n  id: F5686762668\n  name: tumor Position\n  label: Position\n  column_name: tumor_position\n  container_id: \n  search: \'0\'\n  list_show: \'0\'\n  mandatory: \'0\'\n  field_type: text_string\n  params: \'\'\n  sort_order: \n  hide_label: \n  display: \'\'\n  css: \'\'\n  style: \'\'\n  default: \n  lov_type: \'\'\n  lov: \'\'\n  model_path: \n  model_format: \n  description: \'\'\n',NULL,89,153,NULL,NULL,'2012-09-27 04:27:39','2013-03-02 08:58:04','Tumor',276,NULL),(161,'consignment',NULL,'---\nfields:\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F5811419251\n    :name: Diagnosis\n    :label: Diagnosis\n    :column_name: diagnosis\n    :search: \'0\'\n    :list_show: \'0\'\n    :mandatory: \'0\'\n    :field_type: select_string\n    :params: \":default=>\'1\'\"\n    :style: width:200px\n    :lov_type: plain\n    :lov: \"Abdominal mass\\r\\nAbdominal pain\\r\\nAnal pain\\r\\nAnemia work up\\r\\nBowel\n      habit change\\r\\nCT Colonoscopy Positive\\r\\nCarcinomatosis Finding Primary \\r\\nChronic\n      diarrhea\\r\\nConstipation\\r\\nDifficult defecation\\r\\nDyspepsia\\r\\nFOBT Positive\\r\\nGut\n      obstruction\\r\\nInvestigate lesion\\r\\nLGIB\\r\\nLiver metastasis Finding Primary\n      \\r\\nMucous Stool\\r\\nMucous bloody stool\\r\\nPost cancer surgery surveillance\\r\\nPost\n      diverticulitis surviellence\\r\\nPost polypectomy surveillance\\r\\nRaising CEA\\r\\nScreening\\r\\nSurveillence\"\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F5461657304\n    :name: Operation\n    :label: Operation\n    :column_name: operation\n    :search: \'0\'\n    :list_show: \'0\'\n    :mandatory: \'0\'\n    :field_type: check_string\n    :params: \":cols=>2\"\n    :style: width:700px\n    :lov_type: plain\n    :lov: \"Colonoscopy with Biopsy Polypectomy EMR \\r\\nGastroscopy with Biopsy Polypectomy\n      EMR\\r\\nESD\\r\\nColonic stent insertion\"\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F1625050926\n    :name: desc\n    :label: desc\n    :column_name: desc\n    :field_type: html\n    :display: \"<style>\\r\\nlabel{margin-top:10px;margin-bottom:10px}\\r\\n</style>\\r\\nข้าพเจ้าขอแสดงความยินยอมโดยความสมัครใจ\n      ให้คณะแพทย์และบุคลากรทีมสุขภาพของโรง พยาบาลจุฬาลงกรณ์ ที่ได้รับมอบหมายให้มีส่วนร่วมในการดูแล\n      ตรวจ วินิจฉัย และให้การรักษา ข้าพเจ้า ได้ดําเนินการตรวจ วินิจฉัย / รักษา โดยการใช้ยา\n      หรือ เคมีบําบัด หรือ รังสีรักษา หรือ กายภาพบําบัด / รักษาโดยการผ่าตัดเล็กน้อย\n      หรือ ผ่าตัดใหญ่ / ใช้ยาระงับความรู้สึกเฉพาะที่ หรือ ยา ชาฉีดเข้าสันหลัง หรือ\n      การดมยาสลบ \\r\\n<br/>\\r\\n<br/>\\r\\nข้าพเจ้า ได้รับทราบรายละเอียดเกี่ยวกับแผนการตรวจ\n      วินิจฉัยและการรักษาพยาบาลข้างต้น รวมถึง ความเสี่ยง ผลข้างเคียง และ/หรือ ผลที่อาจเกิดขึ้นภายหลังอีกทั้งทางเลือกอื่น\n      ๆ ที่อาจเป็นไปได้อย่าง ชัดเจน จนเป็นที่กระจ่างชัดสําหรับข้าพเจ้าแล้ว และข้าพเจ้าตระหนักดีว่าคณะแพทย์และบุคลากร\n      ทีม สุขภาพ พยาบาล ไม่สามารถรับประกันถึงผลความสําเร็จของการรักษาพยาบาลดังกล่าวได้\n      \\r\\n<br/>\\r\\n<br/>\\r\\nข้าพเจ้าขอแสดงความยินยอมโดยความสมัครใจให้คณะแพทย์และบุคลากรทีมสุขภาพดังกล่าวข้างต้น\n      สามารถกระทําการอื่น ๆ ด้วยเหตุผล แสดงถึงความจําเป็นในการกระทําดังกล่าว อาทิเช่น\n      การดม ยาสลบ การใช้ยาระงับความรู้สึก การให้เลือด และ / หรือ ผลิตภัณฑ์ของเลือด\n      การตรวจวินิจฉัยทาง รังสีวิทยา การตัดชิ้นเนื้อ หรือส่วนของอวัยวะ และการตรวจรักษาหรืผ่าตัดเพิ่มเติม\n      อย่างทันทีทันใด ข้าพเจ้ายินยอมให้แพทย์และบุคลากรทีมสุขภาพดําเนินการได้ หากเป็นการคํานึงถึงชีวิตและประโยชน์\n      ของข้าพเจ้าเป็นสําคัญ\\r\\n<br/>\\r\\n<br/>\\r\\nข้าพเจ้าทราบดีว่า โรงพยาบาลจุฬาลงกรณ์เป็นสถาบันฝึกอบรมแพทย์และพยาบาล\n      ย่อมจะมีบุคลากร ทีมสุขภาพ ประกอบด้วย แพทย์ประจําบ้าน แพทย์ประจําบ้านต่อยอด นิสิตแพทย์\n      นักศึกษาพยาบาล และบุคลากรอื่น ๆ ซึ่งอาจจะเข้ามามีส่วนร่วมดูแล ตรวจ วินิจฉัยและรักษา\\r\\n<br/>\\r\\n<br/>\\r\\nทั้งนี้คณะแพทย์หรือบุคลากรทีมสุขภาพ\n      ได้แจ้งค่าใช้จ่ายโดยประมาณแล้ว แต่หากมีภาวะแทรกซ้อน หรือใช้อุปกรณ์พิเศษเพิ่มเติม\n      ค่าใช้จ่ายจะเพิ่มขึ้น ซึ่งจะต้องแจ้งข้าพเจ้าหรือญาติให้ทราบด้วย\\r\\n<br/>\\r\\n<br/>\\r\\nณ\n      ที่นี้ข้าพเจ้าขอแสดงความ\\r\\n<br/>\\r\\n<br/>\"\n    :style: line-height:1.5em\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F6016585260\n    :name: Agreement\n    :label: \"@\"\n    :column_name: agreement\n    :search: \'0\'\n    :list_show: \'0\'\n    :mandatory: \'0\'\n    :field_type: radio_string\n    :params: \":cols=>2\"\n    :style: width:300px\n    :lov_type: plain\n    :lov: \"ยินยอม\\r\\nไม่ยินยอม\"\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F5575601156\n    :name: desc2\n    :label: desc2\n    :column_name: desc2\n    :field_type: html\n    :display: \"เพื่อรับการรักษาโดยความสมัครใจไว้ ณ ที่นี้\"\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F5108094990\n    :name: Patient Sign\n    :label: \"ลงชื่อผู้ป่วย\"\n    :column_name: patient_sign\n    :search: \'0\'\n    :list_show: \'0\'\n    :mandatory: \'0\'\n    :field_type: extra_signature\n    :style: width:350px\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F9175643708\n    :name: Witness 1\n    :label: \"ลงชื่อพยาน\"\n    :column_name: witness_1\n    :search: \'0\'\n    :list_show: \'0\'\n    :mandatory: \'0\'\n    :field_type: extra_signature\n    :style: width:350px\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F7244472983\n    :name: Patient Name\n    :label: \"ชื่อผู้ป่วย\"\n    :column_name: patient_name\n    :search: \'0\'\n    :list_show: \'0\'\n    :mandatory: \'0\'\n    :field_type: text_string\n    :style: width:170px\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F6022226918\n    :name: Patient Sign Date\n    :label: \"ลงวันที่\"\n    :column_name: patient_sign_date\n    :search: \'0\'\n    :list_show: \'0\'\n    :mandatory: \'0\'\n    :field_type: select_date\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F5995267982\n    :name: Witness Name\n    :label: \"ชื่อพยาน\"\n    :column_name: witness_name\n    :search: \'0\'\n    :list_show: \'0\'\n    :mandatory: \'0