play: TNM\n    :style: padding:2px\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F7608075304\n    :field_type: clear\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F2644167976\n    :name: T\n    :label: T @\n    :column_name: t\n    :list_show: \'1\'\n    :field_type: select_string\n    :lov_type: pair\n    :lov: \"1|Tis\\r\\n2|T0\\r\\n3|T1\\r\\n4|T2\\r\\n5|T3\\r\\n6|T4\\r\\n7|AnyT\\r\\n\"\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F2952326415\n    :name: N\n    :label: N @\n    :column_name: n\n    :list_show: \'1\'\n    :field_type: select_string\n    :lov_type: pair\n    :lov: \"1|N1mi\\r\\n2|N0\\r\\n3|N1\\r\\n4|N2\\r\\n5|N3\\r\\n6|AnyN\\r\\n\"\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F3694597731\n    :name: M\n    :label: M @\n    :column_name: m\n    :list_show: \'1\'\n    :field_type: select_string\n    :lov_type: pair\n    :lov: \"1|M0\\r\\n2|M1\"\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F3973133536\n    :name: stage\n    :label: stage @\n    :column_name: stage\n    :field_type: select_string\n    :lov_type: pair\n    :lov: \"1|0\\r\\n2|IA\\r\\n3|IB\\r\\n4|IIA\\r\\n5|IIB\\r\\n6|IIIA\\r\\n7|IIIB\\r\\n8|IIIC\\r\\n9|IV\\r\\n\"\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F7515297681\n    :field_type: clear\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F1929816409\n    :name: Categories\n    :label: Categories\n    :column_name: categories\n    :field_type: html\n    :display: \"\\r\\n\\r\\n<table width=\\\"710\\\" border=\\\"1\\\">\\r\\n  \\r\\n  <tr>\\r\\n    <td\n      width=\\\"120\\\" bgcolor=\\\"#66FF00\\\">Categories</td>\\r\\n    <td width=\\\"574\\\" bgcolor=\\\"#66FF00\\\">Both\n      patho and clinical staging</td>\\r\\n  </tr>\\r\\n  <tr>\\r\\n    <td>Tx</td>\\r\\n\n      \\   <td>Primary tumor cannot be assessed</td>\\r\\n  </tr>\\r\\n   <tr>\\r\\n    <td>Tis(DCIS)</td>\\r\\n\n      \\   <td>Ductal carcinoma insitu</td>\\r\\n  </tr>\\r\\n   <tr>\\r\\n    <td>Tis(Paget)</td>\\r\\n\n      \\   <td>Paget disease of the nipple NOT associated with invasive carcinoma and/or\n      carcinoma in situ (DCIS) in the underlying breast parenchyma. Carcinomas in\n      the breast parenchyma associated with Paget disease are categorized based on\n      the size and characteristics of the parenchymal disease, although the presence\n      of Paget disease should still be noted.</td>\\r\\n  </tr>\\r\\n   <tr>\\r\\n    <td>T1a</td>\\r\\n\n      \\   <td>Tumor &gt;1 mm but ≤ 5 mm in greatest dimension (round any measurement\n      &gt; 1.0-1.9 mm to 2 mm)</td>\\r\\n  </tr>\\r\\n   <tr>\\r\\n    <td>T1b</td>\\r\\n\n      \\   <td>Tumor &gt;5 mm but ≤ 10 mm in greatest dimension</td>\\r\\n  </tr>\\r\\n\n      \\    <tr>\\r\\n    <td>T1c</td>\\r\\n    <td>Tumor &gt;10 mm but ≤ 20 mm in greatest\n      dimension </td>\\r\\n  </tr>\\r\\n     <tr>\\r\\n    <td>T2</td>\\r\\n    <td>Tumor\n      &gt; 20 mm but ≤ 50 mm in greastest dimension</td>\\r\\n  </tr>\\r\\n     <tr>\\r\\n\n      \\   <td>T3</td>\\r\\n    <td>Tumor &gt; 50 mm greastest dimension </td>\\r\\n  </tr>\\r\\n\n      \\    <tr>\\r\\n    <td>T4a</td>\\r\\n    <td>Extension to chest wall; invasion or\n      adherence to pectoralis muscle in the absence of invasion of chest wall structures\n      does not qualify as T4 </td>\\r\\n  </tr>\\r\\n     <tr>\\r\\n    <td>T4b</td>\\r\\n\n      \\   <td>Ulceration and/or ipsilateral macroscopic satellite nodules and/or edema\n      (including peau d’orange) of the skin that does not meet the criteria for inflammatory\n      carcinoma</td>\\r\\n  </tr>\\r\\n     <tr>\\r\\n    <td>T4c</td>\\r\\n    <td>Both T4a\n      and T4b are present</td>\\r\\n  </tr>\\r\\n     <tr>\\r\\n    <td>T4d</td>\\r\\n    <td>Inflammatory\n      carcinoma</td>\\r\\n  </tr>\\r\\n    \\r\\n     <tr>\\r\\n    <td bgcolor=\\\"#66FF00\\\">Categories</td>\\r\\n\n      \\   <td bgcolor=\\\"#66FF00\\\">Clinical staging</td>\\r\\n  </tr>\\r\\n     <tr>\\r\\n\n      \\   <td>cNx</td>\\r\\n    <td>Regional lymph nodes cannot be assessed</td>\\r\\n\n      \\ </tr>\\r\\n   </tr>\\r\\n     <tr>\\r\\n    <td>cN0</td>\\r\\n    <td>No regional\n      lymph node metastasis</td>\\r\\n  </tr>\\r\\n     <tr>\\r\\n    <td>cN1</td>\\r\\n    <td>Metastases\n      to movable ipsilateral level I, II axillary lymph node(s)</td>\\r\\n  </tr>\\r\\n\n      \\    <tr>\\r\\n    <td>cN1mi</td>\\r\\n    <td>micrometastases (approximately 200\n      cells, larger than 0.2 mm, but none larger than 2.0 mm)</td>\\r\\n  </tr>\\r\\n\n      \\  </tr>\\r\\n     <tr>\\r\\n    <td>cN2a</td>\\r\\n    <td>Metastases in ipsilateral\n      level I, II axillary lymph nodes fixed to one another (matted) or to other structures</td>\\r\\n\n      \\ </tr>\\r\\n     <tr>\\r\\n    <td>cN2b</td>\\r\\n    <td>Metastases only in ipsilateral\n      internal mammary nodes in the absence of axillary lymph node metastases</td>\\r\\n\n      \\ </tr>\\r\\n     <tr>\\r\\n    <td>cN3a</td>\\r\\n    <td>Metastasis in ipsilateral\n      infraclavicular lymph node(s)</td>\\r\\n  </tr>\\r\\n   </tr>\\r\\n     <tr>\\r\\n    <td>cN3b</td>\\r\\n\n      \\   <td>Metastasis in ipsilateral internal mammary lymph node(s) and axillary\n      lymph node(s)</td>\\r\\n  </tr>\\r\\n     <tr>\\r\\n    <td>cN3c</td>\\r\\n    <td>Metastasis\n      in ipsilateral supraclavicular lymph node(s)</td>\\r\\n  </tr>\\r\\n     <tr>\\r\\n\n      \\   <td bgcolor=\\\"#66FF00\\\">Categories</td>\\r\\n    <td bgcolor=\\\"#66FF00\\\">Pathological\n      staging</td>\\r\\n  </tr>\\r\\n    </tr>\\r\\n     <tr>\\r\\n    <td>pNx</td>\\r\\n    <td>Regional\n      lymph nodes cannot be assessed</td>\\r\\n  </tr>\\r\\n    </tr>\\r\\n     <tr>\\r\\n\n      \\   <td>pN0</td>\\r\\n    <td>No regional lymph node metastasis identified or\n      ITCs only</td>\\r\\n  </tr>\\r\\n  </tr>\\r\\n     <tr>\\r\\n    <td>pN0(i+)</td>\\r\\n\n      \\   <td>ITCs only (malignant cells clusters no larger than 0.2 mm) in regional\n      lymph node(s)</td>\\r\\n  </tr>\\r\\n    </tr>\\r\\n     <tr>\\r\\n    <td>pN0(Mol+)</td>\\r\\n\n      \\   <td>Positive molecular findings by reverse transcriptase polymerase chain\n      (RT-PCR); no ITCs detected</td>\\r\\n  </tr>\\r\\n    </tr>\\r\\n     <tr>\\r\\n    <td>pN1mi</td>\\r\\n\n      \\   <td>micrometastases  (200 cells, larger than 0.2 mm, but none larger than\n      2.0 mm)</td>\\r\\n  </tr>\\r\\n    </tr>\\r\\n     <tr>\\r\\n    <td>pN1a</td>\\r\\n    <td>Metastases\n      in 1-3 axillary lymph nodes, at least one metastasis larger than 2.0 mm</td>\\r\\n\n      \\ </tr>\\r\\n  </tr>\\r\\n     <tr>\\r\\n    <td>pN1b</td>\\r\\n    <td>Metastases in\n      ipsilateral internal mammary sentinel nodes, excluding ITCs</td>\\r\\n  </tr>\\r\\n\n      \\   </tr>\\r\\n     <tr>\\r\\n    <td>pN1c</td>\\r\\n    <td>pN1a and pN1b combined.</td>\\r\\n\n      \\ </tr>\\r\\n    </tr>\\r\\n     <tr>\\r\\n    <td>pN2a</td>\\r\\n    <td>Metastases\n      in 4-9 axillary lymph nodes (at least one tumor deposit larger than 2.0 mm)</td>\\r\\n\n      \\ </tr>\\r\\n    </tr>\\r\\n     <tr>\\r\\n    <td>pN2b</td>\\r\\n    <td>Metastases\n      in clinically detected internal mammary lymph nodes with or without microscopic\n      confirmation; with pathologically negative axillary nodes</td>\\r\\n  </tr>\\r\\n\n      \\ </tr>\\r\\n     <tr>\\r\\n    <td>pN3a</td>\\r\\n    <td>Metastases in 10 or more\n      axillary lymph nodes (at least one tumor deposit greater than 2.0 mm); or metastases\n      to the infraclavicular (level lll axillary lymph) nodes</td>\\r\\n  </tr>\\r\\n\n      \\   </tr>\\r\\n     <tr>\\r\\n    <td>pN3b</td>\\r\\n    <td>pN1a or pN2a in the presence\n      of c N2b (positive internal mammary nodes by imagint) or pN2a in the presence\n      of pN1b</td>\\r\\n  </tr>\\r\\n    </tr>\\r\\n     <tr>\\r\\n    <td>pN3c</td>\\r\\n    <td>Metastasis\n      in ipsilateral supraclavicular lymph nodes</td\\r\\n  ></tr>\\r\\n    <tr>\\r\\n    <td\n      bgcolor=\\\"#66FF00\\\">Categories</td>\\r\\n    <td bgcolor=\\\"#66FF00\\\">&nbsp;</td>\\r\\n\n      \\ </tr>\\r\\n    <tr>\\r\\n    <td>M0</td>\\r\\n    <td>No clinical or radiographic\n      evidence of distant metastases</td>\\r\\n  </tr>\\r\\n    <tr>\\r\\n    <td>cM1</td>\\r\\n\n      \\   <td>Distant metastases detected by clinical and radiographic means</td>\\r\\n\n      \\ </tr>\\r\\n    <tr>\\r\\n    <td>pM1</td>\\r\\n    <td>Any histologically proven\n      metastases in distant organs; or if in non-regional nodes, metastases greater\n      than 0.2 mm</td>\\r\\n  </tr>\\r\\n</table>\\r\\n\\r\\n\"\n    :style: padding:2px\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F2876047224\n    :field_type: clear\n',NULL,506,911,NULL,NULL,'2018-10-10 08:20:03','2018-11-15 09:01:58','AJCC8th edition',1455,NULL),(945,'liver_ultrasound_and_fibroscan',NULL,'---\nfields:\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F9228607071\n    :name: Underlying disease\n    :label: Underlying disease\n    :column_name: underlying_disease\n    :field_type: check_string\n    :params: \":cols=>6,:subtree=>true\"\n    :style: width:700px\n    :lov_type: plain\n    :lov: \"HBV\\r\\nHCV\\r\\nFatty Liver\\r\\nHCC\\r\\nCirrhosis\\r\\nOther\"\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F3767955969\n    :name: Underlying disease other\n    :label: Other\n    :column_name: underlying_disease_other\n    :field_type: text_string\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F6594394918\n    :name: US image\n    :label: US Ultrasound\n    :column_name: us_image\n    :field_type: image_camera\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F3645616944\n    :name: US finding\n    :label: US finding\n    :column_name: us_finding\n    :field_type: section\n- !ruby/struct:FIELDCOMPRESSION\n  attributes:\n    :id: F6485269341\n    :name: Liver surface\n    :label: Liver surface\n    :column_name: liver_surface\n    :field_type: radio_string\n    :params: \