achSecretMessage(marker,<%=index%>);\r\n<% end %>\r\n\r\n   \r\n\r\n  }\r\n\r\nfunction attachSecretMessage(marker, number) {\r\n  var message = <%=orgs.to_json.html_safe%>;\r\n  var infowindow = new google.maps.InfoWindow(\r\n      { content:\"<b>\"+message[number][\'name\']+\"</b>\"+\r\n        \"<br/>HbTyping : \"+message[number][\'hbtyping_test\']+\r\n        \"<br/>DNA : \"+message[number][\'dna_test\']+\"<br/>\",\r\n        size: new google.maps.Size(50,50)\r\n      });\r\n  google.maps.event.addListener(marker, \'click\', function() {\r\n    infowindow.open(map,marker);\r\n  });\r\n}\r\n\r\ninitialize() ;\r\n</script>\r\n',NULL,NULL,NULL,'2012-04-23 09:01:13','2012-04-23 09:01:13','',''),(207,'layout',119,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-04-23 09:01:13','2012-04-23 09:01:13',NULL,NULL),(208,'document_name',120,1,'\'Organization\'',NULL,NULL,NULL,'2012-04-23 09:02:06','2012-04-23 09:02:06',NULL,NULL),(211,'index',122,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-04-23 15:03:54','2012-04-23 15:03:54',NULL,NULL),(212,'layout',122,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-04-23 15:03:54','2012-04-23 15:03:54',NULL,NULL),(213,'index',123,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-04-23 15:17:01','2012-04-23 15:17:01',NULL,NULL),(214,'layout',123,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-04-23 15:17:01','2012-04-23 15:17:01',NULL,NULL),(215,'index',124,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-04-23 15:17:09','2012-04-23 15:17:09',NULL,NULL),(216,'layout',124,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-04-23 15:17:09','2012-04-23 15:17:09',NULL,NULL),(217,'index',125,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-04-23 15:24:27','2012-04-23 15:24:27',NULL,NULL),(218,'layout',125,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-04-23 15:24:27','2012-04-23 15:24:27',NULL,NULL),(219,'in