>\r\n<%# render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n<% \r\n    patient,doc = get_has_one_value(\'patient\') \r\n    list = eval(patient.picture)\r\n    atts = doc.project.load_model[:attachment].find(list)\r\n    \r\n    date = record.register_at\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n	t = date-birth_date	\r\n	year = (t/365).to_i\r\n	t%=365\r\n	month = (t/30).to_i\r\n	t%=30\r\n	day = t.to_i\r\n    end\r\n%>\r\n<style>\r\nv{color:#00f}\r\n</style>\r\n<div style=\"border:1px solid #ccc;padding:0px;background:#eef;font-size:1.2em\">\r\n<% if atts\r\nfor i in atts%>\r\n<%= image_tag i.path,:width=>150 ,:class=>\'left\'%> \r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"left\" style=\"padding:20px;float:left\">\r\n<p>\r\n<b> Name : </b><v><%= patient.first_name %> <%= patient.surname %></v>\r\n</p>\r\n<p>\r\n<b> Age : </b><v><%= year%> Years <%=month%> Months <%= day%> Days</v>\r\n</p>\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px:float:left\">\r\n<br/>\r\n<p>\r\n<b> HN : </b><v> <%= patient.hn %></v>\r\n</p>\r\n<p>\r\n<b> à¹€à¸¥à¸‚à¸šà¸±à¸•à¸£à¸›à¸£à¸°à¸Šà¸²à¸Šà¸™ : </b><v><%=patient.public_id%> </v>\r\n</p>\r\n</div>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<br/>\r\n<%# patient.inspect %>\r\n<br/>\r\n<%= link_to \'Edit\', url(\'edit\',:id=>record.id) %> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<hr/>\r\n\r\n<h1>Operative Note</h1>\r\n\r\n<%= tabular :model=>%w(date_note patient_status),:data=>operative_notes do |row,out| \r\n  out<<link_to(\'Show\',url(\'OperativeNote/show\',:id=>row.id)) |\r\n  out<<link_to(\'Edit\',url(\'OperativeNote/edit\',:id=>row.id)) |\r\n  out<<link_to(\'Print\',url(\'OperativeNote/print\',:id=>row.id),:target=>\'_blank\') |\r\n  out<<link_to(\'Delete\',url(\'OperativeNote/destroy\',:id=>row.id))\r\n  out\r\nend\r\n%>\r\n<%# operative_notes.inspect %>\r\n<%= link_to \'Create Operative Note\', url(\'OperativeNote/create\',:colorectal_module=>record.id),:class=>bt_class %>\r\n\r\n',NULL,NULL,NULL,'2012-06-10 04:11:16','2012-06-10 04:11:16','display',''),(361,'create',198,2,'<%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=record.id%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<h1><%=this.table_name.to_s.humanize%></h1><br/>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= form.submit \'Create\' ,:class=>bt_class%> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>',NULL,NULL,NULL,'2012-06-10 04:28:39','2013-07-23 13:48:33','create',''),(362,'create',202,2,'<%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  record.colorectal_module=params[:colorectal_module]\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"../ColorectalModule/show?id=<%=record.colorectal_module%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<h1><%=this.table_name.to_s.humanize%></h1><br/>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= form.submit \'Create\' ,:class=>bt_class ,:style=>\'width:100px\'%> |\r\n<%= link_to \'Back\', url(\'ColorectalModule/show\',:id=>record.colorectal_module) %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>',NULL,NULL,NULL,'2012-06-10 05:30:11','2013-07-23 13:48:33','create',''),(363,'print',189,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%= render :inline=>this.print_partial, :locals=>{:this=>this} %>\r\n<script>\r\nwindow.print()\r\n</script>\r\n<%\r\n    if @current_project.get_setting \'report_server\'\r\n    report_server_path = \"\\\\#{@current_project.get_setting \'report_server\'}?domain=\\\\#{DOMAIN}&solution=\\\\#{@current_solution.name}&application=\\\\#{@current_project.name}&report=\\\\#{this.document_name}&id=\\\\#{params[:id]}\"\r\n    `curl \'\\\\#{report_server_path.html_safe}\'`\r\n    end \r\n%>\r\n<%#report_server_path%>',NULL,NULL,NULL,'2012-06-10 06:31:23','2012-06-10 06:31:23','print',''),(364,'index',203,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-06-10 08:11:56','2012-06-10 08:11:56',NULL,NULL),(365,'layout',203,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-06-10 08:11:56','2012-06-10 08:11:56',NULL,NULL),(366,'document_name',204,1,'\'endoscopist\'',NULL,NULL,NULL,'2012-06-10 08:12:50','2012-06-10 08:12:50',NULL,NULL),(367,'index',205,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-06-10 08:13:59','2012-06-10 08:13:59',NULL,NULL),(368,'layout',205,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-06-10 08:13:59','2012-06-10 08:13:59',NULL,NULL),(369,'document_name',206,1,'\'pathology\'',NULL,NULL,NULL,'2012-06-10 08:25:03','2012-06-10 08:25:03',NULL,NULL),(370,'document_name',207,1,'\'attachment\'',NULL,NULL,NULL,'2012-06-10 13:36:17','2012-06-10 13:36:17',NULL,NULL),(371,'document_name',208,1,'\'operative_note_scope\'',NULL,NULL,NULL,'2012-06-11 08:27:16','2012-06-11 08:27:16',NULL,NULL),(372,'edit',202,2,'<%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"../ColorectalModule/show?id=<%=record.colorectal_module%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n<h1><%=this.table_name.to_s.humanize%></h1><br/>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \'Update\',:class=>bt_class, :style=>\'width:100px\'%> | <%= link_to \'Back\', url(\'ColorectalModule/show\',:id=>record.colorectal_module) %>\r\n<% end %>\r\n<% end %>',NULL,NULL,NULL,'2012-06-13 09:25:50','2013-07-23 13:48:33','edit',''),(373,'form',202,3,'<%\n   fparams = params[:form]\n   model = fparams[:model]\n   f = fparams[:form]\n   @record = fparams[:record]\n   @project =  context[:project]\n   @document =  get_document this.document_name \n\n%>\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\n',NULL,NULL,NULL,'2012-06-18 09:43:28','2012-06-18 09:43:28','form',''),(374,'form',189,3,'<script>\r\nfunction inject(fid){\r\n\r\n\r\n    $(document).ready(function(){\r\n        \r\n        \r\n    $(\'#\'+fid+\'endoscopy_dx\').change(function(){\r\n      var str = $(this).find(\":selected\").val()\r\n \r\n      \r\n      switch (str) {\r\n      case \'Adenomatous polyp\':\r\n          fill(fid,1)\r\n      break;\r\n      case \'Hyperplastic polyp\':\r\n          fill(fid,2)\r\n      break;\r\n      case \'Sessile Serrated Adenoma\':\r\n          fill(fid,3)\r\n      break;\r\n      }\r\n\r\n    });\r\n\r\n    \r\n    \r\n    \r\nfunction fill(fid,number){\r\n    \r\n    \r\n    kudo_type = $(\'#data-\'+fid+\'kudo_type\')\r\n    sano_type = $(\'#data-\'+fid+\'sano_type\')\r\n    nice_classification = $(\'#data-\'+fid+\'nice_classification\')\r\n    jnet_class = $(\'#data-\'+fid+\'jnet_class\')\r\n    \r\n    treatment = $(\'#data-\'+fid+\'treatment\')\r\n    treatment_by = $(\'#data-\'+fid+\'treatment_by\')\r\n    clip = $(\'#data-\'+fid+\'clip\')\r\n    \r\n    \r\n    \r\n    // treatment Total removed\r\n    // treatment_by EMR\r\n    // clip    Done\r\n    \r\n    treatment.val(\'Total removed\')\r\n    treatment_by.val(\'EMR\')\r\n    clip.val(\'Done\')\r\n    \r\n    \r\n    \r\n    // alert(\"\"+fid+\"\"+number+kudo_type.val())\r\n    switch(number){\r\n        case 1:\r\n           kudo_type.val(\'IIIs\')\r\n           sano_type.val(\'II\')\r\n           nice_classification.val(\'II\')\r\n           jnet_class.val(\'2a\')\r\n        break;\r\n        case 2:\r\n           kudo_type.val(\'II\')\r\n           sano_type.val(\'I\')\r\n           nice_classification.val(\'I\')\r\n           jnet_class.val(\'1\')\r\n        break;\r\n        case 3:\r\n           kudo_type.val(\'II\')\r\n           sano_type.val(\'II\')\r\n           nice_classification.val(\'I serrated\')\r\n           jnet_class.val(\'2a\')\r\n        break;\r\n            \r\n    }\r\n    \r\n    update_treatment()\r\n    \r\n    \r\n}\r\n    \r\n    function update_treatment(){\r\n        \r\n        var all_treatment = [];\r\n        \r\n        $(\'.treatment_by\').each(function(){\r\n            \r\n        \r\n        var str = $(this).find(\":selected\").val()\r\n        var s  = \'\'\r\n        if(str==\'Cold polypectomy\'||str==\'Hot polypectomy\')s = \'Polypectomy\'\r\n        if(str==\'Cold biopsy\'||str==\'Hot biopsy\')s = \'Bx\'\r\n        if(str==\'EMR\'||str==\'EMR-C\')s = \'EMR\'\r\n        if(str==\'ESD\'){\r\n            s = \'ESD\'\r\n        \r\n              $(\'#data-project\').val(\'ESD\');\r\n                update_project_rev_func();\r\n            \r\n        }\r\n        if(str==\'APC\')s = \'APC\'\r\n        if(str==\'Coagulation\')s = \'Cauterized bleeding\'\r\n        if(str==\'EPMR\')s = \'EPMR\'\r\n        if(str==\'Precut EMR\')s = \'Precut EMR\'\r\n        \r\n        // alert(s)\r\n           \r\n        all_treatment.push(s);    \r\n            \r\n        })\r\n        \r\n        \r\n         $(\'.tattoo\').each(function(){\r\n            \r\n        \r\n        var str = $(this).find(\":selected\").val()\r\n        var s = \'\'\r\n        if(str==\'Done\')s = \'Tattoo\'\r\n        \r\n        // alert(s)\r\n           \r\n        all_treatment.push(s);    \r\n            \r\n        })\r\n        \r\n        \r\n        \r\n        all_treatment = jQuery.unique(all_treatment);\r\n        // alert(all_treatment)\r\n        \r\n        $(\'#data-procedure\').val(all_treatment.join(\"|\"));\r\n        \r\n        update_procedure_rev_func();\r\n        \r\n        \r\n    }\r\n    \r\n    \r\n    proc =  $(\'#data-\'+fid+\'treatment_by\');\r\n    proc.addClass(\'treatment_by\');\r\n    proc.change(function(){\r\n        update_treatment()   \r\n    });\r\n    \r\n    \r\n    proc =  $(\'#data-\'+fid+\'tattoo\');\r\n    proc.addClass(\'tattoo\');\r\n\r\n\r\n\r\n    \r\n    $(\'#data-\'+fid+\'tattoo\').change(function(){\r\n           update_treatment()   \r\n    });\r\n    \r\n    });\r\n    \r\n}\r\n\r\n\r\n</script>\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   \r\n  \r\n%>\r\n<div id=\'prescope\' >Loading..PreScope information</div>\r\n<script>\r\n\r\n<%\r\n\r\n url = \"../PreScope/pre_scope_detail?id=\\\\#{params[:id]}\"\r\n url = \"../PreScope/pre_scope_detail?parent_id=\\\\#{params[:parent_id]}\" if params[:parent_id]\r\n \r\n%>\r\n\r\n$.ajax({\r\n  url: \"<%=url%>\",\r\n  context: document.body\r\n}).done(function(data) { \r\n  $(\'#prescope\').html(data);\r\n <% unless params[:id] %>\r\n $(\'#data-bowel_preparation\').val(pre_scope[\"bowel_preparation\"]);\r\n $(\'#data-additional_bowel_preparation\').val(pre_scope[\"add_bowel_prep\"]);\r\n\r\n $(\'#data-bowel_cc\').val(pre_scope[\"bowelprep_cc\"]);\r\n $(\'#data-bowel_other\').val(pre_scope[\"bowel_other_note\"]);\r\n $(\'#data-add_bowel_prep_cc\').val(pre_scope[\"add_bowel_prep_cc\"]);\r\n $(\'#data-add_bowel_prep_other\').val(pre_scope[\"add_bowel_other\"]);\r\n \r\n <% end %> \r\n\r\n});\r\n</script>\r\n\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n\r\n$(\'#data-procedure\').bind(\"change\", function (){\r\n    \r\n    v = $(this).val()\r\n    if(v.indexOf(\'ESD\')>=0){\r\n        $(\'#data-project\').val(\'ESD\');\r\n         update_project_rev_func();\r\n    }\r\n    if(v.indexOf(\'Stent\')>=0){\r\n        $(\'#data-project\').val(\'Stent\');\r\n         update_project_rev_func();\r\n    }\r\n    if(v.indexOf(\'ESD\')>=0 && v.indexOf(\'Stent\')>=0){\r\n        $(\'#data-project\').val(\'Stent\');\r\n         update_project_rev_func();\r\n    }\r\n    \r\n    \r\n    \r\n     \r\n    \r\n});\r\n\r\n\r\nsedative = [\'dormicum\',\'pethidine\',\'diprivan\',\'valium\',\'buscopan\',\'plasil\',\'fentanyl\',\'other\']\r\nfunction check_sedative(ele){\r\n   check = ele.prop(\"checked\");\r\n   id = ele.prop(\"id\");\r\n   t = id.split(\'-\')[1];\r\n   if(check)\r\n   $(\".\"+t+\'\').css(\"display\",\"block\");\r\n   else\r\n   $(\".\"+t+\'\').css(\"display\",\"none\");\r\n}\r\n\r\nfor(i=0;i<sedative.length;i++){\r\n t = sedative[i];  \r\n ele = $(\'#data-\'+t);\r\nele.change(function(){\r\n    check_sedative($(this));\r\n});\r\n check_sedative(ele);\r\n}\r\n//$(\'#data-dormicum_mg\').val(323)\r\n//$(\'#data-dormicum_mg\').prop(\'disabled\', true);\r\n//$(\'#data-dormicum_num\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_mg\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_num\').prop(\'disabled\', true);\r\n\r\nvar scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\nfunction refresh(ele){\r\n    for(i=0;i<scope_list.length;i++){\r\n      $(\".\"+scope_list[i]).css(\"display\",\"none\");\r\n   }\r\n    index = $(ele).prop(\"selectedIndex\");\r\n   for(i=0;i<index;i++){\r\n       $(\".\"+scope_list[i]).css(\"display\",\"block\");\r\n   }\r\n}\r\n\r\nrefresh($(\'#data-scope\'));\r\n\r\n$(\"#data-scope\").change(function(){\r\nrefresh(this);\r\n});\r\n\r\n\r\n$(\".diag\").change(function(){\r\n    \r\n   e = $(\"#data-\"+this.id).val();\r\n   p = $(\"#data-patient_status\");\r\n   if(e==\"1\"){\r\n     $.sticky(\"Select Abnormal\", {autoclose : 5000, position: \"top-right\" });\r\n     p.val(\"Abnormal\");    \r\n   }\r\n});\r\n\r\n\r\n  \r\n\r\n$(\'#data-diagnosis_group\').bind(\"change\", function() {\r\n       v = $(this).val() \r\n    //   alert(v)\r\n       if(v!=\'Normal\'){\r\n           $(this).val(v.replace(\'Normal|\',\'\')) \r\n          $(\'#update_diagnosis_group_item_0\').attr(\'checked\', false);\r\n       }\r\n          v = $(this).val() \r\n        var $cbx = $(\"#data-diagnosis_note\").data(\"kendoComboBox\")\r\n        $cbx.value(v.replace(/\\\\|/g,\',\'))\r\n        if(v.indexOf(\'Serrated\')>=0){\r\n            $(\'#data-project\').val(\'Serrated polyp\');\r\n            update_project_rev_func();\r\n        }\r\n\r\n    //   $(\'#data-diagnosis_note\').kendoComboBox().value(\'oiwjfoiwejfoijwef\');\r\n       \r\n     \r\n     \r\n \r\n });\r\n \r\n\r\n</script>',NULL,NULL,NULL,'2012-06-18 09:43:59','2012-06-18 09:43:59','form',''),(375,'list',198,3,'<%\r\n \r\n   records = []\r\n   n = 10 \r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   query=\'\'\r\n   if params[:search]\r\n\r\n        query = params[:search][:query]\r\n          keys = []\r\n    \r\n     \r\n        dates = {}\r\n        if params[:search][:from_date] and params[:search][:from_date]!=\'\' \r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        relation = Fields::RelationOne.new @document, @document.find_by_column_name(\'patient\'),nil\r\n        patient_model = relation.related_table\r\n        relation.related_fields.each_with_index do |f,index| \r\n    	    keys <<{f.to_sym=>Regexp.new(query)}\r\n        end\r\n        ps = patient_model.all({\'$or\'=>keys}.merge!(dates))\r\n   \r\n        model = get_model(this.table_name)\r\n        records = []\r\n        for i in ps\r\n            records+= model.where(:patient=>i.id).all\r\n        end\r\n        count = records.size\r\n    else\r\n        from_date = nil\r\n        to_date = nil  \r\n        page = 0 \r\n        page = params[:page].to_i if params[:page]\r\n        model = get_model(this.table_name)\r\n        count = model.count\r\n        records = model.all(:limit=>n,:order=>\'created_at desc\',:offset=>page*n)\r\n    end\r\n   \r\n%>\r\n\r\n<h1>List of colonoscopy patient</h1>\r\n<br/>\r\n<%= form_for :search, :action=>\'.\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n		value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n	});\r\n    $(\"#to-date\").kendoDatePicker({\r\n    	value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n</script>\r\n\r\n<span class=\"right\">\r\n<%# f.submit \"Reset\", :type => \"reset\",:class=> bt_class if params[:search] %>\r\n<%= f.text_field :query ,:class=>tb_class,:value=>query %>\r\n<%= f.submit \'Search\',:class=>bt_class %> \r\n\r\n<%= link_to \"Show All\", url(\"index\"),:class=>bt_class if params[:search] %>\r\n<%= link_to \"New record\", url(\"create\"),:class=>bt_class %>\r\n</span>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%\r\n    patients = get_has_one_value_from_collection \'patient\', records\r\n    models = get_model\r\n%>\r\n\r\n\r\n<%= tabular :model=>%w{hn patient public_id operative_date}, :data=>records do |i,out|\r\n#fields.each_with_index do |f,index|\r\n#out[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n#end\r\n @record = i\r\n \r\n patient = patients[i.id]\r\n if patient\r\n out[0]=patient.hn\r\n out[1]=\"\\\\#{patient.first_name} \\\\#{patient.surname}\"\r\n out[2]=patient.public_id\r\n end\r\n\r\n opt_note = models[:operative_note].where(:colorectal_module=>i.id).first\r\n out[3]= opt_note.date_note if opt_note\r\n\r\n\r\nout<<link_to(\'Show\', url(\"show\",:id=>i.id))\r\nout<<link_to(\'Delete\', url(\"destroy\",:id=>i.id))\r\nout\r\nend\r\n%>\r\n\r\n<% (count.to_f/n).ceil.times do |i| %>\r\n<%=link_to(i+1, url(\"index\",:page=>i),:class=>bt_class)%>&nbsp;\r\n<% end %>\r\n\r\n<br/>\r\n<br/>\r\n<p>\r\n<%= link_to \"New record\", url(\"create\"),:class=>bt_class %> |\r\n<%= link_to \"Reset\", url(\"reset\") %>\r\n</p>',NULL,NULL,NULL,'2012-06-18 11:52:14','2012-06-18 11:52:14','list',''),(376,'display',202,3,'<%\r\n   model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  @show=true\r\n%>\r\n<h1><%=this.table_name.to_s.humanize%></h1><br/>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n<br/>\r\n<%= link_to \'Edit\', url(\'edit\',:id=>record.id),:class=>bt_class %> | <%= link_to \'Back\', url(\'ColorectalModule/show\',:id=>record.colorectal_module) %>',NULL,NULL,NULL,'2012-06-18 12:06:19','2012-06-18 12:06:19','display',''),(377,'display2',189,3,'<%\r\n   model = get_model(this.table_name