ns.to_json%>\r\n            <script>\r\n                    $(\"#chart-<%=m.id%>\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"<%=m.title%> Patients by Month\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: [{\r\n                            name: \"Patients\",\r\n                            data: <%=data.to_json.html_safe %>\r\n                        }],\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                \r\n\r\n             \r\n            </script>                 \r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        System Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<table class=\"table table-striped table-bordered table-condensed\">\r\n<thead>\r\n<tr>\r\n<th>Title</th>\r\n<th>Value</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Disk Space</td>\r\n<%\r\n   size = patient_model.collection.db.stats[\'storageSize\']\r\n   unit = \'B\'\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'KB\'\r\n   size /= 1000\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'MB\'\r\n   size /= 1000\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'GB\'\r\n   size /= 1000\r\n   \r\n   end\r\n   end\r\n   end\r\n   \r\n   \r\n\r\n%>\r\n\r\n<td><%=format(\'%.2f\',size)%> <%=unit%></td>\r\n</tr>\r\n<tr>\r\n<td>Total Patient</td>\r\n<td><%= (model[:patient]).count %></td>\r\n</tr>\r\n<tr>\r\n<td>Total Module</td>\r\n<td><%= modules.size %></td>\r\n</tr>\r\n<tr>\r\n\r\n</tr>\r\n<tr>\r\n<td>Total Record</td>\r\n<td><%= (model[:patient_module]).count %></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Support\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <%= link_to \'Inventory System\', \'../../inventory/Home/index\',:class=>\'btn\' %>\r\n   \r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2012-07-21 08:52:06','2012-07-21 08:52:06','',''),(385,'layout',213,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-07-21 08:52:06','2012-07-21 08:52:06',NULL,NULL),(386,'document_name',214,1,'\'patient\'',NULL,NULL,NULL,'2012-07-21 08:53:03','2012-07-21 08:53:03',NULL,NULL),(387,'document_name',215,1,'\'patient_module\'',NULL,NULL,NULL,'2012-07-21 09:02:24','2012-07-21 09:02:24',NULL,NULL),(390,'document_name',217,1,'\'endoscopist\'',NULL,NULL,NULL,'2012-07-21 15:15:43','2012-07-21 15:15:43',NULL,NULL),(411,'index',218,2,'<h1>ESM Updater</h1><br>\r\n\r\n<%= form_for :form,:url=>\'index\' ,:confirm=>\'Are you sure?\' do |f| %>\r\n<p>\r\nEsm site\'s URL : <%= f.text_field :url, :value=>\'http://emr-life.com\' %>\r\n</p>\r\n<p>\r\nCommand : <%= f.select :command, %w{review_from migrate_to migrate_from } %> ESM Site\r\n</p>\r\n<%= f.submit :submit ,:confirm=>\'Are you sure?\'%>\r\n<% end %>\r\n\r\n<% if request.post? \r\nurl = params[:form][:url]+\"/esm/system/updater/Home/export_project\"\r\ncmd = `curl \\\\#{url}` \r\n\r\nrequire \"rexml/document\"\r\n\r\npath = \'ccccc\'\r\nREXML::Document.new(cmd).elements.each(\"project\") do |element| \r\n\r\nelement.elements.each(\"package\") { |e| path = e.text }\r\nproject = Project.find_by_package path\r\nif params[:form][:command]==\'migrate_from\'\r\nproject.import element\r\nend\r\nend\r\n\r\n%>\r\nReview update : <%=  path %>\r\n<hr/>\r\n<%= cmd %>\r\n<hr/>\r\n<%=params.inspect %>\r\n\r\n\r\n\r\n<% end %>',NULL,NULL,NULL,'2012-07-22 10:14:22','2012-07-22 10:14:22','',''),(412,'layout',218,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-07-22 10:14:22','2012-07-22 10:14:22',NULL,NULL),(413,'export_project',218,3,' <%\r\n package = \"system.util\" \r\n package = params[:path] if params[:path]\r\n project = Project.find_by_package package\r\n\r\n%>\r\n<%= project.to_xml({:include=>{:services=>{:include=>{:operations=>{:include=>{:script_template=>{:only=>[:name]}},\r\n:except=>[:id,:service_id,:template_id]}},\r\n:except=>[:user_id,:project_id,:id]}}}).html_safe if project %> \r\n',NULL,NULL,NULL,'2012-07-22 10:16:49','2012-07-22 10:16:49','export_project','*'),(415,'document_name',219,1,'\'module\'',NULL,NULL,NULL,'2012-07-26 12:11:19','2012-07-26 12:11:19',NULL,NULL),(418,'document_name',221,1,'\'operative_note\'',NULL,NULL,NULL,'2012-07-26 12:12:37','2012-07-26 12:12:37',NULL,NULL),(419,'document_name',222,1,'\'nurse_record\'',NULL,NULL,NULL,'2012-07-26 12:15:40','2012-07-26 12:15:40',NULL,NULL),(425,'index',224,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-07-27 15:56:43','2012-07-27 15:56:43',NULL,NULL),(426,'layout',224,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-07-27 15:56:43','2012-07-27 15:56:43',NULL,NULL),(427,'index',225,2,'<style>\r\n\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n\r\n    [Widget Styling]\r\n\r\n    Project:    	Slate Admin 2.0\r\n	Version:		1.0\r\n	Last change:	06/27/2012\r\n	Assigned to:	Rod Howard (rh)\r\n\r\n\r\n[Table of contents]\r\n\r\n	1. Widget\r\n	2. Header Actions\r\n	3. Shared Styles\r\n	4. Tables\r\n	5. Toolbar\r\n	6. Tabs\r\n	7. Accordion\r\n	8. Form\r\n	9. Mini Calendar\r\n	10. Full Calendar\r\n	11. Miscellaneous\r\n\r\n-------------------------------------------------------------------*/\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n[*. Widget]\r\n*/\r\n\r\n.widget {	\r\n	position: relative;\r\n	clear: both;\r\n	\r\n	width: auto;\r\n	\r\n	margin-bottom: 2em;\r\n}\r\n	\r\n	.widget-header {		\r\n		position: relative;\r\n		\r\n		height: 40px;\r\n		line-height: 40px;\r\n		\r\n		background: #E9E9E9;\r\n		background:-moz-linear-gradient(top, #FAFAFA 0%, #E9E9E9 100%); /* FF3.6+ */\r\n		background:-webkit-gradient(linear, left top, left bottom, color-stop(0%,#FAFAFA), color-stop(100%,#E9E9E9)); /* Chrome,Safari4+ */\r\n		background:-webkit-linear-gradient(top, #FAFAFA 0%,#E9E9E9 100%); /* Chrome10+,Safari5.1+ */\r\n		background:-o-linear-gradient(top, #FAFAFA 0%,#E9E9E9 100%); /* Opera11.10+ */\r\n		background:-ms-linear-gradient(top, #FAFAFA 0%,#E9E9E9 100%); /* IE10+ */\r\n		background:linear-gradient(top, #FAFAFA 0%,#E9E9E9 100%); /* W3C */\r\n		filter: progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#FAFAFA\', endColorstr=\'#E9E9E9\');\r\n		-ms-filter: \"progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#FAFAFA\', endColorstr=\'#E9E9E9\')\";		\r\n		\r\n		border: 1px solid #CCC;\r\n		\r\n		-webkit-border-top-left-radius: 4px;\r\n		-webkit-border-top-right-radius: 4px;\r\n		-moz-border-radius-topleft: 4px;\r\n		-moz-border-radius-topright: 4px;\r\n		border-top-left-radius: 4px;\r\n		border-top-right-radius: 4px;\r\n		\r\n		-webkit-background-clip: padding-box;\r\n		\r\n		-moz-box-shadow: inset 0 1px 0 rgba(255,255,255,1);\r\n		-webkit-box-shadow: inset 0 1px 0 rgba(255,255,255,1);\r\n		box-shadow: inset 0 1px 0 rgba(255,255,255,1);\r\n	}	\r\n	\r\n		.widget-header h3 {\r\n			\r\n			position: relative;\r\n			top: 10px;\r\n			left: 10px;\r\n			\r\n			float: left;\r\n			\r\n			display: inline-block;\r\n			margin-right: 3em;\r\n			\r\n			font-size: 13px;\r\n			font-weight: 600;\r\n			color: #555;\r\n			line-height: 18px;\r\n			\r\n			text-shadow: 1px 1px 2px rgba(255,255,255,1);\r\n		}\r\n	\r\n			.widget-header h3 [class^=\"icon-\"], .widget-header h3 [class*=\" icon-\"] {\r\n				position: relative;\r\n				top: 2px;\r\n				\r\n				padding-right: .5em;\r\n				\r\n				font-size: 16px;	\r\n			}\r\n\r\n.widget-content {\r\n	padding: 20px 15px 15px;\r\n	\r\n	background: #FFF;\r\n	\r\n	\r\n	border: 1px solid #CCC;\r\n	\r\n	-moz-border-radius: 5px;\r\n	-webkit-border-radius: 5px;\r\n	border-radius: 5px;\r\n}\r\n\r\n\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n[*. Header Actions]\r\n*/	\r\n\r\n.widget-header .widget-actions {\r\n	float: right; \r\n	\r\n	display: inline-block;\r\n	vertical-align: middle;\r\n	\r\n	height: 40px; \r\n	margin-right: .85em;\r\n	\r\n	line-height: 40px; \r\n}\r\n\r\n.widget-header .widget-actions .btn-group .btn,\r\n.widget-header .widget-actions  > .btn {\r\n	float: none;\r\n	\r\n	display: inline-block;\r\n}\r\n\r\n.widget-header .widget-actions .btn-group .btn+.btn {\r\n	margin-left: -4px;\r\n}\r\n\r\n\r\n.widget-header .widget-actions .dropdown-menu {\r\n	top: 93%;\r\n	\r\n	left: auto;\r\n	right: 0;	\r\n}\r\n\r\n\r\n.widget-header .widget-actions input {\r\n	position: relative;\r\n	top: 4px;\r\n	\r\n	padding: 3px;\r\n}\r\n\r\n\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n[*. Shared Styles]\r\n*/\r\n\r\n.widget .widget-tabs,\r\n.widget .widget-toolbar,\r\n.widget.widget-accordion .accordion-heading {\r\n	background: #DADADA;\r\n		background:-moz-linear-gradient(top, #EEEEEE 0%, #DADADA 100%); /* FF3.6+ */\r\n		background:-webkit-gradient(linear, left top, left bottom, color-stop(0%,#EEEEEE), color-stop(100%,#DADADA)); /* Chrome,Safari4+ */\r\n		background:-webkit-linear-gradient(top, #EEEEEE 0%,#DADADA 100%); /* Chrome10+,Safari5.1+ */\r\n		background:-o-linear-gradient(top, #EEEEEE 0%,#DADADA 100%); /* Opera11.10+ */\r\n		background:-ms-linear-gradient(top, #EEEEEE 0%,#DADADA 100%); /* IE10+ */\r\n		background:linear-gradient(top, #EEEEEE 0%,#DADADA 100%); /* W3C */\r\n		filter: progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#EEEEEE\', endColorstr=\'#DADADA\');\r\n		-ms-filter: \"progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#EEEEEE\', endColorstr=\'#DADADA\')\";		\r\n		\r\n		border: 1px solid #CCC;\r\n		\r\n		border-top: none;\r\n		border-bottom: none;\r\n		\r\n	\r\n	\r\n		-moz-box-shadow: inset 0 1px 0 rgba(255,255,255,1);\r\n		-webkit-box-shadow: inset 0 1px 0 rgba(255,255,255,1);\r\n		box-shadow: inset 0 1px 0 rgba(255,255,255,1);\r\n}\r\n\r\n.widget-header+.widget-content,\r\n.widget-tabs+.widget-content,\r\n.widget-toolbar+.widget-content {\r\n	border-top: none;\r\n	\r\n	-webkit-border-top-left-radius: 0;\r\n	-webkit-border-top-right-radius: 0;\r\n	-moz-border-radius-topleft: 0;\r\n	-moz-border-radius-topright: 0;\r\n	border-top-left-radius: 0;\r\n	border-top-right-radius: 0;\r\n}\r\n\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n[*. Tables]\r\n*/\r\n\r\n.widget-table .widget-content {\r\n	padding: 0;\r\n}\r\n\r\n.widget-table .table-bordered {\r\n	border-top: none;\r\n	border-right: none;	\r\n	border-bottom: none;\r\n	\r\n	margin-bottom: 0;\r\n	\r\n}\r\n\r\n.widget-table .widget-header+.widget-content .table-bordered {\r\n\r\n	-moz-border-radius: 0 !important;\r\n	-webkit-border-radius: 0 !important;\r\n	border-radius: 0 !important;\r\n\r\n}\r\n\r\n.widget-table .table-bordered tr td:first-child,\r\n.widget-table .table-bordered tr th:first-child {\r\n	border-left: none;\r\n}\r\n\r\n.widget-table tbody tr:first-child td {\r\n	border-top-color: #CCC;\r\n}\r\n\r\n.widget-table tbody td {\r\n	border-left: 1px solid #FFF;\r\n	border-right: 1px solid #DDD;\r\n}\r\n\r\n.widget-table thead tr th:last-child {\r\n	border-right: none;\r\n}\r\n\r\n.widget-table tbody tr td:last-child {\r\n	border-right: none;\r\n}\r\n\r\n.widget-table .widget-header+.widget-content thead th {\r\n	\r\n	-moz-border-radius: 0 !important;\r\n	-webkit-border-radius: 0 !important;\r\n	border-radius: 0 !important;\r\n	\r\n}\r\n\r\n.widget-table .table-highlight thead:first-child tr:first-child th {\r\nborder-top: 1px solid #292C32;\r\n}\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n[*. Toolbar]\r\n*/\r\n\r\n.widget .widget-toolbar {\r\n	padding: .75em 1em;\r\n	\r\n	border-top: 1px solid #CCC;\r\n	\r\n	border-bottom: 1px solid #CCC;\r\n	\r\n	-webkit-border-top-left-radius: 5px;\r\n	-webkit-border-top-right-radius: 5px;\r\n	-moz-border-radius-topleft: 5px;\r\n	-moz-border-radius-topright: 5px;\r\n	border-top-left-radius: 5px;\r\n	border-top-right-radius: 5px;\r\n}\r\n\r\n.widget .widget-header+.widget-toolbar {\r\n	border-top: none;\r\n	\r\n	-webkit-border-radius: 0;\r\n	-moz-border-radius: 0;\r\n	border-radius: 0;\r\n}\r\n\r\n.widget .widget-toolbar .btn,\r\n.widget .widget-toolbar .btn-group {\r\n	float: none;\r\n	\r\n	display: inline-block;\r\n}\r\n\r\n.widget .widget-toolbar .btn {\r\n	margin-right: .75em;\r\n}\r\n\r\n.widget .widget-toolbar .btn-group {\r\n	margin-right: .75em;\r\n}\r\n\r\n.widget .widget-toolbar .btn-group .btn {\r\n	margin-right: -3px;\r\n}\r\n\r\n\r\n\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n[*. Tabs]\r\n*/\r\n\r\n.widget .widget-tabs {\r\n	border-top: 1px solid #CCC;\r\n	\r\n	-webkit-border-top-left-radius: 5px;\r\n	-webkit-border-top-right-radius: 5px;\r\n	-moz-border-radius-topleft: 5px;\r\n	-moz-border-radius-topright: 5px;\r\n	border-top-left-radius: 5px;\r\n	border-top-right-radius: 5px;\r\n}\r\n\r\n.widget .widget-header+.widget-tabs {\r\n	\r\n	border-top: none;\r\n	\r\n	-moz-border-radius: 0;\r\n	-webkit-border-radius: 0;\r\n	border-radius: 0;\r\n}\r\n\r\n.widget .widget-tabs .nav-tabs {\r\n	padding: 1em 0 0 1em;\r\n	margin: 0;\r\n	\r\n	border-bottom-color: #CCC;\r\n	\r\n}\r\n\r\n.widget .widget-tabs .nav-tabs > li > a {\r\n	font-size: 14px;\r\n	color: #333;\r\n}\r\n\r\n.widget .widget-tabs .nav-tabs > .active > a, .widget .widget-tabs .nav-tabs > .active > a:hover {\r\n	border-color: #CCC;\r\n	\r\n	border-bottom-color: transparent;\r\n}\r\n\r\n\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n[*. Accordion]\r\n*/\r\n\r\n.widget.widget-accordion .widget-content {\r\n	padding: 0;\r\n}\r\n\r\n.widget.widget-accordion .accordion {\r\n	margin-bottom: 0;\r\n}\r\n\r\n.widget.widget-accordion .accordion-group {\r\n	\r\n	margin-top: -1px;\r\n	margin-bottom: 0;\r\n	\r\n	border-color: #bbb;\r\n	\r\n	border-bottom: none;\r\n	border-right: none;\r\n	border-left: none;\r\n	\r\n	-moz-border-radius: 0;\r\n	-webkit-border-radius: 0;\r\n	border-radius: 0;\r\n	\r\n}\r\n\r\n.widget.widget-accordion .accordion-heading {\r\n	position: relative;\r\n	\r\n	border: none;\r\n	\r\n	border-bottom: 1px solid #BBB;\r\n}\r\n\r\n.widget.widget-accordion .accordion-toggle {\r\n	color: #263849;\r\n	\r\n	font-size: 13px;\r\n	font-weight: 600;\r\n}\r\n\r\n.widget.widget-accordion .accordion-toggle:hover {\r\n	\r\n	text-decoration: none;\r\n}\r\n\r\n\r\n.widget.widget-accordion .toggle-icon {\r\n	position: absolute;\r\n	top: 9px;\r\n	right: 1em;	\r\n\r\n	color: #888;\r\n	\r\n	font-size: 15px;\r\n}\r\n\r\n\r\n.widget.widget-accordion .accordion-group.open .accordion-toggle {\r\n	text-shadow: 0px -1px 0px #263849; \r\n	color: #ffffff; \r\n	background-color: #263849; \r\n	background-image: -moz-linear-gradient(top, #3C4C5B, #263849); \r\n	background-image: -ms-linear-gradient(top, #3C4C5B, #263849); \r\n	background-image: -webkit-gradient(linear, 0 0, 0 100%, from(#3C4C5B), to(#263849)); \r\n	background-image: -webkit-linear-gradient(top, #3C4C5B, #263849); \r\n	background-image: -o-linear-gradient(top, #3C4C5B, #263849); \r\n	background-image: linear-gradient(top, #3C4C5B, #263849); \r\n	filter: progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#3C4C5B\', endColorstr=\'#263849\', GradientType=0); \r\n	border-color: #684682 #263849 #263849 #684682; \r\n	border-color: rgba(0, 0, 0, 0.25) rgba(0, 0, 0, 0.35) rgba(0, 0, 0, 0.35) rgba(0, 0, 0, 0.25);\r\n	\r\n	color: #FFF;\r\n	\r\n	border-top: 1px solid #16222C;\r\n	\r\n	-moz-box-shadow: inset 0 1px 0 rgba(255,255,255,.25);\r\n	-webkit-box-shadow: inset 0 1px 0 rgba(255,255,255,.25);\r\n	box-shadow: inset 0 1px 0 rgba(255,255,255,.25);\r\n		\r\n	text-shadow: 1px 1px 2px rgba(0,0,0,.4);\r\n}\r\n\r\n.widget.widget-accordion .accordion-group.open .toggle-icon {\r\n	color: #F90;\r\n}\r\n\r\n.widget.widget-accordion .accordion-group.open .accordion-heading {	\r\n	border-bottom: 1px solid #16222C !important;\r\n}\r\n\r\n.widget.widget-accordion .accordion-group:last-child .accordion-heading {\r\n	border-bottom: none;\r\n}\r\n\r\n\r\n\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n[*. Form]\r\n*/\r\n\r\n.widget-form .form,\r\n.widget-form .form-horizontal {\r\n	margin-top: .5em;\r\n	margin-bottom: 0;\r\n}\r\n\r\n.widget-form .control-group {\r\n	padding: 15px 25px;\r\n	margin-bottom: 0;\r\n	\r\n	border-top: 1px dotted #CCC;\r\n}\r\n\r\n.widget-form .control-group:first-child {\r\n	border-top: none;\r\n}\r\n\r\n.widget-form .form-actions {\r\n	margin-bottom: 0;\r\n	\r\n	-webkit-border-bottom-right-radius: 5px;\r\n	-webkit-border-bottom-left-radius: 5px;\r\n	-moz-border-radius-bottomright: 5px;\r\n	-moz-border-radius-bottomleft: 5px;\r\n	border-bottom-right-radius: 5px;\r\n	border-bottom-left-radius: 5px;\r\n}\r\n\r\n.widget-form .widget-content {\r\n	padding: 0;\r\n}\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n[*. Data Table]\r\n*/\r\n\r\n.widget-table .dataTables_wrapper .table {\r\n	\r\n	border-top: 1px solid #DDD;\r\n	border-bottom: 1px solid #DDD;\r\n	\r\n	border-radius: 0;\r\n}\r\n\r\n.widget-table .dataTables_wrapper .row {\r\n	margin: 1em 0;\r\n}\r\n\r\n.widget-table .dataTables_wrapper .row .span6 {\r\n	padding: 0 10px;\r\n	\r\n	-moz-box-sizing: border-box;\r\n	-webkit-box-sizing: border-box;\r\n	box-sizing: border-box;\r\n}\r\n\r\n.widget-table .dataTables_wrapper .row label {\r\n	margin-bottom: 0;\r\n}\r\n\r\n.widget-table .dataTables_scroll .dataTables_scrollBody .table {\r\n	border-bottom: none;\r\n	border-top: none;\r\n}\r\n\r\n.widget-table .dataTables_scrollHead .dataTables_scrollHeadInner .table {\r\n	border-bottom: none;\r\n}\r\n\r\n\r\n\r\n\r\n\r\n/*------------------------------------------------------------------\r\n[*. Mini Calendar]\r\n*/\r\n\r\n.widget-minicalendar .widget-content {\r\n	padding: 0;\r\n}\r\n\r\n.widget-minicalendar .ui-datepicker {\r\n	width: 100%;\r\n	\r\n	border: none;\r\n	\r\n	-moz-box-shadow: none;\r\n	-webkit-box-shadow: none;\r\n	box-shadow: none;\r\n}\r\n\r\n\r\n.widget-minicalendar .ui-datepicker {\r\n	padding: 0;\r\n}\r\n\r\n.widget-minicalendar .ui-datepicker .ui-datepicker-header { \r\n	position:relative; \r\n	padding: 8px 0 7px 0; \r\n	border:0px; \r\n	font-weight: bold; \r\n	font-size: 11px; \r\n	width: 100%; \r\n	color: #636363; \r\n	text-shadow: 0 1px white;\r\n	border-bottom: 1px solid #CCC; \r\n	border-radius: 0!important; \r\n	box-shadow: 0 1px 0 #fff; \r\n	-webkit-box-shadow: 0 1px 0 #fff; \r\n	-moz-box-shadow: 0 1px 0 #fff; \r\n	background: #DADADA;\r\n		background:-moz-linear-gradient(top, #EEEEEE 0%, #DADADA 100%); /* FF3.6+ */\r\n		background:-webkit-gradient(linear, left top, left bottom, color-stop(0%,#EEEEEE), color-stop(100%,#DADADA)); /* Chrome,Safari4+ */\r\n		background:-webkit-linear-gradient(top, #EEEEEE 0%,#DADADA 100%); /* Chrome10+,Safari5.1+ */\r\n		background:-o-linear-gradient(top, #EEEEEE 0%,#DADADA 100%); /* Opera11.10+ */\r\n		background:-ms-linear-gradient(top, #EEEEEE 0%,#DADADA 100%); /* IE10+ */\r\n		background:linear