lan Container --*/\r\n\r\n.plan-container {\r\n    position: relative;\r\n    float: left;    \r\n    \r\n    margin-bottom: 2em;\r\n}\r\n\r\n/*-- Plan --*/\r\n\r\n.plan {\r\n    margin-right: 6px;\r\n    \r\n    border-radius: 4px;\r\n}\r\n\r\n\r\n/*-- Plan Header --*/\r\n\r\n.plan-header {\r\n    text-align: center;\r\n    color: #FFF;\r\n    \r\n    background-color: #686868;\r\n    \r\n    -webkit-border-top-left-radius: 4px;\r\n	-webkit-border-top-right-radius: 4px;\r\n	-moz-border-radius-topleft: 4px;\r\n	-moz-border-radius-topright: 4px;\r\n	border-top-left-radius: 4px;\r\n	border-top-right-radius: 4px;\r\n    \r\n    text-shadow: 1px 1px 1px rgba(0, 0, 0, 0.4);\r\n}\r\n\r\n.plan-title {\r\n    padding: 10px 0;\r\n    \r\n	font-size: 16px;\r\n    color: #FFF;\r\n\r\n    border-bottom: 1px solid rgba(0, 0, 0, 0.3);\r\n    \r\n    border-radius: 4px 4px 0 0;\r\n}\r\n\r\n.plan-price {\r\n	padding: 20px 0 10px;\r\n	\r\n    font-size: 40px;\r\n    line-height: 0.8em;\r\n    \r\n	background-color: #797979;\r\n	\r\n    border-top: 1px solid rgba(255, 255, 255, 0.2);\r\n}\r\n\r\n.plan-price span.term {\r\n    display: block;\r\n    margin-bottom: 0;\r\n    \r\n    font-size: 13px;\r\n    line-height: 0;\r\n    padding: 2em 0 1em;\r\n}\r\n\r\n.plan-price span.note {\r\n	position: relative;\r\n	top: -40px;\r\n	\r\n	display: inline;\r\n	\r\n    font-size: 17px;\r\n    line-height: 0.8em;\r\n}\r\n\r\n\r\n\r\n/*-- Best Value Highlight --*/\r\n\r\n.plan-container.best-value .plan-header {\r\n	background-color: #D98200;\r\n}\r\n\r\n.plan-container.best-value .plan-price {\r\n	background-color: #F90;\r\n}\r\n\r\n\r\n\r\n/*-- Plan Features --*/\r\n\r\n.plan-features {\r\n	border: 1px solid #DDD;	\r\n	border-bottom: none;\r\n}\r\n\r\n.plan-features {\r\n	padding-bottom: 1em;\r\n}\r\n\r\n.plan-features ul {\r\n	padding: 0;\r\n	margin: 0;\r\n	\r\n	list-style: none;\r\n}\r\n\r\n.plan-features li {	\r\n	padding: 1em 0;\r\n	margin: 0 2em;\r\n	\r\n	text-align: center;\r\n	\r\n	borde