rrent_project.get_services_by_abstract(\'ehr.emr.Document\') %>\r\n<%= show_menu obj %>\r\n',NULL,NULL,NULL,'2012-07-30 07:12:46','2012-07-30 07:12:46','context_menu',''),(447,'index',237,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-07-30 11:42:52','2012-07-30 11:42:52',NULL,NULL),(448,'layout',237,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-07-30 11:42:52','2012-07-30 11:42:52',NULL,NULL),(449,'document_name',238,1,'\'sample\'',NULL,NULL,NULL,'2012-07-30 11:43:09','2012-07-30 11:43:09',NULL,NULL),(452,'popup',213,4,'<script>\r\njQuery(document).ready(function(){\r\n    /**\r\n     * Growl Notification\r\n    **/\r\n	jQuery(\'.growl\').click(function(){\r\n		jQuery.jGrowl(\"Hello world!\");\r\n		return false;\r\n	});\r\n	\r\n	jQuery(\'.growl2\').click(function(){\r\n		var msg = \"This notification will live a little longer.\";\r\n		var position = \"top-right\";\r\n		var scrollpos = jQuery(document).scrollTop();\r\n		if(scrollpos < 50) position = \"customtop-right\";\r\n		jQuery.jGrowl(msg, { life: 5000, position: position});\r\n		return false;\r\n	});\r\n	\r\n	//this will prevent growl box to show on top of the header when\r\n	//scroll event is fired\r\n	jQuery(document).scroll(function(){\r\n		if(jQuery(\'.jGrowl\').length != 0) {\r\n			var pos = jQuery(document).scrollTop();\r\n			if(pos < 50) jQuery(\'.jGrowl\').css({top: \'70px\'}); else jQuery(\'.jGrowl\').css({top: \'0\'});\r\n		}\r\n	});\r\n	\r\n	//button animate upon hover\r\n	jQuery(\'.anchorbutton\').hover(function(){\r\n		jQuery(this).stop().animate({\r\n			backgroundColor: \'#222\', \r\n			borderColor: \'#111\', \r\n			color: \'#fff\'\r\n		},500);\r\n		jQuery(this).find(\'span\').stop().animate({\r\n			backgroundColor: \'#333\', \r\n			borderColor: \'#444\'\r\n		},500);\r\n	},function(){\r\n		jQuery(this).stop().animate({\r\n			backgroundColor: \'#f7f7f7\',\r\n			borderColor: \'#ccc\',\r\n			color: \'#333\'\r\n		},300);\r\n		jQuery(this).find(\'span\').stop().animate({\r\n			backgroundColor: \'#fff\', \r\n			borderColor: \'#ddd\'\r\n		},300);\r\n	});\r\n});\r\n\r\n(function($) {\r\n\r\n    /** jGrowl Wrapper - Establish a base jGrowl Container for compatibility with older releases. **/\r\n	$.jGrowl = function( m , o ) {\r\n		// To maintain compatibility with older version that only supported one instance we\'ll create the base container.\r\n		if ( $(\'#jGrowl\').size() == 0 ) \r\n			$(\'<div id=\"jGrowl\"></div>\').addClass( (o && o.position) ? o.position : $.jGrowl.defaults.position ).appendTo(\'body\');\r\n\r\n		// Create a notification on the container.\r\n		$(\'#jGrowl\').jGrowl(m,o);\r\n	};\r\n\r\n\r\n	/** Raise jGrowl Notification on a jGrowl Container **/\r\n	$.fn.jGrowl = function( m , o ) {\r\n		if ( $.isFunction(this.each) ) {\r\n			var args = arguments;\r\n\r\n			return this.each(function() {\r\n				var self = this;\r\n\r\n				/** Create a jGrowl Instance on the Container if it does not exist **/\r\n				if ( $(this).data(\'jGrowl.instance\') == undefined ) {\r\n					$(this).data(\'jGrowl.instance\', $.extend( new $.fn.jGrowl(), { notifications: [], element: null, interval: null } ));\r\n					$(this).data(\'jGrowl.instance\').startup( this );\r\n				}\r\n\r\n				/** Optionally call jGrowl instance methods, or just raise a normal notification **/\r\n				if ( $.isFunction($(this).data(\'jGrowl.instance\')[m]) ) {\r\n					$(this).data(\'jGrowl.instance\')[m].apply( $(this).data(\'jGrowl.instance\') , $.makeArray(args).slice(1) );\r\n				} else {\r\n					$(this).data(\'jGrowl.instance\').create( m , o );\r\n				}\r\n			});\r\n		};\r\n	};\r\n\r\n	$.extend( $.fn.jGrowl.prototype , {\r\n\r\n		/** Default JGrowl Settings **/\r\n		defaults: {\r\n			pool: 			0,\r\n			header: 		\'\',\r\n			group: 			\'\',\r\n			sticky: 		false,\r\n			position: 		\'top-right\',\r\n			glue: 			\'after\',\r\n			theme: 			\'default\',\r\n			themeState: 	\'highlight\',\r\n			corners: 		\'10px\',\r\n			check: 			250,\r\n			life: 			3000,\r\n			closeDuration:  \'normal\',\r\n			openDuration:   \'normal\',\r\n			easing: 		\'swing\',\r\n			closer: 		true,\r\n			closeTemplate: \'&times;\',\r\n			closerTemplate: \'<div>[ close all ]</div>\',\r\n			log: 			function(e,m,o) {},\r\n			beforeOpen: 	function(e,m,o) {},\r\n			afterOpen: 		function(e,m,o) {},\r\n			open: 			function(e,m,o) {},\r\n			beforeClose: 	function(e,m,o) {},\r\n			close: 			function(e,m,o) {},\r\n			animateOpen: 	{\r\n				opacity: 	\'show\'\r\n			},\r\n			animateClose: 	{\r\n				opacity: 	\'hide\'\r\n			}\r\n		},\r\n		\r\n		notifications: [],\r\n		\r\n		/** jGrowl Container Node **/\r\n		element: 	null,\r\n	\r\n		/** Interval Function **/\r\n		interval:   null,\r\n		\r\n		/** Create a Notification **/\r\n		create: 	function( message , o ) {\r\n			var o = $.extend({}, this.defaults, o);\r\n\r\n			/* To keep backward compatibility with 1.24 and earlier, honor \'speed\' if the user has set it */\r\n			if (typeof o.speed !== \'undefined\') {\r\n				o.openDuration = o.speed;\r\n				o.closeDuration = o.speed;\r\n			}\r\n\r\n			this.notifications.push({ message: message , options: o });\r\n			\r\n			o.log.apply( this.element , [this.element,message,o] );\r\n		},\r\n		\r\n		render: 		function( notification ) {\r\n			var self = this;\r\n			var message = notification.message;\r\n			var o = notification.options;\r\n\r\n			// Support for jQuery theme-states, if this is not used it displays a widget header\r\n			o.themeState = (o.themeState == \'\') ? \'\' : \'ui-state-\' + o.themeState;\r\n\r\n			var notification = $(\r\n				\'<div class=\"jGrowl-notification \' + o.themeState + \' ui-corner-all\' + \r\n				((o.group != undefined && o.group != \'\') ? \' \' + o.group : \'\') + \'\">\' +\r\n				\'<div class=\"jGrowl-close\">\' + o.closeTemplate + \'</div>\' +\r\n				\'<div class=\"jGrowl-header\">\' + o.header + \'</div>\' +\r\n				\'<div class=\"jGrowl-message\">\' + message + \'</div></div>\'\r\n			).data(\"jGrowl\", o).addClass(o.theme).children(\'div.jGr