it\'	if a>0 and a2>0 and a2<4.0 and h+bart == 0 and a>e and cs==0 and mcv<75 and f<6\r\nr  =  \'Hb CS trait\'			if a>0 and a2>=0 and a2<4.0 and a>e and cs>0.5 and f<6\r\nr  =  \'Hb E trait\'			if a>0 and a2>=0 and a2<4.0 and e>=25 and e<36 and f<6\r\nr  =  \'Hb E trait + alpha thal1 trait\' if a>0 and a2>=0 and a2<4.0 and e>=16 and e<25 and f<6\r\nr  =  \'Hb E trait + CS trait\'		if a>0 and a2>0 and a2<4.0 and e>0 and e<36 and cs>0.5  and f<5\r\nr  =  \'AE Bart\\\\\'s disease\' 		if a>0 and a2>0 and a2<4.0 and e>0 and e<18 and f<6 and h+bart>=5 and cs == 0 and mcv <80\r\nr  =  \'AE Bart\\\\\'s CS disease\'		if a>0 and a2>0 and a2<4.0 and e>0 and e<18 and f<6 and h+bart>=5 and cs > 0.5 and mcv <80\r\nr  =  \'Hemoglobin H disease\' 		if a>0 and a2>0 and a2<4.0 and a>e and f<5  and a>e and cs==0 and h+bart >= 5 and mcv<80\r\nr  =  \'Hemoglobin H CS disease\' 	if a>0 and a2>0 and a2<4.0 and a>e and f<5  and a>e and cs>0.5 and h+bart >=5 and mcv<80\r\nr  =  \'Beta thal trait\'		if a>0 and a2>=4.0 and f<11 and cs==0 \r\nr  =  \'Beta thal/Hb E disease\' 			if e >=40 and e < 76 and f >= 5 \r\nr  =  \'Hb E homozygote or Beta thal/Hb E disease\'  	if e >=76 and e < 78 and f < 5\r\nr  =  \'Hb E homozygote\' 				if e >=78 \r\n\r\nr  =  \'Homozygous Beta thal disease\'      			if f > 60 and e == 0  and a == 0 and cs == 0\r\nr  =  \'Fetus with Beta thal/Hb E or Hb E homozygote\'		if f > 60 and e >  0  and a == 0 and cs == 0\r\nr  =  \'Fetus with Hb E trait + Hb CS trait\'			if f > 60 and e >  0  and a > 0  and cs > 0 and bart+h >= 10\r\nr  =  \'Fetus with Hb E trait + possible alpha thal1 trait\'   	if f > 60 and e >  0  and a > 0  and cs == 0 and bart+h >= 10\r\nr  =  \'Fetus with possible alpha thal trait\'         		if f > 60 and e == 0  and a > 0  and cs == 0 and bart+h >= 10\r\nr  =  \'Fetus with Hb E trait\'                        		if f > 60 and e >  0  and a > 0  and cs == 0 and bart+h < 10\r\nr  =  \'Normal Fetal Hb type\'			   		if f > 60 and e == 0  and a > 0  and cs == 0 and bart+h < 10\r\n\r\nr = \"Unknown\" unless r\r\n@r = r\r\n%>\r\n',NULL,NULL,NULL,'2012-08-01 06:57:39','2012-08-01 06:57:39','interpret',''),(463,'document_name',242,1,'\'test_document\'',NULL,NULL,NULL,'2012-08-04 02:09:29','2012-08-04 02:09:29',NULL,NULL),(464,'list',235,3,'\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   records = []\r\n   n = 10 \r\n%>\r\n<%\r\n   \r\n   values = {}\r\n   query=\'\'\r\n   \r\n   # custom patient search\r\n   if params[:search]\r\n        keys = []\r\n        query = params[:search][:query]\r\n        @patient_doc.list_fields.each_with_index do |f,index| \r\n    	    keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        \r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        \r\n        ps = @patient_model.all({\'$or\'=>keys}.merge!(dates))\r\n   \r\n        records = []\r\n        for i in ps\r\n            records+= @module_model.where(:patient_id=>i.id,:module_name=>@module_name).all\r\n        end\r\n        count = records.size\r\n        \r\n        \r\n    else\r\n        from_date = nil\r\n        to_date = nil  \r\n        \r\n        n = @module_model.where(:module_name=>@module_name).count\r\n        rows,offset,page = params[:paginate]\r\n        records = @module_model.where(:module_name=>@module_name).limit(rows).skip(offset).all(:order=>\'created_at desc\')\r\n    end\r\n\r\n patients = {}\r\n @patient_model.find(records.collect{|i| i.patient_id}).each do |i|\r\n patients[i.id]=i\r\n end\r\n%>\r\n\r\n<%= tabular :model=>%w{records patient  date } , :data=>records do |i,out|\r\n\r\n base = 1\r\n patient = patients[i.patient_id]\r\n if patient\r\n url = \"../../\\\\#{@ehr_project.name}/Patient/show?id=\\\\#{patient.id}\"\r\n out[base + 0]=link_to(\"\\\\#{patient.first_name} \\\\#{patient.last_name}<br/>\\\\#{patient.hn}\".html_safe,url,:target=>\'_blank\')\r\n end\r\n\r\nout[0] = \"\\\\#{this.document_name.humanize} \\\\#{\'/ \'+i.ref_number if i.ref_number}\"\r\nout[-1] = \"\\\\#{i.date}\"\r\n\r\n\r\nout<<link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nout<<link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id,:record_name=>patient.hn),:class=>\'btn btn-warning btn-mini\')\r\nout<<link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe,url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:confirm=>\'Are you sure?\')\r\nout\r\nend\r\n%>\r\n\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2012-08-04 02:16:32','2012-08-04 02:16:32','list',''),(465,'display',235,3,'<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n<style>\r\n    .refinfo {padding:5px;width:720px; margin-left:auto; margin-right:auto}\r\n</style>\r\n <div class=\"refinfo\" >\r\n\r\nRef : <%= @patient_module.ref_number[0..9] if @patient_module.ref_number %> \r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n<p style=\"width:720px; margin-left:auto; margin-right:auto; font-weight:bold\">HN : <%= @patient.hn %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Name : <%= @patient.first_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Surname : <%= @patient.last_name %></p>\r\n<hr /><br />\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>',NULL,NULL,NULL,'2012-08-04 02:16:41','2012-08-04 02:16:41','display',''),(466,'create',235,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s  and params[:override]==