\',:remote=>false}]\r\nif params[:id]\r\nlist<<{:name=>\'Edit\',:link=>\"edit?id=\\\\#{params[:id]}\\\\#{return_url}\",:remote=>false}\r\nlist<<{:name=>\'Delete\',:link=>\"destroy?id=\\\\#{params[:id]}\",:remote=>false}\r\nend\r\nlist<<{:name=>\'Back to Home\',:link=>\"../Home/index\",:remote=>false}\r\n%>\r\n<%= show_menu [{:name=>this.document_name.humanize,:open=>true,:actions=>list}] \r\n%>\r\n\r\n',NULL,NULL,NULL,'2012-08-25 05:36:17','2012-08-25 05:36:17','context_menu',''),(528,'migrate',6,2,'<h1>Migration</h1>\r\n<div style=\"padding:20px\">\r\n<ul>\r\n<li>[\r\n<%= link_to \'Reset all data\', url(\'reset\'),:data=>{:confirm=>\'Are you sure?\'} %> ]\r\n</li>\r\n<li><%= link_to \'Download template\', url(\'import\'),:target=>\'_blank\' %></li>\r\n<li><%= link_to \'Export\', url(\'export\'),:target=>\'_blank\' %></li>\r\n<li>Import (.csv) : \r\n<%= form_for :import,:url=>\'import\',:html=>{:multipart=>true} do |f| %>\r\nFile : <%= f.file_field :file %>\r\n<%= f.submit \'Import\' ,:confirm=>\'Are you sure?\'%>\r\n<% end %>\r\n</li>\r\n\r\n\r\n</ul>\r\n</div>',NULL,NULL,NULL,'2012-08-25 05:36:17','2012-08-25 05:36:17','migrate','superuser'),(529,'import',6,3,'<%\n\n @document = get_document(this.document_name)\n   fields = @document.fields\n   fields.collect!{|i| i.column_name unless Document.visual_types.index(i.field_type) }.compact!\n   fields<<\'created_at\'\n   fields<<\'updated_at\'\n   \n   if !request.post?\n  \n%><pre>record_id    <%= fields.join(\"\\t\")%></pre>\n<% else \nrequire \'csv\'\nmodel = get_model(this.table_name)\ncsv = CSV.parse(params[:import][:file].read, :headers => true)\nlist = nil\nrecord_id = false\n%>\n<table>\n<%\ncsv.each do |row|\n list = row.to_hash.keys & fields unless list\n tmp = {}\n\n t = row.to_hash\n if t[\'record_id\'] \n record_id = true\n end\n for i in list\n    tmp[i] = t[i]\n end\n r = model.create tmp\n%><tr><td><%= t[\'record_id\'] %></td><td><%= r.id %></td></tr>\n<%\nend\n%>\n<% unless record_id %>\n<meta http-equiv=\"REFRESH\" content=\"0;url=index\">\n<% end %>\n<% end %>\n',NULL,NULL,NULL,'2012-08-25 05:36:17','2012-08-25 05:36:17','import',NULL),(530,'print',6,3,'<html>\r\n<head>\r\n			<%= javascript_include_tag \"application\"  %>\r\n			<%= stylesheet_link_tag    \"application\" ,\"elfinder\",\"elfinder-theme\"%>\r\n			<%= csrf_meta_tag %>\r\n</head>\r\n<body>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to \'Back\', url(\'index\') %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</body>\r\n</html>',NULL,NULL,NULL,'2012-08-25 05:36:17','2012-08-25 05:36:17','print',''),(531,'resources',168,2,'<%= view :fitwidth %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n#maincontainer {\r\nbackground-image: none; background:#FFF;}\r\n</style>\r\n            <meta content=\"width=device-width, initial-scale=1, maximum-scale=1\" name=\"viewport\">\r\n            \r\n            <!--CSS -->\r\n            <link href=\"/emr-life/css/base.css\" rel=\"stylesheet\">\r\n            <link href=\"/emr-life/css/skeleton.css\" rel=\"stylesheet\">\r\n            <link href=\"/emr-life/css/layout.css\" rel=\"stylesheet\">\r\n            <link href=\"/emr-life/css/font-awesome.css\" rel=\"stylesheet\">\r\n            \r\n            <!--JS -->\r\n           \r\n            <script src=\"/emr-life/js/custom.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-lif