 none;\r\n}\r\n.flex-direction-nav a {\r\nwidth: 54px;\r\nheight: 54px;\r\nmargin: -40px 0 0;\r\ndisplay: block;\r\nbackground: url(http://sunnymagicshow.com/emr-life/images/slide_direction.png) no-repeat;\r\nposition: absolute;\r\ntop: 50%;\r\ncursor: pointer;\r\ntext-indent: -999em;\r\n}\r\n.flex-direction-nav .flex-next {\r\nbackground-position: -54px 0;\r\nright: 10px;\r\n}\r\n.icons.wrench {\r\nbackground: url(http://sunnymagicshow.com/emr-life/images/icons/wrench.png) left center no-repeat transparent;\r\n}\r\n.icons.pencil {\r\nbackground: url(http://sunnymagicshow.com/emr-life/images/icons/pencil.png) left center no-repeat transparent;\r\n}\r\n.icons.stats1 {\r\nbackground: url(http://sunnymagicshow.com/emr-life/images/icons/stats1.png) left center no-repeat transparent;\r\n}\r\n.icons.heart {\r\nbackground: url(http://sunnymagicshow.com/emr-life/images/icons/heart.png) left center no-repeat transparent;\r\n}\r\n.icons {\r\npadding: 0 0 0 23px;\r\nline-height: 16px;\r\nheight: 16px;\r\ndisplay: block;\r\ncolor: #222;\r\nfont-size: 13px;\r\nfont-family: Arial, Helvetica, sans-serif;\r\nmargin: 0 0 8px 0;\r\nfont-weight: bold;\r\n}\r\ninput[type=\"text\"], input[type=\"password\"], input[type=\"email\"], textarea, select {\r\nborder: 1px solid #CCC;\r\npadding: 6px 4px;\r\noutline: none;\r\n-moz-border-radius: 2px;\r\n-webkit-border-radius: 2px;\r\nborder-radius: 2px;\r\nfont: 13px \"HelveticaNeue\", \"Helvetica Neue\", Helvetica, Arial, sans-serif;\r\ncolor: #777;\r\nmargin: 0;\r\nwidth: 210px;\r\nmax-width: 100%;\r\ndisplay: block;\r\nmargin-bottom: 20px;\r\nbackground: white;\r\n}\r\n input[type=\"submit\"], input[type=\"reset\"],  {\r\nbackground: #EEE;\r\nbackground: #EEE -webkit-gradient(linear, left top, left bottom, color-stop(0%,rgba(255, 255, 255, .2)), color-stop(100%,rgba(0, 0, 0, .2)));\r\nborder: 1px solid #AAA;\r\nborder-top: 1px solid #CCC;\r\nborder-left: 1px solid #CCC;\r\n-moz-border-radius: 3px;\r\n-webkit-border-radius: 3px;\r\nborder-radius: 3px;\r\ncolor: #444;\r\ndisplay: inline-block;\r\nfont-size: 11px;\r\nfont-weight: bold;\r\ntext-decoration: none;\r\ntext-shadow: 0 1px rgba(255, 255, 255, .75);\r\ncursor: pointer;\r\nmargin-bottom: 20px;\r\nline-height: normal;\r\npadding: 8px 10px;\r\nfont-family: \"HelveticaNeue\", \"Helvetica Neue\", Helvetica, Arial, sans-serif;\r\n}\r\n.break-feature h2 {\r\nborder-top: 1px solid lightGrey;\r\nborder-bottom: 1px solid lightGrey;\r\ntext-align: center;\r\nfont-family: \'Dosis\', sans-serif;\r\ntext-transform: uppercase;\r\npadding: 8px 0px;\r\ncolor: #353534;\r\nfont-size: 30px;\r\nmargin:5px;\r\n}\r\nh2 {\r\n    \r\n    margin: 0px;\r\n    padding:0px;\r\n    \r\nline-height: 14px;\r\ndisplay: block;\r\n-webkit-margin-before: 0.83em;\r\n-webkit-margin-after: 0.83em;\r\n-webkit-margin-start: 0px;\r\n-webkit-margin-end: 0px;\r\n}\r\n.break-feature p {\r\nfont-family: \'Nobile\', sans-serif;\r\nfont-size: 12px;\r\n}\r\n</style>\r\n',NULL,NULL,NULL,'2012-08-25 18:00:29','2012-08-25 18:00:29','emr_life',''),(533,'solution',168,2,'<%= view :fitwidth %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n#maincontainer {\r\nbackground-image: none; background:#FFF;}\r\n</style>\r\n            <meta content=\"width=device-width, initial-scale=1, maximum-scale=1\" name=\"viewport\">\r\n            \r\n            <!--CSS -->\r\n            <link href=\"/emr-life/css/base.css\" rel=\"stylesheet\">\r\n            <link href=\"/emr-life/css/skeleton.css\" rel=\"stylesheet\">\r\n            <link href=\"/emr-life/css/layout.css\" rel=\"stylesheet\">\r\n            <link href=\"/emr-life/css/font-awesome.css\" rel=\"stylesheet\">\r\n            \r\n            <!--JS -->\r\n           \r\n            <script src=\"/emr-life/js/custom.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.easing.1.3.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.superfish.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.flexslider.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.isotope.min.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.prettyPhoto.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.validate.js\" type=\"text/javascript\"></script>\r\n            \r\n            <!--ICON -->\r\n            <link href=\"/emr-life/images/favicon.ico\" rel=\"shortcut icon\">\r\n            <link href=\"/emr-life/images/apple-touch-icon.png\" rel=\"apple-touch-icon\">\r\n            <link href=\"/emr-life/images/apple-touch-icon-72x72.png\" rel=\"apple-touch-icon\" sizes=\"72x72\">\r\n            <link href=\"/emr-life/images/apple-touch-icon-114x114.png\" rel=\"apple-touch-icon\" sizes=\"114x114\">\r\n            \r\n            <!--GOOGLE FONTS -->\r\n           \r\n       \r\n            <!-- END HEADER -->\r\n        \r\n\r\n            <!-- PAGE CONTENT STEP(1)-->\r\n            <div class=\"container1\"><br />\r\n                <h2><span style=\"color:#fe8518\">EMR</span> Solution</h2>\r\n            	\r\n               \r\n				\r\n                         \r\n            <!-- END PAGE CONTENT STEP(1)-->\r\n            \r\n               <div class=\"seperator\"></div>\r\n               <div class=\"columns eight row\">\r\n\r\n    		  <!-- POSTFORMAT STANDART -->\r\n                    <div class=\"large-blog-item\">\r\n                        <div class=\"blog-item-image line-zero half-bottom\">\r\n                            <img alt=\"blog item\" class=\"scale-with-grid\" height=\"343\" src=\"/emr-life/images/working.jpg\" width=\"610\">\r\n                        </div>\r\n                        <div class=\"blog-item-content\">\r\n                            <h2 class=\"regular-size\"><a href=\"blog-detail.html\">EMR-LIFE Solution</a></h2>\r\n                            <p class=\"minitalic half-bottom\">By admin \r\n                            </p>\r\n                            <p>The new data entry management system for helping\r\n physicians and medical healthcare providers to reduce redundant\r\n document so that  they can concentrate on patients\' treatement \r\nmore efficiently. This is not just about paperless solution,\r\n but it\'s for a better life</p>\r\n                        </div>\r\n                        <div class=\"seperator del-margin\"></div>\r\n                    </div>\r\n    			</div>	\r\n <!-- SIDEBAR -->\r\n                <div class=\"columns four omega row\">\r\n                    <div class=\"sidebar1\">\r\n    					\r\n                        <!-- ACCORDION ELEMENTS -->\r\n                        <div class=\"widget row\">\r\n                            <h2 class=\"row\">Why Choose Us</h2>\r\n                            <div class=\"clear\"></div>\r\n                            <div class=\"accordion\">\r\n                                <h2 class=\"current\">Scalability</h2>\r\n                                <div class=\"pane\" style=\"display:block\">Cloud grows as your company does. Need 1 user today and want 100 next year, no problem. SaaS (Software-as-a-Service) \r\nlevels the playing field between growing businesses and larger competitors, by equipping SMBs with application functionality \r\nthat only large enterprises previously enjoyed. \r\n                                </div>\r\n                                <h2>Reliability</h2>\r\n                                <div class=\"pane\">When software programs are hosted online by independent companies, it ensures reliability of performance. Itâ€™s easy \r\nto have sufficient backup systems in place to handle unexpected downtimes or even blackouts, without burdening server capacity.\r\n Files are automatically saved, ensuring that corruption or data loss occurs much less often than with server-based computing. \r\n                                </div>\r\n                                <h2>Green Computing</h2>\r\n                                <div class=\"pane\">Cloud-based services ar e one of the greenest ways to handle computing-related tasks. Individuals and businesses can save\r\nup to 80 percent of their energy costs by switching to cloud computing. Since data centers have to be run according to strict \r\nmodels to keep up with energy requirements, this means that overall energy consumption is reduced tremendously.  \r\n                                </div>\r\n                                <h2>Cost Savings</h2>\r\n                                <div class=\"pane\">The predominant model of delivering cloud applications is via SaaS (Software-as-a-Service). Companies pay\r\n for cloud applications on a subscription basis and consequently only pay for what they need. \r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n						\r\n                        <!-- TWITTER WIDGET \r\n                        <div class=\"widget row\">\r\n                            <h2 class=\"row\">Layout 1</h2>\r\n                          content\r\n                        </div>-->\r\n                    </div><!-- End .sidebar -->\r\n</div>\r\n                                   \r\n\r\n </div>\r\n	            <div class=\"clear\"></div>\r\n            <!-- END PAGE CONTENT -->			\r\n\r\n        \r\n            <!-- END FOOTER -->	',NULL,NULL,NULL,'2012-08-26 10:45:21','2012-08-26 10:45:21','solution',''),(534,'data',6,3,'data',NULL,NULL,NULL,'2012-09-01 15:18:26','2012-09-01 15:18:26','data',''),(535,'gen_pdf',168,3,'<%\r\n\r\nurl = parmas[:url]\r\nurl = \'http://osotspaeuropereport.com/services/invoke/invoicing_pi_print?order_id=14\'\r\n`wkhtmltopdf \\\\#{url} public/report.pdf`\r\n%>\r\n<iframe id=\"fred\" style=\"border:1px solid #666CCC\" title=\"PDF in an i-Frame\" src=\"/report.pdf\" frameborder=\"1\" scrolling=\"auto\" height=\"1100\" width=\"850\" ></iframe>\r\n',NULL,NULL,NULL,'2012-09-03 16:32:02','2012-09-03 16:32:02','gen_pdf',''),(538,'document_name',261,1,'\'endoscopy_nurse\'',NULL,NULL,NULL,'2012-09-10 15:05:03','2012-09-10 15:05:03',NULL,NULL),(539,'document_name',262,1,'\'provider\'',NULL,NULL,NULL,'2012-09-10 15:15:59','2012-09-10 15:15:59',NULL,NULL),(540,'document_name',263,1,'\'case\'',NULL,NULL,NULL,'2012-09-11 09:22:34','2012-09-11 09:22:34',NULL,NULL),(541,'index',264,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-09-11 09:25:13','2012-09-11 09:25:13',NULL,NULL),(542,'layout',264,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-09-11 09:25:13','2012-09-11 09:25:13',NULL,NULL),(543,'document_name',265,1,'\'colonoscopy_scope\'',NULL,NULL,NULL,'2012-09-12 13:20:33','2012-09-12 13:20:33',NULL,NULL),(544,'document_name',266,1,'\'gastroscopy_scope\'',NULL,NULL,NULL,'2012-09-12 13:21:21','2012-09-12 13:21:21',NULL,NULL),(545,'help',168,2,'<%= view :fitwidth %>\r\n<style>\r\n.gebo-fixed { background:#F5F5F5; }\r\n#sidebar_bt {display:none }\r\n#maincontainer {\r\nbackground-image: none; background:#FFF;}\r\n</style>\r\n\r\nHelp here\r\n ',NULL,NULL,NULL,'2012-09-20 04:37:50','2012-09-20 04:37:50','help',''),(546,'document_name',267,1,'\'appoint\'',NULL,NULL,NULL,'2012-09-24 15:00:44','2012-09-24 15:00:44',NULL,NULL),(547,'document_name',268,1,'\'appointment\'',NULL,NULL,NULL,'2012-09-24 15:01:49','2012-09-24 15:01:49',NULL,NULL),(548,'document_name',269,1,'\'patho_colono\'',NULL,NULL,NULL,'2012-09-26 10:00:34','2012-09-26 10:00:34',NULL,NULL),(549,'document_name',270,1,'\'patho_gastro\'',NULL,NULL,NULL,'2012-09-26 10:03:21','2012-09-26 10:03:21',NULL,NULL),(552,'document_name',274,1,'\'cystoscope\'',NULL,NULL,NULL,'2012-09-27 03:21:05','2012-09-27 03:21:05',NULL,NULL),(553,'document_name',275,1,'\'stone\'',NULL,NULL,NULL,'2012-09-27 04:24:52','2012-09-27 04:24:52',NULL,NULL),(554,'document_name',276,1,'\'tumor\'',NULL,NULL,NULL,'20