].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\' and i.name!=\'billing\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n    # locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name if user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2012-09-30 05:43:35','2013-12-15 08:59:13','patient_record',''),(558,'about_us',168,2,'<%= view :fitwidth %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n#maincontainer {\r\nbackground-image: none; background:#FFF;}\r\n</style>\r\n            <meta content=\"width=device-width, initial-scale=1, maximum-scale=1\" name=\"viewport\">\r\n            \r\n            <!--CSS -->\r\n            <link href=\"/emr-life/css/base.css\" rel=\"stylesheet\">\r\n            <link href=\"/emr-life/css/skeleton.css\" rel=\"stylesheet\">\r\n            <link href=\"/emr-life/css/layout.css\" rel=\"stylesheet\">\r\n            <link href=\"/emr-life/css/font-awesome.css\" rel=\"stylesheet\">\r\n            \r\n            <!--JS -->\r\n           \r\n            <script src=\"/emr-life/js/custom.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.easing.1.3.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.superfish.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.flexslider.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.isotope.min.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.prettyPhoto.js\" type=\"text/javascript\"></script>\r\n            <script src=\"/emr-life/js/jquery.validate.js\" type=\"text/javascript\"></script>\r\n            \r\n            <!--ICON -->\r\n            <link href=\"/emr-life/images/favicon.ico\" rel=\"shortcut icon\">\r\n            <link href=\"/emr-life/images/apple-touch-icon.png\" rel=\"apple-touch-icon\">\r\n            <link href=\"/emr-life/images/apple-touch-icon-72x72.png\" rel=\"apple-touch-icon\" sizes=\"72x72\">\r\n            <link href=\"/emr-life/images/apple-touch-icon-114x114.png\" rel=\"apple-touch-icon\" sizes=\"114x114\">\r\n            \r\n         \r\n       \r\n            <!-- END HEADER -->\r\n        \r\n\r\n            <!-- PAGE CONTENT STEP(1)-->\r\n            <div class=\"container1\"><br />\r\n                <h2><span style=\"color:#fe8518\">About</span> Us</h2>\r\n        		<div class=\"seperator\"></div>\r\n                <!-- LEFT SLIDER -->\r\n                <div class=\"columns six row posrel\">\r\n                    <div class=\"flexslider sliderblog loading\">\r\n                        <ul class=\"slides\">\r\n                            <li>\r\n                                <img src=\"/emr-life/images/pic/service3.jpg\">\r\n                            </li>\r\n                            <li>\r\n                                <img src=\"/emr-life/images/pic/service2.jpg\">\r\n                            </li>\r\n                            <li>\r\n                                <img src=\"/emr-life/images/pic/service1.jpg\">\r\n                            </li>\r\n                        </ul>\r\n                    </div>\r\n                </div>\r\n                <!-- END LEFT SLIDER -->\r\n				\r\n                <!-- RIGHT TEXT -->\r\n                <div class=\"columns six omega\">\r\n                    <p>We are IT solution experts. We provide solutions for research and development purpose and electronics document management for Advance Electronic Medical Record \r\n                    </p>\r\n                    <blockquote>Every customer is our priority. We serve the best in every way, so our users can work efficiently. Our vision is \"Good system is our responsibility\". What we expect most is not only the success of the system, but also our customers\' satisfaction, the success of patient treatment\'s performance, and the developement in medical profession.\r\n                    </blockquote>\r\n                </div>\r\n                <!-- END RIGHT TEXT -->\r\n            </div>\r\n            <!-- END PAGE CONTENT STEP(1)-->\r\n            \r\n               <div class=\"seperator\"></div>\r\n    		 <!-- POSTFORMAT STANDART -->\r\n                    <div class=\"medium-blog-item\">\r\n                        <div class=\"blog-item-image mediumbox line-zero half-bottom\">\r\n                            <img alt=\"blog item\" class=\"scale-with-grid\" height=\"343\" src=\"/emr-life/images/pic/blog_thumb1.jpg\" width=\"610\">\r\n                        </div>\r\n                        <div class=\"blog-item-content\">\r\n                            <h2 class=\"regular-size\"><a href=\"blog-detail.html\">Special Thank you</a></h2>\r\n                            <p class=\"minitalic half-bottom\">\r\n                              \r\n                            \r\n                            </p>\r\n                           </div>\r\n                        <div class=\"seperator del-margin\"></div>\r\n                    </div>\r\n\r\n	            <div class=\"clear\"></div>\r\n            <!-- END PAGE CONTENT -->			\r\n\r\n         \r\n            <!-- END FOOTER -->	',NULL,NULL,NULL,'2012-10-02 02:42:08','2012-10-02 02:42:08','about_us',''),(559,'document_name',278,1,'\'cystoscope\'',NULL,NULL,NULL,'2012-10-03 01:42:35','2012-10-03 01:42:35',NULL,NULL),(561,'test',279,1,'\'Hello world\'\r\n@test = \'hello\'\r\nparams\r\n\r\n',NULL,NULL,NULL,'2012-10-05 17:22:47','2012-10-05 17:22:47','test',''),(563,'show_patient',279,3,'<%\r\n    patient = params[:patient]\r\n    patient_module= params[:patient_module]\r\n    \r\n    if patient and patient_module\r\n    date = patient_module.date\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n	t%=30\r\n	day = t.to_i\r\n    end\r\n%>\r\n<style>\r\nv{color:#00f}\r\n</style>\r\n<div class=\"alert alert-block alert-success\">\r\n<div class=\"btn left\" style=\"height:100px;width:100px;\">\r\nPicture\r\n</div>\r\n<div class=\"left\" style=\"padding:20px;float:left\">\r\n<p>\r\n<b> Patient : </b><v><%= patient.first_name %> <%= patient.last_name %></v>\r\n</p>\r\n<p>\r\n<b> Age : </b><v><%= year%> Years <%=month%> Months <%= day%> Days</v>\r\n</p>\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px:float:left\">\r\n<br/>\r\n<p>\r\n<b> HN : </b><v> <%= patient.hn %></v>\r\n</p>\r\n<p>\r\n<b> บัตรประจำตัวประชาชน : </b><v><%=patient.public_id%> </v>\r\n</p>\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>',NULL,NULL,NULL,'2012-10-06 03:08:10','2012-10-06 03:08:10','show_patient',''),(565,'reset',235,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @module_records = @module_model.destroy_all(:module_name=>@module_name)\r\n  model.destroy_all\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"index\"\r\n//-->\r\n</script>',NULL,NULL,NULL,'2012-10-06 07:05:21','2012-10-06 07:05:21','reset',''),(570,'list',268,3,'<style>\r\n/*!\r\n * FullCalendar v1.6.0 Stylesheet\r\n * Docs & License: http://arshaw.com/fullcalendar/\r\n * (c) 2013 Adam Shaw\r\n */\r\n\r\n\r\n.fc {\r\n    direction: ltr;\r\n	text-align: left;\r\n	}\r\n	\r\n.fc table {\r\n	border-collapse: collapse;\r\n	border-spacing: 0;\r\n	}\r\n	\r\nhtml .fc,\r\n.fc table {\r\n	font-size: 1em;\r\n	}\r\n	\r\n.fc td,\r\n.fc th {\r\n	padding: 0;\r\n	vertical-align: top;\r\n	}\r\n\r\n\r\n\r\n/* Header\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-header td {\r\n	white-space: nowrap;\r\n	}\r\n\r\n.fc-header-left {\r\n	width: 25%;\r\n	text-align: left;\r\n	}\r\n	\r\n.fc-header-center {\r\n	text-align: center;\r\n	}\r\n	\r\n.fc-header-right {\r\n	width: 25%;\r\n	text-align: right;\r\n	}\r\n	\r\n.fc-header-title {\r\n	display: inline-block;\r\n	vertical-align: top;\r\n	}\r\n	\r\n.fc-header-title h2 {\r\n	margin-top: 0;\r\n	white-space: nowrap;\r\n	}\r\n	\r\n.fc .fc-header-space {\r\n	padding-left: 10px;\r\n	}\r\n	\r\n.fc-header .fc-button {\r\n	margin-bottom: 1em;\r\n	vertical-align: top;\r\n	}\r\n	\r\n/* buttons edges butting together */\r\n\r\n.fc-header .fc-button {\r\n	margin-right: -1px;\r\n	}\r\n	\r\n.fc-header .fc-corner-right,  /* non-theme */\r\n.fc-header .ui-corner-right { /* theme */\r\n	margin-right: 0; /* back to normal */\r\n	}\r\n	\r\n/* button layering (for border precedence) */\r\n	\r\n.fc-header .fc-state-hover,\r\n.fc-header .ui-state-hover {\r\n	z-index: 2;\r\n	}\r\n	\r\n.fc-header .fc-state-down {\r\n	z-index: 3;\r\n	}\r\n\r\n.fc-header .fc-state-active,\r\n.fc-header .ui-state-active {\r\n	z-index: 4;\r\n	}\r\n	\r\n	\r\n	\r\n/* Content\r\n------------------------------------------------------------------------*/\r\n	\r\n.fc-content {\r\n	clear: both;\r\n	}\r\n	\r\n.fc-view {\r\n	width: 100%; /* needed for view switching (when view is absolute) */\r\n	overflow: hidden;\r\n	}\r\n	\r\n	\r\n\r\n/* Cell Styles\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-widget-header,    /* <th>, usually */\r\n.fc-widget-content {  /* <td>, usually */\r\n	border: 1px solid #ddd;\r\n	}\r\n	\r\n.fc-state-highlight { /* <td> today cell */ /* TODO: add .fc-today to <th> */\r\n	background: #fcf8e3;\r\n	}\r\n	\r\n.fc-cell-overlay { /* semi-transparent rectangle while dragging */\r\n	background: #bce8f1;\r\n	opacity: .3;\r\n	filter: alpha(opacity=30); /* for IE */\r\n	}\r\n	\r\n\r\n\r\n/* Buttons\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-button {\r\n	position: relative;\r\n	display: inline-block;\r\n	padding: 0 .6em;\r\n	overflow: hidden;\r\n	height: 1.9em;\r\n	line-height: 1.9em;\r\n	white-space: nowrap;\r\n	cursor: pointer;\r\n	}\r\n	\r\n.fc-state-default { /* non-theme */\r\n	border: 1px solid;\r\n	}\r\n\r\n.fc-state-default.fc-corner-left { /* non-theme */\r\n	border-top-left-radius: 4px;\r\n	border-bottom-left-radius: 4px;\r\n	}\r\n\r\n.fc-state-default.fc-corner-right { /* non-theme */\r\n	border-top-right-radius: 4px;\r\n	border-bottom-right-radius: 4px;\r\n	}\r\n\r\n/*\r\n	Our default prev/next buttons use HTML entities like &lsaquo; &rsaquo; &laquo; &raquo;\r\n	and we\'ll try to make them look good cross-browser.\r\n*/\r\n\r\n.fc-text-arrow {\r\n	margin: 0 .1em;\r\n	font-size: 2em;\r\n	font-family: \"Courier New\", Courier, monospace;\r\n	vertical-align: baseline; /* for IE7 */\r\n	}\r\n\r\n.fc-button-prev .fc-text-arrow,\r\n.fc-button-next .fc-text-arrow { /* for &lsaquo; &rsaquo; */\r\n	font-weight: bold;\r\n	}\r\n	\r\n/* icon (for jquery ui) */\r\n	\r\n.fc-button .fc-icon-wrap {\r\n	position: relative;\r\n	float: left;\r\n	top: 50%;\r\n	}\r\n	\r\n.fc-button .ui-icon {\r\n	position: relative;\r\n	float: left;\r\n	margin-top: -50%;\r\n	*margin-top: 0;\r\n	*top: -50%;\r\n	}\r\n	\r\n/*\r\n  button states\r\n  borrowed from twitter bootstrap (http://twitter.github.com/bootstrap/)\r\n*/\r\n\r\n.fc-state-default {\r\n	background-color: #f5f5f5;\r\n	background-image: -moz-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: -webkit-gradient(linear, 0 0, 0 100%, from(#ffffff), to(#e6e6e6));\r\n	background-image: -webkit-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: -o-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: linear-gradient(to bottom, #ffffff, #e6e6e6);\r\n	background-repeat: repeat-x;\r\n	border-color: #e6e6e6 #e6e6e6 #bfbfbf;\r\n	border-color: rgba(0, 0, 0, 0.1) rgba(0, 0, 0, 0.1) rgba(0, 0, 0, 0.25);\r\n	color: #333;\r\n	text-shadow: 0 1px 1px rgba(255, 255, 255, 0.75);\r\n	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2), 0 1px 2px rgba(0, 0, 0, 0.05);\r\n	}\r\n\r\n.fc-state-hover,\r\n.fc-state-down,\r\n.fc-state-active,\r\n.fc-state-disabled {\r\n	color: #333333;\r\n	background-color: #e6e6e6;\r\n	}\r\n\r\n.fc-state-hover {\r\n	color: #333333;\r\n	text-decoration: none;\r\n	background-position: 0 -15px;\r\n	-webkit-transition: background-position 0.1s linear;\r\n	   -moz-transition: background-position 0.1s linear;\r\n	     -o-transition: background-position 0.1s linear;\r\n	        transition: background-position 0.1s linear;\r\n	}\r\n\r\n.fc-state-down,\r\n.fc-state-active {\r\n	background-color: #cccccc;\r\n	background-image: none;\r\n	outline: 0;\r\n	box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.15), 0 1px 2px rgba(0, 0, 0, 0.05);\r\n	}\r\n\r\n.fc-state-disabled {\r\n	cursor: default;\r\n	background-image: none;\r\n	opacity: 0.65;\r\n	filter: alpha(opacity=65);\r\n	box-shadow: none;\r\n	}\r\n\r\n	\r\n\r\n/* Global Event Styles\r\n------------------------------------------------------------------------*/\r\n	 \r\n.fc-event {\r\n	border: 1px solid #3a87ad; /* default BORDER color */\r\n	background-color: #3a87ad; /* default BACKGROUND color */\r\n	color: #fff;               /* default TEXT color */\r\n	text-shadow: 0 -1px 0 rgba(0, 0, 0, 0.25);\r\n	font-size: .85em;\r\n	cursor: default;\r\n	}\r\n\r\na.fc-event {\r\n	text-decoration: none;\r\n	}\r\n	\r\na.fc-event,\r\n.fc-event-draggable {\r\n	cursor: pointer;\r\n	}\r\n	\r\n.fc-rtl .fc-event {\r\n	text-align: right;\r\n	}\r\n\r\n.fc-event-inner {\r\n	width: 100%;\r\n	overflow: hidden;\r\n	}\r\n	\r\n.fc-event-time,\r\n.fc-event-title {\r\n	padding: 0 1px;\r\n	}\r\n	\r\n.fc .ui-resizable-handle {\r\n	display: block;\r\n	position: absolute;\r\n	z-index: 99999;\r\n	overflow: hidden; /* hacky spaces (IE6/7) */\r\n	font-size: 300%;  /* */\r\n	line-height: 50%; /* */\r\n	}\r\n	\r\n	\r\n	\r\n/* Horizontal Events\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-event-hori {\r\n	border-width: 1px 0;\r\n	margin-bottom: 1px;\r\n	}\r\n\r\n.fc-ltr .fc-event-hori.fc-event-start,\r\n.fc-rtl .fc-event-hori.fc-event-end {\r\n	border-left-width: 1px;\r\n	border-top-left-radius: 3px;\r\n	border-bottom-left-radius: 3px;\r\n	}\r\n\r\n.fc-ltr .fc-event-hori.fc-event-end,\r\n.fc-rtl .fc-event-hori.fc-event-start {\r\n	border-right-width: 1px;\r\n	border-top-right-radius: 3px;\r\n	border-bottom-right-radius: 3px;\r\n	}\r\n	\r\n/* resizable */\r\n	\r\n.fc-event-hori .ui-resizable-e {\r\n	top: 0           !important; /* importants override pre jquery ui 1.7 styles */\r\n	right: -3px      !important;\r\n	width: 7px       !important;\r\n	height: 100%     !important;\r\n	cursor: e-resize;\r\n	}\r\n	\r\n.fc-event-hori .ui-resizable-w {\r\n	top: 0           !important;\r\n	left: -3px       !important;\r\n	width: 7px       !important;\r\n	height: 100%     !important;\r\n	cursor: w-resize;\r\n	}\r\n	\r\n.fc-event-hori .ui-resizable-handle {\r\n	_padding-bottom: 14px; /* IE6 had 0 height */\r\n	}\r\n	\r\n	\r\n	\r\n/* Reusable Separate-border Table\r\n------------------------------------------------------------*/\r\n\r\ntable.fc-border-separate {\r\n	border-collapse: separate;\r\n	}\r\n	\r\n.fc-border-separate th,\r\n.fc-border-separate td {\r\n	border-width: 1px 0 0 1px;\r\n	}\r\n	\r\n.fc-border-separate th.fc-last,\r\n.fc-border-separate td.fc-last {\r\n	border-right-width: 1px;\r\n	}\r\n	\r\n.fc-border-separate tr.fc-last th,\r\n.fc-border-separate tr.fc-last td {\r\n	border-bottom-width: 1px;\r\n	}\r\n	\r\n.fc-border-separate tbody tr.fc-first td,\r\n.fc-border-separate tbody tr.fc-first th {\r\n	border-top-width: 0;\r\n	}\r\n	\r\n	\r\n\r\n/* Month View, Basic Week View, Basic Day View\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-grid th {\r\n	text-align: center;\r\n	}\r\n\r\n.fc .fc-week-number {\r\n	width: 22px;\r\n	text-align: center;\r\n	}\r\n\r\n.fc .fc-week-number div {\r\n	padding: 0 2px;\r\n	}\r\n	\r\n.fc-grid .fc-day-number {\r\n	float: right;\r\n	padding: 0 2px;\r\n	}\r\n	\r\n.fc-grid .fc-other-month .fc-day-number {\r\n	opacity: 0.3;\r\n	filter: alpha(opacity=30); /* for IE */\r\n	/* opacity with small font can sometimes look too faded\r\n	   might want to set the \'color\' property instead\r\n	   making day-numbers bold also fixes the problem */\r\n	}\r\n	\r\n.fc-grid .fc-day-content {\r\n	clear: both;\r\n	padding: 2px 2px 1px; /* distance between events and day edges */\r\n	}\r\n	\r\n/* event styles */\r\n	\r\n.fc-grid .fc-event-time {\r\n	font-weight: bold;\r\n	}\r\n	\r\n/* right-to-left */\r\n	\r\n.fc-rtl .fc-grid .fc-day-number {\r\n	float: left;\r\n	}\r\n	\r\n.fc-rtl .fc-grid .fc-event-time {\r\n	float: right;\r\n	}\r\n	\r\n	\r\n\r\n/* Agenda Week View, Agenda Day View\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-agenda table {\r\n	border-collapse: separate;\r\n	}\r\n	\r\n.fc-agenda-days th {\r\n	text-align: center;\r\n	}\r\n	\r\n.fc-agenda .fc-agenda-axis {\r\n	width: 50px;\r\n	padding: 0 4px;\r\n	vertical-align: middle;\r\n	text-align: right;\r\n	white-space: nowrap;\r\n	font-weight: normal;\r\n	}\r\n\r\n.fc-agenda .fc-week-number {\r\n	font-weight: bold;\r\n	}\r\n	\r\n.fc-agenda .fc-day-content {\r\n	padding: 2px 2px 1px;\r\n	}\r\n	\r\n/* make axis border take precedence */\r\n	\r\n.fc-agenda-days .fc-agenda-axis {\r\n	border-right-width: 1px;\r\n	}\r\n	\r\n.fc-agenda-days .fc-col0 {\r\n	border-left-width: 0;\r\n	}\r\n	\r\n/* all-day area */\r\n	\r\n.fc-agenda-allday th {\r\n	border-width: 0 1px;\r\n	}\r\n	\r\n.fc-agenda-allday .fc-day-content {\r\n	min-height: 34px; /* TODO: doesnt work well in quirksmode */\r\n	_height: 34px;\r\n	}\r\n	\r\n/* divider (between all-day and slots) */\r\n	\r\n.fc-agenda-divider-inner {\r\n	height: 2px;\r\n	overflow: hidden;\r\n	}\r\n	\r\n.fc-widget-header .fc-agenda-divider-inner {\r\n	background: #eee;\r\n	}\r\n	\r\n/* slot rows */\r\n	\r\n.fc-agenda-slots th {\r\n	border-width: 1px 1px 0;\r\n	}\r\n	\r\n.fc-agenda-slots td {\r\n	border-width: 1px 0 0;\r\n	background: none;\r\n	}\r\n	\r\n.fc-agenda-slots td div {\r\n	height: 20px;\r\n	}\r\n	\r\n.fc-agenda-slots tr.fc-slot0 th,\r\n.fc-agenda-slots tr.fc-slot0 td {\r\n	border-top-width: 0;\r\n	}\r\n\r\n.fc-agenda-slots tr.fc-minor th,\r\n.fc-agenda-slots tr.fc-minor td {\r\n	border-top-style: dotted;\r\n	}\r\n	\r\n.fc-agenda-slots tr.fc-minor th.ui-widget-header {\r\n	*border-top-style: solid; /* doesn\'t work with background in IE6/7 */\r\n	}\r\n	\r\n\r\n\r\n/* Vertical Events\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-event-vert {\r\n	border-width: 0 1px;\r\n	}\r\n\r\n.fc-event-vert.fc-event-start {\r\n	border-top-width: 1px;\r\n	border-top-left-radius: 3px;\r\n	border-top-right-radius: 3px;\r\n	}\r\n\r\n.fc-event-vert.fc-event-end {\r\n	border-bottom-width: 1px;\r\n	border-bottom-left-radius: 3px;\r\n	border-bottom-right-radius: 3px;\r\n	}\r\n	\r\n.fc-event-vert .fc-event-time {\r\n	white-space: nowrap;\r\n	font-size: 10px;\r\n	}\r\n\r\n.fc-event-vert .fc-event-inner {\r\n	position: relative;\r\n	z-index: 2;\r\n	}\r\n	\r\n.fc-event-vert .fc-event-bg { /* makes the event lighter w/ a semi-transparent overlay  */\r\n	position: absolute;\r\n	z-index: 1;\r\n	top: 0;\r\n	left: 0;\r\n	width: 100%;\r\n	height: 100%;\r\n	background: #fff;\r\n	opacity: .3;\r\n	filter: alpha(opacity=30);\r\n	}\r\n	\r\n.fc .ui-draggable-dragging .fc-event-bg, /* TODO: something nicer like .fc-opacity */\r\n.fc-select-helper .fc-event-bg {\r\n	display: none\\9; /* for IE6/7/8. nested opacity filters while dragging don\'t work */\r\n	}\r\n	\r\n/* resizable */\r\n	\r\n.fc-event-vert .ui-resizable-s {\r\n	bottom: 0        !important; /* importants override pre jquery ui 1.7 styles */\r\n	width: 100%      !important;\r\n	height: 8px      !important;\r\n	overflow: hidden !important;\r\n	line-height: 8px !important;\r\n	font-size: 11px  !important;\r\n	font-family: monospace;\r\n	text-align: center;\r\n	cursor: s-resize;\r\n	}\r\n	\r\n.fc-agenda .ui-resizable-resizing { /* TODO: better selector */\r\n	_overflow: hidden;\r\n	}\r\n	\r\n	\r\n</style>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   records = []\r\n   n = 10 \r\n%>\r\n<%\r\n   \r\n   values = {}\r\n   query=\'\'\r\n   if params[:search]\r\n\r\n        \r\n        query = params[:search][:query]\r\n          keys = []\r\n    \r\n        @patient_doc.list_fields.each_with_index do |f,index| \r\n		    keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        \r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n\r\n                \r\n        ps = @patient_model.all({\'$or\'=>keys}.merge!(dates))\r\n   \r\n        records = []\r\n        for i in ps\r\n            records+= @module_model.where(:patient_id=>i.id,:module_name=>@module_name).all\r\n        end\r\n        count = records.size\r\n        \r\n        \r\n    else\r\n        from_date = nil\r\n        to_date = nil  \r\n          n = @module_model.where(:module_name=>@module_name).count\r\n        rows,offset,page = params[:paginate]\r\n        records = @module_model.where(:module_name=>@module_name).all(:order=>\'created_at desc\',:limit=>20)\r\n    end\r\n\r\n\r\n patients = {}\r\n @patient_model.find(records.collect{|i| i.patient_id}).each do |i|\r\n patients[i.id]=i\r\n end\r\n appointments = {}\r\n @models[:appointment].find(records.collect{|i| i.module_id}).each do |i|\r\n appointments[i.id]=i\r\n end\r\n \r\n title = \'Calendar\'\r\n \r\n if params[:provider_id]\r\n    provider = @models[:provider].find(params[:provider_id])\r\n    title = \"\\\\#{provider.name}\'s Calendar\"\r\n end\r\n%>\r\n\r\n  <link rel=\"stylesheet\" href=\"/gebo/lib/fullcalendar/fullcalendar_gebo.css\" />\r\n  <div class=\"row-fluid\">\r\n            			<div class=\"span12\">\r\n							<h2 class=\"heading\"><%= title %></h2>\r\n							<div id=\"calendar\"></div>\r\n						</div>\r\n					</div>\r\n\r\n\r\n    	<script src=\"/gebo/lib/fullcalendar/fullcalendar.min.js\"></script>\r\n			<!-- calendar functions -->\r\n			<script src=\"/gebo/lib/fullcalendar/gcal.js\"></script>\r\n<%\r\n   pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\njson_data =   records.collect{|i| \r\nl = %w{#bcdeee}\r\nap = appointments[i.module_id] \r\np = patients[i.patient_id]\r\nif (ap and params[:provider_id]==nil) or (params[:provider_id] and ap.provider.to_s==params[:provider_id].to_s)\r\n     date_d = \'-\'\r\n     date_d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n     date_s = \'-\'\r\n     date_s = ap.date.strftime(\"%Y-%m-%d\")+ap.start.strftime(\" %H:%M\") if ap.date and ap.start\r\n     date_e = \'-\'\r\n     date_e = ap.date.strftime(\"%Y-%m-%d\")+ap.stop.strftime(\" %H:%M\") if ap.date  and ap.stop\r\n     \r\n     \r\n    {\'procedure\'=>pro[ap.procedure],\'date\'=>date_d,\'color\'=>l[rand(4%l.size)],\'title\'=>\"\\\\#{p.first_name if p } \\\\#{p.hn if p}\",\'start\'=>date_s,\'end\'=>date_e,\'allDay\'=>false,\'url\'=>\'edit?id=\'+i.id.to_s}  \r\nelse\r\n    nil\r\nend \r\n}.compact\r\n\r\n    \r\n    df =   @models[:day_off].all\r\n \r\n    \r\n    df_list = df.collect{|i|\r\n        pname = \'\'\r\n        p = @models[:provider].find(i.provider)\r\n        pname = p.name if p\r\n        date =  \'-\'\r\n        date = i.date.strftime(\"%Y-%m-%d\") if i.date\r\n        {\'color\'=>\'#ccc\',\'title\'=>\"\\\\#{i.title} \\\\#{pname}\",\'start\'=>date,\'allDay\'=>true}\r\n    }\r\n    \r\n    map = {}\r\n    \r\n    for i in json_data\r\n    \r\n    date = i[\'date\']\r\n    p = i[\'procedure\']\r\n    \r\n    map[date] = {} unless map[date]\r\n    map[date][p] = 0  unless map[date][p]\r\n    map[date][p] += 1\r\n    \r\n    end\r\n    \r\n    c_list = []\r\n    map.each_pair do |k,v|\r\n         txt = \'\'\r\n         v.each_pair { |key, value| txt+=\"\\\\#{key}=\\\\#{value}   \".html_safe }\r\n         c_list<<{\'color\'=>\'#fcc\',\'title\'=>\"\\\\#{txt}\",\'start\'=>k,\'allDay\'=>true,\'url\'=>\'/\'}\r\n    end\r\n    \r\n    detail = json_data\r\n    \r\n    json_data = df_list\r\n    \r\n    json_data+= c_list\r\n    \r\n    json_data+= detail if params[:detail]    \r\n%>\r\n<%#df.inspect %>\r\n\r\n<script>\r\n\r\n var refresh_loading = false;\r\n\r\n function refresh_date(start,end,detail,provider_id){\r\n    \r\n        if(refresh_loading==false){\r\n        refresh_loading = true\r\n    \r\n        path = \'data\'\r\n        detail_path = \'data_detail\'\r\n      \r\n        $.ajax({\r\n            url: path ,\r\n            dataType: \'json\',\r\n            data: {\r\n                start: start,\r\n                end: end,\r\n                detail: detail,\r\n                provider_id: provider_id\r\n            },\r\n            success: function(doc) {\r\n             data = eval(doc);\r\n            $(\'#calendar\').fullCalendar(\'removeEvents\');\r\n           \r\n            $.each(data, function(index, event){\r\n            $(\'#calendar\').fullCalendar(\'renderEvent\', event);\r\n            });\r\n            }\r\n            });\r\n            \r\n         $.ajax({\r\n            url: detail_path,\r\n            data: {\r\n                start: start,\r\n                end: end,\r\n                detail: detail,\r\n                provider_id: provider_id\r\n            },\r\n            success: function(doc) {\r\n                $(\'#event-details\').html(doc);\r\n            }\r\n         });\r\n\r\n    refresh_loading=false;\r\n     $(\'#loading\').hide();\r\n        }\r\n    \r\n}\r\n    $(document).ready(function() {\r\n\r\n\r\n\r\n\r\n\r\n        gebo_calendar.regular();\r\n\r\n		//* resize elements on window resize\r\n		var lastWindowHeight = $(window).height();\r\n		var lastWindowWidth = $(window).width();\r\n		$(window).on(\"debouncedresize\",function() {\r\n      \r\n			if($(window).height()!=lastWindowHeight || $(window).width()!=lastWindowWidth){\r\n				lastWindowHeight = $(window).height();\r\n				lastWindowWidth = $(window).width();\r\n				//* rebuild calendar\r\n			}\r\n		});\r\n	});\r\n	\r\n	//* calendar\r\n	gebo_calendar = {\r\n		regular: function() {\r\n			var date = new Date();\r\n			var d = date.getDate();\r\n			var m = date.getMonth();\r\n			var y = date.getFullYear();\r\n			var calendar = $(\'#calendar\').fullCalendar({\r\n				header: {\r\n					left: \'prev,next today\',\r\n					center: \'title\',\r\n					right: \'month,agendaWeek,agendaDay\'\r\n				},\r\n		\r\n				aspectRatio: 2,\r\n				selectable: true,\r\n				selectHelper: true,\r\n                \r\n      dayClick: function(date, allDay, jsEvent, view) {\r\n      if($(\'#calendar\').fullCalendar( \'getView\').name!=\'month\')\r\n            window.location=\"../DayOff/create?data[date]=\"+date.getFullYear()+\'-\'+(date.getMonth()+1)+\'-\'+date.getDate() +\"&return=../Appointment/index\"\r\n      $(\'#calendar\').fullCalendar( \'changeView\', \'agendaDay\' );\r\n      $(\'#calendar\').fullCalendar( \'gotoDate\', date.getFullYear() ,date.getMonth(), date.getDate()  );\r\n      \r\n       provider_id = \"<%=params[:provider_id]%>\";\r\n      \r\n       refresh_date(date.getTime()/1000,date.getTime()/1000+3600*24-1,true,provider_id);\r\n      \r\n     \r\n      \r\n      },\r\n      viewDisplay: function(view) {\r\n          \r\n\r\n        if(view.name == \'month\')\r\n        { \r\n            $(\'#calendar\').fullCalendar(\'refetchEvents\');\r\n        }\r\n        if(view.name==\'agendaWeek\'){\r\n             $(\'#calendar\').fullCalendar(\'refetchEvents\');\r\n        }\r\n      },\r\n	  select: function(start, end, allDay) {\r\n               \r\n      if(allDay==false){\r\n	        calendar.fullCalendar(\'unselect\');\r\n            window.location=\"create?data[date]=\"+start.getFullYear()+\'-\'+(start.getMonth()+1)+\'-\'+start.getDate()+\"&data[start]=\"+\r\n            start.getHours()+\":\"+start.getMinutes()+\"&data[stop]=\"+end.getHours()+\":\"+end.getMinutes()\r\n      }\r\n               \r\n	  }\r\n      ,\r\n	  editable: false,\r\n	  theme: false,\r\n	  events: function(start, end, callback) {\r\n   \r\n    \r\n      provider_id = \"<%=params[:provider_id]%>\";\r\n    \r\n  \r\n      refresh_date(Math.round(start.getTime() / 1000),Math.round(end.getTime() / 1000),<%=params[:detail]==\'true\'%>,provider_id);\r\n         \r\n\r\n     },\r\n	  loading: function(bool) {\r\n	  if (bool) $(\'#loading\').show();\r\n	  else $(\'#loading\').hide();\r\n	  }\r\n	});\r\n	}\r\n	};\r\n</script>\r\n<div id=\'loading\' style=\'display:none\'>Loading...</div>\r\n\r\n<div id=\"event-details\">\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2012-10-07 08:10:44','2013-07-10 10:08:10','list',''),(571,'patient_tag',235,3,'<span class=\"right\">Extended EMR : <%= @module_name %></span>\r\n<div class=\"clear\"></div>\r\n<% if params[:patient] %>\r\n<% \r\n    patient = params[:patient]\r\n   \r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n	year = (t/365).to_i\r\n	t%=365\r\n	month = (t/30).to_i\r\n	t%=30\r\n	day = t.to_i\r\n    end\r\n%>\r\n<style>\r\nv{color:#00f}\r\n</style>\r\n<div style=\"border:1px solid #ccc;padding:0px;background:#eef;font-size:1.2em\">\r\n\r\n\r\n<div class=\"left\" style=\"padding:20px;float:left\">\r\n<p>\r\n<b> Name : </b><v><%= patient.first_name %> <%= patient.last_name %></v>\r\n</p>\r\n<p>\r\n<b> Age : </b><v><%= year%> Years <%=month%> Months <%= day%> Days</v>\r\n</p>\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px:float:left\">\r\n<br/>\r\n<p>\r\n<b> HN : </b><v> <%= patient.hn %></v>\r\n</p>\r\n<p>\r\n<b> เลขบัตรประจำตัวประชาชน : </b><v><%=patient.public_id%> </v>\r\n</p>\r\n</div>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<br/>\r\n\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2012-10-07 13:25:27','2012-10-07 13:25:27','patient_tag',''),(572,'print',251,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%= render :inline=>this.print_partial, :locals=>{:this=>this} %>\r\n<script>\r\nwindow.print()\r\n</script>\r\n<%\r\n    if @current_project.get_setting \'report_server\'\r\n    report_server_path = \"\\\\#{@current_project.get_setting \'report_server\'}?domain=\\\\#{DOMAIN}&solution=\\\\#{@current_solution.name}&application=\\\\#{@current_project.name}&report=\\\\#{this.document_name}&id=\\\\#{params[:id]}\"\r\n    `curl \'\\\\#{report_server_path.html_safe}\'`\r\n    end \r\n%>',NULL,NULL,NULL,'2012-10-07 13:43:30','2012-10-07 13:43:30','print',''),(573,'print',268,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\n@font-face {\r\n    font-family: \'barcode\';\r\n	src: url(\'/esm/ehr/emr/font/barcode.eot\');\r\n	src: local(\'☺\'), url(\'/esm/ehr/emr/font/c39hrp24dhtt.woff\') format(\'woff\'), url(\'/esm/ehr/emr/font/barcode.ttf\') format(\'truetype\'), url(\'/esm/ehr/emr/font/barcode.svg\') format(\'svg\');\r\n	font-weight: 700px;\r\n	font-size:60px;\r\n}\r\n.barcode\r\n	{font-family:\'barcode\',Sans-Serif;}\r\n#page {border:solid 0px;  border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding:0 0px 10px 10px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:360px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:360px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:360px;margin-left:0px;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:0px solid #ccc;\r\n	-webkit-border-radius: 5px; /* Safari prototype */\r\n	-moz-border-radius: 5px; /* Gecko browsers */\r\n	border-radius: 5px; /* Everything else - limited support at the moment */	\r\n	margin:10px;\r\n}\r\n.smm { font-size:9pt; }\r\n#box img{\r\n		width:150px;\r\n}\r\nlabel{\r\n	color:#666;\r\n}\r\n</style>\r\n<body>\r\n<br />\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"page\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p></p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n%>\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tr>\r\n<td width=\"310\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\'200px\' /></td>\r\n<td>\r\n</td>\r\n<td>\r\n<div class=\"barcode\" style=\"font-size:50px; float:right; margin-right:30px; height:60px\"><%= @patient.hn %> </div></td>\r\n</tr>\r\n\r\n</table>\r\n----------------------------------------------------------------\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tr>\r\n  <td colspan=\"2\" >H.N.</td>\r\n  <td width=\"71%\">: <%= @patient.hn %></td>\r\n</tr>\r\n<tr>\r\n  <td colspan=\"2\" >วันที่</td>\r\n  <td>: <%= render_value \'date\' %></td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" ><storng>ชื่อ-นามสกุล</storng></td><td>: <%=@patient.first_name %> <%=@patient.last_name %></td></tr>\r\n<tr><td colspan=\"2\"><storng>มาพบแพทย์</storng></td><td>: <%= render_value \'provider\' %></td></tr>\r\n<tr>\r\n<td colspan=\"2\"><storng>เวลานัด</storng></td><td>: <%= render_value \'start\' %> ถึง <%= render_value \'stop\' %></td></tr>\r\n<tr>\r\n<td colspan=\"2\"><storng>มาทำ</storng></td><td>: <%= render_value \'procedure\' %></td></tr>\r\n<tr>\r\n  <td width=\"16%\">Note</td>\r\n  <td colspan=\"2\"><p>: <%= render_value \'note\' %></p></td>\r\n  </tr>\r\n</table>\r\n\r\n\r\n<%# render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<%# @record.inspect %>\r\n\r\n<!-- <a href=\"http://<%=get_setting \'barcode_station\' %>/print?name=<%=@patient.first_name%>&date=<%= render_value \'date\'%>&proc=<%= render_value(\'procedure\').strip %>&hn=<%= @patient.hn %>\">Print</a> -->\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</body>\r\n</html>',NULL,NULL,NULL,'2012-10-09 12:41:28','2012-10-09 12:41:28','print',''),(574,'create',6,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<% link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2012-10-09 15:51:14','2013-07-23 13:48:33','create',''),(575,'index',6,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'index\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2012-10-09 15:51:53','2012-10-09 15:51:53','index',''),(577,'destroy',6,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  @record.destroy \r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=index\">',NULL,NULL,NULL,'2012-10-09 15:55:07','2012-10-09 15:55:07','destroy',''),(578,'reset',6,3,'<%\r\n model = get_model(this.table_name)\r\n model.destroy_all\r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=index\">\r\n\r\n',NULL,NULL,NULL,'2012-10-09 15:55:50','2012-10-09 15:55:50','reset',''),(579,'show',6,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2012-10-09 15:56:52','2012-10-09 15:56:52','show',''),(581,'search',213,2,'Searching ...\r\n<META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=<%=\"../Patient/index?search[query]=\\\\#{params[:query]}&search[from_date]=&search[to_date]=\"%>\">\r\n\r\n',NULL,NULL,NULL,'2012-11-02 16:22:08','2012-11-02 16:22:08','search',''),(582,'search',226,2,'\r\n<h1> Search Result </h1>\r\n<hr/>\r\n<% \r\n    models = get_model\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    fields = %w{hn public_id first_name last_name}\r\n    query = params[:query].strip\r\n    \r\n    \r\n    \r\n    hn_mode=false\r\n    if i = query.index(\'/\')\r\n        t = query.split(\'/\')\r\n        query = \"\\\\#{t[0].to_i}/\\\\#{t[1].to_i}\"\r\n        hn_mode = true  \r\n    elsif query[0..-3].size>=4 and query.to_i !=0\r\n        query = \"\\\\#{query[0..-3].to_i}/\\\\#{query[-2..-1].to_i}\"\r\n        hn_mode = true  \r\n    end\r\n    \r\n    # if query.size == 8 and query.index(\'/\')==nil\r\n    #   query = \"\\\\#{query[0..-3].to_i}/\\\\#{query[-2..-1].to_i}\" \r\n    # elsif query.index(\'/\')\r\n    \r\n    # end\r\n    \r\n    \r\n    keys = []\r\n    # fields.each do |f| \r\n    #     keys <<{f.to_sym=>Regexp.new(query)}\r\n    # end\r\n    keys << {:hn=>query}\r\n\r\n    \r\n    unless hn_mode\r\n    \r\n    keys << {:first_name=>Regexp.new(query)}\r\n    keys << {:last_name=>Regexp.new(query)}\r\n    keys << {:public_id=>query} if query.size==13\r\n    \r\n    end\r\n    \r\n    criteria = {\'$or\'=>keys}\r\n    \r\n    patients = patient_model.where(criteria).limit(20).all  \r\n    \r\n    app_name = \"\\\\#{@current_project.name}#appointment\"\r\n    app_model = models[:appointment]\r\n\r\n    if patients.size==1\r\n        row = patients[0]\r\n        ams = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).all.collect{|i| i.module_id }\r\n        app = app_model.where(:id=>{\'$in\'=>ams},:status=>{\'$nin\'=>[\'Cancelled\',\'No show\']}).all :sort=>\'date desc\'\r\n \r\nif app\r\n  \r\n#   app = app_model.where(:id=>am.module_id).first\r\n  app = app[0]\r\n  \r\n  if @current_role!=\'pathologist\'\r\n  url = \"../Home/patient_record?id=\\\\#{app.id}\"\r\n  else\r\n  url = \"../Home/patho_patient_record?id=\\\\#{app.id}\"\r\n  end\r\n\r\n  if true\r\n        \r\n        %>\r\n        <META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=<%=url_for(url)%>\">\r\n        <%\r\n        \r\n    end\r\n        \r\n    end\r\n   end\r\n%>\r\n<%= tabular :model=>fields,:data=>patients,:n=>10 do |row,out|\r\n\r\n  am = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).order(\'date\').last\r\nif am\r\n  app = app_model.where(:id=>am.module_id).first\r\n  \r\n  if @current_role!=\'pathologist\'\r\n  url = \"../Home/patient_record?id=\\\\#{am.module_id}\"\r\n  else\r\n  url = \"../Home/patho_patient_record?id=\\\\#{am.module_id}\"\r\n  end\r\n  \r\n  out[0] = link_to(row.hn,url)\r\n  out[1] = link_to(row.public_id,url)\r\n  out[2] = link_to(row.first_name,url)\r\n  out[3] = link_to(row.last_name,url)\r\n  n = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).count\r\nout << link_to(\"Select (\\\\#{n})\", url,:class=>\"btn btn-mini\")\r\nelse\r\nout<<\'-\'\r\nend\r\n\r\nout\r\nend\r\n\r\n%>\r\n\r\n<hr/>\r\n<%# hn_mode.inspect %>\r\n<%#@current_role %>',NULL,NULL,NULL,'2012-11-02 16:48:59','2012-11-02 16:48:59','search',''),(583,'form',268,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    \r\n    \r\n    $(\'.ctrl\').hide();\r\n    \r\n    \r\n</script>',NULL,NULL,NULL,'2012-11-03 08:29:23','2012-11-03 08:29:23','form',''),(586,'print',188,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:pre_scope].find(colono_id)\r\n    \r\n    parent = @module_model.find(pm.parent_id)\r\n    app = models[:appointment].find(parent.module_id)\r\n    procedure = models[:procedure].find(app.procedure)\r\n    \r\n    diagnosis=\'-\'\r\n    colo_name = @current_project.name+\'#\'+ \'colonoscopy\' \r\n    colo_module = @module_model.first(:parent_id=>parent.id,:module_name=>colo_name)\r\n    if colo_module \r\n        colo = models[:colonoscopy].find(colo_module.module_id)\r\n        @record = colo\r\n        @document = get_document \'colonoscopy\'\r\n        indication=render_value(\'indication\') \r\n        previous_opreation = render_value(\'previous_opreation\')\r\n    end\r\n    \r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n	-webkit-border-radius: 5px; /* Safari prototype */\r\n	-moz-border-radius: 5px; /* Gecko browsers */\r\n	border-radius: 5px; /* Everything else - limited support at the moment */	\r\n	margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n		width:150px;\r\n}\r\nlabel{\r\n	color:#666; font-weight:bold;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo.png\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block; margin-left:20px; float:left\">Pre scope\r\n	<p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <value><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></value> (Age :&nbsp;<value><%= year%> Year <%=month%> Month <%= day%> Day </value>)</h3>\r\n</div><hr />\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../www/Patient/search_result?\';\r\nurl += \'&id=50163c5e790f9b74a2000028\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:98%;padding:0px\">\r\n\r\n\r\n<h3>Indication : <value><%=indication %></value> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Plan Procedure : <value><%=procedure.name %></value>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Previous Operation : <value><%=previous_opreation %></value> </h3>\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n    \r\n<div id=\"call_time\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Call time : </label></span>	\r\n\r\n<value><%= record.call_time.strftime(\"%H:%M\") if record.call_time %></value>\r\n<script>\r\n\r\n$(\"#data-call_time\").kendoTimePicker({\r\n	value: \'23:25\',\r\n	interval: 10\r\n});\r\n</script>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"arrival_time\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Arrival time : </label></span>	\r\n\r\n<value><%= record.arrival_time.strftime(\"%H:%M\") if record.call_time %></value>\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"mode_of_arrival\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Mode of arrival : </label></span>	\r\n\r\n<value><%=render_value \'mode_of_arrival\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\">\r\n</div>\r\n	\r\n<div id=\"person_to_notify_name\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:370px\">\r\n<span class=\"\"><label>Person to notify name : </label></span>	\r\n<value><%=render_value \'person_to_notify_name\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"relation\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Relation : </label></span>	\r\n<value><%=render_value \'relation\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"tel\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>tel : </label></span>	\r\n<value><%=render_value \'tel\'%></value>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n	\r\n<div id=\"patient_identifcation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:450px\">\r\n<span class=\"\"><label>Patient identifcation : </label></span>	\r\n\r\n<value><%=record[\'patient_identifcation\'].split(\'|\').join(\' , \')%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"verification_of_procedure\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:450px\">\r\n<span class=\"\"><label>Verification of Procedure : </label></span>	\r\n\r\n<value><%=record[\'verification_of_procedure\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"psychological_condition\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:450px\">\r\n<span class=\"\"><label>Psychological Condition : </label></span>	\r\n\r\n<value><%=render_value \'psychological_condition\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"psychological_condition_other\" class=\"  portlet \" style=\"width:450px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Other : </label></span>	\r\n<value><%=render_value \'psychological_condition_other\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"112-F8205658533\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"nursing_diagnosis\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:650px\">\r\n<span class=\"\"><label>Nursing diagnosis : </label></span>	\r\n\r\n<value><%=record[\'nursing_diagnosis\'].split(\'|\').join(\' , \')%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"nursing_deagnosis_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\">\r\n<span class=\"\"><label>Note : </label></span>	\r\n<value><%=render_value \'nursing_deagnosis_note\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"112-F8038481183\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"outcome_goal\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Outcome goal : </label></span>	\r\n\r\n<value><%=record[\'outcome_goal\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"plan_and_implementation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Plan and Implementation : </label></span>	\r\n\r\n<value><%=render_value \'plan_and_implementation\'%> <%=render_value \'plan_other\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"evaluation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Evaluation : </label></span>	\r\n\r\n	<value><%=render_value \'evaluation\'%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"previous_illness\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px\">\r\n<span class=\"\"><label>Previous illness : </label></span>	\r\n\r\n<value><%=render_value \'previous_illness\'%></value>\r\n</div>\r\n\r\n	\r\n<div id=\"previous_operation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px\">\r\n<span class=\"\"><label>Previous operation : </label></span>	\r\n\r\n<value><%=render_value \'previous_operation\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"npo_since\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>NPO since : </label></span>	\r\n\r\n<value><%=render_value \'npo_since\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n<div id=\"familycancer\" class=\"  portlet \" style=\"width:450px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Family History of Colorectal cancer : </label></span>	\r\n\r\n<value><%=render_value \'familycancer\'%></value>\r\n	\r\n\r\n</div>\r\n	\r\n<div id=\"nop_at\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:140px\">\r\n<span class=\"\"><label>at : </label></span>	\r\n\r\n<value><%= record.nop_at.strftime(\"%H:%M\") if record.call_time %></value>\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n<div id=\"bowel_preparation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px\">\r\n<span class=\"\"><label>Bowel preparation : </label></span>	\r\n\r\n<imvalue><%=render_