" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px; margin-left:10px\">\r\n<span class=\"\"><label>Recorded date : </label></span>	\r\n\r\n<value><%=render_value \'recorded_date\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"recorded_time\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Recorded time : </label></span>	\r\n\r\n<value><%=render_value \'recorded_time\'%></value>\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2012-11-08 16:30:14','2012-11-08 16:30:14','print',''),(587,'print',187,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    \r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:intra_scope].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    	width:150px;\r\n}\r\nlabel{\r\n	color:#666; font-weight:bold;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo.png\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"margin-left:20px; float:left; \">Intrascope\r\n	<p>Hospital No :&nbsp;<value><%=patient.hn%></value> Name : <value><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></value> (Age :&nbsp;<value><%= year%> Year <%=month%> Month <%= day%> Day </value>)</h3>\r\n</div><hr />\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../www/Patient/search_result?\';\r\nurl += \'&id=50163c5e790f9b74a2000028\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:930px;padding:0px\">\r\n\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n	\r\n<div id=\"time_in_room\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Time in room : </label></span>	\r\n\r\n<value><%= record.time_in_room.strftime(\"%H:%M\") if record.time_in_room %></value>\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"procedure_start\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Procedure start : </label></span>	\r\n\r\n<value><%= record.procedure_start.strftime(\"%H:%M\") if record.procedure_start %></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"procedure_complete\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Procedure complete : </label></span>	\r\n\r\n<value><%= record.procedure_complete.strftime(\"%H:%M\") if record.procedure_complete %></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"time_out_room\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Time out room : </label></span>	\r\n\r\n<value><%= record.time_out_room.strftime(\"%H:%M\") if record.time_out_room %></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"111-F7206284797\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"endosocpist1\" class=\"  portlet \" style=\"width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Endosocpist : </label></span>	\r\n\r\n<value><%=render_value \'endosocpist1\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"endosocpist2\" class=\"  portlet \" style=\"width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Endosocpist 2 : </label></span>	\r\n\r\n<value><%=render_value \'endosocpist2\'%></value>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n	\r\n<div id=\"assistant1\" class=\"  portlet \" style=\"width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><l