r\n%>\r\n</table></div>\r\n</div>\r\n\r\n	\r\n	<div id=\"111-F4697836177\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"level_of_conscious\" class=\"  portlet \" style=\"width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Level of conscious : </label></span>	\r\n\r\n<value><%=render_value \'level_of_conscious\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"electro_surgical_unit\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:550px\">\r\n<span class=\"\"><label>Electro surgical unit : </label></span>	\r\n\r\n<value><%=render_value \'electro_surgical_unit\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"ground_pad_site\" class=\"  portlet \" style=\"width:910px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Ground pad site : </label></span>	\r\n\r\n<value><%=render_value \'ground_pad_site\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"procedure\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px\">\r\n<span class=\"\"><label>Procedure : </label></span>	\r\n\r\n<imvalue><%=render_value \'procedure\'%></imvalue>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"specimen\" class=\"  portlet \" style=\"width:180px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Specimen (pieces) : </label></span>	\r\n<imvalue><%=render_value \'specimen\'%></imvalue>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"nurse_diagnosis_electrosurgical\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Nurse diagnosis ElectroSurgical : </label></span>	\r\n\r\n<value><%=render_value \'nurse_diagnosis_electrosurgical\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"outcom_goal_electrosurgical\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Outcome goal ElectroSurgical : </label></span>	\r\n\r\n<value><%=render_value \'outcom_goal_electrosurgical\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"plan_and_imple_elec\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Plan & Implementation ElectroSurgical  : </label></span>	\r\n\r\n<value><%=render_value \'plan_and_imple_elec\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"evaluate_electro\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:910px\">\r\n<span class=\"\"><label>Evaluation Electrosurgical : </label></span>	\r\n\r\n<value><%=render_value \'evaluate_electro\'%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"comment\" class=\"  portlet \" style=\"width:900px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Comment : </label></span>	\r\n<value><pre><%=render_value \'comment\'%></pre></value>\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n	\r\n\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Recorded nurse :  <value><%=render_value \'recorded_nurse\'%></value></h4>\r\n\r\n\r\n	\r\n<div id=\"recorded_date\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;width:220px; margin-left:10px\">\r\n<span class=\"\"><label>Recorded date : </label></span>	\r\n\r\n<value><%=render_value \'recorded_date\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"recorded_time\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Recorded time : </label></span>	\r\n\r\n<value><%= record.recorded_time.strftime(\"%H:%M\") if record.recorded_time %></value>\r\n\r\n</div>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2012-11-08 16:32:05','2012-11-08 16:32:05','print',''),(588,'print',146,3,'<%\r\n    values = %w{Elective Emergency Extratime}\r\n\r\n    date = Time.now\r\n    \r\n    total = 0\r\n    totals = {}\r\n    \r\n    if params[:print]\r\n    date = params[:print][:date]\r\n    date = Date.parse(date)\r\n    end    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = []\r\n    \r\n    status_list=%w{appointed waiting processing completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    forms = %w{colonoscopy gastroscopy}\r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    list = aps.clone\r\n    id = \'\'\r\n    \r\n      aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n        c = {:ref_number=>m.ref_number,\r\n            :public_id=>patient.public_id,\r\n            :hn=>patient.hn,\r\n            :patient=>link_to(\"\\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n            :provider=>\"\",\r\n            :date=>i.date,\r\n            :note=>i.note,\r\n            :status=>nil,\r\n            :procedure=>models[:procedure].find(i.procedure).name,\r\n            :module=>m,\r\n            :appointment=>i\r\n         }\r\n         \r\n        jname = \"\\\\#{@current_project.name}#intra_scope\"\r\n        m = module_model.where(:module_name=>jname,:parent_id=>m.id.to_s).first\r\n        \r\n        if m and intra = models[:intra_scope].find(m.module_id)\r\n            c[:no_specimen] = intra.specimen\r\n            \r\n          \r\n            \r\n            if !intra.endoscopy_nurse.empty?\r\n            tt = models[:time_to_time]\r\n            for x in  intra.endoscopy_nurse\r\n            tx = tt.find(x)\r\n            if tx and px = p_model.find(tx.endoscopy_nurse)\r\n            c[:provider]+=\"<br/>N:\"+ px.name \r\n            end\r\n            end\r\n            end\r\n            \r\n            if intra.assistant1\r\n            if px = p_model.find(intra.assistant1)\r\n            c[:provider]+=\"<br/>A:\"+ px.name \r\n            end\r\n            end\r\n            if intra.assistant2\r\n            if px = p_model.find(intra.assistant2)\r\n            c[:provider]+=\"<br/>A:\"+ px.name \r\n            end\r\n            end\r\n            \r\n        end\r\n        \r\n     end\r\n      \r\n      c\r\n      \r\n      }\r\n    \r\n    list = []\r\n    \r\n    \r\n    \r\n    for i in aps\r\n    \r\n    mm = i[:module]\r\n    \r\n    status = \'\'\r\n    \r\n    preprovider = i[:provider]\r\n          \r\n    for j in forms\r\n        jname = \"\\\\#{@current_project.name}#\\\\#{j}\"\r\n        m = module_model.where(:module_name=>jname,:parent_id=>mm.id.to_s).first\r\n        if m\r\n        data = models[j.to_sym].find(m.module_id)\r\n        i[:time] = data.start_at.strftime(\"%H:%M\")+\" (\\\\#{((data.stop_at-data.start_at)/60).to_i})\"\r\n        i[:procedure]= j.humanize\r\n        i[:add_procedure] = data.procedure.split(\"|\").join(\", \")\r\n        i[:diagnosis_group] = data.diagnosis_group.split(\"|\").join(\", \")\r\n        i[:status] = data.status;\r\n        status = data.status;\r\n        i[:sedation] = [\'dormicum\',\'pethidine\',\'diprivan\',\'valium\',\'buscopan\',\'plasil\',\'fentanyl\'].collect{|s| \"\\\\#{s.humanize} \\\\#{data[s+\'_mg\']} mg \\\\#{data[s+\'_num\']}\" if data[s+\'_mg\'] }.compact.join(\"<br/>\")\r\n        i[:bowel_prep] = data.quality_of_preparate\r\n        \r\n             prov = \"\"\r\n             \r\n            if data.endoscopist_1\r\n            if px = p_model.find(data.endoscopist_1)\r\n            prov = \"E:\\\\#{px.name}.\"\r\n            end\r\n            end\r\n            \r\n            \r\n            if data.endoscopist_2\r\n            if px = p_model.find(data.endoscopist_2)\r\n            prov+=\"<br/>E:\"+ px.name \r\n            end\r\n            end\r\n            \r\n        i[:provider]= \"\\\\#{prov}\\\\#{preprovider}\"\r\n        \r\n        totals[i[:status]]={} unless totals[i[:status]]\r\n        totals[i[:status]][j]=0 unless totals[i[:status]][j]\r\n        totals[i[:status]][j]+=1\r\n        \r\n        ls = []\r\n        if j == \'colonoscopy\'\r\n        ls = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n        ms = \'colonoscopy_scope\'\r\n        else\r\n        ls = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n        ms = \'gastroscopy_scope\'\r\n        end\r\n        count = 0\r\n        max = 0\r\n        c = 0\r\n        %>\r\n        <%# data.inspect %>\r\n        <%\r\n        ls.each{|lc| \r\n            if data[lc] and !data[lc].empty?\r\n                #count+=data[lc].size\r\n                \r\n                ll = models[ms.to_sym].find(data[lc])\r\n              \r\n                for li in ll\r\n                    #z = li.patho_number.to_i if li.patho_number\r\n                    #max = z if z>max\r\n                    count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                end\r\n            end\r\n        }\r\n        \r\n        \r\n        i[:no_specimen] = (count).to_s\r\n        list<<i.clone  \r\n        end\r\n        \r\n        \r\n                 \r\n\r\n     end  \r\n\r\n     if i and i[:status] and totals[i[:status]]\r\n        totals[i[:status]][\'patient\']=0 unless totals[i[:status]][\'patient\']\r\n        totals[i[:status]][\'patient\']+=1\r\n     end\r\n\r\n     \r\n    end\r\n    \r\n    aps = list.sort{|a,b| a[:time]<=>b[:time]}\r\n\r\n    apss = {}\r\n    \r\n    values.size.times do |j|\r\n    apss[values[j]] = aps.collect{|i| i if i[:status]==values[j] }.compact\r\n    end\r\n\r\n\r\n\r\n%>\r\n\r\n<%# apss.inspect  %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n	-webkit-border-radius: 3px;\r\n	border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo.png\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงผู้ป่วยเข้ารับการส่องกล้องห้องส่องกล้อง Surgical endoscopy \r\n<span style=\"float:right\">ประจำวันที่ \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n<%\r\n \r\n line = 0 \r\n  for x in values \r\n  \r\n  aps = apss[x]\r\n  \r\n  if aps.size>0 \r\n%>\r\n<h2><%=x%></h2>\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th>เวลา(นาที)</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>Quality Prep</th>\r\n    <th style=\"width:150px\">Sedation</th>\r\n    <th>Procedure</th>\r\n    <th>Add procedure</th>\r\n    <th style=\"width:150px\">Endoscopist</th>\r\n    <th>Diagnosis group</th>\r\n    <th>No. of Specimen</th>\r\n  </tr>\r\n  </thead>\r\n  \r\n  \r\n  <tbody>\r\n\r\n  <%\r\n   count = 0\r\n    \r\n  for i in aps \r\n\r\n  %>\r\n <!---\r\nLet\'s now create a ton or rows that will require\r\nseveral pages to fully print.\r\n--->\r\n\r\n  <tr>\r\n  <td><%= count+=1 %>.</td>\r\n    <td> <%= i[:time] %></td>\r\n    <td><%= i[:patient] %><br /><%= i[:hn] %><br /><%= i[:public_id] %></td>\r\n    <td><%= i[:bowel_prep].html_safe  if i[:bowel_prep]%></td>\r\n    <td><%= i[:sedation].html_safe  if i[:sedation]%></td>\r\n    <td><%= i[:procedure] %></td>\r\n    <td><%= i[:add_procedure] %></td>\r\n    <td><%= i[:provider].html_safe %></td>\r\n    <td><%= i[:diagnosis_group] %></td>\r\n    <td><%= i[:no_specimen] %></td>\r\n  </tr>\r\n  \r\n  <% \r\n\r\n \r\n    \r\n    if line%16==14\r\n  %>\r\n  </tbody>\r\n  </table>\r\n  <br/><br/>\r\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\" style=\"page-break-before:always\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th>เวลา(นาที)</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>Quality Prep</th>\r\n    <th style=\"width:150px\">Sedation</th>\r\n    <th>Procedure</th>\r\n    <th>Add procedure</th>\r\n    <th style=\"width:150px\">Endoscopist</th>\r\n    <th>Diagnosis group</th>\r\n    <th>No. of Specimen</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n  <%\r\n    end \r\n     line += 1 \r\n  %>\r\n  \r\n  <% end  %>\r\n  \r\n  </tbody>\r\n</table>\r\n\r\n<br/>\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n<h2>Summary</h2>\r\n<%# totals.inspect%>\r\n<table  border=\"1\" cellspacing=\"0\"  cellpadding=\"5\" id=\"table-3\" style=\"width:400px\">\r\n<tr  align=\"center\"><td>&nbsp;</td>\r\n<% for j in forms %>\r\n<td><%= j.humanize %></td>\r\n<% end %><td>Number of Patient</td>\r\n</tr>\r\n<% for i in values \r\n    if totals[i]\r\n%>\r\n<tr align=\"center\"><th><%=i%></th>\r\n<% for j in forms %>\r\n<td ><%= totals[i][j] %></td>\r\n<% end %>\r\n<td><%= totals[i][\'patient\']%></td>\r\n</tr>\r\n<% \r\n\r\nend \r\nend %>\r\n</table>\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<%#totals.inspect %>\r\n\r\n<div class=\"clear\">\r\n</div>\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2012-11-08 16:37:44','2012-11-08 16:37:44','print',''),(590,'config',146,1,'[\r\n{:name=>\'Nurse Records\',:open=>true,:actions=>[\r\n{:name=>\'Consignment\',:service=>\'consignment\',:link=>\'../Consignment/index\',:remote=>false},\r\n{:name=>\'Pre Scope\',:service=>\'pre_scope\',:link=>\'../PreScope/index\',:remote=>false},\r\n{:name=>\'Intra Scope\',:service=>\'intra_scope\',:link=>\'../IntraScope/index\',:remote=>false},\r\n{:name=>\'Post Scope\',:service=>\'post_scope\',:link=>\'../PostScope/index\',:remote=>false}]},\r\n{:name=>\'Endoscopist Records\',:open=>true,:actions=>[\r\n{:name=>\'Colonosopy\',:service=>\'colonoscopy\',:dashboard=>true,:link=>\'../Colonoscopy/index\',:remote=>false},\r\n{:name=>\'Gastroscopy\',:service=>\'gastroscopy\',:dashboard=>true,:link=>\'../Gastroscopy/index\',:remote=>false}]},\r\n{:name=>\'ETC\',:open=>true,:actions=>[\r\n{:name=>\'Billing\',:service=>\'billing\',:dashboard=>true,:link=>\'../Billing/index\',:remote=>false},\r\n{:name=>\'Pathology\',:service=>\'pathology\',:dashboard=>true,:link=>\'../Pathology/index\',:remote=>false},\r\n{:name=>\'Research\',:service=>\'research\',:exclude=>true,:link=>\'../Research/index\',:remote=>false}]}]\r\n',NULL,NULL,NULL,'2012-11-09 17:46:21','2012-11-09 17:46:21','config',''),(591,'print',206,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:pathology].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\n    \r\n    \r\n    \r\n    patho_colonos = models[:patho_colono].find(record.colono_pathology)\r\n    patho_gastros = models[:patho_gastro].find(record.gastro_pathology)\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\nend %>\r\n\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\nvalue {color:#06F}\r\n#page {border:solid 1px; width:960px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n	-moz-border-radius: 5px; /* Gecko browsers */\r\n	border-radius: 5px; /* Everything else - limited support at the moment */	\r\n	margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n		width:150px;\r\n}\r\nlabel{\r\n	color:#666; font-weight:bold;\r\n}\r\n</style>\r\n<body>\r\n\r\n\r\n\r\n<br />\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>\r\n<center>Surgical Pathology Request Form for Cyto-Histopathology <br/> Department of Pathology</center></h3>\r\n</div><hr />\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<p>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../www/Patient/search_result?\';\r\nurl += \'&id=50163c5e790f9b74a2000028\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:930px;padding:0px\">\r\n\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v><%=Time.now.strftime(\"%d-%m-%Y\")%></v>&nbsp;&nbsp; Colonoscope by :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n	\r\n	<div id=\"126-F6296540512\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n	<div id=\"126-F2858320218\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Colonoscopy</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"colono_pathology\" class=\"  portlet \" style=\"width:905px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<table width=\"100%\">\r\n<% for i in patho_colonos \r\n\r\n   attachments = models[:attachment].find(i.patho_image[0..5].compact)\r\n   attachments2 = models[:attachment].find(i.patho_scope[0..5].compact)\r\n   \r\n\r\n%>\r\n<tr style=\"background:#eef;padding:5px\">\r\n\r\n<td style=\"padding:5px\">No <%=i.patho_no %>.</td>\r\n    \r\n<td><%=i.location %></td>\r\n\r\n<td><%=i.endodx %></td>\r\n    \r\n<td><%=i.wide %>(W) x <%=i.height %>(H) x <%=i.depth%>(D)</td>\r\n<td colspan=\"5\" style=\"width:300px;color:red\"></td>   \r\n\r\n</tr>\r\n<tr>\r\n    <td colspan=\"8\">\r\n    <% for j in attachments %>\r\n        <%=image_tag j.path, :height=>100%>\r\n    <% end %>\r\n    </td>\r\n</tr>\r\n<% if i.diagnosis %>\r\n\r\n<tr><td >\r\n<%=\'Microscopic : \'  %></td><td style=\"color:red\"><%= i.diagnosis %>\r\n</td></tr>\r\n<tr>\r\n    <td colspan=\"8\">\r\n    <% for j in attachments2 %>\r\n        <%=image_tag j.path, :height=>100%>\r\n    <% end %>\r\n    </td>\r\n</tr>\r\n\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n</table>	\r\n\r\n\r\n			\r\n					\r\n<input id=\"record_colono_pathology\" name=\"record[colono_pathology]\" type=\"hidden\" value=\"\" />\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"126-F5280413251\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Gastroscopy</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"gastro_pathology\" class=\"  portlet \" style=\"width:905px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<table width=\"100%\">\r\n<% for i in patho_gastros \r\n\r\n   attachments = models[:attachment].find(i.patho_image[0..5].compact)\r\n   attachments2 = models[:attachment].find(i.patho_scope[0..5].compact)\r\n\r\n\r\n%>\r\n<tr style=\"background:#eef;padding:5px\">\r\n\r\n<td style=\"padding:5px\">No <%=i.patho_no %>.</td>\r\n    \r\n<td><%=i.location %></td>\r\n\r\n<td><%=i.endodx %></td>\r\n    \r\n<td><%=i.wide %>(W) x <%=i.height %>(H) x <%=i.depth%>(D)</td>\r\n<td colspan=\"5\" style=\"width:300px;color:red\"></td>        \r\n</tr>\r\n<tr>\r\n    <td colspan=\"8\">\r\n    <% for j in attachments %>\r\n        <%=image_tag j.path, :height=>100%>\r\n    <% end %>\r\n    </td>\r\n</tr>\r\n\r\n<% if i.diagnosis %>\r\n\r\n<tr><td >\r\n<%=\'Microscopic : \'  %></td><td style=\"color:red\"><%= i.diagnosis %>\r\n</td></tr>\r\n<tr>\r\n    <td colspan=\"8\">\r\n    <% for j in attachments2 %>\r\n        <%=image_tag j.path, :height=>100%>\r\n    <% end %>\r\n    </td>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>	\r\n					\r\n<input id=\"record_gastro_pathology\" name=\"record[gastro_pathology]\" type=\"hidden\" value=\"\" />\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"picture\" class=\"  portlet \" style=\"width:905px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Picture : </label></span>	\r\n\r\n<link rel= \"stylesheet\" href = \"/dragdrop/opt.css\" type=\"text/css\" />\r\n\r\n\r\n<div style=\"width:100%;border:0px solid;\">\r\n	<img src=\'/dragdrop/images/down16.png\' id=\'indicator\'/>\r\n	<div id=\'pictzone\' class=\'k-textbox k-textbox-txt\' >\r\n		\r\n\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n<!-- Upload window -->\r\n<div id=\"search-data-picture\" style=\"display:none\">	\r\n\r\n\r\n\r\n<div id=\"search-result\">\r\n</div>\r\n</div>\r\n<script type=\"text/javascript\" charset=\"utf-8\">\r\n\r\n	function openUploadWindow(){\r\n		$(document).ready(function(){\r\n		    var window = $(\"#search-data-picture\").kendoWindow({\r\n		        height: \"200px\",\r\n		        title: \"Picture Upload\",\r\n		        visible: true,\r\n		        width: \"500px\"\r\n		    }).data(\"kendoWindow\");\r\n		});\r\n		var window = $(\"#search-data-picture\").data(\"kendoWindow\");\r\n	    window.center();\r\n	    window.open();\r\n		$(\"#search-data-picture\").css(\"display\", \"block\")\r\n	}\r\n</script>\r\n<div class=\"clear\"></div>	\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n<script type=\"text/javascript\" charset=\"utf-8\">\r\n$(\"#data-name\").kendoAutoComplete();\r\n$(\"#data-hn\").kendoAutoComplete();\r\n$(\"#data-sxpathono\").kendoAutoComplete();\r\n$(\"#data-totalspecimen\").kendoAutoComplete();\r\n\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n</div>\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2012-11-10 03:31:56','2012-11-10 03:31:56','print',''),(592,'print',193,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:post_scope].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\nvalue {color:#06F}\r\nvalue.nl {font-weight:bold;font-size:1.2em}\r\nvalue.normal {color:#388A15;font-weight:bold;font-size:1.2em}\r\nvalue.warn {color:#aa0;font-weight:bold;font-size:1.2em}\r\nvalue.error {color:#a00;font-weight:bold;font-size:1.2em}\r\ntable.tbcontent td { padding-left:5px; padding-right:5px}\r\n\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px; padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo.png\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"margin-left:20px; float:left; \">Post Scope\r\n    <p>Hospital No :&nbsp;<value><%=patient.hn%></value> Name : <value><%= patient.first_name %> <%= patient.last_name %></value> (Age :&nbsp;<value><%= year%> Year <%=month%> Month <%= day%> Day </value>)</h3>\r\n</div><hr />\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../www/Patient/search_result?\';\r\nurl += \'&id=501e981d790f9b50d8000001\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:930px;padding:0px\">\r\n\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n	\r\n<div id=\"time_in_recovery_room\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Time in recovery room : </label></span>	\r\n\r\n<value><%= render_value \'time_in_recovery_room\' %></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"post_scope_phase\" class=\"  portlet \" style=\"width:100%;float:left;\">\r\n<span class=\"\"><label>Post scope phase : </label></span>	\r\n\r\n			<div id=\"F1272873605\">\r\n            					<div id=\"509e77f1790f9b5bf10001c8\" style=\"border:0px solid #ccc;margin-bottom:0px\">\r\n\r\n	<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:10px;margin-right:10px;width:900px;padding:0px\">\r\n\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:12px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n<table border=\"1\" cellpadding=\"0\" cellspacing=\"0\" bordercolor=\"#E6E6E6\" width=\"100%\" height=\"15\">\r\n  <tr >\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\" >Time</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Point :</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Vital sign</td>\r\n      <td align=\"center\" bgcolor=\"#EEEEEE\">O<sub>2</sub>Sat</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Conscious</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Respiration</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Nausea/<br />Vomiting</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Pain</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Bleeding</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Ambulation</td>\r\n      <td align=\"center\" bgcolor=\"#EEEEEE\">Note</td>\r\n  </tr>\r\n<% \r\n\r\n#==================================================================================   START LOOP\r\nfield_name = \'post_scope_phase\'\r\nrelate_model_name = \'post_scope_record\'\r\n\r\ntemp_record = @record \r\ntemp_document = @document\r\n\r\nrelate_doc = get_document relate_model_name\r\nrelate_records = models[relate_model_name.to_sym].find(record[field_name.to_sym])\r\n\r\nif relate_records!=nil \r\n\r\nrelate_records.each_with_index do |i,index|  \r\n\r\n@record = i\r\n@document = relate_doc\r\n\r\n#================================================================================== START LOOP\r\n%>\r\n<%\r\n    v = @record.o2sat\r\n    osat = 0\r\n    osat = 1 if v> 92 \r\n    osat = 2 if v> 95\r\n    osat = osat.to_s\r\n    \r\n    point = \'0\' \r\n    point = \'1\' if @record.point>10 \r\n    point = \'2\' if @record.point>=14\r\n    \r\n    \r\n%>\r\n  <tr >\r\n<td align=\"center\" >\r\n  <value class=\"nl\"><%= render_value \'post_scope_time\' %></value>\r\n	\r\n<%\r\ndef ccls v\r\n    cls = \'normal\' \r\n    cls = \'warn\' if v==\'1\'\r\n    cls = \'error\' if v==\'0\'\r\n    cls\r\nend\r\n%>\r\n</td> <td align=\"center\">\r\n  <value class=\"<%=ccls(point)%>\"><%= @record.point %></value>\r\n</td> <td align=\"center\">\r\n<value class=\"<%=ccls(@record.vital_sign)%>\"><%=  @record.vital_sign %></value>\r\n</td><td align=\"center\">\r\n<value class=\"<%=ccls(osat)%>\"><%= osat %></value>\r\n</td> <td align=\"center\">\r\n<value class=\"<%=ccls(@record.conscious)%>\"><%= @record.conscious %></value>\r\n</td> <td align=\"center\">\r\n<value class=\"<%=ccls(@record.respiration)%>\"><%= @record.respiration %></value>\r\n</td> <td align=\"center\">\r\n<value class=\"<%=ccls(@record.nausea_vomiting)%>\"><%= @record.nausea_vomiting %></value>\r\n</td> <td align=\"center\">	\r\n<value class=\"<%=ccls(@record.pain)%>\"><%= @record.pain %></value>\r\n</td> <td align=\"center\">\r\n<value class=\"<%=ccls(@record.bleeding)%>\"><%= @record.bleeding %></value>\r\n</td>\r\n<td align=\"center\"><value class=\"<%=ccls(@record.ambulation)%>\"><%=@record.ambulation %></value></td>\r\n<td align=\"center\"><value ><%=@record.post_scope_note %></value></td>\r\n  </tr>\r\n\r\n					<% \r\n#======================================================================== END LOOP\r\nend \r\n@record = temp_record\r\n@document = temp_document\r\nend\r\n#======================================================================== END LOOP\r\n%>\r\n</table>\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n\r\n\r\n\r\n\r\n</div>\r\n					\r\n\r\n			</div>\r\n			\r\n					\r\n<input id=\"record_post_scope_phase\" name=\"record[post_scope_phase]\" type=\"hidden\" value=\"509e77f1790f9b5bf10001c8 509e77f1790f9b5bf10001c9\" />\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<center>เกณฑ์การให้คะแนน</center>\r\n<div style=\"padding-left:10px; padding-right:10px; font-size:12px;\">\r\n<table border=\"1\" cellpadding=\"0\" cellspacing=\"0\" bordercolor=\"#E6E6E6\" width=\"900\" class=\"tbcontent\">\r\n  <tr>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Topic</td>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Data</td>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Score</td>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Topic</td>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Data</td>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Score</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"3\" valign=\"top\">1. BP, HR</td>\r\n    <td>+ - &lt; 20% ของ Pre-Procedure</td>\r\n    <td align=\"center\">2</td>\r\n    <td rowspan=\"3\" valign=\"top\"> 5. Nausea Vomiting</td>\r\n    <td>ไม่มีอาการ</td>\r\n    <td align=\"center\">2</td>\r\n    </tr>\r\n  <tr>\r\n    <td>+ - &lt; 20-40% ของ Pre-Procedure</td>\r\n    <td align=\"center\">1</td>\r\n    <td> มีอาการ</td>\r\n    <td align=\"center\">1</td>\r\n    </tr>\r\n  <tr>\r\n    <td>+ - &gt; 40% ของ Pre-Procedure</td>\r\n    <td align=\"center\">0</td>\r\n    <td> มีอาการมาก ได้รับยาแล้วยังไม่หาย</td>\r\n    <td align=\"center\">0</td>\r\n    </tr>\r\n  <tr>\r\n    <td rowspan=\"3\" valign=\"top\">2. O<sub>2</sub> Sat</td>\r\n    <td> &gt; 95% ขณะ Room air</td>\r\n    <td align=\"center\">2</td>\r\n    <td rowspan=\"3\" valign=\"top\">6. Pain</td>\r\n    <td>ไม่มีอาการปวดเสียด เจ็บแน่นท้อง หน้าอก</td>\r\n    <td align=\"center\">2</td>\r\n    </tr>\r\n  <tr>\r\n    <td> ให้ O<sub>2</sub>&nbsp;&nbsp;&nbsp;&nbsp;O<sub>2</sub>Sat > 92%</td>\r\n    <td align=\"center\">1</td>\r\n    <td>มีอาการปวดเสียด เจ็บแน่นท้อง หน้าอก</td>\r\n    <td align=\"center\">1</td>\r\n    </tr>\r\n  <tr>\r\n    <td> ให้ O<sub>2</sub>&nbsp;&nbsp;&nbsp;&nbsp;O<sub>2</sub>Sat > 92%</td>\r\n    <td align=\"center\">0</td>\r\n    <td>มีอาการปวดเสียด เจ็บแน่นท้อง หน้าอกมาก</td>\r\n    <td align=\"center\">0</td>\r\n    </tr>\r\n  <tr>\r\n    <td rowspan=\"3\" valign=\"top\">3. Conscious</td>\r\n    <td> ตื่นดี</td>\r\n    <td align=\"center\">2</td>\r\n    <td rowspan=\"3\" valign=\"top\"> 7. Bleeding</td>\r\n    <td>No bleeding per oral / Rectum</td>\r\n    <td align=\"center\">2</td>\r\n    </tr>\r\n  <tr>\r\n    <td> หลับปลุกตื่น</td>\r\n    <td align=\"center\">1</td>\r\n    <td>Bleeding per oral / Rectum</td>\r\n    <td align=\"center\">1</td>\r\n    </tr>\r\n  <tr>\r\n    <td> ไม่ตอบสนอง ไม่รุ้สึกตัว</td>\r\n    <td align=\"center\">0</td>\r\n    <td>&nbsp;</td>\r\n    <td align=\"center\">&nbsp;</td>\r\n    </tr>\r\n  <tr>\r\n    <td rowspan=\"3\" valign=\"top\">4. Respiration</td>\r\n    <td> หายใจได้ปกติ</td>\r\n    <td align=\"center\">2</td>\r\n    <td rowspan=\"3\" valign=\"top\">8. Ambulation</td>\r\n    <td> ลุกนั่งได้เอง ไม่เสียนศีรษะ เดินได้เอง ไม่เข</td>\r\n    <td align=\"center\">2</td>\r\n    </tr>\r\n  <tr>\r\n    <td> หายใจไม่ดี</td>\r\n    <td align=\"center\">1</td>\r\n    <td> ต้องการผู้ช่วยประคองให้นั่ง หรือ เดิน</td>\r\n    <td align=\"center\">1</td>\r\n    </tr>\r\n  <tr>\r\n    <td> ไม่หายใจ</td>\r\n    <td align=\"center\">0</td>\r\n    <td> นั่งไม่ได้เลย</td>\r\n    <td align=\"center\">0</td>\r\n    </tr>\r\n</table><br /><div style=\"font-size:14px\"><center>การประเมินผู้ป่วยก่อนกลับบ้าน / หอผู้ป่วย</center>\r\n<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n  <tr>\r\n    <td width=\"10%\">ผู้ป่วยนอก</td>\r\n    <td width=\"90%\">ประเมิน ข้อ 1 - 8 คะแนน = 16 กลับบ้านได้</td>\r\n  </tr>\r\n  <tr>\r\n    <td>&nbsp;</td>\r\n    <td>ประเมิน ข้อ 1 - 8 คะแนน &lt; 16 สังเกตอาการต่อ</td>\r\n  </tr>\r\n  <tr>\r\n    <td>ผู้ป่วยใน</td>\r\n    <td>ประเมิน ข้อ 1 - 7 คะแนน = 14 กลับห่อผู้ป่วยได้้</td>\r\n  </tr>\r\n</table></div>\r\n</div>\r\n</div>\r\n</div>\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Recorded nurse : <value><%= render_value \'recorded_nurse\' %></value></h4>  \r\n\r\n\r\n\r\n	\r\n<div id=\"recorded_date\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;width:250px;margin-left:10px\">\r\n<span class=\"\"><label>Recorded date : </label></span>	\r\n\r\n<value><%= render_value \'recorded_date\' %></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"recorded_time\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Recorded time : </label></span>	\r\n\r\n<value><%= render_value \'recorded_time\' %></value>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2012-11-10 09:35:45','2012-11-10 09:35:45','print',''),(593,'context_menu',268,4,'<%\r\nmodels = get_model\r\n\r\nproviders = (models[:provider]).all :provider_type=>\'1\'\r\n\r\n#providers_links = providers.collect{|i| {:name=>\"<span style=\'background:\\\\#{i.label}\'>\\\\#{i.name}</span>\",:link=>\'index?provider_id=\'+i.id} }\r\nproviders_links = providers.collect{|i| {:name=>i.name,:link=>\'index?provider_id=\'+i.id.to_s} }\r\nproviders_links << {:name=>\"All Providers\",:link=>\'index\'} \r\nproviders_links << {:name=>\"All Detail\",:link=>\'index?detail=true\'} \r\nmenus = [\r\n{:name=>\'By Provider\',:open=>true,:actions=>providers_links},\r\n\r\n{:name=>\'Links\',:open=>true,:actions=>[\r\n{:name=>\'New Appointment\',:service=>\'pathology\',:link=>\'create\'}]}]\r\n%>\r\n<%= show_menu(menus).html_safe %>',NULL,NULL,NULL,'2012-11-11 13:02:40','2013-07-10 10:07:04','context_menu',''),(594,'document_name',281,1,'\'procedure\'',NULL,NULL,NULL,'2012-11-11 13:43:41','2012-11-11 13:43:41',NULL,NULL),(595,'print',277,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    \r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:consignment].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<script src=\"/signature/jquery.signaturepad.min.js\"></script>\r\n<%= javascript_include_tag \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\nvalue {color:#06F}\r\n#page {border:solid 1px; width:960px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n   \r\n    color:#666; font-weight:bold;\r\n}\r\n\r\nvalue.sign{display:inline-block;width:300px;border-bottom:1px solid gray}\r\n\r\n</style>\r\n<body>\r\n<br />\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo.png\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"margin-left:20px; float:left; \">Consignment\r\n    <p>Hospital No :&nbsp;<value><%=patient.hn%></value> Name : <value><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></value> (Age :&nbsp;<value><%= year%> Year <%=month%> Month <%= day%> Day </value>)</h3>\r\n</div><hr />\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p>\r\n<!-- show patient -->\r\n\r\n<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:98%;padding:0px\">\r\n\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n	\r\n<div id=\"diagnosis\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.1em 0;float:left;width:700px; font-size:16px\">\r\n<span class=\"\"><label>Diagnosis : </label></span>	\r\n\r\n<value><%=render_value \'diagnosis\'%></value>\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n	\r\n<div id=\"operation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.1em 0;float:left;width:700px; font-size:16px\">\r\n<span class=\"\"><label>Operation : </label></span>	\r\n\r\n<value><%=render_value \'operation\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"161-F1625050926\" class=\" \" style=\"clear:both;line-height:1.5em\">\r\n		\r\n		<style>\r\nlabel{margin-top:5px;margin-bottom:5px}\r\n</style>\r\nข้าพเจ้าขอแสดงความยินยอมโดยความสมัครใจ ให้คณะแพทย์และบุคลากรทีมสุขภาพของโรง พยาบาลจุฬาลงกรณ์ ที่ได้รับมอบหมายให้มีส่วนร่วมในการดูแล ตรวจ วินิจฉัย และให้การรักษา ข้าพเจ้า ได้ดําเนินการตรวจ วินิจฉัย / รักษา โดยการใช้ยา หรือ เคมีบําบัด หรือ รังสีรักษา หรือ กายภาพบําบัด / รักษาโดยการผ่าตัดเล็กน้อย หรือ ผ่าตัดใหญ่ / ใช้ยาระงับความรู้สึกเฉพาะที่ หรือ ยา ชาฉีดเข้าสันหลัง หรือ การดมยาสลบ \r\n<br/>\r\n<br/>\r\nข้าพเจ้า ได้รับทราบรายละเอียดเกี่ยวกับแผนการตรวจ วินิจฉัยและการรักษาพยาบาลข้างต้น รวมถึง ความเสี่ยง ผลข้างเคียง และ/หรือ ผลที่อาจเกิดขึ้นภายหลังอีกทั้งทางเลือกอื่น ๆ ที่อาจเป็นไปได้อย่าง ชัดเจน จนเป็นที่กระจ่างชัดสําหรับข้าพเจ้าแล้ว และข้าพเจ้าตระหนักดีว่าคณะแพทย์และบุคลากร ทีม สุขภาพ พยาบาล ไม่สามารถรับประกันถึงผลความสําเร็จของการรักษาพยาบาลดังกล่าวได้ \r\n<br/>\r\n<br/>\r\nข้าพเจ้าขอแสดงความยินยอมโดยความสมัครใจให้คณะแพทย์และบุคลากรทีมสุขภาพดังกล่าวข้างต้น สามารถกระทําการอื่น ๆ ด้วยเหตุผล แสดงถึงความจําเป็นในการกระทําดังกล่าว อาทิเช่น การดม ยาสลบ การใช้ยาระงับความรู้สึก การให้เลือด และ / หรือ ผลิตภัณฑ์ของเลือด การตรวจวินิจฉัยทาง รังสีวิทยา การตัดชิ้นเนื้อ หรือส่วนของอวัยวะ และการตรวจรักษาหรืผ่าตัดเพิ่มเติม อย่างทันทีทันใด ข้าพเจ้ายินยอมให้แพทย์และบุคลากรทีมสุขภาพดําเนินการได้ หากเป็นการคํานึงถึงชีวิตและประโยชน์ ของข้าพเจ้าเป็นสําคัญ\r\n<br/>\r\n<br/>\r\nข้าพเจ้าทราบดีว่า โรงพยาบาลจุฬาลงกรณ์เป็นสถาบันฝึกอบรมแพทย์และพยาบาล ย่อมจะมีบุคลากร ทีมสุขภาพ ประกอบด้วย แพทย์ประจําบ้าน แพทย์ประจําบ้านต่อยอด นิสิตแพทย์ นักศึกษาพยาบาล และบุคลากรอื่น ๆ ซึ่งอาจจะเข้ามามีส่วนร่วมดูแล ตรวจ วินิจฉัยและรักษา\r\n<br/>\r\n<br/>\r\nทั้งนี้คณะแพทย์หรือบุคลากรทีมสุขภาพ ได้แจ้งค่าใช้จ่ายโดยประมาณแล้ว แต่หากมีภาวะแทรกซ้อน หรือใช้อุปกรณ์พิเศษเพิ่มเติม ค่าใช้จ่ายจะเพิ่มขึ้น ซึ่งจะต้องแจ้งข้าพเจ้าหรือญาติให้ทราบด้วย\r\n<br/>\r\n<br/>\r\nณ ที่นี้ข้าพเจ้าขอแสดงความ\r\n<br/>\r\n<br/>\r\n	</div>\r\n	\r\n\r\n\r\n	\r\n<div id=\"agreement\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.1em 0;float:left;width:900px\">\r\n<span class=\"\"><label></label></span>	\r\n\r\n<value><%=render_value \'agreement\' %></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"161-F5575601156\" class=\"clear\" >\r\n		\r\n		เพื่อรับการรักษาโดยความสมัครใจไว้ ณ ที่นี้\r\n	</div>\r\n	\r\n<div class=\"clear\"></div>\r\n\r\n<table width=\"940\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tr><td width=\"400\"><div id=\"patient_sign\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:350px; \">\r\n<span class=\"\"><label>ลงชื่อผู้ป่วย : </label></span>	\r\n\r\n<value class=\"sign\"><%=render_value \'patient_sign\' %></value>\r\n</div>\r\n<div id=\"patient_name\" class=\"  portlet \" style=\"margin: 0 0.5em 0 .5em 0;float:left;width:295px;\">\r\n<span class=\"\"><label>ชื่อผู้ป่วย : </label></span>	\r\n\r\n<value><%=render_value \'patient_name\'%></value>\r\n</div>\r\n	\r\n<div id=\"patient_sign_date\" class=\"  portlet \" style=\"width:150px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ลงวันที่ : </label></span>	\r\n\r\n<value><%=render_value \'patient_sign_date\'%></value>\r\n	\r\n</div></td>\r\n<td  width=\"400\">\r\n<div id=\"witness_1\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:350px;\">\r\n<span class=\"\"><label>ลงชื่อพยาน : </label></span>	\r\n\r\n<value  class=\"sign\"><%=render_value \'witness_1\'%></value>	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"witness_name\" class=\"  portlet \" style=\"width:295px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ชื่อพยาน : </label></span>	\r\n<value><%=render_value \'witness_name\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"witness_sign_date\" class=\"  portlet \" style=\"width:150px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ลงวันที่ : </label></span>	\r\n\r\n<value><%=render_value \'witness_sign_date\'%></value>	\r\n	\r\n\r\n</div>\r\n\r\n</td>\r\n</tr><tr>\r\n<td  width=\"400\">\r\n<div id=\"physician_sign\" class=\"  portlet \" style=\"width:705px;margin: 0 0.5em 0.5em 0;float:left;width:350px\">\r\n<span class=\"\"><label>ลงชื่อแพทย์ ผู้ให้ข้อมูล : </label></span>	\r\n\r\n<value  class=\"sign\" ><%=render_value \'physician_sign\'%></value>	\r\n	\r\n\r\n</div>\r\n\r\n<div id=\"physician_name\" class=\"  portlet \" style=\"width:295px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ชื่อแพทย์ผู้ให้ข้อมูล : </label></span>	\r\n<value><%=render_value \'physician_name\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"physician_sign_date\" class=\"  portlet \" style=\"width:150px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ลงวันที่ : </label></span>	\r\n\r\n<value><%=render_value \'physician_sign_date\'%></value>	\r\n\r\n</div>\r\n</td>\r\n<td  width=\"400\">\r\n<div id=\"assistant_sign\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:350px\">\r\n<span class=\"\"><label>ลงชื่อวิสัญญีแพทย์ : </label></span>	\r\n\r\n<value  class=\"sign\"><%=render_value \'assistant_sign\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"assistant_name\" class=\"  portlet \" style=\"width:295px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ชื่อวิสัญญีแพทย์ : </label></span>	\r\n<value><%=render_value \'assistant_name\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"assistant_sign_date\" class=\"  portlet \" style=\"width:150px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ลงวันที่ : </label></span>	\r\n\r\n<value><%=render_value \'assistant_sign_date\'%></value>	\r\n\r\n</div>\r\n</td>\r\n</tr>\r\n\r\n</table>	\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n	\r\n\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n	\r\n\r\n\r\n\r\n	\r\n	<div id=\"161-F4368260082\" class=\" \" style=\"clear:both;line-height:1.5em\">\r\n		<br/>\r\n		<hr/>\r\nในกรณีที่ผู้ป่วยอยู่ในภาวะที่มิอาจให้ความยินยอมได้ตามปกติ แพทย์ได้อธบายข้อความดังกล่าวข้าง ต้นให้แก่ผู้แทนโดยชอบธรรมของผู้ป่วยที่จะตัดสินใจแทนผู้ป่วยได้รับทราบแล้วและขอแสดงความ\r\n	</div>\r\n	\r\n\r\n<br />\r\n	\r\n<div id=\"representor_agreement\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.1em 0;float:left;width:350px;\">\r\n<span class=\"\"><label></label></span>	\r\n\r\n<value><%=render_value \'representor_agreement\'%></value>		\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"161-F0624190508\" class=\" \" style=\"clear:both;\">\r\n		\r\n		เพื่อรับการตรวจรักษาดังกล่าวไว้​ณ​ที่นี้\r\n	<br/>\r\n<br/>\r\n	</div>\r\n	\r\n\r\n\r\n	\r\n<div id=\"representer_sign\" class=\"  portlet \" style=\"width:705px;margin: 0 0.5em 0.5em 0;float:left;width:350px\">\r\n<span class=\"\"><label>ลงชื่อผู้แทนโดยชอบธรรม : </label></span>	\r\n\r\n\r\n<value  class=\"sign\"><%=render_value \'representer_sign\'%></value>	\r\n	\r\n</div></div>\r\n\r\n\r\n	\r\n	<div id=\"161-F8365073067\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"representer_name\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;\">\r\n<span class=\"\"><label>ชื่อผู้แทนโดยชอบธรรม : </label></span>	\r\n<value><%=render_value \'representer_name\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"representer_relation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;\">\r\n<span class=\"\"><label>เกี่ยวข้องเป็น :</label></span>	\r\n<value><%=render_value \'representer_relation\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n	\r\n<div id=\"representer_sign_date\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ลงวันที่ : </label></span>	\r\n\r\n<value><%=render_value \'representer_sign_date\'%></value>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n\r\n\r\n\r\n<div class=\"clear\">\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</div>\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2012-11-15 15:02:49','2012-11-15 15:02:49','print',''),(596,'document_name',282,1,'\'prick_test\'',NULL,NULL,NULL,'2012-11-20 03:34:28','2012-11-20 03:34:28',NULL,NULL),(597,'display',193,3,'<style>\r\n.red{color:red}\r\n</style>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  models = get_model\r\n  \r\n  @patient_module = @module_model.find(params[:id])\r\n  record = (models[this.table_name.to_sym]).find(@patient_module.module_id)\r\n  @show=true\r\n  \r\n%>\r\n<%  @appointment_module = @module_model.find(@patient_module.parent_id)\r\n\r\n  if @appointment_module\r\n   module_name = @current_project.name+\'#\'+ \'pre_scope\' \r\n   @pre_scope_module = @module_model.first(:parent_id=>@patient_module.parent_id,:module_name=>module_name)\r\n   \r\n   if @pre_scope_module\r\n   \r\n   @pre_scope = (models[:pre_scope]).find(@pre_scope_module.module_id)\r\n\r\n%><% end %>\r\n<% end %>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<% if @pre_scope %>\r\n<div style=\"border:1px solid gray;color:gray;padding:10px\">\r\n    Pre scope : \r\n    BP = <span class=\"red\"><%=@pre_scope.bp%>/<%=@pre_scope.di%></span> mmHg,\r\n    PR = <span class=\"red\"><%=@pre_scope.pr%></span>,\r\n    RR = <span class=\"red\"><%=@pre_scope.rr%></span>,\r\n    O2sat = <span class=\"red\"><%=@pre_scope.o2sat%></span>\r\n    \r\n    <span class=\"right\"><%= @pre_scope.created_at %></span>\r\n</div>\r\n<% end %>\r\n\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<% if @pre_scope.bp==nil or @pre_scope.bp==nil or  @pre_scope.di==nil or  @pre_scope.pr==nil or  @pre_scope.rr==nil  %>\r\n<div style=\"border:1px solid red;color:red;margin:10px\">No vital sign for prescope !! </div>\r\n<% end %>\r\n\r\n\r\n<script>\r\n\r\nfunction getScore(name){\r\n    v = $(\"#data-\"+name);\r\n    if(v.val()){\r\n        return parseInt(v.val());\r\n    }\r\n    return 0;\r\n}\r\n\r\nfunction refresh_point(){\r\n           \r\n    score = 0 ;\r\n    \r\n    bp_std = 100;\r\n    di_std = 100;\r\n    hr_std = 100;\r\n    rr_std = 100;\r\n    \r\n    <% if @pre_scope %>\r\n    \r\n    bp_std = <%=@pre_scope.bp%>;\r\n    di_std = <%=@pre_scope.di%>;\r\n    hr_std = <%=@pre_scope.pr%>;\r\n    rr_std = <%=@pre_scope.rr%>;\r\n    \r\n    <% end %>\r\n    \r\n    ts = 2;\r\n    \r\n    v = Math.abs((1.0*bp_std-getScore(\"bp\"))/bp_std);\r\n  \r\n    \r\n    if(v<.2)s=2;\r\n    else\r\n        if(v<.4)s=1;\r\n          else s=0;\r\n    if(s<ts)ts = s;    \r\n        \r\n    v = Math.abs((1.0*di_std-getScore(\"diastolic\"))/di_std);\r\n    \r\n    \r\n    if(v<.2)s=2;\r\n    else\r\n        if(v<.4)s=1;\r\n          else s=0;\r\n    if(s<ts)ts = s; \r\n    \r\n    v = Math.abs((1.0*hr_std-getScore(\"pr\"))/hr_std);\r\n   \r\n    \r\n    if(v<.2)s=2;\r\n    else\r\n        if(v<.4)s=1;\r\n          else s=0;\r\n    if(s<ts)ts = s; \r\n\r\n    v = Math.abs((1.0*rr_std-getScore(\"rr\"))/rr_std);\r\n    \r\n    \r\n    if(v<.2)s=2;\r\n    else\r\n        if(v<.4)s=1;\r\n          else s=0;\r\n    if(s<ts)ts = s; \r\n    \r\n    $(\"#data-vital_sign\").val(ts);    \r\n    \r\n    score = ts;\r\n    \r\n    v = getScore(\"o2sat\");\r\n    if(v>95)score+=2;\r\n    else\r\n        if(v>92)score+=1;\r\n        \r\n        \r\n    \r\n    score += getScore(\"conscious\");       \r\n    score += getScore(\"respiration\"); \r\n    score += getScore(\"nausea_vomiting\"); \r\n    score += getScore(\"pain\"); \r\n    score += getScore(\"ambulation\"); \r\n    score += getScore(\"bleeding\"); \r\n            \r\n    $(\"#data-point\").val(score);       \r\n}\r\n\r\nfunction post_scope_setup(){\r\n$(\"#data-point\").change(refresh_point);\r\n$(\"#data-bp\").change(refresh_point); \r\n$(\"#data-diastolic\").change(refresh_point);\r\n$(\"#data-pr\").change(refresh_point);\r\n$(\"#data-rr\").change(refresh_point);\r\n$(\"#data-o2sat\").change(refresh_point);\r\n$(\"#data-o2sat_on_o2\").change(refresh_point);\r\n$(\"#data-conscious\").change(refresh_point);\r\n$(\"#data-respiration\").change(refresh_point);\r\n$(\"#data-nausea_vomiting\").change(refresh_point);\r\n$(\"#data-pain\").change(refresh_point);\r\n$(\"#data-ambulation\").change(refresh_point);\r\n$(\"#data-bleeding\").change(refresh_point);\r\n\r\n}\r\n</script>',NULL,NULL,NULL,'2012-11-20 08:34:25','2012-11-20 08:34:25','display',''),(598,'document_name',283,1,'\'test\'',NULL,NULL,NULL,'2012-11-23 05:06:39','2012-11-23 05:06:39',NULL,NULL),(601,'index',285,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-11-24 04:56:16','2012-11-24 04:56:16',NULL,NULL),(602,'layout',285,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-11-24 04:56:16','2012-11-24 04:56:16',NULL,NULL),(609,'document_name',289,1,'\'test\'',NULL,NULL,NULL,'2012-11-24 12:36:21','2012-11-24 12:36:21',NULL,NULL),(612,'index',291,2,'<style>\r\n.dashboard-widget-group{padding:0 110px 0 110px;margin:33px 0 30px}.dashboard-widget-group .row-fluid{max-width:974px}.widget-holder,.dashboard-widget-placeholder{position:relative;display:inline-block;width:300px;height:248px;margin:10px;background-color:rgba(46,53,61,0.25);border:1px solid #ccc;-webkit-border-radius:8px;-moz-border-radius:8px;border-radius:8px;-webkit-box-shadow:0 1px 0 rgba(225,225,225,0.2),inset 1px 1px 1px rgba(225,225,225,0.1),1px 0 0 rgba(225,225,225,0.1);-moz-box-shadow:0 1px 0 rgba(225,225,225,0.2),inset 1px 1px 1px rgba(225,225,225,0.1),1px 0 0 rgba(225,225,225,0.1);box-shadow:0 1px 0 rgba(225,225,225,0.2),inset 1px 1px 1px rgba(225,225,225,0.1),1px 0 0 rgba(225,225,225,0.1)}.widget-holder.ui-sortable-helper,.dashboard-widget-placeholder.ui-sortable-helper{background-image:url(\'../../images/photon/widget_bck.png\');-webkit-box-shadow:5px 5px 35px #000;-moz-box-shadow:5px 5px 35px #000;box-shadow:5px 5px 35px #000}.widget-holder.widget-white{background-color:transparent;background-image:url(\"../../images/photon/login_bck2.jpg\");-webkit-box-shadow:none;-moz-box-shadow:none;box-shadow:none;overflow:visible}.widget-holder.widget-white.ui-sortable-helper{-webkit-box-shadow:5px 5px 35px #000;-moz-box-shadow:5px 5px 35px #000;box-shadow:5px 5px 35px #000}.widget-area{position:absolute;top:-1px;left:0;width:100%;height:100%}.widget-area ul{list-style:none;margin:0;padding:0;-webkit-box-sizing:border-box;-moz-box-sizing:border-box;box-sizing:border-box;text