ULL,'2012-12-03 16:14:08','2012-12-03 16:14:08',NULL,NULL),(637,'index',315,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2012-12-07 04:20:05','2012-12-07 04:20:05',NULL,NULL),(638,'layout',315,4,'<%=default_layout%>',NULL,NULL,NULL,'2012-12-07 04:20:05','2012-12-07 04:20:05',NULL,NULL),(641,'index',317,2,'<h1> Manage Users & Roles</h1>\r\n\r\n\r\n        <div id=\"tabstrip\">\r\n    				<ul>\r\n						<li class=\"k-state-active\">\r\n							Users\r\n						</li>\r\n					\r\n					\r\n					</ul>\r\n					<div>\r\n                        <div class=\"weather\">\r\n                            <%\r\n                                @users = @current_solution.get_users\r\n                            %>\r\n                            \r\n                            <div class=\"left\">\r\n                            </div>\r\n                            <div class=\"clear\"></div>\r\n                            <div id=\'user-content\'>\r\n                                <%= render :inline=>this.list_user %>\r\n                            </div>\r\n                            <%= link_to \'Create User\',\'create_user\',:id=>\'button-link\',:remote=>true,:update=>\'user-panel\' %>\r\n                            <br/><br/>\r\n                            \r\n                        </div>\r\n					</div>\r\n					\r\n					\r\n				</div>\r\n\r\n            <script>\r\n                $(document).ready(function() {\r\n                    $(\"#tabstrip\").kendoTabStrip({\r\n						animation:	{\r\n							open: {\r\n								effects: \"fadeIn\"\r\n							}\r\n						}\r\n					\r\n					});\r\n                });\r\n            </script>\r\n<div id = \"content\">\r\n..\r\n</div>\r\n\r\n\r\n\r\n<script>\r\n$(document).ready(function() {\r\nrefresh();\r\n});\r\n</script>',NULL,NULL,NULL,'2012-12-12 23:01:11','2012-12-12 23:01:11','index',''),(642,'list_user',317,4,'<div id=\'user-panel\'></div>\r\n<%= tabular :model=>%w{login email created_at last_accessed},:data=>@users do |row,out| \r\n    out[0]= \"\\#{row.login.split(\'@\')[0]}\"\r\n    out<<link_to(\'Edit\',\"update_user?id=\\#{row.id}\",:remote=>true,:update=>\'user-panel\')\r\n    out<<link_to(\'Delete\',\"delete_user?id=\\#{row.id}\",:remote=>true,:update=>\'user-content\',:confirm=>\'Are you sure?\')\r\n    out\r\nend \r\n%>\r\n',NULL,NULL,NULL,'2012-12-13 17:10:52','2012-12-13 17:10:52','list_user',''),(643,'create_user',317,3,'<% \r\n   @user = @current_solution.users.new\r\n\r\n    if request.post? \r\n    \r\n    \r\n   params[:user][:login] = \"\\#{params[:user][:login]}@\\#{@context.name}.\\#{DOMAIN}\" unless params[:user][:login].index \'@\'\r\n   @user.update_attributes params[:user]\r\n   if @user.save\r\n   \r\n   @users = @current_solution.users\r\n%>\r\nNew User has been created.\r\n<%= render :inline=>this.list_user %>\r\n<% else %>\r\n\r\nThere is an error\r\n<ul>\r\n<% @user.errors.full_messages.each do |msg| %>\r\n<li><%= msg %></li>\r\n<% end %>\r\n</ul>\r\n\r\n<% end %>\r\n<% else %>\r\n<div class=\"alert alert-info\">\r\n<h3>New User</h3>\r\n<%= form_for \'user\', :url=>\'create_user\', :remote=>true, :html=>{:update=>\'user-content\'} do |f| %>\r\n<%= f.label :login %><%= f.text_field \'login\' %><br/>\r\n<%= f.label :password %><%= f.password_field \'password\' %><br/>\r\n<%= f.label :password_confirmation %><%= f.password_field \'password_confirmation\' %><br/>\r\n<%= f.label :email %><%= f.text_field \'email\' %><br/>\r\n<%= f.hidden_field :esm_id, :value=>@current_solution.id  %>\r\n<%= f.submit \'Create User\' ,:class=>bt_class%> | <%=link_to \'Cancel\', \'refresh_user\',:remote=>true,:update=>\'user-content\' %> <br/>\r\n<% end %>\r\n</div>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2012-12-13 17:11:50','2012-12-13 17:11:50','create_user',''),(644,'update_user',317,3,'<% \r\n   @user = @current_solution.users.find(params[:id])\r\n\r\n    if request.post? \r\n    \r\n    \r\n   params[:user][:login] = \"\\\\#{params[:user][:login]}@\\\\#{@context.name}.\\\\#{DOMAIN}\" unless params[:user][:login].index \'@\'\r\n   @user.update_attributes params[:user]\r\n   if @user.save\r\n   \r\n   @users = @current_solution.users\r\n%>\r\nUser has been updated.\r\n<%= render :inline=>this.list_user %>\r\n<% else %>\r\n\r\nThere is an error\r\n<ul>\r\n<% @user.errors.full_messages.each do |msg| %>\r\n<li><%= msg %></li>\r\n<% end %>\r\n</ul>\r\n\r\n<% end %>\r\n<% else %> \r\n<div class=\"alert alert-info\">\r\n<h3>Update User</h3>\r\n<%= form_for \'user\', :url=>\"update_user?id=\\\\#{@user.id}\", :remote=>true, :html=>{:update=>\'user-content\'} do |f| %>\r\n<%= f.label :login %><%= f.text_field \'login\' %><br/>\r\n<%= f.label :email %><%= f.text_field \'email\' %><br/>\r\n<%= f.hidden_field :esm_id, :value=>@current_solution.id  %>\r\n<%= f.submit \'Update User\',:class=>bt_class %>| <%=link_to \'Cancel\', \'refresh_user\',:remote=>true,:update=>\'user-content\' %> <br/>\r\n<% end %>\r\n</div>\r\n<% end %>\r\n',NULL,NULL,NULL,'2012-12-13 17:12:06','2012-12-13 17:12:06','update_user',''),(645,'refresh_user',317,3,'<%\r\n@users = @current_solution.get_users\r\n%>\r\n<%= render :inline=>this.list_user %>\r\n',NULL,NULL,NULL,'2012-12-13 17:12:19','2012-12-13 17:12:19','refresh_user',''),(646,'delete_user',317,3,'<%\r\n@user = @current_solution.users.find(params[:id])\r\n@user.destroy \r\n@users = @current_solution.get_users\r\n%>\r\nUser has been deleted.\r\n<%= render :inline=>this.list_user %>\r\n<%= Time.now %>',NULL,NULL,NULL,'2012-12-13 17:12:33','2012-12-13 17:12:33','delete_user',''),(647,'form',251,3,'\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n  \r\n%>\r\n<div id=\'prescope\' >Loading..PreScope information</div>\r\n<script>\r\n\r\n<%\r\n\r\n url = \"../PreScope/pre_scope_detail?id=\\\\#{params[:id]}\"\r\n url = \"../PreScope/pre_scope_detail?parent_id=\\\\#{params[:parent_id]}\" if params[:parent_id]\r\n \r\n%>\r\n\r\n$.ajax({\r\n  url: \"<%=url%>\",\r\n  context: document.body\r\n}).done(function(data) { \r\n  $(\'#prescope\').html(data);\r\n  var d = new Date(pre_scope[\"npo_since\"]+\"T\"+pre_scope[\"nop_at\"].split(\"T\")[1]);\r\n  var n =  new Date();\r\n  a = Math.round((n-d)/3600000);\r\n  $(\'#data-npotime\').val(a+7);\r\n  \r\n});\r\n</script>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n\r\nsedative = [\'dormicum\',\'pethidine\',\'diprivan\',\'valium\',\'buscopan\',\'plasil\',\'fentanyl\',\'other\']\r\nfunction check_sedative(ele){\r\n   check = ele.prop(\"checked\");\r\n   id = ele.prop(\"id\");\r\n   t = id.split(\'-\')[1];\r\n   if(check)\r\n   $(\".\"+t+\'\').css(\"display\",\"block\");\r\n   else\r\n   $(\".\"+t+\'\').css(\"display\",\"none\");\r\n}\r\n\r\nfor(i=0;i<sedative.length;i++){\r\n t = sedative[i];  \r\n ele = $(\'#data-\'+t);\r\nele.change(function(){\r\n    check_sedative($(this));\r\n});\r\n check_sedative(ele);\r\n}\r\n//$(\'#data-dormicum_mg\').val(323)\r\n//$(\'#data-dormicum_mg\').prop(\'disabled\', true);\r\n//$(\'#data-dormicum_num\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_mg\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_num\').prop(\'disabled\', true);\r\n\r\n//1|Pharynx\r\n//2|Esophagus\r\n//3|EGJ\r\n//4|Fundus\r\n//5|Cardia\r\n//6|Body\r\n//7|Antrum\r\n//8|1st Duodenum\r\n//9|Sphincter of oddi\r\n//10|2nd Duodenum\r\n//11|3rd Duodenum\r\n//12|4th Duodenum\r\n//13|Proximal Jejunum\r\n//14|Distal Jejunum\r\n\r\nvar scope_list = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n\r\n\r\nfunction update(ele){\r\n   for(i=0;i<scope_list.length;i++){\r\n      $(\".\"+scope_list[i]).css(\"display\",\"none\");\r\n   }\r\n    index = $(ele).prop(\"selectedIndex\");\r\n   for(i=0;i<index;i++){\r\n       $(\".\"+scope_list[i]).css(\"display\",\"block\");\r\n   }\r\n}\r\n\r\nupdate($(\'#data-scope\'));\r\n\r\n$(\"#data-scope\").change(function(){\r\nupdate(this);\r\n});\r\n\r\n\r\n$(\".diag\").change(function(){\r\n    \r\n   e = $(\"#data-\"+this.id).val();\r\n   p = $(\"#data-patient_status\");\r\n   if(e==\"1\"){\r\n    $.sticky(\"Select Abnormal\", {autoclose : 5000, position: \"top-right\" });\r\n     p.val(\"Abnormal\");    \r\n   }\r\n});\r\n\r\n\r\n\r\n$(\'#data-diagnosis_group\').bind(\"change\", function() {\r\n       v = $(this).val() \r\n    //   alert(v)\r\n       if(v!=\'Normal\'){\r\n           $(this).val(v.replace(\'Normal|\',\'\')) \r\n          $(\'#update_diagnosis_group_item_0\').attr(\'checked\', false);\r\n       }\r\n       \r\n        v = $(this).val() \r\n        var $cbx = $(\"#data-diagnosis_note\").data(\"kendoComboBox\")\r\n        $cbx.value(v.replace(/\\\\|/g,\',\'))\r\n     \r\n \r\n });\r\n \r\n\r\n</script>',NULL,NULL,NULL,'2012-12-16 05:19:40','2012-12-16 05:19:40','form',''),(648,'create',214,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n     if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n    \r\n    rec1 = model.where(:hn=>params[:record][:hn]).first\r\n    # rec2 = model.where(:public_id=>params[:record][:public_id]).first\r\n    # if rec1!=nil or rec2 != nil\r\n    if rec1!=nil\r\n        # return_url = \"\\\\#{return_url}&patient_id=\\\\#{rec1.id}\"\r\n    %>\r\n    \r\n<span style=\"color:red\"><b>Existing HN or Public ID</b></span><br/>\r\nWill be redirect in 3 seconds\r\n<meta http-equiv=\"Refresh\" content=\"3; url=<%= return_url.html_safe %>\">\r\n    <%\r\n    else\r\n    \r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n   \r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n    end\r\n\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2012-12-16 17:13:17','2013-07-23 13:48:33','create',''),(649,'context_menu',235,4,'<%\r\n     id = params[:parent_id]\r\n     id = params[:id] if params[:id]\r\n     ret_url = !params[:return].nil? ? params[:return] : \'../Home/index\'\r\n%>\r\n<div id=\"context-menu-panel\">\r\n</div>\r\n<script>\r\n         $.ajax({\r\n    	  url: \'../Home/context_menu_partial?id=<%=id%>&mode=module&return=<%= ret_url %>\',\r\n		 success: function(data){\r\n          $(\'#context-menu-panel\').html(data);  \r\n		  }\r\n		});\r\n</script>',NULL,NULL,NULL,'2012-12-17 00:15:04','2012-12-17 00:15:04','context_menu',''),(650,'pre_scope_detail',188,3,'\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %><%\r\n begin\r\nmodels = get_model\r\n\r\n   \r\n   if params[:parent_id]\r\n    @appointment_module = @module_model.find(params[:parent_id])\r\n   else\r\n    @caller_module = @module_model.find(params[:id])\r\n    @appointment_module = @module_model.find( @caller_module.parent_id)\r\n    params[:parent_id] = @caller_module.parent_id\r\n   end\r\n \r\n   if @appointment_module\r\n   module_name = @current_project.name+\'#\'+ \'pre_scope\' \r\n   @pre_scope_module = @module_model.first(:parent_id=>params[:parent_id],:module_name=>module_name)\r\n   @pre_scope = (models[:pre_scope]).find(@pre_scope_module.module_id)\r\n   @app = (models[:appointment]).find(@appointment_module.module_id)\r\n   procedure = models[:procedure].find( @app.procedure )\r\n   if @pre_scope\r\n%>\r\n <div class=\"alert alert-block alert-warning\" >\r\n<table width=\"100%\"><tr>\r\n<td>\r\nPlan procedure : <%=procedure.name  if procedure%>\r\n</td>\r\n<td>\r\nสิทธิผู้ป่วย : <%= @pre_scope.finance %><br/>  \r\n</td>\r\n<td>\r\n<span style=\"color:red\"> Anticoaglant drug : <b><%= @pre_scope.on_anticoaglant_anti_platelet.split(\'|\').join(\", \") if @pre_scope.on_anticoaglant_anti_platelet%> </b></span>\r\n\r\n</td>\r\n\r\n     <%\r\n     if @pre_scope.previous_illness and @pre_scope.previous_illness.index(\"HIV\") or @pre_scope.previous_illness.index(\"Hepatitis\")\r\n      %>\r\n    <td>\r\n      <font style=\"color:red\">Disease : <b ><%=@pre_scope.previous_illness.split(\"|\").join(\", \") %></b></font></td>\r\n      <%\r\n  end\r\n  \r\n  %>\r\n    \r\n</tr>\r\n</table>\r\n</div>\r\n<script>\r\npre_scope = <%=@pre_scope.to_json.html_safe%>;\r\n</script>\r\n<% end %>\r\n<% end %>\r\n\r\n<% rescue %>\r\n<div class=\"alert alert-block alert-warning\" >Require Prescope Information</div>\r\n<% end %>\r\n',NULL,NULL,NULL,'2012-12-17 14:17:40','2012-12-17 14:17:40','pre_scope_detail',''),(651,'attachment',226,2,'\r\n<style>\r\n.card{\r\n    width:300px;\r\n    float:left;\r\n}\r\n\r\n</style>\r\n\r\n<%\r\n   attachments  = get_model[:attachment].sort(\'created_at desc\').all(:limit=>100)\r\n   for i in attachments\r\n%>\r\n<div class=\"card\">\r\n<img src=\"<%= i.path%>\" >\r\n<%= i.id  %><br/>\r\n<%= i.title  %><br/>\r\n<%= i.created_at  %>\r\n</div>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2012-12-19 03:03:03','2012-12-19 03:03:03','attachment',''),(652,'form',187,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n\r\n<div id=\'prescope\' >Loading..PreScope information</div>\r\n<script>\r\n\r\n<%\r\n\r\n url = \"../PreScope/pre_scope_detail?id=\\\\#{params[:id]}\"\r\n url = \"../PreScope/pre_scope_detail?parent_id=\\\\#{params[:parent_id]}\" if params[:parent_id]\r\n \r\n%>\r\n\r\n$.ajax({\r\n  url: \"<%=url%>\",\r\n  context: document.body\r\n}).done(function(data) { \r\n  $(\'#prescope\').html(data);\r\n\r\n});\r\n</script>\r\n<span style=\"float:right\">\r\n<%= link_to \"Connect Monitor\", \"#\",:id=>\'connect_monitor_btn\',:class=>\'btn btn-warning\' %>\r\n</span>\r\n\r\n<div id=\"update\"></div>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n\r\n$(\'#connect_monitor_btn\').click(function(){\r\n    \r\n    $.ajax({\r\n  url: \"../Monitor/select_station\",\r\n  context: document.body\r\n}).done(function(content) {\r\n  $(\'#update\').append(content);\r\n    refresh_remote();\r\n});\r\n    \r\n})\r\n\r\n\r\n\r\n\r\n</script>',NULL,NULL,NULL,'2012-12-19 04:32:11','2012-12-19 04:32:11','form',''),(653,'edit',214,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.ta