adius: 3px;\r\n}\r\n\r\ntable.table tr:last-child td:last-child {\r\n    -moz-border-radius-bottomright: 3px;\r\n    -webkit-border-bottom-right-radius: 3px;\r\n    border-bottom-right-radius: 3px;\r\n}\r\n\r\ntable.table tr:hover td {\r\n    background: #f2f2f2;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#f2f2f2), to(#f0f0f0));\r\n    background: -moz-linear-gradient(top, #f2f2f2, #f0f0f0);\r\n}\r\n\r\ntable.table tr td {\r\n    padding: 18px;\r\n    border-bottom: 1px solid #e0e0e0; border-left: 1px solid #e0e0e0; border-top: 1px solid #ffffff;\r\n    background: #fafafa;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#fbfbfb), to(#fafafa));\r\n    background: -moz-linear-gradient(top, #fbfbfb, #fafafa);\r\n}\r\n\r\ntable.table tr td:first-child {\r\n    padding-left: 20px;\r\n    border-left: 0;\r\n    t\r\n</style>\r\n<body >\r\n<div class=\"wrapper\">\r\n\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\" style=\"width:100%\">\r\n<div class=\"span12\" style=\"width:100%\">\r\n\r\n\r\n\r\n<div id=\"endoscopy_nurse\" class=\"  portlet \" >\r\n\r\n<span><label>  Patient status : </label></span>\r\n\r\n			<div style=\"margin-top:10px\">\r\n <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" class=\"table\">  \r\n \r\n <tr><th>No.</th>\r\n <th>H/N</th>\r\n <th>ชื่อ-สกุล</th>\r\n <th>Status</th></tr>         \r\n<% list.each_with_index do |i,index|  %>\r\n <tr>  \r\n<td><v><%=index+1%>.</v></td> <td><value><%=i[\'hn\']%></value></td> <td>&nbsp;<value><%=i[\'title\']%>  </value></td> <td>&nbsp;<value><%=i[\'status\']%></value></td> \r\n </tr>     \r\n	\r\n <% end %>\r\n\r\n\r\n\r\n\r\n\r\n</table></div>\r\n</div>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n	\r\n\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n<% end %>\r\n',NULL,NULL,NULL,'2012-12-23 16:06:00','2012-12-23 16:06:00','status_feed',''),(661,'print',278,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    uro_id = pm.module_id\r\n    record = models[:cystoscope].find(uro_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo2.png\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n\r\n<h3 style=\"display:inline-block; margin-left:10px; float:left\">Cystoscope\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <value><%= patient.first_name %> <%= patient.last_name %></value> (Age :&nbsp;<value><%= year%> Year <%=month%> Month <%= day%> Day </value>) </p></h3>\r\n\r\n\r\n	<hr />\r\n\r\n<br />\r\n\r\n<div class=\"clear\"></div>\r\n<div id=\"162-F5429248631\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>General Info</b>\r\n		\r\n	</div>\r\n<div id=\"date\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px\">\r\n<span class=\"\"><label>Date : </label></span>	\r\n\r\n<v><%=render_value \'date\'%></v>\r\n\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"start_at\" class=\"  portlet \" style=\"width:120px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Start at : </label></span>	\r\n\r\n<v><%=render_value \'start_at\'%></v>\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"stop_at\" class=\"  portlet \" style=\"width:120px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Stop at : </label></span>	\r\n\r\n<v><%=render_value \'stop_at\'%></v>\r\n\r\n	\r\n\r\n</div>\r\n\r\n<div id=\"clinic\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:210px\">\r\n<span class=\"\"><label>Clinic : </label></span>	\r\n<v><%=render_value \'clinic\'%></v>\r\n</div>\r\n\r\n<div id=\"records\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Records : </label></span>	\r\n\r\n<v><%=render_value \'records\'%></v>\r\n\r\n</div>\r\n<div id=\"previous_operation\" class=\"  portlet \" style=\"width:210px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Previous Operation : </label></span>	\r\n\r\n<v><%=render_value \'previous_operation\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"indication\" class=\"  portlet \" style=\"width:190px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Indication : </label></span>	\r\n\r\n<v><%=render_value \'indication\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"procedure\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:450px\">\r\n<span class=\"\"><label>Procedure : </label></span>	\r\n\r\n<v><%=render_value \'procedure\'%></v>\r\n\r\n</div>\r\n\r\n\r\n<div id=\"162-F4479600404\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Scope pass through</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"scope_pass_through\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Scope pass through : </label></span>	\r\n\r\n<v><%=render_value \'scope_pass_through\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"scope_pass_through_note\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Scope pass note : </label></span>	\r\n<v><%=render_value \'scope_pass_through_note\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"162-F5099855433\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>External genitalia</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"e_status\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Status : </label></span>	\r\n\r\n<v><%=render_value \'e_status\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"e_status_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Status note : </label></span>	\r\n<v><%=render_value \'e_status_note\'%></v>\r\n</div>\r\n<% if patient.gender==\'1\' %>\r\n	\r\n	<div id=\"162-F1398807693\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Urethral (Male)</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"meatus\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Meatus : </label></span>	\r\n\r\n<v><%=render_value \'meatus\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"meatus_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Meatus note : </label></span>	\r\n<v><%=render_value \'meatus_note\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"penile\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Penile : </label></span>	\r\n\r\n<v><%=render_value \'penile\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"penile_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Penile note : </label></span>	\r\n<v><%=render_value \'penile_note\'%></v>\r\n</div>\r\n\r\n\r\n\r\n	\r\n	<div id=\"162-F8387828829\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"bulbous\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Bulbous : </label></span>	\r\n\r\n<v><%=render_value \'bulbous\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"bulbous_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Bulbous note : </label></span>	\r\n<v><%=render_value \'bulbous_note\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"membranous\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Membranous : </label></span>	\r\n\r\n<v><%=render_value \'membranous\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"membranous_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Membranous note : </label></span>	\r\n<v><%=render_value \'membranous_note\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"162-F7345797581\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n\r\n	\r\n<div id=\"prostate_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Prostate note : </label></span>	\r\n<v><%=render_value \'prostate_note\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"lateral_lobe\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:220px\">\r\n<span class=\"\"><label>Lateral lobe : </label></span>	\r\n\r\n<v><%=render_value \'lateral_lobe\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"size\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:50px\">\r\n<span class=\"\"><label>Size(VF) : </label></span>	\r\n<v><%=render_value \'size\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n	\r\n<div id=\"median_lobe\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Median lobe : </label></span>	\r\n\r\n<v><%=render_value \'median_lobe\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"162-F9979814530\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"bladder_neck\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:180px\">\r\n<span class=\"\"><label>Bladder neck : </label></span>	\r\n\r\n<v><%=render_value \'bladder_neck\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"bladder_neck_note\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Bladder neck note : </label></span>	\r\n<v><%=render_value \'bladder_neck_note\'%></v>\r\n</div>\r\n\r\n<% end %>\r\n<% if patient.gender==\'2\' %>\r\n	<div id=\"162-F1281402045\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Urethral (Female)</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"f_meatus\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Meatus : </label></span>	\r\n\r\n<v><%=render_value \'f_meatus\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"f_meatus_note\" class=\"  portlet \" style=\"width:150px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Meatus note : </label></span>	\r\n<v><%=render_value \'f_meatus_note\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"f_urethra\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Urethra : </label></span>	\r\n\r\n<v><%=render_value \'f_urethra\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"f_urethra_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Urethra note : </label></span>	\r\n<v><%=render_value \'f_urethra_note\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"162-F4196373608\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"f__bladder_neck\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:180px\">\r\n<span class=\"\"><label>Bladder neck : </label></span>	\r\n\r\n<v><%=render_value \'f__bladder_neck\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"f_bladder_neck_note\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Bladder neck note : </label></span>	\r\n<v><%=render_value \'f_bladder_neck_note\'%></v>\r\n</div>\r\n\r\n<% end %>\r\n	\r\n	<div id=\"162-F8440450755\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Ureteric orifice</b>\r\n		\r\n	</div>\r\n\r\n\r\n<div id=\"visualization\" class=\"  portlet \" style=\"width:180px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Visualization : </label></span>	\r\n\r\n<v><%=render_value \'visualization\'%></v>\r\n\r\n\r\n</div>\r\n	\r\n<div id=\"shape\" class=\"  portlet \" style=\"width:140px;margin: 0 0.5em 0.5em 0;float:left;width:120px\">\r\n<span class=\"\"><label>Shape : </label></span>	\r\n\r\n<v><%=render_value \'shape\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"shape_note\" class=\"  portlet \" style=\"width:170px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Shape note : </label></span>	\r\n<v><%=render_value \'shape_note\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n\r\n\r\n	\r\n<div id=\"urine_efflux\" class=\"  portlet \" style=\"width:180px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Left Urine efflux : </label></span>	\r\n\r\n<v><%=render_value \'urine_efflux\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"urine_efflux_r\" class=\"  portlet \" style=\"width:180px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Right Urine efflux : </label></span>	\r\n<v><%=render_value \'urine_efflux_r\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"162-F9900894490\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Bladder</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"mucosa\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Mucosa : </label></span>	\r\n\r\n<v><%=render_value \'mucosa\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"mucosa_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Mucosa note : </label></span>	\r\n<v><%=render_value \'mucosa_note\'%></v>\r\n</div>\r\n\r\n<div id=\"trabeculation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px\">\r\n<span class=\"\"><label>Trabeculation : </label></span>	\r\n\r\n<v><%=render_value \'trabeculation\'%></v>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	<div class=\"clear\"></div>\r\n<div style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:170px\">\r\n<span class=\"\"><label><b>Saccule - <v><%=render_value \'saccule_pos\'%></v></b>  </label></span>	\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"number_saccule\" class=\"  portlet \" style=\"width:100px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Number : </label></span>	\r\n<v><%=render_value \'number_saccule\'%></v>\r\n</div>\r\n\r\n	\r\n\r\n<div id=\"position\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Position : </label></span>	\r\n<v><%=render_value \'position\'%></v>\r\n\r\n</div>\r\n\r\n<div id=\"size_saccule\" class=\"  portlet \" style=\"width:120px;margin: 0 0.5em 0.5em 0;float:left;>\r\n<span class=\"\"><label>Size (cm) : </label></span>	\r\n<v><%=render_value \'size_saccule\'%></v>\r\n\r\n</div>\r\n\r\n	\r\n<div class=\"clear\"></div>\r\n\r\n<div style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:170px\">\r\n<span class=\"\"><label><b>Diverticulum - <v><%=render_value \'diverticulum_pos\'%></v></b>  </label></span>	\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"diverticulum_number\" class=\"  portlet \" style=\"width:100px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Number : </label></span>	\r\n<v><%=render_value \'diverticulum_number\'%></v>\r\n</div>\r\n\r\n	\r\n\r\n<div id=\"position_diver\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>Position : </label></span>	\r\n<v><%=render_value \'position_diver\'%></v>\r\n\r\n</div>\r\n\r\n\r\n<div id=\"diver_size\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px\">\r\n<span class=\"\"><label>Size (mm.) : </label></span>	\r\n<v><%=render_value \'diver_size\'%></v>\r\n</div>\r\n	\r\n\r\n\r\n\r\n\r\n<hr />\r\n<b>Stone</b>\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:12px; border: 0px solid;padding:0px;width:100%;margin:0px;\" >\r\n<table border=\"1\" cellpadding=\"0\" cellspacing=\"0\" bordercolor=\"#E6E6E6\" width=\"100%\" height=\"15\">\r\n  <tr >\r\n  <td align=\"center\"  bgcolor=\"#EEEEEE\">No.</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Size :</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Shape :</td>\r\n   \r\n\r\n  </tr>\r\n<% \r\n\r\n#==================================================================================   START LOOP\r\nfield_name = \'stone\'\r\nrelate_model_name = \'stone\'\r\n\r\ntemp_record = @record \r\ntemp_document = @document\r\n\r\nrelate_doc = get_document relate_model_name\r\nrelate_records = models[relate_model_name.to_sym].find(record[field_name.to_sym])\r\n\r\nif relate_records!=nil \r\n\r\nrelate_records.each_with_index do |i,index|  \r\n\r\n@record = i\r\n@document = relate_doc\r\n\r\n#================================================================================== START LOOP\r\n%>\r\n\r\n<tr >\r\n<td align=\"center\"><%= index+1 %>. </td>\r\n\r\n<td align=\"center\">\r\n  <value class=\"\"><%= @record.stone_size %> mm.</value>\r\n</td>\r\n <td align=\"center\">\r\n<value class=\"\"><%=  @record.stone_shape %></value>\r\n</td>\r\n\r\n  </tr>\r\n\r\n					<% \r\n#======================================================================== END LOOP\r\nend \r\n@record = temp_record\r\n@document = temp_document\r\nend\r\n#======================================================================== END LOOP\r\n%>\r\n</table>\r\n</div>\r\n\r\n<b>Tumor</b>\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:12px; border: 0px solid;padding:0px;width:100%;margin:0px;\" >\r\n<table border=\"1\" cellpadding=\"0\" cellspacing=\"0\" bordercolor=\"#E6E6E6\" width=\"100%\" height=\"15\">\r\n  <tr >\r\n   <td align=\"center\"  bgcolor=\"#EEEEEE\">No.</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Size :</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Type :</td>\r\n      <td align=\"center\" bgcolor=\"#EEEEEE\">Position :</td>\r\n\r\n  </tr>\r\n<% \r\n\r\n#==================================================================================   START LOOP\r\nfield_name = \'tumor\'\r\nrelate_model_name = \'tumor\'\r\n\r\ntemp_record = @record \r\ntemp_document = @document\r\n\r\nrelate_doc = get_document relate_model_name\r\nrelate_records = models[relate_model_name.to_sym].find(record[field_name.to_sym])\r\n\r\nif relate_records!=nil \r\n\r\nrelate_records.each_with_index do |i,index|  \r\n\r\n@record = i\r\n@document = relate_doc\r\n\r\n#================================================================================== START LOOP\r\n%>\r\n\r\n<tr >\r\n<td align=\"center\"><%= index+1 %>. </td>\r\n<td align=\"center\">\r\n  <value class=\"\"><%= @record.tumor_size %> mm.</value>\r\n</td>\r\n <td align=\"center\">\r\n<value class=\"\"><%=  @record.tumor_type %></value>\r\n</td>\r\n<td align=\"center\">\r\n<value class=\"\"><%=  @record.tumor_position %></value>\r\n</td> \r\n\r\n  </tr>\r\n\r\n					<% \r\n#======================================================================== END LOOP\r\nend \r\n@record = temp_record\r\n@document = temp_document\r\nend\r\n#======================================================================== END LOOP\r\n%>\r\n</table>\r\n</div>\r\n\r\n<div id=\"addition\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px\">\r\n<span class=\"\"><label>Addition & Remark : </label></span>	\r\n<v><%=render_value \'addition\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"diagnosis\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px\">\r\n<span class=\"\"><label>Diagnosis : </label></span>	\r\n<v><%=render_value \'diagnosis\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"diagnosis_group\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px\">\r\n<span class=\"\"><label>Diagnosis group : </label></span>	\r\n<v><%=render_value \'diagnosis_group\'%></v>	\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"endoscopist_1\" class=\"  portlet \" style=\"width:240px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Endoscopist 1 : </label></span>	\r\n\r\n<v><%=render_value \'endoscopist_1\'%></v>	\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"_endoscopist_2\" class=\"  portlet \" style=\"width:240px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label> Endoscopist 2 : </label></span>	\r\n\r\n<v><%=render_value \'_endoscopist_2\'%></v>	\r\n\r\n</div>\r\n\r\n	<div id=\"162-F1533339688\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Treatment</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"plan_for_treatment\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;min-height:30px;\">\r\n<span class=\"\"><label>Plan for Treatment : </label></span>	\r\n<v><%=render_value \'plan_for_treatment\'%></v>	\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.picture\r\n        atts = list[0..5].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        for i in atts\r\n    %>\r\n	<div id=\"box\" style=\"width:270px\">\r\n		<img alt=\"1\" src=\"<%=i.path%>\" style=\"width:270px\"/><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2013-01-08 02:16:24','2013-01-08 02:16:24','print',''),(662,'report',146,2,'\r\n<h3>Reports</h3><br/>\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n   select_date = params[:print][\'date(1i)\']+\"-\"+params[:print][\'date(2i)\']+\"-15\" if params[:print]\r\n   select_date = Date.to_mongo(select_date)\r\n%>\r\n\r\n\r\n\r\n<% \r\n    app_model = models[:appointment]\r\n    \r\n    selected_doc = %w{colonoscopy gastroscopy}.collect{|i| \"\\\\#{@current_project.name}#\\\\#{i}\"}\r\n    \r\n    \r\n    apps = app_model.collection.find({:status=>{\'$in\'=>[\'Completed\',\'Recovery\',\'Processing\']},:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}},{:fields=>[:date,:status]}).to_a\r\n    app_ids = apps.collect{|i| i[\'_id\']}\r\n    \r\n    appm_ids = []\r\n    mapps = {}\r\n    module_model.collection.find({:module_id=>{\'$in\'=>app_ids}},:fields=>[:patient_id,:module_id]).each do |i|\r\n    appm_ids << i[\'_id\']\r\n    mapps[i[\'module_id\']] = i\r\n    end\r\n    \r\n    parents = {}\r\n    c = {0=>[],1=>[]}\r\n   \r\n    list = module_model.collection.find({:parent_id=>{\'$in\'=>appm_ids},:module_name=>{\'$in\'=>selected_doc}},{:fields=>[:parent_id,:module_name,:module_id]}).each do |i|\r\n    p = i[\'parent_id\']\r\n    parents[p] = {:modules=>0} unless parents[p]\r\n  \r\n    idx = selected_doc.index(i[\'module_name\'])\r\n    parents[p][:modules] |= 2**idx\r\n    parents[p][:id]=i[\'module_id\']\r\n    c[idx] << i[\'module_id\']\r\n    \r\n    end\r\n    \r\n    status={}\r\n    # colono\r\n    models[:colonoscopy].collection.find({:_id=>{\'$in\'=>c[0]}},{:fields=>[:status]}).each do |i|\r\n        status[i[\'_id\']] = i[\'status\']\r\n    end\r\n    models[:gastroscopy].collection.find({:_id=>{\'$in\'=>c[1]}},{:fields=>[:status]}).each do |i|\r\n        status[i[\'_id\']] = i[\'status\']\r\n    end\r\n\r\n    \r\n    \r\n    months = {\'Elective\'=>[],\'Extratime\'=>[],\'Emergency\'=>[]}\r\n    \r\n    list = apps.collect{|i|\r\n        p = parents[mapps[i[\'_id\']][\'_id\']]\r\n       \r\n        if p \r\n        s = status[p[:id]]\r\n        modules = p[:modules]\r\n        mons = months[s]\r\n        if mons\r\n        m = i[\'date\'].month\r\n        mons[m] = {} unless mons[m]\r\n        mons[m][modules] = 0 unless mons[m][modules]\r\n        mons[m][modules] +=1 \r\n        end\r\n        end\r\n      \r\n  \r\n        i\r\n    }\r\n    list = months\r\n    \r\n    #list = app_model.collection.map_reduce(BSON::Code.new(map_func),BSON::Code.new(reduce_func))\r\n    \r\n    #list = app_model.collection.group({:keyf=>\'function(doc){return {month:doc.date.getMonth(),pm:db.www.patient_module.findOne({module_id:this.id}};}\',\r\n    #      :reduce=>\'function(curr,result){result.count++;}\',\r\n    #      :initial=>{:count=>0},\r\n    #      :finalize=>\'function(result){result.month=result.month}\',\r\n    #      :cond=>{:status=>{\'$nin\'=>[\'No show\',\'Cancelled\']},:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}})\r\n      \r\n%>\r\n<%#list.inspect %>\r\n\r\n<%\r\n   m=[]\r\n   12.times do |i|\r\n   m << i+1\r\n   end\r\n   labels = {1=>\'Colono\',2=>\'Gastro\',3=>\'Colono+Gastro\'}\r\n   \r\nmonths.each_pair do |k,v| \r\n\r\n   v = v[1..-1]\r\n   if v\r\n   l = [1,3,2]\r\n   l.collect!{|i|\r\n    {:name=>labels[i],:data=>v.compact.collect{|j| j[i] }}\r\n   }\r\n   end\r\n   \r\n   \r\n%>\r\n\r\n<div id=\"chart<%=k%>\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n</div>\r\n<br/>\r\n\r\n            <script>\r\n                    $(\"#chart<%=k%>\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"<%= k %> Patients by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=l.to_json.html_safe%>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=m.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                \r\n\r\n            </script>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<%# select_date %>\r\n<% date = Time.now%>\r\nMonthly Report : \r\n<%= form_for \'print\',:url=>\"report\" do |f| %>\r\n<%= f.date_select \'date\',:default=>select_date,:discard_day=>true,:id=>\'today-date\',:order=>[:month,:year] %>\r\n<%= f.submit \'Query\' ,:class=>\'btn btn-small btn-info\'%>\r\n<% end %>\r\n\r\n\r\n<hr/>\r\n<%# select_date %>\r\n<%# params.inspect %>\r\n<%\r\n  if params[:print] \r\n\r\n    \r\n    start_date = select_date.at_beginning_of_month\r\n    end_date = select_date.end_of_month\r\n\r\n    apps =  models[:appointment].where(:date.gte=>start_date,:date.lt=>end_date).all \r\n    \r\n    \r\n    map = {\'Elective\'=>{},\'Extratime\'=>{},\'Emergency\'=>{}}\r\n    \r\n    apps.collect! do |i|\r\n        mapp = module_model.where(:module_id=>i.id).first\r\n        p = patient_model.where(:id=>mapp.patient_id).first :select=>:hn    \r\n      \r\n        colo_flag = false\r\n        gastro_flag = false\r\n        status = nil\r\n        \r\n        mm = module_model.where(:parent_id=>mapp.id).all\r\n        mm.each do |j|\r\n        \r\n        \r\n            if j.module_name.index(\'#gastro\')\r\n                gastro_flag = true \r\n                mo_model = models[:gastroscopy]\r\n                x = mo_model.where(:id=>j.module_id).first :select=>[:status]\r\n                 status = x.status if x\r\n            end\r\n            if j.module_name.index(\'#colo\')\r\n                colo_flag = true \r\n                mo_model = models[:colonoscopy]\r\n                x = mo_model.where(:id=>j.module_id).first :select=>[:status]\r\n                status = x.status if x\r\n            end\r\n            \r\n     \r\n        end\r\n        date = i.date.strftime(\"%Y-%m\")\r\n        if status\r\n        map[status][date] = {:colo=>0,:gastro=>0,:colo_gastro=>0} unless map[status][date]\r\n        if colo_flag and gastro_flag\r\n           map[status][date][:colo_gastro]+=1\r\n        elsif colo_flag\r\n           map[status][date][:colo]+=1\r\n        elsif gastro_flag\r\n            map[status][date][:gastro]+=1\r\n        end\r\n        \r\n        end\r\n        \r\n        [i.date.strftime(\"%Y-%m-%d\"),p.hn,colo_flag,gastro_flag]\r\n        \r\n    end\r\n    \r\n\r\n\r\n\r\n%>\r\n<%\r\n   for i in map.keys\r\n%><h1><%=i%></h1>\r\n<table border=\"1\"><tr><th>Month</th><th>Colonoscopy</th><th>Gastroscopy</th><th>Colonoscopy + Gastroscopy</th></tr>\r\n<%\r\n   for j in map[i].keys\r\n   x = map[i][j]\r\n%>\r\n<tr>\r\n<th><%= j %></th>\r\n<td><%= x[:colo] %></td>\r\n<td><%= x[:gastro] %></td>\r\n<td><%= x[:colo_gastro] %></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n<br/><br/>\r\n<table border=\"1\"><tr><th>Date</th><th>HN</th><th>Colo</th><th>Gastro</th></tr>\r\n<% for i in apps.sort{|a,b| (a[0]+a[1])<=>(b[0]+b[1])} \r\n if i[2] or i[3]\r\n%>\r\n<tr><td><%= i[0] %></td><td><%= i[1] %></td><td><%= i[2] %></td><td><%= i[3] %></td></tr>\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n<% end %>\r\n\r\n<% if false \r\n\r\n  patients =  module_model.all(:module_name=>mname)\r\n%>\r\n\r\n\r\n\r\n<% for mo in forms %>\r\n<h3><%=mo.humanize %> Summary</h3>\r\n\r\n<%\r\n    tmap = {}\r\n    map = {}\r\n    rds = 0 \r\n    mo_model = models[mo.to_sym]\r\n    ves =  module_model.all :select=>[:date,:module_name,:module_id],:date.gte=>Time.now.at_beginning_of_year,:module_name=>\"\\\\#{@current_project.name}#\\\\#{mo}\"  \r\n    for i in ves\r\n        tag = i.date.strftime(\"%Y-%m\")\r\n        data = mo_model.find(i.module_id)\r\n        if data\r\n        g = data.status\r\n        tmap[g] = {} unless tmap[g]\r\n        map[tag]= 0 unless map[tag]\r\n        map[tag]+= 1\r\n        tmap[g][tag] = 0 unless tmap[g][tag]\r\n        tmap[g][tag] += 1 \r\n        rds+=1\r\n        end\r\n    end\r\n    columns = map.keys.sort\r\n    tcolumns= tmap.keys.sort\r\n    data = tcolumns.collect{|i| {:name=>i.split(\'#\')[-1].humanize,:data=>columns.collect{|j| tmap[i][j] }}}\r\n    cdata = columns.collect{|i| map[i]}\r\n%>\r\n<div id=\"chart-<%=mo%>\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n<br/>\r\n<div style=\"float:right\">\r\n\r\n</div>\r\n\r\n\r\n            <script>\r\n                function createChart<%=mo%>() {\r\n                    $(\"#chart-<%=mo%>\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                }\r\n\r\n                $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart<%=mo%>();\r\n                    }, 400);\r\n                });\r\n            </script>\r\n            \r\n<% end %>\r\n\r\n<% end %>',NULL,NULL,NULL,'2013-01-12 17:30:06','2013-01-12 17:30:06','report',''),(663,'form',278,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n\r\n\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2013-01-13 17:57:14','2013-01-13 17:57:14','form',''),(665,'create',241,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n<script type=\"text/javascript\">\r\nalert(\"<%= params.inspect%>\")\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n	interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n	});\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n    	$(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n		url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\' %> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2013-01-15 04:50:44','2013-07-23 13:48:33','create',''),(666,'interpret',240,4,'<%\r\n# input as data {hash of hb} \r\n# output type\r\nd= {:hb_a=>60,:hb_a2=>40,:hb_f=>30}\r\n#d= @params[:data] if @params[:data]\r\n#d= params[0][:data] if params[0][:data]\r\n\r\nd = @record\r\n\r\ndef filter data, type\r\n   return 0 unless data[type] or data[type.to_s]\r\n   return  data[type].to_f if data [type]\r\n   return data[type.to_s].to_f\r\nend\r\n\r\na = filter d, :hb_a\r\na2 = filter d, :hb_a2\r\ne = filter d, :hb_e\r\nf =filter d, :hb_f\r\nbart =filter d, :hb_bart\r\nh = filter d, :hb_h\r\ncs = filter d, :hb_cs\r\nhd = filter d, :hb_d\r\ns = filter d, :hb_s\r\nc = filter d, :hb_c\r\n\r\nmcv = filter d, :mcv_value\r\nhb = filter d, :hb_value\r\nmch = hb\r\n\r\n#return [a,a2,e,f,bart].to_json\r\n\r\nof = nil\r\nof = true if d[:of]==\'positive\'\r\nof = false if d[:of]==\'negative\'\r\ndcip = nil\r\ndcip = true if d[:dcip]==\'positive\'\r\ndcip = false if d[:dcip]==\'negative\'\r\n\r\nr = nil\r\n\r\nr =  \'Normal Hb type\'         if a>0 and a2>0 and a2<4.0 and h+bart < 1 and a>e and cs==0 and mcv>=80 and f<8\r\nr =  \'Possible alpha thal trait\'    if a>0 and a2>0 and a2<4.0 and h+bart == 0 and a>e and cs==0 and mcv==0 and f<6\r\nr  =  \'Possible alpha thal2 trait\'    if a>0 and a2>0 and a2<4.0 and h+bart == 0 and a>e and cs==0 and mcv>=75 and mcv<80 and f<6\r\nr  =  \'Possible alpha thal1 trait\'    if a>0 and a2>0 and a2<4.0 and h+bart == 0 and a>e and cs==0 and mcv<75 and f<6\r\nr  =  \'Hb CS trait\'			if a>0 and a2>=0 and a2<4.0 and a>e and cs>0.5 and f<6\r\nr  =  \'Hb E trait\'			if a>0 and a2>=0 and a2<4.0 and e>=25 and e<36 and f<6\r\nr  =  \'Hb E trait + alpha thal1 trait\' if a>0 and a2>=0 and a2<4.0 and e>=16 and e<25 and f<6\r\nr  =  \'Hb E trait + CS trait\'		if a>0 and a2>0 and a2<4.0 and e>0 and e<36 and cs>0.5  and f<5\r\nr  =  \'AE Bart\\\\\'s disease\' 		if a>0 and a2>0 and a2<4.0 and e>0 and e<18 and f<6 and h+bart>=5 and cs == 0 and mcv <80\r\nr  =  \'AE Bart\\\\\'s CS disease\'		if a>0 and a2>0 and a2<4.0 and e>0 and e<18 and f<6 and h+bart>=5 and cs > 0.5 and mcv <80\r\nr  =  \'Hemoglobin H disease\' 		if a>0 and a2>0 and a2<4.0 and a>e and f<5  and a>e and cs==0 and h+bart >= 5 and mcv<80\r\nr  =  \'Hemoglobin H CS disease\' 	if a>0 and a2>0 and a2<4.0 and a>e and f<5  and a>e and cs>0.5 and h+bart >=5 and mcv<80\r\nr  =  \'Beta thal trait\'		if a>0 and a2>=4.0 and f<11 and cs==0 \r\nr  =  \'Beta thal/Hb E disease\' 			if e >=40 and e < 76 and f >= 5 \r\nr  =  \'Hb E homozygote or Beta thal/Hb E disease\'  	if e >=76 and e < 78 and f < 5\r\nr  =  \'Hb E homozygote\' 				if e >=78 \r\n\r\nr  =  \'Homozygous Beta thal disease\'      			if f > 60 and e == 0  and a == 0 and cs == 0\r\nr  =  \'Fetus with Beta thal/Hb E or Hb E homozygote\'		if f > 60 and e >  0  and a == 0 and cs == 0\r\nr  =  \'Fetus with Hb E trait + Hb CS trait\'			if f > 60 and e >  0  and a > 0  and cs > 0 and bart+h >= 10\r\nr  =  \'Fetus with Hb E trait + possible alpha thal1 trait\'   	if f > 60 and e >  0  and a > 0  and cs == 0 and bart+h >= 10\r\nr  =  \'Fetus with possible alpha thal trait\'         		if f > 60 and e == 0  and a > 0  and cs == 0 and bart+h >= 10\r\nr  =  \'Fetus with Hb E trait\'                        		if f > 60 and e >  0  and a > 0  and cs == 0 and bart+h < 10\r\nr  =  \'Normal Fetal Hb type\'			   		if f > 60 and e == 0  and a > 0  and cs == 0 and bart+h < 10\r\n\r\nr = \"Unknown\" unless r\r\n@r = r\r\n%>\r\n',NULL,NULL,NULL,'2013-01-15 07:25:04','2013-01-15 07:25:04','interpret',''),(667,'form',240