%m/%y\")\r\n   session[:last_his] = nil\r\n   his = nil\r\n   end\r\n   end\r\n%>\r\n\r\n<%= link_to \'Get Patient From HIS\',\'javascript:get_patient_info()\',:class=>bt_class+\" btn-info\" %> \r\n<%# \"HIS login as <b>\\\\#{session[:his]}</b>, give \'-\' for hn to logout\".html_safe if session[:his] %>\r\n\r\n\r\n\r\n<div id=\"his-status\"></div>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n\r\nfunction get_patient_image(){\r\n    ///esm_image/132/attach_to_gallery?p_id=64&field_id=F6478524829&ssid=56215239&_=1361259922808\r\n $.ajax({\r\n  url: \"get_patient_image?doc=132&project=64&ssid=56215239\",\r\n  context: document.body,\r\n  crossDomain: true\r\n  }).done(function(data) {\r\n        $(\'#his-status\').html(\'retriving...\');\r\n        eval(data);\r\n        $(\'#his-status\').html(\'completed\');\r\n  }).fail(function(jqXHR, textStatus) {\r\n    alert(\"error\");\r\n  });\r\n}\r\n\r\nhis_username = \'\'\r\n\r\nfunction get_patient_info(){\r\n    $(\'#his-status\').html(\'connecting...\');\r\n<%\r\nif his \r\n%>\r\n\r\nvar username = \'<%=his%>\'\r\nvar password = \'-\'\r\n\r\n<% else %>\r\nvar username=\'emr\' //prompt(\"Please enter your username\",\"\");\r\nvar password=\'emr\'// prompt(\"Please enter your password\",\"\");\r\n<% end %>\r\nvar hn=prompt(\"Please enter HN\",\"\");    \r\n if(hn==\'\'){ \r\n     \r\n  alert(\"Not enough information!!\");     \r\n       \r\n }else{     \r\n     \r\n $(\'#his-status\').html(\'loading...\');    \r\n $.ajax({\r\n  url: \"get_patient_info?un=\"+username+\"&ps=\"+password+\"&hn=\"+hn+\"&doc_id=<%=@document.id%>\",\r\n  context: document.body,\r\n  crossDomain: true\r\n  }).done(function(data) {\r\n        $(\'#his-status\').html(\'Retriving...\');\r\n    eval(data);\r\n        $(\'#his-status\').html(\'Completed\');\r\n  }).fail(function(jqXHR, textStatus) {\r\n    alert(\"error\");\r\n  });\r\n }\r\n}\r\n\r\n\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2013-02-04 01:51:54','2013-02-04 01:51:54','',''),(707,'get_patient_info',345,3,'<%\r\n\r\n\r\n\r\ndef get_hn i\r\n\r\n  n = \'\'\r\n  y = \'\'\r\n  \r\n  return i if i.size<5 or i.size>9\r\n  if i.index \'/\'  \r\n    t = i.split(\"/\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.index \'-\'  \r\n    t = i.split(\"-\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.size==8\r\n    y = i[0..1].to_i\r\n    y2 = i[-2..-1].to_i\r\n    n = i[3..-1].to_i  \r\n    if y2 > y\r\n      y = y2\r\n      n = i[0..-3].to_i    \r\n    end\r\n  else\r\n    y = i[-2..-1]\r\n    n = i[0..-3]\r\n  end\r\n  \r\n  hn = \"\\\\#{n.to_i.to_s}/\\\\#{y}\"\r\n\r\n  return hn    \r\n\r\nend\r\n\r\n\r\nrequire \'uri\'\r\nrequire \'base64\'\r\n\r\nhis_ip = \"http://170.100.50.240:9292\"\r\nhis_ip = \"http://localhost:9292\"\r\nhis_ip =  get_setting \'his_host\'\r\n\r\nusername = \'jane\'\r\npassword = \'jane\'\r\nhn = 47700094.to_s\r\nusername = params[:un] if params[:un]\r\npassword = params[:ps] if params[:ps]\r\nhn = params[:hn] if params[:hn]\r\n\r\nif hn == \'-\'\r\n  session[:his]=nil\r\n  session[:last_his]=nil\r\n  session.delete \'his\'\r\n  msg=\'logout HIS\'\r\n%>\r\nalert(\"<%=msg%>\");\r\nwindow.location.reload();\r\n<%\r\n  \r\nelse # reset login\r\nif false\r\nunless session[:his]  # if not login then login\r\n\r\n    login_url = his_ip+\'/his/login?username=\'+username+\'&password=\'+password+\'&hn=\'+hn\r\n    uri = URI.parse(login_url)\r\n    http = Net::HTTP.new(uri.host, uri.port); \r\n    http.open_timeout = 5; \r\n    http.read_timeout = 20;\r\n    result= http.get(uri.path+\"?\"+uri.query).body\r\n    if result != \'\'\r\n        object = ActiveSupport::JSON.decode result\r\n        session[:his] = \"\\\\#{username}\" \r\n        session[:last_his] = Time.now\r\n%>\r\n        alert(\'<%=object[\'status\'] %>\')\r\n<%\r\n    end\r\n\r\nend  # end login\r\nend\r\n\r\nsession[:his] = \'emr\'\r\n# get patient info\r\n\r\ninfo_url = his_ip+\'/his/get_patient_abs_info?username=\'+session[:his]+\'&hn=\'+hn\r\n\r\nuri = URI.parse(info_url)\r\nhttp = Net::HTTP.new(uri.host, uri.port); \r\nhttp.open_timeout = 3; \r\nhttp.read_timeout = 15;\r\n\r\nbegin\r\n\r\n    result= http.get(uri.path+\"?\"+uri.query).body\r\n\r\n    if result != \'\'\r\n        object = ActiveSupport::JSON.decode result\r\n        object[\'hn\']=params[:hn];\r\n        if object[\'picture\'] and object[\'s_hn\']\r\n            doc = Document.find(params[:doc_id])\r\n            ssid = Time.now.to_i.to_s+rand(100).to_s\r\n            @document = @current_project.get_document doc.name\r\n            atts =  @document.attach_field_image \'F6478524829\',\"\\\\#{object[\'hn\']}.png\",ssid,StringIO.new(Base64.decode64(object[\'picture\']))\r\n            if atts\r\n%>\r\n    $.ajax({\r\n            url: \'/esm_image/<%=params[:doc_id]%>/attach_to_gallery?p_id=<%=@current_project.id%>&field_id=F6478524829&ssid=<%=ssid%>&upload=true\',\r\n            data: [],\r\n        	dataType: \'script\',\r\n			type: \'GET\',\r\n			error: function (xhr, status, error) {\r\n			alert(error);\r\n			}\r\n	}).done(function(data){\r\n        alert(\"Picture Inserted\");\r\n    });\r\n<%\r\n            end\r\n        end\r\n    \r\n%>\r\nobject = <%=object.to_json.html_safe%>\r\n$(\"#data-hn\").val(object[\'hn\']);\r\n$(\"#data-public_id\").val(object[\'public_id\']);\r\n//alert(object[\'birth_date\']);\r\n$(\"#data-prefix_name\").val(object[\'prefix\']);\r\nif(object[\'title\']&&object[\'title\']!=\'\')\r\n$(\"#data-prefix_name\").val(object[\'title\']);\r\n$(\"#data-first_name\").val(object[\'first_name\']);\r\n$(\"#data-last_name\").val(object[\'last_name\']);\r\n$(\"#data-nationality\").val(object[\'nationality\']);\r\n$(\"#data-nationality\").val(object[\'nationality\']);\r\n$(\"#data-nationality\").val(object[\'nationality\']);\r\n$(\"#data-nationality\").val(object[\'nationality\']);\r\n\r\n$(\"#data-born_address\").val(object[\'born_address\']);\r\n$(\"#data-born_tambon\").val(object[\'born_tambon\']);\r\n$(\"#data-born_amphur\").val(object[\'born_amphur\']);\r\n$(\"#data-born_province\").val(object[\'born_province\']);\r\n$(\"#data-born_zipcode\").val(object[\'born_zipcode\']);\r\n$(\"#data-born_country\").val(object[\'born_country\']);\r\n\r\n$(\"#data-contact_address\").val(object[\'contact_address\']);\r\n$(\"#data-contact_tambon\").val(object[\'contact_tambon\']);\r\n$(\"#data-contact_amphur\").val(object[\'contact_amphur\']);\r\n$(\"#data-contact_province\").val(object[\'contact_province\']);\r\n$(\"#data-contact_zipcode\").val(object[\'contact_zipcode\']);\r\n$(\"#data-contact_country\").val(object[\'contact_country\']);\r\n\r\n$(\"#data-occupation\").val(object[\'occupation\']);\r\n$(\"#data-gender\").val(object[\'gender\']);\r\n$(\"#data-marital_status\").val(object[\'marital\']);\r\n\r\n$(\"#data-tel_home\").val(object[\'tel_home\']);\r\n//$(\"#data-tel_office\").val(object[\'lice_tel\']);\r\n$(\"#data-mobile\").val(object[\'mobile\']);\r\n$(\"#data-email\").val(object[\'email\']);\r\n\r\n\r\n$(\"#data-birth_date\").val(object[\'birth_date\']);\r\n$(\"#data-contact_name\").val(object[\'contact_name\']);\r\n$(\"#data-contact_tel\").val(object[\'contact_tel\']);\r\n$(\"#data-contact_desc\").val(object[\'contact_desc\']);\r\nconsole.log(\'title \'+object[\'title\']);\r\n\r\n    <% else %>\r\n        alert(\"Agent Error\");\r\n    <% end %>\r\n<% rescue  Exception=>e %>\r\nalert(\"Cannot connect Agent <%=e.message%>\");\r\n<% end %>\r\n<% end %>',NULL,NULL,NULL,'2013-02-04 01:52:29','2013-02-04 01:52:29','get_patient_info',''),(709,'document_name',346,1,'\'acute_sinusitis\'',NULL,NULL,NULL,'2013-02-20 04:27:52','2013-02-20 04:27:52',NULL,NULL),(711,'document_name',347,1,'\'survey\'',NULL,NULL,NULL,'2013-02-28 14:16:44','2013-02-28 14:16:44',NULL,NULL),(712,'document_name',348,1,'\'rhinology\'',NULL,NULL,NULL,'2013-02-28 15:29:26','2013-02-28 15:29:26',NULL,NULL),(713,'document_name',349,1,'\'chronic_sinusitis\'',NULL,NULL,NULL,'2013-03-03 07:57:06','2013-03-03 07:57:06',NUL