$(\"#data-effrent_fluid\").val());\r\n total_time_crrt = parseInt($(\"#data-total_time_crrt\").val());\r\n  body_weight = parseInt($(\"#data-body_weight\").val());\r\n \r\n $(\"#data-delivered_lose\").val(effrent_fluid/body_weight/total_time_crrt).toFixed(2);\r\n //alert(intake+output)\r\n}\r\n\r\n$(\"#data-effrent_fluid\").change(function(){\r\nrefresh_form1();\r\n});\r\n$(\"#data-total_time_crrt\").change(function(){\r\nrefresh_form1();\r\n});\r\n$(\"#data-body_weight\").change(function(){\r\nrefresh_form1();\r\n});\r\n\r\n\r\n//net flu + Pre Post dilution + Dialysate flu /24 * weight\r\nfunction refresh_form3(){\r\n\r\n crrt_ufr = parseInt($(\"#data-crrt_ufr\").val());\r\n pre_dilution = parseInt($(\"#data-pre_dilution\").val());\r\n  post_dilution = parseInt($(\"#data-post_dilution\").val());\r\n dfr_crrt = parseInt($(\"#data-dfr_crrt\").val());\r\n  body_weight = parseInt($(\"#data-body_weight\").val());\r\n \r\n  if(isNaN(pre_dilution))\r\n  {\r\n      pre_dilution = 0;\r\n}\r\n  if(isNaN(post_dilution))\r\n  {\r\n      post_dilution = 0;\r\n}\r\n\r\n\r\n \r\n $(\"#data-prescribed_dose\").val((crrt_ufr+pre_dilution+post_dilution+dfr_crrt)/body_weight);\r\n //alert(intake+output)\r\n}\r\n\r\n$(\"#data-crrt_ufr\").change(function(){\r\nrefresh_form3();\r\n});\r\n$(\"#data-pre_dilution\").change(function(){\r\nrefresh_form3();\r\n});\r\n$(\"#data-post_dilution\").change(function(){\r\nrefresh_form3();\r\n});\r\n$(\"#data-dfr_crrt\").change(function(){\r\nrefresh_form3();\r\n});\r\n$(\"#data-body_weight\").change(function(){\r\nrefresh_form3();\r\n});\r\n\r\n\r\n$(\"#data-crrt_date\").change(function(){\r\n    $(\"#record-date\").datepicker().val($(this).val());\r\n});\r\n\r\n\r\n\r\n\r\n\r\n</script>',NULL,NULL,NULL,'2013-09-02 15:09:37','2013-09-02 15:09:37','form',''),(807,'create',389,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n 