n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n    window.location = \"../Home/index\"\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n        window.location = \"../Home/patient_record?id=\"+value\r\n        \r\n	}\r\n    function doSelectNewPatient(value){\r\n        window.location = \"create_new?patient_id=\"+value\r\n    }\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelectNewPatient(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%#this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%# f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> \r\n\r\n<%# link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2013-09-03 17:30:29','2013-09-03 17:30:29','create',''),(808,'show',389,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">Patient Entry</h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n<%= this.display.html_safe %>\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2013-09-03 17:31:34','2013-09-03 17:31:34','show',''),(813,'search',389,3,'<% \r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    models = ehr.load_model\r\n    patient_model = models[:patient]\r\n    module_model = models[:patient_module]\r\n    \r\n   @document = ehr.get_document(\'patient\')\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   model = patient_model\r\n   query = params[:q]\r\n   keys = []\r\n   @document.list_fields.each_with_index do |f,index| \r\n    keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n   end\r\n\r\n   records = model.all({\'$or\'=>keys}.merge!({:limit=>20}))\r\n   \r\n   \r\n params[:return] = \"../../\\\\#{@current_project.name}/Appointment/create\"\r\n   \r\n%><br/>\r\n<%= tabular :data=>records,:model=>labels do |i,out|\r\n\r\nif m = module_model.where(:module_name=>\"\\\\#{@current_project.name}#appointment\",:patient_id=>i.id).first\r\nout<<link_to(\'Detail\',\'javascript:doSelect(\"\'+m.module_id.to_s+\'\")\')\r\nelse\r\nout<<link_to(\'Add New\',\'javascript:doSelectNewPatient(\"\'+i.id.to_s+\'\")\')\r\nend\r\nout\r\nend \r\n\r\n \r\n%><center><a href=\"../../www/Patient/create?return=<%=params[:return]%>\" class=\"<%=bt_class%>\">New Patient</a></center>\r\n',NULL,NULL,NULL,'2013-09-12 14:37:27','2013-09-12 14:37:27','search',''),(814,'create_new',389,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if params[:patient_id]\r\n    # patient_id\r\n    date = Time.now.strftime(\"%d/%m/%Y\")\r\n    doc = get_document this.document_name\r\n    params[\'appointment\'] = {}\r\n    params[:date] = date\r\n    record = model.create :date=>Time.now\r\n    %>\r\n    <%=record.inspect%>\r\n    <%\r\n    \r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>date,:parent_id=>nil,:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n<script>\r\nwindow.location = \"../Home/patient_record?id=<%=record.id%>\"\r\n</script>\r\n<% end %>\r\n',NULL,NULL,NULL,'2013-09-12 16:23:17','2013-09-12 16:23:17','create_new',''),(817,'document_name',392,1,'\'endoscope\'',NULL,NULL,NULL,'2013-10-15 04:47:10','2013-10-15 04:47:10',NULL,NULL),(818,'document_name',393,1,'\'colonoscopy_scope\'',NULL,NULL,NULL,'2013-10-15 04:48:48','2013-10-15 04:48:48',NULL,NULL),(821,'index',395,2,'\r\n<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">LIFE</span>-SCOPE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><img src=\"/gebo/img/gCons/edit.png\" alt=\"\" /><br /> New Encounter</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><img src=\"/gebo/img/gCons/ID.png\" alt=\"\" /><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><img src=\"/gebo/img/gCons/pie-chart.png\" alt=\"\" /><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\',:style=>\'width:120px\' %> &nbsp;<br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n    });\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n   # aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n     aps = ap_model.all(:limit=>10,:order=>\'created_at desc\') \r\n\r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n         public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Waiting\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if true}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{date public_id hn patient provider procedure }.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n    \r\n    \r\n%>\r\n\r\n\r\n<%\r\n\r\n     tmp = waiting\r\n\r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Recently Patients \r\n        <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n        </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n       <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n\r\n        \r\n        </div>\r\n    </div>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %>\r\n<div class=\"clear\"></div>\r\n </div>',NULL,NULL,NULL,'2013-10-15 07:02:45','2013-10-15 07:02:45','',''),(822,'patient_record',395,2,'\r\n<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Medical Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    groups = this.config\r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    \r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n          url: \'<%=url%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n\r\n\r\n\r\n<% else %>\r\nData missing\r\n<% end %>\r\n<br/><br/>\r\n<div class=\"clear\"></div>\r\n<%\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    modules = patient_module_model.all(:parent_id=>pm.id,:patient_id=>pm.patient_id).collect do |i|\r\n        name = i.module_name.split(\"#\")[-1]\r\n        hn = patient.hn\r\n        \r\n        rr = link_to(\"\\\\#{i.date.strftime(\"%d-%m-%Y %H:%M\")} \", \"../\\\\#{name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\")\r\n        rr += \' \'\r\n        #rr += link_to(\"[ Edit ]\", \"../\\\\#{name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\")\r\n        date = i.created_at.strftime(\"%d-%m-%y\")\r\n        \r\n        #show = link_to(\'Show\',\"../\\\\#{name.camelize}/show?id=\\\\#{i.id}&record_name=\\\\#{hn}&return=../Home/patient_record?id=\\\\#{ap}\",:class=>\'btn btn-small\')\r\n        show = link_to(\"Edit \", \"../\\\\#{name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-small\')\r\n        show += \' \'\r\n        show += link_to(\'Print\',\"../\\\\#{name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'btn btn-small\')\r\n\r\n        {:name=>name.humanize,:records=>rr.html_safe,:date=>date,:show=>show,:module_name=>name}\r\n    end\r\n\r\n%>\r\n<div class=\"tabbable tabs-left\" style=\"border:1px solid #ccc; -moz-border-radius: 5px;\r\nborder-radius: 5px;\">\r\n<ul class=\"nav nav-tabs\" style=\"background:#F4F4F4; -moz-border-radius: 5px;border-radius: 5px;\">\r\n<li class=\"active\" ><a href=\"#tab_dashboard\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >Dashboard</a></li>\r\n<%\r\nfor g in groups \r\n   services = g[:actions].collect{|i| [@current_project.get_service(i[:service]), i[:name]]}.compact\r\n   %> \r\n<li class=\"\" ><span style=\"font-size:14px;padding:10px\"><%=g[:name]%></span></li>\r\n   <%\r\n   for st in services\r\n   s = st[0]\r\n   name = st[1]\r\n   n = modules.collect{|i| i if i[:module_name]==s.name }.compact.size\r\n%>\r\n<li class=\"<%#\'active\' if s == services[0]%>\" style=\"border:0px solid;width:150px;overflow:hidden\"><a href=\"#tab_<%=s.id%>\" data-toggle=\"tab\" style=\"font-size:12px; padding:10px\">- <%=name%>\r\n<%= \"(\\\\#{n})\" if n>0 %>\r\n</a></li>\r\n<% end %>\r\n<% end %>\r\n\r\n</ul>\r\n\r\n\r\n<div class=\"tab-content\" style=\"width:520px;border:0px solid;float:left; clear:none;margin-left:-20px;\">\r\n<div class=\"tab-pane  <%= \'active\' if true %>\" style=\"border:0px solid;\" id=\"tab_dashboard\">\r\n<br/><h3>Dashboard</h3>\r\n\r\n<div style=\'float:right;margin-top:-30px\'>\r\n<%# select_tag \'form\', options_for_select(services.collect{|i| [i.title,i.name]})  %>\r\n<%# link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class %>\r\n</div>\r\n\r\n<%= tabular :data=> modules,:model=>[:name,:records,:show] %>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n<%\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n   for s in services\r\n%>\r\n<div class=\"tab-pane  <%# \'active\' if s==services[0] %>\" id=\"tab_<%=s.id%>\"  style=\"border:0px solid;\">\r\n<br/><h3><%=s.title%></h3>\r\n\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class ,:style=>\'float:right;margin-top:-30px\'%>\r\n\r\n<%= tabular :data=> modules.collect{|i| i if i[:module_name]==s.name }.compact ,:model=>[:module_name,:records,:show] %>\r\n\r\n</div>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"tab-pane\" id=\"tab_l2\">\r\n										<p>\r\n											Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nulla et tellus felis, sit amet interdum tellus. Suspendisse sit amet scelerisque dui. Vivamus faucibus magna quis augue venenatis ullamcorper. Proin eget mauris eget orci lobortis luctus ac a sem. Curabitur feugiat, eros consectetur egestas iaculis,\r\n											Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nulla et tellus felis, sit amet interdum tellus. Suspendisse sit amet scelerisque dui. Vivamus faucibus magna quis augue venenatis ullamcorper. Proin eget mauris eget orci lobortis luctus ac a sem. Curabitur feugiat, eros consectetur egestas iaculis,\r\n										</p>\r\n									</div>\r\n									<div class=\"tab-pane\" id=\"tab_l3\">\r\n										<p>\r\n											Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nulla et tellus felis, sit amet interdum tellus. Suspendisse sit amet scelerisque dui. Vivamus faucibus magna quis augue venenatis ullamcorper. Proin eget mauris eget orci lobortis luctus ac a sem. Curabitur feugiat, eros consectetur egestas iaculis,\r\n										</p>\r\n									</div>\r\n								</div>\r\n							</div>\r\n\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<br/><br/>\r\n\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n \r\n',NULL,NULL,NULL,'2013-10-15 07:13:16','2013-10-15 07:13:16','patient_record',''),(825,'print',392,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:endoscope].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n	color:#666;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><h2>Company Logo</h2></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colonoscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n	<p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=record.date_note%></v>&nbsp;&nbsp; Colonoscope by :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n  \r\n   \r\n	  <table width=\"100%\">\r\n	    <tr>\r\n	      <td > <h4 style=\"padding:0px; margin:0px; margin-left:10px\">Status : <%=record[\'status\']%> </h4></td>\r\n	      <td><h4 style=\"padding:0px; margin:0px;margin-left:10px\">Sedation</h4></td>\r\n        </tr>\r\n	    <tr>\r\n      <td width=\"60%\"><p><span style=\"float:left; \"> </span>\r\n        <span style=\"float:left;display:block-inline;\">\r\n				<table width=\"100%\" style=\"margin-left:10px\" >\r\n				<tr>\r\n				  \r\n					<td width=\"300\"><label>Previous opreation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n				 \r\n					<td><label>Bowel Preparation :</label> <v><%=render_value \'bowel_preparation\' %> <%=record[\'bowel_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'bowel_other\'%></v></td>\r\n				</tr>\r\n				<tr>\r\n				\r\n					<td><label>Quality of Preparate :</label> <v><%=record[\'quality_of_preparate\']%></v></td>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \') if record[\'record\']%></v></td>\r\n				\r\n				<tr>\r\n					\r\n					<td width=\"220\"><label>Additional Bowel Preparation :</label> <v><%=render_value \'additional_bowel_preparation\' %> <%=record[\'add_bowel_prep_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'add_bowel_prep_other\'%></v></td>\r\n				</tr>		\r\n				\r\n			</table>	\r\n		</span>\r\n		\r\n \r\n		</p></td>\r\n\r\n<td width=\"40%\"  valign=\"top\">\r\n\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% if record[\'dormicum\']==\'true\'%>\r\n<tr><td>Dormicum : <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'%>\r\n<tr><td>Pethidine : <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'drithpivan\']==\'true\'%>\r\n<tr><td>Drithpivan : <v><%=record[\'drithpivan_mg\']%> mg <%=record[\'drithpivan_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'%>\r\n<tr><td>Diprivan : <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'%>\r\n<tr><td>Valium : <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'%>\r\n<tr><td>Buscopan : <v><%=record[\'buscopan_mg\']%> mg <%=record[\'buscopan_route\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'plasil\']==\'true\'%>\r\n<tr><td>Plasil : <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'%>\r\n<tr><td>Fentanyl : <v><%=record[\'fentanyl_mg\']%> mg <%=record[\'fentanyl_routh\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'other\']==\'true\'%>\r\n<tr><td>Other Note : <v><%=record[\'other_note\']%> </v> </td></tr>\r\n<% end%>\r\n</table></td>\r\n </tr></table>\r\n		\r\n<hr />\r\n\r\n<h4>Scope finding</h4>\r\n&nbsp;&nbsp;<label>Scope pass through : </label></td><td><v><%=render_value \'scope\'%> <i></i></v>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n<label>Pocedure : </label></td><td><v><%=render_value \'procedure\'%></v>\r\n<% if  a = record[\'procedure_other\']  and a !=\"\" %><label>Note : </label><v><%=render_value \'procedure_other\'%> </v><% end%>\r\n<p>Start at : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<p >\r\n<%\r\n    scopes = %w{rectum_scope sigmoid_scope descending_colon_scope transvers_colon_scope ascending_colon_scope cecum_scope terminal_ileum_scope}\r\n    \r\n    scopes.each_with_index do |j,index|\r\n    if index<record.scope.to_i \r\n    tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    text = \"Normal\"\r\n    tag_cls = \'\'\r\n    if render_value(tag) == \'1\'\r\n    	text =  \"Abnormal\"\r\n    	 tag_cls = \'color:red\'\r\n    end\r\n%>\r\n<p><%= j.humanize %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Type:</td><td>Dx:</td><td>Morphology:</td><td>Size:</td><td>Treatment:</td><td>By:</td><td>Clip:</td><td>Patho No:</td><td>Pit:</td><td>by:</td><td> Kudo:</td><td>Vascular:</td><td>by:</td><td>Sano:</td><td>NICE class:</td><td>by:</td><td>Note:</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'endoscopy_dx\']%></v></td><td><v><%=i[\'morphology_type\']%></v></td><td><v><%=i[\'size\']%> cm.</v></td><td><v><%=i[\'treatment\']%></v></td><td> <v><%=i[\'treatment_by\']%></v> </td><td><v><%=i[\'clip\']%></v></td><td><v><%=i[\'patho_number\']%></v></td><td><v><%=i[\'pit_pattern\']%></v></td><td><v><%=i[\'pitt_by\']%></v></td><td><v><%=i[\'kudo_type\']%></v></td><td><v><%=i[\'vascular_pattern\']%></v></td><td><v><%=i[\'vascular_by\']%></v></td><td><v><%=i[\'sano_type\']%></v></td><td><v><%=i[\'nice_classification\']%></v> </td><td><v><%=i[\'niceby\']%></v><td><v><%=i[\'abnormal_note\']%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n<hr />\r\n\r\n\r\n<h4>Note</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<% if a= record[\'scope_note\'] and a !=\"\" %><label>Note : </label><v><%=render_value \'scope_note\'%> </v><% end%>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \') if record[\'diagnosis_group\']%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n<script>\r\nwindow.print()\r\n</script>\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2013-10-15 07:34:43','2013-10-15 07:34:43','print',''),(827,'context_menu',395,4,'<style>\r\nul\r\n{\r\n    list-style-type: none;\r\n    margin-left: 5px;\r\n}\r\n</style>\r\n\r\n<p>\r\n<ul>\r\n<li class=\"ui-menu\"><a href=\"/endo/www/Patient/index\" class=\"btn\" style=\"width:195px;height:35px;margin:5px\"><span class=\"label label-warning\" style=\"float:right\">450</span><img src=\"/gebo/img/gCons/female-user.png\" alt=\"\" style=\"float:left\"/>Patient List</a></li>\r\n<li class=\"ui-menu\"><a href=\"#\" class=\"btn\" style=\"width:195px;height:35px;margin:5px\"><span class=\"label label-info\" style=\"float:right\">20</span><img src=\"/gebo/img/gCons/first-aid.png\" alt=\"\" style=\"float:left\" />Doctor List</a></li>\r\n<li class=\"ui-menu\"><a href=\"#\" class=\"btn\" style=\"width:195px;height:35px;margin:5px\"><span class=\"label label-success\" style=\"float:right\">10</span><img src=\"/gebo/img/gCons/phone.png\" alt=\"\" style=\"float:left\" />Labs</a></li>\r\n</ul>\r\n</p>\r\n\r\n<div id=\"context-menu\" class=\"accordion\">\r\n             \r\n\r\n<div class=\"k-widget k-treeview\" tabindex=\"0\" role=\"tree\" aria-activedescendant=\"treeview_tv_active\"><ul id=\"treeview\" class=\"menu k-group k-treeview-lines\" style=\"background:#fff;outline:none\" data-role=\"treeview\">\r\n                    <li data-expanded=\"true\" class=\"k-item k-first k-last\" data-uid=\"1405e3fa-5195-4b0a-a94c-71fdeb4fd3ae\" role=\"treeitem\" id=\"treeview_tv_active\"><div class=\"k-top k-bot\"><span class=\"k-icon k-minus\"></span><span class=\"k-in\"><span class=\"k-sprite folder\"></span><a data-disable-with=\"loading..\" data-remote=\"true\" href=\"/esm_projects/189/edit\">Med Endoscopy (cusys.med)</a></span></div><ul class=\"k-group\">\r\n                            <li class=\"k-item\" data-uid=\"674a30fc-2059-40db-b7cc-1f6d833125f5\" role=\"treeitem\" aria-expanded=\"false\" aria-selected=\"false\"><div class=\"k-top\"><span class=\"k-icon k-plus\"></span><span class=\"k-in\"><span class=\"k-sprite folder\"></span><a data-disable-with=\"loading..\" data-remote=\"true\" href=\"/esm_services?id=18