\n							<div class=\"accordion-group\">\r\n								<div class=\"accordion-heading\">\r\n									<a href=\"#collapseFour\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n										<i class=\"icon-th\"></i> Menu\r\n									</a>\r\n								</div>\r\n								<div class=\"accordion-body collapse\" id=\"collapseFour\">\r\n									<div class=\"accordion-inner\">\r\n										<ul class=\"nav nav-list\">\r\n												<li class=\"divider\"></li>\r\n												<li><a class=\"k-button\" data-disable-with=\"loading..\" data-remote=\"true\" href=\"/esm_menus?id=189\">Manage ..</a></li>\r\n										\r\n										</ul>\r\n									</div>\r\n								</div>\r\n							</div>\r\n							\r\n									<div class=\"accordion-group\">\r\n										<div class=\"accordion-heading\">\r\n											<a href=\"#collapseFive\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											<i class=\"icon-th\"></i>	Users &amp; Roles\r\n											</a>\r\n										</div>\r\n										<div class=\"accordion-body collapse\" id=\"collapseFive\">\r\n											<div class=\"accordion-inner\">\r\n												<ul class=\"nav nav-list\">\r\n												<li class=\"divider\"></li>\r\n												<li><a class=\"k-button\" data-disable-with=\"loading..\" data-remote=\"true\" href=\"/esm_roles?id=189\">Manage ..</a></li>\r\n										\r\n												</ul>\r\n											</div>\r\n										</div>\r\n									</div>\r\n									\r\n	-->								\r\n									\r\n								\r\n						\r\n		\r\n			</div>',NULL,NULL,NULL,'2013-10-15 13:02:08','2013-10-15 13:02:08','context_menu',''),(828,'analysis',235,2,'<%\r\n ncharts= 30\r\n%>\r\n<%\r\n #\r\n  @from_date = Time.now.beginning_of_year\r\n  @to_date = Time.now\r\n  \r\n  if params[:analysis] \r\n  a =   (%w(1 2 3).collect { |e| params[:analysis][\"from_date(\\\\#{e}i)\"].to_i }) \r\n  @from_date = Date.to_mongo(a.join(\"-\")) \r\n  a =   (%w(1 2 3).collect { |e| params[:analysis][\"to_date(\\\\#{e}i)\"].to_i }) \r\n  @to_date = Date.to_mongo(a.join(\"-\")) \r\n  end\r\n  \r\n\r\n  table_name = this.table_name\r\n  @module_name = @current_project.name+\'#\'+ table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  \r\n  @m_patient_model = @ehr_model[:patient]\r\n  @m_patient_module = @ehr_model[:patient_module]\r\n  \r\n  pname = \"\\\\#{@current_project.name}\\#\"\r\n  \r\n  models = get_model\r\n  \r\n  doc = get_document table_name\r\n  fields = doc.list_fields\r\n  fields_name = doc.list_fields_column_name\r\n  \r\n  model = models[table_name.to_sym]\r\n  \r\n      \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n  \r\n    all_app =  models[:appointment].collection.find({:date=>{\'$gte\'=>@from_date,\'$lt\'=>@to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n\r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n     # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}\\\\#{table_name}\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n    cs = {\'_id\'=>1 }\r\n    \r\n    for i in fields \r\n        \r\n        cs[i.column_name] = 1\r\n    \r\n    end\r\n    \r\n\r\n    colo = model.collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>cs}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    \r\n    visits = models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n     # all pm colono of those appointments\r\n    all_patient = @m_patient_model.collection.find(:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\']}}).to_a\r\n    m_all_patient = bmap all_patient, \'_id\'\r\n    \r\n    \r\n    months = {}\r\n    \r\n    for i in all_app\r\n    \r\n        month = i[\'date\'].strftime(\"%Y-%m\")\r\n\r\n         m_app = m_all_pm_app[i[\'_id\']][0]\r\n        \r\n        m_icolo = m_all_pm_colo[m_app[\'_id\']]\r\n        \r\n        \r\n        \r\n        if m_icolo and m_icolo = m_icolo[0]\r\n        \r\n        \r\n        months[month] = [] unless months[month]\r\n        months[month] << i\r\n        \r\n        end\r\n        \r\n    end\r\n    \r\n    imonths = {}\r\n    \r\n    ifields = {}\r\n   \r\n    labels = {}\r\n    \r\n    \r\n    for i in all_app\r\n    \r\n    \r\n        month = i[\'date\'].strftime(\"%Y-%m\")\r\n        m_app = m_all_pm_app[i[\'_id\']][0]\r\n        \r\n        m_icolo = m_all_pm_colo[m_app[\'_id\']]\r\n        \r\n        \r\n        \r\n        if m_icolo and m_icolo = m_icolo[0]\r\n        \r\n        \r\n        record = m_colo[m_icolo[\'module_id\']]\r\n        \r\n        if record and record = record[0]\r\n        for f in fields\r\n        \r\n        \r\n        vs = record[f.column_name].to_s.split(\'|\').uniq\r\n        @record = record\r\n        @document = doc\r\n        \r\n        labels[f.column_name] = {} unless labels[f.column_name]\r\n        labels[f.column_name][record[f.column_name].to_s] = render_value f.column_name unless labels[f.column_name][record[f.column_name].to_s]\r\n        \r\n        \r\n        \r\n        for v in vs\r\n        \r\n        ifields[f.column_name] = {} unless ifields[f.column_name]\r\n        ifields[f.column_name][v] = 1     \r\n        \r\n        imonths[f.column_name] = {} unless imonths[f.column_name]\r\n        imonths[f.column_name][month] = {} unless  imonths[f.column_name][month]\r\n        imonths[f.column_name][month][v] = 0 unless  imonths[f.column_name][month][v] \r\n        imonths[f.column_name][month][v] += 1\r\n        \r\n        end\r\n        \r\n        end\r\n        \r\n        end\r\n        end\r\n    end\r\n    \r\n    \r\n    \r\n\r\n\r\n%>\r\n<style>\r\n    select {\r\n        width:100px;\r\n    }\r\n</style>\r\n<h1><%=table_name.humanize%> Summary</h1>\r\n\r\n\r\n<%=form_for :analysis, :url=>\"analysis\" do |f|  %>\r\nFrom <%= f.date_select \'from_date\' ,:default=>@from_date , :order=>[:day, :month,:year] %> to <%= f.date_select \'to_date\', :default=>@to_date, :order=>[:day,:month,:year] %> \r\n<%= f.submit \'Submit\' %>\r\n<% end %>\r\n\r\n<% if request.post? %>\r\nPeriod : <%= @from_date.strftime(\"%d/%m/%Y\")%> - <%= @to_date.strftime(\"%d/%m/%Y\")%>\r\n<%# m_all_pm_colo.inspect %><br/>\r\n<%#labels.inspect   %> \r\n\r\n\r\n<h2>Monthly</h2>\r\n<table class=\"table\">\r\n    <thead></thead>\r\n    <tbody>\r\n        <% for i in months.keys.sort %>\r\n        <tr>\r\n            <th>\r\n                <%=i%>\r\n            </th>\r\n            <td>\r\n                <%= months[i].size %>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n    </tbody>\r\n</table>\r\n<%\r\nif true \r\nfor f in fields \r\nif ifields[f.column_name]\r\n%>\r\n<h3><%= f.column_name.humanize %></h3>\r\n<table class=\"table\">\r\n    \r\n    <thead>\r\n        <tr>\r\n            <th style=\"width:150px\">\r\n                Month\r\n            </th>\r\n            \r\n            \r\n            \r\n            <% for i in ifields[f.column_name].keys  %>\r\n            <th>\r\n                <%= labels[f.column_name][i] %>\r\n            </th>\r\n            \r\n            <% end %>\r\n            \r\n        </tr>\r\n        \r\n        \r\n    </thead>\r\n    <tbody>\r\n        \r\n        \r\n        \r\n        \r\n        <% for i in imonths[f.column_name].keys.sort\r\n        \r\n            values = imonths[f.column_name][i]\r\n            \r\n        %>\r\n        <tr>\r\n            <th style=\"width:150px\"> \r\n            <%=  i %>\r\n            </th>\r\n        \r\n        \r\n        \r\n        \r\n            <% ifields[f.column_name].keys.each do |k|\r\n                \r\n                v = values[k]\r\n                \r\n            %>\r\n                <td>\r\n                    <%= v %>\r\n                </td>\r\n            <% end %>\r\n            \r\n        </tr>\r\n        <% end %>\r\n    </tbody>\r\n    \r\n    \r\n</table>\r\n\r\n<% end %>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n<hr/>\r\n<%# fields.collect{|i| i.get_lov_options }  %>\r\n    \r\n    \r\n    \r\n    ',NULL,NULL,NULL,'2013-10-22 02:24:33','2013-10-22 02:31:10','analysis',''),(829,'analysis_data',235,3,'[]',NULL,NULL,NULL,'2013-10-22 03:19:58','2013-10-22 03:19:58','analysis_data',''),(830,'print_image',189,3,'\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div style=\"page-break-after: always\">\r\n<%= render :inline=>this.print_partial, :locals=>{:this=>this} %>\r\n</div>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:colonoscopy].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colonoscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n	<p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=record.date_note%></v>&nbsp;&nbsp; Colonoscope :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n\r\n\r\n\r\n<table width=\"100%\" >\r\n<tr>\r\n  <td valign=\"top\" border=\"1\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<p><label>Note : </label><v><% if a= record[\'scope_note\'] and a !=\"\" %><%=render_value \'scope_note\'%> </v><% end%></p></td>\r\n  <td valign=\"top\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \') if record[\'diagnosis_group\']%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p></td>\r\n</tr>\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endoscopist : <v><%=endoscopist_1%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endoscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<b>Picture :</b><br/>\r\n    <%\r\n        list = record.image\r\n        atts = []\r\n        if list[8...36]\r\n        atts = list[8...36].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        end\r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>?thumb=2\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:40px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n<script>\r\nwindow.print()\r\n</script>\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2013-10-22 04:41:36','2013-12-20 04:47:43','print_image',''),(831,'show',189,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<