\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Gastroscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=record.date_note%></v>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n<hr />\r\n\r\n<table width=\"100%\" border=\"0\">\r\n  <tr>\r\n    <td valign=\"top\" width=\"50%\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p></td>\r\n    <td width=\"50%\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \')%></v></p>\r\n</td>\r\n  </tr>\r\n</table>\r\n\r\n\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endoscopist : <v><%=endoscopist_1%></v></p>\r\n    <p>Note: <v><%=record[\'scope_note\']%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endoscopist : <v><%=endoscopist_2%></v></p>\r\n    <p>Remark : <v><%=record[\'remark\']%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n\r\n    <%\r\n        list = record.image\r\n        atts = []\r\n        if list[8...36]\r\n            atts = list[8...36].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        end\r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n    <div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\" style=\"height:40px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2013-10-23 03:24:05','2013-12-20 04:46:05','print_image',''),(834,'show',251,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print image\'.html_safe, \"print_image?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n<%= this.display.html_safe %>\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    sedative = [\'dormicum\',\'pethidine\',\'diprivan\',\'valium\',\'buscopan\',\'plasil\',\'fentanyl\',\'other\']\r\nfunction check_sedative(ele){\r\n   check = ele.prop(\"checked\");\r\n   id = ele.prop(\"id\");\r\n   t = id.split(\'-\')[1];\r\n   if(check)\r\n   $(\".\"+t+\'\').css(\"display\",\"block\");\r\n   else\r\n   $(\".\"+t+\'\').css(\"display\",\"none\");\r\n}\r\n\r\nfor(i=0;i<sedative.length;i++){\r\n t = sedative[i];  \r\n ele = $(\'#data-\'+t);\r\nele.change(function(){\r\n    check_sedative($(this));\r\n});\r\n check_sedative(ele);\r\n}\r\n</script>',NULL,NULL,NULL,'2013-10-23 03:26:03','2013-10-23 03:26:03','show',''),(835,'form',379,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n\r\nfunction refresh_form(){\r\n\r\n intake = parseInt($(\"#data-intake\").val());\r\n output = parseInt($(\"#data-output\").val());\r\n \r\n $(\"#data-net_fluid_balance\").val(intake-output);\r\n //alert(intake+output)\r\n}\r\n\r\n$(\"#data-intake\").change(function(){\r\nrefresh_form();\r\n});\r\n$(\"#data-output\").change(function(){\r\nrefresh_form();\r\n});\r\n\r\n$(\"#data-sled_date\").change(function(){\r\n    $(\"#record-date\").datepicker().val($(this).val());\r\n});\r\n</script>',NULL,NULL,NULL,'2013-10-24 02:55:32','2013-10-24 02:55:32','form',''),(836,'form',377,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n\r\nfunction refresh_form(){\r\n\r\n bw = parseInt($(\"#data-bw\").val());\r\n ht = parseInt($(\"#data-ht\").val());\r\n \r\n\r\n $(\"#data-bmi\").val((bw/(ht*ht)*10000).toFixed(2));\r\n \r\n //alert(intake+output)\r\n}\r\n\r\n$(\"#data-bw\").change(function(){\r\nrefresh_form();\r\n});\r\n$(\"#data-ht\").change(function(){\r\nrefresh_form();\r\n});\r\n\r\n/////\r\n\r\nfunction updateRecordDate(){\r\n    \r\n    l =  $(\'#data-rrt_start_date\').val().split(\"/\");\r\n    year = parseInt(l[2])\r\n    month = parseInt(l[1])\r\n    day = parseInt(l[0])\r\n    \r\n    if(year>2400)year-=543\r\n    \r\n    \r\n    text = \"\"+year+\"-\"+leftPad(month, 2)+\"-\"+leftPad(day, 2);\r\n    date = new Date(Date.parse(text));\r\n    date28 = new Date(date.getTime()+3600*1000*24*28);\r\n    \r\n    var d = date28.getDate();\r\n    var m = date28.getMonth() + 1;\r\n    var y = date28.getFullYear();\r\n    \r\n    $(\'#data-survival_28_days\').val(\"\"+d+\"/\"+m+\"/\"+y);\r\n    \r\n    \r\n}\r\n\r\n\r\nvar list = [\'chronic_health_points\',\'temperature\',\'mean_arterial\',\'heart_rate\',\'respiratory_rate\',\'oxygenation\',\'oxy_b\',\'arterial_ph\',\'serum_sodium\',\'serum_potassium\',\'serum_creatinine\',\'hematocrit\',\'white_blood_count\']\r\nfunction leftPad(number, targetLength) {\r\n    var output = number + \'\';\r\n    while (output.length < targetLength) {\r\n        output = \'0\' + output;\r\n    }\r\n    return output;\r\n}\r\nfunction updateApache(){\r\n    a = 0 \r\n    \r\n    \r\n    for(var i in list){\r\n        value = $(\'#data-\'+list[i]).val();\r\n        a+= Math.abs(parseInt(value));\r\n    }\r\n    \r\n    age = parseInt($(\'#data-age\').val());\r\n    b = 0\r\n    if(age>=75)b=6;\r\n    else\r\n    if(age>=65)b=5;\r\n    else\r\n    if(age>=55)b=3;\r\n    else\r\n    if(age>=45)b=2;\r\n    else\r\n        b=0;\r\n\r\n    \r\n\r\n    \r\n glas = 0\r\n glas =  15 - parseInt($(\'#data-glasgow_coma_score\').val());\r\n   \r\n    $(\'#data-apache_ii\').val(a+b+glas)\r\n      \r\n   updateMDRD()\r\n}\r\n\r\n$(\"#glasgow_coma_score\").change(function(){\r\nupdateApache();\r\n});\r\n\r\n\r\nempty_cr = true\r\n\r\nfunction updateMDRD(){\r\n    \r\n    age = parseInt($(\'#data-age\').val())\r\n    gender = $(\'#data-gender\').val();\r\n     //alert(gender);\r\n    v = 0\r\n    if(gender==\'1\'){\r\n        v = Math.pow(375.5/(75*Math.pow(age,0.364)),0.848)\r\n    }else{\r\n        v = Math.pow(375.5*0.712/(75*Math.pow(age,0.364)),0.848)\r\n\r\n    }\r\n\r\n    v=v.toFixed(2)\r\n    \r\n    $(\'#data-baseline_serum_creainine_by_mdrd\').val(v)\r\n    if(empty_cr){\r\n        $(\'#data-baseline_serum_cr\').val(v)\r\n    }\r\n}\r\n\r\n\r\nif($(\'#data-baseline_serum_cr\').val()!=\'\'){\r\n    empty_cr = false;\r\n}\r\n\r\n$(\'#data-gender\').change(updateMDRD);\r\nupdateMDRD()\r\n\r\n\r\n$(\'#data-age\').change(updateApache);\r\nfor(var i in list){\r\n    $(\'#data-\'+list[i]).change(updateApache);\r\n    \r\n}\r\n\r\n$(\'#data-rrt_start_date\').change(updateRecordDate);\r\n\r\nupdateRecordDate()\r\n\r\n\r\n</script>',NULL,NULL,NULL,'2013-10-24 02:58:08','2013-10-24 02:58:08','form',''),(837,'document_name',398,1,'\'endo\'',NULL,NULL,NULL,'2013-10-24 05:27:37','2013-10-24 05:27:37',NULL,NULL),(841,'index',402,2,'\r\n<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Record</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"search\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-zoom\"></i><br />Search Patient</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n    });\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n   # aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n     aps = ap_model.all(:limit=>10,:order=>\'created_at desc\') \r\n\r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n         #public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date.strftime(\"%d-%m-%Y\"),:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Waiting\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if true}.compact\r\n    \r\n    \r\n    table_model = %w{date hn patient }.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n    \r\n    \r\n%>\r\n\r\n\r\n<%\r\n\r\n     tmp = waiting\r\n\r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Recently Patients \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n       <%= tabular :model=>table_model+[:processing_ctrl],:data=>tmp,:labels=>labels %>\r\n\r\n        \r\n        </div>\r\n    </div>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<br/>\r\n<%  t = Time.new date.year, date.month,date.day\r\n%>\r\n\r\n<%\r\n   start = t.beginning_of_day\r\n   stop = t.end_of_day\r\n\r\n   modules = module_model.where(:module_name=>/\\\\#{@current_project.name}/i,:date=>{\"$gte\"=> start, \"$lt\"=> stop}).all\r\n   \r\n   modules.collect! do |i|\r\n   %>\r\n\r\n   <%\r\n   if i.module_name!=\"\\\\#{@current_project.name}#appointment\"\r\n         patient = patient_model.find(i.patient_id)\r\n        \r\n         hn = \'-\'\r\n         hn = patient.hn #link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         \r\n        ap =  module_model.find(i.parent_id)\r\n      if ap \r\n      ap = ap.module_id \r\n     {:public_id=>public_id, :hn=>hn, :patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\"),\r\n        :show=>link_to(\'Show\',\"../\\\\#{i.module_name.split(\'#\')[-1].camelize}/show?id=\\\\#{i.id}&record_name=\\\\#{hn}&return=../Home/patient_record?id=\\\\#{ap}\",:class=>\'btn btn-small\'), \r\n      :module_name=>i.module_name.split(\"#\")[-1].humanize,\r\n      :updated_at=>i.updated_at.strftime(\"%d-%m-%y\"),\r\n      :date=>i.date.strftime(\"%d-%m-%y\"),\r\n      \r\n     }\r\n     end\r\n     end\r\n   end\r\n   modules.compact!\r\n%>\r\n<%#\"\\\\#{@current_project.name}#appointment\"%>\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Recently Chart Reports \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n	     <%= tabular :model=>[:date, :updated_at,:hn, :patient, :module_name,:show],:data=>modules do |row,out|\r\n             \r\n            out\r\n         end\r\n         %>\r\n    \r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n\r\n </div><br/>\r\n \r\n <script>\r\n $(\"#query\").focus();\r\n </script>',NULL,NULL,NULL,'2013-10-31 04:02:51','2013-10-31 04:02:51','',''),(842,'patient_record',402,2,'    \r\n    <% Time.zone =  get_setting \'time_zone\' %>\r\n    <style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    </style>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n    <div class=\"w-box\">\r\n        <div class=\"w-box-header\">\r\n            Patient Medical Records\r\n            <div class=\"pull-right\">\r\n            <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n            </div> \r\n        </div>  \r\n        <div class=\"w-box-content cnt_a\">\r\n        \r\n    <%\r\n    \r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        ehr_models = ehr.get_model\r\n        patient_model = ehr_models[:patient]\r\n        patient_module_model = ehr_models[:patient_module]\r\n        groups = this.config\r\n        emr_models = get_model\r\n        ap = emr_models[:appointment].find(params[:id])\r\n        pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n        \r\n        locker_model = emr_models[:locker]\r\n        if params[:reset_lock]\r\n            l = locker_model.find(params[:reset_lock])\r\n            l.destroy if l\r\n        end\r\n        #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n        #i.destroy if i\r\n        #end\r\n         \r\n        \r\n        \r\n        if pm\r\n        \r\n        if  params[:schema_patient_module]\r\n           pm.update_attributes params[:schema_patient_module]\r\n        end\r\n        \r\n        if params[:provider_id]\r\n          ap.update_attributes :provider=>params[:provider_id]\r\n           ap = emr_models[:appointment].find(params[:id])\r\n         end\r\n        \r\n        # find provider\r\n        provider = emr_models[:provider].find(ap.provider.to_s)\r\n        \r\n        # find patient\r\n        patient = patient_model.find(pm.patient_id)\r\n        \r\n        params[:patient]=patient\r\n        params[:patient_module]=pm\r\n        \r\n       # s = Service.get(\'ehr.emr.EmrHelper\')\r\n    #    obj = s.load context\r\n        \r\n        providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n        \r\n    %>\r\n    \r\n    <% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\'}.compact %>\r\n    <div style=\"border:0px solid\">\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:688px\">\r\n    <%# render :inline=>obj.show_patient %>\r\n    <div id=\"patient\">\r\n    ...\r\n    </div>\r\n    <script>\r\n    <%\r\n            url = \'../../www/Patient/search_result?\'\r\n            url += \'&id=\'+patient.id.to_s\r\n      %>      \r\n            $.ajax({\r\n              url: \'<%=url.html_safe%>\',\r\n             success: function(data){\r\n              $(\'#patient\').html(data);  \r\n              }\r\n            });\r\n    </script>\r\n    \r\n    <%\r\n    \r\n    \r\n    previous = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\n    history = []\r\n    x = previous[0..7]\r\n    last = []\r\n    last = x.compact if x\r\n    history = []\r\n    y = previous[8..-1]\r\n    history = y.compact if y and  previous.size>5\r\n                                         \r\n    current = time_ago_in_words(ap.date)\r\n    current_date = ap.date.strftime(\"%d-%m-%y\")\r\n    current = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n    \r\n    %>\r\n    \r\n    \r\n    \r\n    <div class=\"clear\"></div>\r\n    \r\n    <h4><%= @current_project.title %> Recrods</h4>\r\n    \r\n    \r\n    \r\n    <% else %>\r\n    Data missing\r\n    <% end %>\r\n    <br/><br/>\r\n    <div class=\"clear\"></div>\r\n    <%\r\n        pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n        modules = patient_module_model.all(:parent_id=>pm.id,:patient_id=>pm.patient_id).collect do |i|\r\n            name = i.module_name.split(\"#\")[-1]\r\n            hn = patient.hn\r\n            \r\n            rr = link_to(\"\\\\#{i.date.strftime(\"%d-%m-%Y\")} \\\\#{i.time.strftime(\"%H:%M\") if i.time } \", \"../\\\\#{name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\")\r\n            rr += \' \'\r\n            #rr += link_to(\"[ Edit ]\", \"../\\\\#{name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\")\r\n            date = i.date.strftime(\"%d-%m-%y\")\r\n            \r\n            #show = link_to(\'Show\',\"../\\\\#{name.camelize}/show?id=\\\\#{i.id}&record_name=\\\\#{hn}&return=../Home/patient_record?id=\\\\#{ap}\",:class=>\'btn btn-small\')\r\n            show = link_to(\"Edit \", \"../\\\\#{name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-small\')\r\n            show += \' \'\r\n            show += link_to(\'Print\',\"../\\\\#{name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'btn btn-small\')\r\n    \r\n            {:name=>name,:records=>rr.html_safe,:date=>date,:show=>show,:module_name=>name}\r\n        end\r\n    \r\n    %>\r\n    <div class=\"tabbable tabs-left\" style=\"border:1px solid #ccc; -moz-border-radius: 5px;\r\n    border-radius: 5px;\">\r\n    <ul class=\"nav nav-tabs\" style=\"background:#F4F4F4; -moz-border-radius: 5px;border-radius: 5px;\">\r\n    <li class=\"active\" ><a href=\"#tab_dashboard\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >Dashboard</a></li>\r\n    <%\r\n    for g in groups \r\n       services = g[:actions].collect{|i| [@current_project.get_service(i[:service]), i[:name]]}.compact\r\n       %> \r\n    <li class=\"\" ><span style=\"font-size:14px;padding:10px\"><%=g[:name]%></span></li>\r\n       <%\r\n       for st in services\r\n       s = st[0]\r\n       name = st[1]\r\n       n = modules.collect{|i| i if i[:module_name]==s.name }.compact.size\r\n    %>\r\n    <li class=\"<%#\'active\' if s == services[0]%>\" style=\"border:0px solid;width:150px;overflow:hidden\"><a href=\"#tab_<%=s.id%>\" data-toggle=\"tab\" style=\"font-size:12px; padding:10px\">- <%=name%>\r\n    <%= \"(\\\\#{n})\" if n>0 %>\r\n    </a></li>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    </ul>\r\n    \r\n    \r\n    <div class=\"tab-content\" style=\"width:520px;border:0px solid;float:left; clear:none;margin-left:-20px;\">\r\n    <div class=\"tab-pane  <%= \'active\' if true %>\" style=\"border:0px solid;\" id=\"tab_dashboard\">\r\n    <br/><h3>Dashboard</h3>\r\n    \r\n    <div style=\'float:right;margin-top:-30px\'>\r\n    <%\r\n      title_map = {}\r\n      services.each {|i| \r\n      \r\n      title_map[i[0].name] = i[1]\r\n      \r\n      }  \r\n      \r\n      \r\n    %>\r\n    <%# link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class %>\r\n    </div>\r\n    \r\n    <%= tabular :data=> modules,:model=>[:name,:records,:show] do |row,out|\r\n    out[0] = title_map[row[:name]]\r\n    out\r\n    end%>\r\n    \r\n    </div>\r\n    <%# title_map%>\r\n    \r\n    <%\r\n    for g in groups \r\n       services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n       for s in services\r\n    %>\r\n    <div class=\"tab-pane  <%# \'active\' if s==services[0] %>\" id=\"tab_<%=s.id%>\"  style=\"border:0px solid;\">\r\n    <br/><h3><%=s.title%></h3>\r\n    \r\n    <%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class ,:style=>\'float:right;margin-top:-30px\'%>\r\n    \r\n    <%= tabular :data=> modules.collect{|i| i if i[:module_name]==s.name }.compact ,:model=>[:title,:records,:show] do |row,out|\r\n    out[0] = s.title\r\n    out\r\n    end%>\r\n    \r\n    </div>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n   </div>\r\n   </div>\r\n    \r\n    \r\n    \r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    <br/><br/>\r\n    \r\n    \r\n    <script>\r\n    $(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n    </script>\r\n    \r\n     \r\n',NULL,NULL,NULL,'2013-10-31 16:09:32','2013-10-31 16:09:32','patient_record',''),(843,'search',402,2,'\r\n<h1> Search Result </h1>\r\n<hr/>\r\n<% \r\n    models = get_model\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    fields = %w{hn public_id first_name last_name}\r\n    %>\r\n    <%= form_for :search,:url=>\'\' do |f| %>\r\n\r\n<div style=\"padding:10px;background:#ededff\">\r\n<center>Search : <%= text_field_tag \'query\', params[:query] , :id=>\'search\' %>  <%=f.submit \'Search\', :class=>\'\' %><br/>\r\n<i>*Search by HN, ID, or Name</i></center>\r\n</div>\r\n\r\n<% end %>\r\n<%\r\n    if request.post?\r\n    \r\n    query = params[:query]\r\n    keys = []\r\n    fields.each do |f| \r\n        keys <<{f.to_sym=>Regexp.new(query)}\r\n    end\r\n    criteria = {\'$or\'=>keys}\r\n    \r\n    patients = patient_model.where(criteria).limit(20).all  \r\n    \r\n    app_name = \"\\\\#{@current_project.name}#appointment\"\r\n    app_model = models[:appointment]\r\n    \r\n    \r\n%>\r\n<%= tabular :model=>fields,:data=>patients,:n=>10 do |row,out|\r\n\r\n  am = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).order(\'date\').last\r\nif am\r\n  app = app_model.where(:id=>am.module_id).first\r\n  url = \"../Home/patient_record?id=\\\\#{am.module_id}\"\r\n  out[0] = link_to(row.hn,url)\r\n  out[1] = link_to(row.public_id,url)\r\n  out[2] = link_to(row.first_name,url)\r\n  out[3] = link_to(row.last_name,url)\r\n  n = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).count\r\nout<<link_to(\"Detail\", url,:class=>\"btn\")\r\nelse\r\nout<<\'-\'\r\nend\r\n\r\nout\r\nend\r\n%>\r\n<hr/>\r\n<%# params.inspect %>\r\n<% end %>\r\n<script>\r\n$(\"#search\").focus();\r\n</script>',NULL,NULL,NULL,'2013-10-31 16:09:44','2013-10-31 16:09:44','search',''),(844,'report',401,2,'<%= form_for :query,:url=>\'report\' do |f| %>\r\n<%= f.date_select :year, :discard_day=>true,:discard_month=>true %>\r\n<%= f.submit \'Search\' %>\r\n<% end %>\r\n<% if request.post? and params[:query]\r\n   year = params[:query][\'year(1i)\']\r\n   date = Time.new  year.to_i\r\n   #DateTime.parse(\"2010-10-30\")\r\n%>\r\n<%= date.inspect %>\r\n<% end %>\r\n<%\r\n    \r\n    \r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    patients =  module_model.all(:module_name=>mname)\r\n    \r\n    \r\n    list = []\r\n    \r\n    date = Time.now unless date\r\n    \r\n    list = module_model.collection.group({:keyf=>\'function(doc){return {month:doc.date.getMonth(),name:doc.module_name};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:date=>{\'$gte\'=>date.at_beginning_of_year(),\'$lte\'=>date.end_of_year}}})\r\n          \r\n          \r\n        columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n   \r\n    map = {}\r\n    data = []\r\n    \r\n    %>\r\n    <%# list.inspect %>\r\n    <%\r\n         \r\n    if list.size>0    \r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    name = i[\'name\'].split(\'#\')[1]\r\n    map[name] = {\'name\'=>name.humanize, \'data\'=>[]} unless map[name] \r\n    map[name][\'data\'][i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\n    end\r\n    map.each_pair do |k,v|\r\n    if k!=\'appointment\'\r\n        data << v    \r\n    end\r\n    \r\n    end\r\n    \r\n    models = get_model\r\n    \r\n    outcome = []\r\n    \r\n\r\n          \r\n \r\n    list = module_model.collection.find({ :module_name=>/.*outcome.*/i,:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}).to_a\r\n   \r\n        \r\n    # list = models[:outcome].collection.group({:keyf=>\'function(doc){ a = doc.day_outcome_date ; if(typeof a==\"undefined\") a = doc.updated_at ;return {month:a.getMonth(),name:doc.outcome_day_28};}\',\r\n    #       :reduce=>\'function(curr,result){result.count++;}\',\r\n    #       :initial=>{:count=>0},\r\n    #       :finalize=>\'function(result){result.month=result.month}\',\r\n    #       :cond=>{:created_at=>{\'$gte\'=>date.at_beginning_of_year(),\'$lte\'=>date.end_of_year}}})\r\n    list = models[:outcome].collection.group({:keyf=>\'function(doc){ a = doc.day_outcome_date ; if(typeof a==\"undefined\") a = doc.updated_at ;return {month:a.getMonth(),name:doc.outcome_day_28};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:day_outcome_date=>{\'$gte\'=>date.at_beginning_of_year(),\'$lte\'=>date.end_of_year}}})\r\n\r\n    map = {}\r\n    if list.size>0    \r\n        for i in list\r\n            columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n            name = i[\'name\']\r\n            map[name] = {\'name\'=>name.humanize, \'data\'=>[]} unless map[name] \r\n            map[name][\'data\'][i[\'month\'].to_i] = i[\'count\'].to_i\r\n        end\r\n    end\r\n    map.each_pair do |k,v|\r\n        if k!=\'\'\r\n            outcome << v    \r\n        end\r\n    end\r\n    columns = mlabels\r\n    # fs = {:fields=>{\'day_outcome_date\'=>1, \'outcome_day_28\'=>1}}\r\n    fs = {}\r\n    tmp = models[:outcome].collection.find({:day_outcome_date=>{\'$gte\'=>date.at_beginning_of_year(),\'$lte\'=>date.end_of_year}}, fs).to_a\r\n    \r\n%>\r\n<%#tmp.to_json.html_safe %>\r\n<h3>Report Summaries</h3>\r\n\r\n\r\n\r\n<div id=\"chart\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n\r\n\r\n</div>\r\n\r\n<br/>\r\n<h3>RRT Report</h3>\r\n<div id=\"chart3-rrt\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n\r\n\r\n</div>\r\n\r\n\r\n<br/>\r\n<h3>Crrt Day Report</h3>\r\n<div id=\"chart1\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n\r\n\r\n</div>\r\n\r\n\r\n<br/>\r\n<h3>SLED Day Report</h3>\r\n<div id=\"chart2\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n\r\n\r\n</div>\r\n\r\n\r\n<br/>\r\n<h3>Outcome Reports</h3>\r\n\r\n<div id=\"chart-outcome\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n\r\n\r\n</div>\r\n\r\n\r\n <%\r\n \r\n\r\n    rrt_list = [] \r\n    \r\n     \r\n \r\n    rrt =  models[:rrt_report].collection.group({:keyf=>\'function(doc){return {month:doc.rrt_start_date.getMonth()};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:rrt_start_date=>{\'$gte\'=>date.at_beginning_of_year(),\'$lte\'=>date.end_of_year}}})\r\n          \r\n    for i in rrt\r\n        rrt_list[i[\'month\'].to_i] = i[\'count\'].to_i \r\n    end\r\n    \r\n    rrt_list = [{\"name\"=>\"Rrt report\",\"data\"=>rrt_list}]   \r\n    # rrt = models[:rrt_report].collection{\r\n %>\r\n\r\n<hr/>\r\n\r\n\r\n            <script>\r\n                function createChart() {\r\n                    $(\"#chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n        			\r\n					\r\n					\r\n					\r\n					 $(\"#chart1\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.collect{|i| i if i[\'name\']==\'Crrt day\'}.compact.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        },\r\n                         seriesClick: function(e){\r\n                             lookup(e.series.name+\"-\"+e.category)\r\n                         }\r\n                    });\r\n					\r\n					\r\n\r\n					 $(\"#chart2\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.collect{|i| i if i[\'name\']==\'Sled day\'}.compact.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n					\r\n					\r\n					\r\n					\r\n\r\n\r\n					 $(\"#chart3-rrt\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=rrt_list.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n					\r\n					\r\n					\r\n					\r\n                    $(\"#chart-outcome\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=outcome.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    }); \r\n                    \r\n                }\r\n\r\n                $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n                });\r\n                \r\n                function lookup(key){\r\n                    $.ajax({url:\"report_partial?q=\"+key,success:function(result){\r\n                    alert(result);\r\n                    }});\r\n                }\r\n                \r\n                \r\n            </script>\r\n\r\n<%#columns.inspect %>\r\n<%#data.inspect %>',NULL,NULL,NULL,'2013-11-03 08:26:06','2013-11-03 08:26:06','report',''),(845,'document_name',403,1,'\'fungal_rhinosinusitis\'',NULL,NULL,NULL,'2013-11-04 02:48:04','2013-11-04 02:48:04',NULL,NULL),(846,'document_name',404,1,'\'immunotherapy\'',NULL,NULL,NULL,'2013-11-04 02:59:03','2013-11-04 02:59:03',NULL,NULL),(847,'document_name',405,1,'\'invasive_fungal_rhinosinusitis\'',NULL,NULL,NULL,'2013-11-06 03:41:04','2013-11-06 03:41:04',NULL,NULL),(848,'document_name',406,1,'\'invasive_fungal_rhinosinusitis\'',NULL,NULL,NULL,'2013-11-06 03:48:09','2013-11-06 03:48:09',NULL,NULL),(850,'document_name',408,1,'\'attachment\'',NULL,NULL,NULL,'2013-11-10 16:17:30','2013-11-10 16:17:30',NULL,NULL),(851,'form',385,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n\r\nfunction refresh_form(){\r\n\r\n intake = parseInt($(\"#data-intake\").val());\r\n output = parseInt($(\"#data-output\").val());\r\n \r\n $(\"#data-net_balance\").val(intake-output);\r\n //alert(intake+output)\r\n}\r\n\r\n$(\"#data-intake\").change(function(){\r\nrefresh_form();\r\n});\r\n$(\"#data-output\").change(function(){\r\nrefresh_form();\r\n});\r\n\r\n\r\nfunction cal2(){\r\n    \r\n     cr = parseFloat($(\"#data-pre_tb\").val());\r\n     inr = parseFloat($(\"#data-pre_cr\").val());\r\n     tb = parseFloat($(\"#data-pre_inr\").val());\r\n     if(!isNaN(cr)&&!isNaN(tb)&&!isNaN(inr)){\r\n     $(\"#data-meld_score\").val(0.957*Math.log(cr)+0.378*Math.log(tb)+1.120*Math.log(inr)+0.643);\r\n     }else{\r\n          $(\"#data-meld_score\").val(\"Please fill CR,Inr and TB\");\r\n     }\r\n     \r\n    \r\n}\r\n$(\"#data-pre_tb\").change(cal2);\r\n$(\"#data-pre_cr\").change(cal2);\r\n$(\"#data-pre_inr\").change(cal2);\r\n\r\n\r\n</script>',NULL,NULL,NULL,'2013-11-12 03:56:39','2013-11-12 03:56:39','form',''),(852,'document_name',409,1,'\'hbtype\'',NULL,NULL,NULL,'2013-11-12 18:05:48','2013-11-12 18:05:48',NULL,NULL),(853,'document_name',410,1,'\'hospital\'',NULL,NULL,NULL,'2013-11-12 18:09:06','2013-11-12 18:09:06',NULL,NULL),(854,'document_name',411,1,'\'diagnosis\'',NULL,NULL,NULL,'2013-11-12 18:15:21','2013-11-12 18:15:21',NULL,NULL),(855,'document_name',412,1,'\'d10_evaluation\'',NULL,NULL,NULL,'2013-11-12 18:52:01','2013-11-12 18:52:01',NULL,NULL),(856,'document_name',413,1,'\'reported_by\'',NULL,NULL,NULL,'2013-11-12 19:08:05','2013-11-12 19:08:05',NULL,NULL),(859,'print',411,3,'    <%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n    <%\r\n        # id of operative note\r\n        \r\n        models  = @models\r\n        pm = @module_model.find(params[:id])\r\n        hbtype_id = pm.module_id\r\n        record = models[:diagnosis].find(hbtype_id)\r\n        @record = record\r\n        @document = get_document this.document_name\r\n        \r\n        reported_by = render_value(\'reported_by\')\r\n        approved_by = render_value(\'approved_by2\')\r\n      \r\n        if @patient \r\n        patient = @patient\r\n        date = Time.now.to_datetime\r\n        birth_date = patient.birth_date \r\n        year = month = day = \'0\'\r\n        if date and birth_date\r\n        t = date-birth_date    \r\n        year = (t/365).to_i\r\n        t%=365\r\n        month = (t/30).to_i\r\n        t%=30\r\n        day = t.to_i\r\n        end\r\n    end %>\r\n    \r\n    <!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n    <html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n    <head>\r\n    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n    <title>PRINT</title>\r\n    </head>\r\n    <style type=\"text/css\" media=\"all\">\r\n    html { }\r\n    #page {border:solid 1px; width:910px; border-color:#666;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */\r\n    margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n    #head { width:100%; height:120px;}\r\n    #logoleft { margin-left:0px; float:left;}\r\n    #logoright{ margin-right:20px; float:right;}\r\n    th              { font-weight: bolder; text-align: center }\r\n    caption         { text-align: center }\r\n    body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n    .wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\n    hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\n    h1              { font-size: 2em; margin: .67em 0 }\r\n    h2              { font-size: 1.5em; margin: .83em 0 }\r\n    h3              { font-size: 1.17em; margin: 1em 0 }\r\n    p {color:#666;}\r\n    h4, p,\r\n    blockquote, ul,\r\n    form,\r\n    ol, dl          { margin: 0.5em; }\r\n    h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n    h6              { font-size: .67em; margin: 2.33em 0 }\r\n    \r\n    h4 { font-size:14pt; color:#333; height:16px;}\r\n    blockquote      { margin-left: 40px; margin-right: 40px }\r\n    i, cite, em,\r\n    var, address    { font-style: italic }\r\n    pre, tt, code,\r\n    kbd, samp       {  font-size:14px; }\r\n    pre             {margin:0;margin-left:1em; color:#666}\r\n    big             { font-size: 1.17em }\r\n    v {color:#2561cD;}\r\n    small, sub, sup { font-size: .83em }\r\n    ol, ul, dd      { margin-left: 40px }\r\n    ol              { list-style-type: decimal }\r\n    ol ul, ul ol,\r\n    ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n    .clear{clear:both;}\r\n    @media print {\r\n      @page         { width:960px; margin-top:0; }\r\n      blockquote, \r\n     .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n    }\r\n    \r\n    #box{\r\n        width:215px;\r\n        float:left;\r\n        padding:0px;\r\n        text-align:center;\r\n        border:1px solid #ccc;\r\n        -webkit-border-radius: 5px; /* Safari prototype */\r\n        -moz-border-radius: 5px; /* Gecko browsers */\r\n        border-radius: 5px; /* Everything else - limited support at the moment */    \r\n        margin:5px;\r\n        font-size:0.8em;\r\n        height:135px;\r\n        overflow:hidden;\r\n    }\r\n    .smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n    #box img{\r\n        \r\n        \r\n        height:120px;\r\n    }\r\n    label{\r\n        color:#666;\r\n    }\r\n    </style>\r\n    <body>\r\n    <div class=\"wrapper\">\r\n    \r\n    <div id=\"head\">\r\n    <div id=\"logoleft\" style=\" width:300px\"><img src=\'/esm/hbt/hbtyping/logohb.jpg\' width=\"300\" /></div>\r\n    <div  style=\"width:650px; float:left\">\r\n    <p style=\"font-size:12px\">ศูนย์วิจัยธาลัสซีเมีย\r\nสถาบันวิจัยและพัฒนาวิทยาศาสตร์และเทคโนโลยี\r\nมหาวิทยาลัยมหิดล วิทยาเขตศาลายา\r\n999 ถ. พุทธมณฑลสาย 4 ต. ศาลายา อ. พุทธมณฑล จ. นครปฐม 73170 <br />โทรสาร (02) 8892559, โทรขอคำแนะนำ (02) 8892557-8 โทรสอบถามผลตรวจ (02) 4419003-7 ต่อ 1357<hr /><p style=\"font-size:12px\">\r\nInstitute of Molecular Bisciences, Mahidol University, Salaya camp Phutthamonthon 4 Rd., Salaya, Phutthamon