9 13:15:15',NULL,NULL),(868,'document_name',422,1,'\'order_item\'',NULL,NULL,NULL,'2013-11-19 13:17:14','2013-11-19 13:17:14',NULL,NULL),(869,'document_name',423,1,'\'stock_card\'',NULL,NULL,NULL,'2013-11-19 13:22:36','2013-11-19 13:22:36',NULL,NULL),(870,'document_name',424,1,'\'site\'',NULL,NULL,NULL,'2013-11-19 13:22:48','2013-11-19 13:22:48',NULL,NULL),(871,'index',425,2,'<h1>Sale System</h1>\r\n\r\n<%= link_to \'Orders\', \'../Order/index\'%>',NULL,NULL,NULL,'2013-11-19 13:35:44','2013-11-19 13:35:44','index',''),(872,'layout',425,4,'<%=default_layout%>',NULL,NULL,NULL,'2013-11-19 13:36:04','2013-11-19 13:36:04','layout',''),(873,'form',420,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n\r\n<script>\r\n\r\n\r\n\r\nfunction doSearch(){\r\n$(\"#myModal1\").modal()   \r\nq = $(\"#product_search_q\").val();\r\n\r\n$.ajax({\r\n  url: \"product_search\",\r\n  data: \'q=\'+q,\r\n  context: document.body\r\n}).done(function(data) {\r\n    $(\'#modal-body\').html(data);\r\n});\r\n\r\n}\r\n\r\nfunction doSelect(id){\r\npid = id\r\n$.ajax({\r\n  url: \"product_select\",\r\n  data: \'pid=\'+pid,\r\n  context: document.body\r\n}).done(function(data) {\r\n    $(\'#items-list\').append(data);\r\n});\r\n    \r\n}\r\n\r\nfunction recalculate(){\r\n    //alert(\"reclculate()\");\r\n    total_amount = 0.0;\r\n    $(\".order-row\").each(function( index ) {\r\n       price = $(this).find(\".price\").val();\r\n       quantity = $(this).find(\".quantity\").val();\r\n       discount = $(this).find(\".discount\").val();\r\n       amount = price*quantity-discount;\r\n       $(this).find(\".amount\").val(amount);\r\n        total_amount += amount;\r\n    });\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    $(\"#total_amount\").val(total_amount);\r\n}\r\n\r\nfunction insertRow(){\r\n    recalculate();\r\n}\r\n\r\nfunction removeRow(){\r\n    recalculate();\r\n}\r\n\r\n\r\n</script>\r\n\r\n\r\n\r\n<%# render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<div id=\"code\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Code : </label></span>    \r\n\r\n<input class=\"k-textbox k-textbox-txt\" id=\"data-code\" name=\"record[code]\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" type=\"text\" validationMessage=\"Cannot be empty\" />\r\n\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n<div id=\"customer_id\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Customer ID : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle\">\r\n\r\n<select class=\"\" id=\"data-customer_id\" name=\"record[customer_id]\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" validationMessage=\"Please select one\">\r\n<option value=\"\"></option>\r\n<option value=\"528b69b2790f9b659d000003\">Anonymous </option></select>\r\n\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n<div id=\"date\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Date : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle\">\r\n\r\n<input id=\"data-date\" name=\"record[date]\" style=\"width:150px\" type=\"text\" value=\"2013-11-19 20:41:34 +0700\" />\r\n<script>\r\n	$(\"#data-date\").kendoDatePicker({\r\n		value: \'<%=Time.now.strftime(\"%d/%m/%Y\")%>\',\r\n	});\r\n</script>\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n<div id=\"time\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Time : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle\">\r\n\r\n<input id=\"data-time\" name=\"record[time]\" onkeypress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" style=\"width:80%\" type=\"text\" validationMessage=\"Cannot be empty\" value=\"2013-11-19 20:41:34 +0700\" />\r\n<script>\r\n\r\n$(\"#data-time\").kendoTimePicker({\r\n	value: \'<%=Time.now.strftime(\"%H:%M\")%>\',\r\n	interval: 10,\r\n	parseFormats: [\"HH.mm\",\"HHmm\"],\r\n	change: function(event){\r\n		\r\n	}\r\n});\r\n</script>\r\n	\r\n\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<div style=\"padding:20px;background:#eef\">\r\nProduct Search : <%= text_field_tag :q,\'\',:id=>\'product_search_q\' %>\r\n<%= button_tag \'Search\',:onclick=>\'doSearch();return false;\' %>\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"items\" class=\"  portlet \" style=\"width:705px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Items : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle\">\r\n\r\n<div id=\"items-list\">\r\n	\r\n</div>\r\n<%=  @record.items.inspect %>\r\n<input id=\"record_items\" name=\"record[items]\" type=\"hidden\" value=\"[]\" />\r\n\r\n</div>\r\n</div>\r\n\r\nTotal Amount : \r\n<%= text_field_tag \'record[total_amount]\', @record.total_amount,:id=>\'total_amount\' %>\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n<div class=\"modal hide\" id=\"myModal1\">\r\n<div class=\"modal-header\">\r\n<h3>Select Products\r\n<a href=\"#\"  style=\"float:right\" data-dismiss=\"modal\">X </a>  \r\n</h3>\r\n</div>\r\n\r\n<div class=\"modal-body\" id=\"modal-body\" >\r\n\r\n</div>\r\n<div class=\"modal-footer\">\r\n</div>\r\n\r\n</div>\r\n\r\n',NULL,NULL,NULL,'2013-11-19 13:41:13','2013-11-19 13:41:13','',''),(874,'product_search',420,3,'<%\r\n    models = get_model\r\n    pm = models[:product]\r\n    x = /\\\\#{params[:q]}/\r\n    products = pm.where(\'$or\'=>[{\"name\"=>x},{\"code\"=>x}]).all\r\n  \r\n  \r\n\r\n%>\r\n\r\n<%= tabular :model=>%w{name code},:data=>products do |row,out| \r\ndolist = \"doSelect(\'\\\\#{row.id}\')\"\r\nout<<\"