unt]\" pattern=\"[-+]?[0-9]*\\.?[0-9]*.\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:80px\" type=\"number\" validationmessage=\"Cannot be empty\" value=\"<%=discount%>\" onchange=\"recalculate()\">\r\n</div>\r\n<div class=\"order-row-td\">\r\n<input class=\"k-textbox k-textbox-txt amount\"  id=\"data-order-items-<%=id%>-amount\" name=\"order[items][<%=id%>][amount]\" pattern=\"[-+]?[0-9]*\\.?[0-9]*.\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:80px\" type=\"number\" validationmessage=\"Cannot be empty\" value=\"<%=amount%>\" onchange=\"recalculate()\">\r\n</div>\r\n<div class=\"order-row-td\" style=\"width:100px\">\r\n<input class=\"k-textbox k-textbox-txt\" id=\"data-order-items-<%=id%>-note\" name=\"order[items][<%=id%>][note]\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" type=\"text\" validationmessage=\"Cannot be empty\" value=\"<%=note%>\">\r\n</div>    \r\n<div class=\"clear\"></div>\r\n</div>\r\n<script>\r\nrecalculate();\r\n</script>\r\n',NULL,NULL,NULL,'2013-11-19 15:04:44','2013-11-19 15:04:44','product_select',''),(876,'document_name',426,1,'\'dental_chart_\'',NULL,NULL,NULL,'2013-11-20 04:55:01','2013-11-20 04:55:01',NULL,NULL),(877,'document_name',427,1,'\'dental_medical_chart\'',NULL,NULL,NULL,'2013-11-20 04:58:52','2013-11-20 04:58:52',NULL,NULL),(878,'document_name',428,1,'\'dental_items\'',NULL,NULL,NULL,'2013-11-20 05:06:42','2013-11-20 05:06:42',NULL,NULL),(879,'patient_record',358,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\")%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\")%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\")} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n    text += \" by \" +User.find(locker.session.to_i).login.split(\"@\")[0]\r\n%>\r\n\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\")} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2013-11-20 05:21:31','2013-11-20 05:21:31','patient_record',''),(880,'index',429,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2013-11-26 06:08:03','2013-11-26 06:08:03',NULL,NULL),(881,'layout',429,4,'<%=default_layout%>',NULL,NULL,NULL,'2013-11-26 06:08:03','2013-11-26 06:08:03',NULL,NULL),(882,'test',356,2,'Test page\r\n\r\n<%= link_to \'Back to Home\', \'index\' %>',NULL,NULL,NULL,'2013-11-26 14:07:39','2013-11-26 14:07:39','test',''),(883,'display',364,3,'\r\n<h1><%=Time.now %></h1>\r\n<%\r\n   model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>',NULL,NULL,NULL,'2013-11-26 14:18:49','2013-11-26 14:18:49','display',''),(886,'index',431,2,'Hello',NULL,NULL,NULL,'2013-11-27 18:04:11','2013-11-27 18:04:11','index',''),(887,'layout',431,4,'<%=default_layout%>',NULL,NULL,NULL,'2013-11-27 18:04:31','2013-11-27 18:04:31','layout',''),(888,'index',432,2,'Store',NULL,NULL,NULL,'2013-11-27 18:06:40','2013-11-27 18:06:40','index',''),(889,'layout',432,4,'<%=default_layout%>',NULL,NULL,NULL,'2013-11-27 18:07:03','2013-11-27 18:07:03','layout',''),(890,'index',433,2,'Dev',NULL,NULL,NULL,'2013-11-27 18:18:18','2013-11-27 18:18:18','index',''),(891,'layout',433,4,'<%=default_layout%>',NULL,NULL,NULL,'2013-11-27 18:18:36','2013-11-27 18:18:36','layout',''),(892,'status_feed_partial',146,3,'<b>ประจำวันท่ี <%= Time.now.strftime(\"%d %B %Y\") %> <%=Time.now.strftime(\"%H:%M:%S\")%></b>\r\n<div class=\"clear\"></div>\r\n<%\r\n  npage = 9\r\n  page = 0 \r\n  page = params[:page].to_i if params[:page]\r\n  \r\n  \r\n  \r\n\r\n  @module_name = @cu