  \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Batch \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\">Batch</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <%= link_to \'Start Wizard\', \'../Wizard/index\'%>\r\n    </div>\r\n</div>\r\n</div>\r\n    \r\n    ',NULL,NULL,NULL,'2013-12-04 14:55:42','2013-12-04 14:55:42','',''),(898,'document_name',439,1,'\'batch\'',NULL,NULL,NULL,'2013-12-06 07:25:00','2013-12-06 07:25:00',NULL,NULL),(899,'document_name',440,1,'\'customer\'',NULL,NULL,NULL,'2013-12-06 07:26:24','2013-12-06 07:26:24',NULL,NULL),(900,'index',441,2,'<h1>Start Wizard</h1>\r\n\r\n<%= form_for \'input\',:url=>\'create_batch\',:html=>{:multipart=>true} do |f|%>\r\n<div class=\"input\">\r\n<label>Number of cases : </label>\r\n<%= f.text_field :number_of_cases %>\r\n</div>\r\nor by upload .csv \r\n<div class=\"input\">\r\n<label>Upload : </label>\r\n<%= f.file_field :upload %>\r\n</div>\r\n\r\n\r\n<%= f.submit \'Submit\' %>\r\n<% end %>\r\n<%= link_to \'Cancel\', \'../Home/index\' %>',NULL,NULL,NULL,'2013-12-06 07:33:55','2013-12-06 07:33:55','index',''),(901,'print_partial',189,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:colonoscopy].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = pm.created_at.to_datetime\r\n    date = record.date_note.to_datetime if record.date_note\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize if @current_user %></p>\r\n<p>Printed :&nbsp;<%=thdate Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colonoscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v><%=thdate record.date_note%></v>&nbsp;&nbsp; Colonoscope :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n  \r\n   \r\n	  <table width=\"100%\">\r\n	    <tr>\r\n	      <td > <h4 style=\"padding:0px; margin:0px; margin-left:10px\">Status : <%=record[\'status\']%> </h4></td>\r\n	      <td><h4 style=\"padding:0px; margin:0px;margin-left:10px\">Sedation</h4></td>\r\n        </tr>\r\n	    <tr>\r\n      <td width=\"60%\"><p><span style=\"float:left; \"> </span>\r\n        <span style=\"float:left;display:block-inline;\">\r\n				<table width=\"100%\" style=\"margin-left:10px\" >\r\n				<tr>\r\n				  \r\n					<td width=\"300\"><label>Previous Operation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n				 \r\n					<td><label>Bowel Preparation :</label> <v><%=render_value \'bowel_preparation\' %> <%=record[\'bowel_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'bowel_other\'%></v></td>\r\n				</tr>\r\n				<tr>\r\n				\r\n					<td><label>Quality of Preparation :</label> <v><%=record[\'quality_of_preparate\']%></v></td>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \') if record[\'record\']%></v></td>\r\n				\r\n				<tr>\r\n					\r\n					<td width=\"220\"><label>Additional Bowel Preparation :</label> <v><%=render_value \'additional_bowel_preparation\' %> <%=record[\'add_bowel_prep_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'add_bowel_prep_other\'%></v></td>\r\n				</tr>		\r\n				\r\n			</table>	\r\n		</span>\r\n		\r\n \r\n		</p></td>\r\n\r\n<td width=\"40%\"  valign=\"top\">\r\n\r\n<p>\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% any_sedation = false %>\r\n\r\n<tr><td >\r\n<% if record[\'dormicum\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Dormicum :</label> <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Pethidine :</label> <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'drithpivan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Drithpivan :</label> <v><%=record[\'drithpivan_mg\']%> mg <%=record[\'drithpivan_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Diprivan :</label> <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v>  </div>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Valium :</label> <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Buscopan :</label> <v><%=record[\'buscopan_mg\']%> mg <%=record[\'buscopan_route\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'plasil\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Plasil :</label> <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Fentanyl :</label> <v><%=record[\'fentanyl_mg\']%> mcg <%=record[\'fentanyl_routh\']%> </v>   </div>\r\n<% end%>\r\n\r\n<% if record[\'general_anesthesia\'] and record[\'general_anesthesia\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><v>General anesthesia</v>   </div>\r\n<% end%>\r\n\r\n<% if record[\'other\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Other Note :</label> <v><%=record[\'other_note\']%> </v>   </div>\r\n\r\n<% end%>\r\n</td>\r\n  </tr>\r\n\r\n\r\n<tr>\r\n<td><% unless  any_sedation %>\r\n<v>No sedation</v>\r\n<% end %>\r\n</td>\r\n</tr>\r\n</table>\r\n</p></td>\r\n </tr></table>\r\n		\r\n<hr />\r\n\r\n<h4>Scope finding</h4>\r\n<table style=\"padding-left:15px\">\r\n<tr>\r\n    <td width=\"300\">\r\n    <label>Scope pass through : </label><v><%=render_value \'scope\'%></v>\r\n    </td>\r\n    <td width=\"240\">\r\n    <label>Procedure : </label><v><%=render_value \'procedure\'%></v>\r\n    </td>\r\n    <td><label>Diverticulum : </label><v><%=render_value \'diverticulum\'%></v></td>\r\n</tr>\r\n\r\n</table>\r\n\r\n\r\n\r\n<% if  a = record[\'procedure_other\']  and a !=\"\" %><label>Note : </label><v><%=render_value \'procedure_other\'%> </v><% end%>\r\n<p style=\"padding-left:10px\">Start : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<p >\r\n<%\r\n    scopes = %w{rectum_scope sigmoid_scope descending_colon_scope transvers_colon_scope ascending_colon_scope cecum_scope terminal_ileum_scope}.reverse\r\n    \r\n    scopes.each_with_index do |j,index|\r\n    if scopes.size-index-1<record.scope.to_i \r\n    tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    text = \"Normal\"\r\n    tag_cls = \'\'\r\n    if record[tag]\r\n    t =  record[tag].strip\r\n    if  t== \'1\' or t==\'Abnormal\'\r\n    	text =  \"Abnormal\"\r\n    	 tag_cls = \'color:red\'\r\n    end\r\n    end\r\n    label = tag\r\n    label = \'transverse_colon\' if tag == \'transvers_colon\'\r\n    \r\n%>\r\n<p><%= label.humanize %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Type:</td><td>Dx:</td><td>Morphology:</td><td>Size:</td><td>Treatment:</td><td>By:</td><td>Clip:</td><td>Patho No:</td>\r\n<td>Chromo By:</td><td>Kudo:</td><td>Sano:</td><td>NICE:</td><td>JNET:</td><td>Note:</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n      \r\n     \r\n     note =  []  \r\n     note << i[\'abnormal_note\'] if i[\'abnormal_note\'] and i[\'abnormal_note\']!=\'\'\r\n     note << \"Tattoo was done\" if i[\'tattoo\'] and i[\'tattoo\']==\'Done\'\r\n     note << i[\'complication\'] if i[\'complication\'] and i[\'complication\']!=\'none\'\r\n     \r\n      note = note.join \", \" \r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'endoscopy_dx\']%></v></td><td><v><%=i[\'morphology_type\']%></v></td><td>\r\n<% if i[\'size\']==0%>\r\n<v> -</v>\r\n<% else%>\r\n<v><%=i[\'size\']%> cm.</v>\r\n<% end%>\r\n</td>\r\n<td><v><%=i[\'treatment\']%></v></td>  <td><v><%=i[\'treatment_by\']%></v> </td> <td><v><%=i[\'clip\']%></v></td>               <td><v><%=i[\'patho_number\']%></v></td>\r\n<td><v><%=i[\'chromo\']%></v></td>     <td><v><%=i[\'kudo_type\']%></v></td>     <td><v><%=i[\'sano_type\']%></v></td>          <td><v><%=i[\'nice_classification\']%></v></td>\r\n<td><v><%=i[\'jnet_class\']%></v></td><td><v><%=note%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n<hr />\r\n\r\n\r\n<h4>Note</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<% if a= record[\'scope_note\'] and a !=\"\" %><label>Note : </label><v><%=render_value \'scope_note\'%> </v><% end%>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \') if record[\'diagnosis_group\']%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endoscopist : <v><%=endoscopist_1%></v></p>\r\n	\r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endoscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\">\r\n    <p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n\r\n    <%\r\n        list = record.image\r\n   \r\n        \r\n        atts = models[:attachment].find(list[0...8].compact).compact\r\n        map = {}\r\n        for i in atts\r\n            map[i.id] = i\r\n            map[i.id.to_s] = i\r\n        end\r\n        atts = []\r\n        for i in list[0...8].compact\r\n            atts << map[i]\r\n        end\r\n\r\n\r\n        \r\n        # atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.compact.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>?thumb=2\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2013-12-08 17:07:13','2013-12-08 17:07:13','print_partial','*'),(902,'print_partial',251,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    gas_id = pm.module_id\r\n    record = models[:gastroscopy].find(gas_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = pm.created_at.to_datetime\r\n    date = record.date_note if record.date_note\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px;padding-left:20px;padding-right:20px }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo2.png\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize if @current_user %></p>\r\n<p>Printed :&nbsp;<%=thdate Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Gastroscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=thdate record.date_note%></v>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n<hr />\r\n    \r\n		<table width=\"100%\"><tr><td width=\"60%\" valign=\"top\">\r\n		\r\n		\r\n     <h4 style=\"padding:0px; margin:0px; margin-left:10px;margin-bottom:5px \">Status : <%=record[\'status\']%> </h4>\r\n						<table width=\"100%\">\r\n				<tr>\r\n					<td><label>Previous Operation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n					<td><label>NPO time (Hours) :</label> <v><%=render_value \'npotime\' %></v></td>\r\n					<td></td>\r\n				</tr>\r\n				<tr>\r\n					<td><label>Quality of Preparation :</label><v> <%=record[\'quality_of_preparate\']%></v></td>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \')%></v></td>\r\n				\r\n				</tr>		\r\n				\r\n			</table>	\r\n		\r\n		<div class=\"clear\"></div>\r\n		\r\n		\r\n</td>\r\n		    <td valign=\"top\" width=\"40%\"><h4 style=\"padding:0px; margin:0px; margin-left:10px; margin-bottom:5px\">Sedation</h4>\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% if record[\'dormicum\']==\'true\'%>\r\n<tr><td>Dormicum : <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'%>\r\n<tr><td>Pethidine : <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'%>\r\n<tr><td>Buscopan : <v><%=record[\'buscopan_mg\']%> mg <%=record[\'route_buscopan\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'%>\r\n<tr><td>Fentanyl : <v><%=record[\'mg_fentanyl\']%> mcg <%=record[\'fentanyl_route\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'%>\r\n<tr><td>Diprivan : <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'%>\r\n<tr><td>Valium : <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v> </td></tr>\r\n<% end%>\r\n\r\n<% if record[\'plasil\']==\'true\'%>\r\n<tr><td>Plasil : <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v> </td></tr>\r\n<% end%>\r\n\r\n<% if record[\'general_anesthesia\'] and record[\'general_anesthesia\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<tr><td><v>General anesthesia</v>  </td></tr>\r\n\r\n<% end%>\r\n<% if record[\'other\']==\'true\'%>\r\n<tr><td>Other Note : <v><%=record[\'other_note\']%> </v> </td></tr>\r\n<% end%>\r\n</table></td>\r\n		</tr>\r\n\r\n</table>\r\n\r\n<hr />\r\n<h4>Scope finding</h4>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<table width=\"850\">\r\n\r\n<tr>\r\n    <td><label>Scope pass through : </label><v><%=render_value \'scope\'%> </td>\r\n    <td colspan=\"3\"><label>Pocedure : </label><v><%=render_value \'procedure\'%> </td>\r\n</tr>\r\n<tr>\r\n<td>Start : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v>  To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></td>\r\n\r\n    <td colspan=\"1\"><label>Esophagitis LA Class : </label><v><%=render_value \'esophagitis_la_class\'%></td>\r\n    <td><label>H.Pylori test : </label><v><%=render_value \'hpylori_test\'%></td>\r\n\r\n    \r\n</tr>\r\n\r\n<tr>\r\n<td><span class=\"\"><label>Z line at (cm.) : </label></span>	\r\n<v><%=render_value \'z_line\'%></v>\r\n    <span class=\"\"><label>EGJ at (cm.) : </label></span>	\r\n<v><%=render_value \'egj_at\'%></v>\r\n    \r\n</td>\r\n<td><span class=\"\"><label>Sliding Hernia : </label></span>	\r\n<v><%=render_value \'sliding_hernia\'%></v></td>\r\n<td><span class=\"\"><label>Ampulla of Vater : </label></span>	\r\n<v><%=render_value \'ampulla_of_vater\'%></v></td>\r\n</tr>\r\n\r\n</table>\r\n\r\n<%\r\n    scopes_labels = {\'egj_scope\'=>\'EGJ\'}\r\n\r\n    scopes = %w{pharynx_scope esophagus_scope egj_scope fundus_scope cardia_scope body_scope antrum_scope first_duodenum_scope sphincter_of_oddi_scope second_duodenum_scope third_duodenum_scope forth_duodenum_scope proximal_jejunum_scope distal_jejunum_scope}\r\n\r\n    scopes.each_with_index do |j,index|\r\n    if index<record.scope.to_i \r\n    tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    \r\n    \r\n    \r\n    text = \"Normal\"\r\n    tag_cls = \'\'\r\n    if record[tag] == \'1\'\r\n    	text =  \"Abnormal\"\r\n    	 tag_cls = \'color:red\'\r\n    end\r\n    label = tag.humanize\r\n    label = scopes_labels[j] if scopes_labels[j]\r\n    \r\n%>\r\n<p><%= label %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Abnormal Type :</td><td>Endoscopy Dx :</td><td>Morphology Type :</td><td>Size (cm.) :</td><td>Treatment :</td><td>By :</td><td>Clip :</td><td>Patho No. :</td><td>Abnormal Note :</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n      size= \'-\'\r\n      size = i[\'size\'] if i[\'size\']!=0\r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'endoscopy_dx\']%></v></td><td><v><%=i[\'morphology_type\']%></v></td><td><v><%=size%></v></td><td><v><%=i[\'treatment\']%></v></td><td> <v><%=i[\'treatment_by\']%></v> </td><td><v><%=i[\'clip\']%></v></td><td><v><%=i[\'patho_number\']%></v></td><td><v><%=i[\'abnormal_note\']%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<hr />\r\n\r\n<h4>Note :</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \')%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endoscopist : <v><%=endoscopist_1%></v></p>\r\n    <p>Note: <v><%=record[\'scope_note\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endoscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n<tr>\r\n<td  colspan=\"2\">\r\n    	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n\r\n</tr>\r\n    \r\n</table>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n        \r\n              \r\n        map = {}\r\n        for i in atts\r\n            map[i.id.to_s] = i\r\n            map[i.id] = i \r\n        end\r\n        atts = []\r\n        for i in list[0...8].compact\r\n            atts << map[i]\r\n        end\r\n        \r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n    <div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>?thumb=2\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2013-12-08 17:12:02','2013-12-08 17:12:02','print_partial',''),(903,'document_name',442,1,'\'lab_info\'',NULL,NULL,NULL,'2013-12-13 04:21:36','2013-12-13 04:21:36',NULL,NULL),(904,'document_name',443,1,'\'user\'',NULL,NULL,NULL,'2013-12-14 04:34:38','2013-12-14 04:34:38',NULL,NULL),(905,'index',444,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2013-12-14 04:42:37','2013-12-14 04:42:37',NULL,NULL),(906,'layout',444,4,'<%=default_layout%>',NULL,NULL,NULL,'2013-12-14 04:42:37','2013-12-14 04:42:37',NULL,NULL),(907,'document_name',445,1,'\'role\'',NULL,NULL,NULL,'2013-12-14 04:44:21','2013-12-14 04:44:21',NULL,NULL),(908,'list',443,3,'<%\r\n   model = get_model(this.table_name)\r\n   records = []\r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   \r\n    if params[:search]\r\n        records = model.all(params[:search][:criteria])\r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n       records = model.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n    end\r\n   \r\n%>\r\n\r\n<%= tabular :model=>labels, :data=>records do |i,out|\r\n\r\nfields.each_with_index do |f,index|\r\n\r\nout[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n\r\nend\r\nout<<link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nout<<link_to(\'<i class=\"splashy-pencil_small\"></i>Password\'.html_safe, url(\"change_password\",:id=>i.id),:class=>\'btn btn-warning btn-mini\' )\r\nout<<link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\')\r\nout<<link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:confirm=>\'Are you sure?\')\r\nout\r\nend\r\n%>\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2013-12-15 04:17:56','2013-12-15 04:19:30','list',''),(909,'change_password',443,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    password = params[:password]\r\n    if password == params[:password_confirmation]\r\n    salt = User.random_string(10) \r\n    hashed_password = User.encrypt(password, salt)\r\n    params[\'record\'] = {\'salt\'=>salt,\'hashed_password\'=>hashed_password}\r\n    end\r\n    \r\n    \r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"index\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'change_password\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<label>Password</label><%= password_field_tag \'password\' %>\r\n<label>Password Confirmation</label><%= password_field_tag \'password_confirmation\' %>\r\n\r\n<%# this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2013-12-15 04:18:16','2013-12-15 08:16:25','change_password',''),(911,'show',443,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to(\'Cnage Password\'.html_safe, url(\"change_password\",:id=>params[:id]),:class=>\'btn btn-warning btn-mini\' )%>\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2013-12-15 04:20:18','2013-12-15 04:21:15','show',''),(912,'create_batch',441,2,'<h1>Batch Creation</h1>\r\n\r\n<%\r\n    \r\n    count = 0 \r\n    \r\n    if request.post?\r\n    \r\n    \r\n    count = params[:input][:number_of_cases]\r\n    \r\n    if params[:input][:upload]\r\n\r\n    file = params[:input][:upload]\r\n    \r\n    list = file.open.readlines(\"\\r\").collect{|i| i.strip.split(\",\") }\r\n    list = list[1..-1]\r\n    count = list.size\r\n    end\r\n%>\r\n\r\n<%# list.inspect %>\r\n<%= form_for :input, :url=>\"confirm_batch\" do |f| %>\r\n<div class=\"input\">\r\n<label>Batch Number : </label>\r\n<%=f.text_field :batch_number %>\r\n</div>\r\n\r\n<div class=\"input\">\r\n<label>Customer : </label>\r\n<%=f.select :customer_id, get_model[:customer].all.collect{|i| [i.name,i.id] } %>\r\n</div>\r\n\r\n<%= f.hidden_field \"number_of_cases\", :value=>count %>\r\n\r\n\r\n<table>\r\n<tr>\r\n<td>HN</td>\r\n<td>Name</td>\r\n<td>Surname</td>\r\n<td>Age</td>\r\n<td>Gender</td>\r\n</tr>\r\n\r\n<% for i in 0...count \r\n    obj = list[i]\r\n%>\r\n<tr>\r\n<td><%=i+1%>.</td>\r\n<td><%=text_field_tag \"hn[\\\\#{i}]\", obj[0] %></td>\r\n<td><%=text_field_tag \"name[\\\\#{i}]\", obj[1] %></td>\r\n<td><%=text_field_tag \"surname[\\\\#{i}]\", obj[2] %></td>\r\n<td><%=text_field_tag \"age[\\\\#{i}]\", obj[3] %></td>\r\n<td><%=text_field_tag \"gender[\\\\#{i}]\", obj[2] %></td>\r\n\r\n</tr>\r\n\r\n<% end %>\r\n</table>\r\n\r\n<%= f.submit \'Submit\' %>\r\n\r\n<% end %>\r\n<%  \r\n    end\r\n\r\n\r\n%>\r\n',NULL,NULL,NULL,'2013-12-19 11:50:28','2013-12-19 11:50:28','create_batch',''),(915,'config',446,1,'services =  %w{presentation pre_operative operative post_operative pathology chemo_rx follow_up surviellence recurrence quality_of_life caf hemorrhoid ostomy}\r\n\r\nservices.collect!{|s| @current_project.get_service(s) }.compact!\r\n\r\n\r\n[{:name=>\'Form\',:open=>true,:actions=>services.collect{|i| {:name=>i.title,:service=>i.name,:link=>\"..\\\\\\#{i.name.camelize}/index\"}} }]\r\n\r\n',NULL,NULL,NULL,'2013-12-24 16:35:19','2013-12-24 16:35:19','config',''),(916,'document_name',447,1,'\'pathology\'',NULL,NULL,NULL,'2013-12-24 16:40:50','2013-12-24 16:40:50',NULL,NULL),(917,'index',449,2,'<style>\r\n    .navbar-inner {\r\n        background: #37b0c9;\r\n    	background: -moz-linear-gradient(top, #37b0c9 0%, #1294af 100%);\r\n		background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#37b0c9), color-stop(100%,#1294af));\r\n		background: -webkit-linear-gradient(top, #37b0c9 0%,#1294af 100%);\r\n		background: -o-linear-gradient(top, #37b0c9 0%,#1294af 100%);\r\n		background: -ms-linear-gradient(top, #37b0c9 0%,#1294af 100%);\r\n		background: linear-gradient(top, #37b0c9 0%,#1294af 100%);\r\n		filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#37b0c9\', endColorstr=\'#1294af\',GradientType=0 );\r\n    }\r\n    .navbar .nav > li > a {\r\n        color: #c7f0f9;\r\n    }\r\n    .navbar .nav > li:hover > a {\r\n        color:#fff;\r\n    }\r\n    .navbar .nav .active > a, .navbar .nav .active > a:hover {\r\n        background: #0f7a90;\r\n    }\r\n    .navbar .divider-vertical {\r\n        background-color:#0f7a90;\r\n        border-color:#15aece;\r\n    }\r\n    .dropdown-menu li > a:hover, .dropdown-menu .active > a,\r\n	.dropdown-menu .active > a:hover,\r\n    .nav-list > .active > a, .nav-list > .act