tion\'%></v>\r\n	\r\n\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'spillage_of_bowel_content\']!=\"\" %>\r\n<div id=\"spillage_of_bowel_content\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;\">\r\n<span class=\"\"><label>Spillage of bowel content : </label></span>	\r\n\r\n<v><%=render_value \'spillage_of_bowel_content\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'intraoperative_complication\']!=\"\" %>\r\n<div id=\"intraoperative_complication\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:430px;\">\r\n<span class=\"\"><label>Intraoperative complication : </label></span>	\r\n\r\n<v><%=render_value \'intraoperative_complication\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'intraoperative_complication_detail\']!=\"\" %>\r\n<div id=\"intraoperative_complication_detail\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:800px;\">\r\n<span class=\"\"><label>Intraoperative detail : </label></span>	\r\n<v><%=render_value \'intraoperative_complication_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n\r\n<% if record[\'other_operative_detail\']!=\"\" %>\r\n<div id=\"other_operative_detail\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:800px;\">\r\n<span class=\"\"><label>Other operative detail : </label></span>	\r\n<v><%=render_value \'other_operative_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	<div class=\"clear\"></div>\r\n\r\n<% if models[:attachment]!=nil %>\r\n    <%\r\n        list = record.images\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\"><br/>\r\n		<img alt=\"1\" src=\"<%=i.path%>\" />\r\n        <v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    \r\n<div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n<% end %>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n<style>\r\n.navitem\r\n{\r\n         \r\n    width: 150px;\r\n    /* padding: 5px; */\r\n}\r\n\r\n.selected\r\n{\r\n    border: 2px solid red;\r\n    width: 146px;\r\n    /* padding: 4px */\r\n}\r\n</style>\r\n\r\n<script type=\"text/javascript\" charset=\"utf-8\">\r\n \r\nfield_idx =\"\"; \r\n\r\nfunction pressKey(){\r\nalert(\"press\")\r\n }\r\nfunction doSelect(){\r\n\r\n   list = []\r\n   \r\n   body = $(\"#piczone-\"+field_idx);\r\n   body.empty();\r\n   $(\'.selected-img\').each(function(i,obj){\r\n     id = obj.id.substring(7);\r\n     list.push(id);\r\n     $(\'#\'+id).removeClass(\'eachpicimg\');\r\n     \r\n      body.append(\'<div style=\"width:150px;float:left;margin:5px\"><center><img id=\"partial-\'+obj.id.substring(7)+\'\" src=\"\'+obj.src+\'\" border=\"0\"   height=\"90px\" align=\"absmiddle\" ></center></div>\');\r\n          \r\n   });\r\n   \r\n   \r\n   $(\'#\'+field_idx).val(JSON.stringify(list))\r\n    \r\n  \r\n}\r\n\r\nlast_select = null;\r\n\r\nfunction doSelectObj(obj){\r\n        \r\n         if(last_select!=null){\r\n                 \r\n                 $(\'#\'+last_select.id).removeClass(\'selected\');\r\n                 \r\n         }\r\n         \r\n         last_select = obj;\r\n         \r\n         $(\'#\'+obj.id).addClass(\'navitem selected\')\r\n    \r\n        $(\'#select-btn\').addClass(\'btn-info\')\r\n}\r\n\r\nfunction doAdd(){\r\n      \r\n  if(last_select!=null){\r\n        doSelectImg(last_select)\r\n        \r\n        $(\'#select-btn\').removeClass(\'btn-info\')\r\n        last_select=null\r\n  }        \r\n}\r\n\r\n\r\nfunction doSelectImg(obj){\r\n  body = $(\"#modal-selection\")\r\n  body.append(\"<img id=\'select-\"+obj.id.substring(7)+\"\' class=\'selected-img\' src=\'\"+obj.src+\"\' width=\'150px\' ondblclick=\'doSelectImg(this)\' />\");\r\n  $(\'#\'+obj.id).remove()\r\n  \r\n}\r\n\r\nfunction doList(fid){\r\n  field_idx = fid;\r\n    $(\"#modal-selection\").empty()\r\n    body = $(\"#modal-body\")\r\n    body.empty();\r\n  $(\'.eachpicimg\').each(function(i,obj){\r\n          path = obj.src+\"?\"+obj.id\r\n    body.append(\"<a href=\'\"+obj.src+\"\' ondblclick=\'return hs.expand(this)\' onclick=\'return false\' id=\'choicc-\"+obj.id+\"\'  ><img id=\'choice-\"+obj.id+\"\' src=\'\"+obj.src+\"\' class=\'navitem\' style=\'margin:1px\'  onclick=\'doSelectObj(this)\'  /></a>\");\r\n  });\r\n}\r\n\r\n\r\n</script>\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n</div></div></div><div id=\"page\" style=\"height:40px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</div></body></html>',NULL,NULL,NULL,'2014-01-07 14:50:27','2014-01-07 14:50:27','print','');
INSERT INTO `esm_operations` VALUES (925,'index',452,2,'\r\n<!--  Content -->\r\n\r\n\r\n\r\n<h2>Welcome Dr. Supasak <br/ ></h2>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12 not_sortable\">\r\n								<div class=\"w-box\">\r\n									<div class=\"w-box-header\">\r\n										Today Patient\r\n									</div>\r\n									<div class=\"w-box-content cnt_a\">\r\n\r\n									Today Patient\r\n									</div>\r\n								</div>\r\n</div>\r\n</div>\r\n\r\n			\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n									<div class=\"w-box-header\">\r\n										Today Patient\r\n									</div>\r\n									<div class=\"w-box-content cnt_a\">\r\n\r\n									Today Patient\r\n									</div>\r\n								</div>\r\n\r\n<h3 class=\"heading\">News</h3>\r\nActivities and News\r\n<br /><br />\r\n          \r\n          \r\n<%= link_to \"New Order\",\'../UserOrder/index\' ,:class=>\"btn btn-warning\"%>\r\n<%= link_to \"My Orders\",\'../UserOrder/index\' ,:class=>\"btn \"%>\r\n<%= link_to \"My Patients\",\'../UserPatient/index\' ,:class=>\"btn \"%>\r\n<%= link_to \"My Formula\",\'../UserFomula/index\' ,:class=>\"btn \"%>\r\n\r\n\r\n\r\n\r\n          \r\n                   \r\n                       \r\n                   </div>\r\n    					<div class=\"span4\">\r\n						\r\n							<div id=\"accordion1\" class=\"accordion\">\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											About Us\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapseOne1\">\r\n										<div class=\"accordion-inner\">\r\n											Anim pariatur cliche reprehenderit, enim eiusmod high life accusamus terry richardson ad squid. 3 wolf moon officia aute, non cupidatat skateboard dolor brunch. Food truck quinoa nesciunt laborum eiusmod. Brunch 3 wolf moon tempor, sunt aliqua put a bird on it squid single-origin coffee nulla assumenda shoreditch et. Nihil anim keffiyeh helvetica, craft beer labore wes anderson cred nesciunt sapiente ea proident. Ad vegan excepteur butcher vice lomo. Leggings occaecat craft beer farm-to-table, raw denim aesthetic synth nesciunt you probably haven\'t heard of them accusamus labore sustainable VHS.\r\n										<br />\r\n                                        <img src=\"/esm/aoim/www/cdip(1).jpg\" width=\"100\">&nbsp;&nbsp;\r\n                                        <img src=\"/esm/aoim/www/banner24674.jpg\"></div>\r\n									</div>\r\n								</div>\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											Why Custom Made\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n											Discover how... We make it easy. No more opening 5 bottles & taking 7 different vitamins every day.\r\nFind out how... You can avoid vitamin overdose and medication-vitamin interactions with our system.\r\nDid you know... Most vitamin capsules are made from animal by-products, while ours are 100% vegetarian?\r\nDiscover a formula to address all your health concerns in 1 dosage, 1 bottle and with a single expiration date.\r\n										</div>\r\n									</div>\r\n								</div>\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseThree1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n										Disclaimer: \r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"collapseThree1\">\r\n										<div class=\"accordion-inner\">\r\n											You should consult your physician before taking vitamins, minerals, health nutritional supplements or herbal products. Our vitamins and nutritional supplements products on this site are not intended to diagnose, treat, cure or prevent any disease. Statements made here have not been evaluated by the Food and Drug Administration.\r\n										</div>\r\n									</div>\r\n								</div>\r\n							</div>\r\n						</div>\r\n						\r\n                        \r\n                </div>\r\n\r\n',NULL,NULL,NULL,'2014-01-08 15:39:02','2014-01-08 15:39:02','index',''),(926,'layout',452,4,'<%=default_layout%>',NULL,NULL,NULL,'2014-01-08 15:39:02','2014-01-08 15:39:02','',''),(927,'document_name',453,1,'\'product\'',NULL,NULL,NULL,'2014-01-08 15:41:10','2014-01-08 15:41:10',NULL,NULL),(928,'document_name',454,1,'\'product_category\'',NULL,NULL,NULL,'2014-01-08 16:56:16','2014-01-08 16:56:16',NULL,NULL),(929,'document_name',455,1,'\'customer\'',NULL,NULL,NULL,'2014-01-08 17:00:21','2014-01-08 17:00:21',NULL,NULL),(930,'document_name',456,1,'\'order\'',NULL,NULL,NULL,'2014-01-08 17:00:52','2014-01-08 17:00:52',NULL,NULL),(931,'document_name',457,1,'\'patient\'',NULL,NULL,NULL,'2014-01-08 17:03:13','2014-01-08 17:03:13',NULL,NULL),(932,'document_name',458,1,'\'clinician\'',NULL,NULL,NULL,'2014-01-08 17:03:23','2014-01-08 17:03:23',NULL,NULL),(933,'document_name',459,1,'\'formula\'',NULL,NULL,NULL,'2014-01-09 16:31:37','2014-01-09 16:31:37',NULL,NULL),(934,'document_name',460,1,'\'manufacture_order\'',NULL,NULL,NULL,'2014-01-09 16:48:24','2014-01-09 16:48:24',NULL,NULL),(935,'document_name',461,1,'\'order_item\'',NULL,NULL,NULL,'2014-01-09 16:48:49','2014-01-09 16:48:49',NULL,NULL),(936,'document_name',462,1,'\'formula_item\'',NULL,NULL,NULL,'2014-01-09 16:49:14','2014-01-09 16:49:14',NULL,NULL),(937,'display',456,3,'<%\r\n  models = get_model \r\n  model = models[this.table_name.to_sym]\r\n  record = model.find(params[:id])\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n<hr/>\r\n<%\r\n   customer = models[:customer].find @record.customer_id\r\n   order_items = models[:order_item].where(:order_id=>@record.id).all\r\n   \r\n%>\r\n<%=order_items.inspect %>\r\n\r\n<%= tabular :model=>%w{quantity product_id patient_id manufacture_order},:data=>order_items %>\r\n\r\n',NULL,NULL,NULL,'2014-01-10 09:58:39','2014-01-10 09:58:39','display',''),(938,'document_name',463,1,'\'case_record\'',NULL,NULL,NULL,'2014-01-11 03:26:14','2014-01-11 03:26:14',NULL,NULL),(939,'form',463,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<% if params[:test] %>\r\n<%= @record.to_json %>\r\n<% end %>\r\n<%\r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  \r\n    cm = @module_model.where(:module_id=>@record.id).first\r\n    \r\n    if cm\r\n        patient = @patient_model.find(cm.patient_id)\r\n    else\r\n        patient = @patient_model.find(params[:patient_id])\r\n    end\r\n%>\r\n\r\n\r\n<script>\r\n\r\n\r\nfunction refresh_form(){\r\n\r\n intake = parseInt($(\"#data-intake\").val());\r\n output = parseInt($(\"#data-output\").val());\r\n \r\n parseInt($(\"#data-net_balance\").val(intake-output));\r\n //alert(intake+output)\r\n}\r\n\r\n$(\"#data-intake\").change(function(){\r\nrefresh_form();\r\n});\r\n$(\"#data-output\").change(function(){\r\nrefresh_form();\r\n});\r\n\r\n\r\n\r\nfunction refresh_form2(){\r\n    t_rs = $(\"#data-rs\").val();\r\n    t_co = $(\"#data-coagulation\").val();\r\n    t_cn = $(\"#data-cns\").val();\r\n    t_li = $(\"#data-liver\").val();\r\n    t_re = $(\"#data-renal\").val();\r\n    t_cv = $(\"#data-cvs\").val();\r\n    if (t_rs===\'00\' && \r\n        t_co===\'00\' &&\r\n        t_cn===\'00\' &&\r\n        t_li===\'00\' &&\r\n        t_re===\'00\' &&\r\n        t_cv===\'00\') {\r\n            \r\n        $(\"#data-sofa\").val(\'\');\r\n    } else {\r\n        rs = parseInt(t_rs);\r\n        coagulation = parseInt(t_co);\r\n        cns = parseInt(t_cn);\r\n        liver = parseInt(t_li);\r\n        renal = parseInt(t_re);\r\n        cvs = parseInt(t_cv);\r\n         \r\n        $(\"#data-sofa\").val(rs+coagulation+cns+liver+renal+cvs);\r\n    }\r\n    // console.log(\'rs : \'+ t_rs + \", coag : \" + t_co + \", cns : \" + t_cn + \", liver : \" + t_li + \", renal : \" + t_re + \", cvs : \" + t_cv);\r\n //alert(rs)\r\n}\r\n\r\n$(\"#data-rs\").change(function(){\r\nrefresh_form2();\r\n});\r\n$(\"#data-coagulation\").change(function(){\r\nrefresh_form2();\r\n});\r\n$(\"#data-cns\").change(function(){\r\nrefresh_form2();\r\n});\r\n$(\"#data-liver\").change(function(){\r\nrefresh_form2();\r\n});\r\n$(\"#data-renal\").change(function(){\r\nrefresh_form2();\r\n});\r\n$(\"#data-cvs\").change(function(){\r\nrefresh_form2();\r\n});\r\n\r\n\r\n//rate_of_vasopressor\r\n//dose_of_vasopressor\r\n//ml_of_vasopressor\r\n//patient_weight\r\n//cal_dose_vasopressor\r\n\r\n//(rate*dose*1000) / (ml*60*น้ำหนัก) \r\n\r\n\r\nfunction refresh_form3(){\r\n\r\n rate_of_vasopressor = parseInt($(\"#data-rate_of_vasopressor\").val());\r\n dose_of_vasopressor = parseInt($(\"#data-dose_of_vasopressor\").val());\r\n  ml_of_vasopressor = parseInt($(\"#data-ml_of_vasopressor\").val());\r\n patient_weight = parseInt($(\"#data-patient_weight\").val());\r\n \r\n $(\"#data-cal_dose_vasopressor\").val(((rate_of_vasopressor*dose_of_vasopressor*1000)/(ml_of_vasopressor*60*patient_weight)).toFixed(2));\r\n //alert()\r\n}\r\n\r\n$(\"#data-rate_of_vasopressor\").change(function(){\r\nrefresh_form3();\r\n});\r\n$(\"#data-dose_of_vasopressor\").change(function(){\r\nrefresh_form3();\r\n});\r\n$(\"#data-ml_of_vasopressor\").change(function(){\r\nrefresh_form3();\r\n});\r\n$(\"#data-patient_weight\").change(function(){\r\nrefresh_form3();\r\n});\r\n\r\n\r\nfunction refresh_form4(){\r\n\r\n effrent_fluid = parseInt($(\"#data-effrent_fluid\").val());\r\n total_time_crrt = parseInt($(\"#data-total_time_crrt\").val());\r\n \r\n parseInt($(\"#data-delivered_lose\").val((effrent_fluid/total_time_crrt).toFixed(2)));\r\n //alert(intake+output)\r\n}\r\n\r\n$(\"#data-effrent_fluid\").change(function(){\r\nrefresh_form4();\r\n});\r\n$(\"#data-total_time_crrt\").change(function(){\r\nrefresh_form4();\r\n});\r\n\r\n\r\nfunction refresh_form5(){\r\n\r\n \r\n \r\n patient_weight = 0\r\n \r\n<% \r\n    if patient and patient.weight \r\n        pat_w = patient.weight\r\n        if pat_w.to_i == 0\r\n            pat_w = patient[:ideal_body_weight]\r\n        end\r\n%>\r\n patient_weight = <%=pat_w%>\r\n<% \r\n    end \r\n    \r\n    hosp_name = @current_solution.name\r\n        io = 24 \r\n        tm = patient[:time_of_icu_admission].strftime(\'%H\').to_i\r\n        tm_00 = [\"rrts_21\"];\r\n        tm_06 = [\"rrts_1\", \"rrts_3\", \"rrts_4\", \"rrts_7\", \"rrts_9\", \"rrts_19\", \"rrts_23\", \"rrts_26\", \"rrts_27\"];\r\n        tm_07 = [\"rrts_6\", \"rrts_17\"];\r\n        tm_22 = [\"rrts_5\"];\r\n        tm_23 = [\"rrts_2\", \"rrts_11\", \"rrts_12\", \"rrts_13\", \"rrts_15\", \"rrts_16\"];\r\n        \r\n        if !tm_00.index(hosp_name).nil?\r\n            io = 0\r\n        elsif !tm_06.index(hosp_name).nil?\r\n            io = 6\r\n        elsif !tm_07.index(hosp_name).nil?\r\n            io = 7\r\n        elsif !tm_22.index(hosp_name).nil?\r\n            io = 22\r\n        elsif !tm_23.index(hosp_name).nil?\r\n            io = 23\r\n        end\r\n%>\r\n \r\n d = $(\"#data-record_day\").val();\r\n out24 = parseInt($(\"#data-urine_output24hr\").val());\r\n admit_hr = 24\r\n \r\n \r\n    if (d == 1) {\r\n<%\r\n    if patient and patient.time_of_icu_admission\r\n        \r\n        mn_diff = (60.0 - patient[:time_of_icu_admission].strftime(\'%M\').to_f)/60.0\r\n        \r\n        tm_diff = io - tm <= 0 ? 24 - (tm - io) : io - tm;\r\n        tm_diff = tm_diff + mn_diff\r\n        \r\n%>\r\n        admit_time = <%= tm %>;\r\n        // admit_cutt = new Date\r\n        admit_hr = <%= tm_diff %>;\r\n        hosp_name = \"<%= @current_solution.name %>\";\r\n        // alert(\'a<%= tm_diff %>x<%= tm %>i<%= io %>\');\r\n        console.log(\'tm_diff:\' + admit_hr + \'|tm:\' + admit_time + \'|io:\' + <%=io%> + \'|w:<%=pat_w%>|day-1\');\r\n        \r\n        /*\r\n        xx = $(\'#data-move_out_time\').val();\r\n        cs = $(\'#data-case_status\').val();\r\n        if (xx != \'\' && cs != \'0\') {\r\n            tt = xx.split(\':\');\r\n            io = <%= io %>;\r\n            hh = parseInt(tt[0]);\r\n            mm = parseFloat(tt[1])/60.0;\r\n            \r\n            tm_diff = 1;\r\n            if (hh - io <= 0) {\r\n                tm_diff = 24 - (io - hh);\r\n            } else {\r\n                tm_diff = hh - io;\r\n            }\r\n            tm_diff = tm_diff + mm;\r\n            admit_hr = tm_diff;\r\n            // alert(\'tm_diff:\' + tm_diff + \'|tm:\' + hh + \'|io:\' + io + \'|w:<%=pat_w%>|xx:\' + xx);\r\n        }\r\n        console.log(\'tm_diff:\' + tm_diff + \'|tm:\' + hh + \'|io:\' + io + \'|w:<%=pat_w%>|day-1:\' + xx); \r\n        */\r\n        \r\n<%\r\n        # end\r\n    else\r\n%>\r\n        alert(\'Time of ICU Admission not found!\');\r\n<%\r\n    end\r\n%>\r\n    }\r\n    \r\n    xx = $(\'#data-move_out_time\').val();\r\n    cs = $(\'#data-case_status\').val();\r\n    if (xx != \'\' && cs != \'0\' && d == 1) {\r\n        tt = xx.split(\':\');\r\n        io = <%= patient[:time_of_icu_admission].strftime(\'%H\') %>;\r\n        mn_diff = <%= (60.0 - patient[:time_of_icu_admission].strftime(\'%M\').to_f )/60.0 %>;\r\n        \r\n        hh = parseInt(tt[0]);\r\n        mm = parseFloat(tt[1])/60.0;\r\n        \r\n        tm_diff = 1;\r\n        if (hh - io <= 0) {\r\n            tm_diff = 24 - (io - hh);\r\n        } else {\r\n            tm_diff = hh - io;\r\n        }\r\n        tm_diff = tm_diff + mm - mn_diff;\r\n        admit_hr = tm_diff;\r\n        console.log(\'tm_diff:\' + tm_diff + \'|tm:\' + hh + \'|io:\' + io + \'|w:<%=pat_w%>|day-1_day-out:\' + xx);\r\n    } else if (xx != \'\' && cs != \'0\') {\r\n        tt = xx.split(\':\');\r\n        io = <%= io %>;\r\n        hh = parseInt(tt[0]);\r\n        mm = parseFloat(tt[1])/60.0;\r\n        \r\n        tm_diff = 1;\r\n        if (hh - io <= 0) {\r\n            tm_diff = 24 - (io - hh);\r\n        } else {\r\n            tm_diff = hh - io;\r\n        }\r\n        tm_diff = tm_diff + mm;\r\n        admit_hr = tm_diff;\r\n        console.log(\'tm_diff:\' + tm_diff + \'|tm:\' + hh + \'|io:\' + io + \'|w:<%=pat_w%>|day-out:\' + xx);\r\n    }\r\n    console.log(\'out24:\' + out24 + \',wt:\' + patient_weight + \',hr:\' + admit_hr);\r\n    $(\"#data-urine_output_cal\").val((out24/(patient_weight*admit_hr)).toFixed(4));\r\n\r\n //alert(intake+output)\r\n}\r\n\r\n\r\n\r\n\r\n$(\"#data-urine_output24hr\").change(refresh_form5);\r\n\r\n\r\n    list =[\"rrt\"];\r\n    control = {\'0\':\'rrt\'};\r\n   \r\n     \r\n    function update_if_rrt_func(){\r\n        options = [\"0\",\"1\"];\r\n        s = new Array()\r\n           \r\n        for(var i in list){\r\n              $(\".\"+list[i]+\'\').css(\"display\",\"none\");      \r\n        }\r\n        \r\n        for(var i in options)\r\n	    {\r\n		    if($(\"#update_if_rrt_item_\"+i).attr(\'checked\')==\'checked\'){\r\n				s.push(options[i])\r\n                \r\n                if(t=control[options[i]]){\r\n                    $(\".\"+t+\'\').css(\"display\",\"block\");\r\n                }\r\n			}\r\n		}\r\n        \r\n        t = \'anastomotic_css\'\r\n		$(\'#data-if_rrt\').val(s.join(\'|\'));\r\n        \r\n	}\r\n    \r\nupdate_if_rrt_func()\r\n\r\n\r\n\r\n\r\n    list2 =[\"ihd\",\"crrt\",\"pd\",\"sled\"];\r\n	control2 = {\'0\':\'ihd\',\'1\':\'crrt\',\'2\':\'pd\',\'3\':\'sled\'};\r\n    function update_mode_of_rrt_func(){\r\n    	options = [\"0\",\"1\",\"2\",\"3\"];\r\n	    s = new Array()\r\n	       \r\n        for(var i in list2){\r\n              $(\".\"+list2[i]+\'\').css(\"display\",\"none\");      \r\n        }\r\n        \r\n        for(var i in options)\r\n	    {\r\n		    if($(\"#update_mode_of_rrt_item_\"+i).attr(\'checked\')==\'checked\'){\r\n				s.push(options[i])\r\n                \r\n                if(t=control2[options[i]]){\r\n                    $(\".\"+t+\'\').css(\"display\",\"block\");\r\n                }\r\n			}\r\n		}\r\n        \r\n        t = \'anastomotic_css\'\r\n        \r\n		$(\'#data-mode_of_rrt\').val(s.join(\'|\'));\r\n        \r\n	}\r\n    \r\nupdate_mode_of_rrt_func()\r\n\r\n\r\n    list3 =[\"vasopressor_type\"];\r\n	control3 = {\'0\':\'vasopressor_type\'};\r\n    function update_vasopressor_func(){\r\n    	options = [\"0\",\"1\"];\r\n	    s = new Array()\r\n	       \r\n        for(var i in list3){\r\n              $(\".\"+list3[i]+\'\').css(\"display\",\"none\");      \r\n        }\r\n        \r\n        for(var i in options)\r\n	    {\r\n		    if($(\"#update_vasopressor_item_\"+i).attr(\'checked\')==\'checked\'){\r\n				s.push(options[i])\r\n                \r\n                if(t=control3[options[i]]){\r\n                    $(\".\"+t+\'\').css(\"display\",\"block\");\r\n                }\r\n			}\r\n		}\r\n        \r\n        t = \'anastomotic_css\'\r\n        \r\n		$(\'#data-vasopressor\').val(s.join(\'|\'));\r\n        \r\n	}\r\n    \r\nupdate_vasopressor_func()\r\n\r\n\r\n\r\n     list4 =[\"lumen_site\"];\r\n	control4 = {\'0\':\'lumen_site\'};\r\n    function update_type_of_catheter_func(){\r\n    	options = [\"0\",\"1\",\"2\"];\r\n	    s = new Array()\r\n	       \r\n        for(var i in list4){\r\n              $(\".\"+list4[i]+\'\').css(\"display\",\"none\");      \r\n        }\r\n        \r\n        for(var i in options)\r\n	    {\r\n		    if($(\"#update_type_of_catheter_item_\"+i).attr(\'checked\')==\'checked\'){\r\n				s.push(options[i])\r\n                \r\n                if(t=control4[options[i]]){\r\n                    $(\".\"+t+\'\').css(\"display\",\"block\");\r\n                }\r\n			}\r\n		}\r\n        \r\n        t = \'anastomotic_css\'\r\n        \r\n		$(\'#data-type_of_catheter\').val(s.join(\'|\'));\r\n        \r\n	}\r\n    \r\nupdate_type_of_catheter_func()\r\n\r\n\r\n   list5 =[\"moveout\"];\r\n	control5 = {\'1\':\'moveout\',\'2\':\'moveout\'};\r\n    function update_case_status_func(){\r\n    	options = [\"0\",\"1\",\"2\"];\r\n	    s = new Array()\r\n	       \r\n        for(var i in list5){\r\n              $(\".\"+list5[i]+\'\').css(\"display\",\"none\");      \r\n        }\r\n        \r\n        for(var i in options)\r\n	    {\r\n		    if($(\"#update_case_status_item_\"+i).attr(\'checked\')==\'checked\'){\r\n				s.push(options[i])\r\n                \r\n                if(t=control5[options[i]]){\r\n                    $(\".\"+t+\'\').css(\"display\",\"block\");\r\n                }\r\n			}\r\n		}\r\n \r\n		$(\'#data-case_status\').val(s.join(\'|\'));\r\n        \r\n	}\r\n    \r\nupdate_case_status_func()\r\n\r\n\r\n \r\n    function update_record_day_func(){\r\n\r\n        // $(\".recordday\").css(\"display\",\"none\");      \r\n        index = parseInt($(\'#data-record_day\').val());\r\n        if(index>3)\r\n        $(\".recordday\").remove()//.css(\"display\",\"block\");      \r\n	}\r\n \r\nupdate_record_day_func()\r\n\r\n$(\'#data-record_day\').change(update_record_day_func);\r\n\r\n    $(document).ready(function(){\r\n        $(\"input[type=\'radio\']\").click(function() {\r\n          var previousValue = $(this).attr(\'previousValue\');\r\n          var name = $(this).attr(\'name\');\r\n          var data = $(\'#\' + name.replace(\"update_\", \"data-\"));\r\n          \r\n          if (previousValue == \'checked\') {\r\n            $(this).removeAttr(\'checked\');\r\n            $(this).attr(\'previousValue\', false);\r\n            data.val(\"\");\r\n          } else {\r\n            $(\"input[name=\"+name+\"]:radio\").attr(\'previousValue\', false);\r\n            $(this).attr(\'previousValue\', \'checked\');\r\n          }\r\n        });\r\n    });\r\n    \r\n$(\'#data-bun_mmol\').change(function(){\r\n    v = $(this).val()\r\n\r\n    if(v!=\'\'){\r\n        vf = parseFloat(v)\r\n       \r\n        $(\'#data-bun\').val(vf*2.8)\r\n    }\r\n}) \r\n\r\n$(\'#data-cr_umol\').change(function(){\r\n    v = $(this).val()\r\n    if(v!=\'\'){\r\n        vf = parseFloat(v)\r\n        $(\'#data-creatinine\').val(vf*0.01131)\r\n    }\r\n});\r\n\r\nfunction update1(){\r\n    x = parseFloat($(\'#data-crrt_ufr\').val())\r\n    y = parseFloat($(\'#data-rfr_crrt\').val())\r\n    z = parseFloat($(\'#data-dfr_crrt\').val())\r\n    w = parseFloat($(\'#data-weight\').val())\r\n    if(w>0){\r\n    r = (x+y+z)/w\r\n    $(\'#data-prescribed_dose\').val(r.toFixed(3))\r\n    }\r\n    \r\n}\r\n$(\'#data-crrt_ufr\').change(update1);\r\n$(\'#data-rfr_crrt\').change(update1);\r\n$(\'#data-dfr_crrt\').change(update1);\r\n$(\'#data-weight\').change(update1);\r\n\r\nfunction update2(){\r\n    a = parseFloat($(\'#data-effrent_fluid\').val())\r\n    b = parseFloat($(\'#data-total_time_crrt\').val())\r\n    w = parseFloat($(\'#data-weight\').val())\r\n    if(w>0){\r\n    r = (a/b)/w\r\n    $(\'#data-delivered_lose\').val(r.toFixed(3))\r\n    }\r\n    \r\n}\r\n$(\'#data-effrent_fluid\').change(update2);\r\n$(\'#data-total_time_crrt\').change(update2);\r\n$(\'#data-weight\').change(update2);\r\n\r\n\r\n   \r\n</script>\r\n',NULL,NULL,NULL,'2014-01-11 14:28:48','2014-01-11 14:28:48','',''),(940,'document_name',464,1,'\'summary_form\'',NULL,NULL,NULL,'2014-01-11 14:43:00','2014-01-11 14:43:00',NULL,NULL),(949,'document_name',470,1,'\'patient\'',NULL,NULL,NULL,'2014-01-13 03:46:05','2014-01-13 03:46:05',NULL,NULL),(951,'print',334,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:presentation].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>HISTORY</title>\r\n\r\n<meta content=\"authenticity_token\" name=\"csrf-param\" />\r\n<meta content=\"8elRem1u07oLB/IYm3jjdDF7/GFlat6d6L3tdLr2wh4=\" name=\"csrf-token\" />\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n        display:none;\r\n        \r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm/cusys/colorectal_cancer/logo_colo_surgery.png\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3>HISTORY</h3>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n <!-- show patient -->\r\n<div id=\'patient\'>\r\n<!-- show patient -->\r\n<div id=\"patient\">\r\n<p style=\"width:900px; margin-left:auto; margin-right:auto; font-weight:bold\">Hospital No :&nbsp;<v><%=patient.hn if patient.hn%></v> Name : <v><%= patient.prefix_name if patient.prefix_name%> <%= patient.first_name if patient.first_name%> <%= patient.last_name if patient.last_name%></v></p>\r\n<hr><br>\r\n</div>\r\n\r\n\r\n<div style=\"width:100%;border: 0px solid red;background:#fff;padding-top:0px;padding-bottom:0px\" id=\"form-data\">\r\n    \r\n<div  style=\"margin-left:auto;margin-right:auto;width:900px;background:#fff;padding:0px;border:0px solid red\">\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n    \r\n\r\n<% if record[\'onset_year\']!=nil %>\r\n<div id=\"onset_year\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;min-height:30px;\">\r\n<span class=\"\"><label>Onset : </label> <v><%=render_value \'onset_year\'%></v> <label>Year</label> <v><%=render_value \'onset_month\'%></v> <label>Month</label> <v><%=render_value \'onset_day\'%></v> <label>Days</label> </span>    \r\n\r\n</div>\r\n<% end%>\r\n\r\n    \r\n\r\n\r\n<% if record[\'chief_complaints\']!=\"\" %>\r\n<div id=\"chief_complaints\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px;;min-height:30px;\">\r\n<span class=\"\"><label>Chief complaints : </label></span>    \r\n<v><%=render_value \'chief_complaints\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'co_morbid_disease\']!=\"\" %>\r\n<div id=\"co_morbid_disease\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;min-height:30px;\">\r\n<span class=\"\"><label>Co-morbid disease : </label></span>	\r\n<v><%=render_value \'co_morbid_disease\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<div class=\"clear\"></div>\r\n	\r\n\r\n\r\n<% if record[\'cardiac_disease\']!=\"\" %>\r\n<div id=\"cardiac_disease\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;min-height:30px;\">\r\n<span class=\"\"><label>Cardiac disease : </label></span>	\r\n<v><%=render_value \'cardiac_disease\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n\r\n<div class=\"clear\"></div>\r\n<% if record[\'warfarin_stop_date\']!=nil %>\r\n<div id=\"warfarin_stop_date\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:270px;min-height:30px;\">\r\n<span class=\"\"><label>Warfarin stop date (days) : </label></span>	\r\n<v><%=render_value \'warfarin_stop_date\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n<% if record[\'aspirin_stop_date\']!=nil %>\r\n<div id=\"aspirin_stop_date\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:270px;min-height:30px;\">\r\n<span class=\"\"><label>Aspirin stop date (days) : </label></span>	\r\n<v><%=render_value \'aspirin_stop_date\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n<% if record[\'clopidogrel_stop_date\']!=nil %>\r\n<div id=\"clopidogrel_stop_date\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n<span class=\"\"><label>Clopidogrel stop date (days) : </label></span>	\r\n<v><%=render_value \'clopidogrel_stop_date\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n\r\n<div class=\"clear\"></div>\r\n	\r\n\r\n\r\n<% if record[\'steroid_usage_detail\']!=\"\" %>\r\n<div id=\"steroid_usage_detail\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Steroid usage detail : </label></span>	\r\n<v><%=render_value \'steroid_usage_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'immunodeficiency_detail\']!=\"\" %>\r\n<div id=\"immunodeficiency_detail\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Immunodeficiency detail : </label></span>	\r\n<v><%=render_value \'immunodeficiency_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'other_detail\']!=\"\" %>\r\n<div id=\"other_detail\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Other detail : </label></span>	\r\n<v><%=render_value \'other_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n\r\n\r\n<% if record[\'past_history_of_cancer\']!=\"\" %>\r\n<div id=\"past_history_of_cancer\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:360px;min-height:30px;\">\r\n<span class=\"\"><label>Past History of Cancer : </label></span>	\r\n<v><%=render_value \'past_history_of_cancer\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n\r\n\r\n\r\n<% if record[\'smoking\']!=\"\" %>\r\n<div class=\"clear\"></div>\r\n<div id=\"smoking\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:100px;min-height:30px;\">\r\n<span class=\"\"><label>Smoking : </label></span>	\r\n<v><%=render_value \'smoking\'%></v>\r\n	\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'smoking_pack\']!=\"\" %>\r\n<div id=\"smoking_pack\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>Smoking (pack/year) : </label></span>	\r\n<v><%=render_value \'smoking_pack\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n	\r\n\r\n	\r\n\r\n\r\n<% if record[\'bw\']!=\"\" %>\r\n\r\n<div id=\"bw\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:180px;min-height:30px;\">\r\n<span class=\"\"><label>Body Weight (kg) : </label></span>	\r\n<v><%=render_value \'bw\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'ht\']!=\"\" %>\r\n<div id=\"ht\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:130px;min-height:30px;\">\r\n<span class=\"\"><label>Height (cm) : </label></span>	\r\n<v><%=render_value \'ht\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'bmi\']!=\"\" %>\r\n<div id=\"bmi\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:130px;min-height:30px;\">\r\n<span class=\"\"><label>BMI  : </label></span>	\r\n<v><%=render_value \'bmi\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n\r\n\r\n<% if record[\'familial_colorectal_cancer\']!=\"\" %>\r\n<div class=\"clear\"></div>\r\n<div id=\"familial_colorectal_cancer\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:450px;min-height:30px;\">\r\n<span class=\"\"><label>Familial colorectal cancer : </label></span>	\r\n<v><%=render_value \'familial_colorectal_cancer\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n\r\n<% if record[\'familial_colorectal_cancer_detail\']!=\"\" %>\r\n\r\n<div id=\"familial_colorectal_cancer_detail\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:430px;min-height:30px;\">\r\n<span class=\"\"><label>Familial colorectal cancer detail : </label></span>	\r\n<v><%=render_value \'familial_colorectal_cancer_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n\r\n<% if record[\'familial_other_cancer\']!=\"\" %>\r\n<div class=\"clear\"></div>\r\n<div id=\"familial_other_cancer\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:450px; ;min-height:30px;\">\r\n<span class=\"\"><label>Familial other cancer : </label></span>	\r\n<v><%=render_value \'familial_other_cancer\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'familial_other_cancer_detail\']!=\"\" %>\r\n\r\n<div id=\"familial_other_cancer_detail\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:430px;min-height:30px;\">\r\n<span class=\"\"><label>Familial other cancer detail : </label></span>	\r\n<v><%=render_value \'familial_other_cancer_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'first_degree_relation\']!=nil %>\r\n<div id=\"first_degree_relation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:280px;min-height:30px;\">\r\n<span class=\"\"><label>Number of First degree CRC : </label></span>	\r\n<v><%=render_value \'first_degree_relation\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'second_degree_relation\']!=nil %>\r\n<div id=\"second_degree_relation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:280px;min-height:30px;\">\r\n<span class=\"\"><label>Number of Second degree CRC : </label></span>	\r\n<v><%=render_value \'second_degree_relation\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'third_degree_relation\']!=nil %>\r\n<div id=\"third_degree_relation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:280px;min-height:30px;\">\r\n<span class=\"\"><label>Number of Third degree CRC : </label></span>	\r\n<v><%=render_value \'third_degree_relation\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'remarks\']!=\"\" %>\r\n<div id=\"remarks\" class=\"  portlet \" style=\"width:705px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Remarks : </label></span>	\r\n<v><%=render_value \'remarks\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'status\']!=\"\" %>\r\n<div id=\"status\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Status : </label></span>	\r\n<v><%=render_value \'status\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n<div id=\"page\" style=\"height:40px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2014-01-14 09:13:21','2014-01-14 09:13:21','print',''),(952,'print',336,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:pre_operative].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PREOPERATIVE EVALUATION</title>\r\n\r\n<meta content=\"authenticity_token\" name=\"csrf-param\" />\r\n<meta content=\"8elRem1u07oLB/IYm3jjdDF7/GFlat6d6L3tdLr2wh4=\" name=\"csrf-token\" />\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n        display:none;\r\n    	\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm/cusys/colorectal_cancer/logo_colo_surgery.png\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3>PREOPERATIVE EVALUATION</h3>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n <!-- show patient -->\r\n<div id=\"patient\">\r\n<p style=\"width:900px; margin-left:auto; margin-right:auto; font-weight:bold\">Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n<hr><br>\r\n</div>\r\n\r\n\r\n<div style=\"width:100%;border: 0px solid red;background:#fff;padding-top:0px;padding-bottom:0px\" id=\"form-data\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:900px;background:#fff;padding:0px;border:0px solid red\">\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n	\r\n\r\n\r\n<% if record[\'preoperative_ecog_performance_status\']!=\"\" %>\r\n<div id=\"preoperative_ecog_performance_status\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:850px;min-height:30px;\">\r\n<span class=\"\"><label>Preoperative ECOG performance status : </label></span>	\r\n<v><%=render_value \'preoperative_ecog_performance_status\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'preopearative_asa_physical_status_grading\']!=\"\" %>\r\n<div id=\"preopearative_asa_physical_status_grading\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:890px;min-height:30px;\">\r\n<span class=\"\"><label>Preopearative ASA physical status grading (revised classification) : </label></span>	<br />\r\n<v><%=render_value \'preopearative_asa_physical_status_grading\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'preoperative_continence_status\']!=\"\" %>\r\n<div id=\"preoperative_continence_status\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:890px;min-height:30px;\">\r\n<span class=\"\"><label>Preoperative continence status : </label></span>	<br />\r\n<v><%=render_value \'preoperative_continence_status\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'preoperative_albumin_level\']!=\"\" %>\r\n<div id=\"preoperative_albumin_level\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:850px;min-height:30px;\">\r\n<span class=\"\"><label>Preoperative albumin level (mg/dL.) : </label></span>	\r\n<v><%=render_value \'preoperative_albumin_level\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n	<% if record[\'malignancy_case\']!=\"\" %>\r\n<div id=\"193-F2794351063\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Malignant case</b> : <v><%=render_value \'malignancy_case\'%></v>\r\n		\r\n	</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<div id=\"193-F5893093878\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Malignancy information</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<% if record[\'preoperative_cea_level\']!=nil %>\r\n\r\n<div id=\"preoperative_cea_level\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Preoperative CEA (ng/dL.) : </label></span>	\r\n<v><%=render_value \'preoperative_cea_level\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'preoperative_ca_19_9\']!=nil %>\r\n<div id=\"preoperative_ca_19_9\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Preoperative CA 19-9 : </label></span>	\r\n<v><%=render_value \'preoperative_ca_19_9\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'preoperative_ca_125\']!=nil %>\r\n<div id=\"preoperative_ca_125\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Preoperative CA 125 : </label></span>	\r\n<v><%=render_value \'preoperative_ca_125\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'preoperative_psa\']!=nil %>\r\n<div id=\"preoperative_psa\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Preoperative PSA : </label></span>	\r\n<v><%=render_value \'preoperative_psa\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n\r\n\r\n<% if record[\'preoperative_tissue_pathology\']!=\"\" %>\r\n<div id=\"preoperative_tissue_pathology\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:500px;min-height:30px;\">\r\n<span class=\"\"><label>Preoperative tissue pathology : </label></span>	\r\n<v><%=render_value \'preoperative_tissue_pathology\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'adenocarcinoma_differentiation\']!=\"\" %>\r\n<div id=\"adenocarcinoma_differentiation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n<span class=\"\"><label>Adenocarcinoma Differentiation : </label></span>	\r\n<v><%=render_value \'adenocarcinoma_differentiation\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'squamous_cell_ca_differentiation\']!=\"\" %>\r\n<div id=\"squamous_cell_ca_differentiation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n<span class=\"\"><label>Squamous cell CA Differentiation : </label></span>	\r\n<v><%=render_value \'squamous_cell_ca_differentiation\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'other_preoperative_tissue_pathology_detail\']!=\"\" %>\r\n<div id=\"other_preoperative_tissue_pathology_detail\" class=\"  portlet \" style=\"width:700px;margin: 0 0.5em 0.5em 0;float:left;width:700px;min-height:30px;\">\r\n<span class=\"\"><label>Other detail : </label></span>	\r\n<v><%=render_value \'other_preoperative_tissue_pathology_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'previous_colorectal_cancer_procedure\']!=\"\" %>\r\n<div id=\"previous_colorectal_cancer_procedure\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;min-height:30px;\">\r\n<span class=\"\"><label>Preoperative procedure  : </label></span>	\r\n<v><%=render_value \'previous_colorectal_cancer_procedure\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'preoperative_chemotherapy\']!=\"\" %>\r\n<div id=\"preoperative_chemotherapy\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;min-height:30px;\">\r\n<span class=\"\"><label>Neoadjuvant chemo regimen : </label></span>	\r\n<v><%=render_value \'preoperative_chemotherapy\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'preoperative_radiotherapy_detail\']!=\"\" %>\r\n<div id=\"preoperative_radiotherapy_detail\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px;min-height:30px;\">\r\n<span class=\"\"><label>Neoadjuvant XRT dose (cGy) : </label></span>	\r\n<v><%=render_value \'preoperative_radiotherapy_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n<% if record[\'previous_colorectal_cancer_procedure_detail\']!=\"\" %>\r\n<div id=\"previous_colorectal_cancer_procedure_detail\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;min-height:30px;\">\r\n<span class=\"\"><label>Preoperative procedure details : </label></span>	\r\n<v><%=render_value \'previous_colorectal_cancer_procedure_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n\r\n<% if record[\'previous_abdominal_procedures\']!=\"\" %>\r\n<div id=\"previous_abdominal_procedures\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;min-height:30px;\">\r\n<span class=\"\"><label>Previous abdominal procedures : </label></span>	\r\n<v><%=render_value \'previous_abdominal_procedures\'%></v>\r\n</div>\r\n<% end%>\r\n	\r\n\r\n\r\n	<% if record[\'liver_metastasis\']!=\"\" %>\r\n<div  class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Liver metastasis</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n<div id=\"liver_metastasis\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Liver metastasis : </label></span>	\r\n<v><%=render_value \'liver_metastasis\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n\r\n<% if record[\'liver_metastasis_if_yes\']!=\"\" %>\r\n<div id=\"liver_metastasis_if_yes\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Liver metastasis if yes : </label></span>	\r\n<v><%=render_value \'liver_metastasis_if_yes\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'liver_metastasis_detail\']!=\"\" %>\r\n<div id=\"liver_metastasis_detail\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Liver metastasis detail : </label></span>	\r\n<v><%=render_value \'liver_metastasis_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n	<% if record[\'lung_metastasis\']!=\"\" %>\r\n<div  class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Lung metastasis</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n<div id=\"lung_metastasis\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Lung metastasis : </label></span>	\r\n<v><%=render_value \'lung_metastasis\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'lung_metastasis_if_yes\']!=\"\" %>\r\n<div id=\"lung_metastasis_if_yes\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Lung metastasis if yes : </label></span>	\r\n<v><%=render_value \'lung_metastasis_if_yes\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'lung_metastasis_detail\']!=\"\" %>\r\n<div id=\"lung_metastasis_detail\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Lung metastasis detail : </label></span>	\r\n<v><%=render_value \'lung_metastasis_detail\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n	<% if record[\'other_metastasis\']!=\"\" %>\r\n<div class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Other metastasis</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"other_metastasis\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Other metastasis : </label></span>	\r\n<v><%=render_value \'other_metastasis\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'other_metastasis_if_ye