ocker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \"Update\".html_safe, :class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   ',NULL,NULL,NULL,'2014-01-27 18:38:43','2014-01-27 18:38:43','edit',''),(987,'export',235,3,'\r\n<%\r\n\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n\r\n  @document = get_document(this.document_name)\r\n\r\n  doc = @document\r\n\r\n  data = get_model(this.document_name).all :sort=>\'created_at desc\', :limit=>4310, :offset=>0\r\n  \r\n   lfields = @document.fields\r\n   fields = lfields.collect{|i| [i.column_name,i.name,i] unless Document.visual_types.index(i.field_type) }.compact!\r\n   fields << \'created_at\'\r\n   fields << \'updated_at\'\r\n   \r\n   models = get_model\r\n   many_list = {}\r\n   \r\n   for f in fields\r\n    field = f[2]\r\n       \r\n    if f.size ==3 and field.field_type==\'relation_many\'\r\n       p = eval(\"{\\\\#{field.params}}\")[:relation][:document]\r\n       many_list[field.column_name] =  {:name=>field.column_name,:doc=>p, :model=>models[p.to_sym],:records=>[] }\r\n        \r\n    end\r\n   \r\n   \r\n   end\r\n   \r\n   \r\n   for i in data\r\n   begin\r\n        for j in many_list.keys\r\n        \r\n            if i[j] and i[j].size > 0 \r\n               \r\n               many_list[j][:records]+=i[j]\r\n                \r\n            end\r\n        \r\n        end\r\n        \r\n        rescue\r\n        \r\n    end\r\n    \r\n   end\r\n   \r\n   many_list.each_pair do |k,v|\r\n \r\n      many_document = get_document(many_list[k][:doc])\r\n      mfields = []\r\n      mfields = many_document.fields.collect{|i| [i.column_name,i.name]  } # if many_document\r\n\r\n      \r\n\r\n      records = v[:model].find v[:records]\r\n      m = {}\r\n      for i in records\r\n        \r\n        m[i.id] = i \r\n      end\r\n       \r\n      many_list[k][:map]=m\r\n      many_list[k][:fields]=mfields\r\n      \r\n \r\n   end\r\n   \r\n   \r\n%><%=include_header%>\r\n\r\n\r\n<h2><%= this.table_name  %></h2> <%= link_to \'Download\', \"#\", :id=>\'btnExport\', :class=>\'btn\' %><hr />\r\n<br />\r\n<div id=\"data\">\r\n<table border=\"1\">\r\n<tr><th>HN</th><th>Name</th><th>Gender</th><th>Birth Date</th><th>Age</th><th>Record date</th>\r\n\r\n<%\r\nfor i in fields \r\n%><th><%= i[1] %></th>\r\n<% end %>\r\n</tr>\r\n\r\n<% for i in data \r\n begin\r\n     @record = i\r\n\r\n    age = 0\r\n    hn = nil\r\n    \r\n    p = @patient_model.new\r\n    m = @module_model.collection.find(:module_id=>i.id).first\r\n    if m \r\n    \r\n    patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n    if patient\r\n    bdate = 0\r\n    bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n    age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n   \r\n    p = patient\r\n    p[\'record_date\'] = m[\'date\']\r\n    \r\n    end\r\n   end\r\n    \r\n    \r\n%>\r\n<tr>\r\n<td><%=p[\'hn\'] %></td><td><%=p[\'first_name\']%> <%=p[\'last_name\']%></td><td><%=p[\'gender\']%></td><td><%=p[\'birth_date\'].strftime(\'%d/%m/%Y\') if p[\'birth_date\'] %></td><td><%=age%></td><td><%=p[\'record_date\'].strftime(\'%d/%m/%Y\') if p[\'record_date\']%></td>\r\n\r\n<%\r\n    @document = doc\r\n    @fields = @document.fields\r\n    \r\n    for j in fields \r\n    \r\n    if i[j[0]]\r\n        \r\n    if j[2].field_type!=\'relation_many\'\r\n%>\r\n<td><%= render_value j[0] %></td>\r\n<% else \r\n\r\n m = many_list[j[0]]\r\n \r\n %>\r\n<td><table>\r\n        <!-- <tr>\r\n            <% for x in m[:fields] %>\r\n            <td>\r\n            <%= x[1]%>\r\n            </td>\r\n            <% end %>\r\n        </tr>-->\r\n            \r\n    <% for k in i[j[0]]\r\n       \r\n        r = m[:map][k]\r\n        %>\r\n        <tr>\r\n            <% for x in m[:fields] %>\r\n            <td>\r\n                <%=x[1]%>=<%=r[x[0].to_s]%>\r\n            </td>\r\n            <% end %>\r\n        </tr>\r\n    <% end %>\r\n    </table>\r\n</td>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n<% else %>\r\n<td>.</td>\r\n<% end %>\r\n<% end %>\r\n\r\n\r\n\r\n</tr>\r\n<% \r\nrescue\r\n\r\nend\r\n\r\nend %>\r\n\r\n</table>\r\n  \r\n</div>\r\n<script>\r\n    $(\"#btnExport\").click(function(e) {\r\n    window.open(\'data:application/vnd.ms-excel,\' + $(\'#data\').html());\r\n    e.preventDefault();\r\n});\r\n</script>\r\n   \r\n',NULL,NULL,NULL,'2014-01-30 10:17:18','2014-01-30 10:17:18','export',''),(988,'document_name',483,