:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n    list =[\"medial_meniscus\",\"lateral_meniscus\"];\r\n    control = {\'0\':\'medial_meniscus\',\'1\':\'lateral_meniscus\'};\r\n   \r\n     \r\n    function update_meniscal_surgery_func(){\r\n        options = [\"0\",\"1\"];\r\n        s = new Array()\r\n           \r\n        for(var i in list){\r\n              $(\".\"+list[i]+\'\').css(\"display\",\"none\");      \r\n        }\r\n        \r\n        for(var i in options)\r\n        {\r\n            if($(\"#update_meniscal_surgery_item_\"+i).attr(\'checked\')==\'checked\'){\r\n    			s.push(options[i])\r\n                \r\n                if(t=control[options[i]]){\r\n                    $(\".\"+t+\'\').css(\"display\",\"block\");\r\n                }\r\n			}\r\n		}\r\n        \r\n	$(\'#data-meniscal_surgery\').val(s.join(\'|\'));\r\n        \r\n	}\r\n    \r\nupdate_meniscal_surgery_func()\r\n\r\n\r\n\r\n\r\n    list2 =[\"graft_other\"];\r\n    control2 = {\'3\':\'graft_other\'};\r\n   \r\n     \r\n    function update_graft_func(){\r\n        options = [\"0\",\"1\",\"2\",\"3\"];\r\n        s = new Array()\r\n           \r\n        for(var i in list2){\r\n              $(\".\"+list2[i]+\'\').css(\"display\",\"none\");      \r\n        }\r\n        \r\n        for(var i in options)\r\n        {\r\n            if($(\"#update_graft_item_\"+i).attr(\'checked\')==\'checked\'){\r\n				s.push(options[i])\r\n                \r\n                if(t=control2[options[i]]){\r\n                    $(\".\"+t+\'\').css(\"display\",\"block\");\r\n                }\r\n			}\r\n		}\r\n        \r\n	$(\'#data-graft\').val(s.join(\'|\'));\r\n        \r\n	}\r\n    \r\nupdate_graft_func()\r\n</script>',NULL,NULL,NULL,'2014-02-03 07:58:20','2014-02-03 07:58:20','form',''),(993,'layout',364,4,'',NULL,NULL,NULL,'2014-02-05 14:25:09','2014-02-05 14:25:09','layout',''),(994,'index',486,2,'test',NULL,NULL,NULL,'2014-02-05 14:25:42','2014-02-05 14:25:42','index',''),(995,'history',472,2,'Hitory',NULL,NULL,NULL,'2014-02-08 02:52:57','2014-02-08 02:52:57','history',''),(996,'document_name',487,1,'\'patient\'',NULL,NULL,NULL,'2014-02-08 17:27:50','2014-02-08 17:27:50','',''),(997,'document_name',488,1,'\'formula\'',NULL,NULL,NULL,'2014-02-08 17:28:25','2014-02-08 17:28:25','',''),(998,'patho_index',146,3,'\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module for Pathology Unit</b></center><br/>\r\n\r\n</center>\r\n\r\n<hr/>\r\n<h3> New Requests</h3>\r\n\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    models = get_model\r\n    patho_model = models[:pathology]\r\n    \r\n    name = \"\\\\#{@current_project.name}#pathology\"\r\n    \r\n    list = module_model.where(:ref_number=>\'new\',:module_name=>name).all(:limit=>20,:order=>\'created_at desc\')\r\n    list.collect!{|i|\r\n        patient = patient_model.find i.patient_id\r\n        patho = patho_model.find i.module_id\r\n        {:id=>i.id,:patient_name=>\"\\\\#{patient.prefix_name}\\\\#{patient.first_name} \\\\#{patient.last_name}\",:hn=>patient.hn,:patho=>patho,:date=>i.date.strftime(\"%d-%m-%Y\") }if patient\r\n    }.compact!\r\n\r\n\r\n%>\r\n<%= tabular :data=>list,:model=>[:hn,:patient_name,:date],:labels=>{} do |row,out|\r\n  \r\n  out << link_to(\'Entry\' , \"../Pathology/edit?id=\\\\#{row[:id]}\",:class=>\'btn btn-info\')\r\n\r\n out\r\nend\r\n%> \r\n<hr/>\r\n<h3>Recently Update (3 days)</h3>\r\n<%\r\n\r\n  list = module_model.where(:updated_at=>{\'$gte\'=>Time.now-(24*3600*3)},:module_name=>name,:ref_number=>{\'$ne\'=>\'new\'}).all :limit=>10\r\n    list.collect!{|i|\r\n        patient = patient_model.find i.patient_id\r\n        patho = patho_model.find i.module_id\r\n        {:id=>i.id,:patient_name=>\"\\\\#{patient.prefix_name}\\\\#{patient.first_name} \\\\#{patient.last_name}\",:hn=>patient.hn,:patho=>patho,:date=>i.date.strftime(\"%d-%m-%Y\") }if patient\r\n        \r\n    }.compact!\r\n     \r\n%>\r\n<%= tabular :data=>list,:model=>[:hn,:patient_name,:date],:labels=>{} do |row,out|\r\n  \r\n  out << link_to(\'Show\' , \"../Pathology/show?id=\\\\#{row[:id]}\",:class=>\'btn\')\r\n\r\n out\r\nend\r\n%> \r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n',NULL,NULL,NULL,'2014-02-13 16:41:50','2014-02-13 16:41:50','patho_index',''),(999,'edit',206,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:record][:sxpathono],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n//  $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \"Update\".html_safe, :class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   ',NULL,NULL,NULL,'2014-02-13 17:11:08','2014-02-13 17:11:08','edit',''),(1000,'search',146,2,'<%\r\n\r\ndef get_hn i\r\n\r\n  n = \'\'\r\n  y = \'\'\r\n  \r\n  return i if i.size<5 or i.size>9\r\n  if i.index \'/\'  \r\n    t = i.split(\"/\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.index \'-\'  \r\n    t = i.split(\"-\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.size==8\r\n    y = i[0..1].to_i\r\n    y2 = i[-2..-1].to_i\r\n    n = i[3..-1].to_i  \r\n    if y2 > y\r\n      y = y2\r\n      n = i[0..-3].to_i    \r\n    end\r\n  else\r\n    y = i[-2..-1]\r\n    n = i[0..-3]\r\n  end\r\n  \r\n  hn = \"\\\\#{n.to_i.to_s}/\\\\#{y}\"\r\n\r\n  return hn    \r\n\r\nend\r\n\r\n%>\r\n<h1> Search Result </h1>\r\n<hr/>\r\n<% \r\n    models = get_model\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    fields = %w{hn public_id first_name last_name}\r\n    params[:query] = \'\' unless params[:query]\r\n    \r\n    query = params[:query].strip\r\n    \r\n    \r\n    \r\n    hn_mode=false\r\n    \r\n    \r\n    # if i = query.index(\'/\')\r\n    #     t = query.split(\'/\')\r\n    #     query = \"\\\\#{t[0].to_i}/\\\\#{t[1].to_i}\"\r\n    #     hn_mode = true  \r\n    # elsif query[0..-3].size>=4 and query.to_i !=0\r\n    #     query = \"\\\\#{query[0..-3].to_i}/\\\\#{query[-2..-1].to_i}\"\r\n    #     hn_mode = true  \r\n    # end\r\n    \r\n    if query.index(\'/\') or query.index(\'-\') or query.to_i>0\r\n        \r\n       query = get_hn query    \r\n       hn_mode = true\r\n        \r\n    end\r\n        \r\n        \r\n        %>\r\n        Query for \r\n        <%=query%>\r\n        \r\n        <%\r\n    \r\n    \r\n    # if query.size == 8 and query.index(\'/\')==nil\r\n    #   query = \"\\\\#{query[0..-3].to_i}/\\\\#{query[-2..-1].to_i}\" \r\n    # elsif query.index(\'/\')\r\n    \r\n    # end\r\n    \r\n    \r\n    keys = []\r\n    # fields.each do |f| \r\n    #     keys <<{f.to_sym=>Regexp.new(query)}\r\n    # end\r\n    keys << {:hn=>query}\r\n\r\n    \r\n    unless hn_mode\r\n    \r\n    keys << {:first_name=>Regexp.new(query)}\r\n    keys << {:last_name=>Regexp.new(query)}\r\n    keys << {:public_id=>query} if query.size==13\r\n    \r\n    end\r\n    \r\n    criteria = {\'$or\'=>keys}\r\n    \r\n    patients = patient_model.where(criteria).limit(100).all  \r\n    \r\n    app_name = \"\\\\#{@current_project.name}#appointment\"\r\n    app_model = models[:appointment]\r\n\r\n    if patients.size==1\r\n        row = patients[0]\r\n        ams = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).all.collect{|i| i.module_id }\r\n        app = app_model.where(:id=>{\'$in\'=>ams},:status=>{\'$nin\'=>[\'Cancelled\',\'No show\',\'Postpone\']}).all :sort=>\'date desc\'\r\n \r\nif app\r\n  \r\n#   app = app_model.where(:id=>am.module_id).first\r\n  app = app[0]\r\n  \r\n  if @current_role!=\'pathologist\'\r\n  url = \"../Home/patient_record?id=\\\\#{app.id}\"\r\n  else\r\n  url = \"../Home/patho_patient_record?id=\\\\#{app.id}\"\r\n  end\r\n\r\n  if true\r\n        \r\n        %>\r\n        <META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=<%=url_for(url)%>\">\r\n        <%\r\n        \r\n    end\r\n        \r\n    end\r\n   end\r\n   \r\n   xlist = [:first_name, :last_name]\r\n   \r\n   patients.sort!{|a,b| \r\n   \r\n   ia = -1\r\n   ia = 0 if a.first_name.index query\r\n   ia = 1 if a.last_name.index query\r\n   \r\n  \r\n   ib = -1\r\n   ib = 0 if b.first_name.index query\r\n   ib = 1 if b.last_name.index query\r\n   \r\n   if ia == ib\r\n        \r\n       a.created_at<=>b.created_at\r\n   \r\n   else\r\n       \r\n       ia<=>ib\r\n       \r\n   end\r\n   \r\n   \r\n   }\r\n   \r\n   \r\n   all_patients = []\r\n   all_mapp = {}\r\n   all_apps = []\r\n   map_apps = {}\r\n   \r\n   for i in patients\r\n   \r\n    all_patients << i.id\r\n   \r\n   end\r\n   \r\n   \r\n   \r\n   module_model.collection.find(:module_name=>\"\\\\#{app_name}\",:patient_id=>{\'$in\'=>all_patients}).to_a.each do |i| \r\n       \r\n         \r\n     all_mapp[i[\'patient_id\']] = [] unless  all_mapp[i[\'patient_id\']] \r\n     all_mapp[i[\'patient_id\']] << i\r\n     all_apps << i[\'module_id\']\r\n  \r\n  \r\n   end\r\n   \r\n   app_model.collection.find(:_id=>{\'$in\'=>all_apps}).to_a.each do |i|\r\n       \r\n       map_apps[i[\'_id\']] = i\r\n       \r\n   end\r\n   \r\n   all_mapp.keys.each do |k|\r\n      \r\n      apps = all_mapp[k]\r\n      \r\n    #   apps.sort!{|a,b| map_apps[a[\'module_id\']][\'date\']<=>map_apps[b[\'module_id\']][\'date\'] }\r\n       \r\n   end\r\n   \r\n   \r\n   \r\n%>\r\n\r\n<%= tabular :model=>fields,:data=>patients,:n=>10 do |row,out|\r\n\r\n#   am = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).order(\'date\').last\r\n#   ams = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).order(\'date\')