kground-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config.collect{|i| i if i[:name]==\'ETC\' }.compact\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.collect{|i| i if i.acl==\'pathologist\' }.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user = @current_solution.get_user_by_id locker.session\r\n   %>\r\n\r\n<%\r\n   text += \" by \" + user.login.split(\"@\")[0]\r\n#   text += locker.session\r\n%>\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2014-02-13 17:20:01','2014-02-13 17:20:01','patho_patient_record',''),(1002,'index',401,2,'<%\r\n    @tb = Time.now\r\n\r\n\r\n    module_name = @current_project.name\r\n    if params[:date]\r\n        session[module_name]={:date=>params[:date]}\r\n    end\r\n    if session[module_name]\r\n        params[:date] = session[module_name][:date]\r\n    end\r\n    unless params[:date]\r\n        params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n    end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Record</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"search\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-zoom\"></i><br />Search Patient</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<a href=\"followup\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-zoom\"></i><br />Follow up</button></a>\r\n\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n    });\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n   # aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n     aps = ap_model.all(:order=>\'created_at desc\') \r\n\r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n%>\r\n<%# aps.inspect %>\r\n<%\r\n    prov    = get_model[:provider].all.group_by{|i| i.id}\r\n    pro_map = get_model[:procedure].all.group_by{|i| i.id}\r\n    \r\n\r\n    app_map = {}    \r\n    \r\n    app_ids = aps.collect{|i| i.id}\r\n    app_mod = module_model.where(:module_name=>mname, :module_id=>app_ids).all\r\n    app_mod.each do |i|\r\n        app_map[i[:module_id]] = i\r\n    end\r\n    par_ids = app_mod.collect{|i| i.id}\r\n    \r\n    ma_rrt  = module_model.where(:module_name=>\"\\\\#{@current_project.name}#rrt_report\", :parent_id=>par_ids).all\r\n    ma_out  = module_model.where(:module_name=>\"\\\\#{@current_project.name}#outcome\", :parent_id=>par_ids).all\r\n    ma_crrt = module_model.where(:module_name=>\"\\\\#{@current_project.name}#crrt_day\", :parent_id=>par_ids).all\r\n    ma_sled = module_model.where(:module_name=>\"\\\\#{@current_project.name}#sled_day\", :parent_id=>par_ids).all\r\n\r\n    mg_rrt  = ma_rrt.group_by{|i| i[:parent_id]}\r\n    mg_out  = ma_out.group_by{|i| i[:parent_id]}\r\n    mg_crrt = ma_crrt.group_by{|i| i[:parent_id]}\r\n    mg_sled = ma_sled.group_by{|i| i[:parent_id]}\r\n    \r\n    rrt_ids = ma_rrt.collect{|i| i[:module_id]}\r\n    aa_rrt  = get_model[:rrt_report].find(rrt_ids)\r\n    ag_rrt  = aa_rrt.group_by{|i| i.id.to_s}\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    #   if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n        if m = app_map[i.id]\r\n         patient = patient_model.find(m.patient_id)\r\n        #  provider = p_model.find(i.provider)\r\n         provider = prov[i.provider][0] if prov[i.provider]\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n        #  pro = models[:procedure].find(i.procedure)\r\n         pro = pro_map[i.procedure][0] if pro_map[i.procedure]\r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n         #public_id = patient.public_id if patient\r\n         \r\n        #  mrrt = module_model.collection.find(:parent_id=>m.id,:module_name=>\"\\\\#{@current_project.name}#rrt_report\").first\r\n         mrrt = mg_rrt[m.id][0] if mg_rrt[m.id]\r\n         rrt_day = 0\r\n         rrt_check = false\r\n         if mrrt\r\n            rrt_check = true\r\n            # rrt = models[:rrt_report].find mrrt[\'module_id\'] \r\n            rrt = ag_rrt[mrrt[\'module_id\'].to_s][0] if ag_rrt[mrrt[\'module_id\'].to_s]\r\n            if rrt\r\n             \r\n                rrt_date = rrt.survival_28_days\r\n                if rrt_date\r\n                    rrt_day = (rrt_date.to_datetime.to_i - Time.now.to_i) /3600/24\r\n                end\r\n            end\r\n         end\r\n         \r\n        #  moutcome = module_model.collection.find(:parent_id=>m.id,:module_name=>\"\\\\#{@current_project.name}#outcome\").first\r\n         moutcome = mg_out[m.id][0] if mg_out[m.id]\r\n         outcome = false\r\n         if moutcome\r\n            outcome = true\r\n         end\r\n         \r\n         \r\n        # rrt_count = module_model.where(\'module_name\'=>\"\\\\#{@current_solution.name}#rrt_report\",:parent_id=>m.id).count\r\n        rrt_count = mg_rrt[m.id].nil? ? 0 : mg_rrt[m.id].count\r\n        rrt_alert = \"\"\r\n        if rrt_count == 0\r\n            # c_count = module_model.where(\'module_name\'=>\"\\\\#{@current_solution.name}#crrt_day\",:parent_id=>m.id).count\r\n            # s_count = module_model.where(\'module_name\'=>\"\\\\#{@current_solution.name}#sled_day\",:parent_id=>m.id).count\r\n            c_count = mg_crrt[m.id].nil? ? 0 : mg_crrt[m.id].count \r\n            s_count = mg_sled[m.id].nil? ? 0 : mg_sled[m.id].count\r\n            if c_count > 0 or s_count > 0\r\n                rrt_alert = \"<strong><font color=\'red\'>RRT</font></strong>&nbsp;&nbsp;\"\r\n            end\r\n        end       \r\n         \r\n         \r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>\"\\\\#{rrt_alert.html_safe} \"+link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date.strftime(\"%d-%m-%Y\"),:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Waiting\",:class=>\'btn btn-small btn-success\'),\r\n         :day_28=>rrt_day,:outcome=>outcome,:rrt_check=>rrt_check,\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n            c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n            status = \'btn-info\'\r\n            status = \'\' if i.status ==\'Completed\'\r\n            c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if true}.compact\r\n    \r\n    \r\n    alert = aps.collect{|i| i if i[:day_28]<=7 and !i[:outcome] and i[:rrt_check] }.compact\r\n    \r\n    \r\n    table_model = %w{date hn patient }.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n    \r\n    \r\n%>\r\n\r\n\r\n<%\r\n\r\n     tmp = alert\r\n\r\n%>\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_05\">    \r\n        <div class=\"w-box-header\">\r\n            28 Days Notification\r\n	    <div class=\"pull-right\"><i class=\"\"><%=tmp.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n       <%= tabular :model=>table_model+[:processing_ctrl],:data=>tmp,:labels=>labels do |row,out|\r\n       \r\n       out[0] += \"&nbsp;&nbsp;<span style=\'color:red\'>\\\\#{row[:day_28]} days</span> \"\r\n        \r\n       out\r\n       end\r\n       \r\n       \r\n       %>\r\n \r\n        \r\n        </div>\r\n    </div>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<br/>\r\n<%\r\n\r\n     tmp = waiting\r\n\r\n%>\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Recently Patients \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n       <%= tabular :model=>table_model+[:processing_ctrl],:data=>tmp[0..10],:labels=>labels %>\r\n\r\n        \r\n        </div>\r\n    </div>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<br/>\r\n<%  t = Time.new date.year, date.month,date.day\r\n%>\r\n\r\n<%\r\n   start = t.beginning_of_day\r\n   stop = t.end_of_day\r\n\r\n   modules = module_model.where(:module_name=>/\\\\#{@current_project.name}/i,:date=>{\"$gte\"=> start, \"$lt\"=> stop}).all\r\n   \r\n   modules.collect! do |i|\r\n   %>\r\n\r\n   <%\r\n   if i.module_name!=\"\\\\#{@current_project.name}#appointment\"\r\n         patient = patient_model.find(i.patient_id)\r\n        \r\n         hn = \'-\'\r\n         hn = patient.hn #link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         \r\n        ap =  module_model.find(i.parent_id)\r\n      if ap \r\n      ap = ap.module_id \r\n     {:public_id=>public_id, :hn=>hn, :patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\"),\r\n        :show=>link_to(\'Show\',\"../\\\\#{i.module_name.split(\'#\')[-1].camelize}/show?id=\\\\#{i.id}&record_name=\\\\#{hn}&return=../Home/patient_record?id=\\\\#{ap}\",:class=>\'btn btn-small\'), \r\n      :module_name=>i.module_name.split(\"#\")[-1].humanize,\r\n      :updated_at=>i.updated_at.strftime(\"%d-%m-%y\"),\r\n      :date=>i.date.strftime(\"%d-%m-%y\"),\r\n      \r\n     }\r\n     end\r\n     end\r\n   end\r\n   modules.compact!\r\n%>\r\n<%#\"\\\\#{@current_project.name}#appointment\"%>\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Recently Chart Reports \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n	     <%= tabular :model=>[:date, :updated_at,:hn, :patient, :module_name,:show],:data=>modules[0..10] do |row,out|\r\n             \r\n            out\r\n         end\r\n         %>\r\n    \r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n\r\n </div><br/>\r\n \r\n <script>\r\n $(\"#query\").focus();\r\n </script>\r\n <p></p>\r\n \r\n </div>\r\n \r\n <%\r\n    if @current_role==\'developer\'\r\n %>\r\n <%# g_rrt.to_json.html_safe %>\r\n <hr/>\r\n Processing Time : <%= Time.now - @tb %>\r\n <%\r\n    end\r\n %>',NULL,NULL,NULL,'2014-02-13 18:45:08','2014-02-13 18:45:08','',''),(1004,'create',477,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  home_url   = \"../../rrts/Home/index\"\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n     if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n    \r\n    rec1 = model.where(:hn=>params[:record][:patient_number]).first\r\n    # rec2 = model.all.sort_by{|i| i[:patient_order]}.reverse\r\n    # rec1 = nil\r\n    rec2 = nil\r\n    if rec1!=nil or rec2 != nil\r\n        # return_url = \"rrt\"\r\n    %>\r\n    \r\n<span style=\"color:red\"><b>Existing HN or Public ID</b></span><br/>\r\nWill be redirect in 3 seconds\r\n<meta http-equiv=\"Refresh\" content=\"3; url=<%= home_url.html_safe %>\">\r\n    <%\r\n    else\r\n    \r\n    # patients = model.all\r\n    # max = 0 \r\n    # for i in patients\r\n    #     max = i.patient_order if i.patient_order and max < i.patient_order\r\n    # end\r\n    # current = max +1\r\n    # params[:record][:patient_order] = current\r\n    \r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n   \r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n    end\r\n\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%=this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n<%= link_to \'Cancel\', home_url %>\r\n\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:320px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>A-gradient calculation</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    \r\n			<span style=\'width:80px\'>FiO2 : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"fio2\" id=\'fio2\' style=\"width:50px\"/>\r\n			</span>\r\n			\r\n			<span style=\'width:80px\'>Result : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"result\" id=\'result\' style=\"width:50px\"/></span>\r\n			\r\n			<div class=\"clear\"></div>\r\n			<span style=\'width:80px\'>PaCO2 : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"paco2\" id=\'paco2\' value=\'40\' style=\"width:50px\"/></span>\r\n			<div class=\"clear\"></div>\r\n			<span style=\'width:80px\'>PaO2 : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"pao2\" id=\'pao2\' value=\'\' style=\"width:50px\"/></span></span>\r\n\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>',NULL,NULL,NULL,'2014-02-17 05:29:32','2014-02-17 05:29:32','create',''),(1005,'document_name',489,1,'\'ercp\'',NULL,NULL,NULL,'2014-02-21 02:04:46','2014-02-21 02:04:46',NULL,NULL),(1006,'document_name',490,1,'\'gastro\'',NULL,NULL,NULL,'2014-02-25 09:59:00','2014-02-25 09:59:00',NULL,NULL),(1007,'document_name',491,1,'\'colono\'',NULL,NULL,NULL,'2014-02-25 10:50:22','2014-02-25 10:50:22',NULL,NULL),(1008,'document_name',492,1,'\'sigmoid\'',NULL,NULL,NULL,'2014-02-25 11:05:36','2014-02-25 11:05:36',NULL,NULL),(1009,'document_name',493,1,'\'eus\'',NULL,NULL,NULL,'2014-02-26 13:29:33','2014-02-26 13:29:33',NULL,NULL),(1010,'document_name',494,1,'\'push_enteroscopy\'',NULL,NULL,NULL,'2014-02-26 14:05:50','2014-02-26 14:05:50',NULL,NULL),(1011,'document_name',495,1,'\'double_balloon_enteroscopy\'',NULL,NULL,NULL,'2014-02-26 14:46:39','2014-02-26 14:46:39','',''),(1012,'document_name',496,1,'\'endoscopic_finding\'',NULL,NULL,NULL,'2014-03-03 04:00:30','2014-03-03 04:00:30',NULL,NULL),(1013,'document_name',497,1,'\'colonoscopy_scope\'',NULL,NULL,NULL,'2014-03-03 04:09:47','2014-03-03 04:09:47',NULL,NULL),(1014,'patient_record',146,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n.active a{\r\n    color:#000;\r\n}\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n\r\n    unless ap.date   \r\n    ap.date = Time.now\r\n    ap.save\r\n    end\r\n    \r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n\r\n\r\n<div id=\'prescope\' >&nbsp;</div>\r\n<br/>\r\n<script>\r\n\r\n<%\r\n\r\n url = \"../PreScope/pre_scope_detail?parent_id=\\\\#{pm.id}\"\r\n# url = \"../PreScope/pre_scope_detail?parent_id=\\\\#{params[:parent_id]}\" if params[:parent_id]\r\n \r\n%>\r\n\r\n$.ajax({\r\n  url: \"<%=url.html_safe%>\",\r\n  context: document.body\r\n}).done(function(data) { \r\n  $(\'#prescope\').html(data);\r\n <% unless params[:id] %>\r\n $(\'#data-bowel_preparation\').val(pre_scope[\"bowel_preparation\"]);\r\n $(\'#data-additional_bowel_preparation\').val(pre_scope[\"add_bowel_prep\"]);\r\n\r\n $(\'#data-bowel_cc\').val(pre_scope[\"bowelprep_cc\"]);\r\n $(\'#data-bowel_other\').val(pre_scope[\"bowel_other_note\"]);\r\n $(\'#data-add_bowel_prep_cc\').val(pre_scope[\"add_bowel_prep_cc\"]);\r\n $(\'#data-add_bowel_prep_other\').val(pre_scope[\"add_bowel_other\"]);\r\n \r\n <% end %> \r\n\r\n});\r\n</script>\r\n\r\n\r\n\r\n<%\r\n\r\ntoday = Time.now.strftime(\"%d-%m-%y\")\r\n\r\n#previous = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:module_name=>pm.module_name,:order=>\'date desc\')\r\nselect_today = false\r\ndate_map = {ap.id=>ap.date}\r\nprevious_map = {}\r\napps = emr_models[:appointment].where(:id=>{\'$in\'=>previous.collect{|i| i.module_id}},:status=>{\'$nin\'=>[\'Postpone\',\'Cancelled\',\'No show\']}).all\r\nfor i in apps\r\n    previous_map[i.id] = i\r\n    date_map[i.id] = i.date\r\n    if i.date and  i.date.strftime(\"%d-%m-%y\") == today\r\n      select_today = true  \r\n    end\r\nend\r\n%>\r\n<%#previous.inspect %>\r\n<%\r\n# previous = previous.collect{|i| i if previous_map[i.module_id] }.compact!\r\n\r\n\r\nunless select_today\r\n  today = date_map[previous[0].module_id].strftime(\"%d-%m-%y\") if date_map[previous[0].module_id]\r\nend\r\n\r\n\r\nhistory = []\r\nx = previous[0..9]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[10..-1]\r\nhistory = y.compact if y and  previous.size>8\r\n\r\nap.date = Time.now unless ap.date\r\n\r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\") if ap and ap.date\r\n\r\ncurrent = \'Today\' if current_date == today\r\n\r\n%>\r\n\r\n<%#last.collect{|i| i.id} %>\r\n\r\n<%#history.collect{|i| i.id} %>\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<% if false %>\r\n									<li class=\"<%=\'active\' if current==\'Today\'%>\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%><br/><%=ap.status%></a></li>\r\n                                    <% end %>\r\n                                    <%\r\n\r\n                                     for i in last \r\n                                     d = date_map[i.module_id]\r\n                                     if d\r\n                                    %>\r\n                                	<li class=\"<%=\'active\' if d and d.strftime(\"%d-%m-%y\")==today %>\"><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(d)%><br/><%=d.strftime(\"%d-%m-%y\") if d and i.date%><br/><%=previous_map[i.module_id].status if  previous_map[i.module_id] %></a></li>\r\n									<% end %>\r\n									<% end %>\r\n									\r\n                                    <% if history.size>0 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<br/>&nbsp;<br/>&nbsp;<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history \r\n                                              d = date_map[j.module_id]\r\n                                             if d\r\n                                            %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=d.strftime(\"%d-%m-%y\") if d%> : <%=time_ago_in_words(d) if d%></a></li>\r\n                                            <% end %>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<% if false %>\r\n<div class=\"tab-pane <%=\'active\' if current==\'Today\' or previous.size==0 %>\" id=\"a<%=pm.id%>\">\r\n<%#previous.size%>\r\n\r\n<h4><%= @current_project.title %> Recrods for <%=current_date %> #one</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service(i[:service]) }.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}|\\\\#{patient.first_name} \\\\#{patient.last_name}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}|\\\\#{patient.first_name} \\\\#{patient.last_name}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class if @current_role!=\'secretary\' %>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n    # locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.minutes.ago}).first\r\n\r\n\r\n\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_role_by_id locker.session\r\n   \r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name\r\n#   text += locker.session\r\n%>\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n\r\n<% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n<% end %>\r\n<% for i in previous \r\n pm = i\r\n d = date_map[i.module_id] \r\n if d\r\n%>\r\n<div class=\"tab-pane <%=\'active\' if d and  d.strftime(\"%d-%m-%y\")==today%>\" id=\"a<%=i.id%>\">\r\n<%= d.strftime(\"%d-%m-%y\") if d%>\r\n<h4><%= @current_project.title %> Recrods for <%=d.strftime(\"%d-%m-%y\")%></h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nnow = Time.now\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service] unless i[:exclude] }.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n\r\n<%if (now - i.created_at)/86400 < 30  or @current_role==\'developer\' and @current_role!=\'secretary\' %>\r\n<%= link_to \"Edit\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&ref_2=\\\\#{patient.first_name} \\\\#{patient.last_name}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-info\' if @current_role==\'incharge\' or  @current_role==\'admin\' or @current_role==\'superadmin\'  or @current_role==\'developer\' or (i.date and (Time.now - i.updated_at).to_i < 3600*24 ) or s.name==\'pre_scope\' %>\r\n&nbsp;<%= link_to \"Del\", \"../\\\\#{s.name.camelize}/destroy?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" ,:data=>{:confirm=>\'Are you sure?\'},:class=>\'btn btn-danger\' if @current_role==\'incharge\' or  @current_role==\'admin\' or  @current_role==\'superadmin\' or @current_role==\'developer\' %>\r\n<%end %>\r\n\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&ref_2=\\\\#{patient.first_name} \\\\#{patient.last_name}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>\'btn\' if @current_role!=\'secretary\'%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'btn\'%>\r\n\r\n<% end %>\r\n\r\n<% \r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>Time.now-3600}).first\r\n\r\n\r\n   text = \'\'\r\n   if locker\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n    \r\n   user,role,solution_user = @current_solution.get_user_role_by_id locker.session\r\n   \r\n#   user_name =  @current_user.login.split(\"@\")[0]\r\n#   user_name =  solution_user.name  if solution_user\r\n   \r\n   \r\n   user_name =  user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name\r\n   \r\n   text = \"<span>\\\\#{text}</span>&nbsp;\"+ image_tag(\'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\')\r\n   \r\n   end\r\n\r\n%>\r\n\r\n<%= text.html_safe %> \r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2014-03-03 16:48:43','2014-03-03 16:48:43','patient_record',''),(1015,'document_name',498,1,'\'gastroscopy_scope\'',NULL,NULL,NULL,'2014-03-04 02:56:02','2014-03-04 02:56:02',NULL,NULL),(1020,'index',499,2,'<div class=\"control-group formSep\"></div>\r\n<h3>ระบบลงทะเบียน</h3>\r\n\r\n<center>\r\n<a class =\"btn\" href=\"/esm/reg_cms/www/Member/create\">ลงทะเบียน</a>\r\n</center>',NULL,NULL,NULL,'2014-03-06 01:28:40','2014-03-06 01:28:40','',''),(1021,'layout',499,4,'<html>\r\n    <head>\r\n        <%=include_header%>\r\n        <style>\r\n\r\n    input{\r\n \r\n        height:24px;\r\n            }\r\n  \r\n\r\n</style>\r\n    </head>\r\n        \r\n<body style=\"width:720px; margin-left:auto; margin-right:auto; background:url(/esm/reg_cms/www/bgcolo.jpg) center no-repeat;\r\nbackground-size: cover;\">\r\n       \r\n<div class=\"row-fluid\" style=\"margin-top:30px\">\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"font-size:16px; border-top:1px #ddd solid; background:#fff;width:760px;padding:30px;\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n<img src=\"/esm/reg_cms/www/h.jpg\" style=\"width:700px;border:0px solid\">\r\n<div class=\"control-group \" style=\"width:650px\"><hr/></div>\r\n\r\n\r\n<%=yield :content %>\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2014-03-06 01:28:40','2014-03-06 01:28:40','',''),(1022,'document_name',500,1,'\'member\'',NULL,NULL,NULL,'2014-03-06 01:29:24','2014-03-06 01:29:24',NULL,NULL),(1023,'create',500,3,'<html>\r\n    <head>\r\n        <%=include_header%>\r\n        <style>\r\n\r\n    input{\r\n \r\n        height:24px;\r\n            }\r\n  \r\n\r\n</style>\r\n    </head>\r\n        \r\n<body style=\"width:720px; margin-left:auto; margin-right:auto; background:url(/esm/reg_cms/www/bgcolo.jpg) center no-repeat;\r\nbackground-size: cover;\">\r\n       \r\n<div class=\"row-fluid\" style=\"margin-top:30px\">\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"font-size:16px; border-top:1px #ddd solid; background:#fff;width:660px;padding:30px;\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'create\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'คุณได้ลงทะเบียนเรีบร้อยแล้วค่ะ ขอบคุณค่ะ\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n\r\n\r\n\r\n<img src=\"/esm/reg_cms/www/h.jpg\" style=\"width:600px;border:0px solid\">\r\n<div class=\"control-group \" style=\"width:650px\"><hr/></div>\r\n<h3>ลงทะเบียน</h3><br/>\r\n<%= this.form.html_safe %>\r\n<br/>\r\n<button class=\'btn btn-small\' style=\"width:200px;font-size:1.2em;height:36px\">ลงทะเบียน</button><br/>\r\n\r\n<%# link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n    <script>\r\n      $(\'#form-data\').css(\"width\",\"660px\")\r\n\r\n    $(\'#form-data div:first-child\').first().css(\"width\",\"660px\")\r\n    \r\n</script><br/>\r\n   <center>\r\n   <%=link_to \'รายชื่อผู้ลงทะเบียนล่วงหน้า\',\'pre_register\', :class=>\'\' %>\r\n</center>\r\n    </body>\r\n</html>\r\n',NULL,NULL,NULL,'2014-03-06 01:47:06','2014-03-06 01:47:06','create','*'),(1025,'index2',407,2,'\r\n<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Record</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"search\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-zoom\"></i><br />Search Patient</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n    });\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n   # aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n     aps = ap_model.all(:limit=>10,:order=>\'created_at desc\') \r\n\r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n         #public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date.strftime(\"%d-%m-%Y\"),:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Waiting\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if true}.compact\r\n    \r\n    \r\n    table_model = %w{date hn patient }.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n    \r\n    \r\n%>\r\n\r\n\r\n<%\r\n\r\n     tmp = waiting\r\n\r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Recently Patients \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n       <%= tabular :model=>table_model+[:processing_ctrl],:data=>tmp,:labels=>labels %>\r\n\r\n        \r\n        </div>\r\n    </div>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<br/>\r\n<%  t = Time.new date.year, date.month,date.day\r\n%>\r\n\r\n<%\r\n   start = t.beginning_of_day\r\n   stop = t.end_of_day\r\n\r\n   modules = module_model.where(:module_name=>/\\\\#{@current_project.name}/i,:date=>{\"$gte\"=> start, \"$lt\"=> stop}).all\r\n   \r\n   modules.collect! do |i|\r\n   %>\r\n\r\n   <%\r\n   if i.module_name!=\"\\\\#{@current_project.name}#appointment\"\r\n         patient = patient_model.find(i.patient_id)\r\n        \r\n         hn = \'-\'\r\n         hn = patient.hn #link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         \r\n        ap =  module_model.find(i.parent_id)\r\n      if ap \r\n      ap = ap.module_id \r\n     {:public_id=>public_id, :hn=>hn, :patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\"),\r\n        :show=>link_to(\'Show\',\"../\\\\#{i.module_name.split(\'#\')[-1].camelize}/show?id=\\\\#{i.id}&record_name=\\\\#{hn}&return=../Home/patient_record?id=\\\\#{ap}\",:class=>\'btn btn-small\'), \r\n      :module_name=>i.module_name.split(\"#\")[-1].humanize,\r\n      :updated_at=>i.updated_at.strftime(\"%d-%m-%y\"),\r\n      :date=>i.date.strftime(\"%d-%m-%y\"),\r\n      \r\n     }\r\n     end\r\n     end\r\n   end\r\n   modules.compact!\r\n%>\r\n<%#\"\\\\#{@current_project.name}#appointment\"%>\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Recently Chart Reports \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n	     <%= tabular :model=>[:date, :updated_at,:hn, :patient, :module_name,:show],:data=>modules do |row,out|\r\n             \r\n            out\r\n         end\r\n         %>\r\n    \r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n\r\n </div><br/>\r\n \r\n <script>\r\n $(\"#query\").focus();\r\n </script>',NULL,NULL,NULL,'2014-03-06 02:12:20','2014-03-06 02:12:20','index2',''),(1026,'confirmation',500,2,'<%=render :inline=>this.init%>\r\n<% if request.post? \r\n\r\n  cparams = params[:customer]\r\n\r\n  if params[:customer] and @models[:customer].where(:name=>cparams[:name]).first == nil and cparams[:password]==cparams[:password_confirmation]\r\n      \r\n      \r\n      \r\n    login = cparams[:admin_user]\r\n    password = cparams[:password]\r\n    \r\n    salt = User.random_string(10) \r\n    hashed_password = User.encrypt(password, salt)\r\n    \r\n    role_model = @models[:role]\r\n    role = role_model.where(:name=>\'customer\').first\r\n        \r\n    role = role_model.create :name=>\'customer\' unless role\r\n    \r\n    admin_user = @models[:user].create :login=>params[:customer][:admin_user],\'salt\'=>salt,\'hashed_password\'=>hashed_password,:role=>role.id\r\n      \r\n    customer = @models[:customer].create :name=>params[:customer][:name], \r\n    :contact_name=>params[:customer][:contact_name],\r\n    :tel=>params[:customer][:tel],\r\n    :address=>params[:customer][:address],\r\n    :email=>params[:customer][:email],\r\n    :fax=>params[:customer][:fax], :user_id=>admin_user.id\r\n     \r\n      \r\n      \r\n  end\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n%>\r\n<% end %>\r\n<% if customer %>\r\nNew customer \"<%=customer.name%>\" has been created \r\n<% else %>\r\nThere is existing customer for <%=params[:customer][:name]%>\r\n<%=link_to \'Back to registration\', \'index\' %>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2014-03-06 17:03:59','2014-03-06 17:03:59','confirmation',''),(1027,'document_name',501,1,'\'post\'',NULL,NULL,NULL,'2014-03-07 14:55:03','2014-03-07 14:55:03',NULL,NULL),(1028,'c