r\n<v><%=render_value \'graft_diameter\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'graft_length\']!=\"\" %>\r\n<div id=\"graft_length\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;min-height:10px;\">\r\n<span class=\"\"><label>Graft length (mm) : </label></span>	\r\n<v><%=render_value \'graft_length\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'femoral_fixation\']!=\"\" %>\r\n<div id=\"femoral_fixation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;min-height:10px;\">\r\n<span class=\"\"><label>Femoral fixation : </label></span>	\r\n<v><%=render_value \'femoral_fixation\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'tibial_fixation\']!=\"\" %>\r\n<div id=\"tibial_fixation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;min-height:10px;\">\r\n<span class=\"\"><label>Tibial fixation : </label></span>	\r\n<v><%=render_value \'tibial_fixation\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'meniscal_surgery\']!=\"\" %>\r\n<div id=\"meniscal_surgery\" class=\" meniscal_surgery portlet \" style=\"width:700px;margin: 0 0.5em 0.5em 0;float:left;width:160pxmin-height:10px;\">\r\n<span class=\"\"><label>Meniscal surgery : </label></span>	\r\n<v><%=render_value \'meniscal_surgery\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'medial_meniscus\']!=\"\" %>\r\n<div id=\"medial_meniscus\" class=\" medial_meniscus portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:550px;min-height:10px;\">\r\n<span class=\"\"><label>Medial meniscus : </label></span>	\r\n<v><%=render_value \'medial_meniscus\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'lateral_meniscus\']!=\"\" %>\r\n<div id=\"lateral_meniscus\" class=\" lateral_meniscus portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:550px;min-height:10px;\">\r\n<span class=\"\"><label>Lateral meniscus : </label></span>	\r\n<v><%=render_value \'lateral_meniscus\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n<div class=\"clear\"></div>\r\n\r\n<% if record[\'microfracture_hole_number\']!=\"\" %>\r\n<div id=\"microfracture_hole_number\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;min-height:10px;\">\r\n<span class=\"\"><label>Microfracture hole number : </label></span>	\r\n<v><%=render_value \'microfracture_hole_number\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'moseicplasty_plug_number\']!=\"\" %>\r\n<div id=\"moseicplasty_plug_number\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;min-height:10px;\">\r\n<span class=\"\"><label>Moseicplasty plug number : </label></span>	\r\n<v><%=render_value \'moseicplasty_plug_number\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n	\r\n\r\n\r\n<% if record[\'immobilizaition\']!=\"\" %>\r\n<div id=\"immobilizaition\" class=\"  portlet \" style=\"width:700px;margin: 0 0.5em 0.5em 0;float:left;width:600pxmin-height:10px;\">\r\n<span class=\"\"><label>Immobilizaition : </label></span>	\r\n<v><%=render_value \'immobilizaition\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n	\r\n<div class=\"clear\"></div>\r\n\r\n<% if record[\'complication\']!=\"\" %>\r\n<div id=\"complication\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;min-height:10px;\">\r\n<span class=\"\"><label>Complication : </label></span>	\r\n<v><%=render_value \'complication\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'drain\']!=\"\" %>\r\n<div id=\"drain\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;min-height:10px;\">\r\n<span class=\"\"><label>Drain : </label></span>	\r\n<v><%=render_value \'drain\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n<% if record[\'estimate_blood_loss\']!=\"\" %>\r\n<div id=\"estimate_blood_loss\" class=\"  portlet \" style=\"width:400px;margin: 0 0.5em 0.5em 0;float:left;min-height:10px;\">\r\n<span class=\"\"><label>Estimate blood loss (ml) : </label></span>	\r\n<v><%=render_value \'estimate_blood_loss\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n    \r\n\r\n\r\n\r\n\r\n   \r\n    \r\n	\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n</p>\r\n\r\n</div></div><div id=\"page\" style=\"height:40px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n<script>\r\nwindow.print();\r\n</script>\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2014-04-20 14:42:38','2014-04-20 14:42:38','print',''),(1077,'print',484,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:shoulder_arthroscopy].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n\r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Knee Arthroscopy Report</title>\r\n\r\n<meta content=\"authenticity_token\" name=\"csrf-param\" />\r\n<meta content=\"VZvldTYkv/AxMqGD+b5LMx6sKcKFmKskmMSfN99Nsi4=\" name=\"csrf-token\" />\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radiu