;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:270px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n        display:none;\r\n    	\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm/cusys/arthroscopy/Authro-logo.jpg\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3>Shoulder Arthroscopy Report</h3>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n<p>\r\n\r\n <!-- show patient -->\r\n<div id=\"patient\">\r\n<p style=\"width:900px; margin-left:auto; margin-right:auto; font-weight:bold\">\r\n<table width=\"100%\"><tr><td>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></td><td><% if record[\'date\']!=\"\" %>\r\n<div id=\"date\" style=\"width:200px;margin: 0 0.5em 0.5em 0;min-height:0px; float:right\">\r\n<span class=\"\">\r\n<label>Date of Record : </label></span>	\r\n<v><%=render_value \'date\'%></v>\r\n</div>\r\n<% end%></td></tr></table>\r\n\r\n\r\n\r\n</p>\r\n<hr><br>\r\n</div>\r\n\r\n\r\n<div style=\"width:100%;border: 0px solid red;background:#fff;padding-top:0px;padding-bottom:0px\" id=\"form-data\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:900px;background:#fff;padding:0px;border:0px solid red\">\r\n\r\n\r\n\r\n<div id=\"sortable\" class