etLength) {\r\n    var output = number + \'\';\r\n    while (output.length < targetLength) {\r\n        output = \'0\' + output;\r\n    }\r\n    return output;\r\n}\r\n\r\n\r\n    function parseDate(d,t){\r\n    \r\n    l = d.split(\"/\");\r\n    year = parseInt(l[2])\r\n    month = parseInt(l[1])\r\n    day = parseInt(l[0])\r\n    \r\n    if(year>2400)year-=543\r\n\r\n    text = \"\"+year+\"-\"+leftPad(month, 2)+\"-\"+leftPad(day, 2)+\"T\"+t;\r\n   \r\n    date = new Date(Date.parse(text));\r\n    \r\n    return date;\r\n    }\r\n\r\n\r\nfunction procedural_cal(){\r\n   \r\n   start_procedural_time = $(\'#data-start_procedural_time\').val()\r\n   stop_procedural_time = $(\'#data-stop_procedural_time\').val()\r\n   \r\n   start_procedural_date = parseDate($(\'#data-start_procedural_date\').val(),start_procedural_time)\r\n   stop_procedural_date = parseDate($(\'#data-start_procedural_date\').val(),stop_procedural_time)\r\n\r\n   min = (stop_procedural_date-start_procedural_date)/60000\r\n\r\n   hour = Math.floor(min/60)\r\n   min = min%60\r\n\r\n   $(\'#data-procedural_time\').val(\"\"+hour+\":\"+min)\r\n    \r\n}\r\n\r\n\r\n$(\'#data-stop_procedural_time\').change(procedural_cal);\r\n\r\nprocedural_cal();\r\n\r\n\r\n</script>',NULL,NULL,NULL,'2014-04-30 06:28:09','2014-04-30 06:28:09','form',''),(1093,'form',381,3,'\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   \r\n   \r\n\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n   \r\n   models = get_model\r\n   \r\n   m = @module_model.find(params[:id])\r\n   parent_id = params[:parent_id]\r\n   if m \r\n       parent_id = m.parent_id\r\n   end\r\n   \r\n   rrt_m = @module_model.where(:parent_id=>parent_id,:module_name=>\"\\\\#{@current_project.name}#rrt_report\").first\r\n   if rrt_m\r\n      \r\n      rrt = models[:rrt_report].find rrt_m.module_id\r\n       \r\n   end\r\n\r\n%>\r\n<%#  rrt_m.inspect %>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    function leftPad(number, targetLength) {\r\n    var output = number + \'\';\r\n    while (output.length < targetLength) {\r\n        output = \'0\' + output;\r\n    }\r\n    return output;\r\n    } \r\n\r\n    function parseDate(d){\r\n    \r\n    l = d.split(\"/\");\r\n    year = parseInt(l[2])\r\n    month = parseInt(l[1])\r\n    day = parseInt(l[0])\r\n    \r\n    if(year>2400)year-=543\r\n\r\n    text = \"\"+year+\"-\"+leftPad(month, 2)+\"-\"+leftPad(day, 2);\r\n    date = new Date(Date.parse(text));\r\n    \r\n    return date;\r\n    }\r\n    \r\n    \r\n    icu_admission_date = new Date();\r\n    rrt_start_date = new Date();\r\n    \r\n    <% if rrt %>\r\n    icu_admission_date = new Date(Date.parse(\'<%=rrt.icu_admission_date%>\'));\r\n    rrt_start_date = new Date(Date.parse(\'<%=rrt.rrt_start_date%>\' ));\r\n    <% end %>\r\n    \r\n    \r\n    function calculation(){\r\n        \r\n        msg = \'\'\r\n        \r\n        // icu_admission_date = parseDate($(\'#data-icu_discharge_date\').val());\r\n        // rrt_start_date\r\n        icu_discharge_date = parseDate($(\'#data-icu_discharge_date\').val());\r\n        scr_date = parseDate($(\'#data-scr_date\').val());\r\n        hospital_admission_date = parseDate($(\'#data-hospital_admission_date\').val())\r\n        hospital_discharge_date = parseDate($(\'#data-hospital_discharge_date\').val())\r\n        \r\n        \r\n        // alert(icu_discharge_date);\r\n        // alert(hospital_admission_date);\r\n        // alert(hospital_discharge_date);\r\n        //$(\'#data-day_on_rrt\').val((scr_date-rrt_start_date)/86400000)\r\n        $(\'#data-los_in_icu\').val((icu_discharge_date-icu_admission_date)/86400000)\r\n        $(\'#data-los_in_hospital\').val((hospital_discharge_date-hospital_admission_date)/86400000)\r\n        \r\n    }\r\n    $(\'#data-scr_date\').change(calculation)\r\n    $(\'#data-icu_discharge_date\').change(calculation)\r\n    $(\'#data-hospital_admission_date\').change(calculation)\r\n    $(\'#data-hospital_discharge_date\').change(calculation)\r\n    calculation()\r\n    \r\n    \r\n</script>',NULL,NULL,NULL,'2014-04-30 17:00:25','2014-04-30 17:00:25','form',''),(1094,'document_name',521,1,'\'gastroscopy_stomach\'',NULL,NULL,NULL,'2014-05-01 11:50:07','2014-05-01 11:50:07',NULL,NULL),(1095,'report_old',481,2,'\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    # patients =  module_model.all(:module_name=>mname)\r\n    @models = get_model\r\n    \r\n    list = []\r\n    \r\n    \r\n    def month_query model,date_field, value_field\r\n           \r\n           from_date = Time.now.at_beginning_of_year()\r\n           \r\n           list = model.collection.group({:keyf=>\"function(doc){return {month:doc.\\\\#{date_field}.getMonth(), name:doc.\\\\#{value_field}};}\",\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{date_field=>{\'$gte\'=>from_date}}})\r\n    \r\n        return list\r\n        \r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    list = module_model.collection.group({:keyf=>\'function(doc){return {month:doc.date.getMonth(),name:doc.module_name};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}})\r\n    \r\n    list = month_query module_model, \'date\',\'module_name\'\r\n    \r\n    list2 = month_query @models[:summary_form], \'date_of_icu_discharge\', \'icu_discharge_status\'\r\n    \r\n    \r\n    %>\r\n    <%# @models[:summary_form].all %>\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    <%\r\n    \r\n    \r\n          \r\n          \r\n    columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n   \r\n    map = {}\r\n    data = []\r\n         \r\n    if list.size>0    \r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    name = i[\'name\'].split(\'#\')[1]\r\n    map[name] = {\'name\'=>name.humanize, \'data\'=>[]} unless map[name] \r\n    map[name][\'data\'][i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\n    end\r\n    map.each_pair do |k,v|\r\n    if k!=\'appointment\'\r\n        data << v    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n   \r\n    columns = mlabels\r\n\r\n%>\r\n\r\n<%#list.inspect%>\r\n<h3>Summary</h3>\r\n\r\n<%\r\n\r\n%>\r\n\r\n<div id=\"chart\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n\r\n<br/>\r\n\r\n<%\r\n     patients = patient_model.all\r\n     \r\n     list = []\r\n     \r\n     for i in patients\r\n        date = i.date_of_admission\r\n        if date\r\n        month = date.month-1\r\n        list[month] = 0 unless list[month] \r\n        list[month] +=1\r\n    end \r\n    \r\n     end\r\n     \r\n     \r\n     result = {\"name\"=>\"Patient Admit Date\", \"data\"=>list} \r\n     data[0] = result\r\n\r\n%>\r\n\r\n\r\n\r\n            <script>\r\n                function createChart() {\r\n                    $(\"#chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                            \r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                }\r\n\r\n                $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n                });\r\n            </script>\r\n\r\n\r\n\r\n<%# data.inspect %>\r\n<%# patients.size %>\r\n\r\n\r\n\r\n<%# columns.inspect %>\r\n',NULL,NULL,NULL,'2014-05-06 08:49:03','2014-05-06 08:49:03','report_old',''),(1097,'ws',481,3,'<%\r\n\r\n  @module_name = @current_project.name+\'#summary_form\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n\r\n    tp = @patient_model.count\r\n    tc = @models[:summary_form].count\r\n\r\n%>\r\n<div style=\"width:200px;height:120px;border:1px solid #ccc;padding:20px \">\r\n<center><b><%=get_setting(\'hn\')%></b></center><br/>\r\n<center>Total Patients : <span  style=\"color:blue\"><%=@patient_model.count %></span></center><br/>\r\n<center>Total Complete : <span  style=\"color:blue\"><%=@models[:summary_form].count %></span></center><br/>\r\n<span style=\"font-size:0.8em\" ><center><%=Time.now %> <span id=\"update-<%=params[:id]%>\"></span></center></span>\r\n</div>\r\n<script>\r\n    updateStat(<%=params[:id]%>,\"<%=get_setting(\'hn\')%>\",<%=tp%>,<%=tc%>)\r\n</script>',NULL,NULL,NULL,'2014-05-06 17:12:54','2014-05-06 17:12:54','ws','*'),(1098,'edit',477,2,'<%\r\n\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  \r\n  return_url = url(\"index\")\r\n  return_url = params[:return] if params[:return]\r\n\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:320px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>A-gradient calculation</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    \r\n			<span style=\'width:80px\'>FiO2 : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"fio2\" id=\'fio2\' style=\"width:50px\"/>\r\n			</span>\r\n			\r\n			<span style=\'width:80px\'>Result : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"result\" id=\'result\' style=\"width:50px\"/></span>\r\n			\r\n			<div class=\"clear\"></div>\r\n			<span style=\'width:80px\'>PaCO2 : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"paco2\" id=\'paco2\' value=\'40\' style=\"width:50px\"/></span>\r\n			<div class=\"clear\"></div>\r\n			<span style=\'width:80px\'>PaO2 : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"pao2\" id=\'pao2\' value=\'\' style=\"width:50px\"/></span></span>\r\n\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>',NULL,NULL,NULL,'2014-05-14 06:34:13','2014-05-14 06:34:13','edit',''),(1099,'overview',522,2,'\r\n<script src=\"/jqplot/jquery.jqplot.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.dateAxisRenderer.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.logAxisRenderer.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.canvasTextRenderer.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.canvasAxisTickRenderer.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.categoryAxisRenderer.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.pointLabels.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.highlighter.min.js\"></script>\r\n<link rel=\"stylesheet\" type=\"text/css\" hrf=\"/jqplot/jquery.jqplot.min.css\" />\r\n\r\n<h1>Overview Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n\r\n<% \r\n    now = Time.now\r\n    beginning_of_year = now.beginning_of_year()\r\n    the_year_before = (beginning_of_year-1).beginning_of_year()\r\n    beginning_of_month = now.beginning_of_month()\r\n    \r\n    \r\n    # last_year = @models[:appointment].collection.find(:date=>{\'$gte\'=>the_year_before,\'$lte\'=>beginning_of_year}).count()\r\n    # this_year = @models[:appointment].collection.find(:date=>{\'$gte\'=>beginning_of_year,\'$lte\'=>now}).count()\r\n    # this_month = @models[:appointment].collection.find(:date=>{\'$gte\'=>beginning_of_month,\'$lte\'=>now}).count()\r\n       \r\n    # last_year_counts =  @models[:appointment].collection.group( { :keyf => \"function(x){ return {month : x.date.getMonth()}; }\" , \r\n    # :cond => {:date=>{\'$gte\'=>the_year_before,\'$lte\'=>beginning_of_year}}, \r\n    # :reduce => \'function(doc,prev) { prev.count += 1; }\', \r\n    # :initial => {:count => 0} })\r\n    \r\n    # this_year_counts =  @models[:appointment].collection.group( { :keyf => \"function(x){ return {month : x.date.getMonth()}; }\" , \r\n    # :cond => {:date=>{\'$gte\'=>beginning_of_year,\'$lte\'=>now}}, \r\n    # :reduce => \'function(doc,prev) { prev.count += 1; }\', \r\n    # :initial => {:count => 0} })\r\n     def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    def query_func beginning, ending\r\n        \r\n        pname = \"\\\\#{@current_project.name}#\"\r\n        \r\n        all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>beginning,\'$lt\'=>ending}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n        m_app = bmap all_app, \'_id\'\r\n    \r\n\r\n        all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n        m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n        \r\n           # all pm colono of those appointments\r\n        all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n        m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n        # all pm colono of those appointments\r\n        all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n        m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n       \r\n        exist = all_pm_app.collect{|i|\r\n        \r\n            m_app[i[\'module_id\']][0] if m_all_pm_colo[i[\'_id\']] or m_all_pm_gastro[i[\'_id\']]\r\n        \r\n        }.compact\r\n        \r\n        map = {}\r\n        \r\n        for i in exist\r\n        m = i[\'date\'].month\r\n        \r\n        map[m] = 0 unless map[m]\r\n        map[m] += 1\r\n        \r\n        end\r\n        list = []\r\n        \r\n        map.each_pair do |k,v|\r\n           list<<{\'month\'=>k-1,\'count\'=>v} \r\n        end\r\n        \r\n        \r\n        return list\r\n    end\r\n    def count_func x\r\n       sum = 0 \r\n       for i in x \r\n        sum+= i[\'count\']\r\n       end\r\n       return sum\r\n    end\r\n    \r\n    # last_year = @models[:appointment].collection.find(:date=>{\'$gte\'=>the_year_before,\'$lte\'=>beginning_of_year}).count()\r\n    # this_year = @models[:appointment].collection.find(:date=>{\'$gte\'=>beginning_of_year,\'$lte\'=>now}).count()\r\n    # this_month = @models[:appointment].collection.find(:date=>{\'$gte\'=>beginning_of_month,\'$lte\'=>now}).count()\r\n    \r\n    \r\n    last_year_counts =  query_func the_year_before, beginning_of_year\r\n    this_year_counts =  query_func beginning_of_year, now\r\n    this_month_counts =  query_func beginning_of_month, now\r\n\r\n    last_year = count_func last_year_counts\r\n    %>\r\n    <%#this_year_counts.inspect %>\r\n    <%\r\n    this_year = count_func this_year_counts\r\n    this_month = count_func this_month_counts\r\n    \r\n    last_x = {}\r\n    this_x = {}\r\n    \r\n    for i in last_year_counts\r\n        last_x[i[\'month\']] = i\r\n    end\r\n    \r\n    \r\n    for i in this_year_counts\r\n        this_x[i[\'month\']] = i\r\n    end\r\n    \r\n    \r\n    # list = []\r\n    # counts.each {|r| results[r[\"event_type\"]] = r[\"count\"]}\r\n    \r\n    last_count = []\r\n    this_count = []\r\n    \r\n    acc = 0 \r\n    12.times do |i|\r\n        count = last_x[i]\r\n        if count \r\n            acc+=count[\'count\']\r\n            last_count<< acc #[the_year_before.strftime(\"%Y-\")+format(\'%02d\',i+1)+\"-01\",acc]\r\n            \r\n        else\r\n            last_count<< acc #[the_year_before.strftime(\"%Y-\")+format(\'%02d\',i+1)+\"-01\",acc]\r\n        end\r\n    end\r\n    \r\n       acc = 0 \r\n    12.times do |i|\r\n        count = this_x[i]\r\n        if count \r\n            acc+=count[\'count\']\r\n            this_count<< acc #[beginning_of_year.strftime(\"%Y-\")+format(\'%02d\',i+1)+\"-01\",acc]\r\n            \r\n        else\r\n            this_count<< acc #[beginning_of_year.strftime(\"%Y-\")+format(\'%02d\',i+1)+\"-01\",acc]\r\n        end\r\n    end\r\n    \r\n    \r\n%>\r\n<%# last_count.inspect %>\r\n\r\n<%# this_count.inspect %>\r\n\r\n<style>\r\n    .red{color:red};\r\n    .blue{color:blue};\r\n</style>\r\n<div class=\"span12 tac\">\r\n							<ul class=\"ov_boxes\">\r\n								<li>\r\n									<div class=\"ov_text red\">\r\n										<strong><%= last_year%> cases</strong>\r\n										Last year ( <%=the_year_before.year%>    ) Avg.<%=last_year/12%>\r\n									</div>\r\n								</li>\r\n								<li>\r\n									<div class=\"ov_text blue\" style=\"color:blue\">\r\n										<strong><%=this_year%> cases</strong>\r\n										This year ( <%=beginning_of_year.year%> ) Avg.<%= this_year/beginning_of_month.month %>\r\n									</div>\r\n								</li>\r\n								<li>\r\n									<div class=\"ov_text\">\r\n										<strong><%=this_month %> cases</strong>\r\n										This month ( <%=beginning_of_month.strftime(\'%b %Y\')%> )\r\n									</div>\r\n								</li>\r\n								\r\n							</ul>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div style=\"margin-left:auto;margin-right:auto;border:0px solid\">\r\n<center>    \r\n<div id=\"chart3\" style=\"width:600px;height:400px;color:#666\">\r\n    \r\n    \r\n</div>\r\n<div id=\"chart\" style=\"width:600px;height:400px;color:#666\">\r\n    \r\n    \r\n</div>\r\n</center>\r\n\r\n</div>\r\n<%\r\n    months = %W{Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec}\r\n    \r\n    count = 0\r\n    last_count.collect!{|i| \r\n        result = [months[count], i ] \r\n        count +=1\r\n        result\r\n    }\r\n    count = 0 \r\n    this_count.collect!{|i| \r\n        result = [months[count], i ] \r\n        count +=1\r\n        result\r\n    }\r\n    \r\n    # count = 0 \r\n    # last_year_counts.collect!{|i| \r\n    #     result = [months[count], i ] \r\n    #     count +=1\r\n    #     result\r\n    # }\r\n    \r\n    \r\n%>\r\n<%#this_count.inspect %>\r\n<script>\r\n$(document).ready(function(){\r\n    \r\n    \r\n     var line1 = [[\'Cup Holder Pinion Bob\', 7], [\'Generic Fog Lamp\', 9], [\'HDTV Receiver\', 15], \r\n  [\'8 Track Control Module\', 12], [\' Sludge Pump Fourier Modulator\', 3], \r\n  [\'Transcender/Spice Rack\', 6], [\'Hair Spray Danger Indicator\', 18]];\r\n    \r\n  var plot1 = $.jqplot (\'chart3\', [<%=last_count.to_json.html_safe%>,<%=this_count.to_json.html_safe%>],{\r\n      title: \'Cases by Year Comparison\',\r\n      seriesColors: [\"rgba(255, 100, 100, 0.7)\", \"rgba(0, 0, 255,0.7)\"],\r\n      highlighter: {\r\n            show: true,\r\n            sizeAdjust: 1,\r\n            tooltipOffset: 9\r\n     }, axesDefaults: {\r\n        tickRenderer: $.jqplot.CanvasAxisTickRenderer ,\r\n        tickOptions: {\r\n          angle: -30,\r\n          fontSize: \'10pt\'\r\n        }\r\n     },seriesDefaults: { \r\n        showMarker:true,\r\n        pointLabels: { show:true } \r\n      },\r\n\r\n     axes: {\r\n        // options for each axis are specified in seperate option objects.\r\n        xaxis: {\r\n            renderer: $.jqplot.CategoryAxisRenderer\r\n        },\r\n        yaxis: {\r\n          label: \"Cases\",\r\n          min: 0\r\n        }\r\n      }\r\n  });\r\n})\r\n\r\n\r\n$(document).ready(function () {\r\n    $.jqplot._noToImageButton = true;\r\n    \r\n    // var prevYear = <%=last_count.to_json.html_safe%>;\r\n \r\n    // var currYear =  <%=this_count.to_json.html_safe%>;\r\n \r\n    // var plot1 = $.jqplot(\"chart3\", [prevYear, currYear], {\r\n        \r\n    //     seriesColors: [\"rgba(255, 100, 100, 0.7)\", \"rgba(0, 0, 255,0.7)\"],\r\n    //     title: \'Cases by Year Comparison\',\r\n    //     highlighter: {\r\n    //         show: true,\r\n    //         sizeAdjust: 1,\r\n    //         tooltipOffset: 9\r\n    //     },\r\n    //     grid: {\r\n    //         background: \'rgba(57,57,57,0.0)\',\r\n    //         drawBorder: false,\r\n    //         shadow: false,\r\n    //         gridLineColor: \'#ccc\',\r\n    //         gridLineWidth: 1\r\n    //     },\r\n    //     legend: {\r\n    //         show: false,\r\n    //         placement: \'outside\'\r\n    //     },\r\n    //     seriesDefaults: {\r\n    //         rendererOptions: {\r\n    //             smooth: true,\r\n    //             animation: {\r\n    //                 show: true\r\n    //             }\r\n    //         },\r\n    //         showMarker: true\r\n    //     },\r\n    //     series: [\r\n    //         {\r\n    //             fill: false,\r\n    //             label: \'2010\'\r\n    //         },\r\n    //         {\r\n    //             label: \'2011\'\r\n    //         }\r\n    //     ],\r\n    //     axesDefaults: {\r\n    //         rendererOptions: {\r\n    //             baselineWidth: 1,\r\n    //             baselineColor: \'#444444\',\r\n    //             drawBaseline: false\r\n    //         }\r\n    //     },\r\n    //     axes: {\r\n    //         xaxis: {\r\n    //             renderer: $.jqplot.DateAxisRenderer,\r\n    //             tickRenderer: $.jqplot.CanvasAxisTickRenderer,\r\n    //             tickOptions: {\r\n    //                 formatString: \"%b %e\",\r\n    //                 angle: -30,\r\n    //                 textColor: \'#666666\'\r\n    //             },\r\n    //             min: \"2014-01-01\",\r\n    //             max: \"2015-12-30\",\r\n    //             tickInterval: \"7 days\",\r\n    //             drawMajorGridlines: false\r\n    //         },\r\n    //         yaxis: {\r\n    //             pad: 0,\r\n    //             rendererOptions: {\r\n    //                 minorTicks: 1\r\n    //             },\r\n    //             tickOptions: {\r\n    //                 formatString: \"$%\'d\",\r\n    //                 showMark: false\r\n    //             }\r\n    //         }\r\n    //     }\r\n    // });\r\n \r\n});\r\n</script>\r\n\r\n\r\n',NULL,NULL,NULL,'2014-05-15 06:14:20','2014-05-15 06:14:20','overview',''),(1100,'yearly_report',522,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Yearly Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    params_date = select_date\r\n    select_date = Date.to_mongo(select_date)\r\n    type = \'0\'\r\n    type = params[:report][:type] if params and params[:report]\r\n\r\n    header_th = %w{ในเวลาราชการ ER นอกเวลาราชการ ทุกประเภท}\r\n   \r\n%>\r\n\r\n\r\n<%=form_for \'report\' do |f| %>\r\nSelect : <%= f.date_select :date, :default=>select_date ,:discard_day=>true ,:discard_month=>true,:start_year => Time.now.year-5,:end_year => Time.now.year, :order=>[:month,:year]%>\r\n<br/>\r\nCase : <%=f.select :type,  options_for_select([[\'Elective\',0],[\'Emergency\',1],[\'Extratime\',2],[\'All\',3]],type) %>\r\n<br/>\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n    ipds = 0 \r\n    opds = 0 \r\n    \r\n    total_patho = 0\r\n \r\n \r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-6-15\" if params[:report]\r\n    select_date = Date.to_mongo(select_date)\r\n    \r\n      \r\n      \r\n      \r\n    \r\n    start_date = Date.to_mongo((params[:report][\'date(1i)\'].to_i-3).to_s+\"-6-15\").beginning_of_year()\r\n    stop_date = select_date.end_of_year()\r\n    \r\n    \r\n    \r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n    other_status = {\'Cancelled\'=>0,\'Postpone\'=>0}\r\n    ipd_opd = {}\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n         # all pm colono of those appointments\r\n    all_pm_prescope = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}pre_scope\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_prescope = bmap all_pm_prescope, \'parent_id\'\r\n    \r\n    \r\n    colo_scope = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n    cs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n    for i in colo_scope\r\n        cs[i] = 1\r\n    end\r\n\r\n    gastro_scope = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n    gs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n       \r\n    for i in gastro_scope\r\n        gs[i] = 1\r\n    end     \r\n    \r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>cs}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>gs}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n \r\n    prescope = @models[:pre_scope].collection.find({:_id=>{\'$in\'=>all_pm_prescope.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'type_of_patient\'=>1 }}).to_a\r\n    m_prescope = bmap prescope, \'_id\'\r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n \r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    for app in all_app\r\n    \r\n        other_status[app[\'status\']] = 0 unless other_status[app[\'status\']]\r\n        other_status[app[\'status\']] += 1 \r\n        \r\n        \r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                prescope = m_all_pm_prescope[pm_app[\'_id\']]\r\n                \r\n                \r\n                p_colo = nil\r\n                p_gastro = nil\r\n                \r\n                r_colo = nil\r\n                r_gastro = nil\r\n                \r\n                \r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                        status = r_colo[0][\'status\']\r\n                        p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    if r_gastro\r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                 \r\n                patho_count = 0 \r\n                \r\n                \r\n                \r\n                # if r_colo and r_colo[0]\r\n                    \r\n                #     xls = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n                #     xms = \'colonoscopy_scope\'\r\n                #     xdata = r_colo[0]\r\n            \r\n                # xls.each{|lc|\r\n                \r\n                #     if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n             \r\n                #         xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                #         for li in xll\r\n                #             patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                   \r\n                #         end\r\n                    \r\n                #     end\r\n                # }\r\n                \r\n                # end\r\n                \r\n                \r\n                # if r_gastro and r_gastro[0]\r\n                    \r\n                #     xls = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n                #     xms = \'gastroscopy_scope\'\r\n                #     xdata = r_gastro[0]\r\n                \r\n                # xls.each{|lc| \r\n                #     if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n                #         xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                #         for li in xll\r\n                #             patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                #         end\r\n                    \r\n                #     end\r\n                # }\r\n                \r\n                # end\r\n                \r\n                \r\n                # total_patho += patho_count\r\n        \r\n                \r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n            \r\n                dates[date][\'no_specimen\'] = 0 unless dates[date][\'no_specimen\']\r\n                dates[date][\'no_specimen\'] += patho_count\r\n            \r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                \r\n                \r\n                \r\n                \r\n                if prescope and prescope = prescope[0]  and prescope and colo or gastro\r\n                    \r\n                if prescope and  prescope[\'module_id\'] and m_prescope[prescope[\'module_id\']]\r\n                    \r\n                    \r\n                    \r\n                r_prescope = m_prescope[prescope[\'module_id\']][0]    \r\n                    \r\n                dates[date][\'ipd_opd\'] = {\'IPD\'=>0,\'OPD\'=>0, \'\'=>0, nil=>0} unless dates[date][\'ipd_opd\']\r\n                dates[date][\'ipd_opd\'][r_prescope[\'type_of_patient\']]+=1\r\n                \r\n                end\r\n                \r\n                end\r\n              \r\n              \r\n              \r\n                \r\n                if p_colo\r\n                dates[date][\'p_colo\'] = {} unless dates[date][\'p_colo\']\r\n                for pi in p_colo.split(\"|\")\r\n                    dates[date][\'p_colo\'][pi] = 0 unless  dates[date][\'p_colo\'][pi]\r\n                    dates[date][\'p_colo\'][pi] += 1 \r\n                end\r\n                \r\n                end\r\n                \r\n                \r\n                \r\n                if p_gastro\r\n                \r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                for pi in p_gastro.split(\"|\")\r\n                dates[date][\'p_gastro\'][pi] = 0 unless  dates[date][\'p_gastro\'][pi]\r\n                dates[date][\'p_gastro\'][pi] += 1 \r\n                end\r\n                end\r\n                \r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n       \r\n        end\r\n    \r\n    end\r\n%>\r\n<%# dates.inspect %>\r\n<%\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<% \r\n\r\n    month_text = month_th[select_date.month-1]+select_date.strftime(\"-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    .date{\r\n        padding:5px;\r\n    }\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    \r\n    td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.small{\r\n        font-size:0.8em;\r\n    }\r\n    td.date{\r\n        padding:0px;\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n        td.date{\r\n        padding:0px;\r\n        \r\n        width:125px;\r\n        \r\n    }\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n    \r\n    tr.page-break{page-break-after:always;page-break-inside:avoid; page-break-after:auto}\r\n    .force-break{ display: block;page-break-before:always;}\r\n        \r\n    }\r\n    \r\n   .m3{\r\n       background-color:#cae3ff;\r\n          text-align:center;\r\n   }\r\n   .m2{\r\n       background-color:#d8ffec;\r\n         text-align:center;\r\n   }\r\n   .m1{\r\n       background-color:#f7ffc6;\r\n         text-align:center;\r\n   }\r\n   .m0{\r\n       background-color:#dfddfe;\r\n         text-align:center;\r\n   }\r\n   .percent{\r\n         text-align:right;\r\n   }\r\n   \r\n    \r\n   table { page-break-inside:auto }\r\n   tr    { page-break-inside:avoid; page-break-after:auto }\r\n    \r\n</style>\r\n<style type=\"text/css\">\r\n\r\n</style>\r\n\r\n\r\n\r\n<div style=\"width:720px\">\r\n<h3>ตารางแสดงจำนวนผู้ป่วย ห้องส่องกล้อง Surgical Endoscopy ประจำปี \r\n<%=stop_date.year%> <br/> เปรียบเทียบ\r\n    \r\n    <%= header_th[ type.to_i ] %>\r\n</h3>\r\n</div>\r\n\r\n<br/>\r\n\r\n\r\n\r\n<% ytime = 4%>\r\n<%\r\n    msum = {}\r\n    psum = {}\r\n    last = nil\r\n%>\r\n\r\n<table border=\"1\" class=\"content\">\r\n<tr>\r\n    <th  class=\"m0\">Month</th>\r\n    <% ytime.times do |y|\r\n        yy = (select_date.year+y-ytime+1)\r\n        if y!=0\r\n    %>\r\n    \r\n    <th colspan=\"5\" class=\"m<%=(y)%>\">\r\n    <%= yy %>    \r\n    </th>\r\n    \r\n    <% end %>\r\n    <% end %>\r\n    \r\n</tr>\r\n\r\n\r\n<tr>\r\n    <th  class=\"m0\">&nbsp;</th>\r\n    \r\n    <% ytime.times do |y|\r\n        yy = (select_date.year+y-ytime+1)\r\n        \r\n        if y != 0 \r\n    %>\r\n    \r\n    <th class=\"m<%=(y)%>\">Gastro</th>\r\n    \r\n    <th class=\"m<%=(y)%>\">Colono</th>\r\n    \r\n    <th class=\"m<%=(y)%>\">G+C</th>\r\n    \r\n    <th class=\"m<%=(y)%>\">รวม</th>\r\n    \r\n    <th class=\"m<%=(y)%>\">Growth</th>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    \r\n    \r\n</tr>\r\n\r\n\r\n\r\n    <% 12.times do |m| %>\r\n    <tr align=\"center\">\r\n    <th class=\"m0\"><%=month_th[m]%></th>\r\n      <% ytime.times do |y| \r\n        yy = (select_date.year+y-ytime+1)\r\n      \r\n      \r\n      \r\n      \r\n      \r\n      \r\n      \r\n      \r\n        d = \"%d\"%yy+\"-\"+\"%02d\"%(m+1)\r\n        dx = [0,0,0]\r\n        \r\n        case params[:report][:type]\r\n        \r\n        when \'0\'\r\n        dx = dates[d][\"Elective\"] if dates[d]\r\n        when \'1\'\r\n        dx = dates[d][\"Emergency\"] if dates[d]\r\n        when \'2\'\r\n        dx = dates[d][\"Extratime\"] if dates[d]\r\n        when \'3\'\r\n        \r\n        dx1 = dates[d][\"Elective\"] if dates[d]\r\n        dx2 = dates[d][\"Extratime\"] if dates[d]\r\n        dx3 = dates[d][\"Emergency\"] if dates[d]\r\n        dx1= [0,0,0] unless dx1\r\n        dx2= [0,0,0] unless dx2\r\n        dx3= [0,0,0] unless dx3\r\n        \r\n        \r\n        dx = [dx1[0]+dx2[0]+dx3[0],dx1[1]+dx2[1]+dx3[1],dx1[2]+dx2[2]+dx3[2]] \r\n        end\r\n        tx = 0\r\n        \r\n        \r\n        dx = [0,0,0] unless dx\r\n        \r\n        \r\n        tx = dx[0]+dx[1]+dx[2] if dx\r\n        \r\n        \r\n        msum[m] = 0 unless msum[m]\r\n        \r\n        \r\n        percent = \'-\'\r\n        if msum[m] > 0 \r\n            percent = \"\\\\#{\'%.2f\'%((tx.to_f-msum[m])/msum[m]*100)}%\"\r\n        end\r\n        \r\n    \r\n        \r\n        psum[yy]=[0,0,0] unless psum[yy]\r\n        \r\n        if dx\r\n        \r\n        psum[yy][0]+= dx[0] \r\n        psum[yy][1]+= dx[1]\r\n        psum[yy][2]+= dx[2]\r\n        \r\n        end\r\n         \r\n         \r\n         \r\n         \r\n         \r\n         \r\n      if y!=0     \r\n        \r\n      %>\r\n      <td class=\"\"><%=dx[1]%></td>\r\n      <td class=\"\"><%=dx[0]%></td>\r\n      <td class=\"\"><%=dx[2]%></td>\r\n      <td class=\"m<%=(y)%>\"><%=tx%></td>\r\n      <td class=\"m<%=(y)%> percent\"><%=percent%></td>\r\n      <%\r\n      \r\n     end\r\n      \r\n      msum[m] = tx\r\n        \r\n      end %>\r\n    </tr>\r\n    <% end %>\r\n    <%# psum.inspect %>\r\n  \r\n  \r\n  <tr>\r\n      <th  class=\"m0\">รวม</th>\r\n      \r\n      <% ytime.times do |y| \r\n        yy = (select_date.year+y-ytime+1)\r\n      \r\n        dx = []  \r\n        \r\n        \r\n        \r\n        \r\n        tx=  0\r\n        \r\n        \r\n        tx = psum[yy][0]+psum[yy][1]+psum[yy][2] \r\n        \r\n         percent = \'-\'\r\n        if last  \r\n            percent = \"\\\\#{\'%.2f\'%((tx.to_f-last)/last*100)} %\"\r\n        end\r\n        last = tx\r\n        if y!=0\r\n    %>\r\n    <td  class=\"m0\"><%=psum[yy][1]%><%#psum[yy].inspect%></td>\r\n    <td  class=\"m0\"><%=psum[yy][0]%></td>\r\n    <td  class=\"m0\"><%=psum[yy][2]%></td>\r\n    <td  class=\"m0\"><%=tx%></td>\r\n    <td  class=\"m0 percent\"><%=percent%></td>\r\n     \r\n    <% end %>\r\n    <% end %>\r\n  \r\n  </tr>\r\n  \r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2014-05-15 06:15:20','2014-05-15 06:15:20','yearly_report',''),(1101,'monthly_report',522,2,'<%= render :inline=>this.menu %>\r\n<h3>Monthly Report</h3>\r\n\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    select_date = Date.to_mongo(select_date)\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n<%= f.date_select :date, :default=>select_date ,:discard_day=>true%>\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n<% if request.post? \r\n\r\n   months=[]\r\n    app_model = models[:appointment]\r\n    \r\n    selected_doc = %w{colonoscopy gastroscopy}.collect{|i| \"\\\\#{@current_project.name}#\\\\#{i}\"}\r\n    \r\n    start_date = select_date.beginning_of_month()\r\n    stop_date = select_date.end_of_month()\r\n    \r\n    apps = app_model.collection.find({:status=>{\'$in\'=>[\'Completed\',\'Recovery\',\'Processing\']},:date=>{\'$gte\'=>start_date,\'$lte\'=>stop_date}},{:fields=>[:date,:status]}).to_a\r\n    app_ids = apps.collect{|i| i[\'_id\']}\r\n    appm_ids = []\r\n    mapps = {}\r\n    module_model.collection.find({:module_id=>{\'$in\'=>app_ids}},:fields=>[:patient_id,:module_id]).each do |i|\r\n    appm_ids << i[\'_id\']\r\n    mapps[i[\'module_id\']] = i\r\n    end\r\n    \r\n    parents = {}\r\n    c = {0=>[],1=>[]}\r\n   \r\n    list = module_model.collection.find({:parent_id=>{\'$in\'=>appm_ids},:module_name=>{\'$in\'=>selected_doc}},{:fields=>[:parent_id,:module_name,:module_id]}).each do |i|\r\n    p = i[\'parent_id\']\r\n    parents[p] = {:modules=>0} unless parents[p]\r\n  \r\n    idx = selected_doc.index(i[\'module_name\'])\r\n    parents[p][:modules] |= 2**idx\r\n    parents[p][:id]=i[\'module_id\']\r\n    c[idx] << i[\'module_id\']\r\n    \r\n    end\r\n    \r\n    status = {}\r\n    patho = {}\r\n    patho_detail = {}\r\n    # colono\r\n    \r\n    ls = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'].collect{|i| i.to_sym }\r\n    ms = \'colonoscopy_scope\'\r\n    \r\n    models[:colonoscopy].collection.find({:_id=>{\'$in\'=>c[0]}},{:fields=>[:status]+ls}).each do |i|\r\n        status[i[\'_id\']] = i[\'status\']\r\n        list = []\r\n        \r\n        for j in ls \r\n            list+=i[j.to_s] if i[j.to_s]\r\n        end\r\n        count = models[ms.to_sym].collection.find({:_id=>{\'$in\'=>list},:patho_number=>{\'$ne\'=>\'\'}}).count\r\n        \r\n        patho_detail[i[\'_id\']] = [] unless patho_detail[i[\'_id\']]\r\n        \r\n         patho_detail[i[\'_id\']] += models[ms.to_sym].collection.find({:_id=>{\'$in\'=>list},:patho_number=>{\'$ne\'=>\'\'}}).to_a\r\n        \r\n        %>\r\n        <%# models[ms.to_sym].collection.find({:_id=>{\'$in\'=>list}}).to_a.inspect %>\r\n        <%#count  %>\r\n        <%\r\n        patho[i[\'_id\']]=0 unless patho[i[\'_id\']]\r\n        patho[i[\'_id\']]+=count\r\n    end\r\n    \r\n    ls = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n    ms = \'gastroscopy_scope\'\r\n    \r\n    models[:gastroscopy].collection.find({:_id=>{\'$in\'=>c[1]}},{:fields=>[:status]+ls}).each do |i|\r\n        status[i[\'_id\']] = i[\'status\']\r\n         for j in ls \r\n            list+=i[j.to_s] if i[j.to_s]\r\n        end\r\n        \r\n          patho_detail[i[\'_id\']] = [] unless patho_detail[i[\'_id\']]\r\n        \r\n         patho_detail[i[\'_id\']] += models[ms.to_sym].collection.find({:_id=>{\'$in\'=>list},:patho_number=>{\'$ne\'=>\'\'}}).to_a\r\n       \r\n        \r\n        \r\n        count = models[ms.to_sym].collection.find({:_id=>{\'$in\'=>list},:patho_number=>{\'$ne\'=>\'\'}}).count\r\n        patho[i[\'_id\']]=0 unless patho[i[\'_id\']]\r\n        patho[i[\'_id\']]+=count\r\n        \r\n        \r\n    end\r\n \r\n    months = {\'Elective\'=>[],\'Extratime\'=>[],\'Emergency\'=>[]}\r\n    \r\n    list = apps.collect{|i|\r\n        p = parents[mapps[i[\'_id\']][\'_id\']] if mapps[i[\'_id\']]\r\n       \r\n        if p \r\n        s = status[p[:id]]\r\n        sp = patho[p[:id]]\r\n        modules = p[:modules]\r\n        mons = months[s]\r\n        if mons\r\n        m = i[\'date\'].day\r\n        mons[m] = {} unless mons[m]\r\n        mons[m][modules] = 0 unless mons[m][modules]\r\n        mons[m][modules] +=1\r\n        mons[m][0] = 0 unless mons[m][0] \r\n        mons[m][0]+=sp\r\n        end\r\n        end\r\n      \r\n  \r\n        i\r\n    }\r\n    list = months\r\n\r\n%>\r\n<%#list.inspect %>\r\n\r\n<%= patho.inspect %>\r\n<hr/>\r\n<%= patho_detail.inspect %>\r\n\r\n\r\n<%\r\n   m=[]\r\n   stop_date.day.times do |i|\r\n   m << i+1\r\n   end\r\n   labels = {1=>\'Colono\',2=>\'Gastro\',3=>\'Colono+Gastro\'}\r\n\r\n   \r\n   months.each_pair do |k,v| \r\n\r\n   v = v[1..-1]\r\n   if v\r\n   l = [1,3,2]\r\n   l.collect!{|i|\r\n     list = []\r\n     for x in v\r\n     if x and x[i]\r\n      list << x[i]\r\n      else\r\n      list << 0     \r\n     end\r\n         \r\n     end\r\n     \r\n    {:name=>labels[i],:data=>list }\r\n    \r\n   }\r\n   end\r\n   \r\n   \r\n%>\r\n\r\n<div id=\"chart<%=k%>\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n</div>\r\n<br/>\r\n\r\n            <script>\r\n                    $(\"#chart<%=k%>\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"<%= k %> Patients by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=l.to_json.html_safe%>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=m.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                \r\n\r\n            </script>\r\n\r\n\r\n<% end %>\r\n\r\n<%\r\nlist = []\r\n\r\nl = nil\r\n     \r\nmonths.each_pair do |k,v| \r\n\r\n   v = v[1..-1]\r\n   if v\r\n   l = [0]\r\n   l.collect!{|i|\r\n     \r\n     v.each_with_index do |x,index|\r\n     \r\n     list[index] = 0 unless list[index]\r\n     \r\n     if x and x[i]\r\n      list[index] += x[i]\r\n     end    \r\n     \r\n     end\r\n     \r\n    {:name=>labels[i],:data=>list }\r\n    \r\n   }\r\n   end\r\n   \r\n   end\r\n    \r\n    data = [{:name=>\'Patho Number\',:data=>list}]\r\n\r\n%>\r\n\r\n<%#data.inspect %>\r\n\r\n\r\n<div id=\"chart-patho\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n</div>\r\n<br/>\r\n\r\n            <script>\r\n                    $(\"#chart-patho\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Patho Number by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe%>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=m.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                \r\n\r\n            </script>\r\n\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2014-05-15 06:15:56','2014-05-15 06:15:56','monthly_report',''),(1102,'menu',522,4,'<h1>Report</h1>\r\n\r\n<%= link_to \'Yearly Report\',\'yearly_report\' ,:class=>\'btn btn-info\' %>\r\n<%= link_to \'Monthly Report\',\'print_monthly_report\' ,:class=>\'btn btn-info\'%>\r\n\r\n\r\n<hr/>',NULL,NULL,NULL,'2014-05-15 06:17:38','2014-05-15 06:17:38','menu',''),(1103,'print',481,3,'   \r\n    <html>\r\n    <head>\r\n    <style>\r\n   h1 {font-size:12px}\r\n	.CSSTableGenerator {\r\n		font-size: 9px;\r\n	margin:0px;padding:0px;\r\n	width:100%;\r\n	\r\n	border:1px solid #ccc;\r\n	\r\n	-moz-border-radius-bottomleft:0px;\r\n	-webkit-border-bottom-left-radius:0px;\r\n	border-bottom-left-radius:0px;\r\n	\r\n	-moz-border-radius-bottomright:0px;\r\n	-webkit-border-bottom-right-radius:0px;\r\n	border-bottom-right-radius:0px;\r\n	\r\n	-moz-border-radius-topright:0px;\r\n	-webkit-border-top-right-radius:0px;\r\n	border-top-right-radius:0px;\r\n	\r\n	-moz-border-radius-topleft:0px;\r\n	-webkit-border-top-left-radius:0px;\r\n	border-top-left-radius:0px;\r\n}.CSSTableGenerator table{\r\n    border-collapse: collapse;\r\n        border-spacing: 0;\r\n	width:100%;\r\n	height:100%;\r\n	margin:0px;padding:0px;\r\n}.CSSTableGenerator tr:last-child td:last-child {\r\n	-moz-border-radius-bottomright:0px;\r\n	-webkit-border-bottom-right-radius:0px;\r\n	border-bottom-right-radius:0px;\r\n}\r\n.CSSTableGenerator table tr:first-child td:first-child {\r\n	-moz-border-radius-topleft:0px;\r\n	-webkit-border-top-left-radius:0px;\r\n	border-top-left-radius:0px;\r\n}\r\n.CSSTableGenerator table tr:first-child td:last-child {\r\n	-moz-border-radius-topright:0px;\r\n	-webkit-border-top-right-radius:0px;\r\n	border-top-right-radius:0px;\r\n}.CSSTableGenerator tr:last-child td:first-child{\r\n	-moz-border-radius-bottomleft:0px;\r\n	-webkit-border-bottom-left-radius:0px;\r\n	border-bottom-left-radius:0px;\r\n}.CSSTableGenerator tr:hover td{\r\n	\r\n}\r\n.CSSTableGenerator tr:nth-child(odd){ background-color:#aad4ff; }\r\n.CSSTableGenerator tr:nth-child(even)    { background-color:#ffffff; }.CSSTableGenerator td{\r\n	vertical-align:middle;\r\n	\r\n	\r\n	border:1px solid #ccc;\r\n	border-width:0px 1px 1px 0px;\r\n	text-align:left;\r\n	padding:7px;\r\n	font-family:Arial;\r\n	font-weight:normal;\r\n	color:#000000;\r\n}.CSSTableGenerator tr:last-child td{\r\n	border-width:0px 1px 0px 0px;\r\n}.CSSTableGenerator tr td:last-child{\r\n	border-width:0px 0px 1px 0px;\r\n}.CSSTableGenerator tr:last-child td:last-child{\r\n	border-width:0px 0px 0px 0px;\r\n}\r\n.CSSTableGenerator tr:first-child td{\r\n		background:-o-linear-gradient(bottom, #005fbf 5%, #003f7f 100%);	background:-webkit-gradient( linear, left top, left bottom, color-stop(0.05, #005fbf), color-stop(1, #003f7f) );\r\n	background:-moz-linear-gradient( center top, #005fbf 5%, #003f7f 100% );\r\n	filter:progid:DXImageTransform.Microsoft.gradient(startColorstr=\"#005fbf\", endColorstr=\"#003f7f\");	background: -o-linear-gradient(top,#005fbf,003f7f);\r\n\r\n	background-color:#005fbf;\r\n	border:0px solid #ccc;\r\n	text-align:center;\r\n	border-width:0px 0px 1px 1px;\r\n    font-size: 9px;\r\n	font-family:Arial;\r\n	font-weight:bold;\r\n	color:#ffffff;\r\n}\r\n.CSSTableGenerator tr:first-child:hover td{\r\n	background:-o-linear-gradient(bottom, #005fbf 5%, #003f7f 100%);	background:-webkit-gradient( linear, left top, left bottom, color-stop(0.05, #005fbf), color-stop(1, #003f7f) );\r\n	background:-moz-linear-gradient( center top, #005fbf 5%, #003f7f 100% );\r\n	filter:progid:DXImageTransform.Microsoft.gradient(startColorstr=\"#005fbf\", endColorstr=\"#003f7f\");	background: -o-linear-gradient(top,#005fbf,003f7f);\r\n\r\n	background-color:#005fbf;\r\n}\r\n.CSSTableGenerator tr:first-child td:first-child{\r\n	border-width:0px 0px 1px 0px;\r\n}\r\n.CSSTableGenerator tr:first-child td:last-child{\r\n	border-width:0px 0px 1px 1px;\r\n}\r\n    </style>\r\n    </head>\r\n    <body class=\"ppp\">\r\n    <div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n     <%\r\n    \r\n            ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n            ehr_models = ehr.get_model\r\n            \r\n            patient_model = ehr_models[:patient]\r\n            patient_module_model = ehr_models[:patient_module]\r\n            \r\n            \r\n            emr_models = get_model\r\n            \r\n            ap = emr_models[:appointment].find(params[:id])\r\n            pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n            \r\n            patient = patient_model.find(pm.patient_id)\r\n            \r\n            pname = @current_project.name \r\n    %>\r\n    \r\n    \r\n    \r\n    \r\n    <%  \r\n        @document = ehr.get_document \'patient\'\r\n        @record = patient\r\n    %>\r\n    <h3>Patient info : <%=render_value \'patient_number\' %></h3>\r\n    <table width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" class=\"CSSTableGenerator\">\r\n    <tr> <th>Birth date</th><th>age</th><th>Gender</th><th>Weight </th><th>Height </th><th>Date of hospital admission</th><th>Date of ICU admission </th> <th>Time of ICU admission</th><th>Reimbursement</th><th>Diagnosis</th><th></th><th></th></tr>\r\n    <tr> <td><%=render_value \'birth_date\' %></td><td><%=render_value \'age\' %></td><td><%=render_value \'gender\' %></td><td><%=render_value \'weight\' %></td><td><%=render_value \'height\' %></td><td><%=render_value \'date_of_admission\' %></td><td><%=render_value \'date_of_icu_admission\' %></td> <td><%=render_value \'time_of_icu_admission\' %></td><td><%=render_value \'reimbursement\' %></td><td><%=render_value \'diagnosis\' %></td><td></td><td></td></tr>\r\n    </table>\r\n    <div id=\"289-F6868079453\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>Underlying disease</b> </div>\r\n       <table  width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" class=\"CSSTableGenerator\">\r\n      <tr><th>HT</th><th>DM</th><th>CAD</th><th>Cerebrovascular disease</th><th>\r\nMalignancy</th><th>CKD</th><th>ESRD</th><th>Baseline serum creainine by MDRD</th><th>Baseline serum Cr</th><th>Date of baseline serum Cr</th><th>ICU</th></tr>\r\n      <tr><td><%=render_value \'ht\' %></td><td><%=render_value \'dm\' %></td><td><%=render_value \'cad\' %></td><td><%=render_value \'cerebrovascular_disease\' %></td><td><%=render_value \'malignancy\' %></td><td><%=render_value \'ckd\' %></td><td><%=render_value \'esrd\' %></td><td><%=render_value \'baseline_serum_creainine_by_mdrd\' %></td><td><%=render_value \'baseline_serum_cr\' %></td><td><%=render_value \'date_of_baseline_serum_cr\' %></td><td><%=render_value \'icu\' %></td></tr>\r\n      </table>\r\n    <div id=\"289-F5662053258\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>APACHE II Score</b> </div>\r\n \r\n        <label>Glasgow coma score : <%=render_value \'glasgow_coma_score\' %></label>\r\n    <div id=\"289-F3558008139\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>Physiologic Variable</b> </div>\r\n    <table  width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" class=\"CSSTableGenerator\">\r\n    <tr><th>Temperature</th><th>Mean arterial pressure</th><th>Heart Rate</th><th>Respiratory rate</th><th>Oxygenation</th><th>Arterial pH</th><th>Serum sodium</th><th>Serum potassium</th><th>Serum creatinine</th><th>Hematocrit</th><th>White blood count</th></tr>\r\n    <tr><td><%=render_value \'temperature\' %></td><td><%=render_value \'mean_arterial\' %></td><td><%=render_value \'heart_rate\' %></td><td><%=render_value \'respiratory_rate\' %></td><td><%=render_value \'oxygenation\' %></td><td><%=render_value \'arterial_ph\' %></td><td><%=render_value \'serum_sodium\' %></td><td><%=render_value \'serum_potassium\' %></td><td><%=render_value \'serum_creatinine\' %></td><td><%=render_value \'hematocrit\' %></td><td><%=render_value \'white_blood_count\' %></td></tr>\r\n    \r\n    </table>\r\n    \r\n     <div id=\"289-F2164698709\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>Chronic Health Points </b> </div>\r\n        Chronic health points : <%=render_value \'chronic_health_points\' %>\r\n      \r\n        <H3>APACHE II :   <%=render_value \'apache_ii\' %></h3>\r\n     \r\n     \r\n    <hr/>\r\n    \r\n    \r\n    <h1>Case Record</h1>\r\n    <table width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" class=\"CSSTableGenerator\">\r\n  <tr>\r\n    <th>record_day </th>\r\n    <th>case_status </th>\r\n    <th>bun </th>\r\n    <th>creatinine </th>\r\n    <th>urine_output24hr </th>\r\n    <th>intake </th>\r\n    <th>output </th>\r\n    <th>net_balance </th>\r\n    <th>mechanical_ventilation </th>\r\n    <th>vasopressor </th>\r\n    <th>vasopressor_type </th>\r\n    <th>rate_of_vasopressor </th>\r\n    <th>dose_of_vasopressor </th>\r\n    <th>ml_of_vasopressor </th>\r\n    <th>patient_weight </th>\r\n    <th>cal_dose_vasopressor </th>\r\n    <th>rs </th>\r\n    <th>Platelet</th>\r\n    <th>cns </th>\r\n    <th>liver </th>\r\n    <th>renal </th>\r\n    <th>cvs </th>\r\n    <th>diuretic </th>\r\n    <th>lactate </th>\r\n    <th>sofa </th>\r\n    <th>if_rrt </th>\r\n    <th>indication </th>\r\n    <th>mode_of_rrt </th>\r\n    <th>type_of_vascular_access </th>\r\n    <th>site_of_vascular_access </th>\r\n    <th>internal_jugular_lr </th>\r\n    <th>bfr </th>\r\n    <th>dfr </th>\r\n    <th>dialyzer </th>\r\n    <th>anticoagulant_ihd </th>\r\n    <th>complication_ihd </th>\r\n    <th>type_of_vascular_access_sled </th>\r\n    <th>site_of_vascular_access_sled </th>\r\n    <th>internal_jugular_lr_sled </th>\r\n    <th>duration_sled </th>\r\n    <th>bfr_sled </th>\r\n    <th>dfr_sled </th>\r\n    <th>dialyzer_sled </th>\r\n    <th>anticoagulant_sled </th>\r\n    <th>complication_sled </th>\r\n    <th>type_of_vascular_access_crrt </th>\r\n    <th>site_of_vascular_access_crrt </th>\r\n    <th>internal_jugular_lr_crrt </th>\r\n    <th>crrt_bfr </th>\r\n    <th>crrt_ufr </th>\r\n    <th>rfr_crrt </th>\r\n    <th>machine_type </th>\r\n    <th>mode </th>\r\n    <th>anticoagulant_crrt </th>\r\n    <th>crrt_complication </th>\r\n    <th>type_of_catheter </th>\r\n    <th>type_solution </th>\r\n    <th>cycle </th>\r\n    <th>fill_volume </th>\r\n    <th>dwell_time </th>\r\n    <th>pd_complication</th>\r\n  </tr>\r\n    <%\r\n        name = \'case_record\'\r\n        \r\n        @document = @current_project.get_document name\r\n        module_name = \"\\\\#{pname}#\\\\#{name}\"\r\n        modules = patient_module_model.where(:parent_id=>pm.id,:module_name=>module_name).all\r\n        model = emr_models[name.to_sym]\r\n        \r\n        for i in modules\r\n        \r\n        @record = model.find(i.module_id)\r\n    \r\n    %>\r\n    \r\n  \r\n<tr>\r\n    <td><%=render_value \'record_day\' %></td>\r\n    <td><%=render_value \'case_status\' %></td>\r\n    <td><%=render_value \'bun\' %></td>\r\n    <td><%=render_value \'creatinine\' %></td>\r\n    <td><%=render_value \'urine_output24hr\' %></td>\r\n    <td><%=render_value \'intake\' %></td>\r\n    <td><%=render_value \'output\' %></td>\r\n    <td><%=render_value \'net_balance\' %></td>\r\n    <td><%=render_value \'mechanical_ventilation\' %></td>\r\n    <td><%=render_value \'vasopressor\' %></td>\r\n    <td><%=render_value \'vasopressor_type\' %></td>\r\n    <td><%=render_value \'rate_of_vasopressor\' %></td>\r\n    <td><%=render_value \'dose_of_vasopressor\' %></td>\r\n    <td><%=render_value \'ml_of_vasopressor\' %></td>\r\n    <td><%=render_value \'patient_weight\' %></td>\r\n    <td><%=render_value \'cal_dose_vasopressor\' %></td>\r\n    <td><%=render_value \'rs\' %></td>\r\n    <td><%=render_value \'coagulation\' %></td>\r\n    <td><%=render_value \'cns\' %></td>\r\n    <td><%=render_value \'liver\' %></td>\r\n    <td><%=render_value \'renal\' %></td>\r\n    <td><%=render_value \'cvs\' %></td>\r\n    <td><%=render_value \'diuretic\' %></td>\r\n    <td><%=render_value \'lactate\' %></td>\r\n    <td><%=render_value \'sofa\' %></td>\r\n    <td><%=render_value \'if_rrt\' %></td>\r\n    <td><%=render_value( \'indication\' )[0..15]%></td>\r\n    <td><%=render_value \'mode_of_rrt\' %></td>\r\n    <td><%=render_value \'type_of_vascular_access\' %></td>\r\n    <td><%=render_value \'site_of_vascular_access\' %></td>\r\n    <td><%=render_value \'internal_jugular_lr\' %></td>\r\n    <td><%=render_value \'bfr\' %></td>\r\n    <td><%=render_value \'dfr\' %></td>\r\n    <td><%=render_value \'dialyzer\' %></td>\r\n    <td><%=render_value \'anticoagulant_ihd\' %></td>\r\n    <td><%=render_value \'complication_ihd\' %></td>\r\n    <td><%=render_value \'type_of_vascular_access_sled\' %></td>\r\n    <td><%=render_value \'site_of_vascular_access_sled\' %></td>\r\n    <td><%=render_value \'internal_jugular_lr_sled\' %></td>\r\n    <td><%=render_value \'duration_sled\' %></td>\r\n    <td><%=render_value \'bfr_sled\' %></td>\r\n    <td><%=render_value \'dfr_sled\' %></td>\r\n    <td><%=render_value \'dialyzer_sled\' %></td>\r\n    <td><%=render_value \'anticoagulant_sled\' %></td>\r\n    <td><%=render_value \'complication_sled\' %></td>\r\n    <td><%=render_value \'type_of_vascular_access_crrt\' %></td>\r\n    <td><%=render_value \'site_of_vascular_access_crrt\' %></td>\r\n    <td><%=render_value \'internal_jugular_lr_crrt\' %></td>\r\n    <td><%=render_value \'crrt_bfr\' %></td>\r\n    <td><%=render_value \'crrt_ufr\' %></td>\r\n    <td><%=render_value \'rfr_crrt\' %></td>\r\n    <td><%=render_value \'machine_type\' %></td>\r\n    <td><%=render_value \'mode\' %></td>\r\n    <td><%=render_value \'anticoagulant_crrt\' %></td>\r\n    <td><%=render_value \'crrt_complication\' %></td>\r\n    <td><%=render_value \'type_of_catheter\' %></td>\r\n    <td><%=render_value \'type_solution\' %></td>\r\n    <td><%=render_value \'cycle\' %></td>\r\n    <td><%=render_value \'fill_volume\' %></td>\r\n    <td><%=render_value \'dwell_time\' %></td>\r\n    <td><%=render_value \'pd_complication\' %></td>\r\n  </tr>\r\n\r\n    \r\n    <% end %>\r\n    </table>\r\n    <h1>AKI</h1>\r\n    \r\n    <%\r\n        name = \'aki\'\r\n        \r\n        @document = @current_project.get_document name\r\n        module_name = \"\\\\#{pname}#\\\\#{name}\"\r\n        modules = patient_module_model.where(:parent_id=>pm.id,:module_name=>module_name).all\r\n        model = emr_models[name.to_sym]\r\n        \r\n        for i in modules\r\n        \r\n        @record = model.find(i.module_id)\r\n    \r\n    %>\r\n    <table width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" class=\"CSSTableGenerator\">\r\n    <tr><th>max_staging</th><th>cause_of_aki</th>\r\n    </tr>\r\n    <tr><td><%=render_value \'max_staging\' %></td><td><%=render_value \'cause_of_aki\' %></td>\r\n    </tr>\r\n    \r\n    </table>\r\n  \r\n    <hr/>\r\n    <% end %>\r\n    \r\n    \r\n    <h1>Outcome</h1>\r\n    \r\n    <%\r\n        name = \'summary_form\'\r\n        \r\n        @document = @current_project.get_document name\r\n        module_name = \"\\\\#{pname}#\\\\#{name}\"\r\n        modules = patient_module_model.where(:parent_id=>pm.id,:module_name=>module_name).all\r\n        model = emr_models[name.to_sym]\r\n        \r\n        for i in modules\r\n        \r\n        @record = model.find(i.module_id)\r\n        if @record\r\n    %>\r\n   \r\n    <table width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" class=\"CSSTableGenerator\">\r\n  <tr>\r\n    <th>icu_discharge_status </th>\r\n    <th>icu_length_of_stay </th>\r\n    <th>hospital_discharge_status </th>\r\n    <th>hospital_length_of_stay </th>\r\n    <th>rrt_day </th>\r\n    <th>total_ventilator_day </th>\r\n    <th>death_date </th>\r\n    <th>date_of_icu_discharge </th>\r\n    <th>date_of_hospital_discharge </th>\r\n    <th>aki </th>\r\n    <th>los_in_icu </th>\r\n    <th>los_in_hospital </th>\r\n    <th>stop_rrt_date</th>\r\n  </tr>\r\n  <tr>\r\n    <td><%=render_value \'icu_discharge_status\' %></td>\r\n    <td><%=render_value \'icu_length_of_stay\' %></td>\r\n    <td><%=render_value \'hospital_discharge_status\' %></td>\r\n    <td><%=render_value \'hospital_length_of_stay\' %></td>\r\n    <td><%=render_value \'rrt_day\' %></td>\r\n    <td><%=render_value \'total_ventilator_day\' %></td>\r\n    <td><%=render_value \'death_date\' %></td>\r\n    <td><%=render_value \'date_of_icu_discharge\' %></td>\r\n    <td><%=render_value \'date_of_hospital_discharge\' %></td>\r\n    <td><%=render_value \'aki\' %></td>\r\n    <td><%=render_value \'los_in_icu\' %></td>\r\n    <td><%=render_value \'los_in_hospital\' %></td>\r\n    <td><%=render_value \'stop_rrt_date\' %></td>\r\n  </tr>\r\n</table>\r\n\r\n    <hr/>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    \r\n   \r\n      <div class=\"clear\"> </div>\r\n    </div>\r\n    </body>\r\n    </html>\r\n',NULL,NULL,NULL,'2014-05-23 03:45:34','2014-05-23 03:45:34','print',''),(1104,'document_name',523,1,'\'dialyzer\'',NULL,NULL,NULL,'2014-05-28 13:30:56','2014-05-28 13:30:56',NULL,NULL),(1105,'patient_record',407,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records hi\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \" Edit \", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\",:class=>\"btn btn-mini\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_role_by_id locker.session\r\n   %>\r\n\r\n\r\n<%\r\n    text = \'22323\'\r\n    \r\n    \r\n   text = \'\'\r\n   user_name = user.login\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + \"\\\\#{user.login}\"\r\n    \r\n  \r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\