n<div id=\"urine_output24hr\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:160px;\">\r\n<span class=\"\"><label>Urine output/24hr : </label></span>	\r\n<v><%=render_value \'urine_output24hr\'%></v>\r\n</div>\r\n<% end%>\r\n<div class=\"clear\"></div>\r\n	\r\n\r\n<% if record[\'intake\']!=nil %>\r\n<div id=\"intake\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:160px;\">\r\n<span class=\"\"><label>Intake : </label></span>	\r\n<v><%=render_value \'intake\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<% if record[\'output\']!=nil %>\r\n<div id=\"output\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:160px;\">\r\n<span class=\"\"><label>Output : </label></span>	\r\n<v><%=render_value \'output\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<% if record[\'net_balance\']!=nil %>\r\n<div id=\"net_balance\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:160px;\">\r\n<span class=\"\"><label>Net balance : </label></span>	\r\n<v><%=render_value \'net_balance\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<% if record[\'urine_output_cal\']!=nil %>\r\n<div id=\"urine_output_cal\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:160px;\">\r\n<span class=\"\"><label>Urine output (ml/kg/hr.) : </label></span>	\r\n<v><%=render_value \'urine_output_cal\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n	\r\n\r\n\r\n	\r\n\r\n<% if record[\'mechanical_ventilation\']!=\"\" %>\r\n<div id=\"mechanical_ventilation\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n<span class=\"\"><label>Mechanical ventilation : </label></span>	\r\n<v><%=render_value \'mechanical_ventilation\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'vasopressor\']!=\"\" %>\r\n<div id=\"vasopressor\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:130px;\">\r\n<span class=\"\"><label>Vasopressor : </label></span>	\r\n<v><%=render_value \'vasopressor\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n<% if record[\'vasopressor_type\']!=\"\" %>\r\n<div id=\"vasopressor_type\" class=\" vasopressor_type portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:520px;\">\r\n<span class=\"\"><label>Vasopressor type : </label></span>	\r\n<v><%=render_value \'vasopressor_type\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<div class=\"clear\"></div>\r\n	\r\n\r\n	\r\n<% if record[\'diuretic\']!=\"\" %>\r\n\r\n<div id=\"diuretic\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n<span class=\"\"><label>Diuretic : </label></span>	\r\n<v><%=render_value \'diuretic\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'lactate\']!=nil %>\r\n<div id=\"lactate\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n<span class=\"\"><label>Lactate : </label></span>	\r\n<v><%=render_value \'lactate\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'sofa\']!=nil %>\r\n<div id=\"sofa\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n<span class=\"\"><label>SOFA : </label></span>	\r\n<v><%=render_value \'sofa\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n	\r\n\r\n<% if record[\'if_rrt\']!=\"\" %>\r\n<div id=\"if_rrt\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n<span class=\"\"><label>IF RRT : </label></span>	\r\n<v><%=render_value \'if_rrt\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'indication\']!=\"\" %>\r\n	<div id=\"283-F5560483698\" class=\" rrt\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>RRT</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n<div id=\"indication\" class=\" rrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;\">\r\n<span class=\"\"><label>Indication : </label></span>	\r\n<v><%=render_value \'indication\'%></v></div>\r\n<% end%>\r\n\r\n	\r\n<% if record[\'mode_of_rrt\']!=\"\" %>\r\n<div id=\"mode_of_rrt\" class=\" rrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:220px;\">\r\n<span class=\"\"><label>Mode of RRT : </label></span>	\r\n<v><%=render_value \'mode_of_rrt\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'type_of_vascular_access\']!=\"\" %>\r\n	<div id=\"283-F7333889227\" class=\" ihd\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>IHD</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n<div id=\"type_of_vascular_access\" class=\" ihd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:800px;\">\r\n<span class=\"\"><label>Type of vascular access : </label></span>	\r\n<v><%=render_value \'type_of_vascular_access\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n<div class=\"clear\"></div>\r\n<% if record[\'site_of_vascular_access\']!=\"\" %>\r\n<div id=\"site_of_vascular_access\" class=\" ihd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:350px;\">\r\n<span class=\"\"><label>Site of vascular access : </label></span>	\r\n<v><%=render_value \'site_of_vascular_access\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'internal_jugular_lr\']!=\"\" %>\r\n<div id=\"internal_jugular_lr\" class=\" ihd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:260px;\">\r\n<span class=\"\"><label>Left or right : </label></span>	\r\n<v><%=render_value \'internal_jugular_lr\'%></v></div>\r\n<% end%>\r\n\r\n	\r\n<div class=\"clear\"></div>\r\n<% if record[\'bfr\']!=nil %>\r\n<div id=\"bfr\" class=\" ihd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:130px;\">\r\n<span class=\"\"><label>BFR (ml/min) : </label></span>	\r\n<v><%=render_value \'bfr\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'dfr\']!=nil %>\r\n<div id=\"dfr\" class=\" ihd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n<span class=\"\"><label>DFR (ml/min) : </label></span>	\r\n<v><%=render_value \'dfr\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n\r\n\r\n\r\n\r\n	\r\n\r\n<% if record[\'dialyzer\']!=\"\" %>\r\n<div id=\"dialyzer\" class=\" ihd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:180px;\">\r\n<span class=\"\"><label>Dialyzer : </label></span>	\r\n<v><%=render_value \'dialyzer\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'anticoagulant_ihd\']!=\"\" %>\r\n<div id=\"anticoagulant_ihd\" class=\" ihd portlet \" style=\"width:420px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n<span class=\"\"><label>Anticoagulant : </label></span>	\r\n\r\n<v><%=render_value \'anticoagulant_ihd\'%></v>\r\n\r\n\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'complication_ihd\']!=\"\" %>\r\n<div id=\"complication_ihd\" class=\" ihd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;\">\r\n<span class=\"\"><label>Complication  : </label></span>	\r\n<v><%=render_value \'complication_ihd\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'type_of_vascular_access_crrt\']!=\"\" %>\r\n	<div id=\"283-F5652059583\" class=\" crrt\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>CRRT</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n<div id=\"type_of_vascular_access_crrt\" class=\" crrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;\">\r\n<span class=\"\"><label>Type of vascular access : </label></span>	\r\n<v><%=render_value \'type_of_vascular_access_crrt\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<div class=\"clear\"></div>	\r\n\r\n<% if record[\'site_of_vascular_access_crrt\']!=\"\" %>\r\n<div id=\"site_of_vascular_access_crrt\" class=\" crrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:550px;\">\r\n<span class=\"\"><label>Site of vascular access crrt : </label></span>	\r\n<v><%=render_value \'site_of_vascular_access_crrt\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'internal_jugular_lr_crrt\']!=\"\" %>\r\n<div id=\"internal_jugular_lr_crrt\" class=\" crrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:260px;\">\r\n<span class=\"\"><label>Left or Right : </label></span>	\r\n<v><%=render_value \'internal_jugular_lr_crrt\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	<div class=\"clear\"></div>	\r\n\r\n<% if record[\'crrt_bfr\']!=nil %>\r\n<div id=\"crrt_bfr\" class=\" crrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:140px;\">\r\n<span class=\"\"><label>BFR (ml/min) : </label></span>	\r\n<v><%=render_value \'crrt_bfr\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'crrt_ufr\']!=nil %>\r\n<div id=\"crrt_ufr\" class=\" crrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n<span class=\"\">\r\n<label>UFR (ml/h) : </label></span>	\r\n<v><%=render_value \'crrt_ufr\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n<% if record[\'rfr_crrt\']!=nil %>\r\n<div id=\"rfr_crrt\" class=\" ihd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n<span class=\"\"><label>RFR (ml/h) : </label></span>	\r\n<v><%=render_value \'rfr_crrt\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n<% if record[\'machine_type\']!=\"\" %>\r\n<div id=\"machine_type\" class=\" crrt portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n<span class=\"\"><label>Machine type : </label></span>	\r\n<v><%=render_value \'machine_type\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'mode\']!=\"\" %>\r\n<div id=\"mode\" class=\" crrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n<span class=\"\"><label>Mode : </label></span>	\r\n\r\n<v><%=render_value \'mode\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n\r\n	<div class=\"clear\"></div>\r\n\r\n<% if record[\'anticoagulant_crrt\']!=\"\" %>\r\n<div id=\"anticoagulant_crrt\" class=\" crrt portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n<span class=\"\"><label>Anticoagulant : </label></span>	\r\n<v><%=render_value \'anticoagulant_crrt\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	<div class=\"clear\"></div>\r\n\r\n<% if record[\'crrt_complication\']!=\"\" %>\r\n<div id=\"crrt_complication\" class=\" crrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;\">\r\n<span class=\"\"><label>Complication : </label></span>	\r\n<v><%=render_value \'crrt_complication\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'type_of_catheter\']!=\"\" %>\r\n	<div id=\"283-F3282840165\" class=\" pd\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>PD</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n<div id=\"type_of_catheter\" class=\" pd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;\">\r\n<span class=\"\"><label>type of catheter : </label></span>	\r\n<v><%=render_value \'type_of_catheter\'%></v>\r\n</div>\r\n<% end%>\r\n<div class=\"clear\"></div>	\r\n	\r\n\r\n<% if record[\'type_solution\']!=\"\" %>\r\n<div id=\"type_solution\" class=\" pd portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n<span class=\"\"><label>Type solution : </label></span>	\r\n<v><%=render_value \'type_solution\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n\r\n\r\n	\r\n\r\n<% if record[\'cycle\']!=nil %>\r\n<div id=\"cycle\" class=\" pd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n<span class=\"\"><label>Cycle : </label></span>	\r\n<v><%=render_value \'cycle\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'fill_volume\']!=nil %>\r\n<div id=\"fill_volume\" class=\" pd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n<span class=\"\"><label>Fill volume : </label></span>	\r\n<v><%=render_value \'fill_volume\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'dwell_time\']!=nil %>\r\n<div id=\"dwell_time\" class=\" pd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n<span class=\"\"><label>Dwell time : </label></span>	\r\n<v><%=render_value \'dwell_time\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n\r\n\r\n<div class=\"clear\"></div>	\r\n	\r\n\r\n<% if record[\'pd_complication\']!=\"\" %>\r\n<div id=\"pd_complication\" class=\" pd portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;\">\r\n<span class=\"\"><label>Complication : </label></span>	\r\n<v><%=render_value \'pd_complication\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2014-06-03 04:06:09','2014-06-03 04:06:09','print_bk',''),(1109,'print',464,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n     hn = get_setting(\'hn\')\r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    med_id = pm.module_id\r\n    record = models[:case_record].find(med_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm_core/banner.png\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3>Outcome Report</h3>\r\n<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n\r\n <div style=\"padding:5px;width:720px; margin-left:auto; margin-right:auto\" >\r\n\r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n<p style=\"width:900px; margin-left:auto; margin-right:auto; font-weight:bold\">Hospital No :&nbsp;<v><%=patient.patient_number %> / <%= hn %></v> </p>\r\n<hr /><br />\r\n</div>\r\n<script>\r\n// url = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\n// url += \'&id=<%=@patient_module.patient_id%>\'\r\n//  $.ajax({\r\n//  url: url,\r\n// success: function(data){\r\n//  $(\'#patient\').html(data);  \r\n//  }\r\n// });\r\n</script>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div class=\"hideprint\">\r\n<%= link_to \'Back\', url(\'index\') %>\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2014-06-03 04:11:22','2014-06-03 04:11:22','print',''),(1111,'print',480,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    ztest = false\r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n    \r\n    pid = @module_model.find(params[:id])[:patient_id].to_s # patient_id\r\n    result = {}\r\n    models = get_model\r\n    m_case_record = models[:case_record]\r\n    pm_case_record = @module_model.where(:patient_id=>pid, :module_name=>\"\\\\#{@current_project.name}#case_record\").collect do |i|\r\n        mid = i.module_id\r\n        x = m_case_record.find(i.module_id)\r\n        x[:urine_output_cal]\r\n        if x[:urine_output_cal] != \"NaN\"\r\n            x[:urine_output_cal].to_f\r\n        end\r\n    end\r\n    \r\n    result[:field] = \'urine_output_cal\'\r\n    result[:pm_id] = params[:id]\r\n    result[:pid] = pid\r\n    result[:case_record] = pm_case_record.compact.sort\r\n    result[:min_urine] = result[:case_record][0]\r\n%>\r\n<%\r\n    # id of operative note\r\n     hn = get_setting(\'hn\')\r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    med_id = pm.module_id\r\n    record = models[:case_record].find(med_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncapti