27','patient_record',''),(1121,'config',502,1,'[\r\n{:name=>\'Operations\',:open=>true,:actions=>[\r\n{:name=>\'Pre-Scope\',:service=>\'pre_scope\',:link=>\'../pre_scope/index\',:remote=>false},\r\n{:name=>\'Intra-scope\',:service=>\'intra_scope\',:link=>\'../intra_scope/index\',:remote=>false},\r\n{:name=>\'Gastroscopy\',:service=>\'gastro\',:link=>\'../Gastro/index\',:remote=>false},\r\n{:name=>\'PushEnterosocpy\',:service=>\'push_enteroscopy\',:link=>\'../PushEnterosocpy/index\',:remote=>false},\r\n{:name=>\'DBE\',:service=>\'dbe\',:link=>\'../Dbe/index\',:remote=>false},\r\n{:name=>\'Colonoscopy\',:service=>\'colono\',:link=>\'../Colono/index\',:remote=>false},\r\n{:name=>\'Sigmoid\',:service=>\'sigmoid\',:link=>\'../Sigmoid/index\',:remote=>false},\r\n{:name=>\'ERCP\',:service=>\'ercp\',:link=>\'../Ercp/index\',:remote=>false},\r\n{:name=>\'EUS\',:service=>\'eus\',:link=>\'../Eus/index\',:remote=>false},\r\n{:name=>\'PercutaneousD\',:service=>\'percutaneous_drainage\',:link=>\'../PercutaneousDrainage/index\',:remote=>false},\r\n{:name=>\'LiverBiopsy\',:service=>\'liver_biopsy\',:link=>\'../LiverBiopsy/index\',:remote=>false},\r\n{:name=>\'Post-Scope\',:service=>\'post_scope\',:link=>\'../post_scope/index\',:remote=>false},\r\n{:name=>\'Liver Ultrasound / Fibroscan\',:service=>\'liver_ultrasound_and_fibroscan\',:link=>\'../LiverUltrasoundAndFibroscan/index\',:remote=>false}\r\n\r\n]}\r\n]\r\n',NULL,NULL,NULL,'2014-06-04 13:47:28','2015-02-15 03:31:51','config',''),(1125,'display',495,3,'\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n\r\n  models = get_model\r\n  model = models[this.table_name.to_sym]\r\n#   model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n\r\n\r\n<table width=\"550\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n  <td width=\"148\" valign=\"top\"><strong>Type of sedation</strong></td>\r\n  <td width=\"365\" valign=\"top\">\r\n  <v></v></td></tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Type of Drug</strong></td>\r\n  <td valign=\"top\"><% if record[\'pethidine\']!=\'false\' %><v>Pethidine <%=render_value \'pethidine_mg\'%>mg</v><% end%>\r\n    <% if record[\'dormicum\']!=\'false\' %><v>, Dormicum <%=render_value \'dormicum_mg\' %>mg</v><% end%>\r\n   <% if record[\'propofol\']!=\'false\' %> <v>, Propofol <%=render_value \'propofol_mg\' %>mg</v><% end%>\r\n    <% if record[\'sedation_none\']==\'true\' %> <v>None</v><% end%>\r\n    <% if record[\'xylocaine_spray\']==\'true\' %> <v>, 10% xylocaine spray</v><% end%>\r\n    </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Endoscopic findings</strong></td>\r\n  <td valign=\"top\"><v></v></td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Oral route\r\n</strong></td>\r\n  <td valign=\"top\"> \r\n  <% if record[\'small_bowel\']!=nil %>Number of insertion :<v><%=render_value \'small_bowel\' %></v> times<% end%>\r\n  <% if record[\'depth_of_insertion\']!=nil %>Depth of insertion :<v><%=render_value \'depth_of_insertion\' %></v> cm.<% end%>\r\n  <% if record[\'time_use\']!=nil %>Time use :<v><%=render_value \'time_use\' %></v> min.<% end%>\r\n  <% if record[\'duodenum\']!=\'\' %><v><%=render_value \'duodenum\' %></v><% end%> <% if record[\'duodenum_abnormal\']!=\'\' %>:<v><%=render_value \'duodenum_abnormal\' %></v><% end%>\r\n  <% if record[\'jejunum\']!=\'\' %><v><%=render_value \'jejunum\' %></v><% end%> <% if record[\'jejunum_abnormal\']!=\'\' %>:<v><%=render_value \'jejunum_abnormal\' %></v><% end%>\r\n  <% if record[\'ileum\']!=\'\' %><v><%=render_value \'ileum\' %></v><% end%> <% if record[\'ileum_abnormal\']!=\'\' %>:<v><%=render_value \'ileum_abnormal\' %></v><% end%>\r\n      \r\n  </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Anus route</strong></td>\r\n  <td valign=\"top\">\r\n  <% if record[\'small_bowel_a\']!=nil %>Number of insertion :<v><%=render_value \'small_bowel_a\' %></v> times<% end%>\r\n  <% if record[\'depth_of_insertion_a\']!=nil %>Depth of insertion :<v><%=render_value \'depth_of_insertion_a\' %></v> cm.<% end%>\r\n  <% if record[\'time_use_a\']!=nil %>Time use :<v><%=render_value \'time_use_a\' %></v> min.<% end%>\r\n  <% if record[\'duodenum_a\']!=\'\' %><v><%=render_value \'duodenum_a\' %></v><% end%> <% if record[\'duodenum_abnormal_a\']!=\'\' %>:<v><%=render_value \'duodenum_abnormal_a\' %></v><% end%>\r\n  <% if record[\'jejunum_a\']!=\'\' %><v><%=render_value \'jejunum_a\' %></v><% end%> <% if record[\'jejunum_abnormal_a\']!=\'\' %>:<v><%=render_value \'jejunum_abnormal_a\' %></v><% end%>\r\n  <% if record[\'ileum_a\']!=\'\' %><v><%=render_value \'ileum_a\' %></v><% end%> <% if record[\'ileum_abnormal_a\']!=\'\' %>:<v><%=render_value \'ileum_abnormal_a\' %></v><% end%>\r\n      \r\n\r\n  </td>\r\n</tr>\r\n\r\n\r\n\r\n<tr>\r\n  <td height=\"81\" valign=\"top\"><strong>Intervention</strong></td>\r\n  <td valign=\"top\"><v><%=render_value \'interv\'%> <%=render_value \'interv_success\'%>\r\n<br />\r\n<%\r\ncmd = <<VALUES\r\n0|Biopsy for repaid	 urease test\r\n1|Biopsy for histopathology\r\n2|Hemostatic therapy\r\n3|EVL\r\n4|Glue injection\r\n5|Dilation with\r\n6|Polypectomy with\r\n7|PEGJ placement\r\n8|PEGJ tube change\r\nVALUES\r\n\r\nconditions = {\'0\'=>[:biopsy_for_rapid],\r\n\'2\'=>[:hemostatic_therapy,\'Concentration:\',:hemo_concentration,\'Volume:\',:hemo_volume,\'ml.\',:hemoclip],\r\n\'5\'=>[:savarygillard_ditator,\'Size:\',:savarygillard_size,\'-\',:savarygillard_max_fr,\'Fr.\',:maloneyhurst_dilator,\'Size:\',:maloneyhurst_size,\'-\',:maloneyhurst_max_fr,\'Fr.\',:pneumatic_balloon_dilator,\'Pressure:\',:pneumatic_pressure,\'p.s.i.\',:pneumatic_max,\'min.\'],\r\n\'6\'=>[:polypectomy_with],\r\n\'7\'=>[:peg_brand,\'Size:\',:peg_size,\'Fr.\',\'Skin fixation at\',:peg_skin_fixation_at,\'cm.\'],\r\n\'8\'=>[:peg_tube_brand,\'Size:\',:peg_tube_size,\'Fr.\',\'Skin fixation at\',:peg_tube_skin_fixation_at,\'cm.\']}\r\n\r\nmap = {}\r\ncmd.lines.each do |i|\r\nt = i.split(\'|\')\r\nmap[t[0]] = t[1]\r\nend\r\n\r\n %>\r\n  \r\n  <% for i in record.interv_type.split(\'|\') \r\n     if title = map[i]\r\n  %>\r\n  <%= title %>\r\n  <% if list = conditions[i] \r\n    for j in list\r\n    j = render_value j.to_s if j.is_a? Symbol\r\n  %>\r\n  <%= j %>\r\n  <% end %>\r\n  <% end %>\r\n  <% end %>\r\n  <% end %>\r\n \r\n \r\n  <% if record[\'intervertion_note\']!=\"\" %>\r\n   Intervention Note :<%=render_value \'intervertion_note\'%> \r\n  <% end %>\r\n  </td>\r\n</tr>\r\n<tr>\r\n  <td height=\"83\" valign=\"top\"><strong>Comment</strong></td>\r\n  <td valign=\"top\">  \r\n  <% if record[\'bleeding_treatment\']==\"true\" %>bleeding treatment<% end %>\r\n  <% if record[\'bleeding_treatment_type\']!=\"\" %>type :<v><%=render_value \'bleeding_treatment_type\'%></v><% end %>\r\n  <% if record[\'concentration\']!=nil %>concentration :<v><%=render_value \'concentration\'%></v><% end %>\r\n  <% if record[\'volume\']!=nil %>volume :<v><%=render_value \'volume\'%></v><% end %>\r\n  <% if record[\'numberclip\']!=nil %>Hemoclip :<v><%=render_value \'numberclip\'%></v> clips<% end %>\r\n  <% if record[\'perforation\']!=\"\" %><v><%=render_value \'perforation\'%></v><% end %>\r\n  <% if record[\'desaturation_sat\']!=nil %>Lowerst O2 sat :<v><%=render_value \'desaturation_sat\'%>%</v><% end %>\r\n  <% if record[\'recommendation_note\']!=\"\" %> Complication  :<v><%=render_value \'recommendation_note\'%></v><% end %></td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Complications</strong></td>\r\n  <td valign=\"top\"><v><%=render_value \'complications\'%></v></td>\r\n</tr>\r\n<tr>\r\n  <td height=\"88\" valign=\"top\"><strong>Diagnosis</strong></td>\r\n  <td valign=\"top\"><%=render_value \'final_diagnosis\'%>\r\n      \r\n      <%=render_value \'final_diagnosis_note\'%>\r\n      \r\n      \r\n  </td>\r\n</tr>\r\n</table>',NULL,NULL,NULL,'2014-06-04 16:08:54','2014-06-04 16:08:54','display',''),(1129,'print_appointment',146,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n\r\n appointments = appointments.collect{|i| i if records[i.id] }.compact\r\n\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id}).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n p = patients[i.patient_id]\r\n provider = providers[ap.provider.to_s]\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p and p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year} ปี \\\\#{month} เดือน \\\\#{day} วัน\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif ap.status!=\'Postpone\' and ap.status!=\'Cancelled\'\r\n    {\'id\'=>ap.id,\r\n    \'status\'=>ap.status,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'remark\'=>p.remark,\r\n    \'procedure\'=>pro[ap.procedure],\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider.name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p }<br/>\\\\#{p.last_name if p }\".html_safe ,\r\n    \'start\'=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'age\'=>age,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\n}.compact\r\n\r\nlist = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"te