 }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <h3> <strong>Colonoscopy Diagnosis Report<br />\r\nKing Chulalongkorn Memorial Hospital<br />\r\nChulalongkorn University Bangkok Thailand\r\n  </strong></h3>\r\n</center>\r\n<div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'/esm/cusys/med/GI.jpg\' width=\"300\" style=\"position:absolute; top:5px\" /></div>\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td width=\"50%\"> \r\n<table>\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n      <v><%=patient.hn%></v> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> ชื่อ-สกุล : </strong>\r\n      <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v>\r\n    \r\n    <br /><strong>Date : </strong>\r\n    <br /><strong>Endoscopist : </strong><v><%=render_value \'endoscopist\'%></v>\r\n    <br /><strong>Nurse : </strong><v><%=render_value \'nurse\'%></v>\r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <strong>เพศ : </strong><%=patient.gender%> &nbsp; <strong>อายุ :&nbsp;</strong><v><%= year%> Y <%=month%> M <%= day%> D</v>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n &nbsp;&nbsp;&nbsp;<strong>Indication : </strong><v><%=render_value \'clinical_indication\'%></v>\r\n	<hr style=\"margin-top: 5px;\"/>\r\n	<hr />\r\n    \r\n    <%\r\n        atts = models[:attachment].find(record.image_diagnosis)\r\n    %>\r\n\r\n    <div style=\"float:right;  width: 280px; padding: 5px; text-align:center\">\r\n    <% for i in atts %>\r\n    <img src=\"<%=i.path%>\" width=\"270\" style=\"margin:5px\"/><br /><%=i.title%><br />\r\n    <% end %>\r\n    </div>\r\n<div style=\"float:left\">\r\n\r\n\r\n<table width=\"550\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr><td valign=\"top\"><strong>Consent</strong></td><td>The procedure of the examination, including possible complications were clearly and discussed with the patient and family, then a consent form was signed by the patient and/or family</td></tr>\r\n<tr><td valign=\"top\"><strong>Procedure</strong></td>\r\n  <td>The patient\'s blood pressure, pulse and oxygen saturetion were montiored ontinusly throghout the procedure. the scope was passed under direct vision through the anus and advanced to the colon. The endoscopy was accomplished without difficulty. The findings were described below. The patient tolerated the procedure well.</td></tr>\r\n</table>\r\n<div class=\"clear\"></div>\r\n\r\n<%= render :inline=>this.display %>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n<strong>Reported by :</strong>&nbsp;<%= @current_user.login.humanize %><br />\r\n<strong>Printed Date Time :</strong>&nbsp;<%= Time.now.strftime(\'%d/%m/%Y %H:%M\') %>\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong><% if record[\'approve\']!=\"\" %>Approved<% end %> By :</strong> \r\n<v><%=render_value \'endoscopist_approve\'%></v>\r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2014-06-11 15:06:56','2014-06-11 15:06:56','print',''),(1134,'list',528,3,'<%\r\n   model = get_model(this.table_name)\r\n   records = []\r\n   n = 20\r\n   rows = 20 \r\n  page = 0 \r\n  page = params[:page].to_i if params[:page]\r\n%>\r\n<%# params[:search] %>\r\n\r\n<%\r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   query=\'\'\r\n   if params[:search]\r\n\r\n\r\n\r\n       keys = []\r\n        query = params[:search][:query]\r\n        @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        @patient_doc = @ehr_project.get_document \'patient\'\r\n        @ehr_model = @ehr_project.get_model()\r\n        @patient_model = @ehr_model[:patient]\r\n        @module_model = @ehr_model[:patient_module]\r\n        @patient_doc.list_fields.each_with_index do |f,index| \r\n    	    keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        \r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        \r\n        ps = @patient_model.all({\'$or\'=>keys}.merge!(dates))\r\n   \r\n        records = []\r\n        for i in ps\r\n            records+= @module_model.where(:patient_id=>i.id).all \r\n        end\r\n        count = records.size\r\n        \r\n        \r\n\r\n        \r\n    else\r\n        \r\n        from_date = nil\r\n        to_date = nil  \r\n        rows,offset,page = params[:paginate]\r\n        n = model.count\r\n        records = model.all :offset=>offset,:limit=>rows,:order=>\'created_at desc\'\r\n    end\r\n   \r\n    patients={}\r\n    patients = {}\r\n    get_model(\'patient\').find(records.collect{|i| i.patient_id}).each do |i|\r\n    patients[i.id]=i\r\n    end\r\n\r\n%>\r\n\r\n\r\n\r\n<%= tabular :model=>%w{records  patient date  module_name }, :data=>records do |i,out|\r\n\r\n\r\nif i.module_name \r\nout[0]= i.module_name.split(\'#\').collect{|i| i.humanize}.join(\' : \') + \"\\\\#{\' / \'+i.ref_number if i.ref_number}\"\r\nend\r\nif patient = patients[i.patient_id]\r\nout[1]=link_to(\"\\\\#{patient.first_name} \\\\#{patient.last_name}<br/>\\\\#{patient.patient_number}\".html_safe,\"../Patient/show?id=\\\\#{i.patient_id}\",:target=>\'_blank\')\r\nend\r\nout[2]= i.date\r\nt = i.module_name.split(\'#\')\r\nproject = t[0]\r\nservice = t[1]\r\nif service\r\nout << link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, \"../../\\\\#{project}/\\\\#{service.camelize}/show?id=\\\\#{i.id}\",:class=>\'btn btn-info btn-mini\' )\r\nout << link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, \"../../\\\\#{project}/\\\\#{service.camelize}/destroy?id=\\\\#{i.id}\",:class=>\'btn btn-danger btn-mini\' )\r\nend\r\nout\r\nend\r\n%>\r\n\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2014-06-12 05:37:53','2014-06-12 05:37:53','lis