n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    count = model.count\r\n    \r\n    patient = @patient_model.find(params[:patient_id])\r\n    if patient\r\n       patient.update_attributes :patient_order=>count+1 \r\n    end\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2014-07-09 14:10:00','2014-07-09 14:10:00','create',''),(1155,'reorder',464,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n model = get_model(this.table_name)\r\n\r\n \r\n @patient_model.all.each do |i|\r\n    i.update_attributes :patient_order=>nil\r\n end\r\n \r\n outcomes = model.all\r\n order = 1\r\n outcomes.each_with_index do |i,index|\r\n \r\n m =  @module_model.collection.find(\'module_id\'=>i.id).first\r\n patient = @patient_model.find(m[\'patient_id\'])\r\n if m and patient\r\n     \r\n     patient.update_attributes :patient_order=>order\r\n     %>\r\n     <p><%=patient.patient_number%> : <%=patient.patient_order%> : <%=m[\'_id\'] %></p>\r\n     <%\r\n     \r\n     order+=1\r\n else\r\n    i.destroy\r\n end\r\n    \r\n end\r\n \r\n%>\r\n<%= outcomes.size %>',NULL,NULL,NULL,'2014-07-09 14:13:26','2014-07-09 14:13:26','reorder',''),(1156,'index',464,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :action=>\'.\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %> |\r\n<%= link_to \"Migration tools\", url(\"migrate\") %> |\r\n<%= link_to \"Export\", url(\"export\") %> |\r\n<%= link_to \"Reorder\", url(\"reorder\") %>\r\n\r\n\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2014-07-09 14:13:56','2014-07-09 14:13:56','index',''),(1157,'analysis2',235,2,'<%\r\n ncharts= 30\r\n%>\r\n<%\r\n #\r\n  @from_date = Time.now.beginning_of_year\r\n   @to_date = Time.now\r\n  if params[:analysis]\r\n  a =   (%w(1 2 3).map { |e| params[:analysis][\"from_date(\\\\#{e}i)\"].to_i }) \r\n\r\n  @from_date = Time.new a[0],a[1],a[2] \r\n  a =   (%w(1 2 3).map { |e| params[:analysis][\"to_date(\\\\#{e}i)\"].to_i }) \r\n  @to_date = Time.new a[0],a[1],a[2]\r\n  end\r\n  \r\n\r\n  table_name = this.table_name\r\n  @module_name = @current_project.name+\'#\'+ table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  models = get_model\r\n  \r\n  doc = get_document table_name\r\n  fields = doc.list_fields\r\n  fields_name = doc.list_fields_column_name\r\n  \r\n  model = models[table_name.to_sym]\r\n\r\n pmap = {}\r\n mmap = {}\r\n multi = {}\r\n lookup = {}\r\n \r\n \r\n # compute multi fields\r\n \r\n for i in fields \r\n   if i.field_type == \'check_string\'\r\n        multi[i.column_name] = {}\r\n        i.lov.split().each do |k|\r\n            multi[i.column_name][k]=0\r\n        end\r\n   end\r\n   if i.field_type == \'relation_one\'\r\n        p = eval \"{\\\\#{i.params}}\"\r\n        p = p[:relation][:document]\r\n        hash = {}\r\n        xdoc = get_document p\r\n        xlist = xdoc.list_fields_column_name\r\n        models[p.to_sym].all.each do |i|\r\n            hash[i.id.to_s]=xlist.collect{|j| i[j]  }.join(\" \")\r\n        end\r\n       lookup[i.column_name]=hash\r\n   end\r\n   \r\n end\r\n\r\n d=nil\r\n data =  @module_model.collection.find({:module_name=>@module_name,:date=>{\'$gte\'=>Date.to_mongo(@from_date), \'$lt\'=>Date.to_mongo(@to_date)}},{:sort=>{\'created_at\'=>-1}})\r\n c = 0\r\n data.each do |i|\r\n  \r\n\r\n c+=1\r\n pmap[i[\'patient_id\']] = nil\r\n mmap[i[\'module_id\']] = nil\r\n d =i\r\n end\r\n\r\n \r\n patients = @patient_model.collection.find({\'_id\'=>{\'$in\'=>pmap.keys}},{:fields=>[\'hn\',\'birth_date\',\'gender\']})\r\n patients.each do |i|\r\n pmap[i[\'_id\']] = i\r\n end\r\n\r\n\r\n \r\n mattrs = {}\r\n mattrs_idx = {}\r\n \r\n modules = model.collection.find({\'_id\'=>{\'$in\'=>mmap.keys}},{:fields=>fields_name})\r\n modules.each do |i|\r\n record = []\r\n fields.each do |field|\r\n j = field.column_name\r\n v = i[j]\r\n \r\n unless mattrs[j]\r\n mattrs[j]= {} \r\n mattrs_idx[j] = {}\r\n end\r\n \r\n l = mattrs[j]\r\n k = mattrs_idx[j]\r\n unless l[v]\r\n k[l.keys.size]=[v,0]\r\n l[v] = l.keys.size\r\n end\r\n k[l[v]][1]+=1\r\n record << l[v]\r\n\r\n end\r\n \r\n mmap[i[\'_id\']] = record\r\n \r\n end\r\n \r\n ages = {}\r\n  mattrs[\'age\']={}\r\n 10.times do |i|\r\n ages[i]= [\"\\\\#{i*10}-\\\\#{(i+1)*10}\",0]\r\n  mattrs[\'age\'][\"\\\\#{i*10}-\\\\#{(i+1)*10}\"]=i\r\n end\r\n \r\n mattrs_idx[\'age\']=ages\r\n \r\n \r\n mattrs_idx[\'gender\']={0=>[\"\",0],1=>[\"Male\",0],2=>[\"Female\",0]}\r\n mattrs[\'gender\']={\"\"=>0,\"Male\"=>1,\"Female\"=>2}\r\n\r\n \r\n \r\n records = []\r\n \r\n data.rewind!\r\n data.each do |i|\r\n date = i[\'date\']\r\n p = pmap[i[\'patient_id\']]\r\n if p and p[\'birth_date\']\r\n m = mmap[i[\'module_id\']]\r\n age = 0 \r\n age = ((date-p[\'birth_date\'])/31536000).to_i if p[\'birth_date\']\r\n record = {:date=>i[\'date\'].to_i,:age=>age,:hn=>p[\'hn\'],:gender=>p[\'gender\']}\r\n record[\'m\']=[age/10,p[\'gender\'].to_i]+m\r\n \r\n  mattrs_idx[\'age\'][age/10][1]+=1 if mattrs_idx[\'age\'][age/10]\r\n \r\n \r\n mattrs_idx[\'gender\'][p[\'gender\'].to_i][1]+=1\r\n \r\n \r\n record = [i[\'date\'].to_i,p[\'hn\'],age,age/10,p[\'gender\'].to_i]+m\r\n \r\n records << record\r\n end \r\n end\r\n \r\n\r\n  \r\n fields_name = [\'age\',\'gender\']+fields_name\r\n attrs = fields_name\r\n list = records;\r\n%>\r\n<h1><%=table_name.humanize%> Analysis</h1>\r\n\r\n\r\n<%=form_for :analysis,:url=>\'\' do |f| %>\r\n<%\r\n\r\noptions = options_for_select(attrs.collect{|i|\r\nif multi[i]\r\n[\"\"+i+\" (\\\\#{multi[i].keys().size()})\",i]\r\nelse\r\n[\"\"+i+\" (\\\\#{mattrs_idx[i].size()})\",i]\r\nend\r\n});\r\n\r\ngroup_options = options_for_select(attrs.collect{|i|[\"\"+i+\" (\\\\#{mattrs_idx[i].size()})\",i] if mattrs_idx[i].size()<5}.compact);\r\n\r\n\r\n%>\r\n\r\nPeriod : <%=f.date_select :from_date,:default=>@from_date,:order=>[:day,:month,:year] %> to : <%=f.date_select :to_date,:order=>[:day,:month,:year] %><%=f.submit \'Submit\'%>\r\n<hr/>\r\n<b>Interactive :</b><br/>\r\n\r\nGroup by : <%=f.select :group, group_options, :include_blank => \"\"%><br/>\r\nPlot X by : <%=f.select :x, options, :include_blank => \"\"%><br/>\r\n\r\n<hr/>\r\n<h3> Results </h3>\r\n<b>Selected period : </b> <%=@from_date%> - <%=@to_date%><br/>\r\n<b>Total results : </b> <%=c%> records\r\n\r\n<!--Plot Y by : <%=f.select :y,  options_for_select(attrs), :include_blank => \"\"%><br/>-->\r\n<div id=\"msg\"></div>\r\n<% ncharts.times do |i| %>\r\n<div id=\"chart<%=i%>\" style=\"width:100%;float:left;padding:20px\">\r\n</div>\r\n<% end %>\r\n<% end %>\r\n<script>\r\n\r\n\r\nfunction chart_repaint(title,id,series){\r\n      \r\n  var line1 = series;\r\n  var plot1 = $.jqplot(\'chart\'+id, [line1], {\r\n    title: \'\'+title,\r\n      animate: !$.jqplot.use_excanvas,\r\n    series:[{renderer:$.jqplot.BarRenderer}],\r\n     seriesDefaults:{\r\n            renderer:$.jqplot.BarRenderer,\r\n            rendererOptions: {\r\n                // Set the varyBarColor option to true to use different colors for each bar.\r\n                // The default series colors are used.\r\n                varyBarColor: true\r\n            }\r\n        },\r\n    axesDefaults: {\r\n        tickRenderer: $.jqplot.CanvasAxisTickRenderer ,\r\n        tickOptions: {\r\n          angle: -30,\r\n          fontSize: \'10pt\'\r\n        }\r\n    },\r\n    axes: {\r\n      xaxis: {\r\n        renderer: $.jqplot.CategoryAxisRenderer\r\n      }\r\n    }\r\n  });\r\n  \r\n  \r\n   \r\n   \r\n   \r\n   \r\n}\r\n\r\n\r\nfunction chart_update(){\r\n    \r\n    \r\n    for(i=0;i<<%=ncharts%>;i++) $(\'#chart\'+i).empty();\r\n    \r\n  \r\n   group = $(\'#analysis_group\').val()\r\n   x = $(\'#analysis_x\').val()\r\n   y = $(\'#analysis_y\').val()\r\n   if(x!=\"\"){\r\n       \r\n   $(\'#msg\').html(\"Group : \"+group+\", X : \"+x);\r\n   \r\n   xx = index[x]\r\n   xid = 3+fields.indexOf(x)\r\n   \r\n\r\n   \r\n   \r\n \r\n   if(group!=\"\"){\r\n        gg = index[group]\r\n        gid = 3+fields.indexOf(group)\r\n        hash = {}\r\n        \r\n        for(var g in gg){\r\n          if(gg.hasOwnProperty(g)){\r\n              hash[g]={}\r\n            for (var i in xx) {\r\n               if (xx.hasOwnProperty(i)) {\r\n                   hash[g][i]=0\r\n               }\r\n            }\r\n          }\r\n        }\r\n        for(i=0;i<records.length;i++){\r\n            r = records[i];\r\n            gidx = r[gid];\r\n            xidx = r[xid];\r\n            if(hash[gidx])\r\n            hash[gidx][xidx]+=1;\r\n            \r\n        }\r\n        \r\n        \r\n        \r\n        idx = 0\r\n        for(var g in gg){\r\n            \r\n            if(gg.hasOwnProperty(g)){\r\n                xattr = []  \r\n              \r\n                if(multi[x]){\r\n                    \r\n                for(var key in multi[x]){\r\n                    if(multi[x].hasOwnProperty(key)){\r\n                        multi[x][key]=0\r\n                    }\r\n                }    \r\n                    \r\n                    \r\n                for (var i in xx) {\r\n                    if (xx.hasOwnProperty(i)) {\r\n                        if(xx[i][0]){\r\n                        aa = xx[i][0].split(\"|\")\r\n                        \r\n                        for(var a in aa){\r\n                            a = aa[a]\r\n                            //alert(\"aa \"+a)\r\n                            if(a){\r\n                            multi[x][a]+=hash[g][i];}\r\n                        } \r\n                        \r\n                        }\r\n                        \r\n                    }\r\n                }\r\n                \r\n                var keys = [];\r\n                for (var key in multi[x]) {\r\n                if (multi[x].hasOwnProperty(key)) {\r\n                    keys.push(key);\r\n                }\r\n                }\r\n                keys.sort();\r\n                \r\n                for (k in multi[x]) {\r\n                       if (multi[x].hasOwnProperty(k)) {\r\n                        xattr.push([k,multi[x][k]]);\r\n                       }\r\n                }\r\n                \r\n               // alert(xattr)\r\n                    \r\n                }else{\r\n                \r\n                \r\n                for (var i in xx) {\r\n                    if (xx.hasOwnProperty(i)) {\r\n                        \r\n                        xattr.push([xx[i][0],hash[g][i]]);\r\n                        \r\n                        \r\n                    }\r\n                }\r\n                    \r\n                }\r\n               \r\n                 if(lookup[x]){\r\n           for(var i in xattr){\r\n               key = xattr[i][0];\r\n               xattr[i][0]= lookup[x][key];\r\n           }\r\n           \r\n       }\r\n       \r\n                \r\n                //alert(xattr[0]);\r\n                chart_repaint(gg[g][0],idx,xattr);\r\n                idx +=1;\r\n            }\r\n            \r\n            \r\n        }\r\n      \r\n       \r\n       \r\n   }else{\r\n       \r\n       \r\n       xattr = []  \r\n       \r\n       \r\n         \r\n                if(multi[x]){\r\n                    \r\n                for(var key in multi[x]){\r\n                    if(multi[x].hasOwnProperty(key)){\r\n                        multi[x][key]=0\r\n                    }\r\n                }    \r\n                    \r\n                    \r\n                for (var i in xx) {\r\n                    if (xx.hasOwnProperty(i)) {\r\n                        if(xx[i][0]){\r\n                        aa = xx[i][0].split(\"|\")\r\n                        \r\n                        for(var a in aa){\r\n                            a = aa[a]\r\n                           \r\n                            if(a){\r\n                            multi[x][a]+=xx[i][1]\r\n                            }\r\n                        } \r\n                        \r\n                        }\r\n                        \r\n                    }\r\n                }\r\n       \r\n                \r\n                for (k in multi[x]) {\r\n                       if (multi[x].hasOwnProperty(k)) {\r\n                       //   alert(\"aa \"+k)  \r\n                        xattr.push([k,multi[x][k]]);\r\n                       }\r\n                }\r\n                }\r\n       else{\r\n       \r\n        for (var i in xx) {\r\n        if (xx.hasOwnProperty(i)) {\r\n            xattr.push(xx[i].slice(0));\r\n        }\r\n        }\r\n       }\r\n       \r\n       if(lookup[x]){\r\n           for(var i in xattr){\r\n               key = xattr[i][0];\r\n               xattr[i][0]= lookup[x][key];\r\n           }\r\n           \r\n       }\r\n       \r\n       \r\n       \r\n        chart_repaint(x,0,xattr);\r\n   }\r\n   \r\n     \r\n   \r\n   \r\n   }else{\r\n     //alert(\"please select x\");\r\n   }\r\n   \r\n   \r\n   \r\n   \r\n   \r\n}\r\n\r\n$(\'#analysis_group\').change(function(){\r\nchart_update();\r\n});\r\n\r\n$(\'#analysis_x\').change(function(){\r\nchart_update();\r\n});\r\n$(\'#analysis_y\').change(function(){\r\nchart_update();\r\n});\r\n\r\n$(document).ready(function () {\r\n $.jqplot.config.enablePlugins = true;\r\n    fields = <%=fields_name.to_json.html_safe%>;\r\n    records = <%=records.to_json.html_safe%>;\r\n    index = <%=mattrs_idx.to_json.html_safe%>;\r\n    values = <%=mattrs.to_json.html_safe%>;\r\n    multi = <%=multi.to_json.html_safe%>;\r\n    lookup = <%=lookup.to_json.html_safe%>;\r\n});\r\n\r\n</script>\r\n\r\n<script type=\"text/javascript\" src=\"/jqplot/jquery.jqplot.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.canvasTextRenderer.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.canvasAxisTickRenderer.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.categoryAxisRenderer.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.barRenderer.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.highlighter.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.cursor.min.js\"></script>\r\n<script type=\"text/javascript\" src=\"/jqplot/plugins/jqplot.pointLabels.min.js\"></script>\r\n<link rel=\"stylesheet\" type=\"text/css\" hrf=\"/jqplot/jquery.jqplot.min.css\" />\r\n<style>\r\ninput,option,select{\r\nwidth:auto;\r\nmin-width:auto;\r\nwidth:100px;\r\n}\r\n</style>\r\n\r\n\r\n',NULL,NULL,NULL,'2014-07-21 13:15:12','2014-07-21 13:15:12','analysis2',''),(1158,'context_menu',398,4,'<div id=\"context-menu\" class=\"accordion\">\r\n             \r\n\r\n<div class=\"k-widget k-treeview\" tabindex=\"0\" role=\"tree\" aria-activedescendant=\"treeview_tv_active\"><ul id=\"treeview\" class=\"menu k-group k-treeview-lines\" style=\"background:#fff;outline:none\" data-role=\"treeview\">\r\n                    <li data-expanded=\"true\" class=\"k-item k-first k-last\" data-uid=\"e48dab40-6068-4d9a-a257-d97fb3c19ba7\" role=\"treeitem\"><div class=\"k-top k-bot\"><span class=\"k-icon k-minus\"></span>s<span class=\"k-in\"><span class=\"k-sprite folder\"></span><a data-disable-with=\"loading..\" data-remote=\"true\" href=\"/esm_projects/189/edit\">Med Endoscopy (Demo)</a></span></div><ul class=\"k-group\">\r\n                            <li class=\"k-item\" data-uid=\"3eabab8d-95fc-4f66-8001-8c95cb78c2b2\" role=\"treeitem\" aria-expanded=\"false\"><div class=\"k-top\"><span class=\"k-icon k-plus\"></span><span class=\"k-in\"><span class=\"k-sprite folder\"></span><a data-disable-with=\"loading..\" data-remote=\"true\" href=\"/esm_services?id=189\">Services</a></span></div><ul class=\"k-group\" style=\"height: 0px; overflow: visible; display: none;\">\r\n										<li class=\"k-item\" data-uid=\"35f557ca-286f-4269-a750-cd52783a50a1\" role=\"treeitem\"><div class=\"k-top\"><span class=\"k-icon k-plus\"></span><span class=\"k-in\"><span class=\"k-sprite html\"></span><a data-disable-with=\"loading..\" data-remote=\"true\" href=\"/esm_services/491\" style=\"text-align:center\">Colono</a></span></div><ul class=\"k-group\" style=\"display: none;\">\r\n												<li class=\"k-item\" data-uid=\"8fbf9194-9263-4487-b887-1f3165f2b56c\" role=\"treeitem\"><div class=\"k-top\"><span class=\"k-in\"><span class=\"k-sprite html\"></span><a data-disable-with=\"loading..\" data-remote=\"true\" href=\"/esm_services/491?op_id=1007\" style=\"text-align:center\">document_name</a></span></div></li>\r\n												<li class=\"k-item\" data-uid=\"45832beb-9c3f-449b-ad5d-92711b32557f\" role=\"treeitem\"><div class=\"k-mid\"><span class=\"k-in\"><span class=\"k-sprite html\"></span><a data-disable-with=\"loading..\" data-remote=\"true\" href=\"/esm_services/491?op_id=1018\" style=\"text-align:center\">form</a></span></div></li>\r\n												<li class=\"k-item\" data-uid=\"11af14fb-9902-453