          <div class=\"col-lg-6\">\r\n                                            <div class=\"form-group\">\r\n                                                <label>First name *</label>\r\n                                                <input id=\"name\" name=\"name\" type=\"text\" class=\"form-control required valid\" aria-required=\"true\" aria-invalid=\"false\">\r\n                                            </div>\r\n                                            <div class=\"form-group\">\r\n                                                <label>Last name *</label>\r\n                                                <input id=\"surname\" name=\"surname\" type=\"text\" class=\"form-control required valid\" aria-required=\"true\" aria-invalid=\"false\">\r\n                                            </div>\r\n                                        </div>\r\n                                        <div class=\"col-lg-6\">\r\n                                            <div class=\"form-group\">\r\n                                                <label>Email *</label>\r\n                                                <input id=\"email\" name=\"email\" type=\"text\" class=\"form-control required email valid\" aria-required=\"true\" aria-invalid=\"false\">\r\n                                            </div>\r\n                                            <div class=\"form-group\">\r\n                                                <label>Address *</label>\r\n                                                <input id=\"address\" name=\"address\" type=\"text\" class=\"form-control valid\" aria-invalid=\"false\">\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                </fieldset>\r\n\r\n                                <h1 id=\"form-h-2\" tabindex=\"-1\" class=\"title\">Warning</h1>\r\n                                <fieldset id=\"form-p-2\" role=\"tabpanel\" aria-labelledby=\"form-h-2\" class=\"body\" aria-hidden=\"true\" style=\"display: none;\">\r\n                                    <div class=\"text-center\" style=\"margin-top: 120px\">\r\n                                        <h2>You did it Man :-)</h2>\r\n                                    </div>\r\n                                </fieldset>\r\n\r\n                                <h1 id=\"form-h-3\" tabindex=\"-1\" class=\"title current\">Finish</h1>\r\n                                <fieldset id=\"form-p-3\" role=\"tabpanel\" aria-labelledby=\"form-h-3\" class=\"body current\" aria-hidden=\"false\" style=\"display: block;\">\r\n                                    <h2>Terms and Conditions</h2>\r\n                                    <input id=\"acceptTerms\" name=\"acceptTerms\" type=\"checkbox\" class=\"required\" aria-required=\"true\"> <label for=\"acceptTerms\">I agree with the Terms and Conditions.</label>\r\n                                </fieldset>\r\n                            </div><div class=\"actions clearfix\"><ul role=\"menu\" aria-label=\"Pagination\"><li class=\"\" aria-disabled=\"false\"><a href=\"#previous\" role=\"menuitem\">Previous</a></li><li aria-hidden=\"true\" aria-disabled=\"true\" class=\"disabled\" style=\"display: none;\"><a href=\"#next\" role=\"menuitem\">Next</a></li><li aria-hidden=\"false\"><a href=\"#finish\" role=\"menuitem\">Finish</a></li><li><a href=\"#cancel\" role=\"menuitem\">Cancel</a></li></ul></div></form>\r\n                        </div>\r\n                    </div>\r\n                    </div>\r\n                    \r\n                    <script src=\"js/plugins/metisMenu/jquery.metisMenu.js\"></script>\r\n    <script src=\"js/plugins/slimscroll/jquery.slimscroll.min.js\"></script>\r\n\r\n    <!-- Custom and plugin javascript -->\r\n    <script src=\"js/inspinia.js\"></script>\r\n    <script src=\"js/plugins/pace/pace.min.js\"></script>\r\n\r\n    <!-- Steps -->\r\n    <script src=\"js/plugins/staps/jquery.steps.min.js\"></script>\r\n\r\n    <!-- Jquery Validate -->\r\n    <script src=\"js/plugins/validate/jquery.validate.min.js\"></script>\r\n\r\n\r\n    <script>\r\n        $(document).ready(function(){\r\n            $(\"#wizard\").steps();\r\n            $(\"#form\").steps({\r\n                bodyTag: \"fieldset\",\r\n                onStepChanging: function (event, currentIndex, newIndex)\r\n                {\r\n                    // Always allow going backward even if the current step contains invalid fields!\r\n                    if (currentIndex > newIndex)\r\n                    {\r\n                        return true;\r\n                    }\r\n\r\n                    // Forbid suppressing \"Warning\" step if the user is to young\r\n                    if (newIndex === 3 && Number($(\"#age\").val()) < 18)\r\n                    {\r\n                        return false;\r\n                    }\r\n\r\n                    var form = $(this);\r\n\r\n                    // Clean up if user went backward before\r\n                    if (currentIndex < newIndex)\r\n                    {\r\n                        // To remove error styles\r\n                        $(\".body:eq(\" + newIndex + \") label.error\", form).remove();\r\n                        $(\".body:eq(\" + newIndex + \") .error\", form).removeClass(\"error\");\r\n                    }\r\n\r\n                    // Disable validation on fields that are disabled or hidden.\r\n                    form.validate().settings.ignore = \":disabled,:hidden\";\r\n\r\n                    // Start validation; Prevent going forward if false\r\n                    return form.valid();\r\n                },\r\n                onStepChanged: function (event, currentIndex, priorIndex)\r\n                {\r\n                    // Suppress (skip) \"Warning\" step if the user is old enough.\r\n                    if (currentIndex === 2 && Number($(\"#age\").val()) >= 18)\r\n                    {\r\n                        $(this).steps(\"next\");\r\n                    }\r\n\r\n                    // Suppress (skip) \"Warning\" step if the user is old enough and wants to the previous step.\r\n                    if (currentIndex === 2 && priorIndex === 3)\r\n                    {\r\n                        $(this).steps(\"previous\");\r\n                    }\r\n                },\r\n                onFinishing: function (event, currentIndex)\r\n                {\r\n                    var form = $(this);\r\n\r\n                    // Disable validation on fields that are disabled.\r\n                    // At this point it\'s recommended to do an overall check (mean ignoring only disabled fields)\r\n                    form.validate().settings.ignore = \":disabled\";\r\n\r\n                    // Start validation; Prevent form submission if false\r\n                    return form.valid();\r\n                },\r\n                onFinished: function (event, currentIndex)\r\n                {\r\n                    var form = $(this);\r\n\r\n                    // Submit form input\r\n                    form.submit();\r\n                }\r\n            }).validate({\r\n                        errorPlacement: function (error, element)\r\n                        {\r\n                            element.before(error);\r\n                        },\r\n                        rules: {\r\n                            confirm: {\r\n                                equalTo: \"#password\"\r\n                            }\r\n                        }\r\n                    });\r\n       });\r\n    </script>\r\n',NULL,NULL,NULL,'2014-07-29 10:41:58','2014-07-29 10:41:58','treetest',''),(1162,'document_name',537,1,'\'analysis\'',NULL,NULL,NULL,'2014-08-05 09:37:07','2014-08-05 09:37:07',NULL,NULL),(1163,'print',538,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\n@font-face {\r\n    font-family: \'barcode\';\r\n	src: url(\'/esm/ehr/emr/font/barcode.eot\');\r\n	src: local(\'☺\'), url(\'/esm/ehr/emr/font/c39hrp24dhtt.woff\') format(\'woff\'), url(\'/esm/ehr/emr/font/barcode.ttf\') format(\'truetype\'), url(\'/esm/ehr/emr/font/barcode.svg\') format(\'svg\');\r\n	font-weight: 700px;\r\n	font-size:60px;\r\n}\r\n.barcode\r\n	{font-family:\'barcode\',Sans-Serif;}\r\n#page {border:solid 0px;  border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding:0 0px 10px 10px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:14px;}\r\n.wrapper{ width:360px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:360px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:360px;margin-left:0px;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:0px solid #ccc;\r\n	-webkit-border-radius: 5px; /* Safari prototype */\r\n	-moz-border-radius: 5px; /* Gecko browsers */\r\n	border-radius: 5px; /* Everything else - limited support at the moment */	\r\n	margin:10px;\r\n}\r\n.smm { font-size:9pt; }\r\n#box img{\r\n		width:150px;\r\n}\r\nlabel{\r\n	color:#666;\r\n}\r\n</style>\r\n<body>\r\n<br />\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"page\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p></p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n%>\r\n<center>โรงพยาบาลจุฬาลงกรณ์ <br />\r\nศูนย์ความเป็นเลิศทางการแพทย์การผ่าตัดส่องกล้องโรคจมูกและไซนัส<br />\r\n  <strong>ใบนัด</strong>\r\n</center>\r\n\r\n----------------------------------------------------------------\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tr>\r\n  <td colspan=\"2\" >เลขที่ทั่วไป</td>\r\n  <td width=\"71%\">: <%= @patient.hn %></td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" ><storng>ชื่อ-นามสกุล</storng></td><td>: <%=@patient.prefix_name %> <%=@patient.first_name %> <%=@patient.last_name %></td></tr>\r\n<tr>\r\n  <td colspan=\"2\" >วันที่นัด</td>\r\n  <%\r\n    \r\n    txt = \'\'\r\n    months = %w{ม.ค. ก.พ. ม.ค. เม.ย. พ.ค. มิ.ย. ก.ค. ส.ค. ก.ย. ต.ค. พ.ย. ธ.ค.}\r\n    # month = month[record.date.month-1]\r\n    month = months[10-1]\r\n    year = record.date.year+543\r\n    \r\n    txt =  \"\\\\#{record.date.day} \\\\#{month} \\\\#{year}\"\r\n  \r\n  %>\r\n  \r\n  \r\n  <td>: <%= txt %></td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\"><storng>ยื่นใบนัด</storng></td><td>: <%= render_value \'start\' %> ถึง <%= render_value \'stop\' %></td></tr>\r\n<td colspan=\"2\">คลินิก</td><td>: คลินิกโรคจมูกและภูมิแพ้</td></tr>\r\n<td colspan=\"2\">ตึก</td><td>: ภปร. ชั้น 10</td></tr>\r\n<tr><td colspan=\"2\"><storng>แพทย์</storng></td><td>: <%= render_value \'provider\' %></td></tr>\r\n<tr>\r\n<td colspan=\"2\"><storng>มาทำ</storng></td><td>: <%= render_value \'procedure\' %></td></tr>\r\n<tr>\r\n  <td width=\"16%\">ข้อความ</td>\r\n  <td colspan=\"2\"><p>: <%= render_value \'note\' %></p></td>\r\n  </tr>\r\n</table>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tr>\r\n\r\n<td>\r\n<div class=\"barcode\" style=\"font-size:50px; float:right; margin-right:30px; height:60px\"><%= @patient.hn %> </div></td>\r\n</tr>\r\n\r\n</table>\r\n----------------------------------------------------------------<br />\r\n<span style=\"font-size:10px\">หมายเหตุ : เลื่อนนัดล่วงหน้า 1 อาทิตย์ โทร. 0-2256-5231 พฤหัสบดี – ศุกร์ เวลา 14.00 – 16.00 น.</span>\r\n<%# render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<%# @record.inspect %>\r\n\r\n<!-- <a href=\"http://<%=get_setting \'barcode_station\' %>/print?name=<%=@patient.first_name%>&date=<%= render_value \'date\'%>&proc=<%= render_value(\'procedure\').strip %>&hn=<%= @patient.hn %>\">Print</a> -->\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n<script>window.print();</script>\r\n</body>\r\n</html>',NULL,NULL,NULL,'2014-08-06 02:56:11','2014-08-06 02:56:11','print',''),(1164,'form',537,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   @prefix = \'\'\r\n   list = []\r\n   services = @project.get_services_by_abstract \'ehr.emr.Document\'\r\n   services.each do | i|\r\n      list<< [i.title,i.name] \r\n   end\r\n   list.sort!{|a,b| a[0]<=>b[0]}\r\n\r\n%>\r\n\r\n<%# render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n\r\n<div style=\"width:175px\">\r\n<%\r\nfield = @document.find_by_column_name \'name\'\r\n%>\r\n<%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n</div>\r\n\r\n<div id=\"name\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Table Name : </label></span>	\r\n\r\n<div style=\"width:175px\">\r\n\r\n<%= f.select :table_name, options_for_select(list, @record.table_name),{}, {:style => \"width:150px\",:id=>\"data-table_name\"}%>\r\n</div>\r\n    \r\n</div>\r\n\r\n\r\n<%\r\nfield = @document.find_by_column_name \'period_type\'\r\n%>\r\n<%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n\r\n<%\r\nfield = @document.find_by_column_name \'date\'\r\n%>\r\n<%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<%\r\nfield = @document.find_by_column_name \'group\'\r\n%>\r\n<%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n\r\n<%\r\nfield = @document.find_by_column_name \'group_visualization\'\r\n%>\r\n<%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%= render :inline=>this.init %>\r\n<% if @analysis %>\r\n<div id=\"form\">\r\n<%= render :inline=>this.form_data %>\r\n</div>\r\n<end>\r\n<% end %>\r\n',NULL,NULL,NULL,'2014-08-10 16:03:37','2014-08-10 16:03:37','',''),(1165,'show',537,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<br/>\r\n<%=form_for \'query\' , :url=>\'show_data?update=result\',:remote=>true do |f| %>\r\n<%= f.hidden_field :id,:value=>params[:id] %>\r\n\r\n<%=f.submit \'Query\' ,:class=>\'btn success\',:disable_with=>\'loading..\'%>\r\n<% end %>\r\n<div id=\"result\">\r\n    ...\r\n</div>\r\n<script>\r\n    refresh();\r\n</script>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2014-08-10 16:05:47','2014-08-10 16:05:47','show',''),(1166,'show_data',537,3,'<%# params.inspect %>\r\n<%\r\nif params[:query]\r\n    models = get_model\r\n    analysis = models[:analysis].find(params[:query][:id])\r\n    \r\n    table = models[analysis.table_name.to_sym]    \r\n    if table \r\n    \r\n    # counts = MessageLog.collection.group( {:key => :event_type, :cond => {}, :reduce => \'function(doc,prev) { prev.count += 1; }\', :initial => {:count => 0} })\r\n    # counts.each {|r| results[r[\"event_type\"]] = r[\"count\"]}\r\n    \r\n    doc = @current_project.get_document analysis.table_name\r\n    fields = doc.fields.collect{|i| i.column_name}.compact\r\n    \r\n    start_date = Time.now\r\n    stop_date = Time.now\r\n    \r\n    require \'active_support/all\'\r\n    \r\n    datetime_field = \'created_at\'\r\n    \r\n    case analysis.period_type\r\n    when \'last_24_hour\'\r\n    start_date = stop_date-3600*24\r\n    when \'last_7_days\'\r\n    start_date = stop_date-3600*24*7\r\n    when \'last_30_days\'\r\n    start_date = stop_date-3600*24*30\r\n    \r\n    when \'last_3_months\'\r\n    start_date = stop_date-3600*24*30*3\r\n    when \'last_6_months\'\r\n    start_date = stop_date-3600*24*30*6\r\n    when \'last_12_months\'\r\n    start_date = stop_date-3600*24*365\r\n    when \'last_3_years\'\r\n    start_date = stop_date-3600*24*365*3\r\n    \r\n    when \'last_hour\'\r\n    start_date = beginning_of_hour\r\n    when \'today\'\r\n    start_date = beginning_of_week\r\n    when \'this_month\'\r\n    start_date = beginning_of_month\r\n    when \'this_year\'\r\n    start_date = beginning_of_year\r\n    when \'all\'\r\n    start_date = stop_date-3600*24*365*99\r\n    \r\n    \r\n    else\r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    %>\r\n    <%#fields.inspect  %>\r\n    <%\r\n    \r\n    flist = []\r\n    or_list = []\r\n    \r\n    \r\n    cond = {datetime_field=>{\'$gte\'=>start_date,\'$lte\'=>stop_date}}\r\n\r\n    \r\n    for i in analysis.conditions\r\n    \r\n    f = doc.find_field i[0]\r\n    cname = f.column_name\r\n    flist << cname\r\n\r\n\r\n    \r\n    i[1].each do |j|\r\n        \r\n        k = j[1]\r\n        v = j[2]\r\n    \r\n    case f.field_type\r\n    \r\n    when \'relation_one\'\r\n        k = BSON::ObjectId(k)\r\n    else\r\n    end\r\n\r\n        \r\n    case v\r\n    \r\n    when \'1\'\r\n        cond.merge! cname=>k  \r\n    when \'2\'\r\n        or_list << {cname=>k}\r\n    when \'3\'\r\n        cond.merge! cname=>{\'$ne\'=>k}\r\n    else\r\n\r\n    end\r\n    \r\n    end    \r\n    \r\n    end\r\n  \r\n    cond.merge! \'$or\'=>or_list if or_list.size>0\r\n  \r\n    flist +=  analysis.fields.collect{|i| f = doc.find_field i[0] ; f.column_name} \r\n  \r\n    \r\n      \r\n    fmap = {}\r\n    \r\n    for i in flist\r\n    \r\n        field = doc.find_by_column_name i\r\n        \r\n        lov_type = field.lov_type\r\n    \r\n        case lov_type\r\n        when \'pair\'\r\n        map = {}\r\n        field.lov.split(\"\\n\").each{|i| \r\n        \r\n            t = i.strip.split(\"|\")\r\n            map[t[0]]=t[1].strip\r\n        }\r\n        fmap[i] = map\r\n        end\r\n\r\n    \r\n        case field.field_type\r\n        when \'relation_one\'\r\n        p = eval(\"{\\\\#{field.params}}\")\r\n        map={}\r\n        doc_name = p[:relation][:document]\r\n        model = models[doc_name.to_sym]\r\n        model.all.each{|i| \r\n            map[i.id]=i.name\r\n        }\r\n        fmap[i] = map\r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    \r\n    end\r\n    \r\n    \r\n  \r\n    flist.uniq!\r\n    %>\r\n    <div class=\"well\">\r\n    Query : <%= cond.inspect %>\r\n    </div>\r\n    <%\r\n    \r\n    flist = [\'_id\',\'hn\',\'name\',\'age\',\'gender\',\'date\',datetime_field] + flist unless analysis.group ==\'true\'\r\n    \r\n    \r\n    \r\n    records = table.collection.group( {\r\n    :key => flist , \r\n    # :key=>[\'status\'],\r\n    # :key=>[\'status\',\'file\'],\r\n    # :cond => {\'status\'=>\'Normal\'}, \r\n    :cond=>cond,\r\n    :reduce => \'function(doc,prev) { prev.count += 1; }\', \r\n    :initial => {:count => 0}\r\n    })\r\n    \r\n    m_list = []\r\n    p_list = []\r\n    \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n\r\n    m_map = {}\r\n    p_map = {}\r\n    am_map = {}\r\n    a_map = {}\r\n    rm_map = {}\r\n    \r\n    m_list = records.collect{|i|; i[\'_id\'] }.compact\r\n    \r\n    m_records = @module_model.collection.find(\'module_id\'=>{\'$in\'=>m_list}).to_a\r\n    \r\n    am_records = @module_model.collection.find(\'_id\'=>{\'$in\'=>m_records.collect{|i| i[\'parent_id\']}}).to_a\r\n    am_records.each do |i|\r\n        am_map[i[\'_id\']] = i\r\n    end\r\n    \r\n    a_records = models[:appointment].collection.find(\'_id\'=>{\'$in\'=>am_records.collect{|i| i[\'module_id\']}}).to_a\r\n    a_records.each do |i|\r\n        a_map[i[\'_id\']] = i\r\n    end\r\n    \r\n    m_records.each do |i|\r\n        rm_map[i[\'module_id\']] = i    \r\n    end\r\n    \r\n    p_list = m_records.collect{|i|  m_map[i[\'module_id\']] = i[\'patient_id\']}.compact\r\n    \r\n    p_records = @patient_model.collection.find({\'_id\'=>{\'$in\'=>p_list}},{:fields=>[\'hn\',\'first_name\',\'last_name\',\'birth_date\',\'gender\']}).to_a\r\n    \r\n    p_records.each do |i|\r\n        p_map[i[\'_id\']] = i\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    %>\r\n    \r\n    <%# a_map.inspect  %>\r\n\r\n\r\n    <%# p_map.inspect %>\r\n    <%\r\n    \r\n \r\n    \r\n    records.each do |i|\r\n    \r\n    pm = m_map[i[\'_id\']]\r\n       \r\n      if pm\r\n      p =  p_map[pm]   \r\n      if p\r\n       \r\n      age = 0 \r\n      age = ((i[datetime_field]-p[\'birth_date\'])/31536000).to_i if p[\'birth_date\']\r\n      p[\'age\'] = age\r\n      p[\'gender\']=\'M\' if p[\'gender\']==\'1\'\r\n      p[\'gender\']=\'F\' if p[\'gender\']==\'2\'\r\n      p[\'name\'] = \"\\\\#{p[\'first_name\']} \\\\#{p[\'last_name\']}\"\r\n      \r\n      rm = rm_map[i[\'_id\']]\r\n      \r\n      am = am_map[rm[\'parent_id\']]\r\n       \r\n      if am\r\n      a = a_map[am[\'module_id\']]\r\n      \r\n      \r\n      p[\'date\'] = a[\'date\'].strftime(\"%d/%m/%Y\") if a[\'date\'] \r\n      \r\n      end\r\n      \r\n      i.merge! p\r\n      \r\n      end\r\n      end  \r\n    end\r\n    %>\r\n    \r\n    <%# rm_map.inspect %>\r\n    <%\r\n    \r\n    \r\n    \r\n    analysis.update_attributes :records=>records\r\n    \r\n    # records = analysis.records\r\n    \r\n        \r\n    end\r\n%>\r\n\r\n<%# analysis.inspect %>\r\n\r\n<% if table \r\n\r\n\r\n%>\r\n<%#table.inspect %>\r\n\r\n<%#records.inspect %>\r\n<%\r\n%>\r\n<b>Download : </b>\r\n    <%= link_to \'XML\',url_for(\"download?id=\\\\#{analysis.id}&format=xml\"),:target=>\'_blank\' %> |\r\n    <%= link_to \'JSON\',url_for(\"download?id=\\\\#{analysis.id}&format=json\"),:target=>\'_blank\' %> |\r\n    <%= link_to \'TSV\',url_for(\"download?id=\\\\#{analysis.id}&format=tsv\"),:target=>\'_blank\' %> |\r\n    <span style=\"color:#666\">HL7</span><%# link_to \'HL7\',url_for(\"download?id=\\\\#{analysis.id}&format=hl7\") %> \r\n</p>\r\n\r\n<%\r\n \r\n cols = [\'select\']+flist\r\n flist.delete \'_id\'\r\n freplace = []\r\n for i in flist\r\n freplace << [i,cols.index(i)] if fmap[i]   \r\n end\r\n \r\n%>\r\n<%= form_for :export,:url=>\'export\' do |f| %>\r\n<%= tabular :data=>records,:model=>cols, :col_width=>{\'select\'=>50} do |row,out| \r\nout[0]= check_box_tag(\"select[]\",row[\'_id\'])\r\n\r\nfor i in freplace\r\nout[i[1]] = fmap[i[0]][row[i[0]]]\r\nend\r\n\r\nout << row[\'count\'] if analysis.group == \'true\'   \r\nout\r\nend%>\r\n\r\n<%= f.submit \'Export\' %>\r\n<% end %>\r\n<% end %>\r\n<% end %>\r\n',NULL,NULL,NULL,'2014-08-10 16:07:17','2014-08-10 16:07:17','show_data',''),(1167,'edit',537,2,'<%=render :inline=>this.setup %>..\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div class=\"\" style=\"border:0px solid;width:700px;float:left\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    \r\n    record = doc.record_update(model,params,record)\r\n    \r\n    if params[:cond]\r\n    \r\n    conditions = []\r\n    \r\n    params[:cond].each_pair do |k,v|\r\n      v = eval v\r\n      conditions << [k,v]\r\n    end\r\n    \r\n    fields = []\r\n    if params[:field]\r\n    params[:field].each_pair do |k,v|\r\n      v = eval v\r\n      fields << [k,v]\r\n    end\r\n    end\r\n    \r\n    \r\n    \r\n    record.update_attributes :conditions=>conditions,:fields=>fields\r\n        \r\n    end\r\n    \r\n    \r\n    \r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=record.id%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n</div>\r\n<div style=\"float:left\">\r\n<div id=\"view\" style=\"border:0px solid\" class=\"well\">\r\n    \r\n</div>    \r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n',NULL,NULL,NULL,'2014-08-10 17:03:45','2014-08-10 17:03:45','edit',''),(1168,'init',537,4,'<%\r\nif params[:id]\r\n    models = get_model\r\n    @analysis = models[:analysis].find(params[:id])\r\nif @analysis    \r\n%>\r\n<% end %>\r\n<% end %>\r\n',NULL,NULL,NULL,'2014-08-10 17:08:50','2014-08-10 17:08:50','init',''),(1169,'add_cond',537,3,'\r\n<% \r\n\r\ntable_name = params[:table_name]\r\ndoc = @current_project.get_document table_name\r\n\r\n\r\n\r\n\r\nunless request.post?\r\n       \r\nfields = doc.fields.collect{|i| i if i.column_name and %w{select_string check_string radio_string relation_one text_string}.index i.field_type }.compact\r\n       \r\n%>\r\n<%= form_for :cond,:url=>\"add_cond?table_name=\\\\#{params[:table_name]}&update=config_cond\",:remote=>true do |f| %>\r\nCondition Field : <%= f.select :field_id, options_for_select(fields.collect{|field| \r\n    \r\n    preview = \"\"\r\n\r\n    values = []\r\n    \r\n    case field.lov_type\r\n    \r\n    when \'plain\'\r\n    values = field.lov.split(\"\\n\").collect{|i| {\'name\'=>i.strip,\'value\'=>i.strip}}.compact\r\n    when \'pair\'\r\n    values = field.lov.split(\"\\n\").collect{|i| t = i.strip.split(\"|\")\r\n    {\'name\'=>t[1],\'value\'=>t[0]}\r\n    \r\n    }.compact\r\n    \r\n    end\r\n\r\n    \r\n    case field.field_type\r\n    when \'text_string\'\r\n    model = get_model()[table_name]\r\n    values = model.collection.find({},{:fields=>[field.column_name]}).limit(100).to_a.collect{|i| i[field.column_name] }.uniq.collect{|i| {\'name\'=>i,\'value\'=>i}}\r\n    \r\n    \r\n    when \'relation_one\'\r\n    p = eval(\"{\\\\#{field.params}}\")\r\n\r\n    doc_name = p[:relation][:document]\r\n    model = get_model()[doc_name.to_sym]\r\n    \r\n    values = model.all.collect{|i| {\'name\'=>i.to_s, \'value\'=>i.id}}.compact\r\n    \r\n    end\r\n    \r\n    preview = values[0..1].collect{|i| i[\'name\']}.join(\",\")+\",..\"\r\n    \r\n \r\n\r\n[\"\\\\#{field.label} (\\\\#{values.size}) : \\\\#{preview}\",field.id] } ) %>\r\n\r\n<%= f.submit \'Select\' %>\r\n<% end %>\r\n\r\n<div id=\"config_cond\">\r\n\r\n</div>\r\n\r\n<% else %>\r\n\r\n<%= render :inline=>this.config_cond %>\r\n\r\n<% end %>\r\n\r\n<script>\r\n    refresh()\r\n</script>\r\n',NULL,NULL,NULL,'2014-08-10 17:26:03','2014-08-10 17:26:03','add_cond',''),(1170,'form_data',537,4,'<hr/>\r\n<h4>Conditions  \r\n\r\n<%=link_to \'+\', \"javascript:add_cond()\",:class=>\'btn btn-success\' %><br/>\r\n</h4><br/>\r\n\r\n<div id=\"cond\">\r\n    \r\n<% \r\n\r\ntable_name = @analysis.table_name\r\ndoc = @current_project.get_document table_name\r\n\r\n@analysis.conditions.each do |i| \r\n\r\nfield = doc.find_field i[0]\r\n\r\n\r\n  tag = i[1].collect{|j| \r\n   \r\n   case j[2]\r\n   when \'1\'\r\n   t = \'And\'\r\n   when \'2\'\r\n   t = \'Or\'\r\n   when \'3\'\r\n   t = \'Not\'\r\n   else\r\n   end\r\n   \r\n   \"\\\\#{j[0]} (\\\\#{t}) \" \r\n   \r\n   }.join(\", \")\r\n\r\n%>\r\n    \r\n<div id=\"cond-<%=field.id%>\" class=\"well\">\r\n<label><b><%=field.name%></b>\r\n<span style=\"float:right\"><%= link_to \'...\', \"javascript:edit_cond(\'\\\\#{field.id}\')\" ,:class=>\'btn btn-mini\'%>\r\n<%= link_to \'Delete\', \"javascript:$(\'#cond-\\\\#{field.id}\').remove()\" ,:confirm=>\'Are you sure?\',:class=>\'btn btn-mini btn-danger\'%>\r\n</span>\r\n</label>\r\n\r\n<span id=\"<%=\"cond-t-\\\\#{field.id}\"%>\"><%=tag%></span>\r\n<%=hidden_field_tag \"cond[\\\\#{field.id}]\", i[1].to_json ,:id=>\"cond-v-\\\\#{field.id}\"%>\r\n</div>\r\n\r\n\r\n<% end %>\r\n\r\n</div>\r\n\r\n<hr/>\r\n\r\n<%# render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n\r\n<h4>\r\nDisplay Fields  \r\n\r\n\r\n<%=link_to \'+\', \"javascript:add_field()\",:class=>\'btn btn-success\' %>\r\n\r\n</h4>\r\n<br/>\r\n<div id=\"field\">\r\n    \r\n<% \r\n\r\n\r\n@analysis.fields.each do |i| \r\n\r\nfield = doc.find_field i[0]\r\n\r\n%>\r\n    \r\n<div id=\"field-<%=field.id%>\" class=\"well\">\r\n<label><%=field.name%>\r\n    <span style=\"float:right\">\r\n<%=hidden_field_tag \"field[\\\\#{field.id}]\", i[1] ,:id=>\"field-v-\\\\#{field.id}\"%>\r\n<%= link_to \'...\', \"config_field?table_name=\\\\#{table_name}&update=view&field[field_id]=\\\\#{field.id}\" ,:remote=>true,:class=>\'btn btn-mini\'%>\r\n<%= link_to \'Delete\', \"javascript:$(\'#field-\\\\#{field.id}\').remove()\" ,:confirm=>\'Are you sure?\',:class=>\'btn btn-mini btn-danger\'%>\r\n</span>\r\n</label>\r\n<span>\r\n    ...\r\n</span>\r\n</div>\r\n\r\n    \r\n\r\n\r\n<% end %>\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n<script>\r\n    refresh();\r\n</script>',NULL,NULL,NULL,'2014-08-10 17:33:23','2014-08-10 17:33:23','form_data',''),(1171,'config_cond',537,3,'<%\r\n\r\n\r\n    table_name = params[:table_name]\r\n    doc = @current_project.get_document table_name\r\n\r\n%>\r\n\r\n\r\n<% unless params[:cond][:config]\r\n\r\n\r\n    field = doc.find_field params[:cond][:field_id]\r\n    values = []\r\n    lov_type = field.lov_type\r\n    \r\n    case lov_type\r\n    \r\n    when \'plain\'\r\n    values = field.lov.split(\"\\n\").collect{|i| {\'name\'=>i.strip,\'value\'=>i.strip}}.compact\r\n    when \'pair\'\r\n    values = field.lov.split(\"\\n\").collect{|i| t = i.strip.split(\"|\")\r\n    {\'name\'=>t[1],\'value\'=>t[0]}\r\n    \r\n    }.compact\r\n    end\r\n\r\n    \r\n    case field.field_type\r\n    \r\n    when \'text_string\'\r\n    model = get_model()[table_name]\r\n    values = model.collection.find({},{:fields=>[field.column_name]}).limit(1000).to_a.collect{|i| i[field.column_name] }.uniq.collect{|i| \r\n    v = i\r\n    # v = i.gsub(\' \',\'_\')  if i\r\n    \r\n    {\'name\'=>i,\'value\'=>v}}\r\n   \r\n    when \'relation_one\'\r\n    p = eval(\"{\\\\#{field.params}}\")\r\n\r\n    doc_name = p[:relation][:document]\r\n    model = get_model()[doc_name.to_sym]\r\n    \r\n    values = model.all.collect{|i| {\'name\'=>i.to_s, \'value\'=>i.id}}.compact\r\n    \r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    values.collect!{|i| i if i[\'value\'] and i[\'value\']!=\'\' }.compact!\r\n    \r\n    \r\n%>\r\n<b><%=field.name %></b>\r\n<div style=\"width:500px\">\r\n\r\n<%\r\n    lmap={}\r\n    if params[:value]\r\n        params[:value].split(\",\").each do |i|\r\n            t = i.split(\"|\")\r\n            lmap[t[0]]=t[1].strip.to_i\r\n        end\r\n    \r\n    end\r\n%>\r\n<%= form_for :cond,:url=>\"config_cond?table_name=\\\\#{params[:table_name]}&update=view\",:remote=>true do |f| %>\r\n<%= f.hidden_field \'config\',:value=>true%>\r\n<%= f.hidden_field \'field_id\',:value=>field.id%>\r\n<%= tabular :data=>values,:model=>%w{Value Any And Or Not},:col_width=>{\'Value\'=>200} do |row,out| \r\nout[0] = row[\'name\']\r\nv = row[\'value\']\r\nlv = lmap[v.to_s]\r\n\r\nout[1] = radio_button_tag(\"cond[values][\\\\#{v}]\",0,lv==nil) \r\nout[2] = radio_button_tag(\"cond[values][\\\\#{v}]\",1,lv==1) \r\nout[3] = radio_button_tag(\"cond[values][\\\\#{v}]\",2,lv==2) \r\nout[4] = radio_button_tag(\"cond[values][\\\\#{v}]\",3,lv==3) \r\nout[1] += hidden_field_tag(\"cond[\\\\#{v}]\",out[0])\r\n\r\n\r\nout\r\nend\r\n%>\r\n<%= f.submit \'Submit\' ,:class=>\'btn btn-info\'%>\r\n\r\n<% end %>\r\n</div>\r\n\r\n<% else %>\r\n<%= params.inspect %>\r\n<%\r\n\r\n   field = doc.find_field params[:cond][:field_id]\r\n   \r\n   map = {}\r\n   mapl = []\r\n   tag = \"\"\r\n   \r\n   if true or field.field_type !=\'text_string\'\r\n   \r\n   params[:cond][:values].each_pair do |k,v|\r\n   label = params[:cond][k]\r\n       \r\n   if v!=\"0\"\r\n       map[k]=v\r\n       mapl << [label,k,v]\r\n   end\r\n       \r\n   end\r\n   \r\n   end\r\n   tag = mapl.collect{|i| \r\n   \r\n   case i[2]\r\n   when \'1\'\r\n   t = \'And\'\r\n   when \'2\'\r\n   t = \'Or\'\r\n   when \'3\'\r\n   t = \'Not\'\r\n   else\r\n   end\r\n   \r\n   \"\\\\#{i[0]} (\\\\#{t}) \" \r\n   \r\n   }.join(\", \")\r\n   \r\n%>\r\n\r\nAdded\r\n\r\n\r\n<div id=\"cond-<%=field.id%>-new\" class=\"well\">\r\n<label><b><%=field.name%></b>\r\n<span style=\"float:right\"><%= link_to \'...\', \"javascript:edit_cond(\'\\\\#{field.id}\')\" ,:class=>\'btn btn-mini\'%>\r\n<%= link_to \'Delete\', \"javascript:$(\'#cond-\\\\#{field.id}\').remove()\" ,:confirm=>\'Are you sure?\',:class=>\'btn btn-mini btn-danger\'%>\r\n</span>\r\n</label>\r\n<span id=\"<%=\"cond-t2-\\\\#{field.id}\"%>\"><%=tag%></span>\r\n<%=hidden_field_tag \"cond[\\\\#{field.id}]\", mapl.to_json ,:id=>\"cond-v-\\\\#{field.id}\"%>\r\n</div>\r\n\r\n\r\n\r\n\r\n<script>\r\n    obj = $(\'#cond-<%=field.id%>\')\r\n    new_obj = $(\'#cond-<%=field.id%>-new\')\r\n    if(obj.length){\r\n      $(\"#cond-v-<%=field.id%>\").val(\'<%=mapl.to_json.html_safe%>\')\r\n      $(\"#cond-t-<%=field.id%>\").html(\'<%=tag%>\')\r\n      new_obj.remove()\r\n    }else{\r\n      new_obj.appendTo($(\"#cond\"));\r\n      new_obj.attr(\"id\",\"cond-<%=field.id%>\");\r\n      $(\"#cond-t2-<%=field.id%>\").attr(\"id\",\"cond-t-<%=field.id%>\")\r\n    }\r\n</script>\r\n\r\n<% end %>\r\n\r\n\r\n<script>\r\nrefresh()    \r\n</script>',NULL,NULL,NULL,'2014-08-10 17:58:59','2014-08-10 17:58:59','config_cond',''),(1172,'setup',537,4,'<script>\r\nfunction add_cond(){\r\n\r\ntable_name = $(\'#data-table_name\').val()\r\n\r\n$.ajax({\r\n    url: \"<%=url_for \"add_cond\"%>?table_name=\"+table_name,\r\n    context: document.body\r\n}).done(function(data) {\r\n    \r\n$(\'#view\').html(data);\r\n});\r\n}\r\n\r\nfunction add_field(){\r\n\r\ntable_name = $(\'#data-table_name\').val()\r\n\r\n$.ajax({\r\n    url: \"<%=url_for \"add_field\"%>?table_name=\"+table_name,\r\n    context: document.body\r\n}).done(function(data) {\r\n    \r\n$(\'#view\').html(data);\r\n});\r\n}\r\n\r\n\r\n\r\n    function edit_cond(field_id){\r\n\r\n        val = $(\'#cond-v-\'+field_id).val()\r\n        pval = eval(val)\r\n      \r\n        values = []\r\n        \r\n        for(i in pval){\r\n            values+=pval[i][1]+\'|\'+pval[i][2]+\',\'\r\n        }\r\n        \r\n        table_name = $(\'#data-table_name\').val()\r\n        \r\n        $.ajax({\r\n          url: \'config_cond?table_name=\'+table_name+\'&update=view&cond[field_id]=\'+field_id+\'&value=\'+values,\r\n          context: document.body\r\n        }).done(function(data) {\r\n           $(\'#view\').html(data)\r\n        });\r\n        \r\n        refresh()\r\n        \r\n    }\r\n    \r\n</script>',NULL,NULL,NULL,'2014-08-11 13:35:34','2014-08-11 13:35:34','setup',''),(1173,'add_field',537,3,'<% \r\n\r\ntable_name = params[:table_name]\r\ndoc = @current_project.get_document table_name\r\n\r\n\r\n\r\n\r\nunless request.post?\r\n       \r\nfields = doc.fields.collect{|i| i if i.column_name }.compact\r\n\r\n       \r\n%>\r\n<%= form_for :field,:url=>\"add_field?table_name=\\\\#{params[:table_name]}&update=config_field\",:remote=>true do |f| %>\r\nSelect Field : <%= f.select :field_id, op