id=\"field-<%=field.id%>-new\">\r\n<label><%=field.name%></label>\r\n<%=text_field_tag \"field[\\\\#{field.id}]\", map ,:id=>\"field-v-\\\\#{field.id}\"%>\r\n<%= link_to \'...\', \"config_field?table_name=\\\\#{table_name}&update=view&field[field_id]=\\\\#{field.id}\" ,:remote=>true,:class=>\'btn\'%>\r\n<%= link_to \'Delete\', \"javascript:$(\'#field-\\\\#{field.id}\').remove()\" ,:confirm=>\'Are you sure?\',:class=>\'btn\'%>\r\n\r\n</div>\r\n\r\n\r\n<script>\r\n    obj = $(\'#field-<%=field.id%>\')\r\n    new_obj = $(\'#field-<%=field.id%>-new\')\r\n    if(obj.length){\r\n      $(\"#field-v-<%=field.id%>\").val(\'<%=map.inspect.html_safe%>\')\r\n      new_obj.remove()\r\n        \r\n        \r\n    }else{\r\n\r\n      new_obj.appendTo($(\"#field\"));\r\n      new_obj.attr(\"id\",\"field-<%=field.id%>\");\r\n    }\r\n</script>\r\n\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2014-08-11 17:16:55','2014-08-11 17:16:55','config_field',''),(1175,'download',537,3,'<%\r\n    format = params[:format]\r\n    \r\n    id = params[:id]\r\n    analysis = get_model()[:analysis].find(id)\r\n    if analysis.records \r\n    first = analysis.records[0]\r\n    keys = first.keys\r\n    end\r\n    \r\n    if analysis\r\n    case format\r\n    when \'json\'\r\n%><%= analysis.records.to_json %>\r\n<% when \'xml\'%><%= analysis.records.to_xml %>\r\n<% when \'tsv\'%><%= keys.join(\"\\t\")%>\r\n<% for i in analysis.records \r\n   for j in keys\r\n   v = i[j]\r\n   v = \'.\' unless i[j]\r\n%><%= v%><%=\"\\t\"%><% end %>\r\n<% end %>\r\n<% else %><% end %><% end %>\r\n',NULL,NULL,NULL,'2014-08-11 18:25:54','2014-08-11 18:25:54','download',''),(1180,'list',379,3,'\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   records = []\r\n   n = 10 \r\n%>\r\n<%\r\n   \r\n   values = {}\r\n   query=\'\'\r\n   \r\n   # custom patient search\r\n   if params[:search]\r\n        keys = []\r\n        query = params[:search][:query]\r\n        @patient_doc.list_fields.each_with_index do |f,i