 list = mtoday.collect{|i| \r\n        p = @patient_model.find(i.patient_id)\r\n        if p\r\n        ap = @models[:appointment].find(i.module_id)\r\n        {:admit_id=>ap.id,:patient_name=>\"\\\\#{p.first_name.force_encoding(\'UTF-8\')} \\\\#{p.last_name.force_encoding(\'UTF-8\')}\",:patient_hn=>p.hn,:patient=>p,:gender=>p.gender,:age=>\'20 year\', :appointment=>ap,:appointed=>@models[:procedure].find(ap.procedure).name,:status=>ap.status}\r\n        else\r\n        nil\r\n        end\r\n    }\r\n    list.compact!\r\n    result = {:result=>\'200 OK\',:return=>list,:timestamp=>Time.now}\r\n    \r\n%>\r\n<%=result.to_json.html_safe%>',NULL,NULL,NULL,'2014-12-06 05:36:35','2014-12-06 05:36:35','get_today_patients','*'),(1241,'get_image_capture_by_admit_id',574,3,'<%= render :inline=>this.init%><%\r\n    result=nil\r\n    if params[:admit_id] \r\n        \r\n    services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if i.name!=\'live_document\'}.compact\r\n    \r\n    #   list = []\r\n    #     Service.find(@current_project.init_instance[:services].collect{|i| i.id}).each do |i|\r\n    #     if i.extended==\'cusys.med.FindingDocument\'\r\n    #       list << i\r\n    #     end          \r\n          \r\n    #     end\r\n        \r\n    #   services = list  \r\n    \r\n\r\n    admit_id = params[:admit_id]\r\n    \r\n    mapp = @patient_module_model.where(:module_id=>admit_id).first\r\n    patient = @patient_model.find(mapp.patient_id) if mapp\r\n    \r\n    if mapp and patient\r\n    \r\n    \r\n    list = services.collect{|i|\r\n    \r\n    doc =  @current_project.get_document i.name\r\n  \r\n    model = @models[doc.name.to_sym]\r\n   \r\n    mm = @patient_module_model.where(:parent_id=>mapp.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\").first\r\n    \r\n    if mm\r\n        record = model.find(mm.module_id)\r\n    else\r\n        mm = @patient_module_model.new :module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\", :parent_id=>mapp.id\r\n        record = model.new\r\n    end\r\n    \r\n    \r\n    \r\n    img_f = nil\r\n    \r\n        ohn = patient.hn\r\n        hn = patient.hn.split(\"/\").join(\"-\")\r\n        \r\n            \r\n    \r\n        \r\n        \r\n        record_id = mm.id\r\n        \r\n        imgs = nil        \r\n        for j in doc.fields \r\n            if j.field_type == \'image_camera\'\r\n                img_f = j \r\n                snap = URI.encode(\"/esm_image/\\\\#{doc.id}/snap?field_id=\\\\#{j.id}&p_id=\\\\#{@current_project.id}&path=esm/\\\\#{@current_project.esm.name}/\\\\#{@current_project.name}/\\\\#{hn}/\\\\#{doc.name}/\\\\#{Time.now.strftime(\'%Y-%m-%d\')}-\\\\#{record_id}/image&ref=\\\\#{ohn}\")\r\n                # admit_id, doc_id, record_id\r\n                attachment = URI.encode(\"/esm/\\\\#{@current_project.esm.name}/\\\\#{@current_project.name}/Api/attach_image_by_admit_id?admit_id=\\\\#{admit_id}&doc_id=\\\\#{doc.name}&record_id=\\\\#{record_id}&f_id=\\\\#{j.column_name}\")\r\n                images = []\r\n                \r\n                images = @models[:attachment].find(record[j.column_name]).collect{|img| img.path}\r\n                created_at = \'\'\r\n                created_at = record.created_at.strftime(\"%d-%m-%Y %H:%M\") if record.created_at\r\n                imgs = {:name=>doc.name,:title=>doc.title, :created_at=>created_at, :snap_url=>snap,:attach_url=>attachment, :images=>images}    \r\n            end\r\n        end\r\n    \r\n    \r\n    imgs if img_f\r\n    \r\n    }    \r\n    \r\n    list.compact!\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n    result = {:result=>\'200 OK\',:return=>list,:timestamp=>Time.now}\r\n    else\r\n    result = {:result=>\'404 Not found\',:return=>nil,:timestamp=>Time.now}\r\n    end\r\n\r\n%><%= result.to_json.html_safe%>',NULL,NULL,NULL,'2014-12-06 05:48:11','2014-12-06 05:48:11','get_image_capture_by_admit_id','*'),(1242,'init',574,4,'<%\r\n    @modules = @current_project.documents\r\n    @models = get_model\r\n    @ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @ehr_models = @ehr.load_model\r\n    \r\n    @patient_model = @ehr_models[:patient]\r\n    @patient_module_model = @ehr_models[:patient_module]\r\n\r\n%>',NULL,NULL,NULL,'2014-12-06 05:48:37','2014-12-06 05:48:37','init',''),(1243,'attach_image_by_admit_id',574,3,'<%= render :inline=>this.init%><%\r\n    \r\n    # admit_id, doc_id, record_id\r\n    \r\n                            #  with name\r\n    if params[:admit_id] and params[:doc_id] and params[:record_id] and params[:ssid] and params[:f_id] \r\n        attachment_model = get_model[:attachment]\r\n        madmit  = @patient_module_model.where(:module_id=>params[:admit_id]).first\r\n        patient = @patient_model.find(madmit.patient_id)\r\n        mrecord = @patient_module_model.find(params[:record_id])\r\n        doc = @current_project.get_document params[:doc_id] \r\n\r\n        mrecord = @patient_module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\",:parent_id=>madmit.id).first unless mrecord\r\n        \r\n        img_f = doc.find_by_column_name params[:f_id] \r\n        if mrecord\r\n            # new record \r\n            list = []\r\n           \r\n            record = @models[doc.name.to_sym].find(mrecord.module_id)\r\n            if record\r\n                \r\n                list = attachment_model.where(:ssid=>{\'$in\'=>[params[:ssid].to_i,params[:ssid]]}).all\r\n            \r\n                # list = attachment_model.all(:limit=>1)\r\n                record.update_attributes img_f.column_name.to_sym=>(record.image+list.collect{|l| l.id })\r\n                #list = record.image\r\n                \r\n            end\r\n            result = {:result=>\'200 OK UPDATED\',:return=>list,:timestamp=>Time.now,:attachments=>list.collect{|l| l.id}}\r\n        else\r\n            # new record\r\n            # list = attachment_model.where(:ssid=>params[:ssid]).all\r\n            list = attachment_model.where(:ssid=>{\'$in\'=>[params[:ssid].to_i,params[:ssid]]}).all\r\n            record = @models[doc.name.to_sym].create  img_f.column_name.to_sym=>(list.collect{|l| l.id })\r\n            \r\n             i = @patient_module_model.last :module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\"\r\n              l = 111\r\n              if i and i.ref_number\r\n                  l = i.ref_number[6..-1].to_i%10000\r\n              end\r\n              next_id = format(\'%04d\',(l+1)%10000)\r\n              d = Time.now\r\n              @next_id = \"\\\\#{d.strftime(\'%y%m%d\')}\\\\#{next_id}\"\r\n            \r\n            \r\n            mrecord = @patient_module_model.create :date=>Time.now, :ref_number=>@next_id ,:patient_id=>patient.id, :module_id=>record.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\",:parent_id=>madmit.id\r\n            \r\n            mapp =  @patient_module_model.find(mrecord.parent_id)\r\n            app = @models[:appointment].find(mapp.module_id)\r\n            app.update_attributes :status=>\'Processing\'\r\n            \r\n            \r\n            \r\n            \r\n            # result = {:result=>\'201 OK CREATED\',:return=>nil,:timestamp=>Time.now,:attachments=>list.collect{|l| l.id}}\r\n            result = {:result=>\'201 OK CREATED\',:return=>list,:timestamp=>Time.now,:attachments=>list.collect{|l| l.id}}\r\n        end\r\n    else\r\n        result = {:result=>\'404 Not found\',:return=>nil,:timestamp=>Time.now}\r\n\r\n    end\r\n   result[:params]=params.inspect\r\n%><%= result.to_json.html_safe%>',NULL,NULL,NULL,'2014-12-06 08:12:45','2014-12-06 08:12:45','attach_image_by_admit_id','*'),(1244,'export_zam',463,3,'<%\r\n\r\n    @module_name = @current_project.name+\'#\'+ this.table_name \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n\r\n    @document = get_document(this.document_name)\r\n\r\n    doc = @document\r\n\r\n    data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n  \r\n    fields = @document.fields\r\n#   fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n    cols = %w{record_day vasopressor rs coagulation cns liver renal cvs diuretic lactate sofa if_rrt mechanical_ventilation net_balance indication mode_of_rrt}\r\n    fields = fields.collect do |i|\r\n        col_name = i.column_name.to_s\r\n        if cols.include?(col_name)\r\n            [i.column_name,i.name] unless Document.visual_types.index(i.field_type)\r\n        end\r\n    end\r\n    fields = fields.compact!\r\n    fields << \'created_at\'\r\n    fields << \'updated_at\'\r\n    @document = doc\r\n    @fields = @document.fields\r\n   \r\n    data.collect! do |i|\r\n    \r\n        @record = i\r\n     \r\n     \r\n        # sofa = [\'rs\',\'temperature\',\'coagulation\',\'cns\',\'liver\',\'renal\',\'cvs\']\r\n        # sum = 0 \r\n        # for j in sofa\r\n        #     v = i[j]\r\n        #     if v and v.strip.downcase == \'na\'\r\n        #         v = \'0\'\r\n        #     end\r\n        #     sum += v.to_i if v \r\n        # end\r\n          \r\n        # i[\'sofa\'] = sum\r\n     \r\n        p = nil\r\n        age = nil\r\n        age = 0\r\n        hn = nil\r\n        \r\n        p = @patient_model.new\r\n        m = @module_model.collection.find(:module_id=>i.id).first\r\n        if m \r\n            patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n            if patient\r\n                bdate = 0\r\n                bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n                age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n                p = patient\r\n            end\r\n        end\r\n        \r\n        if p\r\n            r = {:patient=>p,:age=>age,:record=>i}\r\n        else\r\n            r = nil\r\n        end\r\n    \r\n        # collect record to data\r\n        r\r\n   \r\n    end\r\n   \r\n    data.compact!\r\n    data = data.sort{|a,b| a[:patient][\'patient_order\'].to_i<=>b[:patient][\'patient_order\'].to_i }\r\n   \r\n    unless params[:type]\r\n   \r\n%>\r\n<table>\r\n    <tr>\r\n        <td>Order</td>\r\n        <td>Patient number</td>\r\n        <td>Gender</td>\r\n        <td>Birth Date</td>\r\n        <td>Age</td>\r\n<%\r\n    for i in fields \r\n%>\r\n        <td><%= i[1] %></td>\r\n<% end %>\r\n    </tr>\r\n<% \r\n    for i in data \r\n        p = i[:patient]\r\n        age = i[:age]\r\n        @record = i[:record] \r\n        bd = p[\'birth_date\'].strftime(\'%d-%m-%Y\') if !p[\'birth_date\'].nil?\r\n%>\r\n    <tr>\r\n        <td><%=p[\'patient_order\'] %></td>\r\n        <td><%=p[\'patient_number\']%></td> \r\n        <td><%=p[\'gender\']%></td>\r\n        <td><%=bd%></td>\r\n        <td><%=age%></td>\r\n<%\r\n        for j in fields \r\n            if @record[j[0]]\r\n%>\r\n        <td><%= render_value j[0] %></td>\r\n<% \r\n            else \r\n%>\r\n        <td>.</td>\r\n<%          end %>\r\n<%      end %>\r\n</tr>\r\n<%  end %>\r\n</table>\r\n<% else \r\n    if params[:type]==\'csv\'\r\n        require \'csv\'\r\n        res = CSV.generate do |csv|\r\n            csv << [\"patient_order\", \"patient_number\", \"gender\", \"birth_date\",\"age\"]+fields.collect{|i| i[0]}\r\n            for i in data \r\n                p = i[:patient]\r\n                age = i[:age]\r\n                @record = i[:record]\r\n                lines = []\r\n                lines = fields.collect{|j| \r\n                    if @record[j[0]]\r\n                        res = render_value(j[0]).strip\r\n                    else\r\n                        res = \'\'\r\n                    end\r\n                    res\r\n                }\r\n  \r\n                csv << [p[\'patient_order\'], p[\'patient_number\'],p[\'gender\'],p[\'birth_date\'] ? p[\'birth_date\'].strftime(\'%d/%m/%Y\') : \'-\',age]+lines \r\n            end\r\n  # ...\r\n        end\r\n%>\r\n<%=res.html_safe%>\r\n<%\r\n    end\r\nend\r\n%>\r\n  \r\n  \r\n   \r\n   \r\n   ',NULL,NULL,NULL,'2014-12-13 14:22:35','2014-12-13 14:22:35','export_zam','*'),(1245,'document_name',576,1,'\'gastroscopy_finding_2\'',NULL,NULL,NULL,'2014-12-15 06:36:21','2014-12-15 06:36:21',NULL,NULL),(1246,'document_name',577,1,'\'gastroscopy_finding_3\'',NULL,NULL,NULL,'2014-12-15 06:44:59','2014-12-15 06:44:59',NULL,NULL),(1247,'document_name',578,1,'\'gastroscopy_finding_4\'',NULL,NULL,NULL,'2014-12-15 06:50:17','2014-12-15 06:50:17',NULL,NULL),(1248,'document_name',579,1,'\'gastroscopy_finding_6\'',NULL,NULL,NULL,'2014-12-15 07:46:32','2014-12-15 07:46:32',NULL,NULL),(1249,'document_name',580,1,'\'colono_finding_2\'',NULL,NULL,NULL,'2014-12-15 14:22:59','2014-12-15 14:22:59',NULL,NULL),(1250,'document_name',581,1,'\'colono_finding_4\'',NULL,NULL,NULL,'2014-12-15 14:53:25','2014-12-15 14:53:25',NULL,NULL),(1251,'document_name',582,1,'\'colono_finding_5\'',NULL,NULL,NULL,'2014-12-15 14:57:16','2014-12-15 14:57:16',NULL,NULL),(1252,'document_name',583,1,'\'colono_finding_6\'',NULL,NULL,NULL,'2014-12-15 15:04:15','2014-12-15 15:04:15',NULL,NULL),(1253,'document_name',584,1,'\'colono_finding_7\'',NULL,NULL,NULL,'2014-12-15 15:05:42','2014-12-15 15:05:42',NULL,NULL),(1257,'index',586,2,'<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       <b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n\r\n\r\n\r\n\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\"><i class=\"splashy-add\"></i> New patient</button></a>\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\',:style=>\'width:120px\' %> <%=link_to \"( Today Click )\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %>\r\n\r\n       [ <%= Time.now.strftime(\"%H : %M\") %> ]\r\n        \r\n       <%= date.strftime(\'%A %d %B %Y\')%><br/>\r\n\r\n <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n\r\n\r\n<div class=\"tabbable\">\r\n								<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#tab1\" data-toggle=\"tab\">Today Patient</a></li>\r\n									<li class=\"\"><a href=\"#tab2\" data-toggle=\"tab\">Recovery</a></li>\r\n									<li><a href=\"#tab3\" data-toggle=\"tab\">Complete</a></li>\r\n								</ul>\r\n								<div class=\"tab-content\">\r\n									<div class=\"tab-pane active\" id=\"tab1\">\r\n										<p>\r\n											   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients  \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n    <%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n    \r\n										</p>\r\n									</div>\r\n									<div class=\"tab-pane\" id=\"tab2\">\r\n										<p>\r\n											\r\n\r\n\r\n										</p>\r\n									</div>\r\n									<div class=\"tab-pane\" id=\"tab3\">\r\n										<p>\r\n											<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n										</p>\r\n									</div>\r\n								</div>\r\n							</div>\r\n                            \r\n                            \r\n                            \r\n<div style=\"width:100%;border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n </div><br/>\r\n \r\n',NULL,NULL,NULL,'2015-01-01 03:28:48','2015-01-01 03:28:48','',''),(1258,'index_partial',586,3,'',NULL,NULL,NULL,'2015-01-04 02:09:39','2015-01-04 02:09:39','index_partial',''),(1259,'document_name',587,1,'\'operative_note\'',NULL,NULL,NULL,'2015-01-04 02:51:06','2015-01-04 02:51:06',NULL,NULL),(1260,'patient_record',586,2,'<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n<div id=\"patient\">\r\n Loading ...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n\r\n<style>\r\n    .history-link {\r\n        background-color:#eeeeff;\r\n        border:1px solid #ccc;\r\n        width:100px;\r\n        display:inline-block;\r\n        text-align:center;\r\n        line-height: 1.5em;\r\n        border-collapse: collapse;\r\n        padding:5px;\r\n        border-bottom:0px;\r\n        font-size:0.9em;\r\n        border-radius: 5px;\r\n    }\r\n    \r\n    .history-link-active {\r\n        background-color:#9999ff;\r\n    }\r\n    \r\n    .form-link {\r\n        font-size:0.9em;\r\n        background-color:#eeffff;\r\n        border:1px solid #ccc;\r\n        width:100px;\r\n        display:inline-block;\r\n        text-align:center;\r\n        line-height: 1.5em;\r\n        border-collapse: collapse;\r\n        padding:5px;\r\n        border-right:0px;\r\n        \r\n        margin-bottom:5px;\r\n        border-radius: 5px;\r\n    }\r\n    .form-link-active {\r\n        background-color:#99cccc;\r\n    }\r\n    \r\n</style>\r\n\r\n\r\n\r\n<%\r\n\r\n \r\n name = @current_project.name\r\n \r\n aps = patient_module_model.all(:patient_id=>patient.id,:module_name=>/\\\\#{name}#/,:order=>\'date desc\')\r\n \r\n aps_map = {}\r\n form_map = {}\r\n \r\n app_model =  emr_models[:appointment]\r\n \r\n for i in aps\r\n    if i.module_name.index \'#appointment\' and s = i.id.to_s\r\n        \r\n        \r\n        appoint = app_model.find i.module_id\r\n        if appoint\r\n        aps_map[s] = {:i=>i,:a=>appoint,:m=>{},:date=>appoint.date } unless aps_map[s]\r\n        end\r\n        \r\n    end\r\n end\r\n\r\n for i in aps\r\n    if i.parent_id and s = i.parent_id.to_s\r\n        \r\n        aps_map[s][:m][i.module_name] = [] unless aps_map[s][:m][i.module_name]\r\n        aps_map[s][:m][i.module_name] << i\r\n        form_map[i.module_name] = [] unless form_map[i.module_name]\r\n        \r\n        form_map[i.module_name] << i\r\n\r\n    end\r\n end\r\n\r\n\r\n\r\n list = aps_map\r\n\r\n\r\n%>\r\n\r\n\r\n<div class=\"\" style=\"padding:10px;border:0px solid;padding-bottom:0px\">\r\n\r\n<div id=\"history-panel\" style=\"\">\r\n   \r\n   <span class=\"form-panel-list\" style=\"border:0px solid;width:120px;float:left\">\r\n    &nbsp;\r\n   </span>\r\n   \r\n   <% for i in aps_map.values.sort{|a,b| b[:date]<=>a[:date] } %>\r\n   \r\n   <a href=\"javascript:select_app(\'<%=i[:i].id %>\')\"><span id=\"<%=i[:i].id %>\" class=\"history-link\"><%=time_ago_in_words(i[:date])%><br/><%=i[:date].strftime(\'%d-%m-%y\')%></span></a>\r\n\r\n   <% end %> \r\n</div>\r\n\r\n<div style=\"border:0px solid\">\r\n   \r\n   \r\n   <div class=\"form-panel-list\" style=\"border:0px solid;width:110px;display:table-cell;padding-top:5px\">\r\n   \r\n   \r\n  <% for i in form_map.keys.sort\r\n    id = i.split(\'#\')[-1]\r\n    v = form_map[i]\r\n  %>\r\n   \r\n   <a href=\"javascript:select_form(\'<%= id %>\')\"><span id=\"<%=id%>\" class=\"form-link\"><%=id.humanize%><br/>(<%=v.size%>)</span></a>\r\n\r\n   <% end %> \r\n   \r\n    <div class=\"clear\"></div>\r\n   </div>\r\n\r\n   <div class=\"content-panel\" style=\"border:1px solid #ccc;width:100%;display:table-cell;vertical-align:top;padding:10px;width:700px\">\r\n\r\n  <!-- aps_map list -->\r\n  \r\n    <% for i in aps_map.values.sort{|a,b| b[:date]<=>a[:date] } \r\n    \r\n     pm = patient_module_model.where(\'module_id\'=>i[:a].id).first\r\n    \r\n    %>\r\n   \r\n   \r\n   <div id=\"p<%=i[:i].id%>\" class=\"history-panel\">\r\n   \r\n <h4>Visit : <%=i[:date]%></h4><hr/>\r\n   \r\n<table class=\"table table-striped table-bordered\" >\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<% \r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name\r\n%>\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n<% end %>\r\n\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n   \r\n          \r\n   </div>\r\n\r\n\r\n   <% end %>\r\n  \r\n  <!-- form_map list -->\r\n \r\n  <% for i in form_map.keys\r\n    id = i.split(\'#\')[-1]\r\n    v = form_map[i]\r\n  %>\r\n   \r\n<div id=\"p<%=id%>\" class=\"form-panel\">\r\n\r\n<h4><%=id.humanize%> : </h4><hr/>\r\n\r\n  \r\n    \r\n<table class=\"table table-striped table-bordered\" >\r\n<thead>\r\n<tr><th></th><th>Date</th><th></th></tr>\r\n</thead>\r\n<%  v.each_with_index do |i,index|\r\n    # id = i.split(\'#\')[-1]\r\n    # v = form_map[i]\r\n    pm = patient_module_model.find(i.parent_id)\r\n    ap = app_model.find(pm.module_id)\r\n%>\r\n<tr>\r\n\r\n<td><%= index+1  %>.</td>\r\n\r\n<td><%= ap.date  %></td>\r\n\r\n<td>\r\n<%= link_to \"\\\\#{ap.date.strftime(\"%d-%m-%Y\") if ap.date} - \\\\#{i.ref_number}\", \"../\\\\#{id.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{id.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n   \r\n</td>\r\n    \r\n</tr>\r\n<% end %>\r\n</table>\r\n\r\n   \r\n   </div>\r\n\r\n   <% end %> \r\n  \r\n\r\n   </div>\r\n    \r\n    \r\n \r\n</div>\r\n</div>\r\n\r\n\r\n<br/>\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n\r\n    \r\n    \r\n</div> <!--close content-->\r\n</div>\r\n</div>\r\n</div> <!--close rw-fluid-->\r\n\r\n\r\n\r\n<script>\r\n    \r\n    function select_app(id){\r\n        // alert(\"select_app \"+id)\r\n        $(\'.history-link\').removeClass(\'history-link-active\')\r\n        $(\'.form-link\').removeClass(\'form-link-active\')\r\n        $(\'.history-panel\').hide()\r\n        $(\'.form-panel\').hide()\r\n        \r\n        $(\'#\'+id).addClass(\'history-link-active\')\r\n        $(\'#p\'+id).show()\r\n        \r\n    }\r\n    \r\n    <% if pm %>\r\n    \r\n    select_app(\'<%=pm.id%>\')\r\n    \r\n    <% end %>\r\n    \r\n        \r\n    function select_form(id){\r\n        $(\'.history-link\').removeClass(\'history-link-active\')\r\n        $(\'.form-link\').removeClass(\'form-link-active\')\r\n        $(\'.history-panel\').hide()\r\n        $(\'.form-panel\').hide()\r\n\r\n\r\n        $(\'#\'+id).addClass(\'form-link-active\')\r\n        $(\'#p\'+id).show()       \r\n        //  alert(\"select_form \"+id)\r\n    }\r\n    \r\n    \r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<% Time.zone =  get_setting \'time_zone\' %>\r\n\r\n\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\" style=\"display:none\" >\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %