     lc =  $(\'#data-lc\').val()\r\n            tc =  $(\'#data-tc\').val()\r\n            rc =  $(\'#data-rc\').val()\r\n            \r\n            if(lc==\'\')lc=\'0\'\r\n            if(tc==\'\')tc=\'0\'\r\n            if(rc==\'\')rc=\'0\'\r\n            \r\n            lc =  parseInt(lc);\r\n            tc =  parseInt(tc);\r\n            rc =  parseInt(rc);\r\n            s = lc+tc+rc;\r\n            \r\n            $(\'#data-bbps\').val(s);\r\n             cupdate();\r\n             $(\'#data-bowel_preperation_finding\').val(\'1\');\r\n             \r\n            v = {0:\'3\',1:\'3\',2:\'3\',3:\'2\',4:\'2\',5:\'2\',6:\'2\',7:\'1\',8:\'1\',9:\'0\'}\r\n            va = v[s];\r\n            $(\'#update_bowel_preperation_finding_item_\'+va).attr(\'checked\', \'checked\');\r\n            \r\n            update_bowel_preperation_finding_func();\r\n             \r\n            \r\n            \r\n       }\r\n       \r\n       $(\'#data-lc\').change(calculate);\r\n        \r\n        $(\'#data-tc\').change(calculate);\r\n        \r\n        $(\'#data-rc\').change(calculate);\r\n        \r\n        function cupdate(){\r\n            $(\'#bbps-div\').html($(\'#data-bbps\').val())\r\n        }\r\n        \r\n        $(\'#data-bbps\').change(cupdate);    \r\n        $(document).ready(function(){\r\n      $(\'#bbps-div\').html($(\'#data-bbps\').val())\r\n      });\r\n    \r\n      \r\n    });\r\n    \r\n    $(\'#bowel_preperation_finding\').hide();\r\n    \r\n       }\r\n</script>\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-01-11 17:29:19','2015-01-11 17:29:19','display_script',''),(1264,'document_name',589,1,'\'colono_finding_3\'',NULL,NULL,NULL,'2015-01-12 17:56:58','2015-01-12 17:56:58',NULL,NULL),(1265,'document_name',590,1,'\'colono_finding_6\'',NULL,NULL,NULL,'2015-01-12 18:08:19','2015-01-12 18:08:19',NULL,NULL),(1267,'form',591,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project = 