:36',NULL,NULL),(1275,'document_name',597,1,'\'pushenteroscopy_finding_6\'',NULL,NULL,NULL,'2015-01-31 15:21:42','2015-01-31 15:21:42',NULL,NULL),(1276,'document_name',598,1,'\'pushenteroscopy_finding_7\'',NULL,NULL,NULL,'2015-01-31 15:22:42','2015-01-31 15:22:42',NULL,NULL),(1280,'get_today_patient_by_hn',574,3,'<%= render :inline=>this.init%>\r\n<%  \r\n    date = Time.now\r\n    hn = \'x\'\r\n    if not params[:hn].nil? \r\n        hn = params[:hn]\r\n        \r\n        # if hn.include? \'/\' \r\n        #     hn.sub! \'/\', \'\'\r\n        # end\r\n        hn.sub! \'/\', \'\' if hn.include? \'/\'\r\n        \r\n        models = get_model\r\n        \r\n        mtoday = @patient_module_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day,:module_name=>\"\\\\#{@current_project.name}#appointment\") \r\n        \r\n        mtoday = models[:appointment].where(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day).to_a \r\n     \r\n        mtoday.collect!{|i| @patient_module_model.where(:module_id=>i.id).first }.compact!\r\n    \r\n        objs = {}\r\n        # list = mtoday.collect{|i| \r\n        #     p = @patient_model.find(i.patient_id)\r\n        #     if p.hn == hn\r\n        #         ap = @models[:appointment].find(i.module_id)\r\n        #         {:admit_id=>ap.id,:patient_name=>\"\\\\#{p.first_name} \\\\#{p.last_name}\",:patient_hn=>p.hn,:patient=>p, :appointment=>ap} \r\n        #         # break\r\n        #     end\r\n        # }\r\n        \r\n        for i in mtoday do\r\n            p = @patient_model.find(i.patient_id)\r\n            \r\n            p_hn = p.hn\r\n\r\n            p_hn = p.hn.sub \'/\', \'\' if p.hn.include? \'/\'\r\n\r\n            # check patient_hn and param_hn\r\n            if p_hn == hn\r\n                ap = @models[:appointment].find(i.module_id)\r\n                \r\n                services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\')\r\n    \r\n                admit_id = ap.id\r\n                \r\n                mapp = @patient_module_model.where(:module_id=>admit_id).first\r\n                patient = @patient_model.find(mapp.patient_id) if mapp\r\n                \r\n                if mapp and patient\r\n                \r\n                \r\n                list = services.collect{|i|\r\n                \r\n                doc =  @current_project.get_document i.name\r\n                model = @models[doc.name.to_sym]\r\n                \r\n                mm = @patient_module_model.where(:parent_id=>mapp.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\").first\r\n                \r\n                if mm\r\n                    record = model.find(mm.module_id)\r\n                else\r\n                    mm = @patient_module_model.new :module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\", :parent_id=>mapp.id\r\n                    record = model.new\r\n                end\r\n                \r\n                \r\n                \r\n                img_f = nil\r\n                \r\n                    ohn = patient.hn\r\n                    hn = patient.hn.split(\"/\").join(\"-\")\r\n                    \r\n                        \r\n                    \r\n                    \r\n                    \r\n                    record_id = mm.id\r\n                    \r\n                    imgs = nil        \r\n                    for j in doc.fields \r\n                        if j.field_type == \'image_camera\'\r\n                            img_f = j \r\n                            snap = URI.encode(\"/esm_image/\\\\#{doc.id}/snap?field_id=\\\\#{j.id}&p_id=\\\\#{@current_project.id}&path=esm/\\\\#{@current_project.esm.name}/\\\\#{@current_project.name}/\\\\#{hn}/\\\\#{doc.name}/\\\\#{Time.now.strftime(\'%Y-%m-%d\')}-\\\\#{record_id}/image&ref=\\\\#{ohn}\")\r\n                            # admit_id, doc_id, record_id\r\n                            attachment = URI.encode(\"/esm/\\\\#{@current_project.esm.name}/\\\\#{@current_project.name}/Api/attach_image_by_admit_id?admit_id=\\\\#{admit_id}&doc_id=\\\\#{doc.name}&record_id=\\\\#{record_id}&f_id=\\\\#{j.column_name}\")\r\n                            \r\n                            imgs = {:name=>doc.name,:title=>doc.title, :snap_url=>snap,:attach_url=>attachment}    \r\n                        end\r\n                    end\r\n                \r\n                \r\n                imgs if img_f\r\n                \r\n                }    \r\n                \r\n                list.compact!\r\n                \r\n                end\r\n                \r\n                objs = {:admit_id=>ap.id,:patient_name=>\"\\\\#{p.first_name} \\\\#{p.last_name}\",:patient_hn=>p.hn,:patient=>p,:appointed=>@models[:procedure].find(ap.procedure).name,:status=>ap.status   , :appointment=>ap, :capture_url=>list} \r\n                break\r\n            end \r\n        end\r\n        \r\n        result = {:result=>\'200 OK\',:return=>objs,:timestamp=>Time.now}\r\n    elsif\r\n        result = {:result=>\'404 Not Found\',:return=>nil,:timestamp=>Time.now}\r\n    end\r\n    \r\n%>\r\n<%=result.to_json.html_safe%>\r\n',NULL,NULL,NULL,'2015-02-03 13:43:51','2015-02-03 13:43:51','get_today_patient_by_hn','*'),(1282,'document_name',599,1,'\'hip1\'',NULL,NULL,NULL,'2015-02-06 07:11:03','2015-02-06 07:11:03',NULL,NULL),(1283,'display',599,3,'<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n\r\n <div style=\"padding:5px;width:720px; margin-left:auto; margin-right:auto\" >\r\n\r\nRef : <%= @patient_module.ref_number %> \r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n<p style=\"width:720px; margin-left:auto; margin-right:auto; font-weight:bold\">HN : <%= @patient.hn %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Name : <%= @patient.first_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Surname : <%= @patient.last_name %></p>\r\n<hr /><br />\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>',NULL,NULL,NULL,'2015-02-06 07:41:17','2015-02-06 07:41:17','display',''),(1284,'document_name',600,1,'\'knee1\'',NULL,NULL,NULL,'2015-02-08 13:05:07','2015-02-08 13:05:07',NULL,NULL),(1285,'print_bk',599,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    tex