Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n		\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n		    <title><%=title%></title>\r\n\r\n				<script>\r\n					$(document).ready(function() {\r\n						//* show all elements & remove preloader\r\n						// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n						 // $(\"html\").removeClass(\"js\");\r\n					});\r\n				</script>\r\n		\r\n				 <style>\r\n    .w-box-content.cnt_a {background: #fff;}\r\n    .k-grid table {font-size: 1em;}\r\n.k-calendar .k-content {font-size: 1em;padding-top:5px;}\r\n.k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\nheight: 25px;}\r\n.field-data {\r\nwidth: 220px;}\r\n\r\ninput{\r\n    height:25px;\r\n}\r\n.sidebar_hidden { background: url(\'/esm/thks/www/content/bg1.jpg\') no-repeat center center fixed; \r\n  -webkit-background-size: cover;\r\n  -moz-background-size: cover;\r\n  -o-background-size: cover;\r\n  background-size: cover;}\r\nbody { \r\nbackground: url(\'/esm/thks/www/content/bg1.jpg\') no-repeat center center fixed; \r\n  -webkit-background-size: cover;\r\n  -moz-background-size: cover;\r\n  -o-background-size: cover;\r\n  background-size: cover;\r\n  padding:20px;\r\n    font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\r\n    /*font-weight: lighter;*/\r\n    /*font-size: 1em;*/\r\n}\r\n</style>\r\n		\r\n		\r\n    </head>\r\n    <body>\r\n	<!--background:url(\'/esm/ehr/my_module/surgeons-bg.jpg\') -->\r\n<a href=\"../../www/Home/index\"><img src=\"/esm/thks/www/content/logolong.png\" width=\"200px\" style=\"padding-bottom: 10px\" ></a>\r\n<span style=\"float:right;color:#efefef;font-size:1.2em\" >\r\n    <%= @current_user.login %> | <%=link_to \'Logout\',\'/user/logout\' %>\r\n</span>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n					</div>\r\n</hr>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\" style=\"padding:0px;\">\r\n\r\n				   <%= yield %><%= yield :content%>\r\n                \r\n                </div>\r\n            </div>\r\n     \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n     		<div id=\"context-menu\" class=\"accordion\">\r\n             <% #render :partial=>\'/layouts/context_menu\'%>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n			$(\'#search-field\').focus()\r\n		</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-03-08 12:04:53','2015-03-08 12:04:53','',''),(1335,'create',627,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Create Patient</h3>\r\n<!--<strong>Create Patient</strong>-->\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n<div >\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\" >\r\n\r\n<%= render :inline=>this.init %>\r\n<% # params.inspect %>\r\n<%\r\n\r\n    msg = nil\r\n    err = false\r\n\r\n    if request.post?\r\n      \r\n        p = params[:record]\r\n        p[:hn] = p[:hn].upcase\r\n        return_url = params[:return]\r\n        date = Time.now\r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        \r\n        # next_service = \"../Patient/create_test?return=\\\\#{return_url}&\".html_safe\r\n        next_service = \"../Home/index\"\r\n        patient = false\r\n        patient = @patient_model.where(:hn=>p[:hn], :hospital_name=>p[:hospital_name]).first\r\n        if  patient\r\n            msg = \"Duplicate HN and Hospital in database\"\r\n            # next_service += URI.escape(params.collect{|k,v| \"\\\\#{k}=\\\\#{v}\"}.join(\'&\')).html_safe\r\n            err = true\r\n            next_service = \"../Home/patient_record?id=\\\\#{patient.id}\"\r\n        else\r\n            # msg = \"Success\"\r\n            # next_service = \"../Setting/index\"\r\n            patient = @patient_model.create p\r\n            # if params[:record][:height] != \"\" and params[:record][:weight] != \"\"\r\n                # patient.update_attributes :height=>params[:record][:height], :weight=>params[:record][:weight], :bmi=>params[:record][:bmi]\r\n            # end\r\n            next_service = \'../Home/patient_record?id=\' + patient.id\r\n          \r\n            if params[:record][:provider]\r\n                m_pm_record = @module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>params[:record][:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>params[:record][:provider]\r\n            end\r\n            \r\n            msg = \"Patient created\"\r\n        end\r\n      \r\n    #   return_url += \'&obj_id=\'+patient.id.to_s\r\n      %>\r\n      <%#params.inspect %>\r\n      <div class=\"alert <%= err ? \"alert-error\" : \"alert-success\" %>\"><%= msg %></div>\r\n      <% if false %>\r\n      <pre><%# patient.inspect %></pre>\r\n      <pre><%# params.inspect %></pre>\r\n      <pre><%#  params[:record][:height].empty? %></pre>\r\n      <% end %>\r\n      <meta http-equiv=\"refresh\" content=\"0; url=<%=next_service%>\" />\r\n      <%\r\n    else\r\n%>\r\n<%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%= f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n<%= f.hidden_field :date, :value=>params[:data][:date] %>\r\n<div class=\"w-box\">\r\n<!--<div id=\"132-F1376173358\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">-->\r\n<div class=\"form-horizontal well\">\r\n<!--<b>Personal Information</b>-->\r\n<p class=\"f_legend\">Patient Information</p>\r\n<!--</div>-->\r\n\r\n<div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;margin: 0 0.5em 0.5em 0;float:left;width:140px;min-height:30px;\">\r\n<!--<span class=\"\"><label>Hospital Number <span class=\"f_req\">*</span>  : </label></span>	-->\r\n<!--<input type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"><span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[hn]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n    <span class=\"\"><label>Hospital Number (HN) : </label></span>\r\n    <input type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:140px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n<%\r\n    model = get_model\r\n    \r\n    r_prov = model[:provider].find(params[:data][:provider])\r\n    main_hospital = r_prov[:main_hospital] if r_prov[:main_hospital]\r\n    part_time_hospital = r_prov[:part_time_hospital].split(\'|\') if r_prov[:part_time_hospital]\r\n    \r\n    main_hospital = \'\' unless main_hospital\r\n    part_time_hospital = [] unless part_time_hospital\r\n    \r\n    list_hospital = []\r\n    if main_hospital != \'\' and !main_hospital.nil?\r\n        list_hospital.push(main_hospital)\r\n    end\r\n    if !part_time_hospital.empty?\r\n        list_hospital += part_time_hospital\r\n    end\r\n    \r\n    a_hosp = model[:hospital].all.collect{|i| {:text=>i[:hospital_name_thai], :value=>i.id.to_s}}\r\n%>\r\n<div id=\"hospital_name\" class=\"  portlet \" style=\"border:0px solid blue;width:260px;margin: 0 0 0 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Hospital Name : </label></span>	\r\n    <input type=\"text\" name=\"record[hospital_name]\" id=\"data-hospital_name\" size=\"29\" style=\"margin-top:-2px;vertical-align:text-top;width:100%;display:blockwidth:140px\" class=\"k-textbox k-textbox-txt\">\r\n<script>\r\n    var ds_hosp = <%= a_hosp.to_json.html_safe %>\r\n    $(document).ready(function() {\r\n            $(\"#data-hospital_name\").kendoComboBox({\r\n                dataTextField: \"text\",\r\n                dataValueField: \"value\",\r\n                filter: \"contains\",\r\n                dataSource: ds_hosp,\r\n                change: function(e) {\r\n                    var widget = e.sender;\r\n        \r\n                    if (widget.value() && widget.select() === -1) {\r\n                      //custom has been selected\r\n                      widget.value(\"\"); //reset widget\r\n                    }\r\n                }\r\n            });\r\n            $(\'input[name=\"record[hospital_name]_input\"]\').css(\'height\', \'\');\r\n<%\r\n    if main_hospital\r\n%>\r\n            var cb = $(\"#data-hospital_name\").data(\"kendoComboBox\");\r\n            cb.value(\'<%= main_hospital %>\');\r\n<%\r\n    end\r\n%>\r\n    });\r\n</script>    \r\n    <!--\r\n    <select name=\"record[hospital_name]\" id=\"data-hospital_name\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n<%\r\n    @map_hospital.each do |k,v|\r\n        sel = \"\"\r\n        if k == main_hospital\r\n            sel = \' selected=\"selected\"\'\r\n        end\r\n        if list_hospital.include? k or list_hospital.empty?\r\n%>\r\n        <option value=\"<%=k%>\"<%=sel.html_safe%>><%=v%></option>\r\n<%\r\n        end\r\n    end\r\n%>\r\n    </select>\r\n    -->\r\n</div>\r\n\r\n<div class=\"row-fluid\"></div>\r\n\r\n<div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;margin: 0 0.5em 0.5em 0;float:left;width:240px;min-height:30px;\">\r\n    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n    <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Prefix name : </label></span>	\r\n        <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                    autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;\" \r\n                    aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                    aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                    <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                </span>\r\n            </span>\r\n            <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n        </span>\r\n        <!--\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"record[prefix_name]\" id=\"data-prefix_namez\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n                <option value=\"นาย\">นาย</option>\r\n                <option value=\"นาง\">นาง</option>\r\n                <option value=\"นางสาว\">นางสาว</option>\r\n                <option value=\"ด.ช.\">ด.ช.</option>\r\n                <option value=\"ด.ญ.\">ด.ญ.</option>\r\n            </select>\r\n        </div>\r\n        -->\r\n        <!--<input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n    </div>\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n</script>\r\n\r\n<div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block;margin-top:10px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\">\r\n    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n</div>\r\n\r\n<div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block;margin-top:10px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\">\r\n    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n</div>\r\n\r\n<div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Gender : </label></span>	\r\n    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n    \r\n        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb;margin-top:3px\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n        <option value=\"1\">Male</option>\r\n        <option value=\"2\">Female</option>\r\n        <option value=\"0\">NA</option>\r\n        </select>\r\n    	\r\n    \r\n    </div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<% if false %>\r\n<div id=\"height\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\