on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n<script>\r\n	$(\"#data-birth_date\").kendoDatePicker({\r\n		value: \'<%= Time.now.strftime(\'%d/%m/%Y\')%>\',\r\n	});\r\n</script>\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function data_demo_update(){\r\n		\r\n		// alert(\'call F9784231518 data-demo\')\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    $(\'#data-prefix_name\').change(update_gender);\r\n</script>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<%= hidden_field_tag :return, params[:return] %>\r\n<%= f.hidden_field :created_by, :value=>@current_user.login %>\r\n\r\n<%= f.submit \'Submit\', :class=>\'btn btn-success\' %>\r\n<%= link_to \'Cancel\', \'../Home/index\', :class=>\'btn\' %>\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n<script>\r\n    function bmi_update() {\r\n        // txt = $(this).val();\r\n        // num = isNaN(parseInt(txt)) ? 0 : parseInt(txt);\r\n        \r\n        h = isNaN(parseFloat($(\'#data-height\').val())) ? 0 : parseFloat($(\'#data-height\').val());\r\n        w = isNaN(parseFloat($(\'#data-weight\').val())) ? 0 : parseFloat($(\'#data-weight\').val());\r\n        \r\n        h = h/100;\r\n        bmi = 0\r\n        if (h != 0) {\r\n            bmi = w / (h * h)\r\n            $(\'#data-bmi\').val(bmi.toFixed(2));\r\n            // console.log(\'BMI = \' + bmi)\r\n        }\r\n        // console.log(\'bmi_update h(\' + h + \'), w(\' + w + \')\');\r\n    }\r\n\r\n    $(document).ready(function(){\r\n        // console.log(\'ready\');\r\n        \r\n        $(\'#data-bmi\').val(\'0.00\');\r\n        \r\n        $(\'#data-height\').change(bmi_update);\r\n        $(\'#data-weight\').change(bmi_update);\r\n        // console.log(\'finish\');\r\n    });\r\n</script>',NULL,NULL,NULL,'2015-03-08 13:03:14','2015-03-08 13:03:14','create',''),(1336,'create',628,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n\r\n\r\n\r\n    date = Time.now.strftime(\"%d/%m/%Y\")\r\n    time = Time.now.strftime(\"%H:%M\")\r\n    \r\n    # date = params[:date] if params[:date]\r\n    # time = params[:time] if params[:time]\r\n    \r\n%>\r\n<%= params[:date] %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n    if request.post?   \r\n\r\n        doc = get_document this.document_name\r\n        record = doc.record_create(model,params)\r\n        m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n        flash[:notice]=\'New record has been created\'\r\n        \r\n        models = get_model\r\n        \r\n        procedure = (models[:procedure]).find(record.procedure)\r\n    \r\n        if procedure\r\n    \r\n            proc_record = models[procedure.code.to_sym].create \r\n            m = @module_model.create :patient_id=>params[:patient_id],:module_id=>proc_record.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{procedure.code}\",:date=>params[:date],:time=>params[:time],:parent_id=>m.id,:ref_number=>params[:ref_number]\r\n    \r\n        end\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\nwindow.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\n// window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% elsif params[:record][:id] %>\r\nwindow.location = \"../Home/patient_record?id=<%= params[:record][:id] %>\"\r\n<% else %>\r\nwindow.location = \"../Home/index\"\r\n<% end %>\r\n\r\n// window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n        record = model.new params[:data] \r\n    else\r\n        record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\'), :html=>{:id=>\'app_create\'} do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><