number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',date  ,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',time,:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= date %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\n\r\n   function newPatient(){\r\n    alert(\'jdiofj\')\r\n    $.ajax({\r\n		  url: \"../Patient/create?return=<%=params[:return]%>\",\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n   }\r\n\r\nfunction doSearch(){\r\n    	$(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n    \r\n    \r\n    \r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2015-03-11 11:49:28','2015-03-11 11:49:28','create',''),(1354,'index',641,2,'...\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Solution\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE</b></center><br/>\r\n    <%= render :inline=>this.module %>\r\n</div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-03-11 14:41:35','2015-03-11 14:41:35','',''),(1356,'layout',641,4,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n		\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n		    <title><%=title%></title>\r\n\r\n				<script>\r\n					$(document).ready(function() {\r\n						//* show all elements & remove preloader\r\n						// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n						 // $(\"html\").removeClass(\"js\");\r\n					});\r\n				</script>\r\n		\r\n				 <style>\r\n    .w-box-content.cnt_a {background: #fff;}\r\n    .k-grid table {font-size: 1em;}\r\n.k-calendar .k-content {font-size: 1em;padding-top:5px;}\r\n.k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\nheight: 25px;}\r\n.field-data {\r\nwidth: 220px;}\r\n\r\ninput{\r\n    height:25px;\r\n}\r\n</style>\r\n		\r\n		\r\n    </head>\r\n    <body style=\"background:url(\'/esm/ehr/my_module/surgeons-bg.jpg\');padding:10px;font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;  font-weight: lighter;\">\r\n	\r\n<a href=\"../../www/Home/index\"><img src=\"/esm/ehr/my_module/lifescope.png\" width=\"200px\"></a>\r\n<span style=\"float:right;color:#efefef;font-size:1.2em\" >\r\n<%\r\n    cur_user = get_model[:user].where(:login=>@current_user.login.to_s).first\r\n    usr_name = !cur_user.nil? ? \"\\\\#{cur_user[:name]} (\\\\#{@current_user.login})\" : @current_user.login\r\n%>\r\n    <%= usr_name %> | <%=link_to \'Logout\',\'/user/logout\' %>\r\n</span>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n					</div>\r\n</hr>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\" style=\"padding:0px;\">\r\n\r\n				   <%= yield %><%= yield :content%>\r\n                \r\n                </div>\r\n            </div>\r\n     \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n     		<div id=\"context-menu\" class=\"accordion\">\r\n             <%= render :partial=>\'/layouts/context_menu\'%>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n			$(\'#search-field\').focus()\r\n		</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-03-11 14:46:50','2015-03-11 14:46:50','',''),(1357,'layout',622,4,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n		\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n		    <title><%=title%></title>\r\n\r\n				<script>\r\n					$(document).ready(function() {\r\n						//* show all elements & remove preloader\r\n						// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n						 // $(\"html\").removeClass(\"js\");\r\n					});\r\n				</script>\r\n		\r\n				 <style>\r\n    .w-box-content.cnt_a {background: #fff;}\r\n    .k-grid table {font-size: 1em;}\r\n.k-calendar .k-content {font-size: 1em;padding-top:5px;}\r\n.k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\nheight: 18px;}\r\n.field-data {\r\nwidth: 220px;}\r\n\r\ninput{\r\n    height:18px;\r\n}\r\n</style>\r\n		\r\n		\r\n    </head>\r\n    <body style=\"background:url(\'/esm/ehr/my_module/surgeons-bg.jpg\');padding:10px\">\r\n<a href=\"../../www/Home/index\">	\r\n<img src=\"/esm/lifescope_master/endo/content/logosuperscope.png\" width=\"200px\"></a>\r\n<span style=\"float:right;color:#efefef;font-size:1.2em\" >\r\n<%\r\n    cur_user = get_model[:provider].where(:login=>@current_user.login.to_s).first\r\n    usr_name = !cur_user.nil? ? \"\\\\#{cur_user[:name]} (\\\\#{@current_user.login})\" : @current_user.login\r\n%>\r\n    <%= usr_name %> | <%=link_to \'Logout\',\'/user/logout\' %>\r\n</span>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n						<div class=\"span12\">\r\n							<ul class=\"dshb_icoNav tac\">\r\n								<li><a href=\"../Home/index\" style=\"background-image: url(/gebo/img/gCons/home.png)\"> Home</a></li>\r\n								<li><a href=\"../Appointment/index\" style=\"background-image: url(/gebo/img/gCons/calendar.png)\">Calendar</a></li>\r\n								<li><%= link_to \'Reports\',\"../Report/case_reports\",:style=>\'background-image: url(/gebo/img/gCons/bar-chart.png)\' %></li>\r\n								<li><a href=\"../Setting/index\" style=\"background-image: url(/gebo/img/gCons/configuration02.png)\">Settings</a></li>\r\n				<li><a href=\"../Help/index\" style=\"background-image: url(/gebo/img/gCons/happy-face.png)\">Help</a></li>\r\n						 </ul>		\r\n			\r\n						</div>\r\n					</div>\r\n</hr>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\" style=\"padding:0px;\">\r\n<% if params[:service] == \'Report\'  %>\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Report</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\" style=\"padding:10px\">\r\n                <%= yield %><%= yield :content%>\r\n            </div>\r\n        </div>\r\n<% else %>\r\n				   <%= yield %><%= yield :content%>\r\n<% end %>\r\n    </div>\r\n</div>\r\n     \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n     		<div id=\"context-menu\" class=\"accordion\">\r\n             <%= render :partial=>\'/layouts/context_menu\'%>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n			$(\'#search-field\').focus()\r\n		</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-03-11 15:23:21','2015-03-11 15:23:21','',''),(1358,'login',641,4,'<html>\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n\r\n <!-- Bootstrap framework -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap.min.css\" />\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap-responsive.min.css\" />\r\n        <!-- theme color-->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n        <!-- tooltip -->    \r\n			<link rel=\"stylesheet\" href=\"/gebo/lib/qtip2/jquery.qtip.min.css\" />\r\n        <!-- main styles -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/style.css\" />\r\n<style>\r\ninput, textarea, select, .uneditable-input { height:30px;}\r\n.login_page .cnt_b { padding:15px 0}\r\n</style>            \r\n</head>\r\n<body class=\"login_page\" style=\"background:url(/esm/ehr/my_module/surgeons-bg.jpg) center no-repeat;\r\nbackground-size: cover;\">\r\n<script src=\"/gebo/js/jquery.min.js\"></script>\r\n<script src=\"/gebo/js/jquery.actual.min.js\"></script>\r\n<script src=\"/gebo/lib/validation/jquery.validate.min.js\"></script>\r\n<script src=\"/gebo/bootstrap/js/bootstrap.min.js\"></script>\r\n<%\r\n	p = {}\r\n	if @current_project \r\n	tp = @current_project.get_params if @current_project \r\n	p = tp if tp\r\n	end\r\n	title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"ESM:Innovation as a Service\"\r\n	bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#eee\"\r\n	logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n%>\r\n\r\n<%\r\n    user = \'\'\r\n	user = params[:user][:login] if params[:user]\r\n%>\r\n<%= form_for :user, :action=>\'login\' do|form|%>\r\n            <center><a href=\"/\">\r\n            <img src=\"/esm/ehr/my_module/lifescope.png\" width=\"260\">\r\n            </a><br/><br/>\r\n            </center>\r\n	<div class=\"login_box\" style=\"height:220px;top:0;bottom: 0;left: 0;right: 0;margin: auto;font-size:1.5em\">\r\n		\r\n		<form action=\"dashboard.html\" method=\"post\" id=\"login_form\">\r\n		\r\n			<% if flash[:error] %>\r\n			<div class=\"alert alert-info alert-login\">\r\n				<%= flash[:error] %>\r\n			</div>\r\n			<% else %>\r\n			<div class=\"alert alert-info alert-login\">\r\n				Please login to continue \r\n			</div>\r\n			<% end %>\r\n			\r\n			\r\n	   	\r\n\r\n			\r\n			<div class=\"cnt_b\">\r\n			\r\n					\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\" style=\"height:20px;padding:5px\"><i class=\"icon-user\"></i></span>\r\n						<%= form.text_field \"login\",:id=>\'user_login\',:placeholder=>\"Email or Login ID\",\'data-icon\'=>\"user\",:value=>user%>\r\n					   \r\n					</div>\r\n				</div>\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\" style=\"height:20px;padding:5px\"><i class=\"icon-lock\" ></i></span>\r\n						<%= form.password_field \"password\", :id=>\'user_password\',:placeholder=>\"Password\",\'data-icon\'=>\"closed-lock\"%>\r\n						\r\n					</div>\r\n				</div>\r\n					<%  unless @current_solution %>\r\n				<span id=\"solution_id_toggle\"><center><a href=\"javascript:$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\">...</a></center></span>	\r\n				<div class=\"formRow\" id=\"solution_id\" style=\"display:none\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-book\"></i></span>\r\n						<%= text_field_tag \"user[esm]\",cookies[:esm],:id=>\'esm\',:placeholder=>\"Solution ID\",\'data-icon\'=>\"settings\"%>\r\n					</div>\r\n				</div>\r\n				<script>\r\n				    $(document).ready(function(){\r\n				<% if cookies[:esm] %>\r\n					$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\r\n				<%  end %>\r\n			  });\r\n				</script>\r\n				\r\n					<% else %>\r\n						<%= form.hidden_field \"esm\", :value=> @current_solution.name %>\r\n						<%= form.hidden_field \"project_id\", :value=> @current_project.id if @current_project%>\r\n					<% end %>\r\n					\r\n					\r\n				<div class=\"formRow clearfix\">\r\n					<label class=\"checkbox\"><input id=\"ck\" name=\'remember\' type=\"checkbox\" /> Remember me</label>\r\n				</div>\r\n			</div>\r\n			<div class=\"btm_b clearfix\" >\r\n				<button class=\"btn btn-inverse pull-right\" type=\"submit\">Sign In</button>\r\n				\r\n				<span class=\"link_reg\"><a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#terms\">Disclaimer</a></span>\r\n				\r\n			</div>  \r\n		</form>\r\n		\r\n		\r\n		\r\n		<div id=\"terms\" class=\"modal hide fade\">\r\n				<div class=\"modal-header\">\r\n					<a class=\"close\" data-dismiss=\"modal\">×</a>\r\n					<h3>Disclaimer</h3>\r\n				</div>\r\n				<div class=\"modal-body\">\r\n					<p>\r\n					ระบบนี้ออกแบบเพื่อใช้ในการเก็บข้อมูลทางการแพทย์เท่านั้น ห้ามนำข้อมูลในเว็บไซด์นี้ไปเผยแผ่หรือทำซ้ำโดยเด็ดขาด\r\n					</p>\r\n				</div>\r\n				<div class=\"modal-footer\">\r\n					<a data-dismiss=\"modal\" class=\"btn\" href=\"#\">Close</a>\r\n				</div>\r\n			</div>\r\n		\r\n	</div>\r\n	\r\n	<div class=\"links_b links_btm clearfix\" >\r\n	\r\n	\r\n	</div>\r\n		\r\n	</div>  \r\n   <% end %>\r\n\r\n    <script>\r\n        $(document).ready(function(){\r\n            \r\n			//* boxes animation\r\n			form_wrapper = $(\'.login_box\');\r\n            $(\'.linkform a,.link_reg a\').on(\'click\',function(e){\r\n				var target	= $(this).attr(\'href\'),\r\n					target_height = $(target).actual(\'height\');\r\n				$(form_wrapper).css({\r\n					\'height\'		: form_wrapper.height()\r\n				});	\r\n				$(form_wrapper.find(\'form:visible\')).fadeOut(400,function(){\r\n					form_wrapper.stop().animate({\r\n                        height	: target_height\r\n                    },500,function(){\r\n                        $(target).fadeIn(400);\r\n                        $(\'.links_btm .linkform\').toggle();\r\n						$(form_wrapper).css({\r\n							\'height\'		: \'\'\r\n						});	\r\n                    });\r\n				});\r\n				e.preventDefault();\r\n			});\r\n			\r\n			//* validation\r\n			$(\'#login_form\').validate({\r\n				onkeyup: false,\r\n				errorClass: \'error\',\r\n				validClass: \'valid\',\r\n				rules: {\r\n					username: { required: true, minlength: 3 },\r\n					password: { required: true, minlength: 3 }\r\n				},\r\n				highlight: function(element) {\r\n					$(element).closest(\'div\').addClass(\"f_error\");\r\n				},\r\n				unhighlight: function(element) {\r\n					$(element).closest(\'div\').removeClass(\"f_error\");\r\n				},\r\n				errorPlacement: function(error, element) {\r\n					$(element).closest(\'div\').append(error);\r\n				}\r\n			});\r\n        });\r\n    </script>\r\n\r\n\r\n		<script type=\"text/javascript\">\r\n	\r\n		try{document.getElementById(\'user_login\').focus();}catch(e){}\r\n		</script>\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n\r\n    \r\n\r\n\r\n',NULL,NULL,NULL,'2015-03-11 17:08:22','2015-03-11 17:08:22','login',''),(1359,'document_name',642,1,'\'fiboscan\'',NULL,NULL,NULL,'2015-03-14 03:15:02','2015-03-14 03:15:02',NULL,NULL),(1360,'document_name',643,1,'\'fibrosis\'',NULL,NULL,NULL,'2015-03-14 03:17:15','2015-03-14 03:17:15',NULL,NULL),(1361,'document_name',644,1,'\'fibroscan\'',NULL,NULL,NULL,'2015-03-14 03:18:39','2015-03-14 03:18:39',NULL,NULL),(1362,'config',622,1,'[\r\n{:name=>\'Operations\',:open=>true,:actions=>[\r\n{:name=>\'Gastroscopy\',:service=>\'gastro\',:link=>\'../Gastro/index\',:remote=>false},\r\n{:name=>\'PushEnterosocpy\',:service=>\'push_enteroscopy\',:link=>\'../PushEnterosocpy/index\',:remote=>false},\r\n{:name=>\'DBE\',:service=>\'dbe\',:link=>\'../Dbe/index\',:remote=>false},\r\n{:name=>\'Colonoscopy\',:service=>\'colono\',:link=>\'../Colono/index\',:remote=>false},\r\n{:name=>\'Sigmoid\',:service=>\'sigmoid\',:link=>\'../Sigmoid/index\',:remote=>false},\r\n{:name=>\'ERCP\',:service=>\'ercp\',:link=>\'../Ercp/index\',:remote=>false},\r\n{:name=>\'EUS\',:service=>\'eus\',:link=>\'../Eus/index\',:remote=>false},\r\n{:name=>\'Fibroscan\',:service=>\'fibroscan\',:link=>\'../Fibroscan/index\',:remote=>false}\r\n\r\n]}\r\n]\r\n',NULL,NULL,NULL,'2015-03-14 03:38:20','2015-03-14 03:38:20','config',''),(1363,'test',574,3,'<%= render :inline=>this.init%>\r\n<%\r\n    models = get_model\r\n    date = Time.now \r\n    if not params[:date].nil? \r\n        date = Time.parse(params[:date])\r\n    end\r\n    co = {} # count operative\r\n    groups = this.config\r\n    # for a in groups[0][:actions] \r\n    #     co[a[:name]] = 0\r\n    # end\r\n    \r\n    colono = @models[:colono].all(:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day).size\r\n    gastro = @models[:gastro].all(:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day).size\r\n    ercp = @models[:ercp].all(:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day).size\r\n    sm = @models[:sigmoid].all(:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day).size\r\n    pe = @models[:push_enteroscopy].all(:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day).size\r\n    dbe = @models[:dbe].all(:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day).size\r\n    eus = @models[:eus].all(:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day).size\r\n    \r\n    co[:gastro] = gastro\r\n    co[:colono] = colono\r\n    # co[:ercp] = ercp\r\n    # co[:sigmoid] = sm\r\n    # co[:push_enteroscopy] = pe\r\n    # co[:dbe] = dbe\r\n    # co[:eus] = eus\r\n    \r\n    pc = 0 # processing count\r\n    mtoday = @patient_module_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day,:module_name=>\"\\\\#{@current_project.name}#appointment\") \r\n    mtoday = models[:appointment].where(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day).to_a \r\n    mtoday.collect!{|i| @patient_module_model.where(:module_id=>i.id).first }.compact!\r\n    list = mtoday.collect{|i| \r\n        p = @patient_model.find(i.patient_id)\r\n        ap = @models[:appointment].find(i.module_id)\r\n        {:admit_id=>ap.id,:patient_name=>\"\\\\#{p.first_name} \\\\#{p.last_name}\",:patient_hn=>p.hn,:patient=>p, :appointment=>ap} \r\n        \r\n        # if ap[:status] == \'Completed\'\r\n        #     pc = pc + 1\r\n        # end\r\n    }\r\n    \r\n    for l in list\r\n        if l[:appointment][:status] == \'Completed\'\r\n            pc = pc + 1\r\n        end\r\n    end\r\n    \r\n    cf2 = @models[:colono_finding_2].all(:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day)\r\n    s1 = Array.new\r\n    for x in cf2\r\n        z = x[:size].to_f\r\n        s1.push(z)\r\n    end\r\n    \r\n    # fb = @models[:fibroscan].all\r\n    # fat = Array.new\r\n    # fib = Array.new\r\n    # for x in fb\r\n    #     fat.push(x[:fat_percent].to_f)\r\n    #     fib.push(x[:fibrosis].to_f)\r\n    # end\r\n    \r\n    if colono > pc\r\n        pc = colono\r\n    end\r\n    \r\n    tmp = {}\r\n    result = {:complete=>pc, :total=>mtoday.size, :total=>co, :tmp=>tmp}\r\n    \r\n%>\r\n<%= result.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2015-03-14 06:34:22','2015-03-14 06:34:22','test','*'),(1364,'config',574,1,'services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact\r\n    [{:name=>\'Form\',:open=>true,:actions=>services.collect{|i| {:name=>i.title,:service=>i.name,:link=>\"../\\\\\\#{i.name.camelize}/index\"}} }]',NULL,NULL,NULL,'2015-03-14 07:11:45','2015-03-14 07:11:45','config',''),(1365,'index',646,2,'<%\r\n\r\n  ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  model = ehr.load_model\r\n  patient_model = model[:patient]\r\n  module_model = model[:patient_module]\r\n\r\n  models = get_model\r\n  date = Time.now\r\n  app  = models[:appointment]\r\n  colono = models[:colono]\r\n  gastro = models[:gastro]\r\n  fibroscan = models[:fibroscan]\r\n#   date = Time.now.strftime(\'%d/%m/%Y\')\r\n#   apps = app.where( :date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day ).all\r\n  \r\n#   colonos = colono.where( :created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day ).all\r\n\r\n#   gastros = gastro.where( :created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day ).all\r\n  \r\n  apps = app.all\r\n  \r\n  colonos = colono.all#where( :created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day ).all\r\n\r\n  gastros = gastro.all#where( :created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day ).all\r\n  \r\n  \r\n  \r\n  %>\r\n  <table>\r\n  <%\r\n  \r\n\r\n  for i in colonos\r\n    cm = module_model.where(:module_id=>i.id).first\r\n    if cm\r\n        pm = module_model.find(cm.parent_id)\r\n        f = module_model.where(:module_name=>\"\\\\#{@current_project.name}\\#fibroscan\",:parent_id=>pm.id).first\r\n        if f\r\n            fb = fibroscan.find(f.module_id)\r\n           %>\r\n           <tr>\r\n           <td><%= i.diagnosis_group%></td>\r\n           <td><%=fb.fibrosis%></td><td><%=fb.fat_percentage%></td>\r\n           </tr>\r\n           <%\r\n        end\r\n        if pm\r\n                ap = app.find(pm.module_id)\r\n               \r\n                ap.update_attributes :status=>\'Completed\'\r\n        end\r\n    end\r\n  end\r\n  \r\n  %>\r\n  </table>\r\n  <%\r\n  \r\n  for i in gastro\r\n    cm = module_model.where(:module_id=>i.id).first\r\n    if cm\r\n        pm = module_model.find(cm.parent_id)\r\n      \r\n        if pm\r\n                ap = app.find(pm.module_id)\r\n               \r\n                ap.update_attributes :status=>\'Completed\'\r\n        end\r\n    end\r\n  end\r\n  \r\n\r\n%>\r\n\r\n<%= apps.size  %>\r\n\r\n<%= colonos.size  %>\r\n\r\n<%= gastros.size  %>',NULL,NULL,NULL,'2015-03-14 08:45:31','2015-03-14 08:45:31','index',''),(1366,'status_feed',622,3,'<!DOCTYPE html PUBLIC 