module.where(:id=>zpm[:parent_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\").first\r\n    zap = zmodels[:appointment].find(zpm[:module_id])\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<!--New <%=this.table_name.to_s.humanize%>-->\r\n<h3><strong>New <%# zmap_proc[zap[:procedure].to_s][:name] %>(<%= zmap_proc[zap[:procedure].to_s][:name] %>)</strong></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n<div style=\"border:0px solid;<%= \"background-color:\\\\#{this.color_name};\" if show_color %>\">\r\n<!--<div class=\"document-border\" style=\"border:0px solid\">-->\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<%\r\n    show_url = \"show?id=\\\\#{m.id}\".html_safe\r\n    if params[:record][:bilateral] == \'1\'\r\n    # if params[:b] == \'1\'\r\n        # params[:next_service] = \"../\\\\#{s}/create?patient_id=\\\\#{params[:patient_id]}&b=\\\\#{b}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{m.id}&return=\\\\#{params[:return]}\"\r\n        show_url += \"&b=1&s=\\\\#{params[:record][:side]}&patient_id=\\\\#{params[:patient_id]}&record_name=\\\\#{params[:record_name]}&parent_id=\\\\#{params[:parent_id]}\".html_safe\r\n    else\r\n        show_url = return_url\r\n    end\r\n    if !return_url.empty?\r\n        show_url += \"&return=\\\\#{return_url}\".html_safe\r\n    end\r\n%>\r\nwindow.location = \"<%=show_url%>\";\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n<%\r\n    if params[:b]\r\n%>\r\n<%= hidden_field_tag :b, params[:b] %>\r\n<%\r\n    end\r\n%>\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\' %> \r\n<%= hidden_field_tag \'ref_number\',ref_number %> \r\n<%= hidden_field_tag \'date\',Time.now %> \r\n<%= hidden_field_tag \'time\',Time.now.strftime(\"%H:%M\") %> \r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=request.fullpath%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n        // alert(\"URL \" + url);\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  //$(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe, :onclick=>\'javascript:opnote()\', :class=>\'btn btn-small btn-success\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\', :class=>\'btn btn-small\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<%# if @current_role == \'developer\' %>\r\n<%= render :inline=>this.opnote, :locals=>{:this=>this} %>\r\n<%# end %>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n\r\n<%\r\n    # auto check left/right\r\n    if params[:s] != \'0\'\r\n%>\r\n<script>\r\n    $(document).ready(function() {\r\n        // console.log( \"ready!\" );\r\n        $(\"#data-side\").val(\'2\');\r\n        $(\"#update_side_item_<%= params[:s].to_i - 1 %>\").prop(\'checked\', true);\r\n        $(\"#bilateral\").hide();\r\n        // console.log(\'Ok\');\r\n    });\r\n</script>\r\n\r\n<%\r\n    end\r\n%>\r\n<script>\r\n    window.history.forward();\r\n    window.onload = function()\r\n    {\r\n        // console.log(\'...Loaded...\');\r\n        // console.log(\"HISTORY : \" + history.length + \", prev : \" + history.previous);\r\n        window.history.forward();\r\n    };\r\n    window.onunload = function() {\r\n        // console.log(\'...un Loaded...\');\r\n        null;\r\n    };\r\n    window.onpopstate = function(event) {\r\n        alert(\"location: \" + document.location);\r\n    }\r\n</script>\r\n',NULL,NULL,NULL,'2015-04-13 16:18:58','2015-04-13 16:18:58','create',''),(1417,'test',622,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  attachment_model = @models[:attachment]\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n#   appointments =   @models[:appointment].where(:date=>date).all\r\n    appointments =   @models[:appointment].where(:date=>\'15-02-2015\').all\r\n%>\r\n<p>AP <%= date %> : <%= @models[:appointment].all %></p>\r\n<%\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n \r\n \r\n\r\n\r\n \r\n ml =  @module_model.where(:parent_id=>i.id).all\r\n \r\n diagnosis = \'\'\r\n diagnosis_group = \'\'\r\n provider = providers[ap.provider.to_s]\r\n provider_name = provider.name\r\n attachments = []\r\n#  provider_name = ml.size.to_s\r\n \r\n for x in ml\r\n    if x.module_name==\"\\\\#{@current_project.name}#colono\"\r\n        \r\n        colo = @models[:colono].find(x.module_id)\r\n  \r\n        if colo\r\n            provider_name = colo.id.to_s\r\n            \r\n            provider = providers[colo.endoscopist.to_s]\r\n            provider_name = provider.name\r\n            diagnosis = colo.diagnosis_text\r\n            diagnosis_group = colo.diagnosis_group\r\n            attachments = colo.image\r\n            \r\n        end\r\n    end\r\n end\r\n \r\n \r\n\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year} ปี\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>ml.collect{|i| i.module_name.split(\'#\')[-1].humanize}.join(\',\'),\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider_name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'attachments\'=>attachments,\r\n    \'age\'=>age,\r\n    \'ml\'=>ml,\r\n    \'diagnosis\'=>diagnosis.html_safe,\r\n    \'diagnosis_group\'=>diagnosis_group.html_safe,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\n\r\n\r\nlist = json_data.sort{|a,b| b[\'diagnosis_group\']<=>a[\'diagnosis_group\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_path\'  %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงรายการผู้ป่วย\r\n<span style=\"float:right\">ประจำวันที่ \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>HN</th>\r\n    <th >อายุ</th>\r\n    <th>Procedure</th>\r\n    <th>Diagnosis</th>\r\n    <th>Provider</th>\r\n    <th>Link</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n<% \r\n    sp = {}\r\n    list.each_with_index do |i,index|  \r\n        pps = i[\'procedure\'].split(\',\')\r\n        for pp in pps\r\n            if sp.has_key?(pp)\r\n                sp[pp] = sp[pp] + 1\r\n            else\r\n                sp[pp] = 1\r\n            end\r\n        end\r\n%>\r\n    <tr style=\"\">\r\n    <td><%=index+1%>.</td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%></td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'age\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    <td width=\"100\"><%=i[\'diagnosis\']%></td>\r\n    <td><%=i[\'provider\']%></td>\r\n    <td><%=link_to(\'Detail\',\"patient_record?id=\\\\#{i[\'id\']}\")%></td>\r\n    </tr>\r\n    \r\n    \r\n    <tr>\r\n    <td colspan=\"8\">\r\n        <%  \r\n        if true\r\n            attachments = attachment_model.find(i[\'attachments\'])[0..4]\r\n        for j in attachments\r\n        %>\r\n        <%= image_tag j.path,:width=>80%>\r\n        <% end %>\r\n        <% end %>\r\n    </td>    \r\n        \r\n    </tr>\r\n    \r\n    \r\n    <% end %>\r\n</tbody>\r\n  </table><br/>\r\n<% if false %>\r\n<br/>\r\n  <div><strong>Total procedure</strong></div><br/>\r\n<%\r\nsp.keys.each_with_index do |key, index|\r\n%>\r\n<div><%= key %> : <%= sp[key] %></div>\r\n<%\r\nend\r\nend\r\n%>\r\n  </div>\r\n  </div></div></div></div></div>\r\n</body>\r\n</html>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2015-04-14 17:56:21','2015-04-14 17:56:21','test',''),(1418,'json_test',622,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  attachment_model = @models[:attachment]\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n  end\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n    # appointments =   @models[:appointment].where(:date=>\'15-03-2015\').all\r\n    # appointments =   @models[:appointment].all\r\n    d = \'2015-03-15\'\r\n    # appointments =   @models[:appointment].where(:date=>Time.parse(d)).all\r\n    result = {:date=>date,:appointment=>appointments}\r\n%>\r\n<%=result.to_json.html_safe%>',NULL,NULL,NULL,'2015-04-14 18:17:30','2015-04-14 18:17:30','json_test',''),(1419,'export_polyp',491,3,'\r\n<%\r\n\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n\r\n  @document = get_document(this.document_name)\r\n\r\n  doc = @document\r\n\r\n  data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n  \r\n   fields = @document.fields\r\n   fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n  fields << \'created_at\'\r\n  fields << \'updated_at\'\r\n%>\r\n<table>\r\n<tr><td>HN</td><td>Name</td><td>Gender</td><td>Birth Date</td><td>Age</td><td>Record date</td>\r\n\r\n<%\r\nfor i in fields \r\n%><td><%= i[1] %></td>\r\n<% end %>\r\n</tr>\r\n<% for i in data \r\n\r\n     @record = i\r\n\r\n    age = 0\r\n    hn = nil\r\n    \r\n    p = @patient_model.new\r\n    m = @module_model.collection.find(:module_id=>i.id).first\r\n    if m \r\n    \r\n    patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n    if patient\r\n    bdate = 0\r\n    bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n    age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n   \r\n    p = patient\r\n    p[\'record_date\'] = m[\'date\']\r\n    \r\n    end\r\n   end\r\n    \r\n    \r\n%>\r\n<tr>\r\n<td><%=p[\'hn\'] %></td><td><%=p[\'first_name\']%> <%=p[\'last_name\']%></td><td><%=p[\'gender\']%></td><td><%=p[\'birth_date\'].strftime(\'%d/%m/%Y\') if p[\'birth_date\'] %></td><td><%=age%></td><td><%=p[\'record_date\'].strftime(\'%d/%m/%Y\') if p[\'record_date\']%></td>\r\n\r\n<%\r\n    @document = doc\r\n    @fields = @document.fields\r\n    \r\n    for j in fields \r\n    \r\n    if i[j[0]]\r\n%>\r\n<td><%= render_value j[0] %></td>\r\n<% else %>\r\n<td>.</td>\r\n<% end %>\r\n<% end %>\r\n</tr>\r\n<% end %>\r\n</table>\r\n  \r\n  \r\n   \r\n   \r\n   ',NULL,NULL,NULL,'2015-04-17 17:16:21','2015-04-17 17:16:21','export_polyp',''),(1420,'test',491,3,'\r\n<%\r\n\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n\r\n  @document = get_document(this.document_name)\r\n\r\n  doc = @document\r\n\r\n  data = get_model(this.document_name).sort(:created_at.desc).limit(10)\r\n#   data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n  \r\n   fields = @document.fields\r\n   fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n#   fields << \'created_at\'\r\n#   fields << \'updated_at\'\r\n   fields << [\"finding_2\", \"Polyp\"]\r\n%>\r\n<p><%= fields.inspect %></p>\r\n<p><%= data.inspect %></p>\r\n<table>\r\n<tr><td>HN</td><td>Name</td><td>Gender</td><td>Birth Date</td><td>Age</td><td>Record date</td>\r\n\r\n<%\r\nfor i in fields \r\n%><td><%= i[1] %></td>\r\n<% end %>\r\n</tr>\r\n<% for i in data \r\n\r\n     @record = i\r\n\r\n    age = 0\r\n    hn = nil\r\n    \r\n    p = @patient_model.new\r\n    m = @module_model.collection.find(:module_id=>i.id).first\r\n    if m \r\n    \r\n    patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n    if patient\r\n    bdate = 0\r\n    bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n    age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n   \r\n    p = patient\r\n    p[\'record_date\'] = m[\'date\']\r\n    \r\n    end\r\n   end\r\n    \r\n    \r\n%>\r\n<tr>\r\n<td><%=p[\'hn\'] %></td><td><%=p[\'first_name\']%> <%=p[\'last_name\']%></td><td><%=p[\'gender\']%></td><td><%=p[\'birth_date\'].strftime(\'%d/%m/%Y\') if p[\'birth_date\'] %></td><td><%=age%></td><td><%=p[\'record_date\'].strftime(\'%d/%m/%Y\') if p[\'record_date\']%></td>\r\n\r\n<%\r\n    @document = doc\r\n    @fields = @document.fields\r\n    \r\n    for j in fields \r\n    \r\n    if i[j[0]]\r\n%>\r\n<td><%= render_value j[0] %></td>\r\n<% else %>\r\n<td>.</td>\r\n<% end %>\r\n<% end %>\r\n</tr>\r\n<% end %>\r\n</table>\r\n  \r\n  \r\n   \r\n   \r\n   ',NULL,NULL,NULL,'2015-04-19 03:45:15','2015-04-19 03:45:15','test',''),(1421,'login',626,4,'<html>\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n\r\n <!-- Bootstrap framework -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap.min.css\" />\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap-responsive.min.css\" />\r\n        <!-- theme color-->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n        <!-- tooltip -->    \r\n			<link rel=\"stylesheet\" href=\"/gebo/lib/qtip2/jquery.qtip.min.css\" />\r\n        <!-- main styles -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/style.css\" />\r\n<style>\r\ninput, textarea, select, .uneditable-input { height:40px;font-size:1em;}\r\n.login_page .cnt_b { padding:15px 0}\r\nbody { \r\n    background: url(\'/esm/thks/www/content/bg1.jpg\') no-repeat center center fixed; \r\n  -webkit-background-size: cover;\r\n  -moz-background-size: cover;\r\n  -o-background-size: cover;\r\n  background-size: cover;\r\n   \r\n    font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\r\n    font-weight: lighter;\r\n    /*font-size: 1em;*/\r\n}\r\n</style>            \r\n</head>\r\n<body class=\"login_page\">\r\n<script src=\"/gebo/js/jquery.min.js\"></script>\r\n<script src=\"/gebo/js/jquery.actual.min.js\"></script>\r\n<script src=\"/gebo/lib/validation/jquery.validate.min.js\"></script>\r\n<script src=\"/gebo/bootstrap/js/bootstrap.min.js\"></script>\r\n<%\r\n	p = {}\r\n	if @current_project \r\n	tp = @current_project.get_params if @current_project \r\n	p = tp if tp\r\n	end\r\n	title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"ESM:Innovation as a Service\"\r\n	bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#eee\"\r\n	logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n%>\r\n\r\n<%\r\n    user = \'\'\r\n	user = params[:user][:login] if params[:user]\r\n%>\r\n<%= form_for :user, :action=>\'login\',  :html => { :id => \"user_login\"} do|form|%>\r\n            <center>\r\n                <a href=\"/\">\r\n            <!--<img src=\"/esm/taig/www/content/logo_HIPKNEE.png\" style=\"background-color: white;border-color:white;width:150px;border-radius: 100px;\">-->\r\n            <!--<img src=\"/esm/taig/www/content/web-logo.png\" style=\"background:black;padding:5px;width:380px\"/>-->\r\n                    <!--<img src=\"/esm/taig/www/content/thks.png\" style=\"background-color: black;border-color:black;width:200px;border-radius: 100px;margin-top:-40px\">-->\r\n                    <img src=\"/esm/thks/www/content/logolong.png\" style=\"border-color:black;width:100%;max-width:250px;border-radius: 10px;margin-top:-5px;padding:20px\">\r\n                </a>\r\n                <br/><br/>\r\n            </center>\r\n	<div class=\"login_box\" style=\"height:220px;top:0;bottom: 0;left: 0;right: 0;margin: auto;font-size:1.2em\">\r\n		\r\n		<form action=\"dashboard.html\" method=\"post\" id=\"login_form\">\r\n		\r\n			<% if flash[:error] %>\r\n			<div class=\"alert alert-info alert-login\">\r\n				<%= flash[:error] %>\r\n			</div>\r\n			<% else %>\r\n			<div class=\"alert alert-info alert-login\">\r\n				Please login to continue \r\n			</div>\r\n			<% end %>\r\n			\r\n			\r\n	   	\r\n\r\n			\r\n			<div class=\"cnt_b\">\r\n			\r\n					\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\" style=\"height:30px;padding:5px\"><i class=\"icon-user\"></i></span>\r\n						<%= form.text_field \"login\", :size => 15,:id=>\'user_login\',:placeholder=>\"Email or Login ID\",\'data-icon\'=>\"user\",:value=>user%>\r\n					   \r\n					</div>\r\n				</div>\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\" style=\"height:30px;padding:5px\"><i class=\"icon-lock\" ></i></span>\r\n						<%= form.password_field \"password\", :size => 15,:id=>\'user_password\',:placeholder=>\"Password\",\'data-icon\'=>\"closed-lock\"%>\r\n						\r\n					</div>\r\n				</div>\r\n					<%  unless @current_solution %>\r\n				<span id=\"solution_id_toggle\"><center><a href=\"javascript:$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\">...</a></center></span>	\r\n				<div class=\"formRow\" id=\"solution_id\" style=\"display:none\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-book\"></i></span>\r\n						<%= text_field_tag \"user[esm]\",cookies[:esm], :size => 15,:id=>\'esm\',:placeholder=>\"Solution ID\",\'data-icon\'=>\"settings\"%>\r\n					</div>\r\n				</div>\r\n				<script>\r\n				    $(document).ready(function(){\r\n				<% if cookies[:esm] %>\r\n					$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\r\n				<%  end %>\r\n			  });\r\n				</script>\r\n				\r\n					<% else %>\r\n						<%= form.hidden_field \"esm\", :value=> @current_solution.name %>\r\n						<%= form.hidden_field \"project_id\", :value=> @current_project.id if @current_project%>\r\n					<% end %>\r\n					\r\n					\r\n				<div class=\"formRow clearfix\">\r\n					<label class=\"checkbox\"><input id=\"ck\" name=\'remember\' type=\"checkbox\" /> Remember me</label>\r\n				</div>\r\n			</div>\r\n			<div class=\"btm_b clearfix\" >\r\n				<!--<button class=\"btn btn-inverse pull-right\" type=\"submit\">Sign In</button>-->\r\n				<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#disclaimer\" class=\"btn btn-inverse pull-right\">Sign In</a>\r\n				<span class=\"link_reg\"><a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#terms\">Disclaimer</a></span>\r\n				\r\n			</div>  \r\n			<div class=\"\" style=\"margin-top:10px;text-align:center\">\r\n    			  \r\n    			\r\n    			        <img src=\'/esm_core/banner1.png\' height=\"30px\"/>\r\n    			 \r\n    			   \r\n			</div>\r\n		</form>\r\n		\r\n		\r\n                            <div class=\"modal hide\" id=\"disclaimer\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Disclaimer</h3>\r\n								</div>\r\n								<div class=\"modal-body\" style=\"font-size:10pt\">\r\nPRIVACY\r\nRespecting your privacy is important to us. Patient information that you provide will remain confidential at all times. We do not sell, rent or disclose any information about our patient to other companies. Periodically, we may send you information about our products and services. If, however, you prefer not to receive such offers or information, just send us an email.\r\n<br/>\r\n<br/>\r\nOWNERSHIP OF CONTENT\r\nReproduction of this Web site, in whole or in part, is prohibited by law.\r\n<br/>\r\n<br/>\r\nAll content included on this site, such as text, logos, graphics & images is the property of THKS. or its content suppliers and protected by Thai and international copyright laws. The compilation of all content on this site is the exclusive property of THKS. and protected by Thai and international copyright laws. All software used on this site is the property of THKS.  or its software suppliers and protected by Thai and international copyright laws.\r\n<br/>\r\n<br/>\r\nDISCLAIMER OF WARRANTIES AND LIMITATION OF LIABILITY\r\nTHIS SITE IS PROVIDED BY THKS. ON AN \"AS IS\" AND \"AS AVAILABLE\" BASIS. THKS.  MAKES NO REPRESENTATIONS OR WARRANTIES OF ANY KIND, EXPRESS OR IMPLIED, AS TO THE OPERATION OF THIS SITE OR THE INFORMATION, CONTENT, MATERIALS, OR PRODUCTS INCLUDED ON THIS SITE. YOU EXPRESSLY AGREE THAT YOUR USE OF THIS SITE IS AT YOUR SOLE RISK.\r\nTHKS. WILL NOT BE LIABLE FOR ANY DAMAGES OF ANY KIND ARISING FROM THE USE OF THIS SITE, INCLUDING BUT NOT LIMITED TO DIRECT, INDIRECT, INCIDENTIAL, PUNITIVE, AND CONSEQUENTIAL DAMAGES.\r\n\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n								    <a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Ignore</a>\r\n									<a href=\"#\" onclick=\"javascript:login();\" class=\"btn\" data-dismiss=\"modal\">Accept</a>\r\n								</div>\r\n							</div>\r\n<script>\r\n    function login() {\r\n        document.getElementById(\'user_login\').submit();\r\n    }\r\n</script>\r\n		\r\n		\r\n		\r\n		<div id=\"terms\" class=\"modal hide fade\">\r\n				<div class=\"modal-header\">\r\n					<a class=\"close\" data-dismiss=\"modal\">×</a>\r\n					<h3>Disclaimer</h3>\r\n				</div>\r\n				<div class=\"modal-body\">\r\n					<p>\r\n						PRIVACY\r\nRespecting your privacy is important to us. Patient information that you provide will remain confidential at all times. We do not sell, rent or disclose any information about our patient to other companies. Periodically, we may send you information about our products and services. If, however, you prefer not to receive such offers or information, just send us an email.\r\nOWNERSHIP OF CONTENT\r\nReproduction of this Web site, in whole or in part, is prohibited by law.\r\nAll content included on this site, such as text, logos, graphics & images is the property of THKS. or its content suppliers and protected by Thai and international copyright laws. The compilation of all content on this site is the exclusive property of THKS. and protected by Thai and international copyright laws. All software used on this site is the property of THKS.  or its software suppliers and protected by Thai and international copyright laws.\r\nDISCLAIMER OF WARRANTIES AND LIMITATION OF LIABILITY\r\nTHIS SITE IS PROVIDED BY THKS. ON AN \"AS IS\" AND \"AS AVAILABLE\" BASIS. THKS.  MAKES NO REPRESENTATIONS OR WARRANTIES OF ANY KIND, EXPRESS OR IMPLIED, AS TO THE OPERATION OF THIS SITE OR THE INFORMATION, CONTENT, MATERIALS, OR PRODUCTS INCLUDED ON THIS SITE. YOU EXPRESSLY AGREE THAT YOUR USE OF THIS SITE IS AT YOUR SOLE RISK.\r\nTHKS. WILL NOT BE LIABLE FOR ANY DAMAGES OF ANY KIND ARISING FROM THE USE OF THIS SITE, INCLUDING BUT NOT LIMITED TO DIRECT, INDIRECT, INCIDENTIAL, PUNITIVE, AND CONSEQUENTIAL DAMAGES.\r\n					</p>\r\n				</div>\r\n				<div class=\"modal-footer\">\r\n					<a data-dismiss=\"modal\" class=\"btn\" href=\"#\">Close</a>\r\n				</div>\r\n			</div>\r\n		\r\n	</div>\r\n	\r\n	<div class=\"links_b links_btm clearfix\" >\r\n	\r\n	\r\n	</div>\r\n		\r\n	</div>  \r\n   <% end %>\r\n\r\n    <script>\r\n        $(document).ready(function(){\r\n            \r\n			//* boxes animation\r\n			form_wrapper = $(\'.login_box\');\r\n            $(\'.linkform a,.link_reg a\').on(\'click\',function(e){\r\n				var target	= $(this).attr(\'href\'),\r\n					target_height = $(target).actual(\'height\');\r\n				$(form_wrapper).css({\r\n					\'height\'		: form_wrapper.height()\r\n				});	\r\n				$(form_wrapper.find(\'form:visible\')).fadeOut(400,function(){\r\n					form_wrapper.stop().animate({\r\n                        height	: target_height\r\n                    },500,function(){\r\n                        $(target).fadeIn(400);\r\n                        $(\'.links_btm .linkform\').toggle();\r\n						$(form_wrapper).css({\r\n							\'height\'		: \'\'\r\n						});	\r\n                    });\r\n				});\r\n				e.preventDefault();\r\n			});\r\n			\r\n			//* validation\r\n			$(\'#login_form\').validate({\r\n				onkeyup: false,\r\n				errorClass: \'error\',\r\n				validClass: \'valid\',\r\n				rules: {\r\n					username: { required: true, minlength: 3 },\r\n					password: { required: true, minlength: 3 }\r\n				},\r\n				highlight: function(element) {\r\n					$(element).closest(\'div\').addClass(\"f_error\");\r\n				},\r\n				unhighlight: function(element) {\r\n					$(element).closest(\'div\').removeClass(\"f_error\");\r\n				},\r\n				errorPlacement: function(error, element) {\r\n					$(element).closest(\'div\').append(error);\r\n				}\r\n			});\r\n        });\r\n    </script>\r\n\r\n\r\n		<script type=\"text/javascript\">\r\n	\r\n		try{document.getElementById(\'user_login\').focus();}catch(e){}\r\n		</script>\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-04-19 13:18:46','2015-04-19 13:18:46','login',''),(1422,'layout',666,4,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n			\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n<title><%=title%></title>\r\n\r\n<script>\r\n$(document).ready(function() {\r\n	//* show all elements & remove preloader\r\n	// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n    // $(\"html\").removeClass(\"js\");\r\n});\r\n</script>\r\n		\r\n<style>\r\n.w-box-content.cnt_a {\r\n    background: #fff;\r\n}\r\n.k-grid table {\r\n    font-size: 1em;\r\n}\r\n.k-calendar .k-content {\r\n    font-size: 1em;padding-top:5px;\r\n}\r\n.k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\n    height: 18px;\r\n}\r\n.field-data {\r\n    width: 220px;\r\n}\r\n\r\ninput{\r\n    height:18px;\r\n}\r\nbody { \r\n\r\n    padding: 20px;\r\n    font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\r\n    /*font-weight: lighter;*/\r\n    /*font-size: 1em;*/\r\n}\r\n\r\n\r\n</style>\r\n		\r\n		\r\n</head>\r\n<body style=\"    background-image: url(\'/esm/thks/www/content/hip-knee-pain-bw.jpg\');\r\n    /* ref : http://i0.wp.com/blog.beaumont.edu/wp-content/uploads/2014/10/hip-knee-pain.png */\r\n    background-repeat: no-repeat;\r\n    background-attachment: fixed;\r\n    background-position: center top; \r\n    background-color: black;\r\n    background-size: cover;\">\r\n\r\n\r\n<%\r\n    m_prov = get_model[:provider]\r\n    prov = m_prov.where(:login=>@current_user.login).first\r\n%>\r\n\r\n\r\n\r\n                <div class=\"navbar navbar-fixed-top\">\r\n                    <div class=\"navbar-inner\">\r\n                        <div class=\"container-fluid\">\r\n                            <a class=\"brand\" href=\"/\" style=\"border:0px solid;padding:0px;width:250px\"><img height=\"36\" src=\"<%= logo %>\" style=\'padding:4px;margin-left:25px\' /></a>\r\n                            <ul class=\"nav user_menu pull-right\">\r\n						        <li class=\"divider-vertical hidden-phone hidden-tablet\"></li>\r\n                                <li class=\"dropdown\">\r\n									<a href=\"#\" class=\"dropdown-toggle\" data-toggle=\"dropdown\">\r\n                                        <%= prov.nil? ? @current_user.login : \"\\\\#{prov[:name]} (\\\\#{@current_user.login})\" %>\r\n                                        <b class=\"caret\"></b>\r\n                                    </a>\r\n                                    <ul class=\"dropdown-menu\">\r\n									    <li style=\"\"><a href=\"../Setting/index\">Settings</a></li>\r\n									    <%= \" <li><a href=\'/esm_projects/\\\\#{@current_project.id}\' class=\'btn btn-mini\' target=\'_blank\'>Developer</a></li> \".html_safe if @current_role==\'developer\' %> \r\n										<li class=\"divider\"></li>\r\n										<li><a href=\"/user/logout\">Logout</a></li>\r\n				                    </ul>\r\n                                </li>\r\n                                <li class=\'divider-vertical\'></li>\r\n                                <li><a href=\"/user/logout\">Logout</a></li>\r\n						    </ul>\r\n							<a data-target=\".nav-collapse\" data-toggle=\"collapse\" class=\"btn_menu\">\r\n								<span class=\"icon-align-justify icon-white\"></span>\r\n							</a>\r\n                            <nav>\r\n                                <div class=\"nav-collapse\">\r\n                                    <ul class=\"nav\">\r\n	                                    <li><a href=\"../Home/index\"><i class=\"icon-home icon-white\"></i> <b>Home</b></a></li>\r\n	                                    <!--\r\n	                                    <li class=\"dropdown\">\r\n                                            <a data-toggle=\"dropdown\" class=\"dropdown-toggle\"><i class=\"icon-list-alt icon-white\"></i> <b>Admin</b> <b class=\"caret\"></b></a>\r\n		                                    <ul class=\"dropdown-menu\">\r\n				                                <li><a href=\"../User/index\"><b>User</b></a></li><li><a href=\"../Role/index\"><b>Role</b></a></li>\r\n			                                </ul>\r\n		                                </li>\r\n		                                -->\r\n		                                <li class=\"dropdown\">\r\n                                            <a data-toggle=\"dropdown\" class=\"dropdown-toggle\">\r\n                                                <i class=\"icon-list-alt icon-white\"></i> \r\n                                                <b>Consent Form</b> <b class=\"caret\"></b>\r\n                                            </a>\r\n		                                    <ul class=\"dropdown-menu\">\r\n				                                <li><a href=\"/esm/taig/taig/content/7190_TH_THKJR_consent.pdf\" target=\'_blank\'><b>Consent Form (TH)</b></a></li>\r\n				                                <li><a href=\"/esm/taig/taig/content/7189_EN_THKJR_consent.pdf\" target=\'_blank\'><b>Consent Form (EN)</b></a></li>\r\n			                                </ul>\r\n		                                </li>\r\n		                                <% if session[:owner] %>\r\n		                                <li><a href=\"../Home/report\" if=\"\" i.url=\"\" and=\"\" i.url!=\"\"><i class=\"icon-list-alt icon-white\"></i> <b>Reports </b></a></li>\r\n		                                <% end %>\r\n                                        <li><a href=\"../Setting/index\" if=\"\" i.url=\"\" and=\"\" i.url!=\"\"><i class=\"splashy-sprocket_dark\"></i> <b>Setting </b></a></li>\r\n	                                </ul>\r\n                                </div>\r\n                            </nav>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n<% if false %>\r\n                <div class=\"row-fluid\">\r\n                    <div class=\"span8\">\r\n                        <a href=\"../Home/index\">	\r\n                                        <!--<img src=\"/esm/taig/www/content/logo_HIPKNEE.png\" style=\"background-color: white;border-color:white;width:100px;border-radius: 50px;\">-->\r\n                                        <!--<img src=\"/esm/taig/www/content/web-logo_mini-logo.png\" height=\"80px\"/>-->\r\n                                        <img src=\'<%= logo %>\' height=\'80px\'/>\r\n                                    </a>\r\n                    </div>\r\n					<div class=\"span4\">\r\n					    <span style=\"float:right;color:#efefef;font-size:1.2em;text-align:right;margin-top:10px\" >\r\n\r\n                            Welcome : <span style=\"color:lightgray\"><%= prov.nil? ? @current_user.login : \"\\\\#{prov[:name]} (\\\\#{@current_user.login})\" %></span>\r\n                            <div style=\"padding-top:5px\"></div>\r\n                            <%= \" <a href=\'/esm_projects/\\\\#{@current_project.id}\' class=\'btn btn-mini\' target=\'_blank\'>dev</a> | \".html_safe if @current_role==\'developer\' %> \r\n                            <%=link_to \'<i class=\"splashy-sprocket_dark\"></i> Setting\'.html_safe, \'../Setting/index\', :class=>\'btn btn-mini\', :style=>\'width:60px\' %> |\r\n                            <%=link_to \'Logout <i class=\"splashy-media_controls_play_small\"></i>\'.html_safe, \'/user/logout\', :class=>\'btn btn-mini\', :style=>\'width:60px\' %>\r\n                            <div style=\"padding-top:5px\"></div>\r\n                            <%=link_to \'Home <i class=\"splashy-home_green\"></i>\'.html_safe, \'../Home/index\', :class=>\'btn btn-mini\', :style=>\'width:60px\' %>\r\n                        </span>\r\n					</div>\r\n				</div>\r\n<% end %>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'clear\'>&nbxp;</div>\r\n</div>\r\n<br/>\r\n<br/>\r\n<%\r\n    if @current_role==\'developer\'\r\n%>\r\n\r\n<%\r\n    end\r\n%>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\" style=\"padding:0px;\">\r\n\r\n				   <%= yield %><%= yield :content%>\r\n                \r\n        </div>\r\n    </div>\r\n    <div class=\"alert\">Developed by <%= link_to \'E.S.M.Solution Co.,Ltd.\', \'https://emr-life.com\', :target=>\'_blank\' %></div> \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n     		<div id=\"context-menu\" class=\"accordion\">\r\n             <%= render :partial=>\'/layouts/context_menu\'%>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n			$(\'#search-field\').focus();\r\n		</script>		\r\n<%\r\n    auto_logout = false\r\n    if auto_logout\r\n%>\r\n<script>\r\nvar IDLE_TIMEOUT = 15*60; //seconds\r\nvar _idleSecondsCounter = 0;\r\ndocument.onclick = function() {\r\n    _idleSecondsCounter = 0;\r\n};\r\ndocument.onmousemove = function() {\r\n    _idleSecondsCounter = 0;\r\n};\r\ndocument.onkeypress = function() {\r\n    _idleSecondsCounter = 0;\r\n};\r\nwindow.setInterval(CheckIdleTime, 1000);\r\n\r\nfunction CheckIdleTime() {\r\n    _idleSecondsCounter++;\r\n    var oPanel = document.getElementById(\"SecondsUntilExpire\");\r\n    if (oPanel)\r\n        oPanel.innerHTML = (IDLE_TIMEOUT - _idleSecondsCounter) + \"\";\r\n    if (_idleSecondsCounter >= IDLE_TIMEOUT) {\r\n        alert(\"Session expired!\");\r\n        document.location.href = \"/user/logout\";\r\n    }\r\n}\r\n</script>\r\n<%\r\n    end\r\n%>\r\n<%= include_essential %>\r\n    \r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-04-19 13:40:59','2015-04-19 13:40:59','layout',''),(1423,'test_search',666,2,'<%\r\nmodule_name = @current_project.name\r\nif params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\nend\r\nif session[module_name]\r\n	params[:date] = session[module_name][:date]\r\nend\r\nunless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\nend\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    provider = models[:provider].where(:login=>@current_user.login).first\r\n    if provider\r\n       s_provider = provider.id.to_s\r\n    end\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       My Patients\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\'../Home/test_search\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n            \r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n                \r\n            </div>\r\n            </span>\r\n            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            \r\n            \r\n            <div class=\"field-input\">\r\n                 <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                 \r\n                 <%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>\r\n            </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            <div class=\"field-input\">\r\n            <%\r\n            # Home/patient_record?id=5533e537790f9b01c2000006\r\n                add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n                if s_provider \r\n                    # add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                    add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                end\r\n                \r\n            %>\r\n              \r\n                 <%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>\r\n            </div>\r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        </div>\r\n        <div class=\"row-fluid\"></div>\r\n \r\n<strong>\r\n<%\r\n    rs = []\r\n    if !search_patient and params[:select].nil?\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\").all\r\n    	end\r\n    %>\r\n    <!--ALL : <%= rs.size %>-->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name, :last_name=>s_last_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n        # patients = patient_model.where(criteria).limit(20).all\r\n        patients = patient_model.where(criteria).all\r\n	    # maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}\r\n        # aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     	    rs = module_model.where(:patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\"\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT : <%= rs.size %>-->\r\n    <%\r\n    elsif params[:date]\r\n        require \'date\'\r\n        dddd = Date.parse(params[:date])\r\n	    conds = {:date.gte=>dddd.at_beginning_of_day,:date.lt=>dddd.end_of_day, :module_name=>\"\\\\#{@current_project.name}#provider\"}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n            conds.merge! :module_id=>s_provider \r\n            # conds[:module_id] = s_provider\r\n            # conds[:module_name] = @current_project.name + \"#provider\"\r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n        rs = module_model.where(conds).all\r\n        # aps = ap_model.all(conds)\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     	  #  conds[:module_id] = s_provider\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n     	else\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    	end\r\n    	\r\n    # 	rs = module_model.all(conds)\r\n        # rs = module_model.all\r\n\r\n    %>\r\n    <!--DATE : <%=rs.size%> | <%= conds %>-->\r\n    <%\r\n    end # end if\r\n%>\r\n</strong>\r\n<!--<br/>-->\r\n<!--<br/>-->\r\n<%\r\nm_procedure = models[:procedure].all\r\nmap_proc = {}\r\nfor m in m_procedure do\r\n    map_proc[m.id] = m\r\nend\r\n\r\nresult = rs.collect do |i|\r\n    m_patient = patient_model.find(i[:patient_id].to_s)\r\n    patient_name = m_patient[:first_name] + \" \" + m_patient[:last_name]\r\n    \r\n    proc_rs = []\r\n    m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    for m in m_ap do\r\n        ap = models[:appointment].find(m[:module_id])\r\n        if ap\r\n            proc_rs.push(map_proc[ap[:procedure]])\r\n        end\r\n    end\r\n    \r\n    proc_txt = \'<center><font color=\"red\">-- Create New --</font></center>\'\r\n    if !proc_rs.empty?\r\n        proc_txt = \'\'\r\n        for x in proc_rs do \r\n            proc_txt += \'<center><div class=\"row-fluid\">\' + x.to_s + \'</div></center> \'\r\n        end\r\n    end\r\n    action = link_to(\'Detail\',\"patient_record?id=\\\\#{i[:patient_id]}\",:class=>\'btn btn-info\')\r\n    {:date=>i[:date], :hn=>m_patient[:hn], :name=>patient_name, :pid=>i[:patient_id], :procedure=>proc_txt, :action=>action}\r\nend\r\ncount = 1\r\nlabels = {:no=>\'No.\', :date=>\'Date\', :hn=>\'HN\', :name=>\'Patient Name\', :procedure=>\'Previous Procedure\', :action=>\'Action\'}\r\n%>\r\n\r\n        <div id=\"result-panel\" style=\"padding:10px\">\r\n            <%= tabular :data=>result, :model=>[:no, :date, :hn, :name, :procedure, :action], :labels=>labels do |row,out|\r\n                    out[0] = count.to_s+\".\"\r\n                    count+=1\r\n                 out\r\n             end\r\n            %>\r\n        </div>\r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/test_search?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n\r\n<div class=\"alert \">\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2015-04-19 13:42:23','2015-04-19 13:42:23','test_search',''),(1424,'create_old',667,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Create Patient</h3>\r\n<!--<strong>Create Patient</strong>-->\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n<div >\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\" >\r\n\r\n<%= render :inline=>this.init %>\r\n<% # params.inspect %>\r\n<%\r\n\r\n    msg = nil\r\n    err = false\r\n\r\n    if request.post?\r\n      \r\n        p = params[:record]\r\n        return_url = params[:return]\r\n        date = Time.now\r\n        if !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        \r\n        # next_service = \"../Patient/create_test?return=\\\\#{return_url}&\".html_safe\r\n        next_service = \"../Home/index\"\r\n        patient = false\r\n        # patient = @patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Duplicate HN in database\"\r\n            # next_service += URI.escape(params.collect{|k,v| \"\\\\#{k}=\\\\#{v}\"}.join(\'&\')).html_safe\r\n            err = true\r\n        else\r\n            # msg = \"Success\"\r\n            # next_service = \"../Setting/index\"\r\n            patient = @patient_model.create p\r\n            # if params[:record][:height] != \"\" and params[:record][:weight] != \"\"\r\n                # patient.update_attributes :height=>params[:record][:height], :weight=>params[:record][:weight], :bmi=>params[:record][:bmi]\r\n            # end\r\n            next_service = \'../Home/patient_record?id=\' + patient.id\r\n          \r\n            if params[:record][:provider]\r\n                m_pm_record = @module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>params[:record][:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>params[:record][:provider]\r\n            end\r\n            \r\n            msg = \"Patient created\"\r\n        end\r\n      \r\n    #   return_url += \'&obj_id=\'+patient.id.to_s\r\n      %>\r\n      <%#params.inspect %>\r\n      <div class=\"alert <%= err ? \"alert-error\" : \"alert-success\" %>\"><%= msg %></div>\r\n      <% if false %>\r\n      <pre><%# patient.inspect %></pre>\r\n      <pre><%# params.inspect %></pre>\r\n      <pre><%#  params[:record][:height].empty? %></pre>\r\n      <% end %>\r\n      <meta http-equiv=\"refresh\" content=\"0; url=<%=next_service%>\" />\r\n      <%\r\n    else\r\n%>\r\n<%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%= f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n<%= f.hidden_field :date, :value=>params[:data][:date] %>\r\n<div class=\"w-box\">\r\n<!--<div id=\"132-F1376173358\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">-->\r\n<div class=\"form-horizontal well\">\r\n<!--<b>Personal Information</b>-->\r\n<p class=\"f_legend\">Patient Information</p>\r\n<!--</div>-->\r\n\r\n<div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;margin: 0 0.5em 0.5em 0;float:left;width:140px;min-height:30px;\">\r\n<!--<span class=\"\">