ed\"\'\r\n        end\r\n        if list_hospital.include? k or list_hospital.empty?\r\n%>\r\n        <option value=\"<%=k%>\"<%=sel.html_safe%>><%=v%></option>\r\n<%\r\n        end\r\n    end\r\n%>\r\n    </select>\r\n</div>\r\n\r\n<div class=\"row-fluid\"></div>\r\n\r\n<div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;margin: 0 0.5em 0.5em 0;float:left;width:240px;min-height:30px;\">\r\n    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Prefix name : </label></span>	\r\n    <select name=\"record[prefix_name]\" id=\"data-prefix_name\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n        <option value=\"นาย\">นาย</option>\r\n        <option value=\"นาง\">นาง</option>\r\n        <option value=\"นางสาว\">นางสาว</option>\r\n    </select>\r\n</div>\r\n\r\n<div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\">\r\n    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n</div>\r\n\r\n<div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\">\r\n    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<div id=\"height\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Height (cm.) : </label></span>	\r\n    <input type=\"text\" name=\"record[height]\" id=\"data-height\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div id=\"weight\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Weight (kg.) : </label></span>	\r\n    <input type=\"text\" name=\"record[weight]\" id=\"data-weight\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div id=\"bmi\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>BMI : </label></span>	\r\n    <input type=\"text\" name=\"record[bmi]\" id=\"data-bmi\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Birth date (dd/mm/yyyy) : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n\r\n<span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\"><input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"2015-03-08 20:44:27 +0700\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n<script>\r\n	$(\"#data-birth_date\").kendoDatePicker({\r\n		value: \'<%= Time.now.strftime(\'%d/%m/%Y\')%>\',\r\n	});\r\n</script>\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Gender : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n\r\n<select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n<option value=\"1\">Male</option>\r\n<option value=\"2\">Female</option>\r\n<option value=\"0\">NA</option>\r\n</select>\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<%= hidden_field_tag :return, params[:return] %>\r\n<%= f.submit \'Submit\', :class=>\'btn\' %>\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n<script>\r\n    function bmi_update() {\r\n        // txt = $(this).val();\r\n        // num = isNaN(parseInt(txt)) ? 0 : parseInt(txt);\r\n        \r\n        h = isNaN(parseFloat($(\'#data-height\').val())) ? 0 : parseFloat($(\'#data-height\').val());\r\n        w = isNaN(parseFloat($(\'#data-weight\').val())) ? 0 : parseFloat($(\'#data-weight\').val());\r\n        \r\n        h = h/100;\r\n        bmi = 0\r\n        if (h != 0) {\r\n            bmi = w / (h * h)\r\n            $(\'#data-bmi\').val(bmi.toFixed(2));\r\n            // console.log(\'BMI = \' + bmi)\r\n        }\r\n        // console.log(\'bmi_update h(\' + h + \'), w(\' + w + \')\');\r\n    }\r\n\r\n    $(document).ready(function(){\r\n        // console.log(\'ready\');\r\n        \r\n        $(\'#data-bmi\').val(\'0.00\');\r\n        \r\n        $(\'#data-height\').change(bmi_update);\r\n        $(\'#data-weight\').change(bmi_update);\r\n        // console.log(\'finish\');\r\n    });\r\n</script>',NULL,NULL,NULL,'2015-04-19 16:04:33','2015-04-19 16:04:33','create_old',''),(1426,'create',668,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n\r\n\r\n\r\n    date = Time.now.strftime(\"%d/%m/%Y\")\r\n    time = Time.now.strftime(\"%H:%M\")\r\n    \r\n    # date = params[:date] if params[:date]\r\n    # time = params[:time] if params[:time]\r\n    \r\n%>\r\n<%= params[:date] %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n    if request.post?   \r\n\r\n        doc = get_document this.document_name\r\n        record = doc.record_create(model,params)\r\n        m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n        flash[:notice]=\'New record has been created\'\r\n        \r\n        models = get_model\r\n        \r\n        procedure = (models[:procedure]).find(record.procedure)\r\n    \r\n        if procedure\r\n    \r\n            proc_record = models[procedure.code.to_sym].create \r\n            m = @module_model.create :patient_id=>params[:patient_id],:module_id=>proc_record.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{procedure.code}\",:date=>params[:date],:time=>params[:time],:parent_id=>m.id,:ref_number=>params[:ref_number]\r\n    \r\n        end\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\nwindow.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\n// window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% elsif params[:record][:id] %>\r\nwindow.location = \"../Home/patient_record?id=<%= params[:record][:id] %>\"\r\n<% else %>\r\nwindow.location = \"../Home/index\"\r\n<% end %>\r\n\r\n// window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n        record = model.new params[:data] \r\n    else\r\n        record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\'), :html=>{:id=>\'app_create\'} do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <!--zamachita remove search patient header -->\r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\' %> \r\n<%= hidden_field_tag \'ref_number\',ref_number %> \r\n<%= hidden_field_tag \'date\',Time.now %> \r\n<%= hidden_field_tag \'time\',Time.now.strftime(\"%H:%M\") %> \r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= date %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\n\r\n   function newPatient(){\r\n    alert(\'jdiofj\')\r\n    $.ajax({\r\n		  url: \"../Patient/create?return=<%=params[:return]%>\",\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n   }\r\n\r\nfunction doSearch(){\r\n    	$(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n    \r\n    \r\n    \r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n    // $(\"#app_create\").submit();\r\n</script>   \r\n',NULL,NULL,NULL,'2015-04-19 19:04:24','2015-04-19 19:04:24','create',''),(1427,'report',666,2,'<%\r\n    if !session[:owner]\r\n%>\r\n<script>\r\n    window.location = \'../Home/index\'\r\n</script>\r\n<%\r\n    end\r\n%>\r\n<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% 12px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n        </style>\r\n            <!-- lightbox -->\r\n            <script src=\"/gebo/lib/colorbox/jquery.colorbox.min.js\"></script>\r\n            <!-- common functions -->\r\n			<script src=\"/gebo/js/gebo_common.js\"></script>\r\n            <!-- sticky messages -->\r\n            <script src=\"/gebo/lib/sticky/sticky.min.js\"></script>\r\n            \r\n            <script src=\"/gebo/lib/qtip2/jquery.qtip.min.js\"></script>\r\n        <!-- charts -->\r\n			<script src=\"/gebo/lib/flot/jquery.flot.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.resize.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.pie.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.curvedLines.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.orderBars.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.multihighlight.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.pyramid.min.js\"></script>\r\n			<script src=\"/gebo/lib/moment_js/moment.min.js\">\r\n			   \r\n		</script>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                Report\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                            <div id=\"accordion1\" class=\"accordion\">\r\n                            \r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											User Statistic\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapseOne1\">\r\n									<!--<div class=\"accordion-body collapse \" id=\"collapseOne1\">-->\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"span6\">\r\n										        Over all operation : <span id=\"data-all_operation\" style=\'color:blue\'></span> cases\r\n										        <div id=\"z_all\" style=\"height:220px;width:80%;margin:40px auto 10px\"></div>\r\n										    </div>\r\n										    <!--\r\n										    <div class=\"span12\">\r\n										        Records by month\r\n										        <div id=\"barz\" style=\"height:220px;width:80%;margin:40px auto 10px\"></div>\r\n										    </div>\r\n										    -->\r\n										</div>\r\n									</div>\r\n								</div>\r\n							\r\n							<!--\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											Public Statistic\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n										    <div id=\"chart\" style=\"border:1px solid;width:100%;min-height:300px\"></div>\r\n										</div>\r\n									</div>\r\n								</div>\r\n							-->\r\n							</div>\r\n					</div>\r\n				</div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<%\r\n    if true\r\n%>\r\n\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    patients =  module_model.all(:module_name=>mname)\r\n    \r\n    \r\n    list = []\r\n    \r\n    \r\n    \r\n    list = module_model.collection.group({:keyf=>\'function(doc){return {month:doc.date.getMonth(),name:doc.module_name};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}})\r\n          \r\n          \r\n        columns=[]\r\n        \r\n        mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n       \r\n        map = {}\r\n        data = []\r\n             \r\n    if list.size>0    \r\n        for i in list\r\n            columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n            name = i[\'name\'].split(\'#\')[1]\r\n            map[name] = {\'name\'=>name.humanize, \'data\'=>[]} unless map[name] \r\n            map[name][\'data\'][i[\'month\'].to_i] = i[\'count\'].to_i\r\n        end\r\n    end\r\n    \r\n    map.each_pair do |k,v|\r\n        if k != \'appointment\' \r\n            data.push(v)\r\n        end\r\n    end\r\n    columns = mlabels\r\n\r\n%>\r\n            <script>\r\n                function createChart() {\r\n                    $(\"#chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                }\r\n\r\n                $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n                });\r\n            </script>\r\n<%\r\n    end\r\n%>\r\n\r\n\r\n<%\r\n    \r\n        ehr_model = model\r\n        model = get_model\r\n        \r\n        m_pat_mod = module_model\r\n        # a_pat_mod = m_pat_mod.where([\'module_name LIKE ?\', \"%\\\\#{@current_preoject.name}%\"]).all.group_by{|i| i[:module_name]}\r\n        fields = {:module_name=>@current_project.name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n        # patients = patient_model.where(criteria).limit(20).all\r\n        a_pat_mod = m_pat_mod.where({\"$or\"=>[{:module_name=>/taig/}]}).all.group_by{|i| i[:module_name]}\r\n        \r\n        # provider\r\n        # chinp : 554e5628790f9b0289000015\r\n        # viroj : 55ac60ea790f9b0b31000011\r\n        # chaiwat : 554ef571790f9b439c000002\r\n        # 1. get patient_id from provider\r\n        # 2. each patient get form from module_name, module_id\r\n        # 3. manipulate each module_name, module_id\r\n        \r\n        # get provider id from ... search in provider.where(:login=>@current_user.login)\r\n        \r\n        ehr_model = ehr.load_model\r\n        m_user = ehr_model[:user]\r\n        m_pat_mod = ehr_model[:patient_module]\r\n        \r\n        this_model = get_model\r\n        m_provider = this_model[:provider]\r\n        \r\n        r_user = m_user.all\r\n        r_provider = this_model[:provider].all\r\n        \r\n        prov_id = \'554ef571790f9b439c000002\' # Aj.Chaiwat\r\n        # prov_id = \'55ac60ea790f9b0b31000011\' # Aj.Viroj\r\n        # prov_id = \'554e5628790f9b0289000015\' # Aj.Chinp\r\n        l_hk  = [\'knee1\', \'knee2\', \'hip1\', \'hip2\']\r\n        m_hk = [:knee1, :knee2, :hip1, :hip2]\r\n        a_pat = m_pat_mod.where(:module_id=>prov_id).all.collect{|i| i[:patient_id].to_s}.uniq\r\n        a_dat = m_pat_mod.where(:patient_id=>a_pat).all.collect{|i| {:module_name=>i[:module_name], :module_id=>i[:module_id]}}.group_by{|i| i[:module_name]}\r\n        \r\n        res = {}\r\n        a_dat.each do |k,v|\r\n            mname = k.split(\'#\')[1]\r\n            if m_hk.include? mname.to_sym\r\n                ids = v.collect{|i| i[:module_id]}\r\n                all = model[mname.to_sym].where(:id=>ids).all.collect{|i| {:side=>i[:side], :operation_date=>i[:operation_date]}}\r\n                tmp = all.group_by{|i| i[:side]}\r\n                \r\n                res[mname.to_sym] = tmp\r\n            end\r\n        end\r\n        \r\n\r\n    map_s = {\'1\'=>\'(L)\', \'2\'=>\'(R)\'}\r\n    map_hk = {:hip1=>\'Primary Hip \', :hip2=>\'Revision Hip \', :knee1=>\'Primary Knee \', :knee2=>\'Revision Knee \'}\r\n    dat = []\r\n    xxx = {}\r\n    sum = 0\r\n    res.each do |k,v|\r\n        label = map_hk[k.to_sym]\r\n        tmp = {}\r\n        x = {:label=>label+map_s[\'1\']+\" [\\\\#{v[\'1\'].count}]\",:data=>v[\'1\'].count} if v.has_key?\'1\';\r\n        dat.push(x) if x\r\n        sum += x[:data] if x\r\n        \r\n        x = {:label=>label+map_s[\'2\']+\" [\\\\#{v[\'2\'].count}]\",:data=>v[\'2\'].count} if v.has_key?\'2\';\r\n        sum += x[:data] if x\r\n        dat.push(x) if x\r\n        \r\n        if v.has_key?\'1\'\r\n            xxx[k] = v[\'1\'].group_by { |t| [t[:operation_date].month,t[:operation_date].year] }\r\n        end\r\n    end\r\n    \r\n    # xxx = {}\r\n        # a_dat.each do |k,v|\r\n        #     mname = k.split(\'#\')[1]\r\n        #     if m_hk.include? mname.to_sym\r\n        #         ids = v.collect{|i| i[:module_id]}\r\n        #         all = model[mname.to_sym].where(:id=>ids).all.collect{|i| {:side=>i[:side], :operation_date=>i[:operation_date]}}\r\n        #         tmp = all.group_by{|i| [i[:operation_date].month,i[:operation_date].year]}\r\n                \r\n        #         xxx[mname.to_sym] = tmp\r\n        #     end\r\n        # end\r\nif @current_role == \'developer\'    \r\n    \r\n        \r\n%>\r\n<pre>\r\n    <!--<%= keys %> | <%= criteria %>-->\r\n    <%# a_pat.to_json.html_safe %>\r\n    <%# a_dat.to_json.html_safe %>\r\n    <%= xxx.to_json.html_safe %>\r\n    <%# res.to_json.html_safe %>\r\n    \r\n    <%# dat.to_json.html_safe %>\r\n    \r\n    <%# a_dat.group_by{|i| i[:module_name]}.to_json.html_safe %>\r\n    <%# a_pat_mod.to_json.html_safe %>\r\n    <%# r_provider.to_json.html_safe %>\r\n</pre>\r\n<%\r\n    end\r\n    \r\n    \r\n%>\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n		z_charts.z_all();\r\n		\r\n		$(\'#data-all_operation\').html(\"<%= sum %>\");\r\n	});\r\n    z_charts = {\r\n        z_all : function() {\r\n			// Setup the placeholder reference\r\n            var elem = $(\'#z_all\');\r\n\r\n\r\n			var data = <%= dat.to_json.html_safe %>;\r\n			\r\n            var colors = [ \"#b4dbeb\", \"#8cc7e0\", \"#64b4d5\", \"#3ca0ca\", \"#2d83a6\", \"#22637e\", \"#174356\", \"#0c242e\" ];\r\n            \r\n			// Setup the flot chart using our data\r\n            function a_plotWithColors() {\r\n                fl_a_plot = $.plot(elem, data,         \r\n                    {\r\n                        label: \"Visitors by Location\",\r\n                        series: {\r\n                            pie: {\r\n                                show: true,\r\n                                innerRadius: 0.5,\r\n                                highlight: {\r\n                                    opacity: 0.2\r\n                                }\r\n                            }\r\n                        },\r\n                        grid: {\r\n                            hoverable: true,\r\n                            clickable: true\r\n                        },\r\n                        colors: colors\r\n                    }\r\n                );\r\n            }\r\n        \r\n            a_plotWithColors();\r\n            \r\n            \r\n            // Create a tooltip on our chart\r\n            elem.qtip({\r\n                prerender: true,\r\n                content: \'Loading...\', // Use a loading message primarily\r\n                position: {\r\n                    viewport: $(window), // Keep it visible within the window if possible\r\n                    target: \'mouse\', // Position it in relation to the mouse\r\n                    adjust: { x: 7 } // ...but adjust it a bit so it doesn\'t overlap it.\r\n                },\r\n                show: false, // We\'ll show it programatically, so no show event is needed\r\n                style: {\r\n                    classes: \'ui-tooltip-shadow ui-tooltip-tipsy\',\r\n                    tip: false // Remove the default tip.\r\n                }\r\n            });\r\n         \r\n            // Bind the plot hover\r\n            elem.on(\'plothover\', function(event, pos, obj) {\r\n                \r\n                // Grab the API reference\r\n                var self = $(this),\r\n                    api = $(this).qtip(),\r\n                    previousPoint, content,\r\n         \r\n                // Setup a visually pleasing rounding function\r\n                round = function(x) { return Math.round(x * 1000) / 1000; };\r\n         \r\n                // If we weren\'t passed the item object, hide the tooltip and remove cached point data\r\n                if(!obj) {\r\n                    api.cache.point = false;\r\n                    return api.hide(event);\r\n                }\r\n         \r\n                // Proceed only if the data point has changed\r\n                previousPoint = api.cache.point;\r\n                if(previousPoint !== obj.seriesIndex)\r\n                {\r\n                    percent = parseFloat(obj.series.percent).toFixed(2);\r\n                    // Update the cached point data\r\n                    api.cache.point = obj.seriesIndex;\r\n                    // Setup new content\r\n                    content = obj.series.label + \' ( \' + percent + \'% )\';\r\n                    // Update the tooltip content\r\n                    api.set(\'content.text\', content);\r\n                    // Make sure we don\'t get problems with animations\r\n                    //api.elements.tooltip.stop(1, 1);\r\n                    // Show the tooltip, passing the coordinates\r\n                    api.show(pos);\r\n                }\r\n            });\r\n		}\r\n    };\r\n    <% if false %>\r\n    charts = {\r\n        barz = function() {\r\n            var elem = $(\'#barz\');\r\n        }\r\n    };\r\n<% end %>\r\n</script>',NULL,NULL,NULL,'2015-04-20 03:36:56','2015-04-20 03:36:56','report',''),(1428,'show',668,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n\r\n\r\n<%= this.display.html_safe %>\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%# link_to \'Back\', return_url %>\r\n<%= link_to \'Back\', \"../Home/index\" %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2015-04-20 04:07:05','2015-04-20 04:07:05','show',''),(1429,'document_name',669,1,'\'finding\'',NULL,NULL,NULL,'2015-04-21 19:29:34','2015-04-21 19:29:34',NULL,NULL),(1430,'document_name',670,1,'\'location\'',NULL,NULL,NULL,'2015-04-21 19:29:53','2015-04-21 19:29:53',NULL,NULL),(1431,'document_name',671,1,'\'intervention\'',NULL,NULL,NULL,'2015-04-21 19:30:23','2015-04-21 19:30:23',NULL,NULL),(1432,'document_name',672,1,'\'disease\'',NULL,NULL,NULL,'2015-04-21 19:30:47','2015-04-21 19:30:47',NULL,NULL),(1433,'form',657,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n    function bmi_update(){\r\n        console.log(\'>>> \' + $(this).val());\r\n        weight = $(\'#data-weight\').val();\r\n        height = $(\'#data-height\').val();\r\n        weight = parseFloat(weight);\r\n        height = parseFloat(height)/100;\r\n        if(weight!=0&&height!=0){\r\n            bmi = weight/(height*height)\r\n            $(\'#data-bmi\').val(bmi.toFixed(2))\r\n        }\r\n                \r\n    }\r\n    \r\n    $(document).ready(function(){\r\n        \r\n        tmp_bmi = $(\"#data-bmi\").val();\r\n        if (tmp_bmi == \'\') {\r\n            $(\"#data-bmi\").val(\"0\");\r\n        }\r\n        console.log(\'BMI = \' + tmp_bmi);\r\n        $(\'#data-weight\').change(bmi_update);\r\n        $(\'#data-height\').change(bmi_update);\r\n        bmi_update();\r\n    });\r\n</script>\r\n',NULL,NULL,NULL,'2015-04-22 15:35:23','2015-04-22 15:35:23','form',''),(1434,'print',657,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm/cusys/anesthetic/content/PNI-logo-2.png\" height=\"60px\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3><%=this.table_name.to_s.humanize%></h3>\r\n<%= this.display.html_safe %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div class=\"hideprint\">\r\n<%= link_to \'Back\', url(\'index\') %>\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2015-04-22 16:02:20','2015-04-22 16:02:20','print',''),(1435,'document_name',673,1,'\'myfinding\'',NULL,NULL,NULL,'2015-04-22 17:31:34','2015-04-22 17:31:34',NULL,NULL),(1436,'create',674,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=@current_service.title %></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border-x\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n\r\n  return_url = \"../Home/patient_record?id=\\\\#{@appointment.id}\"\r\n\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    @patient_module = m\r\n    \r\n    # change status to \'Completed\' when created document\r\n    @appointment.update_attributes :status=>\'Recovery\'\r\n   \r\n    # require \'pdfkit\'\r\n    # url = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{@current_service.name}/pdf?id=\\\\#{@patient_module.id}\"\r\n    # kit = PDFKit.new(url,:margin_top => \'0.2in\',:margin_right => \'0.2in\',:margin_bottom => \'0.2in\')\r\n    # report = \"tmp/cache/\\\\#{@patient_module.id.to_s}.pdf\"\r\n    # file = kit.to_file(report)\r\n    # field = @module_doc .find_by_column_name \'report\'\r\n    # att = @module_doc .attach_field_file field.id, report, \'\', File.open(report)\r\n    # @patient_module.update_attributes :report=>att.id\r\n \r\n    url = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{@current_service.name}/pdf?id=\\\\#{@patient_module.id}\"\r\n    attach_pdf = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{@current_service.name}/attach_pdf?id=\\\\#{@patient_module.id}\"\r\n    \r\n    id = @patient_module.id.to_s\r\n    path = \"test\"\r\n    require_relative \'app/models/workers/pdf_generator\'\r\n    PdfGenerator.enqueue :url=>url,:id=>id,:path=>path,:return=>attach_pdf\r\n    \r\n\r\n \r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') ,:html=>{:id=>\'form-id\'} do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:100%;border:1px solid #ccc\" >\r\n<center>\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</center>\r\n    \r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    param