iangle\').each(function(){\r\n        $(this).addClass(\'splashy-check\')\r\n        $(this).removeClass(\'splashy-warning_triangle\')\r\n    })\r\n<%\r\n    mapp = @module_model.find(@patient_module.parent_id)\r\n    @appointment = get_model(\'appointment\').find(mapp.module_id)\r\n%>\r\n<%\r\nif @appointment.visit_type and @appointment.visit_type!=\'\'\r\n\r\n\r\nvisit = get_model(\'visit_type\').find(@appointment.visit_type)\r\nif visit    \r\n%>\r\n$(\'#data-schedule\').val(\'<%=visit.ref_id%>\')\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n})\r\n\r\n</script>   \r\n\r\n<script>jQuery(\"body\").addClass(\"sidebar_hidden_force\");jQuery(\"#sidebar_bt\").hide();</script>\r\n\r\n',NULL,NULL,NULL,'2015-04-22 17:34:24','2015-04-22 17:34:24','edit',''),(1438,'show',674,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block;font-size: 1em;margin: 0px;line-height: normal;\"><%=@current_service.title%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print Images\'.html_safe, \"select_images?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' if record.image.size > 5  %>\r\n\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:980px\">\r\n\r\n\r\n\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n <div style=\"padding:5px;width:720px; margin-left:auto; margin-right:auto\" >\r\n\r\nRef : <%= @patient_module.ref_number %> \r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n<p style=\"width:720px; margin-left:auto; margin-right:auto; font-weight:bold\">HN : <%= @patient.hn %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Name : <%= @patient.first_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Surname : <%= @patient.last_name %></p>\r\n<hr /><br />\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<style>\r\n    @media print {\r\n  body * {\r\n    visibility: hidden;\r\n  }\r\n  #section-to-print, #section-to-print * {\r\n    visibility: visible;\r\n  }\r\n  #section-to-print {\r\n    border:1px solid;\r\n    position: absolute;\r\n    left: 0px;\r\n    top: 0px;\r\n    right:100px;\r\n    width:960px;\r\n    overflow:hidden;\r\n  }\r\n}\r\n</style>\r\n\r\n<div style=\"padding:20px\" id=\"section-to-print2\">\r\n<%\r\n   atts = @ehr_project.get_model :attachment\r\n   att =  atts.find(@patient_module.report)\r\n   if att\r\n%>\r\n<%# att.inspect  %>\r\n<embed src=\"<%= att.path%>\" width=\"960\" height=\"768\"/>\r\n<% else %>\r\n<%= this.print_partial.html_safe %>\r\n<% end %>\r\n\r\n\r\n</div>\r\n\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:class=>\"btn btn-success\",:target=>\'_blank\' %> |\r\n<% if att %>\r\n<%= link_to \'Download PDF\', att.path ,:class=>\"btn btn-success\",:target=>\'_blank\' %> |\r\n<% else %>\r\nPDF generating.. | \r\n<% end %>\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2015-04-22 17:34:35','2015-04-22 17:34:35','show',''),(1439,'attach_pdf',674,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %><%\r\n\r\n \r\n    if params[:path]\r\n        \r\n    field = @module_doc .find_by_column_name \'report\'\r\n    att = @module_doc .attach_field_file field.id, params[:path].split(\'/\')[-1] , \'\', File.open(params[:path])\r\n    @patient_module.update_attributes :report=>att.id\r\n    \r\n    %>\r\n    OK\r\n    <%\r\n    else\r\n    %>\r\n    Error\r\n    <%\r\n    end\r\n%>',NULL,NULL,NULL,'2015-04-22 17:34:46','2015-04-22 17:34:46','attach_pdf','*'),(1440,'display',674,3,'\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n\r\n  models = get_model\r\n  model = models[this.table_name.to_sym]\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @record = record\r\n \r\n  @document = @current_project.get_document this.document_name \r\n%>\r\n\r\n<%\r\n\r\n  root_data_node, root_fields_node, map, fmap = @document.get_root_format_node @record\r\n  \r\n%>\r\n\r\n<%= render :partial=>\'/esm_documents/hidden_field.html\' %>\r\n<%= render :partial=>\'/esm_documents/tree_helper.html\' %>\r\n<%= render :inline=>this.display_script,:locals=>{:document_name=>this.document_name} %>\r\n\r\n<script type=\"text/javascript\" charset=\"utf-8\">\r\n var map = <%=map.to_json.html_safe%>\r\n var fmap = <%=fmap.to_json.html_safe%>\r\n var master = <%=@document.get_mapping_master().to_json.html_safe %>;\r\n var model = \'<%=@document.name%>\'\r\n tree = new ESMTree(\'<%=@document.name%>\',model, map, fmap, master);\r\n esm_helper.push(\'<%=@document.name%>\',tree)\r\n $(\'#form-data\').hide()\r\n tree = esm_helper.get(\'<%=@document.name%>\')     	\r\n\r\n\r\n\r\n</script>\r\n<div id=\"findings\" style=\"display:none\"></div>',NULL,NULL,NULL,'2015-04-22 17:34:53','2015-04-22 17:34:53','display',''),(1441,'form',674,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= view :fullwidth %>\r\n<style>\r\n    /* bootstrap.css */\r\n* {\r\n   font-size: 15px;\r\n   line-height: 1.5em;\r\n}\r\nlabel{\r\n    font-size:15px;\r\n}\r\n</style>\r\n\r\n<%\r\n    if @current_role==\'capture\' or @current_role==\'developer\'\r\n%>\r\n    <div class=\"alert\">\r\n		<!--<h4 class=\"alert-heading\">Endo Button</h4>-->\r\n		<div style=\'float:left\' id=\'btn-form\'>&nbsp;</div>\r\n		<div style=\'float:right\' id=\'btn-snap\'>&nbsp;</div>\r\n		<br/>\r\n		&nbsp;\r\n	</div>\r\n<%\r\n    end\r\n%>\r\n\r\n<div style=\";font-size:1.2em;line-height:1.2em\">\r\n<%= render :partial=>\'/esm_documents/show_tree_layout.html\' %>\r\n<%= render :partial=>\'/esm_documents/tree_helper.html\' %>\r\n</div>\r\n<script>\r\n    function leftPad(number, targetLength) {\r\n    var output = number + \'\';\r\n    while (output.length < targetLength) {\r\n        output = \'0\' + output;\r\n    }\r\n    return output;\r\n}\r\n\r\n\r\n       function parseDate(d,t){\r\n    \r\n    l = d.split(\"/\");\r\n    year = parseInt(l[2])\r\n    month = parseInt(l[1])\r\n    day = parseInt(l[0])\r\n    \r\n    if(year>2400)year-=543\r\n\r\n    if(t.length<5){\r\n    t = \"0\"+t\r\n    }\r\n    \r\n    text = \"\"+year+\"-\"+leftPad(month, 2)+\"-\"+leftPad(day, 2)+\"T\"+t;\r\n\r\n    date = new Date(Date.parse(text));\r\n    \r\n    return date;\r\n    }\r\n    \r\n    function procedural_cal(){\r\n   \r\n   start_procedural_time = $(\'#data-start_procedural_time\').val()\r\n   stop_procedural_time = $(\'#data-stop_procedural_time\').val()\r\n//   alert($(\'#data-start_procedural_date\').val())\r\n   start_procedural_date = parseDate($(\'#data-start_procedural_date\').val(),start_procedural_time)\r\n   stop_procedural_date = parseDate($(\'#data-start_procedural_date\').val(),stop_procedural_time)\r\n//   (start_procedural_date)\r\n//   alert(stop_procedural_date)\r\n   \r\n   min = (stop_procedural_date-start_procedural_date)/60000\r\n\r\n   hour = Math.floor(min / 60)\r\n   min = min % 60\r\n\r\n   $(\'#data-procedural_time\').val(\"\"+hour+\":\"+min)\r\n    \r\n}\r\n\r\n$(\'#data-start_procedural_time\').change(procedural_cal);\r\n$(\'#data-stop_procedural_time\').change(procedural_cal);\r\n\r\nprocedural_cal();\r\n    \r\n</script>\r\n<script>jQuery(\"body\").addClass(\"sidebar_hidden_force\");jQuery(\"#sidebar_bt\").hide();\r\n    \r\n  \r\n$( document ).ready(function() {\r\n      \r\n      \r\n$( \"#form-id\" ).submit(function( event ) {\r\n \r\n});\r\n      \r\n      $(\'#validation-\').appendTo($(\'#report-msg\'))\r\n      \r\n      \r\n      updateReport();\r\n      \r\n$(\'.notification-tab\').each(function(){\r\n   $(this).css(\"display\",\'inline-block\')\r\n    \r\n});    \r\n      \r\n      \r\n});\r\n</script>\r\n\r\n<%\r\n        require \'csv\'\r\n        icd10_list = []\r\n        CSV.foreach(File.join(Dir.pwd,\'public\',\'/esm/cusys/med/icd-10.csv\')) do |row|\r\n           icd10_list << [row[0],row[1]] \r\n        end\r\n    %>\r\n\r\n\r\n\r\n<script>\r\n\r\n    $(document).ready(function(){\r\n    $(\"#icd10-panel\").appendTo(\"#icd10\");\r\n    $(\"#data-icd10\").hide();\r\n\r\n    });\r\n\r\n</script>\r\n\r\n  <style>\r\n  #sortable-icd10 { }\r\n  #sortable-icd10 li {   list-style-type: none; margin: 0 3px 3px 3px; padding: 0.4em; padding-left: 0.5em; font-size: 1.2em; height: 18px; }\r\n  #sortable-icd10 li span { position: absolute; margin-left: -1.3em; }\r\n  #select-icd10  { margin: 0 3px 3px 3px; padding: 0.4em; font-size: 1.2em; }\r\n  /*#select-icd10 .multiselect {width 400px}*/\r\n  /*#select-icd10 li span { position: absolute; margin-left: -1.3em; }*/\r\n  \r\n  </style>\r\n    \r\n<div id=\"icd10-panel\" class=\"span6\" style=\"display:block;width:600px\">\r\n<h1>ICD10\r\n    <input type=\"text\" id=\"search-icd10\" >\r\n<input type=\"button\" value=\'Add\' style=\"width:80px\" class=\"btn btn-success\" id=\"add-icd10\">\r\n    \r\n</h1><i># First ICD is the principle diagnosis, drag to sort ICD order.</i>\r\n<select multiple=\"multiple\" class=\"multiselect\" id=\"select-icd10\" style=\"width:600px;display:none\">\r\n</select>\r\n\r\n<ul id=\"sortable-icd10\" style=\"width:600px;border:1px solid;min-heigth:24px;display:block\">\r\n\r\n</ul>\r\n\r\n  \r\n	</div>\r\n<script>\r\n    // Zam added button\r\n    \r\n    $(document).ready(function() {\r\n<%\r\n    if (@current_role==\'capture\' or @current_role==\'developer\')\r\n        if params[:opt] == \'create\' or params[:opt] == \'edit\'\r\n%>\r\n        frm_submit = $(\'#record-submit\').clone();\r\n        frm_cancel = $(\'#record-submit\').next().clone();\r\n        frm_cancel = frm_cancel.addClass(\'btn btn-small\')\r\n        frm_submit = frm_submit.addClass(\'btn btn-success btn-small\')\r\n        \r\n        btn_form = $(\'#btn-form\');\r\n        btn_form.append(frm_submit);\r\n        btn_form.append(\'&nbsp;&nbsp;|&nbsp;&nbsp;\');\r\n        btn_form.append(frm_cancel);\r\n\r\n<%\r\n        end\r\n%>\r\n        snap = $( \"a:contains(\'Snap\')\" ).clone();\r\n        snap = snap.addClass(\'btn btn-small btn-info\');\r\n        btn_snap = $(\'#btn-snap\');\r\n        btn_snap.append(snap);\r\n        \r\n        $(\'input\').prop(\'required\', null);\r\n        $(\'select\').prop(\'required\', null);\r\n<%\r\n    end\r\n%>\r\n    });\r\n\r\n<%\r\n    if false\r\n        a = [{:text=>\'\',:value=>\'\'}]\r\n        b = get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).collect{|i| {:text=>\"\\\\#{i[:name]} \\\\#{i[:license_number]}\", :value=>\"\\\\#{i.id.to_s}\"}}.sort_by{|i| i[:text]}\r\n        d_prov = a + b\r\n%>\r\n    var ds_prov = <%= d_prov.to_json.html_safe %>;\r\n    \r\n    $(document).ready(function() {\r\n            var tmp = $(\'input[name=\"record[endoscopist]_input\"]\').val();\r\n            $(\"#data-endoscopist\").kendoComboBox({\r\n                dataTextField: \"text\",\r\n                dataValueField: \"value\",\r\n                filter: \"contains\",\r\n                dataSource: ds_prov,\r\n                change: function(e) {\r\n                    var widget = e.sender;\r\n        \r\n                    if (widget.value() && widget.select() === -1) {\r\n                      //custom has been selected\r\n                      widget.value(\"\"); //reset widget\r\n                    }\r\n                }\r\n            });\r\n            $(\'input[name=\"record[endoscopist]_input\"]\').css(\'height\', \'\');\r\n            $(\'input[name=\"record[endoscopist]_input\"]\').val(tmp);\r\n            console.log(\"::: \" + tmp)\r\n            \r\n            // $(\"#data-recorder\").kendoComboBox({\r\n            //     dataTextField: \"text\",\r\n            //     dataValueField: \"value\",\r\n            //     filter: \"contains\",\r\n            //     dataSource: ds_prov,\r\n            //     change: function(e) {\r\n            //         var widget = e.sender;\r\n        \r\n            //         if (widget.value() && widget.select() === -1) {\r\n            //           //custom has been selected\r\n            //           widget.value(\"\"); //reset widget\r\n            //         }\r\n            //     }\r\n            // });\r\n            // $(\'input[name=\"record[recorder]_input\"]\').css(\'height\', \'\');\r\n            // $(\"#data-endoscopist_approve\").kendoComboBox({\r\n            //     dataTextField: \"text\",\r\n            //     dataValueField: \"value\",\r\n            //     filter: \"contains\",\r\n            //     dataSource: ds_prov,\r\n            //     change: function(e) {\r\n            //         var widget = e.sender;\r\n        \r\n            //         if (widget.value() && widget.select() === -1) {\r\n            //           //custom has been selected\r\n            //           widget.value(\"\"); //reset widget\r\n            //         }\r\n            //     }\r\n            // });\r\n            // $(\'input[name=\"record[endoscopist_approve]_input\"]\').css(\'height\', \'\');\r\n            \r\n    });\r\n\r\n\r\n<%\r\n    end\r\n%>\r\n\r\n\r\n\r\n\r\n  $(function() {\r\n      \r\n    var icd10_list = <%=icd10_list.to_json.html_safe%>\r\n    \r\n    function refreshICD10(){\r\n            res = []\r\n            $( \".icd10\" ).each(function(  ) {\r\n                obj = $( this );\r\n                res.push(obj.attr(\'name\'));\r\n            });\r\n            $(\'#data-icd10\').val(res.join(\"|\"));\r\n            \r\n            // var order = $(\"#sortable\").sortable(\"serialize\", {key:\'order[]\'});\r\n            // $( \"p\" ).html( order );\r\n        \r\n        \r\n    }\r\n    function removeICD10(){\r\n        $(this).parent().remove()\r\n        refreshICD10();\r\n    }\r\n          \r\n    $( \"#sortable-icd10\" ).sortable();\r\n    $( \"#sortable-icd10\" ).sortable({\r\n        stop: refreshICD10\r\n    });\r\n    \r\n \r\n    \r\n    $(\'#add-icd10\').click(function (){\r\n        select_icd10 = $(\'#select-icd10\')\r\n        values = select_icd10.val();\r\n    \r\n        sortable_icd10 = $(\'#sortable-icd10\')\r\n     \r\n        for(var idx in values){\r\n            idc = values[idx];\r\n            \r\n            title = \'\'\r\n            for(var idx2 in icd10_list){\r\n                if(idc==icd10_list[idx2][0]){\r\n                    title=icd10_list[idx2][1]\r\n                }\r\n            }\r\n            \r\n            sortable_icd10.append($(\'<li>\', {\r\n                class: \"ui-state-default icd10\",\r\n                name: idc,\r\n                text: \"+ \"+idc+\" : \"+title\r\n            }).append($(\'<a>\').click(removeICD10).append(\" [ - ] \"))\r\n            );\r\n                \r\n                \r\n              \r\n        }\r\n        select_icd10.empty();\r\n        select_icd10.hide();\r\n        \r\n         res = []\r\n            $( \".icd10\" ).each(function( index ) {\r\n                res.push($( this ).attr(\'name\'));\r\n            });\r\n            $(\'#data-icd10\').val(res.join(\"|\"));\r\n        \r\n    });\r\n    \r\n    value = $(\'#data-icd10\').val() \r\n    values = value.split(\'|\')\r\n    sortable_icd10 = $(\'#sortable-icd10\')\r\n     for(var idx in values){\r\n            idc = values[idx];\r\n            if(idc!=\'\'){\r\n            title = \'\'\r\n            for(var idx2 in icd10_list){\r\n                if(idc==icd10_list[idx2][0]){\r\n                    title=icd10_list[idx2][1]\r\n                }\r\n            }\r\n            \r\n            sortable_icd10.append($(\'<li>\', {\r\n                class: \"ui-state-default icd10\",\r\n                name: idc,\r\n                text: \"+ \"+idc+\" : \"+title+\"\"\r\n            }).append($(\'<a>\').click(removeICD10).append(\" [ - ] \"))\r\n            \r\n            );\r\n            }\r\n                \r\n                \r\n              \r\n        }\r\n    \r\n    \r\n    \r\n    \r\n    $( \"#search-icd10\" ).keyup(function(){\r\n        q = $(this).val().toLowerCase()\r\n        res = []\r\n        if(q!=\'\'){\r\n            \r\n            \r\n        select_icd10 = $(\'#select-icd10\')\r\n        select_icd10.show();\r\n        select_icd10.empty();\r\n        \r\n        \r\n        \r\n        for(var idx in icd10_list){\r\n            row = icd10_list[idx];\r\n            if(row[0].toLowerCase().indexOf(q)!=-1||row[1].toLowerCase().indexOf(q)!=-1){\r\n                res.push(row)\r\n                console.log(row[1]);\r\n                select_icd10.append($(\'<option>\', {\r\n                value: row[0],\r\n                text: row[0]+\' : \'+row[1]\r\n                }));\r\n                \r\n            }\r\n            \r\n        }\r\n        \r\n        \r\n        }\r\n        \r\n    });\r\n  \r\n  });\r\n  </script>\r\n  \r\n  <%=hidden_field_tag \"na_findings\", \"1\" %>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-04-22 17:35:01','2015-04-22 17:35:01','form',''),(1442,'pdf',674,3,'<%= render :inline=>this.print_partial %>\r\n',NULL,NULL,NULL,'2015-04-22 17:35:10','2015-04-22 17:35:10','pdf','*'),(1443,'print',674,3,'<%= this.print_partial %>\r\n<script>\r\n   \r\n    $(document).ready(function() {\r\n        setTimeout(function(){\r\n        window.print()\r\n        },3000);\r\n    })\r\n    \r\n</script>',NULL,NULL,NULL,'2015-04-22 17:35:16','2015-04-22 17:35:16','print',''),(1444,'print_partial',674,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[this.document_name.to_sym].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'<%=@current_project.get_setting(\'logo_report_path\')%>\' height=\'70px\' style=\"Float:left,top:5px\" /></div><h3> <strong><%=@current_service.title %> Diagnosis Report<br />\r\n<%=@current_project.get_setting(\"report_title_1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%>\r\n  </strong></h3>\r\n</center>\r\n\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> ชื่อ-สกุล : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'ไม่ระบุ\'\r\n    if patient.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>เพศ : </strong><%= gender %> &nbsp; <strong>อายุ :&nbsp;</strong>\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D-->\r\n      <br /><strong>Date :  </strong> <%=render_value \'start_procedural_date\'%> <strong>Produral Time :  </strong> <%=render_value \'start_procedural_time\'%> - <%=render_value \'stop_procedural_time\'%> Total Time :  <%=render_value \'procedural_time\'%>  <strong>Project : </strong> <%=render_value \'study_project\'%>\r\n    <br /><strong>Endoscopist : </strong><%=render_value \'endoscopist\'%>  , <strong>Endoscopist assist : </strong><%=render_value \'assist1endoscopist\'%> <%=render_value \'assist2endoscopist\'%> \r\n    <br /><strong>Nurse : </strong><%=render_value \'nurse\'%> , <strong>Nurse assist : </strong><%=render_value \'assist_1_nurse\'%><%=render_value \'assist_2_nurse\'%>\r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n &nbsp;&nbsp;&nbsp;<strong>Indication : </strong><%=render_value \'clinical_indication\'%><%=render_value \'indication_other_note\'%>\r\n	<hr style=\"margin-top: 5px;\"/>\r\n    <%\r\n        # atts = models[:attachment].limit(5).find(record.image)\r\n       \r\n       atts_list = record.image[0..4]\r\n       if record.selected_image and record.selected_image.size > 0\r\n          \r\n           atts_list = record.selected_image[0..4]\r\n           \r\n       end\r\n       \r\n       \r\n       atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n       \r\n       \r\n\r\n\r\n    %>\r\n\r\n\r\n<style>\r\n<% if @current_solution.name!=\'gi\' %>\r\n.crop {\r\n    width: 300px;\r\n    overflow: hidden;\r\n    margin-bottom:10px;\r\n}\r\n\r\n.crop img {\r\n    width: 320px;\r\n    height: 190px;\r\n    margin: 0px 0px 0px -150px;\r\n}\r\n<% else %>\r\n.crop {\r\n    width: 240px;\r\n    height: 165px;\r\n    margin:5px;\r\n}\r\n\r\n.crop img {\r\n    width: 240px;\r\n    height: 165px;\r\n}\r\n<% end %>\r\n    \r\n</style>\r\n    <div style=\"float:right;  width: 280px;  padding: 5px; text-align:center; font-size:14px;\">\r\n    <% for i in atts  %>\r\n    <div class=\"crop\">\r\n    <img src=\"<%=i.path%>\" /><br /><span style=\"margin-left:-80px\"><%=i.title%></span><br />\r\n    </div>\r\n    <% end %>\r\n\r\n   \r\n    \r\n    </div>\r\n\r\n<div style=\"float:left\">\r\n\r\n\r\n<table width=\"550\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr><td valign=\"top\"><strong>Consent</strong></td><td>The procedure of the examination, including possible complications were clearly and discussed with the patient and family, then a consent form was signed by the patient and/or family</td></tr>\r\n<tr><td valign=\"top\"><strong>Procedure</strong></td>\r\n  <td>The patient\'s blood pressure, pulse and oxygen saturation were montiored ontinuously throghout the procedure. the scope was passed under direct  vision through the mouth and advanced to the duodenum. The endoscopy was accomplished without difficulty. The findings were described below. The patient tolerated the procedure well.</td></tr>\r\n</table>\r\n<div class=\"clear\"></div>\r\n\r\n<%= render :inline=>this.display %>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n<strong>Reported by :</strong>&nbsp;<%=render_value \'recorder\'%><br />\r\n<strong>Printed Date Time :</strong>&nbsp;<%=render_value \'date_approve\' %> <%=render_value \'time_approve\'%>\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong><% if record[\'approve\']!=\"\" %>Approved<% end %> By :</strong> \r\n<%=render_value \'endoscopist_approve\'%> (Gastroenterologist)\r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<script>\r\n\r\n<%\r\n        require \'csv\'\r\n        icd10_list = {}\r\n        CSV.foreach(File.join(Dir.pwd,\'public\',\'/esm/cusys/med/icd-10.csv\')) do |row|\r\n           icd10_list[row[0]]=row[1] \r\n        end\r\n        \r\n%>\r\n    \r\n    var icd10_list = <%=icd10_list.to_json.html_safe%>\r\n    icd = $(\'#data-icd10\').val()\r\n    licd = icd.split(\'|\')\r\n    div = $(\'#diagnosis-div\')\r\n    tr = div.parent().parent()\r\n    icd = $(\"<tr>\").append(\"<td><strong>ICD</strong></td>\")\r\n    for(var id in licd){\r\n        i = licd[id]\r\n        icd.append($(\'<p>\').append(\"<v>\"+i+\"</v> : \"+icd10_list[i]))\r\n        \r\n    }\r\n    tr.after(icd)\r\n    \r\n    \r\n    \r\n    \r\n</script>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2015-04-22 17:35:27','2015-04-22 17:35:27','print_partial',''),(1445,'report_builder_analysis',674,3,'<% s =  @current_project.get_service @current_service.name  \r\ncmd = s.operations.find_by_name \'display\'\r\n\r\n%>\r\n<table>\r\n\r\n<%\r\n   @document =  get_document this.document_name \r\n  vt = Document.visual_types\r\n\r\nfor i in @document.fields\r\n\r\nunless vt.index i.field_type\r\nresult = \'\'\r\nresult = \'background:#cc6\' if i.column_name and cmd.command.index i.column_name \r\n%>\r\n<tr style=\"<%=result%>\">\r\n<td><%=i.name %></td>\r\n<td><%=i.column_name %></td>\r\n<td><%=i.field_type %></td>\r\n    \r\n</tr>\r\n<% end %>\r\n\r\n<% end %>\r\n</table>\r\n',NULL,NULL,NULL,'2015-04-22 17:35:33','2015-04-22 17:35:33','report_builder_analysis',''),(1446,'context_menu',674,4,'<%\r\nreturn_url = \'\'\r\nreturn_url = \"&return=\\#{params[:return]}\" if params[:return]\r\nname = @current_service.title\r\nplist = []\r\nlist = [{:name=>\'List\',:link=>\'index\',:remote=>false},{:name=>name+ \' Creation\' ,:link=>\'create\',:remote=>false},{:name=>name+\" Analysis\",:link=>\'analysis\',:remote=>false}]\r\n\r\nplist<<{:name=>\'Back to Detail\',:link=>params[:return],:remote=>false} if params[:return]\r\n\r\n\r\nif params[:id]\r\nplist<<{:name=>\'Edit \'+name,:link=>\"edit?id=\\#{params[:id]}\\#{return_url}\",:remote=>false}\r\n\r\n\r\n#list<<{:name=>\'Delete\',:link=>\"destroy?id=\\#{params[:id]}\",:remote=>false}\r\nend\r\nlist<<{:name=>\'Back to Home\',:link=>\"../Home/index\",:remote=>false}\r\n%>\r\n<%= show_menu [{:name=>this.document_name.humanize,:open=>true,:actions=>list},\r\n{:name=>\'Patient Detail\',:open=>true,:actions=>plist}\r\n] \r\n\r\n%>\r\n\r\n<%\r\n\r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n\r\n     p_id = @current_project.id\r\n     doc = @current_project.get_document @current_service.name\r\n     img = nil\r\n     mrecord =  @module_model.find(params[:id])\r\n     if mrecord\r\n     record = doc.get_model.find(mrecord.module_id)\r\n     for i in doc.fields\r\n        if i.field_type==\'image_camera\'\r\n            img = i\r\n        break\r\n        end\r\n     end\r\n     \r\n     \r\n%>\r\n<div class=\"accordion-body collapse in\" id=\"collapse-1\">\r\n			<div class=\"accordion-inner\">\r\n				<ul class=\"nav nav-list\">\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\">\r\n					   <%=link_to \'Download Library\',\"/esm_image/\\#{doc.id}/download?record_id=\\#{record.id}&field_id=\\#{img.id}&p_id=\\#{p_id}\" ,:class=>\'k-button\',:target=>\'_blank\'%>\r\n					</li>\r\n				</ul>\r\n			</div>\r\n</div>\r\n<% end %>',NULL,NULL,NULL,'2015-04-22 17:35:38','2015-04-22 17:35:38','context_menu',''),(1447,'init',674,4,'<%\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  @next_id = nil\r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n  @next_id=@patient_module.ref_number \r\n  @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n  \r\n\r\n  #===========================================================================\r\n         def print_check_value document_tmp, record_tmp, conditions\r\n         tmp_doc = @document\r\n         tmp_rec = @record\r\n         @record = record_tmp\r\n         @document = document_tmp\r\n         \r\n         for j in conditions.keys\r\n         \r\n         \r\n         if @record[j]==\'true\'\r\n             for k in conditions[j]\r\n             if k.is_a? Hash\r\n                 v = @record[k.keys[0]]\r\n                 if v and v != \'\' and v!=0\r\n                    t = \"\"\r\n                    for a in k[k.keys[0]]\r\n                        if a == :value\r\n                        t+= \"<v>\\#{render_value k.keys[0].to_s}</v>\"\r\n                        else\r\n                        t+= \" \\#{a} \"\r\n                        end\r\n                    end\r\n                    k = t\r\n                 else\r\n                     k = \"\"\r\n                 end\r\n             elsif k.is_a? Symbol\r\n             k = \"<v>\\#{render_value k.to_s }</v>\" \r\n             end\r\n             \r\n       %> <%=k.html_safe%> <% end %>\r\n      <% end %>\r\n        \r\n      <% end %>\r\n      \r\n       <%\r\n         \r\n         @document = tmp_doc\r\n         @record = tmp_rec\r\n         end\r\n     \r\n     #===========================================================================\r\n         def print_scope models, r, table_name, conditions\r\n         tmp_doc = @document\r\n         tmp_rec = @record\r\n         @document = get_document table_name.to_s\r\n         list = models[table_name].find(r)\r\n         for i in list\r\n         @record = i\r\n        \r\n         print_check_value @document, @record, conditions\r\n         \r\n         %><br /><% end %>\r\n      <%\r\n        @document = tmp_doc\r\n        @record = tmp_rec\r\n      end\r\n\r\n      def print_multi_check_template document_tmp, record_tmp, list_field, labels, conditions\r\n#  conditions = {\'0\'=>[:biopsy_for_rapid],\r\n# \'2\'=>[:hemostatic_therapy,\'Concentration:\',:hemo_concentration,{:hemo_volume=>[\'Volume:\',:value,\'ml.\']}, {:hemoclip=>[\'Hemoclip\',:value]}],\r\n# \'6\'=>[:savarygillard_ditator,\'Size:\',:savarygillard_size,\'-\',:savarygillard_max_fr,\'Fr.\',:maloneyhurst_dilator,\'Size:\',:maloneyhurst_size,\'-\',:maloneyhurst_max_fr,\'Fr.\',:pneumatic_balloon_dilator,\'Pressure:\',:pneumatic_pressure,\'p.s.i.\',:pneumatic_max,\'min.\'],\r\n# \'7\'=>[:polypectomy_with],\r\n# \'8\'=>[:peg_brand,\'Size:\',:peg_size,\'Fr.\',\'Skin fixation at\',:peg_skin_fixation_at,\'cm.\'],\r\n# \'9\'=>[:peg_tube_brand,\'Size:\',:peg_tube_size,\'Fr.\',\'Skin fixation at\',:peg_tube_skin_fixation_at,\'cm.\']}\r\n\r\n        \r\n\r\n         tmp_doc = @document\r\n         tmp_rec = @record\r\n         @record = record_tmp\r\n         @document = document_tmp\r\n        \r\n         values = @record[list_field.to_sym].split(\"|\")\r\n         \r\n         for i in labels.keys.sort\r\n         \r\n         if values.index i\r\n         %><%= labels[i] %> : \r\n         <%\r\n           if conditions[i]\r\n           for k in conditions[i]\r\n             if k.is_a? Hash\r\n                 v = @record[k.keys[0]]\r\n                 if v and v != \'\' and v!=0 and v!=\"false\"\r\n                    t = \"\"\r\n                    for a in k[k.keys[0]]\r\n                        if a == :value\r\n                        t+= \"<v>\\#{render_value k.keys[0].to_s}</v>\"\r\n                        else\r\n                        t+= \" \\#{a} \"\r\n                        end\r\n                    end\r\n                    k = t\r\n                 else\r\n                     k = \"\"\r\n                 end\r\n             elsif k.is_a? Symbol\r\n             k = \"<v>\\#{render_value k.to_s }</v>\" \r\n             end\r\n             \r\n       %> <%=k.html_safe%> <% end %>\r\n            \r\n        <% end %>\r\n        <% end %>\r\n        <% end\r\n         \r\n         \r\n         \r\n         @document = tmp_doc\r\n         @record = tmp_rec\r\n\r\n\r\n      end\r\n%>\r\n\r\n',NULL,NULL,NULL,'2015-04-22 17:35:45','2015-04-22 17:35:45','init',''),(1448,'finding_ajax',674,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   \r\n   \r\n    reload = false\r\n    \r\n    tconfig = this.finding_template\r\n    xconfig = this.finding_config\r\n    \r\n    config = tconfig.dup\r\n    config[:name] = xconfig[:name]\r\n    config[:selectors] = xconfig[:selectors]\r\n    config[:view] = xconfig[:view]\r\n    config[:data] = xconfig[:data]\r\n    \r\n    config[:validate] = tconfig[:validate]\r\n    \r\n    \r\n    config[:validate] += xconfig[:validate] if xconfig[:validate]\r\n    \r\n    # view template\r\n    \r\n    map = {}\r\n    for i in tconfig[:view]\r\n        map[i[:value]] = i\r\n    end\r\n    for i in config[:view]\r\n        i.merge! map[i[:value]]  if map[i[:value]]\r\n    end\r\n    \r\n     # data template\r\n    \r\n    map = {}\r\n    for i in tconfig[:data]\r\n        map[i[:value]] = i\r\n    end\r\n    \r\n        if false    \r\n    %>\r\n<pre>\r\n<%= config[:data].to_yaml %>\r\n</pre>\r\n    <%\r\nend\r\n    \r\n    for i in config[:data]\r\n        i[:title] = i[:value].humanize unless  i[:title]\r\n        i[:relation] = \'many\' unless i[:relation] \r\n        # i[:values] = nil unless i[:values]\r\n        values = i[:values]\r\n        map[i[:value]] = {:value=>i[:value]} unless map[i[:value]]\r\n        if  map[i[:value]]\r\n            t = i.dup \r\n            i.merge! map[i[:value]] if map[i[:value]]\r\n            i.merge! t if t\r\n            i[:test]=true\r\n            i[:values] =  map[i[:value]][:values] if map[i[:value]][:values]  #map[i[:value]][:values]\r\n             i[:values] = {} unless i[:values]\r\n            # i[:values] =  map[i[:value]][:values] if  map[i[:value]][:values]\r\n            if values\r\n                values.each_pair do |k,v|\r\n                    i[k] = v \r\n                end\r\n            end\r\n            i[:values][:disease] = i[:value] if i[:values]\r\n        end\r\n    end   \r\n\r\n        if false    \r\n    %>\r\n<pre>\r\n<%= config.to_yaml %>\r\n</pre>\r\n    <%\r\nend\r\n\r\n\r\n    link_model = :finding\r\n    link_model = config[:model] if config[:model]\r\n\r\n   cmodels = {}\r\n   \r\n   models = get_model\r\n  \r\n   config[:models].each_pair do |k,v|\r\n\r\n   doc = @current_project.get_document v[0]\r\n   field = doc.find_by_column_name v[1]\r\n   fields = doc.fields.collect{|i| i unless Document.visual_types.index(i.field_type) }.compact\r\n   lov_map = {}\r\n%>\r\n   <%# doc.fields.collect{|i| i unless Document.visual_types.index(i.field_type) }.compact.inspect if k==:intervention  %>\r\n   <%\r\n   \r\n   labels = {}\r\n   \r\n   for f in fields\r\n    lmap = {}\r\n    label = f.label.gsub(\'@\',\'\').strip\r\n    label = f.column_name.humanize if label == \'\'\r\n    labels[f.column_name.to_sym] = label\r\n    \r\n    if f.lov_type\r\n	    if f.lov_type == \'plain\'\r\n	        f.lov.split(\"\\n\").collect{|i| i.strip}.compact.each do |x|\r\n	            lmap[x] = x     \r\n	        end\r\n        elsif f.lov_type == \'pair\'\r\n	        f.lov.split(\"\\n\").collect{|i| i.strip.split(\'|\') }.compact.each do |x|\r\n	            lmap[x[0]] = x[1]   \r\n	        end \r\n        end\r\n        lov_map[f.column_name.to_sym] = lmap if f.column_name\r\n    else\r\n        lov_map[f.column_name.to_sym] = {}  if f.column_name  \r\n    end\r\n    \r\n     \r\n   end\r\n\r\n\r\n   \r\n   cmodels[k] = {:name=>v[0], :field_name=>v[1], :m=>v[2],:labels=>labels, :doc=>doc,:model=>models[v[0]],:lov_map=> lov_map, :field=>field, :lov=>field.lov.split(\"\\n\").collect{|i| i.strip.split(\'|\')}}\r\n   if k==:intervention\r\n       \r\n      	root_data_node, root_fields_node, map, fmap = cmodels[k][:doc].get_root_format_node \r\n        \r\n         cmodels[k][:map] = map\r\n         cmodels[k][:fmap] = fmap\r\n  \r\n   end\r\n   \r\n  \r\n   end\r\n   \r\n    f = \'findings\'\r\n    records = []\r\n    if params[:values]\r\n    records = @models[:finding].find(params[:values].split(\"|\"))\r\n    end\r\n%>\r\n\r\n\r\n<% \r\n    \r\n  case params[:func]\r\n  \r\n  when \'create\'\r\n  \r\n    add_by = nil\r\n    add_by = params[:add_by] if params[:add_by]\r\n    add_value = nil\r\n    add_value = params[:add_value] if params[:add_value]\r\n  \r\n  when \'edit\'\r\n  \r\n  when \'delete\'\r\n  \r\n  %>\r\n  \r\n  <%\r\n  \r\n  else # get\r\n  \r\n  end\r\n\r\n\r\n\r\n  if request.post? \r\n# ======================================= SUBMIT POST\r\n\r\n  case params[:func]\r\n  \r\n  when \'create\'\r\n   # building form\r\n\r\n  when \'create_submit\'\r\n  # commit to database and generaet id\r\n  \r\n  \r\n  model = get_model(\'finding\')\r\n  record = model.new\r\n  doc = get_document \'finding\'\r\n  record = doc.record_create(model,params)\r\n  \r\n  values = eval(params[:values])+[record.id.to_s]\r\n  records = @models[:finding].find(values)\r\n  reload=true\r\n\r\n  \r\n  when \'edit\'\r\n  \r\n  \r\n  model = get_model(\'finding\')\r\n  record = model.find(params[:id])\r\n  doc = get_document \'finding\'\r\n  record = doc.record_update(model,params)\r\n  \r\n  values = eval(params[:values])+[record.id.to_s]\r\n  records = @models[:finding].find(values)\r\n\r\n  reload=true\r\n  \r\n  \r\n  when \'destroy\'\r\n  \r\n  else # get\r\n\r\n  end\r\n\r\n# =========================================================================================================\r\n# ================================================================   POST\r\n# =========================================================================================================\r\n\r\n%>\r\n<% case params[:func] %>\r\n<% when \'create_submit\' \r\nreload = true;\r\n%>\r\nCreated.. <%#%>\r\n<% when \'create\' %>\r\n<div class=\"alert alert-warnning\" style=\"width:680px;overflow:hidden\">\r\n  Form Create Item <%= params[:add_value] if add_by %>\r\n  \r\n  <%=form_for :record ,:url=>\'finding_ajax?func=create_submit\',:html=>{:id=>\'form-finding\'}, :remote=>true do |f| %>\r\n\r\n  <%\r\n       models = get_model\r\n       \r\n    \r\n       @record = models[link_model].new\r\n       \r\n       orders  = config[:order]\r\n       for o in orders\r\n         \r\n         fn = cmodels[o][:field_name]\r\n         tag = nil\r\n         obj = nil\r\n         \r\n        if params[:record][o]\r\n         \r\n         if cmodels[o][:m]==\'single\'\r\n            tag = params[:record][o]        \r\n         else\r\n            tag = params[:record][o].join(\"|\")\r\n         end\r\n  \r\n         obj = cmodels[o][:model].create fn.to_sym => tag\r\n        \r\n        else\r\n      \r\n      \r\n       if params[:record][:disease] and o == :intervention\r\n            map = {}\r\n            for i in config[:data]\r\n                map[i[:value]] = i\r\n            end \r\n            \r\n            intervention = nil\r\n            \r\n            intervention = \"*\"+config[:selectors][:intervention].join(\"|\") if config[:selectors][:intervention]\r\n            \r\n            i = map[params[:record][:disease]]\r\n            \r\n            i[:values][:intervention] << \'other\' if  i[:values][:intervention] and  i[:values][:intervention].size>0\r\n            \r\n            intervention = \"*\"+i[:values][:intervention].join(\"|\") if i[:values][:intervention]\r\n        \r\n            obj = cmodels[o][:model].create fn.to_sym => intervention\r\n        \r\n        else\r\n\r\n            obj = cmodels[o][:model].create \r\n       \r\n        end\r\n      \r\n        \r\n        end\r\n       \r\n        @record[o] = obj.id\r\n    \r\n       \r\n         \r\n         \r\n       end\r\n       \r\n       \r\n    #   location = models[:location].create :location_tag=>\'esophagus\'\r\n       \r\n    #   @record.location = [location.id]\r\n       \r\n       @document =  get_document link_model.to_s \r\n\r\n  %>\r\n  \r\n  <%= render :partial=>\'/esm_documents/show_layout.html\',:locals=>{:selector_key_options=>{\'intervention\'=>intervention}}  %>\r\n  <%= hidden_field_tag \"values\",\"\", :id=>\"tmp-values\" %>\r\n  <%\r\n  \r\n#   finding-location-55aa1514790f9b48de000008-esophagus_distance\r\n    lview = nil\r\n    dview = nil\r\n    for i in config[:view]\r\n        if i[:value]==params[:record][:location]\r\n           lview = i\r\n           break \r\n        end\r\n    end\r\n    for i in config[:data]\r\n        if i[:value]==params[:record][:disease]\r\n           dview = i\r\n           break \r\n        end\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n  \r\n  %>\r\n  \r\n  <script>\r\n  \r\n  $(function(){ \r\n      setTimeout(function(){\r\n     \r\n<%\r\n\r\n    if lview[:filter_dependencies] and lview[:filter_dependencies][:disease] and lview[:filter_dependencies][:disease][params[:record][:disease]]\r\n     \r\n       for i in  lview[:filter_dependencies][:disease][params[:record][:disease]]\r\n        %>\r\n            \r\n            obj = $(\"#finding-location-<%=\"\\\\#{@record.location}-\\\\#{i}\"%>\")\r\n            obj.hide()\r\n            \r\n        <%\r\n       end\r\n    end\r\n%>\r\n\r\n      \r\n<%\r\n\r\n    if dview[:filter_dependencies] and dview[:filter_dependencies][:location] and dview[:filter_dependencies][:location][params[:record][:location]]\r\n       for i in  dview[:filter_dependencies][:location][params[:record][:location]]\r\n        %>\r\n        \r\n            obj = $(\"#finding-disease-<%=\"\\\\#{@record.disease}-\\\\#{i}\"%>\")\r\n            obj.hide()\r\n            \r\n        <%\r\n       end\r\n    end\r\n%>\r\n      \r\n  },10); \r\n  });\r\n  \r\n  \r\n  </script>\r\n  \r\n  <%= f.submit \'Create.\',:id=>\'form-submit\' ,:class=>\"btn btn-success\" ,:data=>{:disable_with=>\'Loading..\'} %> | \r\n    <%= link_to \'Cancel\', \"javascript:cancelFinding()\" ,:class=>\'\' %>\r\n\r\n \r\n  <% end %>\r\n\r\n  <script>\r\n  \r\n  $(\'#form-submit\').click(function(){\r\n      $(this).attr(\"value\",\"loading...\");\r\n      $(this).attr(\'disabled\',\'disabled\');\r\n  })\r\n \r\n  $(function(){\r\n      \r\n        $(\'#tmp-values\').val($(\'#data-findings\').val());\r\n      $(\'#form-submit\').click(function(){\r\n    \r\n         var _data= $(\'#form-finding\').serialize();\r\n         $.ajax({\r\n            type: \'POST\',\r\n            url: \"finding_ajax?func=create_submit\",\r\n            data:_data,\r\n            success: function(html){\r\n               $(\'#findings\').html(html);    \r\n            }\r\n         });\r\n         return false;\r\n      });\r\n      javascript:$(\"html, body\").animate({ scrollTop: 500 }, \"slow\");\r\n  });\r\n  </script>\r\n\r\n\r\n</div>\r\n<% when \'edit\' %>\r\n<!--Edit MSG-->\r\n<% else %>\r\n<% end %>\r\n\r\n<% else \r\n# =========================================================================================================\r\n# ================================================================   GET\r\n# =========================================================================================================\r\n  case params[:func]\r\n%>\r\n<%\r\n  when \'create\'         # =========================================  GET CREATE\r\n%>\r\n\r\n  \r\n  <%=form_for :record ,:url=>\'finding_ajax?func=create\',:html=>{:id=>\'form-finding\'}, :remote=>true do |f| %>\r\n  \r\n <div class=\"alert alert-warnning\" >\r\n \r\n<h4>  Create finding <%= \'for \'+params[:add_value] if add_by %></h4><br/>\r\n  <%\r\n \r\n \r\n    orders  = config[:order]\r\n    selectors = config[:selectors]\r\n    \r\n  for o in orders\r\n  %>\r\n <b><%= o.to_s.humanize%></b>\r\n <ul>\r\n <% \r\n \r\n    filter_list =  cmodels[o][:lov]\r\n    \r\n\r\n \r\n    l = []\r\n\r\n \r\n  \r\n    data_organized_by = config[:data_organized_by]\r\n    if o == data_organized_by\r\n    for i in config[:data]\r\n        l << i[:values][data_organized_by]\r\n    end\r\n    \r\n    \r\n     filter_list  = filter_list.collect{|j| j if l.index j[0].to_s }.compact\r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    count = 0 \r\n    \r\nfilter_list.each_with_index do |i,index|\r\n \r\n \r\n \r\n  if selectors[o]==nil or selectors[o].index(i[0]) \r\n auto = false\r\n auto =  add_by && add_by==o.to_s && add_value==i[0]\r\n       \r\n\r\n\r\n    \r\n    if cmodels[o][:m]==\'single\'\r\n %>\r\n<span style=\"padding-right:0px;width:220px;border:0px solid\">\r\n<%= f.radio_button o, i[0],:checked=> auto,:onchange=>\"selectTag(\'\\\\#{o}:\\\\#{i[0]}\')\" %> \r\n<%= f.label o, i[1], :value => i[1],:style=>\'width:150px;display:inline-block\' %>\r\n</span>\r\n<% else %>\r\n<span style=\"padding-right:0px;width:220px;border:0px solid\">\r\n<%= check_box_tag \'finding_record[\'+o.to_s+\'][]\', i[0], auto,:id=>\"finding_record_\\\\#{o}_\\\\#{i[0]}\" %>\r\n<%= label_tag \'finding_record[\'+o.to_s+\'][\'+i[0]+\']\', i[1], :value => i[1],:style=>\'display:inline-block;width:150px\' %> \r\n</span>\r\n<% end %>\r\n<%#count%>\r\n<% if count%3==2 and count!=0  %>\r\n<div class=\"clear\"></div>\r\n<% end \r\ncount+=1\r\n\r\n%> \r\n\r\n\r\n\r\n<% end %> \r\n<% end %> \r\n </ul>\r\n <% end %>\r\n  \r\n  <%= f.submit \'Select\',:id=>\'form-submit\',:class=>\'btn btn-info\' %> | \r\n  \r\n  <%= link_to \'Cancel\', \"javascript:cancelFinding()\" ,:class=>\'\' %>\r\n\r\n\r\n  <% end %>\r\n</div>\r\n\r\n  <script>\r\n  $(function(){\r\n      $(\'#form-submit\').click(function(){\r\n         var _data= $(\'#form-finding\').serialize();\r\n         $.ajax({\r\n            type: \'POST\',\r\n            url: \"finding_ajax?func=create\",\r\n            data:_data,\r\n            success: function(html){\r\n               $(\'#finding-status\').html(html);    \r\n            }\r\n         });\r\n         return false;\r\n      });\r\n  });\r\n  </script>\r\n  \r\n  \r\n  \r\n<%\r\n  when \'edit\'        # =========================================  GET EDIT\r\n    \r\n    models = get_model\r\n       \r\n    @record = models[:finding].find(params[:id])\r\n    @document =  get_document \'finding\' \r\n    \r\n    map = {}\r\n    for i in config[:data]\r\n        map[i[:value]] = i\r\n    end \r\n    \r\n    \r\n    intervention = nil\r\n            \r\n    intervention = \"*\"+config[:selectors][:intervention].join(\"|\") if config[:selectors][:intervention]\r\n            \r\n            \r\n    mdisease = models[:disease]\r\n    disease = mdisease.find(@record.disease)\r\n    \r\n    if disease \r\n        i = map[disease[:disease_tag]]\r\n         i[:values][:intervention] << \'other\' if  i[:values][:intervention]\r\n        intervention = \"*\"+i[:values][:intervention].join(\"|\")  if i[:values][:intervention]\r\n    end\r\n    # intervention = \"*sampling|clipping\"\r\n    \r\n    \r\n  %>\r\n  <%# map.inspect %>\r\n  <div class=\"alert alert-warnning\">\r\n  Edit Item\r\n\r\n  <%=form_for :record ,:url=>\'finding_ajax?func=update\',:html=>{:id=>\'form-finding\'}, :remote=>true do |f| %>\r\n  <%= render :partial=>\'/esm_documents/show_layout.html\',:locals=>{:selector_key_options=>{\'intervention\'=>intervention}} %>\r\n  <%= hidden_field_tag \"values\",\"\", :id=>\"tmp-values\" %>\r\n  <%= hidden_field_tag \"id\",@record.id, :id=>\"\" %>\r\n\r\n\r\n  <%= f.submit \'Update\',:id=>\'form-submit\',:class=>\"btn btn-success\" %>\r\n  |\r\n  <%= link_to \'Delete\', \"javascript:deleteFinding(\'\\\\#{@record.id}\')\" ,:date=>{:remote=>true,:confirm=>\'Are you sure?\'},:class=>\'btn  btn-danger\' %>\r\n  | <%= link_to \'Cancel\', \"javascript:cancelFinding()\" ,:class=>\'\' %>\r\n  \r\n\r\n  <% end %>\r\n\r\n </div>\r\n  <script>\r\n  $(function(){\r\n      $(\'#tmp-values\').val($(\'#data-findings\').val());\r\n      $(\'#form-submit\').click(function(){\r\n         var _data= $(\'#form-finding\').serialize();\r\n         $.ajax({\r\n            type: \'POST\',\r\n            url: \"finding_ajax?func=edit\",\r\n            data:_data,\r\n            success: function(html){\r\n               $(\'#findings\').html(html);    \r\n            }\r\n         });\r\n         return false;\r\n      });\r\n      javascript:$(\"html, body\").animate({ scrollTop: 500 }, \"slow\");\r\n  });\r\n  </script>\r\n<%\r\n  else  # show            # =========================================  GET SHOW\r\n  reload = true\r\n%>\r\n<%\r\n end\r\n%>\r\n\r\n<% end %>\r\n\r\n<% if reload  %>\r\n\r\n <%\r\n    view_organized_by = config[:view_organized_by]\r\n    \r\n    data_organized_by = config[:data_organized_by]\r\n    \r\n    intervention_by = config[:intervention_by]\r\n    \r\n    data_map = {}\r\n    view_map = {}\r\n    intv_map = {}\r\n    \r\n    # template preparation  \r\n    \r\n    def process_template template\r\n        \r\n         finding_text = template\r\n            \r\n            tmp = finding_text.split()\r\n            val = []\r\n            template = []\r\n            l = []\r\n            for j in tmp\r\n                if j[0]==\':\'\r\n                    if l.size>0\r\n                    template << l.join(\" \")\r\n                    l=[]\r\n                    end\r\n                    \r\n                    var = j.strip.gsub(\'.\',\'\')\r\n                    val << var[1..-1]\r\n                    template << \"\\\\#{var}\"\r\n                    if j.index(\'.\')\r\n                       template << \'.\' \r\n                    end\r\n                else\r\n                    l << j\r\n                end\r\n            end\r\n            if l.size>0\r\n                template << l.join(\" \")\r\n            end\r\n            return [template,val]\r\n    end\r\n    \r\n       def eval_template obj, template, master={}, value_text={}, labels={}\r\n        temp = template[0]\r\n        val = template[1]\r\n      \r\n        text=\'\'#+template.inspect\r\n                just_var = false\r\n                for t in temp\r\n                sub_template = false\r\n                lookup = nil\r\n                \r\n                subfix = \' \'\r\n                  \r\n                  \r\n                if t[0]!=\':\'\r\n                    text += \' \' if just_var and t!=\'.\'\r\n                    text += t\r\n                    text += \' \' if text!=\'.\' \r\n                    just_var = false\r\n                else\r\n                    \r\n                    if t[-1]==\',\' or t[-1]==\'.\'\r\n                       subfix = t[-1]\r\n                       t = t[0..-2] \r\n                    end\r\n                    \r\n                    \r\n                    \r\n                    var = t[1..-1]\r\n                    \r\n                    if var.index(\"|\")\r\n                       x = var.split(\"|\")\r\n                       \r\n                       if x.size==3\r\n                          \r\n                          lookup = {}\r\n                          \r\n                          lxi = x[2].split(\",\")\r\n                          \r\n                          for xi in lxi\r\n                            xk,xv = xi.split(\":\")\r\n                            lookup[xk] = xv\r\n                          end\r\n                           \r\n                       end\r\n                       \r\n                       \r\n                       var = x[0]\r\n                       tvar = x[1].split(\"-\")\r\n                       is_prefix = true\r\n                       xprefix = []\r\n                       xsubfix = []\r\n                       for tx in tvar\r\n                        if tx.index \':\'\r\n                           \r\n                            is_prefix = false\r\n                                \r\n                        else\r\n                            \r\n                            if is_prefix \r\n                               xprefix << tx \r\n                            else\r\n                                xsubfix << tx\r\n                            end\r\n                            \r\n                        end\r\n                         \r\n                       end\r\n                       sub_template = true\r\n                       \r\n                       xprefix = xprefix.join(\" \")\r\n                       xsubfix = xsubfix.join(\" \")\r\n                       \r\n                       \r\n                       \r\n                    #   tvar = x[1].gsub(/[-]/, \' \')  \r\n                       \r\n                        \r\n                    end\r\n                    \r\n                    \r\n                    \r\n                 \r\n                    \r\n                    \r\n                    if var[-1]==\'!\'\r\n                        \r\n                        var = var[0..-2]\r\n                        v = \'\'\r\n                    \r\n                        if obj.respond_to?(var) and obj.send(var)\r\n                     \r\n                            v = obj.send(var)\r\n                            v = \"<v>\\\\#{v}</v> \"\r\n                    \r\n                        end\r\n                \r\n                    elsif obj.respond_to?(var) and obj.send(var)\r\n                   \r\n                        v = obj.send(var)\r\n                    \r\n                        if v and value_text and  value_text[var.to_sym]       \r\n                            if v.index(\'|\')\r\n                                tv = v.split(\'|\')\r\n                                l = []\r\n                                for i in tv\r\n                                    # l << i\r\n                                    xi = value_text[var.to_sym][i] if value_text[var.to_sym][i]\r\n                                    xi = lookup[xi.strip] if lookup and lookup[xi.strip] \r\n                                    l << xi\r\n                                end\r\n                                v = l.join(\", \")\r\n                            else\r\n                                xi = value_text[var.to_sym][v.to_s]  if value_text[var.to_sym][v] \r\n                                xi = lookup[xi.strip] if lookup and lookup[xi.strip] \r\n                                \r\n                                v = xi if value_text[var.to_sym][v] \r\n                            \r\n                            end\r\n                        \r\n                            v = \"<v>\\\\#{v}</v>\"\r\n                        \r\n                        elsif var==\'inspect\'\r\n                       \r\n                            t = []\r\n                        \r\n                            for i in value_text.keys\r\n                        \r\n                                if i != :disease_tag and i!= :intervention_tag\r\n                                    x = obj.send(i)\r\n                          \r\n                                    if x and x != \'\'\r\n                                    \r\n                                        if value_text[i] \r\n                                            l = []\r\n                                            for j in x.split(\'|\')\r\n                                                l << value_text[i][j] if value_text[i][j]\r\n                                            end\r\n                                        \r\n                                        \r\n                                            x = l.join(\", \") if l.size>0\r\n                                        \r\n                                        end\r\n                                    \r\n                                        name = i.to_s.humanize\r\n                                        name = labels[i] if labels[i]\r\n                                    \r\n                                        t << \"\\\\#{name} :  <v>\\\\#{x}</v>\"\r\n                                    end\r\n                                end\r\n                            \r\n                            end\r\n                       \r\n                            v = \"\\\\#{t.join(\" \")}\"\r\n                       \r\n                        else\r\n                            v = \"<v>\\\\#{v}</v>\"\r\n                        end\r\n                \r\n                    elsif master[var]\r\n                    \r\n                        v = \"<v>\\\\#{master[var]}</v>\"\r\n                    \r\n                    else   \r\n                        v = \"<v>[Undefined \\\\#{var}]</v>\"\r\n                    end\r\n                \r\n                    \r\n                \r\n                    if sub_template\r\n                        text+=\"\\\\#{xprefix} \\\\#{v} \\\\#{xsubfix}\\\\#{subfix}\" if v.strip !=\'<v></v>\'\r\n                    else\r\n                        text+=v+\"\\\\#{subfix}\"\r\n                    end\r\n                    \r\n                    \r\n                    just_var = true\r\n                    \r\n                end\r\n                end\r\n                \r\n                t = text \r\n                \r\n                begin\r\n                \r\n                text = (text.split(\' \').collect{|i| i = i if i.upcase!=i; i if i!=\'.\' }.compact.join(\" \"))\r\n                text = text[0].upcase + text[1..-1]\r\n                rescue Exception=>e\r\n                \r\n                end\r\n                \r\n        return text         \r\n    end\r\n    \r\n    \r\n    # data processing\r\n    \r\n    if data_organized_by\r\n        for i in config[:data]\r\n            key = i[:values][data_organized_by]\r\n            data_map[key] = i\r\n            \r\n           \r\n            i[:finding_text] = \"\\\\#{i[:value].humanize} :inspect \" unless i[:finding_text]\r\n            \r\n            i[:finding_template] = process_template i[:finding_text]\r\n            \r\n            \r\n            \r\n            if i[:multiple_finding_text]\r\n                i[:multiple_finding_template] = [process_template(i[:multiple_finding_text][0]),process_template(i[:multiple_finding_text][1])]\r\n            end\r\n            if i[:final_text]\r\n                i[:final_template] = [process_template(i[:final_text][0]),process_template(i[:final_text][1])]\r\n            end\r\n            \r\n            \r\n        end\r\n    end\r\n    \r\n    # view processing\r\n    \r\n    if view_organized_by\r\n            \r\n            for i in config[:view]\r\n\r\n                key = i[:value]\r\n                view_map[key] = i\r\n                \r\n                i[:view_text] =  \"\\\\#{key.humanize}\" unless i[:view_text]\r\n                \r\n                i[:view_template] = process_template i[:view_text]\r\n\r\n            end\r\n    end\r\n    \r\n    \r\n    lov_map = cmodels[:intervention][:lov_map][:intervention_tag] \r\n    \r\n    if intervention_by\r\n            for i in config[:intervention]\r\n            \r\n            key = i[:value]\r\n            intv_map[key] = i\r\n            title = lov_map[key]\r\n            title = i[:title] if i[:title]\r\n            i[:intv_text] = \"\\\\#{title} :inspect \" unless i[:intv_text]\r\n            i[:intv_template] = process_template i[:intv_text]\r\n                \r\n            end\r\n    end\r\n\r\n    # reset normal vlaue    \r\n    \r\n    unless params[:init]\r\n    %>\r\n    <script>\r\n    <%\r\n    for  i in view_map.values\r\n    %>\r\n       var editor = $(\"#data-<%=i[:editor_id]%>\").data(\"kendoEditor\");    \r\n       if(typeof(editor))\r\n       editor.value(\'Normal\');   \r\n    <% end %>\r\n    </script>\r\n    <%\r\n    end\r\n    \r\n    \r\n    \r\n    cm = cmodels[view_organized_by]\r\n    \r\n    \r\n    field_name = cm[:field_name]\r\n    frecords = {}\r\n    orders = config[:order]\r\n    \r\n    mmaps = {}\r\n    \r\n    # location disease intervention\r\n    for i in records\r\n    \r\n        for o in orders\r\n            mmaps[o] = [] unless mmaps[o]\r\n            mmaps[o] << i.send(o)\r\n        end\r\n        \r\n    end\r\n     \r\n    # mmaps[module][record id]\r\n     \r\n    # build sub relation   \r\n    mmaps.each_pair do |k,v|\r\n        m = cmodels[k][:model]\r\n        map = {}\r\n        \r\n        for i in m.find(v)\r\n            map[i.id] = i\r\n        end\r\n        mmaps[k] = map\r\n       \r\n    end\r\n    \r\n    # build disease map\r\n    \r\n    intv_text = []\r\n     \r\n     \r\n    for i in records \r\n    \r\n    c = mmaps[view_organized_by][i[view_organized_by]]\r\n    d = mmaps[data_organized_by][i[data_organized_by]]\r\n    int = mmaps[intervention_by][i[intervention_by]]\r\n    # if int\r\n    # int_text += int.send(\'intervention_tag\').split(\'|\') if int\r\n   \r\n    if c\r\n        loc = c.send field_name\r\n        dis = d.send(cmodels[data_organized_by][:field_name])\r\n        frecords[dis] = {} unless frecords[dis]\r\n        frecords[dis][loc] = [] unless frecords[dis][loc]\r\n        frecords[dis][loc] << i\r\n    end\r\n    \r\n    end\r\n    \r\n    %>\r\n    <%# frecords.inspect %>\r\n    <%\r\n\r\n    # view layout\r\n    \r\n    view_list = cm[:lov]\r\n    \r\n    if config[:selectors][view_organized_by]\r\n        map = {}\r\n        for i in view_list\r\n            map[i[0]]=i\r\n        end\r\n        list = []\r\n        for i in config[:selectors][view_organized_by]\r\n            list << map[i] if map[i]\r\n        end\r\n    end\r\n    \r\n    \r\n    view_list = list\r\n    \r\n    \r\n    cm = cmodels[data_organized_by]\r\n\r\n    data_list = []\r\n    \r\n    map = {}\r\n    \r\n    \r\n    for i in config[:data]\r\n        data_list << [i[:values][data_organized_by], i[:title]] \r\n    end\r\n    \r\n    %>\r\n    <%# data_list.inspect %>\r\n    <%\r\n    \r\n     master = {}\r\n     dx = [\'0\']\r\n     dx_text = []\r\n\r\n    %>\r\n     \r\n     \r\n    <div id=\"finding-id\" style=\"border:0px solid\">\r\n    <label style=\"border-bottom:1px solid #ccc\"><strong>Findings</strong>&nbsp;<span id=\"finding-msg\"></span> </label> \r\n\r\n<%# link_to \'Add Finding\', \"finding_ajax?func=create&update=finding-status\",:class=>\'btn\' ,:remote=>true %><br/><br/>\r\n\r\n<div id=\"finding-status\">\r\n\r\n</div>\r\n\r\n\r\n  <%\r\n  \r\n    location_content = {}\r\n    \r\n    for i in view_list\r\n        location_content[i[0]] = [] unless location_content[i[0]]\r\n    end\r\n  \r\n  \r\n    intv_index = 0\r\n  \r\n  \r\n  \r\n    structure = config[:structure]\r\n    \r\n    unless structure\r\n    \r\n        structure = []\r\n        groups = {}\r\n        \r\n        for i in config[:data]\r\n        \r\n            d = [i[:values][data_organized_by], i[:title]] \r\n            \r\n            unless i[:group]\r\n            \r\n                structure << {:items=>[d]}\r\n            \r\n            else\r\n                \r\n                g = i[:group]\r\n                \r\n                unless groups[g]\r\n                \r\n                    groups[g] = [d] \r\n                    structure << {:items=>groups[g],:group_id=>g}\r\n                \r\n                else\r\n                    glist = groups[g]\r\n                    glist << d\r\n                end\r\n            \r\n            end\r\n        \r\n        end\r\n        \r\n\r\n    end\r\n    \r\n  \r\n    intervention_list = {}\r\n        \r\n        \r\n    for str in structure\r\n  \r\n    data_list = str[:items]\r\n    \r\n    if str[:group_id] == 0 \r\n    %>\r\n    <h3>Other</h3>\r\n    <%\r\n    end\r\n  # list is disease\r\n  \r\n  \r\n\r\n   \r\n    for i in data_list\r\n   %>\r\n    <span style=\"\">\r\n    <%\r\n        disease = data_map[i[0]]\r\n        choises = disease[:values][view_organized_by] \r\n        choises = config[:selectors][view_organized_by] unless choises\r\n        \r\n        if choises\r\n            if choises.size==1\r\n    %>\r\n    <strong><%= i[1] %></strong>\r\n    <%= link_to \"+\", \"finding_ajax?func=create&update=finding-status&record[disease]=\\\\#{i[0]}&record[location]=\\\\#{choises[0]}\",:class=>\'btn btn-mini  \',:data=>{:disable_with=>\'Loading..\'} ,:remote=>true,:method=> :post %>\r\n    \r\n    <% else\r\n          \r\n    %>\r\n    \r\n            \r\n<strong style=\"float:left\"><%= i[1] %>&nbsp;</strong>         \r\n&nbsp;<div class=\"btn-group\" style=\"float:left\">\r\n&nbsp;<button data-toggle=\"dropdown\" class=\"btn dropdown-toggle btn-mini\"> <span class=\"caret\"></span></button>\r\n	<ul class=\"dropdown-menu\">\r\n		<%\r\n		\r\n		  for c in choises\r\n            vw = view_map[c]\r\n            view_text = c.humanize\r\n            view_text = vw[:title] if vw and vw[:title]\r\n        %>\r\n		\r\n		<li>\r\n		 <%= link_to \"\\\\#{view_text}\", \"finding_ajax?func=create&update=finding-status&record[disease]=\\\\#{i[0]}&record[location]=\\\\#{c}\",:data=>{:disable_with=>\'Loading..\'} ,:remote=>true, :method=> :post %>\r\n        </li>\r\n		\r\n         <% end %>\r\n		\r\n	</ul>\r\n</div>\r\n         \r\n         \r\n         <% end %>\r\n         \r\n        <% end %>\r\n        \r\n    </span>\r\n        <% end %>\r\n    \r\n    <br/>  <br/>\r\n    \r\n    \r\n     <%\r\n       \r\n     \r\n       \r\n      for i in data_list   \r\n \r\n       \r\n    if frecords[i[0]]\r\n    \r\n    # each disease \r\n    frecords[i[0]].each_pair do |k,drecords|\r\n       \r\n        disease = data_map[k.to_s]\r\n        if disease \r\n            dx = [] if dx[0]==\'0\' \r\n            dx << disease[:dx_id]\r\n        end\r\n    \r\n        pattern =nil \r\n\r\n       \r\n        \r\n  \r\n        \r\n        if drecords.size>1\r\n            \r\n            # many finding in a disease\r\n            \r\n            text = \'\'\r\n            values = []\r\n            tvalues = []\r\n            tfvalues = []\r\n                \r\n            partial_text = \'\'\r\n            \r\n            \r\n            \r\n    \r\n    \r\n            # compute each record for a location disease\r\n            \r\n            for r in drecords\r\n\r\n                location_text = \"\"\r\n                location_adj = \"\"\r\n                \r\n                # get disease pattern\r\n                if data_organized_by\r\n                    field_name = cmodels[data_organized_by][:field_name]\r\n                    obj = mmaps[data_organized_by][r.send(data_organized_by)]\r\n                    pattern = data_map[obj.send(field_name)]\r\n                    dx << pattern[:dx_id]\r\n                end\r\n                \r\n                # get location pattern\r\n                if  view_map[k]\r\n                        lobj = mmaps[view_organized_by][r.send(view_organized_by)]\r\n                        location_text = eval_template lobj, view_map[k][:view_template],{}, cmodels[view_organized_by][:lov_map]\r\n                        \r\n                        location_adj = location_text \r\n                        location_adj = view_map[k][:adj] if view_map[k][:adj]\r\n                        \r\n                end \r\n                \r\n                obj = mmaps[data_organized_by][r.send(data_organized_by)]\r\n                value_map = cmodels[data_organized_by][:lov_map]\r\n                value_map.merge!(pattern[:value_text]) if pattern[:value_text]\r\n                text = eval_template obj, pattern[:multiple_finding_template][0], {\'location\'=>location_text,\'location_adj\'=>location_adj},  value_map\r\n             \r\n             \r\n                intv = mmaps[intervention_by][ r.send(intervention_by)]\r\n                \r\n                if intv.intervention_tag !=\'\'\r\n                    intv_list = []\r\n                    # value_map = cmodels[intervention_by][:lov_map]\r\n\r\n                        value_map = cmodels[intervention_by][:lov_map]\r\n                        \r\n                        labels = cmodels[intervention_by][:labels]\r\n                        \r\n                        map = cmodels[:intervention][:map]\r\n                        fmap = cmodels[:intervention][:fmap]\r\n                    \r\n                        for i in intv.intervention_tag.split(\"|\")\r\n                        \r\n                            fid = \"\\\\#{cmodels[:intervention][:field][:id]}|\\\\#{i}\"\r\n                            tag = map[fid]\r\n                            fids = tag[:items].collect{|j|t = fmap[j[:id]] ; t.to_sym  if t.split(\'-\').size==1  }.compact\r\n                            vmap = value_map.slice(*fids)\r\n                        \r\n                            if intv_map[i] and  intv_map[i][:intv_template]\r\n                                intv_x = eval_template intv, intv_map[i][:intv_template], vmap if intv_map[i] and  intv_map[i][:intv_template]\r\n                            else\r\n                                template = \"\\\\#{value_map[:intervention_tag][i]} :inspect \"\r\n                                template = process_template template\r\n                                intv_x = eval_template intv, template, {}, vmap, labels\r\n                            end\r\n                        \r\n                            intervention_list[i] = true\r\n                            intv_list << intv_x #+\"\\\\#{i}\"\r\n                        end\r\n                        \r\n                        intv_text << \"(\\\\#{intv_index+1}) \\\\#{intv_list.join(\', \')} \"\r\n                        text+= \"(\\\\#{intv_index+1}) \"\r\n                        intv_index += 1\r\n                        \r\n\r\n                end \r\n             \r\n                tvalues << text\r\n                values << link_to(text.html_safe, \"finding_ajax?func=edit&id=\\\\#{r.id}&update=finding-status\" ,:remote=>true,:class=>\'btn\' )\r\n                \r\n                if pattern[:final_template]  \r\n                    value_map = cmodels[data_organized_by][:lov_map]\r\n                    value_map.merge!(pattern[:value_text]) if pattern[:value_text]\r\n               \r\n                    tf=eval_template obj, pattern[:final_template][0], {\'location\'=>location_text},  value_map \r\n                    tfvalues << tf\r\n                else\r\n                    tfvalues << \'not found pattern\'\r\n                end\r\n\r\n            end\r\n    \r\n            text=eval_template nil, pattern[:multiple_finding_template][1], {\'location\'=>location_text,\'values\'=>values.join(\", \")}\r\n            op_text=eval_template nil, pattern[:multiple_finding_template][1], {\'location\'=>location_text,\'values\'=>tvalues.join(\", \")}\r\n    \r\n            if pattern[:final_template]  \r\n                final_text = eval_template nil, pattern[:final_template][1], {\'location\'=>location_text,\'values\'=>tfvalues.join(\", \")}\r\n                dx_text << final_text\r\n            end\r\n     \r\n            location_content[k] << op_text\r\n            \r\n            # output link text\r\n            %>\r\n            <%= text.html_safe %>\r\n            <%\r\n\r\n        else\r\n\r\n        # single finding in a disease\r\n        \r\n    \r\n            for r in drecords\r\n                \r\n                location_text = \"\"\r\n                location_adj = \"\"\r\n                pattern = nil\r\n                if data_organized_by\r\n                    field_name = cmodels[data_organized_by][:field_name]\r\n                    obj = mmaps[data_organized_by][r.send(data_organized_by)]\r\n                    pattern = data_map[obj.send(field_name)]\r\n                    dx << pattern[:dx_id]\r\n                end\r\n                \r\n                if  view_map[k]\r\n                    lobj = mmaps[view_organized_by][r.send(view_organized_by)]\r\n                    location_text = eval_template lobj, view_map[k][:view_template], {} , cmodels[view_organized_by][:lov_map]\r\n                    location_adj = location_text \r\n                    location_adj = view_map[k][:adj] if view_map[k][:adj]\r\n                end\r\n              \r\n              \r\n           \r\n              \r\n                \r\n                if pattern\r\n                   \r\n                    text = \'\'\r\n                \r\n                    if pattern[:finding_template] \r\n                        value_map = cmodels[data_organized_by][:lov_map]\r\n                        value_map.merge!(pattern[:value_text]) if pattern[:value_text]\r\n                        text = eval_template obj, pattern[:finding_template], {\'location\'=>location_text,\'location_adj\'=>location_adj}, value_map, {:com_fill_con=>\'Content\'}\r\n                    end\r\n                    \r\n                    intv = mmaps[intervention_by][ r.send(intervention_by)]\r\n                    if intv.intervention_tag !=\'\'\r\n                        intv_list = []\r\n                    \r\n                        value_map = cmodels[intervention_by][:lov_map]\r\n                        \r\n                        labels = cmodels[intervention_by][:labels]\r\n                        \r\n                        map = cmodels[:intervention][:map]\r\n                        fmap = cmodels[:intervention][:fmap]\r\n                    \r\n                        for i in intv.intervention_tag.split(\"|\")\r\n                        \r\n                            fid = \"\\\\#{cmodels[:intervention][:field][:id]}|\\\\#{i}\"\r\n                            tag = map[fid]\r\n                            fids = tag[:items].collect{|j|t = fmap[j[:id]] ; t.to_sym  if t.split(\'-\').size==1  }.compact\r\n                            vmap = value_map.slice(*fids)\r\n                        \r\n                            if intv_map[i] and  intv_map[i][:intv_template]\r\n                                intv_x = eval_template intv, intv_map[i][:intv_template], vmap if intv_map[i] and  intv_map[i][:intv_template]\r\n                            else\r\n                                template = \"\\\\#{value_map[:intervention_tag][i]} :inspect \"\r\n                                template = process_template template\r\n                                intv_x = eval_template intv, template, {}, vmap, labels\r\n                            end\r\n                        \r\n                            intervention_list[i] = true\r\n                            intv_list << intv_x #+\"\\\\#{i}\"\r\n                        end\r\n                        \r\n                        intv_text << \"(\\\\#{intv_index+1}) \\\\#{intv_list.join(\', \')} \"\r\n                        text+= \"(\\\\#{intv_index+1}) \"\r\n                        intv_index += 1\r\n                        \r\n                    \r\n                    end \r\n           \r\n                    if pattern[:final_template]  \r\n                        value_map = cmodels[data_organized_by][:lov_map]\r\n                        value_map.merge!(pattern[:value_text]) if pattern[:value_text]\r\n                        final_text = eval_template obj, pattern[:final_template][0], {\'location\'=>location_text}, value_map\r\n                        dx_text << final_text\r\n                    else\r\n                        dx_text << text\r\n                  end\r\n           \r\n                else\r\n                    \r\n                for o in orders\r\n                    field_name = cmodels[o][:field_name]\r\n                    obj = mmaps[o][r.send(o)]\r\n                    if obj\r\n                        tmp = obj.send(field_name)\r\n                        text+=\"\\\\#{tmp.humanize} \" if tmp\r\n                    end\r\n                end\r\n                \r\n                end\r\n                \r\n                \r\n                op_text = text\r\n                text = link_to(text.html_safe, \"finding_ajax?func=edit&id=\\\\#{r.id}&update=finding-status\" ,:data=>{:remote=>true,:disable_with=>\'Loading..\'},:class=>\'btn\')\r\n                location_content[k] << op_text\r\n            end\r\n         %>\r\n         <%=text.html_safe %>\r\n     <% end %>\r\n    \r\n  \r\n     \r\n    <% end %>\r\n    \r\n    \r\n<% end %>\r\n\r\n<% end %> \r\n\r\n\r\n<hr/>\r\n\r\n<% end %>\r\n \r\n<%# dx.inspect %>\r\n\r\n\r\n<% unless params[:init] %>\r\n    <script>\r\n    <%\r\n      \r\n    for i in view_list\r\n      \r\n      v = view_map[i[0]]\r\n      \r\n    #   location_text = \'Normal\'\r\n      if location_content[i[0]].size>0\r\n    %>\r\n     var editor = $(\"#data-<%=v[:editor_id]%>\").data(\"kendoEditor\");    \r\n     if(editor){\r\n        editor.value(<%=location_content[i[0]].join(\", \").to_json.html_safe%>);   \r\n     }\r\n    <% end %>\r\n    <% end %>\r\n    </script>\r\n<% end %>\r\n     \r\n<script>\r\n        <%\r\n            if dx.size>1 and dx.index \'0\'\r\n                dx.shift     \r\n            end\r\n        %>\r\n        $(\'#data-diagnosis_group\').val(\'<%=dx.join(\'|\')%>\')\r\n        if(typeof(update_diagnosis_group_rev_func)!=\'undefined\')\r\n             update_diagnosis_group_rev_func(); \r\n         <% unless params[:init] %>\r\n        var editor = $(\"#data-diagnosis_text\").data(\"kendoEditor\");\r\n        if(typeof(editor)!=\'undefined\'){\r\n            editor.value(\'<%=dx_text.join(\", \").html_safe()%>\')   \r\n            \r\n        }\r\n        \r\n        \r\n        $(\'#data-intervention_group\').val(\'<%=intervention_list.keys.join(\'|\')%>\')\r\n        $(\'#finding_intervention_group\').val(\'<%=intervention_list.keys.join(\'|\')%>\')\r\n\r\n        if(typeof(update_intervention_group_rev_func)!=\'undefined\')\r\n             update_intervention_group_rev_func(); \r\n        \r\n        var editor = $(\"#data-intervention_text\").data(\"kendoEditor\");\r\n        if(typeof(editor)!=\'undefined\'){\r\n            editor.value(\'<%=intv_text.collect{|i|\"\\\\#{i}<br/>\" }.join().html_safe()%>\')   \r\n        }\r\n        <% end %>\r\n</script>\r\n\r\n<%=hidden_field_tag \'finding_intervention_group\', \'\', :id=>\"finding_intervention_group\" %>\r\n    \r\n<div class=\'clear\'></div>\r\n    \r\n</div>\r\n\r\n<%= hidden_field_tag \"record[findings]\",\"\\\\#{records.collect{|j| j.id}.to_json}\", :id=>\"data-\\\\#{f}\" %>\r\n\r\n    \r\n    \r\n<div class=\'clear\'></div>\r\n<%# config.inspect %>\r\n<%# params.inspect  %>\r\n\r\n<% end %>\r\n<script>\r\n    refresh_remote();\r\n\r\n<% if params[:init] %>\r\n\r\n\r\n\r\n$(\'#finding_intervention_group\').val(\'<%=intervention_list.keys.join(\'|\')%>\')\r\n\r\nfunction selectTag(tag){\r\n    \r\n    // obj = $(this)\r\n    console.log(tag)\r\n    \r\n}\r\n\r\n\r\nfunction cancelFinding(){\r\n\r\nvar v = eval($(\'#data-findings\').val()).join(\'|\')\r\nloading();\r\n$.ajax({\r\n  url: \"finding_ajax\",\r\n  method: \"POST\",\r\n  data: { update:\'findings\', values: v },\r\n  cache: false\r\n})\r\n.done(function( html ) {\r\n    $( \"#findings\" ).html( html );\r\n    done();\r\n});\r\n\r\n\r\n\r\n}\r\n\r\n\r\n\r\nfunction deleteFinding(rid){\r\n\r\n\r\nvar v = eval($(\'#data-findings\').val())\r\nindex = v.indexOf(rid)\r\nv.splice(index, 1);\r\nv = v.join(\"|\")\r\n\r\nloading();\r\n$.ajax({\r\n  url: \"finding_ajax\",\r\n  method: \"POST\",\r\n  data: {func:\'delete\',update:\'findings\', values: v },\r\n  cache: false\r\n})\r\n.done(function( html ) {\r\n    $( \"#findings\" ).html( html );\r\n    done();\r\n});\r\n\r\n\r\n\r\n     }\r\n\r\n     function loading(){\r\n         $(\'#finding-msg\').html(\'Loading...\')   \r\n      \r\n     }\r\n     \r\n     function done(){\r\n         $(\'#finding-msg\').html(\'\')   \r\n      \r\n     }\r\n     \r\n     function addBy(k){\r\n         \r\n    loading()     \r\n$.ajax({\r\n  url: \"finding_ajax\",\r\n  method: \"POST\",\r\n  data: { func:\'create\', update:\'finding-status\', add_by : \'location\', add_value: k },\r\n  cache: false\r\n})\r\n.done(function( html ) {\r\n    $( \"#finding-status\" ).html( html );\r\n    done();\r\n});\r\n\r\n\r\n     }\r\n     function updateDx(){\r\n         \r\n      console.log(\"Call DXXXXX\")\r\n \r\n\r\n      diagnosis_text = \'None\'\r\n        \r\n      var editor = $(\"#data-diagnosis_text\").data(\"kendoEditor\");\r\n      \r\n        if(typeof(editor)!=\'undefined\'){\r\n            <% \r\n               views = config[:view]\r\n               for i in views\r\n            %>\r\n             var finding_content = $(\"#data-<%=i[:editor_id]%>\").data(\"kendoEditor\").value();\r\n             if(finding_content==\'\'){ \r\n                 finding_content = \'Normal\'\r\n             }else{\r\n                 if(finding_content!=\'Normal\')\r\n                 $(\"#<%=i[:report_id]%>\").parent().parent().show();\r\n             }\r\n             $(\'#<%=i[:report_id]%>\').html(finding_content)\r\n            <% end %>   \r\n            //   console.log(\"dx\")\r\n            \r\n              var comment = editor.value();\r\n              if(comment==\'\')comment=\'Normal\'\r\n              \r\n              var editor_normal = $(\"#data-normal_summary\").data(\"kendoEditor\");\r\n              if(typeof(editor_normal)!=\'undefined\')\r\n              comment += \" \" + editor_normal.value()\r\n              \r\n              $(\'#diagnosis-div\').html(comment);\r\n              \r\n              var editor = $(\"#data-intervention_text\").data(\"kendoEditor\");\r\n              var comment = editor.value();\r\n              \r\n              var editor2 = $(\"#data-intervention_summary\").data(\"kendoEditor\");\r\n              var comment2 = editor2.value();\r\n            //   alert(\'update\');\r\n            //   finding_content += \" test\"\r\n            //   if($(\"#data-normal_summary\")!=null){\r\n            //   var editor3 = $(\"#data-normal_summary\").data(\"kendoEditor\");\r\n            //   var comment3 = editor2.value();\r\n            //   comment += comment3\r\n                  \r\n            //   }\r\n              \r\n              if(comment==\'\'&&comment2==\'\')comment=\'None\'\r\n              \r\n              $(\'#intervention-div\').html(comment+\" \"+comment2);\r\n              \r\n              var editor = $(\"#data-comment\").data(\"kendoEditor\");\r\n              var comment = editor.value();\r\n              if(comment==\'\')comment=\'None\'\r\n            //   console.log(\"com\")\r\n              $(\'#comment-div\').html(comment);\r\n              \r\n              \r\n            \r\n            //   console.log(\"other\")\r\n              var editor = $(\"#data-finding_other_detail\").data(\"kendoEditor\");\r\n              var value = editor.value()\r\n              if(value&&value!=\'\'){\r\n                $(\'#other-finding-div\').html(value);\r\n                $(\'#other-finding-panel\').show()\r\n              }else{\r\n                $(\'#other-finding-panel\').hide() \r\n              }\r\n              \r\n              \r\n              \r\n        }else{\r\n            \r\n              var comment = $(\'#data-diagnosis_text\').val()\r\n              if(comment==\'\') comment = \'Normal\'\r\n              \r\n              if(typeof $(\"#data-normal_summary\").val()!=\'undefined\'){\r\n                var editor_normal = $(\"#data-normal_summary\").val()\r\n                console.log($(\"#data-normal_summary\").val())            \r\n                comment += \" \" + editor_normal\r\n              }\r\n              \r\n              $(\'#diagnosis-div\').html(comment);\r\n              \r\n              var comment = $(\'#data-intervention_text\').val()\r\n              var comment2 = \'\'\r\n              \r\n              comment2_o = $(\'#data-intervention_summary\')\r\n              if(typeof comment2_o !=\'undefined\'){\r\n                   comment2 = comment2_o.val()\r\n              }\r\n\r\n              if(comment==\'\'&&comment2==\'\') comment = \'None\'\r\n              $(\'#intervention-div\').html(comment+\" \"+comment2);\r\n              \r\n              \r\n              \r\n              var comment = $(\'#data-comment\').val()\r\n              if(comment==\'\') comment = \'None\'\r\n              $(\'#comment-div\').html(comment);\r\n              \r\n              var value = $(\'#data-finding_other_detail\').val();\r\n              if(value&&value!=\'\'){\r\n                $(\'#other-finding-div\').html(value);\r\n                $(\'#other-finding-panel\').show()\r\n              }\r\n\r\n               <% \r\n               views = config[:view]\r\n                  for i in views\r\n               %>  \r\n                var comment = $(\"#data-<%=i[:editor_id]%>\").val()\r\n                 if(comment==\'\'){\r\n                     comment = \'Normal\'\r\n                }else{\r\n                     if(comment!=\'Normal\')\r\n                     $(\"#<%=i[:report_id]%>\").parent().parent().show();\r\n                }\r\n                $(\'#<%=i[:report_id]%>\').html(comment)\r\n                \r\n               <% end %>\r\n        }\r\n            \r\n      \r\n    }    \r\n          console.log(\"Call init xxxx\")\r\n\r\n\r\n       tree = esm_helper.get(\'<%=this.document_name%>\')\r\n       tree.regMonitor(updateDx);\r\n       tree.initReport();\r\n       tree.updateReport();\r\n       tree.sizeMonitor();\r\n       \r\n\r\n\r\n<% else %>\r\n      tree = esm_helper.get(\'<%=this.document_name%>\')\r\n     if(tree){\r\n          tree.updateReport();\r\n        