]\r\n        }\r\n    }, {   :title=>\'PHG\',\r\n        :relation=>\'one\',\r\n        :finding_text=>\"PHG was seen.\",\r\n        :multiple_finding_text=>[\"not define\",\"NA\"],\r\n        :final_text=>[\"PHG\",\"\"],\r\n        :dx_id=>\'52\',\r\n        :values=>{\r\n            :disease=>\'phg\',\r\n            :location=>%w{esophagus},\r\n            :intervention=>[]\r\n        }\r\n    },{   :title=>\'Ulcer\',\r\n        :relation=>\'many\',\r\n        :finding_text=> \"A :ulcer_size -cm. :ulcer_shape :ulcer_stigmata ulcer was seen at :location :ulcer_comment .\",\r\n        :multiple_finding_text=>[\"A :ulcer_size -cm. :ulcer_shape :ulcer_stigmata ulcer at :location :ulcer_comment\",\":values were seen.\"],\r\n        :final_text=>[\"A :ulcer_size -cm. :ulcer_shape :ulcer_stigmata ulcer at :location :ulcer_comment\",\":values\"],\r\n        :dx_id=>\'3\',\r\n        :values=>{\r\n            :disease=>\'ulcer\',\r\n            :location=>%w{esophagus stomach duodenum},\r\n            :intervention=>[]\r\n        }\r\n    },\r\n    {   :title=>\'Polyp\',\r\n        :relation=>\'many\',\r\n        :finding_text=> \"A :polyp_size -cm. :polyp_shape :polyp_comment polyp was seen at :location.\",\r\n        :multiple_finding_text=>[\"A :polyp_size -cm. :polyp_shape :polyp_comment polyp at :location\",\":values were seen.\"],\r\n        :final_text=>[\"A :polyp_size -cm. :polyp_shape :polyp_comment polyp at :location\",\":values\"],\r\n        :dx_id=>\'6\',\r\n        :values=>{\r\n            :disease=>\'polyp\',\r\n            :location=>%w{esophagus stomach duodenum},\r\n            :intervention=>[]\r\n        }\r\n    },\r\n    {   :title=>\'Coustic ingestion\',\r\n        :relation=>\'one\',\r\n        :finding_text=> \"Coustic ingestion\",\r\n        :dx_id=>\'7\',\r\n        :values=>{\r\n            :disease=>\'coustic_ingestion\'\r\n        }\r\n    },\r\n    {   :title=>\'Mallory-Weiss tear\',\r\n        :relation=>\'one\',\r\n        :finding_text=> \"Mallory-Weiss tear\",\r\n        :dx_id=>\'8\',\r\n        :values=>{\r\n            :disease=>\'mallory_weiss\'\r\n        }\r\n    }\r\n]\r\n}',NULL,NULL,NULL,'2015-04-22 18:14:37','2015-04-22 18:14:37','finding_config',''),(1451,'display_script',674,4,'<style>\r\n    v{color:blue};\r\n</style>\r\n\r\n\r\n\r\n\r\n<script>\r\n    function inspect_finding(){\r\n        console.log(\"call inspect _finding \")\r\n    }\r\n  \r\n</script>\r\n    \r\n<div id=\"finding-div\" style=\"width:500px\"></div>\r\n\r\n<script>\r\n\r\nvar define_inspector = null;\r\n\r\n\r\n$( document ).ready(function() {\r\n\r\n\r\ndefine_inspector = true    \r\ntree.regMonitor(inspect_finding);\r\n\r\nvalues = $(\'#data-findings\').val()\r\nvalues = eval(values).join(\"|\")\r\n            \r\n        \r\n$.ajax({\r\n  url: \"finding_ajax\",\r\n  method: \"POST\",\r\n  data: { values : values },\r\n  cache: false\r\n})\r\n.done(function( html ) {\r\n    $( \"#findings\" ).html( html );\r\n});\r\n\r\n});\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-04-22 18:17:52','2015-04-22 18:17:52','display_script',''),(1452,'index',675,2,'<style>\r\n    .red{color:red};\r\n</style>\r\n<h1>Recovery Function</h1>\r\n\r\n<hr/>\r\n\r\n<li><%= link_to \'Check Colono / Gastro association\', \'associate_colono\' %></li>\r\n<li><%= link_to \'Check IntraOp / PostOp\', \'associate_intra_post\' %>  .. Underconstruction  </li>\r\n<li><%= link_to \'Check PreOp\', \'associate_preop\' %>  .. Underconstruction  </li>\r\n<li><%= link_to \'Check Appointment association\', \'appointment_clean\' %></li>\r\n<li><%= link_to \'Check Patho association\', \'patho_clean\' %> .. Underconstruction </li>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-04-23 08:44:12','2015-04-23 08:44:12','index',''),(1453,'partial',675,3,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    \r\n    patient = patient_model.where(:hn=>params[:q].strip).first\r\n    if patient \r\n        gender = \'ไม่ระบุ\'\r\n        case patient.gender\r\n        when \'1\'\r\n        gender = \'ชาย\'\r\n        when \'2\'\r\n        gender = \'หญิง\'\r\n        else\r\n        end\r\n%>\r\n<span style=\"color:blue\">\r\n<%=patient.hn %> <%=gender %> <br/>  <%=patient.first_name %> <%=patient.last_name %> </span>\r\n<script>\r\n    \r\n    $(\'#v<%=params[:id]%>\').val(\'<%=patient.id%>\')\r\n \r\n</script>\r\n<% else %>\r\n<span style=\"color:red\">Not Found</span>\r\n<%=params.inspect %>\r\n\r\n<% end %>\r\n\r\n\r\n',NULL,NULL,NULL,'2015-04-23 16:48:07','2015-04-23 16:48:07','partial',''),(1454,'index_post',675,2,'<%\r\n   if request.post?\r\n       \r\n    mx = {:colonoscopy=>\'Colonoscopy\',:gastroscopy=>\'Gastroscopy\'}\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    mpm = model[:patient_module]\r\n    \r\n    models = get_model\r\n    \r\n    mapp = models[:appointment]\r\n    \r\n    about = []\r\n    \r\n    mabout = {}\r\n    \r\n    pname = @current_project.name\r\n    \r\n    mx.keys.each do |i|\r\n       \r\n       objects = params[\"\\\\#{i}_ass\"]\r\n       if objects\r\n       objects.each_pair do | module_id, patient_id |\r\n    \r\n      \r\n             date = Date.to_mongo(Time.zone.parse(params[:date].split(\'/\').reverse.join(\"-\")))\r\n             time = models[i].find(module_id).created_at\r\n             \r\n            \r\n             if patient_id and patient_id!=nil\r\n            \r\n             all_mapp = mpm.where(:patient_id=>patient_id, :module_name=>\"\\\\#{pname}#appointment\").to_a.collect{|i| i.module_id }\r\n                \r\n             app  = mapp.where(:date=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}, \'_id\'=>{ \'$in\'=> all_mapp }).first\r\n             \r\n             provider_id = params[\"\\\\#{i}_provider\"][module_id]\r\n             \r\n             if app\r\n                m = mpm.where(:patient_id=>patient_id, :module_id=>app.id).first\r\n                about << [:create_link_exist,mpm.new(:ref_number=>\'00000\',:date=>date,:module_id=>module_id,:patient_id=>patient_id,:module_name=>\"\\\\#{pname}#\\\\#{i}\",:parent_id=>m.id)]\r\n                \r\n             else\r\n                \r\n                unless mabout[patient_id]\r\n                \r\n                app = mapp.new :date=>params[:date], :status=>\'Completed\', :provider=>provider_id, :procedure=>nil\r\n                about << [:create_app,app]\r\n                x = mpm.new(:ref_number=>\'00000\',:time=>time,:date=>date,:module_id=>app.id,:patient_id=>patient_id,:module_name=>\"\\\\#{pname}#appointment\")\r\n                about << [:create_app_link,x]\r\n                about << [:create_link,mpm.new(:ref_number=>\'00000\',:time=>time,:date=>date,:module_id=>module_id,:patient_id=>patient_id,:module_name=>\"\\\\#{pname}#\\\\#{i}\",:parent_id=>x.id)]\r\n                mabout[patient_id]=x\r\n                \r\n                else\r\n                \r\n                about << [:create_link_with,mpm.new(:ref_number=>\'00000\',:time=>time,:date=>date,:module_id=>module_id,:patient_id=>patient_id,:module_name=>\"\\\\#{pname}#\\\\#{i}\",:parent_id=>mabout[patient_id].id)]\r\n\r\n                end\r\n                \r\n                 \r\n             end\r\n            end\r\n       end\r\n       end\r\n        \r\n        \r\n    end\r\n    %>\r\n    <h1>Summary</h1>\r\n    <ul>\r\n    <%\r\n    for i in about\r\n    %>\r\n    <li>\r\n    <span style=\"color:blue\"><%= i[0]%></span> : <%= i[1].inspect %></li>\r\n    <% end %>\r\n    </ul>\r\n    \r\n    \r\n    <%\r\n    \r\n    \r\n    if params[:commit_to_db]\r\n    for i in about   \r\n        i[1].save\r\n    end\r\n%>\r\nOK\r\n<meta http-equiv=\"refresh\" content=\"0; url=associate_colono\" />\r\n<% else %>\r\n    <%= form_for :query, :url=>\'index_post\' do |f|%>\r\n    <h1>Review</h1>\r\n    <%=hidden_field_tag \'date\', params[:date] %>\r\n    <%=hidden_field_tag \'commit_to_db\', \'true\' %>\r\n    <%\r\n\r\n        mx.each_pair do |mx_name,mx_label|\r\n            %>\r\n    <h1><%=mx_label%></h1>\r\n    <%\r\n        if  params[\"\\\\#{mx_name}_ass\"]\r\n    \r\n        params[\"\\\\#{mx_name}_ass\"].each_pair do |module_id, patient_id|\r\n    %>\r\n    <li>\r\n        Module_id = <%=module_id%> , Patient_id = <%=patient_id%>\r\n        <%=text_field_tag \"\\\\#{mx_name}_ass[\\\\#{module_id}]\" ,patient_id %>\r\n        <%=text_field_tag \"\\\\#{mx_name}_provider[\\\\#{module_id}]\" , params[\"\\\\#{mx_name}_provider\"][\"\\\\#{module_id}\"] %>\r\n\r\n\r\n    </li>    \r\n    <% end %>\r\n    <% end %>\r\n    <% end %>\r\n    <%=f.submit \'Commit\', :data=>{:confirm=>\'Are you confirm?\'}, :class=>\'btn btn-info\'%>\r\n    <% end %>\r\n\r\n     \r\n<% end %>\r\n\r\n<% end %>\r\n\r\n<%= link_to \'Show\', \"../Home/index?date=\\\\#{params[:date]}\" %> |\r\n\r\n\r\n<%= link_to \'Back\', \"associate_colono?date=\\\\#{params[:date]}\" %> <br/>\r\n\r\n<%= params.inspect %>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-04-23 17:06:09','2015-04-23 17:06:09','index_post',''),(1455,'edit',676,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  \r\n  return_url = url(\"index\")\r\n  return_url = params[:return] if params[:return]\r\n\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n    # record = doc.record_update(model,params,record)\r\n    # record = doc.record_update(record)\r\n    record.update_attributes params[:record]\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<!-- <pre><%# params.inspect %></pre> -->\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small btn-success\'>Update</button> |\r\n<!-- zamachita change back link to history.back() -->\r\n<% # link_to \'Back\', url(\'index\') %>\r\n<% # link_to \'Back\', \'javascript:history.back()\' %>\r\n<%\r\n    if params[:return]\r\n%>\r\n<%= link_to \'Cancel\', params[:return] %>\r\n<%\r\n    elsif\r\n%>\r\n<%= link_to \'Back\', \'javascript:history.back()\' %>\r\n<%\r\nend # end_if \'Back\' link\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<%\r\n    if false\r\n%>\r\n<%\r\n    fields = \'<div id=\"height\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\'\\\r\n            \'<span class=\"\"><label>Height (cm.) : </label></span>\'\\\r\n            \'<input type=\"text\" name=\"record[height]\" id=\"data-height\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\'\\\r\n            \'</div>\'\\\r\n            \'<div id=\"weight\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\'\\\r\n            \'<span class=\"\"><label>Weight (kg.) : </label></span>\'\\\r\n            \'<input type=\"text\" name=\"record[weight]\" id=\"data-weight\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\'\\\r\n            \'</div>\'\\\r\n            \'<div id=\"bmi\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\'\\\r\n            \'<span class=\"\"><label>BMI : </label></span>\'\\\r\n            \'<input type=\"text\" name=\"record[bmi]\" id=\"data-bmi\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\'\\\r\n            \'</div>\'\r\n%>\r\n<script>\r\n    function bmi_update() {\r\n        h = isNaN(parseFloat($(\'#data-height\').val())) ? 0 : parseFloat($(\'#data-height\').val());\r\n        w = isNaN(parseFloat($(\'#data-weight\').val())) ? 0 : parseFloat($(\'#data-weight\').val());\r\n        \r\n        h = h/100;\r\n        bmi = 0\r\n        if (h != 0) {\r\n            bmi = w / (h * h)\r\n            $(\'#data-bmi\').val(bmi.toFixed(2));\r\n            // console.log(\'BMI = \' + bmi)\r\n        }\r\n    }\r\n    $(document).ready(function() {\r\n        $(\'<%= fields.html_safe %>\').insertAfter($(\'#birth_date\'));\r\n        \r\n<% if record[:bmi] %>\r\n        $(\'#data-bmi\').val(\'<%= record[:bmi] %>\');\r\n        $(\'#data-height\').val(\'<%= record[:height] %>\');\r\n        $(\'#data-weight\').val(\'<%= record[:weight] %>\');\r\n<% else %>\r\n        $(\'#data-bmi\').val(\'0.00\');\r\n<% end %>\r\n\r\n        $(\'#data-height\').change(bmi_update);\r\n        $(\'#data-weight\').change(bmi_update);\r\n        console.log(\'fin\');\r\n    });\r\n</script>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2015-04-26 07:54:43','2015-04-26 07:54:43','edit',''),(1456,'test',668,3,'<%\r\n    doc = get_document this.document_name\r\n    \r\n    params[:doc] = doc.inspect\r\n    params[:doc_name] = this.document_name\r\n%>\r\n<%= params.to_json.html_safe %>',NULL,NULL,NULL,'2015-04-26 08:19:10','2015-04-26 08:19:10','test',''),(1457,'search_result',676,3,'<% \r\n\r\n	require \'time_diff\'\r\n\r\n    models = get_model  \r\n\r\n  