data[i][1] %>\r\n    <br/>\r\n    <% end %>\r\n    \r\n    \r\n    \r\n</pre>\r\n\r\n <div style=\"padding:5px;width:720px; margin-left:auto; margin-right:auto\" >\r\n\r\nRef : <%= @patient_module.ref_number %> \r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n<p style=\"width:720px; margin-left:auto; margin-right:auto; font-weight:bold\">HN : <%= @patient.hn %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Name : <%= @patient.first_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Surname : <%= @patient.last_name %></p>\r\n<hr /><br />\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>',NULL,NULL,NULL,'2015-04-30 06:49:34','2015-04-30 06:49:34','display',''),(1475,'patient',666,2,'    \r\n    <% Time.zone =  get_setting \'time_zone\' %>\r\n    <style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    </style>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n    <div class=\"w-box\">\r\n        <div class=\"w-box-header\">\r\n            Patient Medical Records\r\n            <div class=\"pull-right\">\r\n            <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n            </div> \r\n        </div>  \r\n        <div class=\"w-box-content cnt_a\">\r\n        \r\n    <%\r\n    \r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        ehr_models = ehr.get_model\r\n        patient_model = ehr_models[:patient]\r\n        patient_module_model = ehr_models[:patient_module]\r\n        groups = this.config\r\n        emr_models = get_model\r\n        ap = emr_models[:appointment].find(params[:id])\r\n        pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n        \r\n        locker_model = emr_models[:locker]\r\n        if params[:reset_lock]\r\n            l = locker_model.find(params[:reset_lock])\r\n            l.destroy if l\r\n        end\r\n        #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n        #i.destroy if i\r\n        #end\r\n         \r\n        \r\n        \r\n        if pm\r\n        \r\n            if  params[:schema_patient_module]\r\n               pm.update_attributes params[:schema_patient_module]\r\n            end\r\n            \r\n            if params[:provider_id]\r\n              ap.update_attributes :provider=>params[:provider_id]\r\n               ap = emr_models[:appointment].find(params[:id])\r\n            end\r\n        \r\n        # find provider\r\n            provider = emr_models[:provider].find(ap.provider.to_s)\r\n        \r\n        # find patient\r\n            patient = patient_model.find(pm.patient_id)\r\n        \r\n            params[:patient]=patient\r\n            params[:patient_module]=pm\r\n        \r\n       # s = Service.get(\'ehr.emr.EmrHelper\')\r\n    #    obj = s.load context\r\n        \r\n            providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n        \r\n    %>\r\n    <!--xxx-->\r\n    <% # emr_models[:appointment].find(params[:id]).inspect %>\r\n    <% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n    <div style=\"border:0px solid\">\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:688px\">\r\n    <%# render :inline=>obj.show_patient %>\r\n    <div id=\"patient\">\r\n    ... Loading Patient Details ...\r\n    </div>\r\n    <script>\r\n    <%\r\n            url = \'../../www/Patient/search_result?\'\r\n            url += \'&id=\'+patient.id.to_s\r\n    %>      \r\n            $.ajax({\r\n              url: \'<%=url.html_safe%>\',\r\n             success: function(data){\r\n              $(\'#patient\').html(data);  \r\n              }\r\n            });\r\n    </script>\r\n    \r\n    <%\r\n    \r\n    \r\n        previous = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\n        history = []\r\n        x = previous[0..7]\r\n        last = []\r\n        last = x.compact if x\r\n        history = []\r\n        y = previous[8..-1]\r\n        history = y.compact if y and  previous.size>5\r\n                                             \r\n        current = time_ago_in_words(ap.date)\r\n        current_date = ap.date.strftime(\"%d-%m-%y\")\r\n        current = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n        \r\n        models = get_model\r\n        \r\n        procedures = (models[:procedure]).to_a\r\n        mprocedures = {}\r\n        for i in procedures\r\n            mprocedures[i.id] = i\r\n        end\r\n        \r\n        \r\n        \r\n        list = %w{primary-hip-left primary-hip-right primary-knee-left primary-knee-right revision-hip-left revision-hip-right revison-knee-left revision-knee-right}\r\n        \r\n        listx = procedures.collect{|i| [i.name,i.id]}\r\n    \r\n    \r\n    \r\n    \r\n    end\r\n    %>\r\n    \r\n    <% # form_for :data,:url=>\"../Appointment/create?\" ,:method=>\'GET\' do |f| %>\r\n    <% # form_for :data, :url=>\"test?\", :method=>\'GET\' do |f| %>\r\n    <%= form_for :data,:url=>\"appointment_create\" ,:method=>\'POST\' do |f| %>\r\n    \r\n    <div class=\"clear\"></div>\r\n    <div>\r\n    <h4 style=\"float:left\"><%= @current_project.title %> Recrods</h4>\r\n     <span style=\"float:right\"><%= f.select \'procedure\' ,options_for_select(listx)  %> \r\n     <%= f.hidden_field :provider,:value=>provider.id %>\r\n     <%= hidden_field_tag :patient_id,patient.id %>\r\n     <%= f.hidden_field :date,:value=>Time.now %>\r\n     <%#f.hidden_field :source,:value=>\'patient_record\' %>\r\n     \r\n     <%=f.submit \'Add New\',:class=>\'btn btn-success\' %></span>\r\n    <div class=\"clear\"></div>\r\n    </div>\r\n    <% end %>\r\n    <div class=\"clear\"></div>\r\n    \r\n    <%\r\n        all_pm =  patient_module_model.where(:patient_id=>patient.id,:module_name=>\"\\\\#{@current_project.name}#appointment\").to_a\r\n        \r\n        list = all_pm.collect do |i| \r\n        \r\n        app = models[:appointment].find(i.module_id)\r\n        procedure = mprocedures[app.procedure]\r\n        mrecord = models[procedure.code.to_s]\r\n        mr = patient_module_model.where(:parent_id=>i.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{procedure.code}\").first\r\n        record = nil\r\n        if mr\r\n        record = mrecord.find(mr.module_id)\r\n        end\r\n        follow_ups = []\r\n        follow_ups = patient_module_model.where(:parent_id=>i.id,:module_name=>\"\\\\#{@current_project.name}#follow_up_form_tka\").to_a\r\n        follow_ups = follow_ups.collect{|j| [j,(models[:follow_up_form_tka]).find(j.module_id)]}.sort{|a,b| a[1][:period].to_f<=>b[1][:period].to_f} \r\n        \r\n        \r\n        {:id=>i.id,:name=>procedure.name,:record=>record,:mrecord=>mr,:procedure=>procedure,:date=>app.inspect,:main=>i,:follow_ups=>follow_ups}\r\n        \r\n        \r\n        end\r\n    %>\r\n    <%# all_pm.inspect  %>\r\n    <br/>\r\n    \r\n    <div class=\"tabbable tabs-left\" style=\"border:1px solid #ccc; -moz-border-radius: 5px;\r\n    border-radius: 5px;\">\r\n    <ul class=\"nav nav-tabs\" style=\"background:#F4F4F4; -moz-border-radius: 5px;border-radius: 5px;\">\r\n    <li class=\"active\" ><a href=\"#tab_dashboard\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >Dashboard</a></li>\r\n    \r\n    <% for i in list %>\r\n    <li class=\"\" ><a href=\"#tab_<%=i[:id]%>\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" ><%=i[:name]%></a></li>\r\n    <% end %>\r\n    </ul>\r\n   \r\n    <div class=\"tab-content\" style=\"width:520px;border:0px solid;float:left; clear:none;margin-left:-20px;\">\r\n    <div class=\"tab-pane  <%= \'active\' if true %>\" style=\"border:0px solid;\" id=\"tab_dashboard\">\r\n    <br/><h3>Dashboard</h3>\r\n    <div class=\"row-fluid\"><br/></div>\r\n    Welcome\r\n    </div>\r\n    \r\n    <% for i in list %>\r\n    <div class=\"tab-pane  <%= \'active\' if false %>\" style=\"border:0px solid;\" id=\"tab_<%=i[:id]%>\">\r\n    <br/><h3><%=i[:name]%></h3>\r\n        <%\r\n        mname = i[:procedure].code.humanize\r\n        mr = i[:mrecord]\r\n        show = \"\"\r\n        if mr\r\n        show = link_to(\"Edit \", \"../\\\\#{mname}/edit?id=\\\\#{mr.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-small\')\r\n        show += \' \'\r\n        show += link_to(\'Print\',\"../\\\\#{mname}/print?id=\\\\#{mr.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'btn btn-small\')\r\n        else\r\n        show =  link_to(\'Create\',\"../\\\\#{mname}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\" ,:class=>bt_class ,:style=>\'\')\r\n        \r\n\r\n        end\r\n    %>\r\n    \r\n    <hr/>\r\n    \r\n    <%= show.html_safe%>\r\n    <hr/> \r\n    Follow Up\r\n    <div class=\"clear\"></div>\r\n    <%=link_to \'Create\',\"../FollowUpFormTka/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\" ,:class=>bt_class ,:style=>\'float:right;margin-top:-30px\'%>\r\n    <%\r\n        lookup={}\r\n        for j in i[:follow_ups]\r\n            lookup[j[1].id] = j[0]\r\n        end\r\n    %>\r\n    <%= tabular :data=> i[:follow_ups].collect{|j| j[1]},:labels=>{:total_womac_score=>\'WOMAC\',:total_knee_score=>\'Knee Score\'} ,:model=>[:period,:date,:height,:weight,:total_womac_score,:total_knee_score] do |row,out|\r\n    l = lookup[row.id]\r\n    out[0] = \"\\\\#{(row.period.to_i)} m\"\r\n    out[1] = l.date.strftime(\"%d-%m-%y\")\r\n    \r\n    show = link_to(\"Edit \", \"../FollowUpFormTka/edit?id=\\\\#{l.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-small\')\r\n    show += \' \'\r\n    show += link_to(\'Print\',\"../FollowUpFormTka/print?id=\\\\#{l.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'btn btn-small\')\r\n    out << show\r\n\r\n    out\r\n    end%>\r\n    \r\n    \r\n    \r\n        \r\n    </div>\r\n     <% end %>\r\n    \r\n    </div>\r\n    \r\n    \r\n    \r\n    \r\n    <%\r\n    if false\r\n    \r\n    \r\n     alist = []\r\n     alist = patient_module_model.where(:patient_id=>patient.id).all\r\n    %>\r\n   \r\n    <br/><br/>\r\n    <div class=\"clear\"></div>\r\n    <%\r\n        pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n        modules = patient_module_model.all(:parent_id=>pm.id,:patient_id=>pm.patient_id).collect do |i|\r\n            name = i.module_name.split(\"#\")[-1]\r\n            hn = patient.hn\r\n            \r\n            rr = link_to(\"\\\\#{i.date.strftime(\"%d-%m-%Y\")} \\\\#{i.time.strftime(\"%H:%M\") if i.time } \", \"../\\\\#{name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\")\r\n            rr += \' \'\r\n            #rr += link_to(\"[ Edit ]\", \"../\\\\#{name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\")\r\n            date = i.date.strftime(\"%d-%m-%y\")\r\n            \r\n            #show = link_to(\'Show\',\"../\\\\#{name.camelize}/show?id=\\\\#{i.id}&record_name=\\\\#{hn}&return=../Home/patient_record?id=\\\\#{ap}\",:class=>\'btn btn-small\')\r\n            show = link_to(\"Edit \", \"../\\\\#{name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-small\')\r\n            show += \' \'\r\n            show += link_to(\'Print\',\"../\\\\#{name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'btn btn-small\')\r\n    \r\n            {:name=>name,:records=>rr.html_safe,:date=>date,:show=>show,:module_name=>name}\r\n        end\r\n    \r\n    %>\r\n    <div class=\"tabbable tabs-left\" style=\"border:1px solid #ccc; -moz-border-radius: 5px;\r\n    border-radius: 5px;\">\r\n    <ul class=\"nav nav-tabs\" style=\"background:#F4F4F4; -moz-border-radius: 5px;border-radius: 5px;\">\r\n    <li class=\"active\" ><a href=\"#tab_dashboard\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >Dashboard</a></li>\r\n    <%\r\n    for g in groups \r\n       services = g[:actions].collect{|i| [@current_project.get_service(i[:service]), i[:name]]}.compact\r\n       %> \r\n    <li class=\"\" ><span style=\"font-size:14px;padding:10px\"><%=g[:name]%></span></li>\r\n       <%\r\n       for st in services\r\n       s = st[0]\r\n       name = st[1]\r\n       n = modules.collect{|i| i if i[:module_name]==s.name }.compact.size\r\n    %>\r\n    <li class=\"<%#\'active\' if s == services[0]%>\" style=\"border:0px solid;width:150px;overflow:hidden\"><a href=\"#tab_<%=s.id%>\" data-toggle=\"tab\" style=\"font-size:12px; padding:10px\">- <%=name%>\r\n    <%= \"(\\\\#{n})\" if n>0 %>\r\n    </a></li>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    </ul>\r\n    \r\n    \r\n    <div class=\"tab-content\" style=\"width:520px;border:0px solid;float:left; clear:none;margin-left:-20px;\">\r\n    <div class=\"tab-pane  <%= \'active\' if true %>\" style=\"border:0px solid;\" id=\"tab_dashboard\">\r\n    <br/><h3>Dashboard</h3>\r\n    \r\n    <div style=\'float:right;margin-top:-30px\'>\r\n    <%\r\n      title_map = {}\r\n      services.each {|i| \r\n      \r\n      title_map[i[0].name] = i[1]\r\n      \r\n      }  \r\n      \r\n      \r\n    %>\r\n    <%# link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class %>\r\n    </div>\r\n    \r\n    <%= tabular :data=> modules,:model=>[:name,:records,:show] do |row,out|\r\n    out[0] = title_map[row[:name]]\r\n    out\r\n    end%>\r\n    \r\n    </div>\r\n    <%# title_map%>\r\n    \r\n    <%\r\n    for g in groups \r\n       services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n       for s in services\r\n    %>\r\n    <div class=\"tab-pane  <%# \'active\' if s==services[0] %>\" id=\"tab_<%=s.id%>\"  style=\"border:0px solid;\">\r\n    <br/><h3><%=s.title%></h3>\r\n    \r\n    <%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class ,:style=>\'float:right;margin-top:-30px\'%>\r\n    \r\n    <%= tabular :data=> modules.collect{|i| i if i[:module_name]==s.name }.compact ,:model=>[:title,:records,:show] do |row,out|\r\n    out[0] = s.title\r\n    out\r\n    end%>\r\n    \r\n    </div>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    <% end %>\r\n   </div>\r\n   </div>\r\n    \r\n    \r\n    \r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    <br/><br/>\r\n    \r\n    \r\n    <script>\r\n    $(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n    </script>\r\n     \r\n',NULL,NULL,NULL,'2015-05-01 08:20:45','2015-05-01 08:20:45','patient',''),(1476,'appointment_create',666,3,'<%\r\n    models = get_model\r\n    m_provider = models[:provider]\r\n    m_appointment = models[:appointment]\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient = ehr_models[:patient]\r\n    m_patient_module = ehr_models[:patient_module]\r\n    \r\n    # create appointment and add to patient_module\r\n    record = m_appointment.create :procedure=>params[:data][:procedure], :provider=>params[:data][:provider], :status=>\'Appointed\', :start=>params[:data][:date], :stop=>params[:data][:date], :date=>Time.now.strftime(\"%Y-%m-%d\")\r\n    m = m_patient_module.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>\"\\\\#{@current_project.name}#appointment\",:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    \r\n    procedure = (models[:procedure]).find(record.procedure)\r\n    s = procedure[:code].capitalize\r\n    patient = m_patient.find(params[:patient_id])\r\n    \r\n    ss = \'0\'\r\n    if params[:s] == \'1\'\r\n        ss = \'1\'\r\n    elsif params[:s] == \'2\'\r\n        ss = \'2\'\r\n    end\r\n    \r\n    # params[:next_service] = \"../\\\\#{s}/create?patient_id=\\\\#{params[:patient_id]}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{m.id}&return=/thks/thks/Home/patient_record?id=\\\\#{params[:patient_id]}\"\r\n    params[:next_service] = \"../\\\\#{s}/create?patient_id=\\\\#{params[:patient_id]}&s=\\\\#{ss}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{m.id}&return=\\\\#{params[:return]}\"\r\n    # params[:appointment_size] = m_appointment.size\r\n    # params[:all_appointment] = m_appointment.to_a\r\n%>\r\n<%# params.to_json.html_safe %>\r\n<script type=\"text/javascript\">\r\n    window.location = \"<%=params[:next_service].html_safe%>\"\r\n</script>',NULL,NULL,NULL,'2015-05-01 08:26:16','2015-05-01 08:26:16','appointment_create','*'),(1478,'finding_template',674,1,'{\r\n:name=>\'NA\'