5-07 00:51:04','2015-05-07 00:51:04','setting',''),(1483,'document_name',688,1,'\'sigmoid_copy\'',NULL,NULL,NULL,'2015-05-08 03:01:02','2015-05-08 03:01:02',NULL,NULL),(1484,'index_bk',689,2,'<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% -34px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .collapsed {\r\n        background-position: 98% 12px;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n</style>\r\n    <!-- nice form elements -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/uniform/Aristo/uniform.aristo.css\" />\r\n	<!-- 2col multiselect -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/multiselect/css/multi-select.css\" />\r\n\r\n<%= render :inline=>this.init %>\r\n\r\n<%\r\n    msg = []\r\n    tmp = nil\r\n    suc_msg = nil\r\n    \r\n    if request.post?\r\n        if !params[:account].nil?\r\n            if params[:account][:login_name].empty?\r\n                msg.push(\'Invalid login name\')\r\n            end\r\n            if params[:account][:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if params[:account][:password].empty?\r\n                msg.push(\'No password found\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>params[:account][:login_name]).first\r\n                if m_user\r\n                    msg.push(\'Existing login name\')\r\n                else\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(params[:account][:password], salt)\r\n                    tmp = salt + \'...\' + hashed_password\r\n                    m_user = @ehr_models[:user].create :role=>params[:account][:role], :login=>params[:account][:login_name], :salt=>salt, :hashed_password=>hashed_password, :email=>params[:account][:email], :name=>params[:account][:full_name], :activate=>\"true\"\r\n                    tmp = m_user.id.to_s\r\n                    \r\n                    m_provider = @models[:provider].create :group=>\'default\', :name=>params[:account][:full_name], :login=>params[:account][:login_name], :provider_type=>\'1\'\r\n                    tmp += \'...\' + m_provider.id.to_s\r\n                end\r\n            end\r\n        elsif !params[:profile].nil?\r\n            px = params[:profile]\r\n            if px[:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if px[:cur_password].empty?\r\n                msg.push(\'No password to confirm your change\')\r\n            else\r\n                if px[:new_password] != px[:con_password]\r\n                    msg.push(\"Your confirm password not match the new password. Try again.\")\r\n                end\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>px[:login_name]).first\r\n                salt = m_user[:salt]\r\n                hashed_password = User.encrypt(px[:cur_password], salt)\r\n                if m_user[:hashed_password] == hashed_password\r\n                    if px[:con_password] == px[:new_password] and px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov[:main_hospital] = px[:main_hospital]\r\n                            m_prov[:part_time_hospital] = px[:part_time_hospital].join(\'|\') if !px[:part_time_hospital].nil?\r\n                            # m_prov.update_attributes(:main_hospital=>px[:main_hospital],:name=>px[:full_name],:part_time_hospital=>px[:part_time_hospital])\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        suc_msg= \"<strong>Success</strong> Your profile has been change\".html_safe\r\n                    elsif px[:con_password] == px[:new_password] and !px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov[:main_hospital] = px[:main_hospital]\r\n                            m_prov[:part_time_hospital] = px[:part_time_hospital].join(\'|\') if !px[:part_time_hospital].nil?\r\n                            # m_prov.update_attributes(:main_hospital=>px[:main_hospital],:name=>px[:full_name],:part_time_hospital=>px[:part_time_hospital])\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(px[:new_password], salt)\r\n                        m_user[:hashed_password] = hashed_password\r\n                        m_user[:salt] = salt\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your profile and password has been change\".html_safe\r\n                    else\r\n                        msg.push(\'Your new and confirm password does not match\')\r\n                    end\r\n                    \r\n                else\r\n                    msg.push(\'Your current password does not match\')\r\n                end\r\n                # msg.push(px[:login_name])\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n<%#list.inspect%>\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                            <div id=\"accordion1\" class=\"accordion\">\r\n<%\r\n    # check admin or developer role\r\n    if @current_role == \'admin\' or @current_role == \'developer\'\r\n        usr = @ehr_models[:user].all.collect do |i|\r\n            role = @ehr_models[:role].find(i.role)\r\n            role_name = \'undefined\'\r\n            if role\r\n                role_name = role[:name]\r\n            end\r\n            provider = @models[:provider].where(:login=>i.login).first\r\n            \r\n            if provider\r\n                {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :i=>i}\r\n            end\r\n        end\r\n%>\r\n<%\r\n    if !msg.empty?\r\n        for m in msg do\r\n%>\r\n                                <div class=\"alert alert-error\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= m %>\r\n    							</div>\r\n<%\r\n        end\r\n    elsif suc_msg\r\n%>\r\n                                <div class=\"alert alert-success\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= suc_msg %>\r\n    							</div>\r\n<%\r\n    end\r\n%>\r\n<% \r\n        m_hos = @models[:hospital]\r\n        m_com = @models[:company]\r\n        m_kcom = @models[:knee_component]\r\n        \r\n        c_hos = m_hos.all.count\r\n        c_com = m_com.all.count\r\n        c_kcom = m_kcom.all.count\r\n%>\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#admin-control\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Admin Control\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse\" id=\"admin-control\">\r\n										<div class=\"accordion-inner\">\r\n										    <ul class=\"dshb_icoNav tac\">\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/first-aid.png)\" href=\"../Hospital/index\">\r\n										                <span class=\"label label-success\"><%= c_hos > 100 ? \"+100\" : c_hos.to_s %></span> Hospital</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/home.png)\" href=\"../Company/index\">\r\n										                <span class=\"label label-important\"><%= c_com > 100 ? \"+100\" : c_com.to_s %></span> Company</a></li>\r\n										        <li><a style=\"font-size:.8em;background-image: url(/esm/thks/thks/content/knee.jpg);background-size: 52px 52px;\" href=\"../KneeComponent/index\">\r\n										                <span class=\"label label-info\"><%= c_kcom > 100 ? \"+100\" : c_kcom.to_s %></span> Knee Component</a></li>\r\n										        <li><a style=\"background-image: url(/esm/thks/thks/content/hip.jpg);background-size: 52px 52px;\" href=\"javascript:void(0)\">\r\n										                <span class=\"label label-info\">0</span> Hip Component</a></li>\r\n										    </ul>\r\n										    <!--\r\n										    <ul class=\"dshb_icoNav tac\">\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/multi-agents.png)\" href=\"javascript:void(0)\"><span class=\"label label-info\">+10</span> Users</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/world.png)\" href=\"javascript:void(0)\">Map</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/configuration.png)\" href=\"javascript:void(0)\">Settings</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/lab.png)\" href=\"javascript:void(0)\">Lab</a>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/van.png)\" href=\"javascript:void(0)\"><span class=\"label label-success\">$2851</span> Delivery</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/pie-chart.png)\" href=\"javascript:void(0)\">Charts</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/edit.png)\" href=\"javascript:void(0)\">Add New Article</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/add-item.png)\" href=\"javascript:void(0)\"> Add New Page</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/chat-.png)\" href=\"javascript:void(0)\"><span class=\"label label-important\">26</span> Comments</a></li>\r\n                							</ul>\r\n                							-->\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Manage Account\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse\" id=\"collapseOne1\">\r\n										<div class=\"accordion-inner\">\r\n										    <!--<div id=\"form-panel\" class=\"row-fluid\"><%= link_to \'Add New\', \'add_new?update=form-panel\', :remote=>true, :class=>\'btn\', :style=>\'float:right\' %>-->\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :account, :url=>\"index\", :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Add New Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">no space, special characters</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'member\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:class=>\'btn\', :style=>\'vertical-align: top;\' %></span>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n											<!--<hr/>-->\r\n                                            <div id=\"account\">\r\n											<table class=\"table\">\r\n        										<thead>\r\n        											<tr>\r\n        												<th>No.</th>\r\n        												<th>Login Name</th>\r\n        												<th>Name</th>\r\n        												<th>Role</th>\r\n        												<th>Actions</th>\r\n        											</tr>\r\n        										</thead>\r\n        										<tbody>\r\n        										<% \r\n        										    no = 1\r\n        										    for i in usr.compact do\r\n        										\r\n        										%>\r\n        										    <tr>\r\n        										        <td><%= no %>.</td>\r\n        										        <td><%= i[:login] %></td>\r\n        										        <td><%= i[:provider_name] %></td>\r\n        										        <td><%= i[:role_name] %></td>\r\n        										        <td>\r\n        										            <%= link_to \'\', \'#\', :title=>\'Delete Account\', :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>&nbsp;&nbsp;&nbsp;\r\n        										            <%= link_to \'\', \'#\', :title=>\'Edit Account\', :class=>\'splashy-contact_blue_edit\', :onclick=>\"javascript:confirm_edit(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>\r\n        										        </td>\r\n        										    </tr>\r\n        										<%\r\n        										    no += 1\r\n        										    end\r\n        										%>\r\n        										</tbody>\r\n        									</table>\r\n										</div>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n<%\r\n    end\r\n%>\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											User Profile\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :profile, :class=>\'\', :url=>\"index\" ,:method=>\'POST\' do |f| %>\r\n											<%\r\n											    cur_user = @ehr_models[:user].where(:login=>@current_user.to_s).first\r\n											    cur_prov = @models[:provider].where(:login=>@current_user.to_s).first\r\n											%>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your information</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\', :value=>@current_user, :disabled=>\'disabled\' %>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\', :value=>cur_user[:name] if cur_user %> \r\n        													<span class=\"help-block\">your account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<hr/>\r\n<%\r\n    main_hospital = cur_prov[:main_hospital] if cur_prov\r\n    part_time_hospital = cur_prov[:part_time_hospital] if cur_prov\r\n    part_time_hospital = [] unless part_time_hospital\r\n\r\n    m_hosp = get_model[:hospital]\r\n    \r\n    map_hospital = {}\r\n    map_hospital[\"\"] = \"Please select hospital\"\r\n    \r\n    map_region = {\r\n        \'1\'=>\'กรุงเทพ\',\r\n        \'2\'=>\'ปริมณฑล\',\r\n        \'3\'=>\'ภาคกลาง\',\r\n        \'4\'=>\'ภาคเหนือ\',\r\n        \'5\'=>\'ภาคใต้\',\r\n        \'6\'=>\'ภาคอิสาน\',\r\n        \'7\'=>\'ภาคตะวันออก\',\r\n        \'8\'=>\'ภาคตะวันตก\'}\r\n    map_reg_hosp = {}\r\n    \r\n    sel_txt = \"\"\r\n    a_hosp = m_hosp.all\r\n    for i in a_hosp do\r\n        map_hospital[i.id.to_s] = i[:hospital_name_thai]\r\n        if !map_reg_hosp.has_key? i[:region]\r\n            map_reg_hosp[i[:region]] = {}\r\n        end\r\n        # if i.id.to_s == main_hospital\r\n        #     next\r\n        # end\r\n        map_reg_hosp[i[:region]][i.id.to_s] = i[:hospital_name_thai]\r\n    end \r\n%>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Main Hospital</label>\r\n        												<div class=\"controls\">\r\n        												\r\n        												    <%# f.select :main_hospital, map_hospital, :selected => a_hosp.last[:hospital_name_thai], :class=>\'span10\' %>\r\n        												    <select name=\"profile[main_hospital]\" id=\"profile_main_hospital\" class=\"span10\">\r\n<%\r\n    map_hospital.each do |k,v|\r\n        sel = \'\'\r\n        if main_hospital == k\r\n            sel = \' selected=\"selected\"\'\r\n        end\r\n%>\r\n                                                                <option value=\"<%=k%>\"<%= sel %>><%=v%></option>\r\n<% \r\n    end\r\n%>\r\n        												    </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Part Time Hospital</label>\r\n        												<div class=\"controls\">\r\n        												    <%# f.select :main_hospital, map_hospital, :selected => a_hosp.last[:hospital_name_thai], :class=>\'span10\' %>\r\n        												    <select name=\"profile[part_time_hospital][]\" multiple=\"multiple\" class=\"multiselect\" >\r\n<%\r\n    opt_txt = \"\"\r\n    sel_txt = \"\"\r\n    list_part_time = part_time_hospital.split(\'|\')\r\n    # list_part_time = [\'55c5ba20790f9b1672000004\',\'55c4e3ed790f9b223e000002\']\r\n    map_reg_hosp.each do |k,v|\r\n        opt_txt += \"<optgroup label=\'\\\\#{map_region[k]}\'>\"\r\n        v.each do |x,y|\r\n            if list_part_time.include? x\r\n                # sel_txt += \"<li class=\'ms-elem-selected\' ms-value=\'\\\\#{x}\'>\\\\#{y}</li>\"\r\n                opt_txt += \"<option value=\'\\\\#{x}\' selected>\\\\#{y}</option>\"\r\n            else\r\n                opt_txt += \"<option value=\'\\\\#{x}\'>\\\\#{y}</option>\"\r\n            end\r\n        end\r\n        opt_txt += \"</optgroup>\"\r\n    end\r\n%>\r\n                                                                <%= opt_txt.html_safe %>\r\n        												    </select>\r\n        												    <a id=\"select_all\" href=\"javascript:void(0)\">Select All</a> / <a id=\"deselect_all\" href=\"javascript:void(0)\">Deselect All</a>\r\n        												</div>\r\n        											</div>\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Password\" class=\"span10\" name=\"[profile]cur_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your information</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Password\" class=\"span10\" name=\"[profile]new_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Password\" class=\"span10\" name=\"[profile]con_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n										</div>\r\n									</div>\r\n								</div>\r\n							</div>\r\n                        \r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<br/>\r\n\r\n<script>\r\n    refresh();\r\n    \r\n    function confirm_delete(uid, pid) {\r\n        if (confirm(\'Are you sure?\') == true) {\r\n<%\r\n            destroy_url = \'destroy?id=\'\r\n%>\r\n            \r\n            url = \"destroy?uid=\" + uid + \"&pid=\" + pid;\r\n            window.location = url;\r\n        }\r\n    }\r\n    \r\n    function confirm_edit(uid, pid) {\r\n        // if (alert(\'Are you sure?\') == true) {\r\n            \r\n        // }\r\n        \r\n    }\r\n</script>\r\n            <!-- styled form elements -->\r\n            <script src=\"/gebo/lib/uniform/jquery.uniform.min.js\"></script>\r\n            <!-- multiselect -->\r\n            <script src=\"/gebo/lib/multiselect/js/jquery.multi-select.min.js\"></script>\r\n            <!-- enhanced select (chosen) -->\r\n            <script src=\"/gebo/lib/chosen/chosen.jquery.min.js\"></script>\r\n<script>\r\n    $(document).ready(function() {\r\n		//* 2col multiselect\r\n		multiz.init();\r\n		\r\n	});\r\n    //* multiselect\r\n	multiz = {\r\n		init: function(){\r\n			\r\n			$(\'.multiselect\').multiSelect({\r\n				selectableHeader	: \'<h4>Selectable Hospitals</h4>\',\r\n				selectedHeader		: \'<h4>Selected Hospitals</h4>\'\r\n			});\r\n			$(\'.ms-elem-selectable\').hide();\r\n			$(\'.ms-elem-selectable\').click(function(){\r\n			   console.log($(this).attr(\'ms-value\')); \r\n			});\r\n// 			$(\'.ms-selection\').find(\'ul.ms-list\').html(\'<li class=\"ms-elem-selected\" ms-value=\"55c4e3ed790f9b223e000002\">โรงพยาบาลตำรวจ</li><li class=\"ms-elem-selected\" ms-value=\"55c5ba20790f9b1672000004\">โรงพยาบาลจุฬาลงกรณ์</li>\');\r\n// 			$(\'#ms-optgroup .ms-selectable, #ms-outsideCountries .ms-selectable\').find(\'li.ms-elem-selectable\').hide();\r\n			$(\'.ms-optgroup-label\').click(function(){\r\n				if ($(this).hasClass(\'ms-collapse\')){\r\n					$(this).nextAll(\'li\').hide();\r\n					$(this).removeClass(\'ms-collapse\'); \r\n				} else {\r\n					$(this).nextAll(\'li:not(.ms-selected)\').show();\r\n					$(this).addClass(\'ms-collapse\');\r\n				}\r\n			});\r\n		  \r\n// 			$(\'#searchable-form\').multiSelect({\r\n// 				selectableHeader : \'<input type=\"text\" id=\"multi_search\" autocomplete=\"off\" placeholder=\"search\" />\',\r\n// 				selectedHeader	 : \'<a href=\"javascript:void(0)\" id=\"sForm_deselect\" class=\"btn\">Deselect All</a>\'\r\n// 			});\r\n		\r\n// 			$(\'input#multi_search\').quicksearch(\'#ms-searchable-form .ms-selectable li\');\r\n// 			$(\'#searchable-form\').multiSelect();\r\n			\r\n			$(\'#select_all\').on(\'click\', function(){\r\n				$(\'.multiselect\').multiSelect(\'select_all\');\r\n				return false;\r\n			});\r\n			\r\n			$(\'#deselect_all\').on(\'click\', function(){\r\n				$(\'.multiselect\').multiSelect(\'deselect_all\');\r\n				return false;\r\n			});\r\n			\r\n			$(\'#sForm_deselect\').on(\'click\', function(){\r\n				$(\'#searchable-form\').multiSelect(\'deselect_all\');\r\n				return false;\r\n			});\r\n\r\n		}\r\n	};\r\n</script>',NULL,NULL,NULL,'2015-05-09 03:02:21','2015-05-09 03:02:21','index_bk',''),(1485,'show',599,2,'<%\r\n    show_color = false\r\n%>\r\n<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    # map procedure\r\n    models = get_model\r\n    m_procedure = models[:procedure].all\r\n    map_proc = {}\r\n    for m in m_procedure do\r\n        map_proc[m.id.to_s] = {:name=>m[:name], :code=>m[:code]}\r\n    end\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient_module = ehr_models[:patient_module]\r\n    \r\n    pm = m_patient_module.find(params[:id])\r\n    m_ap = m_patient_module.where(:id=>pm[:parent_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\").first\r\n    ap = models[:appointment].find(m_ap[:module_id])\r\n    \r\n    if params[:b] == \'1\' \r\n        s = \'0\'\r\n        if params[:s] == \'1\'\r\n            s = \'2\'\r\n        elsif params[:s] == \'2\'\r\n            s = \'1\'\r\n        end\r\n        # ap.update_attributes :bilateral=>\'1\', :side=>params[:s]\r\n        # create_next = \"create?patient_id=\\\\#{params[:patient_id]}&record_name=\\\\#{params[:record_name]}&parent_id=\\\\#{params[:parent_id]}&return=\\\\#{params[:return]}\"\r\n        # ../Home/appointment_create?patient_id=5576b0ab790f9b4002000003&data[date]=2015-06-10&data[provider]=5576b180790f9b4002000012&data[procedure]=5576b0e4790f9b4002000005&return=%2Ftaig%2Fthkr%2FHome%2Fpatient_record%3Fid%3D5576b0ab790f9b4002000003&commit=Add+New\r\n        create_next = \"../Home/appointment_create?patient_id=\\\\#{params[:patient_id]}&s=\\\\#{s}&act=z&data[provider]=\\\\#{ap[:provider]}&data[procedure]=\\\\#{ap[:procedure]}&data[date]=\\\\#{ap[:date]}&return=\\\\#{params[:return]}\"\r\n        \r\n        if params[:act] == \'z\'\r\n            params[:b] = nil\r\n        end\r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<!--<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>-->\r\n<h3><strong><%= map_proc[ap[:procedure].to_s][:name] %></strong></h3>\r\n<div class=\"pull-right\">\r\n<!--<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print_pgh?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>-->\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<%# pm.inspect %>\r\n<!--<div style=\"border:0px solid;background:#eeeeee;padding:0px\">-->\r\n<!--<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">-->\r\n<div style=\"border:0px solid;<%= \"background-color:\\\\#{this.color_name};\" if show_color %>\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n\r\n\r\n<%= this.display.html_safe %>\r\n<div style=\"padding:20px\">\r\n<% if params[:b] %>\r\n    <%= link_to \'Next\', create_next, :class=>\'btn btn-button btn-success\' %> | \r\n<% else %>\r\n    <%= link_to \'Finish\', return_url, :class=>\'btn btn-button btn-success\' %> | \r\n<% end %>\r\n    <%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> |\r\n    <%= link_to \'Print\'.html_safe, \"print_pgh?id=\\\\#{params[:id]}&return=\\\\#{return_url}\", :target=>\'_blank\', :class=>bt_class %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n',NULL,NULL,NULL,'2015-05-09 03:19:06','2015-05-09 03:19:06','show',''),(1486,'init',689,4,'<%\r\n    @models = get_model\r\n        \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @ehr_models = ehr.get_model\r\n%>',NULL,NULL,NULL,'2015-05-09 03:21:56','2015-05-09 03:21:56','init',''),(1487,'test',689,3,'<%= render :inline=>this.init %>\r\n<%\r\n    tmp = {}\r\n    tmp[:user_id] = @current_user.id\r\n    tmp[:current_user] = @current_user.inspect\r\n    tmp[:current_role] = @current_role.inspect\r\n    tmp[:all_provider] = @models[:provider].all\r\n    tmp[:all_user] = @ehr_models[:user].all\r\n    usr = @ehr_models[:user].all.collect do |i|\r\n        role = @ehr_models[:role].find(i.role)\r\n        role_name = \'undefined\'\r\n        if role\r\n            role_name = role[:name]\r\n        end\r\n        provider = @models[:provider].where(:login=>i.login).first\r\n        \r\n        if provider\r\n            {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :i=>i}\r\n        end\r\n    end\r\n    \r\n    tmp[:user_map] = usr.compact\r\n    tmp[:user_chaiwat] = m_user = @ehr_models[:user].where(:login=>\'chaiwat\').first\r\n%>\r\n<%= tmp.to_json.html_safe %>',NULL,NULL,NULL,'2015-05-09 04:05:00','2015-05-09 04:05:00','test','*'),(1488,'account',689,3,'<%= render :inline=>this.init %>\r\n\r\n<%\r\n        usr = @ehr_models[:user].all.collect do |i|\r\n            role = @ehr_models[:role].find(i.role)\r\n            role_name = \'undefined\'\r\n            if role\r\n                role_name = role[:name]\r\n            end\r\n            provider = @models[:provider].where(:login=>i.login).first\r\n            \r\n            if provider\r\n                {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :i=>i}\r\n            end\r\n        end\r\n%>\r\n                                        <div id=\"account\">\r\n                                            <%= params.inspect %>\r\n											<table class=\"table\">\r\n        										<thead>\r\n        											<tr>\r\n        												<th>No.</th>\r\n        												<th>Login Name</th>\r\n        												<th>Name</th>\r\n        												<th>Role</th>\r\n        												<th>Actions</th>\r\n        											</tr>\r\n        										</thead>\r\n        										<tbody>\r\n        										<% \r\n        										    no = 1\r\n        										    for i in usr.compact do\r\n        										\r\n        										%>\r\n        										    <tr>\r\n        										        <td><%= no %>.</td>\r\n        										        <td><%= i[:login] %></td>\r\n        										        <td><%= i[:provider_name] %></td>\r\n        										        <td><%= i[:role_name] %></td>\r\n        										        <td>x | e | s</td>\r\n        										    </tr>\r\n        										<%\r\n        										    no += 1\r\n        										    end\r\n        										%>\r\n        										</tbody>\r\n        									</table>\r\n										</div>\r\n										\r\n								',NULL,NULL,NULL,'2015-05-09 09:52:40','2015-05-09 09:52:40','account',''),(1489,'destroy',689,3,'<%= render :inline=>this.init %>\r\n<%\r\n    if params[:uid] and params[:pid]\r\n        @ehr_models[:user].find(params[:uid]).destroy\r\n        @models[:provider].find(params[:pid]).destroy\r\n    end\r\n%>\r\n<script>\r\n    window.location = \"index\";\r\n</script>',NULL,NULL,NULL,'2015-05-09 14:55:37','2015-05-09 14:55:37','destroy',''),(1490,'index_old',666,2,'<%\r\nmodule_name = @current_project.name\r\nif params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\nend\r\nif session[module_name]\r\n	params[:date] = session[module_name][:date]\r\nend\r\nunless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\nend\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    provider = models[:provider].where(:login=>@current_user.login).first\r\n    if provider\r\n       s_provider = provider.id.to_s\r\n    end\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       My Patients\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n    \r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\'../Home/index\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n            \r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n                \r\n            </div>\r\n            </span>\r\n            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            \r\n            \r\n            <div class=\"field-input\">\r\n                 <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                 \r\n                 <%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>\r\n            </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            <div class=\"field-input\">\r\n            <%\r\n            # Home/patient_record?id=5533e537790f9b01c2000006\r\n                add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n                if s_provider \r\n                    # add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                    add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                end\r\n                \r\n            %>\r\n              \r\n                 <%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>\r\n            </div>\r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        \r\n        </div>\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%# params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n    \r\n    if !search_patient and params[:select].nil?\r\n\r\n    	patients = patient_model.all  \r\n	    maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n    	aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n    %>\r\n    <!--ALL -->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n    	patients = patient_model.where(criteria).limit(20).all  \r\n	    maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n    	aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT-->\r\n    <%\r\n    elsif params[:date]\r\n    \r\n	    conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n    		conds.merge! :provider=>s_provider \r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n    \r\n    	aps = ap_model.all(conds)\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n\r\n    %>\r\n    <!--DATE-->\r\n    <%\r\n    end # end if\r\n \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n		 patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         # zamachita comment and change link to patient_record\r\n        #  hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n        hn = link_to(patient.hn, \"patient_record?id=\\\\#{m[:patient_id]}&aid=\\\\#{m.id}\")\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n        #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n        #  :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n        #  :visit_type=>visit_type\r\n        #  }\r\n        c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n        :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,\r\n        # :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{m[:patient_id]}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n        :visit_type=>visit_type\r\n        }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{m[:patient_id]}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{m[:patient_id]}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    # table_model = %w{date hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    table_model = %w{date hn patient provider }.collect{|i| i.to_sym}\r\n    \r\n    \r\n    # labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',\r\n    # :status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\', :note=>\'Note\',:visit_type=>\'Group\' }\r\n    labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:Provider=>\'Appointed Doctor\', :pending_ctrl=>\'Appointed ctrl\', :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n    %>\r\n        \r\n        \r\n        \r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                 <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    out[0] = count.to_s+\".\"\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n\r\n        </div>\r\n        \r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n\r\n<div class=\"alert \">\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2015-05-09 18:04:40','2015-05-09 18:04:40','index_old',''),(1491,'pm_search',666,3,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#provider\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    pid = \'554e49bd790f9b797100000c\'\r\n    if params[:id]\r\n        pid = params[:id]\r\n    end\r\n    \r\n    models = get_model\r\n    m_procedure = models[:procedure].all\r\n    list_proc = []\r\n    map_proc = {}\r\n    for m in m_procedure do\r\n        map_proc[m.id] = m[:name]\r\n        list_proc.push(m[:code])\r\n    end\r\n    \r\n    m_pm_provider = module_model.where(:module_name=>mname, :module_id=>pid).all\r\n    result = []\r\n    for m in m_pm_provider do\r\n        m_ap = module_model.where(:patient_id=>m[:patient_id], :module_name=>\"\\\\#{@current_project.name}#appointment\").all\r\n        m[:tmp] = []\r\n        for n in m_ap do\r\n            ap = models[:appointment].find(n[:module_id])\r\n            if ap\r\n                m[:tmp].push(map_proc[ap[:procedure]])\r\n            end\r\n            result.push(m)\r\n        end\r\n    end\r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    rs = {}\r\n    # rs[:time] = Time.now.strftime(\"%H:%M\")\r\n    # rs[:all_provider] = provider_model.all\r\n    # rs[:all_procedure] = m_procedure\r\n    # rs[:map_procedure] = map_proc\r\n    rs[:result] = result\r\n    \r\n    # patient_list = m_pm_provider.collect{|i| i.patient_id}\r\n    # rs[:patient_list] = patient_list\r\n    \r\n%>\r\n<%= rs.to_json.html_safe %>',NULL,NULL,NULL,'2015-05-09 18:32:23','2015-05-09 18:32:23','pm_search',''),(1492,'print_monthly_report_partial',522,3,'<%= render :inline=>this.init %>\r\n <% if params[:report][:date]\r\n \r\n \r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][:date]\r\n    select_date = Date.to_mongo(select_date)\r\n    date = select_date\r\n    start_date = select_date.beginning_of_month()\r\n    stop_date = select_date.end_of_month()\r\n    \r\n    \r\n\r\n    pname = \"\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n%>    \r\n    \r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n    \r\n<body>\r\n        \r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo.png\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงผู้ป่วยเข้ารับการส่องกล้องห้องส่องกล้อง Surgical endoscopy \r\n<span style=\"float:right\">ประจำเดือน \r\n<%= date.strftime(\"%B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n<%\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1 }}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1 }}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                    end\r\n                end\r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        end\r\n    \r\n    end\r\n \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n<style>\r\n    td{\r\n        text-align:center;\r\n    }\r\n    td.Elective{\r\n        background:#deffde;\r\n\r\n            padding:5px 10px 5px 10px;\r\n    }\r\n    td.Extratime{\r\n        background:#dedeff;\r\n\r\n            padding:5px 10px 5px 10px;\r\n    }\r\n    td.Emergency{\r\n        background:#ffdede;\r\n     \r\n            padding:5px 10px 5px 10px;\r\n    }\r\n    td.total{\r\n        background:#dedede;\r\n\r\n            padding:5px 10px 5px 10px;\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.date{\r\n        padding:5px 10px 5px 10px;\r\n        \r\n        \r\n        \r\n    }\r\n</style>\r\n<div style=\"border:0px solid;text-align:center;padding-left:100px\">\r\n<table border=\"1\" style=\"margin-left:auto margin-right:auto;border: 1px solid #6a6a6a;border-collapse:collapse\">\r\n<%\r\n   m = nil\r\n   \r\n       tsum = {\'Elective\'=>[0,0,0,0],\'Extratime\'=>[0,0,0,0], \'Emergency\'=>[0,0,0,0], \'Total\'=>[0,0,0,0]}\r\n\r\n\r\n   for i in dates.keys.sort\r\n\r\n%>\r\n<%\r\n   km = i.split(\"-\")[0..1].join(\"-\")\r\n   if km!=m\r\n    m = km\r\n%>\r\n<tr style=\"background:#ffffde\"><td>&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n    \r\n</tr>\r\n<tr style=\"background:#dedeff\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n\r\n\r\n</tr>\r\n\r\n<% end %>\r\n<tr>\r\n    <td class=\"date\"><%=i.split(\'-\').reverse.join(\'-\')%></td>\r\n    <% \r\n    \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Extratime Emergency} \r\n        \r\n        k = [0,0,0]\r\n        k = dates[i][j] if dates[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        \r\n        tsum[j][0] += k[0]\r\n        tsum[j][1] += k[1]\r\n        tsum[j][2] += k[2]\r\n        tsum[j][3] += s\r\n        \r\n        \r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n\r\n</tr> \r\n<% end %>\r\n<tr>\r\n    <td colspan=\"17\">&nbsp;</td>\r\n</tr>\r\n<tr><td>&nbsp;</td>\r\n<%\r\n\r\n   t = [0,0,0,0]\r\n\r\n  for j in %w{Elective Extratime Emergency} \r\n    \r\n  4.times do |i|    \r\n  t[i]+=tsum[j][i]\r\n%>\r\n<td><%=tsum[j][i]%></td>\r\n<% end %> \r\n<% end %> \r\n\r\n<td><%=t[0]%></td><td><%=t[1]%></td><td><%=t[2]%></td><td><%=t[3]%></td>\r\n\r\n</tr>\r\n</table>\r\n</div>\r\n\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-09 18:41:09','2015-05-09 18:41:09','print_monthly_report_partial',''),(1493,'print_monthly_report',522,2,'<%= render :inline=>this.init %>\r\n<%= render :inline=>this.menu %>\r\n<h3>Monthly Report</h3>\r\n\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    params_date = select_date\r\n    select_date = Date.to_mongo(select_date)\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n<%= f.date_select :date, :default=>select_date ,:discard_day=>true%>\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    select_date = Date.to_mongo(select_date)\r\n    start_date = select_date.beginning_of_month()\r\n    stop_date = select_date.end_of_month()\r\n    \r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1 }}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1 }}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                    end\r\n                end\r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        end\r\n    \r\n    end\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n<style>\r\n    td{\r\n        text-align:center;\r\n    }\r\n    td.Elective{\r\n        background:#deffde;\r\n        text-align:right;\r\n            padding:5px 10px 5px 10px;\r\n    }\r\n    td.Extratime{\r\n        background:#dedeff;\r\n        text-align:right;\r\n            padding:5px 10px 5px 10px;\r\n    }\r\n    td.Emergency{\r\n        background:#ffdede;\r\n        text-align:right;\r\n            padding:5px 10px 5px 10px;\r\n    }\r\n    td.total{\r\n        background:#dedede;\r\n        text-align:right; \r\n            padding:5px 10px 5px 10px;\r\n    }\r\n    td.date{\r\n        padding:5px 10px 5px 10px;\r\n        \r\n        \r\n        \r\n    }\r\n</style>\r\n<table border=\"1\">\r\n<%\r\n   m = nil\r\n   for i in dates.keys.sort\r\n\r\n%>\r\n<%\r\n   km = i.split(\"-\")[0..1].join(\"-\")\r\n   if km!=m\r\n    m = km\r\n%>\r\n<tr style=\"background:#ffffde\"><td>&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\">Elective</td>\r\n    <td colspan=\"4\" align=\"center\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\">Total</td>\r\n    \r\n</tr>\r\n<tr style=\"background:#dedeff\"><td>Date</td>\r\n    <td>C</td><td>G</td><td>C+G</td><td>Sum</td>\r\n    <td>C</td><td>G</td><td>C+G</td><td>Sum</td>\r\n    <td>C</td><td>G</td><td>C+G</td><td>Sum</td>\r\n    <td>C</td><td>G</td><td>C+G</td><td>Sum</td>\r\n\r\n\r\n</tr>\r\n\r\n<% end %>\r\n<tr>\r\n    <td class=\"date\"><%=i.split(\'-\').reverse.join(\'-\')%></td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Extratime Emergency} \r\n        \r\n        k = [0,0,0]\r\n        k = dates[i][j] if dates[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n\r\n</tr> \r\n<% end %>\r\n</table>\r\n<br/>\r\n<%= link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-09 18:41:32','2015-05-09 18:41:32','print_monthly_report',''),(1494,'appointment_clean',675,2,'<%= render :inline=>this.init %>\r\n<%\r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1}}).to_a\r\n    m_all_app = bmap all_app, \'_id\'\r\n\r\n    out[:B_all_appointments] =all_app.size\r\n\r\n    # all pm appointment of those appointmets\r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    out[:B_all_appointments_ass] =all_pm_app.size\r\n     \r\n    app_delete = []\r\n    pm_delete = []\r\n    \r\n    for i in all_app\r\n    \r\n        if m_all_pm_app[i[\'_id\']]\r\n            if  m_all_pm_app[i[\'_id\']].size>1\r\n            %><%= i[\'date\'] %>\r\n            <%\r\n            id = nil\r\n            for a in  m_all_pm_app[i[\'_id\']]\r\n            \r\n            unless id \r\n                id = i[\'_id\']\r\n            else\r\n                 pm_delete << a[\'_id\']\r\n            end\r\n            %>\r\n            <li><%= a[\'_id\']  %> | <%= a[\'module_id\']  %></li>\r\n            <%\r\n            end\r\n             %><hr/>\r\n            <%\r\n            end\r\n           \r\n        else\r\n            app_delete << i[\'_id\']\r\n        end\r\n    end\r\n     \r\n%>\r\nApp : <%= all_app.size %><br/>\r\nPM app : <%= all_pm_app.size %><br/>\r\nDelete app : <%= app_delete.size %><br/>\r\nDete pm : <%= pm_delete.size %>\r\n<pre>\r\n    <% for i in app_delete %>\r\n    <%=i.inspect %>\r\n    <% end %>\r\n</pre>    \r\n    \r\n<% if params[:commit] %>\r\n\r\n<% \r\n\r\nfor i in app_delete\r\n    \r\n@models[:appointment].collection.remove(\'_id\'=>i)\r\n        \r\n%>\r\n<%= i %> ... deleted<br/>\r\n<% end %>\r\n<% \r\n\r\nfor i in pm_delete\r\n    \r\n@m_patient_module.collection.remove(\'_id\'=>i)\r\n        \r\n%>\r\n<%= i %> ... deleted<br/>\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n<%= link_to \'Back\',\'index\' %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-09 18:42:15','2015-05-09 18:42:15','appointment_clean',''),(1495,'associate_colono',675,2,'<%=view :fitscreen %>\r\n<h1>Colonoscopy Recovery System</h1>\r\n<%\r\n  mname = \'colonoscopy\'\r\n  mname = params[:model] if params[:model]\r\n  mname = mname.to_sym\r\n pms = []\r\n ids = []\r\n unlink = []\r\n \r\n \r\n \r\n%>\r\n<%= form_for :query ,:url=>\'index_post\' do |f| %>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    mpm = model[:patient_module]\r\n    \r\n    models = get_model\r\n    \r\n    mcolono = models[mname]\r\n    matt = models[:attachment] \r\n    \r\n    if params[:date]\r\n        \r\n    %>\r\n    <%= hidden_field_tag \'date\', params[:date] %>\r\n    <%\r\n    date = Date.to_mongo(Time.zone.parse(params[:date].split(\'/\').reverse.join(\"-\")))\r\n    # date =Time.zone.parse(params[:date])\r\n    ids = mcolono.collection.find({:created_at=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}},{:fields=>{\'_id\'=>1}}).to_a.collect{|i| i[\'_id\']}\r\n    \r\n    \r\n    else\r\n    \r\n    ids = mcolono.collection.find({},{:fields=>{\'_id\'=>1}}).to_a.collect{|i| i[\'_id\']}\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n    pms = mpm.collection.find(:module_id=>{\'$in\'=>ids}).to_a\r\n    map = {}\r\n   \r\n    for i in pms\r\n        map[i[\"module_id\"]] = i\r\n    end\r\n    for i in ids\r\nif map[i]\r\n%><%# map[i] %>\r\n<% else \r\n\r\n unlink << i \r\n \r\n \r\n \r\n\r\n%>\r\n<% end %>\r\n<% end %>\r\n<% \r\n\r\nmonths = {}\r\ndate_map = {}\r\n\r\ncols =  mcolono.collection.find(\'_id\'=>{\'$in\'=>unlink}).to_a\r\n \r\nfor i in cols  \r\n\r\nk = i[\'created_at\'].strftime(\'%d/%m/%Y\')\r\nm = i[\'created_at\'].strftime(\'%m/%Y\')\r\nmonths[m] = [] unless months[m] \r\nmonths[m] << k unless date_map[k] \r\ndate_map[k] = [] unless date_map[k]\r\ndate_map[k] << i\r\n\r\nend \r\n\r\n%>\r\n<% months.each_pair do |k,v| %>\r\n<%=k%>\r\n<%= v.collect{|j| link_to(j,\"index?date=\\\\#{j}\") }.join(\" | \") .html_safe %>\r\n<hr/>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n \r\n if params[:date]\r\n    cols = date_map[params[:date]] \r\n%>\r\n\r\n<%\r\n    mx = {:colonoscopy=>\'Colonoscopy\',:gastroscopy=>\'Gastroscopy\'}\r\n\r\n    mx.each_pair do |mx_name,mx_label|\r\n%>\r\n\r\n\r\n<h1><%=mx_label%></h1>\r\n<%\r\n\r\n  providers = {}\r\n  models[:provider].to_a.each do |i|\r\n     \r\n     providers[i.id] = i.name \r\n      \r\n  end\r\n  \r\n  mc = models[mx_name]\r\n  objs = mc.collection.find(:created_at=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}).to_a\r\n  ids = objs.collect{|i| i[\'_id\']}\r\n  pms = mpm.collection.find(:module_id=>{\'$in\'=>ids}).to_a\r\n  map = {}\r\n  unlink = []\r\n  for i in pms\r\n        map[i[\"module_id\"]] = i\r\n  end\r\n\r\n  for i in objs\r\n    unless map[i[\'_id\']]\r\n     unlink << i \r\n    end\r\n  end\r\n  \r\n%>\r\n\r\n<table border=\"1\">\r\n<%\r\n \r\nunlink.each_with_index do |i,index| \r\n    \r\n imgs = matt.find(i[\'image\']).to_a\r\n if imgs.size>=3\r\n imgs = imgs[-3..-1] \r\n end\r\n id = i[\'_id\']\r\n%>\r\n<tr>\r\n<td><%=index+1%>. <%=i[\'created_at\']%></td>\r\n<td><%=i[\'diagnosis_group\']%></td>\r\n<td><%=providers[i[\'endoscopist_1\']]%></td>\r\n<td id=\"\">\r\n\r\n    <%=text_field_tag \"\\\\#{mx_name}[\\\\#{id}]\",\"\",:onchange=>\'javascript:search_hn(this)\',:style=>\"width:120px\" %>\r\n    <%=hidden_field_tag \"\\\\#{mx_name}_ass[\\\\#{id}]\",\"\", :id=>\"v\\\\#{id}\" %>\r\n    <%=hidden_field_tag \"\\\\#{mx_name}_provider[\\\\#{id}]\",i[\'endoscopist_1\'] %>\r\n    \r\n</td>\r\n\r\n</tr>\r\n<tr>\r\n<% if  imgs.size>0 and params[:date] %>\r\n<% imgs.to_a.each do |j| %>\r\n<td>\r\n<a href=\"<%=j.path%>?<%=j.id%>\" class=\"highslide\" rel=\"highslide\" onclick=\"return hs.expand(this)\"><center><img src=\"<%=j.path%>?<%=j.id%>&amp;thumb=1\" name=\'img\' id=\"<%=j.id%>\" class=\"eachpicimg\" border=0   height=90px align=absmiddle ></center>\r\n</a>\r\n</td>\r\n<% end %>\r\n<% else %>\r\n<td colspan=\"3\">&nbsp;</td>\r\n<% end %>\r\n<td id=\"<%=id%>\" class=\"alert-info\">.</td>\r\n\r\n</tr>\r\n<% if imgs.size>0 %>\r\n<tr>\r\n    <td colspan=\"4\" style=\"height:200px;background-image:url(\'<%= imgs[0].path%>\')\">\r\n    </td>\r\n</tr>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n<tr>\r\n    <td colspan=\"4\">&nbsp;</td>\r\n</tr>\r\n\r\n\r\n\r\n<% end %>\r\n</table>\r\n\r\n\r\n<hr/>\r\n<% end %>\r\n<br/>\r\n<%= f.submit \'Check Association\', :class=>\'btn btn-success\' %>\r\n<br/>\r\n<% end %>\r\n\r\n<%=ids.size%> | <%=pms.size%>\r\n\r\n<% end %>\r\n\r\n<%= link_to \'See All\' ,\'associate_colono\' %>\r\n\r\n<script>\r\n    \r\n    function search_hn(t){\r\n        \r\n        var v = $(t)\r\n        id = v.attr(\'id\')\r\n        t = id.split(\'_\')\r\n        vid = t[1];\r\n        var value = v.val()\r\n      $(\'#\'+vid).html(\'loading..\');\r\n     \r\n     $.ajax({\r\n            type: \'POST\',\r\n            url: \"partial\",\r\n            data: { q: value,id: vid},\r\n            success: function(html){\r\n                $(\'#\'+vid).html(html);\r\n            }\r\n         });\r\n         \r\n         \r\n    \r\n        \r\n        // alert(\'search \'+v)\r\n    }\r\n    \r\n    \r\n    $(document).ready(function() {\r\n    \r\n    });\r\n\r\n    \r\n</script>\r\n\r\n| \r\n<%= link_to \'Back\',\'index\' %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-09 18:42:28','2015-05-09 18:42:28','associate_colono',''),(1496,'associate_intra_post',675,2,'<%= render :inline=>this.init %>\r\n<%= form_for :search, :url=>\'associate_intra_post\' do |f| %>\r\n\r\n<%\r\n    month = Time.now\r\n    year = Time.now\r\n\r\n    if params[:date]\r\n    \r\n    month = params[:date][:month].to_i if params[:date][:month]\r\n    year = params[:date][:year].to_i if params[:date][:year]\r\n    end\r\n    \r\n%>\r\n\r\n<%= select_month month %> <%= select_year(year, start_year: 2014, end_year: 2015) %>\r\n\r\n<%= f.submit :submit%>\r\n<% end %>\r\n\r\n\r\n<% if request.post?  %>\r\n\r\n<%= form_for :recovery, :url=>\'associate_intra_post\' do |f| %>\r\n<%= text_field_tag \'date[month]\', params[:date][:month] %>\r\n<%= text_field_tag \'date[year]\', params[:date][:year] %>\r\n<%= params.inspect %>\r\n<%\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    \r\n    \r\n    if params[:recovery] and params[:recovery][:perform_commit]==\'1\'\r\n    \r\n    params[:cases].keys.each do |k|\r\n        v = params[:cases][k]\r\n        t = k.split(\'-\')\r\n        \r\n        intra = @models[:intra_scope].find(t[0])\r\n        post = @models[:post_scope].find(t[1])\r\n        mapp = @m_patient_module.find(v)\r\n        \r\n        if intra and post and mapp\r\n            \r\n             @m_patient_module.create :module_name=>\"\\\\#{pname}intra_scope\",:module_id=>intra.id,:patient_id=>mapp.patient_id,:ref_number=>\'00000\',:parent_id=>mapp.id,:date=>mapp.date,:time=>mapp.time\r\n             @m_patient_module.create :module_name=>\"\\\\#{pname}post_scope\",:module_id=>post.id,:patient_id=>mapp.patient_id,:ref_number=>\'00000\',:parent_id=>mapp.id,:date=>mapp.date,:time=>mapp.time\r\n            \r\n            \r\n        end\r\n        \r\n    %>\r\n    <li> <%=intra%> | <%= post %> | <%= mapp %> | OK </li>\r\n    \r\n    <%\r\n    \r\n    end\r\n\r\n    end\r\n\r\n    def query_unlink m, cond= {}\r\n        model =  @models[m]\r\n        if m == :intra_scope\r\n            ids = model.collection.find(cond,{:fields=>{\'_id\'=>1,\'created_at\'=>1,\'procedure_complete\'=>1,\'time_out_room\'=>1,\'endosocpist1\'=>1}}).to_a\r\n        else\r\n            ids = model.collection.find(cond,{:fields=>{\'_id\'=>1,\'created_at\'=>1}}).to_a\r\n        end\r\n        \r\n        \r\n        mids = @m_patient_module.collection.find(:module_id=>{\'$in\'=>  ids.collect{|i| i[\'_id\']} }).to_a\r\n        unlink = []\r\n        map = {}\r\n        for i in mids\r\n            map[i[\"module_id\"]] = i\r\n        end\r\n        ids.collect!{|i| i unless map[i[\'_id\']]}.compact!\r\n        return ids \r\n    end  \r\n  \r\n    \r\n    cond = {\"created_at.month\"=>params[:date][:month], \"created_at.year\"=>params[:date][:year]}\r\n\r\n    date = Date.to_mongo(Time.zone.parse(\"\\\\#{params[:date][:year].to_i}-\\\\#{params[:date][:month].to_i}-15\"))\r\n    start = date.beginning_of_month\r\n    stop = date.end_of_month\r\n    \r\n    cond = {\'created_at\'=>{\'$gte\'=>start,\'$lte\'=>stop}  } \r\n    ids_1 = query_unlink :intra_scope, cond\r\n    ids_2 = query_unlink :post_scope, cond\r\n    \r\n    date_map = {}\r\n    \r\n    stop = nil\r\n    start = nil\r\n    \r\n    for i in ids_1\r\n        d = i[\'created_at\'].strftime(\"%Y-%m-%d\")\r\n        # stop = d if stop == nil or d>stop\r\n        # start = d if start == nil or d<start\r\n        date_map[d] = [] unless date_map[d]\r\n        date_map[d] << [:intra_scope,i[\'_id\'],i[\'created_at\'],i[\'procedure_complete\'].strftime(\"%H:%M\"),i[\'endosocpist1\']]\r\n    end\r\n    \r\n    for i in ids_2\r\n        d = i[\'created_at\'].strftime(\"%Y-%m-%d\")\r\n        # stop = d if stop == nil or d>stop\r\n        # start = d if start == nil or d<start\r\n        date_map[d] = [] unless date_map[d]\r\n        date_map[d] << [:post_scope,i[\'_id\'],i[\'created_at\']]\r\n    end\r\n    \r\n    # t = stop.split(\'-\').collect{|i| i.to_i}\r\n    \r\n    # start =  Date.to_mongo(Date.new 2014, 5, 25)\r\n    # stop =  Date.to_mongo(Date.new t[0],t[1],t[2])\r\n    \r\n    providers = @models[:provider].collection.find({},{:fields=>{\'_id\'=>1,\'name\'=>1}})\r\n    mp = {}\r\n    \r\n    for i in providers\r\n        mp[i[\'_id\'].to_s] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    \r\n\r\n    ids_colo = @models[:colonoscopy].collection.find(cond,{:fields=>{\'_id\'=>1,\'created_at\'=>1,\'stop_at\'=>1,\'endoscopist_1\'=>1}}).to_a\r\n    ids_gastro = @models[:gastroscopy].collection.find(cond,{:fields=>{\'_id\'=>1,\'created_at\'=>1,\'stop_at\'=>1,\'endoscopist_1\'=>1}}).to_a\r\n    \r\n    pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:module_id=>{\'$in\'=>ids_colo.collect{|i| i[\'_id\']}}}).to_a\r\n    m_pm_colo = bmap pm_colo, \'module_id\'\r\n    m_app_colo = bmap pm_colo, \'parent_id\'\r\n\r\n    pm_app_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:_id=>{\'$in\'=>pm_colo.collect{|i| i[\'parent_id\']}}}).to_a\r\n    m_pm_app_colo = bmap pm_app_colo, \'_id\'\r\n    \r\n    ids_colo.collect!{|i| i if m_pm_colo[i[\'_id\']] and m_pm_app_colo[ m_pm_colo[i[\'_id\']][0][\'parent_id\'] ] }.compact!\r\n    \r\n\r\n\r\n\r\n\r\n    pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:module_id=>{\'$in\'=>ids_gastro.collect{|i| i[\'_id\']}}}).to_a\r\n    m_pm_gastro = bmap pm_gastro, \'module_id\'\r\n    m_app_gastro = bmap pm_gastro, \'parent_id\'\r\n\r\n    \r\n    for i in ids_colo\r\n    \r\n    d = i[\'created_at\'].strftime(\"%Y-%m-%d\")\r\n    date_map[d] = [] unless date_map[d]\r\n    date_map[d] << [:colonoscopy,i[\'_id\'],i[\'created_at\'],i[\'stop_at\'].strftime(\"%H:%M\")]\r\n    \r\n    if m_pm_colo[i[\'_id\']]\r\n        \r\n    m_colo = m_pm_colo[i[\'_id\']][0]\r\n    \r\n    date_map[d] << [:case,m_colo[\'parent_id\'],i[\'created_at\'],i[\'stop_at\'].strftime(\"%H:%M\"),i[\'endoscopist_1\']]\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    for i in ids_gastro\r\n    \r\n    d = i[\'created_at\'].strftime(\"%Y-%m-%d\")\r\n    m_gastro = m_pm_gastro[i[\'_id\']][0]\r\n    unless m_app_colo[m_gastro[\'parent_id\']]\r\n    \r\n    date_map[d] = [] unless date_map[d]\r\n    date_map[d] << [:gastroscopy,i[\'_id\'],i[\'created_at\'],i[\'stop_at\'].strftime(\"%H:%M\")]\r\n    date_map[d] << [:case,m_gastro[\'parent_id\'],i[\'created_at\'],i[\'stop_at\'].strftime(\"%H:%M\"),i[\'endoscopist_1\']]\r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    for k in date_map.keys\r\n        date_map[k].sort!{|a,b| a[2]<=>b[2] }    \r\n    end\r\n   \r\n    \r\n  %>\r\n\r\n<%=start %> - <%= stop %>\r\n<style>\r\n    .a1{color:red}\r\n    .a2{color:green}\r\n    .a3{color:blue}\r\n    .a4{color:orange;\r\n    \r\n    \r\n</style>\r\n\r\n    \r\n    \r\n\r\n\r\n<table border=\"1\">\r\n<%\r\n    date_map.keys.sort.each do |k|\r\n        v = date_map[k]        \r\n%>\r\n<div>\r\n<h4><%= k %> : </h4><%# count[k].inspect %>\r\n<%   \r\n   last = v[0][2]\r\n%>\r\n<%\r\n   if false\r\n   for i in v \r\n       cls = {:intra_scope=>\'a1\',:post_scope=>\'a2\',:colonoscopy=>\'a3\',:gastroscopy=>\'a4\'}[i[0]]\r\n   %>\r\n    <li ><span class=\"<%=cls%>\" ><%= i.inspect  %> - - <%= i[2] - last  %></span></li>\r\n    <%\r\n        last = i[2]\r\n    %>\r\n    \r\n   <% end %>\r\n   <% end %>\r\n   <hr/> \r\n   <% \r\n   \r\n    m_list = {}\r\n    list = []\r\n    \r\n    for i in v \r\n        \r\n        if i[0] == :intra_scope\r\n        \r\n            \r\n            \r\n            found = false\r\n            \r\n            for j in list\r\n            \r\n                if j[0]==nil\r\n                   j[0] = i\r\n                   found = true\r\n                   break \r\n                end\r\n                \r\n            end\r\n            \r\n            \r\n            list << [i,nil,nil] unless found\r\n            \r\n        \r\n        elsif i[0] == :post_scope\r\n            \r\n            found = false\r\n            \r\n            for j in list\r\n            \r\n                if j[1]==nil\r\n                   j[1] = i\r\n                   found = true\r\n                   break \r\n                end\r\n                \r\n            end\r\n            \r\n            \r\n            list << [nil,i,nil] unless found\r\n            \r\n     end\r\n end\r\n \r\n    for i in v\r\n    \r\n    \r\n        if i[0] == :case\r\n        \r\n            m_list[i[3]] = [] unless m_list[i[3]]\r\n            m_list[i[3]] << i\r\n            \r\n            found = false\r\n            \r\n            for j in list\r\n            \r\n                if j[2] == nil and j[0] and (i[2]-j[0][2]).abs <30*60\r\n                   j[2] = i\r\n                   found = true\r\n                   break \r\n                end\r\n                \r\n            end\r\n            \r\n            \r\n            list << [nil,nil,i] unless found\r\n            \r\n        \r\n        end\r\n        \r\n    \r\n    end\r\n    \r\n    i_list = {}\r\n    \r\n    for i in list\r\n    \r\n        if i[2]\r\n            \r\n            i_list[i[2][3]] = i\r\n        \r\n        end\r\n    end\r\n    \r\n    \r\n    \r\n    for i in list\r\n        \r\n           if i[0] and i[1] and i[2]\r\n               \r\n               if i[0][3] != i[2][3]\r\n                    \r\n                    if m_list[i[0][3]]\r\n                        \r\n                        #  i_list[i[0][3]][2] = i[2] if i_list[i[0][3]] \r\n                        \r\n                        # i[2] = m_list[i[0][3]].shift\r\n                        \r\n                    end\r\n                     \r\n               end\r\n               \r\n           end\r\n    \r\n    end\r\n    \r\n    i_list = {}\r\n    \r\n    for i in list.reverse\r\n    \r\n        if i[2]\r\n            \r\n            if i_list[i[2][1]]\r\n               \r\n            #   i[2] = nil\r\n                \r\n            else\r\n                \r\n                i_list[i[2][1]] = i\r\n                \r\n            end\r\n            \r\n            \r\n            \r\n        end\r\n    end\r\n    \r\n    \r\n    \r\n    # for i in list\r\n        \r\n    #     i << m_list[i[0][3]].shift\r\n        \r\n    # end\r\n    options = [[nil,nil]]+v.collect{|i| [\"\\\\#{i[3]} \\\\#{mp[i[4].to_s]}\",i[1]] if i[0]==:case }.compact\r\n    \r\n    %>\r\n    <%#options.inspect %>\r\n    \r\n    <%\r\n    for i in list\r\n    \r\n     if true\r\n   \r\n     if i[0] and i[1]\r\n         \r\n         cls = \'a2\'\r\n    \r\n      x = nil\r\n      if i[2]\r\n      x = i[2][1]\r\n      \r\n         cls = \'a1\' if i[0][3] != i[2][3]\r\n         cls = \'a4\' if i[0][4] != i[2][4]\r\n      end\r\n   %>\r\n   \r\n   <li class=\"<%=cls%>\"><%=i[0][0] %> | <%=i[0][3] %>  | <b> <%= mp[i[0][4].to_s] %> </b> | <%= select_tag \"cases[\\\\#{i[0][1]}-\\\\#{i[1][1]}]\", options_for_select(options,x) %>|  <%=i[2][3]  if x%>   | <%= mp[i[2][4].to_s] if x %> |<%=i[0][2] %> | <%=i[1][2] %> | <%=i[2][2] if x %>   </li>\r\n   \r\n    <% elsif i[0]%>\r\n   \r\n   <li class=\"a1\"><%=i.inspect %> </li>\r\n    \r\n    <% end %>\r\n    \r\n    \r\n    <% end %>\r\n    \r\n    <% end %>\r\n    \r\n\r\n   \r\n</div> \r\n    <% end %>\r\n         <%= f.submit \'Submit\', :class=>\'btn\' %>  &nbsp; &nbsp; &nbsp; <%= f.check_box \'perform_commit\'%> Commit\r\n    \r\n    <% end %>\r\n</table>\r\n    <% end %>\r\n\r\n',NULL,NULL,NULL,'2015-05-09 18:42:43','2015-05-09 18:42:43','associate_intra_post',''),(1497,'final_check',675,2,'<%= render :inline=>this.init %>\r\n<%\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n    # all patient\r\n    patients = @m_patient.collection.find({},{:fields=>{\'_id\'=>1,\'hn\'=>1, \'public_number\'=>1}}).to_a\r\n    out[:A_total_patient]  = patients.size\r\n    m_hn = bmap patients, \'hn\'\r\n\r\n    \r\n    # all pm appointment of patients\r\n    pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:patient_id=>{\'$in\'=>patients.collect{|i| i[\'_id\']}}}).to_a\r\n    out[:A_patient_appointments_link] = pm_app.size\r\n    \r\n    # all appointment of pm\r\n    app = @models[:appointment].collection.find({:_id=>{\'$in\'=>pm_app.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'date\'=>1, \'status\'=>1 }}).to_a\r\n    out[:A_patient_appointments_ass] = app.size\r\n    \r\n    #===============================================================================================\r\n    \r\n    # all appointment with and without pm\r\n    all_app =  @models[:appointment].collection.find({},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1}}).to_a\r\n    m_all_app = bmap all_app, \'_id\'\r\n\r\n    out[:B_all_appointments] =all_app.size\r\n\r\n    # all pm appointment of those appointmets\r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    out[:B_all_appointments_ass] =all_pm_app.size\r\n    \r\n    #===============================================================================================\r\n    \r\n    # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n    colos = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'created_at\'=>1 }}).to_a\r\n    m_colo = bmap colos, \'_id\'\r\n\r\n  \r\n  %>\r\n  <%= colos.size %>\r\n  <%\r\n    \r\n    pm_delete = []\r\n    \r\n        \r\n    \r\n    multi_colo = 0\r\n    \r\n    for i in all_pm_app\r\n    \r\n        appx = m_all_app[i[\'module_id\']][0]\r\n        \r\n        m = m_all_pm_colo[i[\'_id\']]\r\n        if m and m.size>1\r\n             %>\r\n            <li><%= appx[\'status\'] %> - <%= appx[\'date\'].strftime(\"%d-%m-%y\") %> | <%= appx[\'_id\']%>\r\n            <ul>\r\n            <%\r\n             check = {}\r\n             \r\n             has_colo = {}\r\n             \r\n             for j in m\r\n             \r\n             colo = m_colo[j[\'module_id\']]\r\n             has_colo[j[\'module_id\']] = j if colo\r\n             check[j[\'module_id\']] = j\r\n             if true\r\n             %><li> PM colo created at : <%= j[\'created_at\']%>| <%= j[\'_id\']%> | <%= colo[0][\'created_at\'] if colo %> \r\n             | Colo id : <%= j[\'module_id\']%> | Patient id :  <%= j[\'patient_id\']%> | Appointment patient id : <%= i[\'patient_id\']%></li>\r\n             <%\r\n             end\r\n            end\r\n            %>\r\n            </ul>\r\n            </li>\r\n            <%\r\n                case m.size - check.keys.size \r\n                when 0 \r\n                    if has_colo.keys.size == check.keys.size\r\n                        \r\n                        for pm in check.values\r\n                            pm_delete << pm[\'_id\']\r\n                        end\r\n                        \r\n                    %>\r\n                    <span style=\"color:blue\">Case 2\r\n                    <%\r\n                    else\r\n                        for pm in check.values\r\n                            unless has_colo[pm[\'module_id\']]\r\n                                 pm_delete << pm[\'_id\']\r\n                            end\r\n                        end\r\n                    %>\r\n                    <span style=\"color:red\">Case 3\r\n                    <%\r\n                    end\r\n                when m.size - 1\r\n                       for pm in m[1..-1]\r\n                            pm_delete << pm[\'_id\']\r\n                       end\r\n                     %>\r\n                    <span style=\"color:green\">Case 1\r\n                    <%\r\n                end\r\n            %>\r\n            <%= check.keys.inspect %>\r\n            </span>\r\n            <br/>\r\n            <%\r\n             multi_colo+=1\r\n        end\r\n        \r\n        \r\n    end\r\n    \r\n    out[:multi_colo] = multi_colo\r\n    \r\n    %>\r\n    To delete : <%= pm_delete.size %>\r\n    <%= pm_delete.inspect  %>\r\n    \r\n<% if params[:commit] %>\r\n\r\n<% \r\n\r\nfor i in pm_delete\r\n    \r\n@m_patient_module.collection.remove(\'_id\'=>i)\r\n        \r\n%>\r\n<%= i %> ... deleted\r\n<% end %>\r\n\r\n\r\n\r\n<% end %>\r\n    \r\n    <%\r\n    \r\n    \r\n    \r\n    m_pm_app = bmap pm_app, \'patient_id\'\r\n    m_app = bmap app\r\n    \r\n\r\n    pm_record = 0\r\n    no_pm_record = 0 \r\n\r\n    app_record = 0\r\n    no_app_record = 0\r\n    \r\n    unique_hn = 0\r\n    repeat_hn = 0 \r\n    # patients = patients[0..1000]\r\n    \r\n    # all patient\r\n    for i in patients\r\n        \r\n        # check repeat hn\r\n        if m_hn[i[\'hn\']].size==1\r\n            unique_hn+=1\r\n        else\r\n            repeat_hn+=1\r\n        end\r\n            \r\n        pid = i[\'_id\']\r\n        \r\n        # all appointments for a patient\r\n        pm_a = m_pm_app[pid]\r\n        if pm_a\r\n            pm_record += 1\r\n            for j in pm_a\r\n                app = m_app[j[\'module_id\']]\r\n            \r\n                if app and app = app[0]\r\n                    app_record += 1 \r\n                else\r\n                    no_app_record+= 1 \r\n                end\r\n            end\r\n      \r\n         \r\n        \r\n        else\r\n               no_pm_record+=1\r\n            \r\n        end\r\n        \r\n    end\r\n    out[:A_unique_hn] = unique_hn\r\n    out[:A_repeat_hn] = repeat_hn\r\n    out[:C_patient_has_pm_record] = pm_record\r\n    out[:C_patient_has_no_pm_record] = no_pm_record\r\n    out[:app_record] = app_record\r\n    out[:no_app_record] = no_app_record\r\n\r\n%>\r\n\r\n<%\r\n  out.each_pair do |k,v|\r\n%>\r\n<%= k %> :  <%=v%>\r\n<hr/>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-09 18:42:58','2015-05-09 18:42:58','final_check',''),(1500,'final_check_2',675,2,'<%= render :inline=>this.init %>\r\n<%\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    params[:date] = \'27/5/2014\'\r\n    date = Date.to_mongo(Time.zone.parse(params[:date].split(\'/\').reverse.join(\"-\")))\r\n\r\n%>\r\n<%=date%><br/>\r\n<%\r\n\r\n    colo = @models[:colonoscopy].collection.find({:created_at=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}}).to_a\r\n    \r\n    pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:module_id=>{\'$in\'=>colo.collect{|i| i[\'_id\']}}}).to_a\r\n    \r\n    m_pm_colo = bmap pm_colo, \'module_id\'\r\n    \r\n    patients = @m_patient.collection.find({:_id=>{\'$in\'=>pm_colo.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'hn\'=>1, \'first_name\'=>1}}).to_a\r\n    \r\n    m_patients = bmap patients, \'_id\'\r\n    \r\n    pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:_id=>{\'$in\'=>pm_colo.collect{|i| i[\'parent_id\']}}}).to_a\r\n    %>\r\n    <%=pm_app.size %><hr/>\r\n    <%\r\n    m_pm_app = bmap pm_app\r\n    \r\n    patients2 = @m_patient.collection.find({:_id=>{\'$in\'=>pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'hn\'=>1, \'first_name\'=>1}}).to_a\r\n\r\n    m_patients_2 = bmap patients2, \'_id\'\r\n    \r\n   \r\n\r\n\r\n    \r\n    colo.each_with_index do |i,index|\r\n%>\r\n<%\r\n     pm = m_pm_colo[i[\'_id\']]\r\n     \r\n     \r\n     for j in pm\r\n     \r\n     \r\n     ps = m_patients[j[\'patient_id\']]\r\n     \r\n     parent = m_pm_app[j[\'parent_id\']]\r\n     \r\n     pr = nil\r\n     pr = parent[0] if parent and parent.size>0\r\n     ps2 = nil\r\n     ps2 = m_patients_2[pr[\'patient_id\']][0] if pr\r\n     \r\n     \r\nfor p in ps\r\n unless ps2\r\n%>\r\n <li> <%= p[\'hn\'] %> <%= p[\'first_name\'] %> | <%=j[\'parent_id\']%> | No parent <%# %></li>\r\n<% else %>\r\n <li> <%= p[\'hn\'] %> <%= p[\'first_name\'] %> | <%=j[\'parent_id\']%> | <%= ps2[\'hn\'] %> | <%= ps2[\'first_name\'] %> <%# %></li>\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-09 18:43:16','2015-05-09 18:43:16','final_check_2',''),(1501,'final_check_2_ass',675,2,'<%= render :inline=>this.init %>\r\n<%\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    params[:date] = \'27/5/2014\'\r\n    date = Date.to_mongo(Time.zone.parse(params[:date].split(\'/\').reverse.join(\"-\")))\r\n\r\n%>\r\n<%#date%><br/>\r\n<%\r\n\r\n    # colo = @models[:colonoscopy].collection.find({:created_at=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}}).to_a\r\n    colo = @models[:colonoscopy].collection.find({},{:fields=>{\'_id\'=>1,\'created_at\'=>1}}).to_a\r\n    %>\r\n    <%= colo.size %>\r\n    <%\r\n    \r\n    pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:module_id=>{\'$in\'=>colo.collect{|i| i[\'_id\']}}}).to_a\r\n    \r\n    m_pm_colo = bmap pm_colo, \'module_id\'\r\n    \r\n    patients = @m_patient.collection.find({:_id=>{\'$in\'=>pm_colo.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'hn\'=>1, \'first_name\'=>1}}).to_a\r\n    \r\n    m_patients = bmap patients, \'_id\'\r\n    \r\n    pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:_id=>{\'$in\'=>pm_colo.collect{|i| i[\'parent_id\']}}}).to_a\r\n    %>\r\n    <%#pm_app.size %><hr/>\r\n    <%\r\n    m_pm_app = bmap pm_app\r\n    \r\n    patients2 = @m_patient.collection.find({:_id=>{\'$in\'=>pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'hn\'=>1, \'first_name\'=>1}}).to_a\r\n\r\n    m_patients_2 = bmap patients2, \'_id\'\r\n    \r\n    no_patient = 0 \r\n    no_parent =  0\r\n    \r\n    colo_delete = []\r\n    pm_delete = []\r\n    \r\n    colo.each_with_index do |i,index|\r\n%>\r\n<%   \r\n     pm = m_pm_colo[i[\'_id\']]\r\n     if pm\r\n       for j in pm\r\n            ps = m_patients[j[\'patient_id\']]\r\n            parent = m_pm_app[j[\'parent_id\']]\r\n            pr = nil\r\n            pr = parent[0] if parent and parent.size>0\r\n            ps2 = nil\r\n            if pr\r\n                parent_patient = m_patients_2[pr[\'patient_id\']]\r\n                ps2 = parent_patient[0] if parent_patient and parent_patient.size>0\r\n            end\r\n            \r\n            if ps\r\n                \r\n                \r\n                     \r\n                if parent    \r\n                    \r\n                    \r\n                else  \r\n                        #no appointment\r\n                        p = ps[0]\r\n                        \r\n                        \r\n                        pm_delete << j[\'_id\']\r\n                        colo_delete << i[\'_id\'] unless j[\'parent_id\']\r\n                        \r\n                        if false\r\n                    %>\r\n                    <li>  <%= i[\'created_at\'].strftime(\"%d-%m-%y\") %>  <%= p[\'hn\'] %> <%= p[\'first_name\'] %> | <%=j[\'parent_id\']%> <%#j.inspect %>| No parent\r\n                    <%\r\n                    end\r\n                    no_parent +=1 \r\n                end\r\n        \r\n            else\r\n                no_patient +=1\r\n            end\r\n            \r\n            if ps  and false\r\n             \r\n                for p in ps\r\n                    unless ps2\r\n                        %>\r\n                        <li> <%= p[\'hn\'] %> <%= p[\'first_name\'] %> | <%=j[\'parent_id\']%> | No parent <%# %></li>\r\n                    <% end %>\r\n                <% end %>\r\n  \r\n        <% end %>\r\n        <%    \r\n        end\r\n     else \r\n         \r\n       %>\r\n       <li>No Pm for date : <%= i[\'created_at\'].strftime(\'%d-%m-%y\')%></li>\r\n       <%\r\n     end     \r\n         %>\r\n\r\n\r\n\r\n    \r\n<% end %>\r\nNo patient : <%= no_patient%><br/>\r\nNo parent  : <%= no_parent%><br/>\r\nColo delete : <%=colo_delete.size%>\r\nPM delete : <%=pm_delete.size %>\r\n<% if params[:commit] %>\r\n\r\n<% \r\n\r\n    for i in pm_delete\r\n    \r\n        @m_patient_module.collection.remove(\'_id\'=>i)\r\n        \r\n%>\r\n<%= i %> ... deleted\r\n<% end %>\r\n<% \r\n\r\n    for i in colo_delete\r\n    \r\n        @models[:colonoscopy].collection.remove(\'_id\'=>i)\r\n        \r\n%>\r\n<%= i %> ... deleted\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-09 18:43:48','2015-05-09 18:43:48','final_check_2_ass',''),(1502,'init',675,4,'<%\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    \r\n    @m_patient = model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    \r\n    @models = get_model\r\n    @m_appointment = @models[:attachment] \r\n    \r\n    \r\n       \r\n    def query_unlink m\r\n        model =  @models[m]\r\n        if m == :intra_op\r\n            ids = model.collection.find({},{:fields=>{\'_id\'=>1,\'created_at\'=>1,\'procedure_complete\'=>1}}).to_a\r\n        else\r\n            ids = model.collection.find({},{:fields=>{\'_id\'=>1,\'created_at\'=>1}}).to_a\r\n        end\r\n        \r\n        \r\n        mids = @m_patient_module.collection.find(:module_id=>{\'$in\'=>  ids.collect{|i| i[\'_id\']} }).to_a\r\n        unlink = []\r\n        map = {}\r\n        for i in mids\r\n            map[i[\"module_id\"]] = i\r\n        end\r\n        ids.collect!{|i| i unless map[i[\'_id\']]}.compact!\r\n        return ids \r\n    end    \r\n    \r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n%>',NULL,NULL,NULL,'2015-05-09 18:45:51','2015-05-09 18:45:51','init',''),(1503,'total_report',675,3,'<%= render :inline=>this.init %>\r\n<%\r\n\r\n    pname = \"\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1 }}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1 }}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n    \r\n\r\n    \r\n    \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    %>\r\n    <%=vt.inspect %>\r\n    <%\r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                    end\r\n                end\r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        end\r\n    \r\n    end\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n            \r\n    \r\n    \r\n    \r\n %>\r\n<table border=\"1\">\r\n<%\r\n   m = nil\r\n   for i in dates.keys.sort\r\n\r\n%>\r\n<%\r\n   km = i.split(\"-\")[0..1].join(\"-\")\r\n   if km!=m\r\n    m = km\r\n%>\r\n<tr style=\"background:#deffde\"><td>&nbsp;</td>\r\n    <td colspan=\"4\">Elective</td>\r\n    <td colspan=\"4\">Extratime</td>\r\n    <td colspan=\"4\">Emergency</td>\r\n    <td colspan=\"4\">Total</td>\r\n    \r\n</tr>\r\n<tr style=\"background:#dedeff\"><td>&nbsp;</td>\r\n    <td>C</td><td>G</td><td>C+G</td><td>Sum</td>\r\n    <td>C</td><td>G</td><td>C+G</td><td>Sum</td>\r\n    <td>C</td><td>G</td><td>C+G</td><td>Sum</td>\r\n    <td>C</td><td>G</td><td>C+G</td><td>Sum</td>\r\n\r\n\r\n</tr>\r\n\r\n<% end %>\r\n<tr>\r\n    <td><%=i%></td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Extratime Emergency} \r\n        \r\n        k = [0,0,0]\r\n        k = dates[i][j] if dates[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n    %>\r\n    <td><%=k[0] %></td> <td><%=k[1] %></td> <td><%=k[2] %></td> <td><%=k[0]+k[1]+k[2] %></td>\r\n\r\n    <% end %>\r\n    <td><%=sum[0] %></td> <td><%=sum[1] %></td> <td><%=sum[2] %></td> <td><%=sum[0]+sum[1]+sum[2] %></td>\r\n\r\n</tr> \r\n<% end %>\r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-09 18:46:12','2015-05-09 18:46:12','total_report',''),(1504,'index_bk',666,2,'<%\r\nmodule_name = @current_project.name\r\nif params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\nend\r\nif session[module_name]\r\n	params[:date] = session[module_name][:date]\r\nend\r\nunless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\nend\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    provider = models[:provider].where(:login=>@current_user.login).first\r\n    if provider\r\n       s_provider = provider.id.to_s\r\n    end\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       My Patients\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\'../Home/index\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n            \r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n                \r\n            </div>\r\n            </span>\r\n            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            \r\n            \r\n            <div class=\"field-input\">\r\n                 <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                 \r\n                 <!--<%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>-->\r\n            </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            <div class=\"field-input\">\r\n            <%\r\n            # Home/patient_record?id=5533e537790f9b01c2000006\r\n                # add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n                if s_provider \r\n                    # add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                    add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                end\r\n                \r\n            %>\r\n              \r\n                 <!--<%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>-->\r\n            </div>\r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        </div>\r\n        <div class=\"row-fluid\"></div>\r\n \r\n<strong>\r\n<%\r\n    rs = []\r\n    if !search_patient and params[:select].nil?\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\").all\r\n    	end\r\n    %>\r\n    <!--ALL : <%= rs.size %>-->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name, :last_name=>s_last_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n        # patients = patient_model.where(criteria).limit(20).all\r\n        patients = patient_model.where(criteria).all\r\n	    # maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}\r\n        # aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     	    rs = module_model.where(:patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\"\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT : <%= rs.size %>-->\r\n    <%\r\n    elsif params[:date]\r\n        require \'date\'\r\n        dddd = Date.parse(params[:date])\r\n	    conds = {:date.gte=>dddd.at_beginning_of_day,:date.lt=>dddd.end_of_day, :module_name=>\"\\\\#{@current_project.name}#provider\"}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n            conds.merge! :module_id=>s_provider \r\n            # conds[:module_id] = s_provider\r\n            # conds[:module_name] = @current_project.name + \"#provider\"\r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n        rs = module_model.where(conds).all\r\n        # aps = ap_model.all(conds)\r\n    	# filter provider\r\n    # 	if s_provider and s_provider != \'\'\r\n     	  #  conds[:module_id] = s_provider\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    #  	else\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    # 	end\r\n    	\r\n    # 	rs = module_model.all(conds)\r\n        # rs = module_model.all\r\n\r\n    %>\r\n    <!--DATE : <%=rs.size%> | <%= conds %>-->\r\n    <%\r\n    end # end if\r\n%>\r\n</strong>\r\n<!--<br/>-->\r\n<!--<br/>-->\r\n<%\r\nm_procedure = models[:procedure].all\r\nmap_proc = {}\r\nfor m in m_procedure do\r\n    map_proc[m.id] = m\r\nend\r\n\r\nm_provider  = models[:provider].all\r\nmap_prov = {}\r\nfor m in m_provider do \r\n    map_prov[m.id.to_s] = m[:name]\r\nend\r\nresult = rs.collect do |i|\r\n    m_patient = patient_model.find(i[:patient_id].to_s)\r\n    \r\n    patient_name = m_patient[:first_name] + \" \" + m_patient[:last_name]\r\n    \r\n    # prov = map_prov[i[:id]]\r\n    m_id = i[:module_id].to_s\r\n    prov = map_prov[m_id]\r\n    \r\n    # prov = nil\r\n    proc_rs = []\r\n    # OLD\r\n    # m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    # for m in m_ap do\r\n    #     ap = models[:appointment].find(m[:module_id])\r\n    #     if ap\r\n    #         proc_rs.push(map_proc[ap[:procedure]])\r\n    #     end\r\n    # end\r\n    # NEW\r\n    m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    for m in m_ap do\r\n        ap = models[:appointment].find(m[:module_id])\r\n        if ap\r\n            # proc_rs.push(map_proc[ap[:procedure]])\r\n            procedure = map_proc[ap[:procedure]]\r\n            code = procedure[:code]\r\n            name = procedure[:name]\r\n            m_code = \"\\\\#{@current_project.name}#\\\\#{code}\"\r\n            m_tmp = module_model.where(:module_name=>m_code, :parent_id=>m.id).first\r\n            side = \'-\'\r\n            if m_tmp\r\n                rec = models[code.to_sym].find(m_tmp[:module_id])\r\n                if rec[:side] == \'1\'\r\n                    side = \'L\'\r\n                elsif rec[:side] == \'2\'\r\n                    side = \'R\'\r\n                end\r\n            end\r\n            txt = name + \" (\" + side + \") \"\r\n            \r\n            if @current_role == \'developer\'\r\n                m_tmp = module_model.where(:parent_id=>m.id).collect{|i| i if i[:module_name].include? \'follow\'}\r\n                txt += \"[\" + m_tmp.count.to_s + \"]\"\r\n            end\r\n            \r\n            proc_rs.push(txt)\r\n        end\r\n    end\r\n    \r\n    proc_txt = \'<center><font color=\"red\">-- Create New --</font></center>\'\r\n    if !proc_rs.empty?\r\n        proc_txt = \'\'\r\n        for x in proc_rs do \r\n            proc_txt += \'<center><div class=\"row-fluid\">\' + x.to_s + \'</div></center> \'\r\n        end\r\n    end\r\n    action = \' \'\r\n    action += link_to(\'Detail\',\"patient_record?id=\\\\#{i[:patient_id]}\",:class=>\'btn btn-info\')\r\n    action += \" \"\r\n    action += link_to(\'\', \"../../www/Patient/edit?id=\\\\#{m_patient.id}&return=\\\\#{request.fullpath}\", :class=>\'splashy-contact_blue_edit\').html_safe\r\n    action += \" \"\r\n    action += link_to(\'\', \"\", :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{m_patient.id}\'); return false;\")\r\n    action += \" \"\r\n    \r\n    {:date=>i[:date], :hn=>m_patient[:hn], :name=>patient_name, :pid=>i[:patient_id], :procedure=>proc_txt, :action=>action, :provider=>prov}\r\nend\r\ncount = 1\r\nlabels = {:no=>\'No.\', :date=>\'Date\', :hn=>\'HN\', :name=>\'Patient Name\', :procedure=>\'Previous Procedure\', :action=>\'Action\'}\r\nfield_select = [:no, :date, :hn, :name, :procedure, :action]\r\n\r\nif @current_role == \'developer\'\r\n    labels[:provider] = \'Provider\'\r\n    field_select.insert(4, :provider)\r\nend\r\nresult = result.sort_by{|i| i[:date]}.reverse\r\n%>\r\n        \r\n        <!--<div class=\"row-fluid\">-->\r\n        <!--    <div style=\"padding-left:10px;display:block;vertical-align:middle\">-->\r\n        <!--        All Patient(s) : <v><%= result.count if result %></v> <%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>-->\r\n        <!--    </div>-->\r\n        <!--</div>-->\r\n        <!--<br/>-->\r\n        <div class=\"row-fluid\">\r\n            <br/>\r\n            <div class=\"\" style=\"float:left;margin-left:10px\">\r\n                All Patient(s) : <span style=\"color:blue\"><%= result.count if result %></span>\r\n                <%=link_to \'<i class=\"splashy-contact_blue_add\"></i> Add Patient\'.html_safe, add_patient, :class=>\'btn btn-info btn-mini\', :style=>\'margin-left:10px\'%>\r\n            </div>\r\n            <div class=\"\" style=\"float:right;margin-right:10px\">\r\n                <%= link_to \'<i class=\"splashy-document_a4\"></i> Reports\'.html_safe,\"../Home/report\", :class=>\'btn btn-mini\' %> | \r\n                <%=link_to \'<i class=\"splashy-sprocket_light\"></i> Setting\'.html_safe, \'../Setting/index\', :class=>\'btn btn-mini\' %>\r\n            </div>\r\n            <br/>\r\n        </div>\r\n        \r\n        <div id=\"result-panel\" style=\"padding:10px\">\r\n            <%= tabular :data=>result, :model=>field_select, :labels=>labels, :col_width=>{:no=>50} do |row,out|\r\n                    out[0] = \"<center>\" + count.to_s+\".</center>\"\r\n                    out[0] = out[0].html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n            %>\r\n        </div>\r\n        \r\n    </div>\r\n\r\n\r\n<hr/>\r\n\r\n<%= link_to \'Access\', \'javascript:access(\"/\")\'%>\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function confirm_delete(id) {\r\n        // destroy?id=\\\\#{m_patient.id}&mode=patient&return=\\\\#{request.fullpath}\r\n<%\r\n    destroy_url = \"destroy?mode=patient&id=\".html_safe\r\n    return_url  = \"&return=\\\\#{request.fullpath}\".html_safe\r\n%>\r\n        if (confirm(\"Do you want to delete patient data ?\") == true) {\r\n            if (confirm(\"All of patient data will be lost\") == true) {\r\n                url = \"<%= destroy_url %>\" + id + \"<%= return_url %>\";\r\n                window.location = url;\r\n            }\r\n        }\r\n    }\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<!--\r\n<div class=\"alert \">\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n</div>\r\n-->\r\n<script>\r\n\r\n    <%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    user = model[:user].where(:login=>@current_user.login).first\r\n    \r\n    %>\r\n    \r\n    function access(target){\r\n        \r\n        var pin = prompt(\"Please enter PIN\", \"\");\r\n        if( \'<%= user ? user.pin : \'-\'%>\'==pin){\r\n            window.location = target\r\n        }\r\n        \r\n        \r\n    }\r\n    \r\n</script>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n',NULL,NULL,NULL,'2015-05-10 08:55:38','2015-05-10 08:55:38','index_bk',''),(1505,'add_new',689,3,'<%= render :inline=>this.init %>\r\n                                        <div id=\"form-panel\" class=\"form-horizontal well\">\r\n											<%= form_for :account, :url=>\"index\", :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Add New Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">no space, special characters</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'member\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:class=>\'btn\', :style=>\'vertical-align: top;\' %></span>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>',NULL,NULL,NULL,'2015-05-10 11:07:35','2015-05-10 11:07:35','add_new',''),(1506,'update',689,3,'<%= render :inline=>this.init %>\r\n                                        <div id=\"form-panel\" class=\"form-horizontal well\">\r\n											<%= form_for :update, :url=>\"index\", :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Update Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.hidden_field :login_name, :value=>@current_user.name %>\r\n        													<input type=\"text\" name=\"login_name\" class=\"span10\" value=\"<%= @current_user.name %>\" disabled>\r\n        													<!--<span class=\"help-block\">no space, special characters</span>-->\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'member\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:class=>\'btn\', :style=>\'vertical-align: top;\' %></span>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>',NULL,NULL,NULL,'2015-05-10 14:33:47','2015-05-10 14:33:47','update',''),(1507,'test',502,3,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n  \r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    m_att = model[:attachment].all\r\n    result = {}\r\n    result[:model_attachment] = m_att\r\n%>\r\n<%= result.to_json.html_safe %>',NULL,NULL,NULL,'2015-05-10 17:20:36','2015-05-10 17:20:36','test','*'),(1509,'patient_report',502,3,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  <script>\r\n      var console = new function() {\r\n          this.log = function(x) {};\r\n      }\r\n  </script>\r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n			\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n		    <title><%=title%></title>\r\n\r\n				<script>\r\n					$(document).ready(function() {\r\n						//* show all elements & remove preloader\r\n						// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n						 // $(\"html\").removeClass(\"js\");\r\n					});\r\n				</script>\r\n		\r\n				 <style>\r\n    .w-box-content.cnt_a {background: #fff;}\r\n    .k-grid table {font-size: 1em;}\r\n    .k-calendar .k-content {font-size: 1em;padding-top:5px;}\r\n    .k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\n        height: 18px;\r\n    }\r\n    .field-data {width: 220px;}\r\n\r\ninput{\r\n    height:18px;\r\n}\r\nbody { \r\n    /*background-image: url(\'/esm/thks/www/content/hip-knee-pain-bw.jpg\');*/\r\n    /* ref : http://i0.wp.com/blog.beaumont.edu/wp-content/uploads/2014/10/hip-knee-pain.png */\r\n    background-repeat: no-repeat;\r\n    background-attachment: fixed;\r\n    background-position: center top; \r\n    /*background-color: black;*/\r\n    /*background-size: cover;*/\r\n    padding: 20px;\r\n    font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\r\n    /*font-weight: lighter;*/\r\n    /*font-size: 1em;*/\r\n}\r\n</style>\r\n		\r\n		\r\n</head>\r\n<body>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\" style=\"padding:0px;\">\r\n<!--start body content-->\r\n\r\n    <div class=\"row-fluid\">\r\n        \r\n<%\r\nmodule_name = @current_project.name\r\nif params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\nend\r\nif session[module_name]\r\n	params[:date] = session[module_name][:date]\r\nend\r\nunless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\nend\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n        s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n        s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n        date_text = s_date.strftime(\"%d/%m/%Y\")\r\n        session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n         Patient Report : CU GI MED \r\n         <span style=\"float:right\"><%=Time.now%></span>\r\n         <div class=\"clear\"></div>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:5px\" >\r\n    \r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\'patient_report\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n            \r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            \r\n            \r\n            <div class=\"field-input\">\r\n                 <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                 \r\n                 <!--<%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>-->\r\n            </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        \r\n        </div>\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%# params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n    \r\n    if !search_patient and params[:select].nil?\r\n\r\n    # 	patients = patient_model.all  \r\n	   # maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n    # 	aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    # 	# filter provider\r\n    # 	if s_provider and s_provider != \'\'\r\n    #  		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n    #  		 aps = tmp\r\n    # 	end\r\n    # 	aps = []\r\n        conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n    	aps = ap_model.all(conds)\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n    %>\r\n    <!--ALL -->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name, :last_name=>s_last_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n    # 	patients = patient_model.where(criteria).limit(20).all  \r\n        patients = patient_model.where(criteria).limit(20).all  \r\n	    maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n    	aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT-->\r\n    <%\r\n    elsif params[:date]\r\n    \r\n	    conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n    		conds.merge! :provider=>s_provider \r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n    \r\n    	aps = ap_model.all(conds)\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n\r\n    %>\r\n    <!--DATE-->\r\n    <%\r\n    end # end if\r\n    %>\r\n\r\n<%\r\n    map_provider = {}\r\n    for i in provider_model do\r\n        map_provider[i.id.to_s] = i\r\n    end\r\n    result = []\r\n    x = 0\r\n    aps.each do |i|\r\n        x += 1\r\n        tmp = {}\r\n        tmp[:date] = i[:date]\r\n        tmp[:provider] = map_provider[i[:provider].to_s].to_s\r\n        m_app = module_model.where(:module_id=>i.id).first\r\n        \r\n        patient = patient_model.find(m_app[:patient_id])\r\n        if patient.nil?\r\n            next\r\n        end\r\n        tmp[:hn] = patient[:hn]\r\n        tmp[:patient] = patient[:prefix].to_s + \" \" + patient[:first_name].to_s + \"&nbsp;&nbsp;&nbsp;\".html_safe + patient[:last_name].to_s\r\n        \r\n        operation = module_model.where(:parent_id=>m_app.id).all\r\n        operation.each do |j|\r\n            tmx = tmp.clone\r\n            op_name = j[:module_name].split(\'#\')[1].capitalize\r\n            att = model[:attachment].find(j[:report])\r\n            action = link_to(\'View\', \"../\\\\#{op_name}/rprint?id=\\\\#{j.id}\", :target=>\'\', :class=>\'btn btn-mini btn-success\')\r\n            if att\r\n                action += \'&nbsp;\'.html_safe\r\n                action += link_to(\'PDF\', att.path, :target=>\'\', :class=>\'btn btn-mini btn-success\')\r\n            end\r\n            tmx[:operation] = op_name\r\n            tmx[:action] = action\r\n            result.push(tmx)\r\n        end\r\n%>\r\n<!--Date : <%= i[:date] %><br/>-->\r\n<!--Provider : <%= map_provider[i[:provider].to_s] %> (<%= i[:provider] %>)<br/>-->\r\n<!--Operation : <%= operation.size %><br/>-->\r\n<!--Patient : <%# patient.inspect %><br/>-->\r\n<!--Result : <%= result.size %>-->\r\n<!--<hr/>-->\r\n<%  \r\n    end \r\n    labels = {:no=>\'No.\', :date=>\'Date\', :hn=>\'HN\', :patient=>\'Patient Name\', :provider=>\'Provider Name\', :operation=>\'Operation Name\', :action=>\'Action\'}\r\n    m = [:no, :date, :hn, :patient, :provider, :operation, :action]\r\n    result = result.sort_by{|i| i[:hn]}.reverse\r\n    result = result.uniq\r\n%>\r\n<%# aps.to_json.html_safe %>\r\n<div id=\"result-panel\"  style=\"padding:0px\">\r\n<p><p></p></p>\r\n<% c = 1 %>\r\n<table class=\"table table-striped\">\r\n    <thread>\r\n        <tr>\r\n            <%\r\n                for x in m\r\n            %>\r\n            <th><%= labels[x] %></th>\r\n            <%\r\n                end\r\n            %>\r\n        </tr>\r\n    </thread>\r\n    <%\r\n        for rs in result \r\n    %>\r\n    <tr>\r\n    <%\r\n            for x in m\r\n                if !rs[x]\r\n                    rs[x] = c\r\n                end\r\n                col = \"<td>\\\\#{rs[x]}</td>\".html_safe\r\n    %>\r\n        <%= col %>\r\n    <%\r\n            end\r\n    %>\r\n    </tr>\r\n    <%\r\n            c += 1\r\n        end\r\n    %>\r\n</table>\r\n<p><p></p></p>\r\n</div>\r\n\r\n\r\n<%\r\nif false \r\n \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n		 patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         # zamachita comment and change link to patient_record\r\n        #  hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n        # hn = link_to(patient.hn, \"patient_record?id=\\\\#{m[:patient_id]}&aid=\\\\#{m.id}\")\r\n        hn = link_to(patient.hn, \"patient_record?id=\\\\#{m.id}\")\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n        #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n        #  :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n        #  :visit_type=>visit_type\r\n        #  }\r\n        c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n        :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,\r\n        # :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{m[:patient_id]}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n        :visit_type=>visit_type\r\n        }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{m[:patient_id]}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{m[:patient_id]}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    # table_model = %w{date hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    table_model = %w{date hn patient provider }.collect{|i| i.to_sym}\r\n    \r\n    \r\n    # labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',\r\n    # :status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\', :note=>\'Note\',:visit_type=>\'Group\' }\r\n    labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:Provider=>\'Appointed Doctor\', :pending_ctrl=>\'Appointed ctrl\', :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n        \r\n        \r\n        \r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                 <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    out[0] = count.to_s+\".\"\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n\r\n        </div>\r\n<%\r\nend\r\n# end if false\r\n%>\r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"patient_report?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n\r\n<!--<div class=\"alert \">-->\r\n<!--Links : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | -->\r\n<!--<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | -->\r\n<!--<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>-->\r\n<!--</div>-->\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n        \r\n    </div>\r\n<!--body content-->\r\n</div>\r\n</div>\r\n     <script type=\"text/javascript\" charset=\"utf-8\">\r\n	refresh_remote();\r\n	$(\'#search-field\').focus()\r\n</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-05-10 17:48:36','2015-05-10 17:48:36','patient_report','*'),(1510,'rprint',674,3,'<%= this.print_partial %>',NULL,NULL,NULL,'2015-05-10 17:50:35','2015-05-10 17:50:35','rprint','*'),(1511,'finding_config',489,1,'{\r\n:name=>\'ERCP\',\r\n:selectors=>{:location=>%w{ bile_duct pancreatic_duct gallbladder }, \r\n:intervention=>%w{biliary_cannulation pancreatic_cannulation sphinctertomy balloon_sphicteroplasty balloon_stricturoplasty \r\nstone_extraction lithotripsy stent_placement_ercp stent_removal sampling transmural_drainage nasobiliary_tube_placement snare_ampullectomy }},\r\n:view=>[\r\n    {   :value=>\'esophagus\',\r\n        :editor_id=>\'finding_1_summary\',\r\n        :report_id=>\'p1\'\r\n    },\r\n    {   :value=>\'stomach\',\r\n        :editor_id=>\'finding_2_summary\',\r\n        :report_id=>\'p2\'\r\n    },\r\n    {   :value=>\'duodenum\',\r\n        :editor_id=>\'finding_3_summary\',\r\n        :report_id=>\'p3\'\r\n    },\r\n    {   :value=>\'bile_duct\',\r\n        :editor_id=>\'finding_6_summary\',\r\n        :report_id=>\'p6\'\r\n    },\r\n    {   :value=>\'pancreatic_duct\',\r\n        :editor_id=>\'finding_8_summary\',\r\n        :report_id=>\'p8\'\r\n    },\r\n    {   :value=>\'gallbladder\',\r\n        :editor_id=>\'finding_9_summary\',\r\n        :report_id=>\'p9\'\r\n    }\r\n    \r\n],\r\n:data=>[\r\n   \r\n    {   :title=>\'Stone/Sludge\',\r\n        :value=>\'filling_defect\',\r\n        :dx_id=>\'\',\r\n        :values=>{:location=>%w{bile_duct pancreatic_duct}},\r\n        :group=>1\r\n    },\r\n    \r\n    {   \r\n        :value=>\'ductal_stricture\',\r\n        :dx_id=>\'\',\r\n        :values=>{:location=>%w{bile_duct pancreatic_duct }},\r\n        :group=>1\r\n    },  \r\n    {   \r\n        :value=>\'mirizzi\',\r\n        :dx_id=>\'\',\r\n        :values=>{:location=>%w{gallbladder}},\r\n        :group=>1\r\n    },\r\n    { \r\n        :value=>\'stent_malfunction\',\r\n        :dx_id=>\'\',\r\n        :group=>2\r\n    },\r\n    {   \r\n        :value=>\'duct_leakage\',\r\n        :dx_id=>\'\',\r\n        :values=>{:location=>%w{bile_duct pancreatic_duct }},\r\n        :group=>2\r\n    },\r\n    {   :title=>\'Chronic pancreatitis\',\r\n        :value=>\'chronic_pancreatitis_ercp\',\r\n        :dx_id=>\'\',\r\n        :values=>{:location=>%w{pancreatic_duct}},\r\n        :group=>2\r\n    },\r\n    {   \r\n        :value=>\'pancreatic_pseudocyst\',\r\n        :dx_id=>\'\',\r\n        :values=>{:location=>%w{pancreatic_duct}},\r\n        :group=>2\r\n    },\r\n    {   :title=>\'Congenital anomalies\',\r\n        :value=>\'congenital_anomalies_ercp\',\r\n        :dx_id=>\'\',\r\n        :values=>{:location=>%w{pancreatic_duct}},\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'spyglass_cholangioscopy\',\r\n        :dx_id=>\'\',\r\n        :group=>0\r\n    }\r\n]\r\n}',NULL,NULL,NULL,'2015-05-11 03:50:28','2015-05-11 03:50:28','finding_config',''),(1512,'edit',599,2,'<%\r\n    show_color = false\r\n%>\r\n<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    # map procedure\r\n    models = get_model\r\n    m_procedure = models[:procedure].all\r\n    map_proc = {}\r\n    for m in m_procedure do\r\n        map_proc[m.id.to_s] = {:name=>m[:name], :code=>m[:code]}\r\n    end\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient_module = ehr_models[:patient_module]\r\n    \r\n    pm = m_patient_module.find(params[:id])\r\n    m_ap = m_patient_module.where(:id=>pm[:parent_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\").first\r\n    ap = models[:appointment].find(m_ap[:module_id])\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3><strong>Edit (<%= map_proc[ap[:procedure].to_s][:name] %>)</strong></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n<!--<div style=\"border:0px solid\">-->\r\n<!--<div class=\"document-border\" style=\"border:0px solid\">-->\r\n<div style=\"border:0px solid;<%= \"background-color:\\\\#{this.color_name};\" if show_color %>\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model()[this.table_name.to_sym]\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n// window.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\nwindow.location = \"<%= return_url %>\";\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n<!--<div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >-->\r\n\r\n<!--Ref : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> -->\r\n<!--<%= hidden_field_tag \'return\', return_url %>-->\r\n\r\n<!--<span class=\"right\">-->\r\n<!--Date : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>-->\r\n<!--Time : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>-->\r\n<!--</span>-->\r\n<!--</div>-->\r\n\r\n<%= hidden_field_tag \'return\', return_url %>\r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\' %> \r\n<%= hidden_field_tag \'ref_number\',@patient_module.ref_number %> \r\n<%= hidden_field_tag \'date\',Time.now %> \r\n<%= hidden_field_tag \'time\',Time.now.strftime(\"%H:%M\") %> \r\n\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>&return=<%=return_url%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \"Update\".html_safe, :onclick=>\'javascript:opnote()\', :class=>\'btn btn-small btn-success\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:data=>{:confirm=>\'Are you sure?\'}, :class=>\'btn btn-small\' %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<%# if @current_role == \'developer\' %>\r\n<%= render :inline=>this.opnote, :locals=>{:this=>this} %>\r\n<%# end %>\r\n\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r