0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n#image { display:none};\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm_core/banner.png\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3><%=this.table_name.to_s.humanize%></h3>\r\n<%= this.display.html_safe %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div class=\"hideprint\">\r\n<%= link_to \'Back\', url(\'index\') %>\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2015-05-12 05:58:56','2015-05-12 05:58:56','print',''),(1516,'display',614,3,'<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n\r\n <div style=\"width:720px; margin-left:auto; margin-right:auto\" >\r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n<p style=\"width:720px; margin-left:auto; margin-right:auto; font-weight:bold\">HN : <%= @patient.hn %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Name : <%= @patient.first_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Surname : <%= @patient.last_name %>\r\n<hr /><br />\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<%= render :inline=>this.imageshow, :locals=>{:this=>this} %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>',NULL,NULL,NULL,'2015-05-12 05:59:50','2015-05-12 05:59:50','display',''),(1517,'print_partial',614,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:operative_note].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n\r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo2.png\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colonoscopy</h4>\r\n<div id=\"374-F4742866987\"><strong>General</strong></div>\r\n<div id=\"operative_date\">\r\n  <label>Operative date :</label>\r\n  <div>11-05-2015</div>\r\n</div>\r\n<div id=\"operative_setting\">\r\n  <label>Operative setting * :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"radio\" name=\"update_operative_setting\" id=\"update_operative_setting_item_0\" value=\"0\" onclick=\"javascript:update_operative_setting_func()\" checked=\"checked\" />\r\n            Elective    </label></td>\r\n          <td><label>\r\n            <input type=\"radio\" name=\"update_operative_setting\" id=\"update_operative_setting_item_1\" value=\"1\" onclick=\"javascript:update_operative_setting_func()\" />\r\n            Emergency   </label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"emergency_detail\">\r\n  <label>Emergency detail :</label>\r\n  <div></div>\r\n</div>\r\n<div id=\"374-F0006820128\"></div>\r\n<div id=\"374-F5570385737\"><strong>Surgeons</strong></div>\r\n<div id=\"surgeon\">\r\n  <label>Surgeon :</label>\r\n  <div>NA</div>\r\n</div>\r\n<div id=\"sg_type\">\r\n  <label>sg type :</label>\r\n  <div></div>\r\n</div>\r\n<div id=\"surgeon_2\">\r\n  <label>Surgeon 2 :</label>\r\n  <div>NA</div>\r\n</div>\r\n<div id=\"sg_type_2\">\r\n  <label>sg type 2 :</label>\r\n  <div></div>\r\n</div>\r\n<div id=\"surgeon_3\">\r\n  <label>Surgeon 3 :</label>\r\n  <div>NA</div>\r\n</div>\r\n<div id=\"sg_type_3\">\r\n  <label>sg type 3 :</label>\r\n  <div></div>\r\n</div>\r\n<div id=\"374-F9870629967\"></div>\r\n<div id=\"assistant_1\">\r\n  <label>Assistant :</label>\r\n  <div>NA</div>\r\n</div>\r\n<div id=\"as_type\">\r\n  <label>as type :</label>\r\n  <div></div>\r\n</div>\r\n<div id=\"assistant_2\">\r\n  <label>Assistant 2 :</label>\r\n  <div>NA</div>\r\n</div>\r\n<div id=\"as_type_2\">\r\n  <label>as type 2 :</label>\r\n  <div></div>\r\n</div>\r\n<div id=\"assistant_3\">\r\n  <label>Assistant 3 :</label>\r\n  <div>NA</div>\r\n</div>\r\n<div id=\"as_type_3\">\r\n  <label>as type 3 :</label>\r\n  <div></div>\r\n</div>\r\n<div id=\"other_assistant\">\r\n  <label>Other assistant :</label>\r\n</div>\r\n<div id=\"374-F0764009194\"></div>\r\n<div id=\"anesthesia\">\r\n  <label>Anesthesia :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_anesthesia_item_\" id=\"update_anesthesia_item_0\" value=\"0\" onclick=\"javascript:update_anesthesia_func()\" />\r\n            SAB</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_anesthesia_item_\" id=\"update_anesthesia_item_1\" value=\"1\" onclick=\"javascript:update_anesthesia_func()\" />\r\n            GA</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_anesthesia_item_\" id=\"update_anesthesia_item_2\" value=\"2\" onclick=\"javascript:update_anesthesia_func()\" />\r\n            LA</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_anesthesia_item_\" id=\"update_anesthesia_item_3\" value=\"3\" onclick=\"javascript:update_anesthesia_func()\" />\r\n            Epidural</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"anesthesiologist\">\r\n  <label>Anesthesiologist * :</label>\r\n  wewe</div>\r\n<div id=\"scrub_nurse\">\r\n  <label>Scrub nurse :</label>\r\n</div>\r\n<div id=\"374-F0209893206\"></div>\r\n<div id=\"operative_time_start_at\">\r\n  <label>Operative Start at :</label>\r\n  <div>14:22</div>\r\n</div>\r\n<div id=\"operative_time_stop_at\">\r\n  <label>Operative Stop at * :</label>\r\n  <div>00:10</div>\r\n</div>\r\n<div id=\"total_operative\">\r\n  <label>Total operative time :</label>\r\n</div>\r\n<div id=\"blood_loss\">\r\n  <label>Blood loss (cc.) : </label>\r\n  0</div>\r\n<div id=\"374-F2121997459\"><strong>Transfusion</strong></div>\r\n<div id=\"prc\">\r\n  <label>PRC (unit) : </label>\r\n  0</div>\r\n<div id=\"ffp\">\r\n  <label>FFP (unit) : </label>\r\n  0</div>\r\n<div id=\"platelet\">\r\n  <label>Platelet (unit) : </label>\r\n  0</div>\r\n<div id=\"position\">\r\n  <label>Position :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_position_item_\" id=\"update_position_item_0\" value=\"1\" onclick=\"javascript:update_position_func()\" />\r\n            Lithotomy</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_position_item_\" id=\"update_position_item_1\" value=\"2\" onclick=\"javascript:update_position_func()\" />\r\n            Prone</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_position_item_\" id=\"update_position_item_2\" value=\"3\" onclick=\"javascript:update_position_func()\" />\r\n            Lateral decubitus</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"374-F5992573170\"><strong>Diagnosis</strong></div>\r\n<div id=\"type_of_operation\">\r\n  <label>Type of operation :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_type_of_operation_item_\" id=\"update_type_of_operation_item_0\" value=\"1\" onclick=\"javascript:update_type_of_operation_func()\" />\r\n            Hemorrhoidectomy</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_type_of_operation_item_\" id=\"update_type_of_operation_item_1\" value=\"2\" onclick=\"javascript:update_type_of_operation_func()\" />\r\n            Lateral internal sphincterotomy(LIS)</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_type_of_operation_item_\" id=\"update_type_of_operation_item_2\" value=\"3\" onclick=\"javascript:update_type_of_operation_func()\" />\r\n            Perianal abscess drainage procedure</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_type_of_operation_item_\" id=\"update_type_of_operation_item_3\" value=\"4\" onclick=\"javascript:update_type_of_operation_func()\" />\r\n            Fistula procedure</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_type_of_operation_item_\" id=\"update_type_of_operation_item_4\" value=\"5\" onclick=\"javascript:update_type_of_operation_func()\" />\r\n            Other</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"374-F3538303481\"><strong>Hemorrhoidectomy</strong></div>\r\n<div id=\"symptoms\">\r\n  <label>Symptoms :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_symptoms_item_\" id=\"update_symptoms_item_0\" value=\"0\" onclick=\"javascript:update_symptoms_func()\" />\r\n            Internal hemorrhoid</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_symptoms_item_\" id=\"update_symptoms_item_1\" value=\"1\" onclick=\"javascript:update_symptoms_func()\" />\r\n            External hemorrhoid</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_symptoms_item_\" id=\"update_symptoms_item_2\" value=\"2\" onclick=\"javascript:update_symptoms_func()\" />\r\n            Bleeding</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_symptoms_item_\" id=\"update_symptoms_item_3\" value=\"3\" onclick=\"javascript:update_symptoms_func()\" />\r\n            Pain</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_symptoms_item_\" id=\"update_symptoms_item_4\" value=\"4\" onclick=\"javascript:update_symptoms_func()\" />\r\n            Prolapse</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_symptoms_item_\" id=\"update_symptoms_item_5\" value=\"5\" onclick=\"javascript:update_symptoms_func()\" />\r\n            Thrombosis</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_symptoms_item_\" id=\"update_symptoms_item_6\" value=\"6\" onclick=\"javascript:update_symptoms_func()\" />\r\n            Others</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"symptoms_grade\">\r\n  <div>\r\n    <table border=\"0\">\r\n      <tbody>\r\n        <tr>\r\n          <td>Grade : </td>\r\n          <td><table>\r\n            <tbody>\r\n              <tr>\r\n                <td><label>\r\n                  <input type=\"radio\" name=\"update_symptoms_grade\" id=\"update_symptoms_grade_item_0\" value=\"1\" onclick=\"javascript:update_symptoms_grade_func()\" />\r\n                  grade I    </label></td>\r\n                <td><label>\r\n                  <input type=\"radio\" name=\"update_symptoms_grade\" id=\"update_symptoms_grade_item_1\" value=\"2\" onclick=\"javascript:update_symptoms_grade_func()\" />\r\n                  grade II    </label></td>\r\n