of_tract\">\r\n  <div>\r\n    <table border=\"0\">\r\n      <tbody>\r\n        <tr>\r\n          <td>Maturation of tract </td>\r\n          <td><table>\r\n            <tbody>\r\n              <tr>\r\n                <td><label>\r\n                  <input type=\"radio\" name=\"update_maturation_of_tract\" id=\"update_maturation_of_tract_item_0\" value=\"1\" onclick=\"javascript:update_maturation_of_tract_func()\" checked=\"checked\" />\r\n                  No    </label></td>\r\n                <td><label>\r\n                  <input type=\"radio\" name=\"update_maturation_of_tract\" id=\"update_maturation_of_tract_item_1\" value=\"2\" onclick=\"javascript:update_maturation_of_tract_func()\" />\r\n                  Yes   </label></td>\r\n              </tr>\r\n              <tr></tr>\r\n            </tbody>\r\n          </table></td>\r\n          <td valign=\"top\"> </td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"penetration_to_anal_mucosa\">\r\n  <div>\r\n    <table border=\"0\">\r\n      <tbody>\r\n        <tr>\r\n          <td>Penetration to anal mucosa </td>\r\n          <td><table>\r\n            <tbody>\r\n              <tr>\r\n                <td><label>\r\n                  <input type=\"radio\" name=\"update_penetration_to_anal_mucosa\" id=\"update_penetration_to_anal_mucosa_item_0\" value=\"1\" onclick=\"javascript:update_penetration_to_anal_mucosa_func()\" checked=\"checked\" />\r\n                  No    </label></td>\r\n                <td><label>\r\n                  <input type=\"radio\" name=\"update_penetration_to_anal_mucosa\" id=\"update_penetration_to_anal_mucosa_item_1\" value=\"2\" onclick=\"javascript:update_penetration_to_anal_mucosa_func()\" />\r\n                  Yes   </label></td>\r\n              </tr>\r\n              <tr></tr>\r\n            </tbody>\r\n          </table></td>\r\n          <td valign=\"top\"> </td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"slip_of_suture\">\r\n  <div>\r\n    <table border=\"0\">\r\n      <tbody>\r\n        <tr>\r\n          <td>Slip of suture </td>\r\n          <td><table>\r\n            <tbody>\r\n              <tr>\r\n                <td><label>\r\n                  <input type=\"radio\" name=\"update_slip_of_suture\" id=\"update_slip_of_suture_item_0\" value=\"1\" onclick=\"javascript:update_slip_of_suture_func()\" checked=\"checked\" />\r\n                  No    </label></td>\r\n                <td><label>\r\n                  <input type=\"radio\" name=\"update_slip_of_suture\" id=\"update_slip_of_suture_item_1\" value=\"2\" onclick=\"javascript:update_slip_of_suture_func()\" />\r\n                  Yes   </label></td>\r\n              </tr>\r\n              <tr></tr>\r\n            </tbody>\r\n          </table></td>\r\n          <td valign=\"top\"> </td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"seton_insertion\">\r\n  <div>\r\n    <table border=\"0\">\r\n      <tbody>\r\n        <tr>\r\n          <td>Seton insertion </td>\r\n          <td><table>\r\n            <tbody>\r\n              <tr>\r\n                <td><label>\r\n                  <input type=\"radio\" name=\"update_seton_insertion\" id=\"update_seton_insertion_item_0\" value=\"1\" onclick=\"javascript:update_seton_insertion_func()\" />\r\n                  No    </label></td>\r\n                <td><label>\r\n                  <input type=\"radio\" name=\"update_seton_insertion\" id=\"update_seton_insertion_item_1\" value=\"2\" onclick=\"javascript:update_seton_insertion_func()\" checked=\"checked\" />\r\n                  Yes   </label></td>\r\n              </tr>\r\n              <tr></tr>\r\n            </tbody>\r\n          </table></td>\r\n          <td valign=\"top\"> </td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"management_of_external_opening\">\r\n  <label>Management of external opening :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_management_of_external_opening_item_\" id=\"update_management_of_external_opening_item_0\" value=\"1\" onclick=\"javascript:update_management_of_external_opening_func()\" />\r\n            Core out fistulectomy</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_management_of_external_opening_item_\" id=\"update_management_of_external_opening_item_1\" value=\"2\" onclick=\"javascript:update_management_of_external_opening_func()\" />\r\n            Curettage</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"374-F8401204931\"></div>\r\n<div id=\"confirmation_of_fistula_tract_after_lift\">\r\n  <label>Confirmation of fistula tract after LIFT :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"radio\" name=\"update_confirmation_of_fistula_tract_after_lift\" id=\"update_confirmation_of_fistula_tract_after_lift_item_0\" value=\"1\" onclick=\"javascript:update_confirmation_of_fistula_tract_after_lift_func()\" checked=\"checked\" />\r\n            No    </label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"radio\" name=\"update_confirmation_of_fistula_tract_after_lift\" id=\"update_confirmation_of_fistula_tract_after_lift_item_1\" value=\"2\" onclick=\"javascript:update_confirmation_of_fistula_tract_after_lift_func()\" />\r\n            Yes   </label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"confirmation_of_fistula_yes\">\r\n  <label>Confirmation of fistula yes :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_confirmation_of_fi