   <td><label>\r\n            <input type=\"checkbox\" name=\"update_ligation_check_item_\" id=\"update_ligation_check_item_0\" value=\"1\" onclick=\"javascript:update_ligation_check_func()\" />\r\n            Single</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_ligation_check_item_\" id=\"update_ligation_check_item_1\" value=\"2\" onclick=\"javascript:update_ligation_check_func()\" />\r\n            Double</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_ligation_check_item_\" id=\"update_ligation_check_item_2\" value=\"3\" onclick=\"javascript:update_ligation_check_func()\" />\r\n            Simple</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_ligation_check_item_\" id=\"update_ligation_check_item_3\" value=\"4\" onclick=\"javascript:update_ligation_check_func()\" />\r\n            Closure intersphincteric defect</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"suture_suture\"></div>\r\n<div id=\"suture_suture_no\"></div>\r\n<div id=\"suture_check\">\r\n  <label>Suture check :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_suture_check_item_\" id=\"update_suture_check_item_0\" value=\"1\" onclick=\"javascript:update_suture_check_func()\" />\r\n            Single</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_suture_check_item_\" id=\"update_suture_check_item_1\" value=\"2\" onclick=\"javascript:update_suture_check_func()\" />\r\n            Double</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_suture_check_item_\" id=\"update_suture_check_item_2\" value=\"3\" onclick=\"javascript:update_suture_check_func()\" />\r\n            Simple</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_suture_check_item_\" id=\"update_suture_check_item_3\" value=\"4\" onclick=\"javascript:update_suture_check_func()\" />\r\n            Closure intersphincteric defect</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"374-F8410113350\"></div>\r\n<div id=\"core_suture\">\r\n  <label>Core suture :</label>\r\n</div>\r\n<div id=\"core_suture_no\">\r\n  <label>Core suture no :</label>\r\n</div>\r\n<div id=\"lift_more_detail\">\r\n  <label>More detail :</label>\r\n</div>\r\n<div id=\"374-F8606061805\"><strong>Advancement flap</strong></div>\r\n<div id=\"advancement_flap_detail\">\r\n  <label>Advancement flap detail :</label>\r\n</div>\r\n<div id=\"374-F6765082293\"><strong>Other procedure</strong></div>\r\n<div id=\"other_procedure\">\r\n  <label>Other procedure :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_other_procedure_item_\" id=\"update_other_procedure_item_0\" value=\"1\" onclick=\"javascript:update_other_procedure_func()\" />\r\n            Hanley\'s fistulotomy</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_other_procedure_item_\" id=\"update_other_procedure_item_1\" value=\"2\" onclick=\"javascript:update_other_procedure_func()\" />\r\n            Seton insertion</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_other_procedure_item_\" id=\"update_other_procedure_item_2\" value=\"3\" onclick=\"javascript:update_other_procedure_func()\" />\r\n            Others i.e. fibrin plug, fibrin glue, Laser</label></td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"374-F0497066188\"></div>\r\n<div id=\"diagnosis_other\">\r\n  <label>Diagnosis Other :</label>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2015-05-12 06:01:35','2015-05-12 06:01:35','print_partial',''),(1518,'index',626,2,'<% if false &&@current_role != \'developer\' %>\r\n<%# render :inline=>this.redirect %>\r\n<% else %>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Solution\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <center><b>Welcome to <span style=\"color:#F3790D\">Thai Hip and Knee Joint Registry</b></center><br/>\r\n    <%= render :inline=>this.module %>\r\n    \r\n    \r\n    <a href=\"/taig/registry/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\">\r\n <img width=\"80\" src=\"/esm/taig/registry/thkjrshortform.png\" alt=\"111984\">\r\n</button></a>\r\n\r\n    </div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2015-05-12 06:13:04','2015-05-12 06:13:04','index',''),(1519,'redirect',626,3,'\r\n<% \r\nmodules = @context.get_projects_by_abstract \'ehr.emr\' \r\nmodel = get_model\r\nlogo = nil\r\nre_url = \"../../\\\\#{modules.first.name}/Home/index\".html_safe\r\n\r\n\r\n\r\n%>\r\n<script>\r\n    // alert(\'Hello\');\r\n    window.location = \"<%=re_url%>\";\r\n</script>\r\n<%= link_to modules.first, \"../../\\\\#{modules.first.name}/Home/index\" %>\r\n\r\n\r\n      			\r\n\r\n',NULL,NULL,NULL,'2015-05-12 06:14:19','2015-05-12 06:14:19','redirect',''),(1520,'',614,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:operative_note].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n\r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo2.png\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colonoscopy</h4>\r\n<div id=\"374-F4742866987\"><strong>General</strong></div>\r\n<div id=\"operative_date\">\r\n  <label>Operative date :</label>\r\n  <div>11-05-2015</div>\r\n</div>\r\n<div id=\"operative_setting\">\r\n  <label>Operative setting * :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"radio\" name=\"update_operative_setting\" id=\"update_operative_setting_item_0\" value=\"0\" onclick=\"javascript:update_operative_setting_func()\" checked=\"checked\" />\r\n            Elective    </label></td>\r\n          <td><label>\r\n            <input type=\"radio\" name=\"update_operative_setting\" id=\"update_operative_setting_item_1\" value=\"1\" onclick=\"javascript:update_operative_setting_func()\" />\r\n            Emergency   </label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"emergency_detail\">\r\n  <label>Emergency detail :</label>\r\n  <div></div>\r\n</div>\r\n<div id=\"374-F0006820128\"></div>\r\n<div id=\"374-F5570385737\"><strong>Surgeons</strong></div>\r\n<div style=\"width:100px\" id=\"surgeon\" >\r\n  <label>Surgeon :</label>\r\n  <div>NA</div>\r\n</div>\r\n<div style=\"width:100px\" id=\"sg_type\">\r\n  <label>sg type :</label>\r\n  <div></div>\r\n</div>\r\n<div style=\"width:100px\" id=\"surgeon_2\">\r\n  <label>Surgeon 2 :</label>\r\n  <div>NA</div>\r\n</div>\r\n<div style=\"width:100px\" id=\"sg_type_2\">\r\n  <label>sg type 2 :</label>\r\n  <div></div>\r\n</div>\r\n<div style=\"width:100px\" id=\"surgeon_3\">\r\n  <label>Surgeon 3 :</label>\r\n  <div>NA</div>\r\n</div>\r\n<div style=\"width:100px\" id=\"sg_type_3\">\r\n  <label>sg type 3 :</label>\r\n  <div></div>\r\n</div>\r\n<div id=\"37