lign=\"top\"> </td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"management_of_external_opening\">\r\n  <label>Management of external opening :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_management_of_external_opening_item_\" id=\"update_management_of_external_opening_item_0\" value=\"1\" onclick=\"javascript:update_management_of_external_opening_func()\" />\r\n            Core out fistulectomy</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_management_of_external_opening_item_\" id=\"update_management_of_external_opening_item_1\" value=\"2\" onclick=\"javascript:update_management_of_external_opening_func()\" />\r\n            Curettage</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"374-F8401204931\"></div>\r\n<div id=\"confirmation_of_fistula_tract_after_lift\">\r\n  <label>Confirmation of fistula tract after LIFT :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"radio\" name=\"update_confirmation_of_fistula_tract_after_lift\" id=\"update_confirmation_of_fistula_tract_after_lift_item_0\" value=\"1\" onclick=\"javascript:update_confirmation_of_fistula_tract_after_lift_func()\" checked=\"checked\" />\r\n            No    </label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"radio\" name=\"update_confirmation_of_fistula_tract_after_lift\" id=\"update_confirmation_of_fistula_tract_after_lift_item_1\" value=\"2\" onclick=\"javascript:update_confirmation_of_fistula_tract_after_lift_func()\" />\r\n            Yes   </label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"confirmation_of_fistula_yes\">\r\n  <label>Confirmation of fistula yes :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_confirmation_of_fistula_yes_item_\" id=\"update_confirmation_of_fistula_yes_item_0\" value=\"1\" onclick=\"javascript:update_confirmation_of_fistula_yes_func()\" />\r\n            Probing</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_confirmation_of_fistula_yes_item_\" id=\"update_confirmation_of_fistula_yes_item_1\" value=\"2\" onclick=\"javascript:update_confirmation_of_fistula_yes_func()\" />\r\n            Water injection</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"374-F4645282140\"></div>\r\n<div id=\"fistula_tract_management\">\r\n  <label>Fistula tract management :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_fistula_tract_management_item_\" id=\"update_fistula_tract_management_item_0\" value=\"1\" onclick=\"javascript:update_fistula_tract_management_func()\" />\r\n            Ligation</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_fistula_tract_management_item_\" id=\"update_fistula_tract_management_item_1\" value=\"2\" onclick=\"javascript:update_fistula_tract_management_func()\" />\r\n            Suture ligation</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_fistula_tract_management_item_\" id=\"update_fistula_tract_management_item_2\" value=\"3\" onclick=\"javascript:update_fistula_tract_management_func()\" />\r\n            Core out intramuscula part</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"ligation_suture\"></div>\r\n<div id=\"ligation_suture_no\"></div>\r\n<div id=\"ligation_check\">\r\n  <label>Ligation check :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_ligation_check_item_\" id=\"update_ligation_check_item_0\" value=\"1\" onclick=\"javascript:update_ligation_check_func()\" />\r\n            Single</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_ligation_check_item_\" id=\"update_ligation_check_item_1\" value=\"2\" onclick=\"javascript:update_ligation_check_func()\" />\r\n            Double</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_ligation_check_item_\" id=\"update_ligation_check_item_2\" value=\"3\" onclick=\"javascript:update_ligation_check_func()\" />\r\n            Simple</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_ligation_check_item_\" id=\"update_ligation_check_item_3\" value=\"4\" onclick=\"javascript:update_ligation_check_func()\" />\r\n            Closure intersphincteric defect</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"suture_suture\"></div>\r\n<div id=\"suture_suture_no\"></div>\r\n<div id=\"suture_check\">\r\n  <label>Suture check :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_suture_check_item_\" id=\"update_suture_check_item_0\" value=\"1\" onclick=\"javascript:update_suture_check_func()\" />\r\n            Single</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_suture_check_item_\" id=\"update_suture_check_item_1\" value=\"2\" onclick=\"javascript:update_suture_check_func()\" />\r\n            Double</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_suture_check_item_\" id=\"update_suture_check_item_2\" value=\"3\" onclick=\"javascript:update_suture_check_func()\" />\r\n            Simple</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_suture_check_item_\" id=\"update_suture_check_item_3\" value=\"4\" onclick=\"javascript:update_suture_check_func()\" />\r\n            Closure intersphincteric defect</label></td>\r\n        </tr>\r\n        <tr></tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"374-F8410113350\"></div>\r\n<div id=\"core_suture\">\r\n  <label>Core suture :</label>\r\n</div>\r\n<div id=\"core_suture_no\">\r\n  <label>Core suture no :</label>\r\n</div>\r\n<div id=\"lift_more_detail\">\r\n  <label>More detail :</label>\r\n</div>\r\n<div id=\"374-F8606061805\"><strong>Advancement flap</strong></div>\r\n<div id=\"advancement_flap_detail\">\r\n  <label>Advancement flap detail :</label>\r\n</div>\r\n<div id=\"374-F6765082293\"><strong>Other procedure</strong></div>\r\n<div id=\"other_procedure\">\r\n  <label>Other procedure :</label>\r\n  <div>\r\n    <table>\r\n      <tbody>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_other_procedure_item_\" id=\"update_other_procedure_item_0\" value=\"1\" onclick=\"javascript:update_other_procedure_func()\" />\r\n            Hanley\'s fistulotomy</label></td>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_other_procedure_item_\" id=\"update_other_procedure_item_1\" value=\"2\" onclick=\"javascript:update_other_procedure_func()\" />\r\n            Seton insertion</label></td>\r\n        </tr>\r\n        <tr>\r\n          <td><label>\r\n            <input type=\"checkbox\" name=\"update_other_procedure_item_\" id=\"update_other_procedure_item_2\" value=\"3\" onclick=\"javascript:update_other_procedure_func()\" />\r\n            Others i.e. fibrin plug, fibrin glue, Laser</label></td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n<div id=\"374-F0497066188\"></div>\r\n<div id=\"diagnosis_other\">\r\n  <label>Diagnosis Other :</label>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2015-05-12 06:40:24','2015-05-12 06:40:24','',''),(1521,'imageshow',614,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:operative_note].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n\r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n  width:300px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    width:300px;\r\n    \r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n\r\n\r\n\r\n\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<h4>Sign :</h4>\r\n\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-12 06:40:45','2015-05-12 06:40:45','imageshow',''),(1523,'destroy',666,3,'<%\r\n    models = get_model\r\n    m_appointment = models[:appointment]\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient  = ehr_models[:patient]\r\n    m_patient_module = ehr_models[:patient_module]\r\n    patient = nil\r\n    rs_pm = nil\r\n    rs_app = nil\r\n    rs_ref = nil\r\n    rs_frm = []\r\n    \r\n    rs_tmp = nil\r\n    \r\n    msg = \"Success\"\r\n    if params[:id] and params[:mode] == \'main\'\r\n        rs_pm = m_patient_module.find(params[:id])\r\n        if rs_pm\r\n            rs_ref = m_patient_module.where(:parent_id=>rs_pm.id.to_s)\r\n            rs_app = m_appointment.find(rs_pm[:module_id])\r\n            \r\n            for rs in rs_ref do\r\n                # mname = rs[:module_name].split(\'#\')[1].split(\'_\').map(&:capitalize)*\'\'\r\n                mname = rs[:module_name].split(\'#\')[1]\r\n                # rs_frm.push(mname)\r\n                rs_frm.push(rs)\r\n                \r\n                m_tmp = models[mname].find(rs[:module_id])\r\n                # rs_frm.push(m_tmp)\r\n                m_tmp.destroy if m_tmp\r\n            end\r\n        \r\n            rs_pm.destroy\r\n            rs_app.destroy if rs_app\r\n            rs_ref.destroy_all if rs_ref\r\n            \r\n            msg = \'All records deleted\'\r\n        elsif\r\n            msg = \'ID not found\'\r\n        end\r\n    elsif params[:id] and params[:mode] == \'followup\'\r\n        rs_pm = m_patient_module.find(params[:id])\r\n        if rs_pm\r\n            msg = rs_pm[:module_name].split(\'#\')[1].split(\'_\').join(\' \').capitalize + \" deleted\"\r\n            mname = rs_pm[:module_name].split(\'#\')[1]\r\n            mid = rs_pm[:module_id].to_s\r\n            rs_tmp = models[mname].find(rs_pm[:module_id])\r\n            \r\n            rs_pm.destroy\r\n            rs_tmp.destroy if rs_tmp\r\n        else\r\n            msg = \'Follow up id not found\'\r\n        end\r\n    elsif params[:id] and params[:mode] == \'patient\'\r\n        rs_pm = m_patient_module.where(:patient_id=>params[:id])\r\n        if rs_pm\r\n            for rs in rs_pm\r\n                mname = rs[:module_name].split(\'#\')[1]\r\n                if mname == \'provider\'\r\n                    next\r\n                else\r\n                    m_tmp = models[mname].find(rs[:module_id])\r\n                    rs_frm.push(m_tmp)\r\n                    m_tmp.destroy if m_tmp\r\n                end\r\n            end\r\n            rs_pm.destroy_all\r\n        end\r\n        \r\n        patient = m_patient.find(params[:id])\r\n        patient.destroy if patient\r\n        \r\n        msg = \"All patient data deleted\"\r\n    else\r\n        msg = \'Service not found\'\r\n    end\r\n    \r\n    # rs_pm = m_patient_module.all\r\n  \r\n    return_url = \'index\'\r\n    return_url = params[:return] if params[:return]\r\n\r\n    result = {}\r\n    result[:msg] = msg\r\n    result[:id]  = params[:id]\r\n    result[:return] = return_url\r\n    result[:patient] = patient\r\n    result[:rs_app] = rs_app\r\n    result[:relative] = rs_ref\r\n    result[:rs_pm] = rs_pm\r\n    result[:rs_frm] = rs_frm\r\n    result[:rs_tmp] = rs_tmp\r\n    result[:params] = params\r\n\r\n%>\r\n<%\r\n    if params[:test]\r\n%>\r\n<%= result.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n<script>\r\n    // alert(\'<%= msg %>\');\r\n    window.location = \'<%= return_url.html_safe %>\';\r\n</script>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2015-05-12 07:28:39','2015-05-12 07:28:39','destroy',''),(1524,'create_test',667,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<!--<h3>Create Patient</h3>-->\r\n<strong>Create Patient</strong>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n<div >\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\" >\r\n\r\n<%= render :inline=>this.init %>\r\n<% # params.inspect %>\r\n<%\r\n\r\n    msg = nil\r\n    err = false\r\n\r\n    if request.post?\r\n      \r\n        p = params[:record]\r\n        return_url = params[:return]\r\n        date = Time.now\r\n        if !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        \r\n        # next_service = \"../Patient/create_test?return=\\\\#{return_url}&\".html_safe\r\n        next_service = \"../Home/index\"\r\n        patient = @patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Duplicate HN in database\"\r\n            # next_service += URI.escape(params.collect{|k,v| \"\\\\#{k}=\\\\#{v}\"}.join(\'&\')).html_safe\r\n            err = true\r\n        else\r\n            # msg = \"Success\"\r\n            # next_service = \"../Setting/index\"\r\n            patient = @patient_model.create p\r\n            next_service = \'../Home/patient_record?id=\' + patient.id\r\n          \r\n            if params[:record][:provider]\r\n                m_pm_record = @module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>params[:record][:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>params[:record][:provider]\r\n            end\r\n        end\r\n      \r\n    #   return_url += \'&obj_id=\'+patient.id.to_s\r\n      %>\r\n      <%#params.inspect %>\r\n<script>\r\n    alert(\'<%=msg%>\');\r\n</script>\r\n      <meta http-equiv=\"refresh\" content=\"0; url=<%=next_service%>\" />\r\n      <%\r\n    else\r\n%>\r\n<%= form_for :record , :url=>\'../Patient/create_test\' do |f| %>\r\n<%= f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n<%= f.hidden_field :date, :value=>params[:data][:date] %>\r\n<div class=\"w-box\">\r\n<!--<div id=\"132-F1376173358\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">-->\r\n<div class=\"form-horizontal well\">\r\n<!--<b>Personal Information</b>-->\r\n<p class=\"f_legend\">Personal Information</p>\r\n<!--</div>-->\r\n\r\n<div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n<span class=\"\"><label>Hospital Number <span class=\"f_req\">*</span>  : </label></span>	\r\n<input type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"><span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[hn]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>\r\n</div>\r\n\r\n<div class=\"row-fluid\"></div>\r\n\r\n<div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n<span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n<input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<!--<div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">-->\r\n<!--<span class=\"\"><label>Prefix name : </label></span>	-->\r\n<!--<input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n<!--</div>-->\r\n\r\n<div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n<input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"><span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>\r\n</div>\r\n\r\n<div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n<input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"><span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Birth date : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n\r\n<span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\"><input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"2015-03-08 20:44:27 +0700\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n<script>\r\n	$(\"#data-birth_date\").kendoDatePicker({\r\n		value: \'\',\r\n	});\r\n</script>\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Gender : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n\r\n<select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n<option value=\"1\">Male\r\n</option>\r\n<option value=\"2\">Female\r\n</option>\r\n<option value=\"0\">NA</option></select>\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<%= hidden_field_tag :return, params[:return] %>\r\n<%= f.submit \'Submit\', :class=>\'btn\' %>\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>',NULL,NULL,NULL,'2015-05-12 08:48:52','2015-05-12 08:48:52','create_test',''),(1525,'index_test',666,2,'<%\r\nmodule_name = @current_project.name\r\nif params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\nend\r\nif session[module_name]\r\n	params[:date] = session[module_name][:date]\r\nend\r\nunless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\nend\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    provider = models[:provider].where(:login=>@current_user.login).first\r\n    if provider\r\n       s_provider = provider.id.to_s\r\n    end\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       My Patients\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\'../Home/index\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n            \r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n                \r\n            </div>\r\n            </span>\r\n            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            \r\n            \r\n            <div class=\"field-input\">\r\n                 <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                 \r\n                 <%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>\r\n            </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            <div class=\"field-input\">\r\n            <%\r\n            # Home/patient_record?id=5533e537790f9b01c2000006\r\n                add_patient = \"../Patient/create_test?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n                if s_provider \r\n                    # add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                    add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                end\r\n                \r\n            %>\r\n              \r\n                 <%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>\r\n            </div>\r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        </div>\r\n        <div class=\"row-fluid\"></div>\r\n \r\n<strong>\r\n<%\r\n    rs = []\r\n    if !search_patient and params[:select].nil?\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\").all\r\n    	end\r\n    %>\r\n    <!--ALL : <%= rs.size %>-->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name, :last_name=>s_last_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n        # patients = patient_model.where(criteria).limit(20).all\r\n        patients = patient_model.where(criteria).all\r\n	    # maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}\r\n        # aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     	    rs = module_model.where(:patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\"\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT : <%= rs.size %>-->\r\n    <%\r\n    elsif params[:date]\r\n        require \'date\'\r\n        dddd = Date.parse(params[:date])\r\n	    conds = {:date.gte=>dddd.at_beginning_of_day,:date.lt=>dddd.end_of_day, :module_name=>\"\\\\#{@current_project.name}#provider\"}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n            conds.merge! :module_id=>s_provider \r\n            # conds[:module_id] = s_provider\r\n            # conds[:module_name] = @current_project.name + \"#provider\"\r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n        rs = module_model.where(conds).all\r\n        # aps = ap_model.all(conds)\r\n    	# filter provider\r\n    # 	if s_provider and s_provider != \'\'\r\n     	  #  conds[:module_id] = s_provider\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    #  	else\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    # 	end\r\n    	\r\n    # 	rs = module_model.all(conds)\r\n        # rs = module_model.all\r\n\r\n    %>\r\n    <!--DATE : <%=rs.size%> | <%= conds %>-->\r\n    <%\r\n    end # end if\r\n%>\r\n</strong>\r\n<!--<br/>-->\r\n<!--<br/>-->\r\n<%\r\nm_procedure = models[:procedure].all\r\nmap_proc = {}\r\nfor m in m_procedure do\r\n    map_proc[m.id] = m\r\nend\r\n\r\nm_provider  = models[:provider].all\r\nmap_prov = {}\r\nfor m in m_provider do \r\n    map_prov[m.id.to_s] = m[:name]\r\nend\r\nresult = rs.collect do |i|\r\n    m_patient = patient_model.find(i[:patient_id].to_s)\r\n    \r\n    patient_name = m_patient[:first_name] + \" \" + m_patient[:last_name]\r\n    \r\n    # prov = map_prov[i[:id]]\r\n    m_id = i[:module_id].to_s\r\n    prov = map_prov[m_id]\r\n    \r\n    # prov = nil\r\n    proc_rs = []\r\n    m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    for m in m_ap do\r\n        ap = models[:appointment].find(m[:module_id])\r\n        if ap\r\n            proc_rs.push(map_proc[ap[:procedure]])\r\n        end\r\n    end\r\n    \r\n    proc_txt = \'<center><font color=\"red\">-- Create New --</font></center>\'\r\n    if !proc_rs.empty?\r\n        proc_txt = \'\'\r\n        for x in proc_rs do \r\n            proc_txt += \'<center><div class=\"row-fluid\">\' + x.to_s + \'</div></center> \'\r\n        end\r\n    end\r\n    action = \' \'\r\n    action += link_to(\'Detail\',\"patient_record?id=\\\\#{i[:patient_id]}\",:class=>\'btn btn-info\')\r\n    action += \" \"\r\n    action += link_to(\'\', \"../../www/Patient/edit?id=\\\\#{m_patient.id}&return=\\\\#{request.fullpath}\", :class=>\'splashy-contact_blue_edit\').html_safe\r\n    action += \" \"\r\n    action += link_to(\'\', \"\", :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{m_patient.id}\'); return false;\")\r\n    action += \" \"\r\n    \r\n    {:date=>i[:date], :hn=>m_patient[:hn], :name=>patient_name, :pid=>i[:patient_id], :procedure=>proc_txt, :action=>action, :provider=>prov}\r\nend\r\ncount = 1\r\nlabels = {:no=>\'No.\', :date=>\'Date\', :hn=>\'HN\', :name=>\'Patient Name\', :procedure=>\'Previous Procedure\', :action=>\'Action\'}\r\nfield_select = [:no, :date, :hn, :name, :procedure, :action]\r\n\r\nif @current_role == \'developer\'\r\n    labels[:provider] = \'Provider\'\r\n    field_select.insert(4, :provider)\r\nend\r\nresult = result.sort_by{|i| i[:date]}.reverse\r\n%>\r\n        <div id=\"result-panel\" style=\"padding:10px\">\r\n            <%= tabular :data=>result, :model=>field_select, :labels=>labels do |row,out|\r\n                    out[0] = count.to_s+\".\"\r\n                    count+=1\r\n                 out\r\n             end\r\n            %>\r\n        </div>\r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function confirm_delete(id) {\r\n        // destroy?id=\\\\#{m_patient.id}&mode=patient&return=\\\\#{request.fullpath}\r\n<%\r\n    destroy_url = \"destroy?mode=patient&id=\".html_safe\r\n    return_url  = \"&return=\\\\#{request.fullpath}\".html_safe\r\n%>\r\n        if (confirm(\"Do you want to delete patient data ?\") == true) {\r\n            if (confirm(\"All of patient data will be lost\") == true) {\r\n                url = \"<%= destroy_url %>\" + id + \"<%= return_url %>\";\r\n                window.location = url;\r\n            }\r\n        }\r\n    }\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<!--\r\n<div class=\"alert \">\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n</div>\r\n-->\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2015-05-12 09:01:01','2015-05-12 09:01:01','index_test',''),(1527,'list',668,3,'<style>\r\n/*!\r\n * FullCalendar v1.6.0 Stylesheet\r\n * Docs & License: http://arshaw.com/fullcalendar/\r\n * (c) 2013 Adam Shaw\r\n */\r\n\r\n\r\n.fc {\r\n    direction: ltr;\r\n	text-align: left;\r\n	}\r\n	\r\n.fc table {\r\n	border-collapse: collapse;\r\n	border-spacing: 0;\r\n	}\r\n	\r\nhtml .fc,\r\n.fc table {\r\n	font-size: 1em;\r\n	}\r\n	\r\n.fc td,\r\n.fc th {\r\n	padding: 0;\r\n	vertical-align: top;\r\n	}\r\n\r\n\r\n\r\n/* Header\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-header td {\r\n	white-space: nowrap;\r\n	}\r\n\r\n.fc-header-left {\r\n	width: 25%;\r\n	text-align: left;\r\n	}\r\n	\r\n.fc-header-center {\r\n	text-align: center;\r\n	}\r\n	\r\n.fc-header-right {\r\n	width: 25%;\r\n	text-align: right;\r\n	}\r\n	\r\n.fc-header-title {\r\n	display: inline-block;\r\n	vertical-align: top;\r\n	}\r\n	\r\n.fc-header-title h2 {\r\n	margin-top: 0;\r\n	white-space: nowrap;\r\n	}\r\n	\r\n.fc .fc-header-space {\r\n	padding-left: 10px;\r\n	}\r\n	\r\n.fc-header .fc-button {\r\n	margin-bottom: 1em;\r\n	vertical-align: top;\r\n	}\r\n	\r\n/* buttons edges butting together */\r\n\r\n.fc-header .fc-button {\r\n	margin-right: -1px;\r\n	}\r\n	\r\n.fc-header .fc-corner-right,  /* non-theme */\r\n.fc-header .ui-corner-right { /* theme */\r\n	margin-right: 0; /* back to normal */\r\n	}\r\n	\r\n/* button layering (for border precedence) */\r\n	\r\n.fc-header .fc-state-hover,\r\n.fc-header .ui-state-hover {\r\n	z-index: 2;\r\n	}\r\n	\r\n.fc-header .fc-state-down {\r\n	z-index: 3;\r\n	}\r\n\r\n.fc-header .fc-state-active,\r\n.fc-header .ui-state-active {\r\n	z-index: 4;\r\n	}\r\n	\r\n	\r\n	\r\n/* Content\r\n------------------------------------------------------------------------*/\r\n	\r\n.fc-content {\r\n	clear: both;\r\n	}\r\n	\r\n.fc-view {\r\n	width: 100%; /* needed for view switching (when view is absolute) */\r\n	overflow: hidden;\r\n	}\r\n	\r\n	\r\n\r\n/* Cell Styles\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-widget-header,    /* <th>, usually */\r\n.fc-widget-content {  /* <td>, usually */\r\n	border: 1px solid #ddd;\r\n	}\r\n	\r\n.fc-state-highlight { /* <td> today cell */ /* TODO: add .fc-today to <th> */\r\n	background: #fcf8e3;\r\n	}\r\n	\r\n.fc-cell-overlay { /* semi-transparent rectangle while dragging */\r\n	background: #bce8f1;\r\n	opacity: .3;\r\n	filter: alpha(opacity=30); /* for IE */\r\n	}\r\n	\r\n\r\n\r\n/* Buttons\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-button {\r\n	position: relative;\r\n	display: inline-block;\r\n	padding: 0 .6em;\r\n	overflow: hidden;\r\n	height: 1.9em;\r\n	line-height: 1.9em;\r\n	white-space: nowrap;\r\n	cursor: pointer;\r\n	}\r\n	\r\n.fc-state-default { /* non-theme */\r\n	border: 1px solid;\r\n	}\r\n\r\n.fc-state-default.fc-corner-left { /* non-theme */\r\n	border-top-left-radius: 4px;\r\n	border-bottom-left-radius: 4px;\r\n	}\r\n\r\n.fc-state-default.fc-corner-right { /* non-theme */\r\n	border-top-right-radius: 4px;\r\n	border-bottom-right-radius: 4px;\r\n	}\r\n\r\n/*\r\n	Our default prev/next buttons use HTML entities like &lsaquo; &rsaquo; &laquo; &raquo;\r\n	and we\'ll try to make them look good cross-browser.\r\n*/\r\n\r\n.fc-text-arrow {\r\n	margin: 0 .1em;\r\n	font-size: 2em;\r\n	font-family: \"Courier New\", Courier, monospace;\r\n	vertical-align: baseline; /* for IE7 */\r\n	}\r\n\r\n.fc-button-prev .fc-text-arrow,\r\n.fc-button-next .fc-text-arrow { /* for &lsaquo; &rsaquo; */\r\n	font-weight: bold;\r\n	}\r\n	\r\n/* icon (for jquery ui) */\r\n	\r\n.fc-button .fc-icon-wrap {\r\n	position: relative;\r\n	float: left;\r\n	top: 50%;\r\n	}\r\n	\r\n.fc-button .ui-icon {\r\n	position: relative;\r\n	float: left;\r\n	margin-top: -50%;\r\n	*margin-top: 0;\r\n	*top: -50%;\r\n	}\r\n	\r\n/*\r\n  button states\r\n  borrowed from twitter bootstrap (http://twitter.github.com/bootstrap/)\r\n*/\r\n\r\n.fc-state-default {\r\n	background-color: #f5f5f5;\r\n	background-image: -moz-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: -webkit-gradient(linear, 0 0, 0 100%, from(#ffffff), to(#e6e6e6));\r\n	background-image: -webkit-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: -o-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: linear-gradient(to bottom, #ffffff, #e6e6e6);\r\n	background-repeat: repeat-x;\r\n	border-color: #e6e6e6 #e6e6e6 #bfbfbf;\r\n	border-color: rgba(0, 0, 0, 0.1) rgba(0, 0, 0, 0.1) rgba(0, 0, 0, 0.25);\r\n	color: #333;\r\n	text-shadow: 0 1px 1px rgba(255, 255, 255, 0.75);\r\n	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2), 0 1px 2px rgba(0, 0, 0, 0.05);\r\n	}\r\n\r\n.fc-state-hover,\r\n.fc-state-down,\r\n.fc-state-active,\r\n.fc-state-disabled {\r\n	color: #333333;\r\n	background-color: #e6e6e6;\r\n	}\r\n\r\n.fc-state-hover {\r\n	color: #333333;\r\n	text-decoration: none;\r\n	background-position: 0 -15px;\r\n	-webkit-transition: background-position 0.1s linear;\r\n	   -moz-transition: background-position 0.1s linear;\r\n	     -o-transition: background-position 0.1s linear;\r\n	        transition: background-position 0.1s linear;\r\n	}\r\n\r\n.fc-state-down,\r\n.fc-state-active {\r\n	background-color: #cccccc;\r\n	background-image: none;\r\n	outline: 0;\r\n	box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.15), 0 1px 2px rgba(0, 0, 0, 0.05);\r\n	}\r\n\r\n.fc-state-disabled {\r\n	cursor: default;\r\n	background-image: none;\r\n	opacity: 0.65;\r\n	filter: alpha(opacity=65);\r\n	box-shadow: none;\r\n	}\r\n\r\n	\r\n\r\n/* Global Event Styles\r\n------------------------------------------------------------------------*/\r\n	 \r\n.fc-event {\r\n	border: 1px solid #3a87ad; /* default BORDER color */\r\n	background-color: #3a87ad; /* default BACKGROUND color */\r\n	color: #fff;               /* default TEXT color */\r\n	text-shadow: 0 -1px 0 rgba(0, 0, 0, 0.25);\r\n	font-size: .85em;\r\n	cursor: default;\r\n	}\r\n\r\na.fc-event {\r\n	text-decoration: none;\r\n	}\r\n	\r\na.fc-event,\r\n.fc-event-draggable {\r\n	cursor: pointer;\r\n	}\r\n	\r\n.fc-rtl .fc-event {\r\n	text-align: right;\r\n	}\r\n\r\n.fc-event-inner {\r\n	width: 100%;\r\n	overflow: hidden;\r\n	}\r\n	\r\n.fc-event-time,\r\n.fc-event-title {\r\n	padding: 0 1px;\r\n	}\r\n	\r\n.fc .ui-resizable-handle {\r\n	display: block;\r\n	position: absolute;\r\n	z-index: 99999;\r\n	overflow: hidden; /* hacky spaces (IE6/7) */\r\n	font-size: 300%;  /* */\r\n	line-height: 50%; /* */\r\n	}\r\n	\r\n	\r\n	\r\n/* Horizontal Events\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-event-hori {\r\n	border-width: 1px 0;\r\n	margin-bottom: 1px;\r\n	}\r\n\r\n.fc-ltr .fc-event-hori.fc-event-start,\r\n.fc-rtl .fc-event-hori.fc-event-end {\r\n	border-left-width: 1px;\r\n	border-top-left-radius: 3px;\r\n	border-bottom-left-radius: 3px;\r\n	}\r\n\r\n.fc-ltr .fc-event-hori.fc-event-end,\r\n.fc-rtl .fc-event-hori.fc-event-start {\r\n	border-right-width: 1px;\r\n	border-top-right-radius: 3px;\r\n	border-bottom-right-radius: 3px;\r\n	}\r\n	\r\n/* resizable */\r\n	\r\n.fc-event-hori .ui-resizable-e {\r\n	top: 0           !important; /* importants override pre jquery ui 1.7 styles */\r\n	right: -3px      !important;\r\n	width: 7px       !important;\r\n	height: 100%     !important;\r\n	cursor: e-resize;\r\n	}\r\n	\r\n.fc-event-hori .ui-resizable-w {\r\n	top: 0           !important;\r\n	left: -3px       !important;\r\n	width: 7px       !important;\r\n	height: 100%     !important;\r\n	cursor: w-resize;\r\n	}\r\n	\r\n.fc-event-hori .ui-resizable-handle {\r\n	_padding-bottom: 14px; /* IE6 had 0 height */\r\n	}\r\n	\r\n	\r\n	\r\n/* Reusable Separate-border Table\r\n------------------------------------------------------------*/\r\n\r\ntable.fc-border-separate {\r\n	border-collapse: separate;\r\n	}\r\n	\r\n.fc-border-separate th,\r\n.fc-border-separate td {\r\n	border-width: 1px 0 0 1px;\r\n	}\r\n	\r\n.fc-border-separate th.fc-last,\r\n.fc-border-separate td.fc-last {\r\n	border-right-width: 1px;\r\n	}\r\n	\r\n.fc-border-separate tr.fc-last th,\r\n.fc-border-separate tr.fc-last td {\r\n	border-bottom-width: 1px;\r\n	}\r\n	\r\n.fc-border-separate tbody tr.fc-first td,\r\n.fc-border-separate tbody tr.fc-first th {\r\n	border-top-width: 0;\r\n	}\r\n	\r\n	\r\n\r\n/* Month View, Basic Week View, Basic Day View\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-grid th {\r\n	text-align: center;\r\n	}\r\n\r\n.fc .fc-week-number {\r\n	width: 22px;\r\n	text-align: center;\r\n	}\r\n\r\n.fc .fc-week-number div {\r\n	padding: 0 2px;\r\n	}\r\n	\r\n.fc-grid .fc-day-number {\r\n	float: right;\r\n	padding: 0 2px;\r\n	}\r\n	\r\n.fc-grid .fc-other-month .fc-day-number {\r\n	opacity: 0.3;\r\n	filter: alpha(opacity=30); /* for IE */\r\n	/* opacity with small font can sometimes look too faded\r\n	   might want to set the \'color\' property instead\r\n	   making day-numbers bold also fixes the problem */\r\n	}\r\n	\r\n.fc-grid .fc-day-content {\r\n	clear: both;\r\n	padding: 2px 2px 1px; /* distance between events and day edges */\r\n	}\r\n	\r\n/* event styles */\r\n	\r\n.fc-grid .fc-event-time {\r\n	font-weight: bold;\r\n	}\r\n	\r\n/* right-to-left */\r\n	\r\n.fc-rtl .fc-grid .fc-day-number {\r\n	float: left;\r\n	}\r\n	\r\n.fc-rtl .fc-grid .fc-event-time {\r\n	float: right;\r\n	}\r\n	\r\n	\r\n\r\n/* Agenda Week View, Agenda Day View\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-agenda table {\r\n	border-collapse: separate;\r\n	}\r\n	\r\n.fc-agenda-days th {\r\n	text-align: center;\r\n	}\r\n	\r\n.fc-agenda .fc-agenda-axis {\r\n	width: 50px;\r\n	padding: 0 4px;\r\n	vertical-align: middle;\r\n	text-align: right;\r\n	white-space: nowrap;\r\n	font-weight: normal;\r\n	}\r\n\r\n.fc-agenda .fc-week-number {\r\n	font-weight: bold;\r\n	}\r\n	\r\n.fc-agenda .fc-day-content {\r\n	padding: 2px 2px 1px;\r\n	}\r\n	\r\n/* make axis border take precedence */\r\n	\r\n.fc-agenda-days .fc-agenda-axis {\r\n	border-right-width: 1px;\r\n	}\r\n	\r\n.fc-agenda-days .fc-col0 {\r\n	border-left-width: 0;\r\n	}\r\n	\r\n/* all-day area */\r\n	\r\n.fc-agenda-allday th {\r\n	border-width: 0 1px;\r\n	}\r\n	\r\n.fc-agenda-allday .fc-day-content {\r\n	min-height: 34px; /* TODO: doesnt work well in quirksmode */\r\n	_height: 34px;\r\n	}\r\n	\r\n/* divider (between all-day and slots) */\r\n	\r\n.fc-agenda-divider-inner {\r\n	height: 2px;\r\n	overflow: hidden;\r\n	}\r\n	\r\n.fc-widget-header .fc-agenda-divider-inner {\r\n	background: #eee;\r\n	}\r\n	\r\n/* slot rows */\r\n	\r\n.fc-agenda-slots th {\r\n	border-width: 1px 1px 0;\r\n	}\r\n	\r\n.fc-agenda-slots td {\r\n	border-width: 1px 0 0;\r\n	background: none;\r\n	}\r\n	\r\n.fc-agenda-slots td div {\r\n	height: 20px;\r\n	}\r\n	\r\n.fc-agenda-slots tr.fc-slot0 th,\r\n.fc-agenda-slots tr.fc-slot0 td {\r\n	border-top-width: 0;\r\n	}\r\n\r\n.fc-agenda-slots tr.fc-minor th,\r\n.fc-agenda-slots tr.fc-minor td {\r\n	border-top-style: dotted;\r\n	}\r\n	\r\n.fc-agenda-slots tr.fc-minor th.ui-widget-header {\r\n	*border-top-style: solid; /* doesn\'t work with background in IE6/7 */\r\n	}\r\n	\r\n\r\n\r\n/* Vertical Events\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-event-vert {\r\n	border-width: 0 1px;\r\n	}\r\n\r\n.fc-event-vert.fc-event-start {\r\n	border-top-width: 1px;\r\n	border-top-left-radius: 3px;\r\n	border-top-right-radius: 3px;\r\n	}\r\n\r\n.fc-event-vert.fc-event-end {\r\n	border-bottom-width: 1px;\r\n	border-bottom-left-radius: 3px;\r\n	border-bottom-right-radius: 3px;\r\n	}\r\n	\r\n.fc-event-vert .fc-event-time {\r\n	white-space: nowrap;\r\n	font-size: 10px;\r\n	}\r\n\r\n.fc-event-vert .fc-event-inner {\r\n	position: relative;\r\n	z-index: 2;\r\n	}\r\n	\r\n.fc-event-vert .fc-event-bg { /* makes the event lighter w/ a semi-transparent overlay  */\r\n	position: absolute;\r\n	z-index: 1;\r\n	top: 0;\r\n	left: 0;\r\n	width: 100%;\r\n	height: 100%;\r\n	background: #fff;\r\n	opacity: .3;\r\n	filter: alpha(opacity=30);\r\n	}\r\n	\r\n.fc .ui-draggable-dragging .fc-event-bg, /* TODO: something nicer like .fc-opacity */\r\n.fc-select-helper .fc-event-bg {\r\n	display: none\\9; /* for IE6/7/8. nested opacity filters while dragging don\'t work */\r\n	}\r\n	\r\n/* resizable */\r\n	\r\n.fc-event-vert .ui-resizable-s {\r\n	bottom: 0        !important; /* importants override pre jquery ui 1.7 styles */\r\n	width: 100%      !important;\r\n	height: 8px      !important;\r\n	overflow: hidden !important;\r\n	line-height: 8px !important;\r\n	font-size: 11px  !important;\r\n	font-family: monospace;\r\n	text-align: center;\r\n	cursor: s-resize;\r\n	}\r\n	\r\n.fc-agenda .ui-resizable-resizing { /* TODO: better selector */\r\n	_overflow: hidden;\r\n	}\r\n	\r\n	\r\n</style>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   records = []\r\n   n = 10 \r\n%>\r\n<%\r\n   \r\n   values = {}\r\n   query=\'\'\r\n   if params[:search]\r\n\r\n        \r\n        query = params[:search][:query]\r\n          keys = []\r\n    \r\n        @patient_doc.list_fields.each_with_index do |f,index| \r\n		    keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        \r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n\r\n                \r\n        ps = @patient_model.all({\'$or\'=>keys}.merge!(dates))\r\n   \r\n        records = []\r\n        for i in ps\r\n            records+= @module_model.where(:patient_id=>i.id,:module_name=>@module_name).all\r\n        end\r\n        count = records.size\r\n        \r\n        \r\n    else\r\n        from_date = nil\r\n        to_date = nil  \r\n          n = @module_model.where(:module_name=>@module_name).count\r\n        rows,offset,page = params[:paginate]\r\n        records = @module_model.where(:module_name=>@module_name).all(:order=>\'created_at desc\',:limit=>20)\r\n    end\r\n\r\n\r\n patients = {}\r\n @patient_model.find(records.collect{|i| i.patient_id}).each do |i|\r\n patients[i.id]=i\r\n end\r\n appointments = {}\r\n @models[:appointment].find(records.collect{|i| i.module_id}).each do |i|\r\n appointments[i.id]=i\r\n end\r\n \r\n title = \'Calendar\'\r\n \r\n if params[:provider_id]\r\n    provider = @models[:provider].find(params[:provider_id])\r\n    title = \"\\#{provider.name}\'s Calendar\"\r\n end\r\n%>\r\n\r\n  <link rel=\"stylesheet\" href=\"/gebo/lib/fullcalendar/fullcalendar_gebo.css\" />\r\n  <div class=\"row-fluid\">\r\n            			<div class=\"span12\">\r\n							<h2 class=\"heading\"><%= title %></h2>\r\n							<div id=\"calendar\"></div>\r\n						</div>\r\n					</div>\r\n\r\n\r\n    	<script src=\"/gebo/lib/fullcalendar/fullcalendar.min.js\"></script>\r\n			<!-- calendar functions -->\r\n			<script src=\"/gebo/lib/fullcalendar/gcal.js\"></script>\r\n<%\r\n   pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\njson_data =   records.collect{|i| \r\nl = %w{#bcdeee}\r\nap = appointments[i.module_id] \r\np = patients[i.patient_id]\r\nif (ap and params[:provider_id]==nil) or (params[:provider_id] and ap.provider.to_s==params[:provider_id].to_s)\r\n     date_d = \'-\'\r\n     date_d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n     date_s = \'-\'\r\n     date_s = ap.date.strftime(\"%Y-%m-%d\")+ap.start.strftime(\" %H:%M\") if ap.date and ap.start\r\n     date_e = \'-\'\r\n     date_e = ap.date.strftime(\"%Y-%m-%d\")+ap.stop.strftime(\" %H:%M\") if ap.date  and ap.stop\r\n     \r\n     \r\n    {\'procedure\'=>pro[ap.procedure],\'date\'=>date_d,\'color\'=>l[rand(4%l.size)],\'title\'=>\"\\#{p.first_name if p } \\#{p.hn if p}\",\'start\'=>date_s,\'end\'=>date_e,\'allDay\'=>false,\'url\'=>\'edit?id=\'+i.id.to_s}  \r\nelse\r\n    nil\r\nend \r\n}.compact\r\n\r\n    \r\n    df =   @models[:day_off].all\r\n \r\n    \r\n    df_list = df.collect{|i|\r\n        pname = \'\'\r\n        p = @models[:provider].find(i.provider)\r\n        pname = p.name if p\r\n        date =  \'-\'\r\n        date = i.date.strftime(\"%Y-%m-%d\") if i.date\r\n        {\'color\'=>\'#ccc\',\'title\'=>\"\\#{i.title} \\#{pname}\",\'start\'=>date,\'allDay\'=>true}\r\n    }\r\n    \r\n    map = {}\r\n    \r\n    for i in json_data\r\n    \r\n    date = i[\'date\']\r\n    p = i[\'procedure\']\r\n    \r\n    map[date] = {} unless map[date]\r\n    map[date][p] = 0  unless map[date][p]\r\n    map[date][p] += 1\r\n    \r\n    end\r\n    \r\n    c_list = []\r\n    map.each_pair do |k,v|\r\n         txt = \'\'\r\n         v.each_pair { |key, value| txt+=\"\\#{key}=\\#{value}   \".html_safe }\r\n         c_list<<{\'color\'=>\'#fcc\',\'title\'=>\"\\#{txt}\",\'start\'=>k,\'allDay\'=>true,\'url\'=>\'/\'}\r\n    end\r\n    \r\n    detail = json_data\r\n    \r\n    json_data = df_list\r\n    \r\n    json_data+= c_list\r\n    \r\n    json_data+= detail if params[:detail]    \r\n%>\r\n<%#df.inspect %>\r\n\r\n<script>\r\n\r\n var refresh_loading = false;\r\n\r\n function refresh_date(start,end,detail,provider_id){\r\n    \r\n        if(refresh_loading==false){\r\n        refresh_loading = true\r\n    \r\n        path = \'data\'\r\n        detail_path = \'data_detail\'\r\n      \r\n        $.ajax({\r\n            url: path ,\r\n            dataType: \'json\',\r\n            data: {\r\n                start: start,\r\n                end: end,\r\n                detail: detail,\r\n                provider_id: provider_id\r\n            },\r\n            success: function(doc) {\r\n             data = eval(doc);\r\n            $(\'#calendar\').fullCalendar(\'removeEvents\');\r\n           \r\n            $.each(data, function(index, event){\r\n            $(\'#calendar\').fullCalendar(\'renderEvent\', event);\r\n            });\r\n            }\r\n            });\r\n            \r\n         $.ajax({\r\n            url: detail_path,\r\n            data: {\r\n                start: start,\r\n                end: end,\r\n                detail: detail,\r\n                provider_id: provider_id\r\n            },\r\n            success: function(doc) {\r\n                $(\'#event-details\').html(doc);\r\n            }\r\n         });\r\n\r\n    refresh_loading=false;\r\n     $(\'#loading\').hide();\r\n        }\r\n    \r\n}\r\n    $(document).ready(function() {\r\n\r\n\r\n\r\n\r\n\r\n        gebo_calendar.regular();\r\n\r\n		//* resize elements on window resize\r\n		var lastWindowHeight = $(window).height();\r\n		var lastWindowWidth = $(window).width();\r\n		$(window).on(\"debouncedresize\",function() {\r\n      \r\n			if($(window).height()!=lastWindowHeight || $(window).width()!=lastWindowWidth){\r\n				lastWindowHeight = $(window).height();\r\n				lastWindowWidth = $(window).width();\r\n				//* rebuild calendar\r\n			}\r\n		});\r\n	});\r\n	\r\n	//* calendar\r\n	gebo_calendar = {\r\n		regular: function() {\r\n			var date = new Date();\r\n			var d = date.getDate();\r\n			var m = date.getMonth();\r\n			var y = date.getFullYear();\r\n			var calendar = $(\'#calendar\').fullCalendar({\r\n				header: {\r\n					left: \'prev,next today\',\r\n					center: \'title\',\r\n					right: \'month,agendaWeek,agendaDay\'\r\n				},\r\n		\r\n				aspectRatio: 2,\r\n				selectable: true,\r\n				selectHelper: true,\r\n                \r\n      dayClick: function(date, allDay, jsEvent, view) {\r\n      if($(\'#calendar\').fullCalendar( \'getView\').name!=\'month\')\r\n            window.location=\"../DayOff/create?data[date]=\"+date.getFullYear()+\'-\'+(date.getMonth()+1)+\'-\'+date.getDate() +\"&return=../Appointment/index\"\r\n      $(\'#calendar\').fullCalendar( \'changeView\', \'agendaDay\' );\r\n      $(\'#calendar\').fullCalendar( \'gotoDate\', date.getFullYear() ,date.getMonth(), date.getDate()  );\r\n      \r\n       provider_id = \"<%=params[:provider_id]%>\";\r\n      \r\n       refresh_date(date.getTime()/1000,date.getTime()/1000+3600*24-1,true,provider_id);\r\n      \r\n     \r\n      \r\n      },\r\n      viewDisplay: function(view) {\r\n          \r\n\r\n        if(view.name == \'month\')\r\n        { \r\n            $(\'#calendar\').fullCalendar(\'refetchEvents\');\r\n        }\r\n        if(view.name==\'agendaWeek\'){\r\n             $(\'#calendar\').fullCalendar(\'refetchEvents\');\r\n        }\r\n      },\r\n	  select: function(start, end, allDay) {\r\n               \r\n      if(allDay==false){\r\n	        calendar.fullCalendar(\'unselect\');\r\n            window.location=\"create?data[date]=\"+start.getFullYear()+\'-\'+(start.getMonth()+1)+\'-\'+start.getDate()+\"&data[start]=\"+\r\n            start.getHours()+\":\"+start.getMinutes()+\"&data[stop]=\"+end.getHours()+\":\"+end.getMinutes()\r\n      }\r\n               \r\n	  }\r\n      ,\r\n	  editable: false,\r\n	  theme: false,\r\n	  events: function(start, end, callback) {\r\n   \r\n    \r\n      provider_id = \"<%=params[:provider_id]%>\";\r\n    \r\n  \r\n      refresh_date(Math.round(start.getTime() / 1000),Math.round(end.getTime() / 1000),<%=params[:detail]==\'true\'%>,provider_id);\r\n         \r\n\r\n     },\r\n	  loading: function(bool) {\r\n	  if (bool) $(\'#loading\').show();\r\n	  else $(\'#loading\').hide();\r\n	  }\r\n	});\r\n	}\r\n	};\r\n</script>\r\n<div id=\'loading\' style=\'display:none\'>Loading...</div>\r\n\r\n<div id=\"event-details\">\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-12 21:26:55','2015-05-12 21:26:55','list',''),(1528,'auto_logout',689,2,'<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% 12px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n</style>\r\n\r\n<%= render :inline=>this.init %>\r\n<%\r\n    msg = []\r\n    tmp = nil\r\n    suc_msg = nil\r\n    \r\n    if request.post?\r\n        if !params[:account].nil?\r\n            if params[:account][:login_name].empty?\r\n                msg.push(\'Invalid login name\')\r\n            end\r\n            if params[:account][:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if params[:account][:password].empty?\r\n                msg.push(\'No password found\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>params[:account][:login_name]).first\r\n                if m_user\r\n                    msg.push(\'Existing login name\')\r\n                else\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(params[:account][:password], salt)\r\n                    tmp = salt + \'...\' + hashed_password\r\n                    m_user = @ehr_models[:user].create :role=>params[:account][:role], :login=>params[:account][:login_name], :salt=>salt, :hashed_password=>hashed_password, :email=>params[:account][:email], :name=>params[:account][:full_name], :activate=>\"true\"\r\n                    tmp = m_user.id.to_s\r\n                    \r\n                    m_provider = @models[:provider].create :group=>\'default\', :name=>params[:account][:full_name], :login=>params[:account][:login_name], :provider_type=>\'1\'\r\n                    tmp += \'...\' + m_provider.id.to_s\r\n                end\r\n            end\r\n        elsif !params[:profile].nil?\r\n            px = params[:profile]\r\n            if px[:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if px[:cur_password].empty?\r\n                msg.push(\'No password to confirm your change\')\r\n            else\r\n                if px[:new_password] != px[:con_password]\r\n                    msg.push(\"Your confirm password not match the new password. Try again.\")\r\n                end\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>px[:login_name]).first\r\n                salt = m_user[:salt]\r\n                hashed_password = User.encrypt(px[:cur_password], salt)\r\n                if m_user[:hashed_password] == hashed_password\r\n                    if px[:con_password] == px[:new_password] and px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        suc_msg= \"<strong>Success</strong> Your profile has been change\".html_safe\r\n                    elsif px[:con_password] == px[:new_password] and !px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(px[:new_password], salt)\r\n                        m_user[:hashed_password] = hashed_password\r\n                        m_user[:salt] = salt\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your profile and password has been change\".html_safe\r\n                    else\r\n                        msg.push(\'Your new and confirm password does not match\')\r\n                    end\r\n                    \r\n                else\r\n                    msg.push(\'Your current password does not match\')\r\n                end\r\n                # msg.push(px[:login_name])\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n<%#list.inspect%>\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                Setting\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                            <div id=\"accordion1\" class=\"accordion\">\r\n<%\r\n    # check admin or developer role\r\n    if @current_role == \'admin\' or @current_role == \'developer\'\r\n        usr = @ehr_models[:user].all.collect do |i|\r\n            role = @ehr_models[:role].find(i.role)\r\n            role_name = \'undefined\'\r\n            if role\r\n                role_name = role[:name]\r\n            end\r\n            provider = @models[:provider].where(:login=>i.login).first\r\n            \r\n            if provider\r\n                {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :i=>i}\r\n            end\r\n        end\r\n%>\r\n<%\r\n    if !msg.empty?\r\n        for m in msg do\r\n%>\r\n                                <div class=\"alert alert-error\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= m %>\r\n    							</div>\r\n<%\r\n        end\r\n    elsif suc_msg\r\n%>\r\n                                <div class=\"alert alert-success\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= suc_msg %>\r\n    							</div>\r\n<%\r\n    end\r\n%>\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											Manage Account\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse\" id=\"collapseOne1\">\r\n										<div class=\"accordion-inner\">\r\n										    <!--<div id=\"form-panel\" class=\"row-fluid\"><%= link_to \'Add New\', \'add_new?update=form-panel\', :remote=>true, :class=>\'btn\', :style=>\'float:right\' %>-->\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :account, :url=>\"index\", :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Add New Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">no space, special characters</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'member\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:class=>\'btn\', :style=>\'vertical-align: top;\' %></span>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n											<!--<hr/>-->\r\n                                            <div id=\"account\">\r\n											<table class=\"table\">\r\n        										<thead>\r\n        											<tr>\r\n        												<th>No.</th>\r\n        												<th>Login Name</th>\r\n        												<th>Name</th>\r\n        												<th>Role</th>\r\n        												<th>Actions</th>\r\n        											</tr>\r\n        										</thead>\r\n        										<tbody>\r\n        										<% \r\n        										    no = 1\r\n        										    for i in usr.compact do\r\n        										\r\n        										%>\r\n        										    <tr>\r\n        										        <td><%= no %>.</td>\r\n        										        <td><%= i[:login] %></td>\r\n        										        <td><%= i[:provider_name] %></td>\r\n        										        <td><%= i[:role_name] %></td>\r\n        										        <td>\r\n        										            <%= link_to \'\', \'#\', :title=>\'Delete Account\', :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>&nbsp;&nbsp;&nbsp;\r\n        										            <%= link_to \'\', \'#\', :title=>\'Edit Account\', :class=>\'splashy-contact_blue_edit\', :onclick=>\"javascript:confirm_edit(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>\r\n        										        </td>\r\n        										    </tr>\r\n        										<%\r\n        										    no += 1\r\n        										    end\r\n        										%>\r\n        										</tbody>\r\n        									</table>\r\n										</div>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n<%\r\n    end\r\n%>\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											User Profile\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :profile, :class=>\'\', :url=>\"index\" ,:method=>\'POST\' do |f| %>\r\n											<%\r\n											    cur_user = @ehr_models[:user].where(:login=>@current_user.to_s).first\r\n											%>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your information</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\', :value=>@current_user, :disabled=>\'disabled\' %>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\', :value=>cur_user[:name] if cur_user %> \r\n        													<span class=\"help-block\">your account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Password\" class=\"span10\" name=\"[profile]cur_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your information</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Password\" class=\"span10\" name=\"[profile]new_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Password\" class=\"span10\" name=\"[profile]con_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n										</div>\r\n									</div>\r\n								</div>\r\n							</div>\r\n                        \r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<br/>\r\n\r\n<script>\r\n    refresh();\r\n    \r\n    function confirm_delete(uid, pid) {\r\n        if (confirm(\'Are you sure?\') == true) {\r\n<%\r\n            destroy_url = \'destroy?id=\'\r\n%>\r\n            \r\n            url = \"destroy?uid=\" + uid + \"&pid=\" + pid;\r\n            window.location = url;\r\n        }\r\n    }\r\n    \r\n    function confirm_edit(uid, pid) {\r\n        // if (alert(\'Are you sure?\') == true) {\r\n            \r\n        // }\r\n        \r\n    }\r\n\r\n\r\n// // idle.js (c) Alexios Chouchoulas 2009\r\n// // Released under the terms of the GNU Public License version 2.0 (or later).\r\n\r\n// var _API_JQUERY = 1;\r\n// var _API_PROTOTYPE = 2;\r\n// var _api;\r\n\r\n// // var _idleTimeout = 30000;       // 30 seconds\r\n// // var _awayTimeout = 600000;      // 10 minutes\r\n// var _idleTimeout = 10000;   // 10 seconds\r\n// var _awayTimeout = 20000;   // 20s\r\n\r\n// var _idleNow = false;\r\n// var _idleTimestamp = null;\r\n// var _idleTimer = null;\r\n// var _awayNow = false;\r\n// var _awayTimestamp = null;\r\n// var _awayTimer = null;\r\n\r\n// function setIdleTimeout(ms)\r\n// {\r\n//     _idleTimeout = ms;\r\n//     _idleTimestamp = new Date().getTime() + ms;\r\n//     if (_idleTimer != n