ttom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<%\r\n    # map procedure\r\n    models = get_model\r\n    m_procedure = models[:procedure].all\r\n    map_proc = {}\r\n    for m in m_procedure do\r\n        map_proc[m.id.to_s] = {:name=>m[:name], :code=>m[:code]}\r\n    end\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient_module = ehr_models[:patient_module]\r\n    \r\n    pm = m_patient_module.find(params[:id])\r\n    m_ap = m_patient_module.where(:id=>pm[:parent_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\").first\r\n    ap = models[:appointment].find(m_ap[:module_id])\r\n%>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<!--<div id=\"logoleft\"><img src=\"/esm/cusys/thks/รพ.ตร.png\" width=\"150\"/></div>-->\r\n<%= params.inspect %>\r\n</div>\r\n<div id=\"page\">\r\n<!--<h3><%=this.table_name.to_s.humanize%></h3>-->\r\n<h3><%= map_proc[ap[:procedure].to_s][:name] %></h3>\r\n<%= this.display.html_safe %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n</div>\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n<strong>Reported by :</strong>&nbsp;<%= @current_user.login.humanize %><br>\r\n<p></p>\r\n<strong>Printed at :</strong>&nbsp;<%= Time.now %>\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br>\r\n<strong> By :</strong> \r\n<%= @current_user.login.humanize %>\r\n\r\n \r\n</div>\r\n<div class=\"hideprint\">\r\n<%= link_to \'Back\', url(\'index\') %>\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n<script>\r\n    // window.print()\r\n</script>',NULL,NULL,NULL,'2015-05-13 02:47:02','2015-05-13 02:47:02','print_test',''),(1530,'document_name',693,1,'\'pregnancy_report\'',NULL,NULL,NULL,'2015-05-13 08:18:29','2015-05-13 08:18:29',NULL,NULL),(1531,'document_name',694,1,'\'health_facilities\'',NULL,NULL,NULL,'2015-05-13 08:30:24','2015-05-13 08:30:24',NULL,NULL),(1532,'document_name',695,1,'\'preg_02\'',NULL,NULL,NULL,'2015-05-13 09:00:49','2015-05-13 09:00:49',NULL,NULL),(1535,'document_name',697,1,'\'preg_03\'',NULL,NUL