    background-position: center top; \r\n    background-color: white;\r\n    background-size: cover;\r\n    padding: 20px;\r\n    font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\r\n    font-weight: lighter;\r\n    /*font-size: 1em;*/\r\n}\r\n</style>            \r\n</head>\r\n<body class=\"login_page\">\r\n<script src=\"/gebo/js/jquery.min.js\"></script>\r\n<script src=\"/gebo/js/jquery.actual.min.js\"></script>\r\n<script src=\"/gebo/lib/validation/jquery.validate.min.js\"></script>\r\n<script src=\"/gebo/bootstrap/js/bootstrap.min.js\"></script>\r\n<%\r\n	p = {}\r\n	if @current_project \r\n	tp = @current_project.get_params if @current_project \r\n	p = tp if tp\r\n	end\r\n	title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"ESM:Innovation as a Service\"\r\n	bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#eee\"\r\n	logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n%>\r\n\r\n<%\r\n    user = \'\'\r\n	user = params[:user][:login] if params[:user]\r\n%>\r\n<%= form_for :user, :action=>\'login\' do|form|%>\r\n            <center><a href=\"/\">\r\n            <img src=\"/esm/thks/www/content/logo-emr-life.png\" style=\"background-color: white;padding:20px;\" width=\"260\">\r\n            </a><br/><br/>\r\n            </center>\r\n	<div class=\"login_box\" style=\"height:220px;top:0;bottom: 0;left: 0;right: 0;margin: auto;font-size:1.2em\">\r\n		\r\n		<form action=\"dashboard.html\" method=\"post\" id=\"login_form\">\r\n		\r\n			<% if flash[:error] %>\r\n			<div class=\"alert alert-info alert-login\">\r\n				<%= flash[:error] %>\r\n			</div>\r\n			<% else %>\r\n			<div class=\"alert alert-info alert-login\">\r\n				Please login to continue \r\n			</div>\r\n			<% end %>\r\n			\r\n			\r\n	   	\r\n\r\n			\r\n			<div class=\"cnt_b\">\r\n			\r\n					\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\" style=\"height:30px;padding:5px\"><i class=\"icon-user\"></i></span>\r\n						<%= form.text_field \"login\", :size => 20,:id=>\'user_login\',:placeholder=>\"Email or Login ID\",\'data-icon\'=>\"user\",:value=>user%>\r\n					   \r\n					</div>\r\n				</div>\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\" style=\"height:30px;padding:5px\"><i class=\"icon-lock\" ></i></span>\r\n						<%= form.password_field \"password\", :size => 20,:id=>\'user_password\',:placeholder=>\"Password\",\'data-icon\'=>\"closed-lock\"%>\r\n						\r\n					</div>\r\n				</div>\r\n					<%  unless @current_solution %>\r\n				<span id=\"solution_id_toggle\"><center><a href=\"javascript:$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\">...</a></center></span>	\r\n				<div class=\"formRow\" id=\"solution_id\" style=\"display:none\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-book\"></i></span>\r\n						<%= text_field_tag \"user[esm]\",cookies[:esm], :size => 20,:id=>\'esm\',:placeholder=>\"Solution ID\",\'data-icon\'=>\"settings\"%>\r\n					</div>\r\n				</div>\r\n				<script>\r\n				    $(document).ready(function(){\r\n				<% if cookies[:esm] %>\r\n					$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\r\n				<%  end %>\r\n			  });\r\n				</script>\r\n				\r\n					<% else %>\r\n						<%= form.hidden_field \"esm\", :value=> @current_solution.name %>\r\n						<%= form.hidden_field \"project_id\", :value=> @current_project.id if @current_project%>\r\n					<% end %>\r\n					\r\n					\r\n				<div class=\"formRow clearfix\">\r\n					<label class=\"checkbox\"><input id=\"ck\" name=\'remember\' type=\"checkbox\" /> Remember me</label>\r\n				</div>\r\n			</div>\r\n			<div class=\"btm_b clearfix\" >\r\n				<button class=\"btn btn-inverse pull-right\" type=\"submit\">Sign In</button>\r\n				\r\n				<span class=\"link_reg\"><a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#terms\">Disclaimer</a></span>\r\n				\r\n			</div>  \r\n		</form>\r\n		\r\n		\r\n		\r\n		<div id=\"terms\" class=\"modal hide fade\">\r\n				<div class=\"modal-header\">\r\n					<a class=\"close\" data-dismiss=\"modal\">×</a>\r\n					<h3>Disclaimer</h3>\r\n				</div>\r\n				<div class=\"modal-body\">\r\n					<p>\r\n						The products and the claims made about specific products on or through this site have not been evaluated by clinician and Drug Administration and are not intended to diagnose, treat, cure or prevent disease. The information provided on this site is for informational purposes only and is not intended as a substitute for your physician\'s or other health care professional\'s advice or any information contained on or in any product label or packaging. You should not use the information on this site for diagnosis or treatment of any health problem or for prescription of any medication or other treatment. You should consult with a healthcare professional before starting any diet, exercise or supplementation program, before taking any medication, or if you have or suspect you might have a health \r\n					</p>\r\n				</div>\r\n				<div class=\"modal-footer\">\r\n					<a data-dismiss=\"modal\" class=\"btn\" href=\"#\">Close</a>\r\n				</div>\r\n			</div>\r\n		\r\n	</div>\r\n	\r\n	<div class=\"links_b links_btm clearfix\" >\r\n	\r\n	\r\n	</div>\r\n		\r\n	</div>  \r\n   <% end %>\r\n\r\n    <script>\r\n        $(document).ready(function(){\r\n            \r\n			//* boxes animation\r\n			form_wrapper = $(\'.login_box\');\r\n            $(\'.linkform a,.link_reg a\').on(\'click\',function(e){\r\n				var target	= $(this).attr(\'href\'),\r\n					target_height = $(target).actual(\'height\');\r\n				$(form_wrapper).css({\r\n					\'height\'		: form_wrapper.height()\r\n				});	\r\n				$(form_wrapper.find(\'form:visible\')).fadeOut(400,function(){\r\n					form_wrapper.stop().animate({\r\n                        height	: target_height\r\n                    },500,function(){\r\n                        $(target).fadeIn(400);\r\n                        $(\'.links_btm .linkform\').toggle();\r\n						$(form_wrapper).css({\r\n							\'height\'		: \'\'\r\n						});	\r\n                    });\r\n				});\r\n				e.preventDefault();\r\n			});\r\n			\r\n			//* validation\r\n			$(\'#login_form\').validate({\r\n				onkeyup: false,\r\n				errorClass: \'error\',\r\n				validClass: \'valid\',\r\n				rules: {\r\n					username: { required: true, minlength: 3 },\r\n					password: { required: true, minlength: 3 }\r\n				},\r\n				highlight: function(element) {\r\n					$(element).closest(\'div\').addClass(\"f_error\");\r\n				},\r\n				unhighlight: function(element) {\r\n					$(element).closest(\'div\').removeClass(\"f_error\");\r\n				},\r\n				errorPlacement: function(error, element) {\r\n					$(element).closest(\'div\').append(error);\r\n				}\r\n			});\r\n        });\r\n    </script>\r\n\r\n\r\n		<script type=\"text/javascript\">\r\n	\r\n		try{document.getElementById(\'user_login\').focus();}catch(e){}\r\n		</script>\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-13 15:26:30','2015-05-13 15:26:30','login',''),(1539,'index',699,2,'\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Solution\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <center><b>Welcome to <span style=\"color:#F3790D\"><%= @current_solution[:title] %></b></center><br/>\r\n    <%= render :inline=>this.module %>\r\n</div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n',NULL,NULL,NULL,'2015-05-13 15:29:16','2015-05-13 15:29:16','index',''),(1542,'finding_config',609,1,'{\r\n:name=>\'Double Balloon Enteroscopy\',\r\n:selectors=>{:location=>%w{esophagus stomach duodenum jejunum}, :intervention=>%w{sampling polypectomy clipping bipolar coaptation apc injection_therapy emr esd peg_placement}},\r\n:view=>[\r\n    {   :value=>\'esophagus\',\r\n        :editor_id=>\'finding_1_summary\',\r\n        :report_id=>\'p1\'\r\n    },\r\n    {\r\n        :value=>\'stomach\',\r\n        :editor_id=>\'finding_2_summary\',\r\n        :report_id=>\'p2\'\r\n    },\r\n    {\r\n        :value=>\'duodenum\',\r\n        :editor_id=>\'finding_3_summary\',\r\n        :report_id=>\'p3\'\r\n    },\r\n    {   :value=>\'jejunum\',\r\n        :editor_id=>\'finding_4_summary\',\r\n        :report_id=>\'p4\'\r\n    }\r\n    \r\n],\r\n:data=>[\r\n    {   \r\n        :value=>\'reflux\',\r\n        :dx_id=>\'11\',\r\n        :group=>1\r\n    },\r\n    {   \r\n        :value=>\'hiatal_hernia\',\r\n        :dx_id=>\'12\',\r\n        :group=>1\r\n    },\r\n    {   \r\n        :value=>\'duodenitis\',\r\n        :dx_id=>\'22\',\r\n        :group=>2\r\n    },\r\n    {   \r\n        :value=>\'gastritis\',\r\n        :dx_id=>\'21\',\r\n        :group=>2\r\n    },\r\n    {   \r\n        :value=>\'mass\',\r\n        :dx_id=>\'4\',\r\n    },  \r\n    {   \r\n        :value=>\'varices\',\r\n        :dx_id=>\'51\',\r\n        :group=>3\r\n        \r\n    }, \r\n    {   \r\n        :value=>\'phg\',\r\n        :title=>\'PHG\',\r\n        :dx_id=>\'52\',\r\n        :group=>3\r\n        \r\n    },\r\n    { \r\n        :value=>\'ulcer\',\r\n        :dx_id=>\'3\',\r\n    },\r\n    {   \r\n        :value=>\'polyp\',\r\n        :dx_id=>\'6\'\r\n    },\r\n    {   \r\n        :value=>\'coustic_ingestion\',\r\n        :dx_id=>\'7\',\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'mallory_weiss\',\r\n        :dx_id=>\'8\',\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'ampulla\',\r\n        :dx_id=>\'\',\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'stricture\',\r\n        :dx_id=>\'10\',\r\n        :group=>0\r\n    },\r\n    {\r\n        :value=>\'dieulafoys_lesion\',\r\n        :dx_id=>\'15\',\r\n        :group=>0\r\n    }\r\n]\r\n}',NULL,NULL,NULL,'2015-05-14 03:32:16','2015-05-14 03:32:16','finding_config',''),(1543,'document_name',702,1,'\'patient_details\'',NULL,NULL,NULL,'2015-05-14 03:42:21','2015-05-14 03:42:21',NULL,NULL),(1544,'create',702,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2015-05-14 03:49:42','2015-05-14 03:49:42','create',''),(1545,'form',702,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n    function change_anesthetic() {\r\n        alert(this.val());\r\n    }\r\n    $(function(){\r\n        // $(\'#patient_asa_grade\').hide();\r\n        ${\'#data-anesthetic_types\').change(change_anesthetic);\r\n    });\r\n</script>',NULL,NULL,NULL,'2015-05-14 03:56:50','2015-05-14 03:56:50','form',''),(1546,'display_script',609,4,'<style>\r\n    v{color:blue};\r\n</style>\r\n\r\n\r\n\r\n\r\n<script>\r\n    function inspect_finding(){\r\n        \r\n        \r\n        \r\n        console.log(\"call inspect finding \")\r\n\r\n        update_route();     \r\n\r\n                \r\n        \r\n        \r\n    }\r\n  \r\n</script>\r\n    \r\n<div id=\"finding-div\" style=\"width:500px\"></div>\r\n\r\n<script>\r\n\r\nvar define_inspector = null;\r\n\r\n\r\n$( document ).ready(function() {\r\n\r\nif(define_inspector==null){\r\nconsole.log(\'display script\')\r\ndefine_inspector = true    \r\n\r\ntree.regMonitor(inspect_finding);\r\n\r\nvalues = $(\'#data-findings\').val()\r\nvalues = eval(values).join(\"|\")\r\n            \r\n        \r\n$.ajax({\r\n  url: \"finding_ajax\",\r\n  method: \"POST\",\r\n  data: { values : values, init:true },\r\n  cache: false\r\n})\r\n.done(function( html ) {\r\n\r\n    $( \"#findings\" ).html( html );\r\n});\r\n\r\n}\r\n\r\n});\r\n</script>\r\n\r\n\r\n\r\n<table width=\"550\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n  <td width=\"148\" valign=\"top\"><strong>Type of sedation</strong></td>\r\n  <td width=\"365\" valign=\"top\">\r\n  <span id=\'type_of_sedation-div\' name=\'type_of_sedation\' class=\"report-field\" >...</span>\r\n  </td>\r\n  </tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Type of Drug</strong></td>\r\n  <td valign=\"top\">\r\n  <span id=\'anesthetic_drug_type-div\' name=\'anesthetic_drug_type\' class=\"report-field\" template=\"subtree\" >...</span>\r\n  </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Endoscopic findings</strong></td>\r\n  <td valign=\"top\"><v></v></td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Route</strong></td>\r\n    <td>\r\n                \r\n                <div id=\"oral-route\" class=\"hide\"> \r\n                <b>Oral : </b><br/>\r\n                <li>Number of insertion : <v><span id=\'oral_number_of_insertion-div\'  class=\"report-field\" ></span></v></li>\r\n                <li>Depth of insertion : <v><span id=\'oral_depth_of_insertion-div\'  class=\"report-field\" ></span></v> cm.</li>\r\n                <li>Time use  : <v><span id=\'oral_time_use-div\'  class=\"report-field\" ></span></v> min.<br/></li>\r\n                </div>\r\n                \r\n                <div id=\"anus-route\" class=\"hide\"> \r\n                <b>Anus :</b><br/>\r\n                <li>Number of insertion : <v><span id=\'anus_number_of_insertion-div\'  class=\"report-field\" ></span></v></li>\r\n                <li>Depth of insertion : <v><span id=\'anus_depth_of_insertion-div\'  class=\"report-field\" ></span></v> cm.</li>\r\n                <li>Time use  : <v><span id=\'anus_time_use-div\'  class=\"report-field\" ></span></v> min.</li>\r\n                </div>\r\n                \r\n               <script>\r\n               function update_route(){\r\n                   v = $(\'#data-route\').val()\r\n                   if(v.indexOf(\"1\")!=-1){\r\n                    $(\'#oral-route\').show();\r\n                    $(\'#oral_number_of_insertion-div\').html($(\'#data-oral_number_of_insertion\').val())\r\n                    $(\'#oral_depth_of_insertion-div\').html($(\'#data-oral_depth_of_insertion\').val())\r\n                    $(\'#oral_time_use-div\').html($(\'#data-oral_time_use\').val())\r\n                   }\r\n                   if(v.indexOf(\"2\")!=-1){\r\n                    $(\'#anus-route\').show();  \r\n                    $(\'#anus_number_of_insertion-div\').html($(\'#data-oral_number_of_insertion\').val())\r\n                    $(\'#anus_depth_of_insertion-div\').html($(\'#data-anus_depth_of_insertion\').val())\r\n                    $(\'#anus_time_use-div\').html($(\'#data-anus_time_use\').val())\r\n                   }\r\n               }\r\n                   update_route();\r\n                   \r\n               </script>\r\n    </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Esophagus</strong></td>\r\n  <td valign=\"top\"><span id=\"p1\" ><v>Loading..</v></span><br/>\r\n  </td>\r\n</tr>\r\n\r\n<tr>\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Stomach</strong></td>\r\n  <td valign=\"top\"><span id=\"p2\"><v>Loading..</v></span><br/>\r\n  </td>\r\n</tr>\r\n\r\n<tr>\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Duodenum</strong></td>\r\n  <td valign=\"top\"><span id=\"p3\"><v>Loading..</v></span><br/>\r\n  </td>\r\n</tr>\r\n\r\n<tr>\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Jejunum</strong></td>\r\n  <td valign=\"top\"><span id=\"p4\"><v>Loading..</v></span><br/>\r\n  </td>\r\n</tr>\r\n\r\n<tr id=\"other-finding-panel\" style=\"display:none\">\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Other</strong></td>\r\n  <td valign=\"top\"><v><span id=\"other-finding-div\"></span></v><br/>\r\n  </td>\r\n</tr>\r\n\r\n\r\n\r\n<tr>\r\n  <td valign=\"top\"><strong>Diagnosis</strong></td>\r\n  \r\n  <td valign=\"top\">\r\n  <span id=\"diagnosis-div\">Loading..</span>\r\n  </td>\r\n</tr>\r\n\r\n<tr>\r\n  <td valign=\"top\"><strong>Intervention</strong></td>\r\n  <td valign=\"top\">\r\n  \r\n    <span id=\'intervention-div\'  >Loading..</span>\r\n     \r\n  </td>\r\n</tr>\r\n\r\n<tr>\r\n  <td valign=\"top\"><strong>Complications</strong></td>\r\n  <td valign=\"top\">\r\n       <span id=\'complications-div\' name=\'complications\' class=\"report-field\" >No</span>\r\n\r\n       <span id=\'complication-div\' name=\'complication_type\' class=\"report-field\" template=\"subtree\">...</span>\r\n         \r\n </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Comment</strong></td>\r\n  <td valign=\"top\">\r\n  \r\n       <span id=\'comment-div\' name=\'comment\' class=\"report-field-x\" >Loading..</span>\r\n\r\n </td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-14 04:14:50','2015-05-14 04:14:50','display_script',''),(1547,'finding_config',492,1,'{\r\n:name=>\'Sigmoid\',\r\n:validate=>[[\'bowel_preperation_finding\',3] ],\r\n:selectors=>{:location=>%w{colon_sigmoid_colon colon_rectum colon_anus}, \r\n    :intervention=>%w{sampling polypectomy clipping bipolar coaptation apc injection_therapy emr esd stent_placement}},\r\n:view=>[\r\n   \r\n    { \r\n        :value=>\'colon_sigmoid_colon\',\r\n        :editor_id=>\'finding_7_summary\',\r\n        :report_id=>\'p7\'\r\n    },\r\n\r\n    { \r\n        :value=>\'colon_rectum\',\r\n        :editor_id=>\'finding_8_summary\',\r\n        :report_id=>\'p8\'\r\n    },\r\n\r\n    { \r\n        :value=>\'colon_anus\',\r\n        :editor_id=>\'finding_9_summary\',\r\n        :report_id=>\'p9\'\r\n    }\r\n\r\n    \r\n],\r\n:data=>[\r\n    {   \r\n        :value=>\'polyp\',\r\n        :dx_id=>\'1\'\r\n    },\r\n    {   \r\n        :value=>\'diverticulum\',\r\n        :dx_id=>\'2\'\r\n    },\r\n    {   \r\n        :value=>\'hemorrhoid\',\r\n        :dx_id=>\'3\'\r\n    },\r\n    {   \r\n        :value=>\'mass\',\r\n        :dx_id=>\'4\'\r\n    }, \r\n    {   \r\n        :value=>\'ulcer\',\r\n        :dx_id=>\'5\'\r\n    }, \r\n    {   \r\n        :value=>\'angiodysplasia\',\r\n        :dx_id=>\'6\',\r\n        :group=>0\r\n        \r\n    },\r\n    { \r\n        :value=>\'colitis\',\r\n        :dx_id=>\'7\',\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'pseudomelanosis_coli\',\r\n        :dx_id=>\'8\',\r\n        :group=>0\r\n    },\r\n    {\r\n        :value=>\'dieulafoys_lesion\',\r\n        :dx_id=>\'10\',\r\n        :group=>0\r\n    },\r\n    {\r\n        :value=>\'stricture\',\r\n        :dx_id=>\'17\',\r\n        :group=>0\r\n    }\r\n]\r\n}',NULL,NULL,NULL,'2015-05-14 04:16:50','2015-05-14 04:16:50','finding_config',''),(1548,'finding_config',494,1,'{\r\n:name=>\'Push Enteroscopy\',\r\n:selectors=>{:location=>%w{esophagus stomach duodenum jejunum}, :intervention=>%w{sampling polypectomy clipping bipolar coaptation apc injection_therapy emr esd peg_placement}},\r\n:view=>[\r\n    {   :value=>\'esophagus\',\r\n        :editor_id=>\'finding_1_summary\',\r\n        :report_id=>\'p1\'\r\n    },\r\n    {\r\n        :value=>\'stomach\',\r\n        :editor_id=>\'finding_2_summary\',\r\n        :report_id=>\'p2\'\r\n    },\r\n    {\r\n        :value=>\'duodenum\',\r\n        :editor_id=>\'finding_3_summary\',\r\n        :report_id=>\'p3\'\r\n    },\r\n    {\r\n        :value=>\'jejunum\',\r\n        :editor_id=>\'finding_4_summary\',\r\n        :report_id=>\'p4\'\r\n    }\r\n    \r\n],\r\n:data=>[\r\n    {   \r\n        :value=>\'reflux\',\r\n        :dx_id=>\'11\',\r\n        :group=>1\r\n    },\r\n    {   \r\n        :value=>\'hiatal_hernia\',\r\n        :dx_id=>\'12\',\r\n        :group=>1\r\n    },\r\n    {   \r\n        :value=>\'duodenitis\',\r\n        :dx_id=>\'22\',\r\n        :group=>2\r\n    },\r\n    {   \r\n        :value=>\'gastritis\',\r\n        :dx_id=>\'21\',\r\n        :group=>2\r\n    },\r\n    {   \r\n        :value=>\'mass\',\r\n        :dx_id=>\'4\',\r\n    },  \r\n    {   \r\n        :value=>\'varices\',\r\n        :dx_id=>\'51\',\r\n        :group=>3\r\n        \r\n    }, \r\n    {   \r\n        :value=>\'phg\',\r\n        :title=>\'PHG\',\r\n        :dx_id=>\'52\',\r\n        :group=>3\r\n        \r\n    },\r\n    { \r\n        :value=>\'ulcer\',\r\n        :dx_id=>\'3\',\r\n    },\r\n    {   \r\n        :value=>\'polyp\',\r\n        :dx_id=>\'6\'\r\n    },\r\n    {   \r\n        :value=>\'coustic_ingestion\',\r\n        :dx_id=>\'7\',\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'mallory_weiss\',\r\n        :dx_id=>\'8\',\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'ampulla\',\r\n        :dx_id=>\'\',\r\n        :group=>0\r\n    }\r\n]\r\n}',NULL,NULL,NULL,'2015-05-14 04:19:29','2015-05-14 04:19:29','finding_config',''),(1549,'document_name',703,1,'\'patient_detail\'',NULL,NULL,NULL,'2015-05-14 05:02:38','2015-05-14 05:02:38',NULL,NULL),(1550,'form',703,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n',NULL,NULL,NULL,'2015-05-14 05:03:59','2015-05-14 05:03:59','form',''),(1554,'index',704,2,'<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Appointment</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\#{patient.prefix_name} \\#{patient.first_name} \\#{patient.last_name}\",\"../../www/Patient/edit?id=\\#{patient.id}&return=\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\#{visit_type} \\#{indications[i.indication]} \\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\#{patient.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p]<<i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p]<<i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p]<<i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %>\r\n<div class=\"clear\"></div>\r\n </div><br/>',NULL,NULL,NULL,'2015-05-14 06:54:23','2015-05-14 06:54:23','index',''),(1555,'patient_record',704,2,'    <% Time.zone =  get_setting \'time_zone\' %>\r\n    <%\r\n    require \'time_diff\'\r\n    \r\n    date = Time.now.to_datetime\r\n    \r\n    models = get_model\r\n    conf = this.config\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient = ehr_models[:patient]\r\n    m_patient_module = ehr_models[:patient_module]\r\n    \r\n    %>\r\n    \r\n    <style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n    </style>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n    <div class=\"w-box\">\r\n        <div class=\"w-box-header\">\r\n            Patient Medical Records\r\n            <div class=\"pull-right\">\r\n            <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n            </div> \r\n        </div>  \r\n        <div class=\"w-box-content cnt_a\">\r\n            <div style=\"border:0px solid\">\r\n                <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n<%\r\n    # get patient by patient_id\r\n    pid = \'\'\r\n    patient = \'\'\r\n    if params[:id]\r\n        pid = params[:id]\r\n        patient = m_patient.find(pid)\r\n    end\r\n    \r\n    if patient\r\n        birth_date = patient.birth_date \r\n        year = month = day = \'0\'\r\n        if date and birth_date\r\n            t = date-birth_date    \r\n            diff = Time.diff(date, birth_date)\r\n            year = diff[:year]\r\n            month = diff[:month]\r\n            # day = diff[:day]\r\n        end\r\n%>\r\n<!--patient section-->\r\n<div class=\"alert alert-block alert-success\">\r\n    <div class=\"btn left\" style=\"height:100px;width:100px\">\r\n<%\r\n        edit_url = \"../../www/Patient/edit?id=\\\\#{params[:id]}&return=\\\\#{request.fullpath}\".html_safe\r\n        att_model = ehr_models[:attachment]\r\n        if !patient[:picture].empty? and patient[:picture].size > 0 \r\n            pic = att_model.find(patient.picture[-1])\r\n            if pic \r\n%>\r\n<a href=\'<%= edit_url %>\'><%= image_tag pic.path, :height=>100 %></a>\r\n<%     \r\n            end \r\n        elsif\r\n%>\r\n<a href=\'<%= edit_url %>\'><%= image_tag \'/esm/thks/www/content/patient_icon.png\', :height=>100 %></a>\r\n<%\r\n		end \r\n%>\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px;float:left\">\r\n<p>\r\n<b> Patient : </b><v><%= patient.prefix_name %>  <%= patient.first_name %> <%= patient.last_name %></v>\r\n</p>\r\n<p>\r\n<b> Age : </b><v><%= year%> Years <%=month%> Months </v> <!-- | <%= patient[:birth_date] %> -->\r\n</p>\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px:float:left\">\r\n<br/>\r\n<p>\r\n<b> HN : </b><v> <%= patient.hn %></v>\r\n</p>\r\n<p>\r\n<%\r\n        # pg = patient gender\r\n        pg = \'NA\'\r\n        if patient.gender == \'1\'\r\n            pg = \'Male\'\r\n        elsif\r\n            pg = \'Female\'\r\n        end\r\n%>\r\n<b> Gender : </b><v><%=pg%> </v>\r\n</p>\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<%\r\n    elsif # if no patient\r\n%>\r\n<script>\r\n    alert(\'No Paient Found!!!\');\r\n    window.location = \"../Home/index\";\r\n</script>\r\n<%\r\n    end # end patient section\r\n%>\r\n\r\n<% if false %>\r\n<script>\r\n    <%\r\n            url = \'../../www/Patient/search_result?\'\r\n            url += \'&id=54fc51d3790f9b4e56000009\'\r\n    %>      \r\n            $.ajax({\r\n              url: \'<%=url.html_safe%>\',\r\n             success: function(data){\r\n              $(\'#patient\').html(data);  \r\n              }\r\n            });\r\n</script>\r\n<% end %>\r\n\r\n\r\n    <!--Appointment form-->\r\n    <%\r\n    procedures = (models[:procedure]).to_a\r\n    # list = %w{primary-hip-left primary-hip-right primary-knee-left primary-knee-right revision-hip-left revision-hip-right revison-knee-left revision-knee-right}\r\n    \r\n    mprocedures = {}\r\n    for i in procedures\r\n        mprocedures[i.id] = i\r\n    end\r\n    \r\n    tmp_list = []\r\n    tmp_app = nil\r\n    tmp_zam = {}\r\n    all_pm =  m_patient_module.where(:patient_id=>patient.id,:module_name=>\"\\\\#{@current_project.name}#appointment\").to_a\r\n    list = all_pm.collect do |i| \r\n        \r\n        app = models[:appointment].find(i.module_id)\r\n        procedure = mprocedures[app.procedure]\r\n        mrecord = models[procedure.code.to_s]\r\n        mr = m_patient_module.where(:parent_id=>i.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{procedure.code}\").first\r\n        record = nil\r\n        if mr\r\n            record = mrecord.find(mr.module_id)\r\n        end\r\n        follow_ups = []\r\n        \r\n        # zamachita query\r\n        m_main = nil\r\n        m_follow = []\r\n        details = m_patient_module.where(:parent_id=>i.id)\r\n        for j in details do\r\n            if j.module_name == \"\\\\#{@current_project.name}#\\\\#{procedure.code}\"\r\n                m_temp = models[procedure.code.to_s]\r\n                record = m_temp.find(j.module_id)\r\n                \r\n                m_main = j\r\n                m_main[:record] = record\r\n            elsif\r\n                m_name = j.module_name.split(\'#\')[1]\r\n                m_temp = models[m_name]\r\n                record = m_temp.find(j.module_id)\r\n                \r\n                j[:record] = record\r\n                m_follow.push(j)\r\n            end\r\n        end\r\n        \r\n        # temporary var\r\n        tmp_list.push(procedure.id.to_s)\r\n        tmp_app = app\r\n        \r\n        {:id=>i.id,:name=>procedure.name,:record=>record,:mrecord=>mr,:procedure=>procedure,:date=>app.inspect,:main=>i,:follow_ups=>follow_ups,:m_main=>m_main, :m_follow=>m_follow}\r\n        \r\n    end\r\n    \r\n    # listx = procedures.collect do |i| \r\n    #     if tmp_list.index(i.id.to_s).nil?\r\n    #         [i.name, i.id]\r\n    #     end\r\n    # end\r\n    \r\n    listx = procedures.collect{|i| [i.name, i.id]}\r\n    %>\r\n    <%= form_for :data,:url=>\"appointment_create?\" ,:method=>\'GET\' do |f| %>\r\n    <%=hidden_field_tag :patient_id, patient.id.to_s %>\r\n    <%=hidden_field_tag :return, request.fullpath %>\r\n    <%=f.hidden_field :date, :value=>date %>\r\n                    <div class=\"clear\"></div>\r\n                    <div>\r\n                        <h4 style=\"float:left\"><%= @current_project.title %> Recrods</h4>\r\n    <%\r\n    if !tmp_app.nil?\r\n    %>\r\n    <%=f.hidden_field :provider, :value=>tmp_app[:provider] %>\r\n    <%\r\n    else\r\n        provider = models[:provider].where(:login=>@current_user.login).first\r\n        if provider.nil?\r\n            providers = models[:provider].all\r\n            p_select = providers.collect{|i| [i.name,i.id,to_s]}\r\n    %>\r\n                        <span style=\"float:right\">Provider :&nbsp;&nbsp; <%= f.select \'provider\', options_for_select(p_select), :style=>\'width:100px\' %> \r\n                        &nbsp;&nbsp;\r\n    <%\r\n        else\r\n    %>\r\n    <%=f.hidden_field :provider, :value=>provider.id.to_s %>\r\n    <%\r\n        end\r\n    end # provider\r\n    %>\r\n                        <span style=\"float:right\"><%= f.select \'procedure\' ,options_for_select(listx.compact)  %> \r\n                            <%=f.submit \'Add New\',:class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %></span>\r\n                        <div class=\"clear\"></div>\r\n                    </div>\r\n    <% end %>\r\n    <!--End Appointment Form-->\r\n    <!--Start TAB-->\r\n    <%\r\n    # all appointment\r\n    \r\n    \r\n    %>\r\n    <%\r\n    \r\n    z_test = false\r\n    if z_test\r\n    %>\r\n    <!--TEST PANE-->\r\n    <div class=\"row-fluid\"></div>\r\n    <div class=\"alert alert-block alert-warning\">\r\n        LIST.<br/>\r\n        <% for i in list %>\r\n        <%= i[:record].inspect %>\r\n        <hr/>\r\n        <% end %>\r\n        tmp_list <%= tmp_list.size %>. <%= tmp_list %><hr/><%= procedures.collect{|i| i.id} %>\r\n    \r\n    </div>\r\n    <%\r\n    end # end test\r\n    %>\r\n                    <div class=\"clear\"></div>\r\n                    <!--<div class=\"tabbable tabs-left\" style=\"border:1px solid #ccc; -moz-border-radius: 5px; border-radius: 5px;\">-->\r\n                    <div class=\"tabbable\" style=\"border:1px solid #ccc; -moz-border-radius: 5px; border-radius: 5px;\">\r\n                        <ul class=\"nav nav-tabs\" style=\"background:#F4F4F4; -moz-border-radius: 5px;border-radius: 5px;\">\r\n                            <li class=\"active\" >\r\n                                <a href=\"#tab_dashboard\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >Dashboard</a>\r\n                            </li>\r\n                            <!--More TAB-->\r\n                            <% for i in list do %>\r\n                            <li class=\"\">\r\n                                <a href=\"#tab_<%=i[:id]%>\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >\r\n                                    <%=i[:name]%><br/>\r\n                                </a>\r\n                            </li>\r\n                            <% end %>\r\n                        </ul>\r\n   \r\n                        <!--<div class=\"tab-content\" style=\"width:640px;border:0px solid;float:left; clear:none;margin-left:-20px;\">-->\r\n                        <div class=\"tab-content\">\r\n                            <div class=\"tab-pane  <%= \'active\' if true %>\" style=\"border:0px solid;\" id=\"tab_dashboard\">\r\n                                <br/>\r\n                                <h3>Dashboard</h3>\r\n                                <div class=\"row-fluid\"><br/></div>\r\n    <%\r\n    if list.size == 0\r\n    %>\r\n                                Welcome\r\n    <%\r\n    elsif\r\n    %>\r\n                                Welcome :)\r\n    <%\r\n    end\r\n    %>\r\n                            </div>\r\n    <!--More TAB Content-->\r\n                            <% for i in list do %>\r\n                            <div class=\"tab-pane\" style=\"border:0px solid;\" id=\"tab_<%= i[:id] %>\">\r\n                                <br/>\r\n                                <div class=\"row-fluid\">\r\n                                    <h3><%= i[:name] %></h3>\r\n    <%\r\n        mname = i[:procedure].code.split(\'_\').map(&:capitalize).join(\'\')\r\n        mr = i[:m_main]\r\n        show = \"\"\r\n        if mr\r\n            show = link_to(\'\',\"../\\\\#{mname}/print?id=\\\\#{mr.id}&return=\\\\#{request.fullpath}#tab_\\\\#{i[:id]}\",:title=>\'Print\', :target=>\'_blank\', :class=>\'splashy-printer\', :style=>\'padding-right:5px\')\r\n            show += link_to(\"\", \"../\\\\#{mname}/edit?id=\\\\#{mr.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}#tab_\\\\#{i[:id]}\",:title=>\'Edit\', :class=>\'splashy-document_a4_edit\', :style=>\'padding-right:5px\')\r\n            # show += \' \'\r\n        else\r\n            show =  link_to(\'\',\"../\\\\#{mname}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\",:title=>\'Create\', :class=>\'splashy-document_a4_add\')\r\n        end\r\n        show += link_to(\'\', \"\", :title=>\'Delete operation\', :class=>\'splashy-document_a4_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{i[:id]}\'); return false;\")\r\n    %>\r\n                                    <div style=\"float:right;margin-top:-30px\"><%# show %>\r\n                                        <%= show %>\r\n                                    </div>\r\n                                </div>\r\n    <% if mr %>\r\n                                <font size=\"1\" style=\"color:gray\">Created at <%= i[:m_main][:record][:created_at].strftime(\"%d/%m/%Y\") %> | Last Updated at <%= i[:m_main][:record][:updated_at].strftime(\"%d/%m/%Y\") %> </font>\r\n                                <hr/>\r\n                                <!--Operation Date : <%= i[:m_main][:record][:operation_date] %>-->\r\n    <% elsif %>\r\n                                <font size=\"1\" style=\"color:gray\">No operation available </font>\r\n                                <hr/>\r\n                                <!--Create Operation-->\r\n    <% end %>\r\n                                <div style=\"margin-left:20px\"></div>\r\n                                <div class=\"row-fluid\">\r\n    <% \r\n        if mr \r\n            today = Time.now\r\n            dd = Date.parse(i[:m_main][:record][:delivery_date].to_s)\r\n            # dd = today\r\n            # rm = distance_of_time_in_words(today, rm)\r\n    %>\r\n                                    Remaining About <%=rm = distance_of_time_in_words(today, dd) %> \r\n                                    <br/>\r\n                                    <!--(Delivery date : <%= dd %>)-->\r\n    <%  else %>\r\n                                    Create New\r\n    <% end %>\r\n                                </div>\r\n                                <!--<div class=\"alert alert-info\">-->\r\n    \r\n    <%\r\n        form_service = \"PregnancyFollow\"\r\n        c_link = \"../\\\\#{form_service}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\"\r\n        if mr\r\n            mr_form = mr[:module_name]\r\n            m_follow = i[:m_follow].collect{|i| [i.id, i[:module_name], i[:record]]}\r\n            f_link = {}\r\n            for j in m_follow do\r\n                f_link[j[2].id] = [j[0], j[1]]\r\n            end\r\n            labels = {:date=>\'Date\', :weight=>\'Weight\', :bp=>\'BP\', :symptoms=>\'Symptoms\', :note=>\'Note\'}\r\n            m_labels = [:date, :weight, :bp, :symptoms, :note]\r\n    %>\r\n                                    <hr/>\r\n                                    <div style=\"float:left\"><strong><font size=\"3\">Follow up</font></strong></div>\r\n                                    <%= link_to \'Create\', c_link, :style=>\'float:right;margin-top:10px\', :class=>\'btn btn-small btn-success\' %>\r\n                                    <div class=\"row-fluid\"></div>\r\n                                    <%= tabular :data=> m_follow.collect{|j| j[2]}, :labels=>labels, :model=>m_labels do |row, out|\r\n                                        l = f_link[row.id]\r\n                                        link_ext = l[1].split(\'#\')[1].split(\'_\').map(&:capitalize).join(\'\')\r\n                                        # out[0] = \"\\\\#{(row.period.to_i)} m\"\r\n                                        # out[1] = row[:created_at].strftime(\"%d-%m-%y\")\r\n                                        \r\n                                        show = link_to(\"E\", \"../\\\\#{link_ext}/edit?id=\\\\#{l[0]}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-mini btn-info\')\r\n                                        show += \' \'\r\n                                        show += link_to(\'P\',\"../\\\\#{link_ext}/print?id=\\\\#{l[0]}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'btn btn-mini\')\r\n                                        out << show\r\n        \r\n                                        out\r\n                                    end %>\r\n\r\n\r\n\r\n    <%\r\n        end\r\n    %>\r\n                                    <p/><p/>\r\n    \r\n    \r\n    <%\r\n    if false\r\n        form_service = nil\r\n        if mr\r\n            m_form = mr[:module_name]\r\n            form_service = \"FollowUpHip\"\r\n            if m_form.index(\'knee\')\r\n                form_service = \"FollowUpKnee\"\r\n            end\r\n            c_link = \"../\\\\#{form_service}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\"\r\n            \r\n            m_follow = i[:m_follow].collect{|i| [i.id, i[:module_name], i[:record]]}.sort{|a,b| a[2][:period].to_f<=>b[2][:period].to_f}\r\n            f_link = {}\r\n            for j in m_follow do\r\n                f_link[j[2].id] = [j[0], j[1]]\r\n            end\r\n    %>\r\n                                    <hr/>\r\n                                    <div style=\"float:left\"><strong><font size=\"3\">Follow up Old</font></strong></div>\r\n                                    <%= link_to \'Create\', c_link, :style=>\'float:right;margin-top:10px\', :class=>\'btn btn-small btn-success\' %>\r\n                                    <div class=\"row-fluid\"></div>\r\n    <!--Follow up table -->\r\n    <%= tabular :data=> m_follow.collect{|j| j[2]},:labels=>{:total_womac_score=>\'WOMAC\',:total_knee_score=>\'Knee Score\'} ,:model=>[:period,:date,:height,:weight,:total_womac_score,:total_knee_score] do |row,out|\r\n        l = f_link[row.id]\r\n        link_ext = l[1].split(\'#\')[1].split(\'_\').map(&:capitalize).join(\'\')\r\n        out[0] = \"\\\\#{(row.period.to_i)} m\"\r\n        out[1] = row[:created_at].strftime(\"%d-%m-%y\")\r\n        \r\n        show = link_to(\"E\", \"../\\\\#{link_ext}/edit?id=\\\\#{l[0]}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-mini btn-info\')\r\n        show += \' \'\r\n        show += link_to(\'P\',\"../\\\\#{link_ext}/print?id=\\\\#{l[0]}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'btn btn-mini\')\r\n        out << show\r\n    \r\n        out\r\n    end%>\r\n    \r\n    <%\r\n        end # end follow up\r\n    end\r\n    %>\r\n                                <!--</div>-->\r\n                            </div>\r\n                            <% end %>\r\n                            \r\n                        </div>\r\n                    </div>\r\n    <!--End TAB-->\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    </div>\r\n    <br/><br/>\r\n<script>\r\n    // alert(\"<%= request.fullpath.html_safe %>\");\r\n    function confirm_delete(id) {\r\n        if (confirm(\'Do you want to delete this operation?\') == true) {\r\n            // ../Appointment/destroy?id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\r\n<%\r\n    destroy_url = \"destroy?mode=main&id=\"\r\n    return_url = \"&return=\" + request.fullpath\r\n%>\r\n            url = \"<%= destroy_url.html_safe %>\" + id + \"<%= return_url.html_safe %>\";\r\n            \r\n            window.location.href = url;\r\n        } \r\n    }\r\n</script>\r\n    \r\n    \r\n    <script>\r\n    $(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n    </script>\r\n     \r\n<!-- charts -->\r\n			<script src=\"/gebo/lib/flot/jquery.flot.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.resize.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.pie.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.curvedLines.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.orderBars.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.multihighlight.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.pyramid.min.js\"></script>\r\n			<script src=\"/gebo/lib/moment_js/moment.min.js\"></script>\r\n			<!-- charts functions -->\r\n			<script src=\"/gebo/js/gebo_charts.js\"></script>\r\n',NULL,NULL,NULL,'2015-05-14 06:55:00','2015-05-14 06:55:00','patient_record',''),(1556,'appointment_create',704,3,'<%\r\n    models = get_model\r\n    m_provider = models[:provider]\r\n    m_appointment = models[:appointment]\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient = ehr_models[:patient]\r\n    m_patient_module = ehr_models[:patient_module]\r\n    \r\n    # create appointment and add to patient_module\r\n    record = m_appointment.create :procedure=>params[:data][:procedure], :provider=>params[:data][:provider], :status=>\'Appointed\', :start=>params[:data][:date], :stop=>params[:data][:date], :date=>Time.now.strftime(\"%Y-%m-%d\")\r\n    m = m_patient_module.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>\"\\#{@current_project.name}#appointment\",:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    \r\n    procedure = (models[:procedure]).find(record.procedure)\r\n    s = procedure[:code].capitalize\r\n    patient = m_patient.find(params[:patient_id])\r\n    \r\n    # params[:next_service] = \"../\\#{s}/create?patient_id=\\#{params[:patient_id]}&record_name=\\#{patient.hn}&parent_id=\\#{m.id}&return=/thks/thks/Home/patient_record?id=\\#{params[:patient_id]}\"\r\n    params[:next_service] = \"../\\#{s}/create?patient_id=\\#{params[:patient_id]}&record_name=\\#{patient.hn}&parent_id=\\#{m.id}&return=\\#{params[:return]}\"\r\n    # params[:appointment_size] = m_appointment.size\r\n    # params[:all_appointment] = m_appointment.to_a\r\n%>\r\n<%# params.to_json.html_safe %>\r\n<script type=\"text/javascript\">\r\n    window.location = \"<%=params[:next_service].html_safe%>\"\r\n</script>',NULL,NULL,NULL,'2015-05-14 06:55:27','2015-05-14 06:55:27','appointment_create',''),(1557,'document_name',706,1,'\'pregnancy_follow\'',NULL,NULL,NULL,'2015-05-14 06:58:19','2015-05-14 06:58:19',NULL,NULL),(1558,'document_name',707,1,'\'kss\'',NULL,NULL,NULL,'2015-05-14 14:51:51','2015-05-14 14:51:51',NULL,NULL),(1559,'document_name',708,1,'\'assessment\'',NULL,NULL,NULL,'2015-05-14 14:53:04','2015-05-14 14:53:04',NULL,NULL),(1560,'document_name',710,1,'\'test\'',NULL,NULL,NULL,'2015-05-16 10:10:14','2015-05-16 10:10:14',NULL,NULL),(1561,'ehr.emr.Document',710,1,'',NULL,NULL,NULL,'2015-05-16 10:11:08','2015-05-16 10:11:08','ehr.emr.document',''),(1562,'export_with_outcome_bk',377,3,'\r\n<%\r\n\r\n    @module_name = @current_project.name+\'#\'+ this.table_name \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n  \r\n\r\n    @document = get_document(this.document_name)\r\n\r\n    doc = @document\r\n\r\n    data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n  \r\n    fields = @document.fields\r\n    fields = fields.collect{|i| [i.column_name,i.name,i.lov_type,i.lov] unless Document.visual_types.index(i.field_type) }.compact!\r\n    fields << \'created_at\'\r\n    fields << \'updated_at\'\r\n    \r\n    d_outcome = get_model(\'outcome\')\r\n    f_outcome = get_document(\'outcome\').fields\r\n    f_outcome = f_outcome.collect{|i| [i.column_name,i.name,i.lov_type,i.lov] unless Document.visual_types.index(i.field_type) }.compact!\r\n   \r\n    d_crrt = get_model(\'crrt_day\')\r\n    f_crrt = get_document(\'crrt_day\').fields\r\n   \r\n    if params[:test] \r\n        result = {}\r\n        result[:export] = []\r\n        result[:tmp] = []\r\n        # result[:field] = @document.fields\r\n        # result[:crrt_day] = @module_model.where(:module_name=>\"\\\\#{@current_project.name}#crrt_day\").all\r\n        \r\n        \r\n        # m = @module_model.where(:module_name=>\"\\\\#{@current_project.name}#outcome\").all\r\n        # result[:tmp] = m\r\n        \r\n        for i in data[0,10]\r\n            @record = i\r\n            tmp = {}\r\n            age = 0\r\n            hn = nil\r\n            \r\n            p = @patient_model.new\r\n            m = @module_model.collection.find(:module_id=>i.id).first\r\n            if m \r\n                \r\n                patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n                if patient\r\n                    bdate = 0\r\n                    bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n                    age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n                    p = patient\r\n                    p[\'record_date\'] = m[\'date\']\r\n                    tmp[:patient] = patient[\'_id\']\r\n                end\r\n            end\r\n            # mx = @module_model.where(:patient_id=>p[\'_id\']).all\r\n            # tmp[:patient_module] = mx\r\n            tmp[:pid] = p[\'_id\']\r\n            tmp[:hn] = p[\'hn\']\r\n            tmp[:name] = p[\'first_name\'] + \' \' + p[\'last_name\']\r\n            tmp[:gender] = p[\'gender\']\r\n            tmp[:age] = age\r\n            tmp[:record_date] = p[\'record_date\']\r\n            \r\n            \r\n            x = tmp.merge(i.attributes)\r\n            \r\n            m = @module_model.where(:module_name=>\"\\\\#{@current_project.name}#outcome\", :patient_id=>p[\'_id\']).first\r\n            if m\r\n                r_outcome = d_outcome.find(m[:module_id])\r\n                x = x.merge(r_outcome.attributes)\r\n                result[:tmp].push(r_outcome)\r\n            end\r\n            \r\n            m = @module_model.where(:module_name=>\"\\\\#{@current_project.name}#crrt_day\", :patient_id=>p[\'_id\']).all\r\n            a = []\r\n            for n in m do\r\n                r_crrt = d_crrt.find(n[:module_id])\r\n                a.push(r_crrt[:mode])\r\n            end\r\n            \r\n            x[:crrt_mode] = a.join(\'|\')\r\n            result[:export].push(x)\r\n        end\r\n%>\r\n<%= result.to_json.html_safe %>\r\n\r\n\r\n<%\r\n    else\r\n%>\r\n<table>\r\n<tr><td>HN</td><td>Name</td><td>Gender</td><td>Birth Date</td><td>Age</td><td>Record date</td>\r\n\r\n<%\r\ntxt_field = \"\"\r\nadd_field = \"\"\r\nfor i in fields \r\n    if i[0] == \'criteria_to_start_rrt\'\r\n        for n in [\'0\',\'1\',\'2\',\'3\',\'4\',\'5\'] do\r\n            add_field += \"<td>\\\\#{i[1]} (\\\\#{n})</td>\"\r\n        end\r\n    elsif i[0] ==  \'cause_of_aki\' or i[0] == \'vasopressor_inotrope\'\r\n        for n in i[3].split(\' \') do\r\n            add_field += \"<td>\\\\#{i[1]} (\\\\#{n})</td>\"\r\n        end\r\n    end\r\n    txt_field += \"<td>\\\\#{i[1]}</td>\"\r\nend\r\nfor i in f_outcome\r\n    if i[0] == \'provider\'\r\n        next\r\n    end\r\n    txt_field += \"<td>\\\\#{i[1]}</td>\"\r\nend\r\nadd_field += \"<td>CRRT Day Mode</td>\"\r\nadd_field += \"<td>CRRT Day Mode All</td>\"\r\n%>\r\n<%= txt_field.html_safe %>\r\n<%= add_field.html_safe %>\r\n</tr>\r\n<% \r\n# for i in data[0,10]\r\nfor i in data\r\n\r\n    @record = i\r\n\r\n    rs_outcome = {}\r\n    rs_mode = nil\r\n    rs_crrt = nil\r\n\r\n    age = 0\r\n    hn = nil\r\n    \r\n    p = @patient_model.new\r\n    m = @module_model.collection.find(:module_id=>i.id).first\r\n    if m \r\n        \r\n        patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n        if patient\r\n            bdate = 0\r\n            bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n            age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n            p = patient\r\n            p[\'record_date\'] = m[\'date\']\r\n        end\r\n        \r\n        d_outcome = get_model(\'outcome\')\r\n        m = @module_model.where(:module_name=>\"\\\\#{@current_project.name}#outcome\", :patient_id=>p[\'_id\']).first\r\n        if m\r\n            rs_outcome = d_outcome.find(m[:module_id])\r\n        end\r\n        \r\n        m = @module_model.where(:module_name=>\"\\\\#{@current_project.name}#crrt_day\", :patient_id=>p[\'_id\']).all\r\n        a = []\r\n        for n in m do\r\n            r_crrt = d_crrt.find(n[:module_id])\r\n            a.push(r_crrt[:mode])\r\n        end\r\n        if !a.empty?\r\n            rs_mode = a[0]\r\n            rs_crrt = a.join(\'|\')\r\n        end\r\n    end\r\n    \r\n    \r\n%>\r\n<tr>\r\n<td><%=p[\'hn\'] %></td><td><%=p[\'first_name\']%> <%=p[\'last_name\']%></td><td><%=p[\'gender\']%></td><td><%=p[\'birth_date\'].strftime(\'%d/%m/%Y\') if p[\'birth_date\'] %></td><td><%=age%></td><td><%=p[\'record_date\'].strftime(\'%d/%m/%Y\') if p[\'record_date\']%></td>\r\n\r\n<%\r\n    @document = doc\r\n    @fields = @document.fields\r\n    \r\n    txt_field = \"\"\r\n    out_field = \"\"\r\n    add_field = \"\"\r\n    for j in fields \r\n        val = render_value j[0]\r\n        if i[j[0]]\r\n            if val.downcase == \'y\' or val.downcase == \'yes\'\r\n                val = \'1\'\r\n            elsif val.downcase == \'n\' or val.downcase == \'no\'\r\n                val = \'0\'\r\n            end\r\n            txt_field += \"<td>\\\\#{val}</td>\"\r\n        else \r\n            txt_field += \"<td>.</td>\"\r\n        end \r\n        if j[0] == \'criteria_to_start_rrt\'\r\n            c = i[j[0]].split(\'|\')\r\n            for n in [\'0\',\'1\',\'2\',\'3\',\'4\',\'5\'] do\r\n                if c.include? n\r\n                    add_field += \"<td>1</td>\"\r\n                else\r\n                    add_field += \"<td>0</td>\"\r\n                end\r\n            end\r\n        elsif j[0] == \'cause_of_aki\' or j[0] == \'vasopressor_inotrope\'\r\n            m = val.split(\',\').map(&:strip)\r\n            for n in j[3].split(\' \') do\r\n                if m.index(n)\r\n                    add_field += \"<td>1</td>\"\r\n                else\r\n                    add_field += \"<td>0</td>\"\r\n                end\r\n            end\r\n        end\r\n    end # end j\r\n    for j in f_outcome\r\n        if j[0] == \'provider\'\r\n            next\r\n        end\r\n        if rs_outcome[j[0]]\r\n            # out_field += \"<td>\\\\#{render_value j[0]}</td>\"\r\n            val = rs_outcome[j[0]].to_s\r\n            if val.downcase == \'survive\'\r\n                val = \"0\"\r\n            elsif val.downcase == \'death\'\r\n                val = \"1\"\r\n            elsif val.downcase == \'unknow\'\r\n                val = \"2\"\r\n            elsif val.downcase == \'y\'\r\n                val = \"1\"\r\n            elsif val.downcase == \'n\'\r\n                val = \"0\"\r\n            end\r\n            out_field += \"<td>\\\\#{val}</td>\"\r\n        else \r\n            out_field += \"<td>.</td>\"\r\n        end \r\n    end\r\n    \r\n    if rs_crrt\r\n        add_field += \"<td>\\\\#{rs_mode}</td>\"\r\n        add_field += \"<td>\\\\#{rs_crrt}</td>\"\r\n    else\r\n        add_field += \"<td>.</td>\"\r\n        add_field += \"<td>.</td>\"\r\n    end\r\n%>\r\n<%= txt_field.html_safe %>\r\n<%= out_field.html_safe %>\r\n<%= add_field.html_safe %>\r\n</tr>\r\n<% end %>\r\n</table>\r\n\r\n<% end %>\r\n  \r\n   \r\n   \r\n   ',NULL,NULL,NULL,'2015-05-18 07:35:01','2015-05-18 07:35:01','export_with_outcome_bk','*'),(1563,'print_patient_record',481,3,'<html>\r\n    <head>\r\n        \r\n        \r\n        <%=include_header %>\r\n        \r\n    </head>\r\n    <body>\r\n\r\n\r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n\r\n    models = get_model\r\n    \r\n    app = models[:appointment].find(params[:id])\r\n    \r\n    mapp = module_model.collection.find(:module_id=>app.id).to_a\r\n    \r\n    patient_id = nil\r\n    patient = nil\r\n    \r\n    if mapp and mapp.size>0\r\n        \r\n        patient_id = mapp[0][\'patient_id\']\r\n        \r\n        patient = patient_model.find(patient_id)\r\n        if patient\r\n           \r\n     \r\n        forms = []\r\n        list = %w{case_record aki summary_form}\r\n        \r\n        for i in list \r\n        \r\n            ls = module_model.collection.find(:module_name=>\"\\\\#{@current_project.name}#\\\\#{i}\",:patient_id=>patient.id).to_a\r\n            forms << {:name=>i,:forms=>ls}\r\n            \r\n        end\r\n       \r\n     \r\n    path = \"/www/Patient/print_partial?id=\\\\#{ mapp[0][\'patient_id\'] }\"\r\n    \r\n                                  \r\n%>\r\n\r\n<%# forms.inspect %>\r\n<%#link_to \'Link\', \"../../www/Patient/print_partial?id=\\\\#{mapp[0][\'patient_id\'] }\" %>\r\n\r\n<%# link_to \"Patient \\\\#{patient_id}\" %>\r\n<%# app.inspect %>\r\n\r\n<div id=\"pid\"></div>\r\n<script>\r\n    \r\n$(function(){\r\n    // alert(\'ejfief\')\r\n   $.ajax(\"<%=path%>\", {\r\n      success: function(data) {\r\n        //   alert(\'doifjdf\')\r\n         $(\'#pid\').html(data);\r\n      }\r\n   });\r\n   \r\n});\r\n   \r\n   \r\n</script>\r\n\r\n<hr/>\r\n<div style=\"page-break-after:always\"> &nbsp;</div>\r\n<% for i in forms %>\r\n\r\n<% for j in i[:forms]\r\n\r\n     path = \"../\\\\#{i[:name].camelize}/print?id=\\\\#{j[\'_id\']}\"\r\n\r\n%>\r\n<div id=\"p<%=j[\'_id\']%>\" style=\"<%= \'page-break-after: always\' if %w{case_record}.index(i[:name])%>\"></div>\r\n\r\n<script>\r\n    \r\n$(function(){\r\n    // alert(\'ejfief\')\r\n   $.ajax(\"<%=path%>\", {\r\n      success: function(data) {\r\n        //   alert(\'doifjdf\')\r\n         $(\'#p<%=j[\'_id\']%>\').html(data);\r\n         \r\n         <% if false and i[:name]==\'summary_form\' %> window.print() <% end %>\r\n         \r\n      }\r\n   });\r\n   \r\n});\r\n   \r\n   \r\n</script>\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<%\r\n\r\n  else%>\r\n  <%=patient_id%>\r\n  <%\r\n            \r\n        end\r\n        \r\n    end\r\n    \r\n    \r\n    %>\r\n\r\n        <%=include_essential %>\r\n<script>\r\n    \r\n</script>\r\n        \r\n    </body>\r\n</html>',NULL,NULL,NULL,'2015-05-18 07:49:36','2015-05-18 07:49:36','print_patient_record',''),(1564,'print_partial',477,3,'\r\n<%\r\n\r\n  rrt_project = @context.get_projects_by_abstract(\'cusys.rrts\')[0]\r\n\r\n\r\n hn = rrt_project.setting(\'hn\')\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n\r\n\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%> <%= hn%></h3>\r\n\r\n<%= this.display.html_safe %><br/>.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2015-05-18 08:07:15','2015-05-18 08:07:15','print_partial',''),(1565,'followup',401,2,'\r\n<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Record</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"search\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-zoom\"></i><br />Search Patient</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<a href=\"followup\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-zoom\"></i><br />Follow up</button></a>\r\n\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n    });\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n.redlink{\r\n    color:red;\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n   # aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n     aps = ap_model.limit(10).all(:order=>\'created_at desc\') \r\n\r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n         #public_id = patient.public_id if patient\r\n         \r\n         mrrt = module_model.collection.find(:parent_id=>m.id,:module_name=>\"\\\\#{@current_project.name}#rrt_report\").first\r\n         rrt_day = 0\r\n         rrt_check = false\r\n         if mrrt\r\n         rrt_check = true\r\n         rrt = models[:rrt_report].find mrrt[\'module_id\'] \r\n         if rrt\r\n             \r\n            rrt_date = rrt.survival_28_days\r\n            if rrt_date\r\n            rrt_day = (rrt_date.to_datetime.to_i - Time.now.to_i) /3600/24\r\n            end\r\n         end\r\n         end\r\n         \r\n         moutcome = module_model.collection.find(:parent_id=>m.id,:module_name=>\"\\\\#{@current_project.name}#outcome\").first\r\n         outcome = false\r\n         if moutcome\r\n         outcome = true\r\n         end\r\n         \r\n         \r\n        rrt_count = module_model.where(\'module_name\'=>\"\\\\#{@current_solution.name}#rrt_report\",:parent_id=>m.id).count\r\n        rrt_alert = \"\"\r\n        if rrt_count == 0\r\n            c_count = module_model.where(\'module_name\'=>\"\\\\#{@current_solution.name}#crrt_day\",:parent_id=>m.id).count\r\n            s_count = module_model.where(\'module_name\'=>\"\\\\#{@current_solution.name}#sled_day\",:parent_id=>m.id).count\r\n            if c_count > 0 or s_count > 0\r\n                rrt_alert = \"<strong><font color=\'red\'>RRT</font></strong>&nbsp;&nbsp;\"\r\n            end\r\n        end       \r\n         \r\n         \r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>\"\\\\#{rrt_alert.html_safe} \"+link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date.strftime(\"%d-%m-%Y\"),:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Waiting\",:class=>\'btn btn-small btn-success\'),\r\n         :day_28=>rrt_day,:outcome=>outcome,:rrt_check=>rrt_check,\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if true}.compact\r\n    \r\n    \r\n    alert = aps.collect{|i| i if i[:day_28]<=7 and !i[:outcome] and i[:rrt_check] }.compact\r\n    \r\n    \r\n    table_model = %w{date hn patient }.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n    \r\n    \r\n%>\r\n\r\n\r\n<%\r\n\r\n     tmp = alert\r\n\r\n%>\r\n\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_05\">    \r\n        <div class=\"w-box-header\">\r\n            28 Days Notification\r\n	    <div class=\"pull-right\"><i class=\"\"><%=tmp.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n       <%= tabular :model=>table_model+[:processing_ctrl],:data=>tmp,:labels=>labels do |row,out|\r\n       \r\n       out[0] += \"&nbsp;&nbsp;<span style=\'color:red\'>\\\\#{row[:day_28]} days</span> \"\r\n        \r\n       out\r\n       end\r\n       \r\n       \r\n       %>\r\n \r\n        \r\n        </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n<%#\"\\\\#{@current_project.name}#appointment\"%>\r\n\r\n \r\n <script>\r\n $(\"#query\").focus();\r\n </script>\r\n <p></p>\r\n \r\n <%\r\n   \r\n   t = Time.now \r\n   \r\n   t2r = t - (365*2*24*3600)\r\n   \r\n \r\n  outcomes = models[:outcome].where(\'hospital_outcome\'=>\'0\',\'day_outcome_date\'=>{\'$gte\'=>t2r.to_mongo}).sort(\'day_outcome_date desc\').to_a\r\n#   outcomes = models[:outcome].where(\'hospital_outcome\'=>{\'$ne\'=>\'death\'}).sort(\'created_at\').to_a\r\n\r\n    pm_map = {}\r\n    patient_map = {}\r\n    parent_map = {}\r\n    patients = []\r\n    parents = []\r\n    \r\n    mrrt_map = {}\r\n    rrts = []\r\n    rrt_map = {}\r\n    \r\n    fws = []\r\n    mfw_map = {}\r\n    fw_map = {}\r\n    \r\n    module_model.where(\'module_id\'=>{\'$in\'=>outcomes.collect{|i| i.id}}).each do |i|\r\n       patients << i.patient_id\r\n       parents << i.parent_id\r\n       pm_map[i.module_id] = i \r\n    end\r\n    \r\n    patient_model.find(patients).each do |i|\r\n       \r\n       patient_map[i.id] = i\r\n        \r\n    end\r\n    \r\n    module_model.find(parents).each do |i|\r\n       \r\n       parent_map[i.id] = i\r\n        \r\n    end\r\n    \r\n    \r\n    module_model.where(:parent_id=>{\'$in\'=>parents},\'module_name\'=>\"rrt#rrt_report\").all.each do |i|\r\n       rrts << i.module_id\r\n       mrrt_map[i.parent_id] = i\r\n    end\r\n    \r\n    models[:rrt_report].find(rrts).each do |i|\r\n       \r\n       rrt_map[i.id] = i\r\n        \r\n    end\r\n    \r\n    \r\n     module_model.where(:parent_id=>{\'$in\'=>parents},\'module_name\'=>\"rrt#follow_up\").all.each do |i|\r\n       fws << i.module_id\r\n       mfw_map[i.parent_id] = [] unless  mfw_map[i.parent_id] \r\n       mfw_map[i.parent_id] << i\r\n    end\r\n    \r\n    models[:rrt_report].find(fws).each do |i|\r\n       \r\n       fw_map[i.id] = i\r\n        \r\n    end\r\n    \r\n\r\n\r\n   ulist= []\r\n   list = outcomes\r\n   list_final = []\r\n#   all live patients     \r\nfor i in list    \r\n\r\n    follow_check = \"\"\r\n    \r\n    # pm = module_model.where(\'module_id\'=>i.id).first   #optimize\r\n    pm = pm_map[i.id]\r\n    \r\n    # apm = module_model.find(pm.parent_id)   #optimize\r\n    apm = parent_map[pm.parent_id]\r\n    \r\n    # app = ap_model.find(apm.module_id)    #optimize\r\n    \r\n    \r\n    # patient = patient_model.find(apm.patient_id)   #optimize\r\n    patient = patient_map[pm.patient_id]   #optimize\r\n    \r\n    \r\n    # m_rrt = module_model.where(\'module_name\'=>\"rrt#rrt_report\",:parent_id=>pm.parent_id).first\r\n    \r\n    m_rrt = mrrt_map[pm.parent_id]\r\n    \r\n    rrt_report = nil\r\n    \r\n    # rrt_report = models[:rrt_report].find(m_rrt.module_id) if m_rrt\r\n    \r\n    rrt_report = rrt_map[m_rrt.module_id]  if m_rrt\r\n    \r\n\r\n    \r\n   \r\n    # if i.hospital_discharge_date\r\n    if rrt_report and rrt_report.rrt_start_date\r\n    \r\n   \r\n    # from_date = i.hospital_discharge_date\r\n    from_date = rrt_report.rrt_start_date\r\n    it = (t.to_i - from_date.to_datetime.to_i)/3600/24/30/3\r\n    \r\n    # cit = module_model.where(\'module_name\'=>\"rrt#follow_up\",:parent_id=>pm.parent_id).to_a\r\n    cit = []\r\n    \r\n    cit = mfw_map[pm.parent_id].collect{|x| fw_map[x.module_id]}.compact  if mfw_map[pm.parent_id]\r\n    \r\n    \r\n    fmap = {}\r\n    \r\n    it.times do |x| \r\n        fmap[x+1] = nil    \r\n    end\r\n    for x in cit\r\n         followup = models[:follow_up].find(x.module_id)\r\n         if followup\r\n            for_month = followup.for_month.to_i\r\n            fmap[for_month] = i\r\n         end\r\n    end\r\n    follow_check = []\r\n    fmap.each_pair do |k,v|\r\n        unless v \r\n            follow_check << link_to((k*3).to_s+\'m\', \'../FollowUp/create?patient_id=\'+patient.id+\'&record_name=\'+patient.hn+\'&parent_id=\'+apm.id,:class=>\'redlink\').html_safe\r\n        end\r\n    end\r\n    follow_check = follow_check.join(\",\")\r\n     \r\n    else\r\n        # follow_check = \"No hospital discharge\" \r\n        follow_check = \"No RRT start date\" \r\n    end\r\n\r\n  \r\n       \r\n    if patient\r\n     \r\n    obj = {:show=>link_to(\'Show\', \"patient_record?id=\\\\#{apm.module_id}\").html_safe,:hn=>patient.hn, :patient=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\",:date=>i.day_outcome_date,:outcome=>i.outcome_day_28, :final_outcome=>i.final_outcome,\r\n    :follow_up=>\"<strong><font color=\'red\'>\\\\#{follow_check}</font></stong>\"}\r\n    #=link_to \'Create Diagnosis\',\"../Diagnosis/create?patient_id=\\\\#{pm.patient_id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.parent_id}&return=\\\\#{return_url}\" ,:class=>bt_class \r\n\r\n\r\n    list_final << obj\r\n      \r\n   end\r\n   end %>\r\n   \r\n   \r\n <div style=\"width:100%;border:0px solid\">\r\n \r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_05\">    \r\n        <div class=\"w-box-header\">\r\n            Follow Up Notification\r\n	    <div class=\"pull-right\"><i class=\"\"><%=list_final.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n\r\n  \r\n  <%= tabular :model=>[:date,:hn, :patient,:follow_up,:show],:data=>list_final do |row,out|\r\n            out\r\n end %>\r\n\r\n </div>\r\n </div>\r\n </div>',NULL,NULL,NULL,'2015-05-18 08:09:48','2015-05-18 08:09:48','followup',''),(1566,'document_name',711,1,'\'post_anesthetic\'',NULL,NULL,NULL,'2015-05-19 15:47:13','2015-05-19 15:47:13',NULL,NULL),(1567,'document_name',712,1,'\'pre_other_1\'',NULL,NULL,NULL,'2015-05-19 15:48:48','2015-05-19 15:48:48',NULL,NULL),(1568,'document_name',713,1,'\'pre_other_2\'',NULL,NULL,NULL,'2015-05-19 15:50:02','2015-05-19 15:50:02',NULL,NULL),(1569,'document_name',714,1,'\'pre_anesthetic\'',NULL,NULL,NULL,'2015-05-19 15:51:01','2015-05-19 15:51:01',NULL,NULL),(1570,'document_name',715,1,'\'test\'',NULL,NULL,NULL,'2015-05-20 18:35:16','2015-05-20 18:35:16',NULL,NULL),(1571,'init',522,4,'<%\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    \r\n    @m_patient = model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    \r\n    @models = get_model\r\n    \r\n    \r\n%>',NULL,NULL,NULL,'2015-05-22 06:28:14','2015-05-22 06:28:14','init',''),(1572,'encrypt',624,3,'<%\r\n    require \'openssl\'\r\n    require \'digest/sha1\'\r\n\r\npk = \'default\'\r\nmsg = \'Hello World\'\r\nif !params.nil?\r\n    if params[:key] and params[:key] != \'\'\r\n        pk = params[:key]\r\n    end\r\n    if params[:msg] and params[:msg] != \'\'\r\n        msg = params[:msg]\r\n    end\r\nend\r\n    \r\n# create the cipher for encrypting\r\nalg = \"des-ede3-cbc\"\r\n# cipher = OpenSSL::Cipher::Cipher.new(\"aes-256-cbc\")\r\ncipher = OpenSSL::Cipher::Cipher.new(alg)\r\ncipher.encrypt\r\n\r\n# you will need to store these for later, in order to decrypt your data\r\nkey = Digest::SHA1.hexdigest(pk)\r\niv = cipher.random_iv\r\n\r\n# load them into the cipher\r\ncipher.key = key\r\ncipher.iv = iv\r\n\r\n# encrypt the message\r\nencrypted = cipher.update(msg)\r\nencrypted << cipher.final\r\nen = \"encrypted: \\\\#{encrypted}\\n\"\r\n\r\n# now we create a sipher for decrypting\r\ncipher = OpenSSL::Cipher::Cipher.new(alg)\r\ncipher.decrypt\r\ncipher.key = key\r\ncipher.iv = iv\r\n\r\n# and decrypt it\r\ndecrypted = cipher.update(encrypted)\r\ndecrypted << cipher.final\r\nde = \"decrypted: \\\\#{decrypted}\\n\"\r\n    \r\n    result = {}\r\n    result[:encrypted] = :x\r\n    result[:decrypted] = :y\r\n%>\r\n<%# result.to_json.html_safe %>\r\n<h3>Using <%= alg %></h3>\r\n<%= en %>\r\n<br/>\r\n<%= de %>\r\n<br/>\r\n',NULL,NULL,NULL,'2015-05-23 03:30:38','2015-05-23 03:30:38','encrypt','*'),(1573,'encrypt_2',624,3,'<h3>Base64</h3>\r\n<%\r\n# be sure to put the following at the top of your code:\r\nrequire \"base64\"\r\nrequire \'uri\'\r\n# after \'the puts data\' in the snippet above do the following:\r\n\r\nrequire \'openssl\'\r\n\r\n  key = \'0123456789abcdef01234567890\' # 24 characters\r\n\r\n  string = \"encrypt this\"\r\n\r\n  des = OpenSSL::Cipher::Cipher.new(\"des-ede3-cbc\")\r\n  des.encrypt # this tells OpenSSL what mode to operate in, here we want to encrypt data\r\n  des.iv = iv = \'01234567\' # 8 characters, hard-coded for now\r\n\r\n  data = des.update(string) + des.final  \r\n  data = iv + data # this way when we randomize our IV it will be available when we need to decrypt the data\r\n%>\r\nMessage : <%= string %><br/>\r\nData : <%= data %><br/>\r\n<%\r\n\r\n    data = Base64.encode64(data)\r\n    data = URI.escape(data, Regexp.new(\"[^\\\\#{URI::PATTERN::UNRESERVED}]\"))\r\n%>\r\nEncrypted : <%= data %><br/>\r\n<%\r\n    encrypted_data = URI.unescape(data)\r\n    encrypted_data = Base64.decode64(data)\r\n%>\r\nEncrypted Data : <%= encrypted_data %><br/>\r\n<%\r\n    des = OpenSSL::Cipher::Cipher.new(\"des-ede3-cbc\")\r\n    des.decrypt\r\n    des.key = key\r\n    encrypted_data = URI.unescape(data)\r\n    encrypted_data = Base64.decode64(data)\r\n    des.iv =  encrypted_data.slice!(0,8) #This gives us our iv back and removes it from the encrypted data\r\n  \r\n    # decrypted = des.update(encrypted_data) + des.final\r\n%>\r\nDecrypted Data :<%= \'decrypted\' %><br/>\r\n<hr/>\r\n<%\r\nsalt  = SecureRandom.random_bytes(64)\r\nkey   = ActiveSupport::KeyGenerator.new(\'password\').generate_key(salt) # => \"\\x89\\xE0\\x156\\xAC...\"\r\ncrypt = ActiveSupport::MessageEncryptor.new(key)                       # => #<ActiveSupport::MessageEncryptor ...>\r\nencrypted_data = crypt.encrypt_and_sign(\'my secret data\')              # => \"NlFBTTMwOUV5UlA1QlNEN2xkY2d6eThYWWh...\"\r\nx = crypt.decrypt_and_verify(encrypted_data)                               # => \"my secret data\"\r\n%>\r\n<%= x %>',NULL,NULL,NULL,'2015-05-23 13:57:23','2015-05-23 13:57:23','encrypt_2','*'),(1574,'enc',666,3,'<%\r\nrequire \'openssl\'\r\nrequire \'digest/sha1\'\r\nrequire \'base64\'\r\n\r\nkey = \'1234567890123456\'\r\nmsg = \'Hello, World\'\r\nif params\r\n    if params[:key]\r\n        key = params[:key]\r\n        if key.length < 16\r\n            z = 16 - key.length\r\n            key = key + (\"Z\" * z)\r\n        end\r\n    end\r\n    if params[:msg]\r\n        msg = params[:msg]\r\n    end\r\nend\r\ntxt = \"\"\r\nalgorithm = \'AES-128-ECB\'\r\n\r\nehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\nehr_models = ehr.get_model\r\nm_user = ehr_models[:user]\r\nuser = m_user.where(:login=>\'chaiwat\').first\r\n\r\nresult = {}\r\nresult[:user] = user\r\nresult[:key] = key\r\nresult[:key64] = Base64.encode64(key).strip\r\nbegin\r\n    cipher = OpenSSL::Cipher::Cipher.new(algorithm)\r\n    cipher.encrypt\r\n    \r\n    # key = Digest::SHA1.hexdigest(key)\r\n    # iv = cipher.random_iv\r\n    \r\n    cipher.key = key \r\n    crypt = cipher.update(msg) + cipher.final()\r\n    crypt_string = (Base64.encode64(crypt))\r\n    result[:encrypt] = crypt_string\r\nrescue Exception => exc\r\n    result[:en_error] = \"Message for the encryption log file for message \\\\#{msg} = \\\\#{exc.message}\"\r\nend\r\n\r\nbegin\r\n    cipher = OpenSSL::Cipher.new(algorithm)\r\n    cipher.decrypt()\r\n    cipher.key = key\r\n    tempkey = Base64.decode64(result[:encrypt])\r\n    crypt = cipher.update(tempkey)\r\n    crypt << cipher.final()\r\n    result[:decrypt] = crypt\r\nrescue Exception => exc\r\n    result[:de_error] = \"Message for the decryption log file for message \\\\#{msg} = \\\\#{exc.message}\"\r\nend\r\n%>\r\n<%= result.to_json.html_safe %>',NULL,NULL,NULL,'2015-05-23 14:16:56','2015-05-23 14:16:56','enc','*'),(1575,'encrypt',666,3,'<%\r\n    require \'openssl\'\r\n    require \'digest/sha1\'\r\n\r\npk = \'default\'\r\nmsg = \'Hello World\'\r\nif !params.nil?\r\n    if params[:key] and params[:key] != \'\'\r\n        pk = params[:key]\r\n    end\r\n    if params[:msg] and params[:msg] != \'\'\r\n        msg = params[:msg]\r\n    end\r\nend\r\n    \r\n# create the cipher for encrypting\r\nalg = \"des-ede3-cbc\"\r\n# cipher = OpenSSL::Cipher::Cipher.new(\"aes-256-cbc\")\r\ncipher = OpenSSL::Cipher::Cipher.new(alg)\r\ncipher.encrypt\r\n\r\n# you will need to store these for later, in order to decrypt your data\r\nkey = Digest::SHA1.hexdigest(pk)\r\niv = cipher.random_iv\r\n\r\n# load them into the cipher\r\ncipher.key = key\r\ncipher.iv = iv\r\n\r\n# encrypt the message\r\nencrypted = cipher.update(msg)\r\nencrypted << cipher.final\r\nen = \"encrypted: \\#{encrypted}\\n\"\r\n\r\n# now we create a sipher for decrypting\r\ncipher = OpenSSL::Cipher::Cipher.new(alg)\r\ncipher.decrypt\r\ncipher.key = key\r\ncipher.iv = iv\r\n\r\n# and decrypt it\r\ndecrypted = cipher.update(encrypted)\r\ndecrypted << cipher.final\r\nde = \"decrypted: \\#{decrypted}\\n\"\r\n    \r\n    result = {}\r\n    result[:encrypted] = :x\r\n    result[:decrypted] = :y\r\n%>\r\n<%# result.to_json.html_safe %>\r\n<h3>Using <%= alg %></h3>\r\n<%= en %>\r\n<br/>\r\n<%= de %>\r\n<br/>\r\n<%= iv %>\r\n',NULL,NULL,NULL,'2015-05-23 16:15:20','2015-05-23 16:15:20','encrypt','*'),(1576,'encode',666,3,'<%\r\n    require \'openssl\'\r\n    require \'digest/sha1\'\r\n    require \'base64\'\r\n    \r\n    algorithm = \'AES-128-ECB\'\r\n    \r\n    key = \'1234567890123456\'\r\n    msg = \'Hello, World\'\r\n    # msg = Base64.encode64(msg)\r\n    \r\n    if params\r\n        if params[:key]\r\n            key = params[:key]\r\n            if key.length < 16\r\n                z = 16 - key.length\r\n                key = key + (\"Z\" * z)\r\n            end\r\n        end\r\n        if params[:msg]\r\n            msg = params[:msg]\r\n            # msg = Base64.encode64(msg)\r\n        end\r\n    end\r\n    \r\n    result = {}\r\n    result[:key] = key\r\n    result[:key_encrypt] = Base64.encode64(key).strip\r\n    result[:message] = msg\r\n    begin\r\n        cipher = OpenSSL::Cipher::Cipher.new(algorithm)\r\n        cipher.encrypt\r\n        \r\n        # key = Digest::SHA1.hexdigest(key)\r\n        # iv = cipher.random_iv\r\n        \r\n        cipher.key = key \r\n        crypt = cipher.update(msg) + cipher.final()\r\n        crypt_string = (Base64.encode64(crypt))\r\n        result[:encrypt] = crypt_string.strip\r\n    rescue Exception => exc\r\n        result[:error] = \"Message for the encryption log file for message \\\\#{msg} = \\\\#{exc.message}\"\r\n    end\r\n    \r\n    result[:usage] = \"encode?key={yourkey}&msg={yourmessage}\"\r\n%>\r\n<%= result.to_json.html_safe %>',NULL,NULL,NULL,'2015-05-23 16:40:32','2015-05-23 16:40:32','encode','*'),(1577,'decode',666,3,'<%\r\n    # https://gurudathbn.wordpress.com/2015/02/04/aes-cipher-encryption-decryption-algorithms-using-ruby-on-rails/ <-- use this\r\n    # http://www.heathanderson.net/2009/09/25/ruby-string-encryption/ <-- choice\r\n    require \'openssl\'\r\n    require \'digest/sha1\'\r\n    require \'base64\'\r\n    \r\n    algorithm = \'AES-128-ECB\'\r\n    \r\n    key = \'1234567890123456\'\r\n    msg = \'gewnNd9l+haSyWRFUglOvA==\'\r\n    # msg = \"/WNIyw/mQRVWDeEOUqEDFUXsnUUCbqgQEvB07fs9jUo=\"\r\n    # msg = Base64.decode64(msg)\r\n    \r\n    if params\r\n        if params[:key]\r\n            key = params[:key]\r\n            if key.length < 16\r\n                z = 16 - key.length\r\n                key = key + (\"Z\" * z)\r\n            end\r\n        end\r\n        if params[:msg]\r\n            msg = params[:msg]\r\n            # msg = Base64.decode64(msg)\r\n        end\r\n    end\r\n    \r\n    result = {}\r\n    result[:key] = key\r\n    result[:key64] = Base64.encode64(key).strip\r\n    result[:message] = msg\r\n    begin\r\n        cipher = OpenSSL::Cipher.new(algorithm)\r\n        cipher.decrypt()\r\n        cipher.key = key\r\n        tempkey = Base64.decode64(msg)\r\n        crypt = cipher.update(tempkey)\r\n        crypt << cipher.final()\r\n        result[:decrypt] = crypt.force_encoding(\'UTF-8\')\r\n    rescue Exception => exc\r\n        result[:error] = \"Message for the decryption log file for message \\\\#{msg} = \\\\#{exc.message}\"\r\n    end\r\n    result[:usage] = \"decode?key={yourkey}&msg=fhDUgM7L714NK7wSCgOj7A==\"\r\n%>\r\n<%= result.to_json.html_safe %>',NULL,NULL,NULL,'2015-05-23 16:43:52','2015-05-23 16:43:52','decode','*'),(1578,'zam',574,3,'<%= render :inline=>this.init%><%\r\n    result=nil\r\n    if params[:admit_id] \r\n        \r\n        services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\')\r\n\r\n        admit_id = params[:admit_id]\r\n    \r\n        mapp = @patient_module_model.where(:module_id=>admit_id).first\r\n        patient = @patient_model.find(mapp.patient_id) if mapp\r\n        list = nil\r\n    \r\n        if mapp and patient\r\n    \r\n    \r\n            list = services.collect{|i|\r\n    \r\n                doc =  @current_project.get_document(i.name)\r\n                # model = @models[doc.name.to_sym]\r\n        \r\n                # mm = @patient_module_model.where(:parent_id=>mapp.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\").first\r\n        \r\n                # if mm\r\n                #     record = model.find(mm.module_id)\r\n                # else\r\n                #     mm = @patient_module_model.new :module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\", :parent_id=>mapp.id\r\n                #     record = model.new\r\n                # end\r\n        \r\n        \r\n        \r\n                # img_f = nil\r\n        \r\n                # ohn = patient.hn\r\n                # hn = patient.hn.split(\"/\").join(\"-\")\r\n            \r\n                \r\n            \r\n            \r\n            \r\n                # record_id = mm.id\r\n            \r\n                # imgs = nil        \r\n                # for j in doc.fields \r\n                #     if j.field_type == \'image_camera\'\r\n                #         img_f = j \r\n                #         snap = URI.encode(\"/esm_image/\\\\#{doc.id}/snap?field_id=\\\\#{j.id}&p_id=\\\\#{@current_project.id}&path=esm/\\\\#{@current_project.esm.name}/\\\\#{@current_project.name}/\\\\#{hn}/\\\\#{doc.name}/\\\\#{Time.now.strftime(\'%Y-%m-%d\')}-\\\\#{record_id}/image&ref=\\\\#{ohn}\")\r\n                #         # admit_id, doc_id, record_id\r\n                #         attachment = URI.encode(\"/esm/\\\\#{@current_project.esm.name}/\\\\#{@current_project.name}/Api/attach_image_by_admit_id?admit_id=\\\\#{admit_id}&doc_id=\\\\#{doc.name}&record_id=\\\\#{record_id}&f_id=\\\\#{j.column_name}\")\r\n                    \r\n                #         imgs = {:name=>doc.name,:title=>doc.title, :snap_url=>snap,:attach_url=>attachment}    \r\n                #     end\r\n                # end\r\n        \r\n        \r\n                # imgs if img_f\r\n                doc\r\n    \r\n            }    \r\n    \r\n            list.compact!\r\n    \r\n        end\r\n    \r\n    \r\n    \r\n        result = {:result=>\'200 OK\',:return=>list,:timestamp=>Time.now}\r\n        m_tmp = @models[\'gastro\']\r\n        result[:gastro] = m_tmp.all.count\r\n        result[:current_project] = @current_project\r\n        result[:doc] = @current_project.get_document(\'gastro\')\r\n        # result[:model] = @models[result[:doc].name.to_sym]\r\n    else\r\n        result = {:result=>\'404 Not found\',:return=>nil,:timestamp=>Time.now}\r\n    end\r\n\r\n%>\r\n<%= result.to_json.html_safe%>',NULL,NULL,NULL,'2015-05-23 18:09:09','2015-05-23 18:09:09','zam','*'),(1579,'document_name',716,1,'\'patient_detail\'',NULL,NULL,NULL,'2015-05-23 18:35:00','2015-05-23 18:35:00',NULL,NULL),(1580,'form_name',714,1,'\'Preanesthetic evaluation and medication record\'',NULL,NULL,NULL,'2015-05-24 04:56:15','2015-05-24 04:56:15','form_name',''),(1581,'form_name',711,1,'\'Postanesthetic evaluation record\'',NULL,NULL,NULL,'2015-05-24 04:57:01','2015-05-24 04:57:01','form_name',''),(1582,'index_check_colo',675,2,'<%=view :fitscreen %>\r\n<h1>Recovery System</h1>\r\n<%\r\n  mname = \'colonoscopy\'\r\n  mname = params[:model] if params[:model]\r\n  mname = mname.to_sym\r\n pms = []\r\n ids = []\r\n unlink = []\r\n \r\n \r\n \r\n%>\r\n<%= form_for :query ,:url=>\'index_post\' do |f| %>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    mpm = model[:patient_module]\r\n    \r\n    models = get_model\r\n    \r\n    mcolono = models[mname]\r\n    matt = models[:attachment] \r\n    \r\n    if params[:date]\r\n        \r\n    %>\r\n    <%= hidden_field_tag \'date\', params[:date] %>\r\n    <%\r\n    date = Date.to_mongo(Time.zone.parse(params[:date].split(\'/\').reverse.join(\"-\")))\r\n    # date =Time.zone.parse(params[:date])\r\n    ids = mcolono.collection.find({:created_at=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}},{:fields=>{\'_id\'=>1}}).to_a.collect{|i| i[\'_id\']}\r\n    \r\n    \r\n    else\r\n    \r\n    ids = mcolono.collection.find({},{:fields=>{\'_id\'=>1}}).to_a.collect{|i| i[\'_id\']}\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n    pms = mpm.collection.find(:module_id=>{\'$in\'=>ids}).to_a\r\n    map = {}\r\n   \r\n    for i in pms\r\n        map[i[\"module_id\"]] = i\r\n    end\r\n    for i in ids\r\nif map[i]\r\n%><%# map[i] %>\r\n<% else \r\n\r\n unlink << i \r\n \r\n \r\n \r\n\r\n%>\r\n<% end %>\r\n<% end %>\r\n<% \r\n\r\nmonths = {}\r\ndate_map = {}\r\n\r\ncols =  mcolono.collection.find(\'_id\'=>{\'$in\'=>unlink}).to_a\r\n \r\nfor i in cols  \r\n\r\nk = i[\'created_at\'].strftime(\'%d/%m/%Y\')\r\nm = i[\'created_at\'].strftime(\'%m/%Y\')\r\nmonths[m] = [] unless months[m] \r\nmonths[m] << k unless date_map[k] \r\ndate_map[k] = [] unless date_map[k]\r\ndate_map[k] << i\r\n\r\nend \r\n\r\n%>\r\n<% months.each_pair do |k,v| %>\r\n<%=k%>\r\n<%= v.collect{|j| link_to(j,\"index?date=\\\\#{j}\") }.join(\" | \") .html_safe %>\r\n<hr/>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n \r\n if params[:date]\r\n    cols = date_map[params[:date]] \r\n%>\r\n\r\n<%\r\n    mx = {:colonoscopy=>\'Colonoscopy\',:gastroscopy=>\'Gastroscopy\'}\r\n\r\n    mx.each_pair do |mx_name,mx_label|\r\n%>\r\n\r\n\r\n<h1><%=mx_label%></h1>\r\n<%\r\n\r\n  providers = {}\r\n  models[:provider].to_a.each do |i|\r\n     \r\n     providers[i.id] = i.name \r\n      \r\n  end\r\n  \r\n  mc = models[mx_name]\r\n  objs = mc.collection.find(:created_at=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}).to_a\r\n  ids = objs.collect{|i| i[\'_id\']}\r\n  pms = mpm.collection.find(:module_id=>{\'$in\'=>ids}).to_a\r\n  map = {}\r\n  unlink = []\r\n  for i in pms\r\n        map[i[\"module_id\"]] = i\r\n  end\r\n\r\n  for i in objs\r\n    unless map[i[\'_id\']]\r\n     unlink << i \r\n    end\r\n  end\r\n  \r\n%>\r\n\r\n<table border=\"1\">\r\n<%\r\n \r\nunlink.each_with_index do |i,index| \r\n    \r\n imgs = matt.find(i[\'image\']).to_a\r\n if imgs.size>=3\r\n imgs = imgs[-3..-1] \r\n end\r\n id = i[\'_id\']\r\n%>\r\n<tr>\r\n<td><%=index+1%>. <%=i[\'created_at\']%></td>\r\n<td><%=i[\'diagnosis_group\']%></td>\r\n<td><%=providers[i[\'endoscopist_1\']]%></td>\r\n<td id=\"\">\r\n\r\n    <%=text_field_tag \"\\\\#{mx_name}[\\\\#{id}]\",\"\",:onchange=>\'javascript:search_hn(this)\',:style=>\"width:120px\" %>\r\n    <%=hidden_field_tag \"\\\\#{mx_name}_ass[\\\\#{id}]\",\"\", :id=>\"v\\\\#{id}\" %>\r\n    <%=hidden_field_tag \"\\\\#{mx_name}_provider[\\\\#{id}]\",i[\'endoscopist_1\'] %>\r\n    \r\n</td>\r\n\r\n</tr>\r\n<tr>\r\n<% if  imgs.size>0 and params[:date] %>\r\n<% imgs.to_a.each do |j| %>\r\n<td>\r\n<a href=\"<%=j.path%>?<%=j.id%>\" class=\"highslide\" rel=\"highslide\" onclick=\"return hs.expand(this)\"><center><img src=\"<%=j.path%>?<%=j.id%>&amp;thumb=1\" name=\'img\' id=\"<%=j.id%>\" class=\"eachpicimg\" border=0   height=90px align=absmiddle ></center>\r\n</a>\r\n</td>\r\n<% end %>\r\n<% else %>\r\n<td colspan=\"3\">&nbsp;</td>\r\n<% end %>\r\n<td id=\"<%=id%>\" class=\"alert-info\">.</td>\r\n\r\n</tr>\r\n<% if imgs.size>0 %>\r\n<tr>\r\n    <td colspan=\"4\" style=\"height:200px;background-image:url(\'<%= imgs[0].path%>\')\">\r\n    </td>\r\n</tr>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n<tr>\r\n    <td colspan=\"4\">&nbsp;</td>\r\n</tr>\r\n\r\n\r\n\r\n<% end %>\r\n</table>\r\n\r\n\r\n<hr/>\r\n<% end %>\r\n<br/>\r\n<%= f.submit \'Check Association\', :class=>\'btn btn-success\' %>\r\n<br/>\r\n<% end %>\r\n\r\n<%=ids.size%> | <%=pms.size%>\r\n\r\n<% end %>\r\n\r\n<%= link_to \'See All\' ,\'index_check_colo\' %>\r\n\r\n<script>\r\n    \r\n    function search_hn(t){\r\n        \r\n        var v = $(t)\r\n        id = v.attr(\'id\')\r\n        t = id.split(\'_\')\r\n        vid = t[1];\r\n        var value = v.val()\r\n      $(\'#\'+vid).html(\'loading..\');\r\n     \r\n     $.ajax({\r\n            type: \'POST\',\r\n            url: \"partial\",\r\n            data: { q: value,id: vid},\r\n            success: function(html){\r\n                $(\'#\'+vid).html(html);\r\n            }\r\n         });\r\n         \r\n         \r\n    \r\n        \r\n        // alert(\'search \'+v)\r\n    }\r\n    \r\n    \r\n    $(document).ready(function() {\r\n    \r\n    });\r\n\r\n    \r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-05-24 14:17:39','2015-05-24 14:17:39','index_check_colo',''),(1583,'basic_patient_report',502,2,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n			\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n		    <title><%=title%></title>\r\n\r\n				<script>\r\n					$(document).ready(function() {\r\n						//* show all elements & remove preloader\r\n						// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n						 // $(\"html\").removeClass(\"js\");\r\n					});\r\n				</script>\r\n		\r\n				 <style>\r\n    .w-box-content.cnt_a {background: #fff;}\r\n    .k-grid table {font-size: 1em;}\r\n.k-calendar .k-content {font-size: 1em;padding-top:5px;}\r\n.k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\nheight: 18px;}\r\n.field-data {\r\nwidth: 220px;}\r\n\r\ninput{\r\n    height:18px;\r\n}\r\nbody { \r\n    /*background-image: url(\'/esm/thks/www/content/hip-knee-pain-bw.jpg\');*/\r\n    /* ref : http://i0.wp.com/blog.beaumont.edu/wp-content/uploads/2014/10/hip-knee-pain.png */\r\n    background-repeat: no-repeat;\r\n    background-attachment: fixed;\r\n    background-position: center top; \r\n    /*background-color: black;*/\r\n    /*background-size: cover;*/\r\n    padding: 20px;\r\n    font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\r\n    /*font-weight: lighter;*/\r\n    /*font-size: 1em;*/\r\n}\r\n</style>\r\n		\r\n		\r\n</head>\r\n<body>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\" style=\"padding:0px;\">\r\n<!--start body content-->\r\n\r\n    <div class=\"row-fluid\">\r\n        \r\n<%\r\nmodule_name = @current_project.name\r\nif params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\nend\r\nif session[module_name]\r\n	params[:date] = session[module_name][:date]\r\nend\r\nunless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\nend\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n         Patient Report : CU GI MED \r\n         <span style=\"float:right\"><%=Time.now%></span>\r\n         <div class=\"clear\"></div>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:5px\" >\r\n    \r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\'patient_report\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n            \r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            \r\n            \r\n            <div class=\"field-input\">\r\n                 <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                 \r\n                 <%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>\r\n            </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        \r\n        </div>\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%# params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n    \r\n    if !search_patient and params[:select].nil?\r\n\r\n    	patients = patient_model.all  \r\n	    maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n    	aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n    	aps = []\r\n    %>\r\n    <!--ALL -->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name, :last_name=>s_last_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n    	patients = patient_model.where(criteria).limit(20).all  \r\n	    maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n    	aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT-->\r\n    <%\r\n    elsif params[:date]\r\n    \r\n	    conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n    		conds.merge! :provider=>s_provider \r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n    \r\n    	aps = ap_model.all(conds)\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n\r\n    %>\r\n    <!--DATE-->\r\n    <%\r\n    end # end if\r\n    %>\r\n<!--<strong><%= aps.size %></strong>-->\r\n\r\n<%\r\n    map_provider = {}\r\n    for i in provider_model do\r\n        map_provider[i.id.to_s] = i\r\n    end\r\n    result = []\r\n    for i in aps do\r\n        tmp = {}\r\n        tmp[:date] = i[:date]\r\n        tmp[:provider] = map_provider[i[:provider].to_s].to_s\r\n        m_app = module_model.where(:module_id=>i.id).first\r\n        \r\n        patient = patient_model.find(m_app[:patient_id])\r\n        tmp[:hn] = patient[:hn]\r\n        tmp[:patient] = patient[:prefix].to_s + \" \" + patient[:first_name].to_s + \"&nbsp;&nbsp;&nbsp;\".html_safe + patient[:last_name].to_s\r\n        \r\n        operation = module_model.where(:parent_id=>m_app.id).all\r\n        for j in operation do\r\n            op_name = j[:module_name].split(\'#\')[1].capitalize\r\n            att = model[:attachment].find(j[:report])\r\n            action = link_to(\'View\', \"../\\#{op_name}/rprint?id=\\#{j.id}\", :target=>\'_blank\', :class=>\'btn btn-mini btn-success\')\r\n            if att\r\n                action += \'&nbsp;\'.html_safe\r\n                action += link_to(\'PDF\', att.path, :target=>\'_blank\', :class=>\'btn btn-mini btn-success\')\r\n            end\r\n            tmp[:operation] = op_name\r\n            tmp[:action] = action\r\n            result.push(tmp)\r\n        end\r\n%>\r\n<!--Date : <%# i[:date] %><br/>-->\r\n<!--Provider : <%# map_provider[i[:provider].to_s] %> (<%= i[:provider] %>)<br/>-->\r\n<!--Operation : <%# operation.size %><br/>-->\r\n<!--Patient : <%# patient.inspect %>-->\r\n<!--<hr/>-->\r\n<%  \r\n    end \r\n    labels = {:no=>\'No.\', :date=>\'Date\', :hn=>\'HN\', :patient=>\'Patient Name\', :provider=>\'Provider Name\', :operation=>\'Operation Name\', :action=>\'Action\'}\r\n    m = [:no, :date, :hn, :patient, :provider, :operation, :action]\r\n    result = result.sort_by{|i| i[:date]}.reverse\r\n    result = result.uniq\r\n%>\r\n<div id=\"result-panel\"  style=\"padding:0px\">\r\n<% count = 1 %>\r\n<%= tabular :model=>m, :data=>result, :labels=>labels do |row,out| \r\n    out[0] = count.to_s+\".\"\r\n    count+=1\r\n    out\r\n    end\r\n%>\r\n</div>\r\n\r\n\r\n<%\r\nif false \r\n \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n		 patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         # zamachita comment and change link to patient_record\r\n        #  hn = link_to(patient.hn, \"../Appointment/show?id=\\#{m.id}\") if patient\r\n        # hn = link_to(patient.hn, \"patient_record?id=\\#{m[:patient_id]}&aid=\\#{m.id}\")\r\n        hn = link_to(patient.hn, \"patient_record?id=\\#{m.id}\")\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n        #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\#{patient.prefix_name} \\#{patient.first_name} \\#{patient.last_name}\",\"../../www/Patient/edit?id=\\#{patient.id}&return=\\#{request.fullpath}\"),\r\n        #  :provider=>provider_name,:date=>i.date,:note=>\"\\#{visit_type} \\#{indications[i.indication]} \\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n        #  :visit_type=>visit_type\r\n        #  }\r\n        c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\#{patient.prefix_name} \\#{patient.first_name} \\#{patient.last_name}\",\"../../www/Patient/edit?id=\\#{patient.id}&return=\\#{request.fullpath}\"),\r\n        :provider=>provider_name,:date=>i.date,:note=>\"\\#{visit_type} \\#{indications[i.indication]} \\#{i.note}\",:status=>i.status,\r\n        # :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\#{m[:patient_id]}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n        :visit_type=>visit_type\r\n        }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\#{m[:patient_id]}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\#{m[:patient_id]}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    # table_model = %w{date hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    table_model = %w{date hn patient provider }.collect{|i| i.to_sym}\r\n    \r\n    \r\n    # labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',\r\n    # :status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\', :note=>\'Note\',:visit_type=>\'Group\' }\r\n    labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:Provider=>\'Appointed Doctor\', :pending_ctrl=>\'Appointed ctrl\', :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n        \r\n        \r\n        \r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                 <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    out[0] = count.to_s+\".\"\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n\r\n        </div>\r\n<%\r\nend\r\n# end if false\r\n%>\r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"patient_report?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n\r\n<!--<div class=\"alert \">-->\r\n<!--Links : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | -->\r\n<!--<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | -->\r\n<!--<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>-->\r\n<!--</div>-->\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n        \r\n    </div>\r\n<!--body content-->\r\n</div>\r\n</div>\r\n     <script type=\"text/javascript\" charset=\"utf-8\">\r\n	refresh_remote();\r\n	$(\'#search-field\').focus()\r\n</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-05-25 03:06:52','2015-05-25 03:06:52','basic_patient_report',''),(1584,'index_dev2',717,2,'<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n		session[module_name]={:date=>params[:date]}\r\n	end\r\n	if session[module_name]\r\n		params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n		params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n		width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list = %w{appointed waiting operation completed recovery icu ward home cancelled}.collect{|i| i.to_s == \'icu\' ? \'ICU\' : i.humanize}\r\n   \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    s_case_type=nil\r\n    hn=nil\r\n    operative=nil\r\n    s_anesth_technique=nil\r\n    # session[:s_provider] if session[:s_provider]\r\n    # session[:s_status] if session[:s_status]\r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n		s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n		s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n		date_text = s_date.strftime(\"%d/%m/%Y\")\r\n		session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n%>\r\n<%= error%>\r\n<%\r\n    session.delete :s_date\r\n    end\r\n%>\r\n<%\r\n    add_visit = \"../Appointment/create?return=../Home/index&data[date]=\\\\#{date_text}\"\r\n    search_patient = false\r\n    if p = params[:search]\r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n		s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n		s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n			search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\" style=\"font-size:3\">\r\n				<b>Home Patients : <%= date.strftime(\"%d/%m/%Y\") %></b>\r\n			</div>  \r\n			<div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n				<div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n					<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n						<!-- Search Form Start -->\r\n						<%=form_for :search,:url=>\'../Home/index\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n						<span class=\"field-data\"> \r\n							<label class=\"field-label\">Date :  </label>\r\n							<div class=\"field-input\" ><%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%></div>\r\n						</span>\r\n					\r\n						<span class=\"field-data\">\r\n							<label class=\"field-label\">HN : </label>\r\n							<div class=\"field-input\"><%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%></div>\r\n						</span>\r\n					\r\n					\r\n						<span class=\"field-data\" style=\"margin-top: 5px;\"> \r\n							<%= button_tag(type: \'submit\', class: \"btn btn-success\") do %>\r\n<i class=\"splashy-zoom\"></i> Search\r\n<% end %>\r\n							<%= link_to(raw(\"Advance Search\"),\'javascript:doSearch()\',{ :class => \'btn\'})  %>\r\n								\r\n							\r\n							\r\n						</span>\r\n						<span class=\"field-data\"> \r\n						\r\n							<div class=\"field-input\">\r\n<%\r\n    \r\n    if s_provider \r\n        add_visit+= \"&data[provider]=\\\\#{s_provider}\" \r\n    end\r\n%>\r\n								<%#link_to (\"<i class=\'splashy-contact_blue_add\'></i> Add patient\").html_safe,add_visit, :class=>\'btn btn-info\',:style=>\'margin-top:10px\'%>\r\n							</div>\r\n						</span>\r\n						<div class=\"clear\"></div>\r\n						<% end %>\r\n						<!-- End Search Form -->\r\n					</div>\r\n				</div>\r\n\r\n<%\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n%>\r\n<%#params.inspect %><%#search_patient.inspect%>\r\n<%\r\n    if search_patient\r\n        \r\n		fields = {:hn=>s_hn, :first_name=>s_first_name}\r\n		keys = []\r\n%>\r\n<%#fields.inspect %>\r\n<%\r\n		fields.each_pair do |k,v| \r\n			keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n		end\r\n		if keys.size>0\r\n			criteria = {\'$or\'=>keys}\r\n		else\r\n			criteria ={}\r\n		end\r\n    \r\n		patients = patient_model.where(criteria).limit(20).all  \r\n		maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n		aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    else\r\n%>\r\n<%\r\n		conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n		\r\n		if s_provider and s_provider !=\'\'\r\n			conds.merge! :provider=>s_provider \r\n		end\r\n\r\n		if s_status and s_status != \"\"\r\n			conds.merge! :status=>s_status \r\n		end\r\n    \r\n		aps = ap_model.all(conds)\r\n%>\r\n<%\r\n    end\r\n    \r\n    map_or_room = {}\r\n    map_or_room[\"\"]  = \"-\"\r\n    map_or_room[nil] = \"-\"\r\n    for m in get_model[:or_room].all do\r\n        map_or_room[m.id.to_s] = m[:name]\r\n    end\r\n    \r\n    map_position = {\'\'=>\'N/A\',nil=>\'N/A\'}\r\n    for m in get_model[:position].all do\r\n        map_position[m.id.to_s] = m[:name]\r\n    end\r\n    \r\n    map_prov = {\'\'=>\'-\', nil=>\'-\'}\r\n    map_login = {\'\'=>\'Unknown\', nil=>\'Unknown\'}\r\n    for m in p_model.all do\r\n        map_prov[m.id.to_s] = m[:name]\r\n        map_login[m[:login]] = m[:name]\r\n    end\r\n    \r\n    l_updated = []\r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n        #  provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = map_prov[i.provider.to_s]\r\n        #  provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n        #  hn = patient.hn if patient\r\n         hn = link_to(patient.hn, \"../Appointment/edit?id=\\\\#{m.id}\") if patient\r\n         case_type = \"<span style=\'color:red;font-weight:bold\'>(\\\\#{i[:case_type]})</span> \" unless !i[:case_type] or i[:case_type] == \'\'\r\n         \r\n         patient_name = \"\\\\#{case_type} \\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\".html_safe\r\n         patient_link = link_to(\"\\\\#{case_type} \\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\".html_safe,\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\")\r\n         \r\n         if @current_role==\'developer\'\r\n             patient_name = patient_link\r\n         end\r\n         \r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n        # change patient_link to name only\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>patient_name,\r\n         :provider=>provider_name,:date=>i.date.strftime(\'%d/%m/%Y\') ,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=> @current_role != \'guest\' ? select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id) : i[:status],\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success btn-mini\'),\r\n         :visit_type=>visit_type, :patient_id=>patient.id.to_s\r\n         }\r\n         \r\n        #  if i.status==\'Waiting\'\r\n            # c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-success btn-mini\')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success btn-mini\') \r\n        #  x = 1\r\n        #  c[:pending_ctrl]+= \'df\'\r\n         \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        #  else\r\n            status = \'btn-info\'\r\n            status = \'\' if i.status ==\'Completed\'\r\n            c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-success btn-mini \'+status)\r\n           \r\n        #  end\r\n         \r\n        # additional for preop, postop\r\n        # m is a patient_module of appointment\r\n        # i is an appointment\r\n        pre_op = module_model.where(:module_name=>\"\\\\#{@current_project.name}#pre_anesthetic\", :parent_id=>m.id)\r\n        if pre_op.first\r\n            c[:pre_op] = \'<i class=\"splashy-check\"></i>\'\r\n            c[:has_pre_op]=true\r\n        else\r\n            c[:pre_op] = \'<i class=\"splashy-remove_minus_sign\"></i>\'\r\n             c[:has_pre_op]=false\r\n        end\r\n        c[:post_op] = \'<i class=\"splashy-remove_minus_sign\"></i>\'\r\n        c[:pacu] = \'<i class=\"splashy-remove_minus_sign\"></i>\'\r\n        \r\n        post_op = module_model.where(:module_name=>\"\\\\#{@current_project.name}#post_anesthetic\", :parent_id=>m.id)\r\n        if post_op.first\r\n            # r_post_op = get_model[:post_anesthetic].find(post_op.first[:module_id])\r\n            # if r_post_op[:alteration_e].to_s.strip != \'\' or r_post_op[:alteration_v].to_s.strip != \'\' or r_post_op[:alteration_m].to_s.strip != \'\'\r\n            #     c[:post_op] = \'<i class=\"splashy-check\"></i>\'\r\n            # end\r\n            c[:post_op] = \'<i class=\"splashy-check\"></i>\'\r\n            c[:pacu] = \'<i class=\"splashy-check\"></i>\'\r\n         c[:has_post_op]=true\r\n        else\r\n         c[:has_post_op]=false\r\n        end\r\n       \r\n       \r\n        #  c[:processing_ctrl]+=c[:has_pre_op].inspect \r\n        unless c[:has_pre_op]\r\n            c[:processing_ctrl]+= link_to(\"+PreOp\",\"../PreAnesthetic/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{m.id}&return=../Home/patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-mini\')\r\n        end\r\n       \r\n        unless c[:has_post_op]\r\n             c[:processing_ctrl]+= link_to(\"+PostOp\",\"../PostAnesthetic/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{m.id}&return=../Home/patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-mini\')\r\n        end\r\n        \r\n        c[:or_room] = map_or_room[i[:or_room]]\r\n        # c[:time] = link_to(i[:start].strftime(\'%H:%M\'), \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n        c[:time] = !i[:start].nil? ? i[:start].strftime(\'%H:%M\').to_s : \'N/A\'\r\n        if i[:time_tf] == \'1\'\r\n            c[:time] += \' TF\'.html_safe\r\n        end\r\n        \r\n        l_updated.push({:user=>i[:updated_by],:time=>i[:updated_at]})\r\n        c[:updated_by] = \"<span id=\'user-\\\\#{i.id}\' title=\'\\\\#{map_login[i[:updated_by]]}\'>\\\\#{i[:updated_by]}</span>\".html_safe\r\n        c[:operation] = i[:operation]\r\n        c[:position]  = map_position[i[:position]]\r\n        c[:anesth_tech] = i[:anesth_technique] ? i[:anesth_technique] : \'-\'\r\n        c[:anesth_tech] = \'-\' if i[:anesth_technique] == \'\'\r\n        \r\n        c\r\n      end\r\n    }.compact!\r\n    \r\n    # waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    # processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    # completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    # cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    # table_model = %w{date hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    # removed pacu \r\n    # add operation, position\r\n    table_model = %w{pre_op post_op or_room time date hn patient position operation status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    # Post Anesth 24hrs\r\n    # removed :pacu=>\'PACU\',\r\n    labels = {:no=>\'No.\', :or_room=>\'OR\', :time=>\'Time\', :pre_op=>\'Pre\', :post_op=>\'Post\', :date=>\'Appoint date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\', :processing_ctrl=>\'Action\', :updated_by=>\'Updated by\', :position=>\'Position\', :operation=>\'Operation\' }\r\n    \r\n    # if @current_role == \'developer\'\r\n        aps = aps.sort_by{|i| [i[:or_room], i[:time]]}  if aps\r\n        # aps = aps.sort_by{|i| i[:or_room]}\r\n    # end\r\n%>\r\n        <div class=\"row-fluid\"></div>\r\n        <br/>\r\n        <!--<div align=\"left\" style=\"float:left;margin-left:5px\">-->\r\n        <!--    <%= link_to \'<i class=\"splashy-calendar_month\"></i> Operative Schedule\'.html_safe, \"print_table?date=\\\\#{date.strftime(\'%d/%m/%Y\')}\", :class=>\'btn btn-mini\', :target=>\'_blank\' %>-->\r\n        <!--    <%= link_to \'<i class=\"splashy-application_windows_share\"></i> Status Board\'.html_safe, \'status_board\', :class=>\'btn btn-mini\', :target=>\'_blank\' %>-->\r\n        <!--</div>-->\r\n        <div style=\"float:left;margin-left:5px\">\r\n            Operation Date : <span style=\"color:blue\"><%= date.strftime(\'%d/%m/%Y\') %></span>\r\n            <% if @current_role != \'guest\' %>\r\n            <%=link_to (\"<i class=\'splashy-contact_blue_add\'></i> Add patient\").html_safe, add_visit, :class=>\'btn btn-mini btn-info\',:style=>\'margin-left:10px\'%>\r\n            <% end %>\r\n        </div>\r\n        <div align=\"right\" style=\"float:right;margin-right:5px\">\r\n            <%= link_to \'<i class=\"splashy-document_letter_marked\"></i> Report\'.html_safe, \"../Report/index\", :class=>\'btn btn-mini\' %>\r\n            <%= link_to \'<i class=\"splashy-calendar_month\"></i> Operative Schedule\'.html_safe, \"print_table?date=\\\\#{date.strftime(\'%d/%m/%Y\')}\", :class=>\'btn btn-mini\', :target=>\'_blank\' %>\r\n            <%= link_to \'<i class=\"splashy-application_windows_share\"></i> Status Board\'.html_safe, \"status_board?date=\\\\#{date.strftime(\'%d/%m/%Y\')}\", :class=>\'btn btn-mini\', :target=>\'_blank\' %>\r\n        </div>\r\n        \r\n        <br/>\r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n<% if false %>\r\n                <% \r\n                    count = 1 \r\n                    # :col_width=>{:no=>50 ,:pre_op=>90 ,:pacu=>90 ,:post_op=>90 ,:date=>100 ,:time=>100 ,:status_ctrl=>140 ,:or_room=>70,:hn=>100}\r\n                %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:updated_by],:data=>aps,:labels=>labels, :col_width=>{:no=>30,:pre_op=>40,:post_op=>40,:pacu=>50}  do |row,out| \r\n                    out[0] = count.to_s+\".\"\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n<% end %>\r\n<%\r\n    # if @current_role == \'developer\'\r\n    if !aps.empty?\r\n%>\r\n<style>\r\n    .table th,\r\n    .table td {\r\n      padding: 8px;\r\n      line-height: 28px;\r\n      text-align: left;\r\n      vertical-align: middle;\r\n      border-top: 1px solid #dddddd;\r\n    }\r\n    .cancel {\r\n        font-style:italic;\r\n        text-decoration:line-through;\r\n        color:#0088cc;\r\n    }\r\n</style>\r\n\r\n<!-- Message -->\r\n<div style=\"padding:10px\"></div>\r\n<div class=\"row-fluid\">\r\n<!--\r\n<div class=\"alert\">\r\n	<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    ระบบจะปิดให้บริการออนไลน์ในวันที่ 31 มกราคม 2559 และจะให้บริการบนเครือข่ายของโรงพยาบาลในวันที่ 1 กุมภาพันธ์ 2559 บน URL: <a href=\'http://128.1.192.103/pni/anes/Home/index\' target=\'_blank\'>http://128.1.192.103/pni/anes/Home/index</a> (กรุณาทำ bookmark ไว้เพื่อความสะดวกในการใช้งาน)\r\n</div>\r\n-->\r\n<% if false %>\r\n<div class=\"alert alert-info\">\r\n	<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    ระบบขยายเวลาปิดให้บริการออนไลน์เป็นวันที่ 31 มีนาคม 2559 เนื่องจากทางมีการปรับปรุงระบบ WIFI และจะให้บริการบนเครือข่ายโรงพยาบาลวันที่ 1 เมษายน 2559\r\n</div>\r\n<% end %>\r\n                                \r\n                                <div style=\"padding:10px\"></div>\r\n                                <div class=\"row-fluid\">\r\n									<table class=\"table table-striped table-bordered table-condensed\">\r\n										<thead>\r\n											<tr>\r\n												<th><center>No.</center></th>\r\n												<th><center>Pre</center></th>\r\n												<th><center>Post</center></th>\r\n												<th><center>OR</center></th>\r\n												<th><center>Time</center></th>\r\n												<th><center>Appoint Date</center></th>\r\n												<th><center>HN</center></th>\r\n												<th><center>Patient Name</center></th>\r\n												<th><center>Position/<br/>AnesthTech</center></th>\r\n												<th><center>Operation</center></th>\r\n												<th><center>Status</center></th>\r\n												<th><center>Action</center></th>\r\n												<th><center>Updated By</center></th>\r\n											</tr>\r\n										</thead>\r\n										<tbody>\r\n<% \r\n    aps.each_with_index do |rs,i| \r\n        # cancel status\r\n        no = i + 1\r\n%>\r\n											<tr<%= \" class=\'cancel\'\".html_safe if rs[:status] == \'Cancelled\' %>>\r\n												<td><center><%= link_to \"\\\\#{no}.\", \"../../www/Patient/edit?id=\\\\#{rs[:patient_id]}\" %></center></td>\r\n												<td><center><%= rs[:pre_op].html_safe %></center></td>\r\n												<td><center><%= rs[:post_op].html_safe %></center></td>\r\n												<td><center><%= rs[:or_room] %></center></td>\r\n												<td><center><%= rs[:time] %></center></td>\r\n												<td><center><%= rs[:date] %></center></td>\r\n												<td><%= rs[:hn] %></td>\r\n												<td><%= rs[:patient] %></td>\r\n												<td><center><%= rs[:position] %> / <%= rs[:anesth_tech] %></center></td>\r\n												<td><%= rs[:operation] %></td>\r\n												<td><%= rs[:status_ctrl].html_safe %></td>\r\n												<td><%= rs[:processing_ctrl].html_safe %></td>\r\n												<td><%= rs[:updated_by] %></td>\r\n											</tr>\r\n<% end %>\r\n										</tbody>\r\n									</table>\r\n								</div>\r\n								<br/>\r\n<% if @current_role == \'admin\' or @current_role == \'developer\' %>\r\n			<span style=\"float:left\">\r\n                <%= link_to \'Reset Locker\', \'javascript:void(0)\', :id=>\'reset\' %>\r\n            </span>\r\n<% end # if role %>\r\n<% else %>\r\n<center><font size=\'4em\'>No Patient Today. Click <a href=\"<%= add_visit %>\">Add Patient</a> First.</font></center>\r\n<%\r\n    end\r\n    if !l_updated.empty?\r\n        latest_user = l_updated.sort_by{|i| i[:time]}.reverse.first\r\n        prov = p_model.where(:login=>latest_user[:user]).first\r\n%>\r\n            <span style=\"float:right\">\r\n                <i>Last updated by <span style=\"color:blue\"><%= prov.nil? ? latest_user[:user] : \"\\\\#{prov[:name]} (\\\\#{latest_user[:user]})\" %></span> at <span style=\"color:blue\"><%= latest_user[:time].strftime(\'%d/%m/%Y %H:%M\') %></span></i>\r\n            </span>\r\n            <br/>\r\n<%\r\n    end\r\n%>\r\n            \r\n        </div>\r\n        \r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nfunction change_status(obj){\r\n	if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n		window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	}\r\n}\r\n\r\n$(\"#today-date\").kendoDatePicker({\r\n	value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n    change: function(){\r\n		window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n	}\r\n});\r\n</script>\r\n<br/>\r\n<div class=\"clear\"></div>\r\n<%#session[module_name].inspect %>\r\n<%\r\n	if params[:obj_id]\r\n		now = Time.now \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n   \r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n</div>\r\n<%\r\n    a_other = [[\'-- All --\',\'\'], [\'Pain Clinic\',\'1\'], [\'Critical care\',\'2\'], [\'CPR\',\'3\'], [\'Ventilation Care\',\'4\']]\r\n    a_surgeon = get_model[:provider].where( \"$or\"=>[{\"provider_type\"=>\'4\'}, {\"provider_type\"=>\'5\'}] ).all.collect{|i| [i.name.strip, i.id.to_s]}\r\n    a_anesth = get_model[:provider].where( \"$or\"=>[{\"provider_type\"=>\'6\'}] ).all.collect{|i| [i.name.strip, i.id.to_s]}\r\n    n_anesth = get_model[:provider].where( \"$or\"=>[{\"provider_type\"=>\'7\'}] ).all.collect{|i| [i.name.strip, i.id.to_s]}\r\n    s_asa = [[\'All\',\'\'], [\'I\',\'I\'], [\'II\',\'II\'], [\'III\',\'III\'], [\'IV\', \'IV\'], [\'V\',\'V\'], [\'VI\',\'VI\']]\r\n    t_asa = [[\'All\',\'\'], [\'-\',\'-\'], [\'E\',\'E\']]\r\n    anesth_tech = [[\"General anesthesia (balanced technique)\",\"1\"],[\"General anesthesia (Inhalation technique)\",\"2\"],[\"General anesthesia (TIVA)\",\"3\"],[\"Monitor anesthetic care\",\"4\"],[\"Regional anesthesia\",\"5\"],[\"Nerve Block\",\"6\"],[\"Combined general anesthesia and nerve block\",\"7\"],[\"Combined general anesthesia and regional anesthesia\",\"8\"],[\"GA due to RA/Nerve block fail\",\"9\"]]\r\n    anesth_dura = [[\'< 30min\',0],[\'30 min - 60 min\',1],[\'61 min - 120 min\',2],[\'121 min - 240 min\',3],[\'> 241 min\',4]]\r\n    duration_field = [[\'-- Anesth Time --\',\'anesthetic_duration\'], [\'Anesth official\',\'anesthetic_official_duration\'], [\'Anesth non-official\',\'anesthetic_non_official_duration\'], [\'RR official\',\'recovery_time\'], [\'RR non-official\',\'recovery_non_official_time_min\']]\r\n    pain_manage = [[\'-- All --\',\'\'], [\'PCA narcotics\',\'1\'], [\'PCA LA\',\'2\'], [\'IV narcotics\', \'3\'], [\'IV NSAIDS\', \'4\'], [\'Oral NSAIDS\', \'5\'], [\'Oral narcotics\',\'6\'], [\'Paracetamol\',\'7\']]\r\n    case_type = [[\'-- All --\',\'\'], [\'Cranio-spinal surgery\',\'1\'], [\'Neurovascular surgery\',\'2\'], [\'Pediatric neurosurgery\',\'3\'], [\'Neurodiagnostic and intervention\',\'4\'], [\'Dental Procedure\',\'5\'], [\'General surgery\',\'6\'], [\'Eye surgery\',\'7\'], [\'Off Operation\',\'8\']]\r\n\r\n%>\r\n\r\n\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Advanced Search</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n<%= form_for :adv_search,:url=>\'../Home/adv_search_dev?update=result-panel\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n	    <span class=\"field-data\"> \r\n			<label class=\"field-label\">Start Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :sdate, :value=>\'\',:id=>\'sdate\',:style=>\"width:100%\"%></div>\r\n		</span> \r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">End Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :edate, :value=>\'\',:id=>\'edate\',:style=>\"width:100%\"%></div>\r\n		</span>\r\n		<span class=\"field-data\" > \r\n			<label class=\"field-label\">Search In : </label>\r\n			<div class=\"field-input\" >\r\n<%= f.select :service, options_for_select([\'All\',\'Pre-Op\',\'Intra-Op\', \'Post-Op\']),{},:style=>\"width:100%\" %>\r\n            </div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n		<span> \r\n			<label class=\"field-label\" style=\'margin-left:440px\'>Other : </label>\r\n			<div class=\"field-input\" style=\"width:120px\">\r\n                <%= f.select :other, options_for_select(a_other, \'\'),{},:style=>\"width:120px\"%>\r\n			</div>\r\n		</span>\r\n		<div class=\"clear\"></div>\r\n		<hr/>\r\n        <span> \r\n			<label class=\"field-label\">Surgeon : </label>\r\n			<div class=\"field-input\" style=\"width:200px\">\r\n<%= f.select :surgeon, options_for_select(a_surgeon, \'\'),{:include_blank=>\'-- All --\'},:style=>\"width:180px\"%>\r\n			</div>\r\n		</span>\r\n		<span> \r\n			<label class=\"field-label\" style=\"width:120px\">Anesthesiologist : </label>\r\n			<div class=\"field-input\">\r\n<%= f.select :anesth, options_for_select(a_anesth, \'\'),{:include_blank=>\'-- All --\'},:style=>\"width:180px\"%>\r\n			</div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n		<span> \r\n			<label class=\"field-label\" style=\"width:125px;margin-left:280px\">Nurse Anesthetist : </label>\r\n			<div class=\"field-input\">\r\n            <%= f.select :nurse_anesth, options_for_select(n_anesth, \'\'),{:include_blank=>\'-- All --\'},:style=>\"width:180px\"%>\r\n			</div>\r\n		</span>\r\n<!--\r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">Firstname :  </label>\r\n			<div class=\"field-input\"><%# f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%></div>\r\n		</span>\r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">Lastname : </label>\r\n		    <div class=\"field-input\"><%# f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%></div>\r\n		</span>\r\n-->		\r\n<!--\r\n		<div class=\"clear\"></div>\r\n		<span> \r\n			<label class=\"field-label\">Operative : </label>\r\n			<div class=\"field-input\" style=\"width:200px\"><%= f.text_field :operative, :value=>operative,:style=>\"width:180px\"%></div>\r\n		</span>\r\n		<span> \r\n			<label class=\"field-label\" style=\"width:120px\">Diagnosis : </label>\r\n			<div class=\"field-input\" ><%= f.text_field :diagnosis, :value=>operative,:style=>\"width:180px\"%></div>\r\n		</span>\r\n-->\r\n		<div class=\"clear\"></div>\r\n        <!--<hr/>-->\r\n<!--\r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">Time : </label>\r\n			<div class=\"field-input\"><%# f.select :operative, options_for_select([\'\',\'official time\',\' non-official time\']),{},:style=>\"width:100%\"%></div>\r\n		</span>\r\n					\r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">by case type  :  </label>\r\n			<div class=\"field-input\"><%# f.text_field :case_type, :value=>s_case_type,:style=>\"width:100%\"%></div>\r\n		</span>\r\n-->						\r\n		<span> \r\n			<label class=\"field-label\">ASA Status : </label>\r\n			<div class=\"field-input\" style=\'width:50px\'><%= f.select :asa_status, options_for_select(s_asa),{},:style=>\"width:50px\"%></div>\r\n		</span>\r\n		<span > \r\n			<label class=\"field-label\">ASA Type  : </label>\r\n			<div class=\"field-input\" style=\'width:80px\'><%= f.select :asa_type, options_for_select(t_asa),{},:style=>\"width:50px\"%></div>\r\n		</span>\r\n		<span class=\"field-data\" style=\"width: 300px;\"> \r\n			<label class=\"field-label\">Anesth&nbsp;Technique&nbsp;:  </label>\r\n			<div class=\"field-input\" style=\"margin-left: 50px;width:160px\"><%= f.select :anesth_tech, options_for_select(anesth_tech),{:include_blank=>\'-- All --\'},:style=>\"width:100%\"%></div>\r\n		</span>\r\n		<div class=\"clear\"></div>\r\n		<span class=\"field-data\" style=\"width: 300px;\"> \r\n			<label class=\"field-label\">Anesthetic&nbsp;Duration&nbsp;: </label>\r\n			<div class=\"field-input\" style=\"margin-left: 50px;\"><%= f.select :anesth_dura, options_for_select(anesth_dura),{:include_blank=>\'-- All --\'},:style=>\"width:140px\"%></div>\r\n		</span>\r\n		<span class=\"field-data\" style=\"width: 300px;\"> \r\n			<label class=\"field-label\" style=\"width:130px\">Official/Non-Official : </label>\r\n			<div class=\"field-input\" style=\"margin-left: 0px;\"><%= f.select :duration_field, options_for_select(duration_field),{},:style=>\"width:160px\"%></div>\r\n		</span>\r\n		<div class=\"clear\"></div>\r\n		<span class=\"field-data\" style=\"width: 300px;\"> \r\n			<label class=\"field-label\" style=\'width:120px\'>Pain Management : &nbsp;</label>\r\n			<div class=\"field-input\" style=\"margin-left: 10px;\"><%= f.select :pain_manage, options_for_select(pain_manage),{},:style=>\"width:140px\"%></div>\r\n		</span>\r\n		<span> \r\n			<label class=\"field-label\">Case Type : </label>\r\n			<div class=\"field-input\" style=\"width:200px\">\r\n                <%= f.select :case_type, options_for_select(case_type, \'\'),{},:style=>\"width:205px\"%>\r\n			</div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n		<br/>\r\n		<span style=\'float:right\'> \r\n			<div>\r\n				<%= link_to \'Close\', \'javascript:void(0)\', :class=>\'btn\', \'data-dismiss\'=>\'modal\' %>\r\n				<%=f.submit \'Search\', :class=>\'btn btn-success\', :input_html=>{\'data-dismiss\'=>\"modal\"}%> \r\n			</div>\r\n		</span>\r\n<script>\r\n    $(\"#sdate\").kendoDatePicker({\r\n    	value: \'<%= s_date.beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n    $(\"#edate\").kendoDatePicker({\r\n    	value: \'<%= s_date.end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n</script>\r\n<% end %>    \r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n    \r\n    function doSearch(){\r\n          $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    }\r\n       function doClose(){\r\n       \r\n     $(\'#modal\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n    \r\n    var cur_user = \"<%= !@current_user.nil? ? @current_user.login : @current_user.name %>\";\r\n    function update_status() {\r\n        var tmp = $(this);\r\n        var status = $(this).val().toString();\r\n        oid = $(this).closest(\'select\').attr(\'id\');\r\n        console.log(\"STATUS : \" + status);\r\n        if(confirm(\"Are you sure to update status to \"+ $(this).val() + \" ?\")){\r\n		  //  window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n		  // id=oid&status=status&updated_by=cur_user\r\n		  //  jqxhr = $.ajax( \"update_status_with_user?id=\" + oid + \"&status=\" + status + \"&updated_by=\" + cur_user )\r\n		  jqxhr = $.ajax( \"update_status?id=\" + oid + \"&status=\" + status )\r\n              .done(function() {\r\n                // alert( \"success\" );\r\n                // $(\'#user-\' + oid).text(cur_user);\r\n                <% if @current_role == \'developer\' %>\r\n                if (status.toLowerCase() === \'cancelled\') {\r\n                    tmp.closest(\'tr\').addClass(\"cancel\");\r\n                } else {\r\n                    tmp.closest(\'tr\').removeAttr( \"class\" );\r\n                }\r\n                <% end %>\r\n                \r\n              })\r\n              .fail(function() {\r\n                alert( \"Update status fail. Please try again.\" );\r\n              })\r\n              .always(function() {\r\n                // alert( \"complete\" );\r\n              });\r\n            // console.log(jqxhr);\r\n	    }\r\n    }\r\n    function reset_locker() {\r\n        var url = \'../Locker/reset\'\r\n        if(confirm(\"Do you want to reset all locker system ?\")){\r\n		  //  window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n		  // id=oid&status=status&updated_by=cur_user\r\n		    jqxhr = $.ajax( url )\r\n              .done(function() {\r\n                alert( \"All locker reset.\" );\r\n              })\r\n              .fail(function() {\r\n                alert( \"Reset fail. Try again.\" );\r\n              })\r\n              .always(function() {\r\n                // alert( \"complete\" );\r\n              });\r\n            // console.log(jqxhr);\r\n	    }\r\n    }\r\n    $(document).ready(function() {\r\n        $(\'.status_cls\').change(update_status);\r\n        $(\'#reset\').click(reset_locker);\r\n    });\r\n    refresh();\r\n</script>\r\n<div class=\"alert \">\r\n\r\n<!--\r\nLinks : \r\n<%# link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%# link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%# link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%# link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%#link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n-->\r\nCopyright 2015 - E.S.M.Solution Co.,Ltd.\r\n    <span style=\"float:right\">\r\n        Useful Link : <%= link_to \'Daily Report\', \"../Report/daily_report_result?query[sdate]=\\\\#{s_date.strftime(\'%d/%m/%Y\')}\", :target=>\"_blank\" %> | \r\n        <%= link_to \'Monthly Report\', \"../Report/monthly_report_result?query[sdate]=\\\\#{s_date.at_beginning_of_month.strftime(\'%d/%m/%Y\')}&query[edate]=\\\\#{s_date.at_end_of_month.strftime(\'%d/%m/%Y\')}\", :target=>\'_blank\' %> |\r\n        <%= link_to \'Dr. OT Report\', \"../Report/dr_report_excel?query[sdate]=\\\\#{s_date.at_beginning_of_month.strftime(\'%d/%m/%Y\')}&query[edate]=\\\\#{s_date.at_end_of_month.strftime(\'%d/%m/%Y\')}\", :target=>\'_blank\' %> | \r\n        <%= link_to \'Staff OT Report\', \"../Report/staff_report_excel?query[sdate]=\\\\#{s_date.at_beginning_of_month.strftime(\'%d/%m/%Y\')}&query[edate]=\\\\#{s_date.at_end_of_month.strftime(\'%d/%m/%Y\')}\", :target=>\'_blank\' %>\r\n    </span>\r\n</div>',NULL,NULL,NULL,'2015-05-25 03:39:35','2015-05-25 03:39:35','index_dev2',''),(1586,'document_name',718,1,'\'report_of_ct_pns\'',NULL,NULL,NULL,'2015-05-27 04:14:24','2015-05-27 04:14:24',NULL,NULL),(1587,'form',718,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<%\r\n#a1 >>> CT template fungus ball\r\n#a2 >>> CT template IP\r\n#a3 >>> CT template JNA\r\n#a4 >>> CT template malignant\r\n#a5 >>> CT template rhinosinusitis\r\n%>\r\n<%\r\na1 = \"<p><span style=\'text-decoration:underline;\'></span></p>\r\n<p><span style=\'text-decoration:underline;\'></span></p>\r\n<p><span style=\'text-decoration:underline;\'>Fungal ball </span></p>\r\n<p>The study reveals heterogenous hypo- and hyperdense lesion\r\noccupying entire <span style=\'background:yellow;\'>(left/right)</span>\r\nmaxillary sinus. Hyperostosis of sinus wall of <span style=\'background:yellow;\'>(left/right)</span> maxillary sinus is observed.\r\nCalcification within the sinus is detected. Obstruction of <span style=\'background:yellow;\'>(left/right)</span> OMU is\r\nrevealed. Fungus ball of <span style=\'background:yellow;\'>(left/right)</span>\r\nmaxillary sinus is likely. Other paranasal sinuses are unremarkable.&nbsp; </p>\r\n<p><span style=\'text-decoration:underline;\'>Impression </span></p>\r\n<p>-A heterogenous hypo- and hyperdense lesion occupying entire\r\n<span style=\'background:yellow;\'>(left/right)</span>\r\nmaxillary sinus with hyperostosis of sinus wall and calcification within the\r\nsinus is observed. Fungus ball of <span style=\'background:yellow;\'>(left/right)</span> maxillary sinus is likely.</p>\r\n<p>-The lesion is obliterating <span style=\'background:yellow;\'>(left/right)</span> OMU </p>\"\r\n\r\na2 = \"<p><span style=\'text-decoration:underline;\'></span></p>\r\n<p><span style=\'text-decoration:underline;\'>Inverted papilloma </span></p>\r\n<p>The study reveals heterogenous enhancing soft tissue lesion\r\noccupying epicenter of ….. Periosteal reaction is observed at …..</p>\r\n<p>Extension</p>\r\n<p>-Anterior extension passes into <span style=\'background:yellow;\'>(left/right)</span> nasal vestibule with\r\nobstruction of <span style=\'background:yellow;\'>(left/right)</span>\r\nnostril</p>\r\n<p>-Posterior extension downs through <span style=\'background:yellow;\'>(left/right)</span> nasal choanae </p>\r\n<p>-Medial extension causes bone remodeling and erosion of <span style=\'background:yellow;\'>(left/right)</span> uncinate\r\nprocess, lateral nasal wall and nasal septum with <span style=\'background:yellow;\'>(left/right)</span> nasal deviation </p>\r\n<p>-Lateral extension abuts lateral wall of <span style=\'background:yellow;\'>(left/right)</span> maxillary\r\nsinus, lamina papyracea</p>\r\n<p>-Superior extension passes into <span style=\'background:yellow;\'>(left/right)</span> frontal sinus.</p>\r\n<p>The lesion also obliterates paranasal structure including <span style=\'background:yellow;\'>(left/right)</span> frontal\r\nrecess, maxillary ostium, maxillary infundibulum, OMU and SER </p>\r\n<p><span style=\'background:yellow;\'>(Total/\r\npartial)</span> opacification of <span style=\'background:yellow;\'>(left/right)</span> maxillary sinus, ethmoid sinus, sphenoid sinus, frontal\r\nsinuses, likely sinusitis. The rest of visualized paranasal sinuses and\r\nbilateral mastoid air are clear.</p>\r\n<p><span style=\'text-decoration:underline;\'>Impression </span></p>\r\n<p>-A heterogenous enhancing soft tissue lesion occupying\r\nepicenter of … with extension and bony remodeling as mentioned above. Inverted\r\npapilloma is likely.</p>\r\n<p>- Maxillary sinus, ethmoid sinus, sphenoid sinus, frontal\r\nsinuses, sinusitis </p>\"\r\n\r\na3 = \"<p><span style=\'text-decoration:underline;\'></span></p>\r\n<p><span style=\'text-decoration:underline;\'></span></p>\r\n<p><span style=\'text-decoration:underline;\'>JNA </span></p>\r\n<p>The study reveals large homogenous enhancing mass involving <span style=\'background:yellow;\'>(left/right)</span>\r\npterygopalatine fossa, sphenopalatine foramen, pterygomaxillary fissure,\r\nposterior aspect of <span style=\'background:yellow;\'>(left/right)</span>\r\nnasal cavity, <span style=\'background:yellow;\'>(left/right)</span>\r\nvidian canal, foramen rotundum, infratemporal fossa, nasopharynx and oropharynx.\r\nExpansile bone lesions of posterior wall of maxillary sinus and greater wing of\r\nright sphenoid bone are observed. </p>\r\n<p>Soft tissue densities in <span style=\'background:yellow;\'>(bilateral/ left/ right)</span> maxillary, <span style=\'background:yellow;\'>(bilateral/ left/ right)</span>\r\nethmoid, <span style=\'background:yellow;\'>(bilateral/ left/\r\nright)</span> frontal and <span style=\'background:yellow;\'>(bilateral/\r\nleft/ right)</span> sphenoid sinuses are detected. The rest of visualized\r\nparanasal sinuses are clear. </p>\r\n<p>The brain parenchyma is of normal attenuation without space occupying\r\nlesion.</p>\r\n<p><span style=\'text-decoration:underline;\'>Impression </span></p>\r\n<p>-A mass involving&nbsp; <span style=\'background:yellow;\'>(left/right)</span>\r\npterygopalatine fossa, sphenopalatine foramen, pterygomaxillary fissure,\r\nposterior aspect of <span style=\'background:yellow;\'>(left/right)</span>\r\nnasal cavity, <span style=\'background:yellow;\'>(left/right)</span>\r\nvidian canal, foramen rotundum, infratemporal fossa, nasopharynx and oropharynx\r\nassociated with expansile bone lesions of posterior wall of maxillary sinus</p>\r\n<p>-Juvenile nasopharyngeal angiofibroma is likely.</p>\"\r\n  \r\na4 = \"<p><span style=\'text-decoration:underline;\'></span></p>\r\n<p><span style=\'text-decoration:underline;\'>Malignant tumor</span></p>\r\n<p>The study reveals hetrogenously enhancing hypodense mass\r\noccupying entire <span style=\'background:yellow;\'>(left/right)</span>\r\nnasal cavity </p>\r\n<p>Extension</p>\r\n<p>-Anterior extension passes into <span style=\'background:yellow;\'>(left/right)</span> pyriform aperture and\r\nnasolacrimal duct</p>\r\n<p>-Posterior extension downs through <span style=\'background:yellow;\'>(left/right)</span> posterior choana into\r\nnasopharygeal airway and bulging into <span style=\'background:yellow;\'>(left/right)</span> sphenoid sinus</p>\r\n<p>-Medial extension causes bone erosion of <span style=\'background:yellow;\'>(left/right)</span> uncinate\r\nprocess, lateral nasal wall and nasal septum </p>\r\n<p>-Lateral extension through<span style=\'background:yellow;\'> (left/right)</span> sphenopalatine foramen to <span style=\'background:yellow;\'>(left/right)</span>\r\npterygopalatine fossa</p>\r\n<p>-Superior extension passes into <span style=\'background:yellow;\'>(left/right)</span> frontal sinus with destruction\r\nof <span style=\'background:yellow;\'>(left/right)</span>\r\ncribiform plate and suspected intracranial extension.</p>\r\n<p>Demineralization of …… are found. Bony destruction of … are\r\nobserved. Bony defects at …. with soft tissue extension in <span style=\'background:yellow;\'>(left/right)</span> extraconal\r\nfat abutting <span style=\'background:yellow;\'>(medial/superior)</span>\r\nrectus muscle including orbital apex is detected. Defect at cribiform plate\r\nwith suspected intracranial extension is observed.Defect at inferomedial wall\r\nof <span style=\'background:yellow;\'>(left/right)</span>\r\nsphenoid sinus with soft tissue extension into nasopharyngeal roof is seen.</p>\r\n<p>The mass obliterates <span style=\'background:yellow;\'>(left/right)</span> maxillary ostium, OMU, SER, frontal\r\nrecess. There is non-enhancing hyper-hypodense soft tissue occupying <span style=\'background:yellow;\'>(left/right)</span> maxillary,\r\nfrontal, sphenoid and ethmoid sinuses ,likely infection/inflammation process. </p>\r\n<p>The rest of <span style=\'background:yellow;\'>(left/right)</span> orbit appear unremarkable </p>\r\n<p><span style=\'background:yellow;\'>(left/right)</span>\r\npterygopalatine fossa, pterygomaxillary fissures, vidian canals, foramen\r\nrotundums, and grater palatine foramina are patent </p>\r\n<p><span style=\'text-decoration:underline;\'>Impression </span></p>\r\n<p>-A heterogenously enhancing hypodense mass occupying entire <span style=\'background:yellow;\'>(left/right)</span> nasal cavity\r\nand adjacent bony destruction with extension as described, possibly malignant sinonasal\r\ntumor &nbsp;</p>\r\n<p>-The mass causes destruction of <span style=\'background:yellow;\'>(left/right)</span> cribiform plate with suspected\r\nminimal intracranial extension </p>\r\n<p>-Obliteration of <span style=\'background:yellow;\'>(left/right)</span> maxillary ostium, OMU, frontal recess and SER by\r\nmass </p>\r\n<p>- non-enhancing hyper-hypodense soft tissue occupying <span style=\'background:yellow;\'>(left/right)</span> maxillary,\r\nfrontal, sphenoid and ethmoid sinuses ,likely infection/inflammation process.&nbsp;</p>\"\r\n  \r\na5 = \"<p><span style=\'text-decoration:underline;\'>Rhinosinusitis &nbsp;</span></p>\r\n<p>The study reveals <span style=\'background:yellow;\'>(mucosal thickening/ fluid level/ high proteinaceous contents/ total\r\nopacification)</span> in <span style=\'background:yellow;\'>(bilateral/\r\nleft/ right)</span> maxillary, <span style=\'background:yellow;\'>(bilateral/ left/ right)</span> ethmoid, <span style=\'background:yellow;\'>(bilateral/ left/ right)</span> frontal and <span style=\'background:yellow;\'>(bilateral/ left/ right)</span>\r\nsphenoid sinuses. </p>\r\n<p>There are non-enhancing lobulated soft tissue density\r\nlesions in <span style=\'background:yellow;\'>(bilateral/\r\nleft/ right)</span> nasal cavities. Nasal polyps are possible. There are mucous\r\nretention cyst in the <span style=\'background:yellow;\'>(….)</span>\r\nsinus.</p>\r\n<p>Obstructions of <span style=\'background:yellow;\'>(bilateral/ left/ right)</span> frontal recesses, <span style=\'background:yellow;\'>(bilateral/ left/ right)</span>\r\nOMU and <span style=\'background:yellow;\'>(bilateral/ left/\r\nright)</span> SER are detected. Sclerotic thicken wall of the <span style=\'background:yellow;\'>(….)</span> sinus are shown. Post-surgical\r\nsinus cavities are observed.</p>\r\n<p>&nbsp;<span style=\'text-decoration:underline;\'>Impression </span></p>\r\n<p>-Rhinosinusitis of ….. sinuses</p>\r\n<p>-Obstruction of … sinus drainage pathway </p>\r\n<p>-<span style=\'background:yellow;\'>Bilateral</span>\r\nnasal polyps </p>\"  \r\n\r\n\r\n%>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\"#data-select_template\").change(function(){\r\n            var editor = $(\"#data-print_out_report\").data(\"kendoEditor\"); \r\n            // console.log(editor);\r\n            console.log($(this).val());\r\n            var v = $(this).val();\r\n            if (v == \"1\") {\r\n                editor.value(\"<%= a1.tr(\"\\n\",\"\").html_safe %>\");\r\n            } else if (v == \"2\") {\r\n                editor.value(\"<%= a2.tr(\"\\n\",\"\").html_safe %>\");\r\n            } else if (v == \"3\") {\r\n                editor.value(\"<%= a3.tr(\"\\n\",\"\").html_safe %>\");\r\n            } else if (v == \"4\") {\r\n                editor.value(\"<%= a4.tr(\"\\n\",\"\").html_safe %>\");\r\n            } else if (v == \"5\") {\r\n                editor.value(\"<%= a5.tr(\"\\n\",\"\").html_safe %>\");\r\n            } else {\r\n                editor.value(\'Your text here, or select the template.\');\r\n            }\r\n        });\r\n    });\r\n</script>',NULL,NULL,NULL,'2015-05-27 04:18:19','2015-05-27 04:18:19','form',''),(1590,'list',719,3,'<% @esm_template = \'inspinia\' %>\r\n<%\r\n   model = get_model(this.table_name)\r\n   records = []\r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   \r\n    if params[:search]\r\n        records = model.all(params[:search][:criteria])\r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n       records = model.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n    end\r\n   \r\n%>\r\n\r\n<%= tabular :model=>labels,:title=>@current_service.title, :data=>records do |i,out|\r\n\r\nfields.each_with_index do |f,index|\r\n\r\nout[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n\r\nend\r\nout<<link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nout<<link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\')\r\nout<<link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:confirm=>\'Are you sure?\')\r\nout\r\nend\r\n%>\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2015-05-27 14:50:08','2015-05-27 14:50:08','list',''),(1592,'layout',721,4,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        \r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n			\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_