e</b></a></li>\r\n	                                    <!--\r\n	                                    <li class=\"dropdown\">\r\n                                            <a data-toggle=\"dropdown\" class=\"dropdown-toggle\"><i class=\"icon-list-alt icon-white\"></i> <b>Admin</b> <b class=\"caret\"></b></a>\r\n		                                    <ul class=\"dropdown-menu\">\r\n				                                <li><a href=\"../User/index\"><b>User</b></a></li><li><a href=\"../Role/index\"><b>Role</b></a></li>\r\n			                                </ul>\r\n		                                </li>\r\n		                                -->\r\n		                                <li class=\"dropdown\">\r\n                                            <a data-toggle=\"dropdown\" class=\"dropdown-toggle\">\r\n                                                <i class=\"icon-list-alt icon-white\"></i> \r\n                                                <b>Document Form</b> <b class=\"caret\"></b>\r\n                                            </a>\r\n		                                    <ul class=\"dropdown-menu\">\r\n				                                <li><a href=\"/esm/taig/www/content/form/Hip1.docx\" target=\'_blank\'>Primary Hip (docx)</a></li>\r\n				                                <li><a href=\"/esm/taig/www/content/form/Knee1.docx\" target=\'_blank\'>Primary Knee (docx)</a></li>\r\n				                                <li class=\"divider\"></li>\r\n				                                <li><a href=\"/esm/taig/www/content/form/Hip1.pdf\" target=\'_blank\'>Primary Hip (pdf)</a></li>\r\n				                                <li><a href=\"/esm/taig/www/content/form/Knee1.pdf\" target=\'_blank\'>Primary Knee (pdf)</a></li>\r\n				                                <li class=\"divider\"></li>\r\n				                                <li><a href=\"/esm/taig/www/content/form/PrimaryForm.zip\" target=\"_blank\">Primary Hip/Knee (docx/pdf)</a></li>\r\n			                                