 <!--<img src=\"/esm/taig/www/content/web-logo_mini-logo.png\" height=\"80px\"/>-->\r\n                                        <img src=\'<%= logo %>\' height=\'80px\'/>\r\n                                    </a>\r\n                    </div>\r\n					<div class=\"span4\">\r\n					    <span style=\"float:right;color:#efefef;font-size:1.2em;text-align:right;margin-top:10px\" >\r\n\r\n                            Welcome : <span style=\"color:lightgray\"><%= prov.nil? ? @current_user.login : \"\\\\#{prov[:name]} (\\\\#{@current_user.login})\" %></span>\r\n                            <div style=\"padding-top:5px\"></div>\r\n                            <%= \" <a href=\'/esm_projects/\\\\#{@current_project.id}\' class=\'btn btn-mini\' target=\'_blank\'>dev</a> | \".html_safe if @current_role==\'developer\' %> \r\n                            <%=link_to \'<i class=\"splashy-sprocket_dark\"></i> Setting\'.html_safe, \'../Setting/index\', :class=>\'btn btn-mini\', :style=>\'width:60px\' %> |\r\n                            <%=link_to \'Logout <i class=\"splashy-media_controls_play_small\"></i>\'.html_safe, \'/user/logout\', :class=>\'btn btn-mini\', :style=>\'width:60px\' %>\r\n                            <div style=\"padding-top:5px\"></div>\r\n                            <%=link_to \'Home <i class=\"splashy-home_green\"></i>\'.html_safe, \'../Home/index\', :class=>\'btn btn-mini\', :style=>\'width:60px\' %>\r\n                        </span>\r\n					</div>\r\n				</div>\r\n<% end %>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'clear\'>&nbxp;</div>\r\n</div>\r\n<br/>\r\n<br/>\r\n<%\r\n    if @current_role==\'developer\'\r\n%>\r\n\r\n<%\r\n    end\r\n%>\r\n<div class=\"row-fluid mm\">\r\n    <div class=\"span12\">\r\n\r\n				   <%= yield %><%= yield :content%>\r\n                \r\n        </div>\r\n    </div>\r\n    <div class=\"alert\">Power by <%= link_to \'E.S.M.Solution Co.,Ltd.\', \'https://esm-solution.com\', :target=>\'_blank\' %></div> \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n     		<div id=\"context-menu\" class=\"accordion\">\r\n             <%= render :partial=>\'/layouts/context_menu\'%>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n			$(\'#search-field\').focus();\r\n		</script>		\r\n<%\r\n    auto_logout = false\r\n    if auto_logout\r\n%>\r\n<script>\r\nvar IDLE_TIMEOUT = 15*60; //seconds\r\nvar _idleSecondsCounter = 0;\r\ndocument.onclick = function() {\r\n    _idleSecondsCounter = 0;\r\n};\r\ndocument.onmousemove = function() {\r\n    _idleSecondsCounter = 0;\r\n};\r\ndocument.onkeypress = function() {\r\n    _idleSecondsCounter = 0;\r\n};\r\nwindow.setInterval(CheckIdleTime, 1000);\r\n\r\nfunction CheckIdleTime() {\r\n    _idleSecondsCounter++;\r\n    var oPanel = document.getElementById(\"SecondsUntilExpire\");\r\n    if (oPanel)\r\n        oPanel.innerHTML = (IDLE_TIMEOUT - _idleSecondsCounter) + \"\";\r\n    if (_idleSecondsCounter >= IDLE_TIMEOUT) {\r\n        alert(\"Session expired!\");\r\n        document.location.href = \"/user/logout\";\r\n    }\r\n}\r\n</script>\r\n<%\r\n    end\r\n%>\r\n<%= include_essential %>\r\n    \r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-05-27 16:35:00','2015-05-27 16:35:00','layout',''),(1593,'show',268,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;max-width:750px\">\r\n\r\n<%\r\n\r\n   @document =  get_document this.document_name \r\n   \r\n   model = get_model(this.table_name)\r\n   @patient_module = @module_model.find(params[:id])\r\n   record = model.find(@patient_module.module_id)\r\n   @record = record    \r\n  if request.post?\r\n    \r\n   \r\n    if p = params[\'cancel_\']\r\n        \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            old_app.destroy\r\n            mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>nil\r\n   \r\n    elsif p = params[\'postpone_\']\r\n    \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            # old_app.destroy\r\n            # mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        \r\n        \r\n        new_app = record.clone\r\n        new_app.update_attributes :date=>p[0][\'postpone_to\'],:status=>\'Appointed\'\r\n        \r\n        mm = @patient_module.clone\r\n        mm.module_id = new_app.id \r\n        mm.save    \r\n        \r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>p[0][\'postpone_to\'], :postpone_id=>new_app.id\r\n       \r\n        \r\n        \r\n    end\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Home/index\" />\r\n<% end %>\r\n<%= this.display.html_safe %>\r\n\r\n<div id=\"cancel\" style=\"display:none\"  class=\"alert alert-warning\">\r\n   <p>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'cancel_\'\r\n        field = @document.find_by_column_name \'cancel_reason\'\r\n        begin\r\n        %>\r\n        \r\n        <%#field%>\r\n        <div>\r\n        \r\n        <h3>Cancel</h3><br/>\r\n        <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Cancelled\' %>\r\n        </div>\r\n        <script>\r\n        <%= yield :script %>\r\n        \r\n      \r\n        </script>\r\n        <% rescue Exception=>e %>\r\n        <%=e.message%>\r\n        <% end%>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n</div>\r\n\r\n<div id=\"postpone\" style=\"display:none;padding:10px\" class=\"alert alert-warning\">\r\n   \r\n      <p>\r\n        <h3>Postpone</h3><br/>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'postpone_\'\r\n        %>\r\n        <div>\r\n        \r\n       <% field = @document.find_by_column_name \'cancel_reason\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n       <% field = @document.find_by_column_name \'postpone_to\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Postpone\' %>\r\n        </div>\r\n       \r\n       \r\n        <script>\r\n        <%= yield :script %>\r\n        </script>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n   \r\n   \r\n</div>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Cancel\'.html_safe, \"javascript:cancel()\",:class=>bt_class %> | \r\n<%= link_to \'Postpone\'.html_safe, \"javascript:postpone()\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    \r\n    function cancel(){\r\n        $(\'#postpone\').hide()\r\n        $(\'#cancel\').slideDown()\r\n        $(\'#cancel_cancel_reason\').show()\r\n        \r\n    }\r\n    \r\n    function postpone(){\r\n        $(\'#cancel\').hide()\r\n        $(\'#postpone\').slideDown()\r\n        $(\'#postpone_postpone_to\').show()\r\n\r\n    }\r\n    \r\n    function cancel_ctrl(){\r\n        $(\'#postpone\').slideUp()\r\n        $(\'#cancel\').slideUp()\r\n    }\r\n    $(\'.ctrl\').hide();\r\n</script>',NULL,NULL,NULL,'2015-05-27 18:44:30','2015-05-27 18:44:30','show',''),(1594,'help',574,3,'<%\r\n    rs = {}\r\n    rs[:api] = [\'attach_image_by_admit_id\', \'get_image_capture_by_admit_id\', \'get_today_patients\', \'get_today_patient_by_hn\']\r\n%>\r\n<%= rs.to_json.html_safe %>',NULL,NULL,NULL,'2015-05-28 05:39:14','2015-05-28 05:39:14','help','*'),(1595,'export_endoscopist',490,3,'<%\r\n    @models = get_model\r\n    \r\n    m_provider = @models[:provider].all\r\n    h_prov = {}\r\n    for x in m_provider\r\n        h_prov[x.id] = x[:name]\r\n    end\r\n    \r\n    m_doc = @models[this.document_name.to_sym]\r\n    \r\n    \r\n    rs = []\r\n    for x in h_prov.keys\r\n        c = m_doc.where(:endoscopist=>x.to_s).count\r\n        rs<<[h_prov[x], c]\r\n    end\r\n    \r\n    zs = {}\r\n    zs[:provider] = h_prov\r\n    zs[:all] = m_doc.count\r\n    zs[:result] = rs\r\n%>\r\n<%= zs.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2015-05-28 06:38:17','2015-05-28 06:38:17','export_endoscopist','*'),(1596,'form',480,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n    \r\n    pid = \'\'\r\n    if params[:id]\r\n        pid = @module_model.find(params[:id])[:patient_id].to_s # patient_id\r\n    else\r\n        pid = params[:patient_id]\r\n    end\r\n    r_patient = @patient_model.find(pid)\r\n    \r\n    result = {}\r\n    models = get_model\r\n    m_outcome = models[:summary_form]\r\n    pm_outcome = @module_model.where(:patient_id=>pid, :module_name=>\"\\\\#{@current_project.name}#summary_form\").first\r\n    r_outcome = nil\r\n    if pm_outcome\r\n        r_outcome = m_outcome.find(pm_outcome[:module_id])\r\n        result[:outcome] = r_outcome\r\n    end\r\n        \r\n    m_case_record = models[:case_record]\r\n    r_case_record = {}\r\n    pm_case_record = @module_model.where(:patient_id=>pid, :module_name=>\"\\\\#{@current_project.name}#case_record\").collect do |i|\r\n        mid = i.module_id\r\n        x = m_case_record.find(i.module_id)\r\n        # if x[:record_day] == \'1\' or x[:record_day] == \'2\' or x[:record_day] == \'3\'\r\n            r_case_record[x[:record_day]] = x\r\n        # end\r\n        if x[:urine_output_cal] != \"NaN\"\r\n            x[:urine_output_cal].to_f\r\n        end\r\n        # if x[:urine_output_cal] == \'NA\'\r\n        #     x[:urine_output_cal]\r\n        # elsif x[:urine_output_cal] != \"NaN\"\r\n        #     x[:urine_output_cal].to_f\r\n        # end\r\n    end\r\n    \r\n    # result[:field] = \'urine_output_cal\'\r\n    result[:pm_id] = params[:id]\r\n    result[:pid] = pid\r\n    # result[:r_case_record] = r_case_record\r\n    # result[:pm_case_record] = pm_case_record.delete_if{|v| v == \'NA\'}\r\n    result[:case_record] = pm_case_record[0,pm_case_record.length-1].compact.sort\r\n    min = 0\r\n    if result[:case_record].size != 0\r\n        min = result[:case_record][0]\r\n    end\r\n    \r\n    true_base_line_cr = r_patient[:baseline_serum_cr]\r\n    mdrd = r_patient[:baseline_serum_creainine_by_mdrd]\r\n    admission_cr = r_case_record[\'1\'][:creatinine]\r\n    \r\n    arr = [true_base_line_cr.to_f, mdrd.to_f, admission_cr.to_f].sort\r\n    # ref_cr = arr[0] == 0.0 ? arr[1] : arr[0]\r\n    ref_cr = true_base_line_cr.to_f\r\n    if ref_cr == 0\r\n        if mdrd.to_f == 0\r\n            ref_cr = admission_cr.to_f\r\n        elsif admission_cr.to_f == 0\r\n            ref_cr = mdrd.to_f\r\n        elsif mdrd.to_f < admission_cr.to_f\r\n            ref_cr = mdrd.to_f\r\n        else\r\n            ref_cr = admission_cr.to_f\r\n        end\r\n    end\r\n    \r\n    result[:min_urine] = result[:case_record][0]\r\n    result[:patient] = r_patient\r\n    result[:r_case_record] = r_case_record\r\n    result[:arr] = arr\r\n    \r\n    map_status = {}\r\n    map_status[\'0\'] = \'Stay in ICU\'\r\n    map_status[\'1\'] = \'Move out\'\r\n    map_status[\'2\'] = \'Death\'\r\n    \r\n    r_case_record.each do |k, v|\r\n        cr = v[:creatinine]\r\n        if cr.to_f.to_s == cr\r\n            v[:time_cr] = (cr.to_f / ref_cr.to_f).round(4)\r\n            v[:diff_cr] = (cr.to_f - ref_cr.to_f).round(4)\r\n        else\r\n            v[:time_cr] = \"NA\"\r\n            v[:diff_cr] = \"NA\"\r\n        end\r\n        v[:status] = map_status[v[:case_status]]\r\n        \r\n        r_case_record[k] = v\r\n    end\r\n    \r\n    result[:ref_cr] = ref_cr\r\n    \r\n    # underlying disease\r\n    ud = []\r\n    if r_patient[:ht] == \'Yes\'\r\n        ud.push(\'HT\')\r\n    end\r\n    if r_patient[:dm] == \'Yes\'\r\n        ud.push(\'DM\')\r\n    end\r\n    if r_patient[:cad] == \'Yes\'\r\n        ud.push(\'CAD\')\r\n    end\r\n    if r_patient[:cerebrovascular_disease] == \'Yes\'\r\n        ud.push(\'Cerebrovascular disease\')\r\n    end\r\n    if r_patient[:malignancy] == \'Yes\'\r\n        ud.push(\'Malignancy\')\r\n    end\r\n    if r_patient[:ckd] == \'Yes\'\r\n        ud.push(\'CKD\')\r\n    end\r\n    if r_patient[:esrd] == \'Yes\'\r\n        ud.push(\'ESRD\')\r\n    end\r\n\r\n%>\r\n\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:420px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\" data-dismiss=\"modal\">X Close</a>\r\n        <h3>Message</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    \r\n        <center><font size=\'4\'>Please create the \'Outcome\'!</font></center>\r\n			\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n    $( document ).ready(function() {\r\n        // console.log( \"ready!\" );\r\n        $(\"#data-urine_output\").val(\"<%= result[:min_urine] %>\");\r\n        \r\n        $(\"#data-baseline_cr_type\").val(\"<%= ref_cr %>\");\r\n        // alert(\"<%= r_patient[:date_of_baseline_serum_cr] %>\");\r\n        $(\"#data-date_true_baseline\").val(\"<%= r_patient[:date_of_baseline_serum_cr] %>\");\r\n        $(\"#data-true_baseline_cr\").val(\"<%= r_patient[:baseline_serum_cr] %>\");\r\n        $(\"#data-mdrd\").val(\"<%= r_patient[:baseline_serum_creainine_by_mdrd] %>\");\r\n        $(\"#data-admission_cr\").val(\"<%= r_case_record[\'1\'][:creatinine] %>\");\r\n<%\r\n    r_case_record.each do |k, v| \r\n%>\r\n        $(\"#data-cr_day_<%= k %>\").val(\"<%= v[:creatinine] %>\");\r\n        $(\"#data-times_cr_day_<%= k %>\").val(\"<%= v[:time_cr] %>\");\r\n        $(\"#data-diff_cr_day_<%= k %>\").val(\"<%= v[:diff_cr] %>\");\r\n        $(\"#data-urine_output_day_<%= k %>\").val(\"<%= v[:urine_output_cal] %>\");\r\n        $(\"#data-case_status_day_<%= k %>\").val(\"<%= v[:status] %>\");\r\n        $(\"#data-rrt_day_<%= k %>\").val(\"<%= v[:if_rrt] == \'0\' ? \'RRT\' : \'\' %>\");\r\n<%\r\n    end\r\n%>\r\n\r\n        $(\'#data-diagnosis\').val(\"<%= r_patient[:diagnosis] %>\");\r\n        $(\'#data-order\').val(\"<%=r_patient[:patient_order] if !r_patient[:patient_order].nil?%>\");\r\n        $(\'#data-underlying_disease\').val(\'<%= ud.join(\', \') %>\');\r\n        \r\n        // 23/09/2015\r\n        $(\'#data-date_icu_admission\').val(\"<%= r_patient[:date_of_icu_admission] %>\");\r\n        \r\n        c1 = $(\'#data-cause_of_aki\').val();\r\n        c2 = $(\'#data-admin_cause_of_aki\').val();\r\n        if (c1 != \'4\') {\r\n            $(\'#cause_other\').hide();\r\n        } else {\r\n            $(\'#cause_other\').show();\r\n        }\r\n        if (c2 != \'4\') {\r\n            $(\'#cause_other2\').hide();\r\n        } else {\r\n            $(\'#cause_other2\').show();\r\n        }\r\n        $(\'#data-cause_of_aki\').change(check_cause_other1);\r\n        $(\'#data-admin_cause_of_aki\').change(check_cause_other2);\r\n<% if result[:outcome] %>\r\n        $(\'#data-stop_rrt_date\').val(\'<%= (!result[:outcome][:stop_rrt_date].nil?) ? result[:outcome][:stop_rrt_date].strftime(\'%d-%m-%Y\') : \'\' %>\');\r\n        $(\'#data-day_on_rrt\').val(\'<%= result[:outcome][:rrt_day] %>\');\r\n<% else %>\r\n        $(\'#record-submit\').prop(\"disabled\",true);\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        })\r\n<% end %>\r\n        // console.log( \"readz!\" );\r\n        \r\n        $(\"input[type=\'radio\']\").click(function() {\r\n          var previousValue = $(this).attr(\'previousValue\');\r\n          var name = $(this).attr(\'name\');\r\n          var data = $(\'#\' + name.replace(\"update_\", \"data-\"));\r\n          \r\n          if (previousValue == \'checked\') {\r\n            $(this).removeAttr(\'checked\');\r\n            $(this).attr(\'previousValue\', false);\r\n            data.val(\"\");\r\n          } else {\r\n            $(\"input[name=\"+name+\"]:radio\").attr(\'previousValue\', false);\r\n            $(this).attr(\'previousValue\', \'checked\');\r\n          }\r\n        });\r\n    });\r\n    \r\n    function check_cause_other1() {\r\n        val = $(this).val();\r\n        if (val === \'4\') {\r\n            $(\'#cause_other\').show();\r\n        } else {\r\n            $(\'#cause_other\').hide();\r\n        }\r\n    }\r\n    function check_cause_other2() {\r\n        val = $(this).val();\r\n        if (val === \'4\') {\r\n            $(\'#cause_other2\').show();\r\n        } else {\r\n            $(\'#cause_other2\').hide();\r\n        }\r\n    }\r\n</script>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<% if params[:test] %>\r\n<hr/>\r\n<%= result.to_json %>\r\n<% end %>\r\n\r\n<% \r\n    is_edit = false\r\n    if @current_role==\'admin\' or @current_role==\'developer\'\r\n        is_edit = true\r\n    end\r\n    if !is_edit\r\n%>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\'.auto_aki\').hide();\r\n        \r\n        $(\'#data-cr_diagnosis\').attr(\'disabled\',true)\r\n        $(\'#data-cr_diagnosis_from_day\').attr(\'disabled\',true)\r\n        $(\'#data-cr_staging\').attr(\'disabled\',true)\r\n        $(\'#data-cr_staging_from_day\').attr(\'disabled\',true)\r\n        $(\'#data-urine_output_diagnosis\').attr(\'disabled\',true)\r\n        $(\'#data-urine_output_from_day\').attr(\'disabled\',true)\r\n        $(\'#data-urine_output_staging\').attr(\'disabled\',true)\r\n        $(\'#data-urine_output_staging_from_day\').attr(\'disabled\',true)\r\n        $(\'#data-data-aki_max_staging\').attr(\'disabled\',true)\r\n        $(\'#data-aki_max_staging_from\').attr(\'disabled\',true)\r\n        $(\'#data-auto_max_staging\').attr(\'disabled\',true)\r\n    });\r\n</script>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2015-05-28 07:51:09','2015-05-28 07:51:09','form',''),(1597,'test',480,3,'<%\r\n    rid = %w{1	2	3	4	5	6	7	9	11	12	13	14	15	16	17	19	21	23	26	27}\r\n    rid.each do |i|\r\n%>\r\n<a href=\'https://rrts_<%=i%>.emr-life.com/rrts/Aki/merge\' target=\'_blank\'>RRT_<%=i%></a><br/>\r\n<%\r\n    end\r\n    \r\n    doc = get_document \'aki\'\r\n%>\r\n<%= doc.to_json.html_safe %>',NULL,NULL,NULL,'2015-05-28 08:12:41','2015-05-28 08:12:41','test','*'),(1598,'feed',522,2,'<h1>Feed</h1>',NULL,NULL,NULL,'2015-05-29 06:44:03','2015-05-29 06:44:03','feed',''),(1600,'document_name',722,1,'\'hipprimary\'',NULL,NULL,NULL,'2015-06-02 01:08:06','2015-06-02 01:08:06',NULL,NULL),(1601,'document_name',723,1,'\'hip_primary\'',NULL,NULL,NULL,'2015-06-02 01:08:34','2015-06-02 01:08:34',NULL,NULL),(1602,'remove_recheck',477,3,'<%\r\n    models = get_model\r\n    m_patient = models[:patient]\r\n    res = {}\r\n    res[:all_patients] = m_patient.all.count\r\n    \r\n    # pid_1 = \'54586eb7790f9b2fe500005b\'\r\n    # pat_1 = m_patient.find(pid_1)\r\n    # pat_1.update_attributes(:recheck=>\'false\')\r\n    \r\n    # pid_2 = \'553d948d790f9b3e51000009\'\r\n    # pat_2 = m_patient.find(pid_2)\r\n    # pat_2.update_attributes(:recheck=>\'false\')\r\n    # res[:patient_1] = pat_1\r\n    # res[:patient_2] = pat_2\r\n    \r\n    \r\n    \r\n    for pat in m_patient.all do\r\n        pat.update_attributes(:recheck=>\'false\')\r\n    end\r\n    res[:update] = \'Sucess\'\r\n    # res[:all_patient] = m_patient.all\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-06-02 07:11:48','2015-06-02 07:11:48','remove_recheck','');
INSERT INTO `esm_operations` VALUES (1603,'case_report',522,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Monthly Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    params_date = select_date\r\n    select_date = Date.to_mongo(select_date)\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nSelect : <%= f.date_select :date, :default=>select_date ,:discard_day=>true , :order=>[:month,:year]%>\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n    ipds = 0 \r\n    opds = 0 \r\n    \r\n    total_patho = 0\r\n \r\n \r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    select_date = Date.to_mongo(select_date)\r\n    start_date = select_date.beginning_of_month()\r\n    stop_date = select_date.end_of_month()\r\n    \r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    other_status = {\'Cancelled\'=>0,\'Postpone\'=>0}\r\n    ipd_opd = {}\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n         # all pm colono of those appointments\r\n    all_pm_prescope = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}pre_scope\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_prescope = bmap all_pm_prescope, \'parent_id\'\r\n    \r\n    \r\n    colo_scope = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n    cs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n    for i in colo_scope\r\n        cs[i] = 1\r\n    end\r\n\r\n    gastro_scope = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n    gs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n       \r\n    for i in gastro_scope\r\n        gs[i] = 1\r\n    end     \r\n    \r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>cs}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>gs}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n \r\n    prescope = @models[:pre_scope].collection.find({:_id=>{\'$in\'=>all_pm_prescope.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'type_of_patient\'=>1 }}).to_a\r\n    m_prescope = bmap prescope, \'_id\'\r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    for app in all_app\r\n    \r\n        other_status[app[\'status\']] = 0 unless other_status[app[\'status\']]\r\n        other_status[app[\'status\']] += 1 \r\n        \r\n        \r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                prescope = m_all_pm_prescope[pm_app[\'_id\']]\r\n                \r\n                \r\n                p_colo = nil\r\n                p_gastro = nil\r\n                \r\n                r_colo = nil\r\n                r_gastro = nil\r\n                \r\n                \r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                        status = r_colo[0][\'status\']\r\n                        p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    if r_gastro\r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                 \r\n                patho_count = 0 \r\n                \r\n                \r\n                \r\n                if r_colo and r_colo[0]\r\n                    \r\n                    xls = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n                    xms = \'colonoscopy_scope\'\r\n                    xdata = r_colo[0]\r\n            \r\n                xls.each{|lc|\r\n                \r\n                    if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n             \r\n                        xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                        for li in xll\r\n                            patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                   \r\n                        end\r\n                    \r\n                    end\r\n                }\r\n                \r\n                end\r\n                \r\n                \r\n                if r_gastro and r_gastro[0]\r\n                    \r\n                    xls = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n                    xms = \'gastroscopy_scope\'\r\n                    xdata = r_gastro[0]\r\n                \r\n                xls.each{|lc| \r\n                    if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n                        xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                        for li in xll\r\n                            patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                        end\r\n                    \r\n                    end\r\n                }\r\n                \r\n                end\r\n                \r\n                \r\n                total_patho += patho_count\r\n        \r\n                \r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n            \r\n                dates[date][\'no_specimen\'] = 0 unless dates[date][\'no_specimen\']\r\n                dates[date][\'no_specimen\'] += patho_count\r\n            \r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                \r\n                \r\n                \r\n                \r\n                if prescope and prescope = prescope[0]  and prescope and colo or gastro\r\n                    \r\n                if prescope and  prescope[\'module_id\'] and m_prescope[prescope[\'module_id\']]\r\n                    \r\n                    \r\n                    \r\n                r_prescope = m_prescope[prescope[\'module_id\']][0]    \r\n                    \r\n                dates[date][\'ipd_opd\'] = {\'IPD\'=>0,\'OPD\'=>0, \'\'=>0, nil=>0} unless dates[date][\'ipd_opd\']\r\n                dates[date][\'ipd_opd\'][r_prescope[\'type_of_patient\']]+=1\r\n                \r\n                end\r\n                \r\n                end\r\n              \r\n              \r\n              \r\n                \r\n                if p_colo\r\n                dates[date][\'p_colo\'] = {} unless dates[date][\'p_colo\']\r\n                for pi in p_colo.split(\"|\")\r\n                    dates[date][\'p_colo\'][pi] = 0 unless  dates[date][\'p_colo\'][pi]\r\n                    dates[date][\'p_colo\'][pi] += 1 \r\n                end\r\n                \r\n                end\r\n                \r\n                \r\n                \r\n                if p_gastro\r\n                \r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                for pi in p_gastro.split(\"|\")\r\n                dates[date][\'p_gastro\'][pi] = 0 unless  dates[date][\'p_gastro\'][pi]\r\n                dates[date][\'p_gastro\'][pi] += 1 \r\n                end\r\n                end\r\n                \r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        end\r\n    \r\n    end\r\n    \r\n    %>\r\n    <%#dates.inspect  %>\r\n    <%\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<% \r\n\r\n    month_text = month_th[select_date.month-1]+select_date.strftime(\"-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    \r\n    td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.small{\r\n        font-size:0.8em;\r\n    }\r\n    td.date{\r\n        padding:0px;\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n          border:1px solid;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n        td.date{\r\n        padding:0px;\r\n        \r\n        width:125px;\r\n        \r\n    }\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n    \r\n    tr.page-break{page-break-after:always;page-break-inside:avoid; page-break-after:auto}\r\n    .force-break{ display: block;page-break-before:always;}\r\n        \r\n    }\r\n    \r\n\r\n    \r\n   table { page-break-inside:auto }\r\n   tr    { page-break-inside:avoid; page-break-after:auto }\r\n    \r\n</style>\r\n<style type=\"text/css\">\r\n\r\n</style>\r\n\r\n\r\n\r\n<div style=\"width:720px\">\r\n<h3>รายงานจำนวนผู้เข้ารับบริการ ห้องส่องกล้อง Surgical Endoscopy โรงพยาบาลจุฬาลงกรณ์ ประจำเดือน  \r\n<%=month_text%></h3>\r\n</div>\r\n\r\n<br/>\r\n<table border=\"1\" class=\"content\">\r\n<%\r\n   m = nil\r\n   \r\n   \r\n       tsum = {\'Elective\'=>[0,0,0,0],\'Extratime\'=>[0,0,0,0], \'Emergency\'=>[0,0,0,0], \'Total\'=>[0,0,0,0]}\r\n%>\r\n\r\n<%\r\n     pc_map = {}\r\n     pg_map = {}\r\n     \r\n     days = stop_date.day\r\n     \r\n    dates.each_pair do |k,v|\r\n        if v[\'p_colo\']    \r\n         v[\'p_colo\'].each_pair do |p,count|\r\n            pc_map[p] = 0 unless pc_map[p]\r\n            pc_map[p] += count\r\n         end\r\n        end\r\n        \r\n        if v[\'p_gastro\'] \r\n         v[\'p_gastro\'].each_pair do |p,count|\r\n            pg_map[p] = 0 unless pg_map[p]\r\n            pg_map[p] += count\r\n         end\r\n        end\r\n     \r\n    end\r\n     \r\n     \r\n\r\n%>\r\n\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td >&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n    <td colspan=\"3\" align=\"center\" class=\"  Elective\">Summary</td>\r\n    \r\n    <td colspan=\"<%=pc_map.keys.size%>\" align=\"center\" class=\"total tx\">Colonoscopy Procedure</td>\r\n    <td colspan=\"<%=pg_map.keys.size%>\" align=\"center\" class=\"total tx\">Gastroscopy Procedure</td>\r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"  class=\"page-break\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n    <td class=\"Elective\">IPD</td><td class=\"Elective\">OPD</td>\r\n    <td class=\"Elective\">#Patho</td>\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n</tr>\r\n\r\n<%\r\n\r\n  \r\n\r\n        count = 0 \r\n   \r\n   days.times do |date|\r\n  \r\n   date = (start_date+(date*3600*24))\r\n   i = date.strftime(\"%Y-%m-%d\")\r\n   \r\n#   for i in dates.keys.sort\r\n    weekend = \'\'\r\n    weekend = \'weekend\' if date.wday==0 or date.wday==6\r\n\r\n    \r\n    \r\n    if dates[i]\r\n\r\n%>\r\n\r\n\r\n<tr class=\"page-break\">\r\n    <td class=\"date <%=weekend%>\"  ><%=i.split(\'-\').reverse.join(\'/\')%> </td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Emergency Extratime} \r\n        \r\n        k = [0,0,0]\r\n        k = dates[i][j] if dates[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        \r\n        tsum[j][0] += k[0]\r\n        tsum[j][1] += k[1]\r\n        tsum[j][2] += k[2]\r\n        tsum[j][3] += s\r\n        \r\n        \r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        s = \'.\' if s == 0 \r\n        \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\" style=\"padding-top:10px;padding-bottom:10px\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n    <%\r\n   \r\n     for j in %w{IPD OPD} \r\n     \r\n        if j == \'IPD\'\r\n           ipds+= dates[i][\'ipd_opd\'][j] if dates[i][\'ipd_opd\'] \r\n        else\r\n           opds += dates[i][\'ipd_opd\'][j] if dates[i][\'ipd_opd\'] \r\n        end\r\n        \r\n    %>\r\n    <td class=\"Elective\">\r\n        <%=dates[i][\'ipd_opd\'][j] if dates[i][\'ipd_opd\'] %>\r\n    </td>\r\n    <% end %>\r\n   <td class=\"Elective\"><%=dates[i][\'no_specimen\']%></td>\r\n    <% for pi in pc_map.keys.sort \r\n  \r\n    c = dates[i][\'p_colo\'][pi] if dates[i][\'p_colo\']\r\n    c = \'-\' unless c\r\n    %>\r\n    <td class=\"total\"><%= c %></td>\r\n    <% end %>\r\n    \r\n    <% for pi in pg_map.keys.sort \r\n        g = dates[i][\'p_gastro\'][pi] if dates[i][\'p_gastro\']\r\n        g = \'-\' unless g\r\n    \r\n    %>\r\n    <td class=\"total\"><%=g %></td>\r\n    <% end %>\r\n    \r\n    \r\n\r\n</tr> \r\n<% else %>\r\n<tr class=\"page-break\" align=\"center\">\r\n    <td class=\"date  <%=weekend%>\"><%=i.split(\'-\').reverse.join(\'/\')%></td>\r\n    <td colspan=\"<%=19+pc_map.keys.size+pg_map.keys.size%>\">\r\n        &nbsp;\r\n        \r\n    </td>\r\n</tr>\r\n<% end %>\r\n<% if count%25==0 and count!=0%>\r\n\r\n</table>\r\n<table border=\"1\" class=\"content force-break\">\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td style=\"width:120px\">&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n        <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n\r\n\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n        <td colspan=\"3\" align=\"center\" class=\"  Elective\">Summary</td>\r\n\r\n\r\n    <td colspan=\"<%=pc_map.keys.size%>\" align=\"center\" class=\"total tx\">Colonoscopy Procedure</td>\r\n    <td colspan=\"<%=pg_map.keys.size%>\" align=\"center\" class=\"total tx\">Gastroscopy Procedure</td>\r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"  class=\"page-break\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n    <td class=\"Elective\">IPD</td><td class=\"Elective\">OPD</td>\r\n    <td class=\"Elective\">#Patho</td>\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% \r\ncount+=1\r\n\r\nend %>\r\n\r\n<tr class=\"page-break\"><td>Total</td>\r\n<%\r\n\r\n   t = [0,0,0,0]\r\n\r\n  for j in %w{Elective  Emergency Extratime} \r\n    \r\n  4.times do |i|    \r\n  t[i]+=tsum[j][i]\r\n%>\r\n<td class=\"total2\"><%=tsum[j][i]%></td>\r\n<% end %> \r\n<% end %> \r\n\r\n<td class=\"total2\" style=\"padding-top:10px;padding-bottom:10px\"><%=t[0]%></td><td class=\"total2\"><%=t[1]%></td><td class=\"total2\"><%=t[2]%></td><td class=\"total2\"><%=t[3]%></td>\r\n\r\n    <td class=\"total2\"><%=ipds%></td>\r\n    <td class=\"total2\"><%=opds%></td>\r\n\r\n    <td class=\"total2\"><%=total_patho%></td>\r\n\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total2\"><%=pc_map[pi] %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total2\"><%=pg_map[pi] %></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n<br/>\r\n<h4><u>รวมจำนวนผู้เข้ารับบริการ</u></h4>\r\n<br/><table>\r\n    <tr>\r\n        <td colspan=\"2\"></td><td>Elective</td><td>Emergency</td><td>Extratime</td>\r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Colonoscopy</th><td  align=\"right\"><%= t[0] %> ราย</td>\r\n        \r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]%> </td>\r\n        <%  end %>\r\n        \r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Gastroscopy</th><td  align=\"right\"><%= t[1] %> ราย </td>\r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][1]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Gastroscopy & Colonoscopy</th><td  align=\"right\"><%= t[2] %> ราย </td>\r\n           <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">รวม</td><td  align=\"right\"><%= t[0]+t[1]+t[2] %> ราย </td>\r\n          <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]+tsum[j][1]+tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    \r\n</table>\r\n<hr/>\r\n<h4><u>รวมจำนวนผู้ป่วยยกเลิกหรือเลื่อนนัด</u></h4>\r\n<br/>\r\n<table>\r\n    <tr>\r\n        <th>Cancelled</th> <td style=\"width:100px\" align=\"center\"><%=other_status[\'Cancelled\'] %></td>\r\n    </tr>\r\n    <tr>\r\n        <th>Postpone</th><td style=\"width:100px\" align=\"center\"><%=other_status[\'Postpone\']%></td> \r\n    </tr>\r\n    \r\n</table>\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-06-02 13:02:16','2015-06-02 13:02:16','case_report',''),(1604,'endoscopist_report',522,2,'<h1>Endoscopist Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n\r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-25\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-25\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nFrom : <%= f.date_select :from_date, :default=>from_date ,:discard_day=>true , :order=>[:month,:year],:start_year=>2008%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date ,:discard_day=>true , :order=>[:month,:year],:start_year=>2008%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n   \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'endoscopist_1\'=>1 ,\'diagnosis_group\'=>1}}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'endoscopist_1\'=>1 }}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    providers = @models[:provider].collection.find().to_a\r\n    m_providers = bmap providers, \'_id\'\r\n    \r\n    \r\n    # this_year_counts =  @models[:colonoscopy].collection.group( { :keyf => \"function(x){ return {\'pol : x.date.getMonth()}; }\" , \r\n    # :cond => {:date=>{\'$gte\'=>beginning_of_year,\'$lte\'=>now}}, \r\n    # :reduce => \'function(doc,prev) { prev.count += 1; }\', \r\n    # :initial => {:count => 0} })\r\n    \r\n\r\n    \r\n    \r\n    endos = {}\r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    \r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n            endoscopist = nil\r\n                status = \'Elective\'\r\n                dg = nil\r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       endoscopist = r_colo[0][\'endoscopist_1\']    \r\n                       dg = r_colo[0][\'diagnosis_group\']\r\n                    end\r\n            \r\n                   \r\n\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       endoscopist = r_gastro[0][\'endoscopist_1\']    \r\n\r\n                    end\r\n                    \r\n\r\n\r\n                    \r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       endoscopist = r_colo[0][\'endoscopist_1\'] \r\n                       dg = r_colo[0][\'diagnosis_group\']\r\n                    end\r\n                       \r\n\r\n                end\r\n              \r\n            end\r\n                \r\n                        \r\n                endos[endoscopist] = {} unless endos[endoscopist]\r\n                endos[endoscopist][status] = [0,0,0] unless endos[endoscopist][status]\r\n                \r\n                d =   endos[endoscopist][status] \r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n                \r\n                endos[endoscopist][\'total\'] = [0,0,0] unless endos[endoscopist][\'total\']\r\n                d =   endos[endoscopist][\'total\'] \r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            \r\n                if dg and (dg.downcase.index(\'polyp\') or dg.index(\'Cancer\') or dg.index(\'Polyposis\') or dg.index(\'Submucosal\'))\r\n                    endos[endoscopist][\'adr\'] = 0 unless endos[endoscopist][\'adr\']\r\n                    endos[endoscopist][\'adr\'] += 1\r\n                end\r\n            \r\n            \r\n                # dates[date] = {} unless dates[date]\r\n                # dates[date][status] = [0,0,0] unless dates[date][status]\r\n                \r\n                # d = dates[date][status]\r\n                # if d\r\n                # d[0]+= data[0]\r\n                # d[1]+= data[1]\r\n                # d[2]+= data[2]\r\n                # end\r\n            # else\r\n            \r\n            \r\n            \r\n        # else\r\n            \r\n            if false\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        \r\n    # end\r\n        end\r\n    \r\n    end\r\n    \r\n    %>\r\n    \r\n    <%# m_providers.inspect  %>\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    <%\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<%# endos.inspect %>\r\n\r\n<% \r\n\r\n    # month_text = select_date.strftime(\"%B-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n        td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.date{\r\n        padding:5px 10px 5px 10px;\r\n        \r\n        \r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n        \r\n    }\r\n\r\n    \r\n</style>\r\n\r\n<%\r\n\r\nfrom_text =  month_th[from_date.month-1]+from_date.strftime(\"-%Y\")\r\n\r\nto_text =  month_th[to_date.month-1]+to_date.strftime(\"-%Y\")\r\n \r\n%>\r\n\r\n<div style=\"width:720px\">\r\n<h3>จำนวนผู้เข้ารับบริการ ตามแพทย์\r\n ตั้งแต่ <%= from_text %>\r\n ถึง <%= to_text %>\r\n<%#month_text%></h3>\r\n</div>\r\n\r\n<br/>\r\n<table border=\"1\" class=\"content\">\r\n<%\r\n   m = nil\r\n   \r\n   \r\n       tsum = {\'Elective\'=>[0,0,0,0],\'Extratime\'=>[0,0,0,0], \'Emergency\'=>[0,0,0,0], \'Total\'=>[0,0,0,0]}\r\n%>\r\n\r\n<%\r\n     days = stop_date.day\r\n\r\n%>\r\n\r\n\r\n<tr style=\"background:#ffffde\"><td>&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n    \r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"><td align=\"center\"> Endoscopist</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n</tr>\r\n\r\n<%\r\n   keys = endos.keys\r\n   \r\n   keys.sort!{|a,b| \r\n    \r\n    aa = endos[a][\'total\']\r\n    bb = endos[b][\'total\']\r\n    aa = aa[0]+aa[1]+aa[2]\r\n    bb = bb[0]+bb[1]+bb[2]\r\n    bb<=>aa\r\n   \r\n   }\r\n   \r\n   \r\n   \r\n   keys.each do |i|\r\n       \r\n   unless endos[i]\r\n   %><tr><td>\r\n   <%=i.inspect %></td></tr>\r\n   <%\r\n   end\r\n  \r\n   if endos[i] and i!=nil\r\n    provider = \'deleted\'\r\n    provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n%>\r\n\r\n\r\n<tr>\r\n    <td class=\"\" ><%=provider%> </td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Extratime Emergency} \r\n        \r\n        k = [0,0,0]\r\n        k = endos[i][j] if endos[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        \r\n        tsum[j][0] += k[0]\r\n        tsum[j][1] += k[1]\r\n        tsum[j][2] += k[2]\r\n        tsum[j][3] += s\r\n        \r\n        \r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        s = \'.\' if s == 0 \r\n        \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n\r\n</tr> \r\n<% end %>\r\n<% end %>\r\n<tr><td>&nbsp;</td>\r\n<%\r\n\r\n   t = [0,0,0,0]\r\n\r\n  for j in %w{Elective Extratime Emergency} \r\n    \r\n  4.times do |i|    \r\n  t[i]+=tsum[j][i]\r\n%>\r\n<td class=\"total2\"><%=tsum[j][i]%></td>\r\n<% end %> \r\n<% end %> \r\n\r\n<td class=\"total2\"><%=t[0]%></td><td class=\"total2\"><%=t[1]%></td><td class=\"total2\"><%=t[2]%></td><td class=\"total2\"><%=t[3]%></td>\r\n\r\n</tr>\r\n</table>\r\n\r\n\r\n<br/>\r\n<h4>Polyp detection rate </h4>\r\n<br/><table>\r\n    <%\r\n     \r\n    keys.each do |i|\r\n  \r\n       if endos[i] and i!=nil  and c =  endos[i][\'adr\']\r\n    \r\n        provider = \'NA\'\r\n        provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n        t = endos[i][\'total\']\r\n        total =t[0]+t[2]+t[1]\r\n    \r\n    %>\r\n       \r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\"><%=provider%></td><td  align=\"right\"><%= c %> ราย / <%=total%> ราย <span style=\"color:blue\"><%=c*100/total %>%</span></td>\r\n    </tr>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    \r\n</table>\r\n\r\n</div>\r\n<br/>\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n\r\n\r\n<% end %>\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-06-02 13:02:31','2015-06-02 13:02:31','endoscopist_report',''),(1605,'procedure_report',522,2,'<h1>Procedure Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n\r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nFrom : <%= f.date_select :from_date, :default=>from_date ,:discard_day=>true , :order=>[:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date ,:discard_day=>true , :order=>[:month,:year]%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'endoscopist_1\'=>1 ,\'procedure\'=>1}}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'endoscopist_1\'=>1, \'procedure\'=>1}}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    providers = @models[:provider].collection.find().to_a\r\n    m_providers = bmap providers, \'_id\'\r\n    \r\n    \r\n    # this_year_counts =  @models[:colonoscopy].collection.group( { :keyf => \"function(x){ return {\'pol : x.date.getMonth()}; }\" , \r\n    # :cond => {:date=>{\'$gte\'=>beginning_of_year,\'$lte\'=>now}}, \r\n    # :reduce => \'function(doc,prev) { prev.count += 1; }\', \r\n    # :initial => {:count => 0} })\r\n    \r\n\r\n    \r\n    \r\n    endos = {}\r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    \r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                endoscopist = nil\r\n                status = \'Elective\'\r\n                proc_colo = nil\r\n                proc_gastro = nil\r\n\r\n\r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       endoscopist = r_colo[0][\'endoscopist_1\']    \r\n                       proc_colo = r_colo[0][\'procedure\'] if r_colo[0][\'procedure\'] !=\'\'\r\n                    end\r\n            \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       endoscopist = r_gastro[0][\'endoscopist_1\']    \r\n                       proc_gastro = r_gastro[0][\'procedure\'] if r_gastro[0][\'procedure\'] !=\'\'\r\n                    end\r\n                    \r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                        # endoscopist = r_gastro[0][\'endoscopist_1\']    \r\n                        proc_gastro = r_gastro[0][\'procedure\'] if r_gastro[0][\'procedure\'] !=\'\'\r\n                    end   \r\n                    if r_colo\r\n                       endoscopist = r_colo[0][\'endoscopist_1\'] \r\n                       dg = r_colo[0][\'diagnosis_group\']\r\n                       proc_colo = r_colo[0][\'procedure\'] if r_colo[0][\'procedure\'] !=\'\'\r\n                    end\r\n                  \r\n\r\n                end\r\n                \r\n                if proc_colo or proc_gastro\r\n                        \r\n                endos[endoscopist] = {} unless endos[endoscopist]\r\n                \r\n                endos[endoscopist][\'colo\'] = {} unless endos[endoscopist][\'colo\']\r\n                endos[endoscopist][\'gastro\'] = {} unless endos[endoscopist][\'gastro\']\r\n                \r\n                if proc_colo\r\n                   l = proc_colo.split(\'|\') \r\n                    for i in l\r\n                        endos[endoscopist][\'colo\'][i] = 0 unless endos[endoscopist][\'colo\'][i]\r\n                        endos[endoscopist][\'colo\'][i] += 1\r\n                    end\r\n                end\r\n                \r\n                if proc_gastro\r\n                   l = proc_gastro.split(\'|\') \r\n                     for i in l\r\n                        endos[endoscopist][\'gastro\'][i] = 0 unless endos[endoscopist][\'gastro\'][i]\r\n                        endos[endoscopist][\'gastro\'][i] += 1\r\n                    end\r\n                end\r\n                \r\n                end\r\n                \r\n                # d =   endos[endoscopist][status] \r\n                # if d\r\n                # d[0]+= data[0]\r\n                # d[1]+= data[1]\r\n                # d[2]+= data[2]\r\n                # end\r\n                \r\n                # endos[endoscopist][\'total\'] = [0,0,0] unless endos[endoscopist][\'total\']\r\n                # d =   endos[endoscopist][\'total\'] \r\n                # if d\r\n                # d[0]+= data[0]\r\n                # d[1]+= data[1]\r\n                # d[2]+= data[2]\r\n                # end\r\n            \r\n                # if dg and (dg.index(\'polyp\') or dg.index(\'Cancer\'))\r\n                #     endos[endoscopist][\'adr\'] = 0 unless endos[endoscopist][\'adr\']\r\n                #     endos[endoscopist][\'adr\'] += 1\r\n                # end\r\n            \r\n            \r\n                # dates[date] = {} unless dates[date]\r\n                # dates[date][status] = [0,0,0] unless dates[date][status]\r\n                \r\n                # d = dates[date][status]\r\n                # if d\r\n                # d[0]+= data[0]\r\n                # d[1]+= data[1]\r\n                # d[2]+= data[2]\r\n                # end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n            \r\n            if false\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        \r\n    end\r\n        end\r\n    \r\n    end\r\n    \r\n    %>\r\n    \r\n    <%# m_providers.inspect  %>\r\n    \r\n    \r\n    \r\n    <%#endos.inspect %>\r\n    \r\n    \r\n    \r\n    <%\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<%# endos.inspect %>\r\n\r\n<% \r\n\r\n    # month_text = select_date.strftime(\"%B-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n           td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.date{\r\n        padding:5px 10px 5px 10px;\r\n        \r\n        \r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n        \r\n    }\r\n\r\n    \r\n</style>\r\n\r\n<%\r\n   \r\n   gastro_list = []\r\n   colo_list = []\r\n   colo_count = {}\r\n   gastro_count = {}\r\n   for i in endos.values\r\n        \r\n        i[\'gastro\'].each_pair do |j,count|\r\n            \r\n            gastro_list << j\r\n            gastro_count[j] = 0 unless  gastro_count[j]\r\n            gastro_count[j] += count\r\n        end\r\n        \r\n        i[\'colo\'].each_pair do |j,count|\r\n            colo_list << j\r\n            colo_count[j] = 0 unless colo_count[j]\r\n            colo_count[j] += count\r\n        end\r\n   end\r\n   \r\n  \r\n   gastro_list.uniq!\r\n   colo_list.uniq!\r\n   \r\n   colo_list.sort!{|a,b| colo_count[b]<=>colo_count[a]}\r\n   gastro_list.sort!{|a,b| gastro_count[b]<=>gastro_count[a]}\r\n   \r\n   \r\n%>\r\n<%\r\n\r\nfrom_text =  month_th[from_date.month-1]+from_date.strftime(\"-%Y\")\r\n\r\nto_text =  month_th[to_date.month-1]+to_date.strftime(\"-%Y\")\r\n \r\n%>\r\n<h2>จำนวนผู้เข้ารับบริการ แยกตามประเภทการรักษา</h2>\r\n<h3>\r\n ตั้งแต่ <%= from_text %>\r\n ถึง <%= to_text %>\r\n</h3>\r\n<h3>Colonoscopy Procedures</h3>\r\n\r\n\r\n<br/>\r\n\r\n<table border=\"1\" class=\"content\">\r\n\r\n<tr style=\"background-color:#dedeff\"><th>Endoscopist</th>\r\n    <% for j in colo_list %>\r\n    <th><%=j%></th>\r\n    <% end %>\r\n</tr>\r\n<%\r\n   \r\n   \r\n   \r\n   keys = endos.keys\r\n   \r\n   \r\n   keys.each do |i|\r\n  \r\n   if e = endos[i] and i!=nil\r\n    provider = \'deleted\'\r\n    provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n\r\n%>\r\n\r\n\r\n<tr>\r\n    <td class=\"\" ><%=provider%> </td>\r\n    <%\r\n        e_colo = e[\'colo\']\r\n        for j in colo_list\r\n            %>\r\n            <td align=\"center\"><%=e_colo[j]%></td>\r\n            <%\r\n        end\r\n    %>\r\n</tr> \r\n<% end %>\r\n<% end %>\r\n<tr>\r\n    <td>Total</td>\r\n    <% for j in colo_list %>\r\n    <td class=\"total2\"><%= colo_count[j]%></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n\r\n<hr/>\r\n\r\n\r\n\r\n<h3>Gastroscopy Procedures</h3>\r\n\r\n\r\n<br/>\r\n\r\n<table border=\"1\" class=\"content\">\r\n\r\n<tr style=\"background-color:#dedeff\"><th>Endoscopist</th>\r\n    <% for j in gastro_list %>\r\n    <th><%=j%></th>\r\n    <% end %>\r\n</tr>\r\n<%\r\n   \r\n   \r\n   \r\n   keys = endos.keys\r\n   \r\n   lkeys = []\r\n   \r\n   keys.each do |i|\r\n      sum=0\r\n      for j in gastro_list\r\n        sum+=endos[i][\'gastro\'][j]  if endos[i][\'gastro\'][j]\r\n      end\r\n      lkeys << i if sum>0\r\n   end\r\n   \r\n   \r\n   \r\n   lkeys.each do |i|\r\n  \r\n   if e = endos[i] and i!=nil\r\n    provider = \'deleted\'\r\n    provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n\r\n%>\r\n\r\n\r\n<tr>\r\n    <td class=\"\" ><%=provider%> </td>\r\n    <%\r\n        e_colo = e[\'gastro\']\r\n        for j in gastro_list\r\n            %>\r\n            <td align=\"center\"><%=e_colo[j]%></td>\r\n            <%\r\n        end\r\n    %>\r\n</tr> \r\n<% end %>\r\n<% end %>\r\n<tr>\r\n    <td>Total</td>\r\n    <% for j in gastro_list %>\r\n    <td class=\"total2\"><%= gastro_count[j]%></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n\r\n\r\n<%\r\nif false\r\n%>\r\n<br/>\r\n<h4>Adenoma detection rate (ADR)</h4>\r\n<br/><table>\r\n    <%\r\n     \r\n    keys.each do |i|\r\n  \r\n       if endos[i] and i!=nil  and c =  endos[i][\'adr\']\r\n    \r\n        provider = \'NA\'\r\n        provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n        t = endos[i][\'total\']\r\n        total =t[0]+t[2]\r\n    \r\n    %>\r\n       \r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\"><%=provider%></td><td  align=\"right\"><%= c %> ราย / <%=total%> ราย <span style=\"color:blue\"><%=c*100/total %>%</span></td>\r\n    </tr>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    \r\n</table>\r\n\r\n</div>\r\n<br/>\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n\r\n<%end %>\r\n\r\n<br/>\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n\r\n\r\n<% end %>\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-06-02 13:02:55','2015-06-02 13:02:55','procedure_report',''),(1606,'context_menu',522,4,'<div class=\"accordion-group\">\r\n	<div class=\"accordion-heading\">\r\n		<a href=\"#collapse-0\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n		Dashboard\r\n		</a>\r\n		<div class=\"accordion-body collapse in\" id=\"collapse-0\">\r\n			<div class=\"accordion-inner\">\r\n				<ul class=\"nav nav-list\">\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"overview\">Overview</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"weekly_report\">Weekly Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"case_report\">Monthly Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"yearly_report\">Yearly Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"annual_report\">Annual Report</a></li>\r\n					<% if %w{admin superadmin developer}.index @current_role %>\r\n					\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"endoscopist_report\">Endoscopist Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"procedure_report\">Procedure Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"total_ssa_report\">SSA Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"total_esd_report\">ESD Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"nbi_report\">NBI Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"emr_report\">EMR Summary Report</a></li>\r\n    				<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"instrument_report\">Subsidy Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"financial_report\">Financial Report</a></li>\r\n    				<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"diagnosis_report\">Diagnosis Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"image_search\">Image Search</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"certify_report\">Certify Report</a></li>\r\n	                <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"usage_report\">Usage Report</a></li>\r\n                    <% end %>\r\n\r\n\r\n                	<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"bowel_report\">Bowel Prep Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"../Attendance/print_report\">Payroll Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"pathology_report\">Pathology Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"attendance_report\">Attendance Report</a></li>\r\n    			\r\n\r\n\r\n    				\r\n\r\n\r\n				</ul>\r\n			</div>\r\n	</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</div></div></div>',NULL,NULL,NULL,'2015-06-02 13:24:24','2015-06-02 13:24:24','context_menu',''),(1607,'layout',717,4,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n			\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n<title><%=title%></title>\r\n\r\n<script>\r\n$(document).ready(function() {\r\n	//* show all elements & remove preloader\r\n	// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n    // $(\"html\").removeClass(\"js\");\r\n});\r\n</script>\r\n		\r\n<style>\r\n.w-box-content.cnt_a {\r\n    background: #fff;\r\n}\r\n.k-grid table {\r\n    font-size: 1em;\r\n}\r\n.k-calendar .k-content {\r\n    font-size: 1em;padding-top:5px;\r\n}\r\n.k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\n    height: 18px;\r\n}\r\n.field-data {\r\n    width: 220px;\r\n}\r\n\r\ninput{\r\n    height:18px;\r\n}\r\nbody { \r\n\r\n    padding: 20px;\r\n    font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\r\n    /*font-weight: lighter;*/\r\n    /*font-size: 1em;*/\r\n}\r\n\r\n\r\n</style>\r\n		\r\n		\r\n</head>\r\n<body style=\"    \r\n    background-repeat: no-repeat;\r\n    background-attachment: fixed;\r\n    background-position: center top; \r\n    /* background-color: #e09320; */\r\n    background-size: cover;\">\r\n<%\r\n    app_logo = eval(@current_project[:params])[\'app_logo_url\']\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12 well\">\r\n        <div class=\"span4\">\r\n            <a href=\"../../<%= @current_project.name %>/Home/index\">	\r\n                <img src=\'<%= app_logo%>\' height=\"40px\"> <a href=\"../../<%= @current_project.name %>/Home/index\" class=\"btn btn-mini\"> <i class=\"splashy-arrow_medium_up\"> </i>Home</a>\r\n                <!--<img src=\"https://emr-life.com/esm/anes/pni/logo.jpg\" height=\"50px\"/>-->\r\n            </a>\r\n            \r\n        </div>\r\n\r\n		<div class=\"span4\">\r\n			<ul class=\"dshb_icoNav tac\">\r\n				<!--<li><a href=\"../Home/index\" style=\"background-image: url(/gebo/img/gCons/home.png)\"> Home</a></li>-->\r\n				\r\n				<!--<li><a href=\"../Appointment/index\" style=\"background-image: url(/gebo/img/gCons/calendar.png)\">Appointment</a></li>-->\r\n				<!--<li><a href=\"../PreAnesthetic/index\" style=\"background-image: url(/gebo/img/gCons/ID.png)\">PreOp Note</a></li>-->\r\n				<!--<li><a href=\"../PostAnesthetic/index\" style=\"background-image: url(/gebo/img/gCons/next-item.png)\">PostOp Note</a></li>-->\r\n				<!--<li><%= link_to \'Reports\',\"../Home/report?\\\\#{\'date=\'+params[:date]if params[:date]}\",:style=>\'background-image: url(/gebo/img/gCons/bar-chart.png)\' %></li>-->\r\n				\r\n				<!--<li><a href=\"../Setting/index\" style=\"background-image: url(/gebo/img/gCons/configuration02.png)\">Settings</a></li>-->\r\n	    	 </ul>		\r\n		</div>\r\n		\r\n<%\r\n    m_prov = get_model[:provider]\r\n    prov = m_prov.where(:login=>@current_user.login).first\r\n%>\r\n\r\n    	<div class=\"span4\">\r\n    	    <span style=\"float:right;color:grey;font-size:1em\" ><%# @current_user.to_json.html_safe %>\r\n                <span style=\"float:right\">Welcome <b><%= prov.nil? ? @current_user.login : \"\\\\#{prov[:name]} (\\\\#{@current_user.login})\" %></b></span> \r\n                <div class=\"row-fluid\"></div> \r\n                <span style=\"float:right\">\r\n                <% if @current_role == \'admin\' or @current_role==\'developer\' %>\r\n                <a href=\"../Setting/index\" class=\"btn btn-mini\" >Setting <i class=\"splashy-sprocket_dark\"></i></a> |\r\n                <% if @current_role==\'developer\' %>\r\n                <%= link_to \'Developer\', \'/esm_projects/\' + @current_project[:id].to_s, :class=>\'btn btn-mini\', :target=>\'_blank\' %> |\r\n                <% end %>\r\n                <% end %>  \r\n                <%=link_to \'Logout <i class=\"splashy-media_controls_play_small\"></i>\'.html_safe,\'/user/logout\',:class=>\'btn btn-mini\' %>\r\n                </span>\r\n            </span>\r\n    	</div>\r\n	</div>\r\n</div>\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\" style=\"padding:0px;\">\r\n	   <%= yield %><%= yield :content%>\r\n    </div>\r\n</div>\r\n     \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n                 		<div id=\"context-menu\" class=\"accordion\">\r\n                            <%= render :partial=>\'/layouts/context_menu\'%>\r\n            			</div>\r\n		            </div>\r\n	            </div>\r\n	        </div>\r\n	    </div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n		</script>		\r\n<%\r\n    auto_logout = false\r\n    if auto_logout\r\n%>\r\n<script>\r\nvar IDLE_TIMEOUT = 15*60; //seconds\r\nvar _idleSecondsCounter = 0;\r\ndocument.onclick = function() {\r\n    _idleSecondsCounter = 0;\r\n};\r\ndocument.onmousemove = function() {\r\n    _idleSecondsCounter = 0;\r\n};\r\ndocument.onkeypress = function() {\r\n    _idleSecondsCounter = 0;\r\n};\r\nwindow.setInterval(CheckIdleTime, 1000);\r\n\r\nfunction CheckIdleTime() {\r\n    _idleSecondsCounter++;\r\n    var oPanel = document.getElementById(\"SecondsUntilExpire\");\r\n    if (oPanel)\r\n        oPanel.innerHTML = (IDLE_TIMEOUT - _idleSecondsCounter) + \"\";\r\n    if (_idleSecondsCounter >= IDLE_TIMEOUT) {\r\n        alert(\"Session expired!\");\r\n        document.location.href = \"/user/logout\";\r\n    }\r\n}\r\n</script>\r\n<%\r\n    end\r\n%>\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-06-02 14:34:37','2015-06-02 14:34:37','',''),(1608,'print_innovian',714,3,'<style>\r\n    \r\n     @media print\r\n    {\r\n    	#body { display: none; }\r\n    	#printable { display: block; }\r\n    }\r\n    \r\n</style>\r\n<div id=\"printable\">\r\n<div style=\"width:1000px;margin-left:auto; margin-right:auto\">\r\n<table width=\"1000px\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\">\r\n  <tr>\r\n    <td rowspan=\"2\" valign=\"top\">Patient</td>\r\n    <td colspan=\"4\" ><b style=\"font-size:20px\">Preanesthetic evalution and medication record</b></td>\r\n    <td colspan=\"2\" rowspan=\"2\" align=\"center\"><img src=\"http://pni.go.th/pnigoth/wp-content/uploads//2009/05/LogoPrasatNew_02-300x212.jpg\" width=\"150px\"/></td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">&nbsp;</td>\r\n    <td colspan=\"2\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">Patient ID<br />\r\n      31010xxxxxx</td>\r\n    <td valign=\"top\">Hospital No.(xxxx/xx)</td>\r\n    <td valign=\"top\">Date of birth</td>\r\n    <td valign=\"top\">Age</td>\r\n    <td valign=\"top\">Gender</td>\r\n    <td valign=\"top\">Weight</td>\r\n    <td valign=\"top\">Height</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"3\">Diagnosis<br />\r\n      N005 Hydrocephalus</td>\r\n    <td colspan=\"2\">Hospital Admit Date</td>\r