r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2015-06-02 16:26:29','2015-06-02 16:26:29','print_bk',''),(1613,'create_all',725,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<!--<h3>Create Patient</h3>-->\r\n<strong>Create Patient</strong>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n<div >\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\" >\r\n\r\n<%= render :inline=>this.initz %>\r\n<% # params.inspect %>\r\n<%\r\n\r\n    msg = nil\r\n    err = false\r\n    \r\n    models = get_model\r\n    all_provider = models[:provider].all\r\n    list_surgeon = all_provider.collect{|i| [i.id, i.name] if i[:provider_type]==\'1\' or i[:provider_type]==\'4\'}\r\n    list_assist = all_provider.collect{|i| [i.id, i.name] if i[:provider_type]==\'1\' or i[:provider_type]==\'4\'}\r\n    \r\n    m_appointment = models[:appointment]\r\n    m_patient_detail = models[:patient_detail]\r\n\r\n    if request.post?\r\n      \r\n        p = params[:record]\r\n        return_url = params[:return]\r\n        date = Time.now\r\n        if !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !params[:admit_date].empty?\r\n            date = Date.parse(params[:admit_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                params[:admit_date] = new_date\r\n            end \r\n        end\r\n        if !params[:appointed_date].empty?\r\n            date = Date.parse(params[:appointed_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                params[:appointed_date] = new_date\r\n            end \r\n        end\r\n        \r\n        \r\n        # next_service = \"../Patient/create_test?return=\\\\#{return_url}&\".html_safe\r\n        next_service = \"../Home/index\"\r\n        patient = @patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Duplicate HN in database\"\r\n            # next_service += URI.escape(params.collect{|k,v| \"\\\\#{k}=\\\\#{v}\"}.join(\'&\')).html_safe\r\n            err = true\r\n        else\r\n            # msg = \"Success\"\r\n            # next_service = \"../Setting/index\"\r\n            patient = @patient_model.create p\r\n            # next_service = \'../Home/patient_record?id=\' + patient.id\r\n          \r\n            # if params[:record][:provider]\r\n            #     m_pm_record = @module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>params[:record][:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>params[:record][:provider]\r\n            # end\r\n            \r\n            msg = \"Patient created\"\r\n        end\r\n        \r\n        # create appointment\r\n        rec_app = m_appointment.create :provider=>params[:surgeon], :date=>params[:appointed_date], :start=>params[:start], :status=>\'Appointed\'\r\n        rec_pm_app = @module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>params[:record][:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id\r\n\r\n        # create patient_detail\r\n        rec_pat = m_patient_detail.create :time=>params[:time], :diagnosis=>params[:diagnosis], :hospital_admit_date=>params[:admit_date], :height=>params[:height], :weight=>params[:weight], :allergies=>params[:allergies], :instrument=>params[:instrument], :procedure=>params[:procedure], :surgeon=>params[:surgeon], :assist=>params[:assist], :room=>params[:room], :bed=>params[:bed], :care_unit_days=>params[:care_unit_days], :position=>params[:position], :post_op=>params[:post_op]\r\n        rec_pm_pat = @module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>params[:record][:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#patient_detail\", :module_id=>rec_pat.id, :parent_id=>rec_pm_app.id\r\n      \r\n    #   return_url += \'&obj_id=\'+patient.id.to_s\r\n      %>\r\n      <!--<%=params.inspect %>-->\r\n      <br/>\r\n      <!--Patient : <%= patient.inspect %><br/>-->\r\n      <!--Appointment : <%= rec_app.inspect %>...<%= rec_pm_app.inspect %><br/>-->\r\n      <!--Patient Detail : <%= rec_pat.inspect %>....<%= rec_pm_pat.inspect %><br/>-->\r\n      <div class=\"alert <%= err ? \"alert-error\" : \"alert-success\" %>\"><%= msg %></div>\r\n      <meta http-equiv=\"refresh\" content=\"0; url=<%=next_service%>\" />\r\n      <%\r\n    else\r\n%>\r\n<%= form_for :record , :url=>\'create\' do |f| %>\r\n<%= f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n<%= f.hidden_field :date, :value=>params[:data][:date] %>\r\n<div class=\"w-box\">\r\n<!--<div id=\"132-F1376173358\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">-->\r\n<div class=\"form-horizontal well\">\r\n<!--<b>Personal Information</b>-->\r\n<p class=\"f_legend\">Patient Information</p>\r\n<!--</div>-->\r\n\r\n<div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n    <span class=\"\"><label>Hospital Number <span class=\"f_req\">*</span>  : </label></span>	\r\n    <input type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"><span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[hn]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>\r\n</div>\r\n\r\n<!--<div class=\"row-fluid\"></div>-->\r\n\r\n<div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:340px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n    <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Appointed Date : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                <input type=\"text\" name=\"appointed_date\" id=\"data-appointed_date\" value=\"2015-03-08 20:44:27 +0700\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n            <script>\r\n            	$(\"#data-appointed_date\").kendoDatePicker({\r\n            		value: \'<%= params[:data][:date] if params[:data][:date] %>\',\r\n            	});\r\n            </script>\r\n        </div>\r\n    </div>\r\n    <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Start : </label></span>\r\n        <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n            <span class=\"k-picker-wrap k-state-default\">\r\n                <input type=\"text\" name=\"start\" id=\"data-start\" value=\"2015-06-03 00:26:20 +0700\" style=\"width: 100%;\" onkeypress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                    <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                </span>\r\n            </span>\r\n        </span>\r\n<script>\r\n    $(\"#data-start\").kendoTimePicker({\r\n	value: \'09:00\',\r\n	interval: 10,\r\n	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\"],\r\n	change: function(event){\r\n		var v = $(\'#data-start\').val()\r\n		if(v.length==3){\r\n			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n		}\r\n		 \r\n	}\r\n});\r\n</script>\r\n	</div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Prefix name : </label></span>	\r\n        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n    <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;f