])\r\n    pat = @patient_model.find(pm_app[:patient_id])\r\n    age = \'-\'\r\n    if pat[:birth_date]\r\n        diff = Time.diff(date, pat[:birth_date])\r\n        year = diff[:year]\r\n        month = diff[:month]\r\n        day = diff[:day]\r\n        age = \"\\\\#{year}\"\r\n    end\r\n    color = \'white\'\r\n    {\r\n        :time=>pat_det[:time] ? pat_det[:time].strftime(\"%H:%M\") : \'00:00\',\r\n        :hn=>pat[:hn],\r\n        :title=>\"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]} \\\\#{pat[:last_name]}\",\r\n        :age=>age,\r\n        :diagnosis=>pat_det[:diagnosis] ? pat_det[:diagnosis] : \"-\",\r\n        :operation=>pat_det[:procedure] ? pat_det[:procedure] : \"-\",\r\n        :position=>pat_det[:position] ? pat_det[:position] : \"-\",\r\n        :surgeon=>pat_det[:surgeon]==\"0\" ? \"-\" : h_prov[pat_det[:surgeon].to_s],\r\n        :instrument=>pat_det[:instrument] ? pat_det[:instrument] : \"-\",\r\n        :post_op=>pat_det[:post_op] ? pat_det[:post_op] : \"-\",\r\n        :status=>i[:status] ? i[:status] : \'Appointed\'\r\n    }\r\n    \r\nend\r\n\r\n# list = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\nlist = res\r\n%>\r\n         \r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<!--<meta http-equiv=\"refresh\" content=\"5\" >-->\r\n<title>PATIENT STATUS</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml {\r\n\r\n  \r\n     }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px;  border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; paddi