ius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n	color:#000;font-weight:bold;\r\n	font-size: 1em;\r\n}\r\n\r\ntable.table {\r\n    \r\n    color: #666;\r\n    font-size: 1em;\r\n    -moz-border-radius: 3px;\r\n    -moz-box-shadow: 0 1px 2px #d1d1d1;\r\n    -webkit-border-radius: 3px;\r\n    -webkit-box-shadow: 0 1px 2px #d1d1d1;\r\n    background: #eaebec;\r\n    border: #ccc 1px solid;\r\n    border-radius: 3px;\r\n    box-shadow: 0 1px 2px #d1d1d1;\r\n    font-family: Arial, Helvetica, sans-serif;\r\n    text-shadow: 1px 1px 0px #fff;\r\n}\r\n\r\ntable.table tr.even td {\r\n    background: #f6f6f6;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#f8f8f8), to(#f6f6f6));\r\n    background: -moz-linear-gradient(top, #f8f8f8, #f6f6f6);\r\n}\r\n\r\ntable.table th {\r\n    padding: 21px 25px 22px 25px;\r\n    border-bottom: 1px solid #e0e0e0; border-top: 1px solid #fafafa;\r\n    background: #ededed;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#ededed), to(#ebebeb));\r\n    background: -moz-linear-gradient(top, #ededed, #ebebeb);\r\n}\r\n\r\ntable.table th:first-child {\r\n    padding-left: 20px;\r\n    text-align: left\r\n}\r\n\r\ntable.table a:visited {\r\n    color: #999999;\r\n    font-weight: bold;\r\n    text-decoration: none\r\n}\r\n\r\ntable.table a:active,\r\ntable.table a:hover {\r\n    color: #bd5a35;\r\n    text-decoration: underline\r\n}\r\n\r\ntable.table a:link {\r\n    color: #666;\r\n    font-weight: bold;\r\n    text-decoration: none\r\n}\r\n\r\ntable.table tr {\r\n    padding-left: 20px;\r\n    text-align: center\r\n}\r\n\r\ntable.table tr:first-child th:first-child {\r\n    -moz-border-radius-topleft: 3px;\r\n    -webkit-border-top-left-radius: 3px;\r\n    border-top-left-radius: 3px;\r\n}\r\n\r\ntable.table tr:first-child th:last-child {\r\n    -moz-border-radius-topright: 3px;\r\n    -webkit-border-top-right-radius: 3px;\r\n    border-top-right-radius: 3px;\r\n}\r\n\r\ntable.table tr:last-child td {    border-bottom: 0 }\r\n\r\ntable.table tr:last-child td:first-child {\r\n    -moz-border-radius-bottomleft: 3px;\r\n    -webkit-border-bottom-left-radius: 3px;\r\n    border-bottom-left-radius: 3px;\r\n}\r\n\r\ntable.table tr:last-child td:last-child {\r\n    -moz-border-radius-bottomright: 3px;\r\n    -webkit-border-bottom-right-radius: 3px;\r\n    border-bottom-right-radius: 3px;\r\n}\r\n\r\ntable.table tr:hover td {\r\n    background: #f2f2f2;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#f2f2f2), to(#f0f0f0));\r\n    background: -moz-linear-gradient(top, #f2f2f2, #f0f0f0);\r\n}\r\n\r\ntable.table tr td {\r\n    padding: 18px;\r\n    border-bottom: 1px solid #e0e0e0; border-left: 1px solid #e0e0e0; border-top: 1px solid #ffffff;\r\n    background: #fafafa;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#fbfbfb), to(#fafafa));\r\n    background: -moz-linear-gradient(top, #fbfbfb, #fafafa);\r\n}\r\n\r\ntable.table tr td:first-child {\r\n    padding-left: 20px;\r\n    border-left: 0;\r\n}\r\n\r\n.appointed {\r\n    color: gray;\r\n}\r\n.waiting {\r\n    color:yellow;\r\n}\r\n.processing {\r\n    color:red;\r\n}\r\n.recovery {\r\n    color:green;\r\n}\r\n.completed {\r\n    color:green;\r\n}\r\n.icu {\r\n    color:purple;\r\n}\r\n.ward {\r\n    color:orange;\r\n}\r\n.home {\r\n    color:orange;\r\n}\r\n</style>\r\n<body >\r\n<div class=\"wrapper\">\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\" style=\"width:100%\">\r\n<div class=\"span12\" style=\"width:100%\">\r\n\r\n\r\n\r\n<div id=\"endoscopy_nurse\" class=\"  portlet \" >\r\n\r\n<span>\r\n    <!--<img src=\'/esm/anes/pni/logo.jpg\' width=\"60\" />-->\r\n    <label> Operation Schedule : </label>\r\n</span>\r\n\r\n			<div style=\"margin-top:10px\">\r\n <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" class=\"table\">  \r\n \r\n <tr>\r\n    <!--<th>No.</th>-->\r\n    <th>Time</th>\r\n    <th>H/N</th>\r\n    <th>Name</th>\r\n    <th>Age</th>\r\n    <th>Diagnosis</th>\r\n    <th>Operation</th>\r\n    <th>Position</th>\r\n    <th>Surgeon</th>\r\n    <th>Instrument</th>\r\n    <th>Post-op</th>\r\n    <!--<th>Status</th>-->\r\n </tr>         \r\n<% list.each_with_index do |i,index|  %>\r\n<tr class=\"<%=i[:status].downcase%>\">  \r\n    <!--<td><%=index+1%>.</td>-->\r\n    <td><%= i[:time] %></td> \r\n    <td><%=i[:hn]%></td> \r\n    <td><%=i[:title]%></td>\r\n    <td><%= i[:age] %></td> \r\n    <td><%= i[:diagnosis] %></td>\r\n    <td><%= i[:operation] %></td>\r\n    <td><%= i[:position] %></td>\r\n    <td><%= i[:surgeon] %></td>\r\n    <td><%= i[:instrument] %></td>\r\n    <td><%= i[:post_op] %></td>\r\n    <!--<td><%=i[:status]%></td> -->\r\n </tr>     \r\n	\r\n <% end %>\r\n\r\n\r\n\r\n\r\n\r\n</table></div>\r\n</div>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n	\r\n\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n<% end %>\r\n',NULL,NULL,NULL,'2015-06-02 16:53:12','2015-06-02 16:53:12','status_feed',''),(1619,'test',714,3,'<%\r\n    zmodels = get_model\r\n    zehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    zehr_models = zehr.get_model\r\n    zm_patient_module = zehr_models[:patient_module]\r\n    \r\n    res = {}\r\n    \r\n    pat_id = \'556df683790f9b05e3000003\'\r\n    parent = \'556df6ac790f9b05e3000005\'\r\n    res[:patient] = zm_patient_module.where(:patient_id=>pat_id)\r\n    \r\n    \r\n    rec_pm = zm_patient_module.find(\'556df6ac790f9b05e3000007\')\r\n    rec_pm.update_attributes :parent_id=>parent\r\n    \r\n    res[:project] = @current_project\r\n    res[:pm] = zm_patient_module.where(:parent_id=>parent, :module_name=>\'pni#patient_detail\').first\r\n    res[:pat_det] = zmodels[:patient_detail].find(res[:pm][:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-06-02 19:15:49','2015-06-02 19:15:49','test','*'),(1620,'test',725,3,'<%\r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @pm_model = @ehr_model[:patient_module]\r\n  \r\n  models = get_model\r\n  m_pat = @patient_model.all\r\n  \r\n  res = {}\r\n  res[:patient_count] = m_pat.count\r\n  res[:all_patient] = m_pat\r\n  res[:appointment] = models[:appointment].all\r\n  res[:all_pm] = @pm_model.all\r\n  \r\n    res[:patient_module] = []\r\n    for pat in m_pat do\r\n        pat_id = pat.id\r\n        pm = @pm_model.where(:patient_id=>pat_id).collect{|i| i if i[:module_name].include? \"pni\"}.compact\r\n        res[:patient_module] << pm\r\n    end\r\n    res[:patient_module] = res[:patient_module].compact\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-06-03 03:54:51','2015-06-03 03:54:51','test',''),(1621,'print',718,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666;display: block;\r\n  padding: 8.5px;\r\n  margin: 0 0 9px;\r\n  font-size: 12.025px;\r\n  line-height: 18px;\r\n  word-break: break-all;\r\n  word-wrap: break-word;\r\n    white-space: pre-wrap;}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm_core/banner.png\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3><%=this.table_name.to_s.humanize%></h3>\r\n<%= this.display.html_safe %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div class=\"hideprint\">\r\n<%= link_to \'Back\', url(\'index\') %>\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2015-06-05 04:40:21','2015-06-05 04:40:21','print',''),(1622,'document_name',727,1,'\'pre_op\'',NULL,NULL,NULL,'2015-06-08 08:28:40','2015-06-08 08:28:40',NULL,NULL),(1623,'document_name',728,1,'\'post_op\'',NULL,NULL,NULL,'2015-06-08 08:28:56','2015-06-08 08:28:56',NULL,NULL),(1624,'document_name',729,1,'\'hospital\'',NULL,NULL,NULL,'2015-06-09 04:27:18','2015-06-09 04:27:18',NULL,NULL),(1625,'document_name',730,1,'\'user_profile\'',NULL,NULL,NULL,'2015-06-09 06:36:22','2015-06-09 06:36:22',NULL,NULL),(1626,'test_user',624,3,'<%\r\n    res = {}\r\n    res[:user] = User.inspect\r\n    res[:curr_project] = @current_project\r\n    res[:doc] = @current_project.get_document(\'user\')\r\n    \r\n    # services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\')\r\n    # res[:services] = services\r\n    www = @context.get_projects_by_abstract(\'www.www\')\r\n    res[:www] = www\r\n    res[:www_services] = @current_project.get_services_by_abstract(\'system.util.Document\')\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-06-09 06:48:21','2015-06-09 06:48:21','test_user',''),(1628,'patient_record',732,2,'    <% Time.zone =  get_setting \'time_zone\' %>\r\n    <%\r\n    require \'time_diff\'\r\n    \r\n    date = Time.now.to_datetime\r\n    \r\n    models = get_model\r\n    conf = this.config\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient = ehr_models[:patient]\r\n    m_patient_module = ehr_models[:patient_module]\r\n    \r\n    %>\r\n    \r\n    <style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n    </style>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n    <div class=\"w-box\">\r\n        <div class=\"w-box-header\">\r\n            Patient Medical Records\r\n            <div class=\"pull-right\">\r\n            <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n            </div> \r\n        </div>  \r\n        <div class=\"w-box-content cnt_a\">\r\n            <div style=\"border:0px solid\">\r\n                <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n<%\r\n    # get patient by patient_id\r\n    pid = \'\'\r\n    patient = \'\'\r\n    if params[:id]\r\n        pid = params[:id]\r\n        patient = m_patient.find(pid)\r\n    end\r\n    \r\n    if patient\r\n        birth_date = patient.birth_date \r\n        year = month = day = \'0\'\r\n        if date and birth_date\r\n            t = date-birth_date    \r\n            diff = Time.diff(date, birth_date)\r\n            year = diff[:year]\r\n            month = diff[:month]\r\n            # day = diff[:day]\r\n        end\r\n%>\r\n<!--patient section-->\r\n<div class=\"alert alert-block alert-success\">\r\n    <div class=\"btn left\" style=\"height:100px;width:100px\">\r\n<%\r\n        edit_url = \"../../www/Patient/edit?id=\\\\#{params[:id]}&return=\\\\#{request.fullpath}\".html_safe\r\n        att_model = ehr_models[:attachment]\r\n        if !patient[:picture].empty? and patient[:picture].size > 0 \r\n            pic = att_model.find(patient.picture[-1])\r\n            if pic \r\n%>\r\n<a href=\'<%= edit_url %>\'><%= image_tag pic.path, :height=>100 %></a>\r\n<%     \r\n            end \r\n        elsif\r\n%>\r\n<a href=\'<%= edit_url %>\'><%= image_tag \'/esm/thks/www/content/patient_icon.png\', :height=>100 %></a>\r\n<%\r\n		end \r\n%>\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px;float:left\">\r\n<p>\r\n<b> Patient : </b><v><%= patient.prefix_name %>  <%= patient.first_name %> <%= patient.last_name %></v>\r\n</p>\r\n<p>\r\n<b> Age : </b><v><%= year%> Years <%=month%> Months </v> <!-- | <%= patient[:birth_date] %> -->\r\n</p>\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px:float:left\">\r\n<br/>\r\n<p>\r\n<b> HN : </b><v> <%= patient.hn %></v>\r\n</p>\r\n<p>\r\n<%\r\n        # pg = patient gender\r\n        pg = \'NA\'\r\n        if patient.gender == \'1\'\r\n            pg = \'Male\'\r\n        elsif\r\n            pg = \'Female\'\r\n        end\r\n%>\r\n<b> Gender : </b><v><%=pg%> </v>\r\n</p>\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<%\r\n    elsif # if no patient\r\n%>\r\n<script>\r\n    alert(\'No Paient Found!!!\');\r\n    window.location = \"../Home/index\";\r\n</script>\r\n<%\r\n    end # end patient section\r\n%>\r\n\r\n<% if false %>\r\n<script>\r\n    <%\r\n            url = \'../../www/Patient/search_result?\'\r\n            url += \'&id=54fc51d3790f9b4e56000009\'\r\n    %>      \r\n            $.ajax({\r\n              url: \'<%=url.html_safe%>\',\r\n             success: function(data){\r\n              $(\'#patient\').html(data);  \r\n              }\r\n            });\r\n</script>\r\n<% end %>\r\n\r\n\r\n    <!--Appointment form-->\r\n    <%\r\n    procedures = (models[:procedure]).to_a\r\n    # list = %w{primary-hip-left primary-hip-right primary-knee-left primary-knee-right revision-hip-left revision-hip-right revison-knee-left revision-knee-right}\r\n    \r\n    mprocedures = {}\r\n    for i in procedures\r\n        mprocedures[i.id] = i\r\n    end\r\n    \r\n    tmp_list = []\r\n    tmp_app = nil\r\n    tmp_zam = {}\r\n    all_pm =  m_patient_module.where(:patient_id=>patient.id,:module_name=>\"\\\\#{@current_project.name}#appointment\").to_a\r\n    list = all_pm.collect do |i| \r\n        \r\n        app = models[:appointment].find(i.module_id)\r\n        procedure = mprocedures[app.procedure]\r\n        mrecord = models[procedure.code.to_s]\r\n        mr = m_patient_module.where(:parent_id=>i.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{procedure.code}\").first\r\n        record = nil\r\n        if mr\r\n            record = mrecord.find(mr.module_id)\r\n        end\r\n        follow_ups = []\r\n        follow_ups = m_patient_module.where(:parent_id=>i.id,:module_name=>\"\\\\#{@current_project.name}#follow_up_form_tka\").to_a\r\n        follow_ups = follow_ups.collect{|j| [j,(models[:follow_up_form_tka]).find(j.module_id)]}.sort{|a,b| a[1][:period].to_f<=>b[1][:period].to_f} \r\n        \r\n        # zamachita query\r\n        m_main = nil\r\n        m_follow = []\r\n        details = m_patient_module.where(:parent_id=>i.id)\r\n        for j in details do\r\n            if j.module_name == \"\\\\#{@current_project.name}#\\\\#{procedure.code}\"\r\n                m_temp = models[procedure.code.to_s]\r\n                record = m_temp.find(j.module_id)\r\n                \r\n                m_main = j\r\n                m_main[:record] = record\r\n            elsif\r\n                m_name = j.module_name.split(\'#\')[1]\r\n                m_temp = models[m_name]\r\n                record = m_temp.find(j.module_id)\r\n                \r\n                j[:record] = record\r\n                m_follow.push(j)\r\n            end\r\n        end\r\n        \r\n        # temporary var\r\n        tmp_list.push(procedure.id.to_s)\r\n        tmp_app = app\r\n        \r\n        {:id=>i.id,:created=>i[:created_at],:name=>procedure.name,:record=>record,:mrecord=>mr,:procedure=>procedure,:date=>app.inspect,:main=>i,:follow_ups=>follow_ups,:m_main=>m_main, :m_follow=>m_follow}\r\n        \r\n    end\r\n    list = list.sort_by{|i| i[:created]}.reverse\r\n    \r\n    listx = procedures.collect{|i| [i.name,i.id]}\r\n    \r\n    # remove exist operative\r\n    # listx = procedures.collect do |i| \r\n    #     if tmp_list.index(i.id.to_s).nil?\r\n    #         [i.name, i.id]\r\n    #     end\r\n    # end\r\n    %>\r\n    <%= form_for :data,:url=>\"appointment_create?\" ,:method=>\'GET\' do |f| %>\r\n    <%=hidden_field_tag :patient_id, patient.id.to_s %>\r\n    <%=hidden_field_tag :return, request.fullpath %>\r\n    <%=f.hidden_field :date, :value=>date %>\r\n                    <div class=\"clear\"></div>\r\n                    <div>\r\n                        <h4 style=\"float:left\"><%= @current_project.title %> Recrods</h4>\r\n                        \r\n    <%\r\n    if !tmp_app.nil?\r\n    %>\r\n    <%=f.hidden_field :provider, :value=>tmp_app[:provider] %>\r\n    <%\r\n    else\r\n        provider = models[:provider].where(:login=>@current_user.login).first\r\n        if provider.nil?\r\n            providers = models[:provider].all\r\n            p_select = providers.collect{|i| [i.name,i.id.to_s]}\r\n    %>\r\n                        <span style=\"float:right\">Provider :&nbsp;&nbsp; <%= f.select \'provider\', options_for_select(p_select), :style=>\'width:100px\' %> \r\n                        &nbsp;&nbsp;\r\n    <%\r\n        else\r\n    %>\r\n    <%=f.hidden_field :provider, :value=>provider.id.to_s %>\r\n    <%\r\n        end\r\n    end # provider\r\n    %>\r\n                        <span style=\"float:right\">\r\n                            <!--<%=f.check_box :bilateral %> Bilateral &nbsp;&nbsp;-->\r\n                            <%= f.select \'procedure\' ,options_for_select(listx.compact)  %>  \r\n                            <%=f.submit \'Add New\',:class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %>\r\n                        </span>\r\n                        <div class=\"clear\"></div>\r\n                    </div>\r\n    <% end %>\r\n    <!--End Appointment Form-->\r\n    <!--Start TAB-->\r\n    <%\r\n    # all appointment\r\n    \r\n    \r\n    %>\r\n    <%\r\n    \r\n    z_test = false\r\n    if z_test\r\n    %>\r\n    <!--TEST PANE-->\r\n    <div class=\"row-fluid\"></div>\r\n    <div class=\"alert alert-block alert-warning\">\r\n        LIST.<br/>\r\n        <% for i in list %>\r\n        \r\n        <b><%= side %>.</b> : <%= i[:record].inspect %>\r\n        <hr/>\r\n        <% end %>\r\n        tmp_list <%= tmp_list.size %>. <%= tmp_list %><hr/><%= procedures.collect{|i| i.id} %>\r\n    \r\n    </div>\r\n    <%\r\n    end # end test\r\n    %>\r\n                    <div class=\"clear\"></div>\r\n                    <!--<div class=\"tabbable tabs-left\" style=\"border:1px solid #ccc; -moz-border-radius: 5px; border-radius: 5px;\">-->\r\n                    <div class=\"tabbable\" style=\"border:1px solid #ccc; -moz-border-radius: 5px; border-radius: 5px;\">\r\n                        <ul class=\"nav nav-tabs\" style=\"background:#F4F4F4; -moz-border-radius: 5px;border-radius: 5px;\">\r\n                            <li class=\"active\" >\r\n                                <a href=\"#tab_dashboard\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >Dashboard</a>\r\n                            </li>\r\n                            <!--More TAB-->\r\n                            <% for i in list do %>\r\n                            <%\r\n                                side = \'-\'\r\n                                bi = false\r\n                                if i[:record]\r\n                                    if i[:record][:side] == \'1\'\r\n                                        side = \'L\'\r\n                                    elsif i[:record][:side] == \'2\'\r\n                                        side = \'R\'\r\n                                    end\r\n                                    \r\n                                    if i[:record][:bilateral] == \'1\'\r\n                                        bi = true\r\n                                    end\r\n                                end\r\n                            %>\r\n                            <li class=\"\">\r\n                                <a href=\"#tab_<%=i[:id]%>\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >\r\n                                    <%=i[:name]%> (<%= side %>) <font color=\'red\'><%= \'*\' if bi %></font><br/>\r\n                                </a>\r\n                            </li>\r\n                            <% end %>\r\n                        </ul>\r\n   \r\n                        <!--<div class=\"tab-content\" style=\"width:640px;border:0px solid;float:left; clear:none;margin-left:-20px;\">-->\r\n                        <div class=\"tab-content\">\r\n                            <div class=\"tab-pane  <%= \'active\' if true %>\" style=\"border:0px solid;\" id=\"tab_dashboard\">\r\n                                <br/>\r\n                                <h3>Dashboard</h3>\r\n                                <div class=\"row-fluid\"><br/></div>\r\n    <%\r\n    if list.size == 0\r\n    %>\r\n                                Welcome\r\n    <%\r\n    elsif\r\n    %>\r\n                                Welcome :)\r\n    <%\r\n    end\r\n    %>\r\n                            </div>\r\n    <!--More TAB Content-->\r\n                            <% for i in list do %>\r\n                            <%\r\n                                side = \'-\'\r\n                                if i[:record]\r\n                                    if i[:record][:side] == \'1\'\r\n                                        side = \'L\'\r\n                                    elsif i[:record][:side] == \'2\'\r\n                                        side = \'R\'\r\n                                    end\r\n                                end\r\n                            %>\r\n                            <div class=\"tab-pane\" style=\"border:0px solid;\" id=\"tab_<%= i[:id] %>\">\r\n                                <br/>\r\n                                <div class=\"row-fluid\">\r\n                                    <h3><%= i[:name] %> (<%= side %>)</h3>\r\n    <%\r\n        mname = i[:procedure].code.humanize\r\n        mr = i[:m_main]\r\n        show = \"\"\r\n        if mr\r\n            show = link_to(\"Edit \", \"../\\\\#{mname}/edit?id=\\\\#{mr.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}#tab_\\\\#{i[:id]}\",:class=>\'btn btn-small btn-info\')\r\n            show += \' \'\r\n            show += link_to(\'Print\',\"../\\\\#{mname}/print?id=\\\\#{mr.id}&return=\\\\#{request.fullpath}#tab_\\\\#{i[:id]}\",:target=>\'_blank\' ,:class=>\'btn btn-small\')\r\n        else\r\n            show =  link_to(\'Create\',\"../\\\\#{mname}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-small btn-success\')\r\n        end\r\n    %>\r\n                                    <%= link_to \'\', \"\", :title=>\'Delete operation\', :class=>\'splashy-error_x\', :style=>\'float:right;margin-top:-30px\', :onclick=>\"javascript:confirm_delete(\'\\\\#{i[:id]}\'); return false;\"%>\r\n                                    <div style=\"float:right\"><%# show %></div>\r\n                                </div>\r\n    <% if mr %>\r\n                                <font size=\"1\" style=\"color:gray\">Created at <%= i[:m_main][:record][:created_at].strftime(\"%d/%m/%Y\") %> | Last Updated at <%= i[:m_main][:record][:updated_at].strftime(\"%d/%m/%Y\") %> </font>\r\n                                <hr/>\r\n                                <!--Operation Date : <%= i[:m_main][:record][:operation_date] %>-->\r\n    <% elsif %>\r\n                                <font size=\"1\" style=\"color:gray\">No operation available </font>\r\n                                <hr/>\r\n                                <!--Create Operation-->\r\n    <% end %>\r\n                                <div style=\"margin-left:20px\"></div><%= show %>\r\n                                <div class=\"row-fluid\"><br/></div>\r\n                                <!--<div class=\"alert alert-info\">-->\r\n    <%\r\n        form_service = nil\r\n        if mr\r\n            m_form = mr[:module_name]\r\n            form_service = \"FollowUpHip\"\r\n            if m_form.index(\'knee\')\r\n                form_service = \"FollowUpKnee\"\r\n            end\r\n            c_link = \"../\\\\#{form_service}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\"\r\n            \r\n            m_follow = i[:m_follow].collect{|i| [i.id, i[:module_name], i[:record]]}.sort{|a,b| a[2][:period].to_f<=>b[2][:period].to_f}\r\n            f_link = {}\r\n            for j in m_follow do\r\n                f_link[j[2].id] = [j[0], j[1]]\r\n            end\r\n            \r\n            labels = {:period=>\'Period\', :date=>\'Date\', :height=>\'Height\', :weight=>\'Weight\'}\r\n            if m_form.index(\'hip\')\r\n                labels[:hhs_hip_score] = \'Hip Score\'\r\n            else\r\n                labels[:womac_total_womac_score] = \'WOMAC\'\r\n                labels[:kss_total_knee_score] = \'Knee Score\'\r\n            end\r\n            m_labels = labels.keys\r\n            \r\n    %>\r\n                                    <hr/>\r\n                                    <div style=\"float:left\"><strong><font size=\"3\">Follow up</font></strong></div>\r\n                                    <%= link_to \'Create\', c_link, :style=>\'float:right;margin-top:10px\', :class=>\'btn btn-small btn-success\' %>\r\n                                    <div class=\"row-fluid\"></div>\r\n    <!--Follow up table -->\r\n    <%= tabular :data=> m_follow.collect{|j| j[2]},:labels=>labels ,:model=>m_labels do |row,out|\r\n        l = f_link[row.id]\r\n        link_ext = l[1].split(\'#\')[1].split(\'_\').map(&:capitalize).join(\'\')\r\n        out[0] = \"\\\\#{(row.period.to_i)} m\"\r\n        out[1] = row[:created_at].strftime(\"%d-%m-%y\")\r\n        \r\n        show = link_to(\"\", \"../\\\\#{link_ext}/edit?id=\\\\#{l[0]}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\", :class=>\'splashy-document_a4_edit\', :title=>\'Edit\')\r\n        # show = \"<a title=\'Edit\' href=\'../\\\\#{link_ext}/edit?id=\\\\#{l[0]}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\'><img src=\'/gebo/img/gCons/edit.png\' alt=\'\' /></a>\"\r\n        show += \'&nbsp;&nbsp;&nbsp;\'.html_safe\r\n        show += link_to(\'\',\"\", :onclick=>\"javascript:confirm_delete_followup(\'\\\\#{l[0]}\'); return false;\", :class=>\'splashy-document_a4_remove\', :title=>\'Remove\')\r\n        show += \'&nbsp;&nbsp;&nbsp;\'.html_safe\r\n        show += link_to(\'\',\"../\\\\#{link_ext}/print?id=\\\\#{l[0]}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'splashy-printer\', :title=>\'Print\')\r\n        # show += \"</i>\".html_safe\r\n        # show += \"<a title=\'Print\' href=\'../\\\\#{link_ext}/edit?id=\\\\#{l[0]}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\'><img src=\'/gebo/img/gCons/print.png\' alt=\'\' /></a>\"\r\n        out << show\r\n    \r\n        out\r\n    end%>\r\n    \r\n    <%\r\n        end # end follow up\r\n    %>\r\n                                <!--</div>-->\r\n                            </div>\r\n                            <% end %>\r\n                            \r\n                        </div>\r\n                    </div>\r\n    <!--End TAB-->\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    </div>\r\n    <br/><br/>\r\n<script>\r\n    // alert(\"<%= request.fullpath.html_safe %>\");\r\n    \r\n    function confirm_delete(id) {\r\n        if (confirm(\'Do you want to delete this operation?\') == true) {\r\n            // ../Appointment/destroy?id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\r\n<%\r\n    destroy_url = \"destroy?mode=main&id=\"\r\n    return_url = \"&return=\" + request.fullpath\r\n%>\r\n            url = \"<%= destroy_url.html_safe %>\" + id + \"<%= return_url.html_safe %>\";\r\n            window.location.href = url;\r\n        } \r\n    }\r\n    function confirm_delete_followup(id) {\r\n        if (confirm(\'Do you want to delete this follow up?\') == true) {\r\n<%\r\n    destroy_url = \"destroy?mode=followup&id=\"\r\n    return_url = \"&return=\" + request.fullpath\r\n%>\r\n            url = \"<%= destroy_url.html_safe %>\" + id + \"<%= return_url.html_safe %>\";\r\n            window.location.href = url;\r\n        }\r\n    }\r\n</script>\r\n    \r\n    \r\n    <script>\r\n    $(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n    </script>\r\n     \r\n\r\n',NULL,NULL,NULL,'2015-06-09 15:57:47','2015-06-09 15:57:47','patient_record',''),(1629,'print_bk',714,3,'<style>\r\n    input {color:#380BBB;}\r\ninput[type=checkbox] + label {\r\n  color: #ccc;\r\n  font-style: italic;\r\n} \r\ninput[type=checkbox]:checked + label {\r\n  color: #f00;\r\n  font-style: normal;\r\n} \r\n</style>\r\n<div style=\"width:1000px; margin-left:auto; margin-right:auto; margin-top:0px;\">\r\n\r\n  <table width=\"100%\" border=\"0\" cellpadding=\"2\" cellspacing=\"2\">\r\n    <tr>\r\n      <td width=\"50%\" height=\"458\" valign=\"top\">\r\n      <center><img src=\"http://pni.go.th/pnigoth/wp-content/uploads/2009/05/LogoPrasatNew_02-300x212.jpg\" width=\"100px\" /><br />\r\n      Department of Anesthesology สป.75(3)<br />\r\n      Prasat Neurological institute<br />\r\n      Preanesthetic evaluation and medication record\r\n      <br /><br />\r\n      History</center><br />\r\n      Underlying disease\r\n      <br />\r\n<input type=\"checkbox\"  class=\"checkbxinput\"  name=\"checkbox4\" id=\"checkbox4\" />\r\nYes\r\n<input type=\"checkbox\" name=\"checkbox4\" id=\"checkbox4\" /> \r\nNo\r\n<br />\r\n<table width=\"100%\" border=\"0\">\r\n  <tr>\r\n    <td width=\"28%\">Underlying disease<br />\r\n      <input type=\"checkbox\" name=\"checkbox6\" id=\"checkbox6\" />\r\nYes\r\n<input type=\"checkbox\" name=\"checkbox6\" id=\"checkbox6\" />\r\nNo <br />\r\n<br />\r\nHabit \r\n<input type=\"checkbox\" name=\"checkbox10\" id=\"checkbox10\" />\r\nSmoking</td>\r\n    <td width=\"72%\"><input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nDM\r\n  <input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nHT\r\n<input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nTB\r\n<input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nCOPD\r\n<input type=\"checkbox\" name=\"checkbox3\" id=\"checkbox3\" />\r\nAsthma<br />\r\n<input type=\"checkbox\" name=\"checkbox5\" id=\"checkbox5\" />\r\nHeart disease<br />\r\n<input type=\"checkbox\" name=\"checkbox7\" id=\"checkbox7\" />\r\nOther<br />\r\n<input type=\"checkbox\" name=\"checkbox8\" id=\"checkbox8\" />\r\nAlcohol\r\n<input type=\"checkbox\" name=\"checkbox9\" id=\"checkbox9\" />\r\nOther<input type=\"text\" name=\"textfield\" id=\"textfield\" />\r\n</td>\r\n  </tr>\r\n</table>\r\n<br />\r\n  Allergy Hx \r\n  <input type=\"text\" name=\"textfield2\" id=\"textfield2\" />\r\n  <br />\r\n  Family Hx \r\n  <input type=\"text\" name=\"textfield3\" id=\"textfield3\" />\r\n  <br />\r\n  LMP \r\n 