c51d3790f9b4e56000009\'\r\n    t3_id = \'54fc53c2790f9b5214000003\'\r\n    t4_id = \'54fc53f8790f9b4e5600001a\'\r\n    \r\n    if params[:id].nil?\r\n        params[:id] = t2_id\r\n    end\r\n    \r\n    tmp = {}\r\n    tmp[:params] = params\r\n    tmp[:xxx] = models[:appointment].find(params[:patient_id])\r\n    # tmp[:patient_module] = patient_module_model.find(\'553d367b790f9b7dbe000017\')\r\n    # tmp[:patient_module] = patient_module_model.all(:patient_id=>t2_id)\r\n    # tmp[:patient] = m_patient.all\r\n    # tmp[:test] = patient_module_model.where(:patient_id=>t2_id,:module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    # tmp[:ap] = {}\r\n    count = 1\r\n    p_ap = patient_module_model.where(:patient_id=>params[:id],:module_name=>\"\\\\#{@current_project.name}#appointment\",:order=>\'date desc\')\r\n    for i in p_ap do\r\n        ap_id = i.id\r\n        pm = patient_module_model.where(:parent_id=>ap_id).to_a\r\n        count += 1\r\n    end\r\n    \r\n    procedures = (models[:procedure]).to_a\r\n    mprocedures = {}\r\n    for i in procedures\r\n        mprocedures[i.id] = i\r\n    end\r\n    # tmp[:providers] = (models[:provider]).to_a\r\n    # tmp[:procedures] = procedures\r\n    # tmp[:mprocedures] = mprocedures\r\n    # tmp[:test] = @current_application\r\n    # tmp[:appointment_only] = patient_module_model.where(:module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    # tmp[:knee1_only] = patient_module_model.where(:module_name=>\"\\\\#{@current_project.name}#knee1\")\r\n    tmp[:ap_proc] = patient_module_model.where(:module_name=>\"\\\\#{@current_project.name}#appointment\").collect do |i|\r\n        am = models[:appointment].find(i.module_id)\r\n        procedure = mprocedures[am.procedure]\r\n        code = procedure[:code]\r\n        m_code = \"\\\\#{@current_project.name}#\\\\#{code}\"\r\n        m_tmp = patient_module_model.where(:module_name=>m_code, :parent_id=>i.id).first\r\n        side = \'-\'\r\n        if m_tmp\r\n            rec = models[code.to_sym].find(m_tmp[:module_id])\r\n            \r\n            if rec[:side] == \'1\'\r\n                side = \'L\'\r\n            elsif rec[:side] == \'2\'\r\n                side = \'R\'\r\n            end\r\n        end\r\n        {:id=>i.id,:name=>procedure[:name],:m_code=>m_code,:side=>side,:appointment=>i,:procedure=>procedure}\r\n    end\r\n    tmp[:all_appointment] = patient_module_model.where(:module_name=>\"\\\\#{@current_project.name}#appointment\").collect do |i|\r\n        am = models[:appointment].find(i.module_id)\r\n        procedure = mprocedures[am.procedure]\r\n        \r\n        m_main = nil\r\n        m_follow = []\r\n        details = patient_module_model.where(:parent_id=>i.id)\r\n        for j in details do\r\n            if j.module_name == \"\\\\#{@current_project.name}#\\\\#{procedure.code}\"\r\n                m_temp = models[procedure.code.to_s]\r\n                record = m_temp.find(j.module_id)\r\n                \r\n                m_main = j\r\n                m_main[:record] = record\r\n                # m_main[:tmp] = (models[m_name]).find(j.module_is)\r\n            elsif\r\n                # x = j.clone\r\n                m_name = j.module_name.split(\'#\')[1]\r\n                m_temp = models[m_name]\r\n                record = m_temp.find(j.module_id)\r\n                \r\n                j[:record] = record\r\n                m_follow.push(j)\r\n            end\r\n        end\r\n        x = i\r\n        \r\n        {:id=>i.id, :m_main=>m_main, :m_follow=>m_follow, :appointment=>am, :procedure=>procedure, :pm_appointment=>i}\r\n        \\\\#{|i| {:appointment=>i,:detail=>patient_module_model.where(:parent_id=>i.id)}}\r\n    end\r\n    \r\n    # tmp[:all_patient_module] = patient_module_model.all\r\n%>\r\n<%= tmp.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2015-06-09 16:56:10','2015-06-09 16:56:10','test',''),(1632,'index',732,2,'<%\r\nmodule_name = @current_project.name\r\nif params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\nend\r\nif session[module_name]\r\n	params[:date] = session[module_name][:date]\r\nend\r\nunless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\nend\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    provider = models[:provider].where(:login=>@current_user.login).first\r\n    if provider\r\n       s_provider = provider.id.to_s\r\n    end\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       My Patients\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\'../Home/index\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n            \r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n                \r\n            </div>\r\n            </span>\r\n            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            \r\n            \r\n            <div class=\"field-input\">\r\n                 <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                 \r\n                 <%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>\r\n            </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            <div class=\"field-input\">\r\n            <%\r\n            # Home/patient_record?id=5533e537790f9b01c2000006\r\n                add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n                if s_provider \r\n                    # add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                    add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                end\r\n                \r\n            %>\r\n              \r\n                 <%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>\r\n            </div>\r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        </div>\r\n        <div class=\"row-fluid\"></div>\r\n \r\n<strong>\r\n<%\r\n    rs = []\r\n    if !search_patient and params[:select].nil?\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\").all\r\n    	end\r\n    %>\r\n    <!--ALL : <%= rs.size %>-->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name, :last_name=>s_last_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n        # patients = patient_model.where(criteria).limit(20).all\r\n        patients = patient_model.where(criteria).all\r\n	    # maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}\r\n        # aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     	    rs = module_model.where(:patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\"\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT : <%= rs.size %>-->\r\n    <%\r\n    elsif params[:date]\r\n        require \'date\'\r\n        dddd = Date.parse(params[:date])\r\n	    conds = {:date.gte=>dddd.at_beginning_of_day,:date.lt=>dddd.end_of_day, :module_name=>\"\\\\#{@current_project.name}#provider\"}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n            conds.merge! :module_id=>s_provider \r\n            # conds[:module_id] = s_provider\r\n            # conds[:module_name] = @current_project.name + \"#provider\"\r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n        rs = module_model.where(conds).all\r\n        # aps = ap_model.all(conds)\r\n    	# filter provider\r\n    # 	if s_provider and s_provider != \'\'\r\n     	  #  conds[:module_id] = s_provider\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    #  	else\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    # 	end\r\n    	\r\n    # 	rs = module_model.all(conds)\r\n        # rs = module_model.all\r\n\r\n    %>\r\n    <!--DATE : <%=rs.size%> | <%= conds %>-->\r\n    <%\r\n    end # end if\r\n%>\r\n</strong>\r\n<!--<br/>-->\r\n<!--<br/>-->\r\n<%\r\nm_procedure = models[:procedure].all\r\nmap_proc = {}\r\nfor m in m_procedure do\r\n    map_proc[m.id] = m\r\nend\r\n\r\nm_provider  = models[:provider].all\r\nmap_prov = {}\r\nfor m in m_provider do \r\n    map_prov[m.id.to_s] = m[:name]\r\nend\r\nresult = rs.collect do |i|\r\n    m_patient = patient_model.find(i[:patient_id].to_s)\r\n    \r\n    patient_name = m_patient[:first_name] + \" \" + m_patient[:last_name]\r\n    \r\n    # prov = map_prov[i[:id]]\r\n    m_id = i[:module_id].to_s\r\n    prov = map_prov[m_id]\r\n    \r\n    # prov = nil\r\n    proc_rs = []\r\n    m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    for m in m_ap do\r\n        ap = models[:appointment].find(m[:module_id])\r\n        if ap\r\n            # proc_rs.push(map_proc[ap[:procedure]])\r\n            procedure = map_proc[ap[:procedure]]\r\n            code = procedure[:code]\r\n            name = procedure[:name]\r\n            m_code = \"\\\\#{@current_project.name}#\\\\#{code}\"\r\n            m_tmp = module_model.where(:module_name=>m_code, :parent_id=>m.id).first\r\n            side = \'-\'\r\n            if m_tmp\r\n                rec = models[code.to_sym].find(m_tmp[:module_id])\r\n                if rec[:side] == \'1\'\r\n                    side = \'L\'\r\n                elsif rec[:side] == \'2\'\r\n                    side = \'R\'\r\n                end\r\n            end\r\n            txt = name + \" (\" + side + \") \"\r\n            proc_rs.push(txt)\r\n        end\r\n    end\r\n    \r\n    # tmp = patient_module_model.where(:module_name=>\"\\\\#{@current_project.name}#appointment\").collect do |i|\r\n    #     am = models[:appointment].find(i.module_id)\r\n    #     procedure = mprocedures[am.procedure]\r\n    #     code = procedure[:code]\r\n    #     m_code = \"\\\\#{@current_project.name}#\\\\#{code}\"\r\n    #     m_tmp = patient_module_model.where(:module_name=>m_code, :parent_id=>i.id).first\r\n    #     side = \'-\'\r\n    #     if m_tmp\r\n    #         rec = models[code.to_sym].find(m_tmp[:module_id])\r\n            \r\n    #         if rec[:side] == \'1\'\r\n    #             side = \'L\'\r\n    #         elsif rec[:side] == \'2\'\r\n    #             side = \'R\'\r\n    #         end\r\n    #     end\r\n    #     {:id=>i.id,:name=>procedure[:name],:m_code=>m_code,:side=>side,:appointment=>i,:procedure=>procedure}\r\n    # end\r\n    \r\n    proc_txt = \'<center><font color=\"red\">-- Create New --</font></center>\'\r\n    if !proc_rs.empty?\r\n        proc_txt = \'\'\r\n        for x in proc_rs do\r\n            proc_txt += \'<center><div class=\"row-fluid\">\' + x.to_s + \'</div></center> \'\r\n        end\r\n    end\r\n    action = \' \'\r\n    action += link_to(\'Detail\',\"patient_record?id=\\\\#{i[:patient_id]}\",:class=>\'btn btn-info\')\r\n    action += \" \"\r\n    action += link_to(\'\', \"../../www/Patient/edit?id=\\\\#{m_patient.id}&return=\\\\#{request.fullpath}\", :class=>\'splashy-contact_blue_edit\').html_safe\r\n    action += \" \"\r\n    action += link_to(\'\', \"\", :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{m_patient.id}\'); return false;\")\r\n    action += \" \"\r\n    \r\n    {:date=>i[:date], :hn=>m_patient[:hn], :name=>patient_name, :pid=>i[:patient_id], :procedure=>proc_txt, :action=>action, :provider=>prov}\r\nend\r\ncount = 1\r\nlabels = {:no=>\'No.\', :date=>\'Date\', :hn=>\'HN\', :name=>\'Patient Name\', :procedure=>\'Previous Procedure\', :action=>\'Action\'}\r\nfield_select = [:no, :date, :hn, :name, :procedure, :action]\r\n\r\nif @current_role == \'developer\'\r\n    labels[:provider] = \'Provider\'\r\n    field_select.insert(4, :provider)\r\nend\r\nresult = result.sort_by{|i| i[:date]}.reverse\r\n%>\r\n        <div id=\"result-panel\" style=\"padding:10px\">\r\n            <%= tabular :data=>result, :model=>field_select, :labels=>labels, :width=>{:no=>\'30px\'} do |row,out|\r\n                    out[0] = count.to_s+\".\"\r\n                    count+=1\r\n                 out\r\n             end\r\n            %>\r\n        </div>\r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function confirm_delete(id) {\r\n        // destroy?id=\\\\#{m_patient.id}&mode=patient&return=\\\\#{request.fullpath}\r\n<%\r\n    destroy_url = \"destroy?mode=patient&id=\".html_safe\r\n    return_url  = \"&return=\\\\#{request.fullpath}\".html_safe\r\n%>\r\n        if (confirm(\"Do you want to delete patient data ?\") == true) {\r\n            if (confirm(\"All of patient data will be lost\") == true) {\r\n                url = \"<%= destroy_url %>\" + id + \"<%= return_url %>\";\r\n                window.location = url;\r\n            }\r\n        }\r\n    }\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<!--\r\n<div class=\"alert \">\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n</div>\r\n-->\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2015-06-15 04:00:07','2015-06-15 04:00:07','index',''),(1633,'mail',732,3,'<%\r\nrequire \'net/smtp\'\r\n\r\nmsg = \'Hello\'\r\nif params[:msg]\r\n    msg = params[:msg]\r\nend\r\n\r\nmessage = <<MESSAGE_END\r\nFrom: Private Person <me@fromdomain.com>\r\nTo: A Test User <test@todomain.com>\r\nMIME-Version: 1.0\r\nContent-type: text/html\r\nSubject: SMTP e-mail test\r\n\r\nThis is an e-mail message to be sent in HTML format...\\\\#{msg}\r\n\r\n<b>This is HTML message.</b>\r\n<h1>This is headline.</h1>\r\nMESSAGE_END\r\n\r\nNet::SMTP.start(\'localhost\') do |smtp|\r\n  smtp.send_message message, \'ehr@esm-solution.com\', \r\n                             \'chaiwat.bootchai@gmail.com\'\r\nend\r\n%>',NULL,NULL,NULL,'2015-06-15 05:02:40','2015-06-15 05:02:40','mail',''),(1634,'update_attr',666,3,'<%\r\n    models = get_model\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient = ehr_models[:patient]\r\n    m_patient_module = ehr_models[:patient_module]\r\n    \r\n    procedure = models[:procedure].all\r\n    appointment = models[:appointment].all\r\n    \r\n    map_side = {\r\n        \"554ef5ca790f9b40fd000016\"=>\'2\',\r\n        \"554ef5e3790f9b40fd000019\"=>\'2\',\r\n        \"554ef677790f9b40fd000021\"=>\'1\',\r\n        \"554ef685790f9b40fd000024\"=>\'1\',\r\n        \"554ef6b8790f9b40fd000028\"=>\'2\',\r\n        \"554ef6d1790f9b40fd00002e\"=>\'2\',\r\n        \"554ef6ed790f9b40fd000031\"=>\'1\',\r\n        \"554ef700790f9b40fd000034\"=>\'1\'\r\n    }\r\n    map_x = {\r\n        \'554ef5ca790f9b40fd000016\' => \'554ef677790f9b40fd000021\',\r\n        \'554ef5e3790f9b40fd000019\' => \'554ef685790f9b40fd000024\',\r\n        \'554ef6b8790f9b40fd000028\' => \'554ef6ed790f9b40fd000031\',\r\n        \'554ef6d1790f9b40fd00002e\' => \'554ef700790f9b40fd000034\'\r\n    }\r\n    map_proc = {}\r\n    for x in procedure do\r\n        x[:side] = map_side[x.id.to_s]\r\n        map_proc[x.id.to_s] = x\r\n    end\r\n    \r\n    m_app = m_patient_module.where(:module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    \r\n    res = {}\r\n    res[:procedure] = procedure.collect do |i|\r\n        side = map_side[i.id.to_s]\r\n        {:id=>i.id, :side=>side, :name=>i.name, :code=>i.code}\r\n    end\r\n    res[:app_size] = appointment.size\r\n    res[:m_app_size] = m_app.size\r\n    \r\n    res[:process] = m_app.collect do |i|\r\n        ap = models[:appointment].find(i[:module_id])\r\n        proc_id = ap[:procedure].to_s\r\n        rec_proc = map_proc[proc_id]\r\n        \r\n        # if map_x.has_key?(proc_id)\r\n        #     ap.update_attributes :procedure=>map_x[proc_id]\r\n        # end\r\n        \r\n        code = rec_proc[:code]\r\n        name = rec_proc[:name]\r\n        side = rec_proc[:side]\r\n        m_code = \"\\\\#{@current_project.name}#\\\\#{code}\"\r\n        \r\n        rec = nil\r\n        tmp = m_patient_module.where(:module_name=>m_code,:parent_id=>i.id.to_s).first\r\n        if tmp\r\n            rec = models[code.to_sym].find(tmp[:module_id])\r\n        end\r\n        {:id=>i.id,:name=>name,:code=>code,:m_code=>m_code,:side=>side,:appointment=>ap, :rec_proc=>rec_proc}\r\n    end\r\n    res[:m_app] = m_app\r\n    \r\n    # res[:test] = procedure.select{|i| i[:id] == \"554ef6d1790f9b40fd00002e\"}\r\n    # res[:appointment] = appointment\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-06-15 06:44:26','2015-06-15 06:44:26','update_attr',''),(1635,'agree',666,2,'<div class=\"row-fluid\">\r\n    <div class=\"well\">\r\n        <div class=\"span2\"><a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#myModal1\" class=\"btn\">Regular</a></div>\r\n        <div class=\"modal hide\" id=\"myModal1\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Modal header</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n									Lorem ipsum dolor sit amet, consectetur adipiscing elit. Pellentesque non elit tellus, eleifend varius erat. Lorem ipsum dolor sit amet, consectetur adipiscing elit. In bibendum laoreet ante sodales elementum. Nullam varius interdum est, at ornare quam aliquam eu. Nulla ultricies commodo leo sit amet vulputate.\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n								    <a href=\"#\" onclick=\"javascript:logout();\" class=\"btn\" data-dismiss=\"modal\">Ignore</a>\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Accept</a>\r\n								</div>\r\n							</div>\r\n    </div>\r\n</div>\r\n<script>\r\n    function logout() {\r\n        // alert(\'You not agree.\');\r\n        window.location = \"/user/logout\";\r\n    }\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2015-06-16 05:52:10','2015-06-16 05:52:10','agree',''),(1636,'document_name',734,1,'\'kss_2015_pre\'',NULL,NULL,NULL,'2015-06-17 09:04:54','2015-06-17 09:04:54',NULL,NULL),(1637,'document_name',735,1,'\'kss2_pre\'',NULL,NULL,NULL,'2015-06-18 06:43:11','2015-06-18 06:43:11',NULL,NULL),(1640,'script',735,3,'<body>\r\n<%\r\nsumgroup = this.sumgroup\r\n%>\r\n<pre>\r\n    <%= sumgroup.size %> : <%= sumgroup %>\r\n</pre>\r\nGenerate Script\r\n<pre>\r\n<%\r\n    doc_ready = \'\\n\'\r\n    sumgroup.each do |k, v|\r\n        ks = \'\' # select\r\n        kr = \'\' # radio\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \"// \" + k.to_s + \"\\n\"\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \'tmp_score = $(\"#data-\' + v[:total].to_s + \'\").val();\\n\'\r\n        doc_ready += \"if (tmp_score == \'\') { \\n  $(\'#data-\\\\#{v[:total].to_s}\').val(\'0\');\\n}\\n\"\r\n        \r\n        if v[:select]\r\n            ks = k.to_s + \"_select\"\r\n            doc_ready += \"for (var i in \\\\#{ks}) {\\n\"\r\n            doc_ready += \"  f = \'#data-\' + \\\\#{ks}[i];\\n\"\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n%>\r\nvar <%= ks %> = [\"<%= v[:select].join(\'\",\"\') %>\"];\r\n<%\r\n        end\r\n        if v[:radio]\r\n            kr = k.to_s + \"_radio\"\r\n            doc_ready += \"for (var i in \\\\#{kr}) {\\n\"\r\n            doc_ready += \'  f = \"input[id^=\' + \"\'update_\" + \'\" + \' + \"\\\\#{kr}[i] + \" + \'\"\' + \"\']\" + \'\";\\n\'\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n            \r\n%>\r\nvar <%= kr %> = [\"<%= v[:radio].join(\'\",\"\') %>\"];\r\n<%\r\n        end\r\n%>\r\nfunction <%= k %>() {\r\n    sum = 0;\r\n<% if v[:select] %>\r\n    for (var i in <%= ks %>) {\r\n        f = \"#data-\" + <%= ks %>[i];\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n<% if v[:radio] %>\r\n    for (var i in <%= kr %>) {\r\n        f = \"input[id^=\'update_\" + <%= kr %>[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n\r\n    console.log(\"<%= k %> = \" + sum);\r\n\r\n    $(\"#data-<%= v[:total] %>\").val(sum);\r\n}\r\n<%\r\n    end\r\n%>\r\n</pre>\r\n\r\nDocument Ready\r\n<pre>\r\n    $(document).ready(function(){\r\n    // ---\r\n    // symptoms\r\n    // ---\r\n    score = 0;\r\n    tmp_score = $(\"#data-kss2_total_symptoms\").val();\r\n    if (tmp_score != \'\') {\r\n        score = tmp_score;\r\n    } else {\r\n        $(\"#data-kss2_total_symptoms\").val(\'0\');\r\n    }\r\n    for (var i in symp_update) {\r\n        f = \"#data-\" + symp_update[i];\r\n        $(f).change(symptom_update);\r\n    }\r\n    for (var i in symp_radio) {\r\n        f = \"input[id^=\'update_\" + symp_radio[i] + \"\']\";\r\n        $(f).change(symptom_update);\r\n    }\r\n    <%= doc_ready %>\r\n</pre>\r\n</body>',NULL,NULL,NULL,'2015-06-25 04:15:52','2015-06-25 04:15:52','script',''),(1641,'sumgroup',735,1,'{\r\n	:symptom_update => {\r\n		:select => [:kss2_pain_walking, :kss2_pain_stairs],\r\n		:radio => [:kss2_ask_normal],\r\n		:total => :kss2_total_symptoms\r\n	},\r\n	:patient_satisfaction_update => {\r\n	    :select => [:kss2_satisfied_sitting, :kss2_satisfied_lying, :kss2_satisfied_getting_out, :kss2_satisfied_performing, :kss2_satisfied_activities],\r\n	    :total => :kss2_total_patient_satisfaction\r\n	},\r\n	:patient_expectation_update => {\r\n	    :select => [:kss2_expect_knee_pain, :kss2_expect_daily_living, :kss2_expect_perform_activities],\r\n	    :total => :kss2_total_patient_expectation\r\n	},\r\n	:walking_standing_update => {\r\n	    :select => [:kss2_aid_use_no],\r\n	    :radio => [:kss2_aid_sitting, :kss2_aid_stoping],\r\n	    :total => :kss2_total_walking_and_standing\r\n	},\r\n	:standard_activities_update => {\r\n	    :select => [:kss2_standard_walking, :kss2_standard_getting_up, :kss2_standard_getting_into, :kss2_standard_turning, :kss2_standard_climbing, :kss2_standard_moving],\r\n	    :total => :kss2_total_standard_activities\r\n	},\r\n	:advanced_activities_update => {\r\n	    :select => [:kss2_advanced_climbing, :kss2_advanced_carrying, :kss2_advanced_squatting, :kss2_advanced_kneeling, :kss2_advanced_running],\r\n	    :total => :kss2_total_advanced_activities\r\n	}, \r\n	:discretion_update => {\r\n	    :select => [:kss2_discretion_ch_1, :kss2_discretion_ch_2, :kss2_discretion_ch_3],\r\n	    :total => :kss2_total_discretionary_knee_activities\r\n	}\r\n}',NULL,NULL,NULL,'2015-06-25 05:58:32','2015-06-25 05:58:32','sumgroup',''),(1642,'form',735,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n<%\r\nsumgroup = this.sumgroup\r\nif sumgroup != \'No service\'\r\n\r\n    doc_ready = \'\\n\'\r\n    sumgroup.each do |k, v|\r\n        ks = \'\' # select\r\n        kr = \'\' # radio\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \"// \" + k.to_s + \"\\n\"\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \'tmp_score = $(\"#data-\' + v[:total].to_s + \'\").val();\\n\'\r\n        doc_ready += \"if (tmp_score == \'\') { \\n  $(\'#data-\\\\#{v[:total].to_s}\').val(\'0\');\\n}\\n\"\r\n%>\r\n\r\n// ---\r\n// Generate for function <%= k %>\r\n// --- zam ---\r\n<%\r\n        if v[:select]\r\n            ks = k.to_s + \"_select\"\r\n            doc_ready += \"for (var i in \\\\#{ks}) {\\n\"\r\n            doc_ready += \"  f = \'#data-\' + \\\\#{ks}[i];\\n\"\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n%>\r\nvar <%= ks %> = [\"<%= v[:select].join(\'\",\"\').html_safe %>\"];\r\n<%\r\n        end\r\n        if v[:radio]\r\n            kr = k.to_s + \"_radio\"\r\n            doc_ready += \"for (var i in \\\\#{kr}) {\\n\"\r\n            doc_ready += \'  f = \"input[id^=\' + \"\'update_\" + \'\" + \' + \"\\\\#{kr}[i] + \" + \'\"\' + \"\']\" + \'\";\\n\'\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n            \r\n%>\r\nvar <%= kr %> = [\"<%= v[:radio].join(\'\",\"\').html_safe %>\"];\r\n<%\r\n        end\r\n%>\r\nfunction <%= k %>() {\r\n    sum = 0;\r\n<% if v[:select] %>\r\n    for (var i in <%= ks %>) {\r\n        f = \"#data-\" + <%= ks %>[i];\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n<% if v[:radio] %>\r\n    for (var i in <%= kr %>) {\r\n        f = \"input[id^=\'update_\" + <%= kr %>[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n\r\n    console.log(\"<%= k %> = \" + sum);\r\n\r\n    $(\"#data-<%= v[:total] %>\").val(sum);\r\n}\r\n<%\r\nend # end generate script\r\n%>\r\n\r\nvar ans = [];\r\nfunction recreational_change() {\r\n    txt = $(this).val();\r\n    lbn = $(this).parent().text().trim();\r\n    console.log(\'recreational >>> \' + lbn);\r\n    \r\n    update_three_field(lbn);\r\n}\r\nfunction workout_change() {\r\n    txt = $(this).val();\r\n    lbn = $(this).parent().text().trim();\r\n    console.log(\'workout >>> \' + lbn);\r\n    \r\n    update_three_field(lbn);\r\n}\r\nfunction update_three_field(lbn) {\r\n    idx = ans.indexOf(lbn);\r\n    if (idx < 0) {\r\n        ans.push(lbn);\r\n    } else {\r\n        ans.splice(idx, 1);\r\n    }\r\n    \r\n    if (ans.length > 3) {\r\n        alert(\'More than 3 choices\');\r\n        return;\r\n    }\r\n    \r\n    process_updated_field();\r\n    console.log(ans);\r\n}\r\nfunction process_updated_field() {\r\n    for (var i = 0; i < 3; i++) {\r\n        x = i + 1;\r\n        f = \'#data-kss2_discretion_ans_\' + x;\r\n        d = \'#data-kss2_discretion_ch_\' + x;\r\n        a = \'#kss2_discretion_ch_\' + x\r\n        if (i < ans.length) {\r\n            t = x + \") \" + ans[i];\r\n            $(f).val(ans[i]);\r\n            $(a).children(\'span\').children(\'label\').text(t);\r\n        } else {\r\n            t = x + \") Activity\";\r\n            $(f).val(\'\');\r\n            // $(d + \" option[value]\").attr(\'selected\', \'selected\');\r\n            $(d + \" option:first-child\").attr(\'selected\', \'selected\');\r\n            $(a).children(\'span\').children(\'label\').text(t);\r\n            discretion_update();\r\n        }\r\n    }\r\n    \r\n    console.log(ans);\r\n}\r\n$(document).ready(function(){\r\n<%= doc_ready.html_safe %> \r\n\r\n    for (var i = 0; i < 3; i++) {\r\n        x = i + 1;\r\n        f = \'#data-kss2_discretion_ans_\' + x;\r\n        v = $(f).val();\r\n        if (v != \'\')\r\n            ans.push(v);\r\n    }\r\n    process_updated_field();\r\n    \r\n    $(\"input[id^=\'update_kss2_discretion_recreational\']\").change(recreational_change);\r\n    $(\"input[id^=\'update_kss2_discretion_workout\']\").change(workout_change);\r\n});\r\n<%\r\n    end\r\n%>\r\n</script>',NULL,NULL,NULL,'2015-06-25 09:31:31','2015-06-25 09:31:31','',''),(1643,'sumgroup',600,1,'{\r\n	:symptom_update => {\r\n		:select => [:kss2_pain_walking, :kss2_pain_stairs],\r\n		:radio => [:kss2_ask_normal],\r\n		:total => :kss2_total_symptoms\r\n	},\r\n	:patient_satisfaction_update => {\r\n	    :select => [:kss2_satisfied_sitting, :kss2_satisfied_lying, :kss2_satis