used date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n            <script>\r\n            	$(\"#data-birth_date\").kendoDatePicker({\r\n            		value: \'\',\r\n            	});\r\n            </script>\r\n        </div>\r\n    </div>\r\n<% if false %>\r\n    <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n            <script>\r\n            	$(\"#data-date\").kendoDatePicker({\r\n            		value: \'<%= p_date %>\',\r\n            	});\r\n            </script>\r\n        </div>\r\n    </div>\r\n<% end %>\r\n    <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n        <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n            <span class=\"k-picker-wrap k-state-default\">\r\n                <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onkeypress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                    <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                </span>\r\n            </span>\r\n        </span>\r\n        <script>\r\n        $(\"#data-start\").kendoTimePicker({\r\n        	value: \'09:00\',\r\n        	interval: 10,\r\n        	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n        	change: function(event){\r\n        		var v = $(\'#data-start\').val()\r\n        		if(v.length==3){\r\n        			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n        		}\r\n        		 \r\n        	}\r\n        });\r\n        </script>\r\n	</div>\r\n	<div id=\"time_tf\" class=\" portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>TF <br/>(Checked for TF) :</label></span>\r\n        <ul class=\"checkbox\"> \r\n            <li>\r\n                <input name=\"app[time_tf]\" type=\"checkbox\" id=\"data-time_tf\" value=\"1\" />\r\n                <label for=\"data-time_tf\">TF</label>\r\n            </li>\r\n        </ul>\r\n	</div>\r\n	<div id=\"case_type\" class=\" portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\">\r\n            <label>Case Type : </label>\r\n       </span>\r\n	    <label class=\"radio\">\r\n			<input type=\"radio\" value=\"E\" id=\"optionsRadios1\" name=\"app[case_type]\" previousValue=\'false\'/>\r\n				(E) Emergency\r\n		</label>\r\n		<label class=\"radio\">\r\n			<input type=\"radio\" value=\"U\" id=\"optionsRadios2\" name=\"app[case_type]\" previousValue=\'false\'/>\r\n				(U) Urgency\r\n		</label>\r\n	</div>\r\n<div class=\"clear\"></div>\r\n<hr/>\r\n    <div id=\"or_room\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Room : </label></span>	\r\n        <!--<input type=\"text\" name=\"room\" id=\"data-room\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[or_room]\" id=\"data-or_room\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n<%\r\n    for l in l_or_room do\r\n%>\r\n                <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n            \r\n            \r\n        </div>\r\n    </div>\r\n    <div id=\"ward\" class=\"  portlet \" style=\"border:0px solid blue;width:360px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Ward : </label></span>	\r\n        <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n           \r\n                \r\n<%\r\n    for l in l_ward do\r\n%>\r\n                \r\n                \r\n                <label class=\"radio rline\">\r\n			<input type=\"radio\" value=\"<%= l[0]%>\"  name=\"app[ward]\" />\r\n				<%= l[1] %>\r\n		</label>\r\n<%\r\n    end\r\n%>\r\n            \r\n            \r\n            \r\n            \r\n        </div>\r\n    </div>\r\n<!--    <div id=\"care_unit_days\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">-->\r\n<!--        <span class=\"\"><label>Care Unit Days : : </label></span>	-->\r\n<!--        <input type=\"text\" name=\"care_unit_days\" id=\"data-care_unit_days\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n<!--    </div>-->\r\n    \r\n<!--<div class=\"clear\"></div>-->\r\n\r\n    <div id=\"position\" class=\"  portlet \" style=\"border:0px solid blue;width:105px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Position : </label></span>	\r\n        <!--<input type=\"text\" name=\"position\" id=\"data-position\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[position]\" id=\"data-position\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n<%\r\n    for l in l_position do\r\n%>\r\n                <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"post_op\" class=\"  portlet \" style=\"border:0px solid blue;width:105px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Post-op : </label></span>	\r\n        <!--<input type=\"text\" name=\"post_op\" id=\"data-post_op\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[post_op]\" id=\"data-post_op\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n<%\r\n    for l in l_post_op do\r\n%>\r\n                <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"anesth_technique\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Anesth Technique : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[anesth_technique]\" id=\"data-anesth_technique\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n                <option value=\"GA\">GA</option>\r\n                <option value=\"LA\">LA</option>\r\n                <option value=\"BB\">BB</option>\r\n                <option value=\"RA\">RA</option>\r\n                <option value=\"MAC\">MAC</option>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <!--\r\n    <div id=\"others\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Others : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[others]\" id=\"data-others\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n                <option value=\"1\">Pain Clinic</option>\r\n                <option value=\"2\">Critical care</option>\r\n                <option value=\"3\">CPR</option>\r\n                <option value=\"4\">Ventilation Care</option>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    -->\r\n<div class=\"clear\"></div>\r\n    <div id=\"surgeon\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Surgeon : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[surgeon]\" id=\"data-surgeon\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_surgeon do\r\n%>\r\n                <option value=\"<%= prov[0] %>\"><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"assist\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Assist : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[assist]\" id=\"data-assist\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_nurse_surgeon do\r\n%>\r\n                <option value=\"<%= prov[0] %>\"><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"surgeon\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Anesthesiologist : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[anesth]\" id=\"data-anesth\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_anesth do\r\n%>\r\n                <option value=\"<%= prov[0] %>\"><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"assist\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Nurse Anesthetist 1 : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[anesth_assist]\" id=\"data-anesth_assist\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_nurse_anesth do\r\n%>\r\n                <option value=\"<%= prov[0] %>\"><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"assist_2\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Nurse Anesthetist 2 : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[anesth_assist_2]\" id=\"data-anesth_assist_2\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_nurse_anesth do\r\n%>\r\n                <option value=\"<%= prov[0] %>\"><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"diagnosis\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Diagnosis : </label></span>	\r\n        <input type=\"text\" name=\"app[diagnosis]\" id=\"data-diagnosis\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"operation\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Operation : </label></span>	\r\n        <input type=\"text\" name=\"app[operation]\" id=\"data-operation\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"instrument\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Instrument : </label></span>\r\n        <ul class=\"checkbox\"> \r\n        <% \r\n            i = 0\r\n            instr.each do |k, v| \r\n        %>\r\n            <li><input name=\"instrument\" type=\"checkbox\" id=\"update_instrument_item_<%=i%>\" value=\"<%= k.to_s %>\" /><label for=\"update_instrument_item_<%=i%>\"><%= v %></label></li>\r\n        <% \r\n                i += 1\r\n            end \r\n        %>\r\n        </ul>\r\n        <!--<textarea type=\"text\" name=\"app[instrument]\" id=\"data-instrument\" row=\"5\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\"></textarea>-->\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"instrument_other\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Instrument Other : </label></span>	\r\n        <input type=\"text\" name=\"app[instrument_other]\" id=\"data-instrument_other\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n<div class=\"clear\"></div>\r\n<%\r\n    cur_user = !@current_user.nil? ? @current_user.login : @current_user.name\r\n%>\r\n<input type=\"hidden\" name=\"app[status]\" value=\"Appointed\"/>\r\n<input type=\"hidden\" name=\"app[date]\" value=\"<%= p_date %>\"/>\r\n<input type=\"hidden\" name=\"app[instrument]\" id=\"data-instrument\" value=\"\"/>\r\n<input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= !@current_user.nil? ? @current_user.login : @current_user.name %>\"/>\r\n<input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= !@current_user.nil? ? @current_user.login : @current_user.name %>\"/>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<div class=\"row-fluid\">\r\n<%= hidden_field_tag :return, params[:return] %>\r\n<%= f.submit \'Add\', :class=>\'btn btn-success\' %>\r\n<%= link_to \'Cancel\', !params[:return].nil? ? params[:return] : \"../Home/index\", :class=>\'btn\' %>\r\n</div>\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Select Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n        <div id=\'previous_content\'></div> \r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<script type=\"text/javascript\" charset=\"utf-8\">\r\n    function do_previous(pid) {\r\n        $.get( \"get_previous\", { pid: pid} )\r\n            .done(function( data ) {\r\n                $(\'#previous_content\').html(data);\r\n                console.log(\"DATA : \" + data);\r\n            }\r\n        );\r\n        /*\r\n        url = \"get_previous?pid=\" + pid;\r\n        console.log(\"DO PREVIOUS : \" + url);\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + (data.prefix_name == \'นาย\'));\r\n                $(\'#previous_content\').html(data.pid);\r\n            } \r\n        });\r\n        // $(\'#previoud_content\').html();\r\n        \r\n        */\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n        \r\n        console.log(\"Patient ID : \" + pid);\r\n    }\r\n    function doClose(){\r\n        $(\'#modal\').hide();\r\n        $(\".modal-backdrop\").hide(\'fade\');\r\n    }\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n\r\n	function data_demo_update(){\r\n		\r\n		// alert(\'call F9784231518 data-demo\')\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n// 		console.log(val + \"<<<\");\r\n// 		var tree = esm_helper.get(\'medication\');\r\n// 		if(tree){\r\n// 		tree.changeValue(\'F9784231518\',t,val,text)\r\n// 		tree.updateReport();\r\n// 		}\r\n	}\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + (data.prefix_name == \'นาย\'));\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n<% if @current_role==\'developer\' %>\r\n                $(\'#patient_msg\').html(\'<a class=\"btn btn-warning\" href=\"javascript:do_previous(\' + \"\'\" + data.id + \"\'\" + \')\"> Previous Visit </a>\');\r\n<% end %>\r\n            } \r\n        });\r\n    }\r\n    function update_previous() {\r\n        \r\n    }\r\n    function update_instrument() {\r\n        var instrument = [];\r\n        $(\"input:checkbox[name=instrument]:checked\").each(function(){\r\n            instrument.push($(this).val());\r\n        });\r\n        $(\'#data-instrument\').val(instrument.join(\'|\'));\r\n        console.log(\"change : \" + $(this).val());\r\n        console.log(\"all    : \" + instrument.join(\'|\'));\r\n    }\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    $(document).ready(function(){\r\n        // hn\r\n        $(\'#data-hn\').change(update_patient);\r\n        // instrument update\r\n        f = \"input[id^=\'update_instrument\']\";\r\n        $(f).change(update_instrument);\r\n        // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n        \r\n        // radio uncheckable\r\n        $(\"input[type=\'radio\']\").click(function() {\r\n          var previousValue = $(this).attr(\'previousValue\');\r\n          var name = $(this).attr(\'name\');\r\n        //   var data = $(\'#\' + name.replace(\"update_\", \"data-\"));\r\n          \r\n          if (previousValue == \'checked\') {\r\n            $(this).removeAttr(\'checked\');\r\n            $(this).attr(\'previousValue\', false);\r\n            // data.val(\"\");\r\n          } else {\r\n            $(\"input[name=\"+name+\"]:radio\").attr(\'previousValue\', false);\r\n            $(this).attr(\'previousValue\', \'checked\');\r\n          }\r\n        });\r\n    });\r\n</script>\r\n<% end #end guest role %>',NULL,NULL,NULL,'2015-07-02 04:53:55','2015-07-02 04:53:55','create',''),(1655,'document_name',742,1,'\'appointment\'',NULL,NULL,NULL,'2015-07-02 08:14:46','2015-07-02 08:14:46',NULL,NULL),(1656,'document_name',743,1,'\'appointment\'',NULL,NULL,NULL,'2015-07-02 08:44:22','2015-07-02 08:44:22',NULL,NULL),(1657,'create',743,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2015-07-02 08:49:02','2015-07-02 08:49:02','create',''),(1658,'document_name',744,1,'\'appointment_example\'',NULL,NULL,NULL,'2015-07-02 08:54:28','2015-07-02 08:54:28',NULL,NULL),(1659,'test',745,3,'<%\r\n\r\n%>\r\n<%= this.inspect %>',NULL,NULL,NULL,'2015-07-02 09:02:20','2015-07-02 09:02:20','test',''),(1660,'test',744,3,'<%= this %>x',NULL,NULL,NULL,'2015-07-02 09:08:06','2015-07-02 09:08:06','test',''),(1661,'test',741,3,'<%= this %>',NULL,NULL,NULL,'2015-07-02 09:09:28','2015-07-02 09:09:28','test',''),(1662,'document_name',746,1,'\