pat_mod.create :module_name=>\"\\\\#{@current_project.name}#pre_anesthetic\", :module_id=>c_pre.id, :parent_id=>params[:parent_id], :patient_id=>params[:patient_id], :ref_number=>\'000000\', :date=>Time.now.strftime(\'%d/%m/%Y\'), :time=>Time.now.strftime(\'%H:%M\')\r\n					end\r\n					\r\n					if pm\r\n					\r\n					if  params[:schema_patient_module]\r\n					   pm.update_attributes params[:schema_patient_module]\r\n					end\r\n					\r\n					if params[:provider_id]\r\n					  ap.update_attributes :provider=>params[:provider_id]\r\n					   ap = emr_models[:appointment].find(params[:id])\r\n					end\r\n					\r\n					# find provider\r\n					provider = emr_models[:provider].find(ap.provider.to_s)\r\n					\r\n					# find patient\r\n					patient = patient_model.find(pm.patient_id)\r\n					\r\n					params[:patient]=patient\r\n					params[:patient_module]=pm\r\n					\r\n					# s = Service.get(\'ehr.emr.EmrHelper\')\r\n					#    obj = s.load context\r\n					\r\n					providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n					\r\n					%>\r\n				<%\r\n					if \'\' == \'developer\'\r\n					    all_pm = patient_module_model.all\r\n					%>\r\n				<pre>\r\n    <%= pm.to_json.html_safe %>\r\n    <% all_pm.each_with_index do |i, idx| %>\r\n    <%= idx %> : <%= i.to_json.html_safe %>\r\n    <% end %>\r\n</pre>\r\n				<%\r\n					end\r\n					%>\r\n				<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n				<div style=\"border:0px solid\">\r\n					<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n						<%# render :inline=>obj.show_patient %>\r\n						<div id=\"patient\">\r\n							...\r\n						</div>\r\n						<script>\r\n							<%\r\n								url = \'../../www/Patient/search_result?\'\r\n								url += \'&id=\'+patient.id.to_s\r\n								%>      \r\n							        $.ajax({\r\n							    	  url: \'<%=url.html_safe%>\',\r\n									 success: function(data){\r\n							          $(\'#patient\').html(data);  \r\n									  }\r\n									});\r\n						</script>\r\n						<br/>\r\n						<%\r\n							previous = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\n							history = []\r\n							x = previous[0..7]\r\n							last = []\r\n							last = x.compact if x\r\n							history = []\r\n							y = previous[8..-1]\r\n							history = y.compact if y and  previous.size>5\r\n							                                     \r\n							current = time_ago_in_words(ap.date)\r\n							current_date = ap.date.strftime(\"%d-%m-%y\")\r\n							current = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n							\r\n							%>\r\n						<div class=\"clear\"></div>\r\n						<div class=\"tabbable\">\r\n							<ul class=\"nav nav-tabs\">\r\n								<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n								<%\r\n									for i in last\r\n									%>\r\n								<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date) if i.date%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n								<% end %>\r\n								<% if history.size>5 %>\r\n								<li class=\"dropdown\">\r\n									<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n									<ul class=\"dropdown-menu\">\r\n										<% for j in history %>\r\n										<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n										<% end %>\r\n										<li class=\"divider\"></li>\r\n									</ul>\r\n								</li>\r\n								<% end %>\r\n							</ul>\r\n							<div class=\"tab-content\">\r\n								<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n									<h4><%= @current_project.title %> Records</h4>\r\n									<hr/>\r\n									<table class=\"table table-striped table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th></th>\r\n												<th>Forms</th>\r\n												<th>Records</th>\r\n												<th></th>\r\n											</tr>\r\n										</thead>\r\n										<%\r\n											groups = this.config\r\n											if true\r\n											for g in groups \r\n											   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n											%>\r\n										<tr>\r\n											<td colspan=\"4\"><%=g[:name]%></td>\r\n										</tr>\r\n										<% \r\n											# check if pre_anesth created ?\r\n											f_pre = false\r\n											m_par = pm.id.to_s\r\n											\r\n											services.each_with_index do |s,index|\r\n											module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n											records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n											%>\r\n										<tr>\r\n											<td><%= index+1 %>. </td>\r\n											<td> <%= s.title %>\r\n												<%\r\n													if \'\' == \'developer\'\r\n													%>\r\n												<br/>\r\n												patient_id : <%= patient.id %><br/>\r\n												parent_id  : <%= pm.id %>\r\n												<%\r\n													end\r\n													%>\r\n											</td>\r\n											<td align=\"center\">\r\n												<% for i in records %>\r\n												<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n												<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n												<% end %>\r\n											</td>\r\n											<td>\r\n												<%  \r\n													if records.size==0 \r\n													%>\r\n												<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n												<% \r\n													else \r\n													    if s.title.to_s.downcase.include? \'pre\'\r\n													        f_pre = true\r\n													    end\r\n													%>\r\n												<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n												<% \r\n													end \r\n													%>\r\n												<% \r\n													locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n													if locker\r\n													text = \'\'\r\n													case locker.status\r\n													when \'create\'\r\n													    text=\'Creating..\'\r\n													when \'edit\'\r\n													    text=\'Editing..\'\r\n													end\r\n													user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n													\r\n													\r\n													%>\r\n												<%\r\n													user_name = user.login.split(\"@\")[0]\r\n													user_name =  solution_user.name  if solution_user\r\n													\r\n													text += \" by \" + user_name if user_name\r\n													#   text += locker.session\r\n													%>\r\n												<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n												<% end %>\r\n											</td>\r\n											<% end %>\r\n										</tr>\r\n										<% end %>\r\n										<% end %>\r\n									</table>\r\n								</div>\r\n								<% for i in previous \r\n									pm = i\r\n									%>\r\n								<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n									<h4><%= @current_project.title %> Recrods</h4>\r\n									<hr/>\r\n									<table class=\"table table-striped table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th></th>\r\n												<th>Forms</th>\r\n												<th>Records</th>\r\n												<th></th>\r\n											</tr>\r\n										</thead>\r\n										<%\r\n											groups = this.config\r\n											if true\r\n											for g in groups \r\n											   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n											%>\r\n										<tr>\r\n											<td colspan=\"4\"><%=g[:name]%></td>\r\n										</tr>\r\n										<% services.each_with_index do |s,index|\r\n											module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n											records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n											%>\r\n										<tr>\r\n											<td><%= index+1 %>. </td>\r\n											<td> <%= s.title %></td>\r\n											<td align=\"center\">\r\n												<% \r\n													for i in records \r\n													%>\r\n												<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n												<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n												<% \r\n													end \r\n													%>\r\n											</td>\r\n											<td>\r\n												<%  \r\n													if records.size==0 \r\n													%>\r\n												<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n												<% \r\n													else \r\n													    if !f_pre and s.title.to_s.downcase.include? \'pre\'\r\n													%>\r\n												<%= link_to \'Copy\', \"\\\\#{request.fullpath}&val=\\\\#{i[:module_id]}&parent_id=\\\\#{m_par}&patient_id=\\\\#{patient.id}\".html_safe, :class=>\'btn btn-warning\' %>\r\n												<%\r\n													end\r\n													%>\r\n												<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n												<% \r\n													end \r\n													%>\r\n												<br/>\r\n											</td>\r\n											<% end %>\r\n										</tr>\r\n										<% end %>\r\n										<% end %>\r\n									</table>\r\n								</div>\r\n								<% end %>\r\n							</div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n				<% else %>\r\n				Data missing\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<script>\r\n	$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>',NULL,NULL,NULL,'2015-07-07 08:43:03','2015-07-07 08:43:03','patient_record',''),(1670,'document_name',751,1,'\'patient_innovian\'',NULL,NULL,NULL,'2015-07-08 03:46:02','2015-07-08 03:46:02',NULL,NULL),(1671,'check_up',481,3,'<%\r\n    rm = false\r\n    if params[:act] == \'destroy\'\r\n        rm = true\r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    m_ehr = ehr.load_model\r\n    m_model = get_model\r\n    \r\n    m_pm = m_ehr[:patient_module]\r\n    m_patient = m_ehr[:patient]\r\n    \r\n    # check patient\r\n    pm = m_pm.first\r\n    all_pm_app = m_pm.where(:module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    all_patient = m_patient.all.collect{|i| i.id.to_s}\r\n    app_p = []\r\n    for a in all_pm_app do\r\n        app_p.push(a[:patient_id].to_s)\r\n    end\r\n    del_patient = (all_patient.uniq - app_p.uniq)\r\n    \r\n    z = []\r\n    if rm\r\n        m_patient.where(:id=>del_patient).destroy_all\r\n        # z = m_patient.where(:id=>del_patient).all\r\n    end\r\n    # end patient\r\n    \r\n    # service\r\n    tmp = {}\r\n    es = []\r\n    service = [:aki, :case_record, :summary_form]\r\n    \r\n    for a in all_pm_app do\r\n        # pm_x = m_pm.where(:parent_id=>a.id).all\r\n        # for b in pm_x do\r\n        #     m_name = b[:module_name].split(\'#\')[1].strip\r\n        #     if !tmp.has_key?(m_name)\r\n        #         tmp[m_name] = []\r\n        #     end\r\n        #     tmp[m_name].push(b[:module_id].to_s)\r\n        # end\r\n        # tmp[a.id] = pm_x.count\r\n        \r\n        for s in service do\r\n            m_name = s.to_s\r\n            pp = m_pm.where(:parent_id=>a.id, :module_name=>\"\\\\#{@current_project.name}#\\\\#{m_name}\").all\r\n            if !tmp.has_key?(m_name)\r\n                tmp[m_name] = []\r\n            end\r\n            ll = pp.collect{|i| i[:module_id].to_s}\r\n            tmp[m_name] += ll\r\n            \r\n            if s.to_s == \'summary_form\'\r\n                if ll.count > 1 \r\n                    es.push(a.id)\r\n                end\r\n            end\r\n        end\r\n    end\r\n    \r\n    x = []\r\n    tss = {}\r\n    txx = {}\r\n    tmp.each {|k,v| \r\n        sv = k\r\n        md = m_model[sv.to_sym].all\r\n        ss = md.collect{|i| i.id.to_s}\r\n        del_service = ss - tmp[k]\r\n        \r\n        tss[k] = {}\r\n        tss[k][:all] = ss.count\r\n        tss[k][:real] = tmp[k].count\r\n        tss[k][:junk] = del_service.count\r\n        \r\n        if rm\r\n            # x.push( del_service )\r\n            for d in del_service do\r\n                r = m_model[k.to_sym].find(d)\r\n                if r\r\n                    r.destroy\r\n                end\r\n                \r\n                m_name = \"\\\\#{@current_project.name}#\\\\#{k}\"\r\n                r = m_pm.where(:module_name=>m_name,:module_id=>d).first\r\n                if r\r\n                    r.destroy\r\n                end\r\n                x.push({:service=>k,:id=>d,:module_name=>m_name,:data=>r})\r\n            end\r\n            # r = m_model[k.to_sym].where(\'id\'=>del_patient).all\r\n            # x = m_pm.where(\'module_id\'=>del_patient).all\r\n            # x.push(r)\r\n        end\r\n    }\r\n    # end\r\n    \r\n    \r\n    \r\n    res = {}\r\n    res[:summary] = {:recently_patient=>app_p.count,:completed_patient=>tss[\'summary_form\'][:all]}\r\n    res[:patient] = {:all_patient=>all_patient.count, :real_patient=>app_p.uniq.count, :junk_patient=>(all_patient.uniq - app_p.uniq).count}\r\n    res[:service] = tss\r\n    res[:error_record] = es.collect{|i|\r\n        pm = m_pm.find(i)\r\n        pp = m_patient.find(pm[:patient_id])\r\n        {:hn=>pp[:patient_number], :app_id=>pm[:module_id]}\r\n    }\r\n    res[:destroy] = rm\r\n    # res[:x] = x\r\n    # res[:z] = z.collect{|i| i.id}\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-07-09 07:27:41','2015-07-09 07:27:41','check_up','*'),(1672,'clean_patient',481,3,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    m_ehr = ehr.load_model\r\n    m_model = get_model\r\n    \r\n    m_pm = m_ehr[:patient_module]\r\n    m_patient = m_ehr[:patient]\r\n    \r\n    all_pm = m_pm.all.collect{|i| i.id}\r\n    all_patient = m_patient.all.collect{|i| i.id.to_s}\r\n    \r\n    pm = m_pm.first\r\n    all_pm_app = m_pm.where(:module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    \r\n    pm_app = m_pm.where(:parent_id=>all_pm_app.first.id)\r\n    x = all_pm_app.first\r\n    x[:child] = pm_app\r\n    app_p = []\r\n    for a in all_pm_app do\r\n        app_p.push(a[:patient_id].to_s)\r\n    end\r\n    \r\n    del_patient = (all_patient.uniq - app_p.uniq)\r\n    \r\n    res = {}\r\n    res[:patient_size] = all_patient.uniq.count\r\n    res[:patient_app] = app_p.uniq.count\r\n    res[:unuse_patient] = del_patient.count\r\n    \r\n    m_patient.where(:id=>del_patient).destroy_all\r\n    \r\n    res[:message] = \'Deleted\'\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-07-10 04:21:21','2015-07-10 04:21:21','clean_patient',''),(1673,'clean_record',481,3,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    m_ehr = ehr.load_model\r\n    m_model = get_model\r\n    \r\n    m_pm = m_ehr[:patient_module]\r\n    m_patient = m_ehr[:patient]\r\n    \r\n    all_pm = m_pm.all.collect{|i| i.id}\r\n    all_patient = m_patient.all.collect{|i| i.id.to_s}\r\n    \r\n    pm = m_pm.first\r\n    all_pm_app = m_pm.where(:module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    \r\n    # service\r\n    tmp = {}\r\n    service = [:aki, :case_record, :summary_form]\r\n    \r\n    for a in all_pm_app do\r\n        pm_x = m_pm.where(:parent_id=>a.id).all\r\n        # for b in pm_x do\r\n        #     m_name = b[:module_name].split(\'#\')[1].strip\r\n        #     if !tmp.has_key?(m_name)\r\n        #         tmp[m_name] = []\r\n        #     end\r\n        #     tmp[m_name].push(b[:module_id].to_s)\r\n        # end\r\n        # tmp[a.id] = pm_x.count\r\n        \r\n        for s in service do\r\n            rs = m_pm.where(:parent_id=>a.id, :module_name=>\"\\\\#{@current_project.name}#\\\\#{s.to_s}\")\r\n            tmp[s.to_s] = rs.collect{|i| i[:module_id].to_s}\r\n        end\r\n    end\r\n    \r\n    txx = {}\r\n    # tmp.each {|k,v| \r\n    #     sv = k\r\n    #     md = m_model[sv.to_sym].all\r\n    #     txx[sv] = md.collect{|i| i.id.to_s}\r\n    # }\r\n    for s in service do\r\n        md = m_model[s].all\r\n        txx[s] = md.collect{|i| i.id.to_s}\r\n    end\r\n    \r\n    tyy = {}\r\n    ccc = {}\r\n    ccc[:sevice] = {}\r\n    ccc[:patient_module] = {}\r\n    for k in service do\r\n        ttt = txx[k] - tmp[k]\r\n        tyy[k] = m_pm.where(:module_id => ttt).count\r\n        ccc[:service][k] = tmp[k].count\r\n        ccc[:patient_module][k] = txx[k].count\r\n        # destroy\r\n        # m_pm.where(:module_id=>ttt).destroy_all\r\n        # m_model[k.to_sym].where(:id=>ttt).destroy_all\r\n    end\r\n    \r\n    # end service\r\n    \r\n    res = {}\r\n    res[:all_pm_app] = all_pm_app.count\r\n    res[:service] = ccc\r\n    res[:tyy] = tyy\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-07-10 05:50:27','2015-07-10 05:50:27','clean_record','*'),(1674,'index',752,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2015-07-14 02:05:12','2015-07-14 02:05:12',NULL,NULL),(1675,'layout',752,4,'<%=default_layout%>',NULL,NULL,NULL,'2015-07-14 02:05:12','2015-07-14 02:05:12',NULL,NULL),(1676,'document_name',753,1,'\'colposcopy\'',NULL,NULL,NULL,'2015-07-14 02:09:54','2015-07-14 02:09:54',NULL,NULL),(1677,'form',753,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<style>\r\n    .document label { font-size:14px;}\r\n</style>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n\r\n<script>\r\n\r\n    function refresh_form(){\r\n colour = parseInt($(\"#data-colour\").val());\r\n lesion_margin_and_surface_configuration = parseInt($(\"#data-lesion_margin_and_surface_configuration\").val());\r\n vessels = parseInt($(\"#data-vessels\").val());\r\n iodine_staining = parseInt($(\"#data-iodine_staining\").val());\r\n\r\n \r\n $(\"#data-rci_score\").val(colour+lesion_margin_and_surface_configuration+vessels+iodine_staining);\r\n //alert(rs)\r\n}\r\n\r\n$(\"#data-colour\").change(function(){\r\nrefresh_form();\r\n});\r\n$(\"#data-lesion_margin_and_surface_configuration\").change(function(){\r\nrefresh_form();\r\n});\r\n$(\"#data-vessels\").change(function(){\r\nrefresh_form();\r\n});\r\n$(\"#data-iodine_staining\").change(function(){\r\nrefresh_form();\r\n});\r\n</script>',NULL,NULL,NULL,'2015-07-14 03:41:58','2015-07-14 03:41:58','form',''),(1678,'print',753,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n\r\n\r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    med_id = pm.module_id\r\n    record = models[:colposcopy].find(med_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n 