              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:250px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:250px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n        display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'/esm/cusys/gyn_onco/login-logo3.png\' width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<center><h3>Colposcopy</h3></center>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid;\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n <!-- show patient -->\r\n<div id=\"patientx\">\r\n  <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <value><%= patient.first_name %> <%= patient.last_name %></value> (Age :&nbsp;<value><%= year%> Year <%=month%> Month <%= day%> Day </value>) </p></h3>\r\n\r\n\r\n<hr>\r\n\r\n\r\n<div id=\"para\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 5px ;float:left;\">\r\n	<label>PARA : </label><v><%=render_value \'para1\'%> </v> - <v><%=render_value \'para2\'%> </v> - <v><%=render_value \'para3\'%> </v> - <v><%=render_value \'para4\'%> </v>\r\n\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"lmp\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 5px ;float:left;\">\r\n<span class=\"\"><label>LMP : </label></span>	\r\n<v><%=render_value \'lmp\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"menopause\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 5px ;float:left;\r\nwidth:180px;\">\r\n	\r\n<span class=\"\"><label>Menopause : </label></span>	\r\n<v><%=render_value \'menopause\'%></v>\r\n</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"contraception\" class=\"  portlet \" style=\"border:0px solid blue;width:250px;margin: 5px ;float:left;\">\r\n<span class=\"\"><label>Contraception : </label></span>	\r\n<v><%=render_value \'contraception\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n	<div id=\"457-F2981386196\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"partners\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 5px ;float:left;\">\r\n<span class=\"\"><label>Partners : </label></span>	\r\n<v><%=render_value \'partners\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"first_si\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 5px ;float:left;\">\r\n<span class=\"\"><label>first SI : </label></span>	\r\n<v><%=render_value \'first_si\'%></v><label> yr</label>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"pap\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 5px ;float:left;\">\r\n<span class=\"\"><label>Pap : </label></span>	\r\n<v><%=render_value \'pap\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"hpv_positive\" class=\"  portlet \" style=\"border:0px solid blue;width:260px;margin: 5px ;float:left;\">\r\n<span class=\"\"><label>HIV positive(specifed) : </label></span>	\r\n<v><%=render_value \'hpv_positive\'%></v>\r\n</div>\r\n\r\n<div id=\"457-F4098855784\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background:#DFF0D8;\r\n-moz-border-radius: 5px;\r\nborder-radius: 5px;\r\npadding:2px;\">\r\n		<b>General assessment</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'general_assessment_type\']!=\"\" %>\r\n<div id=\"general_assessment_type\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>General assessment : </label></span>	\r\n<v><%=render_value \'general_assessment_type\'%></v>\r\n\r\n\r\n\r\n</div>\r\n<% end%>\r\n	\r\n\r\n\r\n\r\n<% if record[\'squamocolumnar_junction\']!=\"\" %>\r\n<div id=\"squamocolumnar_junction\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px;min-height:30px;\">\r\n<span class=\"\"><label>Squamocolumnar junction(visbility) : </label></span>	\r\n<v><%=render_value \'squamocolumnar_juntion\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n<% if record[\'trasformation_zone\']!=\"\" %>\r\n<div id=\"trasformation_zone\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px;min-height:30px;\">\r\n<span class=\"\"><label>Trasformation zone(TZ) : </label></span>	\r\n<v><%=render_value \'trnsformation_zone\'%></v>\r\n</div>\r\n<% end%>\r\n	\r\n\r\n\r\n	<div id=\"457-F4003158794\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background:#DFF0D8;\r\n-moz-border-radius: 5px;\r\nborder-radius: 5px;\r\npadding:2px;\">\r\n		<b>Normal colpscopic findings</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n	<div id=\"457-F9882068380\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'squamous_epithelium\']!=\"\" %>\r\n<div id=\"squamous_epithelium\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>Squamous epithelium : </label></span>	\r\n<v><%=render_value \'squamous_epithelium\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'columnar_epithelium\']!=\"\" %>\r\n<div id=\"columnar_epithelium\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Columnar epithelium : </label></span>	\r\n<v><%=render_value \'columnar_epithelium\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n<% if record[\'metaplastic_squamous_epithelium\']!=\"\" %>\r\n<div id=\"metaplastic_squamous_epithelium\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:350px;min-height:30px;\">\r\n<span class=\"\"><label>Metaplastic squamous epithelium : </label></span>	<br />\r\n<v><%=render_value \'metaplastic_squamous_epithelium\'%></v>\r\n</div>\r\n<% end%>\r\n	\r\n\r\n\r\n	<div id=\"457-F6560388874\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background:#DFF0D8;\r\n-moz-border-radius: 5px;\r\nborder-radius: 5px;\r\npadding:2px;\">\r\n		<b>Abnormal colposcopic findings</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'abnormal_colpo_yn\']!=\"\" %>\r\n<div id=\"abnormal_colpo_yn\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>: </label></span>	\r\n	<v><%=render_value \'abnormal_colpo_yn\'%></v>\r\n\r\n</div>\r\n<% end%>\r\n	\r\n\r\n\r\n\r\n\r\n\r\n\r\n<% if record[\'location_of_the_lesion\']!=\"\" %>\r\n<div id=\"location_of_the_lesion\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n<span class=\"\"><label>Location of the lesion: </label></span>	\r\n<v><%=render_value \'location_of_the_lesion\'%></v> <label>o\'colock</label>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'location_tz\']!=\"\" %>\r\n<div id=\"location_tz\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n	<span class=\"\"><label> </label></span>	\r\n<v><%=render_value \'location_tz\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'size_of_lesion\']!=\"\" %>\r\n<div id=\"size_of_lesion\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n<span class=\"\"><label>Size of lesion: </label></span>	\r\n<v><%=render_value \'size_of_lesion\'%></v> <label>quadrants</label>\r\n\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'percent_of_cervix\']!=\"\" %>\r\n<div id=\"percent_of_cervix\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n\r\n<label>(</label><v><%=render_value \'percent_of_cervix\'%></v><label> % of cervix)</label>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n	<div id=\"457-F4773486557\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n\r\n<% if record[\'grade_1_type\']!=\"\" %>\r\n<div id=\"grade_1_type\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:680px;min-height:30px;\"