\n\r\n\r\n\r\n<% if record[\'additional_signs\']!=\"\" %>\r\n<div id=\"additional_signs\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;min-height:30px;\">\r\n<span class=\"\"><label>Additional signs : </label></span>	\r\n<v><%=render_value \'additional_signs\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'neoplasm\']!=\"\" %>\r\n<div id=\"neoplasm\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>neoplasm: </label></span>	\r\n<v><%=render_value \'neoplasm\'%></v> <label>cm.</label>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n	<div id=\"457-F8664851417\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background:#DFF0D8;\r\n-moz-border-radius: 5px;\r\nborder-radius: 5px;\r\npadding:2px;\">\r\n		<b>Miscellaneous findings</b>\r\n		\r\n	</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'miscellaneous_yn\']!=\"\" %>\r\n<div id=\"miscellaneous_yn\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>: </label></span>	\r\n<v><%=render_value \'miscellaneous_yn\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if record[\'miscellaneous_type\']!=\"\" %>\r\n<div id=\"miscellaneous_type\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:680px;min-height:30px;\">\r\n<span class=\"\"><label>Miscellaneous type : </label></span>	\r\n\r\n\r\n	<v><%=render_value \'miscellaneous_type\'%></v>\r\n\r\n</div>\r\n\r\n<% end%>\r\n\r\n\r\n<% if record[\'colposcopic_impression\']!=\"\" %>\r\n<div id=\"colposcopic_impression\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n<span class=\"\"><label>Colposcopic impression