>\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%3==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2015-07-14 05:05:04','2015-07-14 05:05:04','print',''),(1679,'config',717,1,'[\r\n    {:name=>\'Patient Information\',:open=>true,:actions=>[\r\n        {:name=>\'Patient\',:service=>\'patient_innovian\',:link=>\'../PatientInnovian/index\',:remote=>false}\r\n    ]},\r\n    {:name=>\'Anesthetic Records\',:open=>true,:actions=>[\r\n        {:name=>\'Pre Anesthetic\',:service=>\'pre_anesthetic\',:link=>\'../PreAnesthetic/index\',:remote=>false},\r\n        {:name=>\'Post Anesthetic\',:service=>\'post_anesthetic\',:link=>\'../PostAnesthetic/index\',:remote=>false},\r\n    ]}\r\n]\r\n',NULL,NULL,NULL,'2015-07-14 07:30:48','2015-07-14 07:30:48','config',''),(1680,'create',714,2,'<% if @current_role==\'guest\' %>\r\n<script>alert(\"Permission not allowed\");window.location = \"../Home/index\";</script>\r\n<% else %>\r\n<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n		locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n		if locker \r\n			if locker.session!= session[:user].to_s\r\n%>\r\n<script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n<%\r\n			end\r\n		elsif session[:user] and session[:user]!=\'\' \r\n    \r\n			locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n		end\r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				<h3>New <%=this.form_name.to_s.humanize%></h3>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n				<div style=\"border:0px solid\">\r\n					<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n	model = get_model(this.table_name)\r\n	if request.post? \r\n		locker.destroy if locker\r\n		\r\n		tmp = @module_model.where(:parent_id=>params[:parent_id],:module_name=>@module_name).all\r\n		if tmp.count != 0\r\n%>\r\n<script>\r\n    alert(\'Dupplicate Record Found\');\r\n    window.location = \"<%=return_url%>\";\r\n</script>\r\n<%\r\n		else\r\n    \r\n		doc = get_document this.document_name\r\n		record = doc.record_create(model,params)\r\n		m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n		flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n</script>\r\n<%\r\n        end\r\n	else  \r\n		if params[:data]\r\n			record = model.new params[:data] \r\n		else\r\n			record = model.new \r\n		end\r\n		\r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n					<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n		fid = 0\r\n		name = \'patient_id\'\r\n		value = params[:patient_id]\r\n		value = params[:id] if params[:id]\r\n		ref_number = @next_id\r\n		ref_number = params[:ref_number] if params[:ref_number]\r\n%>\r\n					<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n						<div class=\"modal-header\">\r\n\r\n							<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n							<h3>Select Patient</h3>\r\n						</div>\r\n						<div class=\"modal-body\">\r\n							<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n								<table id=\"search-panel\" style=\"width:100%\" >\r\n									<tr><td align=\'center\' style=\"border:0px solid\">\r\n										Patient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n										<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n										<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n								</tr></table>\r\n							</div>\r\n							<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n								<br/>\r\n								Loading..\r\n							</div>\r\n						</div>\r\n					</div>\r\n					<div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n						Ref : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n						<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\n						Patient : <a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n						<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n						Date : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\n						Time : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n					</div>\r\n					<div id=\'patient\'></div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({\r\n		value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n		interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\n	function doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n			url: url,\r\n			success: function(data){\r\n				$(\'#search-result\').html(data);  \r\n			}\r\n		});    \r\n	}\r\n	function doClose(){\r\n		$(\'#SelectPatient\').hide();\r\n		$(\".modal-backdrop\").hide(\'fade\');\r\n	}\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n		url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n		url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n			url: url,\r\n			success: function(data){\r\n				$(\'#patient\').html(data);  \r\n				$(\'#SelectPatient\').hide();\r\n				$(\".modal-backdrop\").hide(\'fade\');\r\n			}\r\n		});\r\n	}\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n		if(event.keyCode == 13) {\r\n			doSearch();\r\n			event.preventDefault();\r\n			return false;\r\n		} else {\r\n			$(\'#search-result\').html(\'Loading..\')\r\n		}\r\n	});\r\n  \r\n<% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n<% else %>\r\n    $(\'#SelectPatient\').modal({\r\n        show: true, \r\n        backdrop: \'static\',\r\n        keyboard: true\r\n    })          \r\n<% end %>\r\n\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n					<p>\r\n<%= this.form.html_safe %>\r\n					</p>\r\n					<br/>\r\n<%= f.submit \"Save\".html_safe,:class=>\'btn btn-success btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\", :class=>\'btn btn-small\', :confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n<% end %>\r\n				</div>\r\n			</div>\r\n\r\n		</div>\r\n	</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n	var validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n	$(\"#record-submit\").click(function() {\r\n		if (!validator.validate()||$(\'#0\').val()==\"\") {\r\n			alert(\'Please fill all information\');\r\n			if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\n				return false;\r\n		} else {\r\n			return true;\r\n			if(confirm(\'Are you sure?\')==true){\r\n				return true;\r\n			}\r\n			return false;\r\n		}\r\n	});\r\n</script>   \r\n<% if @current_role == \'developer\' %>\r\n<pre>\r\n    <%= this.table_name %>\r\n</pre>\r\n<% end %>\r\n<% end #end guest role %>',NULL,NULL,NULL,'2015-07-14 08:01:01','2015-07-14 08:01:01','create',''),(1681,'print_old',711,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    # age\r\n    today = Date.today\r\n    d = Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day)\r\n    age = d.year - r_pat[:birth_date].year - (d > today ? 1 : 0)\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_position = {}\r\n    map_or_room = {}\r\n    map_post_op = {}\r\n    map_ward = {}\r\n    \r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:position].all do\r\n        map_position[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:or_room].all do\r\n        map_or_room[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:post_op_ward].all do\r\n        map_post_op[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:ward].all do\r\n        map_ward[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    # query patient_innovian\r\n    r_inn = {}\r\n    m_inn = {}\r\n   \r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        res[:patient_innovian] = r_inn\r\n        res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:100px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<style>\r\nl {\r\n	font-size: 80%;\r\n	font-style: italic;\r\n	margin: 5px;\r\n}\r\nv {\r\n	color: blue;\r\n}\r\ntd {\r\n	// padding: 5px;\r\n}\r\n@media print {\r\n    body {\r\n        -webkit-print-color-adjust: exact;\r\n    }\r\n}\r\ninput{\r\n   text-align:center;\r\n}\r\n</style>\r\n\r\n                        <div style=\"width:960px;margin-left:auto; margin-right:auto\">\r\n                            <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\">\r\n                              <tr>\r\n                               \r\n                                <td colspan=\"3\" align=\"center\"><b style=\"font-size:20px\">Postanesthetic evalution record</b></td>\r\n                                <td rowspan=\"2\" align=\"center\"><img src=\"http://pni.go.th/pnigoth/wp-content/uploads//2009/05/LogoPrasatNew_02-300x212.jpg\" width=\"150px\"/></td>\r\n                              </tr>\r\n                              <tr>\r\n                                <td><l>Patient</l>\r\n                                    <br/>\r\n                                    <v><font size=\"5\"><%= r_pat[:first_name] %>, <%= r_pat[:last_name] %></font> (<%= age %>)</v></td>\r\n                                <td><l>Hospital No.(xxxx/xx)</l>\r\n                            		<br/>\r\n                            	&nbsp;&nbsp;<v><%= r_pat[:hn] %></v></td>\r\n                                <td><l>Hospital Admit Date</l>\r\n                            		<br/>\r\n                            	&nbsp;&nbsp;<v><%= r_inn[:hospital_admit_date] %></v></td>\r\n                              </tr>\r\n                              <tr>\r\n                                <td colspan=\"2\" >\r\n                            		<l>Diagnosis</l>\r\n                            		<br />\r\n                                &nbsp;&nbsp;<v><%= r_app[:diagnosis] %></v>\r\n                            	</td>\r\n                                <td valign=\"top\">\r\n                            		<l>Allergies</l>\r\n                            		<br/>\r\n                            	&nbsp;&nbsp;\r\n                            	</td>\r\n                              </tr>\r\n                              <tr>\r\n                                <td colspan=\"2\" valign=\"top\">\r\n                            		<l>Procedure</l>\r\n                            		<br />\r\n                                &nbsp;&nbsp;<v><%= r_app[:procedure] %></v>\r\n                            	</td>\r\n                                <td>\r\n                            		<l>Room</l>\r\n                            		<br />\r\n                                &nbsp;&nbsp;<v><%= map_or_room[r_app[:or_room]] if r_app[:or_room] %> Bed :<%= r_app[:bed] %></v>\r\n                            	</td>\r\n                           \r\n                              </tr>\r\n                            </table>\r\n                            \r\n                              <br />\r\n                             \r\n                            \r\n                            <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" style=\"float:left;margin-right:10px\">\r\n                              <tr>\r\n                                <td align=\"center\">\r\n                            	  <!-- Anesth Period -->\r\n                                  <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n                                    <tr>\r\n                                      <td style=\"padding: 2px\">&nbsp;</td>\r\n                                      <td colspan=\"3\" align=\"center\" bgcolor=\"#66CCFF\">Ansth preiod</td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                      <td  style=\"padding: 2px\" align=\"center\" bgcolor=\"#66CCFF\">Preanesth period</td>\r\n                                      <td align=\"center\">Anesth Technique</td>\r\n                                      <td colspan=\"2\" align=\"center\" bgcolor=\"#C8C8C8\">Anesthetic time</td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                      <td style=\"padding: 2px\" align=\"center\">\r\n                            			ASA Status : <v><%= render_value(\'asa_status\') %></v>\r\n                                      </td>\r\n                                      <td align=\"center\"><v><%= render_value(\'anesth_technique\') %></v></td>\r\n                                      <td align=\"center\" bgcolor=\"#C8C8C8\">Start : <v><%= render_value(\'anesthetic_time_start\') %></v></td>\r\n                                      <td align=\"center\" bgcolor=\"#C8C8C8\">End : <v><%= render_value(\'anesthetic_time_end\') %></v></td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                      <td style=\"padding: 2px\" align=\"center\" colspan=\"4\"> </td>\r\n                                    </tr>\r\n                                  </table>\r\n                            	  <!-- Post Anesth -->\r\n                                  <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n                                    <tr>\r\n                                      <td style=\"padding: 2px\" colspan=\"6\" align=\"center\" bgcolor=\"#66CCFF\">Post anesth preiod</td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                      <td align=\"center\">Recovery place</td>\r\n                                      <td colspan=\"2\" align=\"center\" bgcolor=\"#C8C8C8\">Recovery time</td>\r\n                                      <td align=\"center\">Airway</td>\r\n                                      <td align=\"center\">Ventilation</td>\r\n                                      <td align=\"center\">Oxygen devices</td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                      <td style=\"padding: 2px\" align=\"center\"><v><%= render_value(\'recovery_place\') %></v></td>\r\n                                      <td align=\"center\" bgcolor=\"#C8C8C8\">Start : <v><%= render_value(\'recovery_time_start\') %></v></td>\r\n                                      <td align=\"center\" bgcolor=\"#C8C8C8\">End : <v><%= render_value(\'recovery_time_end\') %></v></td>\r\n                                      <td align=\"center\"><v><%= render_value(\'airway\') %></v></td>\r\n                                      <td align=\"center\"><v><%= render_value(\'ventilation\') %></v></td>\r\n                                      <td align=\"center\"><v><%= render_value(\'oxygen_devices\') %></v></td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                      <td style=\"padding: 2px\" align=\"center\" colspan=\"6\"></td>\r\n                                    </tr>\r\n                                  </table>\r\n                            	</td>\r\n                              </tr>\r\n                              <!-- empty row -->\r\n                              <tr>\r\n                                <td align=\"center\">&nbsp;</td>\r\n                              </tr>\r\n                              <!-- MASS Section -->\r\n                              <tr>\r\n                                <td valign=\"top\">\r\n                            	\r\n                            	<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-style:1px solid red\">\r\n                                  <tr>\r\n                                    <td colspan=\"3\" bgcolor=\"#66CCFF\">Modified Aldrete Scoring System (MASS)</td>\r\n                                    <td style=\"padding: 2px\" align=\"center\" width=\"8%\" bgcolor=\"#66CCFF\">PREOP</td>\r\n                                    <td style=\"padding: 2px\" align=\"center\" width=\"8%\" bgcolor=\"#66CCFF\">ADMIT</td>\r\n                                    <td style=\"padding: 2px\" align=\"center\" width=\"8%\" bgcolor=\"#66CCFF\">15\'</td>\r\n                                    <td style=\"padding: 2px\" align=\"center\" width=\"8%\" bgcolor=\"#66CCFF\">30\'</td>\r\n                                    <td style=\"padding: 2px\" align=\"center\" width=\"8%\" bgcolor=\"#66CCFF\">45\'</td>\r\n                                    <td style=\"padding: 2px\" align=\"center\" width=\"8%\" bgcolor=\"#66CCFF\">60</td>\r\n                                    <td style=\"padding: 2px\" align=\"center\" width=\"8%\" bgcolor=\"#66CCFF\">WARD</td>\r\n                                  </tr>\r\n                                  <tr>\r\n                                    <td style=\"padding: 2px\" width=\"17%\" valign=\"top\" bgcolor=\"#EFEFEF\">Activity : able to move,<br />\r\n                                      voluntarily or<br />\r\n                                      on command</td>\r\n                                    <td colspan=\"2\" valign=\"top\" bgcolor=\"#EFEFEF\">\r\n                                      <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n                                        <tr>\r\n                                          <td>- Four extremities</td>\r\n                                          <td align=\"right\" valign=\"top\">2</td>\r\n                                        </tr>\r\n                                        <tr>\r\n                                          <td>- two extremities</td>\r\n                                          <td align=\"right\" valign=\"top\">1</td>\r\n                                        </tr>\r\n                                        <tr>\r\n                                          <td>- No extremities</td>\r\n                                          <td align=\"right\"valign=\"top\">0</td>\r\n                                        </tr>\r\n                                      </table>\r\n                                    </td>\r\n                                    <td align=\"center\" valign=\"center\" bgcolor=\"#EFEFEF\"><input name=\"activity_preop\" type=\"text\" id=\"data-activity_preop\" style=\"width:30px\" size=\"5\" value=\"<%= render_value(\'activity_preop\') %>\"/></td>\r\n                                    <td align=\"center\" valign=\"center\" bgcolor=\"#EFEFEF\"><input name=\"activity_admit\" type=\"text\" id=\"data-activity_admit\" style=\"width:30px\" size=\"5\" value=\"<%= render_value(\'activity_admit\') %>\" /></td>\r\n                                    <td align=\"center\" valign=\"center\" bgcolor=\"#EFEFEF\"><input name=\"activity_15\" type=\"text\" id=\"data-activity_15\" style=\"width:30px\" size=\"5\" value=\"<%= render_value(\'activity_15\') %>\"/></td>\r\n                                    <td align=\"center\" valign=\"center\" bgcolor=\"#EFEFEF\"><input name=\"activity_30\" type=\"te