                   </tr>\r\n                                          <tr>\r\n                                            <td align=\"center\"><br /><input name=\"textarea2\" type=\"text\" id=\"textarea2\" value=\"\" size=\"45\" style=\"width:200px\" />\r\n                                              <br />\r\n                                              Signature\r\n                                            </td>\r\n                                            <td align=\"center\"><br /><input name=\"textarea3\" type=\"text\" id=\"textarea3\" value=\"\" size=\"45\" style=\"width:200px\"/>\r\n                                              <br />\r\n                                              Date</td>\r\n                                            <td colspan=\"3\" align=\"center\"><br /><input name=\"textarea4\" type=\"text\" id=\"textarea4\" value=\"\" size=\"45\" style=\"width:200px\"/>\r\n                                              <br />\r\n                                              Time</td>\r\n                                          </tr>\r\n                                          </table></td>\r\n                                      </tr>\r\n                                      </table></td>\r\n                                  </tr>\r\n                                  <tr><td colspan=\"10\">&nbsp;</td></tr>\r\n                                  </table></td>\r\n                              </tr>\r\n                            \r\n                            </table>\r\n                            <div style=\"clear:both\"></div><br />\r\n                            <table width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\">\r\n                              <tr>\r\n                                <td rowspan=\"2\" valign=\"top\" width=\"25%\">\r\n                                    <l>Signature</l>\r\n                                </td>\r\n                                <td rowspan=\"2\" valign=\"top\" width=\"25%\">\r\n                                    <l>Date</l>\r\n                                </td>\r\n                                <td valign=\"top\" width=\"50%\">\r\n                                    <l>Date Printed</l>\r\n                                    <br />\r\n                                    &nbsp;&nbsp;<%= Time.now.strftime(\"%d/%m/%Y %H:%M\") %>    \r\n                                </td>\r\n                              </tr>\r\n                              <tr>\r\n                                <td valign=\"top\">\r\n                                    <l>Page</l>\r\n                                    <br/>\r\n                                    &nbsp;&nbsp;1 of 1\r\n                                </td>\r\n                              </tr>\r\n                            </table>\r\n</div>\r\n                        \r\n    <div class=\"hideprint\">\r\n        <%= link_to \'Back\', return_url %>\r\n    </div>\r\n</body>\r\n</html>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2015-07-16 09:49:02','2015-07-16 09:49:02','print_old',''),(1682,'print_old',714,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    today = Date.today\r\n    d = Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day)\r\n    age = d.year - r_pat[:birth_date].year - (d > today ? 1 : 0)\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_position = {}\r\n    map_or_room = {}\r\n    map_post_op = {}\r\n    map_ward = {}\r\n    \r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:position].all do\r\n        map_position[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:or_room].all do\r\n        map_or_room[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:post_op_ward].all do\r\n        map_post_op[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:ward].all do\r\n        map_ward[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    # query patient_innovian\r\n    r_inn = {}\r\n    m_inn = {}\r\n    d_inn = get_document(\'patient_innovian\').fields\r\n    r_pat_inn = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id], :module_name=>\"\\\\#{@current_project.name}#patient_innovian\").first \r\n    if r_pat_inn\r\n        r_inn = model[:patient_innovian].find(r_pat_inn[:module_id]) \r\n        for i in d_inn do\r\n            col = i[:column_name]\r\n            if i[:lov]\r\n                lov = i[:lov].split(/[\\r\\n]+/)\r\n                kv = {}\r\n                for l in lov do\r\n                    if l.include? \'|\'\r\n                        t = l.split(\'|\')\r\n                        k = t[0].strip\r\n                        v = t[1].strip\r\n                        kv[k] = v\r\n                    else\r\n                        kv[l.strip] = l.strip\r\n                    end\r\n                end\r\n                m_inn[col.to_sym] = kv\r\n            end\r\n        end\r\n    end\r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        res[:patient_innovian] = r_inn\r\n        res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:100px;margin:.7in .5in .5in .7in; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n    body {\r\n        -webkit-print-color-adjust: exact;\r\n    }\r\n}\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<style>\r\n    input {color:#380BBB;}\r\ninput[type=checkbox] + label {\r\n  color: #ccc;\r\n  font-style: italic;\r\n} \r\ninput[type=checkbox]:checked + label {\r\n  color: #f00;\r\n  font-style: normal;\r\n} \r\nl {\r\n	font-size: 80%;\r\n	font-style: italic;\r\n	margin: 5px;\r\n}\r\ntd {\r\n    line-height: 20px;\r\n}\r\n</style>\r\n<body>\r\n\r\n\r\n\r\n\r\n<!--<div style=\"width:960px; margin-left:auto; margin-right:auto; margin-top:0px;\">-->\r\n\r\n                        <div style=\"width:960px;margin-left:auto; margin-right:auto\">\r\n                          <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\">\r\n                            <tr>\r\n                              <td colspan=\"3\" align=\"center\"><b style=\"font-size:20px\">Preanesthetic evalution and medication record</b></td>\r\n                              <td rowspan=\"2\" align=\"center\"><img src=\"http://pni.go.th/pnigoth/wp-content/uploads//2009/05/LogoPrasatNew_02-300x212.jpg\" width=\"150px\"/></td>\r\n                            </tr>\r\n                            <tr>\r\n                              <td><l>Patient</l>\r\n                                <br/>\r\n                                &nbsp;&nbsp;<v><font size=\"5\"><%= r_pat[:prefix_name] %> <%= r_pat[:first_name] %>, <%= r_pat[:last_name] %> (<%= age %>)</font></v></td>\r\n                              <td><l>Hospital No.(xxxx/xx)</l>\r\n                                <br/>\r\n                                &nbsp;&nbsp;\r\n                                <v><%= r_pat[:hn] %></v></td>\r\n                              <td><l>Hospital Admit Date</l>\r\n                                <br/>\r\n                                &nbsp;&nbsp;\r\n                                <v><%= r_inn[:hospital_admit_date] %></v></td>\r\n                            </tr>\r\n                            <tr>\r\n                              <td colspan=\"2\" ><l>Diagnosis</l>\r\n                                <br />\r\n                                &nbsp;&nbsp;\r\n                                <v><%= r_app[:diagnosis] %></v></td>\r\n                              <td valign=\"top\"><l>Allergies</l>\r\n                                <br/>\r\n                                &nbsp;&nbsp; <strong><span style=\"color:red\"><%= this_rec[:allergy_hx] %></span></strong></td>\r\n                            </tr>\r\n                            <tr>\r\n                              <td colspan=\"2\" valign=\"top\"><l>Procedure</l>\r\n                                <br />\r\n                                &nbsp;&nbsp;\r\n                                <v><%= r_app[:operation] %></v></td>\r\n                              <td><l>Room</l>\r\n                                <br />\r\n                                &nbsp;&nbsp;\r\n                                <v><%= map_or_room[r_app[:or_room]] if r_app[:or_room] %></v></td>\r\n                            </tr>\r\n                          </table>\r\n                          <table width=\"100%\" border=\"0\" cellpadding=\"2\" cellspacing=\"2\">\r\n    <tr>\r\n      <td width=\"40%\" height=\"458\" valign=\"top\">\r\n<!-- Head Left\r\n      <center><img src=\"http://pni.go.th/pnigoth/wp-content/uploads/2009/05/LogoPrasatNew_02-300x212.jpg\" width=\"100px\" /><br />\r\n      Department of Anesthesology สป.75(3)<br />\r\n      Prasat Neurological institute<br />\r\n      Preanesthetic evaluation and medication record\r\n      <br /><br /></center>\r\n-->\r\n      <br/><center><b>History</b></center><br />\r\n      \r\n      \r\n<table width=\"100%\" border=\"0\">\r\n    <tr>\r\n        <td colspan=\"2\">\r\n            Underlying disease <v><%= this_rec[:underlying_disease] != \'\' ? \'Yes\' : \'No\' %> : <%= render_value(\'underlying_disease\') %></v>\r\n            <%= \'<br/>&nbsp;&nbsp;&nbsp;&nbsp;Heart disease : \'.html_safe if this_rec[:underlying_heart_disease] != \'\' %><v><%= this_rec[:underlying_heart_disease] %></v>\r\n            <%= \'<br/>&nbsp;&nbsp;&nbsp;&nbsp;Note : \'.html_safe if this_rec[:underlying_disease_details] != \'\' %><v><%= this_rec[:underlying_disease_other] %></v>\r\n        </td>\r\n    </tr>\r\n    <tr>\r\n        <td colspan=\"2\">\r\n            Habit : <v><%= render_value(\'habit\') %></v>\r\n        </td>\r\n    </tr>\r\n<!--\r\n  <tr>\r\n    <td width=\"28%\">Underlying disease<br />\r\n        <input type=\"checkbox\" name=\"checkbox6\" id=\"checkbox6\" <%= \"checked\" if this_rec[:underlying_disease] != \'\' %> />Yes\r\n        <input type=\"checkbox\" name=\"checkbox6\" id=\"checkbox6\" <%= \"checked\" if this_rec[:underlying_disease] == \'\' %> />No <br />\r\n    </td>\r\n    <td width=\"72%\">\r\n        <v><%= render_value(\'underlying_disease\') %></v><br/>\r\n        <%= \'Note : \' if this_rec[:underlying_disease_details] != \'\' %><v><%= this_rec[:underlying_disease_details] %></v>\r\n    </td>\r\n  <tr>\r\n    <td width=\"28%\">\r\n<br />\r\nHabit \r\n<input type=\"checkbox\" name=\"checkbox10\" id=\"checkbox10\" />\r\nSmoking</td>\r\n    <td width=\"72%\"><input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nDM\r\n  <input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nHT\r\n<input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nTB\r\n<input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nCOPD\r\n<input type=\"checkbox\" name=\"checkbox3\" id=\"checkbox3\" />\r\nAsthma<br />\r\n<input type=\"checkbox\" name=\"checkbox5\" id=\"checkbox5\" />\r\nHeart disease<br />\r\n<input type=\"checkbox\" name=\"checkbox7\" id=\"checkbox7\" />\r\nOther<br />\r\n<input type=\"checkbox\" name=\"checkbox8\" id=\"checkbox8\" />\r\nAlcohol\r\n<input type=\"checkbox\" name=\"checkbox9\" id=\"checkbox9\" />\r\nOther<input type=\"text\" name=\"textfield\" id=\"textfield\" />\r\n</td>\r\n  </tr>\r\n-->\r\n</table>\r\n  <span style=\"color:red\"><b>Allergy Hx :</b> <%= this_rec[:allergy_hx] %></span>\r\n  <br />\r\n  Family Hx : <v><%= this_rec[:family_hx] %></v>\r\n  <br />\r\n  LMP : <v><%= this_rec[:lmp] %></v>\r\n  <br/>\r\n  Suspicious preg \r\n  <input type=\"checkbox\" name=\"checkbox11\" id=\"checkbox11\" <%= \"checked\" if this_rec[:suspicious_preg] == \'1\' %>/>\r\n  Yes \r\n  <input type=\"checkbox\" name=\"checkbox12\" id=\"checkbox12\" <%= \"checked\" if this_rec[:suspicious_preg] == \'0\' %>/>\r\nNo<br /> \r\nPrevious anesthesia \r\n<input type=\"checkbox\" name=\"checkbox13\" id=\"checkbox13\" <%= \"checked\" if this_rec[:previous_anesthesia] != \'\' %>/>Yes\r\n<!--<input type=\"text\" name=\"textfield5\" id=\"textfield5\" />--><v><%= \' : \' + render_value(\'previous_anesthesia_details\') %></v>\r\n<input type=\"checkbox\" name=\"checkbox14\" id=\"checkbox14\" <%= \"checked\" if this_rec[:previous_anesthesia] == \'\' %> />No<br />\r\nComplications \r\n<input type=\"checkbox\" name=\"checkbox13\" id=\"checkbox13\" <%= \"checked\" if this_rec[:complications] == \'1\' %>/>Yes\r\n<!--<input type=\"text\" name=\"textfield5\" id=\"textfield5\" />--><v><%= \' : \' + render_value(\'complication_details\') %></v>\r\n<input type=\"checkbox\" name=\"checkbox14\" id=\"checkbox14\" <%= \"checked\" if this_rec[:complications] == \'0\' %> />No<br />\r\nCurrent Medications :\r\n&nbsp;&nbsp;&nbsp;&nbsp;<v style=\"margin-left:10px;margin-right:10px\"><%= this_rec[:current_medication_details].strip.html_safe %></v>\r\n<br/>\r\nSystemic review : <v><%= render_value(\'systemic_review\') %></v>\r\n<%= \'<br/>&nbsp;&nbsp;&nbsp;&nbsp;Current Status : \'.html_safe if this_rec[:systemic_review_current_status] != \'\' %><v><%= this_rec[:systemic_review_current_status] %></v>\r\n<%= \'<br/>&nbsp;&nbsp;&nbsp;&nbsp;Note : \'.html_safe if this_rec[:systemic_review_other] != \'\' %><v><%= this_rec[:systemic_review_other] %></v>\r\n<!--\r\nCNS\r\n<input type=\"checkbox\" name=\"checkbox16\" id=\"checkbox17\" />\r\nSeizure\r\n<input type=\"checkbox\" name=\"checkbox17\" id=\"checkbox18\" />\r\nWeakness\r\n<input type=\"checkbox\" name=\"checkbox18\" id=\"checkbox19\" />\r\n<input type=\"text\" name=\"textfield7\" id=\"textfield7\" />\r\n-->\r\n\r\n<% if false %>\r\nCurrent status : <v><%= this_rec[:current_status] %></v>\r\n<br />\r\nCVS\r\n<input type=\"checkbox\" name=\"checkbox19\" id=\"checkbox20\" />\r\nPalpitation\r\n<input type=\"checkbox\" name=\"checkbox19\" id=\"checkbox21\" />\r\nEdema\r\n<input type=\"checkbox\" name=\"checkbox19\" id=\"checkbox22\" />\r\nChest pain \r\n<input type=\"checkbox\" name=\"checkbox20\" id=\"checkbox23\" />\r\n<input type=\"text\" name=\"textfield9\" id=\"textfield9\" />\r\n<br />\r\nCurrent status\r\n<input type=\"text\" name=\"textfield10\" id=\"textfield10\" />\r\n<br />\r\nRS\r\n<input type=\"checkbox\" name=\"checkbox21\" id=\"checkbox24\" />\r\nURI\r\n<input type=\"checkbox\" name=\"checkbox21\" id=\"checkbox25\" />\r\nDyspnea\r\n<input type=\"checkbox\" name=\"checkbox21\" id=\"checkbox26\" />\r\n<input type=\"text\" name=\"textfield11\" id=\"textfield11\" />\r\n<br />\r\nCurrent status\r\n<input type=\"text\" name=\"textfield12\" id=\"textfield12\" />\r\n<br />\r\nGI\r\n<input type=\"checkbox\" name=\"checkbox22\" id=\"checkbox27\" />\r\nJaundice\r\n<input type=\"checkbox\" name=\"checkbox22\" id=\"checkbox29\" />\r\n<input type=\"text\" name=\"textfield13\" id=\"textfield13\" />\r\n<br />\r\nCurrent status\r\n<input type=\"text\" name=\"textfield13\" id=\"textfield14\" />\r\n<br /> \r\nGU\r\n<input type=\"checkbox\" name=\"checkbox23\" id=\"checkbox28\" />\r\nRenal failure\r\n<input type=\"checkbox\" name=\"checkbox23\" id=\"checkbox30\" />\r\n<input type=\"text\" name=\"textfield14\" id=\"textfield15\" />\r\n<br />\r\nCurrent status\r\n<input type=\"text\" name=\"textfield14\" id=\"textfield16\" />\r\n<br />\r\nCoag\r\n<input type=\"checkbox\" name=\"checkbox24\" id=\"checkbox31\" /> \r\nBleeding tendency <br/>\r\nCurrent status\r\n<input type=\"text\" name=\"textfield15\" id=\"textfield17\" />\r\n<% end %>\r\n<br />\r\nHistory form : <v><%= render_value(\'history_from\') %></v>\r\n<br/>\r\n\r\n<br /><center><strong>Physical Examination</strong></center><br />\r\nWt\r\n<input name=\"textfield16\" type=\"text\" id=\"textfield18\" size=\"5\" value=\"<%= this_rec[:wt] %>\"/>\r\nHt\r\n<input name=\"textfield17\" type=\"text\" id=\"textfield19\" size=\"5\" value=\"<%= this_rec[:ht] %>\"/>\r\nBMI\r\n<input name=\"textfield18\" type=\"text\" id=\"textfield20\" size=\"5\" value=\"<%= this_rec[:bmi] %>\"/>\r\nGCS\r\n<input name=\"textfield19\" type=\"text\" id=\"textfield21\" size=\"5\" value=\"<%= this_rec[:gcs] %>\" />\r\n<br />\r\nBP\r\n<input name=\"textfield20\" type=\"text\" id=\"textfield22\" size=\"5\" value=\"<%= this_rec[:sbp] + \'/\' + this_rec[:dbp] %>\"/>\r\nHR\r\n<input name=\"textfield21\" type=\"text\" id=\"textfield23\" size=\"5\" value=\"<%= this_rec[:hr] %>\"/>\r\nPR\r\n<input name=\"textfield22\" type=\"text\" id=\"textfield24\" size=\"5\" value=\"<%= this_rec[:pr] %>\"/>\r\nT\r\n<input name=\"textfield23\" type=\"text\" id=\"textfield25\" size=\"5\" value=\"<%= this_rec[:t] %>\"/>\r\n<br />\r\nPsychological status : <v><%= render_value(\'psychological_status\') %></v>\r\n<br />\r\n<table width=\"100%\" border=\"0\">\r\n  <tr>\r\n    <td valign=\"top\">Airway</td>\r\n    <td valign=\"top\">Mallampati grade : </td>\r\n    <td valign=\"top\" width=\"40%\">\r\n        <v><%= render_value(\'mallampati_grade\') %></v>\r\n<!--\r\n      <input type=\"checkbox\" name=\"checkbox27\" id=\"checkbox34\" />\r\n    1\r\n    <input type=\"checkbox\" name=\"checkbox27\" id=\"checkbox35\" />\r\n    2\r\n    <input type=\"checkbox\" name=\"checkbox27\" id=\"checkbox36\" />\r\n3\r\n<input type=\"checkbox\" name=\"checkbox27\" id=\"checkbox37\" />\r\n4\r\n--> \r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Thyromental distance :</td>\r\n    <td valign=\"top\">\r\n        <v><%= render_value(\'thyromental_distance\') %></v>\r\n<!--\r\n      <input type=\"checkbox\" name=\"checkbox28\" id=\"checkbox38\" />\r\n    &lt;6 cm.\r\n    <input type=\"checkbox\" name=\"checkbox28\" id=\"checkbox39\" />\r\n    &gt;6 cm. \r\n-->\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Mouth opening : </td>\r\n    <td valign=\"top\">\r\n        <v><%= render_value(\'mouth_opening\') %></v>\r\n<!-- \r\n      <input type=\"checkbox\" name=\"checkbox29\" id=\"checkbox40\" />\r\n    &lt;3 cm.\r\n    <input type=\"checkbox\" name=\"checkbox29\" id=\"checkbox41\" />\r\n    &gt;3 cm. \r\n-->\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Patency of nares :</td>\r\n    <td valign=\"top\">\r\n        <v><%= render_value(\'patency_of_nares\') %></v>\r\n<!--\r\n    <input type=\"checkbox\" name=\"checkbox30\" id=\"checkbox42\" />\r\n    Yes\r\n    <input type=\"checkbox\" name=\"checkbox30\" id=\"checkbox43\" />\r\n    No\r\n        -->\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Prominent incisor :</td>\r\n    <td valign=\"top\">\r\n        <v><%= render_value(\'prominent_incisor\') %></v>\r\n<!--\r\n      <input type=\"checkbox\" name=\"checkbox31\" id=\"checkbox44\" />\r\n    Yes\r\n    <input type=\"checkbox\" name=\"checkbox31\" id=\"checkbox45\" />\r\n    No\r\n        -->\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Limitation of neck :</td>\r\n    <td valign=\"top\">\r\n        <v><%= render_value(\'limitation\') %></v>\r\n<!--\r\n      <input type=\"checkbox\" name=\"checkbox32\" id=\"checkbox46\" />\r\n    Yes\r\n    <input type=\"checkbox\" name=\"checkbox32\" id=\"checkbox47\" />\r\nNo\r\n    -->\r\n</td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">\r\nDiffcult intubation expected :</td>\r\n    <td valign=\"top\">\r\n        <v><%= render_value(\'difficult\') %></v>\r\n<!--\r\n      <input type=\"checkbox\" name=\"checkbox33\" id=\"checkbox48\" />\r\n    Yes\r\n    <input type=\"checkbox\" name=\"checkbox33\" id=\"checkbox49\" />\r\n    No\r\n        -->\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Artificial airway</td>\r\n    <td valign=\"top\">\r\n        <v><%= render_value(\'artificial_airway\') %></v>\r\n<!--\r\n      <input type=\"checkbox\" name=\"checkbox34\" id=\"checkbox50\" />\r\n    ETT\r\n    <input type=\"checkbox\" name=\"checkbox34\" id=\"checkbox51\" />\r\n    Tracheostory\r\n    <input type=\"checkbox\" name=\"checkbox35\" id=\"checkbox52\" />\r\n    None\r\n        -->\r\n    </td>\r\n  </tr>\r\n    <tr>\r\n        <td colspan=\"3\">\r\n<%\r\n    ven_txt = \'\'\r\n    ven_chk_y = \'\'\r\n    ven_chk_n = \'\'\r\n    if this_rec[:ventilator_support] == \'1\'\r\n        ven_chk_y = \'checked\'\r\n        ven_txt += \'&nbsp;&nbsp;&nbsp;&nbsp; Setting : <v>Mode(\'\r\n        ven_txt += this_rec[:mode]\r\n        ven_txt += \') Vt(\'\r\n        ven_txt += this_rec[:vt]\r\n        ven_txt += \') f(\'\r\n        ven_txt += this_rec[:f]\r\n        ven_txt += \') fio2(\'\r\n        ven_txt += \')</v><br/>\'\r\n    end\r\n%>\r\nVentitator support \r\n        <input type=\"checkbox\" name=\"checkbox36\" id=\"checkbox53\" <%= ven_chk_y %> />Yes \r\n        <!--<input type=\"text\" name=\"textfield24\" id=\"textfield26\" />-->\r\n        <input type=\"checkbox\" name=\"checkbox37\" id=\"checkbox54\" <%= ven_chk_n %>/>No\r\n        <br />\r\n        <%= ven_txt.html_safe %>\r\n        <!--<span style=\"border-radius:50%; border:solid black 1px;padding:5px\">Hello</span>-->\r\n        </td>\r\n    </tr>\r\n  \r\n        </table>\r\n    </td>\r\n    <td width=\"50%\" valign=\"top\">\r\n        <br/>\r\n<!-- Head Right\r\n        HN: <v><%= r_pat[:hn] %></v>&nbsp;&nbsp;&nbsp;&nbsp; AN:............................<br />\r\n        NAME: <v><%= r_pat[:prefix] %><%= r_pat[:first_name] %>&nbsp;&nbsp;&nbsp;&nbsp;<%= r_pat[:last_name] %></v> Age: <%= age %><br />\r\n        SEX: <v><%# m_inn[:gender][r_pat[:gender]] %></v>&nbsp;&nbsp;&nbsp;&nbsp;WARD: <v><%= map_ward[r_app[:ward]] %></v><br />\r\n        <br />\r\n        <div style=\"border:1px solid #666; width:100%\">\r\n            Date : <v><%= Time.now.strftime(\"%d/%m/%y %H:%M\") %></v><br />\r\n            Diagnosis : <v><%= r_app[:diagnosis] ?  r_app[:diagnosis] : \'-\' %></v><br />\r\n            Purposed operation : <v><%= r_app[:operation] ?  r_app[:operation] : \'-\' %></v><br />\r\n            Patient Classification by Schedule \r\n        \r\n            <input type=\"checkbox\" name=\"checkbox\" id=\"checkbox\" /> P <input type=\"checkbox\" name=\"checkbox\" id=\"checkbox\" /> NP <input type=\"checkbox\" name=\"checkbox\" id=\"checkbox\" /> EP <input type=\"checkbox\" name=\"checkbox\" id=\"checkbox\" /> XP\r\n     \r\n        \r\n        \r\n        </div><br />\r\n-->\r\n\r\n        <div align=\"center\">\r\n            <strong>Dental Examination</strong>\r\n            <br/>&nbsp;\r\n        </div>\r\n        <table width=\"100%\" border=\"0\">\r\n          <tr>\r\n            <td width=\"14%\">Dentures</td>\r\n            <td width=\"17%\">Full</td>\r\n            <td width=\"69%\"><v><%= render_value(\'dentures_full\') %></v></td>\r\n          </tr>\r\n          <tr>\r\n            <td>&nbsp;</td>\r\n            <td>Partial</td>\r\n            <td><v><%= render_value(\'dentures_partial\') %></v></td>\r\n          </tr>\r\n        </table>\r\n        <!--<table width=\"100%\" border=\"0\">-->\r\n          <!--<tr>-->\r\n            <!--<td width=\"26%\" height=\"28\">Crowns(O)</td>-->\r\n            <!--<td width=\"74%\" rowspan=\"2\">-->\r\n            <!--<br/>-->\r\n<%\r\n    p1 = %w{p13 p12 p11 p21 p22 p23}.collect{|i| i.to_sym}\r\n    r1 = []\r\n    for i in p1 do\r\n        t = i.to_s[1..-1]\r\n        x = this_rec[i]\r\n        if x == \'1\'\r\n            r1.push((\' <span style=\"color:Magenta;font-weight:bold; text-decoration: underline; \">\' + t + \'</span> \').html_safe)\r\n        elsif x == \'2\'\r\n            r1.push((\'<span style=\"color:Red;font-weight:bold\">-<strike>\' + t + \'</strike>-</span>\').html_safe)\r\n        else\r\n            r1.push(\' \' + t + \' \')\r\n        end\r\n    end\r\n    \r\n    p2 = %w{p33 p32 p31 p41 p42 p43}.collect{|i| i.to_sym}\r\n    r2 = []\r\n    for i in p2 do\r\n        t = i.to_s[1..-1]\r\n        x = this_rec[i]\r\n        if x == \'1\'\r\n            r2.push((\' <span style=\"color:Magenta;font-weight:bold;  text-decoration: underline; \">\' + t + \'</span> \').html_safe)\r\n        elsif x == \'2\'\r\n            r2.push((\'<span style=\"color:Red;font-weight:bold\">-<strike>\' + t + \'</strike>-</span>\').html_safe)\r\n        else\r\n            r2.push(\' \' + t + \' \')\r\n        end\r\n    end\r\n%>\r\n<pre style=\"color:black\">\r\nCrowns (<span style=\"color:Magenta;font-weight:bold;  text-decoration: underline; \">00</span>)  Loose teeth (<span style=\"color:Red;font-weight:bold\">-<strike>00</strike>-</span>) \r\n    <%= r1.join(\' | \').html_safe %>\r\n    <%= r2.join(\' | \').html_safe %>\r\n</pre>\r\n<% if false %>\r\n            <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n              <tr>\r\n                <td><del>8</del></td>\r\n                <td>&#9318;</td>\r\n                <td>(6)</td>\r\n                <td>5</td>\r\n                <td>4</td>\r\n                <td>3</td>\r\n                <td>2</td>\r\n                <td>1</td>\r\n                <td bgcolor=\"#000\"></td>\r\n                <td align=\"right\">1</td>\r\n                <td align=\"right\">2</td>\r\n                <td align=\"right\">3</td>\r\n                <td align=\"right\">4</td>\r\n                <td align=\"right\">5</td>\r\n                <td align=\"right\">6</td>\r\n                <td align=\"right\">7</td>\r\n                <td align=\"right\">8</td>\r\n              </tr>\r\n              <tr>\r\n                <td colspan=\"17\" bgcolor=\"#000\" style=\"height:1px\"></td>\r\n              </tr>\r\n              <tr>\r\n                <!-- &#9312; = ⑧ -->\r\n                <td>8</td>\r\n                <td>7</td>\r\n                <td>6</td>\r\n                <td>5</td>\r\n                <td>4</td>\r\n                <td>3</td>\r\n                <td>2</td>\r\n                <td>1</td>\r\n                <td bgcolor=\"#000\"></td>\r\n                <td align=\"right\">1</td>\r\n                <td align=\"right\">2</td>\r\n                <td align=\"right\">3</td>\r\n                <td align=\"right\">4</td>\r\n                <td align=\"right\">5</td>\r\n                <td align=\"right\">6</td>\r\n                <td align=\"right\">7</td>\r\n                <td align=\"right\">8</td>\r\n              </tr>\r\n            </table>\r\n<% end %>    \r\n            <!--</td>-->\r\n          <!--</tr>-->\r\n          <!--<tr>-->\r\n          <!--  <td>Loose teeth (<strike>X</strike>)</td>-->\r\n          <!--</tr>-->\r\n        <!--</table>-->\r\n        <br />\r\n        RS/CVS : <v><%= render_value(\'rs_cvs\') %>&nbsp;&nbsp;<%= this_rec[:rs_cvs_details] %></v>\r\n        <!--<input type=\"text\" name=\"textfield25\" id=\"textfield27\" />-->\r\n        <br />\r\n        Abdomen/Extremities : <v><%= render_value(\'abdomen_extremities\') %>&nbsp;&nbsp;<%= this_rec[:abdomen_extremities_details] %></v>\r\n        <!--<input type=\"text\" name=\"textfield26\" id=\"textfield28\" />-->\r\n        <br />\r\n        Neuro : <v><%= render_value(\'neuro\') %>&nbsp;&nbsp;<%= this_rec[:neuro_details] %></v>\r\n        <!--<input type=\"text\" name=\"textfield27\" id=\"textfield29\" />-->\r\n        <br />\r\n        <center><br /><strong>Laboratory Investigation</strong></center>\r\n        <table width=\"100%\" border=\"0\">\r\n          <tr>\r\n            <td>&nbsp;</td>\r\n            <td>Normal</td>\r\n            <td>Abnormal</td>\r\n            <td>&nbsp;</td>\r\n          </tr>\r\n          <tr>\r\n            <td width=\"28%\">CBC</td>\r\n            <td width=\"12%\">\r\n              <input type=\"checkbox\" name=\"checkbox40\" id=\"checkbox57\" <%= \'checked\' if this_rec[:cbc] == \'1\' %>/>\r\n            </td>\r\n            <td width=\"14%\">\r\n              <input type=\"checkbox\" name=\"checkbox41\" id=\"checkbox58\" <%= \'checked\' if this_rec[:cbc] == \'2\' %>/>\r\n            </td>\r\n            <td width=\"46%\"><input name=\"textfield28\" type=\"text\" id=\"textfield30\" size=\"5\" value=\"<%= this_rec[:cbc_details] %>\" />\r\n              Hb/Hct\r\n              <input name=\"textfield29\" type=\"text\" id=\"textfield31\" size=\"5\" value=\"<%= this_rec[:hb_hct] %>\"/></td>\r\n          </tr>\r\n          <tr>\r\n            <td>UA</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox42\" id=\"checkbox59\" <%= \'checked\' if this_rec[:ua] == \'1\' %>/>\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox43\" id=\"checkbox60\" <%= \'checked\' if this_rec[:ua] == \'2\' %>/>\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield30\" id=\"textfield32\" value=\"<%= this_rec[:ua_details] %>\"/></td>\r\n          </tr>\r\n          <tr>\r\n            <td>BS</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox44\" id=\"checkbox61\" <%= \'checked\' if this_rec[:bs] == \'1\' %>/>\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox45\" id=\"checkbox62\" <%= \'checked\' if this_rec[:bs] == \'2\' %>/>\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield31\" id=\"textfield33\" value=\"<%= this_rec[:bs_details] %>\"/></td>\r\n          </tr>\r\n          <tr>\r\n            <td>BUN/Cr.</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox46\" id=\"checkbox63\" <%= \'checked\' if this_rec[:bun_cr] == \'1\' %>/>\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox47\" id=\"checkbox64\" <%= \'checked\' if this_rec[:bun_cr] == \'2\' %>/>\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield32\" id=\"textfield34\" value=\"<%= this_rec[:bun_cr_details] %>\"/></td>\r\n          </tr>\r\n          <tr>\r\n            <td>Electrotytes</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox48\" id=\"checkbox65\" <%= \'checked\' if this_rec[:electrolytes] == \'1\' %>/>\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox49\" id=\"checkbox66\" <%= \'checked\' if this_rec[:electrolytes] == \'2\' %>/>\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield33\" id=\"textfield35\" value=\"<%= this_rec[:electrolytes_details] %>\"/></td>\r\n          </tr>\r\n          <tr>\r\n            <td>Coagulation Study</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox50\" id=\"checkbox67\" <%= \'checked\' if this_rec[:coagulation_study] == \'1\' %>/>\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox53\" id=\"checkbox70\" <%= \'checked\' if this_rec[:coagulation_study] == \'2\' %>/>\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield34\" id=\"textfield36\" value=\"<%= this_rec[:coagulation_study_details] %>\"/></td>\r\n          </tr>\r\n          <tr>\r\n            <td>HIV/VDRL</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox51\" id=\"checkbox68\" <%= \'checked\' if this_rec[:hiv_vdrl] == \'1\' %>/>\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox52\" id=\"checkbox69\" <%= \'checked\' if this_rec[:hiv_vdrl] == \'2\' %> />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield35\" id=\"textfield37\" value=\"<%= this_rec[:hiv_vdrl_details] %>\"/></td>\r\n          </tr>\r\n          <tr>\r\n            <td>CXR</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox54\" id=\"checkbox71\" <%= \'checked\' if this_rec[:cxr] == \'1\' %>/>\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox55\" id=\"checkbox72\" <%= \'checked\' if this_rec[:cxr] == \'2\' %>/>\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield36\" id=\"textfield38\" value=\"<%= this_rec[:cxr_details] %>\"/></td>\r\n          </tr>\r\n          <tr>\r\n            <td>EKG</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox56\" id=\"checkbox73\" <%= \'checked\' if this_rec[:ekg] == \'1\' %>/>\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox57\" id=\"checkbox74\" <%= \'checked\' if this_rec[:ekg] == \'2\' %>/>\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield37\" id=\"textfield39\" value=\"<%= this_rec[:ekg_details] %>\"/></td>\r\n          </tr>\r\n          <tr>\r\n            <td>Other</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox58\" id=\"checkbox75\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox59\" id=\"checkbox76\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield38\" id=\"textfield40\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td><%# render_value(\'other_laboratory_investigation\') %></td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox61\" id=\"checkbox78\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox60\" id=\"checkbox77\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield39\" id=\"textfield41\" /></td>\r\n          </tr>\r\n        </table>        <br />\r\n        <center><strong>Assessment/Preparation</strong></center><br />\r\n        ASA Physical status : <v><%= this_rec[:asa_status] %></v>\r\n<!--\r\n        <input type=\"checkbox\" name=\"checkbox62\" id=\"checkbox79\" />\r\n        1\r\n        <input type=\"checkbox\" name=\"checkbox62\" id=\"checkbox80\" />\r\n        2\r\n        <input type=\"checkbox\" name=\"checkbox62\" id=\"checkbox81\" />\r\n3\r\n<input type=\"checkbox\" name=\"checkbox62\" id=\"checkbox82\" />\r\n4\r\n<input type=\"checkbox\" name=\"checkbox63\" id=\"checkbox83\" />\r\n5\r\n<input type=\"checkbox\" name=\"checkbox64\" id=\"checkbox84\" />\r\nE\r\n-->\r\n<br />\r\nProblem/Risks : <v><%= render_value(\'problems_risk\') %></v><br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;<v><%= this_rec[:problems_risk_details] %></v> \r\n<!--<textarea name=\"textarea2\" id=\"textarea2\" cols=\"45\" rows=\"2\"></textarea>-->\r\n<br />\r\nAnesthetic plan : <v><%= render_value(\'anesthetic_plan\') %></v>\r\n<!--<input name=\"textfield40\" type=\"text\" id=\"textfield42\" size=\"8\" /> -->\r\n<br/>\r\nBlood prepared : Group (<v><%= render_value(\'group\') %></v>), PRC (<v><%= render_value(\'prc\') %></v> u.), FFP (<v><%= render_value(\'ffp\') %></v> u.), Plt (<v><%= render_value(\'plt\') %></v> u.)\r\n<!--<input name=\"textfield41\" type=\"text\" id=\"textfield43\" size=\"8\" />-->\r\n<br />\r\nSuggested preparation : <v><%= render_value(\'suggested_preparation\') %></v><br/>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<v>\r\n    <%= this_rec[:suggested_preparation_details] %>\r\n    <%= render_value(\'suggested_preparation_induction\') %> \r\n    <%= render_value(\'suggested_preparation_muscle\') %> \r\n    <%= render_value(\'suggested_preparation_narcotic\') %> \r\n    <%= render_value(\'suggested_preparation_inhalation\') %> \r\n    <%= render_value(\'suggested_preparation_equipment\') %> \r\n    <%= this_rec[:suggested_preparation_details] %>\r\n</v> \r\n<!--<input type=\"text\" name=\"textfield42\" id=\"textfield44\" />-->\r\n<br />\r\nPremedications : <v><%= render_value(\'premed\') %></v><br/>\r\n<% if this_rec[:premed] == \'1\' %>\r\n&nbsp;&nbsp;&nbsp;&nbsp;Anti-anxiety : <v><%= render_value(\'med_anti_anxiety_name\') %>  [<%= this_rec[:med_anti_anxiety_unit]%> mg]</v><br/>\r\n&nbsp;&nbsp;&nbsp;&nbsp;Analgesics : <v><%= render_value(\'med_analgesics_name\') %>  [<%= this_rec[:med_analgesics_unit]%> mg]</v><br/>\r\n&nbsp;&nbsp;&nbsp;&nbsp;GI Preparation : <v><%= render_value(\'med_gi_preparation_name\') %>  [<%= this_rec[:med_gi_preparation_unit]%> mg]</v><br/>\r\n<% end %>\r\n<!--<br /><textarea name=\"textarea3\" id=\"textarea3\" cols=\"45\" rows=\"2\"></textarea>-->\r\nPost-op Pain Relief Plan : <v><%= render_value(\'post_op_pain_relief_plan\') %></v>\r\n<!--<input type=\"text\" name=\"textfield43\" id=\"textfield45\" />-->\r\n<br />\r\nChecklists for informed education : <v><%= render_value(\'informed_education\') %></v>\r\n<%= \'<br/>&nbsp;&nbsp;&nbsp;&nbsp;Note : \'.html_safe if this_rec[:informed_education_other] != \'\' %><v><%= this_rec[:informed_education_other] %></v>\r\n<br />\r\n\r\n<%\r\n    if this_rec[:proposed_anesthetic_plan] != \'\'\r\n        txt = render_value(\'proposed_anesthetic_plan\').split(\',\').join(\' and \')\r\n%>\r\n<br />\r\nI have discussed the proposed anesthetic plan and possble alternatives with the <br/>&nbsp;&nbsp;&nbsp;&nbsp;<v><%= txt %></v>\r\n<br />\r\n<%\r\n    end\r\n%>\r\n<br/>\r\nAnesthesiologist Name : <v><%= render_value(\'anesthesiologist\') %></v>\r\n<br/>\r\nNurse Anesthetist : <v><%= render_value(\'nurse\') %></v>\r\n<!--<br />-->\r\n<br />\r\n<center>ข้าพเจ้าได้รับข้อมูลและมีโอกาสได้ซักถามเกี่ยวกับ<br />\r\nการให้ยาระงับความรู้สึกแล้ว<br /><br />\r\n.......................................<br />(...<v><%= r_pat[:prefix] %><%= r_pat[:first_name] %>....<%= r_pat[:last_name] %></v>...)<br />\r\nผู้ป่วย</center></td>\r\n    </tr>\r\n  </table>\r\n  <div class=\"footer\">Printed : <v><%= Time.now.strftime(\'%d/%m%Y %H:%M\') %></v></div>\r\n</div>\r\n\r\n</body>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2015-07-17 17:46:18','2015-07-17 17:46:18','print_old',''),(1684,'show',600,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    # map procedure\r\n    models = get_model\r\n    m_procedure = models[:procedure].all\r\n    map_proc = {}\r\n    for m in m_procedure do\r\n        map_proc[m.id.to_s] = {:name=>m[:name], :code=>m[:code]}\r\n    end\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient_module = ehr_models[:patient_module]\r\n    \r\n    pm = m_patient_module.find(params[:id])\r\n    m_ap = m_patient_module.where(:id=>pm[:parent_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\").first\r\n    ap = models[:appointment].find(m_ap[:module_id])\r\n    \r\n    if params[:b] == \'1\' \r\n        s = \'0\'\r\n        if params[:s] == \'1\'\r\n            s = \'2\'\r\n        elsif params[:s] == \'2\'\r\n            s = \'1\'\r\n        end\r\n        # ap.update_attributes :bilateral=>\'1\', :side=>params[:s]\r\n        # create_next = \"create?patient_id=\\\\#{params[:patient_id]}&record_name=\\\\#{params[:record_name]}&parent_id=\\\\#{params[:parent_id]}&return=\\\\#{params[:return]}\"\r\n        # ../Home/appointment_create?patient_id=5576b0ab790f9b4002000003&data[date]=2015-06-10&data[provider]=5576b180790f9b4002000012&data[procedure]=5576b0e4790f9b4002000005&return=%2Ftaig%2Fthkr%2FHome%2Fpatient_record%3Fid%3D5576b0ab790f9b4002000003&commit=Add+New\r\n        create_next = \"../Home/appointment_create?patient_id=\\\\#{params[:patient_id]}&s=\\\\#{s}&act=z&data[provider]=\\\\#{ap[:provider]}&data[procedure]=\\\\#{ap[:procedure]}&data[date]=\\\\#{ap[:date]}&return=\\\\#{params[:return]}\"\r\n        \r\n        if params[:act] == \'z\'\r\n            params[:b] = nil\r\n        end\r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<!--<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>-->\r\n<strong><%= map_proc[ap[:procedure].to_s][:name] %></strong>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print_pgh?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<%# pm.inspect %>\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n\r\n\r\n<%= this.display.html_safe %>\r\n<div style=\"padding:20px\">\r\n<% if params[:b] %>\r\n    <%= link_to \'Next\', create_next, :class=>\'btn btn-button btn-success\' %> | \r\n<% else %>\r\n    <%= link_to \'Finish\', return_url, :class=>\'btn btn-button btn-success\' %> | \r\n<% end %>\r\n    <%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2015-07-19 16:44:04','2015-07-19 16:44:04','show',''),(1685,'total_ssa_report',522,2,'<h1>SSA reports</h1>\r\n<%= render :inline=>this.init%>\r\n<%\r\n\r\n    m = @models[:colonoscopy_scope].collection.find({},{:fields=>{\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1 }}).to_a\r\n   \r\n#   colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n\r\n\r\n   def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n\r\n    \r\n    list = []\r\n    res = []\r\n    \r\n    for i in m\r\n    \r\n        if i[\'endoscopy_dx\']==\'Sessile Serrated Adenoma\'\r\n            list << i \r\n        elsif i[\'abnormal_note\'] and i[\'abnormal_note\'].downcase.index(\'ssa\')\r\n            list << i\r\n        end\r\n    end\r\n    \r\n    # m = @models[:colonoscopy_scope].collection.find({},{:fields=>{\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1 }}).to_a\r\n   \r\n    list = @models[:colonoscopy_scope].collection.find({:_id=>{\'$in\'=>list.collect{|i|i[\'_id\']}}}).to_a\r\n    \r\n    # { $where: \"this.name.length > 1\" }\r\n    \r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n    map = {\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1 }\r\n    qmap = {:diagnosis_group=>{\'$ne\'=>\'Normal\'}}\r\n    where = []\r\n    for i in scope_list\r\n        map[i]=1\r\n        # \'$where\': \"this.name.length > 1\"\r\n        # where << \"this.\\\\#{i}.length > 1\"\r\n    end\r\n    \r\n    \r\n    qmap[\'$where\']= \'this.rectum_scope.length > 1 || this.sigmoid_scope.length > 1 || this.transvers_colon_scope.length>1 || this.ascending_colon_scope.length>1 || this.cecum_scope.length>1 || this.terminal_ileum_scope.length>1\'\r\n    \r\n    ml = @models[:colonoscopy].collection.find(qmap,{:fields=>map}).to_a\r\n    \r\n    lim = {}\r\n    for i in list\r\n    \r\n        lim[i[\'_id\']] = i\r\n    \r\n    end\r\n    \r\n    plist = {}\r\n    \r\n    for i in ml\r\n    \r\n        f = false\r\n        \r\n        for j in scope_list\r\n            \r\n            for k in i[j]\r\n            \r\n            if lim[k]\r\n       \r\n                plist[i[\'_id\']] = {:c=>i,:l=>{}} unless plist[i[\'_id\']]\r\n                \r\n                plist[i[\'_id\']][:l][j] = [] unless plist[i[\'_id\']][:l][j]\r\n                plist[i[\'_id\']][:l][j] << lim[k]\r\n                \r\n            end\r\n            \r\n            end\r\n             \r\n        end\r\n    end\r\n#   {:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}}\r\n     # all pm colono of those appointments\r\n     \r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    \r\n    all_pm_colo = @m_patient_module.collection.find({:module_id=>{\'$in\'=>plist.keys},:module_name=>\"\\\\#{pname}colonoscopy\"}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'module_id\'\r\n    \r\n          # all pm colono of those appointments\r\n    all_patient = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'patient_id\'] }}}).to_a\r\n    m_all_patient = bmap all_patient, \'_id\'\r\n    \r\n    cols = %w{abnormal_type  endoscopy_dx morphology_type size treatment treatment_by clip patho_number pit_pattern pit_pattern pitt_by kudo_type vascular_pattern \r\n    vascular_by sano_type nice_classification niceby abnormal_note tattoo jnet_class jnetby chromo complication } \r\n    count=0\r\n%>\r\n<table border=\"1\" style=\"border-collapse: collapse;font-size:0.6em\" ><th>No.</th>\r\n<th style=\"width:100px\">Date</th><th>HN</th><th style=\"width:100px\">First name</th><th style=\"width:100px\">Last name</th>\r\n<th>Location</th>\r\n<% for x in cols %>\r\n<th><%= x.humanize %></th>\r\n<% end %>\r\n<% 5.times.each do |i| %>\r\n<th  style=\"width:100px\"><%=i+1%>.</th>\r\n<% end %>\r\n<%\r\n   for i in plist.keys\r\n    colo = plist[i]\r\n    c = colo[:c]\r\n    l = colo[:l]\r\n    p_m = m_all_pm_colo[i][0]\r\n    p = m_all_patient[p_m[\'patient_id\']][0] \r\n    \r\n    l.each_pair do |location,list|\r\n        for li in list\r\n\r\n%>\r\n<tr><td><%=count+1%>.<% count+=1 %></td><td><%=p_m[\'date\'].strftime(\"%d-%m-%Y\")%></td><td><%=p[\'hn\']%></td>\r\n<td><%=p[\'first_name\']%></td><td><%=p[\'last_name\']%></td>\r\n\r\n<td><%=location.split(\"_\")[0..-2].join(\" \")%></td>\r\n<% for x in cols\r\n style=\"\"\r\n style=\'style=\"width:150px\"\' if x==\'endoscopy_dx\'\r\n%>\r\n<td <%=style.html_safe%>><%= li[x] %></td>\r\n<% end %>\r\n<% \r\n  \r\n\r\n    atts = @models[:attachment].find(li[\'image\']).to_a\r\n    \r\n    %>\r\n    <%=%>\r\n<%\r\nl = atts[0..4].compact\r\nfor ai in l\r\n%>\r\n<td style=\"width:100px\">\r\n<a href=\"<%=ai.path%>\" class=\"highslide \" rel=\"highslide\" onclick=\"return hs.expand(this)\"><center>\r\n<img  src=\"<%=ai.path%>&thumb=1\" width=\"100\" />\r\n</a>\r\n</td>\r\n<% end %>\r\n\r\n<% (5-l.size).times do |img| %>\r\n<td >&nbsp;</td>\r\n<% end %>\r\n</tr>\r\n\r\n <% \r\n        end\r\n    end\r\n end %>    \r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-07-19 18:54:44','2015-07-19 18:54:44','total_ssa_report',''),(1686,'print_table',717,3,'<%\r\n    sample = false\r\n    if params[:sample] == \'true\'\r\n        sample = true\r\n    end\r\n    \r\n    date = Time.now\r\n    date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    # a_pat_mod = m_pat_mod.where\r\n\r\n    # This model\r\n    model = get_model\r\n    m_app = model[:appointment]\r\n    \r\n    conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n    aps = m_app.all(conds)\r\n    \r\n    if sample\r\n        res = {}\r\n        res[:aps] = aps\r\n\r\n    else\r\n%>\r\n<html>\r\n\r\n<head>\r\n<meta http-equiv=Content-Type content=\"text/html; charset=windows-1252\">\r\n<meta name=Generator content=\"Microsoft Word 14 (filtered)\">\r\n<style>\r\n<!--\r\n /* Font Definitions */\r\n @font-face\r\n	{font-family:Calibri;\r\n	panose-1:2 15 5 2 2 2 4 3 2 4;}\r\n /* Style Definitions */\r\n p.MsoNormal, li.MsoNormal, div.MsoNormal\r\n	{margin-top:0in;\r\n	margin-right:0in;\r\n	margin-bottom:10.0pt;\r\n	margin-left:0in;\r\n	line-height:115%;\r\n	/*font-size:9.0pt;*/\r\n	/*font-size:1em;*/\r\n	font-size:.8em;\r\n	font-family:\"Calibri\",\"sans-serif\";}\r\np.msochpdefault, li.msochpdefault, div.msochpdefault\r\n	{mso-style-name:msochpdefault;\r\n	margin-right:0in;\r\n	margin-left:0in;\r\n	font-size:10.0pt;\r\n	font-family:\"Calibri\",\"sans-serif\";}\r\np.msopapdefault, li.msopapdefault, div.msopapdefault\r\n	{mso-style-name:msopapdefault;\r\n	margin-right:0in;\r\n	margin-bottom:10.0p