n 2pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><b>Position/AnesthTech</b></p>\r\n  </td>\r\n  <td width=114 style=\'width:120pt;border:solid windowtext 1.0pt;border-left:\r\n  none;background:#D9D9D9;padding:0in 2pt 0in 2pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><b>Surgeon/Assist</b></p>\r\n  </td>\r\n  <td width=114 style=\'width:120pt;border:solid windowtext 1.0pt;border-left:\r\n  none;background:#D9D9D9;padding:0in 2pt 0in 2pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><b>Anesth/Assist</b></p>\r\n  </td>\r\n  <td width=174 style=\'width:80pt;border:solid windowtext 1.0pt;border-left:\r\n  none;background:#D9D9D9;padding:0in 2pt 0in 2pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><b>Instrument</b></p>\r\n  </td>\r\n  <td width=40 style=\'width:40pt;border:solid windowtext 1.0pt;border-left:\r\n  none;background:#D9D9D9;padding:0in 2pt 0in 2pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><b>Post-op</b></p>\r\n  </td>\r\n </tr>\r\n <%\r\n    map_or_room = {}\r\n    map_or_room[\"\"]  = \"-\"\r\n    map_or_room[nil] = \"-\"\r\n    for i in model[:or_room].all do\r\n        map_or_room[i.id.to_s] = i[:name]\r\n    end\r\n    map_ward = {}\r\n    for i in model[:ward].all do\r\n        map_ward[i.id.to_s] = i[:name]\r\n    end\r\n    map_position = {nil=>\'N/A\',\'\'=>\'N/A\'}\r\n    for i in model[:position].all do\r\n        map_position[i.id.to_s] = i[:name]\r\n    end\r\n    map_postop = {}\r\n    for i in model[:post_op_ward].all do\r\n        map_postop[i.id.to_s] = i[:name]\r\n    end\r\n    map_provider = {}\r\n    map_provider[\"\"] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    map_instrument = {}\r\n    for i in model[:instrument].all do\r\n        map_instrument[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    l_updated = []\r\n    aps = aps.sort_by{|i| [map_or_room[i[:or_room]], !i[:start].nil? ? i[:start].strftime(\'%H:%M\') : \'N/A\']}\r\n\r\n    for i in aps do\r\n        if i[:status] == \'Cancelled\'\r\n            next\r\n        end\r\n        \r\n        surgeon = \'N/A\'\r\n        if sg = map_provider[i[:surgeon].to_s]\r\n            surgeon = sg\r\n        end\r\n        \r\n        i[:surgeon] == \'0\' ? \'N/A\' : map_provider[i[:surgeon]] \r\n        \r\n        r_pat_mod = m_pat_mod.where(:module_id=>i.id).first\r\n        if r_pat_mod\r\n            r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n            if r_pat\r\n            \r\n                # latest user\r\n                l_updated.push({:user=>i[:updated_by],:time=>i[:updated_at]})\r\n                \r\n                # age\r\n                today = Date.today\r\n                \r\n                d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n              \r\n                age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n                if age == 0 \r\n                    d = today if age ==0 \r\n                    age = !r_pat[:birth_date].nil? ? (((d - r_pat[:birth_date].to_datetime).to_i/30) - (d > today ? 1 : 0)).to_s : \'N/A\' \r\n                    age = \"\"+age+\"m\"\r\n                end\r\n                \r\n                if age == \'0m\'\r\n                    d = today if age ==0 \r\n                    age = !r_pat[:birth_date].nil? ? (((d - r_pat[:birth_date].to_datetime).to_i) - (d > today ? 1 : 0)).to_s : \'N/A\' \r\n                    age = \"\"+age+\"d\"\r\n                end\r\n                \r\n                \r\n            \r\n%>\r\n<!--\r\n<%= d%> <%=r_pat[:birth_date]%> <%=(d - r_pat[:birth_date].to_datetime).to_i%>\r\n<%=((d - r_pat[:birth_date].to_datetime).to_i/3600/24)%>\r\n--> \r\n <tr style=\'height:.3in\'>\r\n  <td style=\'width:34.8pt;border:solid windowtext 1.0pt;border-top:\r\n  none;padding:0in 5.4pt 0in 5.4pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-heigh3:normal\'><%= map_or_room[i[:or_room]] %> </p>\r\n  </td>\r\n  <td style=\'border-top:none;border-left:none;border-bottom:\r\n  solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;padding:0in 2pt 0in 2pt;\r\n  height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><% if i[:time_tf] == \'1\' %><%= \'TF\'  %><% else %><%= !i[:start].nil? ? i[:start].strftime(\'%H:%M\') : \'N/A\' %><% end %> </p>\r\n  </td>\r\n  <td style=\'width:145.7pt;border-top:none;border-left:none;\r\n  border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n  padding:0in 2pt 0in 2pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'>\r\n    <%= \"(\\\\#{i[:case_type]}) \" unless !i[:case_type] or i[:case_type] == \'\'%>\r\n    HN : <%= r_pat[:hn] %>, Age : <%= age %></p>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'>\r\n    <%= r_pat[:prefix_name] %><%= r_pat[:first_name] %>&nbsp;&nbsp;&nbsp;&nbsp;<%= r_pat[:last_name] %></p>\r\n  </td>\r\n<!--\r\n  <td style=\'width:.4in;border-top:none;border-left:none;border-bottom:\r\n  solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;padding:0in 2pt 0in 2pt;\r\n  height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><%= age %></p>\r\n  </td>\r\n -->\r\n  <td style=\'width:40.5pt;border-top:none;border-left:none;border-bottom:\r\n  solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;padding:0in 0in 0in 0in;\r\n  height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><%= map_ward[i[:ward]] %></p>\r\n  </td>\r\n  <td style=\'width:100.0pt;border-top:none;border-left:none;\r\n  border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n  padding:0in 2pt 0in 2pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'>Dx : <%= i[:diagnosis] %> /<br/>Op : <%= i[:operation] %></p>\r\n  </td>\r\n<!--\r\n  <td style=\'width:80pt;border-top:none;border-left:none;\r\n  border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n  padding:0in 5.4pt 0in 5.4pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><%= i[:diagnosis] %></p>\r\n  </td>\r\n  <td style=\'width:100.0pt;border-top:none;border-left:none;\r\n  border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n  padding:0in 5.4pt 0in 5.4pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><%= i[:operation] %></p>\r\n  </td>\r\n-->\r\n  <td style=\'width:63.0pt;border-top:none;border-left:none;border-bottom:\r\n  solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;padding:0in 2pt 0in 2pt;\r\n  height:.3in\'>\r\n<%\r\n    a_tech = i[:anesth_technique] ? i[:anesth_technique] : \'N/A\'\r\n    a_tech = a_tech == \'\' ? \'-\' : a_tech\r\n%>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><%= map_position[i[:position]] %> / <%= a_tech %></p>\r\n  </td>\r\n  <td style=\'width:130pt;border-top:none;border-left:none;\r\n  border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n  padding:0in 2pt 0in 2pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'>S: <%= i[:surgeon] == \'0\' ? \'N/A\' : map_provider[i[:surgeon].to_s] %></p>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'>A: <%= i[:assist] == \'0\' ? \'N/A\' : map_provider[i[:assist].to_s] %></p>\r\n  </td>\r\n  <td style=\'width:130pt;border-top:none;border-left:none;\r\n  border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n  padding:0in 2pt 0in 2pt;height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'>M: <%= i[:anesth] == \'0\' ? \'N/A\' : map_provider[i[:anesth].to_s] %></p>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'>A1: <%= i[:anesth_assist] == \'0\' ? \'N/A\' : map_provider[i[:anesth_assist].to_s] %></p>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'>A2: <%= i[:anesth_assist_2] == \'0\' ? \'N/A\' : map_provider[i[:anesth_assist_2].to_s] %></p>\r\n  </td>\r\n  <td style=\'width:50pt;border-top:none;border-left:none;\r\n  border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n  padding:0in 2pt 0in 2pt;height:.3in\'>\r\n  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n  normal\'>\r\n    <% \r\n        l_instr = !i[:instrument].nil? ? i[:instrument].split(\'|\') : []\r\n        s_instr = []\r\n        for x in l_instr do\r\n            s_instr.push(map_instrument[x])\r\n        end\r\n    %>\r\n    <%= s_instr.join(\'<br/>\').html_safe %><%= \'<br/>\'.html_safe if !s_instr.empty? %><%= \"\\\\#{i[:instrument_other]}\".html_safe if i[:instrument_other] != \'\'%>\r\n  </p>\r\n  </td>\r\n  <td style=\'width:49.5pt;border-top:none;border-left:none;border-bottom:\r\n  solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;padding:0in 2pt 0in 2pt;\r\n  height:.3in\'>\r\n  <p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n  text-align:center;line-height:normal\'><%= map_ward[i[:post_op]] %></p>\r\n  </td>\r\n </tr>\r\n<%\r\n            end # end if r_pat\r\n        end # end if r_pat_mod\r\n    end\r\n%>\r\n</table>\r\n<br/>\r\n<p class=MsoNormal>\r\n<%\r\n    if !l_updated.empty?\r\n        latest_user = l_updated.sort_by{|i| i[:time]}.reverse.first\r\n        prov = get_model[:provider].where(:login=>latest_user[:user]).first\r\n%>\r\n            <span style=\"float:right\">\r\n                <i>Last updated by <span style=\"color:blue\"><%= prov.nil? ? latest_user[:user] : \"\\\\#{prov[:name]} (\\\\#{latest_user[:user]})\" %></span> at <span style=\"color:blue\"><%= latest_user[:time].strftime(\'%d/%m/%Y %H:%M\') %></span></i>\r\n            </span>\r\n            <br/>\r\n<%\r\n    end\r\n%>\r\n</p>\r\n\r\n<p class=MsoNormal>&nbsp;</p>\r\n\r\n<p class=MsoNormal>&nbsp;</p>\r\n\r\n</div>\r\n\r\n<script>\r\n<% if @current_role != \'developer\' %>\r\n    window.print();\r\n<% end %>\r\n</script>\r\n\r\n</body>\r\n\r\n</html>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2015-07-20 08:06:35','2015-07-20 08:06:35','print_table',''),(1687,'document_name',754,1,'\'lesion\'',NULL,NULL,NULL,'2015-07-20 12:22:47','2015-07-20 12:22:47',NULL,NULL),(1688,'search',345,3,'<% \r\n\r\n\r\ndef get_hn i\r\n  i = i.strip\r\n  n = \'\'\r\n  y = \'\'\r\n  \r\n  return i if i.size<5 or i.size>9\r\n  if i.index \'/\'  \r\n    t = i.split(\"/\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.index \'-\'  \r\n    t = i.split(\"-\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.size==8\r\n    y = i[0..1].to_i\r\n    y2 = i[-2..-1].to_i\r\n    n = i[3..-1].to_i  \r\n    if y2 > y\r\n      y = y2\r\n      n = i[0..-3].to_i    \r\n    end\r\n  else\r\n    y = i[-2..-1]\r\n    n = i[0..-3]\r\n  end\r\n  \r\n  hn = \"\\\\#{n.to_i.to_s}/\\\\#{y}\"\r\n\r\n  return hn    \r\n\r\nend\r\n    \r\n   models = get_model\r\n\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   model = models[:patient]\r\n   \r\n  \r\n   \r\n   query = params[:q]\r\n   \r\n   # chula hn customize \r\n   oquery = query\r\n#   iquery = query.to_i\r\n   query = get_hn query\r\n#   if iquery!=0 and !query.index(\'/\')\r\n#       query = \"\\\\#{query[0..-3]}/\\\\#{query[-2..-1]}\"\r\n#   end\r\n\r\n\r\n   keys = []\r\n   \r\n   @document.list_fields.each_with_index do |f,index| \r\n    keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n    keys <<{f.column_name.to_sym=>Regexp.new(oquery)}\r\n   end\r\n   \r\n\r\n   records = model.all({\'$or\'=>keys}.merge!({:limit=>20}))\r\n%><br/>\r\nQuery for <%=query %>\r\n<%= tabular :data=>records,:model=>labels do |i,out|\r\n    \r\n    if params[:name]\r\n        \r\n       mapps = models[:patient_module].where(:patient_id=>i.id, :module_name=> params[:name]).all\r\n          \r\n        \r\n    end\r\n    \r\n    \r\nout << (\"<div id=\'\\\\#{i.id}\' >\"+link_to(\'Select\',\'javascript:doSelect(\"\'+i.id.to_s+\'\")\')+\"</div>\").html_safe\r\nout\r\nend \r\n%><center><a href=\"../../www/Patient/create?return=<%=params[:return]%>\" class=\"<%=bt_class%>\">New Patient</a></center>\r\n<script>\r\n    if(typeof search_appointment === \"function\"){\r\n        search_appointment(<%=records.to_json.html_safe%>)\r\n    }else{\r\n        alert(\'ok\')\r\n    }\r\n</script>',NULL,NULL,NULL,'2015-07-20 16:09:49','2015-07-20 16:09:49','search',''),(1689,'sumgroup',711,1,'{\r\n	:total_ward => {\r\n		:select => [:activity_ward, :respiration_ward, :circulation_ward, :consciousness_ward, :oxygen_saturation_ward],\r\n		:total => :total_mass_ward\r\n	},\r\n	:total_alteration => {\r\n		:select => [:alteration_e, :alteration_v, :alteration_m],\r\n		:total => :alteration_gcs,\r\n		:letter => [\'T\']\r\n	}\r\n}',NULL,NULL,NULL,'2015-07-20 17:18:47','2015-07-20 17:18:47','sumgroup',''),(1690,'get_image_capture_by_admit_id',755,3,'<%= render :inline=>this.init%><%\r\n    result=nil\r\n    if params[:admit_id] \r\n        \r\n    # services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').compact\r\n    \r\n      list = []\r\n        Service.find(@current_project.init_instance[:services].collect{|i| i.id}).each do |i|\r\n        if i.extended==\'cusys.med.FindingDocument\'\r\n          list << i\r\n        end          \r\n          \r\n        end\r\n        \r\n      services = list  \r\n    \r\n\r\n    admit_id = params[:admit_id]\r\n    \r\n    mapp = @patient_module_model.where(:module_id=>admit_id).first\r\n    patient = @patient_model.find(mapp.patient_id) if mapp\r\n    \r\n    if mapp and patient\r\n    \r\n    \r\n    list = services.collect{|i|\r\n    \r\n    doc =  @current_project.get_document i.name\r\n  \r\n    model = @models[doc.name.to_sym]\r\n   \r\n    mm = @patient_module_model.where(:parent_id=>mapp.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\").first\r\n    \r\n    if mm\r\n        record = model.find(mm.module_id)\r\n    else\r\n        mm = @patient_module_model.new :module_name=>\"\\\\#{@current_project.name}#\\\\#{doc.name}\", :parent_id=>mapp.id\r\n        record = model.new\r\n    end\r\n    \r\n    \r\n    \r\n    img_f = nil\r\n    \r\n        ohn = patient.hn\r\n        hn = patient.hn.split(\"/\").join(\"-\")\r\n        \r\n            \r\n        \r\n        \r\n        \r\n        record_id = mm.id\r\n        \r\n        imgs = nil        \r\n        for j in doc.fields \r\n            if j.field_type == \'image_camera\'\r\n                img_f = j \r\n                snap = URI.encode(\"/esm_image/\\\\#{doc.id}/snap?field_id=\\\\#{j.id}&p_id=\\\\#{@current_project.id}&path=esm/\\\\#{@current_project.esm.name}/\\\\#{@current_project.name}/\\\\#{hn}/\\\\#{doc.name}/\\\\#{Time.now.strftime(\'%Y-%m-%d\')}-\\\\#{record_id}/image&ref=\\\\#{ohn}\")\r\n                # admit_id, doc_id, record_id\r\n                attachment = URI.encode(\"/esm/\\\\#{@current_project.esm.name}/\\\\#{@current_project.name}/Api/attach_image_by_admit_id?admit_id=\\\\#{admit_id}&doc_id=\\\\#{doc.name}&record_id=\\\\#{record_id}&f_id=\\\\#{j.column_name}\")\r\n                \r\n                imgs = {:name=>doc.name,:title=>doc.title, :snap_url=>snap,:attach_url=>attachment}    \r\n            end\r\n        end\r\n    \r\n    \r\n    imgs if img_f\r\n    \r\n    }    \r\n    \r\n    list.compact!\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n    result = {:result=>\'200 OK\',:return=>list,:timestamp=>Time.now}\r\n    else\r\n    result = {:result=>\'404 Not found\',:return=>nil,:timestamp=>Time.now}\r\n    end\r\n\r\n%><%= result.to_json.html_safe%>',NULL,NULL,NULL,'2015-07-20 17:18:48','2015-07-20 17:18:48','get_image_capture_by_admit_id','*'),(1691,'form',711,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    mname = \"\\\\#{@current_project.name}#pre_anesthetic\"\r\n    \r\n    r_pre_anes = nil\r\n    pm_pre = nil\r\n    \r\n    if params[:opt] == \'edit\'\r\n        r_pat_mod = m_pat_mod.find(params[:id])\r\n        pm_pre = m_pat_mod.where(:module_name=>mname, :parent_id=>r_pat_mod[:parent_id]).first\r\n    elsif params[:opt] == \'create\'\r\n        pm_pre = m_pat_mod.where(:module_name=>mname, :parent_id=>params[:parent_id]).first\r\n    end\r\n    \r\n    if pm_pre\r\n        r_pre_anes = get_model[:pre_anesthetic].find(pm_pre[:module_id])\r\n%>\r\n    // assign pre_anesth\r\n    $(document).ready(function(){\r\n        tmp = $(\'#data-asa_status\').val();\r\n        if (tmp === \'\') {\r\n            $(\'#data-asa_status\').val(\'<%= r_pre_anes[:asa_status] %>\');\r\n            $(\"input[name=update_asa_status][value=\'<%= r_pre_anes[:asa_status] %>\']\").prop(\'checked\', true);\r\n        }\r\n        tmp = $(\'#data-asa_type\').val();\r\n        if (tmp === \'\') {\r\n            $(\'#data-asa_type\').val(\'<%= r_pre_anes[:asa_type] %>\');\r\n            $(\"input[name=update_asa_type][value=\'<%= r_pre_anes[:asa_type] %>\']\").prop(\'checked\', true);\r\n        }\r\n        tmp = $(\'#data-anesth_technique\').val();\r\n        if (tmp === \'\') {\r\n            $(\'#data-anesth_technique option[value=\"<%= r_pre_anes[:anesthetic_plan] %>\"]\').prop(\'selected\', true);\r\n            //$(\'#data-anesth_technique option:eq(\"<%= r_pre_anes[:anesthetic_plan] %>\")\').prop(\'selected\', true);\r\n        }\r\n    });\r\n<%\r\n    end\r\n%>\r\n    \r\n    function update_recovery_time() {\r\n        ods = $(\'#data-recovery_date_start\').val();\r\n        ode = $(\'#data-recovery_date_end\').val();\r\n        ots = $(\'#data-recovery_time_start\').val();\r\n        ote = $(\'#data-recovery_time_end\').val();\r\n        \r\n        ds = ods.split(\'/\');\r\n        de = ode.split(\'/\');\r\n        \r\n        d_start = new Date(ds[1] + \"/\" + ds[0] + \"/\" + ds[2] + \" \" + ots);\r\n        d_end   = new Date(de[1] + \"/\" + de[0] + \"/\" + de[2] + \" \" + ote);\r\n        \r\n        d_diff = d_end - d_start\r\n        \r\n        total_diff_min = d_diff / 60000\r\n        \r\n        $(\'#data-recovery_time\').val(total_diff_min);\r\n    }\r\n    function update_recovery_non_official_time() {\r\n        ods = $(\'#data-recovery_non_official_date_start\').val();\r\n        ode = $(\'#data-recovery_non_official_date_end\').val();\r\n        ots = $(\'#data-recovery_non_official_time_start\').val();\r\n        ote = $(\'#data-recovery_non_official_time_end\').val();\r\n        \r\n        ds = ods.split(\'/\');\r\n        de = ode.split(\'/\');\r\n        \r\n        d_start = new Date(ds[1] + \"/\" + ds[0] + \"/\" + ds[2] + \" \" + ots);\r\n        d_end   = new Date(de[1] + \"/\" + de[0] + \"/\" + de[2] + \" \" + ote);\r\n        \r\n        d_diff = d_end - d_start\r\n        \r\n        total_diff_min = d_diff / 60000\r\n        \r\n        $(\'#data-recovery_non_official_time_min\').val(total_diff_min);\r\n    }\r\n    function update_duration_time() {\r\n        ods = $(\'#data-anesthetic_official_date_start\').val();\r\n        ode = $(\'#data-anesthetic_official_date_end\').val();\r\n        ots = $(\'#data-anesthetic_official_time_start\').val();\r\n        ote = $(\'#data-anesthetic_official_time_end\').val();\r\n        nds = $(\'#data-anesthetic_nonofficial_date_start\').val();\r\n        nde = $(\'#data-anesthetic_nonofficial_date_end\').val();\r\n        nts = $(\'#data-anesthetic_nonofficial_time_start\').val();\r\n        nte = $(\'#data-anesthetic_nonofficial_time_end\').val();\r\n        \r\n        ds = ods.split(\'/\');\r\n        de = ode.split(\'/\');\r\n        // ts = ots.split(\':\');\r\n        // te = ote.split(\':\');\r\n        \r\n        off_start = new Date(ds[1] + \"/\" + ds[0] + \"/\" + ds[2] + \" \" + ots);\r\n        off_end   = new Date(de[1] + \"/\" + de[0] + \"/\" + de[2] + \" \" + ote);\r\n        \r\n        ds = nds.split(\'/\');\r\n        de = nde.split(\'/\');\r\n        non_start = new Date(ds[1] + \"/\" + ds[0] + \"/\" + ds[2] + \" \" + nts);\r\n        non_end   = new Date(de[1] + \"/\" + de[0] + \"/\" + de[2] + \" \" + nte);\r\n        \r\n        off_diff = off_end - off_start\r\n        non_diff = non_end - non_start\r\n        \r\n        total_diff = off_diff + non_diff\r\n        total_diff_min = total_diff / 60000\r\n        \r\n        $(\'#data-anesthetic_duration\').val(total_diff_min);\r\n        $(\'#data-anesthetic_official_duration\').val(off_diff / 60000);\r\n        $(\'#data-anesthetic_non_official_duration\').val(non_diff / 60000);\r\n        // console.log(\"off_diff : \" + off_diff + \" : \" + (off_diff/60000));\r\n        // console.log(total_diff + \" [\" + total_diff/60000 + \"]\");\r\n        \r\n        // console.log(\"   official : \" + ods + \" \" + ots + \"...\" + ode + \" \" + ote + \" | \" + off_start + \"_\" + off_end);\r\n        // console.log(\"nonofficial : \" + nds + \" \" + nts + \"...\" + nds + \" \" + nte + \" | \" + non_start + \"_\" + non_end);\r\n    }\r\n    $(document).ready(function(){\r\n        // anesth time\r\n        $(\'#data-anesthetic_official_date_start\').change(update_duration_time);\r\n        $(\'#data-anesthetic_official_date_end\').change(update_duration_time);\r\n        $(\'#data-anesthetic_official_time_start\').change(update_duration_time);\r\n        $(\'#data-anesthetic_official_time_end\').change(update_duration_time);\r\n        $(\'#data-anesthetic_nonofficial_date_start\').change(update_duration_time);\r\n        $(\'#data-anesthetic_nonofficial_date_end\').change(update_duration_time);\r\n        $(\'#data-anesthetic_nonofficial_time_start\').change(update_duration_time);\r\n        $(\'#data-anesthetic_nonofficial_time_end\').change(update_duration_time);\r\n        tmp = $(\'#data-anesthetic_duration\').val();\r\n        if (tmp === \'\') {\r\n            $(\'#data-anesthetic_duration\').val(0);\r\n        }\r\n        \r\n        // recovery time\r\n        $(\'#data-recovery_date_start\').change(update_recovery_time);\r\n        $(\'#data-recovery_date_end\').change(update_recovery_time);\r\n        $(\'#data-recovery_time_start\').change(update_recovery_time);\r\n        $(\'#data-recovery_time_end\').change(update_recovery_time);\r\n        tmp = $(\'#data-recovery_time\').val();\r\n        if (tmp === \'\') {\r\n            $(\'#data-recovery_time\').val(0);\r\n        }\r\n        \r\n        // recovery non-official time\r\n        $(\'#data-recovery_non_official_date_start\').change(update_recovery_non_official_time);\r\n        $(\'#data-recovery_non_official_date_end\').change(update_recovery_non_official_time);\r\n        $(\'#data-recovery_non_official_time_start\').change(update_recovery_non_official_time);\r\n        $(\'#data-recovery_non_official_time_end\').change(update_recovery_non_official_time);\r\n        tmp = $(\'#data-recovery_non_official_time_min\').val();\r\n        if (tmp === \'\') {\r\n            $(\'#data-recovery_non_official_time_min\').val(0);\r\n        }\r\n        \r\n        console.log($(\'#data-anesthetic_nonofficial_time_start\').val());\r\n        <% if @current_role==\'developer\' %>\r\n        update_duration_time();\r\n        <% end %>\r\n    });\r\n</script>\r\n<script>\r\n// generate sumgroup script\r\n<%\r\nsumgroup = this.sumgroup\r\nif sumgroup != \'No service\'\r\n\r\n    doc_ready = \'\\n\'\r\n    sumgroup.each do |k, v|\r\n        ks = \'\' # select\r\n        kr = \'\' # radio\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \"// \" + k.to_s + \"\\n\"\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \'tmp_score = $(\"#data-\' + v[:total].to_s + \'\").val();\\n\'\r\n        doc_ready += \"if (tmp_score == \'\') { \\n  $(\'#data-\\\\#{v[:total].to_s}\').val(\'0\');\\n}\\n\"\r\n%>\r\n\r\n// ---\r\n// Generate for function <%= k %>\r\n// --- zam ---\r\n<%\r\n        if v[:select]\r\n            ks = k.to_s + \"_select\"\r\n            doc_ready += \"for (var i in \\\\#{ks}) {\\n\"\r\n            doc_ready += \"  f = \'#data-\' + \\\\#{ks}[i];\\n\"\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n%>\r\nvar <%= ks %> = [\"<%= v[:select].join(\'\",\"\').html_safe %>\"];\r\n<%\r\n        end\r\n        if v[:radio]\r\n            kr = k.to_s + \"_radio\"\r\n            doc_ready += \"for (var i in \\\\#{kr}) {\\n\"\r\n            doc_ready += \'  f = \"input[id^=\' + \"\'update_\" + \'\" + \' + \"\\\\#{kr}[i] + \" + \'\"\' + \"\']\" + \'\";\\n\'\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n            \r\n%>\r\nvar <%= kr %> = [\"<%= v[:radio].join(\'\",\"\').html_safe %>\"];\r\n<%\r\n        end\r\n%>\r\nfunction <%= k %>() {\r\n    sum = 0;\r\n    append = \"\";\r\n    letter = [];\r\n<% if v[:letter] %>\r\n    letter = <%= v[:letter].to_json.html_safe %>;\r\n<% end %>\r\n<% if v[:select] %>\r\n    for (var i in <%= ks %>) {\r\n        f = \"#data-\" + <%= ks %>[i];\r\n        v = $(f).val();\r\n        if (letter.indexOf(v) != -1) {\r\n            append = v;\r\n            continue;\r\n        }\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n<% if v[:radio] %>\r\n    for (var i in <%= kr %>) {\r\n        f = \"input[id^=\'update_\" + <%= kr %>[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n\r\n    console.log(\"<%= k %> = \" + sum);\r\n\r\n    $(\"#data-<%= v[:total] %>\").val(sum + \"\" + append);\r\n}\r\n<%\r\nend # end generate script\r\n%>\r\n\r\n$(document).ready(function(){\r\n    <%= doc_ready.html_safe %> \r\n});\r\n<%\r\nend\r\n%>\r\n// end generate sumgroup\r\n</script>',NULL,NULL,NULL,'2015-07-20 17:23:37','2015-07-20 17:23:37','form',''),(1692,'status_board_home',717,3,'<%\r\n    sample = false\r\n    if params[:sample] == \'true\'\r\n        sample = true\r\n    end\r\n    \r\n    date = Time.now\r\n    date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    # This model\r\n    model = get_model\r\n    \r\n    # map value\r\n    map_provider = {}\r\n    map_position = {}\r\n    map_or_room = {}\r\n    map_post_op = {}\r\n    map_ward = {}\r\n    map_instrument = {}\r\n    \r\n    map_or_room[\"\"]  = \"-\"\r\n    map_or_room[nil] = \"-\"\r\n    \r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:position].all do\r\n        map_position[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:or_room].all do\r\n        map_or_room[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:ward].all do\r\n        map_post_op[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:ward].all do\r\n        map_ward[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:instrument].all do\r\n        map_instrument[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    \r\n    m_app = model[:appointment]\r\n    \r\n    conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n    aps = m_app.all(conds)\r\n    aps = aps.sort_by{|i| [map_or_room[i[:or_room]], i[:start]]} if aps\r\n    list = []\r\n    list = aps.collect{|i|\r\n        r_pat_mod = m_pat_mod.where(:module_id=>i.id).first\r\n        if r_pat_mod\r\n            r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n            if r_pat\r\n                name = \"\\\\#{r_pat[:prefix_name]} \\\\#{r_pat[:first_name]}&nbsp;&nbsp&nbsp;\\\\#{r_pat[:last_name]}\".html_safe\r\n                \r\n                # age\r\n                today = Date.today\r\n                d = Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day)\r\n                age = d.year - r_pat[:birth_date].year - (d > today ? 1 : 0)\r\n                name += \" (\\\\#{age.to_s})\"\r\n                \r\n                {:time=>!i[:start].nil? ? i[:start].strftime(\'%H:%M\') : \'N/A\', :time_tf=>i[:time_tf], :status=>i[:status], :name=>name, :diagnosis=>i[:diagnosis], :operation=>i[:operation], :position=>map_position[i[:position]], :surgeon=>map_provider[i[:surgeon]], :assist=>map_provider[i[:assist]], :or_room=>map_or_room[i[:or_room]], :ward=>map_ward[i[:ward]], :post_op=>map_post_op[i[:post_op]], :instrument=>i[:instrument]}\r\n            end\r\n        end\r\n        # next\r\n        # r_pat_mod\r\n    }.compact\r\n    \r\n    # list = list.sort_by{|i| [map_or_room[i[:or_room]], i[:time]]}\r\n    \r\n    if sample\r\n        res = {}\r\n        res[:aps] = aps\r\n        res[:list] = list\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n         \r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<meta http-equiv=\"refresh\" content=\"60\" >\r\n<title>PATIENT STATUS</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml {\r\n\r\n  \r\n     }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px;  border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding:33px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   \r\n    font-family: Arial, Helvetica, sans-serif; color:#00