m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    # age\r\n    today = Date.today\r\n    d = Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day)\r\n    age = d.year - r_pat[:birth_date].year - (d > today ? 1 : 0)\r\n    \r\n\r\n    \r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n    \r\n#     liner_txt = \'\'\r\n#     head_txt = \'Metal\'\r\n#     tmp = this_rec[:bearing_surface_type]\r\n#     if tmp == \'1\' or tmp == \'5\'\r\n#         liner_txt = \'<v>Polyethylene</v> liner was placed.\'\r\n#     elsif tmp == \'3\' or tmp == \'6\'\r\n#         liner_txt = \'<v>X-Linked Polyethylene</v> liner was placed.\'\r\n#     elsif tmp == \'4\'\r\n#         liner_txt = \'<v>Ceramic</v> liner was placed.\'\r\n#     end\r\n#     if tmp == \'4\' or tmp == \'5\' or tmp == \'6\'\r\n#         head_txt = \'Ceramic\'\r\n#     end\r\n    \r\n#     screw_txt = \'\'\r\n#     if this_rec[:screws] == \'1\'\r\n#         screw_txt = \'Screws was used to reinforced cup placement.\'\r\n#     end\r\n    \r\n#     cement_txt = \'\'\r\n#     if this_rec[:cement] == \'1\'\r\n#         cement_txt = \'Femoral cannal was copiously irrigated and then suctioned it dry.  Cement technique was used to install final femoral component.\'\r\n#     else\r\n#         cement_txt = \'Cementless technique was used to install final femoral component.\'\r\n#     end\r\n\r\n#     txt = \"The patient was set in <v>\\\\#{render_value(\'position\')}</v> position. Skin incision was performed, and <v>\\\\#{render_value(\'approach\')}</v> approach was done.\r\n# Capsulotomy was done using Bovie cautery.\r\n# Femoral head was dislocated and removed.\r\n# Acetabulum was identified, osteophyte around the rim of the acetabulum was removed\r\n# Acetabulum component was prepared and placed in approximately 45 degrees of abduction and 10 to 15 degrees of anteversion.\r\n# Stability of the acetabular compoment was evaluated.<br/>\r\n# \\\\#{liner_txt} \\\\#{screw_txt} <br/>\r\n# Reamers and broaches were used to prepare femoral cannal.\r\n# Femoral component trial was used to evaluate for a appropriate press-fit.\r\n# Femoral component trial was then reduced into the acetabulum to test for appropriate neck length, tension, and range of motion as well as ligamentous stability.\r\n\r\n# After the appropriate femoral component has been confirmed, <v>\\\\#{cement_txt}</v> <br/>\r\n# <v>\\\\#{head_txt}</v> femoral head was assembled to the final femoral stem. \r\n# Finally, the hip was reduced, bleeding and instruments were checked.  And capsules and muscles were repaired respectively.\r\n# Vacuum drain was placed, and Skin were closed.\r\n# \".html_safe\r\n\r\n    m_provider = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#provider\", :patient_id=>r_pat.id).first\r\n    r_provider = model[:provider].find(m_provider[:module_id])\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        res[:pat_mod_provider] = m_provider\r\n        res[:provider] = r_provider\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n<html>\r\n\r\n<head>\r\n<meta http-equiv=Content-Type content=\"text/html; charset=utf-8\">\r\n<meta name=Generator content=\"Microsoft Word 14 (filtered)\">\r\n<style>\r\nv {\r\n    color : blue;\r\n}\r\n<!--\r\n /* Font Definitions */\r\n @font-face\r\n	{font-family:\"Cordia New\";\r\n	panose-1:2 11 3 4 2 2 2 2 2 4;}\r\n@font-face\r\n	{font-family:\"Cordia New\";\r\n	panose-1:2 11 3 4 2 2 2 2 2 4;}\r\n@font-face\r\n	{font-family:Calibri;\r\n	panose-1:2 15 5 2 2 2 4 3 2 4;}\r\n /* Style Definitions */\r\n p.MsoNormal, li.MsoNormal, div.MsoNormal\r\n	{margin-top:0in;\r\n	margin-right:0in;\r\n	margin-bottom:10.0pt;\r\n	margin-left:0in;\r\n	line-height:115%;\r\n	font-size:11.0pt;\r\n	font-family:\"Calibri\",\"sans-serif\";}\r\n.MsoChpDefault\r\n	{font-family:\"Calibri\",\"sans-serif\";}\r\n.MsoPapDefault\r\n	{margin-bottom:10.0pt;\r\n	line-height:115%;}\r\n@page WordSection1\r\n	{size:8.5in 11.0in;\r\n	margin:1.0in 1.0in 1.0in 1.0in;}\r\ndiv.WordSection1\r\n	{page:WordSection1;}\r\n-->\r\n</style>\r\n\r\n</head>\r\n\r\n<body lang=EN-US>\r\n\r\n	<div class=WordSection1>\r\n\r\n		<!--<p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;-->\r\n		<!--text-align:center;line-height:normal\'><span style=\'font-size:20.0pt\'>OPERATIVE-->\r\n		<!--NOTE</span></p>-->\r\n		<% if logo %>\r\n		<table class=MsoTableGrid border=0 cellspacing=0 cellpadding=0\r\n		 style=\'border-collapse:collapse;border:none\'>\r\n		 <tr>\r\n		  <td width=100% valign=top style=\'width:6.2in;border:none windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  \r\n		<p class=MsoNormal align=left style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n		text-align:left;line-height:normal\'>\r\n		    <span style=\'font-size:20.0pt\'>OPERATIVE NOTE</span>\r\n		    <!--<span style=\"float:right\"><img src=\"/esm/taig/www/content/lgpgh01.png\" height=\"30px\"/></span>        -->\r\n		</p>\r\n		    </td>\r\n		    <td><span style=\"float:right\"><img src=\"/esm/taig/www/content/lgpgh01.png\" height=\"50px\"/></span>        </td>\r\n		    </tr>\r\n		    </table>\r\n		    \r\n		<% else %>\r\n		<p class=MsoNormal align=left style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n		text-align:left;line-height:normal\'>\r\n		 