1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><strong>Pre / Post operative diagnosis : </strong><v><%= render_value(\'indication_for_surgery\') %></v></p>\r\n		  </td>\r\n		 </tr>\r\n		 <!--<tr>-->\r\n		 <!-- <td width=638 colspan=3 valign=top style=\'width:6.65in;border:solid windowtext 1.0pt;-->\r\n		 <!-- border-top:none;padding:0in 5.4pt 0in 5.4pt\'>-->\r\n		 <!-- <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:-->\r\n		 <!-- normal\'>Post operative diagnosis : <v><%# this_rec[:post_operative_diag] %></v></p>-->\r\n		 <!-- </td>-->\r\n		 <!--</tr>-->\r\n		 <tr>\r\n		  <td width=638 colspan=3 valign=top style=\'width:6.65in;border:solid windowtext 1.0pt;\r\n		  border-top:none;padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><b>Operation :</b>&nbsp;&nbsp;<v><%= render_value(\'procedure\') %></v></p>\r\n		  </td>\r\n		 </tr>\r\n		 <tr>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border-top:none;border-left:\r\n		  solid windowtext 1.0pt;border-bottom:solid windowtext 1.0pt;border-right:\r\n		  none;padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  </td>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border:none;border-bottom:solid windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  </td>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border-top:none;border-left:\r\n		  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  </td>\r\n		 </tr>\r\n		 <tr>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border:solid windowtext 1.0pt;\r\n		  border-top:none;padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><b>Anesthesiologist</b></p>\r\n		  </td>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border:none;border-bottom:solid windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><b>Surgeon Assistant</b></p>\r\n		  </td>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border-top:none;border-left:\r\n		  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>  </p>\r\n		  </td>\r\n		 </tr>\r\n		 <tr>\r\n		  <td width=638 colspan=3 valign=top style=\'width:6.65in;border:solid windowtext 1.0pt;\r\n		  border-top:none;padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><b>Operative finding(s)</b></p>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>\r\n		    <br/>&nbsp;&nbsp;&nbsp;\r\n<%\r\n    if this_rec[:image].count > 0\r\n        x = 1\r\n        for i in this_rec[:image] do\r\n            if x <= 4\r\n%>\r\n		      <img src=\"https://emr-life.com/content/esm/taig/taig/content/knee1/image/<%= i %>.png?<%= i %>&thumb=1\"/>&nbsp;\r\n<%\r\n            end\r\n            x += 1\r\n        end\r\n    end\r\n%>\r\n		  </p>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  </td>\r\n		 </tr>\r\n		 <tr>\r\n		  <td width=638 colspan=3 valign=top style=\'width:6.65in;border:solid windowtext 1.0pt;\r\n  border-top:none;padding:0in 5.4pt 0in 5.4pt;height:256.0pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><b>Operative procedures, diagram, etc</b></p>\r\n		  \r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:normal;font-size:.7em\'>\r\n		    &nbsp;&nbsp;&nbsp;&nbsp;<%= this_rec[:operative_note].html_safe if this_rec[:operative_note] %>\r\n		  </p>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  \r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  </td>\r\n		 </tr>\r\n		</table>\r\n        <p></p>\r\n        <table class=MsoTableGrid border=0 cellspacing=0 cellpadding=0\r\n		 style=\'border-collapse:collapse;border:none\'>\r\n		 <tr>\r\n		  <td width=100% valign=top style=\'width:5.9in;border:none windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		       <p class=MsoNormal align=left style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n		            text-align:left;line-height:normal\'>\r\n		            <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>&nbsp;</p>\r\n    		        <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Signature : ……………………………………..</p>\r\n    		        <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Surgeon : <v><%= r_provider[:name] if r_provider %></v></p>\r\n    		        <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Printed date : <v><%= Time.now.strftime(\"%d/%m/%y %H:%M\") %></v></p>\r\n		        </p>\r\n		    </td>\r\n		    <td><span style=\"float:right\"><img src=\"/esm/taig/www/content/thks.png\" height=\"90px\"/></span>        </td>\r\n		    </tr>\r\n		</table>\r\n<!--\r\n        <div style=\"display:inline\">\r\n            <div style=\"float:left\">\r\n    		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>&nbsp;</p>\r\n    \r\n    		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Signature : ……………………………………..</p>\r\n    		\r\n    		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Surgeon : <v><%= r_provider[:name] if r_provider %></v></p>\r\n    \r\n    		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Printed date : <v><%= Time.now.strftime(\"%d/%m/%y %H:%M\") %></v></p>\r\n            </div>\r\n            <div style=\"float:right\">\r\n                <img src=\"/esm/taig/www/content/thks.png\" width=\"100px\"/>\r\n            </div>\r\n        </div>\r\n-->\r\n	</div>\r\n<script>\r\n    setTimeout(window.print(), 3500); \r\n    // window.print();\r\n</script>\r\n</body>\r\n\r\n</html>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2015-07-21 17:31:16','2015-07-21 17:31:16','print_pgh',''),(1695,'print_preop',714,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    # query patient_innovian\r\n    r_pat_inn = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id], :module_name=>\"\\\\#{@current_project.name}#patient_innovian\").first\r\n    r_inn = model[:patient_innovian].find(r_pat_inn[:module_id])\r\n    d_inn = get_document(\'patient_innovian\').fields\r\n    m_inn = {}\r\n    for i in d_inn do\r\n        col = i[:column_name]\r\n        if i[:lov]\r\n            lov = i[:lov].split(/[\\r\\n]+/)\r\n            kv = {}\r\n            for l in lov do\r\n                t = l.split(\'|\')\r\n                k = t[0].strip\r\n                v = t[1].strip\r\n                kv[k] = v\r\n            end\r\n            m_inn[col.to_sym] = kv\r\n        end\r\n    end\r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        res[:patient_innovian] = r_inn\r\n        res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:100px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n\r\n\r\n\r\n<style>\r\n    input {color:#380BBB;}\r\ninput[type=checkbox] + label {\r\n  color: #ccc;\r\n  font-style: italic;\r\n} \r\ninput[type=checkbox]:checked + label {\r\n  color: #f00;\r\n  font-style: normal;\r\n} \r\n</style>\r\n<div style=\"width:1000px; margin-left:auto; margin-right:auto; margin-top:0px;\">\r\n\r\n  <table width=\"100%\" border=\"0\" cellpadding=\"2\" cellspacing=\"2\">\r\n    <tr>\r\n      <td width=\"50%\" height=\"458\" valign=\"top\">\r\n      <center><img src=\"http://pni.go.th/pnigoth/wp-content/uploads/2009/05/LogoPrasatNew_02-300x212.jpg\" width=\"100px\" /><br />\r\n      Department of Anesthesology สป.75(3)<br />\r\n      Prasat Neurological institute<br />\r\n      Preanesthetic evaluation and medication record\r\n      <br /><br />\r\n      History</center><br />\r\n      Underlying disease\r\n      <br />\r\n<input type=\"checkbox\"  class=\"checkbxinput\"  name=\"checkbox4\" id=\"checkbox4\" />\r\nYes\r\n<input type=\"checkbox\" name=\"checkbox4\" id=\"checkbox4\" /> \r\nNo\r\n<br />\r\n<table width=\"100%\" border=\"0\">\r\n  <tr>\r\n    <td width=\"28%\">Underlying disease<br />\r\n      <input type=\"checkbox\" name=\"checkbox6\" id=\"checkbox6\" />\r\nYes\r\n<input type=\"checkbox\" name=\"checkbox6\" id=\"checkbox6\" />\r\nNo <br />\r\n<br />\r\nHabit \r\n<input type=\"checkbox\" name=\"checkbox10\" id=\"checkbox10\" />\r\nSmoking</td>\r\n    <td width=\"72%\"><input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nDM\r\n  <input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nHT\r\n<input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nTB\r\n<input type=\"checkbox\" name=\"checkbox2\" id=\"checkbox2\" />\r\nCOPD\r\n<input type=\"checkbox\" name=\"checkbox3\" id=\"checkbox3\" />\r\nAsthma<br />\r\n<input type=\"checkbox\" name=\"checkbox5\" id=\"checkbox5\" />\r\nHeart disease<br />\r\n<input type=\"checkbox\" name=\"checkbox7\" id=\"checkbox7\" />\r\nOther<br />\r\n<input type=\"checkbox\" name=\"checkbox8\" id=\"checkbox8\" />\r\nAlcohol\r\n<input type=\"checkbox\" name=\"checkbox9\" id=\"checkbox9\" />\r\nOther<input type=\"text\" name=\"textfield\" id=\"textfield\" />\r\n</td>\r\n  </tr>\r\n</table>\r\n<br />\r\n  Allergy Hx \r\n  <input type=\"text\" name=\"textfield2\" id=\"textfield2\" />\r\n  <br />\r\n  Family Hx \r\n  <input type=\"text\" name=\"textfield3\" id=\"textfield3\" />\r\n  <br />\r\n  LMP \r\n  <input type=\"text\" name=\"textfield4\" id=\"textfield4\" /> \r\n  Suspicious perg \r\n  <input type=\"checkbox\" name=\"checkbox11\" id=\"checkbox11\" />\r\n  Yes \r\n  <input type=\"checkbox\" name=\"checkbox12\" id=\"checkbox12\" />\r\nNo<br /> \r\nPrevious anesthesia \r\n<input type=\"checkbox\" name=\"checkbox13\" id=\"checkbox13\" />\r\nYes\r\n<input type=\"text\" name=\"textfield5\" id=\"textfield5\" />\r\n\r\n<input type=\"checkbox\" name=\"checkbox14\" id=\"checkbox14\" />\r\nNo<br />\r\nComplications \r\n<input type=\"checkbox\" name=\"checkbox15\" id=\"checkbox15\" />\r\nYes\r\n<input type=\"text\" name=\"textfield6\" id=\"textfield6\" />\r\n\r\n<input type=\"checkbox\" name=\"checkbox15\" id=\"checkbox16\" />\r\nNo<br />\r\nCurrent Medications<br /><textarea name=\"textarea\" id=\"textarea\" cols=\"45\" rows=\"2\"></textarea>\r\n<br />\r\nSystemic review<br />\r\nCNS\r\n<input type=\"checkbox\" name=\"checkbox16\" id=\"checkbox17\" />\r\nSeizure\r\n<input type=\"checkbox\" name=\"checkbox17\" id=\"checkbox18\" />\r\nWeakness\r\n<input type=\"checkbox\" name=\"checkbox18\" id=\"checkbox19\" />\r\n<input type=\"text\" name=\"textfield7\" id=\"textfield7\" />\r\n<br />\r\nCurrent status\r\n<input type=\"text\" name=\"textfield8\" id=\"textfield8\" />\r\n<br />\r\nCVS\r\n<input type=\"checkbox\" name=\"checkbox19\" id=\"checkbox20\" />\r\nPalpitation\r\n<input type=\"checkbox\" name=\"checkbox19\" id=\"checkbox21\" />\r\nEdema\r\n<input type=\"checkbox\" name=\"checkbox19\" id=\"checkbox22\" />\r\nChest pain \r\n<input type=\"checkbox\" name=\"checkbox20\" id=\"checkbox23\" />\r\n<input type=\"text\" name=\"textfield9\" id=\"textfield9\" />\r\n<br />\r\nCurrent status\r\n<input type=\"text\" name=\"textfield10\" id=\"textfield10\" />\r\n<br />\r\nRS\r\n<input type=\"checkbox\" name=\"checkbox21\" id=\"checkbox24\" />\r\nURI\r\n<input type=\"checkbox\" name=\"checkbox21\" id=\"checkbox25\" />\r\nDypanea\r\n<input type=\"checkbox\" name=\"checkbox21\" id=\"checkbox26\" />\r\n<input type=\"text\" name=\"textfield11\" id=\"textfield11\" />\r\n<br />\r\nCurrent status\r\n<input type=\"text\" name=\"textfield12\" id=\"textfield12\" />\r\n<br />\r\nGI\r\n<input type=\"checkbox\" name=\"checkbox22\" id=\"checkbox27\" />\r\nJaundice\r\n<input type=\"checkbox\" name=\"checkbox22\" id=\"checkbox29\" />\r\n<input type=\"text\" name=\"textfield13\" id=\"textfield13\" />\r\n<br />\r\nCurrent status\r\n<input type=\"text\" name=\"textfield13\" id=\"textfield14\" />\r\n<br /> \r\nGU\r\n\r\n<input type=\"checkbox\" name=\"checkbox23\" id=\"checkbox28\" />\r\nRenal failure\r\n<input type=\"checkbox\" name=\"checkbox23\" id=\"checkbox30\" />\r\n<input type=\"text\" name=\"textfield14\" id=\"textfield15\" />\r\n<br />\r\nCurrent status\r\n<input type=\"text\" name=\"textfield14\" id=\"textfield16\" />\r\n<br />\r\nCoag\r\n<input type=\"checkbox\" name=\"checkbox24\" id=\"checkbox31\" /> \r\nBleeding Tendency : Current ststus\r\n<input type=\"text\" name=\"textfield15\" id=\"textfield17\" />\r\n<br />\r\nHistory form \r\n<input type=\"checkbox\" name=\"checkbox25\" id=\"checkbox32\" />\r\nPatient\r\n<input type=\"checkbox\" name=\"checkbox25\" id=\"checkbox32\" />\r\nRelative\r\n<input type=\"checkbox\" name=\"checkbox25\" id=\"checkbox32\" />\r\nRecord<br />\r\n<center>\r\n  <br />\r\n  Physical Examination</center><br />\r\nWt\r\n<input name=\"textfield16\" type=\"text\" id=\"textfield18\" size=\"5\" />\r\nHt\r\n<input name=\"textfield17\" type=\"text\" id=\"textfield19\" size=\"5\" />\r\n(BMI\r\n<input name=\"textfield18\" type=\"text\" id=\"textfield20\" size=\"5\" />\r\n) GCS\r\n<input name=\"textfield19\" type=\"text\" id=\"textfield21\" size=\"5\" />\r\n<br />\r\nBP\r\n<input name=\"textfield20\" type=\"text\" id=\"textfield22\" size=\"5\" />\r\nHR\r\n<input name=\"textfield21\" type=\"text\" id=\"textfield23\" size=\"5\" />\r\nPR\r\n<input name=\"textfield22\" type=\"text\" id=\"textfield24\" size=\"5\" />\r\nT\r\n<input name=\"textfield23\" type=\"text\" id=\"textfield25\" size=\"5\" />\r\n<br />\r\nPsychological status \r\n<input type=\"checkbox\" name=\"checkbox26\" id=\"checkbox33\" />\r\nCalm\r\n<input type=\"checkbox\" name=\"checkbox26\" id=\"checkbox33\" />\r\nAnxious\r\n<input type=\"checkbox\" name=\"checkbox26\" id=\"checkbox33\" /> \r\nDepressed<br />\r\n<table width=\"100%\" border=\"0\">\r\n  <tr>\r\n    <td valign=\"top\">Airway</td>\r\n    <td valign=\"top\">Mallanpati grade</td>\r\n    <td valign=\"top\">\r\n      <input type=\"checkbox\" name=\"checkbox27\" id=\"checkbox34\" />\r\n    1\r\n    <input type=\"checkbox\" name=\"checkbox27\" id=\"checkbox35\" />\r\n    2\r\n    <input type=\"checkbox\" name=\"checkbox27\" id=\"checkbox36\" />\r\n3\r\n<input type=\"checkbox\" name=\"checkbox27\" id=\"checkbox37\" />\r\n4</td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Thyromental distance</td>\r\n    <td valign=\"top\">\r\n      <input type=\"checkbox\" name=\"checkbox28\" id=\"checkbox38\" />\r\n    &lt;6 cm.\r\n    <input type=\"checkbox\" name=\"checkbox28\" id=\"checkbox39\" />\r\n    &gt;6 cm. </td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Mouth opening</td>\r\n    <td valign=\"top\">\r\n      <input type=\"checkbox\" name=\"checkbox29\" id=\"checkbox40\" />\r\n    &lt;3 cm.\r\n    <input type=\"checkbox\" name=\"checkbox29\" id=\"checkbox41\" />\r\n    &gt;3 cm. </td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Patercy of nares</td>\r\n    <td valign=\"top\">\r\n      <input type=\"checkbox\" name=\"checkbox30\" id=\"checkbox42\" />\r\n    Yes\r\n    <input type=\"checkbox\" name=\"checkbox30\" id=\"checkbox43\" />\r\n    No</td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Promiment incisior</td>\r\n    <td valign=\"top\">\r\n      <input type=\"checkbox\" name=\"checkbox31\" id=\"checkbox44\" />\r\n    Yes\r\n    <input type=\"checkbox\" name=\"checkbox31\" id=\"checkbox45\" />\r\n    No</td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Limtation of neck monthy</td>\r\n    <td valign=\"top\">\r\n      <input type=\"checkbox\" name=\"checkbox32\" id=\"checkbox46\" />\r\n    Yes\r\n    <input type=\"checkbox\" name=\"checkbox32\" id=\"checkbox47\" />\r\nNo</td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">\r\nDiffcult ntubation expected</td>\r\n    <td valign=\"top\">\r\n      <input type=\"checkbox\" name=\"checkbox33\" id=\"checkbox48\" />\r\n    Yes\r\n    <input type=\"checkbox\" name=\"checkbox33\" id=\"checkbox49\" />\r\n    No</td>\r\n  </tr>\r\n  <tr>\r\n    <td valign=\"top\">&nbsp;</td>\r\n    <td valign=\"top\">Artificial airway</td>\r\n    <td valign=\"top\">\r\n      <input type=\"checkbox\" name=\"checkbox34\" id=\"checkbox50\" />\r\n    ETT\r\n    <input type=\"checkbox\" name=\"checkbox34\" id=\"checkbox51\" />\r\n    Tracheostory\r\n    <input type=\"checkbox\" name=\"checkbox35\" id=\"checkbox52\" />\r\n    None</td>\r\n  </tr>\r\n\r\n  \r\n</table></td>\r\n      <td width=\"50%\" valign=\"top\">HN: <v><%= r_pat[:hn] %></v>&nbsp;&nbsp;&nbsp;&nbsp; AN:............................<br />\r\n        NAME: <v><%= r_pat[:prefix] %><%= r_pat[:first_name] %>&nbsp;&nbsp;&nbsp;&nbsp;<%= r_pat[:last_name] %></v> Age:........<br />\r\n        SEX: <v><%= m_inn[:gender][r_pat[:gender]] %></v>&nbsp;&nbsp;&nbsp;&nbsp;WARD: <v>x<%# r_app[:ward] ? model[:ward].find(r_app[:ward]).name : \'-\' %></v><br />\r\n        <br />\r\n        <div style=\"border:1px solid #666; width:100%\">\r\n            Date : <v><%= Time.now.strftime(\"%d/%m/%y %H:%M\") %></v><br />\r\n            Diagnosis : <v><%= r_app[:diagnosis] ?  r_app[:diagnosis] : \'-\' %></v><br />\r\n            Purposed operation : <v><%= r_app[:operation] ?  r_app[:operation] : \'-\' %></v><br />\r\n            Patient Classification by Schedule \r\n        \r\n            <input type=\"checkbox\" name=\"checkbox\" id=\"checkbox\" /> P <input type=\"checkbox\" name=\"checkbox\" id=\"checkbox\" /> NP <input type=\"checkbox\" name=\"checkbox\" id=\"checkbox\" /> EP <input type=\"checkbox\" name=\"checkbox\" id=\"checkbox\" /> XP\r\n     \r\n        \r\n        \r\n        </div><br />\r\n        Ventitator support \r\n        <input type=\"checkbox\" name=\"checkbox36\" id=\"checkbox53\" />\r\n        Yes setting\r\n        <input type=\"text\" name=\"textfield24\" id=\"textfield26\" />\r\n        <input type=\"checkbox\" name=\"checkbox37\" id=\"checkbox54\" /> \r\n        No\r\n        <br />\r\n        <table width=\"100%\" border=\"0\">\r\n          <tr>\r\n            <td width=\"14%\">Dentures</td>\r\n            <td width=\"17%\">Full</td>\r\n            <td width=\"69%\">\r\n              <input type=\"checkbox\" name=\"checkbox38\" id=\"checkbox55\" />\r\nUpper\r\n<input type=\"checkbox\" name=\"checkbox38\" id=\"checkbox55\" />\r\nLower </td>\r\n          </tr>\r\n          <tr>\r\n            <td>&nbsp;</td>\r\n            <td>Partial</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox39\" id=\"checkbox56\" />\r\n              Upper\r\n              <input type=\"checkbox\" name=\"checkbox39\" id=\"checkbox56\" />\r\n              Lower</td>\r\n          </tr>\r\n        </table>\r\n        <table width=\"100%\" border=\"0\">\r\n          <tr>\r\n            <td width=\"26%\" height=\"28\">Crowns(O)</td>\r\n            <td width=\"74%\" rowspan=\"2\"><table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n              <tr>\r\n                <td>8</td>\r\n                <td>7</td>\r\n                <td>6</td>\r\n                <td>5</td>\r\n                <td>4</td>\r\n                <td>3</td>\r\n                <td>2</td>\r\n                <td>1</td>\r\n                <td bgcolor=\"#000\"></td>\r\n                <td align=\"right\">1</td>\r\n                <td align=\"right\">2</td>\r\n                <td align=\"right\">3</td>\r\n                <td align=\"right\">4</td>\r\n                <td align=\"right\">5</td>\r\n                <td align=\"right\">6</td>\r\n                <td align=\"right\">7</td>\r\n                <td align=\"right\">8</td>\r\n              </tr>\r\n              <tr>\r\n                <td colspan=\"17\" bgcolor=\"#000\" style=\"height:1px\"></td>\r\n                </tr>\r\n              <tr>\r\n                <td>8</td>\r\n                <td>7</td>\r\n                <td>6</td>\r\n                <td>5</td>\r\n                <td>4</td>\r\n                <td>3</td>\r\n                <td>2</td>\r\n                <td>1</td>\r\n                <td bgcolor=\"#000\"></td>\r\n                <td align=\"right\">1</td>\r\n                <td align=\"right\">2</td>\r\n                <td align=\"right\">3</td>\r\n                <td align=\"right\">4</td>\r\n                <td align=\"right\">5</td>\r\n                <td align=\"right\">6</td>\r\n                <td align=\"right\">7</td>\r\n                <td align=\"right\">8</td>\r\n              </tr>\r\n            </table></td>\r\n          </tr>\r\n          <tr>\r\n            <td>Loose teeth (x)</td>\r\n          </tr>\r\n        </table>\r\n        <br />\r\n        RS/CVS \r\n        <input type=\"text\" name=\"textfield25\" id=\"textfield27\" />\r\n        <br />\r\n        Abdomen/Extermities\r\n        <input type=\"text\" name=\"textfield26\" id=\"textfield28\" />\r\n        <br />\r\n        Neuro\r\n        <input type=\"text\" name=\"textfield27\" id=\"textfield29\" />\r\n        <br />\r\n        <center>\r\n          <br />\r\n        Laboratory Investigation</center>\r\n        <table width=\"100%\" border=\"0\">\r\n          <tr>\r\n            <td>&nbsp;</td>\r\n            <td>Normal</td>\r\n            <td>Abnormal</td>\r\n            <td>&nbsp;</td>\r\n          </tr>\r\n          <tr>\r\n            <td width=\"28%\">CBC</td>\r\n            <td width=\"12%\">\r\n              <input type=\"checkbox\" name=\"checkbox40\" id=\"checkbox57\" />\r\n            </td>\r\n            <td width=\"14%\">\r\n              <input type=\"checkbox\" name=\"checkbox41\" id=\"checkbox58\" />\r\n            </td>\r\n            <td width=\"46%\"><input name=\"textfield28\" type=\"text\" id=\"textfield30\" size=\"5\" />\r\n              HB/Hct\r\n              <input name=\"textfield29\" type=\"text\" id=\"textfield31\" size=\"5\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td>UA</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox42\" id=\"checkbox59\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox43\" id=\"checkbox60\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield30\" id=\"textfield32\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td>BS</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox44\" id=\"checkbox61\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox45\" id=\"checkbox62\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield31\" id=\"textfield33\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td>BUN/Cr.</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox46\" id=\"checkbox63\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox47\" id=\"checkbox64\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield32\" id=\"textfield34\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td>Electrotytes</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox48\" id=\"checkbox65\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox49\" id=\"checkbox66\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield33\" id=\"textfield35\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td>Coagulation Study</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox50\" id=\"checkbox67\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox53\" id=\"checkbox70\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield34\" id=\"textfield36\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td>HIV/VDRL</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox51\" id=\"checkbox68\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox52\" id=\"checkbox69\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield35\" id=\"textfield37\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td>CXR</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox54\" id=\"checkbox71\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox55\" id=\"checkbox72\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield36\" id=\"textfield38\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td>EKG</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox56\" id=\"checkbox73\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox57\" id=\"checkbox74\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield37\" id=\"textfield39\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td>Other</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox58\" id=\"checkbox75\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox59\" id=\"checkbox76\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield38\" id=\"textfield40\" /></td>\r\n          </tr>\r\n          <tr>\r\n            <td>&nbsp;</td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox61\" id=\"checkbox78\" />\r\n            </td>\r\n            <td>\r\n              <input type=\"checkbox\" name=\"checkbox60\" id=\"checkbox77\" />\r\n            </td>\r\n            <td><input type=\"text\" name=\"textfield39\" id=\"textfield41\" /></td>\r\n          </tr>\r\n        </table>        <br />\r\n        <center>Assessment/Preparation</center><br />\r\n        ASA Physical ststus \r\n        <input type=\"checkbox\" name=\"checkbox62\" id=\"checkbox79\" />\r\n        1\r\n        <input type=\"checkbox\" name=\"checkbox62\" id=\"checkbox80\" />\r\n        2\r\n        <input type=\"checkbox\" name=\"checkbox62\" id=\"checkbox81\" />\r\n3\r\n<input type=\"checkbox\" name=\"checkbox62\" id=\"checkbox82\" />\r\n4\r\n<input type=\"checkbox\" name=\"checkbox63\" id=\"checkbox83\" />\r\n5\r\n<input type=\"checkbox\" name=\"checkbox64\" id=\"checkbox84\" />\r\nE<br />\r\nProblem/Risks<br /><textarea name=\"textarea2\" id=\"textarea2\" cols=\"45\" rows=\"2\"></textarea>\r\n<br />\r\nAnesthetic plan\r\n<input name=\"textfield40\" type=\"text\" id=\"textfield42\" size=\"8\" /> \r\nBlood prepared \r\n<input name=\"textfield41\" type=\"text\" id=\"textfield43\" size=\"8\" />\r\n<br />\r\nSuggested prepation\r\n<input type=\"text\" name=\"textfield42\" id=\"textfield44\" />\r\n<br />\r\nPremedications\r\n<br /><textarea name=\"textarea3\" id=\"textarea3\" cols=\"45\" rows=\"2\"></textarea>\r\n<br />\r\nPost-op Pain Relief Plan\r\n<input type=\"text\" name=\"textfield43\" id=\"textfield45\" />\r\n<br />\r\nChecklists for informed education<br />\r\n<input type=\"checkbox\" name=\"checkbox65\" id=\"checkbox85\" />\r\nStaff name\r\n<input type=\"checkbox\" name=\"checkbox65\" id=\"checkbox85\" />\r\nPreanesth\r\n<input type=\"checkbox\" name=\"checkbox65\" id=\"checkbox85\" />\r\nAnesth\r\n<input type=\"checkbox\" name=\"checkbox65\" id=\"checkbox85\" />\r\nRecovery\r\n<input type=\"checkbox\" name=\"checkbox65\" id=\"checkbox86\" /> \r\nRisks\r\n<br />\r\n<input type=\"checkbox\" name=\"checkbox65\" id=\"checkbox87\" />\r\nInquiry\r\n<input type=\"checkbox\" name=\"checkbox66\" id=\"checkbox88\" />\r\nHeart educates\r\n<input type=\"checkbox\" name=\"checkbox67\" id=\"checkbox89\" /> \r\nOther\r\n<input type=\"text\" name=\"textfield44\" id=\"textfield46\" />\r\n<br />\r\nI have discussed the proposed anesthetic plan and possble alternatives with the<br />\r\n<input type=\"checkbox\" name=\"checkbox68\" id=\"checkbox90\" />\r\nPatient\r\n<input type=\"checkbox\" name=\"checkbox68\" id=\"checkbox90\" />\r\nParent\r\n<input type=\"checkbox\" name=\"checkbox68\" id=\"checkbox90\" />\r\nGuardian\r\n<input type=\"checkbox\" name=\"checkbox68\" id=\"checkbox90\" />\r\nNext of G<br />\r\nAnesthetist Name\r\n<input name=\"textfield45\" type=\"text\" id=\"textfield47\" size=\"10\" />\r\nAnesthetist Signature\r\n<input name=\"textfield46\" type=\"text\" id=\"textfield48\" size=\"10\" />\r\n<br />\r\n<br />\r\n<center>ข้าพเจ้าได้รับข้อมูลและมีโอกาสได้ซักถามเกี่ยวกับ<br />\r\nการให้ยาระงับความรู้สึกแล้ว<br /><br />\r\n.......................................<br />(...<v><%= r_pat[:prefix] %><%= r_pat[:first_name] %>&nbsp;&nbsp;&nbsp;&nbsp;<%= r_pat[:last_name] %></v>...)<br />\r\nผู้ป่วย....................</center></td>\r\n    </tr>\r\n  </table>\r\n</div>\r\n\r\n</body>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2015-07-22 15:33:56','2015-07-22 15:33:56','print_preop',''),(1696,'patient_record_bk',622,2,'<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n<div id=\"patient\">\r\n Loading ...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n\r\n<style>\r\n    .history-link {\r\n        background-color:#eeeeff;\r\n        border:1px solid #ccc;\r\n        width:100px;\r\n        display:inline-block;\r\n        text-align:center;\r\n        line-height: 1.5em;\r\n        border-collapse: collapse;\r\n        padding:5px;\r\n        border-bottom:0px;\r\n        font-size:0.9em;\r\n        border-radius: 5px;\r\n    }\r\n    \r\n    .history-link-active {\r\n        background-color:#9999ff;\r\n    }\r\n    \r\n    .form-link {\r\n        font-size:0.9em;\r\n        background-color:#eeffff;\r\n        border:1px solid #ccc;\r\n        width:100px;\r\n        display:inline-block;\r\n        text-align:center;\r\n        line-height: 1.5em;\r\n        border-collapse: collapse;\r\n        padding:5px;\r\n        border-right:0px;\r\n        \r\n        margin-bottom:5px;\r\n        border-radius: 5px;\r\n    }\r\n    .form-link-active {\r\n        background-color:#99cccc;\r\n    }\r\n    \r\n</style>\r\n\r\n\r\n\r\n<%\r\n\r\n \r\n name = @current_project.name\r\n \r\n aps = patient_module_model.all(:patient_id=>patient.id,:module_name=>/\\#{name}#/,:order=>\'date desc\')\r\n \r\n aps_map = {}\r\n form_map = {}\r\n \r\n app_model =  emr_models[:appointment]\r\n \r\n for i in aps\r\n    if i.module_name.index \'#appointment\' and s = i.id.to_s\r\n        \r\n        \r\n        appoint = app_model.find i.module_id\r\n        if appoint\r\n        aps_map[s] = {:i=>i,:a=>appoint,:m=>{},:date=>appoint.date } unless aps_map[s]\r\n        end\r\n        \r\n    end\r\n end\r\n\r\n for i in aps\r\n    if i.parent_id and s = i.parent_id.to_s\r\n        \r\n        aps_map[s][:m][i.module_name] = [] unless aps_map[s][:m][i.module_name]\r\n        aps_map[s][:m][i.module_name] << i\r\n        form_map[i.module_name] = [] unless form_map[i.module_name]\r\n        \r\n        form_map[i.module_name] << i\r\n\r\n    end\r\n end\r\n\r\n\r\n\r\n list = aps_map\r\n\r\n\r\n%>\r\n\r\n\r\n<div class=\"\" style=\"padding:10px;border:0px solid;padding-bottom:0px\">\r\n\r\n<div id=\"history-panel\" style=\"\">\r\n   \r\n   <span class=\"form-panel-list\" style=\"border:0px solid;width:120px;float:left\">\r\n    &nbsp;\r\n   </span>\r\n   \r\n   <% for i in aps_map.values.sort{|a,b| b[:date]<=>a[:date] } %>\r\n   \r\n   <a href=\"javascript:select_app(\'<%=i[:i].id %>\')\"><span id=\"<%=i[:i].id %>\" class=\"history-link\"><%=time_ago_in_words(i[:date])%><br/><%=i[:date].strftime(\'%d-%m-%y\')%></span></a>\r\n\r\n   <% end %> \r\n</div>\r\n\r\n<div style=\"border:0px solid\">\r\n   \r\n   \r\n   <div class=\"form-panel-list\" style=\"border:0px solid;width:110px;display:table-cell;padding-top:5px\">\r\n   \r\n   \r\n  <% for i in form_map.keys.sort\r\n    id = i.split(\'#\')[-1]\r\n    v = form_map[i]\r\n  %>\r\n   \r\n   <a href=\"javascript:select_form(\'<%= id %>\')\"><span id=\"<%=id%>\" class=\"form-link\"><%=id.humanize%><br/>(<%=v.size%>)</span></a>\r\n\r\n   <% end %> \r\n   \r\n    <div class=\"clear\"></div>\r\n   </div>\r\n\r\n   <div class=\"content-panel\" style=\"border:1px solid #ccc;width:100%;display:table-cell;vertical-align:top;padding:10px;width:700px\">\r\n\r\n  <!-- aps_map list -->\r\n  \r\n    <% for i in aps_map.values.sort{|a,b| b[:date]<=>a[:date] } \r\n    \r\n     pm = patient_module_model.where(\'module_id\'=>i[:a].id).first\r\n    \r\n    %>\r\n   \r\n   \r\n   <div id=\"p<%=i[:i].id%>\" class=\"history-panel\">\r\n   \r\n <h4>Visit : <%=i[:date]%></h4><hr/>\r\n   \r\n<table class=\"table table-striped table-bordered\" >\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\#{@current_project.name}#\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\#{i.time.strftime(\"%H:%M\") if i.time } - \\#{i.ref_number}\", \"../\\#{s.name.camelize}/show?id=\\#{i.id}&return=\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\#{s.name.camelize}/edit?id=\\#{i.id}&record_name=\\#{patient.hn}&return=\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\#{s.name.camelize}/create?patient_id=\\#{patient.id}&record_name=\\#{patient.hn}&parent_id=\\#{pm.id}&return=\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\#{s.name.camelize}/print?id=\\#{i.id}&return=\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<% \r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name\r\n%>\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n<% end %>\r\n\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n   \r\n          \r\n   </div>\r\n\r\n\r\n   <% end %>\r\n  \r\n  <!-- form_map list -->\r\n \r\n  <% for i in form_map.keys\r\n    id = i.split(\'#\')[-1]\r\n    v = form_map[i]\r\n  %>\r\n   \r\n<div id=\"p<%=id%>\" class=\"form-panel\">\r\n\r\n<h4><%=id.humanize%> : </h4><hr/>\r\n\r\n  \r\n    \r\n<table class=\"table table-striped table-bordered\" >\r\n<thead>\r\n<tr><th></th><th>Date</th><th></th></tr>\r\n</thead>\r\n<%  v.each_with_index do |i,index|\r\n    # id = i.split(\'#\')[-1]\r\n    # v = form_map[i]\r\n    pm = patient_module_model.find(i.parent_id)\r\n    ap = app_model.find(pm.module_id)\r\n%>\r\n<tr>\r\n\r\n<td><%= index+1  %>.</td>\r\n\r\n<td><%= ap.date  %></td>\r\n\r\n<td>\r\n<%= link_to \"\\#{ap.date.strftime(\"%d-%m-%Y\") if ap.date} - \\#{i.ref_number}\", \"../\\#{id.camelize}/show?id=\\#{i.id}&return=\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\#{id.camelize}/edit?id=\\#{i.id}&record_name=\\#{patient.hn}&return=\\#{request.fullpath}\" %>\r\n   \r\n</td>\r\n    \r\n</tr>\r\n<% end %>\r\n</table>\r\n\r\n   \r\n   </div>\r\n\r\n   <% end %> \r\n  \r\n\r\n   </div>\r\n    \r\n    \r\n \r\n</div>\r\n</div>\r\n\r\n\r\n<br/>\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n\r\n    \r\n    \r\n</div> <!--close content-->\r\n</div>\r\n</div>\r\n</div> <!--close rw-fluid-->\r\n\r\n\r\n\r\n<script>\r\n    \r\n    function select_app(id){\r\n        // alert(\"select_app \"+id)\r\n        $(\'.history-link\').removeClass(\'history-link-active\')\r\n        $(\'.form-link\').removeClass(\'form-link-active\')\r\n        $(\'.history-panel\').hide()\r\n        $(\'.form-panel\').hide()\r\n        \r\n        $(\'#\'+id).addClass(\'history-link-active\')\r\n        $(\'#p\'+id).show()\r\n        \r\n    }\r\n    \r\n    <% if pm %>\r\n    \r\n    select_app(\'<%=pm.id%>\')\r\n    \r\n    <% end %>\r\n    \r\n        \r\n    function select_form(id){\r\n        $(\'.history-link\').removeClass(\'history-link-active\')\r\n        $(\'.form-link\').removeClass(\'form-link-active\')\r\n        $(\'.history-panel\').hide()\r\n        $(\'.form-panel\').hide()\r\n\r\n\r\n        $(\'#\'+id).addClass(\'form-link-active\')\r\n        $(\'#p\'+id).show()       \r\n        //  alert(\"select_form \"+id)\r\n    }\r\n    \r\n    \r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<% Time.zone =  get_setting \'time_zone\' %>\r\n\r\n\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\" style=\"display:none\" >\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\#{@current_project.name}#\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\#{i.time.strftime(\"%H:%M\") if i.time } - \\#{i.ref_number}\", \"../\\#{s.name.camelize}/show?id=\\#{i.id}&return=\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\#{s.name.camelize}/edit?id=\\#{i.id}&record_name=\\#{patient.hn}&return=\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\#{s.name.camelize}/create?patient_id=\\#{patient.id}&record_name=\\#{patient.hn}&parent_id=\\#{pm.id}&return=\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\#{s.name.camelize}/print?id=\\#{i.id}&return=\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\" style=\"border:1px solid red\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\" >\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\#{@current_project.name}#\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\#{i.time.strftime(\"%H:%M\") if i.time } - \\#{i.ref_number}\", \"../\\#{s.name.camelize}/show?id=\\#{i.id}&return=\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\#{s.name.camelize}/edit?id=\\#{i.id}&record_name=\\#{patient.hn}&return=\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\#{s.name.camelize}/create?patient_id=\\#{patient.id}&record_name=\\#{patient.hn}&parent_id=\\#{pm.id}&return=\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\#{s.name.camelize}/print?id=\\#{i.id}&return=\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2015-07-24 16:34:30','2015-07-24 16:34:30','patient_record_bk',''),(1697,'patient_record',622,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<% \r\n    test = false\r\n    if @current_role == \'developer\' and test \r\n%>\r\n<pre>\r\n    Appointment : <%= ap.to_json.html_safe %><br/>\r\n</pre>\r\n<pre>\r\n    PatientModule : <%= pm.to_json.html_safe %>\r\n</pre>\r\n<% if params[:remove] == \'true\'\r\n    ap.destroy\r\n    pm.destroy\r\n%>\r\n<script>\r\n    window.location = \"index\"\r\n</script>\r\n<% end %>\r\n<% \r\n    if params[:update] == \'true\' \r\n        sname = @current_project.name + \"#\" + params[:sname]\r\n        app_id = params[:app_id]\r\n        \r\n        t_ap = emr_models[:appointment].find(app_id)\r\n        t_pm = patient_module_model.first(:module_id=>t_ap.id.to_s)\r\n        f_pm = patient_module_model.where(:module_name=>sname, :parent_id=>pm.id).first\r\n\r\n        # Move unnessesary record to another appointment_id and patient_id\r\n        # open record page that you need to move (f_pm), \r\n        # use parameter update=true&sname={your_service_name}&app_id={another_appointment}\r\n        \r\n        # if t_pm\r\n        #     f_pm.update_attributes :parent_id=>t_pm.id, :patient_id=>t_pm[:patient_id]\r\n        #     ap = t_ap\r\n        #     pm = t_pm\r\n        # end\r\n%>\r\n<pre>\r\n    AppointmentID : <%= t_pm.to_json.html_safe %><br/>\r\n    <!--ParentID : <%=  %><br/>-->\r\n    Service  : <%= sname %><br/>\r\n    TEST : <%= f_pm.to_json.html_safe %>\r\n</pre>\r\n<%\r\n    end\r\n%>\r\n\r\n<% end %>\r\n<br/>\r\n\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date) if i.date%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name if user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2015-07-24 16:50:56','2015-07-24 16:50:56','patient_record',''),(1698,'add_appointment',622,3,'<%\r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    m_pat = @ehr_model[:patient]\r\n    m_pat_mod = @ehr_model[:patient_module]\r\n\r\n    pat_list = \"40642\r\n590091\r\n7344\r\n186128\r\n71421\r\n336433\r\n281731\r\n188971\r\n323054\r\n139740\r\n535878\r\n114152\r\n84106\r\n261543\r\n472370\r\n416186\r\n298940\r\n65627\r\n21179\r\n209630\r\n258461\r\n328000\r\n687559\r\n652397\r\n39144\r\n318651\r\n58366\r\n410288\r\n281835\r\n302836\r\n231323\r\n369930\r\n160736\r\n344071\r\n237319\r\n137436\r\n46970\r\n58650\r\n26520\r\n320429\r\n330310\r\n209231\r\n32809\r\n324144\r\n28478\r\n606130\r\n206310\r\n201776\r\n118780\r\n326477\r\n11546\r\n28949\r\n48986\r\n52864\r\n281731\r\n41796\r\n71461\"\r\n    \r\n# https://mfer.emr-life.com/endo/Appointment/create?return=../Home/index&data%5Bdate%5D=25/07/2015&data%5Bprovider%5D=550324ee790f9b6fe800010f&data%5Bprocedure%5D=550029a1790f9b20b1000018&data%5Bdate%5D=25/7/2015&data%5Bstart%5D=8:00&data%5Bstop%5D=8:00&data%5Bhn%5D=55981\r\n\r\n    date = DateTime.parse(\'26/07/2015 8:00+7:00\')\r\n    prov_id = \'550324ee790f9b6fe800010f\'\r\n    proc_id = \'550029a1790f9b20b1000018\'\r\n    \r\n    app_date = date.strftime(\'%Y-%m-%d\')\r\n    app_time = date.strftime(\'%H:%M\')\r\n    \r\n    model = get_model\r\n    m_app = model[:appointment]\r\n    \r\n    map_pat = {}\r\n    l_pat = pat_list.split(\' \')\r\n    for i in l_pat do\r\n        hn = \"2-\" + i\r\n        rs = m_pat.where(:hn=>hn).first\r\n        \r\n        # if rs.count == 1\r\n            # r_pat = rs[0]\r\n            r_pat = rs\r\n            # r_app = m_app.create :date=>app_date, :start=>app_time, :stop=>app_time, :procedure=>proc_id, :provider=>prov_id, :status=>\'Appointed\'\r\n            # r_pat_mod = m_pat_mod.create :module_id=>r_app.id, :module_name=>\"\\\\#{@current_project.name}#appointment\", :patient_id=>r_pat.id\r\n            # map_pat[hn] = {:appointment=>r_app, :patient_module=>r_pat_mod}\r\n        # else\r\n        #     map_pat[hn] = rs\r\n        # end\r\n        \r\n        # if r_pat\r\n    end\r\n    \r\n    res = {}\r\n    res[:date] = date.strftime(\'%Y-%m-%d\')\r\n    res[:time] = date.strftime(\'%H:%M\')\r\n    res[:patient_list] = map_pat\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-07-24 16:56:29','2015-07-24 16:56:29','add_appointment',''),(1701,'total_status',622,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n    <%= javascript_include_tag \"application\"  %>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>STATUS</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml {}\r\n\r\nvalue {font-size:0.9em;padding:0px;border:0px solid;}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px;  border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /*