radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#000;font-weight:bold;\r\n    font-size: 1em;\r\n}\r\n\r\ntable.table {\r\n    \r\n    color: #666;\r\n    font-size: 2em;\r\n    -moz-border-radius: 3px;\r\n    -moz-box-shadow: 0 1px 2px #d1d1d1;\r\n    -webkit-border-radius: 3px;\r\n    -webkit-box-shadow: 0 1px 2px #d1d1d1;\r\n    background: #eaebec;\r\n    border: #ccc 1px solid;\r\n    border-radius: 3px;\r\n    box-shadow: 0 1px 2px #d1d1d1;\r\n    font-family: Arial, Helvetica, sans-serif;\r\n    text-shadow: 1px 1px 0px #fff;\r\n}\r\n\r\ntable.table tr.even td {\r\n    background: #f6f6f6;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#f8f8f8), to(#f6f6f6));\r\n    background: -moz-linear-gradient(top, #f8f8f8, #f6f6f6);\r\n}\r\n\r\ntable.table th {\r\n    padding: 5px ;\r\n    font-size:0.9em;\r\n    border-bottom: 1px solid #e0e0e0; border-top: 1px solid #fafafa;\r\n    background: #ededed;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#ededed), to(#ebebeb));\r\n    background: -moz-linear-gradient(top, #ededed, #ebebeb);\r\n}\r\n\r\ntable.table th:first-child {\r\n    //padding-left: 20px;\r\n    text-align: center\r\n}\r\n\r\ntable.table a:visited {\r\n    color: #999999;\r\n    font-weight: bold;\r\n    text-decoration: none\r\n}\r\n\r\ntable.table a:active,\r\ntable.table a:hover {\r\n    color: #bd5a35;\r\n    text-decoration: underline\r\n}\r\n\r\ntable.table a:link {\r\n    color: #666;\r\n    font-weight: bold;\r\n    text-decoration: none\r\n}\r\n\r\ntable.table tr {\r\n    padding-left: 20px;\r\n    text-align: center\r\n}\r\n\r\ntable.table tr:first-child th:first-child {\r\n    -moz-border-radius-topleft: 3px;\r\n    -webkit-border-top-left-radius: 3px;\r\n    border-top-left-radius: 3px;\r\n}\r\n\r\ntable.table tr:first-child th:last-child {\r\n    -moz-border-radius-topright: 3px;\r\n    -webkit-border-top-right-radius: 3px;\r\n    border-top-right-radius: 3px;\r\n}\r\n\r\ntable.table tr:last-child td {    border-bottom: 0 }\r\n\r\ntable.table tr:last-child td:first-child {\r\n    -moz-border-radius-bottomleft: 3px;\r\n    -webkit-border-bottom-left-radius: 3px;\r\n    border-bottom-left-radius: 3px;\r\n}\r\n\r\ntable.table tr:last-child td:last-child {\r\n    -moz-border-radius-bottomright: 3px;\r\n    -webkit-border-bottom-right-radius: 3px;\r\n    border-bottom-right-radius: 3px;\r\n}\r\n\r\ntable.table tr:hover td {\r\n    \r\n    background: #f2f2f2;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#f2f2f2), to(#f0f0f0));\r\n    background: -moz-linear-gradient(top, #f2f2f2, #f0f0f0);\r\n}\r\n\r\ntable.table tr td {\r\n    \r\n    padding: 0px;\r\n    border-bottom: 1px solid #e0e0e0; border-left: 1px solid #e0e0e0; border-top: 1px solid #ffffff;\r\n    background: #fafafa;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#fbfbfb), to(#fafafa));\r\n    background: -moz-linear-gradient(top, #fbfbfb, #fafafa);\r\n    border:1px solid;\r\n}\r\n\r\ntable.table tr td:first-child {\r\n    padding-left: 20px;\r\n    border-left: 0;\r\n}\r\n\r\n\r\n.Waiting{color:#ccc}\r\n.Preparing{color:#6cc}\r\n.Processing{color:#6c6}\r\n.Recovering{color:#cc6}\r\n.Completed{color:blue}\r\n\r\n    \r\n    \r\n</style>\r\n<body >\r\n\r\n<div class=\"wrapper\">\r\n\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\" style=\"width:100%\">\r\n<div class=\"span12\" style=\"width:100%\">\r\n\r\n\r\n\r\n<div id=\"endoscopy_nurse\" class=\"  portlet \" >\r\n<!--<img src=\'/esm/cusys/colorectal/login-logo-white.png\' width=\"400\" style=\"float:right;margin-top:-10px\"/>-->\r\n<a href=\"index\" target=\"_blank\"><img src=\"/esm/mfer/endo/tage_logo.jpg\" height=\"70px\" style=\"float:right;margin-top:-10px\"></a>\r\n<span>\r\n<b>สมาคมแพทย์ส่องกล้องทางเดินอาหารไทย</b>\r\n\r\n<div style=\"margin-top:10px\" id=\"table\">\r\n<div id=\"board\">\r\n</div>\r\n</div></div></div></div></div>\r\n<script>\r\nnumpage = 1;\r\npage = 0;\r\n\r\nfunction update(data){\r\n    \r\n}\r\n\r\nfunction executeQuery() {\r\n  $.ajax({\r\n    url: \'total_status_partial?page=\'+page,\r\n    success: function(data) {\r\n      //  alert(\"update\");\r\n      // do something with the return value here if you like\r\n      $(\'#board\').fadeOut(500, function(){\r\n      $(\'#board\').html(data);\r\n      })\r\n      $(\'#board\').fadeIn(500)\r\n    }\r\n  });\r\n  setTimeout(executeQuery, 10000); // you could choose not to continue on failure...\r\n}\r\n\r\nfunction setPage(i){\r\n    page = i;\r\n   // alert(\"set to \"+i);\r\n}\r\n\r\n$(document).ready(function() {\r\n  // run the first time; all subsequent calls will take care of themselves\r\n  setTimeout(executeQuery, 0);\r\n});\r\n</script>\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2015-07-25 04:47:52','2015-07-25 04:47:52','total_status','*'),(1702,'total_status_partial',622,3,'<b>ประจำวันท่ี <%= Time.now.strftime(\"%d %B %Y\") %> <%=Time.now.strftime(\"%H:%M:%S\")%></b>\r\n<div class=\"clear\"></div>\r\n<%\r\n  npage = 9\r\n  page = 0 \r\n  page = params[:page].to_i if params[:page]\r\n  \r\n  \r\n  \r\n\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  params[:print] = {} unless params[:print]\r\n  date = Time.now\r\n\r\n  \r\n\r\n  if params[:print]  # and params[:print][:date]\r\n  \r\n \r\n  \r\n  params[:print][:date] = date.strftime(\"%d/%m/%Y\") unless params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id}).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\nappointments.collect!{|i| \r\n    \r\n    i if records[i.id]\r\n}.compact!\r\n\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n p = patients[i.patient_id]\r\n provider = providers[ap.provider.to_s]\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year} ปี \\\\#{month} เดือน \\\\#{day} วัน\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n \r\nif ap.status==\'Preparing\' or  ap.status==\'Processing\' or ap.status==\'Recovering\' or  (ap.status==\'Completed\' and ( Time.now - ap.updated_at ) < 300)\r\napdate = \'\'\r\napdate = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\nstarttime = \'\'\r\nstoptime = \'\'\r\nstarttime = ap.start.strftime(\" %H:%M\") if ap.start\r\nstoptime = ap.stop.strftime(\" %H:%M\") if ap.stop\r\n    {\'id\'=>ap.id,\r\n    \'status\'=>ap.status ,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'updated_at\'=>ap.updated_at,\r\n    \'procedure\'=>pro[ap.procedure],\r\n    \'date\'=>apdate,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider ? provider.name : \'N/A\',\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p }\",\r\n    \'start\'=>apdate+starttime,\r\n    \'end\'=>apdate+stoptime,\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'age\'=>age,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\n}.compact\r\n\r\nlist = json_data.sort{|a,b| b[\'updated_at\']<=>a[\'updated_at\']}\r\n\r\ntotal_page =  (list.size.to_f/npage).ceil\r\n%>\r\n<%#total_page%>\r\n<%\r\nif page>=total_page-1\r\ntopage = 0\r\nelse\r\ntopage = page +1\r\nend\r\n\r\nlist = list[page*npage..(page+1)*npage-1]\r\n\r\n\r\n\r\n\r\n \r\n%>\r\n         \r\n<%\r\n    model = get_model\r\n    m_fibo = model[:fibroscan]\r\n    m_colo = model[:colono]\r\n    m_gast = model[:gastro]\r\n    \r\n    date = Time.now\r\n    a_fibo = m_fibo.where({:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day}).all\r\n    a_colo = m_colo.where({:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day}).all\r\n    a_gast = m_gast.where({:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day}).all\r\n\r\n    \r\n%>\r\n\r\n<br/>\r\n<div style=\"font-size:36px\">ผู้ป่วยนัดหมายทั้งหมด : <%= appointments.count %> คน</div>\r\n\r\n<br/>\r\n<table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" class=\"table\">  \r\n    <tr>\r\n        <th>Operative</th>\r\n        <th width=\"60%\">Total</th>\r\n    </tr>\r\n    <tr>\r\n        <td>Fibroscan</td>\r\n        <td><%= a_fibo.count %></td>\r\n    </tr>\r\n    <tr>\r\n        <td>Colono</td>\r\n        <td><%= a_colo.count %></td>\r\n    </tr>\r\n    <tr>\r\n        <td>Gastro</td>\r\n        <td><%= a_gast.count %></td>\r\n    </tr>\r\n</table>\r\n<!--\r\n <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" class=\"table\">  \r\n \r\n <tr>\r\n    <th>No.</th>\r\n    <th>H/N</th>\r\n    <th>ชื่อ</th>\r\n    <th>Status</th>\r\n </tr>         \r\n<% list.each_with_index do |i,index|  %>\r\n <tr >  \r\n<td style=\"height:none\"><value><%=index+1+page*npage%>.</value></td> <td><value><%=i[\'hn\']%></value></td> <td><value><%=i[\'title\']%>  </value></td> <td><value class=\"<%=i[\'status\']%>\"><%=i[\'status\']%></value></td> \r\n </tr>     \r\n <% end %>\r\n</table>\r\n-->\r\n    \r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n	\r\n\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n<%\r\n   \r\n   link = \"status_feed?page=\\\\#{topage}\"\r\n\r\n%>\r\n<script>\r\n    setPage(<%=topage%>);\r\n</script>\r\n<!--\r\n<script type=\"text/javascript\">\r\n  var timeout = setTimeout(\"location=\'<%=link%>\'\",10000);\r\n  function resetTimeout() {\r\n    clearTimeout(timeout);\r\n    timeout = setTimeout(\"location=\'<%=link%>\'\",10000);\r\n  }\r\n</script>\r\n-->\r\n<% end %>\r\n',NULL,NULL,NULL,'2015-07-25 04:58:51','2015-07-25 04:58:51','total_status_partial','*'),(1703,'create',640,2,'\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Create Patient</h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:10px;background:#eee\">\r\n<div >\r\n    <div class=\"document-border\" style=\"background:#fff\" >\r\n        \r\n\r\n<%= render :inline=>this.init %>\r\n<%\r\n\r\n  if request.post?\r\n      \r\n      p = params[:record]\r\n      return_url = params[:return]\r\n      \r\n      \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n      \r\n      patient = @patient_model.create p\r\n      \r\n      return_url += \'&obj_id=\'+patient.id.to_s\r\n      %>\r\n      <center><br/><br/>Patient has been created ... <br/><br/></center>\r\n      <meta http-equiv=\"refresh\" content=\"0; url=<%=return_url%>\" />\r\n      <%\r\n  else \r\n%>\r\n<%= form_for :record , :url=>\'../Patient/create\' do |f| %>\r\n<div id=\"132-F1376173358\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n<b>Personal Information</b>\r\n</div>\r\n\r\n<div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n<span class=\"\"><label>Hospital Number <span class=\"f_req\">*</span>  : </label></span>	\r\n<input