le.log(\"Key = \" + key);\r\n                    opt = \"<option value=\'\'></option>\";\r\n                    \r\n                    nn = \"#data-component_\" + key;\r\n                    vv = $(nn).val();\r\n                    $.each(val, function(k,v) {\r\n                        sel = \"\";\r\n                        arr = [];\r\n                        if (vv == v.id) {\r\n                            sel = \" selected=\'selected\'\";\r\n                            arr = v.size_list.split(\' \');\r\n                            // console.log(\'>> \' + vv);\r\n                            mm = \"#data-\" + size_list[component_list.indexOf(key)] + \"_size\";\r\n                            oo = \"\";\r\n                            xx = \"\";\r\n                            idx = component_list.indexOf(key);\r\n                            if (idx == 0) {\r\n                                xx = \"<%= @record[:femoral_size] %>\";\r\n                            } else if (idx == 1) {\r\n                                xx = \"<%= @record[:tibial_size] %>\";\r\n                            } else if (idx == 2) {\r\n                                xx = \"<%= @record[:patella_size] %>\";\r\n                            } else if (idx == 3) {\r\n                                xx = \"<%= @record[:polyethylene_size] %>\";\r\n                            }\r\n                            for (var i in arr) {\r\n                                if (arr[i] === xx) {\r\n                                    oo += \"<option value=\'\" + arr[i] + \"\'\" + sel + \">\" + arr[i] + \"</option>\";\r\n                                } else {\r\n                                    oo += \"<option value=\'\" + arr[i] + \"\'>\" + arr[i] + \"</option>\";\r\n                                }\r\n                                console.log(arr[i] + \' <-> \' + xx + (arr[i] == xx) + \"|\" + (arr[i] === xx));\r\n                            }\r\n                            $(mm).html(oo);\r\n                            console.log(\': \' + mm + \" (\" + xx + \")\" + oo);\r\n                        }\r\n                        opt += \"<option value=\'\" + v.id + \"\'\" + sel + \">\" + v.name + \"</option>\";\r\n                        \r\n                        tdata[v.id] = v.size_list;\r\n                    });\r\n                    $(nn).html(opt);\r\n                });\r\n            } \r\n        });\r\n    }\r\n    function update_component() {\r\n        url = \"../KneeComponent/get_component?id=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                $.each( data, function( key, val ) {\r\n                    console.log(\"Key = \" + key);\r\n                    opt = \"<option value=\'\'></option>\";\r\n                    $.each(val, function(k,v) {\r\n                        opt += \"<option value=\'\" + v.id + \"\'>\" + v.name + \"</option>\";\r\n                        tdata[v.id] = v.size_list;\r\n                    });\r\n                    $(\'#data-component_\' + key).html(opt);\r\n                });\r\n            } else {\r\n                opt = \"<option value=\'\'></option>\";\r\n                for (var i in component_list) {\r\n                    console.log(\"reset component <\" + i + \"> \" + component_list[i]);\r\n                    nn = \'#data-component_\' + component_list[i];\r\n                    $(nn).html(opt);\r\n                    // $(\'#data-component_femur\').html(opt);\r\n                    // $(\'#data-component_tibia\').html(opt);\r\n                    // $(\'#data-component_patella\').html(opt);\r\n                    // $(\'#data-component_polyethylene\').html(opt);\r\n                }\r\n                for (var i in size_list) {\r\n                    console.log(\"reset size <\" + i + \"> \" + size_list[i]);\r\n                    nn = \'#data-\' + size_list[i] + \"_size\";\r\n                    $(nn).html(opt);\r\n                    // $(\'#data-femoral_size\').html(opt);\r\n                    // $(\'#data-tibial_size\').html(opt);\r\n                    // $(\'#data-patella_size\').html(opt);\r\n                    // $(\'#data-polyethylene_size\').html(opt);\r\n                }\r\n            }\r\n        });\r\n        \r\n    }\r\n    function update_component_size() {\r\n        val = $(this).val();\r\n        if (val == \'\') {\r\n            return;\r\n        }\r\n        // alert(val);\r\n        if (!jQuery.isEmptyObject(tdata)) {\r\n            console.log(\"val = \" + tdata[val]);\r\n            arr = tdata[val].split(\' \');\r\n            opt = \"<option value=\'\'></option>\";\r\n            for (var i in arr) {\r\n                opt += \"<option value=\'\" + arr[i] + \"\'>\" + arr[i] + \"</option>\";\r\n            }\r\n            \r\n            nm = $(this)[0].name;\r\n            if (nm.indexOf(\'femur\') != -1) {\r\n                $(\'#data-femoral_size\').html(opt);\r\n            } else if (nm.indexOf(\'tibia\') != -1) {\r\n                $(\'#data-tibial_size\').html(opt);\r\n            } else if (nm.indexOf(\'patel\') != -1) {\r\n                $(\'#data-patella_size\').html(opt);\r\n            } else if (nm.indexOf(\'poly\') != -1) {\r\n                $(\'#data-polyethylene_size\').html(opt);\r\n            }\r\n        } else {\r\n            opt = \"<option value=\'\'></option>\";\r\n            $(\'#data-femoral_size\').html(opt);\r\n            $(\'#data-tibial_size\').html(opt);\r\n            $(\'#data-patella_size\').html(opt);\r\n            $(\'#data-polyethylene_size\').html(opt);\r\n        }\r\n    }\r\n    $(document).ready(function(){\r\n        val = $(\'#data-component_company\').val();\r\n        if (val != \'\') {\r\n            init_component();\r\n        }\r\n        // company\r\n        $(\'#data-component_company\').change(update_component);\r\n        // component\r\n        for (var i in component_list) {\r\n            cname = \'#data-component_\' + component_list[i];\r\n            $(cname).change(update_component_size);\r\n            console.log(cname);\r\n        }\r\n    });\r\n</script>\r\n<% if bmi %>\r\n<script>\r\n    \r\n    function bmi_update(){\r\n        weight = $(\'#data-weight\').val();\r\n        height = $(\'#data-height\').val();\r\n        weight = parseFloat(weight);\r\n        height = parseFloat(height)/100;\r\n        if(weight!=0&&height!=0){\r\n            bmi = weight/(height*height)\r\n            $(\'#data-bmi\').val(bmi.toFixed(2))\r\n        }\r\n                \r\n    }\r\n    \r\n    $(document).ready(function(){\r\n       \r\n       \r\n       $(\'#data-weight\').change(bmi_update);\r\n       $(\'#data-height\').change(bmi_update);\r\n       \r\n       \r\n       bmi_update();\r\n       \r\n    });\r\n    \r\n</script>\r\n<% end %>\r\n\r\n<%\r\n    if this.document_name.downcase.index(\'hip\')\r\n%>\r\n<script>\r\n// harris_hip_score\r\nvar hhs_select = [\'hhs_pain\', \'hhs_limp\', \'hhs_support\', \'hhs_distance_walked\', \'hhs_sit\', \'hhs_stairs\', \'hhs_put_on_shoes_and_socks\'];\r\nvar hhs_radio = [\'hhs_enter_public_transportation\']\r\nvar hhs_absence_group= [\'hhs_fixed_flexion_contracture\', \'hhs_fixed_abduction\', \'hhs_fixed_internal\', \'hhs_limb_length\'];\r\nvar hhs_motion_group = [\'hhs_flexion\', \'hhs_abduction\', \'hhs_adduction\', \'hhs_external_rotation\', \'hhs_internal_rotation\'];\r\nfunction hhs_score_update() {\r\n    txt = $(this).val();\r\n    num = isNaN(parseInt(txt)) ? 0 : parseInt(txt);\r\n    console.log(\"hip = \" + $(this).val());\r\n    \r\n    sum = 0;\r\n    // simple sum\r\n    for (var i in hhs_select) {\r\n        f = \"#data-\" + hhs_select[i];\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n    for (var i in hhs_radio) {\r\n        f = \"input[id^=\'update_\" + hhs_radio[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n    // Absence of Deformity (All yes = 4; Less than 4 =0)\r\n    abs = 0;\r\n    for (var i in hhs_absence_group) {\r\n        f = \"input[id^=\'update_\" + hhs_absence_group[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        abs += n;\r\n    }\r\n    if (abs == 4) {\r\n        sum += abs;\r\n    }\r\n    // Range of Motion (*indicate normal)\r\n    // Range of Motion Scale \r\n    // 211-300 (5)\r\n    // 161-210 (4)\r\n    // 101-160 (3)\r\n    // 61-100 (2)\r\n    // 31-60 (1)\r\n    // 0-30 (0)\r\n    mot = 0;\r\n    sum_m = 0;\r\n    for (var i in hhs_motion_group) {\r\n        f = \"#data-\" + hhs_motion_group[i];\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        if (f.indexOf(\'flexion\') != -1) {\r\n            if (n > 140) {\r\n                n = 140;\r\n            }\r\n        } else {\r\n            if (n > 40) {\r\n                n = 40;\r\n            }\r\n        }\r\n        sum_m += n;\r\n    } \r\n		if (sum_m >= 211 && sum_m <= 300) {\r\n            mot = 5;\r\n        } else if (sum_m >= 161 && sum_m <= 210) {\r\n            mot = 4;\r\n        } else if (sum_m >= 101 && sum_m <= 160) {\r\n            mot = 3;\r\n        } else if (sum_m >= 61 && sum_m <= 100) {\r\n            mot = 2;\r\n        } else if (sum_m >= 31 && sum_m <= 60) {\r\n            mot = 1;\r\n        } else {\r\n            mot = 0;\r\n        }\r\n    \r\n    sum += mot;\r\n    \r\n    console.log(\"[HHS] SUMATION = \" + sum);\r\n    \r\n    $(\"#data-hhs_total_range_of_motion\").val(sum_m);\r\n    $(\"#data-hhs_hip_score\").val(sum);\r\n}\r\n\r\n$(document).ready(function(){\r\n    // ----\r\n    // harris_hip_score\r\n    // ----\r\n    kn_score = 0;\r\n    tmp_score = $(\"#data-hhs_hip_score\").val();\r\n    if (tmp_score != \'\') {\r\n        kn_score = tmp_score;\r\n    } else {\r\n        $(\"#data-hhs_hip_score\").val(\"0\");\r\n    }\r\n    tmp_score = $(\"#data-hhs_total_range_of_motion\").val();\r\n    if (tmp_score != \'\') {\r\n        kn_score = tmp_score;\r\n    } else {\r\n        $(\"#data-hhs_total_range_of_motion\").val(\"0\");\r\n    }\r\n    \r\n    for (var i in hhs_select) {\r\n        f = \"#data-\" + hhs_select[i];\r\n        $(f).change(hhs_score_update);\r\n    }\r\n    for (var i in hhs_radio) {\r\n        f = \"input[id^=\'update_\" + hhs_radio[i] + \"\']\";\r\n        $(f).change(hhs_score_update);\r\n    }\r\n    for (var i in hhs_absence_group) {\r\n        f = \"input[id^=\'update_\" + hhs_absence_group[i] + \"\']\";\r\n        $(f).change(hhs_score_update);\r\n    }\r\n    for (var i in hhs_motion_group) {\r\n        f = \"#data-\" + hhs_motion_group[i];\r\n        $(f).change(hhs_score_update);\r\n    }\r\n});\r\n</script>\r\n<%\r\n    end\r\n%>\r\n<%\r\n    if this.document_name.downcase.index(\'knee\')\r\n%>\r\n<script>\r\n// womac_score\r\nvar w_radio = [\'womac_walk_on_flat\',\'womac_going_up_down_stair\',\'womac_night_pain\',\'womac_sitting_or_lying\',\'womac_standing_upright\',\'womac_knee_joint_stiffness_morning\',\'womac_knee_joint_stiffness_later_day\',\'womac_ascending_stairs\',\'womac_descending_stairs\',\'womac_rising_from_sitting\',\'womac_standing\',\'womac_bending_to_floor_pick_up_object\',\'womac_walking_on_flat\',\'womac_getting_in_out_of_car\',\'womac_going_shopping\',\'womac_putting_on_socks\',\'womac_raising_from_bed\',\'womac_taking_off_socks\',\'womac_lying_in_bed\',\'womac_getting_in_out_of_restroom\',\'womac_sitting\',\'womac_getting_on_off_toilet\',\'womac_heavy_domestic_duties\',\'womac_light_domestic_duties\'];\r\nfunction womac_score_update() {\r\n    txt = $(this).val();\r\n    num = isNaN(parseInt(txt)) ? 0 : parseInt(txt);\r\n    console.log(\"womac = \" + $(this).val());\r\n    \r\n    sum = 0;\r\n    for (var i in w_radio) {\r\n        f = \"input[id^=\'update_\" + w_radio[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n    $(\"#data-womac_total_womac_score\").val(sum);\r\n}\r\n\r\n//  knee_score\r\nvar kn_update = [\'kss_walking\',\'kss_stairs\',\'kss_anteroposterior\',\'kss_mediolateral\',\'kss_flexion_contracture\',\'kss_extension_lag\',\'kss_malalignment_standing_xray\',\'kss_pain_at_rest\'];\r\nvar kn_data = [\'kss_range_of_motion\'];\r\nfunction knee_score_update() {\r\n    txt = $(this).val();\r\n    num = isNaN(parseInt(txt)) ? 0 : parseInt(txt);\r\n    console.log(\"knee = \" + $(this).val());\r\n\r\n    sum = 0;\r\n    for (var i in kn_update) {\r\n        // f = \"#data-\" + kn_update[i];\r\n        // v = $(f).val();\r\n        f = \"input[id^=\'update_\" + kn_update[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        // console.log(\"[\" + f + \"] : \" + n);\r\n        sum += n;\r\n    }\r\n    for (var i in kn_data) {\r\n        f = \"#data-\" + kn_data[i];\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        console.log(\"[\" + f + \"] : \" + n);\r\n        if (n == 0) {\r\n        } else if (n <= 125) {\r\n            sum += Math.ceil( n / 5 );\r\n        } else {\r\n            alert(\"Input range between 0 - 125 degree.\");\r\n            return;\r\n        }\r\n    }\r\n    console.log(\"[KSS] SUMATION = \" + sum);\r\n    $(\"#data-kss_total_knee_score\").val(sum);\r\n}\r\n\r\n$(document).ready(function(){\r\n    // ----\r\n    // womac_score\r\n    // ----\r\n    kn_score = 0;\r\n    tmp_score = $(\"#data-womac_total_womac_score\").val();\r\n    if (tmp_score != \'\') {\r\n        kn_score = tmp_score;\r\n    } else {\r\n        $(\"#data-womac_total_womac_score\").val(\"0\");\r\n    }\r\n    for (var i in w_radio) {\r\n        f = \"input[id^=\'update_\" + w_radio[i] + \"\']\";\r\n        $(f).change(womac_score_update);\r\n    }\r\n    \r\n    // ----\r\n    // knee_society_score\r\n    // ----\r\n    for (var i in kn_update) {\r\n        // console.log(\">> \" + \"input[id^=\'update_\" + kn_update[i] + \"]\");\r\n        $(\"input[id^=\'update_\" + kn_update[i] + \"\']\").change(knee_score_update);\r\n    }\r\n    for (var i in kn_data) {\r\n        $(\"#data-\" + kn_data[i]).change(knee_score_update);\r\n    }\r\n    \r\n    tmp_score = $(\"#data-kss_total_knee_score\").val();\r\n    if (tmp_score != \'\') {\r\n        kn_score = tmp_score;\r\n    } else {\r\n        $(\"#data-kss_total_knee_score\").val(\"0\");\r\n    }\r\n    console.log(\"kn_score = \" + kn_score + \", tmp_score = \" + tmp_score);\r\n});\r\n\r\n// generate script\r\n<%\r\nsumgroup = this.sumgroup\r\nif sumgroup != \'No service\'\r\n\r\n    doc_ready = \'\\n\'\r\n    sumgroup.each do |k, v|\r\n        ks = \'\' # select\r\n        kr = \'\' # radio\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \"// \" + k.to_s + \"\\n\"\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \'tmp_score = $(\"#data-\' + v[:total].to_s + \'\").val();\\n\'\r\n        doc_ready += \"if (tmp_score == \'\') { \\n  $(\'#data-\\\\#{v[:total].to_s}\').val(\'0\');\\n}\\n\"\r\n%>\r\n\r\n// ---\r\n// Generate for function <%= k %>\r\n// --- zam ---\r\n<%\r\n        if v[:select]\r\n            ks = k.to_s + \"_select\"\r\n            doc_ready += \"for (var i in \\\\#{ks}) {\\n\"\r\n            doc_ready += \"  f = \'#data-\' + \\\\#{ks}[i];\\n\"\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n%>\r\nvar <%= ks %> = [\"<%= v[:select].join(\'\",\"\').html_safe %>\"];\r\n<%\r\n        end\r\n        if v[:radio]\r\n            kr = k.to_s + \"_radio\"\r\n            doc_ready += \"for (var i in \\\\#{kr}) {\\n\"\r\n            doc_ready += \'  f = \"input[id^=\' + \"\'update_\" + \'\" + \' + \"\\\\#{kr}[i] + \" + \'\"\' + \"\']\" + \'\";\\n\'\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n            \r\n%>\r\nvar <%= kr %> = [\"<%= v[:radio].join(\'\",\"\').html_safe %>\"];\r\n<%\r\n        end\r\n%>\r\nfunction <%= k %>() {\r\n    sum = 0;\r\n<% if v[:select] %>\r\n    for (var i in <%= ks %>) {\r\n        f = \"#data-\" + <%= ks %>[i];\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n<% if v[:radio] %>\r\n    for (var i in <%= kr %>) {\r\n        f = \"input[id^=\'update_\" + <%= kr %>[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n\r\n    console.log(\"<%= k %> = \" + sum);\r\n\r\n    $(\"#data-<%= v[:total] %>\").val(sum);\r\n    $(\"#data-<%= v[:total] %>\").trigger(\'change\');\r\n}\r\n<%\r\nend # end generate script\r\n%>\r\n\r\nvar ans = [];\r\nfunction recreational_change() {\r\n    txt = $(this).val();\r\n    lbn = $(this).parent().text().trim();\r\n    console.log(\'recreational >>> \' + lbn);\r\n    \r\n    update_three_field(lbn);\r\n}\r\nfunction workout_change() {\r\n    txt = $(this).val();\r\n    lbn = $(this).parent().text().trim();\r\n    console.log(\'workout >>> \' + lbn);\r\n    \r\n    update_three_field(lbn);\r\n}\r\nfunction update_three_field(lbn) {\r\n    idx = ans.indexOf(lbn);\r\n    if (idx < 0) {\r\n        ans.push(lbn);\r\n    } else {\r\n        ans.splice(idx, 1);\r\n    }\r\n    \r\n    if (ans.length > 3) {\r\n        alert(\'More than 3 choices\');\r\n        return;\r\n    }\r\n    \r\n    process_updated_field();\r\n    console.log(ans);\r\n}\r\nfunction process_updated_field() {\r\n    for (var i = 0; i < 3; i++) {\r\n        x = i + 1;\r\n        f = \'#data-kss2_discretion_ans_\' + x;\r\n        d = \'#data-kss2_discretion_ch_\' + x;\r\n        a = \'#kss2_discretion_ch_\' + x\r\n        if (i < ans.length) {\r\n            t = x + \") \" + ans[i];\r\n            $(f).val(ans[i]);\r\n            $(a).children(\'span\').children(\'label\').text(t);\r\n        } else {\r\n            t = x + \") Activity\";\r\n            $(f).val(\'\');\r\n            // $(d + \" option[value]\").attr(\'selected\', \'selected\');\r\n            $(d + \" option:first-child\").attr(\'selected\', \'selected\');\r\n            $(a).children(\'span\').children(\'label\').text(t);\r\n            discretion_update();\r\n        }\r\n    }\r\n    \r\n    console.log(ans);\r\n}\r\n$(document).ready(function(){\r\n<%= doc_ready.html_safe %> \r\n\r\n    for (var i = 0; i < 3; i++) {\r\n        x = i + 1;\r\n        f = \'#data-kss2_discretion_ans_\' + x;\r\n        v = $(f).val();\r\n        if (v != \'\')\r\n            ans.push(v);\r\n    }\r\n    process_updated_field();\r\n    \r\n    $(\"input[id^=\'update_kss2_discretion_recreational\']\").change(recreational_change);\r\n    $(\"input[id^=\'update_kss2_discretion_workout\']\").change(workout_change);\r\n});\r\n<%\r\n    end\r\n%>\r\n</script>\r\n<!-- aaa -->\r\n<%\r\n    koos = {\"0\"=>\"100.000\",\r\n\"1\"=>\"91.975\",\r\n\"2\"=>\"84.600\",\r\n\"3\"=>\"79.914\",\r\n\"4\"=>\"76.332\",\r\n\"5\"=>\"73.342\",\r\n\"6\"=>\"70.704\",\r\n\"7\"=>\"68.284\",\r\n\"8\"=>\"65.994\",\r\n\"9\"=>\"63.776\",\r\n\"10\"=>\"61.583\",\r\n\"11\"=>\"59.381\",\r\n\"12\"=>\"57.140\",\r\n\"13\"=>\"54.840\",\r\n\"14\"=>\"52.465\",\r\n\"15\"=>\"50.012\",\r\n\"16\"=>\"47.487\",\r\n\"17\"=>\"44.905\",\r\n\"18\"=>\"42.281\",\r\n\"19\"=>\"39.625\",\r\n\"20\"=>\"36.931\",\r\n\"21\"=>\"34.174\",\r\n\"22\"=>\"31.307\",\r\n\"23\"=>\"28.251\",\r\n\"24\"=>\"24.875\",\r\n\"25\"=>\"20.941\",\r\n\"26\"=>\"15.939\",\r\n\"27\"=>\"8.291\",\r\n\"28\"=>\"0.000\"}\r\n%>\r\n<script>\r\n    var koos = <%= koos.to_json.html_safe %>; \r\n    function cal_bmi() {\r\n        w = $(\'#data-weight\').val();\r\n        h = $(\'#data-height\').val();\r\n        bmi = \'-\';\r\n        \r\n        if (w != \'\' && h != \'\') {\r\n            w = parseFloat(w);\r\n            h = parseFloat(h) / 100;\r\n            bmi = (w / (h * h)).toFixed(2);\