s  if cur_user %>\');\r\n        \r\n        // Pre-Operative ROM\r\n        $(\'#data-rom_flexion\').change(function(){\r\n            v = $(this).val();\r\n            vi = parseInt(v);\r\n            if (v != \'0\' && vi != 0) {\r\n                if (vi < 70) {\r\n                    $(\'#update_flexion_item_0\').attr(\'checked\', \'checked\');\r\n                } else if (vi >= 70 && vi < 90) {\r\n                    $(\'#update_flexion_item_1\').attr(\'checked\', \'checked\');\r\n                } else if (vi >= 90 && vi < 110) {\r\n                    $(\'#update_flexion_item_2\').attr(\'checked\', \'checked\');\r\n                } else if (vi > 110) {\r\n                    $(\'#update_flexion_item_3\').attr(\'checked\', \'checked\');\r\n                }\r\n            }\r\n        });\r\n        $(\'#data-rom_fixed_flexion\').change(function() {\r\n            v = $(this).val();\r\n            vi = parseInt(v);\r\n            if (v != \'0\' && vi != 0) {\r\n                if (vi < 10) {\r\n                    $(\'#update_fixed_flexion_deformity_item_0\').attr(\'checked\', \'checked\');\r\n                } else if (vi >= 10 && vi < 30) {\r\n                    $(\'#update_fixed_flexion_deformity_item_1\').attr(\'checked\', \'checked\');\r\n                } else if (vi >= 30) {\r\n                    $(\'#update_fixed_flexion_deformity_item_2\').attr(\'checked\', \'checked\');\r\n                } \r\n            }\r\n        });\r\n    });\r\n\r\n</script>\r\n<!-- end aaa -->\r\n<%\r\n    end\r\n%>\r\n\r\n',NULL,NULL,NULL,'2015-07-27 07:56:20','2015-07-27 07:56:20','form',''),(1708,'',757,1,'<%\r\n    model = get_model\r\n    m_company = model[:kcompany]\r\n    \r\n    res = {}\r\n    if params[:comp_id]\r\n        res[:comp_id] = params[:comp_id]\r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-07-27 07:58:16','2015-07-27 07:58:16','',''),(1709,'form',714,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f =