 sug) {\r\n                $(\'#\' + sug[i]).hide();\r\n            }\r\n        }\r\n\r\n        \r\n        $(\"input[type=\'radio\']\").click(function() {\r\n          var previousValue = $(this).attr(\'previousValue\');\r\n          var name = $(this).attr(\'name\');\r\n          var data = $(\'#\' + name.replace(\"update_\", \"data-\"));\r\n          \r\n          if (previousValue == \'checked\') {\r\n            $(this).removeAttr(\'checked\');\r\n            $(this).attr(\'previousValue\', false);\r\n            data.val(\"\");\r\n          } else {\r\n            $(\"input[name=\"+name+\"]:radio\").attr(\'previousValue\', false);\r\n            $(this).attr(\'previousValue\', \'checked\');\r\n          }\r\n        });\r\n    });\r\n\r\n\r\n\r\n\r\nfunction refresh_form(){\r\n\r\n wt = parseInt($(\"#data-wt\").val());\r\n ht = parseInt($(\"#data-ht\").val());\r\n \r\n $(\"#data-bmi\").val((wt/(ht*ht)*10000).toFixed(2));\r\n\r\n}\r\n\r\n$(\"#data-wt\").change(function(){\r\nrefresh_form();\r\n});\r\n$(\"#data-ht\").change(function(){\r\nrefresh_form();\r\n});\r\n\r\n</script>\r\n\r\n<!-- zam generate sumgroup -->\r\n<script>\r\n// generate script\r\n<%\r\nsumgroup = this.sumgroup\r\nif sumgroup != \'No service\'\r\n\r\n    doc_ready = \'\\n\'\r\n    sumgroup.each do |k, v|\r\n        ks = \'\' # select\r\n        kr = \'\' # radio\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \"// \" + k.to_s + \"\\n\"\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \'tmp_score = $(\"#data-\' + v[:total].to_s + \'\").val();\\n\'\r\n        doc_ready += \"if (tmp_score == \'\') { \\n  $(\'#data-\\\\#{v[:total].to_s}\').val(\'0\');\\n}\\n\"\r\n%>\r\n\r\n// ---\r\n// Generate for function <%= k %>\r\n// --- zam ---\r\n<%\r\n        if v[:select]\r\n            ks = k.to_s + \"_select\"\r\n            doc_ready += \"for (var i in \\\\#{ks}) {\\n\"\r\n            doc_ready += \"  f = \'#data-\' + \\\\#{ks}[i];\\n\"\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n%>\r\nvar <%= ks %> = [\"<%= v[:select].join(\'\",\"\').html_safe %>\"];\r\n<%\r\n        end\r\n        if v[:radio]\r\n            kr = k.to_s + \"_radio\"\r\n            doc_ready += \"for (var i in \\\\#{kr}) {\\n\"\r\n            doc_ready += \'  f = \"input[id^=\' + \"\'update_\" + \'\" + \' + \"\\\\#{kr}[i] + \" + \'\"\' + \"\']\" + \'\";\\n\'\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n            \r\n%>\r\nvar <%= kr %> = [\"<%= v[:radio].join(\'\",\"\').html_safe %>\"];\r\n<%\r\n        end\r\n%>\r\nfunction <%= k %>() {\r\n    sum = 0;\r\n    append = \"\";\r\n    letter = [];\r\n<% if v[:letter] %>\r\n    letter = <%= v[:letter].to_json.html_safe %>;\r\n<% end %>\r\n<% if v[:select] %>\r\n    for (var i in <%= ks %>) {\r\n        f = \"#data-\" + <%= ks %>[i];\r\n        v = $(f).val();\r\n        if (letter.indexOf(v) != -1) {\r\n            append = v;\r\n            continue;\r\n        }\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n<% if v[:radio] %>\r\n    for (var i in <%= kr %>) {\r\n        f = \"input[id^=\'update_\" + <%= kr %>[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n\r\n    console.log(\"<%= k %> = \" + sum);\r\n\r\n    $(\"#data-<%= v[:total] %>\").val(sum + \"\" + append);\r\n}\r\n<%\r\nend # end generate script\r\n%>\r\n\r\n$(document).ready(function(){\r\n    <%= doc_ready.html_safe %> \r\n});\r\n<%\r\nend\r\n%>\r\n\r\nfunction gfr_calculation(){\r\n    age = <%= age %>\r\n    f = <%= fgender %>\r\n    cr = $(\'#data-bun_cr_details\').val()\r\n    wt = $(\'#data-wt\').val()\r\n    \r\n    if(cr!=\"\"&&wt!=\"\"){\r\n        cr = parseFloat(cr)\r\n        wt = parseInt(wt)\r\n        gfr  =\'x\'\r\n        // gfr =Math.round( (140−age)*wt/72/cr*f)\r\n        gfr = Math.round((140-age)*wt/72/cr*f)\r\n        \r\n        $(\'#data-gfr_detail\').val(gfr)\r\n    }\r\n    \r\n}\r\n// end of sumgroup\r\n$(\'#data-wt\').change(gfr_calculation);\r\n\r\n$(\'#data-bun_cr_details\').change(gfr_calculation);\r\n\r\n$(\'#revised_cardiac_risk_index label:first\').each(function(){\r\n    o = $(this)\r\n    o.html(\'<a data-toggle=\"modal\" data-backdrop=\"static\" id=\"r1\" class=\"modal-btn\">\'+o.html()+\'</a>\')\r\n})\r\n\r\n$(\'#dvt_wells_score label:first\').each(function(){\r\n    o = $(this)\r\n    o.html(\'<a data-toggle=\"modal\" data-backdrop=\"static\" id=\"r2\" class=\"modal-btn\">\'+o.html()+\'</a>\')\r\n})\r\n\r\n$(\'#af_cha2ds2_vasc_score label:first\').each(function(){\r\n    o = $(this)\r\n    o.html(\'<a data-toggle=\"modal\" data-backdrop=\"static\" id=\"r3\" class=\"modal-btn\">\'+o.html()+\'</a>\')\r\n})\r\n\r\n$(\'#osa_stop_bang_score label:first\').each(function(){\r\n    o = $(this)\r\n    o.html(\'<a data-toggle=\"modal\" data-backdrop=\"static\" id=\"r4\" class=\"modal-btn\">\'+o.html()+\'</a>\')\r\n})\r\n\r\n$(\'.modal-btn\').click(function(){\r\n    \r\n    id = $(this).attr(\'id\')\r\n    $(\'#detail-img\').attr(\"src\",\"/esm/anes/pni/\"+id+\'.png\')\r\n    $(\'#detail-modal\').modal();\r\n    \r\n})\r\n\r\n\r\n</script>\r\n\r\n<div class=\"modal hide modal-lg\" id=\"detail-modal\" aria-hidden=\"false\" style=\"display: none;width:800px;margin-left:-400px\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3></h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n								\r\n                        <img id=\"detail-img\" src=\"/esm/anes/pni/r2.png\">\r\n\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n							</div>',NULL,NULL,NULL,'2015-07-28 10:21:58','2015-07-28 10:21:58','form',''),(1710,'document_name',758,1,'\'line_regimen\'',NULL,NULL,NULL,'2015-07-28 14:13:29','2015-07-28 14:13:29',NULL,NULL),(1711,'document_name',759,1,'\'ablative_techniques\'',NULL,NULL,NULL,'2015-07-28 14:19:20','2015-07-28 14:19:20',NULL,NULL),(1712,'document_name',760,1,'\'preop_tace\'',NULL,NULL,NULL,'2015-07-28 14:24:23','2015-07-28 14:24:23',NULL,NULL),(1713,'admin_page',717,2,'  <% if @current_role == \'admin\' or @current_role==\'developer\' %>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12 well\">\r\n						<center><h3>Admin Setting</h3><br />\r\n						\r\n						\r\n\r\n<a href=\"../Provider/index\">Manage Provider</a> | \r\n<a href=\"../OrRoom/index\">Manage OR Room</a> | \r\n<a href=\"../Ward/index\">Manage Ward</a> | \r\n<a href=\"../Position/index\">Manage Position</a> | \r\n<a href=\"../Instrument/index\">Manage Instrument</a>\r\n\r\n\r\n					</center> 	\r\n						\r\n	</div>\r\n</div>\r\n\r\n<% end %>  ',NULL,NULL,NULL,'2015-07-29 02:37:16','2015-07-29 02:37:16','admin_page',''),(1714,'form',751,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   \r\n   \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    model = get_model\r\n    map_or_room = {}\r\n    for i in model[:or_room].all do\r\n        map_or_room[i.id.to_s] = i[:name]\r\n    end\r\n    map_ward = {}\r\n    for i in model[:ward].all do\r\n        map_ward[i.id.to_s] = i[:name]\r\n    end\r\n    map_position = {}\r\n    for i in model[:position].all do\r\n        map_position[i.id.to_s] = i[:name]\r\n    end\r\n    map_postop = {}\r\n    for i in model[:post_op_ward].all do\r\n        map_postop[i.id.to_s] = i[:name]\r\n    end\r\n    map_provider = {}\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:parent_id])\r\n    pat_id = params[:patient_id]\r\n    m_app = model[:appointment]\r\n    \r\n    if !r_pat_mod\r\n        r_pat_mod = m_pat_mod.find(params[:id]) # patient_innovian\r\n        r_pat_mod = m_pat_mod.find(r_pat_mod[:parent_id])\r\n        pat_id = r_pat_mod[:patient_id]\r\n    end\r\n    \r\n    r_pat = m_pat.find(pat_id)\r\n    r_app = m_app.find(r_pat_mod[:module_id])\r\n    \r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    $(document).ready(function(){\r\n        $(\'#data-room\').val(\'<%= map_or_room[r_app[:or_room].to_s] %>\')\r\n        $(\'#data-hn\').val(\'<%= r_pat[:hn] %>\');\r\n        $(\'#data-public_id\').val(\'<%= r_pat[:public_id] %>\');\r\n        $(\'#data-birth_date\').val(\'<%= r_pat[:birth_date].strftime(\'%d/%m/%Y\') if r_pat[:birth_date] %>\');\r\n        $(\'#data-gender\').val(\'<%= r_pat[:gender] %>\').attr(\'selected\', true);\r\n    });\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2015-07-29 03:34:38','2015-07-29 03:34:38','form',''),(1715,'index2',717,2,'<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n		session[module_name]={:date=>params[:date]}\r\n	end\r\n	if session[module_name]\r\n		params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n		params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n%>fff\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n		width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list = %w{appointed waiting operation recovery icu ward home cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    # session[:s_provider] if session[:s_provider]\r\n    # session[:s_status] if session[:s_status]\r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n		s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n		s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n		date_text = s_date.strftime(\"%d/%m/%Y\")\r\n		session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n%>\r\n<%= error%>\r\n<%\r\n    session.delete :s_date\r\n    end\r\n%>\r\n<%\r\n    add_visit = \"../Appointment/create?return=../Home/index&data[date]=\\\\#{date_text}\"\r\n    search_patient = false\r\n    if p = params[:search]\r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n		s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n		s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n			search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\" style=\"font-size:3\">\r\n				<b>Home Patients : <%= date.strftime(\"%d/%m/%Y\") %></b>\r\n			</div>  \r\n			<div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n				<div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n					<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n						<!-- Search Form Start -->\r\n						<%=form_for :search,:url=>\'../Home/index\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n						<span class=\"field-data\"> \r\n							<label class=\"field-label\">Date :  </label>\r\n							<div class=\"field-input\" ><%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%></div>\r\n						</span>\r\n						\r\n							<span class=\"field-data\"> \r\n							<label class=\"field-label\">HN : </label>\r\n							<div class=\"field-input\"><%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%></div>\r\n						</span>\r\n						\r\n						\r\n							<%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n							\r\n							<%=link_to \'Advance Search\', \'javascript:doSearch()\', :class=>\'btn\' %>\r\n						\r\n						\r\n						<span class=\"field-data\"> \r\n							<label class=\"field-label\">&nbsp;</label> \r\n							<div class=\"field-input\">\r\n<%\r\n    \r\n    if s_provider \r\n        add_visit+= \"&data[provider]=\\\\#{s_provider}\" \r\n    end\r\n%>\r\n								<%#link_to (\"<i class=\'splashy-contact_blue_add\'></i> Add patient\").html_safe,add_visit, :class=>\'btn btn-info\',:style=>\'margin-top:10px\'%>\r\n							</div>\r\n						</span>\r\n						<div class=\"clear\"></div>\r\n						<% end %>\r\n						<!-- End Search Form -->\r\n					</div>\r\n				</div>\r\n\r\n<%\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n%>\r\n<%#params.inspect %><%#search_patient.inspect%>\r\n<%\r\n    if search_patient\r\n        \r\n		fields = {:hn=>s_hn, :first_name=>s_first_name}\r\n		keys = []\r\n%>\r\n<%#fields.inspect %>\r\n<%\r\n		fields.each_pair do |k,v| \r\n			keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n		end\r\n		if keys.size>0\r\n			criteria = {\'$or\'=>keys}\r\n		else\r\n			criteria ={}\r\n		end\r\n    \r\n		patients = patient_model.where(criteria).limit(20).all  \r\n		maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n		aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    else\r\n%>\r\n<%\r\n		conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n		\r\n		if s_provider and s_provider !=\'\'\r\n			conds.merge! :provider=>s_provider \r\n		end\r\n\r\n		if s_status and s_status != \"\"\r\n			conds.merge! :status=>s_status \r\n		end\r\n    \r\n		aps = ap_model.all(conds)\r\n%>\r\n<%\r\n    end\r\n    \r\n    map_or_room = {}\r\n    for m in get_model[:or_room].all do\r\n        map_or_room[m.id.to_s] = m[:name]\r\n    end\r\n         \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         \r\n        # additional for preop, postop\r\n        # m is a patient_module of appointment\r\n        # i is an appointment\r\n        pre_op = module_model.where(:module_name=>\"\\\\#{@current_project.name}#pre_anesthetic\", :parent_id=>m.id)\r\n        if pre_op.first\r\n            c[:pre_op] = \'<i class=\"splashy-check\"></i>\'\r\n        else\r\n            c[:pre_op] = \'<i class=\"splashy-remove_minus_sign\"></i>\'\r\n        end\r\n        \r\n        post_op = module_model.where(:module_name=>\"\\\\#{@current_project.name}#post_anesthetic\", :parent_id=>m.id)\r\n        c[:post_op] = \'<i class=\"splashy-remove_minus_sign\"></i>\'\r\n        if post_op.first\r\n            r_post_op = get_model[:post_anesthetic].find(post_op.first[:module_id])\r\n            if r_post_op[:alteration_e].to_s.strip != \'\' or r_post_op[:alteration_v].to_s.strip != \'\' or r_post_op[:alteration_m].to_s.strip != \'\'\r\n                c[:post_op] = \'<i class=\"splashy-check\"></i>\'\r\n            end\r\n        end\r\n        \r\n        c[:or_room] = map_or_room[i[:or_room]]\r\n        c[:time] = i[:start].strftime(\'%H:%M\')\r\n        \r\n        c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    # table_model = %w{date hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    table_model = %w{pre_op post_op or_room time date hn patient status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    \r\n    labels = {:no=>\'No.\', :or_room=>\'OR\', :time=>\'Time\', :pre_op=>\'Pre Anesth\', :post_op=>\'Post Anesth\', :date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\', :processing_ctrl=>\'Action\' }\r\n    \r\n%>\r\n<!--        \r\n        <div class=\"row-fluid\">\r\n            <div class=\"span12\">\r\n                <div class=\"alert alert-success\">\r\n                    Schedule Date : <%= date %>\r\n                </div>\r\n            </div>\r\n        </div>\r\n-->        \r\n        <div class=\"row-fluid\"></div>\r\n        <br/>\r\n        <!--<div align=\"left\" style=\"float:left;margin-left:5px\">-->\r\n        <!--    <%= link_to \'<i class=\"splashy-calendar_month\"></i> Operative Schedule\'.html_safe, \"print_table?date=\\\\#{date.strftime(\'%d/%m/%Y\')}\", :class=>\'btn btn-mini\', :target=>\'_blank\' %>-->\r\n        <!--    <%= link_to \'<i class=\"splashy-application_windows_share\"></i> Status Board\'.html_safe, \'status_board\', :class=>\'btn btn-mini\', :target=>\'_blank\' %>-->\r\n        <!--</div>-->\r\n        <div style=\"float:left;margin-left:5px\">\r\n            Operation Date : <span style=\"color:blue\"><%= date.strftime(\'%d/%m/%Y\') %></span>\r\n            <%=link_to (\"<i class=\'splashy-contact_blue_add\'></i> Add patient\").html_safe, add_visit, :class=>\'btn btn-mini btn-info\',:style=>\'margin-left:10px\'%>\r\n        </div>\r\n        <div align=\"right\" style=\"float:right;margin-right:5px\">\r\n            <%= link_to \'<i class=\"splashy-calendar_month\"></i> Operative Schedule\'.html_safe, \"print_table?date=\\\\#{date.strftime(\'%d/%m/%Y\')}\", :class=>\'btn btn-mini\', :target=>\'_blank\' %>\r\n            <%= link_to \'<i class=\"splashy-application_windows_share\"></i> Status Board\'.html_safe, \'status_board\', :class=>\'btn btn-mini\', :target=>\'_blank\' %>\r\n        </div>\r\n        \r\n        <br/>\r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl],:data=>aps,:labels=>labels do |row,out| \r\n                    out[0] = count.to_s+\".\"\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n\r\n        </div>\r\n        \r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nfunction change_status(obj){\r\n	if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n		window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	}\r\n}\r\n\r\n$(\"#today-date\").kendoDatePicker({\r\n	value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n    change: function(){\r\n		window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n	}\r\n});\r\n</script>\r\n<br/>\r\n<div class=\"clear\"></div>\r\n<%#session[module_name].inspect %>\r\n<%\r\n	if params[:obj_id]\r\n		now = Time.now \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n<% if false %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Encounter</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n\r\n    \r\n   \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Home Patients : <%= date %>\r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n<br/>\r\n<br/>\r\n<% end  %>\r\n\r\n\r\n\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n    \r\n    						<%=form_for :search,:url=>\'../Home/index\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n\r\n\r\n    \r\n    \r\n						<span class=\"field-data\"> \r\n							<label class=\"field-label\">Provider : </label>\r\n							<div class=\"field-input\">\r\n<% \r\n    \r\n	provider = models[:provider].where(:login=>@current_user.login).first\r\n    if provider\r\n%>\r\n<%= provider.name %>\r\n<%= f.hidden_field :provider, :value=>provider.id %>\r\n<% else %>\r\n<%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n<% end %>\r\n							</div>\r\n						</span>\r\n						<%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n						<span class=\"field-data\"> \r\n							<label class=\"field-label\">Status :  </label>\r\n							<div class=\"field-input\"><%= f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%></div>\r\n						</span>\r\n						<span class=\"field-data\"> \r\n							<label class=\"field-label\">Name :  </label>\r\n							<div class=\"field-input\"><%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%></div>\r\n						</span>\r\n						<span class=\"field-data\"> \r\n							<label class=\"field-label\">Surname : </label>\r\n							<div class=\"field-input\"><%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%></div>\r\n						</span>\r\n						<span class=\"field-data\"> \r\n							<label class=\"field-label\">HN : </label>\r\n							<div class=\"field-input\"><%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%></div>\r\n						</span>\r\n						<span class=\"field-data\"> \r\n							<label class=\"field-label\">Operatives : </label>\r\n							<div class=\"field-input\"><%= f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%></div>\r\n						</span>\r\n						<div class=\"clear\"></div>\r\n						<span class=\"field-data\"> \r\n							<label class=\"field-label\">&nbsp;</label> \r\n							<div class=\"field-input\">\r\n								<%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n								<!--<%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>-->\r\n							</div>\r\n						</span>\r\n    \r\n<% end %>    \r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n<div class=\"alert \">\r\n<% if false %>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n<% end %>\r\nCopyright 2015 - E.S.M.Solution Co.,Ltd.\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div>\r\n</div>\r\n<br/>\r\n<script>\r\n    \r\n    function doSearch(){\r\n          $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    }\r\n    \r\n</script>\r\n\r\n',NULL,NULL,NULL,'2015-07-29 16:17:08','2015-07-29 16:17:08','index2',''),(1716,'document_name',761,1,'\'company\'',NULL,NULL,NULL,'2015-07-30 01:19:51','2015-07-30 01:19:51',NULL,NULL),(1717,'document_name',762,1,'\'component\'',NULL,NULL,NULL,'2015-07-30 01:44:55','2015-07-30 01:44:55',NULL,NULL),(1718,'document_name',763,1,'\'knee_component\'',NULL,NULL,NULL,'2015-07-30 02:10:44','2015-07-30 02:10:44',NULL,NULL),(1719,'get_component',763,3,'<%\r\n    model = get_model\r\n    \r\n    id = params[:id] if params[:id]\r\n    \r\n    m_company = model[:company]\r\n    m_component = model[:knee_component]\r\n    a_component = m_component.where(:company=>id).all\r\n\r\n    res = {}\r\n    map_comp = {\"1\"=>:femur, \"2\"=>:tibia, \"3\"=>:polyethylene, \"4\"=>:patella};\r\n    \r\n    for i in a_component do\r\n        k = map_comp[i[:type]];\r\n        if !res.has_key? k\r\n            res[k] = []\r\n        end\r\n        res[k].push(i)\r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-07-30 07:46:54','2015-07-30 07:46:54','get_component','*'),(1720,'regenerate_pdf',674,2,'\r\n<%\r\n#   @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n    @models = get_model\r\n    \r\n    \r\n    list = @module_model.to_a\r\n    \r\n    for i in list\r\n    @patient_module = i\r\n\r\n    t = i.module_name.split(\'#\')\r\n    t[1] = \'dbe\' if t[1] == \'dobule_balloon_enteroscopy\' or t[1] == \'double_balloon_enteroscopy\'\r\n\r\n\r\n    # doc = @current_project.get_document t[1]\r\n    if t[0]==\'med\' and t[1]!=\'appointment\' and %w{gastro colono push_enteroscopy dbe sigmoid ercp eus}.index(t[1])\r\n        \r\n    m = @models[t[1].to_sym].collection.find({\'_id\'=>i.module_id},{:fields=>{\'endoscopist\'=>1}}).to_a[0]\r\n    if m and m[\'endoscopist\'] and m[\'endoscopist\']!=\'\'\r\n    \r\n    \r\n    url = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{t[0]}/\\\\#{t[1].camelize}/pdf?id=\\\\#{@patient_module.id}\"\r\n    attach_pdf = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{t[0]}/\\\\#{t[1].camelize}/attach_pdf?id=\\\\#{@patient_module.id}\"\r\n    \r\n    id = @patient_module.id.to_s\r\n    path = \"test\"\r\n    require_relative \'app/models/workers/pdf_generator\'\r\n    if params[:commit]\r\n    PdfGenerator.enqueue :url=>url,:id=>id,:path=>path,:return=>attach_pdf\r\n    end\r\n%>\r\n<li><%=i.created_at.strftime(\"%d-%m-%y\")%> <%=t[1]%>: <%= url%></li>\r\n<% end %>\r\n<% end %><% end %>',NULL,NULL,NULL,'2015-07-31 04:00:11','2015-07-31 04:00:11','regenerate_pdf',''),(1721,'form_xx',725,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%# render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<!--<h3>Create Patient</h3>-->\r\n<strong>Create Patient</strong>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n<div >\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\" >\r\n\r\n<%= render :inline=>this.initz %>\r\n<% # params.inspect %>\r\n<%\r\n\r\n    msg = nil\r\n    err = false\r\n    \r\n    models = get_model\r\n    all_provider = models[:provider].all\r\n    list_surgeon = all_provider.collect{|i| [i.id, i.name] if i[:provider_type]==\'1\' or i[:provider_type]==\'4\'}.compact!\r\n    list_assist = all_provider.collect{|i| [i.id, i.name] if i[:provider_type]==\'1\' or i[:provider_type]==\'4\'}.compact!\r\n    \r\n    m_appointment = models[:appointment]\r\n    m_patient_detail = models[:patient_detail]\r\n    \r\n\r\n    if request.post?\r\n      \r\n        p = params[:record]\r\n        p_app = params[:app]\r\n        return_url = params[:return]\r\n        date = Time.now\r\n        if !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        \r\n        # next_service = \"../Patient/create_test?return=\\\\#{return_url}&\".html_safe\r\n        next_service = \"../Home/index\"\r\n        patient = @patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Duplicate HN in database\"\r\n            # next_service += URI.escape(params.collect{|k,v| \"\\\\#{k}=\\\\#{v}\"}.join(\'&\')).html_safe\r\n            err = true\r\n        else\r\n            # msg = \"Success\"\r\n            # next_service = \"../Setting/index\"\r\n            patient = @patient_model.create p\r\n            # next_service = \'../Home/patient_record?id=\' + patient.id\r\n          \r\n            # if params[:record][:provider]\r\n            #     m_pm_record = @module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>params[:record][:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>params[:record][:provider]\r\n            # end\r\n            \r\n            msg = \"Patient created\"\r\n        end\r\n        \r\n        # create appointment\r\n        # rec_app = m_appointment.create :provider=>params[:surgeon], :date=>params[:appointed_date], :start=>params[:start], :status=>\'Appointed\'\r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = @module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>params[:record][:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id\r\n\r\n        # create patient_detail\r\n        # rec_pat = m_patient_detail.create :time=>params[:time], :diagnosis=>params[:diagnosis], :hospital_admit_date=>params[:admit_date], :height=>params[:height], :weight=>params[:weight], :allergies=>params[:allergies], :instrument=>params[:instrument], :procedure=>params[:procedure], :surgeon=>params[:surgeon], :assist=>params[:assist], :room=>params[:room], :bed=>params[:bed], :care_unit_days=>params[:care_unit_days], :position=>params[:position], :post_op=>params[:post_op]\r\n        # rec_pm_pat = @module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>params[:record][:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#patient_detail\", :module_id=>rec_pat.id, :parent_id=>rec_pm_app.id\r\n      \r\n    #   return_url += \'&obj_id=\'+patient.id.to_s\r\n      %>\r\n      <!--<%=params.inspect %>-->\r\n      <br/>\r\n      <!--Patient : <%= patient.inspect %><br/>-->\r\n      <!--Appointment : <%# rec_app.inspect %>...<%= rec_pm_app.inspect %><br/>-->\r\n      <!--Patient Detail : <%# rec_pat.inspect %>....<%# rec_pm_pat.inspect %><br/>-->\r\n      <div class=\"alert <%= err ? \"alert-error\" : \"alert-success\" %>\"><%= msg %></div>\r\n      <meta http-equiv=\"refresh\" content=\"0; url=<%=next_service%>\" />\r\n      <%\r\n    else\r\n%>\r\n<%= form_for :record , :url=>\'create\' do |f| %>\r\n<%= f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n<%= f.hidden_field :date, :value=>params[:data][:date] %>\r\n<div class=\"w-box\">\r\n<!--<div id=\"132-F1376173358\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">-->\r\n<div class=\"form-horizontal well\">\r\n<!--<b>Personal Information</b>-->\r\n<p class=\"f_legend\">Patient Information</p>\r\n<!--</div>-->\r\n\r\n<div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:1