>ด.ญ.</option>\r\n            </select>\r\n        </div>\r\n        <!--<input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n    </div>\r\n    <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n        <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n        <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n    </div>\r\n    <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n        <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n        <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n    </div>\r\n    <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Gender : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n                <option value=\"1\">ชาย</option>\r\n                <option value=\"2\">หญิง</option>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n<%\r\n\r\n    m_or_room = models[:or_room]\r\n    m_post_op_ward = models[:post_op_ward]\r\n    m_ward = models[:ward]\r\n    m_position = models[:position]\r\n    \r\n    l_or_room = m_or_room.all.collect{|i| [i.id, i.name]}\r\n    l_post_op = m_post_op_ward.all.collect{|i| [i.id, i.name]}\r\n    l_ward = m_ward.all.collect{|i| [i.id, i.name]}\r\n    l_position = m_position.all.collect{|i| [i.id, i.name]}\r\n%>\r\n    <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Birth date : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n            <script>\r\n            	$(\"#data-birth_date\").kendoDatePicker({\r\n            		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n            	});\r\n            </script>\r\n        </div>\r\n    </div>\r\n        <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Appointed Date : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n            <script>\r\n            	$(\"#data-date\").kendoDatePicker({\r\n            		value: \'<%= params[:data][:date] if params[:data][:date] %>\',\r\n            	});\r\n            </script>\r\n        </div>\r\n    </div>\r\n    <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Time TF : </label></span>\r\n        <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n            <span class=\"k-picker-wrap k-state-default\">\r\n                <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 00:26:20 +0700\" style=\"width: 100%;\" onkeypress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                    <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                </span>\r\n            </span>\r\n        </span>\r\n        <script>\r\n            $(\"#data-start\").kendoTimePicker({\r\n        	value: \'09:00\',\r\n        	interval: 10,\r\n        	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\"],\r\n        	change: function(event){\r\n        		var v = $(\'#data-start\').val()\r\n        		if(v.length==3){\r\n        			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n        		}\r\n        		 \r\n        	}\r\n        });\r\n        </script>\r\n	</div>\r\n<div class=\"clear\"></div>\r\n<hr/>\r\n    <div id=\"or_room\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Room : </label></span>	\r\n        <!--<input type=\"text\" name=\"room\" id=\"data-room\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[or_room]\" id=\"data-or_room\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n<%\r\n    for l in l_or_room do\r\n%>\r\n                <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"ward\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Ward : </label></span>	\r\n        <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[ward]\" id=\"data-ward\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n<%\r\n    for l in l_ward do\r\n%>\r\n                <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<!--    <div id=\"care_unit_days\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">-->\r\n<!--        <span class=\"\"><label>Care Unit Days : : </label></span>	-->\r\n<!--        <input type=\"text\" name=\"care_unit_days\" id=\"data-care_unit_days\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n<!--    </div>-->\r\n    \r\n<!--<div class=\"clear\"></div>-->\r\n\r\n    <div id=\"position\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Position : </label></span>	\r\n        <!--<input type=\"text\" name=\"position\" id=\"data-position\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[position]\" id=\"data-position\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n<%\r\n    for l in l_position do\r\n%>\r\n                <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"post_op\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Post-op : </label></span>	\r\n        <!--<input type=\"text\" name=\"post_op\" id=\"data-post_op\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[post_op]\" id=\"data-post_op\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n<%\r\n    for l in l_post_op do\r\n%>\r\n                <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"surgeon\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Surgeon : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[surgeon]\" id=\"data-surgeon\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_surgeon do\r\n%>\r\n                <option value=\"<%= prov[0] %>\"><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"assist\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Assist : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0