\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"diagnosis\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Diagnosis : </label></span>	\r\n        <input type=\"text\" name=\"app[diagnosis]\" id=\"data-diagnosis\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"operation\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Operation : </label></span>	\r\n        <input type=\"text\" name=\"app[operation]\" id=\"data-operation\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"instrument\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Instrument : </label></span>	\r\n        <textarea type=\"text\" name=\"app[instrument]\" id=\"data-instrument\" row=\"5\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\"></textarea>\r\n    </div>\r\n<input type=\"hidden\" name=\"app[status]\" value=\"Appointed\"/>\r\n<div class=\"clear\"></div>\r\n<%= hidden_field_tag :return, params[:return] %>\r\n<%= f.submit \'Submit\', :class=>\'btn btn-success\' %>\r\n<%= link_to \'Cancel\', params[:return], :class=>\'btn\' %>\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n<!-- old -->\r\n<script>\r\n    \r\n    \r\n    $(\'.ctrl\').hide();\r\n    \r\n</script>',NULL,NULL,NULL,'2015-08-02 11:23:00','2015-08-02 11:23:00','form_xx',''),(1723,