r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2015-08-02 14:05:39','2015-08-02 14:05:39','show',''),(1725,'get_patient_by_hn',214,3,'<% \r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   model = get_model(this.table_name)\r\n   res = model.where(:hn=>params[:hn]).first\r\n#   query = params[:q]\r\n#   keys = []\r\n#   @document.list_fields.each_with_index do |f,index| \r\n#     keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n#   end\r\n\r\n#   records = model.all({\'$or\'=>keys}.merge!({:limit=>20}))\r\n%>\r\n<%= res.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2015-08-02 15:01:19','2015-08-02 15:01:19','get_patient_by_hn',''),(1726,'edit',725,2,'<% if @current_role==\'guest\' %>\r\n<script>alert(\"Permission not allowed\");window.location = \"../Home/index\";</script>\r\n<% else %>\r\n<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<style>\r\nul.checkbox  { \r\n  margin: 0; \r\n  padding: 0; \r\n  margin-left: 20px; \r\n  list-style: none; \r\n} \r\n\r\nul.checkbox li input { \r\n  margin-right: .25em; \r\n} \r\n\r\nul.checkbox li { \r\n  border: 1px transparent solid; \r\n  display:inline-block;\r\n  width:12em;\r\n} \r\n\r\nul.checkbox li label { \r\n  margin-left: ; \r\n} \r\n.rline { width:100px; float:left }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<!--<h3>Create Patient</h3>-->\r\n<strong>Edit Appointment</strong>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n<div >\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\" >\r\n\r\n<%= render :inline=>this.initz %>\r\n<% # params.inspect %>\r\n<%\r\n\r\n    msg = nil\r\n    err = false\r\n    \r\n    models = get_model\r\n    all_provider = models[:provider].all\r\n    list_surgeon = all_provider.collect{|i| [i.id, i.name] if i[:provider_type]==\'4\'}.compact!\r\n    list_nurse_surgeon = all_provider.collect{|i| [i.id, i.name] if i[:provider_type]==\'5\'}.compact!\r\n    list_anesth = all_provider.collect{|i| [i.id, i.name] if i[:provider_type]==\'6\'}.compact!\r\n    list_nurse_anesth = all_provider.collect{|i| [i.id, i.name] if i[:provider_type]==\'7\'}.compact!\r\n    \r\n    list_surgeon = [] unless list_surgeon\r\n    list_nurse_surgeon = [] unless list_nurse_surgeon\r\n    list_anesth = [] unless list_anesth\r\n    list_nurse_anesth = [] unless list_nurse_anesth\r\n    \r\n    # instr = [\'Head Clamp\', \'Hourse Shoes\', \'Laminectomy Frame\', \'High Speed\', \'Soring\', \'Microscope\', \'Navigator\', \'C-Arm\', \'Laser\', \'Endoscope\', \'Quadrant (X-tube)\', \'Ultrasound\', \'SSEP\', \'MEP\', \'Cortical Stimulator\', \'Screw\', \'ECoG\', \'Buddy Halo\', \'Nerve stimulation\']\r\n    instr = models[:instrument].all.collect{|i| [i.id, i.name]}\r\n    instr = [] unless instr\r\n    \r\n    m_appointment = models[:appointment]\r\n    m_patient_detail = models[:patient_detail]\r\n    \r\n    model = get_model(this.table_name)\r\n    @patient_module = @module_model.find(params[:id])\r\n    record = model.find(@patient_module.module_id)\r\n    rec_pat = @patient_model.find(@patient_module[:patient_id])\r\n\r\n    if request.post?\r\n        if params[:commit].downcase == \'delete\'\r\n            @patient_module.destroy\r\n            record.destroy\r\n            \r\n            msg = \"Appointment deleted\"\r\n            next_service = \"../Home/index\"\r\n            err = true\r\n        else\r\n      \r\n        p = params[:record]\r\n        p_app = params[:app]\r\n        return_url = params[:return]\r\n        date = Time.now\r\n        # if p[:birth_date].length <= 2\r\n        #     cur_year = Time.now.year\r\n        #     dif_year = cur_year - p[:birth_date].to_i\r\n        #     p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        # elsif !p[:birth_date].empty?\r\n        #     date = Date.parse(p[:birth_date])\r\n        #     year = date.strftime(\"%Y\").to_i\r\n        #     if year > 2400\r\n        #         year = year - 543\r\n        #         new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n        #         p[:birth_date] = new_date\r\n        #     end \r\n        # end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        next_service = \"../Home/index\"\r\n        rec_app = record.update_attributes p_app\r\n        @patient_module.update_attributes :updated_by=>p_app[:updated_by]\r\n        msg = \"Appointment updated\"\r\n        end\r\n      %>\r\n      <!--<%#params.inspect %>-->\r\n      <br/>\r\n      \r\n      <div class=\"alert <%= err ? \"alert-error\" : \"alert-success\" %>\"><%= msg %></div>\r\n      \r\n      <meta http-equiv=\"refresh\" content=\"0; url=<%=next_service%>\" />\r\n      \r\n      <%\r\n    else\r\n%>\r\n<%= form_for :record , :url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n<%# f.hidden_field :date, :value=>p_date %>\r\n<div class=\"w-box\">\r\n<!--<div id=\"132-F1376173358\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">-->\r\n<div class=\"form-horizontal well\">\r\n<!--<b>Personal Information</b>-->\r\n<p class=\"f_legend\">Patient Information</p>\r\n<!--</div>-->\r\n<div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n    <span class=\"\"><label>Hospital Number <span class=\"f_req\">*</span>  : </label></span>	\r\n    <input disabled type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" \r\n        class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"\r\n        value=\"<%= rec_pat[:hn] %>\"/>\r\n    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[hn]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n</div>\r\n\r\n<!--<div class=\"row-fluid\"></div>-->\r\n\r\n<div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:340px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n    <input disabled type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" \r\n        value=\"<%= rec_pat[:public_id] %>\" class=\"k-textbox k-textbox-txt\"/>\r\n</div>\r\n<br/>\r\n<div id=\"patient_msg\"></div>\r\n<div class=\"clear\"></div>\r\n<hr/>\r\n    <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Prefix name : </label></span>	\r\n        <!--\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select disabled name=\"record[prefix_name]\" id=\"data-prefix_name\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\">ไม่ระบุ</option>\r\n                <option value=\"นาย\"<%= \" selected=\'selected\'\" if rec_pat[:prefix_name].strip == \'นาย\' %>>นาย</option>\r\n                <option value=\"นาง\"<%= \" selected=\'selected\'\" if rec_pat[:prefix_name].strip == \'นาง\' %>>นาง</option>\r\n                <option value=\"นางสาว\"<%= \" selected=\'selected\'\" if rec_pat[:prefix_name].strip == \'นางสาว\' %>>นางสาว</option>\r\n                <option value=\"ด.ช.\"<%= \" selected=\'selected\'\" if rec_pat[:prefix_name].strip == \'ด.ช.\' %>>ด.ช.</option>\r\n                <option value=\"ด.ญ.\"<%= \" selected=\'selected\'\" if rec_pat[:prefix_name].strip == \'ด.ญ.\' %>>ด.ญ.</option>\r\n            </select>\r\n        </div>\r\n        -->\r\n        <input disabled value=\"<%= rec_pat[:prefix_name] %>\" type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n    <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n        <input disabled type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\"\r\n            value=\"<%= rec_pat[:first_name] %>\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n        <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n    </div>\r\n    <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n        <input disabled type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" \r\n            value=\"<%= rec_pat[:last_name] %>\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n        <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n    </div>\r\n    <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Gender : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select disabled name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"0\"<%= \" selected=\'selected\'\" if rec_pat[:gender] == \'0\' %>>ไม่ระบุ</option>\r\n                <option value=\"1\"<%= \" selected=\'selected\'\" if rec_pat[:gender] == \'1\' %>>ชาย</option>\r\n                <option value=\"2\"<%= \" selected=\'selected\'\" if rec_pat[:gender] == \'2\' %>>หญิง</option>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n<%\r\n\r\n    m_or_room = models[:or_room]\r\n    m_post_op_ward = models[:ward]\r\n    m_ward = models[:ward]\r\n    m_position = models[:position]\r\n    \r\n    l_or_room = m_or_room.all.collect{|i| [i.id, i.name]}\r\n    l_post_op = m_post_op_ward.all.collect{|i| [i.id, i.name]}\r\n    l_ward = m_ward.all.collect{|i| [i.id, i.name]}\r\n    l_position = m_position.all.collect{|i| [i.id, i.name]}\r\n%>\r\n    <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <span class=\"k-widget k-datepicker k-header\" style=\"width: 100px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                <input disabled=\"disabled\" type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n            <script>\r\n            	$(\"#data-birth_date\").kendoDatePicker({\r\n            		value: \'<%= rec_pat[:birth_date].strftime(\"%d/%m/%Y\") %>\',\r\n            	});\r\n            </script>\r\n        </div>\r\n    </div>\r\n<% if false %>\r\n    <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n            <script>\r\n            	$(\"#data-date\").kendoDatePicker({\r\n            		value: \'<%= record[:date].strftime(\"%d/%m/%Y\") %>\',\r\n            	});\r\n            </script>\r\n        </div>\r\n    </div>\r\n<% end %>\r\n    <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Time <br/>(HH.MM): </label></span>\r\n        <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n            <span class=\"k-picker-wrap k-state-default\">\r\n                <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 00:26:20 +0700\" style=\"width: 100%;\" onkeypress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                    <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                </span>\r\n            </span>\r\n        </span>\r\n        <script>\r\n            $(\"#data-start\").kendoTimePicker({\r\n        	value: \'<%= !record[:start].nil? ? record[:start].strftime(\"%H:%M\") : \'N/A\' %>\',\r\n        	interval: 10,\r\n        	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\"],\r\n        	change: function(event){\r\n        		var v = $(\'#data-start\').val()\r\n        		if(v.length==3){\r\n        		    $(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n        		}\r\n        		 \r\n        	}\r\n        });\r\n        </script>\r\n	</div>\r\n	<div id=\"time_tf\" class=\" portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>TF <br/>(Checked for TF) : </label></span>\r\n        <ul class=\"checkbox\"> \r\n            <li>\r\n                <input name=\"app[time_tf]\" type=\"checkbox\" id=\"data-time_tf\" value=\"1\" <%= \'checked\' if record[:time_tf] == \'1\' %> />\r\n                <label for=\"data-time_tf\">TF</label>\r\n            </li>\r\n        </ul>\r\n	</div>\r\n	<div id=\"case_type\" class=\" portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\">\r\n            <label>Case Type : </label>\r\n       </span>\r\n	    <label class=\"radio\">\r\n			<input type=\"radio\" value=\"E\" id=\"update_case_type_item0\" name=\"update_case_type\" previousValue=\'<%= \'checked\' if record[:case_type] == \'E\' %>\' <%= \'checked\' if record[:case_type] == \'E\' %>/>\r\n				(E) Emergency\r\n		</label>\r\n		<label class=\"radio\">\r\n			<input type=\"radio\" value=\"U\" id=\"update_case_type_item1\" name=\"update_case_type\" previousValue=\'<%= \'checked\' if record[:case_type] == \'U\' %>\' <%= \'checked\' if record[:case_type] == \'U\' %>/>\r\n				(U) Urgency\r\n		</label>\r\n	</div>\r\n<div class=\"clear\"></div>\r\n<hr/>\r\n    <div id=\"or_room\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Room : </label></span>	\r\n        <!--<input type=\"text\" name=\"room\" id=\"data-room\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[or_room]\" id=\"data-or_room\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n<%\r\n    for l in l_or_room do\r\n        sel = \'\'\r\n        if l[0].to_s == record[:or_room].to_s\r\n            sel = \" selected=\'selected\'\"\r\n        end\r\n%>\r\n                <option value=\"<%= l[0]%>\"<%= sel %>><%= l[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"ward\" class=\"  portlet \" style=\"border:0px solid blue;width:360px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Ward : </label></span>	\r\n        <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n          \r\n<%\r\n    for l in l_ward do\r\n        sel = \'\'\r\n        if l[0].to_s == record[:ward].to_s\r\n            sel = \" checked \"\r\n        end\r\n%>\r\n               \r\n                                <label class=\"radio rline\">\r\n			<input type=\"radio\" value=\"<%= l[0]%>\"  name=\"app[ward]\" <%= sel %> />\r\n				<%= l[1] %>\r\n		</label>\r\n<%\r\n    end\r\n%>\r\n          \r\n        </div>\r\n    </div>\r\n<!--    <div id=\"care_unit_days\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">-->\r\n<!--        <span class=\"\"><label>Care Unit Days : : </label></span>	-->\r\n<!--        <input type=\"text\" name=\"care_unit_days\" id=\"data-care_unit_days\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n<!--    </div>-->\r\n    \r\n<!--<div class=\"clear\"></div>-->\r\n\r\n    <div id=\"position\" class=\"  portlet \" style=\"border:0px solid blue;width:105px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Position : </label></span>	\r\n        <!--<input type=\"text\" name=\"position\" id=\"data-position\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[position]\" id=\"data-position\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n<%\r\n    for l in l_position do\r\n        sel = \'\'\r\n        if l[0].to_s == record[:position].to_s\r\n            sel = \" selected=\'selected\'\"\r\n        end\r\n%>\r\n                <option value=\"<%= l[0]%>\"<%= sel %>><%= l[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"post_op\" class=\"  portlet \" style=\"border:0px solid blue;width:105px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Post-op : </label></span>	\r\n        <!--<input type=\"text\" name=\"post_op\" id=\"data-post_op\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[post_op]\" id=\"data-post_op\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n<%\r\n    for l in l_post_op do\r\n        sel = \'\'\r\n        if l[0].to_s == record[:post_op].to_s\r\n            sel = \" selected=\'selected\'\"\r\n        end\r\n%>\r\n                <option value=\"<%= l[0]%>\"<%= sel %>><%= l[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"anesth_technique\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Anesth Technique : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n<%\r\n    cur_tech = record[:anesth_technique]\r\n    sel_text = \"selected=\'selected\'\"\r\n%>\r\n            <select name=\"app[anesth_technique]\" id=\"data-anesth_technique\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\" ></option>\r\n                <option value=\"GA\" <%= sel_text if cur_tech==\'GA\' %>>GA</option>\r\n                <option value=\"LA\" <%= sel_text if cur_tech==\'LA\' %>>LA</option>\r\n                <option value=\"BB\" <%= sel_text if cur_tech==\'BB\' %>>BB</option>\r\n                <option value=\"RA\" <%= sel_text if cur_tech==\'RA\' %>>RA</option>\r\n                <option value=\"MAC\" <%= sel_text if cur_tech==\'MAC\' %>>MAC</option>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"others\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Others : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n<%\r\n    cur_other = record[:others]\r\n%>\r\n            <select name=\"app[others]\" id=\"data-others\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\"></option>\r\n                <option value=\"1\" <%= sel_text if cur_other==\'1\' %>>Pain Clinic</option>\r\n                <option value=\"2\" <%= sel_text if cur_other==\'2\' %>>Critical care</option>\r\n                <option value=\"3\" <%= sel_text if cur_other==\'3\' %>>CPR</option>\r\n                <option value=\"4\" <%= sel_text if cur_other==\'4\' %>>Ventilation Care</option>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"surgeon\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Surgeon : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[surgeon]\" id=\"data-surgeon\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_surgeon do\r\n        sel = \'\'\r\n        if prov[0].to_s.strip == record[:surgeon].to_s\r\n            sel = \" selected=\'selected\'\"\r\n        end\r\n%>\r\n                <option value=\"<%= prov[0] %>\"<%= sel %>><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"assist\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Assist : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[assist]\" id=\"data-assist\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_nurse_surgeon do\r\n        sel = \'\'\r\n        if prov[0].to_s == record[:assist].to_s\r\n            sel = \" selected=\'selected\'\"\r\n        end\r\n%>\r\n                <option value=\"<%= prov[0] %>\"<%= sel %>><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"surgeon\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Anesthesiologist : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[anesth]\" id=\"data-anesth\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_anesth do\r\n        sel = \'\'\r\n        if prov[0].to_s == record[:anesth].to_s\r\n            sel = \" selected=\'selected\'\"\r\n        end\r\n%>\r\n                <option value=\"<%= prov[0] %>\"<%= sel %>><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"assist\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Nurse Anesthetist 1 : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[anesth_assist]\" id=\"data-anesth_assist\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_nurse_anesth do\r\n        sel = \'\'\r\n        if prov[0].to_s == record[:anesth_assist].to_s\r\n            sel = \" selected=\'selected\'\"\r\n        end\r\n%>\r\n                <option value=\"<%= prov[0] %>\"<%= sel %>><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div id=\"assist_2\" class=\"  portlet \" style=\"border:0px solid blue;width:335px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <span class=\"\"><label>Nurse Anesthetist 2 : </label></span>	\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <select name=\"app[anesth_assist_2]\" id=\"data-anesth_assist_2\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                <option value=\"\">&nbsp;</option>\r\n                <option value=\"0\">ไม่ระบุ</option>\r\n<%\r\n    for prov in list_nurse_anesth do\r\n        sel = \'\'\r\n        if prov[0].to_s == record[:anesth_assist_2].to_s\r\n            sel = \" selected=\'selected\'\"\r\n        end\r\n%>\r\n                <option value=\"<%= prov[0] %>\"<%= sel %>><%= prov[1] %></option>\r\n<%\r\n    end\r\n%>\r\n            </select>\r\n        </div>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"diagnosis\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Diagnosis : </label></span>	\r\n        <input type=\"text\" name=\"app[diagnosis]\" id=\"data-diagnosis\" size=\"29\" \r\n            style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\"\r\n            value=\"<%= record[:diagnosis] %>\"/>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"operation\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Operation : </label></span>	\r\n        <input type=\"text\" name=\"app[operation]\" id=\"data-operation\" size=\"29\" \r\n            style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\"\r\n            value=\"<%= record[:operation] %>\"/>\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"instrument\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Instrument : </label></span>\r\n        <ul class=\"checkbox\"> \r\n        <% \r\n            l_instr = !record[:instrument].nil? ? record[:instrument].split(\'|\') : {}\r\n            i = 0\r\n        %>\r\n        <% \r\n            instr.each do |k, v| \r\n        %>\r\n            <li><input name=\"instrument\" type=\"checkbox\" \r\n                id=\"update_instrument_item_<%=i%>\" value=\"<%= k.to_s %>\" <%= \'checked=\"checked\"\' if l_instr.include? k.to_s %> />\r\n                <label for=\"update_instrument_item_<%=i%>\"><%= v %></label>\r\n            </li>\r\n        <% \r\n            i += 1\r\n            end \r\n        %>\r\n        </ul>\r\n<!--        \r\n        <textarea type=\"text\" name=\"app[instrument]\" id=\"data-instrument\" row=\"5\" \r\n            style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n<%# record[:instrument] %>        \r\n        </textarea>\r\n-->\r\n    </div>\r\n<div class=\"clear\"></div>\r\n    <div id=\"instrument_other\" class=\"  portlet \" style=\"border:0px solid blue;width:510px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n        <span class=\"\"><label>Instrument Other : </label></span>	\r\n        <input type=\"text\" name=\"app[instrument_other]\" id=\"data-instrument_other\" size=\"29\" \r\n            value=\"<%= record[:instrument_other] %>\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n<div class=\"clear\"></div>\r\n\r\n<input type=\"hidden\" name=\"app[date]\" id=\"data-date\" value=\"<%= record[:date].strftime(\"%d/%m/%Y\") %>\"/>\r\n<input type=\"hidden\" name=\"app[case_type]\" id=\"data-case_type\" value=\"<%= record[:case_type] %>\"/>\r\n<input type=\"hidden\" name=\"app[instrument]\" id=\"data-instrument\" value=\"<%= record[:instrument] %>\"/>\r\n<input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= record[:updated_by] %><%# !@current_user.nil? ? @current_user.login : @current_user.name %>\"/>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n    <div class=\"row-fluid\">\r\n<%= hidden_field_tag :return, \"../Home/index\" %>\r\n<%= f.submit \'Update\', :class=>\'btn btn-success\' %>\r\n<%= link_to \'Cancel\', \"../Home/index\", :class=>\'btn\' %>\r\n\r\n<%= f.submit \'Delete\', :class=>\'btn btn-danger\', :style=>\'float:right\' %>\r\n    </div>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + (data.prefix_name == \'นาย\'));\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    function update_instrument() {\r\n        var instrument = [];\r\n        $(\"input:checkbox[name=instrument]:checked\").each(function(){\r\n            instrument.push($(this).val());\r\n        });\r\n        $(\'#data-instrument\').val(instrument.join(\'|\'));\r\n        console.log(\"change : \" + $(this).val());\r\n        console.log(\"all    : \" + instrument.join(\'|\'));\r\n    }\r\n    \r\n    var cur_user = \"<%= !@current_user.nil? ? @current_user.login : @current_user.name %>\";\r\n    var cre_user = \"<%= record[:updated_by] %>\";\r\n    var cur_room = \"<%= record[:or_room] %>\";\r\n    var cur_time = \"<%= record[:start].strftime(\'%k:%M\').strip if !record[:start].nil? %>\";\r\n    var cur_tf   = \"<%= record[:time_tf] %>\";\r\n    var cur_tech = \"<%= record[:anesth_technique] %>\";\r\n    var cur_pos  = \"<%= record[:position] %>\";\r\n    var cur_op   = \"<%= record[:operation].strip %>\"\r\n    function update_user_updated() {\r\n        room = $(\'#data-or_room\').val();\r\n        time = $(\'#data-start\').val();\r\n        tf = $(\'#data-time_tf\').prop(\'checked\') ? \'1\' : \'\';\r\n        op = $(\'#data-operation\').val().trim();\r\n        pos = $(\'#data-position\').val();\r\n        user = cre_user;\r\n        if (cur_room != room) {\r\n            user = cur_user;\r\n        } else if (cur_time != time) {\r\n            user = cur_user;\r\n        } else if (cur_tf != tf) {\r\n            user = cur_user;\r\n        } else if (cur_pos != pos) {\r\n            user = cur_user;\r\n        } else if (cur_op != op) {\r\n            user = cur_user;\r\n        } else {\r\n            user = cre_user;\r\n        }\r\n        \r\n        console.log(\"user : \" + user + \" [ROOM : \" + (room == cur_room) + \"][TIME : \" + (time == cur_time) + \"][TF : \" + (tf == cur_tf) + \"] >> \" + time + \",\" + cur_time);\r\n        // console.log($(this).val());\r\n        \r\n        $(\"#data-updated_by\").val(user); \r\n    }\r\n    $(document).ready(function(){\r\n        // hn\r\n        $(\'#data-hn\').change(update_patient);\r\n        // instrument update\r\n        f = \"input[id^=\'update_instrument\']\";\r\n        $(f).change(update_instrument);\r\n        \r\n        // check user edit\r\n        $(\'#data-or_room\').change(update_user_updated);\r\n        $(\'#data-start\').change(update_user_updated);\r\n        $(\'#data-time_tf\').change(update_user_updated);\r\n        $(\'#data-operation\').change(update_user_updated);\r\n        $(\'#data-position\').change(update_user_updated);\r\n        \r\n        // radio uncheckable\r\n        $(\"input[type=\'radio\']\").click(function() {\r\n          var previousValue = $(this).attr(\'previousValue\');\r\n          var name = $(this).attr(\'name\');\r\n          var data = $(\'#\' + name.replace(\"update_\", \"data-\"));\r\n          \r\n          if (previousValue == \'checked\') {\r\n            $(this).removeAttr(\'checked\');\r\n            $(this).attr(\'previousValue\', false);\r\n            data.val(\"\");\r\n          } else {\r\n            $(\"input[name=\"+name+\"]:radio\").attr(\'previousValue\', false);\r\n            $(this).attr(\'previousValue\', \'checked\');\r\n            data.val($(this).val());\r\n          }\r\n        });\r\n        \r\n        console.log(\"created user : \" + cre_user);\r\n    });\r\n</script>\r\n<% end #guest role %>',NULL,NULL,NULL,'2015-08-02 16:49:23','2015-08-02 16:49:23','edit',''),(1729,'redirect',765,3,'\r\n<% \r\nmodules = @context.get_projects_by_abstract \'ehr.emr\' \r\nmodel = get_model\r\nlogo = nil\r\nre_url = \"../../\\#{modules.first.name}/Home/index\".html_safe\r\n\r\n\r\n\r\n%>\r\n<script>\r\n    // alert(\'Hello\');\r\n    window.location = \"<%=re_url%>\";\r\n</script>\r\n<%= link_to modules.first, \"../../\\#{modules.first.name}/Home/index\" %>\r\n',NULL,NULL,NULL,'2015-08-02 18:32:34','2015-08-02 18:32:34','redirect',''),(1730,'index',765,2,'\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Solution\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE</b></center><br/>\r\n    <%= render :inline=>this.module %>\r\n</div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n<% \r\n\r\n    model = get_model\r\n    patient_model = model[:patient]\r\n    patient_module_model = model[:patient_module]\r\n    modules = @context.get_projects_by_abstract \'ehr.emr\' \r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n\r\n<%\r\ndb = patient_model.collection.db\r\n%>\r\n<%#db.class%>\r\n<%#db.collection_names.sort%>\r\n<%#db.collection(\'colo.appointment\').count%>\r\n\r\n<%\r\nfor m in modules\r\n  \r\n    list = db.collection(\"\\\\#{m.name}.appointment\").group({:keyf=>\'function(doc){return {month:doc.date.getMonth()};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\'\r\n        #   :cond=>{:status=>{\'$in\'=>[\'Completed\',\'Recovery\',\'Processing\']},:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}\r\n          })\r\n        columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n        \r\n    if list.size>0    \r\n    data = []\r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    data[i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\n    \r\n\r\n%>\r\n<%#list.to_json.html_safe%>\r\n<div id=\"chart-<%=m.id%>\" style=\"border:0px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n<%#columns.to_json%>\r\n            <script>\r\n                    $(\"#chart-<%=m.id%>\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"<%=m.title%> Patients by Month\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: [{\r\n                            name: \"Patients\",\r\n                            data: <%=data.to_json.html_safe %>\r\n                        }],\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                \r\n\r\n             \r\n            </script>                 \r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        System Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<table class=\"table table-striped table-bordered table-condensed\">\r\n<thead>\r\n<tr>\r\n<th>Title</th>\r\n<th>Value</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Disk Space</td>\r\n<%\r\n   size = patient_model.collection.db.stats[\'storageSize\']\r\n   unit = \'B\'\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'KB\'\r\n   size /= 1000\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'MB\'\r\n   size /= 1000\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'GB\'\r\n   size /= 1000\r\n   \r\n   end\r\n   end\r\n   end\r\n   \r\n   \r\n\r\n%>\r\n\r\n<td><%=format(\'%.2f\',size)%> <%=unit%></td>\r\n</tr>\r\n<tr>\r\n<td>Total Patient</td>\r\n<td><%= (model[:patient]).count %></td>\r\n</tr>\r\n<tr>\r\n<td>Total Module</td>\r\n<td><%= modules.size %></td>\r\n</tr>\r\n<tr>\r\n\r\n</tr>\r\n<tr>\r\n<td>Total Record</td>\r\n<td><%= (model[:patient_module]).count %></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<!--\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Support\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\"></div>\r\n</div>\r\n-->\r\n</div>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-08-02 18:32:41','2015-08-02 18:32:41','',''),(1731,'print',751,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm_core/banner.png\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3><%=this.table_name.to_s.humanize%></h3>\r\n<%= this.display.html_safe %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div class=\"hideprint\">\r\n<%= link_to \'Back\', url(\'index\') %>\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2015-08-02 18:35:45','2015-08-02 18:35:45','print',''),(1732,'print_table',622,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  attachment_model = @models[:attachment]\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n \r\n \r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n \r\n \r\n    disease = {}\r\n    @models[:disease].collection.find().to_a.each do |i|\r\n    disease[i[\'_id\']] = i\r\n    end\r\n    \r\n    location = {}\r\n    @models[:location].collection.find().to_a.each do |i|\r\n    location[i[\'_id\']] = i\r\n    end\r\n    \r\n     intervention = {}\r\n    @models[:intervention].collection.find().to_a.each do |i|\r\n    intervention[i[\'_id\']] = i\r\n    end\r\n \r\n \r\n    \r\n    \r\nmfinding = @models[:finding]\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n \r\n \r\n\r\n \r\n ml =  @module_model.where(:parent_id=>i.id).all\r\n \r\n diagnosis = \'-\'\r\n diagnosis_group = \'-\'\r\n provider = providers[ap.provider.to_s]\r\n provider_name = provider.name\r\n attachments = []\r\n#  provider_name = ml.size.to_s\r\n fibosis = \'-\'\r\n fat_percentage = \'-\'\r\n#  fibrosis = @models[:fibrosis].collection.find(:_id=>{\'$in\'=>)\r\n \r\n egd_dx = \'-\'\r\n \r\n cfmap = {}\r\n gfmap = {}\r\n \r\n\r\n \r\n for x in ml\r\n    if x.module_name==\"\\\\#{@current_project.name}#colono\"\r\n        \r\n        colo = @models[:colono].find(x.module_id)\r\n        if colo\r\n            provider_name = colo.id.to_s\r\n            \r\n            provider = providers[colo.endoscopist.to_s]\r\n            provider_name = provider.name\r\n            diagnosis = colo.diagnosis_text\r\n            diagnosis_group = colo.diagnosis_group\r\n            attachments = colo.image\r\n          \r\n        end\r\n    elsif x.module_name ==\"\\\\#{@current_project.name}#fibroscan\"\r\n    \r\n        fibroscan = @models[:fibroscan].find(x.module_id)\r\n        \r\n        if fibroscan\r\n            fibrosis = fibroscan.fibrosis\r\n            fat_percentage = fibroscan.fat_percentage\r\n        end\r\n        \r\n        \r\n     elsif x.module_name ==\"\\\\#{@current_project.name}#gastro\"\r\n    \r\n        gastro = @models[:gastro].find(x.module_id)\r\n        \r\n        if gastro\r\n            egd_dx = gastro.diagnosis_text\r\n        end\r\n        \r\n        \r\n    end\r\n end\r\n \r\n \r\n\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year} ปี\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>ml.collect{|i| i.module_name.split(\'#\')[-1].humanize}.join(\',\'),\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider_name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'attachments\'=>attachments,\r\n    \'age\'=>age,\r\n    \'ml\'=>ml,\r\n    \'fibrosis\'=>fibrosis,\r\n    \'fat\'=>fat_percentage,\r\n    \'egd_dx\'=>egd_dx.html_safe,\r\n    \'diagnosis\'=>diagnosis.html_safe,\r\n    \'diagnosis_group\'=>diagnosis_group.html_safe,\r\n    \'colo\'=>colo,\r\n    \'gastro\'=>gastro,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\n\r\n\r\nlist = json_data.sort{|a,b| b[\'diagnosis_group\']<=>a[\'diagnosis_group\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n  /*tr.page-break  { display: block; page-break-before: auto; }*/\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<%\r\n   cols = %w{schedule type_of_sedation study_project type_of_instrument bowel_preperation_agent \r\n        \r\n        anesthetic_drug_type\r\n        \r\n        pethidine_mg dormicum_mg propofol_mg fentanyl_mcg clinical_indication bowel_preperation_finding\r\n        \r\n        diagnosis_group intervention_text \r\n        \r\n        start_procedural_time stop_procedural_time cecal_intubation_time withdrawal_time intervention_group\r\n        \r\n        }\r\n        \r\n         gols = %w{schedule type_of_sedation study_project type_of_instrument  \r\n        \r\n        anesthetic_drug_type\r\n        \r\n        pethidine_mg dormicum_mg propofol_mg fentanyl_mcg clinical_indication \r\n        \r\n        diagnosis_group intervention_text \r\n        \r\n        \r\n     \r\n            \r\n }\r\n \r\n      colo_location = <<EOF\r\ncolon_terminal_ileum|Terminal ileum\r\ncolon_ileocecal_value|Ileocecal valve\r\ncolon_cecum|Cecum\r\ncolon_ascending_colon|Ascending colon\r\ncolon_transverse_colon|Transverse colon\r\ncolon_descending_colon|Descending colon\r\ncolon_sigmoid_colon|Sigmoid colon\r\ncolon_rectum|Rectum\r\ncolon_anus|Anus       \r\nEOF\r\n\r\n  colo_location = colo_location.split(\"\\n\")\r\n        \r\n    ddisease = {\'polyp\'=>%w{ polyp_number polyp_size polyp_shape}, \'hemorrhoid\'=>%w{hemorrhoid_location hemorrhoid_internal_size hemorrhoid_external_size hemorrhoid_bleeding_stigmata hemorrhoid_external_bleeding_stigmata}}    \r\n        \r\n        \r\n%>\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th>Date</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>HN</th>\r\n    <th>Age</th>\r\n    <th>Procedure</th>\r\n    <th>Fibrosis</th>\r\n    <th>Fat%</th>\r\n    <th>Colono Dx</th>\r\n    <th>Gastro Dx</th>\r\n    <th>Provider</th>\r\n    \r\n    <% for i in colo_location %>\r\n    <th><%=i.split(\"|\")[-1]%></th>\r\n    <% end %>\r\n    <%for i in cols %>\r\n    <th>Colo:<%=i.humanize%></th>\r\n    <% end %>\r\n    <% 5.times do |i|%>\r\n    <th>finding-<%=i%></th>\r\n    <% end %>\r\n  \r\n    \r\n   \r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n<% \r\n    sp = {}\r\n    index = 0 \r\n    list.each_with_index do |i,ix|  \r\n        pps = i[\'procedure\'].split(\',\')\r\n        for pp in pps\r\n            if sp.has_key?(pp)\r\n                sp[pp] = sp[pp] + 1\r\n            else\r\n                sp[pp] = 1\r\n            end\r\n        end\r\n    if params[:filter]==nil or (i[\'diagnosis\']!=\'\' and i[\'diagnosis_group\']!=\'0\') \r\n\r\n    \r\n%> \r\n    <tr class=\"page-break\">\r\n    <td><%=index+1%>.</td>\r\n    <td><%=i[\'date\']%></td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%></td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'age\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    \r\n    <td><%=i[\'fibrosis\']%></td>\r\n    <td><%=i[\'fat\']%></td>\r\n    \r\n    <td><%=i[\'diagnosis\']%></td>\r\n    \r\n    <td><%=i[\'egd_dx\']%></td>\r\n    \r\n    <td><%=i[\'provider\']%></td>\r\n    \r\n\r\n    <%\r\n        \r\n     \r\n    \r\n    colo = i[\'colo\']\r\n    \r\n    \r\n    \r\n     colo_location.each_with_index do |ix,index |\r\n    a = \'-\'\r\n    if colo\r\n        a = colo[\"finding_\\\\#{index+1}_summary\"]\r\n    end\r\n     %>\r\n    <td><%=a.html_safe if a %></td>\r\n    <% end \r\n    \r\n    \r\n\r\n    if colo    \r\n    @record = colo\r\n    @document = @current_project.get_document \'colono\'\r\n    \r\n    for cl in cols\r\n        \r\n    %>\r\n    <td>\r\n    <%=render_value cl%>\r\n    </td>\r\n    <% end %>\r\n    \r\n    <%\r\n      \r\n    fs = mfinding.find(colo.findings)\r\n    for f in fs\r\n    detail = \'\'\r\n    d = disease[f.disease]\r\n    \r\n    # detail = ddisease[d[\'disease_tag\']].collect{|pi|  \"\\\\#{pi}:\\\\#{d[pi]}\"  }.join(\",\") if ddisease[d[\'disease_tag\']]\r\n    \r\n    %>\r\n    <td>\r\n    <%= d[\'disease_tag\'] %> in <%=location[f.location][\'location_tag\']%> \r\n    </td>\r\n    <%\r\n    end \r\n    %>\r\n    \r\n    \r\n    \r\n    <% end %>\r\n    \r\n    \r\n    <!--<td><%=link_to(\'Detail\',\"patient_record?id=\\\\#{i[\'id\']}\")%></td>-->\r\n    </tr>\r\n    \r\n  \r\n    \r\n    <% \r\n    \r\n    index+=1\r\n    end %>\r\n    <% end %>\r\n</tbody>\r\n  </table>\r\n</body>\r\n</html>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2015-08-03 03:22:18','2015-08-03 03:22:18','print_table',''),(1733,'document_name',766,1,'\'instrument\'',NULL,NULL,NULL,'2015-08-03 05:36:05','2015-08-03 05:36:05',NULL,NULL),(1735,'sumgroup',714,1,'{\r\n	:total_preop => {\r\n		:select => [:e, :v, :m],\r\n		:total => :gcs,\r\n		:letter => [\'T\']\r\n	}\r\n}',NULL,NULL,NULL,'2015-08-03 14:03:18','2015-08-03 14:03:18','sumgroup',''),(1736,'patient_record2',717,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date) if i.date%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\#{@current_project.name}#\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\#{i.time.strftime(\"%H:%M\") if i.time } - \\#{i.ref_number}\", \"../\\#{s.name.camelize}/show?id=\\#{i.id}&return=\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\#{s.name.camelize}/edit?id=\\#{i.id}&record_name=\\#{patient.hn}&return=\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\#{s.name.camelize}/create?patient_id=\\#{patient.id}&record_name=\\#{patient.hn}&parent_id=\\#{pm.id}&return=\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\#{s.name.camelize}/print?id=\\#{i.id}&return=\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name if user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\#{@current_project.name}#\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\#{i.time.strftime(\"%H:%M\") if i.time } - \\#{i.ref_number}\", \"../\\#{s.name.camelize}/show?id=\\#{i.id}&return=\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\#{s.name.camelize}/edit?id=\\#{i.id}&record_name=\\#{patient.hn}&return=\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\#{s.name.camelize}/create?patient_id=\\#{patient.id}&record_name=\\#{patient.hn}&parent_id=\\#{pm.id}&return=\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\#{s.name.camelize}/print?id=\\#{i.id}&return=\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2015-08-03 14:36:56','2015-08-03 14:36:56','patient_record2',''),(1737,'list',767,3,'<%\r\n   model = get_model(this.table_name)\r\n   records = []\r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   \r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   \r\n    if params[:search]\r\n        records = model.all(params[:search][:criteria])\r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n       records = model.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n    end\r\n   \r\n%>\r\n\r\n<%= tabular :model=>labels, :data=>records do |i,out|\r\n\r\nfields.each_with_index do |f,index|\r\n\r\nout[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n\r\nend\r\nout<<link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nout<<link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\')\r\nout<<link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:confirm=>\'Are you sure?\')\r\nout\r\nend\r\n%>\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2015-08-03 15:48:43','2015-08-03 15:48:43','list',''),(1740,'document_name',769,1,'\'medication\'',NULL,NULL,NULL,'2015-08-04 14:37:27','2015-08-04 14:37:27',NULL,NULL),(1741,'docume