ck;\r\n}\r\ntable.table tr.operation td {\r\n    /*color:red;*/\r\n    background-color:rgb(253, 98, 98);\r\n    color : black;\r\n    text-shadow : none ;\r\n}\r\n.recovery {\r\n    background-color : PaleGreen  ;\r\n    color : black;\r\n    padding : 10px;\r\n}\r\ntable.table tr.recovery td {\r\n    /*color:green;*/\r\n    background-color : PaleGreen  ;\r\n    color : black;\r\n    text-shadow : none ;\r\n}\r\n.completed {\r\n    padding : 10px;\r\n    background-color :DarkGreen ;\r\n    color : white;\r\n}\r\ntable.table tr.completed td {\r\n    /*color:green;*/\r\n    background-color :DarkGreen ;\r\n    color : white;\r\n    text-shadow : none ;\r\n}\r\n.icu {\r\n    background-color:Plum ;\r\n    color : black;\r\n    padding : 10px;\r\n}\r\ntable.table tr.icu td {\r\n    /*color:purple;*/\r\n    background-color:Plum ;\r\n    color : black;\r\n    text-shadow : none ;\r\n    /*text*/\r\n}\r\n.ward {\r\n    padding : 10px;\r\n    background-color : CornflowerBlue ;\r\n    color : black;\r\n}\r\ntable.table tr.ward td {\r\n    /*color:blue;*/\r\n    background-color : CornflowerBlue ;\r\n    color : black;\r\n    text-shadow : none ;\r\n}\r\n.home {\r\n    padding : 10px;\r\n    background-color : RoyalBlue  ;\r\n    color : black;\r\n}\r\ntable.table tr.home td {\r\n    /*color:blue;*/\r\n    background-color : RoyalBlue  ;\r\n    color : black;\r\n    text-shadow : none ;\r\n}\r\n</style>\r\n<body >\r\n<div class=\"wrapper\">\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\" style=\"width:100%\">\r\n<div class=\"span12\" style=\"width:100%\">\r\n\r\n\r\n\r\n<div id=\"endoscopy_nurse\" class=\"  portlet \" >\r\n\r\n<span>\r\n    <!--<img src=\'/esm/anes/pni/logo.jpg\' width=\"60\" />-->\r\n    <!--<label> Operation Schedule : </label>-->\r\n</span>\r\n<div class=\"row-fluid\">\r\n    <div style=\"float:left;\"><label>Operative Schedule : <%= date.strftime(\'%d/%m/%Y at %H:%M\') %></label></div>\r\n    <div style=\"float:right;margin-bottom:10px\"><label>Prasat Neurological Institute</label></div>\r\n    <p/>\r\n</div>\r\n\r\n<div style=\"margin-top:10px\">\r\n <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" class=\"table\">  \r\n \r\n <tr>\r\n    <th style=\"text-align:center\" width=\'4%\'>Room</th>\r\n    <th width=\'6%\'>Time</th>\r\n    <th width=\'15%\'>Patient Info/<br/> Ward/Post-op</th>\r\n    <th width=\'15%\'>Diagnosis/<br/>Operation</th>\r\n    <th width=\'5%\'>Position/<br/>AnesthTech</th>\r\n    <th width=\'15%\'>Instrument</th>\r\n    <th width=\'15%\'>Surgeon/<br/>Assist</th>\r\n    <th width=\'15%\'>Anesth/<br/>Assist</th>\r\n </tr>         \r\n<% \r\n    l_updated = []\r\n    for i in aps do \r\n        if i[:status] == \'Cancelled\'\r\n            next\r\n        end\r\n        \r\n        r_pat_mod = m_pat_mod.where(:module_id=>i.id).first\r\n        if r_pat_mod\r\n            r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n            if r_pat\r\n            \r\n                # latest user\r\n                l_updated.push({:user=>i[:updated_by],:time=>i[:updated_at]})\r\n                \r\n                # age\r\n                today = Date.today\r\n                d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n                age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n            end\r\n        end\r\n%>\r\n<tr class=\"<%=i[:status].downcase%>\">  \r\n    <td>\r\n        <%=map_or_room[i[:or_room]]%> \r\n    </td>\r\n    <td>\r\n        <%= !i[:start].nil? ? i[:start].strftime(\'%H:%M\') : \'N/A\' %> <%= \'TF\' if i[:time_tf] == \'1\' %>\r\n    </td> \r\n    <td>\r\n        <span style=\"text-align:left;display:block\">\r\n            HN : <%= r_pat[:hn] %> (<%= age %>)\r\n            <br/>\r\n            <%= \"(\\\\#{i[:case_type]}) \" unless !i[:case_type] or i[:case_type] == \'\'%> \r\n            <%=r_pat[:prefix_name]%><%=r_pat[:first_name]%> <%=r_pat[:last_name]%>\r\n            <hr/>\r\n            <%=map_ward[i[:ward]]%> / <%=map_ward[i[:post_op]]%>\r\n        </span>\r\n    </td> \r\n    <td>\r\n        <span style=\"text-align:left;display:block\">\r\n            <%=i[:diagnosis]%><hr/><%=i[:operation]%>\r\n        </span>\r\n    </td>\r\n<%\r\n    a_tech = i[:anesth_technique] ? i[:anesth_technique] : \'N/A\'\r\n    a_tech = a_tech == \'\' ? \'-\' : a_tech\r\n%>\r\n    <td><%= map_position[i[:position]] %><hr/><%= a_tech %></td> \r\n    <td>\r\n        <span style=\"text-align:left;display:block\">\r\n<%\r\n    l_instr = i[:instrument].nil? ? [] : i[:instrument].split(\'|\')\r\n    s_instr = []\r\n    for s in l_instr do\r\n        s_instr.push(map_instrument[s])\r\n    end\r\n%>\r\n        <%= s_instr.join(\',\') %>\r\n        <%= \',\'.html_safe if !s_instr.empty? %><%= \"\\\\#{i[:instrument_other]}\".html_safe if i[:instrument_other] != \'\'%>\r\n        </span>\r\n    </td>\r\n    <td>\r\n        <span style=\"text-align:left;display:block\">\r\n            <%= map_provider[i[:surgeon]] %><hr/><%=map_provider[i[:assist]]%>\r\n        </span>\r\n    </td>\r\n    <td>\r\n        <span style=\"text-align:left;display:block\">\r\n            <%= map_provider[i[:anesth]] %><hr/>\r\n            <%\r\n                a1 = map_provider[i[:anesth_assist]]\r\n                a2 = map_provider[i[:anesth_assist_2]]\r\n            %>\r\n            A1: <%=a1!=\'N/A\' ? a1.split(\' \')[0] : \'N/A\'%>, A2: <%=a2!=\'N/A\' ? a2.split(\' \')[0] : \'N/A\'%>\r\n        </span>\r\n    </td>\r\n </tr>     \r\n	\r\n <% end %>\r\n\r\n\r\n\r\n\r\n\r\n</table>\r\n<br/>\r\n<div class=\"row-fluid\" style=\"\">\r\n    Status : \r\n    <span class=\"appointed\">Appointed</span> | <span class=\"waiting\">Waiting</span> | <span class=\"operation\">Operation</span> | <span class=\"recovery\">Recovery</span> | \r\n    <span class=\"completed\">Completed</span> | <span class=\"icu\">ICU</span> | <span class=\"ward\">Ward</span> | <span class=\"home\">Home</span>\r\n</div>    \r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n	\r\n\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n<% end %>\r\n',NULL,NULL,NULL,'2015-08-04 17:21:25','2015-08-04 17:21:25','status_board','*'),(1743,'json',599,3,'<%\r\n    model = get_model[this.table_name.to_sym]\r\n    # res = model.order(\"created_at\").last\r\n    res = model.limit(5).order(\'created_at desc\')\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-08-05 15:57:00','2015-08-05 15:57:00','json',''),(1744,'document_name',771,1,'\'internal_hemorrrhoid\'',NULL,NULL,NULL,'2015-08-06 06:46:17','2015-08-06 06:46:17',NULL,NULL),(1745,'color_name',599,1,'\'indianred\'',NULL,NULL,NULL,'2015-08-07 16:01:56','2015-08-07 16:01:56','color_name',''),(1746,'color_name',604,1,'\'lightsalmon\'',NULL,NULL,NULL,'2015-08-07 17:06:52','2015-08-07 17:06:52','color_name',''),(1747,'color_name',677,1,'\'tomato\'',NULL,NULL,NULL,'2015-08-07 17:07:27','2015-08-07 17:07:27','color_name',''),(1748,'color_name',600,1,'\'seagreen\'',NULL,NULL,NULL,'2015-08-07 17:08:22','2015-08-07 17:08:22','color_name',''),(1749,'color_name',605,1,'\'mediumseagreen\'',NULL,NULL,NULL,'2015-08-07 17:10:12','2015-08-07 17:10:12','color_name',''),(1750,'color_name',678,1,'\'darkseagreen\'',NULL,NULL,NULL,'2015-08-07 17:10:29','2015-08-07 17:10:29','color_name',''),(1751,'init',667,4,'<%\r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  \r\n    m_hos = get_model[:hospital]\r\n    @map_hospital = {\"\"=>\"Please select hospital\"}\r\n    m_hos.all.each do |i|\r\n        @map_hospital[i.id.to_s] = i[:hospital_name_thai]\r\n    end\r\n%>',NULL,NULL,NULL,'2015-08-08 17:47:44','2015-08-08 17:47:44','init',''),(1752,'opnote',599,4,'\r\n<script>\r\n    // var map_text = {\'position\':\'none\', \'approach\':\'none\'};\r\n    var txt_temp = \"<p class=\'MsoNormal\'>The patient was set in <span style=\'color:blue;\'>\\\\#{render_value(\'position\')}</span> position. \\\r\nSkin incision was performed, and <span style=\'color:blue;\'>\\\\#{render_value(\'approach\')}</span> approach was done. \\\r\nCapsulotomy was done using Bovie cautery. \\\r\nFemoral head was dislocated and removed. \\\r\nAcetabulum was identified, osteophyte around the rim of the acetabulum was removed. \\\r\nAcetabulum component was prepared and placed in approximately 45 degrees of abduction and 10 to 15 degrees of anteversion. \\\r\nStability of the acetabular component was evaluated.</p>\\\r\n<p class=\'MsoNormal\'>\\\\#{liner_txt} \\\\#{screw_txt} </p>\\\r\n<p class=\'MsoNormal\'>Reamers and broaches were used to prepare femoral cannal. \\\r\nFemoral component trial was used to evaluate for a appropriate press-fit. \\\r\nFemoral component trial was then reduced into the acetabulum to test for appropriate neck length, tension, and range of motion as well as ligamentous stability.\\\r\n</p>\\\r\n<p class=\'MsoNormal\'>After the appropriate femoral component has been confirmed, <span style=\'color:blue;\'>\\\\#{cement_txt}</span> \\\r\n<span style=\'color:blue;\'>\\\\#{head_txt}</span> femoral head was assembled to the final femoral stem. \\\r\nFinally, the hip was reduced, bleeding and instruments were checked.  And capsules and muscles were repaired respectively.\\\r\nVacuum drain was placed, and Skin were closed.</p> \\\r\n<br/><p class=\'MsoNormal\'>Bearing cup size : <span style=\'color:blue\'>\\\\#{cup_size}</span> and Head diameter : <span style=\'color:blue\'>\\\\#{diameter}</span></p>\";\r\n    function opnote() {\r\n        var editor = $(\"#data-operative_note\").data(\"kendoEditor\");\r\n        if (typeof(editor)) {\r\n             val = editor.value();\r\n             if (val.trim() == \'\') {\r\n                //  alert(\'no text\');\r\n                 this.generate_opnote();\r\n             }\r\n        }\r\n    }\r\n    function generate_opnote() {\r\n        // alert(\'generate opnote\');\r\n        // tmp = $(\'#data-mechanical\').val();\r\n        // console.log(\"machanic : \" + master.<%=this.table_name%>.mechanical[\'3\']+ \" <-- \" + tmp);\r\n        // console.log(\"asa_grade: \" + master.<%=this.table_name%>.patient_asa_grade[tmp]);\r\n        // console.log(master[\'hip1\'][\'position\'][\'1\']);\r\n        liner_txt = \'\'\r\n        head_txt = \'Metal\'\r\n        tmp = $(\'#data-bearing_surface_type\').val();\r\n        if (tmp != undefined) {\r\n            if (tmp == \'1\' || tmp == \'5\')\r\n                liner_txt = \"<span style=\'color:blue;\'>Polyethylene</span> liner was placed.\"\r\n            else if (tmp == \'3\' || tmp == \'6\')\r\n                liner_txt = \"<span style=\'color:blue;\'>X-Linked Polyethylene</span> liner was placed.\"\r\n            else if (tmp == \'4\')\r\n                liner_txt = \"<span style=\'color:blue;\'>Ceramic</span> liner was placed.\"\r\n            \r\n            if (tmp == \'4\' || tmp == \'5\' || tmp == \'6\')\r\n                head_txt = \'Ceramic\'\r\n        }\r\n        \r\n        t_pos = \'\';\r\n        i_pos = $(\'#data-position\').val();\r\n        if (i_pos != undefined) {\r\n            t_pos = master[\'<%=this.table_name%>\'][\'position\'][i_pos];\r\n        }\r\n        \r\n        t_app = \'\';\r\n        i_app = $(\'#data-approach\').val();\r\n        if (i_app != undefined) {\r\n            t_app = master[\'<%=this.table_name%>\'][\'approach\'][i_app];\r\n        }\r\n        \r\n        screw_txt = \'\'\r\n        i_scr = $(\'#data-screws\').val();\r\n        if (i_scr == \'1\')\r\n            screw_txt = \'Screws was used to reinforced cup placement.\'\r\n        \r\n        cement_txt = \'\'\r\n        i_cem = $(\'#data-cement\').val();\r\n        if (i_cem == \'1\')\r\n            cement_txt = \'Femoral cannal was copiously irrigated and then suctioned it dry. Cement technique was used to install final femoral component.\'\r\n        else if (i_cem == \'0\')\r\n            cement_txt = \'Cementless technique was used to install final femoral component.\'\r\n        \r\n        t_cup = $(\'#data-cup_size\').val() != \'\' ? $(\'#data-cup_size\').val() : \'-none-\';\r\n        t_head = $(\'#data-head_diameter\').val() != \'\' ? $(\'#data-head_diameter\').val() : \'-none-\';\r\n        \r\n        var gen_text = txt_temp.replace(\"\\\\#{render_value(\'position\')}\", t_pos)\r\n            .replace(\"\\\\#{render_value(\'approach\')}\", t_app)\r\n            .replace(\"\\\\#{head_txt}\", head_txt)\r\n            .replace(\"\\\\#{screw_txt}\", screw_txt)\r\n            .replace(\"\\\\#{cement_txt}\", cement_txt)\r\n            .replace(\"\\\\#{liner_txt}\", liner_txt)\r\n            .replace(\'\\\\#{cup_size}\', t_cup)\r\n            .replace(\'\\\\#{diameter}\', t_head);\r\n\r\n        var editor = $(\"#data-operative_note\").data(\"kendoEditor\");\r\n        if (typeof(editor)) {\r\n             editor.value(gen_text);\r\n        }\r\n\r\n        \r\n        \r\n        console.log(gen_text);\r\n    }\r\n    $(\'#btn-generate\').click(generate_opnote);\r\n</script>',NULL,NULL,NULL,'2015-08-08 18:31:48','2015-08-08 18:31:48','opnote',''),(1753,'test_inline',689,3,'<h3>Now : </h3><%= Time.now %>',NULL,NULL,NULL,'2015-08-09 03:13:20','2015-08-09 03:13:20','test_inline',''),(1754,'print_pgh',600,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    logo = false\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    # age\r\n    today = Date.today\r\n    d = Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day)\r\n    age = d.year - r_pat[:birth_date].year - (d > today ? 1 : 0)\r\n    \r\n\r\n    \r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n    \r\n#     liner_txt = \'\'\r\n#     head_txt = \'Metal\'\r\n#     tmp = this_rec[:bearing_surface_type]\r\n#     if tmp == \'1\' or tmp == \'5\'\r\n#         liner_txt = \'<v>Polyethylene</v> liner was placed.\'\r\n#     elsif tmp == \'3\' or tmp == \'6\'\r\n#         liner_txt = \'<v>X-Linked Polyethylene</v> liner was placed.\'\r\n#     elsif tmp == \'4\'\r\n#         liner_txt = \'<v>Ceramic</v> liner was placed.\'\r\n#     end\r\n#     if tmp == \'4\' or tmp == \'5\' or tmp == \'6\'\r\n#         head_txt = \'Ceramic\'\r\n#     end\r\n    \r\n#     screw_txt = \'\'\r\n#     if this_rec[:screws] == \'1\'\r\n#         screw_txt = \'Screws was used to reinforced cup placement.\'\r\n#     end\r\n    \r\n#     cement_txt = \'\'\r\n#     if this_rec[:cement] == \'1\'\r\n#         cement_txt = \'Femoral cannal was copiously irrigated and then suctioned it dry.  Cement technique was used to install final femoral component.\'\r\n#     else\r\n#         cement_txt = \'Cementless technique was used to install final femoral component.\'\r\n#     end\r\n\r\n#     txt = \"The patient was set in <v>\\#{render_value(\'position\')}</v> position. Skin incision was performed, and <v>\\#{render_value(\'approach\')}</v> approach was done.\r\n# Capsulotomy was done using Bovie cautery.\r\n# Femoral head was dislocated and removed.\r\n# Acetabulum was identified, osteophyte around the rim of the acetabulum was removed\r\n# Acetabulum component was prepared and placed in approximately 45 degrees of abduction and 10 to 15 degrees of anteversion.\r\n# Stability of the acetabular compoment was evaluated.<br/>\r\n# \\#{liner_txt} \\#{screw_txt} <br/>\r\n# Reamers and broaches were used to prepare femoral cannal.\r\n# Femoral component trial was used to evaluate for a appropriate press-fit.\r\n# Femoral component trial was then reduced into the acetabulum to test for appropriate neck length, tension, and range of motion as well as ligamentous stability.\r\n\r\n# After the appropriate femoral component has been confirmed, <v>\\#{cement_txt}</v> <br/>\r\n# <v>\\#{head_txt}</v> femoral head was assembled to the final femoral stem. \r\n# Finally, the hip was reduced, bleeding and instruments were checked.  And capsules and muscles were repaired respectively.\r\n# Vacuum drain was placed, and Skin were closed.\r\n# \".html_safe\r\n\r\n    m_provider = m_pat_mod.where(:module_name=>\"\\#{@current_project.name}#provider\", :patient_id=>r_pat.id).first\r\n    r_provider = model[:provider].find(m_provider[:module_id])\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        res[:pat_mod_provider] = m_provider\r\n        res[:provider] = r_provider\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n<html>\r\n\r\n<head>\r\n<meta http-equiv=Content-Type content=\"text/html; charset=utf-8\">\r\n<meta name=Generator content=\"Microsoft Word 14 (filtered)\">\r\n<style>\r\nv {\r\n    color : blue;\r\n}\r\n<!--\r\n /* Font Definitions */\r\n @font-face\r\n	{font-family:\"Cordia New\";\r\n	panose-1:2 11 3 4 2 2 2 2 2 4;}\r\n@font-face\r\n	{font-family:\"Cordia New\";\r\n	panose-1:2 11 3 4 2 2 2 2 2 4;}\r\n@font-face\r\n	{font-family:Calibri;\r\n	panose-1:2 15 5 2 2 2 4 3 2 4;}\r\n /* Style Definitions */\r\n p.MsoNormal, li.MsoNormal, div.MsoNormal\r\n	{margin-top:0in;\r\n	margin-right:0in;\r\n	margin-bottom:10.0pt;\r\n	margin-left:0in;\r\n	line-height:115%;\r\n	font-size:11.0pt;\r\n	font-family:\"Calibri\",\"sans-serif\";}\r\n.MsoChpDefault\r\n	{font-family:\"Calibri\",\"sans-serif\";}\r\n.MsoPapDefault\r\n	{margin-bottom:10.0pt;\r\n	line-height:115%;}\r\n@page WordSection1\r\n	{size:8.5in 11.0in;\r\n	margin:1.0in 1.0in 1.0in 1.0in;}\r\ndiv.WordSection1\r\n	{page:WordSection1;}\r\n-->\r\n</style>\r\n\r\n</head>\r\n\r\n<body lang=EN-US>\r\n\r\n	<div class=WordSection1>\r\n\r\n		<!--<p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;-->\r\n		<!--text-align:center;line-height:normal\'><span style=\'font-size:20.0pt\'>OPERATIVE-->\r\n		<!--NOTE</span></p>-->\r\n		<% if logo %>\r\n		<table class=MsoTableGrid border=0 cellspacing=0 cellpadding=0\r\n		 style=\'border-collapse:collapse;border:none\'>\r\n		 <tr>\r\n		  <td width=100% valign=top style=\'width:6.2in;border:none windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  \r\n		<p class=MsoNormal align=left style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n		text-align:left;line-height:normal\'>\r\n		    <span style=\'font-size:20.0pt\'>OPERATIVE NOTE</span>\r\n		    <!--<span style=\"float:right\"><img src=\"/esm/taig/www/content/lgpgh01.png\" height=\"30px\"/></span>        -->\r\n		</p>\r\n		    </td>\r\n		    <td><span style=\"float:right\"><img src=\"/esm/taig/www/content/lgpgh01.png\" height=\"50px\"/></span>        </td>\r\n		    </tr>\r\n		    </table>\r\n		    \r\n		<% else %>\r\n		<p class=MsoNormal align=left style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n		text-align:left;line-height:normal\'>\r\n		    <span style=\'font-size:20.0pt\'>OPERATIVE NOTE</span>\r\n		    <!--<span style=\"float:right\"><img src=\"/esm/taig/www/content/lgpgh01.png\" height=\"30px\"/></span>        -->\r\n		</p>\r\n		<% end %>\r\n		\r\n\r\n		<p class=MsoNormal align=center style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n		text-align:center;line-height:normal\'>&nbsp;</p>\r\n\r\n		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>                                                                                                                                Name\r\n		: <v><%= r_pat[:first_name] %>&nbsp;&nbsp;&nbsp;&nbsp;<%= r_pat[:last_name] %></v></p>\r\n\r\n		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>                                                                                                                                H.N.\r\n		: <v><%= r_pat[:hn] %></v></p>\r\n\r\n		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>                                                                                                                                Age\r\n		: <v><%= age %></v> Ward : ………………</p>\r\n\r\n		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>                                                                                                                                Admission\r\n		date : ……………………………</p>\r\n\r\n		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>                                                                                                                                Date\r\n		of operation : <v><%= render_value(\'operation_date\') %></v></p>\r\n\r\n		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>&nbsp;</p>\r\n\r\n		<table class=MsoTableGrid border=1 cellspacing=0 cellpadding=0\r\n		 style=\'border-collapse:collapse;border:none\'>\r\n		 <tr>\r\n		  <td width=638 colspan=3 valign=top style=\'width:6.65in;border:solid windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><strong>Pre / Post operative diagnosis : </strong><v><%= render_value(\'indication_for_surgery\') %></v></p>\r\n		  </td>\r\n		 </tr>\r\n		 <!--<tr>-->\r\n		 <!-- <td width=638 colspan=3 valign=top style=\'width:6.65in;border:solid windowtext 1.0pt;-->\r\n		 <!-- border-top:none;padding:0in 5.4pt 0in 5.4pt\'>-->\r\n		 <!-- <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:-->\r\n		 <!-- normal\'>Post operative diagnosis : <v><%# this_rec[:post_operative_diag] %></v></p>-->\r\n		 <!-- </td>-->\r\n		 <!--</tr>-->\r\n		 <tr>\r\n		  <td width=638 colspan=3 valign=top style=\'width:6.65in;border:solid windowtext 1.0pt;\r\n		  border-top:none;padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><b>Operation :</b>&nbsp;&nbsp;<v><%= render_value(\'procedure\') %></v></p>\r\n		  </td>\r\n		 </tr>\r\n		 <tr>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border-top:none;border-left:\r\n		  solid windowtext 1.0pt;border-bottom:solid windowtext 1.0pt;border-right:\r\n		  none;padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  </td>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border:none;border-bottom:solid windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  </td>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border-top:none;border-left:\r\n		  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  </td>\r\n		 </tr>\r\n		 <tr>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border:solid windowtext 1.0pt;\r\n		  border-top:none;padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><b>Anesthesiologist</b></p>\r\n		  </td>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border:none;border-bottom:solid windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><b>Surgeon Assistant</b></p>\r\n		  </td>\r\n		  <td width=213 valign=top style=\'width:159.6pt;border-top:none;border-left:\r\n		  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>  </p>\r\n		  </td>\r\n		 </tr>\r\n		 <tr>\r\n		  <td width=638 colspan=3 valign=top style=\'width:6.65in;border:solid windowtext 1.0pt;\r\n		  border-top:none;padding:0in 5.4pt 0in 5.4pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><b>Operative finding(s)</b></p>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>\r\n		    <br/>&nbsp;&nbsp;&nbsp;\r\n<%\r\n    if this_rec[:image].count > 0\r\n        x = 1\r\n        for i in this_rec[:image] do\r\n            if x <= 4\r\n%>\r\n		      <img src=\"https://emr-life.com/content/esm/taig/taig/content/knee1/image/<%= i %>.png?<%= i %>&thumb=1\"/>&nbsp;\r\n<%\r\n            end\r\n            x += 1\r\n        end\r\n    end\r\n%>\r\n		  </p>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  </td>\r\n		 </tr>\r\n		 <tr>\r\n		  <td width=638 colspan=3 valign=top style=\'width:6.65in;border:solid windowtext 1.0pt;\r\n  border-top:none;padding:0in 5.4pt 0in 5.4pt;height:256.0pt\'>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'><b>Operative procedures, diagram, etc</b></p>\r\n		  \r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:normal;font-size:.7em\'>\r\n		    &nbsp;&nbsp;&nbsp;&nbsp;<%= this_rec[:operative_note].html_safe %>\r\n		  </p>\r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  \r\n		  <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;line-height:\r\n		  normal\'>&nbsp;</p>\r\n		  </td>\r\n		 </tr>\r\n		</table>\r\n        <p></p>\r\n        <table class=MsoTableGrid border=0 cellspacing=0 cellpadding=0\r\n		 style=\'border-collapse:collapse;border:none\'>\r\n		 <tr>\r\n		  <td width=100% valign=top style=\'width:5.9in;border:none windowtext 1.0pt;\r\n		  padding:0in 5.4pt 0in 5.4pt\'>\r\n		       <p class=MsoNormal align=left style=\'margin-bottom:0in;margin-bottom:.0001pt;\r\n		            text-align:left;line-height:normal\'>\r\n		            <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>&nbsp;</p>\r\n    		        <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Signature : ……………………………………..</p>\r\n    		        <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Surgeon : <v><%= r_provider[:name] if r_provider %></v></p>\r\n    		        <p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Printed date : <v><%= Time.now.strftime(\"%d/%m/%y %H:%M\") %></v></p>\r\n		        </p>\r\n		    </td>\r\n		    <td><span style=\"float:right\"><img src=\"/esm/taig/www/content/thks.png\" height=\"90px\"/></span>        </td>\r\n		    </tr>\r\n		</table>\r\n<!--\r\n        <div style=\"display:inline\">\r\n            <div style=\"float:left\">\r\n    		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>&nbsp;</p>\r\n    \r\n    		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Signature : ……………………………………..</p>\r\n    		\r\n    		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Surgeon : <v><%= r_provider[:name] if r_provider %></v></p>\r\n    \r\n    		<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt\'>Printed date : <v><%= Time.now.strftime(\"%d/%m/%y %H:%M\") %></v></p>\r\n            </div>\r\n            <div style=\"float:right\">\r\n                <img src=\"/esm/taig/www/content/thks.png\" width=\"100px\"/>\r\n            </div>\r\n        </div>\r\n-->\r\n	</div>\r\n<script>\r\n    // window.print()\r\n</script>\r\n</body>\r\n\r\n</html>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2015-08-09 08:04:37','2015-08-09 08:04:37','print_pgh',''),(1755,'opnote',600,4,'\r\n<script>\r\n    // var map_text = {\'position\':\'none\', \'approach\':\'none\'};\r\n    var txt_temp = \"<p class=\'MsoNormal\'>The patient was set in Supine position. Skin incision was performed, and <span style=\'color:blue\'>\\\\#{render_value(\'approach\')}</span> approach was done. \\\\#{first_bone_txt}. </p>\\\r\n<p class=\'MsoNormal\'>Extension gap was evaluated. \\\r\nFemoral size was measured. \\\r\nThen bone cut was done using the measured femoral size cutting block. \\\r\nModified gap technique was used to evaluated the balanced of ligaments and bone cuts. \\\r\nBoth Femoral trial component and tibial trial component were assembled then evaluated for balanced of ligaments and bone cuts. \\\r\nTibial size was measured. \\\r\n<span style=\'color:blue\'>\\\\#{patellar_txt}</span>.</p> \\\r\n<br/><br/> \\\r\n<p class=\'MsoNormal\'>Femur size : <span style=\'color:blue\'>\\\\#{femur_size}</span>, Tibia size : <span style=\'color:blue\'>\\\\#{tibia_size}</span>, Polyethylene size : <span style=\'color:blue\'>\\\\#{polyethylene_size}</span> and Patella size : <span style=\'color:blue\'>\\\\#{patella_size}</span></p>\";\r\n    function opnote() {\r\n        var editor = $(\"#data-operative_note\").data(\"kendoEditor\");\r\n        if (typeof(editor)) {\r\n             val = editor.value();\r\n             if (val.trim() == \'\') {\r\n                //  alert(\'no text\');\r\n                 this.generate_opnote();\r\n             }\r\n        }\r\n    }\r\n    function generate_opnote() {\r\n        // alert(\'generate opnote\');\r\n        // tmp = $(\'#data-mechanical\').val();\r\n        // console.log(\"machanic : \" + master.<%=this.table_name%>.mechanical[\'3\']+ \" <-- \" + tmp);\r\n        // console.log(\"asa_grade: \" + master.<%=this.table_name%>.patient_asa_grade[tmp]);\r\n        // console.log(master[\'hip1\'][\'position\'][\'1\']);\r\n        first_bone_txt = \'\'\r\n        i_fbone = $(\'#data-first_bone_cut\').val();\r\n        if (i_fbone == \'1\') {\r\n            first_bone_txt = \'<span style=\"color:blue\">Distal Femur</span> bone cut technique was perform first.  Then <span style=\"color:blue\">Proximal Tibia</span> bone cut technique was perform\';\r\n        } else if (i_fbone == \'2\') {\r\n            first_bone_txt = \'<span style=\"color:blue\">Proximal Tibia</span> bone cut technique was perform first.  Then <span style=\"color:blue\">Distal Femur</span> bone cut technique was perform\';\r\n        }\r\n        \r\n        t_app = \'\';\r\n        i_app = $(\'#data-approach\').val();\r\n        if (i_app != undefined) {\r\n            t_app = master[\'<%=this.table_name%>\'][\'approach\'][i_app];\r\n        }\r\n        \r\n        t_fem = $(\'#data-femoral_size\').val() != \'\' ? $(\'#data-femoral_size\').val() : \'-none-\';\r\n        t_tib = $(\'#data-tibial_size\').val() != \'\' ? $(\'#data-tibial_size\').val() : \'-none-\';\r\n        t_pol = $(\'#data-polyethylene_size\').val() != \'\' ? $(\'#data-polyethylene_size\').val() : \'-none-\';\r\n        t_par = $(\'#data-patella_size\').val() != \'\' ? $(\'#data-patella_size\').val() : \'-none-\';\r\n        \r\n        t_pattellar = \'\'\r\n        i_pat = $(\'#data-patellar_component\').val();\r\n        if (i_pat == \'1\') {\r\n            t_pattellar = \"<span style=\'color:blue\'>\" + \'Patellar size was measured, and prepared\' + \"</span>\";\r\n        } else if (i_pat == \'0\') {\r\n            t_pattellar = \"<span style=\'color:blue\'>\" + master[\'<%=this.table_name%>\'][\'patellar_component_reason\'][$(\'#data-patellar_component_reason\').val()] + \"</span>\";\r\n        }\r\n        \r\n        var gen_text = txt_temp\r\n            .replace(\"\\\\#{render_value(\'approach\')}\", t_app)\r\n            .replace(\"\\\\#{first_bone_txt}\", first_bone_txt)\r\n            .replace(\"\\\\#{patellar_txt}\", t_pattellar)\r\n            .replace(\"\\\\#{femur_size}\", t_fem)\r\n            .replace(\"\\\\#{tibia_size}\", t_tib)\r\n            .replace(\"\\\\#{polyethylene_size}\", t_pol)\r\n            .replace(\"\\\\#{patella_size}\", t_par);\r\n        \r\n        var editor = $(\"#data-operative_note\").data(\"kendoEditor\");\r\n        if (typeof(editor)) {\r\n             editor.value(gen_text);\r\n        }\r\n        // console.log(gen_text);\r\n    }\r\n    $(\'#btn-generate\').click(generate_opnote);\r\n</script>',NULL,NULL,NULL,'2015-08-09 08:23:12','2015-08-09 08:23:12','opnote',''),(1756,'create',605,2,'<%\r\n    show_color = false\r\n%>\r\n<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n        locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n        if locker \r\n            if locker.session!= session[:user].to_s\r\n    %>\r\n    <!--<script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>-->\r\n    <%\r\n            end\r\n        elsif session[:user] and session[:user]!=\'\' \r\n    \r\n            locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n        end\r\n    \r\n    end\r\n    \r\n    # map procedure\r\n    zmodels = get_model\r\n    zm_procedure = zmodels[:procedure].all\r\n    zmap_proc = {}\r\n    for m in zm_procedure do\r\n        zmap_proc[m.id.to_s] = {:name=>m[:name], :code=>m[:code]}\r\n    end\r\n    zehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    zehr_models = zehr.get_model\r\n    zm_patient_module = zehr_models[:patient_module]\r\n    \r\n    zpm = zm_patient_module.find(params[:parent_id])\r\n    # zm_ap = zm_patient_module.where(:id=>zpm[:parent_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\").first\r\n    zap = zmodels[:appointment].find(zpm[:module_id])\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<!--New <%=this.table_name.to_s.humanize%>-->\r\n<h3><strong>New <%# zmap_proc[zap[:procedure].to_s][:name] %>(<%= zmap_proc[zap[:procedure].to_s][:name] %>)</strong></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n<div style=\"border:0px solid;<%= \"background-color:\\\\#{this.color_name};\" if show_color %>\">\r\n<!--<div class=\"document-border\" style=\"border:0px solid\">-->\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<%\r\n    show_url = \"show?id=\\\\#{m.id}\".html_safe\r\n    if params[:record][:bilateral] == \'1\'\r\n    # if params[:b] == \'1\'\r\n        # params[:next_service] = \"../\\\\#{s}/create?patient_id=\\\\#{params[:patient_id]}&b=\\\\#{b}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{m.id}&return=\\\\#{params[:return]}\"\r\n        show_url += \"&b=1&s=\\\\#{params[:record][:side]}&patient_id=\\\\#{params[:patient_id]}&record_name=\\\\#{params[:record_name]}&parent_id=\\\\#{params[:parent_id]}\".html_safe\r\n    else\r\n        show_url = return_url\r\n    end\r\n    if !return_url.empty?\r\n        show_url += \"&return=\\\\#{return_url}\".html_safe\r\n    end\r\n%>\r\n<% if  @appointment %>\r\n// zam remove comment\r\n// window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"<%=show_url%>\";\r\n\r\n<% else %>\r\n// zam remove comment\r\nwindow.location = \"../Home/index\";\r\n<% end %>\r\n// zam add comment\r\nwindow.location = \"<%=show_url%>\";\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n<%\r\n    if params[:b]\r\n%>\r\n<%= hidden_field_tag :b, params[:b] %>\r\n<%\r\n    end\r\n%>\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\' %> \r\n<%= hidden_field_tag \'ref_number\',ref_number %> \r\n<%= hidden_field_tag \'date\',Time.now %> \r\n<%= hidden_field_tag \'time\',Time.now.strftime(\"%H:%M\") %> \r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=request.fullpath%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n        // alert(\"URL \" + url);\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  //$(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe, :onclick=>\'javascript:opnote()\', :class=>\'btn btn-small btn-success\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\', :class=>\'btn btn-small\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<%# if @current_role == \'developer\' %>\r\n<%= render :inline=>this.opnote, :locals=>{:this=>this} %>\r\n<%# end %>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n\r\n<%\r\n    # auto check left/right\r\n    if params[:s] != \'0\'\r\n%>\r\n<script>\r\n    $(document).ready(function() {\r\n        // console.log( \"ready!\" );\r\n        $(\"#data-side\").val(\'2\');\r\n        $(\"#update_side_item_<%= params[:s].to_i - 1 %>\").prop(\'checked\', true);\r\n        $(\"#bilateral\").hide();\r\n        // console.log(\'Ok\');\r\n    });\r\n</script>\r\n\r\n<%\r\n    end\r\n%>\r\n<script>\r\n    window.history.forward();\r\n    window.onload = function()\r\n    {\r\n        // console.log(\'...Loaded...\');\r\n        // console.log(\"HISTORY : \" + history.length + \", prev : \" + history.previous);\r\n        window.history.forward();\r\n    };\r\n    window.onunload = function() {\r\n        // console.log(\'...un Loaded...\');\r\n        null;\r\n    };\r\n    window.onpopstate = function(event) {\r\n        alert(\"location: \" + document.location);\r\n    }\r\n</script>\r\n',NULL,NULL,NULL,'2015-08-09 16:18:51','2015-08-09 16:18:51','create',''),(1757,'opnote',605,4,'\r\n<script>\r\n    // var map_text = {\'position\':\'none\', \'approach\':\'none\'};\r\n    var txt_temp = \"<p class=\'MsoNormal\'>The patient was set in Supine position. Skin incision was performed, and <span style=\'color:blue\'>\\\\#{render_value(\'approach\')}</span> approach was done.</p>\\\r\n<p class=\'MsoNormal\'>Femoral and Tibial components were removed, then scrub and debridement were performed. \\\r\nFemoral and tibial size were measured as well as ligaments and bone lost were evaluated. \\\r\nBoth extension and flextion gaps were evaluated. \\\r\nThen femoral trial component and tibial trial component were assembled then evaluated for balanced of ligaments and bone cuts.</p>\";\r\n    \r\n    function opnote() {\r\n        var editor = $(\"#data-operative_note\").data(\"kendoEditor\");\r\n        if (typeof(editor)) {\r\n             val = editor.value();\r\n             if (val.trim() == \'\') {\r\n                //  alert(\'no text\');\r\n                 this.generate_opnote();\r\n             }\r\n        }\r\n    }\r\n    function generate_opnote() {\r\n        // alert(\'generate opnote\');\r\n        // tmp = $(\'#data-mechanical\').val();\r\n        // console.log(\"machanic : \" + master.<%=this.table_name%>.mechanical[\'3\']+ \" <-- \" + tmp);\r\n        // console.log(\"asa_grade: \" + master.<%=this.table_name%>.patient_asa_grade[tmp]);\r\n        // console.log(master[\'hip1\'][\'position\'][\'1\']);\r\n        t_app = \'\';\r\n        i_app = $(\'#data-approach\').val();\r\n        if (i_app != undefined) {\r\n            t_app = master[\'<%=this.table_name%>\'][\'approach\'][i_app];\r\n        }\r\n        \r\n        var gen_text = txt_temp\r\n            .replace(\"\\\\#{render_value(\'approach\')}\", t_app);\r\n        \r\n        var editor = $(\"#data-operative_note\").data(\"kendoEditor\");\r\n        if (typeof(editor)) {\r\n             editor.value(gen_text);\r\n        }\r\n        \r\n        // console.log(gen_text);\r\n    }\r\n    $(\'#btn-generate\').click(generate_opnote);\r\n</script>',NULL,NULL,NULL,'2015-08-09 16:42:56','2015-08-09 16:42:56','opnote',''),(1758,'opnote',604,4,'\r\n<script>\r\n    // var map_text = {\'position\':\'none\', \'approach\':\'none\'};\r\n    var txt_temp = \"<p class=\'MsoNormal\'>The patient was set in <span style=\'color:blue;\'>\\#{render_value(\'position\')}</span> position. \\\r\nSkin incision was performed, and <span style=\'color:blue;\'>\\#{render_value(\'approach\')}</span> approach was done. \\\r\nCapsulotomy was done using Bovie cautery. \\\r\nFemoral component was dislocated. Previous femoral head and stem were removed. \\\r\nScurb and debridment were performed.  Debris tissue and metal debris were removed. \\\r\nAcetabular cup was identified, then acetabular component and liner were removed. Bone lost were evaluated \\\r\nAcetabulum component was prepared to be placed in approximately 45 degrees of abduction and 10 to 15 degrees of anteversion. \\\r\nStability of the acetabular component was evaluated.</p>\";\r\n    function opnote() {\r\n        var editor = $(\"#data-operative_note\").data(\"kendoEditor\");\r\n        if (typeof(editor)) {\r\n             val = editor.value();\r\n             if (val.trim() == \'\') {\r\n                //  alert(\'no text\');\r\n                 this.generate_opnote();\r\n             }\r\n        }\r\n    }\r\n    function generate_opnote() {\r\n        // alert(\'generate opnote\');\r\n        // tmp = $(\'#data-mechanical\').val();\r\n        // console.log(\"machanic : \" + master.<%=this.table_name%>.mechanical[\'3\']+ \" <-- \" + tmp);\r\n        // console.log(\"asa_grade: \" + master.<%=this.table_name%>.patient_asa_grade[tmp]);\r\n        // console.log(master[\'hip1\'][\'position\'][\'1\']);\r\n        t_pos = \'\';\r\n        i_pos = $(\'#data-position\').val();\r\n        if (i_pos != undefined) {\r\n            t_pos = master[\'<%=this.table_name%>\'][\'position\'][i_pos];\r\n        }\r\n        \r\n        t_app = \'\';\r\n        i_app = $(\'#data-approach\').val();\r\n        if (i_app != undefined) {\r\n            t_app = master[\'<%=this.table_name%>\'][\'approach\'][i_app];\r\n        }\r\n        \r\n        var gen_text = txt_temp.replace(\"\\#{render_value(\'position\')}\", t_pos)\r\n            .replace(\"\\#{render_value(\'approach\')}\", t_app);\r\n\r\n        var editor = $(\"#data-operative_note\").data(\"kendoEditor\");\r\n        if (typeof(editor)) {\r\n             editor.value(gen_text);\r\n        }\r\n        \r\n        // console.log(gen_text);\r\n    }\r\n    $(\'#btn-generate\').click(generate_opnote);\r\n</script>',NULL,NULL,NULL,'2015-08-09 16:55:26','2015-08-09 16:55:26','opnote',''),(1765,'document_name',775,1,'\'post_anesthetic_bk\'',NULL,NULL,NULL,'2015-08-15 09:51:25','2015-08-15 09:51:25',NULL,NULL),(1766,'sumgroup',775,1,'{\r\n	:total_preop => {\r\n		:select => [:activity_preop, :respiration_preop, :circulation_preop, :consciousness_preop, :oxygen_saturation_preop],\r\n		:total => :total_mass_preop\r\n	},\r\n	:total_admit => {\r\n		:select => [:activity_admit, :respiration_admit, :circulation_admit, :consciousness_admit, :oxygen_saturation_admit],\r\n		:total => :total_mass_admit\r\n	},\r\n	:total_15 => {\r\n		:select => [:activity_15, :respiration_15, :circulation_15, :consciousness_15, :oxygen_saturation_15],\r\n		:total => :total_mass_15\r\n	},\r\n	:total_30 => {\r\n		:select => [:activity_30, :respiration_30, :circulation_30, :consciousness_30, :oxygen_saturation_30],\r\n		:total => :total_mass_30\r\n	},\r\n	:total_45 => {\r\n		:select => [:activity_45, :respiration_45, :circulation_45, :consciousness_45, :oxygen_saturation_45],\r\n		:total => :total_mass_45\r\n	},\r\n	:total_60 => {\r\n		:select => [:activity_60, :respiration_60, :circulation_60, :consciousness_60, :oxygen_saturation_60],\r\n		:total => :total_mass_60\r\n	},\r\n	:total_ward => {\r\n		:select => [:activity_ward, :respiration_ward, :circulation_ward, :consciousness_ward, :oxygen_saturation_ward],\r\n		:total => :total_mass_ward\r\n	}\r\n}',NULL,NULL,NULL,'2015-08-15 09:52:05','2015-08-15 09:52:05','sumgroup',''),(1767,'update_status_with_user',717,3,'<%\r\n    date = \"\"\r\n    ap = get_model[:appointment].find(params[:id])\r\n    if ap\r\n        ap.update_attributes :status=>params[:status], :updated_by=>params[:updated_by]\r\n%>\r\nupdated\r\n<%\r\n    end \r\n%>\r\n',NULL,NULL,NULL,'2015-08-20 16:40:52','2015-08-20 16:40:52','update_status_with_user',''),(1768,'print_partial',492,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    id = pm.module_id\r\n    record = models[this.document_name.to_sym].find(id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:100px;min-height:100px;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'<%=@current_project.get_setting(\"logo_report_path\")%>\' height=\"70px\" style=\"Float:left,top:5px\" /></div><h3> <strong><%=@current_service.title %> Diagnosis Report<br />\r\n<%=@current_project.get_setting(\"report_title_1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%>\r\n  </strong></h3>\r\n</center>\r\n\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> ชื่อ-สกุล : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'ไม่ระบุ\'\r\n    if patient.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>เพศ : </strong><%= gender %> &nbsp; <strong>อายุ :&nbsp;</strong>\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D-->\r\n      <br /><strong>Date :  </strong> <%=render_value \'start_procedural_date\'%> <strong>Produral Time :  </strong> <%=render_value \'start_procedural_time\'%> - <%=render_value \'stop_procedural_time\'%> Total Time :  <%=render_value \'procedural_time\'%>  <strong>Project : </strong> <%=render_value \'study_project\'%>\r\n    <br /><strong>Endoscopist : </strong><%=render_value \'endoscopist\'%>  , <strong>Endoscopist assist : </strong><%=render_value \'assist1endoscopist\'%> <%=render_value \'assist2endoscopist\'%> \r\n    <br /><strong>Nurse : </strong><%=render_value \'nurse\'%> , <strong>Nurse assist : </strong><%=render_value \'assist_1_nurse\'%><%=render_value \'assist_2_nurse\'%>\r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n &nbsp;&nbsp;&nbsp;<strong>Indication : </strong><%=render_value \'clinical_indication\'%><% if record[\'other_indication_note\']!=\'\' %> : <%=render_value \'other_indication_note\'%><% end %>\r\n	\r\n	<hr />\r\n    \r\n    <%\r\n        # atts = models[:attachment].find(record.image)\r\n        atts = record.image[0..4].compact.collect{|i| models[:attachment].find(i)}\r\n\r\n\r\n    %>\r\n\r\n\r\n<style>\r\n<% if @current_solution.name!=\'gi\' %>\r\n.crop {\r\n    width: 250px;\r\n    height: 180px;\r\n    overflow: hidden;\r\n    margin-bottom:10px;\r\n}\r\n\r\n.crop img {\r\n    width: 320px;\r\n    height: 190px;\r\n    margin: 0px 0px 0px -110px;\r\n}\r\n<% else %>\r\n.crop {\r\n    width: 240px;\r\n    height: 165px;\r\n    margin:5px;\r\n}\r\n\r\n.crop img {\r\n    width: 240px;\r\n    height: 165px;\r\n}\r\n<% end %>\r\n    \r\n</style>\r\n    <div style=\"float:right;  width: 280px;  padding: 5px; text-align:center; font-size:14px;\">\r\n    <% for i in atts  %>\r\n    <div class=\"crop\">\r\n    <img src=\"<%=i.path%>\" /><br /><%=i.title%><br />\r\n    </div>\r\n    <% end %>\r\n\r\n   \r\n    \r\n    </div>\r\n<div style=\"float:left\">\r\n\r\n\r\n<table width=\"550\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr><td valign=\"top\"><strong>Consent</strong></td><td>The procedure of the examination, including possible complications were clearly and discussed with the patient and family, then a consent form was signed by the patient and/or family</td></tr>\r\n<tr><td valign=\"top\"><strong>Procedure</strong></td>\r\n  <td>The patient\'s blood pressure, pulse and oxygen saturation were montiored ontinuously throghout the procedure. the scope was passed under direct vision through the anus and advanced to the colon. The endoscopy was accomplished without difficulty. The findings were described below. The patient tolerated the procedure well.</td></tr>\r\n</table>\r\n<div class=\"clear\"></div>\r\n\r\n<%= render :inline=>this.display %>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n<strong>Reported by :</strong>&nbsp;<%= @current_user.login.humanize if @current_user %><br />\r\n<strong>Printed Date Time :</strong>&nbsp;<%=render_value \'date_approve\' %> <%=render_value \'time_approve\'%>\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong><% if record[\'approve\']!=\"\" %>Approved<% end %> By :</strong> \r\n<%=render_value \'endoscopist_approve\'%> (Gastroenterologist)\r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n<script>\r\n\r\n<%\r\n        require \'csv\'\r\n        icd10_list = {}\r\n        CSV.foreach(File.join(Dir.pwd,\'public\',\'/esm/cusys/med/icd-10.csv\')) do |row|\r\n           icd10_list[row[0]]=row[1] \r\n        end\r\n        \r\n%>\r\n  \r\n    var icd10_list = <%=icd10_list.to_json.html_safe%>\r\n    obj = $(\'#data-icd10\')\r\n    console.log(obj)\r\n    if(typeof(obj)!=\'undefined\'&&obj.val()!=\'\'){\r\n    icd = obj.val()\r\n    licd = icd.split(\'|\')\r\n    div = $(\'#diagnosis-div\')\r\n    tr = div.parent().parent()\r\n    icd = $(\"<tr>\").append(\"<td><strong>ICD</strong></td>\")\r\n    for(var id in licd){\r\n        i = licd[id]\r\n        icd.append($(\'<p>\').append(\"<v>\"+i+\"</v> : \"+icd10_list[i]))\r\n        \r\n    }\r\n    tr.after(icd)\r\n    \r\n    }\r\n    \r\n    \r\n    \r\n</script>\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2015-08-23 03:32:05','2015-08-23 03:32:05','print_partial',''),(1769,'status_board_patial',717,3,'<%\r\n    sample = false\r\n    if params[:sample] == \'true\'\r\n        sample = true\r\n    end\r\n    \r\n    date = Time.now\r\n    date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    # This model\r\n    model = get_model\r\n    \r\n    # map value\r\n    map_provider = {}\r\n    map_position = {}\r\n    map_or_room = {}\r\n    map_post_op = {}\r\n    map_ward = {}\r\n    map_instrument = {}\r\n    \r\n    map_or_room[\"\"]  = \"-\"\r\n    map_or_room[nil] = \"-\"\r\n    \r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:position].all do\r\n        map_position[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:or_room].all do\r\n        map_or_room[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:ward].all do\r\n        map_post_op[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:ward].all do\r\n        map_ward[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:instrument].all do\r\n        map_instrument[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    \r\n    m_app = model[:appointment]\r\n    \r\n    conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n    aps = m_app.all(conds)\r\n    aps = aps.sort_by{|i| [map_or_room[i[:or_room]], i[:start]]} if aps\r\n    list = []\r\n    list = aps.collect{|i|\r\n        r_pat_mod = m_pat_mod.where(:module_id=>i.id).first\r\n        if r_pat_mod\r\n            r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n            if r_pat\r\n                name = \"\\#{r_pat[:prefix_name]} \\#{r_pat[:first_name]}&nbsp;&nbsp&nbsp;\\#{r_pat[:last_name]}\".html_safe\r\n                \r\n                # age\r\n                today = Date.today\r\n                d = Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day)\r\n                age = d.year - r_pat[:birth_date].year - (d > today ? 1 : 0)\r\n                name += \" (\\#{age.to_s})\"\r\n                \r\n                {:time=>!i[:start].nil? ? i[:start].strftime(\'%H:%M\') : \'N/A\', :time_tf=>i[:time_tf], :status=>i[:status], :name=>name, :diagnosis=>i[:diagnosis], :operation=>i[:operation], :position=>map_position[i[:position]], :surgeon=>map_provider[i[:surgeon]], :assist=>map_provider[i[:assist]], :or_room=>map_or_room[i[:or_room]], :ward=>map_ward[i[:ward]], :post_op=>map_post_op[i[:post_op]], :instrument=>i[:instrument]}\r\n            end\r\n        end\r\n        # next\r\n        # r_pat_mod\r\n    }.compact\r\n    \r\n    # list = list.sort_by{|i| [map_or_room[i[:or_room]], i[:time]]}\r\n    \r\n    if sample\r\n        res = {}\r\n        res[:aps] = aps\r\n        res[:list] = list\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n         \r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<meta http-equiv=\"refresh\" content=\"60\" >\r\n<title>PATIENT STATUS</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml {\r\n\r\n  \r\n     }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px;  border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding:33px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   \r\n    font-family: Arial, Helvetica, sans-serif; color:#000;font-size:25px; background-color:##444444;\r\n}\r\n.wrapper{ width:95%;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:90%; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:100%;margin-left:auto;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n	color:#000;font-weight:bold;\r\n	font-size: 1em;\r\n}\r\n\r\ntable.table {\r\n    \r\n    color: #666;\r\n    font-size: 1em;\r\n    -moz-border-radius: 3px;\r\n    -moz-box-shadow: 0 1px 2px #d1d1d1;\r\n    -webkit-border-radius: 3px;\r\n    -webkit-box-shadow: 0 1px 2px #d1d1d1;\r\n    background: #eaebec;\r\n    border: #ccc 1px solid;\r\n    border-radius: 3px;\r\n    box-shadow: 0 1px 2px #d1d1d1;\r\n    font-family: Arial, Helvetica, sans-serif;\r\n    text-shadow: 1px 1px 0px #fff;\r\n}\r\n\r\ntable.table tr.even td {\r\n    background: #f6f6f6;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#f8f8f8), to(#f6f6f6));\r\n    background: -moz-linear-gradient(top, #f8f8f8, #f6f6f6);\r\n}\r\n\r\ntable.table th {\r\n    padding: 21px 25px 22px 25px;\r\n    border-bottom: 1px solid #e0e0e0; border-top: 1px solid #fafafa;\r\n    background: #ededed;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#ededed), to(#ebebeb));\r\n    background: -moz-linear-gradient(top, #ededed, #ebebeb);\r\n}\r\n\r\ntable.table th:first-child {\r\n    padding-left: 20px;\r\n    text-align: left\r\n}\r\n\r\ntable.table a:visited {\r\n    color: #999999;\r\n    font-weight: bold;\r\n    text-decoration: none\r\n}\r\n\r\ntable.table a:active,\r\ntable.table a:hover {\r\n    color: #bd5a35;\r\n    text-decoration: underline\r\n}\r\n\r\ntable.table a:link {\r\n    color: #666;\r\n    font-weight: bold;\r\n    text-decoration: none\r\n}\r\n\r\ntable.table tr {\r\n    padding-left: 20px;\r\n    text-align: center\r\n}\r\n\r\ntable.table tr:first-child th:first-child {\r\n    -moz-border-radius-topleft: 3px;\r\n    -webkit-border-top-left-radius: 3px;\r\n    border-top-left-radius: 3px;\r\n}\r\n\r\ntable.table tr:first-child th:last-child {\r\n    -moz-border-radius-topright: 3px;\r\n    -webkit-border-top-right-radius: 3px;\r\n    border-top-right-radius: 3px;\r\n}\r\n\r\ntable.table tr:last-child td {    border-bottom: 0 }\r\n\r\ntable.table tr:last-child td:first-child {\r\n    -moz-border-radius-bottomleft: 3px;\r\n    -webkit-border-bottom-left-radius: 3px;\r\n    border-bottom-left-radius: 3px;\r\n}\r\n\r\ntable.table tr:last-child td:last-child {\r\n    -moz-border-radius-bottomright: 3px;\r\n    -webkit-border-bottom-right-radius: 3px;\r\n    border-bottom-right-radius: 3px;\r\n}\r\n/*\r\ntable.table tr:hover td {\r\n    background: #f2f2f2;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#f2f2f2), to(#f0f0f0));\r\n    background: -moz-linear-gradient(top, #f2f2f2, #f0f0f0);\r\n}\r\n*/\r\ntable.table tr td {\r\n    padding: 18px;\r\n    border-bottom: 1px solid #e0e0e0; border-left: 1px solid #e0e0e0; border-top: 1px solid #ffffff;\r\n    background: #fafafa;\r\n    /*background: -webkit-gradient(linear, left top, left bottom, from(#fbfbfb), to(#fafafa));*/\r\n    /*background: -moz-linear-gradient(top, #fbfbfb, #fafafa);*/\r\n}\r\n\r\ntable.table tr td:first-child {\r\n    padding-left: 20px;\r\n    border-left: 0;\r\n}\r\n\r\ntable.table tr.appointed td {\r\n    /*color: gray;*/\r\n}\r\n.waiting {\r\n    background-color : DarkOrange ;\r\n    padding : 10px;\r\n    color : black;\r\n}\r\ntable.table tr.waiting td {\r\n    /*color: GoldenRod;*/\r\n    background-color : DarkOrange ;\r\n    color : black;\r\n    text-shadow : none ;\r\n}\r\n.operation {\r\n    padding : 10px;\r\n    background-color:FireBrick ;\r\n    color : white;\r\n}\r\ntable.table tr.operation td {\r\n    /*color:red;*/\r\n    background-color:FireBrick ;\r\n    color : white;\r\n    text-shadow : none ;\r\n}\r\n.recovery {\r\n    background-color :LimeGreen ;\r\n    color : black;\r\n    padding : 10px;\r\n}\r\ntable.table tr.recovery td {\r\n    /*color:green;*/\r\n    background-color :LimeGreen ;\r\n    color : black;\r\n    text-shadow : none ;\r\n}\r\n.completed {\r\n    padding : 10px;\r\n    background-color :DarkGreen ;\r\n    color : white;\r\n}\r\ntable.table tr.completed td {\r\n    /*color:green;*/\r\n    background-color :DarkGreen ;\r\n    color : white;\r\n    text-shadow : none ;\r\n}\r\n.icu {\r\n    background-color:Plum ;\r\n    color : black;\r\n    padding : 10px;\r\n}\r\ntable.table tr.icu td {\r\n    /*color:purple;*/\r\n    background-color:Plum ;\r\n    color : black;\r\n    text-shadow : none ;\r\n    /*text*/\r\n}\r\n.ward {\r\n    padding : 10px;\r\n    background-color : CornflowerBlue ;\r\n    color : black;\r\n}\r\ntable.table tr.ward td {\r\n    /*color:blue;*/\r\n    background-color : CornflowerBlue ;\r\n    color : black;\r\n    text-shadow : none ;\r\n}\r\n.home {\r\n    padding : 10px;\r\n    background-color : RoyalBlue  ;\r\n    color : black;\r\n}\r\ntable.table tr.home td {\r\n    /*color:blue;*/\r\n    background-color : RoyalBlue  ;\r\n    color : black;\r\n    text-shadow : none ;\r\n}\r\n</style>\r\n<body >\r\n<div class=\"wrapper\">\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\" style=\"width:100%\">\r\n<div class=\"span12\" style=\"width:100%\">\r\n\r\n\r\n\r\n<div id=\"endoscopy_nurse\" class=\"  portlet \" >\r\n\r\n<span>\r\n    <!--<img src=\'/esm/anes/pni/logo.jpg\' width=\"60\" />-->\r\n    <!--<label> Operation Schedule : </label>-->\r\n</span>\r\n<div class=\"row-fluid\">\r\n    <div style=\"float:left;\"><label>Operative Schedule : <%= date.strftime(\'%d/%m/%Y at %H:%M\') %></label></div>\r\n    <div style=\"float:right;margin-bottom:10px\"><label>Prasat Neurological Institute</label></div>\r\n    <p/>\r\n</div>\r\n\r\n<div style=\"margin-top:10px\">\r\n <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" class=\"table\">  \r\n \r\n <tr>\r\n    <th style=\"text-align:center\" width=\'4%\'>Room</th>\r\n    <th width=\'6%\'>Time</th>\r\n    <th width=\'15%\'>Patient Info</th>\r\n    <th width=\'15%\'>Diagnosis/<br/>Operation</th>\r\n    <th width=\'5%\'>Position</th>\r\n    <th width=\'15%\'>Instrument</th>\r\n    <th width=\'15%\'>Surgeon/<br/>Assist</th>\r\n    <th width=\'15%\'>Anesth/<br/>Assist</th>\r\n </tr>         \r\n<% \r\n    list.each_with_index do |i, idx|  \r\n%>\r\n<tr class=\"<%=i[:status].downcase%>\">  \r\n    <td>\r\n        <%=i[:or_room]%> \r\n    </td>\r\n    <td>\r\n        <%= i[:time] %> <%= \'TF\' if i[:time_tf] %>\r\n    </td> \r\n    <td>\r\n        <span style=\"text-align:left;display:block\">\r\n            <%=i[:name]%>\r\n            <hr/>\r\n            <%=i[:ward]%> / <%=i[:post_op]%>\r\n        </span>\r\n    </td> \r\n    <td>\r\n        <span style=\"text-align:left;display:block\">\r\n            <%=i[:diagnosis]%><hr/><%=i[:operation]%>\r\n        </span>\r\n    </td>\r\n    <td><%= i[:position] %></td> \r\n    <td>\r\n        <span style=\"text-align:left;display:block\">\r\n<%\r\n    l_instr = i[:instrument].nil? ? [] : i[:instrument].split(\'|\')\r\n    s_instr = []\r\n    for s in l_instr do\r\n        s_instr.push(map_instrument[s])\r\n    end\r\n%>\r\n        <%= s_instr.join(\',\') %>\r\n        </span>\r\n    </td>\r\n    <td>\r\n        <span style=\"text-align:left;display:block\">\r\n            <%= i[:surgeon] %><hr/><%=i[:assist]%>\r\n        </span>\r\n    </td>\r\n    <td>\r\n        <span style=\"text-align:left;display:block\">\r\n            <%= i[:anesth] %><hr/><%=i[:anesth_assist]%>\r\n        </span>\r\n    </td>\r\n </tr>     \r\n	\r\n <% end %>\r\n\r\n\r\n\r\n\r\n\r\n</table>\r\n<br/>\r\n<div class=\"row-fluid\" style=\"font-size:20px\">\r\n    Status : \r\n    <span class=\"appointed\">Appointed</span> | <span class=\"waiting\">Waiting</span> | <span class=\"operation\">Operation</span> | <span class=\"recovery\">Recovery</span> | \r\n    <span class=\"completed\">Completed</span> | <span class=\"icu\">ICU</span> | <span class=\"ward\">Ward</span> | <span class=\"home\">Home</span>\r\n</div>    \r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n	\r\n\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n<% end %>\r\n',NULL,NULL,NULL,'2015-08-24 13:35:47','2015-08-24 13:35:47','status_board_patial','*'),(1770,'print_images',674,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[this.document_name.to_sym].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nbor