per{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'<%=@current_project.get_setting(\'logo_report_path\')%>\' width=\"280\" style=\"Float:left,top:5px\" /></div><h3> <strong><%=@current_service.title %> Diagnosis Report<br />\r\n<%=@current_project.get_setting(\"report_title_1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%>\r\n  </strong></h3>\r\n</center>\r\n\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> ชื่อ-สกุล : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'ไม่ระบุ\'\r\n    if patient.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>เพศ : </strong><%= gender %> &nbsp; <strong>อายุ :&nbsp;</strong>\r\n      <%= year%> Y <%=month%> M <%= day%> D\r\n      <br /><strong>Date :  </strong> <%=render_value 