date_approve\' %> <%=render_value \'time_approve\'%>\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong><% if record[\'approve\']!=\"\" %>Approved<% end %> By :</strong> \r\n<%=render_value \'endoscopist_approve\'%>\r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2015-08-26 09:34:40','2015-08-26 09:34:40','select_images',''),(1773,'document_name',776,1,'\'patient\'',NULL,NULL,NULL,'2015-08-26 09:58:28','2015-08-26 09:58:28',NULL,NULL),(1774,'qq',725,3,'<%\r\n    res = {}\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-08-26 13:31:38','2015-08-26 13:31:38','qq',''),(1775,'print_partial',714,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n    \r\n    map_position = {}\r\n    map_or_room = {}\r\n    map_post_op = {}\r\n    map_ward = {}\r\n    \r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:position].all do\r\n        map_position[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:or_room].all do\r\n        map_or_room[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:post_op_ward].all do\r\n        map_post_op[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:ward].all do\r\n        map_ward[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    map_yn = {}\r\n    map_yn[\'\']  = \'-\'\r\n    map_yn[\'1\'] = \'Yes\'\r\n    map_yn[\'0\'] = \'No\'\r\n    \r\n    map_na = {}\r\n    map_na[\'\'] = \'-\'\r\n    map_na[\'1\'] = \'Normal\'\r\n    map_na[\'2\'] = \'Abnormal\'\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        # res[:patient_innovian] = r_inn\r\n        # res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        res[:project] = @current_project\r\n        res[:project_params] = eval(@current_project[:params])\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px; line-height:20px;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {\r\n    /*color:#666;*/\r\n    line-height:12px;\r\n}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n /* blockquote, */\r\n /*.wrapper{ width:960px;margin-left:auto;margin-right:auto;} */\r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<script>\r\n    document.title = \"PRINT : (<%= r_pat.hn %>) <%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %>\"\r\n</script>\r\n<body>\r\n	<div class=\"wrapper\">\r\n		<div id=\"head\">\r\n<%\r\n    app_logo = eval(@current_project[:params])[\'app_logo_url\']\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n			<center><div id=\"logoleft\" style=\"margin-left:0px\"><a href=\"../Home/index\"><img src=\'<%=app_logo%>\' height=\"50px\" style=\"Float:left,top:5px\" /></a></div><h3> <strong><%=this.header%><br/><%=this.form_name%>\r\n					\r\n				</strong></h3>\r\n			</center>\r\n		</div>\r\n		<br />\r\n	  <div id=\"page\">\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n				<tr>\r\n					<td > \r\n						<table width=\"100%\">\r\n							<tr>\r\n							  <td>\r\n									<strong>HN : </strong><%=r_pat.hn%> <span class=\'tab intro\'>Name : </span><%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> \r\n									\r\n<%\r\n    gender = \'ไม่ระบุ\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n    case_txt = \"\"\r\n    if r_app[:case_type] == \'E\'\r\n        case_txt = \" <font style=\'color:red\'>(Emergency)</font>\".html_safe\r\n    elsif r_app[:case_type] == \'U\'\r\n        case_txt = \" <font style=\'color:red\'>(Urgency)</font>\".html_safe\r\n    end\r\n%>\r\n									<span class=\'tab intro\'>Gender : </span><%= gender %> \r\n									<span class=\' intro\'> Age : </span> <%= age %> ปี <br/>\r\n									<span class=\" intro\">Date : </span>\r\n									    <%= r_app[:date].strftime(\'%d-%m-%Y\') if r_app[:date] %> \r\n									    <%= r_app[:start].strftime(\'%H:%M\') if r_app[:start] %> \r\n									    <%= \' TF\' if r_app[:time_tf] == \'1\' %> \r\n									    <%= case_txt %>\r\n									    <span class=\"tab intro\">Ward : </span> <%= map_ward[r_app[:ward]] %>\r\n									    <span class=\"tab intro\">OR Room : </span><%= map_or_room[r_app[:or_room]] %>\r\n									    <span class=\"tab intro\">Position : </span><%= map_position[r_app[:position]] %>\r\n									    \r\n									    <br/>\r\n									<span class=\"intro\">Surgeon : </span> <%= map_provider[r_app[:surgeon]] %> <span class=\"tab intro\">Assist : </span> <%= map_provider[r_app[:assist]] %> <br/>\r\n									<span class=\"intro\">Anesthesiologist : </span> <%= render_value(\'anesthesiologist\') %> <span class=\"tab intro\">Nurse Anesthetist : </span> <%= render_value(\'nurse\') %>\r\n									<!--<span class=\"tab intro\">Nurse Anesthetist</span> <%= render_value(\'nurse\') %> -->\r\n								</td>\r\n								<td valign=\"top\" style=\"text-align:left\">\r\n								  	<strong>Anesthesiologist Name : </strong><br/>	&nbsp;<br/>	................................  	<br/>						  	  <%= render_value(\'anesthesiologist\') %>\r\n							  	  <!--<strong>Anesthesiologist : </strong> <%= render_value(\'anesthesiologist\') %><br/>-->\r\n			<!--<strong>Nurse Anesthetist : </strong> <%= render_value(\'nurse\') %>-->\r\n			<br />\r\n									\r\n								</td>\r\n							</tr>\r\n							<tr>\r\n							    <td>\r\n							        <br/>\r\n							        <font style=\'color:red\'><strong>Allergy Hx : </strong> <%= this_rec[:allergy_hx] != \'\' ? this_rec[:allergy_hx] : \'-\' %></font><br/>\r\n							        <strong>Diagnosis : </strong> <%= r_app[:diagnosis] %><br/>\r\n							        <strong>Operation : </strong> <%= r_app[:operation] %>\r\n							    </td>\r\n							    <td style=\"text-align:right\" valign=\"bottom\">\r\n							        <strong>Patient Classification by Schedule : </strong><%= render_value(\'patient_classification_by_schedule\') %><br/>\r\n							    </td>\r\n							</tr>\r\n						</table>\r\n				  </td>\r\n				</tr>\r\n			</table>\r\n			<hr style=\"margin-top: 5px;\"/>\r\n<style>\r\n    .tab { margin-left: 20px; }\r\n    .intro {\r\n        font-weight:bold;\r\n        width : 170px;\r\n        /*display: inline-block;*/\r\n    }\r\n    v {color:#2561cD};\r\n</style>\r\n			<div style=\"display:block\">\r\n				<table width=\"50%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left\">\r\n					<tr>\r\n						<td valign=\"top\">\r\n						    <strong>History</strong>\r\n				        </td>\r\n					</tr>\r\n					<tr>\r\n					    <td style=\"margin-left:10px\">\r\n					        <span class=\'intro tab\'>Underlying disease : </span><v>(<%= this_rec[:underlying_disease] == \'1\' ? \'No\' : \'Yes\' %>)\r\n					        <%= render_value(\'underlying_disease\') if this_rec[:underlying_disease] != \'1\' %></v><br/>\r\n					        <% if this_rec[:underlying_heart_disease] != \'\' %>\r\n					        &nbsp;&nbsp;<span class=\'tab\'>Heart disease : </span><v><%= this_rec[:underlying_heart_disease] %></v><br/>\r\n					        <% end %>\r\n					        <% if this_rec[:underlying_disease_details] != \'\' %>\r\n					        &nbsp;&nbsp;<span class=\'tab tab\'>Other : </span><v><blockquote style=\'font-size:.9em\'><%= this_rec[:underlying_disease_other].html_safe %></blockquote></v>\r\n					        <% end %>\r\n					        <span class=\'tab intro\'>Habit : </span><v><%= render_value(\'habit\') %><%= \': \' + this_rec[:habit_other_detail] if this_rec[:habit_other_detail] != \'\' %></v><br/>\r\n					        <span class=\'tab intro\'>Family Hx : </span><v><%= this_rec[:family_hx] %></v><br/>\r\n					        <span class=\'tab intro\'>LMP : </span><v><%= this_rec[:lmp] %></v> \r\n					        <br/>\r\n					        <span class=\"tab\"></span><span class=\"tab\"></span>Suspicious preg : <v><%= map_yn[this_rec[:suspicious_preg]] %></v><br/>\r\n					        <span class=\'tab intro\'>Previous Anesthesia : </span><v>(<%= map_yn[this_rec[:previous_anesthesia]] %>) <%= this_rec[:previous_anesthesia_details] %></v><br/>\r\n					        <span class=\'tab intro\'>Complications : </span><v>(<%= map_yn[this_rec[:complications]] %>) <%= this_rec[:complication_details] %></v><br/>\r\n					        <span class=\'tab intro\'>Systemic Review : </span><v><%= render_value(\'systemic_review\') %></v><br/>\r\n					        <% if this_rec[:systemic_review_other] != \'\' %>\r\n					        &nbsp;&nbsp;<span class=\'tab tab\'>Other : </span><v><%= this_rec[:systemic_review_other] %></v><br/>\r\n					        <% end %>\r\n					        <span class=\'tab intro\'>Risk Score : </span><br/>\r\n					        \r\n					        <% if this_rec[:revised_cardiac_risk_index] and this_rec[:revised_cardiac_risk_index]!=\'\' %>\r\n					         &nbsp;&nbsp;&nbsp;&nbsp;<span class=\'tab \'>Revised cardiac risk index : </span><v><%=render_value(\'revised_cardiac_risk_index\')%></v><br/>\r\n					        <% end %>\r\n					        <% if this_rec[:dvt_wells_score] and this_rec[:dvt_wells_score]!=\'\'%>\r\n					         &nbsp;&nbsp;&nbsp;&nbsp;<span class=\'tab \'>DVT Probability : </span><v><%=render_value(\'dvt_wells_score\')%></v><br/>\r\n					        <% end %>\r\n					        <% if this_rec[:af_cha2ds2_vasc_score] and this_rec[:af_cha2ds2_vasc_score]!=\'\' %>\r\n					         &nbsp;&nbsp;&nbsp;&nbsp;<span class=\'tab \'>Stroke Risk : </span><v><%=render_value(\'af_cha2ds2_vasc_score\')%></v><br/>\r\n					        <% end %>\r\n					        <% if this_rec[:osa_stop_bang_score]  and this_rec[:osa_stop_bang_score]!=\'\'%>\r\n					         &nbsp;&nbsp;&nbsp;&nbsp;<span class=\'tab \'>STOP-BANG Apnea : </span><v><%=render_value(\'osa_stop_bang_score\')%></v><br/>\r\n					        <% end %>\r\n					        \r\n					        \r\n					        <% if this_rec[:systemic_review_current_status] != \'\' %>\r\n					        &nbsp;&nbsp;<span class=\'tab tab\'>Current status : </span><v><%= this_rec[:systemic_review_current_status] %></v><br/>\r\n					        <% end %>\r\n					        <span class=\'tab intro\'>Current Medications : </span><v>(<%= map_yn[this_rec[:current_medications]] %>) \r\n					        <blockquote  style=\'font-size:.9em\'><%= this_rec[:current_medication_details].html_safe %></blockquote></v>\r\n					        <span class=\'tab intro\'>History From : </span><v><%= render_value(\'history_from\') %></v><br/>\r\n					    </td>\r\n					</tr>\r\n					\r\n				\r\n					<tr>\r\n						<td valign=\"top\"><strong>Physical Examination</strong></td>\r\n					</tr>\r\n					<tr>\r\n					    <td style=\"margin-left:10px\">\r\n					        <span class=\"tab\"><b>Wt : </b><%= this_rec[:wt] %></span>\r\n					        <span class=\"tab\"><b>Ht : </b><%= this_rec[:ht] %></span>\r\n					        <span class=\"tab\"><b>BMI : </b><%= this_rec[:bmi] %></span>\r\n					        <span class=\"tab\"><b>GCS : </b><%= this_rec[:gcs] %> <span style=\"font-size:.8em\">[E: <%= this_rec[:e] %>][V: <%= this_rec[:v] %>][M: <%= this_rec[:m] %>]</span></span>\r\n					        <br/>\r\n					        <span class=\"tab\"><b>BP : </b><%= this_rec[:sbp] + \'/\' + this_rec[:dbp] %></span>\r\n					        <span class=\"tab\"><b>HR : </b><%= this_rec[:hr] %></span>\r\n					        <span class=\"tab\"><b>RR : </b><%= this_rec[:rr] %></span>\r\n					        <span class=\"tab\"><b>T : </b><%= this_rec[:t] %></span>\r\n					        <br/>\r\n					        <span class=\"tab\"><b>Psychological status : </b><v><%= render_value(\'psychological_status\') %></span></v>\r\n					        <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\r\n					            <tr>\r\n					                <td width=\"20%\"><span class=\'tab\'></span><b>Airway</b></td>\r\n					                <td width=\"50%\">Mallampati grade</td>\r\n					                <td width=\"30%\"><v><%= render_value(\'mallampati_grade\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td>Thyromental distance</td>\r\n					                <td><v><%= render_value(\'thyromental_distance\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td>Mouth opening</td>\r\n					                <td><v><%= render_value(\'mouth_opening\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td>Patency of nares</td>\r\n					                <td><v><%= render_value(\'patency_of_nares\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td>Prominent incisor</td>\r\n					                <td><v><%= render_value(\'prominent_incisor\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td>Limitation of neck motility</td>\r\n					                <td><v><%= render_value(\'limitation\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td>Difficult intubation expected</td>\r\n					                <td><v><%= render_value(\'difficult\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td>Artificial airway</td>\r\n					                <td style=\"font-size:9px\"><v><%= render_value(\'artificial_airway\') %><br/> ETT no. :<%= render_value(\'ett_no\') %> Depth : <%= render_value(\'depth\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td colspan=\"3\">\r\n					                    <span class=\'tab\'></span>Ventitator support : <v><%= map_yn[this_rec[:ventilator_support]] %></v>\r\n                                        <% if this_rec[:ventilator_support] == \'0\' %>\r\n					                    <br/><span class=\"tab\"></span> O<sub>2</sub> Support : <v><%=this_rec[:o2support]%></v>\r\n					                    <% end %>\r\n					                    <% if this_rec[:ventilator_support] == \'1\' %>\r\n					                    <br/><span class=\"tab\"></span>Setting : <v>Mode : <%= this_rec[:mode] %>, P<sub>i</sub>/V<sub>t</sub>/PS : <%=this_rec[:vt]%>, RR : <%=this_rec[:f]%>, FiO2 : <%=this_rec[:fio2]%>, PEEP : <%=this_rec[:peep]%></v>\r\n					                    <% end %>\r\n					                </td>\r\n					            </tr>\r\n					        </table>\r\n<%\r\n    den_f = render_value(\'dentures_full\')\r\n    den_p = render_value(\'dentures_partial\')\r\n%>\r\n<style>\r\n    .a1 {\r\n        border-style: double;\r\n    }\r\n    .a2 {\r\n        /*border:1px solid black;*/\r\n        text-decoration: line-through;\r\n    }\r\n    .a2 .child{\r\n        position:absolute; \r\n        width:0; \r\n        height:0;\r\n        border-style:solid;\r\n    }\r\n    .a2 .black-triangle{\r\n        z-index:-2;\r\n        border-color: transparent black white white;\r\n    }\r\n    .a2 .white-triangle{\r\n        border-color: transparent white white white;\r\n        z-index:-1;\r\n    }\r\n    .a3 {\r\n        /*border:1px solid black;*/\r\n        /*text-decoration: line-through;*/\r\n        font-weight: bold;\r\n    }\r\n    .a3 .child{\r\n        position:absolute; \r\n        width:0; \r\n        height:0;\r\n        border-style:solid;\r\n    }\r\n    .a3 .black-triangle{\r\n        z-index:-2;\r\n        border-color: transparent black white white;\r\n    }\r\n    .a3 .white-triangle{\r\n        border-color: transparent white white white;\r\n        z-index:-1;\r\n    }\r\n</style>\r\n<script>\r\n    $(function(){\r\n\r\n        var arrJCrossOut = $(\'.a2\');\r\n        \r\n        arrJCrossOut.each(function(i){\r\n        \r\n            var jTemp = $(this),\r\n                nWidth = jTemp.innerWidth(),\r\n                nHeight = jTemp.innerHeight(),\r\n                sDomTemp = \'<div class=\"child black-triangle\" style=\"border-width:\'+nHeight +\'px \'+nWidth +\'px 0px 0px; margin-top:-\'+nHeight+\'px; \"></div>\';\r\n            \r\n            sDomTemp += \'<div class=\"child white-triangle\" style=\"border-width:\'+nHeight +\'px \'+nWidth +\'px 0px 0px; margin-top:-\'+(nHeight-1)+\'px;\"></div>\';\r\n            \r\n            jTemp.append(sDomTemp);\r\n        });\r\n        \r\n        $(\'.a3\').each(function(i){\r\n        \r\n            var jTemp = $(this),\r\n                nWidth = jTemp.innerWidth(),\r\n                nHeight = jTemp.innerHeight(),\r\n                sDomTemp = \'<div class=\"child black-triangle\" style=\"border-width:\'+nHeight +\'px \'+nWidth +\'px 0px 0px; margin-top:-\'+nHeight+\'px; \"></div>\';\r\n            \r\n            sDomTemp += \'<div class=\"child white-triangle\" style=\"border-width:\'+nHeight +\'px \'+nWidth +\'px 0px 0px; margin-top:-\'+(nHeight-1)+\'px;\"></div>\';\r\n            \r\n            jTemp.append(sDomTemp);\r\n        });\r\n    });\r\n</script>\r\n					        <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"float:right;margin-top:5px\">\r\n					            <tr>\r\n					                <td width=\'20%\'><b class=\'tab\'>Dentures</b></td>\r\n					                <td width=\'15%\'>&nbsp;&nbsp;&nbsp;&nbsp;Full</td>\r\n					                <td width=\'30%\'>&nbsp;&nbsp;<v><%=den_f==\'\' ? \'-\' : den_f%></v></td>\r\n					                <td width=\'35%\'>&nbsp;  </td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td align=\"right\"><v><%= render_value(\'dental\') %></v> </td>\r\n					                <td>&nbsp;&nbsp;&nbsp;&nbsp;Partial</td>\r\n					                <td>&nbsp;&nbsp;<v><%=den_p==\'\' ? \'-\' : den_p%></v></td>\r\n					                <td> \r\n					                    <table width=\'100%\' style=\'margin-left:5px\'>\r\n					                        <tr>\r\n					                            <td width=\'30%\' align=\'center\' class=\'a1\'>Crown</td>\r\n					                            <td width=\'30%\' align=\'center\' class=\'a2\'>Loss</td>\r\n					                            <td width=\'30%\' align=\'center\' class=\'a3\'>Unstable</td>\r\n					                            <td width=\'10%\'></td>\r\n					                       </tr>\r\n					                   </table>\r\n					               \r\n					               </td>\r\n					            </tr>\r\n                                <tr>\r\n                                    <td colspan=\'4\'>&nbsp;</td>\r\n                                </tr>\r\n					            <tr>\r\n					                <td colspan=\"4\">\r\n					                    <table width=\'100%\' style=\'margin-left:5px\'>\r\n					                        <tr>\r\n					                            <td width=\'10%\' align=\'right\'>&nbsp;</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p13]%>\'>13</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p12]%>\'>12</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p11]%>\'>11</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p21]%>\'>21</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p22]%>\'>22</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p23]%>\'>23</td>\r\n					                            <td width=\'15%\' class=\'\'> </td>\r\n					                        </tr>\r\n					                        <tr>\r\n					                            <td width=\'10%\' align=\'right\' >&nbsp; </td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p43]%>\'>43</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p42]%>\'>42</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p41]%>\'>41</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p31]%>\'>31</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p32]%>\'>32</td>\r\n					                            <td width=\'10%\' align=\'center\' class=\'a<%=this_rec[:p33]%>\'>33</td>\r\n					                            <td width=\'15%\' class=\'\'> </td>\r\n					                        </tr>\r\n					                    </table>\r\n					                </td>\r\n					            </tr>\r\n					            <tr>\r\n                                    <td colspan=\'4\'>&nbsp;\r\n                                        \r\n                                  </td>\r\n                                </tr>\r\n					        </table>\r\n					        <span class=\"tab intro\">RS/CVS : </span><v><%= this_rec[:rs_cvs] != \'\' ? \'(\' + render_value(\'rs_cvs\') +\')\' : \'-\'%> \r\n					            <%= this_rec[:rs_cvs_details] %></v><br/>\r\n					        <span class=\"tab intro\">Abdomen//Extremities : </span><v><%= this_rec[:abdomen_extremities] != \'\' ? \'(\' + render_value(\'abdomen_extremities\') +\')\' : \'-\'%> \r\n					            <%= this_rec[:abdomen_extremities_details] %></v><br/>\r\n					        <span class=\"tab intro\">Neuro : </span><v><%= this_rec[:neuro] != \'\' ? \'(\' + render_value(\'neuro\') +\')\' : \'-\'%> \r\n					            <%= this_rec[:neuro_details] %></v>, Upper Rt/Lt : <v><%=render_value(\'upper_rtlt\')%></v>, Lower Rt/Lt : <v><%=render_value(\'lower_rtlt\')%></v><br/>\r\n					    </td>\r\n					</tr>\r\n				</table>\r\n				\r\n				<!--  right column -->\r\n				<table width=\"50%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:right\">\r\n					<tr>\r\n						<td valign=\"top\"><strong>Laboratory Investigation</strong></td>\r\n					</tr>\r\n					<tr>\r\n					    <td>\r\n					        <table style=\'font-size:.9em\'>\r\n					        <% if this_rec[:cbc] != \'\' or this_rec[:hb_hct] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td width=\'35%\'><span class=\'tab\'></span>CBC</td>\r\n					                <td width=\'20%\' align=\'center\'><v><%= map_na[this_rec[:cbc]] %></v></td>\r\n					                <td width=\'50%\'><v><%= this_rec[:cbc_details] %></v> <span class=\"tab\"> Hb/Hct</span> <v>(<%= this_rec[:hb_hct] %>)</v></td>\r\n					            </tr>\r\n					        <% end %>\r\n					        <% if this_rec[:ua] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>UA</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:ua]] %></v></td>\r\n					                <td ><v><%= this_rec[:ua_details] %></v> </td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:bs] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>BS</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:bs]] %></v></td>\r\n					                <td ><v><%= this_rec[:bs_details] %></v> </td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:bun_cr] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>BUN/Cr</td>\r\n					                <td align=\'center\' ><v> <%= map_na[this_rec[:bun_cr]] %></v></td>\r\n					                <td ><v><%= this_rec[:bun_lab] %> / <%= this_rec[:bun_cr_details] %></v> </td>\r\n					            </tr>\r\n					        <% end %>\r\n					        <% if this_rec[:electrolytes] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>Electrolytes</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:electrolytes]] %></v></td>\r\n					                <td ><v><%= this_rec[:electrolytes_details] %></v></td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:coagulation_study] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>Coagulation study</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:coagulation_study]] %></v></td>\r\n					                <td ><v><%= this_rec[:coagulation_study_details] %></v></td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:hiv_vdrl] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>HIV/VDRL</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:hiv_vdrl]] %></v></td>\r\n					                <td ><v><%= this_rec[:hiv_vdrl_details] %></v></td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:lft] != \'\'  %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>LFT</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:lft]] %></v></td>\r\n					                <td ><v><%= this_rec[:lft_details] %></v></td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:cortisol] != \'\'  %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>Cortisol</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:cortisol]] %></v></td>\r\n					                <td ><v><%= this_rec[:cortisol_details] %></v></td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:tft] != \'\'  %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>TFT</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:tft]] %></v></td>\r\n					                <td ><v><%= this_rec[:tft_details] %></v></td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:cxr] != \'\'  %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>CXR</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:cxr]] %></v></td>\r\n					                <td ><v><%= this_rec[:cxr_details] %></v></td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:ekg] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>EKG</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:ekg]] %></v></td>\r\n					                <td ><v><%= this_rec[:ekg_details] %></v> </td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:echo] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td ><span class=\'tab\'></span>Echo</td>\r\n					                <td align=\'center\' ><v><%= map_na[this_rec[:echo]] %></v></td>\r\n					                <td ><v><%= this_rec[:echo_details] %></v></td>\r\n					            </tr>\r\n					       <% end %>\r\n			        <%\r\n			            for i in this_rec[:other_laboratory_investigation] do \r\n					        r_tmp = get_model[:pre_other_1].find(i.to_s)\r\n                    %>\r\n                            <tr valign=\'top\'>\r\n                                <td><span class=\'tab\'></span><%=r_tmp[:other_lab_name]%></td>\r\n                                <td align=\'center\'><v><%=map_na[r_tmp[:other_lab_result]]%></v></td>\r\n                                <td><v><%=r_tmp[:other_lab_details]%></v></td>\r\n                            </tr>\r\n			        <% end %>\r\n					        </table>\r\n					    </td>\r\n					</tr>\r\n					<tr>\r\n						<td valign=\"top\"><strong>Assessment/Preparation</strong></td>\r\n					</tr>\r\n					<tr>\r\n					    <td>\r\n					        <span class=\"tab intro\">ASA Physical status : </span><v><%=this_rec[:asa_status]%> (<%= this_rec[:asa_type] == \'\' ? \'-\' : this_rec[:asa_type] %>)</v><br/>\r\n					        <span class=\"tab intro\">Anesthetic Plan  </span><br/>\r\n					        <span class=\"tab\"></span><span class=\"tab\"></span>: <v><%= render_value(\'anesthetic_plan\') %></v><br/>\r\n					        <span class=\"tab intro\">Blood prepared   </span><br/>\r\n					        <span class=\"tab\"></span><span class=\"tab\"></span>: Group (<v><%=render_value(\'group\')%></v>), PRC (<v><%=this_rec[:prc]==\'\' ? \'-\' : this_rec[:prc] %></v> u.), FFP (<v><%=this_rec[:ffp] ==\'\' ? \'-\' : this_rec[:ffp] %></v> u.), Plt (<v><%=this_rec[:plt] == \'\' ? \'-\' : this_rec[:plt] %></v> u.)<br/>\r\n					        <span class=\"tab intro\">Problems/Risks : </span><v><%= map_yn[this_rec[:problems_risk]] %></v><br/>\r\n					        <% if this_rec[:problems_risk_details] != \'\' %>\r\n					        <v><blockquote  style=\'font-size:.9em\'><%=this_rec[:problems_risk_details].html_safe%></blockquote></v>\r\n					        <% end %>\r\n					        <span class=\"tab intro\">Suggested preparation : </span><v>(<%=map_yn[this_rec[:suggested_preparation]]%>)</v><br/>\r\n					        <% if this_rec[:suggested_preparation]==\'1\'%>\r\n					            <% if false %>\r\n					            <span class=\"tab\"></span><span class=\"tab intro\"> : </span>\r\n					            <v>\r\n					                <%=render_value(\'suggested_preparation_induction\')%> \r\n					                <%=render_value(\'suggested_preparation_muscle\')%> \r\n					                <%=render_value(\'suggested_preparation_narcotic\')%> \r\n					                <%=render_value(\'suggested_preparation_inhalation\')%> \r\n					                <%=render_value(\'suggested_preparation_equipment\')%> \r\n					                <%=render_value(\'suggested_preparation_details\')%> \r\n					            </v>\r\n					            <% end %>\r\n					            <% if true %>\r\n                                <% if this_rec[:suggested_preparation_induction] != \'\' %>\r\n                                <span class=\"tab\"></span><span class=\"tab\"></span>Induction : <v><%=render_value(\'suggested_preparation_induction\')%></v><br/>\r\n                                <% end %>\r\n                                <% if this_rec[:suggested_preparation_muscle] != \'\' %>\r\n                                <span class=\"tab\"></span><span class=\"tab\"></span>Muscle relaxation : <v><%=render_value(\'suggested_preparation_muscle\')%></v><br/>\r\n                                <% end %>\r\n                                <% if this_rec[:suggested_preparation_narcotic] != \'\' %>\r\n                                <span class=\"tab\"></span><span class=\"tab\"></span>Narcotic : <v><%=render_value(\'suggested_preparation_narcotic\')%></v><br/>\r\n                                <% end %>\r\n                                <% if this_rec[:suggested_preparation_inhalation] != \'\' %>\r\n                                <span class=\"tab\"></span><span class=\"tab\"></span>Inhalation : <v><%=render_value(\'suggested_preparation_inhalation\')%></v><br/>\r\n                                <% end %>\r\n                                <% if this_rec[:suggested_preparation_equipment] != \'\' %>\r\n                                <span class=\"tab\"></span><span class=\"tab\"></span>Equipment : <v><%=render_value(\'suggested_preparation_equipment\')%></v><br/>\r\n                                <% end %>\r\n                                <% if this_rec[:suggested_preparation_details] != \'\' %>\r\n                                <span class=\"tab\"></span><span class=\"tab\"></span>Other : <v><%=render_value(\'suggested_preparation_details\')%></v><br/>\r\n                                <% end %>\r\n                                <% end %>\r\n					        <% end %>\r\n					        <% if this_rec[:remark] != \'\' %>\r\n					        <span class=\"tab intro\">Remark : </span><br/>\r\n					        <v><blockquote style=\"font-size:.9em\"><%= this_rec[:remark].html_safe if this_rec[:remark] %></blockquote></v>\r\n					        <% end %>\r\n					    </td>\r\n					</tr>\r\n					<tr>\r\n					    <td>\r\n					        <strong>Premedications </strong><v>(<%= map_yn[this_rec[:premed]] %>)</v>\r\n					        <table width=\'100%\'>\r\n					        <% if this_rec[:anti_ht] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td width=\'30%\'><span class=\"tab\"></span>Anti HT</td>\r\n					                <td width=\'50%\'><v><%= render_value(\'anti_ht\') %></v><span class=\"tab\"></span></td>\r\n					                <td ><v><%= this_rec[:med_anti_ht_unit] %></v> </td>\r\n					                <td >&nbsp;&nbsp;mg.</td>\r\n					            </tr>\r\n					        <% end %>\r\n					        <% if this_rec[:anticonvulsant] != \'\' %>\r\n					            <tr valign=\'top\'>\r\n					                <td width=\'30%\'><span class=\"tab\"></span>Anticonvulsant </td>\r\n					                <td width=\'50%\'><v><%= render_value(\'anticonvulsant\') %></v><span class=\"tab\"></span></td>\r\n					                <td><v><%= this_rec[:med_anticonvulsant_unit] %></v> </td>\r\n					                <td >&nbsp;&nbsp;mg.</td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:med_gi_preparation_name] != \'\' %>\r\n					             <tr valign=\'top\'>\r\n					                <td width=\'30%\'><span class=\"tab\"></span>GI Preparation </td>\r\n					                <td width=\'50%\'><v><%= render_value(\'med_gi_preparation_name\') %></v><span class=\"tab\"></span></td>\r\n					                <td><v><%= this_rec[:med_gi_preparation_unit] %></v> </td>\r\n					                <td>&nbsp;&nbsp;mg.</td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if this_rec[:med_anti_anxiety_name] != \'\' %>\r\n					             <tr valign=\'top\'>\r\n					                <td width=\'30%\'><span class=\"tab\"></span>Anti-anxiety </td>\r\n					                <td width=\'50%\'><v><%= render_value(\'med_anti_anxiety_name\') %></v><span class=\"tab\"></span></td>\r\n					                <td><v><%= this_rec[:med_anti_anxiety_unit] %></v> </td>\r\n					                <td>&nbsp;&nbsp;mg.</td>\r\n					            </tr>\r\n					       <% end %>\r\n					       <% if false %>\r\n					            1 | Cox II Inhibitor\r\n                                2 | NSAIDS\r\n                                3 | Opioids\r\n					       <% end %>\r\n					       <% if this_rec[:med_analgesics_name] != \'\' %>\r\n					             <tr valign=\'top\'>\r\n					                <td width=\'30%\'><span class=\"tab\"></span>Analgesics </td>\r\n					                <td width=\'50%\'><v><%= render_value(\'med_analgesics_name\') %></v><span class=\"tab\"></span></td>\r\n					                <td><v><%= this_rec[:med_analgesics_unit] %></v> </td>\r\n					                <td>&nbsp;&nbsp;mg.</td>\r\n					            </tr>\r\n					       <% end %>\r\n					           <% \r\n					           cc = 0\r\n					           for i in this_rec[:premed_other] do \r\n					               cc += 1\r\n					                r_tmp = model[:pre_other_2].find(i)\r\n					           %>\r\n					             <tr valign=\'top\'>\r\n					                <td width=\'30%\'><span class=\"tab\"></span>Other <%= cc %></td>\r\n					                <td><v><%= r_tmp[:medication_name] %></v><span class=\"tab\"></span></td>\r\n					                <td><v><%= r_tmp[:medication_unit] %></v> </td>\r\n					                <td>&nbsp;&nbsp;mg.</td>\r\n					            </tr>\r\n					            <% end %>\r\n					        </table>\r\n					        <br/>\r\n					<%\r\n					    l_tmp = []\r\n			            for i in this_rec[:post_op_pain_relief_plan] do \r\n					        r_tmp = get_model[:pain_relief_plan].find(i.to_s)\r\n					        name = r_tmp[:name]\r\n					        if r_tmp[:note] != \'\'\r\n					            name += \" (\" + r_tmp[:note] + \")\"\r\n					        end\r\n					        l_tmp.push(name)\r\n					       #l_tmp.push(r_tmp.to_json.html_safe)\r\n					    end\r\n                    %>\r\n					        <span class=\" intro\">Post-op Pain Relief Plan : </span>\r\n					        <% if !l_tmp.empty? %>\r\n					        <v><%=l_tmp.join(\', \')%></v><br/>\r\n					        <% else %>\r\n					        <v> - </v><br/>\r\n					        <% end %>\r\n					        <span class=\" intro\">Checklists for informed education : </span><v><%=render_value(\'informed_education\')%></v><br/>\r\n					        <% if this_rec[:informed_education_other] != \'\' %>\r\n					        </span><span class=\"tab\"></span>Other : <v><%=this_rec[:informed_education_other]%></v><br/>\r\n					        <% end %>\r\n					        <br/>\r\n					        <% if this_rec[:proposed_anesthetic_plan] != \'\'%>\r\n					        <span class=\"tab\"></span>I have discussed the proposed anesthetic plan and possible alternatives with the : <v><%=render_value(\'proposed_anesthetic_plan\')%></v>\r\n					        <% end %>\r\n					    </td>\r\n					</tr>\r\n				</table>\r\n				<div class=\"clear\"></div>\r\n				<% if false %>\r\n				<table width=\'50%\' style=\'float:right\'>\r\n				    <tr>\r\n					    <td>\r\n					        <div class=\'row-fluid\' style=\"font-size:.9em\">\r\n                				<hr/>\r\n                				\r\n                				<center>\r\n                				ข้าพเจ้าได้รับข้อมูลและมีโอกาสได้ซักถามเกี่ยวกับการให้ยาระงับความรู้สึกแล้ว<br/><br/>\r\n                				....................................................................................