                         <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:class=>\'btn\', :style=>\'vertical-align: top;\' %></span>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>',NULL,NULL,NULL,'2015-08-27 15:22:07','2015-08-27 15:22:07','update',''),(1783,'test',777,3,'<%\r\n    model = get_model\r\n    m_prov = model[:provider]\r\n    a_prov = m_prov.where({\'name\' => Regexp.new(\'\')})\r\n    # coll.find({\"name\" => Regexp.new(search_string)})\r\n    \r\n    res = {}\r\n    res[:prov] = a_prov\r\n    res[:prov_count] = a_prov.count if a_prov\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-08-27 16:37:27','2015-08-27 16:37:27','test',''),(1784,'show_partial',714,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:960px;padding:10px\">\r\n\r\n\r\n\r\n<%= this.print_partial.html_safe %>\r\n<div style=\"padding:20px\">\r\n    <!--<%= link_to \'Finish\', return_url, :class=>\'btn btn-success\' %> | -->\r\n    <%= link_to \'Finish\', \'../Home/index\', :class=>\'btn btn-success\' %> | \r\n    <%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n    <%= link_to \'Print\', \"print?id=\\\\#{params[:id]}\", :class=>\'btn\', :target=>\'_blank\' %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2015-08-28 02:40:07','2015-08-28 02:40:07','show_partial',''),(1785,'index',778,2,'<center>ประวัติเครื่องมือ<br /></br>\r\n<!--<a href=\"../Product/index\" class=\"btn\">สินค้า</a>-->\r\n<a href=\"../InstrumentRecord/index\" class=\"btn\">ประวัติเครื่องมือ</a>\r\n</center>\r\n\r\n<hr/>\r\n<%\r\n\r\n    models = get_model\r\n\r\n    records = models[:instrument_record].all\r\n    \r\n    map = {}\r\n    tags = %w{name brand model}\r\n    status_list=%w{- ปกติ ส่งซ่อม จำหน่ายออก}.collect{|i| i.humanize}\r\n    \r\n    for i in records\r\n        for j in tags \r\n            map[j] = {} unless map[j]\r\n            value = i[j]\r\n            map[j][value] = [] unless map[j][value]\r\n            map[j][value] << i\r\n        \r\n        end\r\n    end\r\n \r\n#   tag = \'brand\'\r\n  records.collect!{|i| \r\n    id = i.id\r\n         c = {:name=>i.name,:brand=>i.brand,:model=>i.model,:sn=>i.sn,:status=>status_list[i.status.to_i]\r\n         }\r\n         \r\n         c\r\n    }.compact!  \r\n\r\n    list = {} \r\n    show = []\r\n    list_by = \'\'\r\n    for j in tags \r\n        list[j] = {} unless list[j]\r\n        list[j] =  map[j].keys.collect{|i| [i,map[j][i].size] }.sort{|a,b| b[1]<=>a[1] }.collect{|i| [\"\\\\#{i[0]} (\\\\#{i[1]})\",i[0]] } if map[j]\r\n        show = records.collect{|i| i if i[j.to_sym]==params[j.to_sym]}.compact if params[j.to_sym] \r\n        list_by = \"by \"+j+\" : \"+params[j.to_sym] if params[j.to_sym] \r\n    end   \r\n    \r\n    table_model = %w{ name brand model sn status}.collect{|i| i.to_sym}\r\n    labels = {:name=>\'Name\',:brand=>\'Brand\',:model=>\'Model\',:sn=>\'Serial number\',:status=>\'Status\',:action=>\'Actions\' }\r\n\r\n    \r\n  \r\n%>\r\n<%#list.join(\"<br/>\").html_safe %>\r\n\r\n\r\n<%#=show.inspect%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <h3 style=\"display:inline-block\">List <%=list_by%></h3>\r\n    </div>\r\n    <div class=\"w-box-content cnt_a\">\r\n        <div class=\"row-fluid\">\r\n        <% for j in tags%>\r\n        <%  list[j].unshift([\"\",\"\"])%>\r\n            <div class=\"span4\">\r\n            <label><%=j+\" : \"%>\r\n            <%=select_tag :name, options_for_select(list[j],params[j.to_sym]),:id=>\'select-\'+j if list[j]%>\r\n            </label>\r\n            </div>\r\n            <script>\r\n                $(\'#select-<%=j%>\').change(function(){\r\n                    v = $(this).val();\r\n                    url = document.location.href.split(\'?\')[0];\r\n                    document.location.href=url+\"?<%=j%>=\"+v;\r\n                })\r\n            </script>\r\n        <% end %>\r\n        </div>\r\n    \r\n        \r\n        \r\n        <%= tabular :model=>table_model+[:action],:data=>show,:labels=>labels %>\r\n    \r\n    <br/>\r\n    \r\n    </div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-08-28 06:40:25','2015-08-28 06:40:25','',''),(1786,'layout',778,4,'<%=default_layout%>',NULL,NULL,NULL,'2015-08-28 06:40:25','2015-08-28 06:40:25',NULL,NULL),(1787,'document_name',779,1,'\'product\'',NULL,NULL,NULL,'2015-08-28 06:41:07','2015-08-28 06:41:07',NULL,NULL),(1788,'document_name',780,1,'\'instrument_record\'',NULL,NULL,NULL,'2015-08-28 06:43:08','2015-08-28 06:43:08',NULL,NULL),(1789,'document_name',781,1,'\'history\'',NULL,NULL,NULL,'2015-08-28 06:54:07','2015-08-28 06:54:07',NULL,NULL),(1790,'print_partial',711,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n    \r\n    map_position = {}\r\n    map_or_room = {}\r\n    map_post_op = {}\r\n    map_ward = {}\r\n    map_ward[\'\']  = \'N/A\'\r\n    map_ward[nil] = \'N/A\'\r\n    \r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:position].all do\r\n        map_position[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:or_room].all do\r\n        map_or_room[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:post_op_ward].all do\r\n        map_post_op[i.id.to_s] = i[:name]\r\n    end\r\n    for i in model[:ward].all do\r\n        map_ward[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    map_yn = {}\r\n    map_yn[\'\']  = \'-\'\r\n    map_yn[\'1\'] = \'Yes\'\r\n    map_yn[\'0\'] = \'No\'\r\n    \r\n    map_na = {}\r\n    map_na[\'\'] = \'-\'\r\n    map_na[\'1\'] = \'Normal\'\r\n    map_na[\'2\'] = \'Abnormal\'\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        # res[:patient_innovian] = r_inn\r\n        # res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        res[:project] = @current_project\r\n        res[:project_params] = eval(@current_project[:params])\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px; line-height:20px;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {\r\n    /*color:#666;*/\r\n    line-height:12px;\r\n}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n /* blockquote, */\r\n /*.wrapper{ width:960px;margin-left:auto;margin-right:auto;} */\r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<script>\r\n    document.title = \"PRINT : (<%= r_pat.hn %>) <%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %>\"\r\n</script>\r\n<body>\r\n	<div class=\"wrapper\">\r\n		<div id=\"head\">\r\n<%\r\n    app_logo = eval(@current_project[:params])[\'app_logo_url\']\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n			<center><div id=\"logoleft\" style=\"margin-left:0px\"><a href=\"../Home/index\"><img src=\'<%=app_logo%>\' height=\"50px\" style=\"Float:left,top:5px\" /></a></div><h3> <strong><%=this.header%><br/><%=this.form_name%>\r\n					\r\n				</strong></h3>\r\n			</center>\r\n		</div>\r\n		<br />\r\n	  <div id=\"page\">\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n				<tr>\r\n					<td > \r\n				  <table width=\"100%\">\r\n							<tr>\r\n								<td width=\"68%\">\r\n									<strong>HN : </strong><%=r_pat.hn%> <span class=\'tab intro\'>Name : </span><%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> \r\n									\r\n<%\r\n    gender = \'ไม่ระบุ\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n    case_txt = \"\"\r\n    if r_app[:case_type] == \'E\'\r\n        case_txt = \" <font style=\'color:red\'>(Emergency)</font>\".html_safe\r\n    elsif r_app[:case_type] == \'U\'\r\n        case_txt = \" <font style=\'color:red\'>(Urgency)</font>\".html_safe\r\n    end\r\n%>\r\n									<span class=\'tab intro\'>Gender : </span><%= gender %> \r\n									<span class=\' intro\'> Age : </span> <%= age %> ปี <br/>\r\n									<span class=\" intro\">Date : </span>\r\n									    <%= r_app[:date].strftime(\'%d-%m-%Y\') if r_app[:date] %> \r\n									    <%= r_app[:start].strftime(\'%H:%M\') if r_app[:start] %> \r\n									    <%= \' TF\' if r_app[:time_tf] == \'1\' %> \r\n									    <%= case_txt %>\r\n									    <span class=\"tab intro\">Ward : </span> <%= map_ward[r_app[:ward]] %>\r\n									    <span class=\"tab intro\">OR Room : </span><%= map_or_room[r_app[:or_room]] %>\r\n									    <br/>\r\n									<span class=\"intro\">Surgeon : </span> <%= map_provider[r_app[:surgeon]] %> <span class=\"tab intro\">Assist : </span> <%= map_provider[r_app[:assist]] %> <br/>\r\n									<span class=\"intro\">Anesthesiologist : </span> <%= render_value(\'anesthesiologist\') %> <span class=\"tab intro\">Nurse Anesthetist : </span> <%= render_value(\'nurse_anesthetist\') %>\r\n									\r\n									<!--<span class=\"tab intro\">Nurse Anesthetist</span> <%= render_value(\'nurse\') %> -->\r\n								</td>\r\n								<td width=\"32%\" style=\"text-align:left\">\r\n                                <strong>Anesthesiologist Name : </strong> <br/>&nbsp;<br/>\r\n			................................<br/> <%= render_value(\'anesthesiologist\') %>\r\n									\r\n								</td>\r\n							</tr>\r\n							<tr>\r\n							    <td>\r\n							        <br/>\r\n							        <!--<font style=\'color:red\'><strong>Allergy Hx : </strong> <%= this_rec[:allergy_hx] != \'\' ? this_rec[:allergy_hx] : \'-\' %></font><br/>-->\r\n							        <strong>Diagnosis : </strong> <%= r_app[:diagnosis] %><br/>\r\n							        <strong>Operation : </strong> <%= r_app[:operation] %>\r\n							    </td>\r\n							    <td style=\"text-align:right\" valign=\"bottom\">\r\n							        <!--<strong>Patient Classification by Schedule : </strong><%= render_value(\'patient_classification_by_schedule\') %><br/>-->\r\n							    </td>\r\n							</tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n			<hr style=\"margin-top: 5px;\"/>\r\n<style>\r\n    .tab { margin-left: 20px; }\r\n    .intro {\r\n        font-weight:bold;\r\n        width : 170px;\r\n        /*display: inline-block;*/\r\n    }\r\n    v {color:#2561cD};\r\n</style>\r\n			<div style=\"display:block\">\r\n				<table width=\"50%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left\">\r\n					<tr>\r\n						<td valign=\"top\">\r\n						    <span class=\"intro\"><u><i>Pre anesth period</i></u></span><br/>\r\n						    <span class=\"tab intro\">ASA Status : </span> <v><%= this_rec[:asa_status] %> (<%= this_rec[:asa_type] == \'\' ? \'-\' : this_rec[:asa_type] %>)</v>\r\n				        </td>\r\n					</tr>\r\n<%\r\n    ods = this_rec[:anesthetic_official_date_start]\r\n    ots = this_rec[:anesthetic_official_time_start].strftime(\'%H:%M\') if this_rec[:anesthetic_official_time_start]\r\n    ode = this_rec[:anesthetic_official_date_end]\r\n    ote = this_rec[:anesthetic_official_time_end].strftime(\'%H:%M\') if this_rec[:anesthetic_official_time_end]\r\n    \r\n    nds = this_rec[:anesthetic_nonofficial_date_start]\r\n    nts = this_rec[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\') if this_rec[:anesthetic_nonofficial_time_start]\r\n    nde = this_rec[:anesthetic_nonofficial_date_end]\r\n    nte = this_rec[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\') if this_rec[:anesthetic_nonofficial_time_end]\r\n    \r\n    oos = \"\\\\#{ods} \\\\#{ots}\"\r\n    ooe = \"\\\\#{ode} \\\\#{ote}\"\r\n    \r\n    nos = \"\\\\#{nds} \\\\#{nts}\"\r\n    noe = \"\\\\#{nde} \\\\#{nte}\"\r\n    non = false\r\n    if nos != noe\r\n        non = true\r\n    end\r\n%>\r\n					<tr>\r\n					    <td>\r\n					        <span class=\"intro\"><u><i>Anesth period</i></u></span><br/>\r\n					        <% if non %>\r\n					        <span class=\"tab intro\">Anesthetic official time </span> <br/>\r\n					        <span class=\"tab\"></span><span class=\"tab intro\">: </span> <v><%= oos %> to <%= ooe %>  </v> <br/>\r\n					        <span class=\"tab intro\">Anesthetic non-official time </span> <br/>\r\n					        <span class=\"tab\"></span><span class=\"tab intro\">: </span> <v><%= nos %> to <%= noe %>  </v> <br/>\r\n					        <% else %>\r\n					        <span class=\"tab intro\">Anesthetic start </span> <br/>\r\n					        <span class=\"tab\"></span><span class=\"tab intro\">: </span> <v><%= oos %>  </v> <br/>\r\n					        <span class=\"tab intro\">Anesthetic end  </span> <br/>\r\n					        <span class=\"tab\"></span><span class=\"tab intro\">: </span> <v><%= ooe %>  </v>  <br/>\r\n					        <% end %>\r\n					        <span class=\"tab intro\">Anesthetic duration : </span> <v><%= this_rec[:anesthetic_duration] != \'\' ? this_rec[:anesthetic_duration] : \'-\' %> </v> min. <br/>\r\n					        <span class=\"tab intro\">Anesth Technique </span> <br/>\r\n					        <span class=\"tab\"></span><span class=\"tab intro\">: </span> <v><%= this_rec[:anesth_technique] != \'\' ? render_value(\'anesth_technique\') : \'-\' %></v>\r\n					    </td>\r\n					</tr>\r\n<%\r\n    rds = this_rec[:recovery_date_start]\r\n    rts = this_rec[:recovery_time_start].strftime(\'%H:%M\')\r\n    rde = this_rec[:recovery_date_end]\r\n    rte = this_rec[:recovery_time_end].strftime(\'%H:%M\')\r\n    \r\n    n_rds = this_rec[:recovery_non_official_date_start] if this_rec[:recovery_non_official_date_start]\r\n    n_rts = this_rec[:recovery_non_official_time_start].strftime(\'%H:%M\') if this_rec[:recovery_non_official_time_start]\r\n    n_rde = this_rec[:recovery_non_official_date_end] if this_rec[:recovery_non_official_date_end]\r\n    n_rte = this_rec[:recovery_non_official_time_end].strftime(\'%H:%M\') if this_rec[:recovery_non_official_time_end]\r\n    \r\n    ors = \"\\\\#{rds} \\\\#{rts}\"\r\n    ore = \"\\\\#{rde} \\\\#{rte}\"\r\n    nrs = \"\\\\#{n_rds} \\\\#{n_rts}\"\r\n    nre = \"\\\\#{n_rde} \\\\#{n_rte}\"\r\n    b_r = false\r\n    if nrs != nre\r\n        b_r = true\r\n    end\r\n    \r\n    ort = this_rec[:recovery_time] if this_rec[:recovery_time]\r\n    nrt = this_rec[:recovery_non_official_time_min] if this_rec[:recovery_non_official_time_min]\r\n    r_time = ort.to_i + nrt.to_i\r\n%>\r\n					<tr>\r\n					    <td>\r\n					        <span class=\"intro\"><u><i>Post anesthetic period</i></u></span><br/>\r\n					        <% if b_r %>\r\n					        <span class=\"tab intro\">Recovery official time </span> <br/>\r\n					        <span class=\"tab\"></span><span class=\"tab intro\">: </span> <v><%= ors %> to <%= ore %>  </v> <br/>\r\n					        <span class=\"tab intro\">Recovery non-official time </span> <br/>\r\n					        <span class=\"tab\"></span><span class=\"tab intro\">: </span> <v><%= nrs %> to <%= nre %>  </v> <br/>\r\n					        <% else %>\r\n					        <span class=\"tab intro\">Recovery start </span> <br/>\r\n					        <span class=\"tab\"></span><span class=\"tab intro\">: </span> <v><%= ors %>  </v> <br/>\r\n					        <span class=\"tab intro\">Recovery end  </span> <br/>\r\n					        <span class=\"tab\"></span><span class=\"tab intro\">: </span> <v><%= ore %>  </v>  <br/>\r\n					        <% end %>\r\n					        <!--<span class=\"tab intro\">Recovery start : </span> <v><%= rds %> <%= rts %>  </v> <br/>-->\r\n					        <!--<span class=\"tab intro\">Recovery end : </span> <v><%= rde %> <%= rte %> </v> <br/>-->\r\n                            <span class=\"tab intro\">Recovery duration : </span> <v><%= r_time %> </v> min. <br/>\r\n                            <span class=\"tab intro\">Recovery place : </span> <v><%= this_rec[:recovery_place] != \'\' ? render_value(\'recovery_place\') : \'-\' %></v> <br/>\r\n                        </td>\r\n					</tr>\r\n				    <tr>\r\n					    <td>\r\n					        <span class=\"intro\"><u><i>24 - 48 hrs. Post anesthetic period</i></u></span><br/>\r\n					        <span class=\"tab intro\">Pain score : </span> <v><%= this_rec[:pain_score] %> (<%= this_rec[:pain_score_type] != \'\' ? render_value(\'pain_score_type\') : \'-\' %>)</v><br/>\r\n					        <span class=\"tab intro\">Pain management : </span> <v><%= this_rec[:pain_management] != \'\' ? render_value(\'pain_management\') : \'-\' %></v> <br/>\r\n					        <span class=\"tab intro\">GCS : </span> <v><%= this_rec[:alteration_gcs] != \'\' ? this_rec[:alteration_gcs] : \'-\' %> (E : <%= this_rec[:alteration_e] %>) (V : <%= this_rec[:alteration_v] %>) (M : <%= this_rec[:alteration_m] %>)</v>\r\n					    </td>\r\n					</tr>\r\n					<tr>\r\n					    <td>\r\n					        <span class=\"intro\"><u><i>24 - 48 hrs. Post anesthetic problems</i></u></span><br/>\r\n					        <span class=\"tab intro\">Problems : </span> <v><%= this_rec[:post_operative_problems] != \'\' ? render_value(\'post_operative_problems\') : \'-\' %></v><br/>\r\n					    </td>\r\n					</tr>\r\n					<tr>\r\n					    <td>\r\n					        <span class=\"intro\"><u><i>Management</i></u></span><br/>\r\n					        <v><blockquote><%= this_rec[:management] != \'\' ? this_rec[:management].html_safe : \'-\' %></blockquote></v>\r\n					    </td>\r\n					</tr>\r\n					<tr>\r\n					    <td>\r\n					        <span class=\"intro\"><u><i>Note</i></u></span><br/>\r\n					        <v><blockquote><%= this_rec[:post_note] != \'\' ? this_rec[:post_note].html_safe : \'-\' %></blockquote></v>\r\n					    </td>\r\n					</tr>\r\n				</table>\r\n				\r\n				<!--  right column -->\r\n				<table width=\"50%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:right\">\r\n					<tr>\r\n						<td>\r\n						    <span class=\"intro\"><u><i>Modified Aldrete Scoring System (MASS)</i></u></span><br/>\r\n						    <table width=\"100%\">\r\n						        <tr>\r\n						            <td style=\'border-bottom:1px dashed gray\'> </td>\r\n						            <td align=\'center\' width=\'10%\' style=\'border-bottom:1px dashed gray\'>WARD</td>\r\n						        </tr>\r\n						        <tr>\r\n						            <td style=\'border-bottom:1px dashed gray\'>\r\n						                <b>Activity</b> : able to move, voluntarily or on command<br/>\r\n						                (2) Four extremities<br/>\r\n						                (1) Two extremities<br/>\r\n						                (0) No extremities<br/>\r\n						            </td>\r\n						            <td align=\'center\' style=\'border-bottom:1px dashed gray\'>\r\n						                <v><%= this_rec[:activity_ward] %></v>\r\n						            </td>\r\n						        </tr>\r\n						        <tr>\r\n						            <td style=\'border-bottom:1px dashed gray\'>\r\n						                <b>Respiration</b><br/>\r\n						                (2) Able to breathe deeply and cough freely<br/>\r\n						                (1) Dyspnea, shallow or limilted breathing <br/>\r\n						                (0) Apnea<br/>\r\n						            </td>\r\n						            <td align=\'center\' style=\'border-bottom:1px dashed gray\'>\r\n						                <v><%= this_rec[:respiration_ward] %></v>\r\n						            </td>\r\n						        </tr>\r\n						        <tr>\r\n						            <td style=\'border-bottom:1px dashed gray\'>\r\n						                <b>Circulation</b><br/>\r\n						                (2) BR +/- 20 mmHg of preoperative level<br/>\r\n						                (1) BR +/- 20-50 mmHg of preoperative level<br/>\r\n						                (0) BR +/- 50 mmHg of preoperative level <br/>\r\n						            </td>\r\n						            <td align=\'center\' style=\'border-bottom:1px dashed gray\'>\r\n						                <v><%= this_rec[:circulation_ward] %></v>\r\n						            </td>\r\n						        </tr>\r\n						        <tr>\r\n						            <td style=\'border-bottom:1px dashed gray\'>\r\n						                <b>Consciousness</b><br/>\r\n						                (2) Fully awake<br/>\r\n						                (1) Arousable on calling<br/>\r\n						                (0) Unresponsive<br/>\r\n						            </td>\r\n						            <td align=\'center\' style=\'border-bottom:1px dashed gray\'>\r\n						                <v><%= this_rec[:consciousness_ward] %></v>\r\n						            </td>\r\n						        </tr>\r\n						        <tr>\r\n						            <td style=\'border-bottom:1px dashed gray\'>\r\n						                <b>Oxygen saturation</b><br/>\r\n						                (2) SpO2 ≥ 92% with room air<br/>\r\n						                (1) SpO2 ≥ 92% with oxygen<br/>\r\n						                (0) SpO2 < 92% with oxygen<br/>\r\n						            </td>\r\n						            <td align=\'center\' style=\'border-bottom:1px dashed gray\'>\r\n						                <v><%= this_rec[:oxygen_saturation_ward] %></v>\r\n						            </td>\r\n						        </tr>\r\n						        <tr>\r\n						            <td style=\'border-bottom:1px dashed gray\'>\r\n						                <b>TOTAL MASS SCORE</b>\r\n						            </td>\r\n						            <td align=\'center\' style=\'border-bottom:1px dashed gray\'>\r\n						                <v><%= this_rec[:total_mass_ward] %></v>\r\n						            </td>\r\n						        </tr>\r\n						        <tr>\r\n						            <td style=\'border-bottom:1px dashed gray\'>\r\n						                <b>Sedation score</b> \r\n						            </td>\r\n						            <td align=\'center\' style=\'border-bottom:1px dashed gray\'>\r\n						                <v><%= this_rec[:sedation_ward] %></v>\r\n						            </td>\r\n						        </tr>\r\n						    </table>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n					    <td>\r\n					    </td>\r\n					</tr>\r\n				</table>\r\n				<div class=\"clear\"></div>\r\n				\r\n				<%# render :inline=>this.display %>\r\n				\r\n				\r\n			\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n		<div class=\"clear\"></div>\r\n	</div>\r\n</body>\r\n</html>\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2015-08-30 16:49:19','2015-08-30 16:49:19','print_partial',''),(1791,'header',714,1,'\"Department of Anesthesiology<br/>Prasat Neurological Institute\".html_safe',NULL,NULL,NULL,'2015-08-30 18:27:03','2015-08-30 18:27:03','header',''),(1792,'print',714,3,'<%= this.print_partial.html_safe %>\r\n<% if @current_role!=\'developer\' %>\r\n<script>\r\n    var millisecondsToWait = 2000;\r\n    setTimeout(function() {\r\n        window.print();\r\n    }, millisecondsToWait);\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2015-08-30 18:37:59','2015-08-30 18:37:59','print','');
INSERT INTO `esm_operations` VALUES (1794,'list',725,3,'<style>\r\n/*!\r\n * FullCalendar v1.6.0 Stylesheet\r\n * Docs & License: http://arshaw.com/fullcalendar/\r\n * (c) 2013 Adam Shaw\r\n */\r\n\r\n\r\n.fc {\r\n    direction: ltr;\r\n	text-align: left;\r\n	}\r\n	\r\n.fc table {\r\n	border-collapse: collapse;\r\n	border-spacing: 0;\r\n	}\r\n	\r\nhtml .fc,\r\n.fc table {\r\n	font-size: 1em;\r\n	}\r\n	\r\n.fc td,\r\n.fc th {\r\n	padding: 0;\r\n	vertical-align: top;\r\n	}\r\n\r\n\r\n\r\n/* Header\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-header td {\r\n	white-space: nowrap;\r\n	}\r\n\r\n.fc-header-left {\r\n	width: 25%;\r\n	text-align: left;\r\n	}\r\n	\r\n.fc-header-center {\r\n	text-align: center;\r\n	}\r\n	\r\n.fc-header-right {\r\n	width: 25%;\r\n	text-align: right;\r\n	}\r\n	\r\n.fc-header-title {\r\n	display: inline-block;\r\n	vertical-align: top;\r\n	}\r\n	\r\n.fc-header-title h2 {\r\n	margin-top: 0;\r\n	white-space: nowrap;\r\n	}\r\n	\r\n.fc .fc-header-space {\r\n	padding-left: 10px;\r\n	}\r\n	\r\n.fc-header .fc-button {\r\n	margin-bottom: 1em;\r\n	vertical-align: top;\r\n	}\r\n	\r\n/* buttons edges butting together */\r\n\r\n.fc-header .fc-button {\r\n	margin-right: -1px;\r\n	}\r\n	\r\n.fc-header .fc-corner-right,  /* non-theme */\r\n.fc-header .ui-corner-right { /* theme */\r\n	margin-right: 0; /* back to normal */\r\n	}\r\n	\r\n/* button layering (for border precedence) */\r\n	\r\n.fc-header .fc-state-hover,\r\n.fc-header .ui-state-hover {\r\n	z-index: 2;\r\n	}\r\n	\r\n.fc-header .fc-state-down {\r\n	z-index: 3;\r\n	}\r\n\r\n.fc-header .fc-state-active,\r\n.fc-header .ui-state-active {\r\n	z-index: 4;\r\n	}\r\n	\r\n	\r\n	\r\n/* Content\r\n------------------------------------------------------------------------*/\r\n	\r\n.fc-content {\r\n	clear: both;\r\n	}\r\n	\r\n.fc-view {\r\n	width: 100%; /* needed for view switching (when view is absolute) */\r\n	overflow: hidden;\r\n	}\r\n	\r\n	\r\n\r\n/* Cell Styles\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-widget-header,    /* <th>, usually */\r\n.fc-widget-content {  /* <td>, usually */\r\n	border: 1px solid #ddd;\r\n	}\r\n	\r\n.fc-state-highlight { /* <td> today cell */ /* TODO: add .fc-today to <th> */\r\n	background: #fcf8e3;\r\n	}\r\n	\r\n.fc-cell-overlay { /* semi-transparent rectangle while dragging */\r\n	background: #bce8f1;\r\n	opacity: .3;\r\n	filter: alpha(opacity=30); /* for IE */\r\n	}\r\n	\r\n\r\n\r\n/* Buttons\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-button {\r\n	position: relative;\r\n	display: inline-block;\r\n	padding: 0 .6em;\r\n	overflow: hidden;\r\n	height: 1.9em;\r\n	line-height: 1.9em;\r\n	white-space: nowrap;\r\n	cursor: pointer;\r\n	}\r\n	\r\n.fc-state-default { /* non-theme */\r\n	border: 1px solid;\r\n	}\r\n\r\n.fc-state-default.fc-corner-left { /* non-theme */\r\n	border-top-left-radius: 4px;\r\n	border-bottom-left-radius: 4px;\r\n	}\r\n\r\n.fc-state-default.fc-corner-right { /* non-theme */\r\n	border-top-right-radius: 4px;\r\n	border-bottom-right-radius: 4px;\r\n	}\r\n\r\n/*\r\n	Our default prev/next buttons use HTML entities like &lsaquo; &rsaquo; &laquo; &raquo;\r\n	and we\'ll try to make them look good cross-browser.\r\n*/\r\n\r\n.fc-text-arrow {\r\n	margin: 0 .1em;\r\n	font-size: 2em;\r\n	font-family: \"Courier New\", Courier, monospace;\r\n	vertical-align: baseline; /* for IE7 */\r\n	}\r\n\r\n.fc-button-prev .fc-text-arrow,\r\n.fc-button-next .fc-text-arrow { /* for &lsaquo; &rsaquo; */\r\n	font-weight: bold;\r\n	}\r\n	\r\n/* icon (for jquery ui) */\r\n	\r\n.fc-button .fc-icon-wrap {\r\n	position: relative;\r\n	float: left;\r\n	top: 50%;\r\n	}\r\n	\r\n.fc-button .ui-icon {\r\n	position: relative;\r\n	float: left;\r\n	margin-top: -50%;\r\n	*margin-top: 0;\r\n	*top: -50%;\r\n	}\r\n	\r\n/*\r\n  button states\r\n  borrowed from twitter bootstrap (http://twitter.github.com/bootstrap/)\r\n*/\r\n\r\n.fc-state-default {\r\n	background-color: #f5f5f5;\r\n	background-image: -moz-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: -webkit-gradient(linear, 0 0, 0 100%, from(#ffffff), to(#e6e6e6));\r\n	background-image: -webkit-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: -o-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: linear-gradient(to bottom, #ffffff, #e6e6e6);\r\n	background-repeat: repeat-x;\r\n	border-color: #e6e6e6 #e6e6e6 #bfbfbf;\r\n	border-color: rgba(0, 0, 0, 0.1) rgba(0, 0, 0, 0.1) rgba(0, 0, 0, 0.25);\r\n	color: #333;\r\n	text-shadow: 0 1px 1px rgba(255, 255, 255, 0.75);\r\n	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2), 0 1px 2px rgba(0, 0, 0, 0.05);\r\n	}\r\n\r\n.fc-state-hover,\r\n.fc-state-down,\r\n.fc-state-active,\r\n.fc-state-disabled {\r\n	color: #333333;\r\n	background-color: #e6e6e6;\r\n	}\r\n\r\n.fc-state-hover {\r\n	color: #333333;\r\n	text-decoration: none;\r\n	background-position: 0 -15px;\r\n	-webkit-transition: background-position 0.1s linear;\r\n	   -moz-transition: background-position 0.1s linear;\r\n	     -o-transition: background-position 0.1s linear;\r\n	        transition: background-position 0.1s linear;\r\n	}\r\n\r\n.fc-state-down,\r\n.fc-state-active {\r\n	background-color: #cccccc;\r\n	background-image: none;\r\n	outline: 0;\r\n	box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.15), 0 1px 2px rgba(0, 0, 0, 0.05);\r\n	}\r\n\r\n.fc-state-disabled {\r\n	cursor: default;\r\n	background-image: none;\r\n	opacity: 0.65;\r\n	filter: alpha(opacity=65);\r\n	box-shadow: none;\r\n	}\r\n\r\n	\r\n\r\n/* Global Event Styles\r\n------------------------------------------------------------------------*/\r\n	 \r\n.fc-event {\r\n	border: 1px solid #3a87ad; /* default BORDER color */\r\n	background-color: #3a87ad; /* default BACKGROUND color */\r\n	color: #fff;               /* default TEXT color */\r\n	text-shadow: 0 -1px 0 rgba(0, 0, 0, 0.25);\r\n	font-size: .85em;\r\n	cursor: default;\r\n	}\r\n\r\na.fc-event {\r\n	text-decoration: none;\r\n	}\r\n	\r\na.fc-event,\r\n.fc-event-draggable {\r\n	cursor: pointer;\r\n	}\r\n	\r\n.fc-rtl .fc-event {\r\n	text-align: right;\r\n	}\r\n\r\n.fc-event-inner {\r\n	width: 100%;\r\n	overflow: hidden;\r\n	}\r\n	\r\n.fc-event-time,\r\n.fc-event-title {\r\n	padding: 0 1px;\r\n	}\r\n	\r\n.fc .ui-resizable-handle {\r\n	display: block;\r\n	position: absolute;\r\n	z-index: 99999;\r\n	overflow: hidden; /* hacky spaces (IE6/7) */\r\n	font-size: 300%;  /* */\r\n	line-height: 50%; /* */\r\n	}\r\n	\r\n	\r\n	\r\n/* Horizontal Events\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-event-hori {\r\n	border-width: 1px 0;\r\n	margin-bottom: 1px;\r\n	}\r\n\r\n.fc-ltr .fc-event-hori.fc-event-start,\r\n.fc-rtl .fc-event-hori.fc-event-end {\r\n	border-left-width: 1px;\r\n	border-top-left-radius: 3px;\r\n	border-bottom-left-radius: 3px;\r\n	}\r\n\r\n.fc-ltr .fc-event-hori.fc-event-end,\r\n.fc-rtl .fc-event-hori.fc-event-start {\r\n	border-right-width: 1px;\r\n	border-top-right-radius: 3px;\r\n	border-bottom-right-radius: 3px;\r\n	}\r\n	\r\n/* resizable */\r\n	\r\n.fc-event-hori .ui-resizable-e {\r\n	top: 0           !important; /* importants override pre jquery ui 1.7 styles */\r\n	right: -3px      !important;\r\n	width: 7px       !important;\r\n	height: 100%     !important;\r\n	cursor: e-resize;\r\n	}\r\n	\r\n.fc-event-hori .ui-resizable-w {\r\n	top: 0           !important;\r\n	left: -3px       !important;\r\n	width: 7px       !important;\r\n	height: 100%     !important;\r\n	cursor: w-resize;\r\n	}\r\n	\r\n.fc-event-hori .ui-resizable-handle {\r\n	_padding-bottom: 14px; /* IE6 had 0 height */\r\n	}\r\n	\r\n	\r\n	\r\n/* Reusable Separate-border Table\r\n------------------------------------------------------------*/\r\n\r\ntable.fc-border-separate {\r\n	border-collapse: separate;\r\n	}\r\n	\r\n.fc-border-separate th,\r\n.fc-border-separate td {\r\n	border-width: 1px 0 0 1px;\r\n	}\r\n	\r\n.fc-border-separate th.fc-last,\r\n.fc-border-separate td.fc-last {\r\n	border-right-width: 1px;\r\n	}\r\n	\r\n.fc-border-separate tr.fc-last th,\r\n.fc-border-separate tr.fc-last td {\r\n	border-bottom-width: 1px;\r\n	}\r\n	\r\n.fc-border-separate tbody tr.fc-first td,\r\n.fc-border-separate tbody tr.fc-first th {\r\n	border-top-width: 0;\r\n	}\r\n	\r\n	\r\n\r\n/* Month View, Basic Week View, Basic Day View\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-grid th {\r\n	text-align: center;\r\n	}\r\n\r\n.fc .fc-week-number {\r\n	width: 22px;\r\n	text-align: center;\r\n	}\r\n\r\n.fc .fc-week-number div {\r\n	padding: 0 2px;\r\n	}\r\n	\r\n.fc-grid .fc-day-number {\r\n	float: right;\r\n	padding: 0 2px;\r\n	}\r\n	\r\n.fc-grid .fc-other-month .fc-day-number {\r\n	opacity: 0.3;\r\n	filter: alpha(opacity=30); /* for IE */\r\n	/* opacity with small font can sometimes look too faded\r\n	   might want to set the \'color\' property instead\r\n	   making day-numbers bold also fixes the problem */\r\n	}\r\n	\r\n.fc-grid .fc-day-content {\r\n	clear: both;\r\n	padding: 2px 2px 1px; /* distance between events and day edges */\r\n	}\r\n	\r\n/* event styles */\r\n	\r\n.fc-grid .fc-event-time {\r\n	font-weight: bold;\r\n	}\r\n	\r\n/* right-to-left */\r\n	\r\n.fc-rtl .fc-grid .fc-day-number {\r\n	float: left;\r\n	}\r\n	\r\n.fc-rtl .fc-grid .fc-event-time {\r\n	float: right;\r\n	}\r\n	\r\n	\r\n\r\n/* Agenda Week View, Agenda Day View\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-agenda table {\r\n	border-collapse: separate;\r\n	}\r\n	\r\n.fc-agenda-days th {\r\n	text-align: center;\r\n	}\r\n	\r\n.fc-agenda .fc-agenda-axis {\r\n	width: 50px;\r\n	padding: 0 4px;\r\n	vertical-align: middle;\r\n	text-align: right;\r\n	white-space: nowrap;\r\n	font-weight: normal;\r\n	}\r\n\r\n.fc-agenda .fc-week-number {\r\n	font-weight: bold;\r\n	}\r\n	\r\n.fc-agenda .fc-day-content {\r\n	padding: 2px 2px 1px;\r\n	}\r\n	\r\n/* make axis border take precedence */\r\n	\r\n.fc-agenda-days .fc-agenda-axis {\r\n	border-right-width: 1px;\r\n	}\r\n	\r\n.fc-agenda-days .fc-col0 {\r\n	border-left-width: 0;\r\n	}\r\n	\r\n/* all-day area */\r\n	\r\n.fc-agenda-allday th {\r\n	border-width: 0 1px;\r\n	}\r\n	\r\n.fc-agenda-allday .fc-day-content {\r\n	min-height: 34px; /* TODO: doesnt work well in quirksmode */\r\n	_height: 34px;\r\n	}\r\n	\r\n/* divider (between all-day and slots) */\r\n	\r\n.fc-agenda-divider-inner {\r\n	height: 2px;\r\n	overflow: hidden;\r\n	}\r\n	\r\n.fc-widget-header .fc-agenda-divider-inner {\r\n	background: #eee;\r\n	}\r\n	\r\n/* slot rows */\r\n	\r\n.fc-agenda-slots th {\r\n	border-width: 1px 1px 0;\r\n	}\r\n	\r\n.fc-agenda-slots td {\r\n	border-width: 1px 0 0;\r\n	background: none;\r\n	}\r\n	\r\n.fc-agenda-slots td div {\r\n	height: 20px;\r\n	}\r\n	\r\n.fc-agenda-slots tr.fc-slot0 th,\r\n.fc-agenda-slots tr.fc-slot0 td {\r\n	border-top-width: 0;\r\n	}\r\n\r\n.fc-agenda-slots tr.fc-minor th,\r\n.fc-agenda-slots tr.fc-minor td {\r\n	border-top-style: dotted;\r\n	}\r\n	\r\n.fc-agenda-slots tr.fc-minor th.ui-widget-header {\r\n	*border-top-style: solid; /* doesn\'t work with background in IE6/7 */\r\n	}\r\n	\r\n\r\n\r\n/* Vertical Events\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-event-vert {\r\n	border-width: 0 1px;\r\n	}\r\n\r\n.fc-event-vert.fc-event-start {\r\n	border-top-width: 1px;\r\n	border-top-left-radius: 3px;\r\n	border-top-right-radius: 3px;\r\n	}\r\n\r\n.fc-event-vert.fc-event-end {\r\n	border-bottom-width: 1px;\r\n	border-bottom-left-radius: 3px;\r\n	border-bottom-right-radius: 3px;\r\n	}\r\n	\r\n.fc-event-vert .fc-event-time {\r\n	white-space: nowrap;\r\n	font-size: 10px;\r\n	}\r\n\r\n.fc-event-vert .fc-event-inner {\r\n	position: relative;\r\n	z-index: 2;\r\n	}\r\n	\r\n.fc-event-vert .fc-event-bg { /* makes the event lighter w/ a semi-transparent overlay  */\r\n	position: absolute;\r\n	z-index: 1;\r\n	top: 0;\r\n	left: 0;\r\n	width: 100%;\r\n	height: 100%;\r\n	background: #fff;\r\n	opacity: .3;\r\n	filter: alpha(opacity=30);\r\n	}\r\n	\r\n.fc .ui-draggable-dragging .fc-event-bg, /* TODO: something nicer like .fc-opacity */\r\n.fc-select-helper .fc-event-bg {\r\n	display: none\\9; /* for IE6/7/8. nested opacity filters while dragging don\'t work */\r\n	}\r\n	\r\n/* resizable */\r\n	\r\n.fc-event-vert .ui-resizable-s {\r\n	bottom: 0        !important; /* importants override pre jquery ui 1.7 styles */\r\n	width: 100%      !important;\r\n	height: 8px      !important;\r\n	overflow: hidden !important;\r\n	line-height: 8px !important;\r\n	font-size: 11px  !important;\r\n	font-family: monospace;\r\n	text-align: center;\r\n	cursor: s-resize;\r\n	}\r\n	\r\n.fc-agenda .ui-resizable-resizing { /* TODO: better selector */\r\n	_overflow: hidden;\r\n	}\r\n	\r\n	\r\n</style>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   records = []\r\n   n = 10 \r\n%>\r\n<%\r\n   \r\n   values = {}\r\n   query=\'\'\r\n   if params[:search]\r\n\r\n        \r\n        query = params[:search][:query]\r\n          keys = []\r\n    \r\n        @patient_doc.list_fields.each_with_index do |f,index| \r\n		    keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        \r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n\r\n                \r\n        ps = @patient_model.all({\'$or\'=>keys}.merge!(dates))\r\n   \r\n        records = []\r\n        for i in ps\r\n            records+= @module_model.where(:patient_id=>i.id,:module_name=>@module_name).all\r\n        end\r\n        count = records.size\r\n        \r\n        \r\n    else\r\n        from_date = nil\r\n        to_date = nil  \r\n          n = @module_model.where(:module_name=>@module_name).count\r\n        rows,offset,page = params[:paginate]\r\n        records = @module_model.where(:module_name=>@module_name).all(:order=>\'created_at desc\',:limit=>20)\r\n    end\r\n\r\n\r\n patients = {}\r\n @patient_model.find(records.collect{|i| i.patient_id}).each do |i|\r\n patients[i.id]=i\r\n end\r\n appointments = {}\r\n @models[:appointment].find(records.collect{|i| i.module_id}).each do |i|\r\n appointments[i.id]=i\r\n end\r\n \r\n title = \'Calendar\'\r\n \r\n if params[:provider_id]\r\n    provider = @models[:provider].find(params[:provider_id])\r\n    title = \"\\\\#{provider.name}\'s Calendar\"\r\n end\r\n%>\r\n\r\n  <link rel=\"stylesheet\" href=\"/gebo/lib/fullcalendar/fullcalendar_gebo.css\" />\r\n  <div class=\"row-fluid\">\r\n            			<div class=\"span12\">\r\n							<h2 class=\"heading\"><%= title %></h2>\r\n							<div id=\"calendar\"></div>\r\n						</div>\r\n					</div>\r\n\r\n\r\n    	<script src=\"/gebo/lib/fullcalendar/fullcalendar.min.js\"></script>\r\n			<!-- calendar functions -->\r\n			<script src=\"/gebo/lib/fullcalendar/gcal.js\"></script>\r\n<%\r\n   pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\njson_data =   records.collect{|i| \r\nl = %w{#bcdeee}\r\nap = appointments[i.module_id] \r\np = patients[i.patient_id]\r\nif (ap and params[:provider_id]==nil) or (params[:provider_id] and ap.provider.to_s==params[:provider_id].to_s)\r\n     date_d = \'-\'\r\n     date_d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n     date_s = \'-\'\r\n     date_s = ap.date.strftime(\"%Y-%m-%d\")+ap.start.strftime(\" %H:%M\") if ap.date and ap.start\r\n     date_e = \'-\'\r\n     date_e = ap.date.strftime(\"%Y-%m-%d\")+ap.stop.strftime(\" %H:%M\") if ap.date  and ap.stop\r\n     \r\n     \r\n    {\'procedure\'=>pro[ap.procedure],\'date\'=>date_d,\'color\'=>l[rand(4%l.size)],\'title\'=>\"\\\\#{p.first_name if p } \\\\#{p.hn if p}\",\'start\'=>date_s,\'end\'=>date_e,\'allDay\'=>false,\'url\'=>\'edit?id=\'+i.id.to_s}  \r\nelse\r\n    nil\r\nend \r\n}.compact\r\n\r\n    \r\n    df =   @models[:day_off].all\r\n \r\n    \r\n    df_list = df.collect{|i|\r\n        pname = \'\'\r\n        p = @models[:provider].find(i.provider)\r\n        pname = p.name if p\r\n        date =  \'-\'\r\n        date = i.date.strftime(\"%Y-%m-%d\") if i.date\r\n        {\'color\'=>\'#ccc\',\'title\'=>\"\\\\#{i.title} \\\\#{pname}\",\'start\'=>date,\'allDay\'=>true}\r\n    }\r\n    \r\n    map = {}\r\n    \r\n    for i in json_data\r\n    \r\n    date = i[\'date\']\r\n    p = i[\'procedure\']\r\n    \r\n    map[date] = {} unless map[date]\r\n    map[date][p] = 0  unless map[date][p]\r\n    map[date][p] += 1\r\n    \r\n    end\r\n    \r\n    c_list = []\r\n    map.each_pair do |k,v|\r\n         txt = \'\'\r\n         v.each_pair { |key, value| txt+=\"\\\\#{key}=\\\\#{value}   \".html_safe }\r\n         c_list<<{\'color\'=>\'#fcc\',\'title\'=>\"\\\\#{txt}\",\'start\'=>k,\'allDay\'=>true,\'url\'=>\'/\'}\r\n    end\r\n    \r\n    detail = json_data\r\n    \r\n    json_data = df_list\r\n    \r\n    json_data+= c_list\r\n    \r\n    json_data+= detail if params[:detail]    \r\n%>\r\n<%#df.inspect %>\r\n\r\n<script>\r\n\r\n var refresh_loading = false;\r\n\r\n function refresh_date(start,end,detail,provider_id){\r\n    \r\n        if(refresh_loading==false){\r\n        refresh_loading = true\r\n    \r\n        path = \'data\'\r\n        detail_path = \'data_detail\'\r\n      \r\n        $.ajax({\r\n            url: path ,\r\n            dataType: \'json\',\r\n            data: {\r\n                start: start,\r\n                end: end,\r\n                detail: detail,\r\n                provider_id: provider_id\r\n            },\r\n            success: function(doc) {\r\n             data = eval(doc);\r\n            $(\'#calendar\').fullCalendar(\'removeEvents\');\r\n           \r\n            $.each(data, function(index, event){\r\n            $(\'#calendar\').fullCalendar(\'renderEvent\', event);\r\n            });\r\n            }\r\n            });\r\n            \r\n         $.ajax({\r\n            url: detail_path,\r\n            data: {\r\n                start: start,\r\n                end: end,\r\n                detail: detail,\r\n                provider_id: provider_id\r\n            },\r\n            success: function(doc) {\r\n                $(\'#event-details\').html(doc);\r\n            }\r\n         });\r\n\r\n    refresh_loading=false;\r\n     $(\'#loading\').hide();\r\n        }\r\n    \r\n}\r\n    $(document).ready(function() {\r\n\r\n\r\n\r\n\r\n\r\n        gebo_calendar.regular();\r\n\r\n		//* resize elements on window resize\r\n		var lastWindowHeight = $(window).height();\r\n		var lastWindowWidth = $(window).width();\r\n		$(window).on(\"debouncedresize\",function() {\r\n      \r\n			if($(window).height()!=lastWindowHeight || $(window).width()!=lastWindowWidth){\r\n				lastWindowHeight = $(window).height();\r\n				lastWindowWidth = $(window).width();\r\n				//* rebuild calendar\r\n			}\r\n		});\r\n	});\r\n	\r\n	//* calendar\r\n	gebo_calendar = {\r\n		regular: function() {\r\n			var date = new Date();\r\n			var d = date.getDate();\r\n			var m = date.getMonth();\r\n			var y = date.getFullYear();\r\n			var calendar = $(\'#calendar\').fullCalendar({\r\n				header: {\r\n					left: \'prev,next today\',\r\n					center: \'title\',\r\n					right: \'month,agendaWeek,agendaDay\'\r\n				},\r\n		\r\n				aspectRatio: 2,\r\n				selectable: true,\r\n				selectHelper: true,\r\n                \r\n      dayClick: function(date, allDay, jsEvent, view) {\r\n      if($(\'#calendar\').fullCalendar( \'getView\').name!=\'month\')\r\n            window.location=\"../DayOff/create?data[date]=\"+date.getFullYear()+\'-\'+(date.getMonth()+1)+\'-\'+date.getDate() +\"&return=../Appointment/index\"\r\n      $(\'#calendar\').fullCalendar( \'changeView\', \'agendaDay\' );\r\n      $(\'#calendar\').fullCalendar( \'gotoDate\', date.getFullYear() ,date.getMonth(), date.getDate()  );\r\n      \r\n       provider_id = \"<%=params[:provider_id]%>\";\r\n      \r\n       refresh_date(date.getTime()/1000,date.getTime()/1000+3600*24-1,true,provider_id);\r\n      \r\n     \r\n      \r\n      },\r\n      viewDisplay: function(view) {\r\n          \r\n\r\n        if(view.name == \'month\')\r\n        { \r\n            $(\'#calendar\').fullCalendar(\'refetchEvents\');\r\n        }\r\n        if(view.name==\'agendaWeek\'){\r\n             $(\'#calendar\').fullCalendar(\'refetchEvents\');\r\n        }\r\n      },\r\n	  select: function(start, end, allDay) {\r\n               \r\n      if(allDay==false){\r\n	        calendar.fullCalendar(\'unselect\');\r\n            window.location=\"create?data[date]=\"+start.getFullYear()+\'-\'+(start.getMonth()+1)+\'-\'+start.getDate()+\"&data[start]=\"+\r\n            start.getHours()+\":\"+start.getMinutes()+\"&data[stop]=\"+end.getHours()+\":\"+end.getMinutes()\r\n      }\r\n               \r\n	  }\r\n      ,\r\n	  editable: false,\r\n	  theme: false,\r\n	  events: function(start, end, callback) {\r\n   \r\n    \r\n      provider_id = \"<%=params[:provider_id]%>\";\r\n    \r\n  \r\n      refresh_date(Math.round(start.getTime() / 1000),Math.round(end.getTime() / 1000),<%=params[:detail]==\'true\'%>,provider_id);\r\n         \r\n\r\n     },\r\n	  loading: function(bool) {\r\n	  if (bool) $(\'#loading\').show();\r\n	  else $(\'#loading\').hide();\r\n	  }\r\n	});\r\n	}\r\n	};\r\n</script>\r\n<!--<div id=\'loading\' style=\'display:none\'>Loading...</div>-->\r\n\r\n<!--<div id=\"event-details\"></div>-->\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-08-31 17:55:47','2015-08-31 17:55:47','list',''),(1795,'data',725,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   records = []\r\n   n = 10 \r\n   show_detail = false\r\n   show_detail = params[:detail]!=nil\r\n   start = Time.at(params[:start].to_i)\r\n   stop = Time.at(params[:end].to_i)\r\n%>\r\n<%\r\n   \r\n   values = {}\r\n   query=\'\'\r\n   if params[:search]\r\n\r\n        \r\n        query = params[:search][:query]\r\n          keys = []\r\n    \r\n        @patient_doc.list_fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        \r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n\r\n                \r\n        ps = @patient_model.all({\'$or\'=>keys}.merge!(dates))\r\n   \r\n        records = []\r\n        for i in ps\r\n            records+= @module_model.where(:patient_id=>i.id,:module_name=>@module_name).all\r\n        end\r\n        count = records.size\r\n        \r\n        \r\n    else\r\n        from_date = start\r\n        to_date = stop\r\n        # find all in period\r\n        appointments = @models[:appointment].where(\"date\"=> {\"$gte\"=> from_date, \"$lt\"=> to_date}).all\r\n        \r\n    end\r\n\r\n   \r\n \r\n \r\n \r\n n = appointments.size\r\n rows,offset,page = params[:paginate]\r\n \r\n    pro = {}\r\n    \r\n    \r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name \r\n    pro[i.id] = i.code if i.code and i.code!=\'\'\r\n    end\r\n    \r\n    vtypes = {}\r\n    \r\n    @models[:visit_type].all.each do |i|\r\n    vtypes[i.id] = i.name \r\n    end\r\n    \r\n \r\n \r\n records = {}\r\n patients = {}\r\n providers = {}\r\n \r\n \r\n if params[:detail]!=nil\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n records[i.module_id]=i\r\n end\r\n @patient_model.find(records.values.collect{|i| i.patient_id}).each do |i|\r\n patients[i.id]=i\r\n end\r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n \r\n end\r\n \r\n \r\n text = \"\\\\#{start} - \\\\#{stop}\"\r\n \r\n \r\njson_data =   appointments.collect{|ap| \r\n    i  = records[ap.id]\r\n    p = patients[i.patient_id] if i\r\n    provider = providers[ap.provider.to_s]\r\n    l = %w{#bcdeee}\r\n    if (ap and params[:provider_id]==\'\') or (params[:provider_id] and params[:provider_id] !=\'\' and ap.provider.to_s==params[:provider_id].to_s)\r\n         date_d = \'-\'\r\n         date_d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n         date_s = \'-\'\r\n         date_s = ap.date.strftime(\"%Y-%m-%d\")+ap.start.strftime(\" %H:%M\") if ap.date and ap.start\r\n         date_e = \'-\'\r\n         date_e = ap.date.strftime(\"%Y-%m-%d\")+ap.stop.strftime(\" %H:%M\") if ap.date  and ap.stop\r\n    \r\n        {\'procedure\'=>pro[ap.procedure],\r\n        \'vtype\'=>vtypes[ap.visit_type],\r\n        \'date\'=>date_d,\r\n        \'color\'=>l[rand(4%l.size)],\r\n        \'title\'=>\"\\\\#{ provider.name if provider} : \\\\#{p.first_name if p } \\\\#{p.hn if p}\",\r\n        \'start\'=>date_s,\r\n        \'end\'=>date_e,\r\n        \'allDay\'=>false,\r\n        \'url\'=>\"show?id=\\\\#{i.id if i}\" }  \r\n    else\r\n        nil\r\n    end \r\n}.compact\r\n\r\n    \r\n    df =   @models[:day_off].all\r\n \r\n    \r\n    df_list = df.collect{|i|\r\n        pname = \'\'\r\n        p = @models[:provider].find(i.provider)\r\n        pname = p.name if p\r\n        edit = \"../DayOff/show?id=\\\\#{i.id}\"\r\n        if i.to_date\r\n        {\'color\'=>\'#ccc\',\'title\'=>\"\\\\#{i.title} \\\\#{pname}\",\'start\'=>i.date.strftime(\"%Y-%m-%d\"),\'end\'=>i.to_date.strftime(\"%Y-%m-%d\"),\'allDay\'=>true,\'url\'=>edit}\r\n        else\r\n        {\'color\'=>\'#ccc\',\'title\'=>\"\\\\#{i.title} \\\\#{pname}\",\'start\'=>i.date.strftime(\"%Y-%m-%d\"),\'allDay\'=>true,\'url\'=>edit}\r\n        end\r\n    }\r\n    \r\n    map = {}\r\n    \r\n    for i in json_data\r\n    \r\n    date = i[\'date\']\r\n    p = i[\'procedure\']\r\n    v = i[\'vtype\']\r\n    \r\n    map[date] = {} unless map[date]\r\n    map[date][v] = {} unless map[date][v]\r\n    map[date][v][p] = 0 unless map[date][v][p]\r\n    map[date][v][p] += 1\r\n    \r\n    end\r\n    \r\n\r\n    c_list = []\r\n    map.each_pair do |k,v|\r\n         txt = \'\'\r\n         v.each_pair { |key, value| \r\n         \r\n            txt+=\"\\\\#{key}:\\\\#{value.to_a.collect{|x| x.join(\'=\')}.join(\',\')}, \".html_safe \r\n         \r\n         \r\n         }\r\n         c_list<<{\'color\'=>\'#fcc\',\'title\'=>\"\\\\#{txt}\",\'start\'=>k,\'allDay\'=>true}\r\n    end\r\n    \r\n    detail = json_data\r\n    \r\n    json_data = df_list\r\n    \r\n    json_data+= c_list\r\n    \r\n    json_data+= detail if params[:detail] ==\'true\'   \r\n \r\n \r\n%>\r\n<%=json_data.to_json.html_safe%>\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-08-31 18:09:48','2015-08-31 18:09:48','data',''),(1797,'document_name',782,1,'\'pre_anesthetic\'',NULL,NULL,NULL,'2015-09-03 06:33:42','2015-09-03 06:33:42',NULL,NULL),(1798,'document_name',783,1,'\'post_anesthetic\'',NULL,NULL,NULL,'2015-09-03 06:38:20','2015-09-03 06:38:20',NULL,NULL),(1799,'index',784,2,'<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% -34px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .collapsed {\r\n        background-position: 98% 12px;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n</style>\r\n    <!-- nice form elements -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/uniform/Aristo/uniform.aristo.css\" />\r\n	<!-- 2col multiselect -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/multiselect/css/multi-select.css\" />\r\n\r\n<%= render :inline=>this.init %>\r\n\r\n<%\r\n    msg = []\r\n    tmp = nil\r\n    suc_msg = nil\r\n    \r\n    if request.post?\r\n        if !params[:account].nil? and !params[:add_new].nil?\r\n\r\n            acc = params[:account]\r\n            \r\n            if acc[:login_name].empty?\r\n                msg.push(\'Invalid login name\')\r\n            end\r\n            # if params[:account][:full_name].empty?\r\n            #     msg.push(\'Invalid full name\')\r\n            # end\r\n            if acc[:password].empty?\r\n                msg.push(\'No password found\')\r\n            end\r\n            \r\n            full_name = acc[:prefix].strip + acc[:first_name].strip + \" \" + acc[:last_name].strip\r\n            full_name = full_name.strip\r\n            if full_name == \'\'\r\n                msg.push(\'Invalid name\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>params[:account][:login_name]).first\r\n                if m_user\r\n                    msg.push(\'Existing login name\')\r\n                else\r\n                    r_provider = @models[:provider].where({\'name\' => Regexp.new( full_name )})\r\n                    create_user = false\r\n                    # a_prov = m_prov.where({\'name\' => Regexp.new(\'\')})\r\n                    if r_provider.count == 0\r\n                        m_provider = @models[:provider].create :group=>\'default\', :name=>full_name, :prefix=>acc[:prefix], :first_name=>acc[:first_name], :last_name=>acc[:last_name], :login=>params[:account][:login_name], :provider_type=>params[:account][:provider_type]\r\n                        create_user = true\r\n                    elsif r_provider.count == 1\r\n                        m_provider = r_provider.first.update_attributes :login=>params[:account][:login_name]\r\n                        create_user = true\r\n                    else\r\n                        name_list = r_provider.collect{|i| i[:name]}\r\n                        msg.push(\"Existing name (\\\\#{name_list.count}) : \" + name_list.join(\', \'))\r\n                    end\r\n                    \r\n                    if create_user \r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(params[:account][:password], salt)\r\n                        tmp = salt + \'...\' + hashed_password\r\n                        m_user = @ehr_models[:user].create :role=>params[:account][:role], :login=>params[:account][:login_name], :salt=>salt, :hashed_password=>hashed_password, :email=>params[:account][:email], :name=>full_name, :activate=>\"true\"\r\n                        tmp = m_user.id.to_s\r\n                        # tmp += \'...\' + m_provider.id.to_s\r\n                    end\r\n                    \r\n                end\r\n            end\r\n        elsif !params[:account].nil? and !params[:update].nil?\r\n            acc = params[:account]\r\n            \r\n            full_name = acc[:prefix].strip + acc[:first_name].strip + \" \" + acc[:last_name].strip\r\n            full_name = full_name.strip\r\n            if full_name == \'\'\r\n                msg.push(\'Invalid name\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>acc[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>acc[:login_name]).first\r\n                \r\n                m_prov[:name] = full_name\r\n                m_prov[:prefix] = acc[:prefix]\r\n                m_prov[:first_name] = acc[:first_name]\r\n                m_prov[:last_name] = acc[:last_name]\r\n                m_prov[:provider_type] = acc[:provider_type]\r\n                m_prov.save\r\n                \r\n                suc_msg= \"<b>Success</b> Account <b>\\\\#{acc[:login_name]}</b> has been updated\".html_safe\r\n                \r\n                if acc[:password].strip != \'\'\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(px[:new_password], salt)\r\n                    m_user[:hashed_password] = hashed_password\r\n                    m_user[:salt] = salt\r\n                    # m_user.save\r\n                    suc_msg= \"<strong>Success</strong> Account <b>\\\\#{acc[:login_name]}</b> profile and password has been updated\".html_safe\r\n                end\r\n                \r\n                m_user[:name] = full_name\r\n                m_user[:email] = acc[:email]\r\n                m_user[:role] = acc[:role]\r\n                m_user.save\r\n            end\r\n            \r\n        elsif !params[:profile].nil?\r\n            px = params[:profile]\r\n            if px[:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if px[:cur_password].empty?\r\n                msg.push(\'No password to confirm your change\')\r\n            else\r\n                if px[:new_password] != px[:con_password]\r\n                    msg.push(\"Your confirm password not match the new password. Try again.\")\r\n                end\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>px[:login_name]).first\r\n                salt = m_user[:salt]\r\n                hashed_password = User.encrypt(px[:cur_password], salt)\r\n                if m_user[:hashed_password] == hashed_password\r\n                    if px[:con_password] == px[:new_password] and px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        suc_msg= \"<strong>Success</strong> Your profile has been change\".html_safe\r\n                    elsif px[:con_password] == px[:new_password] and !px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(px[:new_password], salt)\r\n                        m_user[:hashed_password] = hashed_password\r\n                        m_user[:salt] = salt\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your profile and password has been change\".html_safe\r\n                    else\r\n                        msg.push(\'Your new and confirm password does not match\')\r\n                    end\r\n                    \r\n                else\r\n                    msg.push(\'Your current password does not match\')\r\n                end\r\n                # msg.push(px[:login_name])\r\n            end\r\n        else\r\n            if @current_role == \'developer\'\r\n%>\r\n<pre>\r\n    <%= params.inspect %>\r\n</pre>\r\n<%\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n<%#list.inspect%>\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                            <div id=\"accordion1\" class=\"accordion\">\r\n<%\r\n    # check admin or developer role\r\n    a_role = @ehr_models[:role].all\r\n    \r\n    map_role = {}\r\n    map_role[\'\']  = \'Na\'\r\n    map_role[nil] = \'N/A\'\r\n    for a in a_role do\r\n        map_role[a.id.to_s] = a[:name]\r\n    end\r\n    \r\n    a_prov = @models[:provider].where(:disabled=>\'\').all\r\n    map_prov = {} # map each record with id\r\n    map_prov[\'\']  = \'Na\'\r\n    map_prov[nil] = \'N/A\'\r\n    \r\n    map_login = {} # map each login\r\n    map_login[\'\']  = \'Na\'\r\n    map_login[nil] = \'N/A\'\r\n    \r\n    for a in a_prov do\r\n        map_prov[a.id.to_s] = a\r\n        map_login[a[:login]] = a\r\n    end\r\n    \r\n    a_proc = @models[:procedure].all\r\n    map_proc = {} # map procedure\r\n    map_proc[\'\']  = \'Na\'\r\n    map_proc[nil] = \'N/A\'\r\n    \r\n    for a in a_proc do\r\n        map_proc[a.id.to_s] = a.name\r\n    end\r\n    \r\n    if @current_role == \'admin\' or @current_role == \'developer\'\r\n        usr = @ehr_models[:user].all.collect do |i|\r\n            # role = @ehr_models[:role].find(i.role)\r\n            # role_name = \'undefined\'\r\n            # if role\r\n            #     role_name = role[:name]\r\n            # end\r\n            role_name = map_role[i.role.to_s]\r\n            provider = @models[:provider].where(:login=>i.login).first\r\n            \r\n            if provider\r\n                {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :i=>i}\r\n            end\r\n        end\r\n%>\r\n<%\r\n    if !msg.empty?\r\n        for m in msg do\r\n%>\r\n                                <div class=\"alert alert-error\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= m %>\r\n    							</div>\r\n<%\r\n        end\r\n    elsif suc_msg\r\n%>\r\n                                <div class=\"alert alert-success\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= suc_msg %>\r\n    							</div>\r\n<%\r\n    end\r\n%>\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#manage\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Manage Provider\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"manage\">\r\n										<div class=\"accordion-inner\">\r\n										    <ul class=\"dshb_icoNav tac\">\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/agent.png)\" href=\"../Provider/index\">\r\n										                <span class=\"label label-success\"><%= @models[:provider].count %></span> Provider</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/addressbook.png)\" href=\"../Procedure/index\">\r\n										                <span class=\"label label-important\"><%= @models[:procedure].count %></span> Procedure</a></li>\r\n									            <li><a style=\"background-image: url(/gebo/img/gCons/arrow-round.png)\" href=\"../VisitType/index\">\r\n										                <span class=\"label label-info\"><%= @models[:visit_type].count %></span> Visit Type</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/lab.png)\" href=\"../Indication/index\">\r\n										                <span class=\"label label-info\"><%= @models[:indication].count %></span> Indication</a></li>\r\n										        <!--\r\n										        <li><a style=\"font-size:.8em;background-image: url(/esm/thks/thks/content/knee.jpg);background-size: 52px 52px;\" href=\"../KneeComponent/index\">\r\n										                <span class=\"label label-info\"><%# c_kcom > 100 ? \"+100\" : c_kcom.to_s %></span> Knee Component</a></li>\r\n										        <li><a style=\"background-image: url(/esm/thks/thks/content/hip.jpg);background-size: 52px 52px;\" href=\"javascript:void(0)\">\r\n										                <span class=\"label label-info\">0</span> Hip Component</a></li>\r\n										                -->\r\n										    </ul>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n\r\n\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Manage Account\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse <%= \'in\' if @current_role==\'developer\' or @current_role==\'admin\' %>\" id=\"collapseOne1\">\r\n										<div class=\"accordion-inner\">\r\n										    <!--<div id=\"form-panel\" class=\"row-fluid\"><%= link_to \'Add New\', \'add_new?update=form-panel\', :remote=>true, :class=>\'btn\', :style=>\'float:right\' %>-->\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :account, :url=>\"index\", :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Add New Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Name</label>\r\n        												<div class=\"controls\">\r\n        												    <div class=\"row-fluid\">\r\n        												    <%= f.text_field :prefix, :class=>\'span2\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    <%= f.text_field :first_name, :class=>\'span4\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    <%= f.text_field :last_name, :class=>\'span4\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    </div>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block span2\">prefix name</span>\r\n        													<span class=\"help-block span4\">name</span>\r\n        													<span class=\"help-block span4\">surname</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">no space, special characters</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<!--\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%# f.text_field :full_name, :class=>\'span10\' %>\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											-->\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'user\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Provider Type</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[provider_type]\" id=\"provider_type\">\r\n                                                                <option value=\"\"></option>\r\n                                                                <option value=\"1\">Doctor\r\n                                                                </option>\r\n                                                                <option value=\"4\">Fellow Doctor\r\n                                                                </option>\r\n                                                                <option value=\"2\">Nurse\r\n                                                                </option>\r\n                                                                <option value=\"3\">Assistant\r\n                                                                </option>\r\n                                                            </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:id=>\'data-add_new\', :name=>\'add_new\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %> \r\n        													<%=f.submit \'Update\',:id=>\'data-update\', :name=>\'update\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;display:none\' %> \r\n        													<%=link_to \'Cancel\', \'#\', :id=>\'data-cancel\', :class=>\'btn\', :style=>\'display:none\', :onclick=>\"javascript:cancel()\" %>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n											<!--<hr/>-->\r\n                                            <div id=\"account\">\r\n											<table class=\"table\">\r\n        										<thead>\r\n        											<tr>\r\n        												<th>No.</th>\r\n        												<th>Login Name</th>\r\n        												<th>Name</th>\r\n        												<th>Role</th>\r\n        												<th>Actions</th>\r\n        											</tr>\r\n        										</thead>\r\n        										<tbody>\r\n        										<% \r\n        										    no = 1\r\n        										    for i in usr.compact do\r\n        										\r\n        										%>\r\n        										    <tr>\r\n        										        <td><%= no %>.</td>\r\n        										        <td><%= i[:login] %></td>\r\n        										        <td><%= i[:provider_name] %></td>\r\n        										        <td><%= i[:role_name] %></td>\r\n        										        <td>\r\n        										            <%= link_to \'\', \'#\', :title=>\'Delete Account\', :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>&nbsp;&nbsp;&nbsp;\r\n        										            <%= link_to \'\', \'#\', :title=>\'Edit Account\', :class=>\'splashy-contact_blue_edit\', :onclick=>\"javascript:confirm_edit(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>\r\n        										        </td>\r\n        										    </tr>\r\n        										<%\r\n        										    no += 1\r\n        										    end\r\n        										%>\r\n        										</tbody>\r\n        									</table>\r\n										</div>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n<%\r\n    end\r\n%>\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											User Profile\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :profile, :class=>\'\', :url=>\"index\" ,:method=>\'POST\' do |f| %>\r\n											<%\r\n											    cur_user = @ehr_models[:user].where(:login=>@current_user.to_s).first\r\n											    cur_prov = @models[:provider].where(:login=>@current_user.to_s).first\r\n											%>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your information</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\', :value=>@current_user, :disabled=>\'disabled\' %>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\', :value=>cur_user[:name] if cur_user %> \r\n        													<span class=\"help-block\">your account name</span>\r\n        												</div>\r\n        											</div>\r\n        											\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Password\" class=\"span10\" name=\"[profile]cur_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your information</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Password\" class=\"span10\" name=\"[profile]new_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Password\" class=\"span10\" name=\"[profile]con_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n										</div>\r\n									</div>\r\n								</div>\r\n							</div>\r\n                        \r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<br/>\r\n\r\n<script>\r\n    refresh();\r\n    \r\n    function confirm_delete(uid, pid) {\r\n        if (confirm(\'Are you sure?\') == true) {\r\n<%\r\n            destroy_url = \'destroy?id=\'\r\n%>\r\n            \r\n            url = \"destroy?uid=\" + uid + \"&pid=\" + pid;\r\n            window.location = url;\r\n        }\r\n    }\r\n    \r\n    function confirm_edit(uid, pid) {\r\n        // if (alert(\'Are you sure?\') == true) {\r\n            \r\n        // }\r\n        // console.log(\'UID = \' + uid);\r\n        // console.log(\'PID = \' + pid);\r\n        url = \"get_user?uid=\" + uid + \"&pid=\" + pid;\r\n        console.log(\"URL = \" + url);\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prov.prefix + \" | \" + data.user.login + \"...\" + data.user.role);\r\n                $(\'#account_prefix\').val(data.prov.prefix);\r\n                $(\'#account_first_name\').val(data.prov.first_name);\r\n                $(\'#account_last_name\').val(data.prov.last_name);\r\n                $(\'#account_login_name\').val(data.user.login);\r\n                $(\'#account_password\').val(\'\');\r\n                $(\'#account_email\').val(data.user.email);\r\n                $(\'#account_role option[value=\"\' + data.user.role + \'\"]\').prop(\'selected\', true);\r\n                $(\'#provider_type option[value=\"\' + data.prov.provider_type + \'\"]\').prop(\'selected\', true);\r\n                // $(\'#account_role value:eq(\' + data.user.role + \')\').prop(\'selected\', true);\r\n                // $(\'#provider_type value:eq(\' + data.prov.provider_type + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n            } \r\n        });\r\n        \r\n        $(\'#data-add_new\').hide();\r\n        $(\'#data-update\').show();\r\n        $(\'#data-cancel\').show();\r\n        $(\'#account_login_name\').prop(\'readonly\', true);\r\n    }\r\n    \r\n    function cancel() {\r\n        // $(\'#account\').trigger(\"reset\");\r\n        $(\'#data-add_new\').show();\r\n        $(\'#data-update\').hide();\r\n        $(\'#data-cancel\').hide();\r\n        $(\'#account_login_name\').prop(\'readonly\', false);\r\n    }\r\n</script>',NULL,NULL,NULL,'2015-09-07 07:09:46','2015-09-07 07:09:46','index',''),(1800,'init',784,4,'<%\r\n    @models = get_model\r\n        \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @ehr_models = ehr.get_model\r\n%>',NULL,NULL,NULL,'2015-09-07 07:10:12','2015-09-07 07:10:12','init',''),(1801,'index',636,2,'<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% -34px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .collapsed {\r\n        background-position: 98% 12px;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n</style>\r\n    <!-- nice form elements -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/uniform/Aristo/uniform.aristo.css\" />\r\n	<!-- 2col multiselect -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/multiselect/css/multi-select.css\" />\r\n\r\n<%= render :inline=>this.init %>\r\n\r\n<%\r\n    msg = []\r\n    tmp = nil\r\n    suc_msg = nil\r\n    \r\n    if request.post?\r\n        if !params[:account].nil? and !params[:add_new].nil?\r\n\r\n            acc = params[:account]\r\n            \r\n            if acc[:login_name].empty?\r\n                msg.push(\'Invalid login name\')\r\n            end\r\n            # if params[:account][:full_name].empty?\r\n            #     msg.push(\'Invalid full name\')\r\n            # end\r\n            if acc[:password].empty?\r\n                msg.push(\'No password found\')\r\n            end\r\n            \r\n            full_name = acc[:prefix].strip + acc[:first_name].strip + \" \" + acc[:last_name].strip\r\n            full_name = full_name.strip\r\n            if full_name == \'\'\r\n                msg.push(\'Invalid name\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>params[:account][:login_name]).first\r\n                if m_user\r\n                    msg.push(\'Existing login name\')\r\n                else\r\n                    r_provider = @models[:provider].where({\'name\' => Regexp.new( full_name )})\r\n                    create_user = false\r\n                    # a_prov = m_prov.where({\'name\' => Regexp.new(\'\')})\r\n                    if r_provider.count == 0\r\n                        m_provider = @models[:provider].create :group=>\'default\', :name=>full_name, :prefix=>acc[:prefix], :first_name=>acc[:first_name], :last_name=>acc[:last_name], :login=>params[:account][:login_name], :provider_type=>params[:account][:provider_type]\r\n                        create_user = true\r\n                    elsif r_provider.count == 1\r\n                        m_provider = r_provider.first.update_attributes :login=>params[:account][:login_name]\r\n                        create_user = true\r\n                    else\r\n                        name_list = r_provider.collect{|i| i[:name]}\r\n                        msg.push(\"Existing name (\\\\#{name_list.count}) : \" + name_list.join(\', \'))\r\n                    end\r\n                    \r\n                    if create_user \r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(params[:account][:password], salt)\r\n                        tmp = salt + \'...\' + hashed_password\r\n                        m_user = @ehr_models[:user].create :role=>params[:account][:role], :login=>params[:account][:login_name], :salt=>salt, :hashed_password=>hashed_password, :email=>params[:account][:email], :name=>full_name, :activate=>\"true\"\r\n                        tmp = m_user.id.to_s\r\n                        # tmp += \'...\' + m_provider.id.to_s\r\n                    end\r\n                    \r\n                end\r\n            end\r\n        elsif !params[:account].nil? and !params[:update].nil?\r\n            acc = params[:account]\r\n            \r\n            full_name = acc[:prefix].strip + acc[:first_name].strip + \" \" + acc[:last_name].strip\r\n            full_name = full_name.strip\r\n            if full_name == \'\'\r\n                msg.push(\'Invalid name\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>acc[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>acc[:login_name]).first\r\n                \r\n                m_prov[:name] = full_name\r\n                m_prov[:prefix] = acc[:prefix]\r\n                m_prov[:first_name] = acc[:first_name]\r\n                m_prov[:last_name] = acc[:last_name]\r\n                m_prov[:provider_type] = acc[:provider_type]\r\n                m_prov.save\r\n                \r\n                suc_msg= \"<b>Success</b> Account <b>\\\\#{acc[:login_name]}</b> has been updated\".html_safe\r\n                \r\n                if acc[:password].strip != \'\'\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(px[:new_password], salt)\r\n                    m_user[:hashed_password] = hashed_password\r\n                    m_user[:salt] = salt\r\n                    # m_user.save\r\n                    suc_msg= \"<strong>Success</strong> Account <b>\\\\#{acc[:login_name]}</b> profile and password has been updated\".html_safe\r\n                end\r\n                \r\n                m_user[:name] = full_name\r\n                m_user[:email] = acc[:email]\r\n                m_user[:role] = acc[:role]\r\n                m_user.save\r\n            end\r\n            \r\n        elsif !params[:profile].nil?\r\n            px = params[:profile]\r\n            if px[:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if px[:cur_password].empty?\r\n                msg.push(\'No password to confirm your change\')\r\n            else\r\n                if px[:new_password] != px[:con_password]\r\n                    msg.push(\"Your confirm password not match the new password. Try again.\")\r\n                end\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>px[:login_name]).first\r\n                salt = m_user[:salt]\r\n                hashed_password = User.encrypt(px[:cur_password], salt)\r\n                if m_user[:hashed_password] == hashed_password\r\n                    if px[:con_password] == px[:new_password] and px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        suc_msg= \"<strong>Success</strong> Your profile has been change\".html_safe\r\n                    elsif px[:con_password] == px[:new_password] and !px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(px[:new_password], salt)\r\n                        m_user[:hashed_password] = hashed_password\r\n                        m_user[:salt] = salt\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your profile and password has been change\".html_safe\r\n                    else\r\n                        msg.push(\'Your new and confirm password does not match\')\r\n                    end\r\n                    \r\n                else\r\n                    msg.push(\'Your current password does not match\')\r\n                end\r\n                # msg.push(px[:login_name])\r\n            end\r\n        else\r\n            if @current_role == \'developer\'\r\n%>\r\n<pre>\r\n    <%= params.inspect %>\r\n</pre>\r\n<%\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n<%#list.inspect%>\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                <div style=\"border:0px solid\">\r\n<%\r\n    if @current_role == \'developer\'\r\n%>\r\n<%= link_to \'Batch Appointment\', \'batch_register\' %>\r\n<%\r\n    end\r\n%>\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                            <div id=\"accordion1\" class=\"accordion\">\r\n<%\r\n    # check admin or developer role\r\n    a_role = @ehr_models[:role].all\r\n    \r\n    map_role = {}\r\n    map_role[\'\']  = \'Na\'\r\n    map_role[nil] = \'N/A\'\r\n    for a in a_role do\r\n        map_role[a.id.to_s] = a[:name]\r\n    end\r\n    \r\n    a_prov = @models[:provider].where(:disabled=>\'\').all\r\n    map_prov = {} # map each record with id\r\n    map_prov[\'\']  = \'Na\'\r\n    map_prov[nil] = \'N/A\'\r\n    \r\n    map_login = {} # map each login\r\n    map_login[\'\']  = \'Na\'\r\n    map_login[nil] = \'N/A\'\r\n    \r\n    for a in a_prov do\r\n        map_prov[a.id.to_s] = a\r\n        map_login[a[:login]] = a\r\n    end\r\n    \r\n    a_proc = @models[:procedure].all\r\n    map_proc = {} # map procedure\r\n    map_proc[\'\']  = \'Na\'\r\n    map_proc[nil] = \'N/A\'\r\n    \r\n    for a in a_proc do\r\n        map_proc[a.id.to_s] = a.name\r\n    end\r\n    \r\n    if @current_role == \'admin\' or @current_role == \'developer\'\r\n        usr = @ehr_models[:user].all.collect do |i|\r\n            # role = @ehr_models[:role].find(i.role)\r\n            # role_name = \'undefined\'\r\n            # if role\r\n            #     role_name = role[:name]\r\n            # end\r\n            role_name = map_role[i.role.to_s]\r\n            provider = @models[:provider].where(:login=>i.login).first\r\n            \r\n            if provider\r\n                {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :i=>i}\r\n            end\r\n        end\r\n%>\r\n<%\r\n    if !msg.empty?\r\n        for m in msg do\r\n%>\r\n                                <div class=\"alert alert-error\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= m %>\r\n    							</div>\r\n<%\r\n        end\r\n    elsif suc_msg\r\n%>\r\n                                <div class=\"alert alert-success\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= suc_msg %>\r\n    							</div>\r\n<%\r\n    end\r\n%>\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#manage\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Manage Provider, Procedure, Indication\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"manage\">\r\n										<div class=\"accordion-inner\">\r\n										    <ul class=\"dshb_icoNav tac\">\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/agent.png)\" href=\"../Provider/index\">\r\n										                <span class=\"label label-success\"><%= @models[:provider].count %></span> Provider</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/addressbook.png)\" href=\"../Procedure/index\">\r\n										                <span class=\"label label-important\"><%= @models[:procedure].count %></span> Procedure</a></li>\r\n									            <li><a style=\"background-image: url(/gebo/img/gCons/arrow-round.png)\" href=\"../VisitType/index\">\r\n										                <span class=\"label label-info\"><%= @models[:visit_type].count %></span> Visit Type</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/lab.png)\" href=\"../Indication/index\">\r\n										                <span class=\"label label-info\"><%= @models[:indication].count %></span> Indication</a></li>\r\n										        <!--\r\n										        <li><a style=\"font-size:.8em;background-image: url(/esm/thks/thks/content/knee.jpg);background-size: 52px 52px;\" href=\"../KneeComponent/index\">\r\n										                <span class=\"label label-info\"><%# c_kcom > 100 ? \"+100\" : c_kcom.to_s %></span> Knee Component</a></li>\r\n										        <li><a style=\"background-image: url(/esm/thks/thks/content/hip.jpg);background-size: 52px 52px;\" href=\"javascript:void(0)\">\r\n										                <span class=\"label label-info\">0</span> Hip Component</a></li>\r\n										                -->\r\n										    </ul>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n\r\n\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Account Setting\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse <%= \'in\' if @current_role==\'developer\' or @current_role==\'admin\' %>\" id=\"collapseOne1\">\r\n										<div class=\"accordion-inner\">\r\n										    <!--<div id=\"form-panel\" class=\"row-fluid\"><%= link_to \'Add New\', \'add_new?update=form-panel\', :remote=>true, :class=>\'btn\', :style=>\'float:right\' %>-->\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :account, :url=>\"index\", :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Add New Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Name</label>\r\n        												<div class=\"controls\">\r\n        												    <div class=\"row-fluid\">\r\n        												    <%= f.text_field :prefix, :class=>\'span2\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    <%= f.text_field :first_name, :class=>\'span4\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    <%= f.text_field :last_name, :class=>\'span4\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    </div>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block span2\">prefix name</span>\r\n        													<span class=\"help-block span4\">name</span>\r\n        													<span class=\"help-block span4\">surname</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">no space, special characters</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<!--\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%# f.text_field :full_name, :class=>\'span10\' %>\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											-->\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'user\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Provider Type</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[provider_type]\" id=\"provider_type\">\r\n                                                                <option value=\"\"></option>\r\n                                                                <option value=\"1\">Doctor\r\n                                                                </option>\r\n                                                                <option value=\"4\">Fellow Doctor\r\n                                                                </option>\r\n                                                                <option value=\"2\">Nurse\r\n                                                                </option>\r\n                                                                <option value=\"3\">Assistant\r\n                                                                </option>\r\n                                                            </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:id=>\'data-add_new\', :name=>\'add_new\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %> \r\n        													<%=f.submit \'Update\',:id=>\'data-update\', :name=>\'update\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;display:none\' %> \r\n        													<%=link_to \'Cancel\', \'#\', :id=>\'data-cancel\', :class=>\'btn\', :style=>\'display:none\', :onclick=>\"javascript:cancel()\" %>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n											<!--<hr/>-->\r\n                                            <div id=\"account\">\r\n											<table class=\"table\">\r\n        										<thead>\r\n        											<tr>\r\n        												<th>No.</th>\r\n        												<th>Login Name</th>\r\n        												<th>Name</th>\r\n        												<th>Role</th>\r\n        												<th>Actions</th>\r\n        											</tr>\r\n        										</thead>\r\n        										<tbody>\r\n        										<% \r\n        										    no = 1\r\n        										    for i in usr.compact do\r\n        										\r\n        										%>\r\n        										    <tr>\r\n        										        <td><%= no %>.</td>\r\n        										        <td><%= i[:login] %></td>\r\n        										        <td><%= i[:provider_name] %></td>\r\n        										        <td><%= i[:role_name] %></td>\r\n        										        <td>\r\n        										            <%= link_to \'\', \'#\', :title=>\'Delete Account\', :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>&nbsp;&nbsp;&nbsp;\r\n        										            <%= link_to \'\', \'#\', :title=>\'Edit Account\', :class=>\'splashy-contact_blue_edit\', :onclick=>\"javascript:confirm_edit(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>\r\n        										        </td>\r\n        										    </tr>\r\n        										<%\r\n        										    no += 1\r\n        										    end\r\n        										%>\r\n        										</tbody>\r\n        									</table>\r\n										</div>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n<%\r\n    end\r\n%>\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											User Profile\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :profile, :class=>\'\', :url=>\"index\" ,:method=>\'POST\' do |f| %>\r\n											<%\r\n											    cur_user = @ehr_models[:user].where(:login=>@current_user.to_s).first\r\n											    cur_prov = @models[:provider].where(:login=>@current_user.to_s).first\r\n											%>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your information</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\', :value=>@current_user, :disabled=>\'disabled\' %>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\', :value=>cur_user[:name] if cur_user %> \r\n        													<span class=\"help-block\">your account name</span>\r\n        												</div>\r\n        											</div>\r\n        											\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Password\" class=\"span10\" name=\"[profile]cur_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your information</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Password\" class=\"span10\" name=\"[profile]new_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Password\" class=\"span10\" name=\"[profile]con_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n										</div>\r\n									</div>\r\n								</div>\r\n							</div>\r\n                        \r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<br/>\r\n\r\n<script>\r\n    refresh();\r\n    \r\n    function confirm_delete(uid, pid) {\r\n        if (confirm(\'Are you sure?\') == true) {\r\n<%\r\n            destroy_url = \'destroy?id=\'\r\n%>\r\n            \r\n            url = \"destroy?uid=\" + uid + \"&pid=\" + pid;\r\n            window.location = url;\r\n        }\r\n    }\r\n    \r\n    function confirm_edit(uid, pid) {\r\n        // if (alert(\'Are you sure?\') == true) {\r\n            \r\n        // }\r\n        // console.log(\'UID = \' + uid);\r\n        // console.log(\'PID = \' + pid);\r\n        url = \"get_user?uid=\" + uid + \"&pid=\" + pid;\r\n        console.log(\"URL = \" + url);\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prov.prefix + \" | \" + data.user.login + \"...\" + data.user.role);\r\n                $(\'#account_prefix\').val(data.prov.prefix);\r\n                $(\'#account_first_name\').val(data.prov.first_name);\r\n                $(\'#account_last_name\').val(data.prov.last_name);\r\n                $(\'#account_login_name\').val(data.user.login);\r\n                $(\'#account_password\').val(\'\');\r\n                $(\'#account_email\').val(data.user.email);\r\n                $(\'#account_role option[value=\"\' + data.user.role + \'\"]\').prop(\'selected\', true);\r\n                $(\'#provider_type option[value=\"\' + data.prov.provider_type + \'\"]\').prop(\'selected\', true);\r\n                // $(\'#account_role value:eq(\' + data.user.role + \')\').prop(\'selected\', true);\r\n                // $(\'#provider_type value:eq(\' + data.prov.provider_type + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n            } \r\n        });\r\n        \r\n        $(\'#data-add_new\').hide();\r\n        $(\'#data-update\').show();\r\n        $(\'#data-cancel\').show();\r\n        $(\'#account_login_name\').prop(\'readonly\', true);\r\n    }\r\n    \r\n    function cancel() {\r\n        // $(\'#account\').trigger(\"reset\");\r\n        $(\'#data-add_new\').show();\r\n        $(\'#data-update\').hide();\r\n        $(\'#data-cancel\').hide();\r\n        $(\'#account_login_name\').prop(\'readonly\', false);\r\n    }\r\n</script>',NULL,NULL,NULL,'2015-09-07 07:13:38','2015-09-07 07:13:38','index',''),(1802,'context_menu',221,4,'',NULL,NULL,NULL,'2015-09-09 04:00:17','2015-09-09 04:00:17','context_menu',''),(1803,'weekly_report',522,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Weekly Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # params_date = select_date\r\n    # select_date = Date.to_mongo(select_date)\r\n    \r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date , :order=>[:day,:month,:year]%>\r\n\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    # start_date = select_date.beginning_of_month()\r\n    # stop_date = select_date.end_of_month()\r\n    \r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                p_colo = nil\r\n                p_gastro = nil\r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                        status = r_colo[0][\'status\']\r\n                        p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    if r_gastro\r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                \r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                \r\n                if p_colo\r\n                dates[date][\'p_colo\'] = {} unless dates[date][\'p_colo\']\r\n                for pi in p_colo.split(\"|\")\r\n                    dates[date][\'p_colo\'][pi] = 0 unless  dates[date][\'p_colo\'][pi]\r\n                    dates[date][\'p_colo\'][pi] += 1 \r\n                end\r\n                \r\n                end\r\n                if p_gastro\r\n                \r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                for pi in p_gastro.split(\"|\")\r\n                dates[date][\'p_gastro\'][pi] = 0 unless  dates[date][\'p_gastro\'][pi]\r\n                dates[date][\'p_gastro\'][pi] += 1 \r\n                end\r\n                end\r\n                \r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        end\r\n    \r\n    end\r\n    \r\n    %>\r\n    <%#dates.inspect  %>\r\n    <%\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<% \r\nmonth_text=\'\'\r\n    # month_text = month_th[select_date.month-1]+select_date.strftime(\"-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    \r\n    td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.small{\r\n        font-size:0.8em;\r\n    }\r\n    td.date{\r\n        padding:0px;\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n        td.date{\r\n        padding:0px;\r\n        \r\n        width:125px;\r\n        \r\n    }\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n    \r\n    tr.page-break{page-break-after:always;page-break-inside:avoid; page-break-after:auto}\r\n    .force-break{ display: block;page-break-before:always;}\r\n        \r\n    }\r\n    \r\n\r\n    \r\n   table { page-break-inside:auto }\r\n   tr    { page-break-inside:avoid; page-break-after:auto }\r\n    \r\n</style>\r\n<style type=\"text/css\">\r\n\r\n</style>\r\n\r\n<div style=\"width:720px\">\r\n<h3>รายงานจำนวนผู้เข้ารับบริการ ห้องส่องกล้อง Surgical Endoscopy โรงพยาบาลจุฬาลงกรณ์ ประจำเดือน  \r\n<%=month_text%></h3>\r\n</div>\r\n\r\n<br/>\r\n<table border=\"1\" class=\"content\">\r\n<%\r\n   m = nil\r\n   \r\n   \r\n       tsum = {\'Elective\'=>[0,0,0,0],\'Extratime\'=>[0,0,0,0], \'Emergency\'=>[0,0,0,0], \'Total\'=>[0,0,0,0]}\r\n%>\r\n\r\n<%\r\n     pc_map = {}\r\n     pg_map = {}\r\n     \r\n     days = stop_date.day\r\n     \r\n    dates.each_pair do |k,v|\r\n        if v[\'p_colo\']    \r\n         v[\'p_colo\'].each_pair do |p,count|\r\n            pc_map[p] = 0 unless pc_map[p]\r\n            pc_map[p] += count\r\n         end\r\n        end\r\n        \r\n        if v[\'p_gastro\'] \r\n         v[\'p_gastro\'].each_pair do |p,count|\r\n            pg_map[p] = 0 unless pg_map[p]\r\n            pg_map[p] += count\r\n         end\r\n        end\r\n     \r\n    end\r\n     \r\n     \r\n\r\n%>\r\n\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td >&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n    <td colspan=\"<%=pc_map.keys.size%>\" align=\"center\" class=\"total tx\">Colonoscopy Procedure</td>\r\n    <td colspan=\"<%=pg_map.keys.size%>\" align=\"center\" class=\"total tx\">Gastroscopy Procedure</td>\r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"  class=\"page-break\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n</tr>\r\n\r\n<%\r\n\r\n  \r\n\r\n        count = 0 \r\n   \r\n   days.times do |date|\r\n  \r\n   date = (start_date+(date*3600*24))\r\n   i = date.strftime(\"%Y-%m-%d\")\r\n   \r\n#   for i in dates.keys.sort\r\n    weekend = \'\'\r\n    weekend = \'weekend\' if date.wday==0 or date.wday==6\r\n\r\n    \r\n    \r\n    if dates[i]\r\n\r\n%>\r\n\r\n\r\n<tr class=\"page-break\">\r\n    <td class=\"date <%=weekend%>\" ><%=i.split(\'-\').reverse.join(\'-\')%> </td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Emergency Extratime} \r\n        \r\n        k = [0,0,0]\r\n        k = dates[i][j] if dates[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        \r\n        tsum[j][0] += k[0]\r\n        tsum[j][1] += k[1]\r\n        tsum[j][2] += k[2]\r\n        tsum[j][3] += s\r\n        \r\n        \r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        s = \'.\' if s == 0 \r\n        \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n    \r\n    \r\n    \r\n    <% for pi in pc_map.keys.sort \r\n  \r\n    c = dates[i][\'p_colo\'][pi] if dates[i][\'p_colo\']\r\n    c = \'-\' unless c\r\n    %>\r\n    <td class=\"total\"><%= c %></td>\r\n    <% end %>\r\n    \r\n    <% for pi in pg_map.keys.sort \r\n        g = dates[i][\'p_gastro\'][pi] if dates[i][\'p_gastro\']\r\n        g = \'-\' unless g\r\n    \r\n    %>\r\n    <td class=\"total\"><%=g %></td>\r\n    <% end %>\r\n    \r\n    \r\n\r\n</tr> \r\n<% else %>\r\n<tr class=\"page-break\">\r\n    <td class=\"date  <%=weekend%>\"><%=i.split(\'-\').reverse.join(\'-\')%></td>\r\n    <td colspan=\"<%=16+pc_map.keys.size+pg_map.keys.size%>\">\r\n        &nbsp;\r\n        \r\n    </td>\r\n</tr>\r\n<% end %>\r\n<% if count%40==0 and count!=0%>\r\n\r\n</table>\r\n<table border=\"1\" class=\"content force-break\">\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td style=\"width:120px\">&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n    <td colspan=\"<%=pc_map.keys.size%>\" align=\"center\" class=\"total tx\">Colonoscopy Procedure</td>\r\n    <td colspan=\"<%=pg_map.keys.size%>\" align=\"center\" class=\"total tx\">Gastroscopy Procedure</td>\r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"  class=\"page-break\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% \r\ncount+=1\r\n\r\nend %>\r\n\r\n<tr class=\"page-break\"><td>Total</td>\r\n<%\r\n\r\n   t = [0,0,0,0]\r\n\r\n  for j in %w{Elective Extratime Emergency} \r\n    \r\n  4.times do |i|    \r\n  t[i]+=tsum[j][i]\r\n%>\r\n<td class=\"total2\"><%=tsum[j][i]%></td>\r\n<% end %> \r\n<% end %> \r\n\r\n<td class=\"total2\"><%=t[0]%></td><td class=\"total2\"><%=t[1]%></td><td class=\"total2\"><%=t[2]%></td><td class=\"total2\"><%=t[3]%></td>\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total2\"><%=pc_map[pi] %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total2\"><%=pg_map[pi] %></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n<br/>\r\n<h4>รวมจำนวนผู้เข้ารับบริการ</h4>\r\n<br/><table>\r\n    <tr>\r\n        <td colspan=\"2\"></td><td>Elective</td><td>Emergency</td><td>Extratime</td>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">Colonoscopy</td><td  align=\"right\"><%= t[0] %> ราย</td>\r\n        \r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]%> </td>\r\n        <%  end %>\r\n        \r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">Gastroscopy</td><td  align=\"right\"><%= t[1] %> ราย </td>\r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][1]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">Gastroscopy & Colonoscopy</td><td  align=\"right\"><%= t[2] %> ราย </td>\r\n           <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">รวม</td><td  align=\"right\"><%= t[0]+t[1]+t[2] %> ราย </td>\r\n          <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]+tsum[j][1]+tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    \r\n</table>\r\n\r\n</div>\r\n<br/>\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-09-09 08:37:32','2015-09-09 08:37:32','weekly_report',''),(1804,'form',262,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    function update_name() {\r\n        pn = $(\'#data-prefix\').val();\r\n        fn = $(\'#data-first_name\').val();\r\n        ln = $(\'#data-last_name\').val();\r\n        \r\n        $(\'#data-name\').val(pn + fn + \" \" + ln);\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#data-name\').prop(\'readonly\', true);\r\n        \r\n        $(\'#data-prefix\').change(update_name);\r\n        $(\'#data-first_name\').change(update_name);\r\n        $(\'#data-last_name\').change(update_name);\r\n    });\r\n</script>',NULL,NULL,NULL,'2015-09-11 04:03:49','2015-09-11 04:03:49','',''),(1805,'list',262,3,'<%\r\n   model = get_model(this.table_name)\r\n   records = []\r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   \r\n    if params[:search]\r\n        records = model.all(params[:search][:criteria])\r\n    else\r\n        # rs = model.where(:status=>\'\')\r\n        rs = model\r\n        n = rs.count\r\n        rows,offset,page = params[:paginate]\r\n        records = rs.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n    end\r\n   \r\n%>\r\n\r\n<%= tabular :model=>labels, :data=>records do |i,out|\r\n\r\nfields.each_with_index do |f,index|\r\n\r\nout[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n\r\nend\r\nout<<link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nout<<link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\')\r\nout<<link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:confirm=>\'Are you sure?\')\r\nout\r\nend\r\n%>\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2015-09-11 04:12:47','2015-09-11 04:12:47','list',''),(1806,'destroy',262,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  @record.update_attributes :status=>\'0\', :provider_type=>\'-1\'\r\n#   @record.destroy \r\n\r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=index\">',NULL,NULL,NULL,'2015-09-11 04:13:44','2015-09-11 04:13:44','destroy',''),(1807,'print',530,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:ercp].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>ERCP</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v><%=record.date_note%></v>&nbsp;&nbsp; Colonoscope by :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n    <% if a= record[\'date_note\'] and a !=\"\" %>\r\n    <div id=\"date_note\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n<label>Date note: </label>\r\n<v><%=render_value \'date_note\'%> </v>\r\n<% end%>\r\n\r\n</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n	<div id=\"319-F6303882687\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"status\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>Status : </label></span>	\r\n\r\n</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"previous_opreation\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>Previous operation : </label></span>	\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>Indication : </label></span>	\r\n\r\n</div>\r\n\r\n	\r\n\r\n\r\n	<div id=\"319-F4399020731\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"record\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>Record : </label></span>	\r\n\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n	<div id=\"319-F0972779869\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n	<div id=\"319-F2842321799\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Sedative</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'dormicum\'] and a !=\"\" %>\r\n<div id=\"dormicum\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:100px;min-height:30px;\">\r\nDormicum\r\n\r\n</div>\r\n<% end %>\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'dormicum_mg\'] and a !=\"\" %>\r\n<div id=\"dormicum_mg\" class=\" dormicum portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n<%=render_value \'dormicum_mg\'%>\r\n</div>\r\n<%end%>\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'dormicum_num\'] and a !=\"\" %>\r\n<div id=\"dormicum_num\" class=\" dormicum portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n	\r\n\r\n<%=render_value \'dormicum_num\'%>\r\n	\r\n\r\n</div>\r\n\r\n<% end %>\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'diprivan\'] and a !=nil %>\r\n<div id=\"diprivan\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:100px;min-height:30px;\">\r\nDiprivan\r\n\r\n</div>\r\n<% end %>\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'diprivan_mg\'] and a !