        </div>',NULL,NULL,NULL,'2015-09-14 16:43:47','2015-09-14 16:43:47','manage',''),(1809,'get_user',777,3,'<%= render :inline=>this.init %>\r\n<%\r\n    \r\n\r\n    res = {}\r\n    res[:user] = @ehr_models[:user].find(params[:uid])\r\n    res[:prov] = @models[:provider].find(params[:pid])\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-09-14 17:36:35','2015-09-14 17:36:35','get_user',''),(1812,'init',786,4,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @m_ehr = ehr.load_model\r\n    @m_pat = @m_ehr[:patient]\r\n    @m_pat_mod = @m_ehr[:patient_module]\r\n\r\n    @models = get_model\r\n    \r\n    @provider = {}\r\n    @provider[\'\'] = \'Na\'\r\n    @provider[nil] = \'N/A\'\r\n    \r\n    a_prov = @models[:provider].all\r\n    a_prov.each do |i|\r\n        @provider[i.id.to_s] = i[:name]\r\n    end\r\n%>',NULL,NULL,NULL,'2015-09-16 14:27:06','2015-09-16 14:27:06','init',''),(1813,'index_old',786,2,'<%= render :inline=>this.init %>\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Report</h3>\r\n                <div style=\'float:right\'><%= link_to \'Case Reports\', \'case_reports\', :class=>\'btn btn-mini\' %></div>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n                <div style=\"border:0px solid;margin:0px;\">\r\n                <%= params.inspect %>\r\n                    <!--<div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">-->\r\n                        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         \r\n                            <div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n                                <%=form_for :query, :url=>\'query?update=result\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n            \r\n           \r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">Start Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :sdate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'start-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">End Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :edate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'end-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <div class=\"clear\"></div>\r\n                                <div class=\"field-input\">\r\n                                    <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                                     \r\n                                    <%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>\r\n                                </div>\r\n                                <div class=\"clear\"></div>\r\n                                <%=f.hidden_field :view, :value=>\'html\' %>\r\n                                <%=f.hidden_field :mode, :value=>\'procedure\' %>\r\n                                <% end %>\r\n                            </div>\r\n        \r\n                        </div>\r\n<script>\r\n    $(\"#start-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n	$(\"#end-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n</script>\r\n\r\n                        <div class=\"row-fluid\" style=\"margin-top:10px\"></div>\r\n                        <div class=\"row-fluid\" style=\"padding:5px\">\r\n                            <div id=\'result\'></div>\r\n                            <pre>\r\n<%= @current_project.to_json.html_safe %>\r\n                        </pre>\r\n                        </div>\r\n                        \r\n                    <!--</div>-->\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<script>\r\n    refresh();\r\n</script>',NULL,NULL,NULL,'2015-09-16 14:27:50','2015-09-16 14:27:50','index_old',''),(1814,'query',786,3,'<%= render :inline=>this.init %>\r\n<%\r\n    today = Time.now\r\n    s_date = today.beginning_of_day\r\n    e_date = today.end_of_day\r\n    view = \'json\'\r\n    mode = \'procedure\'\r\n    type = \'daily\'\r\n    \r\n    pp = params[:query]\r\n    if !pp.nil?\r\n        s_date = Time.strptime(pp[:sdate], \"%d/%m/%Y\")\r\n        e_date = Time.strptime(pp[:edate], \"%d/%m/%Y\")\r\n        view = pp[:view]\r\n        mode = pp[:mode]\r\n    end\r\n    \r\n    mn = @current_project.name.to_s + \'#\'\r\n    rs = []\r\n    # if mode == \'procedure\'\r\n        a_app = @models[:appointment].where({:date=>{\'$gte\'=>s_date,\'$lt\'=>e_date}}).all\r\n        app_ids = a_app.collect{|i| i.id.to_s}\r\n        \r\n        a_pat_mod = @m_pat_mod.where(:module_id=>app_ids).all\r\n        pat_mod_ids = a_pat_mod.collect{|i| i.id.to_s}\r\n        \r\n        \r\n        p_pat_mod = @m_pat_mod.where(:parent_id=>pat_mod_ids).all\r\n        map_parent = {}\r\n        map_proc = {}\r\n        p_pat_mod.each do |i|\r\n            md = i[:module_name].to_s\r\n            if !map_proc.has_key? md\r\n                map_proc[md] = []\r\n            end\r\n            map_proc[md] << i[:module_id]\r\n            \r\n            parent = i[:parent_id].to_s\r\n            if !map_parent.has_key? parent\r\n                map_parent[parent] = {}\r\n            end\r\n            map_parent[parent][md] = i[:module_id]\r\n            map_parent[parent][:patient_id] = i[:patient_id]\r\n        end\r\n        \r\n        map_rs = {}\r\n        map_proc.each do |k, v|\r\n            m = k.split(\'#\')[1].to_sym\r\n            a_m = @models[m].where(:id=>v).all\r\n            map_tmp = {}\r\n            map_tmp[nil] = \'N/A\'\r\n            \r\n            a_m.each do |i|\r\n                map_tmp[i.id.to_s] = i\r\n            end\r\n            map_rs[k] = map_tmp\r\n        end\r\n        # a_app = @models[:appointment].all\r\n    # end\r\n    \r\n    res = {}\r\n    res[:query] = pp\r\n    res[:mname] = mn\r\n    res[:result] = rs\r\n    res[:appointment] = a_app.count if a_app\r\n    res[:app_ids] = app_ids.count if app_ids\r\n    res[:a_pat_mod] = a_pat_mod.count if a_pat_mod\r\n    res[:pat_mod_ids] = pat_mod_ids.count if pat_mod_ids\r\n    res[:map_parent] = map_parent.count\r\n    res[:map_rs] = map_rs\r\n    # res[:provider] = @provider\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-09-16 14:45:09','2015-09-16 14:45:09','query',''),(1815,'Help',622,2,'sadads',NULL,NULL,NULL,'2015-09-17 07:45:23','2015-09-17 07:45:23','help',''),(1816,'index',787,2,'<style>\r\n.accordion-heading {\r\n        border: 1px solid #ddd;\r\n    padding: 0 10px;\r\n    background: #fbfbfb;\r\n    background: -moz-linear-gradient(top, #fbfbfb 0%, #f1f1f1 100%);\r\n    background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#fbfbfb), color-stop(100%,#f1f1f1));\r\n    background: -webkit-linear-gradient(top, #fbfbfb 0%,#f1f1f1 100%);\r\n    background: -o-linear-gradient(top, #fbfbfb 0%,#f1f1f1 100%);\r\n    background: -ms-linear-gradient(top, #fbfbfb 0%,#f1f1f1 100%);\r\n    background: linear-gradient(top, #fbfbfb 0%,#f1f1f1 100%);\r\n    filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#fbfbfb\', endColorstr=\'#f1f1f1\',GradientType=0 );\r\n}\r\n</style>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>คู่มือการใช้งาน ระบบ LifeScope </h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                    \r\n                    \r\n                    \r\n                    <div class=\"row-fluid\">\r\n                    <div class=\"span12\">\r\n							<h3 class=\"heading\">คู่มือการใช้งานระบบ</h3>\r\n							<div id=\"accordion1\" class=\"accordion\">\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											ขั้นตอนติดตั้งระบบ สำหรับ Admin\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"collapseOne1\" style=\"height: 0px;\">\r\n										<div class=\"accordion-inner\"><center>\r\n										1. กดที่ปุ่ม \"Setting\" <br />\r\n										<img src=\"/esm/lifescope_master/endo/img/1.JPG\" width=\"500\"> <br /> <br />\r\n										 1.1. เลือก \"Provider\" > เพิ่มชื่อแพทย์ในระบบ<br />\r\n										 <img src=\"/esm/lifescope_master/endo/img/2.JPG\" width=\"500\"> <br />\r\n										 <img src=\"/esm/lifescope_master/endo/img/3.JPG\" width=\"500\"> <br /> <br />\r\n										 1.2. เลือก \"Procedure\" > เพื่อเพิ่ม การทำงาน<br />\r\n										 <img src=\"/esm/lifescope_master/endo/img/4.JPG\" width=\"500\"> <br />\r\n										 <img src=\"/esm/lifescope_master/endo/img/5.JPG\" width=\"500\"> <br />\r\n										</center>\r\n										</div>\r\n									</div>\r\n								</div>\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											การตั้งค่าระบบทั่วไป\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\"><center>\r\n									สามารถแก้ไขชื่อ และ password ของตัวเองได้<br />\r\n											<img src=\"/esm/lifescope_master/endo/img/6.JPG\" width=\"500\"> <br />\r\n										 <img src=\"/esm/lifescope_master/endo/img/7.JPG\" width=\"500\"> <br />\r\n\r\n										    </center>\r\n										</div>\r\n									</div>\r\n								</div>\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseThree1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											การลงข้อมูลกาารตรวจ\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"collapseThree1\">\r\n										<div class=\"accordion-inner\"><center>\r\n										ค้นหาคนไข้จากฐานข้อมูลที่มีอยู่<br />\r\n										    	<img src=\"/esm/lifescope_master/endo/img/8.JPG\" width=\"500\"> <br />\r\n										 <img src=\"/esm/lifescope_master/endo/img/9.JPG\" width=\"500\"> <br /><br />\r\n										 เลือกแพทย์เจ้าของคนไข้ และเลือกว่าจะมาทำ Procedure อะไร <br />\r\n										 	<img src=\"/esm/lifescope_master/endo/img/10.JPG\" width=\"500\"> <br /><br />\r\n										 	เลือก คนไข้ที่ต้องการลงข้อมูล<br />\r\n										 <img src=\"/esm/lifescope_master/endo/img/14.JPG\" width=\"500\"> <br />	\r\n										 <br />\r\n										 สามารถดูประวัติย้อนหลังของคนไข้ได้จากหน้านี้ และสามารถเลือกลงข้อมูล ตามแบบฟอร์ม Procedure\r\n										 <br />\r\n										 <img src=\"/esm/lifescope_master/endo/img/11.JPG\" width=\"500\"> <br />\r\n										 \r\n										 <br />\r\n										 หลังจากลงข้อมูลเสร็จแล้วให้กดปุ่ม สีเขียวเพื่อทำการ Save<br />\r\n										 \r\n										 	<img src=\"/esm/lifescope_master/endo/img/12.JPG\" width=\"500\"> <br />\r\n										\r\n										    </center>\r\n										</div>\r\n									</div>\r\n								</div>\r\n									<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapse4\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											การออกรายงาน\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"collapse4\">\r\n										<div class=\"accordion-inner\"><center>\r\n										หลังจากลงข้อมูลเรียบร้อยแล้วสามารถออกรายงาน โดยการ Print เพื่อเก็บในแฟ้มคนไข้\r\n										 <img src=\"/esm/lifescope_master/endo/img/13.JPG\" width=\"500\"> <br />\r\n											</center>\r\n											    \r\n											    \r\n											</div>\r\n									</div>\r\n							\r\n								</div>\r\n								<br/><center>	ติดต่อสอบถามการใช้งานระบบ โทร.081-660-8663 , 085-929-7925</center>\r\n							</div>\r\n				</div></div>\r\n                    \r\n                    \r\n                        \r\n                    </div>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</div>\r\n',NULL,NULL,NULL,'2015-09-17 07:46:34','2015-09-17 07:46:34','index',''),(1817,'print_appointment',622,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n provider = providers[ap.provider.to_s]\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year} ปี \\\\#{month} เดือน \\\\#{day} วัน\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>pro[ap.procedure],\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider.name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'age\'=>age,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\nlist = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงรายการผู้ป่วย\r\n<span style=\"float:right\">ประจำวันที่ \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th>Type</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>HN</th>\r\n    <th >อายุ</th>\r\n    <th>เลขประชาชน</th>\r\n    <th>Indication</th>\r\n    <th>Procedure</th>\r\n    <th>Provider</th>\r\n    <th>Tel.</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n  <% list.each_with_index do |i,index|  %>\r\n    <tr style=\"height:110px\">\r\n    <td><%=index+1%>.</td>\r\n    <td><%=i[\'visit_type\']%></td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%></td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'age\']%></td>\r\n    <td><%=i[\'public_id\']%></td>\r\n    <td><%=i[\'indication\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    <td><%=i[\'provider\']%></td>\r\n    <td><%=i[\'tel\']%></td>\r\n    </tr>\r\n    <% end %>\r\n</tbody>\r\n  </table><br/>\r\n  </div>\r\n  </div></div></div></div></div>\r\n</body>\r\n</html>\r\n<% end %>\r\n',NULL,NULL,NULL,'2015-09-17 08:10:31','2015-09-17 08:10:31','print_appointment',''),(1818,'get_user',784,3,'<%= render :inline=>this.init %>\r\n<%\r\n    \r\n\r\n    res = {}\r\n    res[:user] = @ehr_models[:user].find(params[:uid])\r\n    res[:prov] = @models[:provider].find(params[:pid])\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-09-17 17:12:12','2015-09-17 17:12:12','get_user',''),(1819,'test',636,3,'<%\r\n    def get_map arr\r\n        res = {}\r\n        arr.each do |i|\r\n            res[i.id.to_s] = i\r\n        end\r\n        return res\r\n    end\r\n    def get_option_select arr, field\r\n        res = []\r\n        arr.each do |i|\r\n            res << [i[field], i.id.to_s]\r\n        end\r\n        return res\r\n    end\r\n    \r\n    @models = get_model\r\n        \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @ehr_models = ehr.get_model\r\n    @m_app = @models[:appointment]\r\n    @m_pat = @ehr_models[:patient]\r\n    @m_pat_mod = @ehr_models[:patient_module]\r\n    \r\n    @map_prov = get_map @models[:provider].all\r\n    @sel_prov = get_option_select @models[:provider].where(:provider_type=>\'1\').all, :name\r\n    @sel_proc = get_option_select @models[:procedure].all, :name\r\n    @sel_visit = get_option_select @models[:visit_type].all, :name\r\n    @sel_ind = get_option_select @models[:indication].all, :name\r\n    \r\n    res = []\r\n    \r\n    f_pat = [\'hn\', \'public_id\', \'prefix_name\', \'first_name\', \'last_name\', \'gender\', \'birth_date\', \'note\']\r\n    f_app = [\'date\', \'start\', \'end\']\r\n    if request.post?\r\n        require \'csv\'\r\n        \r\n        csv = CSV.parse(params[:import][:file].read, :headers => true)\r\n        \r\n        csv.each do |i|\r\n                ad = i[\'date\'].split(\'/\')\r\n                ad[2] = (ad[2].to_i - 543).to_s\r\n                # i[\'date\'] = \'xxx\'\r\n                i[\'date\'] = Time.strptime(ad.join(\'/\'), \'%d/%m/%Y\')\r\n                # i[\'date\'] = ad[2] + \'-\' + ad[1] + \'-\' + ad[0]\r\n                i[\'start\'] = Time.parse(i[\'start\'], i[\'date\'])\r\n                i[\'end\'] = Time.parse(i[\'end\'], i[\'date\'])\r\n                \r\n                note = nil\r\n                if i[\'birth_date\'].nil?\r\n                    i[\'birth_date\'] = 55\r\n                    note = \'uncorrect-age\'\r\n                end\r\n                \r\n                    if i[\'birth_date\'].to_s.length <= 2\r\n                        cur_year = Time.now.year\r\n                        dif_year = cur_year - i[\'birth_date\'].to_i\r\n                        i[\'birth_date\'] = \"01/01/\" + dif_year.to_s\r\n                    elsif i[\'birth_date\'].split(\'/\')[2].to_i > Time.now.year\r\n                        dob = i[\'birth_date\'].split(\'/\')\r\n                        yyyy = dob[2].to_i - 543\r\n                        i[\'birth_date\'] = dob.join(\'/\')\r\n                    end\r\n                \r\n                pat = {}\r\n                f_pat.each do |j|\r\n                    pat[j] = i[j]\r\n                end\r\n                \r\n                app = {}\r\n                f_app.each do |j|\r\n                    app[j] = i[j]\r\n                end\r\n                b = params[:import]\r\n                app[\'provider\'] = b[:provider]\r\n                app[\'procedure\'] = b[:procedure]\r\n                app[\'visit_type\'] = b[:visit_type]\r\n                app[\'indication\'] = b[:indication]\r\n                app[\'status\'] = \'Appointed\'\r\n                app[\'note\'] = i[\'note\']\r\n                if note and i[\'note\']\r\n                    app[\'note\'] = \"\\\\#{i[\'note\']}/\\\\#{note}\"\r\n                    i[\'note\'] = app[\'note\']\r\n                else\r\n                    app[\'note\'] = note\r\n                    i[\'note\'] = note\r\n                end\r\n                \r\n                r_app = @m_app.create app\r\n                r_pat = @m_pat.create pat\r\n                r_pat_mod = @m_pat_mod.create :ref_number=>\'0000\', :patient_id=>r_pat.id, :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>r_app.id, :date=>i[\'date\'], :time=>i[\'start\']\r\n                \r\n                res << [r_pat,r_app,r_pat_mod]\r\n                # res << [i[\'hn\'], i[\'start\']]\r\n            \r\n            # res << i[\'hn\']\r\n        end\r\n    end\r\n%>\r\n<%= form_for :import,:url=>params[:opt],:html=>{:multipart=>true} do |f| %>\r\nFile : <%= f.file_field :file %>\r\n<p>\r\n    <%= f.select :provider, options_for_select(@sel_prov, {}), :include_blank=>true %> \r\n                <%= f.select :procedure, options_for_select(@sel_proc, {}), :include_blank=>true %> \r\n                <%= f.select :visit_type, options_for_select(@sel_visit, {}), :include_blank=>true %> \r\n                <%= f.select :indication, options_for_select(@sel_ind, {}), :include_blank=>true %> \r\n</p>\r\n<%= f.submit \'Import\' ,:confirm=>\'Are you sure?\'%>\r\n<% end %>\r\n<hr/>\r\n<% if !res.empty? %>\r\n<%= res.join(\'<br/>\').html_safe %><br/>\r\n<%= csv.headers %>\r\n<% end %>',NULL,NULL,NULL,'2015-09-17 17:27:09','2015-09-17 17:27:09','test',''),(1820,'document_name',788,1,'\'company_component\'',NULL,NULL,NULL,'2015-09-22 17:49:23','2015-09-22 17:49:23',NULL,NULL),(1821,'barcode',788,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n    <title>HTML Code39 Barcode</title>\r\n    <!--<script type=\"text/javascript\" src=\"/esm/cusys/thks/content/js/connectcode-javascript-code39ascii.js\"></script>-->\r\n    <%= javascript_include_tag \"application\"  %>\r\n    <script type=\"text/javascript\" src=\"/esm/cusys/thks/content/js/jquery-barcode.min.js\"></script>\r\n    <style type=\"text/css\">\r\n  	#barcode {font-weight: normal; font-style: normal; line-height:normal; sans-serif; font-size: 12pt}\r\n    </style>\r\n<script type=\"text/javascript\">\r\n\r\n    function generateBarcodeValue(id, val){\r\n        var value = val;\r\n        var btype = \'code39\';\r\n        var renderer = \'css\';\r\n        \r\n		var quietZone = false;\r\n        if ($(\"#quietzone\").is(\':checked\') || $(\"#quietzone\").attr(\'checked\')){\r\n          quietZone = true;\r\n        }\r\n		\r\n        var settings = {\r\n          output:renderer,\r\n          bgColor: \'#FFFFFF\',\r\n          color: \'#000000\',\r\n          barWidth: \'1\',\r\n          barHeight: \'50\',\r\n          moduleSize: \'5\',\r\n          posX: \'10\',\r\n          posY: \'20\',\r\n          addQuietZone: \'1\'\r\n        };\r\n        // if ($(\"#rectangular\").is(\':checked\') || $(\"#rectangular\").attr(\'checked\')){\r\n          value = {code:value, rect: true};\r\n        // }\r\n        // if (renderer == \'canvas\'){\r\n        //   clearCanvas();\r\n        //   $(\"#barcodeTarget\").hide();\r\n        //   $(\"#canvasTarget\").show().barcode(value, btype, settings);\r\n        // } else {\r\n        //   $(\"#canvasTarget\").hide();\r\n        //   $(\"#barcodeTarget\").html(\"\").show().barcode(value, btype, settings);\r\n        // }\r\n        $(\"#\" + id).html(\"\").show().barcode(value, btype, settings);\r\n      }\r\n      \r\n    </script>\r\n</head>\r\n<body>\r\n\r\n    <div id=\"barcodeTarget\" class=\"barcodeTarget\"></div>\r\n    <script>\r\n        generateBarcodeValue(\'barcodeTarget\', \'010101011.5\');\r\n    </script>\r\n    <hr/>\r\n<%\r\n    m = get_model[:knee_component]\r\n    m.all.each do |i|\r\n%>\r\n<div style=\"display:block\">\r\n<div id=\"<%= i.id.to_s %>\"></div>\r\n</div>\r\n<br/>\r\n<script>\r\n    generateBarcodeValue(\'<%=i.id.to_s%>\', \'<%=i.id.to_s%>\');\r\n</script>\r\n<% end %>\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2015-09-22 17:56:07','2015-09-22 17:56:07','barcode',''),(1822,'query',788,3,'<%\r\n    res = nil\r\n    if params[:id]\r\n        bca = params[:id]\r\n        \r\n        cid = bca[0..1]\r\n        tid = bca[2]\r\n        ccd = bca[3..4]\r\n        mid = bca[5..6]\r\n        size = bca[7..bca.size]\r\n        \r\n        res = get_model[this.table_name.to_sym].where(:company=>cid, :type=>tid, :component_type=>ccd, :model=>mid, :size=>size).all\r\n    end\r\n    \r\n    doc = get_document(this.document_name)\r\n    @document = doc\r\n    \r\n    if res and res.count != 0\r\n%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n    <title>HTML Code39 Barcode</title>\r\n    <!--<script type=\"text/javascript\" src=\"/esm/cusys/thks/content/js/connectcode-javascript-code39ascii.js\"></script>-->\r\n    <%= 