ue};\r\n        // }\r\n        // if (renderer == \'canvas\'){\r\n        //   clearCanvas();\r\n        //   $(\"#barcodeTarget\").hide();\r\n        //   $(\"#canvasTarget\").show().barcode(value, btype, settings);\r\n        // } else {\r\n        //   $(\"#canvasTarget\").hide();\r\n        //   $(\"#barcodeTarget\").html(\"\").show().barcode(value, btype, settings);\r\n        // }\r\n        $(\"#\" + id).html(\"\").show().barcode(value, btype, settings);\r\n      }\r\n      \r\n    </script>\r\n</head>\r\n<body>\r\n\r\n<%\r\n    res.each do |i|\r\n        @record = i\r\n%>\r\n<div style=\"display:block\">\r\n<div id=\"<%= i.id.to_s %>\"></div>\r\n<b>Company :</b> <v><%= render_value(\'company\') %></v><br/>\r\n<b>Type : </b> <v><%= render_value(\'type\') %></v><br/>\r\n<b>Component : </b> <v><%= render_value(\'component_type\') %></v><br/>\r\n<b>Model : </b> <v><%= render_value(\'model\') %></v><br/>\r\n<b>Name : </b> <v><%= i[:name] %></v><br/>\r\n<b>Size : </b> <v><%= i[:size] %></v>\r\n</div>\r\n<br/>\r\n<script>\r\n    generateBarcodeValue(\'<%=i.id.to_s%>\', \'<%=params[:id]%>\');\r\n</script>\r\n<% end %>\r\n</body>\r\n</html>\r\n<% else %>\r\nNo id found\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2015-09-22 18:41:13','2015-09-22 18:41:13','query','*'),(1823,'show',788,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%\r\n    rec = get_model[t