x\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<a href=\"nurse_index?date=<%= params[:date] %>\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-heart\"></i><br />Nurse Index</button></a>\r\n\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting arrived preparing processing recovery completed discharge cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         if patient \r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n        # change to use update queue number\r\n        #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n        #  :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n        #  :visit_type=>visit_type\r\n        #  }\r\n        n_txt = []\r\n        if !i[:qn].nil?\r\n            n_txt << \"Q:\\\\#{i[:qn]}\"\r\n        end\r\n        if i.note != \'\'\r\n            n_txt << i.note\r\n        end\r\n        d_qn = \"...\"\r\n        d_qn = \"..\\\\#{patient[:hn].tr(\'/\',\'\')[-5..-3]}/\\\\#{patient[:hn].tr(\'/\',\'\')[-2..-1]}\" if patient and  patient[:hn]\r\n        \r\n        c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"javascript:patient_q(\'\\\\#{i.id}\',\'\\\\#{d_qn}\');\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type,\r\n         :note=>n_txt.join(\' / \')\r\n        }\r\n         \r\n        if i.status==\'Waiting\' or i.status==\'Arrived\' or i.status==\'Preparing\'\r\n            c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n        #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        else\r\n            status = \'btn-info\'\r\n            status = \'\' if i.status ==\'Completed\' or \'Discharge\'\r\n            c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n        end\r\n         c\r\n        end\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\' or i[:status]==\'Arrived\' or i[:status]==\'Preparing\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' or i[:status]==\'Discharge\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:320px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Patient Queue</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n        <form name=\'q\' method=\'post\'>\r\n			<span style=\'width:80px\'>Queue Number : </span><span class=\"field-input\" >\r\n			    <input type=\"text\" name=\"qn\" id=\'qn\' style=\"width:50px\"/>\r\n			</span>\r\n			<input type=\"hidden\" name=\"app_id\" id=\"app_id\" value=\"\">\r\n			<input type=\"hidden\" name=\"app_status\" id=\"app_status\" value=\"Arrived\">\r\n\r\n            <div class=\"clear\"></div>\r\n            \r\n			<input type=\"submit\" name=\"Submit\" value=\"Submit\" class=\"btn btn-success\"/>\r\n			\r\n        </form>\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n    function patient_q(app_id) {\r\n        console.log(\"appointment id : \" + app_id);\r\n        $(\'#app_id\').val(app_id);\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function patient_q(app_id, qn) {\r\n        console.log(\"appointment id : \" + app_id);\r\n        $(\'#qn\').val(qn);\r\n        $(\'#app_id\').val(app_id);\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Nurse Index\',\'nurse_index?date=\'+params[:date] %> |\r\n<%= link_to \'Case Index\',\'case_index?date=\'+params[:date] %> |\r\n<%= link_to \'Patient Status\',\'patient_status?date=\'+params[:date] %> |\r\n<%= link_to \'Patient Board\',\'../Feed/nurse_board?date=\'+params[:date] %> |\r\n<!--<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |-->\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n </div><br/>',NULL,NULL,NULL,'2015-09-29 07:25:56','2015-09-29 07:25:56','',''),(1826,'context_menu',789,4,'\r\n<% \r\n   obj = [\r\n        {:name=>\'Reports\',:open=>true,:actions=>[\r\n            {:name=>\'Case report\',:service=>\'gastro\',:link=>\'../Report/case_reports\',:remote=>false},\r\n            {:name=>\'Colono report\',:service=>\'colono\',:link=>\'../Report/colono_reports\',:remote=>false},\r\n            {:name=>\'Diagnosis report\',:service=>\'colono\',:link=>\'../Report/diag_reports\',:remote=>false},\r\n            {:name=>\'Extra report\',:service=>\'colono\',:link=>\'colono_bowel\',:remote=>false},\r\n            {:name=>\'Endoscopist report\',:service=>\'report\',:link=>\'../Report/endoscopist_report\',:remote=>false},\r\n            {:name=>\'Provider report\',:service=>\'report\',:link=>\'../Report/case_provider_report\',:remote=>false}\r\n\r\n\r\n\r\n            ]\r\n        }\r\n    ]\r\n\r\n#   obj << {:name=>\'Links\', :actions=>[{:name=>\'Back to EHR\',:link=>\"../../www/Home/index\",:remote=>false}]}\r\n%>\r\n<%= show_menu obj%>\r\n\r\n\r\n<div class=\"accordion-group\">\r\n	<div class=\"accordion-heading\">\r\n		<a href=\"#collapse-0\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n		Dashboard\r\n		</a>\r\n		\r\n		<div class=\"accordion-body collapse in\" id=\"collapse-0\" style=\"display:none\">\r\n			<div class=\"accordion-inner\">\r\n				<ul class=\"nav nav-list\">\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"index\">Overview</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"weekly_report\">Weekly Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"case_report\">Monthly Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"endoscopist_report\">Endoscopist Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"procedure_report\">Procedure Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"total_ssa_report\">SSA Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"total_esd_report\">ESD Report</a></li>\r\n\r\n\r\n				\r\n				\r\n				</ul>\r\n			</div>\r\n	</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</div></div></div>',NULL,NULL,NULL,'2015-09-29 07:26:30','2015-09-29 07:26:30','context_menu',''),(1827,'case_reports_soup',789,2,'\r\n <h1>Case Report Summary </h1>\r\n <%\r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n \r\n\r\n\r\n  def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    @m_patient= model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    type = \'All\'\r\n    type = params[:report][:type] if params[:report]\r\n    \r\n    procedure = \'all\'\r\n    procedure = params[:report][:procedure] if params[:report]\r\n    \r\n    procedures = %w{all gastro colono push_enteroscopy sigmoid ercp eus dbe}\r\n    cmap = {}\r\n    for i in procedures\r\n        cmap[i] = i.humanize\r\n    end\r\n    \r\n%>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    v{\r\n        color:blue;\r\n    }\r\n</style>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date  , :order=>[:day,:month,:year]%>\r\n\r\n<br/>\r\n\r\nSchedule : <%=f.select :type, options_for_select(%w{all elective special_clinic emergency}.collect{|i| i.humanize }, type) %>\r\n\r\nProcedure : <%=f.select :procedure, options_for_select(procedures.collect{|i| [i.humanize,i] }, procedure) %>\r\n\r\n\r\n<br/>\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n  <%#params.inspect %>\r\n\r\n\r\n  <% if request.post? \r\n  \r\n  \r\n  # select appointment by date\r\n  \r\n  all_app = @models[:appointment].collection.find({:date=>{\'$gte\'=>from_date,\'$lt\'=>to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n  \r\n  \r\n  # select pm by module_id of appointment\r\n  \r\n  all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n  m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n  \r\n  # select patients by patient_id of pm \r\n  all_patients = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'hn\'=>1}}).to_a\r\n  m_patients = bmap all_patients\r\n  \r\n  \r\n  map = {}\r\n  \r\n  # for each forms prepare list of module_id \r\n  all_pm = @m_patient_module.collection.find({:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n  m_all_pm = bmap all_pm, \'module_id\'\r\n  \r\n  for i in all_pm\r\n  \r\n  m = i[\'module_name\'].split(\'#\')[-1]\r\n  \r\n  if procedure==\'all\'\r\n  \r\n  map[m] = [] unless map[m]\r\n  map[m] << i[\'module_id\']\r\n  \r\n  else\r\n  \r\n  if m == procedure\r\n  \r\n  map[m] = [] unless map[m]\r\n  map[m] << i[\'module_id\']\r\n  \r\n  end\r\n  \r\n      \r\n  end\r\n  \r\n  end\r\n  \r\n  \r\n  # for each form\'s records \r\n  case_map = {}\r\n  provider_map = {}\r\n  \r\n  \r\n  for k in map.keys\r\n    \r\n    rs = map[k]\r\n    case_map[k] = [] unless case_map[k]\r\n    if @models[k.to_sym]\r\n    \r\n    conds = {:_id=>{\'$in\'=>rs}}\r\n    \r\n# 0|Elective\r\n# 1|Emergency\r\n# 2|Special clinic\r\n# 3|Live demo\r\n    \r\n    \r\n    if type !=\'All\'\r\n    \r\n        ctype = \'\'\r\n        case type\r\n        when \'Elective\'\r\n            ctype = \'0\'\r\n        when \'Emergency\'\r\n            ctype = \'1\'\r\n        when \'Special clinic\'\r\n            ctype = \'2\'\r\n        end\r\n        \r\n       conds.merge! :schedule=> ctype\r\n       \r\n    end\r\n        \r\n    records = @models[k.to_sym].collection.find(conds, {:fields=>{\'findings\'=>1,\'_id\'=>1,\'schedule\'=>1,\'endoscopist\'=>1,\'created_at\'=>1,\'diagnosis_text\'=>1,\'diagnosis_group\'=>1,\'intervention_text\'=>1,\'procedure\'=>1,\'intervention\'=>1,\'intervention_group\'=>1,\'intervention_summary\'=>1}}).to_a\r\n\r\n   \r\n    findings_id = []\r\n    \r\n\r\n\r\n    for i in records\r\n        provider_map[i[\'endoscopist\']] = true \r\n        \r\n        findings_id += i[\'findings\'] if i[\'findings\']\r\n        \r\n        if true\r\n            case_map[k] << i \r\n        end\r\n        \r\n    end\r\n    \r\n    \r\n    \r\n    \r\n\r\n\r\n\r\n\r\n    end\r\n  \r\n  end\r\n  \r\n  \r\n  providers = @models[:provider].collection.find({:_id=>{\'$in\'=>provider_map.keys}})\r\n  m_providers = bmap providers\r\n  \r\n  \r\n  findings = @models[:finding].collection.find({:_id=>{\'$in\'=>findings_id.collect{|x| BSON::ObjectId(x)}}}).to_a\r\n  findings_map = bmap findings\r\n  \r\n  intervention_ids = findings.collect{|x| x[\'intervention\'] }\r\n  \r\n  interventions = @models[:intervention].collection.find({:_id=>{\'$in\'=>intervention_ids},:intervention_tag=>{\'$ne\'=>\"\"}},{:fields=>{\'intervention_tag\'=>1,\'op_clipping_type\'=>1}}).to_a\r\n  \r\n  interventions_map = bmap interventions\r\n  \r\n  \r\n     for i in records\r\n  \r\n    \r\n            if i[\'findings\']\r\n            \r\n            fs = i[\'findings\'].collect{|x| findings_map[BSON::ObjectId(x)][0] }\r\n            fs = fs.collect{|x| {:f=>x,:i=>interventions_map[x[\'intervention\']]} } \r\n            inv = []\r\n            inv = i[\'intervention_group\'].split(\"|\") if i[\'intervention_group\']\r\n            for f in fs\r\n                if f[:i]\r\n                    fi = f[:i][0]\r\n                    inv << fi[\'intervention_tag\']\r\n                end\r\n            end\r\n            \r\n            i[\'intervention_group\'] = inv.uniq.join(\'|\')\r\n            \r\n            end\r\n    \r\n            \r\n  end\r\n  \r\n  %>\r\n  <%#interventions_map.inspect %>\r\n  \r\n  \r\n For <i><%=from_date.strftime(\"%d-%m-%Y\")%> to <%=to_date.strftime(\"%d-%m-%Y\")%> </i>\r\n \r\n <br/><br/>\r\n \r\n  <table border=\"1\">\r\n  <tr><th>Procedure</th><th>Elective</th><th>Emergency</th><th>Special Clinic</th><th>Undefined</th><th>Total</th></tr>\r\n<%  \r\n    tsum = {\'0\'=>0,\'1\'=>0,\'2\'=>0,nil=>0}\r\n\r\nfor k in case_map.keys \r\n\r\n    \r\n    tmap = {}\r\n  case_map[k].each do |i|\r\n     \r\n     s = i[\'schedule\']\r\n     \r\n     tmap[s] = [] unless tmap[s]\r\n     tmap[s] << i \r\n     \r\n     tsum[s] = 0 unless tsum[s]\r\n     tsum[s] += 1\r\n      \r\n  end\r\n  \r\n%>\r\n      <tr><td><%=k.humanize%></td>\r\n      \r\n      <td align=\'center\'><%=tmap[\'0\'].size if tmap[\'0\']%></td>\r\n      <td align=\'center\'><%=tmap[\'1\'].size if tmap[\'1\']%></td>\r\n      <td align=\'center\'><%=tmap[\'2\'].size if tmap[\'2\']%></td>\r\n      <td align=\'center\'><%=tmap[\'\'].size if tmap[\'\']%></td>\r\n      \r\n      <th><%=case_map[k].size%></th></tr>\r\n <% end %>      \r\n \r\n <tr>\r\n     <td>&nbsp;</td>\r\n     <th><%=tsum[\'0\']%></td>\r\n     <th><%=tsum[\'1\']%></td>\r\n     <th><%=tsum[\'2\']%></td>\r\n     <th><%=tsum[\'\']%></td>\r\n     <%\r\n        total_sum = 0 \r\n        total_sum += tsum[\'0\'] if tsum[\'0\']\r\n        total_sum += tsum[\'1\'] if tsum[\'1\']\r\n        total_sum += tsum[\'2\'] if tsum[\'2\']\r\n        total_sum += tsum[\'\'] if tsum[\'\']\r\n\r\n     %>\r\n     <th><%=total_sum%></th>\r\n </tr>\r\n  </table>\r\n  \r\n  \r\n  <br>\r\n  \r\n  \r\n  \r\n  <% if procedure!=\'all\'%>\r\n  \r\n  <%\r\n     int_map = {}\r\n     for i in records\r\n     \r\n     int = i[\'intervention_group\']\r\n     if int\r\n     ints = int.split(\'|\') \r\n     \r\n     for j in ints\r\n     \r\n        int_map[j] = 0 unless int_map[j]\r\n        int_map[j] += 1\r\n     \r\n     end\r\n     \r\n    end\r\n      \r\n     end\r\n  \r\n  %>\r\n  \r\n  \r\n  <table border=\"1\">\r\n  \r\n  <tr><th>Intervention</th><th>Count</th></tr>\r\n  <% for i in int_map.keys %>\r\n  <tr>\r\n      <th><%=i.humanize%></th>\r\n      <td align=\'center\'><%=int_map[i]%></td>\r\n  </tr>\r\n  \r\n  <% end %>\r\n  \r\n  \r\n  </table>\r\n  \r\n  \r\n  <br/>\r\n  \r\n  \r\n   <%\r\n     dx_map = {}\r\n     for i in records\r\n     \r\n     int = i[\'diagnosis_group\']\r\n     if int\r\n     dxs = int.split(\'|\') \r\n     \r\n     for j in dxs\r\n     \r\n        dx_map[j] = 0 unless dx_map[j]\r\n        dx_map[j] += 1\r\n     \r\n     end\r\n     \r\n    end\r\n      \r\n     end\r\n  \r\n  %>\r\n\r\n  <%\r\n  \r\n    options = get_document(procedure ).find_by_column_name(\'diagnosis_group\').get_lov_options   \r\n    \r\n    dx_name = {}\r\n    \r\n    for i in options\r\n        \r\n        dx_name[i[0]] = i[1].strip\r\n    \r\n    end\r\n  \r\n  \r\n  %>\r\n  \r\n\r\n  \r\n  <table border=\"1\">\r\n  \r\n  <tr><th>Diagnosis Group</th><th>Count</th></tr>\r\n  <% for i in dx_map.keys \r\n  \r\n  name = \"Undefined(\\\\#{i})\"\r\n  name = dx_name[i] if dx_name[i]\r\n  \r\n  %>\r\n  <tr>\r\n      <th><%=name%></th>\r\n      <td align=\'center\'><%=dx_map[i]%></td>\r\n  </tr>\r\n  \r\n  <% end %>\r\n  \r\n  \r\n  </table>\r\n  \r\n  \r\n  <br/>\r\n  \r\n  <% end %>\r\n  <table border=\"1\">\r\n  <tr>\r\n  <th>#</th>\r\n  <th>Procedure</th>\r\n  <th>Date</th>\r\n  <th>HN</th>\r\n  <th>Patient\'s name</th>\r\n  <th>Schedule</th>\r\n  <th>Endosocpist</th>\r\n  <th>Diagnosis</th>\r\n  <th>Intervention</th>\r\n  <th>InterventionGroup</th>\r\n  </tr>\r\n  <%\r\n  \r\n  # select provider of those records\r\n  for k in case_map.keys\r\n \r\n  \r\n  %>\r\n  <tr style=\"background-color:#ccffcc\"><td colspan=\"10\"><h1><%=k.humanize%></h1></td></tr>\r\n  <%\r\n  \r\n  tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n  tmap = {}\r\n  case_map[k].each do |i|\r\n     \r\n     s = i[\'schedule\']\r\n     \r\n     tmap[s] = [] unless tmap[s]\r\n     tmap[s] << i \r\n      \r\n  end\r\n  \r\n  tmap.each_pair do |ks, list| \r\n   index = 0 \r\n   %>\r\n    <tr style=\"background-color:#cccccc\"><td colspan=\"10\"><%=tschedule[ks]%></td></tr>\r\n   <%\r\n  list.each do |i|\r\n    \r\n    pm = m_all_pm[i[\'_id\']][0]\r\n    if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n    patient = m_patients[pm[\'patient_id\']][0]\r\n    provider = nil\r\n    provider = m_providers[i[\'endoscopist\']][0]  if m_providers[i[\'endoscopist\']]\r\n    if pm and patient  and provider\r\n        \r\n        schedule = \'-\'\r\n        \r\n        schedule = tschedule[ i[\'schedule\']]\r\n        \r\n        %><tr><td><%=index+1%></td>\r\n        <td><%=k.humanize%></td><td><%=i[\'created_at\'].strftime(\"%d-%m-%Y\") %></td><td><%=patient[\'hn\'] %></td><td><%=patient[\'first_name\'] %> <%=patient[\'last_name\']%></td><td><%= schedule %></td><td><%= provider[\'name\'] %></td>\r\n        <td style=\"width:300px\"><%= i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').html_safe if i[\'diagnosis_text\'] %></td>\r\n        <td style=\"width:300px\"><%= i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').html_safe if i[\'intervention_text\'] %><%= i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').html_safe if i[\'intervention_summary\'] %></td>\r\n        <%\r\n           ig = \'background-color:#ffcccc\'\r\n        %>\r\n        <td style=\'<%=ig if  i[\'intervention_text\']!=\"\" and i[\'intervention_group\'] and  i[\'intervention_group\'].strip==\'\' %>\'>\r\n        <%\r\n            intv = \'-\'\r\n          \r\n\r\n        %>\r\n        <%=i[\'intervention_group\']%><%#i[\'intervention_text\']%></td>\r\n        \r\n        </tr>\r\n        \r\n        \r\n        <%\r\n        \r\n        index+=1\r\n        \r\n    end\r\n    \r\nend\r\n  \r\n        \r\n  end\r\n  \r\n  end\r\n  \r\n  end\r\n  \r\n  %>\r\n  </table>\r\n  <%\r\n  \r\n  \r\n  # for each recoreds to reprrt\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  %>\r\n  \r\n  \r\n  \r\n  <% end %>\r\n\r\n',NULL,NULL,NULL,'2015-09-29 07:33:07','2015-09-29 07:33:07','case_reports_soup',''),(1830,'print',639,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\n@font-face {\r\n    font-family: \'barcode\';\r\n	src: url(\'/esm/ehr/emr/font/barcode.eot\');\r\n	src: local(\'☺\'), url(\'/esm/ehr/emr/font/c39hrp24dhtt.woff\') format(\'woff\'), url(\'/esm/ehr/emr/font/barcode.ttf\') format(\'truetype\'), url(\'/esm/ehr/emr/font/barcode.svg\') format(\'svg\');\r\n	font-weight: 700px;\r\n	font-size:60px;\r\n}\r\n.barcode\r\n	{font-family:\'barcode\',Sans-Serif;}\r\n#page {border:solid 0px;  border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding:0 0px 10px 10px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:360px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:360px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:360px;margin-left:0px;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:0px solid #ccc;\r\n	-webkit-border-radius: 5px; /* Safari prototype */\r\n	-moz-border-radius: 5px; /* Gecko browsers */\r\n	border-radius: 5px; /* Everything else - limited support at the moment */	\r\n	margin:10px;\r\n}\r\n.smm { font-size:9pt; }\r\n#box img{\r\n		width:150px;\r\n}\r\nlabel{\r\n	color:#666;\r\n}\r\n</style>\r\n<body>\r\n<br />\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"page\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p></p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n%>\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tr>\r\n<td width=\"310\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' width=\"300\" style=\"float:right;margin:5px; -moz-border-radius: 5px;\r\nborder-radius: 5px; background:#fff;\"/></td>\r\n<td>\r\n</td>\r\n<td>\r\n<div class=\"barcode\" style=\"font-size:50px; float:right; margin-right:30px; height:60px\"><%= @patient.hn %> </div></td>\r\n</tr>\r\n\r\n</table>\r\n----------------------------------------------------------------\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tr>\r\n  <td colspan=\"2\" >H.N.</td>\r\n  <td width=\"71%\">: <%= @patient.hn %></td>\r\n</tr>\r\n<tr>\r\n  <td colspan=\"2\" >วันที่</td>\r\n  <td>: <%= render_value \'date\' %></td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" ><storng>ชื่อ-นามสกุล</storng></td><td>: <%=@patient.first_name %> <%=@patient.last_name %></td></tr>\r\n<tr><td colspan=\"2\"><storng>มาพบแพทย์</storng></td><td>: <%= render_value \'provider\' %></td></tr>\r\n<tr>\r\n<td colspan=\"2\"><storng>เวลานัด</storng></td><td>: <%= render_value \'start\' %> ถึง <%= render_value \'stop\' %></td></tr>\r\n<tr>\r\n<td colspan=\"2\"><storng>มาทำ</storng></td><td>: <%= render_value \'procedure\' %></td></tr>\r\n<tr>\r\n  <td width=\"16%\">Note</td>\r\n  <td colspan=\"2\"><p>: <%= render_value \'note\' %></p></td>\r\n  </tr>\r\n</table>\r\n\r\n\r\n<%# render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<%# @record.inspect %>\r\n\r\n<!-- <a href=\"http://<%=get_setting \'barcode_station\' %>/print?name=<%=@patient.first_name%>&date=<%= render_value \'date\'%>&proc=<%= render_value(\'procedure\').strip %>&hn=<%= @patient.hn %>\">Print</a> -->\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-10-01 13:03:28','2015-10-01 13:03:28','print',''),(1833,'get_previous',725,3,'<%= render :inline=>this.initz %>\r\n<%\r\n    pid = \'\'\r\n    if params[:pid]\r\n        pid = params[:pid]\r\n    end\r\n    \r\n    all_app = @m_pat_mod.where(:patient_id=>pid, :module_name=>\"\\\\#{@current_project.name}#appointment\").reverse.limit(3).sort_by{|i| i[:date]}\r\n    app_ids = []\r\n    par_ids = []\r\n    all_app.each do |i|\r\n        app_ids << i[:module_id].to_s\r\n        par_ids << i.id.to_s\r\n    end\r\n    \r\n    a_app = get_model[:appointment].find(app_ids)\r\n    a_pm = @m_pat_mod.where(:parent_id=>par_ids, :module_name=>\"\\\\#{@current_project.name}#pre_anesthetic\").all\r\n    \r\n    res = {}\r\n    res[:pid] = pid\r\n    # res[:all_pm] = @m_pat_mod.where(:patient_id=>pid, :module_name=>\"\\\\#{@current_project.name}#appointment\").reverse.limit(3).sort_by{|i| i[:date]}\r\n    res[:app_ids] = app_ids\r\n    res[:appointment] = a_app\r\n    res[:par_ids] = par_ids\r\n    res[:parent] = a_pm\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-10-05 16:07:13','2015-10-05 16:07:13','get_previous',''),(1834,'total_esd_report',522,2,'<br/>\r\n<div><span style=\"font-size:2em\" >ESD reports</span>\r\n<span style=\"float:right\"><%=link_to \"Export\", \"./total_esd_report_excel\",:class=>\"btn btn-success\"%></span>\r\n</div>\r\n<br/>\r\n<%= render :inline=>this.init%>\r\n<%\r\n\r\n    m = @models[:colonoscopy_scope].collection.find({},{:fields=>{\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1,\'treatment_by\'=>1 }}).to_a\r\n   \r\n#   colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n# diagnosis_note scope_note project procedure\r\n\r\n   def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n\r\n    \r\n    list = []\r\n    res = []\r\n    \r\n    for i in m\r\n    \r\n        if i[\'endoscopy_dx\']==\'ESD\'\r\n            list << i \r\n        elsif i[\'abnormal_note\'] and i[\'abnormal_note\'].downcase.index(\'esd\')\r\n            list << i\r\n        elsif i[\'treatment_by\'] and i[\'treatment_by\'].downcase.index(\'esd\')\r\n            list << i \r\n        end\r\n    end\r\n    \r\n    # m = @models[:colonoscopy_scope].collection.find({},{:fields=>{\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1 }}).to_a\r\n   \r\n    list = @models[:colonoscopy_scope].collection.find({:_id=>{\'$in\'=>list.collect{|i|i[\'_id\']}}}).to_a\r\n    \r\n    # { $where: \"this.name.length > 1\" }\r\n    \r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n    map = {\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1, \'procedure\'=>1,\'scope_note\'=>1, \'diagnosis_note\'=>1,\'project\'=>1}\r\n    qmap = {:diagnosis_group=>{\'$ne\'=>\'Normal\'}}\r\n    where = []\r\n    for i in scope_list\r\n        map[i]=1\r\n    end\r\n    \r\n    \r\n    qmap[\'$where\']= \'this.rectum_scope.length > 1 || this.sigmoid_scope.length > 1 || this.transvers_colon_scope.length>1 || this.ascending_colon_scope.length>1 || this.cecum_scope.length>1 || this.terminal_ileum_scope.length>1\'\r\n    \r\n    ml = @models[:colonoscopy].collection.find({},{:fields=>map}).to_a\r\n    \r\n    lim = {}\r\n    for i in list\r\n    \r\n        lim[i[\'_id\']] = i\r\n    \r\n    end\r\n    \r\n    plist = {}\r\n    \r\n    for i in ml\r\n    \r\n        f = false\r\n        \r\n        for j in scope_list\r\n            \r\n            for k in i[j]\r\n            \r\n            if lim[k]\r\n       \r\n                plist[i[\'_id\']] = {:c=>i,:l=>{}} unless plist[i[\'_id\']]\r\n                \r\n                plist[i[\'_id\']][:l][j] = [] unless plist[i[\'_id\']][:l][j]\r\n                plist[i[\'_id\']][:l][j] << lim[k]\r\n                \r\n            end\r\n            \r\n            end\r\n             \r\n        end\r\n        \r\n            # map = {\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1, \'procedure\'=>1,\'scope_note\'=>1, \'diagnosis_note\'=>1}\r\n\r\n        \r\n        if (i[\'project\'] and i[\'project\'].downcase.index(\'esd\')) or (i[\'procedure\'] and i[\'procedure\'].downcase.index(\'esd\')) or (i[\'scope_note\'] and i[\'scope_note\'].downcase.index(\'esd\')) or (i[\'diagnosis_note\'] and i[\'diagnosis_note\'].downcase.index(\'esd\')) \r\n            \r\n            plist[i[\'_id\']] = {:c=>i,:l=>{}} unless plist[i[\'_id\']]\r\n            \r\n        end\r\n        \r\n        \r\n        \r\n    end\r\n#   {:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}}\r\n     # all pm colono of those appointments\r\n     \r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    \r\n    all_pm_colo = @m_patient_module.collection.find({:module_id=>{\'$in\'=>plist.keys},:module_name=>\"\\\\#{pname}colonoscopy\"}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'module_id\'\r\n    \r\n          # all pm colono of those appointments\r\n    all_patient = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'patient_id\'] }}}).to_a\r\n    m_all_patient = bmap all_patient, \'_id\'\r\n    \r\n    cols = %w{abnormal_type  endoscopy_dx morphology_type size treatment treatment_by clip patho_number pit_pattern pit_pattern pitt_by kudo_type vascular_pattern \r\n    vascular_by sano_type nice_classification niceby abnormal_note tattoo jnet_class jnetby chromo complication } \r\n    count = 0 \r\n%>\r\n<table border=\"1\" style=\"border-collapse: collapse;font-size:0.6em\" ><th>No.</th>\r\n<th style=\"width:100px\">Date</th><th>HN</th><th style=\"width:100px\">First name</th><th style=\"width:100px\">Last name</th><th>Procedure</th><th>Note</th><th>Project</th>\r\n<th>Location</th>\r\n<% for x in cols %>\r\n<th><%= x.humanize %></th>\r\n<% end %>\r\n<% 5.times.each do |i| %>\r\n<th  style=\"width:100px\"><%=i+1%>.</th>\r\n<% end %>\r\n<%\r\n   for i in plist.keys\r\n    colo = plist[i]\r\n    c = colo[:c]\r\n    l = colo[:l]\r\n    p_m = m_all_pm_colo[i][0]\r\n    p = m_all_patient[p_m[\'patient_id\']][0] \r\n    \r\nif l.size == 0 \r\n%>\r\n<tr><td><%=count+1%><% count+=1 %>.</td><td style=\"width:100px\"><%=p_m[\'date\'].strftime(\"%d-%m-%Y\")%></td><td><%=p[\'hn\']%></td>\r\n<td><%=p[\'first_name\']%></td><td><%=p[\'last_name\']%></td>\r\n<td><%=c[\'procedure\']%></td>    \r\n<td><%=c[\'scope_note\']%></td>      \r\n<td><%=c[\'project\']%></td>      \r\n    \r\n</tr>\r\n<%\r\nelse\r\n    l.each_pair do |location,list|\r\n        \r\n        for li in list\r\n\r\n%>\r\n<tr><td><%=count+1%><% count+=1 %>.</td><td  style=\"width:100px\"><%=p_m[\'date\'].strftime(\"%d-%m-%Y\")%></td><td><%=p[\'hn\']%></td>\r\n<td><%=p[\'first_name\']%></td><td><%=p[\'last_name\']%></td>\r\n<td><%=c[\'procedure\']%></td>    \r\n<td><%=c[\'scope_note\']%></td>      \r\n<td><%=c[\'project\']%></td>  \r\n<td><%=location.split(\"_\")[0..-2].join(\" \")%></td>\r\n<% for x in cols \r\n  style = \'\'\r\n  style = \'style=\"width:150px\"\' if x==\'endoscopy_dx\'\r\n%>\r\n<td <%=style.html_safe %>><%= li[x] %></td>\r\n<% end %>\r\n<% \r\n  \r\n\r\n    atts = @models[:attachment].find(li[\'image\']).to_a\r\n    \r\n    %>\r\n    <%=%>\r\n<%\r\nl = atts[0..4].compact\r\nfor ai in l\r\n%>\r\n<td style=\"width:100px\">\r\n<a href=\"<%=ai.path%>\" class=\"highslide \" rel=\"highslide\" onclick=\"return hs.expand(this)\"><center>\r\n<img  src=\"<%=ai.path%>&thumb=1\" width=\"100\" />\r\n</a>\r\n</td>\r\n<% end %>\r\n\r\n<% (5-l.size).times do |img| %>\r\n<td >&nbsp;</td>\r\n<% end %>\r\n</tr>\r\n<% end %>\r\n <% \r\n        end\r\n    end\r\n end %>    \r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2015-10-06 08:40:15','2015-10-06 08:40:15','total_esd_report',''),(1835,'document_name',791,1,'\'implant_component\'',NULL,NULL,NULL,'2015-10-06 16:06:33','2015-10-06 16:06:33',NULL,NULL),(1836,'document_name',792,1,'\'company_setting\'',NULL,NULL,NULL,'2015-10-06 16:09:38','2015-10-06 16:09:38',NULL,NULL),(1837,'document_name',793,1,'\'demo_implant\'',NULL,NULL,NULL,'2015-10-06 16:27:10','2015-10-06 16:27:10',NULL,NULL),(1838,'json',793,3,'<%\r\n    res = {}\r\n    \r\n    if params[:id]\r\n        res = get_model[this.table_name.to_sym].find(params[:id])\r\n    else\r\n        res = get_model[this.table_name.to_sym].all\r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-10-06 16:29:17','2015-10-06 16:29:17','json',''),(1839,'json',792,3,'<%\r\n    res = {}\r\n    \r\n    if params[:id]\r\n        res = get_model[this.table_name.to_sym].find(params[:id])\r\n    else\r\n        res = get_model[this.table_name.to_sym].all\r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-10-06 16:38:42','2015-10-06 16:38:42','json',''),(1840,'json',791,3,'<%\r\n    res = {}\r\n    \r\n    if params[:id]\r\n        res = get_model[this.table_name.to_sym].find(params[:id])\r\n    elsif params[:pid]\r\n        res = get_model[this.table_name.to_sym].where(:product_id=>params[:pid]).first\r\n    else\r\n        res = get_model[this.table_name.to_sym].all\r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-10-06 17:37:19','2015-10-06 17:37:19','json',''),(1841,'form',793,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    function update_result() {\r\n        val = $(this).val();\r\n        console.log(\"VALUE = \" + val);\r\n        $.get( \"../ImplantComponent/test\", { pid: val} )\r\n            .done(function( data ) {\r\n                $(\'#implant_result\').html(data);\r\n                // console.log(\"DATA : \" + data);\r\n            }\r\n        );\r\n    }\r\n    $(document).ready(function() {\r\n        $(\'#demo_implant-implant_component-add-action\').hide();\r\n        p = $(\'#demo_implant-implant_component-add-action\').parent();\r\n        p.html(\'<input type=\"text\" id=\"demo_implant_text\"/><br/><div id=\"implant_result\"/><br/>\');\r\n        $(\'#demo_implant_text\').change(update_result);\r\n    });\r\n</script>\r\n',NULL,NULL,NULL,'2015-10-06 17:38:16','2015-10-06 17:38:16','',''),(1842,'test',791,3,'<%\r\n    res = {}\r\n    \r\n    if params[:id]\r\n        res = get_model[this.table_name.to_sym].find(params[:id])\r\n    elsif params[:pid]\r\n        res = get_model[this.table_name.to_sym].where(:product_id=>params[:pid]).first\r\n    else\r\n        res = get_model[this.table_name.to_sym].all\r\n    end\r\n%>\r\n<!--<b>ID</b> : <%=res.id.to_s%><br/>-->\r\n<b>Component Description</b> : <%= res[:component_description] %><br/>\r\n<b>Size</b> : <%= res[:size] %>, <b>Side</b> : <%= res[:side] %><br/>\r\n<%= \"<b>Note</b> : \\\\#{res[:note]}\".html_safe if res[:note] != \'\' %><br/>\r\n<input type=\"text\" id=\"text-<%=res.id.to_s%>\"/><br/>\r\n<div id=\"content-<%=res.id.to_s%>\"></div>\r\n<script>\r\n    function content_<%=res.id.to_s%>() {\r\n        val = $(this).val();\r\n        console.log(\"VALUE <%=res[:id].to_s%> = \" + val);\r\n        $.get( \"../ImplantComponent/test\", { pid: val} )\r\n            .done(function( data ) {\r\n                $(\'#content-<%=res.id.to_s%>\').html(data);\r\n                // console.log(\"DATA : \" + data);\r\n            }\r\n        );\r\n    }\r\n    $(\'#text-<%=res.id.to_s%>\').change(content_<%=res.id.to_s%>);\r\n</script>',NULL,NULL,NULL,'2015-10-06 17:57:11','2015-10-06 17:57:11','test',''),(1845,'index_bk',622,2,'<%\r\n    \r\n    module_name = @current_project.name\r\n    if params[:date]\r\n        session[module_name]={:date=>params[:date]}\r\n    end\r\n    if session[module_name]\r\n        params[:date] = session[module_name][:date]\r\n    end\r\n    unless params[:date]\r\n        params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n    end\r\n \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n\r\n<%\r\n    # checking existing provider\r\n    prov = get_model[:provider].where(:provider_type=>\'1\').all\r\n    if prov.empty?\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"modal-provider\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>ข้อแนะนำ</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n								    ไม่พบรายชื่อแพทย์ในระบบ กรุณาคลิกที่ปุ่ม\r\n								    \r\n									<ul class=\"dshb_icoNav tac\" style=\'display:inline\'>\r\n									    <li><a style=\"background-image: url(/gebo/img/gCons/configuration02.png)\" href=\"javascript:void(0);\">\r\n										    Settings</a></li>\r\n									</ul>\r\n									\r\n									เพื่อตั้งค่ารายชื่อแพทย์\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">รับทราบ</a>\r\n								</div>\r\n							</div>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\'#modal-provider\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n        \r\n        // $(\'#btn-add_patient\').off(\'click\');\r\n    });\r\n</script>\r\n<%\r\n    end\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n    \r\n    .table td {\r\n        vertical-align: middle;\r\n    }\r\n\r\n\r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	/*position: fixed;*/\r\n	position: absolute;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat #144884;\r\n}\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting preparing processing recovery completed discharge cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %><%= error%>\r\n    <%\r\n    session.delete :s_date\r\n    end\r\n     %>\r\n        <%\r\n    search_patient = false\r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n          end\r\n        session[:s_status] = s_status\r\n         session[:s_provider] = s_provider \r\n        \r\n    end\r\n    if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        p_app[:status] = \'Appointed\'\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Add & Continue\"\r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n</script>\r\n<%\r\n        end\r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       <b>Home : <%= date.strftime(\'%d/%m/%Y\') %></b>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n            <div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>params[:opt], :html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\">Date : </label>\r\n                    <div class=\"field-input\" >\r\n                        <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\">HN / Name : </label>\r\n                    <div class=\"field-input\">\r\n                        <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n                    </div>\r\n                </span>\r\n            \r\n                <span class=\"field-data\" style=\"margin-top:5px;width:300px\"> \r\n                        <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                        <%=link_to \'Advanced Search\', \'javascript:void(0)\', :id=>\'btn-advanced_search\', :class=>\'btn\' %>\r\n                        <%=link_to \'Show Filter\', \'javascript:void(0)\', :id=>\'btn-show_filter\', :class=>\'btn\' %>\r\n                </span>\r\n                \r\n                <div class=\"clear\"></div>\r\n\r\n                <span class=\"field-data\">\r\n                    <label class=\"field-label\">&nbsp;</label>\r\n                    <div class=\"field-input\">\r\n                        <%=link_to \'Add Patient\', \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\',:style=>\'margin-top:10px\'%>\r\n                    </div>\r\n                </span>\r\n\r\n            <div class=\"clear\"></div>\r\n            \r\n            <script>\r\n                $(\'#search_hn\').focus();\r\n            </script>\r\n<% end %>\r\n            \r\n        </div>\r\n        \r\n    </div>\r\n\r\n    <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" id=\'block-filter\'>\r\n        <a class=\"close\" href=\"javascript:void(0);\" id=\'btn-hide_filter\' style=\'float:left\'>x</a>\r\n        <div class=\"row-fluid\">\r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\"> </label>\r\n                    <div class=\"field-input\" style=\'float:right\'>&nbsp;<b>Filter by</b></div>\r\n                </span>\r\n                <!-- filter -->\r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Provider : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-provider\" id=\"fil-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"prov_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"prov_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Procedure : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-procedure\" id=\"fil-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"proc_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"proc_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Visit : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-visit\" id=\"fil-visit\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"visit_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"visit_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Status : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-status\" id=\"fil-status\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"status_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in status_list do\r\n            %>\r\n                            <option value=\"status_<%= l %>\"><%= l %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n        </div>\r\n    </div>\r\n\r\n        <!--DATE : <%# date %>-->\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%#params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n# SEARCH SECTION    \r\n    if search_patient\r\n        \r\n        fields = {:hn=>s_hn, :first_name=>s_hn, :last_name=>s_hn}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n    \r\n        if keys.size>0\r\n            conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n            criteria = {\'$or\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n    \r\n        patients = patient_model.where(criteria).limit(20).all  \r\n        maps = module_model.all     :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n        aps = ap_model.find(maps.collect{|i| i.module_id})\r\n%>\r\n<!--<%= params[:search].to_json.html_safe %>-->\r\n<%\r\n        if aps.count == 1 # and @current_role==\'developer\' \r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= aps.first.id.to_s %>\';\r\n</script>\r\n<%\r\n        end\r\n\r\n    elsif pad = params[:adv_pat]\r\n        adv = params[:advanced]\r\n        fields = {:provider=>adv[:provider], :visit_type=>adv[:visit_type], :indication=>adv[:indication], :procedure=>adv[:procedure]}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>v} if v and v!=\'\' \r\n        end\r\n        \r\n        if keys.size>0\r\n            criteria = {\'$and\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n        \r\n        # patient criteria\r\n        fs = {:first_name=>pad[:fname], :last_name=>pad[:lname]}\r\n        ks = []\r\n        fs.each_pair do |k, v|\r\n            ks <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n        if ks.size>0\r\n            cr = {\'$or\'=>ks}\r\n        else\r\n            cr ={}\r\n        end\r\n        \r\n        a_app = []\r\n        if !criteria.empty?\r\n            a_app = ap_model.where(criteria).all\r\n        end\r\n        \r\n        a_pat = []\r\n        if !cr.empty?\r\n            a_pat = patient_model.where(cr).all\r\n        end\r\n        \r\n        if !a_app.empty? and cr.empty?\r\n            aps = a_app\r\n        elsif a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(maps.collect{|i| i.module_id})\r\n        elsif !a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(a_app.collect{|i|i.id} & maps.collect{|i| i.module_id})\r\n        else\r\n            aps = ap_model.limit(20).all\r\n        end\r\n    else\r\n    \r\n        conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n        if s_provider and s_provider !=\'\'\r\n            conds.merge! :provider=>s_provider \r\n        end\r\n\r\n        if s_status and s_status != \"\"\r\n            conds.merge! :status=>s_status \r\n        end\r\n    \r\n        aps = ap_model.all(conds)\r\n\r\n    end\r\n     \r\n         \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\") if patient\r\n         public_id = \'-\'\r\n         bdate = i.date.strftime(\'%d/%m/\').to_s + (i.date.strftime(\'%Y\').to_i + 543).to_s\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id}\"),\r\n         :provider=>provider_name,:date=>i.date.strftime(\'%d/%m/%Y\'),:note=>\"\\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\',:style=>\'margin:0px\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type, :patient_id=>patient.id, :prov_id=>i.provider, :proc_id=>i.procedure, :visit_id=>i.visit_type, :visit=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    \r\n        labels = {:no=>\'No.\',:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Action\', :procedure=>\'Procedure\', :visit=>\'Visit type\' }\r\n    \r\n    %>\r\n<div class=\"se-pre-con\"></div>\r\n<%\r\n    if aps.empty?\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\' style=\'padding:20px\'>\r\n        <center><h3>ไม่มีรายการนัดหมายสำหรับวันนี้ คลิกปุ่ม \r\n        <%=link_to \'Add Patient\', \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\',:style=>\'\',:disabled=>true%>\r\n        เพื่อเพิ่มรายการนัดหมาย</h3></center>\r\n    </div>\r\n</div>\r\n<%\r\n    else\r\n        # table fields\r\n        tf = [:no]+table_model+[:processing_ctrl,:visit,:note]\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\' style=\'padding:20px\'>\r\n        Total Patient : <span style=\'color:blue\' id=\'total\'><%= aps.size %></span><br/>\r\n        <table class=\"table table-bordered\">\r\n            <thead>\r\n                <tr>\r\n<%\r\n            tf.each do |i|\r\n%>\r\n                    <th><%= labels[i] %></th>\r\n<%\r\n            end\r\n%>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n<%\r\n            no = 1;\r\n            aps.each do |i|\r\n                i[:no] = link_to(no.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{i[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n%>\r\n                <tr class=\'filterable\'>\r\n<%\r\n                tf.each do |j|\r\n                    cs = \'\'\r\n                    if j.to_s == \'provider\'\r\n                        cs = \"class=\'filter prov_\\\\#{i[:prov_id]}\'\"\r\n                    elsif j.to_s == \'procedure\'\r\n                        cs = \"class=\'filter proc_\\\\#{i[:proc_id]}\'\"\r\n                    elsif j.to_s == \'note\'\r\n                        cs = \"class=\'filter visit_\\\\#{i[:visit_id]}\'\"\r\n                    elsif j.to_s == \'status_ctrl\'\r\n                        cs = \"class=\'filter status_\\\\#{i[:status]}\'\"\r\n                    end\r\n%>\r\n                    <td <%= cs.html_safe %>><%= i[j] %></td>\r\n<%\r\n                end\r\n%>\r\n                </tr>\r\n<%\r\n                no += 1\r\n            end # end aps\r\n%>\r\n            </tbody>\r\n        </table>\r\n    </div>\r\n</div>\r\n<%\r\n    end\r\n%>\r\n\r\n\r\n<% if false %>\r\n<%\r\n        app_a = []\r\n        app_c = []\r\n        aps.each do |i|\r\n            if i[:status] == \'Completed\'\r\n                app_c << i\r\n            else\r\n                app_a << i\r\n            end\r\n        end\r\n%>\r\n<div id=\'default-panel\' style=\'padding:5px\'>\r\n    <div class=\"tabbable\">\r\n        <ul class=\"nav nav-tabs\">\r\n            <li class=\"active\"><a href=\"#appointed\" data-toggle=\"tab\">Appointed (<%= app_a.count %>)</a></li>\r\n            <li><a href=\"#completed\" data-toggle=\"tab\">Completed (<%= app_c.count %>)</a></li>\r\n        </ul>\r\n        <div class=\"tab-content\">\r\n            <div class=\"tab-pane active\" id=\"appointed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_a,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n            <div class=\"tab-pane\" id=\"completed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_c,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<% end %>\r\n\r\n<% if false %>\r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    # out[0] = count.to_s+\".\"\r\n                    out[0] = link_to(count.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\").html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n        </div>\r\n<% end %>        \r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n <script>\r\n function change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"<%=params[:opt]%>?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n\r\n<% if false %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Encounter</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n\r\n    \r\n   \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n<% end  %>\r\n<div class=\"alert \">\r\n<%# link_to \'Total Status\',\'total_status?print[date]=\'+params[:date], :target=>\'_blank\' %>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date],class: \'btn btn-mini\' %> |\r\n<!--<%= link_to \'Status Feed\',\'total_status?print[date]=\'+params[:date],class: \'btn btn-mini\', :target=>\'_blank\' %> |-->\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date],class: \'btn btn-mini\' %> | \r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date],class: \'btn btn-mini\' %> |\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n<%\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"myModal2\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Modal header</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n									Lorem ipsum dolor sit amet, consectetur adipiscing elit. Pellentesque non elit tellus, eleifend varius erat. Lorem ipsum dolor sit amet, consectetur adipiscing elit. In bibendum laoreet ante sodales elementum. Nullam varius interdum est, at ornare quam aliquam eu. Nulla ultricies commodo leo sit amet vulputate.\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n							</div>\r\n	\r\n<div class=\"modal hide fade\" id=\"modal2\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Advanced Search</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n        \r\n<%= form_for :advanced , :url=>params[:opt] do |f| %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name  : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[first_name]\" id=\"data-fname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[last_name]\" id=\"data-lname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <%= f.submit \'Search\', :class=>\'btn btn-success\' %>\r\n                <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a> \r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n							\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                <br/>\r\n                <div id=\"patient_msg\"></div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'<%= Time.now.strftime(\'%H:%M\') %>\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Add & Continue\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n</script>\r\n\r\n<script>\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    \r\n    function filter() {\r\n        var prov = $(\"#fil-provider\").val();\r\n        var proc = $(\"#fil-procedure\").val();\r\n        var visit = $(\"#fil-visit\").val();\r\n        var status = $(\"#fil-status\").val();\r\n        var total = 0;\r\n        \r\n        if (prov.indexOf(\'all\') != -1 && proc.indexOf(\'all\') != -1 && visit.indexOf(\'all\') != -1 && status.indexOf(\'all\') != -1) {\r\n            $(\'tr\').show();\r\n            total++;\r\n        } else {\r\n            $(\'.filterable\').hide();\r\n            console.log(\'all hide ...\');\r\n            $(\"td.filter\").each(function (i, col) {\r\n                \r\n                    if ($(col).hasClass(prov) || $(col).hasClass(proc) || $(col).hasClass(visit) || $(col).hasClass(status)) {\r\n                        $(col).parent(\'tr\').show();\r\n                        total++;\r\n                    } else {\r\n                        // if (!$(col).parent(\'tr\').is(\':visible\')) {\r\n                            // $(col).parent(\'tr\').hide();\r\n                        // }\r\n                    }\r\n                    // console.log(\'i : \' + i + \", col : \" + col)\r\n                    \r\n            });\r\n        }\r\n        \r\n        $(\'#total\').text(total);\r\n        console.log(\'Total filter : \' + total);\r\n        \r\n    }\r\n    \r\n    $(document).ready(function(){\r\n        <% if !prov.empty? %>\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        <% end %>\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#data-hn\').change(update_patient);\r\n        // show filter section\r\n        $(\'#block-filter\').hide();\r\n        $(\'#btn-show_filter\').click(function() {\r\n            // $(\'#block-filter\').show();\r\n            $(\'#block-filter\').fadeIn(\'slow\');\r\n        });\r\n        $(\'#btn-hide_filter\').click(function() {\r\n            $(\'#block-filter\').fadeOut(\'slow\');\r\n        })\r\n        \r\n        $(\"#fil-provider\").change(filter);\r\n        $(\"#fil-procedure\").change(filter);\r\n        $(\"#fil-visit\").change(filter);\r\n        $(\"#fil-status\").change(filter);\r\n        \r\n        // remove splash loading\r\n        $(\".se-pre-con\").fadeOut(\"slow\");\r\n    });\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2015-10-08 16:58:05','2015-10-08 16:58:05','index_bk',''),(1846,'print',533,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm_core/banner.png\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3><%=this.table_name.to_s.humanize%></h3>\r\n<%= this.display.html_safe %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div class=\"hideprint\">\r\n<%= link_to \'Back\', url(\'index\') %>\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2015-10-12 02:24:42','2015-10-12 02:24:42','print',''),(1851,'config',796,1,'[\r\n{:name=>\'Nurse Records\',:open=>true,:actions=>[\r\n{:name=>\'Consignment\',:service=>\'consignment\',:link=>\'../Consignment/index\',:remote=>false},\r\n{:name=>\'Pre Scope\',:service=>\'pre_scope\',:link=>\'../PreScope/index\',:remote=>false},\r\n{:name=>\'Intra Scope\',:service=>\'intra_scope\',:link=>\'../IntraScope/index\',:remote=>false},\r\n{:name=>\'Post Scope\',:service=>\'post_scope\',:link=>\'../PostScope/index\',:remote=>false}]},\r\n{:name=>\'Endoscopist Records\',:open=>true,:actions=>[\r\n{:name=>\'Colonosopy\',:service=>\'colonoscopy\',:link=>\'../Colonoscopy/index\',:remote=>false},\r\n{:name=>\'Gastroscopy\',:service=>\'gastroscopy\',:link=>\'../Gastroscopy/index\',:remote=>false},\r\n{:name=>\'Enteroscopy\',:service=>\'enteroscopy\',:link=>\'../Enteroscopy/index\',:remote=>false},\r\n{:name=>\'ERCP\',:service=>\'ercp\',:link=>\'../Ercp/index\',:remote=>false},\r\n{:name=>\'EUS\',:service=>\'eus_record\',:link=>\'../EusRecord/index\',:remote=>false},\r\n{:name=>\'Bronchoscopy\',:service=>\'bronchoscopy\',:link=>\'../Bronchoscopy/index\',:remote=>false}]},\r\n{:name=>\'ETC\',:open=>true,:actions=>[\r\n{:name=>\'Billing\',:service=>\'billing\',:link=>\'../Billing/index\',:remote=>false},\r\n{:name=>\'Pathology\',:service=>\'pathology\',:link=>\'../Pathology/index\',:remote=>false}]}]\r\n',NULL,NULL,NULL,'2015-10-12 16:33:30','2015-10-12 16:33:30','config',''),(1852,'document_name',798,1,'\'colonoscopy\'',NULL,NULL,NULL,'2015-10-13 02:42:28','2015-10-13 02:42:28',NULL,NULL),(1853,'document_name',799,1,'\'gastroscopy\'',NULL,NULL,NULL,'2015-10-13 02:48:26','2015-10-13 02:48:26',NULL,NULL),(1854,'document_name',800,1,'\'ercp\'',NULL,NULL,NULL,'2015-10-13 02:53:10','2015-10-13 02:53:10',NULL,NULL),(1857,'layout',796,4,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n		\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n		    <title><%=title%></title>\r\n\r\n				<script>\r\n					$(document).ready(function() {\r\n						//* show all elements & remove preloader\r\n						// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n						 // $(\"html\").removeClass(\"js\");\r\n					});\r\n				</script>\r\n		\r\n				 <style>\r\n    .w-box-content.cnt_a {background: #fff;}\r\n    .k-grid table {font-size: 1em;}\r\n.k-calendar .k-content {font-size: 1em;padding-top:5px;}\r\n.k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\nheight: 18px;}\r\n.field-data {\r\nwidth: 220px;}\r\n\r\ninput{\r\n    height:18px;\r\n}\r\n</style>\r\n		\r\n		\r\n    </head>\r\n    <body style=\"background:url(\'/esm/ehr/my_module/surgeons-bg.jpg\');padding:10px\">\r\n<a href=\"../../www/Home/index\">	\r\n<img src=\"/esm/ehr/my_module/lifescope.png\" width=\"200px\"></a>\r\n<span style=\"float:right;color:#efefef;font-size:1.2em\" >\r\n    <%= @current_user.login %> | <%=link_to \'Logout\',\'/user/logout\' %>\r\n</span>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n						<div class=\"span12\">\r\n							<ul class=\"dshb_icoNav tac\">\r\n								<li><a href=\"../Home/index\" style=\"background-image: url(/gebo/img/gCons/home.png)\"> Home</a></li>\r\n								<li><a href=\"../Appointment/index\" style=\"background-image: url(/gebo/img/gCons/calendar.png)\">Calendar</a></li>\r\n								<li><%= link_to \'Reports\',\"../Report/index\",:style=>\'background-image: url(/gebo/img/gCons/bar-chart.png)\' %></li>\r\n								<li><a href=\"../Setting/index\" style=\"background-image: url(/gebo/img/gCons/configuration02.png)\">Settings</a></li>\r\n				<li><a href=\"../Help/index\" style=\"background-image: url(/gebo/img/gCons/happy-face.png)\">Help</a></li>\r\n						 </ul>		\r\n			\r\n						</div>\r\n					</div>\r\n</hr>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12 w-box-content cnt_a\" style=\"padding:0px;\">\r\n<% if params[:service] == \'Report\'  %>\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <b>Report</b>\r\n                <span style=\"float:right\">\r\n                    <%= link_to \'Weekly\', \'weekly_report\', :class=>\'btn btn-mini btn-info\' %> \r\n                    <%= link_to \'Monthly\', \'case_report\', :class=>\'btn btn-mini btn-info\' %> \r\n                    <%= link_to \'Endoscopist\', \'endoscopist_report\', :class=>\'btn btn-mini btn-primary\' %> \r\n                    <%= link_to \'Procedure\', \'procedure_report\', :class=>\'btn btn-mini btn-gebo\' %> \r\n                    <%= link_to \'SSA\', \'total_ssa_report\', :class=>\'btn btn-mini btn-gebo\' %> \r\n                    <%= link_to \'ESD\', \'total_esd_report\', :class=>\'btn btn-mini btn-gebo\' %> \r\n                </span>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\" style=\"padding:10px\">\r\n                <%= yield %><%= yield :content%>\r\n            </div>\r\n        </div>\r\n<% else %>\r\n		    <%= yield %><%= yield :content%>\r\n<% end %>\r\n    </div>\r\n</div>\r\n     \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n     		<div id=\"context-menu\" class=\"accordion\">\r\n             <%= render :partial=>\'/layouts/context_menu\'%>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n			$(\'#search-field\').focus()\r\n		</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-10-14 17:29:26','2015-10-14 17:29:26','',''),(1858,'colono_reports',789,2,'<%\r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n \r\n\r\n\r\n   def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    @models = get_model\r\n\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    @m_patient= model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n%>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    v{\r\n        color:blue;\r\n    }\r\n</style>\r\n\r\n<%=form_for \'report\', :url=>\'colono_reports_partial\', :target=>\'_blank\' do |f| %>\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date  , :order=>[:day,:month,:year]%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n  <% if request.post? \r\n  \r\n  \r\n  \r\n  # select appointment by date\r\n  \r\n  all_app = @models[:appointment].collection.find({:date=>{\'$gte\'=>from_date,\'$lt\'=>to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n  \r\n  \r\n  # select pm by module_id of appointment\r\n  \r\n  all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n  m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n  \r\n  # select patients by patient_id of pm \r\n  all_patients = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'hn\'=>1}}).to_a\r\n  m_patients = bmap all_patients\r\n  \r\n  case_map = {}\r\n  map = {}\r\n  cols = {}\r\n  provider_map = {}\r\n  # for each forms prepare list of module_id \r\n  all_pm = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colono\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n  m_all_pm = bmap all_pm, \'module_id\'\r\n  \r\n  records = @models[:colono].collection.find({:_id=>{\'$in\'=>all_pm.collect{|i| i[\'module_id\']}}}).to_a\r\n  \r\n  for i in records\r\n    for j in i.keys\r\n        \r\n        cols[j] = 0 unless cols[j]\r\n        cols[j] += 1\r\n    \r\n    end\r\n  end\r\n  \r\n  ccols = cols.keys.sort{|a,b| cols[b]<=>cols[a] }\r\n  \r\n  %>\r\n  <%# ccols.collect{|i| \"\\\\#{i}<br/>\"}.join.html_safe %>\r\n  <%\r\n  ccols = %w{\r\n      schedule\r\n\r\ntype_of_sedation\r\nstudy_project\r\ntype_of_instrument\r\n\r\nclinical_indication\r\nother_indication_note\r\nindication_other\r\nindications_other\r\n\r\n\r\nanesthetic_drug_type\r\npethidine\r\npethidine_mg\r\npropofol\r\npropofol_mg\r\ndormicum\r\ndormicum_mg\r\nfentanyl\r\n\r\n\r\nfinal_diagnosis\r\n\r\nbowel_preperation_agent\r\nbowel_preperation_finding\r\n\r\n\r\nstart_time\r\nstop_time\r\n\r\nstart_procedural_date\r\nstart_procedure_date\r\nstart_procedural_time\r\nstop_procedural_date\r\nstop_procedure_date\r\nstop_procedural_time\r\nprocedural_time\r\n\r\nendoscopist\r\nassist1endoscopist\r\nassist2endoscopist\r\nrecorder\r\nnurse\r\nassist_1_nurse\r\nassist_2_nurse\r\n\r\napprove\r\nendoscopist_approve\r\ndate_approve\r\ntime_approve\r\n\r\nextendoscopist\r\n\r\n\r\ncecal_intubation_time\r\nwithdrawal_time\r\n\r\n\r\nfinding\r\nfindings\r\nfinding_other_detail\r\nabnormal_finding\r\nfinding_1_summary\r\nfinding_2_summary\r\nfinding_3_summary\r\nfinding_4_summary\r\nfinding_5_summary\r\nfinding_7_summary\r\nfinding_6_summary\r\nfinding_8_summary\r\nfinding_9_summary\r\n\r\n\r\nfinding_2\r\n\r\n\r\ndiagnosis_text\r\nadditional_diagnosis\r\ndiagnosis_group\r\ncomment\r\nintervention_group\r\nintervention_text\r\nintervention_summary\r\n\r\n\r\ncomplications\r\ncomplication_type\r\ncardiopulmonary_action\r\ncardiopulmonary_type\r\nbleeding_management\r\nperforation_type\r\nperforation_communicating_to\r\nperforation_location\r\nperforation_action\r\n\r\nintervention\r\n\r\nscope_pass_through\r\n\r\nimage\r\n\r\n\r\nfinding_3\r\nfinding_3_internal_size\r\nfinding_3_external_size\r\nfinding_3_location\r\nfinding_3_external_bleeding_stigmata\r\nfinding_3_internal_bleeding_stigmata\r\nfinding_4\r\nfinding_5\r\nfinding_6\r\n\r\nfinding_7_other\r\n\r\noperative_procedure\r\n\r\nop_polypectomy_result\r\nop_esd_specimen_size\r\nop_esd_result\r\nop_esd_pre_nj_volume\r\nop_esd_pre_inj_fluid\r\nop_stent_size\r\noperative\r\nop_sampling_lesion\r\nop_sampling_type\r\nop_polypectomy_method\r\nop_polypectomy_pre_injection\r\nop_polypectomy_pre_inj_fluid\r\nop_stent_result\r\nop_stent_type\r\nop_clipping_type\r\nop_esd_tool\r\nop_emr_specimen_size\r\nop_clipping_number\r\nop_emr_result\r\nop_clipping_result\r\nop_bipolar_result\r\nop_apc_result\r\nop_injection_material\r\nop_injection_volume\r\nop_injection_result\r\nop_emr_tool\r\nop_emr_pre_nj_volume\r\nop_polypectomy_pre_inj_volume\r\nop_emr_pre_inj_fluid\r\n\r\n\r\n\r\nfinal_sigmoid\r\nsigmoid_colitis_most_like_from\r\nfinal_sigmoid_other\r\nfinal_sigmoid_polyp_type\r\nfinal_sigmoid_type\r\nsigmoid_ulcer_most_like_from\r\nfinal_rectum_other\r\nfinal_rectum_polyp_type\r\nfinal_rectum\r\nfinal_anus_other\r\nfinal_descending\r\nfinal_anus_type\r\nfinal_anus\r\nfinal_descending_type\r\nfinal_descending_polyp_type\r\nfinal_descending_other\r\ndescending_colitis_most_like_from\r\ndescending_ulcer_most_like_from\r\nfinal_ascending_polyp_type\r\nfinal_transverse\r\nfinal_transverse_type\r\nrecommendation_note\r\nfinal_transverse_polyp_type\r\nperforation\r\nfinal_transverse_other\r\nconcentration\r\ntransverse_colitis_most_like_from\r\nbleeding_treatment\r\nintervertion_note\r\ntransverse_ulcer_most_like_from\r\nfinal_ascending\r\nhemo_concentration\r\nhemostatic_therapy\r\npolypectomy_with\r\ninterv_type\r\nfinal_ascending_type\r\ninterv\r\nterminal_ulcer_most_like_from\r\nterminal_colitis_most_like_from\r\nfinal_terminal_other\r\nfinal_terminal_polyp_type\r\nfinal_terminal_type\r\nfinal_terminal\r\ncecum_ulcer_most_like_from\r\ncecum_colitis_most_like_from\r\nfinal_cecum_other\r\nfinal_cecum_polyp_type\r\nfinal_cecum_type\r\nfinal_cecum\r\nascending_ulcer_most_like_from\r\nascending_colitis_most_like_from\r\nfinal_ascending_other\r\ninterv_success\r\nbleeding_treatment_type\r\nsedation_none\r\nterminal_most_likely_from\r\nrectum_most_likely_from\r\ncecum_most_likely_from\r\nascending_most_likely_from\r\ntransverse_most_likely_fro