  <% for i in ccols %>\r\n  <th><%= i %></th>\r\n  <% end %>\r\n  </tr>\r\n  <%\r\n  \r\n  # select provider of those records\r\n\r\n \r\n  list = records\r\n  index = 0\r\n  list.each do |i|\r\n     \r\n  \r\n    \r\n    pm = m_all_pm[i[\'_id\']][0]\r\n    patient = m_patients[pm[\'patient_id\']][0]\r\n    provider = nil\r\n    provider = m_providers[i[\'endoscopist\']][0]  if m_providers[i[\'endoscopist\']]\r\n    \r\n    @document = @current_project.get_document \'colono\'\r\n    @record = @models[:colono].find(i[\'_id\'])\r\n    \r\n    if pm and patient  and provider\r\n        \r\n        schedule = \'-\'\r\n        \r\n        schedule = tschedule[ i[\'schedule\']]\r\n        \r\n        %><tr><td><%=index+1%></td>\r\n        <td><%=\'\'%></td><td><%=i[\'created_at\'].strftime(\"%d-%m-%Y\") %></td><td><%=patient[\'hn\'] %></td><td><%=patient[\'first_name\'] %> <%=patient[\'last_name\']%></td><td><%= schedule %></td><td><%= provider[\'name\'] %></td>\r\n        <td style=\"width:300px\"><%= i[\'diagnosis_text\'].html_safe %></td>\r\n        <td style=\"width:300px\"><%= i[\'intervention_text\'].html_safe if i[\'intervention_text\'] %><%= i[\'intervention_summary\'].html_safe if i[\'intervention_summary\'] %></td>\r\n        \r\n  <% for j in ccols %>\r\n  <td><%=render_value j if i[j]%></td>\r\n  <% end %>\r\n        \r\n        </tr>\r\n        \r\n        \r\n        <%\r\n        \r\n        index+=1\r\n        \r\n \r\n       \r\n  end\r\n  \r\n  end\r\n  \r\n  %>\r\n  </table>\r\n  \r\n  \r\n  \r\n  <% end %>\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n',NULL,NULL,NULL,'2015-10-15 09:54:46','2015-10-15 09:54:46','colono_reports',''),(1859,'colono_reports_partial',789,3,'<%\r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n \r\n\r\n\r\n   def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    @models = get_model\r\n\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    @m_patient= model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n%>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    v{\r\n        color:blue;\r\n    }\r\n</style>\r\n\r\n\r\n\r\n  <% if request.post? \r\n  \r\n  \r\n  \r\n  # select appointment by date\r\n  \r\n  all_app = @models[:appointment].collection.find({:date=>{\'$gte\'=>from_date,\'$lt\'=>to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n  \r\n  \r\n  # select pm by module_id of appointment\r\n  \r\n  all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n  m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n  \r\n  # select patients by patient_id of pm \r\n  all_patients = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'hn\'=>1}}).to_a\r\n  m_patients = bmap 