 %>\r\n                if (status.toLowerCase() === \'cancelled\') {\r\n                    tmp.closest(\'tr\').addClass(\"cancel\");\r\n                } else {\r\n                    tmp.closest(\'tr\').removeAttr( \"class\" );\r\n                }\r\n                <% end %>\r\n                \r\n              })\r\n              .fail(function() {\r\n                alert( \"Update status fail. Please try again.\" );\r\n              })\r\n              .always(function() {\r\n                // alert( \"complete\" );\r\n              });\r\n            // console.log(jqxhr);\r\n	    }\r\n    }\r\n    function reset_locker() {\r\n        var url = \'../Locker/reset\'\r\n        if(confirm(\"Do you want to reset all locker system ?\")){\r\n		  //  window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n		  // id=oid&status=status&updated_by=cur_user\r\n		    jqxhr = $.ajax( url )\r\n              .done(function() {\r\n                alert( \"All locker reset.\" );\r\n              })\r\n              .fail(function() {\r\n                alert( \"Reset fail. Try again.\" );\r\n              })\r\n              .always(function() {\r\n                // alert( \"complete\" );\r\n              });\r\n            // console.log(jqxhr);\r\n	    }\r\n    }\r\n    $(document).ready(function() {\r\n        $(\'.status_cls\').change(update_status);\r\n        $(\'#reset\').click(reset_locker);\r\n    });\r\n    refresh();\r\n</script>\r\n<div class=\"alert \">\r\n\r\n<!--\r\nLinks : \r\n<%# link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%# link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%# link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%# link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%#link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n-->\r\nCopyright 2015 - E.S.M.Solution C