nheight: 18px;}\r\n.field-data {\r\nwidth: 220px;}\r\n\r\ninput{\r\n    height:18px;\r\n}\r\n</style>\r\n		\r\n		\r\n    </head>\r\n    <body style=\"background:url(\'/esm/ehr/my_module/surgeons-bg.jpg\');padding:10px\">\r\n<a href=\"../../www/Home/index\">	\r\n<img src=\"/esm/ehr/my_module/lifescope.png\" width=\"200px\"></a>\r\n<span style=\"float:right;color:#efefef;font-size:1.2em\" >\r\n    <%= @current_user.login %> | <%=link_to \'Logout\',\'/user/logout\' %>\r\n</span>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n						<div class=\"span12\">\r\n							<ul class=\"dshb_icoNav tac\">\r\n								<li><a href=\"../Home/index\" style=\"background-image: url(/gebo/img/gCons/home.png)\"> Home</a></li>\r\n								<li><a href=\"../Appointment/index\" style=\"background-image: url(/gebo/img/gCons/calendar.png)\">Calendar</a></li>\r\n								<li><%= link_to \'Reports\',\"../Report/index\",:style=>\'background-image: url(/gebo/img/gCons/bar-chart.png)\' %></li>\r\n								<li><a href=\"../Setting/index\" style=\"background-image: url(/gebo/img/gCons/configuration02.png)\">Settings</a></li>\r\n				<!--<li><a href=\"../Help/index\" style=\"background-image: url(/gebo/img/gCons/happy-face.png)\">Help</a></li>-->\r\n						 </ul>		\r\n			\r\n						</div>\r\n					</div>\r\n</hr>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\" style=\"padding:0px;\">\r\n<% if params[:service] == \'Report\'  %>\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Report</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\" style=\"padding:10px\">\r\n                <%= yield %><%= yield :content%>\r\n            </div>\r\n        </div>\r\n<% else %>\r\n				   <%= yield %><%= yield :content%>\r\n<% end %>\r\n    </div>\r\n</div>\r\n     \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n     		<div id=\"context-menu\" class=\"accordion\">\r\n             <%= render :partial=>\'/layouts/context_menu\'%>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n			$(\'#search-field\').focus()\r\n		</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2015-12-02 15:42:31','2015-12-02 15:42:31','lay',''),(1929,'index',829,2,'<%\r\n    module_name = @current_project.name\r\n    if params[:date]\r\n        session[module_name]={:date=>params[:date]}\r\n    end\r\n    if session[module_name]\r\n        params[:date] = session[module_name][:date]\r\n    end\r\n    unless params[:date]\r\n        params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n    end\r\n \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %><%= error%>\r\n    <%\r\n    session.delete :s_date\r\n    end\r\n     %>\r\n        <%\r\n    search_patient = false\r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n          end\r\n        session[:s_status] = s_status\r\n         session[:s_provider] = s_provider \r\n        \r\n    end\r\n    if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Add & Continue\"\r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n</script>\r\n<%\r\n        end\r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       <b>Home : <%= date.strftime(\'%d/%m/%Y\') %></b>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n            <div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>params[:opt], :html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\">Date : </label>\r\n                    <div class=\"field-input\" >\r\n                        <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\">HN : </label>\r\n                    <div class=\"field-input\">\r\n                        <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n                    </div>\r\n                </span>\r\n            \r\n                <span class=\"field-data\" style=\"margin-top:5px\"> \r\n                        <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                        <%=link_to \'Advanced Search\', \'javascript:void(0)\', :id=>\'btn-advanced_search\', :class=>\'btn\'%>\r\n                </span>\r\n                \r\n                <div class=\"clear\"></div>\r\n\r\n                <span class=\"field-data\">\r\n                    <label class=\"field-label\">&nbsp;</label>\r\n                    <div class=\"field-input\">\r\n                        <%=link_to \'Add Patient\', \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\',:style=>\'margin-top:10px\'%>\r\n                    </div>\r\n                </span>\r\n\r\n            <div class=\"clear\"></div>\r\n            \r\n            <script>\r\n                $(\'#search_hn\').focus();\r\n            </script>\r\n<% end %>\r\n        </div>\r\n        \r\n        </div>\r\n        <!--DATE : <%# date %>-->\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%#params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n# SEARCH SECTION    \r\n    if search_patient\r\n        \r\n        fields = {:hn=>s_hn, :first_name=>s_first_name}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n    \r\n        if keys.size>0\r\n            criteria = {\'$or\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n    \r\n        patients = patient_model.where(criteria).limit(20).all  \r\n        maps = module_model.all     :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n        aps = ap_model.find(maps.collect{|i| i.module_id})\r\n\r\n        if aps.count == 1 # and @current_role==\'developer\' \r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= aps.first.id.to_s %>\';\r\n</script>\r\n<%\r\n        end\r\n\r\n    elsif pad = params[:adv_pat]\r\n        adv = params[:advanced]\r\n        fields = {:provider=>adv[:provider], :visit_type=>adv[:visit_type], :indication=>adv[:indication], :procedure=>adv[:procedure]}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>v} if v and v!=\'\' \r\n        end\r\n        \r\n        if keys.size>0\r\n            criteria = {\'$and\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n        \r\n        # patient criteria\r\n        fs = {:first_name=>pad[:fname], :last_name=>pad[:lname]}\r\n        ks = []\r\n        fs.each_pair do |k, v|\r\n            ks <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n        if ks.size>0\r\n            cr = {\'$or\'=>ks}\r\n        else\r\n            cr ={}\r\n        end\r\n        \r\n        a_app = []\r\n        if !criteria.empty?\r\n            a_app = ap_model.where(criteria).all\r\n        end\r\n        \r\n        a_pat = []\r\n        if !cr.empty?\r\n            a_pat = patient_model.where(cr).all\r\n        end\r\n        \r\n        if !a_app.empty? and cr.empty?\r\n            aps = a_app\r\n        elsif a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(maps.collect{|i| i.module_id})\r\n        elsif !a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(a_app.collect{|i|i.id} & maps.collect{|i| i.module_id})\r\n        else\r\n            aps = ap_model.limit(20).all\r\n        end\r\n    else\r\n    \r\n        conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n        if s_provider and s_provider !=\'\'\r\n            conds.merge! :provider=>s_provider \r\n        end\r\n\r\n        if s_status and s_status != \"\"\r\n            conds.merge! :status=>s_status \r\n        end\r\n    \r\n        aps = ap_model.all(conds)\r\n\r\n    end\r\n     \r\n         \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\") if patient\r\n         public_id = \'-\'\r\n         bdate = i.date.strftime(\'%d/%m/\').to_s + (i.date.strftime(\'%Y\').to_i + 543).to_s\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id}\"),\r\n         :provider=>provider_name,:date=>i.date.strftime(\'%d/%m/%Y\'),:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type, :patient_id=>patient.id\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{date hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    \r\n        labels = {:no=>\'No.\', :date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Action\', :procedure=>\'Procedure\' }\r\n    \r\n    %>\r\n<% if true %>\r\n<%\r\n        app_a = []\r\n        app_c = []\r\n        aps.each do |i|\r\n            if i[:status] == \'Completed\'\r\n                app_c << i\r\n            else\r\n                app_a << i\r\n            end\r\n        end\r\n%>\r\n<div id=\'default-panel\' style=\'padding:5px\'>\r\n    <div class=\"tabbable\">\r\n        <ul class=\"nav nav-tabs\">\r\n            <li class=\"active\"><a href=\"#appointed\" data-toggle=\"tab\">Appointed (<%= app_a.count %>)</a></li>\r\n            <li><a href=\"#completed\" data-toggle=\"tab\">Completed (<%= app_c.count %>)</a></li>\r\n        </ul>\r\n        <div class=\"tab-content\">\r\n            <div class=\"tab-pane active\" id=\"appointed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_a,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n            <div class=\"tab-pane\" id=\"completed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_c,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<% end %>\r\n\r\n<% if false %>\r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    # out[0] = count.to_s+\".\"\r\n                    out[0] = link_to(count.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\").html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n        </div>\r\n<% end %>        \r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n <script>\r\n function change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"<%=params[:opt]%>?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n\r\n<% if false %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Encounter</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n\r\n    \r\n   \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n<% end  %>\r\n<% if false %>\r\n<div class=\"alert \">\r\n<%# link_to \'Total Status\',\'total_status?print[date]=\'+params[:date], :target=>\'_blank\' %>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<!--<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date],class: \'btn btn-mini\' %> |-->\r\n<%= link_to \'Status Feed\',\'total_status?print[date]=\'+params[:date],class: \'btn btn-mini\', :target=>\'_blank\' %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date],class: \'btn btn-mini\' %> | \r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date],class: \'btn btn-mini\' %> |\r\n</div>\r\n<% end %>\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n<%\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"myModal2\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Modal header</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n									Lorem ipsum dolor sit amet, consectetur adipiscing elit. Pellentesque non elit tellus, eleifend varius erat. Lorem ipsum dolor sit amet, consectetur adipiscing elit. In bibendum laoreet ante sodales elementum. Nullam varius interdum est, at ornare quam aliquam eu. Nulla ultricies commodo leo sit amet vulputate.\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n							</div>\r\n	\r\n<div class=\"modal hide fade\" id=\"modal2\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Advanced Search</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n        \r\n<%= form_for :advanced , :url=>params[:opt] do |f| %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name  : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[first_name]\" id=\"data-fname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[last_name]\" id=\"data-lname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <%= f.submit \'Search\', :class=>\'btn btn-success\' %>\r\n                <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a> \r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n							\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                <br/>\r\n                <div id=\"patient_msg\"></div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Add & Continue\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n</script>\r\n\r\n<script>\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#data-hn\').change(update_patient);\r\n    });\r\n</script>',NULL,NULL,NULL,'2015-12-02 15:43:13','2015-12-02 15:43:13','index',''),(1930,'colono_bowel',789,2,'<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n		width:100px\r\n    }\r\n</style>\r\n<%\r\n    report = [\r\n            [\'Bowel Report\', \'bowel\'],\r\n            [\'Screening CRC - Poylp Report\', \'spolyp\'],\r\n            [\'Iron deficiency anemia (colono)\', \'iron-colo\'],\r\n            [\'Iron deficiency anemia (gastro)\', \'iron-gast\'],\r\n            [\'SpyGlass (ERCP)\', \'spyglass\']\r\n        ]\r\n%>\r\n<%= form_for :adv_search,:url=>\'colono_bowel_partial?update=result-panel\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n	    <span class=\"field-data\"> \r\n			<label class=\"field-label\">Start Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :sdate, :value=>\'\',:id=>\'sdate\',:style=>\"width:100%\"%></div>\r\n		</span> \r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">End Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :edate, :value=>\'\',:id=>\'edate\',:style=>\"width:100%\"%></div>\r\n		</span>\r\n		<span class=\'field-data\' style=\'width:450px\'>\r\n		    <label class=\'field-label\'style=\'width:100px\'>Report Output : </label>\r\n		    <div class=\'field-input\' style=\'width:250px\'><%= f.select :report, report, include_blank: false %></div>\r\n		</span>\r\n		<span class=\"field-data\">\r\n		    <div class=\"field-input\"><%=f.submit \'Submit\', :class=>\'btn btn-success\'%> </div>\r\n		</span>\r\n<script>\r\n    $(\"#sdate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n    $(\"#edate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n</script>\r\n<% end %>\r\n<div class=\'clear\'></div>\r\n<br/>\r\n<div id=\'result-panel\'></div>\r\n',NULL,NULL,NULL,'2015-12-03 04:09:50','2015-12-03 04:09:50','colono_bowel',''),(1931,'colono_bowel_partial',789,3,'<%\r\n    tb = Time.now\r\n    rs = {}\r\n    cond = {}\r\n    \r\n    report = \'\'\r\n    if q = params[:adv_search]\r\n        q[:sdate] = Time.strptime(q[:sdate], \"%d/%m/%Y\")\r\n        q[:edate] = Time.strptime(q[:edate], \"%d/%m/%Y\")\r\n        \r\n        report = q[:report]\r\n        \r\n        cond[:start_procedural_date] = {\'$gte\'=>q[:sdate].beginning_of_day,\'$lt\'=>q[:edate].end_of_day}\r\n        res = []\r\n        if report == \'bowel\'\r\n            res = get_model[:colono].where(cond).all.group_by{|i| i[:start_procedural_date].strftime(\'%m/%y\')}\r\n        elsif report == \'spolyp\'\r\n            tmp = get_model[:colono].collection.find(cond,{:fields=>{\'start_procedural_date\'=>1,\'diagnosis_group\'=>1,\'clinical_indication\'=>1}}).to_a\r\n            tmp.each do |i|\r\n                if !i[\'diagnosis_group\'].nil?\r\n                    # indication\r\n                    ind = i[\'clinical_indication\'].split(\'|\')\r\n                    dx = i[\'diagnosis_group\'].split(\'|\')\r\n                    \r\n                    if dx.include? \'1\' and ind.include? \'5\'\r\n                        res << i\r\n                    end\r\n                end\r\n            end\r\n            res = res.group_by{|i| i[\'start_procedural_date\'].strftime(\'%m-%y\')}\r\n        elsif report == \'iron-colo\'\r\n            tmp = get_model[:colono].collection.find(cond,{:fields=>{\'start_procedural_date\'=>1,\'diagnosis_group\'=>1,\'clinical_indication\'=>1}}).to_a\r\n            tmp.each do |i|\r\n                if !i[\'diagnosis_group\'].nil?\r\n                    # indication\r\n                    ind = i[\'clinical_indication\'].split(\'|\')\r\n                    dx = i[\'diagnosis_group\'].split(\'|\')\r\n                    \r\n                    if ind.include? \'3\'\r\n                        res << i\r\n                    end\r\n                end\r\n            end\r\n            res = res.group_by{|i| i[\'start_procedural_date\'].strftime(\'%m-%y\')}\r\n            # res = tmp\r\n        elsif report == \'iron-gast\'\r\n            tmp = get_model[:gastro].collection.find(cond,{:fields=>{\'start_procedural_date\'=>1,\'diagnosis_group\'=>1,\'clinical_indication\'=>1}}).to_a\r\n            tmp.each do |i|\r\n                if !i[\'diagnosis_group\'].nil?\r\n                    # indication\r\n                    ind = i[\'clinical_indication\'].split(\'|\')\r\n                    dx = i[\'diagnosis_group\'].split(\'|\')\r\n                    \r\n                    if ind.include? \'7\'\r\n                        res << i\r\n                    end\r\n                end\r\n            end\r\n            res = res.group_by{|i| i[\'start_procedural_date\'].strftime(\'%m-%y\')}\r\n        elsif report == \'spyglass\'\r\n            \r\n            ss = []\r\n            fs = %w{finding_6_summary finding_8_summary finding_9_summary finding_other_detail diagnosis_text intervention_text intervention_summary}\r\n            fs.each do |i|\r\n                x = {}\r\n                x[i] = {\'$regex\' => \'spy\\*glass|spy\\*bite\', \'$options\' => \'i\'}\r\n                ss << x\r\n            end\r\n            \r\n            cond[\'$or\'] = ss\r\n            \r\n            # x[:finding_6_summary] = /^spy$/i\r\n            tmp = get_model[:ercp].collection.find(cond,{:fields=>{\'start_procedural_date\'=>1,\'diagnosis_group\'=>1,\'clinical_indication\'=>1}}).to_a\r\n            \r\n            res = tmp.group_by{|i| i[\'start_procedural_date\'].strftime(\'%m-%y\')}\r\n        end\r\n        \r\n        \r\n        rs = res\r\n    end\r\n    # bowel_preperation_finding\r\n    \r\n    bowel_map = {\'0\'=>\'Excellent\', \'1\'=>\'Good\', \'2\'=>\'Fair\', \'3\'=>\'Poor\'}\r\n    \r\n%>\r\n<%\r\n    if rs.count != 0 and report == \'bowel\'\r\n%>\r\n<br/>\r\n<table class=\"table table-bordered\">\r\n<thead>\r\n    <tr>\r\n        <th>Month/Year</th>\r\n        <th>Excellent</th>\r\n        <th>Good</th>\r\n        <th>Fair</th>\r\n        <th>Poor</th>\r\n        <th>Sum</th>\r\n    </tr>\r\n</thead>\r\n<tbody>\r\n<%\r\n        rs.each do |k,v|\r\n            x = v.group_by{|i| i[:bowel_preperation_finding]}\r\n            a = []\r\n            0.upto(3) do |i|\r\n                a[i] = x[i.to_s] ? x[i.to_s].count : 0\r\n        \r\n            end\r\n%>\r\n    <tr>\r\n        <td><%= k %></td>\r\n        <td><%= a[0] %></td>\r\n        <td><%= a[1] %></td>\r\n        <td><%= a[2] %></td>\r\n        <td><%= a[3] %></td>\r\n        <td><%= a.sum %></td>\r\n    </tr>\r\n<%\r\n        end\r\n%>\r\n</tbody>\r\n</table>\r\n<%\r\n    elsif rs.count != 0 and (report == \'spolyp\' or report == \'iron-colo\' or report == \'iron-gast\' or report == \'spyglass\')\r\n%>\r\n<br/>\r\n<%# rs.to_json.html_safe %>\r\n<div class=\'span4\'>\r\n<table class=\"table table-bordered\" style=\'width:100%\'>\r\n    <thead>\r\n        <tr>\r\n            <th>Month-Year</th>\r\n            <th>Total</th>\r\n            <th>Action</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n<%\r\n        sum = 0\r\n        rs.each do |k, v|\r\n            sum += v.count\r\n%>\r\n        <tr>\r\n            <td><%= k %></td>\r\n            <td><%= v.count %></td>\r\n            <td><%= link_to \'Result\', \"javascript:view(\'\\\\#{k}\')\", :class=>\'btn btn-info btn-mini\' %></td>\r\n        </tr>\r\n<%\r\n        end\r\n%>\r\n        <tr>\r\n            <td>Total</td>\r\n            <td><%= sum %></td>\r\n            <td></td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n</div>\r\n\r\n<div id=\'patient-result\' class=\'span8\'>\r\n    \r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    m_pat = model[:patient]\r\n    m_pat_mod = model[:patient_module]\r\n    \r\n    rs.each do |k,v|\r\n        vid = v.collect{|i| i[\'_id\']}\r\n        \r\n        tmp = m_pat_mod.where(:module_id=>vid).all\r\n        \r\n        pid = tmp.collect{|i| i[:patient_id]}\r\n        pat = m_pat.collection.find({\'_id\'=>{\'$in\'=>pid}},{:fields=>{\'hn\'=>1, \'prefix_name\'=>1,\'first_name\'=>1,\'last_name\'=>1}}).to_a\r\n        \r\n        g_pat = pat.group_by{|i| i[\'_id\']}\r\n%>\r\n    <div id=\'<%= k %>\' style=\'display:none\'>\r\n    <h3><%= k %></h3>\r\n    <table class=\"table table-bordered\" style=\'width:100%\'>\r\n        <thead>\r\n            <tr>\r\n                <th>HN</th>\r\n                <th>Name</th>\r\n                <th>Date</th>\r\n                <th>View</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n<%\r\n        tmp.each do |i|\r\n            pp = g_pat[i[:patient_id]][0]\r\n            pn = \"\\\\#{pp[\'prefix_name\']}\\\\#{pp[\'first_name\']} \\\\#{pp[\'last_name\']}\"\r\n            # pn = pp.to_json.html_safe\r\n            md = i[:module_name].split(\'#\')[1].humanize\r\n%>\r\n            <tr>\r\n                <td><%= pp[\'hn\'] %></td>\r\n                <td><%= pn %></td>\r\n                <td><%= i[:created_at].strftime(\'%d/%m/%Y\') %></td>\r\n                <td><%= link_to \'Detail\', \"../\\\\#{md}/show?id=\\\\#{i.id}&return=../Home/index\", :target=>\'_blank\', :class=>\'btn btn-mini btn-gebo\' %></td>\r\n            </tr>\r\n<%      end %>            \r\n        </tbody>\r\n    </table>\r\n    </div>\r\n<%  end %>\r\n    \r\n</div>\r\n\r\n<script>\r\n    function view(tb) {\r\n        $(\"#\" + tb).show();\r\n    }\r\n</script>\r\n\r\n<div class=\'clear\'></div>\r\n<%\r\n    else\r\n%>\r\n<b>No Result Found.</b>\r\n<%\r\n    end\r\n%>\r\n<br/>\r\nProcessing time : <%= Time.now - tb %>\r\n<hr/>',NULL,NULL,NULL,'2015-12-03 04:21:00','2015-12-03 04:21:00','colono_bowel_partial',''),(1932,'monthly_report_search',805,3,'<%=form_for :query, :url=>\'monthly_report_result?update=result-area\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n            \r\n           \r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">Start Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :sdate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'start-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">End Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :edate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'end-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.submit \'Submit\', :class=>\'btn btn-success\' %>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\" style=\'float:right\'> \r\n                                    <div class=\"field-input\" style=\"float:right\">\r\n                                        <%= link_to \'Print\', \'javascript:void(0)\', :style=>\'float:right;margin-top:5px\', :onclick=>\'javascript:window.print()\', :class=>\'btn btn-info\' %>\r\n                                    </div>\r\n                                </span>\r\n                                \r\n<script>\r\n    $(\"#start-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.at_beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n	$(\"#end-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.at_end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2015-12-04 15:36:12','2015-12-04 15:36:12','monthly_report_search',''),(1933,'monthly_report_result_office',805,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.init %>\r\n<%\r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    if q = params[:query]\r\n        sdate = q[:sdate]\r\n        edate = q[:edate] \r\n        rs = get_appointment_by_date(sdate, edate)\r\n        app_ids = rs.collect{|i| i.id.to_s}\r\n        pat_mod = get_patient_module_by_appointment_ids(app_ids)\r\n        par_ids = pat_mod.collect{|i| i.id.to_s}\r\n        pat_mod = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#post_anesthetic\")\r\n        xxx = get_module_id_array(pat_mod)\r\n        res = @models[:post_anesthetic].find(xxx)\r\n        \r\n        res.each do |i|\r\n            # anesth official and non-official time\r\n            at_dur = i[:anesthetic_duration] ? i[:anesthetic_duration].to_i : 0\r\n            at_off = i[:anesthetic_official_duration] ? i[:anesthetic_official_duration].to_i : 0\r\n            at_non = i[:anesthetic_non_official_duration] ? i[:anesthetic_non_official_duration].to_i : 0\r\n            \r\n            if at_dur < 30\r\n                @res_mon[:at_dur][0] += 1\r\n            elsif at_dur >= 30 and at_dur <=60\r\n                @res_mon[:at_dur][1] += 1\r\n            elsif at_dur > 60 and at_dur <= 120\r\n                @res_mon[:at_dur][2] += 1\r\n            elsif at_dur > 120 and at_dur <= 240\r\n                @res_mon[:at_dur][3] += 1\r\n            else\r\n                @res_mon[:at_dur][4] += 1\r\n            end\r\n            \r\n            if at_off > 0\r\n                @res_mon[:at_off] += 1\r\n            end\r\n            if at_non > 0\r\n                @res_mon[:at_non] += 1\r\n            end\r\n            \r\n            # anesth technique\r\n            an_tec = (i[:anesth_technique] == \'\' or i[:anesth_technique] == nil) ? \'0\' : i[:anesth_technique]\r\n            @res_mon[:an_tec][an_tec] += 1\r\n            \r\n            # case_type\r\n            case_type = (i[:case_type] ==\'\' or i[:case_type] == nil) ? \'0\' : i[:case_type]\r\n            @res_mon[:case_type][case_type] += 1\r\n            \r\n            # asa status and asa type\r\n            asa_status = (i[:asa_status] == \'\' or i[:asa_status] == nil) ? \'0\' : i[:asa_status]\r\n            asa_type = i[:asa_type] == \'\' ? \'-\' : i[:asa_type]\r\n            @res_mon[:asa_status][asa_status] += 1\r\n            @res_mon[:asa_type][asa_type] += 1\r\n            \r\n            # recovery place\r\n            rr = i[:recovery_place]\r\n            ar << rr\r\n            if rr == \'2\'\r\n                @res_mon[:rr] += 1\r\n            end\r\n        end\r\n        @res_mon[:count] = res.count\r\n        @res_mon[:sdate] = sdate\r\n        @res_mon[:edate] = edate\r\n        \r\n        session[:res_mon] = @res_mon\r\n    end\r\n%>\r\n<% if @res_mon.count == 0 %>\r\n<center><b>No Result Found</b></center>\r\n<% else %>\r\n<style>\r\n<!--\r\n /* Font Definitions */\r\n @font-face\r\n	{font-family:Wingdings;\r\n	panose-1:5 0 0 0 0 0 0 0 0 0;}\r\n@font-face\r\n	{font-family:\"Cordia New\";\r\n	panose-1:2 11 3 4 2 2 2 2 2 4;}\r\n@font-face\r\n	{font-family:\"Cordia New\";\r\n	panose-1:2 11 3 4 2 2 2 2 2 4;}\r\n@font-face\r\n	{font-family:Calibri;\r\n	panose-1:2 15 5 2 2 2 4 3 2 4;}\r\n@font-face\r\n	{font-family:\"TH SarabunPSK\";\r\n	panose-1:2 11 5 0 4 2 0 2 0 3;}\r\n /* Style Definitions */\r\n p.MsoNormal, li.MsoNormal, div.MsoNormal\r\n	{margin-top:0in;\r\n	margin-right:0in;\r\n	margin-bottom:10.0pt;\r\n	margin-left:0in;\r\n	line-height:115%;\r\n	font-size:11.0pt;\r\n	font-family:\"Calibri\",\"sans-serif\";}\r\np.MsoListParagraph, li.MsoListParagraph, div.MsoListParagraph\r\n	{margin-top:0in;\r\n	margin-right:0in;\r\n	margin-bottom:10.0pt;\r\n	margin-left:.5in;\r\n	line-height:115%;\r\n	font-size:11.0pt;\r\n	font-family:\"Calibri\",\"sans-serif\";}\r\np.MsoListParagraphCxSpFirst, li.MsoListParagraphCxSpFirst, div.MsoListParagraphCxSpFirst\r\n	{margin-top:0in;\r\n	margin-right:0in;\r\n	margin-bottom:0in;\r\n	margin-left:.5in;\r\n	margin-bottom:.0001pt;\r\n	line-height:115%;\r\n	font-size:11.0pt;\r\n	font-family:\"Calibri\",\"sans-serif\";}\r\np.MsoListParagraphCxSpMiddle, li.MsoListParagraphCxSpMiddle, div.MsoListParagraphCxSpMiddle\r\n	{margin-top:0in;\r\n	margin-right:0in;\r\n	margin-bottom:0in;\r\n	margin-left:.5in;\r\n	margin-bo