t\'>(&#3619;&#3634;&#3618;)</span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span lang=TH class=\'sarabun-font\'>งานดูแลผู้ป่วยในห้องพักฟื้น</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:rr] %></v></span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span lang=TH class=\'sarabun-font\'>จำนวนผู้เข้ารับบริการ</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:count] %></v></span></p>\r\n  </td>\r\n </tr>\r\n</table>\r\n\r\n<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;text-align:\r\njustify;text-justify:inter-cluster;line-height:normal\'><span lang=TH\r\nstyle=\'font-size:16.0pt;font-family:\"TH SarabunPSK\",\"sans-serif\"\'>&nbsp;</span></p>\r\n<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;text-align:\r\njustify;text-justify:inter-cluster;line-height:normal\'><span lang=TH\r\nstyle=\'font-size:16.0pt;font-family:\"TH SarabunPSK\",\"sans-serif\"\'><i>Printed by <v><%= @map_login[@current_user].nil? ? \'Unknown\' : @map_login[@current_user] %> (<%= @current_user %>)</v> at <v><%= Time.now.strftime(\'%d/%m/%Y %H:%M\') %></v> </i></span></p>\r\n<hr/>\r\n<% if @current_role==\'developer\' %>\r\n<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;text-align:\r\njustify;text-justify:inter-cluster;line-height:normal\'><span lang=TH\r\nstyle=\'font-size:16.0pt;font-family:\"TH SarabunPSK\",\"sans-serif\"\'>Processing Time : <%= Time.now - tb %></span></p>\r\n<% end # role %>\r\n</div>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2015-12-04 15:48:11','2015-12-04 15:48:11','monthly_report_result_office',''),(1934,'layout',586,4,'<%=default_layout%>',NULL,NULL,NULL,'2015-12-04 17:29:44','2015-12-04 17:29:44','',''),(1935,'temp',805,3,'<%= render :inline=>this.init %>\r\n<% \r\n    today = Time.now.strftime(\'%Y%m%d\')\r\n    yesterday = (Time.now + 1.month).yesterday.strftime(\'%Y%m%d\')\r\n%>\r\n<%= today %> - <%= yesterday %>\r\n<br/>\r\n<%= today > yesterday %> | <%= today == yesterday %> | <%= today < yesterday %>\r\n<hr/>\r\n<%= link_to \'excel\', \'excel?content_type=application/xml\', :target=>\'_blank\' %>',NULL,NULL,NULL,'2015-12-05 11:11:54','2015-12-05 11:11:54','temp',''),(1936,'daily_report_search',805,3,'<%=form_for :query, :url=>\'daily_report_result?update=result-area\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n            \r\n           \r\n                                <span class=\"field-data\" style=\'width:300px\'> \r\n                                    <label class=\"field-label\" style=\'width:150px\'>Operation Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :sdate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'start-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.submit \'Submit\', :class=>\'btn btn-success\' %>\r\n                                    </div>\r\n                                </span>\r\n<script>\r\n    $(\"#start-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.yesterday.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2015-12-05 15:38:05','2015-12-05 15:38:05','daily_report_search',''),(1937,'daily_report_result',805,3,'<% \r\n    tb = Time.now \r\n    \r\n    def map_parent_object(m_arr = [])\r\n        rs = {}\r\n        m_arr.each do |i|\r\n            rs[i[:parent_id].to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n%>\r\n<%= render :inline=>this.init %>\r\n<%\r\n    rs = {}\r\n    res = {}\r\n    ars = []\r\n    pat_mod = {}\r\n    app_date = Time.now\r\n    if q = params[:query]\r\n        sdate = q[:sdate]\r\n        edate = q[:sdate]\r\n        app_date = sdate\r\n        \r\n        rs = get_appointment_by_date(sdate, edate).sort_by{|i|  (i[:start] == \'\' or i[:start] == nil) ? \'00:00\' : i[:start].strftime(\'%H:%M\')}\r\n        app_ids = rs.collect{|i| i.id.to_s}\r\n        pat_mod = get_patient_module_by_appointment_ids(app_ids)\r\n        par_ids = pat_mod.collect{|i| i.id.to_s}\r\n        pat_ids = pat_mod.collect{|i| i[:patient_id].to_s}\r\n        mod_pre = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#pre_anesthetic\")\r\n        mod_pos = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#post_anesthetic\")\r\n        ids_pre = get_module_id_array(mod_pre)\r\n        ids_pos = get_module_id_array(mod_pos)\r\n        a_pre = @models[:pre_anesthetic].find(ids_pre)\r\n        a_pos = @models[:post_anesthetic].find(ids_pos)\r\n        \r\n        a_pat = @m_pat.find(pat_ids)\r\n        \r\n        par_app = get_module_id_map(pat_mod)\r\n        par_pre = map_parent_object(mod_pre)\r\n        par_pos = map_parent_object(mod_pos)\r\n        map_pre = get_map(a_pre)\r\n        map_pos = get_map(a_pos)\r\n        \r\n        map_pat = get_map(a_pat)\r\n        map_ward = get_map(@models[:ward].all)\r\n        # map_room = get_map(@models[:or_room].all)\r\n        \r\n        map_anes_tech = {\'\'=>\'Undefined\',\'1\'=>\'General anesthesia (balanced technique)\', \'2\'=>\'General anesthesia (Inhalation technique)\',\'3\'=>\'General anesthesia (TIVA)\',\'4\'=>\'Monitor anesthetic care\',\'5\'=>\'Regional anesthesia\',\'6\'=>\'Nerve Block\',\'7\'=>\'Combined general anesthesia and nerve block\',\'8\'=>\'Combined general anesthesia and regional anesthesia\',\'9\'=>\'GA due to RA/Nerve block fail\'}\r\n        map_pacu = {nil=>\'Undefined\', \'\'=>\'Undefined\',\'1\'=>\'OR\',\'2\'=>\'RR\',\'3\'=>\'WARD\',\'4\'=>\'ICU\'}\r\n        \r\n        res = par_pre\r\n        rs.each do |i|\r\n            tmp = {}\r\n            pm_app = par_app[i.id.to_s]\r\n            # tmp[:par_id] = par_id.id\r\n            pm_pre = par_pre[pm_app.id.to_s]\r\n            pm_pos = par_pos[pm_app.id.to_s]\r\n            \r\n            if  pm_pos.nil?\r\n                next\r\n            end\r\n            \r\n            # patient info\r\n            pat_id = pm_app[:patient_id].to_s\r\n            pat = map_pat[pat_id]\r\n            \r\n            tmp[:hn] = pat[:hn]\r\n            tmp[:name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]}  \\\\#{pat[:last_name]}\"\r\n            \r\n            today = i[:date]\r\n            if pat[:birth_date]\r\n                d = Date.new(today.year, pat[:birth_date].month,  pat[:birth_date].day)\r\n                age = d.year - pat[:birth_date].year - (d > today ? 1 : 0)\r\n                tmp[:age] = age\r\n            else\r\n                tmp[:age] = \'-\'\r\n            end\r\n            \r\n            # appointment\r\n            tmp[:diag] = i[:diagnosis]\r\n            tmp[:operation] = i[:operation]\r\n            tmp[:ward] = (i[:ward]==\'\' or i[:ward].nil?) ? \'N/A\' : map_ward[i[:ward]][:name]\r\n            tmp[:surgeon] = (i[:surgeon]==\'\' or i[:surgeon].nil?) ? \'N/A\' : @provider[i[:surgeon]]\r\n            tmp[:ast_surgeon] = (i[:assist]==\'\' or i[:assist].nil?) ? \'N/A\' : @provider[i[:assist]]\r\n            \r\n            # anesth team\r\n            pre = !pm_pre.nil? ? map_pre[pm_pre[:module_id].to_s] : nil\r\n            pos = map_pos[pm_pos[:module_id].to_s]\r\n            # tmp[:debug] = \"PRE : \\\\#{pre.to_json.html_safe}<br/>POS : \\\\#{pos.to_json.html_safe}\"\r\n            \r\n            if pre\r\n                tmp[:team_pre_1] = (pre[:anesthesiologist]==\'\' or pre[:anesthesiologist].nil?) ? \'N/A\' : @provider[pre[:anesthesiologist].to_s]\r\n                tmp[:team_pre_2] = (pre[:nurse]==\'\' or pre[:nurse].nil?) ? \'N/A\' : @provider[pre[:nurse].to_s]\r\n            else\r\n                tmp[:team_pre_1] = \'N/A\'\r\n                tmp[:team_pre_2] = \'N/A\'\r\n            end\r\n            \r\n            tmp[:team_pos_1] = (pos[:anesthesiologist]==\'\' or pos[:anesthesiologist].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist].to_s]\r\n            tmp[:team_pos_2] = (pos[:nurse_anesthetist]==\'\' or pos[:nurse_anesthetist].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetist].to_s]\r\n            \r\n            # intra-op\r\n            tmp[:dur_time] = \'N/A\'\r\n            tmp[:dur_anesthesiologist] = \'N/A\'\r\n            tmp[:dur_anesthetist] = \'N/A\'\r\n            dur_off = (pos[:anesthetic_official_duration]==\'\' or pos[:anesthetic_official_duration].nil?) ? 0 : pos[:anesthetic_official_duration].to_i\r\n            dur_non = (pos[:anesthetic_non_official_duration]==\'\' or pos[:anesthetic_non_official_duration].nil?) ? 0 : pos[:anesthetic_non_official_duration].to_i\r\n            if dur_non==0 and dur_off > 0\r\n                ds = pos[:anesthetic_official_date_start].strftime(\'%d/%m/%Y\')\r\n                de = pos[:anesthetic_official_date_end].strftime(\'%d/%m/%Y\')\r\n                ts = pos[:anesthetic_official_time_start].strftime(\'%H:%M\')\r\n                te = pos[:anesthetic_official_time_end].strftime(\'%H:%M\')\r\n                \r\n                tmp[:dur_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{dur_off} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                tmp[:dur_anesthetist] = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n                \r\n                tmp[:dur_anesthesiologist] = \"\\\\#{tmp[:dur_anesthesiologist]} (official time)\"\r\n                tmp[:dur_anesthetist] = \"\\\\#{tmp[:dur_anesthetist]} (official time)\"\r\n            elsif dur_non > 0 and dur_off==0\r\n                ds = pos[:anesthetic_nonofficial_date_start].strftime(\'%d/%m/%Y\')\r\n                de = pos[:anesthetic_nonofficial_date_end].strftime(\'%d/%m/%Y\')\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\')\r\n                te = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\')\r\n                \r\n                tmp[:dur_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{dur_non} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                tmp[:dur_anesthetist] = \"\\\\#{a1}, \\\\#{a2}\"\r\n                \r\n                tmp[:dur_anesthesiologist] = \"\\\\#{tmp[:dur_anesthesiologist]} (non-official time)\"\r\n                tmp[:dur_anesthetist] = \"\\\\#{tmp[:dur_anesthetist]} (non-official time)\"\r\n            elsif dur_non > 0 and dur_off > 0\r\n                ds_off = pos[:anesthetic_official_date_start]\r\n                de_off = pos[:anesthetic_official_date_end]\r\n                ds_non = pos[:anesthetic_nonofficial_date_start]\r\n                de_non = pos[:anesthetic_nonofficial_date_end]\r\n                \r\n                ts_off = pos[:anesthetic_official_time_start].strftime(\'%H:%M\')\r\n                te_off = pos[:anesthetic_official_time_end].strftime(\'%H:%M\')\r\n                ts_non = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\')\r\n                te_non = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\')\r\n                \r\n                ds = ds_off\r\n                de = de_non\r\n                ts = ts_off\r\n                te = te_non\r\n                if ds_off == ds_non and de_off == de_non\r\n                    if ts_non < ts_off\r\n                        ts = ts_non\r\n                        te = te_off\r\n                    end\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"    \r\n                elsif de_non > ds_off\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"    \r\n                elsif ds_non < de_off\r\n                    ds = ds_non\r\n                    de = de_off\r\n                    ts = ts_non\r\n                    te = te_off\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"    \r\n                else\r\n                    tmp[:dur_time] = \"official time : (\\\\#{ds_off} \\\\#{ts_off} - \\\\#{de_off} \\\\#{te_off}) / non-official time : (\\\\#{ds_non} \\\\#{ts_non} - \\\\#{de_non} \\\\#{te_non}) [\\\\#{dur_off + dur_non} mins] \"\r\n                end\r\n\r\n                off_a0 = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                off_a1 = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n                non_a0 = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                non_a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                non_a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                \r\n                tmp[:dur_anesthesiologist] = \"\\\\#{off_a0} (official time) / \\\\#{non_a0} (non-official time)\"\r\n                tmp[:dur_anesthetist] = \"\\\\#{off_a1} (official time) / \\\\#{non_a1}, \\\\#{non_a2} (non-official time)\"\r\n            end\r\n            \r\n            tmp[:anes_tech] = map_anes_tech[pos[:anesth_technique]]\r\n            tmp[:asa_status] = pos[:asa_status] == \'\' ? \'Undefined\' : pos[:asa_status]\r\n            tmp[:asa_type] = pos[:asa_type] == \'\' ? \'-\' : pos[:asa_type]\r\n\r\n            # PACU\r\n            tmp[:rr_time] = \'N/A\'\r\n            tmp[:rr_anesthesiologist] = \'N/A\'\r\n            tmp[:rr_anesthetist] = \'N/A\'\r\n            \r\n            rr_place = pos[:recovery_place]\r\n            tmp[:rr_place] = map_pacu[rr_place]\r\n            \r\n            rr_off = (pos[:recovery_time]==\'\' or pos[:recovery_time].nil?) ? 0 : pos[:recovery_time].to_i\r\n            rr_non = (pos[:recovery_non_official_time_min]==\'\' or pos[:recovery_non_official_time_min].nil?) ? 0 : pos[:recovery_non_official_time_min].to_i\r\n            if rr_non==0 and rr_off > 0\r\n                ds = pos[:recovery_date_start].strftime(\'%d/%m/%Y\')\r\n                de = pos[:recovery_date_end].strftime(\'%d/%m/%Y\')\r\n                ts = pos[:recovery_time_start].strftime(\'%H:%M\')\r\n                te = pos[:recovery_time_end].strftime(\'%H:%M\')\r\n                \r\n                tmp[:rr_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{rr_off} mins)\"\r\n                tmp[:rr_anesthesiologist] = (pos[:recovery_anesthesiologist_official]==\'\' or pos[:recovery_anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_official].to_s]\r\n                tmp[:rr_anesthetist] = (pos[:recovery_anesthetic_official]==\'\' or pos[:recovery_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_official].to_s]\r\n            \r\n                tmp[:rr_anesthesiologist] = \"\\\\#{tmp[:rr_anesthesiologist]} (official time)\"\r\n                tmp[:rr_anesthetist] = \"\\\\#{tmp[:rr_anesthetist]} (official time)\"\r\n            elsif rr_non > 0 and rr_off==0\r\n                ds = pos[:recovery_non_official_date_start].strftime(\'%d/%m/%Y\')\r\n                de = pos[:recovery_non_official_date_end].strftime(\'%d/%m/%Y\')\r\n                ts = pos[:recovery_non_official_time_start].strftime(\'%H:%M\')\r\n                te = pos[:recovery_non_official_time_end].strftime(\'%H:%M\')\r\n                \r\n                tmp[:rr_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{rr_non} mins)\"\r\n                tmp[:rr_anesthesiologist] = (pos[:recovery_anesthesiologist_non_official]==\'\' or pos[:recovery_anesthesiologist_non_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_non_official].to_s]\r\n                a1 = (pos[:recovery_anesthetic_non_official_1]==\'\' or pos[:recovery_anesthetic_non_official_1].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_1].to_s]\r\n                a2 = (pos[:recovery_anesthetic_non_official_2]==\'\' or pos[:recovery_anesthetic_non_official_2].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_2].to_s]\r\n                tmp[:rr_anesthetist] = \"\\\\#{a1}, \\\\#{a2}\"\r\n            \r\n                tmp[:rr_anesthesiologist] = \"\\\\#{tmp[:rr_anesthesiologist]} (non-official time)\"\r\n                tmp[:rr_anesthetist] = \"\\\\#{tmp[:rr_anesthetist]} (non-official time)\"\r\n            elsif rr_non > 0 and rr_off > 0\r\n                ds_off = pos[:recovery_date_start]\r\n                de_off = pos[:recovery_date_end]\r\n                ds_non = pos[:recovery_time_start]\r\n                de_non = pos[:recovery_time_end]\r\n                \r\n                ts_off = pos[:recovery_non_official_date_start].strftime(\'%H:%M\')\r\n                te_off = pos[:recovery_non_official_date_end].strftime(\'%H:%M\')\r\n                ts_non = pos[:recovery_non_official_time_start].strftime(\'%H:%M\')\r\n                te_non = pos[:recovery_non_official_time_end].strftime(\'%H:%M\')\r\n                \r\n                ds = ds_off\r\n                de = de_non\r\n                ts = ts_off\r\n                te = te_non\r\n                if ds_off == ds_non and de_off == de_non\r\n                    if ts_non < ts_off\r\n                        ts = ts_non\r\n                        te = te_off\r\n                    end\r\n                    tmp[:rr_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{rr_off + rr_non} mins)\"    \r\n                elsif de_non > ds_off\r\n                    tmp[:rr_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{rr_off + rr_non} mins)\"    \r\n                elsif ds_non < de_off\r\n                    ds = ds_non\r\n                    de = de_off\r\n                    ts = ts_non\r\n                    te = te_off\r\n                    tmp[:rr_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{rr_off + rr_non} mins)\"    \r\n                else\r\n                    tmp[:rr_time] = \"official time : (\\\\#{ds_off} \\\\#{ts_off} - \\\\#{de_off} \\\\#{te_off}) / non-official time : (\\\\#{ds_non} \\\\#{ts_non} - \\\\#{de_non} \\\\#{te_non}) [\\\\#{rr_off + rr_non} mins] \"\r\n                end\r\n\r\n                off_a0 = (pos[:recovery_anesthesiologist_official]==\'\' or pos[:recovery_anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_official].to_s]\r\n                off_a1 = (pos[:recovery_anesthetic_official]==\'\' or pos[:recovery_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_official].to_s]\r\n                non_a0 = (pos[:recovery_anesthesiologist_non_official]==\'\' or pos[:recovery_anesthesiologist_non_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_non_official].to_s]\r\n                non_a1 = (pos[:recovery_anesthetic_non_official_1]==\'\' or pos[:recovery_anesthetic_non_official_1].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_1].to_s]\r\n                non_a2 = (pos[:recovery_anesthetic_non_official_2]==\'\' or pos[:recovery_anesthetic_non_official_2].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_2].to_s]\r\n                \r\n                tmp[:rr_anesthesiologist] = \"\\\\#{off_a0} (official time) / \\\\#{non_a0} (non-official time)\"\r\n                tmp[:rr_anesthetist] = \"\\\\#{off_a1} (official time) / \\\\#{non_a1}, \\\\#{non_a2} (non-official time)\"\r\n            end\r\n                        \r\n            tmp[:id] = i.id.to_s\r\n            tmp[:pm_id] = pm_app.id.to_s\r\n            ars << tmp\r\n        end\r\n        \r\n    end\r\n%>\r\n<% if ars.count == 0 %>\r\n<center><b>No Result Found.</b></center>\r\n<% else %>\r\n<style>\r\nv {\r\n    col