+= 1\r\n            elsif at_dur >= 30 and at_dur <=60\r\n                @res_mon[:at_dur][1] += 1\r\n            elsif at_dur > 60 and at_dur <= 120\r\n                @res_mon[:at_dur][2] += 1\r\n            elsif at_dur > 120 and at_dur <= 240\r\n                @res_mon[:at_dur][3] += 1\r\n            else\r\n                @res_mon[:at_dur][4] += 1\r\n            end\r\n            \r\n            if at_non==0 and at_off > 0\r\n                @res_mon[:at_off] += 1\r\n            elsif at_non > 0 and at_off==0\r\n                @res_mon[:at_non] += 1\r\n            elsif at_non > 0 and at_off > 0\r\n                ds_off = i[:anesthetic_official_date_start]\r\n                de_off = i[:anesthetic_official_date_end]\r\n                ds_non = i[:anesthetic_nonofficial_date_start]\r\n                de_non = i[:anesthetic_nonofficial_date_end]\r\n                \r\n                ts_off = i[:anesthetic_official_time_start].strftime(\'%H:%M\')\r\n                te_off = i[:anesthetic_official_time_end].strftime(\'%H:%M\')\r\n                ts_non = i[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\')\r\n                te_non = i[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\')\r\n                \r\n                ds = ds_off\r\n                de = de_non\r\n                ts = ts_off\r\n                te = te_non\r\n                if ds_off == ds_non and de_off == de_non\r\n                    if ts_non < ts_off\r\n                        ts = ts_non\r\n                        te = te_off\r\n                    end\r\n                    @res_mon[:at_off] += 1\r\n                    @res_mon[:at_non] += 1\r\n                elsif de_non > ds_off\r\n                    @res_mon[:at_off] += 1   \r\n                    @res_mon[:at_non] += 1\r\n                elsif ds_non < de_off\r\n                    ds = ds_non\r\n                    de = de_off\r\n                    ts = ts_non\r\n                    te = te_off\r\n                    @res_mon[:at_off] += 1\r\n                    @res_mon[:at_non] += 1    \r\n                else\r\n                    @res_mon[:at_off] += 1\r\n                    @res_mon[:at_non] += 1\r\n                    # tmp[:dur_time] = \"official time : (\\\\#{ds_off} \\\\#{ts_off} - \\\\#{de_off} \\\\#{te_off}) / non-official time : (\\\\#{ds_non} \\\\#{ts_non} - \\\\#{de_non} \\\\#{te_non}) [\\\\#{dur_off + dur_non} mins] \"\r\n                end\r\n            else\r\n                @res_mon[:at_off] += 1\r\n                @res_mon[:at_non] += 1\r\n            end\r\n            \r\n            \r\n            # if at_off > 0\r\n            #     @res_mon[:at_off] += 1\r\n            # end\r\n            # if at_non > 0\r\n            #     @res_mon[:at_non] += 1\r\n            # end\r\n            \r\n            \r\n            \r\n            \r\n            \r\n            # anesth technique\r\n            an_tec = (i[:anesth_technique] == \'\' or i[:anesth_technique].nil?) ? \'0\' : i[:anesth_technique]\r\n         \r\n            @res_mon[:an_tec][an_tec] += 1 if @res_mon[:an_tec][an_tec]\r\n            \r\n            \r\n            # case_type\r\n            case_type = (i[:case_type] == \'\' or i[:case_type].nil?) ? \'0\' : i[:case_type]\r\n            \r\n            @res_mon[:case_type][case_type] += 1\r\n            \r\n            # cs << \"\\\\#{i[:record_date]}...\\\\#{case_type}\"\r\n            \r\n            \r\n            \r\n            \r\n            # asa status and asa type\r\n            asa_status = (i[:asa_status] == \'\' or i[:asa_status].nil?) ? \'0\' : i[:asa_status]\r\n            asa_type = i[:asa_type] == \'\' ? \'-\' : i[:asa_type]\r\n            if asa_type == \'E\'\r\n                \r\n                asae = \"\\\\#{asa_status}E\"\r\n                @res_mon[:asa_status][asae] = 0 unless @res_mon[:asa_status][asae]\r\n                @res_mon[:asa_status][asae] += 1\r\n            \r\n            else\r\n                