n 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>     5.5 Monitor\r\n  anesthetic care</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:an_tec][\'4\'] %></v></span></p>\r\n  </td>\r\n </tr>\r\n \r\n\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>     5.6 Regional\r\n  anesthesia</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:an_tec][\'5\'] %></v></span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>     5.7 Nerve\r\n  Block</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:an_tec][\'6\'] %></v></span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>     5.8 Combined\r\n  general anesthesia and nerve block</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:an_tec][\'7\'] %></v></span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>     5.9 Combined\r\n  general anesthesia and regional anesthesia</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:an_tec][\'8\'] %></v></span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>     5.10 GA\r\n  due to RA/nerve block fail</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:an_tec][\'9\'] %></v></span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>     5.11 Undefined</span></p>\r\n  </td>\r\n  <td width=60 valign=top>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:an_tec][\'0\'] %></v></span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>6. <span\r\n  lang=TH>&#3649;&#3610;&#3656;&#3591;&#3605;&#3634;&#3617;&#3588;&#3623;&#3634;&#3617;&#3593;&#3640;&#3585;&#3648;&#3593;&#3636;&#3609;</span></span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span lang=TH class=\'sarabun-font\'>(<v><%= @res_mon[:asa_type].values.sum %> </v>&#3619;&#3634;&#3618;)</span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span lang=TH class=\'sarabun-font\'>     </span><span class=\'sarabun-font\'>6.1 Elective\r\n  case</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:asa_type][\'-\'] %></v></span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>     6.2 Emergency\r\n  case</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:asa_type][\'E\'] %></v></span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><b><span lang=TH class=\'sarabun-font\'>งานบริการอื่น ๆ</span></b></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'>(&#3619;&#3634;&#3618;)</span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span lang=TH class=\'sarabun-font\'>งานดูแลผู้ป่วยในห้องพักฟื้น</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:rr] %></v></span></p>\r\n  </td>\r\n </tr>\r\n <tr>\r\n  <td width=445 valign=top style=\'width:333.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span lang=TH class=\'sarabun-font\'>จำนวนผู้เข้ารับบริการ</span></p>\r\n  </td>\r\n  <td width=60 valign=top style=\'width:45.0pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=col1><span class=\'sarabun-font\'>&nbsp;</span></p>\r\n  </td>\r\n  <td width=133 valign=top style=\'width:99.9pt;padding:0in 5.4pt 0in 5.4pt\'>\r\n  <p class=\'col3\'><span class=\'sarabun-font\'><v><%= @res_mon[:count] %></v></span></p>\r\n  </td>\r\n </tr>\r\n</table>\r\n\r\n<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;text-align:\r\njustify;text-justify:inter-cluster;line-height:normal\'><span lang=TH\r\nstyle=\'font-size:16.0pt;font-family:\"TH SarabunPSK\",\"sans-serif\"\'>&nbsp;</span></p>\r\n<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;text-align:\r\njustify;text-justify:inter-cluster;line-height:normal\'><span lang=TH\r\nstyle=\'font-size:16.0pt;font-family:\"TH SarabunPSK\",\"sans-serif\"\'><i>Printed by <v><%= @map_login[@current_user].nil? ? \'Unknown\' : @map_login[@current_user] %> (<%= @current_user %>)</v> at <v><%= Time.now.strftime(\'%d/%m/%Y %H:%M\') %></v> </i></span></p>\r\n<hr/>\r\n<% if @current_role==\'developer\' %>\r\n<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;text-align:\r\njustify;text-justify:inter-cluster;line-height:normal\'><span lang=TH\r\nstyle=\'font-size:16.0pt;font-family:\"TH SarabunPSK\",\"sans-serif\"\'>Processing Time : <%= Time.now - tb %></span></p>\r\n<% end # role %>\r\n</div>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2015-12-07 05:43:51','2015-12-07 05:43:51','monthly_report_result',''),(1942,'config',830,1,'[\r\n    {:name=>\'Anesthetic Records\',:open=>true,:actions=>[\r\n        {:name=>\'Pre Anesthetic\',:service=>\'pre_op\',:link=>\'../PreOp/index\',:remote=>false},\r\n        {:title=>\'Post Anesthetic\', :name=>\'Post Anesthetic\',:service=>\'post_op\',:link=>\'../PostOp/index\',:remote=>false},\r\n    ]}\r\n]\r\n',NULL,NULL,NULL,'2015-12-07 14:34:24','2015-12-07 14:34:24','config',''),(1943,'test',830,3,'<%\r\n    doc = get_document(\'pre_op\')\r\n    # doc = get_document(\'post_op\')\r\n    a_doc = doc.fields\r\n    rs = []\r\n    \r\n    a_doc.each do |i|\r\n        name = i[:name]\r\n        type = i[:field_type]\r\n        lov = \'-\'\r\n        if i[:lov]\r\n            lov = i[:lov].to_s.split(\'\\r\\n\').join(\', \')\r\n        end\r\n        txt = \"\\\\#{name}, \\\\#{type}, \\\\#{lov}\"\r\n        rs << txt\r\n        \r\n%>\r\n<%= txt %><br/>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2015-12-07 14:43:18','2015-12-07 14:43:18','test',''),(1944,'patient_record',830,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    if v = params[:val]\r\n        r_pre = get_model[:pre_anesthetic].find(v)\r\n        c_pre = r_pre.clone\r\n        c_pre.save\r\n        # get_model[:pre_anesthetic].create c_pre\r\n        \r\n        m_pat_mod = ehr_models[:patient_module]\r\n        m_pat_mod.create :module_name=>\"\\\\#{@current_project.name}#pre_anesthetic\", :module_id=>c_pre.id, :parent_id=>params[:parent_id], :patient_id=>params[:patient_id], :ref_number=>\'000000\', :date=>Time.now.strftime(\'%d/%m/%Y\'), :time=>Time.now.strftime(\'%H:%M\')\r\n    end\r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n    end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n<%\r\n    if \'\' == \'developer\'\r\n        all_pm = patient_module_model.all\r\n%>\r\n<pre>\r\n    <%= pm.to_json.html_safe %>\r\n    <% all_pm.each_with_index do |i, idx| %>\r\n    <%= idx %> : <%= i.to_json.html_safe %>\r\n    <% end %>\r\n</pre>\r\n<%\r\n    end\r\n%>\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    for i in last\r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date) if i.date%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% \r\n    # check if pre_anesth created ?\r\n    f_pre = false\r\n    m_par = pm.id.to_s\r\n    \r\n    services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr>\r\n    <td><%= index+1 %>. </td>\r\n    <td> <%= s.title %>\r\n<%\r\nif \'\' == \'developer\'\r\n%>\r\n<br/>\r\npatient_id : <%= patient.id %><br/>\r\nparent_id  : <%= pm.id %><br/>\r\n<%= g.inspect %>\r\n<%\r\nend\r\n%>\r\n    </td>\r\n    <td align=\"center\">\r\n    <% for i in records %>\r\n        <%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n        <%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n    <% end %>\r\n    </td>\r\n<td>\r\n<%  \r\n    if records.size==0 \r\n%>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% \r\n    else \r\n        if s.title.to_s.downcase.include? \'pre\'\r\n            f_pre = true\r\n        end\r\n%>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% \r\n    end \r\n%>\r\n\r\n\r\n<% \r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name if user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\">\r\n<% \r\n    for i in records \r\n%>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% \r\n    end \r\n%>\r\n</td>\r\n<td>\r\n<%  \r\n    if records.size==0 \r\n%>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% \r\n    else \r\n        if !f_pre and s.title.to_s.downcase.include? \'pre\'\r\n%>\r\n<%= link_to \'Copy\', \"\\\\#{request.fullpath}&val=\\\\#{i[:module_id]}&parent_id=\\\\#{m_par}&patient_id=\\\\#{patient.id}\".html_safe, :class=>\'btn btn-warning\' %>\r\n<%\r\n        end\r\n%>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% \r\n    end \r\n%>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2015-12-07 15:35:45','2015-12-07 15:35:45','patient_record',''),(1945,'document_name',834,1,'\'pre_anesthetic\'',NULL,NULL,NULL,'2015-12-07 17:12:47','2015-12-07 17:12:47',NULL,NULL),(1946,'document_name',835,1,'\'post_anesthetic\'',NULL,NULL,NULL,'2015-12-07 17:14:33','2015-12-07 17:14:33',NULL,NULL),(1947,'ot_report_search',805,3,'<%=form_for :query, :url=>\'monthly_report_result?update=result-area\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n            \r\n           \r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">Start Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :sdate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'start-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">End Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :edate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'end-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.submit \'Submit\', :class=>\'btn btn-success\' %>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\" style=\'float:right\'> \r\n                                    <div class=\"field-input\" style=\"float:right\">\r\n                                        <%= link_to \'Print\', \'javascript:void(0)\', :style=>\'float:right;margin-top:5px\', :onclick=>\'javascript:window.print()\', :class=>\'btn btn-info\' %>\r\n                                    </div>\r\n                                </span>\r\n                                \r\n<script>\r\n    $(\"#start-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.at_beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n	$(\"#end-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.at_end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2015-12-13 16:26:42','2015-12-13 16:26:42','ot_report_search',''),(1948,'ot_report_result',805,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.init %>\r\n<%\r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    if q = params[:query]\r\n        sdate = q[:sdate]\r\n        edate = q[:edate] \r\n        rs = get_appointment_by_date(sdate, edate)\r\n        app_ids = rs.collect{|i| i.id.to_s}\r\n        pat_mod = get_patient_module_by_appointment_ids(app_ids)\r\n        par_ids = pat_mod.collect{|i| i.id.to_s}\r\n        pat_mod = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\#{@current_project.name}#post_anesthetic\")\r\n        xxx = get_module_id_array(pat_mod)\r\n        res = @models[:post_anesthetic].find(xxx)\r\n        \r\n        res.each do |i|\r\n            # anesth official and non-official time\r\n            at_dur = i[:anesthetic_duration] ? i[:anesthetic_duration].to_i : 0\r\n            at_off = i[:anesthetic_official_duration] ? i[:anesthetic_official_duration].to_i : 0\r\n            at_non = i[:anesthetic_non_official_duration] ? i[:anesthetic_non_official_duration].to_i : 0\r\n            \r\n            if at_dur < 30\r\n                @res_mon[:at_dur][0] += 1\r\n            elsif at_dur >= 30 and at_dur <=60\r\n                @res_mon[:at_dur][1] += 1\r\n            elsif at_dur > 60 and at_dur <= 120\r\n                @res_mon[:at_dur][2] += 1\r\n            elsif at_dur > 120 and at_dur <= 240\r\n                @res_mon[:at_dur][3] += 1\r\n            else\r\n                @res_mon[:at_dur][4] += 1\r\n            end\r\n            \r\n            if at_off > 0\r\n                @res_mon[:at_off] += 1\r\n            end\r\n            if at_non > 0\r\n                @res_mon[:at_non] += 1\r\n            end\r\n            \r\n            # anesth technique\r\n            an_tec = (i[:anesth_technique] == \'\' or i[:anesth_technique] == nil) ? \'0\' : i[:anesth_technique]\r\n            @res_mon[:an_tec][an_tec] += 1\r\n            \r\n            # case_type\r\n            case_type = (i[:case_type] ==\'\' or i[:case_type] == nil) ? \'0\' : i[:case_type]\r\n            @res_mon[:case_type][case_type] += 1\r\n            \r\n            # asa status and asa type\r\n            asa_status = (i[:asa_status] == \'\' or i[:asa_status] == nil) ? \'0\' : i[:asa_status]\r\n            asa_type = i[:asa_type] == \'\' ? \'-\' : i[:asa_type]\r\n            @res_mon[:asa_status][asa_status] += 1\r\n            @res_mon[:asa_type][asa_type] += 1\r\n            \r\n            # recovery place\r\n            rr = i[:recovery_place]\r\n            ar << rr\r\n            if rr == \'2\'\r\n                @res_mon[:rr] += 1\r\n            end\r\n        end\r\n        @res_mon[:count] = res.count\r\n        @res_mon[:sdate] = sdate\r\n        @res_mon[:edate] = edate\r\n        \r\n        session[:res_mon] = @res_mon\r\n    end\r\n%>\r\n<% if @res_mon.count == 0 %>\r\n<center><b>No Result Found</b></center>\r\n<% else %>\r\n<style>\r\n<!--\r\n /* Font Definitions */\r\n @font-face\r\n	{font-family:Wingdings;\r\n	panose-1:5 0 0 0 0 0 0 0 0 0;}\r\n@font-face\r\n	{font-family:\"Cordia New\";\r\n	panose-1:2 11 3 4 2 2 2 2 2 4;}\r\n@font-face\r\n	{font-family:\"Cordia New\";\r\n	pa