span></p>\r\n<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;text-align:\r\njustify;text-justify:inter-cluster;line-height:normal\'><span lang=TH\r\nstyle=\'font-size:16.0pt;font-family:\"TH SarabunPSK\",\"sans-serif\"\'><i>Printed by <v><%= @map_login[@current_user].nil? ? \'Unknown\' : @map_login[@current_user] %> (<%= @current_user %>)</v> at <v><%= Time.now.strftime(\'%d/%m/%Y %H:%M\') %></v> </i></span></p>\r\n<hr/>\r\n<% if @current_role==\'developer\' %>\r\n<p class=MsoNormal style=\'margin-bottom:0in;margin-bottom:.0001pt;text-align:\r\njustify;text-justify:inter-cluster;line-height:normal\'><span lang=TH\r\nstyle=\'font-size:16.0pt;font-family:\"TH SarabunPSK\",\"sans-serif\"\'>Processing Time : <%= Time.now - tb %></span></p>\r\n<% end # role %>\r\n</div>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2015-12-13 16:27:16','2015-12-13 16:27:16','ot_report_result',''),(1950,'layout',836,4,'<html>\r\n<head>\r\n<title>Clinic system : <%=@current_service%></title>\r\n<%=include_header%>\r\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n<style>\r\n.w-box-header {\r\n    background: -webkit-linear-gradient(top, #fbfbfb 0%,#D8D8D8 100%);\r\n}\r\nspan.k-timepicker, span.k-datetimepicker, span.k-datepicker {\r\n    \r\n    padding-bottom: 10px;\r\n}\r\nbody {\r\n    background: url(\"/esm/clinic_master/clinic/2.jpg\");\r\n    background-repeat: no-repeat;\r\n    background-attachment: fixed;\r\n    -webkit-background-size: cover;\r\n    -moz-background-size: cover;\r\n    -o-background-size: cover;\r\n    background-size: cover;\r\n    \r\n}\r\n\r\n.pull-right {margin-top: 5px;}\r\n#cssmenu {\r\n\r\n  line-height: 15px;\r\n  text-transform: uppercase;\r\n  text-align: left;\r\n}\r\n#cssmenu > ul {\r\n  width: auto;\r\n  list-style-type: none;\r\n  padding: 0;\r\n  margin: 0;\r\n  background: #F7F7F7;\r\n  border: 1px solid #ece6e8;\r\n  border-bottom: 3px solid #d9ced2;\r\n  -webkit-border-radius: 2px;\r\n  -moz-border-rad