</script>\r\n    <!-- CUSTOM SCRIPTS  -->\r\n <script src=\"/esm/kmnci/www/assets/custom.js\"></script>\r\n\r\n</body>\r\n\r\n</html>\r\n',NULL,NULL,NULL,'2015-12-23 15:14:28','2015-12-23 15:14:28','',''),(1993,'get_component',821,3,'<%\r\n    cid = params[:cid].strip\r\n    opt = params[:option]\r\n    # a_type = {}\r\n    \r\n    res = {}\r\n    # tmp = get_model[this.table_name.to_sym].where(\'component_ref_id\'=>\'5654a640790f9b29ce00000d\').all\r\n    tmp = get_model[this.table_name.to_sym].where(:component_ref_id=>cid).all\r\n    if opt.nil?\r\n        res[:result] = tmp\r\n        res[:params] = params\r\n    elsif opt == \'select\'\r\n        xxx = [\"<option value=\'\'></option>\"]\r\n        tmp.each do |i|\r\n            xxx << \"<option value=\'\\\\#{i.id.to_s}\'>\\\\#{i[:type_name]}</option>\"\r\n        end\r\n        res[:result] = xxx.join(\'\');\r\n        res[:params] = params\r\n    end\r\n        \r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-12-24 00:54:06','2015-12-24 00:54:06','get_component',''),(1994,'get_description',819,3,'<%\r\n    company   = params[:company_id]\r\n    component = params[:component_id]\r\n    type = params[:type_id]\r\n    opt = params[:option]\r\n    # a_type = {}\r\n    \r\n    res = {}\r\n    tmp = []\r\n    \r\n        if type\r\n            tmp = get_model[this.table_name.to_sym].where(:company_ref_id=>company, :type_ref_id=>type, :component_ref_id=>component).all\r\n        else\r\n            tmp = get_model[this.table_name.to_sym].where(:company_ref_id=>company, :component_ref_id=>component).all\r\n        end\r\n    \r\n    \r\n    # tmp = get_model[this.table_name.to_sym].where(:company_ref_id=>\'5654bdc8790f9b4bec000003\', :type_ref_id=>\'\', :component_ref_id=>\'\').all\r\n    if opt.nil?\r\n        res[:result] = tmp\r\n    elsif opt == \'select\'\r\n        xxx = [\"<option value=\'\'></option>\"]\r\n        tmp.each do |i|\r\n            xxx << \"<option value=\'\\\\#{i.id.to_s}\'>\\\\#{i[:component_description]} (size:\\\\#{i[:size]}) [side:\\\\#{i[:side]}]</option>\"\r\n        end\r\n        res[:result] = xxx.join(\'\');\r\n    end\r\n        \r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-12-24 01:27:20','2015-12-24 01:27:20','get_description',''),(1995,'check',819,3,'<%\r\n    res = {}\r\n    \r\n    m = get_model[:implant_profile].where(:type_ref_id=>\'\').all\r\n    \r\n    mc = get_model[:implant_component].all\r\n    hc = {}\r\n    mc.each do |i|\r\n        hc[i[:component_id]] = i.id.to_s\r\n    end\r\n    \r\n    ht = {}\r\n    mt = get_model[:implant_type].all\r\n    mt.each do |i|\r\n        key = \"\\\\#{i[:component_id]}-\\\\#{i[:type_id]}\"\r\n        ht[key] = i.id.to_s\r\n    end\r\n    \r\n    m.collect do |i|\r\n        key = \"\\\\#{i[:component_id]}-\\\\#{i[:type_id]}\"\r\n        i[:type_ref_id] = ht[key]\r\n        # i.update_attributes :type_ref_id=>ht[key]\r\n        i\r\n    end\r\n    \r\n    res[:hc] = ht\r\n    res[:count] = m.count\r\n    res[:all_imp] = get_model[:implant_profile].all.count\r\n    res[:all] = m\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-12-24 01:52:02','2015-12-24 01:52:02','check',''),(1996,'all',821,3,'<%\r\n    m = get_model[:implant_type].all\r\n%>\r\n<%= m.to_json.html_safe %>',NULL,NULL,NULL,'2015-12-24 02:10:22','2015-12-24 02:10:22','all',''),(1997,'get_code',819,3,'<%\r\n    code = params[:code]\r\n    # a_type = {}\r\n    \r\n    res = {}\r\n    tmp = []\r\n    if code\r\n        # { :$or => [{:tags => /pePe/i}, {:title => /.*Aubrey.*/i}] }\r\n        tmp = get_model[this.table_name.to_sym].where(:$or=>[{:product_id=>code},{:barcode=>code}]).first\r\n    end\r\n    \r\n    res[:component] = \"<option value=\'\'></option>\"\r\n    res[:type] = \"<option value=\'\'></option>\"\r\n    if tmp\r\n        m_component = get_model[:implant_component].find(tmp[:component_ref_id])\r\n        m_type = get_model[:implant_type].find(tmp[:type_ref_id])\r\n        m_company = get_model[:implant_company].find(tmp[:company_ref_id])\r\n   \r\n        xxx = [\"<option value=\'\'></option>\"]\r\n        # tmp.each do |i|\r\n        res[:description] = \"<option value=\'\\\\#{tmp.id.to_s}\'>\\\\#{tmp[:component_description]} (size:\\\\#{tmp[:size]}) [side:\\\\#{tmp[:side]}]</option>\"\r\n        # end\r\n        \r\n        if m_component\r\n            res[:component] = \"<option value=\'\\\\#{m_component.id.to_s}\'>\\\\#{m_component[:component_name]}</option>\"\r\n        end\r\n        if m_type\r\n            res[:type] = \"<option value=\'\\\\#{m_type.id.to_s}\'>\\\\#{m_type[:type_name]}</option>\"\r\n        end\r\n        if m_company \r\n            res[:company] = \"<option value=\'\\\\#{m_company.id.to_s}\'>\\\\#{m_company[:company_name]}</option>\"\r\n        end\r\n        \r\n        \r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2015-12-24 03:18:53','2015-12-24 03:18:53','get_code',''),(1998,'temp',717,3,'<p>ช่วงสงกรานต์นี้ หลายๆ ท่านคงได้กลับบ้านอยู่กับครอบครัวพร้อมหน้าพร้อมตากัน ก็เลยอยากจะถือโอกาสเผยแพร่บทความที่รวบรวมมาเกี่ยวกับการขอขมากรรมต่อบิดา-มารดา ครับ</p> <p>แน่นอนว่า ตั้งแต่เด็ก จนโต ... แทบทุกคน คงจะมีบ้างที่พลั้งเผลอ ทั้งที่ไม่เจตนา หรือเจตนา ล่วงเกินบิดา-มารดา (พ่อ-แม่) ของเรามาบ้างพอสมควร การกระทำเหล่านั้น อาจจะเป็นด้วยกาย, วาจา, หรือใจ ... ซึ่งสิ่งเหล่านี้อาจเป็นบาปกรรมที่ติดตัวและสะสมกับเราไปได้ เมื่อมันส่งผลจะทำให้เราทำอะไรก็รู้สึกติดขัดโดยไม่รู้สาเหตุ โดยเฉพาะนักปฏิบัติธรรม</p> <p><strong>การขอขมากรรมจะสำเร็จผลได้ จะต้องประกอบด้วยผู้ขอขมากรรม และผู้ให้อโหสิกรรม</strong></p> <ul> <li>ผู้ขอขมากรรม คือเรา ... ซึ่งจะต้องทำให้ครบทั้ง 3 ทาง คือ กาย,วาจา และใจ</li> <li>ผู้ให้อโหสิกรรม คือบิดา-มาดา หรือ พ่อ แม่ ของเรานั่นเอง</li> </ul> <p>สิ่งที่ควรจัดเตรียมก่อนการขอขมา</p> <ol> <li>ธูป 3 ดอก</li> <li>เทียน</li> <li>ดอกไม้ (ทำเป็นกรวยดอกไม้ก็ได้)</li> <li>เงิน หรือสิ่งของที่จะมอบให้บิดา-มารดา ใส่พานรวมกัน</li> </ol> <p>นำทั้งหมดใส่พานรวมกัน เพราะบิดาและมารดาของเราก็เปรียบเสมือน พระอรหันต์ภายในบ้าน อย่างทำบุญง่ายๆเราไม่ต้องไปแสวงหาเกจิดังๆที่ไหนหรอก</p> <p><em>หมายเหตุ-สิ่งของที่จัดเตรียมนั้น อาจจัดเป็นพานขันธ์ 5 (รูป, เวทนา, สัญญา, สังขาร, วิญญาณ) ยกมอบแด่บิดา-มารดาก็ได้ครับ ซึ่งที่บ้านผมทำพานขันธ์ประมาณนี้ครับ 1. ธูป 3 ดอก, 2. เทียนแพ (เทียนเล่มเล็กๆ ขายเป็นซอง), 3. เทียนเล่มบาท (เทียนเล่มใหญ่ๆ หน่อย) 2 เล่ม, 4. ดอกไม้ขาว 5 คู่, 5. เงินเหรียญ 5 เหรียญ ... ครับ</em></p> <p>จากนั้นให้ท่านทั้งสองนั่งคู่กัน แล้วน้อมจิตระลึกคุณบิดา-มารดา และจึงเริ่มกล่าวขอขมาบิดา-มารดา ดังนี้</p> <p><!--more--></p> <h1 style=\"text-align: center;\"><strong>คำกล่าวขอขมาบิดา - มารดา</strong></h1> <p style=\"text-align: center;\">ตั้งนะโม 3 จบ</p> <p style=\"text-align: center;\">... กล่าว ...</p> <p style=\"text-align: center;\">สัพเพปะมาเทนะ ทวารัตเย รักกะตัง สัพพัง อับปะราธัง ขะมะถะเมพันเต มัยหัง มาตาปิตุนังวะ ปาเทวันทามิ สาทะรัง</p> <p>&nbsp;</p> <p>ลูกขอกราบไหว้บูชา บิดามารดาผู้มีพระคุณ ผู้เป็นพระอรหันต์</p> <p>ผู้เป็นพระพรหม เป็นเทพยดาเจ้า และสิ่งศักดิ์สิทธิ์ของลูกทั้งหลาย</p> <p>ด้วยกายก็ดี ด้วยวาจาก็ดี ด้วยใจก็ดี อันลูกทั้งหลายได้กระทำประมาทพลาดพลั้ง</p> <p>ล่วงเกินแล้ว ด้วยความโง่เขลาเบาปัญญา ทั้งต่อหน้าก็ดี ลับหลังก็ดี ที่เจตนาก็ตาม</p> <p>มิได้เจตนาก็ตาม การกระทำใด อันลูกได้กระทำแล้ว ด้วยโลภะจริต โทสะจริต โมหะจริต</p> <p>ต่อบิดามารดา ผู้มีพระคุณ ลูกได้นำมาซึ่งข้าวตอกดอกไม้ ธูปเทียน ของหอม</p> <p>กับน้ำอันบริสุทธิ์นี้ ตลอดจนทรัพย์บรรณาการ</p> <p>อันหามาได้โดยยาก ลูกขอบูชาพระคุณของบิดามารดา ผู้ให้กำเนิดลูกมา</p> <p>ทั้งเลี้ยงดูทะนุถนอม ให้สรรพวิชาความรู้จนเติบใหญ่</p> <p>หาเลี้ยงตนได้ในปัจจุบันนี้ ลูกจักไม่ลืมพระคุณ จะตั้งตนเป็นคนดี</p> <p>ให้สมกับที่ได้เกิดมาเป็นลูกพ่อแม่ ด้วยอำนาจแห่งความรัก และสัจจะวาจานี้</p> <p>ลูกกราบขอขมากรรมทั้งปวง ที่ล่วงกระทำไปแล้ว นับจากอดีตจนถึงปัจจุบัน</p> <p>ขอพ่อแม่ผู้มีพระคุณโปรดเมตตา งดโทษล่วงเกินอันนั้น</p> <p>เพื่อการสำรวมระวังต่อบิดามารดาในการต่อไป บุญทั้งหลายที่ลูกได้กระทำแล้ว</p> <p>ขอพ่อแม่จงเป็นผู้มีส่วนในบุญของลูกด้วย ขอให้พ่อแม่จงเป็นผู้มีอายุยืน</p> <p>มีสุขภาพร่างกายและจิตใจที่แข็งแรง ปราศจากทุกข์โศก และโรคภัยทั้งปวง</p> <p>อยู่เป็นร่มโพธิ์ ร่มไทรของลูกทั้งหลาย เป็นเนื้อนาบุญของลูกทั้งหลายตลอดไปเทอญ</p> <blockquote><p style=\"text-align: left;\">&nbsp;</p> <p style=\"text-align: left;\"><strong>(หมอบกราบพร้อมกล่าว)</strong> กาเยนะ วาจายะวะเจ ตะสาวา มาตาปิตุคุณัง กุกัมมัง ปะกะตัง มะยายัง</p> <p style=\"text-align: left;\">มาตาปิตุ กุกัมมะ อัตจะยันตัง การันตะเร สังวะริตุง มาตาปิตะเร</p> <p>ด้วยกายก็ดี ด้วยวาจาก็ดี ด้วยใจก็ดี ที่ลูกได้กระทำล่วงเกินแล้วต่อบิดามารดาผู้มีพระคุณ</p> <p>ขอบิดามารดาผู้มีพระคุณ โปรดงดโทษล่วงเกินอันนั้น เพื่อการสำรวมระวังในการต่อไป <strong>(พ่อแม่ กล่าว สาธุ ...)</strong></p></blockquote> <p>&nbsp;</p> <p style=\"text-align: center;\"><strong>กราบ 3 ครั้ง – ประเคนพานดอกไม้ – รดน้ำที่มือ/เท้า</strong></p> <p style=\"text-align: center;\"><strong>บิดา - มาดา กล่าวคำว่า \"ให้อโหสิกรรม\"</strong></p> <p>&nbsp;</p> <h2><strong>เคล็ดของสวรรค์</strong></h2> <p>ให้นำเอากะละมังใส่น้ำ จากนั้นเอาเท้าของพ่อ และแม่ (ทีละคน) แช่ลงในน้ำ แล้วเอามือล้างให้สะอาดจนเสร็จ จากนั้นคุกเข่าพนมมือตั้งใจน้อมจิตระลึกคุณพ่อ แม่ แล้วกล่าวออกเสียงว่า</p> <blockquote><p><strong>\"กรรมใดที่ลูก ได้ล่วงเกินต่อพ่อและแม่ จะด้วยกายกรรม วจีกรรม และมโนกรรม ทั้งต่อหน้าและลับหลัง ทั้งที่ตั้งใจและไม่ได้ตังใจ ทั้งในชาตินี้และทุกๆ ชาติที่ผ่านมา ลูกขอขมากรรม ขออโหสิกรรมจากพ่อและแม่ ขอให้พ่อและแม่ให้อโหสิกรรมแก่ลูกด้วยเถิด\"</strong></p></blockquote> <p>หลังจากเรากล่าวเสร็จ พ่อและแม่ จะต้องกล่าวคำว่า <strong>\"ให้อโหสิกรรม\" </strong>จากนั้นเราก็ <strong>เอาน้ำล้างเท้าพ่อแม่เรานั่นแหละมาล้างหน้าลูบหัว</strong> เป็นอันเสร็จพิธี</p> <p><em>(การกล่าวขอขมา จะกล่าวคำขอขมาบิดา-มารดา ที่อยู่ด้านบน ... หรือกล่าวไม่ต้องทุกคำก็ได้ ... สำคัญที่ใจจะต้อง<strong>รู้สึกสำนึก</strong>ผิดและอยากขอขมาต่อพ่อและแม่จริงๆ)</em></p> <p>วิธีนี้ เป็นนัยว่าเป็นเคล็ดสวรรค์ และน้ำล้างเท้าพ่อและแม่นี้ศักดิ์สิทธิ์มากๆ สำหรับลูกครับ</p> <p>&nbsp;</p> <p>***สามารถทำได้ทุกโอกาส  เพื่อความเป็นศิริมงคล***</p> <p>&nbsp;</p> <p>อาจจะมีเขินๆ บ้างนะครับ ตอนที่ล้างเท้าพ่อและแม่ ... และก็ก่อนเริ่มคุยกับพ่อแม่ ... แนะไปเลยว่าให้คุยไปตรงๆ เลยว่าจะเป็นมงคลกับลูกอย่างยิ่ง แล้วเราจะเห็นความเปลี่ยนแปลงด้วยตัวเราเอง โดยเฉพาะนักปฏิบัติ</p> <p>กระผมขออนุโมทนาในมหาบุญนี้กับทุกๆ ท่านด้วยนะครับ และขออุทิศให้กับเจ้าของบทความที่ผมนำมาเผยแพร่ด้วยครับ ... สาธุ</p> <p>------------------------</p> <p>CREDIT</p> <p>- <a href=\"http://www.nangkatik-club.com/smf/index.php?topic=551.0\" target=\"_blank\">http://www.nangkatik-club.com/smf/index.php?topic=551.0</a></p> <p>- <a href=\"http://board.palungjit.com/f8/%E0%B9%80%E0%B8%84%E0%B8%A5%E0%B9%87%E0%B8%94%E0%B8%81%E0%B8%B2%E0%B8%A3%E0%B8%82%E0%B8%AD%E0%B8%82%E0%B8%A1%E0%B8%B2%E0%B8%81%E0%B8%A3%E0%B8%A3%E0%B8%A1%E0%B8%81%E0%B8%B1%E0%B8%9A%E0%B8%9A%E0%B8%B4%E0%B8%94%E0%B8%B2%E0%B8%A1%E0%B8%B2%E0%B8%A3%E0%B8%94%E0%B8%B2-92444.html\" target=\"_blank\">Palungjit</a></p>\r\n\r\n',NULL,NULL,NULL,'2015-12-26 03:55:31','2015-12-26 03:55:31','temp',''),(2003,'staff_report_search',805,3,'<h1>Staff OT Report</h1>\r\n<%=form_for :query, :url=>\'staff_report_result?update=result-area\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n            \r\n           \r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">Start Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :sdate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'start-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">End Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :edate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'end-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.submit \'Submit\', :class=>\'btn btn-success\' %>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\" style=\'float:right\'> \r\n                                    <div class=\"field-input\" style=\"float:right\">\r\n                                        <%= link_to \'Print\', \'javascript:void(0)\', :style=>\'float:right;margin-top:5px\', :onclick=>\'javascript:window.print()\', :class=>\'btn btn-info\' %>\r\n                                    </div>\r\n                                </span>\r\n                                \r\n<script>\r\n    $(\"#start-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.at_beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n	$(\"#end-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.at_end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n	$(\'#result-area\').html(\'\');\r\n</script>\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-01-06 01:25:15','2016-01-06 01:25:15','staff_report_search',''),(2004,'staff_report_result',805,3,'\r\n<%\r\n    tb = Time.now \r\n    \r\n    def map_parent_object(m_arr = [])\r\n        rs = {}\r\n        m_arr.each do |i|\r\n            rs[i[:parent_id].to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n%>\r\n<%= render :inline=>this.init %>\r\n<%#params.inspect %><br/>\r\n<%\r\n\r\n        \r\n\r\n   if true\r\n    rs = {}\r\n    res = {}\r\n    ars = []\r\n    pat_mod = {}\r\n    app_date = Time.now\r\n    if q = params[:query]\r\n        sdate = q[:sdate]\r\n        edate = q[:edate]\r\n        app_date = sdate\r\n        \r\n        \r\n        \r\n        rs = get_appointment_by_date(sdate, edate).compact.sort_by{|i|  (i[:start] == \'\' or i[:start] == nil) ? \'00:00\' : i[:start].strftime(\'%H:%M\')}\r\n        app_ids = rs.collect{|i| i.id.to_s}\r\n        pat_mod = get_patient_module_by_appointment_ids(app_ids)\r\n        par_ids = pat_mod.collect{|i| i.id.to_s}\r\n        pat_ids = pat_mod.collect{|i| i[:patient_id].to_s}\r\n        mod_pre = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#pre_anesthetic\")\r\n        mod_pos = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#post_anesthetic\")\r\n        ids_pre = get_module_id_array(mod_pre)\r\n        ids_pos = get_module_id_array(mod_pos)\r\n        a_pre = @models[:pre_anesthetic].find(ids_pre)\r\n        a_pos = @models[:post_anesthetic].find(ids_pos)\r\n        \r\n        a_pat = @m_pat.find(pat_ids)\r\n        \r\n        \r\n        par_app = get_module_id_map(pat_mod)\r\n        par_pre = map_parent_object(mod_pre)\r\n        par_pos = map_parent_object(mod_pos)\r\n        map_pre = get_map(a_pre)\r\n        map_pos = get_map(a_pos)\r\n        \r\n        map_pat = get_map(a_pat)\r\n        map_ward = get_map(@models[:ward].all)\r\n        # map_room = get_map(@models[:or_room].all)\r\n        \r\n        map_anes_tech = {\'\'=>\'Undefined\',\'1\'=>\'General anesthesia (balanced technique)\', \'2\'=>\'General anesthesia (Inhalation technique)\',\'3\'=>\'General anesthesia (TIVA)\',\'4\'=>\'Monitor anesthetic care\',\'5\'=>\'Regional anesthesia\',\'6\'=>\'Nerve Block\',\'7\'=>\'Combined general anesthesia and nerve block\',\'8\'=>\'Combined general anesthesia and regional anesthesia\',\'9\'=>\'GA due to RA/Nerve block fail\'}\r\n        map_pacu = {nil=>\'Undefined\', \'\'=>\'Undefined\',\'1\'=>\'OR\',\'2\'=>\'RR\',\'3\'=>\'WARD\',\'4\'=>\'ICU\'}\r\n        \r\n        res = par_pre\r\n        oti = [] # intra-operative\r\n        otp = [] # pacu-operative\r\n        rs.each do |i|\r\n            tmp = {}\r\n            pm_app = par_app[i.id.to_s]\r\n            # tmp[:par_id] = par_id.id\r\n            pm_pre = par_pre[pm_app.id.to_s]\r\n            pm_pos = par_pos[pm_app.id.to_s]\r\n            \r\n            if  pm_pos.nil?\r\n                next\r\n            end\r\n            \r\n            \r\n            # patient info\r\n            pat_id = pm_app[:patient_id].to_s\r\n            pat = map_pat[pat_id]\r\n            \r\n            tmp[:hn] = pat[:hn]\r\n            tmp[:name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]}  \\\\#{pat[:last_name]}\"\r\n            \r\n            today = i[:date]\r\n            if pat[:birth_date]\r\n                d = Date.new(today.year, pat[:birth_date].month,  pat[:birth_date].day)\r\n                age = d.year - pat[:birth_date].year - (d > today ? 1 : 0)\r\n                tmp[:age] = age\r\n            else\r\n                tmp[:age] = \'-\'\r\n            end\r\n            \r\n            \r\n            \r\n            # appointment\r\n            tmp[:diag] = i[:diagnosis]\r\n           \r\n            tmp[:operation] = i[:operation]\r\n            tmp[:ward] = \'N/A\'\r\n            tmp[:ward] = (i[:ward]==\'\' or i[:ward].nil?) ? \'N/A\' : map_ward[i[:ward]][:name] if map_ward[i[:ward]]\r\n         \r\n            tmp[:surgeon] = (i[:surgeon]==\'\' or i[:surgeon].nil?) ? \'N/A\' : @provider[i[:surgeon]]\r\n            tmp[:ast_surgeon] = (i[:assist]==\'\' or i[:assist].nil?) ? \'N/A\' : @provider[i[:assist]]\r\n            tmp[:app_date] = i[:date]\r\n            \r\n            \r\n            \r\n            # anesth team\r\n            pre = !pm_pre.nil? ? map_pre[pm_pre[:module_id].to_s] : nil\r\n            pos = map_pos[pm_pos[:module_id].to_s]\r\n            # tmp[:debug] = \"PRE : \\\\#{pre.to_json.html_safe}<br/>POS : \\\\#{pos.to_json.html_safe}\"\r\n            \r\n            if pre\r\n                tmp[:team_pre_1] = (pre[:anesthesiologist]==\'\' or pre[:anesthesiologist].nil?) ? \'N/A\' : @provider[pre[:anesthesiologist].to_s]\r\n                tmp[:team_pre_2] = (pre[:nurse]==\'\' or pre[:nurse].nil?) ? \'N/A\' : @provider[pre[:nurse].to_s]\r\n            else\r\n                tmp[:team_pre_1] = \'N/A\'\r\n                tmp[:team_pre_2] = \'N/A\'\r\n            end\r\n            \r\n            tmp[:team_pos_1] = (pos[:anesthesiologist]==\'\' or pos[:anesthesiologist].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist].to_s]\r\n            tmp[:team_pos_2] = (pos[:nurse_anesthetist]==\'\' or pos[:nurse_anesthetist].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetist].to_s]\r\n            \r\n            # intra-op\r\n            tmp[:xproc] = \"Neuroanesthesia with Special monitor\"\r\n            tmp[:dur_time] = \'N/A\'\r\n            tmp[:dur_anesthesiologist] = \'N/A\'\r\n            tmp[:dur_anesthetist] = \'N/A\'\r\n            \r\n            dur_off = (pos[:anesthetic_official_duration]==\'\' or pos[:anesthetic_official_duration].nil?) ? 0 : pos[:anesthetic_official_duration].to_i\r\n            dur_non = (pos[:anesthetic_non_official_duration]==\'\' or pos[:anesthetic_non_official_duration].nil?) ? 0 : pos[:anesthetic_non_official_duration].to_i\r\n                \r\n            rec_non = (pos[:recovery_non_official_time_min]==\'\' or pos[:recovery_non_official_time_min].nil?) ? 0 : pos[:recovery_non_official_time_min].to_i\r\n                \r\n                \r\n            # anesthetic_official_time_start anesthetic_official_duration\r\n            if rec_non>0\r\n                \r\n                ts = pos[:recovery_non_official_time_start].strftime(\'%H:%M\') if pos[:recovery_non_official_time_start]\r\n                te = pos[:recovery_non_official_time_end].strftime(\'%H:%M\') if pos[:recovery_non_official_time_end]\r\n                \r\n                \r\n                tmp[:rec_non_anesthesiologist] = (pos[:recovery_anesthesiologist_non_official]==\'\' or pos[:recovery_anesthesiologist_non_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_non_official].to_s]\r\n                a1 = (pos[:recovery_anesthetic_non_official_1]==\'\' or pos[:recovery_anesthetic_non_official_1].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_1].to_s]\r\n                a2 = (pos[:recovery_anesthetic_non_official_2]==\'\' or pos[:recovery_anesthetic_non_official_2].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_2].to_s]\r\n                tmp[:rec_non_nurse] = \"\\\\#{a1}, \\\\#{a2}\"\r\n                \r\n                # OT Report\r\n                tmp[:xtime_rec] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes_rec] = tmp[:rec_non_anesthesiologist]\r\n                tmp[:xnur1_rec] = a1\r\n                tmp[:xnur2_rec] = a2\r\n            end\r\n            # only official hour\r\n            if dur_non==0 and dur_off > 0\r\n                ds = pos[:anesthetic_official_date_start].strftime(\'%d/%m/%Y\') if pos[:anesthetic_official_date_start]\r\n                de = pos[:anesthetic_official_date_end].strftime(\'%d/%m/%Y\') if pos[:anesthetic_official_date_end]\r\n                ts = pos[:anesthetic_official_time_start].strftime(\'%H:%M\') if pos[:anesthetic_official_time_start]\r\n                te = pos[:anesthetic_official_time_end].strftime(\'%H:%M\') if pos[:anesthetic_official_time_end]\r\n                \r\n                tmp[:dur_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{dur_off} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                tmp[:dur_anesthetist] = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n            \r\n            # only non officla hour\r\n            elsif dur_non > 0 # and dur_off==0\r\n                ds = pos[:anesthetic_nonofficial_date_start].strftime(\'%d/%m/%Y\') if pos[:anesthetic_nonofficial_date_start]\r\n                de = pos[:anesthetic_nonofficial_date_end].strftime(\'%d/%m/%Y\') if pos[:anesthetic_nonofficial_date_end]\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\') if pos[:anesthetic_nonofficial_time_start]\r\n                te = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\') if pos[:anesthetic_nonofficial_time_end]\r\n                \r\n                tmp[:dur_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{dur_non} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                tmp[:dur_anesthetist] = \"\\\\#{a1}, \\\\#{a2}\"\r\n                \r\n                # OT Report\r\n                tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes] = tmp[:dur_anesthesiologist]\r\n                tmp[:xnur1] = a1\r\n                tmp[:xnur2] = a2\r\n            # has both\r\n            elsif dur_non > 0 and dur_off > 0\r\n                ds_off = pos[:anesthetic_official_date_start]\r\n                de_off = pos[:anesthetic_official_date_end]\r\n                ds_non = pos[:anesthetic_nonofficial_date_start]\r\n                de_non = pos[:anesthetic_nonofficial_date_end]\r\n                \r\n                ts_off = pos[:anesthetic_official_time_start].strftime(\'%H:%M\') if  pos[:anesthetic_official_time_start]\r\n                te_off = pos[:anesthetic_official_time_end].strftime(\'%H:%M\') if  pos[:anesthetic_official_time_end]\r\n                ts_non = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\') if  pos[:anesthetic_nonofficial_time_start]\r\n                te_non = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\') if  pos[:anesthetic_nonofficial_time_end]\r\n                \r\n                ds = ds_off\r\n                de = de_non\r\n                ts = ts_off\r\n                te = te_non\r\n                if ds_off == ds_non and de_off == de_non\r\n                    if ts_non < ts_off\r\n                        ts = ts_non\r\n                        te = te_off\r\n                    end\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\" \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                elsif de_non > ds_off\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"  \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                elsif ds_non < de_off\r\n                    ds = ds_non\r\n                    de = de_off\r\n                    ts = ts_non\r\n                    te = te_off\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"    \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                else\r\n                    tmp[:dur_time] = \"official time : (\\\\#{ds_off} \\\\#{ts_off} - \\\\#{de_off} \\\\#{te_off}) / non-official time : (\\\\#{ds_non} \\\\#{ts_non} - \\\\#{de_non} \\\\#{te_non}) [\\\\#{dur_off + dur_non} mins] \"\r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts_non}-\\\\#{te_non}\"\r\n                end\r\n\r\n\r\n                off_a0 = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                off_a1 = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n                non_a0 = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                non_a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                non_a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                \r\n                \r\n                tmp[:dur_anesthesiologist] = \"\\\\#{off_a0} (official time) / \\\\#{non_a0} (non-official time)\"\r\n                tmp[:dur_anesthetist] = \"\\\\#{off_a1} (official time) / \\\\#{non_a1}, \\\\#{non_a2} (non-official time)\"\r\n                \r\n                # OT Report\r\n                tmp[:xanes] = non_a0\r\n                tmp[:xnur1] = non_a1\r\n                \r\n                tmp[:xnur2] = non_a2\r\n            else\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\') if  pos[:anesthetic_nonofficial_time_start]\r\n                te = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\') if  pos[:anesthetic_nonofficial_time_end]\r\n                if ts==te\r\n                    next\r\n                end\r\n                # OT Report\r\n                tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes] = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesth