[:id]}\", :target=>\'_blank\', :title=>\'more detail\' %></center></td>\r\n    <td><center><%= val[:app_date].strftime(\"%d/%m/%Y\") %></center></td>\r\n    <td><center><%= val[:name] %></center></td>\r\n    <td><center><%= val[:hn] %></center></td>\r\n    <td><center><%= val[:xtime] %></center></td>\r\n    <td><center><%= val[:xproc] %></center></td>\r\n    <td><center><%= val[:xanes] %></center></td>\r\n    <td>&nbsp;</td>\r\n\r\n</tr>\r\n\r\n    <% if val[:xtime_rec] %>\r\n    \r\n <tr>\r\n    <td><center><%= link_to \"\\\\#{count + 1}.\", \"../Home/patient_record?id=\\\\#{val[:id]}\", :target=>\'_blank\', :title=>\'more detail\' %></center></td>\r\n    <td><center><%= val[:app_date].strftime(\"%d/%m/%Y\") %></center></td>\r\n    <td><center><%= val[:name] %></center></td>\r\n    <td><center><%= val[:hn] %></center></td>\r\n    <td><center><%= val[:xtime_rec] %></center></td>\r\n    <td><center><%= \'Post anesthetic care in neurocritical\'  %></center></td>\r\n    <td><center><%= val[:xanes_rec] %></center></td>\r\n    <td>&nbsp;</td>\r\n\r\n</tr> \r\n    <% end %>\r\n\r\n<%\r\n\r\n   count +=1 \r\n    end\r\n    end\r\n%>\r\n										</tbody>\r\n									</table>\r\n<div style=\"width:200px; margin-left:700px; margin-top:30px;line-height: 30px;\">\r\n______________________<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;(นพ. ภูพิงค์ เอกะวิภาต)<br />\r\n&nbsp;&nbsp;หัวหน้ากลุ่มงานวิสัญญีวิทยา\r\n</div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<div class=\'row-fluid\'>\r\n    <div style=\'width:960px\'>\r\n        <strong>\r\n            <center>รายงานผู้ป่วยที่ได้รับยาระงับความรู้สึกนอกเวลาราชการ</center>\r\n            <br/>\r\n            <center>ระหว่างวันที่ <v><%= params[:query][:sdate] %></v> ถึงวันที่ <v><%= params[:query][:edate] %></v></center>\r\n        </strong>\r\n        <br/>\r\n<table class=\"table table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th>ลำดับที่</th>\r\n												<th>ว/ด/ป</th>\r\n												<th>ชื่อ - สกุล</th>\r\n												<th>HN</th>\r\n												<th>เวลา</th>\r\n												<th>วิธีการให้ยาระงับความรู้สึก</th>\r\n												<th>วิสัญญีพยาบาล</th>\r\n												<th>วิสัญญีพยาบาล</th>\r\n												<th>ผู้ช่วยพยาบาล / ผู้ช่วยเหลือคนไข้</th>\r\n											</tr>\r\n										</thead>\r\n										<tbody>\r\n\r\n<%\r\n    ars = ars.sort_by{|i| i[:app_date]}\r\n    count = 0\r\n    ars.each_with_index do |val, i|\r\n    if val[:xtime] and val[:xnur1]!=\"N/A\"\r\n%>\r\n<tr>\r\n    <td><center><%= link_to \"\\\\#{count + 1}.\", \"../Home/patient_record?id=\\\\#{val[:id]}\", :target=>\'_blank\', :title=>\'more detail\' %></center></td>\r\n    <td><center><%= val[:app_date].strftime(\"%d/%m/%Y\") %></center></td>\r\n    <td><center><%= val[:name] %></center></td>\r\n    <td><center><%= val[:hn] %></center></td>\r\n    <td><center><%= val[:xtime] %></center></td>\r\n    <td><center><%= val[:xproc] %></center></td>\r\n    <td><center><%= val[:xnur1] %></center></td>\r\n    <td><center><%= val[:xnur2] %></center></td>\r\n    <td><center><%= val[:xass] %></center></td>\r\n    \r\n</tr>\r\n  <% if val[:xtime_rec] %>\r\n    \r\n <tr>\r\n    <td><center><%= link_to \"\\\\#{count + 1}.\", \"../Home/patient_record?id=\\\\#{val[:id]}\", :target=>\'_blank\', :title=>\'more detail\' %></center></td>\r\n    <td><center><%= val[:app_date].strftime(\"%d/%m/%Y\") %></center></td>\r\n    <td><center><%= val[:name] %></center></td>\r\n    <td><center><%= val[:hn] %></center></td>\r\n    <td><center><%= val[:xtime_rec] %></center></td>\r\n    <td><center><%= \'Post anesthetic care in neurocritical\'  %></center></td>\r\n    <td><center><%= val[:xnur1_rec] %></center></td>\r\n    <td><center><%= val[:xnur2_rec] %></center></td>\r\n    <td><center><%= val[:xass_rec] %></center></td>\r\n</tr> \r\n    <% end %>\r\n\r\n<%\r\ncount+=1\r\n    end\r\n    end\r\n%>\r\n										</tbody>\r\n									</table>\r\n<div style=\"width:200px; margin-left:700px; margin-top:30px;line-height: 30px;\">\r\n______________________<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n(นางสาวเกศินี ดำรงบุล)<br />\r\n&nbsp;&nbsp;หัวหน้าการพยาบาลวิสัญญี\r\n    \r\n</div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<% end%> \r\n',NULL,NULL,NULL,'2016-01-06 01:25:45','2016-01-06 01:25:45','staff_report_result',''),(2005,'dr_report_search',805,3,'<%=form_for :query, :url=>\'dr_report_result?update=result-area\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n            \r\n           \r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">Start Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :sdate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'start-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">End Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :edate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'end-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.submit \'Submit\', :class=>\'btn btn-success\' %>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\" style=\'float:right\'> \r\n                                    <div class=\"field-input\" style=\"float:right\">\r\n                                        <%= link_to \'Print\', \'javascript:void(0)\', :style=>\'float:right;margin-top:5px\', :onclick=>\'javascript:window.print()\', :class=>\'btn btn-info\' %>\r\n                                    </div>\r\n                                </span>\r\n                                \r\n<script>\r\n    $(\"#start-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.at_beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n	$(\"#end-date\").kendoDatePicker({\r\n        value: \'<%= Time.now.at_end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n	});\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2016-01-06 01:26:46','2016-01-06 01:26:46','dr_report_search',''),(2006,'dr_report_result',805,3,'<%\r\n    tb = Time.now \r\n    \r\n    def map_parent_object(m_arr = [])\r\n        rs = {}\r\n        m_arr.each do |i|\r\n            rs[i[:parent_id].to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n%>\r\n<%= render :inline=>this.init %>\r\n<%\r\n    rs = {}\r\n    res = {}\r\n    ars = []\r\n    pat_mod = {}\r\n    app_date = Time.now\r\n    if q = params[:query]\r\n        sdate = q[:sdate]\r\n        edate = q[:edate]\r\n        app_date = sdate\r\n        \r\n        rs = get_appointment_by_date(sdate, edate).sort_by{|i|  (i[:start] == \'\' or i[:start] == nil) ? \'00:00\' : i[:start].strftime(\'%H:%M\')}\r\n        app_ids = rs.collect{|i| i.id.to_s}\r\n        pat_mod = get_patient_module_by_appointment_ids(app_ids)\r\n        par_ids = pat_mod.collect{|i| i.id.to_s}\r\n        pat_ids = pat_mod.collect{|i| i[:patient_id].to_s}\r\n        mod_pre = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#pre_anesthetic\")\r\n        mod_pos = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#post_anesthetic\")\r\n        ids_pre = get_module_id_array(mod_pre)\r\n        ids_pos = get_module_id_array(mod_pos)\r\n        a_pre = @models[:pre_anesthetic].find(ids_pre)\r\n        a_pos = @models[:post_anesthetic].find(ids_pos)\r\n        \r\n        a_pat = @m_pat.find(pat_ids)\r\n        \r\n        par_app = get_module_id_map(pat_mod)\r\n        par_pre = map_parent_object(mod_pre)\r\n        par_pos = map_parent_object(mod_pos)\r\n        map_pre = get_map(a_pre)\r\n        map_pos = get_map(a_pos)\r\n        \r\n        map_pat = get_map(a_pat)\r\n        map_ward = get_map(@models[:ward].all)\r\n        # map_room = get_map(@models[:or_room].all)\r\n        \r\n        map_anes_tech = {\'\'=>\'Undefined\',\'1\'=>\'General anesthesia (balanced technique)\', \'2\'=>\'General anesthesia (Inhalation technique)\',\'3\'=>\'General anesthesia (TIVA)\',\'4\'=>\'Monitor anesthetic care\',\'5\'=>\'Regional anesthesia\',\'6\'=>\'Nerve Block\',\'7\'=>\'Combined general anesthesia and nerve block\',\'8\'=>\'Combined general anesthesia and regional anesthesia\',\'9\'=>\'GA due to RA/Nerve block fail\'}\r\n        map_pacu = {nil=>\'Undefined\', \'\'=>\'Undefined\',\'1\'=>\'OR\',\'2\'=>\'RR\',\'3\'=>\'WARD\',\'4\'=>\'ICU\'}\r\n        \r\n        res = par_pre\r\n        rs.each do |i|\r\n            tmp = {}\r\n            pm_app = par_app[i.id.to_s]\r\n            # tmp[:par_id] = par_id.id\r\n            pm_pre = par_pre[pm_app.id.to_s]\r\n            pm_pos = par_pos[pm_app.id.to_s]\r\n            \r\n            if  pm_pos.nil?\r\n                next\r\n            end\r\n            \r\n            # patient info\r\n            pat_id = pm_app[:patient_id].to_s\r\n            pat = map_pat[pat_id]\r\n            \r\n            tmp[:hn] = pat[:hn]\r\n            tmp[:name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]}  \\\\#{pat[:last_name]}\"\r\n            \r\n            today = i[:date]\r\n            if pat[:birth_date]\r\n                d = Date.new(today.year, pat[:birth_date].month,  pat[:birth_date].day)\r\n                age = d.year - pat[:birth_date].year - (d > today ? 1 : 0)\r\n                tmp[:age] = age\r\n            else\r\n                tmp[:age] = \'-\'\r\n            end\r\n            \r\n            # appointment\r\n            tmp[:diag] = i[:diagnosis]\r\n            tmp[:operation] = i[:operation]\r\n            tmp[:ward] = (i[:ward]==\'\' or i[:ward].nil?) ? \'N/A\' : map_ward[i[:ward]][:name]\r\n            tmp[:surgeon] = (i[:surgeon]==\'\' or i[:surgeon].nil?) ? \'N/A\' : @provider[i[:surgeon]]\r\n            tmp[:ast_surgeon] = (i[:assist]==\'\' or i[:assist].nil?) ? \'N/A\' : @provider[i[:assist]]\r\n            tmp[:app_date] = i[:date]\r\n            \r\n            # anesth team\r\n            pre = !pm_pre.nil? ? map_pre[pm_pre[:module_id].to_s] : nil\r\n            pos = map_pos[pm_pos[:module_id].to_s]\r\n            # tmp[:debug] = \"PRE : \\\\#{pre.to_json.html_safe}<br/>POS : \\\\#{pos.to_json.html_safe}\"\r\n            \r\n            if pre\r\n                tmp[:team_pre_1] = (pre[:anesthesiologist]==\'\' or pre[:anesthesiologist].nil?) ? \'N/A\' : @provider[pre[:anesthesiologist].to_s]\r\n                tmp[:team_pre_2] = (pre[:nurse]==\'\' or pre[:nurse].nil?) ? \'N/A\' : @provider[pre[:nurse].to_s]\r\n            else\r\n                tmp[:team_pre_1] = \'N/A\'\r\n                tmp[:team_pre_2] = \'N/A\'\r\n            end\r\n            \r\n            tmp[:team_pos_1] = (pos[:anesthesiologist]==\'\' or pos[:anesthesiologist].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist].to_s]\r\n            tmp[:team_pos_2] = (pos[:nurse_anesthetist]==\'\' or pos[:nurse_anesthetist].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetist].to_s]\r\n            \r\n            # intra-op\r\n            tmp[:dur_time] = \'N/A\'\r\n            tmp[:dur_anesthesiologist] = \'N/A\'\r\n            tmp[:dur_anesthetist] = \'N/A\'\r\n            dur_off = (pos[:anesthetic_official_duration]==\'\' or pos[:anesthetic_official_duration].nil?) ? 0 : pos[:anesthetic_official_duration].to_i\r\n            dur_non = (pos[:anesthetic_non_official_duration]==\'\' or pos[:anesthetic_non_official_duration].nil?) ? 0 : pos[:anesthetic_non_official_duration].to_i\r\n            if dur_non==0 and dur_off > 0\r\n                next\r\n                ds = pos[:anesthetic_official_date_start].strftime(\'%d/%m/%Y\')\r\n                de = pos[:anesthetic_official_date_end].strftime(\'%d/%m/%Y\')\r\n                ts = pos[:anesthetic_official_time_start].strftime(\'%H:%M\')\r\n                te = pos[:anesthetic_official_time_end].strftime(\'%H:%M\')\r\n                \r\n                tmp[:dur_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{dur_off} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                tmp[:dur_anesthetist] = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n            elsif dur_non > 0 and dur_off==0\r\n                ds = pos[:anesthetic_nonofficial_date_start].strftime(\'%d/%m/%Y\')\r\n                de = pos[:anesthetic_nonofficial_date_end].strftime(\'%d/%m/%Y\')\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\')\r\n                te = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\')\r\n                \r\n                tmp[:dur_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{dur_non} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                tmp[:dur_anesthetist] = \"\\\\#{a1}, \\\\#{a2}\"\r\n                \r\n                # OT Report\r\n                tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes] = tmp[:dur_anesthesiologist]\r\n            elsif dur_non > 0 and dur_off > 0\r\n                ds_off = pos[:anesthetic_official_date_start]\r\n                de_off = pos[:anesthetic_official_date_end]\r\n                ds_non = pos[:anesthetic_nonofficial_date_start]\r\n                de_non = pos[:anesthetic_nonofficial_date_end]\r\n                \r\n                ts_off = pos[:anesthetic_official_time_start].strftime(\'%H:%M\')\r\n                te_off = pos[:anesthetic_official_time_end].strftime(\'%H:%M\')\r\n                ts_non = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\')\r\n                te_non = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\')\r\n                \r\n                ds = ds_off\r\n                de = de_non\r\n                ts = ts_off\r\n                te = te_non\r\n                if ds_off == ds_non and de_off == de_non\r\n                    if ts_non < ts_off\r\n                        ts = ts_non\r\n                        te = te_off\r\n                    end\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\" \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                elsif de_non > ds_off\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"  \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                elsif ds_non < de_off\r\n                    ds = ds_non\r\n                    de = de_off\r\n                    ts = ts_non\r\n                    te = te_off\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"    \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                else\r\n                    tmp[:dur_time] = \"official time : (\\\\#{ds_off} \\\\#{ts_off} - \\\\#{de_off} \\\\#{te_off}) / non-official time : (\\\\#{ds_non} \\\\#{ts_non} - \\\\#{de_non} \\\\#{te_non}) [\\\\#{dur_off + dur_non} mins] \"\r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts_non}-\\\\#{te_non}\"\r\n                end\r\n\r\n                off_a0 = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                off_a1 = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n                non_a0 = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                non_a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                non_a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                \r\n                tmp[:dur_anesthesiologist] = \"\\\\#{off_a0} (official time) / \\\\#{non_a0} (non-official time)\"\r\n                tmp[:dur_anesthetist] = \"\\\\#{off_a1} (official time) / \\\\#{non_a1}, \\\\#{non_a2} (non-official time)\"\r\n                \r\n                # OT Report\r\n                tmp[:xanes] = non_a0\r\n            else\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\')\r\n                te = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\')\r\n                if ts==te\r\n                    next\r\n                end\r\n                # OT Report\r\n                tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes] = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n            end\r\n            \r\n            # tmp[:anes_tech] = map_anes_tech[pos[:anesth_technique]]\r\n            # tmp[:asa_status] = pos[:asa_status] == \'\' ? \'Undefined\' : pos[:asa_status]\r\n            # tmp[:asa_type] = pos[:asa_type] == \'\' ? \'-\' : pos[:asa_type]\r\n\r\n            # PACU\r\n            # tmp[:rr_time] = \'N/A\'\r\n            # tmp[:rr_anesthesiologist] = \'N/A\'\r\n            # tmp[:rr_anesthetist] = \'N/A\'\r\n            \r\n            # rr_place = pos[:recovery_place]\r\n            # tmp[:rr_place] = map_pacu[rr_place]\r\n            \r\n            # rr_off = (pos[:recovery_time]==\'\' or pos[:recovery_time].nil?) ? 0 : pos[:recovery_time].to_i\r\n            # rr_non = (pos[:recovery_non_official_time_min]==\'\' or pos[:recovery_non_official_time_min].nil?) ? 0 : pos[:recovery_non_official_time_min].to_i\r\n            # if rr_non==0 and rr_off > 0\r\n            #     ds = pos[:recovery_date_start].strftime(\'%d/%m/%Y\')\r\n            #     de = pos[:recovery_date_end].strftime(\'%d/%m/%Y\')\r\n            #     ts = pos[:recovery_time_start].strftime(\'%H:%M\')\r\n            #     te = pos[:recovery_time_end].strftime(\'%H:%M\')\r\n                \r\n            #     tmp[:rr_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{rr_off} mins)\"\r\n            #     tmp[:rr_anesthesiologist] = (pos[:recovery_anesthesiologist_official]==\'\' or pos[:recovery_anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_official].to_s]\r\n            #     tmp[:rr_anesthetist] = (pos[:recovery_anesthetic_official]==\'\' or pos[:recovery_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_official].to_s]\r\n            # elsif rr_non > 0 and rr_off==0\r\n            #     ds = pos[:recovery_non_official_date_start].strftime(\'%d/%m/%Y\')\r\n            #     de = pos[:recovery_non_official_date_end].strftime(\'%d/%m/%Y\')\r\n            #     ts = pos[:recovery_non_official_time_start].strftime(\'%H:%M\')\r\n            #     te = pos[:recovery_non_official_time_end].strftime(\'%H:%M\')\r\n                \r\n            #     tmp[:rr_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{rr_non} mins)\"\r\n            #     tmp[:rr_anesthesiologist] = (pos[:recovery_anesthesiologist_non_official]==\'\' or pos[:recovery_anesthesiologist_non_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_non_official].to_s]\r\n            #     a1 = (pos[:recovery_anesthetic_non_official_1]==\'\' or pos[:recovery_anesthetic_non_official_1].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_1].to_s]\r\n            #     a2 = (pos[:recovery_anesthetic_non_official_2]==\'\' or pos[:recovery_anesthetic_non_official_2].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_2].to_s]\r\n            #     tmp[:rr_anesthetist] = \"\\\\#{a1}, \\\\#{a2}\"\r\n            # elsif rr_non > 0 and rr_off > 0\r\n            #     ds_off = pos[:recovery_date_start]\r\n            #     de_off = pos[:recovery_date_end]\r\n            #     ds_non = pos[:recovery_time_start]\r\n            #     de_non = pos[:recovery_time_end]\r\n                \r\n            #     ts_off = pos[:recovery_non_official_date_start].strftime(\'%H:%M\')\r\n            #     te_off = pos[:recovery_non_official_date_end].strftime(\'%H:%M\')\r\n            #     ts_non = pos[:recovery_non_official_time_start].strftime(\'%H:%M\')\r\n            #     te_non = pos[:recovery_non_official_time_end].strftime(\'%H:%M\')\r\n                \r\n            #     ds = ds_off\r\n            #     de = de_non\r\n            #     ts = ts_off\r\n            #     te = te_non\r\n            #     if ds_off == ds_non and de_off == de_non\r\n            #         if ts_non < ts_off\r\n            #             ts = ts_non\r\n            #             te = te_off\r\n            #         end\r\n            #         tmp[:rr_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{rr_off + rr_non} mins)\"    \r\n            #     elsif de_non > ds_off\r\n            #         tmp[:rr_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{rr_off + rr_non} mins)\"    \r\n            #     elsif ds_non < de_off\r\n            #         ds = ds_non\r\n            #         de = de_off\r\n            #         ts = ts_non\r\n            #         te = te_off\r\n            #         tmp[:rr_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{rr_off + rr_non} mins)\"    \r\n            #     else\r\n            #         tmp[:rr_time] = \"official time : (\\\\#{ds_off} \\\\#{ts_off} - \\\\#{de_off} \\\\#{te_off}) / non-official time : (\\\\#{ds_non} \\\\#{ts_non} - \\\\#{de_non} \\\\#{te_non}) [\\\\#{rr_off + rr_non} mins] \"\r\n            #     end\r\n\r\n            #     off_a0 = (pos[:recovery_anesthesiologist_official]==\'\' or pos[:recovery_anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_official].to_s]\r\n            #     off_a1 = (pos[:recovery_anesthetic_official]==\'\' or pos[:recovery_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_official].to_s]\r\n            #     non_a0 = (pos[:recovery_anesthesiologist_non_official]==\'\' or pos[:recovery_anesthesiologist_non_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_non_official].to_s]\r\n            #     non_a1 = (pos[:recovery_anesthetic_non_official_1]==\'\' or pos[:recovery_anesthetic_non_official_1].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_1].to_s]\r\n            #     non_a2 = (pos[:recovery_anesthetic_non_official_2]==\'\' or pos[:recovery_anesthetic_non_official_2].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_2].to_s]\r\n                \r\n            #     tmp[:rr_anesthesiologist] = \"\\\\#{off_a0} (official time) / \\\\#{non_a0} (non-official time)\"\r\n            #     tmp[:rr_anesthetist] = \"\\\\#{off_a1} (official time) / \\\\#{non_a1}, \\\\#{non_a2} (non-official time)\"\r\n            # end\r\n                        \r\n            tmp[:id] = i.id.to_s\r\n            tmp[:pm_id] = pm_app.id.to_s\r\n            ars << tmp\r\n        end\r\n        \r\n    end\r\n%>\r\n<style>\r\nv {\r\n    color: #2561CD;\r\n}\r\n</style>\r\n<br/>\r\n<div class=\'row-fluid\'>\r\n    <div style=\'width:960px\'>\r\n        <strong>\r\n            <center>รายงานผู้ป่วยที่ได้รับยาระงับความรู้สึกนอกเวลาราชการ</center>\r\n            <br/>\r\n            <center>ระหว่างวันที่ <v><%= params[:query][:sdate] %></v> ถึงวันที่ <v><%= params[:query][:edate] %></v></center>\r\n        </strong>\r\n        <br/>\r\n<table class=\"table table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th>ลำดับที่</th>\r\n												<th>ว/ด/ป</th>\r\n												<th>ชื่อ - สกุล</th>\r\n												<th>HN</th>\r\n												<th>เวลา</th>\r\n												<th>วิธีการให้ยาระงับความรู้สึก</th>\r\n												<th>วิสัญญีแพทย์</th>\r\n											</tr>\r\n										</thead>\r\n										<tbody>\r\n\r\n<%\r\n    ars = ars.sort_by{|i| i[:app_date]}\r\n    ars.each_with_index do |val, i|\r\n%>\r\n<tr>\r\n    <td><center><%= link_to \"\\\\#{i + 1}.\", \"../Home/patient_record?id=\\\\#{val[:id]}\", :target=>\'_blank\', :title=>\'more detail\' %></center></td>\r\n    <td><center><%= val[:app_date] %></center></td>\r\n    <td><center><%= val[:name] %></center></td>\r\n    <td><center><%= val[:hn] %></center></td>\r\n    <td><center><%= val[:xtime] %></center></td>\r\n    <td><center>Post anesthetic care in neurocritical patient</center></td>\r\n    <td><center><%= val[:xanes] %></center></td>\r\n</tr>\r\n<%\r\n    end\r\n%>\r\n										</tbody>\r\n									</table>\r\n    </div>\r\n</div>\r\n',NULL,NULL,NULL,'2016-01-06 01:27:10','2016-01-06 01:27:10','dr_report_result',''),(2007,'index',856,2,'\r\n<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n\r\n\r\n\r\n<div id = \"index_panel\">\r\nLoading..\r\n</div>\r\n\r\n<%\r\n\r\n\r\n\r\n@partial_role = @current_role\r\n\r\n\r\nif params[:role]\r\n   session[:role] = params[:role] \r\nend\r\n\r\nsession.delete :role if params[:role] and params[:role] ==\'\'\r\n\r\n@partial_role = session[:role] if session[:role]\r\n\r\n\r\nlanding = \'index_partial\'\r\n\r\nlanding = \"../Registration/index_partial\" if @partial_role==\'registration\'\r\n\r\nlanding = \"../Exam/index_partial\" if @partial_role==\'exam\'\r\n\r\nlanding = \"../Opd/index_partial\" if @partial_role==\'opd\'\r\n\r\nlanding = \"../Counselling/index_partial\" if @partial_role==\'counselling1\'\r\n\r\nlanding = \"../Accounting/index_partial\" if @partial_role==\'accounting\'\r\n\r\nlanding = \"../Counselling/index_partial_2\" if @partial_role==\'counselling2\'\r\n\r\nlanding = \"../Injection/index_partial\" if @partial_role==\'injection\'\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n%>\r\n\r\n<script>\r\n    \r\n$.ajax({\r\n  url: \"<%=landing%>\",\r\n  cache: false\r\n})\r\n .done(function( html ) {\r\n    $( \"#index_panel\" ).html( html );\r\n  });\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-01-06 13:23:09','2016-01-06 13:23:09','',''),(2008,'index',666,2,'<%\r\n@tb = Time.now\r\nmodule_name = @current_project.name\r\nif params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\nend\r\nif session[module_name]\r\n	params[:date] = session[module_name][:date]\r\nend\r\nunless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\nend\r\n\r\nif session[:owner].nil?\r\n    session[:owner] = false\r\nend\r\n\r\nif @current_role==\'developer\'\r\n    session[:owner] = true\r\n    session[:pin] = \'\'\r\nend\r\n\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n    \r\n    if session[:pin].nil?\r\n        r_user = model[:user].where(:login=>@current_user.login.to_s).first\r\n        if r_user[:pin]\r\n            session[:pin] = r_user[:pin].to_s\r\n        else\r\n            session[:pin] = \'\'\r\n        end\r\n    end\r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n\r\n    \r\n    provider = models[:provider].where(:login=>@current_user.login).first\r\n    if provider\r\n      s_provider = provider.id.to_s\r\n    end\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn].upcase if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n    # PIN Section\r\n    in_pin = nil\r\n    if p = params[:record]\r\n        in_pin = p[:pin]\r\n        if p[:patient_id] != \'\' and in_pin == session[:pin] and p[:mode] == \'delete\'\r\n            destroy_url = \"destroy?mode=patient&id=\\\\#{p[:patient_id]}\".html_safe\r\n            return_url  = \"&return=\\\\#{request.fullpath}\".html_safe\r\n%>\r\n<script>\r\n                url = \"<%= destroy_url %><%= return_url %>\";\r\n                window.location = url;\r\n</script>\r\n<%\r\n        elsif p[:mode] == \'unlock\' and in_pin == session[:pin]\r\n            session[:owner] = true\r\n        elsif p[:mode] == \'lock\'\r\n            session[:owner] = false\r\n        end\r\n    end\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       My Patients\r\n       <span style=\'float:right\'>\r\n       <% if session[:owner] %>\r\n                <%= link_to \'<i class=\"splashy-document_a4\"></i> Reports\'.html_safe,\"../Home/report\", :class=>\'btn btn-mini\' %> | \r\n                <%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \"\\\\#{params[:opt]}?record[mode]=lock\", :class=>\'btn btn-mini btn-warning\' %>\r\n                <!--<%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \'javascript:lock_unlock(\"lock\")\', :class=>\'btn btn-mini btn-warning\' %>-->\r\n                <% else %>\r\n                <%=link_to \'<i class=\"splashy-lock_large_unlocked\"></i> Unlock\'.html_safe, \'javascript:lock_unlock(\"unlock\");\', :class=>\'btn btn-mini btn-warning\' %>\r\n        <% end %>\r\n        <!--\r\n        <a href=\'/esm/cusys/thks/Consignment-TH.pdf\' class=\'btn btn-mini\' target=\'_blank\'>\r\n            <i class=\"splashy-document_a4_marked\"></i>\r\n            Consignment (TH)\r\n        </a>\r\n        -->\r\n    </span>\r\n    </div>  \r\n    \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\"../Home/\\\\#{params[:opt]}\",:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n\r\n<!--           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n            </div>\r\n            </span>\r\n-->            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n        <% if @current_role==\'developer\' %>    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surgeon :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n            </div>\r\n            </span>\r\n        <% end %>    \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\" style=\'width:300px\'> \r\n                <label class=\"field-label\">\r\n                   &nbsp;\r\n                </label> \r\n                \r\n                \r\n                <div class=\"field-input\" style=\'width:200px\'>\r\n                     <%=f.submit \'Search\', :class=>\'btn btn-success\'%> \r\n                     <% if !session[:owner] %>\r\n                     <%= link_to \'Show All\', \"javascript:show_all()\", :class=>\'btn btn-warning\', :style=>\'margin-top:5px\' %>\r\n                     <% end %>\r\n                     <!--<%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>-->\r\n                </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            <div class=\"field-input\">\r\n            <%\r\n            # Home/patient_record?id=5533e537790f9b01c2000006\r\n                # add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n                if s_provider \r\n                    # add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                    add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                end\r\n                \r\n            %>\r\n              \r\n                 <!--<%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>-->\r\n            </div>\r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        </div>\r\n        <div class=\"row-fluid\"></div>\r\n \r\n<strong>\r\n<%\r\n    rs = []\r\n    if !search_patient and params[:select].nil?\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n    	    if (session[:pin] == in_pin) or session[:owner]\r\n                rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n            else\r\n                \r\n            end\r\n        else\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\").all\r\n    	end\r\n    %>\r\n    <!--ALL : <%= rs.size %>-->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name, :last_name=>s_last_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        # 	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n            keys << {k.to_sym=>v}\r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n        patients = patient_model.where(criteria).all\r\n        # patients = patient_model.where(criteria).limit(20).all\r\n	    # maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}\r\n        # aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     	    rs = module_model.where(:patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\"\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT : <%= rs.size %>-->\r\n    <%\r\n    elsif params[:date]\r\n        require \'date\'\r\n        dddd = Date.parse(params[:date])\r\n	    conds = {:date.gte=>dddd.at_beginning_of_day,:date.lt=>dddd.end_of_day, :module_name=>\"\\\\#{@current_project.name}#provider\"}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n            conds.merge! :module_id=>s_provider \r\n            # conds[:module_id] = s_provider\r\n            # conds[:module_name] = @current_project.name + \"#provider\"\r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n        rs = module_model.where(conds).all\r\n        # aps = ap_model.all(conds)\r\n    	# filter provider\r\n    # 	if s_provider and s_provider != \'\'\r\n     	  #  conds[:module_id] = s_provider\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    #  	else\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    # 	end\r\n    	\r\n    # 	rs = module_model.all(conds)\r\n        # rs = module_model.all\r\n\r\n    %>\r\n    <!--DATE : <%=rs.size%> | <%= conds %>-->\r\n    <%\r\n    end # end if\r\n%>\r\n</strong>\r\n<!--<br/>-->\r\n<!--<br/>-->\r\n<%\r\nm_procedure = models[:procedure].all\r\nmap_proc = {}\r\nfor m in m_procedure do\r\n    map_proc[m.id] = m\r\nend\r\n\r\nm_provider  = models[:provider].all\r\nmap_prov = {}\r\nfor m in m_provider do \r\n    map_prov[m.id.to_s] = m[:name]\r\nend\r\n\r\n# pat_ids = rs.collect{|i| i.id}\r\n# pa_pat  = patient_model.find(pat_ids)\r\n# pat_map = pa_pat.group_by{|i| i.id.to_s}\r\n\r\n# mod_app = module_model.where(:patient_id=>pat_ids, :module_name=>\"\\\\#{@current_project.name}#appointment\").all\r\n# pat_app = mod_app.group_by{|i| i[:patient_id].to_s}\r\n# par_ids = mod_app.collect{|i| i.id}\r\n# app_ids = mod_app.collect{|i| i[:module_id]}\r\n# aa_app  = get_model[:appointment].find(app_ids)\r\n# app_map = aa_app.group_by{|i| i.id.to_s}\r\n\r\nresult = rs.collect do |i|\r\n    pat_id = i[:patient_id]\r\n    m_patient = patient_model.find(i[:patient_id].to_s)\r\n    # m_patient = pat_map[i[:patient_id].to_s][0] if pat_map[i[:patient_id]]\r\n    \r\n    # patient_name = m_patient[:prefix_name] + m_patient[:first_name] + \" \" + m_patient[:last_name]\r\n    patient_name = \"\\\\#{m_patient[:prefix_name]}\\\\#{m_patient[:first_name]}   \\\\#{m_patient[:last_name]}\"\r\n    \r\n    # prov = map_prov[i[:id]]\r\n    m_id = i[:module_id].to_s\r\n    prov = map_prov[m_id]\r\n    \r\n    # prov = nil\r\n    proc_rs = []\r\n    # OLD\r\n    # m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    # for m in m_ap do\r\n    #     ap = models[:appointment].find(m[:module_id])\r\n    #     if ap\r\n    #         proc_rs.push(map_proc[ap[:procedure]])\r\n    #     end\r\n    # end\r\n    # NEW\r\n    m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    # m_ap = pat_app[pat_id]\r\n    for m in m_ap do\r\n        ap = models[:appointment].find(m[:module_id])\r\n        # ap = app_map[m[:module_id].to_s][0] if app_map[m[:module_id]]\r\n        if ap\r\n            # proc_rs.push(map_proc[ap[:procedure]])\r\n            procedure = map_proc[ap[:procedure]]\r\n            if procedure.nil?\r\n                next\r\n            end\r\n            code = procedure[:code]\r\n            name = procedure[:name]\r\n            m_code = \"\\\\#{@current_project.name}#\\\\#{code}\"\r\n            m_tmp = module_model.where(:module_name=>m_code, :parent_id=>m.id).first\r\n            side = \'-\'\r\n            if m_tmp\r\n                rec = models[code.to_sym].find(m_tmp[:module_id])\r\n                if rec[:side] == \'1\'\r\n                    side = \'L\'\r\n                elsif rec[:side] == \'2\'\r\n                    side = \'R\'\r\n                end\r\n            end\r\n            # txt = name + \" (\" + side + \") \"\r\n            op_txt = \"op : \\\\#{rec[:operation_date]}\" if rec\r\n            txt = \"\\\\#{name} (\\\\#{side}) <span style=\'float:right\'>\\\\#{op_txt}</span>\".html_safe\r\n            \r\n            if @current_role == \'developer\'\r\n                m_tmp = module_model.where(:parent_id=>m.id).collect{|i| i if i[:module_name].include? \'follow\'}\r\n                txt += \"[\" + m_tmp.count.to_s + \"]\"\r\n            end\r\n            \r\n            proc_rs.push(txt)\r\n        end\r\n    end\r\n    \r\n    proc_txt = \'<center><font color=\"red\">-- Create New --</font></center>\'\r\n    if !proc_rs.empty?\r\n        proc_txt = \'\'\r\n        for x in proc_rs do \r\n            if proc_rs.last == x\r\n                proc_txt += \"<div class=\'row-fluid\' style=\'float:left;padding: 0.5em 0 0.5em 0;\'>\\\\#{x.to_s}</div>\"\r\n            else\r\n                proc_txt += \"<div class=\'row-fluid\' style=\'float:left;padding: 0.5em 0 0.5em 0;border-bottom: 1px solid gray;\'>\\\\#{x.to_s}</div>\"\r\n            end\r\n            # proc_txt += \"<div class=\'row-fluid\' style=\'float:left;padding: 0.5em 0 0.5em 0;\'>\\\\#{x.to_s}</div>\"\r\n        end\r\n    end\r\n    action = \' \'\r\n    action += link_to(\'Detail\',\"patient_record?id=\\\\#{i[:patient_id]}\",:class=>\'btn btn-info\')\r\n    action += \" \"\r\n    action += link_to(\'\', \"../../www/Patient/edit?id=\\\\#{m_patient.id}&return=\\\\#{request.fullpath}\", :class=>\'splashy-contact_blue_edit\').html_safe\r\n    action += \" \"\r\n    if session[:owner]\r\n        action += link_to(\'\', \"\", :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{m_patient.id}\'); return false;\")\r\n    else\r\n        action += link_to(\'\', \"\", :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_pin(\'\\\\#{m_patient.id}\'); return false;\")\r\n    end\r\n    action += \" \"\r\n    \r\n    {:date=>i[:date], :hn=>m_patient[:hn], :name=>patient_name, :pid=>i[:patient_id], :procedure=>proc_txt, :action=>action, :provider=>prov}\r\nend\r\ncount = 1\r\nlabels = {:no=>\'No.\', :date=>\'Added Date\', :hn=>\'HN\', :name=>\'Patient Name\', :procedure=>\'Previous Procedure\', :action=>\'Action\'}\r\nfield_select = [:no, :date, :hn, :name, :procedure, :action]\r\n\r\nif @current_role == \'developer\'\r\n    labels[:provider] = \'Provider\'\r\n    field_select.insert(4, :provider)\r\nend\r\nresult = result.sort_by{|i| i[:date]}.reverse\r\n%>\r\n        \r\n        <!--<div class=\"row-fluid\">-->\r\n        <!--    <div style=\"padding-left:10px;display:block;vertical-align:middle\">-->\r\n        <!--        All Patient(s) : <v><%= result.count if result %></v> <%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>-->\r\n        <!--    </div>-->\r\n        <!--</div>-->\r\n        <!--<br/>-->\r\n        <div class=\"row-fluid\">\r\n            <br/>\r\n            <div class=\"\" style=\"float:left;margin-left:10px\">\r\n                All Patient(s) : <span style=\"color:blue\"><%= result.count if result %></span>\r\n                <%=link_to \'<i class=\"splashy-contact_blue_add\"></i> Add Patient\'.html_safe, add_patient, :class=>\'btn btn-info btn-mini\', :style=>\'margin-left:10px\'%>\r\n            </div>\r\n            <% if false %>\r\n            <div class=\"\" style=\"float:right;margin-right:10px\">\r\n                <%=link_to \'<i class=\"splashy-sprocket_light\"></i> Setting\'.html_safe, \'../Setting/index\', :class=>\'btn btn-mini\' %> | \r\n                <% if session[:owner] %>\r\n                <%= link_to \'<i class=\"splashy-document_a4\"></i> Reports\'.html_safe,\"../Home/report\", :class=>\'btn btn-mini\' %> | \r\n                <%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \"\\\\#{params[:opt]}?record[mode]=lock\", :class=>\'btn btn-mini btn-warning\' %>\r\n                <!--<%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \'javascript:lock_unlock(\"lock\")\', :class=>\'btn btn-mini btn-warning\' %>-->\r\n                <% else %>\r\n                <%=link_to \'<i class=\"splashy-lock_large_unlocked\"></i> Unlock\'.html_safe, \'javascript:lock_unlock(\"unlock\");\', :class=>\'btn btn-mini btn-warning\' %>\r\n                <% end %>\r\n            </div>\r\n            <% end %>\r\n            <br/>\r\n        </div>\r\n        \r\n        <div id=\"result-panel\" style=\"padding:10px\">\r\n<% if result.count > 1 or session[:owner] %>\r\n            <%# tabular :data=>result, :model=>field_select, :labels=>labels, :col_width=>{:no=>50} do |row,out| %>\r\n            <%= tabular :data=>result, :model=>field_select, :labels=>labels, :col_width=>{:no=>80, :procedure=>300} do |row,out|\r\n                    out[0] = \"<center>\" + count.to_s+\".</center>\"\r\n                    out[0] = out[0].html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n            %>\r\n<% elsif result.count == 1  and search_patient %>\r\n<script>\r\n    window.location = \"patient_record?id=<%= result[0][:pid] %>\";\r\n</script>\r\n<% \r\n    else \r\n        if request.post? and !session[:owner]\r\n%>\r\n                        <div style=\'margin: auto;width:60%;\'>\r\n                            <div class=\"alert\">\r\n								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n								<strong>Invalid Private Password.</strong> Please try again or contact administrator for setting your private password.\r\n							</div>\r\n							<div class=\'clear\'></div>\r\n						</div>\r\n<%\r\n        end\r\n%>\r\n            <center><font size=\'2.5em\'><strong>Search Patient to continue.</strong></font></center>\r\n<% \r\n    end\r\n%>\r\n        </div>\r\n        \r\n    </div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function confirm_pin(id) {\r\n        \r\n    }\r\n\r\n    function confirm_delete(id) {\r\n        // destroy?id=\\\\#{m_patient.id}&mode=patient&return=\\\\#{request.fullpath}\r\n<%\r\n    destroy_url = \"destroy?mode=patient&id=\".html_safe\r\n    return_url  = \"&return=\\\\#{request.fullpath}\".html_safe\r\n%>\r\n        if (confirm(\"Do you want to delete patient data ?\") == true) {\r\n            if (confirm(\"All of patient data will be lost\") == true) {\r\n                url = \"<%= destroy_url %>\" + id + \"<%= return_url %>\";\r\n                window.location = url;\r\n            }\r\n        }\r\n    }\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<!--\r\n<div class=\"alert \">\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n</div>\r\n-->\r\n<script>\r\n\r\n    <%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    user = model[:user].where(:login=>@current_user.login).first\r\n    \r\n    %>\r\n    \r\n    function access(target){\r\n        \r\n        var pin = prompt(\"Please enter PIN\", \"\");\r\n        if( \'<%= user ? user.pin : \'-\'%>\'==pin){\r\n            window.location = target\r\n        }\r\n        \r\n        \r\n    }\r\n    \r\n</script>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n\r\n<!--\r\n\r\n    Modal\r\n\r\n-->\r\n\r\n<div class=\"modal hide fade\" id=\"modal-pin\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"close\" style=\"float:right;\"  data-dismiss=\"modal\">X</a>\r\n        <h3>Private Access</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"pin\" class=\"  portlet \" style=\"border:0px solid blue;width:250px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Please input your private password : </label></span>	\r\n                    <input type=\"password\" name=\"record[pin]\" id=\"data-pin\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n            <%= f.hidden_field :mode, :id=>\'data-mode\', :value=>\'\' %>\r\n            <%= f.hidden_field :patient_id, :id=>\'data-patient_id\', :value=>\'\' %>\r\n            <%= f.submit \'Submit\', :class=>\'btn btn-info\' %>\r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n    function pin() {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function show_all() {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(\'show\');\r\n    }\r\n    function lock_unlock(mode) {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(mode);\r\n    }\r\n    function confirm_pin(id) {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(\'delete\');\r\n        $(\'#data-patient_id\').val(id);\r\n    }\r\n    <% if false %>\r\n    function check_pin() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    <% end %>\r\n    $(document).ready(function(){\r\n        $(\'#btn-pin\').click(pin);\r\n    });\r\n</script>\r\n<%\r\n    if @current_role==\'developer\' or @current_user.login==\'ehr@esm-solution.com\'\r\n%>\r\n<hr/>\r\nProcessing Time : <%= Time.now - @tb %>. xxxx\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2016-01-06 23:20:25','2016-01-06 23:20:25','index',''),(2009,'registration_role',856,3,'\r\n<div class=\"row-fluid\">\r\n\r\n\r\n\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n  \r\n  \r\n        <div class=\"alert alert-block alert-info\" >\r\n              \r\n\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" ><i class=\"splashy-add\"></i><br />New patient</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" ><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" ><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n<span style=\"float:right\">\r\nStation : admin\r\n<br/>\r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> \r\n\r\n       \r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n</span>\r\n\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n </div><br/>',NULL,NULL,NULL,'2016-01-07 01:41:41','2016-01-07 01:41:41','registration_role',''),(2010,'exam_role',856,3,'<h1>Exam</h1>',NULL,NULL,NULL,'2016-01-07 01:42:21','2016-01-07 01:42:21','exam_role',''),(2011,'stations',856,2,'<div id= \"index_panel\"></div>\r\nLoading..\r\n<script>\r\n$.ajax({\r\n  url: \"<%=\'index_partial\'%>\",\r\n  cache: false\r\n})\r\n .done(function( html ) {\r\n    $( \"#index_panel\" ).html( html );\r\n  });\r\n</script>\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-01-07 01:46:18','2016-01-07 01:46:18','stations',''),(2012,'index_partial',859,3,'<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\