f pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n </div><br/>',NULL,NULL,NULL,'2016-01-07 03:07:17','2016-01-07 03:07:17','index_partial',''),(2013,'index_partial',856,3,'<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<div class=\"row-fluid\">\r\n\r\n\r\n\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n  \r\n  \r\n        <div class=\"alert alert-block alert-info\" >\r\n              \r\n\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" ><i class=\"splashy-add\"></i><br />New patient</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" ><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" ><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n<span style=\"float:right\">\r\nStation : admin\r\n<br/>\r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> \r\n\r\n       \r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n</span>\r\n\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{ hn patient}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Action\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span3\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"span3\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"span3\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"span3\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n </div><br/>',NULL,NULL,NULL,'2016-01-07 03:19:24','2016-01-07 03:19:24','index_partial',''),(2014,'index_partial',860,3,'<h1>Exam</h1>',NULL,NULL,NULL,'2016-01-07 03:25:49','2016-01-07 03:25:49','index_partial',''),(2015,'index_partial',861,3,'<h1>OPD service</h1>',NULL,NULL,NULL,'2016-01-07 06:26:01','2016-01-07 06:26:01','index_partial',''),(2016,'index_partial',863,1,'<h1>Billing and Accounting</h1>',NULL,NULL,NULL,'2016-01-07 06:26:42','2016-01-07 06:26:42','index_partial',''),(2017,'index_partial',862,3,'<h1>Couselling</h1>',NULL,NULL,NULL,'2016-01-07 06:27:06','2016-01-07 06:27:06','index_partial',''),(2018,'index_partial',864,3,'<h1>Injection</h1>',NULL,NULL,NULL,'2016-01-07 06:28:44','2016-01-07 06:28:44','index_partial',''),(2019,'index_partial_2',862,3,'',NULL,NULL,NULL,'2016-01-07 06:29:33','2016-01-07 06:29:33','index_partial_2','');
INSERT INTO `esm_operations` VALUES (2020,'dr_report_excel',805,3,'<%\r\n    response.headers[\"Content-Type\"] = \"application/xls\"\r\n    response.headers[\"Content-disposition\"] = \"attachment; filename=DoctorOT-\\\\#{Time.now.to_i}.xls\"\r\n    \r\n    tb = Time.now \r\n    \r\n    def map_parent_object(m_arr = [])\r\n        rs = {}\r\n        m_arr.each do |i|\r\n            rs[i[:parent_id].to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n%>\r\n<%= render :inline=>this.init %>\r\n<%\r\n    rs = {}\r\n    res = {}\r\n    ars = []\r\n    pat_mod = {}\r\n  \r\n    ars_rec = 0 \r\n    app_date = Time.now\r\n    if q = params[:query]\r\n        sdate = q[:sdate]\r\n        edate = q[:edate]\r\n        app_date = sdate\r\n       \r\n        rs = get_appointment_by_date(sdate, edate).sort_by{|i|  (i[:start] == \'\' or i[:start] == nil) ? \'00:00\' : i[:start].strftime(\'%H:%M\')}\r\n        app_ids = rs.collect{|i| i.id.to_s}\r\n        pat_mod = get_patient_module_by_appointment_ids(app_ids)\r\n        par_ids = pat_mod.collect{|i| i.id.to_s}\r\n        pat_ids = pat_mod.collect{|i| i[:patient_id].to_s}\r\n        mod_pre = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#pre_anesthetic\")\r\n        mod_pos = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#post_anesthetic\")\r\n        ids_pre = get_module_id_array(mod_pre)\r\n        ids_pos = get_module_id_array(mod_pos)\r\n        a_pre = @models[:pre_anesthetic].find(ids_pre)\r\n        a_pos = @models[:post_anesthetic].find(ids_pos)\r\n        \r\n        a_pat = @m_pat.find(pat_ids)\r\n        \r\n        par_app = get_module_id_map(pat_mod)\r\n        par_pre = map_parent_object(mod_pre)\r\n        par_pos = map_parent_object(mod_pos)\r\n        map_pre = get_map(a_pre)\r\n        map_pos = get_map(a_pos)\r\n        \r\n        map_pat = get_map(a_pat)\r\n        map_ward = get_map(@models[:ward].all)\r\n        # map_room = get_map(@models[:or_room].all)\r\n        \r\n        map_anes_tech = {\'\'=>\'Undefined\',\'1\'=>\'General anesthesia (balanced technique)\', \'2\'=>\'General anesthesia (Inhalation technique)\',\'3\'=>\'General anesthesia (TIVA)\',\'4\'=>\'Monitor anesthetic care\',\'5\'=>\'Regional anesthesia\',\'6\'=>\'Nerve Block\',\'7\'=>\'Combined general anesthesia and nerve block\',\'8\'=>\'Combined general anesthesia and regional anesthesia\',\'9\'=>\'GA due to RA/Nerve block fail\'}\r\n        map_pacu = {nil=>\'Undefined\', \'\'=>\'Undefined\',\'1\'=>\'OR\',\'2\'=>\'RR\',\'3\'=>\'WARD\',\'4\'=>\'ICU\'}\r\n        \r\n        res = par_pre\r\n        rs.each do |i|\r\n            tmp = {}\r\n            pm_app = par_app[i.id.to_s]\r\n            # tmp[:par_id] = par_id.id\r\n            pm_pre = par_pre[pm_app.id.to_s]\r\n            pm_pos = par_pos[pm_app.id.to_s]\r\n            \r\n            if  pm_pos.nil?\r\n                next\r\n            end\r\n            \r\n            # patient info\r\n            pat_id = pm_app[:patient_id].to_s\r\n            pat = map_pat[pat_id]\r\n            \r\n            tmp[:hn] = pat[:hn]\r\n            tmp[:name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]}  \\\\#{pat[:last_name]}\"\r\n            \r\n            today = i[:date]\r\n            if pat[:birth_date]\r\n                d = Date.new(today.year, pat[:birth_date].month,  pat[:birth_date].day)\r\n                age = d.year - pat[:birth_date].year - (d > today ? 1 : 0)\r\n                tmp[:age] = age\r\n            else\r\n                tmp[:age] = \'-\'\r\n            end\r\n            \r\n            # appointment\r\n            tmp[:diag] = i[:diagnosis]\r\n            tmp[:operation] = i[:operation]\r\n            tmp[:ward] = \'N/A\'\r\n            tmp[:ward] = (i[:ward]==\'\' or i[:ward].nil?) ? \'N/A\' : map_ward[i[:ward]][:name] if map_ward[i[:ward]]\r\n            \r\n            tmp[:surgeon] = (i[:surgeon]==\'\' or i[:surgeon].nil?) ? \'N/A\' : @provider[i[:surgeon]]\r\n            tmp[:ast_surgeon] = (i[:assist]==\'\' or i[:assist].nil?) ? \'N/A\' : @provider[i[:assist]]\r\n            \r\n            tmp[:app_date] = i[:date]\r\n            \r\n            # anesth team\r\n            pre = !pm_pre.nil? ? map_pre[pm_pre[:module_id].to_s] : nil\r\n            pos = map_pos[pm_pos[:module_id].to_s]\r\n            # tmp[:debug] = \"PRE : \\\\#{pre.to_json.html_safe}<br/>POS : \\\\#{pos.to_json.html_safe}\"\r\n            \r\n            if pre\r\n                tmp[:team_pre_1] = (pre[:anesthesiologist]==\'\' or pre[:anesthesiologist].nil?) ? \'N/A\' : @provider[pre[:anesthesiologist].to_s]\r\n                tmp[:team_pre_2] = (pre[:nurse]==\'\' or pre[:nurse].nil?) ? \'N/A\' : @provider[pre[:nurse].to_s]\r\n            else\r\n                tmp[:team_pre_1] = \'N/A\'\r\n                tmp[:team_pre_2] = \'N/A\'\r\n            end\r\n            \r\n            tmp[:team_pos_1] = (pos[:anesthesiologist]==\'\' or pos[:anesthesiologist].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist].to_s]\r\n            tmp[:team_pos_2] = (pos[:nurse_anesthetist]==\'\' or pos[:nurse_anesthetist].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetist].to_s]\r\n            \r\n            # intra-op\r\n            tmp[:dur_time] = \'N/A\'\r\n            tmp[:dur_anesthesiologist] = \'N/A\'\r\n            tmp[:dur_anesthetist] = \'N/A\'\r\n            dur_off = (pos[:anesthetic_official_duration]==\'\' or pos[:anesthetic_official_duration].nil?) ? 0 : pos[:anesthetic_official_duration].to_i\r\n            dur_non = (pos[:anesthetic_non_official_duration]==\'\' or pos[:anesthetic_non_official_duration].nil?) ? 0 : pos[:anesthetic_non_official_duration].to_i\r\n            \r\n            rec_non = (pos[:recovery_non_official_time_min]==\'\' or pos[:recovery_non_official_time_min].nil?) ? 0 : pos[:recovery_non_official_time_min].to_i\r\n\r\n            \r\n              # anesthetic_official_time_start anesthetic_official_duration\r\n            if rec_non>0\r\n                \r\n                ts = pos[:recovery_non_official_time_start].strftime(\'%H:%M\') if pos[:recovery_non_official_time_start]\r\n                te = pos[:recovery_non_official_time_end].strftime(\'%H:%M\') if pos[:recovery_non_official_time_end]\r\n                \r\n                \r\n                tmp[:rec_non_anesthesiologist] = (pos[:recovery_anesthesiologist_non_official]==\'\' or pos[:recovery_anesthesiologist_non_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_non_official].to_s]\r\n                a1 = (pos[:recovery_anesthetic_non_official_1]==\'\' or pos[:recovery_anesthetic_non_official_1].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_1].to_s]\r\n                a2 = (pos[:recovery_anesthetic_non_official_2]==\'\' or pos[:recovery_anesthetic_non_official_2].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_2].to_s]\r\n                tmp[:rec_non_nurse] = \"\\\\#{a1}, \\\\#{a2}\"\r\n                \r\n                # OT Report\r\n                tmp[:xtime_rec] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes_rec] = tmp[:rec_non_anesthesiologist]\r\n                tmp[:xnur1_rec] = a1\r\n                tmp[:xnur2_rec] = a2\r\n                ars_rec += 1\r\n            end\r\n            \r\n            if dur_non==0 and dur_off > 0\r\n                next\r\n                ds = pos[:anesthetic_official_date_start].strftime(\'%d/%m/%Y\')\r\n                de = pos[:anesthetic_official_date_end].strftime(\'%d/%m/%Y\')\r\n                ts = pos[:anesthetic_official_time_start].strftime(\'%H:%M\')\r\n                te = pos[:anesthetic_official_time_end].strftime(\'%H:%M\')\r\n                \r\n                tmp[:dur_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{dur_off} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                tmp[:dur_anesthetist] = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n            elsif dur_non > 0 #and dur_off==0\r\n                ds = pos[:anesthetic_nonofficial_date_start].strftime(\'%d/%m/%Y\') if pos[:anesthetic_nonofficial_date_start]\r\n                de = pos[:anesthetic_nonofficial_date_end].strftime(\'%d/%m/%Y\') if pos[:anesthetic_nonofficial_date_end]\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\') if pos[:anesthetic_nonofficial_time_start]\r\n                te = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\') if pos[:anesthetic_nonofficial_time_end]\r\n                \r\n                tmp[:dur_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{dur_non} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                tmp[:dur_anesthetist] = \"\\\\#{a1}, \\\\#{a2}\"\r\n                \r\n                # OT Report\r\n                tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes] = tmp[:dur_anesthesiologist]\r\n                tmp[:xnur1] = a1\r\n                tmp[:xnur2] = a2\r\n            elsif dur_non > 0 and dur_off > 0\r\n                ds_off = pos[:anesthetic_official_date_start]\r\n                de_off = pos[:anesthetic_official_date_end]\r\n                ds_non = pos[:anesthetic_nonofficial_date_start]\r\n                de_non = pos[:anesthetic_nonofficial_date_end]\r\n                \r\n                ts_off = pos[:anesthetic_official_time_start].strftime(\'%H:%M\') if  pos[:anesthetic_official_time_start]\r\n                te_off = pos[:anesthetic_official_time_end].strftime(\'%H:%M\') if  pos[:anesthetic_official_time_end]\r\n                ts_non = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\') if  pos[:anesthetic_nonofficial_time_start]\r\n                te_non = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\') if  pos[:anesthetic_nonofficial_time_end]\r\n                \r\n                ds = ds_off\r\n                de = de_non\r\n                ts = ts_off\r\n                te = te_non\r\n                if ds_off == ds_non and de_off == de_non\r\n                    if ts_non < ts_off\r\n                        ts = ts_non\r\n                        te = te_off\r\n                    end\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\" \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                elsif de_non > ds_off\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"  \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                elsif ds_non < de_off\r\n                    ds = ds_non\r\n                    de = de_off\r\n                    ts = ts_non\r\n                    te = te_off\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"    \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                else\r\n                    tmp[:dur_time] = \"official time : (\\\\#{ds_off} \\\\#{ts_off} - \\\\#{de_off} \\\\#{te_off}) / non-official time : (\\\\#{ds_non} \\\\#{ts_non} - \\\\#{de_non} \\\\#{te_non}) [\\\\#{dur_off + dur_non} mins] \"\r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts_non}-\\\\#{te_non}\"\r\n                end\r\n\r\n                off_a0 = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                off_a1 = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n                non_a0 = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                non_a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                non_a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                \r\n                tmp[:dur_anesthesiologist] = \"\\\\#{off_a0} (official time) / \\\\#{non_a0} (non-official time)\"\r\n                tmp[:dur_anesthetist] = \"\\\\#{off_a1} (official time) / \\\\#{non_a1}, \\\\#{non_a2} (non-official time)\"\r\n                \r\n                # OT Report\r\n                tmp[:xanes] = non_a0\r\n            else\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\')\r\n                te = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\')\r\n                if ts==te\r\n                    next\r\n                end\r\n                # OT Report\r\n                tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes] = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n            end\r\n            \r\n            # tmp[:anes_tech] = map_anes_tech[pos[:anesth_technique]]\r\n            # tmp[:asa_status] = pos[:asa_status] == \'\' ? \'Undefined\' : pos[:asa_status]\r\n            # tmp[:asa_type] = pos[:asa_type] == \'\' ? \'-\' : pos[:asa_type]\r\n\r\n            # PACU\r\n            # tmp[:rr_time] = \'N/A\'\r\n            # tmp[:rr_anesthesiologist] = \'N/A\'\r\n            # tmp[:rr_anesthetist] = \'N/A\'\r\n            \r\n            # rr_place = pos[:recovery_place]\r\n            # tmp[:rr_place] = map_pacu[rr_place]\r\n            \r\n            # rr_off = (pos[:recovery_time]==\'\' or pos[:recovery_time].nil?) ? 0 : pos[:recovery_time].to_i\r\n            # rr_non = (pos[:recovery_non_official_time_min]==\'\' or pos[:recovery_non_official_time_min].nil?) ? 0 : pos[:recovery_non_official_time_min].to_i\r\n            # if rr_non==0 and rr_off > 0\r\n            #     ds = pos[:recovery_date_start].strftime(\'%d/%m/%Y\')\r\n            #     de = pos[:recovery_date_end].strftime(\'%d/%m/%Y\')\r\n            #     ts = pos[:recovery_time_start].strftime(\'%H:%M\')\r\n            #     te = pos[:recovery_time_end].strftime(\'%H:%M\')\r\n                \r\n            #     tmp[:rr_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{rr_off} mins)\"\r\n            #     tmp[:rr_anesthesiologist] = (pos[:recovery_anesthesiologist_official]==\'\' or pos[:recovery_anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_official].to_s]\r\n            #     tmp[:rr_anesthetist] = (pos[:recovery_anesthetic_official]==\'\' or pos[:recovery_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_official].to_s]\r\n            # elsif rr_non > 0 and rr_off==0\r\n            #     ds = pos[:recovery_non_official_date_start].strftime(\'%d/%m/%Y\')\r\n            #     de = pos[:recovery_non_official_date_end].strftime(\'%d/%m/%Y\')\r\n            #     ts = pos[:recovery_non_official_time_start].strftime(\'%H:%M\')\r\n            #     te = pos[:recovery_non_official_time_end].strftime(\'%H:%M\')\r\n                \r\n            #     tmp[:rr_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{rr_non} mins)\"\r\n            #     tmp[:rr_anesthesiologist] = (pos[:recovery_anesthesiologist_non_official]==\'\' or pos[:recovery_anesthesiologist_non_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_non_official].to_s]\r\n            #     a1 = (pos[:recovery_anesthetic_non_official_1]==\'\' or pos[:recovery_anesthetic_non_official_1].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_1].to_s]\r\n            #     a2 = (pos[:recovery_anesthetic_non_official_2]==\'\' or pos[:recovery_anesthetic_non_official_2].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_2].to_s]\r\n            #     tmp[:rr_anesthetist] = \"\\\\#{a1}, \\\\#{a2}\"\r\n            # elsif rr_non > 0 and rr_off > 0\r\n            #     ds_off = pos[:recovery_date_start]\r\n            #     de_off = pos[:recovery_date_end]\r\n            #     ds_non = pos[:recovery_time_start]\r\n            #     de_non = pos[:recovery_time_end]\r\n                \r\n            #     ts_off = pos[:recovery_non_official_date_start].strftime(\'%H:%M\')\r\n            #     te_off = pos[:recovery_non_official_date_end].strftime(\'%H:%M\')\r\n            #     ts_non = pos[:recovery_non_official_time_start].strftime(\'%H:%M\')\r\n            #     te_non = pos[:recovery_non_official_time_end].strftime(\'%H:%M\')\r\n                \r\n            #     ds = ds_off\r\n            #     de = de_non\r\n            #     ts = ts_off\r\n            #     te = te_non\r\n            #     if ds_off == ds_non and de_off == de_non\r\n            #         if ts_non < ts_off\r\n            #             ts = ts_non\r\n            #             te = te_off\r\n            #         end\r\n            #         tmp[:rr_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{rr_off + rr_non} mins)\"    \r\n            #     elsif de_non > ds_off\r\n            #         tmp[:rr_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{rr_off + rr_non} mins)\"    \r\n            #     elsif ds_non < de_off\r\n            #         ds = ds_non\r\n            #         de = de_off\r\n            #         ts = ts_non\r\n            #         te = te_off\r\n            #         tmp[:rr_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{rr_off + rr_non} mins)\"    \r\n            #     else\r\n            #         tmp[:rr_time] = \"official time : (\\\\#{ds_off} \\\\#{ts_off} - \\\\#{de_off} \\\\#{te_off}) / non-official time : (\\\\#{ds_non} \\\\#{ts_non} - \\\\#{de_non} \\\\#{te_non}) [\\\\#{rr_off + rr_non} mins] \"\r\n            #     end\r\n\r\n            #     off_a0 = (pos[:recovery_anesthesiologist_official]==\'\' or pos[:recovery_anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_official].to_s]\r\n            #     off_a1 = (pos[:recovery_anesthetic_official]==\'\' or pos[:recovery_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_official].to_s]\r\n            #     non_a0 = (pos[:recovery_anesthesiologist_non_official]==\'\' or pos[:recovery_anesthesiologist_non_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_non_official].to_s]\r\n            #     non_a1 = (pos[:recovery_anesthetic_non_official_1]==\'\' or pos[:recovery_anesthetic_non_official_1].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_1