mberFormat/>\r\n   <Protection/>\r\n  </Style>\r\n  <Style ss:ID=\"s62\">\r\n   <Font ss:FontName=\"TH SarabunPSK\" x:Family=\"Swiss\" ss:Size=\"16\"\r\n    ss:Color=\"#000000\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s63\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\"/>\r\n   <Font ss:FontName=\"TH SarabunPSK\" x:Family=\"Swiss\" ss:Size=\"16\"\r\n    ss:Color=\"#000000\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s65\">\r\n   <Alignment ss:Vertical=\"Center\"/>\r\n   <Font ss:FontName=\"TH SarabunPSK\" x:Family=\"Swiss\" ss:Size=\"16\"\r\n    ss:Color=\"#000000\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s66\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\"/>\r\n   <Borders>\r\n    <Border ss:Position=\"Bottom\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Left\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Right\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Top\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n   </Borders>\r\n   <Font ss:FontName=\"TH SarabunPSK\" x:Family=\"Swiss\" ss:Size=\"16\"\r\n    ss:Color=\"#000000\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s67\">\r\n   <Alignment ss:Vertical=\"Center\"/>\r\n   <Borders>\r\n    <Border ss:Position=\"Bottom\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Left\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Right\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Top\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n   </Borders>\r\n   <Font ss:FontName=\"TH SarabunPSK\" x:Family=\"Swiss\" ss:Size=\"16\"\r\n    ss:Color=\"#000000\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s68\">\r\n   <Alignment ss:Horizontal=\"Right\" ss:Vertical=\"Center\"/>\r\n   <Font ss:FontName=\"TH SarabunPSK\" x:Family=\"Swiss\" ss:Size=\"16\"\r\n    ss:Color=\"#000000\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s69\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\"/>\r\n   <Borders/>\r\n   <Font ss:FontName=\"TH SarabunPSK\" x:Family=\"Swiss\" ss:Size=\"16\"\r\n    ss:Color=\"#000000\"/>\r\n   <Interior ss:Color=\"#FFFFFF\" ss:Pattern=\"Solid\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s70\">\r\n   <Alignment ss:Vertical=\"Center\" ss:WrapText=\"1\"/>\r\n   <Borders>\r\n    <Border ss:Position=\"Bottom\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Left\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Right\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Top\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n   </Borders>\r\n   <Font ss:FontName=\"TH SarabunPSK\" x:Family=\"Swiss\" ss:Size=\"16\"\r\n    ss:Color=\"#000000\"/>\r\n  </Style>\r\n </Styles>\r\n <Worksheet ss:Name=\"Doctor\">\r\n  <Table ss:ExpandedColumnCount=\"8\" ss:ExpandedRowCount=\"<%= ars.count + 8 + ars_rec %>\" x:FullColumns=\"1\"\r\n   x:FullRows=\"1\" ss:StyleID=\"s62\" ss:DefaultRowHeight=\"15\">\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"24.75\"/>\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"61.5\"/>\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"135\"/>\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"60\" ss:Span=\"1\"/>\r\n   <Column ss:Index=\"6\" ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"120\"/>\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"123.75\"/>\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"97.5\"/>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"21\">\r\n    <Cell ss:MergeAcross=\"7\" ss:StyleID=\"s63\"><Data ss:Type=\"String\">รายงานผู้ป่วยที่ได้รับยาระงับความรู้สึกนอกเวลาราชการ</Data></Cell>\r\n   </Row>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"21\">\r\n    <Cell ss:MergeAcross=\"7\" ss:StyleID=\"s63\"><Data ss:Type=\"String\">ตั้งแต่ <%= params[:query][:sdate] %>  ถึง <%= params[:query][:edate] %>