 \r\n    \r\n    <Row ss:AutoFitHeight=\"0\" ss:Height=\"52.5\">\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= i + 1 %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:app_date].strftime(\"%d/%m/%Y\") %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:name] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:hn] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:xtime_rec] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s70\"><Data ss:Type=\"String\">Post anesthetic care in neurocritical</Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:xanes_rec] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"/>\r\n   </Row>\r\n    \r\n \r\n    <% end %>\r\n    \r\n   \r\n   \r\n<%\r\n    end\r\nend\r\n%>\r\n   <Row ss:AutoFitHeight=\"0\">\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n   </Row>\r\n      <Row ss:AutoFitHeight=\"0\" ss:Height=\"21\">\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s69\"><Data ss:Type=\"String\">____________________</Data></Cell>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n\r\n   </Row>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"21\">\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s69\"><Data ss:Type=\"String\">(นพ.ภูพิงค์ เอกะวิภาต)</Data></Cell>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n\r\n   </Row>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"21\">\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s69\"><Data ss:Type=\"String\">หัวหน้ากลุ่มงานวิสัญญีวิทยา</Data></Cell>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n   </Row>\r\n  </Table>\r\n  <WorksheetOptions xmlns=\"urn:schemas-microsoft-com:office:excel\">\r\n   <PageSetup>\r\n    <Layout x:Orientation=\"Landscape\"/>\r\n    <Header x:Margin=\"0.3\"/>\r\n    <Footer x:Margin=\"0.3\"/>\r\n    <PageMargins x:Bottom=\"0.75\" x:Left=\"0.7\" x:Right=\"0.7\" x:Top=\"0.75\"/>\r\n   </PageSetup>\r\n   <Unsynced/>\r\n   <FitToPage/>\r\n   <Print>\r\n    <ValidPrinterInfo/>\r\n    <PaperSizeIndex>9</PaperSizeIndex>\r\n    <Scale>57</Scale>\r\n    <HorizontalResolution>600</HorizontalResolution>\r\n    <VerticalResolution>0</VerticalResolution>\r\n   </Print>\r\n   <Selected/>\r\n   <Panes>\r\n    <Pane>\r\n     <Number>3</Number>\r\n     <ActiveRow>7</ActiveRow>\r\n     <ActiveCol>2</ActiveCol>\r\n    </Pane>\r\n   </Panes>\r\n   <ProtectObjects>False</ProtectObjects>\r\n   <ProtectScenarios>False</ProtectScenarios>\r\n  </WorksheetOptions>\r\n </Worksheet>\r\n</Workbook>\r\n\r\n',NULL,NULL,NULL,'2016-01-07 06:36:26','2016-01-07 06:36:26','dr_report_excel',''),(2021,'document_name',865,1,'\'fit_test\'',NULL,NULL,NULL,'2016-01-08 03:49:22','2016-01-08 03:49:22',NULL,NULL),(2022,'print_report_fit',866,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  attachment_model = @models[:attachment]\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n \r\n \r\n\r\n\r\n \r\n ml =  @module_model.where(:parent_id=>i.id).all\r\n \r\n diagnosis = \'\'\r\n diagnosis_group = \'\'\r\n provider = providers[ap.provider.to_s]\r\n provider_name = provider.name\r\n attachments = []\r\n#  provider_name = ml.size.to_s\r\n fit_result = \'\'\r\n fm_his = {\'0\'=>\'No\', \'1\'=>\'Yes\'}\r\n ft_tes = {\'-1\'=>\'Neg\', \'1\'=>\'Pos\', \'0\'=>\'N/A\'}\r\n \r\n for x in ml\r\n    if x.module_name==\"\\\\#{@current_project.name}#colono\"\r\n        \r\n        colo = @models[:colono].find(x.module_id)\r\n  \r\n        if colo\r\n            provider_name = colo.id.to_s\r\n            \r\n            provider = providers[colo.endoscopist.to_s]\r\n            provider_name = provider.name\r\n            diagnosis = colo.diagnosis_text\r\n            diagnosis_group = colo.diagnosis_group\r\n            attachments = colo.image\r\n            \r\n        end\r\n    elsif x.module_name == \"\\\\#{@current_project.name}#fit_test\"\r\n        \r\n        fit = @models[:fit_test].find(x.module_id)\r\n        fm  = fm_his[fit[:family_history]]\r\n        ft  = ft_tes[fit[:fit_test]]\r\n        fit_result = \"Family History : <v>\\\\#{fm}</v>, FIT Test : <v>\\\\#{ft}</v>\".html_safe\r\n    end\r\n end\r\n \r\n \r\n\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year}y.\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>ml.collect{|i| i.module_name.split(\'#\')[-1].humanize}.join(\',\'),\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider_name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'attachments\'=>attachments,\r\n    \'age\'=>age,\r\n    \'ml\'=>ml,\r\n    \'diagnosis\'=>diagnosis.html_safe,\r\n    \'diagnosis_group\'=>diagnosis_group.html_safe,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id,\r\n    \'fit_result\'=>fit_result\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\n\r\n\r\nlist = json_data.sort{|a,b| b[\'diagnosis_group\']<=>a[\'diagnosis_group\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n  /*tr.page-break  { display: block; page-break-before: auto; }*/\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>Summary Report\r\n<span style=\"float:right\">Date :  \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th style=\"width:150px\">Name (Age)</th>\r\n    <th>HN</th>\r\n    <th>Procedure</th>\r\n    <th>Diagnosis</th>\r\n    <th>Endoscopist</th>\r\n    <th>Link</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n<% \r\n    sp = {}\r\n    index = 0 \r\n    list.each_with_index do |i,ix|  \r\n        pps = i[\'procedure\'].split(\',\')\r\n        for pp in pps\r\n            if sp.has_key?(pp)\r\n                sp[pp] = sp[pp] + 1\r\n            else\r\n                sp[pp] = 1\r\n            end\r\n        end\r\n    if params[:filter]==nil or (i[\'diagnosis\']!=\'\' and i[\'diagnosis_group\']!=\'0\') \r\n\r\n    \r\n%> \r\n    <tr class=\"page-break\">\r\n    <td><%=index+1%>.</td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%> (<%=i[\'age\']%>)</td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    <td><%=i[\'diagnosis\']%></td>\r\n    <td><%=i[\'provider\']%></td>\r\n    <td><%=link_to(\'Detail\',\"patient_record?id=\\\\#{i[\'id\']}\")%></td>\r\n    </tr>\r\n    \r\n  \r\n    <tr>\r\n    <td colspan=\"7\">\r\n        <%  \r\n        if true\r\n            attachments = attachment_model.find(i[\'attachments\'])[0..4]\r\n        for j in attachments\r\n        %>\r\n        <%= image_tag j.path + \"?thumb=1\", :width=>80, :style=>\'\' %>\r\n        <% end %>\r\n        <% end %>\r\n        <span style=\"padding:50px\"><%= i[\'fit_result\'] %></span>\r\n    </td>    \r\n        \r\n    </tr>\r\n    \r\n    <% \r\n    \r\n    index+=1\r\n    end %>\r\n    <% end %>\r\n</tbody>\r\n  </table><br/>\r\n<% if false %>\r\n<br/>\r\n  <div><strong>Total procedure</strong></div><br/>\r\n<%\r\nsp.keys.each_with_index do |key, index|\r\n%>\r\n<div><%= key %> : <%= sp[key] %></div>\r\n<%\r\nend\r\nend\r\n%>\r\n  </div>\r\n  </div></div></div></div></div>\r\n</body>\r\n</html>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2016-01-08 03:51:29','2016-01-08 03:51:29','print_report_fit',''),(2023,'endoscopist_report',866,2,'<%\r\n    fdate = Date.strptime(\'24/8/2015\', \'%d/%m/%Y\').at_beginning_of_month\r\n    tdate = Date.strptime(\'29/9/2015\', \'%d/%m/%Y\').end_of_month\r\n    \r\n    fdate = Time.utc(fdate.year, fdate.month, fdate.day)\r\n    tdate = Time.utc(tdate.year, tdate.month, tdate.day)\r\n    \r\n    date  = Time.now\r\n    conds = {:created_at.gte=>date.at_beginning_of_day,:created_at.lt=>date.end_of_day}\r\n    # conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n    \r\n    model = get_model\r\n    m_colono = model[:colono]\r\n    a_colono = m_colono.where(conds)\r\n    # m_app = model[:appointment]\r\n    # a_app = m_app.where(:date=> { \'$gt\' => Time.parse(\'2015-08-25\'), \'$lt\' =>  Time.parse(\'2015-08-30\')} )\r\n    \r\n    res = {}\r\n    res[:fdate] = fdate\r\n    res[:tdate] = tdate\r\n    res[:a_colono] = a_colono.count\r\n    \r\n    # a_provider = \r\n%>\r\n<%# a_app.count %>\r\n\r\n<%# m_app.all.to_json.html_safe %>\r\n<div class=\"span12\">\r\n    <div class=\"w-box\">\r\n        <div class=\"w-box-header\">\r\n            <b>Endoscopist Report</b>\r\n        </div>\r\n        <div class=\"w-box-content cnt_a\">\r\n            <%= res.to_json.html_safe %>\r\n        </div>\r\n    </div>\r\n</div>',NULL,NULL,NULL,'2016-01-08 03:52:14','2016-01-08 03:52:14','endoscopist_report',''),(2024,'patient_record',866,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<% \r\n    test = false\r\n    if @current_role == \'developer\' and test \r\n%>\r\n<pre>\r\n    Appointment : <%= ap.to_json.html_safe %><br/>\r\n</pre>\r\n<pre>\r\n    PatientModule : <%= pm.to_json.html_safe %>\r\n</pre>\r\n<% if params[:remove] == \'true\'\r\n    ap.destroy\r\n    pm.destroy\r\n%>\r\n<script>\r\n    window.location = \"index\"\r\n</script>\r\n<% end %>\r\n<% \r\n    if params[:update] == \'true\' \r\n        sname = @current_project.name + \"#\" + params[:sname]\r\n        app_id = params[:app_id]\r\n        \r\n        t_ap = emr_models[:appointment].find(app_id)\r\n        t_pm = patient_module_model.first(:module_id=>t_ap.id.to_s)\r\n        f_pm = patient_module_model.where(:module_name=>sname, :parent_id=>pm.id).first\r\n\r\n        # Move unnessesary record to another appointment_id and patient_id\r\n        # open record page that you need to move (f_pm), \r\n        # use parameter update=true&sname={your_service_name}&app_id={another_appointment}\r\n        \r\n        # if t_pm\r\n        #     f_pm.update_attributes :parent_id=>t_pm.id, :patient_id=>t_pm[:patient_id]\r\n        #     ap = t_ap\r\n        #     pm = t_pm\r\n        # end\r\n%>\r\n<pre>\r\n    AppointmentID : <%= t_pm.to_json.html_safe %><br/>\r\n    <!--ParentID : <%=  %><br/>-->\r\n    Service  : <%= sname %><br/>\r\n    TEST : <%= f_pm.to_json.html_safe %>\r\n</pre>\r\n<%\r\n    end\r\n%>\r\n\r\n<% end %>\r\n<br/>\r\n\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date) if i.date%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\n    pm_fit = patient_module_model.first :module_name=>\"\\#{@current_project.name}#fit_test\", :parent_id=>pm.id, :patient_id=>pm.patient_id\r\n    \r\n    if pm_fit\r\n        r_fit = get_model[:fit_test].find(pm_fit[:module_id])\r\n        fm_his = {\'0\'=>\'No\', \'1\'=>\'Yes\'}\r\n        ft_tes = {\'-1\'=>\'Negative\', \'1\'=>\'Positive\', \'0\'=>\'Not done\'}\r\n%>\r\n<div class=\'alert\'>\r\n    <b>Family History : </b><%= fm_his[r_fit[:family_history]] %>, <b>FIT Test : </b><%= ft_tes[r_fit[:fit_test]] %>\r\n</div>\r\n<% \r\n    end \r\n%>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\#{@current_project.name}#\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\#{i.time.strftime(\"%H:%M\") if i.time } - \\#{i.ref_number}\", \"../\\#{s.name.camelize}/show?id=\\#{i.id}&return=\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\#{s.name.camelize}/edit?id=\\#{i.id}&record_name=\\#{patient.hn}&return=\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\#{s.name.camelize}/create?patient_id=\\#{patient.id}&record_name=\\#{patient.hn}&parent_id=\\#{pm.id}&return=\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\#{s.name.camelize}/print?id=\\#{i.id}&return=\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name if user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\#{@current_project.name}#\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\#{i.time.strftime(\"%H:%M\") if i.time } - \\#{i.ref_number}\", \"../\\#{s.name.camelize}/show?id=\\#{i.id}&return=\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\#{s.name.camelize}/edit?id=\\#{i.id}&record_name=\\#{patient.hn}&return=\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\#{s.name.camelize}/create?patient_id=\\#{patient.id}&record_name=\\#{patient.hn}&parent_id=\\#{pm.id}&return=\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\#{s.name.camelize}/print?id=\\#{i.id}&return=\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2016-01-08 03:52:40','2016-01-08 03:52:40','patient_record',''),(2025,'config',866,1,'[\r\n{:name=>\'Operations\',:open=>true,:actions=>[\r\n{:name=>\'Gastroscopy\',:service=>\'gastro\',:link=>\'../Gastro/index\',:remote=>false},\r\n{:name=>\'PushEnterosocpy\',:service=>\'push_enteroscopy\',:link=>\'../PushEnterosocpy/index\',:remote=>false},\r\n{:name=>\'DBE\',:service=>\'dbe\',:link=>\'../Dbe/index\',:remote=>false},\r\n{:name=>\'Colonoscopy\',:service=>\'colono\',:link=>\'../Colono/index\',:remote=>false},\r\n{:name=>\'Sigmoid\',:service=>\'sigmoid\',:link=>\'../Sigmoid/index\',:remote=>false},\r\n{:name=>\'ERCP\',:service=>\'ercp\',:link=>\'../Ercp/index\',:remote=>false},\r\n{:name=>\'EUS\',:service=>\'eus\',:link=>\'../Eus/index\',:remote=>false},\r\n{:name=>\'FIT\',:service=>\'fit_test\',:link=>\'../FitTest/index\',:remote=>false}\r\n\r\n]}\r\n]\r\n',NULL,NULL,NULL,'2016-01-08 03:53:09','2016-01-08 03:53:09','config',''),(2026,'print_partial',868,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[this.document_name.to_sym].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'<%=@current_project.get_setting(\'logo_report_path\')%>\' height=\'70px\' style=\"Float:left,top:5px\" /></div><h3> <strong><%=@current_service.title %> Diagnosis Report<br />\r\n<%=@current_project.get_setting(\"report_title_1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%>\r\n  </strong></h3>\r\n</center>\r\n\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> Patient Name : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'N/a\'\r\n    if patient.gender == \'1\'\r\n        gender = \'Male\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'Female\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>Sex    : </strong><%= gender %> &nbsp; <strong>Age :&nbsp;</strong>\r\n      <%= year%> Y <%=month%> M <%= day%> D\r\n      <br /><strong>Date :  </strong> <%=render_value \'start_procedural_date\'%> <strong>Produral Time :  </strong> <%=render_value \'start_procedural_time\'%> - <%=render_value \'stop_procedural_time\'%> Total Time :  <%=render_value \'procedural_time\'%>  <strong>Project : </strong> <%=render_value \'study_project\'%>\r\n    <br /><strong>Endoscopist : </strong><%=render_value \'endoscopist\'%>  , <strong>Endoscopist assist : </strong><%=render_value \'assist1endoscopist\'%> <%=render_value \'assist2endoscopist\'%> \r\n    <br /><strong>Nurse : </strong><%=render_value \'nurse\'%> , <strong>Nurse assist : </strong><%=render_value \'assist_1_nurse\'%><%=render_value \'assist_2_nurse\'%>\r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n &nbsp;&nbsp;&nbsp;<strong>Indication : </strong><%=render_value \'clinical_indication\'%><%=render_value \'indication_other_note\'%>\r\n	<hr style=\"margin-top: 5px;\"/>\r\n    <%\r\n        # atts = models[:attachment].limit(5).find(record.image)\r\n       \r\n       atts_list = record.image[0..4]\r\n       if record.selected_image and record.selected_image.size > 0\r\n          \r\n           atts_list = record.selected_image[0..4]\r\n           \r\n       end\r\n       \r\n       \r\n       atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n       \r\n       \r\n\r\n\r\n    %>\r\n\r\n    <div style=\"float:right;  width: 280px;  padding: 5px; text-align:center; font-size:14px;\">\r\n    <% for i in atts  %>\r\n    <img src=\"<%=i.path%>\" width=\"250\" height=\"180\" style=\"margin:5px\"/><br /><%=i.title%><br />\r\n    <% end %>\r\n    </div>\r\n\r\n<div style=\"float:left\">\r\n\r\n\r\n<table width=\"550\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr><td valign=\"top\"><strong>Consent</strong></td><td>The procedure of the examination, including possible complications were clearly and discussed with the patient and family, then a consent form was signed by the patient and/or family</td></tr>\r\n<tr><td valign=\"top\"><strong>Procedure</strong></td>\r\n  <td>The patient\'s blood pressure, pulse and oxygen saturation were montiored ontinuously throghout the procedure. the scope was passed under direct  vision through the mouth and advanced to the duodenum. The endoscopy was accomplished without difficulty. The findings were described below. The patient tolerated the procedure well.</td></tr>\r\n</table>\r\n<div class=\"clear\"></div>\r\n\r\n<%= render :inline=>this.display %>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n<strong>Reported by :</strong>&nbsp;<%=render_value \'recorder\'%><br />\r\n<strong>Printed Date Time :</strong>&nbsp;<%=render_value \'date_approve\' %> <%=render_value \'time_approve\'%>\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong><% if record[\'approve\']!=\"\" %>Approved<% end %> By :</strong> \r\n<%=render_value \'endoscopist_approve\'%>\r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2016-01-08 03:55:15','2016-01-08 03:55:15','print_partial',''),(2027,'create',868,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=@current_service.title %></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border-x\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    @patient_module = m\r\n   \r\n    # require \'pdfkit\'\r\n    # url = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/pdf?id=\\#{@patient_module.id}\"\r\n    # kit = PDFKit.new(url,:margin_top => \'0.2in\',:margin_right => \'0.2in\',:margin_bottom => \'0.2in\')\r\n    # report = \"tmp/cache/\\#{@patient_module.id.to_s}.pdf\"\r\n    # file = kit.to_file(report)\r\n    # field = @module_doc .find_by_column_name \'report\'\r\n    # att = @module_doc .attach_field_file field.id, report, \'\', File.open(report)\r\n    # @patient_module.update_attributes :report=>att.id\r\n \r\n    url = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/pdf?id=\\#{@patient_module.id}\"\r\n    attach_pdf = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/attach_pdf?id=\\#{@patient_module.id}\"\r\n    \r\n    id = @patient_module.id.to_s\r\n    path = \"test\"\r\n    require_relative \'app/models/workers/pdf_generator\'\r\n    PdfGenerator.enqueue :url=>url,:id=>id,:path=>path,:return=>attach_pdf\r\n    \r\n\r\n \r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') ,:html=>{:id=>\'form-id\'} do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:100%;border:1px solid #ccc\" >\r\n<center>\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</center>\r\n    \r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%# f.submit \"Save & Exit\".html_safe,:class=>\'btn btn-small btn-success\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%# link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n\r\n<div id=\"button-submit\" style=\"width:100%;padding-left:20px;position:fixed;height:40px;background:#eee;padding:5px;bottom:0px;border-top:1px solid #ccc\">\r\n<%= f.submit \"Finish\".html_safe, :class=>\'btn btn-small btn-info\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<div id=\"validation-error\" style=\"display:inline-block;margin-bottom:5px;\" class=\"alert alert-info\">Loading...</div>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\ncustom_validation();\r\n// alert(\'Please fill all information\');\r\n// if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n<script>jQuery(\"body\").addClass(\"sidebar_hidden_force\");jQuery(\"#sidebar_bt\").hide();</script>',NULL,NULL,NULL,'2016-01-08 03:58:31','2016-01-08 03:58:31','create',''),(2028,'create',869,2,'<style>\r\n    .w-box-content .tabbable {top:0px;}\r\n</style>\r\n<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=@current_service.title %></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border-x\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    @patient_module = m\r\n   \r\n    # require \'pdfkit\'\r\n    # url = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/pdf?id=\\#{@patient_module.id}\"\r\n    # kit = PDFKit.new(url,:margin_top => \'0.2in\',:margin_right => \'0.2in\',:margin_bottom => \'0.2in\')\r\n    # report = \"tmp/cache/\\#{@patient_module.id.to_s}.pdf\"\r\n    # file = kit.to_file(report)\r\n    # field = @module_doc .find_by_column_name \'report\'\r\n    # att = @module_doc .attach_field_file field.id, report, \'\', File.open(report)\r\n    # @patient_module.update_attributes :report=>att.id\r\n \r\n    url = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/pdf?id=\\#{@patient_module.id}\"\r\n    attach_pdf = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/attach_pdf?id=\\#{@patient_module.id}\"\r\n    \r\n    id = @patient_module.id.to_s\r\n    path = \"test\"\r\n    require_relative \'app/models/workers/pdf_generator\'\r\n    PdfGenerator.enqueue :url=>url,:id=>id,:path=>path,:return=>attach_pdf\r\n    \r\n\r\n \r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') ,:html=>{:id=>\'form-id\'} do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:100%;border:1px solid #ccc\" >\r\n<center>\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</center>\r\n    \r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%# f.submit \"Save & Exit\".html_safe,:class=>\'btn btn-small btn-success\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%# link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n\r\n<div id=\"button-submit\" style=\"width:100%;padding-left:20px;position:fixed;height:40px;background:#eee;padding:5px;bottom:0px;border-top:1px solid #ccc\">\r\n<%= f.submit \"Finish\".html_safe, :class=>\'btn btn-small btn-info\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<div id=\"validation-error\" style=\"display:inline-block;margin-bottom:5px;\" class=\"alert alert-info\">Loading...</div>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\ncustom_validation();\r\n// alert(\'Please fill all information\');\r\n// if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n<script>jQuery(\"body\").addClass(\"sidebar_hidden_force\");jQuery(\"#sidebar_bt\").hide();</script>',NULL,NULL,NULL,'2016-01-08 03:59:21','2016-01-08 03:59:21','create',''),(2029,'edit',869,2,'\r\n<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<script>\r\nfunction custom_validation(){\r\n    alert(\'Please fill all information\');\r\n}\r\n</script>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=@current_service.title %></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border-x\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n\r\n\r\n    url = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/pdf?id=\\#{@patient_module.id}\"\r\n    attach_pdf = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/attach_pdf?id=\\#{@patient_module.id}\"\r\n    \r\n    id = @patient_module.id.to_s\r\n    path = \"test\"\r\n    require_relative \'app/models/workers/pdf_generator\'\r\n    PdfGenerator.enqueue :url=>url,:id=>id,:path=>path,:return=>attach_pdf\r\n    \r\n    @patient_module.update_attributes :report=>nil\r\n    \r\n    \r\n\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) ,:html=>{:id=>\'form-id\'} do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n\r\n<div id=\"button-submit\" style=\"width:100%;padding-left:20px;position:fixed;height:40px;background:#eee;padding:5px;bottom:0px;border-top:1px solid #ccc\">\r\n<%= f.submit \"Finish\".html_safe, :class=>\'btn btn-small btn-info\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<div id=\"validation-error\" style=\"display:inline-block;margin-bottom:5px;\" class=\"alert alert-info\">Loading...</div>\r\n\r\n\r\n</div>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n    \r\n    var t = $(\'#data-approve\').val()\r\n    if(t!=\'Yes\'){\r\n        var date = new Date();\r\n        var hour = date.getHours()\r\n        var min = date.getMinutes()\r\n        if(hour>=15){\r\n             $(\'#data-schedule\').val(\'2\');  \r\n            $.sticky(\"Set to special clinic\", {autoclose : 5000, position: \"top-right\" });\r\n             \r\n        }\r\n            \r\n    }\r\n    \r\n    \r\n</script>\r\n\r\n<script>\r\n\r\n\r\n\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n    \r\nif (custom_validation()&&!validator.validate()) {\r\n// alert(\'Please fill all information\');\r\n\r\nreturn false;\r\n}else{\r\n      return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n\r\n$(document).ready(function(){\r\n    v = $(\'#data-approve\')\r\n    \r\n    $(\'.splashy-warning_triangle\').each(function(){\r\n        $(this).addClass(\'splashy-check\')\r\n        $(this).removeClass(\'splashy-warning_triangle\')\r\n    })\r\n    \r\n    \r\n    \r\n})\r\n\r\n</script>   \r\n\r\n<script>jQuery(\"body\").addClass(\"sidebar_hidden_force\");jQuery(\"#sidebar_bt\").hide();</script>\r\n\r\n',NULL,NULL,NULL,'2016-01-08 03:59:36','2016-01-08 03:59:36','edit',''),(2030,'print_partial',869,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:colono].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:100px;min-height:100px;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'<%=@current_project.get_setting(\"logo_report_path\")%>\' width=\"280\" style=\"Float:left,top:5px\" /></div><h3> <strong><%=@current_service.title %> Diagnosis Report<br />\r\n<%=@current_project.get_setting(\"report_title_1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%>\r\n  </strong></h3>\r\n</center>\r\n\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> Patient Name : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'Unknow\'\r\n    if patient.gender == \'1\'\r\n        gender = \'Male\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'Female\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>Gender : </strong><%= gender %> &nbsp; <strong>Age :&nbsp;</strong>\r\n      <%= year%> Y <%=month%> M <%= day%> D\r\n      <br /><strong>Date :  </strong> <%=render_value \'start_procedural_date\'%> <strong>Produral Time :  </strong> <%=render_value \'start_procedural_time\'%> - <%=render_value \'stop_procedural_time\'%> Total Time :  <%=render_value \'procedural_time\'%>  <strong>Project : </strong> <%=render_value \'study_project\'%>\r\n    <br /><strong>Endoscopist : </strong><%=render_value \'endoscopist\'%>  , <strong>Endoscopist assist : </strong><%=render_value \'assist1endoscopist\'%> <%=render_value \'assist2endoscopist\'%> \r\n    <br /><strong>Nurse : </strong><%=render_value \'nurse\'%> , <strong>Nurse assist : </strong><%=render_value \'assist_1_nurse\'%><%=render_value \'assist_2_nurse\'%>\r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n &nbsp;&nbsp;&nbsp;<strong>Indication : </strong><%=render_value \'clinical_indication\'%><% if record[\'other_indication_note\']!=\'\' %> : <%=render_value \'other_indication_note\'%><% end %>\r\n	\r\n	<hr />\r\n    \r\n    <%\r\n        # atts = models[:attachment].find(record.image)\r\n        # atts = record.image[0..4].compact.collect{|i| models[:attachment].find(i)}\r\n   \r\n       atts_list = record.image[0..4]\r\n       if record[:selected_image] and record.selected_image and record.selected_image.size > 0\r\n          \r\n           atts_list = record.selected_image[0..4]\r\n           \r\n       end\r\n       \r\n       \r\n       atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n\r\n    %>\r\n\r\n    <div style=\"float:right;  width: 280px;  padding: 5px; text-align:center; font-size:14px;\">\r\n    <% for i in atts  %>\r\n    <img src=\"<%=i.path%>\" width=\"250\" height=\"180\" style=\"margin:5px\"/><br /><%=i.title%><br />\r\n    <% end %>\r\n    </div>\r\n<div style=\"float:left\">\r\n\r\n\r\n<table width=\"550\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr><td valign=\"top\"><strong>Consent</strong></td><td>The procedure of the examination, including possible complications were clearly and discussed with the patient and family, then a consent form was signed by the patient and/or family</td></tr>\r\n<tr><td valign=\"top\"><strong>Procedure</strong></td>\r\n  <td>The patient\'s blood pressure, pulse and oxygen saturation were montiored ontinuously throghout the procedure. the scope was passed under direct vision through the anus and advanced to the colon. The endoscopy was accomplished without difficulty. The findings were described below. The patient tolerated the procedure well.</td></tr>\r\n</table>\r\n<div class=\"clear\"></div>\r\n\r\n<%= render :inline=>this.display %>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n<strong>Reported by :</strong>&nbsp;<%= @current_user.login.humanize if @current_user %><br />\r\n<strong>Printed Date Time :</strong>&nbsp;<%=render_value \'date_approve\' %> <%=render_value \'time_approve\'%>\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong><% if record[\'approve\']!=\"\" %>Approved<% end %> By :</strong> \r\n<%=render_value \'endoscopist_approve\'%>\r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-01-08 04:00:17','2016-01-08 04:00:17','print_partial',''),(2031,'print_partial',870,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[this.document_name.to_sym].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'<%=@current_project.get_setting(\'logo_report_path\')%>\' height=\'70px\' style=\"Float:left,top:5px\" /></div><h3> <strong><%=@current_service.title %> Diagnosis Report<br />\r\n<%=@current_project.get_setting(\"report_title_1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%>\r\n  </strong></h3>\r\n</center>\r\n\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> Name : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'N/A\'\r\n    if patient.gender == \'1\'\r\n        gender = \'Male\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'Female\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>Sex : </strong><%= gender %> &nbsp; <strong>Age :&nbsp;</strong>\r\n      <%= year%> Y <%=month%> M <%= day%> D\r\n      <br /><strong>Date :  </strong> <%=render_value \'start_procedural_date\'%> <strong>Produral Time :  </strong> <%=render_value \'start_procedural_time\'%> - <%=render_value \'stop_procedural_time\'%> Total Time :  <%=render_value \'procedural_time\'%>  <strong>Project : </strong> <%=render_value \'study_project\'%>\r\n    <br /><strong>Endoscopist : </strong><%=render_value \'endoscopist\'%>  , <strong>Endoscopist assist : </strong><%=render_value \'assist1endoscopist\'%> <%=render_value \'assist2endoscopist\'%> \r\n    <br /><strong>Nurse : </strong><%=render_value \'nurse\'%> , <strong>Nurse assist : </strong><%=render_value \'assist_1_nurse\'%><%=render_value \'assist_2_nurse\'%>\r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n &nbsp;&nbsp;&nbsp;<strong>Indication : </strong><%=render_value \'clinical_indication\'%><%=render_value \'indication_other_note\'%>\r\n	<hr style=\"margin-top: 5px;\"/>\r\n    <%\r\n        # atts = models[:attachment].limit(5).find(record.image)\r\n       \r\n       atts_list = record.image[0..4]\r\n       if record.selected_image and record.selected_image.size > 0\r\n          \r\n           atts_list = record.selected_image[0..4]\r\n           \r\n       end\r\n       \r\n       \r\n       atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n       \r\n       \r\n\r\n\r\n    %>\r\n\r\n    <div style=\"float:right;  width: 280px;  padding: 5px; text-align:center; font-size:14px;\">\r\n    <% for i in atts  %>\r\n    <img src=\"<%=i.path%>\" width=\"250\" height=\"180\" style=\"margin:5px\"/><br /><%=i.title%><br />\r\n    <% end %>\r\n    </div>\r\n\r\n<div style=\"float:left\">\r\n\r\n\r\n<table width=\"550\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr><td valign=\"top\"><strong>Consent</strong></td><td>The procedure of the examination, including possible complications were clearly and discussed with the patient and family, then a consent form was signed by the patient and/or family</td></tr>\r\n<tr><td valign=\"top\"><strong>Procedure</strong></td>\r\n  <td>The patient\'s blood pressure, pulse and oxygen saturation were montiored ontinuously throghout the procedure. the scope was passed under direct  vision through the mouth and advanced to the duodenum. The endoscopy was accomplished without difficulty. The findings were described below. The patient tolerated the procedure well.</td></tr>\r\n</table>\r\n<div class=\"clear\"></div>\r\n\r\n<%= render :inline=>this.display %>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n<strong>Reported by :</strong>&nbsp;<%=render_value \'recorder\'%><br />\r\n<strong>Printed Date Time :</strong>&nbsp;<%=render_value \'date_approve\' %> <%=render_value \'time_approve\'%>\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong><% if record[\'approve\']!=\"\" %>Approved<% end %> By :</strong> \r\n<%=render_value \'endoscopist_approve\'%>\r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2016-01-08 04:00:53','2016-01-08 04:00:53','print_partial',''),(2032,'document_name',871,1,'\'colposcopy\'',NULL,NULL,NULL,'2016-01-10 06:22:16','2016-01-10 06:22:16',NULL,NULL),(2033,'print',871,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:colposcopy].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n\r\n  \r\n    if @patient \r\n        patient = @patient\r\n        date = Time.now.to_datetime\r\n        birth_date = patient.birth_date \r\n        year = month = day = \'0\'\r\n        if date and birth_date\r\n            t = date-birth_date    \r\n            year = (t/365).to_i\r\n            t%=365\r\n            month = (t/30).to_i\r\n            t%=30\r\n            day = t.to_i\r\n        end\r\n    end \r\n    \r\n    # many lesion\r\n    a_lesion = models[:lesion].find(record[:lesion])\r\n    d_lesion = get_document \'lesion\'\r\n    f_lesion = d_lesion.fields\r\n    fl = {}\r\n    fm = {}\r\n    \r\n    f_lesion.each do |i|\r\n        # lab = i[:label]\r\n        lov = i[:lov]\r\n        name = i[:column_name]\r\n        if lov\r\n            fm[name] = {}\r\n            ll = lov.split(/[\\r\\n]+/)\r\n            ll.each do |j|\r\n                if j.include? \'|\'\r\n                    xx = j.split(\'|\')\r\n                    fm[name][xx[0].strip.to_s] = xx[1].strip\r\n                else\r\n                    fm[name][j.strip] = j.strip\r\n                end\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:290px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:240px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:240px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colposcopy Report</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v></v>&nbsp;&nbsp; Colonoscope by :&nbsp;<v><%=endoscopist_1%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n<hr />\r\n<br/>\r\n\r\n<div id=\"para1\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;\">\r\n	\r\n<%=render_value \'para1\' %> <%=render_value \'para2\' %> <%=render_value \'para3\' %> <%=render_value \'para4\' %>\r\n</div>\r\n\r\n\r\n<div id=\"lmp\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;\">\r\n	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n<%=render_value \'lmp\' %>\r\n</div>\r\n</div>\r\n\r\n\r\n<div id=\"menopause\">\r\n  <div>\r\n   Menopause :<%=render_value \'menopause\' %>\r\n  </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"contraception\">\r\n  <label>Contraception : </label>\r\n  <%=render_value \'contraception\' %></div>\r\n<div id=\"518-F3364280841\"></div>\r\n<div id=\"partner\" style=\"width:200px; float:left\">\r\n  \r\n  <%=render_value \'partner\' %></div>\r\n<div id=\"first_si\" style=\"width:200px; float:left\">\r\n \r\n  <%=render_value \'first_si\' %></div>\r\n<div id=\"pap\" style=\"width:200px; float:left\">\r\n  \r\n    <%=render_value \'pap\' %>\r\n  \r\n</div>\r\n<div id=\"518-F0483335858\"></div>\r\n<div id=\"hpv\" style=\"width:200px; float:left\">\r\n  <label>HPV :</label>\r\n  <%=render_value \'hpv\' %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"hpv_positive\" style=\"width:400px; float:left;; height:30px\">\r\n  <label>HPV positive :</label>\r\n\r\n   <%=render_value \'hpv_positive\' %>\r\n  \r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"518-F4184992546\"><strong>General assessment</strong></div>\r\n<div id=\"adequacy\" style=\"width:400px; float:left\">\r\n  <label>Adequacy : </label>\r\n  <%=render_value \'adequacy\' %></div>\r\n<div id=\"squamocolumnar_junction\" style=\"width:400px; float:left\">\r\n  <label>Squamocolumnar junction(visbility) :</label>\r\n  <%=render_value \'squamocolumnar_junction\' %>\r\n</div>\r\n<div id=\"transformation_zone\" style=\"width:400px; float:left; height:30px\">\r\n  <label>Transformation zone(TZ) :</label>\r\n  <%=render_value \'transformation_zone\' %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"518-F2337439620\"><strong>Normal colposcopic finddings</strong></div>\r\n<div id=\"squamous_epithelium\" style=\"width:400px; float:left\">\r\n  <label>Squamous epithelium :</label>\r\n  <%=render_value \'squamous_epithelium\' %>\r\n</div>\r\n<div id=\"columnar_epithelium\" style=\"width:400px; float:left\">\r\n  <label>Columnar epithelium :</label>\r\n <%=render_value \'columnar_epithelium\' %>\r\n</div>\r\n<div id=\"other_normal_colpscopic\" style=\"width:700px; float:left; height:30px\">\r\n  <label>Other :</label>\r\n <%=render_value \'other_normal_colpscopic\' %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"518-F6673927113\"><strong>Abnormal colposcopic finddings</strong></div>\r\n<div id=\"abnormal\">\r\n<%=render_value \'abnormal\' %>\r\n</div>\r\n<div id=\"518-F1126903404\"></div>\r\n<div id=\"site_of_lesion\" style=\"width:400px; float:left\">\r\n  <label>Site of lesion :</label>\r\n  <%=render_value \'site_of_lesion\' %>\r\n</div>\r\n<div id=\"number_of_lesion\" style=\"width:400px; float:left\">\r\n  <label>Number of lesion :</label>\r\n <%=render_value \'number_of_lesion\' %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"lesion\">\r\n  <label>Lesion :</label> <b><%= a_lesion.count %></b>\r\n \r\n  <br/>\r\n<%# fm.to_json.html_safe %>\r\n<%\r\n  no = 1\r\n%>\r\n<%\r\n   tmp_rec = @record\r\n   tmp_doc = @document \r\n   @document = d_lesion\r\n   \r\n    a_lesion.each do |i|\r\n        @record = i\r\n%>\r\n\r\n  <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" style=\"-moz-border-radius: 5px;\r\nborder-radius: 5px; border-color:#999\">\r\n  <tr>\r\n  <th style=\"background:#EAEAEA\">Lesion <%= no%> : Location of the lesion:<%= i[\'location_of_the_lesion\'] %>o\'colock (<%= i[\'percent_of_lesion\'] %>%)</th>\r\n  </tr><tr>\r\n  \r\n  <td style=\"font-size: 12px;\"><%=\"<br/>Grade 1 (monor; insignificant or low grade) :\".html_safe if i[\'grade_1_type\']!=\'\' %><%= render_value \'grade_1_type\' %><%=\"<br />Grade 2 (major; significant or high grade) :\".html_safe if i[\'grade_2_type\']!=\'\' %><%=  render_value \'grade_2_type\' %><%=\"<br />Non-specific :\".html_safe if i[\'non_grade\']!=\'\' %><%=  render_value \'non_grade\' %><%=  render_value \'biopsy_was_done\' %> at clock(<%=  render_value \'biopsy_at_clock\' %>) <br />\r\n  Supicious for invasion :<%= render_value \'supicious_for_invasion\' %> Atypical vessels :<%= render_value \'atypical_vessels\' %> Additional signs :<%= render_value \'additional_signs\' %><%=  render_value\'tumor_or_gross_cm\' %><br />\r\n  Miscellaneous findings <%= render_value \'miscellaneous_yn\' %><%=\"Colposcopic impression :\" if i[\'miscellaneous_type\']!=\'\' %><%= render_value \'miscellaneous_type\' %><%= i[\'colposcopic_impression\'] %><br />&nbsp;</td>\r\n  </tr>\r\n \r\n  </table>\r\n  <br />\r\n  \r\n  \r\n  \r\n<% \r\nno += 1\r\n    end \r\n    \r\n    @record = tmp_rec\r\n    @document = tmp_doc\r\n%>\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n <div id=\"colposcopy-lesion-56920536790f9b04aa000014-458-F8664851417\"><strong>Colposcopic impression</strong></div>\r\n<div id=\"colposcopic_impression\">\r\n \r\n  <%=render_value \'colposcopic_impression\' %></div>\r\n<div id=\"management\">\r\n  <label>Management :</label>\r\n  <%=render_value \'management\' %>\r\n</div>\r\n<div id=\"pap_at\" style=\"width:400px; float:left\">\r\n  <label>PAP at </label>\r\n   <%=render_value \'pap_at\' %></div>\r\n<div id=\"hpv_at\" style=\"width:400px; float:left\">\r\n  <label>HPV at </label>\r\n   <%=render_value \'hpv_at\' %></div>\r\n<div id=\"management_other\" style=\"width:400px; float:left\"><%=render_value \'management_other\' %></div>\r\n<div id=\"follow_up\" style=\"width:700px; float:left; height:30px\">\r\n  <label>Follow up : </label>\r\n   <%=render_value \'follow_up\' %></div>\r\n<div id=\"note\" style=\"width:700px; float:left; height:30px\">\r\n  <label>Note : </label>\r\n   <%=render_value \'note\' %></div>\r\n   <div class=\"clear\"></div>\r\n\r\n\r\n<!--   -->\r\n\r\n\r\n\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n	\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Fellow : <v><%=render_value \'fellow\'%> </v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.images\r\n        atts = list[0...3].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%3==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:40px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-01-10 07:38:48','2016-01-10 07:38:48','print',''),(2034,'document_name',872,1,'\'pre_op\'',NULL,NULL,NULL,'2016-01-13 03:58:14','2016-01-13 03:58:14',NULL,NULL),(2035,'document_name',873,1,'\'post_op\'',NULL,NULL,NULL,'2016-01-13 03:58:54','2016-01-13 03:58:54',NULL,NULL),(2036,'document_name',874,1,'\'pacu\'',NULL,NULL,NULL,'2016-01-13 04:14:24','2016-01-13 04:14:24',NULL,NULL),(2037,'context_menu_partial',383,3,'<style>\r\n    .list-x{width:100px;border:0px solid;display:inline-block;}\r\n</style>\r\n<% \r\nif @current_role != \'pathologist\'\r\nmodules = @context.get_projects_by_abstract \'ehr.emr\' \r\nmodel = get_model\r\nehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\nehr_models = ehr.load_model\r\npatient_model = ehr_models[:patient]\r\nm = modules.collect{|i| {:name=>i.title,:link=>\"../../\\\\#{i.name}/Home/index\",:remote=>false} }\r\nm <<  {:name=>\'Back to EHR\',:link=>\"../../www/Home/index\",:remote=>false}\r\n%>\r\n<%# show_menu m %>\r\n\r\n<%\r\n\r\nif params[:id]\r\n\r\npm_model = ehr_models[:patient_module]\r\nif params[:mode]==\'module\'\r\n    \r\n    lpm = pm_model.find(params[:id])\r\n    \r\n    apm = pm_model.find(lpm.parent_id)\r\n    if lpm and apm\r\n    ap = model[:appointment].find(apm.module_id)\r\n    else\r\n    apm = pm_model.find(params[:id])\r\n    ap = model[:appointment].find(apm.module_id)\r\n\r\n    end\r\n    \r\nelse\r\n    ap = model[:appointment].find(params[:id]) \r\n    apm = pm_model.where(:module_id=>ap.id).first\r\n    \r\nend\r\npatient = nil\r\nif apm\r\n   patient = patient_model.find(apm.patient_id) \r\nend\r\n\r\n# if params[:id] or params[:parent_id]\r\n    \r\nobj = this.config\r\n\r\nlist = []\r\n\r\nfor i in obj\r\nfor j in i[:actions]\r\n  if j[:dashboard]==true\r\n    list << j\r\n  end\r\nend\r\nend\r\n\r\n\r\n# \r\n\r\n\r\n# if params[:parent_id]\r\n# elsif params[:service]==\'Home\'\r\n#     ap = model[:appointment].find(params[:id]) \r\n# else\r\n#     lpm = pm_model.find(params[:id])\r\n#     apm = pm_model.find(lpm.parent_id)\r\n#     ap = model[:appointment].find(apm.module_id)\r\n# end\r\n\r\n# obj = [\r\n# {:name=>\'Endoscopy\',:open=>true,:actions=>[\r\n# {:name=>\'Consignment\',:service=>\'consignment\',:link=>\'../Consignment/index\',:remote=>false},\r\n# {:name=>\'Pre Scope\',:service=>\'pre_scope\',:link=>\'../PreScope/index\',:remote=>false},\r\n# {:name=>\'Intra Scope\',:service=>\'intra_scope\',:link=>\'../IntraScope/index\',:remote=>false},\r\n# {:name=>\'Post Scope\',:service=>\'post_scope\',:link=>\'../PostScope/index\',:remote=>false}]},\r\n# {:name=>\'Endoscopist Records\',:open=>true,:actions=>[\r\n# {:name=>\'Colonosopy\',:service=>\'colonoscopy\',:link=>\'../Colonoscopy/index\',:remote=>false},\r\n# {:name=>\'Gastroscopy\',:service=>\'gastroscopy\',:link=>\'../Gastroscopy/index\',:remote=>false}]},\r\n# {:name=>\'ETC\',:open=>true,:actions=>[\r\n# {:name=>\'Pathology\',:service=>\'pathology\',:link=>\'../Pathology/index\',:remote=>false},\r\n# {:name=>\'Analyses\',:service=>\'report\',:link=>\'../Report/index\',:remote=>false}]}]\r\n%>\r\n<%# params[:id] %>\r\n<%#list.inspect  %>\r\n\r\n\r\n<div class=\"accordion-group\" style=\"\">\r\n	<div class=\"accordion-heading\">\r\n		<a href=\"#collapse-0\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n		Visit Detail\r\n		</a>\r\n		</div>\r\n		<div class=\"accordion-body collapse in\" id=\"collapse-0\">\r\n			<div class=\"accordion-inner\">\r\n			<div class=\"alert alert-info\">\r\n			\r\n<b>Name : </b><%= patient.first_name %> <%= patient.last_name %> <br/>\r\n<b>HN : </b><%= patient.hn %> <br/>\r\n\r\n			\r\n<b>Visit Type : </b><%=t = model[:visit_type].find(ap.visit_type); t.name if t %> <br/>\r\n<b>Visit Date : </b><%= ap.date  if ap%><br/>\r\n</div>\r\n<% for i in list %>\r\n<div style=\"padding-bottom:5px;padding-top:5px;border-bottom:1px solid #ccc\">\r\n<span class=\"list-x\"><%=i[:name]%> : </span>\r\n<%\r\n   ilist = []\r\n#   apm\r\n   pm = pm_model.where(:parent_id=>apm.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{i[:service]}\").first\r\n   return_url = \"../Home/patient_record?id=\\\\#{ap.id}\"\r\n   if pm\r\n      ilist << link_to(\"Edit\",\"\\\\#{i[:link].split(\'/\')[0..-2].join(\'/\')}/edit?id=\\\\#{pm.id}&return=\\\\#{return_url}\",:class=>\'btn\')\r\n      ilist << link_to(\"Print\",\"\\\\#{i[:link].split(\'/\')[0..-2].join(\'/\')}/print?id=\\\\#{pm.id}\",:class=>\'btn \',:target=>\'_blank\')\r\n   else\r\n      patient_id = apm.patient_id\r\n      patient_hn = \'0000\'\r\n      \r\n      ilist << link_to(\"Create\",\"\\\\#{i[:link].split(\'/\')[0..-2].join(\'/\')}/create?patient_id=\\\\#{patient_id}&record_name=\\\\#{patient_hn}&parent_id=\\\\#{apm.id}&return=\\\\#{return_url}\",:class=>\'btn\')\r\n   end\r\n\r\n\r\n\r\n for j in ilist \r\n%>\r\n<%=j.html_safe%>\r\n<% end %>\r\n</div>\r\n\r\n<% end %>\r\n<div><br/>\r\n<center><%=link_to \'Back to Detail\', return_url, :class=>\'btn\' %></center>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n<% else %>\r\n\r\n<%=show_menu this.config %>\r\n<% end %>\r\n\r\n<%    \r\n\r\n# obj << {:name=>\'Links\',:open=>true,:actions=>m}\r\n%>\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\') %>\r\n\r\n<% else %>\r\n<center style=\"margin-top:20px\"><%= link_to \'Pathology Records\',\'../Pathology/index\',:class=>\'btn\' %></center>\r\n<% end %>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-01-15 07:40:30','2016-01-15 07:40:30','context_menu',''),(2039,'document_name',875,1,'\'diag_note\'',NULL,NULL,NULL,'2016-01-16 02:03:51','2016-01-16 02:03:51',NULL,NULL),(2040,'document_name',876,1,'\'colposcopy\'',NULL,NULL,NULL,'2016-01-18 10:21:28','2016-01-18 10:21:28',NULL,NULL),(2041,'print_bk',876,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    apm = @module_model.find(pm.parent_id)\r\n    @appointment = models[:appointment].find(apm.module_id)\r\n    colono_id = pm.module_id\r\n    record = models[:colposcopy].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n\r\n  \r\n    if @patient \r\n        patient = @patient\r\n        date = Time.now.to_datetime\r\n        birth_date = patient.birth_date \r\n        year = month = day = \'0\'\r\n        if date and birth_date\r\n            t = date-birth_date    \r\n            year = (t/365).to_i\r\n            t%=365\r\n            month = (t/30).to_i\r\n            t%=30\r\n            day = t.to_i\r\n        end\r\n    end \r\n    \r\n    # many lesion\r\n    a_lesion = models[:lesion].find(record[:lesion])\r\n    d_lesion = get_document \'lesion\'\r\n    f_lesion = d_lesion.fields\r\n    fl = {}\r\n    fm = {}\r\n    \r\n    f_lesion.each do |i|\r\n        # lab = i[:label]\r\n        lov = i[:lov]\r\n        name = i[:column_name]\r\n        if lov\r\n            fm[name] = {}\r\n            ll = lov.split(/[\\r\\n]+/)\r\n            ll.each do |j|\r\n                if j.include? \'|\'\r\n                    xx = j.split(\'|\')\r\n                    fm[name][xx[0].strip.to_s] = xx[1].strip\r\n                else\r\n                    fm[name][j.strip] = j.strip\r\n                end\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:290px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:240px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:240px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"\"><center><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></center></div>\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colposcopy Report</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v><%= @appointment.date.strftime(\"%d-%m-%Y\") %></v>&nbsp;&nbsp; Colposcopist by :&nbsp;<v><%=endoscopist_1%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n<hr />\r\n<br/>\r\n\r\n<div id=\"para1\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;\">\r\n	\r\n<%=render_value \'para1\' %> <%=render_value \'para2\' %> <%=render_value \'para3\' %> <%=render_value \'para4\' %>\r\n</div>\r\n\r\n\r\n<div id=\"lmp\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;\">\r\n	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n<%=render_value \'lmp\' %>\r\n</div>\r\n</div>\r\n\r\n\r\n<div id=\"menopause\">\r\n  <div>\r\n   Menopause :<%=render_value \'menopause\' %>\r\n  </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"contraception\">\r\n  <label>Contraception : </label>\r\n  <%=render_value \'contraception\' %></div>\r\n<div id=\"518-F3364280841\"></div>\r\n<div id=\"partner\" style=\"width:200px; float:left\">\r\n  \r\n  <%=render_value \'partner\' %></div>\r\n<div id=\"first_si\" style=\"width:200px; float:left\">\r\n \r\n  <%=render_value \'first_si\' %></div>\r\n<div id=\"pap\" style=\"width:200px; float:left\">\r\n  \r\n    <%=render_value \'pap\' %>\r\n  \r\n</div>\r\n<div id=\"518-F0483335858\"></div>\r\n<div id=\"hpv\" style=\"width:200px; float:left\">\r\n  <label>HPV :</label>\r\n  <%=render_value \'hpv\' %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"hpv_positive\" style=\"width:400px; float:left;; height:30px\">\r\n  <label>HPV positive :</label>\r\n\r\n   <%=render_value \'hpv_positive\' %>\r\n  \r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"518-F4184992546\"><strong>General assessment</strong></div>\r\n<div id=\"adequacy\" style=\"width:400px; float:left\">\r\n  <label>Adequacy : </label>\r\n  <%=render_value \'adequacy\' %></div>\r\n<div id=\"squamocolumnar_junction\" style=\"width:400px; float:left\">\r\n  <label>Squamocolumnar junction(visbility) :</label>\r\n  <%=render_value \'squamocolumnar_junction\' %>\r\n</div>\r\n<div id=\"transformation_zone\" style=\"width:400px; float:left; height:30px\">\r\n  <label>Transformation zone(TZ) :</label>\r\n  <%=render_value \'transformation_zone\' %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"518-F2337439620\"><strong>Normal colposcopic finddings</strong></div>\r\n<div id=\"squamous_epithelium\" style=\"width:400px; float:left\">\r\n  <label>Squamous epithelium :</label>\r\n  <%=render_value \'squamous_epithelium\' %>\r\n</div>\r\n<div id=\"columnar_epithelium\" style=\"width:400px; float:left\">\r\n  <label>Columnar epithelium :</label>\r\n <%=render_value \'columnar_epithelium\' %>\r\n</div>\r\n<div id=\"other_normal_colpscopic\" style=\"width:700px; float:left; height:30px\">\r\n  <label>Other :</label>\r\n <%=render_value \'other_normal_colpscopic\' %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"518-F6673927113\"><strong>Abnormal colposcopic finddings</strong></div>\r\n<div id=\"abnormal\">\r\n<%=render_value \'abnormal\' %>\r\n</div>\r\n<div id=\"518-F1126903404\"></div>\r\n<div id=\"site_of_lesion\" style=\"width:400px; float:left\">\r\n  <label>Site of lesion :</label>\r\n  <%=render_value \'site_of_lesion\' %>\r\n</div>\r\n<div id=\"number_of_lesion\" style=\"width:400px; float:left\">\r\n  <label>Number of lesion :</label>\r\n <%=render_value \'number_of_lesion\' %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"lesion\">\r\n  <label>Lesion :</label> <b><%= a_lesion.count %></b>\r\n \r\n  <br/>\r\n<%# fm.to_json.html_safe %>\r\n<%\r\n  no = 1\r\n%>\r\n\r\n<%\r\n    tmp_doc = @document\r\n    tmp_rec = @record\r\n    \r\n    @document = d_lesion\r\n\r\n\r\n    a_lesion.each do |i|\r\n        \r\n    @record = i    \r\n    img = models[:attachment].find(i[\'image\'])\r\n    \r\n%>\r\n\r\n  <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" style=\"-moz-border-radius: 5px;\r\nborder-radius: 5px; border-color:#999\">\r\n  <tr>\r\n  <th style=\"background:#EAEAEA\">Lesion <%= no%> : Location of the lesion:<%= i[\'location_of_the_lesion\'] %>o\'colock (<%= i[\'percent_of_lesion\'] %>%)</th>\r\n  </tr><tr>\r\n  \r\n  <td>  <%= \"Grade 1 (monor; insignificant or low grade)\" if i.grade_1_type!=\"\" %> <%=render_value\'grade_1_type\' %>\r\n  <%= \"Grade 2 (major; significant or high grade)\" if i.grade_2_type!=\"\" %> <%=render_value\'grade_2_type\' %>\r\n  <%= \"Non-specific\" if i.non_grade!=\"\" %> <%=render_value\'non_grade\' %>\r\n  Supicious for invasion :<%= render_value\'supicious_for_invasion\' %> <%= render_value\'atypical_vessels_location\' %> Additional signs :<%= render_value\'additional_signs\' %><%= render_value\'tumor_or_gross_cm\' %>\r\n  <%= \"<br />Miscellaneous findings :\".html_safe if i.miscellaneous_type!=\"\" %> <%= render_value\'miscellaneous_type\' %></td>\r\n  </tr>\r\n \r\n  </table>\r\n  <br />\r\n  \r\n  \r\n  \r\n<% \r\nno += 1\r\n    end \r\n    \r\n    @document = tmp_doc\r\n    @record = tmp_rec\r\n    \r\n%>\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n<%=render_value\'biopsy_was_done\' %><%= \"at\" if a= record[\'biopsy_at_clock\'] and a !=\"\" %> <%= render_value\'biopsy_at_clock\' if a= record[\'biopsy_was_done\'] and a !=\"\" %> \r\n <div id=\"colposcopy-lesion-56920536790f9b04aa000014-458-F8664851417\"><strong>Colposcopic impression</strong></div>\r\n<div id=\"colposcopic_impression\">\r\n \r\n  <%=render_value \'colposcopic_impression\' %></div>\r\n<div id=\"management\">\r\n  <label>Management :</label>\r\n  <%=render_value \'management\' %>\r\n</div>\r\n<div id=\"pap_at\" style=\"width:400px; float:left\">\r\n <%= \"PAP at:\" if a= record[\'pap_at\'] and a !=\"\" %> \r\n   <%=record[\'pap_at\'] %></div>\r\n<div id=\"hpv_at\" style=\"width:400px; float:left\">\r\n   <%= \"HPV at:\" if a= record[\'hpv_at\'] and a !=\"\" %> \r\n   <%=record[\'hpv_at\'] %></div>\r\n  \r\n<div id=\"management_other\" style=\"width:400px; float:left\"><%=render_value \'management_other\' %></div>\r\n<div id=\"follow_up\" style=\"width:700px; float:left; height:30px\">\r\n  <label>Follow up : </label>\r\n   <%=render_value \'follow_up\' %></div>\r\n<div id=\"note\" style=\"width:700px; float:left; height:30px\">\r\n  <label>Note : </label>\r\n   <%=render_value \'note\' %></div>\r\n   <div class=\"clear\"></div>\r\n\r\n\r\n<!--   -->\r\n\r\n\r\n\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Colposcopist by : <v><%=endoscopist_1%></v></p>\r\n	\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Fellow : <v><%=render_value \'fellow\'%> </v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.images\r\n        atts = list[0...3].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%3==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:50px\">\r\n<div id=\"logoleft\"><p>Sign :___________________<br />&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<%=endoscopist_1%></p></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-01-19 02:40:33','2016-01-19 02:40:33','print_bk',''),(2042,'staff_report_excel',805,3,'<%\r\n    response.headers[\"Content-Type\"] = \"application/xls\"\r\n    response.headers[\"Content-disposition\"] = \"attachment; filename=StaffOT-\\\\#{Time.now.to_i}.xls\"\r\n    \r\n    tb = Time.now \r\n    \r\n    def map_parent_object(m_arr = [])\r\n        rs = {}\r\n        m_arr.each do |i|\r\n            rs[i[:parent_id].to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n%>\r\n<%= render :inline=>this.init %>\r\n<%\r\n    rs = {}\r\n    res = {}\r\n    ars = []\r\n    pat_mod = {}\r\n     ars_rec = 0 \r\n    app_date = Time.now\r\n    if q = params[:query]\r\n        sdate = q[:sdate]\r\n        edate = q[:edate]\r\n        app_date = sdate\r\n        \r\n        rs = get_appointment_by_date(sdate, edate).sort_by{|i|  (i[:start] == \'\' or i[:start] == nil) ? \'00:00\' : i[:start].strftime(\'%H:%M\')}\r\n        app_ids = rs.collect{|i| i.id.to_s}\r\n        pat_mod = get_patient_module_by_appointment_ids(app_ids)\r\n        par_ids = pat_mod.collect{|i| i.id.to_s}\r\n        pat_ids = pat_mod.collect{|i| i[:patient_id].to_s}\r\n        mod_pre = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#pre_anesthetic\")\r\n        mod_pos = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#post_anesthetic\")\r\n        ids_pre = get_module_id_array(mod_pre)\r\n        ids_pos = get_module_id_array(mod_pos)\r\n        a_pre = @models[:pre_anesthetic].find(ids_pre)\r\n        a_pos = @models[:post_anesthetic].find(ids_pos)\r\n        \r\n        a_pat = @m_pat.find(pat_ids)\r\n        \r\n        par_app = get_module_id_map(pat_mod)\r\n        par_pre = map_parent_object(mod_pre)\r\n        par_pos = map_parent_object(mod_pos)\r\n        map_pre = get_map(a_pre)\r\n        map_pos = get_map(a_pos)\r\n        \r\n        map_pat = get_map(a_pat)\r\n        map_ward = get_map(@models[:ward].all)\r\n        # map_room = get_map(@models[:or_room].all)\r\n        \r\n        map_anes_tech = {\'\'=>\'Undefined\',\'1\'=>\'General anesthesia (balanced technique)\', \'2\'=>\'General anesthesia (Inhalation technique)\',\'3\'=>\'General anesthesia (TIVA)\',\'4\'=>\'Monitor anesthetic care\',\'5\'=>\'Regional anesthesia\',\'6\'=>\'Nerve Block\',\'7\'=>\'Combined general anesthesia and nerve block\',\'8\'=>\'Combined general anesthesia and regional anesthesia\',\'9\'=>\'GA due to RA/Nerve block fail\'}\r\n        map_pacu = {nil=>\'Undefined\', \'\'=>\'Undefined\',\'1\'=>\'OR\',\'2\'=>\'RR\',\'3\'=>\'WARD\',\'4\'=>\'ICU\'}\r\n        \r\n        res = par_pre\r\n        rs.each do |i|\r\n            tmp = {}\r\n            pm_app = par_app[i.id.to_s]\r\n            # tmp[:par_id] = par_id.id\r\n            pm_pre = par_pre[pm_app.id.to_s]\r\n            pm_pos = par_pos[pm_app.id.to_s]\r\n            \r\n            if  pm_pos.nil?\r\n                next\r\n            end\r\n            \r\n            # patient info\r\n            pat_id = pm_app[:patient_id].to_s\r\n            pat = map_pat[pat_id]\r\n            \r\n            tmp[:hn] = pat[:hn]\r\n            tmp[:name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]}  \\\\#{pat[:last_name]}\"\r\n            \r\n            today = i[:date]\r\n            if pat[:birth_date]\r\n                d = Date.new(today.year, pat[:birth_date].month,  pat[:birth_date].day)\r\n                age = d.year - pat[:birth_date].year - (d > today ? 1 : 0)\r\n                tmp[:age] = age\r\n            else\r\n                tmp[:age] = \'-\'\r\n            end\r\n            \r\n            # appointment\r\n            tmp[:diag] = i[:diagnosis]\r\n            tmp[:operation] = i[:operation]\r\n            tmp[:ward] = (i[:ward]==\'\' or i[:ward].nil?) ? \'N/A\' : map_ward[i[:ward]][:name]\r\n            tmp[:surgeon] = (i[:surgeon]==\'\' or i[:surgeon].nil?) ? \'N/A\' : @provider[i[:surgeon]]\r\n            tmp[:ast_surgeon] = (i[:assist]==\'\' or i[:assist].nil?) ? \'N/A\' : @provider[i[:assist]]\r\n            tmp[:app_date] = i[:date]\r\n            \r\n            # anesth team\r\n            pre = !pm_pre.nil? ? map_pre[pm_pre[:module_id].to_s] : nil\r\n            pos = map_pos[pm_pos[:module_id].to_s]\r\n            # tmp[:debug] = \"PRE : \\\\#{pre.to_json.html_safe}<br/>POS : \\\\#{pos.to_json.html_safe}\"\r\n            \r\n            if pre\r\n                tmp[:team_pre_1] = (pre[:anesthesiologist]==\'\' or pre[:anesthesiologist].nil?) ? \'N/A\' : @provider[pre[:anesthesiologist].to_s]\r\n                tmp[:team_pre_2] = (pre[:nurse]==\'\' or pre[:nurse].nil?) ? \'N/A\' : @provider[pre[:nurse].to_s]\r\n            else\r\n                tmp[:team_pre_1] = \'N/A\'\r\n                tmp[:team_pre_2] = \'N/A\'\r\n            end\r\n            \r\n            tmp[:team_pos_1] = (pos[:anesthesiologist]==\'\' or pos[:anesthesiologist].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist].to_s]\r\n            tmp[:team_pos_2] = (pos[:nurse_anesthetist]==\'\' or pos[:nurse_anesthetist].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetist].to_s]\r\n            \r\n            # intra-op\r\n            tmp[:dur_time] = \'N/A\'\r\n            tmp[:dur_anesthesiologist] = \'N/A\'\r\n            tmp[:dur_anesthetist] = \'N/A\'\r\n            dur_off = (pos[:anesthetic_official_duration]==\'\' or pos[:anesthetic_official_duration].nil?) ? 0 : pos[:anesthetic_official_duration].to_i\r\n            dur_non = (pos[:anesthetic_non_official_duration]==\'\' or pos[:anesthetic_non_official_duration].nil?) ? 0 : pos[:anesthetic_non_official_duration].to_i\r\n            \r\n            \r\n            \r\n             rec_non = (pos[:recovery_non_official_time_min]==\'\' or pos[:recovery_non_official_time_min].nil?) ? 0 : pos[:recovery_non_official_time_min].to_i\r\n                \r\n                \r\n            # anesthetic_official_time_start anesthetic_official_duration\r\n            if rec_non>0\r\n                \r\n                ts = pos[:recovery_non_official_time_start].strftime(\'%H:%M\') if pos[:recovery_non_official_time_start]\r\n                te = pos[:recovery_non_official_time_end].strftime(\'%H:%M\') if pos[:recovery_non_official_time_end]\r\n                \r\n                \r\n                tmp[:rec_non_anesthesiologist] = (pos[:recovery_anesthesiologist_non_official]==\'\' or pos[:recovery_anesthesiologist_non_official].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthesiologist_non_official].to_s]\r\n                a1 = (pos[:recovery_anesthetic_non_official_1]==\'\' or pos[:recovery_anesthetic_non_official_1].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_1].to_s]\r\n                a2 = (pos[:recovery_anesthetic_non_official_2]==\'\' or pos[:recovery_anesthetic_non_official_2].nil?) ? \'N/A\' : @provider[pos[:recovery_anesthetic_non_official_2].to_s]\r\n                tmp[:rec_non_nurse] = \"\\\\#{a1}, \\\\#{a2}\"\r\n                \r\n                # OT Report\r\n                tmp[:xtime_rec] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes_rec] = tmp[:rec_non_anesthesiologist]\r\n                tmp[:xnur1_rec] = a1\r\n                tmp[:xnur2_rec] = a2\r\n                ars_rec+=1\r\n            end\r\n            \r\n            if dur_non==0 and dur_off > 0\r\n                next\r\n                ds = pos[:anesthetic_official_date_start].strftime(\'%d/%m/%Y\')\r\n                de = pos[:anesthetic_official_date_end].strftime(\'%d/%m/%Y\')\r\n                ts = pos[:anesthetic_official_time_start].strftime(\'%H:%M\')\r\n                te = pos[:anesthetic_official_time_end].strftime(\'%H:%M\')\r\n                \r\n                tmp[:dur_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{dur_off} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                tmp[:dur_anesthetist] = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n            elsif dur_non > 0 #and dur_off==0\r\n                ds = pos[:anesthetic_nonofficial_date_start].strftime(\'%d/%m/%Y\')\r\n                de = pos[:anesthetic_nonofficial_date_end].strftime(\'%d/%m/%Y\')\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\')\r\n                te = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\')\r\n                \r\n                tmp[:dur_time] = \"\\\\#{ds} \\\\#{ts} - \\\\#{de} \\\\#{te} (\\\\#{dur_non} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                tmp[:dur_anesthetist] = \"\\\\#{a1}, \\\\#{a2}\"\r\n                \r\n                # OT Report\r\n                tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes] = tmp[:dur_anesthesiologist]\r\n                tmp[:xnur1] = a1\r\n                tmp[:xnur2] = a2\r\n            elsif dur_non > 0 and dur_off > 0\r\n                ds_off = pos[:anesthetic_official_date_start]\r\n                de_off = pos[:anesthetic_official_date_end]\r\n                ds_non = pos[:anesthetic_nonofficial_date_start]\r\n                de_non = pos[:anesthetic_nonofficial_date_end]\r\n                \r\n                ts_off = pos[:anesthetic_official_time_start].strftime(\'%H:%M\')\r\n                te_off = pos[:anesthetic_official_time_end].strftime(\'%H:%M\')\r\n                ts_non = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\')\r\n                te_non = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\')\r\n                \r\n                ds = ds_off\r\n                de = de_non\r\n                ts = ts_off\r\n                te = te_non\r\n                if ds_off == ds_non and de_off == de_non\r\n                    if ts_non < ts_off\r\n                        ts = ts_non\r\n                        te = te_off\r\n                    end\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\" \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                elsif de_non > ds_off\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"  \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                elsif ds_non < de_off\r\n                    ds = ds_non\r\n                    de = de_off\r\n                    ts = ts_non\r\n                    te = te_off\r\n                    tmp[:dur_time] = \"\\\\#{ds.strftime(\'%d/%m/%Y\')} \\\\#{ts} - \\\\#{de.strftime(\'%d/%m/%Y\')} \\\\#{te} (\\\\#{dur_off + dur_non} mins)\"    \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                else\r\n                    tmp[:dur_time] = \"official time : (\\\\#{ds_off} \\\\#{ts_off} - \\\\#{de_off} \\\\#{te_off}) / non-official time : (\\\\#{ds_non} \\\\#{ts_non} - \\\\#{de_non} \\\\#{te_non}) [\\\\#{dur_off + dur_non} mins] \"\r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\\\#{ts_non}-\\\\#{te_non}\"\r\n                end\r\n\r\n                off_a0 = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                off_a1 = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n                non_a0 = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                non_a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                non_a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                \r\n                tmp[:dur_anesthesiologist] = \"\\\\#{off_a0} (official time) / \\\\#{non_a0} (non-official time)\"\r\n                tmp[:dur_anesthetist] = \"\\\\#{off_a1} (official time) / \\\\#{non_a1}, \\\\#{non_a2} (non-official time)\"\r\n                \r\n                # OT Report\r\n                tmp[:xanes] = non_a0\r\n                tmp[:xnur1] = non_a1\r\n                tmp[:xnur2] = non_a2\r\n            else\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\')\r\n                te = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\')\r\n                if ts==te\r\n                    next\r\n                end\r\n                # OT Report\r\n                tmp[:xtime] = \"\\\\#{ts}-\\\\#{te}\"\r\n                tmp[:xanes] = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                tmp[:xnur1] = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_ane