nter\"/>\r\n   <Borders/>\r\n   <Font ss:FontName=\"TH SarabunPSK\" x:Family=\"Swiss\" ss:Size=\"16\"\r\n    ss:Color=\"#000000\"/>\r\n   <Interior ss:Color=\"#FFFFFF\" ss:Pattern=\"Solid\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s70\">\r\n   <Alignment ss:Vertical=\"Center\" ss:WrapText=\"1\"/>\r\n   <Borders>\r\n    <Border ss:Position=\"Bottom\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Left\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Right\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n    <Border ss:Position=\"Top\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/>\r\n   </Borders>\r\n   <Font ss:FontName=\"TH SarabunPSK\" x:Family=\"Swiss\" ss:Size=\"16\"\r\n    ss:Color=\"#000000\"/>\r\n  </Style>\r\n </Styles>\r\n <Worksheet ss:Name=\"Staff\">\r\n  <Table ss:ExpandedColumnCount=\"9\" ss:ExpandedRowCount=\"<%= ars.count + 8 + ars_rec %>\" x:FullColumns=\"1\"\r\n   x:FullRows=\"1\" ss:StyleID=\"s62\" ss:DefaultColumnWidth=\"65\"\r\n   ss:DefaultRowHeight=\"15\">\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"25\"/>\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"62\"/>\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"135\"/>\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"60\" ss:Span=\"1\"/>\r\n   <Column ss:Index=\"6\" ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"120\"/>\r\n   <Column ss:StyleID=\"s62\" ss:AutoFitWidth=\"0\" ss:Width=\"124\" ss:Span=\"2\"/>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"21\">\r\n    <Cell ss:MergeAcross=\"8\" ss:StyleID=\"s63\"><Data ss:Type=\"String\">รายงานผู้ป่วยที่ได้รับยาระงับความรู้สึกนอกเวลาราชการ</Data></Cell>\r\n   </Row>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"21\">\r\n    <Cell ss:MergeAcross=\"8\" ss:StyleID=\"s63\"><Data ss:Type=\"String\">ตั้งแต่ <%= params[:query][:sdate] %>  ถึง <%= params[:query][:edate] %></Data></Cell>\r\n   </Row>\r\n   <Row ss:AutoFitHeight=\"0\">\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n   </Row>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"26\" ss:StyleID=\"s63\">\r\n    <Cell ss:StyleID=\"s66\"><Data ss:Type=\"String\">ที่</Data></Cell>\r\n    <Cell ss:StyleID=\"s66\"><Data ss:Type=\"String\">ว/ด/ป</Data></Cell>\r\n    <Cell ss:StyleID=\"s66\"><Data ss:Type=\"String\">ชื่อ - สกุล</Data></Cell>\r\n    <Cell ss:StyleID=\"s66\"><Data ss:Type=\"String\">HN</Data></Cell>\r\n    <Cell ss:StyleID=\"s66\"><Data ss:Type=\"String\">เวลา</Data></Cell>\r\n    <Cell ss:StyleID=\"s66\"><Data ss:Type=\"String\">วิธีการให้ยาระงับความรู้สึก</Data></Cell>\r\n    <Cell ss:StyleID=\"s66\"><Data ss:Type=\"String\">วิสัญญีพยาบาล</Data></Cell>\r\n    <Cell ss:StyleID=\"s66\"><Data ss:Type=\"String\">วิสัญญีพยาบาล</Data></Cell>\r\n    <Cell ss:StyleID=\"s66\"><Data ss:Type=\"String\">เจ้าหน้าที่พยาบาล</Data></Cell>\r\n   </Row>\r\n<%\r\n  ars = ars.sort_by{|i| i[:app_date]}\r\n  ars.each_with_index do |val, i|\r\n%>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"52\">\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= i + 1 %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:app_date] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:name] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:hn] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:xtime] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s70\"><Data ss:Type=\"String\">Neuroanesthesia with special monitor</Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:xnur1] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:xnur2] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"/>\r\n   </Row>\r\n       <% if val[:xtime_rec] %>\r\n    <Row ss:AutoFitHeight=\"0\" ss:Height=\"52.5\">\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= i + 1 %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:app_date].strftime(\"%d/%m/%Y\") %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:name] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:hn] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:xtime_rec] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s70\"><Data ss:Type=\"String\">Post anesthetic care in neurocritical</Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:xnur1] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"><Data ss:Type=\"String\"><%= val[:xnur2] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s67\"/>\r\n   </Row>\r\n    <% end %>\r\n   \r\n   \r\n<%\r\n  end\r\n%>\r\n   <Row ss:AutoFitHeight=\"0\">\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n   </Row>\r\n    <Row ss:AutoFitHeight=\"0\" ss:Height=\"21\">\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s69\"><Data ss:Type=\"String\">____________________</Data></Cell>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n\r\n   </Row>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"21\">\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s69\"><Data ss:Type=\"String\">(นางสาวเกศินี ดำรงบุล)</Data></Cell>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n\r\n   </Row>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"21\">\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n    <Cell ss:StyleID=\"s69\"><Data ss:Type=\"String\">หัวหน้างานการพยาบาลวิสัญญี</Data></Cell>\r\n    <Cell ss:StyleID=\"s65\"/>\r\n   </Row>\r\n  </Table>\r\n  <WorksheetOptions xmlns=\"urn:schemas-microsoft-com:office:excel\">\r\n   <PageSetup>\r\n    <Layout x:Orientation=\"Landscape\"/>\r\n    <Header x:Margin=\"0.3\"/>\r\n    <Footer x:Margin=\"0.3\"/>\r\n    <PageMargins x:Bottom=\"0.75\" x:Left=\"0.7\" x:Right=\"0.7\" x:Top=\"0.75\"/>\r\n   </PageSetup>\r\n   <Unsynced/>\r\n   <FitToPage/>\r\n   <Print>\r\n    <ValidPrinterInfo/>\r\n    <PaperSizeIndex>9</PaperSizeIndex>\r\n    <Scale>57</Scale>\r\n    <HorizontalResolution>600</HorizontalResolution>\r\n    <VerticalResolution>0</VerticalResolution>\r\n   </Print>\r\n   <PageLayoutZoom>0</PageLayoutZoom>\r\n   <Selected/>\r\n   <Panes>\r\n    <Pane>\r\n     <Number>3</Number>\r\n     <ActiveRow>4</ActiveRow>\r\n     <ActiveCol>2</ActiveCol>\r\n    </Pane>\r\n   </Panes>\r\n   <ProtectObjects>False</ProtectObjects>\r\n   <ProtectScenarios>False</ProtectScenarios>\r\n  </WorksheetOptions>\r\n </Worksheet>\r\n</Workbook>\r\n\r\n',NULL,NULL,NULL,'2016-01-19 17:12:45','2016-01-19 17:12:45','staff_report_excel',''),(2045,'patient_record',666,2,'\r\n<% Time.zone =  get_setting \'time_zone\' %>\r\n<%\r\n    require \'time_diff\'\r\n    \r\n    date = Time.now.to_datetime\r\n    \r\n    models = get_model\r\n    conf = this.config\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    m_patient = ehr_models[:patient]\r\n    m_patient_module = ehr_models[:patient_module]\r\n\r\n    if params[:id]\r\n        session[:params_id] = params[:id]\r\n    else\r\n        params[:id] = session[:params_id]\r\n    end\r\n    \r\n    if @current_role == \'developer\'\r\n        session[:owner] == true\r\n    end\r\n\r\n    if p = params[:record]\r\n        in_pin = p[:pin]\r\n        if p[:service_id] != \'\' and in_pin == session[:pin]\r\n            destroy_url = \"destroy?mode=\\\\#{p[:mode]}&id=\\\\#{p[:service_id]}\".html_safe\r\n            return_url  = \"&return=\\\\#{request.fullpath}\".html_safe\r\n%>\r\n<script>\r\n                url = \"<%= destroy_url %><%= return_url %>\";\r\n                // url = \'<%= request.fullpath.html_safe %>\'\r\n                window.location = url;\r\n</script>\r\n<%\r\n        end\r\n    end\r\n%>\r\n    <style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n    </style>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n    <div class=\"w-box\">\r\n        <div class=\"w-box-header\">\r\n            Patient Medical Records\r\n            <div class=\"pull-right\">\r\n            <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n            </div> \r\n        </div>  \r\n        <div class=\"w-box-content cnt_a\">\r\n            <div style=\"border:0px solid\">\r\n                <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n<%\r\n    # get patient by patient_id\r\n    pid = \'\'\r\n    patient = \'\'\r\n    if params[:id]\r\n        pid = params[:id]\r\n        patient = m_patient.find(pid)\r\n    end\r\n    \r\n    if patient\r\n        birth_date = patient.birth_date \r\n        year = month = day = \'0\'\r\n        if date and birth_date\r\n            t = date-birth_date    \r\n            diff = Time.diff(date, birth_date)\r\n            year = diff[:year]\r\n            month = diff[:month]\r\n            # day = diff[:day]\r\n        end\r\n%>\r\n<!--patient section-->\r\n<div class=\"alert alert-block alert-success\">\r\n    <div class=\"btn left\" style=\"height:100px;width:100px\">\r\n<%\r\n        edit_url = \"../../www/Patient/edit?id=\\\\#{params[:id]}&return=\\\\#{request.fullpath}\".html_safe\r\n        att_model = ehr_models[:attachment]\r\n        if !patient[:picture].empty? and patient[:picture].size > 0 \r\n            pic = att_model.find(patient.picture[-1])\r\n            if pic \r\n%>\r\n<a href=\'<%= edit_url %>\'><%= image_tag pic.path, :height=>100 %></a>\r\n<%     \r\n            end \r\n        elsif\r\n%>\r\n<a href=\'<%= edit_url %>\'><%= image_tag \'/esm/thks/www/content/patient_icon.png\', :height=>100 %></a>\r\n<%\r\n		end \r\n%>\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px;float:left\">\r\n<p>\r\n<b> Patient : </b><v><%= patient.prefix_name %>  <%= patient.first_name %> <%= patient.last_name %></v>\r\n</p>\r\n<p>\r\n<b> Age : </b><v><%= year%> Years <%=month%> Months </v> <!-- | <%= patient[:birth_date] %> -->\r\n</p>\r\n\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px:float:left\">\r\n<br/>\r\n<p>\r\n<b> HN : </b><v> <%= patient.hn %></v>\r\n</p>\r\n<p>\r\n<%\r\n        # pg = patient gender\r\n        pg = \'NA\'\r\n        if patient.gender == \'1\'\r\n            pg = \'Male\'\r\n        elsif\r\n            pg = \'Female\'\r\n        end\r\n%>\r\n<b> Gender : </b><v><%=pg%> </v>\r\n</p>\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<%\r\n    elsif # if no patient\r\n%>\r\n<script>\r\n    alert(\'No Paient Found!!!\');\r\n    window.location = \"../Home/index\";\r\n</script>\r\n<%\r\n    end # end patient section\r\n%>\r\n\r\n<% if false %>\r\n<script>\r\n    <%\r\n            url = \'../../www/Patient/search_result?\'\r\n            url += \'&id=54fc51d3790f9b4e56000009\'\r\n    %>      \r\n            $.ajax({\r\n              url: \'<%=url.html_safe%>\',\r\n             success: function(data){\r\n              $(\'#patient\').html(data);  \r\n              }\r\n            });\r\n</script>\r\n<% end %>\r\n\r\n\r\n    <!--Appointment form-->\r\n    <%\r\n    procedures = (models[:procedure]).to_a\r\n    # list = %w{primary-hip-left primary-hip-right primary-knee-left primary-knee-right revision-hip-left revision-hip-right revison-knee-left revision-knee-right}\r\n    \r\n    mprocedures = {}\r\n    for i in procedures\r\n        mprocedures[i.id] = i\r\n    end\r\n    \r\n    tmp_list = []\r\n    tmp_app = nil\r\n    tmp_zam = {}\r\n    all_pm =  m_patient_module.where(:patient_id=>patient.id,:module_name=>\"\\\\#{@current_project.name}#appointment\").to_a\r\n    list = all_pm.collect do |i| \r\n        \r\n        app = models[:appointment].find(i.module_id)\r\n        procedure = mprocedures[app.procedure]\r\n        if procedure.nil?\r\n            next\r\n        end\r\n        mrecord = models[procedure.code.to_s]\r\n        mr = m_patient_module.where(:parent_id=>i.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{procedure.code}\").first\r\n        record = nil\r\n        if mr\r\n            record = mrecord.find(mr.module_id)\r\n        end\r\n        follow_ups = []\r\n        follow_ups = m_patient_module.where(:parent_id=>i.id,:module_name=>\"\\\\#{@current_project.name}#follow_up_form_tka\").to_a\r\n        follow_ups = follow_ups.collect{|j| [j,(models[:follow_up_form_tka]).find(j.module_id)]}.sort{|a,b| a[1][:period].to_f<=>b[1][:period].to_f} \r\n        \r\n        # zamachita query\r\n        m_main = nil\r\n        m_follow = []\r\n        details = m_patient_module.where(:parent_id=>i.id)\r\n        for j in details do\r\n            if j.module_name == \"\\\\#{@current_project.name}#\\\\#{procedure.code}\"\r\n                m_temp = models[procedure.code.to_s]\r\n                record = m_temp.find(j.module_id)\r\n                \r\n                m_main = j\r\n                m_main[:record] = record\r\n            elsif\r\n                m_name = j.module_name.split(\'#\')[1]\r\n                m_temp = models[m_name]\r\n                record = m_temp.find(j.module_id)\r\n                \r\n                j[:record] = record\r\n                m_follow.push(j)\r\n            end\r\n        end\r\n        \r\n        # temporary var\r\n        tmp_list.push(procedure.id.to_s)\r\n        tmp_app = app\r\n        \r\n        {:id=>i.id,:created=>i[:created_at],:name=>procedure.name,:record=>record,:mrecord=>mr,:procedure=>procedure,:date=>app.inspect,:main=>i,:follow_ups=>follow_ups,:m_main=>m_main, :m_follow=>m_follow}\r\n        \r\n    end\r\n    list = list.sort_by{|i| i[:created]} if list\r\n    \r\n    listx = procedures.collect do |i| \r\n        # if tmp_list.index(i.id.to_s).nil?\r\n            [i.name, i.id]\r\n        # end\r\n    end\r\n    %>\r\n<%\r\n    if \'\' == \'developer\'\r\n%>\r\n<pre>\r\n    <%= list.to_json.html_safe %>\r\n</pre>\r\n<%\r\n    else\r\n%>\r\n    <%= form_for :data,:url=>\"appointment_create?\" ,:method=>\'GET\' do |f| %>\r\n    <%=hidden_field_tag :patient_id, patient.id.to_s %>\r\n    <%=hidden_field_tag :return, request.fullpath %>\r\n    <%=f.hidden_field :date, :value=>date %>\r\n                    <div class=\"clear\"></div>\r\n                    <div>\r\n                        <h4 style=\"float:left\"><%= @current_project.title %> Recrods</h4>\r\n    <%\r\n    if !tmp_app.nil?\r\n    %>\r\n    <%=f.hidden_field :provider, :value=>tmp_app[:provider] %>\r\n    <%\r\n    else\r\n        provider = models[:provider].where(:login=>@current_user.login).first\r\n        if provider.nil?\r\n            providers = models[:provider].all\r\n            p_select = providers.collect{|i| [i.name,i.id.to_s]}\r\n    %>\r\n                        <span style=\"float:right\">Provider :&nbsp;&nbsp; <%= f.select \'provider\', options_for_select(p_select), :style=>\'width:100px\' %> \r\n                        &nbsp;&nbsp;\r\n    <%\r\n        else\r\n    %>\r\n    <%=f.hidden_field :provider, :value=>provider.id.to_s %>\r\n    <%\r\n        end\r\n    end # provider\r\n    %>\r\n                        <span style=\"float:right\"><%= f.select \'procedure\' ,options_for_select(listx.compact.sort)  %> \r\n                            <%=f.submit \'Add New\',:class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %></span>\r\n                        <div class=\"clear\"></div>\r\n                    </div>\r\n    <% end %>\r\n    <!--End Appointment Form-->\r\n    \r\n<!-- charts -->\r\n			<script src=\"/gebo/lib/flot/jquery.flot.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.resize.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.pie.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.curvedLines.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.orderBars.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.multihighlight.min.js\"></script>\r\n			<script src=\"/gebo/lib/flot/jquery.flot.pyramid.min.js\"></script>\r\n			<script src=\"/gebo/lib/moment_js/moment.min.js\"></script>\r\n    <!--Start TAB-->\r\n    <%\r\n    # all appointment\r\n    \r\n    \r\n    %>\r\n    <%\r\n    \r\n    z_test = false\r\n    if z_test\r\n    %>\r\n    <!--TEST PANE-->\r\n    <div class=\"row-fluid\"></div>\r\n    <div class=\"alert alert-block alert-warning\">\r\n        LIST.<br/>\r\n        <% for i in list %>\r\n        <%= i[:record].inspect %>\r\n        <hr/>\r\n        <% end %>\r\n        tmp_list <%= tmp_list.size %>. <%= tmp_list %><hr/><%= procedures.collect{|i| i.id} %>\r\n    \r\n    </div>\r\n    <%\r\n    end # end test\r\n    %>\r\n                    <div class=\"clear\"></div>\r\n                    <!--<div class=\"tabbable tabs-left\" style=\"border:1px solid #ccc; -moz-border-radius: 5px; border-radius: 5px;\">-->\r\n                    <div class=\"tabbable\" style=\"border:1px solid #ccc; -moz-border-radius: 5px; border-radius: 5px;\">\r\n                        <ul class=\"nav nav-tabs\" style=\"background:#F4F4F4; -moz-border-radius: 5px;border-radius: 5px;\">\r\n                            <li class=\"active\" >\r\n                                <a href=\"#tab_dashboard\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >Dashboard</a>\r\n                            </li>\r\n                            <!--More TAB-->\r\n                            <% for i in list do %>\r\n                            <%\r\n                                side = \'-\'\r\n                                bi = false\r\n                                if i[:m_main]\r\n                                    if i[:m_main][:record][:side] == \'1\'\r\n                                        side = \'L\'\r\n                                    elsif i[:m_main][:record][:side] == \'2\'\r\n                                        side = \'R\'\r\n                                    end\r\n                                    \r\n                                    if i[:m_main][:record][:bilateral] == \'1\'\r\n                                        bi = true\r\n                                    end\r\n                                end\r\n                            %>\r\n                            <li class=\"\">\r\n                                <a href=\"#tab_<%=i[:id]%>\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >\r\n                                    <%=i[:name]%> (<%= side %>) <font color=\'red\'><%= \'*\' if bi %></font><br/>\r\n                                </a>\r\n                            </li>\r\n                            <% end %>\r\n                        </ul>\r\n   \r\n                        <!--<div class=\"tab-content\" style=\"width:640px;border:0px solid;float:left; clear:none;margin-left:-20px;\">-->\r\n                        <div class=\"tab-content\">\r\n                            <div class=\"tab-pane  <%= \'active\' if true %>\" style=\"border:0px solid;\" id=\"tab_dashboard\">\r\n                                <br/>\r\n                                <h3>Dashboard</h3>\r\n                                <div class=\"row-fluid\"><br/></div>\r\n    <%\r\n    if list.size == 0\r\n    %>\r\n                                Welcome\r\n    <%\r\n    elsif\r\n    %>\r\n                                Welcome :)\r\n                                <br/>\r\n                                \r\n    <%\r\n    end\r\n    %>\r\n                            </div>\r\n<!--More TAB Content-->\r\n<%\r\n    fnc_data = {} # for create charts\r\n%>\r\n                            <% for i in list do %>\r\n                            <%\r\n                                fnc_series = nil\r\n                                side = \'-\'\r\n                                xx = \'x\'\r\n                                if i[:m_main]\r\n                                    if i[:m_main][:record][:side] == \'1\'\r\n                                        side = \'L\'\r\n                                    elsif i[:m_main][:record][:side] == \'2\'\r\n                                        side = \'R\'\r\n                                    end\r\n                                    xx = i[:m_main][:id]\r\n                                end\r\n                            %>\r\n                            <div class=\"tab-pane\" style=\"border:0px solid;\" id=\"tab_<%= i[:id] %>\">\r\n                                <br/>\r\n                                <div class=\"row-fluid\">\r\n                                    <h3><%= i[:name] %>  (<%= side %>)</h3>\r\n    <%\r\n        mname = i[:procedure].code.humanize\r\n        mr = i[:m_main]\r\n        show = \"\"\r\n        fnc_name = mname.downcase + \'_\' + side.downcase\r\n        if mr\r\n            show = link_to(\"Edit \", \"../\\\\#{mname}/edit?id=\\\\#{mr.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}#tab_\\\\#{i[:id]}\",:class=>\'btn btn-small btn-info\')\r\n            show += \' \'\r\n            show += link_to(\"View \", \"../\\\\#{mname}/show?id=\\\\#{mr.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}#tab_\\\\#{i[:id]}\",:class=>\'btn btn-small\')\r\n            show += \' \'\r\n            show += link_to(\'Print\',\"../\\\\#{mname}/print?id=\\\\#{mr.id}&return=\\\\#{request.fullpath}#tab_\\\\#{i[:id]}\",:target=>\'_blank\' ,:class=>\'btn btn-small\')\r\n        else\r\n            show =  link_to(\'Create\',\"../\\\\#{mname}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-small btn-success\')\r\n        end\r\n        con_del = session[:owner] ? \"javascript:confirm_delete(\'\\\\#{i[:id]}\'); return false;\" : \"javascript:confirm_main(\'\\\\#{i[:id]}\'); return false;\"\r\n        # con_del = \"javascript:confirm_main(\'\\\\#{i[:id]}\'); return false;\" \r\n    %>\r\n                                    <%= link_to \'\', \"\", :title=>\'Delete operation\', :class=>\'splashy-error_x\', :style=>\'float:right;margin-top:-30px\', :onclick=>con_del%>\r\n                                    <div style=\"float:right\"><%# show %></div>\r\n                                </div>\r\n    <% if mr %>\r\n                                <font size=\"1\" style=\"color:gray\">Created at <%= i[:m_main][:record][:created_at].strftime(\"%d/%m/%Y\") %> | Last Updated at <%= i[:m_main][:record][:updated_at].strftime(\"%d/%m/%Y\") %> </font>\r\n                                <hr/>\r\n<%\r\nif mr[:record][:component_company].to_s.strip != \'\'\r\n    map_company = {}\r\n    map_component = {}\r\n    for x in get_model[:company].all do\r\n        map_company[x.id.to_s] = x[:name]\r\n    end\r\n    for x in get_model[:knee_component].all do\r\n        map_component[x.id.to_s] = x\r\n    end\r\n    \r\n%>\r\n                                <div style=\"float:right;margin-right:10px\" class=\" well\">\r\n                                    <strong>Component from : </strong><v><%= map_company[mr[:record][:component_company].to_s] %></v>\r\n                                    <div style=\"margin-left:20px\">\r\n                                        Femur : <v><%= mr[:record][:component_femur] ? map_component[mr[:record][:component_femur].to_s][:name] : \"none\" %> (size : <%= mr[:record][:femoral_size] %>)</v><br/>\r\n                                        Tibia : <v><%= mr[:record][:component_tibia] ? map_component[mr[:record][:component_tibia].to_s][:name] : \"none\" %> (size : <%= mr[:record][:tibial_size] %>)</v><br/>\r\n                                        Patella : <v><%= mr[:record][:component_patella] ? map_component[mr[:record][:component_patella].to_s][:name] : \"none\" %> (size : <%= mr[:record][:patella_size] %>)</v><br/>\r\n                                        Polyethylene : <v><%= mr[:record][:component_polyethylene] ? map_component[mr[:record][:component_polyethylene].to_s][:name] : \"none\" %> (size : <%= mr[:record][:polyethylene_size] %>)</v>\r\n                                    </div>\r\n                                </div>\r\n                                <br/>\r\n<%\r\nend\r\n%>\r\n                                <div style=\"margin-left:20px\"></div><%= show %>\r\n                                <!--Operation Date : <%= i[:m_main][:record][:operation_date] %>-->\r\n    <% elsif %>\r\n                                <font size=\"1\" style=\"color:gray\">No operation available </font>\r\n                                <hr/>\r\n                                <div style=\"margin-left:20px\"></div><%= show %>\r\n                                <!--Create Operation-->\r\n    <% end %>\r\n                                \r\n                                <div class=\"row-fluid\">\r\n                                    <br/>\r\n                                </div>\r\n<%\r\n    if i[:main]\r\n%>\r\n                                <div class=\"span10\">\r\n        							<div id=\"<%= fnc_name %>\">\r\n        						</div>\r\n<%\r\n    end\r\n%>\r\n        						</div>\r\n                                <div class=\"row-fluid\">\r\n					</div>\r\n                                <!--<div class=\"alert alert-info\">-->\r\n    <%\r\n        tmp_str = \"\"\r\n        form_service = nil\r\n        if mr\r\n            m_form = mr[:module_name]\r\n            form_service = \"FollowUpHip\"\r\n            if m_form.index(\'knee\')\r\n                form_service = \"FollowUpKnee\"\r\n            end\r\n            c_link = \"../\\\\#{form_service}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\"\r\n            \r\n            m_follow = i[:m_follow].collect{|i| [i.id, i[:module_name], i[:record]]}.sort{|a,b| a[2][:period].to_f<=>b[2][:period].to_f}\r\n            f_link = {}\r\n            for j in m_follow do\r\n                f_link[j[2].id] = [j[0], j[1]]\r\n            end\r\n            \r\n            fnc_series = {}\r\n            fnc_data[fnc_name] = {}\r\n            fnc_period = [[0,\"\"]]\r\n            idx = 2\r\n            # labels = {:period=>\'Period\', :date=>\'Date\', :height=>\'Height\', :weight=>\'Weight\'}\r\n            labels = {:period=>\'Period\', :date=>\'Created Date\'}\r\n            if m_form.index(\'hip\')\r\n                labels[:hhs_hip_score] = \'Hip Score\'\r\n                labels[:hhs_hip_score] = \'HOOS-JR\'\r\n                \r\n                if i[:m_main]\r\n                    fnc_series[:hhs_hip_score] = [[1,i[:m_main][:record][:hhs_hip_score].to_i]]\r\n                    fnc_series[:hoos_interval_score] = [[1,i[:m_main][:record][:hoos_interval_score].to_f]]\r\n                    \r\n                    # fnc_period << [1,i[:m_main][:record][:operation_date].strftime(\'%m/%^b/%y\')]\r\n                    if i[:m_main][:record][:operation_date].nil?\r\n                        fnc_period << [1,i[:m_main][:record][:created_at].strftime(\'%m/%^b/%y\')]\r\n                    else\r\n                        fnc_period << [1,i[:m_main][:record][:operation_date].strftime(\'%m/%^b/%y\')]\r\n                    end\r\n                end\r\n            else\r\n                labels[:koos_interval_score] = \'KOOS-JR\'\r\n                labels[:womac_total_womac_score] = \'WOMAC\'\r\n                labels[:kss_total_knee_score] = \'Knee Score\'\r\n                \r\n                if i[:m_main]\r\n                    fnc_series[:womac_total_womac_score] = [[1,i[:m_main][:record][:womac_total_womac_score].to_i]]\r\n                    fnc_series[:kss_total_knee_score] = [[1,i[:m_main][:record][:kss_total_knee_score].to_i]]\r\n                    fnc_series[:koos_interval_score] = [[1,i[:m_main][:record][:koos_interval_score].to_f]]\r\n                    if i[:m_main][:record][:operation_date].nil?\r\n                        fnc_period << [1,i[:m_main][:record][:created_at].strftime(\'%m/%^b/%y\')]\r\n                    else\r\n                        fnc_period << [1,i[:m_main][:record][:operation_date].strftime(\'%m/%^b/%y\')]\r\n                    end\r\n                    # tmp_str = i[:m_main][:record].to_json.html_safe\r\n                end\r\n            end\r\n            m_labels = labels.keys\r\n            \r\n            \r\n    %>\r\n                        <%= tmp_str %>\r\n                                    <hr/>\r\n                                    <div style=\"float:left\"><strong><font size=\"3\">Follow up</font></strong></div>\r\n                                    <%= link_to \'Create\', c_link, :style=>\'float:right;margin-top:10px\', :class=>\'btn btn-small btn-success\' %>\r\n                                    <div class=\"row-fluid\"></div>\r\n    <!--Follow up table -->\r\n    <%= tabular :data=> m_follow.collect{|j| j[2]},:labels=>labels ,:model=>m_labels do |row,out|\r\n        l = f_link[row.id]\r\n        link_ext = l[1].split(\'#\')[1].split(\'_\').map(&:capitalize).join(\'\')\r\n        \r\n        period = row.period\r\n        period_txt = \"\\\\#{period} m.\"\r\n        if period.to_i >= 12\r\n            period = period.to_i / 12\r\n            period_txt = \"\\\\#{period} y.\"\r\n        elsif period.to_f < 1\r\n            period = period.to_f * 30\r\n            period = period.to_i\r\n            period_txt = \"\\\\#{period} d.\"\r\n        end\r\n        out[0] = period_txt\r\n        out[1] = row[:created_at].strftime(\"%d-%m-%Y\")\r\n        \r\n        for k in fnc_series.keys do\r\n            fnc_series[k] << [idx, row[k].to_i]\r\n        end\r\n        fnc_period << [idx, period_txt.html_safe]\r\n        idx += 1\r\n        \r\n        show = link_to(\"\", \"../\\\\#{link_ext}/edit?id=\\\\#{l[0]}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\", :class=>\'splashy-document_a4_edit\', :title=>\'Edit\')\r\n        # show = \"<a title=\'Edit\' href=\'../\\\\#{link_ext}/edit?id=\\\\#{l[0]}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\'><img src=\'/gebo/img/gCons/edit.png\' alt=\'\' /></a>\"\r\n        show += \'&nbsp;&nbsp;&nbsp;\'.html_safe\r\n        show += link_to(\'\',\"\", :onclick=>\"javascript:confirm_delete_followup(\'\\\\#{l[0]}\'); return false;\", :class=>\'splashy-document_a4_remove\', :title=>\'Remove\')\r\n        show += \'&nbsp;&nbsp;&nbsp;\'.html_safe\r\n        show += link_to(\'\',\"../\\\\#{link_ext}/print?id=\\\\#{l[0]}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'splashy-printer\', :title=>\'Print\')\r\n        # show += \"</i>\".html_safe\r\n        # show += \"<a title=\'Print\' href=\'../\\\\#{link_ext}/edit?id=\\\\#{l[0]}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\'><img src=\'/gebo/img/gCons/print.png\' alt=\'\' /></a>\"\r\n        out << show\r\n    \r\n        out\r\n    end%>\r\n    \r\n    <%\r\n        end # end follow up\r\n        \r\n        fnc_data[fnc_name] = {}\r\n        fnc_data[fnc_name][:series] = fnc_series\r\n        fnc_data[fnc_name][:period] = fnc_period\r\n    %>\r\n                                <!--</div>-->\r\n                            </div>\r\n                            <% end %>\r\n                            \r\n                        </div>\r\n                    </div>\r\n    <!--End TAB-->\r\n    <!--<%# fnc_data %>-->\r\n\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    </div>\r\n    <br/><br/>\r\n\r\n<script>\r\n    \r\n    $(document).ready(function() {\r\n// style=\"height:270px;width:90%;margin:15px auto 0\"\r\n<%\r\n    fnc_list = []\r\n    for fnc in fnc_data.keys do\r\n        if fnc_data[fnc][:series] and fnc_data[fnc][:period].count > 2\r\n            fnc_list << fnc\r\n%>\r\n\r\n        $(\'#<%= fnc %>\').css({\"height\":\"270px\", \"width\":\"90%\", \"margin\":\"15px auto 0\"});\r\n        gebo_charts.<%= fnc %>();\r\n<%\r\n        end\r\n    end\r\n%>\r\n	});\r\n	\r\n	gebo_charts = {\r\n<%\r\n    fnc_list.each_with_index do |k, i|\r\n%>\r\n        <%= k %> : function() {\r\n            var elem = $(\'#<%= k.html_safe %>\');\r\n            var options = {\r\n				series: {\r\n					curvedLines: { active: true }\r\n				},\r\n				yaxes: [\r\n					{min: 0},\r\n                    {position: \"right\"}\r\n				],\r\n				xaxis: {\r\n					autoscaleMargin: 0.10,\r\n					ticks: <%= fnc_data[k][:period].to_json.html_safe %>\r\n					\r\n				},\r\n				grid: { hoverable: true },\r\n				legend: { position: \'nw\' },\r\n				colors: [ \"#3d641b\", \"#8cc7e0\", \"#3ca0ca\" ]\r\n			};\r\n<%\r\n    if fnc_data[k][:series].count > 1\r\n%>\r\n            // Setup the flot chart using our data\r\n            <%= k %>_plot = $.plot(elem,\r\n				[\r\n				    {   data: <%= fnc_data[k][:series][:koos_interval_score].to_json %>,\r\n                        label: \"KOOS-JR\",\r\n                        curvedLines: {\r\n                            active: true,\r\n                            show: true,\r\n                            lineWidth: 3\r\n                        },\r\n				// 		yaxis: 2,\r\n						points: { show: true },\r\n				// 		stack: null\r\n					},\r\n					{ 	data: <%= fnc_data[k][:series][:womac_total_womac_score].to_json %>,\r\n						label: \"WOMAC\",\r\n						points: { show: true },\r\n						curvedLines: {\r\n                            active: true,\r\n                            show: true,\r\n                            lineWidth: 3\r\n                        }\r\n					},\r\n					{   data: <%= fnc_data[k][:series][:kss_total_knee_score].to_json %>,\r\n                        label: \"KSS\",\r\n                        curvedLines: {\r\n                            active: true,\r\n                            show: true,\r\n                            lineWidth: 3\r\n                        },\r\n				// 		yaxis: 2,\r\n						points: { show: true },\r\n				// 		stack: null\r\n					}\r\n					\r\n				], options);\r\n<%\r\n    else\r\n%>\r\n            <%= k %>_plot = $.plot(elem,\r\n				[\r\n				    {   data: <%= fnc_data[k][:series][:hoos_interval_score].to_json %>,\r\n                            label: \"HOOS-JR\",\r\n                            curvedLines: {\r\n                                active: true,\r\n                                show: true,\r\n                                lineWidth: 3\r\n                            },\r\n                            \r\n    				// 		yaxis: 2,\r\n    						points: { show: true },\r\n    				// 		stack: null\r\n    				},\r\n					{ 	data: <%= fnc_data[k][:series][:hhs_hip_score].to_json %>,\r\n						label: \"HHS\",\r\n						points: { show: true },\r\n						curvedLines: {\r\n                            active: true,\r\n                            show: true,\r\n                            lineWidth: 3\r\n                        }\r\n    					\r\n					}\r\n				], options);\r\n<%\r\n    end\r\n%>\r\n			\r\n        } <%= \',\' if i < fnc_list.count - 1 %>\r\n<%\r\n    end\r\n%>\r\n	}\r\n</script>\r\n\r\n<script>\r\n    \r\n    function confirm_delete(id) {\r\n        if (confirm(\'Do you want to delete this operation?\') == true) {\r\n            // ../Appointment/destroy?id=\\\\#{i[:id]}&return=\\\\#{request.fullpath}\r\n<%\r\n    destroy_url = \"destroy?mode=main&id=\"\r\n    return_url = \"&return=\" + request.fullpath\r\n%>\r\n            url = \"<%= destroy_url.html_safe %>\" + id + \"<%= return_url.html_safe %>\";\r\n            window.location.href = url;\r\n        } \r\n    }\r\n    function confirm_delete_followup(id) {\r\n        if (confirm(\'Do you want to delete this follow up?\') == true) {\r\n<%\r\n    destroy_url = \"destroy?mode=followup&id=\"\r\n    return_url = \"&return=\" + request.fullpath\r\n%>\r\n            url = \"<%= destroy_url.html_safe %>\" + id + \"<%= return_url.html_safe %>\";\r\n            window.location.href = url;\r\n        }\r\n    }\r\n</script>\r\n    \r\n    \r\n    <script>\r\n    $(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n    </script>\r\n     \r\n\r\n<%\r\nend # developer\r\n%>\r\n\r\n\r\n\r\n\r\n<!--# modal-->\r\n\r\n<%\r\n    pdate = Time.now.strftime(\'%d/%m/%Y\')\r\n%>\r\n<div class=\"modal hide fade\" id=\"modal-add-patient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                <br/>\r\n                <div id=\"patient_msg\"></div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <input type=\"hidden\" name=\"app[provider]\" id=\"data-provider\" value=\"provider\"/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            <!--\r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Add & Continue\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n            -->\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n</script>\r\n\r\n<script>\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        // hn\r\n        // $(\'#data-hn\').change(update_patient);\r\n    });\r\n</script>\r\n\r\n\r\n<div class=\"modal hide fade\" id=\"modal-pin\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Access PIN</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"pin\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Please input your PIN : </label></span>	\r\n                    <input type=\"password\" name=\"record[pin]\" id=\"data-pin\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n            <input type=\"hidden\" name=\"id\" value=\"<%= params[:id] %>\">\r\n            <%= f.hidden_field :mode, :id=>\'data-mode\', :value=>\'\' %>\r\n            <%= f.hidden_field :service_id, :id=>\'data-service_id\', :value=>\'\' %>\r\n            \r\n            <%= f.submit \'Submit\', :class=>\'btn btn-info\' %>\r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n<script>\r\n    function confirm_main(id) {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(\'main\');\r\n        $(\'#data-service_id\').val(id);\r\n    }\r\n    function confirm_followup(id) {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(\'followup\');\r\n        $(\'#data-service_id\').val(id);\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#btn-pin\').click(pin);\r\n    });\r\n</script>',NULL,NULL,NULL,'2016-01-20 15:35:41','2016-01-20 15:35:41','patient_record',''),(2046,'index_old',689,2,'<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% -34px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .collapsed {\r\n        background-position: 98% 12px;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n</style>\r\n    <!-- nice form elements -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/uniform/Aristo/uniform.aristo.css\" />\r\n	<!-- 2col multiselect -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/multiselect/css/multi-select.css\" />\r\n\r\n<%= render :inline=>this.init %>\r\n\r\n<%\r\n    msg = []\r\n    tmp = nil\r\n    suc_msg = nil\r\n    \r\n    if request.post?\r\n        if !params[:account].nil?\r\n            if params[:account][:login_name].empty?\r\n                msg.push(\'Invalid login name\')\r\n            end\r\n            if params[:account][:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if params[:account][:password].empty?\r\n                msg.push(\'No password found\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>params[:account][:login_name]).first\r\n                if m_user\r\n                    msg.push(\'Existing login name\')\r\n                else\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(params[:account][:password], salt)\r\n                    tmp = salt + \'...\' + hashed_password\r\n                    m_user = @ehr_models[:user].create :role=>params[:account][:role], :login=>params[:account][:login_name], :salt=>salt, :hashed_password=>hashed_password, :email=>params[:account][:email], :name=>params[:account][:full_name], :activate=>\"true\"\r\n                    tmp = m_user.id.to_s\r\n                    \r\n                    m_provider = @models[:provider].create :group=>\'default\', :name=>params[:account][:full_name], :login=>params[:account][:login_name], :provider_type=>\'1\'\r\n                    tmp += \'...\' + m_provider.id.to_s\r\n                end\r\n            end\r\n        elsif px = params[:public_pass]\r\n            m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n\r\n            pri = px[:pri_password]\r\n            if pri == m_user[:pin]\r\n                pub = px[:pub_password]\r\n                \r\n                salt = User.random_string(10) \r\n                hashed_password = User.encrypt(px[:pub_password], salt)\r\n                m_user[:hashed_password] = hashed_password\r\n                m_user[:salt] = salt\r\n                m_user.save\r\n                suc_msg= \"<strong>Success</strong> Your public password has been change\".html_safe\r\n            else\r\n                msg.push(\'Invalid private password\')\r\n            end\r\n            \r\n        elsif px = params[:private_pass]\r\n            new_pri = px[:new_private]\r\n            con_pri = px[:con_private]\r\n            \r\n            cur_pri = px[:cur_private]\r\n            \r\n            if new_pri != con_pri\r\n                msg.push(\'Your new and confirm password does not match\')\r\n            end\r\n        \r\n            m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n            \r\n            if msg.empty?\r\n                if !m_user[:pin].nil?\r\n                    if cur_pri == m_user[:pin] and new_pri == con_pri\r\n                        m_user[:pin] = new_pri\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your private password has been change\".html_safe\r\n                        \r\n                        session[:pin] = new_pri\r\n                    else\r\n                        msg.push(\'Invalid current private password\')\r\n                    end\r\n                else\r\n                    if new_pri == con_pri\r\n                        m_user[:pin] = new_pri\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your private password has been update\".html_safe\r\n                        \r\n                        session[:pin] = new_pri\r\n                    end\r\n                end\r\n            end\r\n        elsif !params[:profile].nil?\r\n            px = params[:profile]\r\n            if px[:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if px[:confirm_private].empty?\r\n                msg.push(\'No password to confirm your change\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>px[:login_name]).first\r\n                salt = m_user[:salt]\r\n                hashed_password = User.encrypt(px[:cur_password], salt)\r\n                if m_user[:hashed_password] == hashed_password\r\n                    if px[:con_password] == px[:new_password] and px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov[:main_hospital] = px[:main_hospital]\r\n                            m_prov[:part_time_hospital] = px[:part_time_hospital].join(\'|\') if !px[:part_time_hospital].nil?\r\n                            # m_prov.update_attributes(:main_hospital=>px[:main_hospital],:name=>px[:full_name],:part_time_hospital=>px[:part_time_hospital])\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        suc_msg= \"<strong>Success</strong> Your profile has been change\".html_safe\r\n                    elsif px[:con_password] == px[:new_password] and !px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov[:main_hospital] = px[:main_hospital]\r\n                            m_prov[:part_time_hospital] = px[:part_time_hospital].join(\'|\') if !px[:part_time_hospital].nil?\r\n                            # m_prov.update_attributes(:main_hospital=>px[:main_hospital],:name=>px[:full_name],:part_time_hospital=>px[:part_time_hospital])\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(px[:new_password], salt)\r\n                        m_user[:hashed_password] = hashed_password\r\n                        m_user[:salt] = salt\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your profile and password has been change\".html_safe\r\n                    else\r\n                        msg.push(\'Your new and confirm password does not match\')\r\n                    end\r\n                    \r\n                else\r\n                    msg.push(\'Your current password does not match\')\r\n                end\r\n                # msg.push(px[:login_name])\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n<%#list.inspect%>\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                            <div id=\"accordion1\" class=\"accordion\">\r\n\r\n<%\r\n    if !msg.empty?\r\n        for m in msg do\r\n%>\r\n                                <div class=\"alert alert-error\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= m %>\r\n    							</div>\r\n<%\r\n        end\r\n    elsif suc_msg\r\n%>\r\n                                <div class=\"alert alert-success\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= suc_msg %>\r\n    							</div>\r\n<%\r\n    end\r\n%>\r\n\r\n<%\r\n    # check admin or developer role\r\n    if (@current_role == \'admin\' and session[:owner]) or @current_role == \'developer\'\r\n        usr = @ehr_models[:user].all.collect do |i|\r\n            role = @ehr_models[:role].find(i.role)\r\n            role_name = \'undefined\'\r\n            if role\r\n                role_name = role[:name]\r\n            end\r\n            provider = @models[:provider].where(:login=>i.login).first\r\n            \r\n            if provider\r\n                {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :i=>i}\r\n            end\r\n        end\r\n%>\r\n\r\n<% \r\n        m_hos = @models[:hospital]\r\n        m_com = @models[:implant_company]\r\n        m_imp = @models[:implant_profile]\r\n        \r\n        c_hos = m_hos.all.count\r\n        c_com = m_com.all.count\r\n        c_imp = m_imp.all.count\r\n%>\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#admin-control\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Admin Control\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse\" id=\"admin-control\">\r\n										<div class=\"accordion-inner\">\r\n										    <ul class=\"dshb_icoNav tac\">\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/first-aid.png)\" href=\"../Hospital/index\">\r\n										                <span class=\"label label-success\"><%= c_hos > 100 ? \"+100\" : c_hos.to_s %></span> Hospital</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/home.png)\" href=\"../ImplantCompany/index\">\r\n										                <span class=\"label label-important\"><%= c_com > 100 ? \"+100\" : c_com.to_s %></span> Company</a></li>\r\n										        <li><a style=\"font-size:0.8em;background-image: url(/gebo/img/gCons/home.png)\" href=\"../ImplantCompany/index\">\r\n										                <span class=\"label label-info\"><%= @models[:implant_company].all.count.to_s %></span> Implant Company</a></li>\r\n										                <br/>\r\n										        <li><a href=\"../ImplantProfile/index\">Implant Profile</a></li>\r\n										        <li><a style=\'font-size:0.7em;\' href=\"../ImplantComponent/index\">Implant Component</a></li>\r\n										        <li><a href=\"../ImplantType/index\">Implant Type</a></li>\r\n										        <li><a href=\"../ImplantMaterial/index\">Implant Material</a></li>\r\n										    </ul>\r\n										    <!--\r\n										    <ul class=\"dshb_icoNav tac\">\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/multi-agents.png)\" href=\"javascript:void(0)\"><span class=\"label label-info\">+10</span> Users</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/world.png)\" href=\"javascript:void(0)\">Map</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/configuration.png)\" href=\"javascript:void(0)\">Settings</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/lab.png)\" href=\"javascript:void(0)\">Lab</a>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/van.png)\" href=\"javascript:void(0)\"><span class=\"label label-success\">$2851</span> Delivery</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/pie-chart.png)\" href=\"javascript:void(0)\">Charts</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/edit.png)\" href=\"javascript:void(0)\">Add New Article</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/add-item.png)\" href=\"javascript:void(0)\"> Add New Page</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/chat-.png)\" href=\"javascript:void(0)\"><span class=\"label label-important\">26</span> Comments</a></li>\r\n                							</ul>\r\n                							-->\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Manage Account\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse\" id=\"collapseOne1\">\r\n										<div class=\"accordion-inner\">\r\n										    <!--<div id=\"form-panel\" class=\"row-fluid\"><%= link_to \'Add New\', \'add_new?update=form-panel\', :remote=>true, :class=>\'btn\', :style=>\'float:right\' %>-->\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :account, :url=>\"index\", :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Add New Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">no space, special characters</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'member\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:class=>\'btn\', :style=>\'vertical-align: top;\' %></span>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n											<!--<hr/>-->\r\n                                            <div id=\"account\">\r\n											<table class=\"table\">\r\n        										<thead>\r\n        											<tr>\r\n        												<th>No.</th>\r\n        												<th>Login Name</th>\r\n        												<th>Name</th>\r\n        												<th>Role</th>\r\n        												<th>Actions</th>\r\n        											</tr>\r\n        										</thead>\r\n        										<tbody>\r\n        										<% \r\n        										    no = 1\r\n        										    for i in usr.compact do\r\n        										\r\n        										%>\r\n        										    <tr>\r\n        										        <td><%= no %>.</td>\r\n        										        <td><%= i[:login] %></td>\r\n        										        <td><%= i[:provider_name] %></td>\r\n        										        <td><%= i[:role_name] %></td>\r\n        										        <td>\r\n        										            <%= link_to \'\', \'#\', :title=>\'Delete Account\', :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>&nbsp;&nbsp;&nbsp;\r\n        										            <%= link_to \'\', \'#\', :title=>\'Edit Account\', :class=>\'splashy-contact_blue_edit\', :onclick=>\"javascript:confirm_edit(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>\r\n        										        </td>\r\n        										    </tr>\r\n        										<%\r\n        										    no += 1\r\n        										    end\r\n        										%>\r\n        										</tbody>\r\n        									</table>\r\n										</div>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n<%\r\n    end\r\n%>\r\n\r\n											<%\r\n											    cur_user = @ehr_models[:user].where(:login=>@current_user.to_s).first\r\n											    cur_prov = @models[:provider].where(:login=>@current_user.to_s).first\r\n											%>\r\n											\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n									    <!--<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle \">-->\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											User Profile\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseTwo1\">-->\r\n									<div class=\"accordion-body collapse\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :profile, :class=>\'\', :url=>params[:opt] ,:method=>\'POST\' do |f| %>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your information</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\', :value=>@current_user, :disabled=>\'disabled\' %>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\', :value=>cur_user[:name] if cur_user %> \r\n        													<span class=\"help-block\">your account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<hr/>\r\n<%\r\n    main_hospital = cur_prov[:main_hospital] if cur_prov\r\n    part_time_hospital = cur_prov[:part_time_hospital] if cur_prov\r\n    part_time_hospital = [] unless part_time_hospital\r\n\r\n    m_hosp = get_model[:hospital]\r\n    \r\n    map_hospital = {}\r\n    map_hospital[\"\"] = \"Please select hospital\"\r\n    \r\n    map_region = {\r\n        \'1\'=>\'กรุงเทพ\',\r\n        \'2\'=>\'ปริมณฑล\',\r\n        \'3\'=>\'ภาคกลาง\',\r\n        \'4\'=>\'ภาคเหนือ\',\r\n        \'5\'=>\'ภาคใต้\',\r\n        \'6\'=>\'ภาคอิสาน\',\r\n        \'7\'=>\'ภาคตะวันออก\',\r\n        \'8\'=>\'ภาคตะวันตก\'}\r\n    map_reg_hosp = {}\r\n    \r\n    sel_txt = \"\"\r\n    a_hosp = m_hosp.all\r\n    for i in a_hosp do\r\n        map_hospital[i.id.to_s] = i[:hospital_name_thai]\r\n        if !map_reg_hosp.has_key? i[:region]\r\n            map_reg_hosp[i[:region]] = {}\r\n        end\r\n        # if i.id.to_s == main_hospital\r\n        #     next\r\n        # end\r\n        map_reg_hosp[i[:region]][i.id.to_s] = i[:hospital_name_thai]\r\n    end \r\n%>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Main Hospital</label>\r\n        												<div class=\"controls\">\r\n        												\r\n        												    <%# f.select :main_hospital, map_hospital, :selected => a_hosp.last[:hospital_name_thai], :class=>\'span10\' %>\r\n        												    <select name=\"profile[main_hospital]\" id=\"profile_main_hospital\" class=\"span10\">\r\n<%\r\n    map_hospital.each do |k,v|\r\n        sel = \'\'\r\n        if main_hospital == k\r\n            sel = \' selected=\"selected\"\'\r\n        end\r\n%>\r\n                                                                <option value=\"<%=k%>\"<%= sel %>><%=v%></option>\r\n<% \r\n    end\r\n%>\r\n        												    </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Part Time Hospital</label>\r\n        												<div class=\"controls\">\r\n        												    <%# f.select :main_hospital, map_hospital, :selected => a_hosp.last[:hospital_name_thai], :class=>\'span10\' %>\r\n        												    <select name=\"profile[part_time_hospital][]\" multiple=\"multiple\" class=\"multiselect\" >\r\n<%\r\n    opt_txt = \"\"\r\n    sel_txt = \"\"\r\n    list_part_time = part_time_hospital.split(\'|\')\r\n    # list_part_time = [\'55c5ba20790f9b1672000004\',\'55c4e3ed790f9b223e000002\']\r\n    map_reg_hosp.each do |k,v|\r\n        opt_txt += \"<optgroup label=\'\\\\#{map_region[k]}\'>\"\r\n        v.each do |x,y|\r\n            if list_part_time.include? x\r\n                # sel_txt += \"<li class=\'ms-elem-selected\' ms-value=\'\\\\#{x}\'>\\\\#{y}</li>\"\r\n                opt_txt += \"<option value=\'\\\\#{x}\' selected>\\\\#{y}</option>\"\r\n            else\r\n                opt_txt += \"<option value=\'\\\\#{x}\'>\\\\#{y}</option>\"\r\n            end\r\n        end\r\n        opt_txt += \"</optgroup>\"\r\n    end\r\n%>\r\n                                                                <%= opt_txt.html_safe %>\r\n        												    </select>\r\n        												    <a id=\"select_all\" href=\"javascript:void(0)\">Select All</a> / <a id=\"deselect_all\" href=\"javascript:void(0)\">Deselect All</a>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm Private</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Information using Private Password\" class=\"span10\" name=\"[profile]confirm_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your information</span>\r\n        												</div>\r\n        											</div>\r\n        											<!--\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Public Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Public Password\" class=\"span10\" name=\"[profile]pub_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">make change your public password</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Private Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Private Password\" class=\"span10\" name=\"[profile]pri_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm to change your public password</span>\r\n        												</div>\r\n        											</div>\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        											<%\r\n        											    ctrl = \'\'\r\n        											    if @current_role==\'developer\'\r\n        											        ctrl = \'disable\'\r\n        											    elsif cur_user[:pin].nil? or cur_user[:pin] == \'\'\r\n        											        ctrl = \'readonly\'\r\n        									            end\r\n        											%>\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Private Password\" class=\"span10\" name=\"[profile]cur_private\" <%= ctrl %>>\r\n        													<span class=\"help-block\">your private password</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Private Password\" class=\"span10\" name=\"[profile]new_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your private password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Private Password\" class=\"span10\" name=\"[profile]con_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new private password</span>\r\n        												</div>\r\n 