fieldset>\r\n        											<p class=\"f_legend\">Update your private password</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Private Password\" class=\"span10\" name=\"[private_pass]cur_private\" <%= ctrl %>>\r\n        													<span class=\"help-block\">your private password</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Private Password\" class=\"span10\" name=\"[private_pass]new_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your private password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Private Password\" class=\"span10\" name=\"[private_pass]con_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new private password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n        										\r\n        										<% end %>\r\n        									</div>\r\n        								</div>\r\n        							</div>\r\n								</div>\r\n							</div>\r\n                        \r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<br/>\r\n\r\n<script>\r\n    refresh();\r\n    \r\n    function confirm_delete(uid, pid) {\r\n        if (confirm(\'Are you sure?\') == true) {\r\n<%\r\n            destroy_url = \'destroy?id=\'\r\n%>\r\n            \r\n            url = \"destroy?uid=\" + uid + \"&pid=\" + pid;\r\n            window.location = url;\r\n        }\r\n    }\r\n    \r\n    function confirm_edit(uid, pid) {\r\n        // if (alert(\'Are you sure?\') == true) {\r\n            \r\n        // }\r\n        \r\n    }\r\n</script>\r\n            <!-- styled form elements -->\r\n            <script src=\"/gebo/lib/uniform/jquery.uniform.min.js\"></script>\r\n            <!-- multiselect -->\r\n            <script src=\"/gebo/lib/multiselect/js/jquery.multi-select.min.js\"></script>\r\n            <!-- enhanced select (chosen) -->\r\n            <script src=\"/gebo/lib/chosen/chosen.jquery.min.js\"></script>\r\n<script>\r\n    $(document).ready(function() {\r\n		//* 2col multiselect\r\n		multiz.init();\r\n		\r\n	});\r\n    //* multiselect\r\n	multiz = {\r\n		init: function(){\r\n			\r\n			$(\'.multiselect\').multiSelect({\r\n				selectableHeader	: \'<h4>Selectable Hospitals</h4>\',\r\n				selectedHeader		: \'<h4>Selected Hospitals</h4>\'\r\n			});\r\n			$(\'.ms-elem-selectable\').hide();\r\n			$(\'.ms-elem-selectable\').click(function(){\r\n			   console.log($(this).attr(\'ms-value\')); \r\n			});\r\n// 			$(\'.ms-selection\').find(\'ul.ms-list\').html(\'<li class=\"ms-elem-selected\" ms-value=\"55c4e3ed790f9b223e000002\">โรงพยาบาลตำรวจ</li><li class=\"ms-elem-selected\" ms-value=\"55c5ba20790f9b1672000004\">โรงพยาบาลจุฬาลงกรณ์</li>\');\r\n// 			$(\'#ms-optgroup .ms-selectable, #ms-outsideCountries .ms-selectable\').find(\'li.ms-elem-selectable\').hide();\r\n			$(\'.ms-optgroup-label\').click(function(){\r\n				if ($(this).hasClass(\'ms-collapse\')){\r\n					$(this).nextAll(\'li\').hide();\r\n					$(this).removeClass(\'ms-collapse\'); \r\n				} else {\r\n					$(this).nextAll(\'li:not(.ms-selected)\').show();\r\n					$(this).addClass(\'ms-collapse\');\r\n				}\r\n			});\r\n		  \r\n// 			$(\'#searchable-form\').multiSelect({\r\n// 				selectableHeader : \'<input type=\"text\" id=\"multi_search\" autocomplete=\"off\" placeholder=\"search\" />\',\r\n// 				selectedHeader	 : \'<a href=\"javascript:void(0)\" id=\"sForm_deselect\" class=\"btn\">Deselect All</a>\'\r\n// 			});\r\n		\r\n// 			$(\'input#multi_search\').quicksearch(\'#ms-searchable-form .ms-selectable li\');\r\n// 			$(\'#searchable-form\').multiSelect();\r\n			\r\n			$(\'#select_all\').on(\'click\', function(){\r\n				$(\'.multiselect\').multiSelect(\'select_all\');\r\n				return false;\r\n			});\r\n			\r\n			$(\'#deselect_all\').on(\'click\', function(){\r\n				$(\'.multiselect\').multiSelect(\'deselect_all\');\r\n				return false;\r\n			});\r\n			\r\n			$(\'#sForm_deselect\').on(\'click\', function(){\r\n				$(\'#searchable-form\').multiSelect(\'deselect_all\');\r\n				return false;\r\n			});\r\n\r\n		}\r\n	};\r\n</script>',NULL,NULL,NULL,'2016-01-20 16:57:43','2016-01-20 16:57:43','index_old',''),(2047,'index',819,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.fields\r\n query=\'\'\r\n#  xxx = \'\'\r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            if f.column_name\r\n                keys <<{f.column_name.to_sym=>Regexp.new(query, \'i\')}\r\n            end\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<%= form_for :search, :url=>params[:opt], :id=>\'search\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n<% if @current_role==\'developer\' %>\r\n... <%# params[:search].to_json.html_safe %> <%= criteria.to_json.html_safe %> ...\r\n<% end %>\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2016-01-20 18:36:47','2016-01-20 18:36:47','index',''),(2048,'export',463,3,'\r\n<%\r\n\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n\r\n  @document = get_document(this.document_name)\r\n\r\n  doc = @document\r\n\r\n  data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n  \r\n   fields = @document.fields\r\n   fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n   fields = fields.compact!\r\n   fields << \'created_at\'\r\n   fields << \'updated_at\'\r\n    @document = doc\r\n    @fields = @document.fields\r\n   \r\n   data.collect! do |i|\r\n    \r\n    @record = i\r\n \r\n \r\n   sofa = [\'rs\',\'temperature\',\'coagulation\',\'cns\',\'liver\',\'renal\',\'cvs\']\r\n      sum = 0 \r\n   for j in sofa\r\n        v = i[j]\r\n        if v and v.strip.downcase == \'na\'\r\n            v = \'0\'\r\n        end\r\n        sum += v.to_i if v \r\n      end\r\n      \r\n    i[\'sofa\'] = sum\r\n \r\n    \r\n    \r\n    \r\n    p = nil\r\n    age = nil\r\n    age = 0\r\n    hn = nil\r\n    \r\n    p = @patient_model.new\r\n    m = @module_model.collection.find(:module_id=>i.id).first\r\n    if m \r\n    \r\n    patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n    if patient\r\n    bdate = 0\r\n    bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n    age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n   \r\n    p = patient\r\n    \r\n\r\n    end\r\n   end\r\n    if p\r\n    r = {:patient=>p,:age=>age,:record=>i}\r\n    else\r\n    r = nil\r\n    end\r\n    \r\n    r\r\n   \r\n   end\r\n   \r\n   data.compact!\r\n   data = data.sort{|a,b| a[:patient][\'patient_order\'].to_i<=>b[:patient][\'patient_order\'].to_i }\r\n   \r\n   \r\n   \r\n   unless params[:type]\r\n   \r\n%>\r\n<table>\r\n<tr><td>Order</td><td>Patient number</td><td>Gender</td><td>Birth Date</td><td>Age</td>\r\n\r\n<%\r\nfor i in fields \r\n%><td><%= i[1] %></td>\r\n<% end %>\r\n</tr>\r\n<% for i in data \r\n\r\n   p = i[:patient]\r\n   age = i[:age]\r\n   @record = i[:record] \r\n  \r\n    bd = p[\'birth_date\'].strftime(\'%d-%m-%Y\') if !p[\'birth_date\'].nil?    \r\n%>\r\n<tr>\r\n<td><%=p[\'patient_order\'] %></td><td><%=p[\'patient_number\']%></td><td><%=p[\'gender\']%></td><td><%=bd%></td><td><%=age%></td>\r\n\r\n<%\r\n    \r\n    for j in fields \r\n    \r\n    if @record[j[0]]\r\n%>\r\n<td><%= render_value j[0] %></td>\r\n<% else %>\r\n<td>.</td>\r\n<% end %>\r\n<% end %>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% else \r\nif params[:type]==\'csv\'\r\n    require \'csv\'\r\nres = CSV.generate do |csv|\r\n  csv << [\"patient_order\", \"patient_number\", \"gender\", \"birth_date\",\"age\"]+fields.collect{|i| i[0]}\r\n  for i in data \r\n  p = i[:patient]\r\n  age = i[:age]\r\n  @record = i[:record]\r\n  lines = []\r\n  lines = fields.collect{|j| \r\n  if @record[j[0]]\r\n    res = render_value(j[0]).strip\r\n  else\r\n    res = \'\'\r\n  end\r\n  res\r\n  }\r\n  \r\n  csv << [p[\'patient_order\'], p[\'patient_number\'],p[\'gender\'],p[\'birth_date\'],age]+lines \r\n  end\r\n  # ...\r\nend\r\n%><%=res.html_safe%><%\r\nend\r\nend%>\r\n  \r\n  \r\n   \r\n   \r\n   ',NULL,NULL,NULL,'2016-01-22 09:47:27','2016-01-22 09:47:27','export','*'),(2049,'export_zam_collapse',463,3,'<%\r\n\r\n    @module_name = @current_project.name+\'#\'+ this.table_name \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n\r\n    @document = get_document(this.document_name)\r\n\r\n    doc = @document\r\n\r\n    data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n  \r\n    fields = @document.fields\r\n#   fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n    cols = %w{vasopressor rs coagulation cns liver renal cvs diuretic lactate sofa if_rrt mechanical_ventilation net_balance indication mode_of_rrt}\r\n    fields = fields.collect do |i|\r\n        col_name = i.column_name.to_s\r\n        if cols.include?(col_name)\r\n            [i.column_name,i.name] unless Document.visual_types.index(i.field_type)\r\n        end\r\n    end\r\n    fields = fields.compact!\r\n    fields << \'created_at\'\r\n    fields << \'updated_at\'\r\n    @document = doc\r\n    @fields = @document.fields\r\n   \r\n    data.collect! do |i|\r\n    \r\n        @record = i\r\n     \r\n     \r\n        # sofa = [\'rs\',\'temperature\',\'coagulation\',\'cns\',\'liver\',\'renal\',\'cvs\']\r\n        # sum = 0 \r\n        # for j in sofa\r\n        #     v = i[j]\r\n        #     if v and v.strip.downcase == \'na\'\r\n        #         v = \'0\'\r\n        #     end\r\n        #     sum += v.to_i if v \r\n        # end\r\n          \r\n        # i[\'sofa\'] = sum\r\n     \r\n        p = nil\r\n        age = nil\r\n        age = 0\r\n        hn = nil\r\n        \r\n        p = @patient_model.new\r\n        m = @module_model.collection.find(:module_id=>i.id).first\r\n        if m \r\n            patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n            if patient\r\n                bdate = 0\r\n                bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n                age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n                p = patient\r\n            end\r\n        end\r\n        \r\n        if p\r\n            r = {:patient=>p,:age=>age,:record=>i}\r\n        else\r\n            r = nil\r\n        end\r\n    \r\n        # collect record to data\r\n        r\r\n   \r\n    end\r\n   \r\n    data.compact!\r\n    data = data.sort{|a,b| a[:patient][\'patient_order\'].to_i<=>b[:patient][\'patient_order\'].to_i }\r\n   \r\n    unless params[:type]\r\n   \r\n%>\r\n<table>\r\n    <tr>\r\n        <td>Order</td>\r\n        <td>Patient number</td>\r\n        <td>Gender</td>\r\n        <td>Birth Date</td>\r\n        <td>Age</td>\r\n<%\r\n    for i in fields \r\n%>\r\n        <td><%= i[1] %></td>\r\n<% end %>\r\n    </tr>\r\n<% \r\n    for i in data \r\n        p = i[:patient]\r\n        age = i[:age]\r\n        @record = i[:record] \r\n%>\r\n    <tr>\r\n        <td><%=p[\'patient_order\'] %></td>\r\n        <td><%=p[\'patient_number\']%></td> \r\n        <td><%=p[\'gender\']%></td>\r\n        <td><%=p[\'birth_date\'] ? p[\'birth_date\'].strftime(\'%d/%m/%Y\') : \'-\'%></td>\r\n        <td><%=age%></td>\r\n<%\r\n        for j in fields \r\n            if @record[j[0]]\r\n%>\r\n        <td><%= render_value j[0] %></td>\r\n<% \r\n            else \r\n%>\r\n        <td>.</td>\r\n<%          end %>\r\n<%      end %>\r\n</tr>\r\n<%  end %>\r\n</table>\r\n<% else \r\n    if params[:type]==\'csv\'\r\n        require \'csv\'\r\n        res = CSV.generate do |csv|\r\n            csv << [\"patient_order\", \"patient_number\", \"gender\", \"birth_date\",\"age\"]+fields.collect{|i| i[0]}\r\n            for i in data \r\n                p = i[:patient]\r\n                age = i[:age]\r\n                @record = i[:record]\r\n                lines = []\r\n                lines = fields.collect{|j| \r\n                    if @record[j[0]]\r\n                        res = render_value(j[0]).strip\r\n                    else\r\n                        res = \'\'\r\n                    end\r\n                    res\r\n                }\r\n  \r\n                csv << [p[\'patient_order\'], p[\'patient_number\'],p[\'gender\'],p[\'birth_date\'] ? p[\'birth_date\'].strftime(\'%d/%m/%Y\') : \'-\',age]+lines \r\n            end\r\n  # ...\r\n        end\r\n%>\r\n<%=res.html_safe%>\r\n<%\r\n    end\r\nend\r\n%>\r\n  \r\n  \r\n   \r\n   \r\n   ',NULL,NULL,NULL,'2016-01-22 09:51:24','2016-01-22 09:51:24','export_zam_collapse','*'),(2050,'export_check',477,3,'<%\r\n    @document = get_document(this.document_name)\r\n    @fields = @document.fields\r\n    fields = @document.fields\r\n    fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n    \r\n    fields << \'created_at\'\r\n    fields << \'updated_at\'\r\n    @fields = fields  \r\n   \r\n    # @patients = Schema::Patient.all\r\n    @patients = get_model[:patient].all\r\n    @patients.collect!{|i| i if i.patient_order}.compact!\r\n    @patients.sort!{|a,b| a.patient_order <=> b.patient_order }\r\n    \r\n    pat_ids = []\r\n    @patients.each do |i|\r\n        pat_ids << i.id\r\n    end    \r\n    \r\n    \r\n    emr = @context.get_projects_by_abstract(\'ehr.emr\')[0]\r\n    i_case = {}\r\n    m_case_1 = emr.get_model[:case_record].where(:record_day=>\'1\').all\r\n    m_cids = m_case_1.collect do |i| \r\n        i_case[i.id] = i\r\n        i.id\r\n    end\r\n    m_case_name = \"\\\\#{emr.name}#case_record\"\r\n    \r\n    pat_mod = get_model[:patient_module].where(:module_name=>m_case_name,:patient_id=>pat_ids,:module_id=>m_cids)\r\n    p_case = {}\r\n    pat_mod.each do |i|\r\n        p_case[i[:patient_id]] = i_case[i[:module_id]]\r\n    end\r\n   \r\n#   apache = [\'chronic_health_points\',\'temperature\',\'mean_arterial\',\'heart_rate\',\'respiratory_rate\',\'oxygenation\',\'arterial_ph\',\'serum_sodium\',\'serum_potassium\',\'serum_creatinine\',\'hematocrit\',\'white_blood_count\']\r\n#   for i in @patients\r\n#       sum = 0 \r\n#       for j in apache\r\n#         v = i[j]\r\n#         if v.strip.downcase == \'na\'\r\n#             v = \'0\'\r\n#         end\r\n#         sum += v.to_i \r\n#       end\r\n      \r\n#       i[\'apache_ii\'] = sum\r\n      \r\n#   end\r\n   \r\n    fd = []\r\n    tmp_field = %w{patient_number patient_order weight ideal_body_weight reference ckd esrd date_of_admission date_of_baseline_serum_cr date_of_icu_admission baseline_serum_creainine_by_mdrd baseline_serum_cr first_available_cr_date first_available_cr available_baseline note}\r\n    @fields.each do |i|\r\n        if tmp_field.include? i[0]\r\n            fd << i\r\n        end\r\n    end\r\n    # fd << [\'note\', \'Note\']\r\n	unless params[:type]\r\n# 		cols = %w{reimbursement diagnosis }\r\n        \r\n%>\r\n<%= stylesheet_link_tag    \"application\"  %>\r\n<!--<%= p_case.count.to_json.html_safe %>-->\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n	<tr>\r\n<% \r\n# 		for f in @fields \r\n		for f in fd\r\n%>\r\n		<th><%=f[1]%></th>\r\n<% \r\n		end # table header\r\n%>\r\n	</tr>\r\n<%\r\n        \r\n		for p in @patients\r\n		    if p_case[p.id].nil?\r\n		        next\r\n		    end\r\n			# find baseline Cr\r\n			d_hos = p[:date_of_admission] # date of Hospital admission\r\n			d_icu = p[:date_of_icu_admission] # date of ICU admission\r\n			d_bas = p[:date_of_baseline_serum_cr] # date of baseline serum Cr\r\n			mdrd = p[:baseline_serum_creainine_by_mdrd] # baseline by calculation\r\n			base = p[:baseline_serum_cr] # checking this field (true baseline)\r\n			ckd  = p[:ckd].downcase\r\n			av = p[:available_baseline]\r\n			g = p[:gender]\r\n				\r\n			p[:reference] = \'0\'\r\n			obj = d_bas # date of TRUE baseline\r\n			if obj.kind_of?(Date) || obj.kind_of?(Time)\r\n            # if obj.is_a?(Date)\r\n				# begin\r\n				# 	# Date.parse(d_bas.to_s)\r\n				# 	d_bas.between?(d_hos, d_icu)\r\n				# 	p[:first_available_cr] = base\r\n				# 	p[:baseline_serum_cr] = \'na\'\r\n					\r\n				# 	fm = mdrd.to_f\r\n				# 	fb = base.to_f\r\n				# 	if fm < fb\r\n				# 		p[:reference] = \'2\'\r\n				# 	end\r\n				# rescue ArgumentError\r\n					\r\n				# end\r\n				if obj >= d_hos and obj < d_icu\r\n				    fm = mdrd.to_f\r\n				    fb = base.to_f\r\n				        p[:first_available_cr] = base\r\n				        p[:baseline_serum_cr] = \'n/a\'\r\n				        p[:date_of_baseline_serum_cr] = nil\r\n				        p[:first_available_cr_date] = obj\r\n				        \r\n				    if ckd==\'yes\'\r\n				        p[:reference] = \'3\'\r\n				        p[:available_baseline] = \'2\'\r\n				        \r\n				        p[:note] = \'CKD [green]\'\r\n				    else\r\n				        p[:ckd] = \'No\'\r\n    				    if fm < fb\r\n    				    \r\n    				        p[:reference] = \'2\'\r\n    				        p[:available_baseline] = \'2\'\r\n    				        \r\n    				        p[:note] = \'cond-1 [green]\'\r\n    				    else\r\n    				        p[:reference] = \'3\'\r\n    				        p[:available_baseline] = \'2\'\r\n    				        \r\n    				        p[:note] = \'cond-2 [green]\'\r\n    				    end\r\n    				end\r\n				elsif obj >= d_hos - 12.months and obj < d_hos\r\n				    p[:reference] = \'1\'\r\n				    p[:available_baseline] = \'1\'\r\n				    \r\n				    p[:note] = \'cond-3 [red]\'\r\n				elsif obj >= d_icu\r\n				    p[:first_available_cr] = base\r\n				    p[:baseline_serum_cr] = \'n/a\'\r\n				    p[:date_of_baseline_serum_cr] = nil\r\n				    p[:first_available_cr_date] = obj\r\n				    p[:available_baseline] = \'2\'\r\n				    \r\n				    fm = mdrd.to_f\r\n				    fb = base.to_f\r\n				    if ckd == \'yes\'\r\n				        p[:reference] = \'3\'\r\n				        \r\n				        p[:note] = \'CKD [orange]\'\r\n				    else\r\n				        p[:ckd] = \'No\'\r\n    				    if fm < fb\r\n    				        p[:reference] = \'2\'\r\n    				    else\r\n    				        p[:reference] = \'3\'\r\n    				    end\r\n    				    \r\n    				    p[:note] = \'cond-4 [orange]\'\r\n    				end\r\n				elsif obj < d_hos - 12.months\r\n				    p[:reference] = \'2\'\r\n				    \r\n				    p[:available_baseline] = \'1\'\r\n				    p[:note] = \'More than 1 year\'\r\n				end\r\n			else\r\n			    p[:reference] = \'1\'\r\n			    p[:available_baseline] = \'1\'\r\n			    \r\n			    p[:patient_number] = \"<font color=\'red\'>\\\\#{p[:patient_number]}</font>\".html_safe\r\n			    p[:note] = \'<font color=\"red\">Assign as TRUE Baseline</font>\'.html_safe\r\n			end\r\n			\r\n			if p[:available_baseline] == \'1\'\r\n			    p[:available_baseline] = \'1|2\'\r\n			    \r\n			    tmp = p_case[p.id]\r\n			    \r\n			    p[:first_available_cr] = tmp[:creatinine]\r\n     		    p[:first_available_cr_date] = d_icu\r\n     		end\r\n				\r\n			# reference 1=true baseline, 2=mdrd, 3=day 1\r\n			@record  = p\r\n\r\n%>\r\n	<tr>\r\n<% \r\n# 			for f in @fields \r\n            for f in fd\r\n        \r\n%>\r\n		<td><%=render_value f[0] %></td>\r\n<% \r\n			end # end value in each field\r\n%>\r\n	</tr>\r\n<% \r\n		end # end each patient\r\n%>\r\n</table>\r\n<% \r\n	else\r\n		require \'csv\'\r\n		res = CSV.generate do |csv|\r\n			csv << fields.collect{|i| i[0]}\r\n			for p in @patients\r\n				csv << fields.collect{|i|\r\n					@record = p\r\n					if p[i[0]]\r\n						r = render_value(i[0]).strip\r\n					else \r\n						r = \'\'\r\n					end\r\n					r\r\n				}\r\n			end # end each patient\r\n		end # end CSV\r\n%>\r\n<%=res.html_safe%>\r\n<% \r\n	end # unless\r\n%>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-01-22 16:40:42','2016-01-22 16:40:42','export_check','*'),(2051,'print',463,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    zam = true\r\n    if @current_role == \'developer\'\r\n        zam = true\r\n    end\r\n     hn = get_setting(\'hn\')\r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    med_id = pm.module_id\r\n    record = models[:case_record].find(med_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<meta content=\"authenticity_token\" name=\"csrf-param\" />\r\n<meta content=\"Z8Zz5QqLaSMVqj2eAmPk3QVfuyVGylmhBMDtf4i/ZFM=\" name=\"csrf-token\" />\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n        display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm_core/banner.png\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3>Case record (daily)</h3>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid;\">\r\n\r\n\r\n\r\n\r\n\r\n<p>\r\n\r\n <!-- show patient -->\r\n<div id=\"patientx\">\r\n<p style=\"width:900px; margin-left:auto; margin-right:auto; font-weight:bold\">Hospital No :&nbsp;<v><%=patient.patient_number %> / <%= hn %></v> </p>\r\n<hr><br>\r\n<% if record[\'record_day\']!=\"\" %>\r\n<div id=\"record_day\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;min-height:30px;\">\r\n<span class=\"\"><label>Record day : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n\r\n<v><%=render_value \'record_day\'%></v>\r\n	\r\n\r\n</div>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n<% if record[\'case_status\']!=\"\" %>\r\n<div id=\"case_status\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;min-height:30px;\">\r\n<span class=\"\"><label>Case status : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n\r\n<v><%=render_value \'case_status\'%></v>\r\n	\r\n\r\n</div>\r\n</div>\r\n</div>\r\n<% end%>\r\n\r\n<% if record[\'move_out_time\']!=\"\" and zam %>\r\n<div id=\"case_status\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;min-height:30px;\">\r\n<span class=\"\"><label>Move out time : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n\r\n<v><%=render_value \'move_out_time\'%></v>\r\n	\r\n\r\n</div>\r\n</div>\r\n</div>\r\n<% end%>\r\n\r\n\r\n<div style=\"width:100%;border: 0px solid red;background:#fff;padding-top:0px;padding-bottom:0px\" id=\"form-data\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:900px;background:#fff;padding:0px;border:0px solid red\">\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n	\r\n\r\n\r\n	<div id=\"283-F7144901528\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;width:500px\">\r\n		<b>Case record </b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n<% if record[\'bun\']!=nil %>\r\n<div id=\"bun\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:110px;\">\r\n<span class=\"\"><label>BUN : </label></span>	\r\n<v><%=render_value \'bun\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'creatinine\']!=nil %>\r\n<div id=\"creatinine\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n<span class=\"\"><label>Creatinine : </label></span>	\r\n<v><%=render_value \'creatinine\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'urine_output24hr\']!=nil %>\r\n<div id=\"urine_output24hr\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:160px;\">\r\n<span class=\"\"><label>Urine output/24hr : </label></span>	\r\n<v><%=render_value \'urine_output24hr\'%></v>\r\n</div>\r\n<% end%>\r\n<div class=\"clear\"></div>\r\n	\r\n\r\n<% if record[\'intake\']!=nil %>\r\n<div id=\"intake\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:160px;\">\r\n<span class=\"\"><label>Intake : </label></span>	\r\n<v><%=render_value \'intake\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<% if record[\'output\']!=nil %>\r\n<div id=\"output\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Output : </label></span>	\r\n<v><%=render_value \'output\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<% if record[\'net_balance\']!=nil %>\r\n<div id=\"net_balance\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:160px;\">\r\n<span class=\"\"><label>Net balance : </label></span>	\r\n<v><%=render_value \'net_balance\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<% if record[\'urine_output_cal\']!=nil %>\r\n<div id=\"urine_output_cal\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:220px;\">\r\n<span class=\"\"><label>Urine output (ml/kg/hr.) : </label></span>	\r\n<v><%=render_value \'urine_output_cal\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<div class=\"clear\"><br/></div>\r\n\r\n	\r\n\r\n\r\n	\r\n\r\n<% if record[\'mechanical_ventilation\']!=\"\" %>\r\n<div id=\"mechanical_ventilation\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n<span class=\"\"><label>Mechanical ventilation : </label></span>	\r\n<v><%=render_value \'mechanical_ventilation\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'vasopressor\']!=\"\" %>\r\n<div id=\"vasopressor\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Vasopressor : </label></span>	\r\n<v><%=render_value \'vasopressor\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n<% if record[\'vasopressor_type\']!=\"\" and render_value(\'vasopressor\')==\'Yes\' %>\r\n<div id=\"vasopressor_type\" class=\" vasopressor_type portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:220px;\">\r\n<span class=\"\"><label>Vasopressor type : </label></span>	\r\n<v><%=render_value \'vasopressor_type\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<div class=\'clear\'></div>\r\n\r\n<% if zam %>\r\n\r\n<% if record[\'rate_of_vasopressor\']!=\"\" and render_value(\'vasopressor\')==\'Yes\' %>\r\n<div id=\"rate_of_vasopressor\" class=\" vasopressor_type portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Rate of vasopressor (ml/hr) : </label></span>	\r\n<v><%=render_value \'rate_of_vasopressor\'%></v>\r\n</div>\r\n<% end%>\r\n<% if record[\'dose_of_vasopressor\']!=\"\" and render_value(\'vasopressor\')==\'Yes\' %>\r\n<div id=\"dose_of_vasopressor\" class=\" vasopressor_type portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Dose of vasopressor (mg) : </label></span>	\r\n<v><%=render_value \'dose_of_vasopressor\'%></v>\r\n</div>\r\n<% end%>\r\n<% if record[\'ml_of_vasopressor\']!=\"\" and render_value(\'vasopressor\')==\'Yes\' %>\r\n<div id=\"ml_of_vasopressor\" class=\" vasopressor_type portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ml of vasopressor : </label></span>	\r\n<v><%=render_value \'ml_of_vasopressor\'%></v>\r\n</div>\r\n<% end%>\r\n<% if record[\'patient_weight\']!=\"\" and render_value(\'vasopressor\')==\'Yes\' %>\r\n<div id=\"patient_weight\" class=\" vasopressor_type portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Patient weight (kg) : </label></span>	\r\n<v><%=render_value \'patient_weight\'%></v>\r\n</div>\r\n<% end%>\r\n<% if record[\'cal_dose_vasopressor\']!=\"\" and render_value(\'vasopressor\')==\'Yes\' %>\r\n<div id=\"cal_dose_vasopressor\" class=\" vasopressor_type portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Dose vasopressor (mcg/kg/min) : </label></span>	\r\n<v><%=render_value \'cal_dose_vasopressor\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<% end # zam %>\r\n\r\n	\r\n\r\n<div class=\"clear\"></div>\r\n	\r\n<% if record[\'sofa\'] and zam%>\r\n    <div style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>SOFA (Day 1 to Day 3)</b>\r\n	</div>\r\n\r\n<% if record[\'rs\']!=\"\" %>\r\n<div id=\"rs\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left\">\r\n<span class=\"\"><label>PaO2/FiO2 : </label></span>	\r\n<v><%=render_value \'rs\'%></v>\r\n</div>\r\n<% end%>\r\n<% if record[\'coagulation\']!=\"\" %>\r\n<div id=\"coagulation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left\">\r\n<span class=\"\"><label>Platelet : </label></span>	\r\n<v><%=render_value \'coagulation\'%></v>\r\n</div>\r\n<% end%>\r\n<% if record[\'cns\']!=\"\" %>\r\n<div id=\"cns\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left\">\r\n<span class=\"\"><label>CGS : </label></span>	\r\n<v><%=render_value \'cns\'%></v>\r\n</div>\r\n<% end%>\r\n<% if record[\'liver\']!=\"\" %>\r\n<div id=\"liver\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left\">\r\n<span class=\"\"><label>total bilirubin (mg/dl) : </label></span>	\r\n<v><%=render_value \'liver\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<div class=\'clear\'></div>\r\n<% if record[\'renal\']!=\"\" %>\r\n<div id=\"renal\" class=\"  portlet \" style=\"width:600px;margin: 0 0.5em 0.5em 0;float:left\">\r\n<span class=\"\"><label>Cr(mg/dl) or urine output : </label></span>	\r\n<v><%=render_value \'renal\'%></v>\r\n</div>\r\n<% end%>\r\n<div class=\'clear\'></div>\r\n<% if record[\'cvs\']!=\"\" %>\r\n<div id=\"cvs\" class=\"  portlet \" style=\"width:600px;margin: 0 0.5em 0.5em 0;float:left\">\r\n<span class=\"\"><label>Hypotension : </label></span>	\r\n<v><%=render_value \'cvs\'%></v>\r\n</div>\r\n<% end%>\r\n<div class=\'clear\'></div>\r\n\r\n<% if record[\'diuretic\']!=\"\" %>\r\n<div id=\"diuretic\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left\">\r\n<span class=\"\"><label>Diuretic : </label></span>	\r\n<v><%=render_value \'diuretic\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n<% if record[\'lactate\']!=nil %>\r\n<div id=\"lactate\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left\">\r\n<span class=\"\"><label>Lactate : </label></span>	\r\n<v><%=render_value \'lactate\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<% if record[\'sofa\']!=nil %>\r\n<div id=\"sofa\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left\">\r\n<span class=\"\"><label>SOFA : </label></span>	\r\n<v><%=render_value \'sofa\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<% end # zam %>\r\n	\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n	\r\n\r\n<% if record[\'if_rrt\']!=\"\" %>\r\n<div id=\"if_rrt\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n<span class=\"\"><label>IF RRT : </label></span>	\r\n<v><%=render_value \'if_rrt\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n	\r\n\r\n<% if record[\'indication\']!=\"\" %>\r\n	<div id=\"283-F5560483698\" class=\" rrt\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>RRT</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n<div id=\"indication\" class=\" rrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;\">\r\n<span class=\"\"><label>Indication : </label></span>	\r\n<v><%=render_value \'indication\'%></v></div>\r\n<% end%>\r\n\r\n	\r\n<% if record[\'mode_of_rrt\']!=\"\" %>\r\n<div id=\"mode_of_rrt\" class=\" rrt portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:220px;\">\r\n<span class=\"\"><label>Mode of RRT : </label></span>	\r\n<v><%=render_value \'mode_of_rrt\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n<%\r\nif zam\r\n    r_rrt = record[\'if_rrt\']\r\n    if r_rrt == \'0\'\r\n        doc = get_document(this.document_name)\r\n        fields = doc.fields\r\n        mf = {}\r\n        fields.collect do |i| \r\n            mf[i.column_name] = i.label\r\n            # [i.column_name,i.name] unless Document.visual_types.index(i.field_type)\r\n            i\r\n        end\r\n        \r\n        m_rrt = record[\'mode_of_rrt\'] \r\n        ff = {}\r\n        # IHD fields\r\n        ff[\'0\'] = %w{type_of_vascular_access site_of_vascular_access internal_jugular_lr bfr dfr dialyzer anticoagulant_ihd complication_ihd}\r\n        # SLED fields\r\n        ff[\'3\'] = %w{type_of_vascular_access_sled site_of_vascular_access_sled internal_jugular_lr_sled duration_sled bfr_sled dfr_sled dialyzer_sled anticoagulant_sled complication_sled}\r\n        # CRRT fields\r\n        ff[\'1\'] = %w{type_of_vascular_access_crrt site_of_vascular_access_crrt internal_jugular_lr_crrt}\r\n        # Prescribed fields\r\n        fcp = %w{crrt_bfr crrt_ufr rfr_crrt dfr_crrt}\r\n        # Delivered fields\r\n        fcd = %w{effrent_fluid total_time_crrt delivered_lose machine_type mode anticoagulant_crrt crrt_complication}\r\n        # PD fields\r\n        ff[\'2\'] = %w{type_of_catheter type_solution cycle fill_volume dwell_time pd_complication}\r\n        \r\n        sec = {\'0\'=>\'IHD (4hr.)\'.html_safe, \'1\'=>\'CRRT\'.html_safe, \'2\'=>\'PD\', \'3\'=>\'SLED (8hr.)\'.html_safe}\r\n        \r\n        fx = ff[m_rrt.to_s]\r\n        if !m_rrt.nil? and m_rrt != \'\'\r\n%>\r\n    <div style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b><%= sec[m_rrt] %></b>\r\n	</div>\r\n<% fx.each do |i| %>\r\n<% if record[i]!=\"\" %>\r\n<div id=\"<%= i %>\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left\">\r\n<span class=\"\"><label><%= mf[i] %> : </label></span>	\r\n<v><%=render_value i.to_s%></v>\r\n</div>\r\n<% \r\n    end # fx.each\r\nend\r\n%>\r\n\r\n<% if m_rrt==\'1\' %>\r\n    <div style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Prescribed</b>\r\n	</div>\r\n    <% fcp.each do |i| %>\r\n    <% if record[i]!=\"\" %>\r\n    <div id=\"<%= i %>\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left\">\r\n    <span class=\"\"><label><%= mf[i] %> : </label></span>	\r\n    <v><%=render_value i.to_s%></v>\r\n    </div>\r\n    <% \r\n        end\r\n    end\r\n    %>\r\n    \r\n    <div style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Delivered</b>\r\n	</div>\r\n    <% fcd.each do |i| %>\r\n    <% if record[i]!=\"\" %>\r\n    <div id=\"<%= i %>\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left\">\r\n    <span class=\"\"><label><%= mf[i] %> : </label></span>	\r\n    <v><%=render_value i.to_s%></v>\r\n    </div>\r\n    <% \r\n        end\r\n    end\r\n    %>\r\n<% end %>\r\n\r\n<%     \r\n        end\r\n    end\r\nend \r\n%>\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2016-01-23 08:53:40','2016-01-23 08:53:40','print',''),(2052,'get_type',821,3,'<%\r\n    tid = params[:tid].strip\r\n    \r\n    tmp = get_model[this.table_name.to_sym].find(tid)\r\n    res = {}\r\n    if tmp\r\n        res[:result] = tmp[:type_id]\r\n    else\r\n        res[:result] = \'0\'\r\n    end\r\n        \r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2016-01-24 03:51:40','2016-01-24 03:51:40','get_type',''),(2053,'json',820,3,'<%\r\n    id = params[:id].strip\r\n    \r\n    tmp = get_model[this.table_name.to_sym].find(id)\r\n    res = {}\r\n    if tmp\r\n        res[:result] = tmp[:company_id]\r\n    else\r\n        res[:result] = \'0\'\r\n    end\r\n        \r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2016-01-24 04:03:44','2016-01-24 04:03:44','json',''),(2054,'json',822,3,'<%\r\n    id = params[:id].strip\r\n    \r\n    tmp = get_model[this.table_name.to_sym].find(id)\r\n    res = {}\r\n    if tmp\r\n        res[:result] = tmp[:material_id]\r\n    else\r\n        res[:result] = \'0\'\r\n    end\r\n        \r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2016-01-24 04:04:04','2016-01-24 04:04:04','json',''),(2055,'form',872,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n    function bmi() {\r\n        w = parseInt($(\'#data-weight\').val());\r\n        h = parseInt($(\'#data-height\').val()) * 0.01;\r\n        bmi = \'N/A\';\r\n        if (h != 0 || !isNaN(h)) {\r\n            bmi = w / (h*h);\r\n            $(\'#data-bmi\').val(bmi.toFixed(2));\r\n        } else {\r\n            $(\'#data-bmi\').val(\'N/A\');\r\n        }\r\n        \r\n        console.log(\'w:\' + w + \', h:\' + h + \', BMI:\' + bmi);\r\n    }\r\n    function hide_underlying() {\r\n        ff = [\"respiratory\",\"respiratory_other\",\"cvs\",\"cvs_other\",\"renal\",\"renal_other\",\"endocrine\",\"endocrine_other\",\"hematology\",\"hematology_other\",\"neuro\",\"neuro_other\",\"metabolic\",\"metabolic_other\",\"infection\",\"infection_other\",\"hepatobiliary\",\"hepatobiliary_other\",\"gastro_intestinal\",\"gastro_intestinal_other\",\"musculoskeletal\",\"musculoskeletal_other\",\"psychiatric_problem\",\"psychiatric_problem_other\",\"disease_other\",\"previous_anesthesia_yes\",\"complications\"]\r\n        for (i in ff) {\r\n            fid = \'#\' + ff[i];\r\n            $(fid).hide();\r\n            // console.log(\'hide-\' + fid);\r\n        }\r\n    }\r\n    function update_recorder_name_1() {\r\n        code = $(this).val();\r\n        $.getJSON( \"../Apiz/get_provider_by_ref_number?code=\"+code, function( data ) {\r\n          $(\'#data-recorder_name_1\').val(data.id);\r\n          $(\'#data-recorder_name_1\').effect(\"highlight\", {}, 2000);\r\n        });\r\n    }\r\n    function update_recorder_name_2() {\r\n        code = $(this).val();\r\n        $.getJSON( \"../Apiz/get_provider_by_ref_number?code=\"+code, function( data ) {\r\n          $(\'#data-recorder_name_2\').val(data.id);\r\n          $(\'#data-recorder_name_2\').effect(\"highlight\", {}, 2000);\r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n        x = $(\'#data-underlying_disease_none\').val();\r\n        if (x == \'0\') {\r\n            hide_underlying();\r\n        }\r\n        \r\n        // BMI Calculation\r\n        $(\'#data-weight\').change(bmi);\r\n        $(\'#data-height\').change(bmi);\r\n        \r\n<%\r\n    prov = get_model[:provider].all\r\n    code = []\r\n    prov.each do |i|\r\n        if i[:ref_number]\r\n            code << i[:ref_number]\r\n        end\r\n        # if i[:license_number]\r\n        #     code << i[:license_number]\r\n        # end\r\n    end\r\n    \r\n%>\r\n        // console.log(\'all prov : <%= code.count %>\');\r\n        var prov = <%= code.to_s.html_safe %>;\r\n        $(\'#data-recorder_code_1\').kendoAutoComplete({\r\n            dataSource: prov,\r\n            placeholder: \"Enter code ...\"\r\n        });\r\n        $(\'#data-recorder_code_2\').kendoAutoComplete({\r\n            dataSource: prov,\r\n            placeholder: \"Enter code ...\"\r\n        });\r\n        $(\'#data-recorder_code_1\').change(update_recorder_name_1);\r\n        $(\'#data-recorder_code_2\').change(update_recorder_name_2);\r\n        $(\'#data-recorder_name_2\').attr(\"readonly\", true);\r\n        \r\n<%\r\n    cur_user = @current_user\r\n    cur_prov = get_model[:provider].where(:login=>cur_user[:login]).first\r\n    if !cur_prov.nil?\r\n%>\r\n        $(\'#data-recorder_name_1\').val(\'<%= cur_prov.id.to_s %>\');\r\n<%\r\n    end\r\n%>\r\n    })\r\n</script>\r\n',NULL,NULL,NULL,'2016-01-24 05:28:28','2016-01-24 05:28:28','form',''),(2056,'index_old',878,2,'<%\r\ntb = Time.now\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Appointment</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    \r\n    # finding pre-op, post-op module\r\n    app_ids = aps.collect{|i| i.id}\r\n    m_app = module_model.where(:module_id=>app_ids)\r\n    h_app_mod = {} # app_id <-> module\r\n    m_app_ids = []\r\n    par_ids = []\r\n    m_app.each do |i|\r\n        h_app_mod[i[:module_id]] = i\r\n        m_app_ids << i[:module_id]\r\n        par_ids << i.id\r\n    end\r\n    \r\n    m_pre_name = \"\\\\#{@current_project.name}#pre_op\"\r\n    m_pos_name = \"\\\\#{@current_project.name}#post_op\"\r\n    m_pac_name = \"\\\\#{@current_project.name}#pacu\"\r\n    m_pre = module_model.where(:parent_id=>par_ids, :module_name=>m_pre_name)\r\n    m_pos = module_model.where(:parent_id=>par_ids, :module_name=>m_pos_name)\r\n    m_pac = module_model.where(:parent_id=>par_ids, :module_name=>m_pac_name)\r\n    \r\n    h_pre = {}\r\n    h_pos = {}\r\n    h_pac = {}\r\n    \r\n    m_pre.each do |i|\r\n        h_pre[i[:parent_id]] = i.id\r\n    end\r\n    m_pac.each do |i|\r\n        h_pac[i[:parent_id]] = i.id\r\n    end\r\n    m_pos.each do |i|\r\n        h_pos[i[:parent_id]] = i.id\r\n    end\r\n%>\r\n<%# aps.inspect %>\r\n<!--<%= h_pre.to_json.html_safe %>-->\r\n<%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    #   if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n        if m = h_app_mod[i.id]\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n         \r\n         c_pre = link_to(\'+Pre Op\', \"../PreOp/create?patient_id=\\\\#{patient.id}&record_name=000001&parent_id=\\\\#{m.id}&return=../Home/patient_record?id=\\\\#{i.id}\", :class=>\'btn btn-small\');\r\n         c_pos = link_to(\'+Post Op\', \"../PostOp/create?patient_id=\\\\#{patient.id}&record_name=000001&parent_id=\\\\#{m.id}&return=../Home/patient_record?id=\\\\#{i.id}\", :class=>\'btn btn-small\');\r\n         c_pac = link_to(\'+PACU\', \"../Pacu/create?patient_id=\\\\#{patient.id}&record_name=000001&parent_id=\\\\#{m.id}&return=../Home/patient_record?id=\\\\#{i.id}\", :class=>\'btn btn-small\');\r\n         \r\n         v_pre = link_to(\'Pre Op\', \"../PreOp/show?id=\\\\#{h_pre[m.id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\');\r\n         v_pos = link_to(\'Post Op\', \"../PostOp/show?id=\\\\#{h_pos[m.id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\');\r\n         v_pac = link_to(\'PACU\', \"../Pacu/show?id=\\\\#{h_pac[m.id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\');\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        # zam\r\n        #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :pending_ctrl=>link_to(\'Confirmed\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n            c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         elsif i.status == \'Processing\' or i.status == \'Completed\'\r\n            c[:processing_ctrl] = \"\"\r\n            if h_pre[m.id]\r\n                c[:processing_ctrl] += v_pre\r\n            else\r\n                c[:processing_ctrl] += c_pre\r\n            end\r\n            if h_pac[m.id]\r\n                c[:processing_ctrl] += v_pac\r\n            else\r\n                c[:processing_ctrl] += c_pac\r\n            end\r\n            if h_pos[m.id]\r\n                c[:processing_ctrl] += v_pos\r\n            else\r\n                c[:processing_ctrl] += c_pos\r\n            end\r\n            c[:processing_ctrl] += link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info\')\r\n            # c[:processing_ctrl] = c[:processing_ctrl]\r\n         else\r\n            status = \'btn-info\'\r\n            status = \'\' if i.status ==\'Completed\'\r\n            c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n<% if @current_role == \'developer\' %>\r\nProcessing time : <%= Time.now - tb %>\r\n<% end %>\r\n </div><br/>',NULL,NULL,NULL,'2016-01-24 16:33:00','2016-01-24 16:33:00','index_old',''),(2057,'document_name',879,1,'\'demo\'',NULL,NULL,NULL,'2016-01-25 02:36:50','2016-01-25 02:36:50',NULL,NULL),(2060,'document_name',880,1,'\'opd_first_visit\'',NULL,NULL,NULL,'2016-01-27 09:34:31','2016-01-27 09:34:31',NULL,NULL),(2061,'form',879,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<link rel=\"stylesheet\" href=\"/gebo/lib/jquery-ui/css/Aristo/Aristo.css\">\r\n<style>\r\n        .demo-section {\r\n            text-align: center;\r\n        }\r\n\r\n        #equalizer {\r\n            padding-right: 15px;\r\n        }\r\n\r\n        div.balSlider {\r\n            width: 100%;\r\n        }\r\n\r\n        div.balSlider .k-slider-selection {\r\n            display: none;\r\n        }\r\n\r\n        div.eqSlider {\r\n            display: inline-block;\r\n            margin: 1em;\r\n            height: 122px;\r\n            vertical-align: top;\r\n        }\r\n    </style>\r\n<script>\r\n    //* sliders\r\n	gebo_sliders = {\r\n		init: function(){\r\n			//* default slider\r\n			$( \".ui_slider1\" ).slider({\r\n				value:<%= @record[:pain_slider] %>,\r\n				min: 0,\r\n				max: 10,\r\n				step: 0.2,\r\n				slide: function( event, ui ) {\r\n				// 	$( \".ui_slider1_val\" ).text( \"$\" + ui.value );\r\n					$( \"#data-pain_slider\" ).val( ui.value );\r\n				}\r\n			});\r\n// 			$( \".ui_slider1_val\" ).text( \"$\" + $( \".ui_slider1\" ).slider( \"value\" ) );\r\n			$( \"#data-pain_slider\" ).val( $( \".ui_slider1\" ).slider( \"value\" ) );\r\n\r\n		}\r\n	};\r\n	$(document).ready(function() {\r\n            var slider = $(\"#data-pain_kendo\").kendoSlider({\r\n                increaseButtonTitle: \"Right\",\r\n                decreaseButtonTitle: \"Left\",\r\n                min: 0,\r\n                max: 10,\r\n                smallStep: 0.1,\r\n                largeStep: 1\r\n            }).data(\"kendoSlider\");\r\n	});\r\n	$(document).ready(function() {\r\n		//* jQuery UI sliders\r\n		gebo_sliders.init();\r\n	});\r\n</script>\r\n\r\n\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n',NULL,NULL,NULL,'2016-02-01 04:52:48','2016-02-01 04:52:48','',''),(2062,'print_weekly',146,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Untitled Document</title>\r\n<style>\r\n    table, th, td {\r\n   border: 1pt solid black;\r\n   border-collapse: collapse; \r\n    font-size:12x;\r\n}\r\n    \r\n</style>\r\n<style type=\"text/css\" media=\"print\">\r\n@media print{@page {size: landscape}}\r\n    .page\r\n    {\r\n        \r\n     -webkit-transform: rotate(-90deg); \r\n     -moz-transform:rotate(-90deg);\r\n     filter:progid:DXImageTransform.Microsoft.BasicImage(rotation=3);\r\n	\r\n    }\r\n    body {margin-top: 3px;padding-top: 3px;}\r\n</style>\r\n</head>\r\n\r\n<body style=\"margin-top: 3px;padding-top: 3px;\">\r\n\r\n<div id=\"page\" style=\"font-size:12px\">\r\n<span style=\"position:fixed;\">แบบ ย.ส.6</span>\r\n<center>รายงานประจำเดือน <% %>\r\n\r\n\r\n<br />\r\nชื่อผู้รับใบอนุญาต\r\n<% %>\r\nสถานที่ชื่อ \r\n<% %>\r\n<br />\r\nอยู่เลขที่ \r\n<% %>\r\n<br /></center>\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" style=\"font-size:12px;\">\r\n  <tr>\r\n    <td rowspan=\"2\" align=\"center\">วัน เดือน ปี</td>\r\n    <td rowspan=\"2\" align=\"center\">ชื่อยาเสพติดให้โทษในประเภทที่ 2 </td>\r\n    <td rowspan=\"2\" align=\"center\">รหัส</td>\r\n    <td rowspan=\"2\" align=\"center\">ได้มาจาก<br />\r\n      กระทรวงสาธารณะสุข</td>\r\n    <td rowspan=\"2\" align=\"center\">จ่ายไป</td>\r\n    <td colspan=\"3\" align=\"center\">(ปริมาณ กรัม หรือ ช.ม.)</td>\r\n    <td rowspan=\"2\" align=\"center\">หมายเหตุ</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"center\">รับ</td>\r\n    <td align=\"center\">จ่าย</td>\r\n    <td align=\"center\">คงเหลือ</td>\r\n    </tr>\r\n  <tr>\r\n    <td align=\"center\">1 / 1 / 59</td>\r\n    <td>&nbsp;Fentany 0.1 mg</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;นาย กฤษฎา วงษ์จินเพื่อง</td>\r\n    <td align=\"center\" width=\"100\">&nbsp;</td>\r\n    <td align=\"center\" width=\"100\">1 Amps.</td>\r\n    <td align=\"center\" width=\"100\">&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n</table>\r\n<br />\r\nหมายเหตุ ให้ขีดฆ่าข้อความที่ไม่ต้องการออก คำอธิบาย 1.ช่องรหัส ให้ดูรหัสจากฉลากติดกับภาชนะบรรจุ 2.ช่องจ่ายไป ให้ระบุชื่อคนไข้ เพศ อายุ อาชีพ และที่อยู่ให้ชัดเจน 3.รายงานนี้ให้ส่งถึงเลขาธิการคณะกรรมการอาหารและยา ภายใน สามสินวันนับแต่วันสิ้นเดือน 4.แบบฟอร์มนี้ขอให้ที่กองคอบคุมวัตถุเสพติด สำนักงานคณะกรรมการอาหารและยา กระทรวงสาธารณสุข<br />\r\n<span style=\"float:right\">(ลายมือชื่อ).................................................(ผู้รับอนุมัติ)</span></div>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-02-01 12:00:20','2016-02-01 12:00:20','print_weekly',''),(2064,'initx',573,4,'<%\r\n    def get_map(arr)\r\n        rs = {}\r\n        arr.each do |i|\r\n            rs[i.id.to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @m_ehr = ehr.load_model\r\n    @m_pat = @m_ehr[:patient]\r\n    @m_pat_mod = @m_ehr[:patient_module]\r\n\r\n    @models = get_model\r\n    \r\n    def get_appointment_by_date(sdate = Time.now.strftime(\'%d/%m/%Y\'), edate = Time.now.strftime(\'%d/%m/%Y\'))\r\n        sdate = Time.strptime(sdate, \"%d/%m/%Y\")\r\n        edate = Time.strptime(edate, \"%d/%m/%Y\")\r\n        cond = {}\r\n        cond[:date] = {\'$gte\'=>sdate.beginning_of_day,\'$lt\'=>edate.end_of_day}\r\n        rs = @models[:appointment].where(cond).all\r\n        return rs\r\n    end\r\n    \r\n    def get_all_appointment()\r\n        return @models[:appointment].all\r\n    end\r\n    \r\n    def get_all_appointment_by_ids(ids=[])\r\n        return @models[:appointment].find(ids)\r\n    end\r\n    \r\n    def get_all_patient_by_ids(ids=[])\r\n        return @m_pat.find(ids)\r\n    end\r\n    \r\n    def get_patient_module_by_module_name(mod_name=\'\')\r\n        return @m_pat_mod.where(:module_name=>mod_name).all\r\n    end\r\n    \r\n    def get_patient_module_by_appointment_ids(app_ids = [])\r\n        return @m_pat_mod.where(:module_id=>app_ids).all\r\n    end\r\n    \r\n    def get_patient_module_document_by_patient_module_appointment(par_ids = [], mod_name = \'\')\r\n        return @m_pat_mod.where(:parent_id=>par_ids, :module_name=>mod_name).all\r\n    end\r\n    \r\n    def get_patient_module_by_document_ids(mod_name, mod_ids)\r\n        return @m_pat_mod.where(:module_name=>mod_name, :module_id=>mod_ids).all\r\n    end\r\n    \r\n    def get_module_id_array(patient_module_array = [])\r\n        return patient_module_array.collect{|i| i[:module_id].to_s}\r\n    end\r\n    \r\n    def get_module_id_map(pat_mod_arr = [])\r\n        rs = {}\r\n        pat_mod_arr.each do |i|\r\n            rs[i[:module_id].to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n    \r\n%>',NULL,NULL,NULL,'2016-02-01 14:36:41','2016-02-01 14:36:41','initx',''),(2065,'exportx',573,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    \r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = []\r\n    pat_ids = []\r\n    app_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n    end\r\n    \r\n    mod_doc = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#\\\\#{this.document_name}\")\r\n    mod_par = {}\r\n    mod_ids = []\r\n    mod_doc.collect do |i|\r\n        mod_ids << i[:module_id]\r\n        par = i[:parent_id]\r\n        if !mod_par.has_key? par\r\n            mod_par[par] = []\r\n        end\r\n        mod_par[i[:parent_id]] << i[:module_id]\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    a_pat = a_pat.sort_by{|i| i[:patient_order]}\r\n    \r\n    @document = get_document(this.document_name)\r\n    doc = @document\r\n    data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n  \r\n    fields = @document.fields\r\n    fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n    \r\n    rs[:all_patient] = a_pat.count\r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    rs[:app_par] = app_par\r\n    rs[:mod_par] = mod_par\r\n%>\r\n<%= rs.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2016-02-01 14:37:19','2016-02-01 14:37:19','exportx',''),(2067,'link',481,3,'<h3>Patient</h3>\r\n<%\r\n    1.upto(23) do |i|\r\n%>\r\n<%= link_to \"rrts_\\\\#{i}\", \"../../../rrts_\\\\#{i}/www/Patient/export\", :target=>\'_blank\' %><br/>\r\n<% end %>\r\n<hr/>\r\n<h3>Summary Form</h3>\r\n<%\r\n    1.upto(23) do |i|\r\n%>\r\n<%= link_to \"rrts_\\\\#{i}\", \"../../../rrts_\\\\#{i}/rrts/SummaryForm/export\", :target=>\'_blank\' %><br/>\r\n<% end %>\r\n<hr/>\r\n<h3>Case Record</h3>\r\n<%\r\n    1.upto(23) do |i|\r\n%>\r\n<%= link_to \"rrts_\\\\#{i}\", \"../../../rrts_\\\\#{i}/rrts/CaseRecord/export_zam\", :target=>\'_blank\' %><br/>\r\n<% end %>\r\n<hr/>',NULL,NULL,NULL,'2016-02-02 15:47:42','2016-02-02 15:47:42','link',''),(2068,'form',880,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<style>\r\n        .demo-section {\r\n            text-align: center;\r\n        }\r\n\r\n        #equalizer {\r\n            padding-right: 15px;\r\n        }\r\n\r\n        div.balSlider {\r\n            width: 100%;\r\n        }\r\n\r\n        div.balSlider .k-slider-selection {\r\n            display: none;\r\n        }\r\n\r\n        div.eqSlider {\r\n            display: inline-block;\r\n            margin: 1em;\r\n            height: 122px;\r\n            vertical-align: top;\r\n        }\r\n</style>\r\n<script>\r\n    var tf_slider = [\'kun_slider\',\'jam_slider\',\'kunna_slider\',\'mok_slider\',\'pod_slider\',\'kun_ta_slider\',\'ktm\'];\r\n    $(document).ready(function() {\r\n        for (var i in tf_slider) {\r\n            var slider = $(\"#data-\" + tf_slider[i]).kendoSlider({\r\n                increaseButtonTitle: \"Right\",\r\n                decreaseButtonTitle: \"Left\",\r\n                min: 0,\r\n                max: 10,\r\n                smallStep: 0.01,\r\n                largeStep: 1\r\n            }).data(\"kendoSlider\");\r\n        }\r\n	});\r\n</script>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n',NULL,NULL,NULL,'2016-02-03 04:42:35','2016-02-03 04:42:35','form',''),(2069,'document_name',881,1,'\'pacu_record\'',NULL,NULL,NULL,'2016-02-03 06:05:27','2016-02-03 06:05:27',NULL,NULL),(2070,'document_name',882,1,'\'pacu\'',NULL,NULL,NULL,'2016-02-03 06:06:06','2016-02-03 06:06:06',NULL,NULL),(2071,'document_name',883,1,'\'document\'',NULL,NULL,NULL,'2016-02-03 06:06:37','2016-02-03 06:06:37',NULL,NULL),(2072,'print_report',866,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  attachment_model = @models[:attachment]\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n# @document = @model[:colono].get_document\r\ndx_stat = {} \r\ndg_stat = {}\r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n \r\n \r\n\r\n\r\n \r\n ml =  @module_model.where(:parent_id=>i.id).all\r\n \r\n diagnosis = \'\'\r\n diagnosis_group = \'\'\r\n provider = providers[ap.provider.to_s]\r\n provider_name = provider.name if provider\r\n attachments = []\r\n#  provider_name = ml.size.to_s\r\n \r\n for x in ml\r\n    if x.module_name==\"\\#{@current_project.name}#colono\"\r\n        \r\n        colo = @models[:colono].find(x.module_id)\r\n  \r\n        if colo\r\n            provider_name = colo.id.to_s\r\n            \r\n            provider = providers[colo.endoscopist.to_s]\r\n            provider_name = provider.name if provider\r\n            diagnosis = colo.diagnosis_text\r\n            attachments = colo.image\r\n            \r\n            # diagnosis_group\r\n            # 0 - Normal\r\n            # 1 - Polyp\r\n            # 2 - Diverticulum\r\n            # \r\n            diagnosis_group = colo.diagnosis_group\r\n            a_dx = diagnosis_group.split(\'|\')\r\n            tmp = {}\r\n            a_dx.each do |i|\r\n                if !dx_stat.has_key? i\r\n                    dx_stat[i] = 0\r\n                end\r\n                \r\n                if !tmp.has_key? i\r\n                    tmp[i] = 0\r\n                    dx_stat[i] += 1\r\n                end\r\n            end\r\n            dx_group = tmp.keys.join(\'|\')\r\n            if !dg_stat.has_key? dx_group\r\n                dg_stat[dx_group] = 0\r\n            end\r\n            dg_stat[dx_group] += 1\r\n        end\r\n    end\r\n end\r\n \r\n \r\n\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\#{year} ปี\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>ml.collect{|i| i.module_name.split(\'#\')[-1].humanize}.join(\',\'),\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider_name,\r\n    \'title\'=>\"\\#{p.prefix_name if p } \\#{p.first_name if p } \\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'attachments\'=>attachments,\r\n    \'age\'=>age,\r\n    \'ml\'=>ml,\r\n    \'diagnosis\'=>diagnosis.html_safe,\r\n    \'diagnosis_group\'=>diagnosis_group.html_safe,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\n\r\n\r\nlist = json_data.sort{|a,b| b[\'diagnosis_group\']<=>a[\'diagnosis_group\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Summary Report</title>\r\n<%# javascript_include_tag \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' height=\"60px\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงรายการผู้ป่วย\r\n<span style=\"float:right\">ประจำวันที่ \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>HN</th>\r\n    <th >อายุ</th>\r\n    <th>Procedure</th>\r\n    <th>Diagnosis</th>\r\n    <th>Provider</th>\r\n    <th>Link</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n<% \r\n    sp = {}\r\n    index = 0 \r\n    list.each_with_index do |i,ix|  \r\n        pps = i[\'procedure\'].split(\',\')\r\n        for pp in pps\r\n            if sp.has_key?(pp)\r\n                sp[pp] = sp[pp] + 1\r\n            else\r\n                sp[pp] = 1\r\n            end\r\n        end\r\n    if params[:filter]==nil or (i[\'diagnosis\']!=\'\' and i[\'diagnosis_group\']!=\'0\') \r\n\r\n    \r\n%> \r\n    <tr class=\"page-break\">\r\n    <td><%=index+1%>.</td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%></td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'age\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    <td><%=i[\'diagnosis\']%></td>\r\n    <td><%=i[\'provider\']%></td>\r\n    <td><%=link_to(\'Detail\',\"patient_record?id=\\#{i[\'id\']}\")%></td>\r\n    </tr>\r\n    \r\n  \r\n    <tr>\r\n    <td colspan=\"8\">\r\n        <%  \r\n        if true\r\n            attachments = attachment_model.find(i[\'attachments\'])[0..4]\r\n        for j in attachments\r\n        %>\r\n        <% if @current_role != \'developer\' %>\r\n        <%= image_tag j.path + \"?thumb=1\", :width=>80, :style=>\'\' %>\r\n        <% end %>\r\n        <% end %>\r\n        <% end %>\r\n    </td>    \r\n        \r\n    </tr>\r\n    \r\n    <% \r\n    \r\n    index+=1\r\n    end %>\r\n    <% end %>\r\n</tbody>\r\n<%\r\n    dx_lbn = [\'Normal\', \'Polyp\', \'Diverticulum\', \'Hemorrhoid\', \'Mass\', \'Ulcer\', \'Other\']\r\n    dx_val = Array.new(dx_lbn.count + 1).collect{|i| 0}\r\n    dx_pie = []\r\n    dx_map = {}\r\n    dx_stat.keys.each do |i|\r\n        r = {}\r\n        idx = i.to_i\r\n        k = \'Other\'\r\n        v = dx_stat[i]\r\n        if idx <= 5\r\n            k = dx_lbn[idx]\r\n            v = dx_stat[i]\r\n        end\r\n        \r\n        if !dx_map.has_key? k\r\n            dx_map[k] = 0\r\n        end\r\n        dx_map[k] += v\r\n        \r\n        # if idx > 5\r\n        #     dx_val[6] += dx_stat[i]\r\n        #     r[:category] = dx_lbn[6]\r\n        #     r[:value] = dx_val[6]\r\n        # else\r\n        #     dx_val[idx] = dx_stat[i]\r\n        #     r[:category] = dx_lbn[idx]\r\n        #     r[:value] = dx_val[idx]\r\n        # end\r\n        # dx_pie << r\r\n    end\r\n%>\r\n    <tr>\r\n        <td colspan=\"4\">\r\n            <div class=\'row-fluid\'>\r\n                <b>สรุปรายการที่พบ</b><br/>\r\n                <blockquote>\r\n                <%\r\n                    n = 0\r\n                    dx_lbn.each do |i|\r\n                %>\r\n                    <b><%= n %>. <%= i %> : </b> <%= dx_map[i] ? dx_map[i] : 0 %><br/>\r\n                <%\r\n                        n += 1\r\n                    end\r\n                %>  \r\n                </blockquote>\r\n                <%# dx_map.to_json.html_safe %>\r\n                <!--<div id=\"dx-chart\" style=\"border:0px solid;width:480%;min-height:300px\"></div>-->\r\n            </div>\r\n        </td>  \r\n        <td colspan=\"4\">\r\n            <div class=\'row-fluid\'>\r\n                <b>สรุปรายการที่พบ</b><br/>\r\n                <blockquote>\r\n                <%\r\n                    n = 1\r\n                    dg_stat.each do |i,v|\r\n                        arr = i.split(\'|\')\r\n                        txt = []\r\n                        arr.each do |a|\r\n                            idx = a.to_i\r\n                            if idx > 5\r\n                                txt << \'Other\'\r\n                            else\r\n                                txt << dx_lbn[idx]\r\n                            end\r\n                        end\r\n                %>\r\n                    <b><%= n %>. <%= txt.join(\', \') %> : </b> <%= v %><br/>\r\n                <%\r\n                        n += 1\r\n                    end\r\n                %>  \r\n                </blockquote>\r\n                <%# dx_map.to_json.html_safe %>\r\n                <!--<div id=\"dx-chart\" style=\"border:0px solid;width:480%;min-height:300px\"></div>-->\r\n            </div>\r\n        </td>  \r\n    </tr>\r\n  </table><br/>\r\n\r\n<script>\r\n<%\r\n    dx_lbn = [\'Normal\', \'Polyp\', \'Diverticulum\', \'Hemorrhoid\', \'Mass\', \'Ulcer\', \'Other\']\r\n    dx_val = Array.new(dx_lbn.count + 1).collect{|i| 0}\r\n    dx_pie = []\r\n    dx_stat.keys.each do |i|\r\n        r = {}\r\n        idx = i.to_i\r\n        if idx > 5\r\n            dx_val[6] += dx_stat[i]\r\n            r[:category] = dx_lbn[6]\r\n            r[:value] = dx_val[6]\r\n        else\r\n            dx_val[idx] = dx_stat[i]\r\n            r[:category] = dx_lbn[idx]\r\n            r[:value] = dx_val[idx]\r\n        end\r\n        dx_pie << r\r\n    end\r\n%>\r\n    function createChart() {\r\n        /*\r\n                    $(\"#dx-chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Number Diagnosis\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: [<%#dx_val.to_json.html_safe %>]\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%#dx_lbn.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    }); */\r\n                    /*\r\n        $(\"#dx-chart\").kendoChart({\r\n            title: {\r\n                text: \"Diagnosis\"\r\n            },\r\n            legend: {\r\n                position: \"left\"\r\n            },\r\n            seriesDefaults: {\r\n                labels: {\r\n                    visible: true,\r\n                    format : \"{0}\"\r\n                    // format: \"{0}%\"\r\n                }\r\n            },\r\n            series: [{\r\n                type: \"pie\",\r\n                data: <%# dx_pie.to_json.html_safe %>\r\n            }]\r\n        });*/\r\n    }\r\n    /*\r\n    $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n    });*/\r\n</script>  \r\n  \r\n  \r\n<% if false %>\r\n<br/>\r\n  <div><strong>Total procedure</strong></div><br/>\r\n<%\r\nsp.keys.each_with_index do |key, index|\r\n%>\r\n<div><%= key %> : <%= sp[key] %></div>\r\n<%\r\nend\r\nend\r\n%>\r\n  </div>\r\n  </div></div></div></div></div>\r\n  <%# dx_stat.to_json.html_safe %>\r\n</body>\r\n</html>\r\n<% end %>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-02-04 05:15:16','2016-02-04 05:15:16','print_report',''),(2073,'annual_report',522,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Annual Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    params_date = select_date\r\n    select_date = Date.to_mongo(select_date)\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nSelect : <%= f.date_select :date, :default=>select_date ,:discard_day=>true ,:discard_month=>true,:start_year => Time.now.year-5,:end_year => Time.now.year, :order=>[:month,:year]%>\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n    ipds = 0 \r\n    opds = 0 \r\n    \r\n    total_patho = 0\r\n \r\n \r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-6-15\" if params[:report]\r\n    select_date = Date.to_mongo(select_date)\r\n    start_date = select_date.beginning_of_year()\r\n    stop_date = select_date.end_of_year()\r\n    \r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    other_status = {\'Cancelled\'=>0,\'Postpone\'=>0}\r\n    ipd_opd = {}\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n         # all pm colono of those appointments\r\n    all_pm_prescope = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}pre_scope\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_prescope = bmap all_pm_prescope, \'parent_id\'\r\n    \r\n    \r\n    colo_scope = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n    cs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n    for i in colo_scope\r\n        cs[i] = 1\r\n    end\r\n\r\n    gastro_scope = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n    gs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n       \r\n    for i in gastro_scope\r\n        gs[i] = 1\r\n    end     \r\n    \r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>cs}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>gs}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n \r\n    prescope = @models[:pre_scope].collection.find({:_id=>{\'$in\'=>all_pm_prescope.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'type_of_patient\'=>1 }}).to_a\r\n    m_prescope = bmap prescope, \'_id\'\r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    for app in all_app\r\n    \r\n        other_status[app[\'status\']] = 0 unless other_status[app[\'status\']]\r\n        other_status[app[\'status\']] += 1 \r\n        \r\n        \r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                prescope = m_all_pm_prescope[pm_app[\'_id\']]\r\n                \r\n                \r\n                p_colo = nil\r\n                p_gastro = nil\r\n                \r\n                r_colo = nil\r\n                r_gastro = nil\r\n                \r\n                \r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                        status = r_colo[0][\'status\']\r\n                        p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    if r_gastro\r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                 \r\n                patho_count = 0 \r\n                \r\n                \r\n                \r\n                # if r_colo and r_colo[0]\r\n                    \r\n                #     xls = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n                #     xms = \'colonoscopy_scope\'\r\n                #     xdata = r_colo[0]\r\n            \r\n                # xls.each{|lc|\r\n                \r\n                #     if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n             \r\n                #         xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                #         for li in xll\r\n                #             patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                   \r\n                #         end\r\n                    \r\n                #     end\r\n                # }\r\n                \r\n                # end\r\n                \r\n                \r\n                # if r_gastro and r_gastro[0]\r\n                    \r\n                #     xls = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n                #     xms = \'gastroscopy_scope\'\r\n                #     xdata = r_gastro[0]\r\n                \r\n                # xls.each{|lc| \r\n                #     if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n                #         xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                #         for li in xll\r\n                #             patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                #         end\r\n                    \r\n                #     end\r\n                # }\r\n                \r\n                # end\r\n                \r\n                \r\n                # total_patho += patho_count\r\n        \r\n                \r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n            \r\n                dates[date][\'no_specimen\'] = 0 unless dates[date][\'no_specimen\']\r\n                dates[date][\'no_specimen\'] += patho_count\r\n            \r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                \r\n                \r\n                \r\n                \r\n                if prescope and prescope = prescope[0]  and prescope and colo or gastro\r\n                    \r\n                if prescope and  prescope[\'module_id\'] and m_prescope[prescope[\'module_id\']]\r\n                    \r\n                    \r\n                    \r\n                r_prescope = m_prescope[prescope[\'module_id\']][0]    \r\n                    \r\n                dates[date][\'ipd_opd\'] = {\'IPD\'=>0,\'OPD\'=>0, \'\'=>0, nil=>0} unless dates[date][\'ipd_opd\']\r\n                dates[date][\'ipd_opd\'][r_prescope[\'type_of_patient\']]+=1\r\n                \r\n                end\r\n                \r\n                end\r\n              \r\n              \r\n              \r\n                \r\n                if p_colo\r\n                dates[date][\'p_colo\'] = {} unless dates[date][\'p_colo\']\r\n                for pi in p_colo.split(\"|\")\r\n                    dates[date][\'p_colo\'][pi] = 0 unless  dates[date][\'p_colo\'][pi]\r\n                    dates[date][\'p_colo\'][pi] += 1 \r\n                end\r\n                \r\n                end\r\n                \r\n                \r\n                \r\n                if p_gastro\r\n                \r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                for pi in p_gastro.split(\"|\")\r\n                dates[date][\'p_gastro\'][pi] = 0 unless  dates[date][\'p_gastro\'][pi]\r\n                dates[date][\'p_gastro\'][pi] += 1 \r\n                end\r\n                end\r\n                \r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        end\r\n    \r\n    end\r\n\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<% \r\n\r\n    month_text = month_th[select_date.month-1]+select_date.strftime(\"-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    .date{\r\n        padding:5px;\r\n    }\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    \r\n    td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.small{\r\n        font-size:0.8em;\r\n    }\r\n    td.date{\r\n        padding:0px;\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n        td.date{\r\n        padding:0px;\r\n        \r\n        width:125px;\r\n        \r\n    }\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n    \r\n    tr.page-break{page-break-after:always;page-break-inside:avoid; page-break-after:auto}\r\n    .force-break{ display: block;page-break-before:always;}\r\n        \r\n    }\r\n    \r\n\r\n    \r\n   table { page-break-inside:auto }\r\n   tr    { page-break-inside:avoid; page-break-after:auto }\r\n    \r\n</style>\r\n<style type=\"text/css\">\r\n\r\n</style>\r\n\r\n\r\n\r\n<div style=\"width:720px\">\r\n<h3>ตารางแสดงจำนวนผู้ป่วย ห้องส่องกล้อง Surgical Endoscopy ประจำปี \r\n<%=start_date.year%></h3>\r\n</div>\r\n\r\n<br/>\r\n<table border=\"1\" class=\"content\">\r\n<%\r\n   m = nil\r\n   \r\n   \r\n       tsum = {\'Elective\'=>[0,0,0,0],\'Extratime\'=>[0,0,0,0], \'Emergency\'=>[0,0,0,0], \'Total\'=>[0,0,0,0]}\r\n%>\r\n\r\n<%\r\n     pc_map = {}\r\n     pg_map = {}\r\n     \r\n    days = stop_date.day\r\n     \r\n    dates.each_pair do |k,v|\r\n        if v[\'p_colo\']    \r\n         v[\'p_colo\'].each_pair do |p,count|\r\n            pc_map[p] = 0 unless pc_map[p]\r\n            pc_map[p] += count\r\n         end\r\n        end\r\n        \r\n        if v[\'p_gastro\'] \r\n         v[\'p_gastro\'].each_pair do |p,count|\r\n            pg_map[p] = 0 unless pg_map[p]\r\n            pg_map[p] += count\r\n         end\r\n        end\r\n     \r\n    end\r\n     \r\n     \r\n\r\n%>\r\n\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td >&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >ในเวลา</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">ER</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">นอกเวลา</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">รวม</td>\r\n    \r\n\r\n</tr>\r\n\r\n<tr style=\"\"  class=\"page-break\"><td></td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n   \r\n</tr>\r\n\r\n<%  12.times do |time| \r\n\r\n   \r\n   i = start_date.strftime(\"%Y-\")+\"%02d\"%(time+1)\r\n   \r\n#   for i in dates.keys.sor\r\n    \r\n    if d = dates[i]\r\n\r\n\r\n%>\r\n    \r\n\r\n<tr class=\"page-break\">\r\n    <td class=\"date\"  ><%=month_th[time]%> </td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Emergency Extratime} \r\n        \r\n        k = [0,0,0]\r\n        k = dates[i][j] if dates[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        \r\n        tsum[j][0] += k[0]\r\n        tsum[j][1] += k[1]\r\n        tsum[j][2] += k[2]\r\n        tsum[j][3] += s\r\n        \r\n        \r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        s = \'.\' if s == 0 \r\n        \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n    \r\n    \r\n\r\n</tr> \r\n\r\n<% else %>\r\n<tr class=\"page-break\">\r\n    <td class=\"date  \"><%=month_th[time]%></td>\r\n    <td colspan=\"<%=19%>\">\r\n        &nbsp;\r\n        \r\n    </td>\r\n</tr>\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n<tr class=\"page-break\"><td>Total</td>\r\n<%\r\n\r\n   t = [0,0,0,0]\r\n\r\n  for j in %w{Elective  Emergency Extratime} \r\n    \r\n  4.times do |i|    \r\n  t[i]+=tsum[j][i]\r\n%>\r\n<td class=\"total2\"><%=tsum[j][i]%></td>\r\n<% end %> \r\n<% end %> \r\n\r\n<td class=\"total2\"><%=t[0]%></td><td class=\"total2\"><%=t[1]%></td><td class=\"total2\"><%=t[2]%></td><td class=\"total2\"><%=t[3]%></td>\r\n\r\n   \r\n</tr>\r\n</table>\r\n<br/>\r\n<h4><u>รวมจำนวนผู้เข้ารับบริการ</u></h4>\r\n<br/><table>\r\n    <tr>\r\n        <td colspan=\"2\"></td><td>Elective</td><td>Emergency</td><td>Extratime</td>\r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Colonoscopy</th><td  align=\"right\"><%= t[0] %> ราย</td>\r\n        \r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]%> </td>\r\n        <%  end %>\r\n        \r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Gastroscopy</th><td  align=\"right\"><%= t[1] %> ราย </td>\r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][1]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Gastroscopy & Colonoscopy</th><td  align=\"right\"><%= t[2] %> ราย </td>\r\n           <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">รวม</td><td  align=\"right\"><%= t[0]+t[1]+t[2] %> ราย </td>\r\n          <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]+tsum[j][1]+tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    \r\n</table>\r\n<hr/>\r\n<h4><u>รวมจำนวนผู้ป่วยยกเลิกหรือเลื่อนนัด</u></h4>\r\n<br/>\r\n<table>\r\n    <tr>\r\n        <th>Cancelled</th> <td style=\"width:100px\" align=\"center\"><%=other_status[\'Cancelled\'] %></td>\r\n    </tr>\r\n    <tr>\r\n        <th>Postpone</th><td style=\"width:100px\" align=\"center\"><%=other_status[\'Postpone\']%></td> \r\n    </tr>\r\n    \r\n</table>\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-02-07 03:08:08','2016-02-07 03:08:08','annual_report',''),(2074,'form',882,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<input type=\"hidden\" name=\"diagnosis_note\" id=\"data-diagnosis_note\" value=\'\'>\r\n<input type=\"hidden\" name=\"pacu_record\" id=\"data-pacu_record\" value=\'\'>\r\n\r\n\r\n\r\n<script>\r\n    function update_recorder_name_1() {\r\n        code = $(this).val();\r\n        $.getJSON( \"../Apiz/get_provider_by_ref_number?code=\"+code, function( data ) {\r\n          $(\'#data-recorder_name_1\').val(data.id);\r\n          $(\'#data-recorder_name_1\').effect(\"highlight\", {}, 2000);\r\n        });\r\n    }\r\n    function update_recorder_name_2() {\r\n        code = $(this).val();\r\n        $.getJSON( \"../Apiz/get_provider_by_ref_number?code=\"+code, function( data ) {\r\n          $(\'#data-recorder_name_2\').val(data.id);\r\n          $(\'#data-recorder_name_2\').effect(\"highlight\", {}, 2000);\r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n<%\r\n    prov = get_model[:provider].all\r\n    code = []\r\n    prov.each do |i|\r\n        if i[:ref_number]\r\n            code << i[:ref_number]\r\n        end\r\n        # if i[:license_number]\r\n        #     code << i[:license_number]\r\n        # end\r\n    end\r\n    \r\n%>\r\n        var prov = <%= code.to_s.html_safe %>;\r\n        $(\'#data-recorder_code_1\').kendoAutoComplete({\r\n            dataSource: prov,\r\n            placeholder: \"Enter code ...\"\r\n        });\r\n        $(\'#data-recorder_code_2\').kendoAutoComplete({\r\n            dataSource: prov,\r\n            placeholder: \"Enter code ...\"\r\n        });\r\n        $(\'#data-recorder_code_1\').change(update_recorder_name_1);\r\n        $(\'#data-recorder_code_2\').change(update_recorder_name_2);\r\n        $(\'#data-recorder_name_2\').attr(\"readonly\", true);\r\n    })\r\n</script>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-02-07 07:38:26','2016-02-07 07:38:26','form',''),(2075,'case_reports',789,2,'\r\n<h1>Case Report Summary </h1>\r\n<%\r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n	tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n \r\n\r\n\r\n	def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    @m_patient= model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    type = \'All\'\r\n    type = params[:report][:type] if params[:report]\r\n    \r\n    procedure = \'all\'\r\n    procedure = params[:report][:procedure] if params[:report]\r\n    \r\n    procedures = %w{all gastro colono push_enteroscopy sigmoid ercp eus dbe liver_biopsy}\r\n    cmap = {}\r\n    for i in procedures\r\n        cmap[i] = i.humanize\r\n    end\r\n    \r\n%>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    v{\r\n        color:blue;\r\n    }\r\n</style>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date  , :order=>[:day,:month,:year]%>\r\n\r\n<br/>\r\n\r\n\r\nSchedule : <%=f.select :type, options_for_select(%w{all elective special_clinic emergency}.collect{|i| i.humanize }, type) %>\r\n\r\nProcedure : <%=f.select :procedure, options_for_select(procedures.collect{|i| [i.humanize,i] }, procedure) %>\r\n\r\n\r\n\r\n\r\n<br/>\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n  <%#params.inspect %>\r\n\r\n\r\n<% \r\n\r\n	findings_id = []\r\n    \r\n\r\n\r\n\r\n	if request.post? \r\n  \r\n  \r\n		# select appointment by date\r\n  \r\n		all_app = @models[:appointment].collection.find({:date=>{\'$gte\'=>from_date,\'$lt\'=>to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n  \r\n  \r\n  \r\n		# select pm by module_id of appointment\r\n  \r\n		all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n		\r\n		m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n  \r\n		# select patients by patient_id of pm \r\n		all_patients = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'hn\'=>1}}).to_a\r\n		m_patients = bmap all_patients\r\n  \r\n  \r\n  \r\n		map = {}\r\n  \r\n  \r\n		# for each forms prepare list of module_id \r\n		all_pm = @m_patient_module.collection.find({:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n		m_all_pm = bmap all_pm, \'module_id\'\r\n  \r\n		for i in all_pm\r\n  \r\n			m = i[\'module_name\'].split(\'#\')[-1]\r\n  \r\n			if procedure==\'all\'\r\n  \r\n				map[m] = [] unless map[m]\r\n				map[m] << i[\'module_id\']\r\n  \r\n			else\r\n  \r\n				if m == procedure\r\n  \r\n					map[m] = [] unless map[m]\r\n					map[m] << i[\'module_id\']\r\n  \r\n				end\r\n  \r\n      \r\n			end\r\n  \r\n		end\r\n  \r\n  \r\n		# for each form\'s records \r\n		case_map = {}\r\n		provider_map = {}\r\n  \r\n    for k in map.keys\r\n    \r\n		rs = map[k]\r\n		case_map[k] = [] unless case_map[k]\r\n		if @models[k.to_sym]\r\n    \r\n			conds = {:_id=>{\'$in\'=>rs}}\r\n    \r\n			# 0|Elective\r\n			# 1|Emergency\r\n			# 2|Special clinic\r\n			# 3|Live demo\r\n    \r\n    \r\n			if type !=\'All\'\r\n    \r\n				ctype = \'\'\r\n				case type\r\n					when \'Elective\'\r\n						ctype = \'0\'\r\n					when \'Emergency\'\r\n						ctype = \'1\'\r\n					when \'Special clinic\'\r\n						ctype = \'2\'\r\n				end\r\n        \r\n				conds.merge! :schedule=> ctype\r\n       \r\n			end\r\n			\r\n        \r\n			records = @models[k.to_sym].collection.find(conds, {:fields=>{\'findings\'=>1,\'_id\'=>1,\'schedule\'=>1,\'endoscopist\'=>1,\'created_at\'=>1,\'diagnosis_text\'=>1,\'diagnosis_group\'=>1,\'intervention_text\'=>1,\'procedure\'=>1,\'intervention\'=>1,\'intervention_group\'=>1,\'intervention_summary\'=>1}}).to_a\r\n\r\n   \r\n		\r\n			for i in records\r\n				provider_map[i[\'endoscopist\']] = true \r\n        \r\n				findings_id += i[\'findings\'] if i[\'findings\']\r\n        \r\n				if true\r\n					case_map[k] << i \r\n				end\r\n        \r\n			end\r\n\r\n		end\r\n  \r\n	end\r\n  \r\n  \r\n  \r\n	providers = @models[:provider].collection.find({:_id=>{\'$in\'=>provider_map.keys}})\r\n	m_providers = bmap providers\r\n  \r\n  \r\n  #  collect error\r\n  \r\n	findings = @models[:finding].collection.find({:_id=>{\'$in\'=>findings_id.collect{|x| BSON::ObjectId(x)}}}).to_a\r\n	\r\n	findings_map = bmap findings\r\n  \r\n  \r\n  \r\n	intervention_ids = findings.collect{|x| x[\'intervention\'] }\r\n  \r\n  \r\n  \r\n	interventions = @models[:intervention].collection.find({:_id=>{\'$in\'=>intervention_ids},:intervention_tag=>{\'$ne\'=>\"\"}},{:fields=>{\'intervention_tag\'=>1,\'op_clipping_type\'=>1}}).to_a\r\n  \r\n	interventions_map = bmap interventions\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  if records\r\n  \r\n		for i in records\r\n  \r\n			if i[\'findings\']\r\n            \r\n            \r\n			fs = i[\'findings\'].collect{|x| findings_map[BSON::ObjectId(x)][0] }\r\n			\r\n			fs = fs.collect{|x| {:f=>x,:i=>interventions_map[x[\'intervention\']]} } \r\n            inv = []\r\n            inv = i[\'intervention_group\'].split(\"|\") if i[\'intervention_group\']\r\n            if fs\r\n            for f in fs\r\n                if f[:i]\r\n                    fi = f[:i][0]\r\n                    inv << fi[\'intervention_tag\']\r\n                end\r\n            end\r\n            end\r\n            \r\n            i[\'intervention_group\'] = inv.uniq.join(\'|\')\r\n            \r\n            end\r\n    \r\n            \r\n		end\r\n  \r\n  end\r\n %>\r\n  <%#interventions_map.inspect %>\r\n  \r\n  \r\nFor <i><%=from_date.strftime(\"%d-%m-%Y\")%> to <%=to_date.strftime(\"%d-%m-%Y\")%> </i>\r\n \r\n<br/><br/>\r\n \r\n \r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Procedure</th><th>Elective</th><th>Emergency</th><th>Special Clinic</th><th>Undefined</th><th>Total</th>\r\n	</tr>\r\n<%  \r\n    tsum = {\'0\'=>0,\'1\'=>0,\'2\'=>0,nil=>0}\r\n\r\n	for k in case_map.keys \r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n		s = i[\'schedule\']\r\n     \r\n		tmap[s] = [] unless tmap[s]\r\n		tmap[s] << i \r\n     \r\n		tsum[s] = 0 unless tsum[s]\r\n		tsum[s] += 1\r\n      \r\n	end\r\n  \r\n%>\r\n    <tr><td><%=k.humanize%></td>\r\n      \r\n		<td align=\'center\'><%=tmap[\'0\'].size if tmap[\'0\']%></td>\r\n		<td align=\'center\'><%=tmap[\'1\'].size if tmap[\'1\']%></td>\r\n		<td align=\'center\'><%=tmap[\'2\'].size if tmap[\'2\']%></td>\r\n		<td align=\'center\'><%=tmap[\'\'].size if tmap[\'\']%></td>\r\n      \r\n    <th><%=case_map[k].size%></th></tr>\r\n	\r\n<% end %>      \r\n \r\n	<tr>\r\n		<td>&nbsp;</td>\r\n		<th><%=tsum[\'0\']%></td>\r\n		<th><%=tsum[\'1\']%></td>\r\n		<th><%=tsum[\'2\']%></td>\r\n		<th><%=tsum[\'\']%></td>\r\n<%\r\n			total_sum = 0 \r\n			total_sum += tsum[\'0\'] if tsum[\'0\']\r\n			total_sum += tsum[\'1\'] if tsum[\'1\']\r\n			total_sum += tsum[\'2\'] if tsum[\'2\']\r\n			total_sum += tsum[\'\'] if tsum[\'\']\r\n\r\n%>\r\n		<th><%=total_sum%></th>\r\n	</tr>\r\n</table>\r\n\r\n<br>\r\n  \r\n<% if procedure!=\'all\'%>\r\n<%\r\n    int_map = {}\r\n    for i in records\r\n		int = i[\'intervention_group\']\r\n		if int\r\n			ints = int.split(\'|\') \r\n     \r\n			for j in ints\r\n				int_map[j] = 0 unless int_map[j]\r\n				int_map[j] += 1\r\n			end\r\n		end\r\n    end\r\n  \r\n%>\r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Intervention</th><th>Count</th>\r\n	</tr>\r\n<% for i in int_map.keys %>\r\n	<tr>\r\n		<th><%=i.humanize%></th>\r\n		<td align=\'center\'><%=int_map[i]%></td>\r\n	</tr>\r\n<% end %>\r\n</table>\r\n  \r\n<br/>\r\n  \r\n<%\r\n    dx_map = {}\r\n    for i in records\r\n     \r\n		int = i[\'diagnosis_group\']\r\n		if int\r\n			dxs = int.split(\'|\') \r\n     \r\n			for j in dxs\r\n     \r\n				dx_map[j] = 0 unless dx_map[j]\r\n				dx_map[j] += 1\r\n     \r\n			end\r\n     \r\n		end\r\n      \r\n    end\r\n  \r\n%>\r\n\r\n<%\r\n  \r\n    options = get_document(procedure ).find_by_column_name(\'diagnosis_group\').get_lov_options   \r\n    \r\n    dx_name = {}\r\n    \r\n    for i in options\r\n        \r\n        dx_name[i[0]] = i[1].strip\r\n    \r\n    end\r\n  \r\n  \r\n%>\r\n  \r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Diagnosis Group</th><th>Count</th>\r\n	</tr>\r\n<% \r\n	for i in dx_map.keys \r\n  \r\n		name = \"Undefined(\\\\#{i})\"\r\n		name = dx_name[i] if dx_name[i]\r\n  \r\n%>\r\n	<tr>\r\n		<th><%=name%></th>\r\n		<td align=\'center\'><%=dx_map[i]%></td>\r\n	</tr>\r\n  \r\n<% end %>\r\n</table>\r\n  \r\n<br/>\r\n  \r\n<% end %>\r\n<div class=\'row-fluid\'>\r\n<div style=\'float:right;margin:20px\'>\r\n<%= link_to \'Export EXCEL\', \"case_reports_excel?from_date=\\\\#{from_date.strftime(\'%Y-%m-%d\')}&to_date=\\\\#{to_date.strftime(\'%Y-%m-%d\')}&type=\\\\#{params[:report][:type]}&procedure=\\\\#{params[:report][:procedure]}\", :target=>\'_blank\', :class=>\'btn btn-info\' %>\r\n</div></div>\r\n\r\n<table border=\"1\">\r\n	<tr>\r\n		<th>#</th>\r\n		<th>Procedure</th>\r\n		<th>Date</th>\r\n		<th>HN</th>\r\n		<th>Patient\'s name</th>\r\n		<th>Schedule</th>\r\n		<th>Endosocpist</th>\r\n		<th>Diagnosis</th>\r\n		<th>Intervention</th>\r\n		<th>InterventionGroup</th>\r\n	</tr>\r\n\r\n<%\r\n	# zam\r\n	# prepare excel result\r\n	res = {}\r\n	\r\n	# select provider of those records\r\n	for k in case_map.keys\r\n		\r\n		# zam\r\n		# set operation name\r\n		op_name = k.humanize\r\n%>\r\n	<tr style=\"background-color:#ccffcc\">\r\n		<td colspan=\"10\"><h1><%=k.humanize%></h1></td>\r\n	</tr>\r\n<%\r\n  \r\n		tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n			s = i[\'schedule\']\r\n     \r\n			tmap[s] = [] unless tmap[s]\r\n			tmap[s] << i \r\n      \r\n		end\r\n  \r\n		tmap.each_pair do |ks, list| \r\n			index = 0 \r\n			\r\n			# zam\r\n			# set visit_type\r\n			vt = tschedule[ks]\r\n			kk = \"\\\\#{op_name}-\\\\#{vt}\"\r\n			res[kk] = []\r\n%>\r\n    <tr style=\"background-color:#cccccc\">\r\n		<td colspan=\"10\"><%=tschedule[ks]%></td>\r\n	</tr>\r\n<%\r\n	list.each do |i|\r\n	\r\n		# zam\r\n		# temporary for each records\r\n		tmp = {}\r\n    \r\n		pm = m_all_pm[i[\'_id\']][0]\r\n		if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n			patient = m_patients[pm[\'patient_id\']][0]\r\n			provider = nil\r\n			provider = m_providers[i[\'endoscopist\']][0]  if m_providers[i[\'endoscopist\']]\r\n			\r\n			if pm and patient  and provider\r\n        \r\n				schedule = \'-\'\r\n        \r\n				schedule = tschedule[ i[\'schedule\']]\r\n				\r\n				# collect text into tmp\r\n				op_date = i[\'created_at\'].strftime(\"%d/%m/%Y\") \r\n				pat_hn  = patient[\'hn\'] \r\n				pat_name= \"\\\\#{patient[\'first_name\']} \\\\#{patient[\'last_name\']}\"\r\n				\r\n				tmp[:op_date] = op_date\r\n				tmp[:hn] = pat_hn\r\n				tmp[:name] = pat_name\r\n				tmp[:endo] = provider[\'name\']\r\n				tmp[:diag] = i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'diagnosis_text\']\r\n				tmp[:inv_txt] = i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'intervention_text\'] \r\n				tmp[:inv_sum] = i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'intervention_summary\']\r\n				tmp[:inv_group] = i[\'intervention_group\']\r\n				\r\n				\r\n				res[kk] << tmp\r\n        \r\n%>\r\n	<tr>\r\n		<td><%=index+1%></td>\r\n        <td><%=k.humanize%></td>\r\n		<td><%=i[\'created_at\'].strftime(\"%d-%m-%Y\") %></td>\r\n		<td><%=patient[\'hn\'] %></td>\r\n		<td><%=patient[\'first_name\'] %> <%=patient[\'last_name\']%></td>\r\n		<td><%= schedule %></td><td><%= provider[\'name\'] %></td>\r\n        <td style=\"width:300px\"><%= i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').html_safe if i[\'diagnosis_text\'] %></td>\r\n        <td style=\"width:300px\"><%= i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').html_safe if i[\'intervention_text\'] %><%= i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').html_safe if i[\'intervention_summary\'] %></td>\r\n<%\r\n           ig = \'background-color:#ffcccc\'\r\n%>\r\n        <td style=\'<%=ig if  i[\'intervention_text\']!=\"\" and i[\'intervention_group\'] and  i[\'intervention_group\'].strip==\'\' %>\'>\r\n<%\r\n            intv = \'-\'\r\n          \r\n%>\r\n			<%=i[\'intervention_group\']%><%#i[\'intervention_text\']%>\r\n			</td>\r\n        </tr>\r\n<%\r\n        \r\n				index+=1\r\n        \r\n			end # if pm and patient  and provider\r\n    \r\n		end #if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n  \r\n        \r\n	end # list.each do |i|\r\n  \r\n	end # tmap.each_pair do |ks, list| \r\n  \r\n	end # for k in case_map.keys\r\n	\r\n# 	session[:case_report_excel] = res\r\n# 	session[:case_report_from] = from_date.strftime(\"%d/%m/%Y\")\r\n# 	session[:case_report_to] = to_date.strftime(\"%d/%m/%Y\")\r\n  \r\n%>\r\n</table>\r\n<%# res.to_json.html_safe %>\r\n<%\r\n  \r\n  # for each recoreds to reprrt\r\n  \r\n%>\r\n  \r\n  \r\n  \r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2016-02-08 02:55:51','2016-02-08 02:55:51','case_reports',''),(2076,'case_reports_excel',789,3,'<%\r\n    response.headers[\"Content-Type\"] = \"application/xls\"\r\n    response.headers[\"Content-disposition\"] = \"attachment; filename=CaseReports-\\\\#{Time.now.to_i}.xls\"\r\n    \r\n    pname = \"\\\\#{@current_project.name}#\"\r\n	tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n \r\n\r\n\r\n	def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    @m_patient= model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = params[:from_date]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = params[:to_date]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    type = \'All\'\r\n    type = params[:report][:type] if params[:report]\r\n    \r\n    procedure = \'all\'\r\n    procedure = params[:report][:procedure] if params[:report]\r\n    \r\n    procedures = %w{all gastro colono push_enteroscopy sigmoid ercp eus dbe}\r\n    cmap = {}\r\n    for i in procedures\r\n        cmap[i] = i.humanize\r\n    end\r\n	\r\n	\r\n  \r\n		# select appointment by date\r\n  \r\n		all_app = @models[:appointment].collection.find({:date=>{\'$gte\'=>from_date,\'$lt\'=>to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n  \r\n  \r\n		# select pm by module_id of appointment\r\n  \r\n		all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n		m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n  \r\n		# select patients by patient_id of pm \r\n		all_patients = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'hn\'=>1}}).to_a\r\n		m_patients = bmap all_patients\r\n  \r\n  \r\n		map = {}\r\n  \r\n		# for each forms prepare list of module_id \r\n		all_pm = @m_patient_module.collection.find({:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n		m_all_pm = bmap all_pm, \'module_id\'\r\n  \r\n		for i in all_pm\r\n  \r\n			m = i[\'module_name\'].split(\'#\')[-1]\r\n  \r\n			if procedure==\'all\'\r\n  \r\n				map[m] = [] unless map[m]\r\n				map[m] << i[\'module_id\']\r\n  \r\n			else\r\n  \r\n				if m == procedure\r\n  \r\n					map[m] = [] unless map[m]\r\n					map[m] << i[\'module_id\']\r\n  \r\n				end\r\n  \r\n      \r\n			end\r\n  \r\n		end\r\n  \r\n  \r\n		# for each form\'s records \r\n		case_map = {}\r\n		provider_map = {}\r\n  \r\n    for k in map.keys\r\n    \r\n		rs = map[k]\r\n		case_map[k] = [] unless case_map[k]\r\n		if @models[k.to_sym]\r\n    \r\n			conds = {:_id=>{\'$in\'=>rs}}\r\n    \r\n			# 0|Elective\r\n			# 1|Emergency\r\n			# 2|Special clinic\r\n			# 3|Live demo\r\n    \r\n    \r\n			if type !=\'All\'\r\n    \r\n				ctype = \'\'\r\n				case type\r\n					when \'Elective\'\r\n						ctype = \'0\'\r\n					when \'Emergency\'\r\n						ctype = \'1\'\r\n					when \'Special clinic\'\r\n						ctype = \'2\'\r\n				end\r\n        \r\n				conds.merge! :schedule=> ctype\r\n       \r\n			end\r\n        \r\n			records = @models[k.to_sym].collection.find(conds, {:fields=>{\'comment\'=>1,\'_id\'=>1,\'complications\'=>1,\'clinical_indication\'=>1,\'start_procedural_time\'=>1,\'findings\'=>1,\'_id\'=>1,\'schedule\'=>1,\'endoscopist\'=>1,\'created_at\'=>1,\'diagnosis_text\'=>1,\'diagnosis_group\'=>1,\'intervention_text\'=>1,\'procedure\'=>1,\'intervention\'=>1,\'intervention_group\'=>1,\'intervention_summary\'=>1}}).to_a\r\n\r\n	@document = get_document(k)\r\n   \r\n			findings_id = []\r\n         idx_name = {}\r\n		    if @document.find_by_column_name(\'clinical_indication\')\r\n		    for i in @document.find_by_column_name(\'clinical_indication\').get_lov_options   \r\n			\r\n			    idx_name[i[0]] = i[1].strip\r\n		\r\n		    end # for i in options\r\n        end\r\n\r\n			for i in records\r\n				provider_map[i[\'endoscopist\']] = true \r\n        \r\n				findings_id += i[\'findings\'] if i[\'findings\']\r\n                i[\'clinical_indication\'] =  i[\'clinical_indication\'].split(\"|\").collect{|x| idx_name[x]}.join(\", \") if i[\'clinical_indication\']  #render_value(\'clinical_indication\')\r\n                i[\'complications\'] = i[\'comment\'] if i[\'complications\']==\'0\'\r\n                i[\'complications\'] = \'Y \'+i[\'comment\'] if i[\'complications\']==\'1\'\r\n                \r\n				if true\r\n					case_map[k] << i \r\n				end\r\n        \r\n			end\r\n\r\n		end\r\n  \r\n	end\r\n  \r\n  \r\n	providers = @models[:provider].collection.find({:_id=>{\'$in\'=>provider_map.keys}})\r\n	m_providers = bmap providers\r\n  \r\n  \r\n	findings = @models[:finding].collection.find({:_id=>{\'$in\'=>findings_id.collect{|x| BSON::ObjectId(eval(x)[0])}}}).to_a\r\n	findings_map = bmap findings\r\n  \r\n	intervention_ids = findings.collect{|x| x[\'intervention\'] }\r\n  \r\n	interventions = @models[:intervention].collection.find({:_id=>{\'$in\'=>intervention_ids},:intervention_tag=>{\'$ne\'=>\"\"}},{:fields=>{\'intervention_tag\'=>1,\'op_clipping_type\'=>1}}).to_a\r\n  \r\n	interventions_map = bmap interventions\r\n  \r\n  \r\n		for i in records\r\n  \r\n			if i[\'findings\']\r\n            \r\n			fs = i[\'findings\'].collect{|x| findings_map[BSON::ObjectId(eval(x)[0])][0] }\r\n			fs = fs.collect{|x| {:f=>x,:i=>interventions_map[x[\'intervention\']]} } \r\n            inv = []\r\n            inv = i[\'intervention_group\'].split(\"|\") if i[\'intervention_group\']\r\n            for f in fs\r\n                if f[:i]\r\n                    fi = f[:i][0]\r\n                    inv << fi[\'intervention_tag\']\r\n                end\r\n            end\r\n            \r\n            i[\'intervention_group\'] = inv.uniq.join(\'|\')\r\n            \r\n            end\r\n    \r\n            \r\n		end\r\n \r\n    tsum = {\'0\'=>0,\'1\'=>0,\'2\'=>0,nil=>0}\r\n\r\n	for k in case_map.keys \r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n			s = i[\'schedule\']\r\n		 \r\n			tmap[s] = [] unless tmap[s]\r\n			tmap[s] << i \r\n		 \r\n			tsum[s] = 0 unless tsum[s]\r\n			tsum[s] += 1\r\n      \r\n		end # case_map[k].each do |i|\r\n  \r\n	end  # for k in case_map.keys      \r\n \r\n  \r\n	if procedure!=\'all\'\r\n\r\n		int_map = {}\r\n		for i in records\r\n			int = i[\'intervention_group\']\r\n			if int\r\n				ints = int.split(\'|\') \r\n		 \r\n				for j in ints\r\n					int_map[j] = 0 unless int_map[j]\r\n					int_map[j] += 1\r\n				end\r\n			end\r\n		end\r\n	  \r\n		dx_map = {}\r\n		for i in records\r\n		 \r\n			int = i[\'diagnosis_group\']\r\n			if int\r\n				dxs = int.split(\'|\') \r\n		 \r\n				for j in dxs\r\n		 \r\n					dx_map[j] = 0 unless dx_map[j]\r\n					dx_map[j] += 1\r\n		 \r\n				end # for j in dxs\r\n		 \r\n			end # if int\r\n		  \r\n		end # for i in records\r\n		options = []\r\n		options = get_document(procedure ).find_by_column_name(\'diagnosis_group\').get_lov_options    if get_document(procedure ).find_by_column_name(\'diagnosis_group\')\r\n		\r\n		dx_name = {}\r\n		\r\n		for i in options\r\n			\r\n			dx_name[i[0]] = i[1].strip\r\n		\r\n		end # for i in options\r\n	  \r\n	  \r\n		for i in dx_map.keys \r\n	  \r\n			name = \"Undefined(\\\\#{i})\"\r\n			name = dx_name[i] if dx_name[i]\r\n		end # for i in dx_map.keys \r\n	  \r\n	  \r\n	end # if procedure!=\'all\'\r\n\r\n	# zam\r\n	# prepare excel result\r\n	res = {}\r\n	sdate = from_date.strftime(\'%d/%m/%Y\')\r\n	edate = to_date.strftime(\'%d/%m/%Y\')\r\n	\r\n	# select provider of those records\r\n	for k in case_map.keys\r\n		\r\n		# zam\r\n		# set operation name\r\n		op_name = k.humanize\r\n\r\n		tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n			s = i[\'schedule\']\r\n     \r\n			tmap[s] = [] unless tmap[s]\r\n			tmap[s] << i \r\n      \r\n		end\r\n  \r\n		tmap.each_pair do |ks, list| \r\n			index = 0 \r\n			\r\n			# zam\r\n			# set visit_type\r\n			vt = tschedule[ks]\r\n			kk = \"\\\\#{op_name}-\\\\#{vt}\"\r\n			res[kk] = []\r\n\r\n			list.each do |i|\r\n			\r\n				# zam\r\n				# temporary for each records\r\n				tmp = {}\r\n			\r\n				pm = m_all_pm[i[\'_id\']][0]\r\n				if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n					patient = m_patients[pm[\'patient_id\']][0]\r\n					provider = nil\r\n					provider = m_providers[i[\'endoscopist\']][0]  if m_providers[i[\'endoscopist\']]\r\n					\r\n					if pm and patient  and provider\r\n				\r\n						schedule = \'-\'\r\n				\r\n						schedule = tschedule[ i[\'schedule\']]\r\n						\r\n						# collect text into tmp\r\n						op_date = i[\'created_at\'].strftime(\"%d/%m/%Y\") \r\n						pat_hn  = patient[\'hn\'] \r\n						pat_name= \"\\\\#{patient[\'first_name\']} \\\\#{patient[\'last_name\']}\"\r\n						\r\n						tmp[:op_date] = op_date\r\n						tmp[:hn] = pat_hn\r\n						tmp[:name] = pat_name\r\n						tmp[:endo] = provider[\'name\']\r\n						tmp[:diag] = i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'diagnosis_text\']\r\n						tmp[:inv_txt] = i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'intervention_text\'] \r\n						tmp[:inv_sum] = i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'intervention_summary\']\r\n						tmp[:inv_group] = i[\'intervention_group\']\r\n						tmp[:time] = i[\'start_procedural_time\'].strftime(\"%H:%M\")\r\n						tmp[:indication]= i[\'clinical_indication\']\r\n						tmp[:complication] = i[\'complications\']\r\n						\r\n						res[kk] << tmp\r\n				\r\n						index+=1\r\n				\r\n					end # if pm and patient  and provider\r\n			\r\n				end #if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n		  \r\n				\r\n			end # list.each do |i|\r\n  \r\n		end # tmap.each_pair do |ks, list| \r\n  \r\n	end # for k in case_map.keys\r\n%>\r\n<?xml version=\"1.0\"?>\r\n<?mso-application progid=\"Excel.Sheet\"?>\r\n<Workbook xmlns=\"urn:schemas-microsoft-com:office:spreadsheet\"\r\n xmlns:o=\"urn:schemas-microsoft-com:office:office\"\r\n xmlns:x=\"urn:schemas-microsoft-com:office:excel\"\r\n xmlns:ss=\"urn:schemas-microsoft-com:office:spreadsheet\"\r\n xmlns:html=\"http://www.w3.org/TR/REC-html40\">\r\n <DocumentProperties xmlns=\"urn:schemas-microsoft-com:office:office\">\r\n  <Author>E.S.M.Solution CO.,Ltd.</Author>\r\n  <LastAuthor><%= @current_user %></LastAuthor>\r\n  <Created><%= Time.now %></Created>\r\n  <LastSaved><%= Time.now %></LastSaved>\r\n  <Version>15.00</Version>\r\n </DocumentProperties>\r\n <OfficeDocumentSettings xmlns=\"urn:schemas-microsoft-com:office:office\">\r\n  <AllowPNG/>\r\n </OfficeDocumentSettings>\r\n <ExcelWorkbook xmlns=\"urn:schemas-microsoft-com:office:excel\">\r\n  <WindowHeight>7800</WindowHeight>\r\n  <WindowWidth>20490</WindowWidth>\r\n  <WindowTopX>0</WindowTopX>\r\n  <WindowTopY>0</WindowTopY>\r\n  <ProtectStructure>False</ProtectStructure>\r\n  <ProtectWindows>False</ProtectWindows>\r\n </ExcelWorkbook>\r\n <Styles>\r\n  <Style ss:ID=\"Default\" ss:Name=\"Normal\">\r\n   <Alignment ss:Vertical=\"Bottom\"/>\r\n   <Borders/>\r\n   <Font ss:FontName=\"Calibri\" x:Family=\"Swiss\" ss:Size=\"11\" ss:Color=\"#000000\"/>\r\n   <Interior/>\r\n   <NumberFormat/>\r\n   <Protection/>\r\n  </Style>\r\n  <Style ss:ID=\"s65\">\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s68\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s69\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s70\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Bottom\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s72\">\r\n   <Alignment ss:Vertical=\"Bottom\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s74\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\" ss:WrapText=\"1\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s75\">\r\n   <Alignment ss:Vertical=\"Bottom\" ss:WrapText=\"1\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n </Styles>\r\n<%\r\n    res.keys.each do |i|\r\n        ws_name = i\r\n        arr = res[i]\r\n        if arr.count == 0\r\n            next\r\n        end\r\n        if i.split(\'-\').count != 1 or arr.count != 0\r\n            # arr = res[i]\r\n%>\r\n <Worksheet ss:Name=\"<%= ws_name %>\">\r\n  <Table ss:ExpandedColumnCount=\"13\" ss:ExpandedRowCount=\"<%= arr.count + 10 %>\" x:FullColumns=\"1\"\r\n   x:FullRows=\"1\" ss:DefaultRowHeight=\"15\">\r\n   <Column ss:StyleID=\"s68\" ss:AutoFitWidth=\"0\" ss:Width=\"35.25\"/>\r\n   <Column ss:StyleID=\"s70\" ss:AutoFitWidth=\"0\" ss:Width=\"68.25\"/>\r\n   <Column ss:StyleID=\"s70\" ss:Width=\"67.5\"/>\r\n   <Column ss:StyleID=\"s65\" ss:AutoFitWidth=\"0\" ss:Width=\"150\" ss:Span=\"1\"/>\r\n   <Column ss:Index=\"6\" ss:StyleID=\"s75\" ss:AutoFitWidth=\"0\" ss:Width=\"150\"\r\n    ss:Span=\"3\"/>\r\n   <Column ss:Index=\"10\" ss:StyleID=\"s65\" ss:AutoFitWidth=\"0\"/>\r\n   <Row>\r\n    <Cell ss:MergeAcross=\"8\"><Data ss:Type=\"String\"><%= ws_name %> Report</Data></Cell>\r\n    <Cell ss:StyleID=\"s72\"/>\r\n   </Row>\r\n   <Row>\r\n    <Cell ss:MergeAcross=\"8\"><Data ss:Type=\"String\"><%= sdate %> to <%= edate %></Data></Cell>\r\n    <Cell ss:StyleID=\"s72\"/>\r\n   </Row>\r\n   <Row ss:Index=\"4\" ss:StyleID=\"s69\">\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">No</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Date</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Time</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">HN</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Patient\'s name</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Endosocpist</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Indication</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Diagnosis</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Intervention</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Intervention Summary</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">InterventionGroup</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Complication</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"/>\r\n   </Row>\r\n<%\r\n    idx = 1\r\n    arr.each do |i|\r\n%>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"52\">\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= idx.to_s %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:op_date] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:time] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:hn] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:name] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:endo] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:indication] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= i[:diag] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= i[:inv_txt] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= i[:inv_sum] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= i[:inv_group] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= i[:complication] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"/>\r\n   </Row>\r\n<%\r\n        idx += 1\r\n    end\r\n%>\r\n  </Table>\r\n  <WorksheetOptions xmlns=\"urn:schemas-microsoft-com:office:excel\">\r\n   <PageSetup>\r\n    <Header x:Margin=\"0.3\"/>\r\n    <Footer x:Margin=\"0.3\"/>\r\n    <PageMargins x:Bottom=\"0.75\" x:Left=\"0.7\" x:Right=\"0.7\" x:Top=\"0.75\"/>\r\n   </PageSetup>\r\n   <Selected/>\r\n   <Panes>\r\n    <Pane>\r\n     <Number>3</Number>\r\n     <ActiveRow>5</ActiveRow>\r\n     <ActiveCol>1</ActiveCol>\r\n    </Pane>\r\n   </Panes>\r\n   <ProtectObjects>False</ProtectObjects>\r\n   <ProtectScenarios>False</ProtectScenarios>\r\n  </WorksheetOptions>\r\n </Worksheet>\r\n<%\r\n        end\r\n    end\r\n%>\r\n</Workbook>\r\n\r\n',NULL,NULL,NULL,'2016-02-08 03:40:15','2016-02-08 03:40:15','case_reports_excel',''),(2077,'document_name',884,1,'\'station\'',NULL,NULL,NULL,'2016-02-09 05:53:14','2016-02-09 05:53:14',NULL,NULL),(2078,'index',885,2,'\r\n<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n\r\n\r\n<div id = \"index_panel\" style=\"min-height:400px\">\r\n<center>\r\n<br/><br/><br/><br/><br/><br/><br/>\r\n<h1>\r\nLoading...</h1>\r\n</center>\r\n</div>\r\n\r\n<%\r\n\r\n\r\n\r\n@partial_role = @current_role\r\n\r\n\r\nif params[:role]\r\n   session[:role] = params[:role] \r\nend\r\n\r\nsession.delete :role if params[:role] and params[:role] ==\'\'\r\n\r\n@partial_role = session[:role] if session[:role]\r\nif params[:station]\r\n   \r\n   session[:current_station] = params[:station] \r\n    \r\nend\r\n\r\n\r\n if session[:current_station]\r\n    @current_station = session[:current_station] \r\n else\r\n    @station = get_model[:station].first\r\n    if @station\r\n        session[:current_station] = @station.id\r\n        @current_station = session[:current_station]\r\n    end\r\n    \r\n end\r\n\r\n\r\nlanding = \'index_partial\'\r\n\r\n# landing = \"../Registration/index_partial\" if @partial_role==\'registration\'\r\n\r\n# landing = \"../Exam/index_partial\" if @partial_role==\'exam\'\r\n\r\n# landing = \"../Opd/index_partial\" if @partial_role==\'opd\'\r\n\r\n# landing = \"../Counselling/index_partial\" if @partial_role==\'counselling1\'\r\n\r\n# landing = \"../Accounting/index_partial\" if @partial_role==\'accounting\'\r\n\r\n# landing = \"../Counselling/index_partial_2\" if @partial_role==\'counselling2\'\r\n\r\n# landing = \"../Injection/index_partial\" if @partial_role==\'injection\'\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n%>\r\n\r\n<script>\r\n    \r\n$.ajax({\r\n  url: \"<%=landing%>\",\r\n  cache: false\r\n})\r\n .done(function( html ) {\r\n    $( \"#index_panel\" ).hide();\r\n    $( \"#index_panel\" ).html(html);\r\n    $(\"#index_panel\").fadeIn(300);\r\n\r\n  });\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n\r\n if params[:obj_id] \r\n now = Time.now \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-02-09 05:57:13','2016-02-09 05:57:13','',''),(2080,'clinic_config',885,1,'\r\n\r\n    @clinic_config = {}\r\n    \r\n    config = @clinic_config\r\n    \r\n    \r\n    config[:name] = \'Clinic Solution\'\r\n    \r\n    @clinic_config = config',NULL,NULL,NULL,'2016-02-09 06:04:12','2016-02-09 06:04:12','clinic_config',''),(2081,'create',882,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n\r\n    dd = Time.now.strftime(\'%d-%m-%Y\')\r\n    tt = Time.now.strftime(\'%H:%M\')\r\n    rec_name = @next_id\r\n    record = get_model[this.table_name.to_sym].create\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>dd,:time=>tt,:parent_id=>params[:parent_id],:ref_number=>rec_name\r\n    params[:id] = m.id.to_s\r\n%>\r\n<script>\r\n    window.location=\"edit?id=<%=m.id%>&return=<%=return_url%>\";\r\n</script>\r\n<%\r\n    if false\r\n%>\r\n<div class=\"row-fluid\">\r\n  <div class=\"span12\">\r\n    <div class=\"w-box\">\r\n      <div class=\"w-box-header\">\r\n        <h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n      </div>\r\n      <div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n        <div style=\"border:0px solid\">\r\n          <div class=\"document-border\" style=\"border:0px solid\">\r\n<%\r\n    model = get_model()[this.table_name.to_sym]\r\n    @patient_module = @module_model.find(params[:id])\r\n    record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n      locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n      if locker \r\n        if locker.session!= session[:user].to_s\r\n%>\r\n<script>\r\n    alert(\"Someone is editing this document!!\");\r\n    window.location = \"<%=return_url%>\";\r\n</script>\r\n<%\r\n        end\r\n      else\r\n        locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n      end\r\n    end\r\n  \r\n     \r\n    t = Time.now - record.updated_at \r\n \r\n \r\n    if  false and  @current_role!=\'superuser\' and @current_role!=\'developer\' and @current_role!=\'admin\' # and t.to_i > 3600 * 24 \r\n     locker.destroy if locker\r\n%>\r\n<script>\r\n  alert(\"Not allowed to edit this document!!\");\r\n  window.location = \"<%=return_url%>\";\r\n</script>\r\n<%\r\n    end\r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n           <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n            Ref : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n            <%= hidden_field_tag \'return\', return_url %>\r\n\r\n            <span class=\"right\">\r\n              Date : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\n              Time : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n            </span>\r\n          </div>\r\n<!-- show patient -->\r\n          <div id=\'patient\'></div>\r\n<script>\r\n    url = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\n    url += \'&id=<%=@patient_module.patient_id%>\'\r\n    $.ajax({\r\n      url: url,\r\n      success: function(data){\r\n        $(\'#patient\').html(data);  \r\n      }\r\n    });\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n          <p>\r\n<%= this.form.html_safe %>\r\n          </p>\r\n          <br/>\r\n          <%= f.submit \"Update\".html_safe, :class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n          <%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:data=>{:confirm=>\'Are you sure?\'} %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end # form_for %>\r\n<% end # if request.post? %>\r\n\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n\r\n<!--\r\n\r\n\r\n    PACU FORM RECORD\r\n\r\n\r\n-->\r\n<!--\r\n\r\n\r\n  PACU FORM MODAL SECTION\r\n  \r\n\r\n                -->\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>PACU Record</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n<%= form_for :pacu, :url=>\"pacu_content??update=pacu-content\", :html=>{\'id\'=>\'form-pacu-modal\'}, :remote=>true do |f| %>\r\n        <div id=\'form-pacu_record\'></div>\r\n        <div id=\'form-fluid\'></div>\r\n        <div id=\'form-drain\'></div>\r\n        <div style=\'float:right\'>\r\n            <%= link_to \'Cancel\', \'#\', :class=>\'btn\', \'data-dismiss\'=>\'modal\' %>\r\n            <%= f.submit \'Add\', :class=>\'btn btn-success\', :id=>\'pacu-add-btn\' %>\r\n        </div>\r\n<% end %>\r\n    </div>\r\n</div>\r\n\r\n\r\n<script>\r\n    function o2supplement_update() {\r\n        tmp = $(this).val();\r\n        $(\'#o2-supplement-data\').text(tmp);\r\n        console.log(\'VAL : \' + tmp);\r\n    }\r\n    function painscore_update() {\r\n        tmp = parseInt($(this).val());\r\n        obj = $(\'#data-pain\');\r\n        if (tmp <= 4) {\r\n            obj.val(\'2\');\r\n        } else if (tmp == 5 || tmp == 6) {\r\n            obj.val(\'1\');\r\n        } else {\r\n            obj.val(\'0\');\r\n        }\r\n        // console.log(\'SCORE : \' + tmp);\r\n    }\r\n    function init_field() {\r\n        \r\n    }\r\n    function pacuDemo(){\r\n        init_field();\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n        \r\n        // console.log(\'EVENT : \' + $(\"#data-pain_score:Event(change)\"));\r\n        // $(\'#data-pain_score\').change(painscore_update);\r\n    }\r\n    function pacuModalClose() {\r\n        \r\n        console.log(\'Modal Close\');\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#pacu-diagnosis_note-add-action\').text(\'เพิ่มรายละเอียด\');\r\n        \r\n        $(\'#form-pacu_record\').load(\'../PacuRecord/create #form-data\', function() {\r\n            $(\'#data-pain_score\').change(painscore_update);\r\n            $(\"#data-time\").kendoTimePicker({\r\n              value: \'08:00\',\r\n              interval: 10,\r\n              parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n              change: function(event){\r\n                var v = $(\'#data-time\').val()\r\n                if(v.length==3){\r\n                  $(\'#data-time\').val(v[0]+\":\"+v[1]+v[2])\r\n                }\r\n                 \r\n              }\r\n            });\r\n        });\r\n        $(\'#pacu-content\').load(\'pacu_content\');\r\n        $(\'#data-o2_supplement\').change(o2supplement_update);\r\n        // $(\'#pacu-add-btn\').click(pacuModalClose);\r\n        $(\'#form-pacu-modal\').on(\'submit\', function() {\r\n            $(\'#modal\').modal(\'hide\');\r\n            console.log(\'Demo\');\r\n        });\r\n        // $(\'#pacu-pacu-add-action\').attr(\"href\", \"javascript:demo();\")\r\n        // $(\'#pacuDemo\').click();\r\n        \r\n    });\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<% \r\n    if @current_role == \'developer\' \r\n        model = get_model()[this.table_name.to_sym]\r\n        @patient_module = @module_model.find(params[:id])\r\n        record = model.find(@patient_module.module_id)\r\n%>\r\n<%= record.to_json.html_safe %>\r\n<% end %>\r\n<% end %>',NULL,NULL,NULL,'2016-02-09 06:14:21','2016-02-09 06:14:21','create',''),(2082,'clinic_config_template',885,1,'config = {:test=>\'xx\'}\r\n\r\nworkflow = []\r\n\r\n\r\n\r\nworkflow << { :name=>\'registration\', :in_bound=>%w{booking appointed new}, :process_station=>%w{registration}, :out_bound=>%w{arrived cancelled} }\r\n\r\nworkflow << { :name=>\'basic_exam\', :in_bound=>%w{arrived}, :process_station=>%w{exam}, :out_bound=>%w{waiting_diagnosis} }\r\n\r\nworkflow << { :name=>\'diagnosis\', :in_bound=>%w{waiting_diagnosis}, :inter_status=>\'calling_diagnosis\', :process_station=>%w{diagnosis}, :out_bound=>%w{waiting_consult1} } \r\n\r\nworkflow << { :name=>\'consult1\', :in_bound=>%w{waiting_consult1}, :process_station=>%w{consult1}, :out_bound=>%w{waiting_billing completed} }\r\n\r\nworkflow << { :name=>\'pharmacy\', :in_bound=>%w{waiting_billing}, :process_station=>%w{billing}, :out_bound=>%w{waiting_consult2 completed} } \r\n\r\nworkflow << { :name=>\'consult2\', :in_bound=>%w{waiting_consult2}, :process_station=>%w{consult2}, :out_bound=>%w{waiting_injection completed} }\r\n\r\nworkflow << { :name=>\'injection\', :in_bound=>%w{waiting_injection}, :process_station=>%w{injection}, :out_bound=>%w{recovering} }\r\n\r\nworkflow << { :name=>\'recovery\', :in_bound=>%w{recovering}, :process_station=>%w{recovery}, :out_bound=>%w{completed} }\r\n\r\n\r\n\r\n\r\nconfig[:workflow] = workflow\r\n\r\n\r\nreturn config',NULL,NULL,NULL,'2016-02-09 06:47:49','2016-02-09 06:47:49','clinic_config_template',''),(2085,'document_name',887,1,'\'tumor\'',NULL,NULL,NULL,'2016-02-10 15:37:31','2016-02-10 15:37:31',NULL,NULL),(2088,'show',882,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    atts = @ehr_project.get_model :attachment\r\n    att =  atts.find(@patient_module.report)\r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n<% if att %>\r\n<%= link_to \'<i class=\"splashy-document_small_download\"></i> PDF\'.html_safe, att.path,:target=>\'_blank\',:class=>\'btn btn-mini btn-info\' %>\r\n<% end %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:950px\">\r\n\r\n<%= this.print_partial.html_safe %>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-02-10 17:04:40','2016-02-10 17:04:40','show',''),(2089,'edit',882,2,'<style>\r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	/*position: fixed;*/\r\n	position: absolute;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat #fff;\r\n}\r\n</style>\r\n<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\'se-pre-con\'></div>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model()[this.table_name.to_sym]\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this document!!\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n     \r\n    t = Time.now - record.updated_at \r\n \r\n \r\n    if  false and  @current_role!=\'superuser\' and @current_role!=\'developer\' and @current_role!=\'admin\' # and t.to_i > 3600 * 24 \r\n        locker.destroy if locker\r\n%>\r\n<script>\r\n    alert(\"Not allowed to edit this document!!\");window.location = \"<%=return_url%>\";\r\n</script>\r\n<%\r\n    end\r\n  \r\n    if request.post?\r\n  \r\n        locker.destroy if locker\r\n        doc = get_document this.document_name\r\n      \r\n        @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n        record = doc.record_update(model,params,record)\r\n        flash[:notice]=\'New record has been created\'\r\n        \r\n        url = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{@current_service.name}/pdf?id=\\\\#{@patient_module.id}\"\r\n        id = @patient_module.id.to_s\r\n        \r\n        pdf_file = \"tmp/cache/\\\\#{id}.pdf\"\r\n        kit = PDFKit.new(url,:margin_top => \'0.2in\',:margin_right => \'0.2in\',:margin_bottom => \'0.2in\',:javascript_delay => 1000)\r\n        file = kit.to_file(pdf_file)\r\n        \r\n        field = @module_doc .find_by_column_name \'report\'\r\n        att = @module_doc .attach_field_file field.id, file.path.split(\'/\')[-1] , \'\', File.open(file.path)\r\n        @patient_module.update_attributes :report=>att.id\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\n    window.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n    else\r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n    url = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\n    url += \'&id=<%=@patient_module.patient_id%>\'\r\n    $.ajax({\r\n        url: url,\r\n        success: function(data){\r\n            $(\'#patient\').html(data);  \r\n        }\r\n    });\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \"Save\".html_safe, :class=>\'btn btn-info\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:data=>{:confirm=>\'Are you sure?\'}, :class=>\'btn \' %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<%\r\n        end\r\n    end\r\n%>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n        value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n        interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n        value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\n    var validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n    $(\"#record-submit\").click(function() {\r\n        if (!validator.validate()) {\r\n            alert(\'Please fill all information\');\r\n            return false;\r\n        }else{\r\n            return true;\r\n            if(confirm(\'Are you sure?\')==true){\r\n                return true;\r\n            }\r\n            return false;\r\n        }\r\n    });\r\n</script>   \r\n\r\n<%= render :inline=>this.pacu_modal, :locals=>{:this=>this} %>\r\n<%= render :inline=>this.diag_modal, :locals=>{:this=>this} %>\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        setTimeout(function(){ \r\n            $(\".se-pre-con\").fadeOut(\"slow\"); \r\n            console.log(\'PACU REF : <%= record.id %>\');\r\n            $(\'data-pacu_ref_id\').val(\'<%= record.id %>\');\r\n        }, 1500);\r\n    });\r\n</script>',NULL,NULL,NULL,'2016-02-10 17:11:14','2016-02-10 17:11:14','edit',''),(2090,'document_name',889,1,'\'test_pacu\'',NULL,NULL,NULL,'2016-02-10 17:21:49','2016-02-10 17:21:49',NULL,NULL),(2091,'document_name',890,1,'\'item\'',NULL,NULL,NULL,'2016-02-10 17:31:03','2016-02-10 17:31:03',NULL,NULL),(2092,'form',873,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   \r\n    pm_app = nil\r\n    \r\n    if params[:opt] == \'create\'\r\n        pm_app = @module_model.where(:module_id=>@appointment.id).first\r\n    else\r\n        pm_rec = @module_model.where(:module_id=>@record.id).first\r\n        pm_app = @module_model.find(pm_rec[:parent_id])\r\n    end\r\n\r\n    pm_pre = @module_model.where(:parent_id=>pm_app.id, :module_name=>\"\\\\#{@current_project.name}#pre_op\").first\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    $(document).ready(function(){\r\n        tmp = $(\'#data-oral\').val();\r\n        if (tmp.indexOf(\'99\') == -1) {\r\n            $(\'#oral_other\').hide();\r\n        }\r\n        // console.log(\'oral : ...\' + tmp.indexOf(\'99\') + \"...\")\r\n    });\r\n</script>\r\n<script>\r\n    function update_recorder_name_1() {\r\n        code = $(this).val();\r\n        $.getJSON( \"../Apiz/get_provider_by_ref_number?code=\"+code, function( data ) {\r\n          $(\'#data-recorder_name_1\').val(data.id);\r\n          $(\'#data-recorder_name_1\').effect(\"highlight\", {}, 2000);\r\n        });\r\n    }\r\n    function update_recorder_name_2() {\r\n        code = $(this).val();\r\n        $.getJSON( \"../Apiz/get_provider_by_ref_number?code=\"+code, function( data ) {\r\n          $(\'#data-recorder_name_2\').val(data.id);\r\n          $(\'#data-recorder_name_2\').effect(\"highlight\", {}, 2000);\r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n<%\r\n    prov = get_model[:provider].all\r\n    code = []\r\n    prov.each do |i|\r\n        if i[:ref_number]\r\n            code << i[:ref_number]\r\n        end\r\n        # if i[:license_number]\r\n        #     code << i[:license_number]\r\n        # end\r\n    end\r\n    \r\n%>\r\n        var prov = <%= code.to_s.html_safe %>;\r\n        $(\'#data-recorder_code_1\').kendoAutoComplete({\r\n            dataSource: prov,\r\n            placeholder: \"Enter code ...\"\r\n        });\r\n        $(\'#data-recorder_code_2\').kendoAutoComplete({\r\n            dataSource: prov,\r\n            placeholder: \"Enter code ...\"\r\n        });\r\n        $(\'#data-recorder_code_1\').change(update_recorder_name_1);\r\n        $(\'#data-recorder_code_2\').change(update_recorder_name_2);\r\n        $(\'#data-recorder_name_2\').attr(\"readonly\", true);\r\n        \r\n<%\r\n    cur_user = @current_user\r\n    cur_prov = get_model[:provider].where(:login=>cur_user[:login]).first\r\n    if !cur_prov.nil?\r\n%>\r\n        rn_1 = $(\'#data-recorder_name_1\').val();\r\n        if (rn_1 == \"\") {\r\n            $(\'#data-recorder_name_1\').val(\'<%= cur_prov.id.to_s %>\');\r\n        }\r\n<%\r\n    end\r\n%>\r\n        \r\n    })\r\n    \r\n    \r\n<%\r\n# pm_pre = nil\r\n    if !pm_pre.nil?\r\n        rec = get_model[:pre_op].find(pm_pre[:module_id])\r\n%>\r\n    $(document).ready(function() {\r\n        dx_node = $(\'#data-diagnosis\');\r\n        op_node = $(\'#data-operation\');\r\n        if (dx_node.val() == \"\") {\r\n            dx_node.val(\"<%= rec[:diagnosis_1] %>\");\r\n        }\r\n        if (op_node.val() == \"\") {\r\n            op_node.val(\"<%= rec[:operation_1] %>\");\r\n        }\r\n    });\r\n<%  end %>\r\n</script>',NULL,NULL,NULL,'2016-02-11 04:09:03','2016-02-11 04:09:03','form',''),(2093,'form',881,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n',NULL,NULL,NULL,'2016-02-11 05:32:30','2016-02-11 05:32:30','',''),(2094,'pacu_content',882,3,'<%\r\n    mod = get_model[this.table_name.to_sym]\r\n    rec = nil\r\n    if params[:id]\r\n        rec = mod.find(params[:id])\r\n    end\r\n    \r\n    pacu = []\r\n    if rec\r\n        m_pacu = get_model[:pacu_record]\r\n        if params[:record]\r\n            p_rec = params[:record]\r\n            tmp = m_pacu.create p_rec\r\n            rec[:pacu_record] << tmp.id\r\n            rec.update_attributes :pacu_record=>rec[:pacu_record]\r\n        end\r\n        pacu = m_pacu.find(rec[:pacu_record])\r\n    end\r\n    \r\n    ts = {}\r\n    ff = [:vs_score, :spo2_score, :feeling, :breathing, :movement, :nausea_and_vomiting, :bleeding, :sit_up, :pain]\r\n    pacu.each_with_index do |v, i|\r\n        ts[i] = []\r\n        ff.each do |j|\r\n            ts[i] << v[j].to_i\r\n        end\r\n    end\r\n%>\r\n<style>\r\n.td_cen {\r\n	text-align:center;\r\n}\r\n.td_r {\r\n	text-align:right;\r\n}\r\n</style>\r\n<%# params.to_json.html_safe %>\r\n<% if params[:dis] == \'content\' %>\r\n<div style=\'width:720px;overflow: auto;overflow-y: hidden;white-space: nowrap;-ms-overflow-y: hidden;\'>\r\n<% else %>\r\n<div style=\'width:880px;overflow: auto;overflow-y: hidden;white-space: nowrap;-ms-overflow-y: hidden;\'>\r\n<% end %>\r\n\r\n	<table class=\"table table-bordered\">\r\n	  <thead>\r\n		<tr>\r\n		  <th width=\"50px\">Time</th>\r\n<% \r\n    pacu.each do |i| \r\n        if params[:dis] == \'content\'\r\n%>\r\n		  <th width=\"80px\">\r\n		    <center><%= link_to i[:time].strftime(\'%H:%M\'), \"../PacuRecord/edit?id=\\\\#{i.id}&pm=\\\\#{params[:pm]}&ap=\\\\#{params[:ap]}\", :class=>\'btn btn-info btn-mini\' %></center>\r\n		  </th>\r\n<% else %>\r\n		  <th width=\"80px\"><center><%= i[:time].strftime(\'%H:%M\') %></center></th>\r\n<% \r\n        end\r\n    end \r\n%>\r\n		  <!--<th width=\"20px\">PADS</th>-->\r\n		  <!-- <th>TREATMENT &amp; NURSING CARE</th> -->\r\n		</tr>\r\n	  </thead>\r\n	  <tbody>\r\n<% if params[:dis] == \'content\' %>\r\n	    <tr>\r\n	        <td>Remove</td>\r\n<% pacu.each do |i| %>\r\n		  <td>\r\n		    <center><%= link_to \'x\', \"../PacuRecord/destroy?id=\\\\#{i.id}&pm=\\\\#{params[:pm]}&ap=\\\\#{params[:ap]}\",:data=>{:confirm=>\'Are you sure?\'}, :class=>\'btn btn-danger btn-mini\' %></center>\r\n		  </td>\r\n<% end %>\r\n	    </tr>\r\n<% end %>\r\n		<tr>\r\n		  <td><center>O2 Supplement</center></td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:o2_supplement] != \'\' ? i[:o2_supplement][0,3].upcase : \'-\' %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td><center>Flow (LPM)</center></td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:flow] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td width=\"50px\">HR</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:hr] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>EKG</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:ekg] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>BP</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= \"\\\\#{i[:sbp]} / \\\\#{i[:dbp]}\" %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>SpO2</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:spo2] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>RR</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:rr] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>BT</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:bt] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>1. V/S Score</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:vs_score] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>2. SpO<sub>2</sub> Score</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:spo2_score] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>3. ความรู้สึกตัว</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:feeling] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>4. การหายใจ</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:breathing] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>5. การขยับแขนขา</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:movement] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>6. คลื่นไส้อาเจียน</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:nausea_and_vomiting] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>7. ความปวด / Pain Score</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= \"\\\\#{i[:pain]} / \\\\#{i[:pain_score]}\" %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>8. การเสียเลือด</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:bleeding] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>9. การลุกนั่ง</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center><%= i[:sit_up] %></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td style=\"background: lightgray;\"><b><center>Total Score</center></b></td>\r\n<% pacu.each_with_index do |v, i| %>\r\n		  <td style=\"background: lightgray;\"><center><b><%= ts[i].sum %></b></center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>Fluid</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center>-</center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>Urine (color)</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center>-</center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>Urine (amount)</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center>-</center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n		<tr>\r\n		  <td>Drain</td>\r\n<% pacu.each do |i| %>\r\n		  <td><center>-</center></td>\r\n<% end %>\r\n		  <!--<td>&nbsp;</td>-->\r\n		</tr>\r\n	  </tbody>\r\n	</table>\r\n</div>\r\n<script>\r\n    // $(\'#modal\').hide();\r\n    // $(\'#modal\').modal({\r\n    //         show: false, \r\n    //         backdrop: \'static\',\r\n    //         keyboard: true\r\n    //     });\r\n    \r\n    $(\'#modal\').hide();\r\n    $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n    // $(\'#o2-supplement-data\').text($(\'#data-o2_supplement\').val());\r\n    // $(\'#data-pacu_record\').val(\'<%= rec[:pacu_record].to_json.html_safe %>\');\r\n    // console.log(\"pacu_record : \" + \'<%= rec[:pacu_record].to_json.html_safe %>\')\r\n    \r\n    function pacu_delete(id) {\r\n        \r\n    }\r\n</script>',NULL,NULL,NULL,'2016-02-11 06:26:24','2016-02-11 06:26:24','pacu_content','*'),(2095,'layout2',885,4,'<html>\r\n<head>\r\n<title>Clinic system : <%=@current_service%></title>\r\n<%=include_header%>\r\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n<style>\r\n.w-box-header {\r\n    background: -webkit-linear-gradient(top, #fbfbfb 0%,#D8D8D8 100%);\r\n}\r\nspan.k-timepicker, span.k-datetimepicker, span.k-datepicker {\r\n    \r\n    padding-bottom: 10px;\r\n}\r\nbody {\r\n    background: url(\"https://kmnci.emr-life.com/esm/kmnci/www/assets/2.jpg\");\r\n    background-repeat: no-repeat;\r\n    background-attachment: fixed;\r\n    -webkit-background-size: cover;\r\n    -moz-background-size: cover;\r\n    -o-background-size: cover;\r\n    background-size: cover;\r\n    \r\n}\r\n\r\n.pull-right {margin-top: 5px;}\r\n#cssmenu {\r\n\r\n  line-height: 15px;\r\n  text-transform: uppercase;\r\n  text-align: left;\r\n}\r\n#cssmenu > ul {\r\n  width: auto;\r\n  list-style-type: none;\r\n  padding: 0;\r\n  margin: 0;\r\n  background: #F7F7F7;\r\n  border: 1px solid #ece6e8;\r\n  border-bottom: 3px solid #d9ced2;\r\n  -webkit-border-radius: 2px;\r\n  -moz-border-radius: 2px;\r\n  -o-border-radius: 2px;\r\n  border-radius: 2px;\r\n}\r\n#cssmenu > ul li#responsive-tab {\r\n  display: none;\r\n  /* Hide for large screens */\r\n\r\n}\r\n#cssmenu > ul li {\r\n  display: inline-block;\r\n  zoom: 1;\r\n}\r\n#cssmenu > ul li.right {\r\n  float: right;\r\n}\r\n#cssmenu > ul li.has-sub {\r\n  position: relative;\r\n}\r\n#cssmenu > ul li.has-sub:hover ul {\r\n  display: block;\r\n}\r\n#cssmenu > ul li.has-sub ul {\r\n  display: none;\r\n  width: 250px;\r\n  position: absolute;\r\n  margin: 0;\r\n  padding: 0;\r\n  list-style-type: none;\r\n  background: #ffffff;\r\n  border: 1px solid #ece6e8;\r\n  border-bottom: 3px solid #d9ced2;\r\n  border-top: 0 none;\r\n}\r\n#cssmenu > ul li.has-sub ul li {\r\n  display: block;\r\n}\r\n#cssmenu > ul li.has-sub > a {\r\n\r\n  background-repeat: no-repeat;\r\n  background-position: 90% -95%;\r\n}\r\n#cssmenu > ul li.has-sub > a.active,\r\n#cssmenu > ul li.has-sub > a:hover {\r\n\r\n  background-position: 90% 195%;\r\n}\r\n#cssmenu > ul li a {\r\n  display: block;\r\n  padding: 12px 24px 11px 24px;\r\n  text-decoration: none;\r\n  color: #747474;\r\n  text-shadow: 0px 1px 0px #fff;\r\n}\r\n#cssmenu > ul li a.active,\r\n#cssmenu > ul li a:hover {\r\n  background: #0A7E03;\r\n  color: #fff;\r\n  text-shadow: 0px 1px 0px #000;\r\n}\r\n\r\n}\r\n\r\n\r\ninput, textarea, select, .uneditable-input {height:24px;}\r\ninput { height:24px;}\r\ntable { font-size:100%;}\r\n@media print {\r\n.noshowprint { display:none;}\r\n}\r\n</style>\r\n\r\n<script src=\"/gebo/js/gebo_common.js\"></script>\r\n</head>\r\n<body style=\" max-width:1280px;min-width:720px; margin-left:auto; margin-right:auto; \r\nbackground-size: cover;\">\r\n\r\n\r\n	<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n\r\n<a href=\"../clinic_master/qsmi/Home/index\" style=\"float:left\"><h1><%=title%></h1></a>\r\n<div style=\"float:right; margin:10px\">\r\n<% if  @current_user %>\r\n<a class=\"btn btn-mini\" href=\"#\"><i class=\"splashy-lock_large_locked\"></i> <%=@current_user.login %> (<%=@current_role%>)</a>\r\n<a class=\"btn btn-mini\" href=\"<%=url_for \'../Home/user_logout\'%>\"><i class=\"splashy-lock_large_unlocked\"></i> Logout </a>\r\n<% else %>\r\n<a class=\"btn btn-mini\" href=\"/user/login\"><i class=\"splashy-lock_large_locked\"></i> Login </a>\r\n<% end %>\r\n    \r\n</div>\r\n<div style=\"margin-top:5px;margin-bottom:5px;\">\r\n<div id=\'cssmenu\'>\r\n<ul>\r\n   <li class=\'active\'><a href=\'../Home/index\'><i class=\"splashy-star_boxed_full\"></i> <span>Home</span></a></li>\r\n   <li ><a href=\'../../www/Patient/index\'><i class=\"splashy-contact_blue\"></i> <span>Patient</span></a>\r\n  \r\n   </li>\r\n   <li class=\'has-sub\'><a href=\'../Home/stations\'><i class=\"splashy-marker_rounded_light_blue\"></i> <span>Station</span></a>\r\n    </li>\r\n    <li class=\'has-sub\'><a href=\'#\'><i class=\"splashy-calendar_month\"></i> <span>Reports</span></a>\r\n    </li>\r\n  \r\n\r\n</ul>\r\n</div>\r\n</div>\r\n\r\n</hr>\r\n<div class=\"w-box-content cnt_a\" style=\"background:#fff; padding-bottom:20px\">\r\n\r\n<%=yield :content %>\r\n</div>\r\n<div class=\"well noshowprint\" style=\"border-top:#CCC 1px solid; padding:10px\">\r\nQSMI Clinic system\r\n<span style=\"float:right\">\r\nUser : <%=@current_user.login if @current_user %>, \r\nStation : All\r\n </span>\r\n    \r\n</div>\r\n<script>\r\n\r\n\r\n// Cache the elements we\'ll need\r\nvar menu = $(\'#cssmenu\');\r\nvar menuList = menu.find(\'ul:first\');\r\nvar listItems = menu.find(\'li\').not(\'#responsive-tab\');\r\n\r\n// Create responsive trigger\r\nmenuList.prepend(\'<li id=\"responsive-tab\"><a href=\"#\">Menu</a></li>\');\r\n\r\n// Toggle menu visibility\r\nmenu.on(\'click\', \'#responsive-tab\', function(){\r\n	listItems.slideToggle(\'fast\');\r\n	listItems.addClass(\'collapsed\');\r\n});\r\n\r\nrefresh_remote();\r\n</script>\r\n</body>\r\n\r\n</html>\r\n',NULL,NULL,NULL,'2016-02-11 07:58:11','2016-02-11 07:58:11','layout2',''),(2096,'index_partial',885,3,'\r\n<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n \r\n @current_station = nil\r\n \r\n\r\n \r\n if session[:current_station]\r\n    @current_station = session[:current_station] \r\n else\r\n    @station = get_model[:station].first\r\n    if @station\r\n        session[:current_station] = @station.id\r\n        @current_station = session[:current_station]\r\n    end\r\n    \r\n end\r\n \r\n \r\n%>\r\n\r\n<script>\r\n    function change_station(station){\r\n        window.location = \"../Home/index?station=\"+station\r\n    }    \r\n</script>\r\n\r\n<% \r\n\r\n    @config = this.clinic_config_template\r\n\r\n    @clinic_config = @config.merge this.clinic_config \r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    \r\n      \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n    @workflow = nil\r\n    \r\n    @current_station = models[:station].find(@current_station)\r\n    \r\n    if @current_station\r\n        @current_workflow = models[:workflow].where(:name=>@current_station.workflow).first\r\n    end\r\n\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n\r\n<div class=\"row-fluid alert-info\" style=\"border:0px solid\" >\r\n              \r\n\r\n\r\n<div class=\"span4\" style=\"border:0px solid;padding:10px\">\r\n\r\n<form action=\"../Home/search\" class=\"input-append\" method=\"post\">\r\n<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:30px\" size=\"16\" type=\"text\" placeholder=\"Search...\">\r\n<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n<a href=\"../Appointment/create?return=../Home/index\" class=\"btn\"> <img src=\"/gebo/img/gCons/agent.png\" width=\"20\"alt=\"\" /> New patient</a>\r\n\r\n</form>\r\n\r\n\r\n    \r\n</div>\r\n\r\n\r\n<div class=\"span4\" style=\"padding:5px\">\r\n\r\n<center><h1><%= @current_workflow.name.humanize %></h1></center>\r\n\r\n</div>\r\n\r\n<%\r\n    \r\n    \r\n    \r\n    workflow = @clinic_config[:workflow]\r\n    workflows = workflow.collect{|i| [i[:name].humanize,i[:name]] }\r\n    stations = models[:station].all\r\n    station_map = {}\r\n    stations_list = stations.collect{|i| station_map[i.id] = i ; [i.name,i.id] }\r\n    \r\n    \r\n%>\r\n<%# @current_station %>\r\n<div class=\"span4\" style=\"padding:10px\">\r\nStation : <%= select_tag :station, options_for_select(stations_list, @current_station.id),:style=>\'width:150px\',:id=>\'status_update\' %>\r\n\r\n\r\n<%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n%>\r\n<%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> \r\n</div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n	\r\n	$(\'#search-field\').focus();\r\n	\r\n</script>\r\n\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n</span>\r\n\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\n$(document).ready(function(){\r\n\r\n$(\'#status_update\').change(function(){\r\n//   if(confirm(\"Are you sure to update status?\")){\r\n    value = $(\'#status_update\').val();  \r\n    window.location = \"../Home/index?station=\"+value;\r\n//   }\r\n });\r\n\r\n});\r\n\r\n\r\n    \r\n</script>\r\n\r\n\r\n<%\r\n\r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n     def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    aps = ap_model.sort({updated_at:1}).all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    \r\n    \r\n    \r\n    \r\n    pms = module_model.collection.find(:module_id=>{\'$in\'=>aps.collect{|i|i.id}}).to_a\r\n    pms_map = bmap pms, \'module_id\'\r\n    \r\n    patients = patient_model.collection.find(:_id=>{\'$in\'=>pms.collect{|i|i[\'patient_id\']}}).to_a\r\n    patients_map = bmap patients\r\n    \r\n    \r\n        \r\n    procs = models[:procedure].collection.find().to_a\r\n    proc_map = bmap procs, \'_id\'\r\n    \r\n    \r\n status_list = %w{appointed}\r\n  \r\n    aps_list = aps.collect{|i| \r\n    \r\n    r = i.attributes\r\n    \r\n    pm = pms_map[i.id]\r\n    begin  \r\n    if pm and p = patients_map[pm[0][\'patient_id\']][0]\r\n    \r\n    \r\n    r[\'name\']=\"\\\\#{p[\'prefix_name\']} \\\\#{p[\'first_name\']} \\\\#{p[\'last_name\']}\"\r\n    \r\n    r[\'hn\']=p[\'hn\'] \r\n    r[\'hn\']=p[\'public_id\']+\"(pid)\" if p[\'hn\'] == nil\r\n    \r\n    unless proc_map[r[\'procedure\']]\r\n    r[\'hn\']=p[\'id\']\r\n    end\r\n     \r\n    \r\n    \r\n    r[\'procedure\'] =proc_map[r[\'procedure\']][0][\'name\'] if proc_map[r[\'procedure\']]\r\n\r\n \r\n        \r\n    c = {:status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         \'pending_ctrl\'=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\')\r\n    }\r\n    \r\n    s = station_map[i.station_id]\r\n    c[:station] = \'-\'\r\n    \r\n    c[:station] = s.name if s\r\n    \r\n    c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')\r\n    \r\n    to_status = nil\r\n    if  @current_workflow  \r\n    \r\n    to_status =  @current_workflow .out_bound_status    \r\n        \r\n    c[:pending_ctrl]+=link_to(to_status.humanize,\"update_status?id=\\\\#{i.id}&status=\\\\#{to_status}\",:class=>\'btn btn-small btn-success\',:disabled_with=>\'Loading\') \r\n\r\n    end\r\n    \r\n    \r\n    \r\n    r.merge! c\r\n    \r\n  \r\n\r\n    \r\n        \r\n    end\r\n    \r\n    \r\n    \r\n    r\r\n    rescue\r\n    \r\n    i.destroy\r\n    \r\n    \r\n    end\r\n    \r\n    }.compact\r\n    \r\n \r\n%>\r\n\r\n\r\n\r\n<%# link_to \'+Visit\', \'../Appointment/create\' %>\r\n\r\n<%\r\n  processing_status = [\'appointed\']\r\n  calling_status = []\r\n  waiting_status = []\r\n  complete_status = []\r\n  \r\n  if @current_workflow\r\n    \r\n    processing_status = @current_workflow.processing_status.split(\",\") if @current_workflow.processing_status\r\n    calling_status = @current_workflow.calling_status.split(\",\") if @current_workflow.calling_status\r\n    waiting_status = @current_workflow.in_bound_status.split(\",\") if @current_workflow.in_bound_status\r\n    complete_status = @current_workflow.out_bound_status.split(\",\") if @current_workflow.out_bound_status\r\n  \r\n  \r\n  end\r\n  \r\n    aps = []\r\n    aps += aps_list.collect{|i| i if processing_status.index(i[:status].downcase) }.compact\r\n    aps += aps_list.collect{|i| i if calling_status.index(i[:status].downcase) }.compact\r\n    \r\n    other_processing = [] \r\n    \r\n    if true\r\n     \r\n       aps.collect!{|i| \r\n        if   i[:station] == \'-\' or i[:station] == \'\' or i[:station] == @current_station.name \r\n            i \r\n        else\r\n            other_processing << i\r\n            nil\r\n        end\r\n        }.compact! \r\n        \r\n    end\r\n\r\n%>\r\n<div class=\"row-fluid\">&nbsp;</div>\r\n<div class=\"alert alert-success \">\r\n<div>\r\n    <span style=\"float:right\">\r\n        <%=link_to \'Next Queue\', \"next_queue?update=index_panel\", :remote=>true, :class=>\'btn btn-success\' %>\r\n    </span>\r\n    \r\n</div>\r\n<h3>Processing & Calling</h3><%# processing_status.inspect %>\r\n<%= tabular :data=>aps, :model=>%w{queue_number hn name station procedure  pending_ctrl} do|row,out|\r\n\r\nout\r\nend%>\r\n<%=\"other station : \\\\#{other_processing.size}\" if other_processing.size > 0 %>\r\n</div>\r\n\r\n<%\r\n    aps = aps_list.collect{|i| i if  waiting_status.index(i[:status].downcase) }.compact\r\n%><div class=\"alert  \">\r\n<h3>Waiting</h3>\r\n<%= tabular :data=>aps, :model=>%w{queue_number hn name station procedure pending_ctrl} do|row,out|\r\n\r\nout\r\nend%>\r\n</div>\r\n\r\n<%\r\n    aps = aps_list.collect{|i| i if complete_status.index(i[:status].downcase) }.compact\r\n%><div class=\"well \">\r\n<h3>Recently completed</h3>\r\n<%= tabular :data=>aps, :model=>%w{queue_number hn name station procedure pending_ctrl} do|row,out|\r\nout[-1] = \"-\"\r\nout\r\nend%>\r\n</div>\r\n<hr />\r\n<%# aps.inspect %>\r\n<br/>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<script>\r\n    refresh_remote()\r\n</script>\r\n<% Time.now %>\r\n\r\n',NULL,NULL,NULL,'2016-02-11 08:04:57','2016-02-11 08:04:57','index_partial',''),(2097,'test',882,3,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'../Home/index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    record = get_model[this.table_name.to_sym]\r\n%>\r\n<%= record.all.count %>',NULL,NULL,NULL,'2016-02-11 15:21:49','2016-02-11 15:21:49','test',''),(2098,'patient_record',885,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<script>\r\n\r\n</script>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n.text-tab{font-size:1.4em;}\r\n</style>\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                Patient Records\r\n                <div class=\"pull-right\">\r\n                    <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n                </div> \r\n            </div>  \r\n            \r\n            <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n                ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n                ehr_models = ehr.get_model\r\n                patient_model = ehr_models[:patient]\r\n                patient_module_model = ehr_models[:patient_module]\r\n                \r\n                emr_models = get_model\r\n                ap = emr_models[:appointment].find(params[:id])\r\n                pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n                locker_model = emr_models[:locker]\r\n                if params[:reset_lock]\r\n                    l = locker_model.find(params[:reset_lock])\r\n                    l.destroy if l\r\n                end\r\n                #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n                #i.destroy if i\r\n                #end\r\n                procedure  = emr_models[:procedure].find(ap.procedure)\r\n                current_procedure = nil\r\n                current_procedure = procedure.code if procedure\r\n                \r\n                \r\n                if pm\r\n                \r\n                if  params[:schema_patient_module]\r\n                   pm.update_attributes params[:schema_patient_module]\r\n                end\r\n                \r\n                if params[:provider_id]\r\n                  ap.update_attributes :provider=>params[:provider_id]\r\n                   ap = emr_models[:appointment].find(params[:id])\r\n                 end\r\n                \r\n                # find provider\r\n                provider = emr_models[:provider].find(ap.provider.to_s)\r\n                \r\n                # find patient\r\n                patient = patient_model.find(pm.patient_id)\r\n                \r\n                params[:patient]=patient\r\n                params[:patient_module]=pm\r\n                \r\n               # s = Service.get(\'ehr.emr.EmrHelper\')\r\n            #    obj = s.load context\r\n                \r\n                providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n                \r\n                workflows = emr_models[:workflow].where(:sort_order=>{\'$ne\'=>nil}).sort(:sort_order).all\r\n                groups = []\r\n                \r\n                for i in workflows\r\n                    \r\n                    \r\n                    \r\n                    if i.default_documents!=\"\" and i.sort_order<=@current_workflow.sort_order\r\n                       \r\n                        list = []\r\n                        if i.list_documents and i.list_documents !=\"\"\r\n                            \r\n                            list = i.list_documents.split(\",\").collect{|j| j.strip} \r\n                        else\r\n                            list << i.default_documents\r\n                        end\r\n                       \r\n                       groups<<{:name=>i.name, :doc=>i.default_documents, :list=>list}\r\n                        \r\n                    end\r\n                \r\n                end\r\n                \r\n                if @current_station and ap and @current_workflow\r\n                   \r\n                    if ap.station_id == nil or ap.status.strip == @current_workflow.calling_status.strip\r\n                        \r\n                        ap.update_attributes :station_id=>@current_station.id, :status=>@current_workflow.processing_status\r\n                        \r\n                    end\r\n                    \r\n                end\r\n                 ap.update_attributes :station_id=>@current_station.id\r\n                \r\n                docs = @current_workflow.list_documents.split(\",\").collect{|i|i.strip} if @current_workflow.list_documents and @current_workflow.list_documents!=\'\'\r\n                \r\n                services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact \r\n                \r\n                \r\n                %>\r\n                \r\n\r\n                <div style=\"border:0px solid\">\r\n                \r\n                    <div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;\">\r\n<%# render :inline=>obj.show_patient %>\r\n                        <div id=\"patient\">\r\n                            <center>loading...</center>\r\n                        </div>\r\n                    \r\n                    \r\n                        <div class=\"span12\" style=\"margin-left:0px;\">\r\n<!--############################################################################################################## Tab first -->						\r\n                            <div class=\"tabbable tabbable-bordered\">\r\n    	                    <%#groups.inspect %>\r\n    	                        <ul class=\"nav nav-tabs\">\r\n    	\r\n                        	<% for g in groups \r\n                        	\r\n                        	    active = \'\'\r\n                        	    active = \'active\' if  @current_workflow.name == g[:name]\r\n                        	    group_title = g[:name].humanize\r\n                        	   # group_title = g[:list][0].humanize if g[:list].size==1 and g[:list][0]\r\n                        	    \r\n                            	%>\r\n    		                <li class=\"<%=active%>\"> <a href=\"#tab_g<%=g[:name]%>\" data-toggle=\"tab\"><span class=\"text-tab\"><%=group_title%></span></a></li>\r\n\r\n                             <% end %>\r\n    	                        </ul>\r\n    	\r\n    	                    \r\n    	                    <div class=\"tab-content\" style=\"padding:5px\">\r\n    	                    \r\n    	                    \r\n                        	<% \r\n                        	\r\n                        	\r\n                        	\r\n                        	\r\n                        	for g in groups \r\n                        	        active = \'\'\r\n                            	    active = \'active\' if  @current_workflow.name == g[:name]\r\n                                \r\n                                    # if @current_workflow.default_documents.split(\",\").size>1\r\n                            	        if g[:name]==\'diagnosis\'\r\n                                	        g[:list].collect!{|i|\r\n                                	        \r\n                                	        i if i==current_procedure or i==\'prescription\'\r\n                                	        \r\n                                	        }.compact!\r\n                                	    end\r\n                            	        \r\n                            	   # end\r\n                        \r\n                        \r\n                        	%>\r\n                        	<div class=\"tab-pane <%=active%>\" id=\"tab_g<%=g[:name]%>\" ><%#g.inspect %><%#current_procedure%>\r\n    	                        \r\n                            <% if g[:list].size>1 %>   <!--#################################################################### multiple forms -->\r\n                            \r\n                            <div class=\"tabbable tabbable-bordered\">\r\n                            <ul class=\"nav nav-tabs\">\r\n                            	<%  g[:list].each_with_index do |i,index|  \r\n                            	    active = \'\'\r\n                            	    active = \'active\' if  @current_workflow.default_documents.index(i) or index==0\r\n                            	%>\r\n                            	<li class=\"<%=active%>\">\r\n                            	<a href=\"#tab_f<%=i%>\" data-toggle=\"tab\">\r\n                            	<span class=\"text-tab\"><%=i.humanize%></span>\r\n                            	</a>\r\n                            	</li>\r\n                            	<% end %>\r\n                            </ul>\r\n                            \r\n                            <div class=\"tab-content\">\r\n                            	    \r\n                                    <%  \r\n                                    \r\n                                        \r\n                                    \r\n                                        g[:list].each_with_index do |i,index|  \r\n                                        active = \'\'\r\n                            	        active = \'active\' if  @current_workflow.default_documents.index(i) or index==0\r\n                            	        \r\n                            	   \r\n                            	        \r\n                                    %>  	 \r\n    	 	                            <div class=\"tab-pane <%=active%>\" id=\"tab_f<%=i%>\"> \r\n        	                                <div id=\"panel-<%=i%>\" >\r\n                                                <%\r\n                                                    \r\n                                                    url = \"\"\r\n                                                    opx = nil\r\n                                                    exist_document = false\r\n                                                    \r\n                                                    if doc = @current_project.get_document(i)  \r\n                                                        \r\n                                                        url = \"../\\\\#{i.camelize}/create\"\r\n                                                        \r\n                                                        # opx = patient_module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{i}\",:parent_id=>pm.id).first\r\n                                                             \r\n                                                        \r\n                                                        if i==\'appointment\'\r\n                                                        opx = patient_module_model.find pm.id\r\n                                                        else    \r\n                                                        opx = patient_module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{i}\",:parent_id=>pm.id).first\r\n                                                        end     \r\n                                                                                                        \r\n                                                        return_url = \".\"\r\n                                                        unless opx\r\n                                                            url = \"../\\\\#{i.camelize}/create_partial?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{return_url}\"\r\n                                                        else\r\n                                                            # if @current_workflow.default_documents.index(i)\r\n                                                            # url = \"../\\\\#{i.camelize}/edit_partial?id=\\\\#{opx.id}\"\r\n                                                            # else\r\n                                                            url = \"../\\\\#{i.camelize}/show_partial?id=\\\\#{opx.id}\"\r\n                                                            \r\n                                                            # end\r\n                                                        end\r\n                                                        \r\n                                                        \r\n                                                        exist_document = true\r\n                                                    else\r\n                                                    \r\n                                                        if i==\'patient\'\r\n                                                           \r\n                                                           url= \"../Home/patient_partial?id=\\\\#{patient.id}\"\r\n                                                           exist_document = true\r\n                                                        end\r\n                                                    \r\n                                                    end\r\n                                                \r\n                                                %>Load ..\r\n            \r\n                                            </div>\r\n                                            <% if  exist_document %>\r\n\r\n                                                <script>\r\n                                                \r\n                                                    $.ajax({\r\n                                                	  url: \'<%=url.html_safe%>\',\r\n                                            		 success: function(data){\r\n                                            		     console.log(data)\r\n                                            		  //   alert(data)\r\n                                                      $(\'#panel-<%=i%>\').html(data);  \r\n                                                    //   refresh_remote();\r\n                                            		  }\r\n                                            		});\r\n                                                        \r\n                                                </script>\r\n        	                                <% end %>\r\n    	 	                            </div> <!-- inner tab pane -->\r\n                                        <% end %>\r\n    	                            </div> <!-- inner tab content -->\r\n                            	</div> <!-- inner tabbable -->\r\n    \r\n                                 <% else %> <!-- form size < 1 -->\r\n                                    \r\n                              \r\n        <%\r\n            \r\n            url = \"\"\r\n            exist_document = false\r\n            \r\n            if doc = @current_project.get_document(g[:doc])  \r\n                \r\n                url = \"../\\\\#{g[:doc].camelize}/create_partial\"\r\n                i = g[:doc]\r\n                \r\n                if i==\'appointment\'\r\n                opx = patient_module_model.find pm.id\r\n                else    \r\n                opx = patient_module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{g[:doc]}\",:parent_id=>pm.id).first\r\n                end\r\n\r\n                return_url = \".\"\r\n                                                        \r\n                unless opx\r\n                    url = \"../\\\\#{i.camelize}/create_partial?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{return_url}\"\r\n                else\r\n                    url = \"../\\\\#{i.camelize}/show_partial?id=\\\\#{opx.id}\"\r\n                end\r\n                                        \r\n                \r\n                exist_document = true\r\n            end\r\n        \r\n        %>  <%#pm.inspect%>\r\n        <%#opx.inspect %>\r\n        <div id=\"panel-<%=g[:doc]%>\" >\r\n        Load .. <%=g[:name]%>\r\n                <%# @current_project.get_instance.inspect %>\r\n\r\n\r\n                                 </div>\r\n                                    <% if exist_document %>\r\n                                       <%#url%>\r\n                                       <script>\r\n                                    \r\n                                    $.ajax({\r\n                                	  url: \'<%=url.html_safe%>\',\r\n                            		 success: function(data){\r\n                            		   \r\n                            		  //   alert(data)\r\n                                      $(\'#panel-<%=g[:doc]%>\').html(data);\r\n                                        refresh_remote();\r\n                                      \r\n                            		  }\r\n                            		});\r\n                                        \r\n                                    </script>\r\n                                	<% end %> <!-- if ex doc -->\r\n                            <% end %>	<!-- form size > 1-->\r\n\r\n    		</div> <!-- close outter tabpan-->\r\n    		\r\n    <% end %> <!-- outer group-->\r\n\r\n    \r\n            &nbsp;\r\n        </div>\r\n        \r\n    </div>\r\n    \r\n</div>\r\n<%#ap.inspect %>\r\n\r\n<% else %>\r\nData missing\r\n<% end %>\r\n\r\n</div>\r\n\r\n         <div class=\"clear\"></div>\r\n\r\n   \r\n</div>\r\n\r\n        <div class=\"clear\"></div>\r\n\r\n \r\n</div>\r\n\r\n    \r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n%>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n\r\n<script>\r\n$(\'title\').html(\'สถานเสาวภา : <%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2016-02-11 16:14:22','2016-02-11 16:14:22','patient_record',''),(2099,'document_name',891,1,'\'form_test\'',NULL,NULL,NULL,'2016-02-11 16:32:14','2016-02-11 16:32:14',NULL,NULL),(2100,'sumgroup',882,1,'{\r\n	:total_score_update => {\r\n		:select => [:vs_score, :spo2_score, :feeling, :breathing, :movement, :nausea_and_vomiting, :bleeding, :sit_up, :pain],\r\n		:total => :total_score\r\n	}\r\n}',NULL,NULL,NULL,'2016-02-11 17:02:02','2016-02-11 17:02:02','sumgroup',''),(2101,'status_appointment',502,3,'<%\r\n    res = {}\r\n    nurse = false\r\n    \r\n    if frm = params[:frm]\r\n        r_app = get_model[:appointment].find(frm[:aid])\r\n        # res[:app] = r_app\r\n        # res[:room] = frm[:room]\r\n        # res[:status] = frm[:status]\r\n        update = {:status=>frm[:status]}\r\n        if frm[:room] != \'-\'\r\n            update[:room] = frm[:room]\r\n        end\r\n        res[:update] = update\r\n        r_app.update_attributes update\r\n        \r\n        if frm[:ref] == \'nurse\'\r\n            nurse = true\r\n        end\r\n    else\r\n        res[:return] = \'xxx\'\r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<script>\r\n    $(\'#modal\').hide();\r\n    $(\".modal-backdrop\").hide(\'fade\');\r\n    <% if nurse %>\r\n    feed_page(200);\r\n    <% end %>\r\n</script>',NULL,NULL,NULL,'2016-02-23 04:26:22','2016-02-23 04:26:22','status_appointment',''),(2102,'nbi_report',522,3,'\r\n\r\n<%\r\n    models = get_model\r\n    \r\n    providers = models[:provider].all.collect{|i| [i.name,i.id] }\r\n    m_attachment = models[:attachment]\r\n    provider = nil\r\n    provider_id = nil\r\n    if params[:query]\r\n        provider = models[:provider].find(params[:query][:provider])\r\n        provider_id = provider.id\r\n    end\r\n        \r\n    \r\n%>\r\n\r\n<%= form_for :query do |f| %>\r\n<%= f.select :provider, options_for_select(providers, provider_id )%>\r\n<%= f.submit \'Submit\' %>\r\n<% end %>\r\n\r\n<% if request.post? \r\n        \r\n    records = models[:colonoscopy_scope].collection.find({},{:fields=>{\'endoscopy_dx\'=>1,\'abnormal_type\'=>1,\'morphology_type\'=>1,\'image\'=>1}}).to_a\r\n    records = records[-1000..-1]\r\n%>\r\n<% %>\r\n<table>\r\n\r\n<%\r\n  map_atts = {}\r\n  atts = m_attachment.find(records.collect{|j| j[\'image\']  })\r\n  for i in atts\r\n    map_atts[i.id] = i\r\n  end\r\n\r\n  for i in records\r\n  atts = m_attachment.find(i[\'image\'])\r\n  \r\n  atts = atts.collect!{|a| image_tag(map_atts[a.id].path)   }.join  if atts\r\n  \r\n%>\r\n<tr>\r\n<td><%=i[\'endoscopy_dx\'] %></td><td><%=i[\'abnormal_type\'] %></td><td><%=i[\'morphology_type\'] %></td>\r\n<td>\r\n    \r\n    <%=atts.html_safe  if atts %>\r\n</td>\r\n    \r\n</tr>\r\n<% end %>\r\n</table>\r\n\r\n<% end%>',NULL,NULL,NULL,'2016-02-29 01:35:30','2016-02-29 01:40:29','',''),(2105,'zam',477,3,'<%\r\n    rid = %w{1	2	3	4	5	6	7	9	11	12	13	14	15	16	17	19	21	23	26	27}\r\n    rid.each do |i|\r\n%>\r\n<a href=\'https://rrts_<%=i%>.emr-life.com/www/Patient/export_check\' target=\'_blank\'>RRT_<%=i%></a><br/>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2016-03-03 03:30:14','2016-03-03 03:30:14','zam','*'),(2106,'setting',856,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"well \">Account setting<br />\r\n<ul>\r\n    <li>1. User profile</li>\r\n    <li>2. My account</li>\r\n    <li>3. admin mote</li>\r\n    <li>4. User control</li>\r\n    <li>5. Database backup</li>\r\n    <li>6. How to</li>\r\n</ul>\r\n\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-03-03 06:24:59','2016-03-03 06:24:59','setting',''),(2107,'form',333,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    \r\n    \r\n    $(\'.ctrl\').hide();\r\n    \r\n    \r\n</script>\r\n<style>\r\n    #room {display:none;}\r\n</style>',NULL,NULL,NULL,'2016-03-03 13:52:17','2016-03-03 13:52:17','form',''),(2108,'day1_check',463,3,'<%\r\n    hosp_name = @current_solution.name\r\n    io = 24 \r\n    # tm = patient[:time_of_icu_admission].strftime(\'%H\').to_i\r\n    tm_00 = [\"rrts_14\", \"rrts_21\"];\r\n    tm_06 = [\"rrts_1\", \"rrts_3\", \"rrts_4\", \"rrts_7\", \"rrts_9\", \"rrts_19\", \"rrts_23\", \"rrts_26\", \"rrts_27\"];\r\n    tm_07 = [\"rrts_6\", \"rrts_17\"];\r\n    tm_22 = [\"rrts_5\"];\r\n    tm_23 = [\"rrts_2\", \"rrts_11\", \"rrts_12\", \"rrts_13\", \"rrts_15\", \"rrts_16\"];\r\n        \r\n    if !tm_00.index(hosp_name).nil?\r\n        io = 0\r\n    elsif !tm_06.index(hosp_name).nil?\r\n        io = 6\r\n    elsif !tm_07.index(hosp_name).nil?\r\n        io = 7\r\n    elsif !tm_22.index(hosp_name).nil?\r\n        io = 22\r\n    elsif !tm_23.index(hosp_name).nil?\r\n        io = 23\r\n    end\r\n    \r\n    a_case = get_model[this.table_name.to_sym].where(:record_day=>\'1\').all\r\n    i_case = {}\r\n    a_case.each do |i|\r\n        i_case[i.id] = i\r\n    end\r\n    \r\n    # @module_name = @current_project.name+\'#\'+ this.table_name \r\n    # @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    # @patient_doc = @ehr_project.get_document \'patient\'\r\n    # @module_doc = @ehr_project.get_document \'patient_module\'\r\n    # @ehr_model = @ehr_project.get_model()\r\n    # @patient_model = @ehr_model[:patient]\r\n    # @module_model = @ehr_model[:patient_module]\r\n    \r\n    rs = []\r\n    \r\n    mname = @current_project.name + \'#\' + this.table_name\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    pat_mod = ehr.get_model[:patient_module]\r\n    pid_case = {}\r\n    pat_case = pat_mod.where(:module_name=>mname, :module_id=>i_case.keys)\r\n    pat_case.each do |i|\r\n        pid_case[i[:patient_id]] = i_case[i[:module_id]]\r\n    end\r\n    xx = {}\r\n    a_pat = ehr.get_model[:patient]\r\n    a_pat.each do |i|\r\n        pat = i\r\n        cas = pid_case[pat.id]\r\n        xx[:pat] = pat\r\n        xx[:case] = cas\r\n        # break\r\n    end\r\n%>\r\n\r\n\r\n\r\n\r\n<%= stylesheet_link_tag \"application\"  %>\r\n<h3>Using I/O Cut at <%= io %>:00</h3>\r\n<%= pid_case.count.to_json.html_safe %> | <%= a_pat.count %> | <%= xx.to_json.html_safe %>\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n	    <th>Header</th>\r\n    </tr>\r\n    <tr>\r\n        <td>XXX</td>\r\n    </tr>\r\n</table>',NULL,NULL,NULL,'2016-03-03 16:48:12','2016-03-03 16:48:12','day1',''),(2109,'merge',480,3,'<% if false %>\r\n<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    \r\n    upd_pat = false\r\n    if params[:pat] == \'true\'\r\n        upd_pat = true\r\n    end\r\n    \r\n    upd_cas = false \r\n    if params[:cas] == \'true\'\r\n        upd_cas = true\r\n    end\r\n    \r\n    upd_aki = false\r\n    if params[:aki] == \'true\'\r\n        upd_aki = true\r\n    end\r\n    \r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    \r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = [] # all parent_id\r\n    pat_ids = [] # all patient_id\r\n    app_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    # begin\r\n    # a_pat = a_pat.sort_by{|i| i[:patient_order] if i[:patient_order]}\r\n    a_pat = a_pat.sort{|a,b| a[:patient_order] && b[:patient_order] ? a[:patient_order] <=> b[:patient_order] : a[:patient_order] ? -1 : 1 }\r\n    \r\n    # query patient_module <-> aki\r\n    mod_aki = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#aki\")\r\n    i_aki = []\r\n    p_aki = {}\r\n    mod_aki.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_aki << mid\r\n        if !p_aki.has_key? pid\r\n            p_aki[pid] = []\r\n        end\r\n        p_aki[pid] << mid\r\n    end\r\n    m_aki = {}\r\n    a_aki = get_model[:aki].find(i_aki)\r\n    a_aki.each do |i|\r\n        m_aki[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> case_record\r\n    mod_case = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#case_record\")\r\n    i_case = []\r\n    p_case = {}\r\n    mod_case.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_case << mid\r\n        if !p_case.has_key? pid\r\n            p_case[pid] = []\r\n        end\r\n        p_case[pid] << mid\r\n    end\r\n    m_case = {}\r\n    a_case = get_model[:case_record].find(i_case)\r\n    a_case.each do |i|\r\n        m_case[i.id] = i\r\n    end\r\n    \r\n    # selecting I/O\r\n    hosp_name = @current_solution.name\r\n    io = 24 \r\n    # tm = patient[:time_of_icu_admission].strftime(\'%H\').to_i\r\n    tm_00 = [\"rrts_14\", \"rrts_21\"];\r\n    tm_06 = [\"rrts_1\", \"rrts_3\", \"rrts_4\", \"rrts_7\", \"rrts_9\", \"rrts_19\", \"rrts_23\", \"rrts_26\", \"rrts_27\"];\r\n    tm_07 = [\"rrts_6\", \"rrts_17\"];\r\n    tm_22 = [\"rrts_5\"];\r\n    tm_23 = [\"rrts_2\", \"rrts_11\", \"rrts_12\", \"rrts_13\", \"rrts_15\", \"rrts_16\"];\r\n        \r\n    if !tm_00.index(hosp_name).nil?\r\n        io = 0\r\n    elsif !tm_06.index(hosp_name).nil?\r\n        io = 6\r\n    elsif !tm_07.index(hosp_name).nil?\r\n        io = 7\r\n    elsif !tm_22.index(hosp_name).nil?\r\n        io = 22\r\n    elsif !tm_23.index(hosp_name).nil?\r\n        io = 23\r\n    else\r\n        io = 6\r\n    end\r\n    \r\n    # processing\r\n    res = []\r\n    pf = %w{patient_number patient_order gender weight height ideal_body_weight age date_of_admission date_of_icu_admission time_of_icu_admission ckd esrd reference baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr first_available_cr_date}\r\n#	0	patient_number\r\n#	1	patient_order\r\n#	2	gender\r\n#	3	weight\r\n#	4	height\r\n#	5	ideal_body_weight\r\n#	6	age\r\n#	7	reference\r\n#	8	date_of_admission\r\n#	9	date_of_icu_admission\r\n#	10	time_of_icu_admission\r\n#	11	ckd\r\n#	12	esrd\r\n#	13	baseline_serum_creainine_by_mdrd\r\n#	14	available_baseline\r\n#	15	baseline_serum_cr\r\n#	16	date_of_baseline_serum_cr\r\n#	17	first_available_cr\r\n#	18	first_available_cr_date\r\n    dd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    cf = %w{urine_output_cal record_day case_status move_out_time creatinine urine_output24hr if_rrt}\r\n#	0	record_day\r\n#	1	case_status\r\n#	2	move_out_time\r\n#	3	creatinine\r\n#	4	urine_output24hr\r\n#	5	urine_output_cal\r\n#	6	if_rrt\r\n    af = %w{cr_diagnosis cr_diagnosis_from_day cr_staging cr_staging_from_day urine_output_diagnosis urine_output_from_day urine_output_staging urine_output_staging_from_day}\r\n#	0	cr_diagnosis\r\n#	1	cr_diagnosis_from_day\r\n#	2	cr_staging\r\n#	3	cr_staging_from_day\r\n#	4	urine_output_diagnosis\r\n#	5	urine_output_from_day\r\n#	6	urine_output_staging\r\n#	7	urine_output_staging_from_day\r\n\r\n    # using field\r\n    uf = {\r\n        \'1\'=>{:f=>:baseline_serum_cr,:d=>:date_of_baseline_serum_cr}, \r\n        \'2\'=>{:f=>:first_available_cr,:d=>:first_available_cr_date}, \r\n        \'3\'=>{:f=>:baseline_serum_creainine_by_mdrd,:d=>:date_of_icu_admission}\r\n    }\r\n    \r\n    # for each patient\r\n    a_pat.each do |pat|\r\n        tmp = {}\r\n        msg = []\r\n        if pat.nil?\r\n            next\r\n        end\r\n        \r\n        pp = {}\r\n        pf.each do |i|\r\n            pp[i.to_sym] = pat[i.to_sym]\r\n        end\r\n        \r\n        # recheck urine output from case_record\r\n        cid_list = []\r\n        if xx = p_case[pat.id]\r\n            xx.each do |i|\r\n                cid_list << m_case[i]\r\n            end\r\n        else\r\n            msg << \"xx found\"\r\n        end\r\n        \r\n        # mapping day <--> case_record\r\n        mc = {}\r\n        cid_list.each do |i|\r\n            rd = i[:record_day]\r\n            if rd==\'\'\r\n                msg << \'empty rd\'\r\n            end\r\n            if !mc.has_key? rd\r\n                mc[rd] = i\r\n            else\r\n                msg << \"dup rd[\\\\#{rd}]\"\r\n            end\r\n        end\r\n        \r\n        if pp[:height] != \'\'\r\n            if pp[:gender] == \'1\'\r\n                pp[:ideal_body_weight] = (pp[:height].to_i - 100)\r\n            else\r\n                pp[:ideal_body_weight] = (pp[:height].to_i - 105)\r\n            end\r\n        end\r\n        pp[:time_of_icu_admission] = pp[:time_of_icu_admission].strftime(\'%H:%M\')\r\n        ti = Time.parse(pp[:time_of_icu_admission])\r\n        \r\n        # finding the reference baseline cr\r\n            obj = pp[:date_of_baseline_serum_cr]\r\n            if obj.kind_of?(Date) || obj.kind_of?(Time)\r\n				if obj >= pp[:date_of_admission] and obj < pp[:date_of_icu_admission]\r\n				    fm = pp[:baseline_serum_creainine_by_mdrd].to_f\r\n				    fb = pp[:baseline_serum_cr].to_f\r\n				    \r\n				    pp[:first_available_cr] = pp[:baseline_serum_cr]\r\n				    pp[:first_available_cr_date] = obj\r\n				    pp[:baseline_serum_cr] = \'n/a\'\r\n				    pp[:date_of_baseline_serum_cr] = nil\r\n				        \r\n				    if pp[:ckd].downcase==\'yes\'\r\n				        pp[:reference] = \'3\'\r\n				        pp[:available_baseline] = \'2\'\r\n				        \r\n				        pp[:note] = \'CKD [green]\'\r\n				    else\r\n				        pp[:ckd] = \'No\'\r\n    				    if fm < fb\r\n    				    \r\n    				        pp[:reference] = \'2\'\r\n    				        pp[:available_baseline] = \'2\'\r\n    				        \r\n    				        pp[:note] = \'cond-1 [green]\'\r\n    				    else\r\n    				        pp[:reference] = \'3\'\r\n    				        pp[:available_baseline] = \'2\'\r\n    				        \r\n    				        pp[:note] = \'cond-2 [green]\'\r\n    				    end\r\n    				end\r\n				elsif obj >= pp[:date_of_admission] - 12.months and obj < pp[:date_of_admission]\r\n				    if pp[:ckd] == \'\'\r\n				        pp[:ckd] = \'No\'\r\n				    end\r\n				    pp[:reference] = \'1\'\r\n				    pp[:available_baseline] = \'1\'\r\n				    \r\n				    pp[:note] = \'cond-3 [red]\'\r\n				elsif obj >= pp[:date_of_icu_admission]\r\n				    fm = pp[:baseline_serum_creainine_by_mdrd].to_f\r\n				    fb = pp[:baseline_serum_cr].to_f\r\n				    \r\n				    pp[:first_available_cr] = pp[:baseline_serum_cr]\r\n				    pp[:baseline_serum_cr] = \'n/a\'\r\n				    pp[:date_of_baseline_serum_cr] = nil\r\n				    pp[:first_available_cr_date] = obj\r\n				    pp[:available_baseline] = \'2\'\r\n				    \r\n				    if pp[:ckd].downcase == \'yes\'\r\n				        pp[:reference] = \'3\'\r\n				        \r\n				        pp[:note] = \'CKD [orange]\'\r\n				    else\r\n				        pp[:ckd] = \'No\'\r\n    				    if fm < fb\r\n    				        pp[:reference] = \'2\'\r\n    				    else\r\n    				        pp[:reference] = \'3\'\r\n    				    end\r\n    				    \r\n    				    pp[:note] = \"cond-4 [orange] m:\\\\#{fm}|b:\\\\#{fb}\"\r\n    				end\r\n    			# compare with first cr available again\r\n				elsif obj < pp[:date_of_admission] - 12.months\r\n				    tmp = mc[\'1\']\r\n				    fb = tmp[:creatinine].to_f\r\n				    fm = pp[:baseline_serum_creainine_by_mdrd].to_f\r\n				    if pp[:ckd].downcase == \'yes\'\r\n				        pp[:reference] = \'3\'\r\n				        \r\n				        pp[:note] = \'CKD [orange]\'\r\n				    else\r\n				        pp[:ckd] = \'No\'\r\n    				    if fm < fb\r\n    				        pp[:reference] = \'2\'\r\n    				    else\r\n    				        pp[:reference] = \'3\'\r\n    				    end\r\n    				    \r\n    				    pp[:note] = \'cond-4 [orange]\'\r\n    				end\r\n				    \r\n				    pp[:first_available_cr] = fb\r\n				    pp[:first_available_cr_date] = pp[:date_of_icu_admission]\r\n				    \r\n				    pp[:available_baseline] = \'1|2\'\r\n				    pp[:note] = \'More than 1 year\'\r\n				end\r\n			else\r\n			    pp[:reference] = \'1\'\r\n			    pp[:available_baseline] = \'1\'\r\n			    pp[:date_of_baseline_serum_cr] = pp[:date_of_admission] - 6.months\r\n			    \r\n			 #   pp[:patient_number] = \"<font color=\'red\'>\\\\#{pp[:patient_number]}</font>\".html_safe\r\n			    pp[:patient_number] = pp[:patient_number]\r\n			    pp[:note] = \'<font color=\"red\">Assign as TRUE Baseline</font>\'.html_safe\r\n			end\r\n			\r\n			if pp[:available_baseline] == \'1\'\r\n			    begin\r\n    			    tmp = mc[\'1\']\r\n    			    \r\n    			    pp[:first_available_cr] = tmp[:creatinine]\r\n         		    pp[:first_available_cr_date] = pp[:date_of_icu_admission]\r\n         		    pp[:available_baseline] = \'1|2\'\r\n     		    rescue\r\n     		        msg << tmp.to_json.html_safe\r\n     		        msg << \"err_cr\"\r\n     		    end\r\n     		end\r\n     		\r\n    #  		update patient\r\n        \r\n        \r\n        # temporary aki diag\r\n        ta = {:aki=>\'No\'}\r\n        af.each do |i|\r\n            if !i.include? \'day\'\r\n                ta[i.to_sym] = \'0\'\r\n            else\r\n                ta[i.to_sym] = \'\'\r\n            end\r\n        end\r\n        # number of record_day\r\n        nrd = cid_list.count\r\n        # weight that used to calculate\r\n        calw = 0\r\n        begin \r\n            calw = pp[:weight].to_i\r\n        rescue\r\n            calw = pp[:ideal_body_weight].to_i\r\n            msg << \'no weight found\'\r\n        end\r\n        pp[:num_of_record_day] = nrd\r\n        # pp[:case] = cid_list.sort_by{|i| i[:record_day].to_i}\r\n        # pp[:d1_num] = pp[:case].collect{|i| i[:record_day].to_i}\r\n        # pp[:d1_cr]  = pp[:case].collect{|i| i[:creatinine]}\r\n        # pp[:d1_out24] = pp[:case].collect{|i| i[:urine_output24hr]}\r\n        # pp[:d1_urine] = pp[:case].collect{|i| i[:urine_output_cal]}\r\n        # pp[:d1_rrt] = pp[:case].collect{|i| i[:if_rrt]}\r\n        if !mc.empty?\r\n            # pp[:case] = mc\r\n            \r\n            aki_2d = []\r\n            aki_7d = []\r\n            ur_list = []\r\n            \r\n            ### AKI Diagnosis and Calculation\r\n            rc, df = nil\r\n                if pp[:esrd].downcase == \'no\' or pp[:esrd] == \'\'\r\n                    pp[:esrd] = \'No\'\r\n                    # get reference\r\n                    ref = pp[:reference]\r\n                    ref_field = uf[ref][:f]\r\n                    ref_date  = uf[ref][:d]\r\n                    # reference cr\r\n                    rc = pp[ref_field].to_f\r\n                    # reference date\r\n                    begin \r\n                    rd = Date.strptime(pp[ref_date].to_s,  \'%Y-%m-%d\')\r\n                    rescue\r\n                    rd = Date.strptime(pp[:date_of_icu_admission].to_s,  \'%Y-%m-%d\')\r\n                    msg << \"err-rd[\\\\#{pp[ref_date]}]\"\r\n                    end\r\n                    # rd = pp[ref_date]\r\n                    # date of icu\r\n                    ri = Date.strptime(pp[:date_of_icu_admission].to_s, \'%Y-%m-%d\')\r\n                    # ri = pp[:date_of_icu_admission]\r\n                    # calculate difference between date_of_icu_admission and date_of_cr \r\n                    df = (rd-ri).to_i\r\n                    # msg << rd\r\n                    # msg << ri\r\n                    # msg << (ri - rd)\r\n                end\r\n            # df=0\r\n            r2d = rc\r\n            r7d = rc\r\n            dd.each do |i|\r\n                \r\n                # condition to find AKI\r\n                if pp[:esrd].downcase == \'no\' and !mc[i].nil?\r\n                    # if mc[i][:creatinine].downcase != \'na\' and mc[i][:creatinine].downcase != \'nan\' and mc[i][:creatinine].downcase != \'n/a\'\r\n                    d = i.to_i\r\n                    cc = mc[i][:creatinine].downcase\r\n                    dcr = 0\r\n                    if cc != \'na\' and cc != \'nan\' and cc != \'n/a\' and cc != \'\'\r\n                        if cc.to_f >= 4.0 and ta[:cr_staging] != \'3\'\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n                                ta[:cr_staging] = \'3\'\r\n                                ta[:cr_staging_from_day] = i\r\n                                ta[:aki] = \'Yes\'\r\n                        end\r\n                        if d == 1 and (df >= -2 and df < 0)\r\n                            dcr = (cc.to_f - rc).round(4)\r\n                            aki_2d << {:dx=>\'1\',:dr=>\'0\',:dd=>i,:df=>df,:v=>dcr,:cn=>\'2d\',:cc=>cc,:cr=>rc}\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'1\',:dd=>i,:df=>df,:v=>(cc.to_f / rc.to_f).round(4),:cn=>\'7d\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                                    ta[:cr_diagnosis] = \'1\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                        # elsif d == 1 and (df >= -7 and df < 0)\r\n                        elsif d == 1\r\n                            dcr = (cc.to_f / rc).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'0\',:dd=>i,:df=>df,:v=>dcr,:cn=>\'7d\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                    ta[:cr_diagnosis] = \'2\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                        elsif d == 2\r\n                            c1 = mc[(d - 1).to_s][:creatinine].downcase\r\n                            if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                dcr = (cc.to_f - c1.to_f).round(4)\r\n                                aki_2d << {:dx=>\'1\',:dr=>\'1\',:dd=>i,:df=>1,:v=>dcr,:cn=>\'2d\',:cc=>cc,:cr=>c1}\r\n                                if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                                    ta[:cr_diagnosis] = \'1\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                                end\r\n                                \r\n                                dcr = (cc.to_f / c1.to_f).round(4)\r\n                                aki_7d << {:dx=>\'2\',:dr=>\'1\',:dd=>i,:df=>1,:v=>(cc.to_f / c1.to_f).round(4),:cn=>\'7d\',:cc=>cc,:cr=>c1}\r\n                                if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                    ta[:cr_diagnosis] = \'1\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                                end\r\n                            end\r\n                        elsif d > 2 and d <= 7\r\n                            # c1 = mc[(d - 1).to_s][:creatinine].downcase\r\n                            # c2 = mc[(d - 2).to_s][:creatinine].downcase\r\n                            \r\n                            # if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                            #     dcr = (cc.to_f - c1.to_f).round(4)\r\n                            #     aki_2d << {:dx=>\'1\',:dr=>(d-1).to_s,:dd=>i,:df=>1,:v=>dcr,:cn=>\'2d\',:cc=>cc,:cr=>c1}\r\n                            #     aki_7d << {:dx=>\'2\',:dr=>(d-1).to_s,:dd=>i,:df=>1,:v=>(cc.to_f / c1.to_f).round(4),:cn=>\'7d\',:cc=>cc,:cr=>c1}\r\n                            #     if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                            #         ta[:cr_diagnosis] = \'1\'\r\n                            #         ta[:cr_diagnosis_from_day] = i\r\n                            #     end\r\n                            # end\r\n                            # if c2 != \'na\' and c2 != \'nan\' and c2 != \'n/a\' and c2 != \'\'\r\n                            #     dcr = (cc.to_f - c2.to_f).round(4)\r\n                            #     aki_2d << {:dx=>\'1\',:dr=>(d-2).to_s,:dd=>i,:df=>2,:v=>dcr,:cn=>\'2d\',:cc=>cc,:cr=>c2}\r\n                            #     aki_7d << {:dx=>\'2\',:dr=>(d-2).to_s,:dd=>i,:df=>2,:v=>(cc.to_f / c2.to_f).round(4),:cn=>\'7d\',:cc=>cc,:cr=>c2}\r\n                            #     if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                            #         ta[:cr_diagnosis] = \'1\'\r\n                            #         ta[:cr_diagnosis_from_day] = i\r\n                            #     end\r\n                            # end\r\n                            \r\n                            (d-1).downto(d - 2) do |j|\r\n                                c1 = mc[j.to_s][:creatinine].downcase\r\n                                if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                    dcr = (cc.to_f - c1.to_f).round(4)\r\n                                    aki_2d << {:dx=>\'1\',:dr=>j.to_s,:dd=>i,:df=>(d - j),:v=>dcr,:cn=>\'2d(d)\',:cc=>cc,:cr=>c1}\r\n                                    if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                                        ta[:cr_diagnosis] = \'1\'\r\n                                        ta[:cr_diagnosis_from_day] = i\r\n                                    end\r\n                                end\r\n                            end\r\n                            \r\n                            (d-1).downto(1) do |j|\r\n                                c1 = mc[j.to_s][:creatinine].downcase\r\n                                if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                    dcr = (cc.to_f / c1.to_f).round(4)\r\n                                    aki_7d << {:dx=>\'2\',:dr=>j.to_s,:dd=>i,:df=>(d - j),:v=>dcr,:cn=>\'7d(d)\',:cc=>cc,:cr=>c1}\r\n                                    if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                        ta[:cr_diagnosis] = \'2\'\r\n                                        ta[:cr_diagnosis_from_day] = i\r\n                                    end\r\n                                end\r\n                            end\r\n                            # compare with reference cr\r\n                            dcr = (cc.to_f / rc.to_f).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'0\',:dd=>i,:df=>0,:v=>dcr,:cn=>\'7d(rf)\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                                \r\n                            \r\n                        elsif d > 7\r\n                            c1 = mc[(d - 7).to_s][:creatinine].downcase\r\n                            \r\n                            if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                dcr = (cc.to_f / c1.to_f).round(4)\r\n                                aki_7d << {:dx=>\'2\',:dr=>(d-7).to_s,:dd=>i,:df=>7,:v=>dcr,:cn=>\'7d(d-7)\',:cc=>cc,:cr=>c1}\r\n                                if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                    ta[:cr_diagnosis] = \'2\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                                end\r\n                            end\r\n                            # compare with reference cr\r\n                            dcr = (cc.to_f / rc.to_f).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'0\',:dd=>i,:df=>0,:v=>dcr,:cn=>\'7d(rfx)\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                        end\r\n                        \r\n                        if df != 0 and (d - df) > 2 and (d - df) <= 7\r\n                            dcr = (cc.to_f / rc).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>i.to_s,:dd=>i,:df=>(d - df),:v=>dcr,:cn=>\"7d(d:\\\\#{d}+df:\\\\#{df})\",:cc=>cc,:cr=>c1}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n      