_urine_output_cal_new\"\r\n                                v = ur != 0 ? (ur/calw.to_f/hh).round(4) : 0\r\n                                pp[k.to_sym] = v\r\n                                \r\n                                if ta[:urine_output_from_day] == \'\' and v < 0.5\r\n                                    ta[:urine_output_diagnosis] = \'1\'\r\n                                    ta[:urine_output_from_day] = i.to_s\r\n                                    if v < 0.3\r\n                                        ta[:urine_output_staging] = \'3\'\r\n                                        ta[:urine_output_staging_from_day] = i.to_s\r\n                                    else\r\n                                        ta[:urine_output_staging] = \'2\'\r\n                                        ta[:urine_output_staging_from_day] = i.to_s\r\n                                    end\r\n                                end\r\n                                ur_list << {:d=>i.to_i,:v=>v}\r\n                            end\r\n                        else\r\n                            k = \"d\\\\#{i}_urine_output_cal_new\"\r\n                            pp[k.to_sym] = v\r\n                        end\r\n                        \r\n                    # end # end if i == 1\r\n                end   # end esrd\r\n            end # end dd\r\n            \r\n            # ta[:ur_list] = ur_list\r\n            ta[:ur_list] = ur_list.join(\',\')\r\n            begin\r\n            if ta[:urine_output_diagnosis] == \'1\'\r\n                ur_list.each do |i|\r\n                    d = i[:d].to_s\r\n                    v = i[:v]\r\n                    if i.to_i < ur_list.last[:d].to_i\r\n                        if v < 0.3 \r\n                            ta[:urine_output_staging] = \'3\'\r\n                            ta[:urine_output_staging_from_day] = d\r\n                            break;\r\n                        elsif v >= 0.3 and v < 0.5 and ta[:urine_output_staging] != \'2\'\r\n                            ta[:urine_output_staging] = \'2\'\r\n                            ta[:urine_output_staging_from_day] = d\r\n                        end\r\n                    end\r\n                # mx_ur = ur_list.sort_by{|i| [i[:v],i[:d]]}[0]\r\n                # d = mx_ur[:d].to_s\r\n                # v = mx_ur[:v]\r\n                # if v >= 0.3 and v < 0.5\r\n                #     ta[:urine_output_staging] = \'2\'\r\n                #     ta[:urine_output_staging_from_day] = d\r\n                # elsif v < 0.3\r\n                #     ta[:urine_output_staging] = \'3\'\r\n                #     ta[:urine_output_staging_from_day] = d\r\n                # end\r\n                # ta[:ur_list] = ur_list.sort_by{|i| i[:v]}\r\n                end\r\n                \r\n                if ta[:urine_output_from_day].to_i == ur_list.last[:d].to_i and ur_list.count != 1\r\n                    ta[:urine_output_diagnosis] = \'0\'\r\n                    ta[:urine_output_from_day] = \'\'\r\n                    ta[:urine_output_staging] = \'0\'\r\n                    ta[:urine_output_staging_from_day] = \'\'\r\n                    msg << \'reset_urine\'\r\n                end\r\n                msg << \"ud:\\\\#{ta[:urine_output_from_day]}-ul:\\\\#{ur_list.last[:d]}(\\\\#{ta[:urine_output_from_day].to_i==ur_list.last[:d].to_i})\"\r\n                    \r\n            end\r\n            rescue\r\n                msg << \"err=\\\\#{ur_list.to_s}\"\r\n            end\r\n            \r\n            aki_list = []\r\n            if ta[:cr_diagnosis] != \'0\' and ta[:cr_staging] != \'3\'\r\n                aki_list = (aki_2d + aki_7d).sort do |a,b|\r\n                    # [b[:v], a[:dd].to_i] <=> [a[:v], b[:dd].to_i]\r\n                    [b[:dx].to_i, a[:dd].to_i] <=> [a[:dx].to_i, b[:dd].to_i]\r\n                end\r\n                # msg << \'xx\'\r\n                # xx = aki_list[0]\r\n                ta[:cr_staging] = \'1\'\r\n                ta[:cr_staging_from_day] = ta[:cr_diagnosis_from_day]\r\n                ta[:aki] = \'Yes\'\r\n                            \r\n                aki_list.each do |xx|\r\n                    if xx[:dx] == \'2\'\r\n                        if xx[:v] >= 1.5 and xx[:v] < 2.0\r\n                            ta[:cr_staging] = \'1\'\r\n                            ta[:cr_staging_from_day] = xx[:dd]\r\n                            ta[:aki] = \'Yes\'\r\n                            break;\r\n                        elsif xx[:v] >= 2.0 and xx[:v] < 3.0\r\n                            ta[:cr_staging] = \'2\'\r\n                            ta[:cr_staging_from_day] = xx[:dd]\r\n                            ta[:aki] = \'Yes\'\r\n                            break;\r\n                        elsif xx[:v] >= 3\r\n                            ta[:cr_staging] = \'3\'\r\n                            ta[:cr_staging_from_day] = xx[:dd]\r\n                            ta[:aki] = \'Yes\'\r\n                            break;\r\n                        end\r\n                    end\r\n                    # if xx[:v] >= 0.3 and xx[:df] <= 2 and xx[:dx] == \'1\'\r\n                    #     ta[:cr_staging] = \'1\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \"Yes\"\r\n                    # elsif xx[:v] >= 1.5 and xx[:v] < 2.0 and xx[:df] <= 7 and xx[:dx] == \'2\'\r\n                    #     ta[:cr_staging] = \'1\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \'Yes\'\r\n                    # elsif xx[:v] >= 2.0 and xx[:v] < 3.0\r\n                    #     ta[:cr_staging] = \'2\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \'Yes\'\r\n                    # elsif xx[:v] >= 3\r\n                    #     ta[:cr_staging] = \'3\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \'Yes\'\r\n                    # end\r\n                end\r\n            end\r\n            if ta[:aki].downcase == \'no\'\r\n                ta[:cr_staging] = \'0\'\r\n                ta[:cr_staging_from_day] = \'\'\r\n            end\r\n            \r\n            # msg << \"2D:\\\\#{aki_2d.to_s}\"\r\n            # msg << \"7D:\\\\#{aki_7d.to_s}\"\r\n            msg << aki_list.to_s\r\n            \r\n            #  query each field from case record\r\n            cf.each do |j|\r\n                dd.each do |i|\r\n                    k = \"d\\\\#{i}_\\\\#{j}\"\r\n                    v = !mc[i].nil? ? mc[i][j.to_sym] : \'-\'\r\n                    if j.to_s == \'move_out_time\'\r\n                        if !mc[i].nil?\r\n                            if mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\'\r\n                                begin\r\n                                v = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                rescue\r\n                                v = \"00:00na\"\r\n                                msg << \"time:\\\\#{mc[i][j.to_sym]}.\"\r\n                                end\r\n                            else\r\n                                v = \'-\'\r\n                            end\r\n                        end\r\n                    end\r\n                    pp[k.to_sym] = v\r\n                    \r\n                end # end dd\r\n            end # end cf\r\n        end  \r\n        \r\n        pp[:note] = \"\\\\#{pp[:note]},\\\\#{msg.join(\',\')}\"\r\n        \r\n        pp = pp.merge(ta)\r\n        \r\n        res << pp\r\n    end\r\n    \r\n    lbl = %w{patient_number patient_order gender weight height ideal_body_weight age reference date_of_admission date_of_icu_admission time_of_icu_admission ckd esrd baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr first_available_cr_date}\r\n    lbl << \"num_of_record_day\"\r\n    fx = [\'urine_output_cal_new\', \'creatinine\']\r\n    fx.each do |i|\r\n        dd.each do |j|\r\n            lbl << \"d\\\\#{j}_\\\\#{i}\"\r\n        end\r\n    end\r\n    lbl << \"aki\"\r\n    lbl = lbl + af\r\n        \r\n    \r\n    # result assign\r\n    display = \'table\'\r\n    if params[:type] == \'csv\'\r\n        display = \'csv\'\r\n    elsif params[:type] == \'xls\'\r\n        display = \'xls\'\r\n    elsif params[:type] == \'json\'\r\n        display = \'json\'\r\n    end\r\n    \r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    # rs[:app_par] = app_par\r\n    # rs[:mod_par] = mod_par\r\n\r\n    if display == \'json\'\r\n        rs[:all_patient] = a_pat.count\r\n        rs[:patient_1] = a_pat[1]\r\n        rs[:all_aki] = a_aki.count\r\n        rs[:all_case_record] = a_case.count\r\n        rs[:result] = res\r\n        rs[:time] = Time.now - tb\r\n%>\r\n\r\n<%= rs.to_json.html_safe %>\r\n\r\n<%\r\n    elsif display == \'table\'\r\n        ff = res[0].keys\r\n        # ff = lbl.collect{|i| i.to_sym}\r\n%>\r\n\r\n<%= stylesheet_link_tag    \"application\"  %>\r\n<h3>Using I/O Cut at <%= io %>:00</h3>\r\n<h3>Total Patient = <%= a_pat.count %></h3>\r\nquery time = <%= Time.now - tb %>\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n<% ff.each do |i| %>\r\n        <th><%= i %></th>\r\n<% end %>        \r\n    </tr>\r\n<% \r\n        res.each do |i| \r\n%>\r\n    <tr>\r\n        <% ff.each do |j| %>\r\n        <% if j.to_s != \'case\' %>\r\n        <td><%= i[j] %></td>\r\n        <% else %>\r\n        <!--<td/>-->\r\n        <td><%= i[j] %></td>\r\n        <% end %>\r\n        <% end %>\r\n    </tr>\r\n<% end %>\r\n</table>\r\nProcessing time = <%= Time.now - tb %>\r\n\r\n<%\r\n    elsif display == \'csv\'\r\n        require \'csv\'\r\n    \r\n        response.headers[\"Content-Type\"] = \"text/csv\"\r\n        response.headers[\"Content-disposition\"] = \"attachment; filename=\\\\#{this.document_name}-\\\\#{params[:solution_name]}-\\\\#{Time.now.to_i}.csv\"\r\n        \r\n        ff = res[0].keys\r\n        \r\n        xxx = CSV.generate do |csv|\r\n            \r\n            csv << ff\r\n            tmp = []\r\n            res.each do |i|\r\n                ff.each do |j|\r\n                    tmp << i[j]\r\n                end\r\n                csv << tmp\r\n            end\r\n      \r\n        end\r\n%>\r\n<%= xxx.html_safe %>\r\n<%\r\n    end\r\nend\r\n%>\r\n',NULL,NULL,NULL,'2016-03-04 04:39:37','2016-03-04 04:39:37','merge','*'),(2110,'exportx',480,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    \r\n    rd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    \r\n    mod_app = get_patient_module_by_module_name(\"\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = []\r\n    pat_ids = []\r\n    app_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n    end\r\n    \r\n    mod_doc = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\#{@current_project.name}#\\#{this.document_name}\")\r\n    mod_par = {}\r\n    mod_ids = []\r\n    mod_doc.collect do |i|\r\n        mod_ids << i[:module_id]\r\n        par = i[:parent_id]\r\n        if !mod_par.has_key? par\r\n            mod_par[par] = []\r\n        end\r\n        mod_par[i[:parent_id]] << i[:module_id]\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    a_pat = a_pat.sort_by{|i| i[:patient_order]}\r\n    \r\n    @document = get_document(this.document_name)\r\n    doc = @document\r\n    data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n  \r\n    fields = @document.fields\r\n    fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n    \r\n    rs[:all_patient] = a_pat.count\r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    rs[:app_par] = app_par\r\n    rs[:mod_par] = mod_par\r\n%>\r\n<%= rs.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2016-03-04 09:28:57','2016-03-04 09:28:57','exportx',''),(2111,'show',333,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n<%\r\n\r\n   @document =  get_document this.document_name \r\n   \r\n   model = get_model(this.table_name)\r\n   @patient_module = @module_model.find(params[:id])\r\n   record = model.find(@patient_module.module_id)\r\n   @record = record    \r\n  if request.post?\r\n    \r\n   \r\n    if params[\'cancel_\'] and p =  params[\'cancel_\'] \r\n        \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            old_app.destroy\r\n            mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>nil\r\n   \r\n    elsif  params[\'postpone_\'] and p =  params[\'postpone_\']\r\n    \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            old_app.destroy\r\n            mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        \r\n        \r\n        new_app = record.clone\r\n        new_app.update_attributes :date=>p[0][\'postpone_to\'],:status=>\'Appointed\'\r\n        \r\n        mm = @patient_module.clone\r\n        mm.module_id = new_app.id \r\n        mm.save    \r\n        \r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>p[0][\'postpone_to\'], :postpone_id=>new_app.id\r\n       \r\n        \r\n        \r\n    end\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Home/index\" />\r\n<% end %>\r\n<%= this.display.html_safe %>\r\n\r\n<div id=\"cancel\" style=\"display:none\"  class=\"alert alert-warning\">\r\n   <p>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'cancel_\'\r\n        field = @document.find_by_column_name \'cancel_reason\'\r\n        begin\r\n        %>\r\n        \r\n        <%#field%>\r\n        <div>\r\n        \r\n        <h3>Cancel</h3><br/>\r\n        <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Cancelled\' %>\r\n        </div>\r\n        <script>\r\n        <%= yield :script %>\r\n        \r\n      \r\n        </script>\r\n        <% rescue Exception=>e %>\r\n        <%=e.message%>\r\n        <% end%>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n</div>\r\n\r\n<div id=\"postpone\" style=\"display:none;padding:10px\" class=\"alert alert-warning\">\r\n   \r\n      <p>\r\n        <h3>Postpone</h3><br/>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'postpone_\'\r\n        %>\r\n        <div>\r\n        \r\n       <% field = @document.find_by_column_name \'cancel_reason\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n       <% field = @document.find_by_column_name \'postpone_to\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Postpone\' %>\r\n        </div>\r\n       \r\n       \r\n        <script>\r\n        <%= yield :script %>\r\n        </script>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n   \r\n\r\n<%\r\n    age = \'-\'\r\n    if @patient.birth_date and @patient.birth_date!=\'\'\r\n        age = (Time.now - @patient.birth_date.to_datetime) / 365 /3600/24\r\n        age = age.to_i.to_s+\" yrs\"\r\n    end\r\n    gender = \'-\'\r\n    if @patient.gender\r\n        gender = \'Male\' if @patient.gender==\'1\'\r\n        gender = \'Female\' if @patient.gender==\'2\'\r\n        \r\n    end\r\n%>\r\n   \r\n</div>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Cancel\'.html_safe, \"javascript:cancel()\",:class=>bt_class %> | \r\n<%= link_to \'Postpone\'.html_safe, \"javascript:postpone()\",:class=>bt_class %> | \r\n<a target=\"_blank\" class=\"<%=bt_class%>\" href=\"print_sticker?cmd=print&queue=esm-pi&age=<%=age%>&gender=<%=gender%>&provider=<%= render_value \'provider\'%>&name=<%=@patient.first_name+\" \"+@patient.last_name%>&date=<%= render_value \'date\'%>&proc=<%=render_value(\'procedure\').strip.gsub(/&amp;/,\'-\') %>&hn=<%= @patient.hn %>\">WristBand</a>\r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    \r\n    function cancel(){\r\n        $(\'#postpone\').hide()\r\n        $(\'#cancel\').slideDown()\r\n        $(\'#cancel_cancel_reason\').show()\r\n        \r\n    }\r\n    \r\n    function postpone(){\r\n        $(\'#cancel\').hide()\r\n        $(\'#postpone\').slideDown()\r\n        $(\'#postpone_postpone_to\').show()\r\n\r\n    }\r\n    \r\n    function cancel_ctrl(){\r\n        $(\'#postpone\').slideUp()\r\n        $(\'#cancel\').slideUp()\r\n    }\r\n    $(\'.ctrl\').hide();\r\n</script>\r\n\r\n<style>\r\n    #room {display:none;}\r\n</style>',NULL,NULL,NULL,'2016-03-05 04:12:08','2016-03-05 04:12:08','show',''),(2112,'index2',885,2,'',NULL,NULL,NULL,'2016-03-07 01:39:19','2016-03-07 01:39:19','index2',''),(2113,'layout',885,4,'<html>\r\n<head>\r\n<title>Clinic system : <%=@current_service%></title>\r\n<%=include_header%>\r\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n<style>\r\n.w-box-header {\r\n    background: -webkit-linear-gradient(top, #fbfbfb 0%,#D8D8D8 100%);\r\n}\r\nspan.k-timepicker, span.k-datetimepicker, span.k-datepicker {\r\n    \r\n    padding-bottom: 10px;\r\n}\r\nbody {\r\n    background: url(\"/esm/clinic_master/clinic/bg.jpg\");\r\n    background-repeat: no-repeat;\r\n    background-attachment: fixed;\r\n    -webkit-background-size: cover;\r\n    -moz-background-size: cover;\r\n    -o-background-size: cover;\r\n    background-size: cover;\r\n    \r\n}\r\n\r\n.pull-right {margin-top: 5px;}\r\n#cssmenu {\r\n\r\n  line-height: 15px;\r\n  text-transform: uppercase;\r\n  text-align: left;\r\n}\r\n#cssmenu > ul {\r\n  width: auto;\r\n  list-style-type: none;\r\n  paddin