id=\"finding-div\" style=\"width:500px\"></div>\r\n\r\n<script>\r\n\r\nvar define_inspector = null;\r\n\r\n\r\n$( document ).ready(function() {\r\n\r\nif(define_inspector==null){\r\nconsole.log(\'display script\')\r\ndefine_inspector = true    \r\n\r\ntree.regMonitor(inspect_finding);\r\n\r\nvalues = $(\'#data-findings\').val()\r\nvalues = eval(values).join(\"|\")\r\n            \r\n        \r\n$.ajax({\r\n  url: \"finding_ajax\",\r\n  method: \"POST\",\r\n  data: { values : values, init:true },\r\n  cache: false\r\n})\r\n.done(function( html ) {\r\n\r\n    $( \"#findings\" ).html( html );\r\n});\r\n\r\n}\r\n\r\n});\r\n</script>\r\n\r\n\r\n\r\n<table width=\"550\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n  <td width=\"148\" valign=\"top\"><strong>Type of sedation</strong></td>\r\n  <td width=\"365\" valign=\"top\">\r\n  <span id=\'type_of_sedation-div\' name=\'type_of_sedation\' class=\"report-field\" >...</span>\r\n  </td>\r\n  </tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Type of Drug</strong></td>\r\n  <td valign=\"top\">\r\n  <span id=\'anesthetic_drug_type-div\' name=\'anesthetic_drug_type\' class=\"report-field\" template=\"subtree\" >...</span>\r\n  </td>\r\n</tr>\r\n\r\n\r\n\r\n<tr>\r\n  <td valign=\"top\"><strong>Finding</strong></td>\r\n  <td valign=\"top\"><v></v></td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Bile duct</strong></td>\r\n  <td valign=\"top\"><span id=\"p6\"><v>NA</v></span><br/>\r\n  </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Gallabladder</strong></td>\r\n  <td valign=\"top\"><span id=\"p9\"><v>NA</v></span><br/>\r\n  </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Liver</strong></td>\r\n  <td valign=\"top\"><span id=\"p10\"><v>NA</v></span><br/>\r\n  </td>\r\n</tr>\r\n\r\n\r\n<!-- \r\n<tr id=\"c1-panel\">\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp