pdated_at,\r\n    #             \'procedure\'=>pro[ap.procedure.to_s],\r\n    #             \'date\'=>apdate,\r\n    #             \'color\'=>l[rand(4%l.size)],\r\n    #             \'provider\'=>\"\\\\#{provider.name if provider} \" ,\r\n    #             \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p }\",\r\n    #             \'full_name\'=>\"\\\\#{p.prefix_name if p }\\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    #             \'start\'=>apdate+starttime,\r\n    #             \'end\'=>apdate+stoptime,\r\n    #             # \'indication\'=>indication,\r\n    #             \'allDay\'=>false,\r\n    #             \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    #             \'age\'=>age,\r\n    #             # \'visit_type\'=>visit_type,\r\n    #             \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    #             \'public_id\'=>p.public_id,\r\n    #             \'room\'=>room,\r\n    #             \'qn\'=>ap.qn\r\n    #         }  \r\n    #     else\r\n    #         nil\r\n    #     end \r\n    # }.compact\r\n    # # sort data by date\r\n    # list = res.sort{|a,b| b[\'updated_at\']<=>a[\'updated_at\']}\r\n    \r\n    # g_list = list.group_by{|i| i[\'status\']}\r\n    # c_list = list.group_by{|i| i[\'procedure\']}\r\n    \r\n    # s_list = %w{appointed waiting processing recovery completed}.collect{|i| i.humanize}\r\n    \r\n    # nc = g_list[\'Completed\'].nil? ? 0 : g_list[\'Completed\'].count\r\n%>\r\n\r\n<div id=\'cnt_nurse\'>\r\n\r\n\r\n\r\n</div>\r\n\r\n<script>\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            console.log(\'Updated found. Loading...\')\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        tt = Math.random() * 50000;\r\n        console.log(\'Checking in \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'case_index_partial?date=<%=date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(\'#cnt_nurse\').fadeOut(fade, function(){\r\n                        $(\'#cnt_nurse\').html(data);\r\n                    })\r\n                    $(\'#cnt_nurse\').fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        setTimeout(feed_page(100), 0);\r\n        loadPartial();\r\n    });\r\n    \r\n    refresh_remote();\r\n</script>\r\n',NULL,NULL,NULL,'2016-04-10 08:52:19','2016-04-10 08:52:19','case_index',''),(2174,'case_index_partial',502,3,'<%\r\n    @module_name = @current_project.name+\'#appointment\' \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n  \r\n    @models = get_model\r\n    \r\n    date = Time.now.strftime(\"%d/%m/%Y\")\r\n    if params[:date]\r\n        date = params[:date]\r\n    end\r\n    date = Date.to_mongo(params[:date])\r\n    \r\n    \r\n    a_app = @models[:appointment].where(:date=>date).all\r\n    \r\n    vst = {\'-\'=>\'Undefined\'}\r\n    pro = {}\r\n    rec = {}\r\n    pat = {}\r\n    prov = {}\r\n    \r\n    @models[:visit_type].all.each do |i|\r\n        vst[i.id.to_s] = i.name\r\n    end\r\n    \r\n    @models[:procedure].all.each do |i|\r\n        pro[i.id.to_s] = i.name\r\n    end\r\n    \r\n    @models[:provider].all.each do |i|\r\n        prov[i.id.to_s] = i\r\n    end\r\n    \r\n    @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>a_app.collect{|i| i.id }}).all.each do |i|\r\n        rec[i.module_id]=i\r\n    end\r\n \r\n    @patient_model.find(rec.values.collect{|i| i.patient_id}).each do |i|\r\n        pat[i.id]=i\r\n    end\r\n    \r\n    \r\n    res = a_app.collect{|ap| \r\n        i  = rec[ap.id]\r\n        p = pat[i.patient_id]\r\n        if p.nil?\r\n            next\r\n        end\r\n        provider = prov[ap.provider.to_s]\r\n        l = %w{#bcdeee}\r\n        age = \'-\'\r\n        if p.birth_date\r\n            diff = Time.diff(date, p.birth_date)\r\n            year = diff[:year]\r\n            month = diff[:month]\r\n            day = diff[:day]\r\n            age = \"\\\\#{year}\"\r\n        end\r\n        # indication=\"-\"\r\n        # visit_type=\"-\"\r\n \r\n        # indication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n        # visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n \r\n        # if  ap.status==\'Waiting\' or  ap.status==\'Processing\' or ap.status==\'Recovery\' or  (ap.status==\'Completed\' and ( Time.now - ap.updated_at ) < 300)\r\n            apdate = \'\'\r\n            apdate = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n            starttime = \'\'\r\n            stoptime = \'\'\r\n            starttime = ap.start.strftime(\" %H:%M\") if ap.start\r\n            stoptime = ap.stop.strftime(\" %H:%M\") if ap.stop\r\n            room = ap.room==\'\' ? \'-\' : ap.room\r\n            if ap.status == \'Recovery\'\r\n                room = \'R\'\r\n            elsif ap.status == \'Preparing\'\r\n                room = \'P\'\r\n            end\r\n            vs = \'-\'\r\n            if ap.visit_type != \'\' and !ap.visit_type.nil?\r\n                vs = ap.visit_type\r\n            end\r\n            {\r\n                \'id\'=>ap.id,\r\n                \'status\'=>ap.status ,\r\n                \'record\'=>i.id,\r\n                \'hn\'=> p.hn,\r\n                \'updated_at\'=>ap.updated_at,\r\n                \'procedure\'=>pro[ap.procedure.to_s],\r\n                \'date\'=>apdate,\r\n                \'color\'=>l[rand(4%l.size)],\r\n                \'provider\'=>\"\\\\#{provider.name if provider} \" ,\r\n                \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p }\",\r\n                \'full_name\'=>\"\\\\#{p.prefix_name if p }\\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n                \'start\'=>apdate+starttime,\r\n                \'end\'=>apdate+stoptime,\r\n                # \'indication\'=>indication,\r\n                \'allDay\'=>false,\r\n                \'url\'=>\'edit?id=\'+i.id.to_s,\r\n                \'age\'=>age,\r\n                # \'visit_type\'=>visit_type,\r\n                \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n                \'public_id\'=>p.public_id,\r\n                \'room\'=>room,\r\n                \'qn\'=>ap.qn,\r\n                \'visit_type\'=>vst[vs.to_s]\r\n            }  \r\n        # else\r\n        #     nil\r\n        # end \r\n    }.compact\r\n    # sort data by date\r\n    list = res.sort{|a,b| b[\'updated_at\']<=>a[\'updated_at\']}\r\n    \r\n    v_list = list.group_by{|i| i[\'visit_type\']}\r\n    g_list = list.group_by{|i| i[\'status\']}\r\n    c_list = list.group_by{|i| i[\'procedure\']}\r\n    \r\n    s_list = %w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n    \r\n    nc = g_list[\'Completed\'].nil? ? 0 : g_list[\'Completed\'].count\r\n    n_can = g_list[\'Cancelled\'].nil? ? 0 : g_list[\'Cancelled\'].count\r\n    \r\n    k_vs = v_list.keys.sort\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span10\'>\r\n        <div class=\'alert alert-info\'  style=\'position:fixed;\'>\r\n            <b>Go to section : </b>\r\n<%\r\n    k_vs.each do |i|\r\n%>\r\n<span style=\'margin-right:10px;margin-left:10px\'><%= link_to \"\\\\#{i}\", \"#section-\\\\#{i.downcase}\", :class=>\'btn btn-info\' %></span>\r\n<%\r\n    end\r\n%>\r\n        </div>\r\n    </div>\r\n    <div class=\'span2\'>\r\n        <div class=\'alert alert-success\' style=\'position:fixed;float:right\'>\r\n            <b>Go to : </b><%= link_to \'Nurse Index\', \"nurse_index?date=\\\\#{date.strftime(\'%d/%m/%Y\')}\", :class=>\'btn btn-success\' %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\'row-fluid\' style=\'margin-top:20px\'></div>\r\n<!-- each visit_type : display -->\r\n<%\r\n    \r\n    k_vs.each do |vs|\r\n        l_vs = v_list[vs]\r\n        p_vs = l_vs.group_by{|i| i[\'procedure\']}\r\n        s_vs = l_vs.group_by{|i| i[\'status\']}\r\n        fin  = 0\r\n        if s_vs.has_key? \'Completed\'\r\n            fin += s_vs[\'Completed\'].count\r\n        end\r\n        if s_vs.has_key? \'Discharge\'\r\n            fin += s_vs[\'Discharge\'].count\r\n        end\r\n%>\r\n<div class=\'clear\'></div>\r\n<div id=\'section-<%= vs.downcase %>\' style=\'margin-top:50px\'></div>\r\n\r\n<div class=\'row-fluid\'>\r\n    <div class=\"span10\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\" id=\"header_<%= vs.downcase %>\">\r\n                <%= vs %>\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"today_case\">\r\n            <!--<div class=\'span8\'>-->\r\n                <table class=\"table table-bordered\">\r\n                    <thead>\r\n                        <tr>\r\n                            <th><center>Procedure</center></th>\r\n                            <% s_list.each do |i| %>\r\n                            <th><center><%= i %></center></th>\r\n                            <% end %>\r\n                        </tr>\r\n                    </thead>\r\n                    <tbody>\r\n                    <% \r\n                        kp = p_vs.keys.sort\r\n                        kp.each do |i| \r\n                    %>\r\n                        <tr>\r\n                            <td><%= i %></td>\r\n                    <%\r\n                        gr = p_vs[i].group_by{|i| i[\'status\']}\r\n                        s_list.each do |i|\r\n                            n = gr[i].nil? ? 0 : gr[i].count\r\n                    %>\r\n                            <td><center><%= n %></center></td>\r\n                    <% end %>\r\n                        </tr>\r\n                    <% end %>\r\n                    </tbody>\r\n                </table>\r\n            <!--</div>-->\r\n    	</div>\r\n    </div>\r\n    <div class=\"span2\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                Completed / Appointed\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"all_patient\">\r\n    	    <div class=\"alert alert-block alert-success\">\r\n    	        <center><h1><%= fin %> / <%= l_vs.count %></h1></center>\r\n    	        <!--<center><b>Date : </b><%= date.strftime(\'%d/%m/%Y\') %> </center>-->\r\n    	        <center><%= link_to \'Refresh\', \'javascript:location.reload()\', :class=>\'btn btn-success\' %></center>\r\n    	    </div>\r\n    	</div>\r\n    </div>\r\n</div>\r\n<%\r\n    end\r\n%>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-04-10 08:52:42','2016-04-10 08:52:42','case_index_partial',''),(2175,'link_update',909,3,'<%\r\n    # rid = %w{1	2	3	4	5	6	7	9	11	12	13	14	15	16	17	19	21	23}\r\n    # THAI\r\n    rid = %w{1	2	3	4	5	6	7	9	11	12	13	14	15	16	17	21	23}\r\n    ser = %w{patient case_record aki export export_cir}\r\n    idx = 1\r\n    rid.each do |i|\r\n%>\r\n<h3><%= idx %>. RRTS_<%= i %></h3>\r\n<ul>\r\n<%\r\n        ser.each do |j|\r\n%>\r\n    <li><a href=\'https://emr-life.com/rrts_<%=i%>/rrts/Zam/<%= j %>\' target=\'_blank\'><%= j %></a><br/></li>\r\n<%\r\n        end\r\n%>\r\n</ul>\r\n<%\r\n        idx += 1\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2016-04-11 14:05:01','2016-04-11 14:05:01','link_update',''),(2176,'cs_aki',909,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    \r\n    is_update = false # update\r\n    if params[:act] == \'update\'\r\n        is_update = true\r\n    end\r\n    \r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    \r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")[0..9]\r\n\r\n    a_ids = []\r\n    par_ids = [] # all parent_id\r\n    pat_ids = [] # all patient_id\r\n    app_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    # begin\r\n    # a_pat = a_pat.sort_by{|i| i[:patient_order] if i[:patient_order]}\r\n    a_pat = a_pat.sort{|a,b| a[:patient_order] && b[:patient_order] ? a[:patient_order] <=> b[:patient_order] : a[:patient_order] ? -1 : 1 }\r\n    \r\n    # query patient_module <-> aki\r\n    mod_aki = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#aki\")\r\n    i_aki = []\r\n    p_aki = {}\r\n    mod_aki.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_aki << mid\r\n        if !p_aki.has_key? pid\r\n            p_aki[pid] = []\r\n        end\r\n        p_aki[pid] << mid\r\n    end\r\n    m_aki = {}\r\n    a_aki = get_model[:aki].find(i_aki)\r\n    a_aki.each do |i|\r\n        m_aki[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> case_record\r\n    mod_case = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#case_record\")\r\n    i_case = []\r\n    p_case = {}\r\n    mod_case.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_case << mid\r\n        if !p_case.has_key? pid\r\n            p_case[pid] = []\r\n        end\r\n        p_case[pid] << mid\r\n    end\r\n    m_case = {}\r\n    a_case = get_model[:case_record].find(i_case)\r\n    a_case.each do |i|\r\n        m_case[i.id] = i\r\n    end\r\n    \r\n    # selecting I/O\r\n    hosp_name = @current_solution.name\r\n    io = 24 \r\n    # tm = patient[:time_of_icu_admission].strftime(\'%H\').to_i\r\n    tm_00 = [\"rrts_14\", \"rrts_21\"];\r\n    tm_06 = [\"rrts_1\", \"rrts_3\", \"rrts_4\", \"rrts_7\", \"rrts_9\", \"rrts_19\", \"rrts_23\", \"rrts_26\", \"rrts_27\"];\r\n    tm_07 = [\"rrts_6\", \"rrts_17\"];\r\n    tm_22 = [\"rrts_5\"];\r\n    tm_23 = [\"rrts_2\", \"rrts_11\", \"rrts_12\", \"rrts_13\", \"rrts_15\", \"rrts_16\"];\r\n        \r\n    if !tm_00.index(hosp_name).nil?\r\n        io = 0\r\n    elsif !tm_06.index(hosp_name).nil?\r\n        io = 6\r\n    elsif !tm_07.index(hosp_name).nil?\r\n        io = 7\r\n    elsif !tm_22.index(hosp_name).nil?\r\n        io = 22\r\n    elsif !tm_23.index(hosp_name).nil?\r\n        io = 23\r\n    else\r\n        io = 6\r\n    end\r\n    \r\n    # processing\r\n    res = []\r\n    pf = %w{patient_number patient_order gender weight height ideal_body_weight age date_of_admission date_of_icu_admission time_of_icu_admission ckd esrd reference baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr first_available_cr_date}\r\n#	0	patient_number\r\n#	1	patient_order\r\n#	2	gender\r\n#	3	weight\r\n#	4	height\r\n#	5	ideal_body_weight\r\n#	6	age\r\n#	7	reference\r\n#	8	date_of_admission\r\n#	9	date_of_icu_admission\r\n#	10	time_of_icu_admission\r\n#	11	ckd\r\n#	12	esrd\r\n#	13	baseline_serum_creainine_by_mdrd\r\n#	14	available_baseline\r\n#	15	baseline_serum_cr\r\n#	16	date_of_baseline_serum_cr\r\n#	17	first_available_cr\r\n#	18	first_available_cr_date\r\n    dd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    cf = %w{urine_output_cal record_day case_status move_out_time creatinine urine_output24hr if_rrt}\r\n#	0	record_day\r\n#	1	case_status\r\n#	2	move_out_time\r\n#	3	creatinine\r\n#	4	urine_output24hr\r\n#	5	urine_output_cal\r\n#	6	if_rrt\r\n    af = %w{cr_diagnosis cr_diagnosis_from_day cr_staging cr_staging_from_day urine_output_diagnosis urine_output_from_day urine_output_staging urine_output_staging_from_day}\r\n#	0	cr_diagnosis\r\n#	1	cr_diagnosis_from_day\r\n#	2	cr_staging\r\n#	3	cr_staging_from_day\r\n#	4	urine_output_diagnosis\r\n#	5	urine_output_from_day\r\n#	6	urine_output_staging\r\n#	7	urine_output_staging_from_day\r\n\r\n    # using field\r\n    uf = {\r\n        \'1\'=>{:f=>:baseline_serum_cr,:d=>:date_of_baseline_serum_cr}, \r\n        \'2\'=>{:f=>:first_available_cr,:d=>:first_available_cr_date}, \r\n        \'3\'=>{:f=>:baseline_serum_creainine_by_mdrd,:d=>:date_of_icu_admission}\r\n    }\r\n    \r\n    # for each patient\r\n    a_pat.each do |pat|\r\n        tmp = {}\r\n        msg = []\r\n        if pat.nil?\r\n            next\r\n        end\r\n        \r\n        pp = {}\r\n        pf.each do |i|\r\n            pp[i.to_sym] = pat[i.to_sym]\r\n        end\r\n        \r\n        # recheck urine output from case_record\r\n        cid_list = []\r\n        if xx = p_case[pat.id]\r\n            xx.each do |i|\r\n                cid_list << m_case[i]\r\n            end\r\n        else\r\n            msg << \"xx found\"\r\n        end\r\n        \r\n        # mapping day <--> case_record\r\n        mc = {}\r\n        cid_list.each do |i|\r\n            rd = i[:record_day]\r\n            if rd==\'\'\r\n                msg << \'empty rd\'\r\n            end\r\n            if !mc.has_key? rd\r\n                mc[rd] = i\r\n            else\r\n                msg << \"dup rd[\\\\#{rd}]\"\r\n            end\r\n        end\r\n        \r\n        # checking aki is created ?\r\n        is_aki = false\r\n        aid_list = []\r\n        if xx = p_aki[pat.id]\r\n            xx.each do |i|\r\n                aid_list << m_aki[i]\r\n            end\r\n            is_aki = true\r\n        else\r\n            msg << \"NO AKI\"\r\n        end\r\n        \r\n        # assign aki\r\n        r_aki = nil\r\n        if is_aki\r\n            r_aki = aid_list[0]\r\n        end\r\n        \r\n        pp[:time_of_icu_admission] = pp[:time_of_icu_admission].strftime(\'%H:%M\')\r\n        ti = Time.parse(pp[:time_of_icu_admission])\r\n        \r\n        # temporary aki diag\r\n        ta = {:aki=>\'No\'}\r\n        af.each do |i|\r\n            if !i.include? \'day\'\r\n                ta[i.to_sym] = \'0\'\r\n            else\r\n                ta[i.to_sym] = \'\'\r\n            end\r\n        end\r\n        # number of record_day\r\n        nrd = cid_list.count\r\n        # weight that used to calculate\r\n        calw = 0\r\n        begin \r\n            calw = pp[:weight].to_i\r\n        rescue\r\n            calw = pp[:ideal_body_weight].to_i\r\n            msg << \'no weight found\'\r\n        end\r\n        pp[:num_of_record_day] = nrd\r\n        # pp[:case] = cid_list.sort_by{|i| i[:record_day].to_i}\r\n        # pp[:d1_num] = pp[:case].collect{|i| i[:record_day].to_i}\r\n        # pp[:d1_cr]  = pp[:case].collect{|i| i[:creatinine]}\r\n        # pp[:d1_out24] = pp[:case].collect{|i| i[:urine_output24hr]}\r\n        # pp[:d1_urine] = pp[:case].collect{|i| i[:urine_output_cal]}\r\n        # pp[:d1_rrt] = pp[:case].collect{|i| i[:if_rrt]}\r\n        if !mc.empty?\r\n            # pp[:case] = mc\r\n            \r\n            aki_2d = []\r\n            aki_7d = []\r\n            ur_list = []\r\n            \r\n            ### AKI Diagnosis and Calculation\r\n            rc, df = nil\r\n                if pp[:esrd].downcase == \'no\' or pp[:esrd] == \'\'\r\n                    pp[:esrd] = \'No\'\r\n                    # get reference\r\n                    ref = pp[:reference]\r\n                    ref_field = uf[ref][:f]\r\n                    ref_date  = uf[ref][:d]\r\n                    # reference cr\r\n                    rc = pp[ref_field].to_f\r\n                    # reference date\r\n                    begin \r\n                        rd = Date.strptime(pp[ref_date].to_s,  \'%Y-%m-%d\')\r\n                    rescue\r\n                        rd = Date.strptime(pp[:date_of_icu_admission].to_s,  \'%Y-%m-%d\')\r\n                        msg << \"err-rd[\\\\#{pp[ref_date]}]\"\r\n                    end\r\n                    # rd = pp[ref_date]\r\n                    # date of icu\r\n                    ri = Date.strptime(pp[:date_of_icu_admission].to_s, \'%Y-%m-%d\')\r\n                    # ri = pp[:date_of_icu_admission]\r\n                    # calculate difference between date_of_icu_admission and date_of_cr \r\n                    df = (rd-ri).to_i\r\n                    # msg << rd\r\n                    # msg << ri\r\n                    # msg << (ri - rd)\r\n                end\r\n            # df=0\r\n            r2d = rc\r\n            r7d = rc\r\n            dd.each do |i|\r\n                \r\n                # condition to find AKI\r\n                if pp[:esrd].downcase == \'no\' and !mc[i].nil?\r\n                    # if mc[i][:creatinine].downcase != \'na\' and mc[i][:creatinine].downcase != \'nan\' and mc[i][:creatinine].downcase != \'n/a\'\r\n                    d = i.to_i\r\n                    cc = mc[i][:creatinine].downcase\r\n                    dcr = 0\r\n                    if cc != \'na\' and cc != \'nan\' and cc != \'n/a\' and cc != \'\'\r\n                        if cc.to_f >= 4.0 and ta[:cr_staging] != \'3\'\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n                                ta[:cr_staging] = \'3\'\r\n                                ta[:cr_staging_from_day] = i\r\n                                ta[:aki] = \'Yes\'\r\n                        end\r\n                        if d == 1 and (df >= -2 and df < 0)\r\n                            dcr = (cc.to_f - rc).round(4)\r\n                            aki_2d << {:dx=>\'1\',:dr=>\'0\',:dd=>i,:df=>df,:v=>dcr,:cn=>\'2d\',:cc=>cc,:cr=>rc}\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'1\',:dd=>i,:df=>df,:v=>(cc.to_f / rc.to_f).round(4),:cn=>\'7d\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                                    ta[:cr_diagnosis] = \'1\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                        # elsif d == 1 and (df >= -7 and df < 0)\r\n                        elsif d == 1\r\n                            dcr = (cc.to_f / rc).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'0\',:dd=>i,:df=>df,:v=>dcr,:cn=>\'7d\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                    ta[:cr_diagnosis] = \'2\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                        elsif d == 2\r\n                            c1 = mc[(d - 1).to_s][:creatinine].downcase\r\n                            if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                dcr = (cc.to_f - c1.to_f).round(4)\r\n                                aki_2d << {:dx=>\'1\',:dr=>\'1\',:dd=>i,:df=>1,:v=>dcr,:cn=>\'2d\',:cc=>cc,:cr=>c1}\r\n                                if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                                    ta[:cr_diagnosis] = \'1\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                                end\r\n                                \r\n                                dcr = (cc.to_f / c1.to_f).round(4)\r\n                                aki_7d << {:dx=>\'2\',:dr=>\'1\',:dd=>i,:df=>1,:v=>(cc.to_f / c1.to_f).round(4),:cn=>\'7d\',:cc=>cc,:cr=>c1}\r\n                                if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                    ta[:cr_diagnosis] = \'1\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                                end\r\n                            end\r\n                        elsif d > 2 and d <= 7\r\n                            # c1 = mc[(d - 1).to_s][:creatinine].downcase\r\n                            # c2 = mc[(d - 2).to_s][:creatinine].downcase\r\n                            \r\n                            # if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                            #     dcr = (cc.to_f - c1.to_f).round(4)\r\n                            #     aki_2d << {:dx=>\'1\',:dr=>(d-1).to_s,:dd=>i,:df=>1,:v=>dcr,:cn=>\'2d\',:cc=>cc,:cr=>c1}\r\n                            #     aki_7d << {:dx=>\'2\',:dr=>(d-1).to_s,:dd=>i,:df=>1,:v=>(cc.to_f / c1.to_f).round(4),:cn=>\'7d\',:cc=>cc,:cr=>c1}\r\n                            #     if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                            #         ta[:cr_diagnosis] = \'1\'\r\n                            #         ta[:cr_diagnosis_from_day] = i\r\n                            #     end\r\n                            # end\r\n                            # if c2 != \'na\' and c2 != \'nan\' and c2 != \'n/a\' and c2 != \'\'\r\n                            #     dcr = (cc.to_f - c2.to_f).round(4)\r\n                            #     aki_2d << {:dx=>\'1\',:dr=>(d-2).to_s,:dd=>i,:df=>2,:v=>dcr,:cn=>\'2d\',:cc=>cc,:cr=>c2}\r\n                            #     aki_7d << {:dx=>\'2\',:dr=>(d-2).to_s,:dd=>i,:df=>2,:v=>(cc.to_f / c2.to_f).round(4),:cn=>\'7d\',:cc=>cc,:cr=>c2}\r\n                            #     if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                            #         ta[:cr_diagnosis] = \'1\'\r\n                            #         ta[:cr_diagnosis_from_day] = i\r\n                            #     end\r\n                            # end\r\n                            \r\n                            (d-1).downto(d - 2) do |j|\r\n                                c1 = mc[j.to_s][:creatinine].downcase\r\n                                if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                    dcr = (cc.to_f - c1.to_f).round(4)\r\n                                    aki_2d << {:dx=>\'1\',:dr=>j.to_s,:dd=>i,:df=>(d - j),:v=>dcr,:cn=>\'2d(d)\',:cc=>cc,:cr=>c1}\r\n                                    if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                                        ta[:cr_diagnosis] = \'1\'\r\n                                        ta[:cr_diagnosis_from_day] = i\r\n                                    end\r\n                                end\r\n                            end\r\n                            \r\n                            (d-1).downto(1) do |j|\r\n                                c1 = mc[j.to_s][:creatinine].downcase\r\n                                if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                    dcr = (cc.to_f / c1.to_f).round(4)\r\n                                    aki_7d << {:dx=>\'2\',:dr=>j.to_s,:dd=>i,:df=>(d - j),:v=>dcr,:cn=>\'7d(d)\',:cc=>cc,:cr=>c1}\r\n                                    if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                        ta[:cr_diagnosis] = \'2\'\r\n                                        ta[:cr_diagnosis_from_day] = i\r\n                                    end\r\n                                end\r\n                            end\r\n                            # compare with reference cr\r\n                            dcr = (cc.to_f / rc.to_f).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'0\',:dd=>i,:df=>0,:v=>dcr,:cn=>\'7d(rf)\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                                \r\n                            \r\n                        elsif d > 7\r\n                            c1 = mc[(d - 7).to_s][:creatinine].downcase\r\n                            \r\n                            if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                dcr = (cc.to_f / c1.to_f).round(4)\r\n                                aki_7d << {:dx=>\'2\',:dr=>(d-7).to_s,:dd=>i,:df=>7,:v=>dcr,:cn=>\'7d(d-7)\',:cc=>cc,:cr=>c1}\r\n                                if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                    ta[:cr_diagnosis] = \'2\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                                end\r\n                            end\r\n                            # compare with reference cr\r\n                            dcr = (cc.to_f / rc.to_f).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'0\',:dd=>i,:df=>0,:v=>dcr,:cn=>\'7d(rfx)\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                        end\r\n                        \r\n                        if df != 0 and (d - df) > 2 and (d - df) <= 7\r\n                            dcr = (cc.to_f / rc).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>i.to_s,:dd=>i,:df=>(d - df),:v=>dcr,:cn=>\"7d(d:\\\\#{d}+df:\\\\#{df})\",:cc=>cc,:cr=>c1}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                        end \r\n                        \r\n                    end\r\n                # end # end esrd\r\n                \r\n                \r\n                ### URINE Diagnosis and Calculation\r\n                    # if i == \'1\' \r\n                    #     if mc[i][:urine_output24hr].downcase == \'na\' or mc[i][:urine_output24hr].downcase == \'n/a\' or mc[i][:urine_output24hr].downcase == \'nan\'\r\n                    #         ur = \'NA\'\r\n                    #         k = \"d\\\\#{i}_urine_output_cal_new\"\r\n                    #         pp[:case] = \"ur:\\\\#{ur}<--\\\\#{i}\"\r\n                    #         pp[k.to_sym] = ur\r\n                    #         msg << \"[ur-\\\\#{i}]\"\r\n                    #     else\r\n      