          pp[:case] = \"ur:\\\\#{ur}\"\r\n                                pp[k.to_sym] = ur\r\n                                msg << \"[ur-\\\\#{i}]\"\r\n                            else\r\n                                ur = mc[i][:urine_output24hr].to_i\r\n                                hh = 24\r\n                                if i == \'1\'\r\n                                    tx = Time.parse(\"\\\\#{io}:00\")\r\n                                    if mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\'\r\n                                        tx = Time.parse(mc[i][:move_out_time].strftime(\'%H:%M\'))\r\n                                    end\r\n                                    \r\n                                    # ti - time of icu admission\r\n                                    hh = ((tx - ti)/3600).round(2) # make time in hour\r\n                                    if hh <= 0\r\n                                        hh = 24 + hh\r\n                                    end\r\n                                end\r\n                                \r\n                                k = \"d\\\\#{i}_urine_output_cal_new\"\r\n                                v = ur != 0 ? (ur/calw.to_f/hh).round(4) : 0\r\n                                pp[k.to_sym] = v\r\n                                \r\n                                if ta[:urine_output_from_day] == \'\' and v < 0.5\r\n                                    ta[:urine_output_diagnosis] = \'1\'\r\n                                    ta[:urine_output_from_day] = i.to_s\r\n                                    if v < 0.3\r\n                                        ta[:urine_output_staging] = \'3\'\r\n                                        ta[:urine_output_staging_from_day] = i.to_s\r\n                                    else\r\n                                        ta[:urine_output_staging] = \'2\'\r\n                                        ta[:urine_output_staging_from_day] = i.to_s\r\n                                    end\r\n                                end\r\n                                ur_list << {:d=>i.to_i,:v=>v}\r\n                            end\r\n                        else\r\n                            k = \"d\\\\#{i}_urine_output_cal_new\"\r\n                            pp[k.to_sym] = v\r\n                        end\r\n                        \r\n                    # end # end if i == 1\r\n                end   # end esrd\r\n            end # end dd\r\n            \r\n            # ta[:ur_list] = ur_list\r\n            ta[:ur_list] = ur_list.join(\',\')\r\n            begin\r\n            if ta[:urine_output_diagnosis] == \'1\'\r\n                ur_list.each do |i|\r\n                    d = i[:d].to_s\r\n                    v = i[:v]\r\n                    if i.to_i < ur_list.last[:d].to_i\r\n                        if v < 0.3 \r\n                            ta[:urine_output_staging] = \'3\'\r\n                            ta[:urine_output_staging_from_day] = d\r\n                            break;\r\n                        elsif v >= 0.3 and v < 0.5 and ta[:urine_output_staging] != \'2\'\r\n                            ta[:urine_output_staging] = \'2\'\r\n                            ta[:urine_output_staging_from_day] = d\r\n                        end\r\n                    end\r\n                # mx_ur = ur_list.sort_by{|i| [i[:v],i[:d]]}[0]\r\n                # d = mx_ur[:d].to_s\r\n                # v = mx_ur[:v]\r\n                # if v >= 0.3 and v < 0.5\r\n                #     ta[:urine_output_staging] = \'2\'\r\n                #     ta[:urine_output_staging_from_day] = d\r\n                # elsif v < 0.3\r\n                #     ta[:urine_output_staging] = \'3\'\r\n                #     ta[:urine_output_staging_from_day] = d\r\n                # end\r\n                # ta[:ur_list] = ur_list.sort_by{|i| i[:v]}\r\n                end\r\n                \r\n                if ta[:urine_output_from_day].to_i == ur_list.last[:d].to_i and ur_list.count != 1\r\n                    ta[:urine_output_diagnosis] = \'0\'\r\n                    ta[:urine_output_from_day] = \'\'\r\n                    ta[:urine_output_staging] = \'0\'\r\n                    ta[:urine_output_staging_from_day] = \'\'\r\n                    msg << \'reset_urine\'\r\n                end\r\n                msg << \"ud:\\\\#{ta[:urine_output_from_day]}-ul:\\\\#{ur_list.last[:d]}(\\\\#{ta[:urine_output_from_day].to_i==ur_list.last[:d].to_i})\"\r\n                    \r\n            end\r\n            rescue\r\n                msg << \"err=\\\\#{ur_list.to_s}\"\r\n            end\r\n            \r\n            aki_list = []\r\n            if ta[:cr_diagnosis] != \'0\' and ta[:cr_staging] != \'3\'\r\n                aki_list = (aki_2d + aki_7d).sort do |a,b|\r\n                    # [b[:v], a[:dd].to_i] <=> [a[:v], b[:dd].to_i]\r\n                    [b[:dx].to_i, a[:dd].to_i] <=> [a[:dx].to_i, b[:dd].to_i]\r\n                end\r\n                # msg << \'xx\'\r\n                # xx = aki_list[0]\r\n                ta[:cr_staging] = \'1\'\r\n                ta[:cr_staging_from_day] = ta[:cr_diagnosis_from_day]\r\n                ta[:aki] = \'Yes\'\r\n                            \r\n                aki_list.each do |xx|\r\n                    if xx[:dx] == \'2\'\r\n                        if xx[:v] >= 1.5 and xx[:v] < 2.0\r\n                            ta[:cr_staging] = \'1\'\r\n                            ta[:cr_staging_from_day] = xx[:dd]\r\n                            ta[:aki] = \'Yes\'\r\n                            break;\r\n                        elsif xx[:v] >= 2.0 and xx[:v] < 3.0\r\n                            ta[:cr_staging] = \'2\'\r\n                            ta[:cr_staging_from_day] = xx[:dd]\r\n                            ta[:aki] = \'Yes\'\r\n                            break;\r\n                        elsif xx[:v] >= 3\r\n                            ta[:cr_staging] = \'3\'\r\n             