.5\r\n                    #             ta[:urine_output_diagnosis] = \'1\'\r\n                    #             ta[:urine_output_from_day] = \'1\'\r\n                    #         end\r\n                    #         # msg << k\r\n                    #     end\r\n                            \r\n                    # else\r\n                        last_day = d_list.last\r\n                        v = \'-\'\r\n                        if !mc[i].nil?\r\n                            if mc[i][:urine_output24hr].downcase == \'na\' or mc[i][:urine_output24hr].downcase == \'n/a\' or mc[i][:urine_output24hr].downcase == \'nan\' or mc[i][:urine_output24hr].strip == \'\'\r\n                                ur = \'NA\'\r\n                                k = \"d\\\\#{i}_urine_output_cal_new\"\r\n                                pp[:case] = \"ur:\\\\#{ur}\"\r\n                                pp[k.to_sym] = ur\r\n                                msg << \"[ur-\\\\#{i}]\"\r\n                            else\r\n                                l_day_move_out = true\r\n                                ur = mc[i][:urine_output24hr].to_i\r\n                                hh = 24\r\n                                if i == \'1\'\r\n                                    tx = Time.parse(\"\\\\#{io}:00\")\r\n                                    if mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\'\r\n                                        tx = Time.parse(mc[i][:move_out_time].strftime(\'%H:%M\'))\r\n                                    end\r\n                                    \r\n                                    hh = ((tx - ti)/3600).round(2) # make time in hour\r\n                                    if hh <= 0\r\n                                        hh = 24 + hh\r\n                                    end\r\n                                elsif  i == l_day\r\n                                    to = Time.parse(\"\\\\#{io}:00\") \r\n                                    if mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\' and !mc[i][:move_out_time].nil?\r\n                                        tx = Time.parse(mc[i][:move_out_time].strftime(\'%H:%M\'))\r\n                                        hh = ((tx - to)/3600).round(2)\r\n                                        if hh <= 0\r\n                                            hh = 24 +  hh\r\n                                        end\r\n                                    elsif mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\' and mc[i][:move_out_time].nil?\r\n                                        l_day_move_out = false\r\n                                    end\r\n                                end\r\n                                \r\n                                k = \"d\\\\#{i}_urine_output_cal_new\"\r\n                                # v = ur != 0 ? (ur/calw.to_f/hh).round(4) : 0\r\n                                v = l_day_move_out ? (ur / calw.to_f / hh).round(4) : \'NA\'\r\n                                pp[k.to_sym] = v\r\n                                # pp[k.to_sym] = \"\\\\#{v} \\\\#{ur}/\\\\#{calw}/\\\\#{hh}|\\\\#{tx}\"\r\n                                \r\n                                # v = mc[i][:urine_output_cal].to_f\r\n                                if !v.is_a? String  \r\n                                if ta[:urine_output_from_day] == \'\' and v < 0.5\r\n                                    ta[:aki] = \'Yes\'\r\n                                    ta[:urine_output_diagnosis] = \'1\'\r\n                                    ta[:urine_output_from_day] = i.to_s\r\n                                    if v < 0.3\r\n                                        ta[:urine_output_staging] = \'3\'\r\n                                        ta[:urine_output_staging_from_day] = i.to_s\r\n                                    else\r\n                                        ta[:urine_output_staging] = \'2\'\r\n                                        ta[:urine_ou