      ta[:aki] = \'Yes\'\r\n                            break;\r\n                        elsif xx[:v] >= 3\r\n                            ta[:cr_staging] = \'3\'\r\n                            ta[:cr_staging_from_day] = xx[:dd]\r\n                            ta[:aki] = \'Yes\'\r\n                            break;\r\n                        end\r\n                    end\r\n                    # if xx[:v] >= 0.3 and xx[:df] <= 2 and xx[:dx] == \'1\'\r\n                    #     ta[:cr_staging] = \'1\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \"Yes\"\r\n                    # elsif xx[:v] >= 1.5 and xx[:v] < 2.0 and xx[:df] <= 7 and xx[:dx] == \'2\'\r\n                    #     ta[:cr_staging] = \'1\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \'Yes\'\r\n                    # elsif xx[:v] >= 2.0 and xx[:v] < 3.0\r\n                    #     ta[:cr_staging] = \'2\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \'Yes\'\r\n                    # elsif xx[:v] >= 3\r\n                    #     ta[:cr_staging] = \'3\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \'Yes\'\r\n                    # end\r\n                end\r\n                \r\n            end\r\n            \r\n            if ta[:aki].downcase == \'no\'\r\n                ta[:cr_staging] = \'0\'\r\n                ta[:cr_staging_from_day] = \'\'\r\n                # ta[:auto_max_staging] = \'00\'\r\n            end\r\n            \r\n            ta[:auto_max_staging] = \"\\\\#{ta[:cr_staging]}\\\\#{ta[:urine_output_staging]}\"\r\n            \r\n            # msg << \"2D:\\\\#{aki_2d.to_s}\"\r\n            # msg << \"7D:\\\\#{aki_7d.to_s}\"\r\n            msg << aki_list.to_s\r\n            \r\n            #  query each field from case record\r\n            cf.each do |j|\r\n                dd.each do |i|\r\n                    k = \"d\\\\#{i}_\\\\#{j}\"\r\n                    v = !mc[i].nil? ? mc[i][j.to_sym] : \'-\'\r\n                    if j.to_s == \'move_out_time\'\r\n                        if !mc[i].nil?\r\n                            if mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\'\r\n                                begin\r\n                                v = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                rescue\r\n                                v = \"00:00na\"\r\n                                msg << \"time:\\\\#{mc[i][j.to_sym]}.\"\r\n                                end\r\n                            else\r\n                                v = \'-\'\r\n                            end\r\n                        end\r\n                    end\r\n                    pp[k.to_sym] = v\r\n                    \r\n                end # end dd\r\n            end # end cf\r\n            \r\n            last_day = d_list.last.to_i\r\n            ud = ta[:urine_output_staging_from_day].to_i\r\n            cd = ta[:cr_staging_from_day].to_i\r\n            mf = ta[:aki_max_staging_form].to_i\r\n            cs = !mc[last_day.to_s].nil? ? mc[last_day.to_s][:case_status]  : \'0\'\r\n            \r\n            \r\n            ta[:date_detect] = \"DDD L:\\\\#{last_day}, C:\\\\#{cd}, U:\\\\#{ud}\"\r\n            if (ud == last_day) and ta[:aki].downcase==\'yes\' and cs != \'0\' and last_day > 1\r\n                ta[:date_detect] = \"<span style=\'background:green\'>UUU \\\\#{last_day} L:\\\\#{last_day}</span>\".html_safe\r\n                e_ur += 1\r\n                e_ur_pat_list << pp[:patient_order]\r\n            end\r\n                \r\n        end  \r\n        \r\n        if is_update\r\n            att = {}\r\n            af.each do |k,v|\r\n                smb = k.to_sym\r\n                att[smb] = ta[smb]\r\n            end\r\n            if is_aki\r\n                r_aki.update_attributes att\r\n                msg << \"AKIZ : \\\\#{att}\"\r\n            elsif ta[:aki].downcase == \'yes\' \r\n                pid = pat.id\r\n                par = pat_par[pid]\r\n                r_aki = get_model[:aki].create att\r\n                \r\n                msg << \"akiz : pat_id-\\\\#{pid}|par-\\\\#{par}\"\r\n                pm = @m_pat_mod.create :patient_id=>pid,:module_id=>r_aki.id,:module_name=>\"\\\\#{@current_project.name}#aki\",:date=>Time.now.strftime(\'%d/%m/%Y\'),:time=>Time.now.strftime(\'%H:%M\'),:parent_id=>par,:ref_number=>\'000000\'\r\n            end\r\n        end\r\n        pm_id = pat_par[pat.id]\r\n        x_id = app_par[pm_id]\r\n        pp[:detail] = link_to(\'detail\', \"../Home/patient_record?id=\\\\#{x_id}\", :target=>\'_blank\')\r\n\r\n        # pp[:note] = \"\\\\#{pp[:note]},\\\\#{msg.join(\',\')}\"\r\n        \r\n        pp = pp.merge(ta)\r\n        \r\n        res << pp\r\n    end\r\n    \r\n    lbl = %w{patient_number patient_order gender weight height ideal_body_weight age reference date_of_admission date_of_icu_admission time_of_icu_admission ckd esrd baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr first_available_cr_date}\r\n    lbl << \"num_of_record_day\"\r\n    fx = [\'urine_output_cal_new\', \'creatinine\']\r\n    fx.each do |i|\r\n        dd.each do |j|\r\n            lbl << \"d\\\\#{j}_\\\\#{i}\"\r\n        end\r\n    end\r\n    lbl << \"aki\"\r\n    lbl = lbl + af\r\n    lbl << \'detail\'\r\n        \r\n    \r\n    # result assign\r\n    display = \'table\'\r\n    if params[:type] == \'csv\'\r\n        display = \'csv\'\r\n    elsif params[:type] == \'xls\'\r\n        display = \'xls\'\r\n    elsif params[:type] == \'json\'\r\n        display = \'json\'\r\n    end\r\n    \r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    # rs[:app_par] = app_par\r\n    # rs[:mod_par] = mod_par\r\n\r\n    if display == \'json\'\r\n        rs[:all_patient] = a_pat.count\r\n        # rs[:patient_1] = a_pat[1]\r\n        rs[:e_urine] = e_ur\r\n        rs[:e_patient] = e_ur_pat_list\r\n        # rs[:all_aki] = a_aki.count\r\n        # rs[:all_case_record] = a_case.count\r\n        # rs[:result] = res\r\n        rs[:time] = Time.now - tb\r\n%>\r\n\r\n<%= rs.to_json.html_safe %>\r\n\r\n<%\r\n    elsif display == \'table\'\r\n        ff = res[0].keys\r\n        # ff = lbl.collect{|i| i.to_sym}\r\n%>\r\n\r\n<%= stylesheet_link_tag    \"application\"  %>\r\n<h3>Using I/O Cut at <%= io %>:00</h3>\r\n<h3>Total Patient = <%= a_pat.count %></h3>\r\nquery time = <%= Time.now - tb %>\r\n<div style=\'\'><%= link_to \'Confirm\', \"\\\\#{params[:opt]}?act=update\", :class=>\'btn btn-success\' %></div>\r\n<div style=\'padding:50px\'><%= e_ur %> | <%= e_ur_pat_list %></div>\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n<% ff.each do |i| %>\r\n        <th><%= i %></th>\r\n<% end %>        \r\n    </tr>\r\n<% \r\n        res.each do |i| \r\n%>\r\n    <tr>\r\n        <% ff.each do |j| %>\r\n        <% if j.to_s != \'case\' %>\r\n        <td><%= i[j] %></td>\r\n        <% else %>\r\n        <!--<td/>-->\r\n        <td><%= i[j] %></td>\r\n        <% end %>\r\n        <% end %>\r\n    </tr>\r\n<% end %>\r\n</table>\r\n\r\n<br/>\r\nProcessing time = <%= Time.now - tb %>\r\n\r\n<%\r\n    elsif display == \'csv\'\r\n        require \'csv\'\r\n    \r\n        response.headers[\"Content-Type\"] = \"text/csv\"\r\n        response.headers[\"Content-disposition\"] = \"attachment; filename=\\\\#{this.document_name}-\\\\#{params[:solution_name]}-\\\\#{Time.now.to_i}.csv\"\r\n        \r\n        ff = res[0].keys\r\n        \r\n        xxx = CSV.generate do |csv|\r\n            \r\n            csv << ff\r\n            tmp = []\r\n            res.each do |i|\r\n                ff.each do |j|\r\n                    tmp << i[j]\r\n                end\r\n                csv << tmp\r\n            end\r\n      \r\n        end\r\n%>\r\n<%= xxx.html_safe %>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2016-04-28 04:38:20','2016-04-28 04:38:20','aki',''),(2193,'index',916,2,'API Services',NULL,NULL,NULL,'2016-04-29 20:22:00','2016-04-29 20:22:00','index',''),(2194,'get_provider_by_ref_number',916,3,'<%\r\n    c = \'\'\r\n    res = {:name=>\'\', :id=>\'\'}\r\n    if c = params[:code]\r\n        res = get_model[:provider].where(:ref_number=>c).first\r\n        if res.nil?\r\n            res = {:name=>\'\',:id=>\'\'}\r\n        end\r\n    end\r\n    \r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2016-04-29 20:24:27','2016-04-29 20:24:27','get_provider_by_ref_number',''),(2195,'document_name',917,1,'\'rabies\'',NULL,NULL,NULL,'2016-05-02 01:00:35','2016-05-02 01:00:35',NULL,NULL),(2196,'document_name',918,1,'\'toxins\'',NULL,NULL,NULL,'2016-05-02 01:01:14','2016-05-02 01:01:14',NULL,NULL),(2197,'document_name',919,1,'\'travel\'',NULL,NULL,NULL,'2016-05-02 01:01:43','2016-05-02 01:01:43',NULL,NULL),(2198,'document_name',920,1,'\'basic_exam\'',NULL,NULL,NULL,'2016-05-02 01:09:12','2016-05-02 01:09:12',NULL,NULL),(2199,'create',908,3,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-05-02 01:24:11','2016-05-02 01:24:11','create',''),(2200,'export_old',909,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    \r\n    is_update = false # update\r\n    if params[:act] == \'update\'\r\n        is_update = true\r\n    end\r\n    \r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    \r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = [] # all parent_id\r\n    pat_ids = [] # all patient_id\r\n    app_par = {}\r\n    pat_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n        pat_par[i[:patient_id]] = i.id.to_s\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    # begin\r\n    # a_pat = a_pat.sort_by{|i| i[:patient_order] if i[:patient_order]}\r\n    a_pat = a_pat.sort{|a,b| a[:patient_order] && b[:patient_order] ? a[:patient_order] <=> b[:patient_order] : a[:patient_order] ? -1 : 1 }\r\n    \r\n    # query patient_module <-> aki\r\n    mod_aki = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#aki\")\r\n    i_aki = []\r\n    p_aki = {}\r\n    mod_aki.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_aki << mid\r\n        if !p_aki.has_key? pid\r\n            p_aki[pid] = []\r\n        end\r\n        p_aki[pid] << mid\r\n    end\r\n    m_aki = {}\r\n    a_aki = get_model[:aki].find(i_aki)\r\n    a_aki.each do |i|\r\n        m_aki[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> case_record\r\n    mod_case = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#case_record\")\r\n    i_case = []\r\n    p_case = {}\r\n    mod_case.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_case << mid\r\n        if !p_case.has_key? pid\r\n            p_case[pid] = []\r\n        end\r\n        p_case[pid] << mid\r\n    end\r\n    m_case = {}\r\n    a_case = get_model[:case_record].find(i_case)\r\n    a_case.each do |i|\r\n        m_case[i.id] = i\r\n    end\r\n    \r\n    # selecting I/O\r\n    hosp_name = @current_solution.name\r\n    io = 24 \r\n    # tm = patient[:time_of_icu_admission].strftime(\'%H\').to_i\r\n    tm_00 = [\"rrts_14\", \"rrts_21\"];\r\n    tm_06 = [\"rrts_1\", \"rrts_3\", \"rrts_4\", \"rrts_7\", \"rrts_9\", \"rrts_19\", \"rrts_23\", \"rrts_26\", \"rrts_27\"];\r\n    tm_07 = [\"rrts_6\", \"rrts_17\"];\r\n    tm_22 = [\"rrts_5\"];\r\n    tm_23 = [\"rrts_2\", \"rrts_11\", \"rrts_12\", \"rrts_13\", \"rrts_15\", \"rrts_16\"];\r\n        \r\n    if !tm_00.index(hosp_name).nil?\r\n        io = 0\r\n    elsif !tm_06.index(hosp_name).nil?\r\n        io = 6\r\n    elsif !tm_07.index(hosp_name).nil?\r\n        io = 7\r\n    elsif !tm_22.index(hosp_name).nil?\r\n        io = 22\r\n    elsif !tm_23.index(hosp_name).nil?\r\n        io = 23\r\n    else\r\n        io = 6\r\n    end\r\n    \r\n    # processing\r\n    res = []\r\n    pf = %w{patient_number	patient_order	recheck	reference	birth_date	gender	weight	height	ideal_body_weight	date_of_admission	date_of_icu_admission	time_of_icu_admission	reimbursement	diagnosis	ht	dm	cad	cerebrovascular_disease	malignancy	ckd	esrd	baseline_serum_creainine_by_mdrd	available_baseline	baseline_serum_cr	date_of_baseline_serum_cr	first_available_cr	first_available_cr_date	icu	glasgow_coma_score	temperature	mean_arterial	heart_rate	respiratory_rate	oxygenation	arterial_ph	serum_sodium	serum_potassium	serum_creatinine	hematocrit	white_blood_count	age	chronic_health_points	apache_ii}\r\n    # pf = %w{patient_number patient_order gender weight height ideal_body_weight age date_of_admission date_of_icu_admission time_of_icu_admission ckd esrd reference baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr first_available_cr_date}\r\n#	0	patient_number\r\n#	1	patient_order\r\n#	2	gender\r\n#	3	weight\r\n#	4	height\r\n#	5	ideal_body_weight\r\n#	6	age\r\n#	7	reference\r\n#	8	date_of_admission\r\n#	9	date_of_icu_admission\r\n#	10	time_of_icu_admission\r\n#	11	ckd\r\n#	12	esrd\r\n#	13	baseline_serum_creainine_by_mdrd\r\n#	14	available_baseline\r\n#	15	baseline_serum_cr\r\n#	16	date_of_baseline_serum_cr\r\n#	17	first_available_cr\r\n#	18	first_available_cr_date\r\n    dd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    cf = %w{case_status	move_out_time	bun	creatinine	urine_output24hr	intake	output	net_balance	urine_output_cal	mechanical_ventilation	vasopressor	vasopressor_type	rate_of_vasopressor	dose_of_vasopressor	ml_of_vasopressor	patient_weight	cal_dose_vasopressor	rs	coagulation	cns	liver	renal	cvs	diuretic	lactate	sofa	if_rrt	indication	mode_of_rrt	type_of_vascular_access	site_of_vascular_access	internal_jugular_lr	bfr	dfr	dialyzer	anticoagulant_ihd	complication_ihd	type_of_vascular_access_sled	site_of_vascular_access_sled	internal_jugular_lr_sled	duration_sled	bfr_sled	dfr_sled	dialyzer_sled	anticoagulant_sled	complication_sled	type_of_vascular_access_crrt	site_of_vascular_access_crrt	internal_jugular_lr_crrt	crrt_bfr	crrt_ufr	rfr_crrt	dfr_crrt	effrent_fluid	total_time_crrt	delivered_lose	machine_type	mode	anticoagulant_crrt	crrt_complication	type_of_catheter	type_solution	cycle	fill_volume	dwell_time	pd_complication	c	u}\r\n    # cf = %w{urine_output_cal record_day case_status move_out_time creatinine urine_output24hr if_rrt}\r\n#	0	record_day\r\n#	1	case_status\r\n#	2	move_out_time\r\n#	3	creatinine\r\n#	4	urine_output24hr\r\n#	5	urine_output_cal\r\n#	6	if_rrt\r\n    af = %w{cr_diagnosis cr_diagnosis_from_day cr_staging cr_staging_from_day urine_output_diagnosis urine_output_from_day urine_output_staging urine_output_staging_from_day admin_cause_of_aki aki_type aki_from a_on_c}\r\n    # af = %w{cr_diagnosis cr_diagnosis_from_day cr_staging cr_staging_from_day urine_output_diagnosis urine_output_from_day urine_output_staging urine_output_staging_from_day}\r\n#	0	cr_diagnosis\r\n#	1	cr_diagnosis_from_day\r\n#	2	cr_staging\r\n#	3	cr_staging_from_day\r\n#	4	urine_output_diagnosis\r\n#	5	urine_output_from_day\r\n#	6	urine_output_staging\r\n#	7	urine_output_staging_from_day\r\n\r\n    # using field\r\n    uf = {\r\n        \'1\'=>{:f=>:baseline_serum_cr,:d=>:date_of_baseline_serum_cr}, \r\n        \'2\'=>{:f=>:first_available_cr,:d=>:first_available_cr_date}, \r\n        \'3\'=>{:f=>:baseline_serum_creainine_by_mdrd,:d=>:date_of_icu_admission}\r\n    }\r\n    \r\n    # for each patient\r\n    a_pat.each do |pat|\r\n        tmp = {}\r\n        msg = []\r\n        if pat.nil?\r\n            next\r\n        end\r\n        \r\n        pp = {}\r\n        pf.each do |i|\r\n            pp[i.to_sym] = pat[i.to_sym]\r\n        end\r\n        \r\n        # recheck urine output from case_record\r\n        cid_list = []\r\n        if xx = p_case[pat.id]\r\n            xx.each do |i|\r\n                cid_list << m_case[i]\r\n            end\r\n        else\r\n            msg << \"xx found\"\r\n        end\r\n        \r\n        # mapping day <--> case_record\r\n        mc = {}\r\n        cid_list.each do |i|\r\n            rd = i[:record_day]\r\n            if rd==\'\'\r\n                msg << \'empty rd\'\r\n            end\r\n            if !mc.has_key? rd\r\n                mc[rd] = i\r\n            else\r\n                msg << \"dup rd[\\\\#{rd}]\"\r\n            end\r\n        end\r\n        \r\n        # checking aki is created ?\r\n        is_aki = false\r\n        aid_list = []\r\n        if xx = p_aki[pat.id]\r\n            xx.each do |i|\r\n                aid_list << m_aki[i]\r\n            end\r\n            is_aki = true\r\n        else\r\n            msg << \"NO AKI\"\r\n        end\r\n        \r\n        # assign aki\r\n        r_aki = nil\r\n        if is_aki\r\n            r_aki = aid_list[0]\r\n        end\r\n        \r\n        # begin\r\n            pp[:time_of_icu_admission] = pp[:time_of_icu_admission].strftime(\'%H:%M\')\r\n            ti = Time.parse(pp[:time_of_icu_admission])\r\n        # rescue\r\n        #     ti = Time.parse(\'00:00\')\r\n        #     msg << \'TIME ASSIGN = 00:00\'\r\n        # end\r\n        \r\n        # temporary aki diag\r\n        ta = {:aki=>\'No\'}\r\n        af.each do |i|\r\n            if !i.include? \'day\'\r\n                ta[i.to_sym] = \'0\'\r\n            else\r\n                ta[i.to_sym] = \'\'\r\n            end\r\n        end\r\n        # number of record_day\r\n        nrd = cid_list.count\r\n        # weight that used to calculate\r\n        calw = 0\r\n        begin \r\n            calw = pp[:weight].to_i\r\n        rescue\r\n            calw = pp[:ideal_body_weight].to_i\r\n            msg << \'no weight found\'\r\n        end\r\n        pp[:num_of_record_day] = nrd\r\n        # pp[:case] = cid_list.sort_by{|i| i[:record_day].to_i}\r\n        # pp[:d1_num] = pp[:case].collect{|i| i[:record_day].to_i}\r\n        # pp[:d1_cr]  = pp[:case].collect{|i| i[:creatinine]}\r\n        # pp[:d1_out24] = pp[:case].collect{|i| i[:urine_output24hr]}\r\n        # pp[:d1_urine] = pp[:case].collect{|i| i[:urine_output_cal]}\r\n        # pp[:d1_rrt] = pp[:case].collect{|i| i[:if_rrt]}\r\n        if !mc.empty?\r\n            dd.each do |i|\r\n                if !mc[i].nil?\r\n                    cf.each do |j|\r\n                        if j.to_s == \'move_out_time\'\r\n                            if mc[i][:case_status].to_i != 0\r\n                                pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym].nil? ? \'00:00\' : mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                # pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                            end\r\n                        else\r\n                            pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym]\r\n                        end\r\n                    end\r\n                end\r\n            end # end dd\r\n        end  \r\n        \r\n        if is_aki\r\n            sum = 0\r\n            af.each do |i|\r\n                pp[i.to_sym] = r_aki[i.to_sym]\r\n                sum += r_aki[i.to_sym].to_i\r\n            end\r\n            if sum > 0\r\n                pp[:aki] = \'Yes\'\r\n            else\r\n                pp[:aki] = \'No(Aki)\'\r\n            end\r\n        else\r\n            pp[:aki] = \'No\'\r\n        end\r\n        \r\n        pm_id = pat_par[pat.id]\r\n        x_id = app_par[pm_id]\r\n        pp[:detail] = link_to(\'detail\', \"../Home/patient_record?id=\\\\#{x_id}\", :target=>\'_blank\')\r\n        \r\n        res << pp\r\n    end\r\n    \r\n    # lbl = %w{patient_number patient_order gender weight height ideal_body_weight age reference date_of_admission date_of_icu_admission time_of_icu_admission ckd esrd baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr first_available_cr_date}\r\n    lbl = pf\r\n    lbl << \"num_of_record_day\"\r\n    # fx = [\'urine_output_cal\', \'creatinine\']\r\n    # fx = cf\r\n    # fx.each do |i|\r\n    #     dd.each do |j|\r\n    #         lbl << \"\\\\#{i}_\\\\#{j}\"\r\n    #     end\r\n    # end\r\n    lbl << \"aki\"\r\n    lbl = lbl + af\r\n    lbl << \'detail\'\r\n        \r\n    \r\n    # result assign\r\n    display = \'table\'\r\n    if params[:type] == \'csv\'\r\n        display = \'csv\'\r\n    elsif params[:type] == \'xls\'\r\n        display = \'xls\'\r\n    elsif params[:type] == \'json\'\r\n        display = \'json\'\r\n    end\r\n    \r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    # rs[:app_par] = app_par\r\n    # rs[:mod_par] = mod_par\r\n\r\n    if display == \'json\'\r\n        rs[:all_patient] = a_pat.count\r\n        rs[:patient_1] = a_pat[1]\r\n        rs[:all_aki] = a_aki.count\r\n        rs[:all_case_record] = a_case.count\r\n        rs[:result] = res\r\n        rs[:time] = Time.now - tb\r\n%>\r\n\r\n<%= rs.to_json.html_safe %>\r\n\r\n<%\r\n    elsif display == \'table\'\r\n        ff = res[0].keys\r\n        ff = lbl.collect{|i| i.to_sym}\r\n%>\r\n\r\n<%= stylesheet_link_tag    \"application\"  %>\r\n<h3>Using I/O Cut at <%= io %>:00</h3>\r\n<h3>Total Patient = <%= a_pat.count %></h3>\r\nquery time = <%= Time.now - tb %>\r\n\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n<% ff.each do |i| %>\r\n        <th><%= i %></th>\r\n<% end %>        \r\n    </tr>\r\n<% \r\n        res.each do |i| \r\n%>\r\n    <tr>\r\n<% \r\n            ff.each do |j| \r\n                val = i[j]\r\n%>\r\n       <td><%= val %></td>\r\n<% end %>\r\n    </tr>\r\n<% end %>\r\n</table>\r\n\r\n<br/>\r\nProcessing time = <%= Time.now - tb %><br/>\r\n<%\r\n    elsif display == \'csv\'\r\n        require \'csv\'\r\n    \r\n     