         lov = i[:lov].to_s.split(\'\\r\\n\')\r\n            lov.each do |j|\r\n                x = j.split(\'|\')\r\n                tmp[:pair][x[0].strip] = x[1].strip\r\n                tmp[:list] << x[1].strip\r\n            end\r\n            \r\n            fm[cn][:list] = tmp[:list]\r\n            fm[cn][:pair] = tmp[:pair]\r\n        end\r\n    end\r\n    \r\n    f_1 = %w{indication mode_of_rrt sofa  intake	 output	 net_balance	 	 urine_output_cal	 	 mechanical_ventilation	 vasopressor	 vasopressor_type	 	 rate_of_vasopressor	 dose_of_vasopressor	 ml_of_vasopressor rs	 coagulation	 cns	 liver	 renal	 cvs	 diuretic	 lactate if_rrt  }.collect{|i| i.to_sym} # intro\r\n    # f_2 = %w{bfr dfr dialyzer }.collect{|i| i.to_sym} # IHD\r\n    f_2 = %w{ type_of_vascular_access	 site_of_vascular_access	 internal_jugular_lr	 bfr	 dfr	 	 dialyzer	 dialyzer_ihd_other	 anticoagulant_ihd	 complication_ihd	}.collect{|i| i.to_sym}\r\n    # f_3 = %w{bfr_sled dfr_sled dialyzer_sled }.collect{|i| i.to_sym} # SLED\r\n    f_3 = %w{ type_of_vascular_access_sled	 site_of_vascular_access_sled	 internal_jugular_lr_sled	 duration_sled	 bfr_sled	 dfr_sled		 dialyzer_sled	 dialyzer_sled_other	 anticoagulant_sled	 complication_sled	}.collect{|i| i.to_sym}\r\n    # f_4 = %w{crrt_bfr crrt_ufr dfr_crrt }.collect{|i| i.to_sym} # CRRT\r\n    f_4 = %w{ type_of_vascular_access_crrt	 site_of_vascular_access_crrt	 internal_jugular_lr_crrt	 	  crrt_bfr	 crrt_ufr	 rfr_crrt	 dfr_crrt	  effrent_fluid	 total_time_crrt	 delivered_lose	 	 dialyzer_crrt	 other_dialyzer_crrt	 anticoagulant_crrt	 	 machine_type	 mode	 crrt_complication}.collect{|i| i.to_sym}\r\n    # f_5 = %w{type_of_catheter fill_volume }.collect{|i| i.to_sym} # PD\r\n    f_5 = %w{ type_of_catheter	 type_solution	 	 cycle	 fill_volume	 dwell_time	 	 pd_complication}.collect{|i| i.to_sym}\r\n    \r\n    \r\n    res = {}\r\n    res[:parent] = par\r\n    res[:pm_case] = pm_case\r\n    res[:rs_case] = rs_case\r\n    \r\n    @fm = fm\r\n    def get_value f, val\r\n        x = @fm[f.to_sym]\r\n        v = val\r\n        if x.to_h.has_key? :pair and !v.nil? and v != \'\'\r\n            if f.to_sym == :if_rrt or f.to_sym == :vasopressor\r\n                v = x[:pair][v]\r\n            else\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n                v = \"<span title=\'\\\\#{v}\'>\\\\#{val} <i class=\'splashy-help\'></i></span>\".html_safe\r\n            end\r\n        end\r\n            if f.to_sym == :delivered_lose and !v.nil? and v != \'\'\r\n                    v = v.to_f.round(4) if Float(v) rescue v\r\n            end\r\n        if v.nil? or v == \'\'\r\n            v = \'-\'\r\n        end\r\n        return v\r\n    end\r\n    \r\n    start_rrt = nil\r\n%>\r\n<%# javascript_include_tag \"application\"  %>\r\n<%# stylesheet_link_tag    \"application\"  %>\r\n\r\n\r\n\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n        <th>Day</th>\r\n<%\r\n    dd.each do |i|\r\n%>\r\n        <th><%= i %></th>\r\n<% end %>\r\n    </tr>\r\n<!-- intro -->\r\n<% f_1.each do |i| %>\r\n    <tr>\r\n        <td><%= fm[i.to_sym][:label].html_safe %></td>\r\n<% \r\n        dd.each do |j| \r\n            rs = rd_case[j]\r\n            tx = \'\'\r\n            if rs\r\n                # tx = rs[i]\r\n                tx = get_value i, rs[i]\r\n                \r\n                if i.to_s == \'if_rrt\' and start_rrt.nil? and tx.downcase == \'yes\'\r\n                    # if rs[i] == \'0\'\r\n                        start_rrt = j\r\n                    # end\r\n                end\r\n            else\r\n                tx = \'-\'\r\n            end\r\n            \r\n            \r\n%>\r\n        <td><%= tx %></td>\r\n<% end %>\r\n    </tr>\r\n<% end %>\r\n<!-- IHD -->\r\n    <tr>\r\n        <th colspan=\'11\'>IHD</th>\r\n    </tr>\r\n<% f_2.each do |i| %>\r\n    <tr>\r\n        <td><%= fm[i.to_sym][:label].html_safe %></td>\r\n<% \r\n        dd.each do |j| \r\n            rs = rd_case[j]\r\n            tx = \'\'\r\n            if rs\r\n                # tx = rs[i]\r\n                tx = get_value i, rs[i]\r\n            else\r\n                tx = \'-\'\r\n            end\r\n%>\r\n        <td><%= tx %></td>\r\n<% end %>\r\n    </tr>\r\n<% end %>\r\n\r\n<!-- SLED -->\r\n    <tr>\r\n        <th colspan=\'11\'>SLED</th>\r\n    </tr>\r\n<% f_3.each do |i| %>\r\n    <tr>\r\n        <td><%= fm[i.to_sym][:label].html_safe %></td>\r\n<% \r\n        dd.each do |j| \r\n            rs = rd_case[j]\r\n            tx = \'\'\r\n            if rs\r\n                # tx = rs[i]\r\n                tx = get_value i, rs[i]\r\n            else\r\n                tx = \'-\'\r\n            end\r\n%>\r\n        <td><%= tx %></td>\r\n<% end %>\r\n    </tr>\r\n<% end %>\r\n\r\n<!-- CRRT -->\r\n    <tr>\r\n        <th colspan=\'11\'>CRRT</th>\r\n    </tr>\r\n<% f_4.each do |i| %>\r\n    <tr>\r\n        <td><%= fm[i.to_sym][:label].html_safe %></td>\r\n<% \r\n        dd.each do |j| \r\n            rs = rd_case[j]\r\n            tx = \'\'\r\n            if rs\r\n                # tx = rs[i]\r\n                tx = get_value i, rs[i]\r\n            else\r\n                tx = \'-\'\r\n            end\r\n%>\r\n        <td><%= tx %></td>\r\n<% end %>\r\n    </tr>\r\n<% end %>\r\n\r\n<!-- PD -->\r\n    <tr>\r\n        <th colspan=\'11\'>PD</th>\r\n    </tr>\r\n<% f_5.each do |i| %>\r\n    <tr>\r\n        <td><%= fm[i.to_sym][:label].html_safe %></td>\r\n<% \r\n        dd.each do |j| \r\n            rs = rd_case[j]\r\n            tx = \'\'\r\n            if rs\r\n                # tx = rs[i]\r\n                tx = get_value i, rs[i]\r\n            else\r\n                tx = \'-\'\r\n            end\r\n%>\r\n        <td><%= tx %></td>\r\n<% end %>\r\n    </tr>\r\n<% end %>\r\n\r\n</table>\r\n\r\n<script>\r\n    $(\'#data-rrt_start_day\').val(\'<%= start_rrt %>\');\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-05-03 06:34:54','2016-05-03 06:34:54','rec_partial',''),(2202,'create',899,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n\r\n\r\n<script>\r\n    function load_content() {\r\n      $.ajax({\r\n        url: \'rec_partial?parent_id=<%=params[:parent_id]%>\',\r\n        success: function(data) {\r\n          //  alert(\"update\");\r\n          // do something with the return value here if you like\r\n          $(\'#rrt-result\').fadeOut(500, function(){\r\n            $(\'#rrt-result\').html(data);\r\n          })\r\n          $(\'#rrt-result\').fadeIn(500)\r\n        }\r\n      });\r\n    }\r\n    $(document).ready(function() {\r\n        load_content();\r\n    });\r\n</script>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-05-03 07:26:34','2016-05-03 07:26:34','create',''),(2203,'edit',899,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model()[this.table_name.to_sym]\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this document!!\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n     \r\n    t = Time.now - record.updated_at \r\n \r\n \r\n    if  false and  @current_role!=\'superuser\' and @current_role!=\'developer\' and @current_role!=\'admin\' # and t.to_i > 3600 * 24 \r\n     locker.destroy if locker\r\n  %>\r\n   <script>alert(\"Not allowed to edit this document!!\");window.location = \"<%=return_url%>\";</script>\r\n  <%\r\n  end\r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \"Update\".html_safe, :class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:data=>{:confirm=>\'Are you sure?\'} %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n\r\n\r\n\r\n<script>\r\n    function load_content() {\r\n      $.ajax({\r\n        url: \'rec_partial?pm_id=<%=params[:id]%>\',\r\n        success: function(data) {\r\n          //  alert(\"update\");\r\n          // do something with the return value here if you like\r\n          $(\'#rrt-result\').fadeOut(500, function(){\r\n            $(\'#rrt-result\').html(data);\r\n          })\r\n          $(\'#rrt-result\').fadeIn(500)\r\n        }\r\n      });\r\n    }\r\n    $(document).ready(function() {\r\n        load_content();\r\n    });\r\n</script>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-05-03 07:34:42','2016-05-03 07:34:42','edit',''),(2204,'print_partial',882,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    \r\n    gender = \'ไม่ระบุ\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n    \r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # check pre-op exist ?\r\n    x_pre_op = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id], :module_name=>\"\\\\#{@current_project.name}#pre_op\").first\r\n    r_pre_op = nil\r\n    if !x_pre_op.nil?\r\n        r_pre_op = get_model[:pre_op].find(x_pre_op[:module_id])\r\n    end\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        # res[:patient_innovian] = r_inn\r\n        # res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        res[:project] = @current_project\r\n        res[:project_params] = eval(@current_project[:params])\r\n        \r\n        res[:dx] = this_rec[:diagnosis_note]\r\n        res[:px] = get_model[:pacu_record].find(this_rec[:pacu_record])\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px; line-height:20px;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {\r\n    /*color:#666;*/\r\n    line-height:12px;\r\n}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n /* blockquote, */\r\n /*.wrapper{ width:960px;margin-left:auto;margin-right:auto;} */\r\n body {-webkit-print-color-adjust: exact;}\r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n\r\ntable {\r\n  max-width: 100%;\r\n  background-color: transparent;\r\n  border-collapse: collapse;\r\n  border-spacing: 0;\r\n}\r\n\r\n.table {\r\n  width: 100%;\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.table th,\r\n.table td {\r\n  padding: 8px;\r\n  line-height: 15px;\r\n  text-align: left;\r\n  vertical-align: top;\r\n  border-top: 1px solid #dddddd;\r\n}\r\n\r\n.table th {\r\n  font-weight: bold;\r\n}\r\n\r\n.table thead th {\r\n  vertical-align: bottom;\r\n}\r\n\r\n.table caption + thead tr:first-child th,\r\n.table caption + thead tr:first-child td,\r\n.table colgroup + thead tr:first-child th,\r\n.table colgroup + thead tr:first-child td,\r\n.table thead:first-child tr:first-child th,\r\n.table thead:first-child tr:first-child td {\r\n  border-top: 0;\r\n}\r\n\r\n.table tbody + tbody {\r\n  border-top: 2px solid #dddddd;\r\n}\r\n\r\n.table-bordered {\r\n  border: 1px solid #dddddd;\r\n  border-collapse: separate;\r\n  *border-collapse: collapsed;\r\n  border-left: 0;\r\n  -webkit-border-radius: 4px;\r\n     -moz-border-radius: 4px;\r\n          border-radius: 4px;\r\n}\r\n\r\n.table-bordered th,\r\n.table-bordered td {\r\n  border-left: 1px solid #dddddd;\r\n}\r\n\r\n.table-bordered caption + thead tr:first-child th,\r\n.table-bordered caption + tbody tr:first-child th,\r\n.table-bordered caption + tbody tr:first-child td,\r\n.table-bordered colgroup + thead tr:first-child th,\r\n.table-bordered colgroup + tbody tr:first-child th,\r\n.table-bordered colgroup + tbody tr:first-child td,\r\n.table-bordered thead:first-child tr:first-child th,\r\n.table-bordered tbody:first-child tr:first-child th,\r\n.table-bordered tbody:first-child tr:first-child td {\r\n  border-top: 0;\r\n}\r\n\r\n.table-bordered thead:first-child tr:first-child th:first-child,\r\n.table-bordered tbody:first-child tr:first-child td:first-child {\r\n  -webkit-border-top-left-radius: 4px;\r\n          border-top-left-radius: 4px;\r\n  -moz-border-radius-topleft: 4px;\r\n}\r\n\r\n.table-bordered thead:first-child tr:first-child th:last-child,\r\n.table-bordered tbody:first-child tr:first-child td:last-child {\r\n  -webkit-border-top-right-radius: 4px;\r\n          border-top-right-radius: 4px;\r\n  -moz-border-radius-topright: 4px;\r\n}\r\n\r\n.table-bordered thead:last-child tr:last-child th:first-child,\r\n.table-bordered tbody:last-child tr:last-child td:first-child {\r\n  -webkit-border-radius: 0 0 0 4px;\r\n     -moz-border-radius: 0 0 0 4px;\r\n          border-radius: 0 0 0 4px;\r\n  -webkit-border-bottom-left-radius: 4px;\r\n          border-bottom-left-radius: 4px;\r\n  -moz-border-radius-bottomleft: 4px;\r\n}\r\n\r\n.table-bordered thead:last-child tr:last-child th:last-child,\r\n.table-bordered tbody:last-child tr:last-child td:last-child {\r\n  -webkit-border-bottom-right-radius: 4px;\r\n          border-bottom-right-radius: 4px;\r\n  -moz-border-radius-bottomright: 4px;\r\n}\r\n\r\n.table-striped tbody tr:nth-child(odd) td,\r\n.table-striped tbody tr:nth-child(odd) th {\r\n  background-color: #f9f9f9;\r\n}\r\n\r\n.table tbody tr:hover td,\r\n.table tbody tr:hover th {\r\n  background-color: #f5f5f5;\r\n}\r\n\r\n</style>\r\n<%# stylesheet_link_tag    \"application\"  %>\r\n<script>\r\n    document.title = \"PRINT : (<%= r_pat.hn %>) <%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %>\"\r\n</script>\r\n<body>\r\n	<div class=\"wrapper\">\r\n		<div id=\"head\">\r\n<%\r\n    app_logo = @current_project.get_setting(\'logo_report_path\')\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n			<center><div id=\"logoleft\" style=\"margin-left:0px\"><a href=\"../Home/index\"><img src=\'<%=app_logo%>\' height=\"70px\" style=\"Float:left,top:5px\" /></a></div><h3> <strong><%=this.header%><br/><%=this.form_name%>\r\n				\r\n				</strong></h3>\r\n			</center>\r\n		</div>\r\n		<br />\r\n		<div id=\"page\">\r\n		<!-- Title Section -->\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n				<tr>\r\n					<td > \r\n						<table width=\"100%\">\r\n							<tr>\r\n							    <td width=\'65%\' style=\'vertical-align:top\'>\r\n							        <span class=\" intro\">Date : </span> <v><%= r_app[:date].strftime(\'%d-%m-%Y\') if r_app[:date] %></v> <br/> \r\n							        <span class=\" intro\">Diagnosis : </span> <v><%= r_pre_op.nil? ? \'-\' : r_pre_op[:diagnosis_1] %> </v><br/>\r\n							        <span class=\" intro\">Operation : </span> <v><%= r_pre_op.nil? ? \'-\' : r_pre_op[:operation_1] %> </v><br/>\r\n							        <%\r\n							            ct = {\'0\'=>\"Emergency\",\'1\'=>\"Elective\"}\r\n							            pt = {\'1\'=>\'IPD\',\'2\'=>\'OPD\'}\r\n							        %>\r\n							        <span class=\' intro\'> Case type : </span> <v><%= r_pre_op.nil? ? \'-\' : ct[r_pre_op[:case_type]] %> </v> <br/>\r\n							    	<span class=\' intro\' style=\'color:red\'>Allergy : </span> <span style=\'color:red\'><%= r_pre_op.nil? ? \'N/A\' : r_pre_op[:allergy_notify] %> </span><br/>\r\n								</td>\r\n								<td style=\'vertical-align:top\'>\r\n									<span class=\'intro\'>HN : </span><%=r_pat.hn%> <br/>\r\n									<span class=\' intro\'>Name : </span><%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> <br/>\r\n									<span class=\' intro\'> Age : </span> <%= age %> ปี  \r\n									<span class=\'tab intro\'>Gender : </span><%= gender %> <br/>\r\n									<span class=\' intro\'>Ward : </span><%= r_pre_op.nil? ? \'-\' : r_pre_op[:ward] %> (<%= r_pre_op.nil? ? \'-\' : pt[r_pre_op[:patient_type]] %>) <br/>\r\n								</td>\r\n							</tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n			<hr style=\"margin-top: 5px;\"/>\r\n<style>\r\n    .tab { margin-left: 20px; }\r\n    .intro {\r\n        font-weight:bold;\r\n        width : 170px;\r\n        /*display: inline-block;*/\r\n    }\r\n    v {color:#2561cD};\r\n</style>\r\n			<div style=\"display:block;\">\r\n			<!-- Main Content -->\r\n				<table width=\"100%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left\">\r\n				    <tr>\r\n				        <td valign=\'top\' style=\'font-size:0.8em;line-height:14px\'>\r\n				            <div id=\'pacu-content\'></div>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td style=\'font-size:0.8em;line-height:14px\'>\r\n				            <div id=\'diag-content\'></div>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td>\r\n				            <span class=\'intro\'>\r\n				                จำนวนเลือดส่งกลับ\r\n				            </span> \r\n				            <v><%= (this_rec[:blood_product] == \'\' or this_rec[:blood_product].nil?) ? \'- None -\' : render_value(\'blood_product\') %></v> <br/>\r\n				            <% \r\n				                if this_rec[:blood_product] != \'0\' \r\n				                    bl = this_rec[:blood_product].split(\'|\')\r\n				                    if bl.index(\'1\')\r\n				            %>\r\n				            <span class=\'tab intro\'></span><span class=\'tab intro\'>PRC : </span> <v><%= this_rec[:blood_prc] %></v> u.<br/> \r\n				            <% \r\n				                    end # if 1 \r\n				                    if bl.index(\'2\')\r\n				            %>\r\n				            <span class=\'tab intro\'></span><span class=\'tab intro\'>FFP : </span> <v><%= this_rec[:blood_ffp] %></v> u.<br/> \r\n				            <% \r\n				                    end # if 2\r\n				                    if bl.index(\'3\')\r\n				            %>\r\n				            <span class=\'tab intro\'></span><span class=\'tab intro\'>Plt : </span> <v><%= this_rec[:blood_plt] %></v> u.<br/> \r\n				            <% \r\n				                    end # if 3\r\n				                    if bl.index(\'99\')\r\n				            %>\r\n				            <span class=\'tab intro\'></span><span class=\'tab intro\'>Other : </span> <v><%= this_rec[:blood_other] %></v> u.<br/> \r\n				            <% \r\n				                    end # 99\r\n				                end\r\n				            %>\r\n				        </td>\r\n				    </tr>\r\n				</table>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\'#pacu-content\').load(\'pacu_content?id=<%=@patient_module.module_id%>\');\r\n        $(\'#diag-content\').load(\'diag_content?id=<%=@patient_module.module_id%>\');\r\n    });\r\n</script>\r\n				\r\n				<div class=\"clear\"></div>\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n		<!-- Footer -->\r\n		<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n			<span style=\"float:right\">\r\n				<strong>Record Date Time :</strong>&nbsp;<%= this_rec[:created_at].strftime(\'%d-%m-%Y %H:%M\') %><br />\r\n				<strong>Printed Date Time :</strong>&nbsp;<%= Time.now.strftime(\'%d-%m-%Y %H:%M\') %>\r\n			</span>\r\n			<strong>Anesthesiologist Name : </strong> <%= render_value \'recorder_name_1\' %> <br/>\r\n			<strong>Anesthesiologist signature : </strong> ................................\r\n			<br />\r\n		</div>\r\n		<div class=\"clear\"></div>\r\n	</div>\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-05-04 01:48:22','2016-05-04 01:48:22','print_partial',''),(2205,'a',882,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    \r\n    gender = \'ไม่ระบุ\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n    \r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # check pre-op exist ?\r\n    x_pre_op = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id], :module_name=>\"\\\\#{@current_project.name}#pre_op\").first\r\n    r_pre_op = nil\r\n    if !x_pre_op.nil?\r\n        r_pre_op = get_model[:pre_op].find(x_pre_op[:module_id])\r\n    end\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        # res[:patient_innovian] = r_inn\r\n        # res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        res[:project] = @current_project\r\n        res[:project_params] = eval(@current_project[:params])\r\n        \r\n        res[:dx] = this_rec[:diagnosis_note]\r\n        res[:px] = get_model[:pacu_record].find(this_rec[:pacu_record])\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n