</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							  </tr>\r\n							  <tr class=\"fc-slot43 fc-minor\"><th class=\"fc-agenda-axis fc-widget-header\">&nbsp;</th><td class=\"fc-widget-content\"><div style=\"position:relative\">&nbsp;</div></td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							  </tr>\r\n							  <tr class=\"fc-slot44 \"><th class=\"fc-agenda-axis fc-widget-header\">10pm</th><td class=\"fc-widget-content\"><div style=\"position:relative\">&nbsp;</div></td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							  </tr>\r\n							  <tr class=\"fc-slot45 fc-minor\"><th class=\"fc-agenda-axis fc-widget-header\">&nbsp;</th><td class=\"fc-widget-content\"><div style=\"position:relative\">&nbsp;</div></td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							  </tr>\r\n							  <tr class=\"fc-slot46 \"><th class=\"fc-agenda-axis fc-widget-header\">11pm</th><td class=\"fc-widget-content\"><div style=\"position:relative\">&nbsp;</div></td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							  </tr>\r\n							  <tr class=\"fc-slot47 fc-minor\"><th class=\"fc-agenda-axis fc-widget-header\">&nbsp;</th><td class=\"fc-widget-content\"><div style=\"position:relative\">&nbsp;</div></td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							    <td class=\"fc-widget-content\">&nbsp;</td>\r\n							  </tr>\r\n							</tbody></table></div></div></div></div></div></div>\r\n						</div>',NULL,NULL,NULL,'2016-05-07 15:12:00','2016-05-07 15:12:00','testappointment',''),(2218,'document_name',925,1,'\'laryngology\'',NULL,NULL,NULL,'2016-05-08 13:43:23','2016-05-08 13:43:23',NULL,NULL),(2219,'document_name',926,1,'\'voice_and_swallowing_evaluation\'',NULL,NULL,NULL,'2016-05-08 13:44:56','2016-05-08 13:44:56',NULL,NULL),(2220,'document_name',927,1,'\'pre_operative\'',NULL,NULL,NULL,'2016-05-08 13:49:35','2016-05-08 13:49:35',NULL,NULL),(2221,'document_name',928,1,'\'lbe_operative\'',NULL,NULL,NULL,'2016-05-08 14:11:12','2016-05-08 14:11:12',NULL,NULL),(2222,'document_name',929,1,'\'post_operative\'',NULL,NULL,NULL,'2016-05-08 15:51:17','2016-05-08 15:51:17',NULL,NULL),(2223,'document_name',930,1,'\'follow_up\'',NULL,NULL,NULL,'2016-05-08 15:59:16','2016-05-08 15:59:16',NULL,NULL),(2224,'document_name',931,1,'\'history\'',NULL,NULL,NULL,'2016-05-08 16:10:51','2016-05-08 16:10:51',NULL,NULL),(2225,'total_esd_report_excel',522,3,'<%= render :inline=>this.init%><%\r\n response.headers[\"Content-Type\"] = \"application/xls\"\r\n    response.headers[\"Content-disposition\"] = \"attachment; filename=ESD-Reports-\\\\#{Time.now.to_i}.xls\"\r\n    \r\n    m = @models[:colonoscopy_scope].collection.find({},{:fields=>{\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1,\'treatment_by\'=>1 }}).to_a\r\n   \r\n#   colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n# diagnosis_note scope_note project procedure\r\n\r\n   def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n\r\n    \r\n    list = []\r\n    res = []\r\n    \r\n    for i in m\r\n    \r\n        # if i[\'endoscopy_dx\']==\'ESD\'\r\n        #     list << i \r\n        # elsif i[\'abnormal_note\'] and i[\'abnormal_note\'].downcase.index(\'esd\')\r\n        #     list << i\r\n        # elsif i[\'treatment_by\'] and i[\'treatment_by\'].downcase.index(\'esd\')\r\n        #     list << i \r\n        # end\r\n        \r\n       if i[\'treatment_by\'] and i[\'treatment_by\'].downcase.index(\'esd\')\r\n            list << i \r\n        end\r\n    end\r\n    \r\n    # m = @models[:colonoscopy_scope].collection.find({},{:fields=>{\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1 }}).to_a\r\n   \r\n    list = @models[:colonoscopy_scope].collection.find({:_id=>{\'$in\'=>list.collect{|i|i[\'_id\']}}}).to_a\r\n    \r\n    # { $where: \"this.name.length > 1\" }\r\n    \r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n    map = {\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1, \'procedure\'=>1,\'scope_note\'=>1, \'diagnosis_note\'=>1,\'\'=>1, \'start_at\'=>1,\'stop_at\'=>1}\r\n    qmap = {:diagnosis_group=>{\'$ne\'=>\'Normal\'}}\r\n    where = []\r\n    for i in scope_list\r\n        map[i]=1\r\n    end\r\n    \r\n    \r\n    qmap[\'$where\']= \'this.rectum_scope.length > 1 || this.sigmoid_scope.length > 1 || this.transvers_colon_scope.length>1 || this.ascending_colon_scope.length>1 || this.cecum_scope.length>1 || this.terminal_ileum_scope.length>1\'\r\n    \r\n    ml = @models[:colonoscopy].collection.find({},{:fields=>map}).to_a\r\n    \r\n    lim = {}\r\n    for i in list\r\n    \r\n        lim[i[\'_id\']] = i\r\n    \r\n    end\r\n    \r\n    plist = {}\r\n    \r\n    for i in ml\r\n    \r\n        f = false\r\n        \r\n        for j in scope_list\r\n            \r\n            for k in i[j]\r\n            \r\n            if lim[k]\r\n       \r\n                plist[i[\'_id\']] = {:c=>i,:l=>{}} unless plist[i[\'_id\']]\r\n                \r\n                plist[i[\'_id\']][:l][j] = [] unless plist[i[\'_id\']][:l][j]\r\n                plist[i[\'_id\']][:l][j] << lim[k]\r\n                \r\n            end\r\n            \r\n            end\r\n             \r\n        end\r\n        \r\n            # map = {\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1, \'procedure\'=>1,\'scope_note\'=>1, \'diagnosis_note\'=>1}\r\n\r\n        \r\n        if (i[\'project\'] and i[\'project\'].downcase.index(\'esd\')) or (i[\'procedure\'] and i[\'procedure\'].downcase.index(\'esd\'))\r\n            \r\n            plist[i[\'_id\']] = {:c=>i,:l=>{}} unless plist[i[\'_id\']]\r\n            \r\n        end\r\n        \r\n        \r\n        \r\n    end\r\n#   {:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}}\r\n     # all pm colono of those appointments\r\n     \r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    \r\n    all_pm_colo = @m_patient_module.collection.find({:module_id=>{\'$in\'=>plist.keys},:module_name=>\"\\\\#{pname}colonoscopy\"}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'module_id\'\r\n    \r\n          # all pm colono of those appointments\r\n    all_patient = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'patient_id\'] }}}).to_a\r\n    m_all_patient = bmap all_patient, \'_id\'\r\n    \r\n    cols = %w{abnormal_type  endoscopy_dx morphology_type size treatment treatment_by clip patho_number pit_pattern pit_pattern pitt_by kudo_type vascular_pattern \r\n    vascular_by sano_type nice_classification niceby abnormal_note tattoo jnet_class jnetby chromo complication } \r\n    count = 0 \r\n    \r\n\r\n%>\r\n<?xml version=\"1.0\"?>\r\n<?mso-application progid=\"Excel.Sheet\"?>\r\n<Workbook xmlns=\"urn:schemas-microsoft-com:office:spreadsheet\"\r\n xmlns:o=\"urn:schemas-microsoft-com:office:office\"\r\n xmlns:x=\"urn:schemas-microsoft-com:office:excel\"\r\n xmlns:ss=\"urn:schemas-microsoft-com:office:spreadsheet\"\r\n xmlns:html=\"http://www.w3.org/TR/REC-html40\">\r\n <DocumentProperties xmlns=\"urn:schemas-microsoft-com:office:office\">\r\n  <Author>E.S.M.Solution CO.,Ltd.</Author>\r\n  <LastAuthor><%= \'user\' %></LastAuthor>\r\n  <Created><%= Time.now %></Created>\r\n  <LastSaved><%= Time.now %></LastSaved>\r\n  <Version>15.00</Version>\r\n </DocumentProperties>\r\n <OfficeDocumentSettings xmlns=\"urn:schemas-microsoft-com:office:office\">\r\n  <AllowPNG/>\r\n </OfficeDocumentSettings>\r\n <ExcelWorkbook xmlns=\"urn:schemas-microsoft-com:office:excel\">\r\n  <WindowHeight>7800</WindowHeight>\r\n  <WindowWidth>20490</WindowWidth>\r\n  <WindowTopX>0</WindowTopX>\r\n  <WindowTopY>0</WindowTopY>\r\n  <ProtectStructure>False</ProtectStructure>\r\n  <ProtectWindows>False</ProtectWindows>\r\n </ExcelWorkbook>\r\n <Styles>\r\n  <Style ss:ID=\"Default\" ss:Name=\"Normal\">\r\n   <Alignment ss:Vertical=\"Bottom\"/>\r\n   <Borders/>\r\n   <Font ss:FontName=\"Calibri\" x:Family=\"Swiss\" ss:Size=\"11\" ss:Color=\"#000000\"/>\r\n   <Interior/>\r\n   <NumberFormat/>\r\n   <Protection/>\r\n  </Style>\r\n  <Style ss:ID=\"s65\">\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s68\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s69\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s70\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Bottom\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s72\">\r\n   <Alignment ss:Vertical=\"Bottom\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s74\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\" ss:WrapText=\"1\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  \r\n <Style ss:ID=\"s120\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\" ss:WrapText=\"1\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  \r\n  <Style ss:ID=\"s75\">\r\n   <Alignment ss:Vertical=\"Bottom\" ss:WrapText=\"1\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n </Styles>\r\n<%\r\n ws_name = \'ws name\'\r\n%>\r\n <Worksheet ss:Name=\"<%= ws_name %>\">\r\n  <Table ss:ExpandedColumnCount=\"<%=12+cols.size+6%>\" ss:ExpandedRowCount=\"<%= 1+plist.keys.size*4 %>\" x:FullColumns=\"1\"\r\n   x:FullRows=\"1\" ss:DefaultRowHeight=\"15\">\r\n   <Column ss:StyleID=\"s68\" ss:AutoFitWidth=\"0\" ss:Width=\"35.25\"/>\r\n   <Column ss:StyleID=\"s70\" ss:AutoFitWidth=\"0\" ss:Width=\"68.25\"/>\r\n   <Column ss:StyleID=\"s70\" ss:Width=\"67.5\"/>\r\n   <Column ss:StyleID=\"s65\" ss:AutoFitWidth=\"0\" ss:Width=\"150\" ss:Span=\"1\"/>\r\n   <Column ss:Index=\"6\" ss:StyleID=\"s75\" ss:AutoFitWidth=\"0\" ss:Width=\"150\"\r\n    ss:Span=\"3\"/>\r\n   <Column ss:Index=\"10\" ss:StyleID=\"s65\" ss:AutoFitWidth=\"0\"/>\r\n   \r\n   <Column ss:StyleID=\"s120\"  ss:AutoFitWidth=\"0\" ss:Width=\"150\"/>\r\n\r\n   <Row ss:Index=\"1\" ss:StyleID=\"s69\">\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">No.</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Date</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">HN</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Patient\'s name</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Gender</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Age at op</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Start - Stop</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Time (min)</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Procedure</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Note</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Project</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Location</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">InterventionGroup</Data></Cell>\r\n    <% for x in cols %>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= x.humanize %></Data></Cell>\r\n    <% end %>\r\n   </Row>\r\n   \r\n   <%\r\n   for i in plist.keys\r\n    colo = plist[i]\r\n    c = colo[:c]\r\n    l = colo[:l]\r\n    p_m = m_all_pm_colo[i][0]\r\n    p = m_all_patient[p_m[\'patient_id\']][0] \r\n    \r\n    if l.size == 0 \r\n%>\r\n<Row ss:Index=\"<%=2+count%>\" ss:StyleID=\"s69\">\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=count+1%><% count+=1 %>.</Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=p_m[\'date\'].strftime(\"%Y-%m-%d\")%></Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=p[\'hn\']%></Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=p[\'first_name\']%> <%=p[\'last_name\']%></Data></Cell>\r\n\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">- </Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">-</Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">-</Data></Cell>\r\n\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=c[\'procedure\']%></Data></Cell>  \r\n<Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%=c[\'scope_note\']%></Data></Cell>   \r\n<Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%=c[\'project\']%></Data></Cell> \r\n<Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">.</Data></Cell>\r\n<Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">.</Data></Cell>\r\n</Row>\r\n<%\r\n    else\r\n   \r\n        l.each_pair do |location,list|\r\n        \r\n            for li in list\r\n            \r\n            age = 0 \r\n            \r\n            day = p_m[\'date\'].to_datetime-p[\'birth_date\'].to_datetime\r\n            \r\n            age = (day.to_f/365)\r\n            \r\n            gender = \'-\'\r\n        \r\n            gender = \'M\'    if p[\'gender\']==\'1\'\r\n            \r\n            gender = \'F\'    if p[\'gender\']==\'2\'\r\n            \r\n%>\r\n<Row ss:Index=\"<%=2+count%>\" ss:StyleID=\"s69\">\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=count+1%><% count+=1 %>.</Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=p_m[\'date\'].strftime(\"%Y-%m-%d\")%></Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=p[\'hn\']%></Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=p[\'first_name\']%> <%=p[\'last_name\']%></Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=gender%> </Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=(age*100).to_i/100.0%> </Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=c[\'stop_at\'].to_datetime.strftime(\"%H:%M\")%> - <%=c[\'start_at\'].to_datetime.strftime(\"%H:%M\")%> </Data></Cell>\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=((c[\'stop_at\'].to_datetime - c[\'start_at\'].to_datetime).to_f*24*60).to_i%> </Data></Cell>\r\n\r\n\r\n<Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%=c[\'procedure\']%></Data></Cell>  \r\n<Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%=c[\'scope_note\']%></Data></Cell>   \r\n<Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%=c[\'project\']%></Data></Cell> \r\n<Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%=location.split(\"_\")[0..-2].join(\" \")%></Data></Cell>\r\n<Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">.</Data></Cell>\r\n\r\n<% for x in cols \r\n  style = \'\'\r\n  style = \'style=\"width:150px\"\' if x==\'endoscopy_dx\'\r\n%>\r\n<Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= li[x] %></Data></Cell>\r\n<% end %>\r\n<% \r\n    atts = @models[:attachment].find(li[\'image\']).to_a\r\n%>\r\n<%\r\nl = atts[0..4].compact\r\n            for ai in l\r\n%>\r\n               <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">https://colo.emrlife.com<%=ai.path%> </Data></Cell>\r\n<% end %>\r\n</Row>\r\n<% end %>\r\n<% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n   \r\n   \r\n   \r\n  </Table>\r\n  <WorksheetOptions xmlns=\"urn:schemas-microsoft-com:office:excel\">\r\n   <PageSetup>\r\n    <Header x:Margin=\"0.3\"/>\r\n    <Footer x:Margin=\"0.3\"/>\r\n    <PageMargins x:Bottom=\"0.75\" x:Left=\"0.7\" x:Right=\"0.7\" x:Top=\"0.75\"/>\r\n   </PageSetup>\r\n   <Selected/>\r\n   <Panes>\r\n    <Pane>\r\n     <Number>1</Number>\r\n     <ActiveRow>1</ActiveRow>\r\n     <ActiveCol>1</ActiveCol>\r\n    </Pane>\r\n   </Panes>\r\n   <ProtectObjects>False</ProtectObjects>\r\n   <ProtectScenarios>False</ProtectScenarios>\r\n  </WorksheetOptions>\r\n </Worksheet>\r\n</Workbook>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n\r\n    if false\r\n\r\n%>\r\n<table border=\"1\" style=\"border-collapse: collapse;font-size:0.6em\" >\r\n\r\n<th>No.</th>\r\n<th style=\"width:100px\">Date</th><th>HN</th><th style=\"width:100px\">First name</th><th style=\"width:100px\">Last name</th><th>Procedure</th><th>Note</th><th>Project</th>\r\n<th>Location</th>\r\n<% for x in cols %>\r\n<th><%= x.humanize %></th>\r\n<% end %>\r\n<% 5.times.each do |i| %>\r\n<th  style=\"width:100px\"><%=i+1%>.</th>\r\n<% end %>\r\n<%\r\n   for i in plist.keys\r\n    colo = plist[i]\r\n    c = colo[:c]\r\n    l = colo[:l]\r\n    p_m = m_all_pm_colo[i][0]\r\n    p = m_all_patient[p_m[\'patient_id\']][0] \r\n    \r\nif l.size == 0 \r\n%>\r\n<tr><td><%=count+1%><% count+=1 %>.</td><td style=\"width:100px\"><%=p_m[\'date\'].strftime(\"%d-%m-%Y\")%></td><td><%=p[\'hn\']%></td>\r\n<td><%=p[\'first_name\']%></td><td><%=p[\'last_name\']%></td>\r\n<td><%=c[\'procedure\']%></td>    \r\n<td><%=c[\'scope_note\']%></td>      \r\n<td><%=c[\'project\']%></td>      \r\n    \r\n</tr>\r\n<%\r\nelse\r\n    l.each_pair do |location,list|\r\n        \r\n        for li in list\r\n\r\n%>\r\n<tr><td><%=count+1%><% count+=1 %>.</td><td  style=\"width:100px\"><%=p_m[\'date\'].strftime(\"%d-%m-%Y\")%></td><td><%=p[\'hn\']%></td>\r\n<td><%=p[\'first_name\']%></td><td><%=p[\'last_name\']%></td>\r\n<td><%=c[\'procedure\']%></td>    \r\n<td><%=c[\'scope_note\']%></td>      \r\n<td><%=c[\'project\']%></td>  \r\n<td><%=location.split(\"_\")[0..-2].join(\" \")%></td>\r\n<% for x in cols \r\n  style = \'\'\r\n  style = \'style=\"width:150px\"\' if x==\'endoscopy_dx\'\r\n%>\r\n<td <%=style.html_safe %>><%= li[x] %></td>\r\n<% end %>\r\n<% \r\n  \r\n\r\n    atts = @models[:attachment].find(li[\'image\']).to_a\r\n    \r\n    %>\r\n    <%=%>\r\n<%\r\nl = atts[0..4].compact\r\nfor ai in l\r\n%>\r\n<td style=\"width:100px\">\r\n<a href=\"<%=ai.path%>\" class=\"highslide \" rel=\"highslide\" onclick=\"return hs.expand(this)\"><center>\r\n<img  src=\"<%=ai.path%>&thumb=1\" width=\"100\" />\r\n</a>\r\n</td>\r\n<% end %>\r\n\r\n<% (5-l.size).times do |img| %>\r\n<td >&nbsp;</td>\r\n<% end %>\r\n</tr>\r\n<% end %>\r\n <% \r\n        end\r\n    end\r\n end %>    \r\n</table>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-05-09 14:57:48','2016-05-09 14:57:48','total_esd_report_excel',''),(2226,'patient_board',502,3,'<%\r\n    @module_name = @current_project.name+\'#appointment\' \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n  \r\n    @models = get_model\r\n    \r\n    date = Time.now.strftime(\"%d/%m/%Y\")\r\n    if !params[:date].nil?\r\n        date = params[:date]\r\n    end\r\n    date = Date.to_mongo(date)\r\n\r\n    # dd = params[:date]\r\n    \r\n    \r\n    a_app = @models[:appointment].where(:date=>date).all\r\n%>\r\n    <%= javascript_include_tag \"application\"  %>\r\n    <%# stylesheet_link_tag    \"application\"  %>\r\n\r\n<style type=\"text/css\">\r\nbody {\r\n    background: black;\r\n    font-family:Arial, sans-serif;\r\n    font-size:1.5em;\r\n    color:#efefef;\r\n    overflow:hidden;\r\n}\r\n\r\n::-webkit-scrollbar { \r\n    display: none; \r\n}\r\n\r\n.tg  {border-collapse:collapse;border-spacing:0;height:60px;}\r\n.tg td{font-family:Arial, sans-serif;font-size:1.2em;padding:10px 5px;border-style:solid;border-width:1px;overflow:hidden;word-break:normal;height:59px;}\r\n.tg th{font-family:Arial, sans-serif;font-size:1.2em;font-weight:normal;padding:10px 5px;border-style:solid;border-width:1px;overflow:hidden;word-break:normal;height:50px;}\r\n.tg .tg-7dwi{font-weight:bold;font-size:large;font-family:\"Courier New\", Courier, monospace !important;;background-color:#000000;color:#efefef}\r\n.tg .tg-skti{background-color:#013300;color:#efefef;text-align:center}\r\n.tg .tg-eo60{font-weight:bold;background-color:#010066;color:#efefef;text-align:center;vertical-align:middle}\r\n.tg .tg-eyhi{background-color:#036400;/*height:72px;*/}\r\n.procedure{font-size:0.8em;font-family:\"Courier New\", Courier, monospace !important;;background-color:#34696d;color:#efefef;padding:5px;}\r\n\r\n.status-waiting{background-color:black;}\r\n.status-arrived {background-color:gray;}\r\n.status-preparing {background-color:#343434;}\r\n.status-processing {background-color:#963400;}\r\n.status-recovery {background-color:#036400;}\r\n.status-completed {background-color:#00009b;}\r\n.tg .tg-discharge {color:gray}\r\n.tg .tg-cancelled {color:gray;text-decoration:line-through;}\r\n\r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	position: fixed;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	/*background: url(http://smallenvelop.com/wp-content/uploads/2014/08/Preloader_11.gif) center no-repeat #fff;*/\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat;\r\n}\r\n</style>\r\n<script src=\"http://ajax.googleapis.com/ajax/libs/jquery/1.5.2/jquery.min.js\"></script>\r\n<script src=\"http://cdnjs.cloudflare.com/ajax/libs/modernizr/2.8.2/modernizr.js\"></script>\r\n\r\n<body style=\'background:black\'>\r\n\r\n    <div id=\'header\' style=\'height:60px;margin-top:30px;vertical-align:middle\'>\r\n        <span style=\'float:left;margin-left:0.5%;background-color:#000000;font-size:1.5em\'><%=@current_project.get_setting(\"report_title_1\")%></span>\r\n        <span style=\'float:right;margin-right:80px\' id=\'date\'><%= date.strftime(\"%d %B %Y\") %></span>\r\n        <br/>\r\n        <span style=\'float:right;margin-right:80px;margin-top:20px\' id=\'clock\'>xx:xx:xx</span>\r\n    </div>\r\n    \r\n    <div style=\"margin-top:20px;align:center;margin-left:0.5%\" id=\"table\">\r\n        <div class=\"se-pre-con\"></div>\r\n        <div id=\"board\"></div>\r\n    </div>\r\n    \r\n    <a href=\'index\' style=\'color:black;font-size:20px\'>Home</a>\r\n<!--<%= date.strftime(\'%d/%m/%Y\') %>-->\r\n<script>\r\n    function executeQuery() {\r\n      $.ajax({\r\n        url: \'patient_board_partial?date=<%=date%>\',\r\n        success: function(data) {\r\n          //  alert(\"update\");\r\n          // do something with the return value here if you like\r\n          $(\'#board\').fadeOut(500, function(){\r\n            $(\'#board\').html(data);\r\n          })\r\n          $(\'#board\').fadeIn(500)\r\n        }\r\n      });\r\n    //   setTimeout(executeQuery, 10000); // you could choose not to continue on failure...\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n    var li = 0;\r\n    var partial_timeout = 10000;\r\n    var par_obj;\r\n    var interval_obj;\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        li++;\r\n        $.getJSON( \"last_updated?date=<%=date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            console.log(\'Found updated! Loading... [\' + li + \']\');\r\n            executeQuery();\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        console.log(\'Recheck in \' + partial_timeout + \' ms. [\' + li + \']\');\r\n        // sleep(partial_timeout);\r\n        clearTimeout(par_obj);\r\n        par_obj = setTimeout(loadPartial, partial_timeout);\r\n    }\r\n    \r\n    function startTime() {\r\n        var today = new Date();\r\n        var h = today.getHours();\r\n        var m = today.getMinutes();\r\n        var s = today.getSeconds();\r\n        m = checkTime(m);\r\n        s = checkTime(s);\r\n        // document.getElementById(\'txt\').innerHTML =\r\n        txt = h + \":\" + m + \":\" + s;\r\n        $(\'#clock\').html(txt);\r\n        var t = setTimeout(startTime, 500);\r\n    }\r\n    function checkTime(i) {\r\n        if (i < 10) {i = \"0\" + i};  // add zero in front of numbers < 10\r\n        return i;\r\n    }\r\n    \r\n    var element = $(\".blink\");\r\n    var shown = true;\r\n    setInterval(toggle, 1000);\r\n    \r\n    \r\n    function toggle() {\r\n        if(shown) {\r\n            // element.hide();\r\n            element.fadeOut(\"slow\");\r\n            shown = false;\r\n        } else {\r\n            element.show();\r\n            shown = true;\r\n        }\r\n    }\r\n    \r\n    function sleep(milliseconds) {\r\n      var start = new Date().getTime();\r\n      for (var i = 0; i < 1e7; i++) {\r\n        if ((new Date().getTime() - start) > milliseconds){\r\n          break;\r\n        }\r\n      }\r\n    }\r\n    refresh_remote();\r\n\r\n    $(document).ready(function() {\r\n        // run the first time; all subsequent calls will take care of themselves\r\n        setTimeout(executeQuery, 0);\r\n        loadPartial();\r\n        startTime();\r\n    });\r\n\r\n</script>\r\n\r\n</body>',NULL,NULL,NULL,'2016-05-10 05:09:44','2016-05-10 05:09:44','patient_board','*'),(2227,'patient_board_partial',502,3,'<%\r\n  \r\n    @module_name = @current_project.name+\'#appointment\' \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n  \r\n    @models = get_model\r\n  \r\n    if this.table_name!=\'appointment\' and params[:parent_id] \r\n        @appointment_module = @module_model.find(params[:parent_id])\r\n        if @appointment_module\r\n            @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n        end\r\n    end \r\n  \r\n    if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n        @patient = @patient_model.find(@patient_module.patient_id)\r\n    end\r\n\r\n    p_date = Time.now\r\n    if params[:date]\r\n        p_date = params[:date]\r\n    end\r\n        date = Date.to_mongo(p_date)\r\n     \r\n        appointments =   @models[:appointment].where(:date=>date).all\r\n     \r\n     \r\n        records = {}\r\n        patients = {}\r\n        providers = {}\r\n        indications= {}\r\n        visit_types= {}\r\n    \r\n    \r\n        @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n            records[i.module_id]=i\r\n        end\r\n     \r\n        @patient_model.find(records.values.collect{|i| i.patient_id}).each do |i|\r\n            patients[i.id]=i\r\n        end\r\n    \r\n        @models[:visit_type].all.each do |i|\r\n            visit_types[i.id.to_s] = i\r\n        end\r\n     \r\n        @models[:provider].all.each do |i|\r\n            providers[i.id.to_s] = i\r\n        end\r\n        @models[:indication].all.each do |i|\r\n            indications[i.id.to_s] = i\r\n        end\r\n     \r\n        pro = {}\r\n        @models[:procedure].all.each do |i|\r\n            pro[i.id] = i.name\r\n        end\r\n        \r\n        \r\n    \r\n        \r\n        json_data =   appointments.collect{|ap| \r\n            i  = records[ap.id]\r\n            p = patients[i.patient_id]\r\n            provider = providers[ap.provider.to_s]\r\n            l = %w{#bcdeee}\r\n            age = \'-\'\r\n            if p.birth_date\r\n                diff = Time.diff(date, p.birth_date)\r\n                year = diff[:year]\r\n                month = diff[:month]\r\n                day = diff[:day]\r\n                age = \"\\\\#{year} Y\"\r\n            end\r\n            indication=\"-\"\r\n            visit_type=\"-\"\r\n     \r\n            indication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n            visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n     \r\n     \r\n            # if  ap.status==\'Processing\' or ap.status==\'Recovery\' or ap.status==\'Preparing\' or ap.status==\'Completed\'\r\n                apdate = \'\'\r\n                apdate = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n                starttime = \'\'\r\n                stoptime = \'\'\r\n                starttime = ap.start.strftime(\" %H:%M\") if ap.start\r\n                stoptime = ap.stop.strftime(\" %H:%M\") if ap.stop\r\n                room = ap.room==\'\' ? \'-\' : ap.room\r\n                # if ap.status == \'Recovery\'\r\n                #     room = \'R\'\r\n                # end\r\n                qn = \'\'\r\n                if !ap[:qn].nil?\r\n                    qn = ap[:qn]\r\n                end\r\n                prov = \"อ.\\\\#{provider.name.split(\' \')[0] if provider}\"\r\n                if provider\r\n                    if provider.name.index(\'.\')\r\n                        prov = provider.name\r\n                    end\r\n                end\r\n                {\r\n                    :id=>ap.id,\r\n                    :status=>ap.status ,\r\n                    :record=>i.id,\r\n                    :hn=> p.hn,\r\n                    :updated_at=>ap.updated_at,\r\n                    :procedure=>pro[ap.procedure],\r\n                    :date=>apdate,\r\n                    :color=>l[rand(4%l.size)],\r\n                    :provider=>\"\\\\#{provider.name if provider} \" ,\r\n                    :title=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p }\",\r\n                    :first_name=>\"\\\\#{p.first_name if p }\",\r\n                    :last_name=>\"\\\\#{p.last_name if p }\",\r\n                    :full_name=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p }   \\\\#{p.last_name if p}\",\r\n                    :gender=>\"\\\\#{p.gender if p }\",\r\n                    :start=>apdate+starttime,\r\n                    :end=>apdate+stoptime,\r\n                    :indication=>indication,\r\n                    :age=>age,\r\n                    :tel=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n                    :public_id=>p.public_id,\r\n                    :room=>room,\r\n                    :ward=>ap.ward,\r\n                    :note=>ap.note,\r\n                    :prov=>\"อ.\\\\#{provider.name.split(\' \')[0] if provider}\",\r\n                    :hn=>\"\\\\#{p.first_name if p} \\\\#{p.last_name[0]}.\",\r\n                    :qn=>qn\r\n                }  \r\n            # else\r\n            #     nil\r\n            # end \r\n        }.compact\r\n    \r\n        # sort data by date\r\n        # list = json_data.sort{|a,b| b[\'updated_at\']<=>a[\'updated_at\']}\r\n    \r\n        # p_list = list.group_by{|i| i[\'procedure\']}\r\n        \r\n        # sort data by procedure\r\n        list = json_data.sort{|a,b| b[:procedure]<=>a[:procedure]}.reverse\r\n\r\n        p_list = list.group_by{|i| i[:procedure]}\r\n        c_list = []\r\n        \r\n        p_list.each_pair do |k, v|\r\n            tmp = {}\r\n            tmp[:proc] = k\r\n            tmp[:count] = v.count\r\n            c_list << tmp\r\n        end\r\n        # c_list = c_list.sort_by{|i| i[:count]}.reverse\r\n        c_list = c_list.sort_by{|i| [i[:proc],i[:count]]}\r\n\r\n        content = []\r\n        c_list.each do |i|\r\n            pr = i[:proc]\r\n            tmp = p_list[pr]\r\n            res = {:type=>\'head\', :body=>pr, :count=>i[:count]}\r\n            content << res\r\n            tmp.each do |j|\r\n                res = {:type=>\'cont\', :body=>j}\r\n                content << res\r\n            end\r\n        end\r\n        \r\n        s_list = %w{appointed waiting arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.to_s}\r\n        \r\n        mx = 11 \r\n        pg = (content.size / (mx*2.0)).ceil\r\n%>\r\n\r\n<%\r\nno = 1\r\n1.upto(pg) do |page|    \r\n%>\r\n\r\n<div id=\'page-<%=page%>\' style=\'display:block\'>\r\n<!-- Left Table <%= page %>-->\r\n<table class=\"tg\" style=\"undefined;table-layout: fixed; width: 49%; float:left;\">\r\n  <colgroup>\r\n    <col style=\"width: 10%\">\r\n    <col style=\"width: 25%\">\r\n    <col style=\"width: 25%\">\r\n    <col style=\"width: 15%\">\r\n    <col style=\"width: 10%\">\r\n    <col style=\"width: 15%\">\r\n  </colgroup>\r\n  <tr>\r\n    <th class=\"tg-eo60\">No.</th>\r\n    <th class=\"tg-eo60\">Name</th>\r\n    <th class=\"tg-eo60\">Provider</th>\r\n    <th class=\"tg-eo60\">Ward</th>\r\n    <th class=\"tg-eo60\">Room</th>\r\n    <th class=\"tg-eo60\">Status</th>\r\n  </tr>\r\n<%\r\n    # content.each do |i|\r\n    start = ((page - 1) * (mx * 2)) + 1\r\n    stop  = ((page - 1) * (mx * 2)) + mx\r\n    (start - 1).upto(stop - 1) do |n|\r\n        if n < content.size\r\n            i = content[n]\r\n            if i[:type] == \'head\'\r\n                no = 1\r\n%>\r\n  <tr>\r\n    <td class=\"tg-7dwi\" colspan=\"6\" style=\'text-align:left;margin-left:20px\'><%= i[:body] %> ( <%= i[:count] %> ) </td>\r\n  </tr>  \r\n<%      \r\n            else \r\n                x = i[:body]\r\n                name = \"\\\\#{x[:first_name]} \\\\#{x[:last_name][0]}.\"\r\n                prov = (x[:provider].nil? or x[:provider] == \'\') ? \'-\' : x[:provider].split(\' \')[0]\r\n                if !prov.index(\'.\')\r\n                    prov = \"อ.\\\\#{prov}\"\r\n                end\r\n                room = x[:room]\r\n                ward = x[:ward].nil? ? \'OPD\' : x[:ward]\r\n                status = x[:status].downcase\r\n                blink = (s_list.index(status) and s_list.index(status) >= 1 and s_list.index(status) <= 5) ? \'blink\' : \'\'\r\n                note = (x[:note].nil? or x[:note]==\'\') ? \'\' : \"<br/><span style=\'font-size:0.5em;display: block;font-weight: bold;text-align: left;\'>Note: \\\\#{x[:note]}</span>\".html_safe \r\n%> \r\n  <tr>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= no %>.</td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= name %> <%= note %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= prov %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= ward %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= room %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><div class=\' status-<%= status %>\'><font size=\'2em\' class=\'<%= blink %>\'><%= status.humanize %></font></