s].downcase\r\n                blink = (s_list.index(status) and s_list.index(status) >= 1 and s_list.index(status) <= 5) ? \'blink\' : \'\'\r\n                note = (x[:note].nil? or x[:note]==\'\') ? \'\' : \"<br/><span style=\'font-size:0.5em;display: block;font-weight: bold;text-align: left;\'>Note: \\\\#{x[:note]}</span>\".html_safe \r\n%> \r\n  <tr>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= no %>.</td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= name %> <%= note %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= prov %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= ward %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= room %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><div class=\'status-<%= status.downcase %>\'><font size=\'2em\'  class=\'<%= blink %>\'><%= status.humanize %></font></div></td>\r\n  </tr>\r\n<%\r\n                no += 1\r\n            end\r\n        else\r\n%>\r\n  <tr>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n  </tr>\r\n<%\r\n        end\r\n    end\r\n%>\r\n</table>  \r\n\r\n</div>\r\n\r\n<% end # page %>\r\n<%# content.to_json.html_safe %>\r\n\r\n\r\n<script>\r\n    function hidden_page() {\r\n<%\r\n        1.upto(pg) do |i|\r\n            if i > 1\r\n%>\r\n        $(\'#page-<%=i%>\').hide();\r\n<%\r\n            end\r\n        end\r\n%>\r\n    }\r\n    \r\n    var cur_page = 0;\r\n    var all_page = <%= pg %>;\r\n    var t_out = 10000;\r\n    var page_obj;\r\n    function change_page(from_page, to_page) {\r\n        // $(from_page).fadeOut(500);\r\n        $(from_page).hide();\r\n        $(to_page).fadeIn(500);\r\n        console.log(\'... \'+from_page+\' - \' + to_page)\r\n    }\r\n    function execute_change_page() {\r\n        nex_page = cur_page + 1\r\n        f_page = \"#page-\" + cur_page;\r\n        t_page = \"#page-\" + nex_page;\r\n        if (nex_page > all_page) {\r\n            nex_page = 1;\r\n            t_page = \"#page-\" + nex_page;\r\n        } \r\n        \r\n        change_page(f_page, t_page);\r\n        \r\n        cur_page = nex_page;\r\n        console.log(\'### cur_page (\' + cur_page + \") - nex_page (\" + nex_page + \") : ALL = \" + all_page);\r\n        clearTimeout(page_obj);\r\n        page_obj = setTimeout(execute_change_page, t_out);\r\n    }\r\n    \r\n    var element = $(\".blink\");\r\n    var shown = true;\r\n    clearInterval(interval_obj);\r\n    interval_obj = setInterval(toggle, 1000);\r\n    \r\n    // function toggle() {\r\n    //     if(shown) {\r\n    //         // element.hide();\r\n    //         element.fadeOut(\"slow\");\r\n    //         shown = false;\r\n    //     } else {\r\n    //         element.show();\r\n    //         shown = true;\r\n    //     }\r\n    // }\r\n    \r\n    $(document).ready(function() {\r\n        hidden_page();\r\n        \r\n<% \r\n        if pg > 1\r\n%>\r\n        execute_change_page();\r\n<%\r\n        end\r\n%>\r\n        \r\n        $(\".se-pre-con\").fadeOut(\"slow\");\r\n    })\r\n\r\n    \r\n</script>',NULL,NULL,NULL,'2016-05-10 05:21:24','2016-05-10 05:21:24','patient_board_partial','*'),(2228,'signup',921,2,'<%\r\n    solutions = Esm.all.collect{|i| i.name}\r\n%>\r\n<script>\r\n\r\nsolutions = <%=solutions.to_json.html_safe%>\r\n    \r\n    \r\n</script>\r\n<h1>SuperScope</h1>\r\n\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n    \r\n    <div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n    <h3 style=\"display:inline-block\">Sign Up</h3>\r\n    <div class=\"pull-right\">\r\n    \r\n    </div>\r\n    </div>\r\n    \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n    <div style=\"border:0px solid\">\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%;max-width:730px\">\r\n    <%\r\n    #   model = get_model(:customer)\r\n    #   record = model.new\r\n      \r\n      return_url = url(\'index\')\r\n      return_url = params[:return] if params[:return]\r\n      \r\n      if request.post?\r\n        doc = get_document this.document_name\r\n        record = doc.record_create(model,params)\r\n        flash[:notice]=\'New record has been created\'\r\n        \r\n        if return_url.index(\'?\')\r\n            return_url+=\'&\'\r\n         else\r\n            return_url+=\'?\'\r\n        end\r\n    \r\n        return_url += \"obj_id=\\\\#{record.id}\"\r\n    %>\r\n    <script type=\"text/javascript\">\r\n    <!--\r\n    window.location = \"<%= return_url.html_safe %>\"\r\n    //-->\r\n    </script>\r\n    <%\r\n      else  \r\n    %>\r\n    <%= form_for :record,:url=>\'signup_confirm\' do |form| %>\r\n    <%\r\n        # params[:form] = {}\r\n        # params[:form][:model] = model\r\n        # params[:form][:form] = form\r\n        # params[:form][:record] = record\r\n    %>\r\n    <%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n    <p>\r\n\r\n    <div style=\"width:100%;border: 0px solid blue;padding-top:0px;padding-bottom:0px\" id=\"form-data\" data-role=\"validator\">\r\n    <div style=\"margin-left:auto;margin-right:auto;width:100%;padding:1px;border:0px solid green\" >\r\n    <div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:100%;margin:0px;min-height:50px\">\r\n\r\n    <div id=\"555-F6757117143\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n    <b>Solution (ระบบ SuperScope)</b> \r\n    </div>\r\n    \r\n    <div id=\"solution_name_div\" class=\"alert alert-warn portlet \" style=\"border:0px solid blue;width:700px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Solution name : </label></span>	\r\n    <input type=\"text\" name=\"solution[solution_name]\" id=\"solution_name\" size=\"29\" onkeyup=\"check_name(this)\" style=\"vertical-align:text-middle;width:100px;display:inline-block\" class=\"k-textbox k-textbox-txt\">\r\n   <font style=\"font-size:1.5em;width:200px;display:inline-block\"> .emr-life.com</font> <span id=\"check_name\" style=\'color:green;display:inline-block;width:200px\'></span>\r\n        \r\n    </div>\r\n\r\n<script>\r\n\r\nfunction check_name(e){\r\n\r\n    solutions = <%=solutions.to_json.html_safe %>\r\n    $(\'#create\').attr(\'disabled\', \'disabled\');\r\n\r\n    if(solutions.indexOf(e.value)==-1){\r\n    if(e.value.length>1){\r\n        \r\n          \r\n\r\n      \r\n    //   $.ajax({\r\n    //         url: \"check_solution?name=\"+e.value,\r\n    //         context: document.body\r\n    //   }).done(function(data) {\r\n    //         $(\'#check_name\').html(data);\r\n    //   });\r\n    \r\n     $(\'#check_name\').html(\"<span style=\'color:green\'>\"+e.value+\" is OK</span>\");\r\n\r\n    \r\n    $(\'#create\').removeAttr(\"disabled\");\r\n\r\n    \r\n      \r\n    }else{\r\n         $(\'#check_name\').html(\"<span style=\'color:red\'>Too short!!</span>\");\r\n    }\r\n    }\r\n    else{\r\n         $(\'#check_name\').html(\"<span style=\'color:red\'>Existed !!</span>\");\r\n    }\r\n}\r\n\r\n$(\'#solution_name\').focus();\r\n</script>\r\n\r\n\r\n\r\n        <div id=\"555-F6757117143\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n            <b>Account (บัญชีผู้ใช้)</b>\r\n            \r\n        </div>\r\n    \r\n \r\n \r\n    <div id=\"name\" class=\"  portlet \" style=\"border:0px solid blue;width:250px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Name (ชื่อผู้ใช้ / สถาบัน) : </label></span>	\r\n        <input type=\"text\" name=\"record[name]\" id=\"data-name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n \r\n \r\n \r\n \r\n \r\n    <div id=\"register_date\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Register date : </label></span>	\r\n    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n    \r\n    <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\"><input type=\"text\" name=\"record[register_date]\" id=\"data-register_date\" value=\"2016-05-07 21:06:33 +0700\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-register_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 7 พฤษภาคม 2016\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-register_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n    <script>\r\n        $(\"#data-register_date\").kendoDatePicker({\r\n            value: \'07/05/2016\',\r\n        });\r\n    </script>\r\n        \r\n    \r\n    </div>\r\n    </div>\r\n    <script type=\"text/javascript\" charset=\"utf-8\">\r\n    \r\n    \r\n    \r\n        $(\'#data-register_date\').change(data_register_date_proxy_update);\r\n        \r\n        function data_register_date_proxy_update(){\r\n            if(typeof(esm_helper)!==\'undefined\'){\r\n            var tree = esm_helper.get(\'customer\');\r\n            if(tree){\r\n            tree.updateReport();\r\n            }\r\n            data_register_date_update()\r\n            }\r\n        }\r\n        function data_register_date_update(){\r\n            \r\n            // alert(\'call F2765712666 data-register_date\')\r\n            t = $(\'#data-register_date\')\r\n            val = t.val()\r\n            if(val==\'true\'){\r\n                val = t.attr(\'checked\')\r\n                if(val==\'checked\'){\r\n                    val = \'TRUE\'\r\n                }else{\r\n                    val = \'\'\r\n                }\r\n                            \r\n            }\r\n            text = val\r\n            \r\n            var tree = esm_helper.get(\'customer\');\r\n            if(tree){\r\n            tree.changeValue(\'F2765712666\',t,val,text)\r\n            tree.updateReport();\r\n            }\r\n        }\r\n            \r\n    </script>\r\n    \r\n    <div class=\"clear\"></div>\r\n        \r\n    \r\n    \r\n    \r\n    \r\n    <div id=\"commercial_name\" class=\"  portlet \" style=\"border:0px solid blue;width:350px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Commercial name (ชื่อในการออกใบเสร็จใบกำกับภาษี)  : </label></span>	\r\n    <input type=\"text\" name=\"record[commercial_name]\" id=\"data-commercial_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n    \r\n    \r\n    <div class=\"clear\"></div>\r\n        \r\n    \r\n    <div id=\"commercial_address\" class=\"  portlet \" style=\"border:0px solid blue;width:500px;margin: 0 0.5em 0.5em 0;float:left;width:500px;min-height:30px;\">\r\n    <span class=\"\"><label>Commercial address (ที่อยู่) : </label></span>	\r\n    <input type=\"text\" name=\"record[commercial_address]\" id=\"data-commercial_address\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:500px\" class=\"k-textbox k-textbox-txt\">\r\n    \r\n    </div>\r\n   \r\n    \r\n    \r\n    <div id=\"555-F6757117143\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n    <b>Contact (ผู้ติดต่อ)</b>\r\n            \r\n    </div>\r\n    \r\n    \r\n    \r\n    <div id=\"contact_person\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Contact person : </label></span>	\r\n    <input type=\"text\" name=\"record[contact_person]\" id=\"data-contact_person\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n    \r\n    <div id=\"contact_tel\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Contact tel : </label></span>	\r\n    <input type=\"text\" name=\"record[contact_tel]\" id=\"data-contact_tel\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n\r\n\r\n    <div id=\"contact_email\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Contact email : </label></span>	\r\n    <input type=\"text\" name=\"record[contact_email]\" id=\"data-contact_email\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n  \r\n    \r\n    <div id=\"address\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:500px;min-height:30px;\">\r\n    <span class=\"\"><label>Address : </label></span>	\r\n    <input type=\"text\" name=\"record[address]\" id=\"data-address\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:500px\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n  \r\n        \r\n \r\n    <div id=\"555-F6757117143\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n    <b>Administrator (บัญชีผู้ดูแลระบบ)</b>\r\n            \r\n    </div>\r\n    \r\n    \r\n    \r\n    <div id=\"admin_login\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Username : </label></span>	\r\n    <input type=\"text\" name=\"admin[login]\" id=\"data-admin_login\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n    <div class=\"clear\"></div>\r\n    \r\n    <div id=\"admin_password\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Password : </label></span>	\r\n    <input type=\"password\" name=\"admin[password]\"  id=\"data-admin_password\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n        <div class=\"clear\"></div>\r\n\r\n    <div id=\"admin_password_confirmation\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Password : </label></span>	\r\n    <input type=\"password\" name=\"admin[password_confirmation]\" onkeyup=\"check_password(this)\" id=\"data-admin_password_confirmation\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">\r\n    </div>\r\n    \r\n    <script>\r\n    \r\n        function check_password(e){\r\n        }\r\n        \r\n        \r\n    </script>\r\n    \r\n    \r\n    \r\n    <div class=\"clear\">	</div>	\r\n    \r\n    </div>\r\n \r\n    <div class=\"clear\"></div>\r\n    \r\n    \r\n    </div>\r\n    </div>\r\n    </p>\r\n    <br/>\r\n    <button id=\"create\" class=\'btn btn-small btn-success\' style=\"width:200px;font-size:1.2em;\" disabled=\"disabled\">  ลงทะเบียน</button> \r\n    \r\n    <%= link_to \'ยกเลิก\', return_url %>\r\n    <% end %>\r\n    <span style=\"color:green\"><%=flash[:notice]%></span>\r\n    \r\n    <% end %>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>',NULL,NULL,NULL,'2016-05-12 06:16:55','2016-05-12 06:16:55','signup',''),(2229,'signup_confirm',921,2,'<div class=\"well\">\r\n    <div class=\"alert alert-warn\" style=\"min-height:200px;padding-top:100px\">\r\n    <h3><center>New customer and solution have been created</center></h3>\r\n    \r\n   \r\n    \r\n\r\n<%\r\n    models = get_model\r\n    # if request.post? and params[:solution]\r\n    #  s = params[:solution]\r\n    # if @current_user.login and s[:term]\r\n    \r\n    # esm = Esm.create :title=>s[:name].humanize , :name=>s[:name],:user_id=>@current_user.id\r\n    # app = models[:app].find(s[:app])\r\n    # if app\r\n    # app_tem = Project.find_by_package app.name\r\n    # www = esm.projects.create :title=>\'Www\', :name=>\'www\', :extended=>app_tem.package ,:package=>\"\\\\#{esm.name}.www\"\r\n    \r\n    # if s[:modules]\r\n    #     for i in s[:modules]\r\n    #         m = models[:app_module].find(i)\r\n    #         project = Project.find_by_package m.name\r\n    #         if project \r\n    #             app_module = esm.projects.create :title=>project.title, :name=>project.name, :extended=>project.package \r\n    #         end\r\n    #     end\r\n    \r\n    # end\r\n    # end\r\n    \r\n    \r\n    models = get_model\r\n    \r\n    \r\n    if request.post? and params[:solution] and params[:record]\r\n    \r\n    ##############################\r\n    \r\n    developer_user_login = \'super@esm-solution.com\'\r\n    \r\n    developer_user = User.find_by_login developer_user_login\r\n    \r\n    if developer_user\r\n        \r\n    %>\r\n    ------------------- User is OK <br/>\r\n    <%\r\n    \r\n    \r\n        \r\n    # pre conditions\r\n    \r\n    # 1 check solution\r\n    \r\n    # Management model\r\n    \r\n    # 0.1 create customer model\r\n    customer = models[:customer].where(:name=>params[:record][:name]).first\r\n    unless customer\r\n        customer = models[:customer].create(params[:record])\r\n    end\r\n    \r\n    # 0.2 create solution model\r\n    solution = models[:solution].where(:solution_name=>params[:solution][:solution_name]).first\r\n    unless solution   \r\n        solution = models[:solution].create(params[:solution])\r\n        solution.customer_id = customer.id\r\n        solution.save\r\n    end\r\n    \r\n    \r\n    package = models[:package].where(:name=>\'Trial\').first\r\n    \r\n    if package and solution\r\n        \r\n         models[:enrollment].create :solution_id=> solution.id, :package_id=>package.id, :start_date => Time.now \r\n           %>\r\n    ------------------- Package and Enrollment is OK <br/>\r\n    <%\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n    %>\r\n    ------------------- Customer is OK <br/>\r\n    <%\r\n    \r\n    # 1. create solution under super@esm-solution.com\r\n    \r\n    # 1.1 create solution ESM\r\n    # 1.2 create www project lifescope_master.www\r\n    # 1.3 create endo project lifescope_master.endo\r\n    \r\n    super_package_www = \'super_scope.www\'\r\n    super_package_app = \'super_scope.endo\'\r\n    \r\n    app_module = nil\r\n    \r\n    esm = Esm.find_by_name solution.solution_name\r\n    \r\n    unless esm\r\n    \r\n    esm = Esm.create :title=>customer.name , :name=>solution.solution_name,:user_id=>developer_user.id\r\n    # app = models[:app].find(s[:app])\r\n    # if app\r\n    \r\n    # app_tem = Project.find_by_package app.name\r\n    www = esm.projects.create :title=>\'Www\', :name=>\'www\', :extended=>super_package_www ,:package=>\"\\\\#{esm.name}.www\"\r\n    \r\n    # if s[:modules]\r\n        # for i in s[:modules]\r\n            # m = models[:app_module].find(i)\r\n            project = Project.find_by_package super_package_app\r\n            if project \r\n                app_module = esm.projects.create :title=>project.title, :name=>project.name, :extended=>super_package_app \r\n                \r\n                \r\n                \r\n                \r\n            end\r\n        # end\r\n    \r\n    # end\r\n    \r\n     %>\r\n    ------------------- Solution is OK <br/>\r\n    <%\r\nelse\r\n    \r\n    project = Project.find_by_package super_package_app\r\n\r\n    app_module = esm.projects.find_by_name project.name\r\n    \r\n    \r\n     %>\r\n    ------------------- Solution is not OK <br/>\r\n    <%\r\n    end\r\n    \r\n    mongo = Mongo::MongoClient.new(\"localhost\",27017)\r\n    \r\n    db = mongo.db(\"esm_emr-\\\\#{solution.solution_name}\")\r\n    \r\n    col = db.collection(\'www.role\')\r\n    \r\n    doc = {:name=>\'admin\'}\r\n    \r\n    admin_role = col.insert(doc) if col.count()==0\r\n    \r\n    \r\n    \r\n    col.insert( {:name=>\'user\'}) if col.find(:name=>\'user\').count()==0\r\n    \r\n  \r\n    if params[:admin]\r\n       \r\n       admin_role = col.find(:name=>\'admin\').to_a[0]\r\n       \r\n       \r\n  \r\n       \r\n       login = params[:admin][:login]\r\n       password = params[:admin][:password]\r\n        salt = User.random_string(10) \r\n        hashed_password = User.encrypt(password, salt)\r\n      \r\n        col = db.collection(\'www.user\')\r\n    \r\n        doc = { :login=> login, :salt=>salt, :hashed_password=>hashed_password, :role => admin_role[\'_id\'], :email=>customer.contact_email}\r\n        col.insert(doc) if col.count()==0\r\n        \r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    procedures = [\'EGD\', \'EGD + Colonoscopy\',\'Colonoscopy\',\'ERCP\',\'EUS\' , \'Sigmoidoscopy\', \'DBE\', \'ERCP + EUS\', \'EGD + Colonoscopy + EUS\',\'EGD + EUS\', \'Colonoscopy + EUS\',\'Liver biopsy\']\r\n    \r\n    col = db.collection(\'endo.procedure\')\r\n    \r\n    col.remove()\r\n    \r\n    \r\n    if col.count()==0\r\n        \r\n    for i in procedures\r\n    \r\n    doc = {:name=>i}\r\n    \r\n    col.insert(doc) \r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n    procedures = [\'Elective\', \'Emergency\', \'Special Clinic\']\r\n    procedures_ref_id = [\'0\',\'1\',\'2\']\r\n    \r\n    col = db.collection(\'endo.visit_type\')\r\n    \r\n    if col.count()==0\r\n    procedures.each_with_index do |i,index|\r\n    \r\n    doc = {:name=>i,:ref_id=>procedures_ref_id[index]}\r\n    \r\n    col.insert(doc)\r\n    \r\n    end\r\n    end\r\n    \r\n        \r\n    # 1.3.1 create all setting parameters \r\n            # logo_path \r\n            # logo_report_path \r\n            # report_title_1\r\n            # report_title_2\r\n            \r\n    \r\n    if app_module and app_module.settings.count == 0\r\n       \r\n       \r\n       # logo path\r\n       \r\n       app_module.settings.create :name=>\'report_title_1\', :value=> customer.name\r\n       app_module.settings.create :name=>\'report_title_2\', :value=> customer.commercial_name\r\n       \r\n        \r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    # class SuperScopeUser\r\n    #     include MongoMapper::Document\r\n    #     # connection(Mongo::Connection.new(\'localhost\', 27017))\r\n    #     set_database_name \"esm_emr-\\\\#{solution.solution_name}\"\r\n    # end\r\n    \r\n    # SuperScopeUser.create :login=>\'userx\'\r\n\r\n            \r\n            \r\n            \r\n    \r\n    # 2. create procedure and visit template\r\n    \r\n    # 3. create user and role [later]\r\n    # 3.1 create default admin role\r\n    # 3.2 create default admin user with password\r\n    \r\n    # 4. import list of providers [later]\r\n    \r\n    # 5. redirect to login page\r\n    \r\n    end\r\n    \r\n    end \r\n\r\n    # if @current_user.login and s[:term]\r\n    \r\n    # esm = Esm.create :title=>s[:name].humanize , :name=>s[:name],:user_id=>@current_user.id\r\n    # app = models[:app].find(s[:app])\r\n    # if app\r\n    # app_tem = Project.find_by_package app.name\r\n    # www = esm.projects.create :title=>\'Www\', :name=>\'www\', :extended=>app_tem.package ,:package=>\"\\\\#{esm.name}.www\"\r\n    \r\n    # if s[:modules]\r\n    #     for i in s[:modules]\r\n    #         m = models[:app_module].find(i)\r\n    #         project = Project.find_by_package m.name\r\n    #         if project \r\n    #             app_module = esm.projects.create :title=>project.title, :name=>project.name, :extended=>project.package \r\n    #         end\r\n    #     end\r\n    \r\n    # end\r\n    # end\r\n    \r\n    \r\n    # pre conditions\r\n    \r\n    # 1 check solution\r\n    \r\n    # Management model\r\n    \r\n    # 0.1 create customer model\r\n    # 0.2 create solution model\r\n    \r\n    \r\n    # 1. create solution under super@esm-solution.com\r\n    \r\n    # 1.1 create solution ESM\r\n    # 1.2 create www project lifescope_master.www\r\n    # 1.3 create endo project lifescope_master.endo\r\n    # 1.3.1 create all setting parameters \r\n            # logo_path\r\n            # logo_report_path\r\n            # report_title_1\r\n            # report_title_2\r\n    \r\n    # 2. create procedure and visit template\r\n    \r\n    # 3. create user and role [later]\r\n    # 3.1 create default admin role\r\n    # 3.2 create default admin user with password\r\n    \r\n    # 4. import list of providers [later]\r\n    \r\n    # 5. redirect to login page\r\n    \r\n    \r\n%>\r\n\r\n<br/><br/>\r\n<hr/>\r\nPlease visit this site : <br/>\r\n<center style=\"padding:50px\">\r\n<%=link_to \"\\\\#{solution.solution_name}.emr-life.com\", \"https://\\\\#{solution.solution_name}.emr-life.com\" ,:target=>\'_blank\', :class=>\'\', :style=>\"font-size:1.5em\" %>\r\n</center>\r\n\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-05-12 06:18:51','2016-05-12 06:18:51','signup_confirm',''),(2230,'index',922,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n  \r\n     model = get_model(this.table_name)\r\n\r\n    if params[:all]==\'true\'\r\n    records = model.all()\r\n    else\r\n    records = model.where({:deleted=>{\'$ne\'=>\'true\' }}).all()\r\n    end \r\n \r\n \r\n%>\r\n<div class=\"w-box\"  style=\" margin-left:auto; margin-right:auto;\" >\r\n									<div class=\"w-box-header\" style=\"font-size:20px\">\r\n						\r\n										<span style=\"float:right;padding-top: 5px;\"><a href=\"../Home/signup\" target=\"_blank\" class=\"btn btn-mini\"><i class=\"splashy-add_small\"></i>ลงทะเบียนใหม่</a></span>\r\n									</div>\r\n									<div class=\"w-box-content\" style=\"padding:20px;padding-top:10px\">\r\n									 \r\n<table class=\"table table-striped table-bordered table-condensed\">\r\n<tbody>\r\n  <tr>\r\n    <th align=\"left\">No.</th>\r\n    <th align=\"left\">Name</th>\r\n    <th align=\"left\">Commercial name</th>\r\n    <th>Solution</th>\r\n    <th>Active</th>\r\n    <th>Start at</th>\r\n    <th>Expiry at</th>\r\n    <th style=\"width:100px\">Remain days</th>\r\n    <th colspan=\"3\">Action </th>\r\n    \r\n  </tr>\r\n  <%  records.each_with_index do |i,index| \r\n  \r\n      models = get_model\r\n      solution = models[:solution].where(:customer_id=>i.id).first\r\n      enroll = nil\r\n      remain = nil\r\n      expried_at = nil\r\n      if solution\r\n            \r\n            enroll = models[:enrollment].where(:solution_id=>solution.id).first\r\n            if enroll\r\n                package = models[:package].where(:id=>enroll.package_id).first\r\n                if package\r\n                    remain = (package.period.to_i - (Time.now - enroll.start_date.to_datetime)/3600/24 ).ceil\r\n                    \r\n                    expried_at =( enroll.start_date.to_datetime+ package.period.to_i)\r\n                end\r\n                \r\n            end\r\n             \r\n      end\r\n  \r\n  %>\r\n  <tr>\r\n    \r\n    <% if i.deleted == \'true\'%>\r\n  \r\n    <td align=\"left\" width=\"50\"><%=index+1%>.</td>\r\n    <td align=\"left\" width=\"200\"><del><%=link_to i.name, \"edit?id=\\\\#{i.id}\" %></del></td>\r\n    <td align=\"left\" width=\"200\"><del><%=link_to i.commercial_name, \"edit?id=\\\\#{i.id}\" %></del></td>\r\n    <td  width=\"603\"><del><%=link_to solution.solution_name, \"../Solution/edit?id=\\\\#{solution.id}\"  if solution%></del></td>\r\n    \r\n    <% else %>\r\n    \r\n    <td align=\"left\" width=\"50\"><%=index+1%>.</td>\r\n    <td align=\"left\" width=\"200\"><%=link_to i.name, \"edit?id=\\\\#{i.id}\" %></td>\r\n    <td align=\"left\" width=\"200\"><%=link_to i.commercial_name, \"edit?id=\\\\#{i.id}\" %></td>\r\n    <td  width=\"603\"><%=link_to solution.solution_name, \"../Solution/edit?id=\\\\#{solution.id}\"  if solution%>\r\n      \r\n        \r\n    </td>\r\n    \r\n    <% end %>\r\n    \r\n    <td width=\"72\">\r\n    <% if solution and solution.active==\'true\' %>\r\n    <a href=\"../Home/account_info\" class=\"btn btn-mini btn-success\">OK</a>\r\n    <% else %>    \r\n    -\r\n    <% end %>\r\n    </td>\r\n\r\n    <td width=\"72\"><%= enroll.start_date.strftime(\"%d/%m/%Y\") if enroll %></td>\r\n    \r\n    <td width=\"72\"><%= expried_at.strftime(\"%d/%m/%Y\") if enroll and expried_at %></td>\r\n    \r\n    \r\n\r\n    <td width=\"72\">\r\n    <% if solution and solution.active==\'true\'\r\n\r\n    \r\n    %><%=remain%> days\r\n    <% else %>    \r\n    -\r\n    <% end %>\r\n    </td>\r\n    \r\n    <% if  solution and solution.active == \'true\' %>\r\n        <td width=\"72\"><a href=\"active?id=<%=solution.id if solution%>&active=false\" class=\"btn btn-mini\"> Inactive </a></td>\r\n   <% else %>\r\n        <td width=\"72\"><a href=\"active?id=<%=solution.id if solution %>&active=true\" class=\"btn btn-mini\"> Active </a></td>\r\n   <% end %>\r\n    \r\n        <td width=\"72\"><a href=\"renew?id=<%=i.id%>\" class=\"btn btn-mini\"> Renew </a></td>\r\n\r\n\r\n        <td width=\"72\">\r\n        \r\n        <%=link_to \'Remove\',  \"remove?id=\\\\#{i.id}\",:class=>\'btn btn-mini\',:data=>{:confirm=>\'Are you sure?\'} %>\r\n        \r\n    <!--\r\n    <td width=\"72\"><a href=\"#\" class=\"btn btn-mini\"><i class=\"splashy-document_a4_marked\"></i> invoice</a></td>\r\n  -->\r\n      \r\n      \r\n  </tr>\r\n  <% end %>\r\n  </tbody>\r\n</table>\r\n\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2016-05-12 06:20:15','2016-05-12 06:20:15','index',''),(2231,'index',932,2,'<h1>Admin Home</h1>\r\n\r\n\r\n<ul class=\"dshb_icoNav tac\">\r\n							\r\n    \r\n\r\n	<li><%=link_to \"Solution\",\r\n	\"../Solution/index\" %> </li>\r\n	\r\n	\r\n\r\n	<li><%=link_to \"Enrollment\",\r\n	\"../Enrollment/index\" %> </li>\r\n	\r\n	\r\n	\r\n	<li><%=link_to \"InvoiceItem\",\r\n	\"../InvoiceItem/index\" %> </li>\r\n\r\n\r\n	<li><%=link_to \"PaymentItem\",\r\n	\"../PaymentItem/index\" %> </li>\r\n	\r\n	\r\n</ul>',NULL,NULL,NULL,'2016-05-12 06:21:08','2016-05-12 06:21:08','index',''),(2232,'document_name',933,1,'\'enrollment\'',NULL,NULL,NULL,'2016-05-12 06:23:24','2016-05-12 06:23:24',NULL,NULL),(2233,'document_name',934,1,'\'invoice\'',NULL,NULL,NULL,'2016-05-12 06:30:25','2016-05-12 06:30:25',NULL,NULL),(2234,'document_name',935,1,'\'invoice_item\'',NULL,NULL,NULL,'2016-05-12 06:30:35','2016-05-12 06:30:35',NULL,NULL),(2235,'document_name',936,1,'\'payment\'',NULL,NULL,NULL,'2016-05-12 06:30:41','2016-05-12 06:30:41',NULL,NULL),(2236,'document_name',937,1,'\'payment_item\'',NULL,NULL,NULL,'2016-05-12 06:31:17','2016-05-12 06:31:17',NULL,NULL),(2237,'document_name',938,1,'\'contact\'',NULL,NULL,NULL,'2016-05-12 06:32:52','2016-05-12 06:32:52',NULL,NULL),(2238,'check_solution',921,3,'<% e = Esm.find_by_name params[:name] \r\n  unless e\r\n%>\r\n\"<%= params[:name] %>\" is ok\r\n<script>\r\n    $(\'#create\').removeAttr(\"disabled\");\r\n</script>\r\n<% else %>\r\n<span style=\"color:red\">\"<%=params[:name]%>\" has already existed!</span>\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-05-13 03:59:53','2016-05-13 03:59:53','check_solution',''),(2239,'index',939,3,'Test API <%=Time.now %>',NULL,NULL,NULL,'2016-05-15 14:57:28','2016-05-15 14:57:28','index','*'),(2240,'check_package',939,3,'<%\r\n    solution_name = params[:id]\r\n    \r\n    models = get_model\r\n    \r\n    solution = models[:solution].where(:solution_name=>solution_name).first\r\n    \r\n    result = {}\r\n    \r\n    if solution\r\n    \r\n        last_enrollment = models[:enrollment].where(:solution_id=>solution.id).first\r\n        # result[:data] =  solution.id\r\n        # result[:data2] = models[:enrollment].all\r\n        if last_enrollment\r\n           \r\n            package = models[:package].where(:id=>last_enrollment.package_id).first\r\n            \r\n            result[:return]=200\r\n            result[:msg]=\'OK\'\r\n            day = 0\r\n            day = (Time.now - last_enrollment.start_date.to_datetime)/3600/24\r\n            \r\n            remain = package.period.to_i - day\r\n            \r\n            result[:data]={:active=>solution.active, :start_date=>last_enrollment.start_date.to_datetime, :day=> day.to_i ,:remain=>remain.ceil}\r\n            \r\n            \r\n            \r\n        else\r\n            \r\n            result[:return]=404\r\n            result[:msg]=\'not found enrollment\'\r\n            \r\n        end\r\n        \r\n    else\r\n        result[:return]=404\r\n        result[:return]=\'not found solution\'\r\n    \r\n    end\r\n    \r\n    \r\n\r\n%><%=result.to_json.html_safe%>',NULL,NULL,NULL,'2016-05-15 15:08:05','2016-05-15 15:08:05','check_package','*'),(2241,'',939,3,'',NULL,NULL,NULL,'2016-05-15 15:08:14','2016-05-15 15:08:14','',''),(2244,'login',941,4,'<html>\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n\r\n <!-- Bootstrap framework -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap.min.css\" />\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap-responsive.min.css\" />\r\n        <!-- theme color-->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n        <!-- tooltip -->    \r\n			<link rel=\"stylesheet\" href=\"/gebo/lib/qtip2/jquery.qtip.min.css\" />\r\n        <!-- main styles -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/style.css\" />\r\n<style>\r\ninput, textarea, select, .uneditable-input { height:30px;}\r\n.login_page .cnt_b { padding:15px 0}\r\n</style>            \r\n</head>\r\n<body class=\"login_page\" style=\"background:url(/esm/ehr/my_module/surgeons-bg.jpg) center no-repeat;\r\nbackground-size: cover;\">\r\n<script src=\"/gebo/js/jquery.min.js\"></script>\r\n<script src=\"/gebo/js/jquery.actual.min.js\"></script>\r\n<script src=\"/gebo/lib/validation/jquery.validate.min.js\"></script>\r\n<script src=\"/gebo/bootstrap/js/bootstrap.min.js\"></script>\r\n<%\r\n	p = {}\r\n	if @current_project \r\n	tp = @current_project.get_params if @current_project \r\n	p = tp if tp\r\n	end\r\n	title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"ESM:Innovation as a Service\"\r\n	bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#eee\"\r\n	logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n%>\r\n\r\n<%\r\n    user = \'\'\r\n	user = params[:user][:login] if params[:user]\r\n%>\r\n<%= form_for :user, :action=>\'login\' do|form|%>\r\n            <center><a href=\"/\">\r\n            \r\n            <img src=\"/esm/super_scope/www/superlogo.png\" width=\"260\">\r\n            \r\n           \r\n            \r\n            </a><br/><br/>\r\n            </center>\r\n	<div class=\"login_box\" style=\"height:220px;top:0;bottom: 0;left: 0;right: 0;margin: auto;font-size:1.5em\">\r\n		\r\n		<form action=\"dashboard.html\" method=\"post\" id=\"login_form\">\r\n		\r\n			<% if flash[:error] %>\r\n			<div class=\"alert alert-info alert-login\">\r\n				<%= flash[:error] %>\r\n			</div>\r\n			<% else %>\r\n			<div class=\"alert alert-info alert-login\">\r\n				Please login to continue \r\n			</div>\r\n			<% end %>\r\n			\r\n			\r\n	   	\r\n\r\n			\r\n			<div class=\"cnt_b\">\r\n			\r\n					\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\" style=\"height:20px;padding:5px\"><i class=\"icon-user\"></i></span>\r\n						<%= form.text_field \"login\",:id=>\'user_login\',:placeholder=>\"Email or Login ID\",\'data-icon\'=>\"user\",:value=>user%>\r\n					   \r\n					</div>\r\n				</div>\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\" style=\"height:20px;padding:5px\"><i class=\"icon-lock\" ></i></span>\r\n						<%= form.password_field \"password\", :id=>\'user_password\',:placeholder=>\"Password\",\'data-icon\'=>\"closed-lock\"%>\r\n						\r\n					</div>\r\n				</div>\r\n					<%  unless @current_solution %>\r\n				<span id=\"solution_id_toggle\"><center><a href=\"javascript:$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\">...</a></center></span>	\r\n				<div class=\"formRow\" id=\"solution_id\" style=\"display:none\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-book\"></i></span>\r\n						<%= text_field_tag \"user[esm]\",cookies[:esm],:id=>\'esm\',:placeholder=>\"Solution ID\",\'data-icon\'=>\"settings\"%>\r\n					</div>\r\n				</div>\r\n				<script>\r\n				    $(document).ready(function(){\r\n				<% if cookies[:esm] %>\r\n					$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\r\n				<%  end %>\r\n			  });\r\n				</script>\r\n				\r\n					<% else %>\r\n						<%= form.hidden_field \"esm\", :value=> @current_solution.name %>\r\n						<%= form.hidden_field \"project_id\", :value=> @current_project.id if @current_project%>\r\n					<% end %>\r\n					\r\n					\r\n				<div class=\"formRow clearfix\">\r\n					<label class=\"checkbox\"><input id=\"ck\" name=\'remember\' type=\"checkbox\" /> Remember me</label>\r\n				</div>\r\n			\r\n			   \r\n			    \r\n			</div>\r\n			\r\n			\r\n			<div class=\"btm_b clearfix\" >\r\n				<button class=\"btn btn-inverse pull-right\" type=\"submit\">Sign In</button>\r\n				\r\n				<span class=\"link_reg\"><a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#terms\">Disclaimer</a></span>\r\n				\r\n			</div>  \r\n		</form>\r\n		\r\n		\r\n		\r\n		<div id=\"terms\" class=\"modal hide fade\">\r\n				<div class=\"modal-header\">\r\n					<a class=\"close\" data-dismiss=\"modal\">×</a>\r\n					<h3>Disclaimer</h3>\r\n				</div>\r\n				<div class=\"modal-body\">\r\n					<p>\r\n					ระบบนี้ออกแบบเพื่อใช้ในการเก็บข้อมูลทางการแพทย์เท่านั้น ห้ามนำข้อมูลในเว็บไซด์นี้ไปเผยแผ่หรือทำซ้ำโดยเด็ดขาด\r\n					</p>\r\n				</div>\r\n				<div class=\"modal-footer\">\r\n					<a data-dismiss=\"modal\" class=\"btn\" href=\"#\">Close</a>\r\n				</div>\r\n			</div>\r\n		\r\n	</div>\r\n	\r\n	<div class=\"links_b links_btm clearfix\" >\r\n	\r\n	\r\n	</div>\r\n		\r\n	</div>  \r\n   <% end %>\r\n\r\n    <script>\r\n        $(document).ready(function(){\r\n            \r\n			//* boxes animation\r\n			form_wrapper = $(\'.login_box\');\r\n            $(\'.linkform a,.link_reg a\').on(\'click\',function(e){\r\n				var target	= $(this).attr(\'href\'),\r\n					target_height = $(target).actual(\'height\');\r\n				$(form_wrapper).css({\r\n					\'height\'		: form_wrapper.height()\r\n				});	\r\n				$(form_wrapper.find(\'form:visible\')).fadeOut(400,function(){\r\n					form_wrapper.stop().animate({\r\n                        height	: target_height\r\n                    },500,function(){\r\n                        $(target).fadeIn(400);\r\n                        $(\'.links_btm .linkform\').toggle();\r\n						$(form_wrapper).css({\r\n							\'height\'		: \'\'\r\n						});	\r\n                    });\r\n				});\r\n				e.preventDefault();\r\n			});\r\n			\r\n			//* validation\r\n			$(\'#login_form\').validate({\r\n				onkeyup: false,\r\n				errorClass: \'error\',\r\n				validClass: \'valid\',\r\n				rules: {\r\n					username: { required: true, minlength: 3 },\r\n					password: { required: true, minlength: 3 }\r\n				},\r\n				highlight: function(element) {\r\n					$(element).closest(\'div\').addClass(\"f_error\");\r\n				},\r\n				unhighlight: function(element) {\r\n					$(element).closest(\'div\').removeClass(\"f_error\");\r\n				},\r\n				errorPlacement: function(error, element) {\r\n					$(element).closest(\'div\').append(error);\r\n				}\r\n			});\r\n        });\r\n    </script>\r\n\r\n\r\n		<script type=\"text/javascript\">\r\n	\r\n		try{document.getElementById(\'user_login\').focus();}catch(e){}\r\n		</script>\r\n	\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n\r\n    \r\n\r\n\r\n',NULL,NULL,NULL,'2016-05-15 15:38:02','2016-05-15 15:38:02','login',''),(2245,'check_access',941,3,'<%\r\n\r\nrequire \"net/http\"\r\nrequire \"uri\"\r\n\r\n    # data = `curl `\r\n    # uri = URI()\r\n    # data = Net::HTTP.get(uri)\r\n    \r\n    \r\n    \r\nrequire \'net/https\'\r\nuri = URI.parse(\"https://super_master.emr-life.com/www/Api/check_package?id=\\\\#{@current_solution.name}\")\r\nhttp = Net::HTTP.new(uri.host, uri.port)\r\nhttp.use_ssl = true\r\nhttp.verify_mode = OpenSSL::SSL::VERIFY_NONE\r\nrequest = Net::HTTP::Get.new(uri)\r\nresponse = http.request(request)\r\n    object = JSON.parse(response.body)\r\n    \r\n    if object[\'return\']==200\r\n        remain = object[\'data\'][\'remain\'].to_i\r\n        r_txt = \"\\\\#{remain} days\"\r\n        if remain > 365\r\n            r = remain / 365\r\n            r_txt = r > 1 ? \"\\\\#{r} months\" : \"\\\\#{r} month\"\r\n        elsif remain > 30\r\n            r = remain / 30\r\n            r_txt = r > 1 ? \"\\\\#{r} months\" : \"\\\\#{r} month\"\r\n        end\r\n        \r\n        be_active = false\r\n        \r\n        active = object[\'data\'][\'active\']\r\n        \r\n        if active == \'true\'\r\n            be_active = true\r\n        end\r\n        \r\n        session[:active] = be_active\r\n        \r\n%>\r\n<% if be_active %>\r\n<div class=\"alert alert-success\" style=\"font-size:1.2em\">\r\n    \r\n    Remaining usage <%= r_txt %> (<%= object[\'data\'][\'remain\']%>  days left)\r\n    \r\n</div>\r\n<script>\r\n        $(\'#enter-btn\').show();\r\n</script>\r\n<% else %>\r\n\r\n<div class=\"alert alert-danger\" style=\"font-size:1.2em\">\r\n    ขออภัยขณะนี้ระบบถูกระงับการใช้งาน \r\n     กรุณาติดต่อผู้ดูแลระบบ 02-xxx-xxxx\r\n    <br/><br/>\r\n   The solution has not been actived !!\r\n   Please contact administrator.\r\n    \r\n</div>\r\n<script>\r\n    $(\'#enter-btn\').attr(\'disabled\',\'disabled\');\r\n    $(\'#enter-btn\').remove();\r\n</script>\r\n<% end %>\r\n\r\n<% else %>\r\n<div class=\"box box-info\">\r\n    \r\n    Error : <%= object[\'msg\']%>\r\n    \r\n</div>\r\n\r\n<% \r\n    end \r\n    session[:active] = be_active\r\n%>\r\n<script>\r\n    $(\".se-pre-con\").fadeOut(\"slow\");\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2016-05-15 15:43:47','2016-05-15 15:43:47','check_access','*'),(2246,'index',941,2,'...\r\n<style>\r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	/*position: fixed;*/\r\n	position: absolute;\r\n	left: 0px;\r\n	top: 10px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat ;\r\n}\r\n\r\n.text-loading {\r\n    -webkit-animation-name: blinker;\r\n    -webkit-animation-duration: 1s;\r\n    -webkit-animation-timing-function: linear;\r\n    -webkit-animation-iteration-count: infinite;\r\n    \r\n    -moz-animation-name: blinker;\r\n    -moz-animation-duration: 1s;\r\n    -moz-animation-timing-function: linear;\r\n    -moz-animation-iteration-count: infinite;\r\n    \r\n    animation-name: blinker;\r\n    animation-duration: 1s;\r\n    animation-timing-function: linear;\r\n    animation-iteration-count: infinite;\r\n}\r\n\r\n@-moz-keyframes blinker {  \r\n    0% { opacity: 1.0; }\r\n    50% { opacity: 0.0; }\r\n    100% { opacity: 1.0; }\r\n}\r\n\r\n@-webkit-keyframes blinker {  \r\n    0% { opacity: 1.0; }\r\n    50% { opacity: 0.0; }\r\n    100% { opacity: 1.0; }\r\n}\r\n\r\n@keyframes blinker {  \r\n    0% { opacity: 1.0; }\r\n    50% { opacity: 0.0; }\r\n    100% { opacity: 1.0; }\r\n}\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n    \r\n    <center>\r\n    <img src=\"http://www.thaitage.org/Thai/images/logo_new.gif\" style=\"padding:20px;width:120px\"><br />\r\n    <div class=\"well\" style=\'width:720px\'>\r\n    ระบบนี้ออกแบบเพื่อใช้ในการเก็บข้อมูลทางการแพทย์เท่านั้น ห้ามนำข้อมูลในเว็บไซด์นี้ไปเผยแผ่หรือทำซ้ำโดยเด็ดขาด\r\n    \r\n    \r\n    <div class=\'clear\'></div>\r\n    <div style=\'margin-top:20px\'></div>\r\n        	<div id=\"check_access\">\r\n        	    <span class=\'text-loading\'>... กำลังตรวจสอบสถานะ  กรุณารอสักครู่ ...</span>\r\n        	</div>\r\n            <!--<div class=\"se-pre-con\"></div>-->\r\n        \r\n        <div class=\'clear\'></div>\r\n        <div style=\'margin-top:20px\' class=\"\">\r\n            <a href=\"../../endo/Home/index\" class=\"btn hide\" id=\"enter-btn\"><< เข้าสู่โปรแกรม >></a></center>\r\n        </div>\r\n        \r\n    </div>\r\n \r\n    \r\n    \r\n</div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n\r\n<script>\r\n    \r\n    $.ajax({url: \"/www/Home/check_access\", success: function(result){\r\n        $(\"#check_access\").html(result);\r\n    }});\r\n</script>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-05-16 05:06:31','2016-05-16 05:06:31','',''),(2247,'layout',941,4,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n		\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n		    <title><%=title%></title>\r\n\r\n				<script>\r\n					$(document).ready(function() {\r\n						//* show all elements & remove preloader\r\n						// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n						 // $(\"html\").removeClass(\"js\");\r\n					});\r\n				</script>\r\n		\r\n				 <style>\r\n    .w-box-content.cnt_a {background: #fff;}\r\n    .k-grid table {font-size: 1em;}\r\n.k-calendar .k-content {font-size: 1em;padding-top:5px;}\r\n.k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\nheight: 25px;}\r\n.field-data {\r\nwidth: 220px;}\r\n\r\ninput{\r\n    height:25px;\r\n}\r\n</style>\r\n		\r\n		\r\n    </head>\r\n    <body style=\"background:url(\'/esm/ehr/my_module/surgeons-bg.jpg\');padding:10px;font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\">\r\n	\r\n<a href=\"../../www/Home/index\"><img src=\"/esm/super_scope/www/superlogo.png\" width=\"200px\"></a>\r\n<span style=\"float:right;color:#efefef;font-size:1.2em\" >\r\n<%\r\n    cur_user = get_model[:user].where(:login=>@current_user.login.to_s).first\r\n    usr_name = !cur_user.nil? ? \"\\\\#{cur_user[:name]} (\\\\#{@current_user.login})\" : @current_user.login\r\n%>\r\n    <%= usr_name %> | <%=link_to \'Logout\',\'/user/logout\' %>\r\n</span>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n					</div>\r\n</hr>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\" style=\"padding:0px;\">\r\n\r\n				   <%= yield %><%= yield :content%>\r\n                \r\n                </div>\r\n            </div>\r\n     \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n     		<div id=\"context-menu\" class=\"accordion\">\r\n             <%= render :partial=>\'/layouts/context_menu\'%>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n			$(\'#search-field\').focus()\r\n		</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2016-05-16 06:08:39','2016-05-16 06:08:39','',''),(2248,'layout',942,4,'<%\r\n    if @current_role != \'developer\'\r\n        if session[:active].nil?\r\n            session[:acive] = false\r\n        end\r\n    \r\n        if !session[:active]\r\n%>\r\n<script>\r\n    alert(\'No permission to access !!! Please contact your administrator.\');\r\n    window.location = \'../../www/Home/index\';\r\n</script>\r\n<%\r\n        end\r\n    end\r\n%>\r\n\r\n<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n		\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n		    <title><%=title%></title>\r\n\r\n				<script>\r\n					$(document).ready(function() {\r\n						//* show all elements & remove preloader\r\n						// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n						 // $(\"html\").removeClass(\"js\");\r\n					});\r\n				</script>\r\n		\r\n				 <style>\r\n    .w-box-content.cnt_a {background: #fff;}\r\n    .k-grid table {font-size: 1em;}\r\n.k-calendar .k-content {font-size: 1em;padding-top:5px;}\r\n.k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\nheight: 18px;}\r\n.field-data {\r\nwidth: 220px;}\r\n\r\ninput{\r\n    height:18px;\r\n}\r\n</style>\r\n		\r\n		\r\n    </head>\r\n    <body style=\"background:url(\'/esm/ehr/my_module/surgeons-bg.jpg\');padding:10px\">\r\n<a href=\"../../www/Home/index\">	\r\n<img src=\"/esm/super_scope/www/superlogo.png\" width=\"200px\"></a>\r\n<span style=\"float:right;color:#efefef;font-size:1.2em\" >\r\n<%\r\n    cur_user = get_model[:provider].where(:login=>@current_user.login.to_s).first\r\n    usr_name = !cur_user.nil? ? \"\\\\#{cur_user[:name]} (\\\\#{@current_user.login})\" : @current_user.login\r\n%>\r\n    <%= usr_name %> | <%=link_to \'Logout\',\'/user/logout\' %>\r\n</span>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n						<div class=\"span12\">\r\n							<ul class=\"dshb_icoNav tac\">\r\n								<li><a href=\"../Home/index\" style=\"background-image: url(/gebo/img/gCons/home.png)\"> Home</a></li>\r\n								<li><a href=\"../Appointment/index\" style=\"background-image: url(/gebo/img/gCons/calendar.png)\">Calendar</a></li>\r\n								<li><%= link_to \'Reports\',\"../Report/case_reports\",:style=>\'background-image: url(/gebo/img/gCons/bar-chart.png)\' %></li>\r\n								<li><a href=\"../Setting/index\" style=\"background-image: url(/gebo/img/gCons/configuration02.png)\">Settings</a></li>\r\n				<li><a href=\"../Help/index\" style=\"background-image: url(/gebo/img/gCons/happy-face.png)\">Help</a></li>\r\n						 </ul>		\r\n			\r\n						</div>\r\n					</div>\r\n</hr>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\" style=\"padding:0px;\">\r\n<% if params[:service] == \'Report\'  %>\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Report</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\" style=\"padding:10px\">\r\n                <%= yield %><%= yield :content%>\r\n            </div>\r\n        </div>\r\n<% else %>\r\n				   <%= yield %><%= yield :content%>\r\n<% end %>\r\n    </div>\r\n</div>\r\n     \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n     		<div id=\"context-menu\" class=\"accordion\">\r\n             <%= render :partial=>\'/layouts/context_menu\'%>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n			$(\'#search-field\').focus()\r\n		</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2016-05-16 06:10:19','2016-05-16 06:10:19','',''),(2249,'remove',922,2,'\r\n<%  \r\n    if params[:id]\r\n\r\n    models = get_model\r\n    \r\n    customer = models[:customer].find(params[:id])\r\n    solutions = models[:solution].where(:customer_id=>customer.id).all\r\n    enrollments = models[:enrollment].where(\'solution_id\'=>{\'$in\'=>solutions.collect{|i| i.id} }).all\r\n    \r\n    customer.active = \'false\'\r\n    customer.deleted = true\r\n    customer.save\r\n    \r\n%>\r\nremoved..\r\n\r\n<meta http-equiv=\"refresh\" content=\"0; url=index\" />\r\n\r\n\r\n\r\n<% end %>',NULL,NULL,NULL,'2016-05-17 02:51:18','2016-05-17 02:51:18','remove',''),(2250,'renew',922,2,'renew',NULL,NULL,NULL,'2016-05-17 02:51:31','2016-05-17 02:51:31','renew',''),(2251,'active',922,2,'active...\r\n\r\n\r\n\r\n<%  \r\n    if params[:id]\r\n\r\n    models = get_model\r\n    \r\n    solution = models[:solution].find(params[:id])\r\n  \r\n    \r\n    # solution = models[:solution].find(solution.id)\r\n \r\n   solution.update_attributes :active=>params[:active]\r\n\r\n%><meta http-equiv=\"refresh\" content=\"0; url=index\" />\r\n\r\n\r\n<% end %>',NULL,NULL,NULL,'2016-05-17 02:55:10','2016-05-17 02:55:10','active',''),(2252,'index_ajax',942,2,'<%\r\n    module_name = @current_project.name\r\n    if params[:date]\r\n        session[module_name]={:date=>params[:date]}\r\n    end\r\n    if session[module_name]\r\n        params[:date] = session[module_name][:date]\r\n    end\r\n    unless params[:date]\r\n        params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n    end\r\n \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %><%= error%>\r\n    <%\r\n    session.delete :s_date\r\n    end\r\n     %>\r\n        <%\r\n    search_patient = false\r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n          end\r\n        session[:s_status] = s_status\r\n         session[:s_provider] = s_provider \r\n        \r\n    end\r\n    if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Add & Continue\"\r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n</script>\r\n<%\r\n        end\r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       <b>Home : <%= date.strftime(\'%d/%m/%Y\') %></b>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n            <div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>params[:opt], :html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\">Date : </label>\r\n                    <div class=\"field-input\" >\r\n                        <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\">HN : </label>\r\n                    <div class=\"field-input\">\r\n                        <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n                    </div>\r\n                </span>\r\n            \r\n                <span class=\"field-data\" style=\"margin-top:5px\"> \r\n                        <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                        <%=link_to \'Advanced Search\', \'javascript:void(0)\', :id=>\'btn-advanced_search\', :class=>\'btn\'%>\r\n                </span>\r\n                \r\n                <div class=\"clear\"></div>\r\n\r\n                <span class=\"field-data\">\r\n                    <label class=\"field-label\">&nbsp;</label>\r\n                    <div class=\"field-input\">\r\n                        <%=link_to \'Add Patient\', \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\',:style=>\'margin-top:10px\'%>\r\n                    </div>\r\n                </span>\r\n\r\n            <div class=\"clear\"></div>\r\n            \r\n            <script>\r\n                $(\'#search_hn\').focus();\r\n            </script>\r\n<% end %>\r\n        </div>\r\n        \r\n        </div>\r\n        <!--DATE : <%# date %>-->\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%#params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n# SEARCH SECTION    \r\n    if search_patient\r\n        \r\n        fields = {:hn=>s_hn, :first_name=>s_hn, :last_name=>s_hn}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n    \r\n        if keys.size>0\r\n            conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n            criteria = {\'$or\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n    \r\n        patients = patient_model.where(criteria).limit(20).all  \r\n        maps = module_model.all     :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n        aps = ap_model.find(maps.collect{|i| i.module_id})\r\n%>\r\n<!--<%= params[:search].to_json.html_safe %>-->\r\n<%\r\n        if aps.count == 1 # and @current_role==\'developer\' \r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= aps.first.id.to_s %>\';\r\n</script>\r\n<%\r\n        end\r\n\r\n    elsif pad = params[:adv_pat]\r\n        adv = params[:advanced]\r\n        fields = {:provider=>adv[:provider], :visit_type=>adv[:visit_type], :indication=>adv[:indication], :procedure=>adv[:procedure]}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>v} if v and v!=\'\' \r\n        end\r\n        \r\n        if keys.size>0\r\n            criteria = {\'$and\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n        \r\n        # patient criteria\r\n        fs = {:first_name=>pad[:fname], :last_name=>pad[:lname]}\r\n        ks = []\r\n        fs.each_pair do |k, v|\r\n            ks <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n        if ks.size>0\r\n            cr = {\'$or\'=>ks}\r\n        else\r\n            cr ={}\r\n        end\r\n        \r\n        a_app = []\r\n        if !criteria.empty?\r\n            a_app = ap_model.where(criteria).all\r\n        end\r\n        \r\n        a_pat = []\r\n        if !cr.empty?\r\n            a_pat = patient_model.where(cr).all\r\n        end\r\n        \r\n        if !a_app.empty? and cr.empty?\r\n            aps = a_app\r\n        elsif a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(maps.collect{|i| i.module_id})\r\n        elsif !a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(a_app.collect{|i|i.id} & maps.collect{|i| i.module_id})\r\n        else\r\n            aps = ap_model.limit(20).all\r\n        end\r\n    else\r\n    \r\n        conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n        if s_provider and s_provider !=\'\'\r\n            conds.merge! :provider=>s_provider \r\n        end\r\n\r\n        if s_status and s_status != \"\"\r\n            conds.merge! :status=>s_status \r\n        end\r\n    \r\n        aps = ap_model.all(conds)\r\n\r\n    end\r\n     \r\n         \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\#{m.id}&return=../Home/index\") if patient\r\n         public_id = \'-\'\r\n         bdate = i.date.strftime(\'%d/%m/\').to_s + (i.date.strftime(\'%Y\').to_i + 543).to_s\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\#{patient.prefix_name} \\#{patient.first_name} \\#{patient.last_name}\",\"patient_record?id=\\#{i.id}\"),\r\n         :provider=>provider_name,:date=>i.date.strftime(\'%d/%m/%Y\'),:note=>\"\\#{visit_type} \\#{indications[i.indication]} \\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type, :patient_id=>patient.id\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{date hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    \r\n        labels = {:no=>\'No.\', :date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Action\', :procedure=>\'Procedure\' }\r\n    \r\n    %>\r\n<% if true %>\r\n<%\r\n        app_a = []\r\n        app_c = []\r\n        aps.each do |i|\r\n            if i[:status] == \'Completed\'\r\n                app_c << i\r\n            else\r\n                app_a << i\r\n            end\r\n        end\r\n%>\r\n<div id=\'default-panel\' style=\'padding:5px\'>\r\n    <div class=\"tabbable\">\r\n        <ul class=\"nav nav-tabs\">\r\n            <li class=\"active\"><a href=\"#appointed\" data-toggle=\"tab\">Appointed (<%= app_a.count %>)</a></li>\r\n            <li><a href=\"#completed\" data-toggle=\"tab\">Completed (<%= app_c.count %>)</a></li>\r\n        </ul>\r\n        <div class=\"tab-content\">\r\n            <div class=\"tab-pane active\" id=\"appointed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_a,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\#{row[:patient_id]}&return=\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n            <div class=\"tab-pane\" id=\"completed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_c,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\#{row[:patient_id]}&return=\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<% end %>\r\n\r\n<% if false %>\r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    # out[0] = count.to_s+\".\"\r\n                    out[0] = link_to(count.to_s+\".\", \"../../www/Patient/edit?id=\\#{patient.id}&return=\\#{request.fullpath}\").html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n        </div>\r\n<% end %>        \r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n <script>\r\n function change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"<%=params[:opt]%>?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n\r\n<% if false %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Encounter</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n\r\n    \r\n   \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n<% end  %>\r\n<div class=\"alert \">\r\n<%# link_to \'Total Status\',\'total_status?print[date]=\'+params[:date], :target=>\'_blank\' %>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<!--<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date],class: \'btn btn-mini\' %> |-->\r\n<%= link_to \'Status Feed\',\'total_status?print[date]=\'+params[:date],class: \'btn btn-mini\', :target=>\'_blank\' %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date],class: \'btn btn-mini\' %> | \r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date],class: \'btn btn-mini\' %> |\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n<%\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"myModal2\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Modal header</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n									Lorem ipsum dolor sit amet, consectetur adipiscing elit. Pellentesque non elit tellus, eleifend varius erat. Lorem ipsum dolor sit amet, consectetur adipiscing elit. In bibendum laoreet ante sodales elementum. Nullam varius interdum est, at ornare quam aliquam eu. Nulla ultricies commodo leo sit amet vulputate.\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n							</div>\r\n	\r\n<div class=\"modal hide fade\" id=\"modal2\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Advanced Search</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n        \r\n<%= form_for :advanced , :url=>params[:opt] do |f| %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name  : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[first_name]\" id=\"data-fname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[last_name]\" id=\"data-lname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <%= f.submit \'Search\', :class=>\'btn btn-success\' %>\r\n                <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a> \r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n							\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                <br/>\r\n                <div id=\"patient_msg\"></div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Add & Continue\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n</script>\r\n\r\n<script>\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#data-hn\').change(update_patient);\r\n    });\r\n</script>',NULL,NULL,NULL,'2016-05-17 03:07:02','2016-05-17 03:07:02','index_ajax',''),(2253,'index_partial',942,3,'...',NULL,NULL,NULL,'2016-05-17 03:07:22','2016-05-17 03:07:22','index_partial',''),(2255,'document_name',944,1,'\'registration\'',NULL,NULL,NULL,'2016-05-17 03:53:59','2016-05-17 03:53:59',NULL,NULL),(2256,'create',944,3,'<%\r\n    txt = \"\"\r\n%>\r\n<html>\r\n\r\n    <head>\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n        <%=include_header%>\r\n        <style>\r\n\r\n    input{\r\n \r\n        height:24px;\r\n            }\r\n  \r\n\r\n</style>\r\n    </head>\r\n        \r\n<body style=\"width:720px; margin-left:auto; margin-right:auto; background:url(/esm/reg_cms/www/bgcolo.jpg) center no-repeat;\r\nbackground-size: cover;\">\r\n       \r\n<div class=\"row-fluid\" style=\"margin-top:30px\">\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"font-size:16px; border-top:1px #ddd solid; background:#fff;width:660px;padding:30px;\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'create\')\r\n  \r\n  return_url = params[:return] if params[:return]\r\n  lm = 50  # default limit (round 1 - 4 limit at 15)\r\n  ex = 70 # extra limit   (round 1 - 4 extra at 50)\r\n  se = 7   # extra study_date registration (round 1 - 4 sr=3)\r\n  rd = {nil=>0, 0=>0, 1=>15, 2=>15, 3=>50, 4=>14, 5=>50, 6=>50, 7=>150, 8=>70, 9=>100, 10=>100}\r\n  pl = [1,2,3,4,5,6,7,8] # previous round\r\n  if request.post?\r\n        sr = params[:record][:study_date] # study_date\r\n        ar = get_model[:registration].where(:study_date=>sr).all\r\n      \r\n        num_limit = rd[sr.to_i]\r\n    #   if sr == se.to_s\r\n    \r\n        #     num_limit = ex\r\n        # end\r\n        if ar.count >= num_limit\r\n%>\r\n<script>\r\n    alert(\'(<%= ar.count %>) รอบการอบรมเต็มแล้ว กรุณาเลือกรอบอบรมใหม่ค่ะ\')\r\n</script>\r\n<%\r\n            return_url = url(\'create\')\r\n        else\r\n      \r\n      \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    return_url = url(\'confirm\')\r\n    \r\n        end\r\n        \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<%# params.to_json.html_safe %>\r\n<script type=\"text/javascript\">\r\n    \r\n    window.location = \"<%= return_url.html_safe %>\"\r\n\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n\r\n\r\n<div>\r\n    <img src=\"/esm/rrts_center/www/Chula logo red cross.png\" width=\"300px\">\r\n    <img src=\"/esm/rrts_center/www/EC-CCN logo.png\" width=\"300px\">\r\n</div>\r\n<br/>\r\n<center><h1 style=\'color:#0F5082\'>CRRT Course Registation</h1></center>\r\n<center>\r\n    <h3 style=\'color:#0F5082\'>\r\n        <%= txt %>\r\n    </h3>\r\n</center>\r\n<div class=\"control-group \" style=\"width:650px\"><hr/></div>\r\n<h3>ลงทะเบียน</h3><br/>\r\n<%= this.form.html_safe %>\r\n<br/>\r\n<div>\r\n    <input type=\'submit\' class=\'btn btn-small btn-success\' style=\"width:200px;font-size:1.2em;\" value=\"ลงทะเบียน\">\r\n</div>\r\n\r\n<%# link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n<div id=\'js-js\'>\r\n<script>\r\n      $(\'#form-data\').css(\"width\",\"660px\")\r\n\r\n    $(\'#form-data div:first-child\').first().css(\"width\",\"660px\")\r\n<%\r\n    reg_group = get_model[:registration].all\r\n    rg = reg_group.group_by{|i| i[:study_date]}\r\n    rg.each do |k, v|\r\n        x = v.count\r\n        i = k.to_i - 1\r\n        \r\n        num_limit = rd[k.to_i]\r\n        # if i == (se - 1)\r\n        #     num_limit = ex\r\n        # end\r\n        if x >= num_limit\r\n%>\r\n    console.log(\'K : <%= k %>, V : <%= v.count %>\');\r\n    $(\'#update_study_date_item_<%= i %>\').attr(\'disabled\',true);\r\n    $(\'#update_study_date_item_<%= i %>\').parent().append(\'<br/><font color=\"red\">(เต็มแล้วค่ะ)</font>\');\r\n<%\r\n        else\r\n%>\r\n    $(\'#update_study_date_item_<%= i %>\').parent().append(\'<br/><font color=\"blue\">(เหลือจำนวน <%= num_limit - x %> ท่านค่ะ)</font>\');\r\n<%\r\n        end\r\n    end\r\n    \r\n    pl.each do |i|\r\n%>\r\n    $(\'#update_study_date_item_<%= i - 1 %>\').parent().parent().parent().remove();\r\n<% \r\n    end # pl\r\n%>\r\nconsole.log(\'<%= rg.keys.to_json.html_safe %>\')\r\n    function aaa() {\r\n        alert(\'xxx\');\r\n    }\r\n\r\n    $(\'#js-js\').hide();\r\n    \r\n</script>\r\n</div>\r\n    </body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-05-17 04:13:22','2016-05-17 04:13:22','create','*'),(2257,'index',943,2,'<%= render :inline=>this.init %>\r\n<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% -34px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .collapsed {\r\n        background-position: 98% 12px;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n    \r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	/*position: fixed;*/\r\n	position: absolute;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat #144884;\r\n}\r\n</style>\r\n    <!-- nice form elements -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/uniform/Aristo/uniform.aristo.css\" />\r\n	<!-- 2col multiselect -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/multiselect/css/multi-select.css\" />\r\n\r\n<%\r\n    msg = []\r\n    tmp = nil\r\n    suc_msg = nil\r\n    \r\n    if request.post?\r\n        if !params[:account].nil? and !params[:add_new].nil?\r\n\r\n            acc = params[:account]\r\n            \r\n            if acc[:login_name].empty?\r\n                msg.push(\'Invalid login name\')\r\n            end\r\n            # if params[:account][:full_name].empty?\r\n            #     msg.push(\'Invalid full name\')\r\n            # end\r\n            if acc[:password].empty?\r\n                msg.push(\'No password found\')\r\n            end\r\n            \r\n            full_name = acc[:prefix].strip + acc[:first_name].strip + \" \" + acc[:last_name].strip\r\n            full_name = full_name.strip\r\n            if full_name == \'\'\r\n                msg.push(\'Invalid name\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>params[:account][:login_name]).first\r\n                if m_user\r\n                    msg.push(\'Existing login name\')\r\n                else\r\n                    r_provider = @models[:provider].where({\'name\' => Regexp.new( full_name )})\r\n                    create_user = false\r\n                    # a_prov = m_prov.where({\'name\' => Regexp.new(\'\')})\r\n                    if r_provider.count == 0\r\n                        m_provider = @models[:provider].create :group=>\'default\', :name=>full_name, :prefix=>acc[:prefix], :first_name=>acc[:first_name], :last_name=>acc[:last_name], :login=>params[:account][:login_name], :provider_type=>params[:account][:provider_type]\r\n                        create_user = true\r\n                    elsif r_provider.count == 1\r\n                        m_provider = r_provider.first.update_attributes :login=>params[:account][:login_name]\r\n                        create_user = true\r\n                    else\r\n                        name_list = r_provider.collect{|i| i[:name]}\r\n                        msg.push(\"Existing name (\\\\#{name_list.count}) : \" + name_list.join(\', \'))\r\n                    end\r\n                    \r\n                    if create_user \r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(params[:account][:password], salt)\r\n                        tmp = salt + \'...\' + hashed_password\r\n                        m_user = @ehr_models[:user].create :role=>params[:account][:role], :login=>params[:account][:login_name], :salt=>salt, :hashed_password=>hashed_password, :email=>params[:account][:email], :name=>full_name, :activate=>\"true\"\r\n                        tmp = m_user.id.to_s\r\n                        # tmp += \'...\' + m_provider.id.to_s\r\n                    end\r\n                    \r\n                end\r\n            end\r\n        elsif !params[:account].nil? and !params[:update].nil?\r\n            acc = params[:account]\r\n            \r\n            full_name = acc[:prefix].strip + acc[:first_name].strip + \" \" + acc[:last_name].strip\r\n            full_name = full_name.strip\r\n            if full_name == \'\'\r\n                msg.push(\'Invalid name\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>acc[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>acc[:login_name]).first\r\n                \r\n                m_prov[:name] = full_name\r\n                m_prov[:prefix] = acc[:prefix]\r\n                m_prov[:first_name] = acc[:first_name]\r\n                m_prov[:last_name] = acc[:last_name]\r\n                m_prov[:provider_type] = acc[:provider_type]\r\n                m_prov.save\r\n                \r\n                suc_msg= \"<b>Success</b> Account <b>\\\\#{acc[:login_name]}</b> has been updated\".html_safe\r\n                \r\n                if acc[:password].strip != \'\'\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(acc[:password], salt)\r\n                    m_user[:hashed_password] = hashed_password\r\n                    m_user[:salt] = salt\r\n                    # m_user.save\r\n                    suc_msg= \"<strong>Success</strong> Account <b>\\\\#{acc[:login_name]}</b> profile and password has been updated\".html_safe\r\n                end\r\n                \r\n                m_user[:name] = full_name\r\n                m_user[:email] = acc[:email]\r\n                m_user[:role] = acc[:role]\r\n                m_user.save\r\n            end\r\n            \r\n        elsif !params[:profile].nil?\r\n            px = params[:profile]\r\n            if px[:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if px[:cur_password].empty?\r\n                msg.push(\'No password to confirm your change\')\r\n            else\r\n                if px[:new_password] != px[:con_password]\r\n                    msg.push(\"Your confirm password not match the new password. Try again.\")\r\n                end\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>px[:login_name]).first\r\n                salt = m_user[:salt]\r\n                hashed_password = User.encrypt(px[:cur_password], salt)\r\n                if m_user[:hashed_password] == hashed_password\r\n                    if px[:con_password] == px[:new_password] and px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        suc_msg= \"<strong>Success</strong> Your profile has been change\".html_safe\r\n                    elsif px[:con_password] == px[:new_password] and !px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(px[:new_password], salt)\r\n                        m_user[:hashed_password] = hashed_password\r\n                        m_user[:salt] = salt\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your profile and password has been change\".html_safe\r\n                    else\r\n                        msg.push(\'Your new and confirm password does not match\')\r\n                    end\r\n                    \r\n                else\r\n                    msg.push(\'Your current password does not match\')\r\n                end\r\n                # msg.push(px[:login_name])\r\n            end\r\n        else\r\n            if @current_role == \'developer\'\r\n%>\r\n<pre>\r\n    <%= params.inspect %>\r\n</pre>\r\n<%\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n\r\n<%\r\n    # checking the provider\r\n    prov = @models[:provider].where(:provider_type=>\'1\').all\r\n    if prov.empty?\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"modal-provider\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>ข้อแนะนำ</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n									ไม่พบรายชื่อแพทย์ในระบบ กรุณาคลิกที่ปุ่ม\r\n									\r\n									<ul class=\"dshb_icoNav tac\"  style=\'display:inline\'>\r\n									    <li><a style=\"background-image: url(/gebo/img/gCons/multi-agents.png)\" href=\"javascript:void(0);\">\r\n										    User Account</a></li>\r\n									</ul>\r\n									<!--<img src=\"/gebo/img/gCons/multi-agents.png\" alt=\"\" />-->\r\n									\r\n									เพื่อเพิ่มบัญชีผู้ใช้และรายชื่อแพทย์\r\n									<br/>\r\n									หรือคลิกที่ปุ่ม\r\n									\r\n									<ul class=\"dshb_icoNav tac\" style=\'display:inline\'>\r\n									    <li><a style=\"background-image: url(/gebo/img/gCons/agent.png)\" href=\"javascript:void(0);\">\r\n										    Provider</a></li>    \r\n									</ul>\r\n									<!--<img src=\"/gebo/img/gCons/agent.png\" alt=\"\" />-->\r\n									\r\n									เพื่อเพิ่มรายชื่อแพทย์\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">รับทราบ</a>\r\n								</div>\r\n							</div>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\'#modal-provider\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n        \r\n        $(\'#btn-add_patient\').off(\'click\');\r\n    });\r\n</script>\r\n<%\r\n    end\r\n%>\r\n\r\n<%#list.inspect%>\r\n<div class=\"se-pre-con\"></div>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                            <div id=\"accordion1\" class=\"accordion\">\r\n<%\r\n    # check admin or developer role\r\n    a_role = @ehr_models[:role].all\r\n    \r\n    map_role = {}\r\n    map_role[\'\']  = \'Na\'\r\n    map_role[nil] = \'N/A\'\r\n    for a in a_role do\r\n        map_role[a.id.to_s] = a[:name]\r\n    end\r\n    if @current_role == \'admin\' or @current_role == \'developer\'\r\n        usr = @ehr_models[:user].all.collect do |i|\r\n            # role = @ehr_models[:role].find(i.role)\r\n            # role_name = \'undefined\'\r\n            # if role\r\n            #     role_name = role[:name]\r\n            # end\r\n            role_name = map_role[i.role.to_s]\r\n            provider = @models[:provider].where(:login=>i.login).first\r\n            \r\n            if provider\r\n                {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :i=>i}\r\n            end\r\n        end\r\n%>\r\n<%\r\n    if !msg.empty?\r\n        for m in msg do\r\n%>\r\n                                <div class=\"alert alert-error\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= m %>\r\n    							</div>\r\n<%\r\n        end\r\n    elsif suc_msg\r\n%>\r\n                                <div class=\"alert alert-success\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= suc_msg %>\r\n    							</div>\r\n<%\r\n    end\r\n%>\r\n\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#manage\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Manage Account\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"manage\">\r\n										<div class=\"accordion-inner\">\r\n										    <ul class=\"dshb_icoNav tac\">\r\n										        <li><a id=\'admin-user_account\' style=\"background-image: url(/gebo/img/gCons/multi-agents.png)\" href=\"javascript:show_toggle(\'group-account\');hide_toggle(\'group-profile\');\">\r\n										                <span class=\"label label-success\"><%= usr.compact.count %></span> User Account</a></li>\r\n										        <li><a id=\'admin-user_profile\' style=\"background-image: url(/gebo/img/gCons/ID.png)\" href=\"javascript:show_toggle(\'group-profile\');hide_toggle(\'group-account\');\">\r\n										                User Profile</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/agent.png)\" href=\"../Provider/index\">\r\n										                <span class=\"label label-success\"><%= @models[:provider].count %></span> Provider</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/addressbook.png)\" href=\"../Procedure/index\">\r\n										                <span class=\"label label-important\"><%= @models[:procedure].count %></span> Procedure</a></li>\r\n									            <li><a style=\"background-image: url(/gebo/img/gCons/arrow-round.png)\" href=\"../VisitType/index\">\r\n										                <span class=\"label label-info\"><%= @models[:visit_type].count %></span> Visit Type</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/lab.png)\" href=\"../Indication/index\">\r\n										                <span class=\"label label-info\"><%= @models[:indication].count %></span> Indication</a></li>\r\n								    <% if false %>\r\n										        <li><a id=\'admin-customer\' style=\"background-image: url(/gebo/img/gCons/processing.png)\" href=\"https://super_master.emr-life.com/www/Home/customer_login?s=<%=@current_solution.name%>&p=<%=@current_project.name%>\">\r\n										                 Account Profile</a></li>\r\n									<% end %>\r\n										        <!--\r\n										        <li><a style=\"font-size:.8em;background-image: url(/esm/thks/thks/content/knee.jpg);background-size: 52px 52px;\" href=\"../KneeComponent/index\">\r\n										                <span class=\"label label-info\"><%# c_kcom > 100 ? \"+100\" : c_kcom.to_s %></span> Knee Component</a></li>\r\n										        <li><a style=\"background-image: url(/esm/thks/thks/content/hip.jpg);background-size: 52px 52px;\" href=\"javascript:void(0)\">\r\n										                <span class=\"label label-info\">0</span> Hip Component</a></li>\r\n										                -->\r\n										    </ul>\r\n                                        </div>\r\n                                        <div class=\'row-fluid\'>\r\n                                            <form id=\'customer\' action=\'https://super_master.emr-life.com/www/Home/customer\' method=\'post\' target=\'_blank\'>\r\n                                                <input type=\"hidden\" name=\"solution_name\" value=\"<%= @current_solution.name %>\"/>\r\n                                                <input type=\"hidden\" name=\"customer[package_name]\" value=\"<%= @current_project.package %>\"/>\r\n                                                <!--<input type=\'submit\' name=\'submit\'/>-->\r\n                                            </form>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n\r\n\r\n                                <div class=\"accordion-group\" id=\"group-account\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Account (<%= usr.compact.count %>)\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse <%= \'in\' if @current_role==\'developer\' or @current_role==\'admin\' %>\" id=\"collapseOne1\">\r\n										<div class=\"accordion-inner\">\r\n										    <!--<div id=\"form-panel\" class=\"row-fluid\"><%= link_to \'Add New\', \'add_new?update=form-panel\', :remote=>true, :class=>\'btn\', :style=>\'float:right\' %>-->\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :account, :url=>\"index\", :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Add New Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Name</label>\r\n        												<div class=\"controls\">\r\n        												    <div class=\"row-fluid\">\r\n        												    <%= f.text_field :prefix, :class=>\'span2\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    <%= f.text_field :first_name, :class=>\'span4\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    <%= f.text_field :last_name, :class=>\'span4\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    </div>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block span2\">prefix name</span>\r\n        													<span class=\"help-block span4\">name</span>\r\n        													<span class=\"help-block span4\">surname</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">no space, special characters</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<!--\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%# f.text_field :full_name, :class=>\'span10\' %>\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											-->\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'user\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Provider Type</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[provider_type]\" id=\"provider_type\">\r\n                                                                <option value=\"\"></option>\r\n                                                                <option value=\"1\">Doctor</option>\r\n                                                                <option value=\"4\">Fellow Doctor</option>\r\n                                                                <option value=\"2\">Nurse</option>\r\n                                                                <option value=\"3\">Assistant</option>\r\n                                                            </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:id=>\'data-add_new\', :name=>\'add_new\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %> \r\n        													<%=f.submit \'Update\',:id=>\'data-update\', :name=>\'update\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;display:none\' %> \r\n        													<%=link_to \'Cancel\', \'#\', :id=>\'data-cancel\', :class=>\'btn\', :style=>\'display:none\', :onclick=>\"javascript:cancel()\" %>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n											<!--<hr/>-->\r\n                                            <div id=\"account\">\r\n											<table class=\"table\">\r\n        										<thead>\r\n        											<tr>\r\n        												<th>No.</th>\r\n        												<th>Login Name</th>\r\n        												<th>Name</th>\r\n        												<th>Role</th>\r\n        												<th>Actions</th>\r\n        											</tr>\r\n        										</thead>\r\n        										<tbody>\r\n        										<% \r\n        										    no = 1\r\n        										    for i in usr.compact do\r\n        										\r\n        										%>\r\n        										    <tr>\r\n        										        <td><%= no %>.</td>\r\n        										        <td><%= i[:login] %></td>\r\n        										        <td><%= i[:provider_name] %></td>\r\n        										        <td><%= i[:role_name] %></td>\r\n        										        <td>\r\n        										            <%= link_to \'\', \'#\', :title=>\'Delete Account\', :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>&nbsp;&nbsp;&nbsp;\r\n        										            <%= link_to \'\', \'#\', :title=>\'Edit Account\', :class=>\'splashy-contact_blue_edit\', :onclick=>\"javascript:confirm_edit(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>\r\n        										        </td>\r\n        										    </tr>\r\n        										<%\r\n        										    no += 1\r\n        										    end\r\n        										%>\r\n        										</tbody>\r\n        									</table>\r\n										</div>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n<%\r\n    end\r\n%>\r\n								<div class=\"accordion-group\" id=\"group-profile\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											User Profile\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :profile, :class=>\'\', :url=>\"index\" ,:method=>\'POST\' do |f| %>\r\n											<%\r\n											    cur_user = @ehr_models[:user].where(:login=>@current_user.to_s).first\r\n											    cur_prov = @models[:provider].where(:login=>@current_user.to_s).first\r\n											%>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your information</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\', :value=>@current_user, :disabled=>\'disabled\' %>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\', :value=>cur_user[:name] if cur_user %> \r\n        													<span class=\"help-block\">your account name</span>\r\n        												</div>\r\n        											</div>\r\n        											\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Password\" class=\"span10\" name=\"[profile]cur_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your information</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Password\" class=\"span10\" name=\"[profile]new_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Password\" class=\"span10\" name=\"[profile]con_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n										</div>\r\n									</div>\r\n								</div>\r\n							</div>\r\n                        \r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<br/>\r\n\r\n<script>\r\n    refresh();\r\n    \r\n    function confirm_delete(uid, pid) {\r\n        if (confirm(\'Are you sure?\') == true) {\r\n<%\r\n            destroy_url = \'destroy?id=\'\r\n%>\r\n            \r\n            url = \"destroy?uid=\" + uid + \"&pid=\" + pid;\r\n            window.location = url;\r\n        }\r\n    }\r\n    \r\n    function confirm_edit(uid, pid) {\r\n        // if (alert(\'Are you sure?\') == true) {\r\n            \r\n        // }\r\n        // console.log(\'UID = \' + uid);\r\n        // console.log(\'PID = \' + pid);\r\n        url = \"get_user?uid=\" + uid + \"&pid=\" + pid;\r\n        console.log(\"URL = \" + url);\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prov.prefix + \" | \" + data.user.login + \"...\" + data.user.role);\r\n                $(\'#account_prefix\').val(data.prov.prefix);\r\n                $(\'#account_first_name\').val(data.prov.first_name);\r\n                $(\'#account_last_name\').val(data.prov.last_name);\r\n                $(\'#account_login_name\').val(data.user.login);\r\n                $(\'#account_password\').val(\'\');\r\n                $(\'#account_email\').val(data.user.email);\r\n                $(\'#account_role option[value=\"\' + data.user.role + \'\"]\').prop(\'selected\', true);\r\n                $(\'#provider_type option[value=\"\' + data.prov.provider_type + \'\"]\').prop(\'selected\', true);\r\n                // $(\'#account_role value:eq(\' + data.user.role + \')\').prop(\'selected\', true);\r\n                // $(\'#provider_type value:eq(\' + data.prov.provider_type + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n            } \r\n        });\r\n        \r\n        $(\'#data-add_new\').hide();\r\n        $(\'#data-update\').show();\r\n        $(\'#data-cancel\').show();\r\n        $(\'#account_login_name\').prop(\'readonly\', true);\r\n    }\r\n    \r\n    function cancel() {\r\n        // $(\'#account\').trigger(\"reset\");\r\n        $(\'#data-add_new\').show();\r\n        $(\'#data-update\').hide();\r\n        $(\'#data-cancel\').hide();\r\n        $(\'#account_login_name\').prop(\'readonly\', false);\r\n    }\r\n    \r\n    function show_toggle(id) {\r\n        obj_id = \"#\" + id;\r\n        // $(obj_id).show();\r\n        $(obj_id).fadeIn(\'slow\');\r\n    }\r\n    \r\n    function hide_toggle(id) {\r\n        obj_id = \"#\" + id;\r\n        // $(obj_id).hide();\r\n        $(obj_id).fadeOut(\'slow\');\r\n        // console.log(\"ID : \" + obj_id);\r\n    }\r\n    \r\n    function fnc_user_account() {\r\n        show_toggle(\"group-account\");\r\n        hide_toggle(\"group-profile\")\r\n    }\r\n    \r\n    function post_customer() {\r\n        $(\'#customer\').submit();\r\n        // var myForm = document.createElement(\"form\");\r\n        // myForm.action=this.href;// the href of the link\r\n        // myForm.target=\"myFrame\";\r\n        // myForm.method=\"POST\";\r\n        // myForm.submit();\r\n        // return false; // cancel the actual link\r\n    }\r\n    \r\n    $(document).ready(function() {\r\n<% if @current_role==\'developer\' or @current_role==\'admin\' %>\r\n        $(\'#group-account\').hide();\r\n        $(\'#group-profile\').hide();\r\n<% end %>\r\n        \r\n        // button user\r\n        $(\'#admin-user_account\').click(fnc_user_account);\r\n        $(\'#admin-account\').click();\r\n        \r\n        setTimeout(function(){ $(\".se-pre-con\").fadeOut(\"slow\"); }, 1500);\r\n        \r\n    });\r\n</script>',NULL,NULL,NULL,'2016-05-17 05:32:44','2016-05-17 05:32:44','index',''),(2258,'destroy',636,3,'<%= render :inline=>this.init %>\r\n<%\r\n    if params[:uid] and params[:pid]\r\n        @ehr_models[:user].find(params[:uid]).destroy\r\n        # @models[:provider].find(params[:pid]).destroy\r\n        @models[:provider].find(params[:pid]).update_attributes :provider_type=>\'0\'\r\n    end\r\n%>\r\n<script>\r\n    window.location = \"index\";\r\n</script>',NULL,NULL,NULL,'2016-05-17 05:46:11','2016-05-17 05:46:11','destroy',''),(2259,'test',943,3,'<%\r\n    esm = Esm.find_by_name @current_solution.name\r\n    \r\n    pro = Project.find_by_package @current_project.package\r\n    # pro[:title] = \'ENDO\'\r\n    # pro.save\r\n    \r\n    app = esm.projects.find_by_name pro.name\r\n    # app_module.settings.create :name=>\'report_title_2\', :value=> customer.commercial_name\r\n    \r\n    # rt_1 = app.settings.find_by_name \'report_title_1\'\r\n    # rt_1.value = rt_1.value.split(\' \').join(\'.\')\r\n    # rt_1.save\r\n    \r\n    sm = Esm.find_by_name \'super_master\'\r\n    mm = get_model\r\n    \r\n    res = {}\r\n    res[:sm] = sm\r\n    res[:mm] = mm.inspect\r\n    res[:esm] = esm\r\n    res[:pro] = pro\r\n    res[:app] = app\r\n    res[:app_setting] = app.settings\r\n    \r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2016-05-17 14:05:44','2016-05-17 14:05:44','test',''),(2260,'edit',923,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    obj = get_model[:attachment]\r\n    pa1 = nil\r\n    pa2 = nil\r\n    \r\n    if l = record[:logo]\r\n        pa1 = obj.find(l)[:path]\r\n    end\r\n    if l = record[:report_logo]\r\n        pa2 = obj.find(l)[:path]\r\n    end\r\n    \r\n    sol_name = record[:solution_name]\r\n    pkg_name = \"\\\\#{sol_name}.endo\"\r\n    \r\n    esm = Esm.find_by_name sol_name\r\n    pro = Project.find_by_package pkg_name\r\n    app = esm.projects.find_by_name pro.name\r\n    \r\n    if pa1\r\n        if tmp = app.settings.find_by_name(\'logo_path\')\r\n            tmp.value = pa1\r\n            tmp.save\r\n        else\r\n            app.settings.create :name=>\'logo_path\', :value=>pa1\r\n        end\r\n    end\r\n    if pa2\r\n        if tmp = app.settings.find_by_name(\'logo_report_path\')\r\n            tmp.value = pa2\r\n            tmp.save\r\n        else\r\n            app.settings.create :name=>\'logo_report_path\', :value=>pa2\r\n        end\r\n    end\r\n    \r\n    res = {}\r\n    res[:pa1] = pa1\r\n    res[:pa2] = pa2\r\n    res[:app] = app\r\n    res[:esm] = esm\r\n    res[:pro] = pro\r\n    res[:app] = app\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=record.id%>\"\r\n//-->\r\n</script>\r\n<%# res.to_json.html_safe %>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-05-17 14:49:35','2016-05-17 14:49:35','edit',''),(2261,'test',923,3,'<%\r\n    obj = get_model[:attachment]\r\n    logo_1 = obj.find(\'573b2f23790f9b657b000002\')\r\n    logo_2 = obj.find(\'573b2f54790f9b5aa900000e\')\r\n    res = {}\r\n    res[:obj] = obj.all\r\n    res[:logo_1] = logo_1[:path]\r\n    res[:logo_2] = logo_2[:path]\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2016-05-17 15:02:45','2016-05-17 15:02:45','test',''),(2262,'index_bk',943,2,'<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% -34px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .collapsed {\r\n        background-position: 98% 12px;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n    \r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	position: fixed;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat #fff;\r\n}\r\n</style>\r\n    <!-- nice form elements -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/uniform/Aristo/uniform.aristo.css\" />\r\n	<!-- 2col multiselect -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/multiselect/css/multi-select.css\" />\r\n\r\n<%= render :inline=>this.init %>\r\n\r\n<%\r\n    msg = []\r\n    tmp = nil\r\n    suc_msg = nil\r\n    \r\n    if request.post?\r\n        if !params[:account].nil? and !params[:add_new].nil?\r\n\r\n            acc = params[:account]\r\n            \r\n            if acc[:login_name].empty?\r\n                msg.push(\'Invalid login name\')\r\n            end\r\n            # if params[:account][:full_name].empty?\r\n            #     msg.push(\'Invalid full name\')\r\n            # end\r\n            if acc[:password].empty?\r\n                msg.push(\'No password found\')\r\n            end\r\n            \r\n            full_name = acc[:prefix].strip + acc[:first_name].strip + \" \" + acc[:last_name].strip\r\n            full_name = full_name.strip\r\n            if full_name == \'\'\r\n                msg.push(\'Invalid name\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>params[:account][:login_name]).first\r\n                if m_user\r\n                    msg.push(\'Existing login name\')\r\n                else\r\n                    r_provider = @models[:provider].where({\'name\' => Regexp.new( full_name )})\r\n                    create_user = false\r\n                    # a_prov = m_prov.where({\'name\' => Regexp.new(\'\')})\r\n                    if r_provider.count == 0\r\n                        m_provider = @models[:provider].create :group=>\'default\', :name=>full_name, :prefix=>acc[:prefix], :first_name=>acc[:first_name], :last_name=>acc[:last_name], :login=>params[:account][:login_name], :provider_type=>params[:account][:provider_type]\r\n                        create_user = true\r\n                    elsif r_provider.count == 1\r\n                        m_provider = r_provider.first.update_attributes :login=>params[:account][:login_name]\r\n                        create_user = true\r\n                    else\r\n                        name_list = r_provider.collect{|i| i[:name]}\r\n                        msg.push(\"Existing name (\\#{name_list.count}) : \" + name_list.join(\', \'))\r\n                    end\r\n                    \r\n                    if create_user \r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(params[:account][:password], salt)\r\n                        tmp = salt + \'...\' + hashed_password\r\n                        m_user = @ehr_models[:user].create :role=>params[:account][:role], :login=>params[:account][:login_name], :salt=>salt, :hashed_password=>hashed_password, :email=>params[:account][:email], :name=>full_name, :activate=>\"true\"\r\n                        tmp = m_user.id.to_s\r\n                        # tmp += \'...\' + m_provider.id.to_s\r\n                    end\r\n                    \r\n                end\r\n            end\r\n        elsif !params[:account].nil? and !params[:update].nil?\r\n            acc = params[:account]\r\n            \r\n            full_name = acc[:prefix].strip + acc[:first_name].strip + \" \" + acc[:last_name].strip\r\n            full_name = full_name.strip\r\n            if full_name == \'\'\r\n                msg.push(\'Invalid name\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>acc[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>acc[:login_name]).first\r\n                \r\n                m_prov[:name] = full_name\r\n                m_prov[:prefix] = acc[:prefix]\r\n                m_prov[:first_name] = acc[:first_name]\r\n                m_prov[:last_name] = acc[:last_name]\r\n                m_prov[:provider_type] = acc[:provider_type]\r\n                m_prov.save\r\n                \r\n                suc_msg= \"<b>Success</b> Account <b>\\#{acc[:login_name]}</b> has been updated\".html_safe\r\n                \r\n                if acc[:password].strip != \'\'\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(acc[:password], salt)\r\n                    m_user[:hashed_password] = hashed_password\r\n                    m_user[:salt] = salt\r\n                    # m_user.save\r\n                    suc_msg= \"<strong>Success</strong> Account <b>\\#{acc[:login_name]}</b> profile and password has been updated\".html_safe\r\n                end\r\n                \r\n                m_user[:name] = full_name\r\n                m_user[:email] = acc[:email]\r\n                m_user[:role] = acc[:role]\r\n                m_user.save\r\n            end\r\n            \r\n        elsif !params[:profile].nil?\r\n            px = params[:profile]\r\n            if px[:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if px[:cur_password].empty?\r\n                msg.push(\'No password to confirm your change\')\r\n            else\r\n                if px[:new_password] != px[:con_password]\r\n                    msg.push(\"Your confirm password not match the new password. Try again.\")\r\n                end\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>px[:login_name]).first\r\n                salt = m_user[:salt]\r\n                hashed_password = User.encrypt(px[:cur_password], salt)\r\n                if m_user[:hashed_password] == hashed_password\r\n                    if px[:con_password] == px[:new_password] and px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        suc_msg= \"<strong>Success</strong> Your profile has been change\".html_safe\r\n                    elsif px[:con_password] == px[:new_password] and !px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(px[:new_password], salt)\r\n                        m_user[:hashed_password] = hashed_password\r\n                        m_user[:salt] = salt\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your profile and password has been change\".html_safe\r\n                    else\r\n                        msg.push(\'Your new and confirm password does not match\')\r\n                    end\r\n                    \r\n                else\r\n                    msg.push(\'Your current password does not match\')\r\n                end\r\n                # msg.push(px[:login_name])\r\n            end\r\n        else\r\n            if @current_role == \'developer\'\r\n%>\r\n<pre>\r\n    <%= params.inspect %>\r\n</pre>\r\n<%\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n<%#list.inspect%>\r\n<div class=\"se-pre-con\"></div>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                            <div id=\"accordion1\" class=\"accordion\">\r\n<%\r\n    # check admin or developer role\r\n    a_role = @ehr_models[:role].all\r\n    \r\n    map_role = {}\r\n    map_role[\'\']  = \'Na\'\r\n    map_role[nil] = \'N/A\'\r\n    for a in a_role do\r\n        map_role[a.id.to_s] = a[:name]\r\n    end\r\n    if @current_role == \'admin\' or @current_role == \'developer\'\r\n        usr = @ehr_models[:user].all.collect do |i|\r\n            # role = @ehr_models[:role].find(i.role)\r\n            # role_name = \'undefined\'\r\n            # if role\r\n            #     role_name = role[:name]\r\n            # end\r\n            role_name = map_role[i.role.to_s]\r\n            provider = @models[:provider].where(:login=>i.login).first\r\n            \r\n            if provider\r\n                {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :i=>i}\r\n            end\r\n        end\r\n%>\r\n<%\r\n    if !msg.empty?\r\n        for m in msg do\r\n%>\r\n                                <div class=\"alert alert-error\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= m %>\r\n    							</div>\r\n<%\r\n        end\r\n    elsif suc_msg\r\n%>\r\n                                <div class=\"alert alert-success\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= suc_msg %>\r\n    							</div>\r\n<%\r\n    end\r\n%>\r\n\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#manage\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Manage Account\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"manage\">\r\n										<div class=\"accordion-inner\">\r\n										    <ul class=\"dshb_icoNav tac\">\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/multi-agents.png)\" href=\"../Provider/index\">\r\n										                <span class=\"label label-success\"><%= usr.compact.count %></span> User</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/addressbook.png)\" href=\"../Procedure/index\">\r\n										                <span class=\"label label-important\"><%= @models[:procedure].count %></span> Procedure</a></li>\r\n									            <li><a style=\"background-image: url(/gebo/img/gCons/arrow-round.png)\" href=\"../VisitType/index\">\r\n										                <span class=\"label label-info\"><%= @models[:visit_type].count %></span> Visit Type</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/lab.png)\" href=\"../Indication/index\">\r\n										                <span class=\"label label-info\"><%= @models[:indication].count %></span> Indication</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/processing.png)\" href=\"../Indication/index\">\r\n										                 Profile</a></li>\r\n										        <!--\r\n										        <li><a style=\"font-size:.8em;background-image: url(/esm/thks/thks/content/knee.jpg);background-size: 52px 52px;\" href=\"../KneeComponent/index\">\r\n										                <span class=\"label label-info\"><%# c_kcom > 100 ? \"+100\" : c_kcom.to_s %></span> Knee Component</a></li>\r\n										        <li><a style=\"background-image: url(/esm/thks/thks/content/hip.jpg);background-size: 52px 52px;\" href=\"javascript:void(0)\">\r\n										                <span class=\"label label-info\">0</span> Hip Component</a></li>\r\n										                -->\r\n										    </ul>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n\r\n\r\n                                <div class=\"accordion-group\" id=\"group-account\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Account (<%= usr.compact.count %>)\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse <%= \'in\' if @current_role==\'developer\' or @current_role==\'admin\' %>\" id=\"collapseOne1\">\r\n										<div class=\"accordion-inner\">\r\n										    <!--<div id=\"form-panel\" class=\"row-fluid\"><%= link_to \'Add New\', \'add_new?update=form-panel\', :remote=>true, :class=>\'btn\', :style=>\'float:right\' %>-->\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :account, :url=>\"index\", :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Add New Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Name</label>\r\n        												<div class=\"controls\">\r\n        												    <div class=\"row-fluid\">\r\n        												    <%= f.text_field :prefix, :class=>\'span2\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    <%= f.text_field :first_name, :class=>\'span4\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    <%= f.text_field :last_name, :class=>\'span4\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    </div>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block span2\">prefix name</span>\r\n        													<span class=\"help-block span4\">name</span>\r\n        													<span class=\"help-block span4\">surname</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">no space, special characters</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<!--\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%# f.text_field :full_name, :class=>\'span10\' %>\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											-->\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'user\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Provider Type</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[provider_type]\" id=\"provider_type\">\r\n                                                                <option value=\"\"></option>\r\n                                                                <option value=\"3\">Assistant\r\n                                                                </option>\r\n                                                                <option value=\"4\">Surgeon\r\n                                                                </option>\r\n                                                                <option value=\"5\">Surgeon assistant\r\n                                                                </option>\r\n                                                                <option value=\"6\">Anesthesiologist\r\n                                                                </option>\r\n                                                                <option value=\"7\">Nurse anesthesiologist</option>\r\n                                                            </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:id=>\'data-add_new\', :name=>\'add_new\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %> \r\n        													<%=f.submit \'Update\',:id=>\'data-update\', :name=>\'update\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;display:none\' %> \r\n        													<%=link_to \'Cancel\', \'#\', :id=>\'data-cancel\', :class=>\'btn\', :style=>\'display:none\', :onclick=>\"javascript:cancel()\" %>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n											<!--<hr/>-->\r\n                                            <div id=\"account\">\r\n											<table class=\"table\">\r\n        										<thead>\r\n        											<tr>\r\n        												<th>No.</th>\r\n        												<th>Login Name</th>\r\n        												<th>Name</th>\r\n        												<th>Role</th>\r\n        												<th>Actions</th>\r\n        											</tr>\r\n        										</thead>\r\n        										<tbody>\r\n        										<% \r\n        										    no = 1\r\n        										    for i in usr.compact do\r\n        										\r\n        										%>\r\n        										    <tr>\r\n        										        <td><%= no %>.</td>\r\n        										        <td><%= i[:login] %></td>\r\n        										        <td><%= i[:provider_name] %></td>\r\n        										        <td><%= i[:role_name] %></td>\r\n        										        <td>\r\n        										            <%= link_to \'\', \'#\', :title=>\'Delete Account\', :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\#{i[:id]}\', \'\\#{i[:provider_id]}\')\" %>&nbsp;&nbsp;&nbsp;\r\n        										            <%= link_to \'\', \'#\', :title=>\'Edit Account\', :class=>\'splashy-contact_blue_edit\', :onclick=>\"javascript:confirm_edit(\'\\#{i[:id]}\', \'\\#{i[:provider_id]}\')\" %>\r\n        										        </td>\r\n        										    </tr>\r\n        										<%\r\n        										    no += 1\r\n        										    end\r\n        										%>\r\n        										</tbody>\r\n        									</table>\r\n										</div>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n<%\r\n    end\r\n%>\r\n								<div class=\"accordion-group\" id=\"group-profile\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											User Profile\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :profile, :class=>\'\', :url=>\"index\" ,:method=>\'POST\' do |f| %>\r\n											<%\r\n											    cur_user = @ehr_models[:user].where(:login=>@current_user.to_s).first\r\n											    cur_prov = @models[:provider].where(:login=>@current_user.to_s).first\r\n											%>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your information</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\', :value=>@current_user, :disabled=>\'disabled\' %>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\', :value=>cur_user[:name] if cur_user %> \r\n        													<span class=\"help-block\">your account name</span>\r\n        												</div>\r\n        											</div>\r\n        											\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Password\" class=\"span10\" name=\"[profile]cur_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your information</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Password\" class=\"span10\" name=\"[profile]new_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Password\" class=\"span10\" name=\"[profile]con_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n										</div>\r\n									</div>\r\n								</div>\r\n							</div>\r\n                        \r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<br/>\r\n\r\n<script>\r\n    refresh();\r\n    \r\n    function confirm_delete(uid, pid) {\r\n        if (confirm(\'Are you sure?\') == true) {\r\n<%\r\n            destroy_url = \'destroy?id=\'\r\n%>\r\n            \r\n            url = \"destroy?uid=\" + uid + \"&pid=\" + pid;\r\n            window.location = url;\r\n        }\r\n    }\r\n    \r\n    function confirm_edit(uid, pid) {\r\n        // if (alert(\'Are you sure?\') == true) {\r\n            \r\n        // }\r\n        // console.log(\'UID = \' + uid);\r\n        // console.log(\'PID = \' + pid);\r\n        url = \"get_user?uid=\" + uid + \"&pid=\" + pid;\r\n        console.log(\"URL = \" + url);\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prov.prefix + \" | \" + data.user.login + \"...\" + data.user.role);\r\n                $(\'#account_prefix\').val(data.prov.prefix);\r\n                $(\'#account_first_name\').val(data.prov.first_name);\r\n                $(\'#account_last_name\').val(data.prov.last_name);\r\n                $(\'#account_login_name\').val(data.user.login);\r\n                $(\'#account_password\').val(\'\');\r\n                $(\'#account_email\').val(data.user.email);\r\n                $(\'#account_role option[value=\"\' + data.user.role + \'\"]\').prop(\'selected\', true);\r\n                $(\'#provider_type option[value=\"\' + data.prov.provider_type + \'\"]\').prop(\'selected\', true);\r\n                // $(\'#account_role value:eq(\' + data.user.role + \')\').prop(\'selected\', true);\r\n                // $(\'#provider_type value:eq(\' + data.prov.provider_type + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n            } \r\n        });\r\n        \r\n        $(\'#data-add_new\').hide();\r\n        $(\'#data-update\').show();\r\n        $(\'#data-cancel\').show();\r\n        $(\'#account_login_name\').prop(\'readonly\', true);\r\n    }\r\n    \r\n    function cancel() {\r\n        // $(\'#account\').trigger(\"reset\");\r\n        $(\'#data-add_new\').show();\r\n        $(\'#data-update\').hide();\r\n        $(\'#data-cancel\').hide();\r\n        $(\'#account_login_name\').prop(\'readonly\', false);\r\n    }\r\n    \r\n    function show_toggle(id) {\r\n        obj_id = \"#\" + id;\r\n        $(obj_id).show();\r\n    }\r\n    \r\n    function hide_toggle(id) {\r\n        obj_id = \"#\" + id;\r\n        $(obj_id).hide();\r\n        console.log(\"ID : \" + obj_id);\r\n    }\r\n    \r\n    $(document).ready(function() {\r\n<% if @current_role==\'developer\' or @current_role==\'admin\' %>\r\n        $(\'#group-account\').hide();\r\n<% end %>\r\n        $(\'#group-profile\').hide();\r\n        \r\n        $(\".se-pre-con\").fadeOut(\"slow\");\r\n    });\r\n</script>',NULL,NULL,NULL,'2016-05-18 04:04:38','2016-05-18 04:04:38','index_bk',''),(2263,'index',942,2,'<%\r\n    \r\n    module_name = @current_project.name\r\n    if params[:date]\r\n        session[module_name]={:date=>params[:date]}\r\n    end\r\n    if session[module_name]\r\n        params[:date] = session[module_name][:date]\r\n    end\r\n    unless params[:date]\r\n        params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n    end\r\n \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n\r\n<%\r\n    # checking existing provider\r\n    prov = get_model[:provider].where(:provider_type=>\'1\').all\r\n    if prov.empty?\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"modal-provider\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>ข้อแนะนำ</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n								    ไม่พบรายชื่อแพทย์ในระบบ กรุณาคลิกที่ปุ่ม\r\n								    \r\n									<ul class=\"dshb_icoNav tac\" style=\'display:inline\'>\r\n									    <li><a style=\"background-image: url(/gebo/img/gCons/configuration02.png)\" href=\"javascript:void(0);\">\r\n										    Settings</a></li>\r\n									</ul>\r\n									\r\n									เพื่อตั้งค่ารายชื่อแพทย์\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">รับทราบ</a>\r\n								</div>\r\n							</div>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\'#modal-provider\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n        \r\n        // $(\'#btn-add_patient\').off(\'click\');\r\n    });\r\n</script>\r\n<%\r\n    end\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n    \r\n    .table td {\r\n        vertical-align: middle;\r\n    }\r\n\r\n\r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	/*position: fixed;*/\r\n	position: absolute;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat #144884;\r\n}\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %><%= error%>\r\n    <%\r\n    session.delete :s_date\r\n    end\r\n     %>\r\n        <%\r\n    search_patient = false\r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n          end\r\n        session[:s_status] = s_status\r\n         session[:s_provider] = s_provider \r\n        \r\n    end\r\n    if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Add & Continue\"\r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n</script>\r\n<%\r\n        end\r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       <b>Home : <%= date.strftime(\'%d/%m/%Y\') %></b>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n            <div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>params[:opt], :html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\">Date : </label>\r\n                    <div class=\"field-input\" >\r\n                        <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\">HN : </label>\r\n                    <div class=\"field-input\">\r\n                        <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n                    </div>\r\n                </span>\r\n            \r\n                <span class=\"field-data\" style=\"margin-top:5px;width:300px\"> \r\n                        <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                        <%=link_to \'Advanced Search\', \'javascript:void(0)\', :id=>\'btn-advanced_search\', :class=>\'btn\' %>\r\n                        <%=link_to \'Show Filter\', \'javascript:void(0)\', :id=>\'btn-show_filter\', :class=>\'btn\' %>\r\n                </span>\r\n                \r\n                <div class=\"clear\"></div>\r\n\r\n                <span class=\"field-data\">\r\n                    <label class=\"field-label\">&nbsp;</label>\r\n                    <div class=\"field-input\">\r\n                        <%=link_to \'Add Patient\', \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\',:style=>\'margin-top:10px\'%>\r\n                    </div>\r\n                </span>\r\n\r\n            <div class=\"clear\"></div>\r\n            \r\n            <script>\r\n                $(\'#search_hn\').focus();\r\n            </script>\r\n<% end %>\r\n            \r\n        </div>\r\n        \r\n    </div>\r\n\r\n    <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" id=\'block-filter\'>\r\n        <a class=\"close\" href=\"javascript:void(0);\" id=\'btn-hide_filter\' style=\'float:left\'>x</a>\r\n        <div class=\"row-fluid\">\r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\"> </label>\r\n                    <div class=\"field-input\" style=\'float:right\'>&nbsp;<b>Filter by</b></div>\r\n                </span>\r\n                <!-- filter -->\r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Provider : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-provider\" id=\"fil-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"prov_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"prov_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Procedure : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-procedure\" id=\"fil-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"proc_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"proc_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Visit : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-visit\" id=\"fil-visit\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"visit_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"visit_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n        </div>\r\n    </div>\r\n\r\n        <!--DATE : <%# date %>-->\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%#params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n# SEARCH SECTION    \r\n    if search_patient\r\n        \r\n        fields = {:hn=>s_hn, :first_name=>s_hn, :last_name=>s_hn}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n    \r\n        if keys.size>0\r\n            conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n            criteria = {\'$or\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n    \r\n        patients = patient_model.where(criteria).limit(20).all  \r\n        maps = module_model.all     :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n        aps = ap_model.find(maps.collect{|i| i.module_id})\r\n%>\r\n<!--<%= params[:search].to_json.html_safe %>-->\r\n<%\r\n        if aps.count == 1 # and @current_role==\'developer\' \r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= aps.first.id.to_s %>\';\r\n</script>\r\n<%\r\n        end\r\n\r\n    elsif pad = params[:adv_pat]\r\n        adv = params[:advanced]\r\n        fields = {:provider=>adv[:provider], :visit_type=>adv[:visit_type], :indication=>adv[:indication], :procedure=>adv[:procedure]}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>v} if v and v!=\'\' \r\n        end\r\n        \r\n        if keys.size>0\r\n            criteria = {\'$and\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n        \r\n        # patient criteria\r\n        fs = {:first_name=>pad[:fname], :last_name=>pad[:lname]}\r\n        ks = []\r\n        fs.each_pair do |k, v|\r\n            ks <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n        if ks.size>0\r\n            cr = {\'$or\'=>ks}\r\n        else\r\n            cr ={}\r\n        end\r\n        \r\n        a_app = []\r\n        if !criteria.empty?\r\n            a_app = ap_model.where(criteria).all\r\n        end\r\n        \r\n        a_pat = []\r\n        if !cr.empty?\r\n            a_pat = patient_model.where(cr).all\r\n        end\r\n        \r\n        if !a_app.empty? and cr.empty?\r\n            aps = a_app\r\n        elsif a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(maps.collect{|i| i.module_id})\r\n        elsif !a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(a_app.collect{|i|i.id} & maps.collect{|i| i.module_id})\r\n        else\r\n            aps = ap_model.limit(20).all\r\n        end\r\n    else\r\n    \r\n        conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n        if s_provider and s_provider !=\'\'\r\n            conds.merge! :provider=>s_provider \r\n        end\r\n\r\n        if s_status and s_status != \"\"\r\n            conds.merge! :status=>s_status \r\n        end\r\n    \r\n        aps = ap_model.all(conds)\r\n\r\n    end\r\n     \r\n         \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\") if patient\r\n         public_id = \'-\'\r\n         bdate = i.date.strftime(\'%d/%m/\').to_s + (i.date.strftime(\'%Y\').to_i + 543).to_s\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id}\"),\r\n         :provider=>provider_name,:date=>i.date.strftime(\'%d/%m/%Y\'),:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\',:style=>\'margin:0px\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type, :patient_id=>patient.id, :prov_id=>i.provider, :proc_id=>i.procedure, :visit_id=>i.visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{date hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    \r\n        labels = {:no=>\'No.\', :date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Action\', :procedure=>\'Procedure\' }\r\n    \r\n    %>\r\n<div class=\"se-pre-con\"></div>\r\n<%\r\n    if aps.empty?\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\' style=\'padding:20px\'>\r\n        <center><h3>ไม่มีรายการนัดหมายสำหรับวันนี้ คลิกปุ่ม \r\n        <%=link_to \'Add Patient\', \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\',:style=>\'\',:disabled=>true%>\r\n        เพื่อเพิ่มรายการนัดหมาย</h3></center>\r\n    </div>\r\n</div>\r\n<%\r\n    else\r\n        # table fields\r\n        tf = [:no]+table_model+[:processing_ctrl,:note]\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\' style=\'padding:20px\'>\r\n        <table class=\"table table-bordered\">\r\n            <thead>\r\n                <tr>\r\n<%\r\n            tf.each do |i|\r\n%>\r\n                    <th><%= labels[i] %></th>\r\n<%\r\n            end\r\n%>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n<%\r\n            no = 1;\r\n            aps.each do |i|\r\n                i[:no] = link_to(no.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{i[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n%>\r\n                <tr class=\'filterable\'>\r\n<%\r\n                tf.each do |j|\r\n                    cs = \'\'\r\n                    if j.to_s == \'provider\'\r\n                        cs = \"class=\'filter prov_\\\\#{i[:prov_id]}\'\"\r\n                    elsif j.to_s == \'procedure\'\r\n                        cs = \"class=\'filter proc_\\\\#{i[:proc_id]}\'\"\r\n                    elsif j.to_s == \'note\'\r\n                        cs = \"class=\'filter visit_\\\\#{i[:visit_id]}\'\"\r\n                    end\r\n%>\r\n                    <td <%= cs.html_safe %>><%= i[j] %></td>\r\n<%\r\n                end\r\n%>\r\n                </tr>\r\n<%\r\n                no += 1\r\n            end # end aps\r\n%>\r\n            </tbody>\r\n        </table>\r\n    </div>\r\n</div>\r\n<%\r\n    end\r\n%>\r\n\r\n\r\n<% if false %>\r\n<%\r\n        app_a = []\r\n        app_c = []\r\n        aps.each do |i|\r\n            if i[:status] == \'Completed\'\r\n                app_c << i\r\n            else\r\n                app_a << i\r\n            end\r\n        end\r\n%>\r\n<div id=\'default-panel\' style=\'padding:5px\'>\r\n    <div class=\"tabbable\">\r\n        <ul class=\"nav nav-tabs\">\r\n            <li class=\"active\"><a href=\"#appointed\" data-toggle=\"tab\">Appointed (<%= app_a.count %>)</a></li>\r\n            <li><a href=\"#completed\" data-toggle=\"tab\">Completed (<%= app_c.count %>)</a></li>\r\n        </ul>\r\n        <div class=\"tab-content\">\r\n            <div class=\"tab-pane active\" id=\"appointed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_a,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n            <div class=\"tab-pane\" id=\"completed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_c,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<% end %>\r\n\r\n<% if false %>\r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    # out[0] = count.to_s+\".\"\r\n                    out[0] = link_to(count.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\").html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n        </div>\r\n<% end %>        \r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n <script>\r\n function change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"<%=params[:opt]%>?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n\r\n<% if false %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Encounter</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n\r\n    \r\n   \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n<% end  %>\r\n<div class=\"alert \">\r\n<%# link_to \'Total Status\',\'total_status?print[date]=\'+params[:date], :target=>\'_blank\' %>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date],class: \'btn btn-mini\' %> |\r\n<!--<%= link_to \'Status Feed\',\'total_status?print[date]=\'+params[:date],class: \'btn btn-mini\', :target=>\'_blank\' %> |-->\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date],class: \'btn btn-mini\' %> | \r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date],class: \'btn btn-mini\' %> |\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n<%\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"myModal2\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Modal header</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n									Lorem ipsum dolor sit amet, consectetur adipiscing elit. Pellentesque non elit tellus, eleifend varius erat. Lorem ipsum dolor sit amet, consectetur adipiscing elit. In bibendum laoreet ante sodales elementum. Nullam varius interdum est, at ornare quam aliquam eu. Nulla ultricies commodo leo sit amet vulputate.\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n							</div>\r\n	\r\n<div class=\"modal hide fade\" id=\"modal2\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Advanced Search</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n        \r\n<%= form_for :advanced , :url=>params[:opt] do |f| %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name  : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[first_name]\" id=\"data-fname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[last_name]\" id=\"data-lname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <%= f.submit \'Search\', :class=>\'btn btn-success\' %>\r\n                <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a> \r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n							\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                <br/>\r\n                <div id=\"patient_msg\"></div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Add & Continue\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n</script>\r\n\r\n<script>\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    \r\n    function filter() {\r\n        var prov = $(\"#fil-provider\").val();\r\n        var proc = $(\"#fil-procedure\").val();\r\n        var visit = $(\"#fil-visit\").val();\r\n        \r\n        if (prov.indexOf(\'all\') != -1 && proc.indexOf(\'all\') != -1 && visit.indexOf(\'all\') != -1) {\r\n            $(\'tr\').show();\r\n        } else {\r\n            $(\'.filterable\').hide();\r\n            console.log(\'all hide ...\');\r\n            $(\"td.filter\").each(function (i, col) {\r\n                \r\n                    if ($(col).hasClass(prov) || $(col).hasClass(proc) || $(col).hasClass(visit)) {\r\n                        $(col).parent(\'tr\').show();\r\n                    } else {\r\n                        // if (!$(col).parent(\'tr\').is(\':visible\')) {\r\n                            // $(col).parent(\'tr\').hide();\r\n                        // }\r\n                    }\r\n                    // console.log(\'i : \' + i + \", col : \" + col)\r\n                    \r\n            });\r\n        }\r\n        \r\n    }\r\n    \r\n    $(document).ready(function(){\r\n        <% if !prov.empty? %>\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        <% end %>\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#data-hn\').change(update_patient);\r\n        // show filter section\r\n        $(\'#block-filter\').hide();\r\n        $(\'#btn-show_filter\').click(function() {\r\n            // $(\'#block-filter\').show();\r\n            $(\'#block-filter\').fadeIn(\'slow\');\r\n        });\r\n        $(\'#btn-hide_filter\').click(function() {\r\n            $(\'#block-filter\').fadeOut(\'slow\');\r\n        })\r\n        \r\n        $(\"#fil-provider\").change(filter);\r\n        $(\"#fil-procedure\").change(filter);\r\n        $(\"#fil-visit\").change(filter);\r\n        \r\n        // remove splash loading\r\n        $(\".se-pre-con\").fadeOut(\"slow\");\r\n    });\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2016-05-18 04:05:13','2016-05-18 04:05:13','index',''),(2264,'idx',943,2,'<%= render :inline=>this.init %>\r\n<style>\r\n.se-pre-con {\r\n	/*position: fixed;*/\r\n	position: absolute;\r\n	display: block;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat ;\r\n}\r\n</style>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                \r\n                <div class=\"row-fluid\">\r\n                    <div class=\"span5\">\r\n                        <div class=\'w-box\'>\r\n                            <div class=\'w-box-header\'>\r\n                                Administrator\r\n                            </div>\r\n                            <div class=\'w-box-content cnt_a\'>\r\n                                <ul class=\"dshb_icoNav tac\">\r\n										        <li><a id=\'admin-user_account\' style=\"background-image: url(/gebo/img/gCons/multi-agents.png)\" href=\"javascript:void(0)\">\r\n										                <span class=\"label label-success\"><%# usr.compact.count %></span> User</a></li>\r\n										        <li><a id=\'admin-user_profile\' style=\"background-image: url(/gebo/img/gCons/agent.png)\" href=\"javascript:void(0)\">\r\n										                <span class=\"label label-success\"><%# usr.compact.count %></span> User Profile</a></li>\r\n										        <li><a id=\'admin-site\' style=\"background-image: url(/gebo/img/gCons/processing.png)\" href=\"javascript:void(0)\">\r\n										                 Site</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/addressbook.png)\" href=\"../Procedure/index\">\r\n										                <span class=\"label label-important\"><%= @models[:procedure].count %></span> Procedure</a></li>\r\n									            <li><a style=\"background-image: url(/gebo/img/gCons/arrow-round.png)\" href=\"../VisitType/index\">\r\n										                <span class=\"label label-info\"><%= @models[:visit_type].count %></span> Visit Type</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/lab.png)\" href=\"../Indication/index\">\r\n										                <span class=\"label label-info\"><%= @models[:indication].count %></span> Indication</a></li>\r\n										        \r\n								</ul>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <div class=\"span7\">\r\n                        <div class=\'w-box\'>\r\n                            <div class=\'w-box-header\'>\r\n                                <div id=\'cnt-header\'>Loading...</div>\r\n                            </div>\r\n                            <div class=\'w-box-content cnt_a\'>\r\n                                <div id=\'cnt-body\'>\r\n                                    <!--<div class=\'se-pre-con\'></div>-->\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                \r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<script>\r\n    $(document).ready(function() {\r\n        \r\n    });\r\n</script>',NULL,NULL,NULL,'2016-05-18 04:09:16','2016-05-18 04:09:16','idx',''),(2265,'print',928,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:lbe_operative].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-ri