,'2016-05-18 07:07:25','2016-05-18 07:07:25','print',''),(2266,'confirm',944,3,'\r\n<html>\r\n    <head>\r\n        <%=include_header%>\r\n        <style>\r\n\r\n    input{\r\n \r\n        height:24px;\r\n            }\r\n  \r\n\r\n</style>\r\n    </head>\r\n        \r\n<body style=\"width:720px; margin-left:auto; margin-right:auto; background:url(/esm/reg_cms/www/bgcolo.jpg) center no-repeat;\r\nbackground-size: cover;\">\r\n       \r\n<div class=\"row-fluid\" style=\"margin-top:30px\">\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"font-size:16px; border-top:1px #ddd solid; background:#fff;width:660px;padding:30px;\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'create\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n      sr = params[:record][:study_date] # study_date\r\n      ar = get_model[:registration].where(:study_date=>sr).all\r\n      if ar.count > 15\r\n%>\r\n<script>\r\n    alert(\'รอบการอบรมเต็มแล้วค่ะ กรุณาเลือกรอบการอบรมใหม่ \\nขอบคุณค่ะ\');\r\n</script>\r\n<%\r\n       \r\n        else\r\n      \r\n      \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n        end\r\n        \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n\r\n\r\n<div>\r\n    <img src=\"/esm/rrts_center/www/Chula logo red cross.png\" width=\"300px\">\r\n    <img src=\"/esm/rrts_center/www/EC-CCN logo.png\" width=\"300px\">\r\n</div>\r\n<br/>\r\n<center><h1 style=\'color:#0F5082\'>CRRT Course Registation</h1></center>\r\n<div class=\"control-group \" style=\"width:650px\"><hr/></div>\r\n\r\n    <center><h1>ลงทะเบียนสำเร็จ</h1></center>\r\n    <br/>\r\n    <center><h1>ขอบคุณสำหรับข้อมูลค่ะ</h1></center>\r\n    <br/>\r\n    <center><h3>กรุณารอการตอบกลับทาง e-mail หรือ โทรศัพท์</h3></center>\r\n    <br/>\r\n    <center>\r\n        <%= link_to \'ลงทะเบียนเพิ่ม\', \'create\', :class=>\'btn btn-success\' %>\r\n<% if false %>\r\n        <%= link_to \'ดูรายการลงทะเบียน\', \'index\', :class=>\'btn btn-info\' %>\r\n<% end %>\r\n    </center>\r\n<br/>\r\n<%# link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n    <script>\r\n      $(\'#form-data\').css(\"width\",\"660px\")\r\n\r\n    $(\'#form-data div:first-child\').first().css(\"width\",\"660px\")\r\n    \r\n</script>\r\n    </body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2016-05-18 07:33:57','2016-05-18 07:33:57','confirm','*'),(2267,'history',943,3,'    <div class=\"span7\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                History\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                Content\r\n            </div>\r\n        </div>\r\n    </div>\r\n                ',NULL,NULL,NULL,'2016-05-18 08:54:07','2016-05-18 08:54:07','history',''),(2268,'index',945,2,'\r\n\r\n<div id=\"menu\"></div>\r\n\r\n<script>\r\n    \r\n$.ajax({\r\n  url: \"../Account/menu\",\r\n  context: document.body\r\n}).done(function(data) {\r\n  $(\'#menu\').html(data);\r\n});\r\n\r\n\r\n</script>',NULL,NULL,NULL,'2016-05-18 14:58:29','2016-05-18 14:58:29','index',''),(2269,'menu',945,3,'<h1>Accounting </h1>\r\n\r\n<ul class=\"dshb_icoNav tac\">\r\n							\r\n    \r\n\r\n	<li><%=link_to \"Packages\",\r\n	\"../Package/index\" ,:class=>\'btn\' %> </li>\r\n	\r\n	<li><%=link_to \"Invoice\",\r\n	\"../Invoice/index\" %> </li>\r\n	\r\n	<li><%=link_to \"Payment\",\r\n	\"../Payment/index\" %> </li>    \r\n    \r\n</ul>\r\n\r\n',NULL,NULL,NULL,'2016-05-18 15:02:33','2016-05-18 15:02:33','menu',''),(2270,'index',934,2,'\r\n\r\n<div id=\"menu\"></div>\r\n\r\n<script>\r\n$(\'#menu\').hide();    \r\n$.ajax({\r\n  url: \"../Account/menu\",\r\n  context: document.body\r\n}).done(function(data) {\r\n  $(\'#menu\').html(data);\r\n  $(\'#menu\').slideDown();\r\n});\r\n\r\n\r\n</script>\r\n\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'.\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2016-05-18 15:08:17','2016-05-18 15:08:17','index',''),(2271,'create_contact',921,2,'<div class=\"well\">\r\n    <div class=\"alert alert-warn\" style=\"min-height:200px;padding-top:150px\">\r\n    <h3><center>Thank you very much, we will contact you very soon..</center></h3>\r\n    </div>\r\n</div>\r\n\r\n<% \r\n    if request.post?\r\n        \r\n       model = get_model[:contact]\r\n       \r\n      model.create :name=>params[:name], :tel=>params[:tel], :email=>params[:email], :body=>params[:body]\r\n        \r\n    end\r\n\r\n\r\n%>\r\n\r\n<meta http-equiv=\"refresh\" content=\"2; url=index\" />\r\n\r\n',NULL,NULL,NULL,'2016-05-18 16:54:07','2016-05-18 16:54:07','create_contact','*'),(2273,'customer_login',921,3,'<%\r\n    if session[:customer].nil?\r\n        session[:customer] = {}\r\n        session[:customer][:verify] = false\r\n    end\r\n    \r\n    logo = \"/esm/lifescope_master/endo/content/tage_logo.gif\"\r\n    r_logo = nil\r\n    t_1 = nil\r\n    t_2 = nil\r\n    esm = nil\r\n    app = nil\r\n    if params[:s] and params[:p]\r\n        \r\n        esm = Esm.find_by_name params[:s]\r\n        app = esm.projects.find_by_name params[:p]\r\n        \r\n        if tmp = app.settings.find_by_name(\'logo_path\')\r\n            logo = tmp[:value]\r\n        end\r\n        if tmp = app.settings.find_by_name(\'logo_report_path\')\r\n            r_logo = tmp[:value]\r\n        end\r\n        if tmp = app.settings.find_by_name(\'report_title_1\')\r\n            t_1 = tmp[:value]\r\n        end\r\n        if tmp = app.settings.find_by_name(\'report_title_2\')\r\n            t_2 = tmp[:value]\r\n        end\r\n        \r\n        session[:customer][:title_1] = t_1\r\n        session[:customer][:title_2]  = t_2\r\n        session[:customer][:logo_path] = logo\r\n        session[:customer][:logo_report_path] = r_logo\r\n        session[:customer][:solution_name] = params[:s]\r\n        session[:customer][:project_name]  = params[:p]\r\n    else session[:customer][:logo_path]\r\n        logo = session[:customer][:logo_path]\r\n        t_1  = session[:customer][:title_1]\r\n    end\r\n%>\r\n\r\n<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\">\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n        <title>Customer - Login Page</title>\r\n    \r\n        <!-- Bootstrap framework -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap.min.css\" />\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap-responsive.min.css\" />\r\n        <!-- theme color-->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n        <!-- tooltip -->    \r\n			<link rel=\"stylesheet\" href=\"/gebo/lib/qtip2/jquery.qtip.min.css\" />\r\n        <!-- main styles -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/style.css\" />\r\n    \r\n        <!-- Favicons and the like (avoid using transparent .png) -->\r\n            <link rel=\"shortcut icon\" href=\"favicon.ico\" />\r\n            <link rel=\"apple-touch-icon-precomposed\" href=\"icon.png\" />\r\n    \r\n        <!--[if lte IE 8]>\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n    </head>\r\n    <body class=\"login_page\">\r\n<script src=\"/gebo/js/jquery.min.js\"></script>\r\n<script src=\"/gebo/js/jquery.actual.min.js\"></script>\r\n<script src=\"/gebo/lib/validation/jquery.validate.min.js\"></script>\r\n<script src=\"/gebo/bootstrap/js/bootstrap.min.js\"></script>\r\n\r\n    <center><img height=\'120px\' src=\'<%= logo %>\' style=\'padding:20px\'/></center>\r\n    <center>\r\n        <!--Login to Site : <%= t_1 if t_1 %>-->\r\n    </center>\r\n	<div class=\"login_box\" style=\"\">\r\n		\r\n		<form action=\"customer\" method=\"post\" id=\"login_form\">\r\n			<div class=\" navbar-inner \" style=\"text-align:center;padding-top:5px;color:#fff;font-size:1.2em;\">\r\n		        <div style=\'margin-top:10px\'><%= t_1 if t_1 %></div>\r\n			</div>    \r\n			<div class=\"alert alert-info alert-login\">\r\n				Please login to continue\r\n			</div>\r\n			\r\n			\r\n	   	\r\n\r\n			\r\n			<div class=\"cnt_b\">\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-user\"></i></span>\r\n						<input size=\"20\" id=\"user_login\" placeholder=\"Email or Login ID\" data-icon=\"user\" value=\"\" type=\"text\" name=\"user[login]\" />\r\n					   \r\n					</div>\r\n				</div>\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-lock\"></i></span>\r\n						<input size=\"20\" id=\"user_password\" placeholder=\"Password\" data-icon=\"closed-lock\" type=\"password\" name=\"user[password]\" />\r\n						\r\n					</div>\r\n				</div>\r\n						<input value=\"super_master\" type=\"hidden\" name=\"user[esm]\" id=\"user_esm\" />\r\n						<input value=\"371\" type=\"hidden\" name=\"user[project_id]\" id=\"user_project_id\" />\r\n					\r\n			</div>\r\n			<div class=\"btm_b clearfix\">\r\n				<button class=\"btn btn-inverse pull-right\" type=\"submit\">Sign In</button>\r\n			</div>  \r\n		</form>\r\n\r\n\r\n	</div>\r\n	\r\n	<div class=\"links_b links_btm clearfix\" >\r\n		<!--<span class=\"linkform\"><a href=\"/user/forgot_password\">Forgot password?</a></span> |-->\r\n		Copyright by E.S.M.Solution Co.,Ltd.\r\n	    <!--<span class=\"linkform\">login to www super_master <a href=\"/user/logout?solution=true\">Cancel</a>  </span>-->\r\n	</div>\r\n		\r\n	</div>  \r\n</form>\r\n    <script>\r\n        $(document).ready(function(){\r\n            \r\n			//* boxes animation\r\n			form_wrapper = $(\'.login_box\');\r\n            $(\'.linkform a,.link_reg a\').on(\'click\',function(e){\r\n				var target	= $(this).attr(\'href\'),\r\n					target_height = $(target).actual(\'height\');\r\n				$(form_wrapper).css({\r\n					\'height\'		: form_wrapper.height()\r\n				});	\r\n				$(form_wrapper.find(\'form:visible\')).fadeOut(400,function(){\r\n					form_wrapper.stop().animate({\r\n                        height	: target_height\r\n                    },500,function(){\r\n                        $(target).fadeIn(400);\r\n                        $(\'.links_btm .linkform\').toggle();\r\n						$(form_wrapper).css({\r\n							\'height\'		: \'\'\r\n						});	\r\n                    });\r\n				});\r\n				e.preventDefault();\r\n			});\r\n			\r\n			//* validation\r\n			$(\'#login_form\').validate({\r\n				onkeyup: false,\r\n				errorClass: \'error\',\r\n				validClass: \'valid\',\r\n				rules: {\r\n					username: { required: true, minlength: 3 },\r\n					password: { required: true, minlength: 3 }\r\n				},\r\n				highlight: function(element) {\r\n					$(element).closest(\'div\').addClass(\"f_error\");\r\n				},\r\n				unhighlight: function(element) {\r\n					$(element).closest(\'div\').removeClass(\"f_error\");\r\n				},\r\n				errorPlacement: function(error, element) {\r\n					$(element).closest(\'div\').append(error);\r\n				}\r\n			});\r\n        });\r\n    </script>\r\n\r\n\r\n		<script type=\"text/javascript\">\r\n		try{document.getElementById(\'user_login\').focus();}catch(e){}\r\n		</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n    \r\n\r\n\r\n  	  </script>\r\n	    </body>\r\n	</html>\r\n',NULL,NULL,NULL,'2016-05-19 02:14:52','2016-05-19 02:14:52','customer_login','*'),(2274,'customer',921,2,'<%\r\n    res = {}\r\n    if request.post?\r\n        usr = params[:user][:login]\r\n        pwd = params[:user][:password]\r\n        \r\n        col = \"esm_emr-\\\\#{session[:customer][:solution_name]}\"\r\n        \r\n        mongo = Mongo::MongoClient.new(\"localhost\",27017)\r\n        \r\n    \r\n        db = mongo.db(\"esm_emr-\\\\#{session[:customer][:solution_name]}\")\r\n        # db = mongo.db(\'esm_emr-super3\')\r\n    \r\n        c_role = db.collection(\'www.role\').find(:name=>\'admin\').first\r\n        c_user = db.collection(\'www.user\').find({\'login\':\"\\\\#{usr}\",\'role\':\"\\\\#{BSON::ObjectId.from_string(c_role[\'_id\'].to_s)}\"})\r\n        # c_user = db.collection_names\r\n        \r\n        # r_admin = c_role.find(:name=>\'admin\').to_a[0]\r\n        # r_user  = c_user.find(:login=>usr).to_a[0]\r\n        \r\n        # salt = r_user[\'salt\']\r\n        # h_pass = r_user[\'hashed_password\']\r\n        \r\n        # e_pass = User.encrypt(pwd, salt)\r\n        # if h_pass == e_pass\r\n        #     session[:customer][:verify] = true\r\n        # end\r\n        \r\n        res[:usr] = usr\r\n        res[:pwd] = pwd\r\n        res[:collection] = col\r\n        res[:c_role] = c_role\r\n        res[:c_user] = c_user\r\n        res[:xx] = c_role[\'_id\']\r\n        # res[:r_role] = r_role\r\n        # res[:r_user] = r_user\r\n        # res[:salt]   = salt\r\n        # res[:h_pass] = h_pass\r\n        # res[:e_pass] = e_pass\r\n    elsif @current_role==\'developer\'\r\n        if session[:customer].nil?\r\n            session[:customer] = {}\r\n        end\r\n        session[:customer][:verify] = true\r\n    end\r\n    \r\n    if !session[:customer][:verify]\r\n%>\r\n<script>\r\n    // alert(\'ID and Password does not match\');\r\n    // window.location = \"customer_login\";\r\n</script>\r\n<%\r\n    end\r\n%>\r\n\r\n<pre>\r\n<%= params.to_json.html_safe %>\r\n\r\n<%= session.to_json.html_safe %>\r\n\r\n<%= res.to_json.html_safe %>\r\n</pre>',NULL,NULL,NULL,'2016-05-19 06:07:53','2016-05-19 06:07:53','customer','*'),(2275,'context_menu',878,4,'\r\n<% \r\nmodules = @current_project.documents\r\nmodel = get_model\r\nehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\npatient = (ehr.load_model)[:patient]\r\n#m = modules.collect{|i| {:name=>i.title,:link=>\"../../\\\\#{i.name}/Home/index\",:remote=>false} }\r\nm = []\r\nm <<  {:name=>\'Back to EHR\',:link=>\"../../www/Home/index\",:remote=>false}\r\nobj = this.config\r\nobj << {:name=>\'Links\',:open=>true,:actions=>m}\r\n%>\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\') %>\r\n<%= show_menu obj %>\r\n',NULL,NULL,NULL,'2016-05-25 00:46:12','2016-05-25 00:46:12','context_menu',''),(2276,'context_menu_partial',878,3,'<style>\r\n	.list-x{width:100px;border:0px solid;display:inline-block;}\r\n</style>\r\n<% \r\n	if @current_role != \'pathologist\'\r\n    	modules = @context.get_projects_by_abstract \'ehr.emr\' \r\n    	model = get_model\r\n    	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    	ehr_models = ehr.load_model\r\n    	patient_model = ehr_models[:patient]\r\n    	m = modules.collect{|i| {:name=>i.title,:link=>\"../../\\\\#{i.name}/Home/index\",:remote=>false} }\r\n    	m <<  {:name=>\'Back to EHR\',:link=>\"../../www/Home/index\",:remote=>false}\r\n%>\r\n<%# show_menu m %>\r\n<%\r\n    	if params[:id]\r\n    	\r\n        	pm_model = ehr_models[:patient_module]\r\n        	\r\n        	lpm = pm_model.find(params[:id])\r\n        	    \r\n        	if params[:mode]==\'module\' and lpm\r\n        	    \r\n        	    \r\n        	    apm = pm_model.find(lpm.parent_id)\r\n        	    if lpm and apm\r\n        	        ap = model[:appointment].find(apm.module_id)\r\n        	    else\r\n        	        apm = pm_model.find(params[:id])\r\n        	        ap = model[:appointment].find(apm.module_id)\r\n        	    end\r\n        	    \r\n        	else\r\n        	    ap = model[:appointment].find(params[:id]) \r\n        	    if ap\r\n        	        apm = pm_model.where(:module_id=>ap.id).first\r\n        	    end\r\n        	    \r\n        	end\r\n        	patient = nil\r\n        	if apm\r\n        	   patient = patient_model.find(apm.patient_id) \r\n        	end\r\n        	\r\n        	# if params[:id] or params[:parent_id]\r\n        	    \r\n        	obj = this.config\r\n        	\r\n        	list = []\r\n        	\r\n        	for i in obj\r\n            	for j in i[:actions]\r\n            	  if j[:dashboard]==true\r\n            	    list << j\r\n            	  end\r\n            	end\r\n        	end\r\n    	\r\n    	\r\n    	# \r\n    	\r\n    	\r\n        	# if params[:parent_id]\r\n        	# elsif params[:service]==\'Home\'\r\n        	#     ap = model[:appointment].find(params[:id]) \r\n        	# else\r\n        	#     lpm = pm_model.find(params[:id])\r\n        	#     apm = pm_model.find(lpm.parent_id)\r\n        	#     ap = model[:appointment].find(apm.module_id)\r\n        	# end\r\n        	\r\n        	# obj = [\r\n        	# {:name=>\'Endoscopy\',:open=>true,:actions=>[\r\n        	# {:name=>\'Consignment\',:service=>\'consignment\',:link=>\'../Consignment/index\',:remote=>false},\r\n        	# {:name=>\'Pre Scope\',:service=>\'pre_scope\',:link=>\'../PreScope/index\',:remote=>false},\r\n        	# {:name=>\'Intra Scope\',:service=>\'intra_scope\',:link=>\'../IntraScope/index\',:remote=>false},\r\n        	# {:name=>\'Post Scope\',:service=>\'post_scope\',:link=>\'../PostScope/index\',:remote=>false}]},\r\n        	# {:name=>\'Endoscopist Records\',:open=>true,:actions=>[\r\n        	# {:name=>\'Colonosopy\',:service=>\'colonoscopy\',:link=>\'../Colonoscopy/index\',:remote=>false},\r\n        	# {:name=>\'Gastroscopy\',:service=>\'gastroscopy\',:link=>\'../Gastroscopy/index\',:remote=>false}]},\r\n        	# {:name=>\'ETC\',:open=>true,:actions=>[\r\n        	# {:name=>\'Pathology\',:service=>\'pathology\',:link=>\'../Pathology/index\',:remote=>false},\r\n        	# {:name=>\'Analyses\',:service=>\'report\',:link=>\'../Report/index\',:remote=>false}]}]\r\n        	\r\n        	if patient\r\n	%>\r\n<%# params[:id] %>\r\n<%#list.inspect  %>\r\n<div class=\"accordion-group\" style=\"\">\r\n	<div class=\"accordion-heading\">\r\n		<a href=\"#collapse-0\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n		Visit Detail\r\n		</a>\r\n	</div>\r\n	<div class=\"accordion-body collapse in\" id=\"collapse-0\">\r\n		<div class=\"accordion-inner\">\r\n			<div class=\"alert alert-info\">\r\n				<b>Name : </b><%= patient.first_name %> <%= patient.last_name %> <br/>\r\n				<b>HN : </b><%= patient.hn %> <br/>\r\n				<b>Visit Type : </b><%=t = model[:visit_type].find(ap.visit_type); t.name if t %> <br/>\r\n				<b>Visit Date : </b><%= ap.date  if ap%><br/>\r\n			</div>\r\n			<%\r\n			    return_url = params[:return].nil? ? \"../Home/index\" : params[:return]\r\n			%>\r\n			<% for i in list %>\r\n			<div style=\"padding-bottom:5px;padding-top:5px;border-bottom:1px solid #ccc\">\r\n				<span class=\"list-x\"><%=i[:name]%> : </span>\r\n				<%\r\n					ilist = []\r\n					#   apm\r\n					pm = pm_model.where(:parent_id=>apm.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{i[:service]}\").first\r\n					return_url = \"../Home/patient_record?id=\\\\#{ap.id}\"\r\n					if pm\r\n					   ilist << link_to(\"Edit\",\"\\\\#{i[:link].split(\'/\')[0..-2].join(\'/\')}/edit?id=\\\\#{pm.id}&return=\\\\#{return_url}\",:class=>\'btn\')\r\n					   ilist << link_to(\"Print\",\"\\\\#{i[:link].split(\'/\')[0..-2].join(\'/\')}/print?id=\\\\#{pm.id}\",:class=>\'btn \',:target=>\'_blank\')\r\n					else\r\n					   patient_id = apm.patient_id\r\n					   patient_hn = \'0000\'\r\n					   \r\n					   ilist << link_to(\"Create\",\"\\\\#{i[:link].split(\'/\')[0..-2].join(\'/\')}/create?patient_id=\\\\#{patient_id}&record_name=\\\\#{patient_hn}&parent_id=\\\\#{apm.id}&return=\\\\#{return_url}\",:class=>\'btn\')\r\n					end\r\n					\r\n					\r\n					\r\n					for j in ilist \r\n				%>\r\n				<%=j.html_safe%>\r\n				<% end %>\r\n			</div>\r\n			<% end %>\r\n			<div>\r\n				<br/>\r\n				<center><%=link_to \'Back to Detail\', return_url, :class=>\'btn\' %></center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<% else %>\r\n<%=show_menu this.config %>\r\n<% end %>\r\n<%    \r\n	# obj << {:name=>\'Links\',:open=>true,:actions=>m}\r\n	%>\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\') %>\r\n<% end %>\r\n<% end %>',NULL,NULL,NULL,'2016-05-25 00:46:31','2016-05-25 00:46:31','context_menu',''),(2277,'config',878,1,'[{:name=>\'Records\', :open=>true, :actions=>[\r\n	{:name=>\'Pre-Op\', :service=>\'pre_op\', :link=>\'../PreOp/index\', :remote=>false},\r\n	{:name=>\'PACU\', :service=>\'pacu\', :link=>\'../Pacu/index\', :remote=>false},\r\n	{:name=>\'Post-Op\', :service=>\'post_op\', :link=>\'../PostOp/index\', :remote=>false}\r\n]}]',NULL,NULL,NULL,'2016-05-25 00:47:35','2016-05-25 00:47:35','config',''),(2278,'print_partial',872,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    \r\n    gender = \'ไม่ระบุ\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n    \r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        # res[:patient_innovian] = r_inn\r\n        # res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        res[:project] = @current_project\r\n        res[:project_params] = eval(@current_project[:params])\r\n        \r\n        res[:dx] = this_rec[:diagnosis_note]\r\n        res[:px] = get_model[:pacu_record].find(this_rec[:pacu_record])\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px; line-height:20px;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {\r\n    /*color:#666;*/\r\n    line-height:12px;\r\n}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n /* blockquote, */\r\n /*.wrapper{ width:960px;margin-left:auto;margin-right:auto;} */\r\n body {-webkit-print-color-adjust: exact;}\r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n\r\ntable {\r\n  max-width: 100%;\r\n  background-color: transparent;\r\n  border-collapse: collapse;\r\n  border-spacing: 0;\r\n}\r\n\r\n.table {\r\n  width: 100%;\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.table th,\r\n.table td {\r\n  padding: 8px;\r\n  line-height: 15px;\r\n  text-align: left;\r\n  vertical-align: top;\r\n  border-top: 1px solid #dddddd;\r\n}\r\n\r\n.table th {\r\n  font-weight: bold;\r\n}\r\n\r\n.table thead th {\r\n  vertical-align: bottom;\r\n}\r\n\r\n.table caption + thead tr:first-child th,\r\n.table caption + thead tr:first-child td,\r\n.table colgroup + thead tr:first-child th,\r\n.table colgroup + thead tr:first-child td,\r\n.table thead:first-child tr:first-child th,\r\n.table thead:first-child tr:first-child td {\r\n  border-top: 0;\r\n}\r\n\r\n.table tbody + tbody {\r\n  border-top: 2px solid #dddddd;\r\n}\r\n\r\n.table-bordered {\r\n  border: 1px solid #dddddd;\r\n  border-collapse: separate;\r\n  *border-collapse: collapsed;\r\n  border-left: 0;\r\n  -webkit-border-radius: 4px;\r\n     -moz-border-radius: 4px;\r\n          border-radius: 4px;\r\n}\r\n\r\n.table-bordered th,\r\n.table-bordered td {\r\n  border-left: 1px solid #dddddd;\r\n}\r\n\r\n.table-bordered caption + thead tr:first-child th,\r\n.table-bordered caption + tbody tr:first-child th,\r\n.table-bordered caption + tbody tr:first-child td,\r\n.table-bordered colgroup + thead tr:first-child th,\r\n.table-bordered colgroup + tbody tr:first-child th,\r\n.table-bordered colgroup + tbody tr:first-child td,\r\n.table-bordered thead:first-child tr:first-child th,\r\n.table-bordered tbody:first-child tr:first-child th,\r\n.table-bordered tbody:first-child tr:first-child td {\r\n  border-top: 0;\r\n}\r\n\r\n.table-bordered thead:first-child tr:first-child th:first-child,\r\n.table-bordered tbody:first-child tr:first-child td:first-child {\r\n  -webkit-border-top-left-radius: 4px;\r\n          border-top-left-radius: 4px;\r\n  -moz-border-radius-topleft: 4px;\r\n}\r\n\r\n.table-bordered thead:first-child tr:first-child th:last-child,\r\n.table-bordered tbody:first-child tr:first-child td:last-child {\r\n  -webkit-border-top-right-radius: 4px;\r\n          border-top-right-radius: 4px;\r\n  -moz-border-radius-topright: 4px;\r\n}\r\n\r\n.table-bordered thead:last-child tr:last-child th:first-child,\r\n.table-bordered tbody:last-child tr:last-child td:first-child {\r\n  -webkit-border-radius: 0 0 0 4px;\r\n     -moz-border-radius: 0 0 0 4px;\r\n          border-radius: 0 0 0 4px;\r\n  -webkit-border-bottom-left-radius: 4px;\r\n          border-bottom-left-radius: 4px;\r\n  -moz-border-radius-bottomleft: 4px;\r\n}\r\n\r\n.table-bordered thead:last-child tr:last-child th:last-child,\r\n.table-bordered tbody:last-child tr:last-child td:last-child {\r\n  -webkit-border-bottom-right-radius: 4px;\r\n          border-bottom-right-radius: 4px;\r\n  -moz-border-radius-bottomright: 4px;\r\n}\r\n\r\n.table-striped tbody tr:nth-child(odd) td,\r\n.table-striped tbody tr:nth-child(odd) th {\r\n  background-color: #f9f9f9;\r\n}\r\n\r\n.table tbody tr:hover td,\r\n.table tbody tr:hover th {\r\n  background-color: #f5f5f5;\r\n}\r\n\r\n</style>\r\n<%# stylesheet_link_tag    \"application\"  %>\r\n<script>\r\n    document.title = \"PRINT : (<%= r_pat.hn %>) <%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %>\"\r\n</script>\r\n<body>\r\n	<div class=\"wrapper\">\r\n		<div id=\"head\">\r\n<%\r\n    app_logo = @current_project.get_setting(\'logo_report_path\')\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n			<center><div id=\"logoleft\" style=\"margin-left:0px\"><a href=\"../Home/index\"><img src=\'<%=app_logo%>\' height=\"70px\" style=\"Float:left,top:5px\" /></a></div><h3> <strong><%=this.header%><br/><%=this.form_name%>\r\n					\r\n				</strong></h3>\r\n			</center>\r\n		</div>\r\n		<br />\r\n		<div id=\"page\">\r\n		<!-- Title Section -->\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n				<tr>\r\n					<td > \r\n						<table width=\"100%\">\r\n							<tr>\r\n							    <td width=\'65%\' style=\'vertical-align:top\'>\r\n							        <span class=\" intro\">Date : </span> <v><%= r_app[:date].strftime(\'%d-%m-%Y\') if r_app[:date] %></v>  \r\n							        <span class=\"tab tab intro\">Service : </span> <v><%= render_value \'service\' %> </v><br/>\r\n							        <span class=\" intro\">Diagnosis : </span> <v><%= render_value \'diagnosis_1\' %> </v><br/>\r\n							        <span class=\" intro\">Operation : </span> <v><%= render_value \'operation_1\' %> </v><br/>\r\n							        <% if this_rec[:diagnosis_2] != \'\' %>\r\n							        <span class=\" intro\">Dx/Op 2 : </span> <v><%= render_value \'diagnosis_2\' %> / <%= render_value \'operation_2\' %></v><br/>\r\n							        <% end %>\r\n							        <% if this_rec[:diagnosis_3] != \'\' %>\r\n							        <span class=\" intro\">Dx/Op 3 : </span> <v><%= render_value \'diagnosis_3\' %> /  <%= render_value \'operation_3\' %></v><br/>\r\n							        <% end %>\r\n							        <span class=\' intro\'> ASA : </span> <v><%= render_value(\'asa\') %> </v> <span class=\'tab tab intro\'> Case type : </span> <v><%= render_value(\'case_type\') %> </v> <br/>\r\n							    	<span class=\' intro\' style=\'color:red\'>Allergy : </span> <span style=\'color:red\'><%= this_rec[:allergy] == \'1\' ? render_value(\'allergy_notify\') : render_value(\'allergy\') %> </span><br/>\r\n								</td>\r\n								<td style=\'vertical-align:top\'>\r\n									<span class=\'intro\'>HN : </span><%=r_pat.hn%> <br/>\r\n									<span class=\' intro\'>Name : </span><%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> <br/>\r\n									<span class=\' intro\'> Age : </span> <%= age %> ปี  \r\n									<span class=\'tab intro\'>Gender : </span><%= gender %> <br/>\r\n									<span class=\' intro\'>Ward : </span><%= render_value \'ward\' %> (<%= render_value \'patient_type\' %>) <br/>\r\n								</td>\r\n							</tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n			<hr style=\"margin-top: 5px;\"/>\r\n<style>\r\n    .tab { margin-left: 20px; }\r\n    .intro {\r\n        font-weight:bold;\r\n        width : 170px;\r\n        /*display: inline-block;*/\r\n    }\r\n    v {color:#2561cD};\r\n</style>\r\n			<div style=\"display:block\">\r\n			<!-- Left Content -->\r\n				<table width=\"50%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left\">\r\n				    <tr>\r\n				        <td valign=\'top\'>\r\n				            <b>Demographic Data</b>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td style=\'margin-left:10px\'>\r\n				            <span class=\'tab intro\'>Weight : </span> <v><%= this_rec[:weight] %></v>\r\n				            <span class=\'tab intro\'>Height : </span> <v><%= this_rec[:height] %></v>\r\n				            <span class=\'tab intro\'>BMI : </span> <v><%= this_rec[:bmi] %></v>\r\n				            <br/>\r\n				            \r\n				            <span class=\'tab intro\'>Smoking : </span> <v><%= this_rec[:pack_year] != \'\' ? \"\\\\#{render_value(\'smoking\')} (\\\\#{this_rec[:pack_year]} Pack/Year)\" : render_value(\'smoking\') %></v>\r\n				            <br/>\r\n				            <span class=\'tab intro\'>Alcohol consumption : </span> <v><%= render_value(\'alcohol_consumption\') %></v>\r\n				            <br/>\r\n				            <span class=\'tab intro\'>Drug addiction : </span> <v><%= this_rec[:drug_addiction] == \'1\' ? \"\\\\#{render_value(\'drug_addiction\')} (this_rec[:drug_notify])\" : render_value(\'drug_addiction\') %></v>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td valign=\'top\'>\r\n				            <b>Preoperation</b>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td>\r\n				            <span class=\'tab intro\'>Underlying disease : </span> <v><%= render_value(\'underlying_disease_none\') %></v><br/>\r\n<%\r\n    if this_rec[:underlying_disease_none] == \'1\'\r\n        ud_list = render_value(\'underlying_disease_list\').split(\',\').collect{|i| i.downcase.strip.tr(\' \', \'_\')}\r\n        ud_list.each do |i|\r\n            if i != \'other\'\r\n                title = i.humanize\r\n                if i == \'cvs\'\r\n                    title = \'CVS\'\r\n                end\r\n                sym = i.to_sym\r\n                txt = render_value(i)\r\n                sym_other = \"\\\\#{i}_other\".to_sym\r\n                txt_other = render_value(sym_other.to_s)\r\n%>\r\n                            <span class=\'tab intro\'><%= i %> : </span> <v><%= txt %></v><br/>\r\n<%\r\n                if txt_other != \'\'\r\n%>\r\n                            <!--<span style=\'style=font-size:0.9em;margin-left:40px\'>Note : </span> --> \r\n                            <div style=\"margin-left:40px\"><v style=\'font-size:0.9em;\'><%= txt_other %></v></div>\r\n<%\r\n                end\r\n            else\r\n%>\r\n                            <span class=\'tab intro\'>Disease other : </span> <v><%= render_value(\'disease_other\') %></v><br/>                            \r\n<%\r\n            end\r\n        end\r\n    end \r\n%>\r\n                            <span class=\'tab intro\'>Medication : </span> <v><%= render_value(\'medication\') %></v><br/>\r\n                            <% if this_rec[:medication_other] != \'\' %>\r\n                            <div style=\"margin-left:40px\"><v style=\'font-size:0.9em;\'><%= render_value(\'medication_other\') %></v></div>\r\n                            <% end %>\r\n                            <span class=\'tab intro\'>Previous Anesthesia : </span> <v><%= render_value(\'previous_anesthesia\') %></v>\r\n                            <% if this_rec[:previous_anesthesia] == \'1\' %>\r\n                            <v>(<%= render_value(\'previous_anesthesia_yes\') %>)</v><br/>\r\n                            <span class=\'tab intro\'>Complications : </span> <v><%= render_value(\'complications\') %></v><br/>\r\n                            <% else %>\r\n                            <br/>\r\n                            <% end %>\r\n				        </td>\r\n				    </tr>\r\n				</table>\r\n				<!-- Right Content -->\r\n				<table width=\"50%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left\">\r\n				    <tr>\r\n				        <td valign=\'top\'>\r\n				            <b>Physical exam and Lab evaluation</b>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td >\r\n				            <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\r\n					            <tbody>\r\n					            <tr>\r\n					                <td width=\"30%\"><span class=\"tab\"></span><b>Vital Signs</b></td>\r\n					                <td width=\"10%\">BP</td>\r\n					                <td width=\"20%\"><v><%= this_rec[:bp] %> / <%= this_rec[:bp_2] %></v></td>\r\n					                <td width=\"10%\">PR</td>\r\n					                <td width=\"20%\"><v><%= this_rec[:pr] %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td>RR</td>\r\n					                <td><v><%= this_rec[:rr] %></v></td>\r\n					                <td>SpO<sub>2</sub></td>\r\n					                <td><v><%= this_rec[:spo2] %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td>BT</td>\r\n					                <td><v><%= this_rec[:bt] %></v></td>\r\n					                <td> </td>\r\n					                <td> </td>\r\n					            </tr>\r\n					        </tbody></table>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td>\r\n				            <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\r\n					            <tbody><tr>\r\n					                <td width=\"20%\"><span class=\"tab\"></span><b>Airway</b></td>\r\n					                <td width=\"80%\"><v><%= render_value(\'mallampati_class\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td><v><%= render_value(\'thyromental_distance\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td><v><%= render_value(\'range_of_neck\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td><v><%= render_value(\'interincisor_distance\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td>\r\n					                    <v><%= render_value(\'dentition\') %></v>\r\n					                    <% if this_rec[:dentition_other] != \'\' %>\r\n					                    <br/>\r\n					                    <v style=\'font-size:0.9em;margin-left:10px;\'>Other : <%= this_rec[:dentition_other] %></v>\r\n					                    <% end %>\r\n					                </td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td><v ><%= render_value(\'other_problem\') %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td> </td>\r\n					                <td><v><%= render_value(\'expected_difficult_airway\') %></v></td>\r\n					            </tr>\r\n					        </tbody></table>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td>\r\n				            <span class=\'tab intro\'>Physical examination</span><br/>\r\n				            <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\r\n					            <tbody><tr>\r\n					                <td width=\"20%\"><span class=\"tab\"></span><span class=\"tab\"></span><b>Heart</b></td>\r\n					                <td width=\'5%\'></td>\r\n					                <td width=\"20%\"><v><%= render_value(\'heart\') %></v></td>\r\n					                <td width=\"55%\"><v><%= this_rec[:heart_other] != \'\' ? render_value(\'heart_other\') : \'-\' %></v></td>\r\n					            </tr>\r\n					            <tr>\r\n					                <td ><span class=\"tab\"></span><span class=\"tab\"></span><b>Lungs</b></td>\r\n					                <td></td>\r\n					                <td ><v><%= render_value(\'lungs\') %></v></td>\r\n					                <td ><v><%= this_rec[:lungs_other] != \'\' ? render_value(\'lung_other\') : \'-\' %></v></td>\r\n					            </tr>\r\n					        </tbody></table>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td>\r\n				            <span class=\'tab intro\'>Lab investigation</span><br/>\r\n				            <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\r\n					            <tbody><tr>\r\n					                <td width=\"100%\" style=\'padding-left:40px\'>\r\n					                    <span class=\"intro\">Hb : </span> <v><%= this_rec[:lab_hb] %></v> \r\n					                    <span class=\"tab intro\">Hct : </span> <v><%= this_rec[:lab_hct] %></v>\r\n					                    <span class=\"tab intro\">WBC : </span> <v><%= this_rec[:lab_wbc] %></v>\r\n					                    <span class=\"tab intro\">Plt : </span> <v><%= this_rec[:lab_plt] %></v><br/>\r\n					                    <span class=\" intro\">BS : </span> <v><%= this_rec[:lab_bs] %></v>\r\n					                    <span class=\"tab intro\">BUN : </span> <v><%= this_rec[:lab_bun] %></v>\r\n					                    <span class=\"tab intro\">Cr : </span> <v><%= this_rec[:lab_cr] %></v><br/>\r\n					                    <span class=\"intro\">Na : </span> <v><%= this_rec[:lab_na] %></v> \r\n					                    <span class=\"tab intro\">K : </span> <v><%= this_rec[:lab_k] %></v>\r\n					                    <span class=\"tab intro\">Cl : </span> <v><%= this_rec[:lab_cl] %></v>\r\n					                    <span class=\"tab intro\">CO2 : </span> <v><%= this_rec[:lab_co2] %></v><br/>\r\n					                    <span class=\" intro\">PT : </span> <v><%= this_rec[:lab_pt_1] %> / <%= this_rec[:lab_pt_2] %></v>\r\n					                    <span class=\"tab intro\">PTT : </span> <v><%= this_rec[:lab_ptt_1] %> / <%= this_rec[:lab_ptt_2] %></v>\r\n					                    <span class=\"tab intro\">INR : </span> <v><%= this_rec[:lab_inr] %></v><br/>\r\n					                    <span class=\'intro\'>CXR </span>\r\n					                    <% if this_rec[:lab_cxr] != \'\' %>\r\n					                    <v>(<%= render_value(\'lab_cxr\') %>) <%= this_rec[:lab_cxr_note] if this_rec[:lab_cxr_note] != \'\' %></v><br/>\r\n					                    <% else %>\r\n					                    <br/>\r\n					                    <% end %>\r\n					                    <span class=\'intro\'>EKG </span>\r\n					                    <% if this_rec[:lab_ekg] != \'\' %>\r\n					                    <v>(<%= render_value(\'lab_ekg\') %>) <%= this_rec[:lab_ekg_note] if this_rec[:lab_ekg_note] != \'\' %></v><br/>\r\n					                    <% else %>\r\n					                    <br/>\r\n					                    <% end %>\r\n					                </td>\r\n					            </tr>\r\n					        </tbody></table>\r\n				        </td>\r\n				     </tr>\r\n				     <tr>\r\n				         <td valign=\'top\'><b>Anesthetic plan</b></td>\r\n				     </tr>\r\n				     <tr>\r\n				         <td>\r\n				             <span class=\'tab intro\'>Pre medication : </span> <v><%= render_value(\'pre_medication\') %></v><br/>\r\n				             <% if this_rec[:premed_other] != \'\' %>\r\n				             <v style=\'margin-left:40px;font-size:0.9em\'><%= render_value(\'premed_other\') %></v><br/>\r\n				             <% end %>\r\n				             <span class=\'tab intro\'>ICU : </span> <v><%= render_value(\'icu\') %></v><br/>\r\n				             <span class=\'tab intro\'>Blood product preparation : </span> <v><%= this_rec[:blood_product] != \'0\' ? \'Yes\' : render_value(\'blood_product\') %></v><br/>\r\n				            <% \r\n				                if this_rec[:blood_product] != \'0\' \r\n				                    bl = this_rec[:blood_product].split(\'|\')\r\n				                    if bl.index(\'1\')\r\n				            %>\r\n				            <span class=\'tab intro\'></span><span class=\'tab intro\'>PRC : </span> <v><%= this_rec[:blood_prc] %></v> u.<br/> \r\n				            <% \r\n				                    end # if 1 \r\n				                    if bl.index(\'2\')\r\n				            %>\r\n				            <span class=\'tab intro\'></span><span class=\'tab intro\'>FFP : </span> <v><%= this_rec[:blood_ffp] %></v> u.<br/> \r\n				            <% \r\n				                    end # if 2\r\n				                    if bl.index(\'3\')\r\n				            %>\r\n				            <span class=\'tab intro\'></span><span class=\'tab intro\'>Plt : </span> <v><%= this_rec[:blood_plt] %></v> u.<br/> \r\n				            <% \r\n				                    end # if 3\r\n				                    if bl.index(\'99\')\r\n				            %>\r\n				            <span class=\'tab intro\'></span><span class=\'tab intro\'>Other : </span> <v><%= this_rec[:blood_other] %></v> u.<br/> \r\n				            <% \r\n				                    end # 99\r\n				                end\r\n				            %>\r\n				            <%\r\n				                pl = this_rec[:problem_lists]\r\n				                al = this_rec[:anesthetic_plan]\r\n				                pp = get_model[:note_text].find(pl)\r\n				                aa = get_model[:note_text].find(al)\r\n				            %>\r\n				            <span class=\'tab intro\'>Problem lists : </span> <v><%= \'-\' if pl.empty? %></v><br/>\r\n				            <% pp.each_with_index do |i, n| %>\r\n				            <span class=\'tab intro\'></span><span class=\'tab intro\'></span> <v><%= n + 1 %>. <%= i[:note] %></v><br/>\r\n				            <% end %>\r\n				            <span class=\'tab intro\'>Anesthetic plan : </span> <v><%= \'-\' if al.empty? %></v><br/>\r\n				            <% aa.each_with_index do |i, n| %>\r\n				            <span class=\'tab intro\'></span><span class=\'tab intro\'></span> <v><%= n + 1 %>. <%= i[:note] %></v><br/>\r\n				            <% end %>\r\n				            <br/>\r\n				            <span class=\'tab\'><%= render_value(\'possible_complications\') %></span><br/>\r\n				            <span class=\'tab intro\'>Post operative pain : </span> <v><%= \'-\' if this_rec[:post_operative_pain] == \'\' %></v><br/>\r\n				            <%\r\n				                if this_rec[:post_operative_pain] != \'\'\r\n				                    pol = this_rec[:post_operative_pain].split(\'|\')\r\n				                    pol_txt = render_value(\'post_operative_pain\').split(\',\').collect{|i| i.strip}\r\n				                    txt_list = []\r\n				                    pol.each do |i|\r\n				                        if i == \'4\' or i == \'6\' or i == \'7\' or i == \'99\'\r\n				                            sym = \"\\\\#{pol_txt[pol.index(i)]} note\".downcase.tr(\' \', \'_\').to_sym\r\n				                            val = this_rec[sym]\r\n				            %>  \r\n				            <span class=\'tab \'></span><span class=\'tab \'><%= pol_txt[pol.index(i)] %> : </span> <v><%= val %></v><br/>\r\n				            <%\r\n				                        else\r\n				                            txt_list << pol_txt[pol.index(i)] \r\n				                        end\r\n				                    end\r\n				            %>\r\n				            \r\n				            <span class=\'tab \'></span><span class=\'tab \'></span><%= txt_list.join(\', \') if !txt_list.empty? %>\r\n				            <%\r\n				                end\r\n				            %>\r\n				         </td>\r\n				     </tr>\r\n				</table>\r\n				\r\n				\r\n				<div class=\"clear\"></div>\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n		<!-- Footer -->\r\n		<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n			<span style=\"float:right\">\r\n				<strong>Record Date Time :</strong>&nbsp;<%= this_rec[:created_at].strftime(\'%d-%m-%Y %H:%M\') %><br />\r\n				<strong>Printed Date Time :</strong>&nbsp;<%= Time.now.strftime(\'%d-%m-%Y %H:%M\') %>\r\n			</span>\r\n			<strong>Anesthesiologist Name : </strong> <%= render_value \'recorder_name_1\' %> <br/>\r\n			<strong>Anesthesiologist signature : </strong> ................................\r\n			<br />\r\n		</div>\r\n		<div class=\"clear\"></div>\r\n	</div>\r\n</body>\r\n</html>\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        // $(\'#pacu-content\').load(\'pacu_content?id=<%=r_pat_mod[:module_id]%>\');\r\n        // $(\'#diag-content\').load(\'diag_content?id=<%=r_pat_mod[:module_id]%>\');\r\n    })\r\n</script>\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-05-25 15:52:56','2016-05-25 15:52:56','print_partial',''),(2279,'document_name',946,1,'\'note_text\'',NULL,NULL,NULL,'2016-05-25 15:58:07','2016-05-25 15:58:07',NULL,NULL),(2280,'header',872,1,'\'King Chulalongkorn Memorial Hospital\'',NULL,NULL,NULL,'2016-05-25 16:37:36','2016-05-25 16:37:36','header',''),(2281,'form_name',872,1,'\'Anesthetic Evaluation Record\'',NULL,NULL,NULL,'2016-05-25 16:38:02','2016-05-25 16:38:02','form_name',''),(2282,'print',872,3,'<%= this.print_partial.html_safe %>\r\n<% if @current_role!=\'developer\' %>\r\n<script>\r\n    var millisecondsToWait = 2000;\r\n    setTimeout(function() {\r\n        window.print();\r\n    }, millisecondsToWait);\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2016-05-25 20:17:58','2016-05-25 20:17:58','print',''),(2283,'show',872,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    atts = @ehr_project.get_model :attachment\r\n    att =  atts.find(@patient_module.report)\r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n<% if att %>\r\n<%= link_to \'<i class=\"splashy-document_small_download\"></i> PDF\'.html_safe, att.path,:target=>\'_blank\',:class=>\'btn btn-mini btn-info\' %>\r\n<% end %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:950px\">\r\n\r\n<%= this.print_partial.html_safe %>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-05-25 20:19:37','2016-05-25 20:19:37','show',''),(2284,'print_partial',873,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    \r\n    gender = \'ไม่ระบุ\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n    \r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # check pre-op exist ?\r\n    x_pre_op = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id], :module_name=>\"\\\\#{@current_project.name}#pre_op\").first\r\n    r_pre_op = nil\r\n    if x_pre_op\r\n        r_pre_op = get_model[:pre_op].find(x_pre_op[:module_id])\r\n    end\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        # res[:patient_innovian] = r_inn\r\n        # res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        res[:project] = @current_project\r\n        res[:project_params] = eval(@current_project[:params])\r\n        \r\n        res[:dx] = this_rec[:diagnosis_note]\r\n        res[:px] = get_model[:pacu_record].find(this_rec[:pacu_record])\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px; line-height:20px;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {\r\n    /*color:#666;*/\r\n    line-height:12px;\r\n}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n /* blockquote, */\r\n /*.wrapper{ width:960px;margin-left:auto;margin-right:auto;} */\r\n body {-webkit-print-color-adjust: exact;}\r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n\r\ntable {\r\n  max-width: 100%;\r\n  background-color: transparent;\r\n  border-collapse: collapse;\r\n  border-spacing: 0;\r\n}\r\n\r\n.table {\r\n  width: 100%;\r\n  margin-bottom: 18px;\r\n}\r\n\r\n.table th,\r\n.table td {\r\n  padding: 8px;\r\n  line-height: 15px;\r\n  text-align: left;\r\n  vertical-align: top;\r\n  border-top: 1px solid #dddddd;\r\n}\r\n\r\n.table th {\r\n  font-weight: bold;\r\n}\r\n\r\n.table thead th {\r\n  vertical-align: bottom;\r\n}\r\n\r\n.table caption + thead tr:first-child th,\r\n.table caption + thead tr:first-child td,\r\n.table colgroup + thead tr:first-child th,\r\n.table colgroup + thead tr:first-child td,\r\n.table thead:first-child tr:first-child th,\r\n.table thead:first-child tr:first-child td {\r\n  border-top: 0;\r\n}\r\n\r\n.table tbody + tbody {\r\n  border-top: 2px solid #dddddd;\r\n}\r\n\r\n.table-bordered {\r\n  border: 1px solid #dddddd;\r\n  border-collapse: separate;\r\n  *border-collapse: collapsed;\r\n  border-left: 0;\r\n  -webkit-border-radius: 4px;\r\n     -moz-border-radius: 4px;\r\n          border-radius: 4px;\r\n}\r\n\r\n.table-bordered th,\r\n.table-bordered td {\r\n  border-left: 1px solid #dddddd;\r\n}\r\n\r\n.table-bordered caption + thead tr:first-child th,\r\n.table-bordered caption + tbody tr:first-child th,\r\n.table-bordered caption + tbody tr:first-child td,\r\n.table-bordered colgroup + thead tr:first-child th,\r\n.table-bordered colgroup + tbody tr:first-child th,\r\n.table-bordered colgroup + tbody tr:first-child td,\r\n.table-bordered thead:first-child tr:first-child th,\r\n.table-bordered tbody:first-child tr:first-child th,\r\n.table-bordered tbody:first-child tr:first-child td {\r\n  border-top: 0;\r\n}\r\n\r\n.table-bordered thead:first-child tr:first-child th:first-child,\r\n.table-bordered tbody:first-child tr:first-child td:first-child {\r\n  -webkit-border-top-left-radius: 4px;\r\n          border-top-left-radius: 4px;\r\n  -moz-border-radius-topleft: 4px;\r\n}\r\n\r\n.table-bordered thead:first-child tr:first-child th:last-child,\r\n.table-bordered tbody:first-child tr:first-child td:last-child {\r\n  -webkit-border-top-right-radius: 4px;\r\n          border-top-right-radius: 4px;\r\n  -moz-border-radius-topright: 4px;\r\n}\r\n\r\n.table-bordered thead:last-child tr:last-child th:first-child,\r\n.table-bordered tbody:last-child tr:last-child td:first-child {\r\n  -webkit-border-radius: 0 0 0 4px;\r\n     -moz-border-radius: 0 0 0 4px;\r\n          border-radius: 0 0 0 4px;\r\n  -webkit-border-bottom-left-radius: 4px;\r\n          border-bottom-left-radius: 4px;\r\n  -moz-border-radius-bottomleft: 4px;\r\n}\r\n\r\n.table-bordered thead:last-child tr:last-child th:last-child,\r\n.table-bordered tbody:last-child tr:last-child td:last-child {\r\n  -webkit-border-bottom-right-radius: 4px;\r\n          border-bottom-right-radius: 4px;\r\n  -moz-border-radius-bottomright: 4px;\r\n}\r\n\r\n.table-striped tbody tr:nth-child(odd) td,\r\n.table-striped tbody tr:nth-child(odd) th {\r\n  background-color: #f9f9f9;\r\n}\r\n\r\n.table tbody tr:hover td,\r\n.table tbody tr:hover th {\r\n  background-color: #f5f5f5;\r\n}\r\n\r\n</style>\r\n<%# stylesheet_link_tag    \"application\"  %>\r\n<script>\r\n    document.title = \"PRINT : (<%= r_pat.hn %>) <%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %>\"\r\n</script>\r\n<body>\r\n	<div class=\"wrapper\">\r\n		<div id=\"head\">\r\n<%\r\n    app_logo = @current_project.get_setting(\'logo_report_path\')\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n			<center><div id=\"logoleft\" style=\"margin-left:0px\"><a href=\"../Home/index\"><img src=\'<%=app_logo%>\' height=\"70px\" style=\"Float:left,top:5px\" /></a></div><h3> <strong><%=this.header%><br/><%=this.form_name%>\r\n				\r\n				</strong></h3>\r\n			</center>\r\n		</div>\r\n		<br />\r\n		<div id=\"page\">\r\n		<!-- Title Section -->\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n				<tr>\r\n					<td > \r\n						<table width=\"100%\">\r\n							<tr>\r\n							    <td width=\'65%\' style=\'vertical-align:top\'>\r\n							        <span class=\" intro\">Date : </span> <v><%= r_app[:date].strftime(\'%d-%m-%Y\') if r_app[:date] %></v> <br/> \r\n							        <span class=\" intro\">Diagnosis : </span> <v><%= render_value \'diagnosis\' %> </v><br/>\r\n							        <span class=\" intro\">Operation : </span> <v><%= render_value \'operation\' %> </v><br/>\r\n							        <%\r\n							            ct = {\'0\'=>\"Emergency\",\'1\'=>\"Elective\"}\r\n							            pt = {\'1\'=>\'IPD\',\'2\'=>\'OPD\'}\r\n							        %>\r\n							        <span class=\' intro\'> Case type : </span> <v><%= r_pre_op.nil? ? \'-\' : ct[r_pre_op[:case_type]] %> </v> <br/>\r\n							    	<span class=\' intro\' style=\'color:red\'>Allergy : </span> <span style=\'color:red\'><%= r_pre_op.nil? ? \'N/A\' : r_pre_op[:allergy_notify] %> </span><br/>\r\n								</td>\r\n								<td style=\'vertical-align:top\'>\r\n									<span class=\'intro\'>HN : </span><%=r_pat.hn%> <br/>\r\n									<span class=\' intro\'>Name : </span><%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> <br/>\r\n									<span class=\' intro\'> Age : </span> <%= age %> ปี  \r\n									<span class=\'tab intro\'>Gender : </span><%= gender %> <br/>\r\n									<span class=\' intro\'>Ward : </span><%= r_pre_op.nil? ? \'-\' : r_pre_op[:ward] %> (<%= r_pre_op.nil? ? \'-\' : pt[r_pre_op[:patient_type]] %>) <br/>\r\n								</td>\r\n							</tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n			<hr style=\"margin-top: 5px;\"/>\r\n<style>\r\n    .tab { margin-left: 20px; }\r\n    .intro {\r\n        font-weight:bold;\r\n        width : 170px;\r\n        /*display: inline-block;*/\r\n    }\r\n    v {color:#2561cD};\r\n</style>\r\n			<div style=\"display:block\">\r\n			<!-- Main Content -->\r\n				<table width=\"100%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left\">\r\n				    <tr>\r\n				        <td valign=\'top\'>\r\n				            <b>Post-op pain control and Complication</b>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td>\r\n				            <span class=\"tab intro\">Postop pain control route</span><br/>\r\n				            <span class=\'tab\'></span><span class=\'tab intro\'>Intravenous : </span> <v><%= render_value \'postop_pain_control_route\' %></v> <br/>\r\n				            <span class=\'tab\'></span><span class=\'tab intro\'>Epidural : </span> <v><%= render_value \'epidural\' %></v> <br/>\r\n				            <span class=\'tab\'></span><span class=\'tab intro\'>Spinal : </span> <v><%= render_value \'spinal\' %></v> <br/>\r\n				            <span class=\'tab\'></span><span class=\'tab intro\'>PNB : </span> <v><%= render_value \'pnb\' %></v> <br/>\r\n				            <span class=\'tab\'></span><span class=\'tab intro\'>Oral : </span> <v><%= render_value \'oral\' %> <%= \" (\\\\#{this_rec[:oral_other]})\" if this_rec[:oral_other] != \'\' %></v> <br/>\r\n				            <span class=\'tab\'></span><span class=\'tab intro\'>Pain Score (at Rest) : </span> <v><%= render_value \'pain_score_rest\' %></v> <br/>\r\n				            <span class=\'tab\'></span><span class=\'tab intro\'>Pain Score (at Motion) : </span> <v><%= render_value \'pain_score_motion\' %></v> <br/>\r\n				            <span class=\'tab\'></span><span class=\'tab intro\'>Patient Satisfaction : </span> <v><%= render_value \'patient_satisfaction\' %></v> <br/>\r\n				            <span class=\'tab\'></span><span class=\'tab intro\'>Sedation : </span> <v><%= render_value \'sedation\' %></v> <br/>\r\n				        </td>\r\n				    </tr>\r\n				</table>\r\n				<table width=\"100%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left\">\r\n				    <tr>\r\n				        <td valign=\'top\'>\r\n				            <b>Intra Operative Complication</b>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td>\r\n				            <span class=\'tab intro\'>Complications : </span> <v><%= this_rec[:intra_complications_yes_no] == \'1\' ? \'Yes\' : \'No\' %></v><br/>\r\n<%  \r\n\r\n    if  this_rec[:intra_complications_yes_no] == \'1\'\r\n		cl = render_value(\'intra_complications\').split(\',\').collect{|i| i.strip}\r\n		cl.each do |i|\r\n		    sym = \"intra_\\\\#{i.downcase.tr(\' \',\'_\').to_sym}\"\r\n		    \r\n%>  \r\n                            <span class=\'tab intro\'><%= i %> : </span> <v><%= render_value(sym.to_s) %></v><br/>\r\n<%\r\n        end\r\n    end\r\n%>\r\n				        </td>\r\n				        \r\n				    </tr>\r\n					<tr>\r\n						<td>\r\n							<span class=\"tab intro\">Case Type :</span> <v><%= render_value(\'intra_case_type\') != \'\' ? render_value(\'intra_case_type\') : \'-\' %></v>\r\n						</td>\r\n					</tr>\r\n				</table>\r\n				<table width=\"100%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left\">\r\n				    <tr>\r\n				        <td valign=\'top\'>\r\n				            <b>Complication in post operative 24 hr.</b>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td>\r\n				            <span class=\'tab intro\'>Complications : </span> <v><%= this_rec[:complications_yes_no] == \'1\' ? \'Yes\' : \'No\' %></v><br/>\r\n<%  \r\n\r\n    if  this_rec[:complications_yes_no] == \'1\'\r\n		cl = render_value(\'complications\').split(\',\').collect{|i| i.strip}\r\n		cl.each do |i|\r\n		    sym = i.downcase.tr(\' \',\'_\').to_sym\r\n		    \r\n%>  \r\n                            <span class=\'tab intro\'><%= i %> : </span> <v><%= render_value(i.downcase) %></v><br/>\r\n<%\r\n        end\r\n    end\r\n%>\r\n				        </td>\r\n				        \r\n				    </tr>\r\n				</table>\r\n				\r\n				\r\n				<div class=\"clear\"></div>\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n		<!-- Footer -->\r\n		<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n			<span style=\"float:right\">\r\n				<strong>Record Date Time :</strong>&nbsp;<%= this_rec[:created_at].strftime(\'%d-%m-%Y %H:%M\') %><br />\r\n				<strong>Printed Date Time :</strong>&nbsp;<%= Time.now.strftime(\'%d-%m-%Y %H:%M\') %>\r\n			</span>\r\n			<strong>Anesthesiologist Name : </strong> <%= render_value \'recorder_name_1\' %> <br/>\r\n			<strong>Anesthesiologist signature : </strong> ................................\r\n			<br />\r\n		</div>\r\n		<div class=\"clear\"></div>\r\n	</div>\r\n</body>\r\n</html>\r\n\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-05-25 20:46:20','2016-05-25 20:46:20','print',''),(2285,'form_name',873,1,'\'Post Anesthetic Visit\'',NULL,NULL,NULL,'2016-05-25 21:27:18','2016-05-25 21:27:18','form_name',''),(2286,'header',873,1,'\'King Chulalongkorn Memorial Hospital\'',NULL,NULL,NULL,'2016-05-25 21:27:42','2016-05-25 21:27:42','header',''),(2287,'header',882,1,'\'King Chulalongkorn Memorial Hospital\'',NULL,NULL,NULL,'2016-05-25 21:31:43','2016-05-25 21:31:43','header',''),(2288,'form_name',882,1,'\'PACU Record\'',NULL,NULL,NULL,'2016-05-25 21:32:49','2016-05-25 21:32:49','form_name',''),(2289,'show',873,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    atts = @ehr_project.get_model :attachment\r\n    att =  atts.find(@patient_module.report)\r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n<% if att %>\r\n<%= link_to \'<i class=\"splashy-document_small_download\"></i> PDF\'.html_safe, att.path,:target=>\'_blank\',:class=>\'btn btn-mini btn-info\' %>\r\n<% end %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:950px\">\r\n\r\n<%= this.print_partial.html_safe %>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-05-25 21:35:01','2016-05-25 21:35:01','show',''),(2290,'print',873,3,'<%= this.print_partial.html_safe %>\r\n<% if @current_role!=\'developer\' %>\r\n<script>\r\n    var millisecondsToWait = 2000;\r\n    setTimeout(function() {\r\n        window.print();\r\n    }, millisecondsToWait);\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2016-05-25 21:35:16','2016-05-25 21:35:16','print',''),(2291,'print',882,3,'<%= this.print_partial.html_safe %>\r\n<% if @current_role!=\'developer\' %>\r\n<script>\r\n    var millisecondsToWait = 2000;\r\n    setTimeout(function() {\r\n        window.print();\r\n    }, millisecondsToWait);\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2016-05-25 22:31:14','2016-05-25 22:31:14','print',''),(2292,'document_name',947,1,'\'endoscopic_exam\'',NULL,NULL,NULL,'2016-05-27 05:15:02','2016-05-27 05:15:02',NULL,NULL),(2293,'rtmp',231,2,'<iframe src=\"//content.jwplatform.com/players/vFn3puiA-57sgyeMw.html\" width=\"480\" height=\"270\" frameborder=\"0\" scrolling=\"auto\" allowfullscreen></iframe>',NULL,NULL,NULL,'2016-05-27 09:48:48','2016-05-27 09:48:48','rtmp','*'),(2294,'document_name',949,1,'\'appointment\'',NULL,NULL,NULL,'2016-05-31 05:24:24','2016-05-31 05:24:24',NULL,NULL),(2295,'index',950,2,'<style>\r\n                .dataTables_wrapper{position:relative;overflow:hidden}\r\n                .dataTables_wrapper table.table {clear:both;margin-bottom:6px!important;max-width:inherit}\r\n                .dataTables_wrapper table.table thead .sorting,table.table thead .sorting_asc,table.table thead .sorting_desc,table.table thead .sorting_asc_disabled,table.table thead .sorting_desc_disabled{cursor:hand;cursor:pointer}\r\n                .dataTables_wrapper table.table thead .sorting{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_both.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc_disabled.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc_disabled.png) no-repeat center right}\r\n</style>\r\n<!-- datatable -->\r\n            <script src=\"/gebo/lib/datatables/jquery.dataTables.min.js\"></script>\r\n            <script src=\"/gebo/lib/datatables/extras/Scroller/media/js/Scroller.min.js\"></script>\r\n            <!-- datatable functions -->\r\n            <script src=\"/gebo/js/gebo_datatables.js\"></script>\r\n<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n	session[module_name]={:date=>params[:date],:stamp=>Time.now.strftime(\'%d/%m/%Y\')}\r\n	end\r\n	if session[module_name] and session[module_name][:stamp] == Time.now.strftime(\'%d/%m/%Y\')\r\n	  params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n	his = session[:his]\r\n%>\r\n	\r\n<%#session[module_name].inspect %>\r\n<%\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    if params[:reset_lock]\r\n	    l = get_model[:locker].find(params[:reset_lock])\r\n        l.destroy if l\r\n	end\r\n	if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Patient Record\"\r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n    // window.location = \"../OutPatientForm/create?patient_id=<%=patient.id.to_s%>&record_name=<%=patient[:hn]%>&parent_id=<%=rec_pm_app.id.to_s%>&return=../Home/index\";\r\n</script>\r\n<%\r\n        end\r\n    end\r\n	\r\n	\r\n	\r\n	if params[:obj_id]\r\n	    now = Time.now \r\n	\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n					<!--<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Add Visit</button></a>-->\r\n					<a href=\"javascript:add_patient()\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-contact_blue_add\"></i><br />Add Patient</button></a>\r\n					<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Calendar</button></a>\r\n					<a href=\"../Report/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\" >\r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n					<h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n    \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"close\" style=\"float:right;\"  data-dismiss=\"modal\">X</a>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>เลขที่บัตรประชาชน : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                \r\n<span id=\'span-his_btn\' style=\'margin-left:20px\'>\r\n\r\n  \r\n  \r\n<% if true #and session[:his]%>\r\n<span id=\'his-status\'>\r\nWelcome <%= session[:his] %>\r\n\r\n  </span>\r\n    <a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient</a>\r\n<% else %>\r\n<span id=\'his-status\'>\r\nPlease login to get HN from HIS\r\n\r\n  </span>\r\n  <span id=\'temp-get-his\'>&nbsp;</span>\r\n            <span class=\'login-block\'>\r\n                <!--<div class=\'clear\'></div>-->\r\n                <div id=\"his-user\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px\">\r\n                    <span class=\"\"><label>Username : </label></span>	\r\n                    <input autofocus=\"\" type=\"text\" name=\"username\" id=\"input-username\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\">\r\n                </div>\r\n                <div id=\"his-pass\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Password  : </label></span>	\r\n                    <input type=\"password\" name=\"password\" id=\"input-password\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\">\r\n                </div>\r\n                <!--<div class=\'clear\'></div>-->\r\n            </span>\r\n<% end %>\r\n</span>\r\n\r\n<span id=\'span-btn\'>\r\n<% if true #session[:his] %>\r\n <!-- <a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a> -->\r\n<% else %>\r\n  <span id=\'temp-his-logout\'>&nbsp;</span>\r\n  <a href=\'javascript:void(0)\' id=\'his-login\' class=\'btn btn-info\'>HIS Login</a>\r\n<% end %>\r\n</span>\r\n\r\n            \r\n\r\n                <br/>\r\n                <div class=\'login-block btn btn-mini\' id=\'login-cancel\'  >x</div>\r\n                <span style=\'color:blue\' id=\'patient-msg\'></span>\r\n                <div class=\'clear\'></div>\r\n            \r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\" selected><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <div id=\'temporary\' style=\'display:none\'></div>\r\n                <input type=\"hidden\" name=\"record[status]\" id=\"data-status\" value=\"Appointed\"/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Patient Record\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n\r\n    function init_fields(b) {\r\n        $(\'#data-public_id\').prop(\'readonly\', b);\r\n        $(\'#data-first_name\').prop(\'readonly\',b);\r\n        $(\'#data-last_name\').prop(\'readonly\',b);\r\n        $(\'#data-prefix_name\').prop(\'readonly\',b);\r\n        $(\'#input-prefix_name\').prop(\'readonly\',b);\r\n        $(\'#data-gender\').prop(\'readonly\',b);\r\n        $(\'#data-birth_date\').prop(\'readonly\',b);\r\n        \r\n        if (!b) {\r\n            $(\'#data-public_id\').val(\"\");\r\n            $(\'#data-first_name\').val(\"\");\r\n            $(\'#data-last_name\').val(\"\");\r\n            $(\'#data-prefix_name\').val(\"\");\r\n            $(\'#input-prefix_name\').val(\"\");\r\n            $(\'#data-gender\').val(\"\");\r\n            $(\'#data-birth_date\').val(\"<%= Time.now.strftime(\'%d/%m/%Y\') %>\");\r\n        }\r\n    }\r\n\r\n    function get_patient_info(us, ps, hn){\r\n        console.log(\'US:\' + us + \', PS:\' + ps + \',HN:\' + hn)\r\n        $(\'#his-status\').html(\'connecting...\');\r\n	    \r\n<% if his %>\r\n	\r\n	    var username = \'<%=his%>\'\r\n	    var password = \'-\'\r\n	\r\n<% end %>\r\n\r\n        // var hn=prompt(\"Please enter HN\",\"\");    \r\n        // var hn = hn\r\n        username = us;\r\n        password = ps;\r\n        if (hn==\'\') { \r\n            // alert(\"Not enough information!!\"); \r\n            $(\'#his-status\').html(\'No HN information, Please fill Patient HN\')\r\n        }else{     \r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading...</span>\');    \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            $.ajax({\r\n                url: \"get_patient_info?un=\"+username+\"&ps=\"+password+\"&hn=\"+hn,\r\n                context: document.body,\r\n                crossDomain: true\r\n            }).done(function(data) {\r\n                $(\'#his-status\').html(\'retriving...\');\r\n                // eval(data);\r\n                $(\'#temporary\').html(data);\r\n                $(\'#his-status\').html(\'completed\');\r\n                \r\n                if ($(\'#data-first_name\').val() != \'\') {\r\n                    init_fields(true);\r\n                } else {\r\n                    init_fields(false);\r\n                    $(\'#his-status\').html(\'Patient not found\')\r\n                }\r\n            }).fail(function(jqXHR, textStatus) {\r\n                // alert(\"error\");\r\n                $(\'#his-status\').html(\'Error loading, Please fill Patient information\')\r\n            });\r\n        }\r\n    }\r\n    \r\n    $(\'#get-his\').click(function() {\r\n        get_patient_info(\'<%= his %>\', \'-\', $(\'#data-hn\').val());\r\n    });\r\n	        \r\n	$(\'#his-logout\').click(function() {\r\n        $(\'#his-logout\').html(\'Loading ...\');\r\n        console.log(\'logout...\')\r\n        get_patient_info(\'-\', \'-\', \'-\');\r\n        // window.location = \'../Home/index\';\r\n    });\r\n    \r\n    $(document).ready(function(){\r\n        $(\'.login-block\').hide();\r\n        $(\'#his-login\').click(function() {\r\n            if ($(\'.login-block\').is(\":visible\")) {\r\n                $(\'#his-status\').show();\r\n                $(\'.login-block\').hide();\r\n                // console.log(\'get_patient_info\')\r\n                \r\n                \r\n    us = $(\'#input-username\').val();\r\n                ps = $(\'#input-password\').val();\r\n                hn = $(\'#data-hn\').val();\r\n                // $(\'#data-hn\').val(hn);\r\n                // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n                console.log(us + \'...\' + ps + \'...\' + hn);\r\n                $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n                get_patient_info(us, ps, hn);\r\n                \r\n                setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n                \r\n                // console.log(\'xxxx\');\r\n                // $(\'#his-status\').html(\'Logged as \' + us);\r\n                \r\n                $(\'#his-login\').hide();\r\n                $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n                $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient</a>\");\r\n                \r\n                // $(\'#modal\').modal(\'hide\')\r\n                // $(\'#modal\').attr(\'aria-hidden: false\');\r\n                // $(\'.modal-backdrop\').modal(\'hide\')\r\n                \r\n                // $(\'#commit\').click(function() {\r\n                //     console.log(\'login ...\')\r\n                //     us = $(\'#input-username\').val();\r\n                //     ps = $(\'#input-password\').val();\r\n                //     hn = $(\'#input-hn\').val();\r\n                //     get_patient_info(us, ps, hn);\r\n                //     console.log(\'... pass ...\')\r\n                // });\r\n                \r\n                $(\'#his-logout\').click(function() {\r\n            	    $(\'#his-logout\').html(\'Loading ...\');\r\n            	    console.log(\'logout...\')\r\n                    get_patient_info(\'-\', \'-\', \'-\');\r\n                    // window.location = \'../Home/index\';\r\n            	});\r\n                \r\n            } else {\r\n                $(\'#his-status\').hide();\r\n                $(\'.login-block\').show();\r\n                $(\'#his-login\').text(\'Get Patient\');\r\n                console.log(\'hide\')\r\n            }\r\n        })\r\n        $(\'#login-cancel\').click(function() {\r\n            $(\'#his-status\').show();\r\n            $(\'.login-block\').hide();\r\n            $(\'#his-login\').text(\'HIS Login\');\r\n        });\r\n        $(\'#commit\').click(function() {\r\n            us = $(\'#input-username\').val();\r\n            ps = $(\'#input-password\').val();\r\n            hn = $(\'#data-hn\').val();\r\n            // $(\'#data-hn\').val(hn);\r\n            // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n            // console.log(us + \'...\' + ps + \'...\' + hn);\r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n            get_patient_info(us, ps, hn);\r\n            \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            \r\n            // console.log(\'xxxx\');\r\n            // $(\'#his-status\').html(\'Logged as \' + us);\r\n            \r\n            $(\'#his-login\').hide();\r\n            $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n            $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient from HIS</a>\");\r\n            \r\n            // $(\'#modal\').modal(\'hide\')\r\n            // $(\'#modal\').attr(\'aria-hidden: false\');\r\n            // $(\'.modal-backdrop\').modal(\'hide\')\r\n            \r\n            // $(\'#commit\').click(function() {\r\n            //     console.log(\'login ...\')\r\n            //     us = $(\'#input-username\').val();\r\n            //     ps = $(\'#input-password\').val();\r\n            //     hn = $(\'#input-hn\').val();\r\n            //     get_patient_info(us, ps, hn);\r\n            //     console.log(\'... pass ...\')\r\n            // });\r\n            \r\n            $(\'#his-logout\').click(function() {\r\n        	    $(\'#his-logout\').html(\'Loading ...\');\r\n        	    console.log(\'logout...\')\r\n                get_patient_info(\'-\', \'-\', \'-\');\r\n                // window.location = \'../Home/index\';\r\n        	});\r\n        });\r\n    });\r\n</script>\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    \r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n	\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-hn\').val(\'\');\r\n        $(\'#patient-msg\').text(\'\');\r\n        init_fields(false);\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#data-hn\').val(data.hn);\r\n                $(\'#data-prefix_name\').val(data.prefix_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.toString().indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n                $(\'#patient-msg\').text(\'Patient found in DB\');\r\n                init_fields(true);\r\n            } else {\r\n                $(\'#patient-msg\').text(\'Patient not found in DB. Please fill patient info.\');\r\n                init_fields(false);\r\n            }\r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        // $(\'#data-hn\').keyup(update_patient);\r\n    });\r\n</script>\r\n\r\n<script>\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'index_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        setTimeout(feed_page(100), 0);\r\n        loadPartial();\r\n    });\r\n    \r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2016-06-01 03:20:54','2016-06-01 03:20:54','',''),(2296,'form',949,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    \r\n    \r\n    $(\'.ctrl\').hide();\r\n    \r\n    $(\'#procedure\').remove();\r\n    $(\'#room\').remove();\r\n    \r\n    $(\'#operative_procedure\').remove();\r\n    $(\'#stop\').remove();\r\n    \r\n</script>',NULL,NULL,NULL,'2016-06-01 03:26:27','2016-06-01 03:26:27','form',''),(2299,'show',949,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n<%\r\n\r\n   @document =  get_document this.document_name \r\n   \r\n   model = get_model(this.table_name)\r\n   @patient_module = @module_model.find(params[:id])\r\n   record = model.find(@patient_module.module_id)\r\n   @record = record    \r\n  if request.post?\r\n    \r\n   \r\n    if p = params[\'cancel_\']\r\n        \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            old_app.destroy\r\n            mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>nil\r\n   \r\n    elsif p = params[\'postpone_\']\r\n    \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            old_app.destroy\r\n            mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        \r\n        \r\n        new_app = record.clone\r\n        new_app.update_attributes :date=>p[0][\'postpone_to\'],:status=>\'Appointed\'\r\n        \r\n        mm = @patient_module.clone\r\n        mm.module_id = new_app.id \r\n        mm.save    \r\n        \r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>p[0][\'postpone_to\'], :postpone_id=>new_app.id\r\n       \r\n        \r\n        \r\n    end\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Home/index\" />\r\n<% end %>\r\n<%= this.display.html_safe %>\r\n\r\n<div id=\"cancel\" style=\"display:none\"  class=\"alert alert-warning\">\r\n   <p>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'cancel_\'\r\n        field = @document.find_by_column_name \'cancel_reason\'\r\n        begin\r\n        %>\r\n        \r\n        <%#field%>\r\n        <div>\r\n        \r\n        <h3>Cancel</h3><br/>\r\n        <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Cancelled\' %>\r\n        </div>\r\n        <script>\r\n        <%= yield :script %>\r\n        \r\n      \r\n        </script>\r\n        <% rescue Exception=>e %>\r\n        <%=e.message%>\r\n        <% end%>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n</div>\r\n\r\n<div id=\"postpone\" style=\"display:none;padding:10px\" class=\"alert alert-warning\">\r\n   \r\n      <p>\r\n        <h3>Postpone</h3><br/>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'postpone_\'\r\n        %>\r\n        <div>\r\n        \r\n       <% field = @document.find_by_column_name \'cancel_reason\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n       <% field = @document.find_by_column_name \'postpone_to\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Postpone\' %>\r\n        </div>\r\n       \r\n       \r\n        <script>\r\n        <%= yield :script %>\r\n        </script>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n   \r\n   \r\n</div>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Cancel\'.html_safe, \"javascript:cancel()\",:class=>bt_class %> | \r\n<%= link_to \'Postpone\'.html_safe, \"javascript:postpone()\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    \r\n    function cancel(){\r\n        $(\'#postpone\').hide()\r\n        $(\'#cancel\').slideDown()\r\n        $(\'#cancel_cancel_reason\').show()\r\n        \r\n    }\r\n    \r\n    function postpone(){\r\n        $(\'#cancel\').hide()\r\n        $(\'#postpone\').slideDown()\r\n        $(\'#postpone_postpone_to\').show()\r\n\r\n    }\r\n    \r\n    function cancel_ctrl(){\r\n        $(\'#postpone\').slideUp()\r\n        $(\'#cancel\').slideUp()\r\n    }\r\n    $(\'.ctrl\').hide();\r\n    $(\'#procedure\').remove();\r\n    $(\'#room\').remove();\r\n<%\r\n    if params[:return]\r\n%>\r\n    setTimeout(function(){ window.location=\'../Home/index\'; }, 3000);\r\n<%\r\n    end\r\n%>\r\n</script>',NULL,NULL,NULL,'2016-06-01 05:42:02','2016-06-01 05:42:02','show',''),(2300,'patient_report',950,3,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  <script>\r\n      var console = new function() {\r\n          this.log = function(x) {};\r\n      }\r\n  </script>\r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n			\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n		    <title><%=title%></title>\r\n\r\n				<script>\r\n					$(document).ready(function() {\r\n						//* show all elements & remove preloader\r\n						// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n						 // $(\"html\").removeClass(\"js\");\r\n					});\r\n				</script>\r\n		\r\n				 <style>\r\n    .w-box-content.cnt_a {background: #fff;}\r\n    .k-grid table {font-size: 1em;}\r\n    .k-calendar .k-content {font-size: 1em;padding-top:5px;}\r\n    .k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\n        height: 18px;\r\n    }\r\n    .field-data {width: 220px;}\r\n\r\ninput{\r\n    height:18px;\r\n}\r\nbody { \r\n    /*background-image: url(\'/esm/thks/www/content/hip-knee-pain-bw.jpg\');*/\r\n    /* ref : http://i0.wp.com/blog.beaumont.edu/wp-content/uploads/2014/10/hip-knee-pain.png */\r\n    background-repeat: no-repeat;\r\n    background-attachment: fixed;\r\n    background-position: center top; \r\n    /*background-color: black;*/\r\n    /*background-size: cover;*/\r\n    padding: 20px;\r\n    font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\r\n    /*font-weight: lighter;*/\r\n    /*font-size: 1em;*/\r\n}\r\n</style>\r\n		\r\n		\r\n</head>\r\n<body>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\" style=\"padding:0px;\">\r\n<!--start body content-->\r\n\r\n    <div class=\"row-fluid\">\r\n        \r\n<%\r\nmodule_name = @current_project.name\r\nif params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\nend\r\nif session[module_name]\r\n	params[:date] = session[module_name][:date]\r\nend\r\nunless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\nend\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n        s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n        s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n        date_text = s_date.strftime(\"%d/%m/%Y\")\r\n        session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n         Patient Report \r\n         <span style=\"float:right\"><%=Time.now%></span>\r\n         <div class=\"clear\"></div>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:5px\" >\r\n    \r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\'patient_report\',:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n            \r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            \r\n            \r\n            <div class=\"field-input\">\r\n                 <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                 \r\n                 <!--<%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>-->\r\n            </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        \r\n        </div>\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%# params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n    \r\n    if !search_patient and params[:select].nil?\r\n\r\n    # 	patients = patient_model.all  \r\n	   # maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n    # 	aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    # 	# filter provider\r\n    # 	if s_provider and s_provider != \'\'\r\n    #  		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n    #  		 aps = tmp\r\n    # 	end\r\n    # 	aps = []\r\n        conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n    	aps = ap_model.all(conds)\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n    %>\r\n    <!--ALL -->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name, :last_name=>s_last_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n    # 	patients = patient_model.where(criteria).limit(20).all  \r\n        patients = patient_model.where(criteria).limit(20).all  \r\n	    maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n    	aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT-->\r\n    <%\r\n    elsif params[:date]\r\n    \r\n	    conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n    		conds.merge! :provider=>s_provider \r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n    \r\n    	aps = ap_model.all(conds)\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     		 tmp = aps.reject{|i| i.provider.to_s != s_provider}\r\n     		 aps = tmp\r\n    	end\r\n\r\n    %>\r\n    <!--DATE-->\r\n    <%\r\n    end # end if\r\n    %>\r\n\r\n<%\r\n    map_provider = {}\r\n    for i in provider_model do\r\n        map_provider[i.id.to_s] = i\r\n    end\r\n    result = []\r\n    x = 0\r\n    aps.each do |i|\r\n        x += 1\r\n        tmp = {}\r\n        tmp[:date] = i[:date]\r\n        tmp[:provider] = map_provider[i[:provider].to_s].to_s\r\n        m_app = module_model.where(:module_id=>i.id).first\r\n        \r\n        patient = patient_model.find(m_app[:patient_id])\r\n        tmp[:hn] = patient[:hn]\r\n        tmp[:patient] = patient[:prefix].to_s + \" \" + patient[:first_name].to_s + \"&nbsp;&nbsp;&nbsp;\".html_safe + patient[:last_name].to_s\r\n        \r\n        operation = module_model.where(:parent_id=>m_app.id).all\r\n        operation.each do |j|\r\n            tmx = tmp.clone\r\n            op_name = j[:module_name].split(\'#\')[1].capitalize\r\n            att = model[:attachment].find(j[:report])\r\n            action = link_to(\'View\', \"../\\\\#{op_name}/rprint?id=\\\\#{j.id}\", :target=>\'\', :class=>\'btn btn-mini btn-success\')\r\n            if att\r\n                action += \'&nbsp;\'.html_safe\r\n                action += link_to(\'PDF\', att.path, :target=>\'\', :class=>\'btn btn-mini btn-success\')\r\n            end\r\n            tmx[:operation] = op_name\r\n            tmx[:action] = action\r\n            result.push(tmx)\r\n        end\r\n%>\r\n<!--Date : <%= i[:date] %><br/>-->\r\n<!--Provider : <%= map_provider[i[:provider].to_s] %> (<%= i[:provider] %>)<br/>-->\r\n<!--Operation : <%= operation.size %><br/>-->\r\n<!--Patient : <%# patient.inspect %><br/>-->\r\n<!--Result : <%= result.size %>-->\r\n<!--<hr/>-->\r\n<%  \r\n    end \r\n    labels = {:no=>\'No.\', :date=>\'Date\', :hn=>\'HN\', :patient=>\'Patient Name\', :provider=>\'Provider Name\', :operation=>\'Operation Name\', :action=>\'Action\'}\r\n    m = [:no, :date, :hn, :patient, :provider, :operation, :action]\r\n    result = result.sort_by{|i| i[:hn]}.reverse\r\n    result = result.uniq\r\n%>\r\n<%# aps.to_json.html_safe %>\r\n<div id=\"result-panel\"  style=\"padding:0px\">\r\n<p><p></p></p>\r\n<% c = 1 %>\r\n<table class=\"table table-striped\">\r\n    <thread>\r\n        <tr>\r\n            <%\r\n                for x in m\r\n            %>\r\n            <th><%= labels[x] %></th>\r\n            <%\r\n                end\r\n            %>\r\n        </tr>\r\n    </thread>\r\n    <%\r\n        for rs in result \r\n    %>\r\n    <tr>\r\n    <%\r\n            for x in m\r\n                if !rs[x]\r\n                    rs[x] = c\r\n                end\r\n                col = \"<td>\\\\#{rs[x]}</td>\".html_safe\r\n    %>\r\n        <%= col %>\r\n    <%\r\n            end\r\n    %>\r\n    </tr>\r\n    <%\r\n            c += 1\r\n        end\r\n    %>\r\n</table>\r\n<p><p></p></p>\r\n</div>\r\n\r\n\r\n<%\r\nif false \r\n \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n		 patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         # zamachita comment and change link to patient_record\r\n        #  hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n        # hn = link_to(patient.hn, \"patient_record?id=\\\\#{m[:patient_id]}&aid=\\\\#{m.id}\")\r\n        hn = link_to(patient.hn, \"patient_record?id=\\\\#{m.id}\")\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n        #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n        #  :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n        #  :visit_type=>visit_type\r\n        #  }\r\n        c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n        :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,\r\n        # :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{m[:patient_id]}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n        :visit_type=>visit_type\r\n        }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{m[:patient_id]}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{m[:patient_id]}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    # table_model = %w{date hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    table_model = %w{date hn patient provider }.collect{|i| i.to_sym}\r\n    \r\n    \r\n    # labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',\r\n    # :status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\', :note=>\'Note\',:visit_type=>\'Group\' }\r\n    labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:Provider=>\'Appointed Doctor\', :pending_ctrl=>\'Appointed ctrl\', :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n        \r\n        \r\n        \r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                 <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    out[0] = count.to_s+\".\"\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n\r\n        </div>\r\n<%\r\nend\r\n# end if false\r\n%>\r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"patient_report?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n\r\n<!--<div class=\"alert \">-->\r\n<!--Links : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | -->\r\n<!--<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | -->\r\n<!--<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>-->\r\n<!--</div>-->\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n        \r\n    </div>\r\n<!--body content-->\r\n</div>\r\n</div>\r\n     <script type=\"text/javascript\" charset=\"utf-8\">\r\n	refresh_remote();\r\n	$(\'#search-field\').focus()\r\n</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2016-06-01 06:10:40','2016-06-01 06:10:40','patient_report','*'),(2301,'form',928,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<style>\r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	/*position: fixed;*/\r\n	position: absolute;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat #fff;\r\n}\r\n</style>\r\n<div class=\'se-pre-con\'></div>\r\n<%\r\n    if @current_role==\'capture\' or @current_role==\'developer\'\r\n%>\r\n    <div class=\"alert\">\r\n		<!--<h4 class=\"alert-heading\">Endo Button</h4>-->\r\n		<div style=\'float:left\' id=\'btn-form\'>&nbsp;</div>\r\n		<div style=\'float:right\' id=\'btn-snap\'>&nbsp;</div>\r\n		<br/>\r\n		&nbsp;\r\n	</div>\r\n<%\r\n    end\r\n%>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    function cal_total_operative() {\r\n        s = $(\'#data-operative_time_start_at\').val();\r\n        e = $(\'#data-operative_time_stop_at\').val();\r\n        \r\n        if (s != \"\" && e != \"\") {\r\n            s = new Date(\"<%= Time.now.strftime(\'%Y/%m/%d\') %> \" + s);\r\n            e = new Date(\"<%= Time.now.strftime(\'%Y/%m/%d\') %> \" + e);\r\n            \r\n            t = (e - s) / 60 / 1000\r\n            $(\'#data-total_operative\').val(t);\r\n            // console.log(\"Time diff : \" + (t) + \"..s..\" + s);\r\n        }\r\n    }\r\n    \r\n    $(document).ready(function() {\r\n        $(\'#data-operative_time_start_at\').change(cal_total_operative);\r\n        $(\'#data-operative_time_stop_at\').change(cal_total_operative);\r\n\r\n<%\r\n    if (@current_role==\'capture\' or @current_role==\'developer\')\r\n        if params[:opt] == \'create\' or params[:opt] == \'edit\'\r\n%>\r\n        frm_submit = $(\'#record-submit\').clone();\r\n        frm_cancel = $(\'#record-submit\').next().clone();\r\n        frm_cancel = frm_cancel.addClass(\'btn btn-small\')\r\n        frm_submit = frm_submit.addClass(\'btn btn-success btn-small\')\r\n        \r\n        btn_form = $(\'#btn-form\');\r\n        btn_form.append(frm_submit);\r\n        btn_form.append(\'&nbsp;&nbsp;|&nbsp;&nbsp;\');\r\n        btn_form.append(frm_cancel);\r\n\r\n<%\r\n        end\r\n%>\r\n        snap = $( \"a:contains(\'Snap\')\" ).clone();\r\n        snap = snap.addClass(\'btn btn-small btn-info\');\r\n        btn_snap = $(\'#btn-snap\');\r\n        btn_snap.append(snap);\r\n<%\r\n    end\r\n%>\r\n        // end loading\r\n        $(\".se-pre-con\").fadeOut(\"slow\"); \r\n    });\r\n    \r\n\r\n</script>\r\n',NULL,NULL,NULL,'2016-06-01 06:46:53','2016-06-01 06:46:53','form',''),(2302,'fields',909,3,'<%\r\n    if d = params[:doc]\r\n        doc = get_document(d.downcase)\r\n        # doc = get_document(\'post_op\')\r\n        if doc\r\n            a_doc = doc.fields\r\n            rs = []\r\n            \r\n            a_doc.each do |i|\r\n                name = i[:name]\r\n                type = i[:field_type]\r\n                col  = i[:column_name]\r\n                lov = \'-\'\r\n                if i[:lov]\r\n                    lov = i[:lov].to_s.split(\'\\r\\n\').join(\', \')\r\n                end\r\n                txt = \"\\\\#{name},\\\\#{col},\\\\#{type},\\\\#{lov}\"\r\n                rs << txt\r\n        \r\n%>\r\n<%= txt %><br/>\r\n<%\r\n            end\r\n        else\r\n%>\r\ndocument not found\r\n<%\r\n        end\r\n    else\r\n%>\r\nusing \'doc\' to get document\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2016-06-02 16:13:24','2016-06-02 16:13:24','fields',''),(2303,'fields',477,3,'<%\r\n    params[:doc] = this.document_name\r\n    if d = params[:doc]\r\n        doc = get_document(d.downcase)\r\n        # doc = get_document(\'post_op\')\r\n        if doc\r\n            a_doc = doc.fields\r\n            rs = []\r\n            \r\n            a_doc.each do |i|\r\n                name = i[:name]\r\n                col  = i[:column_name]\r\n                type = i[:field_type]\r\n                lov = \'-\'\r\n                if i[:lov]\r\n                    lov = i[:lov].to_s.split(\'\\r\\n\').join(\', \')\r\n                end\r\n                txt = \"\\\\#{name}, \\\\#{col}, \\\\#{type}, \\\\#{lov}\"\r\n                rs << txt\r\n        \r\n%>\r\n<%= txt %><br/>\r\n<%\r\n            end\r\n        else\r\n%>\r\ndocument not found\r\n<%\r\n        end\r\n    else\r\n%>\r\nusing \'doc\' to get document\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2016-06-02 16:16:28','2016-06-02 16:16:28','fields',''),(2304,'index3',231,2,'<div class=\"row\">\r\n<div class=\"col-md-4 well white-bg\">\r\n    <h2>Diagnosis</h2>\r\n<table class=\"table table-hover\">\r\n                                    <tbody>\r\n                                    <tr>\r\n                                        <td class=\"project-status\">\r\n                                            <span class=\"label label-primary\">Active</span>\r\n                                        </td>\r\n                                        <td class=\"project-title\">\r\n                                            <a href=\"project_detail.html\">Contract with Zender Company</a>\r\n                                            <br>\r\n                                            <small>Created 14.08.2014</small>\r\n                                        </td>\r\n                                        <td class=\"project-completion\">\r\n                                                <small>Completion with: 48%</small>\r\n                                                <div class=\"progress progress-mini\">\r\n                                                    <div style=\"width: 48%;\" class=\"progress-bar\"></div>\r\n                                                </div>\r\n                                        </td>\r\n                                        <td class=\"project-actions\">\r\n                                            <a href=\"#\" class=\"btn btn