r\n\r\n</div>',NULL,NULL,NULL,'2016-06-05 03:24:16','2016-06-05 03:24:16','index3',''),(2305,'export_cir',909,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    \r\n    is_update = false # update\r\n    if params[:act] == \'update\'\r\n        is_update = true\r\n    end\r\n    \r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    \r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = [] # all parent_id\r\n    pat_ids = [] # all patient_id\r\n    app_par = {}\r\n    pat_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n        pat_par[i[:patient_id]] = i.id.to_s\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    # begin\r\n    # a_pat = a_pat.sort_by{|i| i[:patient_order] if i[:patient_order]}\r\n    a_pat = a_pat.sort{|a,b| a[:patient_order] && b[:patient_order] ? a[:patient_order] <=> b[:patient_order] : a[:patient_order] ? -1 : 1 }\r\n    \r\n    # query patient_module <-> aki\r\n    mod_aki = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#aki\")\r\n    i_aki = []\r\n    p_aki = {}\r\n    mod_aki.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_aki << mid\r\n        if !p_aki.has_key? pid\r\n            p_aki[pid] = []\r\n        end\r\n        p_aki[pid] << mid\r\n    end\r\n    m_aki = {}\r\n    a_aki = get_model[:aki].find(i_aki)\r\n    a_aki.each do |i|\r\n        m_aki[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> aki\r\n    mod_out = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#summary_form\")\r\n    i_out = []\r\n    p_out = {}\r\n    mod_out.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_out << mid\r\n        if !p_out.has_key? pid\r\n            p_out[pid] = []\r\n        end\r\n        p_out[pid] << mid\r\n    end\r\n    m_out = {}\r\n    a_out = get_model[:summary_form].find(i_aki)\r\n    a_out.each do |i|\r\n        m_out[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> case_record\r\n    mod_case = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#case_record\")\r\n    i_case = []\r\n    p_case = {}\r\n    mod_case.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_case << mid\r\n        if !p_case.has_key? pid\r\n            p_case[pid] = []\r\n        end\r\n        p_case[pid] << mid\r\n    end\r\n    m_case = {}\r\n    a_case = get_model[:case_record].find(i_case)\r\n    a_case.each do |i|\r\n        m_case[i.id] = i\r\n    end\r\n    \r\n    \r\n    # processing\r\n    res = []\r\n    pf = %w{patient_number gender age birth_date date_of_admission date_of_icu_admission ckd esrd ht dm cad cerebrovascular_disease malignancy diagnosis glasgow_coma_score temperature mean_arterial oxygenation serum_sodium serum_creatinine hematocrit white_blood_count}\r\n\r\n    dd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    cf = %w{case_status bun  creatinine mechanical_ventilation vasopressor vasopressor_type dose_of_vasopressor rs coagulation cns liver renal cvs diuretic lactate sofa if_rrt}\r\n\r\n    of = %w{icu_discharge_status date_of_icu_discharge los_in_icu hospital_discharge_status date_of_hospital_discharge los_in_hospital death_date total_ventilator_day}\r\n    af = %w{cr_diagnosis cr_diagnosis_from_day cr_staging cr_staging_from_day urine_output_diagnosis urine_output_from_day urine_output_staging urine_output_staging_from_day admin_cause_of_aki aki_type aki_from a_on_c}\r\n\r\n    dx_group = {}\r\n\r\n    # for each patient\r\n    a_pat.each do |pat|\r\n        tmp = {}\r\n        msg = []\r\n        if pat.nil?\r\n            next\r\n        end\r\n        \r\n        pp = {}\r\n        pf.each do |i|\r\n            pp[i.to_sym] = pat[i.to_sym]\r\n        end\r\n        \r\n        dx_str = pp[:diagnosis].clone.downcase\r\n        if dx_str.include? \' and \'\r\n            dx_str.gsub!(\' and \', \',\')\r\n        end\r\n        dx_str.split(\',\').collect do |i|\r\n            k = i.strip\r\n            v = pp[:patient_number]\r\n            if !dx_group.has_key? k\r\n                dx_group[k] = []\r\n            end\r\n            dx_group[k] << v\r\n        end\r\n        \r\n        # recheck urine output from case_record\r\n        cid_list = []\r\n        if xx = p_case[pat.id]\r\n            xx.each do |i|\r\n                cid_list << m_case[i]\r\n            end\r\n        else\r\n            msg << \"xx found\"\r\n        end\r\n        \r\n        # mapping day <--> case_record\r\n        mc = {}\r\n        cid_list.each do |i|\r\n            rd = i[:record_day]\r\n            if rd==\'\'\r\n                msg << \'empty rd\'\r\n            end\r\n            if !mc.has_key? rd\r\n                mc[rd] = i\r\n            else\r\n                msg << \"dup rd[\\\\#{rd}]\"\r\n            end\r\n        end\r\n        \r\n        # checking aki is created ?\r\n        is_aki = false\r\n        aid_list = []\r\n        if xx = p_aki[pat.id]\r\n            xx.each do |i|\r\n                aid_list << m_aki[i]\r\n            end\r\n            is_aki = true\r\n        else\r\n            msg << \"NO AKI\"\r\n        end\r\n        \r\n        # checking summary_form is created ?\r\n        is_out = false\r\n        aid_list = []\r\n        if xx = p_out[pat.id]\r\n            xx.each do |i|\r\n                aid_list << m_out[i]\r\n            end\r\n            is_out = true\r\n        else\r\n            msg << \"NO OUTCOME\"\r\n        end\r\n        \r\n        # assign aki\r\n        r_aki = nil\r\n        if is_aki\r\n            r_aki = aid_list[0]\r\n        end\r\n        \r\n        # number of record_day\r\n        nrd = cid_list.count\r\n        \r\n        \r\n        pp[:num_of_record_day] = nrd\r\n        if !mc.empty?\r\n            dd.each do |i|\r\n                if !mc[i].nil?\r\n                    cf.each do |j|\r\n                        if j.to_s == \'move_out_time\'\r\n                            if mc[i][:case_status].to_i != 0\r\n                                pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                            end\r\n                        else\r\n                            pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym]\r\n                        end\r\n                    end\r\n                end\r\n            end # end dd\r\n        end  \r\n        \r\n        pm_id = pat_par[pat.id]\r\n        x_id = app_par[pm_id]\r\n        pp[:detail] = link_to(\'detail\', \"../Home/patient_record?id=\\\\#{x_id}\", :target=>\'_blank\')\r\n        \r\n        res << pp\r\n    end\r\n    \r\n    lbl = pf\r\n    lbl << \"num_of_record_day\"\r\n    fx = cf\r\n    fx.each do |i|\r\n        dd.each do |j|\r\n            lbl << \"\\\\#{i}_\\\\#{j}\"\r\n        end\r\n    end\r\n    lbl = lbl + of\r\n    lbl << \'detail\'\r\n        \r\n    \r\n    # result assign\r\n    display = \'table\'\r\n    if params[:type] == \'csv\'\r\n        display = \'csv\'\r\n    elsif params[:type] == \'xls\'\r\n        display = \'xls\'\r\n    elsif params[:type] == \'json\'\r\n        display = \'json\'\r\n    end\r\n    \r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    # rs[:app_par] = app_par\r\n    # rs[:mod_par] = mod_par\r\n\r\n    if display == \'json\'\r\n        rs[:all_patient] = a_pat.count\r\n        rs[:patient_1] = a_pat[1]\r\n        rs[:all_aki] = a_aki.count\r\n        rs[:all_case_record] = a_case.count\r\n        rs[:result] = res\r\n        rs[:time] = Time.now - tb\r\n%>\r\n\r\n<%= rs.to_json.html_safe %>\r\n\r\n<%\r\n    elsif display == \'table\'\r\n        ff = res[0].keys\r\n        ff = lbl.collect{|i| i.to_sym}\r\n%>\r\n\r\n<%= stylesheet_link_tag    \"application\"  %>\r\n<h3>Total Patient = <%= a_pat.count %></h3>\r\nquery time = <%= Time.now - tb %>\r\n\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n<% ff.each do |i| %>\r\n        <th><%= i %></th>\r\n<% end %>        \r\n    </tr>\r\n<% \r\n        res.each do |i| \r\n%>\r\n    <tr>\r\n<% \r\n            ff.each do |j| \r\n                val = i[j]\r\n%>\r\n       <td><%= val %></td>\r\n<% end %>\r\n    </tr>\r\n<% end %>\r\n</table>\r\n<br/>\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n        <td>CODE</td>\r\n        <td>Dx</td>\r\n        <td>Total</td>\r\n        <td>Patients</td>\r\n    </tr>\r\n<%\r\n    ks = dx_group.keys.sort\r\n    ks.each do |k|\r\n        v = dx_group[k]\r\n%>\r\n    <tr>\r\n        <td>&nbsp;</td>\r\n        <td><%= k %></td>\r\n        <td><%= v.count %></td>\r\n        <td><%= v.join(\', \') %></td>\r\n    </tr>\r\n<%\r\n    end\r\n%>\r\n</table>\r\n<br/>\r\nProcessing time = <%= Time.now - tb %><br/>\r\n\r\n<%\r\n    elsif display == \'csv\'\r\n        require \'csv\'\r\n    \r\n        response.headers[\"Content-Type\"] = \"text/csv\"\r\n        response.headers[\"Content-disposition\"] = \"attachment; filename=Export-\\\\#{params[:solution_name]}-\\\\#{Time.now.to_i}.csv\"\r\n        \r\n        ff = res[0].keys\r\n        \r\n        xxx = CSV.generate do |csv|\r\n            \r\n            csv << ff\r\n            tmp = []\r\n            res.each do |i|\r\n                ff.each do |j|\r\n                    tmp << i[j]\r\n                end\r\n                csv << tmp\r\n            end\r\n      \r\n        end\r\n%>\r\n<%= xxx.html_safe %>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2016-06-06 07:02:23','2016-06-06 07:02:23','export_cir',''),(2306,'index',944,2,'<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        if query.include? \':\'\r\n            x = query.split(\':\')\r\n            keys << {x[0].to_sym=>Regexp.new(x[1])}\r\n        else\r\n            @fields.each_with_index do |f,index| \r\n                keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n            end\r\n        end\r\n        \r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<%# params.to_json.html_safe %>\r\n<br/>\r\n<%= form_for :search, :url=>params[:opt] do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2016-06-07 05:13:25','2016-06-07 05:13:25','index',''),(2307,'list',944,3,'<%\r\n   model = get_model(this.table_name)\r\n   records = []\r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   \r\n    if params[:search]\r\n        records = model.all(params[:search][:criteria])\r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n       records = model.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n    end\r\n\r\n    if params[:search]   \r\n%>\r\n\r\n<h3>Total : <%= records.count %> record(s) found.</h3>\r\n\r\n<%\r\n    end\r\n%>\r\n<%= tabular :model=>labels, :data=>records do |i,out|\r\n\r\nfields.each_with_index do |f,index|\r\n\r\nout[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n\r\nend\r\nout<<link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nout<<link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\')\r\nout<<link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:confirm=>\'Are you sure?\')\r\nout\r\nend\r\n%>\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2016-06-07 05:23:47','2016-06-07 05:23:47','list',''),(2308,'document_name',952,1,'\'appointment\'',NULL,NULL,NULL,'2016-06-09 12:09:57','2016-06-09 12:09:57',NULL,NULL),(2309,'create_partial',908,3,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    \r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n\r\n<%\r\n    url = \"../\\\\#{this.document_name.camelize}/show_partial?id=\\\\#{m.id}\"\r\n%>\r\n   $.ajax({\r\n       url: \'<%=url.html_safe%>\',\r\n       success: function(data){\r\n        // console.log(data)\r\n\r\n         $(\'#panel-<%=this.document_name%>\').html(data);  \r\n         \r\n        }\r\n    });\r\n\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create_partial\'),:data=>{:remote=>true} do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n<%= hidden_field_tag :parent_id, params[:parent_id] if params[:parent_id] %>\r\n<%= hidden_field_tag :record_name, params[:record_name] if params[:record_name] %>\r\n<%= hidden_field_tag :patient_id, params[:patient_id] if params[:patient_id] %>\r\n\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"display:none;background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\n<%= hidden_field_tag \'patient_id\',params[:patient_id] ,:id=>\'record-patient_id\'%> \r\n\r\n\r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n// 		$.ajax({\r\n// 		  url: url,\r\n// 		 success: function(data){\r\n// 		  $(\'#search-result\').html(data);  \r\n// 		  }\r\n// 		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n// 		$.ajax({\r\n// 		  url: url,\r\n// 		 success: function(data){\r\n//           $(\'#patient\').html(data);  \r\n//           $(\'#SelectPatient\').hide();\r\n//           $(\".modal-backdrop\").hide(\'fade\');\r\n// 		  }\r\n// 		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n    //  $(\'#SelectPatient\').modal({\r\n    //             show: true, \r\n    //             backdrop: \'static\',\r\n    //             keyboard: true\r\n    // })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:data=>{:disable_with=>\'Creating..\'} %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n\r\n',NULL,NULL,NULL,'2016-06-10 03:38:00','2016-06-10 03:38:00','create_partial',''),(2310,'create_partial',952,3,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-06-10 03:39:38','2016-06-10 03:39:38','create_partial',''),(2311,'index_bk2',953,3,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n	<head>\r\n		<%= include_header %>\r\n		<style>\r\n			body { \r\n			background: url(/esm/clinic_master/clinic/bg.jpg) no-repeat;\r\n			background-size: 100% auto; \r\n			background-attachment: fixed; \r\n			}\r\n			.btnshadow {\r\n			-moz-box-shadow: 0 0 5px 5px #888;\r\n			-webkit-box-shadow: 0 0 5px 5px#888;\r\n			box-shadow: 0 0 5px 5px #888;\r\n			}\r\n			.myButton {\r\n			width:150px; height:60px;padding:20px;margin:10px; \r\n			-moz-box-shadow: 0px 10px 14px -7px #276873;\r\n			-webkit-box-shadow: 0px 10px 14px -7px #276873;\r\n			box-shadow: 0px 10px 14px -7px #276873;\r\n			background:-webkit-gradient(linear, left top, left bottom, color-stop(0.05, #599bb3), color-stop(1, #408c99));\r\n			background:-moz-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n			background:-webkit-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n			background:-o-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n			background:-ms-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n			background:linear-gradient(to bottom, #599bb3 5%, #408c99 100%);\r\n			filter:progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#599bb3\', endColorstr=\'#408c99\',GradientType=0);\r\n			background-color:#599bb3;\r\n			-moz-border-radius:8px;\r\n			-webkit-border-radius:8px;\r\n			border-radius:8px;\r\n			display:inline-block;\r\n			cursor:pointer;\r\n			color:#ffffff;\r\n			font-family:Arial;\r\n			font-size:20px;\r\n			font-weight:bold;\r\n			padding:13px 32px;\r\n			text-decoration:none;\r\n			text-shadow:0px 1px 0px #3d768a;\r\n			}\r\n			.myButton:hover {\r\n			background:-webkit-gradient(linear, left top, left bottom, color-stop(0.05, #408c99), color-stop(1, #599bb3));\r\n			background:-moz-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n			background:-webkit-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n			background:-o-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n			background:-ms-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n			background:linear-gradient(to bottom, #408c99 5%, #599bb3 100%);\r\n			filter:progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#408c99\', endColorstr=\'#599bb3\',GradientType=0);\r\n			background-color:#408c99;\r\n			}\r\n			.myButton:active {\r\n			position:relative;\r\n			top:1px;\r\n			}\r\n			.bb { padding:20px; font-size:1.5em; margin:10px; width:150px; height:60px;\r\n			-moz-border-radius: 5px;\r\n			border-radius: 5px;\r\n			-moz-box-shadow: 2px 2px #ccc;\r\n			-webkit-box-shadow: 2px 2px #ccc;\r\n			box-shadow: 2px 2px #ccc;}\r\n			.modal {width:1000px;}    \r\n			input, textarea, select, .uneditable-input {\r\n			width: 100%; }\r\n			.modal {\r\n			margin: -300px 0 0 -500px;}\r\n			.input-barcode {\r\n                border: none;\r\n                color: transparent;\r\n                display: inline-block;\r\n                font-size: 2em;\r\n                text-shadow: 0 0 0 black;\r\n                width: 2em;\r\n                \r\n                &:focus {\r\n                    outline: none;\r\n                }\r\n            }\r\n		</style>\r\n	</head>\r\n	<body>\r\n		<br/>\r\n<%\r\n			models = get_model    \r\n%>\r\n<%= models[:appointment].count %>\r\n		<div class=\"row-fluid\">\r\n			<div id=\"home-panel\" class=\"span12\" style=\"magin-left:auto;magin-right:auto;\">\r\n				<div class=\"span12\" style=\"border:0px solid\" >\r\n					<center><a href=\"../Home/index\" ><img src=\"/esm/clinic_master/clinic/logo.jpg\"></a></center>\r\n					<br />\r\n				</div>\r\n				<div class=\"row-fluid\">\r\n					<div class=\"span6 center\">\r\n						<img src=\"/esm/clinic_master/clinic/flow.jpg\" width=\"500px\" class=\"well\" style=\"float:right; marign-right:20px\">\r\n					</div>\r\n					<div class=\"span6\">\r\n<%= text_field_tag :barcode,\"\", :id=>\"barcode\",:class=>\'input-barcode\', :placeholder=>\'hn, appoint-id, online-id, pid\',:style=>\'height:40px; font-size:1.5em; width:400px; \' %> <a href=\"javascript:checkin()\" id=\"appoint-btn\" class=\"btn\" style=\"margin-bottom: 10px;\"><i class=\"splashy-star_full\"></i> check-in <br/>appointment  </a><br />\r\n<!-- แก้ให้หน่วยจ้าา  -->\r\n<script>\r\n    var b_txt = \"\";\r\n	function changeValue(n) {\r\n	    console.log(\'n = \' + n);\r\n	    b_txt = $(\'#barcode\').val();\r\n		\r\n		if (b_txt.length >= 1 && n == \'del\') {\r\n		    b_txt = b_txt.substring(0, b_txt.length - 1);\r\n		} else {\r\n		    b_txt += n;\r\n		}\r\n		console.log(b_txt + \'---\' + n);\r\n		$(\'#barcode\').val(b_txt);\r\n	}\r\n</script>\r\n						<button class=\"myButton\" id=\"1\" onclick=\"changeValue(\'1\')\">1</button><button class=\"myButton\" id=\"2\" onclick=\"changeValue(\'2\')\">2</button><button class=\"myButton\" id=\"3\" onclick=\"changeValue(\'3\')\">3</button><br />\r\n						<button class=\"myButton\" id=\"4\" onclick=\"changeValue(\'4\')\">4</button><button class=\"myButton\" id=\"5\" onclick=\"changeValue(\'5\')\">5</button><button class=\"myButton\" id=\"6\" onclick=\"changeValue(\'6\')\">6</button><br />\r\n						<button class=\"myButton\" id=\"7\" onclick=\"changeValue(\'7\')\">7</button><button class=\"myButton\" id=\"8\" onclick=\"changeValue(\'8\')\">8</button><button class=\"myButton\" id=\"9\" onclick=\"changeValue(\'9\')\">9</button><br />\r\n						<button class=\"myButton\" id=\"/\" onclick=\"changeValue(\'/\')\">/</button><button class=\"myButton\" id=\"0\" onclick=\"changeValue(\'0\')\">0</button><button class=\"myButton\" id=\"del\" onclick=\"changeValue(\'del\')\">DEL</button>\r\n						</center>\r\n					</div>\r\n				</div>\r\n				<div class=\"row\">\r\n					<div class=\"span12 offset3\" >\r\n						<center>\r\n							<h2>\r\n								<a href=\"#\" id=\"online-btn\" class=\"btn \"><i class=\"splashy-star_full\"></i> check-in <br/> online regist  \r\n							</h2>\r\n							</a>\r\n						</center>\r\n					</div>\r\n				</div>\r\n			</div>\r\n			<a data-toggle=\"modal\" data-backdrop=\"static\" id=\"clinic\" href=\"#myModal1\"></a>\r\n			<div class=\"modal hide in\" id=\"myModal1\" aria-hidden=\"false\" style=\"display: none;\">\r\n				<div class=\"modal-header\">\r\n					<button class=\"close\" data-dismiss=\"modal\" onClick=\"\">x</button>\r\n					<h3>Patient Information</h3>\r\n				</div>\r\n				<div class=\"modal-body\">\r\n<%= form_for :patient,:url=>\"create_patient\" do |f|  %>\r\n					<table>\r\n						<tr>\r\n							<th>เลขบัตรประชาชน</th>\r\n							<th>รหัสโรงพยาบาล</th>\r\n							<th>ชื่อ-สกุล</th>\r\n							<th>คลิกนิกที่นัดไว้</th>\r\n							<th>เวลารับบริการ</th>\r\n						</tr>\r\n						<tr>\r\n							<td> <%= f.text_field :public_id ,:id=>\'public_id\',:class=>\"patient\"%></td>\r\n							<td><%= text_field_tag :patient_id, \'\',:id=>\'patient_id\' %> </td>\r\n							<td><%= f.text_field :prefix_name,:class=>\"patient\"%><%= f.text_field :first_name, class:\"patient\"%> <%= f.text_field :last_name, class:\"patient\"%></td>\r\n							<td><%= text_field_tag :procedure, \'\',:id=>\'procedure_code\' %></td>\r\n							<td><%= f.text_field :register_date,:value=>Time.now%></td>\r\n						</tr>\r\n					</table>\r\n					<table width=\"100%\">\r\n						<tr>\r\n							<td>\r\n								<a href=\"javascript:clinic(0)\" class=\"btn clinic-btn \" style=\"width:80%\">\r\n									<h4><i class=\"splashy-star_full\"></i> คลินิกพิษสุนักบ้า <br /> Rabies\r\n									</h4>\r\n								</a>\r\n							</td>\r\n							<td>\r\n								<a href=\"javascript:clinic(2)\" class=\"btn  clinic-btn \" style=\"width:80%\">\r\n									<h4><i class=\"splashy-star_full\"></i> ขอเอกสารเพื่อการเดินทาง<br /> Travel certificate\r\n									</h4>\r\n								</a>\r\n							</td>\r\n							<td>\r\n								<a href=\"javascript:clinic(1)\" class=\"btn clinic-btn \" style=\"width:80%\">\r\n									<h4><i class=\"splashy-star_full\"></i> คลินิกเซลุ่มพิษงู <br /> Toxin\r\n									</h4>\r\n								</a>\r\n							</td>\r\n						</tr>\r\n					</table>\r\n					<br />\r\n					<h2> <%=f.submit \'รับบัตรคิว\' ,:class=>\'btn btn-success\'%></h2>\r\n					<!-- <img src=\"/gebo/img/gCons/print.png\" /><br />พิมพ์บัตรคิว -->\r\n<% \r\n	end # end form\r\n%>\r\n				</div>\r\n				<div class=\"modal-footer\">\r\n					<a href=\"\" onClick=\"\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n				</div>\r\n			</div>\r\n		</div>\r\n		<div id=\"id-panel\" class=\"span12 hide\" >\r\n		</div>\r\n		<div id=\"panel\" class=\"span12\">... </div>\r\n		<div class=\"span12\">\r\n			<script>\r\n				var disable_barcode=false;\r\n				function resetAll(){\r\n				    reset();\r\n				}\r\n				\r\n				function checkin(){\r\n				    $(\'#clinic\').click();\r\n				    $(\'#barcode\').focus();\r\n				}\r\n				\r\n				\r\n				function reset(){\r\n				\r\n					$(\'#patient_id\').val(\"\");\r\n					$(\'#patient_prefix_name\').val(\"\");\r\n					$(\'#patient_first_name\').val(\"\");\r\n					$(\'#patient_last_name\').val(\"\");\r\n					$(\'#public_id\').val(\"\")\r\n					$(\'#hn\').val(\"\");\r\n					$(\'.patient\').prop(\'disabled\', false);\r\n				\r\n					$(\'.clinic-btn\').removeClass(\"btn-success\");\r\n					$(\'#appoint-btn\').removeClass(\"disabled\");\r\n					$(\'#online-btn\').removeClass(\"disabled\");\r\n				\r\n				\r\n					$(\'#barcode\').focus();\r\n				\r\n				}\r\n				\r\n				  \r\n				function clinic(id){\r\n				    disable_barcode=true;\r\n				    proc_code = \'\'\r\n				    if(id==0) proc_code=\'rabies\'\r\n				    if(id==1) proc_code=\'toxins\'\r\n				    if(id==2) proc_code=\'travel\'\r\n				    \r\n				    // $(\'#patient_id\').val(\"\")\r\n				    // $(\'#patient_prefix_name\').val(\"\");\r\n				    // $(\'#patient_first_name\').val(\"\");\r\n				    // $(\'#patient_last_name\').val(\"\");\r\n				    // $(\'#hn\').prop(\'disabled\', false);\r\n				    // $(\'#hn\').val(\"\");\r\n				    // $(\'.patient\').prop(\'disabled\', false);\r\n				    \r\n				    \r\n				    $(\'#procedure_code\').val(proc_code);\r\n				    $(\'#clinic\').click();\r\n				    $(\'#barcode\').focus();\r\n				\r\n				\r\n				    // $(\'#hn\').focus();\r\n				}    \r\n				\r\n				function search_barcode(barcode){\r\n				     console.log(barcode)\r\n				        $.ajax({\r\n				            url: \"barcode?read=\"+barcode,\r\n				            context: document.body\r\n				            }).done(function(html) {\r\n				            $(\"#panel\").show();\r\n				            $(\"#id-panel\").show();\r\n				            $(\"#panel\").html(html);\r\n				        });\r\n				}\r\n				\r\n				$(document).ready(function() {\r\n				  \r\n					$(\'#hn\').keydown(function(event) {\r\n				    	if (event.keyCode == 13) {\r\n				        \r\n				        	barcode = $(\'#hn\').val()\r\n					        search_barcode(barcode)\r\n					        return false;\r\n					    }\r\n				    \r\n				    \r\n					});\r\n					$(\'#barcode\').keydown(function(event) {\r\n				    	if (event.keyCode == 13) {\r\n				        	barcode = $(\'#barcode\').val()\r\n					        $(\'#barcode\').val(\'\')\r\n					       	search_barcode(barcode)\r\n				        \r\n					    	return false;\r\n						}\r\n					    \r\n					});\r\n				\r\n				\r\n				});\r\n				\r\n				function focus_barcode(){\r\n					if(disable_barcode==false)\r\n						$(\'#barcode\').focus();\r\n				}\r\n\r\n				focus_barcode();\r\n				setInterval(focus_barcode,1000);\r\n				    \r\n			</script>\r\n<% if false %>\r\n			<center >\r\n				<img src=\"https://emr-life.com/esm/clinic_master/clinic/logo.jpg\">\r\n				<hr />\r\n				<h2>กรุณาเสียบบัตรประชาชน เพื่อรับการบริการ กรุณาเลือกคลินิกที่ต้องการ</h2>\r\n				<br /><br />\r\n				<table width=\"100%\" >\r\n					<tr>\r\n						<td width=\"55%\"><img src=\"/esm/clinic_master/clinic/flow.jpg\" width=\"90%\" class=\"well\"></td>\r\n						<td width=\"45%\">\r\n							<div class=\"well\">\r\n								<table width=\"100%\">\r\n									<tr>\r\n										<td width=\"19%\" rowspan=\"2\"><img src=\"/gebo/img/gCons/agent.png\" alt=\"\"  width=\"60px\"/></td>\r\n										<td width=\"16%\" align=\"left\">ID</td>\r\n										<td width=\"65%\"> : 11522544441\r\n										</td>\r\n									</tr>\r\n									<tr>\r\n										<td align=\"left\">ชื่อ-สกุล </td>\r\n										<td>: นาย XXX XXX </td>\r\n									</tr>\r\n								</table>\r\n							</div>\r\n							<a href=\"#\" class=\"btn btnshadow\">\r\n								<h2><i class=\"splashy-star_full\"></i> รับบริการเกี่ยวกับโรคพิษสุนักบ้า</h2>\r\n							</a>\r\n							<br /><br />\r\n							<a href=\"#\" class=\"btn btnshadow\">\r\n								<h2><i class=\"splashy-star_full\"></i> รับบริการเกี่ยวกับเซลุ่มพิษงู</h2>\r\n							</a>\r\n							<br /><br />\r\n							<a href=\"#\" class=\"btn btnshadow\">\r\n								<h2><i class=\"splashy-star_full\"></i> Travel Cerificatie</h2>\r\n							</a>\r\n							<br /><br />\r\n							<a href=\"#\" class=\"btn btn-info btnshadow\">\r\n								<h2><i class=\"splashy-star_full\"></i> สมัครสมาชิกใหม่</h2>\r\n							</a>\r\n						</td>\r\n					</tr>\r\n				</table>\r\n			</center>\r\n<% end %>\r\n		</div>\r\n	</body>\r\n</html>',NULL,NULL,NULL,'2016-06-10 07:01:04','2016-06-10 07:01:04','index_bk2',''),(2312,'document_name',954,1,'\'prescription\'',NULL,NULL,NULL,'2016-06-10 08:01:58','2016-06-10 08:01:58',NULL,NULL),(2313,'document_name',955,1,'\'prescription_item\'',NULL,NULL,NULL,'2016-06-10 08:05:57','2016-06-10 08:05:57',NULL,NULL),(2315,'test',231,2,'<script>\r\n    $(\'body\').addClass(\'top-navigation  pace-done\');\r\n</script>\r\n\r\n    <div id=\"wrapper\">\r\n\r\n\r\n        <div id=\"\" class=\"white-bg\">\r\n       \r\n        <div class=\"wrapper wrapper-content\">\r\n      <div class=\"middle-box text-center animated fadeInRightBig\" style=\"margin-top: 0px;padding-top: 0px\">\r\n                    <span class=\"logo-name\" style=\"color:#1AB394\"><img src=\"http://temporarytrick.com/assets/picture/portfolio/nci/nci.png\" width=\"100px\"></span>\r\n                    <div class=\"error-desc\">\r\n                    <table width=\"100%\" border=\"0\">\r\n  <tr>\r\n    <td><a href=\"_patient.html\"><button class=\"btn btn-primary dim btn-large-dim\" type=\"button\"><i class=\"fa fa-folder-open-o\"></i></button></a></td>\r\n    <td><a href=\"_patient.html\"><button class=\"btn btn-primary dim btn-large-dim\" type=\"button\"><i class=\"fa fa-stethoscope\"></i></button> </a></td>\r\n    <td><a href=\"_patient.html\"><button class=\"btn btn-primary dim btn-large-dim\" type=\"button\"><i class=\"fa fa-money\"></i></button></a></td>\r\n  </tr><tr>\r\n  <td>Patient</td>\r\n    <td>Doctor</td>\r\n    <td>Accounting</td>\r\n    </tr>\r\n  <tr>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td><a href=\"_patient.html\"><button class=\"btn btn-primary dim btn-large-dim\" type=\"button\"><i class=\"fa fa-medkit\"></i></button></a></td>\r\n    <td><a href=\"_patient.html\"><button class=\"btn btn-primary dim btn-large-dim\" type=\"button\"><i class=\"fa fa-plus-circle\"></i></button></a></td>\r\n    <td><a href=\"_patient.html\"><button class=\"btn btn-primary dim btn-large-dim\" type=\"button\"><i class=\"fa fa-calendar-o\"></i></button></a></td>\r\n  </tr>\r\n  <tr>\r\n    <td>Consult</td>\r\n    <td>Medication</td>\r\n    <td>Knowleage base</td>\r\n  </tr>\r\n</table>\r\n<br>\r\n                    <span><br>\r\n                    </span><br/>\r\n                    <a href=\"index.html\" class=\"btn btn-primary m-t\">Log out</a>\r\n</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        </div>\r\n\r\n    <!-- Mainly scripts -->\r\n    <script src=\"js/jquery-2.1.1.js\"></script>\r\n    <script src=\"js/bootstrap.min.js\"></script>\r\n    <script src=\"js/plugins/metisMenu/jquery.metisMenu.js\"></script>\r\n    <script src=\"js/plugins/slimscroll/jquery.slimscroll.min.js\"></script>\r\n\r\n    <!-- Custom and plugin javascript -->\r\n    <script src=\"js/inspinia.js\"></script>\r\n    <script src=\"js/plugins/pace/pace.min.js\"></script>\r\n\r\n',NULL,NULL,NULL,'2016-06-13 10:15:28','2016-06-13 10:15:28','test',''),(2316,'show_partial',908,3,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"../\\\\#{this.table_name.camelize}/print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n\r\n\r\n<%= this.display.html_safe %>\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"javascript:goEdit\\\\#{this.document_name}()\",:id=>\"\\\\#{this.document_name}-edit\",:class=>bt_class %> | \r\n<%\r\n @current_station = nil\r\n \r\n models = get_model\r\n \r\n if session[:current_station]\r\n    @current_station = session[:current_station] \r\n else\r\n    @station = models[:station].first\r\n    if @station\r\n        session[:current_station] = @station.id\r\n        @current_station = session[:current_station]\r\n    end\r\n    \r\n end\r\n \r\n if @current_station\r\n    station = models[:station].find @current_station\r\n    workflow = models[:workflow].where(:name=>station.workflow).first\r\n  \r\n if workflow.default_documents.index(this.table_name)  \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    cm = module_model.find(params[:id])\r\n    am = module_model.find(cm.parent_id)\r\n %>\r\n <%= link_to workflow.out_bound_status.humanize, \"../Home/update_status?id=\\\\#{am.module_id}&status=\\\\#{workflow.out_bound_status}\",:class=>\'btn btn-success\'%>\r\n <% end %> <% end %>\r\n  <%#workflow.inspect  %>\r\n\r\n\r\n<%# link_to \'Back\', return_url %>\r\n\r\n\r\n<script>\r\n\r\n   function goEdit<%=this.document_name%>(){\r\n       \r\n   \r\n<%\r\n    url = \"../\\\\#{this.document_name.camelize}/edit_partial?id=\\\\#{params[:id]}\"\r\n%>\r\n    \r\n   $.ajax({\r\n       url: \'<%=url.html_safe%>\',\r\n       success: function(data){\r\n        console.log(data)\r\n         $(\'#panel-<%=this.document_name%>\').html(data);  \r\n        refresh_remote();\r\n           \r\n       }\r\n    });\r\n    \r\n    \r\n   }\r\n</script>\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-06-16 02:18:08','2016-06-16 02:18:08','show_partial',''),(2317,'edit_partial',908,3,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model()[this.table_name.to_sym]\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this document!!\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n     \r\n    t = Time.now - record.updated_at \r\n \r\n \r\n    if  false and  @current_role!=\'superuser\' and @current_role!=\'developer\' and @current_role!=\'admin\' # and t.to_i > 3600 * 24 \r\n     locker.destroy if locker\r\n  %>\r\n   <script>alert(\"Not allowed to edit this document!!\");window.location = \"<%=return_url%>\";</script>\r\n  <%\r\n  end\r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n// <!--\r\n// window.location = \"show_partial?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n<%\r\n    url = \"../\\\\#{this.document_name.camelize}/show_partial?id=\\\\#{params[:id]}\"\r\n%>\r\n    \r\n   $.ajax({\r\n       url: \'<%=url.html_safe%>\',\r\n       success: function(data){\r\n        console.log(data)\r\n         $(\'#panel-<%=this.document_name%>\').html(data);  \r\n        }\r\n    });\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit_partial\',:id=>params[:id]),:data=>{:remote=>true} do |f| %>\r\n\r\n <div style=\"display:none;background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \"Update\".html_safe, :class=>\'btn btn-small\',:id=>\'record-submit-\'+this.document_name,:disable_with=>\'Updating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:data=>{:confirm=>\'Are you sure?\'} %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit-<%=this.document_name%>\").click(function() {\r\n  \r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   ',NULL,NULL,NULL,'2016-06-16 02:19:36','2016-06-16 02:19:36','edit_partial',''),(2318,'test',885,2,'\r\n<div id=\"panel-rabies\"></div>\r\n<%\r\n    url = \"../Rabies/show_partial?id=57620c23790f9b2cb9000019\"\r\n%>\r\n<script>\r\n         $.ajax({\r\n                                                	  url: \'<%=url.html_safe%>\',\r\n                                            		 success: function(data){\r\n                                            		     console.log(data)\r\n                                            		  //   alert(data)\r\n                                                      $(\'#panel-rabies\').html(data);  \r\n                                            		  }\r\n                                            		});\r\n</script>\r\n\r\n\r\n\r\n<div id=\"panel-rabies-2\"></div>\r\n<%\