nction(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n<%\r\n    if return_url.include? \'?\'\r\n        return_url += \"&reset_lock=\\\\#{locker.id}\"\r\n    else\r\n        return_url += \"?reset_lock=\\\\#{locker.id}\"\r\n    end\r\n%>                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-info\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\', :class=>\'btn\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2016-06-26 08:23:49','2016-06-26 08:23:49','create',''),(2327,'edit',873,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model()[this.table_name.to_sym]\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this document!!\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n     \r\n    t = Time.now - record.updated_at \r\n \r\n \r\n    if  false and  @current_role!=\'superuser\' and @current_role!=\'developer\' and @current_role!=\'admin\' # and t.to_i > 3600 * 24 \r\n     locker.destroy if locker\r\n  %>\r\n   <script>alert(\"Not allowed to edit this document!!\");window.location = \"<%=return_url%>\";</script>\r\n  <%\r\n  end\r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    url = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{@current_service.name}/pdf?id=\\\\#{@patient_module.id}\"\r\n    id = @patient_module.id.to_s\r\n    \r\n    pdf_file = \"tmp/cache/\\\\#{id}.pdf\"\r\n    kit = PDFKit.new(url,:margin_top => \'0.2in\',:margin_right => \'0.2in\',:margin_bottom => \'0.2in\',:javascript_delay => 1000)\r\n    file = kit.to_file(pdf_file)\r\n    \r\n    field = @module_doc .find_by_column_name \'report\'\r\n    att = @module_doc .attach_field_file field.id, file.path.split(\'/\')[-1] , \'\', File.open(file.path)\r\n    @patient_module.update_attributes :report=>att.id\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%\r\n    if return_url.include? \'?\'\r\n        return_url += \"&reset_lock=\\\\#{locker.id}\"\r\n    else\r\n        return_url += \"?reset_lock=\\\\#{locker.id}\"\r\n    end\r\n%>\r\n<%= f.submit \"Update\".html_safe, :class=>\'btn btn-info\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url,:data=>{:confirm=>\'Are you sure?\'}, :class=>\'btn\' %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   ',NULL,NULL,NULL,'2016-06-26 08:24:24','2016-06-26 08:24:24','edit',''),(2328,'index',958,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2016-07-03 03:46:35','2016-07-03 03:46:35',NULL,NULL),(2329,'layout',958,4,'<%=default_layout%>',NULL,NULL,NULL,'2016-07-03 03:46:35','2016-07-03 03:46:35',NULL,NULL),(2330,'index',959,2,'<style>\r\n    .img{\r\n        margin:5px;\r\n    