mplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Save\".html_safe,:class=>\'btn btn-success\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\', :class=>\'btn\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\n    if (!validator.validate()||$(\'#0\').val()==\"\") {\r\n        alert(\'Please fill all information\');\r\n        if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\n            return false;\r\n    }else{\r\n        \r\n        $(this).attr(\'disabled\', true);\r\n        $(this).val(\'Please wait ...\');\r\n        var f = $(this).closest(\'form\');\r\n        f.submit();\r\n        // setTimeout(function() {\r\n            // f.submit();\r\n        // }, 3000);\r\n        \r\n        return true;\r\n        if(confirm(\'Are you sure?\')==true){\r\n            return true;\r\n        }\r\n            return false;\r\n        }\r\n    }\r\n);\r\n</script>   \r\n',NULL,NULL,NULL,'2016-07-04 08:57:32','2016-07-04 08:57:32','create',''),(2339,'edit',876,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n\r\n<style>\r\n    .se-pre-con {\r\n    	/*position: fixed;*/\r\n    	position: absolute;\r\n    	left: 0px;\r\n    	top: 0px;\r\n    	width: 100%;\r\n    	height: 100%;\r\n    	z-index: 9999;\r\n    	background: url(/gebo/img/ajax_loader.gif) center no-repeat #144884;\r\n    }\r\n</style>\r\n\r\n<div class=\'se-pre-con\'></div>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model()[this.table_name.to_sym]\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this document!!\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n     \r\n    t = Time.now - record.updated_at \r\n \r\n \r\n    if  false and  @current_role!=\'superuser\' and @current_role!=\'developer\' and @current_role!=\'admin\' # and t.to_i > 3600 * 24 \r\n     locker.destroy if locker\r\n  %>\r\n   <script>alert(\"Not allowed to edit this document!!\");window.location = \"<%=return_url%>\";</script>\r\n  <%\r\n  end\r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n\r\n    // var href = \'print?id=<%=@patient_module.id%>\';\r\n    // var link = $(\'<a href=\"\' + href + \'\" />\');\r\n    // link.attr(\'target\', \'_blank\');\r\n    // window.open(link.attr(\'href\'));\r\n\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \"Save\".html_safe, :class=>\'btn btn-success\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:data=>{:confirm=>\'Are you sure?\'}, :class=>\'btn\' %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   ',NULL,NULL,NULL,'2016-07-04 09:00:37','2016-07-04 09:00:37','edit',''),(2340,'print',876,3,'<%= this.print_partial.html_safe %>\r\n<% if @current_role!=\'developer\' %>\r\n<script>\r\n    var millisecondsToWait = 2000;\r\n    setTimeout(function() {\r\n        window.print();\r\n    }, millisecondsToWait);\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2016-07-04 15:21:01','2016-07-04 15:21:01','print',''),(2341,'print_partial',876,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    \r\n    gender = \'NA\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'Male\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'Female\'\r\n    end\r\n    \r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # check pre-op exist ?\r\n    x_pre_op = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id], :module_name=>\"\\\\#{@current_project.name}#pre_op\").first\r\n    r_pre_op = nil\r\n    if x_pre_op\r\n        r_pre_op = get_model[:pre_op].find(x_pre_op[:module_id])\r\n    end\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    map_ind = {}\r\n    map_ind[\'\']  = \'N/A\'\r\n    map_ind[nil] = \'N/A\'\r\n    model[:indication].all.each do |i|\r\n        map_ind[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n    \r\n    # many lesion\r\n    a_lesion = model[:lesion].find(this_rec[:lesion])\r\n    d_lesion = get_document \'lesion\'\r\n    f_lesion = d_lesion.fields\r\n    fl = {}\r\n    fm = {}\r\n    \r\n    s_font = \'\'\r\n        if this_rec[:lesion].nil? or this_rec[:lesion].count < 3\r\n            s_font = \'font-size:1.3em;line-height:1.3em\'\r\n        end\r\n    \r\n    f_lesion.each do |i|\r\n        # lab = i[:label]\r\n        lov = i[:lov]\r\n        name = i[:column_name]\r\n        if lov\r\n            fm[name] = {}\r\n            ll = lov.split(/[\\r\\n]+/)\r\n            ll.each do |j|\r\n                if j.include? \'|\'\r\n                    xx = j.split(\'|\')\r\n                    fm[name][xx[0].strip.to_s] = xx[1].strip\r\n                else\r\n                    fm[name][j.strip] = j.strip\r\n                end\r\n            end\r\n        end\r\n    end\r\n    \r\n    def get_render_value(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return \'-\'\r\n        else\r\n            return render_value(f.to_s)\r\n        end\r\n    end\r\n    \r\n    def get_value(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return \'-\'\r\n        else\r\n            return @record[f]\r\n        end\r\n    end\r\n    \r\n    def is_exist(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return false\r\n        else\r\n            return true\r\n        end\r\n    end\r\n    \r\n    prov = []\r\n    if is_exist(\'fellow\')\r\n        prov << get_render_value(\'fellow\')\r\n    end\r\n    if is_exist(\'colposcopist_1\')\r\n        prov << get_render_value(\'colposcopist_1\')\r\n    end\r\n    colpo_name = prov.join(\' / \')\r\n    \r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        # res[:patient_innovian] = r_inn\r\n        # res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        res[:project] = @current_project\r\n        res[:project_params] = eval(@current_project[:params])\r\n        \r\n        res[:dx] = this_rec[:diagnosis_note]\r\n        res[:px] = get_model[:pacu_record].find(this_rec[:pacu_record])\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px; line-height:20px;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {\r\n    /*color:#666;*/\r\n    line-height:12px;\r\n}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; margin-left:70px; margin-right:10px; }\r\n /* blockquote, */\r\n /*.wrapper{ width:960px;margin-left:auto;margin-right:auto;} */\r\n body {-webkit-print-color-adjust: exact;}\r\n}\r\n\r\n#box{\r\n    max-width:400px;\r\n    \r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:250px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    height:225px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n    .tab { margin-left: 20px; }\r\n    .intro {\r\n        font-weight:bold;\r\n        width : 170px;\r\n        /*display: inline-block;*/\r\n    }\r\n    v {color:#2561cD};\r\n\r\n</style>\r\n<%# stylesheet_link_tag    \"application\"  %>\r\n<script>\r\n    document.title = \"<%= r_pat.hn %> - <%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> - PRINT\"\r\n</script>\r\n<body>\r\n	<div class=\"wrapper\" >\r\n		<div id=\"head\">\r\n<%\r\n    app_logo = @current_project.get_setting(\'logo_report_path\')\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n			<div style=\'float:left\'>\r\n			    <span style=\"margin-top: 30px;display: block;font-size: 2em;font-weight: bold;margin-left: 20px;\">Colposcopic Report</span>\r\n			</div>\r\n			<div id=\"logoright\" ><a href=\"../Home/index\"><img src=\'<%=app_logo%>\' height=\"55px\" style=\"float:right;margin-top:15px;margin-right:20px\" /></a></div>\r\n		</div>\r\n		<br />\r\n		<div id=\"page\" style=\'min-height:960px\'>\r\n		<!-- Title Section -->\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n				<tr>\r\n					<td > \r\n						<table width=\"100%\">\r\n							<tr>\r\n							    <td width=\'65%\' style=\'vertical-align:top\'>\r\n							        <span class=\"intro\">Operation Date : </span> <v><%= r_app[:date].strftime(\'%d-%m-%Y\') if r_app[:date] %></v> <br/> \r\n							        <span class=\"intro\">Colposcopist : </span> <v><%= colpo_name %></v><br/>\r\n							        <br/>\r\n								</td>\r\n								<td style=\'vertical-align:top\'>\r\n									<span class=\'intro\'>HN : </span><%=r_pat.hn%> <br/>\r\n									<span class=\' intro\'>Name : </span><%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> <br/>\r\n									<span class=\' intro\'> Age : </span> <%= age %> yr  \r\n									<span class=\'tab intro\'>Gender : </span><%= gender %>\r\n								</td>\r\n							</tr>\r\n							<!--<tr>-->\r\n							<!--    <td colspan=\'2\'>&nbsp;</td>-->\r\n							<!--</tr>-->\r\n						</table>\r\n						\r\n			<hr style=\"margin-top: 5px;\"/>\r\n						<table width=\'100%\'>\r\n							<tr>\r\n							    <td colspan=\'2\'>&nbsp;</td>\r\n							</tr>\r\n							<tr>\r\n							    <td colspan=\'2\'>\r\n							        <span class=\"intro\" style=\'width:75px;display:inline-block\'>PARA : </span> <v style=\'width:50px;display:inline-block\'><%= \"\\\\#{this_rec[:para1]}-\\\\#{this_rec[:para2]}-\\\\#{this_rec[:para3]}-\\\\#{this_rec[:para4]}\" %></v>\r\n							        <%\r\n							            mp = this_rec[:menopause] == \'\' ? \'-<br/>\'.html_safe : this_rec[:menopause]\r\n							        %>\r\n							        <span class=\"intro tab\">Menopause : </span> <v ><%= mp %></v> \r\n							        <% if mp.downcase == \'yes\' %>\r\n							        <span class=\" \"> for <v> <%= this_rec[:menopause_last] %> </v></span> yr. <br/>\r\n							        <% elsif mp.downcase == \'no\' %>\r\n							        <span class=\"intro tab\"> LMP : </span> <v><%= this_rec[:lmp].nil? ? \'-\' : this_rec[:lmp].strftime(\'%d-%m-%Y\') %></v> <span class=\"tab intro\">Contraception : </span> <v><%= this_rec[:contraception] %></v><br/>\r\n							        <% end %>\r\n							        \r\n							        <span class=\"intro\" style=\'width:75px;display:inline-block\'>Partner : </span> <v style=\'width:50px;display:inline-block\'><%= this_rec[:partner] %></v> <span class=\"intro tab\">First SI : </span> <v><%= this_rec[:first_si] %></v> yr.\r\n							        <span class=\"intro tab\">Underlying Disease : </span> <v><%= this_rec[:underlying_disease] %></v> \r\n							    \r\n							        <p>&nbsp;</p>\r\n							    </td>\r\n							</tr>\r\n							<tr>\r\n							    <td colspan=\'2\' style=\'background:#ccc;padding:10px;font-size:1.5em\'>\r\n							        <span class=\"intro\">PAP : </span><v> <%= this_rec[:pap] %></v> \r\n							        <%\r\n							            hpv = this_rec[:hpv]\r\n							        %>\r\n							        <span class=\"tab intro\"> HPV : </span> <v> <%= render_value \'hpv\' %> </v> \r\n							        <% \r\n							            if hpv.include? \'2\' \r\n							                hpvp = this_rec[:hpv_positive]\r\n							        %>\r\n							        <v> / <%= render_value \'hpv_positive\' %></v>\r\n							                <% if hpvp.include? \'3\' %>\r\n							        <v> / <%= this_rec[:hpv_other_high_risk] %></v>\r\n							                <% end %>\r\n							        <% end %>\r\n							    </td>\r\n							</tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n\r\n			<div style=\"display:block;\">\r\n			<!-- Main Content -->\r\n				<table width=\"50%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left;<%= s_font %>\">\r\n				    <tr>\r\n				        <td valign=\'top\'>\r\n				            <span class=\"intro \">General assessment</span><br/>\r\n				            <span class=\'intro tab\'>Adequacy : </span> <v><%= this_rec[:adequacy] %></v> <br/>\r\n				            <span class=\'intro tab\'>Squamocolumnar junction : </span> <v><%= render_value \'squamocolumnar_junction\' %></v> <br/>\r\n				            <span class=\'intro tab\'>Transformation zone : </span> <v><%= render_value \'transformation_zone\' %></v> <br/>\r\n				        </td>\r\n				    </tr>\r\n							<tr>\r\n							    <td>\r\n							        <span class=\'intro\'>Normal colposcopic</span><br/>\r\n							        <span class=\'intro tab\'>Squamous epithelium : </span> <v><%= this_rec[:squamous_epithelium].nil? or this_rec[:squamous_epithelium]==\'\' ? \'-\' : render_value(\'squamous_epithelium\') %></v><br/>\r\n							        <span class=\'intro tab\'>Columnar epithelium : </span> <v><%= this_rec[:columnar_epithelium].nil? or this_rec[:columnar_epithelium]==\'\' ? \'-\' : render_value(\'columnar_epithelium\') %></v><br/>\r\n							        <span class=\'intro tab\'>Other Normal colpscopic : </span> <v><%= this_rec[:other_normal_colpscopic].nil? or this_rec[:other_normal_colpscopic]==\'\' ? \'-\' : render_value(\'other_normal_colpscopic\') %></v> <br/>\r\n							    </td>\r\n							</tr>\r\n<%\r\n    ab = this_rec[:abnormal]\r\n    les = this_rec[:lesion]\r\n    if ab.downcase == \'yes\'\r\n%>\r\n                            <tr>\r\n                                <td>\r\n                                    <span class=\'intro\'>Abnormal colposcopic findings : </span><v>( <%= ab %> )</v><br/>\r\n                                    \r\n                                    <span class=\'intro tab\'>Site of lesion : </span><v><%= get_render_value(\'site_of_lesion\') %></v><br/>\r\n                                    <span class=\'intro tab\'>Biopsy was done : </span><v><%= is_exist(:biopsy_was_done) ? \"Yes, \\\\#{get_render_value(\'biopsy_at_clock\')}\".html_safe : \'NA\'%></v><br/>\r\n                                    <span class=\'intro tab\'>Management : </span><v><%= get_render_value(\'management\') %></v><br/>\r\n<%\r\n    tmp = this_rec[:management]\r\n    if !tmp.nil?\r\n        aa = tmp.split(\'|\')\r\n        aa.each do |i|\r\n            if i == \'3\'\r\n%> \r\n                                    <span class=\'intro tab\'></span><span class=\'intro tab\'>Repeat PAP : </span><v><%= get_value(\'pap_at\') %></v><br/>\r\n<%\r\n            elsif i == \'4\'\r\n%>\r\n                                    <span class=\'intro tab\'></span><span class=\'intro tab\'>Repeat HPV DNA : </span><v><%= get_value(\'hpv_at\') %></v><br/>\r\n<%\r\n            elsif i == \'6\'\r\n%>\r\n                                    <span class=\'intro tab\'></span><span class=\'intro tab\'>Other : </span><v><%= get_value(\'management_other\') %></v><br/>\r\n<%\r\n            end\r\n        end\r\n    end\r\n%>\r\n                                </td>\r\n                            </tr>\r\n<%\r\n    end # end abnormal\r\n%>\r\n				<!--</table>-->\r\n\r\n\r\n<%\r\n    if ab.downcase == \'yes\'\r\n        les = this_rec[:lesion]\r\n        obj = get_model[:lesion].find(les)\r\n        \r\n%>\r\n                <!--<table width=\'49%\'  cellpadding=\"5\" cellspacing=\"5\" style=\"float:right\">-->\r\n                    <tr>\r\n                        <td>\r\n                            <span class=\'intro\'>Number of lesion : </span> <v><%= obj.nil? ? \'-\' : obj.size %></v> <br/>\r\n                        </td>\r\n                    </tr>\r\n<%\r\n        @document = d_lesion\r\n        obj.each_with_index do |v, idx|\r\n            @record = v\r\n%>\r\n                    <tr>\r\n                        <td>\r\n                            <span class=\'intro tab\'>Lesion : </span> <v><%= idx + 1 %></v> <span class=\'intro tab\'>Location : </span><v><%= get_render_value(\'lesion_location\') %></v> ( TZ : <v><%= get_render_value(\'location_tz\') %></v> )  <br/>\r\n                            <% if is_exist(\'grade_1_type\') %>\r\n                            <span class=\'tab\'></span><span class=\'intro tab\'>Grade 1 (minor; insignificant or low grade) </span><br/>\r\n                            <span class=\'tab\'></span><span class=\'intro tab\'> : </span><v><%= get_render_value(\'grade_1_type\') %></v><br/>\r\n                            <% end %>\r\n                            <% if is_exist(\'grade_2_type\') %>\r\n                            <span class=\'tab\'></span><span class=\'intro tab\'>Grade 2 (major; significant or high grade) </span><br/>\r\n                            <span class=\'tab\'></span><span class=\'intro tab\'> : </span><v><%= get_render_value(\'grade_2_type\') %></v><br/>\r\n                            <% end %>\r\n                            <% if is_exist(\'non_grade\') %>\r\n                            <span class=\'tab\'></span><span class=\'intro tab\'>Non-specific : </span><v><%= get_render_value(\'non_grade\') %></v><br/>\r\n                            <% end %>\r\n                            <span class=\'tab\'></span><span class=\'intro tab\'>Location of lesion </span> <v><%= get_value(\'location_of_the_lesion\') %></v> o\'clock, <v><%= get_value(\'percent_of_lesion\') %>%</v> area of cervix <br/>\r\n                            <% if is_exist(\'note\') %>\r\n                            <span class=\'tab\'></span><span class=\'intro tab\'>Note : </span><v><%= get_value(\'note\') %></v><br/>\r\n                            <% end %>\r\n                            <span class=\'tab\'></span><span class=\'intro tab\'><i>Supicious for invasion : </i></span> <v>( <%= get_render_value(\'supicious_for_invasion\') %> )</v> <br/>\r\n                            <% if is_exist(\'atypical_vessels_location\') %>\r\n                            <span class=\'tab\'></span><span class=\'tab\'></span><span class=\'tab\'>Atypical&nbsp;vessels&nbsp;location&nbsp;: <v><%= get_value(\'atypical_vessels_location\') %></v> &nbsp;o\'clock</span><br/>\r\n                            <% end %>\r\n                            <% if is_exist(\'additional_signs\') %>\r\n                            <span class=\'tab\'></span><span class=\'tab\'></span><span class=\'tab\'>Additional signs : </span> <v><%= get_render_value(\'additional_signs\') %></v> <br/>\r\n                            <% end %>\r\n                            <% if is_exist(\'tumor_or_gross_cm\') %>\r\n                            <span class=\'tab\'></span><span class=\'tab\'></span><span class=\'tab\'>Tumor or gross </span> <v><%= get_value(\'tumor_or_gross_cm\') %></v> cm. <br/>\r\n                            <% end %>\r\n                            <% if is_exist(\'miscellaneous_type\') %>\r\n                            <span class=\'tab\'></span><span class=\'intro tab\'><i>Miscellaneous type : </i></span> <v> <%= get_render_value(\'miscellaneous_type\') %> </v> <br/>\r\n                            <% end %>\r\n                            \r\n                        </td>\r\n                    </tr>\r\n<%\r\n        end\r\n        \r\n        @document = this_doc\r\n        @record   = this_rec\r\n%>\r\n                </table>\r\n<%\r\n    end # end abnormal lesion\r\n%>\r\n\r\n\r\n<%\r\n    # image table\r\n    list = this_rec.images\r\n    if list\r\n%>\r\n		<!-- Images -->\r\n		<table width=\'50%\'  cellpadding=\"5\" cellspacing=\"5\" >\r\n		    <tr >\r\n		        <td >\r\n		            <span class=\'intro\' style=\"float:right\">Picture<%= \'s\' if list.size >= 1%></span>\r\n		        </td>\r\n		    </tr>\r\n		    <tr>\r\n		        <td style=\'float:right\'>\r\n                \r\n<%\r\n    atts = list[0...3].compact.collect{|i| get_model[:attachment].find(i)}.compact\r\n            \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n%>\r\n            \r\n            <!--<tr>-->\r\n                <!--<td style=\'float:right\'>-->\r\n        	<div id=\"box\" style=\'float:right\'>\r\n        		<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n        		<v><%=i.title%></v>\r\n        	</div>\r\n        	    \r\n        <% end %>\r\n        \r\n            	</td>\r\n            </tr>\r\n    <% end %>\r\n        \r\n            \r\n        </table>\r\n<%\r\n    end # image\r\n%>\r\n\r\n\r\n\r\n				\r\n				<table width=\'100%\'  cellpadding=\"5\" cellspacing=\"5\" style=\"float:left\">\r\n<%\r\n    if is_exist(\'colposcopic_impression\')\r\n%>\r\n                    <tr>\r\n							    <td style=\'background:#ccc;padding:10px;font-size:1.5em\'>\r\n							    \r\n							        <span class=\"intro\">Colposcopic impression : </span><v> <%= get_render_value(:colposcopic_impression) %> <%= is_exist(:colposcopic_impression_other) ? \" - \\\\#{get_value(:colposcopic_impression_other)}\".html_safe : \'\' %></v> \r\n\r\n							    </td>\r\n					</tr>\r\n<%\r\n    end # end colposcopic impression\r\n%>\r\n                    <tr>\r\n                        <td>\r\n                            <span class=\'intro\' style=\'width:100px;display:inline-block\'>Follow up : </span> <v><%= this_rec[:follow_up].nil? or this_rec[:follow_up]==\'\' ? \'-\' : this_rec[:follow_up] %></v> <br/>\r\n                            <span class=\'intro\' style=\'width:100px;display:inline-block\'>Note : </span> <v><%= this_rec[:note].nil? or this_rec[:note]==\'\' ? \'-\' : this_rec[:note] %></v> <br/>\r\n                        </td>\r\n                    </tr>\r\n                </table>\r\n				\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n<%\r\n    # old image section\r\nif false\r\n    list = this_rec.images\r\n    if list\r\n%>\r\n		<!-- Images -->\r\n		<div id=\"page\">\r\n        <h4>Picture<%= \'s\' if list.size >= 1%> :</h4>\r\n<%\r\n    atts = list[0...3].compact.collect{|i| get_model[:attachment].find(i)}.compact\r\n            \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n%>\r\n        	<div id=\"box\">\r\n        		<img alt=\"1\" src=\"<%=i.path%>?thumb=2\" /><br/>\r\n        		<v><%=i.title%></v>\r\n        	</div>\r\n        <% if index%3==3 %>\r\n            <div class=\"clear\"></div>\r\n        <% end %>\r\n        <% end %>\r\n    <% end %>\r\n        \r\n            <div class=\"clear\"></div>\r\n        </div>\r\n<%\r\n    end # image\r\nend # end false\r\n%>\r\n		<!-- Footer -->\r\n		<div id=\"page\" style=\"height:60px;padding-top: 5px;\">\r\n			<strong>Colposcopist name : </strong> <%= colpo_name %> \r\n			<br/>\r\n			<br/>\r\n			<strong>Colposcopist signature : </strong> ........................................................\r\n			<br />\r\n		</div>\r\n		<div class=\"clear\"></div>\r\n	</div>\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-07-04 15:41:59','2016-07-04 15:41:59','prin',''),(2342,'fields',960,3,'<%\r\n    if d = params[:doc]\r\n        doc = get_document(d.downcase)\r\n        # doc = get_document(\'post_op\')\r\n        if doc\r\n            a_doc = doc.fields\r\n            rs = []\r\n            \r\n            a_doc.each do |i|\r\n                name = i[:name]\r\n                type = i[:field_type]\r\n                col  = i[:column_name]\r\n                lov = \'-\'\r\n                if i[:lov]\r\n                    lov = i[:lov].to_s.split(\'\\r\\n\').join(\', \')\r\n                end\r\n                txt = \"\\\\#{name},\\\\#{col},\\\\#{type},\\\\#{lov}\"\r\n                rs << txt\r\n        \r\n%>\r\n<%= txt %><br/>\r\n<%\r\n            end\r\n        else\r\n%>\r\ndocument not found\r\n<%\r\n        end\r\n    else\r\n%>\r\nusing \'doc\' to get document\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2016-07-05 02:57:56','2016-07-05 02:57:56','fields','developer'),(2343,'print',947,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:endoscopic_exam].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:300px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:0px;\r\n    font-size:0.8em;\r\n    height:190px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n     width:100%;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\"><center><img src=\"/esm/cusys/ent2/cuent2.jpg\" /></center>\r\n<center>\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><h2>Endoscopic Exam</h2></div>\r\n\r\n<div id=\"logoright\">\r\n<br />\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</center>\r\n\r\n\r\n\r\n</div><br /><br /><br />\r\n<div id=\"page\">\r\n\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n\r\n\r\n\r\n\r\n\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> ชื่อ-สกุล : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'ไม่ระบุ\'\r\n    if patient.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>เพศ : </strong><%= gender %> &nbsp; <strong>อายุ :&nbsp;</strong>\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D-->\r\n      </td>\r\n          <td>\r\n         \r\n              <% if record[\'operative_date\']!=nil %>\r\n\r\n<label>Operative date : </label><%=render_value \'operative_date\'%>\r\n\r\n\r\n<% end%>\r\n          </td>\r\n          \r\n      </tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n \r\n	<hr style=\"margin-top: 5px;\"/>\r\n    \r\n    <%\r\n        # atts = models[:attachment].limit(5).find(record.image)\r\n       \r\n       atts_list = record.images[0..4]\r\n \r\n       \r\n       \r\n       atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n       \r\n       \r\n\r\n\r\n    %>\r\n\r\n  \r\n    <div style=\"float:left;width: 800px; font-size:13px\">\r\n   <!--   -->\r\n   \r\n   \r\n\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:100%;margin:0px;min-height:50px\" >\r\n	\r\n\r\n\r\n<br />\r\n\r\n<div id=\"scope_type\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;min-height:30px;\">\r\n<span class=\"\"><label>Scope type : </label></span>	\r\n<%=render_value \'scope_type\'%></div>\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"nasal_cavity\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;;min-height:30px;\">\r\n	<%=render_value \'nasal_cavity\'%>\r\n</div>\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"nasal_abnormal\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<%=render_value \'nasal_abnormal\'%>\r\n</div>\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"nasopharynx\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;;min-height:30px;\">\r\n	<%=render_value \'nasopharynx\'%>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"nasopharynx_abnormal\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n	\r\n<%=render_value \'nasopharynx_abnormal\'%>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"oral_cavity\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;;min-height:30px;\">\r\n<%=render_value \'oral_cavity\'%>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"oral_cavity_abnormal\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n	<%=render_value \'oral_cavity_type\'%>\r\n<%=render_value \'oral_cavity_abnormal\'%>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"oropharynx\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;;min-height:30px;\">\r\n<%=render_value \'oropharynx\'%>\r\n</div>\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"oropharynx_type\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<%=render_value \'oropharynx_type\'%>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n	\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"larynx\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;;min-height:30px;\">\r\n	<%=render_value \'larynx\'%>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"larynx_abnormal\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<!--<%=render_value \'larynx_abnormal\'%>--> &nbsp;\r\n</div>\r\n\r\n\r\n<%\r\n    def get_doc_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].strip\r\n                    tmp[:list] << x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    # field map\r\n    fm = get_doc_field(this.document_name)\r\n\r\n    fx = {\'4\'=>[:larynx_ab_epiglottis],\'5r\'=>[:fvc_rt_note],\'5l\'=>[:fvc_lt_note],\'6r\'=>[:larynx_ab_tvc_r,:larynx_ab_tvc_movement_r,:larynx_ab_tvc_other_r],\'6l\'=>[:larynx_ab_tvc_l,:larynx_ab_tvc_movement_l,:larynx_ab_tvc_other_l],\'7r\'=>[:arytenoid_rt_note],\'7l\'=>[:arytenoid_lt_note]}\r\n    rx = @record[:larynx_abnormal]\r\n    tmp = render_value(\'larynx_abnormal\').split(\',\')\r\n    rx.split(\'|\').each_with_index do |v,i|\r\n%>\r\n\r\n<div class=\"clear\"></div>\r\n<div id=\"field-<%= tmp[i] %>\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;;min-height:30px;\">\r\n	&nbsp;&nbsp;&nbsp;&nbsp;- <%= tmp[i] %> \r\n</div>\r\n<div id=\"value-<%= tmp[i] %>\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n<%\r\n    # sub field\r\n    sf = fx[v]\r\n    # result\r\n    rs = []\r\n    sf.each do |j|\r\n%>\r\n<%= fm[j][:label] %> :<v><%= render_value(j.to_s) %></v> <br/>\r\n<%\r\n    end\r\n%>\r\n</div>\r\n<% end %>\r\n\r\n\r\n<div id=\"hypopharynx\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;;min-height:30px;\">\r\n	<%=render_value \'hypopharynx\'%>\r\n\r\n</div>\r\n<div id=\"note\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;;min-height:30px;\">\r\nNote :	<%=render_value \'note\'%>\r\n\r\n</div>\r\n\r\n</div>\r\n   \r\n   \r\n   \r\n   \r\n   \r\n    </div>\r\n    <div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.images\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%3==2 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong></strong> \r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n<s