spond.min.js\"></script>\r\n	<![endif]-->\r\n<% if false %>\r\n<%= javascript_include_tag \"application\"  %>\r\n<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n<script type=\"text/javascript\" src=\"//netsh.pp.ua/upwork-demo/1/js/typeahead.js\"></script>\r\n<% end %>\r\n	</head>\r\n	<body>\r\n\r\n	<header role=\"banner\" id=\"fh5co-header\" style=\"    position: fixed !important;\r\n    background: #fff;\r\n    -webkit-box-shadow: 0 0 9px 0 rgba(0, 0, 0, 0.1);\r\n    -moz-box-shadow: 0 0 9px 0 rgba(0, 0, 0, 0.1);\r\n    -ms-box-shadow: 0 0 9px 0 rgba(0, 0, 0, 0.1);\r\n    box-shadow: 0 0 9px 0 rgba(0, 0, 0, 0.1);\r\n    margin-top: 0px;\r\n    top: 0;color: #ccc;\">\r\n			<div class=\"container\">\r\n				<!-- <div class=\"row\"> -->\r\n			    <nav class=\"navbar navbar-default\">\r\n		        <div class=\"navbar-header\" >\r\n		        	<!-- Mobile Toggle Menu Button -->\r\n					<a href=\"#\" class=\"js-fh5co-nav-toggle fh5co-nav-toggle\" data-toggle=\"collapse\" data-target=\"#navbar\" aria-expanded=\"false\" aria-controls=\"navbar\"><i></i></a>\r\n		          	<a class=\"navbar-brand\" href=\"index\" ><img src=\"/esm/thks_web/www/content/web/images/logolong.png\" width=\"180\" style=\"float:left\"></a> \r\n		        </div>\r\n		          <div id=\"navbar\" class=\"navbar-collapse collapse\">\r\n		          <ul class=\"nav navbar-nav navbar-right\">\r\n		            <li ><a href=\"index\" data-nav-section=\"home\" style=\"color:#ccc\"><span>Back to Home</span></a></li>\r\n		         \r\n		            \r\n		          </ul>\r\n		        </div>\r\n			    </nav>\r\n			  <!-- </div> -->\r\n		  </div>\r\n	</header>\r\n\r\n\r\n	\r\n	<div id=\"fh5co-features\" data-section=\"features\">\r\n		<div class=\"container\">\r\n			<div class=\"row\">\r\n				<div class=\"col-md-12 section-heading text-center\">\r\n				\r\n				 <%= yield :content%>\r\n				</div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n\r\n\r\n	<footer id=\"footer\" role=\"contentinfo\">\r\n		<div class=\"container\">\r\n			<div class=\"row row-bottom-padded-sm\">\r\n				<div class=\"col-md-12\">\r\n					<p class=\"copyright text-center\">&copy; 2016 Power by E.S.M.Solution</p>\r\n					 <% unless @current_user %>\r\n			   \r\n			   <%=link_to \'Login\', \"/user/login\"  %>\r\n			       \r\n			  <% else %>    \r\n			  <%=@current_user.login%> \r\n			   <%=link_to \'Logout\', \"/user/logout?redirect_to=/www/Home/index\" %>\r\n			       <% end %>\r\n			   \r\n			       <% if @current_user %>\r\n                    | <a href=\"../Member/index\">Members</a>| <a href=\"../Post/index\">Post</a>\r\n            \r\n                    \r\n                    <% end %>\r\n				</div>\r\n			</div>\r\n			\r\n		</div>\r\n	</footer>\r\n	\r\n	\r\n	<!-- For demo purposes Only ( You may delete this anytime :-) \r\n	<div id=\"colour-variations\">\r\n		<a class=\"option-toggle\"><i class=\"icon-gear\"></i></a>\r\n		<h3>Preset Colors</h3>\r\n		<ul>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"style\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"pink\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"blue\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"turquoise\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"orange\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"lightblue\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"brown\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"green\"></a></li>\r\n		</ul>\r\n	</div>-->\r\n	<!-- End demo purposes only -->\r\n\r\n	\r\n	<!-- jQuery -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/jquery.min.js\"></script>\r\n	<!-- jQuery Easing -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/jquery.easing.1.3.js\"></script>\r\n	<!-- Bootstrap -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/bootstrap.min.js\"></script>\r\n	<!-- Waypoints -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/jquery.waypoints.min.js\"></script>\r\n	<!-- Owl Carousel -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/owl.carousel.min.js\"></script>\r\n\r\n	<!-- For demo purposes only styleswitcher ( You may delete this anytime ) \r\n	<script src=\"js/jquery.style.switcher.js\"></script>\r\n	<script>\r\n	$(function(){\r\n		$(\'#colour-variations ul\').styleSwitcher({\r\n			defaultThemeId: \'theme-switch\',\r\n			hasPreview: false,\r\n			cookie: {\r\n	          	expires: 30,\r\n	          	isManagingLoad: true\r\n	      	}\r\n		});	\r\n		$(\'.option-toggle\').click(function() {\r\n			$(\'#colour-variations\').toggleClass(\'sleep\');\r\n		});\r\n	});\r\n	</script>-->\r\n	<!-- End demo purposes only -->\r\n\r\n	<!-- Main JS (Do not remove) -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/main.js\"></script>\r\n\r\n	</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-07-10 06:32:01','2016-07-10 06:32:01','',''),(2350,'about',965,2,'<br/ ><div class=\"headline\">About THKJR</div>\r\n<br />\r\n\r\n  The Thai Hip and Knee Joint  Registry collect information on joint replacement surgery and monitor the  performance of joint replacement implants. This program was set up by Thai Hip  and Knee Society in January 2015.<br />\r\n  Hip and knee joint replacement  have become common and highly successful procedure that helps patients return  to daily life by improved mobility and relief pain. There are more than  thousands of such procedures perform in Thailand every year.<br />\r\n  With constant strive to improve patient  outcomes; there are many types of implants can be used in joint replacement  procedures. The registry helps to monitor the performance of these implants and  effectiveness of different technique of surgery, improving clinical standards  and surgery outcome, and the orthopaedic sector as a whole. The THKJR currently  collects data on all hip and knee joint replacements across Thailand.<br />\r\n <br /> \r\n <div class=\"headline\">Mission:</div><br />\r\n  The purpose of the Thai Hip and  Knee Joint Registry is to collect high quality and relevant data about joint  replacement surgery in order to provide an early warning of issues relating to  patient safety. In a continuous drive to improve the quality of outcomes and  ensure the quality and cost effectiveness of joint replacement surgery, the THKJR  will monitor and report on outcomes, and support and enable related research.<br />\r\n <br /><br /><div class=\"headline\">Goals:</div>\r\n<ul>\r\n  <li>Monitor outcomes achieved by brand of  prosthesis, hospital and surgeon, and highlight where these fall below an  expected performance in order to allow prompt investigation.</li>\r\n</ul>\r\n<ul type=\"disc\">\r\n  <li>Inform       patients, clinicians, providers and commissioners of healthcare,       regulators and implant suppliers of the outcomes achieved in joint       replacement surgery.</li>\r\n</ul>\r\n<ul>\r\n  <li>&nbsp;Evidence variations in outcome achieved  across surgical practice in order to inform best practice.</li>\r\n</ul>\r\n<ul type=\"disc\">\r\n  <li>Support       evidence-based purchasing of joint replacement implants for healthcare       providers to support quality and cost effectiveness.</li>\r\n</ul>\r\n\r\n<strong><u>How does the THKJR benefit patients?</u></strong><br /><br />\r\n<ul>\r\n  <li>Be able to provide best perform prosthesis and  surgical technique</li>\r\n</ul>\r\n<ul type=\"disc\">\r\n  <li>Improve       patient safety by showing how well implants, surgeons and hospitals       perform and take action where it is needed</li>\r\n  <li>Give       hospitals, surgeons and implant manufacturers feedback about their       performance to help them improve patient care</li>\r\n</ul>  <br /> <img src=\"/esm/thks_web/www/assets/show3.jpg\" width=\"100%\"> <br /><br />\r\n<div class=\"headline\">Our Partner:</div>\r\n<p>\r\n     <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a6002f790f9b6270000013.jpg\" alt=\"57a6002f790f9b6270000013\">  <span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60031790f9b627000001c.gif\" alt=\"57a60031790f9b627000001c\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60031790f9b627000001f.jpg\" alt=\"57a60031790f9b627000001f\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a6002e790f9b627000000d.png\" alt=\"57a6002e790f9b627000000d\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a6002e790f9b6270000010.jpg\" alt=\"57a6002e790f9b6270000010\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60030790f9b6270000016.jpg\" alt=\"57a60030790f9b6270000016\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60031790f9b6270000019.jpg\" alt=\"57a60031790f9b6270000019\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60032790f9b1ac200006e.jpg\" alt=\"57a60032790f9b1ac200006e\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60032790f9b1ac2000071.jpg\" alt=\"57a60032790f9b1ac2000071\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60033790f9b1ac2000074.png\" alt=\"57a60033790f9b1ac2000074\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60033790f9b1ac2000077.png\" alt=\"57a60033790f9b1ac2000077\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60034790f9b1ac200007a.png\" alt=\"57a60034790f9b1ac200007a\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60034790f9b1ac200007d.jpg\" alt=\"57a60034790f9b1ac200007d\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60035790f9b6270000022.jpg\" alt=\"57a60035790f9b6270000022\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60034790f9b1ac2000080.jpg\" alt=\"57a60034790f9b1ac2000080\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60035790f9b53ff000024.png\" alt=\"57a60035790f9b53ff000024\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60035790f9b6270000025.jpg\" alt=\"57a60035790f9b6270000025\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60035790f9b1ac2000083.jpg\" alt=\"57a60035790f9b1ac2000083\">  </span><span style=\"font-size:12px;\"> <img width=\"100\" src=\"/content/esm/thks_web/www/content/post/image/57a60035790f9b53ff000027.jpg\" alt=\"57a60035790f9b53ff000027\">  </span>\r\n</p>\r\n',NULL,NULL,NULL,'2016-07-10 07:28:46','2016-07-10 07:28:46','about','*'),(2351,'news',965,2,'<%\r\n\r\n    models = get_model\r\n    \r\n    posts = models[:post].where(:published=>\'true\').limit(40).reverse\r\n    \r\n    \r\n\r\n%>\r\n<style>\r\n    h4 {font-weight: bold;}\r\n    \r\n</style>\r\n<br />\r\n<div class=\"headline\">ข่าวสมาคม</div><br/>\r\n<ul>\r\n<% \r\n    matt = models[:attachment]\r\n    \r\n    \r\nfor p in posts \r\n\r\n    atts = matt.find(p.image)\r\n    atts_main = atts.collect{|i| i if i.title.index(\'main\')}.compact\r\n    default = \'/esm/thks_web/www/assets/thkjr.png\'\r\n    default = atts_main[0].path if atts_main.size>0\r\n%>\r\n    \r\n<div style=\"width:200px; float:left; margin-right:10px;\"><div class=\"boxcontent\"><%#atts_main.inspect %>\r\n   <a href=\"post?id=<%=p.id%>\"> <img src=\"<%=default%>\" width=\"100%\" height=\"150px\"  align=\"top\"><h4><%=p.title.html_safe  %> </h4></a><br />\r\n</div><div class=\"clear\"></div></div>\r\n\r\n<% end %>\r\n<div class=\"clear\"></div>\r\n</ul>\r\n</div>',NULL,NULL,NULL,'2016-07-10 07:29:00','2016-07-10 07:29:00','news','*'),(2352,'contact',965,2,'<center>\r\n<div class=\"headline\">Thai Hip-Knee Joint Registry (THKJR) Steering Group</div>\r\n\r\n<h2>ชมรมศัลยแพทย์ข้อสะโพกและข้อเข่าแห่งประเทศไทย</h2>\r\n<img src=\"https://emr-life.com/esm/thks_web/www/assets/vi.jpg\" style=\"box-sizing:border-box;max-width:100%;vertical-align:middle;border:0px;\" width=\"150\"><br />\r\nพ.ต.อ.นพ.วิโรจน์ ลาภไพบูลย์พงศ์  492/1 ถ.พระราม1 <br />แขวงปทุมวัน เขตปทุมวัน กมม. 10330 <br />โทร.02-253-5836  email.thkjoint@gmail.com</div>\r\n</center>',NULL,NULL,NULL,'2016-07-10 07:29:12','2016-07-10 07:29:12','contact','*'),(2353,'export',909,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    is_oneline = false\r\n    if params[:cs] == \'one\'\r\n        is_oneline = true\r\n    end\r\n    \r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n\r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = [] # all parent_id\r\n    pat_ids = [] # all patient_id\r\n    app_par = {}\r\n    pat_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n        pat_par[i[:patient_id]] = i.id.to_s\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    # begin\r\n    # a_pat = a_pat.sort_by{|i| i[:patient_order] if i[:patient_order]}\r\n    a_pat = a_pat.sort{|a,b| a[:patient_order] && b[:patient_order] ? a[:patient_order] <=> b[:patient_order] : a[:patient_order] ? -1 : 1 }\r\n    \r\n    # query patient_module <-> aki\r\n    mod_aki = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#aki\")\r\n    i_aki = []\r\n    p_aki = {}\r\n    mod_aki.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_aki << mid\r\n        if !p_aki.has_key? pid\r\n            p_aki[pid] = []\r\n        end\r\n        p_aki[pid] << mid\r\n    end\r\n    m_aki = {}\r\n    a_aki = get_model[:aki].find(i_aki)\r\n    a_aki.each do |i|\r\n        m_aki[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> summary_form\r\n    mod_out = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#summary_form\")\r\n    i_out = []\r\n    p_out = {}\r\n    mod_out.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_out << mid\r\n        if !p_out.has_key? pid\r\n            p_out[pid] = []\r\n        end\r\n        p_out[pid] << mid\r\n    end\r\n    m_out = {}\r\n    a_out = get_model[:summary_form].find(i_out)\r\n    a_out.each do |i|\r\n        m_out[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> case_record\r\n    mod_case = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#case_record\")\r\n    i_case = []\r\n    p_case = {}\r\n    mod_case.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_case << mid\r\n        if !p_case.has_key? pid\r\n            p_case[pid] = []\r\n        end\r\n        p_case[pid] << mid\r\n    end\r\n    m_case = {}\r\n    a_case = get_model[:case_record].find(i_case)\r\n    a_case.each do |i|\r\n        m_case[i.id] = i\r\n    end\r\n    \r\n    \r\n    # processing\r\n    res = []\r\n    pf = %w{patient_number	patient_order	recheck	reference	birth_date	gender	weight	height	ideal_body_weight	date_of_admission	date_of_icu_admission	time_of_icu_admission	reimbursement	diagnosis	ht	dm	cad	cerebrovascular_disease	malignancy	ckd	esrd	baseline_serum_creainine_by_mdrd	available_baseline	baseline_serum_cr	date_of_baseline_serum_cr	first_available_cr	first_available_cr_date	icu	glasgow_coma_score	temperature	mean_arterial	heart_rate	respiratory_rate	oxygenation	arterial_ph	serum_sodium	serum_potassium	serum_creatinine	hematocrit	white_blood_count	age	chronic_health_points	apache_ii}\r\n\r\n    dd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    # cf = %w{case_status bun  creatinine mechanical_ventilation vasopressor vasopressor_type dose_of_vasopressor rs coagulation cns liver renal cvs diuretic lactate sofa if_rrt}\r\n    cf = %w{record_day case_status move_out_time bun creatinine urine_output24hr intake output net_balance urine_output_cal mechanical_ventilation vasopressor vasopressor_type rate_of_vasopressor dose_of_vasopressor ml_of_vasopressor patient_weight cal_dose_vasopressor rs coagulation cns liver renal cvs diuretic lactate sofa if_rrt indication mode_of_rrt type_of_vascular_access site_of_vascular_access internal_jugular_lr bfr dfr dialyzer anticoagulant_ihd complication_ihd type_of_vascular_access_sled site_of_vascular_access_sled internal_jugular_lr_sled duration_sled bfr_sled dfr_sled dialyzer_sled anticoagulant_sled complication_sled type_of_vascular_access_crrt site_of_vascular_access_crrt internal_jugular_lr_crrt  crrt_bfr crrt_ufr rfr_crrt dfr_crrt effrent_fluid total_time_crrt delivered_lose machine_type mode anticoagulant_crrt crrt_complication type_of_catheter type_solution cycle fill_volume dwell_time pd_complication}\r\n\r\n    of = %w{stop_rrt_date rrt_day  icu_discharge_status date_of_icu_discharge los_in_icu  hospital_discharge_status date_of_hospital_discharge los_in_hospital  death_date total_ventilator_day  crbsi vap}\r\n    af = %w{aki_max_staging aki_max_staging_from auto_max_staging cr_diagnosis cr_diagnosis_from_day cr_staging cr_staging_from_day urine_output_diagnosis urine_output_from_day urine_output_staging urine_output_staging_from_day cause_of_aki cause_other admin_cause_of_aki cause_other2 aki_type a_on_c}\r\n\r\n    dx_group = {}\r\n\r\n    # for each patient\r\n    a_pat.each do |pat|\r\n        tmp = {}\r\n        msg = []\r\n        # filter age < 18\r\n        if pat.nil? or pat[:age].to_i < 18\r\n            next\r\n        end\r\n        \r\n        pp = {}\r\n        pp[:site] = @current_solution.name\r\n        pf.each do |i|\r\n            pp[i.to_sym] = pat[i.to_sym]\r\n        end\r\n        \r\n        dx_str = pp[:diagnosis].clone.downcase\r\n        if dx_str.include? \' and \'\r\n            dx_str.gsub!(\' and \', \',\')\r\n        end\r\n        dx_str.split(\',\').collect do |i|\r\n            k = i.strip\r\n            v = pp[:patient_number]\r\n            if !dx_group.has_key? k\r\n                dx_group[k] = []\r\n            end\r\n            dx_group[k] << v\r\n        end\r\n        \r\n        \r\n        pp[:time_of_icu_admission] = pp[:time_of_icu_admission].nil? ? \'\' : pp[:time_of_icu_admission].strftime(\'%H:%M\')\r\n        \r\n        # recheck urine output from case_record\r\n        cid_list = []\r\n        if xx = p_case[pat.id]\r\n            xx.each do |i|\r\n                cid_list << m_case[i]\r\n            end\r\n        else\r\n            msg << \"xx found\"\r\n        end\r\n        \r\n        # mapping day <--> case_record\r\n        mc = {}\r\n        cid_list.each do |i|\r\n            rd = i[:record_day]\r\n            if rd==\'\'\r\n                msg << \'empty rd\'\r\n            end\r\n            if !mc.has_key? rd\r\n                mc[rd] = i\r\n            else\r\n                msg << \"dup rd[\\\\#{rd}]\"\r\n            end\r\n        end\r\n        \r\n        # checking aki is created ?\r\n        is_aki = false\r\n        aid_list = []\r\n        if xx = p_aki[pat.id]\r\n            xx.each do |i|\r\n                aid_list << m_aki[i]\r\n            end\r\n     