n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"background:#none\">\r\n\r\n<div style=\"border:0px solid\" >\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(\'customer\')\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document \'customer\'\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<br />\r\n<center><h4> คุณได้ลงทะเบียนแล้วสามารถตรวจสอบผลการลงทะเบียนได้\r\n    \r\n</h4></center>\r\n<br />&nbsp;\r\n<meta http-equiv=\"refresh\" content=\"3;url=<%= return_url.html_safe %>\" />\r\n\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>\'register\' do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = model.new\r\n   @document =  get_document \'customer\' \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<div style=\"padding-left:200px\"><p>\r\n<%= f.submit \'ลงทะเบียน\' %> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<br/>\r\n\r\n</p>\r\n</div>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n\r\n<script>\r\n   \r\n</script>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-07-15 02:04:18','2016-07-15 02:04:18','register','*'),(2377,'document_name',972,1,'\'speaker\'',NULL,NULL,NULL,'2016-07-15 14:13:12','2016-07-15 14:13:12',NULL,NULL),(2378,'document_name',973,1,'\'live_event\'',NULL,NULL,NULL,'2016-07-16 05:43:31','2016-07-16 05:43:31',NULL,NULL),(2379,'index',974,2,'\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Solution\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE</b></center><br/>\r\n    <%= render :inline=>this.module %>\r\n</div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n<% \r\n\r\n    model = get_model\r\n    patient_model = model[:patient]\r\n    patient_module_model = model[:patient_module]\r\n    modules = @context.get_projects_by_abstract \'ehr.emr\' \r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n\r\n<%\r\ndb = patient_model.collection.db\r\n%>\r\n<%#db.class%>\r\n<%#db.collection_names.sort%>\r\n<%#db.collection(\'colo.appointment\').count%>\r\n\r\n<%\r\nfor m in modules\r\n  \r\n    list = db.collection(\"\\\\#{m.name}.appointment\").group({:keyf=>\'function(doc){return {month:doc.date.getMonth()};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\'\r\n        #   :cond=>{:status=>{\'$in\'=>[\'Completed\',\'Recovery\',\'Processing\']},:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}\r\n        })\r\n        columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n        \r\n    if list.size>0    \r\n    data = []\r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    data[i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\n    \r\n\r\n%>\r\n<%#list.inspect%>\r\n<div id=\"chart-<%=m.id%>\" style=\"border:0px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n<%#columns.to_json%>\r\n            <script>\r\n                    $(\"#chart-<%=m.id%>\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"<%=m.title%> Patients by Month\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: [{\r\n                            name: \"Patients\",\r\n                            data: <%=data.to_json.html_safe %>\r\n                        }],\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                \r\n\r\n             \r\n            </script>                 \r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        System Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<table class=\"table table-striped table-bordered table-condensed\">\r\n<thead>\r\n<tr>\r\n<th>Title</th>\r\n<th>Value</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Disk Space</td>\r\n<%\r\n   size = patient_model.collection.db.stats[\'storageSize\']\r\n   unit = \'B\'\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'KB\'\r\n   size /= 1000\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'MB\'\r\n   size /= 1000\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'GB\'\r\n   size /= 1000\r\n   \r\n   end\r\n   end\r\n   end\r\n   \r\n   \r\n\r\n%>\r\n\r\n<td><%=format(\'%.2f\',size)%> <%=unit%></td>\r\n</tr>\r\n<tr>\r\n<td>Total Patient</td>\r\n<td><%= (model[:patient]).count %></td>\r\n</tr>\r\n<tr>\r\n<td>Total Module</td>\r\n<td><%= modules.size %></td>\r\n</tr>\r\n<tr>\r\n\r\n</tr>\r\n<tr>\r\n<td>Total Record</td>\r\n<td><%= (model[:patient_module]).count %></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<!--\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Support\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n        <%= link_to \'Inventory System\', \'../../inventory/Home/index\',:class=>\'btn\' %>\r\n    </div>\r\n</div>\r\n-->\r\n</div>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-07-18 09:09:55','2016-07-18 09:09:55','','');
INSERT INTO `esm_operations` VALUES (2380,'recheck_aki',909,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    is_all = false\r\n    if params[:cs] == \'all\'\r\n        is_all = true\r\n    end\r\n    \r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    \r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = [] # all parent_id\r\n    pat_ids = [] # all patient_id\r\n    app_par = {}\r\n    pat_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n        pat_par[i[:patient_id]] = i.id.to_s\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    # begin\r\n    # a_pat = a_pat.sort_by{|i| i[:patient_order] if i[:patient_order]}\r\n    a_pat = a_pat.sort{|a,b| a[:patient_order] && b[:patient_order] ? a[:patient_order] <=> b[:patient_order] : a[:patient_order] ? -1 : 1 }\r\n    \r\n    # query patient_module <-> aki\r\n    mod_aki = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#aki\")\r\n    i_aki = []\r\n    p_aki = {}\r\n    mod_aki.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_aki << mid\r\n        if !p_aki.has_key? pid\r\n            p_aki[pid] = []\r\n        end\r\n        p_aki[pid] << mid\r\n    end\r\n    m_aki = {}\r\n    a_aki = get_model[:aki].find(i_aki)\r\n    a_aki.each do |i|\r\n        m_aki[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> summary_form\r\n    mod_out = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#summary_form\")\r\n    i_out = []\r\n    p_out = {}\r\n    mod_out.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_out << mid\r\n        if !p_out.has_key? pid\r\n            p_out[pid] = []\r\n        end\r\n        p_out[pid] << mid\r\n    end\r\n    m_out = {}\r\n    a_out = get_model[:summary_form].find(i_out)\r\n    a_out.each do |i|\r\n        m_out[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> case_record\r\n    mod_case = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#case_record\")\r\n    i_case = []\r\n    p_case = {}\r\n    mod_case.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_case << mid\r\n        if !p_case.has_key? pid\r\n            p_case[pid] = []\r\n        end\r\n        p_case[pid] << mid\r\n    end\r\n    m_case = {}\r\n    a_case = get_model[:case_record].find(i_case)\r\n    a_case.each do |i|\r\n        m_case[i.id] = i\r\n    end\r\n    \r\n    \r\n    # processing\r\n    res = []\r\n    pf = %w{patient_number	patient_order	recheck	reference	birth_date	gender	weight	height	ideal_body_weight	date_of_admission	date_of_icu_admission	time_of_icu_admission	reimbursement	diagnosis	ht	dm	cad	cerebrovascular_disease	malignancy	ckd	esrd	baseline_serum_creainine_by_mdrd	available_baseline	baseline_serum_cr	date_of_baseline_serum_cr	first_available_cr	first_available_cr_date	icu	glasgow_coma_score	temperature	mean_arterial	heart_rate	respiratory_rate	oxygenation	arterial_ph	serum_sodium	serum_potassium	serum_creatinine	hematocrit	white_blood_count	age	chronic_health_points	apache_ii}\r\n\r\n    dd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    cf = %w{case_status bun  creatinine mechanical_ventilation vasopressor vasopressor_type dose_of_vasopressor rs coagulation cns liver renal cvs diuretic lactate sofa if_rrt}\r\n    # cf = %w{record_day case_status move_out_time bun creatinine urine_output24hr intake output net_balance urine_output_cal mechanical_ventilation vasopressor note vasopressor_type rate_of_vasopressor dose_of_vasopressor ml_of_vasopressor patient_weight cal_dose_vasopressor rs coagulation cns liver renal cvs diuretic lactate sofa if_rrt indication mode_of_rrt type_of_vascular_access site_of_vascular_access internal_jugular_lr bfr dfr dialyzer anticoagulant_ihd complication_ihd type_of_vascular_access_sled site_of_vascular_access_sled internal_jugular_lr_sled duration_sled bfr_sled dfr_sled dialyzer_sled anticoagulant_sled complication_sled type_of_vascular_access_crrt site_of_vascular_access_crrt internal_jugular_lr_crrt  crrt_bfr crrt_ufr rfr_crrt dfr_crrt effrent_fluid total_time_crrt delivered_lose machine_type mode anticoagulant_crrt crrt_complication type_of_catheter type_solution cycle fill_volume dwell_time pd_complication}\r\n\r\n    of = %w{stop_rrt_date rrt_day  icu_discharge_status date_of_icu_discharge los_in_icu  hospital_discharge_status date_of_hospital_discharge los_in_hospital  death_date total_ventilator_day  crbsi vap}\r\n    af = %w{aki_max_staging aki_max_staging_form cr_staging urine_output_staging auto_max_staging cr_diagnosis cr_diagnosis_from_day  cr_staging_from_day urine_output_diagnosis urine_output_from_day  urine_output_staging_from_day  admin_cause_of_aki aki_type aki_from a_on_c}\r\n\r\n    dx_group = {}\r\n\r\n    # for each patient\r\n    a_pat.each do |pat|\r\n        tmp = {}\r\n        msg = []\r\n        if pat.nil?\r\n            next\r\n        end\r\n        \r\n        pp = {}\r\n        pp[:site] = @current_solution.name\r\n        pf.each do |i|\r\n            pp[i.to_sym] = pat[i.to_sym]\r\n        end\r\n        \r\n        dx_str = pp[:diagnosis].clone.downcase\r\n        if dx_str.include? \' and \'\r\n            dx_str.gsub!(\' and \', \',\')\r\n        end\r\n        dx_str.split(\',\').collect do |i|\r\n            k = i.strip\r\n            v = pp[:patient_number]\r\n            if !dx_group.has_key? k\r\n                dx_group[k] = []\r\n            end\r\n            dx_group[k] << v\r\n        end\r\n        \r\n        # recheck urine output from case_record\r\n        cid_list = []\r\n        if xx = p_case[pat.id]\r\n            xx.each do |i|\r\n                cid_list << m_case[i]\r\n            end\r\n        else\r\n            msg << \"xx found\"\r\n        end\r\n        \r\n        # mapping day <--> case_record\r\n        mc = {}\r\n        cid_list.each do |i|\r\n            rd = i[:record_day]\r\n            if rd==\'\'\r\n                msg << \'empty rd\'\r\n            end\r\n            if !mc.has_key? rd\r\n                mc[rd] = i\r\n            else\r\n                msg << \"dup rd[\\\\#{rd}]\"\r\n            end\r\n        end\r\n        \r\n        # checking aki is created ?\r\n        is_aki = false\r\n        aid_list = []\r\n        if xx = p_aki[pat.id]\r\n            xx.each do |i|\r\n                aid_list << m_aki[i]\r\n            end\r\n            is_aki = true\r\n        else\r\n            msg << \"NO AKI\"\r\n        end\r\n        \r\n        # assign aki\r\n        # auto max staging\r\n        r_aki = nil\r\n        if is_aki\r\n            r_aki = aid_list[0]\r\n            \r\n            sum = 0\r\n            af.each do |i|\r\n                pp[i.to_sym] = r_aki[i.to_sym].nil? ? \'\' : r_aki[i.to_sym]\r\n                sum += r_aki[i.to_sym].nil? ? 0 : r_aki[i.to_sym].to_i\r\n                # pp[i.to_sym] = r_aki\r\n            end\r\n            if sum > 0\r\n                pp[:aki] = \'Yes\'\r\n            else\r\n                pp[:aki] = \'No(Aki)\'\r\n            end\r\n            \r\n            pp[:auto_max_staging] = \"\\\\#{pp[:cr_staging]}\\\\#{pp[:urine_output_staging]}\"\r\n            if params[:update]\r\n                if r_aki\r\n                    cr = pp[:cr_staging].to_i\r\n                    ur = pp[:urine_output_staging].to_i\r\n                    pp[:aki_max_staging] = 0\r\n                    pp[:aki_max_staging_form] = 0\r\n                    if cr > ur\r\n                        pp[:aki_max_staging] = cr\r\n                        pp[:aki_max_staging_form] = 1\r\n                    elsif cr < ur\r\n                        pp[:aki_max_staging] = ur\r\n                        pp[:aki_max_staging_form] = 2\r\n                    elsif (cr != 0) and cr == ur\r\n                        pp[:aki_max_staging] = cr\r\n                        pp[:aki_max_staging_form] = 3\r\n                    end\r\n                        \r\n                    # r_aki.update_attributes :auto_max_staging=>\"\\\\#{pp[:cr_staging]}\\\\#{pp[:urine_output_staging]}\"\r\n                    r_aki.update_attributes :aki_max_staging=>pp[:aki_max_staging], :aki_max_staging_form=>pp[:aki_max_staging_form]\r\n                end\r\n            end\r\n        else\r\n            pp[:aki] = \'No\'\r\n        end\r\n        \r\n        # checking summary_form is created ?\r\n        is_out = false\r\n        oid_list = []\r\n        if xx = p_out[pat.id]\r\n            xx.each do |i|\r\n                oid_list << m_out[i]\r\n            end\r\n            is_out = true\r\n            # pp[:outcome] = \'Yes\'\r\n        else\r\n            msg << \"NO OUTCOME\"\r\n            # pp[:outcome] = \'No\'\r\n        end\r\n        \r\n        # assign summary_form (outcome)\r\n        r_out = nil\r\n        if is_out\r\n            r_out = oid_list[0]\r\n            \r\n            of.each do |i|\r\n                pp[i.to_sym] = r_out[i.to_sym].nil? ? \'\' : r_out[i.to_sym]\r\n                # pp[i.to_sym] = m_out.to_json.html_safe \r\n            end\r\n            pp[:outcome] = \'Yes\'\r\n        else\r\n            pp[:outcome] = \'No\'\r\n        end\r\n\r\n        \r\n        \r\n        # number of record_day\r\n        nrd = cid_list.count\r\n        \r\n        \r\n        pp[:num_of_record_day] = nrd\r\n        if !mc.empty? and is_all\r\n            dd.each do |i|\r\n                if !mc[i].nil?\r\n                    cf.each do |j|\r\n                        if j.to_s == \'move_out_time\'\r\n                            if mc[i][:case_status].to_i != 0\r\n                                pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                            end\r\n                        else\r\n                            pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym]\r\n                        end\r\n                    end\r\n                end\r\n            end # end dd\r\n        end  \r\n        \r\n        pm_id = pat_par[pat.id]\r\n        x_id = app_par[pm_id]\r\n        # pp[:detail] = link_to(\'detail\', \"../Home/patient_record?id=\\\\#{x_id}\", :target=>\'_blank\')\r\n        pp[:time_of_icu_admission] = pp[:time_of_icu_admission].nil? ? \'\' : pp[:time_of_icu_admission].strftime(\'%H:%M\')\r\n        \r\n        res << pp\r\n    end\r\n    \r\n    lbl = []\r\n    lbl << \'site\'\r\n    lbl = lbl + pf\r\n    lbl << \"num_of_record_day\"\r\n    if is_all\r\n        fx = cf\r\n        fx.each do |i|\r\n            dd.each do |j|\r\n                lbl << \"\\\\#{i}_\\\\#{j}\"\r\n            end\r\n        end\r\n    end\r\n    lbl << \'aki\'\r\n    lbl = lbl + af\r\n    lbl << \'outcome\'\r\n    lbl = lbl + of\r\n        \r\n    \r\n    # result assign\r\n    display = \'table\'\r\n    if params[:type] == \'csv\'\r\n        display = \'csv\'\r\n    elsif params[:type] == \'xls\'\r\n        display = \'xls\'\r\n    elsif params[:type] == \'json\'\r\n        display = \'json\'\r\n    end\r\n    \r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    # rs[:app_par] = app_par\r\n    # rs[:mod_par] = mod_par\r\n\r\n    if display == \'json\'\r\n        rs[:all_patient] = a_pat.count\r\n        rs[:patient_1] = a_pat[1]\r\n        rs[:all_aki] = a_aki.count\r\n        rs[:all_case_record] = a_case.count\r\n        rs[:result] = res\r\n        rs[:time] = Time.now - tb\r\n%>\r\n\r\n<%= rs.to_json.html_safe %>\r\n\r\n<%\r\n    elsif display == \'table\'\r\n        # ff = res[0].keys\r\n        ff = lbl.collect{|i| i.to_sym}\r\n%>\r\n\r\n<%= stylesheet_link_tag    \"application\"  %>\r\n<h3>Total Patient = <%= a_pat.count %></h3>\r\nquery time = <%= Time.now - tb %>\r\n\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n<% ff.each do |i| %>\r\n        <th><%= i %></th>\r\n<% end %>        \r\n    </tr>\r\n<% \r\n        res.each do |i| \r\n%>\r\n    <tr>\r\n<% \r\n            ff.each do |j| \r\n                val = i[j]\r\n%>\r\n       <td><%= val %></td>\r\n<% end %>\r\n    </tr>\r\n<% end %>\r\n</table>\r\n\r\n<br/>\r\nProcessing time = <%= Time.now - tb %><br/>\r\n\r\n<%\r\n    elsif display == \'csv\'\r\n        require \'csv\'\r\n        fname = \'Export\'\r\n        if params[:fname]\r\n            fname = params[:fname]\r\n        end\r\n    \r\n        response.headers[\"Content-Type\"] = \"text/csv\"\r\n        response.headers[\"Content-disposition\"] = \"attachment; filename=\\\\#{params[:solution_name]}-\\\\#{fname}-\\\\#{Time.now.to_i}.csv\"\r\n        \r\n        # ff = res[0].keys\r\n        ff = lbl.collect{|i| i.to_sym}\r\n        \r\n        xxx = CSV.generate do |csv|\r\n            csv << ff\r\n            res.each do |i|\r\n                tmp = []\r\n                ff.each do |j|\r\n                    tmp << i[j]\r\n                end\r\n                csv << tmp\r\n            end\r\n        end\r\n%>\r\n<%= xxx.html_safe %>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2016-07-19 02:42:32','2016-07-19 02:42:32','recheck_aki',''),(2381,'link_recheck_aki',909,3,'<%\r\n    # rid = %w{1	2	3	4	5	6	7	9	11	12	13	14	15	16	17	19	21	23}\r\n    # THAI\r\n    # rid = %w{1	2	3	4	5	6	7	9	11	12	13	14	15	16	17	21	23}\r\n    # LAOS + PHILIPPINS\r\n    rid = %w{8 19 24 25 26 27}\r\n    idx = 1\r\n    rid.each do |i|\r\n%>\r\n<h3><%= idx %>. RRTS_<%= i %></h3>\r\n<ul>\r\n    <!--<li><a href=\'https://emr-life.com/rrts_<%=i%>/rrts/Zam/recheck_aki?update=true\' target=\'_blank\'>Recheck AKI</a><br/></li>-->\r\n    <li><a href=\'https://emr-life.com/rrts_<%=i%>/rrts/Zam/patient\' target=\'_blank\'>Recheck Patient</a></li>\r\n    <li><a href=\'https://emr-life.com/rrts_<%=i%>/rrts/Zam/aki\' target=\'_blank\'>Recheck AKI</a></li>\r\n</ul>\r\n<%\r\n        idx += 1\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2016-07-19 05:08:35','2016-07-19 05:08:35','link_recheck_aki',''),(2383,'layout',976,4,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\'default\'\r\n\r\n			%>\r\n		\r\n		<script src=\"/ace/src-min-noconflict/ace.js\" type=\"text/javascript\" charset=\"utf-8\"></script>\r\n\r\n        <!--<script type=\"text/javascript\" src=\"http://maps.googleapis.com/maps/api/js?sensor=false\"></script>-->\r\n\r\n	\r\n        <!-- Favicon -->\r\n            <link rel=\"shortcut icon\" href=\"/favicon.ico\" />\r\n		\r\n        <!--[if lte IE 8]>\r\n            <link rel=\"stylesheet\" href=\"css/ie.css\" />\r\n            <script src=\"/gebo/js/ie/html5.js\"></script>\r\n			<script src=\"/gebo/js/ie/respond.min.js\"></script>\r\n        <![endif]-->\r\n		\r\n		\r\n		\r\n		\r\n			<%= javascript_include_tag \"application\"  %>\r\n			\r\n			<%= stylesheet_link_tag    \"application\"  %>\r\n			<%= csrf_meta_tag %>\r\n            \r\n			<%= render :partial=>\'/layouts/kendoui\'%>\r\n			<link href=\"/kendoui/source/styles/kendo.<%=theme%>.css\" rel=\"stylesheet\"/>\r\n\r\n			<link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n			\r\n\r\n\r\n	\r\n		    <title><%=title%></title>\r\n\r\n				<script>\r\n					$(document).ready(function() {\r\n						//* show all elements & remove preloader\r\n						// setTimeout(\'$(\"html\").removeClass(\"js\")\',1000);\r\n						 // $(\"html\").removeClass(\"js\");\r\n					});\r\n				</script>\r\n		\r\n				 <style>\r\n    .w-box-content.cnt_a {background: #fff;}\r\n    .k-grid table {font-size: 1em;}\r\n.k-calendar .k-content {font-size: 1em;padding-top:5px;}\r\n.k-autocomplete .k-input, .k-dropdown-wrap .k-input, .k-picker-wrap .k-input, .k-numeric-wrap .k-input, .k-numeric-wrap .k-link, .k-colorpicker .k-selected-color, .k-progress, .k-progress-status {\r\nheight: 25px;}\r\n.field-data {\r\nwidth: 220px;}\r\n\r\ninput{\r\n    height:25px;\r\n}\r\nbody { \r\n    /*background-image: url(\'/esm/thks/www/content/hip-knee-pain-bw.jpg\');*/\r\n    /* ref : http://i0.wp.com/blog.beaumont.edu/wp-content/uploads/2014/10/hip-knee-pain.png */\r\n    background: black;\r\n    background-repeat: no-repeat;\r\n    background-attachment: fixed;\r\n    background-position: center top; \r\n    background-color: black;\r\n    background-size: cover;\r\n    padding: 20px;\r\n    font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\r\n    /*font-weight: lighter;*/\r\n    /*font-size: 1em;*/\r\n}\r\n</style>\r\n		\r\n		\r\n    </head>\r\n    <body>\r\n	<!--background:url(\'/esm/ehr/my_module/surgeons-bg.jpg\') -->\r\n<a href=\"../../www/Home/index\"><img src=\"/esm/thks/www/content/logo-emr-life_white.png\" width=\"200px\" style=\"padding-bottom: 10px\" ></a>\r\n<span style=\"float:right;color:#efefef;font-size:1.2em\" >\r\n    <%= @current_user.login %> | <%=link_to \'Logout\',\'/user/logout\' %>\r\n</span>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n					</div>\r\n</hr>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\" style=\"padding:0px;\">\r\n\r\n				   <%= yield %><%= yield :content%>\r\n                \r\n                </div>\r\n            </div>\r\n     \r\n\r\n	<div class=\"sidebar\" style=\"display:none\">\r\n		<div class=\"antiScroll\">\r\n			<div class=\"antiscroll-inner\" style=\"width:260px\">\r\n				<div class=\"antiscroll-content\" >\r\n					<div class=\"sidebar_inner\">\r\n						<form action=\"../Home/search\" class=\"input-append\" method=\"post\" >\r\n							<input autocomplete=\"off\" id=\"search-field\" name=\"query\" class=\"search_query input-medium\" style=\"height:20px\" size=\"16\" type=\"text\" placeholder=\"Search...\" />\r\n							<button type=\"submit\" class=\"btn\" style=\"height:30px\"><i class=\"icon-search\"></i></button>\r\n						</form>\r\n     		<div id=\"context-menu\" class=\"accordion\">\r\n             <% #render :partial=>\'/layouts/context_menu\'%>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>            \r\n		\r\n\r\n		\r\n\r\n		<script type=\"text/javascript\" charset=\"utf-8\">\r\n			refresh_remote();\r\n			$(\'#search-field\').focus()\r\n		</script>		\r\n		\r\n<%= include_essential %>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2016-07-19 14:17:20','2016-07-19 14:17:20','layout',''),(2384,'login',976,4,'<html>\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n\r\n <!-- Bootstrap framework -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap.min.css\" />\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap-responsive.min.css\" />\r\n        <!-- theme color-->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n        <!-- tooltip -->    \r\n			<link rel=\"stylesheet\" href=\"/gebo/lib/qtip2/jquery.qtip.min.css\" />\r\n        <!-- main styles -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/style.css\" />\r\n<style>\r\ninput, textarea, select, .uneditable-input { height:40px;font-size:1em;}\r\n.login_page .cnt_b { padding:15px 0}\r\nbody { \r\n    background-image: url(\'/esm/thks/www/content/hip-knee-pain.png\');\r\n    /* ref : http://i0.wp.com/blog.beaumont.edu/wp-content/uploads/2014/10/hip-knee-pain.png */\r\n    /*background: black;*/\r\n    background-repeat: no-repeat;\r\n    background-attachment: fixed;\r\n    background-position: center top; \r\n    background-color: black;\r\n    background-size: cover;\r\n    padding: 20px;\r\n    font-family: \'Helvetica Neue\',Helvetica,Arial,sans-serif;\r\n    /*font-weight: lighter;*/\r\n    /*font-size: 1em;*/\r\n}\r\n</style>            \r\n</head>\r\n<body class=\"login_page\">\r\n<script src=\"/gebo/js/jquery.min.js\"></script>\r\n<script src=\"/gebo/js/jquery.actual.min.js\"></script>\r\n<script src=\"/gebo/lib/validation/jquery.validate.min.js\"></script>\r\n<script src=\"/gebo/bootstrap/js/bootstrap.min.js\"></script>\r\n<%\r\n	p = {}\r\n	if @current_project \r\n	tp = @current_project.get_params if @current_project \r\n	p = tp if tp\r\n	end\r\n	title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"ESM:Innovation as a Service\"\r\n	bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#eee\"\r\n	logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n%>\r\n\r\n<%\r\n    user = \'\'\r\n	user = params[:user][:login] if params[:user]\r\n%>\r\n<%= form_for :user, :action=>\'login\',  :html => { :id => \"user_login\"} do|form|%>\r\n            <center>\r\n                <a href=\"/\">\r\n            <!--<img src=\"/esm/taig/www/content/logo_HIPKNEE.png\" style=\"background-color: white;border-color:white;width:150px;border-radius: 100px;\">-->\r\n            <!--<img src=\"/esm/taig/www/content/web-logo.png\" style=\"background:black;padding:5px;width:380px\"/>-->\r\n                    <img src=\"/esm/taig/www/content/thks.png\" style=\"background-color: black;border-color:black;width:200px;border-radius: 100px;margin-top:-40px\">\r\n                </a>\r\n                <br/><br/>\r\n            </center>\r\n	<div class=\"login_box\" style=\"height:220px;top:0;bottom: 0;left: 0;right: 0;margin: auto;font-size:1.2em\">\r\n		\r\n		<form action=\"dashboard.html\" method=\"post\" id=\"login_form\">\r\n		\r\n			<% if flash[:error] %>\r\n			<div class=\"alert alert-info alert-login\">\r\n				<%= flash[:error] %>\r\n			</div>\r\n			<% else %>\r\n			<div class=\"alert alert-info alert-login\">\r\n				Please login to continue \r\n			</div>\r\n			<% end %>\r\n			\r\n			\r\n	   	\r\n\r\n			\r\n			<div class=\"cnt_b\">\r\n			\r\n					\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\" style=\"height:30px;padding:5px\"><i class=\"icon-user\"></i></span>\r\n						<%= form.text_field \"login\", :size => 20,:id=>\'user_login\',:placeholder=>\"Email or Login ID\",\'data-icon\'=>\"user\",:value=>user%>\r\n					   \r\n					</div>\r\n				</div>\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\" style=\"height:30px;padding:5px\"><i class=\"icon-lock\" ></i></span>\r\n						<%= form.password_field \"password\", :size => 20,:id=>\'user_password\',:placeholder=>\"Password\",\'data-icon\'=>\"closed-lock\"%>\r\n						\r\n					</div>\r\n				</div>\r\n					<%  unless @current_solution %>\r\n				<span id=\"solution_id_toggle\"><center><a href=\"javascript:$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\">...</a></center></span>	\r\n				<div class=\"formRow\" id=\"solution_id\" style=\"display:none\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-book\"></i></span>\r\n						<%= text_field_tag \"user[esm]\",cookies[:esm], :size => 20,:id=>\'esm\',:placeholder=>\"Solution ID\",\'data-icon\'=>\"settings\"%>\r\n					</div>\r\n				</div>\r\n				<script>\r\n				    $(document).ready(function(){\r\n				<% if cookies[:esm] %>\r\n					$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\r\n				<%  end %>\r\n			  });\r\n				</script>\r\n				\r\n					<% else %>\r\n						<%= form.hidden_field \"esm\", :value=> @current_solution.name %>\r\n						<%= form.hidden_field \"project_id\", :value=> @current_project.id if @current_project%>\r\n					<% end %>\r\n					\r\n					\r\n				<div class=\"formRow clearfix\">\r\n					<label class=\"checkbox\"><input id=\"ck\" name=\'remember\' type=\"checkbox\" /> Remember me</label>\r\n				</div>\r\n			</div>\r\n			<div class=\"btm_b clearfix\" >\r\n				<!--<button class=\"btn btn-inverse pull-right\" type=\"submit\">Sign In</button>-->\r\n				<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#disclaimer\" class=\"btn btn-inverse pull-right\">Sign In</a>\r\n				<span class=\"link_reg\"><a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#terms\">Disclaimer</a></span>\r\n				\r\n			</div>  \r\n			<div class=\"alert\" style=\"margin-top:10px;text-align:center\">\r\n    			    <span style=\"font-size:.7em;font-weight:400;\">Hosted by : </span>\r\n    			    <% if false %>\r\n    			    <a href=\"http://www.pgh.go.th\">\r\n    			        <img src=\'/esm/taig/www/content/lgpgh01.png\' height=\"30px\"/>\r\n    			        <img src=\'/esm/taig/www/content/ctc_logo_new.png\' height=\"30px\"/>\r\n    			    </a>\r\n    			    <% end %>\r\n    			    <a href=\'http://esm-solution.com\'>\r\n    			        <img src=\'/esm/thks_master/www/content/esm-solution.png\' height=\'30px\' />\r\n    			        <!--<img src=\'/esm/thks_master/www/content/emr-life_transparent.png\' height=\'30px\'/>-->\r\n    			    </a>\r\n			</div>\r\n		</form>\r\n		\r\n		\r\n                            <div class=\"modal hide\" id=\"disclaimer\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Disclaimer</h3>\r\n								</div>\r\n								<div class=\"modal-body\" style=\"font-size:10pt\">\r\nPRIVACY\