2.id%>.m3u8\">\r\n  <source src=\"<%=video2.path%>\" type=\"video/mp4\">\r\n    Your browser does not support the video tag.\r\n</video>\r\n\r\n<% end %>\r\n\r\n<% if video3 %>\r\n<h3>Video</h3>\r\n<video width=\"640\" height=\"480\" controls>\r\n  <source src=\"<%=\"/esm/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\"%><%=video3.id%>.m3u8\">\r\n  <source src=\"<%=video3.path%>\" type=\"video/mp4\">\r\n    Your browser does not support the video tag.\r\n</video>\r\n\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2016-07-25 01:22:42','2016-07-25 01:22:42','live_surgery_show',''),(2416,'export_csv',967,3,'<%\r\nrequire \'csv\'\r\n @document = get_document(this.document_name)\r\n\r\n model = get_model[this.document_name]\r\n \r\n list = model.all\r\n fields = @document.fields.collect{|i| i if i and i.column_name }.compact\r\n \r\n response.headers[\"Content-Type\"] = \"application/csv\"\r\n response.headers[\"Content-Disposition\"] = \"attachment;filename=export.csv\"\r\n \r\n csv_string = CSV.generate(:encoding=>\'utf-8\') do |csv|\r\n  csv << fields.collect{|i| i.column_name}\r\n  for i in list\r\n    csv << fields.collect{|j| i[j.column_name] }\r\n  end\r\n  # ...\r\nend\r\n \r\n %><%=csv_string%>\r\n',NULL,NULL,NULL,'2016-07-25 07:38:28','2016-07-25 07:38:28','export_csv',''),(2417,'document_name',993,1,'\'history\'',NULL,NULL,NULL,'2016-07-26 03:23:41','2016-07-26 03:23:41',NULL,NULL),(2418,'document_name',994,1,'\'post_operative\'',NULL,NULL,NULL,'2016-07-26 04:11:50','2016-07-26 04:11:50',NULL,NULL),(2419,'board',885,3,'<html>\r\n    <head>\r\n    <%=include_header%>\r\n        <style>\r\n            \r\n            body{\r\n                background-color:black;\r\n                color:#eee;\r\n            }\r\n            .block{\r\n                 padding:20px;\r\n                border:1px solid #666;\r\n                font-size:2em;\r\n            }\r\n            .processing-style{\r\n               \r\n                color:green;\r\n            }\r\n            .calling-style{\r\n             color:red;\r\n            }\r\n            .waiting-style{\r\n             color:gray;\r\n            }\r\n            \r\n        </style>\r\n    </head>\r\n    <body style=\"background-color:black;padding:20px\">\r\n        \r\n<%\r\n\r\n    models = get_model\r\n    \r\n    boardm = models[:scrollboard]\r\n    \r\n    board = boardm.where(:name=>params[:name]).first\r\n %>\r\n\r\n<div id=\"panel\">\r\n<center>Loading..</center>\r\n</div>\r\n\r\n\r\n<script>\r\n\r\nfunction update_board(){\r\n    $.ajax({\r\n    url: \"board_partial?name=<%=params[:name]%>\",\r\n    context: document.body\r\n    }).done(function(html) {\r\n\r\n  $( \'#panel\' ).html( html );\r\n});\r\n}\r\n\r\n\r\n    \r\n    setInterval (update_board, 3000 );\r\n    \r\n    update_board();\r\n\r\n\r\n</script>\r\n    </body>\r\n</html>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-07-27 03:03:00','2016-07-27 03:03:00','board',''),(2420,'form',993,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n    function cal_bmi() {\r\n        w = $(\'#data-bw\').val();\r\n        h = $(\'#data-ht\').val();\r\n        bmi = \'-\';\r\n        \r\n        if (w != \'\' && h != \'\') {\r\n            w = parseFloat(w);\r\n            h = parseFloat(h) / 100;\r\n            bmi = (w / (h * h)).toFixed(2);\r\n        }\r\n        \r\n        \r\n        $(\'#data-bmi\').val(bmi);\r\n    }\r\n    \r\n    $(document).ready(function() {\r\n        $(\'#data-bw\').change(cal_bmi);\r\n        $(\'#data-ht\').change(cal_bmi);\r\n    });\r\n</script>',NULL,NULL,NULL,'2016-07-27 04:40:48','2016-07-27 04:40:48','form',''),(2421,'board_partial',885,3,'\r\n        \r\n<%\r\n\r\n    models = get_model\r\n    \r\n    boardm = models[:scrollboard]\r\n    \r\n    board = boardm.where(:name=>params[:name]).first\r\n    \r\n    if board\r\n\r\n    wfs = []\r\n    if board.workflow==\'\'\r\n        \r\n    wfs = models[:workflow].sort(:sort_order).all\r\n    \r\n    else\r\n    list = board.workflow.split(\",\").collect{|i|i.strip}\r\n    wfs = models[:workflow].where(:name=>list).sort(:sort_order).all \r\n    end\r\n\r\n    wfs.compact!\r\n    \r\n    \r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    ap_model = models[:appointment]\r\n    date = Time.now \r\n    aps = ap_model.sort({updated_at:1}).all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    \r\n    status = {}\r\n    \r\n    \r\n   \r\n    patient_map = {}\r\n    \r\n    apms = module_model.where(:module_id=>aps.collect{|i| i.id }).all\r\n    apm_map = {}\r\n    for i in apms\r\n        apm_map[i.module_id] = i\r\n    end\r\n    \r\n    patients = patient_model.where(:id=>apms.collect{|i| i.patient_id}).all\r\n    for i in patients\r\n        patient_map[i.id] = i\r\n    end\r\n    \r\n    station_map = {}\r\n    models[:station].all.collect{|i| station_map[i.id] = i }\r\n    \r\n    \r\n    \r\n     for i in aps \r\n    \r\n        status[i.status.downcase]=[] unless status[i.status.downcase]\r\n        \r\n        x = {}\r\n        x[:ap] = i\r\n        x[:pm] = apm_map[i.id] if apm_map[i.id]\r\n        x[:patient] = patient_map[x[:pm].patient_id] if x[:pm]\r\n        x[:station] = station_map[i.station_id] if station_map[i.station_id]\r\n        status[i.status.downcase] << x\r\n    \r\n    end\r\n    \r\n%>\r\n<%=Time.now.to_s %><hr/>\r\n<div class=\"row-fluid\">\r\n\r\n<% wfs.each_with_index do |i,index| \r\n\r\n    processing = nil\r\n    calling = nil\r\n    \r\n%>\r\n\r\n<%=\"</div><div class=\'row-fluid\'>\".html_safe if index!=0 and index%3==0%>\r\n\r\n\r\n<div class=\"span4\">    \r\n    <%=i.name.humanize%>\r\n    <hr/>\r\n    <%\r\n        processing = status[i.processing_status]\r\n        if processing\r\n         for j in processing\r\n         patient = j[:patient]\r\n         ap = j[:ap]\r\n         s = j[:station]\r\n        \r\n    %>\r\n    \r\n   <div class=\"block processing-style\">  \r\n   <%=ap.queue_number %> : <%=patient.hn %> : <%=j[:station].name if s%>    \r\n  </div>    \r\n    <% end %>  \r\n    \r\n    <% end %>  \r\n    \r\n     <%\r\n        calling = status[i.calling_status]\r\n        if calling\r\n            for j in calling\r\n            patient = j[:patient]\r\n            ap = j[:ap]\r\n            s = j[:station]\r\n            \r\n            \r\n    %>\r\n   <div class=\"block calling-style\">  \r\n   <%=ap.queue_number %> : <%=patient.hn %> : <%=j[:station].name if s%>    \r\n  </div>\r\n    <% end %>   \r\n    <% end %>   \r\n    <%# i.in_bound_status.split(\",\") %>\r\n      <%\r\n        inbound = [] \r\n        i.in_bound_status.split(\",\").collect{|i| status[i.strip]}.compact.each do |x|\r\n        inbound += x    \r\n        end\r\n        if inbound\r\n            for j in inbound\r\n            patient = j[:patient]\r\n            ap = j[:ap]\r\n            s = j[:station]\r\n    %>\r\n    <div class=\"block waiting-style\"> \r\n    <%=ap.queue_number %>|<%=patient.hn %>|<%=j[:station].name if s%>     \r\n    </div>\r\n    <% end %>   \r\n    <% end %>    \r\n        \r\n    \r\n</div>\r\n\r\n<% end %>\r\n</div>\r\n<%# apms.inspect  %>\r\n<script>\r\n    (function blink() { \r\n    $(\'.calling-style\').fadeOut(1000).fadeIn(1000).delay(1000, blink); \r\n})();\r\n</script>\r\n<% end %>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-07-27 09:16:57','2016-07-27 09:16:57','board_partial',''),(2422,'barcode',953,3,'<%\r\n    models = get_model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    read = params[:read]\r\n    \r\n    app = models[:appointment].where(:appoint_number=>read).first\r\n    \r\n    if app\r\n        \r\n        \r\n        \r\n    %>\r\n    <script>\r\n      $(\'.clinic-btn\').addClass(\'disabled\')\r\n      $(\'#appoint-btn\').addClass(\'btn-success\');\r\n    </script>\r\n    <%\r\nelse\r\n    \r\n    \r\n    \r\n    patient = patient_model.where(\'$or\'=>[{:hn=>read},{:public_id=>read}]).first\r\n    \r\n%><%=Time.now%><br/><%=params.inspect %><br/>\r\n<% if patient \r\n\r\n    apm = module_model.where(:patient_id=>patient.id,:module_name=>\"\\\\#{@current_project.name}#appointment\").all\r\n    today = []\r\n    if apm.size>0\r\n       date = Time.now\r\n       today = models[:appointment].all(:id=>apm.collect{|i| i.module_id },:status=>\'Appointed\',:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    \r\n    end\r\n    \r\n    %>\r\n<script>\r\n    $(\'#patient_id\').val(\"<%=patient.id%>\")\r\n    $(\'#patient_prefix_name\').val(\"<%=patient.prefix_name%>\");\r\n    $(\'#patient_first_name\').val(\"<%=patient.first_name%>\");\r\n    $(\'#patient_last_name\').val(\"<%=patient.last_name%>\");\r\n    $(\'#hn\').val(\"<%=patient.hn%>\");\r\n    $(\'#public_id\').val(\"<%=patient.public_id%>\")\r\n    $(\'.patient\').prop(\'disabled\', true);\r\n</script>\r\n\r\n<% if today.size == 1 \r\n     today = today[0]\r\n     \r\n     proc = models[:procedure].find(today.procedure)\r\n    \r\n%>\r\n<h1> Has today appoint</h1>\r\n<%= today.inspect %>\r\n<script>\r\n    \r\n      $(\'.clinic-btn\').removeClass(\'btn-success\')\r\n      $(\'.clinic-btn\').addClass(\'disabled\')\r\n      $(\'#appoint-btn\').removeClass(\'disabled\')\r\n      $(\'#appoint-btn\').addClass(\'btn-success\');\r\n      \r\n      $(\'#procedure_code\').val(\'<%=proc.code%>\');\r\n     \r\n\r\n      \r\n</script>\r\n\r\n<% else %>\r\n<script>\r\n    $(\'.clinic-btn\').addClass(\'btn-success\');\r\n    $(\'#appoint-btn\').removeClass(\'btn-success\')\r\n    $(\'#appoint-btn\').addClass(\'disabled\');\r\n    $(\'.clinic-btn\').removeClass(\'disabled\')\r\n    $(\'#online-btn\').addClass(\'disabled\');\r\n    \r\n    \r\n</script>\r\n<% end %>\r\n<% else %>\r\n<script>\r\n    reset();\r\n</script>\r\n\r\n<% end %>\r\n<% end %>',NULL,NULL,NULL,'2016-07-28 02:40:20','2016-07-28 02:40:20','barcode',''),(2423,'create_patient',953,3,'<%\r\n    models = get_model \r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n\r\n    appm = models[:appointment]\r\n    \r\n    procedure_id = nil\r\n    \r\n    if params[:procedure] and params[:procedure]!=\'\'\r\n        procedure_id = models[:procedure].where(:code=>params[:procedure]).first.id   \r\n    end\r\n    \r\n       %>\r\n    <%= procedure_id.inspect %>\r\n        <%\r\n    patient_id = nil\r\n    \r\n    if params[:patient_id]==\"\"\r\n        patient = patient_model.create params[:patient]\r\n        %>\r\n        New Patient has been created;\r\n        <%\r\n    else   %>\r\n        Found Patient ;\r\n        <%\r\n        patient = patient_model.find params[:patient_id]\r\n    end\r\n    %>\r\n   <%=patient.inspect%>\r\n    <%\r\n    if  patient\r\n        number = appm.next_number\r\n        app = appm.create :date=>Time.now, :procedure=>procedure_id.to_s ,:status=>\'Arrived\',:appoint_number=>number\r\n        mapp = module_model.create  :module_id=>app.id, :patient_id=>patient.id.to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\"\r\n      %>\r\n        New Appointment has been created;\r\n        <meta http-equiv=\"refresh\" content=\"0; url=print_queue?id=<%=app.id%>\" />\r\n        <%\r\n   else\r\n\r\n%><meta http-equiv=\"refresh\" content=\"0; url=index\" />\r\n<%end%>\r\n\r\n',NULL,NULL,NULL,'2016-07-28 03:07:32','2016-07-28 03:07:32','create_patient',''),(2424,'next_number',952,3,'<%\r\n    models = get_model\r\n    model = models[:appointment]\r\n%>\r\n\r\n<%=model.next_number %>',NULL,NULL,NULL,'2016-07-28 13:09:10','2016-07-28 13:09:10','next_number',''),(2425,'print_queue_bk',953,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n    <style>\r\n        body{background:#333;}\r\n        .printpage{ padding:5px; -moz-border-radius: 5px;border-radius: 5px; background:#FFF; width:300px; margin-left:auto; margin-right:auto; text-align:center}\r\n@media print {\r\n .printpage{ padding:0px; margin:0px; margin-left:auto; margin-right:auto;width:300px; height:200px;}\r\n body{background:#fff;}\r\n}        \r\n        \r\n    </style>\r\n</head>\r\n<body>\r\n<%\r\n\r\n    date = Time.now \r\n    \r\n    \r\n    models = get_model\r\n    \r\n    app = models[:appointment].find(params[:id])\r\n    max = models[:appointment].where(:_id=>{\'$ne\'=>app.id},:queue_number=>{\'$ne\'=>nil},:procedure=>app.procedure,:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day).all.collect{|i| i.queue_number[1..-1].to_i}.max\r\n    procedure = models[:procedure].find(app.procedure)\r\n    \r\n    cm = {\'travel\'=>\'A\',\'toxin\'=>\'C\',\'rabies\'=>\'B\'}\r\n    c = \'\'\r\n    c = cm[procedure[:code]]\r\n    max = 0 unless max\r\n    app.update_attributes :queue_number=> \"\\\\#{c}\\\\#{format(\'%03d\',max+1)}\", :status=>\'Arrived\'\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    apm = module_model.where(:module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>app.id).first\r\n    pat = patient_model.find(apm[:patient_id])\r\n%>\r\n<div class=\"printpage\">\r\n<h2>สถานเสาภา</h2><hr />\r\n<br />\r\n<h2><%= app.queue_number %></h2>\r\n<br /><br />\r\n<%= app.date %><br />\r\n<%= \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]} \\\\#{pat[:last_name]} \"%>นอน<br />\r\n<%= pat[:hn] %><br />\r\n<%= app.status %><br />\r\nrabies Clinic<hr />\r\n\r\nสถานเสาวภา สภากาชาดไทย <br />\r\n1871 ถนนพระราม 4 เขตปทุมวัน กทม. 10330 <br />\r\n\r\n</div>\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-07-28 13:32:33','2016-07-28 13:32:33','print_queue_bk',''),(2426,'export',952,3,'\r\n<%\r\n\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n\r\n  @document = get_document(this.document_name)\r\n\r\n  doc = @document\r\n\r\n  data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n  \r\n   fields = @document.fields\r\n   fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n   fields << \'created_at\'\r\n   fields << \'updated_at\'\r\n%>\r\n<table>\r\n<tr><td>ID</td><td>HN</td><td>Name</td><td>Gender</td><td>Birth Date</td><td>Age</td><td>Record date</td>\r\n\r\n<%\r\nfor i in fields \r\n%><td><%= i[1] %></td>\r\n<% end %>\r\n</tr>\r\n<% for i in data \r\n\r\n     @record = i\r\n\r\n    age = 0\r\n    hn = nil\r\n    \r\n    p = @patient_model.new\r\n    m = @module_model.collection.find(:module_id=>i.id).first\r\n    if m \r\n    \r\n    patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n    if patient\r\n    bdate = 0\r\n    bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n    age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n   \r\n    p = patient\r\n    p[\'record_date\'] = m[\'date\']\r\n    \r\n    end\r\n   end\r\n    \r\n    \r\n%>\r\n<tr><td><%=i.id %></td>\r\n<td><%=p[\'hn\'] %></td><td><%=p[\'first_name\']%> <%=p[\'last_name\']%></td><td><%=p[\'gender\']%></td><td><%=p[\'birth_date\'].strftime(\'%d/%m/%Y\') if p[\'birth_date\'] %></td><td><%=age%></td><td><%=p[\'record_date\'].strftime(\'%d/%m/%Y\') if p[\'record_date\']%></td>\r\n\r\n<%\r\n    @document = doc\r\n    @fields = @document.fields\r\n    \r\n    for j in fields \r\n    \r\n    if i[j[0]]\r\n%>\r\n<td><%= render_value j[0] %></td>\r\n<% else %>\r\n<td>.</td>\r\n<% end %>\r\n<% end %>\r\n</tr>\r\n<% end %>\r\n</table>\r\n  \r\n  \r\n   \r\n   \r\n   ',NULL,NULL,NULL,'2016-07-28 13:55:42','2016-07-28 13:55:42','export',''),(2427,'print',953,3,'<html>\r\n<style>\r\n    .print {width:300px; margin-left:auto; margin-right:auto;background:#fff;}\r\n</style>\r\n    <body style=\"background:#ccc\">\r\n    <div class=\"print\">\r\n        <h2>Header</h2>\r\n        <hr />\r\n        \r\n    </div>\r\n        \r\n    </body>\r\n    \r\n</html>',NULL,NULL,NULL,'2016-07-28 14:46:34','2016-07-28 14:46:34','print',''),(2428,'case_record2',909,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    \r\n    is_update = false # update\r\n    is_1 = false # reupdate day 1\r\n    is_last = false # reupdate last day\r\n    if params[:act] == \'update\'\r\n        is_update = true\r\n    end\r\n    if params[:act] == \'day1\'\r\n        is_1 = true\r\n    end\r\n    if params[:act] == \'last\'\r\n        is_last = true\r\n    end\r\n    \r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    \r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = [] # all parent_id\r\n    pat_ids = [] # all patient_id\r\n    app_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    # begin\r\n    # a_pat = a_pat.sort_by{|i| i[:patient_order] if i[:patient_order]}\r\n    a_pat = a_pat.sort{|a,b| a[:patient_order] && b[:patient_order] ? a[:patient_order] <=> b[:patient_order] : a[:patient_order] ? -1 : 1 }\r\n    \r\n    # query patient_module <-> aki\r\n    mod_aki = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#aki\")\r\n    i_aki = []\r\n    p_aki = {}\r\n    mod_aki.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_aki << mid\r\n        if !p_aki.has_key? pid\r\n            p_aki[pid] = []\r\n        end\r\n        p_aki[pid] << mid\r\n    end\r\n    m_aki = {}\r\n    a_aki = get_model[:aki].find(i_aki)\r\n    a_aki.each do |i|\r\n        m_aki[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> case_record\r\n    mod_case = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#case_record\")\r\n    i_case = []\r\n    p_case = {}\r\n    mod_case.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_case << mid\r\n        if !p_case.has_key? pid\r\n            p_case[pid] = []\r\n        end\r\n        p_case[pid] << mid\r\n    end\r\n    m_case = {}\r\n    a_case = get_model[:case_record].find(i_case)\r\n    a_case.each do |i|\r\n        m_case[i.id] = i\r\n    end\r\n    \r\n    # selecting I/O\r\n    hosp_name = @current_solution.name\r\n    io = 24 \r\n    # tm = patient[:time_of_icu_admission].strftime(\'%H\').to_i\r\n    tm_00 = [\"rrts_14\", \"rrts_21\"];\r\n    tm_06 = [\"rrts_1\", \"rrts_3\", \"rrts_4\", \"rrts_7\", \"rrts_9\", \"rrts_19\", \"rrts_23\", \"rrts_26\", \"rrts_27\"];\r\n    tm_07 = [\"rrts_6\", \"rrts_17\"];\r\n    tm_22 = [\"rrts_5\"];\r\n    tm_23 = [\"rrts_2\", \"rrts_11\", \"rrts_12\", \"rrts_13\", \"rrts_15\", \"rrts_16\"];\r\n        \r\n    if !tm_00.index(hosp_name).nil?\r\n        io = 0\r\n    elsif !tm_06.index(hosp_name).nil?\r\n        io = 6\r\n    elsif !tm_07.index(hosp_name).nil?\r\n        io = 7\r\n    elsif !tm_22.index(hosp_name).nil?\r\n        io = 22\r\n    elsif !tm_23.index(hosp_name).nil?\r\n        io = 23\r\n    else\r\n        io = 6\r\n    end\r\n    \r\n    # processing\r\n    res = []\r\n    pf = %w{patient_number patient_order gender weight height ideal_body_weight age date_of_admission date_of_icu_admission time_of_icu_admission ckd esrd reference baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr first_available_cr_date}\r\n#	0	patient_number\r\n#	1	patient_order\r\n#	2	gender\r\n#	3	weight\r\n#	4	height\r\n#	5	ideal_body_weight\r\n#	6	age\r\n#	7	reference\r\n#	8	date_of_admission\r\n#	9	date_of_icu_admission\r\n#	10	time_of_icu_admission\r\n#	11	ckd\r\n#	12	esrd\r\n#	13	baseline_serum_creainine_by_mdrd\r\n#	14	available_baseline\r\n#	15	baseline_serum_cr\r\n#	16	date_of_baseline_serum_cr\r\n#	17	first_available_cr\r\n#	18	first_available_cr_date\r\n    dd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    cf = %w{urine_output_cal record_day case_status move_out_time creatinine urine_output24hr if_rrt}\r\n#	0	record_day\r\n#	1	case_status\r\n#	2	move_out_time\r\n#	3	creatinine\r\n#	4	urine_output24hr\r\n#	5	urine_output_cal\r\n#	6	if_rrt\r\n    af = %w{cr_diagnosis cr_diagnosis_from_day cr_staging cr_staging_from_day urine_output_diagnosis urine_output_from_day urine_output_staging urine_output_staging_from_day}\r\n#	0	cr_diagnosis\r\n#	1	cr_diagnosis_from_day\r\n#	2	cr_staging\r\n#	3	cr_staging_from_day\r\n#	4	urine_output_diagnosis\r\n#	5	urine_output_from_day\r\n#	6	urine_output_staging\r\n#	7	urine_output_staging_from_day\r\n\r\n    # using field\r\n    uf = {\r\n        \'1\'=>{:f=>:baseline_serum_cr,:d=>:date_of_baseline_serum_cr}, \r\n        \'2\'=>{:f=>:first_available_cr,:d=>:first_available_cr_date}, \r\n        \'3\'=>{:f=>:baseline_serum_creainine_by_mdrd,:d=>:date_of_icu_admission}\r\n    }\r\n    \r\n    # for each patient\r\n    a_pat.each do |pat|\r\n        tmp = {}\r\n        msg = []\r\n        if pat.nil?\r\n            next\r\n        end\r\n        \r\n        pp = {}\r\n        pf.each do |i|\r\n            pp[i.to_sym] = pat[i.to_sym]\r\n        end\r\n        \r\n        # recheck urine output from case_record\r\n        cid_list = []\r\n        if xx = p_case[pat.id]\r\n            xx.each do |i|\r\n                cid_list << m_case[i]\r\n            end\r\n        else\r\n            msg << \"xx found\"\r\n        end\r\n        \r\n        # mapping day <--> case_record\r\n        mc = {}\r\n        cid_list.each do |i|\r\n            rd = i[:record_day]\r\n            if rd==\'\'\r\n                msg << \'empty rd\'\r\n            end\r\n            if !mc.has_key? rd\r\n                mc[rd] = i\r\n            else\r\n                msg << \"dup rd[\\\\#{rd}]\"\r\n            end\r\n        end\r\n        \r\n        # checking aki is created ?\r\n        is_aki = false\r\n        aid_list = []\r\n        if xx = p_aki[pat.id]\r\n            xx.each do |i|\r\n                aid_list << m_aki[i]\r\n            end\r\n            is_aki = true\r\n        else\r\n            msg << \"NO AKI\"\r\n        end\r\n        \r\n        # assign aki\r\n        r_aki = nil\r\n        if is_aki\r\n            r_aki = aid_list[0]\r\n        end\r\n        \r\n        pp[:time_of_icu_admission] = pp[:time_of_icu_admission].strftime(\'%H:%M\')\r\n        ti = Time.parse(pp[:time_of_icu_admission])\r\n        \r\n        # temporary aki diag\r\n        ta = {:aki=>\'No\'}\r\n        af.each do |i|\r\n            if !i.include? \'day\'\r\n                ta[i.to_sym] = \'0\'\r\n            else\r\n                ta[i.to_sym] = \'\'\r\n            end\r\n        end\r\n        # number of record_day\r\n        nrd = cid_list.count\r\n        # weight that used to calculate\r\n        calw = 0\r\n        begin \r\n            calw = pp[:weight].to_i\r\n        rescue\r\n            calw = pp[:ideal_body_weight].to_i\r\n            msg << \'no weight found\'\r\n        end\r\n        pp[:num_of_record_day] = nrd\r\n        \r\n        rc, df = nil\r\n        if pp[:esrd].downcase == \'no\' or pp[:esrd] == \'\'\r\n            pp[:esrd] = \'No\'\r\n            # get reference\r\n            ref = pp[:reference]\r\n            ref_field = uf[ref][:f]\r\n            ref_date  = uf[ref][:d]\r\n            # reference cr\r\n            rc = pp[ref_field].to_f\r\n            # reference date\r\n            begin \r\n                rd = Date.strptime(pp[ref_date].to_s,  \'%Y-%m-%d\')\r\n            rescue\r\n                rd = Date.strptime(pp[:date_of_icu_admission].to_s,  \'%Y-%m-%d\')\r\n                msg << \"err-rd[\\\\#{pp[ref_date]}]\"\r\n            end\r\n            # rd = pp[ref_date]\r\n            # date of icu\r\n            ri = Date.strptime(pp[:date_of_icu_admission].to_s, \'%Y-%m-%d\')\r\n            # ri = pp[:date_of_icu_admission]\r\n            # calculate difference between date_of_icu_admission and date_of_cr \r\n            df = (rd-ri).to_i\r\n            # msg << rd\r\n            # msg << ri\r\n            # msg << (ri - rd)\r\n        end\r\n        \r\n        if !mc.empty?\r\n            \r\n            # df=0\r\n            x_list = []\r\n            dd.each do |i|\r\n                if !mc[i].nil?\r\n                    x_list << i\r\n                end\r\n            end\r\n            l_day = x_list.last\r\n            \r\n            r2d = rc\r\n            r7d = rc\r\n            dd.each do |i|\r\n                \r\n                v = \'-\'\r\n	            if !mc[i].nil?\r\n	                k = \"d\\\\#{i}_urine_output_cal_new\"\r\n	                v = \'NA\'\r\n	                hh = 24\r\n	                \r\n	                if mc[i][:urine_output24hr].downcase == \'na\' or mc[i][:urine_output24hr].downcase == \'n/a\' or mc[i][:urine_output24hr].downcase == \'nan\' or mc[i][:urine_output24hr].strip == \'\'\r\n	                    ur = mc[i][:urine_output24hr]\r\n	                else\r\n                        l_day_move_out = true\r\n                        ur = mc[i][:urine_output24hr].to_i\r\n                        \r\n                        if i == \'1\'\r\n                            tx = Time.parse(\"\\\\#{io}:00\")\r\n                            if mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\'\r\n                                tx = Time.parse(mc[i][:move_out_time].strftime(\'%H:%M\'))\r\n                            end\r\n                                    \r\n                            hh = ((tx - ti)/3600).round(2) # make time in hour\r\n                            if hh <= 0\r\n                                hh = 24 + hh\r\n                            end\r\n                        elsif  i == l_day\r\n                            to = Time.parse(\"\\\\#{io}:00\") \r\n                            if mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\' and !mc[i][:move_out_time].nil?\r\n                                tx = Time.parse(mc[i][:move_out_time].strftime(\'%H:%M\'))\r\n                                hh = ((tx - to)/3600).round(2)\r\n                                if hh <= 0\r\n                                    hh = 24 +  hh\r\n                                end\r\n                            elsif mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\' and mc[i][:move_out_time].nil?\r\n                                l_day_move_out = false\r\n                            end\r\n                        end\r\n                                \r\n                        \r\n                        # v = ur != 0 ? (ur/calw.to_f/hh).round(4) : 0\r\n                        v = l_day_move_out ? (ur / calw.to_f / hh).round(4) : \'NA\'\r\n                        # pp[k.to_sym] = v\r\n                        \r\n	                end\r\n	                \r\n	                pp[k.to_sym] = \"v=\\\\#{v} [\\\\#{ur}/\\\\#{calw}/\\\\#{hh}]\"\r\n	                pp[k.to_sym] = v\r\n	                if is_1\r\n                        mc[i].update_attributes :urine_output_cal=> v, :note=>\"old_urine_output_cal: \\\\#{mc[i][:urine_output_cal]}\"\r\n                    end\r\n                    if is_update\r\n                        mc[i].update_attributes :urine_output_cal=> v, :note=>\"old_urine_output_cal: \\\\#{mc[i][:urine_output_cal]}\"\r\n                    end\r\n                    if is_last\r\n                        mc[i].update_attributes :urine_output_cal=> v, :note=>\"old_urine_output_cal: \\\\#{mc[i][:urine_output_cal]}\"\r\n                    end\r\n	                \r\n	                \r\n	                if false\r\n                	ur = mc[i][:urine_output24hr].to_i\r\n                    hh = 24\r\n                    if i == \'1\'\r\n                        tx = Time.parse(\"\\\\#{io}:00\")\r\n                        if mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\'\r\n                            tx = Time.parse(mc[i][:move_out_time].strftime(\'%H:%M\'))\r\n                        end\r\n                                    \r\n                        hh = ((tx - ti)/3600).round(2) # make time in hour\r\n                        if hh <= 0\r\n                            hh = 24 + hh\r\n                        end\r\n                    end\r\n                                \r\n                    k = \"d\\\\#{i}_urine_output_cal_new\"\r\n                    v = ur != 0 ? (ur/calw.to_f/hh).round(4) : 0\r\n                    pp[k.to_sym] = v\r\n                    pp[k.to_sym] = \"v=\\\\#{v} [\\\\#{ur}/\\\\#{calw}/\\\\#{hh}]\"\r\n                                \r\n                    if is_1\r\n                        mc[i].update_attributes :urine_output_cal=> v, :note=>\"old_urine_output_cal: \\\\#{mc[i][:urine_output_cal]}\"\r\n                    elsif is_last\r\n                        mc[i].update_attributes :urine_output_cal=> v, :note=>\"old_urine_output_cal: \\\\#{mc[i][:urine_output_cal]}\"\r\n                    end\r\n                    end # if false            \r\n                end\r\n\r\n            end # end dd\r\n            \r\n            \r\n            #  query each field from case record\r\n            cf.each do |j|\r\n                dd.each do |i|\r\n                    k = \"d\\\\#{i}_\\\\#{j}\"\r\n                    v = !mc[i].nil? ? mc[i][j.to_sym] : \'-\'\r\n                    if j.to_s == \'move_out_time\'\r\n                        if !mc[i].nil?\r\n                            if mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\'\r\n                                begin\r\n                                v = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                rescue\r\n                                v = \"00:00na\"\r\n                                msg << \"time:\\\\#{mc[i][j.to_sym]}.\"\r\n                                end\r\n                            else\r\n                                v = \'-\'\r\n                            end\r\n                        end\r\n                    end\r\n                    pp[k.to_sym] = v\r\n                    \r\n                end # end dd\r\n            end # end cf\r\n        end  \r\n\r\n        if is_update\r\n            \r\n        end\r\n        \r\n        pp[:note] = \"\\\\#{pp[:note]},\\\\#{msg.join(\',\')}\"\r\n        \r\n        pp = pp.merge(ta)\r\n        res << pp\r\n    end\r\n    \r\n    lbl = %w{patient_number patient_order gender weight height ideal_body_weight age reference date_of_admission date_of_icu_admission time_of_icu_admission ckd esrd baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr first_available_cr_date}\r\n    lbl = pf\r\n    lbl << \"num_of_record_day\"\r\n    fx = [\'urine_output_cal_new\', \'urine_output_cal\', \'urine_output24hr\', \'creatinine\']\r\n    fx = [\'urine_output_cal_new\'] + cf\r\n    fx.each do |i|\r\n        dd.each do |j|\r\n            lbl << \"d\\\\#{j}_\\\\#{i}\"\r\n        end\r\n    end\r\n    # lbl << \"aki\"\r\n    # lbl = lbl + af\r\n        \r\n    \r\n    # result assign\r\n    display = \'table\'\r\n    if params[:type] == \'csv\'\r\n        display = \'csv\'\r\n    elsif params[:type] == \'xls\'\r\n        display = \'xls\'\r\n    elsif params[:type] == \'json\'\r\n        display = \'json\'\r\n    end\r\n    \r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    # rs[:app_par] = app_par\r\n    # rs[:mod_par] = mod_par\r\n\r\n    if display == \'json\'\r\n        rs[:all_patient] = a_pat.count\r\n        # rs[:patient_1] = a_pat[1]\r\n        # rs[:all_aki] = a_aki.count\r\n        # rs[:all_case_record] = a_case.count\r\n        rs[:result] = res.count\r\n        rs[:time] = Time.now - tb\r\n%>\r\n\r\n<%= rs.to_json.html_safe %>\r\n\r\n<%\r\n    elsif display == \'table\'\r\n        # ff = res[0].keys\r\n        ff = lbl.collect{|i| i.to_sym}\r\n%>\r\n\r\n<%= stylesheet_link_tag    \"application\"  %>\r\n<h3>Using I/O Cut at <%= io %>:00</h3>\r\n<h3>Total Patient = <%= a_pat.count %></h3>\r\nquery time = <%= Time.now - tb %>\r\n<div style=\'\'>\r\n    <%= link_to \'Confirm\', \"\\\\#{params[:opt]}?act=update\", :class=>\'btn btn-success\' %> | \r\n    <%= link_to \'Day 1\', \"\\\\#{params[:opt]}?act=day1\", :class=>\'btn btn-info\' %> |\r\n    <%= link_to \'Last day\', \"\\\\#{params[:opt]}?act=last\", :class=>\'btn btn-info\' %>\r\n</div>\r\n\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n<% ff.each do |i| %>\r\n        <th><%= i %></th>\r\n<% end %>        \r\n    </tr>\r\n<% \r\n        res.each do |i| \r\n%>\r\n    <tr>\r\n        <% ff.each do |j| %>\r\n        <% if j.to_s != \'case\' %>\r\n        <td><%= i[j] %></td>\r\n        <% else %>\r\n        <!--<td/>-->\r\n        <td><%= i[j] %></td>\r\n        <% end %>\r\n        <% end %>\r\n    </tr>\r\n<% end %>\r\n</table>\r\n\r\nProcessing time = <%= Time.now - tb %>\r\n\r\n<%\r\n    elsif display == \'csv\'\r\n        require \'csv\'\r\n    \r\n        response.headers[\"Content-Type\"] = \"text/csv\"\r\n        response.headers[\"Content-disposition\"] = \"attachment; filename=\\\\#{this.document_name}-\\\\#{params[:solution_name]}-\\\\#{Time.now.to_i}.csv\"\r\n        \r\n        ff = res[0].keys\r\n        \r\n        xxx = CSV.generate do |csv|\r\n            \r\n            csv << ff\r\n            tmp = []\r\n            res.each do |i|\r\n                ff.each do |j|\r\n                    tmp << i[j]\r\n                end\r\n                csv << tmp\r\n            end\r\n      \r\n        end\r\n%>\r\n<%= xxx.html_safe %>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2016-07-28 15:21:40','2016-07-28 15:21:40','case_record2','*'),(2429,'aki2',909,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    \r\n    is_update = false # update\r\n    if params[:act] == \'update\'\r\n        is_update = true\r\n    end\r\n    \r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n    \r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = [] # all parent_id\r\n    pat_ids = [] # all patient_id\r\n    app_par = {}\r\n    pat_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n        pat_par[i[:patient_id]] = i.id.to_s\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    # begin\r\n    # a_pat = a_pat.sort_by{|i| i[:patient_order] if i[:patient_order]}\r\n    a_pat = a_pat.sort{|a,b| a[:patient_order] && b[:patient_order] ? a[:patient_order] <=> b[:patient_order] : a[:patient_order] ? -1 : 1 }\r\n    \r\n    # query patient_module <-> aki\r\n    mod_aki = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#aki\")\r\n    i_aki = []\r\n    p_aki = {}\r\n    mod_aki.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_aki << mid\r\n        if !p_aki.has_key? pid\r\n            p_aki[pid] = []\r\n        end\r\n        p_aki[pid] << mid\r\n    end\r\n    m_aki = {}\r\n    a_aki = get_model[:aki].find(i_aki)\r\n    a_aki.each do |i|\r\n        m_aki[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> case_record\r\n    mod_case = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#case_record\")\r\n    i_case = []\r\n    p_case = {}\r\n    mod_case.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_case << mid\r\n        if !p_case.has_key? pid\r\n            p_case[pid] = []\r\n        end\r\n        p_case[pid] << mid\r\n    end\r\n    m_case = {}\r\n    a_case = get_model[:case_record].find(i_case)\r\n    a_case.each do |i|\r\n        m_case[i.id] = i\r\n    end\r\n    \r\n    # selecting I/O\r\n    hosp_name = @current_solution.name\r\n    io = 24 \r\n    # tm = patient[:time_of_icu_admission].strftime(\'%H\').to_i\r\n    tm_00 = [\"rrts_14\", \"rrts_21\"];\r\n    tm_06 = [\"rrts_1\", \"rrts_3\", \"rrts_4\", \"rrts_7\", \"rrts_9\", \"rrts_19\", \"rrts_23\", \"rrts_26\", \"rrts_27\"];\r\n    tm_07 = [\"rrts_6\", \"rrts_17\"];\r\n    tm_22 = [\"rrts_5\"];\r\n    tm_23 = [\"rrts_2\", \"rrts_11\", \"rrts_12\", \"rrts_13\", \"rrts_15\", \"rrts_16\"];\r\n        \r\n    if !tm_00.index(hosp_name).nil?\r\n        io = 0\r\n    elsif !tm_06.index(hosp_name).nil?\r\n        io = 6\r\n    elsif !tm_07.index(hosp_name).nil?\r\n        io = 7\r\n    elsif !tm_22.index(hosp_name).nil?\r\n        io = 22\r\n    elsif !tm_23.index(hosp_name).nil?\r\n        io = 23\r\n    else\r\n        io = 6\r\n    end\r\n    \r\n    # processing\r\n    res = []\r\n    pf = %w{patient_number patient_order gender weight height ideal_body_weight age date_of_admission date_of_icu_admission time_of_icu_admission ckd esrd reference baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr first_available_cr_date}\r\n#	0	patient_number\r\n#	1	patient_order\r\n#	2	gender\r\n#	3	weight\r\n#	4	height\r\n#	5	ideal_body_weight\r\n#	6	age\r\n#	7	reference\r\n#	8	date_of_admission\r\n#	9	date_of_icu_admission\r\n#	10	time_of_icu_admission\r\n#	11	ckd\r\n#	12	esrd\r\n#	13	baseline_serum_creainine_by_mdrd\r\n#	14	available_baseline\r\n#	15	baseline_serum_cr\r\n#	16	date_of_baseline_serum_cr\r\n#	17	first_available_cr\r\n#	18	first_available_cr_date\r\n    dd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    cf = %w{urine_output_cal record_day case_status move_out_time creatinine urine_output24hr if_rrt}\r\n#	0	record_day\r\n#	1	case_status\r\n#	2	move_out_time\r\n#	3	creatinine\r\n#	4	urine_output24hr\r\n#	5	urine_output_cal\r\n#	6	if_rrt\r\n    af = %w{cr_diagnosis cr_diagnosis_from_day cr_staging cr_staging_from_day urine_output_diagnosis urine_output_from_day urine_output_staging urine_output_staging_from_day auto_max_staging aki_max_staging aki_max_staging_from}\r\n#	0	cr_diagnosis\r\n#	1	cr_diagnosis_from_day\r\n#	2	cr_staging\r\n#	3	cr_staging_from_day\r\n#	4	urine_output_diagnosis\r\n#	5	urine_output_from_day\r\n#	6	urine_output_staging\r\n#	7	urine_output_staging_from_day\r\n\r\n    # using field\r\n    uf = {\r\n        \'1\'=>{:f=>:baseline_serum_cr,:d=>:date_of_baseline_serum_cr}, \r\n        \'2\'=>{:f=>:first_available_cr,:d=>:first_available_cr_date}, \r\n        \'3\'=>{:f=>:baseline_serum_creainine_by_mdrd,:d=>:date_of_icu_admission}\r\n    }\r\n    \r\n    e_ur = 0\r\n    e_ur_pat_list = []\r\n    # for each patient\r\n    a_pat.each do |pat|\r\n        tmp = {}\r\n        msg = []\r\n        if pat.nil?\r\n            next\r\n        end\r\n        \r\n        pp = {}\r\n        pf.each do |i|\r\n            pp[i.to_sym] = pat[i.to_sym]\r\n        end\r\n        \r\n        # recheck urine output from case_record\r\n        cid_list = []\r\n        if xx = p_case[pat.id]\r\n            xx.each do |i|\r\n                cid_list << m_case[i]\r\n            end\r\n        else\r\n            msg << \"xx found\"\r\n        end\r\n        \r\n        # mapping day <--> case_record\r\n        mc = {}\r\n        cid_list.each do |i|\r\n            rd = i[:record_day]\r\n            if rd==\'\'\r\n                msg << \'empty rd\'\r\n            end\r\n            if !mc.has_key? rd\r\n                mc[rd] = i\r\n            else\r\n                msg << \"dup rd[\\\\#{rd}]\"\r\n            end\r\n        end\r\n        \r\n        # checking aki is created ?\r\n        is_aki = false\r\n        aid_list = []\r\n        if xx = p_aki[pat.id]\r\n            xx.each do |i|\r\n                aid_list << m_aki[i]\r\n            end\r\n            is_aki = true\r\n        else\r\n            msg << \"NO AKI\"\r\n        end\r\n        \r\n        # assign aki\r\n        r_aki = nil\r\n        if is_aki\r\n            r_aki = aid_list[0]\r\n        end\r\n        \r\n        # begin\r\n            pp[:time_of_icu_admission] = pp[:time_of_icu_admission].strftime(\'%H:%M\')\r\n            ti = Time.parse(pp[:time_of_icu_admission])\r\n        # rescue\r\n        #     ti = Time.parse(\'00:00\')\r\n        #     msg << \'TIME ASSIGN = 00:00\'\r\n        # end\r\n        \r\n        # temporary aki diag\r\n        ta = {:aki=>\'No\'}\r\n        af.each do |i|\r\n            if !i.include? \'day\'\r\n                ta[i.to_sym] = \'0\'\r\n            else\r\n                ta[i.to_sym] = \'\'\r\n            end\r\n        end\r\n        # number of record_day\r\n        nrd = cid_list.count\r\n        # weight that used to calculate\r\n        calw = 0\r\n        begin \r\n            calw = pp[:weight].to_i\r\n        rescue\r\n            calw = pp[:ideal_body_weight].to_i\r\n            msg << \'no weight found\'\r\n        end\r\n        pp[:num_of_record_day] = nrd\r\n        # pp[:case] = cid_list.sort_by{|i| i[:record_day].to_i}\r\n        # pp[:d1_num] = pp[:case].collect{|i| i[:record_day].to_i}\r\n        # pp[:d1_cr]  = pp[:case].collect{|i| i[:creatinine]}\r\n        # pp[:d1_out24] = pp[:case].collect{|i| i[:urine_output24hr]}\r\n        # pp[:d1_urine] = pp[:case].collect{|i| i[:urine_output_cal]}\r\n        # pp[:d1_rrt] = pp[:case].collect{|i| i[:if_rrt]}\r\n        if !mc.empty?\r\n            # pp[:case] = mc\r\n            \r\n            aki_2d = []\r\n            aki_7d = []\r\n            ur_list = []\r\n            \r\n            x_list = []\r\n            dd.each do |i|\r\n                if !mc[i].nil?\r\n                    x_list << i\r\n                end\r\n            end\r\n            l_day = x_list.last\r\n            \r\n            ### AKI Diagnosis and Calculation\r\n            rc, df = nil\r\n            if pp[:esrd].downcase == \'no\' or pp[:esrd] == \'\'\r\n                pp[:esrd] = \'No\'\r\n                # get reference\r\n                ref = pp[:reference]\r\n                ref_field = uf[ref][:f]\r\n                ref_date  = uf[ref][:d]\r\n                # reference cr\r\n                rc = pp[ref_field].to_f\r\n                # reference date\r\n                begin \r\n                    rd = Date.strptime(pp[ref_date].to_s,  \'%Y-%m-%d\')\r\n                rescue\r\n                    rd = Date.strptime(pp[:date_of_icu_admission].to_s,  \'%Y-%m-%d\')\r\n                    msg << \"err-rd[\\\\#{pp[ref_date]}]\"\r\n                end\r\n                # rd = pp[ref_date]\r\n                # date of icu\r\n                ri = Date.strptime(pp[:date_of_icu_admission].to_s, \'%Y-%m-%d\')\r\n                # ri = pp[:date_of_icu_admission]\r\n                # calculate difference between date_of_icu_admission and date_of_cr \r\n                df = (rd-ri).to_i\r\n                # msg << rd\r\n                # msg << ri\r\n                # msg << (ri - rd)\r\n            end\r\n            \r\n            # df=0\r\n            # x_list = []\r\n            # dd.each do |i|\r\n            #     if !mc[i].nil?\r\n            #         x_list << i\r\n            #     end\r\n            # end\r\n            # l_day = x_list.last\r\n            msg_txt = \'-\'\r\n            r2d = rc\r\n            r7d = rc\r\n            d_list = []\r\n            dd.each do |i|\r\n                \r\n                # condition to find AKI\r\n                if pp[:esrd].downcase == \'no\' and !mc[i].nil?\r\n                    # if mc[i][:creatinine].downcase != \'na\' and mc[i][:creatinine].downcase != \'nan\' and mc[i][:creatinine].downcase != \'n/a\'\r\n                    d = i.to_i\r\n                    d_list << d\r\n                    cc = mc[i][:creatinine].downcase\r\n                    dcr = 0\r\n                    if cc != \'na\' and cc != \'nan\' and cc != \'n/a\' and cc != \'\'\r\n                        if cc.to_f >= 4.0 and ta[:cr_staging] != \'3\'\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n                                ta[:cr_staging] = \'3\'\r\n                                ta[:cr_staging_from_day] = i\r\n                                ta[:aki] = \'Yes\'\r\n                        end\r\n                        if d == 1 and (df >= -2 and df < 0)\r\n                            dcr = (cc.to_f - rc).round(4)\r\n                            aki_2d << {:dx=>\'1\',:dr=>\'0\',:dd=>i,:df=>df,:v=>dcr,:cn=>\'2d\',:cc=>cc,:cr=>rc}\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'1\',:dd=>i,:df=>df,:v=>(cc.to_f / rc.to_f).round(4),:cn=>\'7d\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                                    ta[:cr_diagnosis] = \'1\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                        # elsif d == 1 and (df >= -7 and df < 0)\r\n                        elsif d == 1\r\n                            dcr = (cc.to_f / rc).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'0\',:dd=>i,:df=>df,:v=>dcr,:cn=>\'7d\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                    ta[:cr_diagnosis] = \'2\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                        elsif d == 2\r\n                            c1 = mc[(d - 1).to_s][:creatinine].downcase\r\n                            if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                dcr = (cc.to_f - c1.to_f).round(4)\r\n                                aki_2d << {:dx=>\'1\',:dr=>\'1\',:dd=>i,:df=>1,:v=>dcr,:cn=>\'2d\',:cc=>cc,:cr=>c1}\r\n                                if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                                    ta[:cr_diagnosis] = \'1\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                                end\r\n                                \r\n                                dcr = (cc.to_f / c1.to_f).round(4)\r\n                                aki_7d << {:dx=>\'2\',:dr=>\'1\',:dd=>i,:df=>1,:v=>(cc.to_f / c1.to_f).round(4),:cn=>\'7d\',:cc=>cc,:cr=>c1}\r\n                                if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                    ta[:cr_diagnosis] = \'1\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                                end\r\n                            end\r\n                        elsif d > 2 and d <= 7\r\n                            (d-1).downto(d - 2) do |j|\r\n                                c1 = mc[j.to_s][:creatinine].downcase\r\n                                if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                    dcr = (cc.to_f - c1.to_f).round(4)\r\n                                    aki_2d << {:dx=>\'1\',:dr=>j.to_s,:dd=>i,:df=>(d - j),:v=>dcr,:cn=>\'2d(d)\',:cc=>cc,:cr=>c1}\r\n                                    if ta[:cr_diagnosis] == \'0\' and dcr >= 0.3\r\n                                        ta[:cr_diagnosis] = \'1\'\r\n                                        ta[:cr_diagnosis_from_day] = i\r\n                                    end\r\n                                end\r\n                            end\r\n                            \r\n                            (d-1).downto(1) do |j|\r\n                                c1 = mc[j.to_s][:creatinine].downcase\r\n                                if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                    dcr = (cc.to_f / c1.to_f).round(4)\r\n                                    aki_7d << {:dx=>\'2\',:dr=>j.to_s,:dd=>i,:df=>(d - j),:v=>dcr,:cn=>\'7d(d)\',:cc=>cc,:cr=>c1}\r\n                                    if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                        ta[:cr_diagnosis] = \'2\'\r\n                                        ta[:cr_diagnosis_from_day] = i\r\n                                    end\r\n                                end\r\n                            end\r\n                            # compare with reference cr\r\n                            dcr = (cc.to_f / rc.to_f).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'0\',:dd=>i,:df=>0,:v=>dcr,:cn=>\'7d(rf)\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                                \r\n                            \r\n                        elsif d > 7\r\n                            c1 = mc[(d - 7).to_s][:creatinine].downcase\r\n                            \r\n                            if c1 != \'na\' and c1 != \'nan\' and c1 != \'n/a\' and c1 != \'\'\r\n                                dcr = (cc.to_f / c1.to_f).round(4)\r\n                                aki_7d << {:dx=>\'2\',:dr=>(d-7).to_s,:dd=>i,:df=>7,:v=>dcr,:cn=>\'7d(d-7)\',:cc=>cc,:cr=>c1}\r\n                                if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                    ta[:cr_diagnosis] = \'2\'\r\n                                    ta[:cr_diagnosis_from_day] = i\r\n                                end\r\n                            end\r\n                            # compare with reference cr\r\n                            dcr = (cc.to_f / rc.to_f).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>\'0\',:dd=>i,:df=>0,:v=>dcr,:cn=>\'7d(rfx)\',:cc=>cc,:cr=>rc}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n                            end\r\n                        end\r\n                        \r\n                        if df != 0 and (d - df) > 2 and (d - df) <= 7\r\n                            dcr = (cc.to_f / rc).round(4)\r\n                            aki_7d << {:dx=>\'2\',:dr=>i.to_s,:dd=>i,:df=>(d - df),:v=>dcr,:cn=>\"7d(d:\\\\#{d}+df:\\\\#{df})\",:cc=>cc,:cr=>c1}\r\n                            if ta[:cr_diagnosis] == \'0\' and dcr >= 1.5\r\n                                ta[:cr_diagnosis] = \'2\'\r\n                                ta[:cr_diagnosis_from_day] = i\r\n  