\r\n                        end\r\n                        \r\n                    # end # end if i == 1\r\n                end   # end esrd\r\n            end # end dd\r\n            \r\n            # ta[:ur_list] = ur_list\r\n            ta[:ur_list] = ur_list.join(\',\')\r\n            begin\r\n            if ta[:urine_output_diagnosis] == \'1\'\r\n                ur_list.each do |i|\r\n                    d = i[:d].to_s\r\n                    v = i[:v]\r\n                    if i.to_i < ur_list.last[:d].to_i\r\n                        if v < 0.3 \r\n                            ta[:aki] = \'Yes\'\r\n                            ta[:urine_output_staging] = \'3\'\r\n                            ta[:urine_output_staging_from_day] = d\r\n                            break;\r\n                        elsif v >= 0.3 and v < 0.5 and ta[:urine_output_staging] != \'2\'\r\n                            ta[:aki] = \'Yes\'\r\n                            ta[:urine_output_staging] = \'2\'\r\n                            ta[:urine_output_staging_from_day] = d\r\n                        end\r\n                    end\r\n                # mx_ur = ur_list.sort_by{|i| [i[:v],i[:d]]}[0]\r\n                # d = mx_ur[:d].to_s\r\n                # v = mx_ur[:v]\r\n                # if v >= 0.3 and v < 0.5\r\n                #     ta[:urine_output_staging] = \'2\'\r\n                #     ta[:urine_output_staging_from_day] = d\r\n                # elsif v < 0.3\r\n                #     ta[:urine_output_staging] = \'3\'\r\n                #     ta[:urine_output_staging_from_day] = d\r\n                # end\r\n                # ta[:ur_list] = ur_list.sort_by{|i| i[:v]}\r\n                end\r\n                \r\n                if ta[:urine_output_from_day].to_i == ur_list.last[:d].to_i and ur_list.count != 1\r\n                    ta[:urine_output_diagnosis] = \'0\'\r\n                    ta[:urine_output_from_day] = \'\'\r\n                    ta[:urine_output_staging] = \'0\'\r\n                    ta[:urine_output_staging_from_day] = \'\'\r\n                    msg << \'reset_urine\'\r\n                    msg_txt = \'reset_urine\'\r\n                end\r\n                msg << \"ud:\\\\#{ta[:urine_output_from_day]}-ul:\\\\#{ur_list.last[:d]}(\\\\#{ta[:urine_output_from_day].to_i==ur_list.last[:d].to_i})\"\r\n                    \r\n            end\r\n            rescue\r\n                msg << \"err=\\\\#{ur_list.to_s}\"\r\n            end\r\n            \r\n            aki_list = []\r\n            if ta[:cr_diagnosis] != \'0\' and ta[:cr_staging] != \'3\'\r\n                aki_list = (aki_2d + aki_7d).sort do |a,b|\r\n                    # [b[:v], a[:dd].to_i] <=> [a[:v], b[:dd].to_i]\r\n                    [b[:dx].to_i, a[:dd].to_i] <=> [a[:dx].to_i, b[:dd].to_i]\r\n                end\r\n                # msg << \'xx\'\r\n                # xx = aki_list[0]\r\n                ta[:cr_staging] = \'1\'\r\n                ta[:cr_staging_from_day] = ta[:cr_diagnosis_from_day]\r\n                ta[:aki] = \'Yes\'\r\n                            \r\n                aki_list.each do |xx|\r\n                    if xx[:dx] == \'2\'\r\n                        if xx[:v] >= 1.5 and xx[:v] < 2.0\r\n                            ta[:cr_staging] = \'1\'\r\n                            ta[:cr_staging_from_day] = xx[:dd]\r\n                            ta[:aki] = \'Yes\'\r\n                            break;\r\n                        elsif xx[:v] >= 2.0 and xx[:v] < 3.0\r\n                            ta[:cr_staging] = \'2\'\r\n                            ta[:cr_staging_from_day] = xx[:dd]\r\n                            ta[:aki] = \'Yes\'\r\n                            break;\r\n                        elsif xx[:v] >= 3\r\n                            ta[:cr_staging] = \'3\'\r\n                            ta[:cr_staging_from_day] = xx[:dd]\r\n                            ta[:aki] = \'Yes\'\r\n                            break;\r\n                        end\r\n                    end\r\n                    # if xx[:v] >= 0.3 and xx[:df] <= 2 and xx[:dx] == \'1\'\r\n                    #     ta[:cr_staging] = \'1\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \"Yes\"\r\n                    # elsif xx[:v] >= 1.5 and xx[:v] < 2.0 and xx[:df] <= 7 and xx[:dx] == \'2\'\r\n                    #     ta[:cr_staging] = \'1\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \'Yes\'\r\n                    # elsif xx[:v] >= 2.0 and xx[:v] < 3.0\r\n                    #     ta[:cr_staging] = \'2\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \'Yes\'\r\n                    # elsif xx[:v] >= 3\r\n                    #     ta[:cr_staging] = \'3\'\r\n                    #     ta[:cr_staging_from_day] = xx[:dd]\r\n                    #     ta[:aki] = \'Yes\'\r\n                    # end\r\n                end\r\n                \r\n            end\r\n            \r\n            if ta[:aki].downcase == \'no\'\r\n                ta[:cr_staging] = \'0\'\r\n                ta[:cr_staging_from_day] = \'\'\r\n                # ta[:auto_max_staging] = \'00\'\r\n            end\r\n            \r\n            ta[:auto_max_staging] = \"\\\\#{ta[:cr_staging]}\\\\#{ta[:urine_output_staging]}\"\r\n            \r\n            # msg << \"2D:\\\\#{aki_2d.to_s}\"\r\n            # msg << \"7D:\\\\#{aki_7d.to_s}\"\r\n            msg << aki_list.to_s\r\n            \r\n            #  query each field from case record\r\n            cf.each do |j|\r\n                dd.each do |i|\r\n                    k = \"d\\\\#{i}_\\\\#{j}\"\r\n                    v = !mc[i].nil? ? mc[i][j.to_sym] : \'-\'\r\n                    if j.to_s == \'move_out_time\'\r\n                        if !mc[i].nil?\r\n                            if mc[i][:case_status] != \'0\' and mc[i][:case_status] != \'\'\r\n                                begin\r\n                                v = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                rescue\r\n                                v = \"00:00na\"\r\n                                msg << \"time:\\\\#{mc[i][j.to_sym]}.\"\r\n                                end\r\n                            else\r\n                                v = \'-\'\r\n                            end\r\n                        end\r\n                    end\r\n                    pp[k.to_sym] = v\r\n                    \r\n                end # end dd\r\n            end # end cf\r\n            \r\n            last_day = d_list.last.to_i\r\n            ud = ta[:urine_output_staging_from_day].to_i\r\n            cd = ta[:cr_staging_from_day].to_i\r\n            mf = ta[:aki_max_staging_form].to_i\r\n            cs = !mc[last_day.to_s].nil? ? mc[last_day.to_s][:case_status]  : \'0\'\r\n            \r\n            \r\n            ta[:date_detect] = \"DDD L:\\\\#{last_day}, C:\\\\#{cd}, U:\\\\#{ud} \\\\#{msg_txt}\"\r\n            if (ud == last_day) and ta[:aki].downcase==\'yes\' and cs != \'0\' and last_day > 1\r\n                ta[:date_detect] = \"<span style=\'background:green\'>UUU \\\\#{last_day} L:\\\\#{last_day}</span> \\\\#{msg_txt}\".html_safe\r\n                e_ur += 1\r\n                e_ur_pat_list << pp[:patient_order]\r\n            end\r\n                \r\n        end  \r\n        \r\n                    cr = ta[:cr_staging].to_i\r\n                    ur = ta[:urine_output_staging].to_i\r\n                    ta[:aki_max_staging] = 0\r\n                    ta[:aki_max_staging_from] = 0\r\n                    if cr > ur\r\n                        ta[:aki_max_staging] = cr\r\n                        ta[:aki_max_staging_from] = 1\r\n                    elsif cr < ur\r\n                        ta[:aki_max_staging] = ur\r\n                        ta[:aki_max_staging_from] = 2\r\n                    elsif (cr != 0) and cr == ur\r\n                        ta[:aki_max_staging] = cr\r\n                        ta[:aki_max_staging_from] = 3\r\n                    end\r\n        \r\n        if is_update\r\n            att = {}\r\n            af.each do |k,v|\r\n                smb = k.to_sym\r\n                att[smb] = ta[smb]\r\n            end\r\n            if is_aki\r\n                r_aki.update_attributes att\r\n                msg << \"AKIZ : \\\\#{att}\"\r\n            elsif ta[:aki].downcase == \'yes\' \r\n                pid = pat.id\r\n                par = pat_par[pid]\r\n                r_aki = get_model[:aki].create att\r\n                \r\n                msg << \"akiz : pat_id-\\\\#{pid}|par-\\\\#{par}\"\r\n                pm = @m_pat_mod.create :patient_id=>pid,:module_id=>r_aki.id,:module_name=>\"\\\\#{@current_project.name}#aki\",:date=>Time.now.strftime(\'%d/%m/%Y\'),:time=>Time.now.strftime(\'%H:%M\'),:parent_id=>par,:ref_number=>\'000000\'\r\n            end\r\n        end\r\n        pm_id = pat_par[pat.id]\r\n        x_id = app_par[pm_id]\r\n        pp[:detail] = link_to(\'detail\', \"../Home/patient_record?id=\\\\#{x_id}\", :target=>\'_blank\')\r\n\r\n        # pp[:note] = \"\\\\#{pp[:note]},\\\\#{msg.join(\',\')}\"\r\n        \r\n        pp = pp.merge(ta)\r\n        \r\n        res << pp\r\n    end\r\n    \r\n    lbl = %w{patient_number patient_order gender weight height ideal_body_weight age reference date_of_admission date_of_icu_admission time_of_icu_admission ckd esrd baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr first_available_cr_date}\r\n    lbl << \"num_of_record_day\"\r\n    fx = [\'urine_output_cal_new\', \'creatinine\']\r\n    fx.each do |i|\r\n        dd.each do |j|\r\n            lbl << \"d\\\\#{j}_\\\\#{i}\"\r\n        end\r\n    end\r\n    lbl << \"aki\"\r\n    lbl = lbl + af\r\n    lbl << \'detail\'\r\n    lbl << \'date_detect\'\r\n        \r\n    \r\n    # result assign\r\n    display = \'table\'\r\n    if params[:type] == \'csv\'\r\n        display = \'csv\'\r\n    elsif params[:type] == \'xls\'\r\n        display = \'xls\'\r\n    elsif params[:type] == \'json\'\r\n        display = \'json\'\r\n    end\r\n    \r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    # rs[:app_par] = app_par\r\n    # rs[:mod_par] = mod_par\r\n\r\n    if display == \'json\'\r\n        rs[:all_patient] = a_pat.count\r\n        # rs[:patient_1] = a_pat[1]\r\n        # rs[:e_urine] = e_ur\r\n        # rs[:e_patient] = e_ur_pat_list\r\n        # rs[:all_aki] = a_aki.count\r\n        # rs[:all_case_record] = a_case.count\r\n        rs[:result] = res.count\r\n        rs[:time] = Time.now - tb\r\n%>\r\n\r\n<%= rs.to_json.html_safe %>\r\n\r\n<%\r\n    elsif display == \'table\'\r\n        ff = res[0].keys\r\n        # ff = lbl.collect{|i| i.to_sym}\r\n%>\r\n\r\n<%= stylesheet_link_tag    \"application\"  %>\r\n<h3>Using I/O Cut at <%= io %>:00</h3>\r\n<h3>Total Patient = <%= a_pat.count %></h3>\r\nquery time = <%= Time.now - tb %>\r\n<div style=\'\'><%= link_to \'Confirm\', \"\\\\#{params[:opt]}?act=update\", :class=>\'btn btn-success\' %></div>\r\n<div style=\'padding:50px\'><%= e_ur %> | <%= e_ur_pat_list %></div>\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n<% ff.each do |i| %>\r\n        <th><%= i %></th>\r\n<% end %>        \r\n    </tr>\r\n<% \r\n        res.each do |i| \r\n%>\r\n    <tr>\r\n        <% ff.each do |j| %>\r\n        <% if j.to_s != \'case\' %>\r\n        <td><%= i[j] %></td>\r\n        <% else %>\r\n        <!--<td/>-->\r\n        <td><%= i[j] %></td>\r\n        <% end %>\r\n        <% end %>\r\n    </tr>\r\n<% end %>\r\n</table>\r\n\r\n<br/>\r\nProcessing time = <%= Time.now - tb %>\r\n\r\n<%\r\n    elsif display == \'csv\'\r\n        require \'csv\'\r\n    \r\n        response.headers[\"Content-Type\"] = \"text/csv\"\r\n        response.headers[\"Content-disposition\"] = \"attachment; filename=\\\\#{this.document_name}-\\\\#{params[:solution_name]}-\\\\#{Time.now.to_i}.csv\"\r\n        \r\n        ff = res[0].keys\r\n        \r\n        xxx = CSV.generate do |csv|\r\n            \r\n            csv << ff\r\n            tmp = []\r\n            res.each do |i|\r\n                ff.each do |j|\r\n                    tmp << i[j]\r\n                end\r\n                csv << tmp\r\n            end\r\n      \r\n        end\r\n%>\r\n<%= xxx.html_safe %>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2016-07-28 16:31:57','2016-07-28 16:31:57','aki2','*'),(2438,'template',1000,1,'{\r\n    version:1.0\r\n\r\n\r\n\r\n}',NULL,NULL,NULL,'2016-07-30 14:50:18','2016-07-30 14:50:18','template','*'),(2439,'live',1000,3,'\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n\r\n<%\r\n    config = this.template\r\n    config.merge! this.live_config\r\n    \r\n    models = get_model\r\n    \r\n    finding_doc_name =  config[:finding_doc]\r\n    finding_model = models[finding_doc_name.to_sym]\r\n    \r\n\r\n    \r\n    model = models[this.document_name]\r\n    \r\n    doc = get_document this.document_name\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    emodel = ehr.load_model\r\n    patient_model = emodel[:patient]\r\n    module_model = emodel[:patient_module]\r\n    \r\n    \r\n    \r\n    if params[:id]\r\n        \r\n   \r\n    \r\n    m = module_model.find params[:id]\r\n    \r\n    \r\n    patient = patient_model.find(m.patient_id)\r\n     \r\n    current_module =m\r\n    \r\n    record = model.find m.module_id\r\n    else    \r\n        \r\n        \r\n    models[:appointment].find(params[:admit_id]).update_attributes :status=>\'Processing\'\r\n\r\n    \r\n        \r\n        \r\n    patient =  patient_model.find(params[:patient_id])\r\n    record = model.new\r\n    \r\n    # module_model.find(mrecord.parent_id).module_id\r\n    \r\n    end\r\n    \r\n    # record is data record\r\n    \r\n    \r\n    review_1 = config[:review_1]\r\n    review_2 = config[:review_2]\r\n    \r\n    relation = {}\r\n    \r\n    reviews = review_1+review_2\r\n    \r\n    rfields = {}\r\n    fmap = {}\r\n    for i in doc.fields\r\n        if reviews.index(i.column_name)\r\n            cfg= {:name=>i.column_name,:title=>i.name,:field_type=>i.field_type}\r\n             if i.lov_type==\'plain\' or i.lov_type==\'pair\'\r\n                    if i.lov_type == \'plain\'\r\n                   options = [[\'&nbsp;\',nil]]+i.lov.split(\"\\n\").compact.collect{|j| j.strip}       \r\n                   elsif i.lov_type ==\'pair\'\r\n                   options = [[\'&nbsp;\',nil]]+i.lov.split(\"\\n\").compact.collect{|j| t = j.split(\'|\').reverse; [t[0].strip,t[1]] }\r\n                   end\r\n                cfg[:lov_type] = i.lov_type\r\n                cfg[:lov] = options\r\n                \r\n             elsif i.field_type==\'relation_one\'\r\n             \r\n             fp = eval \"{\\\\#{i.params}}\"\r\n             \r\n             rdoc_name = fp[:relation][:document]\r\n             \r\n\r\n             records = []\r\n             \r\n             unless fp[:relation][:where]\r\n             unless relation[rdoc_name]\r\n             rmodel = models[rdoc_name]\r\n             relation_records = rmodel.all\r\n             \r\n            if fp[:relation][:sort]\r\n	\r\n	        relation_records.sort! do |a,b|\r\n		    k = 0 \r\n		    fp[:relation][:sort].each do |i|\r\n		\r\n		        k = a[i]<=>b[i] if a[i]!=nil and b[i]!=nil\r\n		 \r\n		        k = -1 if b[i]==nil\r\n		        k = 1 if a[i]==nil  \r\n		\r\n		        k = 0 if a[i]==nil and b[i]==nil\r\n		  		   \r\n		        break if k!=0  \r\n		\r\n		    end\r\n		    k\r\n		    end 	\r\n	        end\r\n             \r\n             \r\n             \r\n             relation[rdoc_name] = relation_records.collect{|r| [r.name,r.id] }\r\n             end\r\n             records = relation[rdoc_name].clone\r\n             \r\n             else\r\n             rmodel = models[rdoc_name]  \r\n             \r\n             relation_records = rmodel.all(fp[:relation][:where])\r\n          \r\n             \r\n               if fp[:relation][:sort]\r\n	\r\n	        relation_records.sort! do |a,b|\r\n		    k = 0 \r\n		    fp[:relation][:sort].each do |i|\r\n		\r\n		        k = a[i]<=>b[i] if a[i]!=nil and b[i]!=nil\r\n		 \r\n		        k = -1 if b[i]==nil or b[i]==\'\'\r\n		        k = 1 if a[i]==nil or a[i]==\'\'  \r\n		\r\n		        k = 0 if a[i]==nil and b[i]==nil\r\n		  		   \r\n		        break if k!=0  \r\n		\r\n		    end\r\n		    k\r\n		    end 	\r\n	        end\r\n             \r\n             \r\n             records = [[\'\',nil]]+relation_records.collect{|r| [r.name,r.id] }\r\n            \r\n             end\r\n             \r\n             \r\n             \r\n             \r\n             \r\n             \r\n             \r\n             \r\n             cfg[:lov] = records\r\n             \r\n             \r\n             \r\n            end\r\n             \r\n             cfg[:multiple] = true if %w{check_string}.index(i.field_type)\r\n             \r\n             rfields[cfg[:name]] = cfg\r\n             \r\n             \r\n        end\r\n        \r\n    end\r\n    \r\n    \r\n \r\n    finding =finding_model.new\r\n    \r\n    \r\n    finding_doc = get_document finding_doc_name\r\n    \r\n    cfg_fields = config[:fields]\r\n    \r\n    fields = {}\r\n    if finding_doc\r\n        for i in finding_doc.fields\r\n            if i.column_name\r\n               options = nil\r\n              \r\n                \r\n               cfg = {:name=>i.column_name,:title=>i.name,:field_type=>i.field_type}\r\n               if i.lov_type==\'plain\' or i.lov_type==\'pair\'\r\n                    if i.lov_type == \'plain\'\r\n                   options = [[\'&nbsp;\',nil]]+i.lov.split(\"\\n\").compact.collect{|j| j.strip}       \r\n                   elsif i.lov_type ==\'pair\'\r\n                   options = [[\'&nbsp;\',nil]]+i.lov.split(\"\\n\").compact.collect{|j| t = j.split(\'|\').reverse; [t[0],t[1]] }\r\n                   end\r\n                cfg[:lov_type] = i.lov_type\r\n                cfg[:lov] = options\r\n               end\r\n               \r\n               cfg.merge! cfg_fields[cfg[:name]] if cfg_fields[cfg[:name]]\r\n               fields[cfg[:name]] = cfg\r\n            end\r\n        end\r\n    \r\n    end\r\n    config[:fields]= fields\r\n    \r\n    start_time = Time.now\r\n    \r\n    start_time = start_time.strftime(\"%H:%M\")\r\n    \r\n%>\r\n\r\n\r\n<html>\r\n<head>\r\n    <%=include_header%>\r\n    <style>\r\n        .btn-size{width:40px;margin:10px;margin-right:10px;}\r\n        .img{width:100px;height:100px;border:1px solid;margin:20px;display:inline-block;}\r\n        .btn{font-size:1.5em ;line-height:1.5em ;height:4em;display:table-cell};\r\n        .page_patient{\r\n            background-color:#fff;\r\n        }\r\n        .page1{\r\n            background-color:#233643;\r\n            margin-top:20px;\r\n            \r\n        }\r\n        .page2{\r\n            background-color:#233643;\r\n            margin-top:20px;\r\n\r\n\r\n        }\r\n        .page3{\r\n            margin-top:20px;\r\n            background-color:#233643;\r\n        }\r\n        .image{\r\n            margin:10px;\r\n            width:200px;\r\n        }\r\n        .btn-x{\r\n            width:99%;display:inline-block;height:1.5em;padding:0px;padding-top:20px;padding-bottom:20px;\r\n            \r\n        }\r\n        .btn-y{\r\n            height:1em;\r\n        }\r\n    </style>\r\n    \r\n</head>\r\n\r\n\r\n<body class=\"\" style=\"background-color:#10222e;color:#aaa;padding:0px\">\r\n    <script>\r\n\r\n\r\n                Array.prototype.unique = function(a){\r\n                     return function(){ return this.filter(a) }\r\n                    }(function(a,b,c){ return c.indexOf(a,b+1) < 0 });\r\n                    \r\n\r\n            var record = <%=record.to_json.html_safe%>\r\n            var finding = <%=finding.to_json.html_safe%>\r\n            var selected_location = null;\r\n            var selected_disease = null;\r\n            var i_disease = null;\r\n            var counter = 0;\r\n            var path_number = 0;\r\n            \r\n            var start_time =  new Date();\r\n            var start_scope_time =  new Date(); // start\r\n            var target_scope_time = null; // \r\n            var stop_scope_time = null; // \r\n            var stop_time = null;\r\n            \r\n            var finding_start = null;\r\n            var finding_stop = null;\r\n            var on_finding = false;\r\n            var images_map = {};\r\n            \r\n            var will_add_to_record = {};\r\n            \r\n            var finding_template = null;\r\n            \r\n            \r\n            function select_location(location){\r\n                selected_location = location\r\n                $(\'#locations\').hide();\r\n                $(\'#loc-\'+location).addClass(\"btn-success\")\r\n                console.log(location)\r\n                $(\'.dis\').removeClass(\"btn-success\");\r\n                $(\'#diseases\').effect(\"highlight\");\r\n                \r\n                $(\'#finding-image\').show();\r\n                $(\'#finding-item\').hide();\r\n                \r\n                $(\'#finding-finish\').removeClass(\'btn-info\')\r\n                $(\'#finding-finish\').addClass(\'btn-success\')\r\n                $(\'#finding-finish\').html(\'Next\');\r\n\r\n            }\r\n\r\n\r\n\r\n            function close_pageflow(){\r\n                $(\'.pageflow\').hide(); \r\n            }\r\n            function select_disease(disease, check=true){\r\n                \r\n                \r\n                \r\n                lov = <%=config[:fields][config[:disease_field]][:lov].to_json.html_safe%>\r\n                \r\n                \r\n                \r\n                lov = <%=([\'\']+config[:diseases].collect{|i| i}).to_json.html_safe if config[:diseases] %>\r\n\r\n                will_add_to_record = {};\r\n                \r\n                \r\n                i_disease = disease;\r\n                selected_disease = lov[disease];\r\n                // alert(selected_disease)\r\n                \r\n                finding[\'<%=config[:disease_field]%>\'] = selected_disease\r\n                   \r\n                   \r\n                $(\'.dis\').removeClass(\"btn-success\");\r\n                $(\'#dis-\'+(disease-1)).addClass(\"btn-success\")\r\n                console.log(disease)\r\n                document.getElementById(\"finding-panel\").scrollIntoView();\r\n                \r\n                close_pageflow();\r\n                $(\'#finding-panel\').show();\r\n                \r\n                \r\n                \r\n                templates = {}\r\n                \r\n                templates = <%=config[:disease_config].to_json.html_safe%>\r\n                \r\n                \r\n                \r\n                // console.log(templates)\r\n\r\n                    \r\n                template = templates[selected_disease]\r\n                \r\n                finding_template = template;\r\n                \r\n                fw = template[\'fw\']\r\n                for (var key in fw) {\r\n                    if (fw.hasOwnProperty(key)) {\r\n                        finding[key] = fw[key]\r\n                    }\r\n                }\r\n                \r\n                \r\n                fwr = template[\'fwr\']\r\n                for (var key in fwr) {\r\n                    if (fwr.hasOwnProperty(key)) {\r\n                        \r\n                        v = fwr[key]\r\n                    \r\n                    \r\n\r\n                        if(v[0]==\'+\'){\r\n                           \r\n                            if (typeof record[key] === \"undefined\") {\r\n                                record[key] = \'\'\r\n                            }\r\n\r\n                            vl = record[key].split(\"|\")\r\n                            vx = v.substring(2,v.length-1);\r\n                            \r\n                            // alert(\'has fwr \'+vx)\r\n                            \r\n                            if(vx==\'@\')vx = selected_disease;\r\n                            vl.push(vx);\r\n                            \r\n                            will_add_to_record[key] = vx\r\n                            \r\n                            // record[key] = vl.unique().join(\"|\");\r\n                            \r\n                        }else{\r\n                            vx = fwr[key]\r\n                            if(vx==\'@\')vx = selected_disease;\r\n                            // record[key] = vx\r\n                        }\r\n                        \r\n                    }\r\n                }\r\n                \r\n                \r\n               \r\n                \r\n                \r\n                \r\n                fields = template[\'fields\']\r\n                \r\n                start_finding(check);\r\n                \r\n                  console.log(fields)\r\n                \r\n                <%\r\n                    for i in config[:findings]\r\n                %>\r\n                    $(\'.f-<%=i%>\').removeClass(\"btn-success\");\r\n                    $(\'#v-<%=i%>\').hide()\r\n                     $(\'#f-<%=i%>\').hide()\r\n                <% end %>\r\n                \r\n             \r\n                for(i=0;i<fields.length;i++){\r\n                    \r\n                     $(\'#f-\'+fields[i]).show()\r\n                }\r\n                \r\n                <%\r\n                \r\n                if true\r\n                    for i in config[:findings]\r\n                    f = config[:fields][i]\r\n                    lov = f[:lov]\r\n                    \r\n                   if f[:auto_increment]\r\n                       \r\n                %>  \r\n                    \r\n                   if(fields.indexOf(\"<%=f[:name]%>\")>=0){\r\n                    if(check)path_number+=1\r\n                    // alert(path_number)\r\n                    value = \'\'+path_number\r\n                    \r\n                    live_click(\'<%=i%>\',value,<%=lov.to_json.html_safe%>.indexOf(value),false)\r\n                   }\r\n                    \r\n                <% end %>\r\n                \r\n                <%\r\n                end\r\n                end %>\r\n                \r\n               \r\n\r\n                \r\n\r\n               \r\n                \r\n            }\r\n            \r\n            function reset_start_finding(){\r\n                finding_start = new Date();\r\n                title = finding_start.getHours() + \":\" + finding_start.getMinutes()\r\n                $(\'#finding-start\').html(\'Start at<br/>\'+title)\r\n            }\r\n            function start_finding(check=false){\r\n                counter += 1\r\n                title = \"Finding #\"+(counter)+\" : \"+selected_disease+\" at \"+selected_location;\r\n                $(\'#finding-title\').html(title)\r\n                reset_start_finding()\r\n                $(\'#finding-image\').html(\"<center><h1>Ready for capture..</h1></center>\");\r\n                if(check)on_finding = true;\r\n                finding[\'<%=config[:finding_image_field]%>\']=[];\r\n                console.log(finding);\r\n                \r\n                \r\n                \r\n                \r\n                <%\r\n                    for i in config[:findings]\r\n                %>\r\n                \r\n                    $(\'.f-<%=i%>\').removeClass(\"btn-success\");\r\n                    $(\'#v-<%=i%>\').hide()\r\n                    $(\'#f-<%=i%>\').show()\r\n                <% end %>\r\n                \r\n                \r\n                     \r\n           \r\n                \r\n            }\r\n            \r\n            function stop_finding(){\r\n                finding_stop = new Date();\r\n           \r\n                title = finding_stop.getHours() + \":\" + finding_stop.getMinutes();\r\n                $(\'#finding-timer\').html(\'Timer<br/>\'+title)\r\n                \r\n                title = \"Finish<br/>\"+title\r\n                 $(\'#finish_finding\').html(title)\r\n                 \r\n                 \r\n                 \r\n                 \r\n            }\r\n            \r\n            function process_update(data){\r\n                d = JSON.parse(data)\r\n                \r\n                    console.log(d)\r\n                    \r\n                if(\"record\" in d){\r\n                    // record = d[\'record\']\r\n                    id =  d[\'record\'][\'_id\']\r\n                    if(d[\'record\'][\'id\']!=null)\r\n                        id =  d[\'record\'][\'id\']  \r\n                    // console.log(d[\'record\'])\r\n                    // alert(\'get record \'+id)\r\n                    \r\n                    record[\'_id\'] = id\r\n                    record[\'id\'] = id\r\n                    record[\'<%=config[:image_field]%>\'] = d[\'record\'][\'<%=config[:image_field]%>\']\r\n                    \r\n                    \r\n                    <% if config[:timers][:start_scope_time] %>\r\n                    if(record[\'<%=config[:timers][:start_scope_time]%>\']!=null){\r\n                        console.log(\"set scope time start\")\r\n                        set_start_scope_time_proc(record[\'<%=config[:timers][:start_scope_time]%>\'])\r\n                    }\r\n                    <% end %>\r\n                     <% if config[:timers][:target_scope_time] %>\r\n                    if(record[\'<%=config[:timers][:target_scope_time]%>\']!=null){\r\n                        console.log(\"set scope time target\")\r\n                        set_target_scope_time_proc(record[\'<%=config[:timers][:target_scope_time]%>\'])\r\n                    }\r\n                    <% end %>\r\n                    <% if config[:timers][:stop_scope_time] %>\r\n                    if(record[\'<%=config[:timers][:stop_scope_time]%>\']!=null){\r\n                        console.log(\"set scope time stop\")\r\n                        // alert(record[\'<%=config[:timers][:stop_scope_time]%>\'])\r\n                        set_stop_scope_time_proc(record[\'<%=config[:timers][:stop_scope_time]%>\'])\r\n                    }\r\n                    <% end %>\r\n                    fx = $(\'#finding-list\')\r\n                    fx.html(\'\')\r\n                    \r\n                    for(var i=0;i<d[\'findings\'].length;i++){                    \r\n                    t = d[\'findings\'][i]   \r\n                    // alert(i)\r\n                    var newLink = $(\"<a />\", {\r\n                    id : t[\'id\'],\r\n                    name : t[\'id\'],\r\n                    href : \"javascript:\",\r\n                    text : t[\'title\'],\r\n                    class : \'btn  btn-x\'\r\n                    });\r\n                    \r\n                    var newdiv = $(\"<div/>\",{\r\n                        class: \'row-fluid\'\r\n                    });\r\n                    \r\n                    newdiv.append(newLink)\r\n                    \r\n                    fx.append(newdiv);\r\n                    }\r\n                    \r\n                   \r\n                    \r\n                   \r\n\r\n                    \r\n                    \r\n                    // partial for debug\r\n                    record[\'diagnosis_group\'] = d[\'record\'][\'diagnosis_group\']\r\n                    record[\'procedure\'] = d[\'record\'][\'procedure\']\r\n                    \r\n                    // alert(\'get record \'+record[\'diagnosis_group\'] )\r\n                    \r\n                    <% for i in config[:locations] \r\n                        j = i+config[:field_subfix]\r\n                    %>\r\n                    // console.log( d[\'record\'][\'<%=j%>\'])\r\n                    record[\'<%=j%>\'] = d[\'record\'][\'<%=j%>\']\r\n                    <% end %>\r\n                    \r\n                }\r\n                \r\n                if(\"next_finding\" in d){\r\n                    finding[\'_id\'] = d[\'next_finding\']\r\n                    finding[\'id\'] = d[\'next_finding\']\r\n                }\r\n                \r\n                // alert(d);\r\n                if(\"app_id\" in d){\r\n                    \r\n                    // window.location.replace(\"../Live/patient_record?id=\"+d[\'app_id\']);\r\n                    window.location = \"../Live/patient_record?id=\"+d[\'app_id\'];\r\n                    //  window.history.back();\r\n                    \r\n                }\r\n                \r\n               else\r\n               \r\n                if(\"images\" in d){\r\n                    lasted = \"\";\r\n                    for( i=0;i<d[\'images\'].length;i++){\r\n                        \r\n                        j = d[\'images\'][i]\r\n                        //  alert(j)\r\n                        \r\n                     \r\n                        if(!(j[\'id\'] in images_map)){\r\n                            console.log(j)\r\n                            \r\n                            $(\'#live-image\').append($(\'<img>\',{id:\'\',\'class\':\"image\",src:(j[\'path\']+\"?thumb=2\")}))\r\n                            if(on_finding){\r\n                                \r\n                                $(\'#finding-image\').append($(\'<img>\',{id:\'\',\'class\':\"image\",src:(j[\'path\']+\"?thumb=2\")}))\r\n                                finding[\'<%=config[:finding_image_field]%>\'].push(j[\'id\'])\r\n                                \r\n                            }\r\n                            \r\n                            images_map[j[\'id\']] = j\r\n                            lasted = j[\'path\']+\"?thumb=2\"\r\n                            \r\n                        }\r\n                        \r\n                        \r\n                        \r\n                    }\r\n                    if(lasted != \"\"){\r\n                        // alert(lasted)\r\n                        $(\'#lasted\').attr(\"src\",lasted);\r\n                        $(\'#lasted\').fadeIn();\r\n                        \r\n                        $(\'#to_library\').html(\"Library (\"+d[\'images\'].length+\")\");\r\n                        \r\n                    }\r\n                    \r\n                }\r\n                \r\n                \r\n               \r\n                \r\n                    // alert( \"Data Loaded: \" +  eval(data[\'record\']));\r\n                    \r\n                    // data = process_update\r\n                    //\r\n\r\n                    \r\n                \r\n            }\r\n            \r\n            function finish_finding(){\r\n                // alert(\'finish_finding\')\r\n            \r\n            if(on_finding){\r\n                on_finding = false;\r\n                \r\n                $(\'#finding-image\').hide();\r\n                $(\'#finding-item\').show();\r\n                \r\n                $(\'#finding-finish\').addClass(\'btn-info\')\r\n                $(\'#finding-finish\').removeClass(\'btn-success\')\r\n                $(\'#finding-finish\').addClass(\'btn-info\')\r\n                $(\'#finding-finish\').html(\'Finish Finding\')\r\n                \r\n                select_disease(i_disease,false);\r\n                \r\n                \r\n            }else{\r\n\r\n            record_field = selected_location+\"<%=config[:field_subfix]%>\";\r\n            \r\n            // record[record_field].push(finding[\'id\']);\r\n            \r\n\r\n                \r\n    //         \'Polyp\':{\r\n    // :fwr=>{},\r\n    // :fw=>{:abnormal_type=>\'Polyp\'},\r\n    // :fields=>%w{endoscopy_dx size treatment_by patho_number clip tattoo},\r\n    // :values=>{\'endoscopy_dx\'=>[\'Hyperplastic polyp\',\'Adenomatous polyp\',\'Sessile Serrated Adenoma\',\'Traditional Serrated Adenoma\',\'Malignant non invasive polyp\',\'Malignant invasive polyp\',\'Inflammatory polyp\',\'Pseudopolyp\']}, \r\n    // :values_fwr_default=>\'diagnosis_group\',\r\n    // :values_fwr=>{\'endoscopy_dx\'=>{\'Hyperplastic polyp\'=>\'Hyperplastic polyp\',\'Adenomatous polyp\'=>\'Neoplastic polyp\',\'Malignant non invasive polyp\'=>\'Neoplastic polyp\',\'Malignant invasive polyp\'=>\'Neoplastic polyp\',\r\n    // \'Inflammatory polyp\'=>\'Other polyp\',\'Pseudopolyp\'=>\'Other polyp\',\'Sessile Serrated Adenoma\'=>\'Serrated polyp\',\'Sessile Serrated Adenoma\'=>\'Serrated polyp\',\'\'=>\'\'}}\r\n    // }    \r\n            \r\n            if(finding_template!=null){\r\n                \r\n                if(finding_template.hasOwnProperty(\'values_fwr\')){\r\n                    v = finding_template[\'values_fwr\']\r\n                    record_key = finding_template[\'values_fwr_default\'];\r\n                    for(var key in v){\r\n                        if(v.hasOwnProperty(key)){\r\n                            if(v[key].hasOwnProperty(finding[key])){\r\n                                // alert(\"\"+record_key+\" set to \"+ v[key][finding[key]])\r\n                                will_add_to_record[record_key] = v[key][finding[key]]\r\n                                console.log(\"+Set \"+record_key+\" = \"+v[key][finding[key]])\r\n\r\n\r\n                                \r\n                            }\r\n                            \r\n                        }\r\n                    }\r\n                    \r\n                }\r\n                \r\n                \r\n                                    \r\n                ext_templates =  <%=config[:disease_template][:values_fwr_extra].to_json.html_safe%>\r\n            \r\n                \r\n                for(var idx in ext_templates){\r\n                    ext = ext_templates[idx]\r\n                    item_field = ext[\'item_field\']\r\n                    record_field = ext[\'record_field\']\r\n                    values = ext[\'values\']\r\n                    \r\n                    if(finding.hasOwnProperty(item_field)){\r\n                        \r\n                        text = values[finding[item_field]]\r\n                        console.log(\"+Set \"+record_field+\" = \"+text)\r\n                        will_add_to_record[record_field]=text\r\n                          \r\n                    }\r\n               \r\n                    \r\n                }\r\n                \r\n                \r\n                \r\n                \r\n            }     \r\n            \r\n            \r\n            \r\n            \r\n            \r\n            \r\n \r\n \r\n            for (var key in will_add_to_record) {\r\n                if (will_add_to_record.hasOwnProperty(key)) {\r\n                    // alert(\"xx\"+record[key])\r\n                    if(typeof(record[key])==\'undefined\')record[key]=\'\'\r\n                    \r\n                    vl = record[key].split(\"|\")\r\n                    \r\n                    vl.push(will_add_to_record[key]);\r\n                    console.log(\"add \"+will_add_to_record[key]+\" to \"+key)\r\n                    record[key] = vl.unique().join(\"|\")\r\n                    \r\n                }\r\n            }\r\n                           \r\n            \r\n            \r\n            \r\n            $.post( \"../Live/live_api\", { model:\'<%=this.document_name%>\' ,finding_model:\'<%= config[:finding_doc] %>\', location:selected_location, disease:selected_disease , record: JSON.stringify(record), finding: JSON.stringify(finding), finding_image: \'<%=config[:finding_image_field]%>\', record_field:record_field , params:<%=params.to_json.html_safe%> })\r\n            .done(process_update);\r\n            \r\n            back_to_finding();   \r\n            reset_finding();\r\n            }\r\n            // refresh_procedure();\r\n            }\r\n            \r\n            function update_record(){\r\n                \r\n                \r\n            <%\r\n                if config[:timers]\r\n            %>\r\n            <% if config[:timers][:start_time] %>\r\n            record[\'<%=config[:timers][:start_time]%>\'] = start_time \r\n            <% end %>\r\n            <% if config[:timers][:stop_time] %>\r\n            record[\'<%=config[:timers][:stop_time]%>\'] = stop_time \r\n            <% end %>\r\n            \r\n            <% if config[:timers][:start_scope_time] %>\r\n            if(start_scope_time!=null)record[\'<%=config[:timers][:start_scope_time]%>\'] = start_scope_time \r\n            <% end %>\r\n            \r\n            <% if config[:timers][:target_scope_time] %>\r\n            if(target_scope_time!=null)record[\'<%=config[:timers][:target_scope_time]%>\'] = target_scope_time \r\n            <% end %>\r\n            \r\n            \r\n            <% if config[:timers][:stop_scope_time] %>\r\n            if(stop_scope_time!=null)record[\'<%=config[:timers][:stop_scope_time]%>\'] = stop_scope_time \r\n            <% end %>       \r\n            <% end %>\r\n            \r\n            \r\n            <% if config[:record] %>\r\n            <% config[:record].each_pair do |k,v| %>\r\n            <% if  v.key?(:unless) %>\r\n                \r\n                if(record[\'<%=k%>\']==null){record[\'<%=k%>\'] = \'<%=v[:unless]%>\';}\r\n            \r\n            <% end %>\r\n            <% end %>\r\n           \r\n            <% end %>\r\n           \r\n            \r\n            // $.post( \"live_api\", {parent_id: \'<%=params[:parent_id]%>\', start:start_time,ref:\'44829/51\',img: \'<%= config[:image_field]%>\' , model:\'<%=this.document_name%>\', params:<%=params.to_json.html_safe%> })\r\n            //     .done(process_update);\r\n               \r\n           \r\n            $.post( \"../Live/live_api\", {model:\'<%=this.document_name%>\',record:JSON.stringify(record), status:\'Recovery\', params:<%=params.to_json.html_safe%> })\r\n            .done(process_update);\r\n                \r\n                \r\n                \r\n            }\r\n            \r\n            \r\n            function back_to_finding(){\r\n                close_pageflow();\r\n                $(\'#start\').show();\r\n                \r\n            }\r\n\r\n            <% unless params[:id] %>            \r\n            setInterval(stop_finding, 10000);        \r\n            \r\n            stop_finding();\r\n            <% end %>\r\n            \r\n            function set_start_scope_time(){\r\n                time = new Date();\r\n                set_start_scope_time_proc(time);\r\n            }\r\n            function set_start_scope_time_proc(time){\r\n                start_scope_time = new Date(time);\r\n                $(\'#start_scope_time\').removeClass(\"btn-info\")\r\n                $(\'#target_scope_time\').addClass(\"btn-info\")\r\n                title = start_scope_time.getHours() + \":\" + start_scope_time.getMinutes()\r\n                $(\'#start_scope_time\').html(\'Started at<br/>\'+title)\r\n            }\r\n            function set_target_scope_time(){\r\n                time = new Date();\r\n                set_target_scope_time_proc(time);\r\n            \r\n                \r\n            }\r\n            function set_target_scope_time_proc(time){\r\n                \r\n                $(\'#target_scope_time\').removeClass(\"btn-info\")\r\n                $(\'#finish_finding\').addClass(\"btn-success\")\r\n                target_scope_time = new Date(time)\r\n                title = target_scope_time.getHours() + \":\" + target_scope_time.getMinutes()\r\n                $(\'#target_scope_time\').html(\'Cecum at<br/>\'+title)\r\n                // update_record();\r\n            }\r\n            \r\n            function set_stop_scope_time(){\r\n                \r\n                time = new Date();\r\n               set_stop_scope_time_proc(time)\r\n            }\r\n            \r\n            function set_stop_scope_time_proc(time){\r\n                stop_scope_time =  new Date(time);\r\n                title = stop_scope_time.getHours() + \":\" + stop_scope_time.getMinutes()\r\n                $(\'#finish_finding\').html(\'Finished at<br/>\'+title)\r\n                \r\n            }\r\n            \r\n            function finish(){\r\n                close_pageflow();\r\n                stop_time = new Date();\r\n                $(\'#summary-panel\').show();\r\n\r\n\r\n            }\r\n            \r\n            \r\n            \r\n            function sync_record(){\r\n                \r\n            }\r\n            \r\n            function sync_finding(){\r\n                    \r\n            }\r\n            function reset_finding(){\r\n                $(\'.loc\').removeClass(\"btn-success\");\r\n                $(\'.dis\').removeClass(\"btn-success\");\r\n                $(\'#diseases\').hide()\r\n                $(\'#locations\').show()\r\n                finding = {}\r\n                \r\n            }\r\n            \r\n            function cancel_finding(){\r\n                counter -=1\r\n                \r\n                reset_finding();\r\n                \r\n                if(counter<0)counter = 0 \r\n                document.getElementById(\"start\").scrollIntoView();\r\n                 close_pageflow();\r\n                $(\'#start\').show();\r\n            }\r\n            \r\n            function record_click_mul(f,v,t){\r\n                // $(\'.r-\'+f).removeClass(\"btn-success\");\r\n                console.log(\"rf=\"+f+\' v=\'+v)\r\n                \r\n                found = false\r\n                l = []\r\n                if(record[f]==null){\r\n                    record[f]=\'\'\r\n                }\r\n             \r\n                    vl = record[f].split(\"|\")\r\n                    //  console.log(vl)\r\n                    for (i = 0; i < vl.length; i++) { \r\n                        \r\n                        if(vl[i]==v){\r\n                            found=true\r\n                        }else{\r\n                            l.push(vl[i])\r\n                        }\r\n                        \r\n                    }\r\n                    if(found){\r\n                        $(\"#r-\"+f+\"-\"+t).removeClass(\'btn-success\')\r\n                    }else{\r\n                        l.push(v)\r\n                        $(\"#r-\"+f+\"-\"+t).addClass(\'btn-success\')\r\n                    }\r\n                    s =  l.join(\"|\")\r\n                    record[f] = s\r\n                    \r\n\r\n                    \r\n                    \r\n                    // alert(record[f])\r\n                \r\n                \r\n                \r\n                \r\n                // console.log(record)\r\n                \r\n                \r\n                \r\n            }\r\n            function record_click(f,v,t){\r\n                $(\'.r-\'+f).removeClass(\"btn-success\");\r\n                console.log(\"rf=\"+f+\' v=\'+v)\r\n                $(\"#r-\"+f+\"-\"+t).addClass(\'btn-success\')\r\n                record[f] = v\r\n                console.log(record)\r\n                $(\'#f-\'+f).slideUp()\r\n                $(\'#v-\'+f).toggle( \"highlight\" )\r\n                $(\'#v-\'+f+\"-value\").html( $(\"#r-\"+f+\"-\"+t).html())\r\n                $(window).scrollTop($(\'#v-\'+f).offset().top);\r\n\r\n\r\n\r\n            }\r\n            function live_click(f,v,t,s=true){\r\n                \r\n                if(f==\'patho_number\'&&(v==\'\'||v==\'Loss\')){\r\n                    path_number -= 1\r\n                }\r\n                \r\n                $(\'.f-\'+f).removeClass(\"btn-success\");\r\n                console.log(\"f=\"+f+\' v=\'+v+\' t=\'+t)\r\n                $(\"#f-\"+f+\"-\"+t).addClass(\'btn-success\')\r\n                finding[f] = v\r\n                console.log(finding)\r\n                $(\'#v-\'+f+\"-value\").html( $(\"#f-\"+f+\"-\"+t).html())\r\n                $(\'#f-\'+f).slideUp()\r\n                $(\'#v-\'+f).toggle( \"highlight\" )\r\n                if(s)\r\n                $(window).scrollTop($(\'#v-\'+f).offset().top);\r\n\r\n\r\n            }\r\n            \r\n             function live_click_number(f,v,t,s=true){\r\n                \r\n                // alert(v)\r\n// live_click(‘size’,’0.9’,9)\r\n// Id f-size-9\r\n// Value = 0.9\r\n                base = parseInt(v)\r\n                cls = \"f-\"+f;\r\n                $(\".\"+cls).each(function(){\r\n                    \r\n                    o = $(this)\r\n                    b = parseFloat(o.attr(\'base\'));\r\n                    n = base+b\r\n                    id = o.attr(\'id\').split(\"-\")[2];\r\n                    o.attr(\'onmousedown\',\"javascript:live_click(\'size\',\'\"+n+\"\',\"+id+\")\")   \r\n                    o.html(n)\r\n                    \r\n                    \r\n                })\r\n                // <a onmousedown=\"javascript:live_click(&quot;size&quot;,&quot;0.3&quot;,3)\" class=\"f-size btn btn-size\" \r\n                // id=\"f-size-3\" style=\"font-size:1.2em;\" href=\"javascript:\">0.3</a>\r\n\r\n            }\r\n            \r\n            \r\n            \r\n            function reselect(f){\r\n                \r\n                $(\'#v-\'+f).slideUp( )\r\n                $(\'#f-\'+f).slideDown()\r\n            }\r\n            \r\n            function refresh_procedure(){\r\n             \r\n                // $(\'live-image\').html(new Date());\r\n                var currentdate = new Date();\r\n                var datetime = \"Last Sync: \" + currentdate.getDay() + \"/\"+currentdate.getMonth() \r\n                + \"/\" + currentdate.getFullYear() + \" @ \" \r\n                + currentdate.getHours() + \":\" \r\n                + currentdate.getMinutes() + \":\" + currentdate.getSeconds();\r\n            \r\n                // $(\'#live-image\').html(datetime);\r\n                \r\n                <%\r\n                    ref = params[:ref]\r\n                    ref = params[:record_name] if params[:record_name]\r\n                    params[:parent_id] = current_module.parent_id if current_module\r\n                %>\r\n                $.post( \"../Live/live_api\", {parent_id: \'<%=params[:parent_id]%>\', start:start_time,ref:\'<%=ref%>\',img: \'<%= config[:image_field]%>\' , model:\'<%=this.document_name%>\', params:<%=params.to_json.html_safe%> })\r\n                .done(process_update);\r\n                \r\n                \r\n            }\r\n            refresh_procedure();\r\n    </script>\r\n\r\n<div id=\"contentwrapper\" >\r\n\r\n<div class=\"row-fluid  page_patient  \" style=\"border:0px solid;margin-top:0px;background:#fff;padding:5px\">\r\n    <div class=\"span3\" id=\"header-panel\">\r\n    </div>\r\n    <div class=\"span2\" style=\"\">  <br/>\r\n    <h2> </h2>\r\n    </div>\r\n    <div class=\"span5\" style=\"color:black\">  <br/>\r\n    <h2 > <%=patient.prefix_name%><%=patient.first_name %> <%=patient.last_name%>  HN: <%=patient.hn%> </h2>\r\n    </div>\r\n    \r\n   <%#link_to \'Back\',\"javascript:\",:onmousedown=> \"../Live/patient_record?id=\\\\#{params[:admit_id]}\",:style=>\"margin-top:20px;height:40px\", :class=>\"btn span2\"%>\r\n\r\n\r\n</div>\r\n\r\n<div  id=\"start\" class=\"pageflow row-fluid page1 \" style=\"border:0px solid;margin-top:0px;padding-top:10px;padding:5px\">\r\n \r\n\r\n\r\n    <div class=\"row-fluid\">    \r\n    <div class=\"span7\">\r\n    <div id=\"locations\">\r\n    <div class=\"row-fluid \">\r\n        <div class=\"span12\"><h1>Finding Location</h1></div>\r\n    </div>    \r\n     <div   class=\"\" style=\"height:539px;border:0px solid black;align:center\" >\r\n     <center>\r\n      <%=render  :inline=>this.live_map %></center>\r\n     </div>\r\n     \r\n      </div>\r\n           <% if config[:disease_field]\r\n    \r\n        field = config[:fields][config[:disease_field]]\r\n        list = field[:lov][1..-1]\r\n        list = config[:diseases].collect{|i| i} if config[:diseases]\r\n        \r\n    %>  \r\n    <div id=\"diseases\" class=\"hide\">\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span4\"><h1>Disease</h1> \r\n    </div>\r\n    <div class=\"span4\"><h1>&nbsp;</h1> \r\n    </div>\r\n    \r\n    <%=link_to \"Back to location\",\"javascript:\",:onmousedown=>\"javascript:back_to_finding();reset_finding();\",:class=>\'btn span4\',:style=>\"height:40px\" %>\r\n\r\n\r\n\r\n\r\n    </div>\r\n      \r\n      \r\n    <div class=\"row-fluid\" id=\"diseases\">    \r\n        <% list.each_with_index do |i,index|  %>\r\n        \r\n        <% if index!=0 and index%3==0%>\r\n        </div> <div class=\"row-fluid\">&nbsp;</div>\r\n        <div class=\"row-fluid\" >\r\n        <% end %>\r\n        <% if i.instance_of? String %>\r\n        <div class=\"span4\">\r\n        <%=link_to \"\\\\#{i}\" ,\"javascript:\", :onmousedown=>\"javascript:select_disease(\\\\#{index+1},true)\", :class=>\'btn btn-x dis\', :id=>\"dis-\\\\#{index}\" %>\r\n        </div>\r\n        <% else%>\r\n        <%=link_to \"\\\\#{i[0]} \\\\#{i.class}\" ,\"javascript:\", :class=>\'btn \' %>\r\n        <% end %>\r\n        <% end %>\r\n    </div>\r\n    \r\n\r\n     \r\n     \r\n    \r\n    \r\n    </div>\r\n    \r\n        \r\n    <% end %>    \r\n    </div>\r\n    <div class=\"span5\">\r\n       \r\n       \r\n        <div class=\"row-fluid\"><h1>Capture</h1></div>\r\n        <div class=\"row-fluid\" >\r\n        \r\n            <div class=\"span8\">\r\n                <%=image_tag \'\', :id=>\'lasted\'%>\r\n            </div>\r\n            <div class=\"span4\">\r\n            <%=link_to \"Library\".html_safe ,\"javascript:\",:id=>\'to_library\', :class=>\'btn  btn-x\',:style=>\"vertical-align:middle;width;90%\"%>\r\n            </div>\r\n            <%#button_to \"Library\".html_safe ,\"javascript:\",:id=>\'to_library\', :class=>\'btn span4 \',:style=>\"vertical-align:middle\"%>\r\n\r\n\r\n        </div>\r\n\r\n\r\n\r\n        <div class=\"row-fluid\"><h1>Timer</h1></div>\r\n\r\n        <div class=\"row-fluid\">\r\n        <%=link_to \"Started at<br/>--:--\".html_safe ,\"javascript:\",:onmousedown=>\"\\\\#{\'javascript:set_start_scope_time()\' unless params[:id]}\", :class=>\'btn span12 btn-info\',:id=>\'start_scope_time\'%>\r\n        </div>\r\n        \r\n        <div class=\"row-fluid\">\r\n        <%=link_to \"Cecum at<br/>--:--\".html_safe ,\"javascript:\",:onmousedown=>\"\\\\#{\'javascript:set_target_scope_time()\' unless params[:id]}\", :class=>\'btn span12\',:id=>\"target_scope_time\" %>\r\n        </div>\r\n        \r\n        <div class=\"row-fluid\">\r\n        <%=link_to \"Finished at<br/>--:--\".html_safe ,\"javascript:\",:onmousedown=>\"\\\\#{\'javascript:set_stop_scope_time();\' unless params[:id]}finish()\", :class=>\'btn span12\',:id=>\'finish_finding\' %>\r\n        </div>\r\n       \r\n        <div class=\"row-fluid\"><h1>Finding</h1></div>\r\n\r\n        <div class=\"row-fluid\" id=\"finding-list\">\r\n        </div>\r\n       \r\n        \r\n        <%#link_to \"Finish<br/>--:--\".html_safe ,\"javascript:finish()\", :class=>\'btn span3\' ,:id=>\'finish_finding\' %>\r\n    \r\n    <div class=\"hide\">\r\n    <div class=\"row-fluid\" id=\"locations\">\r\n        <div class=\"span12\"><h1>Location</h1></div>\r\n    </div>        \r\n        <div class=\"row-fluid\" >\r\n\r\n\r\n        <% config[:locations].each_with_index do |i,index|  %>\r\n        <% if index!=0 and index%3==0%>\r\n        </div> <div class=\"row-fluid\">&nbsp;</div>\r\n        <div class=\"row-fluid\" >\r\n        <% end %>\r\n        <%=link_to \"\\\\#{i.humanize}\" ,\"javascript:\",:onmousedown=>\"javascript:select_location(\'\\\\#{i}\')\",:id=>\"loc-\\\\#{i}\",:class=>\'loc btn span4\' %>\r\n        <% end %>\r\n        \r\n    </div>\r\n     </div>  \r\n        \r\n  \r\n        \r\n        \r\n        \r\n        \r\n    </div>\r\n    </div>\r\n        \r\n    \r\n        \r\n        \r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12\" id=\"library-image\"><h1>Procedure / Image captures</h1></div>\r\n    </div>\r\n      \r\n \r\n    <div id=\"live-image\" class=\"row-fluid\" style=\"min-height:200px;border:1px solid #ccc\">    \r\n    \r\n    \r\n    </div>\r\n    \r\n   \r\n    <script>\r\n        \r\n        //setInterval(refresh_procedure, 10000);\r\n        \r\n    </script>\r\n        \r\n</div>\r\n\r\n\r\n\r\n<div id=\"finding-panel\" class=\"pageflow row-fluid page2  hide\">\r\n<div  class=\"row-fluid span12 \">\r\n<h1 id=\"finding-title\">Polyp #1 at Rectum</h1>\r\n</div>\r\n\r\n<div  class=\"row-fluid \">\r\n\r\n        <div class=\"span3\">\r\n        <%=link_to \"Cancel\" ,\"javascript:cancel_finding()\", :class=>\'btn  btn-x\' %>\r\n        </div>\r\n     \r\n        <%=link_to \"Start at<br/>--:--\".html_safe ,\"javascript:\",:onmousedown=>\"reset_start_finiding()\",:id=>\"finding-start\", :class=>\'btn span3 \',:style=>\"\" %>\r\n      \r\n        <%=link_to \"Timer<br/>--:--\".html_safe ,\"javascript:\",:onmousedown=>\"stop_finding()\",:id=>\"finding-timer\", :class=>\'btn span3\' %>\r\n        <div class=\"span3\">\r\n        <%=link_to \"Finish\".html_safe ,\"javascript:\",:onmousedown=>\"javascript:finish_finding()\",:id=>\"finding-finish\", :class=>\'btn   btn-x\' %>\r\n        </div>\r\n</div>\r\n \r\n \r\n \r\n \r\n \r\n\r\n<!---------------------------------------------------------------------------------\r\n\r\n--------------------------------------------------------------------------------->\r\n<script>\r\n\r\n</script>\r\n<%\r\n    def render_live_field  ft,f,r = nil\r\n%>\r\n\r\n    \r\n\r\n    <div  class=\" span3 \" style=\"font-size:1.5em;display:table;\">\r\n    <center><%=f[:title]%> <%=\'(s)\' if f[:multiple]%></center>\r\n    </div>\r\n    <% \r\n    \r\n    row=4\r\n    \r\n    if %w{endoscopist_1 endoscopist_2 nurse endoscopy_dx }.index(f[:name])\r\n        row = 2\r\n        \r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    if f[:lov]\r\n        f[:lov].each_with_index  do |j,jindex| %>\r\n            <% if jindex!=0 and jindex%row==0 %>\r\n                </div>\r\n                <div class=\"row-fluid\" >\r\n                <div class=\"span3\" style=\"\">&nbsp;</div>\r\n            <% end %>\r\n            <%\r\n                if j.instance_of? Array\r\n                    title = j[0]\r\n                    value = j[1]\r\n                else\r\n                    title = j\r\n                    value = j\r\n                end\r\n                value = \"\" unless value\r\n            selected  = \'\'\r\n            \r\n            size = \'span\'+(8/row).to_s\r\n            \r\n            \r\n            \r\n                \r\n            if ft == \'record\'\r\n                \r\n                selected = \'btn-success\' if r and r[f[:name]]==value\r\n                \r\n                if f[:multiple]\r\n            %>\r\n                 <div class=\"<%=size%>\">\r\n                <%=link_to title.html_safe,\"javascript:\",:onmousedown=> \'javascript:record_click_mul(\"\'+f[:name]+\'\",\"\'+value+\'\",\'+jindex.to_s+\')\',:id=>\"r-\\\\#{f[:name]}-\\\\#{jindex}\",:class=>\"r-\\\\#{f[:name]} btn btn-x \\\\#{selected}\",:style=>\"font-size:1.2em;\" %>\r\n                </div>\r\n            <% else%>\r\n                <div class=\"<%=size%>\">\r\n                <%=link_to title.html_safe,\"javascript:\",:onmousedown=> \'javascript:record_click(\"\'+f[:name]+\'\",\"\'+value+\'\",\'+jindex.to_s+\')\',:id=>\"r-\\\\#{f[:name]}-\\\\#{jindex}\",:class=>\"r-\\\\#{f[:name]} btn btn-x \\\\#{selected}\",:style=>\"font-size:1.2em;\" %>\r\n                </div>\r\n            <% end %>\r\n            \r\n            <% else %>\r\n                <div class=\"<%=size%>\">\r\n            \r\n            <%=link_to title.html_safe,\"javascript:\",:onmousedown=> \'javascript:live_click(\"\'+f[:name]+\'\",\"\'+value+\'\",\'+jindex.to_s+\')\',:id=>\"f-\\\\#{f[:name]}-\\\\#{jindex}\",:class=>\"f-\\\\#{f[:name]} btn btn-x \\\\#{selected}\",:style=>\"font-size:1.2em;\" %>\r\n                </div>\r\n            <% end %>\r\n        <% end %>\r\n  \r\n    <% elsif f[:type]==\'number\' %>\r\n    \r\n    <div class=\"span8\" style=\"border:0px solid\">\r\n    \r\n   <div class=\"row-fluid\"> \r\n\r\n   <%10.times do |j| \r\n        j+=0\r\n   %>\r\n    <%=link_to j,\"javascript:\",:onmousedown=> \'javascript:live_click_number(\"\'+f[:name]+\'\",\"\'+(j).to_s+\'\",\'+(j+10).to_s+\')\',:class=>\"btn btn-size \" ,:id=>\"f-\\\\#{f[:name]}-\\\\#{j+10}\",:style=>\"font-size:1.2em;\" %>\r\n    <% end %>\r\n   </div>\r\n   \r\n   \r\n   \r\n    <div class=\"row-fluid\">  \r\n    <%10.times do |j| \r\n        j+=0\r\n        iv = (j/10.0)\r\n    %>\r\n    <%=link_to iv ,\"javascript:\",:onmousedown=>\'javascript:live_click(\"\'+f[:name]+\'\",\"\'+(iv).to_s+\'\",\'+j.to_s+\')\',:base=>iv, :class=>\"f-\\\\#{f[:name]} btn btn-size\" ,:id=>\"f-\\\\#{f[:name]}-\\\\#{j}\",:style=>\"font-size:1.2em;\" %>\r\n    <% end %>\r\n    \r\n    </div>  \r\n    \r\n    \r\n      </div>\r\n\r\n\r\n    <% end %>\r\n  \r\n  \r\n\r\n\r\n<% end %>\r\n\r\n<%\r\n    def render_live_value  ft,f, r= nil\r\n        \r\n        \r\n    row=4\r\n    \r\n    if %w{endoscopist_1 endoscopist_2 nurse endoscopy_dx }.index(f[:name])\r\n        row = 2\r\n        \r\n    end\r\n    \r\n%>\r\n\r\n    <div  class=\" span3 \" style=\"font-size:1.5em;display:table\">\r\n    <center><%=f[:title]%> <%=\'(s)\' if f[:multiple]%></center>\r\n    </div>\r\n    \r\n    <%=link_to \"Value\",\"javascript:\",:onmousedown=> \'javascript:reselect(\"\'+f[:name]+\'\")\',:id=>\"v-\\\\#{f[:name]}-value\",:class=>\"btn span3 btn-success \",:style=>\"font-size:1.2em;height:none;display:inline-block;padding:20px\" %>\r\n\r\n    \r\n\r\n<% end %>\r\n\r\n   <div class=\"row-fluid\">\r\n    <div class=\"span12\">&nbsp;</div>\r\n        \r\n    </div>\r\n\r\n\r\n<div class=\"row-fluid  \">\r\n\r\n<div id=\"finding-image\"  class=\"row-fluid\">\r\n\r\n</div>\r\n\r\n<div id=\"finding-item\">\r\n<% for i in config[:findings] \r\n    \r\n    f = config[:fields][i]\r\n    if f\r\n    %>\r\n    <div id=\"v-<%=f[:name]%>\" class=\"hide\">\r\n    <div class=\"row-fluid\">&nbsp;</div>    \r\n    <div class=\"row-fluid\" >  \r\n    <%= render_live_value(\'record\',f).html_safe%>\r\n    </div>\r\n    </div>\r\n    \r\n    <div id=\"f-<%=f[:name]%>\" >\r\n    <div class=\"row-fluid\">&nbsp;</div>    \r\n    <div class=\"row-fluid\">    \r\n    <%= render_live_field(\'\',f).html_safe%>\r\n    </div>\r\n    </div>\r\n    <% end %>\r\n   <% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n<div class=\"pageflow row-fluid  page3 hide\" id=\"summary-panel\">\r\n\r\n<div class=\"row-fluid\">\r\n        <div class=\"span3\">\r\n        <%=link_to \"Finding\" ,\"javascript:\",:onmousedown=>\"javascript:back_to_finding()\", :class=>\'btn  btn-x\' %>\r\n        </div>\r\n        <%#link_to \"\" ,\"javascript:\", :class=>\'btn span3\' %>\r\n        <%#link_to \"\" ,\"javascript:\", :class=>\'btn span3\' %>\r\n        <div class=\"span3\">&nbsp;</div>\r\n         <div class=\"span3\">&nbsp;</div>\r\n         <div class=\"span3\">\r\n        <%=link_to \"FINISH\" ,\"javascript:\", :class=>\'btn btn-info btn-x\' ,:id=>\'update_record\' %>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"row-fluid page3\">\r\n<h1>Sedation</h1>\r\n</div>\r\n\r\n    <%\r\n        \r\n      review_sedation = config[:review_sedation]\r\n  \r\n     review_sedation = [] unless review_sedation\r\n    %>\r\n      \r\n    <%\r\n    \r\n     for i in review_sedation\r\n     \r\n        \r\n        f = {:title=>i[:select].humanize}\r\n     \r\n     \r\n        default = i[:default]\r\n        unit = \'mg\'\r\n        \r\n        unit = i[:unit] if i[:unit]\r\n        \r\n        # default = 5.to_s if i.index \'dormi\'==-1\r\n        ch = \'\'\r\n        ch = \'hide\' if i[:default]==nil\r\n        j = i[:value]\r\n        m = 5\r\n        n = 1\r\n        m = i[:m] if i[:m]\r\n        n = i[:n] if i[:n]\r\n        m = m.to_s\r\n        n = n.to_s\r\n        \r\n        vv = default\r\n        \r\n        vv = record[j.to_s] if record and record[j.to_s]\r\n    %>\r\n<div class=\"row-fluid page3 <%=ch%>\" ><%=ch%>\r\n    \r\n    \r\n    <div  class=\" span3 \" style=\"font-size:1.5em;display:table\">\r\n    <center><%=f[:title]%><br/><i><%=unit%></i> <%=\'(s)\' if f[:multiple]%></center>\r\n    </div>\r\n        \r\n   \r\n\r\n     \r\n    <div class=\"span2\">\r\n    <%= link_to vv,\"javascript:\",:onmousedown=>\"javascript:set(\'#value-\\\\#{j}\',\'\\\\#{j}\',\'\\\\#{i[:select]}\',record)\", :class=>\"btn btn-x \\\\#{\'btn-success\' if vv and  vv > 0}\", :id=>\"value-\\\\#{j}\" %>\r\n    </div>\r\n       <%\r\n   \r\n            if i[:route]\r\n            ivf = doc.find_by_column_name i[:route]\r\n            px = {}\r\n            px = eval \'{\'+ivf.params+\'}\' if ivf.params\r\n            \r\n            lov = ivf.get_lov_options\r\n            defv = \'\'\r\n            defv = px[:default]\r\n   \r\n   \r\n   %>\r\n    <div class=\"span1\"><%= select_tag \"\", options_for_select(lov,defv ), :class=>\" btn  btn-x x-\\\\#{j} btn-y\",:style=>\"height:3em\" , :name=>i[:route], :id=>\"route-\\\\#{j}\"%></div>\r\n     <% end %>\r\n     \r\n    <div class=\"span1\"><%= link_to \'+\'+m,\"javascript:\",:onmousedown=> \"javascript:modify(\'#value-\\\\#{j}\',\"+m+\",\'\\\\#{j}\',\'\\\\#{i[:select]}\',record)\", :class=>\'btn btn-x btn-y \'+\"x-\\\\#{j}\" %></div>\r\n    \r\n    <div class=\"span1\"><%= link_to \'-\'+m,\"javascript:\",:onmousedown=> \"javascript:modify(\'#value-\\\\#{j}\',-\"+m+\",\'\\\\#{j}\',\'\\\\#{i[:select]}\',record)\", :class=>\'btn btn-x btn-y \'+\"x-\\\\#{j}\" %></div>\r\n    \r\n    <div class=\"span1\"><%= link_to \'+\'+n,\"javascript:\",:onmousedown=> \"javascript:modify(\'#value-\\\\#{j}\',\"+n+\",\'\\\\#{j}\',\'\\\\#{i[:select]}\',record)\", :class=>\'btn btn-x btn-y \' +\"x-\\\\#{j}\" %></div>\r\n    \r\n    <div class=\"span1\"><%= link_to \'-\'+n,\"javascript:\",:onmousedown=> \"javascript:modify(\'#value-\\\\#{j}\',-\"+n+\",\'\\\\#{j}\',\'\\\\#{i[:select]}\',record)\", :class=>\'btn btn-x btn-y \' +\"x-\\\\#{j}\" %></div>\r\n\r\n   \r\n\r\n</div>\r\n\r\n\r\n\r\n<script>\r\n\r\n    function modify(id,v,field,sel,obj){\r\n        i = $(id)\r\n        f = parseFloat(i.html())+v\r\n        if(f<0)f=0;\r\n        obj[field] = f\r\n        obj[sel] = true\r\n        $(\'#value-\'+field).addClass(\'btn-success\')\r\n         if(f==0){\r\n             obj[sel] = false;\r\n             $(\'#value-\'+field).removeClass(\'btn-success\')\r\n         }\r\n        i.html(f)\r\n    }\r\n    \r\n    function set(id,field,sel,obj){\r\n        \r\n          i = $(id)\r\n          f = Math.round(parseFloat(i.html())*10)/10\r\n          \r\n          obj[field] = f\r\n          $(\'#value-\'+field).addClass(\'btn-success\')\r\n\r\n\r\n          obj[sel] = true\r\n         if(f==0){\r\n             obj[sel] = false;\r\n             $(\'#value-\'+field).removeClass(\'btn-success\')\r\n\r\n\r\n         }\r\n\r\n          $(\'.x-\'+field).toggle()\r\n        \r\n    }\r\n    <% if i[:route] %>\r\n    $(\'#route-<%=j%>\').change(function(){\r\n       v = $(this).val()\r\n       n = $(this).attr(\"name\")\r\n       record[n]=v\r\n    //   console.log(record);\r\n       \r\n    });\r\n    \r\n    <% end %>\r\n    \r\n    \r\n    \r\n</script>\r\n\r\n    \r\n    \r\n   <% end %>\r\n<div class=\"row-fluid page3\">\r\n<h1>Summary</h1>\r\n</div>\r\n\r\n\r\n<div class=\"row-fluid page3\">\r\n    <%\r\n     for i in review_1\r\n\r\n     f = rfields[i]\r\n     if f\r\n    %>\r\n    <div id=\"v-<%=f[:name]%>\" class=\"hide\">\r\n    <div class=\"row-fluid\">&nbsp;</div>    \r\n    <div class=\"row-fluid\" >  \r\n    <%= render_live_value(\'record\',f,record).html_safe%>\r\n    </div>\r\n    </div>\r\n    \r\n    <div id=\"f-<%=f[:name]%>\">\r\n    <div class=\"row-fluid\">&nbsp;</div>    \r\n    <div class=\"row-fluid\" >    \r\n    <%= render_live_field(\'record\',f,record).html_safe%>\r\n    </div>\r\n    </div>\r\n    <% end %>\r\n   \r\n   <% end %>\r\n</div> \r\n\r\n    \r\n<div class=\"row-fluid page3\">\r\n    <%\r\n     for i in review_2\r\n\r\n     f = rfields[i]\r\n     if f\r\n    %>\r\n    \r\n    <div id=\"v-<%=f[:name]%>\" class=\"hide\">\r\n    <div class=\"row-fluid\">&nbsp;</div>    \r\n    <div class=\"row-fluid\" >  \r\n    <%= render_live_value(\'record\',f,record).html_safe%>\r\n    </div>\r\n    </div>\r\n    \r\n    \r\n    <div id=\"f-<%=f[:name]%>\" >\r\n    <div class=\"row-fluid\" >&nbsp;</div>\r\n    <div class=\"row-fluid\" >    \r\n    <%= render_live_field(\'record\',f,record).html_safe%>\r\n    </div>\r\n    </div>\r\n    <% end %>\r\n   \r\n   <% end %>\r\n</div> \r\n\r\n\r\n\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n</div>\r\n<div class=\"row-fluid\">\r\n    &nbsp;\r\n</div>\r\n<div class=\"row-fluid\">\r\n\r\n  \r\n  <div class=\"span8\">&nbsp;</div>\r\n    <%=link_to \'<<Top>>\',\"javascript:\",:onmousedown=> \'javascript:window.scrollTo(0,0);\',:style=>\"padding-top:0px;height:40px\", :class=>\"btn span4\"%>\r\n    <br/>\r\n</div>\r\n\r\n\r\n    \r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n<div id=\"header-content\" style=\"padding-left:20px;background:#fff\">\r\n<%=yield :header%>\r\n</div>\r\n<script>\r\n    $(\'#header-content\').appendTo(\"#header-panel\");\r\n</script>\r\n<style>\r\ndiv#toolbar\r\n{\r\nheight: 100px;\r\nright: 00px;\r\nbottom: -10px;\r\nposition: fixed;\r\nwidth:20px;\r\nz-index: 1;\r\n}\r\n\r\n\r\n\r\n</style>\r\n\r\n<div id=\"toolbar\" class = \"alert\" style=\"font-size:0.5em;background:#1e4862\">\r\n    <%=link_to \'<i class=\"splashy-arrow_large_up\"></i>\'.html_safe,\'javascript:\',:id=>\"s_up\", :class=>\"btn btn-large\" ,:style=>\"\"%><br/>\r\n    <%=link_to \'<i class=\"splashy-arrow_large_down\"></i>\'.html_safe,\"javascript:\",:id=>\"s_down\" ,:class=>\"btn btn-large\",:style=>\"\" %>\r\n</div>\r\n<script>\r\n\r\nvar status=null;\r\nvar ac = 20;\r\n\r\n$(\'#s_up\').mousedown(function(){\r\n   status=\'up\'\r\n});\r\n\r\n$(\'#s_down\').mousedown(function(){\r\n    status=\'down\'\r\n});\r\n\r\n$(\'#s_up\').mouseup(function(){\r\n   status=\'\'\r\n   ac = 10;\r\n});\r\n\r\n$(\'#s_down\').mouseup(function(){\r\n    status=\'\'\r\n    ac = 10;\r\n});\r\n\r\n$(\'#to_library\').mousedown(function(){\r\n  $(window).scrollTop($(\'#library-image\').offset().top);\r\n});\r\n\r\n\r\nfunction update_scroll(){\r\n    if(status==\'up\'){\r\n      if(window.pageYOffset-ac<0){status=\'\';ac=10;}\r\n      window.scrollTo(window.pageXOffset, window.pageYOffset-ac);\r\n     \r\n      ac+=3\r\n    }\r\n    if(status==\'down\'){\r\n      if(window.pageYOffset+ac>$(document).height()-$(window).height()){status=\'\';ac=10}\r\n      \r\n      window.scrollTo(window.pageXOffset, window.pageYOffset+ac);\r\n      ac+=3\r\n    }\r\n    //   console.log(status)\r\n    \r\n}\r\n\r\n    setInterval(update_scroll, 100);        \r\n$(\"#update_record\").click(function(){\r\n    $(this).html(\'Updating..\');\r\n    update_record();\r\n    \r\n    // window.location = \'../Live/patient_record?id=<%=params[:admit_id]%>\'\r\n     \r\n});\r\n</script>\r\n<%#  @next_id%>\r\n</body>\r\n</html>',NULL,NULL,NULL,'2016-07-30 14:53:57','2016-07-30 14:53:57','live','*'),(2440,'live_config',189,1,'{\r\n    name: \"Colonoscopy\",\r\n    multi_fields: true,\r\n    finding_doc: \'colonoscopy_scope\',\r\n    disease_field: \'abnormal_type\',\r\n    image_field: \'image\',\r\n    field_subfix: \'_scope\',\r\n    live_background: \'/esm/cusys/mobile/colo.png\',\r\n    :record=>{\r\n        :diagnosis_group=>{:unless=>\'Normal\'},\r\n        :procedure=>{}\r\n    },\r\n    locations:[\"rectum\", \"sigmoid\", \"descending_colon\", \"transvers_colon\", \"ascending_colon\", \"cecum\", \"terminal_ileum\"],\r\n    location_config:[\r\n        {name:\'rectum\'},\r\n        {name:\'sigmoid\'},\r\n        {name:\'descending_colon\'},\r\n        {name:\'transvers_colon\'},\r\n        {name:\'ascending_colon\'},\r\n        {name:\'cecum\'},\r\n        {name:\'terminal_ileum\'}\r\n    ],\r\n    :diseases=>%w{Polyp Cancer Lipoma Submucosal Diverticulum Ulcer}+[\"SRUS\",\"Abnormal VV\"],\r\n    :disease_template=>{\r\n        :values_fwr_extra=>[{\r\n                            :item_field=>:treatment_by,\r\n                            :record_field=>:procedure,\r\n                            :values=>{\'Cold polypectomy\'=>\'Polypectomy\',\'Hot polypectomy\'=>\'Polypectomy\',\r\n                                      \'Cold biopsy\'=>\'Bx\',\'Hot biopsy\'=>\'Bx\',\'EMR\'=>\'EMR\',\'EPMR\'=>\'EPMR\',\r\n                                      \'Precut EMR\'=>\'Precut EMR\',\'EMR-C\'=>\'EMR-C\',\'ESD\'=>\'ESD\',\'APC\'=>\'APC\',\r\n                                      \'Coagulation\'=>\'Coagulation\'}\r\n                            }]\r\n    },\r\n    :disease_config=>{\r\n    \'Polyp\':{\r\n        :fwr=>{},\r\n        :fw=>{:abnormal_type=>\'Polyp\'},\r\n        :fields=>%w{endoscopy_dx size nice_classification treatment_by patho_number clip tattoo},\r\n        :values=>{\'endoscopy_dx\'=>[\'Hyperplastic polyp\',\'Adenomatous polyp\',\'Sessile Serrated Adenoma\',\'Traditional Serrated Adenoma\',\'Malignant non invasive polyp\',\'Malignant invasive polyp\',\'Inflammatory polyp\',\'Pseudopolyp\']}, \r\n        :values_fwr_default=>\'diagnosis_group\',\r\n        :values_fwr=>{\'endoscopy_dx\'=>{\'Hyperplastic polyp\'=>\'Hyperplastic polyp\',\'Adenomatous polyp\'=>\'Neoplastic polyp\',\'Malignant non invasive polyp\'=>\'Neoplastic polyp\',\'Malignant invasive polyp\'=>\'Neoplastic polyp\',\r\n        \'Inflammatory polyp\'=>\'Other polyp\',\'Pseudopolyp\'=>\'Other polyp\',\'Sessile Serrated Adenoma\'=>\'Serrated polyp\',\'Sessile Serrated Adenoma\'=>\'Serrated polyp\',\'\'=>\'\'}},\r\n        },\r\n    \'Lipoma\':{\r\n        :fwr=>{:diagnosis_group=>\'+@\'},\r\n        :fw=>{:abnormal_type=>\'Submucosal lesion\',:endoscopy_dx=>\'Lipoma\'},\r\n        :fields=>%w{size treatment_by patho_number clip tattoo}},\r\n    \'Submucosal\':{\r\n        :fwr=>{:diagnosis_group=>\'+@\'},\r\n        :fw=>{:abnormal_type=>\'Submucosal lesion\'},\r\n        :fields=>%w{size treatment_by patho_number clip tattoo}},\r\n    \'Diverticulum\':{\r\n        :fwr=>{:diagnosis_group=>\'+@\'},\r\n        :fw=>{:abnormal_type=>\'Diverticulum\'},\r\n        :fields=>[]},\r\n    \'Cancer\':{\r\n        :fwr=>{:diagnosis_group=>\'+@\'},\r\n        :fw=>{:abnormal_type=>\'Mass\'},\r\n        :fields=>[\'patho_number\',\'tattoo\']},\r\n    \'Ulcer\':{\r\n        :fwr=>{:diagnosis_group=>\'+@\'},\r\n        :fw=>{:abnormal_type=>\'Ulcer\'},\r\n        :fields=>[\'patho_number\']},\r\n    \'SRUS\':{\r\n        :fwr=>{:diagnosis_group=>\'+@\'},\r\n        :fw=>{:abnormal_type=>\'Mucosal lesion\'},\r\n        :fields=>[\'patho_number\']},\r\n    \'Abnormal VV\':{\r\n        :fwr=>{:diagnosis_group=>\'+Abnormal vessel\'},\r\n        :fw=>{:abnormal_type=>\'Abnormal VV\'},\r\n        :fields=>[]}\r\n    \r\n    },\r\n    :findings=> %w{endoscopy_dx size nice_classification treatment_by  patho_number clip  tattoo },\r\n    :finding_image_field=>\'image\',\r\n    fields:{\r\n        \'abnormal_type\'=>{title:\"Disease\"},\r\n        \'patho_number\'=>{auto_increment:true},\r\n        \'size\'=>{type:\'number\'},\r\n        \'dormicum_mg\'=>{type:\'number\'}\r\n    },\r\n    \r\n    :review_sedation=>[\r\n        {:select=>\'dormicum\', :value=>\'dormicum_mg\',:route=>\'dormicum_num\',:default=>5,:m=>1,:n=>0.5},\r\n        {:select=>\'pethidine\', :value=>\'pethidine_mg\',:route=>\'pethidine_num\',:default=>25,:m=>5, :n=>1},\r\n        {:select=>\'buscopan\', :value=>\'buscopan_mg\',:route=>\'buscopan_route\'},\r\n        {:select=>\'fentanyl\', :value=>\'fentanyl_mg\',:route=>\'fentanyl_routh\',:unit=>\'mcg\'},\r\n        {:select=>\'diprivan\', :value=>\'diprivan_mg\',:route=>\'diprivan_num\'},\r\n        {:select=>\'valium\', :value=>\'valium_mg\',:route=>\'valium_num\'},\r\n        {:select=>\'plasil\', :value=>\'plasil_mg\',:route=>\'plasil_route\'},\r\n        {:select=>\'general_anesthesia\'}\r\n        \r\n    ],\r\n    :review_1=> %w{\r\n    \r\n        colonoscope\r\n        quality_of_preparate\r\n        scope\r\n        endoscopist_1\r\n        endoscopist_2\r\n        nurse\r\n\r\n    \r\n    },\r\n    timers:{\r\n        start_time:\'start_at\',\r\n        stop_time:\'stop_at\',\r\n        start_scope_time:\'start_scope_at\',\r\n        target_scope_time:\'cecum_at\',\r\n        stop_scope_time:\'stop_scope_at\'\r\n        \r\n    },\r\n    review_2: %w{ \r\n     }\r\n    \r\n}\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-07-30 14:56:34','2016-07-30 14:56:34','live_config',''),(2441,'live_config',1000,1,'{}',NULL,NULL,NULL,'2016-07-30 14:58:18','2016-07-30 14:58:18','live_config','*'),(2442,'report',885,2,'<h2>Report</h2><hr/>\r\n<ul>\r\n    <li><a href=\"#\">รายงานรายได้</a></li>\r\n    <li><a href=\"#\">สินค้าคงคลัง</a></li>\r\n    <li><a href=\"#\">สถิติการผู้รับบริการ</a></li>\r\n    <li><a href=\"#\">รายงานสำหรับผู้บริหาร</a></li>\r\n    <li><a href=\"#\">รายงานเชิงระบบ (สำหรับ admin)</a></li>\r\n    \r\n</ul>',NULL,NULL,NULL,'2016-07-31 02:40:37','2016-07-31 02:40:37','report',''),(2443,'live_api',1000,3,'<%\r\n    config = this.template\r\n    config.merge! this.live_config\r\n\r\n    models = get_model\r\n    \r\n    model = models[params[:model].to_sym]\r\n    \r\n    result = {:params=>params.to_json}\r\n    mrecord = nil\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    emodel = ehr.load_model\r\n        \r\n    patient_model = emodel[:patient]\r\n    module_model = emodel[:patient_module]\r\n    \r\n    \r\n    if params[:record]\r\n        rx = JSON.parse(params[:record])\r\n        \r\n        \r\n        \r\n        rx[\'id\'] = rx[\'_id\'] if rx[\'_id\']\r\n        record = model.find(rx[\'id\'])\r\n    \r\n        \r\n        unless record\r\n    \r\n       \r\n        \r\n        record = model.create  rx \r\n        \r\n        p = params[:params]\r\n        \r\n        apm = module_model.find(p[:parent_id])\r\n        \r\n        \r\n        # models[:appointment].find(module_model.find(mrecord.parent_id).module_id).update_attributes :status=>\'Processing\'\r\n        i = module_model.last :module_name=>\"\\\\#{@current_project.name}#\\\\#{params[:model]}\"\r\n      l = 111\r\n      if i and i.ref_number\r\n          l = i.ref_number[6..-1].to_i%10000\r\n      end\r\n      next_id = format(\'%04d\',(l+1)%10000)\r\n      d = Time.now\r\n      @next_id = \"\\\\#{d.strftime(\'%y%m%d\')}\\\\#{next_id}\"  \r\n          \r\n          \r\n          \r\n        mrecord = module_model.create :parent_id=>p[:parent_id], :ref_number=> @next_id ,:module_id=>record.id, :module_name=>\"\\\\#{@current_project.name}#\\\\#{params[:model]}\",:patient_id=>apm.patient_id\r\n        \r\n        \r\n        else\r\n        \r\n        mrecord = module_model.where(:module_id=>record.id).first\r\n            \r\n        record.update_attributes rx \r\n            \r\n        end\r\n        \r\n        result[:record] = record\r\n        \r\n        unless params[:finding]\r\n            result[:app_id] =  module_model.find(mrecord.parent_id).module_id\r\n            \r\n        end\r\n        \r\n        \r\n        \r\n        \r\n    end\r\n\r\n    if params[:finding]\r\n        \r\n        fx = JSON.parse(params[:finding])\r\n        \r\n        \r\n        finding_model = models[params[:finding_model]]\r\n        \r\n        finding = finding_model.find(fx[\'id\'])\r\n        unless finding\r\n            finding = finding_model.create fx\r\n        end\r\n        \r\n        list = record[params[:record_field].to_sym]\r\n        list = [] unless list\r\n        list << finding.id\r\n        \r\n        record.update_attributes params[:record_field].to_sym => list\r\n        \r\n        \r\n        if params[:finding_image]\r\n            \r\n           title = params[:disease]\r\n           \r\n           list = finding[params[:finding_image]]\r\n           attm = models[:attachment]\r\n           attm.find(list).each_with_index do |i,index| \r\n           \r\n        #   if index%2==0\r\n            \r\n        #     title = params[:disease]\r\n        #     else\r\n        #     title = params[:location]\r\n        #     end\r\n           adsfadsfadsf\r\n           title = params[:location]\r\n\r\n\r\n           i.update_attributes :title=>title.humanize\r\n           \r\n           \r\n           \r\n           end\r\n            \r\n        end\r\n        \r\n        \r\n        result[:record_field] = params[:record_field] \r\n        result[:finding] = finding.id \r\n        result[:next_finding] = finding_model.new.id\r\n        result[:record] = record\r\n    end\r\n    \r\n    if params[:status]\r\n        \r\n        \r\n            models[:appointment].find(result[:app_id]).update_attributes :status=>\'Recovery\'\r\n        \r\n    end\r\n\r\n    if params[:start]\r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        emodel = ehr.load_model\r\n        \r\n        patient_model = emodel[:patient]\r\n        module_model = emodel[:patient_module]\r\n        \r\n        patient = patient_model.where(:hn=>params[:ref]).first\r\n        \r\n        date = Date.to_mongo(params[:start])\r\n        m = module_model.where(:parent_id=>params[:parent_id], :module_name=>\"\\\\#{@current_project.name}#\\\\#{params[:model]}\",:patient_id=>patient.id).first()\r\n        result[:module_name]= \"\\\\#{@current_project.name}#\\\\#{params[:model]}\"\r\n        result[:parent_id]= params[:parent_id]\r\n        \r\n        result[:patient_id] = patient.id\r\n        result[:date] = date\r\n        result[:m] = m\r\n        r = nil\r\n        if m\r\n          ma = module_model.find(m[\'parent_id\'])\r\n          app = models[:appointment].find(ma.module_id)\r\n          app.update_attributes :status=>\'Processing\'\r\n          r = model.collection.find(\"_id\"=>m[\'module_id\']).first()\r\n          result[:record]  = r\r\n        end\r\n        if r and params[:img]\r\n          attm = models[:attachment]\r\n           \r\n          result[:images] = attm.find(r[params[:img]]).collect{|i|  i }  \r\n\r\n           \r\n        end\r\n        \r\n        \r\n        \r\n     \r\n\r\n    end\r\n    \r\n       \r\n           scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n            map = {}\r\n            findings = []\r\n            \r\n            ids = []\r\n            \r\n            r = record unless r\r\n            if r \r\n                \r\n                for i in scope_list\r\n                    ids+= r[i] if r[i]\r\n                end\r\n                \r\n                result[:ids] = ids\r\n                \r\n                models[:colonoscopy_scope].find(ids).each do |i|\r\n                    map[i.id.to_s] = i \r\n                end\r\n               \r\n             index = 0   \r\n                  \r\n            for i in scope_list\r\n                \r\n                \r\n                for j in r[i]\r\n                \r\n                index+=1\r\n                t = {:loc=>i}\r\n                t2 = i.split(\"_\")[0]\r\n                lesion = map[j.to_s]\r\n                t[:title] = \"#\\\\#{index}. \\\\#{lesion[config[:disease_field]]} at \\\\#{t2.humanize}\"\r\n                t[:id] = j.to_s\r\n                findings << t\r\n                    \r\n                end\r\n                \r\n            end\r\n               \r\n               result[:findings] = findings\r\n            end\r\n           \r\n        \r\n        \r\n    \r\n\r\n%><%=result.to_json.html_safe%>',NULL,NULL,NULL,'2016-08-01 02:22:46','2016-08-01 02:22:46','live_api','*'),(2444,'print',949,3,'<%= this.print_partial.html_safe %>\r\n<% if @current_role!=\'developer\' %>\r\n<script>\r\n    var millisecondsToWait = 2000;\r\n    setTimeout(function() {\r\n        window.print();\r\n    }, millisecondsToWait);\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2016-08-01 04:44:12','2016-08-01 04:44:12','print',''),(2445,'print_partial_bk',949,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    \r\n    gender = \'NA\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'Male\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'Female\'\r\n    end\r\n    \r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # check pre-op exist ?\r\n    x_pre_op = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id], :module_name=>\"\\\\#{@current_project.name}#pre_op\").first\r\n    r_pre_op = nil\r\n    if x_pre_op\r\n        r_pre_op = get_model[:pre_op].find(x_pre_op[:module_id])\r\n    end\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    map_ind = {}\r\n    map_ind[\'\']  = \'N/A\'\r\n    map_ind[nil] = \'N/A\'\r\n    model[:indication].all.each do |i|\r\n        map_ind[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    # r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    # r_app = model[:appointment].find(r_parent[:module_id])\r\n    r_app = model[:appointment].find(params[:id])\r\n    \r\n    \r\n    def get_render_value(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return \'-\'\r\n        else\r\n            return render_value(f.to_s)\r\n        end\r\n    end\r\n    \r\n    def get_value(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return \'-\'\r\n        else\r\n            return @record[f]\r\n        end\r\n    end\r\n    \r\n    def is_exist(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return false\r\n        else\r\n            return true\r\n        end\r\n    end\r\n    \r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:all_pat_mod] = r_pat_mod\r\n        # res[:patient_innovian] = r_inn\r\n        # res[:pat_inn] = m_inn\r\n        res[:app] = r_app\r\n        res[:this_record] = this_rec\r\n        res[:project] = @current_project\r\n        res[:project_params] = eval(@current_project[:params])\r\n        \r\n        res[:dx] = this_rec[:diagnosis_note]\r\n        res[:px] = get_model[:pacu_record].find(this_rec[:pacu_record])\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px; line-height:20px;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 