 / <%= render_value \'hpv_positive\' %></v>\r\n							                <% if hpvp == \'3\' %>\r\n							        <v> / <%= this_rec[:hpv_other_high_risk] %></v>\r\n							                <% end %>\r\n							        <% end %>\r\n							    </td>\r\n							</tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n\r\n			<div style=\"display:block;\">\r\n			<!-- Main Content -->\r\n				<table width=\"50%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left\">\r\n				    <tr>\r\n				        <td valign=\'top\'>\r\n				            <span class=\"intro \">List</span><br/>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td>\r\n				            <span class=\'intro tab\'>Adequacy : </span> <v><%= get_render_value(\'indication\') %></v> <br/>\r\n				        </td>\r\n				    </tr>\r\n							\r\n                    <tr>\r\n                        <td>\r\n                            <%# obj.to_json.html_safe %>\r\n                        </td>\r\n                    </tr>\r\n                </table>\r\n				\r\n				<div class=\"clear\"></div>\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n\r\n		<div class=\"clear\"></div>\r\n	</div>\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-08-01 04:55:30','2016-08-01 04:55:30','print_partial_bk',''),(2446,'index',1001,2,'<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n \r\n date = Time.now\r\n date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n%>\r\n<div class=\"span12 alert\"><%=date.strftime(\"%d/%m/%Y\")%></div>\r\n\r\n\r\n<%\r\n ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n model = ehr.load_model\r\n patient_model = model[:patient]\r\n module_model = model[:patient_module]\r\n\r\n models = get_model\r\n ap_model = models[:appointment]\r\n    \r\n aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n \r\n patient_filter = []\r\n \r\n if request.post? and params[:search]\r\n \r\n    q = params[:search][:q]\r\n \r\n    patient_filter = patient_model.where(:hn=>q.strip).all.collect{|i| i.id}\r\n\r\n \r\n end\r\n \r\n module_map = {}\r\n module_model.where(:module_id=>aps.collect{|i| i.id}).all.collect{|i| module_map[i.module_id] = i}\r\n \r\n patient_map = {}\r\n patient_model.where(:id=>module_map.values.collect{|i| i.patient_id}).all.collect{|i| patient_map[i.id] = i}\r\n \r\n aps.collect! do |i|\r\n     \r\n appm = module_map[i.id]\r\n \r\n res = {:app=>i}\r\n \r\n if appm \r\n      p = patient_map[appm.patient_id]\r\n      next unless p\r\n      res[:p] = p \r\n      \r\n      res[:name] = \"\\\\#{p.hn } &nbsp;&nbsp;&nbsp;&nbsp;\\\\#{p.prefix_name} \\\\#{p.first_name} \\\\#{p.last_name}\" .html_safe if p\r\n end \r\n \r\n \r\n if patient_filter.size==0 or patient_filter.index(p.id)\r\n    res\r\n else\r\n    nil\r\n end\r\n\r\n end\r\n \r\n aps.compact!\r\n\r\n%>\r\n\r\n<% if request.post? and aps.size==1%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=patient_record?id=<%=aps[0][:app].id%>\" />\r\n<% end %>\r\n\r\n<%\r\n \r\n groups = {}\r\n \r\n for i in aps\r\n    \r\n    app = i[:app]\r\n    status = app.status\r\n    \r\n    groups[status] = [] unless groups[status]\r\n    res = groups[status]\r\n        \r\n    res << i\r\n    \r\n     \r\n end\r\n\r\n%>\r\n\r\n<% \r\n\r\n style_tab = {}\r\n style_tab[\'Processing\'] = \'#dbdef7\'\r\n style_tab[\'Preparing\'] = \'#ebe9d3\'\r\n style_tab[\'Arrived\'] = \'#ebe9d3\'\r\n style_tab[\'Recovery\'] = \'#e0f1d8\'\r\n style_tab[\'Appointed\'] = \'#fff\'\r\n \r\n \r\n\r\n%w{ Processing Preparing  Arrived  Appointed Recovery }.each do |k,g|\r\n    \r\n    g = groups[k]\r\n    \r\n    %>\r\n    \r\n<div class=\"left alert-info \" style=\"width:100%;;border:0px solid;background-color:<%=style_tab[k]%>\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n                <%=k%> \r\n	    <div class=\"pull-right\"><i class=\"\"><%=g.size if g%> Patient(s)</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        \r\n\r\n    <%\r\n    \r\n    if g \r\n        \r\ng.each_with_index do |i,index| \r\n    \r\n    app = i[:app]\r\n    p = i[:p]\r\n%>\r\n<%\r\nif index%2==0 \r\n%>\r\n<div class=\"row-fluid\" >\r\n<% end %>\r\n\r\n\r\n<div class=\"span6\">\r\n<%=link_to i[:name], \"javascript:\",:onmousedown=>\"window.location=\'patient_record?id=\\\\#{app.id}\'\", :class=>\"btn btnx \",:style=>\"width:340px\"%>\r\n</div>\r\n\r\n<%\r\nif index%2==1 \r\n%>\r\n</div>\r\n<div class=\"span12\">&nbsp;</div>\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n\r\n<%\r\nif g.size%2==1 \r\n%>\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n\r\n\r\n<% end %>\r\n\r\n</div>\r\n\r\n\r\n	    </div>\r\n\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<% end %>\r\n<style>\r\ndiv#toolbar\r\n{\r\nheight: 100px;\r\nright: 00px;\r\nbottom: -10px;\r\nposition: fixed;\r\nwidth:20px;\r\nz-index: 1;\r\n}\r\n\r\n</style>\r\n<div id=\"toolbar\" class = \"alert\" style=\"font-size:0.5em;background:#1e4862\">\r\n    <%=link_to \'<i class=\"splashy-arrow_large_up\"></i>\'.html_safe,\'javascript:\',:id=>\"s_up\", :class=>\"btn btn-large\" ,:style=>\"\"%><br/><br/>\r\n    <%=link_to \'<i class=\"splashy-arrow_large_down\"></i>\'.html_safe,\"javascript:\",:id=>\"s_down\" ,:class=>\"btn btn-large\",:style=>\"\" %>\r\n</div>\r\n<script>\r\n\r\nvar status=null;\r\nvar ac = 20;\r\n\r\n$(\'#s_up\').mousedown(function(){\r\n   status=\'up\'\r\n});\r\n\r\n$(\'#s_down\').mousedown(function(){\r\n    status=\'down\'\r\n});\r\n\r\n$(\'#s_up\').mouseup(function(){\r\n   status=\'\'\r\n   ac = 10;\r\n});\r\n\r\n$(\'#s_down\').mouseup(function(){\r\n    status=\'\'\r\n    ac = 10;\r\n});\r\n\r\n$(\'#to_library\').mousedown(function(){\r\n  $(window).scrollTop($(\'#library-image\').offset().top);\r\n});\r\n\r\n\r\nfunction update_scroll(){\r\n    if(status==\'up\'){\r\n      if(window.pageYOffset-ac<0){status=\'\';ac=10;}\r\n      window.scrollTo(window.pageXOffset, window.pageYOffset-ac);\r\n     \r\n      ac+=3\r\n    }\r\n    if(status==\'down\'){\r\n      if(window.pageYOffset+ac>$(document).height()-$(window).height()){status=\'\';ac=10}\r\n      \r\n      window.scrollTo(window.pageXOffset, window.pageYOffset+ac);\r\n      ac+=3\r\n    }\r\n    //   console.log(status)\r\n    \r\n}\r\n\r\n    setInterval(update_scroll, 100);\r\n\r\n<%# params.inspect %>\r\n\r\n</script>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-08-01 06:10:36','2016-08-01 06:10:36','index','*'),(2447,'patient_record',1001,2,'<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n \r\n date = Time.now\r\n date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n\r\n ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n model = ehr.load_model\r\n patient_model = model[:patient]\r\n module_model = model[:patient_module]\r\n\r\n models = get_model\r\n ap_model = models[:appointment]\r\n    \r\n#  aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n \r\n patient_filter = []\r\n \r\n \r\n app = ap_model.find(params[:id])\r\n \r\n if app\r\n     \r\n appm = module_model.where(:module_id=>app.id).first\r\n\r\n services =  @current_project.get_services_by_abstract(\'ehr.emr.LiveDocument\').collect{|i| i if  i.name!=\'appointment\'}.compact \r\n p = patient_model.find appm.patient_id\r\n \r\n hn = p.hn\r\n patient_name = \"\\\\#{p.prefix_name} \\\\#{p.first_name} \\\\#{p.last_name}\" \r\n admit_id = app.id\r\n\r\n\r\n %>\r\n<div class=\"row-fluid alert\" s