\'} %>\r\n</div>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n </div>\r\n\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n<%#render :inline=>this.index_content%>\r\n\r\n<script>\r\n    refresh_remote();\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2016-08-01 06:10:59','2016-08-01 06:10:59','patient_record',''),(2448,'layout',1001,4,'<html>\r\n    <head>\r\n        <%=include_header%>\r\n        <style>\r\n            \r\n            .box{\r\n                border:0px solid;\r\n            };\r\n            \r\n            .xxx{\r\n                background:rgb(0,232,251);\r\n            }\r\n            .search{\r\n                height:2em;\r\n            }\r\n            .btnx{font-size:1.5em ;line-height:1.5em ;height:4em;display:table-cell};\r\n            .pbox{\r\n                background:#233643;\r\n                color:#fff;\r\n                border:none;\r\n            }\r\n            \r\n            .ptab{\r\n                padding: 8px 35px 8px 14px;\r\nmargin-bottom: 18px;\r\ncolor: #fff;\r\ntext-shadow: 0 1px 0 rgba(255, 255, 255, 0.5);\r\nbackground-color: #1e4862;\r\nborder: 0px solid #fbeed5;\r\n-webkit-border-radius: 4px;\r\n-moz-border-radius: 4px;\r\nborder-radius: 4px;\r\n            }\r\n            \r\n        </style>\r\n        \r\n    </head>\r\n    \r\n    <body class=\"\" style=\"background-color:#fff;;padding:0px\">\r\n       \r\n        <div class=\"header\" style=\"background:#fff;padding-left:20px\">\r\n        <div class=\"row-fluid\">\r\n        <div class=\"span6\">\r\n        <div id=\"header-panel\" >\r\n        \r\n        </div>\r\n        </div>\r\n        <div class=\"span3\">&nbsp;</div>\r\n        \r\n        <div class=\"span5\" style=\"border:0px solid black; ;  text-align: center;  display: table;padding-top:20px\">\r\n            \r\n            <div style=\"vertical-align: middle; display: table-cell; border:0px solid;height:1em \">\r\n            <%=form_for :search,:url=>\"../Live/search\" ,:html=>{:id=>\'hn_search\'} do |f| %>\r\n            <%= f.text_field :q ,:class=>\"search\",:id=>\'search_value\'%>\r\n            <%= f.submit \'Search\' ,:class=>\'btn\',:style=>\"vertical-align:text-bottom\"%>\r\n            \r\n            <a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#search\" class=\"btn btn-success\" style=\"vertical-align:text-bottom\">\r\n                <i class=\"icon-th\"></i> HN\r\n            </a>\r\n            <% end %>\r\n            </div>\r\n          \r\n        </div>\r\n            \r\n        </div>\r\n            \r\n     \r\n        \r\n        </div>\r\n        <div class=\"row-fluid\">\r\n		<div id=\"\" class=\"span12 box\">\r\n		        <%= render :inline=>this.index_content %>\r\n\r\n        <%=yield :content %>\r\n        \r\n        </div>\r\n\r\n        <div id=\"header-content\">\r\n        <%=yield :header%>\r\n        </div>\r\n        <script>\r\n        $(\'#header-content\').appendTo(\"#header-panel\");\r\n        </script>\r\n\r\n\r\n        \r\n        </div>\r\n          \r\n            <div id=\"heder_content\">\r\n</div>\r\n<div class=\"modal hide\" id=\"search\"  style=\"display: none;width:200px\">\r\n	<div class=\"modal-header\">\r\n		<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n		<h3>HN Number</h3>\r\n	</div>\r\n	<div class=\"modal-body\">\r\n<form name=\"Calc\" id=\"calc\">\r\n	<div class=\"formSep control-group input-append\">\r\n		<input type=\"text\" style=\"width:95px;font-size:1.2em;height:2.1em\" name=\"Input\" ><button type=\"button\" class=\"btn btn-large\" name=\"clear\" value=\"c\"  onclick=\"Calc.Input.value = \'\'\"><i class=\"icon-remove\"></i></button>\r\n	</div>\r\n	<div class=\"control-group\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"seven\" value=\"7\" onmousedown=\"Calc.Input.value += \'7\'\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"eight\" value=\"8\" onmousedown=\"Calc.Input.value += \'8\'\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"nine\" value=\"9\" onmousedown=\"Calc.Input.value += \'9\'\">\r\n\r\n	</div>\r\n	<div class=\"control-group\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"four\" value=\"4\" onmousedown=\"Calc.Input.value += \'4\'\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"five\" value=\"5\" onmousedown=\"Calc.Input.value += \'5\'\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"six\" value=\"6\" onmousedown=\"Calc.Input.value += \'6\'\">\r\n	\r\n	</div>\r\n	<div class=\"control-group\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"one\" value=\"1\" onmousedown=\"Calc.Input.value += \'1\'\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"two\" value=\"2\" onmousedown=\"Calc.Input.value += \'2\'\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"three\" value=\"3\" onmousedown=\"Calc.Input.value += \'3\'\">\r\n\r\n	</div>\r\n	<div class=\"formSep control-group\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"dot\" value=\"/\" onmousedown=\"Calc.Input.value += \'/\'\">\r\n		<input type=\"button\" class=\"btn btn-large\" name=\"zero\" value=\"0\" onmousedown=\"Calc.Input.value += \'0\'\">\r\n		<a href=\"javascript:submit()\" onmousedown=\"\" class=\"btn btn-large btn-success\" ><i class=\"icon-search\"></i></a>\r\n	</div>\r\n	<script>\r\n	    function submit(){\r\n	        \r\n	        $(\'#search_value\').val(Calc.Input.value);\r\n	        $(\'#hn_search\').submit()\r\n	    }\r\n	</script>\r\n</form>\r\n\r\n	</div>\r\n\r\n</div>    \r\n\r\n<script>\r\n            $(document).ready(function(){\r\n                $(\'#search_value\').focus()\r\n            });\r\n                \r\n            </script>\r\n    </body>\r\n</html>',NULL,NULL,NULL,'2016-08-03 17:44:12','2016-08-03 17:44:12','layout',''),(2449,'ceo_message',965,2,'\r\n<center><h2>สาร์นจากประธาน </h2><br />\r\n<img src=\"/esm/thks_web/www/assets/vi.jpg\" width=\"150\"></center>\r\n<p>ตั้งแต่ปี 1979 เป็นต้นมา ประเทศสวีเดนได้เริ่มจัดเก็บข้อมูลการผ่าตัดเปลี่ยนข้อเทียม  มีการดำเนินการอย่างต่อเนื่อง จนสามารถเก็บรวบรวมครบ 100% และรายงานผลการจัดเก็บข้อมูล  แพทย์ นักวิจัยได้นำไปอ้างอิงงานวิจัยเป็นจำนวนมาก เป็นที่รับรู้จากทั่วโลกว่า  การจัดเก็บข้อมูลการผ่าตัดข้อเทียม ช่วยสะท้อนให้เห็นความเป็นจริง  ความเป็นไปของการผ่าตัดข้อเทียมได้เป็นอย่างดี ทำให้แพทย์ผู้เกี่ยวข้อง  รวมถึงผู้บริหารด้านสาธารณสุข ตระหนัก นำข้อมูลไปพัฒนาการให้บริการรักษาด้านข้อเทียมให้ดีขึ้นเรื่อยๆ  อย่างต่อเนื่อง ตรวจพบวิธีการผ่าตัดที่ไม่เกิดประโยชน์  ข้อเทียมที่มีผลการรักษาไม่ดี ทำให้ได้รับการพัฒนา ปรับปรุงให้ดีขึ้น  ซึ่งสุดท้ายแล้ว  ผู้ป่วยจะได้รับประโยชน์โดยตรงจากการให้บริการทางการแพทย์ที่อยู่พื้นฐานของข้อมูลที่เป็นจริง <br />\r\n  หลายประเทศทั่วโลก  เห็นความสำคัญของการพัฒนาระบบเก็บข้อมูลฐานขนาดใหญ่ระดับประเทศ  เช่นประเทศออสเตรเลีย เป็นอีกประเทศหนึ่งที่มีขนาดใหญ่  และประสบความสำเร็จมากในการรวบรวมข้อมูลการผ่าตัดได้ครบ 100% ทุกปีจะมีรายงานผลการเก็บข้อมูลออกสู่สาธารณะสม่ำเสมอ  ประเทศที่พัฒนาแล้วทั่วทั้งยุโรป อเมริกา รวมถึงเอเชีย ได้แก่ ญี่ปุ่น เกาหลี จีน อินเดียเป็นต้น  ล้วนให้ความสำคัญ และพยายามพัฒนาระบบการจัดเก็บข้อมูลการผ่าตัดข้อเทียม  เพื่อประโยชน์กับประชาชนในประเทศของตน<br />\r\n  ในประเทศไทย  มีความพยายามที่จะจัดเก็บข้อมูลการผ่าตัดข้อเทียม ตั้งแต่ปี 2005 แต่ขาดความต่อเนื่องและได้เลิกไปในที่สุด<br />\r\n  ชมรมศัลยแพทย์ข้อสะโพกและข้อเข่าแห่งประเทศไทย  ได้มีมติที่ประชุมให้ทดลองพัฒนาระบบการจัดเก็บข้อมูลการผ่าตัดข้อเทียมอีกครั้ง  เมื่อ 22-23 มค. 2015 การพัฒนาในครั้งนี้  เริ่มต้นจาก รพ.ตำรวจ และรพ.เลิดสินก่อน ใช้เวลาพัฒนาอย่างต่อเนื่องประมาณ 1  ปี จนระบบฐานข้อมูล และโปรแกรมเสร็จ  จึงได้เริ่มเข้าขั้นที่สองของการพัฒนา  คือทดสอบการใช้งานจริงในรพ.ตำรวจและรพ.เลิดสิน   ชมรมศัลยแพทย์ข้อสะโพกและข้อเข่าแห่งประเทศไทย  จึงได้มีมติต่อเนื่องที่จะแต่งตั้งคณะกรรมการขับเคลื่อนจากสถาบันหลักทั่วประเทศไทย  เพื่อดำเนินการผลักดันในหลายๆด้าน <br />\r\n  การประชุมความเห็นร่วมที่ได้จัดขึ้นที่จังหวัดนครปฐม เมื่อ 24-25 มิย. 2016 ได้มีข้อตกลงร่วมกันที่จะจัดเก็บข้อมูลเท่าที่จำเป็น  เพื่อไม่ให้เพิ่มภาระมากจนเกินไปในแต่ละโรงพยาบาล และมีข้อตกลงสรุปร่วมกันอีกหลายประเด็น  ที่จะนำไปสู่ความสำเร็จในการที่จะให้แพทย์ทุกคนที่สนใจนำไปบันทึกข้อมูล<br />\r\n  ปีนี้  และปีหน้า (2016-2017) คณะกรรมการขับเคลื่อน  จะเน้นในขั้นตอนการ Deployment โปรแกรม  และชักชวนให้แพทย์เข้ามาร่วมกันบันทึกข้อมูลการผ่าตัดเปลี่ยนข้อให้ได้มากที่สุด  ด้วยมาตรการต่างๆ เช่นการขอให้แพทย์ Fellow บันทึกข้อมูล  เพื่อใช้เป็น log book เมื่อสำเร็จการศึกษา อาจารย์แพทย์ทุกสถาบันให้การสนับสนุนจัดเก็บข้อมูลเพื่อการวิจัยด้วย  THKJR  มีการจัดการประชุม  session THKJR (Thai Hip Knee Joint Registry) ในงาน THKS  APOKA 11-13 สค. 2016 ที่โรงแรมแชงกรีล่า  การจัด workshop ในวันที่ 11-12 สค.  ภายในงาน นอกจากนี้ ปลายปี จะจัดทัวร์ไปทำ workshop ที่ขอนแก่น  และต้นปีหน้าที่เชียงใหม่<br />\r\n  ในระยะยาว หวังว่าระบบการจัดเก็บข้อเทียม THKJR นี้  จะเป็นที่ยอมรับมากขึ้น  และมีการสืบทอดขยายเป็นระบบที่ใหญ่ขึ้น โดยร่วมมือกับหน่วยงานที่เกี่ยวข้องเช่นกระทรวงสาธารณสุข  สปสช สปก และหน่วยงานอื่นๆเป็นต้น </p>\r\n<p>                                                                                                                พ.ต.อ.นพ.วิโรจน์  ลาภไพบูลย์พงศ์ <br />\r\n  ประธานกรรมการขับเคลื่อน  THKJR </p>',NULL,NULL,NULL,'2016-08-04 01:56:40','2016-08-04 01:56:40','ceo_message',''),(2450,'document_name',1002,1,'\'member\'',NULL,NULL,NULL,'2016-08-05 04:08:49','2016-08-05 04:08:49',NULL,NULL),(2451,'document_name',1003,1,'\'workshop\'',NULL,NULL,NULL,'2016-08-05 04:10:25','2016-08-05 04:10:25',NULL,NULL),(2452,'reset',365,3,'<%\r\n    model = get_model(this.table_name)\r\n    model.destroy_all\r\n    \r\n    if params[:return]\r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=<%= params[:return] %>\">\r\n<%\r\n    else\r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=index\">\r\n<%\r\n    end\r\n%>\r\n\r\n',NULL,NULL,NULL,'2016-08-05 04:17:56','2016-08-05 04:17:56','reset',''),(2453,'register_check',965,2,' <div style=\"text-align:center\">\r\n <img src=\"/esm/thks_web/www/assets/111984.jpg\" width=\"220\">\r\n                  \r\n        <%\r\n          models = get_model \r\n          workshop = models[:workshop].first\r\n          \r\n        #   members = models[:member].where(:workshop_id=>workshop.id).all\r\n          \r\n          \r\n          if request.post?\r\n              \r\n              members = models[:member].where(:workshop_id=>workshop.id, :med_id=>params[:query][:q]).all\r\n\r\n        a = {}\r\n        a[\'1\'] = \'1\'\r\n        a[\'2\'] = \'2\'\r\n        a[\'3\'] = \'3\'\r\n\r\n        \r\n        if members.size >0 \r\n          \r\n        %>\r\n        <center><h4>รายชื่อผู้ลงทะเบียน</h4></center>        \r\n        \r\n        <%= tabular :data=>members,:model=>%w{name med_id work_office program status} do |row,out|\r\n        \r\n        \r\n        \r\n        \r\n        out[-2] = a[row.program]\r\n        out[0] = \"\\\\#{row.first_name} \\\\#{row.last_name}\"    \r\n        out[-1] = \'<font color=\"red\">อยู่ระหว่างการพิจารณา</font>\'\r\n        out[-1] = \'<font color=\"green\">ท่านผ่านการพิจารณา</font>\' if row.status==\'1\'\r\n        \r\n        out\r\n        end\r\n        %>\r\n        \r\n        \r\n        <% else %>\r\n        <center>\r\n        <font color=\"red\" style=\"font-size:1.5em\">\r\n            ไม่พบข้อมูลการลงทะเบียน\r\n        </font>\r\n            \r\n<meta http-equiv=\"refresh\"  content=\"0; url=register_check\">\r\n\r\n            \r\n        </center>\r\n        \r\n        <% end %>\r\n        <% else %>\r\n        \r\n        \r\n         <center><h4>\r\n         ตรวจสอบสถานะการลงทะเบียน\r\n         </h4>\r\n         \r\n        \r\n        <%=form_for :query , :url=>\'register_check\' do |f|  %>\r\n    <div style=\"width:300px\">\r\n       <label style=\"color:#fff\">กรุณาใส่เลขที่ใบประกอบวิชาชีพ </label> <%=f.text_field :q %> \r\n       <%=f.submit \'ค้นหา\' %>\r\n       </div>\r\n       </center> \r\n        <% end %>\r\n       \r\n       <% end %>\r\n         \r\n        <br/>\r\n        \r\n        \r\n        <a href=\"index\" class=\"btn btn-lg\"><i class=\"fa fa-globe\" ></i> Back to home <i class=\"fa fa-globe\" ></i></a>\r\n                  \r\n                  <br />&nbsp;\r\n                  \r\n</div>',NULL,NULL,NULL,'2016-08-05 05:11:43','2016-08-05 05:11:43','register_check','*'),(2454,'register_list',965,2,' <div style=\"text-align:center\">\r\n <img src=\"/esm/thks_web/www/assets/111984.jpg\" width=\"220\">\r\n                  \r\n        <%\r\n          models = get_model \r\n          workshop = models[:workshop].first\r\n          \r\n          members = models[:member].where(:workshop_id=>workshop.id).all\r\n          \r\n        %>\r\n         <center><h4>รายชื่อผู้ลงทะเบียน</h4></center>        \r\n        \r\n        <%= tabular :data=>members,:model=>%w{first_name last_name work_office}  %>\r\n        <br/>\r\n        <a href=\"index\" class=\"btn btn-lg\"><i class=\"fa fa-globe\" ></i> Back to home <i class=\"fa fa-globe\" ></i></a>\r\n                  \r\n                  <br />&nbsp;\r\n                  \r\n</div>',NULL,NULL,NULL,'2016-08-05 05:12:45','2016-08-05 05:12:45','register_list',''),(2455,'register',965,2,'	<h2 class=\"single-animate animate-features-1\">Register</h2>\r\n<style>\r\n\r\n    \r\n    label {\r\n\r\n    color: #111;\r\n    }\r\n    .k-textbox{\r\n        background-color:#fff;\r\n        height:25px;\r\n    }\r\n    .document-border {\r\n    width: 100%;}\r\n    .form-data-content{\r\n        width:100%;\r\n    }\r\n   #workshop_id {display:none}\r\n    \r\n    #status {display:none}\r\n    .w-box-header {\r\n    height: 100%;\r\n     line-height: 100%;\r\n    /border: 0px solid #fff;\r\n    }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\" >\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">ลงทะเบียน \r\n<span id=\"workshop-title\"></span></h3>\r\n<div class=\"pull-right\">\r\n<%# link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"background:#none\">\r\n\r\n<div style=\"border:0px solid\" >\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(\'member\')\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document \'member\'\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<br />\r\n<center><h4> ได้รับข้อมูลการลงทะเบียนของท่านเรียบร้อยแล้ว กรุณาตรวจสอบสถานะ\r\n\r\n</h4></center>\r\n<br />&nbsp;\r\n<meta http-equiv=\"refresh\" content=\"3;url=<%= return_url.html_safe %>\" />\r\n\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>\'register\' do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = model.new\r\n   @document =  get_document \'member\' \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</div>\r\n<div style=\"float:left\"><p>\r\n\r\n<%= f.submit \'ลงทะเบียน\' %> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<br/>\r\nสอบถามรายละเอียดเพิ่มเติมได้ที่<br/>\r\n\r\n<h2>ชมรมศัลยแพทย์ข้อสะโพกและข้อเข่าแห่งประเทศไทย</h2>\r\n 492/1 ถ.พระราม1 <br />แขวงปทุมวัน เขตปทุมวัน กมม. 10330 <br />โทร.02-253-5836  email.thkjoint@gmail.com\r\n\r\n</p>\r\n</div>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n\r\n<script>\r\n    <%\r\n        models = get_model \r\n        workshop = models[:workshop].first(:opened=>\'true\')\r\n    %>\r\n    \r\n    $(\'#data-workshop_id\').val(\'<%=workshop.id%>\')\r\n    $(\'#workshop_id\').hide()\r\n    $(\'#workshop-title\').html(\'<%=workshop.name%>\')\r\n    $(\'#status\').hide()\r\n\r\n    \r\n    \r\n //     var obj2 =  $(\'#update_program_item_1\');\r\n   // obj2.attr(\'disabled\', true);\r\n //   obj2.parent().css(\"color\",\"gray\")\r\n//    obj2.parent().append(\"<span style=\'color:red\'>เต็ม</span>\");\r\n        \r\n  //     var obj2 =  $(\'#update_program_item_2\');\r\n  //  obj2.attr(\'disabled\', true);\r\n //   obj2.parent().css(\"color\",\"gray\")\r\n  //  obj2.parent().append(\"<span style=\'color:red\'>เต็ม</span>\");\r\n  //  obj2.parent().css(\"text-decoration\",\"line-through\")\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2016-08-05 05:17:15','2016-08-05 05:17:15','register','*'),(2456,'document_name',1004,1,'\'post\'',NULL,NULL,NULL,'2016-08-06 06:19:21','2016-08-06 06:19:21',NULL,NULL),(2457,'post',965,2,'\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    if params[:id]\r\n        \r\n    post = models[:post].find params[:id]\r\n    attm = models[:attachment]\r\n    \r\n    atts = {}\r\n    attm.find(post.image).collect{|i| atts[i.title] = i.path }\r\n\r\n    \r\n    template = post.content.split( /[\\\\[\\\\]]+/ )\r\n    \r\n    %>\r\n    <% template.inspect %> \r\n    <%\r\n    \r\n    \r\n    template.collect! do |i| \r\n    \r\n       i = i.gsub(/&nbsp;/, \" \")\r\n       t = i.split \r\n       if t[0] ==\'image\' and img = atts[t[1]]\r\n           \r\n            if t.size==2\r\n            image_tag(img)\r\n            else\r\n            image_tag(img, :width=>t[2].to_i , :style=>\'padding:10px\')\r\n            end\r\n        else\r\n        i \r\n        end\r\n       \r\n    end\r\n    \r\n    content = template.compact.join(\" \")\r\n    \r\n    \r\n%><hr />\r\n<h1>\r\n<%= post.title.html_safe %></h1><hr />\r\n<p>\r\n    <%=content.html_safe %>\r\n</p><br />\r\n<center><button><a href=\"index\" class=\"btn\" style=\"font-size:20px\"> [ Back to home ] </a></button></center>\r\n<% end %>\r\n\r\n<%  atts.inspect  %>',NULL,NULL,NULL,'2016-08-06 06:26:31','2016-08-06 06:26:31','post','*'),(2461,'layout',1004,4,'<!DOCTYPE html>\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n    <meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1\" />\r\n    <meta name=\"description\" content=\"\" />\r\n    <meta name=\"author\" content=\"\" />\r\n      <!--[if IE]>\r\n        <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\">\r\n        <![endif]-->\r\n\r\n     <title>THKJR</title>\r\n     <%= include_header %>\r\n     <%# javascript_include_tag \"application\"  %>\r\n    \r\n    <!-- BOOTSTRAP CORE STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/bootstrap.css\" rel=\"stylesheet\" />\r\n      <!-- VEGAS SLIDESHOW STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/vegas/jquery.vegas.min.css\" rel=\"stylesheet\" />\r\n     <!-- FONTAWESOME STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/font-awesome.min.css\" rel=\"stylesheet\" />\r\n    <!-- CUSTOM STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/style.css\" rel=\"stylesheet\" />    \r\n    <!-- GOOGLE FONT -->\r\n     <link href=\"/esm/thks_web/www/assets/thsarabunnew.css\" rel=\"stylesheet\" />  \r\n     <!-- HTML5 shim and Respond.js IE8 support of HTML5 elements and media queries -->\r\n    <!--[if lt IE 9]>\r\n      <script src=\"https://oss.maxcdn.com/libs/html5shiv/3.7.0/html5shiv.js\"></script>\r\n      <script src=\"https://oss.maxcdn.com/libs/respond.js/1.3.0/respond.min.js\"></script>\r\n    <![endif]-->\r\n<style>\r\nbody {}\r\n.bbox{ width:150px; float:left; padding:10px; margin-right:20px}\r\n.ss{padding:0px;;margin-right:5px; width:180px; font-size:1em}\r\n.sm {font-size:0.8em}\r\ninput, button, select, textarea {color:#000;}\r\nlabel {    font-weight: normal;}\r\n.navbar-inverse {\r\n    background-color: rgb(255, 