nding_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n\r\n    colo_m = module_model.where(:parent_id=>appm.values.collect{|i| i.id}, :module_name=>\"\\\\#{@current_project.name}#colonoscopy\").all\r\n    colo_p = {}\r\n    colo_m.each do |i|\r\n        colo_p[i.patient_id] = i.module_id \r\n    end\r\n    \r\n    \r\n\r\n    \r\n    \r\n    colos =  models[:colonoscopy].find(colo_m.collect{|i| i.module_id})\r\n    colomap = {}\r\n    scopes = []\r\n    \r\n    coloms = {}\r\n    colos.each do |i|\r\n         \r\n         colomap[i.id] = i\r\n         scope_list.each do |j|\r\n            coloms[i.id] = [] unless coloms[i.id]\r\n            coloms[i.id] += i[j] if i[j]\r\n           \r\n            scopes += coloms[i.id] if coloms[i.id]\r\n         end\r\n    end\r\n    scm = {}\r\n    \r\n    models[:colonoscopy_scope].find(scopes).each do |i|\r\n    scm[i.id] = i\r\n    end\r\n    \r\n    l = {}\r\n    \r\n  \r\n \r\n    \r\n    # models[:colonoscopy_scope].find(colom)\r\n    \r\n    \r\n    \r\n \r\n    \r\n    \r\n    # abnormal_type\r\n    total_register =0\r\n    total_register += groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    total_register += groups[\'Processing\'].size if groups[\'Processing\']\r\n    total_register += groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    \r\n    total_complete = 0 \r\n    total_complete = groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    total_cancer = 0\r\n    total_polyp  = 0 \r\n    total_waiting = 0 \r\n    total_waiting = groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    \r\n   \r\n    # coloms.each_pair do |c,l|\r\n         \r\n    # end\r\n    \r\n    data = []\r\n    \r\n    coloms.keys.each do |k|\r\n        v = coloms[k].collect{|i| scm[i] }\r\n        l[k.to_s] = v\r\n        total_cancer+=1 if v and v.index(\'Cancer\') \r\n        total_polyp+=1 if v and v.index(\'Polyp\')\r\n\r\n    end\r\n\r\n    mm = {}\r\n    mm2 = {}\r\n    module_model.where(:module_id=>coloms.keys).all.each do|i|\r\n        mm[i.module_id.to_s] = i.patient_id\r\n        mm2[i.module_id.to_s] = i.id\r\n    end\r\n    \r\n    pm = {}\r\n    patient_model.find(mm.values).each do |i|\r\n      pm[i.id] = i \r\n    end\r\n    \r\n    providers = {}\r\n    models[:provider].all.each do |i|\r\n        providers[i.id] = i.name \r\n    end\r\n    \r\n\r\n    # scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n#     1|Rectum\r\n# 2|Sigmoid\r\n# 3|Descending colon\r\n# 4|Transvers colon\r\n# 5|Ascending colon\r\n# 6|Cecum\r\n# 7|Terminal ileum\r\n    \r\n    scope_map = {}\r\n    scope_list.each_with_index do |i,index|\r\n        scope_map[(index+1).to_s] = i.split(\"_\")[0].humanize\r\n    end\r\n    \r\n    gender_map = {\'1\'=>\'ชาย\', \'2\'=>\'หญิง\'}\r\n\r\n%>\r\n\r\n<body>\r\n\r\n<div class=\"bbody\" style=\"font-size:14px\">\r\n\r\n<div class=\"bhead\">\r\n \r\n\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"margin-left:auto;margin-right:auto;font-size:0.8em\">\r\n<tr>\r\n  <th colspan=\"16\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/cusys/mobile/trang_logo.png\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h2>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลตรัง ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์\r\n  </h2>\r\n\r\n<h1>&nbsp;</h1></th>\r\n  </tr>\r\n<tr>\r\n    <th width=\"10px\">No.</th>\r\n    <th>ชื่อ-สกุล</th>\r\n    <th>HN</th>\r\n    <th>เลขบัตรประชาชน</th><th>Gender</th><th>อายุ</th><th>วันที่ทำ</th>\r\n    <th>Tel</th></td><th>Fit test</th><th>Diagnosis</th><th>Bowel preparation</th><th>กล้อง</th><th>ส่องถึง</th><th>Patho</th><th>แพทย์1</th><th>แพทย์2</th><th>พยาบาล</th><th>Action</th>\r\n</tr>\r\n<% \r\n    index = 0 \r\n    \r\n    list = []\r\n    for i in l.keys \r\n    v = l[i]\r\n    m = mm[i]\r\n    p = pm[m]\r\n    index+=1\r\n    \r\n    r = colomap[colo_p[p.id]]\r\n    lesion = coloms[r.id]\r\n    \r\n    age = 0 \r\n    \r\n    age = ((Time.now - p.birth_date.to_datetime)/3600/365/24).to_i if p.birth_date\r\n    age_class =\"black\"\r\n    age_class = \"red\" if age < 40 or age > 100\r\n    \r\n    sc = scope_map[r.scope]\r\n    \r\n    patho = 0 \r\n   \r\n    if coloms[r.id]\r\n    for x in coloms[r.id]\r\n        patho+=1 if scm[x] and scm[x].patho_number.to_i >0\r\n    end\r\n    end\r\n    \r\n    s = \'-\'\r\n    \r\n    if s = screen_r[screen_map[p.id]]\r\n        s = s.fit_test\r\n    end\r\n    \r\n    line = {:p=>p, :date=>params[:date], :r=>r,  :sc=>sc, :patho=>patho,:age=>age,:s=>s }\r\n    list << line\r\nend\r\nindex = 0\r\n\r\n    list.sort! {|b,a| \r\n        a[:patho]<=>b[:patho]\r\n    }\r\n    \r\n    if params[:poor]\r\n       list.collect!{|i| i if i[:r].quality_of_preparate ==\'Poor\' }.compact!\r\n    end\r\n    \r\n    \r\n    \r\n    for i in list \r\n    \r\n    p = i[:p]\r\n    date = i[:date]\r\n    r = i[:r]\r\n    patho = i[:patho]\r\n    sc = i[:sc]\r\n    index+=1\r\n    age = i[:age]\r\n    \r\n    \r\n   s = i[:s]\r\n    \r\n%>\r\n\r\n    <tr style=\"color:<%=age_class%>\">\r\n    <td><%=index%></td>\r\n    <td><%=p.first_name%> <%=p.last_name%> </td>\r\n    <td><%=p.hn%></td>\r\n    <td><%=p.public_id%></td>\r\n    <td><%=gender_map[p.gender]%></td>\r\n    <td ><%=\"\\\\#{age} ปี \"%> \r\n    <%=p.birth_date if age_class==\'red\'%></td>  \r\n<td><%=params[:date]%></td>\r\n<td><%=p.mobile%></td>\r\n\r\n<td><%=s%></td>\r\n<td><%=r.diagnosis_group%></td>\r\n<td><%=r.quality_of_preparate%></td>\r\n<td><%=r.colonoscope%></td>\r\n<td><%=sc%></td>\r\n<td><%=patho %><%= %></td>\r\n<td><%=providers[r.endoscopist_1]%></td>\r\n<td><%=providers[r.endoscopist_2]%></td>\r\n<td><%=providers[r.nurse]%></td>\r\n        <td><%=link_to \"Show\", \"../Colonoscopy/show?id=\\\\#{r.id}\" %></td>\r\n    </tr>\r\n    \r\n    <% end %>\r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2016-08-15 03:32:46','2016-08-15 03:32:46','patient_report',''),(2494,'report_total',964,2,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Patient Report</title>\r\n<%=include_header%>\r\n<style>\r\n .bbody{ width:100%; margin-left:auto; margin-right:auto;}\r\n .bhead{text-align:center}\r\n</style>\r\n</head>\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    params[:date]  = \"13/8/2016\" unless params[:date]\r\n    t = params[:date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    date = Date.new t[0],t[1],t[2]\r\n    date = Time.now\r\n    \r\n    apps = models[:appointment].where(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day).all\r\n\r\n    groups = {}\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    \r\n    \r\n    # colos = models[:colonoscopy].where(\r\n    \r\n    \r\n    \r\n    \r\n    for i in apps\r\n    \r\n    s = i.status\r\n    groups[s] = [] unless groups[s]\r\n    groups[s] << i\r\n    \r\n    \r\n    end\r\n    \r\n    appm = {}\r\n    \r\n    module_model.where(:module_id=>apps.collect{|i| i.id} ).all.each do |i|\r\n    \r\n    appm[i.module_id] = i\r\n    \r\n    end\r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n    \r\n   \r\n    \r\n    colom =  models[:colonoscopy].find(module_model.where(:parent_id=>appm.values.collect{|i| i.id}, :module_name=>\"\\#{@current_project.name}#colonoscopy\").all.collect{|i| i.module_id})\r\n    \r\n    scopes = []\r\n    \r\n    coloms = {}\r\n    colom.each do |i|\r\n         scope_list.each do |j|\r\n            coloms[i.id] = [] unless coloms[i.id]\r\n            coloms[i.id] += i[j] if i[j]\r\n            scopes += coloms[i.id] if coloms[i.id]\r\n         end\r\n    end\r\n    scm = {}\r\n    \r\n    models[:colonoscopy_scope].find(scopes).each do |i|\r\n    scm[i.id.to_s] = i.finding\r\n    end\r\n    \r\n    l = {}\r\n    \r\n  \r\n \r\n    \r\n    # models[:colonoscopy_scope].find(colom)\r\n    \r\n    \r\n    \r\n \r\n    \r\n    \r\n    # abnormal_type\r\n    total_register =0\r\n    total_register += groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    total_register += groups[\'Processing\'].size if groups[\'Processing\']\r\n    total_register += groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    \r\n  total_complete = 0 \r\n    total_complete = groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    total_cancer = 0\r\n    total_polyp  = 0 \r\n    total_waiting = 0 \r\n    total_waiting = groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    \r\n   \r\n    # coloms.each_pair do |c,l|\r\n         \r\n    # end\r\n    \r\n    data = []\r\n    \r\n     coloms.keys.each do |k|\r\n        v = coloms[k].collect{|i| scm[i] }\r\n        l[k.to_s] = v\r\n        total_cancer+=1 if v and v.index(\'Cancer\') \r\n        total_polyp+=1 if v and v.index(\'Polyp\')\r\n\r\n    end\r\n\r\n    mm = {}\r\n    mm2 = {}\r\n    module_model.where(:module_id=>coloms.keys).all.each do|i|\r\n        mm[i.module_id.to_s] = i.patient_id\r\n        mm2[i.module_id.to_s] = i.id\r\n    end\r\n    \r\n    pm = {}\r\n    patient_model.find(mm.values).each do |i|\r\n      pm[i.id] = i \r\n    end\r\n    \r\n\r\n%>\r\n\r\n<body>\r\n\r\n<div class=\"bbody\" style=\"font-size:14px\">\r\n\r\n<div class=\"bhead\">\r\n \r\n\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"margin-left:auto;margin-right:auto\">\r\n<tr>\r\n  <th colspan=\"16\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/cusys/mobile/trang_logo.png\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h2>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลตรัง ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์\r\n  </h2>\r\n\r\n<h1>&nbsp;</h1></th>\r\n  </tr>\r\n<tr>\r\n    <th width=\"10px\">No.</th>\r\n    <th>ชื่อ-สกุล</th>\r\n    <th>HN</th>\r\n    <th>เลขบัตรประชาชน</th><th>Gender</th><th>อายุ</th><th>วันที่ทำ</th><th>Diagnosis</th><th>Bowel preparation</th><th>กล้อง</th><th>ส่องถึง</th><th>Patho</th><th>แพทย์1</th><th>แพทย์2</th><th>พยาบาล</th><th>Action</th>\r\n</tr>\r\n<% \r\n    index = 0 \r\n    for i in l.keys \r\n    v = l[i]\r\n    m = mm[i]\r\n    p = pm[m]\r\n    index+=1\r\n%>\r\n\r\n    <tr>\r\n    <td><%=index%></td>\r\n    <td><%=p.first_name%> <%=p.last_name%> </td>\r\n    <td><%=p.hn%></td>\r\n    <td><%=p.public_id%></td>\r\n    <td><%=p.gender%></td>\r\n    <td><%=p.birth_date%></td>  \r\n<td>วันที่ทำ</td>\r\n<td>Diagnosis</td>\r\n<td>Bowel preparation</td>\r\n<td>colonoscope</td>\r\n<td>scope</td>\r\n<td>Patho</td>\r\n<td>endoscopist_1</td>\r\n<td>endoscopist_2</td>\r\n<td>nurse</td>      \r\n      \r\n        <td><%=link_to \"Show\", \"../Colonoscopy/show?id=\\#{mm2[i]}\" %></td>\r\n    </tr>\r\n    \r\n    <% end %>\r\n</table>\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2016-08-15 03:33:09','2016-08-15 03:33:09','report_total',''),(2495,'summary_report',964,3,'<%\r\n\r\n    dates = %w{12/8/2016 13/8/2016}\r\n    groups = {}\r\n    \r\n    models = get_model\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n  \r\n    map = {}\r\n    \r\n    l = %w{total total_polyp total_cancer total_diver total_other}.collect{|i| i.to_sym}\r\n    s = {}\r\n    for i in dates\r\n        t = i.split(\"/\").reverse.collect{|i| i.to_i}\r\n        date = Date.new t[0],t[1],t[2]\r\n        key = i\r\n        \r\n        apps = models[:appointment].where(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day).all\r\n        appm = module_model.where(:module_id=>apps.collect{|i| i.id }).all\r\n        \r\n        colom = module_model.where(:parent_id=>appm.collect{|i| i.id },:module_name=>\"\\#{@current_project.name}#colonoscopy\").all\r\n        \r\n        colos = models[:colonoscopy].find(colom.collect{|i| i.module_id })\r\n        \r\n        map[key] = {} unless map[key]\r\n        r = map[key]\r\n        %>\r\n        <%#colos.collect{|i| \"\\#{i.diagnosis_group}\"}.join(\'<br/>\').html_safe%>\r\n        <%\r\n        \r\n        r[:total] = colos.size\r\n        r[:total_polyp] = colos.collect{|i| i if  i.diagnosis_group.downcase.index(\'polyp\') }.compact.size\r\n        r[:total_cancer] = colos.collect{|i| i if  i.diagnosis_group.index(\'Cancer\') }.compact.size\r\n        r[:total_diver] = colos.collect{|i| i if  i.diagnosis_group.downcase.index(\'diverti\') }.compact.size\r\n        r[:total_other] = colos.collect{|i| i if  i.diagnosis_group.downcase.index(\'polyp\')==nil and i.diagnosis_group.downcase.index(\'cancer\')==nil and i.diagnosis_group.downcase.index(\'diverti\')==nil and i.diagnosis_group!=\'Normal\' }.compact.size\r\n        # r[:total]- r[:total_polyp]- r[:total_cancer]- r[:total_diver]- colos.collect{|i| i if  i.diagnosis_group==\'Normal\' }.compact.size\r\n        \r\n        for x in l\r\n            s[x] = 0 unless s[x]\r\n            s[x] += r[x]\r\n        end\r\n# {\"12/8/2016\"=>{:total=>81, :total_polyp=>18, :total_cancer=>1, :total_diver=>10, :total_other=>1}, \"13/8/2016\"=>{:total=>76, :total_polyp=>25, :total_cancer=>1, :total_diver=>12, :total_other=>-2}}        \r\n        \r\n    end\r\n%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Patient Report</title>\r\n<%=include_header%>\r\n<style>\r\n .bbody{ width:100%; margin-left:auto; margin-right:auto;}\r\n .bhead{text-align:center}\r\n</style>\r\n</head>\r\n    <body>\r\n\r\n<div class=\"bbody\" style=\"font-size:14px\">\r\n\r\n<div class=\"bhead\">\r\n \r\n\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\"  style=\"margin-left:auto;margin-right:auto\">\r\n<tr>\r\n  <th colspan=\"16\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/cusys/mobile/trang_logo.png\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h2>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลตรัง ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์\r\n  </h2>\r\n\r\n<h1>&nbsp;</h1></th>\r\n  </tr>\r\n<tr>\r\n<td align=\"center\">\r\n        <table border=\"1\" cellpadding=\"20\" >\r\n            <tr><td>&nbsp;</td>\r\n                <% for d in dates %>\r\n                <th><%=d%></th>\r\n                <% end %>\r\n                <td>Sum</td>\r\n            </tr>\r\n            <% for r in l %>\r\n            <tr><td><%=r.to_s.humanize%></td>\r\n                <% for d in dates %>\r\n                <td><%=map[d][r]%></td>\r\n                <% end %>\r\n                \r\n                <td><%=s[r]%> <%=\"(\\#{(s[r]*100/s[:total]).to_f}%)\" if r!=:total %></td>\r\n            </tr>\r\n            <% end %>\r\n            \r\n            \r\n            \r\n        </table>\r\n    </td>\r\n    </tr>\r\n    </table>\r\n    </div>\r\n    </div>\r\n        \r\n    </body>\r\n</html>',NULL,NULL,NULL,'2016-08-15 03:33:39','2016-08-15 03:33:39','summary_report',''),(2496,'vn_invoice',952,3,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n  <%= include_header %>\r\n    <meta charset=\"utf-8\">\r\n    <title>INVOICE Template</title>\r\n    <link href=\"css/bootstrap.css\" rel=\"stylesheet\">\r\n    <style>\r\n	body {font-size:9px}\r\n	.boxcompany { border:1px solid; -moz-border-radius: 5px; border-radius: 5px; padding:10px}\r\n	.sign {width:300px; border:1px solid; -moz-border-radius: 5px; border-radius: 5px; padding:10px; text-align:center; float:left}\r\n	table, th, td {\r\n    border: 1px solid ddd;\r\n}\r\nth, tr, td {\r\n    border-bottom: 1px solid #ddd;\r\n}\r\n	</style>\r\n  </head>\r\n  <body style=\"background:#666\">\r\n    <div class=\"container\" style=\"background:#fff\">\r\n      <div class=\"row\" style=\"border: 0px solid;margin-left:0px;\">\r\n        <center>\r\n          <h1>ใบวางบิล<br>\r\n          Invoice</h1></center>\r\n          <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n            <td width=\"10%\"><img src=\"/esm/clinic_master/clinic/logo.jpg\" width=\"100\" alt=\"สถานเสาวภา\"></td><td width=\"62%\">\r\n          \r\n<h4>สถานเสาวภา สภากาชาดไทย </h4>\r\n<b>1871 ถนนพระราม 4 เขตปทุมวัน กทม. 10330 <br />\r\nโทรศัพท์. 02-252-0161-4, 02-252-0167 <br />\r\nโทรสาร. 02-254-0212 <br />\r\nอีเมล์ : info@saovabha.com <br />\r\nเว็บไซต์ : www.saovabha.com</b></td>\r\n            <td width=\"28%\"><br>\r\n				เลขที่ :<br>\r\n				วันที่ :<br>\r\n              VN :\r\n              </td>\r\n            </tr>\r\n          </table><br />\r\n          <div class=\"boxcompany\">\r\n           <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n            <td width=\"65%\">ชื่อ-สกุล :</td><td width=\"30%\">สถานที่จัดส่งสินค้า:</td>\r\n            </tr>\r\n            <tr>\r\n            <td>ที่อยู่ :</td><td>ติดต่อ :</td>\r\n            </tr>\r\n            \r\n         