p;</td>\r\n  </tr>\r\n</table>\r\n\r\n\r\n</div> \r\n      <!-- /row -->\r\n    </div> <!-- /container -->\r\n    \r\n    \r\n  </body>\r\n</html>',NULL,NULL,NULL,'2016-08-16 02:14:24','2016-08-16 02:14:24','vn_invoice',''),(2497,'note_search',189,2,'<%\r\n    models = get_model\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n  \r\n  \r\n    models[:colonoscopy].collection.find({:remark=>{ \'$regex\': \'/30/\'}},{:fields=>{:_id=>1,:remark=>1}}).to_a\r\n    \r\n    \r\n    for i in models\r\n    \r\n%>\r\n\r\n<%= i.inspect %>\r\n\r\n<% end %>',NULL,NULL,NULL,'2016-08-16 06:47:51','2016-08-16 06:47:51','note_search',''),(2498,'note_search',522,2,'<%\r\n    models = get_model\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    \r\n    \r\n  \r\n   list = models[:colonoscopy].collection.find({\'$or\'=>[{:remark=>/30/},{:scope_note=>/30/}]},{:fields=>{:_id=>1,:remark=>1,:scope_note=>1}}).to_a\r\n    \r\n  %>\r\n  <table border=\"1\">\r\n  <%\r\n    for i in list\r\n    \r\n    m = module_model.where(:module_id=>i[\'_id\']).first\r\n    p = patient_model.find(m.patient_id)\r\n    \r\n%>\r\n<tr>\r\n<td>\r\n<%= p.hn %>\r\n</td>\r\n<td>\r\n<%= p.first_name %> <%= p.last_name %>\r\n</td>\r\n<td>\r\n<%=i[\'remark\']%>\r\n</td>\r\n<td>\r\n<%=i[\'scope_note\']%> \r\n</td>\r\n\r\n\r\n    \r\n</tr>\r\n<% end %>\r\n</table>',NULL,NULL,NULL,'2016-08-16 06:56:35','2016-08-16 06:56:35','note_search',''),(2499,'index',1011,2,'\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Solution\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <center><b>Welcome to <span style=\"color:#F3790D\">Clinic</span> Solution</b></c