n	-moz-box-shadow: 0px 10px 14px -7px #276873;\r\n	-webkit-box-shadow: 0px 10px 14px -7px #276873;\r\n	box-shadow: 0px 10px 14px -7px #276873;\r\n	background:-webkit-gradient(linear, left top, left bottom, color-stop(0.05, #599bb3), color-stop(1, #408c99));\r\n	background:-moz-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n	background:-webkit-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n	background:-o-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n	background:-ms-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n	background:linear-gradient(to bottom, #599bb3 5%, #408c99 100%);\r\n	filter:progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#599bb3\', endColorstr=\'#408c99\',GradientType=0);\r\n	background-color:#599bb3;\r\n	-moz-border-radius:8px;\r\n	-webkit-border-radius:8px;\r\n	border-radius:8px;\r\n	display:inline-block;\r\n	cursor:pointer;\r\n	color:#ffffff;\r\n	font-family:Arial;\r\n	font-size:20px;\r\n	font-weight:bold;\r\n	padding:13px 32px;\r\n	text-decoration:none;\r\n	text-shadow:0px 1px 0px #3d768a;\r\n}\r\n.myButton:hover {\r\n	background:-webkit-gradient(linear, left top, left bottom, color-stop(0.05, #408c99), color-stop(1, #599bb3));\r\n	background:-moz-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n	background:-webkit-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n	background:-o-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n	background:-ms-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n	background:linear-gradient(to bottom, #408c99 5%, #599bb3 100%);\r\n	filter:progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#408c99\', endColorstr=\'#599bb3\',GradientType=0);\r\n	background-color:#408c99;\r\n}\r\n.myButton:active {\r\n	position:relative;\r\n	top:1px;\r\n}\r\n\r\n\r\n.bb { padding:20px; font-size:1.5em; margin:10px; width:150px; height:60px;\r\n-moz-border-radius: 5px;\r\nborder-radius: 5px;\r\n-moz-box-shadow: 2px 2px #ccc;\r\n-webkit-box-shadow: 2px 2px #ccc;\r\nbox-shadow: 2px 2px #ccc;}\r\n.modal {width:1000px;}    \r\ninput, textarea, select, .uneditable-input {\r\nwidth: 100%; }\r\n.modal {\r\n    margin: -300px 0 0 -500px;}\r\n        </style>\r\n    </header>\r\n    <body>\r\n    <br/>\r\n    \r\n    <%\r\n    models = get_model\r\n    \r\n    %>\r\n    <%=models[:appointment].count%>\r\n    <div class=\"row-fluid\">\r\n\r\n    <div id=\"home-panel\" class=\"span12\" style=\"magin-left:auto;magin-right:auto;\">\r\n        \r\n            \r\n            <div class=\"span12\" style=\"border:0px solid\" > \r\n            <center><a href=\"index\" ><img src=\"https://emr-life.com/esm/clinic_master/clinic/logo.jpg\"></a></center>\r\n                <br />\r\n            </div>\r\n            \r\n            \r\n       \r\n    \r\n        <div class=\"row-fluid\">\r\n            \r\n            <div class=\"span6 center\">\r\n             <img src=\"/esm/clinic_master/clinic/flow.jpg\" width=\"500px\" class=\"well\" style=\"float:right; marign-right:20px\">\r\n            \r\n            </div>\r\n            \r\n            \r\n            <div class=\"span6\">\r\n            <%= text_field_tag :barcode,\"\", :id=>\"barcode\",:placeholder=>\'hn, appoint-id, online-id, pid\',:style=>\'height:50px; font-size:1.5em; width:400px\' %> <a href=\"javascript:checkin()\" id=\"appoint-btn\" class=\"btn\" style=\"margin-bottom: 10px;\"><i class=\"splashy-star_full\"></i> check-in <br/>appointment  </a><br />\r\n    \r\n      <!-- แก้ให้หน่วยจ้าา  -->\r\n    <script>\r\n   function changeValue(o){\r\n     document.getElementById(\'barcode\').value=o.innerHTML;\r\n    }\r\n</script>\r\n\r\n    <button class=\"myButton\" id=\"1\" onclick=\"changeValue(this)\">1</button><button class=\"myButton\" id=\"2\" onclick=\"changeValue(this)\">2</button><button class=\"myButton\" id=\"3\" onclick=\"changeValue(this)\">3</button><br />\r\n    <button class=\"myButton\" id=\"4\" onclick=\"changeValue(this)\">4</button><button class=\"myButton\" id=\"5\" onclick=\"changeValue(this)\">5</button><button class=\"myButton\" id=\"6\" onclick=\"changeValue(this)\">6</button><br />\r\n    <button class=\"myButton\" id=\"7\" onclick=\"changeValue(this)\">7</button><button class=\"myButton\" id=\"8\" onclick=\"changeValue(this)\">8</button><button class=\"myButton\" id=\"9\" onclick=\"changeValue(this)\">9</button><br />\r\n    <button class=\"myButton\" id=\"/\" onclick=\"changeValue(this)\">/</button><button class=\"myButton\" id=\"0\" onclick=\"changeValue(this)\">0</button><button class=\"myButton\" id=\"#\" onclick=\"changeValue(this)\">DEL</button>\r\n    </center>\r\n            </div>\r\n            \r\n      \r\n            \r\n        </div>\r\n       \r\n        <div class=\"row\">\r\n        \r\n            <div class=\"span12 offset3\" ><center>\r\n                 <h2>\r\n                 <a href=\"#\" id=\"online-btn\" class=\"btn \"><i class=\"splashy-star_full\"></i> check-in <br/> online regist  </h2></a></center>\r\n            </div>\r\n            \r\n           \r\n            \r\n            \r\n        </div>\r\n    </div>\r\n    \r\n    \r\n    <a data-toggle=\"modal\" data-backdrop=\"static\" id=\"clinic\" href=\"#myModal1\"></a>\r\n    \r\n    <div class=\"modal hide in\" id=\"myModal1\" aria-hidden=\"false\" style=\"display: none;\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\" onClick=\"\">x</button>\r\n									<h3>Patient Information</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n						\r\n						  <%= form_for :patient,:url=>\"create_patient\" do |f|  %>\r\n                          <table>\r\n                          <tr>\r\n                          <th>เลขบัตรประชาชน</th><th>รหัสโรงพยาบาล</th><th>ชื่อ-สกุล</th><th>คลิกนิกที่นัดไว้</th><th>เวลารับบริการ</th></tr>\r\n                          <tr>\r\n                         <td> <%= f.text_field :public_id ,:id=>\'public_id\',:class=>\"patient\"%></td><td><%= text_field_tag :patient_id, \'\',:id=>\'patient_id\' %> </td><td><%= f.text_field :prefix_name,:class=>\"patient\"%><%= f.text_field :first_name, class:\"patient\"%> <%= f.text_field :last_name, class:\"patient\"%></td><td><%= text_field_tag :procedure, \'\',:id=>\'procedure_code\' %></td><td><%= f.text_field :register_date,:value=>Time.now%></td>\r\n               \r\n                         \r\n                          </tr></table>\r\n       <table width=\"100%\">\r\n       <tr>\r\n       <td> <a href=\"javascript:clinic(0)\" class=\"btn clinic-btn \" style=\"width:80%\"><h4><i class=\"splashy-star_full\"></i> คลินิกพิษสุนักบ้า <br /> Rabies\r\n               </h4></a></td><td> <a href=\"javascript:clinic(2)\" class=\"btn  clinic-btn \" style=\"width:80%\"><h4><i class=\"splashy-star_full\"></i> ขอเอกสารเพื่อการเดินทาง<br /> Travel certificate\r\n            \r\n                </h4></a></td><td> \r\n               <a href=\"javascript:clinic(1)\" class=\"btn clinic-btn \" style=\"width:80%\"><h4><i class=\"splashy-star_full\"></i> คลินิกเซลุ่มพิษงู <br /> Toxin\r\n            </h4></a></td>\r\n       </tr>\r\n</table>\r\n       \r\n               \r\n             \r\n              \r\n              \r\n            <br />\r\n       <h2> <%=f.submit \'รับบัตรคิว\' ,:class=>\'btn btn-success\'%></h2> <!-- <img src=\"/gebo/img/gCons/print.png\" /><br />พิมพ์บัตรคิว -->\r\n        <% end %>\r\n						\r\n						\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"\" onClick=\"\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n	</div>\r\n    \r\n    \r\n    \r\n    </div>\r\n    \r\n    \r\n    <div id=\"id-panel\" class=\"span12 hide\" >\r\n        \r\n    </div>\r\n    \r\n    \r\n    <div id=\"panel\" class=\"span12\">... </div>\r\n    \r\n    <div class=\"span12\">\r\n   \r\n   \r\n        <script>\r\n            \r\n        var disable_barcode=false;\r\n        function resetAll(){\r\n            reset();\r\n                \r\n\r\n    \r\n        }\r\n        \r\n        function checkin(){\r\n                   \r\n            $(\'#clinic\').click();\r\n             $(\'#barcode\').focus();\r\n\r\n\r\n        }\r\n        \r\n        \r\n        function reset(){\r\n\r\n        $(\'#patient_id\').val(\"\");\r\n    $(\'#patient_prefix_name\').val(\"\");\r\n    $(\'#patient_first_name\').val(\"\");\r\n    $(\'#patient_last_name\').val(\"\");\r\n    $(\'#public_id\').val(\"\")\r\n    $(\'#hn\').val(\"\");\r\n    $(\'.patient\').prop(\'disabled\', false);\r\n    \r\n    $(\'.clinic-btn\').removeClass(\"btn-success\");\r\n    $(\'#appoint-btn\').removeClass(\"disabled\");\r\n    $(\'#online-btn\').removeClass(\"disabled\");\r\n        \r\n    \r\n                         $(\'#barcode\').focus();\r\n\r\n\r\n        }\r\n        \r\n          \r\n        function clinic(id){\r\n            disable_barcode=true;\r\n            proc_code = \'\'\r\n            if(id==0) proc_code=\'rabies\'\r\n            if(id==1) proc_code=\'toxin\'\r\n            if(id==2) proc_code=\'travel\'\r\n            \r\n            // $(\'#patient_id\').val(\"\")\r\n            // $(\'#patient_prefix_name\').val(\"\");\r\n            // $(\'#patient_first_name\').val(\"\");\r\n            // $(\'#patient_last_name\').val(\"\");\r\n            // $(\'#hn\').prop(\'disabled\', false);\r\n            // $(\'#hn\').val(\"\");\r\n            // $(\'.patient\').prop(\'disabled\', false);\r\n            \r\n            \r\n            $(\'#procedure_code\').val(proc_code);\r\n            $(\'#clinic\').click();\r\n             $(\'#barcode\').focus();\r\n\r\n\r\n            // $(\'#hn\').focus();\r\n        }    \r\n        \r\n        function search_barcode(barcode){\r\n             console.log(barcode)\r\n                $.ajax({\r\n                    url: \"barcode?read=\"+barcode,\r\n                    context: document.body\r\n                    }).done(function(html) {\r\n                    $(\"#panel\").show();\r\n                    $(\"#id-panel\").show();\r\n                    $(\"#panel\").html(html);\r\n                });\r\n        }\r\n        \r\n        $(document).ready(function() {\r\n          \r\n       $(\'#hn\').keydown(function(event) {\r\n            if (event.keyCode == 13) {\r\n                \r\n                barcode = $(\'#hn\').val()\r\n                search_barcode(barcode)\r\n                return false;\r\n            }\r\n            \r\n            \r\n        });\r\n        $(\'#barcode\').keydown(function(event) {\r\n            if (event.keyCode == 13) {\r\n                barcode = $(\'#barcode\').val()\r\n                $(\'#barcode\').val(\'\')\r\n               search_barcode(barcode)\r\n                \r\n            return false;\r\n         }\r\n            \r\n        });\r\n        \r\n       \r\n        });\r\n        \r\n        function focus_barcode(){\r\n              if(disable_barcode==false)\r\n              $(\'#barcode\').focus();\r\n              \r\n        }\r\n        focus_barcode();\r\n        setInterval(focus_barcode,1000);\r\n            \r\n        </script>\r\n        \r\n        <% if false %>\r\n        <center ><img src=\"https://emr-life.com/esm/clinic_master/clinic/logo.jpg\">\r\n        <hr />\r\n        <h2>กรุณาเสียบบัตรประชาชน เพื่อรับการบริการ กรุณาเลือกคลินิกที่ต้องการ</h2>\r\n        \r\n        <br /><br />\r\n        \r\n        \r\n        <table width=\"100%\" >\r\n        <tr>\r\n        <td width=\"55%\"><img src=\"/esm/clinic_master/clinic/flow.jpg\" width=\"90%\" class=\"well\"></td>\r\n        <td width=\"45%\">\r\n        <div class=\"well\">\r\n        <table width=\"100%\"><tr><td width=\"19%\" rowspan=\"2\"><img src=\"/gebo/img/gCons/agent.png\" alt=\"\"  width=\"60px\"/></td>\r\n          <td width=\"16%\" align=\"left\">ID</td>\r\n          <td width=\"65%\"> : 11522544441\r\n            </td></tr>\r\n            <tr>\r\n              <td align=\"left\">ชื่อ-สกุล </td>\r\n              <td>: นาย XXX XXX </td>