-20 11:58:11','2016-08-20 11:58:11','index',''),(2522,'document_name',1021,1,'\'injection\'',NULL,NULL,NULL,'2016-08-20 15:54:30','2016-08-20 15:54:30',NULL,NULL),(2523,'form',954,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   models = get_model\r\n   \r\n   products = models[:product].all\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n\r\n    $(document).ready(function(){\r\n\r\n    var products = <%=products.to_json.html_safe%>\r\n    var product_map = {}\r\n    var item_count = 0 ;\r\n    function init(){\r\n        \r\n        for(id in products){\r\n            i = products[id]\r\n            product_map[i[\'barcode\']] = i;\r\n        }\r\n        $(\'#prescription-items-add-action\').hide()\r\n        $(\'#prescription-search\').appendTo($(\"#items\"))\r\n        $(\'#product-search\').keypress(search);    \r\n         $(\'#product-search\').focus();\r\n    }\r\n    function search(e){\r\n        if(e.which === 13){\r\n        v = $(this).val()\r\n        list = []\r\n        \r\n        i = product_map[v]\r\n        if(i!=null){\r\n            line = $(\'#prescription-search-item\').clone()\r\n            \r\n            line.removeClass(\'hide\')\r\n            id = \"item_\"+item_count\r\n            line.attr(\"id\", id)\r\n            \r\n           $(\'#prescription-search\').append(line)\r\n \r\n            \r\n            \r\n            fs = [\'title\',\'product_id\',\'note\',\'quantity\'];\r\n            \r\n            for(j in fs){\r\n                field = fs[j]\r\n                \r\n            \r\n            obj = $(\'#\'+id+\' .prescription-\'+field)\r\n            obj.attr(\'id\',\"data-prescription-items-\"+id+\"-\"+field)\r\n            obj.attr(\'name\',\"prescription[items][\"+id+\"][\"+field+\"]\")\r\n            }\r\n            \r\n            obj = $(\'#\'+id+\' .prescription-title\')\r\n            obj.val(i[\'name\'])\r\n            \r\n            obj = $(\'#\'+id+\' .prescription-product_id\')\r\n            obj.val(i[\'id\'])\r\n            \r\n            \r\n            item_count+=1;\r\n           \r\n        //   alert(\"ok\")\r\n              e.preventDefault();\r\n              $(\'#product-search\').val(\"\")\r\n        }else{\r\n             e.preventDefault();\r\n              $(\'#product-search\').val(\"\")\r\n        }\r\n        }\r\n  \r\n        \r\n        \r\n    }\r\n\r\n    function add_product(){\r\n        v = $(this).val()\r\n        \r\n    }\r\n    init()\r\n        \r\n    })\r\n\r\n\r\n    \r\n</script>\r\n\r\n<%= text_field_tag \'search\',\'\',:id=>\'product-search\' %>\r\n<div id=\"prescription-search\">\r\n</div>\r\n\r\n\r\n<div id=\"prescription-search-item\" class=\"hide\">\r\n\r\n<div style=\"width:100%;border: 0px solid blue;padding-top:0px;padding-bottom:0px\" id=\"form-data\">\r\n	\r\n<div style=\"margin-left:auto;margin-right:auto;padding:1px;\" class=\"form-data-content\">\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:100%;margin:0px;min-height:50px\">\r\n\r\n<div id=\"prescription-items--title\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Title : </label></span>	\r\n<input type=\"text\" name=\"prescription2[items][][title]\" id=\"data-prescription-items-title\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"prescription-title k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div id=\"prescription-items--product_id\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Product ID : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n<input type=\"text\" name=\"prescription2[items][][product_id]\" id=\"data-prescription-items-product_id\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" class=\"prescription-product_id k-textbox k-textbox-txt\" >\r\n\r\n</div>\r\n</div>\r\n\r\n<div id=\"prescription-items--quantity\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Quantity : </label></span>	\r\n<input type=\"number\" name=\"prescription2[items][][quantity]\" id=\"data-prescription-items-quantity\" value=\"1\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"prescription-quantity k-textbox k-textbox-txt\" default=\"default\" step=\"1\">\r\n</div>\r\n\r\n<div id=\"prescription-items--note\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Note : </label></span>	\r\n<input type=\"text\" name=\"prescription2[items][][note]\" id=\"data-prescription-items-note\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"prescription-note k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n\r\n    \r\n</div>\r\n\r\n    \r\n    \r\n</div>\r\n</div>\r\n\r\n',NULL,NULL,NULL,'2016-08-20 17:22:22','2016-08-20 17:22:22','form',''),(2524,'index',953,3,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n	<head>\r\n		<%= include_header %>\r\n		<style>\r\n			body { \r\n			background: url(\'/esm/clinic_master/clinic/bg.jpg\') no-repeat;\r\n			background-size: 100% auto; \r\n			background-attachment: fixed; \r\n			}\r\n			.btnshadow {\r\n			-moz-box-shadow: 0 0 5px 5px #888;\r\n			-webkit-box-shadow: 0 0 5px 5px#888;\r\n			box-shadow: 0 0 5px 5px #888;\r\n			}\r\n			.myButton {\r\n			width:100px; height:60px;padding:20px;margin:5px; \r\n			-moz-box-shadow: 0px 10px 14px -7px #276873;\r\n			-webkit-box-shadow: 0px 10px 14px -7px #276873;\r\n			box-shadow: 0px 10px 14px -7px #276873;\r\n			background:-webkit-gradient(linear, left top, left bottom, color-stop(0.05, #599bb3), color-stop(1, #408c99));\r\n			background:-moz-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n			background:-webkit-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n			background:-o-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n			background:-ms-linear-gradient(top, #599bb3 5%, #408c99 100%);\r\n			background:linear-gradient(to bottom, #599bb3 5%, #408c99 100%);\r\n			filter:progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#599bb3\', endColorstr=\'#408c99\',GradientType=0);\r\n			background-color:#599bb3;\r\n			-moz-border-radius:8px;\r\n			-webkit-border-radius:8px;\r\n			border-radius:8px;\r\n			display:inline-block;\r\n			cursor:pointer;\r\n			color:#ffffff;\r\n			font-family:Arial;\r\n			font-size:20px;\r\n			font-weight:bold;\r\n			padding:13px 32px;\r\n			text-decoration:none;\r\n			text-shadow:0px 1px 0px #3d768a;\r\n			}\r\n			.myButton:hover {\r\n			background:-webkit-gradient(linear, left top, left bottom, color-stop(0.05, #408c99), color-stop(1, #599bb3));\r\n			background:-moz-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n			background:-webkit-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n			background:-o-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n			background:-ms-linear-gradient(top, #408c99 5%, #599bb3 100%);\r\n			background:linear-gradient(to bottom, #408c99 5%, #599bb3 100%);\r\n			filter:progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#408c99\', endColorstr=\'#599bb3\',GradientType=0);\r\n			background-color:#408c99;\r\n			}\r\n			.myButton:active {\r\n			position:relative;\r\n			top:1px;\r\n			}\r\n			.bb { padding:20px; font-size:1.5em; margin:10px; width:150px; height:60px;\r\n			-moz-border-radius: 5px;\r\n			border-radius: 5px;\r\n			-moz-box-shadow: 2px 2px #ccc;\r\n			-webkit-box-shadow: 2px 2px #ccc;\r\n			box-shadow: 2px 2px #ccc;}\r\n			.modal {width:1000px;}    \r\n			input, textarea, select, .uneditable-input {\r\n			width: 100%; }\r\n			.modal {\r\n			margin: -300px 0 0 -500px;}\r\n			.input-barcode {\r\n                border: none;\r\n                color: transparent;\r\n                display: inline-block;\r\n                font-size: 2em;\r\n                text-shadow: 0 0 0 black;\r\n                width: 2em;\r\n                \r\n                &:focus {\r\n                    outline: none;\r\n                }\r\n            }\r\n		</style>\r\n	</head>\r\n	<body>\r\n<style>\r\n    .kiosk-btn {\r\n        width:80%;font-size:2em;line-height:2em;margin-top:20px;margin-left:8%;text-align:center\r\n    }\r\n    .info-label {\r\n        width:40%;text-align:right;font-weight:bold;font-size:1.2em;line-height:1.3em;display:inline-block;padding:5px;\r\n    }\r\n    .info-value {\r\n        width:40%;text-align:left;margin-left:1%;font-size:1.2em;line-height:1.3em;display:inline-block;\r\n    }\r\n</style>\r\n	    <div style=\'margin-top:5px\'>&nbsp;</div>\r\n		<div class=\"row-fluid\">\r\n			<div id=\"home-panel\" class=\"span12\" style=\"magin-left:auto;magin-right:auto;\">\r\n				<div class=\"span12\" style=\"border:0px solid\" >\r\n					<center><a href=\"<%= params[:opt] %>\" ><img src=\"/esm/clinic_master/clinic/logo.jpg\"></a></center>\r\n					<br />\r\n				</div>\r\n				<div class=\"row-fluid\">\r\n				    <div class=\'span1\'>&nbsp;</div>\r\n					<div class=\"span5 center\">\r\n					    <div id=\'kiosk-home\'>\r\n					        <div style=\'margin-top:40px\'>&nbsp;</div>\r\n					        <a href=\'#\' id=\'checkin-btn\' class=\'btn kiosk-btn\' >Check-in</a>\r\n					        <br/>\r\n					        <a href=\'#\' id=\'register-btn\' class=\'btn kiosk-btn\' >Registration</a>\r\n						</div>\r\n					    <div id=\'checkin-1\'>\r\n					        <div class=\'well\' style=\'font-size:2em\'><center>Check-in</center></div>\r\n					        <div class=\'well\'>\r\n					            <img src=\"/esm/clinic_master/clinic/flow.jpg\"/>    \r\n					        </div>\r\n						</div>\r\n						<div id=\'checkin-2\'>\r\n					        <div class=\'well\' style=\'font-size:2em\'><center>Check-in</center></div>\r\n					        <div class=\'clear\'></div>\r\n					        <div class=\'well\'>\r\n					            <div id=\'pat-info\' style=\'height:200px;padding:10px;border:1px solid grey;background:white\'>\r\n					                <div class=\'info-label\'>HN :</div>\r\n					                <div class=\'info-value\' id=\'info-hn\'>xxxx/xx</div>\r\n					                <br/>\r\n					                <div class=\'info-label\'>ID :</div>\r\n					                <div class=\'info-value\' id=\'info-pid\'>xxxxxxxxxxxxx</div>\r\n					                <br/>\r\n					                <div class=\'info-label\'>Name :</div>\r\n					                <div class=\'info-value\' id=\'info-name\'>Mr.xxxxxx xxxxxx</div>\r\n					                <!--<br/>-->\r\n					                <!--<div class=\'info-label\'>Age :</div>-->\r\n					                <!--<div class=\'info-value\' id=\'info-age\'>xx yr.</div>-->\r\n					                <br/>\r\n					                <div class=\'info-label\'>Procedure :</div>\r\n					                <div class=\'info-value\' id=\'info-procedure\'>xxxx/xx</div>\r\n					                <br/>\r\n					                <div style=\'margin-top:10px\'>\r\n					                    <center><a href=\'#\' class=\'btn btn-success\' id=\'print-app\'>Print</a></center>\r\n					                </div>\r\n					            </div>\r\n					        </div>\r\n						</div>\r\n						<!-- register -->\r\n						<div id=\'register-home\'>\r\n					        <div class=\'well\' style=\'font-size:2em\'><center>Registeration</center></div>\r\n<%\r\n    procedure = get_model[:procedure].all\r\n    procedure.each do |i|\r\n%>\r\n					            <a href=\'javascript:registerProcedure(\"<%= i[:name] %>\", \"<%= i[:code] %>\")\' class=\'btn kiosk-btn\' ><%= i[:name] %></a>\r\n    					        <br/>\r\n<%\r\n    end\r\n%>\r\n						</div>\r\n						<div id=\'register-index\'>\r\n					        <div class=\'well\' style=\'font-size:2em\'><center><span id=\'reg-text\'>...</span></center></div>\r\n					        <div class=\'well\'>\r\n					            <center><div style=\'font-size:1.6em\' id=\'reg-cont\'>...</div></center>\r\n					            <br/><br/>\r\n					            <center><a href=\'javascript:void(0)\' class=\'btn btn-success\' style=\'line-height:2em\' id=\'reg-print\'>Print Queue</a></center>\r\n					            <input type=\"hidden\" name=\"reg-code\" id=\'reg-code\' value=\"\">\r\n					            <br/><br/><br/>\r\n					        </div>\r\n						</div>\r\n					</div>\r\n					<input type=\"hidden\" name=\"pat-id\" id=\'pat-id\' value=\"\">\r\n					<input type=\"hidden\" name=\"app-id\" id=\'app-id\' value=\"\">\r\n					<div class=\"span5\">\r\n					    \r\n<%= text_field_tag :barcode,\"\", :id=>\"barcode\",:class=>\'input-barcode\', :placeholder=>\'hn, appoint-id, online-id, pid\',:style=>\'height:40px; font-size:1.5em; width:310px; text-align: center; margin-left:5px\' %> \r\n<!-- <a href=\"javascript:checkin()\" id=\"appoint-btn\" class=\"btn\" style=\"margin-bottom: 10px;\"><i class=\"splashy-star_full\"></i> check-in <br/>appointment  </a><br /> -->\r\n                        \r\n<script>\r\n    function init() {\r\n        $(\'#kiosk-home\').show();\r\n        $(\'#checkin-1\').hide();\r\n        $(\'#checkin-2\').hide();\r\n        $(\'#register-home\').hide();\r\n        $(\'#register-index\').hide();\r\n    }\r\n    \r\n    init();\r\n    \r\n    var b_txt = \"\";\r\n    var bc = $(\'#barcode\');\r\n	function changeValue(n) {\r\n	    b_txt = $(\'#barcode\').val();\r\n		\r\n		if (b_txt.length >= 1 && n == \'d\') {\r\n		    b_txt = b_txt.substring(0, b_txt.length - 1);\r\n		} else if (n != \'d\') {\r\n		    b_txt += n;\r\n		}\r\n		$(\'#barcode\').val(b_txt);\r\n	}\r\n	\r\n	function registerProcedure(name, code) {\r\n	    $(\'#reg-text\').text(name);\r\n	    $(\'#reg-code\').val(code);\r\n	    $(\'#register-home\').hide();\r\n	    $(\'#register-index\').show();\r\n	    \r\n	    if ($(\'#pat-id\').val() == \'\' && $(\'#app-id\').val() == \'\') {\r\n	        $(\'#reg-cont\').text(\'New Registration\');\r\n	    } else if ($(\'#pat-id\').val() != \'\' && $(\'#app-id\').val() == \'\') {\r\n	        $(\'#reg-cont\').text(\'Register\');\r\n	    }\r\n	    \r\n	    \r\n	}\r\n	\r\n	function resetBarcode() {\r\n	    bc.val(\'\');\r\n	    init();\r\n	}\r\n	\r\n	function newPatient(procedure_code) {\r\n	    $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n	}\r\n	\r\n	function printModal() {\r\n	    $(\'#print-modal\').modal({\r\n                        show: true, \r\n                        // backdrop: \'static\',\r\n                        backdrop: \'fade\',\r\n                        keyboard: true\r\n                    });\r\n	}\r\n	\r\n	function submitBarcode() {\r\n	    bid = bc.val();\r\n	    if (bid.length != 0 && bid.length <= 13) {\r\n            $.getJSON( \"patient_query?read=\"+bid, function( data ) {\r\n                console.log(\'res : \' + data.res);\r\n                if (data.res == \'-1\') {\r\n                    init();\r\n                    $(\'#kiosk-home\').hide();\r\n                    $(\'#register-home\').show();\r\n                    \r\n                    \r\n                } else if (data.res == \'1\') {\r\n                    init();\r\n                    \r\n                    // pat info\r\n                    $(\'#info-hn\').text(data.pat.hn);\r\n                    $(\'#info-pid\').text(data.pat.public_id);\r\n                    $(\'#info-name\').text(data.pat.prefix_name + data.pat.first_name + \" \" + data.pat.last_name);\r\n                    $(\'#info-procedure\').text(data.pro.name);\r\n                    \r\n                    $(\'#pat-id\').val(data.pat.id);\r\n                    $(\'#app-id\').val(data.app.id);\r\n                    \r\n                    $(\'#kiosk-home\').hide();\r\n                    $(\'#checkin-2\').show();\r\n                    \r\n                    bc.val(\'\');\r\n                } else if (data.res == \'0\') {\r\n                    init();\r\n                    \r\n                    $(\'#pat-id\').val(data.pat.id);\r\n                    \r\n                    $(\'#kiosk-home\').hide();\r\n                    $(\'#register-home\').show();\r\n                    \r\n                    bc.val(\'\');\r\n                }\r\n            });\r\n	    } else if (bid.length == 0) {\r\n	        init();\r\n	        $(\'#kiosk-home\').hide();\r\n	        $(\'#register-home\').show();\r\n	    }\r\n	}\r\n	\r\n	$(document).ready(function() {\r\n	    $(\'#checkin-btn\').click(function() {\r\n	        $(\'#kiosk-home\').hide();\r\n	        $(\'#checkin-1\').show();\r\n	    });\r\n	    $(\'#register-btn\').click(function() {\r\n	        $(\'#kiosk-home\').hide();\r\n	        $(\'#register-home\').show();\r\n	    })\r\n	    $(\'#print-app\').click(function() {\r\n	           // $.ajax({\r\n            //         url: \"print_queue?id=\"+$(\'#app-id\').val(),\r\n            //         context: document.body\r\n            //     }).done(function(html) {\r\n            //         printModal();\r\n            //         $(\"#print-content\").html(html);\r\n            //     });\r\n            // $(\'#print-modal-content\').load(\"print_queue?aid=\"+$(\'#app-id\').val()+\" body\");\r\n            // printModal();\r\n            \r\n            window.location = \"print_queue?aid=\"+$(\'#app-id\').val();\r\n	    });\r\n	    \r\n	    $(\'#reg-print\').click(function() {\r\n	        var code = \'\';\r\n	        var pat_id = \'\';\r\n	        if ($(\'#pat-id\').val() == \'\' && $(\'#app-id\').val() == \'\') {\r\n    	       // $(\'#print-modal-content\').load(\"print_queue?code=\"+$(\'#reg-code\').val()+\" body\");\r\n    	       window.location = \"print_queue?code=\"+$(\'#reg-code\').val();\r\n    	    } else if ($(\'#pat-id\').val() != \'\' && $(\'#app-id\').val() == \'\') {\r\n    	       // $(\'#print-modal-content\').load(\"print_queue?pid=\"+$(\'#pat-id\').val()+\"&code=\"+$(\'#reg-code\').val()+\" body\");\r\n    	       window.location = \"print_queue?pid=\"+$(\'#pat-id\').val()+\"&code=\"+$(\'#reg-code\').val();\r\n    	    }\r\n    	    \r\n    	    \r\n    	    \r\n    	    init();\r\n	    });\r\n	    \r\n	});\r\n</script>\r\n<br/>\r\n    						<button class=\"myButton\" id=\"1\" onclick=\"changeValue(\'1\')\">1</button><button class=\"myButton\" id=\"2\" onclick=\"changeValue(\'2\')\">2</button><button class=\"myButton\" id=\"3\" onclick=\"changeValue(\'3\')\">3</button><br />\r\n    						<button class=\"myButton\" id=\"4\" onclick=\"changeValue(\'4\')\">4</button><button class=\"myButton\" id=\"5\" onclick=\"changeValue(\'5\')\">5</button><button class=\"myButton\" id=\"6\" onclick=\"changeValue(\'6\')\">6</button><br />\r\n    						<button class=\"myButton\" id=\"7\" onclick=\"changeValue(\'7\')\">7</button><button class=\"myButton\" id=\"8\" onclick=\"changeValue(\'8\')\">8</button><button class=\"myButton\" id=\"9\" onclick=\"changeValue(\'9\')\">9</button><br />\r\n    						<button class=\"myButton\" id=\"/\" onclick=\"changeValue(\'/\')\">/</button><button class=\"myButton\" id=\"0\" onclick=\"changeValue(\'0\')\">0</button><button class=\"myButton\" id=\"del\" onclick=\"changeValue(\'d\')\">DEL</button>\r\n						    <br/><br/>\r\n						    <span style=\'margin-left:40px\'></span><a href=\'javascript:resetBarcode();\' class=\'btn\' style=\'width:100px;font-size:1.5em;line-height:1.5em\'>Reset</a>&nbsp;&nbsp;<a href=\'javascript:submitBarcode();\' class=\'btn\' style=\'width:100px;font-size:1.5em;line-height:1.5em\'>Submit</a>\r\n						</center>\r\n					</div>\r\n					<div class=\'span1\'>&nbsp;</div>\r\n				</div>	\r\n			</div>\r\n		</div>\r\n		\r\n		\r\n<!-- modal section -->\r\n\r\n\r\n<div class=\"modal hide fade\" id=\"print-modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Print Queue</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n        <div class=\"w-box\">\r\n            <div id=\'print-modal-content\'></div>\r\n        </div>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n		\r\n		\r\n		\r\n		\r\n	</body>\r\n</html>',NULL,NULL,NULL,'2016-08-21 02:40:10','2016-08-21 02:40:10','index','*'),(2525,'document_name',1022,1,'\'billing_item\'',NULL,NULL,NULL,'2016-08-21 06:55:25','2016-08-21 06:55:25',NULL,NULL),(2527,'form',1016,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   models = get_model\r\n   \r\n   products = models[:product].all\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n\r\n    $(document).ready(function(){\r\n\r\n    var products = <%=products.to_json.html_safe%>\r\n    var product_map = {}\r\n    var item_count = 0 ;\r\n    function init_billing(){\r\n        \r\n        for(id in products){\r\n            i = products[id]\r\n            product_map[i[\'barcode\']] = i;\r\n        }\r\n        $(\'#billing-items-add-action\').hide()\r\n        \r\n        $(\'#billing-search-panel\').insertBefore($(\".billing-item-list\"))\r\n        \r\n        $(\'#billing-search\').appendTo($(\".billing-item-list\"))\r\n        \r\n        \r\n        $(\'#billing-search-field\').keypress(billing_search);    \r\n         $(\'#billing-search-field\').focus();\r\n         \r\n         \r\n       quantities = $(\".billing-item-list .billing-quantity\")\r\n       $(\".billing-item-list .billing-price\").each(function( index, element ) {\r\n       \r\n       $(element).change(update_billing);   \r\n       $(quantities[index]).change(update_billing);\r\n       \r\n   \r\n       \r\n\r\n       });\r\n       update_billing();\r\n         \r\n         \r\n    }\r\n    function billing_search(e){\r\n        if(e.which === 13){\r\n        v = $(this).val()\r\n        list = []\r\n        \r\n        i = product_map[v]\r\n        if(i!=null){\r\n          \r\n            line = $(\'#billing-search-item\').clone()\r\n            \r\n            line.removeClass(\'hide\')\r\n            id = \"item_\"+item_count\r\n            line.attr(\"id\", id)\r\n            \r\n           $(\'#billing-search\').append(line)\r\n \r\n            \r\n            \r\n            fs = [\'title\',\'product_id\',\'note\',\'quantity\',\'price\'];\r\n            \r\n            for(j in fs){\r\n                field = fs[j]\r\n                \r\n            \r\n            obj = $(\'#\'+id+\' .billing-\'+field)\r\n            obj.attr(\'id\',\"data-billing-items-\"+id+\"-\"+field)\r\n            obj.attr(\'name\',\"billing[items][\"+id+\"][\"+field+\"]\")\r\n            }\r\n            \r\n            obj = $(\'#\'+id+\' .billing-title\')\r\n            obj.val(i[\'name\'])\r\n            obj = $(\'#\'+id+\' .billing-price\')\r\n            obj.val(i[\'price\'])\r\n            obj.change(update_billing);\r\n            \r\n            obj = $(\'#\'+id+\' .billing-quantity\')\r\n            obj.change(update_billing);\r\n            \r\n            \r\n            \r\n            obj = $(\'#\'+id+\' .billing-product_id\')\r\n            obj.val(i[\'id\'])\r\n            \r\n            \r\n            item_count+=1;\r\n           \r\n        //   alert(\"ok\")\r\n              e.preventDefault();\r\n              $(\'#billing-search-field\').val(\"\")\r\n              update_billing()\r\n        }else{\r\n             e.preventDefault();\r\n              $(\'#billing-search-field\').val(\"\")\r\n        }\r\n        }\r\n  \r\n        \r\n        \r\n    }\r\n\r\n    function add_product(){\r\n        v = $(this).val()\r\n        \r\n    }\r\n    \r\n    function update_billing(){\r\n       \r\n       list = []\r\n       total = 0 \r\n       quantities = $(\".billing-item-list .billing-quantity\")\r\n       $(\".billing-item-list .billing-price\").each(function( index, element ) {\r\n       \r\n       price = parseFloat( $( element ).val())\r\n       quantity = parseInt( $( quantities[index] ).val())\r\n       amount = price* quantity\r\n       $($(\".billing-item-list .billing-note\")[index]).val(amount)\r\n       \r\n       \r\n    //   alert(\"\"+price+\"x\"+quantity)\r\n       \r\n       total+= amount\r\n           \r\n           \r\n       });\r\n       \r\n       $(\'#data-amount_total\').val(total)\r\n       \r\n       \r\n    }\r\n    \r\n    \r\n    init_billing()\r\n        \r\n    })\r\n\r\n\r\n    \r\n</script>\r\n\r\n<div  id=\"billing-search-panel\"  > \r\n<div class=\"clear\"></div>\r\n<div class=\"alert alert-info\">\r\nProduct search :\r\n<%= text_field_tag \'search\',\'\',:id=>\'billing-search-field\' %>\r\n</div>\r\n</div>\r\n<div id=\"billing-search\">\r\n</div>\r\n\r\n    \r\n\r\n\r\n<div id=\"billing-search-item\" class=\" hide \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:100%;margin:0px;min-height:50px\">\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"billing-items-57b979cc790f9b3272000006-title\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n	\r\n<table border=\"0\" style=\"border:0px solid\"><tbody><tr><td class=\"mlabel\" style=\"vertical-align:middle;\">&nbsp;</td><td>\r\n<input type=\"text\" name=\"billing2[items][57b979cc790f9b3272000006][title]\" id=\"data-billing-items-57b979cc790f9b3272000006-title\" value=\"sdsds\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" \r\nclass=\"billing-title k-textbox k-textbox-txt\">\r\n</td><td valign=\"top\" class=\"mlabel\" style=\"vertical-align:middle;\"></td></tr></tbody></table>\r\n</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"billing-items-57b979cc790f9b3272000006-product_id\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:100px;min-height:30px;\">\r\n	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n<table border=\"0\"><tbody><tr><td class=\"mlabel\" style=\"vertical-align:middle;\">&nbsp;</td><td>\r\n<input type=\"text\" name=\"billing2[items][57b979cc790f9b3272000006][product_id]\" id=\"data-billing-items-57b979cc790f9b3272000006-product_id\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" \r\nclass=\"billing-product_id \" validationmessage=\"Please select one\"><option value=\"\"></option><option selected=\"selected\" value=\"57b87dd0790f9b2f83000001\">Item1 Item1-title 123456 123456 10.0 10.0 false</option>\r\n<option value=\"57b8a2aa790f9b5fc8000012\">Item 2 item2  123457 123457 200.0 100.0 false</option></select>\r\n\r\n	\r\n</td><td valign=\"top\" class=\"mlabel\" style=\"vertical-align:middle;\">&nbsp;</td></tr></tbody></table>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"billing-items-57b979cc790f9b3272000006-quantity\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:50px;min-height:30px;\">\r\n	\r\n<table border=\"0\" style=\"border:0px solid\"><tbody><tr><td class=\"mlabel\" style=\"vertical-align:middle;\">&nbsp;</td><td>\r\n<input type=\"number\" name=\"billing2[items][57b979cc790f9b3272000006][quantity]\" id=\"data-billing-items-57b979cc790f9b3272000006-quantity\" value=\"1\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:50px\" \r\nclass=\"billing-quantity k-textbox k-textbox-txt\" default=\"default\" step=\"1\">\r\n</td><td valign=\"top\" class=\"mlabel\" style=\"vertical-align:middle;\"></td></tr></tbody></table>\r\n</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"billing-items-57b979cc790f9b3272000006-price\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n	\r\n<table border=\"0\" style=\"border:0px solid\"><tbody><tr><td class=\"mlabel\" style=\"vertical-align:middle;\">&nbsp;</td><td>\r\n<input type=\"number\" name=\"billing2[items][57b979cc790f9b3272000006][price]\" id=\"data-billing-items-57b979cc790f9b3272000006-price\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" \r\nclass=\"billing-price k-textbox k-textbox-txt\" step=\"0.001\">\r\n</td><td valign=\"top\" class=\"mlabel\" style=\"vertical-align:middle;\"></td></tr></tbody></table>\r\n</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"billing-items-57b979cc790f9b3272000006-note\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n	\r\n<table border=\"0\" style=\"border:0px solid\"><tbody><tr><td class=\"mlabel\" style=\"vertical-align:middle;\">&nbsp;</td><td>\r\n<input type=\"text\" name=\"billing2[items][57b979cc790f9b3272000006][note]\" id=\"data-billing-items-57b979cc790f9b3272000006-note\" value=\"\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" \r\nclass=\"billing-note k-textbox k-textbox-txt\">\r\n</td><td valign=\"top\" class=\"mlabel\" style=\"vertical-align:middle;\"></td></tr></tbody></table>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-08-21 07:06:00','2016-08-21 07:06:00','form',''),(2529,'patient_query',953,3,'<%\r\n    models = get_model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    read = params[:read]\r\n    \r\n    app = models[:appointment].where(:appoint_number=>read).first\r\n    \r\n    res = {}\r\n    res[:app] = \'\'\r\n    res[:pat] = \'\'\r\n    res[:pro] = \'\'\r\n    res[:res] = \'0\'\r\n    \r\n    if app\r\n        res[:app] = app\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n        patient = patient_model.where(\'$or\'=>[{:hn=>read},{:public_id=>read}]).first\r\n        \r\n        if patient \r\n            apm = module_model.where(:patient_id=>patient.id,:module_name=>\"\\\\#{@current_project.name}#appointment\").all\r\n            today = []\r\n            if apm.size>0\r\n                date = Time.now\r\n                today = models[:appointment].all(:id=>apm.collect{|i| i.module_id },:status=>\'Appointed\',:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n            end\r\n\r\n            if today.size == 1 \r\n                today = today[0]\r\n                proc = models[:procedure].find(today.procedure)\r\n                \r\n                res[:apm] = apm\r\n                res[:app] = today\r\n                res[:pat] = patient\r\n                res[:pro] = proc\r\n                res[:res] = \'1\'\r\n    \r\n%>\r\n<%= res.to_json.html_safe %>\r\n<% \r\n            else \r\n                today = models[:appointment].all(:id=>apm.collect{|i| i.module_id },:status=>\'Appointed\',:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n                res[:apm] = apm\r\n                res[:app] = today\r\n                res[:pat] = patient\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<% \r\n            end \r\n%>\r\n<% \r\n        else \r\n            res[:res] = \'-1\'\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<% \r\n        end \r\n%>\r\n<% \r\n    end \r\n%>',NULL,NULL,NULL,'2016-08-21 10:30:25','2016-08-21 10:30:25','patient_query',''),(2530,'print',1016,3,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patie