      <td width=\"28%\"><br>\r\n				เลขที่ : \r\n				<%=app.id%>\r\n				<br>\r\n				วันที่  :  \r\n				<%=app.date%><br>\r\n              VN : <%=app.queue_number%>\r\n              </td>\r\n            </tr>\r\n          </table><br />\r\n          <div class=\"boxcompany\">\r\n           <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n            <td width=\"65%\">ชื่อ-สกุล :\r\n                <%=patient.prefix_name %><%=patient.first_name %> <%=patient.last_name %>\r\n            </td><td width=\"30%\">สถานที่จัดส่งสินค้า:</td>\r\n            </tr>\r\n            <tr>\r\n            <td>ที่อยู่ :</td><td>ติดต่อ :</td>\r\n            </tr>\r\n            \r\n          \r\n        </table>\r\n        </div>\r\n            <br />\r\n      <table width=\"100%\" height=\"221\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n  <tr>\r\n    <th width=\"2%\">ลำดับ</th>\r\n    <th width=\"10%\">รหัสสินค้า</th>\r\n    <th width=\"52%\">รายละเอียด</th>\r\n    <th width=\"7%\">จำนวน</th>\r\n    <th width=\"6%\">หน่วย</th>\r\n    <th width=\"9%\">ราคาต่อหน่วย</th>\r\n    <th width=\"7%\">ส่วนลด</th>\r\n    <th width=\"7%\">จำนวนเงิน</th>\r\n  </tr>\r\n  <% for i in items\r\n    p = product_map[i.product_id]\r\n  %>\r\n  <tr>\r\n    <td><%=i.title%></td>\r\n    <td><%=p.code%></td>\r\n    <td><%=p.title%></td>\r\n    <td><%=i.quantity%></td>\r\n    <td><%=p.unit%></td>\r\n    <td><%=i.price%></td>\r\n    <td>-</td>\r\n    <td><%=i.quantity*i.price%></td>\r\n  </tr>\r\n  <% end %>\r\n  <tr>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"5\" rowspan=\"5\" valign=\"top\">หมายเหตุ</td>\r\n    <td colspan=\"2\">รวมเป็นเงิน</td>\r\n    <td><%=record.amount_total%></td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">ส่วนลด</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">จำนวนเงินหลังส่วนลด</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">จำนวนภาษีมูลค่าเพิ่ม</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">จำนวนเงินทั้งสิ้น</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n\r\n</table><br />\r\n<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n  <tr>\r\n    <td width=\"25%\" style=\"padding:20px\"><hr />ห้องยา<br /></td>\r\n    <td width=\"25%\" style=\"padding:20px\"><hr />ผู้รับยริการ<br /></td>\r\n    <td width=\"25%\" style=\"padding:20px\"><hr />ผู้รับเงิน<br /></td>\r\n    <td width=\"25%\" style=\"padding:20px\">&nbsp;</td>\r\n  </tr>\r\n</table>\r\n\r\n\r\n</div> \r\n      <!-- /row -->\r\n    </div> <!-- /container -->\r\n\r\n    \r\n  </body>\r\n</html>',NULL,NULL,NULL,'2016-08-21 10:30:45','2016-08-21 10:30:45','print',''),(2531,'create_partial',1016,3,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    \r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n\r\n<%\r\n    url = \"../\\\\#{this.document_name.camelize}/show_partial?id=\\\\#{m.id}\"\r\n%>\r\n   $.ajax({\r\n       url: \'<%=url.html_safe%>\',\r\n       success: function(data){\r\n        // console.log(data)\r\n\r\n         $(\'#panel-<%=this.document_name%>\').html(data);  \r\n         \r\n        }\r\n    });\r\n\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    models = get_model\r\n    \r\n    mproduct = models[:product]\r\n    prem = module_model.where(:module_name=>\"\\\\#{@current_project.name}\\#prescription\",:parent_id=>params[:parent_id]).first\r\n    \r\n    if prem\r\n\r\n\r\n        pre = models[:prescription].find prem.module_id\r\n        items = models[:prescription_item].find pre.items\r\n        \r\n        mbilling_item = models[:billing_item]\r\n        for i in items \r\n            \r\n            j = mbilling_item.create :title=>i.title, :product_id=>i.product_id, :quantity=>i.quantity,:price=>mproduct.find(i.product_id).price\r\n            \r\n            record.items << j.id\r\n        end\r\n        \r\n        \r\n        \r\n        \r\n    end\r\n\r\n    \r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create_partial\'),:data=>{:remote=>true} do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n<%= hidden_field_tag :parent_id, params[:parent_id] if params[:parent_id] %>\r\n<%= hidden_field_tag :record_name, params[:record_name] if params[:record_name] %>\r\n<%= hidden_field_tag :patient_id, params[:patient_id] if params[:patient_id] %>\r\n\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"display:none;background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\n<%= hidden_field_tag \'patient_id\',params[:patient_id] ,:id=>\'record-patient_id\'%> \r\n\r\n\r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n// 		$.ajax({\r\n// 		  url: url,\r\n// 		 success: function(data){\r\n// 		  $(\'#search-result\').html(data);  \r\n// 		  }\r\n// 		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n// 		$.ajax({\r\n// 		  url: url,\r\n// 		 success: function(data){\r\n//           $(\'#patient\').html(data);  \r\n//           $(\'#SelectPatient\').hide();\r\n//           $(\".modal-backdrop\").hide(\'fade\');\r\n// 		  }\r\n// 		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n    //  $(\'#SelectPatient\').modal({\r\n    //             show: true, \r\n    //             backdrop: \'static\',\r\n    //             keyboard: true\r\n    // })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:data=>{:disable_with=>\'Creating..\'} %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n\r\n',NULL,NULL,NULL,'2016-08-21 11:33:40','2016-08-21 11:33:40','create_partial',''),(2532,'print',919,3,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n  <%= include_header %>\r\n    <meta charset=\"utf-8\">\r\n    <title>INVOICE Template</title>\r\n    <link href=\"css/bootstrap.css\" rel=\"stylesheet\">\r\n    <style>\r\n	body {font-size:9px}\r\n	.boxcompany { border:1px solid; -moz-border-radius: 5px; border-radius: 5px; padding:10px}\r\n	.sign {width:300px; border:1px solid; -moz-border-radius: 5px; border-radius: 5px; padding:10px; text-align:center; float:left}\r\n	table, th, td {\r\n    border: 1px solid ddd;\r\n}\r\nth, tr, td {\r\n    border-bottom: 1px solid #ddd;\r\n}\r\n	</style>\r\n  </head>\r\n  <body style=\"background:#666\">\r\n    <div class=\"container\" style=\"background:#fff\">\r\n      <div class=\"row\" style=\"border: 0px solid;margin-left:0px;\">\r\n        <center>\r\n          <h1>ใบวางบิล<br>\r\n          Invoice</h1></center>\r\n          <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n            <td width=\"10%\"><img src=\"/esm/clinic_master/clinic/logo.jpg\" width=\"100\" alt=\"สถานเสาวภา\"></td><td width=\"62%\">\r\n          \r\n<h4>สถานเสาวภา สภากาชาดไทย </h4>\r\n<b>1871 ถนนพระราม 4 เขตปทุมวัน กทม. 10330 <br />\r\nโทรศัพท์. 02-252-0161-4, 02-252-0167 <br />\r\nโทรสาร. 02-254-0212 <br />\r\nอีเมล์ : info@saovabha.com <br />\r\nเว็บไซต์ : www.saovabha.com</b></td>\r\n            <td width=\"28%\"><br>\r\n				เลขที่ :<br>\r\n				วันที่ :<br>\r\n              VN :\r\n              </td>\r\n            </tr>\r\n          </table><br />\r\n          <div class=\"boxcompany\">\r\n           <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n            <td width=\"65%\">ชื่อ-สกุล :</td><td width=\"30%\">สถานที่จัดส่งสินค้า:</td>\r\n            </tr>\r\n            <tr>\r\n            <td>ที่อยู่ :</td><td>ติดต่อ :</td>\r\n            </tr>\r\n            \r\n          \r\n        </table>\r\n        </div>\r\n            <br />\r\n      <table width=\"100%\" height=\"221\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n  <tr>\r\n    <th width=\"2%\">ลำดับ</th>\r\n    <th width=\"10%\">รหัสสินค้า</th>\r\n    <th width=\"52%\">รายละเอียด</th>\r\n    <th width=\"7%\">จำนวน</th>\r\n    <th width=\"6%\">หน่วย</th>\r\n    <th width=\"9%\">ราคาต่อหน่วย</th>\r\n    <th width=\"7%\">ส่วนลด</th>\r\n    <th width=\"7%\">จำนวนเงิน</th>\r\n  </tr>\r\n  <tr>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"5\" rowspan=\"5\" valign=\"top\">หมายเหตุ</td>\r\n    <td colspan=\"2\">รวมเป็นเงิน</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">ส่วนลด</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">จำนวนเงินหลังส่วนลด</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">จำนวนภาษีมูลค่าเพิ่ม</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\">จำนวนเงินทั้งสิ้น</td>\r\n    <td>&nbsp;</td>\r\n  </tr>\r\n\r\n</table><br />\r\n<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n  <tr>\r\n    <td width=\"25%\" style=\"padding:20px\"><hr />ห้องยา<br /></td>\r\n    <td width=\"25%\" style=\"padding:20px\"><hr />ผู้รับยริการ<br /></td>\r\n    <td width=\"25%\" style=\"padding:20px\"><hr />ผู้รับเงิน<br /></td>\r\n    <td width=\"25%\" style=\"padding:20px\">&nbsp;</td>\r\n  </tr>\r\n</table>\r\n\r\n\r\n</div> \r\n      <!-- /row -->\r\n    </div> <!-- /container -->\r\n    \r\n    \r\n  </body>\r\n</html>',NULL,NULL,NULL,'2016-08-21 15:02:16','2016-08-21 15:02:16','print',''),(2534,'print',952,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\n@font-face {\r\n    font-family: \'barcode\';\r\n	src: url(\'/esm/ehr/emr/font/barcode.eot\');\r\n	src: local(\'☺\'), url(\'/esm/ehr/emr/font/c39hrp24dhtt.woff\') format(\'woff\'), url(\'/esm/ehr/emr/font/barcode.ttf\') format(\'truetype\'), url(\'/esm/ehr/emr/font/barcode.svg\') format(\'svg\');\r\n	font-weight: 700px;\r\n	font-size:60px;\r\n}\r\n.barcode\r\n	{font-family:\'barcode\',Sans-Serif;}\r\n#page {border:solid 0px;  border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding:0 0px 10px 10px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:360px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:360px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:360px;margin-left:0px;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:0px solid #ccc;\r\n	-webkit-border-radius: 5px; /* Safari prototype */\r\n	-moz-border-radius: 5px; /* Gecko browsers */\r\n	border-radius: 5px; /* Everything else - limited support at the moment */	\r\n	margin:10px;\r\n}\r\n.smm { font-size:9pt; }\r\n#box img{\r\n		width:150px;\r\n}\r\nlabel{\r\n	color:#666;\r\n}\r\n</style>\r\n<body>\r\n<br />\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"page\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p></p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n%>\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tr>\r\n<td width=\"310\"></td>\r\n<td>\r\n</td>\r\n<td>\r\n<div class=\"barcode\" style=\"font-size:50px; float:right; margin-right:30px; height:60px\"><%= @patient.hn %> </div></td>\r\n</tr>\r\n\r\n</table>\r\n----------------------------------------------------------------\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tr>\r\n  <td colspan=\"2\" >H.N.</td>\r\n  <td width=\"71%\">: <%= @patient.hn %></td>\r\n</tr>\r\n<tr>\r\n  <td colspan=\"2\" >วันที่</td>\r\n  <td>: <%= render_value \'date\' %></td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\" ><storng>ชื่อ-นามสกุล</storng></td><td>: <%=@patient.first_name %> <%=@patient.last_name %></td></tr>\r\n<tr><td colspan=\"2\"><storng>มาพบแพทย์</storng></td><td>: <%= render_value \'provider\' %></td></tr>\r\n<tr>\r\n<td colspan=\"2\"><storng>เวลานัด</storng></td><td>: <%= render_value \'start\' %> ถึง <%= render_value \'stop\' %></td></tr>\r\n<tr>\r\n<td colspan=\"2\"><storng>มาทำ</storng></td><td>: <%= render_value \'procedure\' %></td></tr>\r\n<tr>\r\n  <td width=\"16%\">Note</td>\r\n  <td colspan=\"2\"><p>: <%= render_value \'note\' %></p></td>\r\n  </tr>\r\n</table>\r\n\r\n\r\n<%# render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<%# @record.inspect %>\r\n\r\n<!-- <a href=\"http://<%=get_setting \'barcode_station\' %>/print?name=<%=@patient.first_name%>&date=<%= render_value \'date\'%>&proc=<%= render_value(\'procedure\').strip %>&hn=<%= @patient.hn %>\">Print</a> -->\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</body>\r\n</html>',NULL,NULL,NULL,'2016-08-21 16:11:53','2016-08-21 16:11:53','print',''),(2535,'print_queue',953,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n    <META HTTP-EQUIV=\"REFRESH\" CONTENT=\"5;URL=index\">\r\n    <style>\r\n        body{background:#333;}\r\n        .printpage{ padding:5px; -moz-border-radius: 5px;border-radius: 5px; background:#FFF; width:300px; margin-left:auto; margin-right:auto; text-align:center}\r\n@media print {\r\n .printpage{ padding:0px; margin:0px; margin-left:auto; margin-right:auto;width:300px; height:200px;}\r\n body{background:#fff;}\r\n}        \r\n        \r\n    </style>\r\n</head>\r\n<body>\r\n<%\r\n    models = get_model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    patient_model = ehr_model[:patient]\r\n    module_model = ehr_model[:patient_module]\r\n\r\n\r\n    cm = {\'travel\'=>\'A\',\'toxins\'=>\'C\',\'rabies\'=>\'B\'}\r\n    date = Time.now \r\n    \r\n    res = {}\r\n    \r\n    if params[:aid]\r\n        app = models[:appointment].find(params[:aid])\r\n        max = models[:appointment].where(:_id=>{\'$ne\'=>app.id},:queue_number=>{\'$ne\'=>nil},:procedure=>app.procedure,:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day).all.collect{|i| i.queue_number[1..-1].to_i}.max\r\n        procedure = models[:procedure].find(app.procedure)\r\n    \r\n    \r\n        c = \'\'\r\n        c = cm[procedure[:code]]\r\n        max = 0 unless max\r\n        app.update_attributes :queue_number=> \"\\\\#{c}\\\\#{format(\'%03d\',max+1)}\", :status=>\'Arrived\'\r\n    \r\n    \r\n        apm = module_model.where(:module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>app.id).first\r\n        pat = patient_model.find(apm[:patient_id])\r\n        \r\n        res[:pat] = pat\r\n        res[:apm] = apm\r\n        res[:app] = app\r\n        res[:pro] = procedure\r\n        res[:name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]} \\\\#{pat[:last_name]}\"\r\n        res[:hn] = pat[:hn]\r\n    elsif params[:code]\r\n        pat = nil\r\n        if params[:pid]\r\n            pat = patient_model.find(params[:pid])\r\n        else\r\n            pat = patient_model.create :hn=>\'\', :public_id=>\'\', :prefix_name=>\'\', :first_name=>\'\', :last_name=>\'\'\r\n        end\r\n        pro = models[:procedure].where(:code=>params[:code]).first\r\n        # find max q\r\n        max = models[:appointment].where(:queue_number=>{\'$ne\'=>nil},:procedure=>pro.id,:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day).all.collect{|i| i.queue_number[1..-1].to_i}.max\r\n        c = \'\'\r\n        c = cm[pro[:code]]\r\n        max = 0 unless max\r\n        q = \"\\\\#{c}\\\\#{format(\'%03d\',max+1)}\"\r\n        # create related doc\r\n        app = models[:appointment].create :status=>\'Arrived\', :procedure=>pro.id, :date=>Time.now.strftime(\'%d/%m/%Y\'), :queue_number=>q, :start=>Time.now.strftime(\'%H:%M\')\r\n        apm = module_model.create :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>app.id, :patient_id=>pat.id\r\n        \r\n        res[:pat] = pat\r\n        res[:apm] = apm\r\n        res[:app] = app\r\n        res[:pro] = pro\r\n        res[:name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]} \\\\#{pat[:last_name]}\"\r\n        res[:hn] = pat[:hn]\r\n    end\r\n%>\r\n<div class=\"printpage\">\r\n<h2>สถานเสาภา</h2><hr />\r\n<br />\r\n<h2><%= res[:app][:queue_number] %></h2>\r\n<br /><br />\r\n<%= res[:app][:date] %><br />\r\n<%= res[:name] %><br />\r\n<%= res[:hn] %><br />\r\n<%= res[:app][:status] %><br />\r\n<%= res[:pro][:name] %><hr />\r\n\r\nสถานเสาวภา สภากาชาดไทย <br />\r\n1871 ถนนพระราม 4 เขตปทุมวัน กทม. 10330 <br />\r\n\r\n</div>\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-08-21 16:23:04','2016-08-21 16:23:04','print_queue',''),(2536,'check',949,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    r_app = get_model[:appointment].all\r\n    r_pat = @patient_model.all\r\n    r_pat_group = r_pat.group_by{|i| i[:hn]}\r\n    hn = \'\'\r\n    \r\n    m_pm = @module_model\r\n    r_pat_group.each do |k, v|\r\n        if v.count > 1\r\n            hn = k\r\n            id_ref = \'\'\r\n            v.each_with_index do |i, idx|\r\n                if idx == 0\r\n                    id_ref = i.id.to_s\r\n                else\r\n                    r = m_pm.where(:patient_id=>i.id.to_s).all\r\n                    r.each do |j|\r\n                        j.update_attributes :patient_id=>id_ref\r\n                    end\r\n                end\r\n            end\r\n        end\r\n    end\r\n    \r\n\r\n    res = {}\r\n    res[:app_count] = r_app.count\r\n    res[:app] = r_app\r\n    res[:pat_count] = r_pat.count\r\n    res[:pat] = r_pat\r\n    res[:pat_hn_group] = r_pat_group[hn]\r\n    res[:pat_hn] = hn\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2016-08-24 09:27:57','2016-08-24 09:27:57','check',''),(2537,'patho_index',964,2,'\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module for Pathology Unit</b></center><br/>\r\n\r\n</center>\r\n\r\n<hr/>\r\n<h3> New Requests</h3>\r\n\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    models = get_model\r\n    patho_model = models[:pathology]\r\n    \r\n    name = \"\\\\#{@current_project.name}#pathology\"\r\n    \r\n    list = module_model.where(:ref_number=>\'new\',:module_name=>name).all(:order=>\'created_at desc\')\r\n    list.collect!{|i|\r\n        patient = patient_model.find i.patient_id\r\n        patho = patho_model.find i.module_id\r\n        appm = module_model.find i.parent_id\r\n        app = models[:appointment].find(appm.module_id)\r\n        {:id=>i.id,:patient_name=>\"\\\\#{patient.prefix_name}\\\\#{patient.first_name} \\\\#{patient.last_name}\",:hn=>patient.hn,:patho=>patho,:date=>app.date.strftime(\"%d-%m-%Y\") }if patient\r\n    }.compact!\r\n\r\n\r\n%>\r\n<%= tabular :data=>list,:model=>[:hn,:patient_name,:date],:labels=>{} do |row,out|\r\n  \r\n  out << link_to(\'Entry\' , \"../Pathology/edit?id=\\\\#{row[:id]}\",:class=>\'btn btn-info\')\r\n\r\n out\r\nend\r\n%> \r\n<hr/>\r\n<h3>Recently Update (3 days)</h3>\r\n<%\r\n\r\n  list = module_model.where(:updated_at=>{\'$gte\'=>Time.now-(24*3600*3)},:module_name=>name,:ref_number=>{\'$ne\'=>\'new\'}).all :limit=>10\r\n    list.collect!{|i|\r\n        patient = patient_model.find i.patient_id\r\n        patho = patho_model.find i.module_id\r\n        {:id=>i.id,:patient_name=>\"\\\\#{patient.prefix_name}\\\\#{patient.first_name} \\\\#{patient.last_name}\",:hn=>patient.hn,:patho=>patho,:date=>i.date.strftime(\"%d-%m-%Y\") }if patient\r\n        \r\n    }.compact!\r\n     \r\n%>\r\n<%= tabular :data=>list,:model=>[:hn,:patient_name,:date],:labels=>{} do |row,out|\r\n  \r\n  out << link_to(\'Show\' , \"../Pathology/show?id=\\\\#{row[:id]}\",:class=>\'btn\')\r\n\r\n out\r\nend\r\n%> \r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n',NULL,NULL,NULL,'2016-08-25 14:00:53','2016-08-25 14:00:53','patho_index',''),(2538,'edit',1023,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:record][:sxpathono],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \"Update\".html_safe, :class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   ',NULL,NULL,NULL,'2016-08-25 14:17:43','2016-08-25 14:17:43','edit','*'),(2539,'document_name',1024,1,'\'thoracentesis\'',NULL,NULL,NULL,'2016-08-30 12:26:53','2016-08-30 12:26:53',NULL,NULL),(2540,'print',1024,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   \r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:thoracentesis].find(colono_id)\r\n	@record = record\r\n	@document = get_document this.document_name\r\n	\r\n	endoscopist_1 = render_value(\'endoscopist_1\')\r\n	endoscopist_2 = render_value(\'endoscopist_2\')\r\n	\r\n	if @patient \r\n	patient = @patient\r\n	date = Time.now.to_datetime\r\n	birth_date = patient.birth_date \r\n	year = month = day = \'0\'\r\n	if date and birth_date\r\n	t = date-birth_date    \r\n	year = (t/365).to_i\r\n	t%=365\r\n	month = (t/30).to_i\r\n	t%=30\r\n	day = t.to_i\r\n	end\r\n	end\r\n	\r\n	\r\n	\r\n	%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>PRINT</title>\r\n	</head>\r\n	<style type=\"text/css\" media=\"all\">\r\n		html { }\r\n		#page {border:solid 1px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n		#head { width:100%; height:140px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-siz