roup_by{|i| i[:nurse_anesthetic_official]}\r\n    g_tmp = r_pos.group_by{|i| i[f]}\r\n    g_pos = {}\r\n    \r\n    g_tmp.keys.each do |i|\r\n        if i == nil\r\n            g_pos[m_prov[i.to_s]] = g_tmp[i]\r\n        else\r\n            g_pos[m_prov[i.to_s]] = g_tmp[i].count\r\n        end\r\n    end\r\n    \r\n    # a = @m_pat_mod.where(:module_id=>\'57983e97790f9b30bc000005\').first\r\n    # b = @m_pat.find(a[:patient_id])\r\n      \r\n    res = {}\r\n    res[:sdate] = q[:sdate]\r\n    res[:edate] = q[:edate]\r\n    res[:post_ids_count] = pat_mod_post_ids.count\r\n    res[:rs_count] = r_pos.count\r\n    res[:tmp] = g_pos\r\n    res[:xxx] = m_prov\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2016-09-26 15:24:30','2016-09-26 15:24:30','intra',''),(2562,'form',690,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<% if @current_role!=\'superuser\' and  @current_role!=\'superadmin\'\r\n\r\n \r\n%>\r\n<script>\r\n\r\n$(\'#role option\').each(function( index ) {\r\n  obj = $(this)\r\n  if(obj.text()==\'superadmin\'){\r\n    obj.hide()\r\n  } \r\n  \r\n});\r\n    \r\n    $(\'#data-pin\').prop(\'type\',\'password\');\r\n    \r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2016-09-26 16:57:16','2016-09-26 16:57:16','',''),(2563,'show',690,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r