ategories = models[:product_category].all\r\n   \r\n   \r\n   items = []\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n\r\n   if params[:parent_id]\r\n     m = module_model.find params[:parent_id]\r\n     app = models[:appointment].find m.module_id\r\n   else\r\n     im = module_model.find params[:id]\r\n     m = module_model.find im.parent_id\r\n     app = models[:appointment].find m.module_id\r\n    \r\n   end\r\n   ref_id = nil\r\n   if app\r\n      visit = models[:visit_type].find app.visit_type\r\n      if visit\r\n          case visit.name\r\n          when \'Elective\'\r\n          ref_id = \'1\'\r\n          when \'Emergency\'\r\n          ref_id = \'1\'\r\n          when \'Extratime\'\r\n          ref_id = \'2\'\r\n          when \'Special Clinic\'\r\n          ref_id = \'2\' \r\n          else\r\n          ref_id = \'1\'\r\n          end\r\n          if visit.ref_id and visit.ref_id !=\'\'\r\n              ref_id = visit.ref_id\r\n          end\r\n          \r\n          if ref_id ==\'2\'\r\n              params[:extratime] = true\r\n          end\r\n          \r\n      end          \r\n      \r\n   end\r\n   \r\n   section = \'ในเวลาราชการ\'\r\n   section = \'คลีนิคนอกเวลา\'  if params[:extratime]\r\n\r\n\r\n\r\n%>\r\n<%# params[:extratime].inspect %>\r\n<center>\r\n    <div class=\"\"><h2>\r\n        บันทึกค่าใช้จ่ายผู้ป่วย\r\n        <%= section %>\r\n    </h2></div>\r\n</center>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n    <div class=\"span7\">\r\n        \r\n        <div class=\"row-fluid\">\r\n            \r\n            <div class=\"span6\">\r\n                \r\n            </div>\r\n            <div id=\'search-items\' class=\"span6\">\r\n                \r\n            </div>\r\n        </div>\r\n        \r\n        \r\n        <div class=\"tabbable\">\r\n								<ul class=\"nav nav-tabs\">\r\n								<% \r\n								\r\n								has_one_list = {}\r\n								    \r\n								categories.each_with_index do |c,cindex| %>\r\n									<li class=\'<%=\'active\' if cindex==0%>\'>\r\n									<a href=\"#tab-<%=c.id%>\" data-toggle=\"tab\" style=\"font-size:1.2em\"><%=c.name%></a>\r\n									</li>\r\n								<% end %>\r\n								    \r\n								</ul>\r\n								<div class=\"tab-content\">\r\n								\r\n									<% categories.each_with_index do |c,cindex| \r\n									\r\n									     has_one = false\r\n									    \r\n									    has_one = true if c.has_one==\'true\'\r\n									    \r\n									\r\n								        ps = products.collect{|p| p if p.category_id == c.id}.compact\r\n								        	    \r\n									%>\r\n									\r\n									<div class=\"tab-pane <%=\'active\' if cindex==0%>\" id=\"tab-<%=c.id%>\">\r\n										<p>\r\n									\r\n										  <table style=\"width:100%\">\r\n										  <thead>\r\n										      <tr>\r\n										          <th style=\"text-align:right\">No.</th>\r\n										          <th>รายการ</th>\r\n										          <th style=\"text-align:left\">รหัส</th>\r\n										          <th style=\"text-align:right\">ราคา</th>\r\n										          <th style=\"text-align:right\">\r\n										          <% unless has_one %>\r\n										          จำนวน\r\n										          <% end %>    \r\n										              \r\n										          </th>\r\n										          \r\n										      </tr>\r\n										  </thead>\r\n										  <tbody>\r\n										  <% \r\n										  \r\n										    if has_one \r\n										    ps.sort!{|a,b| \r\n										        t =  a.code[0..1]<=>b.code[0..1] \r\n										        t = a.name<=>b.name if t == 0  \r\n										        t\r\n										    }\r\n										    \r\n										    else\r\n										    ps.sort!{|a,b| \r\n										       a.name<=>b.name\r\n										    }\r\n										    \r\n										    \r\n										    end\r\n										  \r\n										    ps.each_with_index do |p,pindex| \r\n										    \r\n										    has_one_list[p.id.to_s] = true if has_one\r\n										    \r\n										    price = p.price\r\n										    price = p.price_2 if params[:extratime] and p.price_2\r\n										  \r\n										  %>\r\n										  <tr id=\"<%=\"r\\\\#{p.id}\"%>\">\r\n										  <td style=\"text-align:right\"><%=pindex+1%>.</td>\r\n										  <td><%=link_to \"\\\\#{p.name} \", \"javascript:add_product(\'\\\\#{p.id}\')\", :class=>\' \', :style=>\'text-align:left;\'%>\r\n										      <% if p.required_note==\'true\' %>\r\n										      \r\n										      <span class=\"alert alert-danger \"> #<%=text_field_tag \"note[\\\\#{p.id}]\",\"\",:id=>\"n\\\\#{p.id}\",:style=>\"width:50px;margin-top:5px;\" %></span>\r\n										      \r\n										      <% end %>\r\n										  </td>\r\n										  <td style=\"text-align:left\"><%=p.code%>&nbsp;</td>\r\n										  \r\n										  <td  style=\'text-align:right\'><%=fn price%></td>\r\n										  \r\n										  <% if has_one %>\r\n										  <td style=\"height:40px\">\r\n										  <%=text_field_tag \"items[\\\\#{p.id}]\", 0, :class=>\'items hide\',:onchange=>\"update_product(\'\\\\#{p.id}\',null,\'\')\", :id=>\"p\\\\#{p.id}\",:style=>\"width:50px;margin-top:5px;\" %>\r\n                                          </td>\r\n										  \r\n                                          \r\n                                          <% else %>\r\n										  <td>\r\n										  <%=text_field_tag \"items[\\\\#{p.id}]\", 0, :class=>\'items\',:onchange=>\"update_product(\'\\\\#{p.id}\',null,\'\')\", :id=>\"p\\\\#{p.id}\",:style=>\"width:50px;margin-top:5px;\" %>\r\n										  </td>\r\n										  <% end %>\r\n										  \r\n										  <td>\r\n										    \r\n										    <%=hidden_field_tag \"price[\\\\#{p.id}]\", price %>\r\n\r\n\r\n										      <%=link_to \"[-]\", \"javascript:update_product(\'\\\\#{p.id}\',0,\'\')\", :class=>\' \', :style=>\'text-align:left;\' unless has_one%>\r\n										  \r\n										  </td>\r\n										      \r\n										  </tr>\r\n										  <% end %>\r\n										  </tbody>\r\n										  </table>\r\n										</p>\r\n									</div>\r\n									\r\n									<% end %>\r\n									\r\n								</div>\r\n							</div>\r\n        \r\n        \r\n    </div>\r\n    <div class=\"span5\">\r\n        <div class=\"alert\">\r\n            <h3 style=\"color:black\">\r\n                ค่าใช้จ่ายที่เลือก\r\n            </h3>\r\n    \r\n            \r\n            <div id=\"billing-list\">\r\n            \r\n            \r\n            </div>\r\n            \r\n            <h3 style=\"color:red\">\r\n            รวม \r\n            <span id=\"total_amount\">\r\n                0\r\n            </span> บาท\r\n            </h3>\r\n        </div>\r\n    </div>\r\n  \r\n</div>\r\n</div>\r\n  <hr/>\r\n<style>\r\n    .list{\r\n        display:block;\r\n        border:1px solid #666;\r\n        \r\n    }\r\n</style>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n\r\n<%#has_one_list.inspect %>\r\n<script>\r\n\r\n  var products = <%=products.to_json.html_safe%>\r\n  var has_one_list = <%=has_one_list.to_json.html_safe%>\r\n  var categories = <%=categories.to_json.html_safe%>\r\n    var product_map = {}\r\n    var item_count = 0 ;\r\n    \r\nfunction commaSeparateNumber(val){\r\n    val = val.replace(\',\', \'\');\r\n    var array = val.split(\'\');\r\n    var index = -3;\r\n    var search_list = null;\r\n    while (array.length + index > 0) {\r\n        array.splice(index, 0, \',\');\r\n        // Decrement by 4 since we just added another unit to the array.\r\n        index = index - 4;\r\n    }\r\n    return array.join(\'\');\r\n};  \r\n\r\n  function update_product(id, quantity, note){\r\n      \r\n      if (typeof(quantity)===\'undefined\') quantity = null;\r\n\r\n      i = product_map[id]\r\n       \r\n   \r\n       \r\n      \r\n    //   alert(i)\r\n    //   alert(id+\"-\"+quantity+\" \")\r\n      if(i!=null){\r\n          \r\n         nobj =$(\'#n\'+id)\r\n         nobj.val(note);\r\n          \r\n        //   alert(id)\r\n          obj =$(\'#p\'+id)\r\n         var old = null;\r\n         if(quantity!=null){\r\n             old = quantity\r\n             obj.val(old)\r\n         } else{\r\n          old = parseInt(obj.val())\r\n         \r\n         }    \r\n            // alert(id+\"-\"+old+\" \"+quantity)\r\n          if(old==0||obj.val()==\"\"){\r\n                        \r\n\r\n\r\n              $(\'#r\'+id).removeClass(\"alert-info\")\r\n              obj.val(0)\r\n          }else{\r\n              obj.val(old)\r\n              $(\'#r\'+id).addClass(\"alert-info\")\r\n          }\r\n          \r\n      }\r\n      \r\n      var total = 0;\r\n      \r\n      $(\'#billing-list\').html(\"\")\r\n      l =  $(\'#billing-list\')\r\n      \r\n      for(id in categories ){\r\n        c = categories[id]\r\n        l.append(\"<li>\"+c[\'name\']+\"<ul id=\'\"+c[\'id\']+\"\'></ul></li>\")\r\n      }\r\n      \r\n      $(\'.items\').each(function(){\r\n          v = $(this)\r\n          id = v.attr(\"id\").substring(1)\r\n          product = product_map[id]\r\n          i = parseInt(v.val())\r\n          \r\n          if(i>0){\r\n             \r\n             price = product[\'price\'];\r\n             <% if params[:extratime] %>\r\n             if(product[\'price_2\']>0)\r\n             price = product[\'price_2\'];\r\n             <% end %>\r\n             \r\n             total += i * price\r\n             m = $(\'#\'+product[\'category_id\'])\r\n             m.append(\"<li><span style=\'width:250px;display:inline-block;vertical-align:top;\'>\"+i+\" x \"+product[\'name\']+\"</span><span style=\'border:0px solid;;width:80px;text-align:right;display:inline-block\'>\"+ commaSeparateNumber((price*i).toString())+\"</span></li>\") \r\n          }\r\n          \r\n      })\r\n      \r\n     \r\n      $(\'#total_amount\').html(commaSeparateNumber(total.toString()))\r\n      \r\n      \r\n      \r\n  }\r\n  \r\n//   function del_product(id){\r\n     \r\n//       update_product(id,0)\r\n//   }     \r\n\r\n  function add_product(id){\r\n        obj =$(\'#p\'+id)\r\n        old = parseInt(obj.val())  \r\n        \r\n        if(has_one_list[id]&&old!=0){\r\n              update_product(id,0,\'\')\r\n        }else{\r\n  \r\n        i = product_map[id]\r\n        if(i!=null){\r\n            \r\n        \r\n          old = parseInt(obj.val())\r\n          \r\n          old+=1\r\n          \r\n          obj.val(old)\r\n            $(\'#r\'+id).addClass(\"alert-info\")\r\n            \r\n            item_count+=1;\r\n           \r\n            $(\'#billing-search-list\').html(\"\")\r\n            $(\'#product-search\').val(\"\")\r\n           \r\n            update_product(id,old,\'\')\r\n        }\r\n        }\r\n        \r\n    }\r\n\r\n    $(document).ready(function(){\r\n    \r\n  \r\n    function init(){\r\n        \r\n        for(id in products){\r\n            i = products[id]\r\n            product_map[i[\'id\']] = i;\r\n            if(i[\'barcode\'])product_map[i[\'barcode\'].toUpperCase()] = i;\r\n            product_map[i[\'code\'].toUpperCase()] = i;\r\n            \r\n        }\r\n        console.log(product_map)\r\n        $(\'#billing-items-add-action\').hide()\r\n        $(\'#billing-search\').appendTo($(\"#items\"))\r\n        $(\'#product-search\').keyup(search);   \r\n        \r\n         $(\'#product-search\').keydown(function(event){\r\n     if(event.keyCode == 13) {\r\n        \r\n       if(search_list.length==1){\r\n           add_product(search_list[0])\r\n       }\r\n         \r\n       event.preventDefault();\r\n       return false;\r\n     }\r\n   });\r\n         $(\'#product-search\').focus();\r\n         \r\n        $(\'#product-search-panel\').insertBefore($(\"#search-items\"))\r\n\r\n         \r\n         \r\n    }\r\n    function search(e){\r\n        \r\n        search_list = []\r\n        \r\n        v = $(this).val().toUpperCase()\r\n        if(v.length>1){\r\n            list =  $(\'#billing-search-list\');\r\n            list.html(\"\")\r\n             console.log(v)\r\n        \r\n            for(id in products){\r\n                i = products[id]\r\n                if(i[\'barcode\']==v||i[\'code\'].toUpperCase().search(v)>=0||i[\'name\'].toUpperCase().search(v)>=0||(i[\'title\']&&i[\'title\'].toUpperCase().search(v)>=0)){\r\n                    \r\n                    search_list.push(i[\'id\'])\r\n                    \r\n                    var li = $(\'<li/>\')\r\n                    .addClass(\'alert alert-success\')\r\n                    .attr(\'role\', \'menuitem\')\r\n                    .appendTo(list);\r\n                    \r\n                        $(\'<a>\',{\r\n                        text: i[\'name\']+ \"  \"+ i[\'code\'],\r\n                        title: i[\'title\'],\r\n                        id:i[\'id\'],\r\n                        click: function(){\r\n                            add_product($(this).attr(\"id\"))\r\n                             $(\'#product-search\').focus();\r\n                            \r\n                        }\r\n                        }).appendTo(li)\r\n\r\n\r\n                        \r\n                }\r\n                \r\n                \r\n            }\r\n            \r\n        \r\n            \r\n        }\r\n        \r\n          var code = e.keyCode ? e.keyCode : e.which;\r\n\r\n    switch(code)\r\n    {\r\n        case 13:\r\n       \r\n            i = product_map[v]\r\n            // if(i!=null)\r\n            if(i!=null){\r\n            add_product(search_list[0])\r\n            \r\n            // $(\'#product-search\').val(\"\")\r\n            }\r\n             e.preventDefault();\r\n             return false;\r\n        break;\r\n\r\n        default:\r\n                     e.preventDefault();\r\n\r\n\r\n        return false;\r\n     }\r\n        \r\n \r\n        \r\n        \r\n    }\r\n\r\n  \r\n    init()\r\n    \r\n        \r\n<%\r\nitems = models[:billing_item].find(@record.items)\r\n%>\r\n<% for i in items %>\r\nupdate_product(\'<%=i.product_id%>\',<%=i.quantity%>,\'<%=i.note%>\')\r\n<% end %>\r\n\r\n\r\n    \r\n        \r\n    })\r\n\r\n\r\n    \r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n<div  id=\"product-search-panel\"  > \r\n<div class=\"clear\"></div>\r\n<div class=\"alert alert-info\"><center>\r\nSearch :\r\n<%= text_field_tag \'search\',\'\',:id=>\'product-search\' %>\r\n</center>\r\n</div>\r\n<div id=\"billing-search-list\">\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"billing-search-list-item\" class=\"hide\">\r\n\r\n<div id=\"name\">Name</div>\r\n\r\n</div>\r\n\r\n\r\n<div id=\"billing-search-item\" class=\"hide\">\r\n\r\n<div style=\"width:100%;border: 0px solid blue;padding-top:0px;padding-bottom:0px\" id=\"form-data\">\r\n	\r\n<div style=\"margin-left:auto;margin-right:auto;padding:1px;\" class=\"form-data-content\">\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:100%;margin:0px;min-height:50px\">\r\n\r\n<div id=\"billing-items--title\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Title : </label></span>	\r\n<input type=\"text\" name=\"prescription2[items][][title]\" id=\"data-prescription-items-title\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"prescription-title k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div id=\"prescription-items--product_id\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Product ID : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n<input type=\"text\" name=\"prescription2[items][][product_id]\" id=\"data-prescription-items-product_id\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" class=\"prescription-product_id k-textbox k-textbox-txt\" >\r\n\r\n</div>\r\n</div>\r\n\r\n<div id=\"prescription-items--quantity\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Quantity : </label></span>	\r\n<input type=\"number\" name=\"prescription2[items][][quantity]\" id=\"data-prescription-items-quantity\" value=\"1\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"prescription-quantity k-textbox k-textbox-txt\" default=\"default\" step=\"1\">\r\n</div>\r\n\r\n<div id=\"prescription-items--note\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Note : </label></span>	\r\n<input type=\"text\" name=\"prescription2[items][][note]\" id=\"data-prescription-items-note\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"prescription-note k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n\r\n    \r\n</div>\r\n\r\n    \r\n    \r\n</div>\r\n</div>\r\n<script>\r\n    \r\n    <% unless @current_role ==\'developer\' %>\r\n    \r\n    $(\'#provider_id\').hide()\r\n    $(\'#type_of_patient\').hide()\r\n    $(\'#data-financial\').attr(\'disabled\',\'disabled\');\r\n    $(\'#billing_type\').hide()\r\n       $(\'#paid\').hide()\r\n    <% end %>\r\n    \r\n    <% if params[:extratime] %>\r\n    $(\'#update_billing_type_item_1\').attr(\'checked\', true);\r\n    <% end %>\r\n  \r\n    $(\'#items\').remove()\r\n    \r\n   <% if @record.paid==\'true\' and @current_role!=\'developer\' %>\r\n   alert(\"Not allowed\")\r\n   window.location = \"show?id=<%=params[:id]%>\"\r\n   <% end %>\r\n    \r\n</script>\r\n\r\n<% if @record.paid == \'true\' and @current_role !=\'developer\' %>\r\n<script>\r\n    alert(\"You are not allow to edit complete billing\")\r\n</script>\r\n<meta http-equiv=\"show?id=<%=@record.id%>>\" content=\"0; url=index\" />\r\n<% end %>\r\n<%#@record.inspect %>\r\n\r\n',NULL,NULL,NULL,'2016-09-29 05:24:35','2016-09-29 05:24:35','form',''),(2574,'index',1036,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i>เพิ่มคลีนิกพิเศษ(เคสนอก)\'.html_safe, \r\n\"create?record[special_clinic]=true\",:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'.\' do |f| %>\r\n<div class=\"hide\">\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%\r\n        models = get_model \r\n        date = Time.now \r\n        if params[:date]\r\n           date = Date.parse params[:date] \r\n        end\r\n        attendance = models[:attendance].where(:date=>{\'$gte\'=>date.beginning_of_day(),\'$lte\'=>date.end_of_day()}).first\r\n        \r\n        providers = {}\r\n        for i in models[:provider].all\r\n            providers[i.id] = i.name\r\n        end\r\n        \r\n        if attendance \r\n        \r\n        @show = true        \r\n        @record = attendance\r\n        \r\n        \r\n%>\r\n<div class=\"alert alert-success \">\r\n    <%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n        <div style=\"margin-left:auto;margin-right:auto;padding:1px;width:700px\">\r\n<br/>\r\n    <%= link_to \'Calculate Payroll\', \"payroll?id=\\\\#{@record.id}\" , :class=>\'btn btn-info\' if @record.payroll_check!=\'true\'%>\r\n    <%= link_to \'Show\', \"payroll?id=\\\\#{@record.id}\" , :class=>\'btn\' if @record.payroll_check==\'true\'%>\r\n    <br/>\r\n    </div>\r\n</div>\r\n\r\n\r\n<% else %>\r\n     \r\n    <%= form_for :record, :url=>\'../Attendance/create\' do |f|  %> \r\n    <%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n   \r\n    <div style=\"margin-left:auto;margin-right:auto;padding:1px;width:730px;border:0px solid\">\r\n    <%=f.submit \"Save Today Attendance\", :class=>\'btn btn-success\' %>\r\n    </div>\r\n    <% end %>\r\n<% end%>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<%= this.list.html_safe  if @current_role==\'admin\' or @current_role==\'developer\'%>\r\n\r\n<br/>\r\n<p>\r\n<%# link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%# link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2016-09-29 09:04:10','2016-09-29 09:04:10','index',''),(2575,'payroll',1036,2,'<%\r\n   \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n   error=false\r\n    models = get_model\r\n    \r\n    attendance = models[:attendance].find params[:id]\r\n    \r\n    date = attendance.date\r\n    \r\n    apps = models[:appointment].where(:date=>{\'$gte\'=>date.beginning_of_day(),\'$lte\'=>date.end_of_day()}).all \r\n    \r\n    pm_map = {}\r\n    pms = module_model.where(:module_id=>apps.collect{|i| i.id}).all\r\n    \r\n    ppms = module_model.where(:parent_id=>pms.collect{|i| i.id}, :module_name=>\"\\\\#{@current_project.name}#billing\").all\r\n    \r\n    cats = {}\r\n    \r\n    \r\n    \r\n    \r\n    \r\n   \r\n   if request.post?\r\n       \r\n       if params[:payroll] and params[:payroll][:opd]and params[:payroll][:doctor]\r\n           \r\n            if attendance.payroll_check ==nil or attendance.payroll_check == false or attendance.payroll_check ==\'false\'\r\n              \r\n            \r\n            ipds = params[:payroll][:ipd]  \r\n              \r\n             \r\n            params[:payroll][:opd].each_pair do |key,opd|\r\n                    \r\n                    ipd = ipds[key] \r\n                    if x = models[:attendance_payroll].where(:attendance_id=>attendance.id, :provider=>key).first\r\n                        x.destroy\r\n                    end    \r\n                        \r\n                    att = models[:attendance_payroll].create :attendance_id=>attendance.id, :provider=>key, :amount=>opd.to_i,:amount_2=>ipd.to_i, :date=>date\r\n                    \r\n            end\r\n            \r\n            params[:payroll][:doctor].each_pair do |key,v|\r\n                \r\n                    opd = 0 \r\n                    opd = params[:payroll][:doctor_opd][key].to_i if params[:payroll][:doctor_opd][key]\r\n                    ipd = 0 \r\n                    ipd = params[:payroll][:doctor_ipd][key].to_i if params[:payroll][:doctor_ipd][key]\r\n                    \r\n                    if x = models[:attendance_payroll].where(:attendance_id=>attendance.id, :provider=>key).first\r\n                        x.destroy\r\n                    end   \r\n                    att = models[:attendance_payroll].create :attendance_id=>attendance.id, :provider=>key, :amount=>opd,:amount_2=>ipd, :date=>date\r\n                    \r\n            end\r\n            \r\n            \r\n            \r\n            \r\n            attendance.update_attributes :payroll_check=>true\r\n            \r\n            end\r\n            \r\n            %>\r\n                        <meta http-equiv=\"refresh\" content=\"0; url=index\" />\r\n\r\n\r\n            <%\r\n       end\r\n       \r\n else \r\n   \r\n    \r\n    models[:product_category].all.each do |i|\r\n        cats[i.id.to_s] = i  \r\n    end\r\n    \r\n    products = {}\r\n    \r\n    models[:product].all.each do |i|\r\n        products[i.id.to_s] = i  \r\n    end\r\n    \r\n    payroll_structs = {}\r\n    \r\n    models[:payroll_structure].all.each do |i|\r\n        payroll_structs[i.product_id.to_s] = i  \r\n    end\r\n    \r\n    providers = {}\r\n    models[:provider].all.each do |i|\r\n        providers[i.id.to_s] = i  \r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    %>\r\n<style>\r\n    .gray { color:#aaa;}\r\n</style>\r\n<h1>ประจำวันที่ \r\n<%=attendance.date%></h1>    \r\n<hr/>\r\n<center>\r\n<h3>รายชื่อผู้ขอรับบริการ\r\n    <br/>   <br/>\r\n</h3>\r\n</center>\r\n<table class=\"table\"> \r\n\r\n<thead>\r\n    <tr>\r\n    \r\n    <th>HN</th>\r\n        \r\n    <th>Description</th>\r\n    \r\n    <th>ราคา\r\n    </th>\r\n    <th>เบิกได้\r\n    </th>\r\n    <th>เบิกไม่ได้\r\n    </th>\r\n    <th>แพทย์\r\n    </th>\r\n    <th>ค่าบริการ\r\n    </th>\r\n    <th>ค่าบำรุง\r\n    </th>\r\n    <th>พยาบาล\r\n    </th>\r\n    <th>PN\r\n    </th>\r\n    <th>ธุรการ\r\n    </th>\r\n    <th>ลูกจ้าง\r\n    </th>\r\n    \r\n    \r\n        \r\n    </tr>\r\n</thead>\r\n<tbody>\r\n<%\r\n    \r\n    pos = {}\r\n    \r\n    pros = {}\r\n    \r\n    pros_list = {}\r\n    instrument = 0 \r\n        med_total = 0 \r\n    \r\n    for i in ppms\r\n    \r\n    \r\n    \r\n    patient = patient_model.find(i.patient_id)\r\n    pres = models[:billing].find(i.module_id)\r\n    \r\n    if pres.billing_type == \'2\'\r\n    \r\n    items = models[:billing_item].find(pres.items)\r\n    \r\n\r\n    \r\n    total = 0 \r\n    for j in items \r\n        p = products[j.product_id.to_s]\r\n        price = p.price\r\n        price = p.price_2 if pres.billing_type == \'2\' and p.price_2\r\n        total += price * j.quantity\r\n    end\r\n    \r\n    cls = \'\'\r\n    unless pres.provider_id\r\n        cls = \'color:red\' \r\n        error=true\r\n    end\r\n    \r\n%>\r\n\r\n<tr style=\"<%=cls%>\">\r\n<td width=\"100\"><b><%=link_to patient.hn,\"../Billing/edit?id=\\\\#{i.id}\"  %></b> <%#items.inspect %> <%#products.inspect %></td>\r\n<td><b><%=patient.first_name%> <%=patient.last_name%>  <span style=\"color:red\"><%=pres.type_of_patient %></span></b></td>\r\n<td colspan=\"10\"><v style=\"color:blue\"><%=fn total%></v></td>\r\n</tr>\r\n<% \r\n    med = 0 \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n\r\n    for j in items \r\n    p = products[j.product_id.to_s]\r\n    if p\r\n    s = payroll_structs[p.id.to_s]\r\n    row = \"\"\r\n    \r\n    price = p.price\r\n    price = p.price_2 if pres.billing_type == \'2\' and p.price_2\r\n    if p\r\n \r\nend\r\n    \r\n    unless s \r\n        row = \"gray\"\r\n        \r\n        \r\n     med+= price * j.quantity if price\r\n    \r\n       \r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n    if s \r\n        \r\n  \r\n    \r\n%>\r\n<tr class=\"<%=row%>\">\r\n<td>&nbsp;</td>\r\n<td><%= p.name %></td> \r\n<td> <%=fn price %> </td>\r\n<td> <%=fn p.reimbursable %> </td>\r\n<td> <%=fn (price.to_i - p.reimbursable.to_i) %> </td>\r\n\r\n\r\n<% if s \r\n\r\n    type = \"\\\\#{pres.type_of_patient}_\"\r\n    pos[\'instrument\'] = 0 unless  pos[\'instrument\']\r\n    pos[type+\'instrument\'] = 0 unless pos[type+\'instrument\']\r\n    pos[type+\'nurse\'] = 0 unless pos[type+\'nurse\']\r\n    pos[type+\'pn\'] = 0 unless pos[type+\'pn\']\r\n    pos[type+\'officer\'] = 0 unless pos[type+\'officer\']\r\n    pos[type+\'employee\'] = 0 unless pos[type+\'employee\']\r\n    \r\n    pos[\'instrument\'] += s.instrument.to_i\r\n    pos[type+\'instrument\'] += s.instrument.to_i\r\n    pos[type+\'nurse\'] += s.nurse.to_i\r\n    pos[type+\'pn\'] += s.pn.to_i\r\n    pos[type+\'officer\'] += s.officer.to_i\r\n    pos[type+\'employee\'] += s.employee.to_i\r\n    \r\n    \r\n    # pros[pres.provider_id] = 0 unless pros[pres.provider_id]\r\n    # pros[pres.provider_id] += s.doctor.to_i\r\n    \r\n    pros_list[pres.provider_id] = true\r\n    \r\n    if pres.type_of_patient==\'OPD\'\r\n        pros[pres.provider_id.to_s+\'_opd\'] = 0 unless pros[pres.provider_id.to_s+\'_opd\']\r\n        pros[pres.provider_id.to_s+\'_opd\'] += s.doctor.to_i\r\n    else\r\n        pros[pres.provider_id.to_s+\'_ipd\'] = 0 unless pros[pres.provider_id.to_s+\'_ipd\']\r\n        pros[pres.provider_id.to_s+\'_ipd\'] += s.doctor.to_i\r\n    end\r\n\r\n    \r\n%>\r\n<td>\r\n    <%=fn  s.doctor %>\r\n</td>\r\n<td>\r\n    <%=fn  s.fee %>\r\n</td>\r\n<td>\r\n    <%=fn  s.instrument %>\r\n</td>\r\n\r\n<td>\r\n    <%=fn  s.nurse %>\r\n</td>\r\n<td>\r\n    <%=fn  s.pn %>\r\n</td>\r\n<td>\r\n    <%=fn  s.officer %>\r\n</td>\r\n<td>\r\n    <%=fn  s.employee %>\r\n</td>\r\n<% else %>\r\n<td colspan=\"7\"></td>\r\n<% end%>\r\n\r\n\r\n</tr>\r\n<% end %>\r\n\r\n<% end %>\r\n<tr>\r\n    <td>&nbsp;</td>\r\n    <td>\r\n        ค่าเวชภัณฑ์\r\n    </td>\r\n    <td><%=fn med%></td>\r\n    <td colspan=\"7\"></td>\r\n    <%\r\n    med_total+= med\r\n    %>\r\n\r\n</tr>\r\n<% end%>\r\n<% end%>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>สรุปค่าตอบแทนเจ้าหน้าที่\r\n    \r\n    \r\n</h3>\r\n\r\n<br/>\r\n\r\n<% att = attendance %>\r\n\r\n\r\n<%= form_for :payroll, :url=>\"payroll?id=\\\\#{params[:id]}\", :url=>\'payroll\' do |f| %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n\r\n\r\n<table class=\"table\" style=\"width:500px\">\r\n<thead>\r\n    <th>Name</th>\r\n    <th>Position</th></th>\r\n    <th>OPD</th>\r\n    <th>IPD</th>\r\n    \r\n</thead>\r\n<tbody>\r\n\r\n<% 4.times do |j| %>\r\n\r\n<% \r\n    if att[\"n\\\\#{j+1}\"]\r\n    p = providers[att[\"n\\\\#{j+1}\"].to_s]\r\n%>\r\n<tr>\r\n<td> <%=p.name if p%></td>\r\n<td>\r\nพยาบาล\r\n</td>\r\n\r\n\r\n<td><%=fn pos[\'OPD_nurse\']%><%=f.hidden_field \"opd[\\\\#{p.id}]\", :value=>pos[\'OPD_nurse\'].to_i if p%> </td>\r\n\r\n<td><%=fn pos[\'IPD_nurse\']%><%=f.hidden_field \"ipd[\\\\#{p.id}]\", :value=>pos[\'IPD_nurse\'].to_i if p%> </td>\r\n</tr>\r\n<% end %>\r\n<% end %>  \r\n<% 3.times do |j| %>\r\n\r\n<% \r\n    if att[\"pn\\\\#{j+1}\"]\r\n    p = providers[att[\"pn\\\\#{j+1}\"].to_s]\r\n%>\r\n<tr>\r\n<td> <%=p.name if p%> </td>\r\n<td>\r\nPN\r\n</td>\r\n\r\n<td><%=fn pos[\'OPD_pn\']%><%=f.hidden_field \"opd[\\\\#{p.id}]\", :value=>pos[\'OPD_pn\'].to_i if p%> </td>\r\n\r\n<td><%=fn pos[\'IPD_pn\']%><%=f.hidden_field \"ipd[\\\\#{p.id}]\", :value=>pos[\'IPD_pn\'].to_i if p %> </td>\r\n</tr>\r\n<% end %>\r\n<% end %>  \r\n    \r\n<% 1.times do |j| %>\r\n\r\n<% \r\n    if att[\"officer\\\\#{j+1}\"]\r\n    p = providers[att[\"officer\\\\#{j+1}\"].to_s]\r\n%>\r\n<tr>\r\n<td> <%=p.name if p%> </td>\r\n<td>\r\nธุรการ\r\n</td>\r\n\r\n\r\n<td><%=fn pos[\'OPD_officer\']%><%=f.hidden_field \"opd[\\\\#{p.id}]\", :value=>pos[\'OPD_officer\'].to_i if p%></td>\r\n\r\n<td><%=fn pos[\'IPD_officer\']%><%=f.hidden_field \"ipd[\\\\#{p.id}]\", :value=>pos[\'IPD_officer\'].to_i if p%></td>\r\n\r\n\r\n</tr>\r\n<% end %>\r\n<% end %> \r\n\r\n<% 2.times do |j| %>\r\n\r\n<% \r\n    if att[\"employee\\\\#{j+1}\"]\r\n    p = providers[att[\"employee\\\\#{j+1}\"].to_s]\r\n%>\r\n<tr>\r\n<td> <%=p.name if p%> </td><td>\r\nลูกจ้างประจำ \r\n</td> \r\n </td>\r\n<td><%=fn pos[\'OPD_employee\']%><%=f.hidden_field \"opd[\\\\#{p.id}]\", :value=>pos[\'OPD_officer\'].to_i if p%></td>\r\n\r\n<td><%=fn pos[\'IPD_employee\']%><%=f.hidden_field \"ipd[\\\\#{p.id}]\", :value=>pos[\'IPD_officer\'].to_i if p%></td>\r\n\r\n\r\n    \r\n</tr>\r\n<% end %>\r\n<% end %> \r\n    \r\n</tbody>\r\n\r\n\r\n</table>\r\n\r\n\r\n<h3>สรุปค่าตอบแทนแพทย์และค่าบำรุงเวชภัณฑ์\r\n</h3>\r\n\r\n<br/>\r\n<table class=\"table\" style=\"width:400px\">\r\n<thead>\r\n\r\n    <th>Name</th>\r\n    <th>รวม</th>\r\n    <th>OPD</th>\r\n    <th>IPD</th>\r\n    \r\n    \r\n</thead>\r\n<tbody>\r\n<%#pros.inspect %>\r\n<% \r\n if  pros\r\npros_list.each_pair do |k,v| \r\np = providers[k.to_s]\r\n\r\nopd = 0 \r\nopd = pros[k.to_s+\"_opd\"] if pros[k.to_s+\"_opd\"]\r\n\r\n\r\nipd = 0 \r\nipd = pros[k.to_s+\"_ipd\"] if pros[k.to_s+\"_ipd\"]\r\n\r\n%>\r\n<tr>\r\n    <%=f.hidden_field \"doctor[\\\\#{p.id}]\", :value=>opd+ipd  if p%>\r\n    <td><%=p.name if p%></td> <td><%=fn opd+ipd%></td>  <td><%=fn opd%></td> <td><%=fn ipd%></td>\r\n    <%=f.hidden_field \"doctor_opd[\\\\#{p.id}]\", :value=>opd if p%>\r\n    <%=f.hidden_field \"doctor_ipd[\\\\#{p.id}]\", :value=>ipd if p %>\r\n\r\n</tr>\r\n<% end%>\r\n<% end%>\r\n<tr>\r\n    <td>\r\n    ค่าบำรุง   \r\n    </td>  <td><%=fn pos[\'instrument\']%></td>\r\n    <td></td><td></td>\r\n</tr>\r\n\r\n<tr>\r\n    <td>\r\n    ค่าเวชภัณฑ์   \r\n    </td>  <td><%=fn med_total %></td>\r\n    <td></td><td></td>\r\n\r\n\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n\r\n\r\n<center>\r\n\r\n<% unless error %>\r\n    <%=f.submit \"Submit\",:class=>\'btn btn-success\',:data=>{:confirm=>\'Are you sure?\',:disable_with=>\'Loading..\'} if attendance.payroll_check!=\'true\' %>\r\n<% else%>\r\n    <span style=\"color:red\">There is unlink doctor in billing form!</span>\r\n<% end %>\r\n\r\n    <%= link_to \'Back\', \"../Attendance/index\" %>\r\n    \r\n</center>\r\n<% end%>\r\n<%# pos.inspect %>\r\n<% end%>',NULL,NULL,NULL,'2016-09-29 09:24:32','2016-09-29 09:24:32','payroll',''),(2576,'index',721,2,'<%\r\nmodule_name = @current_project.name\r\nif params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\nend\r\nif session[module_name]\r\n	params[:date] = session[module_name][:date]\r\nend\r\nunless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\nend\r\n\r\nif session[:owner].nil?\r\n    session[:owner] = false\r\nend\r\n\r\nif @current_role==\'developer\'\r\n    session[:owner] = true\r\n    session[:pin] = \'\'\r\nend\r\n\r\n%>\r\n\r\n<style>\r\n\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n    \r\n    if session[:pin].nil? or session[:pin] == \'\'\r\n        r_user = model[:user].where(:login=>@current_user.login.to_s).first\r\n        if !r_user.nil? and r_user[:pin]\r\n            session[:pin] = r_user[:pin].to_s\r\n        else\r\n            session[:pin] = \'\'\r\n        end\r\n    end\r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n\r\n    provider = models[:provider].where(:login=>@current_user.login).first\r\n    if !provider.nil?\r\n      s_provider = provider.id.to_s\r\n    end\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn].upcase if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n    # PIN Section\r\n    in_pin = nil\r\n    if p = params[:record]\r\n        in_pin = p[:pin]\r\n        if p[:patient_id] != \'\' and in_pin == session[:pin] and p[:mode] == \'delete\'\r\n            destroy_url = \"destroy?mode=patient&id=\\\\#{p[:patient_id]}\".html_safe\r\n            return_url  = \"&return=\\\\#{request.fullpath}\".html_safe\r\n%>\r\n<script>\r\n                url = \"<%= destroy_url %><%= return_url %>\";\r\n                window.location = url;\r\n</script>\r\n<%\r\n        elsif p[:mode] == \'unlock\' and in_pin == session[:pin]\r\n            session[:owner] = true\r\n        elsif p[:mode] == \'lock\'\r\n            session[:owner] = false\r\n        end\r\n    end\r\n    \r\n    if p = params[:newpin]\r\n        if p[:pin] == p[:con_pin]\r\n        \r\n            r_user = model[:user].where(:login=>@current_user.login.to_s).first\r\n            r_user[:pin] = p[:pin]\r\n            r_user.save\r\n            \r\n            session[:owner] = true\r\n        end\r\n    end\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       My Patients\r\n       <span style=\'float:right\'>\r\n       <% if session[:owner] %>\r\n                <%= link_to \'<i class=\"splashy-document_a4\"></i> Reports\'.html_safe,\"../Home/report\", :class=>\'btn btn-mini\' %> | \r\n                <%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \"\\\\#{params[:opt]}?record[mode]=lock\", :class=>\'btn btn-mini btn-warning\' %>\r\n                <!--<%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \'javascript:lock_unlock(\"lock\")\', :class=>\'btn btn-mini btn-warning\' %>-->\r\n                <% else %>\r\n                <%=link_to \'<i class=\"splashy-lock_large_unlocked\"></i> Unlock\'.html_safe, \'javascript:lock_unlock(\"unlock\");\', :class=>\'btn btn-mini btn-warning\' %>\r\n        <% end %>\r\n        <!--\r\n        <a href=\'/esm/cusys/thks/Consignment-TH.pdf\' class=\'btn btn-mini\' target=\'_blank\'>\r\n            <i class=\"splashy-document_a4_marked\"></i>\r\n            Consignment (TH)\r\n        </a>\r\n        -->\r\n    </span>\r\n    </div>  \r\n    \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\"../Home/\\\\#{params[:opt]}\",:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n\r\n<!--           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n            </div>\r\n            </span>\r\n-->            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n        <% if @current_role==\'developer\' %>    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surgeon :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n            </div>\r\n            </span>\r\n        <% end %>    \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\" style=\'width:300px\'> \r\n                <label class=\"field-label\">\r\n                   &nbsp;\r\n                </label> \r\n                \r\n                \r\n                <div class=\"field-input\" style=\'width:200px\'>\r\n                     <%=f.submit \'Search\', :class=>\'btn btn-success\'%> \r\n                     <% if !session[:owner] %>\r\n                     <%= link_to \'Show All\', \"javascript:show_all()\", :class=>\'btn btn-warning\', :style=>\'margin-top:5px\' %>\r\n                     <% end %>\r\n                     <!--<%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>-->\r\n                </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            <div class=\"field-input\">\r\n            <%\r\n            # Home/patient_record?id=5533e537790f9b01c2000006\r\n                # add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n                if s_provider \r\n                    # add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                    add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                end\r\n                \r\n            %>\r\n              \r\n                 <!--<%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>-->\r\n            </div>\r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        </div>\r\n        <div class=\"row-fluid\"></div>\r\n \r\n<strong>\r\n<%\r\n    rs = []\r\n    if !search_patient and params[:select].nil?\r\n    	# filter provider\r\n    	if (!s_provider.nil?) and (s_provider != \'\')\r\n    	    if (session[:pin] == in_pin) or session[:owner]\r\n                rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n            else\r\n                \r\n            end\r\n        else\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\").all\r\n    	end\r\n    %>\r\n    <!--ALL : <%= rs.size %> | <%= s_provider %> -->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name, :last_name=>s_last_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        # 	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n            keys << {k.to_sym=>v}\r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n        patients = patient_model.where(criteria).all\r\n        # patients = patient_model.where(criteria).limit(20).all\r\n	    # maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}\r\n        # aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     	    rs = module_model.where(:patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\"\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT : <%= rs.size %>-->\r\n    <%\r\n    elsif params[:date]\r\n        require \'date\'\r\n        dddd = Date.parse(params[:date])\r\n	    conds = {:date.gte=>dddd.at_beginning_of_day,:date.lt=>dddd.end_of_day, :module_name=>\"\\\\#{@current_project.name}#provider\"}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n            conds.merge! :module_id=>s_provider \r\n            # conds[:module_id] = s_provider\r\n            # conds[:module_name] = @current_project.name + \"#provider\"\r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n        rs = module_model.where(conds).all\r\n        # aps = ap_model.all(conds)\r\n    	# filter provider\r\n    # 	if s_provider and s_provider != \'\'\r\n     	  #  conds[:module_id] = s_provider\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    #  	else\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    # 	end\r\n    	\r\n    # 	rs = module_model.all(conds)\r\n        # rs = module_model.all\r\n\r\n    %>\r\n    <!--DATE : <%=rs.size%> | <%= conds %>-->\r\n    <%\r\n    end # end if\r\n%>\r\n</strong>\r\n<!--<br/>-->\r\n<!--<br/>-->\r\n<%\r\nm_procedure = models[:procedure].all\r\nmap_proc = {}\r\nfor m in m_procedure do\r\n    map_proc[m.id] = m\r\nend\r\n\r\nm_provider  = models[:provider].all\r\nmap_prov = {}\r\nfor m in m_provider do \r\n    map_prov[m.id.to_s] = m[:name]\r\nend\r\nresult = rs.collect do |i|\r\n    m_patient = patient_model.find(i[:patient_id].to_s)\r\n    \r\n    # patient_name = m_patient[:prefix_name] + m_patient[:first_name] + \" \" + m_patient[:last_name]\r\n    patient_name = \"\\\\#{m_patient[:prefix_name]}\\\\#{m_patient[:first_name]}   \\\\#{m_patient[:last_name]}\"\r\n    \r\n    # prov = map_prov[i[:id]]\r\n    m_id = i[:module_id].to_s\r\n    prov = map_prov[m_id]\r\n    \r\n    # prov = nil\r\n    proc_rs = []\r\n    # OLD\r\n    # m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    # for m in m_ap do\r\n    #     ap = models[:appointment].find(m[:module_id])\r\n    #     if ap\r\n    #         proc_rs.push(map_proc[ap[:procedure]])\r\n    #     end\r\n    # end\r\n    # NEW\r\n    m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    for m in m_ap do\r\n        ap = models[:appointment].find(m[:module_id])\r\n        if ap\r\n            # proc_rs.push(map_proc[ap[:procedure]])\r\n            procedure = map_proc[ap[:procedure]]\r\n            if procedure.nil?\r\n                next\r\n            end\r\n            code = procedure[:code]\r\n            name = procedure[:name]\r\n            m_code = \"\\\\#{@current_project.name}#\\\\#{code}\"\r\n            m_tmp = module_model.where(:module_name=>m_code, :parent_id=>m.id).first\r\n            side = \'-\'\r\n            if m_tmp\r\n                rec = models[code.to_sym].find(m_tmp[:module_id])\r\n                if rec[:side] == \'1\'\r\n                    side = \'L\'\r\n                elsif rec[:side] == \'2\'\r\n                    side = \'R\'\r\n                end\r\n            end\r\n            # txt = name + \" (\" + side + \") \"\r\n            op_txt = \"op : \\\\#{rec[:operation_date]}\" if rec\r\n            txt = \"\\\\#{name} (\\\\#{side}) <span style=\'float:right\'>\\\\#{op_txt}</span>\".html_safe\r\n            \r\n            if @current_role == \'developer\'\r\n                m_tmp = module_model.where(:parent_id=>m.id).collect{|i| i if i[:module_name].include? \'follow\'}\r\n                txt += \"[\" + m_tmp.count.to_s + \"]\"\r\n            end\r\n            \r\n            proc_rs.push(txt)\r\n        end\r\n    end\r\n    \r\n    proc_txt = \'<center><font color=\"red\">-- Create New --</font></center>\'\r\n    if !proc_rs.empty?\r\n        proc_txt = \'\'\r\n        for x in proc_rs do \r\n            if proc_rs.last == x\r\n                proc_txt += \"<div class=\'row-fluid\' style=\'float:left;padding: 0.5em 0 0.5em 0;\'>\\\\#{x.to_s}</div>\"\r\n            else\r\n                proc_txt += \"<div class=\'row-fluid\' style=\'float:left;padding: 0.5em 0 0.5em 0;border-bottom: 1px solid gray;\'>\\\\#{x.to_s}</div>\"\r\n            end\r\n            # proc_txt += \"<div class=\'row-fluid\' style=\'float:left;padding: 0.5em 0 0.5em 0;\'>\\\\#{x.to_s}</div>\"\r\n        end\r\n    end\r\n    action = \' \'\r\n    action += link_to(\'Detail\',\"patient_record?id=\\\\#{i[:patient_id]}\",:class=>\'btn btn-info\')\r\n    action += \" \"\r\n    action += link_to(\'\', \"../../www/Patient/edit?id=\\\\#{m_patient.id}&return=\\\\#{request.fullpath}\", :class=>\'splashy-contact_blue_edit\').html_safe\r\n    action += \" \"\r\n    if session[:owner]\r\n        action += link_to(\'\', \"\", :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{m_patient.id}\'); return false;\")\r\n    else\r\n        action += link_to(\'\', \"\", :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_pin(\'\\\\#{m_patient.id}\'); return false;\")\r\n    end\r\n    action += \" \"\r\n    \r\n    {:date=>i[:date], :hn=>m_patient[:hn], :name=>patient_name, :pid=>i[:patient_id], :procedure=>proc_txt, :action=>action, :provider=>prov}\r\nend\r\ncount = 1\r\nlabels = {:no=>\'No.\', :date=>\'Added Date\', :hn=>\'HN\', :name=>\'Patient Name\', :procedure=>\'Previous Procedure\', :action=>\'Action\'}\r\nfield_select = [:no, :date, :hn, :name, :procedure, :action]\r\n\r\nif @current_role == \'developer\'\r\n    labels[:provider] = \'Provider\'\r\n    field_select.insert(4, :provider)\r\nend\r\nresult = result.sort_by{|i| i[:date]}.reverse\r\n%>\r\n        \r\n        <!--<div class=\"row-fluid\">-->\r\n        <!--    <div style=\"padding-left:10px;display:block;vertical-align:middle\">-->\r\n        <!--        All Patient(s) : <v><%= result.count if result %></v> <%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>-->\r\n        <!--    </div>-->\r\n        <!--</div>-->\r\n        <!--<br/>-->\r\n        <div class=\"row-fluid\">\r\n            <br/>\r\n            <div class=\"\" style=\"float:left;margin-left:10px\">\r\n                All Patient(s) : <span style=\"color:blue\"><%= result.count if result %></span>\r\n                <%=link_to \'<i class=\"splashy-contact_blue_add\"></i> Add Patient\'.html_safe, add_patient, :class=>\'btn btn-info btn-mini\', :style=>\'margin-left:10px\'%>\r\n            </div>\r\n            <% if false %>\r\n            <div class=\"\" style=\"float:right;margin-right:10px\">\r\n                <%=link_to \'<i class=\"splashy-sprocket_light\"></i> Setting\'.html_safe, \'../Setting/index\', :class=>\'btn btn-mini\' %> | \r\n                <% if session[:owner] %>\r\n                <%= link_to \'<i class=\"splashy-document_a4\"></i> Reports\'.html_safe,\"../Home/report\", :class=>\'btn btn-mini\' %> | \r\n                <%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \"\\\\#{params[:opt]}?record[mode]=lock\", :class=>\'btn btn-mini btn-warning\' %>\r\n                <!--<%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \'javascript:lock_unlock(\"lock\")\', :class=>\'btn btn-mini btn-warning\' %>-->\r\n                <% else %>\r\n                <%=link_to \'<i class=\"splashy-lock_large_unlocked\"></i> Unlock\'.html_safe, \'javascript:lock_unlock(\"unlock\");\', :class=>\'btn btn-mini btn-warning\' %>\r\n                <% end %>\r\n            </div>\r\n            <% end %>\r\n            <br/>\r\n        </div>\r\n        \r\n        <div id=\"result-panel\" style=\"padding:10px\">\r\n<% if result.count > 1 or session[:owner] %>\r\n            <%# tabular :data=>result, :model=>field_select, :labels=>labels, :col_width=>{:no=>50} do |row,out| %>\r\n            <%= tabular :data=>result, :model=>field_select, :labels=>labels, :col_width=>{:no=>80, :procedure=>300} do |row,out|\r\n                    out[0] = \"<center>\" + count.to_s+\".</center>\"\r\n                    out[0] = out[0].html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n            %>\r\n<% elsif result.count == 1  and search_patient %>\r\n<script>\r\n    window.location = \"patient_record?id=<%= result[0][:pid] %>\";\r\n</script>\r\n<% \r\n    else \r\n        if request.post? and !session[:owner]\r\n%>\r\n                        <div style=\'margin: auto;width:60%;\'>\r\n                            <div class=\"alert\">\r\n								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n								<strong>Invalid Private Password.</strong> Please try again or contact administrator for setting your private password.\r\n							</div>\r\n							<div class=\'clear\'></div>\r\n						</div>\r\n<%\r\n        end\r\n%>\r\n            <center><font size=\'2.5em\'><strong>Search Patient to continue.</strong></font></center>\r\n<% \r\n    end\r\n%>\r\n        </div>\r\n        \r\n    </div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function confirm_pin(id) {\r\n        \r\n    }\r\n\r\n    function confirm_delete(id) {\r\n        // destroy?id=\\\\#{m_patient.id}&mode=patient&return=\\\\#{request.fullpath}\r\n<%\r\n    destroy_url = \"destroy?mode=patient&id=\".html_safe\r\n    return_url  = \"&return=\\\\#{request.fullpath}\".html_safe\r\n%>\r\n        if (confirm(\"Do you want to delete patient data ?\") == true) {\r\n            if (confirm(\"All of patient data will be lost\") == true) {\r\n                url = \"<%= destroy_url %>\" + id + \"<%= return_url %>\";\r\n                window.location = url;\r\n            }\r\n        }\r\n    }\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<!--\r\n<div class=\"alert \">\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n</div>\r\n-->\r\n<script>\r\n\r\n    <%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    user = model[:user].where(:login=>@current_user.login).first\r\n    \r\n    %>\r\n    \r\n    function access(target){\r\n        \r\n        var pin = prompt(\"Please enter PIN\", \"\");\r\n        if( \'<%= user ? user.pin : \'-\'%>\'==pin){\r\n            window.location = target\r\n        }\r\n        \r\n        \r\n    }\r\n    \r\n</script>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n\r\n<!--\r\n\r\n    Modal\r\n\r\n-->\r\n\r\n<div class=\"modal hide fade\" id=\"modal-pin\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"close\" style=\"float:right;\"  data-dismiss=\"modal\">X</a>\r\n        <h3>Private Access</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"pin\" class=\"  portlet \" style=\"border:0px solid blue;width:250px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Please input your private password : </label></span>	\r\n                    <input type=\"password\" name=\"record[pin]\" id=\"data-pin\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n            <%= f.hidden_field :mode, :id=>\'data-mode\', :value=>\'\' %>\r\n            <%= f.hidden_field :patient_id, :id=>\'data-patient_id\', :value=>\'\' %>\r\n            <%= f.submit \'Submit\', :class=>\'btn btn-info\' %>\r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n    function pin() {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function show_all() {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(\'show\');\r\n    }\r\n    function lock_unlock(mode) {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(mode);\r\n    }\r\n    function confirm_pin(id) {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(\'delete\');\r\n        $(\'#data-patient_id\').val(id);\r\n    }\r\n    <% if false %>\r\n    function check_pin() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    <% end %>\r\n    $(document).ready(function(){\r\n        $(\'#btn-pin\').click(pin);\r\n    });\r\n</script>\r\n\r\n<%\r\n    # if no pin create then popup create PIN\r\n    r_user = model[:user].where(:login=>@current_user.login.to_s).first\r\n    if r_user.nil?\r\n        r_user = {}\r\n    end\r\n    if r_user[:pin].nil? or r_user[:pin] == \'\'\r\n%>\r\n<div class=\"modal hide fade\" id=\"modal-create_pin\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"close\" style=\"float:right;\"  data-dismiss=\"modal\">X</a>\r\n        <h3>Create New Private Password</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :newpin , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"pin\" class=\"  portlet \" style=\"border:0px solid blue;width:250px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Please input your private password : </label></span>	\r\n                    <input type=\"password\" name=\"newpin[pin]\" id=\"data-pin\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                \r\n                <div id=\"con_pin\" class=\"  portlet \" style=\"border:0px solid blue;width:250px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Please confirm your private password : </label></span>	\r\n                    <input type=\"password\" name=\"newpin[con_pin]\" id=\"data-con_pin\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n            <%= f.submit \'Submit\', :class=>\'btn btn-info\' %>\r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\'#modal-create_pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n    });\r\n</script>\r\n<%  end %>',NULL,NULL,NULL,'2016-09-29 16:09:10','2016-09-29 16:09:10','',''),(2577,'edit',1033,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model()[this.table_name.to_sym]\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this document!!\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n     \r\n    t = Time.now - record.updated_at \r\n \r\n \r\n    if  false and  @current_role!=\'superuser\' and @current_role!=\'developer\' and @current_role!=\'admin\' # and t.to_i > 3600 * 24 \r\n     locker.destroy if locker\r\n  %>\r\n   <script>alert(\"Not allowed to edit this document!!\");window.location = \"<%=return_url%>\";</script>\r\n  <%\r\n  end\r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    \r\n    if params[:items]\r\n       \r\n       models = get_model\r\n       \r\n       products = models[:product].find(params[:items].keys)\r\n       \r\n       items = models[:billing_item].find(record.items)\r\n       for i in items\r\n        i.destroy\r\n       end\r\n       \r\n       items = []\r\n       \r\n       for i in products\r\n       \r\n            j = params[:items][i.id.to_s].to_i\r\n            price = params[:price][i.id.to_s].to_i\r\n            note = params[:note][i.id.to_s]\r\n\r\n\r\n            if j > 0 \r\n                 k = models[:billing_item].create :quantity=>j, :product_id=>i.id, :title=>i.name,:price=>price,:note=>note\r\n            \r\n                items << k.id\r\n            end\r\n        \r\n        end\r\n       \r\n       \r\n       record.update_attributes :items=>items\r\n       \r\n       \r\n        \r\n    end\r\n    \r\n    \r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n window.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \"Update\".html_safe, :class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:data=>{:confirm=>\'Are you sure?\'} %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   ',NULL,NULL,NULL,'2016-09-30 17:18:37','2016-09-30 17:18:37','edit',''),(2578,'create',1033,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n     if params[:items]\r\n       \r\n       models = get_model\r\n       \r\n       products = models[:product].find(params[:items].keys)\r\n       \r\n       items = models[:billing_item].find(record.items)\r\n       for i in items\r\n        i.destroy\r\n       end\r\n       \r\n       items = []\r\n       \r\n       for i in products\r\n       \r\n            j = params[:items][i.id.to_s].to_i\r\n            price = params[:price][i.id.to_s].to_i\r\n            note = params[:note][i.id.to_s]\r\n            if j > 0 \r\n                 k = models[:billing_item].create :quantity=>j, :product_id=>i.id, :title=>i.name,:price=>price, :note=>note\r\n            \r\n                items << k.id\r\n            end\r\n        \r\n        end\r\n       \r\n       \r\n       record.update_attributes :items=>items\r\n       \r\n       \r\n        \r\n    end\r\n    \r\n \r\n \r\n%>\r\n<!--\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n-->\r\n<%=params.inspect %>\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2016-09-30 18:13:10','2016-09-30 18:13:10','create',''),(2579,'index',1041,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2016-10-01 03:25:30','2016-10-01 03:25:30',NULL,NULL),(2580,'layout',1041,4,'<%=default_layout%>',NULL,NULL,NULL,'2016-10-01 03:25:30','2016-10-01 03:25:30',NULL,NULL),(2581,'index',965,3,'\r\n\r\n<!DOCTYPE html>\r\n<!--[if lt IE 7]>      <html class=\"no-js lt-ie9 lt-ie8 lt-ie7\"> <![endif]-->\r\n<!--[if IE 7]>         <html class=\"no-js lt-ie9 lt-ie8\"> <![endif]-->\r\n<!--[if IE 8]>         <html class=\"no-js lt-ie9\"> <![endif]-->\r\n<!--[if gt IE 8]><!--> <html class=\"no-js\"> <!--<![endif]-->\r\n	<head>\r\n	<meta charset=\"utf-8\">\r\n	<meta http-equiv=\"X-UA-Compatib