r-variations li a[data-theme=\"lightblue\"] {\r\n		background: #5585b5;\r\n	}\r\n	#colour-variations li a[data-theme=\"brown\"] {\r\n		background: #a03232;\r\n	}\r\n	#colour-variations li a[data-theme=\"green\"] {\r\n		background: #65d269;\r\n	}\r\n\r\n	.option-toggle {\r\n		position: absolute;\r\n		right: 0;\r\n		top: 0;\r\n		margin-top: 5px;\r\n		margin-right: -30px;\r\n		width: 30px;\r\n		height: 30px;\r\n		background: #f64662;\r\n		text-align: center;\r\n		border-top-right-radius: 4px;\r\n		border-bottom-right-radius: 4px;\r\n		color: #fff;\r\n		cursor: pointer;\r\n		-webkit-box-shadow: 0 0 9px 0 rgba(0,0,0,.1);\r\n		-moz-box-shadow: 0 0 9px 0 rgba(0,0,0,.1);\r\n		-ms-box-shadow: 0 0 9px 0 rgba(0,0,0,.1);\r\n		box-shadow: 0 0 9px 0 rgba(0,0,0,.1);\r\n	}\r\n	.option-toggle i {\r\n		top: 2px;\r\n		position: relative;\r\n	}\r\n	.option-toggle:hover, .option-toggle:focus, .option-toggle:active {\r\n		color:  #fff;\r\n		text-decoration: none;\r\n		outline: none;\r\n	}\r\n	\r\n.black-ribbon {\r\n  position: fixed;\r\n  z-index: 9999;\r\n  width: 70px;\r\n}\r\n@media only all and (min-width: 768px) {\r\n  .black-ribbon {\r\n    width: auto;\r\n  }\r\n}\r\n\r\n.stick-left { left: 0; }\r\n.stick-right { right: 0; }\r\n.stick-top { top: 0; }\r\n.stick-bottom { bottom: 0; }\r\n	\r\n<% if false %>\r\n*{\r\n    -moz-filter: grayscale(30%);\r\n    -webkit-filter: grayscale(30%);\r\n    filter: grayscale(0.3); /* IE6-9 */\r\n    filter: grayscale(30%);\r\n    \r\n}\r\n<% end %>\r\n	</style>\r\n	<!-- End demo purposes only -->\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    posts = models[:post].where(:published=>\'true\').limit(6).reverse\r\n    \r\n    \r\n\r\n%>\r\n\r\n	<!-- Modernizr JS -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/modernizr-2.6.2.min.js\"></script>\r\n	<!-- FOR IE9 below -->\r\n	<!--[if lt IE 9]>\r\n	<script src=\"/esm/thks_web/www/content/web/js/respond.min.js\"></script>\r\n	<![endif]-->\r\n\r\n	</head>\r\n	<body>\r\n	<img src=\"/esm/thks_web/www/content/web/images/black_ribbon_top_left.png\" class=\"black-ribbon stick-top stick-left\"/>\r\n	<header role=\"banner\" id=\"fh5co-header\">\r\n			<div class=\"container\">\r\n				<!-- <div class=\"row\"> -->\r\n			    <nav class=\"navbar navbar-default\">\r\n		        <div class=\"navbar-header\" >\r\n		        	<!-- Mobile Toggle Menu Button -->\r\n					<a href=\"#\" class=\"js-fh5co-nav-toggle fh5co-nav-toggle\" data-toggle=\"collapse\" data-target=\"#navbar\" aria-expanded=\"false\" aria-controls=\"navbar\"><i></i></a>\r\n		          	<a class=\"navbar-brand\" href=\"index.html\" ><img src=\"/esm/thks_web/www/content/web/images/logolong.png\" width=\"180\" style=\"float:left\"></a> \r\n		        </div>\r\n		        <div id=\"navbar\" class=\"navbar-collapse collapse\">\r\n		          <ul class=\"nav navbar-nav navbar-right\">\r\n		            <li class=\"active\"><a href=\"#\" data-nav-section=\"home\"><span>Home</span></a></li>\r\n		            <li><a href=\"#\" data-nav-section=\"about\"><span>About</span></a></li>\r\n		            <li><a href=\"#\" data-nav-section=\"services\"><span>Value</span></a></li>\r\n		             <li><a href=\"#\" data-nav-section=\"news\"><span>News</span></a></li>\r\n		            <li><a href=\"register\" target=\"_blank\"><span>Register</span></a></li>\r\n		            <li><a href=\"http://thkjr.info\" target=\"_blank\"><span>THKJS</span></a></li>\r\n		            <li><a href=\"#\" data-nav-section=\"pricing\"><span>Contact</span></a></li>\r\n		            \r\n		          </ul>\r\n		        </div>\r\n			    </nav>\r\n			  <!-- </div> -->\r\n		  </div>\r\n	</header>\r\n\r\n	<div id=\"slider\" data-section=\"home\">\r\n		<div class=\"owl-carousel owl-carousel-fullwidth\">\r\n			<!-- You may change the background color here. -->\r\n		    <div class=\"item\" style=\"background: url(/esm/thks_web/www/content/web/images/bg1.jpg)no-repeat center center; \r\n  -webkit-background-size: cover;\r\n  -moz-background-size: cover;\r\n  -o-background-size: cover;\r\n  background-size: cover;\">\r\n		    	<div class=\"container\" style=\"position: relative;\">\r\n		    		<div class=\"row\">\r\n					    <div class=\"col-md-7 col-sm-7\">\r\n			    			<div class=\"fh5co-owl-text-wrap\">\r\n						    	<div class=\"fh5co-owl-text\">\r\n						    		<h1 class=\"fh5co-lead to-animate\">Thai Hip-Knee Joint REgistry</h1>\r\n									<h2 class=\"fh5co-sub-lead to-animate\">สร้างข้อมูลการรักษาด้วยกันเพื่ออนาคตของคนไทย <a href=\"http://freehtml5.co/\" target=\"_blank\">THKJR System</a></h3>\r\n									<p class=\"to-animate-2\"><a href=\"register\" class=\"btn btn-primary btn-lg\">สมัครสมาชิก</a></p>\r\n						    	</div>\r\n						    </div>\r\n					    </div>\r\n					    <div class=\"col-md-4 col-md-push-1 col-sm-4 col-sm-push-1 iphone-image\">\r\n					    	<div class=\"iphone to-animate-2\"><img src=\"/esm/thks_web/www/content/web/images/iphone-3.png\" alt=\"Free HTML5 Template by FREEHTML5.co\"></div>\r\n					    </div>\r\n\r\n		    		</div>\r\n		    	</div>\r\n		    </div>\r\n			<!-- You may change the background color here.  -->\r\n		   \r\n\r\n		    <div class=\"item\" style=\"background: url(/esm/thks_web/www/content/web/images/slide_5.jpg) no-repeat center center; \r\n  -webkit-background-size: cover;\r\n  -moz-background-size: cover;\r\n  -o-background-size: cover;\r\n  background-size: cover;\">\r\n		    	<div class=\"overlay\"></div>\r\n		    	<div class=\"container\" style=\"position: relative;\">\r\n		    		<div class=\"row\">\r\n		    			<div class=\"col-md-8 col-md-offset-2 text-center\">\r\n		    				<div class=\"fh5co-owl-text-wrap\">\r\n						    	<div class=\"fh5co-owl-text\">\r\n		    						<h1 class=\"fh5co-lead to-animate\">VDO งานประชุม</h1>\r\n									<h2 class=\"fh5co-sub-lead to-animate\">อธิบายความสำคัญการเก็บข้อมูลทางการแพทย์ </h3>\r\n									<p class=\"to-animate-2\"><a href=\"/www/Home/post?id=57f6436b790f9b0de9000005\" target=\"_blank\" class=\"btn btn-primary btn-lg\">คลิกที่นี้</a></p>\r\n								</div>\r\n							</div>\r\n		    			</div>\r\n		    		</div>\r\n		    	</div>\r\n		    </div>\r\n\r\n		</div>\r\n	</div>\r\n	\r\n	<div id=\"fh5co-about-us\" data-section=\"about\">\r\n		<div class=\"container\">\r\n			<div class=\"row row-bottom-padded-lg\" id=\"about-us\">\r\n				<div class=\"col-md-12 section-heading text-center\">\r\n					<h2 class=\"to-animate\">About THKJR</h2>\r\n					<p>The Thai Hip and Knee Joint Registry collect information on joint replacement surgery and monitor the performance of joint replacement implants. This program was set up by Thai Hip and Knee Society in January 2015.\r\nHip and knee joint replacement have become common and highly successful procedure that helps patients return to daily life by improved mobility and relief pain. There are more than thousands of such procedures perform in Thailand every year.\r\nWith constant strive to improve patient outcomes; there are many types of implants can be used in joint replacement procedures. The registry helps to monitor the performance of these implants and effectiveness of different technique of surgery, improving clinical standards and surgery outcome, and the orthopaedic sector as a whole. The THKJR currently collects data on all hip and knee joint replacements across Thailand. </p>\r\n					<strong>Mission</strong><br /><p>The purpose of the Thai Hip and Knee Joint Registry is to collect high quality and relevant data about joint replacement surgery in order to provide an early warning of issues relating to patient safety. In a continuous drive to improve the quality of outcomes and ensure the quality and cost effectiveness of joint replacement surgery, the THKJR will monitor and report on outcomes, and support and enable related research.</p>\r\n				<strong>Goals</strong><br /><p>Monitor outcomes achieved by brand of prosthesis, hospital and surgeon, and highlight where these fall below an expected performance in order to allow prompt investigation.\r\nInform patients, clinicians, providers and commissioners of healthcare, regulators and implant suppliers of the outcomes achieved in joint replacement surgery.\r\n Evidence variations in outcome achieved across surgical practice in order to inform best practice.\r\nSupport evidence-based purchasing of joint replacement implants for healthcare providers to support quality and cost effectiveness.\r\nHow does the THKJR benefit patients?\r\n\r\nBe able to provide best perform prosthesis and surgical technique\r\nImprove patient safety by showing how well implants, surgeons and hospitals perform and take action where it is needed</p>\r\n<p>\r\n     <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a6002f790f9b6270000013.jpg\" alt=\"57a6002f790f9b6270000013\">  <span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60031790f9b627000001c.gif\" alt=\"57a60031790f9b627000001c\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60031790f9b627000001f.jpg\" alt=\"57a60031790f9b627000001f\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a6002e790f9b627000000d.png\" alt=\"57a6002e790f9b627000000d\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a6002e790f9b6270000010.jpg\" alt=\"57a6002e790f9b6270000010\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60030790f9b6270000016.jpg\" alt=\"57a60030790f9b6270000016\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60031790f9b6270000019.jpg\" alt=\"57a60031790f9b6270000019\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60032790f9b1ac200006e.jpg\" alt=\"57a60032790f9b1ac200006e\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60032790f9b1ac2000071.jpg\" alt=\"57a60032790f9b1ac2000071\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60033790f9b1ac2000074.png\" alt=\"57a60033790f9b1ac2000074\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60033790f9b1ac2000077.png\" alt=\"57a60033790f9b1ac2000077\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60034790f9b1ac200007a.png\" alt=\"57a60034790f9b1ac200007a\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60034790f9b1ac200007d.jpg\" alt=\"57a60034790f9b1ac200007d\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60035790f9b6270000022.jpg\" alt=\"57a60035790f9b6270000022\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60034790f9b1ac2000080.jpg\" alt=\"57a60034790f9b1ac2000080\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60035790f9b53ff000024.png\" alt=\"57a60035790f9b53ff000024\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60035790f9b6270000025.jpg\" alt=\"57a60035790f9b6270000025\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60035790f9b1ac2000083.jpg\" alt=\"57a60035790f9b1ac2000083\">  </span><span style=\"font-size:12px;\"> <img width=\"90\" src=\"/content/esm/thks_web/www/content/post/image/57a60035790f9b53ff000027.jpg\" alt=\"57a60035790f9b53ff000027\">  </span>\r\n</br ><img src=\"/esm/thks_web/www/assets/DPS_jj_hrz_RGB.png\" width=\"90\">\r\n    \r\n</p>\r\n\r\n                </div>\r\n			\r\n				\r\n			</div>\r\n			<div class=\"row\" id=\"team\">\r\n				<div class=\"col-md-12 section-heading text-center to-animate\">\r\n					<h2>Team</h2>\r\n				</div>\r\n				<div class=\"col-md-12\">\r\n					<div class=\"row row-bottom-padded-lg\">\r\n						<img src=\"/esm/thks_web/www/content/web/images/map.jpg\" width=\"100%\">\r\n					</div>\r\n				</div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div id=\"fh5co-our-services\" style=\"background: #fff;\" data-section=\"services\">\r\n		<div class=\"container\">\r\n			<div class=\"row row-bottom-padded-sm\">\r\n				<div class=\"col-md-12 section-heading text-center\">\r\n					<h2 class=\"to-animate\">THKJR CORE VALUES</h2>\r\n					<div class=\"row\">\r\n				<div class=\"col-md-4\">\r\n					<div class=\"box to-animate\">\r\n						<img src=\"/esm/thks_web/www/content/web/images/1.jpg\" width=\"100%\"><br />โรงพยายาลได้ข้อมูลเพื่อใช้ในการพัฒนาการให้บริการ\r\n					</div>\r\n				</div>\r\n				<div class=\"col-md-4\">\r\n					<div class=\"box to-animate\">\r\n						<img src=\"/esm/thks_web/www/content/web/images/3.jpg\" width=\"100%\"><br />ทำให้สามารถติดตามการรักษาคนไข้ได้อย่างมีระบบ\r\n					</div>\r\n				</div>\r\n				<div class=\"col-md-4\">\r\n					<div class=\"box to-animate\">\r\n						<img src=\"/esm/thks_web/www/content/web/images/2.jpg\" width=\"100%\"><br />คนไข้รับการรักษาที่ได้ดีขึ้นและสามารถมีชีวิตที่ดีขึ้น\r\n					</div>\r\n					\r\n				</div>\r\n			</div>\r\n		</div>\r\n				</div>\r\n			</div>\r\n			\r\n	</div>\r\n	\r\n\r\n\r\n\r\n	<div id=\"fh5co-press\" style=\"background: #fff;\" data-section=\"news\">\r\n		<div class=\"container\">\r\n			<div class=\"row\">\r\n				<div class=\"col-md-12 section-heading text-center\">\r\n					<h2 class=\"single-animate animate-press-1\">News/Event</h2>\r\n					<div class=\"row\">\r\n						<div class=\"col-md-12 subtext single-animate animate-press-2\">\r\n							\r\n<% \r\n    matt = models[:attachment]\r\n    \r\n    \r\nfor p in posts \r\n\r\n    atts = matt.find(p.image)\r\n    atts_main = atts.collect{|i| i if i.title.index(\'main\')}.compact\r\n    default = \'/esm/thks_web/www/assets/thkjr.png\'\r\n    default = atts_main[0].path if atts_main.size>0\r\n%>\r\n    \r\n<div class=\"col-md-4\"><div class=\"boxcontent\"><%#atts_main.inspect %>\r\n   <a href=\"post?id=<%=p.id%>\"> <img src=\"<%=default%>\" width=\"100%\" height=\"220px\"  align=\"top\"><h4><%=p.title.html_safe  %> </h4></a><br />\r\n</div><div class=\"clear\"></div></div>\r\n\r\n<% end %>\r\n<div class=\"clear\"></div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</div>\r\n			\r\n\r\n			</div>\r\n		</div>\r\n	</div>\r\n		<div id=\"fh5co-pricing\" data-section=\"pricing\">\r\n		<div class=\"container\">\r\n			<div class=\"row\">\r\n				<div class=\"col-md-12 section-heading text-center\">\r\n					<h2 class=\"single-animate animate-pricing-1\">Contact Us</h2>\r\n				<p><h3>	ชมรมศัลยแพทย์ข้อสะโพกและข้อเข่าแห่งประเทศไทย<br />\r\n492/1 ถ.พระราม1 แขวงปทุมวัน<br />\r\nเขตปทุมวัน กมม. 10330 <br />\r\nโทร.02-253-5836 email.thkjoint(at)gmail.com<br /></h3></p>\r\n				</div>\r\n				\r\n			</div>\r\n		</div>\r\n	</div>\r\n\r\n	<footer id=\"footer\" role=\"contentinfo\">\r\n		<div class=\"container\">\r\n			<div class=\"row row-bottom-padded-sm\">\r\n				<div class=\"col-md-12\">\r\n					<p class=\"copyright text-center\">&copy; 2016 Power by E.S.M.Solution</p><center>\r\n					 <% unless @current_user %>\r\n			   \r\n			   <%=link_to \'Login\', \"../Post/index\" %>\r\n			       \r\n			  <% else %>    \r\n			  <%=@current_user.login%> \r\n			   <%=link_to \'Logout\', \"/user/logout?redirect_to=/www/Home/index\" %>\r\n			       <% end %>\r\n			   \r\n			       <% if @current_user %>\r\n                    | <a href=\"../Member/index\">Members</a>| <a href=\"../Post/index\">Post</a>\r\n            \r\n                    \r\n                    <% end %>\r\n                    </center>\r\n				</div>\r\n			</div>\r\n			\r\n		</div>\r\n	</footer>\r\n	\r\n	\r\n	<!-- For demo purposes Only ( You may delete this anytime :-) \r\n	<div id=\"colour-variations\">\r\n		<a class=\"option-toggle\"><i class=\"icon-gear\"></i></a>\r\n		<h3>Preset Colors</h3>\r\n		<ul>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"style\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"pink\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"blue\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"turquoise\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"orange\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"lightblue\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"brown\"></a></li>\r\n			<li><a href=\"javascript: void(0);\" data-theme=\"green\"></a></li>\r\n		</ul>\r\n	</div>-->\r\n	<!-- End demo purposes only -->\r\n\r\n	\r\n	<!-- jQuery -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/jquery.min.js\"></script>\r\n	<!-- jQuery Easing -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/jquery.easing.1.3.js\"></script>\r\n	<!-- Bootstrap -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/bootstrap.min.js\"></script>\r\n	<!-- Waypoints -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/jquery.waypoints.min.js\"></script>\r\n	<!-- Owl Carousel -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/owl.carousel.min.js\"></script>\r\n\r\n	<!-- For demo purposes only styleswitcher ( You may delete this anytime ) \r\n	<script src=\"js/jquery.style.switcher.js\"></script>\r\n	<script>\r\n	$(function(){\r\n		$(\'#colour-variations ul\').styleSwitcher({\r\n			defaultThemeId: \'theme-switch\',\r\n			hasPreview: false,\r\n			cookie: {\r\n	          	expires: 30,\r\n	          	isManagingLoad: true\r\n	      	}\r\n		});	\r\n		$(\'.option-toggle\').click(function() {\r\n			$(\'#colour-variations\').toggleClass(\'sleep\');\r\n		});\r\n	});\r\n	</script>-->\r\n	<!-- End demo purposes only -->\r\n\r\n	<!-- Main JS (Do not remove) -->\r\n	<script src=\"/esm/thks_web/www/content/web/js/main.js\"></script>\r\n	<style>\r\n\r\n	</style>\r\n	</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-01 03:30:17','2016-10-01 03:30:17','index','*'),(2582,'layout2',965,4,'<!DOCTYPE html>\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n    <meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1\" />\r\n    <meta name=\"description\" content=\"\" />\r\n    <meta name=\"author\" content=\"\" />\r\n      <!--[if IE]>\r\n        <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\">\r\n        <![endif]-->\r\n\r\n     <title>THKJR</title>\r\n   \r\n    \r\n    <!-- BOOTSTRAP CORE STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/bootstrap.css\" rel=\"stylesheet\" />\r\n      <!-- VEGAS SLIDESHOW STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/vegas/jquery.vegas.min.css\" rel=\"stylesheet\" />\r\n     <!-- FONTAWESOME STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/font-awesome.min.css\" rel=\"stylesheet\" />\r\n    <!-- CUSTOM STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/style.css\" rel=\"stylesheet\" />    \r\n    <link href=\"/esm/thks_web/www/assets/thsarabunnew.css\" rel=\"stylesheet\" />   \r\n      <%= include_header %>\r\n    <!-- GOOGLE FONT -->\r\n    \r\n     <!-- HTML5 shim and Respond.js IE8 support of HTML5 elements and media queries -->\r\n    <!--[if lt IE 9]>\r\n      <script src=\"https://oss.maxcdn.com/libs/html5shiv/3.7.0/html5shiv.js\"></script>\r\n      <script src=\"https://oss.maxcdn.com/libs/respond.js/1.3.0/respond.min.js\"></script>\r\n    <![endif]-->\r\n<style>\r\n.headline {width:100%; color:#fff; background:#fd9048; padding:5px;-moz-border-radius: 5px; border-radius: 5px;}\r\n.bbox{ width:150px; float:left; padding:10px; margin-right:20px}\r\n.ss{padding:0px;;margin-right:5px; width:180px; font-size:1em}\r\n.sm {font-size:0.8em}\r\ninput, button, select, textarea {color:#000;}\r\nlabel {    font-weight: normal;}\r\n.navbar-inverse {\r\n    background-color: rgb(18, 18, 18);}\r\n\r\n    .navbar-inverse .navbar-toggle .icon-bar {\r\n    background-color: #8c8c8c;}\r\n    \r\n  .footer {\r\n    text-align: right;\r\n    color: #8c8c8c;\r\n    background-color: #fff;}\r\n    .navbar-brand {\r\n \r\n    font-size: 14px;}\r\n    body {color: #3e3d3d; background: url(\"/esm/thks_web/www/assets/1.jpg\") no-repeat center center fixed; \r\n  -webkit-background-size: cover;\r\n  -moz-background-size: cover;\r\n  -o-background-size: cover;\r\n  background-size: cover; }\r\n    \r\n .navbar .nav > li > a:hover {\r\n  color: #ccc;}\r\n  \r\n    \r\n</style>\r\n</head>\r\n<body data-spy=\"scroll\" data-target=\"#menu\">\r\n<!--                             -->\r\n <!-- Button trigger modal -->\r\n\r\n<!--                             -->\r\n\r\n\r\n    <div class=\"navbar navbar-inverse navbar-fixed-top scrollclass\" id=\"menu\" >\r\n        <div class=\"container\">\r\n            <div class=\"navbar-header\" >\r\n                <button type=\"button\" class=\"navbar-toggle\" data-toggle=\"collapse\" data-target=\".navbar-collapse\">\r\n                    <span class=\"icon-bar\"></span>\r\n                    <span class=\"icon-bar\"></span>\r\n                    <span class=\"icon-bar\"></span>\r\n                </button>\r\n                <a href=\"index\" class=\"navbar-brand\" style=\"margin-left:10px\"><img src=\"/esm/thks_web/www/assets/logolong2.png\" alt=\"\" class=\"logoo\"  /></a>\r\n            </div>\r\n            <div class=\"navbar-collapse collapse\">\r\n                <ul class=\"nav navbar-nav navbar-right\">\r\n                    <li><a href=\"index\">HOME</a></li>\r\n                     <li><a href=\"about\">ABOUT US</a></li>\r\n                     <li><a href=\"register\">REGISTER</a></li>\r\n                     <li><a href=\"news\">NEWS/EVENT</a></li>\r\n                     <li><a href=\"contact\">CONTACT US</a></li>\r\n                \r\n                </ul>\r\n            </div>\r\n           \r\n        </div>\r\n    </div>\r\n    <!--NAVBAR SECTION END-->\r\n   <div id=\"home\" >\r\n   \r\n       <div class=\"container\">\r\n           <div class=\"row\">\r\n<!-- ใส -->\r\n           \r\n\r\n               <div class=\"col-lg-12	 \"><br /><br /><br /><div class=\"col-lg-12 text-center\" style=\"background-color:rgba(255, 255, 255, 1);-moz-border-radius: 5px;\r\nborder-radius: 5px; padding:10px;text-align:left\">\r\n                   <%= yield :content%>\r\n               \r\n                 </div>\r\n  <!-- ใส -->                  \r\n                    \r\n                    \r\n               </div>\r\n           </div>\r\n       </div>\r\n       \r\n   </div>\r\n   \r\n     <!--CONTACT SECTION END-->\r\n			   <div class=\"footer\">\r\n			   THAI HIP-KNEE REGISTRY STEERING GROUP Power by E.S.M.\r\n			    <% unless @current_user %>\r\n			   \r\n			   <%=link_to \'Login\', \"/user/login\" %>\r\n			       \r\n			  <% else %>    \r\n			  <%=@current_user.login%> \r\n			   <%=link_to \'Logout\', \"/user/logout?redirect_to=/www/Home/index\" %>\r\n			       <% end %>\r\n			   \r\n			       <% if @current_user %>\r\n                    | <a href=\"../Member/index\">Members</a>| <a href=\"../Post/index\">Post</a>\r\n            \r\n                    \r\n                    <% end %>\r\n			   </div>\r\n          \r\n			    \r\n <!-- JAVASCRIPT FILES PLACED AT THE BOTTOM TO REDUCE THE LOADING TIME  -->\r\n    <!-- CORE JQUERY \r\n    <script src=\"/esm/thks_web/www/assets/jquery-1.10.2.js\"></script> -->\r\n    <!-- BOOTSTRAP SCRIPTS  -->\r\n    <script src=\"/esm/thks_web/www/assets/bootstrap.js\"></script>\r\n     <!-- EASING SCROLL SCRIPTS PLUGIN  \r\n    <script src=\"/esm/thks_web/www/assets/vegas/jquery.vegas.min.js\"></script>-->\r\n    <!-- VEGAS SLIDESHOW SCRIPTS  >-->\r\n    <script src=\"/esm/thks_web/www/assets/jquery.easing.min.js\"></script\r\n    <!-- CUSTOM SCRIPTS  -->\r\n <script src=\"/esm/thks_web/www/assets/custom.js\"></script>\r\n</body>\r\n\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-01 03:42:24','2016-10-01 03:42:24','layout2',''),(2583,'index',1032,2,'<%\r\n\r\n models = get_model\r\n \r\n category_map = {}\r\n categories =  models[:product_category].all\r\n cat_map = {}\r\n categories.each do |i|\r\n     category_map[i.id] = []\r\n     cat_map[i.id] = i\r\n end\r\n category_map[nil] = []\r\n \r\n pmap = {}\r\n products = models[:product].all\r\n for i in products\r\n    pmap[i.id.to_s] = i\r\n end\r\n \r\n if request.post?\r\n    \r\n    \r\n    params[:ids].each_with_index do |i,index| \r\n        \r\n        p = pmap[i]\r\n        \r\n        p.update_attributes :name=>params[:name][index],:short_code=>params[:short_code][index], :code=>params[:code][index], :code_2=>params[:code_2][index],  :barcode=>params[:barcode][index], \r\n        :category_id=>params[:category_id][index], :price=>params[:price][index],:price_2=>params[:price_2][index], :reimbursable=>params[:reimbursable][index]\r\n        \r\n    end\r\n     \r\n     %>\r\n     <script>\r\n         window.location= \"index\";\r\n     </script>\r\n     <%\r\n     \r\n else\r\n \r\n \r\n \r\n\r\n \r\n for i in products\r\n  \r\n    category_map[i.category_id] << i     if  category_map[i.category_id] \r\n    \r\n end\r\n \r\n%>\r\n<%= form_for :product, :url=>\'index\' do |f| %>\r\n<table class=\"table\">\r\n<thead>\r\n    <tr>\r\n        <th>Category</th> <th>Code</th><th>Code-2</th>\r\n        <th>Name</th>\r\n         <th>Short</th>\r\n       \r\n        <th>Barcode</th>\r\n        <th>Price</th>\r\n        <th>Price 2</th>\r\n\r\n        <th>Reimbursable</th>\r\n        <th>Structure</th>\r\n        \r\n    </tr>\r\n</thead>\r\n    <tbody>\r\n    <% \r\n        \r\n        cats = categories.collect{|i| i.id} + [nil]\r\n        \r\n        for i in cats\r\n        \r\n        cat = cat_map[i]\r\n    %>\r\n    \r\n    <% for p in category_map[i].sort{|a,b| a.name<=>b.name} %>\r\n    <tr>\r\n    \r\n    <td><%=hidden_field_tag \"ids[]\", p.id %>\r\n        <%=select_tag \"category_id[]\", options_for_select(categories.collect{|i| [i.name,i.id]}, p.category_id),:include_blank=>true,:style=>\"width:120px\" %>\r\n        \r\n    </td>\r\n     <td>\r\n        <%=text_field_tag \"code[]\",p.code, :style=>\'width:70px\' %>\r\n    </td>   \r\n       <td>\r\n        <%=text_field_tag \"code_2[]\",p.code_2, :style=>\'width:70px\' %>\r\n    </td>  \r\n    <td>\r\n        <%=text_field_tag \"name[]\",p.name, :style=>\'width:270px\' %>\r\n    </td>    \r\n    \r\n    <td>\r\n        <%=text_field_tag \"short_code[]\",p.short_code, :style=>\'width:50px\' %>\r\n    </td>    \r\n    \r\n    \r\n    \r\n    <td>\r\n        <%=text_field_tag \"barcode[]\",p.barcode,:onkeypress=>\'javascript:key()\',:style=>\'width:100px\' %>\r\n    </td>    \r\n    \r\n    \r\n    <td>\r\n     \r\n        <%=text_field_tag \"price[]\",p.price, :style=>\'width:60px\' %>\r\n     \r\n    </td> \r\n    \r\n        <td>\r\n     \r\n        <%=text_field_tag \"price_2[]\",p.price_2, :style=>\'width:60px\' %>\r\n     \r\n    </td> \r\n    \r\n    \r\n    <td>\r\n        <%=text_field_tag \"reimbursable[]\",p.reimbursable, :style=>\'width:60px\' %>\r\n\r\n    </td> \r\n    <td align=\"center\">\r\n    \r\n       <%=link_to \'Edit\', \"../Product/edit?id=\\\\#{p.id}&return=../Product/index\", :class=>\'btn btn-info\'%>\r\n\r\n      <%\r\n        ps = models[:payroll_structure].where(:product_id=>p.id).first\r\n        if ps\r\n      %>\r\n        <%=link_to \'Show\', \"../PayrollStructure/edit?id=\\\\#{ps.id}&return=../Product/index\", :class=>\'btn btn-info\'%>\r\n        <% else %>\r\n        <%=link_to \'+\', \"../PayrollStructure/create?record[product_id]=\\\\#{p.id}&return=../Product/index\" %>\r\n        \r\n        <% end %>\r\n    </td>\r\n\r\n    \r\n    \r\n        \r\n    </tr>\r\n    <% end %>\r\n    <% end %>\r\n    </tbody>\r\n</table>\r\n<%= f.submit \'Update\' %> |\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n\r\n\r\n<% end %>\r\n<% end %>\r\n\r\n<script>\r\n    function key(){\r\n     \r\n    }\r\n</script>',NULL,NULL,NULL,'2016-10-01 04:03:38','2016-10-01 04:03:38','index',''),(2584,'index_list',1032,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'.\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n',NULL,NULL,NULL,'2016-10-01 04:03:49','2016-10-01 04:03:49','index_list',''),(2585,'init',1033,4,'<%\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n  \r\n  @next_id= \'000000\'\r\n\r\n\r\n\r\n%>\r\n\r\n',NULL,NULL,NULL,'2016-10-01 04:47:46','2016-10-01 04:47:46','init',''),(2587,'print_partial',1033,3,'<style>\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n\r\n\r\n\r\n    @media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n</style>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n  \r\n    record = models[this.document_name.to_sym].find(pm.module_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    appm = @module_model.find pm.parent_id\r\n    \r\n    if appm and record.provider_id == nil\r\n        app = models[:appointment].find appm.module_id\r\n        if app \r\n            keys = {}\r\n            \r\n            # keys[:provider_id] = app[\'operative_provider\'] if record.provider_id==nil and app[\'operative_provider\'] \r\n            # keys[:finance] = app[\'finance\'] if record.financial==\'\' and app[\'finance\'] \r\n            # keys[:type_of_patient] = app[\'type_of_patient\'] if record.type_of_patient==nil and app[\'type_of_patient\'] \r\n            \r\n            \r\n            # record.update_attributes keys\r\n            \r\n        end\r\n        \r\n    end\r\n    \r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\n    \r\n    if record.provider_id\r\n        @provider = models[:provider].find record.provider_id\r\n        \r\n    end\r\n        \r\n    \r\nend %>\r\n\r\n\r\n<% times = 1\r\n\r\n   times = params[:times] if params[:times]\r\n    \r\n    \r\n   times.times do |t| \r\n\r\n%>\r\n<div class=\"wrapper\" style=\"border-bottom:<%=\'1\' if t==10%>px dotted #666\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" />\r\n</div>\r\n\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n\r\n</div>\r\n\r\n<%\r\n   section = \'ผู้ป่วยในเวลา\'\r\n   section = \'ผู้ป่วยนอกเวลา\' if @record.billing_type==\'2\'\r\n   \r\n%><br/>\r\n<center><b id=\"report-title\"><h4>ใบคิดค่าใช้จ่ายห้องส่องกล้อง Surgical Endoscopy \r\n    <%=section%>\r\n</h4></b></center>\r\n\r\n<br/>\r\n<div id=\"page\" style=\"padding-top:10px\">\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\"  >\r\n<tr >\r\n<td width=\"60%\"> \r\n\r\n    <p style=\"font-size:1.2em\">Hospital No :&nbsp;<v><%=patient.hn%></v> \r\n    Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v>\r\n        \r\n      \r\n    </p>\r\n    <p style=\"font-size:1.2em\">\r\n        \r\n          อายุ :&nbsp;<v><%= year%> \r\n        ปี <%=month%>\r\n        เดือน <%= day%> วัน\r\n        </v>\r\n    </p>\r\n    \r\n    <p style=\"font-size:1.2em\">\r\n    Patient : <v style=\"color:red\"><%= @record.type_of_patient %></v>\r\n    \r\n   \r\n    </p>\r\n    \r\n    <p style=\"font-size:1.2em\">\r\n       สิทธิ์การรักษา :\r\n        <v style=\"color:red\"><%= @record.financial %></v>\r\n   \r\n    </p>\r\n    \r\n      \r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p style=\"font-size:1.2em\">\r\n    Endoscopist : &nbsp; \r\n    <v><b><%= @provider.name if @provider %></b></v>\r\n  \r\n    </p>\r\n  <p style=\"font-size:1.2em\">\r\n  \r\n  <%\r\n    months = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n    month = months[pm.date.month-1]\r\n    year = pm.date.year+543\r\n    \r\n    date_th = \"\\\\#{pm.date.day} \\\\#{month} \\\\#{year}\"\r\n    \r\n  %>\r\n  \r\n  Date :&nbsp;<v><%=date_th%></v></p>\r\n	\r\n	  \r\n	    \r\n	      <%  if @provider %>\r\n	       <p style=\"font-size:1.2em\">\r\n	       รหัสแพทย์ :\r\n    <v><%= @provider.ref_number %></v>\r\n    \r\n	    </p>\r\n    <% end %>\r\n    \r\n    <p style=\"font-size:1.2em\">\r\n	       เลขอ้างอิง :\r\n    <v></v>\r\n    \r\n	    </p>\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n<%\r\n\r\n  models = get_model\r\n \r\n  items = models[:billing_item].find record.items\r\n  products = models[:product].find items.collect{|i| i.product_id}\r\n  \r\n  pmap = {}\r\n  \r\n  categories = models[:product_category].find products.collect{|i| i.category_id}.uniq\r\n  \r\n  cat_map = {}\r\n   \r\n  \r\n  for i in products\r\n    pmap[i.id] = i\r\n  end\r\n  \r\n  for i in items\r\n    p = pmap[i.product_id]\r\n    \r\n    cat_map[p.category_id] = [] unless  cat_map[p.category_id] \r\n    cat_map[p.category_id]  << i\r\n  \r\n  end\r\n    \r\n \r\n%>\r\n\r\n\r\n<table class=\"table\" width=\"100%\">\r\n<thead>\r\n    <tr>\r\n        <th>No.</th>\r\n        <th>รหัส</th>\r\n        <th style=\"\">รายการ</th>\r\n   \r\n        <th style=\"text-align:right\">ราคา</th>\r\n        \r\n        <th>จำนวน</th>\r\n        <th style=\"text-align:right\">รวม</th>\r\n        <th></th>\r\n    </tr>\r\n</thead>\r\n<tbody>\r\n\r\n<% \r\ntotal = 0\r\ncategories.each do |c| \r\n    \r\n    qshow = true\r\n    \r\n    qshow = false if c.has_one ==\'true\' \r\n\r\n    items = cat_map[c.id]\r\n%>\r\n<tr>\r\n    <th colspan=\"6\" style=\"text-align:left\">รายการ<%=c.name%></th>\r\n</tr>\r\n<%\r\n\r\nitems.each_with_index do |i,index|\r\n    p = pmap[i.product_id]\r\n    \r\n    \r\n     price = p.price\r\n     \r\n    if record.billing_type == \'2\' and p.price_2 and p.price_2>0\r\n        price = p.price_2     \r\n    end\r\n     \r\n    total += price*i.quantity if price and i.quantity \r\n\r\n    %>\r\n<tr>\r\n<td>\r\n    <%= index+1%>.\r\n</td>    \r\n<td  style=\"text-size:1.9em\">\r\n<v>\r\n<%\r\n\r\n    if @record.billing_type == \'2\' and @record.type_of_patient == \'IPD\' and p.code.index(\'SU\')\r\n       \r\n    #   p.code = \"IS\\\\#{p.code[2..-1]}\"\r\n    p.code = p.code_2 if p.code_2 and p.code_2!=\'\'\r\n        \r\n    end\r\n\r\n%>\r\n<%= p.code%>     <%= \"<span class=\'alert-danger\'>#\\\\#{i.note}</span>\".html_safe if p.required_note==\"true\" %>\r\n\r\n</v>\r\n    \r\n    \r\n</td>\r\n<td>\r\n    <%= p.name %>\r\n</td>\r\n\r\n<td align=\"right\" style=\"text-align:right\">\r\n    <%=fn price %>\r\n</td>\r\n\r\n<td align=\"right\" style=\"text-align:center\">\r\n    <%= i.quantity if qshow %>\r\n</td>\r\n\r\n<td align=\"right\" style=\"text-align:right\">\r\n    <%=fn i.quantity*price  %>\r\n</td>\r\n\r\n<td>\r\n    บาท\r\n</td>\r\n    \r\n</tr>\r\n<% end%>\r\n<tr>\r\n     <td colspan=\"7\">\r\n        &nbsp;\r\n    </td>\r\n</tr>\r\n<% end%>\r\n\r\n<tr style=\"font-size:1.5em\">\r\n    <td colspan=\"4\">&nbsp;</td>\r\n    <td >\r\n        รวม\r\n    </td>\r\n    <td >\r\n        <v><%=fn total%></v> \r\n    </td>\r\n    <td>\r\n                บาท\r\n    </td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n<% end %>\r\n\r\n<script>\r\n    <%=\'window.print()\' if params[:times] %>\r\n</script>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-10-01 07:01:46','2016-10-01 07:01:46','print_partial',''),(2588,'display',1033,3,'<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n\r\n <div style=\"padding:5px; margin-left:auto; margin-right:auto\" >\r\n\r\nRef : <%= @patient_module.ref_number %> \r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n<p style=\"margin-left:auto; margin-right:auto; font-weight:bold\">HN : <%= @patient.hn %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Name : <%= @patient.first_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Surname : <%= @patient.last_name %></p>\r\n<hr /><br />\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%= render :inline=>this.print_partial %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>',NULL,NULL,NULL,'2016-10-01 07:02:31','2016-10-01 07:02:31','display',''),(2589,'show',1033,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;\">\r\n\r\n\r\n\r\n<%= this.display.html_safe %>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> |\r\n<%\r\n  begin\r\n   inventory =  @current_project.get_setting \'inventory\'\r\n   inven = @context.get_project inventory\r\n   if inven\r\n   order = inven.get_model[:order].where(:ref_id=>params[:id]).first\r\n   unless order\r\n%>\r\n<%=link_to \'Inventory : Check Out\',\"commit?id=\\\\#{params[:id]}&inventory=\\\\#{inventory}\",:class=>\'btn btn-success\', :confirm=>\'Are you sure?\' %> |\r\n<% \r\nelse %>\r\n<%=link_to \'Inventory : Order\',\"../../\\\\#{inven.name}/Order/show?id=\\\\#{order.id}\",:target=>\'_blank\' %> |\r\n<% end%><% end%>\r\n<%\r\nrescue =>e\r\n%>\r\nError <%= e %>\r\n<%\r\nend\r\n%>\r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-10-01 07:05:17','2016-10-01 07:05:17','show',''),(2590,'print',1033,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<%=include_header%>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\n\r\n</style>\r\n<body>\r\n<%  params[:times] = 1%>\r\n<%= this.print_partial.html_safe %>\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-10-01 07:09:24','2016-10-01 07:09:24','print',''),(2591,'show',1036,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%\r\n    @record = params[:record]\r\n%>\r\n<%= link_to \'Payroll Calculation\'.html_safe, \"payroll?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini btn-success\' if  @record.payroll_check != \'true\' %>&nbsp;\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' if (Time.now - @record.created_at)/86400<30  %>&nbsp;\r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-10-01 07:31:23','2016-10-01 07:31:23','show',''),(2592,'edit',1038,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<% if params[:return] %>\r\nwindow.location = \"<%=\"\\\\#{url_for(params[:return])}\"%>\"\r\n\r\n<% else %>\r\nwindow.location = \"show?id=<%=record.id%>\"\r\n<% end %>\r\n    \r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%= hidden_field_tag \'return\', params[:return] %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-10-01 07:49:23','2016-10-01 07:49:23','edit',''),(2593,'create',1038,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  if params[\'record\'][\"product_id\"]\r\n\r\n     record.product_id =  params[\'record\'][\"product_id\"]\r\n  end\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-10-01 07:55:33','2016-10-01 07:55:33','create',''),(2596,'display',1036,3,'\r\n<%\r\n   model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:record] = record\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>',NULL,NULL,NULL,'2016-10-01 13:39:21','2016-10-01 13:39:21','display',''),(2597,'mypayroll',1036,2,'<%\r\n    \r\n    models = get_model\r\n    \r\n    provider = models[:provider].where(:login=>@current_user.login).first\r\n    \r\n    if provider \r\n    items = models[:attendance_payroll].where(:provider=>provider.id).all.sort {|a,b| a.date<=>b.date}\r\n    \r\n   \r\n%>\r\n<div style=\"row-fluid\">\r\n<div style=\"span6\" style=\"width:500px\">\r\n\r\n\r\n<h1>รายงานค่าตอบแทนนอกเวลาของ  \r\n<%= provider.name%>\r\n    \r\n</h1>\r\n\r\n<table class=\"table hide \" width=\'60%\'>\r\n    <thead>\r\n        <tr><th>Date</th><th>\r\n        ค่าตอบแทน\r\n        OPD\r\n            \r\n        </th>\r\n            <th>\r\n        ค่าตอบแทน\r\n           IPD \r\n        </th>\r\n             <th>\r\n        รวม\r\n        </th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <% \r\n            sum = 0\r\n            sum2 = 0 \r\n            month = nil\r\n        for i in items \r\n        \r\n        \r\n            if i.date.month != month and month !=nil\r\n            %>\r\n            <tr><th><%=thmonth month%> รวม</th> <th><%=fn sum%></th><th><%=fn sum2%></th><th><%=fn sum+sum2%></th></tr>\r\n            <%\r\n                month = i.date.month\r\n                sum = 0 \r\n                sum2 = 0\r\n            end\r\n            month = i.date.month if month == nil\r\n            \r\n            sum+= i.amount.to_i\r\n            sum2+= i.amount_2.to_i\r\n            \r\n            \r\n        %>\r\n        <tr>\r\n            <td><%=i.date.strftime(\'%d-%m-%Y\')%></td><td><%=fn i.amount%></td><td><%=fn i.amount_2%></td><td><%=fn (i.amount.to_i + i.amount_2.to_i)%></td>\r\n        </tr>\r\n        <% end %>\r\n            <tr><th><%=thmonth month%> รวม </th> <th><%=fn sum%></th><th><%=fn sum2%></th><th><%=fn sum+sum2%></th></tr>\r\n        \r\n        \r\n    </tbody>\r\n    \r\n</table>\r\n<%\r\n    ymap = {}\r\n    now = Time.now.strftime(\"%Y-%m\")\r\n    show = false\r\n    last = nil\r\n    \r\n    for i in items\r\n        year = i.date.year\r\n        month = i.date.month\r\n        ymap[year] = {} unless ymap[year]\r\n        ymap[year][month] = [] unless ymap[year][month]\r\n        ymap[year][month] << i \r\n        last = \"\\\\#{year}-\\\\#{format(\'%02d\',month)}\"\r\n        \r\n    end\r\n\r\n%>\r\n<%\r\n#  acc-in\r\nshow = false\r\nfor y in ymap.keys.sort.reverse \r\n    yitems = []\r\n    ydata = ymap[y]\r\n%>\r\n<h3><%=y%></h3>\r\n<div id=\"accordion<%=y%>\" class=\"accordion\">\r\n\r\n						\r\n						\r\n<% for m in ydata.keys.sort{|a,b| a.to_i<=>b.to_i}\r\n   k = \"\\\\#{y}-\\\\#{m}\"\r\n   k2 = \"\\\\#{y}-\\\\#{format(\'%02d\',m)}\"\r\n   show = true if k2==last\r\n   items = ymap[y][m]\r\n   yitems += items\r\n%>\r\n\r\n	<div class=\"accordion-group\">\r\n		<div class=\"accordion-heading\">\r\n			<a href=\"#<%=k%>\" data-parent=\"#accordion<%=y%>\" data-toggle=\"collapse\" class=\"accordion-toggle <%=\'acc-in\' if show %>\">\r\n			     <%=thmonth m.to_i%> - <%=y%>\r\n			</a>\r\n		\r\n		</div>\r\n		<div class=\"accordion-body collapse <%=\'in\' if show %>\" id=\"<%=k%>\">\r\n			<div class=\"accordion-inner\">\r\n            \r\n            <table class=\"table \" width=\'60%\'>\r\n    <thead>\r\n        <tr><th>Date</th><th>\r\n        ค่าตอบแทน\r\n        OPD\r\n            \r\n        </th>\r\n            <th>\r\n        ค่าตอบแทน\r\n           IPD \r\n        </th>\r\n        <th>\r\n        รวม\r\n        </th>\r\n        <th>\r\n        รับ OPD\r\n        </th>\r\n        <th>\r\n        รับ IPD\r\n        </th>\r\n        <th>\r\n        รวมรับ\r\n        </th>\r\n        </tr>\r\n    </thead>\r\n    	<%\r\n			    show = false\r\n			%>\r\n    <tbody>\r\n        <% \r\n            sum = 0\r\n            sum2 = 0 \r\n            month = nil\r\n            percent = 0.95\r\n            percent = 0.80 if true or provider.provider_type==\'1\'\r\n        for i in items \r\n        \r\n        \r\n            if i.date.month != month and month !=nil\r\n            %>\r\n            <tr><th><%=thmonth month%> รวม</th> <th><%=fn sum%></th><th><%=fn sum2%></th><th><%=fn sum+sum2%></th><th><%=fn (sum)*percent%></th><th><%=fn (sum2)*percent%></th><th><%=fn (sum+sum2)*percent%></th></tr>\r\n            <%\r\n                month = i.date.month\r\n                sum = 0 \r\n                sum2 = 0\r\n            end\r\n            month = i.date.month if month == nil\r\n            \r\n            sum+= i.amount.to_i\r\n            sum2+= i.amount_2.to_i\r\n            \r\n            \r\n        %>\r\n        <tr>\r\n            <td><%=i.date.strftime(\'%d-%m-%Y\')%></td><td><%=fn i.amount%></td><td><%=fn i.amount_2%></td><td><%=fn (i.amount.to_i + i.amount_2.to_i)%></td><td><%=fn (i.amount.to_i)*percent%></td><td><%=fn (i.amount_2.to_i)*percent%></td><td><%=fn (i.amount.to_i + i.amount_2.to_i)*percent%></td>\r\n        </tr>\r\n        <% end %>\r\n            <tr><th><%=thmonth month%> รวม </th> <th><%=fn sum%></th><th><%=fn sum2%></th><th><%=fn sum+sum2%></th> <th><%=fn (sum)*percent%></th><th><%=fn (sum2)*percent%></th><th><%=fn (sum+sum2)*percent%></th></tr>\r\n        \r\n        \r\n        \r\n    </tbody>\r\n    \r\n</table>\r\n            \r\n\r\n			</div>\r\n		</div>\r\n	</div>\r\n<% end %>\r\n    <%\r\n        k = \"\\\\#{y}\"\r\n    %>\r\n	<div class=\"accordion-group\">\r\n		<div class=\"accordion-heading\">\r\n			<a href=\"#<%=k%>\" data-parent=\"#accordion<%=y%>\" data-toggle=\"collapse\" class=\"accordion-toggle <%=\'acc-in\' if show %>\">\r\n			      Summary - <%=y%>\r\n			</a>\r\n		\r\n		</div>\r\n		<div class=\"accordion-body collapse <%=\'in\' if show %>\" id=\"<%=k%>\">\r\n			<div class=\"accordion-inner\">\r\n			\r\n			\r\n			            <table class=\"table \" width=\'60%\'>\r\n    <thead>\r\n        <tr><th>Date</th><th>\r\n        ค่าตอบแทน\r\n        OPD\r\n            \r\n        </th>\r\n            <th>\r\n        ค่าตอบแทน\r\n           IPD \r\n        </th>\r\n             <th>\r\n        รวม\r\n        </th>      <th>\r\n        รับ\r\n        </th>\r\n        </tr>\r\n    </thead>\r\n    	<%\r\n			    show = false\r\n			%>\r\n    <tbody>\r\n        <% \r\n            sum = 0\r\n            sum2 = 0 \r\n            month = nil\r\n            percent = 0.95\r\n            percent = 0.80 if provider.provider_type==\'1\'\r\n            tsum = 0 \r\n            tsum2 = 0 \r\n        for i in yitems \r\n        \r\n        \r\n            if i.date.month != month and month !=nil\r\n            %>\r\n            <tr><td><%=thmonth month%> รวม</td> <td><%=fn sum%></td><td><%=fn sum2%></th><td><%=fn sum+sum2%></td><td><%=fn (sum+sum2)*percent%></td></tr>\r\n            <%\r\n                month = i.date.month\r\n                sum = 0 \r\n                sum2 = 0\r\n            end\r\n            month = i.date.month if month == nil\r\n            \r\n            sum+= i.amount.to_i\r\n            sum2+= i.amount_2.to_i\r\n            tsum+= i.amount.to_i\r\n            tsum2+= i.amount_2.to_i\r\n            \r\n        %>\r\n        <% end %>\r\n            <tr><td><%=thmonth month%> รวม</td> <td><%=fn sum%></td><td><%=fn sum2%></th><td><%=fn sum+sum2%></td><td><%=fn (sum+sum2)*percent%></td></tr>\r\n\r\n        \r\n        <tr><td> รวม</td> <td><%=fn tsum%></td><td><%=fn tsum2%></th><td><%=fn tsum+tsum2%></td><td><%=fn (tsum+tsum2)*percent%></td></tr>\r\n\r\n\r\n        \r\n    </tbody>\r\n    \r\n</table>\r\n			\r\n			\r\n			\r\n			</div>\r\n		</div>\r\n	</div>\r\n    \r\n    \r\n</div>\r\n\r\n<% end %>    \r\n    \r\n    \r\n</div>\r\n</div>\r\n\r\n\r\n<div style=\"row-fluid\">\r\n<%=link_to \'Back to Home\', \"../Home/index\" %>\r\n</div>\r\n\r\n\r\n<%  else %>\r\n<h1 class=\"alert alert-danger\">There is no provider which associate to your login name.</h1>\r\n<% end %>',NULL,NULL,NULL,'2016-10-01 16:45:08','2016-10-01 16:45:08','mypayroll',''),(2598,'context_menu',1036,4,'',NULL,NULL,NULL,'2016-10-01 16:50:02','2016-10-01 16:50:02','context_menu','');
INSERT INTO `esm_operations` VALUES (2599,'print',1042,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    \r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:consignment].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<script src=\"/signature/jquery.signaturepad.min.js\"></script>\r\n<%= javascript_include_tag \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\nvalue {color:#06F}\r\n#page {border:solid 1px; width:960px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; }\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n   \r\n    color:#666; font-weight:bold;\r\n}\r\n\r\nvalue.sign{display:inline-block;width:300px;border-bottom:1px solid gray}\r\n\r\n</style>\r\n<body>\r\n<br />\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' height=\'70px\' /></div></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"margin-left:20px; float:left; \">Consignment\r\n    <p>Hospital No :&nbsp;<value><%=patient.hn%></value> Name : <value><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></value> (Age :&nbsp;<value><%= year%> Year <%=month%> Month <%= day%> Day </value>)</h3>\r\n</div><hr />\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p>\r\n<!-- show patient -->\r\n\r\n<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:98%;padding:0px\">\r\n\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n	\r\n<div id=\"diagnosis\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.1em 0;float:left;width:700px; font-size:16px\">\r\n<span class=\"\"><label>Diagnosis : </label></span>	\r\n\r\n<value><%=render_value \'diagnosis\'%></value>\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n	\r\n<div id=\"operation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.1em 0;float:left;width:700px; font-size:16px\">\r\n<span class=\"\"><label>Operation : </label></span>	\r\n\r\n<value><%=render_value \'operation\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"161-F1625050926\" class=\" \" style=\"clear:both;line-height:1.5em\">\r\n		\r\n		<style>\r\nlabel{margin-top:5px;margin-bottom:5px}\r\n</style>\r\nข้าพเจ้าขอแสดงความยินยอมโดยความสมัครใจ ให้คณะแพทย์และบุคลากรทีมสุขภาพของโรง พยาบาลจุฬาลงกรณ์ ที่ได้รับมอบหมายให้มีส่วนร่วมในการดูแล ตรวจ วินิจฉัย และให้การรักษา ข้าพเจ้า ได้ดําเนินการตรวจ วินิจฉัย / รักษา โดยการใช้ยา หรือ เคมีบําบัด หรือ รังสีรักษา หรือ กายภาพบําบัด / รักษาโดยการผ่าตัดเล็กน้อย หรือ ผ่าตัดใหญ่ / ใช้ยาระงับความรู้สึกเฉพาะที่ หรือ ยา ชาฉีดเข้าสันหลัง หรือ การดมยาสลบ \r\n<br/>\r\n<br/>\r\nข้าพเจ้า ได้รับทราบรายละเอียดเกี่ยวกับแผนการตรวจ วินิจฉัยและการรักษาพยาบาลข้างต้น รวมถึง ความเสี่ยง ผลข้างเคียง และ/หรือ ผลที่อาจเกิดขึ้นภายหลังอีกทั้งทางเลือกอื่น ๆ ที่อาจเป็นไปได้อย่าง ชัดเจน จนเป็นที่กระจ่างชัดสําหรับข้าพเจ้าแล้ว และข้าพเจ้าตระหนักดีว่าคณะแพทย์และบุคลากร ทีม สุขภาพ พยาบาล ไม่สามารถรับประกันถึงผลความสําเร็จของการรักษาพยาบาลดังกล่าวได้ \r\n<br/>\r\n<br/>\r\nข้าพเจ้าขอแสดงความยินยอมโดยความสมัครใจให้คณะแพทย์และบุคลากรทีมสุขภาพดังกล่าวข้างต้น สามารถกระทําการอื่น ๆ ด้วยเหตุผล แสดงถึงความจําเป็นในการกระทําดังกล่าว อาทิเช่น การดม ยาสลบ การใช้ยาระงับความรู้สึก การให้เลือด และ / หรือ ผลิตภัณฑ์ของเลือด การตรวจวินิจฉัยทาง รังสีวิทยา การตัดชิ้นเนื้อ หรือส่วนของอวัยวะ และการตรวจรักษาหรืผ่าตัดเพิ่มเติม อย่างทันทีทันใด ข้าพเจ้ายินยอมให้แพทย์และบุคลากรทีมสุขภาพดําเนินการได้ หากเป็นการคํานึงถึงชีวิตและประโยชน์ ของข้าพเจ้าเป็นสําคัญ\r\n<br/>\r\n<br/>\r\nข้าพเจ้าทราบดีว่า โรงพยาบาลจุฬาลงกรณ์เป็นสถาบันฝึกอบรมแพทย์และพยาบาล ย่อมจะมีบุคลากร ทีมสุขภาพ ประกอบด้วย แพทย์ประจําบ้าน แพทย์ประจําบ้านต่อยอด นิสิตแพทย์ นักศึกษาพยาบาล และบุคลากรอื่น ๆ ซึ่งอาจจะเข้ามามีส่วนร่วมดูแล ตรวจ วินิจฉัยและรักษา\r\n<br/>\r\n<br/>\r\nทั้งนี้คณะแพทย์หรือบุคลากรทีมสุขภาพ ได้แจ้งค่าใช้จ่ายโดยประมาณแล้ว แต่หากมีภาวะแทรกซ้อน หรือใช้อุปกรณ์พิเศษเพิ่มเติม ค่าใช้จ่ายจะเพิ่มขึ้น ซึ่งจะต้องแจ้งข้าพเจ้าหรือญาติให้ทราบด้วย\r\n<br/>\r\n<br/>\r\nณ ที่นี้ข้าพเจ้าขอแสดงความ\r\n<br/>\r\n<br/>\r\n	</div>\r\n	\r\n\r\n\r\n	\r\n<div id=\"agreement\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.1em 0;float:left;width:900px\">\r\n<span class=\"\"><label></label></span>	\r\n\r\n<value><%=render_value \'agreement\' %></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"161-F5575601156\" class=\"clear\" >\r\n		\r\n		เพื่อรับการรักษาโดยความสมัครใจไว้ ณ ที่นี้\r\n	</div>\r\n	\r\n<div class=\"clear\"></div>\r\n\r\n<table width=\"940\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tr><td width=\"400\"><div id=\"patient_sign\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:350px; \">\r\n<span class=\"\"><label>ลงชื่อผู้ป่วย : </label></span>	\r\n\r\n<value class=\"sign\"><%=render_value \'patient_sign\' %></value>\r\n</div>\r\n<div id=\"patient_name\" class=\"  portlet \" style=\"margin: 0 0.5em 0 .5em 0;float:left;width:295px;\">\r\n<span class=\"\"><label>ชื่อผู้ป่วย : </label></span>	\r\n\r\n<value><%=render_value \'patient_name\'%></value>\r\n</div>\r\n	\r\n<div id=\"patient_sign_date\" class=\"  portlet \" style=\"width:150px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ลงวันที่ : </label></span>	\r\n\r\n<value><%=render_value \'patient_sign_date\'%></value>\r\n	\r\n</div></td>\r\n<td  width=\"400\">\r\n<div id=\"witness_1\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:350px;\">\r\n<span class=\"\"><label>ลงชื่อพยาน : </label></span>	\r\n\r\n<value  class=\"sign\"><%=render_value \'witness_1\'%></value>	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"witness_name\" class=\"  portlet \" style=\"width:295px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ชื่อพยาน : </label></span>	\r\n<value><%=render_value \'witness_name\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"witness_sign_date\" class=\"  portlet \" style=\"width:150px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ลงวันที่ : </label></span>	\r\n\r\n<value><%=render_value \'witness_sign_date\'%></value>	\r\n	\r\n\r\n</div>\r\n\r\n</td>\r\n</tr><tr>\r\n<td  width=\"400\">\r\n<div id=\"physician_sign\" class=\"  portlet \" style=\"width:705px;margin: 0 0.5em 0.5em 0;float:left;width:350px\">\r\n<span class=\"\"><label>ลงชื่อแพทย์ ผู้ให้ข้อมูล : </label></span>	\r\n\r\n<value  class=\"sign\" ><%=render_value \'physician_sign\'%></value>	\r\n	\r\n\r\n</div>\r\n\r\n<div id=\"physician_name\" class=\"  portlet \" style=\"width:295px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ชื่อแพทย์ผู้ให้ข้อมูล : </label></span>	\r\n<value><%=render_value \'physician_name\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"physician_sign_date\" class=\"  portlet \" style=\"width:150px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ลงวันที่ : </label></span>	\r\n\r\n<value><%=render_value \'physician_sign_date\'%></value>	\r\n\r\n</div>\r\n</td>\r\n<td  width=\"400\">\r\n<div id=\"assistant_sign\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:350px\">\r\n<span class=\"\"><label>ลงชื่อวิสัญญีแพทย์ : </label></span>	\r\n\r\n<value  class=\"sign\"><%=render_value \'assistant_sign\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"assistant_name\" class=\"  portlet \" style=\"width:295px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ชื่อวิสัญญีแพทย์ : </label></span>	\r\n<value><%=render_value \'assistant_name\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"assistant_sign_date\" class=\"  portlet \" style=\"width:150px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ลงวันที่ : </label></span>	\r\n\r\n<value><%=render_value \'assistant_sign_date\'%></value>	\r\n\r\n</div>\r\n</td>\r\n</tr>\r\n\r\n</table>	\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n	\r\n\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n	\r\n\r\n\r\n\r\n	\r\n	<div id=\"161-F4368260082\" class=\" \" style=\"clear:both;line-height:1.5em\">\r\n		<br/>\r\n		<hr/>\r\nในกรณีที่ผู้ป่วยอยู่ในภาวะที่มิอาจให้ความยินยอมได้ตามปกติ แพทย์ได้อธบายข้อความดังกล่าวข้าง ต้นให้แก่ผู้แทนโดยชอบธรรมของผู้ป่วยที่จะตัดสินใจแทนผู้ป่วยได้รับทราบแล้วและขอแสดงความ\r\n	</div>\r\n	\r\n\r\n<br />\r\n	\r\n<div id=\"representor_agreement\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.1em 0;float:left;width:350px;\">\r\n<span class=\"\"><label></label></span>	\r\n\r\n<value><%=render_value \'representor_agreement\'%></value>		\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"161-F0624190508\" class=\" \" style=\"clear:both;\">\r\n		\r\n		เพื่อรับการตรวจรักษาดังกล่าวไว้​ณ​ที่นี้\r\n	<br/>\r\n<br/>\r\n	</div>\r\n	\r\n\r\n\r\n	\r\n<div id=\"representer_sign\" class=\"  portlet \" style=\"width:705px;margin: 0 0.5em 0.5em 0;float:left;width:350px\">\r\n<span class=\"\"><label>ลงชื่อผู้แทนโดยชอบธรรม : </label></span>	\r\n\r\n\r\n<value  class=\"sign\"><%=render_value \'representer_sign\'%></value>	\r\n	\r\n</div></div>\r\n\r\n\r\n	\r\n	<div id=\"161-F8365073067\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"representer_name\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;\">\r\n<span class=\"\"><label>ชื่อผู้แทนโดยชอบธรรม : </label></span>	\r\n<value><%=render_value \'representer_name\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"representer_relation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;\">\r\n<span class=\"\"><label>เกี่ยวข้องเป็น :</label></span>	\r\n<value><%=render_value \'representer_relation\'%></value>	\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n	\r\n<div id=\"representer_sign_date\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>ลงวันที่ : </label></span>	\r\n\r\n<value><%=render_value \'representer_sign_date\'%></value>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n\r\n\r\n\r\n<div class=\"clear\">\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</div>\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-10-02 13:57:57','2016-10-02 13:57:57','print',''),(2600,'print',1043,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:pre_scope].find(colono_id)\r\n    \r\n    parent = @module_model.find(pm.parent_id)\r\n    app = models[:appointment].find(parent.module_id)\r\n    procedure = models[:procedure].find(app.procedure)\r\n    \r\n    diagnosis=\'-\'\r\n    colo_name = @current_project.name+\'#\'+ \'colonoscopy\' \r\n    colo_module = @module_model.first(:parent_id=>parent.id,:module_name=>colo_name)\r\n    if colo_module \r\n        colo = models[:colonoscopy].find(colo_module.module_id)\r\n        @record = colo\r\n        @document = get_document \'colonoscopy\'\r\n        indication=render_value(\'indication\') \r\n        previous_opreation = render_value(\'previous_opreation\')\r\n    end\r\n    \r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n	-webkit-border-radius: 5px; /* Safari prototype */\r\n	-moz-border-radius: 5px; /* Gecko browsers */\r\n	border-radius: 5px; /* Everything else - limited support at the moment */	\r\n	margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n		width:150px;\r\n}\r\nlabel{\r\n	color:#666; font-weight:bold;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' height=\'70px\' /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block; margin-left:20px; float:left\">Pre scope\r\n	<p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <value><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></value> (Age :&nbsp;<value><%= year%> Year <%=month%> Month <%= day%> Day </value>)</h3>\r\n</div><hr />\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../www/Patient/search_result?\';\r\nurl += \'&id=50163c5e790f9b74a2000028\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:98%;padding:0px\">\r\n\r\n\r\n<h3>Indication : <value><%=indication %></value> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Plan Procedure : <value><%= procedure.nil? ? \'-\' : procedure.name %></value>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Previous Operation : <value><%=previous_opreation %></value> </h3>\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n    \r\n<div id=\"call_time\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Call time : </label></span>	\r\n\r\n<value><%= record.call_time.strftime(\"%H:%M\") if record.call_time %></value>\r\n<script>\r\n\r\n$(\"#data-call_time\").kendoTimePicker({\r\n	value: \'23:25\',\r\n	interval: 10\r\n});\r\n</script>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"arrival_time\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Arrival time : </label></span>	\r\n\r\n<value><%= record.arrival_time.strftime(\"%H:%M\") if record.call_time %></value>\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"mode_of_arrival\" class=\"  portlet \" style=\"width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Mode of arrival : </label></span>	\r\n\r\n<value><%=render_value \'mode_of_arrival\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\">\r\n</div>\r\n	\r\n<div id=\"person_to_notify_name\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:370px\">\r\n<span class=\"\"><label>Person to notify name : </label></span>	\r\n<value><%=render_value \'person_to_notify_name\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"relation\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Relation : </label></span>	\r\n<value><%=render_value \'relation\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"tel\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>tel : </label></span>	\r\n<value><%=render_value \'tel\'%></value>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n	\r\n<div id=\"patient_identifcation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:450px\">\r\n<span class=\"\"><label>Patient identifcation : </label></span>	\r\n\r\n<value><%=record[\'patient_identifcation\'].split(\'|\').join(\' , \')%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"verification_of_procedure\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:450px\">\r\n<span class=\"\"><label>Verification of Procedure : </label></span>	\r\n\r\n<value><%=record[\'verification_of_procedure\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"psychological_condition\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:450px\">\r\n<span class=\"\"><label>Psychological Condition : </label></span>	\r\n\r\n<value><%=render_value \'psychological_condition\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"psychological_condition_other\" class=\"  portlet \" style=\"width:450px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Other : </label></span>	\r\n<value><%=render_value \'psychological_condition_other\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"112-F8205658533\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"nursing_diagnosis\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:650px\">\r\n<span class=\"\"><label>Nursing diagnosis : </label></span>	\r\n\r\n<value><%=record[\'nursing_diagnosis\'].split(\'|\').join(\' , \')%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"nursing_deagnosis_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\">\r\n<span class=\"\"><label>Note : </label></span>	\r\n<value><%=render_value \'nursing_deagnosis_note\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"112-F8038481183\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"outcome_goal\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Outcome goal : </label></span>	\r\n\r\n<value><%=record[\'outcome_goal\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"plan_and_implementation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Plan and Implementation : </label></span>	\r\n\r\n<value><%=render_value \'plan_and_implementation\'%> <%=render_value \'plan_other\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"evaluation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Evaluation : </label></span>	\r\n\r\n	<value><%=render_value \'evaluation\'%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"previous_illness\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px\">\r\n<span class=\"\"><label>Previous illness : </label></span>	\r\n\r\n<value><%=render_value \'previous_illness\'%></value>\r\n</div>\r\n\r\n	\r\n<div id=\"previous_operation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px\">\r\n<span class=\"\"><label>Previous operation : </label></span>	\r\n\r\n<value><%=render_value \'previous_operation\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"npo_since\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>NPO since : </label></span>	\r\n\r\n<value><%=render_value \'npo_since\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n<div id=\"familycancer\" class=\"  portlet \" style=\"width:450px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Family History of Colorectal cancer : </label></span>	\r\n\r\n<value><%=render_value \'familycancer\'%></value>\r\n	\r\n\r\n</div>\r\n	\r\n<div id=\"nop_at\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:140px\">\r\n<span class=\"\"><label>at : </label></span>	\r\n\r\n<value><%= record.nop_at.strftime(\"%H:%M\") if record.call_time %></value>\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n<div id=\"bowel_preparation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px\">\r\n<span class=\"\"><label>Bowel preparation : </label></span>	\r\n\r\n<imvalue><%=render_value \'bowel_preparation\'%></imvalue>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"bowelprep_cc\" class=\"  portlet \" style=\"width:115px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>(CC.) : </label></span>	\r\n<imvalue><%=render_value \'bowelprep_cc\'%></imvalue>\r\n</div>\r\n\r\n	\r\n<div id=\"bowel_other_note\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px\">\r\n<span class=\"\"><label>Other : </label></span>	\r\n<imvalue><%=render_value \'bowel_other_note\'%></imvalue>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n	\r\n<div id=\"add_bowel_prep\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px\">\r\n<span class=\"\"><label>Add Bowel preparation : </label></span>	\r\n\r\n<imvalue><%=render_value \'add_bowel_prep\'%></imvalue>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"add_bowel_prep_cc\" class=\"  portlet \" style=\"width:115px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>(CC.) : </label></span>	\r\n<imvalue><%=render_value \'add_bowel_prep_cc\'%></imvalue>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"add_bowel_other\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px\">\r\n<span class=\"\"><label>Other : </label></span>	\r\n<imvalue><%=render_value \'add_bowel_other\'%></imvalue>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"112-F3932340452\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"quality_of_bowel_preparation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Quality of bowel preparation : </label></span>	\r\n\r\n<imvalue><%=render_value \'quality_of_bowel_preparation\'%></imvalue>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"112-F2604116493\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"on_anticoaglant_anti_platelet\" class=\"  portlet \" style=\"width:450px;margin: 0 0.5em 0.5em 0;float:left;;color:red\">\r\n<span class=\"\"><label>Anticoaglant drug : </label></span>	\r\n\r\n<imvalue><%=record[\'on_anticoaglant_anti_platelet\'].split(\'|\').join(\' , \')%></imvalue>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n\r\n<div id=\"stop\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;;color:red\">\r\n<span class=\"\"><label>Stop (days) : </label></span>	\r\n<value><%=render_value \'stop\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"accessories\" class=\"  portlet \" style=\"width:900px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Accessories removal : </label></span>	\r\n\r\n<value><%=record[\'accessories\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"skin_condition\" class=\"  portlet \" style=\"width:450px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Skin condition : </label></span>	\r\n\r\n<value><%=record[\'skin_condition\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"accessories_other\" class=\"  portlet \" style=\"width:450px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Other : </label></span>	\r\n<value><%=render_value \'accessories_other\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"112-F4081972800\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"bp\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px\">\r\n<span class=\"\"><label>BP : </label></span>	\r\n<value><%=render_value \'bp\'%>/<%=render_value \'di\'%> mmHg</value>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n	\r\n<div id=\"pr\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:110px\">\r\n<span class=\"\"><label>PR/min : </label></span>	\r\n<value><%=render_value \'pr\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"rr\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:110px\">\r\n<span class=\"\"><label>RR/min : </label></span>	\r\n<value><%=render_value \'rr\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"o2sat\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:110px\">\r\n<span class=\"\"><label>O<sub>2</sub>Sat : </label></span>	\r\n<value><%=render_value \'o2sat\'%> %</value>\r\n</div>\r\n\r\n<div id=\"weight\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:110px\">\r\n<span class=\"\"><label>W : </label></span>	\r\n<value><%=render_value \'weight\'%> kg.</value>\r\n</div>\r\n\r\n<div id=\"height\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:110px\">\r\n<span class=\"\">H : </label></span>	\r\n<value><%=render_value \'height\'%> cm.</value>\r\n</div>\r\n\r\n<div id=\"bmi\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:110px\">\r\n<span class=\"\">BMI : </label></span>	\r\n<value><%=render_value \'bmi\'%></value>\r\n</div>\r\n\r\n<div id=\"633-F0906661567\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background:#ffffcc\">\r\n		<b>Nutrition Screening</b>\r\n		\r\n	</div>\r\n	\r\n<div id=\"nutrition_1\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;min-height:30px;\">\r\n    <span class=\"\"><label>1. ได้รับสารอาหารหรือสารอาหารน้อยลงในระยะเวลา &gt;= 7 วันที่ผ่านมา :  </label>\r\n        <value><%= render_value \'nutrition_1\' %></value>\r\n    </span>	\r\n</div>\r\n\r\n<div id=\"nutrition_2\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;min-height:30px;\">\r\n    <span class=\"\"><label>2. น้ำหนักลดลงในช่วงเวลา 6 เดือนที่ผ่านมา : </label>\r\n        <value><%= render_value \'nutrition_2\' %></value>\r\n    </span>	\r\n</div>\r\n\r\n<div id=\"nutrition_3\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;min-height:30px;\">\r\n    <span class=\"\"><label>3. ดัชนีมวลกาย < 18.5 หรือ >= 25 : </label>\r\n        <value><%= render_value \'nutrition_3\' %></value>\r\n    </span>	\r\n</div>\r\n\r\n<div id=\"nutrition_4\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;min-height:30px;\">\r\n    <span class=\"\"><label>4. มีภาวะวิกฤตหรือกึ่งวิกฤตร่วมด้วย : </label>\r\n        <value><%= render_value \'nutrition_4\' %></value>\r\n    </span>	\r\n</div>\r\n	\r\n	<div id=\"112-F6525886786\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n	<div id=\"112-F4135184342\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background:#ffffcc\">\r\n		<b>Allergy and Chemical agent</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"allergy\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Allergy : </label></span>	\r\n\r\n<value><%=record[\'allergy\'].split(\'|\').join(\' , \')%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"allergy_is\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Allergy agent : </label></span>	\r\n<value><%=render_value \'allergy_is\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"symptom\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Symptom : </label></span>	\r\n<value><%=render_value \'symptom\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"112-F0975202726\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"nursing_diagnosis_1\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Nursing diagnosis : </label></span>	\r\n\r\n<value><%=record[\'nursing_diagnosis_1\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"Allergy_to\" class=\"  portlet \" style=\"width:450px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label></label></span>	\r\n<value><%=render_value \'Allergy_to\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"112-F8823884320\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"outcome_goal_1\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Outcome goal : </label></span>	\r\n\r\n<value><%=record[\'outcome_goal_1\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"plan_and_implementation_1\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Plan and Implementation : </label></span>	\r\n\r\n<value><%=record[\'plan_and_implementation_1\'].split(\'|\').join(\' , \')%></value>\r\n\r\n</div>\r\n\r\n<div id=\"evaluation_1\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px\">\r\n<span class=\"\"><label>Evaluation : </label></span>	\r\n	<value><%=record[\'evaluation_1\'].split(\'|\').join(\' , \')%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"112-F8708669263\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background:#ffffcc\">\r\n		<b>IV solution and transfer</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"solution\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Solution : </label></span>	\r\n\r\n<value><%=record[\'solution\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"oral_premed\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Oral premed : </label></span>	\r\n\r\n<value><%=record[\'oral_premed\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"physical_limitation\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px\">\r\n<span class=\"\"><label>Physical Limitation : </label></span>	\r\n\r\n<value><%=record[\'physical_limitation\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"nurse_dx_transfer\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px\">\r\n<span class=\"\"><label>Nurse diagnosis transfer : </label></span>	\r\n\r\n<value><%=record[\'nurse_dx_transfer\'].split(\'|\').join(\' , \')%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"outcom_goal_transfer\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px\">\r\n<span class=\"\"><label>Outcome goal transfer : </label></span>	\r\n\r\n<value><%=record[\'outcom_goal_transfer\'].split(\'|\').join(\' , \')%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"plan_implement_transfer\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px\">\r\n<span class=\"\"><label>Plan&Implement transfer : </label></span>	\r\n\r\n<value><%=record[\'plan_implement_transfer\'].split(\'|\').join(\' , \')%></value>\r\n	\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"evaluation_transfer\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px\">\r\n<span class=\"\"><label>Evaluation transfer : </label></span>	\r\n<value><%=record[\'evaluation_transfer\'].split(\'|\').join(\' , \')%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Recorded nurse :  <value><%=render_value \'recorded_nurse\'%></value></h4>\r\n\r\n <div id=\"recorded_date\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px; margin-left:10px\">\r\n<span class=\"\"><label>Recorded date : </label></span>	\r\n\r\n<value><%=render_value \'recorded_date\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"recorded_time\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Recorded time : </label></span>	\r\n\r\n<value><%=render_value \'recorded_time\'%></value>\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-02 14:08:14','2016-10-02 14:08:14','print',''),(2601,'print',1044,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    \r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:intra_scope].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    	width:150px;\r\n}\r\nlabel{\r\n	color:#666; font-weight:bold;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' height=\'70px\' /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"margin-left:20px; float:left; \">Intrascope\r\n	<p>Hospital No :&nbsp;<value><%=patient.hn%></value> Name : <value><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></value> (Age :&nbsp;<value><%= year%> Year <%=month%> Month <%= day%> Day </value>)</h3>\r\n</div><hr />\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\