797\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"endosocpist1\" class=\"  portlet \" style=\"width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Endosocpist : </label></span>	\r\n\r\n<value><%=render_value \'endosocpist1\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"endosocpist2\" class=\"  portlet \" style=\"width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Endosocpist 2 : </label></span>	\r\n\r\n<value><%=render_value \'endosocpist2\'%></value>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n	\r\n<div id=\"assistant1\" class=\"  portlet \" style=\"width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Assistant : </label></span>	\r\n<value><%=render_value \'assistant1\'%></value>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"assistant2\" class=\"  portlet \" style=\"width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Assistant 2 : </label></span>	\r\n<value><%=render_value \'assistant2\'%></value>\r\n</div>\r\n\r\n\r\n<div id=\"endoscopy_nurse\" class=\"  portlet \" style=\"width:900px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Endoscopy nurse : </label></span>	\r\n\r\n			<div id=\"F1847084588\">\r\n <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" bordercolor=\"#EBEBEB\">  <tr><td bgcolor=\"#EBEBEB\">No.</td><td bgcolor=\"#EBEBEB\">Endoscopy nurse </td><td bgcolor=\"#EBEBEB\">Start time</td><td bgcolor=\"#EBEBEB\">Stop time </td></tr>         \r\n<% \r\n#==================================================================================   START LOOP\r\n#sedation_time\r\ntemp_record = @record \r\ntemp_document = @document\r\n\r\ntime_to_time_doc = get_document \'time_to_time\'\r\ntime_to_time_items = models[:time_to_time].find(record.endoscopy_nurse)\r\ntime_to_time_items.each_with_index do |i,index|  \r\n\r\n@record = i\r\n@document = time_to_time_doc\r\n\r\n#=============