><%=render_value \'outcome_goal\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"plan_and_implementation\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Plan and Implementation : </label></span>	\r\n\r\n<value><%=render_value \'plan_and_implementation\'%> <%=render_value \'plan_other\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"evaluation\" class=\"  portlet \" style=\"margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Evaluation : </label></span>	\r\n\r\n<value><%=render_value \'evaluation\'%> <%=render_value \'evalutation_other\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"111-F9630768737\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n	<div id=\"111-F5132786821\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background:#ffffcc\">\r\n		<b>Sedation and Procedure</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n<div id=\"sedation\" class=\"  portlet \" style=\"width:900px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Sedation : </label></span>	\r\n\r\n			<div id=\"F8558573060\">\r\n             <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" bordercolor=\"#EBEBEB\">\r\n<tr><td width=\"4%\" bgcolor=\"#EBEBEB\">&nbsp;No.</td><td width=\"15%\" bgcolor=\"#EBEBEB\">Sedation</td><td width=\"11%\" bgcolor=\"#EBEBEB\">mg. </td><td width=\"70%\" bgcolor=\"#EBEBEB\">Sedation at time</td></tr>\r\n<% \r\n\r\n#==================================================================================   START LOOP\r\nfield_name = \'sedation\'\r\nrelate_model_name = \'sedation_time\'\r\n\r\ntemp_record = @record \r\ntemp_document = @document\r\n\r\nrelate_doc = get_document relate_model_name\r\nrelate_records = models[relate_model_name.to_sym].find(record[field_name.to_sym])\r\n\r\nif relate_records!=nil \r\n\r\nrelate_records.each_with_index do |i,index|  \r\n\r\n@record = i\r\n@document = relate_doc\r\n\r\n#================================================================================== START LOOP\r\n%>\r\n		<tr><td>&nbsp;<%=index+1%>.</td><td>&nbsp;<value><%= render_value \'sedation_drug\' %> </value></td><td>&nbsp;<value><%= render_value \'mg\' %></value></td><td>&nbsp;<value><%= render_value \'sedation_at_time\' %></value></td></tr>\r\n        			\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n<% \r\n#======================================================================== END LOOP\r\nend \r\n@record = temp_record\r\n@document = temp_document\r\nend\r\n#======================================================================== END LOOP\r\n%>\r\n</table></div>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"vital_sign\" class=\"  portlet \" style=\"width:900px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Vital sign : </label></span>	\r\n\r\n			<div id=\"F7646639377\">\r\n   <table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" bordercolor=\"#EBEBEB\"><tr> <td bgcolor=\"#EBEBEB\">&nbsp;No.</td> <td bgcolor=\"#EBEBEB\">Start </td> <td bgcolor=\"#EBEBEB\">BP</td> <td bgcolor=\"#EBEBEB\">mmHg</td> <td bgcolor=\"#EBEBEB\">PR/min</td> <td bgcolor=\"#EBEBEB\">RR/min</td> <td bgcolor=\"#EBEBEB\">O2Sat </td> <td bgcolor=\"#EBEBEB\">Note</td> </tr>\r\n<% \r\n\r\n#==================================================================================   START LOOP\r\nfield_name = \'vital_sign\'\r\nrelate_model_name = \'vital_sign\'\r\n\r\ntemp_record = @record \r\ntemp_document = @document\r\n\r\nrelate_doc = get_document relate_model_name\r\nrelate_records = models[relate_model_name.to_sym].find(record[field_name.to_sym])\r\n\r\nif relate_records!=nil \r\n\r\nrelate_records.each_with_index do |i,index|  \r\n\r\n@record = i\r\n@document = relate_doc\r\n\r\n#================================================================================== START LOOP\r\n%>            \r\n           <tr> <td>&nbsp;<%=index+1%>. </td> <td>&nbsp;<value><%= render_value \'votal_sign_start\' %></value></td> <td>&nbsp;<value><%= render_value \'bp\' %></value></td> <td>&nbsp;<value><%= render_value \'diastolic\' %></value> </td><td>&nbsp;<value><%= render_value \'pr\' %></value> </td> <td>&nbsp;<value><%= render_value \'rr\' %></value></td> <td>&nbsp;<value><%= render_value \'o2sat\' %></value></td><td>&nbsp;<value><%= render_value \'vital_sign_note\' %></value></td></tr>\r\n				\r\n<% \r\n#======================================================================== END LOOP\r\nend \r\n@record = temp_record\r\n@document = temp_document\r\nend\r\n#======================================================================== END LOOP\r\n%>\r\n</table></div>\r\n</div>\r\n\r\n	\r\n	<div id=\"111-F4697836177\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"level_of_conscious\" class=\"  portlet \" style=\"width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Level of conscious : </label></span>	\r\n\r\n<value><%=render_value \'level_of_conscious\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"electro_surgical_unit\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:550px\">\r\n<span class=\"\"><label>Electro surgical unit : </label></span>	\r\n\r\n<value><%=render_value \'electro_surgical_unit\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"ground_pad_site\" class=\"  portlet \" style=\"width:910px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Ground pad site : </label></span>	\r\n\r\n<value><%=render_value \'ground_pad_site\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"procedure\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px\">\r\n<span class=\"\"><label>Procedure : </label></span>	\r\n\r\n<imvalue><%=render_value \'procedure\'%></imvalue>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"specimen\" class=\"  portlet \" style=\"width:180px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Specimen (pieces) : </label></span>	\r\n<imvalue><%=render_value \'specimen\'%></imvalue>\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"nurse_diagnosis_electrosurgical\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Nurse diagnosis ElectroSurgical : </label></span>	\r\n\r\n<value><%=render_value \'nurse_diagnosis_electrosurgical\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"outcom_goal_electrosurgical\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Outcome goal ElectroSurgical : </label></span>	\r\n\r\n<value><%=render_value \'outcom_goal_electrosurgical\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"plan_and_imple_elec\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:900px\">\r\n<span class=\"\"><label>Plan & Implementation ElectroSurgical  : </label></span>	\r\n\r\n<value><%=render_value \'plan_and_imple_elec\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"evaluate_electro\" class=\"  portlet \" style=\"width:165px;margin: 0 0.5em 0.5em 0;float:left;width:910px\">\r\n<span class=\"\"><label>Evaluation Electrosurgical : </label></span>	\r\n\r\n<value><%=render_value \'evaluate_electro\'%></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"comment\" class=\"  portlet \" style=\"width:900px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Comment : </label></span>	\r\n<value><pre><%=render_value \'comment\'%></pre></value>\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n	\r\n\r\n\r\n</div>\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Recorded nurse :  <value><%=render_value \'recorded_nurse\'%></value></h4>\r\n\r\n\r\n	\r\n<div id=\"recorded_date\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;width:220px; margin-left:10px\">\r\n<span class=\"\"><label>Recorded date : </label></span>	\r\n\r\n<value><%=render_value \'recorded_date\'%></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"recorded_time\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Recorded time : </label></span>	\r\n\r\n<value><%= record.recorded_time.strftime(\"%H:%M\") if record.recorded_time %></value>\r\n\r\n</div>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2016-10-02 14:12:16','2016-10-02 14:12:16','print',''),(2602,'print',1045,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:post_scope].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\nvalue {color:#06F}\r\nvalue.nl {font-weight:bold;font-size:1.2em}\r\nvalue.normal {color:#388A15;font-weight:bold;font-size:1.2em}\r\nvalue.warn {color:#aa0;font-weight:bold;font-size:1.2em}\r\nvalue.error {color:#a00;font-weight:bold;font-size:1.2em}\r\ntable.tbcontent td { padding-left:5px; padding-right:5px}\r\n\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px; padding-right:20px}\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' height=\'70px\' /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"margin-left:20px; float:left; \">Post Scope\r\n    <p>Hospital No :&nbsp;<value><%=patient.hn%></value> Name : <value><%= patient.first_name %> <%= patient.last_name %></value> (Age :&nbsp;<value><%= year%> Year <%=month%> Month <%= day%> Day </value>)</h3>\r\n</div><hr />\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../www/Patient/search_result?\';\r\nurl += \'&id=501e981d790f9b50d8000001\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:930px;padding:0px\">\r\n\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n	\r\n<div id=\"time_in_recovery_room\" class=\"  portlet \" style=\"width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Time in recovery room : </label></span>	\r\n\r\n<value><%= render_value \'time_in_recovery_room\' %></value>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"post_scope_phase\" class=\"  portlet \" style=\"width:100%;float:left;\">\r\n<span class=\"\"><label>Post scope phase : </label></span>	\r\n\r\n			<div id=\"F1272873605\">\r\n            					<div id=\"509e77f1790f9b5bf10001c8\" style=\"border:0px solid #ccc;margin-bottom:0px\">\r\n\r\n	<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:10px;margin-right:10px;width:900px;padding:0px\">\r\n\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:12px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n<table border=\"1\" cellpadding=\"0\" cellspacing=\"0\" bordercolor=\"#E6E6E6\" width=\"100%\" height=\"15\">\r\n  <tr >\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\" >Time</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Point :</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Vital sign</td>\r\n      <td align=\"center\" bgcolor=\"#EEEEEE\">O<sub>2</sub>Sat</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Conscious</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Respiration</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Nausea/<br />Vomiting</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Pain</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Bleeding</td>\r\n    <td align=\"center\" bgcolor=\"#EEEEEE\">Ambulation</td>\r\n      <td align=\"center\" bgcolor=\"#EEEEEE\">Note</td>\r\n  </tr>\r\n<% \r\n\r\n#==================================================================================   START LOOP\r\nfield_name = \'post_scope_phase\'\r\nrelate_model_name = \'post_scope_record\'\r\n\r\ntemp_record = @record \r\ntemp_document = @document\r\n\r\nrelate_doc = get_document relate_model_name\r\nrelate_records = models[relate_model_name.to_sym].find(record[field_name.to_sym])\r\n\r\nif relate_records!=nil \r\n\r\nrelate_records.each_with_index do |i,index|  \r\n\r\n@record = i\r\n@document = relate_doc\r\n\r\n#================================================================================== START LOOP\r\n%>\r\n<%\r\n    v = @record.o2sat\r\n    osat = 0\r\n    osat = 1 if v> 92 \r\n    osat = 2 if v> 95\r\n    osat = osat.to_s\r\n    \r\n    point = \'0\' \r\n    point = \'1\' if @record.point>10 \r\n    point = \'2\' if @record.point>=14\r\n    \r\n    \r\n%>\r\n  <tr >\r\n<td align=\"center\" >\r\n  <value class=\"nl\"><%= render_value \'post_scope_time\' %></value>\r\n	\r\n<%\r\ndef ccls v\r\n    cls = \'normal\' \r\n    cls = \'warn\' if v==\'1\'\r\n    cls = \'error\' if v==\'0\'\r\n    cls\r\nend\r\n%>\r\n</td> <td align=\"center\">\r\n  <value class=\"<%=ccls(point)%>\"><%= @record.point %></value>\r\n</td> <td align=\"center\">\r\n<value class=\"<%=ccls(@record.vital_sign)%>\"><%=  @record.vital_sign %></value>\r\n</td><td align=\"center\">\r\n<value class=\"<%=ccls(osat)%>\"><%= osat %></value>\r\n</td> <td align=\"center\">\r\n<value class=\"<%=ccls(@record.conscious)%>\"><%= @record.conscious %></value>\r\n</td> <td align=\"center\">\r\n<value class=\"<%=ccls(@record.respiration)%>\"><%= @record.respiration %></value>\r\n</td> <td align=\"center\">\r\n<value class=\"<%=ccls(@record.nausea_vomiting)%>\"><%= @record.nausea_vomiting %></value>\r\n</td> <td align=\"center\">	\r\n<value class=\"<%=ccls(@record.pain)%>\"><%= @record.pain %></value>\r\n</td> <td align=\"center\">\r\n<value class=\"<%=ccls(@record.bleeding)%>\"><%= @record.bleeding %></value>\r\n</td>\r\n<td align=\"center\"><value class=\"<%=ccls(@record.ambulation)%>\"><%=@record.ambulation %></value></td>\r\n<td align=\"center\"><value ><%=@record.post_scope_note %></value></td>\r\n  </tr>\r\n\r\n					<% \r\n#======================================================================== END LOOP\r\nend \r\n@record = temp_record\r\n@document = temp_document\r\nend\r\n#======================================================================== END LOOP\r\n%>\r\n</table>\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n\r\n\r\n\r\n\r\n</div>\r\n					\r\n\r\n			</div>\r\n			\r\n					\r\n<input id=\"record_post_scope_phase\" name=\"record[post_scope_phase]\" type=\"hidden\" value=\"509e77f1790f9b5bf10001c8 509e77f1790f9b5bf10001c9\" />\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<center>เกณฑ์การให้คะแนน</center>\r\n<div style=\"padding-left:10px; padding-right:10px; font-size:12px;\">\r\n<table border=\"1\" cellpadding=\"0\" cellspacing=\"0\" bordercolor=\"#E6E6E6\" width=\"900\" class=\"tbcontent\">\r\n  <tr>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Topic</td>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Data</td>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Score</td>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Topic</td>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Data</td>\r\n    <td align=\"center\" bgcolor=\"#eeeeee\">Score</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"3\" valign=\"top\">1. BP, HR</td>\r\n    <td>+ - &lt; 20% ของ Pre-Procedure</td>\r\n    <td align=\"center\">2</td>\r\n    <td rowspan=\"3\" valign=\"top\"> 5. Nausea Vomiting</td>\r\n    <td>ไม่มีอาการ</td>\r\n    <td align=\"center\">2</td>\r\n    </tr>\r\n  <tr>\r\n    <td>+ - &lt; 20-40% ของ Pre-Procedure</td>\r\n    <td align=\"center\">1</td>\r\n    <td> มีอาการ</td>\r\n    <td align=\"center\">1</td>\r\n    </tr>\r\n  <tr>\r\n    <td>+ - &gt; 40% ของ Pre-Procedure</td>\r\n    <td align=\"center\">0</td>\r\n    <td> มีอาการมาก ได้รับยาแล้วยังไม่หาย</td>\r\n    <td align=\"center\">0</td>\r\n    </tr>\r\n  <tr>\r\n    <td rowspan=\"3\" valign=\"top\">2. O<sub>2</sub> Sat</td>\r\n    <td> &gt; 95% ขณะ Room air</td>\r\n    <td align=\"center\">2</td>\r\n    <td rowspan=\"3\" valign=\"top\">6. Pain</td>\r\n    <td>ไม่มีอาการปวดเสียด เจ็บแน่นท้อง หน้าอก</td>\r\n    <td align=\"center\">2</td>\r\n    </tr>\r\n  <tr>\r\n    <td> ให้ O<sub>2</sub>&nbsp;&nbsp;&nbsp;&nbsp;O<sub>2</sub>Sat > 92%</td>\r\n    <td align=\"center\">1</td>\r\n    <td>มีอาการปวดเสียด เจ็บแน่นท้อง หน้าอก</td>\r\n    <td align=\"center\">1</td>\r\n    </tr>\r\n  <tr>\r\n    <td> ให้ O<sub>2</sub>&nbsp;&nbsp;&nbsp;&nbsp;O<sub>2</sub>Sat > 92%</td>\r\n    <td align=\"center\">0</td>\r\n    <td>มีอาการปวดเสียด เจ็บแน่นท้อง หน้าอกมาก</td>\r\n    <td align=\"center\">0</td>\r\n    </tr>\r\n  <tr>\r\n    <td rowspan=\"3\" valign=\"top\">3. Conscious</td>\r\n    <td> ตื่นดี</td>\r\n    <td align=\"center\">2</td>\r\n    <td rowspan=\"3\" valign=\"top\"> 7. Bleeding</td>\r\n    <td>No bleeding per oral / Rectum</td>\r\n    <td align=\"center\">2</td>\r\n    </tr>\r\n  <tr>\r\n    <td> หลับปลุกตื่น</td>\r\n    <td align=\"center\">1</td>\r\n    <td>Bleeding per oral / Rectum</td>\r\n    <td align=\"center\">1</td>\r\n    </tr>\r\n  <tr>\r\n    <td> ไม่ตอบสนอง ไม่รุ้สึกตัว</td>\r\n    <td align=\"center\">0</td>\r\n    <td>&nbsp;</td>\r\n    <td align=\"center\">&nbsp;</td>\r\n    </tr>\r\n  <tr>\r\n    <td rowspan=\"3\" valign=\"top\">4. Respiration</td>\r\n    <td> หายใจได้ปกติ</td>\r\n    <td align=\"center\">2</td>\r\n    <td rowspan=\"3\" valign=\"top\">8. Ambulation</td>\r\n    <td> ลุกนั่งได้เอง ไม่เสียนศีรษะ เดินได้เอง ไม่เข</td>\r\n    <td align=\"center\">2</td>\r\n    </tr>\r\n  <tr>\r\n    <td> หายใจไม่ดี</td>\r\n    <td align=\"center\">1</td>\r\n    <td> ต้องการผู้ช่วยประคองให้นั่ง หรือ เดิน</td>\r\n    <td align=\"center\">1</td>\r\n    </tr>\r\n  <tr>\r\n    <td> ไม่หายใจ</td>\r\n    <td align=\"center\">0</td>\r\n    <td> นั่งไม่ได้เลย</td>\r\n    <td align=\"center\">0</td>\r\n    </tr>\r\n</table><br /><div style=\"font-size:14px\"><center>การประเมินผู้ป่วยก่อนกลับบ้าน / หอผู้ป่วย</center>\r\n<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n  <tr>\r\n    <td width=\"10%\">ผู้ป่วยนอก</td>\r\n    <td width=\"90%\">ประเมิน ข้อ 1 - 8 คะแนน = 16 กลับบ้านได้</td>\r\n  </tr>\r\n  <tr>\r\n    <td>&nbsp;</td>\r\n    <td>ประเมิน ข้อ 1 - 8 คะแนน &lt; 16 สังเกตอาการต่อ</td>\r\n  </tr>\r\n  <tr>\r\n    <td>ผู้ป่วยใน</td>\r\n    <td>ประเมิน ข้อ 1 - 7 คะแนน = 14 กลับห่อผู้ป่วยได้้</td>\r\n  </tr>\r\n</table></div>\r\n</div>\r\n</div>\r\n</div>\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Recorded nurse : <value><%= render_value \'recorded_nurse\' %></value></h4>  \r\n\r\n\r\n\r\n	\r\n<div id=\"recorded_date\" class=\"  portlet \" style=\"width:220px;margin: 0 0.5em 0.5em 0;float:left;width:250px;margin-left:10px\">\r\n<span class=\"\"><label>Recorded date : </label></span>	\r\n\r\n<value><%= render_value \'recorded_date\' %></value>\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"recorded_time\" class=\"  portlet \" style=\"width:250px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Recorded time : </label></span>	\r\n\r\n<value><%= render_value \'recorded_time\' %></value>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-10-02 14:14:36','2016-10-02 14:14:36','print',''),(2603,'print',800,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:ercp].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:200px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n.thumbnail {\r\n  position: relative;\r\n  width: 300x;\r\n  height: 300px;\r\n  overflow: hidden;\r\n}\r\n.thumbnail img {\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 50%;\r\n  height: 100%;\r\n  width: auto;\r\n  -webkit-transform: translate(-50%,-50%);\r\n      -ms-transform: translate(-50%,-50%);\r\n          transform: translate(-50%,-50%);\r\n}\r\n.thumbnail img.portrait {\r\n  width: 100%;\r\n  height: auto;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>ERCP</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v><%=record.date_note%></v>&nbsp;&nbsp; Colonoscope by :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n    <% if a= record[\'date_note\'] and a !=\"\" %>\r\n    <div id=\"date_note\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n<label>Date note: </label>\r\n<v><%=render_value \'date_note\'%> </v>\r\n<% end%>\r\n\r\n</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n	<div id=\"319-F6303882687\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"status\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>Status : </label></span>	\r\n\r\n</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"previous_opreation\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>Previous operation : </label></span>	\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>Indication : </label></span>	\r\n\r\n</div>\r\n\r\n	\r\n\r\n\r\n	<div id=\"319-F4399020731\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"record\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n<span class=\"\"><label>Record : </label></span>	\r\n\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n	<div id=\"319-F0972779869\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n	<div id=\"319-F2842321799\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Sedative</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'dormicum\'] and a !=\"\" %>\r\n<div id=\"dormicum\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:100px;min-height:30px;\">\r\nDormicum\r\n\r\n</div>\r\n<% end %>\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'dormicum_mg\'] and a !=\"\" %>\r\n<div id=\"dormicum_mg\" class=\" dormicum portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n<%=render_value \'dormicum_mg\'%>\r\n</div>\r\n<%end%>\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'dormicum_num\'] and a !=\"\" %>\r\n<div id=\"dormicum_num\" class=\" dormicum portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n	\r\n\r\n<%=render_value \'dormicum_num\'%>\r\n	\r\n\r\n</div>\r\n\r\n<% end %>\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'diprivan\'] and a !=nil %>\r\n<div id=\"diprivan\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:100px;min-height:30px;\">\r\nDiprivan\r\n\r\n</div>\r\n<% end %>\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'diprivan_mg\'] and a !=\"\" %>\r\n<div id=\"diprivan_mg\" class=\" diprivan portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n<%=render_value \'diprivan_mg\'%>\r\n\r\n</div>\r\n\r\n<% end %>\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'diprivan_num\'] and a !=\"\" %>\r\n<div id=\"diprivan_num\" class=\" diprivan portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n	<%=render_value \'diprivan_num\'%>\r\n\r\n</div>\r\n\r\n<% end %>\r\n	\r\n\r\n\r\n	<div id=\"319-F2393984515\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'pethidine\'] and a !=\"\" %>\r\n<div id=\"pethidine\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:100px;min-height:30px;\">\r\nPethidine\r\n\r\n</div>\r\n<% end %>\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'pethidine_mg\'] and a !=\"\" %>\r\n<div id=\"pethidine_mg\" class=\" pethidine portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n	<%=render_value \'pethidine_mg\'%>\r\n\r\n</div>\r\n\r\n<% end %>\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'pethidine_num\'] and a !=\"\" %>\r\n<div id=\"pethidine_num\" class=\" pethidine portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n