\r\n<div id=\"plasil\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:100px;min-height:30px;\">\r\nPlasil\r\n</div>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<% if a= record[\'plasil_mg\'] and a !=\"\" %>\r\n<div id=\"plasil_mg\" class=\" plasil portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n	<%=render_value \'plasil_mg\'%>\r\n \r\n</div>\r\n<% end %>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'plasil_route\'] and a !=\"\" %>\r\n<div id=\"plasil_route\" class=\" plasil portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n	<%=render_value \'plasil_route\'%>\r\n\r\n</div>\r\n\r\n<% end %>\r\n	\r\n\r\n\r\n	\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'fentanyl\'] and a !=\"\" %>\r\n<div id=\"fentanyl\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:100px;min-height:30px;\">\r\nFentanyl\r\n</div>\r\n<% end %>\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'mg_fentanyl\'] and a !=\"\" %>\r\n<div id=\"mg_fentanyl\" class=\" fentanyl portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n	<%=render_value \'mg_fentanyl\'%>\r\n \r\n</div>\r\n\r\n<% end %>\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'fentanyl_route\'] and a !=\"\" %>\r\n<div id=\"fentanyl_route\" class=\" fentanyl portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;\">\r\n	<%=render_value \'fentanyl_route\'%>\r\n\r\n</div>\r\n<% end %>\r\n\r\n	\r\n\r\n\r\n	<div id=\"319-F0602746188\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'other\'] and a !=\"\" %>\r\n<div id=\"other\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:100px;min-height:30px;\">\r\n	<%=render_value \'other\'%>\r\n\r\n</div>\r\n<% end %>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n<% if a= record[\'other_note\'] and a !=\"\" %>\r\n<div id=\"other_note\" class=\" other portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n	<%=render_value \'other_note\'%>\r\n</div>\r\n<% end %>\r\n\r\n	\r\n\r\n\r\n	<div id=\"319-F2466770945\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n	<hr />\r\n\r\n<h4>Scope finding</h4>\r\n<table style=\"padding-left:15px\">\r\n<tr>\r\n    <td width=\"300\">\r\n    <label>Scope pass through : </label><v><%=render_value \'scope\'%></v>\r\n    </td>\r\n</tr>\r\n</table>\r\n<% if a= record[\'common_hepatic_duct\'] and a !=\"\" %>\r\n<div id=\"common_hepatic_duct\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;\">\r\nBiliary procedure : <v><%=render_value \'Biliary_procedure\'%></v>\r\n</div>\r\n<% end %>\r\n<div id=\"common_hepatic_duct\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<% if a= record[\'common_hepatic_duct\'] and a !=\"\" %>\r\ncommon_bile_duct : <v><%=render_value \'common_bile_duct\'%></v>\r\n</div>\r\n<% end %>\r\n\r\n<% if a= record[\'common_hepatic_duct\'] and a !=\"\" %>\r\n<div id=\"common_hepatic_duct\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;\">\r\ncommon hepatic duct :<v><%=render_value \'common_hepatic_duct\'%></v>\r\n</div>\r\n<% end %>\r\n<br />\r\n<% if a= record[\'intrahepatic_duct\'] and a !=\"\" %>\r\n<div id=\"intrahepatic_duct\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;\">\r\nIntrahepatic_duct :<v><%=render_value \'intrahepatic_duct\'%></v>\r\n</div>\r\n<% end %>\r\n<br />\r\n<% if a= record[\'cystic_duct\'] and a !=\"\" %>\r\n<div id=\"cystic_duct\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;\">\r\nCystic duct<v><%=render_value \'cystic_duct\'%></v>\r\n</div>\r\n<% end %>\r\n<br />\r\n<% if a= record[\'procedure_other\'] and a !=\"\" %>\r\n<div id=\"procedure_other\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;\">\r\nOther :<v><%=render_value \'procedure_other\'%></v>\r\n</div>\r\n<% end %>\r\n<br />\r\n<% if a= record[\'pancrease\'] and a !=\"\" %>\r\n<div id=\"pancrease\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;\">\r\nPancrease :<v><%=render_value \'pancrease\'%></v>\r\n</div>\r\n<% end %>\r\n<br />\r\n<% if a= record[\'findings\'] and a !=\"\" %>\r\n<div id=\"findings\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;\">\r\nFindings :<v><%=render_value \'findings\'%></v>\r\n</div>\r\n<% end %>\r\n<br />\r\n<% if a= record[\'finding_note\'] and a !=\"\" %>\r\n<div id=\"finding_note\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;\">\r\nNote :<v><%=render_value \'finding_note\'%></v>\r\n</div>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<br />\r\n<% if  a = record[\'procedure_other\']  and a !=\"\" %><label>Note : </label><v><%=render_value \'procedure_other\'%> </v><% end%><br />\r\n<p style=\"padding-left:10px\">Start at : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<p >\r\n<%\r\n    scopes = %w{rectum_scope sigmoid_scope descending_colon_scope transvers_colon_scope ascending_colon_scope cecum_scope terminal_ileum_scope}\r\n    \r\n    scopes.each_with_index do |j,index|\r\n    if index<record.scope.to_i \r\n    tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    text = \"Normal\"\r\n    tag_cls = \'\'\r\n    if render_value(tag) == \'1\'\r\n    	text =  \"Abnormal\"\r\n    	 tag_cls = \'color:red\'\r\n    end\r\n%>\r\n<p><%= j.humanize %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Type:</td><td>Dx:</td><td>Morphology:</td><td>Size:</td><td>Treatment:</td><td>By:</td><td>Clip:</td><td>Patho No:</td>\r\n<td>Chromo By:</td><td>Kudo:</td><td>Sano:</td><td>NICE:</td><td>JNET:</td><td>Note:</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'endoscopy_dx\']%></v></td><td><v><%=i[\'morphology_type\']%></v></td><td>\r\n<% if i[\'size\']==0%>\r\n<v> -</v>\r\n<% else%>\r\n<v><%=i[\'size\']%> cm.</v>\r\n<% end%>\r\n</td>\r\n<td><v><%=i[\'treatment\']%></v></td>  <td><v><%=i[\'treatment_by\']%></v> </td> <td><v><%=i[\'clip\']%></v></td>               <td><v><%=i[\'patho_number\']%></v></td>\r\n<td><v><%=i[\'chromo\']%></v></td>     <td><v><%=i[\'kudo_type\']%></v></td>     <td><v><%=i[\'sano_type\']%></v></td>          <td><v><%=i[\'nice_classification\']%></v></td>\r\n<td><v><%=i[\'jnet_class\']%></v></td><td><v><%=i[\'abnormal_note\']%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n<hr />\r\n\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\" class=\"thumbnail\">\r\n		<%= image_tag i.path+\"?thumb=2\" %><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-02 14:24:20','2016-10-02 14:24:20','print',''),(2604,'print',1046,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:pathology].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\n    \r\n    \r\n    \r\n    patho_colonos = models[:patho_colono].find(record.colono_pathology)\r\n    patho_gastros = models[:patho_gastro].find(record.gastro_pathology)\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\nend %>\r\n\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\nvalue {color:#06F}\r\n#page {border:solid 1px; width:960px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; }\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n	-moz-border-radius: 5px; /* Gecko browsers */\r\n	border-radius: 5px; /* Everything else - limited support at the moment */	\r\n	margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n		width:150px;\r\n}\r\nlabel{\r\n	color:#666; font-weight:bold;\r\n}\r\n</style>\r\n<body>\r\n\r\n\r\n\r\n<br />\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>\r\n<center>Surgical Pathology Request Form for Cyto-Histopathology <br/> Department of Pathology</center></h3>\r\n</div><hr />\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<p>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../www/Patient/search_result?\';\r\nurl += \'&id=50163c5e790f9b74a2000028\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<div style=\"width:100%;border: 0px solid red;\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;width:930px;padding:0px\">\r\n\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid;padding:0px;width:100%;margin:0px;min-height:100px\" >\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v><%=Time.now.strftime(\"%d-%m-%Y\")%></v>&nbsp;&nbsp; Colonoscope by :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n	\r\n	<div id=\"126-F6296540512\" class=\" \" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n	<div id=\"126-F2858320218\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Colonoscopy</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"colono_pathology\" class=\"  portlet \" style=\"width:905px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<table width=\"100%\">\r\n<% for i in patho_colonos \r\n\r\n   attachments = models[:attachment].find(i.patho_image[0..5].compact)\r\n   attachments2 = models[:attachment].find(i.patho_scope[0..5].compact)\r\n   \r\n\r\n%>\r\n<tr style=\"background:#eef;padding:5px\">\r\n\r\n<td style=\"padding:5px\">No <%=i.patho_no %>.</td>\r\n    \r\n<td><%=i.location %></td>\r\n\r\n<td><%=i.endodx %></td>\r\n    \r\n<td><%=i.wide %>(W) x <%=i.height %>(H) x <%=i.depth%>(D)</td>\r\n<td colspan=\"5\" style=\"width:300px;color:red\"></td>   \r\n\r\n</tr>\r\n<tr>\r\n    <td colspan=\"8\">\r\n    <% for j in attachments %>\r\n        <%=image_tag j.path, :height=>100%>\r\n    <% end %>\r\n    </td>\r\n</tr>\r\n<% if i.diagnosis %>\r\n\r\n<tr><td >\r\n<%=\'Microscopic : \'  %></td><td style=\"color:red\"><%= i.diagnosis %>\r\n</td></tr>\r\n<tr>\r\n    <td colspan=\"8\">\r\n    <% for j in attachments2 %>\r\n        <%=image_tag j.path, :height=>100%>\r\n    <% end %>\r\n    </td>\r\n</tr>\r\n\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n</table>	\r\n\r\n\r\n			\r\n					\r\n<input id=\"record_colono_pathology\" name=\"record[colono_pathology]\" type=\"hidden\" value=\"\" />\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n	<div id=\"126-F5280413251\" class=\" \" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Gastroscopy</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n<div id=\"gastro_pathology\" class=\"  portlet \" style=\"width:905px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<table width=\"100%\">\r\n<% for i in patho_gastros \r\n\r\n   attachments = models[:attachment].find(i.patho_image[0..5].compact)\r\n   attachments2 = models[:attachment].find(i.patho_scope[0..5].compact)\r\n\r\n\r\n%>\r\n<tr style=\"background:#eef;padding:5px\">\r\n\r\n<td style=\"padding:5px\">No <%=i.patho_no %>.</td>\r\n    \r\n<td><%=i.location %></td>\r\n\r\n<td><%=i.endodx %></td>\r\n    \r\n<td><%=i.wide %>(W) x <%=i.height %>(H) x <%=i.depth%>(D)</td>\r\n<td colspan=\"5\" style=\"width:300px;color:red\"></td>        \r\n</tr>\r\n<tr>\r\n    <td colspan=\"8\">\r\n    <% for j in attachments %>\r\n        <%=image_tag j.path, :height=>100%>\r\n    <% end %>\r\n    </td>\r\n</tr>\r\n\r\n<% if i.diagnosis %>\r\n\r\n<tr><td >\r\n<%=\'Microscopic : \'  %></td><td style=\"color:red\"><%= i.diagnosis %>\r\n</td></tr>\r\n<tr>\r\n    <td colspan=\"8\">\r\n    <% for j in attachments2 %>\r\n        <%=image_tag j.path, :height=>100%>\r\n    <% end %>\r\n    </td>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>	\r\n					\r\n<input id=\"record_gastro_pathology\" name=\"record[gastro_pathology]\" type=\"hidden\" value=\"\" />\r\n\r\n	\r\n\r\n</div>\r\n\r\n\r\n	\r\n<div id=\"picture\" class=\"  portlet \" style=\"width:905px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Picture : </label></span>	\r\n\r\n<link rel= \"stylesheet\" href = \"/dragdrop/opt.css\" type=\"text/css\" />\r\n\r\n\r\n<div style=\"width:100%;border:0px solid;\">\r\n	<img src=\'/dragdrop/images/down16.png\' id=\'indicator\'/>\r\n	<div id=\'pictzone\' class=\'k-textbox k-textbox-txt\' >\r\n		\r\n\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n<!-- Upload window -->\r\n<div id=\"search-data-picture\" style=\"display:none\">	\r\n\r\n\r\n\r\n<div id=\"search-result\">\r\n</div>\r\n</div>\r\n<script type=\"text/javascript\" charset=\"utf-8\">\r\n\r\n	function openUploadWindow(){\r\n		$(document).ready(function(){\r\n		    var window = $(\"#search-data-picture\").kendoWindow({\r\n		        height: \"200px\",\r\n		        title: \"Picture Upload\",\r\n		        visible: true,\r\n		        width: \"500px\"\r\n		    }).data(\"kendoWindow\");\r\n		});\r\n		var window = $(\"#search-data-picture\").data(\"kendoWindow\");\r\n	    window.center();\r\n	    window.open();\r\n		$(\"#search-data-picture\").css(\"display\", \"block\")\r\n	}\r\n</script>\r\n<div class=\"clear\"></div>	\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\">	</div>	\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n<script type=\"text/javascript\" charset=\"utf-8\">\r\n$(\"#data-name\").kendoAutoComplete();\r\n$(\"#data-hn\").kendoAutoComplete();\r\n$(\"#data-sxpathono\").kendoAutoComplete();\r\n$(\"#data-totalspecimen\").kendoAutoComplete();\r\n\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n</div>\r\n</div>-->\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div id=\"clear\">\r\n</div>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n   <!--                                 -->\r\n\r\n</div>\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-02 14:30:09','2016-10-02 14:30:09','print',''),(2605,'show',799,2,'<%\r\n   return_url = url(\'index\')\r\n   return_url = params[:return] if params[:return]\r\n   %>\r\n<div class=\"row-fluid\">\r\n   <div class=\"span12\">\r\n      <div class=\"w-box\">\r\n         <div class=\"w-box-header\">\r\n            <h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n            <div class=\"pull-right\">\r\n               <%= link_to \'<i class=\"splashy-printer\"></i> Print image\'.html_safe, \"print_image?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n               <%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n            </div>\r\n         </div>\r\n         <div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n            <div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n               <div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n                  <%= this.display.html_safe %>\r\n                  <div style=\"padding:20px\">\r\n                     <%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n                     <%= link_to \'Back\', return_url %>\r\n                  </div>\r\n               </div>\r\n            </div>\r\n         </div>\r\n      </div>\r\n   </div>\r\n</div>\r\n<script>\r\n   sedative = [\'dormicum\',\'pethidine\',\'diprivan\',\'valium\',\'buscopan\',\'plasil\',\'fentanyl\',\'other\']\r\n   function check_sedative(ele){\r\n   check = ele.prop(\"checked\");\r\n   id = ele.prop(\"id\");\r\n   t = id.split(\'-\')[1];\r\n   if(check)\r\n   $(\".\"+t+\'\').css(\"display\",\"block\");\r\n   else\r\n   $(\".\"+t+\'\').css(\"display\",\"none\");\r\n   }\r\n   \r\n   for(i=0;i<sedative.length;i++){\r\n   t = sedative[i];  \r\n   ele = $(\'#data-\'+t);\r\n   ele.change(function(){\r\n   check_sedative($(this));\r\n   });\r\n   check_sedative(ele);\r\n   }\r\n</script>',NULL,NULL,NULL,'2016-10-02 14:40:14','2016-10-02 14:40:14','show',''),(2606,'paid',146,3,'<%\r\n    billing = get_model(\'billing\').find params[:id]\r\n    \r\n    billing.update_attributes :paid=>\'true\'\r\n    \r\n%>\r\n<script>\r\n    window.location=\"index\";\r\n</script>',NULL,NULL,NULL,'2016-10-02 14:50:30','2016-10-02 14:50:30','paid',''),(2607,'create',1047,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n    \r\n     \r\n    models = get_model\r\n    \r\n    mx = @module_model.find params[:parent_id]\r\n    \r\n    provider_id = nil\r\n    \r\n    \r\n    cm = @module_model.where(:parent_id=>mx.id, :module_name=>\"\\\\#{@current_project.name}#colonoscopy\").first\r\n    if cm\r\n        c = models[:colonoscopy].collection.find({:_id=>cm.module_id},{:fields=>{\'endoscopist_1\'=>1}}).first\r\n        provider_id = c[\'endoscopist_1\']    \r\n    else \r\n    \r\n        gm = @module_model.where(:parent_id=>mx.id, :module_name=>\"\\\\#{@current_project.name}#gastroscopy\").first\r\n        \r\n        if gm \r\n            g = models[:gastroscopy].collection.find({:_id=>gm.module_id},{:fields=>{\'endoscopist_1\'=>1}}).first\r\n            provider_id = g[\'endoscopist_1\']  \r\n        end\r\n    \r\n    end\r\n    \r\n    psm = @module_model.where(:parent_id=>mx.id, :module_name=>\"\\\\#{@current_project.name}#pre_scope\").first\r\n   \r\n   \r\n    ps = nil\r\n    finance = \'\'\r\n    type_of_patient = \'IPD\'\r\n    if psm\r\n        ps = models[:pre_scope].collection.find({:_id=>psm.module_id},{:fields=>{\'type_of_patient\'=>1,\'finance\'=>1}}).first\r\n        \r\n        finance = ps[\'finance\']\r\n        type_of_patient  = ps[\'type_of_patient\']\r\n        \r\n        \r\n        \r\n    \r\n    end\r\n    \r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    \r\n    \r\n    \r\n    record = doc.record_create(model,params)\r\n    \r\n    \r\n    \r\n    record.update_attributes :financial=>finance, :type_of_patient=>type_of_patient, :provider_id=>provider_id\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    m = @module_model.create :patient_id=>params[:patient_id], :module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n     if params[:items]\r\n       \r\n       models = get_model\r\n       \r\n       products = models[:product].find(params[:items].keys)\r\n       \r\n       items = models[:billing_item].find(record.items)\r\n       for i in items\r\n        i.destroy\r\n       end\r\n       \r\n       items = []\r\n       \r\n       for i in products\r\n       \r\n       \r\n            j = params[:items][i.id.to_s].to_i\r\n            price = params[:price][i.id.to_s].to_i\r\n            note = params[:note][i.id.to_s]\r\n            if j > 0 \r\n                 k = models[:billing_item].create :quantity=>j, :product_id=>i.id, :title=>i.name,:price=>price, :note=>note\r\n            \r\n                items << k.id\r\n            end\r\n        \r\n        end\r\n       \r\n       \r\n       record.update_attributes :items=>items\r\n       \r\n       \r\n        \r\n    end\r\n    \r\n \r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n    \r\n    \r\n    # models = get_model\r\n    \r\n    # mx = @module_model.find params[:parent_id]\r\n    \r\n    # provider_id = nil\r\n    \r\n    \r\n    # cm = @module_model.where(:parent_id=>mx.id, :module_name=>\"\\\\#{@current_project.name}#colonoscopy\").first\r\n    # if cm\r\n    #     c = models[:colonoscopy].collection.find({:_id=>cm.module_id},{:fields=>{\'endoscopist_1\'=>1}}).first\r\n    #     provider_id = c[\'endoscopist_1\']    \r\n    # else \r\n    \r\n    #     gm = @module_model.where(:parent_id=>mx.id, :module_name=>\"\\\\#{@current_project.name}#gastroscopy\").first\r\n        \r\n    #     if gm \r\n    #         g = models[:gastroscopy].collection.find({:_id=>gm.module_id},{:fields=>{\'endoscopist_1\'=>1}}).first\r\n    #         provider_id = g[\'endoscopist_1\']  \r\n    #     end\r\n    \r\n    # end\r\n    \r\n    # psm = @module_model.where(:parent_id=>mx.id, :module_name=>\"\\\\#{@current_project.name}#pre_scope\").first\r\n   \r\n   \r\n    # ps = nil\r\n    # finance = \'\'\r\n    # type_of_patient = \'IPD\'\r\n    # if psm\r\n    #     ps = models[:pre_scope].collection.find({:_id=>psm.module_id},{:fields=>{\'type_of_patient\'=>1,\'finance\'=>1}}).first\r\n        \r\n    #     finance = ps[\'finance\']\r\n    #     type_of_patient  = ps[\'type_of_patient\']\r\n    \r\n    # end\r\n    \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n\r\n<% if provider_id %>\r\n$(\'#data-provider_id\').val(\'<%=provider_id%>\')\r\n$(\'#data-financial\').val(\'<%=finance%>\')\r\n$(\'#data-type_of_patient\').val(\'<%=type_of_patient%>\')\r\n\r\n\r\n<% end %>\r\n</script>   \r\n',NULL,NULL,NULL,'2016-10-02 17:04:52','2016-10-02 17:04:52','create',''),(2608,'show',711,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\