ent_project.name\r\n    if params[:date]\r\n        session[module_name]={:date=>params[:date]}\r\n    end\r\n    if session[module_name]\r\n        params[:date] = session[module_name][:date]\r\n    end\r\n    unless params[:date]\r\n        params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n    end\r\n \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n\r\n<%\r\n    # checking existing provider\r\n    prov = get_model[:provider].where(:provider_type=>\'1\').all\r\n    if prov.empty?\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"modal-provider\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>ข้อแนะนำ</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n								    ไม่พบรายชื่อแพทย์ในระบบ กรุณาคลิกที่ปุ่ม\r\n								    \r\n									<ul class=\"dshb_icoNav tac\" style=\'display:inline\'>\r\n									    <li><a style=\"background-image: url(/gebo/img/gCons/configuration02.png)\" href=\"javascript:void(0);\">\r\n										    Settings</a></li>\r\n									</ul>\r\n									\r\n									เพื่อตั้งค่ารายชื่อแพทย์\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">รับทราบ</a>\r\n								</div>\r\n							</div>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\'#modal-provider\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n        \r\n        // $(\'#btn-add_patient\').off(\'click\');\r\n    });\r\n</script>\r\n<%\r\n    end\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n    \r\n    .table td {\r\n        vertical-align: middle;\r\n    }\r\n\r\n\r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	/*position: fixed;*/\r\n	position: absolute;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat #144884;\r\n}\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %><%= error%>\r\n    <%\r\n    session.delete :s_date\r\n    end\r\n     %>\r\n        <%\r\n    search_patient = false\r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n          end\r\n        session[:s_status] = s_status\r\n         session[:s_provider] = s_provider \r\n        \r\n    end\r\n    if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Add & Continue\"\r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n</script>\r\n<%\r\n        end\r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       <b>Home : <%= date.strftime(\'%d/%m/%Y\') %></b>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n            <div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>params[:opt], :html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n<style>\r\n.bb {width:300px;}\r\n</style>\r\n                <span class=\"field-data bb\" style=\"width:200px\" > \r\n                    <label class=\"field-label\" style=\"width:50px\">Date : </label>\r\n                    <div class=\"field-input\" >\r\n                        <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n                    </div>\r\n                </span>\r\n              \r\n               \r\n                <span class=\"field-data bb\" style=\"width:300px;\"> \r\n                    <label class=\"field-label\" style=\"width:40px\">HN : </label>\r\n                    <div class=\"field-input\" style=\"margin-right:20px\">\r\n                        <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc;\"%>\r\n                           \r\n                    </div>\r\n                    <button type=\"submit\" class=\"btn btn-success\" style=\"margin-top:5px\">\r\n  <i class=\"splashy-zoom icon-white\"></i> Search\r\n</button><%=link_to \'*\', \'javascript:void(0)\', :id=>\'btn-advanced_search\', :class=>\'btn\',:style=>\"margin-top:5px\" %>\r\n                </span>\r\n            \r\n       \r\n                \r\n             \r\n          <span style=\"float:right;margin-top:5px\">\r\n          \r\n          \r\n                  <%=link_to \'<i class=\"splashy-contact_blue_add\"></i> Add Visit\'.html_safe, \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\'%>\r\n                        <%=link_to \'<i class=\"splashy-view_list_with_thumbnail\"></i> Filter\'.html_safe, \'javascript:void(0)\', :id=>\'btn-show_filter\', :class=>\'btn\' %>\r\n                    \r\n                </span>\r\n        \r\n\r\n            <div class=\"clear\"></div>\r\n            \r\n            <script>\r\n                $(\'#search_hn\').focus();\r\n            </script>\r\n<% end %>\r\n            \r\n        </div>\r\n        \r\n    </div>\r\n\r\n    <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" id=\'block-filter\'>\r\n        <a class=\"close\" href=\"javascript:void(0);\" id=\'btn-hide_filter\' style=\'float:left\'>x</a>\r\n        <div class=\"row-fluid\">\r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\"> </label>\r\n                    <div class=\"field-input\" style=\'float:right\'>&nbsp;<b>Filter by</b></div>\r\n                </span>\r\n                <!-- filter -->\r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Provider : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-provider\" id=\"fil-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"prov_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"prov_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Procedure : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-procedure\" id=\"fil-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"proc_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"proc_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Visit : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-visit\" id=\"fil-visit\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"visit_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"visit_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Status : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-status\" id=\"fil-status\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"status_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in status_list do\r\n            %>\r\n                            <option value=\"status_<%= l %>\"><%= l %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n        </div>\r\n    </div>\r\n\r\n        <!--DATE : <%# date %>-->\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%#params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n# SEARCH SECTION    \r\n    if search_patient\r\n        \r\n        fields = {:hn=>s_hn, :first_name=>s_hn, :last_name=>s_hn}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n    \r\n        if keys.size>0\r\n            conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n            criteria = {\'$or\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n    \r\n        patients = patient_model.where(criteria).limit(20).all  \r\n        maps = module_model.all     :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n        aps = ap_model.find(maps.collect{|i| i.module_id})\r\n%>\r\n<!--<%= params[:search].to_json.html_safe %>-->\r\n<%\r\n        if aps.count == 1 # and @current_role==\'developer\' \r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= aps.first.id.to_s %>\';\r\n</script>\r\n<%\r\n        end\r\n\r\n    elsif pad = params[:adv_pat]\r\n        adv = params[:advanced]\r\n        fields = {:provider=>adv[:provider], :visit_type=>adv[:visit_type], :indication=>adv[:indication], :procedure=>adv[:procedure]}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>v} if v and v!=\'\' \r\n        end\r\n        \r\n        if keys.size>0\r\n            criteria = {\'$and\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n        \r\n        # patient criteria\r\n        fs = {:first_name=>pad[:fname], :last_name=>pad[:lname]}\r\n        ks = []\r\n        fs.each_pair do |k, v|\r\n            ks <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n        if ks.size>0\r\n            cr = {\'$or\'=>ks}\r\n        else\r\n            cr ={}\r\n        end\r\n        \r\n        a_app = []\r\n        if !criteria.empty?\r\n            a_app = ap_model.where(criteria).all\r\n        end\r\n        \r\n        a_pat = []\r\n        if !cr.empty?\r\n            a_pat = patient_model.where(cr).all\r\n        end\r\n        \r\n        if !a_app.empty? and cr.empty?\r\n            aps = a_app\r\n        elsif a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(maps.collect{|i| i.module_id})\r\n        elsif !a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(a_app.collect{|i|i.id} & maps.collect{|i| i.module_id})\r\n        else\r\n            aps = ap_model.limit(20).all\r\n        end\r\n    else\r\n    \r\n        conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n        if s_provider and s_provider !=\'\'\r\n            conds.merge! :provider=>s_provider \r\n        end\r\n\r\n        if s_status and s_status != \"\"\r\n            conds.merge! :status=>s_status \r\n        end\r\n    \r\n        aps = ap_model.all(conds)\r\n\r\n    end\r\n     \r\n         \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         app_date = link_to(i.date.strftime(\'%d/%m/%Y\'), \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\") if patient\r\n         hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=\\\\#{request.fullpath}\").html_safe if patient\r\n         public_id = \'-\'\r\n         bdate = i.date.strftime(\'%d/%m/\').to_s + (i.date.strftime(\'%Y\').to_i + 543).to_s\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id}\"),\r\n         :provider=>provider_name,:date=>app_date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\',:style=>\'margin:0px\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type, :patient_id=>patient.id, :prov_id=>i.provider, :proc_id=>i.procedure, :visit_id=>i.visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{date hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    \r\n        labels = {:no=>\'No.\', :date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Action\', :procedure=>\'Procedure\' }\r\n    \r\n    %>\r\n<div class=\"se-pre-con\"></div>\r\n<%\r\n    if aps.empty?\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\' style=\'padding:20px\'>\r\n        <center><h3>ไม่มีรายการนัดหมายสำหรับวันนี้ คลิกปุ่ม \r\n        <%=link_to \'Add Visit\', \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\',:style=>\'\',:disabled=>true%>\r\n        เพื่อเพิ่มรายการนัดหมาย</h3></center>\r\n    </div>\r\n</div>\r\n<%\r\n    else\r\n        # table fields\r\n        tf = [:no]+table_model+[:processing_ctrl,:note]\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\' style=\'padding:20px\'>\r\n        <table class=\"table table-bordered\">\r\n            <thead>\r\n                <tr>\r\n<%\r\n            tf.each do |i|\r\n%>\r\n                    <th><%= labels[i] %></th>\r\n<%\r\n            end\r\n%>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n<%\r\n            no = 1;\r\n            aps.each do |i|\r\n                i[:no] = link_to(no.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{i[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n%>\r\n                <tr class=\'filterable\'>\r\n<%\r\n                tf.each do |j|\r\n                    cs = \'\'\r\n                    if j.to_s == \'provider\'\r\n                        cs = \"class=\'filter prov_\\\\#{i[:prov_id]}\'\"\r\n                    elsif j.to_s == \'procedure\'\r\n                        cs = \"class=\'filter proc_\\\\#{i[:proc_id]}\'\"\r\n                    elsif j.to_s == \'note\'\r\n                        cs = \"class=\'filter visit_\\\\#{i[:visit_id]}\'\"\r\n                    elsif j.to_s == \'status_ctrl\'\r\n                        cs = \"class=\'filter status_\\\\#{i[:status]}\'\"\r\n                    end\r\n%>\r\n                    <td <%= cs.html_safe %>><%= i[j] %></td>\r\n<%\r\n                end\r\n%>\r\n                </tr>\r\n<%\r\n                no += 1\r\n            end # end aps\r\n%>\r\n            </tbody>\r\n        </table>\r\n    </div>\r\n</div>\r\n<%\r\n    end\r\n%>\r\n\r\n\r\n<% if false %>\r\n<%\r\n        app_a = []\r\n        app_c = []\r\n        aps.each do |i|\r\n            if i[:status] == \'Completed\'\r\n                app_c << i\r\n            else\r\n                app_a << i\r\n            end\r\n        end\r\n%>\r\n<div id=\'default-panel\' style=\'padding:5px\'>\r\n    <div class=\"tabbable\">\r\n        <ul class=\"nav nav-tabs\">\r\n            <li class=\"active\"><a href=\"#appointed\" data-toggle=\"tab\">Appointed (<%= app_a.count %>)</a></li>\r\n            <li><a href=\"#completed\" data-toggle=\"tab\">Completed (<%= app_c.count %>)</a></li>\r\n        </ul>\r\n        <div class=\"tab-content\">\r\n            <div class=\"tab-pane active\" id=\"appointed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_a,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n            <div class=\"tab-pane\" id=\"completed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_c,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<% end %>\r\n\r\n<% if false %>\r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    # out[0] = count.to_s+\".\"\r\n                    out[0] = link_to(count.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\").html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n        </div>\r\n<% end %>        \r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n <script>\r\n function change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"<%=params[:opt]%>?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n\r\n<% if false %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Encounter</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n\r\n    \r\n   \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n<% end  %>\r\n<div class=\"alert \">\r\n<%# link_to \'Total Status\',\'total_status?print[date]=\'+params[:date], :target=>\'_blank\' %>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date],class: \'btn btn-mini\' %> |\r\n<!--<%= link_to \'Status Feed\',\'total_status?print[date]=\'+params[:date],class: \'btn btn-mini\', :target=>\'_blank\' %> |-->\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date],class: \'btn btn-mini\' %> | \r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date],class: \'btn btn-mini\' %> |\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n<%\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"myModal2\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Modal header</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n									Lorem ipsum dolor sit amet, consectetur adipiscing elit. Pellentesque non elit tellus, eleifend varius erat. Lorem ipsum dolor sit amet, consectetur adipiscing elit. In bibendum laoreet ante sodales elementum. Nullam varius interdum est, at ornare quam aliquam eu. Nulla ultricies commodo leo sit amet vulputate.\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n							</div>\r\n	\r\n<div class=\"modal hide fade\" id=\"modal2\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Advanced Search</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n        \r\n<%= form_for :advanced , :url=>params[:opt] do |f| %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name  : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[first_name]\" id=\"data-fname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[last_name]\" id=\"data-lname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <%= f.submit \'Search\', :class=>\'btn btn-success\' %>\r\n                <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a> \r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n							\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                <br/>\r\n                <div id=\"patient_msg\"></div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Add & Continue\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n</script>\r\n\r\n<script>\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    \r\n    function filter() {\r\n        var prov = $(\"#fil-provider\").val();\r\n        var proc = $(\"#fil-procedure\").val();\r\n        var visit = $(\"#fil-visit\").val();\r\n        var status = $(\"#fil-status\").val();\r\n        \r\n        if (prov.indexOf(\'all\') != -1 && proc.indexOf(\'all\') != -1 && visit.indexOf(\'all\') != -1 && status.indexOf(\'all\') != -1) {\r\n            $(\'tr\').show();\r\n        } else {\r\n            $(\'.filterable\').hide();\r\n            console.log(\'all hide ...\');\r\n            $(\"td.filter\").each(function (i, col) {\r\n                \r\n                    if ($(col).hasClass(prov) || $(col).hasClass(proc) || $(col).hasClass(visit) || $(col).hasClass(status)) {\r\n                        $(col).parent(\'tr\').show();\r\n                    } else {\r\n                        // if (!$(col).parent(\'tr\').is(\':visible\')) {\r\n                            // $(col).parent(\'tr\').hide();\r\n                        // }\r\n                    }\r\n                    // console.log(\'i : \' + i + \", col : \" + col)\r\n                    \r\n            });\r\n        }\r\n        \r\n    }\r\n    \r\n    $(document).ready(function(){\r\n        <% if !prov.empty? %>\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        <% end %>\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#data-hn\').change(update_patient);\r\n        // show filter section\r\n        $(\'#block-filter\').hide();\r\n        $(\'#btn-show_filter\').click(function() {\r\n            // $(\'#block-filter\').show();\r\n            $(\'#block-filter\').fadeIn(\'slow\');\r\n        });\r\n        $(\'#btn-hide_filter\').click(function() {\r\n            $(\'#block-filter\').fadeOut(\'slow\');\r\n        })\r\n        \r\n        $(\"#fil-provider\").change(filter);\r\n        $(\"#fil-procedure\").change(filter);\r\n        $(\"#fil-visit\").change(filter);\r\n        $(\"#fil-status\").change(filter);\r\n        \r\n        // remove splash loading\r\n        $(\".se-pre-con\").fadeOut(\"slow\");\r\n    });\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2016-10-14 03:55:13','2016-10-14 03:55:13','index_bk',''),(2632,'document_name',1065,1,'\'genral_summary\'',NULL,NULL,NULL,'2016-10-15 03:17:03','2016-10-15 03:17:03',NULL,NULL),(2633,'document_name',1066,1,'\'obstetrics\'',NULL,NULL,NULL,'2016-10-15 03:31:35','2016-10-15 03:31:35','',''),(2634,'patient_record_bk',1064,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\' and i.name!=\'billing\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n    # locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name if user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2016-10-15 04:11:38','2016-10-15 04:11:38','patient_record_bk',''),(2635,'config',1064,1,'services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\' and i.name!=\'billing\'}.compact\r\n[{:name=>\'Form\',:open=>true,:actions=>services.collect{|i| {:name=>i.name.camelize,:service=>i.name,:link=>\"../\\\\#{i.name.camelize}/index\"}} }]\r\n\r\n',NULL,NULL,NULL,'2016-10-15 04:12:21','2016-10-15 04:12:21','config',''),(2636,'index',1064,2,'<%\r\n    \r\n    module_name = @current_project.name\r\n    if params[:date]\r\n        session[module_name]={:date=>params[:date]}\r\n    end\r\n    if session[module_name]\r\n        params[:date] = session[module_name][:date]\r\n    end\r\n    unless params[:date]\r\n        params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n    end\r\n \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n\r\n<%\r\n    # checking existing provider\r\n    prov = get_model[:provider].where(:provider_type=>\'1\').all\r\n    if prov.empty?\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"modal-provider\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>ข้อแนะนำ</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n								    ไม่พบรายชื่อแพทย์ในระบบ กรุณาคลิกที่ปุ่ม\r\n								    \r\n									<ul class=\"dshb_icoNav tac\" style=\'display:inline\'>\r\n									    <li><a style=\"background-image: url(/gebo/img/gCons/configuration02.png)\" href=\"javascript:void(0);\">\r\n										    Settings</a></li>\r\n									</ul>\r\n									\r\n									เพื่อตั้งค่ารายชื่อแพทย์\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">รับทราบ</a>\r\n								</div>\r\n							</div>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\'#modal-provider\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n        \r\n        // $(\'#btn-add_patient\').off(\'click\');\r\n    });\r\n</script>\r\n<%\r\n    end\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n    \r\n    .table td {\r\n        vertical-align: middle;\r\n    }\r\n\r\n\r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	/*position: fixed;*/\r\n	position: absolute;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat #144884;\r\n}\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %><%= error%>\r\n    <%\r\n    session.delete :s_date\r\n    end\r\n     %>\r\n        <%\r\n    search_patient = false\r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n          end\r\n        session[:s_status] = s_status\r\n         session[:s_provider] = s_provider \r\n        \r\n    end\r\n    if p = params[:record]\r\n        p_app = params[:app]\r\n        p[:hn] = p[:hn].strip\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Add & Continue\"\r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n</script>\r\n<%\r\n        end\r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       <b>Home : <%= date.strftime(\'%d/%m/%Y\') %></b>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n            <div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>params[:opt], :html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n<style>\r\n.bb {width:300px;}\r\n</style>\r\n                <span class=\"field-data bb\" style=\"width:200px\" > \r\n                    <label class=\"field-label\" style=\"width:50px\">Date : </label>\r\n                    <div class=\"field-input\" >\r\n                        <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n                    </div>\r\n                </span>\r\n              \r\n               \r\n                <span class=\"field-data bb\" style=\"width:300px;\"> \r\n                    <label class=\"field-label\" style=\"width:40px\">HN : </label>\r\n                    <div class=\"field-input\" style=\"margin-right:20px\">\r\n                        <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc;\"%>\r\n                           \r\n                    </div>\r\n                    <button type=\"submit\" class=\"btn btn-success\" style=\"margin-top:5px\">\r\n  <i class=\"splashy-zoom icon-white\"></i> Search\r\n</button><%=link_to \'*\', \'javascript:void(0)\', :id=>\'btn-advanced_search\', :class=>\'btn\',:style=>\"margin-top:5px\" %>\r\n                </span>\r\n            \r\n       \r\n                \r\n             \r\n          <span style=\"float:right;margin-top:5px\">\r\n          \r\n          \r\n                  <%=link_to \'<i class=\"splashy-contact_blue_add\"></i> Add Visit\'.html_safe, \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\'%>\r\n                        <%=link_to \'<i class=\"splashy-view_list_with_thumbnail\"></i> Filter\'.html_safe, \'javascript:void(0)\', :id=>\'btn-show_filter\', :class=>\'btn\' %>\r\n                    \r\n                </span>\r\n        \r\n\r\n            <div class=\"clear\"></div>\r\n            \r\n            <script>\r\n                $(\'#search_hn\').focus();\r\n            </script>\r\n<% end %>\r\n            \r\n        </div>\r\n        \r\n    </div>\r\n\r\n    <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" id=\'block-filter\'>\r\n        <a class=\"close\" href=\"javascript:void(0);\" id=\'btn-hide_filter\' style=\'float:left\'>x</a>\r\n        <div class=\"row-fluid\">\r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\"> </label>\r\n                    <div class=\"field-input\" style=\'float:right\'>&nbsp;<b>Filter by</b></div>\r\n                </span>\r\n                <!-- filter -->\r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Provider : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-provider\" id=\"fil-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"prov_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"prov_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Procedure : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-procedure\" id=\"fil-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"proc_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"proc_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Visit : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-visit\" id=\"fil-visit\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"visit_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"visit_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Status : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-status\" id=\"fil-status\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"status_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in status_list do\r\n            %>\r\n                            <option value=\"status_<%= l %>\"><%= l %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n        </div>\r\n    </div>\r\n\r\n        <!--DATE : <%# date %>-->\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%#params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n# SEARCH SECTION    \r\n    if search_patient\r\n        \r\n        fields = {:hn=>s_hn, :first_name=>s_hn, :last_name=>s_hn}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n    \r\n        if keys.size>0\r\n            conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n            criteria = {\'$or\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n    \r\n        patients = patient_model.where(criteria).limit(20).all  \r\n        maps = module_model.all     :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n        aps = ap_model.find(maps.collect{|i| i.module_id})\r\n%>\r\n<!--<%= params[:search].to_json.html_safe %>-->\r\n<%\r\n        if aps.count == 1 # and @current_role==\'developer\' \r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= aps.first.id.to_s %>\';\r\n</script>\r\n<%\r\n        end\r\n\r\n    elsif pad = params[:adv_pat]\r\n        adv = params[:advanced]\r\n        fields = {:provider=>adv[:provider], :visit_type=>adv[:visit_type], :indication=>adv[:indication], :procedure=>adv[:procedure]}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>v} if v and v!=\'\' \r\n        end\r\n        \r\n        if keys.size>0\r\n            criteria = {\'$and\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n        \r\n        # patient criteria\r\n        fs = {:first_name=>pad[:fname], :last_name=>pad[:lname]}\r\n        ks = []\r\n        fs.each_pair do |k, v|\r\n            ks <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n        if ks.size>0\r\n            cr = {\'$or\'=>ks}\r\n        else\r\n            cr ={}\r\n        end\r\n        \r\n        a_app = []\r\n        if !criteria.empty?\r\n            a_app = ap_model.where(criteria).all\r\n        end\r\n        \r\n        a_pat = []\r\n        if !cr.empty?\r\n            a_pat = patient_model.where(cr).all\r\n        end\r\n        \r\n        if !a_app.empty? and cr.empty?\r\n            aps = a_app\r\n        elsif a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(maps.collect{|i| i.module_id})\r\n        elsif !a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(a_app.collect{|i|i.id} & maps.collect{|i| i.module_id})\r\n        else\r\n            aps = ap_model.limit(20).all\r\n        end\r\n    else\r\n    \r\n        conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n        if s_provider and s_provider !=\'\'\r\n            conds.merge! :provider=>s_provider \r\n        end\r\n\r\n        if s_status and s_status != \"\"\r\n            conds.merge! :status=>s_status \r\n        end\r\n    \r\n        aps = ap_model.all(conds)\r\n\r\n    end\r\n     \r\n         \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\") if patient\r\n         public_id = \'-\'\r\n         bdate = i.date.strftime(\'%d/%m/\').to_s + (i.date.strftime(\'%Y\').to_i + 543).to_s\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}\"),\r\n         :provider=>provider_name,:date=>i.date.strftime(\'%d/%m/%Y\'),:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\',:style=>\'margin:0px\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type, :patient_id=>patient.id, :prov_id=>i.provider, :proc_id=>i.procedure, :visit_id=>i.visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{date hn patient  procedure }.collect{|i| i.to_sym}\r\n    \r\n    \r\n        labels = {:no=>\'No.\', :date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Action\', :procedure=>\'Procedure\' }\r\n    \r\n    %>\r\n<div class=\"se-pre-con\"></div>\r\n<%\r\n    if aps.empty?\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\' style=\'padding:20px\'>\r\n        <center><h3>ไม่มีรายการนัดหมายสำหรับวันนี้ คลิกปุ่ม \r\n        <%=link_to \'Add Visit\', \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\',:style=>\'\',:disabled=>true%>\r\n        เพื่อเพิ่มรายการนัดหมาย</h3></center>\r\n    </div>\r\n</div>\r\n<%\r\n    else\r\n        # table fields\r\n        tf = [:no]+table_model+[:processing_ctrl,:note]\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\' style=\'padding:20px\'>\r\n        <table class=\"table table-bordered\">\r\n            <thead>\r\n                <tr>\r\n<%\r\n            tf.each do |i|\r\n%>\r\n                    <th><%= labels[i] %></th>\r\n<%\r\n            end\r\n%>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n<%\r\n            no = 1;\r\n            aps.each do |i|\r\n                i[:no] = link_to(no.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{i[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n%>\r\n                <tr class=\'filterable\'>\r\n<%\r\n                tf.each do |j|\r\n                    cs = \'\'\r\n                    if j.to_s == \'provider\'\r\n                        cs = \"class=\'filter prov_\\\\#{i[:prov_id]}\'\"\r\n                    elsif j.to_s == \'procedure\'\r\n                        cs = \"class=\'filter proc_\\\\#{i[:proc_id]}\'\"\r\n                    elsif j.to_s == \'note\'\r\n                        cs = \"class=\'filter visit_\\\\#{i[:visit_id]}\'\"\r\n                    elsif j.to_s == \'status_ctrl\'\r\n                        cs = \"class=\'filter status_\\\\#{i[:status]}\'\"\r\n                    end\r\n%>\r\n                    <td <%= cs.html_safe %>><%= i[j] %></td>\r\n<%\r\n                end\r\n%>\r\n                </tr>\r\n<%\r\n                no += 1\r\n            end # end aps\r\n%>\r\n            </tbody>\r\n        </table>\r\n    </div>\r\n</div>\r\n<%\r\n    end\r\n%>\r\n\r\n\r\n<% if false %>\r\n<%\r\n        app_a = []\r\n        app_c = []\r\n        aps.each do |i|\r\n            if i[:status] == \'Completed\'\r\n                app_c << i\r\n            else\r\n                app_a << i\r\n            end\r\n        end\r\n%>\r\n<div id=\'default-panel\' style=\'padding:5px\'>\r\n    <div class=\"tabbable\">\r\n        <ul class=\"nav nav-tabs\">\r\n            <li class=\"active\"><a href=\"#appointed\" data-toggle=\"tab\">Appointed (<%= app_a.count %>)</a></li>\r\n            <li><a href=\"#completed\" data-toggle=\"tab\">Completed (<%= app_c.count %>)</a></li>\r\n        </ul>\r\n        <div class=\"tab-content\">\r\n            <div class=\"tab-pane active\" id=\"appointed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_a,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n            <div class=\"tab-pane\" id=\"completed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_c,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<% end %>\r\n\r\n<% if false %>\r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    # out[0] = count.to_s+\".\"\r\n                    out[0] = link_to(count.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\").html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n        </div>\r\n<% end %>        \r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n <script>\r\n function change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"<%=params[:opt]%>?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n\r\n<% if false %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Encounter</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"../Report/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n\r\n    \r\n   \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n<% end  %>\r\n<div class=\"alert \">\r\n<%# link_to \'Total Status\',\'total_status?print[date]=\'+params[:date], :target=>\'_blank\' %>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<%= link_to \'Reports\',\'../Report/index\',class: \'btn btn-mini\' %> | <%= link_to \'Summary Report\',\'summary_report?date=\'+params[:date],class: \'btn btn-mini\' %> | \r\n</div>\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n<%\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"myModal2\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Modal header</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n									Lorem ipsum dolor sit amet, consectetur adipiscing elit. Pellentesque non elit tellus, eleifend varius erat. Lorem ipsum dolor sit amet, consectetur adipiscing elit. In bibendum laoreet ante sodales elementum. Nullam varius interdum est, at ornare quam aliquam eu. Nulla ultricies commodo leo sit amet vulputate.\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n							</div>\r\n	\r\n<div class=\"modal hide fade\" id=\"modal2\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Advanced Search</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n        \r\n<%= form_for :advanced , :url=>params[:opt] do |f| %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name  : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[first_name]\" id=\"data-fname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[last_name]\" id=\"data-lname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n               \r\n                <div class=\"clear\"></div>\r\n                <div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <%= f.submit \'Search\', :class=>\'btn btn-success\' %>\r\n                <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a> \r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n							\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                <br/>\r\n                <div id=\"patient_msg\"></div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age: </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                      \r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= \"1/1/2559\" %>\" style=\"width: 120px;padding-left:5px\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        \r\n                        <script>\r\n\r\n                            date = new Date(2559, 4, 1);\r\n                            \r\n                            \r\n                            $(\"#data-birth_date\").change(function(){\r\n                                v = $(this).val()\r\n                                t = v.split(\"/\")\r\n                                date = new Date(parseInt(t[2])-543,parseInt(t[1])-1,parseInt(t[0]))\r\n                                \r\n                                $(this).val(\"\"+date.getDate()+\"/\"+(date.getMonth()+1)+\"/\"+date.getFullYear())\r\n                            })\r\n                            \r\n                        // 	$(\"#data-birth_date\").kendoDatePicker({\r\n                        // 		value: date,\r\n                        // 		  max: new Date(2560, 0, 1),\r\n                        // 		  change: function(){\r\n                        		      \r\n                        // 		        var datepicker = $(\"#data-birth_date\").data(\"kendoDatePicker\");\r\n                        // 		        d = datepicker.value()\r\n                        // 		        date = d\r\n                        //                 if(d.getYear()>200){\r\n                        //                 date = new Date(1900+d.getYear()-543, d.getMonth()-1, d.getDay());\r\n                        //                 }\r\n                        //                 datepicker.value(date);\r\n                    \r\n                        // 		  }\r\n                        // 	});\r\n                        // 	$(\"#data-birth_date\").kendoDatePicker({\r\n                        // 		value: \'<%= Time.now.strftime(\"%d/%m/%Y]\") %>\',\r\n                        // 	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                \r\n              \r\n                \r\n                \r\n                \r\n                <div id=\"mobile\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Tel.  : </label></span>	\r\n                    <input type=\"text\" name=\"record[mobile]\" id=\"data-moblie\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt \" />\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                 <div id=\"contact_address\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Address : </label></span>	\r\n                    <input type=\"text\" name=\"record[contact_address]\" id=\"data-contact_address\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt \" />\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                \r\n                      <div id=\"procedure\" class=\"  portlet  \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet hide\" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet  hide\" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet hide \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet hide\" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet hide \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n            \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Add & Continue\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"Ms\",\"value\":\"Ms\"},\r\n            {\"text\":\"Mrs\",\"value\":\"Mrs\"},   {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        \r\n        ]\r\n	\r\n    });\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n</script>\r\n\r\n<script>\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    \r\n    function filter() {\r\n        var prov = $(\"#fil-provider\").val();\r\n        var proc = $(\"#fil-procedure\").val();\r\n        var visit = $(\"#fil-visit\").val();\r\n        var status = $(\"#fil-status\").val();\r\n        \r\n        if (prov.indexOf(\'all\') != -1 && proc.indexOf(\'all\') != -1 && visit.indexOf(\'all\') != -1 && status.indexOf(\'all\') != -1) {\r\n            $(\'tr\').show();\r\n        } else {\r\n            $(\'.filterable\').hide();\r\n            console.log(\'all hide ...\');\r\n            $(\"td.filter\").each(function (i, col) {\r\n                \r\n                    if ($(col).hasClass(prov) || $(col).hasClass(proc) || $(col).hasClass(visit) || $(col).hasClass(status)) {\r\n                        $(col).parent(\'tr\').show();\r\n                    } else {\r\n                        // if (!$(col).parent(\'tr\').is(\':visible\')) {\r\n                            // $(col).parent(\'tr\').hide();\r\n                        // }\r\n                    }\r\n                    // console.log(\'i : \' + i + \", col : \" + col)\r\n                    \r\n            });\r\n        }\r\n        \r\n    }\r\n    \r\n    $(document).ready(function(){\r\n        <% if !prov.empty? %>\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        <% end %>\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#data-hn\').change(update_patient);\r\n        // show filter section\r\n        $(\'#block-filter\').hide();\r\n        $(\'#btn-show_filter\').click(function() {\r\n            // $(\'#block-filter\').show();\r\n            $(\'#block-filter\').fadeIn(\'slow\');\r\n        });\r\n        $(\'#btn-hide_filter\').click(function() {\r\n            $(\'#block-filter\').fadeOut(\'slow\');\r\n        })\r\n        \r\n        $(\"#fil-provider\").change(filter);\r\n        $(\"#fil-procedure\").change(filter);\r\n        $(\"#fil-visit\").change(filter);\r\n        $(\"#fil-status\").change(filter);\r\n        \r\n        // remove splash loading\r\n        $(\".se-pre-con\").fadeOut(\"slow\");\r\n    });\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2016-10-15 04:25:15','2016-10-15 04:25:15','index',''),(2637,'index',1059,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'index\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2016-10-17 06:50:55','2016-10-17 06:50:55','index',''),(2638,'index',1063,2,'<style>\r\n                .dataTables_wrapper{position:relative;overflow:hidden}\r\n                .dataTables_wrapper table.table {clear:both;margin-bottom:6px!important;max-width:inherit}\r\n                .dataTables_wrapper table.table thead .sorting,table.table thead .sorting_asc,table.table thead .sorting_desc,table.table thead .sorting_asc_disabled,table.table thead .sorting_desc_disabled{cursor:hand;cursor:pointer}\r\n                .dataTables_wrapper table.table thead .sorting{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_both.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc_disabled.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc_disabled.png) no-repeat center right}\r\n</style>\r\n<!-- javascript datatable -->\r\n<script src=\"/gebo/lib/datatables/jquery.dataTables.min.js\"></script>\r\n<script src=\"/gebo/lib/datatables/extras/Scroller/media/js/Scroller.min.js\"></script>\r\n<!-- datatable functions -->\r\n<script src=\"/gebo/js/gebo_datatables.js\"></script>\r\n\r\n<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\n	end\r\n	if session[module_name]\r\n	  params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n	%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n	if request.post?\r\n	    r_app = get_model[:appointment].find(params[:app_id])\r\n	    status = \'Waiting\'\r\n	    if params[:app_status]\r\n	        status = params[:app_status]\r\n	    end\r\n	    r_app.update_attributes :status=>params[:app_status], :qn=>params[:qn]\r\n	end\r\n	\r\n	\r\n	\r\n	if params[:obj_id]\r\n	    now = Time.now \r\n	\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n					<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Add Visit</button></a>\r\n					<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n						-->\r\n					<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Calendar</button></a>\r\n					<a href=\"../Report/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n					<a href=\"nurse_index?date=<%= params[:date] %>\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-heart\"></i><br />Nurse Index</button></a>\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\" >\r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n					<h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n%>\r\n\r\n\r\n<% if false %>\r\n<%\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed waiting arrived preparing processing recovery completed discharge cancelled no_show}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	list = aps.clone\r\n	id = \'\'\r\n	aps.collect!{|i| \r\n	id = i.id\r\n	  if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n	     patient = patient_model.find(m.patient_id)\r\n	     if patient \r\n	     provider = p_model.find(i.provider)\r\n	     visit_type = visits[i.visit_type]\r\n	     provider_name = \'-\'\r\n	     provider_name = provider.name if provider\r\n	     procedure_name = \'-\'\r\n	     pro = models[:procedure].find(i.procedure) \r\n	     procedure_name = pro.name if pro\r\n	     patient = patient_model.new unless patient \r\n	     hn = \'-\'\r\n	     hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n	     public_id = \'-\'\r\n	    # public_id = patient.public_id if patient\r\n	    # change to use update queue number\r\n	    #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n	    #  :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	    #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	    #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n	    #  :visit_type=>visit_type\r\n	    #  }\r\n	    n_txt = []\r\n	    if !i[:qn].nil?\r\n	        n_txt << \"Q:\\\\#{i[:qn]}\"\r\n	    end\r\n	    if i.note != \'\'\r\n	        n_txt << i.note\r\n	    end\r\n	    d_qn = \"...\"\r\n	    d_qn = \"..\\\\#{patient[:hn].tr(\'/\',\'\')[-5..-3]}/\\\\#{patient[:hn].tr(\'/\',\'\')[-2..-1]}\" if patient and  patient[:hn]\r\n	    \r\n	    c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	     :pending_ctrl=>link_to(\'Arrived\',\"javascript:patient_q(\'\\\\#{i.id}\',\'\\\\#{d_qn}\');\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n	     :visit_type=>visit_type,\r\n	     :note=>n_txt.join(\' / \')\r\n	    }\r\n	     \r\n	    if i.status==\'Waiting\' or i.status==\'Arrived\' or i.status==\'Preparing\'\r\n	        c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    \r\n	\r\n	    #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    else\r\n	        status = \'btn-info\'\r\n	        status = \'\' if i.status ==\'Completed\' or \'Discharge\'\r\n	        c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n	    end\r\n	     c\r\n	    end\r\n	  end\r\n	}.compact!\r\n	\r\n	waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\' or i[:status]==\'Arrived\' or i[:status]==\'Preparing\'}.compact\r\n	\r\n	processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n	\r\n	completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' or i[:status]==\'Discharge\' }.compact\r\n	\r\n	cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n	\r\n	table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n	:note=>\'Note\',:visit_type=>\'Group\' }\r\n	\r\n	%>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in processing\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Processing \r\n				<div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in completed\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Completed \r\n				<div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in cancelling\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Cancelled &amp; No show \r\n				<div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<!--\r\n		<div class=\"left\" style=\"width:50%\">\r\n		   <div class=\"w-box\" id=\"w_sort05\">    \r\n		        <div class=\"w-box-header\">\r\n		            Today Patients\r\n			    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n			    </div>\r\n			    <div class=\"w-box-content cnt_a\">\r\n			        content\r\n		        </div>\r\n		    </div>\r\n		</div>\r\n		-->\r\n</div>\r\n<% end %>\r\n<br/>\r\n<br/>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:320px;left:50%;margin-left:-360px\">\r\n	<div class=\"modal-header\">\r\n		<a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n		<h3>Patient Queue</h3>\r\n	</div>\r\n	<div class=\"modal-body\">\r\n		<form name=\'q\' method=\'post\'>\r\n			<span style=\'width:80px\'>Queue Number : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"qn\" id=\'qn\' style=\"width:50px\"/>\r\n			</span>\r\n			<input type=\"hidden\" name=\"app_id\" id=\"app_id\" value=\"\">\r\n			<input type=\"hidden\" name=\"app_status\" id=\"app_status\" value=\"Arrived\">\r\n			<div class=\"clear\"></div>\r\n			<input type=\"submit\" name=\"Submit\" value=\"Submit\" class=\"btn btn-success\"/>\r\n		</form>\r\n	</div>\r\n</div>\r\n<script>\r\n	function patient_q(app_id) {\r\n	    console.log(\"appointment id : \" + app_id);\r\n	    $(\'#app_id\').val(app_id);\r\n	    $(\'#modal\').modal({\r\n	        show: true, \r\n	        backdrop: \'static\',\r\n	        keyboard: true\r\n	    });\r\n	}\r\n	function patient_q(app_id, qn) {\r\n	    console.log(\"appointment id : \" + app_id);\r\n	    $(\'#qn\').val(qn);\r\n	    $(\'#app_id\').val(app_id);\r\n	    $(\'#modal\').modal({\r\n	        show: true, \r\n	        backdrop: \'static\',\r\n	        keyboard: true\r\n	    });\r\n	}\r\n</script>\r\n\r\n<script>\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'index_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        setTimeout(feed_page(100), 0);\r\n        loadPartial();\r\n    });\r\n    \r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Summary\',\'patient_summary?date=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Nurse Index\',\'nurse_index?date=\'+params[:date] %> |\r\n<!--<%= link_to \'Case Index\',\'case_index?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Patient Status\',\'patient_status?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Patient Board\',\'../Feed/nurse_board?date=\'+params[:date] %> |-->\r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %> | \r\n\r\n<span class=\"right\">\r\n<%= link_to \'Inventory\',\'../../endo_inventory/Home/index\' , :class=>\'btn btn-mini\' if @current_role==\'admin\' or @current_role==\'inventory\' or @current_role==\'developer\' %>\r\n</span>\r\n\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2016-10-17 07:03:19','2016-10-17 07:03:19','index',''),(2639,'index_partial',1063,3,'<%\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	list = aps.clone\r\n	id = \'\'\r\n	aps.collect!{|i| \r\n	id = i.id\r\n	  if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n	     patient = patient_model.find(m.patient_id)\r\n	     if patient \r\n	     provider = p_model.find(i.provider)\r\n	     visit_type = visits[i.visit_type]\r\n	     provider_name = \'NA\'\r\n	     provider_name = provider.name if provider\r\n	     procedure_name = \'NA\'\r\n	     pro = models[:procedure].find(i.procedure) \r\n	     procedure_name = pro.name if pro\r\n	     patient = patient_model.new unless patient \r\n	     hn = \'-\'\r\n	   #  hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n	     procedure_name = link_to(procedure_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n	     public_id = \'-\'\r\n	    # public_id = patient.public_id if patient\r\n	    # change to use update queue number\r\n	    #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n	    #  :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	    #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	    #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n	    #  :visit_type=>visit_type\r\n	    #  }\r\n	    n_txt = []\r\n	    if !i[:qn].nil?\r\n	        n_txt << \"Q:\\\\#{i[:qn]}\"\r\n	    end\r\n	    if i.note != \'\'\r\n	        n_txt << i.note\r\n	    end\r\n	    d_qn = \"...\"\r\n	    d_qn = \"..\\\\#{patient[:hn].tr(\'/\',\'\')[-5..-3]}/\\\\#{patient[:hn].tr(\'/\',\'\')[-2..-1]}\" if patient and  patient[:hn]\r\n	    \r\n	    i.status =\'Recovery\' if i.status == \'Recovering\'\r\n	    \r\n	    c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id.to_s}\"),\r\n	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	     :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Arrived\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n	     :visit_type=>visit_type,\r\n	     :note=>n_txt.join(\' / \')\r\n	    }\r\n	    \r\n	    if i[:status] == \'Appointed\'\r\n	        c[:ctrl] = c[:pending_ctrl]\r\n	    elsif i.status==\'Waiting\' or i.status==\'Arrived\' or i.status==\'Preparing\'\r\n	        c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    \r\n	        c[:ctrl] = c[:pending_ctrl]\r\n	    #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    else\r\n	        status = \'btn-info\'\r\n	        status = \'\' if i.status ==\'Completed\' or \'Discharge\'\r\n	        c[:processing_ctrl] =link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n	        \r\n	        c[:ctrl] = c[:processing_ctrl]\r\n	    end\r\n	    \r\n	    \r\n	    \r\n	     c\r\n	    end\r\n	  end\r\n	}.compact!\r\n	\r\n	waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\' or i[:status]==\'Arrived\' or i[:status]==\'Preparing\'}.compact\r\n	\r\n	processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n	\r\n	completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Recovering\' or i[:status]==\'Completed\' or i[:status]==\'Discharge\' }.compact\r\n	\r\n	cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n	\r\n	table_model = %w{ hn patient provider procedure status_ctrl ctrl note}.collect{|i| i.to_sym}\r\n    # table_model = %w{ hn patient provider procedure status_ctrl }.collect{|i| i.to_sym}\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:procedure=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n	:note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Actions\', :ctrl=>\'Actions\' }\r\n	\r\n	# status group\r\n    sg = aps.group_by{|i| i[:status]}\r\n	\r\nif true\r\n%>\r\n\r\n<div class=\'left\' style=\'width:100%\'>\r\n                            \r\n<%\r\n    sorted_status =%w{processing preparing appointed arrived   recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n    sorted_status.each do |x|\r\n        v = sg[x]\r\n        n = 0\r\n        if !v.nil?\r\n            n = v.count\r\n        end\r\n        \r\n        style = \'\'\r\n        if x == \'Processing\'\r\n            style = \"background:#d9edf7\"\r\n        elsif x == \'Recovery\'\r\n            style = \"background:#dff0d8\"\r\n        end\r\n%>\r\n                            <div id=\"group_<%= x.downcase %>\" class=\"accordion\">\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#status_<%= x %>\" data-parent=\"#group_<%= x %>\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											<b><%= x %> </b>\r\n											<i>(<%= n %> Patient<%= \'s\' if n > 1%>)</i>\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"status_<%= x %>\" style=\"<%= style %>\">\r\n										<div class=\"accordion-inner\">\r\n											\r\n<% if n > 0 %>\r\n			                        <div class=\'row-fluid\'>\r\n			                            <table id=\'table_<%= x %>\' class=\"table table-striped table-bordered dTableR\">\r\n    										<thead>\r\n    											<tr>\r\n<%  table_model.each do |i| %>\r\n    												<th><%= labels[i.to_sym] %></th>\r\n<%  end %>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n    if n > 0\r\n        # v = v.sort_by{|i| i[:provider]}\r\n        pg = v.group_by{|i| i[:provider]}\r\n        pg.each do |k, v|\r\n%>\r\n                                                <tr>\r\n                                                    <td colspan=\'<%= labels.count %>\'> <b><%= k %></b> </td>\r\n                                                </tr>\r\n<%\r\n        v.each do |i|\r\n%>\r\n                                                <tr>\r\n<%\r\n            table_model.each do |j|\r\n                \r\n%>\r\n                                                    <td style=\'vertical-align:middle\'><%= (i[j].nil? or i[j]==\'\') ? \'-\' : i[j] %></td>\r\n<%\r\n            end\r\n%>\r\n                                                </tr>\r\n<%\r\n        end\r\n        end\r\n%>\r\n<% end %>\r\n                                            </tbody>\r\n                                        </table>\r\n                                    </div>\r\n\r\n<% else %>\r\n<br/>\r\n<center><h3>-- Patient not available --</h3></center>\r\n<br/>\r\n<% end %>\r\n\r\n										    \r\n										</div>\r\n									</div>\r\n								</div>\r\n							</div>\r\n<% if false %>\r\n<script>\r\n        gebo_<%= x %> = {\r\n    		dt_a: function() {\r\n    			$(\'#table_<%= x %>\').dataTable({\r\n    			    stateSave : true,\r\n                    \"sDom\": \"<\'row\'<\'span6\'<\'dt_actions\'>l><\'span6\'f>r>t<\'row\'<\'span6\'i><\'span6\'p>>\",\r\n                    \"sPaginationType\": \"bootstrap_alt\",\r\n                    \"oLanguage\": {\r\n                        \"sLengthMenu\": \"_MENU_ records per page\",\r\n                        \"sEmptyTable\": \"No patient available in table. Please \'<a href=\'javascript:add_patient()\'>Add</a>\' the patient.\"\r\n                    }\r\n                });\r\n    		}\r\n        }\r\n        \r\n        gebo_<%= x %>.dt_a();\r\n</script>\r\n<% end %>\r\n<%\r\n    end\r\nend\r\n%>\r\n</div>\r\n\r\n<div class=\'clear\'></div>\r\n\r\n<% if false %>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in processing\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Processing \r\n				<div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in completed\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Completed \r\n				<div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in cancelling\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Cancelled &amp; No show \r\n				<div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<!--\r\n		<div class=\"left\" style=\"width:50%\">\r\n		   <div class=\"w-box\" id=\"w_sort05\">    \r\n		        <div class=\"w-box-header\">\r\n		            Today Patients\r\n			    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n			    </div>\r\n			    <div class=\"w-box-content cnt_a\">\r\n			        content\r\n		        </div>\r\n		    </div>\r\n		</div>\r\n		-->\r\n</div>\r\n<% end %>',NULL,NULL,NULL,'2016-10-17 07:04:02','2016-10-17 07:04:02','index_partial',''),(2640,'search',1063,2,'<h1> Search Result </h1>\r\n<% \r\n	models = get_model\r\n	\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	\r\n	fields = %w{hn public_id first_name last_name}\r\n	query = \'\'\r\n	if params[:query]\r\n	    query = params[:query].strip\r\n	end\r\n	\r\n	keys = []\r\n	\r\n	keys << {:hn=>Regexp.new(query)}\r\n	keys << {:first_name=>Regexp.new(query)}\r\n	keys << {:last_name=>Regexp.new(query)}\r\n	keys << {:public_id=>query} if query.size==13\r\n	\r\n	criteria = {\'$or\'=>keys}\r\n	\r\n	patients = patient_model.where(criteria).limit(20).all  \r\n	\r\n	app_name = \"\\\\#{@current_project.name}#appointment\"\r\n	app_model = models[:appointment]\r\n	\r\n\r\n	\r\n	fields.insert(0, \'no\')\r\n	r = 0\r\n%>\r\nResult for \'<%= query %>\' = <%= patients.count %>\r\n<hr/>\r\n<%\r\nif patients.count != 0\r\n%>\r\n<%= tabular :model=>fields,:data=>patients,:n=>10 do |row,out|\r\n	am = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).order(\'date\').last\r\n	r += 1\r\n	if am\r\n        app = app_model.where(:id=>am.module_id).first\r\n	\r\n        if @current_role!=\'pathologist\'\r\n            url = \"../Home/patient_record?id=\\\\#{am.module_id}\"\r\n        else\r\n            url = \"../Home/patho_patient_record?id=\\\\#{am.module_id}\"\r\n        end\r\n	\r\n        out[0] = link_to(\"\\\\#{r}.\", url)\r\n        out[1] = link_to(row.hn,url)\r\n        out[2] = link_to(row.public_id,url)\r\n        out[3] = link_to(row.first_name,url)\r\n        out[4] = link_to(row.last_name,url)\r\n        n = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).count\r\n        	\r\n        extra = link_to(\'Add Visit\', \"../Appointment/create?obj_id=\\\\#{row.id}&return=../Home/index\", :class=>\'btn btn-mini btn-success\') + \' \' + link_to(\"Detail (\\\\#{n})\", url, :class=>\'btn btn-mini btn-info\')\r\n        	\r\n        	\r\n        out << extra.html_safe\r\n        \r\n	else\r\n	    out[0] = \"\\\\#{r}.\"\r\n        out << link_to(\'Add Visit\', \"../Appointment/create?obj_id=\\\\#{row.id}&return=../Home/index\", :class=>\'btn btn-mini btn-success\')\r\n	end\r\n	\r\n        out\r\nend\r\n	\r\n%>\r\n<%\r\nelse\r\n%>\r\n<h3>No patient found</h3>\r\n<%= link_to \'New patient\', \"../../www/Patient/create?hn=\\\\#{params[:query]}&return=/\\\\#{@current_project.name}/Appointment/create?return=../Home/index\", :class=>\'btn btn-info\' %>\r\n<%\r\nend\r\n%>\r\n<hr/>',NULL,NULL,NULL,'2016-10-17 07:08:34','2016-10-17 07:08:34','search',''),(2641,'data_detail',591,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   records = []\r\n   n = 10 \r\n   \r\n   start = Time.at(params[:start].to_i)\r\n   stop = Time.at(params[:end].to_i)\r\n%>\r\n<%\r\n   \r\n   values = {}\r\n   query=\'\'\r\n   if params[:search]\r\n\r\n        \r\n        query = params[:search][:query]\r\n          keys = []\r\n    \r\n        @patient_doc.list_fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        \r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n\r\n                \r\n        ps = @patient_model.all({\'$or\'=>keys}.merge!(dates))\r\n   \r\n        records = []\r\n        for i in ps\r\n            records+= @module_model.where(:patient_id=>i.id,:module_name=>@module_name).all\r\n        end\r\n        count = records.size\r\n        \r\n        \r\n    else\r\n        from_date = start\r\n        to_date = stop\r\n        appointments = @models[:appointment].where(\"date\"=> {\"$gte\"=> from_date, \"$lt\"=> to_date}).sort(:created_at.desc).limit(100).all\r\n        \r\n    end\r\n\r\n   \r\n \r\n \r\n \r\n n = appointments.size\r\n rows,offset,page = params[:paginate]\r\n \r\n \r\n  \r\n records = {}\r\n patients = {}\r\n providers = {}\r\n \r\n \r\n if params[:detail]\r\n\r\n@module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id}).each do |i|\r\n patients[i.id]=i\r\n end\r\n \r\n \r\nend\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n  \r\n \r\n text = \"\\\\#{start} - \\\\#{stop}\"\r\n \r\n \r\n \r\n \r\n \r\n    pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    vtypes = {}\r\n    @models[:visit_type].all.each do |i|\r\n    vtypes[i.id] = i.name\r\n    end\r\n    \r\n appointments.collect!{|ap|\r\n   ap if records[ap.id]\r\n }.compact!\r\n    \r\n\r\nm_prov = get_model[:provider].all\r\nprov = {nil=>\'NA\', \'\'=>\'NA\'}\r\nm_prov.each do |i|\r\n    prov[i.id.to_s] = i[:name]\r\nend\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n p = patients[i.patient_id]\r\n#  provider = providers[ap.provider.to_s]\r\nprovider = prov[ap.provider.to_s]\r\n l = %w{#bcdeee}\r\nif (ap and params[:provider_id]==\'\') or (params[:provider_id] and ap.provider.to_s==params[:provider_id].to_s)\r\n     date_d = \'-\'\r\n     date_d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n     date_s = \'-\'\r\n     date_s = ap.date.strftime(\"%Y-%m-%d\")+ap.start.strftime(\" %H:%M\") if ap.date and ap.start\r\n     date_e = \'-\'\r\n     date_e = ap.date.strftime(\"%Y-%m-%d\")+ap.stop.strftime(\" %H:%M\") if ap.date  and ap.stop\r\n     \r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'procedure\'=>pro[ap.procedure],\r\n    \'date\'=>date_d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider,\r\n    \'visit_type\'=>vtypes[ap.visit_type],\r\n    \'title\'=>\"\\\\#{p.first_name if p } \\\\#{p.hn if p}\",\r\n    \'start\'=>date_s,\r\n    \'end\'=>date_e,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s}  \r\nelse\r\n    nil\r\nend \r\n}.compact\r\n\r\n    \r\n    df =   @models[:day_off].all\r\n \r\n    \r\n    df_list = df.collect{|i|\r\n        pname = \'\'\r\n        p = @models[:provider].find(i.provider)\r\n        pname = p.name if p\r\n        edit = \"../DayOff/edit?id=\\\\#{i.id}\"\r\n        if i.to_date\r\n        {\'color\'=>\'#ccc\',\'title\'=>\"\\\\#{i.title} \\\\#{pname}\",\'start\'=>i.date.strftime(\"%Y-%m-%d\"),\'end\'=>i.to_date.strftime(\"%Y-%m-%d\"),\'allDay\'=>true,\'url\'=>edit}\r\n        else\r\n        {\'color\'=>\'#ccc\',\'title\'=>\"\\\\#{i.title} \\\\#{pname}\",\'start\'=>i.date.strftime(\"%Y-%m-%d\"),\'allDay\'=>true,\'url\'=>edit}\r\n        end\r\n    }\r\n    \r\n    map = {}\r\n    \r\n    for i in json_data\r\n    \r\n    date = i[\'date\']\r\n    p = i[\'procedure\']\r\n    \r\n    map[date] = {} unless map[date]\r\n    map[date][p] = 0  unless map[date][p]\r\n    map[date][p] += 1\r\n    \r\n    end\r\n    \r\n    c_list = []\r\n    map.each_pair do |k,v|\r\n         txt = \'\'\r\n         v.each_pair { |key, value| txt+=\"\\\\#{key}=\\\\#{value}   \".html_safe }\r\n         c_list<<{\'color\'=>\'#fcc\',\'title\'=>\"\\\\#{txt}\",\'start\'=>k,\'allDay\'=>true,\'url\'=>\'/\'}\r\n    end\r\n    \r\n    detail = json_data\r\n  \r\n    \r\n   # json_data+= detail  \r\n\r\n%>\r\n<style>\r\n\r\n.k-pager-numbers{\r\n    float:left\r\n}\r\n.k-pager-numbers li{\r\nborder:0px solid;\r\ndisplay:inline-block;\r\npadding:5px;\r\n}\r\n.k-link{\r\nborder:0px solid;\r\nfloat:left;\r\ndisplay:inline-block;\r\n}\r\n.k-pager-info{\r\nfloat:right\r\n}\r\n.k-state-selected{\r\n    border:0px solid\r\n    padding:5px;\r\n    margin-top:-12px;\r\n    display:inline-table;\r\n    \r\n}\r\n\r\n\r\n</style>\r\n<%= tabular :model=>%w{provider visit_type procedure title start},:rows=>100 , :data=>json_data do |i,out|\r\nif true #\'completed\' \r\n#out<<link_to(\'Detail\', \"../Home/patient_record?id=\\\\#{i[\'id\']}\",:class=>\'btn btn-small\')\r\nend\r\nout<<link_to(\'Show\', url(\"show\",:id=>i[\'record\']),:class=>\'btn btn-small btn-info\')\r\nout<<link_to(\'Edit\', url(\"edit\",:id=>i[\'record\']),:class=>\'btn btn-small btn-warning\')\r\nout<<link_to(\'Delete\', url(\"destroy\",:id=>i[\'record\']),:class=>\'btn btn-small btn-danger\',:confirm=>\'Are you sure?\')\r\nout\r\nend\r\n%>\r\n<%# params.inspect %>',NULL,NULL,NULL,'2016-10-17 07:55:32','2016-10-17 07:55:32','data_detail',''),(2642,'print_appointment',1063,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n provider = providers[ap.provider.to_s]\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\#{year} ปี \\#{month} เดือน \\#{day} วัน\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>pro[ap.procedure],\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider.name,\r\n    \'title\'=>\"\\#{p.prefix_name if p } \\#{p.first_name if p } \\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'age\'=>age,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>\"\\#{p[:contact_person]}:\\#{p[:contact_tel]}\",\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\nlist = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงรายการผู้ป่วย\r\n<span style=\"float:right\">ประจำวันที่ \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th>Type</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>HN</th>\r\n    <th >อายุ</th>\r\n    <th>เลขประชาชน</th>\r\n    <th>Indication</th>\r\n    <th>Procedure</th>\r\n    <th>Provider</th>\r\n    <th>Tel.</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n  <% list.each_with_index do |i,index|  %>\r\n    <tr style=\"height:110px\">\r\n    <td><%=index+1%>.</td>\r\n    <td><%=i[\'visit_type\']%></td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%></td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'age\']%></td>\r\n    <td><%=i[\'public_id\']%></td>\r\n    <td><%=i[\'indication\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    <td><%=i[\'provider\']%></td>\r\n    <td><%=i[\'tel\']%></td>\r\n    </tr>\r\n    <% end %>\r\n</tbody>\r\n  </table><br/>\r\n  </div>\r\n  </div></div></div></div></div>\r\n</body>\r\n</html>\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-10-17 14:34:17','2016-10-17 14:34:17','print_appointment',''),(2643,'patient_status_partial',1063,3,'<%\r\n  \r\n    @module_name = @current_project.name+\'#appointment\' \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n  \r\n    @models = get_model\r\n  \r\n    if this.table_name!=\'appointment\' and params[:parent_id] \r\n        @appointment_module = @module_model.find(params[:parent_id])\r\n        if @appointment_module\r\n            @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n        end\r\n    end \r\n  \r\n    if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n        @patient = @patient_model.find(@patient_module.patient_id)\r\n    end\r\n\r\n    p_date = Time.now\r\n    if params[:date]\r\n        p_date = params[:date]\r\n    end\r\n        date = Date.to_mongo(p_date)\r\n     \r\n        appointments =   @models[:appointment].where(:date=>date).all\r\n     \r\n     \r\n        records = {}\r\n        patients = {}\r\n        providers = {}\r\n        indications= {}\r\n        visit_types= {}\r\n    \r\n    \r\n        @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n            records[i.module_id]=i\r\n        end\r\n     \r\n        @patient_model.find(records.values.collect{|i| i.patient_id}).each do |i|\r\n            patients[i.id]=i\r\n        end\r\n    \r\n        @models[:visit_type].all.each do |i|\r\n            visit_types[i.id.to_s] = i\r\n        end\r\n     \r\n        @models[:provider].all.each do |i|\r\n            providers[i.id.to_s] = i\r\n        end\r\n        @models[:indication].all.each do |i|\r\n            indications[i.id.to_s] = i\r\n        end\r\n     \r\n        pro = {}\r\n        @models[:procedure].all.each do |i|\r\n            pro[i.id] = i.name\r\n        end\r\n        \r\n        \r\n    \r\n        \r\n        json_data =   appointments.collect{|ap| \r\n            i  = records[ap.id]\r\n            p = patients[i.patient_id]\r\n            provider = providers[ap.provider.to_s]\r\n            l = %w{#bcdeee}\r\n            age = \'-\'\r\n            if p.birth_date\r\n                diff = Time.diff(date, p.birth_date)\r\n                year = diff[:year]\r\n                month = diff[:month]\r\n                day = diff[:day]\r\n                age = \"\\#{year} ปี \\#{month} เดือน \\#{day} วัน\"\r\n            end\r\n            indication=\"-\"\r\n            visit_type=\"-\"\r\n     \r\n            indication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n            visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n     \r\n     \r\n            if  ap.status==\'Processing\' or ap.status==\'Recovery\' or ap.status==\'Preparing\' or ap.status==\'Completed\'\r\n                apdate = \'\'\r\n                apdate = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n                starttime = \'\'\r\n                stoptime = \'\'\r\n                starttime = ap.start.strftime(\" %H:%M\") if ap.start\r\n                stoptime = ap.stop.strftime(\" %H:%M\") if ap.stop\r\n                room = ap.room==\'\' ? \'-\' : ap.room\r\n                if ap.status == \'Recovery\'\r\n                    room = \'R\'\r\n                end\r\n                qn = \'\'\r\n                if !ap[:qn].nil?\r\n                    qn = ap[:qn]\r\n                end\r\n                {\r\n                    \'id\'=>ap.id,\r\n                    \'status\'=>ap.status ,\r\n                    \'record\'=>i.id,\r\n                    \'hn\'=> p.hn,\r\n                    \'updated_at\'=>ap.updated_at,\r\n                    \'procedure\'=>pro[ap.procedure],\r\n                    \'date\'=>apdate,\r\n                    \'color\'=>l[rand(4%l.size)],\r\n                    \'provider\'=>\"\\#{provider.name if provider} \" ,\r\n                    \'title\'=>\"\\#{p.prefix_name if p }\\#{p.first_name if p }\",\r\n                    \'start\'=>apdate+starttime,\r\n                    \'end\'=>apdate+stoptime,\r\n                    \'indication\'=>indication,\r\n                    \'allDay\'=>false,\r\n                    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n                    \'age\'=>age,\r\n                    \'visit_type\'=>visit_type,\r\n                    \'public_id\'=>p.public_id,\r\n                    \'room\'=>room,\r\n                    \'qn\'=>qn\r\n                }  \r\n            else\r\n                nil\r\n            end \r\n        }.compact\r\n    \r\n        # sort data by date\r\n        list = json_data.sort{|a,b| b[\'updated_at\']<=>a[\'updated_at\']}\r\n    \r\n        s_list = list.group_by{|i| i[\'status\']}\r\n\r\n \r\n%>\r\n\r\n<table class=\"tg\" style=\"undefined;table-layout: fixed; width: 99%\">\r\n    <colgroup>\r\n        <col style=\"width: 25%\">\r\n        <col style=\"width: 25%\">\r\n        <col style=\"width: 25%\">\r\n        <col style=\"width: 25%\">\r\n    </colgroup>\r\n      <tr>\r\n<%\r\n    r = 8\r\n	s = %w{Preparing Processing Recovery Completed}\r\n	c = %w{tg-1s26 tg-xne5 tg-jfbk tg-eo60}\r\n	0.upto(s.count-1) do |i|\r\n	    n = s[i].to_s\r\n%>\r\n        <td class=\"<%= c[i] %>\" id=\'title_<%=n.downcase%>\'><%= n %></td>\r\n<% end %>\r\n      </tr>\r\n<%\r\n    c = %w{tg-avgk tg-tr29 tg-7z4u tg-cqae}\r\n    0.upto(r - 1) do |i|\r\n%>\r\n      <tr>\r\n<%\r\n        0.upto(s.count-1) do |j|\r\n            status = s[j]\r\n            qn = \' \'\r\n            x = \'.\'\r\n            if x = s_list[status]\r\n                if z = x[i]\r\n                	qn = z[\'qn\']\r\n                	if qn == \'\' or z[\'qn\'].nil?\r\n                    	qn = z[\'hn\']\r\n    	            end\r\n    	            \r\n    	            qn = \"..\\#{z[\'hn\'].tr(\'/\',\'\')[-5..-3]}/\\#{z[\'hn\'].tr(\'/\',\'\')[-2..-1]}\"\r\n    	            qn = z[\'title\']\r\n    	        end\r\n    	    end\r\n%>\r\n      \r\n        <td class=\"<%= c[j] %>\"><%= qn %></td>\r\n<%\r\n        end\r\n%>\r\n      </tr>\r\n<%\r\n    end\r\n%>\r\n    </table>',NULL,NULL,NULL,'2016-10-17 14:34:51','2016-10-17 14:34:51','patient_status_partial','*'),(2644,'status_feed_partial',1063,3,'<b>ประจำวันที่ <%= Time.now.strftime(\"%d %B %Y\") %> <%=Time.now.strftime(\"%H:%M:%S\")%></b>\r\n<div class=\"clear\"></div>\r\n<%\r\n	npage = 9\r\n	page = 0 \r\n	page = params[:page].to_i if params[:page]\r\n	\r\n	\r\n	\r\n	\r\n	@module_name = @current_project.name+\'#appointment\' \r\n	@ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@patient_doc = @ehr_project.get_document \'patient\'\r\n	@module_doc = @ehr_project.get_document \'patient_module\'\r\n	@ehr_model = @ehr_project.get_model()\r\n	@patient_model = @ehr_model[:patient]\r\n	@module_model = @ehr_model[:patient_module]\r\n	\r\n	@models = get_model\r\n	\r\n	if this.table_name!=\'appointment\' and params[:parent_id] \r\n	@appointment_module = @module_model.find(params[:parent_id])\r\n	if @appointment_module\r\n	@appointment = @models[:appointment].find(@appointment_module.module_id)\r\n	end\r\n	end \r\n	\r\n	if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n	   @patient = @patient_model.find(@patient_module.patient_id)\r\n	end\r\n	\r\n	params[:print] = {} unless params[:print]\r\n	date = Time.now\r\n	\r\n	\r\n	\r\n	if params[:print]  # and params[:print][:date]\r\n	\r\n	\r\n	\r\n	params[:print][:date] = date.strftime(\"%d/%m/%Y\") unless params[:print][:date]\r\n	\r\n	date = Date.to_mongo(params[:print][:date])\r\n	\r\n	appointments =   @models[:appointment].where(:date=>date).all\r\n	\r\n	\r\n	records = {}\r\n	patients = {}\r\n	providers = {}\r\n	indications= {}\r\n	visit_types= {}\r\n	\r\n	st_th = {\r\n	        \'Preparing\'=>\'เตรียมความพร้อม\',\r\n	        \'Processing\'=>\'กำลังส่องกล้อง\',\r\n	        \'Recovery\'=>\'พักฟื้น\',\r\n	        \'Completed\'=>\'เสร็จสิ้น\'\r\n	    }\r\n	\r\n	\r\n	@module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n	\r\n    	records[i.module_id]=i\r\n    	end\r\n    	\r\n    	@patient_model.find(records.values.collect{|i| i.patient_id}).each do |i|\r\n    	patients[i.id]=i\r\n    	end\r\n    	\r\n    	@models[:visit_type].all.each do |i|\r\n    	visit_types[i.id.to_s] = i\r\n    	end\r\n    	\r\n    	@models[:provider].all.each do |i|\r\n    	providers[i.id.to_s] = i\r\n    	end\r\n    	@models[:indication].all.each do |i|\r\n    	indications[i.id.to_s] = i\r\n    	end\r\n    	\r\n    	   pro = {}\r\n    	  @models[:procedure].all.each do |i|\r\n    	  pro[i.id] = i.name\r\n    	  end\r\n    	  \r\n    	appointments.collect!{|i| \r\n    	  \r\n    	  i if records[i.id]\r\n    	}.compact!\r\n    	\r\n    	  \r\n    	json_data =   appointments.collect{|ap| \r\n    	i  = records[ap.id]\r\n    	p = patients[i.patient_id]\r\n    	prov = providers[ap.provider.to_s]\r\n    	l = %w{#bcdeee}\r\n    	age = \'-\'\r\n    	if p.birth_date\r\n    	   diff = Time.diff(date, p.birth_date)\r\n    	  year = diff[:year]\r\n    	  month = diff[:month]\r\n    	  day = diff[:day]\r\n    	  age = \"\\\\#{year} ปี \\\\#{month} เดือน \\\\#{day} วัน\"\r\n    	end\r\n    	indication=\"-\"\r\n    	visit_type=\"-\"\r\n    	\r\n    	indication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n    	visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n    	\r\n    	\r\n    	if ap.status==\'Preparing\' or  ap.status==\'Processing\' or ap.status==\'Recovery\' or  ap.status==\'Completed\'\r\n        	apdate = \'\'\r\n        	apdate = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n        	starttime = \'\'\r\n        	stoptime = \'\'\r\n        	starttime = ap.start.strftime(\" %H:%M\") if ap.start\r\n        	stoptime = ap.stop.strftime(\" %H:%M\") if ap.stop\r\n        	prov_name = \"\\\\#{prov[:prefix]}\\\\#{prov[:first_name]}\"\r\n    	    {\r\n    	          \'id\'=>ap.id,\r\n            	  \'status\'=>ap.status ,\r\n            	  \'record\'=>i.id,\r\n            	  \'hn\'=> p.hn,\r\n            	  \'updated_at\'=>ap.updated_at,\r\n            	  \'procedure\'=>pro[ap.procedure],\r\n            	  \'date\'=>apdate,\r\n            	  \'color\'=>l[rand(4%l.size)],\r\n            	  \'provider\'=>prov_name,\r\n            	  \'title\'=>\"คุณ \\\\#{p.first_name if p } &nbsp;&nbsp; \\\\#{p[:last_name][0] if p}.\".html_safe,\r\n            	  \'start\'=>apdate+starttime,\r\n            	  \'end\'=>apdate+stoptime,\r\n            	  \'indication\'=>indication,\r\n            	  \'allDay\'=>false,\r\n            	  \'url\'=>\'edit?id=\'+i.id.to_s,\r\n            	  \'age\'=>age,\r\n            	  \'visit_type\'=>visit_type,\r\n            	  \'room\'=>ap.room,\r\n            	  \'status_th\'=>st_th[ap.status]\r\n    	    }  \r\n    	else\r\n    	  nil\r\n    	end \r\n	}.compact\r\n	\r\n	list = json_data.sort{|a,b| b[\'updated_at\']<=>a[\'updated_at\']}\r\n	\r\n	total_page =  (list.size.to_f/npage).ceil\r\n	%>\r\n<%#total_page%>\r\n<%\r\n	if page>=total_page-1\r\n	topage = 0\r\n	else\r\n	topage = page +1\r\n	end\r\n	\r\n	list = list[page*npage..(page+1)*npage-1]\r\n	\r\n	\r\n	\r\n	\r\n	 \r\n	%>\r\n<table width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" class=\"table\">\r\n	<tr>\r\n		<th>No.</th>\r\n		<!--<th>H/N</th>-->\r\n		<th>ชื่อ</th>\r\n		<th>ห้อง</th>\r\n		<th>แพทย์</th>\r\n		<th>สถานะ</th>\r\n	</tr>\r\n	<% list.each_with_index do |i,index|  %>\r\n	<tr >\r\n		<td style=\"height:none\">\r\n			<value><%=index+1+page*npage%>.</value>\r\n		</td>\r\n		<!--\r\n		<td>\r\n			<value><%=i[\'hn\']%></value>\r\n		</td>\r\n		-->\r\n		<td>\r\n			<value><%=i[\'title\']%>  </value>\r\n		</td>\r\n		<td>\r\n		    <value><%= (i[\'room\']==\'\' or i[\'room\'].nil?) ? \'-\' : i[\'room\'] %></value>\r\n		</td>\r\n		<td>\r\n		    <value><%= i[\'provider\'] %></value>\r\n		</td>\r\n		<td>\r\n			<value class=\"<%=i[\'status\']%>\"><%= i[\'status_th\'] %></value>\r\n		</td>\r\n	</tr>\r\n	<% end %>\r\n</table>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"clear\">	</div>\r\n</div>\r\n<div class=\"clear\">	</div>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<!--\r\n	</div>\r\n	</div>-->\r\n<div class=\"clear\"></div>\r\n<div id=\"clear\"></div>\r\n</p>\r\n</div>\r\n</div>\r\n<!--                                 -->\r\n<%\r\n	link = \"status_feed?page=\\\\#{topage}\"\r\n	\r\n	%>\r\n<script>\r\n	setPage(<%=topage%>);\r\n</script>\r\n<!--\r\n	<script type=\"text/javascript\">\r\n	  var timeout = setTimeout(\"location=\'<%=link%>\'\",10000);\r\n	  function resetTimeout() {\r\n	    clearTimeout(timeout);\r\n	    timeout = setTimeout(\"location=\'<%=link%>\'\",10000);\r\n	  }\r\n	</script>\r\n	-->\r\n<% end %>',NULL,NULL,NULL,'2016-10-17 14:35:26','2016-10-17 14:35:26','status_feed_partial',''),(2645,'nurse_index_partial',1063,3,'<%\r\n    @module_name = @current_project.name+\'#appointment\' \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n  \r\n    @models = get_model\r\n    \r\n    date = Time.now.strftime(\"%d/%m/%Y\")\r\n    if params[:date]\r\n        date = params[:date]\r\n    end\r\n    date = Date.to_mongo(params[:date])\r\n    \r\n    \r\n    a_app = @models[:appointment].where(:date=>date).all\r\n    \r\n    vst = {\'-\'=>\'Undefined\'}\r\n    pro = {}\r\n    rec = {}\r\n    pat = {}\r\n    prov = {}\r\n    \r\n    @models[:visit_type].all.each do |i|\r\n        vst[i.id.to_s] = i.name\r\n    end\r\n    \r\n    @models[:procedure].all.each do |i|\r\n        pro[i.id.to_s] = i.name\r\n    end\r\n    \r\n    @models[:provider].all.each do |i|\r\n        prov[i.id.to_s] = i\r\n    end\r\n    \r\n    @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>a_app.collect{|i| i.id }}).all.each do |i|\r\n        rec[i.module_id]=i\r\n    end\r\n \r\n    @patient_model.find(rec.values.collect{|i| i.patient_id}).each do |i|\r\n        pat[i.id]=i\r\n    end\r\n    \r\n    \r\n    res = a_app.collect{|ap| \r\n        i  = rec[ap.id]\r\n        p = pat[i.patient_id]\r\n        if p.nil?\r\n            next\r\n        end\r\n        provider = prov[ap.provider.to_s]\r\n        l = %w{#bcdeee}\r\n        age = \'-\'\r\n        if p.birth_date\r\n            diff = Time.diff(date, p.birth_date)\r\n            year = diff[:year]\r\n            month = diff[:month]\r\n            day = diff[:day]\r\n            age = \"\\\\#{year}\"\r\n        end\r\n        # indication=\"-\"\r\n        # visit_type=\"-\"\r\n \r\n        # indication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n        # visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n \r\n        # if  ap.status==\'Waiting\' or  ap.status==\'Processing\' or ap.status==\'Recovery\' or  (ap.status==\'Completed\' and ( Time.now - ap.updated_at ) < 300)\r\n            apdate = \'\'\r\n            apdate = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n            starttime = \'\'\r\n            stoptime = \'\'\r\n            starttime = ap.start.strftime(\" %H:%M\") if ap.start\r\n            stoptime = ap.stop.strftime(\" %H:%M\") if ap.stop\r\n            room = ap.room==\'\' ? \'-\' : ap.room\r\n            if ap.status == \'Recovery\'\r\n                room = \'R\'\r\n            # elsif ap.status == \'Preparing\'\r\n            #     room = \'P\'\r\n            end\r\n            vs = \'-\'\r\n            if ap.visit_type != \'\' and !ap.visit_type.nil?\r\n                vs = ap.visit_type\r\n            end\r\n            p_rec = link_to(\"\\\\#{p.hn}\", \"../Home/patient_record?id=\\\\#{ap.id}\", :target=>\'_blank\')\r\n            {\r\n                \'id\'=>ap.id,\r\n                \'status\'=>ap.status ,\r\n                \'record\'=>i.id,\r\n                \'hn\'=> p_rec,\r\n                \'updated_at\'=>ap.updated_at,\r\n                \'procedure\'=>pro[ap.procedure.to_s],\r\n                \'date\'=>apdate,\r\n                \'color\'=>l[rand(4%l.size)],\r\n                \'provider\'=>\"\\\\#{provider.name if provider} \" ,\r\n                \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p }\",\r\n                \'full_name\'=>\"\\\\#{p.prefix_name if p }\\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n                \'start\'=>apdate+starttime,\r\n                \'end\'=>apdate+stoptime,\r\n                # \'indication\'=>indication,\r\n                \'allDay\'=>false,\r\n                \'url\'=>\'edit?id=\'+i.id.to_s,\r\n                \'age\'=>age,\r\n                # \'visit_type\'=>visit_type,\r\n                \'public_id\'=>p.public_id,\r\n                \'room\'=>room,\r\n                \'qn\'=>ap[:qn],\r\n                \'visit_type\'=>vst[vs.to_s]\r\n            }  \r\n        # else\r\n        #     nil\r\n        # end \r\n    }.compact\r\n    # sort data by date\r\n    list = res.sort{|a,b| b[\'updated_at\']<=>a[\'updated_at\']}\r\n    \r\n    g_list = list.group_by{|i| i[\'status\']}\r\n    c_list = list.group_by{|i| i[\'procedure\']}\r\n    \r\n    s_list = %w{appointed arrived preparing processing recovery completed discharge}.collect{|i| i.humanize}\r\n    \r\n    nc = g_list[\'Completed\'].nil? ? 0 : g_list[\'Completed\'].count\r\n%>\r\n\r\n\r\n\r\n\r\n<% if false %>\r\n<div class=\'row-fluid\'>\r\n    <div class=\"span10\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                Today Case<%= a_app.count <= 1 ? \'\' : \'s\' %>\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"today_case\">\r\n            <!--<div class=\'span8\'>-->\r\n                <table class=\"table table-bordered\">\r\n                    <thead>\r\n                        <tr>\r\n                            <th><center>Procedure</center></th>\r\n                            <% s_list.each do |i| %>\r\n                            <th><center><%= i %></center></th>\r\n                            <% end %>\r\n                        </tr>\r\n                    </thead>\r\n                    <tbody>\r\n                    <% \r\n                        c_sort = c_list.keys.sort\r\n                        c_sort.each do |i| \r\n                    %>\r\n                        <tr>\r\n                            <td><%= i %></td>\r\n                    <%\r\n                        gr = c_list[i].group_by{|i| i[\'status\']}\r\n                        s_list.each do |i|\r\n                            n = gr[i].nil? ? 0 : gr[i].count\r\n                    %>\r\n                            <td><center><%= n %></center></td>\r\n                    <% end %>\r\n                        </tr>\r\n                    <% end %>\r\n                    </tbody>\r\n                </table>\r\n            <!--</div>-->\r\n    	</div>\r\n    </div>\r\n    <div class=\"span2\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                Status\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"all_patient\">\r\n    	    <div class=\"alert alert-block alert-success\">\r\n    	        <center><h1><%= nc %> / <%= a_app.count %></h1></center>\r\n    	        <!--<center><b>Date : </b><%= date.strftime(\'%d/%m/%Y\') %> </center>-->\r\n    	        <center><%= link_to \'Refresh\', \'javascript:location.reload()\', :class=>\'btn btn-success\' %></center>\r\n    	    </div>\r\n    	</div>\r\n    </div>\r\n</div>\r\n<% end # if false <-- not show %>\r\n\r\n<!--\r\n\r\n        Arrived Section\r\n        \r\n-->\r\n<div class=\'row-fluid\'>\r\n    <div class=\"span10\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                Arrived\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"status-arrived\">\r\n<%\r\n    sa = 0 # arrived status\r\n    if g_list.has_key? \'Arrived\'\r\n        sa = g_list[\'Arrived\'].count\r\n    end\r\n    if sa == 0\r\n%>\r\n<center>\r\n    <div>--- No Patient ---</div>\r\n    \r\n    <%= link_to \'Reload\', \'javascript:location.reload()\', :class=>\'btn btn-success\' %>                \r\n</center>\r\n<% \r\n    else \r\n        # arrived list\r\n        al = g_list[\'Arrived\'] \r\n        # arrived visit\r\n        av = al.group_by{|i| i[\'visit_type\']}\r\n        av.keys.each do |v|\r\n%>\r\n        <div class=\'alert alert-info\'>\r\n            <b>Visit : </b> <%= v %>\r\n            <span id=\'btn-reload\' style=\'float:right\'>\r\n                <%# link_to \'Reload\', \'javascript:location.reload()\', :class=>\'btn btn-info\', :style=>\'margin-top:-4.5px\' %>\r\n                <%= link_to \'Reload\', \'javascript:feed_page(500)\', :class=>\'btn btn-info\', :style=>\'margin-top:-4.5px\' %>\r\n            </span>\r\n        <!--</div>-->\r\n            <div class=\'row-fluid\' style=\'margin-top:10px\'></div>\r\n            <table class=\"table table-striped\" >\r\n                <thead>\r\n                    <tr>\r\n                        <th>QN</th>\r\n                        <th>HN</th>\r\n                        <th>Name</th>\r\n                        <th>Age</th>\r\n                        <th>Procedure</th>\r\n                        <th>Provider</th>\r\n                        <th>Room</th>\r\n                        <th>&nbsp;</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n<%\r\n                        idx = 1\r\n                        av[v].each do |i|\r\n%>\r\n                    <tr>\r\n                        <td><%= i[\'qn\'] %></td>\r\n                        <td><%= i[\'hn\'] %></td>\r\n                        <td><%= i[\'full_name\'] %></td>\r\n                        <td><%= i[\'age\'] %></td>\r\n                        <td><%= i[\'procedure\'] %></td>\r\n                        <td><%= i[\'provider\'] %></td>\r\n                        <td><%=link_to \"\\\\#{i[\'room\']}\", \"javascript:app_update(\'\\\\#{i[\'id\']}\',\'\\\\#{i[\'hn\']}\', \'\\\\#{i[\'title\']}\', \'\\\\#{i[\'room\']}\', \'\\\\#{i[\'status\']}\')\"%></td>\r\n                        <td><%= link_to \'<i class=\"splashy-arrow_state_blue_right\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{i[\'id\']}\',\'\\\\#{s_list[idx+1]}\',\'\')\", :class=>\'\' %></td>\r\n                    </tr>\r\n<%\r\n                        end\r\n%>\r\n                </tbody>\r\n            </table>\r\n            </div>\r\n            <!--<div class=\'row-fluid\' style=\'margin-top:10px\'></div>-->\r\n            \r\n<% \r\n        end\r\n    end \r\n%>\r\n    	</div>\r\n    </div>\r\n    <div class=\"span2\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                Total\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"total-status-arrived\">\r\n    	    <div class=\"alert alert-block alert-success\">\r\n    	        <center>\r\n    	            <h1><%= sa %> </h1>\r\n    	            <center>\r\n    	                <%= link_to \'Case Index\', \"case_index?date=\\\\#{date.strftime(\'%d/%m/%Y\')}\", :class=>\'btn btn-success\' %>\r\n    	            </center>       \r\n    	        </center>\r\n    	    </div>\r\n    	</div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<!--\r\n\r\n\r\n        Status Section\r\n        \r\n-->\r\n<div class=\'row-fluid\'>\r\n    <!--<div class=\'row-fluid\'><%= date %></div>-->\r\n    \r\n<% \r\n    s_list[2..4].each_with_index do |r, idx|\r\n        idx += 2\r\n        n = !g_list[r].nil? ? g_list[r].count : 0\r\n%>\r\n    <div class=\"span4\" >\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                <%= r %> \r\n    	        <div class=\"pull-right\"><i class=\"\"><%= n %> Patient<%= n <= 1 ? \"\" : \"s\" %></i></div>\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"cnt_<%= r.downcase %>\">\r\n    	    <div class=\"alert alert-block alert-info\">\r\n    	        <center><h1><%= n %></h1></center>\r\n    	    </div>\r\n<%\r\n        tmp = g_list[r]\r\n        if tmp\r\n%>\r\n            <table class=\"table table-striped\">\r\n                <thead>\r\n                    <tr>\r\n                        <th>&nbsp;</th>\r\n                        <th>HN</th>\r\n                        <th>Name</th>\r\n                        <th>Procedure</th>\r\n                        <th>R</th>\r\n                        <th>&nbsp;</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n<%\r\n                        tmp.each do |i|\r\n%>\r\n                    <tr>\r\n                        <td><%= link_to \'<i class=\"splashy-arrow_state_blue_left\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{i[\'id\']}\',\'\\\\#{s_list[idx-1]}\',\'\')\", :class=>\'\' %></td>\r\n                        <td><%= i[\'hn\'] %></td>\r\n                        <td><%= i[\'title\'] %></td>\r\n                        <td><%= i[\'procedure\'] %></td>\r\n                        <td><%= link_to \"\\\\#{i[\'room\']}\", \"javascript:app_update(\'\\\\#{i[\'id\']}\',\'\\\\#{i[\'hn\']}\', \'\\\\#{i[\'title\']}\', \'\\\\#{i[\'room\']}\', \'\\\\#{i[\'status\']}\')\" %></td>\r\n                        <td><%= link_to \'<i class=\"splashy-arrow_state_blue_right\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{i[\'id\']}\',\'\\\\#{s_list[idx+1]}\',\'\')\", :class=>\'\' %></td>\r\n                    </tr>\r\n<%\r\n                        end\r\n%>\r\n                </tbody>\r\n            </table>\r\n<%\r\n            \r\n        else\r\n%>\r\n<center>--- No Patient ---</center>\r\n<%\r\n        end\r\n%>\r\n        </div>\r\n    </div>\r\n<%\r\n    end\r\n%>\r\n    \r\n</div>\r\n\r\n\r\n<!--\r\n\r\n\r\n        Completed Section\r\n\r\n\r\n-->\r\n<div class=\'row-fluid\'>\r\n    <div class=\"span10\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                Completed\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"all_patient\">\r\n<%\r\n    if nc == 0\r\n%>\r\n<center>--- No Patient ---</center>\r\n<% else %>\r\n            <table class=\"table table-striped\">\r\n                <thead>\r\n                    <tr>\r\n                        <th>&nbsp;</th>\r\n                        <th>QN</th>\r\n                        <th>HN</th>\r\n                        <th>Name</th>\r\n                        <th>Age</th>\r\n                        <th>Procedure</th>\r\n                        <th>Provider</th>\r\n                        <th>&nbsp;</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n<%\r\n                        idx = s_list.index(\'Completed\')\r\n                        g_list[\'Completed\'].each do |i|\r\n%>\r\n                    <tr>\r\n                        <td><%= link_to \'<i class=\"splashy-arrow_state_blue_left\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{i[\'id\']}\',\'\\\\#{s_list[idx-1]}\',\'\')\", :class=>\'\' %></td>\r\n                        <td><%= i[\'qn\'] %></td>\r\n                        <td><%= i[\'hn\'] %></td>\r\n                        <td><%= i[\'full_name\'] %></td>\r\n                        <td><%= i[\'age\'] %></td>\r\n                        <td><%= i[\'procedure\'] %></td>\r\n                        <td><%= i[\'provider\'] %></td>\r\n                        <td><%= link_to \'<i class=\"splashy-arrow_state_blue_right\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{i[\'id\']}\',\'\\\\#{s_list[idx+1]}\',\'\')\", :class=>\'\' %></td>\r\n                    </tr>\r\n<%\r\n                        end\r\n%>\r\n                </tbody>\r\n            </table>\r\n<% end %>\r\n    	</div>\r\n    </div>\r\n    <div class=\"span2\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                Total\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"all_patient\">\r\n    	    <div class=\"alert alert-block alert-success\">\r\n    	        <center><h1><%= nc %> </h1></center>\r\n    	    </div>\r\n    	</div>\r\n    </div>\r\n</div>\r\n\r\n<!-- \r\n\r\n        Discharge status\r\n        \r\n-->\r\n<div class=\'row-fluid\'>\r\n    <div class=\"span10\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                Discharge\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"all_patient\">\r\n<%\r\n    nd = 0\r\n    if g_list.has_key? \'Discharge\'\r\n        nd = g_list[\'Discharge\'].count\r\n    end\r\n    if nd == 0\r\n%>\r\n<center>--- No Patient ---</center>\r\n<% else %>\r\n            <table class=\"table table-striped\">\r\n                <thead>\r\n                    <tr>\r\n                        <th>&nbsp;</th>\r\n                        <th>QN</th>\r\n                        <th>HN</th>\r\n                        <th>Name</th>\r\n                        <th>Age</th>\r\n                        <th>Procedure</th>\r\n                        <th>Provider</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n<%\r\n                        idx = s_list.index(\'Discharge\')\r\n                        g_list[\'Discharge\'].each do |i|\r\n%>\r\n                    <tr>\r\n                        <td><%= link_to \'<i class=\"splashy-arrow_state_blue_left\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{i[\'id\']}\',\'\\\\#{s_list[idx-1]}\',\'\')\", :class=>\'\' %></td>\r\n                        <td><%= i[\'qn\'] %></td>\r\n                        <td><%= i[\'hn\'] %></td>\r\n                        <td><%= i[\'full_name\'] %></td>\r\n                        <td><%= i[\'age\'] %></td>\r\n                        <td><%= i[\'procedure\'] %></td>\r\n                        <td><%= i[\'provider\'] %></td>\r\n                    </tr>\r\n<%\r\n                        end\r\n%>\r\n                </tbody>\r\n            </table>\r\n<% end %>\r\n    	</div>\r\n    </div>\r\n    <div class=\"span2\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                Total\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"all_patient\">\r\n    	    <div class=\"alert alert-block alert-success\">\r\n    	        <center><h1><%= nd %> </h1></center>\r\n    	    </div>\r\n    	</div>\r\n    </div>\r\n</div>\r\n\r\n',NULL,NULL,NULL,'2016-10-17 14:35:59','2016-10-17 14:35:59','nurse_index_partial',''),(2646,'case_index_partial',1063,3,'<%\r\n    @module_name = @current_project.name+\'#appointment\' \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n  \r\n    @models = get_model\r\n    \r\n    date = Time.now.strftime(\"%d/%m/%Y\")\r\n    if params[:date]\r\n        date = params[:date]\r\n    end\r\n    date = Date.to_mongo(params[:date])\r\n    \r\n    \r\n    a_app = @models[:appointment].where(:date=>date).all\r\n    \r\n    vst = {\'-\'=>\'Undefined\'}\r\n    pro = {}\r\n    rec = {}\r\n    pat = {}\r\n    prov = {}\r\n    \r\n    @models[:visit_type].all.each do |i|\r\n        vst[i.id.to_s] = i.name\r\n    end\r\n    \r\n    @models[:procedure].all.each do |i|\r\n        pro[i.id.to_s] = i.name\r\n    end\r\n    \r\n    @models[:provider].all.each do |i|\r\n        prov[i.id.to_s] = i\r\n    end\r\n    \r\n    @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>a_app.collect{|i| i.id }}).all.each do |i|\r\n        rec[i.module_id]=i\r\n    end\r\n \r\n    @patient_model.find(rec.values.collect{|i| i.patient_id}).each do |i|\r\n        pat[i.id]=i\r\n    end\r\n    \r\n    \r\n    res = a_app.collect{|ap| \r\n        i  = rec[ap.id]\r\n        p = pat[i.patient_id]\r\n        if p.nil?\r\n            next\r\n        end\r\n        provider = prov[ap.provider.to_s]\r\n        l = %w{#bcdeee}\r\n        age = \'-\'\r\n        if p.birth_date\r\n            diff = Time.diff(date, p.birth_date)\r\n            year = diff[:year]\r\n            month = diff[:month]\r\n            day = diff[:day]\r\n            age = \"\\\\#{year}\"\r\n        end\r\n        # indication=\"-\"\r\n        # visit_type=\"-\"\r\n \r\n        # indication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n        # visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n \r\n        # if  ap.status==\'Waiting\' or  ap.status==\'Processing\' or ap.status==\'Recovery\' or  (ap.status==\'Completed\' and ( Time.now - ap.updated_at ) < 300)\r\n            apdate = \'\'\r\n            apdate = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n            starttime = \'\'\r\n            stoptime = \'\'\r\n            starttime = ap.start.strftime(\" %H:%M\") if ap.start\r\n            stoptime = ap.stop.strftime(\" %H:%M\") if ap.stop\r\n            room = ap.room==\'\' ? \'-\' : ap.room\r\n            if ap.status == \'Recovery\'\r\n                room = \'R\'\r\n            elsif ap.status == \'Preparing\'\r\n                room = \'P\'\r\n            end\r\n            vs = \'-\'\r\n            if ap.visit_type != \'\' and !ap.visit_type.nil?\r\n                vs = ap.visit_type\r\n            end\r\n            {\r\n                \'id\'=>ap.id,\r\n                \'status\'=>ap.status ,\r\n                \'record\'=>i.id,\r\n                \'hn\'=> p.hn,\r\n                \'updated_at\'=>ap.updated_at,\r\n                \'procedure\'=>pro[ap.procedure.to_s],\r\n                \'date\'=>apdate,\r\n                \'color\'=>l[rand(4%l.size)],\r\n                \'provider\'=>\"\\\\#{provider.name if provider} \" ,\r\n                \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p }\",\r\n                \'full_name\'=>\"\\\\#{p.prefix_name if p }\\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n                \'start\'=>apdate+starttime,\r\n                \'end\'=>apdate+stoptime,\r\n                # \'indication\'=>indication,\r\n                \'allDay\'=>false,\r\n                \'url\'=>\'edit?id=\'+i.id.to_s,\r\n                \'age\'=>age,\r\n                # \'visit_type\'=>visit_type,\r\n                \'public_id\'=>p.public_id,\r\n                \'room\'=>room,\r\n                \'qn\'=>ap[:qn],\r\n                \'visit_type\'=>vst[vs.to_s]\r\n            }  \r\n        # else\r\n        #     nil\r\n        # end \r\n    }.compact\r\n    # sort data by date\r\n    list = res.sort{|a,b| b[\'updated_at\']<=>a[\'updated_at\']}\r\n    \r\n    v_list = list.group_by{|i| i[\'visit_type\']}\r\n    g_list = list.group_by{|i| i[\'status\']}\r\n    c_list = list.group_by{|i| i[\'procedure\']}\r\n    \r\n    s_list = %w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n    \r\n    nc = g_list[\'Completed\'].nil? ? 0 : g_list[\'Completed\'].count\r\n    n_can = g_list[\'Cancelled\'].nil? ? 0 : g_list[\'Cancelled\'].count\r\n    \r\n    k_vs = v_list.keys.sort\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span10\'>\r\n        <div class=\'alert alert-info\'  style=\'position:fixed;\'>\r\n            <b>Go to section : </b>\r\n<%\r\n    k_vs.each do |i|\r\n%>\r\n<span style=\'margin-right:10px;margin-left:10px\'><%= link_to \"\\\\#{i}\", \"#section-\\\\#{i.downcase}\", :class=>\'btn btn-info\' %></span>\r\n<%\r\n    end\r\n%>\r\n        </div>\r\n    </div>\r\n    <div class=\'span2\'>\r\n        <div class=\'alert alert-success\' style=\'position:fixed;float:right\'>\r\n            <b>Go to : </b><%= link_to \'Nurse Index\', \"nurse_index?date=\\\\#{date.strftime(\'%d/%m/%Y\')}\", :class=>\'btn btn-success\' %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\'row-fluid\' style=\'margin-top:20px\'></div>\r\n<!-- each visit_type : display -->\r\n<%\r\n    \r\n    k_vs.each do |vs|\r\n        l_vs = v_list[vs]\r\n        p_vs = l_vs.group_by{|i| i[\'procedure\']}\r\n        s_vs = l_vs.group_by{|i| i[\'status\']}\r\n        fin  = 0\r\n        if s_vs.has_key? \'Completed\'\r\n            fin += s_vs[\'Completed\'].count\r\n        end\r\n        if s_vs.has_key? \'Discharge\'\r\n            fin += s_vs[\'Discharge\'].count\r\n        end\r\n%>\r\n<div class=\'clear\'></div>\r\n<div id=\'section-<%= vs.downcase %>\' style=\'margin-top:50px\'></div>\r\n\r\n<div class=\'row-fluid\'>\r\n    <div class=\"span10\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\" id=\"header_<%= vs.downcase %>\">\r\n                <%= vs %>\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"today_case\">\r\n            <!--<div class=\'span8\'>-->\r\n                <table class=\"table table-bordered\">\r\n                    <thead>\r\n                        <tr>\r\n                            <th><center>Procedure</center></th>\r\n                            <% s_list.each do |i| %>\r\n                            <th><center><%= i %></center></th>\r\n                            <% end %>\r\n                        </tr>\r\n                    </thead>\r\n                    <tbody>\r\n                    <% \r\n                        kp = p_vs.keys.sort\r\n                        kp.each do |i| \r\n                    %>\r\n                        <tr>\r\n                            <td><%= i %></td>\r\n                    <%\r\n                        gr = p_vs[i].group_by{|i| i[\'status\']}\r\n                        s_list.each do |i|\r\n                            n = gr[i].nil? ? 0 : gr[i].count\r\n                    %>\r\n                            <td><center><%= n %></center></td>\r\n                    <% end %>\r\n                        </tr>\r\n                    <% end %>\r\n                    </tbody>\r\n                </table>\r\n            <!--</div>-->\r\n    	</div>\r\n    </div>\r\n    <div class=\"span2\">\r\n        <div class=\"w-box\">    \r\n            <div class=\"w-box-header\">\r\n                Completed / Appointed\r\n    	    </div>\r\n    	</div>\r\n    	<div class=\"w-box-content cnt_a\" id=\"all_patient\">\r\n    	    <div class=\"alert alert-block alert-success\">\r\n    	        <center><h1><%= fin %> / <%= l_vs.count %></h1></center>\r\n    	        <!--<center><b>Date : </b><%= date.strftime(\'%d/%m/%Y\') %> </center>-->\r\n    	        <center><%= link_to \'Refresh\', \'javascript:location.reload()\', :class=>\'btn btn-success\' %></center>\r\n    	    </div>\r\n    	</div>\r\n    </div>\r\n</div>\r\n<%\r\n    end\r\n%>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-10-17 14:36:20','2016-10-17 14:36:20','case_index_partial',''),(2647,'patient_board_partial',1063,3,'<%\r\n  \r\n    @module_name = @current_project.name+\'#appointment\' \r\n    @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @patient_doc = @ehr_project.get_document \'patient\'\r\n    @module_doc = @ehr_project.get_document \'patient_module\'\r\n    @ehr_model = @ehr_project.get_model()\r\n    @patient_model = @ehr_model[:patient]\r\n    @module_model = @ehr_model[:patient_module]\r\n  \r\n    @models = get_model\r\n  \r\n    if this.table_name!=\'appointment\' and params[:parent_id] \r\n        @appointment_module = @module_model.find(params[:parent_id])\r\n        if @appointment_module\r\n            @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n        end\r\n    end \r\n  \r\n    if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n        @patient = @patient_model.find(@patient_module.patient_id)\r\n    end\r\n\r\n    p_date = Time.now\r\n    if params[:date]\r\n        p_date = params[:date]\r\n    end\r\n        date = Date.to_mongo(p_date)\r\n     \r\n        appointments =   @models[:appointment].where(:date=>date).all\r\n     \r\n     \r\n        records = {}\r\n        patients = {}\r\n        providers = {}\r\n        indications= {}\r\n        visit_types= {}\r\n    \r\n    \r\n        @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n            records[i.module_id]=i\r\n        end\r\n     \r\n        @patient_model.find(records.values.collect{|i| i.patient_id}).each do |i|\r\n            patients[i.id]=i\r\n        end\r\n    \r\n        @models[:visit_type].all.each do |i|\r\n            visit_types[i.id.to_s] = i\r\n        end\r\n     \r\n        @models[:provider].all.each do |i|\r\n            providers[i.id.to_s] = i\r\n        end\r\n        @models[:indication].all.each do |i|\r\n            indications[i.id.to_s] = i\r\n        end\r\n     \r\n        pro = {}\r\n        @models[:procedure].all.each do |i|\r\n            pro[i.id] = i.name\r\n        end\r\n        \r\n        \r\n    \r\n        \r\n        json_data =   appointments.collect{|ap| \r\n            i  = records[ap.id]\r\n            p = patients[i.patient_id]\r\n            provider = providers[ap.provider.to_s]\r\n            l = %w{#bcdeee}\r\n            age = \'-\'\r\n            if p.birth_date\r\n                diff = Time.diff(date, p.birth_date)\r\n                year = diff[:year]\r\n                month = diff[:month]\r\n                day = diff[:day]\r\n                age = \"\\#{year} Y\"\r\n            end\r\n            indication=\"-\"\r\n            visit_type=\"-\"\r\n     \r\n            indication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n            visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n     \r\n     \r\n            # if  ap.status==\'Processing\' or ap.status==\'Recovery\' or ap.status==\'Preparing\' or ap.status==\'Completed\'\r\n                apdate = \'\'\r\n                apdate = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n                starttime = \'\'\r\n                stoptime = \'\'\r\n                starttime = ap.start.strftime(\" %H:%M\") if ap.start\r\n                stoptime = ap.stop.strftime(\" %H:%M\") if ap.stop\r\n                room = ap.room==\'\' ? \'-\' : ap.room\r\n                # if ap.status == \'Recovery\'\r\n                #     room = \'R\'\r\n                # end\r\n                qn = \'\'\r\n                if !ap[:qn].nil?\r\n                    qn = ap[:qn]\r\n                end\r\n                prov = \"อ.\\#{provider.name.split(\' \')[0] if provider}\"\r\n                if provider\r\n                    if provider.name.index(\'.\')\r\n                        prov = provider.name\r\n                    end\r\n                end\r\n                {\r\n                    :id=>ap.id,\r\n                    :status=>ap.status ,\r\n                    :record=>i.id,\r\n                    :hn=> p.hn,\r\n                    :updated_at=>ap.updated_at,\r\n                    :procedure=>pro[ap.procedure],\r\n                    :date=>apdate,\r\n                    :color=>l[rand(4%l.size)],\r\n                    :provider=>\"\\#{provider.name if provider} \" ,\r\n                    :title=>\"\\#{p.prefix_name if p } \\#{p.first_name if p }\",\r\n                    :first_name=>\"\\#{p.first_name if p }\",\r\n                    :last_name=>\"\\#{p.last_name if p }\",\r\n                    :full_name=>\"\\#{p.prefix_name if p } \\#{p.first_name if p }   \\#{p.last_name if p}\",\r\n                    :gender=>\"\\#{p.gender if p }\",\r\n                    :start=>apdate+starttime,\r\n                    :end=>apdate+stoptime,\r\n                    :indication=>indication,\r\n                    :age=>age,\r\n                    :public_id=>p.public_id,\r\n                    :room=>room,\r\n                    :ward=>ap.ward,\r\n                    :note=>ap.note,\r\n                    :prov=>\"อ.\\#{provider.name.split(\' \')[0] if provider}\",\r\n                    :hn=>\"\\#{p.first_name if p} \\#{p.last_name[0]}.\",\r\n                    :qn=>qn\r\n                }  \r\n            # else\r\n            #     nil\r\n            # end \r\n        }.compact\r\n    \r\n        # sort data by date\r\n        # list = json_data.sort{|a,b| b[\'updated_at\']<=>a[\'updated_at\']}\r\n    \r\n        # p_list = list.group_by{|i| i[\'procedure\']}\r\n        \r\n        # sort data by procedure\r\n        list = json_data.sort{|a,b| b[:procedure]<=>a[:procedure]}.reverse\r\n\r\n        p_list = list.group_by{|i| i[:procedure]}\r\n        c_list = []\r\n        \r\n        p_list.each_pair do |k, v|\r\n            tmp = {}\r\n            tmp[:proc] = k\r\n            tmp[:count] = v.count\r\n            c_list << tmp\r\n        end\r\n        # c_list = c_list.sort_by{|i| i[:count]}.reverse\r\n        c_list = c_list.sort_by{|i| [i[:proc],i[:count]]}\r\n\r\n        content = []\r\n        c_list.each do |i|\r\n            pr = i[:proc]\r\n            tmp = p_list[pr]\r\n            res = {:type=>\'head\', :body=>pr, :count=>i[:count]}\r\n            content << res\r\n            tmp.each do |j|\r\n                res = {:type=>\'cont\', :body=>j}\r\n                content << res\r\n            end\r\n        end\r\n        \r\n        s_list = %w{appointed waiting arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.to_s}\r\n        \r\n        mx = 11 \r\n        pg = (content.size / (mx*2.0)).ceil\r\n%>\r\n\r\n<%\r\nno = 1\r\n1.upto(pg) do |page|    \r\n%>\r\n\r\n<div id=\'page-<%=page%>\' style=\'display:block\'>\r\n<!-- Left Table <%= page %>-->\r\n<table class=\"tg\" style=\"undefined;table-layout: fixed; width: 49%; float:left;\">\r\n  <colgroup>\r\n    <col style=\"width: 10%\">\r\n    <col style=\"width: 25%\">\r\n    <col style=\"width: 25%\">\r\n    <col style=\"width: 15%\">\r\n    <col style=\"width: 10%\">\r\n    <col style=\"width: 15%\">\r\n  </colgroup>\r\n  <tr>\r\n    <th class=\"tg-eo60\">No.</th>\r\n    <th class=\"tg-eo60\">Name</th>\r\n    <th class=\"tg-eo60\">Provider</th>\r\n    <th class=\"tg-eo60\">Ward</th>\r\n    <th class=\"tg-eo60\">Room</th>\r\n    <th class=\"tg-eo60\">Status</th>\r\n  </tr>\r\n<%\r\n    # content.each do |i|\r\n    start = ((page - 1) * (mx * 2)) + 1\r\n    stop  = ((page - 1) * (mx * 2)) + mx\r\n    (start - 1).upto(stop - 1) do |n|\r\n        if n < content.size\r\n            i = content[n]\r\n            if i[:type] == \'head\'\r\n                no = 1\r\n%>\r\n  <tr>\r\n    <td class=\"tg-7dwi\" colspan=\"6\" style=\'text-align:left;margin-left:20px\'><%= i[:body] %> ( <%= i[:count] %> ) </td>\r\n  </tr>  \r\n<%      \r\n            else \r\n                x = i[:body]\r\n                name = \"\\#{x[:first_name]} \\#{x[:last_name][0]}.\"\r\n                prov = (x[:provider].nil? or x[:provider] == \'\') ? \'-\' : x[:provider].split(\' \')[0]\r\n                if !prov.index(\'.\')\r\n                    prov = \"อ.\\#{prov}\"\r\n                end\r\n                room = x[:room]\r\n                ward = x[:ward].nil? ? \'OPD\' : x[:ward]\r\n                status = x[:status].downcase\r\n                blink = (s_list.index(status) and s_list.index(status) >= 1 and s_list.index(status) <= 5) ? \'blink\' : \'\'\r\n                note = (x[:note].nil? or x[:note]==\'\') ? \'\' : \"<br/><span style=\'font-size:0.5em;display: block;font-weight: bold;text-align: left;\'>Note: \\#{x[:note]}</span>\".html_safe \r\n%> \r\n  <tr>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= no %>.</td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= name %> <%= note %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= prov %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= ward %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= room %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><div class=\' status-<%= status %>\'><font size=\'2em\' class=\'<%= blink %>\'><%= status.humanize %></font></div></td>\r\n  </tr>\r\n<%\r\n                no += 1\r\n            end\r\n        else\r\n%>\r\n  <tr>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n  </tr>\r\n<%\r\n        end\r\n    end\r\n%>\r\n</table> \r\n\r\n\r\n\r\n<!-- Right Table <%= page %>-->\r\n<table class=\"tg\" style=\"undefined;table-layout: fixed; width: 49%; float:right;\">\r\n  <colgroup>\r\n    <col style=\"width: 10%\">\r\n    <col style=\"width: 25%\">\r\n    <col style=\"width: 25%\">\r\n    <col style=\"width: 15%\">\r\n    <col style=\"width: 10%\">\r\n    <col style=\"width: 15%\">\r\n  </colgroup>\r\n  <tr>\r\n    <th class=\"tg-eo60\">No.</th>\r\n    <th class=\"tg-eo60\">Name</th>\r\n    <th class=\"tg-eo60\">Provider</th>\r\n    <th class=\"tg-eo60\">Ward</th>\r\n    <th class=\"tg-eo60\">Room</th>\r\n    <th class=\"tg-eo60\">Status</th>\r\n  </tr>\r\n<%\r\n    start = ((page - 1) * (mx * 2)) + 1 + mx\r\n    stop  = ((page - 1) * (mx * 2)) + (2 * mx)\r\n    # content.each do |i|\r\n    (start - 1).upto(stop - 1) do |n|\r\n        if n < content.size\r\n            i = content[n]\r\n            if i[:type] == \'head\'\r\n                no = 1\r\n%>\r\n  <tr>\r\n    <td class=\"tg-7dwi\" colspan=\"6\" style=\'text-align:left;margin-left:20px\'><%= i[:body] %> ( <%= i[:count] %> ) </td>\r\n  </tr>  \r\n<%      \r\n            else \r\n                x = i[:body]\r\n                name = \"\\#{x[:first_name]} \\#{x[:last_name][0]}.\"\r\n                prov = (x[:provider].nil? or x[:provider] == \'\') ? \'-\' : x[:provider].split(\' \')[0]\r\n                if !prov.index(\'.\')\r\n                    prov = \"อ.\\#{prov}\"\r\n                end\r\n                room = x[:room]\r\n                ward = x[:ward].nil? ? \'OPD\' : x[:ward]\r\n                status = x[:status].downcase\r\n                blink = (s_list.index(status) and s_list.index(status) >= 1 and s_list.index(status) <= 5) ? \'blink\' : \'\'\r\n                note = (x[:note].nil? or x[:note]==\'\') ? \'\' : \"<br/><span style=\'font-size:0.5em;display: block;font-weight: bold;text-align: left;\'>Note: \\#{x[:note]}</span>\".html_safe \r\n%> \r\n  <tr>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= no %>.</td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= name %> <%= note %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= prov %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= ward %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><%= room %></td>\r\n    <td class=\"tg-skti tg-<%=status%>\"><div class=\'status-<%= status.downcase %>\'><font size=\'2em\'  class=\'<%= blink %>\'><%= status.humanize %></font></div></td>\r\n  </tr>\r\n<%\r\n                no += 1\r\n            end\r\n        else\r\n%>\r\n  <tr>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n    <td class=\"tg-skti\">&nbsp;</td>\r\n  </tr>\r\n<%\r\n        end\r\n    end\r\n%>\r\n</table>  \r\n\r\n</div>\r\n\r\n<% end # page %>\r\n<%# content.to_json.html_safe %>\r\n\r\n\r\n<script>\r\n    function hidden_page() {\r\n<%\r\n        1.upto(pg) do |i|\r\n            if i > 1\r\n%>\r\n        $(\'#page-<%=i%>\').hide();\r\n<%\r\n            end\r\n        end\r\n%>\r\n    }\r\n    \r\n    var cur_page = 0;\r\n    var all_page = <%= pg %>;\r\n    var t_out = 10000;\r\n    var page_obj;\r\n    function change_page(from_page, to_page) {\r\n        // $(from_page).fadeOut(500);\r\n        $(from_page).hide();\r\n        $(to_page).fadeIn(500);\r\n        console.log(\'... \'+from_page+\' - \' + to_page)\r\n    }\r\n    function execute_change_page() {\r\n        nex_page = cur_page + 1\r\n        f_page = \"#page-\" + cur_page;\r\n        t_page = \"#page-\" + nex_page;\r\n        if (nex_page > all_page) {\r\n            nex_page = 1;\r\n            t_page = \"#page-\" + nex_page;\r\n        } \r\n        \r\n        change_page(f_page, t_page);\r\n        \r\n        cur_page = nex_page;\r\n        console.log(\'### cur_page (\' + cur_page + \") - nex_page (\" + nex_page + \") : ALL = \" + all_page);\r\n        clearTimeout(page_obj);\r\n        page_obj = setTimeout(execute_change_page, t_out);\r\n    }\r\n    \r\n    var element = $(\".blink\");\r\n    var shown = true;\r\n    clearInterval(interval_obj);\r\n    interval_obj = setInterval(toggle, 1000);\r\n    \r\n    // function toggle() {\r\n    //     if(shown) {\r\n    //         // element.hide();\r\n    //         element.fadeOut(\"slow\");\r\n    //         shown = false;\r\n    //     } else {\r\n    //         element.show();\r\n    //         shown = true;\r\n    //     }\r\n    // }\r\n    \r\n    $(document).ready(function() {\r\n        hidden_page();\r\n        \r\n<% \r\n        if pg > 1\r\n%>\r\n        execute_change_page();\r\n<%\r\n        end\r\n%>\r\n        \r\n        $(\".se-pre-con\").fadeOut(\"slow\");\r\n    })\r\n\r\n    \r\n</script>',NULL,NULL,NULL,'2016-10-17 14:37:40','2016-10-17 14:37:40','patient_board_partial','*'),(2648,'create',1059,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n        p = params[:record]\r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            params[:record][:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                params[:record][:birth_date] = new_date\r\n            end \r\n        end\r\n        \r\n    \r\n     if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n    \r\n    rec1 = model.where(:hn=>params[:record][:hn]).first\r\n    # rec2 = model.where(:public_id=>params[:record][:public_id]).first\r\n    # if rec1!=nil or rec2 != nil\r\n    if rec1!=nil\r\n        # return_url = \"\\#{return_url}&patient_id=\\#{rec1.id}\"\r\n    %>\r\n    \r\n<span style=\"color:red\"><b>Existing HN or Public ID</b></span><br/>\r\nWill be redirect in 3 seconds\r\n<meta http-equiv=\"Refresh\" content=\"3; url=<%= return_url.html_safe %>\">\r\n    <%\r\n    else\r\n    \r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n   \r\n\r\n    return_url += \"obj_id=\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n    end\r\n\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-10-17 15:22:06','2016-10-17 15:22:06','create',''),(2649,'search_result',1059,3,'<% \r\n\r\nrequire \'time_diff\'\r\n\r\n    models = get_model  \r\n\r\n    @document = get_document(this.document_name)\r\n    model = models[:patient]\r\n    att_model = models[:attachment]\r\n    patient = model.find(params[:id])\r\n    date = Time.now.to_datetime\r\n    if patient \r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    diff = Time.diff(date, birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    \r\n    #year = (t/365).to_i\r\n    #t%=365\r\n    #month = (t/30).to_i\r\n	#t%=30\r\n	#day = t.to_i\r\n    end\r\n%>\r\n<style>\r\nv{color:#00f}\r\n</style>\r\n<div class=\"alert alert-block alert-success\">\r\n<div class=\"btn left\" style=\"height:100px;width:100px\">\r\n<%\r\nif patient.picture and patient.picture.size>0 \r\n pic = att_model.find(patient.picture[-1])\r\n if pic \r\n%>\r\n<%=image_tag \"\\\\#{pic.path}?thumb=1\",:height=>100 %>\r\n<% end \r\nend %>\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px;float:left\">\r\n<p>\r\n<b> Patient : </b><v><%= patient.prefix_name %>  <%= patient.first_name %> <%= patient.last_name %></v>\r\n</p>\r\n<p>\r\n<b> Age : </b><v><%= year%> Years <!-- <%=month%> Months <%= day%> Days --></v>\r\n</p>\r\n</div>\r\n\r\n<div class=\"left\" style=\"padding:20px:float:left\">\r\n<br/>\r\n<p>\r\n<b> HN : </b><v> <%= patient.hn %></v>\r\n</p>\r\n<p>\r\n<!--<b> เลขบัตรประจำตัวประชาชน : </b><v><%=patient.public_id%> </v>-->\r\n</p>\r\n</div>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\npatient = <%= patient.to_json.html_safe %>;\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2016-10-17 15:24:11','2016-10-17 15:24:11','search_result',''),(2650,'context_menu',591,4,'<%\r\n    models = get_model\r\n\r\n    providers = (models[:provider]).all :provider_type=>\'1\'\r\n\r\n    #providers_links = providers.collect{|i| {:name=>\"<span style=\'background:\\\\#{i.label}\'>\\\\#{i.name}</span>\",:link=>\'index?provider_id=\'+i.id} }\r\n    providers_select = providers.collect{|i| {:name=>i.name, :link=>\"javascript:prov_select(\'\\\\#{i.id.to_s}\')\"} }\r\n    providers_links = providers.collect{|i| {:name=>i.name,:link=>\'index?provider_id=\'+i.id.to_s} }\r\n    providers_links << {:name=>\"All Providers\",:link=>\'index\'} \r\n    providers_links << {:name=>\"All Detail\",:link=>\'index?detail=true\'} \r\n    menus = [\r\n        {:name=>\'Provider Select\',:open=>true,:actions=>providers_select},\r\n        {:name=>\'Provider Schedule\',:open=>true,:actions=>providers_links},\r\n\r\n        {:name=>\'Links\',:open=>true,:actions=>[\r\n            {:name=>\'New Appointment\',:service=>\'pathology\',:link=>\'create\'}\r\n        ]}\r\n    ]\r\n%>\r\n<%= show_menu(menus).html_safe %>\r\n<script>\r\n    function prov_select(id) {\r\n        $(\'#data-provider\').val(id);\r\n        $(\'#data-provider\').effect(\"highlight\", {}, 1000);\r\n    }\r\n    \r\n    $(\'#collapse-1\').collapse(\'hide\');\r\n</script>',NULL,NULL,NULL,'2016-10-17 16:11:43','2016-10-17 16:11:43','context_menu',''),(2651,'form',798,3,'<script>\r\nfunction inject(fid){\r\n\r\n\r\n    $(document).ready(function(){\r\n        \r\n        \r\n    $(\'#\'+fid+\'endoscopy_dx\').change(function(){\r\n      var str = $(this).find(\":selected\").val()\r\n \r\n      \r\n      switch (str) {\r\n      case \'Adenomatous polyp\':\r\n          fill(fid,1)\r\n      break;\r\n      case \'Hyperplastic polyp\':\r\n          fill(fid,2)\r\n      break;\r\n      case \'Sessile Serrated Adenoma\':\r\n          fill(fid,3)\r\n      break;\r\n      }\r\n\r\n    });\r\n\r\n    \r\n    \r\n    \r\nfunction fill(fid,number){\r\n    \r\n    \r\n    kudo_type = $(\'#data-\'+fid+\'kudo_type\')\r\n    sano_type = $(\'#data-\'+fid+\'sano_type\')\r\n    nice_classification = $(\'#data-\'+fid+\'nice_classification\')\r\n    jnet_class = $(\'#data-\'+fid+\'jnet_class\')\r\n    \r\n    treatment = $(\'#data-\'+fid+\'treatment\')\r\n    treatment_by = $(\'#data-\'+fid+\'treatment_by\')\r\n    clip = $(\'#data-\'+fid+\'clip\')\r\n    \r\n    \r\n    \r\n    // treatment Total removed\r\n    // treatment_by EMR\r\n    // clip    Done\r\n    \r\n    treatment.val(\'Total removed\')\r\n    treatment_by.val(\'EMR\')\r\n    clip.val(\'Done\')\r\n    \r\n    \r\n    \r\n    // alert(\"\"+fid+\"\"+number+kudo_type.val())\r\n    switch(number){\r\n        case 1:\r\n           kudo_type.val(\'IIIs\')\r\n           sano_type.val(\'II\')\r\n           nice_classification.val(\'II\')\r\n           jnet_class.val(\'2a\')\r\n        break;\r\n        case 2:\r\n           kudo_type.val(\'II\')\r\n           sano_type.val(\'I\')\r\n           nice_classification.val(\'I\')\r\n           jnet_class.val(\'1\')\r\n        break;\r\n        case 3:\r\n           kudo_type.val(\'II\')\r\n           sano_type.val(\'II\')\r\n           nice_classification.val(\'I serrated\')\r\n           jnet_class.val(\'2a\')\r\n        break;\r\n            \r\n    }\r\n    \r\n    update_treatment()\r\n    \r\n    \r\n}\r\n    \r\n    function update_treatment(){\r\n        \r\n        var all_treatment = [];\r\n        \r\n        $(\'.treatment_by\').each(function(){\r\n            \r\n        \r\n        var str = $(this).find(\":selected\").val()\r\n        var s  = \'\'\r\n        if(str==\'Cold polypectomy\'||str==\'Hot polypectomy\')s = \'Polypectomy\'\r\n        if(str==\'Cold biopsy\'||str==\'Hot biopsy\')s = \'Bx\'\r\n        if(str==\'EMR\'||str==\'EMR-C\')s = \'EMR\'\r\n        if(str==\'ESD\'){\r\n            s = \'ESD\'\r\n        \r\n              $(\'#data-project\').val(\'ESD\');\r\n                update_project_rev_func();\r\n            \r\n        }\r\n        if(str==\'APC\')s = \'APC\'\r\n        if(str==\'Coagulation\')s = \'Cauterized bleeding\'\r\n        if(str==\'EPMR\')s = \'EPMR\'\r\n        if(str==\'Precut EMR\')s = \'Precut EMR\'\r\n        \r\n        // alert(s)\r\n           \r\n        all_treatment.push(s);    \r\n            \r\n        })\r\n        \r\n        \r\n         $(\'.tattoo\').each(function(){\r\n            \r\n        \r\n        var str = $(this).find(\":selected\").val()\r\n        var s = \'\'\r\n        if(str==\'Done\')s = \'Tattoo\'\r\n        \r\n        // alert(s)\r\n           \r\n        all_treatment.push(s);    \r\n            \r\n        })\r\n        \r\n        \r\n        \r\n        all_treatment = jQuery.unique(all_treatment);\r\n        // alert(all_treatment)\r\n        \r\n        $(\'#data-procedure\').val(all_treatment.join(\"|\"));\r\n        \r\n        update_procedure_rev_func();\r\n        \r\n        \r\n    }\r\n    \r\n    \r\n    proc =  $(\'#data-\'+fid+\'treatment_by\');\r\n    proc.addClass(\'treatment_by\');\r\n    proc.change(function(){\r\n        update_treatment()   \r\n    });\r\n    \r\n    \r\n    proc =  $(\'#data-\'+fid+\'tattoo\');\r\n    proc.addClass(\'tattoo\');\r\n\r\n\r\n\r\n    \r\n    $(\'#data-\'+fid+\'tattoo\').change(function(){\r\n           update_treatment()   \r\n    });\r\n    \r\n    });\r\n    \r\n}\r\n\r\n\r\n</script>\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   \r\n  \r\n%>\r\n<%\r\n    if @current_role==\'capture\' or @current_role==\'developer\'\r\n%>\r\n    <div class=\"alert\">\r\n		<!--<h4 class=\"alert-heading\">Endo Button</h4>-->\r\n		<div style=\'float:left\' id=\'btn-form\'>&nbsp;</div>\r\n		<div style=\'float:right\' id=\'btn-snap\'>&nbsp;</div>\r\n		<br/>\r\n		&nbsp;\r\n	</div>\r\n<%\r\n    end\r\n%>\r\n<div id=\'prescope\' >Loading..PreScope information</div>\r\n<script>\r\n\r\n<%\r\n\r\n url = \"../PreScope/pre_scope_detail?id=\\\\#{params[:id]}\"\r\n url = \"../PreScope/pre_scope_detail?parent_id=\\\\#{params[:parent_id]}\" if params[:parent_id]\r\n \r\n%>\r\n\r\n$.ajax({\r\n  url: \"<%=url%>\",\r\n  context: document.body\r\n}).done(function(data) { \r\n  $(\'#prescope\').html(data);\r\n <% unless params[:id] %>\r\n $(\'#data-bowel_preparation\').val(pre_scope[\"bowel_preparation\"]);\r\n $(\'#data-additional_bowel_preparation\').val(pre_scope[\"add_bowel_prep\"]);\r\n\r\n $(\'#data-bowel_cc\').val(pre_scope[\"bowelprep_cc\"]);\r\n $(\'#data-bowel_other\').val(pre_scope[\"bowel_other_note\"]);\r\n $(\'#data-add_bowel_prep_cc\').val(pre_scope[\"add_bowel_prep_cc\"]);\r\n $(\'#data-add_bowel_prep_other\').val(pre_scope[\"add_bowel_other\"]);\r\n \r\n <% end %> \r\n\r\n});\r\n</script>\r\n\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n\r\n//  add snap button on the top\r\n    $(document).ready(function() {\r\n<%\r\n    if (@current_role==\'capture\' or @current_role==\'developer\')\r\n        if params[:opt] == \'create\' or params[:opt] == \'edit\'\r\n%>\r\n        frm_submit = $(\'#record-submit\').clone();\r\n        frm_cancel = $(\'#record-submit\').next().clone();\r\n        frm_cancel = frm_cancel.addClass(\'btn btn-small\')\r\n        frm_submit = frm_submit.addClass(\'btn btn-success btn-small\')\r\n        \r\n        btn_form = $(\'#btn-form\');\r\n        btn_form.append(frm_submit);\r\n        btn_form.append(\'&nbsp;&nbsp;|&nbsp;&nbsp;\');\r\n        btn_form.append(frm_cancel);\r\n        \r\n        // $(\'#record-submit\').click(function() {\r\n        //     if ($(\'#data-stop_at\').val() == \"\") {\r\n        //         d = new Date();\r\n        //         $(\'#data-stop_at\').val(d.getHours() + \":\" + d.getMinutes());\r\n        //     }\r\n        // });\r\n\r\n<%\r\n        end\r\n%>\r\n        snap = $( \"a:contains(\'Snap\')\" ).clone();\r\n        snap = snap.addClass(\'btn btn-small btn-info\');\r\n        btn_snap = $(\'#btn-snap\');\r\n        btn_snap.append(snap);\r\n        \r\n        $(\'input\').prop(\'required\', null);\r\n        $(\'select\').prop(\'required\', null);\r\n<%\r\n    end\r\n%>\r\n\r\n        \r\n\r\n    })\r\n\r\n$(\'#data-bowel_cc\').change(function() {\r\n            v = $(this).val();\r\n            if (v == \'\') {\r\n                $(this).val(\'0\');\r\n            }\r\n            // console.log(\'xxx : \' + v)\r\n        })\r\n\r\n$(\'#data-procedure\').bind(\"change\", function (){\r\n    \r\n    v = $(this).val()\r\n    if(v.indexOf(\'ESD\')>=0){\r\n        $(\'#data-project\').val(\'ESD\');\r\n         update_project_rev_func();\r\n    }\r\n    if(v.indexOf(\'Stent\')>=0){\r\n        $(\'#data-project\').val(\'Stent\');\r\n         update_project_rev_func();\r\n    }\r\n    if(v.indexOf(\'ESD\')>=0 && v.indexOf(\'Stent\')>=0){\r\n        $(\'#data-project\').val(\'Stent\');\r\n         update_project_rev_func();\r\n    }\r\n    \r\n    \r\n    \r\n     \r\n    \r\n});\r\n\r\n\r\nsedative = [\'dormicum\',\'pethidine\',\'diprivan\',\'valium\',\'buscopan\',\'plasil\',\'fentanyl\',\'other\']\r\nfunction check_sedative(ele){\r\n   check = ele.prop(\"checked\");\r\n   id = ele.prop(\"id\");\r\n   t = id.split(\'-\')[1];\r\n   if(check)\r\n   $(\".\"+t+\'\').css(\"display\",\"block\");\r\n   else\r\n   $(\".\"+t+\'\').css(\"display\",\"none\");\r\n}\r\n\r\nfor(i=0;i<sedative.length;i++){\r\n t = sedative[i];  \r\n ele = $(\'#data-\'+t);\r\nele.change(function(){\r\n    check_sedative($(this));\r\n});\r\n check_sedative(ele);\r\n}\r\n//$(\'#data-dormicum_mg\').val(323)\r\n//$(\'#data-dormicum_mg\').prop(\'disabled\', true);\r\n//$(\'#data-dormicum_num\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_mg\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_num\').prop(\'disabled\', true);\r\n\r\nvar scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\nfunction refresh(ele){\r\n    for(i=0;i<scope_list.length;i++){\r\n      $(\".\"+scope_list[i]).css(\"display\",\"none\");\r\n   }\r\n    index = $(ele).prop(\"selectedIndex\");\r\n   for(i=0;i<index;i++){\r\n       $(\".\"+scope_list[i]).css(\"display\",\"block\");\r\n   }\r\n}\r\n\r\nrefresh($(\'#data-scope\'));\r\n\r\n$(\"#data-scope\").change(function(){\r\nrefresh(this);\r\n});\r\n\r\n\r\n$(\".diag\").change(function(){\r\n    \r\n   e = $(\"#data-\"+this.id).val();\r\n   p = $(\"#data-patient_status\");\r\n   if(e==\"1\"){\r\n     $.sticky(\"Select Abnormal\", {autoclose : 5000, position: \"top-right\" });\r\n     p.val(\"Abnormal\");    \r\n   }\r\n});\r\n\r\n\r\n  \r\n\r\n$(\'#data-diagnosis_group\').bind(\"change\", function() {\r\n       v = $(this).val() \r\n    //   alert(v)\r\n       if(v!=\'Normal\'){\r\n           $(this).val(v.replace(\'Normal|\',\'\')) \r\n          $(\'#update_diagnosis_group_item_0\').attr(\'checked\', false);\r\n       }\r\n          v = $(this).val() \r\n        var $cbx = $(\"#data-diagnosis_note\").data(\"kendoComboBox\")\r\n        $cbx.value(v.replace(/\\\\|/g,\',\'))\r\n        if(v.indexOf(\'Serrated\')>=0){\r\n            $(\'#data-project\').val(\'Serrated polyp\');\r\n            update_project_rev_func();\r\n        }\r\n\r\n    //   $(\'#data-diagnosis_note\').kendoComboBox().value(\'oiwjfoiwejfoijwef\');\r\n       \r\n     \r\n     \r\n \r\n });\r\n \r\n\r\n</script>',NULL,NULL,NULL,'2016-10-18 04:12:43','2016-10-18 04:12:43','form',''),(2652,'form',799,3,'\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n  \r\n%>\r\n<%\r\n    if @current_role==\'capture\' or @current_role==\'developer\'\r\n%>\r\n    <div class=\"alert\">\r\n		<!--<h4 class=\"alert-heading\">Endo Button</h4>-->\r\n		<div style=\'float:left\' id=\'btn-form\'>&nbsp;</div>\r\n		<div style=\'float:right\' id=\'btn-snap\'>&nbsp;</div>\r\n		<br/>\r\n		&nbsp;\r\n	</div>\r\n<%\r\n    end\r\n%>\r\n<div id=\'prescope\' >Loading..PreScope information</div>\r\n<script>\r\n\r\n<%\r\n\r\n url = \"../PreScope/pre_scope_detail?id=\\\\#{params[:id]}\"\r\n url = \"../PreScope/pre_scope_detail?parent_id=\\\\#{params[:parent_id]}\" if params[:parent_id]\r\n \r\n%>\r\n\r\n$.ajax({\r\n  url: \"<%=url%>\",\r\n  context: document.body\r\n}).done(function(data) { \r\n  $(\'#prescope\').html(data);\r\n  var d = new Date(pre_scope[\"npo_since\"]+\"T\"+pre_scope[\"nop_at\"].split(\"T\")[1]);\r\n  var n =  new Date();\r\n  a = Math.round((n-d)/3600000);\r\n  $(\'#data-npotime\').val(a+7);\r\n  \r\n});\r\n</script>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n\r\n    $(document).ready(function() {\r\n<%\r\n    if (@current_role==\'capture\' or @current_role==\'developer\')\r\n        if params[:opt] == \'create\' or params[:opt] == \'edit\'\r\n%>\r\n        frm_submit = $(\'#record-submit\').clone();\r\n        frm_cancel = $(\'#record-submit\').next().clone();\r\n        frm_cancel = frm_cancel.addClass(\'btn btn-small\')\r\n        frm_submit = frm_submit.addClass(\'btn btn-success btn-small\')\r\n        \r\n        btn_form = $(\'#btn-form\');\r\n        btn_form.append(frm_submit);\r\n        btn_form.append(\'&nbsp;&nbsp;|&nbsp;&nbsp;\');\r\n        btn_form.append(frm_cancel);\r\n        \r\n        // frm_submit.click(function() {\r\n        //     if ($(\'#data-stop_at\').val() == \"\") {\r\n        //         d = new Date();\r\n        //         d_txt = d.getHours() + \":\" + d.getMinutes();\r\n        //         $(\'#data-stop_at\').val(d_txt);\r\n        //     }\r\n        // });\r\n\r\n<%\r\n        end\r\n%>\r\n        snap = $( \"a:contains(\'Snap\')\" ).clone();\r\n        snap = snap.addClass(\'btn btn-small btn-info\');\r\n        btn_snap = $(\'#btn-snap\');\r\n        btn_snap.append(snap);\r\n        \r\n        $(\'input\').prop(\'required\', null);\r\n        $(\'select\').prop(\'required\', null);\r\n<%\r\n    end\r\n%>\r\n    })\r\n\r\n\r\nsedative = [\'dormicum\',\'pethidine\',\'diprivan\',\'valium\',\'buscopan\',\'plasil\',\'fentanyl\',\'other\']\r\nfunction check_sedative(ele){\r\n   check = ele.prop(\"checked\");\r\n   id = ele.prop(\"id\");\r\n   t = id.split(\'-\')[1];\r\n   if(check)\r\n   $(\".\"+t+\'\').css(\"display\",\"block\");\r\n   else\r\n   $(\".\"+t+\'\').css(\"display\",\"none\");\r\n}\r\n\r\nfor(i=0;i<sedative.length;i++){\r\n t = sedative[i];  \r\n ele = $(\'#data-\'+t);\r\nele.change(function(){\r\n    check_sedative($(this));\r\n});\r\n check_sedative(ele);\r\n}\r\n//$(\'#data-dormicum_mg\').val(323)\r\n//$(\'#data-dormicum_mg\').prop(\'disabled\', true);\r\n//$(\'#data-dormicum_num\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_mg\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_num\').prop(\'disabled\', true);\r\n\r\n//1|Pharynx\r\n//2|Esophagus\r\n//3|EGJ\r\n//4|Fundus\r\n//5|Cardia\r\n//6|Body\r\n//7|Antrum\r\n//8|1st Duodenum\r\n//9|Sphincter of oddi\r\n//10|2nd Duodenum\r\n//11|3rd Duodenum\r\n//12|4th Duodenum\r\n//13|Proximal Jejunum\r\n//14|Distal Jejunum\r\n\r\nvar scope_list = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n\r\n\r\nfunction update(ele){\r\n   for(i=0;i<scope_list.length;i++){\r\n      $(\".\"+scope_list[i]).css(\"display\",\"none\");\r\n   }\r\n    index = $(ele).prop(\"selectedIndex\");\r\n   for(i=0;i<index;i++){\r\n       $(\".\"+scope_list[i]).css(\"display\",\"block\");\r\n   }\r\n}\r\n\r\nupdate($(\'#data-scope\'));\r\n\r\n$(\"#data-scope\").change(function(){\r\nupdate(this);\r\n});\r\n\r\n\r\n$(\".diag\").change(function(){\r\n    \r\n   e = $(\"#data-\"+this.id).val();\r\n   p = $(\"#data-patient_status\");\r\n   if(e==\"1\"){\r\n    $.sticky(\"Select Abnormal\", {autoclose : 5000, position: \"top-right\" });\r\n     p.val(\"Abnormal\");    \r\n   }\r\n});\r\n\r\n\r\n\r\n$(\'#data-diagnosis_group\').bind(\"change\", function() {\r\n       v = $(this).val() \r\n    //   alert(v)\r\n       if(v!=\'Normal\'){\r\n           $(this).val(v.replace(\'Normal|\',\'\')) \r\n          $(\'#update_diagnosis_group_item_0\').attr(\'checked\', false);\r\n       }\r\n       \r\n        v = $(this).val() \r\n        var $cbx = $(\"#data-diagnosis_note\").data(\"kendoComboBox\")\r\n        $cbx.value(v.replace(/\\\\|/g,\',\'))\r\n     \r\n \r\n });\r\n \r\n     \r\n\r\n</script>',NULL,NULL,NULL,'2016-10-18 04:13:25','2016-10-18 04:13:25','form',''),(2653,'create',800,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if false and  locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%\r\n    if @current_role==\'capture\' or @current_role==\'developer\'\r\n%>\r\n    <div class=\"alert\">\r\n		<!--<h4 class=\"alert-heading\">Endo Button</h4>-->\r\n		<div style=\'float:left\' id=\'btn-form\'>&nbsp;</div>\r\n		<div style=\'float:right\' id=\'btn-snap\'>&nbsp;</div>\r\n		<br/>\r\n		&nbsp;\r\n	</div>\r\n<%\r\n    end\r\n%>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n    $(document).ready(function() {\r\n<%\r\n    if (@current_role==\'capture\' or @current_role==\'developer\')\r\n        if params[:opt] == \'create\' or params[:opt] == \'edit\'\r\n%>\r\n        frm_submit = $(\'#record-submit\').clone();\r\n        frm_cancel = $(\'#record-submit\').next().clone();\r\n        frm_cancel = frm_cancel.addClass(\'btn btn-small\')\r\n        frm_submit = frm_submit.addClass(\'btn btn-success btn-small\')\r\n        \r\n        btn_form = $(\'#btn-form\');\r\n        btn_form.append(frm_submit);\r\n        btn_form.append(\'&nbsp;&nbsp;|&nbsp;&nbsp;\');\r\n        btn_form.append(frm_cancel);\r\n        \r\n        // frm_submit.click(function() {\r\n        //     if ($(\'#data-stop_at\').val() == \"\") {\r\n        //         d = new Date();\r\n        //         d_txt = d.getHours() + \":\" + d.getMinutes();\r\n        //         $(\'#data-stop_at\').val(d_txt);\r\n        //     }\r\n        // });\r\n\r\n<%\r\n        end\r\n%>\r\n        snap = $( \"a:contains(\'Snap\')\" ).clone();\r\n        snap = snap.addClass(\'btn btn-small btn-info\');\r\n        btn_snap = $(\'#btn-snap\');\r\n        btn_snap.append(snap);\r\n        \r\n        $(\'input\').prop(\'required\', null);\r\n        $(\'select\').prop(\'required\', null);\r\n<%\r\n    end\r\n%>\r\n    })\r\n<% if @appointment[:provider] %>\r\n    $(\'#data-endoscopist_1\').val(\'<%= @appointment[:provider] %>\');\r\n<% end %>\r\n</script>   \r\n',NULL,NULL,NULL,'2016-10-18 04:14:36','2016-10-18 04:14:36','create',''),(2654,'patient_record',796,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\n	body { min-width:0px; }\r\n	.gebo-fixed { background-color:#f5f5f5; }\r\n	#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Patient Records\r\n				<div class=\"pull-right\">\r\n					<%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n				</div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<%\r\n					ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n					ehr_models = ehr.get_model\r\n					patient_model = ehr_models[:patient]\r\n					patient_module_model = ehr_models[:patient_module]\r\n					\r\n					emr_models = get_model\r\n					ap = emr_models[:appointment].find(params[:id])\r\n					pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n					locker_model = emr_models[:locker]\r\n					if params[:reset_lock]\r\n					    l = locker_model.find(params[:reset_lock])\r\n					    l.destroy if l\r\n					end\r\n					#locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n					#i.destroy if i\r\n					#end\r\n					 \r\n					\r\n					\r\n					if pm\r\n					\r\n					if  params[:schema_patient_module]\r\n					   pm.update_attributes params[:schema_patient_module]\r\n					end\r\n					\r\n					if params[:provider_id]\r\n					  ap.update_attributes :provider=>params[:provider_id]\r\n					   ap = emr_models[:appointment].find(params[:id])\r\n					 end\r\n					\r\n					# find provider\r\n					provider = emr_models[:provider].find(ap.provider.to_s)\r\n					\r\n					# find patient\r\n					patient = patient_model.find(pm.patient_id)\r\n					\r\n					params[:patient]=patient\r\n					params[:patient_module]=pm\r\n					\r\n					# s = Service.get(\'ehr.emr.EmrHelper\')\r\n					#    obj = s.load context\r\n					\r\n					providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n					\r\n					%>\r\n				<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\'}.compact %>\r\n				<div style=\"border:0px solid\">\r\n					<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n						<%# render :inline=>obj.show_patient %>\r\n						<div id=\"patient\">\r\n							...\r\n						</div>\r\n						<script>\r\n							<%\r\n								url = \'../../www/Patient/search_result?\'\r\n								url += \'&id=\'+patient.id.to_s\r\n								%>      \r\n							        $.ajax({\r\n							    	  url: \'<%=url.html_safe%>\',\r\n									 success: function(data){\r\n							          $(\'#patient\').html(data);  \r\n									  }\r\n									});\r\n						</script>\r\n						<% \r\n							test = false\r\n							if @current_role == \'developer\' and test \r\n							%>\r\n						<pre>\r\n    Appointment : <%= ap.to_json.html_safe %><br/>\r\n</pre>\r\n						<pre>\r\n    PatientModule : <%= pm.to_json.html_safe %>\r\n</pre>\r\n						<% if params[:remove] == \'true\'\r\n							ap.destroy\r\n							pm.destroy\r\n							%>\r\n						<script>\r\n							window.location = \"index\"\r\n						</script>\r\n						<% end %>\r\n						<% \r\n							if params[:update] == \'true\' \r\n							    sname = @current_project.name + \"#\" + params[:sname]\r\n							    app_id = params[:app_id]\r\n							    \r\n							    t_ap = emr_models[:appointment].find(app_id)\r\n							    t_pm = patient_module_model.first(:module_id=>t_ap.id.to_s)\r\n							    f_pm = patient_module_model.where(:module_name=>sname, :parent_id=>pm.id).first\r\n							\r\n							    # Move unnessesary record to another appointment_id and patient_id\r\n							    # open record page that you need to move (f_pm), \r\n							    # use parameter update=true&sname={your_service_name}&app_id={another_appointment}\r\n							    \r\n							    # if t_pm\r\n							    #     f_pm.update_attributes :parent_id=>t_pm.id, :patient_id=>t_pm[:patient_id]\r\n							    #     ap = t_ap\r\n							    #     pm = t_pm\r\n							    # end\r\n							%>\r\n						<pre>\r\n    AppointmentID : <%= t_pm.to_json.html_safe %><br/>\r\n    <!--ParentID : <%=  %><br/>-->\r\n    Service  : <%= sname %><br/>\r\n    TEST : <%= f_pm.to_json.html_safe %>\r\n</pre>\r\n						<%\r\n							end\r\n							%>\r\n						<% end %>\r\n						<br/>\r\n						<%\r\n							previous = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\n							history = []\r\n							x = previous[0..7]\r\n							last = []\r\n							last = x.compact if x\r\n							history = []\r\n							y = previous[8..-1]\r\n							history = y.compact if y and  previous.size>5\r\n							                                     \r\n							current = time_ago_in_words(ap.date)\r\n							current_date = ap.date.strftime(\"%d-%m-%y\") \r\n							current = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n							\r\n							a_map = {}\r\n							a_ids = last.collect{|i| i[:module_id]}\r\n							a_list = get_model[:appointment].find(a_ids)\r\n							a_list.each do |i|\r\n							    a_map[i.id.to_s] = i\r\n							end\r\n						%>	\r\n						<div class=\"clear\"></div>\r\n						\r\n						<div class=\"tabbable\">\r\n						    \r\n							<ul class=\"nav nav-tabs\">\r\n								<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%><br/><%= ap[:status] %></a></li>\r\n								<%\r\n									for i in last \r\n									    m_ap_id = i[:module_id].to_s\r\n									    m_ap = a_map[m_ap_id]\r\n									    ap_status = \'NA\'\r\n									    ap_date = i.date.strftime(\"%d-%m-%y\") if i.date\r\n									    if m_ap\r\n									        ap_status = m_ap[:status].nil? ? \'N/A\' : m_ap[:status]\r\n									        ap_date = m_ap[:date].strftime(\"%d-%m-%y\") if m_ap[:date]\r\n									    end\r\n								%>\r\n								<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date) if i.date%><br/><%=ap_date%><br/><%= m_ap[:status] %></a></li>\r\n								<% end %>\r\n								<% if history.size>5 %>\r\n								<li class=\"dropdown\">\r\n									<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n									<ul class=\"dropdown-menu\">\r\n										<% for j in history %>\r\n										<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n										<% end %>\r\n										<li class=\"divider\"></li>\r\n									</ul>\r\n								</li>\r\n								<% end %>\r\n								<span style=\'float:right;margin-top:20px;margin-right:10px\'>\r\n        						    <%= link_to \'Add Visit\', \"../Appointment/create?obj_id=\\\\#{patient.id.to_s}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-mini btn-success\' %>\r\n        						</span>\r\n							</ul>\r\n							<div class=\"tab-content\">\r\n								<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n									<h4><%= @current_project.title %> Records</h4>\r\n									<% if current == \'Today\' %>\r\n									<div style=\'float:right\'><%= link_to \'Edit Visit\', \"../Appointment/show?id=\\\\#{pm.id.to_s}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-mini btn-info\', :style=>\'margin-top:-30px\' %></div>\r\n									<% end %>\r\n									<hr/>\r\n									<table class=\"table table-striped table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th></th>\r\n												<th>Forms</th>\r\n												<th>Records</th>\r\n												<th></th>\r\n											</tr>\r\n										</thead>\r\n										\r\n										<%\r\n											groups = this.config\r\n											if true\r\n											for g in groups \r\n											   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n											%>\r\n										<tr>\r\n											<td colspan=\"4\"><%=g[:name]%></td>\r\n										</tr>\r\n										<% services.each_with_index do |s,index|\r\n											module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n											records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n											%>\r\n										<tr>\r\n											<td><%= index+1 %>. </td>\r\n											<td> <%= s.title %></td>\r\n											<td align=\"center\"><% for i in records %>\r\n												<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number[0..9] if !i.ref_number.nil?}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n												<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n												<% end %>\r\n											</td>\r\n											<td>\r\n												<%  if records.size==0 %>\r\n												<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n												<% else %>\r\n												<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n												<% end %>\r\n												<% \r\n													locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n													if locker\r\n													text = \'\'\r\n													case locker.status\r\n													when \'create\'\r\n													    text=\'Creating..\'\r\n													when \'edit\'\r\n													    text=\'Editing..\'\r\n													end\r\n													user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n													\r\n													\r\n													%>\r\n												<%\r\n													user_name = user.login.split(\"@\")[0]\r\n													user_name =  solution_user.name  if solution_user\r\n													\r\n													text += \" by \" + user_name if user_name\r\n													#   text += locker.session\r\n													%>\r\n												<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n												<% end %>\r\n											</td>\r\n											<% end %>\r\n										</tr>\r\n										<% end %>\r\n										<% end %>\r\n									</table>\r\n								</div>\r\n								\r\n								\r\n								<% for i in previous \r\n									pm = i\r\n									%>\r\n								<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n									<h4><%= @current_project.title %> Records</h4>\r\n									<% \r\n								\r\n									    \r\n									    x = a_map[i[:module_id].to_s]\r\n									    \r\n									    \r\n									    \r\n									    \r\n									    if x and  x[:date] and  Time.now.to_i < x[:date].to_time.to_i \r\n									        \r\n								    %> \r\n								    \r\n									<div style=\'float:right\'><%= link_to \'Edit Visit\', \"../Appointment/show?id=\\\\#{i.id.to_s}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-mini btn-info\', :style=>\'margin-top:-30px\' %></div>\r\n									<% end %>\r\n							\r\n									\r\n									<hr/>\r\n									<table class=\"table table-striped table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th></th>\r\n												<th>Forms</th>\r\n												<th>Records</th>\r\n												<th></th>\r\n											</tr>\r\n										</thead>\r\n										\r\n										<%\r\n											groups = this.config\r\n											if true\r\n											for g in groups \r\n											   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n											%>\r\n										<tr>\r\n											<td colspan=\"4\"><%=g[:name]%></td>\r\n										</tr>\r\n										\r\n										<% services.each_with_index do |s,index|\r\n											module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n											records = patient_module_model.all :module_name=>module_nam