\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:200px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n.thumbnail {\r\n  position: relative;\r\n  width: 300x;\r\n  height: 300px;\r\n  overflow: hidden;\r\n}\r\n.thumbnail img {\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 50%;\r\n  height: 100%;\r\n  width: auto;\r\n  -webkit-transform: translate(-50%,-50%);\r\n      -ms-transform: translate(-50%,-50%);\r\n          transform: translate(-50%,-50%);\r\n}\r\n.thumbnail img.portrait {\r\n  width: 100%;\r\n  height: auto;\r\n}\r\n.tt {     margin-left: -90px; width: 140%;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<!--<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo2.png\' width=\"300\" /></div>-->\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' height=\'70px\' /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Gastroscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=record.date_note%></v>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n<hr />\r\n\r\n<table width=\"100%\" border=\"0\">\r\n  <tr>\r\n    <td valign=\"top\" width=\"50%\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p></td>\r\n    <td width=\"50%\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \')%></v></p>\r\n</td>\r\n  </tr>\r\n</table>\r\n\r\n\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n    <p>Note: <v><%=record[\'scope_note\']%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    <p>Remark : <v><%=record[\'remark\']%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n\r\n    <%\r\n        list = record.image\r\n        atts = []\r\n        if list[8...36]\r\n            atts = list[8...36].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        end\r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<%= image_tag i.path+\"?thumb=2\", :class=>\'tt\' %><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\" style=\"height:40px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-18 16:18:52','2016-10-18 16:18:52','print_image',''),(2660,'document_name',1069,1,'\'colonoscopy_scope\'',NULL,NULL,NULL,'2016-10-18 17:24:06','2016-10-18 17:24:06',NULL,NULL),(2661,'pz',904,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:pleuroscopy].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\n  end\r\n    \r\n     # many lesion\r\n    a_lesion = models[:pleuroscopy_scope].find(record[:apex])\r\n    d_lesion = get_document \'pleuroscopy_scope\'\r\n    f_lesion = d_lesion.fields\r\n    fl = {}\r\n    fm = {}\r\n    \r\n    f_lesion.each do |i|\r\n        # lab = i[:label]\r\n        lov = i[:lov]\r\n        name = i[:column_name]\r\n        if lov\r\n            fm[name] = {}\r\n            ll = lov.split(/[\\r\\n]+/)\r\n            ll.each do |j|\r\n                if j.include? \'|\'\r\n                    xx = j.split(\'|\')\r\n                    fm[name][xx[0].strip.to_s] = xx[1].strip\r\n                else\r\n                    fm[name][j.strip] = j.strip\r\n                end\r\n            end\r\n        end\r\n    end\r\n  \r\n %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:120px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:170px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:170px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\" class=\"well\">\r\n<div id=\"logoleft\" style=\"width:600px; float:left\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n<br />\r\n\r\n     First Name : \r\n       <v><%= patient.prefix_name %> <%= patient.first_name %></v><br />\r\n     Last Name : <v><%= patient.last_name %></v><br />\r\n     HN :&nbsp;<v><%=patient.hn%></v><br />\r\n     Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v><br />\r\n     Gender :&nbsp;<v><%=patient.gender%></v><br />\r\n    Date :&nbsp;<v><%=record.date_note%></v><br />\r\n\r\n\r\n\r\n</div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n\r\n	<div class=\"clear\"></div>\r\n  \r\n   \r\n	  <table width=\"100%\">\r\n	    <tr>\r\n	      <td > <h4 style=\"padding:0px; margin:0px; margin-left:10px\">Status : <%=record[\'status\']%> </h4></td>\r\n	      <td><h4 style=\"padding:0px; margin:0px;margin-left:10px\">Findings</h4></td>\r\n        </tr>\r\n	    <tr>\r\n      <td width=\"46%\"><p><span style=\"float:left; \"> </span>\r\n        <span style=\"float:left;display:block-inline;\">\r\n				<table width=\"100%\" style=\"margin-left:10px\" >\r\n				<tr>\r\n				  \r\n					<td width=\"122\">Procedure</td>\r\n					<td width=\"271\">Pleuroscopy</td>\r\n				</tr>\r\n				<tr>\r\n				 \r\n					<td>\r\n					  Endoscopist</td>\r\n					<td><%=endoscopist_1%></td>\r\n				</tr>\r\n				<tr>\r\n				\r\n					<td>Fellow</td>\r\n					<td><%=endoscopist_2%></td>\r\n				\r\n				<tr>\r\n				  <td>Diagnosis\r\n			      </td>\r\n				  <td><%=render_value \'provisional_diagnosis\'%><%=render_value \'definite_diagnosis\'%>\r\n\r\n                  </td>\r\n				  </tr>\r\n				<tr>\r\n				  <td>Pathology</td>\r\n				  <td><%=render_value \'histopathology1\'%><%=render_value \'cytology\'%></td>\r\n				  </tr>\r\n				<tr>\r\n				  <td>Microbiology</td>\r\n				  <td><%=render_value \'culture\'%><%=render_value \'culture_other\'%></td>\r\n				  </tr>\r\n				<tr>\r\n				  <td>Operation</td>\r\n				  <td><%=render_value \'operative_time_start_at\'%> - <%=render_value \'operative_time_stop_at\'%> </td>\r\n				  </tr>\r\n				<tr>\r\n				  <td>Sedation</td>\r\n				  <td><%=render_value \'midazolam\'%> <%=render_value \'midazolam_mg\'%><br />\r\n			      <%=render_value \'fentanyl\'%> <%=render_value \'fentanyl_mcg\'%> <br />\r\n			      <%=render_value \'propofol\'%> <%=render_value \'propofol_mg\'%><br />\r\n			      <%=render_value \'other\'%> <%=render_value \'other_note\'%></td>\r\n				  </tr>\r\n				<tr>\r\n					\r\n					<td width=\"122\">Indication</td>\r\n					<td><%=render_value \'indication\'%></td>\r\n				</tr>		\r\n				\r\n			</table>	\r\n		</span>\r\n		\r\n \r\n		</p></td>\r\n\r\n<td width=\"54%\"  valign=\"top\">\r\n<div id=\"lesion\">\r\n  <label>Side :</label> <b><%=render_value \'xxx\'%></b>\r\n <label>Pleural fluid finding :</label>\r\n  <%=render_value \'xxx\'%><label>Characteristics:</label><%=render_value \'xxx\'%><label>Color:</label><%=render_value \'xxx\'%><br/>\r\n<%# fm.to_json.html_safe %>\r\n<%\r\n  no = 1\r\n%>\r\n\r\n<%\r\n    tmp_doc = @document\r\n    tmp_rec = @record\r\n    \r\n    @document = d_lesion\r\n\r\n\r\n    pleuro_many_field = [\'apex\', \'anterior_aspect\', \'posterior_aspect\', \'diaphragm\']\r\n    pleuro_many_field.each do |f|\r\n        a_lesion = models[:pleuroscopy_scope].find(tmp_rec[f.to_sym])\r\n        if a_lesion\r\n            a_lesion.each do |i|\r\n        \r\n    @record = i    \r\n    # img = models[:attachment].find(i[\'image\'])\r\n    \r\n%>\r\n\r\n  <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"-moz-border-radius: 5px;\r\nborder-radius: 5px; border-color:#999\">\r\n  <tr>\r\n  <td><%= f.humanize %></td>\r\n  \r\n  <td> \r\n   Diagnosis :<%= render_value\'diagnosis\' %> ,Intervention :<%= render_value\'intervention\' %> ,Note :<%= render_value\'scope_note\' %>\r\n   \r\n   </td>\r\n  </tr>\r\n   \r\n  \r\n  \r\n  \r\n<% \r\nno += 1\r\n            end\r\n        end\r\n    end \r\n    \r\n    @document = tmp_doc\r\n    @record = tmp_rec\r\n    \r\n%>\r\n<tr>\r\n  <td>&nbsp;&nbsp;Anterior aspect</td>\r\n  \r\n  <td><% if a_lesion%>\r\n   Diagnosis :<%= render_value\'diagnosis\' %> ,Intervention :<%= render_value\'finding\' %> ,Note :<%= render_value\'scope_note\' %>\r\n   <% end %></td>\r\n  </tr>\r\n    <tr>\r\n  <td>&nbsp;&nbsp;Panetal Pleura </td>\r\n  \r\n  <td> \r\n  <% if a_lesion%>\r\n   Diagnosis :<%= render_value\'diagnosis\' %> ,Intervention :<%= render_value\'finding\' %> ,Note :<%= render_value\'scope_note\' %>\r\n   <% end %>\r\n   </td>\r\n  </tr>\r\n    <tr>\r\n  <td>&nbsp;&nbsp;Diaphragm</td>\r\n  \r\n  <td> \r\n   <% if a_lesion%>\r\n  Diagnosis :<%= render_value\'diagnosis\' %> ,Intervention :<%= render_value\'finding\' %> ,Note :<%= render_value\'scope_note\' %>\r\n   <% end %>\r\n   </td>\r\n  </tr>\r\n    <tr>\r\n      <td>Procedure</td>\r\n      <td><%=render_value \'medical_pleurodesis1\'%> <%=render_value \'type_of_sclerosing_agent\'%> <%=render_value \'amount_of_agent\'%> <%=render_value \'icd_number\'%> <%=render_value \'apply_negative_pressure_suction1\'%>  <%=render_value \'set_pressure\'%>    </td>\r\n    </tr>\r\n    <tr>\r\n      <td>Complication</td>\r\n      <td><%=render_value \'intraoperative_complication1\'%> <%=render_value \'intraoperative_complication_detail\'%> </td>\r\n    </tr>\r\n    <tr>\r\n      <td>Comments</td>\r\n      <td><%=render_value \'comment\'%></td>\r\n    </tr>\r\n  </table>\r\n  <br />\r\n</div>\r\n\r\n</td>\r\n </tr></table>\r\n	\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-19 08:24:37','2016-10-19 08:24:37','pz',''),(2662,'document_name',1070,1,'\'attendance_payroll_item\'',NULL,NULL,NULL,'2016-10-19 09:01:11','2016-10-19 09:01:11',NULL,NULL),(2663,'reprocess',1033,2,'<%\r\n    map = {}\r\n    models = get_model\r\n    models[:product].all.each do |i|\r\n        map[i.id] = i\r\n    end\r\n        \r\n    list = models[:billing].all\r\n    \r\n    imap = {}\r\n    models[:billing_item].all.each do |i|\r\n        imap[i.id] = i \r\n    end\r\n    \r\n    count = 0\r\n%>\r\n<ul>\r\n\r\n<% for i in list %>\r\n    <li><%=i.id%> <%=i.inspect %>\r\n        \r\n        <ul>\r\n            <% for j in i.items.collect{|k| imap[k]}\r\n                p = map[j.product_id]\r\n                price = p.price\r\n                price = p.price_2 if i.billing_type==\'2\' and p.price_2\r\n                \r\n                if j.price== nil\r\n                \r\n                j.update_attributes :price=>price\r\n                \r\n                end\r\n                count += 1 if price!=j.price\r\n                \r\n            %>\r\n            <li style=\" <%= \'background-color:red\' if price != j.price%> \"><%=j.id%> : <%=j.product_id%> : <%=j.price %> : <%=price%></li>\r\n            <% end %>\r\n            \r\n        </ul>\r\n    </li>\r\n\r\n<% end %>\r\n</ul>\r\n<hr/>\r\n<%= count %>',NULL,NULL,NULL,'2016-10-19 09:26:15','2016-10-19 09:26:15','reprocess',''),(2664,'pp',902,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n	# id of operative note\r\n	\r\n	models  = @models\r\n	pm = @module_model.find(params[:id])\r\n	colono_id = pm.module_id\r\n	record = models[:bronchoscopy].find(colono_id)\r\n	@record = record\r\n	@document = get_document this.document_name\r\n	\r\n	endoscopist_1 = render_value(\'endoscopist_1\')\r\n	endoscopist_2 = render_value(\'endoscopist_2\')\r\n	\r\n	# gender\r\n	gd = {\'0\'=>\'N/A\',\'1\'=>\'Male\',\'2\'=>\'Female\'}\r\n	\r\n	if @patient \r\n	patient = @patient\r\n	date = Time.now.to_datetime\r\n	birth_date = patient.birth_date \r\n	year = month = day = \'0\'\r\n	if date and birth_date\r\n	t = date-birth_date    \r\n	year = (t/365).to_i\r\n	t%=365\r\n	month = (t/30).to_i\r\n	t%=30\r\n	day = t.to_i\r\n	end\r\n	end\r\n	\r\n	 # many lesion\r\n	a_lesion = models[:bronchoscopy_scope].find(record[:apex])\r\n	d_lesion = get_document \'bronchoscopy_scope\'\r\n	f_lesion = d_lesion.fields\r\n	fl = {}\r\n	fm = {}\r\n	\r\n	f_lesion.each do |i|\r\n	    # lab = i[:label]\r\n	    lov = i[:lov]\r\n	    name = i[:column_name]\r\n	    if lov\r\n	        fm[name] = {}\r\n	        ll = lov.split(/[\\r\\n]+/)\r\n	        ll.each do |j|\r\n	            if j.include? \'|\'\r\n	                xx = j.split(\'|\')\r\n	                fm[name][xx[0].strip.to_s] = xx[1].strip\r\n	            else\r\n	                fm[name][j.strip] = j.strip\r\n	            end\r\n	        end\r\n	    end\r\n	end\r\n	\r\n					# atts = models[:attachment].limit(5).find(record.image)\r\n					\r\n	atts = models[:attachment].where(:_id=>record[:images], :selected=>1).all\r\n	if atts.nil?\r\n	    atts = []\r\n	end				\r\n	if atts.empty?\r\n	   atts_list = record[:images][0..8]\r\n	   atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n	end\r\n	\r\n	\r\n	a_page = 1\r\n	if atts.size > 5\r\n	    a_page = 2\r\n	end\r\n	\r\n	g_att = atts.group_by{|i| i.id.to_s}\r\n	rs_att = []\r\n	record[:images].each do |i|\r\n	    if g_att.has_key? i.to_s\r\n	        rs_att << g_att[i.to_s][0]\r\n	    end\r\n	end\r\n	\r\n	%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>PRINT</title>\r\n	</head>\r\n	<style type=\"text/css\" media=\"all\">\r\n		html { }\r\n		#page {border:solid 1px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n		#head { width:100%; height:140px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-size: 1.5em; margin: .83em 0 }\r\n		h3              { font-size: 1.17em; margin: 1em 0 }\r\n		p {color:#666;}\r\n		h4, p,\r\n		blockquote, ul,\r\n		form,\r\n		ol, dl          { margin: 0.5em; }\r\n		h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n		h6              { font-size: .67em; margin: 2.33em 0 }\r\n		h4 { font-size:14pt; color:#333; height:16px;}\r\n		blockquote      { margin-left: 40px; margin-right: 40px }\r\n		i, cite, em,\r\n		var, address    { font-style: italic }\r\n		pre, tt, code,\r\n		kbd, samp       {  font-size:14px; }\r\n		pre             {margin:0;margin-left:1em; color:#666}\r\n		big             { font-size: 1.17em }\r\n		v {color:#2561cD;}\r\n		small, sub, sup { font-size: .83em }\r\n		ol, ul, dd      { margin-left: 40px }\r\n		ol              { list-style-type: decimal }\r\n		ol ul, ul ol,\r\n		ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n		.clear{clear:both;}\r\n		@media print {\r\n		@page         { width:960px; margin-top:0; }\r\n		blockquote, \r\n		.wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n		footer {\r\n		page-break-after: always;\r\n		}\r\n		}\r\n		#box{\r\n		width:215px;\r\n		float:left;\r\n		padding:0px;\r\n		text-align:center;\r\n		border:1px solid #ccc;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */    \r\n		margin:5px;\r\n		font-size:0.8em;\r\n		height:190px;\r\n		overflow:hidden;\r\n		}\r\n		.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n		#box img{\r\n		height:170px;\r\n		margin-left: -90px;\r\n		}\r\n		label{\r\n		color:#666;\r\n		}\r\n		.sidationcss\r\n		{width:160px; float:left; margin-bottom:3px;}\r\n	</style>\r\n	<body>\r\n		<div class=\"wrapper\">\r\n			<div id=\"head\" class=\"well\">\r\n				<div id=\"logoleft\" style=\"width:600px; float:left\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n					<br />\r\n					First Name : \r\n					<v><%= patient.prefix_name %> <%= patient.first_name %></v>\r\n					<br />\r\n					Last Name : \r\n					<v><%= patient.last_name %></v>\r\n					<br />\r\n					HN :&nbsp;\r\n					<v><%=patient.hn%></v>\r\n					<br />\r\n					Age :&nbsp;\r\n					<v><%= year%> Year <%=month%> Month <%= day%> Day </v>\r\n					<br />\r\n					Gender :&nbsp;\r\n					<v><%= gd[patient[:gender]] %></v>\r\n					<br />\r\n					Date :&nbsp;\r\n					<v><%=record.date_note%></v>\r\n					<br />\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now %></p>\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n			</div>\r\n			<div id=\"page\">\r\n				<div class=\"clear\"></div>\r\n				<table width=\"100%\">\r\n					<tr>\r\n						<td width=\'48%\'>\r\n						</td>\r\n						<td>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td valign=\'top\' cellspacing=\'10\'>\r\n							<h4 style=\"padding:0px; margin:0px; margin-left:10px\">Status : <%=render_value \'status\'%> </h4>\r\n							<br/><br/>\r\n							<p>\r\n								<span style=\"float:left; \"> </span>\r\n								<span style=\"float:left;display:block-inline;\">\r\n							<table width=\"100%\" style=\"margin-left:10px\" >\r\n							<tr>\r\n							<td width=\"122\">Procedure</td>\r\n							<td width=\"271\"><v>Bronchoscopy</v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>\r\n							Endoscopist</td>\r\n							<td><v><%=endoscopist_1%></v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>Fellow</td>\r\n							<td><v><%=endoscopist_2%></v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>Diagnosis\r\n							</td>\r\n							<td><v><%=render_value \'provisional_diagnosis\'%></v>\r\n							</td>\r\n							</tr>\r\n							<tr>\r\n							<td>Definite Diagnosis </td>\r\n							<td><v><%=render_value \'definite_diagnosis\'%></v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>Pathology</td>\r\n							<td><v>Histopathology :<%=render_value \'histopathology1\'%></v><br /><v>Cytology :<%=render_value \'cytology\'%></v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>Microbiology</td>\r\n							<td><v><%=render_value \'culture\'%> / <%=render_value \'culture_other\'%></v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>Operation</td>\r\n							<td><v><%=render_value \'operative_time_start_at\'%> - <%=render_value \'operative_time_stop_at\'%></v> </td>\r\n							</tr>\r\n							<tr>\r\n							<td>Sedation</td>\r\n							<td> <% if record[\'midazolam\']==\'true\'%><v>Midazolam : <%=render_value \'midazolam_mg\'%></v><br /><% end%>\r\n							<% if record[\'fentanyl\']==\'true\'%><v>Fentanyl :<%=render_value \'fentanyl_mcg\'%></v><br /><% end%>\r\n							<% if record[\'propofol\']==\'true\'%><v>Propofol :<%=render_value \'propofol_mg\'%></v><br /><% end%>\r\n							<% if record[\'other\']==\'true\'%><v>Ohter :<%=render_value \'other_note\'%></v><% end%></td>\r\n							</tr>		\r\n							</table>	\r\n							</span>\r\n							</p>\r\n							<div class=\'clear\'></div>\r\n						</td>\r\n						<td valign=\"top\">\r\n							<div id=\'sign\' style=\'height:10px\'>\r\n								<h4>Sign : </h4>\r\n								<div id=\'provider-name\' style=\'margin-top:10px;float:right\'>\r\n									<%= render_value(\'endoscopist_1\') %> / <%= render_value(\'endoscopist_2\') %>\r\n								</div>\r\n							</div>\r\n							<hr/>\r\n							<br/>\r\n							<h4 style=\"padding:0px; margin:0px;margin-left:10px\">Findings</h4>\r\n							<br />\r\n							<div id=\'finding\'>\r\n								<br/>\r\n								<%\r\n									def get_render_value(field)\r\n									    f = field.to_sym\r\n									    if @record[f].nil? or @record[f]==\'\'\r\n									        return \"-\"\r\n									    else\r\n									        return render_value(f.to_s)\r\n									    end\r\n									end\r\n									\r\n									def get_value(field)\r\n									    f = field.to_sym\r\n									    if @record[f].nil? or @record[f]==\'\'\r\n									        return \'-\'\r\n									    else\r\n									        return @record[f]\r\n									    end\r\n									end\r\n									\r\n									def is_exist(field)\r\n									    f = field.to_sym\r\n									    if @record[f].nil? or @record[f]==\'\'\r\n									        return false\r\n									    else\r\n									        return true\r\n									    end\r\n									end\r\n									\r\n									# anatomy fields\r\n									af = get_render_value(:anatomy).split(\',\').collect{|i| i.downcase.strip.gsub \' \', \'_\'} \r\n									# field map\r\n									fm = {}\r\n									@document.fields.each do |i|\r\n									    if i[:lov_type] == \'pair\'\r\n									        tmp = {}\r\n									        tmp[:name] = i[:name]\r\n									        tmp[:list] = []\r\n									        tmp[:pair] = {}\r\n									        lov = i[:lov].to_s.split(\'\\r\\n\')\r\n									        lov.each do |j|\r\n									            x = j.split(\'|\')\r\n									            tmp[:pair][x[0].strip] = x[1].strip\r\n									            tmp[:list] << x[1].strip\r\n									        end\r\n									        fm[i[:column_name].to_sym] = tmp\r\n									    end\r\n									end\r\n									\r\n									tmp_rec = @record\r\n									tmp_doc = @document\r\n									\r\n									@document = get_document \'bronchoscopy_scope\'\r\n									%>\r\n								<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"2\" style=\"-moz-border-radius: 5px;\r\n									border-radius: 5px; border-color:#999\">\r\n									<%\r\n										# section to render report\r\n										fm[:anatomy][:list][0..5].each do |i|\r\n										    # key symbol\r\n										    ks = i.downcase.strip.gsub(\' \', \'_\').to_sym\r\n										    # has sub element ?\r\n										    hs = fm.has_key? ks\r\n										    # selected item ?\r\n										    si = af.include? ks.to_s\r\n										    \r\n										    rs = \"N/A\"\r\n										    if si and !hs\r\n										        @record = get_model[:bronchoscopy_scope].find(tmp_rec[ks])\r\n										        dx_val = \'N/A\'\r\n										        in_val = \'N/A\'\r\n										        sc_val = \'\'\r\n										        \r\n										        if !@record.nil?\r\n										            dx_val = get_render_value(:diagnosis)\r\n										            in_val = get_render_value(:intervention)\r\n										            \r\n										            if is_exist(:scope_note)\r\n										                sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										            end\r\n										        end\r\n										        rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										        \r\n										        i = \"<b>\\\\#{i}</b>\".html_safe\r\n										    \r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										elsif si and hs\r\n										    i = \"<b>\\\\#{i}</b>\".html_safe\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										rs = \'\'\r\n										kk = fm[ks]\r\n										\r\n										ls = tmp_rec[ks].split(\'|\')\r\n										ls.each do |j|\r\n										    # sub element name\r\n										    em = kk[:pair][j]\r\n										    sn = \"<i><b>\\\\#{em}</b></i>\".html_safe\r\n										    # element symbol\r\n										    es = em.downcase.strip.gsub(\' \', \'_\')\r\n										    \r\n										    @record = get_model[:bronchoscopy_scope].find(tmp_rec[\"\\\\#{ks}_\\\\#{es}\".to_sym])\r\n										    dx_val = \'N/A\'\r\n										    in_val = \'N/A\'\r\n										    sc_val = \'\'\r\n										    \r\n										    if !@record.nil?\r\n										        dx_val = get_render_value(:diagnosis)\r\n										        in_val = get_render_value(:intervention)\r\n										        \r\n										        if is_exist(:scope_note)\r\n										            sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										        end\r\n										    end\r\n										    rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										    \r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											&nbsp;&nbsp;<%= sn %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<% \r\n										end\r\n										else\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										end\r\n										end \r\n										# end section\r\n										%>\r\n								</table>\r\n							</div>\r\n						</td>\r\n					</tr>\r\n				</table>\r\n				<!--<hr/>-->\r\n				<!-- separate finding left-right -->\r\n				<div id=\'finding-left-right\' style=\'margin-top:20px\'>\r\n					<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"2\" style=\"-moz-border-radius: 5px;\r\n						border-radius: 5px; border-color:#999\">\r\n						<tr>\r\n							<td>\r\n								<h4>Finding Left</h4>\r\n							</td>\r\n							<td>\r\n								<h4>Finding Right</h4>\r\n							</td>\r\n						</tr>\r\n						<tr>\r\n							<td width=\'48%\' valign=\'top\'>\r\n								<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"2\" style=\"-moz-border-radius: 5px;\r\n									border-radius: 5px; border-color:#999\">\r\n									<%\r\n										# section to render report\r\n										fm[:anatomy][:list][11..-1].each do |i|\r\n										    # key symbol\r\n										    ks = i.downcase.strip.gsub(\' \', \'_\').to_sym\r\n										    # has sub element ?\r\n										    hs = fm.has_key? ks\r\n										    # selected item ?\r\n										    si = af.include? ks.to_s\r\n										    \r\n										    rs = \"N/A\"\r\n										    if si and !hs\r\n										        @record = get_model[:bronchoscopy_scope].find(tmp_rec[ks])\r\n										        dx_val = \'N/A\'\r\n										        in_val = \'N/A\'\r\n										        sc_val = \'\'\r\n										        \r\n										        if !@record.nil?\r\n										            dx_val = get_render_value(:diagnosis)\r\n										            in_val = get_render_value(:intervention)\r\n										            \r\n										            if is_exist(:scope_note)\r\n										                sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										            end\r\n										        end\r\n										        rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										        i = \"<b>\\\\#{i}</b>\".html_safe\r\n										    \r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %> \r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										elsif si and hs\r\n										    i = \"<b>\\\\#{i}</b>\".html_safe\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										rs = \'\'\r\n										kk = fm[ks]\r\n										\r\n										ls = tmp_rec[ks].split(\'|\')\r\n										ls.each do |j|\r\n										    # sub element name\r\n										    em = kk[:pair][j]\r\n										    sn = \"<i><b>\\\\#{em}</b></i>\".html_safe\r\n										    # element symbol\r\n										    es = em.downcase.strip.gsub(\' \', \'_\')\r\n										    if es == \'apicoposterior_segment\'\r\n										        es = \'apoposterior_segment\'\r\n										    end\r\n										    \r\n										    @record = get_model[:bronchoscopy_scope].find(tmp_rec[\"\\\\#{ks}_\\\\#{es}\".to_sym])\r\n										    dx_val = \'N/A\'\r\n										    in_val = \'N/A\'\r\n										    sc_val = \'\'\r\n										    \r\n										    if !@record.nil?\r\n										        dx_val = get_render_value(:diagnosis)\r\n										        in_val = get_render_value(:intervention)\r\n										        \r\n										        if is_exist(:scope_note)\r\n										            sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										        end\r\n										    end\r\n										    rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											&nbsp;&nbsp;<%= sn %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<% \r\n										end\r\n										else\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										end\r\n										end \r\n										# end section\r\n										%>\r\n								</table>\r\n							</td>\r\n							<td valign=\'top\'>\r\n								<table width=\'100%\' border=\'0\' cellpadding=\'0\' cellspacing=\'2\' style=\'-moz-border-radius:5px;border-radius:5px;border-color:#999\'>\r\n									<%\r\n										# section to render report\r\n										fm[:anatomy][:list][6..10].each do |i|\r\n										    # key symbol\r\n										    ks = i.downcase.strip.gsub(\' \', \'_\').to_sym\r\n										    # has sub element ?\r\n										    hs = fm.has_key? ks\r\n										    # selected item ?\r\n										    si = af.include? ks.to_s\r\n										    \r\n										    rs = \"N/A\"\r\n										    if si and !hs\r\n										        @record = get_model[:bronchoscopy_scope].find(tmp_rec[ks])\r\n										        dx_val = \'N/A\'\r\n										        in_val = \'N/A\'\r\n										        sc_val = \'\'\r\n										        \r\n										        if !@record.nil?\r\n										            dx_val = get_render_value(:diagnosis)\r\n										            in_val = get_render_value(:intervention)\r\n										            \r\n										            if is_exist(:scope_note)\r\n										                sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										            end\r\n										        end\r\n										        rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										        i = \"<b>\\\\#{i}</b>\".html_safe\r\n										    \r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										elsif si and hs\r\n										    i = \"<b>\\\\#{i}</b>\".html_safe\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										rs = \'\'\r\n										kk = fm[ks]\r\n										\r\n										ls = tmp_rec[ks].split(\'|\')\r\n										ls.each do |j|\r\n										    # sub element name\r\n										    em = kk[:pair][j]\r\n										    sn = \"<i><b>\\\\#{em}</b></i>\".html_safe\r\n										    # element symbol\r\n										    es = em.downcase.strip.gsub(\' \', \'_\')\r\n										    \r\n										    @record = get_model[:bronchoscopy_scope].find(tmp_rec[\"\\\\#{ks}_\\\\#{es}\".to_sym])\r\n										    dx_val = \'N/A\'\r\n										    in_val = \'N/A\'\r\n										    sc_val = \'\'\r\n										    \r\n										    if !@record.nil?\r\n										        dx_val = get_render_value(:diagnosis)\r\n										        in_val = get_render_value(:intervention)\r\n										        \r\n										        if is_exist(:scope_note)\r\n										            sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										        end\r\n										    end\r\n										    rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											&nbsp;&nbsp;<%= sn %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<% \r\n										end\r\n										else\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										end\r\n										end \r\n										# end section\r\n										%>\r\n								</table>\r\n							</td>\r\n						</tr>\r\n					</table>\r\n				</div>\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n			<div id=\"page\">\r\n				<h4>Comment :</h4>\r\n				<%= record.comments.html_safe %>\r\n			</div>\r\n			<div id=\"page\">\r\n				<h4>Picture :</h4>\r\n				<%\r\n					if !rs_att.empty?\r\n					 rs_att[0..7].each_with_index do |i,index| \r\n					%>\r\n				<div id=\"box\">\r\n					<img alt=\"<%= i[:title] %>\" src=\"<%=i[:path]%>\" /><br/>\r\n					<v><%=i[:title]%></v>\r\n				</div>\r\n				<% if index%4==3 %>\r\n				<div class=\"clear\"></div>\r\n				<% end %>\r\n				<% end %>\r\n				<% end %>\r\n				<div class=\"clear\"></div>\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n			\r\n<%\r\n    if rs_att.size > 8\r\n%>\r\n            <br/><br/>\r\n            <footer></footer>\r\n            <div id=\"head\" class=\"well\">\r\n				<div id=\"logoleft\" style=\"width:600px; float:left\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n					<br />\r\n					First Name : \r\n					<v><%= patient.prefix_name %> <%= patient.first_name %></v>\r\n					<br />\r\n					Last Name : \r\n					<v><%= patient.last_name %></v>\r\n					<br />\r\n					HN :&nbsp;\r\n					<v><%=patient.hn%></v>\r\n					<br />\r\n					Age :&nbsp;\r\n					<v><%= year%> Year <%=month%> Month <%= day%> Day </v>\r\n					<br />\r\n					Gender :&nbsp;\r\n					<v><%= gd[patient[:gender]] %></v>\r\n					<br />\r\n					Date :&nbsp;\r\n					<v><%=record.date_note%></v>\r\n					<br />\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now %></p>\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n			</div>\r\n			<div id=\"page\" style=\"min-height:25cm\">\r\n				<div class=\"clear\"></div>\r\n				<table width=\"100%\">\r\n					<tr>\r\n						<td>\r\n<h4>Picture :</h4>\r\n				<%\r\n				# rs_att = rs_att+rs_att+rs_att\r\n					if !rs_att.empty? and false\r\n					 rs_att[0..7].each_with_index do |i,index| \r\n					%>\r\n				<div id=\"box\">\r\n					<img alt=\"<%= i[:title] %>\" src=\"<%=i[:path]%>\" /><br/>\r\n					<v><%=i[:title]%></v>\r\n				</div>\r\n				<% if index%4==3 %>\r\n				<div class=\"clear\"></div>\r\n				<% end %>\r\n				<% end %>\r\n				<% end %>\r\n				\r\n				\r\n<% \r\n    # attachment image section \r\n    @record = tmp_rec\r\n    @document = tmp_doc\r\n%>				\r\n				<% \r\n				    for i in rs_att[9..23]\r\n				%>\r\n				    <div style=\"float:left;  width: 280px;  padding: 5px; text-align:center; font-size:14px;\">\r\n				        <img src=\"<%=i.path%>\" width=\"250\" height=\"180\" style=\"margin:5px\"/><br /><%=i.title%><br />\r\n				    </div>\r\n				<% \r\n				    end\r\n				%>\r\n						</td>\r\n					</tr>\r\n				</table>\r\n				<!--<hr/>-->\r\n				\r\n			</div>\r\n			<div id=\"page\" style=\"padding-top: 5px;min-height:1.5cm\">\r\n			    <div id=\'sign-2\' style=\'float:left\'>\r\n    			    <h4>Sign : </h4>\r\n    			    <br/>\r\n    			    <br/>&nbsp;\r\n			    </div>\r\n				<div id=\'provider-name-2\' style=\'margin-top:10px;float:right;color:#666\'>\r\n					<%= render_value(\'endoscopist_1\') %> / <%= render_value(\'endoscopist_2\') %>\r\n					<br/>\r\n					Printed at : <%= Time.now %>\r\n					<br/>\r\n				</div>\r\n			</div>\r\n<%\r\n    end\r\n%>\r\n			\r\n		</div>\r\n	</body>\r\n</html>\r\n<script>\r\nwindow.print()\r\n</script>',NULL,NULL,NULL,'2016-10-19 14:57:50','2016-10-19 14:57:50','pp',''),(2665,'index',1071,2,'\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Solution\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE</b></center><br/>\r\n    <%= render :inline=>this.module %>\r\n</div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n<% \r\n\r\n    model = get_model\r\n    patient_model = model[:patient]\r\n    patient_module_model = model[:patient_module]\r\n    modules = @context.get_projects_by_abstract \'ehr.emr\' \r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n\r\n<%\r\ndb = patient_model.collection.db\r\n%>\r\n<%#db.class%>\r\n<%#db.collection_names.sort%>\r\n<%#=db.collection(\'colpo.appointment\').find(:date=>nil).inspect%>\r\n\r\n<%\r\n\r\nfor m in modules\r\nif false #mit edit\r\n    list = db.collection(\"\\\\#{m.name}.appointment\").group({:keyf=>\'function(doc){return {month:doc.date.getMonth()};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\'\r\n        #   :cond=>{:status=>{\'$in\'=>[\'Completed\',\'Recovery\',\'Processing\']},:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}\r\n          })\r\n        columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n        \r\n    if list.size>0    \r\n    data = []\r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    data[i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\nend #mit edit\r\n\r\n%>\r\n<%#list.to_json.html_safe%>\r\n<div id=\"chart-<%=m.id%>\" style=\"border:0px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n<%#columns.to_json%>\r\n            <script>\r\n                    $(\"#chart-<%=m.id%>\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"<%=m.title%> Patients by Month\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: [{\r\n                            name: \"Patients\",\r\n                            data: <%=data.to_json.html_safe %>\r\n                        }],\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                \r\n\r\n             \r\n            </script>                 \r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        System Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<table class=\"table table-striped table-bordered table-condensed\">\r\n<thead>\r\n<tr>\r\n<th>Title</th>\r\n<th>Value</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Disk Space</td>\r\n<%    \r\n\r\n\r\n   size = patient_model.collection.db.stats[\'storageSize\']\r\n   unit = \'B\'\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'KB\'\r\n   size /= 1000\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'MB\'\r\n   size /= 1000\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'GB\'\r\n   size /= 1000\r\n   \r\n   end\r\n   end\r\n   end\r\n   \r\n   \r\n\r\n%>\r\n\r\n<td><%=format(\'%.2f\',size)%> <%=unit%></td>\r\n</tr>\r\n<tr>\r\n<td>Total Patient</td>\r\n<td><%= (model[:patient]).count %></td>\r\n</tr>\r\n<tr>\r\n<td>Total Module</td>\r\n<td><%= modules.size %></td>\r\n</tr>\r\n<tr>\r\n\r\n</tr>\r\n<tr>\r\n<td>Total Record</td>\r\n<td><%= (model[:patient_module]).count %></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<!--\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Support\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\"></div>\r\n</div>\r\n-->\r\n</div>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-10-19 17:38:14','2016-10-19 17:38:14','',''),(2666,'form',1072,3,'<script src=\"/gebo/lib/smoke/smoke.js\"></script>\r\n<link rel=\"stylesheet\" href=\"/gebo/lib/smoke/themes/gebo.css\" />\r\n<%# session.inspect %>\r\n<%\r\n	fparams = params[:form]\r\n	model = fparams[:model]\r\n	f = fparams[:form]\r\n	@record = fparams[:record]\r\n	@project =  context[:project]\r\n	@document =  get_document this.document_name \r\n	his = nil\r\n	his = session[:his]\r\n	unless session[:last_his] \r\n	    his = nil\r\n	else\r\n	    if session[:last_his].strftime(\"%d/%m/%y\")!=Time.now.strftime(\"%d/%m/%y\")\r\n            session[:last_his] = nil\r\n            his = nil\r\n        end\r\n	end\r\n%>\r\n<% if false %>\r\n    <%= link_to \'Get Patient From HIS\',\'javascript:get_patient_info()\',:class=>bt_class+\" btn-info\" %> \r\n    <%= \"HIS login as <b>\\\\#{session[:his]}</b>, give \'-\' for hn to logout\".html_safe if session[:his] %>\r\n    \r\n    <div id=\"his-status\"></div>\r\n<% end %>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n\r\n    // $(\'#span-his_btn\').hide();\r\n    // $(\'#span-btn\').hide();\r\n\r\n	function get_patient_image(){\r\n	    ///esm_image/132/attach_to_gallery?p_id=64&field_id=F6478524829&ssid=56215239&_=1361259922808\r\n	 $.ajax({\r\n	  url: \"get_patient_image?doc=132&project=64&ssid=56215239\",\r\n	  context: document.body,\r\n	  crossDomain: true\r\n	  }).done(function(data) {\r\n	        $(\'#his-status\').html(\'retriving...\');\r\n	        eval(data);\r\n	        $(\'#his-status\').html(\'completed\');\r\n	  }).fail(function(jqXHR, textStatus) {\r\n	    alert(\"error\");\r\n	  });\r\n	}\r\n	\r\n	his_username = \'\'\r\n	\r\n	function get_patient_info(us, ps, hn){\r\n        $(\'#his-status\').html(\'connecting...\');\r\n	    \r\n<% if his %>\r\n	\r\n	    var username = \'<%=his%>\'\r\n	    var password = \'-\'\r\n	\r\n<% else %>\r\n\r\n	   // var username=prompt(\"Please enter your username\",\"\");\r\n	   // var password=prompt(\"Please enter your password\",\"\");\r\n	\r\n<% end %>\r\n\r\n        // var hn=prompt(\"Please enter HN\",\"\");    \r\n        // var hn = hn\r\n        username = us;\r\n        password = ps;\r\n        if (hn==\'\') { \r\n            // alert(\"Not enough information!!\"); \r\n            $(\'#his-status\').html(\'No HN information, Please fill Patient HN\')\r\n        }else{     \r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading...</span>\');    \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            $.ajax({\r\n                url: \"get_patient_info?un=\"+username+\"&ps=\"+password+\"&hn=\"+hn+\"&doc_id=<%=@document.id%>\",\r\n                context: document.body,\r\n                crossDomain: true\r\n            }).done(function(data) {\r\n                $(\'#his-status\').html(\'retriving...\');\r\n                eval(data);\r\n                $(\'#his-status\').html(\'completed\');\r\n            }).fail(function(jqXHR, textStatus) {\r\n                // alert(\"error\");\r\n                $(\'#his-status\').html(\'Error loading, Please fill Patient information\')\r\n            });\r\n        }\r\n    }\r\n    \r\n    function his_login_modal() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    \r\n    $(\'#get-his\').click(function() {\r\n        get_patient_info(\'<%= his %>\', \'-\', $(\'#data-hn\').val());\r\n    });\r\n    \r\n    $(\'#his-login\').click(function() {\r\n        his_login_modal();\r\n        // get_patient_info(\'\',\'\',\'\');\r\n    });\r\n	        \r\n	        $(\'#his-logout\').click(function() {\r\n        	    $(\'#his-logout\').html(\'Loading ...\');\r\n        	    console.log(\'logout...\')\r\n                get_patient_info(\'-\', \'-\', \'-\');\r\n                // window.location = \'../Home/index\';\r\n        	});\r\n	\r\n</script>',NULL,NULL,NULL,'2016-10-21 04:47:07','2016-10-21 04:47:07','',''),(2667,'get_patient_info',1072,3,'<%\r\n\r\n\r\n\r\ndef get_hn i\r\n\r\n  n = \'\'\r\n  y = \'\'\r\n  \r\n  return i if i.size<5 or i.size>9\r\n  if i.index \'/\'  \r\n    t = i.split(\"/\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.index \'-\'  \r\n    t = i.split(\"-\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.size==8\r\n    y = i[0..1].to_i\r\n    y2 = i[-2..-1].to_i\r\n    n = i[3..-1].to_i  \r\n    if y2 > y\r\n      y = y2\r\n      n = i[0..-3].to_i    \r\n    end\r\n  else\r\n    y = i[-2..-1]\r\n    n = i[0..-3]\r\n  end\r\n  \r\n  hn = \"\\\\#{n.to_i.to_s}/\\\\#{y}\"\r\n\r\n  return hn    \r\n\r\nend\r\n\r\n\r\nrequire \'uri\'\r\nrequire \'base64\'\r\n\r\nhis_ip = \"http://170.100.50.240:9292\"\r\nhis_ip = \"http://localhost:9292\"\r\nhis_ip =  get_setting \'his_host\'\r\n\r\nusername = \'jane\'\r\npassword = \'jane\'\r\nhn = 47700094.to_s\r\nusername = params[:un] if params[:un]\r\npassword = params[:ps] if params[:ps]\r\nhn = params[:hn] if params[:hn]\r\n\r\nif hn == \'-\'\r\n  session[:his]=nil\r\n  session[:last_his]=nil\r\n  session.delete \'his\'\r\n  msg=\'logout HIS\'\r\n%>\r\n<!--alert(\"<%=msg%>\");-->\r\nwindow.location.reload();\r\n<%\r\n  \r\nelse # reset login\r\n\r\nunless session[:his]  # if not login then login\r\n\r\n    login_url = his_ip+\'/his/login?username=\'+username+\'&password=\'+password+\'&hn=\'+hn\r\n    uri = URI.parse(login_url)\r\n    http = Net::HTTP.new(uri.host, uri.port); \r\n    http.open_timeout = 5; \r\n    http.read_timeout = 20;\r\n    result= http.get(uri.path+\"?\"+uri.query).body\r\n    if result != \'\'\r\n        object = ActiveSupport::JSON.decode result\r\n        session[:his] = \"\\\\#{username}\" \r\n        session[:last_his] = Time.now\r\n%>\r\n        <!--alert(\'<%=object[\'status\'] %>\')-->\r\n        $(\'#his-status\').text(\'Status <%= object[\'status\'] %>\');\r\n<%\r\n    end\r\n\r\nend  # end login\r\n\r\n# get patient info\r\n\r\ninfo_url = his_ip+\'/his/get_patient_info?username=\'+session[:his]+\'&hn=\'+hn\r\n\r\nuri = URI.parse(info_url)\r\nhttp = Net::HTTP.new(uri.host, uri.port); \r\nhttp.open_timeout = 3; \r\nhttp.read_timeout = 15;\r\n\r\nbegin\r\n\r\n    result= http.get(uri.path+\"?\"+uri.query).body\r\n\r\n    if result != \'\'\r\n        object = ActiveSupport::JSON.decode result\r\n        object[\'hn\']=params[:hn];\r\n        if object[\'picture\'] and object[\'s_hn\']\r\n            doc = Document.find(params[:doc_id])\r\n            ssid = Time.now.to_i.to_s+rand(100).to_s\r\n            @document = @current_project.get_document doc.name\r\n            atts =  @document.attach_field_image \'F6478524829\',\"\\\\#{object[\'hn\']}.png\",ssid,StringIO.new(Base64.decode64(object[\'picture\']))\r\n            if atts\r\n%>\r\n    $.ajax({\r\n            url: \'/esm_image/<%=params[:doc_id]%>/attach_to_gallery?p_id=<%=@current_project.id%>&field_id=F6478524829&ssid=<%=ssid%>&upload=true\',\r\n            data: [],\r\n        	dataType: \'script\',\r\n			type: \'GET\',\r\n			error: function (xhr, status, error) {\r\n			alert(error);\r\n			}\r\n	}).done(function(data){\r\n        alert(\"Picture Inserted\");\r\n    });\r\n<%\r\n            end\r\n        end\r\n    \r\n%>\r\nobject = <%=object.to_json.html_safe%>\r\n$(\"#data-hn\").val(object[\'hn\']);\r\n$(\"#data-public_id\").val(object[\'public_id\']);\r\n//alert(object[\'birth_date\']);\r\n$(\"#data-prefix_name\").val(object[\'prefix\']);\r\n$(\"#input-prefix_name\").val(object[\'prefix\']);\r\n$(\"#data-first_name\").val(object[\'first_name\']);\r\n$(\"#data-last_name\").val(object[\'last_name\']);\r\n$(\"#data-nationality\").val(object[\'nationality\']);\r\n$(\"#data-nationality\").val(object[\'nationality\']);\r\n$(\"#data-nationality\").val(object[\'nationality\']);\r\n$(\"#data-nationality\").val(object[\'nationality\']);\r\n\r\n$(\"#data-born_address\").val(object[\'born_address\']);\r\n$(\"#data-born_tambon\").val(object[\'born_tambon\']);\r\n$(\"#data-born_amphur\").val(object[\'born_amphur\']);\r\n$(\"#data-born_province\").val(object[\'born_province\']);\r\n$(\"#data-born_zipcode\").val(object[\'born_zipcode\']);\r\n$(\"#data-born_country\").val(object[\'born_country\']);\r\n\r\n$(\"#data-contact_address\").val(object[\'contact_address\']);\r\n$(\"#data-contact_tambon\").val(object[\'contact_tambon\']);\r\n$(\"#data-contact_amphur\").val(object[\'contact_amphur\']);\r\n$(\"#data-contact_province\").val(object[\'contact_province\']);\r\n$(\"#data-contact_zipcode\").val(object[\'contact_zipcode\']);\r\n$(\"#data-contact_country\").val(object[\'contact_country\']);\r\n\r\n$(\"#data-occupation\").val(object[\'occupation\']);\r\n$(\"#data-gender\").val(object[\'gender\']);\r\n$(\"#data-marital_status\").val(object[\'marital\']);\r\n\r\n$(\"#data-tel_home\").val(object[\'tel_home\']);\r\n//$(\"#data-tel_office\").val(object[\'lice_tel\']);\r\n$(\"#data-mobile\").val(object[\'mobile\']);\r\n$(\"#data-email\").val(object[\'email\']);\r\n\r\n\r\n$(\"#data-birth_date\").val(object[\'birth_date\']);\r\n$(\"#data-contact_name\").val(object[\'contact_name\']);\r\n$(\"#data-contact_tel\").val(object[\'contact_tel\']);\r\n$(\"#data-contact_desc\").val(object[\'contact_desc\']);\r\n\r\n\r\n    <% else %>\r\n        alert(\"Agent Error\");\r\n    <% end %>\r\n<% rescue  Exception=>e %>\r\nalert(\"Cannot connect Agent <%=e.message%>\");\r\n<% end %>\r\n<% end %>',NULL,NULL,NULL,'2016-10-24 07:57:20','2016-10-24 07:57:20','get_patient_info',''),(2668,'his_login_modal',1072,4,'<div class=\"modal hide fade in\" id=