invalid=\"true\">\r\n                </div>\r\n        \r\n          \r\n                <div class=\"clear\"></div>\r\n                <br>\r\n            <div style=\'float:right\'>\r\n                <input type=\"button\" id=\'commit\' name=\"commit\" value=\"Login\" class=\"btn btn-info\">\r\n                <a href=\"javascript:void(0)\" class=\"btn \" data-dismiss=\"modal\">Cancel</a>  \r\n            </div>\r\n            \r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n<script>\r\n    \r\n    $(document).ready(function(){\r\n        $(\'#commit\').click(function() {\r\n            us = $(\'#input-username\').val();\r\n            ps = $(\'#input-password\').val();\r\n            hn = $(\'#input-hn\').val();\r\n            $(\'#data-hn\').val(hn);\r\n            // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n            console.log(us + \'...\' + ps + \'...\' + hn);\r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n            get_patient_info(us, ps, hn);\r\n            \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            \r\n            // console.log(\'xxxx\');\r\n            // $(\'#his-status\').html(\'Logged as \' + us);\r\n            \r\n            $(\'#his-login\').hide();\r\n            $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n            $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient from HIS</a>\");\r\n            \r\n            $(\'#modal\').modal(\'hide\')\r\n            // $(\'#modal\').attr(\'aria-hidden: false\');\r\n            $(\'.modal-backdrop\').modal(\'hide\')\r\n            \r\n            // $(\'#commit\').click(function() {\r\n            //     console.log(\'login ...\')\r\n            //     us = $(\'#input-username\').val();\r\n            //     ps = $(\'#input-password\').val();\r\n            //     hn = $(\'#input-hn\').val();\r\n            //     get_patient_info(us, ps, hn);\r\n            //     console.log(\'... pass ...\')\r\n            // });\r\n            \r\n            $(\'#his-logout\').click(function() {\r\n        	    $(\'#his-logout\').html(\'Loading ...\');\r\n        	    console.log(\'logout...\')\r\n                get_patient_info(\'-\', \'-\', \'-\');\r\n                // window.location = \'../Home/index\';\r\n        	});\r\n        });\r\n    });\r\n</script>\r\n\r\n                \r\n                </div>\r\n            </div>',NULL,NULL,NULL,'2016-10-24 08:22:33','2016-10-24 08:22:33','his_login_modal',''),(2669,'create',1072,2,'<%\r\n\r\n\r\n\r\ndef get_hn i\r\n  i = i.strip\r\n  n = \'\'\r\n  y = \'\'\r\n  \r\n  return i if i.size<5 or i.size>9\r\n  if i.index \'/\'  \r\n    t = i.split(\"/\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.index \'-\'  \r\n    t = i.split(\"-\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.size==8\r\n    y = i[0..1].to_i\r\n    y2 = i[-2..-1].to_i\r\n    n = i[3..-1].to_i  \r\n    if y2 > y\r\n      y = y2\r\n      n = i[0..-3].to_i    \r\n    end\r\n  else\r\n    y = i[-2..-1]\r\n    n = i[0..-3]\r\n  end\r\n  \r\n  hn = \"\\\\#{n.to_i.to_s}/\\\\#{y}\"\r\n\r\n  return hn    \r\n\r\nend\r\n\r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n      \r\n\r\n      \r\n      \r\n    doc = get_document this.document_name\r\n     if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n    \r\n    rec1 = model.where(:hn=>params[:record][:hn]).first\r\n    # rec2 = model.where(:public_id=>params[:record][:public_id]).first\r\n    # if rec1!=nil or rec2 != nil\r\n    if rec1!=nil\r\n        return_url = \"\\\\#{return_url}patient_id=\\\\#{rec1.id}\"\r\n    %>\r\n    \r\n<span style=\"color:red\"><b>Existing HN or Public ID</b></span><br/>\r\nWill be redirect in 3 seconds\r\n<meta http-equiv=\"Refresh\" content=\"3; url=<%= return_url.html_safe %>\">\r\n    <%\r\n    else\r\n\r\n    if params[:record] and params[:record][:hn]\r\n       \r\n       params[:record][:hn] = get_hn params[:record][:hn]\r\n        \r\n    end    \r\n    \r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n   \r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n    end\r\n\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<%= render :inline=>this.his_login_modal %>',NULL,NULL,NULL,'2016-10-24 08:23:24','2016-10-24 08:23:24','create',''),(2670,'document_name',1073,1,'\'fund\'',NULL,NULL,NULL,'2016-10-24 16:53:55','2016-10-24 16:53:55',NULL,NULL),(2671,'index_partial',950,3,'<%\r\n    main = \'../Home/index\'\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	id = \'\'\r\n	a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = module_model.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n	\r\n	sm = {}\r\n	# form service\r\n	f_ser = {}\r\n	# service_map\r\n	sv =  @current_project.get_services_by_abstract(\'ehr.emr.Document\')\r\n# 	sv.each do |i|\r\n# 	    nm = i[:name]\r\n# 	    if nm == \'appointment\' or nm == \'billing\' or nm == \'live_document\'\r\n# 	        next\r\n# 	    end\r\n	    \r\n# 	    sm[nm.to_sym] = i[:title]\r\n# 	end\r\n    # {\"tumor\":\"Tumor\",\"voice_and_swallowing_evaluation\":\"voice and swallowing evaluation\",\"pre_operative\":\"Pre Operative\",\"lbe_operative\":\"LBE Operative\",\"post_operative\":\"Post Operative\",\"follow_up\":\"Follow up\",\"history\":\"History\",\"endoscopic_exam\":\"Endoscopic Exam\",\"follow_up_document\":\"Follow Up Document\"}\r\n	sm = {\r\n	    :endoscopic_exam=>\"Endoscopic Exam\",\r\n	    :history=>\"History\",\r\n	    :lbe_operative=>\"LBE Operative\",\r\n	    :voice_and_swallowing_evaluation=>\"voice and swallowing evaluation\"\r\n	    \r\n	}\r\n	sm.each do |k, v|\r\n	    f_ser[k] = {}\r\n	    tmp = module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>pa_id).all\r\n	    tmp.each do |i|\r\n	        f_ser[k][i[:patient_id].to_s] = i.id.to_s\r\n	    end\r\n	end\r\n	\r\n	aps.collect!{|i| \r\n        id = i.id\r\n        if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n            pat_id = m.patient_id.to_s\r\n    	     patient = patient_model.find(m.patient_id)\r\n    	     if patient \r\n        	     provider = p_model.find(i.provider)\r\n        	     visit_type = visits[i.visit_type]\r\n        	     provider_name = \'NA\'\r\n        	     provider_name = provider.name if provider\r\n        	     procedure_name = \'NA\'\r\n        	     pro = models[:procedure].find(i.procedure) \r\n        	     procedure_name = pro.name if pro\r\n        	     patient = patient_model.new unless patient \r\n        	     hn = \'-\'\r\n        	     \r\n        	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n        	     provider_name  = link_to(provider_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     procedure_name = link_to(procedure_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     public_id = \'-\'\r\n    	    \r\n                c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id.to_s}\"),\r\n        	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        	     :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Arrived\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n        	     :visit_type=>visit_type,\r\n        	     :note=>i[:note]\r\n                }\r\n                \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info \', :style=>\'width:45px\')\r\n                # v_link = link_to(\'<i class=\"splashy-add\"></i> Add\'.html_safe, \r\n                #     \"../OutPatientForm/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/index\", \r\n                #     :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                # c_link = \'&nbsp;&nbsp;&nbsp;&nbsp;<i class=\"splashy-remove\"></i>\'\r\n                # if f_liv[pat_id]\r\n                #     c_link = \'&nbsp;&nbsp;&nbsp;&nbsp;<i class=\"splashy-check\"></i>\'\r\n                #     v_link = link_to(\'<i class=\"splashy-document_a4\"></i> View\'.html_safe, \r\n                #         \"../OutPatientForm/show?id=\\\\#{f_liv[pat_id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                # end\r\n                # c[:processing_ctrl]= \"\\\\#{v_link} \\\\#{d_link}\".html_safe \r\n                \r\n        l_list = []\r\n        sm.each do |k, v|\r\n                    lab = k.to_s.split(\'_\')[0].humanize\r\n                    v = v.delete(\' \')\r\n                    v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                        \"../\\\\#{v}/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=\\\\#{main}\", \r\n                        :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                    if f_ser[k][pat_id]\r\n                        v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            \"../\\\\#{v}/show?id=\\\\#{f_ser[k][pat_id]}&return=\\\\#{main}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                        # v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            # \"../\\\\#{v}/print?id=\\\\#{f_ser[k][pat_id]}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\', :target=>\'_blank\')\r\n                    end\r\n                    l_list << v_link\r\n        end\\\\#{request.fullpath}\r\n        \r\n                c[:processing_ctrl]= \"\\\\#{d_link}\".html_safe \r\n                c[:processing_ctrl] = \"\\\\#{l_list.join(\' \')} \\\\#{c[:processing_ctrl]}\".html_safe\r\n                \r\n                c\r\n            end\r\n        end\r\n	}.compact!\r\n	\r\n	table_model = %w{ hn patient provider visit_type processing_ctrl note }.collect{|i| i.to_sym}\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:procedure=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n	:note=>\'Note\',:visit_type=>\'Visit\',:processing_ctrl=>\'Actions\', :out_pat=>\'Out Patient Form\' }\r\n	\r\n	%>\r\n	<%# sm.to_json.html_safe %>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=aps.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\'background:#FCF8F0\'>\r\n			                        <div class=\'row-fluid\'>\r\n			                            <table id=\'appointed-patient\' class=\"table table-striped table-bordered dTableR\">\r\n    										<thead>\r\n    											<tr>\r\n<%  table_model.each do |i| %>\r\n    												<th><%= labels[i.to_sym] %></th>\r\n<%  end %>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n    if aps.size > 0\r\n        aps.each do |i|\r\n%>\r\n                                                <tr>\r\n<%\r\n            table_model.each do |j|\r\n                \r\n%>\r\n                                                    <td style=\'vertical-align:middle\'><%= (i[j].nil? or i[j]==\'\') ? \'-\' : i[j] %></td>\r\n<%\r\n            end\r\n%>\r\n                                                </tr>\r\n<%\r\n        end\r\n%>\r\n<% end %>\r\n                                            </tbody>\r\n                                        </table>\r\n                                    </div>\r\n\r\n\r\n<!--\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = aps.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model,:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = aps.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model,:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n-->\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n</div>\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        gebo_datatbles = {\r\n    		dt_a: function() {\r\n    			$(\'#appointed-patient\').dataTable({\r\n    			    stateSave : true,\r\n                    \"sDom\": \"<\'row\'<\'span6\'<\'dt_actions\'>l><\'span6\'f>r>t<\'row\'<\'span6\'i><\'span6\'p>>\",\r\n                    \"sPaginationType\": \"bootstrap_alt\",\r\n                    \"oLanguage\": {\r\n                        \"sLengthMenu\": \"_MENU_ records per page\",\r\n                        \"sEmptyTable\": \"No patient available in table. Please \'<a href=\'javascript:add_patient()\'>Add</a>\' the patient.\"\r\n                    }\r\n                });\r\n    		}\r\n        }\r\n        \r\n        gebo_datatbles.dt_a();\r\n        // gebo_datatbles.state.save();\r\n        \r\n        // $(\'#appointed-patient\').DataTable( {\r\n        //     stateSave: true,\r\n        //     columnDefs: [ {\r\n        //         targets: [ 0 ],\r\n        //         orderData: [ 0, 1 ]\r\n        //     }, {\r\n        //         targets: [ 1 ],\r\n        //         orderData: [ 1, 0 ]\r\n        //     }, {\r\n        //         targets: [ 4 ],\r\n        //         orderData: [ 4, 0 ]\r\n        //     } ]\r\n        // } );\r\n    })\r\n</script>',NULL,NULL,NULL,'2016-10-25 01:10:17','2016-10-25 01:10:17','index_partial',''),(2672,'reprocess',1036,2,'<%\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n\r\n    models = get_model \r\n    \r\n    list = models[:attendance].all\r\n    \r\n    billing_m = models[:billing]\r\n    billing_map = {}\r\n    billing_list = billing_m.collection.find.to_a\r\n    \r\n    mbilling_list = {}\r\n    \r\n    m_billings = module_model.collection.find(:module_id=>{\'$in\'=>billing_list.collect{|i| i[\'_id\']}}).to_a\r\n    for i in m_billings\r\n    \r\n    mbilling_list[i[\'module_id\'].to_s] = i\r\n    \r\n    end\r\n\r\n    \r\n    \r\n    \r\n    \r\n    for i in billing_list\r\n    \r\n        # m_billing = module_model.collection.find(:module_id=>i[\'_id\']).first\r\n    \r\n        m_billing = mbilling_list[i[\'_id\'].to_s]\r\n        \r\n        if m_billing\r\n    \r\n        m_parent = module_model.collection.find(:_id=>m_billing[\'parent_id\']).first\r\n        \r\n        app = models[:appointment].collection.find(:_id=>m_parent[\'module_id\']).first\r\n        if app\r\n        date = app[\'date\'].strftime(\"%d-%m-%Y\")\r\n        billing_map[date] = [] unless billing_map[date]\r\n        billing_map[date] << i\r\n        end\r\n        end\r\n    end\r\n    \r\n    if true\r\n    \r\n    product_m = models[:product]\r\n    product_map = {}\r\n    for i in product_m.collection.find.to_a\r\n        product_map[i[\'_id\']] = i\r\n    end\r\n    \r\n    billing_item_map = {}\r\n    billing_item_m = models[:billing_item]\r\n    for i in billing_list\r\n        billing_item_map[i[\'_id\']] = billing_item_m.collection.find(\'_id\'=>{\'$in\'=>i[\'items\']}).to_a\r\n    end\r\n\r\n    payroll_structure_map = {}\r\n    models[:payroll_structure].all.each do |i|\r\n       payroll_structure_map[i.product_id] = i\r\n    end\r\n    \r\n    provider_map = {}\r\n    \r\n    models[:provider].collection.find.to_a.each do |i|\r\n      provider_map[i[\'_id\']] = i\r\n    end\r\n    \r\n    atm_m = models[:attendance_payroll_item]\r\n    \r\n    atm_list = []\r\n    \r\n    %>\r\n<table>   \r\n<%\r\n    \r\nfor i in list\r\n    date = i.date.strftime(\"%d-%m-%Y\")\r\n    billings = billing_map[date]\r\n    \r\n    a_list = {}\r\n    \r\n    a_list[\'nurse\'] = []\r\n    a_list[\'nurse\'] << provider_map[i[\'n1\']]\r\n    a_list[\'nurse\'] << provider_map[i[\'n2\']]\r\n    a_list[\'nurse\'] << provider_map[i[\'n3\']]\r\n    \r\n    a_list[\'pn\'] = []\r\n    a_list[\'pn\'] << provider_map[i[\'pn1\']]\r\n    a_list[\'pn\'] << provider_map[i[\'pn2\']]\r\n    \r\n    a_list[\'officer\'] = []\r\n    a_list[\'officer\'] << provider_map[i[\'officer1\']]\r\n    \r\n    \r\n    a_list[\'employee\'] = []\r\n    a_list[\'employee\'] << provider_map[i[\'employee1\']]\r\n \r\n    \r\n    \r\n    sum = {}    \r\n    \r\n%>\r\n<tr>\r\n    <td>\r\n        <%=i.date%>\r\n    </td>\r\n</tr>\r\n\r\n<% \r\n\r\nif billings \r\n \r\nfor j in billings \r\n\r\nif j[\'billing_type\']==\'2\'\r\n\r\n    items =  billing_item_map[j[\'_id\']]\r\n    \r\n%>\r\n<tr>\r\n    <td>\r\n        &nbsp;\r\n    </td>\r\n    \r\n    <td>\r\n        <%=j[\'_id\']  %>\r\n    </td>\r\n</tr>\r\n\r\n<% \r\n  \r\nfor k in items \r\n\r\n    product = product_map[k[\'product_id\']]\r\n    \r\n    stc = payroll_structure_map[product[\'_id\']]\r\n    if stc\r\n        \r\n        \r\n%>\r\n\r\n<tr>\r\n    <td>\r\n        &nbsp;\r\n    </td>\r\n     <td>\r\n        &nbsp;\r\n    </td>\r\n    \r\n    <td>\r\n        <%#k.inspect %>\r\n        <%=product[\'name\'] %>    <%=product[\'code\'] %>\r\n    </td>\r\n    \r\n    <% %w{nurse pn officer employee}.each do |x| \r\n    \r\n        \r\n        sum[x] = 0  unless sum[x]\r\n        sum[x] += stc[x].to_i \r\n        \r\n        txt = []\r\n        \r\n        a_list[x].each do|y|\r\n        \r\n            txt << y[\'name\']\r\n            key = \"\\\\#{i[\'_id\']}-\\\\#{y[\'_id\']}-\\\\#{j[\'_id\']}-\\\\#{product[\'_id\']}\"\r\n            \r\n            atm = atm_m.collection.find(:attendance_id=>i[\'_id\'], :provider_id=>y[\'_id\'], :billing_id=>j[\'_id\'], :product_id=>product[\'_id\']).first\r\n            \r\n            unless atm\r\n            \r\n            atm_m.create(:attendance_id=>i[\'_id\'], :provider_id=>y[\'_id\'], :billing_id=>j[\'_id\'], :product_id=>product[\'_id\'], :price=>stc[x].to_i)\r\n            atm_list << {:date=>date, :provider=>y[\'name\'],:product=>product[\'name\'] ,:attendance_id=>i[\'_id\'], :provider_id=>y[\'_id\'], :billing_id=>j[\'_id\'],:product_id=>product[\'_id\'], :price=>stc[x].to_i}\r\n            \r\n            end\r\n            \r\n            \r\n        \r\n        end\r\n    \r\n    %>\r\n    \r\n    <td>\r\n        <%= stc[x] %> (<%=txt.join(\"&nbsp;\").html_safe%>)\r\n    </td>\r\n    \r\n    \r\n    <% end%>\r\n    \r\n    \r\n</tr>\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n<%\r\n        \r\n\r\n%>\r\n\r\n\r\n\r\n<% end %>\r\n<tr>\r\n    <td>Summary</td>\r\n    <td><%=sum.inspect %></td><td><%#a_list.inspect %></td>\r\n</tr>\r\n\r\n<% end %>\r\n\r\n<% end%>\r\n\r\n</table> \r\n<table class=\"table\">\r\n<tbody>\r\n<% for i in atm_list %>\r\n<tr>\r\n<td><%= i[:date] %></td>\r\n<td><%= i[:provider] %></td>\r\n<td><%= i[:product] %></td>\r\n<td><%= i[:price] %></td>\r\n</tr>\r\n<% end %>\r\n</tbody>\r\n</table\r\n\r\n\r\n<% end %>',NULL,NULL,NULL,'2016-10-25 01:10:33','2016-10-25 01:10:33','reprocess',''),(2673,'last_updated',950,3,'<%\r\n    date = Time.now\r\n    if params[:date]\r\n        date = params[:date]\r\n    end\r\n    date = Date.to_mongo(params[:date])\r\n    \r\n    a_app = get_model[:appointment].where(:date=>Date.to_mongo(date)).all\r\n    a_app = a_app.sort_by{|i| i[:updated_at]}.reverse\r\n\r\n\r\n    res = {}\r\n    if !a_app.empty?\r\n        res[:last_updated] = a_app.first[:updated_at]\r\n        res[:app_first] = a_app.first[:updated_at]\r\n        res[:app_last] = a_app.last[:updated_at]\r\n    else\r\n        res[:last_updated] = \"\"\r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2016-10-25 01:26:02','2016-10-25 01:26:02','last_updated',''),(2674,'search',950,2,'<h1> Search Result </h1>\r\n<% \r\n	models = get_model\r\n	\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	\r\n	fields = %w{hn public_id first_name last_name}\r\n	query = \'\'\r\n	if params[:query]\r\n	    query = params[:query].strip\r\n	end\r\n	\r\n	keys = []\r\n	\r\n	keys << {:hn=>Regexp.new(query)}\r\n	keys << {:first_name=>Regexp.new(query)}\r\n	keys << {:last_name=>Regexp.new(query)}\r\n	keys << {:public_id=>query} if query.size==13\r\n	\r\n	criteria = {\'$or\'=>keys}\r\n	\r\n	patients = patient_model.where(criteria).limit(20).all  \r\n	\r\n	app_name = \"\\#{@current_project.name}#appointment\"\r\n	app_model = models[:appointment]\r\n	\r\n\r\n	\r\n	fields.insert(0, \'no\')\r\n	r = 1\r\n%>\r\nResult for \'<%= query %>\' = <%= patients.count %>\r\n<hr/>\r\n<%\r\nif patients.count != 0\r\n%>\r\n<%= tabular :model=>fields,:data=>patients,:n=>10 do |row,out|\r\n	am = module_model.where(:module_name=>\"\\#{app_name}\",:patient_id=>row.id).order(\'date\').last\r\n	if am\r\n        app = app_model.where(:id=>am.module_id).first\r\n	\r\n        if @current_role!=\'pathologist\'\r\n            url = \"../Home/patient_record?id=\\#{am.module_id}\"\r\n        else\r\n            url = \"../Home/patho_patient_record?id=\\#{am.module_id}\"\r\n        end\r\n	\r\n        out[0] = link_to(\"\\#{r}.\", url)\r\n        out[1] = link_to(row.hn,url)\r\n        out[2] = link_to(row.public_id,url)\r\n        out[3] = link_to(row.first_name,url)\r\n        out[4] = link_to(row.last_name,url)\r\n        n = module_model.where(:module_name=>\"\\#{app_name}\",:patient_id=>row.id).count\r\n        	\r\n        extra = link_to(\'Add Visit\', \"../Appointment/create?obj_id=\\#{row.id}&return=../Home/index\", :class=>\'btn btn-mini btn-success\') + \' \' + link_to(\"Detail (\\#{n})\", url, :class=>\'btn btn-mini btn-info\')\r\n        	\r\n        	\r\n        out << extra.html_safe\r\n        r += 1\r\n	else\r\n	    out[0] = \"\\#{r}.\"\r\n        out << link_to(\'Add Visit\', \"../Appointment/create?obj_id=\\#{row.id}&return=../Home/index\", :class=>\'btn btn-mini btn-success\')\r\n	end\r\n	\r\n        out\r\nend\r\n	\r\n%>\r\n<%\r\nelse\r\n%>\r\n<h3>No patient found</h3>\r\n<%= link_to \'New patient\', \"../../www/Patient/create?hn=\\#{params[:query]}&return=/\\#{@current_project.name}/Appointment/create?return=../Home/index\", :class=>\'btn btn-info\' %>\r\n<%\r\nend\r\n%>\r\n<hr/>',NULL,NULL,NULL,'2016-10-25 01:26:51','2016-10-25 01:26:51','search',''),(2675,'print_report',1036,3,'\r\n<html>\r\n    <head>\r\n        <%=include_header%>\r\n    </head>\r\n<style media=\"print\">\r\n    table,th,td{\r\n        border: 0.5px solid black;\r\n        font-size:9px;\r\n    }\r\n    .event{\r\n        background-color:#eee;\r\n    }\r\n</style>\r\n<style>\r\n    table,th,td{\r\n        border: 0.5px solid black;\r\n        font-size:9px;\r\n    }\r\n    \r\n    .event{\r\n        background-color:#eee;\r\n    }\r\n@media print {\r\n    .page {page-break-after: always;}\r\n}\r\n</style>\r\n<body style=\"font-size:0.6em;padding-left:50px\">\r\n<% unless request.post? %>\r\n<%=form_for \'month\', :url=>\'print_report\' do |f| %>\r\n<h1>พิมพ์รายงานอยู่เวร </h1>\r\nSelect Month : <%=f.date_select :query ,:order=>[:month,:year] %>\r\n\r\n<%= f.submit \'Submit\' %>\r\n\r\n<% end %>\r\n\r\n<%= link_to \'check_consistency\', \'reprocess\' %>\r\n<% else %>\r\n<%# params.inspect %>\r\n<% \r\n\r\n    models = get_model \r\n\r\n    provider_map = {}\r\n    \r\n    date = Date.parse(\"\\\\#{params[:month][\'query(1i)\']}-\\\\#{params[:month][\'query(2i)\']}-1\").to_mongo\r\n    \r\n    list = models[:attendance].where(:date=>{\'$gte\'=>date.beginning_of_month,\'$lt\'=>date.end_of_month}).all.sort{|a,b| a.date<=>b.date}\r\n    \r\n    \r\n    \r\n    if list.size > 0 \r\n    providers = models[:provider]\r\n    \r\n    for i in providers\r\n        provider_map[i.id] = i\r\n    end\r\n    \r\n    \r\n    product_m = {}\r\n    models[:product].all.each do |i|\r\n        product_m[i.id] = i \r\n    end\r\n    \r\n    payroll_product_m = {}\r\n    models[:payroll_structure].all.each do |i|\r\n        payroll_product_m[i.product_id] = i \r\n    end\r\n    \r\n    last = 0 \r\n    \r\n    \r\n    omap = {}\r\n    imap = {}\r\n    \r\n    pmap = {}\r\n    pvmap = {}\r\n    l = models[:attendance_payroll_item].where(:attendance_id=>{\'$in\'=>list.collect{|j| j.id}}).all\r\n    \r\n    billing_map = {}\r\n    billings =  models[:billing].find(l.collect{|i| i.billing_id})\r\n    billings.each do |i|\r\n        billing_map[i.id] = i.type_of_patient     \r\n    end\r\n\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    billing_m = module_model.where(:module_name=>\"\\\\#{@current_project.name}#billing\", :module_id=>billings.collect{|i| i.id }).all\r\n    patients = {}\r\n    \r\n    patient_model.find(billing_m.collect{|i| i.patient_id }).each do |i|\r\n        patients[i.id] = [i.hn, \"\\\\#{i.prefix_name}\\\\#{i.first_name} \\\\#{i.last_name}\", i.birth_date]\r\n    end\r\n\r\n    billing_patient = {}\r\n    for  i  in billing_m\r\n        billing_patient[i.module_id] = patients[i.patient_id]\r\n    end\r\n\r\n\r\n    \r\n    a_map = {}\r\n    \r\n    for i in l\r\n        a_map[i.attendance_id] = {} unless a_map[i.attendance_id]\r\n        a_map[i.attendance_id][i.billing_id] = {} unless a_map[i.attendance_id][i.billing_id]\r\n        a_map[i.attendance_id][i.billing_id][i.product_id] = true\r\n    end\r\n \r\n     \r\n    for i in l\r\n    \r\n    \r\n        type = billing_map[i.billing_id]\r\n        \r\n        if type==\'OPD\'\r\n    \r\n        omap[i.provider_id] = {} unless omap[i.provider_id]\r\n        omap[i.provider_id][i.product_id] = [] unless omap[i.provider_id][i.product_id]\r\n        omap[i.provider_id][i.product_id] << i.price\r\n        \r\n        else \r\n        \r\n        imap[i.provider_id] = {} unless imap[i.provider_id]\r\n        imap[i.provider_id][i.product_id] = [] unless imap[i.provider_id][i.product_id]\r\n        imap[i.provider_id][i.product_id] << i.price\r\n        \r\n        end\r\n        \r\n        \r\n        pmap[i.product_id] = true\r\n        \r\n        \r\n    \r\n    end\r\n    \r\n    \r\n    \r\n    plist = pmap.keys\r\n    \r\n    \r\n    plist = payroll_product_m.keys\r\n    \r\n    plist.sort! do |a,b|\r\n       \r\n       x = product_m[a]\r\n       y = product_m[b]\r\n       \r\n       x.short_code <=> y.short_code\r\n        \r\n    end\r\n    \r\n    \r\n    \r\n%>\r\n<style>\r\n.xlabel2 {\r\n  \r\n    /* Rotate div */\r\n\r\n     padding:5px;\r\n \r\n    \r\n    -ms-transform: rotate(-90deg); /* IE 9 */\r\n    -webkit-transform: rotate(-90deg); /* Chrome, Safari, Opera */\r\n    transform: rotate(-90deg);\r\n}\r\n    \r\n</style>\r\n\r\n\r\n<%\r\n\r\n%w{OPD IPD}.each do |z|\r\n    \r\n    if z == \'OPD\' \r\n        map = omap\r\n    else \r\n        map = imap\r\n    end\r\n    \r\n    pxlabel = {\'2\'=>\'nurse\',\'3\'=>\'assist\',\'8\'=>\'officer\',\'10\'=>\'employee\'}\r\n    pxmap = {}\r\n    \r\n    \r\n    for p_id in map.keys \r\n        p = provider_map[p_id]\r\n        pxmap[p.provider_type] = [] unless pxmap[p.provider_type]\r\n        pxmap[p.provider_type] << p.id\r\n    end\r\n    \r\n    \r\n    ix = 0\r\n    vsum = 0 \r\n    \r\n    %>\r\n\r\n    <table  style=\"border:0px;font-size:1.0em\">\r\n        <tr>\r\n            <td style=\"border:0px;width:250px\" valign=\"top\">\r\n                <b>รายงานการอยู่เวรของฝ่ายการพยาบาล</b>\r\n            </td>\r\n            <td  style=\"border:0px\">\r\n                <b>สำนักงานโรงพยาบาลจุฬาลงกรณ์ ห้องส่องกล้อง อาคารผู้ป่วยในพิเศษ\r\n                <br/><br/>\r\n                วันที่ \r\n                <%=thdate Time.now %>\r\n                </b>\r\n            </td>\r\n        </tr>\r\n        <tr>\r\n        <td colspan=\"2\"  style=\"border:0px\">\r\n            <b>\r\n            เรียน ผู้อำนวยการโรงพยาบาลจุฬาลงกรณ์\r\n            <br/>\r\n            <br/>\r\n            อ.นพ.สุภกิจ ขมวิลัย  ตำแหน่ง  หัวหน้าห้องส่องกล้อง Surgical Endoscopy หน่วยศัลยศาสตร์ลำไส้ใหญ่และทวารหนัก \r\n            ขอรายงานการปฏิบัติงานคลินิกพิเศษห้องส่องกล้องอาคารผู้ป่วยในพิเศษ 14 ชั้น \r\n            ตั้งแต่วันที่ \r\n            <%\r\n                start = date.beginning_of_month\r\n                stop = date.end_of_month\r\n            %>\r\n            <%=start.day%>\r\n            <%=thmonth start.month%>\r\n            ถึงวันที่ \r\n            <%=stop.day%>\r\n            <%=thmonth stop.month%>\r\n            พ.ศ. <%=date.year+543%> \r\n            ดังนี้\r\n             </b>\r\n             \r\n        </td>\r\n            \r\n        </tr>\r\n    </table>\r\n   \r\n \r\n    <%\r\n    \r\n    [\'2\',\'3\',\'8\',\'10\'].each_with_index do |pxi, pxix|\r\n    \r\n    px = pxmap[pxi]\r\n    \r\n    \r\n\r\n    cols1 = {}\r\n    cols2 = {}\r\n%>\r\n<div class=\"row-fluid <%=\'page\' if pxix!=3%>\">\r\n\r\n<table class=\"\" border=\"1\" style=\"   border-collapse: collapse; width:100%\">\r\n    <thead style=\"background-color:#fde6d4\">\r\n    <% if pxix!=0 %>\r\n    \r\n        <tr style=\"background-color:#82abde;border-bottom:1px solid\">\r\n        <td></td>\r\n        <td>\r\n            &nbsp;\r\n        </td>\r\n        <td colspan=\"<%=plist.size+1%>\">\r\n            <b><center>ยอดยกมา\r\n        </center></b>\r\n            \r\n        </td>\r\n        <td>\r\n            <%=fn vsum %>\r\n        </td>\r\n          <td>\r\n            &nbsp;\r\n        </td>\r\n    </tr>\r\n    \r\n    \r\n    <% end %>\r\n    \r\n        <tr style=\"\">\r\n        <th rowspan=\"3\">No.</th>\r\n    \r\n        <th  rowspan=\"3\">\r\n            เลขประจำตัว\r\n        </th>\r\n        <th style=\"width:120px\">\r\n            รายชื่อ\r\n        </th>\r\n        \r\n        <th colspan=\"<%=plist.size%>\">\r\n            จำนวนผู้ป่วย (ราย)\r\n        </th>\r\n        <th rowspan=\"3\">\r\n            รวมจ่าย\r\n        </th>\r\n        \r\n        <th  rowspan=\"3\" style=\"width:100px\">\r\n            ลายเซ็นต์\r\n        </th>    \r\n            \r\n        </tr>\r\n        <tr style=\"border-bottom:1px solid;\">\r\n        \r\n            <th>เลขบัตรประชาชน</th>\r\n             <% for i in plist \r\n            p = product_m[i]\r\n            name = p.name\r\n            name = p.short_code if p.short_code\r\n            code = p.code\r\n            code = p.code if code ==\"\"\r\n            \r\n            ps = payroll_product_m[i]\r\n            price = 0\r\n            if ps \r\n                price = ps.nurse \r\n                price = ps.pn if pxix==1\r\n                price = ps.officer if pxix==2\r\n                price = ps.employee if pxix==3 \r\n            end\r\n        %>\r\n        <th  rowspan=\"2\"> <div class=\"xlabel\"><%= name %><br/><%=code%><br/>\r\n            \r\n            (<%=price if ps%>)\r\n            \r\n        </div></th>        \r\n        <% end %>\r\n        </tr>\r\n        <tr>\r\n            <td algin=\"center\">\r\n            <center>\r\n                <b><%=[\'พยาบาล\',\'ผู้ช่วยพยาบาล / เจ้าหน้าที่พยาบาล\' ,\'เจ้าหน้าที่ธุรการ\',\r\n                \'ลูกจ้างประจำ\'][pxix]%></b>\r\n           </center>\r\n            </td>\r\n            \r\n        </tr>\r\n        \r\n    </thead>\r\n<tbody>\r\n\r\n\r\n\r\n    \r\n    <% \r\n        px = [] unless px\r\n    for p_id in px\r\n        p = provider_map[p_id]\r\n        rsum = 0 \r\n        \r\n        row = \'\'\r\n        row = \'event\' if ix%2==1\r\n    %>\r\n    <tr class=\"<%=row%>\">\r\n        <td>\r\n            <center><%=ix+=1%></center>\r\n        </td>\r\n        <td>\r\n            <%=p.ref_number%>\r\n        </td>\r\n        <td>\r\n            <b><%=p.name%></b>\r\n        </td>\r\n        <% for i in plist\r\n            x = map[p.id][i]\r\n            if x\r\n            count = x.size\r\n            cols1[i] = 0 unless cols1[i]\r\n            cols1[i] += count\r\n            \r\n        %>\r\n        <td style=\"\">\r\n            <center><%= count %></center>\r\n        </td>\r\n       \r\n        <% else %>\r\n        <td style=\"\">\r\n           <center>-</center> \r\n        </td>    \r\n        <% end %>\r\n        \r\n        <% end %>\r\n        <td ><center>\r\n          </center>\r\n        </td>\r\n        <td rowspan=\"3\">\r\n            \r\n        </td>\r\n    </tr>\r\n    \r\n    \r\n     <tr class=\"<%=row%>\">\r\n        <td>\r\n            &nbsp;\r\n        </td>\r\n        <td>\r\n            &nbsp;\r\n        </td>\r\n        <td>\r\n           <b>จำนวนเงิน</b>\r\n        </td>\r\n        <% for i in plist\r\n            x = map[p.id][i]\r\n            if x\r\n            count = x.size\r\n            sum =0 \r\n            for j in x\r\n            sum+= j\r\n            end\r\n            rsum += sum\r\n            cols2[i] = 0 unless cols2[i]\r\n            cols2[i] += sum\r\n        %>\r\n        <td style=\"\" >\r\n            <center><%=fn sum %></center>\r\n        </td>\r\n       \r\n        <% else %>\r\n        <td style=\"\">\r\n            <center>-</center>\r\n        </td>    \r\n        <% end %>\r\n        \r\n        <% end \r\n        \r\n          vsum += rsum\r\n        %>\r\n        <td ><center>\r\n            <%=fn rsum%></center>\r\n        </td>\r\n    </tr>\r\n    \r\n    \r\n    \r\n    \r\n    <tr style=\"border-bottom:1px solid\" class=\"<%=row%>\"><%\r\n        n = p.pid\r\n        t = \'-\'\r\n        t = \"\\\\#{n[0]} \\\\#{n[1..4]} \\\\#{n[5..9]} \\\\#{n[10..11]} \\\\#{n[12]}\" if n\r\n    %>  \r\n         <td>\r\n            &nbsp;\r\n        </td>\r\n        <td>\r\n            &nbsp;\r\n        </td>\r\n        <td><%=t%></td>\r\n        <% for i in plist %>\r\n        <td>&nbsp;</td>\r\n        <% end %>\r\n        <td>&nbsp;</td>\r\n    </tr>\r\n\r\n    <% end %>\r\n    \r\n    \r\n    <tr style=\"background-color:#eeeeff\">\r\n        <td></td>\r\n        <td>\r\n            &nbsp;\r\n        </td>\r\n          \r\n        <td>\r\n            รวมจำนวนหัตถาร\r\n        </td>\r\n        <%\r\n        summ = 0 \r\n        for i in plist \r\n        summ+=cols1[i] if cols1[i]\r\n        \r\n        %>\r\n        <td>\r\n         \r\n         <center><%=cols1[i] if cols1[i]%></center>\r\n         \r\n        </td>\r\n        <% end %>\r\n      \r\n        \r\n        \r\n        <td>\r\n            <center><%=fn summ %></center>\r\n        </td>\r\n          <td>\r\n            &nbsp;\r\n        </td>\r\n    </tr>\r\n    \r\n    \r\n\r\n\r\n    <tr style=\"background-color:#eeeeff\">\r\n        <td></td>\r\n        <td>\r\n            &nbsp;\r\n        </td>\r\n          \r\n        <td>\r\n            รวมค่าตอบแทน\r\n        </td>\r\n        <%\r\n        summ = 0 \r\n        for i in plist \r\n        summ+=cols2[i] if cols2[i]\r\n        \r\n        %>\r\n        <td>\r\n         \r\n         <center><%=fn cols2[i] if cols2[i]%></center>\r\n         \r\n        </td>\r\n        <% end %>\r\n      \r\n        \r\n        \r\n        <td>\r\n            <center><%=fn summ %></center>\r\n        </td>\r\n          <td>\r\n            &nbsp;\r\n        </td>\r\n    </tr>\r\n    \r\n    <% if pxix != 3 %>\r\n    <tr style=\"background-color:#82abde\">\r\n        <td></td>\r\n        <td>\r\n            &nbsp;\r\n        </td>\r\n        <td colspan=\"<%=plist.size+1%>\">\r\n            <b><center>ยอดยกไป\r\n        </center></b>\r\n            \r\n        </td>\r\n        <td>\r\n            <%=fn vsum %>\r\n        </td>\r\n          <td>\r\n            &nbsp;\r\n        </td>\r\n    </tr>\r\n    <% end %>\r\n    <% if pxix== 3%>\r\n    \r\n        <tr style=\"background-color:#bace8e\">\r\n        <td></td>\r\n        <td>\r\n            &nbsp;\r\n        </td>\r\n        <td colspan=\"<%=plist.size+1%>\">\r\n            <b><center>รวมเป็นเงินทั้งสิ้น\r\n        </center></b>\r\n            \r\n        </td>\r\n        <td>\r\n            <%=fn vsum %>\r\n        </td>\r\n          <td>\r\n            &nbsp;\r\n        </td>\r\n    </tr>\r\n    <% end %>\r\n    \r\n</tbody>\r\n    \r\n</table>\r\n</div>\r\n\r\n\r\n <% end %>\r\n <br/>\r\n<table class=\"<%=\'page\' if z==\'OPD\'%>\" border=\"0\" style=\"border:0px;font-size:1.0em\" width=\"100%\"> \r\n <tr>\r\n <td style=\"border:0px \" valign=\"top\">\r\n <b>\r\n จำนวนเงิน (ตัวอักษร) <%= thnumber vsum.to_i %>\r\n บาทถ้วน\r\n </b>\r\n</td>\r\n<td style=\"border:0px \">\r\n\r\n <div class=\"span3\">\r\n <b>\r\n ขอรับรองว่าผู้มีรายนามข้างต้นได้มาปฏิบัติงานจริง\r\n <br/> <br/> <br/>\r\n ลงนาม..............................................................<br/>\r\n    <left> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(\r\n          อ.นพ.สุภกิจ ขมวิลัย\r\n          )<br/>\r\nหัวหน้าห้องส่องกล้อง Surgical Endoscopy</left>\r\n    \r\n </b>\r\n </td>\r\n \r\n </tr>\r\n <tr>\r\n <td style=\"border:0px \" >\r\n  อนุมัติ ..............................................................\r\n  <br/><left>\r\n  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ผู้อำนวยการสำนักงาน หรือ ผู้ที่ได้รับมอบหมาย\r\n      \r\n  </left>\r\n</td>\r\n </tr>\r\n</table>\r\n<%  end %>\r\n\r\n<%\r\n\r\n\r\n    products = {}\r\n    models[:product].all.each do |i|\r\n       products[i.id] = i \r\n    end\r\n    \r\n    ptab = {}\r\n    \r\n    for i in list\r\n        bs = a_map[i.id]\r\n        if bs\r\n        for j in bs.keys\r\n            patient = billing_patient[j]\r\n            \r\n            ps = bs[j]\r\n            \r\n            for k in ps.keys\r\n            \r\n            ptab[k] = true\r\n            \r\n            end  \r\n        end\r\n    end\r\n        \r\n    end\r\n    \r\n    \r\n       \r\n     %w{IPD OPD}.each do |type_select|\r\n    \r\n \r\n    \r\n%>\r\n\r\n    \r\n<div class=\'\' style=\"page-break-before: always;\">\r\n<h3><%=type_select%> ประจำเดือน <%=thmonth date.month%></h3>\r\n\r\n\r\n     \r\n        \r\n<table class=\"table\" style=\"width:800px;  border-collapse: collapse;\" >\r\n<thead>\r\n    <tr>\r\n         <th  rowspan=\"2\">ลำดับ</th>\r\n         <th  rowspan=\"2\">วดป.</th>\r\n         <th rowspan=\"2\">Type</th>\r\n         <th  rowspan=\"2\">ชื่อ - นามสกุล</th>\r\n         <th  rowspan=\"2\"> HN </th>\r\n         <th  rowspan=\"2\">อายุ</th>\r\n         \r\n         <th  colspan=\"<%=ptab.keys.size if ptab%>\"><center>หัตถการ</center> </th>\r\n         \r\n         \r\n    </tr>\r\n    <tr>\r\n        \r\n        <% \r\n        \r\n        if ptab\r\n        for x in ptab.keys\r\n            p = products[x]\r\n            code = p.code\r\n            code = p.code if code==\"\"\r\n        %>\r\n        <th><%=p.short_code%><br/><%=code%></th>\r\n        <% end %>\r\n        <% end %>\r\n        \r\n        \r\n    </tr>\r\n</thead>\r\n    <tbody>\r\n    \r\n        \r\n        \r\n        <% \r\n        \r\n           csum={}\r\n        \r\n            index = 0\r\n        list.each_with_index do |i,idx| \r\n        \r\n            bs = a_map[i.id]\r\n            \r\n            bs = {} unless bs\r\n            for j in bs.keys\r\n            \r\n            patient = billing_patient[j]\r\n            ps = bs[j]\r\n            \r\n            type = billing_map[j]\r\n            if type == type_select\r\n        %>\r\n        \r\n        \r\n<% if index%38==0 and index !=0 %>\r\n\r\n<% end %>\r\n\r\n<% if index%38==0 and index !=0   %> \r\n        </tbody>\r\n</table>\r\n<table class=\"table\" style=\"width:800px;  border-collapse: collapse;page-break-before: always; \" >\r\n<thead>\r\n    <tr>\r\n         <th  rowspan=\"2\">ลำดับ</th>\r\n         <th  rowspan=\"2\">วดป.</th>\r\n         <th rowspan=\"2\">Type</th>\r\n         <th  rowspan=\"2\">ชื่อ - นามสกุล</th>\r\n         <th  rowspan=\"2\"> HN </th>\r\n         <th  rowspan=\"2\">อายุ</th>\r\n         \r\n         <th  colspan=\"<%=ptab.keys.size if ptab%>\"><center>หัตถการ</center> </th>\r\n         \r\n         \r\n    </tr>\r\n    <tr>\r\n        \r\n        <% \r\n        \r\n        if ptab\r\n        for x in ptab.keys\r\n            p = products[x]\r\n            code = p.code\r\n            code = p.code if code==\"\"\r\n        %>\r\n        <th><%=p.short_code%><br/><%=code%></th>\r\n        <% end %>\r\n        <% end %>\r\n        \r\n        \r\n    </tr>\r\n</thead>\r\n    <tbody>\r\n    \r\n        \r\n       <% end %> \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        <tr>\r\n        \r\n            <td><%=index+=1%>.</td>\r\n            \r\n             <td>\r\n                <%= i.date.strftime(\"%d-%m-%Y\")  %>\r\n            </td>\r\n            <td>\r\n                <%=type%>\r\n            </td>\r\n            \r\n            <td>\r\n                <%=patient[1] %>\r\n            </td>\r\n            <td>\r\n                <%=patient[0] %>\r\n            </td>\r\n            <td>\r\n                <%=(i.date - patient[2]).to_i/365 if patient[2] %> ปี\r\n            </td>\r\n            \r\n            \r\n            <% for k in  ptab.keys\r\n                csum[k] = 0 unless csum[k]\r\n                csum[k] +=1 if ps[k]\r\n            %>\r\n            <td>\r\n                <%=\"&#10003;\".html_safe if ps[k]%>\r\n            </td>\r\n            <% end %>\r\n        </tr> \r\n           \r\n        <% end %>\r\n        <% end %>\r\n           \r\n           \r\n           <% end %>\r\n        <tr>\r\n               <td colspan=\"6\"><right>รวม</right></td>\r\n               \r\n               <% for k in ptab.keys %>\r\n               <td><%=csum[k]%></td>\r\n               <% end %>\r\n           </tr>\r\n    </tbody>\r\n    \r\n    \r\n</table>\r\n</div>\r\n\r\n<% end %>\r\n\r\n<%  else %>\r\n<div class=\"alert\" ><h1>There is no records</h1></div>\r\n<%=link_to \'Back\', \'print_report\'%>\r\n<%  end %>\r\n<script>\r\n    window.print()\r\n</script>\r\n\r\n<% end %>\r\n</body>\r\n</html>',NULL,NULL,NULL,'2016-10-25 03:05:55','2016-10-25 03:05:55','print_report',''),(2676,'document_name',1074,1,'\'sigmoid\'',NULL,NULL,NULL,'2016-10-25 14:27:00','2016-10-25 14:27:00',NULL,NULL),(2677,'print_partial',1074,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:sigmoid].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto; margin-top:10px;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n  <!--  height:200px; -->\r\n    overflow:hidden;\r\n\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n.thumbnail {\r\n  position: relative;\r\n  width: 300x;\r\n  height: 300px;\r\n  overflow: hidden;\r\n}\r\n.thumbnail img {\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 50%;\r\n  height: 100%;\r\n  width: auto;\r\n  -webkit-transform: translate(-50%,-50%);\r\n      -ms-transform: translate(-50%,-50%);\r\n          transform: translate(-50%,-50%);\r\n}\r\n.thumbnail img.portrait {\r\n  width: 100%;\r\n  height: auto;\r\n}\r\n\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' height=\'70px\' /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Sigmoid</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v><%=record.date_note%></v>&nbsp;&nbsp; Colonoscope by :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n  \r\n   \r\n	  <table width=\"100%\">\r\n	    <tr>\r\n	      <td > <h4 style=\"padding:0px; margin:0px; margin-left:10px\">Status : <%=record[\'status\']%> </h4></td>\r\n	      <td><h4 style=\"padding:0px; margin:0px;margin-left:10px\">Sedation</h4></td>\r\n        </tr>\r\n	    <tr>\r\n      <td width=\"60%\"><p><span style=\"float:left; \"> </span>\r\n        <span style=\"float:left;display:block-inline;\">\r\n				<table width=\"100%\" style=\"margin-left:10px\" >\r\n				<tr>\r\n				  \r\n					<td width=\"300\"><label>Previous opreation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n				 \r\n					<td><label>Bowel Preparation :</label> <v><%=render_value \'bowel_preparation\' %> <%=record[\'bowel_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'bowel_other\'%></v></td>\r\n				</tr>\r\n				<tr>\r\n				\r\n					<td><label>Quality of Preparate :</label> <v><%=record[\'quality_of_preparate\']%></v></td>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \') if record[\'record\']%></v></td>\r\n				\r\n				<tr>\r\n					\r\n					<td width=\"220\"><label>Additional Bowel Preparation :</label> <v><%=render_value \'additional_bowel_preparation\' %> <%=record[\'add_bowel_prep_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'add_bowel_prep_other\'%></v></td>\r\n				</tr>		\r\n				\r\n			</table>	\r\n		</span>\r\n		\r\n \r\n		</p></td>\r\n\r\n<td width=\"40%\"  valign=\"top\">\r\n\r\n<p>\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% any_sedation = false %>\r\n\r\n<tr><td >\r\n<% if record[\'dormicum\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Dormicum :</label> <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Pethidine :</label> <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'drithpivan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Drithpivan :</label> <v><%=record[\'drithpivan_mg\']%> mg <%=record[\'drithpivan_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Diprivan :</label> <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v>  </div>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Valium :</label> <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Buscopan :</label> <v><%=record[\'buscopan_mg\']%> mg <%=record[\'buscopan_route\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'plasil\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Plasil :</label> <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Fentanyl :</label> <v><%=record[\'fentanyl_mg\']%> mcg <%=record[\'fentanyl_routh\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'other\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Other Note :</label> <v><%=record[\'other_note\']%> </v>   </div>\r\n\r\n<% end%>\r\n</td>\r\n  </tr>\r\n\r\n\r\n<tr>\r\n<td><% unless  any_sedation %>\r\n<v>No sedation</v>\r\n<% end %>\r\n</td>\r\n</tr>\r\n</table>\r\n</p></td>\r\n </tr></table>\r\n		\r\n<hr />\r\n\r\n<h4>Scope finding</h4>\r\n<table style=\"padding-left:15px\">\r\n<tr>\r\n    <td width=\"300\">\r\n    <label>Scope pass through : </label><v><%=render_value \'scope\'%></v>\r\n    </td>\r\n    <td width=\"240\">\r\n    <label>Pocedure : </label><v><%=render_value \'procedure\'%></v>\r\n    </td>\r\n    <td><label>Diverticulum : </label><v><%=render_value \'diverticulum\'%></v></td>\r\n</tr>\r\n\r\n</table>\r\n\r\n\r\n\r\n\r\n<% if  a = record[\'procedure_other\']  and a !=\"\" %><label>Note : </label><v><%=render_value \'procedure_other\'%> </v><% end%>\r\n<p style=\"padding-left:10px\">Start at : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<p >\r\n<%\r\n    scopes = %w{rectum_scope sigmoid_scope descending_colon_scope transvers_colon_scope ascending_colon_scope cecum_scope terminal_ileum_scope}\r\n    \r\n    scopes.each_with_index do |j,index|\r\n    if index<record.scope.to_i \r\n    tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    text = \"Normal\"\r\n    tag_cls = \'\'\r\n    if render_value(tag) == \'1\'\r\n    	text =  \"Abnormal\"\r\n    	 tag_cls = \'color:red\'\r\n    end\r\n%>\r\n<p><%= j.humanize %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Type:</td><td>Dx:</td><td>Morphology:</td><td>Size:</td><td>Treatment:</td><td>By:</td><td>Clip:</td><td>Patho No:</td>\r\n<td>Chromo By:</td><td>Kudo:</td><td>Sano:</td><td>NICE:</td><td>JNET:</td><td>Note:</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'endoscopy_dx\']%></v></td><td><v><%=i[\'morphology_type\']%></v></td><td>\r\n<% if i[\'size\']==0%>\r\n<v> -</v>\r\n<% else%>\r\n<v><%=i[\'size\']%> cm.</v>\r\n<% end%>\r\n</td>\r\n<td><v><%=i[\'treatment\']%></v></td>  <td><v><%=i[\'treatment_by\']%></v> </td> <td><v><%=i[\'clip\']%></v></td>               <td><v><%=i[\'patho_number\']%></v></td>\r\n<td><v><%=i[\'chromo\']%></v></td>     <td><v><%=i[\'kudo_type\']%></v></td>     <td><v><%=i[\'sano_type\']%></v></td>          <td><v><%=i[\'nice_classification\']%></v></td>\r\n<td><v><%=i[\'jnet_class\']%></v></td><td><v><%=i[\'abnormal_note\']%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n<hr />\r\n\r\n\r\n<h4>Note</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<% if a= record[\'scope_note\'] and a !=\"\" %><label>Note : </label><v><%=render_value \'scope_note\'%> </v><% end%>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \') if record[\'diagnosis_group\']%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\" class=\"\">\r\n		<%= image_tag i.path+\"?thumb=2\",:style=>\'width:100%; display: block; margin: auto;\' %>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-25 14:30:36','2016-10-25 14:30:36','print_partial',''),(2678,'config',1063,1,'[\r\n{:name=>\'Nurse Records\',:open=>true,:actions=>[\r\n{:name=>\'Consignment\',:service=>\'consignment\',:link=>\'../Consignment/index\',:remote=>false},\r\n{:name=>\'Pre Scope\',:service=>\'pre_scope\',:link=>\'../PreScope/index\',:remote=>false},\r\n{:name=>\'Intra Scope\',:service=>\'intra_scope\',:link=>\'../IntraScope/index\',:remote=>false},\r\n{:name=>\'Post Scope\',:service=>\'post_scope\',:link=>\'../PostScope/index\',:remote=>false}]},\r\n{:name=>\'Endoscopist Records\',:open=>true,:actions=>[\r\n{:name=>\'Colonosopy\',:service=>\'colonoscopy\',:link=>\'../Colonoscopy/index\',:remote=>false},\r\n{:name=>\'Gastroscopy\',:service=>\'gastroscopy\',:link=>\'../Gastroscopy/index\',:remote=>false},\r\n{:name=>\'Enteroscopy\',:service=>\'enteroscopy\',:link=>\'../Enteroscopy/index\',:remote=>false},\r\n{:name=>\'ERCP\',:service=>\'ercp\',:link=>\'../Ercp/index\',:remote=>false},\r\n{:name=>\'EUS\',:service=>\'eus\',:link=>\'../Eus/index\',:remote=>false},\r\n{:name=>\'Bronchoscopy\',:service=>\'bronchoscopy\',:link=>\'../Bronchoscopy/index\',:remote=>false}]},\r\n{:name=>\'ETC\',:open=>true,:actions=>[\r\n{:name=>\'Billing\',:service=>\'billing\',:link=>\'../Billing/index\',:remote=>false},\r\n{:name=>\'Pathology\',:service=>\'pathology\',:link=>\'../Pathology/index\',:remote=>false}]}]\r\n\r\n',NULL,NULL,NULL,'2016-10-25 14:33:57','2016-10-25 14:33:57','config',''),(2679,'print_image',1074,3,'\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div style=\"page-break-after: always\">\r\n<%= render :inline=>this.print_partial, :locals=>{:this=>this} %>\r\n</div>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:sigmoid].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Sigmoid</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n	<p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=record.date_note%></v>&nbsp;&nbsp; Colonoscope by :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n\r\n\r\n\r\n<table width=\"100%\" >\r\n<tr>\r\n  <td valign=\"top\" border=\"1\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<p><label>Note : </label><v><% if a= record[\'scope_note\'] and a !=\"\" %><%=render_value \'scope_note\'%> </v><% end%></p></td>\r\n  <td valign=\"top\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \') if record[\'diagnosis_group\']%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p></td>\r\n</tr>\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<b>Picture :</b><br/>\r\n    <%\r\n        list = record.image\r\n        atts = []\r\n        if list[8...36]\r\n        atts = list[8...36].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        end\r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>?thumb=1\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:40px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n<script>\r\nwindow.print()\r\n</script>\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-25 14:48:05','2016-10-25 14:48:05','print_image',''),(2680,'report_provider',624,3,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    e_model = ehr.load_model\r\n    m_pat = e_model[:patient]\r\n    m_mod = e_model[:patient_module]\r\n    \r\n    m_prov = get_model[:provider]\r\n    a_prov = m_prov.all\r\n    \r\n    prov_ids = a_prov.collect{|i| i.id.to_s}\r\n    \r\n    a_mod  = m_mod.where(:module_id=>prov_ids).all\r\n    g_prov = a_mod.group_by{|i| i[:module_id]}\r\n    \r\n    prov_map = {}\r\n    a_prov.each do |i|\r\n        prov_map[i.id.to_s] = i\r\n    end\r\n    \r\n    k1 = m_mod.where(:module_name=>\"\\\\#{@current_project.name}#knee1\").all\r\n    k2 = m_mod.where(:module_name=>\"\\\\#{@current_project.name}#knee2\").all\r\n    h1 = m_mod.where(:module_name=>\"\\\\#{@current_project.name}#hip1\").all\r\n    h2 = m_mod.where(:module_name=>\"\\\\#{@current_project.name}#hip2\").all\r\n    \r\n    res = {}\r\n    res[:pat] = m_pat.all.count\r\n    res[:prov]  = a_prov.count\r\n    res[:a_mod] = a_mod.count\r\n    res[:g_prov] = g_prov.count\r\n    res[:knee1] = k1.count\r\n    res[:knee2] = k2.count\r\n    res[:hip1] = h1.count\r\n    res[:hip2] = h2.count\r\n    \r\n    view = params[:view].nil? ? \'json\' : params[:view]\r\n    \r\n    if view == \'json\'\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<% \r\n    elsif view = \'csv\'\r\n%>\r\n<% g_prov.each do |k,v| %>\r\n<%= k %>, <%= prov_map[k.to_s] %>, <%= v.count %> <br/>\r\n<% end %>\r\n<% end %>',NULL,NULL,NULL,'2016-10-25 15:53:48','2016-10-25 15:53:48','report_provider',''),(2681,'index',1072,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'index\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2016-10-26 05:26:08','2016-10-26 05:26:08','index',''),(2682,'document_name',1075,1,'\'bronchoscopy_scope_inter\'',NULL,NULL,NULL,'2016-10-27 11:14:58','2016-10-27 11:14:58',NULL,NULL),(2683,'document_name',1076,1,'\'gastroscopy_scope\'',NULL,NULL,NULL,'2016-10-27 14:40:40','2016-10-27 14:40:40',NULL,NULL),(2684,'print_partial',1077,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:colonoscopy].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto; margin-top:10px;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n   height:200px;\r\n    overflow:hidden;\r\n\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n.thumbnail {\r\n  position: relative;\r\n  width: 300x;\r\n  height: 300px;\r\n  overflow: hidden;\r\n}\r\n.thumbnail img {\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 50%;\r\n  height: 100%;\r\n  width: auto;\r\n  -webkit-transform: translate(-50%,-50%);\r\n      -ms-transform: translate(-50%,-50%);\r\n          transform: translate(-50%,-50%);\r\n}\r\n.thumbnail img.portrait {\r\n  width: 100%;\r\n  height: auto;\r\n}\r\n\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' height=\'70px\' /><img src=\'/esm/nci/endo/50.jpg\' height=\'70px\'></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize if @current_user %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colonoscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v><%=record.date_note%></v>&nbsp;&nbsp; Colonoscope by :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n  \r\n   \r\n	  <table width=\"100%\">\r\n	    <tr>\r\n	      <td > <h4 style=\"padding:0px; margin:0px; margin-left:10px\">Status : <%=record[\'status\']%> </h4></td>\r\n	      <td><h4 style=\"padding:0px; margin:0px;margin-left:10px\">Sedation</h4></td>\r\n        </tr>\r\n	    <tr>\r\n      <td width=\"60%\"><p><span style=\"float:left; \"> </span>\r\n        <span style=\"float:left;display:block-inline;\">\r\n				<table width=\"100%\" style=\"margin-left:10px\" >\r\n				<tr>\r\n				  \r\n					<td width=\"300\"><label>Previous opreation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n				 \r\n					<td><label>Bowel Preparation :</label> <v><%=render_value \'bowel_preparation\' %> <%=record[\'bowel_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'bowel_other\'%></v></td>\r\n				</tr>\r\n				<tr>\r\n				\r\n					<td><label>Quality of Preparate :</label> <v><%=record[\'quality_of_preparate\']%></v></td>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \') if record[\'record\']%></v></td>\r\n				\r\n				<tr>\r\n					\r\n					<td width=\"220\"><label>Additional Bowel Preparation :</label> <v><%=render_value \'additional_bowel_preparation\' %> <%=record[\'add_bowel_prep_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'add_bowel_prep_other\'%></v></td>\r\n				</tr>		\r\n				\r\n			</table>	\r\n		</span>\r\n		\r\n \r\n		</p></td>\r\n\r\n<td width=\"40%\"  valign=\"top\">\r\n\r\n<p>\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% any_sedation = false %>\r\n\r\n<tr><td >\r\n<% if record[\'dormicum\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Dormicum :</label> <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Pethidine :</label> <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'drithpivan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Drithpivan :</label> <v><%=record[\'drithpivan_mg\']%> mg <%=record[\'drithpivan_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Diprivan :</label> <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v>  </div>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Valium :</label> <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Buscopan :</label> <v><%=record[\'buscopan_mg\']%> mg <%=record[\'buscopan_route\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'plasil\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Plasil :</label> <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Fentanyl :</label> <v><%=record[\'fentanyl_mg\']%> mcg <%=record[\'fentanyl_routh\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'other\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Other Note :</label> <v><%=record[\'other_note\']%> </v>   </div>\r\n\r\n<% end%>\r\n</td>\r\n  </tr>\r\n\r\n\r\n<tr>\r\n<td><% unless  any_sedation %>\r\n<v>No sedation</v>\r\n<% end %>\r\n</td>\r\n</tr>\r\n</table>\r\n</p></td>\r\n </tr></table>\r\n		\r\n<hr />\r\n\r\n<h4>Scope finding</h4>\r\n<table style=\"padding-left:15px\">\r\n<tr>\r\n    <td width=\"300\">\r\n    <label>Scope pass through : </label><v><%=render_value \'scope\'%></v>\r\n    </td>\r\n    <td width=\"240\">\r\n    <label>Pocedure : </label><v><%=render_value \'procedure\'%></v>\r\n    </td>\r\n    <td><label>Diverticulum : </label><v><%=render_value \'diverticulum\'%></v></td>\r\n</tr>\r\n\r\n</table>\r\n\r\n\r\n\r\n\r\n<% if  a = record[\'procedure_other\']  and a !=\"\" %><label>Note : </label><v><%=render_value \'procedure_other\'%> </v><% end%>\r\n<p style=\"padding-left:10px\">Start at : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<p >\r\n<%\r\n    scopes = %w{rectum_scope sigmoid_scope descending_colon_scope transvers_colon_scope ascending_colon_scope cecum_scope terminal_ileum_scope}\r\n    \r\n    scopes.each_with_index do |j,index|\r\n    if index<record.scope.to_i \r\n    tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    text = \"Normal\"\r\n    tag_cls = \'\'\r\n    if render_value(tag) == \'1\'\r\n    	text =  \"Abnormal\"\r\n    	 tag_cls = \'color:red\'\r\n    end\r\n%>\r\n<p><%= j.humanize %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Type:</td><td>Dx:</td><td>Morphology:</td><td>Size:</td><td>Treatment:</td><td>By:</td><td>Clip:</td><td>Patho No:</td>\r\n<td>Chromo By:</td><td>Kudo:</td><td>Sano:</td><td>NICE:</td><td>JNET:</td><td>Note:</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'endoscopy_dx\']%></v></td><td><v><%=i[\'morphology_type\']%></v></td><td>\r\n<% if i[\'size\']==0%>\r\n<v> -</v>\r\n<% else%>\r\n<v><%=i[\'size\']%> cm.</v>\r\n<% end%>\r\n</td>\r\n<td><v><%=i[\'treatment\']%></v></td>  <td><v><%=i[\'treatment_by\']%></v> </td> <td><v><%=i[\'clip\']%></v></td>               <td><v><%=i[\'patho_number\']%></v></td>\r\n<td><v><%=i[\'chromo\']%></v></td>     <td><v><%=i[\'kudo_type\']%></v></td>     <td><v><%=i[\'sano_type\']%></v></td>          <td><v><%=i[\'nice_classification\']%></v></td>\r\n<td><v><%=i[\'jnet_class\']%></v></td><td><v><%=i[\'abnormal_note\']%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n<%\r\n    if !record[\'intervention_summary\'].nil? and record[\'intervention_summary\'] != \'\'\r\n%>\r\nIntervention Summary : \r\n<blockquote>\r\n    <%= render_value \'intervention_summary\' %>\r\n</blockquote>\r\n<%\r\n    end\r\n%>\r\n<hr />\r\n\r\n\r\n<h4>Note</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<% if a= record[\'scope_note\'] and a !=\"\" %><label>Note : </label><v><%=render_value \'scope_note\'%> </v><% end%>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \') if record[\'diagnosis_group\']%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n    <div style=\"float:left;width:220px\">\r\n	<div id=\"box\" class=\"thumbnail\" style=\"float:none\">\r\n		<%= image_tag i.path+\"?thumb=2\",:style=>\'display: block; margin: auto;\' %>\r\n	</div>\r\n	<v align=\"center\" style=\"display:block;\" ><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-31 06:11:42','2016-10-31 06:11:42','print_partial','*'),(2685,'form',1074,3,'<script>\r\nfunction inject(fid){\r\n\r\n\r\n    $(document).ready(function(){\r\n        \r\n        \r\n    $(\'#\'+fid+\'endoscopy_dx\').change(function(){\r\n      var str = $(this).find(\":selected\").val()\r\n \r\n      \r\n      switch (str) {\r\n      case \'Adenomatous polyp\':\r\n          fill(fid,1)\r\n      break;\r\n      case \'Hyperplastic polyp\':\r\n          fill(fid,2)\r\n      break;\r\n      case \'Sessile Serrated Adenoma\':\r\n          fill(fid,3)\r\n      break;\r\n      }\r\n\r\n    });\r\n\r\n    \r\n    \r\n    \r\nfunction fill(fid,number){\r\n    \r\n    \r\n    kudo_type = $(\'#data-\'+fid+\'kudo_type\')\r\n    sano_type = $(\'#data-\'+fid+\'sano_type\')\r\n    nice_classification = $(\'#data-\'+fid+\'nice_classification\')\r\n    jnet_class = $(\'#data-\'+fid+\'jnet_class\')\r\n    \r\n    treatment = $(\'#data-\'+fid+\'treatment\')\r\n    treatment_by = $(\'#data-\'+fid+\'treatment_by\')\r\n    clip = $(\'#data-\'+fid+\'clip\')\r\n    \r\n    \r\n    \r\n    // treatment Total removed\r\n    // treatment_by EMR\r\n    // clip    Done\r\n    \r\n    treatment.val(\'Total removed\')\r\n    treatment_by.val(\'EMR\')\r\n    clip.val(\'Done\')\r\n    \r\n    \r\n    \r\n    // alert(\"\"+fid+\"\"+number+kudo_type.val())\r\n    switch(number){\r\n        case 1:\r\n           kudo_type.val(\'IIIs\')\r\n           sano_type.val(\'II\')\r\n           nice_classification.val(\'II\')\r\n           jnet_class.val(\'2a\')\r\n        break;\r\n        case 2:\r\n           kudo_type.val(\'II\')\r\n           sano_type.val(\'I\')\r\n           nice_classification.val(\'I\')\r\n           jnet_class.val(\'1\')\r\n        break;\r\n        case 3:\r\n           kudo_type.val(\'II\')\r\n           sano_type.val(\'II\')\r\n           nice_classification.val(\'I serrated\')\r\n           jnet_class.val(\'2a\')\r\n        break;\r\n            \r\n    }\r\n    \r\n    update_treatment()\r\n    \r\n    \r\n}\r\n    \r\n    function update_treatment(){\r\n        \r\n        var all_treatment = [];\r\n        \r\n        $(\'.treatment_by\').each(function(){\r\n            \r\n        \r\n        var str = $(this).find(\":selected\").val()\r\n        var s  = \'\'\r\n        if(str==\'Cold polypectomy\'||str==\'Hot polypectomy\')s = \'Polypectomy\'\r\n        if(str==\'Cold biopsy\'||str==\'Hot biopsy\')s = \'Bx\'\r\n        if(str==\'EMR\'||str==\'EMR-C\')s = \'EMR\'\r\n        if(str==\'ESD\'){\r\n            s = \'ESD\'\r\n        \r\n              $(\'#data-project\').val(\'ESD\');\r\n                update_project_rev_func();\r\n            \r\n        }\r\n        if(str==\'APC\')s = \'APC\'\r\n        if(str==\'Coagulation\')s = \'Cauterized bleeding\'\r\n        if(str==\'EPMR\')s = \'EPMR\'\r\n        if(str==\'Precut EMR\')s = \'Precut EMR\'\r\n        \r\n        // alert(s)\r\n           \r\n        all_treatment.push(s);    \r\n            \r\n        })\r\n        \r\n        \r\n         $(\'.tattoo\').each(function(){\r\n            \r\n        \r\n        var str = $(this).find(\":selected\").val()\r\n        var s = \'\'\r\n        if(str==\'Done\')s = \'Tattoo\'\r\n        \r\n        // alert(s)\r\n           \r\n        all_treatment.push(s);    \r\n            \r\n        })\r\n        \r\n        \r\n        \r\n        all_treatment = jQuery.unique(all_treatment);\r\n        // alert(all_treatment)\r\n        \r\n        $(\'#data-procedure\').val(all_treatment.join(\"|\"));\r\n        \r\n        update_procedure_rev_func();\r\n        \r\n        \r\n    }\r\n    \r\n    \r\n    proc =  $(\'#data-\'+fid+\'treatment_by\');\r\n    proc.addClass(\'treatment_by\');\r\n    proc.change(function(){\r\n        update_treatment()   \r\n    });\r\n    \r\n    \r\n    proc =  $(\'#data-\'+fid+\'tattoo\');\r\n    proc.addClass(\'tattoo\');\r\n\r\n\r\n\r\n    \r\n    $(\'#data-\'+fid+\'tattoo\').change(function(){\r\n           update_treatment()   \r\n    });\r\n    \r\n    });\r\n    \r\n}\r\n\r\n\r\n</script>\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   \r\n  \r\n%>\r\n<%\r\n    if @current_role==\'capture\' or @current_role==\'developer\'\r\n%>\r\n    <div class=\"alert\">\r\n		<!--<h4 class=\"alert-heading\">Endo Button</h4>-->\r\n		<div style=\'float:left\' id=\'btn-form\'>&nbsp;</div>\r\n		<div style=\'float:right\' id=\'btn-snap\'>&nbsp;</div>\r\n		<br/>\r\n		&nbsp;\r\n	</div>\r\n<%\r\n    end\r\n%>\r\n<div id=\'prescope\' >Loading..PreScope information</div>\r\n<script>\r\n\r\n//  add snap button on the top\r\n    $(document).ready(function() {\r\n<%\r\n    if (@current_role==\'capture\' or @current_role==\'developer\')\r\n        if params[:opt] == \'create\' or params[:opt] == \'edit\'\r\n%>\r\n        frm_submit = $(\'#record-submit\').clone();\r\n        frm_cancel = $(\'#record-submit\').next().clone();\r\n        frm_cancel = frm_cancel.addClass(\'btn btn-small\')\r\n        frm_submit = frm_submit.addClass(\'btn btn-success btn-small\')\r\n        \r\n        btn_form = $(\'#btn-form\');\r\n        btn_form.append(frm_submit);\r\n        btn_form.append(\'&nbsp;&nbsp;|&nbsp;&nbsp;\');\r\n        btn_form.append(frm_cancel);\r\n        \r\n        // $(\'#record-submit\').click(function() {\r\n        //     if ($(\'#data-stop_at\').val() == \"\") {\r\n        //         d = new Date();\r\n        //         $(\'#data-stop_at\').val(d.getHours() + \":\" + d.getMinutes());\r\n        //     }\r\n        // });\r\n\r\n<%\r\n        end\r\n%>\r\n        snap = $( \"a:contains(\'Snap\')\" ).clone();\r\n        snap = snap.addClass(\'btn btn-small btn-info\');\r\n        btn_snap = $(\'#btn-snap\');\r\n        btn_snap.append(snap);\r\n        \r\n        $(\'input\').prop(\'required\', null);\r\n        $(\'select\').prop(\'required\', null);\r\n<%\r\n    end\r\n%>\r\n    })\r\n\r\n<%\r\n\r\n url = \"../PreScope/pre_scope_detail?id=\\#{params[:id]}\"\r\n url = \"../PreScope/pre_scope_detail?parent_id=\\#{params[:parent_id]}\" if params[:parent_id]\r\n \r\n%>\r\n\r\n$.ajax({\r\n  url: \"<%=url%>\",\r\n  context: document.body\r\n}).done(function(data) { \r\n  $(\'#prescope\').html(data);\r\n <% unless params[:id] %>\r\n $(\'#data-bowel_preparation\').val(pre_scope[\"bowel_preparation\"]);\r\n $(\'#data-additional_bowel_preparation\').val(pre_scope[\"add_bowel_prep\"]);\r\n\r\n $(\'#data-bowel_cc\').val(pre_scope[\"bowelprep_cc\"]);\r\n $(\'#data-bowel_other\').val(pre_scope[\"bowel_other_note\"]);\r\n $(\'#data-add_bowel_prep_cc\').val(pre_scope[\"add_bowel_prep_cc\"]);\r\n $(\'#data-add_bowel_prep_other\').val(pre_scope[\"add_bowel_other\"]);\r\n \r\n <% end %> \r\n\r\n});\r\n</script>\r\n\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n\r\n$(\'#data-procedure\').bind(\"change\", function (){\r\n    \r\n    v = $(this).val()\r\n    if(v.indexOf(\'ESD\')>=0){\r\n        $(\'#data-project\').val(\'ESD\');\r\n         update_project_rev_func();\r\n    }\r\n    if(v.indexOf(\'Stent\')>=0){\r\n        $(\'#data-project\').val(\'Stent\');\r\n         update_project_rev_func();\r\n    }\r\n    if(v.indexOf(\'ESD\')>=0 && v.indexOf(\'Stent\')>=0){\r\n        $(\'#data-project\').val(\'Stent\');\r\n         update_project_rev_func();\r\n    }\r\n    \r\n    \r\n    \r\n     \r\n    \r\n});\r\n\r\n\r\nsedative = [\'dormicum\',\'pethidine\',\'diprivan\',\'valium\',\'buscopan\',\'plasil\',\'fentanyl\',\'other\']\r\nfunction check_sedative(ele){\r\n   check = ele.prop(\"checked\");\r\n   id = ele.prop(\"id\");\r\n   t = id.split(\'-\')[1];\r\n   if(check)\r\n   $(\".\"+t+\'\').css(\"display\",\"block\");\r\n   else\r\n   $(\".\"+t+\'\').css(\"display\",\"none\");\r\n}\r\n\r\nfor(i=0;i<sedative.length;i++){\r\n t = sedative[i];  \r\n ele = $(\'#data-\'+t);\r\nele.change(function(){\r\n    check_sedative($(this));\r\n});\r\n check_sedative(ele);\r\n}\r\n//$(\'#data-dormicum_mg\').val(323)\r\n//$(\'#data-dormicum_mg\').prop(\'disabled\', true);\r\n//$(\'#data-dormicum_num\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_mg\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_num\').prop(\'disabled\', true);\r\n\r\nvar scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\nfunction refresh(ele){\r\n    for(i=0;i<scope_list.length;i++){\r\n      $(\".\"+scope_list[i]).css(\"display\",\"none\");\r\n   }\r\n    index = $(ele).prop(\"selectedIndex\");\r\n   for(i=0;i<index;i++){\r\n       $(\".\"+scope_list[i]).css(\"display\",\"block\");\r\n   }\r\n}\r\n\r\nrefresh($(\'#data-scope\'));\r\n\r\n$(\"#data-scope\").change(function(){\r\nrefresh(this);\r\n});\r\n\r\n\r\n$(\".diag\").change(function(){\r\n    \r\n   e = $(\"#data-\"+this.id).val();\r\n   p = $(\"#data-patient_status\");\r\n   if(e==\"1\"){\r\n     $.sticky(\"Select Abnormal\", {autoclose : 5000, position: \"top-right\" });\r\n     p.val(\"Abnormal\");    \r\n   }\r\n});\r\n\r\n\r\n  \r\n\r\n$(\'#data-diagnosis_group\').bind(\"change\", function() {\r\n       v = $(this).val() \r\n    //   alert(v)\r\n       if(v!=\'Normal\'){\r\n           $(this).val(v.replace(\'Normal|\',\'\')) \r\n          $(\'#update_diagnosis_group_item_0\').attr(\'checked\', false);\r\n       }\r\n          v = $(this).val() \r\n        var $cbx = $(\"#data-diagnosis_note\").data(\"kendoComboBox\")\r\n        $cbx.value(v.replace(/\\\\|/g,\',\'))\r\n        if(v.indexOf(\'Serrated\')>=0){\r\n            $(\'#data-project\').val(\'Serrated polyp\');\r\n            update_project_rev_func();\r\n        }\r\n\r\n    //   $(\'#data-diagnosis_note\').kendoComboBox().value(\'oiwjfoiwejfoijwef\');\r\n       \r\n     \r\n     \r\n \r\n });\r\n \r\n\r\n</script>',NULL,NULL,NULL,'2016-10-31 06:20:59','2016-10-31 06:20:59','form',''),(2686,'print_partial',1079,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    gas_id = pm.module_id\r\n    record = models[:gastroscopy].find(gas_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px;padding-left:20px;padding-right:20px }\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\nheight:200px; \r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n.thumbnail {\r\n  position: relative;\r\n  width: 300x;\r\n  height: 300px;\r\n  overflow: hidden;\r\n}\r\n.thumbnail img {\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 50%;\r\n  height: 100%;\r\n  width: auto;\r\n  -webkit-transform: translate(-50%,-50%);\r\n      -ms-transform: translate(-50%,-50%);\r\n          transform: translate(-50%,-50%);\r\n}\r\n.thumbnail img.portrait {\r\n  width: 100%;\r\n  height: auto;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' height=\'70px\' /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize   if @current_user %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Gastroscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=record.date_note%></v>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n<hr />\r\n    \r\n		<table width=\"100%\"><tr><td width=\"60%\" valign=\"top\">\r\n		\r\n		\r\n     <h4 style=\"padding:0px; margin:0px; margin-left:10px;margin-bottom:5px \">Status : <%=record[\'status\']%> </h4>\r\n						<table width=\"100%\">\r\n				<tr>\r\n					<td><label>Previous opreation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n					<td><label>NPO time (Hours) :</label> <v><%=render_value \'npotime\' %></v></td>\r\n					<td></td>\r\n				</tr>\r\n				<tr>\r\n					<td><label>Quality of Preparate :</label><v> <%=record[\'quality_of_preparate\']%></v></td>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \')%></v></td>\r\n				\r\n				</tr>		\r\n				\r\n			</table>	\r\n		\r\n		<div class=\"clear\"></div>\r\n		\r\n		\r\n</td>\r\n		    <td valign=\"top\" width=\"40%\"><h4 style=\"padding:0px; margin:0px; margin-left:10px; margin-bottom:5px\">Sedation</h4>\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% if record[\'dormicum\']==\'true\'%>\r\n<tr><td>Dormicum : <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'%>\r\n<tr><td>Pethidine : <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'%>\r\n<tr><td>Buscopan : <v><%=record[\'buscopan_mg\']%> mg <%=record[\'route_buscopan\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'%>\r\n<tr><td>Fentanyl : <v><%=record[\'mg_fentanyl\']%> mg <%=record[\'fentanyl_route\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'%>\r\n<tr><td>Diprivan : <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'%>\r\n<tr><td>Valium : <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v> </td></tr>\r\n<% end%>\r\n\r\n<% if record[\'plasil\']==\'true\'%>\r\n<tr><td>Plasil : <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v> </td></tr>\r\n<% end%>\r\n\r\n<% if record[\'other\']==\'true\'%>\r\n<tr><td>Other Note : <v><%=record[\'other_note\']%> </v> </td></tr>\r\n<% end%>\r\n</table></td>\r\n		</tr>\r\n\r\n</table>\r\n\r\n<hr />\r\n<h4>Scope finding</h4>\r\n&nbsp;&nbsp;<label>Scope pass through : </label><v><%=render_value \'scope\'%> <i></i></v>&nbsp;\r\n&nbsp;&nbsp;<label>Esophagitis LA Class : </label><v><%=render_value \'esophagitis_la_class\'%> <i></i></v>&nbsp;\r\n<label>Pocedure : </label><v><%=render_value \'procedure\'%> <i></i></v><br />\r\n<p>Start at : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<div class=\"clear\"></div>\r\n\r\n<table width=\"850\"><tr>\r\n<td><span class=\"\"><label>Z line at (cm.) : </label></span>	\r\n<v><%=render_value \'z_line\'%></v></td>\r\n<td><span class=\"\"><label>EGJ at (cm.) : </label></span>	\r\n<v><%=render_value \'egj_at\'%></v></td>\r\n<td><span class=\"\"><label>Sliding Hernia : </label></span>	\r\n<v><%=render_value \'sliding_hernia\'%></v></td>\r\n<td><span class=\"\"><label>Ampulla of Vater : </label></span>	\r\n<v><%=render_value \'ampulla_of_vater\'%></v></td>\r\n</tr>\r\n\r\n<tr>\r\n    <td><span class=\"\"><label>H.Pylori test: </label></span>	\r\n<v><%=render_value \'hpylori_test\'%></v></td>\r\n</tr>\r\n\r\n\r\n</table>\r\n\r\n<%\r\n    scopes_labels = {\'egj_scope\'=>\'EGJ\'}\r\n\r\n    scopes = %w{pharynx_scope esophagus_scope egj_scope fundus_scope cardia_scope body_scope antrum_scope first_duodenum_scope sphincter_of_oddi_scope second_duodenum_scope third_duodenum_scope forth_duodenum_scope proximal_jejunum_scope distal_jejunum_scope}\r\n\r\n    scopes.each_with_index do |j,index|\r\n    if index<record.scope.to_i \r\n    tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    \r\n    \r\n    \r\n    text = \"Normal\"\r\n    tag_cls = \'\'\r\n    if record[tag] == \'1\'\r\n    	text =  \"Abnormal\"\r\n    	 tag_cls = \'color:red\'\r\n    end\r\n    label = tag.humanize\r\n    label = scopes_labels[j] if scopes_labels[j]\r\n    \r\n%>\r\n<p><%= label %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Abnormal Type :</td><td>Endoscopy Dx :</td><td>Morphology Type :</td><td>Size (cm.) :</td><td>Treatment :</td><td>By :</td><td>Clip :</td><td>Patho No. :</td><td>Abnormal Note :</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n      size= \'-\'\r\n      size = i[\'size\'] if i[\'size\']!=0\r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'endoscopy_dx\']%></v></td><td><v><%=i[\'morphology_type\']%></v></td><td><v><%=size%></v></td><td><v><%=i[\'treatment\']%></v></td><td> <v><%=i[\'treatment_by\']%></v> </td><td><v><%=i[\'clip\']%></v></td><td><v><%=i[\'patho_number\']%></v></td><td><v><%=i[\'abnormal_note\']%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n<%\r\n    if !record[\'intervention_summary\'].nil? and record[\'intervention_summary\'] != \'\'\r\n%>\r\nIntervention Summary : \r\n<blockquote>\r\n    <%= render_value \'intervention_summary\' %>\r\n</blockquote>\r\n<%\r\n    end\r\n%>\r\n<hr />\r\n\r\n<h4>Note :</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \')%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n    <p>Note: <v><%=record[\'scope_note\']%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	 <div style=\"float:left;width:220px\">\r\n	<div id=\"box\" class=\"thumbnail\" style=\"float:none\">\r\n		<%= image_tag i.path+\"?thumb=2\",:style=>\'display: block; margin: auto;\' %>\r\n	</div>\r\n	<v align=\"center\" style=\"display:block;\" ><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2016-10-31 06:22:52','2016-10-31 06:22:52','print_partial','*'),(2688,'form',1077,3,'<script>\r\nfunction inject(fid){\r\n\r\n\r\n    $(document).ready(function(){\r\n        \r\n        \r\n    $(\'#\'+fid+\'endoscopy_dx\').change(function(){\r\n      var str = $(this).find(\":selected\").val()\r\n \r\n      \r\n      switch (str) {\r\n      case \'Adenomatous polyp\':\r\n          fill(fid,1)\r\n      break;\r\n      case \'Hyperplastic polyp\':\r\n          fill(fid,2)\r\n      break;\r\n      case \'Sessile Serrated Adenoma\':\r\n          fill(fid,3)\r\n      break;\r\n      }\r\n\r\n    });\r\n\r\n    \r\n    \r\n    \r\nfunction fill(fid,number){\r\n    \r\n    \r\n    kudo_type = $(\'#data-\'+fid+\'kudo_type\')\r\n    sano_type = $(\'#data-\'+fid+\'sano_type\')\r\n    nice_classification = $(\'#data-\'+fid+\'nice_classification\')\r\n    jnet_class = $(\'#data-\'+fid+\'jnet_class\')\r\n    \r\n    treatment = $(\'#data-\'+fid+\'treatment\')\r\n    treatment_by = $(\'#data-\'+fid+\'treatment_by\')\r\n    clip = $(\'#data-\'+fid+\'clip\')\r\n    \r\n    \r\n    \r\n    // treatment Total removed\r\n    // treatment_by EMR\r\n    // clip    Done\r\n    \r\n    treatment.val(\'Total removed\')\r\n    treatment_by.val(\'EMR\')\r\n    clip.val(\'Done\')\r\n    \r\n    \r\n    \r\n    // alert(\"\"+fid+\"\"+number+kudo_type.val())\r\n    switch(number){\r\n        case 1:\r\n           kudo_type.val(\'IIIs\')\r\n           sano_type.val(\'II\')\r\n           nice_classification.val(\'II\')\r\n           jnet_class.val(\'2a\')\r\n        break;\r\n        case 2:\r\n           kudo_type.val(\'II\')\r\n           sano_type.val(\'I\')\r\n           nice_classification.val(\'I\')\r\n           jnet_class.val(\'1\')\r\n        break;\r\n        case 3:\r\n           kudo_type.val(\'II\')\r\n           sano_type.val(\'II\')\r\n           nice_classification.val(\'I serrated\')\r\n           jnet_class.val(\'2a\')\r\n        break;\r\n            \r\n    }\r\n    \r\n    update_treatment()\r\n    \r\n    \r\n}\r\n    \r\n    function update_treatment(){\r\n        \r\n        var all_treatment = [];\r\n        \r\n        $(\'.treatment_by\').each(function(){\r\n            \r\n        \r\n        var str = $(this).find(\":selected\").val()\r\n        var s  = \'\'\r\n        if(str==\'Cold polypectomy\'||str==\'Hot polypectomy\')s = \'Polypectomy\'\r\n        if(str==\'Cold biopsy\'||str==\'Hot biopsy\')s = \'Bx\'\r\n        if(str==\'EMR\'||str==\'EMR-C\')s = \'EMR\'\r\n        if(str==\'ESD\'){\r\n            s = \'ESD\'\r\n        \r\n              $(\'#data-project\').val(\'ESD\');\r\n                update_project_rev_func();\r\n            \r\n        }\r\n        if(str==\'APC\')s = \'APC\'\r\n        if(str==\'Coagulation\')s = \'Cauterized bleeding\'\r\n        if(str==\'EPMR\')s = \'EPMR\'\r\n        if(str==\'Precut EMR\')s = \'Precut EMR\'\r\n        \r\n        // alert(s)\r\n           \r\n        all_treatment.push(s);    \r\n            \r\n        })\r\n        \r\n        \r\n         $(\'.tattoo\').each(function(){\r\n            \r\n        \r\n        var str = $(this).find(\":selected\").val()\r\n        var s = \'\'\r\n        if(str==\'Done\')s = \'Tattoo\'\r\n        \r\n        // alert(s)\r\n           \r\n        all_treatment.push(s);    \r\n            \r\n        })\r\n        \r\n        \r\n        \r\n        all_treatment = jQuery.unique(all_treatment);\r\n        // alert(all_treatment)\r\n        \r\n        $(\'#data-procedure\').val(all_treatment.join(\"|\"));\r\n        \r\n        update_procedure_rev_func();\r\n        \r\n        \r\n    }\r\n    \r\n    \r\n    proc =  $(\'#data-\'+fid+\'treatment_by\');\r\n    proc.addClass(\'treatment_by\');\r\n    proc.change(function(){\r\n        update_treatment()   \r\n    });\r\n    \r\n    \r\n    proc =  $(\'#data-\'+fid+\'tattoo\');\r\n    proc.addClass(\'tattoo\');\r\n\r\n\r\n\r\n    \r\n    $(\'#data-\'+fid+\'tattoo\').change(function(){\r\n           update_treatment()   \r\n    });\r\n    \r\n    });\r\n    \r\n}\r\n\r\n\r\n</script>\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   \r\n  \r\n%>\r\n<%\r\n    if @current_role==\'capture\' or @current_role==\'developer\'\r\n%>\r\n    <div class=\"alert\">\r\n		<!--<h4 class=\"alert-heading\">Endo Button</h4>-->\r\n		<div style=\'float:left\' id=\'btn-form\'>&nbsp;</div>\r\n		<div style=\'float:right\' id=\'btn-snap\'>&nbsp;</div>\r\n		<br/>\r\n		&nbsp;\r\n	</div>\r\n<%\r\n    end\r\n%>\r\n\r\n<div id=\'prescope\' >Loading..PreScope information</div>\r\n<script>\r\n\r\n<%\r\n\r\n url = \"../PreScope/pre_scope_detail?id=\\\\#{params[:id]}\"\r\n url = \"../PreScope/pre_scope_detail?parent_id=\\\\#{params[:parent_id]}\" if params[:parent_id]\r\n \r\n%>\r\n\r\n$.ajax({\r\n  url: \"<%=url%>\",\r\n  context: document.body\r\n}).done(function(data) { \r\n  $(\'#prescope\').html(data);\r\n <% unless params[:id] %>\r\n $(\'#data-bowel_preparation\').val(pre_scope[\"bowel_preparation\"]);\r\n $(\'#data-additional_bowel_preparation\').val(pre_scope[\"add_bowel_prep\"]);\r\n\r\n $(\'#data-bowel_cc\').val(pre_scope[\"bowelprep_cc\"]);\r\n $(\'#data-bowel_other\').val(pre_scope[\"bowel_other_note\"]);\r\n $(\'#data-add_bowel_prep_cc\').val(pre_scope[\"add_bowel_prep_cc\"]);\r\n $(\'#data-add_bowel_prep_other\').val(pre_scope[\"add_bowel_other\"]);\r\n \r\n <% end %> \r\n\r\n});\r\n</script>\r\n\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n\r\n//  add snap button on the top\r\n    $(document).ready(function() {\r\n<%\r\n    if (@current_role==\'capture\' or @current_role==\'developer\')\r\n        if params[:opt] == \'create\' or params[:opt] == \'edit\'\r\n%>\r\n        frm_submit = $(\'#record-submit\').clone();\r\n        frm_cancel = $(\'#record-submit\').next().clone();\r\n        frm_cancel = frm_cancel.addClass(\'btn btn-small\')\r\n        frm_submit = frm_submit.addClass(\'btn btn-success btn-small\')\r\n        \r\n        btn_form = $(\'#btn-form\');\r\n        btn_form.append(frm_submit);\r\n        btn_form.append(\'&nbsp;&nbsp;|&nbsp;&nbsp;\');\r\n        btn_form.append(frm_cancel);\r\n        \r\n        // $(\'#record-submit\').click(function() {\r\n        //     if ($(\'#data-stop_at\').val() == \"\") {\r\n        //         d = new Date();\r\n        //         $(\'#data-stop_at\').val(d.getHours() + \":\" + d.getMinutes());\r\n        //     }\r\n        // });\r\n\r\n<%\r\n        end\r\n%>\r\n        snap = $( \"a:contains(\'Snap\')\" ).clone();\r\n        snap = snap.addClass(\'btn btn-small btn-info\');\r\n        btn_snap = $(\'#btn-snap\');\r\n        btn_snap.append(snap);\r\n        \r\n        $(\'input\').prop(\'required\', null);\r\n        $(\'select\').prop(\'required\', null);\r\n<%\r\n    end\r\n%>\r\n    })\r\n\r\n$(\'#data-procedure\').bind(\"change\", function (){\r\n    \r\n    v = $(this).val()\r\n    if(v.indexOf(\'ESD\')>=0){\r\n        $(\'#data-project\').val(\'ESD\');\r\n         update_project_rev_func();\r\n    }\r\n    if(v.indexOf(\'Stent\')>=0){\r\n        $(\'#data-project\').val(\'Stent\');\r\n         update_project_rev_func();\r\n    }\r\n    if(v.indexOf(\'ESD\')>=0 && v.indexOf(\'Stent\')>=0){\r\n        $(\'#data-project\').val(\'Stent\');\r\n         update_project_rev_func();\r\n    }\r\n    \r\n    \r\n    \r\n     \r\n    \r\n});\r\n\r\n\r\nsedative = [\'dormicum\',\'pethidine\',\'diprivan\',\'valium\',\'buscopan\',\'plasil\',\'fentanyl\',\'propofol\',\'other\']\r\nfunction check_sedative(ele){\r\n   check = ele.prop(\"checked\");\r\n   id = ele.prop(\"id\");\r\n   t = id.split(\'-\')[1];\r\n   if(check)\r\n   $(\".\"+t+\'\').css(\"display\",\"block\");\r\n   else\r\n   $(\".\"+t+\'\').css(\"display\",\"none\");\r\n}\r\n\r\nfor(i=0;i<sedative.length;i++){\r\n t = sedative[i];  \r\n ele = $(\'#data-\'+t);\r\nele.change(function(){\r\n    check_sedative($(this));\r\n});\r\n check_sedative(ele);\r\n}\r\n//$(\'#data-dormicum_mg\').val(323)\r\n//$(\'#data-dormicum_mg\').prop(\'disabled\', true);\r\n//$(\'#data-dormicum_num\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_mg\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_num\').prop(\'disabled\', true);\r\n\r\nvar scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\nfunction refresh(ele){\r\n    for(i=0;i<scope_list.length;i++){\r\n      $(\".\"+scope_list[i]).css(\"display\",\"none\");\r\n   }\r\n    index = $(ele).prop(\"selectedIndex\");\r\n   for(i=0;i<index;i++){\r\n       $(\".\"+scope_list[i]).css(\"display\",\"block\");\r\n   }\r\n}\r\n\r\nrefresh($(\'#data-scope\'));\r\n\r\n$(\"#data-scope\").change(function(){\r\nrefresh(this);\r\n});\r\n\r\n\r\n$(\".diag\").change(function(){\r\n    \r\n   e = $(\"#data-\"+this.id).val();\r\n   p = $(\"#data-patient_status\");\r\n   if(e==\"1\"){\r\n     $.sticky(\"Select Abnormal\", {autoclose : 5000, position: \"top-right\" });\r\n     p.val(\"Abnormal\");    \r\n   }\r\n});\r\n\r\n\r\n  \r\n\r\n$(\'#data-diagnosis_group\').bind(\"change\", function() {\r\n       v = $(this).val() \r\n    //   alert(v)\r\n       if(v!=\'Normal\'){\r\n           $(this).val(v.replace(\'Normal|\',\'\')) \r\n          $(\'#update_diagnosis_group_item_0\').attr(\'checked\', false);\r\n       }\r\n          v = $(this).val() \r\n        var $cbx = $(\"#data-diagnosis_note\").data(\"kendoComboBox\")\r\n        $cbx.value(v.replace(/\\\\|/g,\',\'))\r\n        if(v.indexOf(\'Serrated\')>=0){\r\n            $(\'#data-project\').val(\'Serrated polyp\');\r\n            update_project_rev_func();\r\n        }\r\n\r\n    //   $(\'#data-diagnosis_note\').kendoComboBox().value(\'oiwjfoiwejfoijwef\');\r\n       \r\n     \r\n     \r\n \r\n });\r\n \r\n $(\'#data-bowel_cc\').change(function() {\r\n            v = $(this).val();\r\n            if (v == \'\') {\r\n                $(this).val(\'0\');\r\n            }\r\n            // console.log(\'xxx : \' + v)\r\n        })\r\n\r\n</script>',NULL,NULL,NULL,'2016-11-02 07:16:46','2016-11-02 07:16:46','form',''),(2689,'form',1079,3,'\r\n<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n  \r\n%>\r\n<%\r\n    if @current_role==\'capture\' or @current_role==\'developer\'\r\n%>\r\n    <div class=\"alert\">\r\n		<!--<h4 class=\"alert-heading\">Endo Button</h4>-->\r\n		<div style=\'float:left\' id=\'btn-form\'>&nbsp;</div>\r\n		<div style=\'float:right\' id=\'btn-snap\'>&nbsp;</div>\r\n		<br/>\r\n		&nbsp;\r\n	</div>\r\n<%\r\n    end\r\n%>\r\n<div id=\'prescope\' >Loading..PreScope information</div>\r\n<script>\r\n\r\n<%\r\n\r\n url = \"../PreScope/pre_scope_detail?id=\\\\#{params[:id]}\"\r\n url = \"../PreScope/pre_scope_detail?parent_id=\\\\#{params[:parent_id]}\" if params[:parent_id]\r\n \r\n%>\r\n\r\n$.ajax({\r\n  url: \"<%=url%>\",\r\n  context: document.body\r\n}).done(function(data) { \r\n  $(\'#prescope\').html(data);\r\n  var d = new Date(pre_scope[\"npo_since\"]+\"T\"+pre_scope[\"nop_at\"].split(\"T\")[1]);\r\n  var n =  new Date();\r\n  a = Math.round((n-d)/3600000);\r\n  $(\'#data-npotime\').val(a+7);\r\n  \r\n});\r\n</script>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n//  add snap button on the top\r\n    $(document).ready(function() {\r\n<%\r\n    if (@current_role==\'capture\' or @current_role==\'developer\')\r\n        if params[:opt] == \'create\' or params[:opt] == \'edit\'\r\n%>\r\n        frm_submit = $(\'#record-submit\').clone();\r\n        frm_cancel = $(\'#record-submit\').next().clone();\r\n        frm_cancel = frm_cancel.addClass(\'btn btn-small\')\r\n        frm_submit = frm_submit.addClass(\'btn btn-success btn-small\')\r\n        \r\n        btn_form = $(\'#btn-form\');\r\n        btn_form.append(frm_submit);\r\n        btn_form.append(\'&nbsp;&nbsp;|&nbsp;&nbsp;\');\r\n        btn_form.append(frm_cancel);\r\n        \r\n        // $(\'#record-submit\').click(function() {\r\n        //     if ($(\'#data-stop_at\').val() == \"\") {\r\n        //         d = new Date();\r\n        //         $(\'#data-stop_at\').val(d.getHours() + \":\" + d.getMinutes());\r\n        //     }\r\n        // });\r\n\r\n<%\r\n        end\r\n%>\r\n        snap = $( \"a:contains(\'Snap\')\" ).clone();\r\n        snap = snap.addClass(\'btn btn-small btn-info\');\r\n        btn_snap = $(\'#btn-snap\');\r\n        btn_snap.append(snap);\r\n        \r\n        $(\'input\').prop(\'required\', null);\r\n        $(\'select\').prop(\'required\', null);\r\n<%\r\n    end\r\n%>\r\n    })\r\n    \r\n    \r\n    \r\nsedative = [\'dormicum\',\'pethidine\',\'diprivan\',\'valium\',\'buscopan\',\'plasil\',\'fentanyl\',\'propofol\',\'other\']\r\nfunction check_sedative(ele){\r\n   check = ele.prop(\"checked\");\r\n   id = ele.prop(\"id\");\r\n   t = id.split(\'-\')[1];\r\n   if(check)\r\n   $(\".\"+t+\'\').css(\"display\",\"block\");\r\n   else\r\n   $(\".\"+t+\'\').css(\"display\",\"none\");\r\n}\r\n\r\nfor(i=0;i<sedative.length;i++){\r\n t = sedative[i];  \r\n ele = $(\'#data-\'+t);\r\nele.change(function(){\r\n    check_sedative($(this));\r\n});\r\n check_sedative(ele);\r\n}\r\n//$(\'#data-dormicum_mg\').val(323)\r\n//$(\'#data-dormicum_mg\').prop(\'disabled\', true);\r\n//$(\'#data-dormicum_num\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_mg\').prop(\'disabled\', true);\r\n//$(\'#data-pethidine_num\').prop(\'disabled\', true);\r\n\r\n//1|Pharynx\r\n//2|Esophagus\r\n//3|EGJ\r\n//4|Fundus\r\n//5|Cardia\r\n//6|Body\r\n//7|Antrum\r\n//8|1st Duodenum\r\n//9|Sphincter of oddi\r\n//10|2nd Duodenum\r\n//11|3rd Duodenum\r\n//12|4th Duodenum\r\n//13|Proximal Jejunum\r\n//14|Distal Jejunum\r\n\r\nvar scope_list = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n\r\n\r\nfunction update(ele){\r\n   for(i=0;i<scope_list.length;i++){\r\n      $(\".\"+scope_list[i]).css(\"display\",\"none\");\r\n   }\r\n    index = $(ele).prop(\"selectedIndex\");\r\n   for(i=0;i<index;i++){\r\n       $(\".\"+scope_list[i]).css(\"display\",\"block\");\r\n   }\r\n}\r\n\r\nupdate($(\'#data-scope\'));\r\n\r\n$(\"#data-scope\").change(function(){\r\nupdate(this);\r\n});\r\n\r\n\r\n$(\".diag\").change(function(){\r\n    \r\n   e = $(\"#data-\"+this.id).val();\r\n   p = $(\"#data-patient_status\");\r\n   if(e==\"1\"){\r\n    $.sticky(\"Select Abnormal\", {autoclose : 5000, position: \"top-right\" });\r\n     p.val(\"Abnormal\");    \r\n   }\r\n});\r\n\r\n\r\n\r\n$(\'#data-diagnosis_group\').bind(\"change\", function() {\r\n       v = $(this).val() \r\n    //   alert(v)\r\n       if(v!=\'Normal\'){\r\n           $(this).val(v.replace(\'Normal|\',\'\')) \r\n          $(\'#update_diagnosis_group_item_0\').attr(\'checked\', false);\r\n       }\r\n       \r\n        v = $(this).val() \r\n        var $cbx = $(\"#data-diagnosis_note\").data(\"kendoComboBox\")\r\n        $cbx.value(v.replace(/\\\\|/g,\',\'))\r\n     \r\n \r\n });\r\n \r\n\r\n</script>',NULL,NULL,NULL,'2016-11-02 07:29:04','2016-11-02 07:29:04','form',''),(2690,'print_report_bk',1063,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  attachment_model = @models[:attachment]\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n# @document = @model[:colono].get_document\r\ndx_stat = {} \r\ndg_stat = {}\r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n \r\n \r\n\r\n\r\n \r\n ml =  @module_model.where(:parent_id=>i.id).all\r\n \r\n diagnosis = \'\'\r\n diagnosis_group = \'\'\r\n provider = providers[ap.provider.to_s]\r\n provider_name = provider.name if provider\r\n attachments = []\r\n#  provider_name = ml.size.to_s\r\n \r\n for x in ml\r\n    if x.module_name==\"\\\\#{@current_project.name}#colonoscopy\"\r\n        \r\n        colo = @models[:colonoscopy].find(x.module_id)\r\n  \r\n        if colo\r\n            provider_name = colo.id.to_s\r\n            \r\n            provider = providers[colo.endoscopist_1.to_s]\r\n            provider_name = provider.name if provider\r\n            diagnosis = colo.diagnosis_note\r\n            attachments = colo.image\r\n            \r\n            # diagnosis_group\r\n            # 0 - Normal\r\n            # 1 - Polyp\r\n            # 2 - Diverticulum\r\n            # \r\n            diagnosis_group = colo.diagnosis_group\r\n            a_dx = diagnosis_group.split(\'|\')\r\n            tmp = {}\r\n            a_dx.each do |i|\r\n                if !dx_stat.has_key? i\r\n                    dx_stat[i] = 0\r\n                end\r\n                \r\n                if !tmp.has_key? i\r\n                    tmp[i] = 0\r\n                    dx_stat[i] += 1\r\n                end\r\n            end\r\n            dx_group = tmp.keys.join(\'|\')\r\n            if !dg_stat.has_key? dx_group\r\n                dg_stat[dx_group] = 0\r\n            end\r\n            dg_stat[dx_group] += 1\r\n        end\r\n    end\r\n end\r\n \r\n \r\n\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year} ปี\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>ml.collect{|i| i.module_name.split(\'#\')[-1].humanize}.join(\',\'),\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider_name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'attachments\'=>attachments,\r\n    \'age\'=>age,\r\n    \'ml\'=>ml,\r\n    \'diagnosis\'=>diagnosis.html_safe,\r\n    \'diagnosis_group\'=>diagnosis_group.html_safe,\r\n    \'visit_type\'=>visit_type,\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\n\r\n\r\nlist = json_data.sort{|a,b| b[\'diagnosis_group\']<=>a[\'diagnosis_group\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Summary Report</title>\r\n<%# javascript_include_tag \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' height=\"60px\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงรายการผู้ป่วย\r\n<span style=\"float:right\">ประจำวันที่ \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>HN</th>\r\n    <th >อายุ</th>\r\n    <th>Procedure</th>\r\n    <th>Diagnosis</th>\r\n    <th>Provider</th>\r\n    <th>Link</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n<% \r\n    sp = {}\r\n    index = 0 \r\n    list.each_with_index do |i,ix|  \r\n        pps = i[\'procedure\'].split(\',\')\r\n        for pp in pps\r\n            if sp.has_key?(pp)\r\n                sp[pp] = sp[pp] + 1\r\n            else\r\n                sp[pp] = 1\r\n            end\r\n        end\r\n    if params[:filter]==nil or (i[\'diagnosis\']!=\'\' and i[\'diagnosis_group\']!=\'0\') \r\n\r\n    \r\n%> \r\n    <tr class=\"page-break\">\r\n    <td><%=index+1%>.</td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%></td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'age\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    <td><%=i[\'diagnosis\']%></td>\r\n    <td><%=i[\'provider\']%></td>\r\n    <td><%=link_to(\'Detail\',\"patient_record?id=\\\\#{i[\'id\']}\")%></td>\r\n    </tr>\r\n    \r\n  \r\n    <tr>\r\n    <td colspan=\"8\">\r\n        <%  \r\n        if true\r\n            \r\n            # atts_list = record.image[0..4]\r\n            # if record.selected_image and record.selected_image.size > 0\r\n              \r\n            #   atts_list = record.selected_image[0..4]\r\n               \r\n            # end\r\n           \r\n           \r\n            # attachments = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n            #  old\r\n            # attachments = attachment_model.find(i[\'attachments\'])[0..4]\r\n            attachments = attachment_model.find(i[\'attachments\'][0..4])\r\n        for j in attachments\r\n        %>\r\n        <% if @current_role != \'developer\' %>\r\n        <%= image_tag j.path + \"?thumb=1\", :width=>80, :style=>\'\' %>\r\n        <% end %>\r\n        <% end %>\r\n        <% end %>\r\n    </td>    \r\n        \r\n    </tr>\r\n    \r\n    <% \r\n    \r\n    index+=1\r\n    end %>\r\n    <% end %>\r\n</tbody>\r\n<%\r\n    dx_lbn = [\'Normal\', \'Polyp\', \'Diverticulum\', \'Hemorrhoid\', \'Mass\', \'Ulcer\', \'Other\']\r\n    dx_val = Array.new(dx_lbn.count + 1).collect{|i| 0}\r\n    dx_pie = []\r\n    dx_map = {}\r\n    dx_stat.keys.each do |i|\r\n        r = {}\r\n        idx = i.to_i\r\n        k = \'Other\'\r\n        v = dx_stat[i]\r\n        if idx <= 5\r\n            k = dx_lbn[idx]\r\n            v = dx_stat[i]\r\n        end\r\n        \r\n        if !dx_map.has_key? k\r\n            dx_map[k] = 0\r\n        end\r\n        dx_map[k] += v\r\n        \r\n        # if idx > 5\r\n        #     dx_val[6] += dx_stat[i]\r\n        #     r[:category] = dx_lbn[6]\r\n        #     r[:value] = dx_val[6]\r\n        # else\r\n        #     dx_val[idx] = dx_stat[i]\r\n        #     r[:category] = dx_lbn[idx]\r\n        #     r[:value] = dx_val[idx]\r\n        # end\r\n        # dx_pie << r\r\n    end\r\n%>\r\n    <tr>\r\n        <td colspan=\"4\">\r\n            <div class=\'row-fluid\'>\r\n                <b>สรุปรายการที่พบ</b><br/>\r\n                <blockquote>\r\n                <%\r\n                    n = 0\r\n                    dx_lbn.each do |i|\r\n                %>\r\n                    <b><%= n %>. <%= i %> : </b> <%= dx_map[i] ? dx_map[i] : 0 %><br/>\r\n                <%\r\n                        n += 1\r\n                    end\r\n                %>  \r\n                </blockquote>\r\n                <%# dx_map.to_json.html_safe %>\r\n                <!--<div id=\"dx-chart\" style=\"border:0px solid;width:480%;min-height:300px\"></div>-->\r\n            </div>\r\n        </td>  \r\n        <td colspan=\"4\">\r\n            <div class=\'row-fluid\'>\r\n                <b>สรุปรายการที่พบ</b><br/>\r\n                <blockquote>\r\n                <%\r\n                    n = 1\r\n                    dg_stat.each do |i,v|\r\n                        arr = i.split(\'|\')\r\n                        txt = []\r\n                        arr.each do |a|\r\n                            idx = a.to_i\r\n                            if idx > 5\r\n                                txt << \'Other\'\r\n                            else\r\n                                txt << dx_lbn[idx]\r\n                            end\r\n                        end\r\n                %>\r\n                    <b><%= n %>. <%= txt.join(\', \') %> : </b> <%= v %><br/>\r\n                <%\r\n                        n += 1\r\n                    end\r\n                %>  \r\n                </blockquote>\r\n                <%# dx_map.to_json.html_safe %>\r\n                <!--<div id=\"dx-chart\" style=\"border:0px solid;width:480%;min-height:300px\"></div>-->\r\n            </div>\r\n        </td>  \r\n    </tr>\r\n  </table><br/>\r\n\r\n<script>\r\n<%\r\n    dx_lbn = [\'Normal\', \'Polyp\', \'Diverticulum\', \'Hemorrhoid\', \'Mass\', \'Ulcer\', \'Other\']\r\n    dx_val = Array.new(dx_lbn.count + 1).collect{|i| 0}\r\n    dx_pie = []\r\n    dx_stat.keys.each do |i|\r\n        r = {}\r\n        idx = i.to_i\r\n        if idx > 5\r\n            dx_val[6] += dx_stat[i]\r\n            r[:category] = dx_lbn[6]\r\n            r[:value] = dx_val[6]\r\n        else\r\n            dx_val[idx] = dx_stat[i]\r\n            r[:category] = dx_lbn[idx]\r\n            r[:value] = dx_val[idx]\r\n        end\r\n        dx_pie << r\r\n    end\r\n%>\r\n    function createChart() {\r\n        /*\r\n                    $(\"#dx-chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Number Diagnosis\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: [<%#dx_val.to_json.html_safe %>]\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%#dx_lbn.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    }); */\r\n                    /*\r\n        $(\"#dx-chart\").kendoChart({\r\n            title: {\r\n                text: \"Diagnosis\"\r\n            },\r\n            legend: {\r\n                position: \"left\"\r\n            },\r\n            seriesDefaults: {\r\n                labels: {\r\n                    visible: true,\r\n                    format : \"{0}\"\r\n                    // format: \"{0}%\"\r\n                }\r\n            },\r\n            series: [{\r\n                type: \"pie\",\r\n                data: <%# dx_pie.to_json.html_safe %>\r\n            }]\r\n        });*/\r\n    }\r\n    /*\r\n    $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n    });*/\r\n</script>  \r\n  \r\n  \r\n<% if false %>\r\n<br/>\r\n  <div><strong>Total procedure</strong></div><br/>\r\n<%\r\nsp.keys.each_with_index do |key, index|\r\n%>\r\n<div><%= key %> : <%= sp[key] %></div>\r\n<%\r\nend\r\nend\r\n%>\r\n  </div>\r\n  </div></div></div></div></div>\r\n  <%# dx_stat.to_json.html_safe %>\r\n</body>\r\n</html>\r\n<% end %>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-11-02 07:48:40','2016-11-02 07:48:40','print_report_bk',''),(2691,'create',1077,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   if @appointment\r\n\r\n        @appointment.update_attributes :status=>\'Processing\' \r\n       \r\n   end\r\n%>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n  \r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    unless @appointment[\'operative_provider\']\r\n        # @appointment.update_attributes :operative_provider => record.endoscopist_1 \r\n    end\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    var validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n    $(\"#record-submit\").click(function() {\r\n    \r\n    if (!validator.validate()||$(\'#0\').val()==\"\") {\r\n    alert(\'Please fill all information\');\r\n    if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\n    return false;\r\n    \r\n    }else{\r\n        return true;\r\n        if(confirm(\'Are you sure?\')==true){\r\n            return true;\r\n        }\r\n        return false;\r\n    }\r\n    });\r\n<%\r\n    # type of sedation\r\n    tos = {\'1\'=>\'dormicum\', \'2\'=>\'pethidine\', \'3\'=>\'propofol\'}\r\n    if @appointment[:type_of_sedation]\r\n        sed = tos[@appointment[:type_of_sedation]]\r\n%>\r\n    // $(\'#data-<%=sed%>\').trigger(\'click\');\r\n<%  end %>\r\n\r\n  $(\'#data-dormicum\').trigger(\'click\');\r\n   $(\'#data-dormicum_mg\').val(\'2.5\')\r\n  \r\n  \r\n<% if @appointment[:provider] %>\r\n    $(\'#data-endoscopist_1\').val(\'<%= @appointment[:provider] %>\');\r\n<% end %>\r\n</script>   \r\n',NULL,NULL,NULL,'2016-11-02 14:44:19','2016-11-02 14:44:19','create',''),(2692,'create',1079,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   if @appointment\r\n\r\n        @appointment.update_attributes :status=>\'Processing\' \r\n       \r\n   end\r\n%>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    var validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n    $(\"#record-submit\").click(function() {\r\n    \r\n    if (!validator.validate()||$(\'#0\').val()==\"\") {\r\n    alert(\'Please fill all information\');\r\n    if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\n    return false;\r\n    \r\n    }else{\r\n        return true;\r\n        if(confirm(\'Are you sure?\')==true){\r\n            return true;\r\n        }\r\n        return false;\r\n    }\r\n    });\r\n<%\r\n    # type of sedation\r\n    tos = {\'1\'=>\'dormicum\', \'2\'=>\'pethidine\', \'3\'=>\'propofol\'}\r\n    if @appointment[:type_of_sedation]\r\n        sed = tos[@appointment[:type_of_sedation]]\r\n%>\r\n    $(\'#data-<%=sed%>\').trigger(\'click\');\r\n<%  end %>\r\n<% if @appointment[:provider] %>\r\n    $(\'#data-endoscopist_1\').val(\'<%= @appointment[:provider] %>\');\r\n<% end %>\r\n</script>   \r\n',NULL,NULL,NULL,'2016-11-02 15:08:15','2016-11-02 15:08:15','create',''),(2693,'patient_summary',1063,3,'<%\r\n	@module_name = @current_project.name+\'#appointment\' \r\n	@ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@patient_doc = @ehr_project.get_document \'patient\'\r\n	@module_doc = @ehr_project.get_document \'patient_module\'\r\n	@ehr_model = @ehr_project.get_model()\r\n	@patient_model = @ehr_model[:patient]\r\n	@module_model = @ehr_model[:patient_module]\r\n	\r\n	@models = get_model\r\n	attachment_model = @models[:attachment]\r\n	\r\n	if this.table_name!=\'appointment\' and params[:parent_id] \r\n    	@appointment_module = @module_model.find(params[:parent_id])\r\n    	if @appointment_module\r\n        	@appointment = @models[:appointment].find(@appointment_module.module_id)\r\n    	end\r\n	end \r\n	\r\n	if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n	   @patient = @patient_model.find(@patient_module.patient_id)\r\n	end\r\n	\r\n	date = Date.to_mongo(Time.now.strftime(\'%d/%m/%Y\'))\r\n	if params[:date]\r\n	    date = Date.to_mongo(params[:date])\r\n	end\r\n	\r\n	app = @models[:appointment].where(:date=>date).all\r\n	\r\n	\r\n	mod_app = {}\r\n	pat = {}\r\n	prov = {}\r\n	ind = {}\r\n	vis = {}\r\n	\r\n	par_ids = []\r\n	mod_par = {}\r\n	\r\n	ss = [\'gastroscopy\', \'colonoscopy\'] # services\r\n	\r\n	mod_serv = {}\r\n	pat_serv = {}\r\n	\r\n	@module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>app.collect{|i| i.id }}).all.each do |i|\r\n        mod_app[i.module_id] = i\r\n        par_ids << i.id.to_s\r\n	end\r\n	\r\n	ss.each do |i|\r\n	    mod_name = \"\\\\#{@current_project.name}#\\\\#{i}\"\r\n	    mod_list = @module_model.where(:module_name=>mod_name, :parent_id=>par_ids).all\r\n	    mod_ids = []\r\n	    tmp = {}\r\n	    mod_list.each do |j|\r\n	        mod_ids << j[:module_id].to_s\r\n	        tmp[j[:module_id].to_s] = j[:patient_id].to_s\r\n	    end\r\n	    \r\n	    rec_serv = get_model[i.to_sym].find(mod_ids)\r\n	    rec_serv.each do |j|\r\n	        pat_id = tmp[j.id.to_s]\r\n	        if !pat_serv.has_key? pat_id\r\n	            pat_serv[pat_id] = {}\r\n	        end\r\n	        pat_serv[pat_id][i] = j\r\n	    end\r\n	end\r\n	\r\n	@patient_model.find(mod_app.values.collect{|i| i.patient_id if i }).each do |i|\r\n        pat[i.id]=i\r\n	end\r\n	\r\n	@models[:visit_type].all.each do |i|\r\n        vis[i.id.to_s] = i\r\n	end\r\n	\r\n	@models[:provider].all.each do |i|\r\n        prov[i.id.to_s] = i\r\n	end\r\n	@models[:indication].all.each do |i|\r\n        ind[i.id.to_s] = i\r\n	end\r\n	\r\n    pro = {}\r\n        @models[:procedure].all.each do |i|\r\n        pro[i.id] = i.name\r\n    end\r\n	  \r\n	  \r\n	# @document = @model[:colono].get_document\r\n	dx_stat = {} \r\n	dg_stat = {}\r\n	json_data = app.collect{|ap| \r\n        i  = mod_app[ap.id]\r\n        if i\r\n            p = pat[i.patient_id]  \r\n            \r\n        	provider = prov[ap.provider.to_s]\r\n        	provider_name = provider.name if provider\r\n        	attachments = []\r\n        	\r\n        	l = %w{#bcdeee}\r\n        	age = \'-\'\r\n        	if p.birth_date\r\n        	    diff = Time.diff(date, p.birth_date)\r\n        	    year = diff[:year]\r\n        	    month = diff[:month]\r\n        	    day = diff[:day]\r\n        	    age = \"\\\\#{year} y.\"\r\n        	end\r\n        	indication=\"-\"\r\n        	visit_type=\"-\"\r\n        	\r\n        	indication = ind[ap.indication.to_s].name if ind[ap.indication.to_s]\r\n        	visit_type = vis[ap.visit_type.to_s].name if vis[ap.visit_type.to_s]\r\n        	\r\n        	d = \"-\"\r\n        	d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n    	\r\n    	\r\n            operative = pat_serv[p.id.to_s]\r\n            \r\n    	\r\n    	  {\r\n    	      :aid=>ap.id,\r\n        	  :hn=> p.hn,\r\n        	  :procedure=>pro[ap[:procedure]],\r\n        	  :date=>d,\r\n        	  :provider=>provider_name,\r\n        	  :name=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n        	  :start=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n        	  :indication=>indication,\r\n        	  :attachments=>attachments,\r\n        	  :age=>age,\r\n        	  :visit_type=>visit_type,\r\n        	  :public_id=>p.public_id,\r\n        	  :operative=>operative\r\n    	  }  \r\n	    end\r\n	}.compact\r\n	\r\n	\r\n	list = json_data.sort_by{|i| [i[:hn], i[:visit_type]]}\r\n	\r\n%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>Summary Report</title>\r\n		<%# javascript_include_tag \"application\"  %>\r\n	</head>\r\n	<style type=\"text/css\" media=\"print,screen\">\r\n		html { }\r\n		value {color:#06F}\r\n		imvalue { color:#F00; font-weight:bold}\r\n		imvalue value { color:#F00; font-weight:bold}\r\n		#page {border:solid 1px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n		#head { width:100%; height:60px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-size: 1.5em; margin: .83em 0 }\r\n		h3              { font-size: 1.17em; margin: 1em 0 }\r\n		p {color:#666;}\r\n		h4, p,\r\n		blockquote, ul,\r\n		form,\r\n		ol, dl          { margin: 0.5em; }\r\n		h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n		h6              { font-size: .67em; margin: 2.33em 0 }\r\n		h4 { font-size:14pt; color:#333; height:16px;}\r\n		blockquote      { margin-left: 40px; margin-right: 40px }\r\n		i, cite, em,\r\n		var, address    { font-style: italic }\r\n		pre, tt, code,\r\n		kbd, samp       {  font-size:14px; }\r\n		pre             {margin:0;margin-left:1em; color:#666}\r\n		big             { font-size: 1.17em }\r\n		v {color:#2561cD;}\r\n		small, sub, sup { font-size: .83em }\r\n		ol, ul, dd      { margin-left: 40px }\r\n		ol              { list-style-type: decimal }\r\n		ol ul, ul ol,\r\n		ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n		.clear{clear:both;}\r\n		#box{\r\n		width:150px;\r\n		float:left;\r\n		padding:10px;\r\n		text-align:center;\r\n		border:1px solid #ccc;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */    \r\n		margin:10px;\r\n		}\r\n		.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n		#box img{\r\n		width:150px;\r\n		}\r\n		label{\r\n		color:#666; font-weight:bold;\r\n		}\r\n		#table-3 {\r\n		border: 1px solid #DFDFDF;\r\n		background-color: #F9F9F9;\r\n		width: 100%;\r\n		-moz-border-radius: 3px;\r\n		-webkit-border-radius: 3px;\r\n		border-radius: 3px;\r\n		font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n		color: #333;\r\n		}\r\n		#table-3 td, #table-3 th {\r\n		border-top-color: white;\r\n		border-bottom: 1px solid #DFDFDF;\r\n		color: #555;\r\n		}\r\n		#table-3 th {\r\n		text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n		font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n		font-weight: normal;\r\n		padding: 7px 7px 8px;\r\n		text-align: left;\r\n		line-height: 1.3em;\r\n		font-size: 14px;\r\n		}\r\n		#table-3 td {\r\n		font-size: 12px;\r\n		padding: 4px 7px 2px;\r\n		vertical-align: top;\r\n		background:#FFF;\r\n		}\r\n		thead {\r\n		display:table-header-group;\r\n		}\r\n		tbody {\r\n		display:table-row-group;\r\n		}\r\n	</style>\r\n	<body>\r\n		<div class=\"wrapper\">\r\n			<div id=\"head\">\r\n				<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' height=\"60px\" /></div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now %></p>\r\n				</div>\r\n			</div>\r\n			<div id=\"page\">\r\n				<div class=\"row-fluid\">\r\n					<div class=\"span12\">\r\n						<div class=\"w-box\">\r\n							<br />\r\n							<b>Patient summary report\r\n							<span style=\"float:right\">Date :\r\n							<%= date.strftime(\"%d %B %Y\")%></b>\r\n							</span>\r\n							<br /><br />\r\n							<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n								<thead>\r\n									<tr>\r\n										<th>No.</th>\r\n										<th>HN</th>\r\n										<th style=\"width:150px\">Name</th>\r\n										<th>Age</th>\r\n										<th>Procedure</th>\r\n										<th>Provider</th>\r\n										<th>Visit Type</th>\r\n									</tr>\r\n								</thead>\r\n								<tbody>\r\n<%\r\n    index = 0\r\n    json_data.each do |i|\r\n%>\r\n									<tr class=\"page-break\">\r\n										<td rowspan=\'2\'><%=index+1%>.</td>\r\n										<td><%=i[:hn]%></td>\r\n										<td><%=i[:name]%></td>\r\n										<td><%=i[:age]%></td>\r\n										<td><%=i[:procedure]%></td>\r\n										<td><%=i[:provider]%></td>\r\n										<td><%=i[:visit_type]%></td>\r\n									</tr>\r\n									<tr>\r\n										<td colspan=\"6\">\r\n										    <br/>\r\n<%  \r\n        if i[:operative]\r\n            i[:operative].each do |k, v|  \r\n                imgs = get_model[:attachment].find(v[:image][0..7])\r\n%>\r\n                                            &nbsp;&nbsp;&nbsp;&nbsp;<b><%= k.humanize %> Dx. : </b> <%= v[:diagnosis_note] == \'\' ? \'-\' : v[:diagnosis_note].html_safe %> / <%= v[:diagnosis_group].split(\'|\').join(\',\').html_safe %><br/>\r\n                                            &nbsp;&nbsp;&nbsp;&nbsp;\r\n                                            <% imgs.each do |x| %>\r\n                                            <%= image_tag x.path + \"?thumb=1\", :width=>80, :style=>\'\' %>\r\n                                            <% end %>\r\n                                            <br/><br/>\r\n<%      \r\n            end \r\n        else\r\n%>\r\n                                            &nbsp;&nbsp;&nbsp;&nbsp;-- Not done --<br/>\r\n<%      end %>\r\n                                            <br/>\r\n										</td>\r\n									</tr>\r\n<% \r\n		index+=1\r\n	end \r\n%>\r\n								</tbody>\r\n							</table>\r\n							<br/>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</div>\r\n		</div>\r\n		</div>\r\n		<%# dx_stat.to_json.html_safe %>\r\n	</body>\r\n</html>',NULL,NULL,NULL,'2016-11-03 03:40:27','2016-11-03 03:40:27','patient_summary',''),(2694,'create',1067,2,'<%\r\n	params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n	return_url = url(\'index\')\r\n	return_url = params[:return] if params[:return]\r\n	\r\n	\r\n	locker_model = get_model(\'locker\')\r\n	\r\n	\r\n	\r\n	date = Time.now.strftime(\"%d/%m/%Y\")\r\n	time = Time.now.strftime(\"%H:%M\")\r\n	\r\n	# date = params[:date] if params[:date]\r\n	# time = params[:time] if params[:time]\r\n	\r\n	%>\r\n<%= params[:date] %>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n				<div style=\"border:0px solid\">\r\n					<div class=\"document-border\" style=\"border:0px solid\">\r\n						<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n						<%\r\n							model = get_model(this.table_name)\r\n							\r\n							\r\n							if request.post? \r\n							    m = nil\r\n							        p_date = params[:record][:date]\r\n							        \r\n							        m_date = Date.to_mongo(p_date)\r\n							        \r\n							        a_ids   = @models[:appointment].where(:date=>m_date).all.collect{|i| i.id.to_s}\r\n							        m_mod = @module_model.where(:module_id=>a_ids, :patient_id=>params[:patient_id]).first\r\n							        \r\n							        if m_mod\r\n							            flash[:notice]=\"Appointment exist.\"\r\n							            m = m_mod\r\n							        else\r\n							            flash[:notice]=\"New record has been created\"\r\n							            doc = get_document this.document_name\r\n    							        record = doc.record_create(model,params)\r\n    							        m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n							        end\r\n\r\n%>\r\n<br/>\r\n<h3><%= flash[:notice] %></h3>\r\n<br/>\r\n\r\n						<script type=\"text/javascript\">\r\n							<% if  @appointment %>\r\n							//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\n							window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n							\r\n							<% else %>\r\n							//window.location = \"../Home/index\"\r\n							<% end %>\r\n							\r\n							window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n							\r\n							\r\n						</script>\r\n						<%\r\n							else  \r\n							\r\n							  if params[:data]\r\n							  record = model.new params[:data] \r\n							  else\r\n							  record = model.new \r\n							  end\r\n							\r\n							  \r\n							%>\r\n						<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n						<%= hidden_field_tag :return, return_url if params[:return] %>\r\n						<%\r\n							fid = 0\r\n							name = \'patient_id\'\r\n							value = params[:patient_id]\r\n							value = params[:id] if params[:id]\r\n							ref_number = @next_id\r\n							ref_number = params[:ref_number] if params[:ref_number]\r\n							\r\n							%>\r\n						<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n							<div class=\"modal-header\">\r\n								<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n								<h3>Select Patient</h3>\r\n							</div>\r\n							<div class=\"modal-body\">\r\n								<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n									<table id=\"search-panel\" style=\"width:100%\" >\r\n										<tr>\r\n											<td align=\'center\' style=\"border:0px solid\">\r\n												Patient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n												<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n												<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %>\r\n											</td>\r\n										</tr>\r\n									</table>\r\n								</div>\r\n								<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n									<br/>\r\n									Loading..\r\n								</div>\r\n							</div>\r\n						</div>\r\n						<div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n							Ref : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n							<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\n							Patient : \r\n							<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n							<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n							Date : <%= text_field_tag \'date\',date  ,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\n							Time : <%= text_field_tag \'time\',time,:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n						</div>\r\n						<div id=\'patient\'></div>\r\n						<script>\r\n							$(\"#record-time\").kendoTimePicker({\r\n							value: \'<%= time %>\',\r\n							interval: 10\r\n							});\r\n							$(\"#record-date\").kendoDatePicker({\r\n							  value: \'<%= date %>\',\r\n							});\r\n							\r\n							$(\"#ref-record\").kendoAutoComplete();\r\n							$(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n							\r\n							function doSearch(){\r\n							$(\'#search-result\').css(\"display\", \"block\");\r\n							url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n							   url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n							   url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n							$.ajax({\r\n							url: url,\r\n							success: function(data){\r\n							$(\'#search-result\').html(data);  \r\n							}\r\n							});\r\n							   \r\n							}\r\n							function doClose(){\r\n							  \r\n							$(\'#SelectPatient\').hide();\r\n							$(\".modal-backdrop\").hide(\'fade\');\r\n							\r\n							}\r\n							\r\n							\r\n							\r\n							function doSelect(value){\r\n							$(\'#<%=fid%>\').val(value);\r\n							   \r\n							   url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n							url += \'&id=\'+value\r\n							   url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n							   \r\n							$.ajax({\r\n							url: url,\r\n							success: function(data){\r\n							     $(\'#patient\').html(data);  \r\n							     $(\'#SelectPatient\').hide();\r\n							     $(\".modal-backdrop\").hide(\'fade\');\r\n							}\r\n							});\r\n							   \r\n							}\r\n							\r\n							\r\n							\r\n							\r\n							\r\n							$(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n							if(event.keyCode == 13) {\r\n							doSearch();\r\n							 event.preventDefault();\r\n							 return false;\r\n							}else{\r\n							\r\n							$(\'#search-result\').html(\'Loading..\')\r\n							}\r\n							});\r\n							\r\n							<% if params[:patient_id] %>\r\n							$(\'#search-result\').css(\"display\", \"block\");\r\n							doSelect(\'<%=params[:patient_id]%>\')    \r\n							<% else %>\r\n							\r\n							$(\'#SelectPatient\').modal({\r\n							           show: true, \r\n							           backdrop: \'static\',\r\n							           keyboard: true\r\n							})\r\n							\r\n							     \r\n							<% end %>\r\n							\r\n							\r\n						</script>\r\n						<%\r\n							params[:form] = {}\r\n							params[:form][:model] = model\r\n							params[:form][:form] = f\r\n							params[:form][:record] = record\r\n							\r\n							\r\n							\r\n							%>\r\n						<p>\r\n							<%= this.form.html_safe %>\r\n						</p>\r\n						<br/>\r\n						<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n						<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n						<% end %>\r\n						<span style=\"color:green\"><%=flash[:notice]%></span>\r\n						<% end %>\r\n					</div>\r\n				</div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<script>\r\n	var validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n	$(\"#record-submit\").click(function() {\r\n	\r\n	if (!validator.validate()||$(\'#0\').val()==\"\") {\r\n	alert(\'Please fill all information\');\r\n	if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\n	return false;\r\n	\r\n	}else{\r\n	    return true;\r\n	    if(confirm(\'Are you sure?\')==true){\r\n	        return true;\r\n	    }\r\n	    return false;\r\n	}\r\n	});\r\n</script>',NULL,NULL,NULL,'2016-11-03 08:14:48','2016-11-03 08:14:48','create',''),(2695,'document_name',1083,1,'\'appointment\'',NULL,NULL,NULL,'2016-11-07 01:54:49','2016-11-07 01:54:49',NULL,NULL),(2696,'document_name',1084,1,'\'hpb\'',NULL,NULL,NULL,'2016-11-07 02:58:07','2016-11-07 02:58:07',NULL,NULL),(2698,'index',1085,2,'<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\n	end\r\n	if session[module_name]\r\n	  params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n	%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n	if request.post?\r\n	    r_app = get_model[:appointment].find(params[:app_id])\r\n	    status = \'Waiting\'\r\n	    if params[:app_status]\r\n	        status = params[:app_status]\r\n	    end\r\n	    r_app.update_attributes :status=>params[:app_status], :qn=>params[:qn]\r\n	end\r\n	\r\n	\r\n	\r\n	if params[:obj_id]\r\n	    now = Time.now \r\n	\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n					<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Add Visit</button></a>\r\n					<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n						-->\r\n					<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Calendar</button></a>\r\n					<a href=\"../Report/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n					<a href=\"nurse_index?date=<%= params[:date] %>\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-heart\"></i><br />Nurse Index</button></a>\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\" >\r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n					<h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n%>\r\n\r\n\r\n<% if false %>\r\n<%\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed waiting arrived preparing processing recovery completed discharge cancelled no_show}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	list = aps.clone\r\n	id = \'\'\r\n	aps.collect!{|i| \r\n	id = i.id\r\n	  if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n	     patient = patient_model.find(m.patient_id)\r\n	     if patient \r\n	     provider = p_model.find(i.provider)\r\n	     visit_type = visits[i.visit_type]\r\n	     provider_name = \'-\'\r\n	     provider_name = provider.name if provider\r\n	     procedure_name = \'-\'\r\n	     pro = models[:procedure].find(i.procedure) \r\n	     procedure_name = pro.name if pro\r\n	     patient = patient_model.new unless patient \r\n	     hn = \'-\'\r\n	     hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n	     public_id = \'-\'\r\n	    # public_id = patient.public_id if patient\r\n	    # change to use update queue number\r\n	    #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n	    #  :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	    #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	    #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n	    #  :visit_type=>visit_type\r\n	    #  }\r\n	    n_txt = []\r\n	    if !i[:qn].nil?\r\n	        n_txt << \"Q:\\\\#{i[:qn]}\"\r\n	    end\r\n	    if i.note != \'\'\r\n	        n_txt << i.note\r\n	    end\r\n	    d_qn = \"...\"\r\n	    d_qn = \"..\\\\#{patient[:hn].tr(\'/\',\'\')[-5..-3]}/\\\\#{patient[:hn].tr(\'/\',\'\')[-2..-1]}\" if patient and  patient[:hn]\r\n	    \r\n	    c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	     :pending_ctrl=>link_to(\'Arrived\',\"javascript:patient_q(\'\\\\#{i.id}\',\'\\\\#{d_qn}\');\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n	     :visit_type=>visit_type,\r\n	     :note=>n_txt.join(\' / \')\r\n	    }\r\n	     \r\n	    if i.status==\'Waiting\' or i.status==\'Arrived\' or i.status==\'Preparing\'\r\n	        c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    \r\n	\r\n	    #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    else\r\n	        status = \'btn-info\'\r\n	        status = \'\' if i.status ==\'Completed\' or \'Discharge\'\r\n	        c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n	    end\r\n	     c\r\n	    end\r\n	  end\r\n	}.compact!\r\n	\r\n	waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\' or i[:status]==\'Arrived\' or i[:status]==\'Preparing\'}.compact\r\n	\r\n	processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n	\r\n	completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' or i[:status]==\'Discharge\' }.compact\r\n	\r\n	cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n	\r\n	table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n	:note=>\'Note\',:visit_type=>\'Group\' }\r\n	\r\n	%>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in processing\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Processing \r\n				<div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in completed\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Completed \r\n				<div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in cancelling\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Cancelled &amp; No show \r\n				<div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<!--\r\n		<div class=\"left\" style=\"width:50%\">\r\n		   <div class=\"w-box\" id=\"w_sort05\">    \r\n		        <div class=\"w-box-header\">\r\n		            Today Patients\r\n			    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n			    </div>\r\n			    <div class=\"w-box-content cnt_a\">\r\n			        content\r\n		        </div>\r\n		    </div>\r\n		</div>\r\n		-->\r\n</div>\r\n<% end %>\r\n<br/>\r\n<br/>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:320px;left:50%;margin-left:-360px\">\r\n	<div class=\"modal-header\">\r\n		<a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n		<h3>Patient Queue</h3>\r\n	</div>\r\n	<div class=\"modal-body\">\r\n		<form name=\'q\' method=\'post\'>\r\n			<span style=\'width:80px\'>Queue Number : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"qn\" id=\'qn\' style=\"width:50px\"/>\r\n			</span>\r\n			<input type=\"hidden\" name=\"app_id\" id=\"app_id\" value=\"\">\r\n			<input type=\"hidden\" name=\"app_status\" id=\"app_status\" value=\"Arrived\">\r\n			<div class=\"clear\"></div>\r\n			<input type=\"submit\" name=\"Submit\" value=\"Submit\" class=\"btn btn-success\"/>\r\n		</form>\r\n	</div>\r\n</div>\r\n<script>\r\n	function patient_q(app_id) {\r\n	    console.log(\"appointment id : \" + app_id);\r\n	    $(\'#app_id\').val(app_id);\r\n	    $(\'#modal\').modal({\r\n	        show: true, \r\n	        backdrop: \'static\',\r\n	        keyboard: true\r\n	    });\r\n	}\r\n	function patient_q(app_id, qn) {\r\n	    console.log(\"appointment id : \" + app_id);\r\n	    $(\'#qn\').val(qn);\r\n	    $(\'#app_id\').val(app_id);\r\n	    $(\'#modal\').modal({\r\n	        show: true, \r\n	        backdrop: \'static\',\r\n	        keyboard: true\r\n	    });\r\n	}\r\n</script>\r\n\r\n<script>\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'index_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        setTimeout(feed_page(100), 0);\r\n        loadPartial();\r\n    });\r\n    \r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Summary\',\'patient_summary?date=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Nurse Index\',\'nurse_index?date=\'+params[:date] %> |\r\n<!--<%= link_to \'Case Index\',\'case_index?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Patient Status\',\'patient_status?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Patient Board\',\'../Feed/nurse_board?date=\'+params[:date] %> |-->\r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2016-11-07 03:24:14','2016-11-07 03:24:14','index',''),(2699,'index_partial',1085,3,'<%\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	list = aps.clone\r\n	id = \'\'\r\n	aps.collect!{|i| \r\n	id = i.id\r\n	  if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n	     patient = patient_model.find(m.patient_id)\r\n	     if patient \r\n	     provider = p_model.find(i.provider)\r\n	     visit_type = visits[i.visit_type]\r\n	     provider_name = \'NA\'\r\n	     provider_name = provider.name if provider\r\n	     procedure_name = \'NA\'\r\n	     pro = models[:procedure].find(i.procedure) \r\n	     procedure_name = pro.name if pro\r\n	     patient = patient_model.new unless patient \r\n\r\n	     hn = \'-\'\r\n	   #  hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n	     procedure_name = link_to(\'Detail\', \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\",:class=>\'btn\')\r\n	     public_id = \'-\'\r\n	    # public_id = patient.public_id if patient\r\n	    # change to use update queue number\r\n	    #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n	    #  :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	    #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	    #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n	    #  :visit_type=>visit_type\r\n	    #  }\r\n	    n_txt = []\r\n	    if !i[:qn].nil?\r\n	        n_txt << \"Q:\\\\#{i[:qn]}\"\r\n	    end\r\n	    if i.note != \'\'\r\n	        n_txt << i.note\r\n	    end\r\n	    d_qn = \"...\"\r\n	    d_qn = \"..\\\\#{patient[:hn].tr(\'/\',\'\')[-5..-3]}/\\\\#{patient[:hn].tr(\'/\',\'\')[-2..-1]}\" if patient and  patient[:hn]\r\n	    \r\n	    @record = i\r\n	    @document = @current_project.get_document \'appointment\'\r\n	    \r\n	    sector = \'\'\r\n	    sector = render_value \'sector\'\r\n	    reimbursement = \'\'\r\n	    reimbursement = render_value \'reimbursement\'\r\n	    \r\n	    \r\n	    \r\n	    c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id.to_s}\"),\r\n	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	     :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Arrived\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n	     :visit_type=>visit_type,:sector=>sector,:reimbursement=>reimbursement,:indication=>indications[i.indication],\r\n	     :note=>n_txt.join(\' / \')\r\n	    }\r\n	    \r\n	   \r\n	    \r\n	     \r\n	    if i.status==\'Waiting\' or i.status==\'Arrived\' or i.status==\'Preparing\'\r\n	        c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    \r\n	\r\n	    #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    else\r\n	        status = \'btn-info\'\r\n	        status = \'\' if i.status ==\'Completed\' or \'Discharge\'\r\n	        c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n	    end\r\n	     c\r\n	    end\r\n	  end\r\n	}.compact!\r\n	\r\n	waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\' or i[:status]==\'Arrived\' or i[:status]==\'Preparing\'}.compact\r\n	\r\n	processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n	\r\n	completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' or i[:status]==\'Discharge\' }.compact\r\n	\r\n	cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n	\r\n	table_model = %w{ hn patient sector reimbursement indication procedure}.collect{|i| i.to_sym}\r\n	\r\n	#table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n	\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Doctor\',:procedure=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n	:indication=>\'Diangonsis\',:note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Actions\',:sector=>\'เขต\', :reimbursement=>\'สิทธิ์\' }\r\n	\r\n	%>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model,:data=>tmp ,:labels=>labels %>\r\n				<%# tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in processing\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Processing \r\n				<div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in completed\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Completed \r\n				<div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in cancelling\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Cancelled &amp; No show \r\n				<div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<!--\r\n		<div class=\"left\" style=\"width:50%\">\r\n		   <div class=\"w-box\" id=\"w_sort05\">    \r\n		        <div class=\"w-box-header\">\r\n		            Today Patients\r\n			    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n			    </div>\r\n			    <div class=\"w-box-content cnt_a\">\r\n			        content\r\n		        </div>\r\n		    </div>\r\n		</div>\r\n		-->\r\n</div>',NULL,NULL,NULL,'2016-11-07 03:28:26','2016-11-07 03:28:26','index_partial',''),(2700,'document_name',1087,1,'\'operative_note\'',NULL,NULL,NULL,'2016-11-07 10:16:34','2016-11-07 10:16:34',NULL,NULL),(2701,'document_name',1088,1,'\'operative_note\'',NULL,NULL,NULL,'2016-11-07 10:22:36','2016-11-07 10:22:36',NULL,NULL),(2702,'document_name',1089,1,'\'operative_note\'',NULL,NULL,NULL,'2016-11-07 10:22:49','2016-11-07 10:22:49',NULL,NULL),(2703,'mail',666,3,'<%\r\n    # Test Pass .. soup@server.esm-solution.com\r\n    # to = \"chaiwat.bootchai@gmail.com\"\r\n    # from = \'thkjr@esm-solutino.com\'\r\n    # subject = \"the process has been finished\"\r\n    # content = \"The process has finished successfully.\"\r\n    # `mail -s \"\\\\#{subject}\" \\\\#{to} -- -f \\\\#{from} <<EOM\r\n    #   \\\\#{content}\r\n    # EOM`\r\n    \r\n    require \'net/smtp\'\r\n \r\n    message =\r\n<<EOF\r\nFrom: ESM Chaiwat <chaiwat@esm-solution.com>\r\nTo: MR.CHAIWAT <chaiwat.bootchai@gmail.com>\r\nSubject: SMTP ESM E-mail\r\nThis is a email message.\r\nEOF\r\n     \r\n    smtp = Net::SMTP.new \'smtp.gmail.com\', 587\r\n    smtp.enable_starttls\r\n    smtp.start(\'gmail.com\', \'chaiwat@esm-solution.com\', \'zamachita\', :login)\r\n    smtp.send_message message, \'chaiwat@esm-solution.com\', \'chaiwat.bootchai@gmail.com\'\r\n    smtp.finish\r\n%>\r\n',NULL,NULL,NULL,'2016-11-07 15:12:18','2016-11-07 15:12:18','mail',''),(2704,'reset_password',689,3,'<%= render :inline=>this.init %>\r\n<%\r\n    require \'net/smtp\'\r\n \r\n    uid = params[:uid] # user_id\r\n    pid = params[:pid] # provider_id\r\n\r\n    prov = @models[:provider].find(pid)\r\n    user = @ehr_models[:user].find(uid)\r\n    \r\n    to = user[:email]\r\n    name = prov[:name]\r\n    \r\n    # pass = rand(10**24-10)+10\r\n    pass = 8.times.map{ Random.rand(10).to_s } .join(\'\')\r\n    \r\n    salt = User.random_string(10) \r\n    hashed_password = User.encrypt(pass, salt)\r\n \r\n    user.update_attributes :salt=>salt, :hashed_password=>hashed_password, :pin=>\'\'\r\n \r\n    message =\r\n<<EOF\r\nFrom: ESM Chaiwat <chaiwat@esm-solution.com>\r\nTo: \\\\#{name} <\\\\#{to}>\r\nSubject: [THKJR.info] Reset Password\r\n\r\nเรียน \\\\#{name},\r\n\r\nทางระบบได้ทำการ reset password โดยท่านสามารถทำการ login ในระบบ https://thkjr.info โดยใช้\r\n\r\nUsername : \\\\#{user[:login]}\r\nPassword : \\\\#{pass}\r\n\r\nเมื่อท่าน login แล้ว ให้ทำการสร้าง private password โดยเข้าไปที่\r\n\r\nเมนูบาร์ Setting > Private Password\r\n\r\nจึงเรียนมาเพื่อทราบ\r\n\r\n--\r\nChaiwat Bootchai\r\nSystem Administrator\r\nTHKJR.info\r\n\r\nEOF\r\n     \r\n	smtp = Net::SMTP.new \'smtp.gmail.com\', 587\r\n    smtp.enable_starttls\r\n    smtp.start(\'gmail.com\', \'chaiwat@esm-solution.com\', \'zamachita\', :login)\r\n    smtp.send_message message, \'chaiwat@esm-solution.com\', \"\\\\#{to}\"\r\n    smtp.finish   \r\n%>\r\n<%# message %>\r\n<script>\r\n    window.location = \"index\";\r\n</script>',NULL,NULL,NULL,'2016-11-07 16:32:03','2016-11-07 16:32:03','reset_password',''),(2705,'all_provider',624,3,'<%\r\n    prov = get_model[:provider].all\r\n    a_prov = prov.collect{|i| [i[:name], i[:provider_type]]}\r\n    a_prov.each do |i|\r\n%>\r\n<%= i.join(\',\') %><br/>\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-11-08 02:31:46','2016-11-08 02:31:46','all_provider',''),(2706,'form',947,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    $(document).ready(function() {\r\n        // TVC Element\r\n            \r\n            $(\'#larynx_ab_tvc_movement\').detach().appendTo(\'#panel_larynx_abnormal_item_2\');\r\n            $(\'#larynx_ab_tvc_other\').detach().appendTo(\'#panel_larynx_abnormal_item_2\');\r\n            \r\n        x = $(\'#data-larynx_ab_tvc\').val();\r\n        if (x == \'Movement\') {\r\n            $(\'#larynx_ab_tvc_movement\').show();\r\n        } else if (x == \'Other\') {\r\n            $(\'#larynx_ab_tvc_other\').show();\r\n        } else {\r\n            $(\'#larynx_ab_tvc_movement\').hide();\r\n            $(\'#larynx_ab_tvc_other\').hide();\r\n        }\r\n        \r\n        // arytenoid\r\n        $(\'#larynx_ab_arytenoid_other\').detach().appendTo(\'#panel_larynx_abnormal_item_3\');\r\n        \r\n        x = $(\'#data-larynx_ab_arytenoid\').val();\r\n        if (x == \'Abnormal\') {\r\n            $(\'#larynx_ab_arytenoid_other\').show();\r\n        } else {\r\n            $(\'#larynx_ab_arytenoid_other\').hide();\r\n        }\r\n    });\r\n</script>',NULL,NULL,NULL,'2016-11-08 04:45:32','2016-11-08 04:45:32','form',''),(2707,'last_updated',1090,3,'<%\r\n    date = Time.now\r\n    if params[:date]\r\n        date = params[:date]\r\n    end\r\n    date = Date.to_mongo(params[:date])\r\n    \r\n    a_app = get_model[:appointment].where(:date=>Date.to_mongo(date)).all\r\n    a_app = a_app.sort_by{|i| i[:updated_at]}.reverse\r\n\r\n\r\n    res = {}\r\n    if !a_app.empty?\r\n        res[:last_updated] = a_app.first[:updated_at]\r\n        res[:app_first] = a_app.first[:updated_at]\r\n        res[:app_last] = a_app.last[:updated_at]\r\n    else\r\n        res[:last_updated] = \"\"\r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2016-11-08 07:32:55','2016-11-08 07:32:55','last','*'),(2708,'index',1090,2,'<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\n	end\r\n	if session[module_name]\r\n	  params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n	%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n	\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n	if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Add & Continue\"\r\n%>\r\n<script>\r\n    // window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n    window.location = \"../OutPatientForm/create?patient_id=<%=patient.id.to_s%>&record_name=<%=patient[:hn]%>&parent_id=<%=rec_pm_app.id.to_s%>&return=../Home/index\";\r\n</script>\r\n<%\r\n        end\r\n    end\r\n	\r\n	\r\n	\r\n	if params[:obj_id]\r\n	    now = Time.now \r\n	\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n					<!--<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Add Visit</button></a>-->\r\n					<a href=\"javascript:add_patient()\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-contact_blue_add\"></i><br />Add Patient</button></a>\r\n					<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Calendar</button></a>\r\n					<a href=\"../Report/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\" >\r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n					<h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n    \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                <br/>\r\n                <div id=\"patient_msg\"></div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\" selected><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Add & Continue\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n	\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#data-hn\').change(update_patient);\r\n    });\r\n</script>\r\n\r\n<script>\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'index_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        setTimeout(feed_page(100), 0);\r\n        loadPartial();\r\n    });\r\n    \r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2016-11-08 07:33:52','2016-11-08 07:33:52','index',''),(2709,'index_partial',1090,3,'<%\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	id = \'\'\r\n	a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = module_model.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n	f_liv = {}\r\n	liver = module_model.where(:module_name=>\"\\\\#{@current_project.name}#out_patient_form\", :parent_id=>pa_id).all\r\n	liver.each do |i|\r\n	    f_liv[i[:patient_id].to_s] = i.id.to_s\r\n	end\r\n	\r\n	aps.collect!{|i| \r\n        id = i.id\r\n        if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n            pat_id = m.patient_id.to_s\r\n    	     patient = patient_model.find(m.patient_id)\r\n    	     if patient \r\n        	     provider = p_model.find(i.provider)\r\n        	     visit_type = visits[i.visit_type]\r\n        	     provider_name = \'NA\'\r\n        	     provider_name = provider.name if provider\r\n        	     procedure_name = \'NA\'\r\n        	     pro = models[:procedure].find(i.procedure) \r\n        	     procedure_name = pro.name if pro\r\n        	     patient = patient_model.new unless patient \r\n        	     hn = \'-\'\r\n        	     \r\n        	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n        	     provider_name  = link_to(provider_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     procedure_name = link_to(procedure_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     public_id = \'-\'\r\n    	    \r\n                c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id.to_s}\"),\r\n        	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        	     :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Arrived\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n        	     :visit_type=>visit_type,\r\n        	     :note=>i[:note]\r\n                }\r\n                \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info \', :style=>\'width:45px\')\r\n                v_link = link_to(\'<i class=\"splashy-add\"></i> Add\'.html_safe, \r\n                    \"../OutPatientForm/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/index\", \r\n                    :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                c_link = \'&nbsp;&nbsp;&nbsp;&nbsp;<i class=\"splashy-remove\"></i>\'\r\n                if f_liv[pat_id]\r\n                    c_link = \'&nbsp;&nbsp;&nbsp;&nbsp;<i class=\"splashy-check\"></i>\'\r\n                    v_link = link_to(\'<i class=\"splashy-document_a4\"></i> View\'.html_safe, \r\n                        \"../OutPatientForm/show?id=\\\\#{f_liv[pat_id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                end\r\n                # c[:processing_ctrl]= \"\\\\#{v_link} \\\\#{d_link}\".html_safe \r\n                c[:processing_ctrl]= \"\\\\#{d_link}\".html_safe \r\n                \r\n                c[:out_pat] = c_link.html_safe\r\n                \r\n                c\r\n            end\r\n        end\r\n	}.compact!\r\n	\r\n	table_model = %w{ hn patient provider out_pat processing_ctrl note }.collect{|i| i.to_sym}\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:procedure=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n	:note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Actions\', :out_pat=>\'Out Patient Form\' }\r\n	\r\n	%>\r\n	\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=aps.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = aps.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model,:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = aps.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model,:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n</div>',NULL,NULL,NULL,'2016-11-08 07:34:15','2016-11-08 07:34:15','index_partial',''),(2710,'search',1090,2,'<h1> Search Result </h1>\r\n<% \r\n	models = get_model\r\n	\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	\r\n	fields = %w{hn public_id first_name last_name}\r\n	query = \'\'\r\n	if params[:query]\r\n	    query = params[:query].strip\r\n	end\r\n	\r\n	keys = []\r\n	\r\n	keys << {:hn=>Regexp.new(query)}\r\n	keys << {:first_name=>Regexp.new(query)}\r\n	keys << {:last_name=>Regexp.new(query)}\r\n	keys << {:public_id=>query} if query.size==13\r\n	\r\n	criteria = {\'$or\'=>keys}\r\n	\r\n	patients = patient_model.where(criteria).limit(20).all  \r\n	\r\n	app_name = \"\\\\#{@current_project.name}#appointment\"\r\n	app_model = models[:appointment]\r\n	\r\n\r\n	\r\n	fields.insert(0, \'no\')\r\n	r = 0\r\n%>\r\nResult for \'<%= query %>\' = <%= patients.count %>\r\n<hr/>\r\n<%\r\nif patients.count != 0\r\n%>\r\n<%= tabular :model=>fields,:data=>patients,:n=>10 do |row,out|\r\n	am = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).order(\'date\').last\r\n	r += 1\r\n	if am\r\n        app = app_model.where(:id=>am.module_id).first\r\n	\r\n        if @current_role!=\'pathologist\'\r\n            url = \"../Home/patient_record?id=\\\\#{am.module_id}\"\r\n        else\r\n            url = \"../Home/patho_patient_record?id=\\\\#{am.module_id}\"\r\n        end\r\n	\r\n        out[0] = link_to(\"\\\\#{r}.\", url)\r\n        out[1] = link_to(row.hn,url)\r\n        out[2] = link_to(row.public_id,url)\r\n        out[3] = link_to(row.first_name,url)\r\n        out[4] = link_to(row.last_name,url)\r\n        n = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).count\r\n        	\r\n        extra = link_to(\'Add Visit\', \"../Appointment/create?obj_id=\\\\#{row.id}&return=../Home/index\", :class=>\'btn btn-mini btn-success\') + \' \' + link_to(\"Detail (\\\\#{n})\", url, :class=>\'btn btn-mini btn-info\')\r\n        	\r\n        	\r\n        out << extra.html_safe\r\n        \r\n	else\r\n	    out[0] = \"\\\\#{r}.\"\r\n        out << link_to(\'Add Visit\', \"../Appointment/create?obj_id=\\\\#{row.id}&return=../Home/index\", :class=>\'btn btn-mini btn-success\')\r\n	end\r\n	\r\n        out\r\nend\r\n	\r\n%>\r\n<%\r\nelse\r\n%>\r\n<h3>No patient found</h3>\r\n<%= link_to \'New patient\', \"../../www/Patient/create?hn=\\\\#{params[:query]}&return=/\\\\#{@current_project.name}/Appointment/create?return=../Home/index\", :class=>\'btn btn-info\' %>\r\n<%\r\nend\r\n%>\r\n<hr/>',NULL,NULL,NULL,'2016-11-08 07:40:29','2016-11-08 07:40:29','search',''),(2711,'document_name',1091,1,'\'out_patient_form\'',NULL,NULL,NULL,'2016-11-09 11:22:12','2016-11-09 11:22:12',NULL,NULL),(2712,'document_name',1092,1,'\'operative_data_form\'',NULL,NULL,NULL,'2016-11-09 11:32:56','2016-11-09 11:32:56',NULL,NULL),(2713,'document_name',1093,1,'\'pathological_report_form\'',NULL,NULL,NULL,'2016-11-09 11:33:39','2016-11-09 11:33:39',NULL,NULL),(2714,'print_report',502,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  attachment_model = @models[:attachment]\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n# @document = @model[:colono].get_document\r\ndx_stat = {} \r\ndg_stat = {}\r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n \r\n \r\n\r\n\r\n \r\n ml =  @module_model.where(:parent_id=>i.id).all\r\n \r\n diagnosis = \'\'\r\n diagnosis_group = \'\'\r\n provider = providers[ap.provider.to_s]\r\n provider_name = provider.name if provider\r\n attachments = []\r\n#  provider_name = ml.size.to_s\r\n \r\n for x in ml\r\n    if x.module_name==\"\\\\#{@current_project.name}#colono\"\r\n        \r\n        colo = @models[:colono].find(x.module_id)\r\n  \r\n        if colo\r\n            provider_name = colo.id.to_s\r\n            \r\n            provider = providers[colo.endoscopist.to_s]\r\n            provider_name = provider.name if provider\r\n            diagnosis = colo.diagnosis_text\r\n            attachments = colo.image\r\n            \r\n            # diagnosis_group\r\n            # 0 - Normal\r\n            # 1 - Polyp\r\n            # 2 - Diverticulum\r\n            # \r\n            diagnosis_group = colo.diagnosis_group\r\n            a_dx = diagnosis_group.split(\'|\')\r\n            tmp = {}\r\n            a_dx.each do |i|\r\n                if !dx_stat.has_key? i\r\n                    dx_stat[i] = 0\r\n                end\r\n                \r\n                if !tmp.has_key? i\r\n                    tmp[i] = 0\r\n                    dx_stat[i] += 1\r\n                end\r\n            end\r\n            dx_group = tmp.keys.join(\'|\')\r\n            if !dg_stat.has_key? dx_group\r\n                dg_stat[dx_group] = 0\r\n            end\r\n            dg_stat[dx_group] += 1\r\n        end\r\n    end\r\n end\r\n \r\n \r\n\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year} ปี\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>ml.collect{|i| i.module_name.split(\'#\')[-1].humanize}.join(\',\'),\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider_name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'attachments\'=>attachments,\r\n    \'age\'=>age,\r\n    \'ml\'=>ml,\r\n    \'diagnosis\'=>diagnosis.html_safe,\r\n    \'diagnosis_group\'=>diagnosis_group.html_safe,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\n\r\n\r\nlist = json_data.sort{|a,b| b[\'diagnosis_group\']<=>a[\'diagnosis_group\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Summary Report</title>\r\n<%# javascript_include_tag \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' height=\"60px\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงรายการผู้ป่วย\r\n<span style=\"float:right\">ประจำวันที่ \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>HN</th>\r\n    <th >อายุ</th>\r\n    <th>Procedure</th>\r\n    <th>Diagnosis</th>\r\n    <th>Provider</th>\r\n    <th>Link</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n<% \r\n    sp = {}\r\n    index = 0 \r\n    list.each_with_index do |i,ix|  \r\n        pps = i[\'procedure\'].split(\',\')\r\n        for pp in pps\r\n            if sp.has_key?(pp)\r\n                sp[pp] = sp[pp] + 1\r\n            else\r\n                sp[pp] = 1\r\n            end\r\n        end\r\n    if params[:filter]==nil or (i[\'diagnosis\']!=\'\' and i[\'diagnosis_group\']!=\'0\') \r\n\r\n    \r\n%> \r\n    <tr class=\"page-break\">\r\n    <td><%=index+1%>.</td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%></td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'age\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    <td><%=i[\'diagnosis\']%></td>\r\n    <td><%=i[\'provider\']%></td>\r\n    <td><%=link_to(\'Detail\',\"patient_record?id=\\\\#{i[\'id\']}\")%></td>\r\n    </tr>\r\n    \r\n  \r\n    <tr>\r\n    <td colspan=\"8\">\r\n        <%  \r\n        if true\r\n            \r\n            # atts_list = record.image[0..4]\r\n            # if record.selected_image and record.selected_image.size > 0\r\n              \r\n            #   atts_list = record.selected_image[0..4]\r\n               \r\n            # end\r\n           \r\n           \r\n            # attachments = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n            #  old\r\n            # attachments = attachment_model.find(i[\'attachments\'])[0..4]\r\n            attachments = attachment_model.find(i[\'attachments\'][0..4])\r\n        for j in attachments\r\n        %>\r\n        <% # if @current_role != \'developer\' %>\r\n        <%= image_tag j.path + \"?thumb=1\", :width=>80, :style=>\'\' %>\r\n        <% # end %>\r\n        <% end %>\r\n        <% end %>\r\n    </td>    \r\n        \r\n    </tr>\r\n    \r\n    <% \r\n    \r\n    index+=1\r\n    end %>\r\n    <% end %>\r\n</tbody>\r\n<%\r\n    dx_lbn = [\'Normal\', \'Polyp\', \'Diverticulum\', \'Hemorrhoid\', \'Mass\', \'Ulcer\', \'Other\']\r\n    dx_val = Array.new(dx_lbn.count + 1).collect{|i| 0}\r\n    dx_pie = []\r\n    dx_map = {}\r\n    dx_stat.keys.each do |i|\r\n        r = {}\r\n        idx = i.to_i\r\n        k = \'Other\'\r\n        v = dx_stat[i]\r\n        if idx <= 5\r\n            k = dx_lbn[idx]\r\n            v = dx_stat[i]\r\n        end\r\n        \r\n        if !dx_map.has_key? k\r\n            dx_map[k] = 0\r\n        end\r\n        dx_map[k] += v\r\n        \r\n        # if idx > 5\r\n        #     dx_val[6] += dx_stat[i]\r\n        #     r[:category] = dx_lbn[6]\r\n        #     r[:value] = dx_val[6]\r\n        # else\r\n        #     dx_val[idx] = dx_stat[i]\r\n        #     r[:category] = dx_lbn[idx]\r\n        #     r[:value] = dx_val[idx]\r\n        # end\r\n        # dx_pie << r\r\n    end\r\n%>\r\n    <tr>\r\n        <td colspan=\"4\">\r\n            <div class=\'row-fluid\'>\r\n                <b>สรุปรายการที่พบ</b><br/>\r\n                <blockquote>\r\n                <%\r\n                    n = 0\r\n                    dx_lbn.each do |i|\r\n                %>\r\n                    <b><%= n %>. <%= i %> : </b> <%= dx_map[i] ? dx_map[i] : 0 %><br/>\r\n                <%\r\n                        n += 1\r\n                    end\r\n                %>  \r\n                </blockquote>\r\n                <%# dx_map.to_json.html_safe %>\r\n                <!--<div id=\"dx-chart\" style=\"border:0px solid;width:480%;min-height:300px\"></div>-->\r\n            </div>\r\n        </td>  \r\n        <td colspan=\"4\">\r\n            <div class=\'row-fluid\'>\r\n                <b>สรุปรายการที่พบ</b><br/>\r\n                <blockquote>\r\n                <%\r\n                    n = 1\r\n                    dg_stat.each do |i,v|\r\n                        arr = i.split(\'|\')\r\n                        txt = []\r\n                        arr.each do |a|\r\n                            idx = a.to_i\r\n                            if idx > 5\r\n                                txt << \'Other\'\r\n                            else\r\n                                txt << dx_lbn[idx]\r\n                            end\r\n                        end\r\n                %>\r\n                    <b><%= n %>. <%= txt.join(\', \') %> : </b> <%= v %><br/>\r\n                <%\r\n                        n += 1\r\n                    end\r\n                %>  \r\n                </blockquote>\r\n                <%# dx_map.to_json.html_safe %>\r\n                <!--<div id=\"dx-chart\" style=\"border:0px solid;width:480%;min-height:300px\"></div>-->\r\n            </div>\r\n        </td>  \r\n    </tr>\r\n  </table><br/>\r\n\r\n<script>\r\n<%\r\n    dx_lbn = [\'Normal\', \'Polyp\', \'Diverticulum\', \'Hemorrhoid\', \'Mass\', \'Ulcer\', \'Other\']\r\n    dx_val = Array.new(dx_lbn.count + 1).collect{|i| 0}\r\n    dx_pie = []\r\n    dx_stat.keys.each do |i|\r\n        r = {}\r\n        idx = i.to_i\r\n        if idx > 5\r\n            dx_val[6] += dx_stat[i]\r\n            r[:category] = dx_lbn[6]\r\n            r[:value] = dx_val[6]\r\n        else\r\n            dx_val[idx] = dx_stat[i]\r\n            r[:category] = dx_lbn[idx]\r\n            r[:value] = dx_val[idx]\r\n        end\r\n        dx_pie << r\r\n    end\r\n%>\r\n    function createChart() {\r\n        /*\r\n                    $(\"#dx-chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Number Diagnosis\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: [<%#dx_val.to_json.html_safe %>]\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%#dx_lbn.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    }); */\r\n                    /*\r\n        $(\"#dx-chart\").kendoChart({\r\n            title: {\r\n                text: \"Diagnosis\"\r\n            },\r\n            legend: {\r\n                position: \"left\"\r\n            },\r\n            seriesDefaults: {\r\n                labels: {\r\n                    visible: true,\r\n                    format : \"{0}\"\r\n                    // format: \"{0}%\"\r\n                }\r\n            },\r\n            series: [{\r\n                type: \"pie\",\r\n                data: <%# dx_pie.to_json.html_safe %>\r\n            }]\r\n        });*/\r\n    }\r\n    /*\r\n    $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n    });*/\r\n</script>  \r\n  \r\n  \r\n<% if false %>\r\n<br/>\r\n  <div><strong>Total procedure</strong></div><br/>\r\n<%\r\nsp.keys.each_with_index do |key, index|\r\n%>\r\n<div><%= key %> : <%= sp[key] %></div>\r\n<%\r\nend\r\nend\r\n%>\r\n  </div>\r\n  </div></div></div></div></div>\r\n  <%# dx_stat.to_json.html_safe %>\r\n</body>\r\n</html>\r\n<% end %>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-11-10 11:17:19','2016-11-10 11:17:19','print',''),(2715,'document_name',1094,1,'\'eus\'',NULL,NULL,NULL,'2016-11-13 10:31:46','2016-11-13 10:31:46',NULL,NULL),(2716,'document_name',1095,1,'\'eus_scope\'',NULL,NULL,NULL,'2016-11-13 10:38:34','2016-11-13 10:38:34',NULL,NULL),(2717,'document_name',1096,1,'\'ercp\'',NULL,NULL,NULL,'2016-11-13 10:39:31','2016-11-13 10:39:31',NULL,NULL),(2718,'document_name',1097,1,'\'ercp_scope\'',NULL,NULL,NULL,'2016-11-13 10:40:52','2016-11-13 10:40:52',NULL,NULL),(2719,'print_partial',1094,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    gas_id = pm.module_id\r\n    record = models[:eus].find(gas_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px;padding-left:20px;padding-right:20px }\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\nheight:200px; \r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n.thumbnail {\r\n  position: relative;\r\n  width: 300x;\r\n  height: 300px;\r\n  overflow: hidden;\r\n}\r\n.thumbnail img {\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 50%;\r\n  height: 100%;\r\n  width: auto;\r\n  -webkit-transform: translate(-50%,-50%);\r\n      -ms-transform: translate(-50%,-50%);\r\n          transform: translate(-50%,-50%);\r\n}\r\n.thumbnail img.portrait {\r\n  width: 100%;\r\n  height: auto;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' height=\'70px\' /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize   if @current_user %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Endoscopic Ultrasound - EUS</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=record.date_note%></v>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n<hr />\r\n    \r\n		<table width=\"100%\"><tr><td width=\"60%\" valign=\"top\">\r\n		\r\n		\r\n     <h4 style=\"padding:0px; margin:0px; margin-left:10px;margin-bottom:5px \">Status : <%=record[\'status\']%> </h4>\r\n						<table width=\"100%\">\r\n				<tr>\r\n					<td><label>Previous opreation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n					<td><label></label> <v><%#render_value \'npotime\' %></v></td>\r\n					<td></td>\r\n				</tr>\r\n				<tr>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \')%></v></td>\r\n					<td><label></label><v> <%#record[\'quality_of_preparate\']%></v></td>\r\n				\r\n				</tr>		\r\n				\r\n			</table>	\r\n		\r\n		<div class=\"clear\"></div>\r\n		\r\n		\r\n</td>\r\n		    <td valign=\"top\" width=\"40%\"><h4 style=\"padding:0px; margin:0px; margin-left:10px; margin-bottom:5px\">Sedation</h4>\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% if record[\'dormicum\']==\'true\'%>\r\n<tr><td>Dormicum : <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'%>\r\n<tr><td>Pethidine : <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'%>\r\n<tr><td>Buscopan : <v><%=record[\'buscopan_mg\']%> mg <%=record[\'route_buscopan\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'%>\r\n<tr><td>Fentanyl : <v><%=record[\'mg_fentanyl\']%> mg <%=record[\'fentanyl_route\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'%>\r\n<tr><td>Diprivan : <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'%>\r\n<tr><td>Valium : <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v> </td></tr>\r\n<% end%>\r\n\r\n<% if record[\'plasil\']==\'true\'%>\r\n<tr><td>Plasil : <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v> </td></tr>\r\n<% end%>\r\n\r\n<% if record[\'other\']==\'true\'%>\r\n<tr><td>Other Note : <v><%=record[\'other_note\']%> </v> </td></tr>\r\n<% end%>\r\n</table></td>\r\n		</tr>\r\n\r\n</table>\r\n\r\n<hr />\r\n<h4>Finding & Procedure</h4>\r\n&nbsp;&nbsp;<label>Procedure summary : </label><v><%=render_value(\'procedure\').split(\"|\").join(\", \")%> <i></i></v>&nbsp;\r\n<p>Start at : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n<%\r\n    scopes_labels = {\'egj_scope\'=>\'EGJ\'}\r\n\r\n    scopes = %w{finding_scope}\r\n\r\n    scopes.each_with_index do |j,index|\r\n    if true\r\n\r\n\r\n    # tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    tag = \'eus\'\r\n    %>\r\n \r\n    <%\r\n    \r\n    text = \"Abnormal\"\r\n    tag_cls = \'\'\r\n    # if record[tag] == \'1\'\r\n    # 	text =  \"Abnormal\"\r\n    # 	 tag_cls = \'color:red\'\r\n    # end\r\n    tag_cls = \'color:red\'\r\n\r\n    label = scopes_labels[j] if scopes_labels[j]\r\n  \r\n  if true  \r\n%>\r\n<p><%= \'Finding List\' %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nend\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Abnormal Type :</td><td>Size :</td><td>Location :</td><td>Treatment :</td><td>Patho No. :</td><td>Abnormal Note :</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n      size= \'-\'\r\n      size = i[\'size\'] if i[\'size\']!=0\r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'size\']%></v></td><td><v><%=i[\'location\']%></v></td><td><v><%=i[\'treatment\']%></v></td><td><v><%=i[\'clip\']%></v></td><td><v><%=i[\'patho_number\'].split(\"|\").join(\", \")%></v></td><td><v><%=i[\'abnormal_note\']%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n<%\r\n    if !record[\'intervention_summary\'].nil? and record[\'intervention_summary\'] != \'\'\r\n%>\r\nIntervention Summary : \r\n<blockquote>\r\n    <%= render_value \'intervention_summary\' %>\r\n</blockquote>\r\n<%\r\n    end\r\n%>\r\n<hr />\r\n\r\n<h4>Note :</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \')%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n    <p>Note: <v><%=record[\'scope_note\']%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	 <div style=\"float:left;width:220px\">\r\n	<div id=\"box\" class=\"thumbnail\" style=\"float:none\">\r\n		<%= image_tag i.path+\"?thumb=2\",:style=>\'display: block; margin: auto;\' %>\r\n	</div>\r\n	<v align=\"center\" style=\"display:block;\" ><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2016-11-14 05:14:35','2016-11-14 05:14:35','print_partial','*'),(2720,'print_partial',1096,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    gas_id = pm.module_id\r\n    record = models[:ercp].find(gas_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px;padding-left:20px;padding-right:20px }\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-a