4 style=\"padding:0px; margin:0px; margin-left:10px;margin-bottom:5px \">Status : <%=record[\'status\']%> </h4>\r\n						<table width=\"100%\">\r\n				<tr>\r\n					<td><label>Previous opreation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n					<td><label></label> <v><%#render_value \'npotime\' %></v></td>\r\n					<td></td>\r\n				</tr>\r\n				<tr>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \')%></v></td>\r\n					<td><label></label><v> <%#record[\'quality_of_preparate\']%></v></td>\r\n				\r\n				</tr>		\r\n				\r\n			</table>	\r\n		\r\n		<div class=\"clear\"></div>\r\n		\r\n		\r\n</td>\r\n		    <td valign=\"top\" width=\"40%\"><h4 style=\"padding:0px; margin:0px; margin-left:10px; margin-bottom:5px\">Sedation</h4>\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% if record[\'dormicum\']==\'true\'%>\r\n<tr><td>Dormicum : <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'%>\r\n<tr><td>Pethidine : <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'%>\r\n<tr><td>Buscopan : <v><%=record[\'buscopan_mg\']%> mg <%=record[\'route_buscopan\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'%>\r\n<tr><td>Fentanyl : <v><%=record[\'mg_fentanyl\']%> mg <%=record[\'fentanyl_route\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'%>\r\n<tr><td>Diprivan : <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'%>\r\n<tr><td>Valium : <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v> </td></tr>\r\n<% end%>\r\n\r\n<% if record[\'plasil\']==\'true\'%>\r\n<tr><td>Plasil : <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v> </td></tr>\r\n<% end%>\r\n\r\n<% if record[\'other\']==\'true\'%>\r\n<tr><td>Other Note : <v><%=record[\'other_note\']%> </v> </td></tr>\r\n<% end%>\r\n</table></td>\r\n		</tr>\r\n\r\n</table>\r\n\r\n<hr />\r\n<h4>Finding & Procedure</h4>\r\n&nbsp;&nbsp;<label>Procedure summary : </label><v><%=render_value(\'procedure\').split(\"|\").join(\", \")%> <i></i></v>&nbsp;\r\n<p>Start at : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n<%\r\n    scopes_labels = {\'egj_scope\'=>\'EGJ\'}\r\n\r\n    scopes = %w{finding_scope}\r\n\r\n    scopes.each_with_index do |j,index|\r\n    if true\r\n\r\n\r\n    # tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    tag = \'eus\'\r\n    %>\r\n \r\n    <%\r\n    \r\n    text = \"Abnormal\"\r\n    tag_cls = \'\'\r\n    # if record[tag] == \'1\'\r\n    # 	text =  \"Abnormal\"\r\n    # 	 tag_cls = \'color:red\'\r\n    # end\r\n    tag_cls = \'color:red\'\r\n\r\n    label = scopes_labels[j] if scopes_labels[j]\r\n  \r\n  if true  \r\n%>\r\n<p><%= \'Finding List\' %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nend\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Abnormal Type :</td><td>Size :</td><td>Location :</td><td>Treatment :</td><td>Patho No. :</td><td>Abnormal Note :</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n      size= \'-\'\r\n      size = i[\'size\'] if i[\'size\']!=0\r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'size\']%></v></td><td><v><%=i[\'location\']%></v></td><td><v><%=i[\'treatment\']%></v></td><td><v><%=i[\'clip\']%></v></td><td><v><%=i[\'patho_number\'].split(\"|\").join(\", \")%></v></td><td><v><%=i[\'abnormal_note\']%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n<%\r\n    if !record[\'intervention_summary\'].nil? and record[\'intervention_summary\'] != \'\'\r\n%>\r\nIntervention Summary : \r\n<blockquote>\r\n    <%= render_value \'intervention_summary\' %>\r\n</blockquote>\r\n<%\r\n    end\r\n%>\r\n<hr />\r\n\r\n<h4>Note :</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \')%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n    <p>Note: <v><%=record[\'scope_note\']%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	 <div style=\"float:left;width:220px\">\r\n	<div id=\"box\" class=\"thumbnail\" style=\"float:none\">\r\n		<%= image_tag i.path+\"?thumb=2\",:style=>\'display: block; margin: auto;\' %>\r\n	</div>\r\n	<v align=\"center\" style=\"display:block;\" ><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-11-14 05:38:57','2016-11-14 05:38:57','print_partial','*'),(2721,'weekly_report',1098,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Weekly Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # params_date = select_date\r\n    # select_date = Date.to_mongo(select_date)\r\n    \r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date , :order=>[:day,:month,:year]%>\r\n\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    # start_date = select_date.beginning_of_month()\r\n    # stop_date = select_date.end_of_month()\r\n    \r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n    all_pm_ercp = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}ercp\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_ercp = bmap all_pm_ercp, \'parent_id\'\r\n    \r\n    all_pm_eus = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}eus\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_eus = bmap all_pm_eus, \'parent_id\'\r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}, :scope=>{\'$ne\'=>\'2\'}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n    colox = colo\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    sigmoid = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}, :scope=>\'2\'},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n    m_sigmoid = bmap sigmoid, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n    \r\n    ercp = @models[:ercp].collection.find({:_id=>{\'$in\'=>all_pm_ercp.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n    m_ercp = bmap ercp, \'_id\'\r\n    \r\n    eus = @models[:eus].collection.find({:_id=>{\'$in\'=>all_pm_eus.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n    m_eus = bmap eus, \'_id\'\r\n \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                # zam data 0-colo, 1-sigmoid, 2-gastro, 3-eus, 4-ercp\r\n                data = [0,0,0,0,0]\r\n                s_c = m_all_pm_colo[pm_app[\'_id\']]  # colo\r\n                s_s = m_all_pm_colo[pm_app[\'_id\']]   # sigmoid\r\n                s_g = m_all_pm_gastro[pm_app[\'_id\']]    # gastro\r\n                s_e = m_all_pm_eus[pm_app[\'_id\']]   # eus\r\n                s_r = m_all_pm_ercp[pm_app[\'_id\']]  # ercp\r\n                \r\n                p_colo = nil\r\n                p_gastro = nil\r\n                p_sig = nil\r\n                p_eus = nil\r\n                p_erc = nil\r\n                \r\n                status = \'Elective\'\r\n                \r\n                if s_c\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[s_c[0][\'module_id\']]\r\n                    if r_colo\r\n                        status = r_colo[0][\'status\']\r\n                        p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    \r\n                end\r\n                # if !s_s.nil?\r\n                #     data[1]+=1    \r\n                    \r\n                #     r_sig = m_sigmoid[s_s[0][\'module_id\']]\r\n                #     if !r_colo.empty?\r\n                #         status = r_sig[0][\'status\']\r\n                #         p_sig = r_sig[0][\'procedure\']\r\n                #     end\r\n                # end\r\n                if s_g\r\n                    data[2]+=1    \r\n                    \r\n                    r_gastro = m_gastro[s_g[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                # if s_e\r\n                #     data[3]+=1    \r\n                    \r\n                #     r_eus = m_eus[s_e[0][\'module_id\']]\r\n                #     if r_eus\r\n                #       status = r_eus[0][\'status\'] \r\n                #       p_eus =r_eus[0][\'procedure\'] \r\n                #     end\r\n                # end\r\n                # if s_r\r\n                #     data[4]+=1    \r\n                    \r\n                #     r_erc = m_ercp[s_r[0][\'module_id\']]\r\n                #     if r_eus\r\n                #       status = r_erc[0][\'status\'] \r\n                #       p_erc =r_erc[0][\'procedure\'] \r\n                #     end\r\n                # end\r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n                dates[date][status] = [0,0,0,0,0] unless dates[date][status]\r\n                \r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                \r\n                if p_colo\r\n                    dates[date][\'p_colo\'] = {} unless dates[date][\'p_colo\']\r\n                    for pi in p_colo.split(\"|\")\r\n                        dates[date][\'p_colo\'][pi] = 0 unless  dates[date][\'p_colo\'][pi]\r\n                        dates[date][\'p_colo\'][pi] += 1 \r\n                    end\r\n                end\r\n                \r\n                if p_gastro\r\n                    dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                    for pi in p_gastro.split(\"|\")\r\n                        dates[date][\'p_gastro\'][pi] = 0 unless  dates[date][\'p_gastro\'][pi]\r\n                        dates[date][\'p_gastro\'][pi] += 1 \r\n                    end\r\n                end\r\n                \r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                    d[0]+= data[0]\r\n                    d[1]+= data[1]\r\n                    d[2]+= data[2]\r\n                    d[3]+= data[3]\r\n                    d[4]+= data[4]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        end\r\n    \r\n    end\r\n    \r\n    %>\r\n    <%#dates.inspect  %>\r\n    <%\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<% \r\nmonth_text=\'\'\r\n    # month_text = month_th[select_date.month-1]+select_date.strftime(\"-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    \r\n    td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.small{\r\n        font-size:0.8em;\r\n    }\r\n    td.date{\r\n        padding:0px;\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n        td.date{\r\n        padding:0px;\r\n        \r\n        width:125px;\r\n        \r\n    }\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n    \r\n    tr.page-break{page-break-after:always;page-break-inside:avoid; page-break-after:auto}\r\n    .force-break{ display: block;page-break-before:always;}\r\n        \r\n    }\r\n    \r\n\r\n    \r\n   table { page-break-inside:auto }\r\n   tr    { page-break-inside:avoid; page-break-after:auto }\r\n    \r\n</style>\r\n<style type=\"text/css\">\r\n\r\n</style>\r\n\r\n<div style=\"width:720px\">\r\n<center><h3>\r\nรายงานจำนวนผู้เข้ารับบริการ \r\n<%=@current_project.get_setting \'report_title_1\' %>\r\n<br/>\r\n<%=@current_project.get_setting \'report_title_2\' %></h3>\r\n\r\n<h4>ระหว่างวันที่ \r\n<%=start_date.strftime(\'%d/%m/%Y\')%> - <%=stop_date.strftime(\'%d/%m/%Y\')%></h4></center>\r\n</div>\r\n<br/>\r\n\r\n<%\r\n    op = [\'C\',\'S\',\'G\',\'EU\',\'ER\']\r\n    ob = [colox,sigmoid,gastro,eus,ercp]\r\n    \r\n    all_app.each do |app|\r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n    end\r\n    \r\n    \r\n%>\r\n\r\n<table border=\'1\' class=\'content\'>\r\n    <tr>\r\n        <td style=\"background:#ffffde\"  >&nbsp;</td>\r\n        <td colspan=\'6\' class=\'Elective tx\'>Elective</td>\r\n        <td colspan=\'6\' class=\'Emergency tx\'>Emergency</td>\r\n        <td colspan=\'6\' class=\'Extratime tx\'>Extratime</td>\r\n        <td colspan=\'6\' class=\'total xt\'>total</td>\r\n    </tr>\r\n    <tr class=\"page-break\">\r\n        <td style=\"background:#ffffde\"  > Date </td>\r\n        <td class=\'Elective\'>C</td><td class=\'Elective\'>S</td><td class=\'Elective\'>G</td><td class=\'Elective\'>EU</td><td class=\'Elective\'>ER</td><td class=\'Elective\'>Sum</td>\r\n        <td class=\'Emergency\'>C</td><td class=\'Emergency\'>S</td><td class=\'Emergency\'>G</td><td class=\'Emergency\'>EU</td><td class=\'Emergency\'>ER</td><td class=\'Emergency\'>Sum</td>\r\n        <td class=\'Extratime\'>C</td><td class=\'Extratime\'>S</td><td class=\'Extratime\'>G</td><td class=\'Extratime\'>EU</td><td class=\'Extratime\'>ER</td><td class=\'Extratime\'>Sum</td>\r\n        <td class=\'total\'>C</td><td class=\'total\'>S</td><td class=\'total\'>G</td><td class=\'total\'>EU</td><td class=\'total\'>ER</td><td class=\'total\'>Sum</td>\r\n    </tr>\r\n</table>\r\n\r\n\r\n<table border=\"1\" class=\"content\">\r\n<%\r\n   m = nil\r\n   \r\n   \r\n       tsum = {\'Elective\'=>[0,0,0,0],\'Extratime\'=>[0,0,0,0], \'Emergency\'=>[0,0,0,0], \'Total\'=>[0,0,0,0]}\r\n%>\r\n\r\n<%\r\n     pc_map = {}\r\n     pg_map = {}\r\n     \r\n     days = stop_date.day\r\n     \r\n    dates.each_pair do |k,v|\r\n        if v[\'p_colo\']    \r\n         v[\'p_colo\'].each_pair do |p,count|\r\n            pc_map[p] = 0 unless pc_map[p]\r\n            pc_map[p] += count\r\n         end\r\n        end\r\n        \r\n        if v[\'p_gastro\'] \r\n         v[\'p_gastro\'].each_pair do |p,count|\r\n            pg_map[p] = 0 unless pg_map[p]\r\n            pg_map[p] += count\r\n         end\r\n        end\r\n     \r\n    end\r\n     \r\n     \r\n\r\n%>\r\n\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td >&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n    <td colspan=\"<%=pc_map.keys.size%>\" align=\"center\" class=\"total tx\">Colonoscopy Procedure</td>\r\n    <td colspan=\"<%=pg_map.keys.size%>\" align=\"center\" class=\"total tx\">Gastroscopy Procedure</td>\r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"  class=\"page-break\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n</tr>\r\n\r\n<%\r\n\r\n  \r\n\r\n        count = 0 \r\n   \r\n   days.times do |date|\r\n  \r\n   date = (start_date+(date*3600*24))\r\n   i = date.strftime(\"%Y-%m-%d\")\r\n   \r\n#   for i in dates.keys.sort\r\n    weekend = \'\'\r\n    weekend = \'weekend\' if date.wday==0 or date.wday==6\r\n\r\n    \r\n    \r\n    if dates[i]\r\n\r\n%>\r\n\r\n\r\n<tr class=\"page-break\">\r\n    <td class=\"date <%=weekend%>\" ><%=i.split(\'-\').reverse.join(\'-\')%> </td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Emergency Extratime} \r\n        \r\n        k = [0,0,0]\r\n        k = dates[i][j] if dates[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        \r\n        tsum[j][0] += k[0]\r\n        tsum[j][1] += k[1]\r\n        tsum[j][2] += k[2]\r\n        tsum[j][3] += s\r\n        \r\n        \r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        s = \'.\' if s == 0 \r\n        \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n    \r\n    \r\n    \r\n    <% for pi in pc_map.keys.sort \r\n  \r\n    c = dates[i][\'p_colo\'][pi] if dates[i][\'p_colo\']\r\n    c = \'-\' unless c\r\n    %>\r\n    <td class=\"total\"><%= c %></td>\r\n    <% end %>\r\n    \r\n    <% for pi in pg_map.keys.sort \r\n        g = dates[i][\'p_gastro\'][pi] if dates[i][\'p_gastro\']\r\n        g = \'-\' unless g\r\n    \r\n    %>\r\n    <td class=\"total\"><%=g %></td>\r\n    <% end %>\r\n    \r\n    \r\n\r\n</tr> \r\n<% else %>\r\n<tr class=\"page-break\">\r\n    <td class=\"date  <%=weekend%>\"><%=i.split(\'-\').reverse.join(\'-\')%></td>\r\n    <td colspan=\"<%=16+pc_map.keys.size+pg_map.keys.size%>\">\r\n        &nbsp;\r\n        \r\n    </td>\r\n</tr>\r\n<% end %>\r\n<% if count%40==0 and count!=0%>\r\n\r\n</table>\r\n<table border=\"1\" class=\"content force-break\">\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td style=\"width:120px\">&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n    <td colspan=\"<%=pc_map.keys.size%>\" align=\"center\" class=\"total tx\">Colonoscopy Procedure</td>\r\n    <td colspan=\"<%=pg_map.keys.size%>\" align=\"center\" class=\"total tx\">Gastroscopy Procedure</td>\r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"  class=\"page-break\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% \r\ncount+=1\r\n\r\nend %>\r\n\r\n<tr class=\"page-break\"><td>Total</td>\r\n<%\r\n\r\n   t = [0,0,0,0]\r\n\r\n  for j in %w{Elective Extratime Emergency} \r\n    \r\n  4.times do |i|    \r\n  t[i]+=tsum[j][i]\r\n%>\r\n<td class=\"total2\"><%=tsum[j][i]%></td>\r\n<% end %> \r\n<% end %> \r\n\r\n<td class=\"total2\"><%=t[0]%></td><td class=\"total2\"><%=t[1]%></td><td class=\"total2\"><%=t[2]%></td><td class=\"total2\"><%=t[3]%></td>\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total2\"><%=pc_map[pi] %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total2\"><%=pg_map[pi] %></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n<br/>\r\n<h4>รวมจำนวนผู้เข้ารับบริการ</h4>\r\n<br/><table>\r\n    <tr>\r\n        <td colspan=\"2\"></td><td>Elective</td><td>Emergency</td><td>Extratime</td>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">Colonoscopy</td><td  align=\"right\"><%= t[0] %> ราย</td>\r\n        \r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]%> </td>\r\n        <%  end %>\r\n        \r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">Gastroscopy</td><td  align=\"right\"><%= t[1] %> ราย </td>\r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][1]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">Gastroscopy & Colonoscopy</td><td  align=\"right\"><%= t[2] %> ราย </td>\r\n           <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">รวม</td><td  align=\"right\"><%= t[0]+t[1]+t[2] %> ราย </td>\r\n          <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]+tsum[j][1]+tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    \r\n</table>\r\n\r\n</div>\r\n<br/>\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-11-15 03:18:17','2016-11-15 03:18:17','weekly_report',''),(2722,'case_report',1098,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Monthly Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\#{@current_project.name}#appointment\"\r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    params_date = select_date\r\n    select_date = Date.to_mongo(select_date)\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nSelect : <%= f.date_select :date, :default=>select_date ,:discard_day=>true , :order=>[:month,:year]%>\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n    ipds = 0 \r\n    opds = 0 \r\n    \r\n    total_patho = 0\r\n \r\n \r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    select_date = Date.to_mongo(select_date)\r\n    start_date = select_date.beginning_of_month()\r\n    stop_date = select_date.end_of_month()\r\n    \r\n    \r\n\r\n    pname = \"\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    other_status = {\'Cancelled\'=>0,\'Postpone\'=>0}\r\n    ipd_opd = {}\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n         # all pm colono of those appointments\r\n    all_pm_prescope = @m_patient_module.collection.find({:module_name=>\"\\#{pname}pre_scope\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_prescope = bmap all_pm_prescope, \'parent_id\'\r\n    \r\n    \r\n    colo_scope = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n    cs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n    for i in colo_scope\r\n        cs[i] = 1\r\n    end\r\n\r\n    gastro_scope = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n    gs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n       \r\n    for i in gastro_scope\r\n        gs[i] = 1\r\n    end     \r\n    \r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>cs}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>gs}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n \r\n    prescope = @models[:pre_scope].collection.find({:_id=>{\'$in\'=>all_pm_prescope.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'type_of_patient\'=>1 }}).to_a\r\n    m_prescope = bmap prescope, \'_id\'\r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    for app in all_app\r\n    \r\n        other_status[app[\'status\']] = 0 unless other_status[app[\'status\']]\r\n        other_status[app[\'status\']] += 1 \r\n        \r\n        \r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                prescope = m_all_pm_prescope[pm_app[\'_id\']]\r\n                \r\n                \r\n                p_colo = nil\r\n                p_gastro = nil\r\n                \r\n                r_colo = nil\r\n                r_gastro = nil\r\n                \r\n                \r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                        status = r_colo[0][\'status\']\r\n                        p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    if r_gastro\r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                 \r\n                patho_count = 0 \r\n                \r\n                \r\n                \r\n                if r_colo and r_colo[0]\r\n                    \r\n                    xls = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n                    xms = \'colonoscopy_scope\'\r\n                    xdata = r_colo[0]\r\n            \r\n                xls.each{|lc|\r\n                \r\n                    if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n             \r\n                        xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                        for li in xll\r\n                            patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                   \r\n                        end\r\n                    \r\n                    end\r\n                }\r\n                \r\n                end\r\n                \r\n                \r\n                if r_gastro and r_gastro[0]\r\n                    \r\n                    xls = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n                    xms = \'gastroscopy_scope\'\r\n                    xdata = r_gastro[0]\r\n                \r\n                xls.each{|lc| \r\n                    if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n                        xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                        for li in xll\r\n                            patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                        end\r\n                    \r\n                    end\r\n                }\r\n                \r\n                end\r\n                \r\n                \r\n                total_patho += patho_count\r\n        \r\n                \r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n            \r\n                dates[date][\'no_specimen\'] = 0 unless dates[date][\'no_specimen\']\r\n                dates[date][\'no_specimen\'] += patho_count\r\n            \r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                \r\n                \r\n                \r\n                \r\n                if prescope and prescope = prescope[0]  and prescope and colo or gastro\r\n                    \r\n                if prescope and  prescope[\'module_id\'] and m_prescope[prescope[\'module_id\']]\r\n                    \r\n                    \r\n                    \r\n                r_prescope = m_prescope[prescope[\'module_id\']][0]    \r\n                    \r\n                dates[date][\'ipd_opd\'] = {\'IPD\'=>0,\'OPD\'=>0, \'\'=>0, nil=>0} unless dates[date][\'ipd_opd\']\r\n                dates[date][\'ipd_opd\'][r_prescope[\'type_of_patient\']]+=1\r\n                \r\n                end\r\n                \r\n                end\r\n              \r\n              \r\n              \r\n                \r\n                if p_colo\r\n                dates[date][\'p_colo\'] = {} unless dates[date][\'p_colo\']\r\n                for pi in p_colo.split(\"|\")\r\n                    dates[date][\'p_colo\'][pi] = 0 unless  dates[date][\'p_colo\'][pi]\r\n                    dates[date][\'p_colo\'][pi] += 1 \r\n                end\r\n                \r\n                end\r\n                \r\n                \r\n                \r\n                if p_gastro\r\n                \r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                for pi in p_gastro.split(\"|\")\r\n                dates[date][\'p_gastro\'][pi] = 0 unless  dates[date][\'p_gastro\'][pi]\r\n                dates[date][\'p_gastro\'][pi] += 1 \r\n                end\r\n                end\r\n                \r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        end\r\n    \r\n    end\r\n    \r\n    %>\r\n    <%#dates.inspect  %>\r\n    <%\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<% \r\n\r\n    month_text = month_th[select_date.month-1]+select_date.strftime(\"-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    \r\n    td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.small{\r\n        font-size:0.8em;\r\n    }\r\n    td.date{\r\n        padding:0px;\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n        td.date{\r\n        padding:0px;\r\n        \r\n        width:125px;\r\n        \r\n    }\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n    \r\n    tr.page-break{page-break-after:always;page-break-inside:avoid; page-break-after:auto}\r\n    .force-break{ display: block;page-break-before:always;}\r\n        \r\n    }\r\n    \r\n\r\n    \r\n   table { page-break-inside:auto }\r\n   tr    { page-break-inside:avoid; page-break-after:auto }\r\n    \r\n</style>\r\n<style type=\"text/css\">\r\n\r\n</style>\r\n\r\n\r\n\r\n<div style=\"width:720px\">\r\n<center><h3>\r\nรายงานจำนวนผู้เข้ารับบริการ \r\n<%=@current_project.get_setting \'report_title_1\' %>\r\n<br/>\r\n<%=@current_project.get_setting \'report_title_2\' %></h3>\r\n<br/>\r\n<h4>ประจำเดือน\r\n    <%=month_text%>\r\n</h4></center>\r\n\r\n</div>\r\n\r\n<br/>\r\n<table border=\"1\" class=\"content\">\r\n<%\r\n   m = nil\r\n   \r\n   \r\n       tsum = {\'Elective\'=>[0,0,0,0],\'Extratime\'=>[0,0,0,0], \'Emergency\'=>[0,0,0,0], \'Total\'=>[0,0,0,0]}\r\n%>\r\n\r\n<%\r\n     pc_map = {}\r\n     pg_map = {}\r\n     \r\n     days = stop_date.day\r\n     \r\n    dates.each_pair do |k,v|\r\n        if v[\'p_colo\']    \r\n         v[\'p_colo\'].each_pair do |p,count|\r\n            pc_map[p] = 0 unless pc_map[p]\r\n            pc_map[p] += count\r\n         end\r\n        end\r\n        \r\n        if v[\'p_gastro\'] \r\n         v[\'p_gastro\'].each_pair do |p,count|\r\n            pg_map[p] = 0 unless pg_map[p]\r\n            pg_map[p] += count\r\n         end\r\n        end\r\n     \r\n    end\r\n     \r\n     \r\n\r\n%>\r\n\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td >&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n    <td colspan=\"3\" align=\"center\" class=\"  Elective\">Summary</td>\r\n    \r\n    <td colspan=\"<%=pc_map.keys.size%>\" align=\"center\" class=\"total tx\">Colonoscopy Procedure</td>\r\n    <td colspan=\"<%=pg_map.keys.size%>\" align=\"center\" class=\"total tx\">Gastroscopy Procedure</td>\r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"  class=\"page-break\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n    <td class=\"Elective\">IPD</td><td class=\"Elective\">OPD</td>\r\n    <td class=\"Elective\">#Patho</td>\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n</tr>\r\n\r\n<%\r\n\r\n  \r\n\r\n        count = 0 \r\n   \r\n   days.times do |date|\r\n  \r\n   date = (start_date+(date*3600*24))\r\n   i = date.strftime(\"%Y-%m-%d\")\r\n   \r\n#   for i in dates.keys.sort\r\n    weekend = \'\'\r\n    weekend = \'weekend\' if date.wday==0 or date.wday==6\r\n\r\n    \r\n    \r\n    if dates[i]\r\n\r\n%>\r\n\r\n\r\n<tr class=\"page-break\">\r\n    <td class=\"date <%=weekend%>\"  ><%=i.split(\'-\').reverse.join(\'-\')%> </td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Emergency Extratime} \r\n        \r\n        k = [0,0,0]\r\n        k = dates[i][j] if dates[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        \r\n        tsum[j][0] += k[0]\r\n        tsum[j][1] += k[1]\r\n        tsum[j][2] += k[2]\r\n        tsum[j][3] += s\r\n        \r\n        \r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        s = \'.\' if s == 0 \r\n        \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n    <%\r\n   \r\n     for j in %w{IPD OPD} \r\n     \r\n        if j == \'IPD\'\r\n           ipds+= dates[i][\'ipd_opd\'][j] if dates[i][\'ipd_opd\'] \r\n        else\r\n           opds += dates[i][\'ipd_opd\'][j] if dates[i][\'ipd_opd\'] \r\n        end\r\n        \r\n    %>\r\n    <td class=\"Elective\">\r\n        <%=dates[i][\'ipd_opd\'][j] if dates[i][\'ipd_opd\'] %>\r\n    </td>\r\n    <% end %>\r\n   <td class=\"Elective\"><%=dates[i][\'no_specimen\']%></td>\r\n    <% for pi in pc_map.keys.sort \r\n  \r\n    c = dates[i][\'p_colo\'][pi] if dates[i][\'p_colo\']\r\n    c = \'-\' unless c\r\n    %>\r\n    <td class=\"total\"><%= c %></td>\r\n    <% end %>\r\n    \r\n    <% for pi in pg_map.keys.sort \r\n        g = dates[i][\'p_gastro\'][pi] if dates[i][\'p_gastro\']\r\n        g = \'-\' unless g\r\n    \r\n    %>\r\n    <td class=\"total\"><%=g %></td>\r\n    <% end %>\r\n    \r\n    \r\n\r\n</tr> \r\n<% else %>\r\n<tr class=\"page-break\">\r\n    <td class=\"date  <%=weekend%>\"><%=i.split(\'-\').reverse.join(\'-\')%></td>\r\n    <td colspan=\"<%=19+pc_map.keys.size+pg_map.keys.size%>\">\r\n        &nbsp;\r\n        \r\n    </td>\r\n</tr>\r\n<% end %>\r\n<% if count%25==0 and count!=0%>\r\n\r\n</table>\r\n<table border=\"1\" class=\"content force-break\">\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td style=\"width:120px\">&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n        <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n\r\n\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n        <td colspan=\"3\" align=\"center\" class=\"  Elective\">Summary</td>\r\n\r\n\r\n    <td colspan=\"<%=pc_map.keys.size%>\" align=\"center\" class=\"total tx\">Colonoscopy Procedure</td>\r\n    <td colspan=\"<%=pg_map.keys.size%>\" align=\"center\" class=\"total tx\">Gastroscopy Procedure</td>\r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"  class=\"page-break\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n    <td class=\"Elective\">IPD</td><td class=\"Elective\">OPD</td>\r\n    <td class=\"Elective\">#Patho</td>\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total  small\"><%=pi %></td>\r\n    <% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% \r\ncount+=1\r\n\r\nend %>\r\n\r\n<tr class=\"page-break\"><td>Total</td>\r\n<%\r\n\r\n   t = [0,0,0,0]\r\n\r\n  for j in %w{Elective  Emergency Extratime} \r\n    \r\n  4.times do |i|    \r\n  t[i]+=tsum[j][i]\r\n%>\r\n<td class=\"total2\"><%=tsum[j][i]%></td>\r\n<% end %> \r\n<% end %> \r\n\r\n<td class=\"total2\"><%=t[0]%></td><td class=\"total2\"><%=t[1]%></td><td class=\"total2\"><%=t[2]%></td><td class=\"total2\"><%=t[3]%></td>\r\n\r\n    <td class=\"total2\"><%=ipds%></td>\r\n    <td class=\"total2\"><%=opds%></td>\r\n\r\n    <td class=\"total2\"><%=total_patho%></td>\r\n\r\n    <% for pi in pc_map.keys.sort %>\r\n    <td class=\"total2\"><%=pc_map[pi] %></td>\r\n    <% end %>\r\n    <% for pi in pg_map.keys.sort %>\r\n    <td  class=\"total2\"><%=pg_map[pi] %></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n<br/>\r\n<h4><u>รวมจำนวนผู้เข้ารับบริการ</u></h4>\r\n<br/><table>\r\n    <tr>\r\n        <td colspan=\"2\"></td><td>Elective</td><td>Emergency</td><td>Extratime</td>\r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Colonoscopy</th><td  align=\"right\"><%= t[0] %> ราย</td>\r\n        \r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]%> </td>\r\n        <%  end %>\r\n        \r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Gastroscopy</th><td  align=\"right\"><%= t[1] %> ราย </td>\r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][1]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Gastroscopy & Colonoscopy</th><td  align=\"right\"><%= t[2] %> ราย </td>\r\n           <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">รวม</td><td  align=\"right\"><%= t[0]+t[1]+t[2] %> ราย </td>\r\n          <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]+tsum[j][1]+tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    \r\n</table>\r\n<hr/>\r\n<h4><u>รวมจำนวนผู้ป่วยยกเลิกหรือเลื่อนนัด</u></h4>\r\n<br/>\r\n<table>\r\n    <tr>\r\n        <th>Cancelled</th> <td style=\"width:100px\" align=\"center\"><%=other_status[\'Cancelled\'] %></td>\r\n    </tr>\r\n    <tr>\r\n        <th>Postpone</th><td style=\"width:100px\" align=\"center\"><%=other_status[\'Postpone\']%></td> \r\n    </tr>\r\n    \r\n</table>\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-11-15 03:37:12','2016-11-15 03:37:12','case_report',''),(2723,'yearly_report',1098,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Yearly Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\#{@current_project.name}#appointment\"\r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    params_date = select_date\r\n    select_date = Date.to_mongo(select_date)\r\n    type = \'0\'\r\n    type = params[:report][:type] if params and params[:report]\r\n\r\n    header_th = %w{ในเวลาราชการ ER นอกเวลาราชการ ทุกประเภท}\r\n   \r\n%>\r\n\r\n\r\n<%=form_for \'report\' do |f| %>\r\nSelect : <%= f.date_select :date, :default=>select_date ,:discard_day=>true ,:discard_month=>true,:start_year => Time.now.year-5,:end_year => Time.now.year, :order=>[:month,:year]%>\r\n<br/>\r\nCase : <%=f.select :type,  options_for_select([[\'Elective\',0],[\'Emergency\',1],[\'Extratime\',2],[\'All\',3]],type) %>\r\n<br/>\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n    ipds = 0 \r\n    opds = 0 \r\n    \r\n    total_patho = 0\r\n \r\n \r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-6-15\" if params[:report]\r\n    select_date = Date.to_mongo(select_date)\r\n    \r\n      \r\n      \r\n      \r\n    \r\n    start_date = Date.to_mongo((params[:report][\'date(1i)\'].to_i-3).to_s+\"-6-15\").beginning_of_year()\r\n    stop_date = select_date.end_of_year()\r\n    \r\n    \r\n    \r\n    \r\n\r\n    pname = \"\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n    other_status = {\'Cancelled\'=>0,\'Postpone\'=>0}\r\n    ipd_opd = {}\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n         # all pm colono of those appointments\r\n    all_pm_prescope = @m_patient_module.collection.find({:module_name=>\"\\#{pname}pre_scope\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_prescope = bmap all_pm_prescope, \'parent_id\'\r\n    \r\n    \r\n    colo_scope = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n    cs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n    for i in colo_scope\r\n        cs[i] = 1\r\n    end\r\n\r\n    gastro_scope = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n    gs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n       \r\n    for i in gastro_scope\r\n        gs[i] = 1\r\n    end     \r\n    \r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>cs}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>gs}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n \r\n    prescope = @models[:pre_scope].collection.find({:_id=>{\'$in\'=>all_pm_prescope.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'type_of_patient\'=>1 }}).to_a\r\n    m_prescope = bmap prescope, \'_id\'\r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n \r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    for app in all_app\r\n    \r\n        other_status[app[\'status\']] = 0 unless other_status[app[\'status\']]\r\n        other_status[app[\'status\']] += 1 \r\n        \r\n        \r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                prescope = m_all_pm_prescope[pm_app[\'_id\']]\r\n                \r\n                \r\n                p_colo = nil\r\n                p_gastro = nil\r\n                \r\n                r_colo = nil\r\n                r_gastro = nil\r\n                \r\n                \r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                        status = r_colo[0][\'status\']\r\n                        p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    if r_gastro\r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                 \r\n                patho_count = 0 \r\n                \r\n                \r\n                \r\n                # if r_colo and r_colo[0]\r\n                    \r\n                #     xls = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n                #     xms = \'colonoscopy_scope\'\r\n                #     xdata = r_colo[0]\r\n            \r\n                # xls.each{|lc|\r\n                \r\n                #     if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n             \r\n                #         xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                #         for li in xll\r\n                #             patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                   \r\n                #         end\r\n                    \r\n                #     end\r\n                # }\r\n                \r\n                # end\r\n                \r\n                \r\n                # if r_gastro and r_gastro[0]\r\n                    \r\n                #     xls = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n                #     xms = \'gastroscopy_scope\'\r\n                #     xdata = r_gastro[0]\r\n                \r\n                # xls.each{|lc| \r\n                #     if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n                #         xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                #         for li in xll\r\n                #             patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                #         end\r\n                    \r\n                #     end\r\n                # }\r\n                \r\n                # end\r\n                \r\n                \r\n                # total_patho += patho_count\r\n        \r\n                \r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n            \r\n                dates[date][\'no_specimen\'] = 0 unless dates[date][\'no_specimen\']\r\n                dates[date][\'no_specimen\'] += patho_count\r\n            \r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                \r\n                \r\n                \r\n                \r\n                if prescope and prescope = prescope[0]  and prescope and colo or gastro\r\n                    \r\n                if prescope and  prescope[\'module_id\'] and m_prescope[prescope[\'module_id\']]\r\n                    \r\n                    \r\n                    \r\n                r_prescope = m_prescope[prescope[\'module_id\']][0]    \r\n                    \r\n                dates[date][\'ipd_opd\'] = {\'IPD\'=>0,\'OPD\'=>0, \'\'=>0, nil=>0} unless dates[date][\'ipd_opd\']\r\n                dates[date][\'ipd_opd\'][r_prescope[\'type_of_patient\']]+=1\r\n                \r\n                end\r\n                \r\n                end\r\n              \r\n              \r\n              \r\n                \r\n                if p_colo\r\n                dates[date][\'p_colo\'] = {} unless dates[date][\'p_colo\']\r\n                for pi in p_colo.split(\"|\")\r\n                    dates[date][\'p_colo\'][pi] = 0 unless  dates[date][\'p_colo\'][pi]\r\n                    dates[date][\'p_colo\'][pi] += 1 \r\n                end\r\n                \r\n                end\r\n                \r\n                \r\n                \r\n                if p_gastro\r\n                \r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                for pi in p_gastro.split(\"|\")\r\n                dates[date][\'p_gastro\'][pi] = 0 unless  dates[date][\'p_gastro\'][pi]\r\n                dates[date][\'p_gastro\'][pi] += 1 \r\n                end\r\n                end\r\n                \r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n       \r\n        end\r\n    \r\n    end\r\n%>\r\n<%# dates.inspect %>\r\n<%\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<% \r\n\r\n    month_text = month_th[select_date.month-1]+select_date.strftime(\"-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    .date{\r\n        padding:5px;\r\n    }\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    \r\n    td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.small{\r\n        font-size:0.8em;\r\n    }\r\n    td.date{\r\n        padding:0px;\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n        td.date{\r\n        padding:0px;\r\n        \r\n        width:125px;\r\n        \r\n    }\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n    \r\n    tr.page-break{page-break-after:always;page-break-inside:avoid; page-break-after:auto}\r\n    .force-break{ display: block;page-break-before:always;}\r\n        \r\n    }\r\n    \r\n   .m3{\r\n       background-color:#cae3ff;\r\n          text-align:center;\r\n   }\r\n   .m2{\r\n       background-color:#d8ffec;\r\n         text-align:center;\r\n   }\r\n   .m1{\r\n       background-color:#f7ffc6;\r\n         text-align:center;\r\n   }\r\n   .m0{\r\n       background-color:#dfddfe;\r\n         text-align:center;\r\n   }\r\n   .percent{\r\n         text-align:right;\r\n   }\r\n   \r\n    \r\n   table { page-break-inside:auto }\r\n   tr    { page-break-inside:avoid; page-break-after:auto }\r\n    \r\n</style>\r\n<style type=\"text/css\">\r\n\r\n</style>\r\n\r\n\r\n\r\n<div style=\"width:720px\">\r\n<center><h3>\r\nรายงานจำนวนผู้เข้ารับบริการ \r\n<%=@current_project.get_setting \'report_title_1\' %>\r\n<br/>\r\n<%=@current_project.get_setting \'report_title_2\' %></h3>\r\n<br/>\r\n<h4>ประจำปี\r\n    <%=stop_date.year%>\r\n</h4></center>\r\n<h3>ตารางแสดงจำนวนผู้ป่วย ห้องส่องกล้อง Surgical Endoscopy ประจำปี \r\n<%=stop_date.year%> <br/> เปรียบเทียบ\r\n    \r\n    <%= header_th[ type.to_i ] %>\r\n</h3>\r\n</div>\r\n\r\n<br/>\r\n\r\n\r\n\r\n<% ytime = 4%>\r\n<%\r\n    msum = {}\r\n    psum = {}\r\n    last = nil\r\n%>\r\n\r\n<table border=\"1\" class=\"content\">\r\n<tr>\r\n    <th  class=\"m0\">Month</th>\r\n    <% ytime.times do |y|\r\n        yy = (select_date.year+y-ytime+1)\r\n        if y!=0\r\n    %>\r\n    \r\n    <th colspan=\"5\" class=\"m<%=(y)%>\">\r\n    <%= yy %>    \r\n    </th>\r\n    \r\n    <% end %>\r\n    <% end %>\r\n    \r\n</tr>\r\n\r\n\r\n<tr>\r\n    <th  class=\"m0\">&nbsp;</th>\r\n    \r\n    <% ytime.times do |y|\r\n        yy = (select_date.year+y-ytime+1)\r\n        \r\n        if y != 0 \r\n    %>\r\n    \r\n    <th class=\"m<%=(y)%>\">Gastro</th>\r\n    \r\n    <th class=\"m<%=(y)%>\">Colono</th>\r\n    \r\n    <th class=\"m<%=(y)%>\">G+C</th>\r\n    \r\n    <th class=\"m<%=(y)%>\">รวม</th>\r\n    \r\n    <th class=\"m<%=(y)%>\">Growth</th>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    \r\n    \r\n</tr>\r\n\r\n\r\n\r\n    <% 12.times do |m| %>\r\n    <tr align=\"center\">\r\n    <th class=\"m0\"><%=month_th[m]%></th>\r\n      <% ytime.times do |y| \r\n        yy = (select_date.year+y-ytime+1)\r\n      \r\n      \r\n      \r\n      \r\n      \r\n      \r\n      \r\n      \r\n        d = \"%d\"%yy+\"-\"+\"%02d\"%(m+1)\r\n        dx = [0,0,0]\r\n        \r\n        case params[:report][:type]\r\n        \r\n        when \'0\'\r\n        dx = dates[d][\"Elective\"] if dates[d]\r\n        when \'1\'\r\n        dx = dates[d][\"Emergency\"] if dates[d]\r\n        when \'2\'\r\n        dx = dates[d][\"Extratime\"] if dates[d]\r\n        when \'3\'\r\n        \r\n        dx1 = dates[d][\"Elective\"] if dates[d]\r\n        dx2 = dates[d][\"Extratime\"] if dates[d]\r\n        dx3 = dates[d][\"Emergency\"] if dates[d]\r\n        dx1= [0,0,0] unless dx1\r\n        dx2= [0,0,0] unless dx2\r\n        dx3= [0,0,0] unless dx3\r\n        \r\n        \r\n        dx = [dx1[0]+dx2[0]+dx3[0],dx1[1]+dx2[1]+dx3[1],dx1[2]+dx2[2]+dx3[2]] \r\n        end\r\n        tx = 0\r\n        \r\n        \r\n        dx = [0,0,0] unless dx\r\n        \r\n        \r\n        tx = dx[0]+dx[1]+dx[2] if dx\r\n        \r\n        \r\n        msum[m] = 0 unless msum[m]\r\n        \r\n        \r\n        percent = \'-\'\r\n        if msum[m] > 0 \r\n            percent = \"\\#{\'%.2f\'%((tx.to_f-msum[m])/msum[m]*100)}%\"\r\n        end\r\n        \r\n    \r\n        \r\n        psum[yy]=[0,0,0] unless psum[yy]\r\n        \r\n        if dx\r\n        \r\n        psum[yy][0]+= dx[0] \r\n        psum[yy][1]+= dx[1]\r\n        psum[yy][2]+= dx[2]\r\n        \r\n        end\r\n         \r\n         \r\n         \r\n         \r\n         \r\n         \r\n      if y!=0     \r\n        \r\n      %>\r\n      <td class=\"\"><%=dx[1]%></td>\r\n      <td class=\"\"><%=dx[0]%></td>\r\n      <td class=\"\"><%=dx[2]%></td>\r\n      <td class=\"m<%=(y)%>\"><%=tx%></td>\r\n      <td class=\"m<%=(y)%> percent\"><%=percent%></td>\r\n      <%\r\n      \r\n     end\r\n      \r\n      msum[m] = tx\r\n        \r\n      end %>\r\n    </tr>\r\n    <% end %>\r\n    <%# psum.inspect %>\r\n  \r\n  \r\n  <tr>\r\n      <th  class=\"m0\">รวม</th>\r\n      \r\n      <% ytime.times do |y| \r\n        yy = (select_date.year+y-ytime+1)\r\n      \r\n        dx = []  \r\n        \r\n        \r\n        \r\n        \r\n        tx=  0\r\n        \r\n        \r\n        tx = psum[yy][0]+psum[yy][1]+psum[yy][2] \r\n        \r\n         percent = \'-\'\r\n        if last  \r\n            percent = \"\\#{\'%.2f\'%((tx.to_f-last)/last*100)} %\"\r\n        end\r\n        last = tx\r\n        if y!=0\r\n    %>\r\n    <td  class=\"m0\"><%=psum[yy][1]%><%#psum[yy].inspect%></td>\r\n    <td  class=\"m0\"><%=psum[yy][0]%></td>\r\n    <td  class=\"m0\"><%=psum[yy][2]%></td>\r\n    <td  class=\"m0\"><%=tx%></td>\r\n    <td  class=\"m0 percent\"><%=percent%></td>\r\n     \r\n    <% end %>\r\n    <% end %>\r\n  \r\n  </tr>\r\n  \r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-11-15 03:58:47','2016-11-15 03:58:47','yearly_report',''),(2724,'annual_report',1098,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Annual Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\#{@current_project.name}#appointment\"\r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    params_date = select_date\r\n    select_date = Date.to_mongo(select_date)\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nSelect : <%= f.date_select :date, :default=>select_date ,:discard_day=>true ,:discard_month=>true,:start_year => Time.now.year-5,:end_year => Time.now.year, :order=>[:month,:year]%>\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n    ipds = 0 \r\n    opds = 0 \r\n    \r\n    total_patho = 0\r\n \r\n \r\n    select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    select_date = params[:report][\'date(1i)\']+\"-6-15\" if params[:report]\r\n    select_date = Date.to_mongo(select_date)\r\n    start_date = select_date.beginning_of_year()\r\n    stop_date = select_date.end_of_year()\r\n    \r\n    \r\n\r\n    pname = \"\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    other_status = {\'Cancelled\'=>0,\'Postpone\'=>0}\r\n    ipd_opd = {}\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n         # all pm colono of those appointments\r\n    all_pm_prescope = @m_patient_module.collection.find({:module_name=>\"\\#{pname}pre_scope\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_prescope = bmap all_pm_prescope, \'parent_id\'\r\n    \r\n    \r\n    colo_scope = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n    cs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n    for i in colo_scope\r\n        cs[i] = 1\r\n    end\r\n\r\n    gastro_scope = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n    gs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }\r\n    \r\n       \r\n    for i in gastro_scope\r\n        gs[i] = 1\r\n    end     \r\n    \r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>cs}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>gs}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n \r\n    prescope = @models[:pre_scope].collection.find({:_id=>{\'$in\'=>all_pm_prescope.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'type_of_patient\'=>1 }}).to_a\r\n    m_prescope = bmap prescope, \'_id\'\r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    for app in all_app\r\n    \r\n        other_status[app[\'status\']] = 0 unless other_status[app[\'status\']]\r\n        other_status[app[\'status\']] += 1 \r\n        \r\n        \r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                prescope = m_all_pm_prescope[pm_app[\'_id\']]\r\n                \r\n                \r\n                p_colo = nil\r\n                p_gastro = nil\r\n                \r\n                r_colo = nil\r\n                r_gastro = nil\r\n                \r\n                \r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                        status = r_colo[0][\'status\']\r\n                        p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    if r_gastro\r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                 \r\n                patho_count = 0 \r\n                \r\n                \r\n                \r\n                # if r_colo and r_colo[0]\r\n                    \r\n                #     xls = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n                #     xms = \'colonoscopy_scope\'\r\n                #     xdata = r_colo[0]\r\n            \r\n                # xls.each{|lc|\r\n                \r\n                #     if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n             \r\n                #         xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                #         for li in xll\r\n                #             patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                   \r\n                #         end\r\n                    \r\n                #     end\r\n                # }\r\n                \r\n                # end\r\n                \r\n                \r\n                # if r_gastro and r_gastro[0]\r\n                    \r\n                #     xls = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n                #     xms = \'gastroscopy_scope\'\r\n                #     xdata = r_gastro[0]\r\n                \r\n                # xls.each{|lc| \r\n                #     if xdata[lc] and !xdata[lc].empty?\r\n                        \r\n                #         xll = models[xms.to_sym].find(xdata[lc])\r\n              \r\n                #         for li in xll\r\n                #             patho_count+=1 if li.patho_number!=\'\' and li.patho_number!=\'Loss\'\r\n                #         end\r\n                    \r\n                #     end\r\n                # }\r\n                \r\n                # end\r\n                \r\n                \r\n                # total_patho += patho_count\r\n        \r\n                \r\n                \r\n                \r\n                \r\n                dates[date] = {} unless dates[date]\r\n            \r\n                dates[date][\'no_specimen\'] = 0 unless dates[date][\'no_specimen\']\r\n                dates[date][\'no_specimen\'] += patho_count\r\n            \r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                \r\n                \r\n                \r\n                \r\n                if prescope and prescope = prescope[0]  and prescope and colo or gastro\r\n                    \r\n                if prescope and  prescope[\'module_id\'] and m_prescope[prescope[\'module_id\']]\r\n                    \r\n                    \r\n                    \r\n                r_prescope = m_prescope[prescope[\'module_id\']][0]    \r\n                    \r\n                dates[date][\'ipd_opd\'] = {\'IPD\'=>0,\'OPD\'=>0, \'\'=>0, nil=>0} unless dates[date][\'ipd_opd\']\r\n                dates[date][\'ipd_opd\'][r_prescope[\'type_of_patient\']]+=1\r\n                \r\n                end\r\n                \r\n                end\r\n              \r\n              \r\n              \r\n                \r\n                if p_colo\r\n                dates[date][\'p_colo\'] = {} unless dates[date][\'p_colo\']\r\n                for pi in p_colo.split(\"|\")\r\n                    dates[date][\'p_colo\'][pi] = 0 unless  dates[date][\'p_colo\'][pi]\r\n                    dates[date][\'p_colo\'][pi] += 1 \r\n                end\r\n                \r\n                end\r\n                \r\n                \r\n                \r\n                if p_gastro\r\n                \r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                for pi in p_gastro.split(\"|\")\r\n                dates[date][\'p_gastro\'][pi] = 0 unless  dates[date][\'p_gastro\'][pi]\r\n                dates[date][\'p_gastro\'][pi] += 1 \r\n                end\r\n                end\r\n                \r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        end\r\n    \r\n    end\r\n\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<% \r\n\r\n    month_text = month_th[select_date.month-1]+select_date.strftime(\"-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    .date{\r\n        padding:5px;\r\n    }\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    \r\n    td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.small{\r\n        font-size:0.8em;\r\n    }\r\n    td.date{\r\n        padding:0px;\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n        td.date{\r\n        padding:0px;\r\n        \r\n        width:125px;\r\n        \r\n    }\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n    \r\n    tr.page-break{page-break-after:always;page-break-inside:avoid; page-break-after:auto}\r\n    .force-break{ display: block;page-break-before:always;}\r\n        \r\n    }\r\n    \r\n\r\n    \r\n   table { page-break-inside:auto }\r\n   tr    { page-break-inside:avoid; page-break-after:auto }\r\n    \r\n</style>\r\n<style type=\"text/css\">\r\n\r\n</style>\r\n\r\n\r\n\r\n<div style=\"width:720px\">\r\n<center><h3>\r\nรายงานจำนวนผู้เข้ารับบริการ \r\n<%=@current_project.get_setting \'report_title_1\' %>\r\n<br/>\r\n<%=@current_project.get_setting \'report_title_2\' %></h3>\r\n<br/>\r\n<h4>ประจำปี\r\n    <%=start_date.year%>\r\n</h4></center>\r\n</div>\r\n\r\n<br/>\r\n<table border=\"1\" class=\"content\">\r\n<%\r\n   m = nil\r\n   \r\n   \r\n       tsum = {\'Elective\'=>[0,0,0,0],\'Extratime\'=>[0,0,0,0], \'Emergency\'=>[0,0,0,0], \'Total\'=>[0,0,0,0]}\r\n%>\r\n\r\n<%\r\n     pc_map = {}\r\n     pg_map = {}\r\n     \r\n    days = stop_date.day\r\n     \r\n    dates.each_pair do |k,v|\r\n        if v[\'p_colo\']    \r\n         v[\'p_colo\'].each_pair do |p,count|\r\n            pc_map[p] = 0 unless pc_map[p]\r\n            pc_map[p] += count\r\n         end\r\n        end\r\n        \r\n        if v[\'p_gastro\'] \r\n         v[\'p_gastro\'].each_pair do |p,count|\r\n            pg_map[p] = 0 unless pg_map[p]\r\n            pg_map[p] += count\r\n         end\r\n        end\r\n     \r\n    end\r\n     \r\n     \r\n\r\n%>\r\n\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td >&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >ในเวลา</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">ER</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">นอกเวลา</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">รวม</td>\r\n    \r\n\r\n</tr>\r\n\r\n<tr style=\"\"  class=\"page-break\"><td></td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n   \r\n</tr>\r\n\r\n<%  12.times do |time| \r\n\r\n   \r\n   i = start_date.strftime(\"%Y-\")+\"%02d\"%(time+1)\r\n   \r\n#   for i in dates.keys.sor\r\n    \r\n    if d = dates[i]\r\n\r\n\r\n%>\r\n    \r\n\r\n<tr class=\"page-break\">\r\n    <td class=\"date\"  ><%=month_th[time]%> </td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Emergency Extratime} \r\n        \r\n        k = [0,0,0]\r\n        k = dates[i][j] if dates[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        \r\n        tsum[j][0] += k[0]\r\n        tsum[j][1] += k[1]\r\n        tsum[j][2] += k[2]\r\n        tsum[j][3] += s\r\n        \r\n        \r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        s = \'.\' if s == 0 \r\n        \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n    \r\n    \r\n\r\n</tr> \r\n\r\n<% else %>\r\n<tr class=\"page-break\">\r\n    <td class=\"date  \"><%=month_th[time]%></td>\r\n    <td colspan=\"<%=19%>\">\r\n        &nbsp;\r\n        \r\n    </td>\r\n</tr>\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n<tr class=\"page-break\"><td>Total</td>\r\n<%\r\n\r\n   t = [0,0,0,0]\r\n\r\n  for j in %w{Elective  Emergency Extratime} \r\n    \r\n  4.times do |i|    \r\n  t[i]+=tsum[j][i]\r\n%>\r\n<td class=\"total2\"><%=tsum[j][i]%></td>\r\n<% end %> \r\n<% end %> \r\n\r\n<td class=\"total2\"><%=t[0]%></td><td class=\"total2\"><%=t[1]%></td><td class=\"total2\"><%=t[2]%></td><td class=\"total2\"><%=t[3]%></td>\r\n\r\n   \r\n</tr>\r\n</table>\r\n<br/>\r\n<h4><u>รวมจำนวนผู้เข้ารับบริการ</u></h4>\r\n<br/><table>\r\n    <tr>\r\n        <td colspan=\"2\"></td><td>Elective</td><td>Emergency</td><td>Extratime</td>\r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Colonoscopy</th><td  align=\"right\"><%= t[0] %> ราย</td>\r\n        \r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]%> </td>\r\n        <%  end %>\r\n        \r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Gastroscopy</th><td  align=\"right\"><%= t[1] %> ราย </td>\r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][1]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <th align=\"left\" style=\"width:250px\">Gastroscopy & Colonoscopy</th><td  align=\"right\"><%= t[2] %> ราย </td>\r\n           <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">รวม</td><td  align=\"right\"><%= t[0]+t[1]+t[2] %> ราย </td>\r\n          <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]+tsum[j][1]+tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    \r\n</table>\r\n<hr/>\r\n<h4><u>รวมจำนวนผู้ป่วยยกเลิกหรือเลื่อนนัด</u></h4>\r\n<br/>\r\n<table>\r\n    <tr>\r\n        <th>Cancelled</th> <td style=\"width:100px\" align=\"center\"><%=other_status[\'Cancelled\'] %></td>\r\n    </tr>\r\n    <tr>\r\n        <th>Postpone</th><td style=\"width:100px\" align=\"center\"><%=other_status[\'Postpone\']%></td> \r\n    </tr>\r\n    \r\n</table>\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-11-15 03:59:48','2016-11-15 03:59:48','annual_report',''),(2725,'endoscopist_report',1098,2,'<h1>Endoscopist Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n\r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-25\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-25\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nFrom : <%= f.date_select :from_date, :default=>from_date ,:discard_day=>true , :order=>[:month,:year],:start_year=>2008%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date ,:discard_day=>true , :order=>[:month,:year],:start_year=>2008%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n   \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'endoscopist_1\'=>1 ,\'diagnosis_group\'=>1}}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'endoscopist_1\'=>1 }}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    providers = @models[:provider].collection.find().to_a\r\n    m_providers = bmap providers, \'_id\'\r\n    \r\n    \r\n    # this_year_counts =  @models[:colonoscopy].collection.group( { :keyf => \"function(x){ return {\'pol : x.date.getMonth()}; }\" , \r\n    # :cond => {:date=>{\'$gte\'=>beginning_of_year,\'$lte\'=>now}}, \r\n    # :reduce => \'function(doc,prev) { prev.count += 1; }\', \r\n    # :initial => {:count => 0} })\r\n    \r\n\r\n    \r\n    \r\n    endos = {}\r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    \r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n            endoscopist = nil\r\n                status = \'Electivex\'\r\n                dg = nil\r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       endoscopist = r_colo[0][\'endoscopist_1\']    \r\n                       dg = r_colo[0][\'diagnosis_group\']\r\n                    end\r\n            \r\n                   \r\n\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       endoscopist = r_gastro[0][\'endoscopist_1\']    \r\n\r\n                    end\r\n                    \r\n\r\n\r\n                    \r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       endoscopist = r_colo[0][\'endoscopist_1\'] \r\n                       dg = r_colo[0][\'diagnosis_group\']\r\n                    end\r\n                       \r\n\r\n                end\r\n              \r\n            end\r\n                \r\n                        \r\n                endos[endoscopist] = {} unless endos[endoscopist]\r\n                endos[endoscopist][status] = [0,0,0] unless endos[endoscopist][status]\r\n                \r\n                d =   endos[endoscopist][status] \r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n                \r\n                endos[endoscopist][\'total\'] = [0,0,0] unless endos[endoscopist][\'total\']\r\n                d =   endos[endoscopist][\'total\'] \r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            \r\n                if dg and (dg.downcase.index(\'polyp\') or dg.index(\'Cancer\') or dg.index(\'Polyposis\') or dg.index(\'Submucosal\'))\r\n                    endos[endoscopist][\'adr\'] = 0 unless endos[endoscopist][\'adr\']\r\n                    endos[endoscopist][\'adr\'] += 1\r\n                end\r\n            \r\n            \r\n                # dates[date] = {} unless dates[date]\r\n                # dates[date][status] = [0,0,0] unless dates[date][status]\r\n                \r\n                # d = dates[date][status]\r\n                # if d\r\n                # d[0]+= data[0]\r\n                # d[1]+= data[1]\r\n                # d[2]+= data[2]\r\n                # end\r\n            # else\r\n            \r\n            \r\n            \r\n        # else\r\n            \r\n            if false\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        \r\n    # end\r\n        end\r\n    \r\n    end\r\n    \r\n    %>\r\n    \r\n    <%# m_providers.inspect  %>\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    <%\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<%# endos.inspect %>\r\n\r\n<% \r\n\r\n    # month_text = select_date.strftime(\"%B-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n        td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.date{\r\n        padding:5px 10px 5px 10px;\r\n        \r\n        \r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n        \r\n    }\r\n\r\n    \r\n</style>\r\n\r\n<%\r\n\r\nfrom_text =  month_th[from_date.month-1]+from_date.strftime(\"-%Y\")\r\n\r\nto_text =  month_th[to_date.month-1]+to_date.strftime(\"-%Y\")\r\n \r\n%>\r\n\r\n<div style=\"width:720px\">\r\n<center><h3>\r\nรายงานจำนวนผู้เข้ารับบริการ \r\n<%=@current_project.get_setting \'report_title_1\' %>\r\n<br/>\r\n<%=@current_project.get_setting \'report_title_2\' %></h3>\r\n<br/>\r\n<h4>แบ่งตามแพทย์ ระหว่างวันที่\r\n    <%=from_text%> - <%= to_text %>\r\n</h4></center>\r\n</div>\r\n\r\n<br/>\r\n<table border=\"1\" class=\"content\">\r\n<%\r\n   m = nil\r\n   \r\n   \r\n       tsum = {\'Elective\'=>[0,0,0,0],\'Extratime\'=>[0,0,0,0], \'Emergency\'=>[0,0,0,0], \'Total\'=>[0,0,0,0]}\r\n%>\r\n\r\n<%\r\n     days = stop_date.day\r\n\r\n%>\r\n\r\n\r\n<tr style=\"background:#ffffde\"><td>&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n    \r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"><td align=\"center\"> Endoscopist</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n</tr>\r\n\r\n<%\r\n   keys = endos.keys\r\n   \r\n   keys.sort!{|a,b| \r\n    \r\n    aa = endos[a][\'total\']\r\n    bb = endos[b][\'total\']\r\n    aa = aa[0]+aa[1]+aa[2]\r\n    bb = bb[0]+bb[1]+bb[2]\r\n    bb<=>aa\r\n   \r\n   }\r\n   \r\n   \r\n   \r\n   keys.each do |i|\r\n       \r\n   unless endos[i]\r\n   %><tr><td>\r\n   <%=i.inspect %></td></tr>\r\n   <%\r\n   end\r\n  \r\n   if endos[i] and i!=nil\r\n    provider = \'deleted\'\r\n    provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n%>\r\n\r\n\r\n<tr>\r\n    <td class=\"\" ><%=provider%> </td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Extratime Emergency} \r\n        \r\n        k = [0,0,0]\r\n        k = endos[i][j] if endos[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        \r\n        tsum[j][0] += k[0]\r\n        tsum[j][1] += k[1]\r\n        tsum[j][2] += k[2]\r\n        tsum[j][3] += s\r\n        \r\n        \r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        s = \'.\' if s == 0 \r\n        \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n\r\n</tr> \r\n<% end %>\r\n<% end %>\r\n<tr><td>&nbsp;</td>\r\n<%\r\n\r\n   t = [0,0,0,0]\r\n\r\n  for j in %w{Elective Extratime Emergency} \r\n    \r\n  4.times do |i|    \r\n  t[i]+=tsum[j][i]\r\n%>\r\n<td class=\"total2\"><%=tsum[j][i]%></td>\r\n<% end %> \r\n<% end %> \r\n\r\n<td class=\"total2\"><%=t[0]%></td><td class=\"total2\"><%=t[1]%></td><td class=\"total2\"><%=t[2]%></td><td class=\"total2\"><%=t[3]%></td>\r\n\r\n</tr>\r\n</table>\r\n\r\n\r\n<br/>\r\n<h4>Polyp detection rate </h4>\r\n<br/><table>\r\n    <%\r\n     \r\n    keys.each do |i|\r\n  \r\n       if endos[i] and i!=nil  and c =  endos[i][\'adr\']\r\n    \r\n        provider = \'NA\'\r\n        provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n        t = endos[i][\'total\']\r\n        total =t[0]+t[2]+t[1]\r\n    \r\n    %>\r\n       \r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\"><%=provider%></td><td  align=\"right\"><%= c %> ราย / <%=total%> ราย <span style=\"color:blue\"><%=c*100/total %>%</span></td>\r\n    </tr>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    \r\n</table>\r\n\r\n</div>\r\n<br/>\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n\r\n\r\n<% end %>\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-11-15 04:01:29','2016-11-15 04:01:29','endoscopist_report',''),(2726,'procedure_report',1098,2,'<h1>Procedure Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n\r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy ercp eus}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nFrom : <%= f.date_select :from_date, :default=>from_date ,:discard_day=>true , :order=>[:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date ,:discard_day=>true , :order=>[:month,:year]%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_ercp = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}ercp\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_ercp = bmap all_pm_ercp, \'parent_id\'\r\n    \r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_eus = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}eus\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_eus = bmap all_pm_eus, \'parent_id\'\r\n \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'endoscopist_1\'=>1 ,\'procedure\'=>1}}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'endoscopist_1\'=>1, \'procedure\'=>1}}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n    ercp = @models[:ercp].collection.find({:_id=>{\'$in\'=>all_pm_ercp.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'endoscopist_1\'=>1 ,\'diagnosis_group\'=>1,\'procedure\'=>1}}).to_a\r\n    m_ercp = bmap ercp, \'_id\'\r\n    \r\n    eus = @models[:eus].collection.find({:_id=>{\'$in\'=>all_pm_eus.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'endoscopist_1\'=>1 ,\'procedure\'=>1}}).to_a\r\n    m_eus = bmap eus, \'_id\'\r\n    \r\n \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    providers = @models[:provider].collection.find().to_a\r\n    m_providers = bmap providers, \'_id\'\r\n    \r\n    \r\n    # this_year_counts =  @models[:colonoscopy].collection.group( { :keyf => \"function(x){ return {\'pol : x.date.getMonth()}; }\" , \r\n    # :cond => {:date=>{\'$gte\'=>beginning_of_year,\'$lte\'=>now}}, \r\n    # :reduce => \'function(doc,prev) { prev.count += 1; }\', \r\n    # :initial => {:count => 0} })\r\n    \r\n\r\n    \r\n    \r\n    endos = {}\r\n    \r\n    \r\n    dates = {}\r\n    vt = {}\r\n    \r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                ercp = m_all_pm_ercp[pm_app[\'_id\']]\r\n                eus = m_all_pm_eus[pm_app[\'_id\']]\r\n\r\n\r\n\r\n                \r\n                \r\n                \r\n                \r\n                endoscopist = nil\r\n                status = \'Elective\'\r\n                proc_colo = nil\r\n                proc_gastro = nil\r\n                proc_ercp = nil\r\n                proc_eus = nil\r\n\r\n\r\n                # if colo and !gastro\r\n                #     data[0]+=1    \r\n                    \r\n                #     r_colo = m_colo[colo[0][\'module_id\']]\r\n                #     if r_colo\r\n                #       endoscopist = r_colo[0][\'endoscopist_1\']    \r\n                #       proc_colo = r_colo[0][\'procedure\'] if r_colo[0][\'procedure\'] !=\'\' \r\n                #     end\r\n            \r\n                # end\r\n                # if !colo and gastro\r\n                #     data[1]+=1    \r\n                    \r\n                #     r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                #     if r_gastro\r\n                #       endoscopist = r_gastro[0][\'endoscopist_1\']    \r\n                #       proc_gastro = r_gastro[0][\'procedure\'] if r_gastro[0][\'procedure\'] !=\'\'\r\n                #     end\r\n                    \r\n                # end\r\n                \r\n                \r\n                 if ercp\r\n                     r_ercp = m_ercp[ercp[0][\'module_id\']]\r\n                    if r_ercp\r\n                        endoscopist = r_ercp[0][\'endoscopist_1\']    \r\n                        \r\n                        proc_ercp = r_ercp[0][\'diagnosis_group\'] if r_ercp[0][\'diagnosis_group\'] !=\'\'\r\n                    end   \r\n                end\r\n                \r\n                 if eus\r\n                     r_eus = m_eus[eus[0][\'module_id\']]\r\n                    if r_eus\r\n                        endoscopist = r_eus[0][\'endoscopist_1\']    \r\n                        proc_eus = r_eus[0][\'procedure\'] if r_eus[0][\'procedure\'] !=\'\'\r\n                    end   \r\n                end\r\n                \r\n                \r\n                if gastro\r\n                     r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                        endoscopist = r_gastro[0][\'endoscopist_1\']    \r\n                        proc_gastro = r_gastro[0][\'procedure\'] if r_gastro[0][\'procedure\'] !=\'\'\r\n                    end   \r\n                end\r\n                \r\n                if colo \r\n                    \r\n                     r_colo = m_colo[colo[0][\'module_id\']]\r\n                    \r\n                     if r_colo\r\n                       endoscopist = r_colo[0][\'endoscopist_1\'] \r\n                       dg = r_colo[0][\'diagnosis_group\']\r\n                       proc_colo = r_colo[0][\'procedure\'] if r_colo[0][\'procedure\'] !=\'\'\r\n                    end\r\n                end \r\n                \r\n                \r\n                \r\n                \r\n                # if colo and gastro\r\n                #     data[0]+=1    \r\n                #     r_colo = m_colo[colo[0][\'module_id\']]\r\n                #     r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                #     if r_gastro\r\n                #         # endoscopist = r_gastro[0][\'endoscopist_1\']    \r\n                #         proc_gastro = r_gastro[0][\'procedure\'] if r_gastro[0][\'procedure\'] !=\'\'\r\n                #     end   \r\n                #     if r_colo\r\n                #       endoscopist = r_colo[0][\'endoscopist_1\'] \r\n                #       dg = r_colo[0][\'diagnosis_group\']\r\n                #       proc_colo = r_colo[0][\'procedure\'] if r_colo[0][\'procedure\'] !=\'\'\r\n                #     end\r\n                  \r\n\r\n                # end\r\n                \r\n                if proc_colo or proc_gastro or proc_ercp or proc_eus\r\n            \r\n            \r\n                endos[endoscopist] = {} unless endos[endoscopist]\r\n                \r\n                endos[endoscopist][\'colo\'] = {} unless endos[endoscopist][\'colo\']\r\n                endos[endoscopist][\'gastro\'] = {} unless endos[endoscopist][\'gastro\']\r\n                endos[endoscopist][\'ercp\'] = {} unless endos[endoscopist][\'ercp\']\r\n                endos[endoscopist][\'eus\'] = {} unless endos[endoscopist][\'eus\']\r\n                \r\n                \r\n                if proc_colo\r\n                   l = proc_colo.split(\'|\').collect{|i| i if i!=\'\' }.compact \r\n                    for i in l\r\n                        endos[endoscopist][\'colo\'][i] = 0 unless endos[endoscopist][\'colo\'][i]\r\n                        endos[endoscopist][\'colo\'][i] += 1\r\n                    end\r\n                end\r\n                \r\n                if proc_gastro\r\n                   l = proc_gastro.split(\'|\').collect{|i| i if i!=\'\' }.compact \r\n                     for i in l\r\n                        endos[endoscopist][\'gastro\'][i] = 0 unless endos[endoscopist][\'gastro\'][i]\r\n                        endos[endoscopist][\'gastro\'][i] += 1\r\n                    end\r\n                end\r\n                \r\n                \r\n                \r\n                if proc_ercp\r\n                   l = proc_ercp.split(\'|\').collect{|i| i if i!=\'\' }.compact \r\n                     for i in l\r\n                        endos[endoscopist][\'ercp\'][i] = 0 unless endos[endoscopist][\'ercp\'][i]\r\n                        endos[endoscopist][\'ercp\'][i] += 1\r\n                    end\r\n                end\r\n                \r\n                \r\n                \r\n                if proc_eus\r\n                \r\n                \r\n                   l = proc_eus.split(\'|\').collect{|i| i if i!=\'\' }.compact \r\n                     for i in l\r\n                        endos[endoscopist][\'eus\'][i] = 0 unless endos[endoscopist][\'eus\'][i]\r\n                        endos[endoscopist][\'eus\'][i] += 1\r\n                    end\r\n                end\r\n                \r\n                \r\n                end\r\n                \r\n                # d =   endos[endoscopist][status] \r\n                # if d\r\n                # d[0]+= data[0]\r\n                # d[1]+= data[1]\r\n                # d[2]+= data[2]\r\n                # end\r\n                \r\n                # endos[endoscopist][\'total\'] = [0,0,0] unless endos[endoscopist][\'total\']\r\n                # d =   endos[endoscopist][\'total\'] \r\n                # if d\r\n                # d[0]+= data[0]\r\n                # d[1]+= data[1]\r\n                # d[2]+= data[2]\r\n                # end\r\n            \r\n                # if dg and (dg.index(\'polyp\') or dg.index(\'Cancer\'))\r\n                #     endos[endoscopist][\'adr\'] = 0 unless endos[endoscopist][\'adr\']\r\n                #     endos[endoscopist][\'adr\'] += 1\r\n                # end\r\n            \r\n            \r\n                # dates[date] = {} unless dates[date]\r\n                # dates[date][status] = [0,0,0] unless dates[date][status]\r\n                \r\n                # d = dates[date][status]\r\n                # if d\r\n                # d[0]+= data[0]\r\n                # d[1]+= data[1]\r\n                # d[2]+= data[2]\r\n                # end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n            \r\n            if false\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        \r\n    end\r\n        end\r\n    \r\n    end\r\n    \r\n    %>\r\n    \r\n    <%# m_providers.inspect  %>\r\n    \r\n    \r\n    \r\n    <%#endos.inspect %>\r\n    \r\n    \r\n    \r\n    <%\r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<%# endos.inspect %>\r\n\r\n<% \r\n\r\n    # month_text = select_date.strftime(\"%B-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n           td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.date{\r\n        padding:5px 10px 5px 10px;\r\n        \r\n        \r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n        \r\n    }\r\n\r\n    \r\n</style>\r\n\r\n<%\r\n   \r\n   gastro_list = []\r\n   colo_list = []\r\n   ercp_list = []\r\n   eus_list = []\r\n   \r\n   \r\n   \r\n   colo_count = {}\r\n   gastro_count = {}\r\n   ercp_count = {}\r\n   eus_count = {}\r\n   \r\n   \r\n   for i in endos.values\r\n        \r\n        i[\'ercp\'].each_pair do |j,count|\r\n            \r\n            ercp_list << j\r\n            ercp_count[j] = 0 unless  ercp_count[j]\r\n            ercp_count[j] += count\r\n        end\r\n        \r\n        i[\'eus\'].each_pair do |j,count|\r\n            \r\n            eus_list << j\r\n            eus_count[j] = 0 unless  eus_count[j]\r\n            eus_count[j] += count\r\n        end\r\n        \r\n        \r\n        \r\n        i[\'gastro\'].each_pair do |j,count|\r\n            \r\n            gastro_list << j\r\n            gastro_count[j] = 0 unless  gastro_count[j]\r\n            gastro_count[j] += count\r\n        end\r\n        \r\n        \r\n        \r\n        i[\'colo\'].each_pair do |j,count|\r\n            colo_list << j\r\n            colo_count[j] = 0 unless colo_count[j]\r\n            colo_count[j] += count\r\n        end\r\n   end\r\n   \r\n   ercp_list.uniq!\r\n   eus_list.uniq!\r\n   gastro_list.uniq!\r\n   colo_list.uniq!\r\n   \r\n   \r\n   colo_list.sort!{|a,b| colo_count[b]<=>colo_count[a]}\r\n   gastro_list.sort!{|a,b| gastro_count[b]<=>gastro_count[a]}\r\n   ercp_list.sort!{|a,b| ercp_count[b]<=>ercp_count[a]}\r\n   eus_list.sort!{|a,b| eus_count[b]<=>eus_count[a]}\r\n   \r\n   \r\n%>\r\n<%\r\n\r\nfrom_text =  month_th[from_date.month-1]+from_date.strftime(\"-%Y\")\r\n\r\nto_text =  month_th[to_date.month-1]+to_date.strftime(\"-%Y\")\r\n \r\n%>\r\n<center><h3>\r\nรายงานจำนวนผู้เข้ารับบริการ \r\n<%=@current_project.get_setting \'report_title_1\' %>\r\n<br/>\r\n<%=@current_project.get_setting \'report_title_2\' %></h3>\r\n<br/>\r\n<h4>แยกตามประเภทการรักษา ระหว่างวันที่ \r\n    <%=from_text %> - <%= to_text %>\r\n</h4></center>\r\n\r\n<h3>Colonoscopy Procedures</h3>\r\n\r\n\r\n<br/>\r\n\r\n<table border=\"1\" class=\"content\">\r\n\r\n<tr style=\"background-color:#dedeff\"><th>Endoscopist</th>\r\n    <% for j in colo_list %>\r\n    <th><%=j%></th>\r\n    <% end %>\r\n</tr>\r\n<%\r\n   \r\n   \r\n   \r\n   keys = endos.keys\r\n   \r\n   \r\n   keys.each do |i|\r\n  \r\n   if e = endos[i] and i!=nil\r\n    provider = \'deleted\'\r\n    provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n\r\n%>\r\n\r\n\r\n<tr>\r\n    <td class=\"\" ><%=provider%> </td>\r\n    <%\r\n        e_colo = e[\'colo\']\r\n        for j in colo_list\r\n            %>\r\n            <td align=\"center\"><%=e_colo[j]%></td>\r\n            <%\r\n        end\r\n    %>\r\n</tr> \r\n<% end %>\r\n<% end %>\r\n<tr>\r\n    <td>Total</td>\r\n    <% for j in colo_list %>\r\n    <td class=\"total2\"><%= colo_count[j]%></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n\r\n<hr/>\r\n\r\n\r\n\r\n<h3>Gastroscopy Procedures</h3>\r\n\r\n\r\n<br/>\r\n\r\n<table border=\"1\" class=\"content\">\r\n\r\n<tr style=\"background-color:#dedeff\"><th>Endoscopist</th>\r\n    <% for j in gastro_list %>\r\n    <th><%=j%></th>\r\n    <% end %>\r\n</tr>\r\n<%\r\n   \r\n   \r\n   \r\n   keys = endos.keys\r\n   \r\n   lkeys = []\r\n   \r\n   keys.each do |i|\r\n      sum=0\r\n      for j in gastro_list\r\n        sum+=endos[i][\'gastro\'][j]  if endos[i][\'gastro\'][j]\r\n      end\r\n      lkeys << i if sum>0\r\n   end\r\n   \r\n   \r\n   \r\n   lkeys.each do |i|\r\n  \r\n   if e = endos[i] and i!=nil\r\n    provider = \'deleted\'\r\n    provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n\r\n%>\r\n\r\n\r\n<tr>\r\n    <td class=\"\" ><%=provider%> </td>\r\n    <%\r\n        e_colo = e[\'gastro\']\r\n        for j in gastro_list\r\n            %>\r\n            <td align=\"center\"><%=e_colo[j]%></td>\r\n            <%\r\n        end\r\n    %>\r\n</tr> \r\n<% end %>\r\n<% end %>\r\n<tr>\r\n    <td>Total</td>\r\n    <% for j in gastro_list %>\r\n    <td class=\"total2\"><%= gastro_count[j]%></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n\r\n<hr/>\r\n\r\n\r\n<!-------------------------------------   -->\r\n\r\n<h3>ERCP Procedures</h3>\r\n\r\n\r\n<br/>\r\n\r\n<table border=\"1\" class=\"content\">\r\n\r\n<tr style=\"background-color:#dedeff\"><th>Endoscopist</th>\r\n    <% for j in ercp_list %>\r\n    <th><%=j%></th>\r\n    <% end %>\r\n</tr>\r\n<%\r\n   \r\n   \r\n   \r\n   keys = endos.keys\r\n   \r\n   lkeys = []\r\n   \r\n   keys.each do |i|\r\n      sum=0\r\n      for j in ercp_list\r\n        sum+=endos[i][\'ercp\'][j]  if endos[i][\'ercp\'][j]\r\n      end\r\n      lkeys << i if sum>0\r\n   end\r\n   \r\n   \r\n   \r\n   lkeys.each do |i|\r\n  \r\n   if e = endos[i] and i!=nil\r\n    provider = \'deleted\'\r\n    provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n\r\n%>\r\n\r\n\r\n<tr>\r\n    <td class=\"\" ><%=provider%> </td>\r\n    <%\r\n        e_colo = e[\'ercp\']\r\n        for j in ercp_list\r\n            %>\r\n            <td align=\"center\"><%=e_colo[j]%></td>\r\n            <%\r\n        end\r\n    %>\r\n</tr> \r\n<% end %>\r\n<% end %>\r\n<tr>\r\n    <td>Total</td>\r\n    <% for j in ercp_list %>\r\n    <td class=\"total2\"><%= ercp_count[j]%></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n\r\n\r\n<hr/>\r\n\r\n\r\n<!-------------------------------------   -->\r\n\r\n<h3>EUS Procedures</h3>\r\n\r\n\r\n<br/>\r\n\r\n<table border=\"1\" class=\"content\">\r\n\r\n<tr style=\"background-color:#dedeff\"><th>Endoscopist</th>\r\n    <% for j in eus_list %>\r\n    <th><%=j%></th>\r\n    <% end %>\r\n</tr>\r\n<%\r\n   \r\n   \r\n   \r\n   keys = endos.keys\r\n   \r\n   lkeys = []\r\n   \r\n   keys.each do |i|\r\n      sum=0\r\n      for j in eus_list\r\n        sum+=endos[i][\'eus\'][j]  if endos[i][\'eus\'][j]\r\n      end\r\n      lkeys << i if sum>0\r\n   end\r\n   \r\n   \r\n   \r\n   lkeys.each do |i|\r\n  \r\n   if e = endos[i] and i!=nil\r\n    provider = \'deleted\'\r\n    provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n\r\n%>\r\n\r\n\r\n<tr>\r\n    <td class=\"\" ><%=provider%> </td>\r\n    <%\r\n        e_colo = e[\'eus\']\r\n        for j in eus_list\r\n            %>\r\n            <td align=\"center\"><%=e_colo[j]%></td>\r\n            <%\r\n        end\r\n    %>\r\n</tr> \r\n<% end %>\r\n<% end %>\r\n<tr>\r\n    <td>Total</td>\r\n    <% for j in eus_list %>\r\n    <td class=\"total2\"><%= eus_count[j]%></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<%\r\nif false\r\n%>\r\n<br/>\r\n<h4>Adenoma detection rate (ADR)</h4>\r\n<br/><table>\r\n    <%\r\n     \r\n    keys.each do |i|\r\n  \r\n       if endos[i] and i!=nil  and c =  endos[i][\'adr\']\r\n    \r\n        provider = \'NA\'\r\n        provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n        t = endos[i][\'total\']\r\n        total =t[0]+t[2]\r\n    \r\n    %>\r\n       \r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\"><%=provider%></td><td  align=\"right\"><%= c %> ราย / <%=total%> ราย <span style=\"color:blue\"><%=c*100/total %>%</span></td>\r\n    </tr>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    \r\n</table>\r\n\r\n</div>\r\n<br/>\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n\r\n<%end %>\r\n\r\n<br/>\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n\r\n\r\n<% end %>\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-11-15 04:08:54','2016-11-15 04:08:54','procedure_report',''),(2727,'bowel_report',1098,2,'<h1>Bowel Prepreation</h1>\r\n<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\#{@current_project.name}#appointment\"\r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # params_date = select_date\r\n    # select_date = Date.to_mongo(select_date)\r\n    \r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date , :order=>[:day,:month,:year]%>\r\n\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    # start_date = select_date.beginning_of_month()\r\n    # stop_date = select_date.end_of_month()\r\n    \r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n\r\n    pname = \"\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n    all_pm_pre = @m_patient_module.collection.find({:module_name=>\"\\#{pname}pre_scope\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_pre = bmap all_pm_pre, \'parent_id\'\r\n    \r\n    \r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1, \'quality_of_preparate\'=>1 }}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n    pre_scope = @models[:pre_scope].collection.find({:_id=>{\'$in\'=>all_pm_pre.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'type_of_patient\'=>1}}).to_a\r\n    m_pre = bmap pre_scope, \'_id\'\r\n    \r\n    \r\n    \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    \r\n    # quality_of_preparate\r\n    # type_of_patient\r\n    bsum = {}\r\n    \r\n    dates = {}\r\n    vt = {}\r\n    for i in visits\r\n        vt[i[\'_id\']] = i[\'name\']\r\n    end\r\n    \r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m-%d\")\r\n            # visit = m_visit[app[\'visit_type\']]\r\n            # if visit\r\n                # visit = visit[0]\r\n                data = [0,0,0]\r\n                colo = m_all_pm_colo[pm_app[\'_id\']]\r\n                gastro = m_all_pm_gastro[pm_app[\'_id\']]\r\n                pre_scope = m_all_pm_pre[pm_app[\'_id\']]\r\n                \r\n                \r\n                p_colo = nil\r\n                p_gastro = nil\r\n                \r\n                status = \'Elective\'\r\n                \r\n                if colo and !gastro\r\n                    data[0]+=1    \r\n                    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    if r_colo\r\n                        status = r_colo[0][\'status\']\r\n                        p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    \r\n                end\r\n                if !colo and gastro\r\n                    data[1]+=1    \r\n                    \r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_gastro\r\n                       status = r_gastro[0][\'status\'] \r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                if colo and gastro\r\n                    data[2]+=1    \r\n                    r_colo = m_colo[colo[0][\'module_id\']]\r\n                    r_gastro = m_gastro[gastro[0][\'module_id\']]\r\n                    if r_colo\r\n                       status = r_colo[0][\'status\'] \r\n                       p_colo = r_colo[0][\'procedure\']\r\n                    end\r\n                    if r_gastro\r\n                       p_gastro =r_gastro[0][\'procedure\'] \r\n                    end\r\n                end\r\n                \r\n                type_of_patient = nil\r\n                bowel = nil\r\n                \r\n                \r\n                \r\n                if r_colo\r\n                   \r\n                   bowel = r_colo[0][\'quality_of_preparate\'] \r\n                    \r\n                end\r\n          \r\n                \r\n                if pre_scope \r\n                   \r\n                    r_pre = m_pre[pre_scope[0][\'module_id\']]\r\n                   \r\n                    if r_pre\r\n                        type_of_patient = r_pre[0][\'type_of_patient\']\r\n                    end\r\n                end\r\n                \r\n                      \r\n                      \r\n                \r\n            \r\n                \r\n                dates[date] = {} unless dates[date]\r\n                dates[date][status] = [0,0,0] unless dates[date][status]\r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                \r\n                if p_colo\r\n                dates[date][\'p_colo\'] = {} unless dates[date][\'p_colo\']\r\n                for pi in p_colo.split(\"|\")\r\n                    dates[date][\'p_colo\'][pi] = 0 unless  dates[date][\'p_colo\'][pi]\r\n                    dates[date][\'p_colo\'][pi] += 1 \r\n                end\r\n                \r\n                \r\n                \r\n                end\r\n                if p_gastro\r\n                \r\n                dates[date][\'p_gastro\'] = {} unless dates[date][\'p_gastro\']\r\n                for pi in p_gastro.split(\"|\")\r\n                dates[date][\'p_gastro\'][pi] = 0 unless  dates[date][\'p_gastro\'][pi]\r\n                dates[date][\'p_gastro\'][pi] += 1 \r\n                end\r\n                end\r\n                \r\n                \r\n                if bowel\r\n                \r\n                bk = \"\\#{type_of_patient}-\\#{bowel}\"\r\n                \r\n                type_of_patient = \'NA\' unless type_of_patient\r\n                \r\n                dates[date][\'bowel\'] = {} unless dates[date][\'bowel\']\r\n                dates[date][\'bowel\'][bk] = 0 unless dates[date][\'bowel\'][bk]\r\n                dates[date][\'bowel\'][bk] += 1\r\n                \r\n                bsum[bk] = 0 unless bsum[bk]\r\n                bsum[bk] += 1 \r\n                \r\n                \r\n                end\r\n                \r\n                d = dates[date][status]\r\n                if d\r\n                d[0]+= data[0]\r\n                d[1]+= data[1]\r\n                d[2]+= data[2]\r\n                end\r\n            # else\r\n            \r\n            \r\n            \r\n        else\r\n        %>  \r\n        \r\n            no pm_app for <%=app[\'_id\'] %>\r\n        <%\r\n        end\r\n    \r\n    end\r\n    \r\n    # month date\r\n    #                     1   2   3   4   5   6\r\n    # elective\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # extratime\r\n    #     colono\r\n    #     gastro\r\n    #     colono + gastro\r\n    # emmergency    \r\n    \r\n    #                 elective                    extratime                       embergency                        total\r\n    #         colo    gastro    colo+gastro       colo    gastro  colo+gastro     colo    gastro  colo+gastro       colo    gastro  colo+gastro\r\n    # 1\r\n    # 2\r\n    # 3\r\n    # 4\r\n    # 5\r\n    # 6\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<% \r\nmonth_text=\'\'\r\n    # month_text = month_th[select_date.month-1]+select_date.strftime(\"-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    \r\n    td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.small{\r\n        font-size:0.8em;\r\n    }\r\n    td.date{\r\n        padding:0px;\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n        td.date{\r\n        padding:0px;\r\n        \r\n        width:125px;\r\n        \r\n    }\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n    \r\n    tr.page-break{page-break-after:always;page-break-inside:avoid; page-break-after:auto}\r\n    .force-break{ display: block;page-break-before:always;}\r\n        \r\n    }\r\n    \r\n\r\n    \r\n   table { page-break-inside:auto }\r\n   tr    { page-break-inside:avoid; page-break-after:auto }\r\n    \r\n</style>\r\n<style type=\"text/css\">\r\n\r\n</style>\r\n\r\n<div style=\"width:720px\">\r\n\r\n<center><h3>\r\nรายงานจำนวนผู้เข้ารับบริการ \r\n<%=@current_project.get_setting \'report_title_1\' %>\r\n<br/>\r\n<%=@current_project.get_setting \'report_title_2\' %></h3>\r\n<br/>\r\n<h4>ระหว่างวันที่ \r\n    <%=start_date.strftime(\'%d/%m/%Y\')%> - <%= stop_date.strftime(\'%d/%m/%Y\') %>\r\n</h4></center>\r\n\r\n</div>\r\n\r\n<br/>\r\n<table border=\"1\" class=\"content\">\r\n<%\r\n   m = nil\r\n   \r\n   #quality_of_preparate\r\n    \r\n    \r\n       tsum = {\'Elective\'=>[0,0,0,0],\'Extratime\'=>[0,0,0,0], \'Emergency\'=>[0,0,0,0], \'Total\'=>[0,0,0,0]}\r\n%>\r\n\r\n<%\r\n     pc_map = {}\r\n     pg_map = {}\r\n     \r\n     days = ((stop_date-start_date)/3600/24).to_i\r\n     \r\n    dates.each_pair do |k,v|\r\n        if v[\'p_colo\']    \r\n         v[\'p_colo\'].each_pair do |p,count|\r\n            pc_map[p] = 0 unless pc_map[p]\r\n            pc_map[p] += count\r\n         end\r\n        end\r\n        \r\n        if v[\'p_gastro\'] \r\n         v[\'p_gastro\'].each_pair do |p,count|\r\n            pg_map[p] = 0 unless pg_map[p]\r\n            pg_map[p] += count\r\n         end\r\n        end\r\n     \r\n    end\r\n     \r\n     \r\n\r\n%>\r\n\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td >&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n    <td colspan=\"9\" align=\"center\" >Bowel Preparation </td>\r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"  class=\"page-break\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n    <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n    <td>OPD Good</td><td>OPD Fair</td><td>OPD Poor</td>\r\n    <td>IPD Good</td><td>IPD Fair</td><td>IPD Poor</td>\r\n    <td>NA Good</td><td>NA Fair</td><td>NA Poor</td>\r\n</tr>\r\n\r\n\r\n<%\r\n\r\n  \r\n\r\n        count = 0 \r\n   \r\n   days.times do |date|\r\n  \r\n   date = (start_date+(date*3600*24))\r\n   i = date.strftime(\"%Y-%m-%d\")\r\n   \r\n#   for i in dates.keys.sort\r\n    weekend = \'\'\r\n    weekend = \'weekend\' if date.wday==0 or date.wday==6\r\n\r\n    \r\n    \r\n    if dates[i]\r\n\r\n%>\r\n\r\n<% if date.day==1 and count!=0%>\r\n\r\n\r\n<tr style=\"background:#ffffde\"  class=\"page-break\"><td style=\"width:120px\">&nbsp;</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Elective tx\" >Elective</td>\r\n        <td colspan=\"4\" align=\"center\" class=\"Emergency tx\">Emergency</td>\r\n    <td colspan=\"4\" align=\"center\" class=\"Extratime tx\">Extratime</td>\r\n\r\n    <td colspan=\"4\" align=\"center\" class=\"total tx\">Total</td>\r\n</tr>\r\n\r\n<tr style=\"background:#dedeff\"  class=\"page-break\"><td>Date</td>\r\n    <td class=\"Elective\">C</td><td class=\"Elective\">G</td><td class=\"Elective\">C+G</td><td class=\"Elective\">Sum</td>\r\n        <td class=\"Emergency\">C</td><td class=\"Emergency\">G</td><td class=\"Emergency\">C+G</td><td class=\"Emergency\">Sum</td>\r\n    <td class=\"Extratime\">C</td><td class=\"Extratime\">G</td><td class=\"Extratime\">C+G</td><td class=\"Extratime\">Sum</td>\r\n\r\n    <td class=\"total\">C</td><td class=\"total\">G</td><td class=\"total\">C+G</td><td class=\"total\">Sum</td>\r\n</tr>\r\n\r\n<% end %>\r\n<tr class=\"page-break\" align=\"center\">\r\n    <td class=\"date <%=weekend%>\" ><%=i.split(\'-\').reverse.join(\'-\')%> </td>\r\n    <% \r\n    sum = [0,0,0]\r\n    for j in %w{Elective Emergency Extratime} \r\n        \r\n        k = [0,0,0]\r\n        k = dates[i][j] if dates[i][j]     \r\n        sum[0] += k[0]\r\n        sum[1] += k[1]\r\n        sum[2] += k[2]\r\n        s = k[0]+k[1]+k[2]\r\n        \r\n        tsum[j][0] += k[0]\r\n        tsum[j][1] += k[1]\r\n        tsum[j][2] += k[2]\r\n        tsum[j][3] += s\r\n        \r\n        \r\n        k[0] = \'.\' if k[0] == 0 \r\n        k[1] = \'.\' if k[1] == 0 \r\n        k[2] = \'.\' if k[2] == 0 \r\n        s = \'.\' if s == 0 \r\n        \r\n        \r\n    %>\r\n    <td class=\"<%=j%>\"><%=k[0] %></td> <td class=\"<%=j%>\"><%=k[1] %></td> <td class=\"<%=j%>\"><%=k[2] %></td> <td class=\"<%=j%>\"><u><%=s %></u></td>\r\n\r\n    <% end %>\r\n    <td class=\"total\"><%=sum[0] %></td> <td class=\"total\"><%=sum[1] %></td> <td class=\"total\"><%=sum[2] %></td> <td class=\"total\"><%=sum[0]+sum[1]+sum[2] %></td>\r\n    \r\n    <%  bowel = dates[i][\'bowel\']  \r\n    \r\n        \r\n    \r\n    %>\r\n    \r\n    <td><%=bowel[\'OPD-Good\']%></td>\r\n    \r\n    <td><%=bowel[\'OPD-Fair\']%></td>\r\n    \r\n    <td><%=bowel[\'OPD-Poor\']%></td>\r\n    \r\n    \r\n    <td><%=bowel[\'IPD-Good\']%></td>\r\n    \r\n    <td><%=bowel[\'IPD-Fair\']%></td>\r\n    \r\n    <td><%=bowel[\'IPD-Poor\']%></td>\r\n    \r\n    \r\n    <td><%=bowel[\'NA-Good\']%></td>\r\n    \r\n    <td><%=bowel[\'NA-Fair\']%></td>\r\n    \r\n    <td><%=bowel[\'NA-Poor\']%></td>\r\n\r\n</tr> \r\n<% else %>\r\n<tr class=\"page-break\">\r\n    <td class=\"date  <%=weekend%>\"><%=i.split(\'-\').reverse.join(\'-\')%></td>\r\n    <td colspan=\"<%=16+pc_map.keys.size+pg_map.keys.size%>\">\r\n        &nbsp;\r\n        \r\n    </td>\r\n    \r\n</tr>\r\n<% end %>\r\n\r\n<% \r\ncount+=1\r\n\r\nend %>\r\n\r\n<tr class=\"page-break\" align=\"center\"><td>Total</td>\r\n<%\r\n\r\n   t = [0,0,0,0]\r\n\r\n  for j in %w{Elective Extratime Emergency} \r\n    \r\n  4.times do |i|    \r\n  t[i]+=tsum[j][i]\r\n%>\r\n<td class=\"total2\"><%=tsum[j][i]%></td>\r\n<% end %> \r\n<% end %> \r\n\r\n<td class=\"total2\"><%=t[0]%></td><td class=\"total2\"><%=t[1]%></td><td class=\"total2\"><%=t[2]%></td><td class=\"total2\"><%=t[3]%></td>\r\n<%  bowel = bsum %>\r\n    <td><%=bowel[\'OPD-Good\']%></td>\r\n    \r\n    <td><%=bowel[\'OPD-Fair\']%></td>\r\n    \r\n    <td><%=bowel[\'OPD-Poor\']%></td>\r\n    \r\n    \r\n    <td><%=bowel[\'IPD-Good\']%></td>\r\n    \r\n    <td><%=bowel[\'IPD-Fair\']%></td>\r\n    \r\n    <td><%=bowel[\'IPD-Poor\']%></td>\r\n    \r\n    \r\n    <td><%=bowel[\'NA-Good\']%></td>\r\n    \r\n    <td><%=bowel[\'NA-Fair\']%></td>\r\n    \r\n    <td><%=bowel[\'NA-Poor\']%></td>\r\n\r\n</tr>\r\n</table>\r\n<br/>\r\n<h4>รวมจำนวนผู้เข้ารับบริการ</h4>\r\n<br/><table>\r\n    <tr>\r\n        <td colspan=\"2\"></td><td>Elective</td><td>Emergency</td><td>Extratime</td>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">Colonoscopy</td><td  align=\"right\"><%= t[0] %> ราย</td>\r\n        \r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]%> </td>\r\n        <%  end %>\r\n        \r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">Gastroscopy</td><td  align=\"right\"><%= t[1] %> ราย </td>\r\n        <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][1]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">Gastroscopy & Colonoscopy</td><td  align=\"right\"><%= t[2] %> ราย </td>\r\n           <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    <tr>\r\n        <td align=\"left\" style=\"width:250px\">รวม</td><td  align=\"right\"><%= t[0]+t[1]+t[2] %> ราย </td>\r\n          <%  for j in %w{Elective Emergency Extratime}  %>\r\n        <td align=\"right\"> <%=tsum[j][0]+tsum[j][1]+tsum[j][2]%> </td>\r\n        <%  end %>\r\n    </tr>\r\n    \r\n</table>\r\n\r\n</div>\r\n<br/>\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2016-11-15 04:14:44','2016-11-15 04:14:44','bowel_report',''),(2728,'document_name',1099,1,'\'room\'',NULL,NULL,NULL,'2016-11-15 14:14:49','2016-11-15 14:14:49',NULL,NULL),(2729,'document_name',1100,1,'\'appointment\'',NULL,NULL,NULL,'2016-11-15 14:27:15','2016-11-15 14:27:15',NULL,NULL),(2730,'last_updated',1061,3,'<%\r\n    date = Time.now\r\n    if params[:date]\r\n        date = params[:date]\r\n    end\r\n    date = Date.to_mongo(params[:date])\r\n    \r\n    a_app = get_model[:appointment].where(:date=>Date.to_mongo(date)).all\r\n    a_app = a_app.sort_by{|i| i[:updated_at]}.reverse\r\n\r\n\r\n    res = {}\r\n    if !a_app.empty?\r\n        res[:last_updated] = a_app.first[:updated_at]\r\n        res[:app_first] = a_app.first[:updated_at]\r\n        res[:app_last] = a_app.last[:updated_at]\r\n    else\r\n        res[:last_updated] = \"\"\r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2016-11-15 14:30:20','2016-11-15 14:30:20','last','*'),(2731,'index_partial_bk',1061,3,'<%\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n    pdate = date.strftime(\'%d/%m/%Y\')\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n# 	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n    status_list = this.status_list\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	r_model = models[:room]\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	room_list = [\'N/A\']\r\n	rooms = {nil=>\'N/A\',\'\'=>\'N/A\'}\r\n	r_model.all.each do |i|\r\n	    rooms[i.id.to_s] = i[:name]\r\n	    room_list << i[:name]\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n\r\n	id = \'\'\r\n	a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = module_model.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n	\r\n	# form service\r\n	f_ser = {}\r\n	# service_map\r\n	sm = this.service_map\r\n	sm.each do |k, v|\r\n	    f_ser[k] = {}\r\n	    tmp = module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>pa_id).all\r\n	    tmp.each do |i|\r\n	        f_ser[k][i[:patient_id].to_s] = i.id.to_s\r\n	    end\r\n	end\r\n	\r\n	\r\n	aps.collect!{|i| \r\n        id = i.id\r\n        if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n            pat_id = m.patient_id.to_s\r\n    	     patient = patient_model.find(m.patient_id)\r\n    	     if patient \r\n        	     provider = p_model.find(i.provider)\r\n        	     visit_type = visits[i.visit_type]\r\n        	     provider_name = \'NA\'\r\n        	     provider_name = provider.name if provider\r\n        	     procedure_name = \'NA\'\r\n        	     pro = models[:procedure].find(i.procedure) \r\n        	     procedure_name = pro.name if pro\r\n        	     patient = patient_model.new unless patient \r\n        	     hn = \'-\'\r\n        	     \r\n        	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n        	     prov_name = provider_name\r\n        	     provider_name  = link_to(provider_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     procedure_name = link_to(procedure_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     public_id = \'-\'\r\n        	     \r\n        	     rm = \'N/A\'\r\n        	     if i[:room]\r\n        	         rm = rooms[i[:room]]\r\n        	     end\r\n    	    \r\n                c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id.to_s}\"),\r\n        	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        	     :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Arrived\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n        	     :visit_type=>visit_type,\r\n        	     :rm=>rm,\r\n        	     :room=>select_tag(\'room\',options_for_select(room_list,rm),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_room(this)\'),\r\n        	     :start=>i[:start].strftime(\'%H:%M\'),\r\n        	     :stop=>((i[:stop].nil? or i[:stop]==\'\') ? \'-\' : i[:stop].strftime(\'%H:%M\')),\r\n        	     :prov=>prov_name,\r\n        	     :note=>i[:note]\r\n                }\r\n                \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info \', :style=>\'width:45px\')\r\n                l_list = []\r\n                sm.each do |k, v|\r\n                    lab = k.to_s.split(\'_\')[0].humanize\r\n                    v_link = link_to(\"<i class=\'splashy-add\'></i> \\\\#{lab}\".html_safe, \r\n                        \"../\\\\#{v}/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/main?date=\\\\#{pdate}\", \r\n                        :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                    if f_ser[k][pat_id]\r\n                        v_link = link_to(\"<i class=\'splashy-document_a4\'></i> \\\\#{lab}\".html_safe, \r\n                            \"../\\\\#{v}/show?id=\\\\#{f_ser[k][pat_id]}&return=../Home/main?date=\\\\#{pdate}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                    end\r\n                    l_list << v_link\r\n                end\r\n                \r\n                # v_link = link_to(\'<i class=\"splashy-add\"></i> Add\'.html_safe, \r\n                #     \"../OutPatientForm/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/index\", \r\n                #     :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                # if f_liv[pat_id]\r\n                #     v_link = link_to(\'<i class=\"splashy-document_a4\"></i> View\'.html_safe, \r\n                #         \"../OutPatientForm/show?id=\\\\#{f_liv[pat_id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                # end\r\n                c[:processing_ctrl]= \"\\\\#{l_list.join(\' \')} \\\\#{d_link}\".html_safe \r\n                \r\n                c\r\n            end\r\n        end\r\n	}.compact!\r\n	\r\n	# room group\r\n	rg = aps.sort_by{|i| [i[:rm],i[:start]]}.group_by{|i| i[:rm]}\r\n\r\n	table_model = %w{room start stop hn patient provider status_ctrl processing_ctrl note }.collect{|i| i.to_sym}\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:room=>\'Room\',:start=>\'Start\',:stop=>\'Stop\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Surgeon\',:procedure=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n	:note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Actions\' }\r\n	\r\n	%>\r\n	\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n<%\r\n    rg.each do |k, aps|\r\n        prov_list = aps.group_by{|i| i[:prov]}.keys\r\n%>\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				ROOM <%= k %>\r\n				<div class=\"pull-right\"><i class=\"\"><%=aps.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n			    <div class=\'span4\'>\r\n			        <div class=\'alert\' style=\'font-size:1.4em;line-height:1.4em\'>\r\n			            <b>Surgeon</b><br/><%= prov_list.join(\'<br/>\').html_safe %>\r\n			        </div>\r\n			    </div>\r\n			    <div class=\'span3 alert\' style=\'font-size:1.4em\'>\r\n			        <b>Room : </b><%= k %>\r\n			    </div>\r\n			    <div class=\'span3\'>\r\n			        <div class=\'alert\' style=\'font-size:1.4em\'>\r\n			            <b>Total patient : </b><%= aps.size %>\r\n			        </div>\r\n			    </div>\r\n			    <div class=\'clear\'></div>\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = aps.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model,:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = aps.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model,:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n              \r\n			</div>\r\n            \r\n		</div> \r\n<% end %>\r\n<%\r\n    if rg.size == 0\r\n%>\r\n        <div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				ROOM N/A\r\n				<div class=\"pull-right\"><i class=\"\">0 Patient</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n			    <div class=\'span10 \' style=\'font-size:1.4em\'>\r\n			        <div class=\'clear\'></div><br/>\r\n			        <center>\r\n			            <!--<div class=\'alert alert-info\'>-->\r\n			                No Patient for today. Please click \r\n			                <a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br>Appointment</button></a>\r\n			                to add Patient for today.\r\n			            <!--</div>-->\r\n			        </center>\r\n			        <div class=\'clear\'></div>  \r\n                   \r\n                \r\n                <br/>\r\n			    </div>\r\n			    <div class=\'clear\'></div><br/>\r\n			</div>\r\n		</div>\r\n<%\r\n    end\r\n%>\r\n	</div>\r\n	<div class=\"clear\"></div>	<br/>\r\n	\r\n	\r\n	<div class=\"clear\"></div>	\r\n	<br/>\r\n</div>',NULL,NULL,NULL,'2016-11-15 14:30:58','2016-11-15 14:30:58','index_partial_bk',''),(2732,'search',1061,2,'<h1> Search Result </h1>\r\n<% \r\n	models = get_model\r\n	\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	\r\n	fields = %w{hn public_id first_name last_name}\r\n	query = \'\'\r\n	if params[:query]\r\n	    query = params[:query].strip\r\n	end\r\n	\r\n	keys = []\r\n	\r\n	keys << {:hn=>Regexp.new(query)}\r\n	keys << {:first_name=>Regexp.new(query)}\r\n	keys << {:last_name=>Regexp.new(query)}\r\n	keys << {:public_id=>query} if query.size==13\r\n	\r\n	criteria = {\'$or\'=>keys}\r\n	\r\n	patients = patient_model.where(criteria).limit(20).all  \r\n	\r\n	app_name = \"\\#{@current_project.name}#appointment\"\r\n	app_model = models[:appointment]\r\n	\r\n\r\n	\r\n	fields.insert(0, \'no\')\r\n	r = 0\r\n%>\r\nResult for \'<%= query %>\' = <%= patients.count %>\r\n<hr/>\r\n<%\r\nif patients.count != 0\r\n%>\r\n<%= tabular :model=>fields,:data=>patients,:n=>10 do |row,out|\r\n	am = module_model.where(:module_name=>\"\\#{app_name}\",:patient_id=>row.id).order(\'date\').last\r\n	r += 1\r\n	if am\r\n        app = app_model.where(:id=>am.module_id).first\r\n	\r\n        if @current_role!=\'pathologist\'\r\n            url = \"../Home/patient_record?id=\\#{am.module_id}\"\r\n        else\r\n            url = \"../Home/patho_patient_record?id=\\#{am.module_id}\"\r\n        end\r\n	\r\n        out[0] = link_to(\"\\#{r}.\", url)\r\n        out[1] = link_to(row.hn,url)\r\n        out[2] = link_to(row.public_id,url)\r\n        out[3] = link_to(row.first_name,url)\r\n        out[4] = link_to(row.last_name,url)\r\n        n = module_model.where(:module_name=>\"\\#{app_name}\",:patient_id=>row.id).count\r\n        	\r\n        extra = link_to(\'Add Visit\', \"../Appointment/create?obj_id=\\#{row.id}&return=../Home/index\", :class=>\'btn btn-mini btn-success\') + \' \' + link_to(\"Detail (\\#{n})\", url, :class=>\'btn btn-mini btn-info\')\r\n        	\r\n        	\r\n        out << extra.html_safe\r\n        \r\n	else\r\n	    out[0] = \"\\#{r}.\"\r\n        out << link_to(\'Add Visit\', \"../Appointment/create?obj_id=\\#{row.id}&return=../Home/index\", :class=>\'btn btn-mini btn-success\')\r\n	end\r\n	\r\n        out\r\nend\r\n	\r\n%>\r\n<%\r\nelse\r\n%>\r\n<h3>No patient found</h3>\r\n<%= link_to \'New patient\', \"../../www/Patient/create?hn=\\#{params[:query]}&return=/\\#{@current_project.name}/Appointment/create?return=../Home/index\", :class=>\'btn btn-info\' %>\r\n<%\r\nend\r\n%>\r\n<hr/>',NULL,NULL,NULL,'2016-11-15 14:37:16','2016-11-15 14:37:16','search',''),(2733,'document_name',1101,1,'\'nurse_time\'',NULL,NULL,NULL,'2016-11-15 15:06:42','2016-11-15 15:06:42',NULL,NULL),(2736,'document_name',1104,1,'\'room_procedure\'',NULL,NULL,NULL,'2016-11-17 03:36:11','2016-11-17 03:36:11',NULL,NULL),(2737,'print',1100,3,'<%= this.print_partial.html_safe %>\r\n<% if @current_role!=\'developer\' %>\r\n<script>\r\n    var millisecondsToWait = 2000;\r\n    setTimeout(function() {\r\n        window.print();\r\n    }, millisecondsToWait);\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2016-11-17 07:14:28','2016-11-17 07:14:28','print',''),(2738,'print_partial',1100,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    \r\n    gender = \'NA\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'Male\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'Female\'\r\n    end\r\n    \r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # check pre-op exist ?\r\n    x_pre_op = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id], :module_name=>\"\\\\#{@current_project.name}#pre_op\").first\r\n    r_pre_op = nil\r\n    if x_pre_op\r\n        r_pre_op = get_model[:pre_op].find(x_pre_op[:module_id])\r\n    end\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    map_ind = {}\r\n    map_ind[\'\']  = \'N/A\'\r\n    map_ind[nil] = \'N/A\'\r\n    model[:indication].all.each do |i|\r\n        map_ind[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    map_room = {}\r\n    map_room[\'\'] = \'N/A\'\r\n    map_room[nil] = \'N/A\'\r\n    model[:room].all.each do |i|\r\n        map_room[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    def get_render_value(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return \'-\'\r\n        else\r\n            return render_value(f.to_s)\r\n        end\r\n    end\r\n    \r\n    def get_value(field)\r\n        f = field.to_sym\r\n 