; float:left; margin-bottom:3px;}\r\n\r\n    .tab { margin-left: 20px; }\r\n    .intro {\r\n        font-weight:bold;\r\n        width : 170px;\r\n        /*display: inline-block;*/\r\n    }\r\n    v {color:#2561cD};\r\n\r\n</style>\r\n<%# stylesheet_link_tag    \"application\"  %>\r\n<script>\r\n    document.title = \"<%= r_pat.hn %> - <%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> - PRINT\"\r\n</script>\r\n<body>\r\n	<div class=\"wrapper\" >\r\n		<div id=\"head\">\r\n<%\r\n    app_logo = @current_project.get_setting(\'logo_report_path\')\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n			<div id=\"logoleft\" ><a href=\"../Home/index\"><img src=\'<%=app_logo%>\' height=\"80px\" style=\"float:left;margin-top:15px;margin-right:20px\" /></a></div>\r\n			<div style=\'float:left\'>\r\n			    <span style=\"margin-top: 30px;display: block;font-size: 2em;font-weight: bold;margin-left: 20px;text-align:center\"> \r\n			    \r\n			    <%= @current_project.get_setting(\'report_title_1\') %><br/><br/>\r\n			    <div style=\'font-size:0.7em\'>แบบฟอร์มการนัดผ่าตัด</div>\r\n			        \r\n			    </span>\r\n			    <br/>\r\n			</div>\r\n			\r\n		</div>\r\n		<br />\r\n		<div id=\"page\" style=\'min-height:960px\'>\r\n		<!-- Title Section -->\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\" style=\'font-size:1.4em;line-height:1.4em\'>\r\n				<tr>\r\n					<td > \r\n						<table width=\"100%\">\r\n							<tr>\r\n							    <td width=\'65%\' style=\'vertical-align:top\'>\r\n<%\r\n    vis_base = get_render_value(:visit_base)\r\n    vis_txt  = \'\'\r\n    if vis_base == \'OPD\'\r\n        vis_txt = \"<span class=\'intro\'>Clinic :</span> \\\\#{get_render_value(:clinic)}\".html_safe\r\n    elsif vis_base == \'IPD\'\r\n        vis_txt = \"<span class=\'intro\'>Ward :</span> \\\\#{get_render_value(:ward)}\".html_safe\r\n    end\r\n%>\r\n							        <span class=\'intro\'>Visit base : </span><%= get_render_value(:visit_base) %> / <%= vis_txt %> <br/>\r\n							        <span class=\'intro\'>ประเภทการผ่าตัด : </span><%= get_render_value(:visit_type) %> <br/>\r\n							        <span class=\'intro\'>วันที่ผ่าตัด / เวลา : </span><br/>\r\n							        <span class=\'tab\'></span>\r\n							        <%= get_render_value(:date) %> / <%= get_render_value(:start) %> ~ <%= get_render_value(:stop) %> (OR: <%= map_room[get_value(:room)] %>) <br/>\r\n							        \r\n								</td>\r\n								<td style=\'vertical-align:top\'>\r\n									<span class=\'intro\'>HN : </span><%=r_pat.hn%> <br/>\r\n									<span class=\' intro\'>ชื่อ - สกุล : </span><%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> <br/>\r\n									<span class=\' intro\'> อายุ : </span> <%= age %> yr  \r\n									<span class=\'tab intro\'>เพศ : </span><%= gender %>\r\n								</td>\r\n							</tr>\r\n							<!--<tr>-->\r\n							<!--    <td colspan=\'2\'>&nbsp;</td>-->\r\n							<!--</tr>-->\r\n						</table>\r\n						\r\n			<hr style=\"margin-top: 5px;padding:10px\"/>\r\n						<table width=\'100%\'  cellpadding=\"5\" cellspacing=\"5\">\r\n							<!--\r\n							<tr>\r\n							    <td  style=\'background:#ccc;padding:10px;font-size:1.5em\'>\r\n							    \r\n							    </td>\r\n							</tr>\r\n							-->\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n\r\n			<div style=\"display:block;font-size:1.4em;line-height:1.4em\">\r\n			<!-- Main Content -->\r\n				<table width=\"60%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left;\">\r\n							<tr>\r\n							    <td >\r\n							        <span class=\'intro\'>Diagnosis : </span> <br/>\r\n							        <span class=\'tab\'>1. <%= get_render_value(:diagnosis_1) %></span> <br/>\r\n							        <% if is_exist(:diagnosis_2) %>\r\n							        <span class=\'tab\'>2. <%= get_render_value(:diagnosis_2) %></span> <br/>\r\n							        <% end %>\r\n							    </td>\r\n							</tr>\r\n							<tr>\r\n							