\n							    <td width=\'60%\' style=\'text-align:center\'>\r\n							        ลงชื่อ ......................................<br/>\r\n							         (<%= get_render_value(:assistant) %>)\r\n							    </td>\r\n							</tr>\r\n<% if is_exist(:spacial_cost) %>\r\n							<tr>\r\n							    <td colspan=\'2\' style=\'background:#ccc;padding:10px;font-size:1em;color:darkred\'>\r\n							        ส่งปรึกษาฝ่ายลูกค้าสัมพันธ์เรื่องค่าใช้จ่ายอุปกรณ์/เครื่องมือพิเศษ.................ที่เบิกไม่ได้ \r\n							        <br/>\r\n							        <span class=\'tab\'></span>\r\n							        ราคาโดยประมาณ \r\n							        <%= get_render_value(:estimate_cost) %>\r\n							        บาท\r\n							    </td>\r\n							</tr>\r\n							<tr style=\'background:#ccc;padding:10px;font-size:1em;color:darkred\'>\r\n							    <td  >\r\n							        <span class=\'tab\'></span><span class=\'tab\'></span>พยาบาลผู้ส่งปรึกษา\r\n							    </td>\r\n							    <td width=\'60%\' style=\'text-align:center\'>\r\n							        ลงชื่อ ......................................<br/>\r\n							         (<%= get_render_value(:consult_nurse) %>)\r\n							    </td>\r\n							</tr>\r\n<% end %>\r\n							\r\n                </table>\r\n\r\n\r\n				\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n\r\n		<!-- Footer -->\r\n		<!--\r\n		<div id=\"page\" style=\"height:60px;padding-top: 5px;\">\r\n			<strong>Colposcopist name : </strong> <%= \'colpo_name\' %> \r\n			<br/>\r\n			<br/>\r\n			<strong>Colposcopist signature : </strong> ........................................................\r\n			<br />\r\n		</div>\r\n		-->\r\n		<div class=\"clear\"></div>\r\n	</div>\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-11-17 07:27:47','2016-11-17 07:27:47','print_partial',''),(2739,'print_template',1100,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    \r\n    gender = \'NA\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'Male\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'Female\'\r\n    end\r\n    \r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  r_pat[:birth_date].day) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # check pre-op exist ?\r\n    x_pre_op = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id], :module_name=>\"\\#{@current_project.name}#pre_op\").first\r\n    r_pre_op = nil\r\n    if x_pre_op\r\n        r_pre_op = get_model[:pre_op].find(x_pre_op[:module_id])\r\n    end\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    map_ind = {}\r\n    map_ind[\'\']  = \'N/A\'\r\n    map_ind[nil] = \'N/A\'\r\n    model[:indication].all.each do |i|\r\n        map_ind[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    def get_render_value(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return \'-\'\r\n        else\r\n            return render_value(f.to_s)\r\n        end\r\n    end\r\n    \r\n    def get_value(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return \'-\'\r\n        else\r\n            return @record[f]\r\n        end\r\n    end\r\n    \r\n    def is_exist(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return false\r\n        else\r\n            return true\r\n        end\r\n    end\r\n    \r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        res[:render] = render_value(\'asa_status\')\r\n        # res[:this_document] = this_doc\r\n        # res[:this_model] = this_mod.find(r_pat_mod[:module_id])\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:85px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px; line-height:20px;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {\r\n    /*color:#666;*/\r\n    line-height:12px;\r\n}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; margin-left:70px; margin-right:10px; }\r\n /* blockquote, */\r\n /*.wrapper{ width:960px;margin-left:auto;margin-right:auto;} */\r\n body {-webkit-print-color-adjust: exact;}\r\n}\r\n\r\n#box{\r\n    width:300px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:250px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    height:225px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n    .tab { margin-left: 20px; }\r\n    .intro {\r\n        font-weight:bold;\r\n        width : 170px;\r\n        /*display: inline-block;*/\r\n    }\r\n    v {color:#2561cD};\r\n\r\n</style>\r\n<%# stylesheet_link_tag    \"application\"  %>\r\n<script>\r\n    document.title = \"<%= r_pat.hn %> - <%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> - PRINT\"\r\n</script>\r\n<body>\r\n	<div class=\"wrapper\" >\r\n		<div id=\"head\">\r\n<%\r\n    app_logo = @current_project.get_setting(\'logo_report_path\')\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n			<div id=\"logoleft\" ><a href=\"../Home/index\"><img src=\'<%=app_logo%>\' height=\"80px\" style=\"float:left;margin-top:15px;margin-right:20px\" /></a></div>\r\n			<div style=\'float:left\'>\r\n			    <span style=\"margin-top: 30px;display: block;font-size: 2em;font-weight: bold;margin-left: 20px;text-align:center\"> \r\n			    \r\n			    <%= @current_project.get_setting(\'report_title_1\') %><br/><br/>\r\n			    <div style=\'font-size:0.7em\'>แบบฟอร์มการนัดผ่าตัด</div>\r\n			        \r\n			    </span>\r\n			    <br/>\r\n			</div>\r\n			\r\n		</div>\r\n		<br />\r\n		<div id=\"page\" style=\'min-height:960px\'>\r\n		<!-- Title Section -->\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n				<tr>\r\n					<td > \r\n						<table width=\"100%\">\r\n							<tr>\r\n							    <td width=\'65%\' style=\'vertical-align:top\'>\r\n							        <br/>\r\n								</td>\r\n								<td style=\'vertical-align:top\'>\r\n									<span class=\'intro\'>HN : </span><%=r_pat.hn%> <br/>\r\n									<span class=\' intro\'>Name : </span><%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> <br/>\r\n									<span class=\' intro\'> Age : </span> <%= age %> yr  \r\n									<span class=\'tab intro\'>Gender : </span><%= gender %>\r\n								</td>\r\n							</tr>\r\n							<!--<tr>-->\r\n							<!--    <td colspan=\'2\'>&nbsp;</td>-->\r\n							<!--</tr>-->\r\n						</table>\r\n						\r\n			<hr style=\"margin-top: 5px;\"/>\r\n						<table width=\'100%\'>\r\n							<tr>\r\n							    <td colspan=\'2\'>&nbsp;</td>\r\n							</tr>\r\n							<tr>\r\n							    <td colspan=\'2\'>\r\n							    \r\n							    </td>\r\n							</tr>\r\n							<tr>\r\n							    <td colspan=\'2\' style=\'background:#ccc;padding:10px;font-size:1.5em\'>\r\n							    \r\n							    </td>\r\n							</tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n\r\n			<div style=\"display:block;\">\r\n			<!-- Main Content -->\r\n				<table width=\"60%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left;\">\r\n				    <tr>\r\n				        <td valign=\'top\'>\r\n				        \r\n				        </td>\r\n				    </tr>\r\n							<tr>\r\n							    <td>\r\n							   \r\n					            </td>\r\n							</tr>\r\n\r\n                </table>\r\n\r\n\r\n				\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n\r\n		<!-- Footer -->\r\n		<div id=\"page\" style=\"height:60px;padding-top: 5px;\">\r\n			<strong>Colposcopist name : </strong> <%= \'colpo_name\' %> \r\n			<br/>\r\n			<br/>\r\n			<strong>Colposcopist signature : </strong> ........................................................\r\n			<br />\r\n		</div>\r\n		<div class=\"clear\"></div>\r\n	</div>\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-11-17 07:40:57','2016-11-17 07:40:57','print_template',''),(2740,'show',1105,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n<%\r\n\r\n   @document =  get_document this.document_name \r\n   \r\n   model = get_model(this.table_name)\r\n   @patient_module = @module_model.find(params[:id])\r\n   record = model.find(@patient_module.module_id)\r\n   @record = record    \r\n  if request.post?\r\n    \r\n   \r\n    if p = params[\'cancel_\']\r\n        \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            old_app.destroy\r\n            mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>nil\r\n   \r\n    elsif p = params[\'postpone_\']\r\n    \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            # old_app.destroy\r\n            # mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        \r\n        \r\n        new_app = record.clone\r\n        new_app.update_attributes :date=>p[0][\'postpone_to\'],:status=>\'Appointed\'\r\n        \r\n        mm = @patient_module.clone\r\n        mm.module_id = new_app.id \r\n        mm.save    \r\n        \r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>p[0][\'postpone_to\'], :postpone_id=>new_app.id\r\n       \r\n        \r\n        \r\n    end\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Home/index\" />\r\n<% end %>\r\n<%= this.display.html_safe %>\r\n\r\n<div id=\"cancel\" style=\"display:none\"  class=\"alert alert-warning\">\r\n   <p>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'cancel_\'\r\n        field = @document.find_by_column_name \'cancel_reason\'\r\n        begin\r\n        %>\r\n        \r\n        <%#field%>\r\n        <div>\r\n        \r\n        <h3>Cancel</h3><br/>\r\n        <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Cancelled\' %>\r\n        </div>\r\n        <script>\r\n        <%= yield :script %>\r\n        \r\n      \r\n        </script>\r\n        <% rescue Exception=>e %>\r\n        <%=e.message%>\r\n        <% end%>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n</div>\r\n\r\n<div id=\"postpone\" style=\"display:none;padding:10px\" class=\"alert alert-warning\">\r\n   \r\n      <p>\r\n        <h3>Postpone</h3><br/>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'postpone_\'\r\n        %>\r\n        <div>\r\n        \r\n       <% field = @document.find_by_column_name \'cancel_reason\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n       <% field = @document.find_by_column_name \'postpone_to\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Postpone\' %>\r\n        </div>\r\n       \r\n       \r\n        <script>\r\n        <%= yield :script %>\r\n        </script>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n   \r\n   \r\n</div>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Cancel\'.html_safe, \"javascript:cancel()\",:class=>bt_class %> | \r\n<%= link_to \'Postpone\'.html_safe, \"javascript:postpone()\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n\r\n<%= link_to \'Details\', \"../Home/patient_record?id=\\\\#{record.id}\", :class=>\'btn btn-info\', :style=>\'float:right\' %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    \r\n    function cancel(){\r\n        $(\'#postpone\').hide()\r\n        $(\'#cancel\').slideDown()\r\n        $(\'#cancel_cancel_reason\').show()\r\n        \r\n    }\r\n    \r\n    function postpone(){\r\n        $(\'#cancel\').hide()\r\n        $(\'#postpone\').slideDown()\r\n        $(\'#postpone_postpone_to\').show()\r\n\r\n    }\r\n    \r\n    function cancel_ctrl(){\r\n        $(\'#postpone\').slideUp()\r\n        $(\'#cancel\').slideUp()\r\n    }\r\n    $(\'.ctrl\').hide();\r\n</script>',NULL,NULL,NULL,'2016-11-21 06:41:55','2016-11-21 06:41:55','show',''),(2741,'room_index_old',1061,2,'<%\r\n	module_name = @current_project.name\r\n	\r\n	if params[:room]\r\n	    session[:room] = params[:room]\r\n	end\r\n	if params[:status]\r\n	    session[:status] = params[:status]\r\n	end\r\n	\r\n	cur_status = session[:status].nil? ? \'\' : session[:status]\r\n	cur_room   = session[:room].nil? ? \'N/A\' : session[:room]\r\n	\r\n%>\r\n<%= render :inline=>this.params_config %>\r\n<%= render :inline=>this.common_query %>\r\n<%\r\n    date = @date\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center>\r\n				    <b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b>\r\n                </center>\r\n				<br/>\r\n				<center>\r\n<%\r\n    @rs_room_list.each do |i|\r\n%> \r\n                    <a href=\"<%= params[:opt] %>?room=<%= i.html_safe %>\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-home_green\"></i><br />Room <b><%= i %></b>\r\n                        <br />HN:1123/58<br />Supasak</button>\r\n                    </a>\r\n<%\r\n    end\r\n%>\r\n				<!--\r\n					<a href=\"#\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />ROOM 1<br />HN:1123/58<br />Supasak</button></a>\r\n                    <a href=\"#\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />ROOM 2<br />HN:1123/58<br />Supasak</button></a>\r\n                    <a href=\"#\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />ROOM 3<br />HN:1123/58<br />Supasak</button></a>\r\n                    <a href=\"#\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />ROOM 4<br />HN:1123/58<br />Supasak</button></a>\r\n                    <a href=\"#\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />ROOM 5<br />HN:1123/58<br />Supasak</button></a>\r\n                    <a href=\"#\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />ROOM 6<br />HN:1123/58<br />Supasak</button></a>\r\n                -->\r\n                    \r\n					<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n						\r\n					<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Calendar</button></a>\r\n					<a href=\"../Home/report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n					<a href=\"room_index?date=<%= params[:date] %>\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-folder_modernist_opened\"></i><br />Room</button></a>-->\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n\r\n    <div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\">\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %>\r\n					<h1 id=\"clock\"><%= Time.now.strftime(\'%H:%M\') %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n    \r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n%>\r\n\r\n\r\n<% if false %>\r\n<%\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed waiting arrived preparing processing recovery completed discharge cancelled no_show}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	list = aps.clone\r\n	id = \'\'\r\n	aps.collect!{|i| \r\n	id = i.id\r\n	  if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n	     patient = patient_model.find(m.patient_id)\r\n	     if patient \r\n	     provider = p_model.find(i.provider)\r\n	     visit_type = visits[i.visit_type]\r\n	     provider_name = \'-\'\r\n	     provider_name = provider.name if provider\r\n	     procedure_name = \'-\'\r\n	     pro = models[:procedure].find(i.procedure) \r\n	     procedure_name = pro.name if pro\r\n	     patient = patient_model.new unless patient \r\n	     hn = \'-\'\r\n	     hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n	     public_id = \'-\'\r\n	    # public_id = patient.public_id if patient\r\n	    # change to use update queue number\r\n	    #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n	    #  :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	    #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	    #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n	    #  :visit_type=>visit_type\r\n	    #  }\r\n	    n_txt = []\r\n	    if !i[:qn].nil?\r\n	        n_txt << \"Q:\\\\#{i[:qn]}\"\r\n	    end\r\n	    if i.note != \'\'\r\n	        n_txt << i.note\r\n	    end\r\n	    d_qn = \"...\"\r\n	    d_qn = \"..\\\\#{patient[:hn].tr(\'/\',\'\')[-5..-3]}/\\\\#{patient[:hn].tr(\'/\',\'\')[-2..-1]}\" if patient and  patient[:hn]\r\n	    \r\n	    c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	     :pending_ctrl=>link_to(\'Arrived\',\"javascript:patient_q(\'\\\\#{i.id}\',\'\\\\#{d_qn}\');\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n	     :visit_type=>visit_type,\r\n	     :note=>n_txt.join(\' / \')\r\n	    }\r\n	     \r\n	    if i.status==\'Waiting\' or i.status==\'Arrived\' or i.status==\'Preparing\'\r\n	        c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    \r\n	\r\n	    #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    else\r\n	        status = \'btn-info\'\r\n	        status = \'\' if i.status ==\'Completed\' or \'Discharge\'\r\n	        c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n	    end\r\n	     c\r\n	    end\r\n	  end\r\n	}.compact!\r\n	\r\n	waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\' or i[:status]==\'Arrived\' or i[:status]==\'Preparing\'}.compact\r\n	\r\n	processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n	\r\n	completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' or i[:status]==\'Discharge\' }.compact\r\n	\r\n	cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n	\r\n	table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n	:note=>\'Note\',:visit_type=>\'Group\' }\r\n	\r\n	%>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				ROOM 1 (Active)\r\n				<div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in processing\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Processing \r\n				<div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in completed\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Completed \r\n				<div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in cancelling\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Cancelled &amp; No show \r\n				<div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<!--\r\n		<div class=\"left\" style=\"width:50%\">\r\n		   <div class=\"w-box\" id=\"w_sort05\">    \r\n		        <div class=\"w-box-header\">\r\n		            Today Patients\r\n			    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n			    </div>\r\n			    <div class=\"w-box-content cnt_a\">\r\n			        content\r\n		        </div>\r\n		    </div>\r\n		</div>\r\n		-->\r\n</div>\r\n<% end %>\r\n<br/>\r\n<br/>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:320px;left:50%;margin-left:-360px\">\r\n	<div class=\"modal-header\">\r\n		<a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n		<h3>Patient Queue</h3>\r\n	</div>\r\n	<div class=\"modal-body\">\r\n		<form name=\'q\' method=\'post\'>\r\n			<span style=\'width:80px\'>Queue Number : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"qn\" id=\'qn\' style=\"width:50px\"/>\r\n			</span>\r\n			<input type=\"hidden\" name=\"app_id\" id=\"app_id\" value=\"\">\r\n			<input type=\"hidden\" name=\"app_status\" id=\"app_status\" value=\"Arrived\">\r\n			<div class=\"clear\"></div>\r\n			<input type=\"submit\" name=\"Submit\" value=\"Submit\" class=\"btn btn-success\"/>\r\n		</form>\r\n	</div>\r\n</div>\r\n<script>\r\n	function patient_q(app_id) {\r\n	    console.log(\"appointment id : \" + app_id);\r\n	    $(\'#app_id\').val(app_id);\r\n	    $(\'#modal\').modal({\r\n	        show: true, \r\n	        backdrop: \'static\',\r\n	        keyboard: true\r\n	    });\r\n	}\r\n	function patient_q(app_id, qn) {\r\n	    console.log(\"appointment id : \" + app_id);\r\n	    $(\'#qn\').val(qn);\r\n	    $(\'#app_id\').val(app_id);\r\n	    $(\'#modal\').modal({\r\n	        show: true, \r\n	        backdrop: \'static\',\r\n	        keyboard: true\r\n	    });\r\n	}\r\n</script>\r\n\r\n<script>\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'index_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        setTimeout(feed_page(100), 0);\r\n        loadPartial();\r\n    });\r\n    \r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Summary\',\'patient_summary?date=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Nurse Index\',\'nurse_index?date=\'+params[:date] %> |\r\n<!--<%= link_to \'Case 