= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n<% if @appointment[:provider] %>\r\n    $(\'#data-endoscopist_1\').val(\'<%= @appointment[:provider] %>\');\r\n<% end %>\r\n</script>   \r\n',NULL,NULL,NULL,'2016-11-22 05:31:18','2016-11-22 05:31:18','create',''),(2748,'transfer',262,2,'<%\r\n    emr = @context.get_projects_by_abstract(\'ehr.emr\')\r\n\r\n    res = {}\r\n    emr_list = emr.collect{|i| i[:name] if i[:name] != @current_project.name}.compact\r\n    \r\n    list = [\"\"]\r\n    list = list + emr_list\r\n    \r\n    model = nil\r\n    \r\n    if request.post?\r\n        res[:post] = params\r\n        \r\n        if proj = params[:record][:project]\r\n            \r\n            emr.each do |i|\r\n                if i[:name] == proj\r\n                    model = i\r\n                end\r\n            end\r\n            res[:prov] = model.get_model[:provider].all\r\n            res[:name] = proj\r\n        end\r\n    end\r\n%>\r\n\r\n<%= form_for :record,:url=>url(params[:opt]) do |f| %>\r\n\r\n    Import provider from application : \r\n    <%= f.select :project, options_for_select(list) %>&nbsp;&nbsp;&nbsp;&nbsp;\r\n    <%= f.submit \"Submit\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Processing ...\', :style=>\'margin-top:-10px\' %> \r\n\r\n\r\n<% end %>\r\n\r\n<%# res.to_json.html_safe %>\r\n\r\n<%\r\n    if model\r\n        \r\n        key_prov = {}\r\n        \r\n        mod_prov = get_model[:provider]\r\n        ext_prov = mod_prov.all\r\n        cur_prov = get_model[:provider].all\r\n        cur_prov.each do |i|\r\n            key_prov[i[:name]] = i\r\n        end\r\n        cre_list = []\r\n        res[:key] = key_prov\r\n        res[:cur] = cur_prov\r\n        res[:ext] = ext_prov\r\n        ext_prov.each do |i|\r\n            \r\n            if key_prov.has_key? i[:name].to_s\r\n%>\r\n<%= i[:name] %> is exists! <br/>\r\n<%\r\n            else\r\n                cre_list << i\r\n                mod_prov.create i.attributes\r\n%>\r\n<%= i[:name] %> is created! <br/>\r\n<% \r\n            end\r\n        end\r\n    end \r\n%>\r\n',NULL,NULL,NULL,'2016-11-22 05:36:04','2016-11-22 05:36:04','transfer',''),(2749,'create',262,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  record = nil\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    \r\n    name = params[:record][:name]\r\n    prov = get_model[:provider].where(:name=>name).first\r\n    if prov\r\n        record = prov\r\n        flash[:notice]=\"Provider \'\\\\#{name}\' exist.\"\r\n    else\r\n        record = doc.record_create(model,params)\r\n        flash[:notice]=\'New record has been created\'\r\n    end\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<br/>\r\n<h3><%= flash[:notice] %></h3>\r\n<br/>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-11-22 06:36:46','2016-11-22 06:36:46','create','');
INSERT INTO `esm_operations` VALUES (2750,'edit',262,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = nil\r\n    name = params[:record][:name]\r\n    prov = get_model[:provider].where(:name=>name).first\r\n    if prov\r\n        record = prov\r\n        record = doc.record_update(model,params,record)\r\n        flash[:notice]=\"Provider \'\\\\#{name}\' exist.\"\r\n    else\r\n        record = doc.record_update(model,params,record)\r\n        flash[:notice]=\'Record has been updated\'\r\n    end\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=record.id%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-11-23 03:05:41','2016-11-23 03:05:41','edit',''),(2751,'print',1027,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n	# id of operative note\r\n	\r\n	models  = @models\r\n	pm = @module_model.find(params[:id])\r\n	colono_id = pm.module_id\r\n	record = models[:ve_record].find(colono_id)\r\n	@record = record\r\n	@document = get_document this.document_name\r\n	\r\n	\r\n	def get_render_value(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return \'-\'\r\n	    else\r\n	        return render_value(f.to_s)\r\n	    end\r\n	end\r\n	\r\n	def get_value(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return \'-\'\r\n	    else\r\n	        return @record[f]\r\n	    end\r\n	end\r\n	\r\n	def is_exist(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return false\r\n	    else\r\n	        return true\r\n	    end\r\n	end\r\n	\r\n	\r\n	endoscopist_1 = render_value(\'surgeon_1\')\r\n	endoscopist_2 = render_value(\'endoscopist_2\')\r\n	\r\n	if @patient \r\n	    patient = @patient\r\n	    date = pm.created_at.to_datetime\r\n	    birth_date = patient.birth_date \r\n	    year = month = day = \'0\'\r\n	    if date and birth_date\r\n	        t = date-birth_date    \r\n	        year = (t/365).to_i\r\n	        t%=365\r\n	        month = (t/30).to_i\r\n	        t%=30\r\n	        day = t.to_i\r\n	    end\r\n	end \r\n%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>PRINT</title>\r\n	</head>\r\n	<style type=\"text/css\" media=\"all\">\r\n		html { }\r\n		#page {border:solid 0px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n		#head { width:100%; height:140px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-size: 1.5em; margin: .83em 0 }\r\n		h3              { font-size: 1.17em; margin: 1em 0 }\r\n		p {color:#666;}\r\n		h4, p,\r\n		blockquote, ul,\r\n		form,\r\n		ol, dl          { margin: 0.5em; }\r\n		h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n		h6              { font-size: .67em; margin: 2.33em 0 }\r\n		h4 { font-size:14pt; color:#333; height:16px;}\r\n		blockquote      { margin-left: 40px; margin-right: 40px }\r\n		i, cite, em,\r\n		var, address    { font-style: italic }\r\n		pre, tt, code,\r\n		kbd, samp       {  font-size:14px; }\r\n		pre             {margin:0;margin-left:1em; color:#666}\r\n		big             { font-size: 1.17em }\r\n		v {color:#2561cD;}\r\n		small, sub, sup { font-size: .83em }\r\n		ol, ul, dd      { margin-left: 40px }\r\n		ol              { list-style-type: decimal }\r\n		ol ul, ul ol,\r\n		ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n		.clear{clear:both;}\r\n		@media print {\r\n		@page         { width:960px; margin-top:0; }\r\n		blockquote, \r\n		.wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n		}\r\n		#box{\r\n		width:215px;\r\n		float:left;\r\n		padding:0px;\r\n		text-align:center;\r\n		border:1px solid #ccc;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */    \r\n		margin:5px;\r\n		font-size:0.8em;\r\n		height:170px;\r\n		overflow:hidden;\r\n		}\r\n		.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n		#box img{\r\n		height:170px; margin-left:-50px;\r\n		}\r\n		label{\r\n		color:#666;\r\n		}\r\n		.sidationcss\r\n		{width:160px; float:left; margin-bottom:3px;}\r\n	</style>\r\n	<body>\r\n		<div class=\"wrapper\">\r\n			<div id=\"head\" class=\"well\">\r\n				<div id=\"logoleft\" style=\"width:600px; float:left\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n					<br />\r\n					First Name : \r\n					<v><%= patient.prefix_name %> <%= patient.first_name %></v>\r\n					<br />\r\n					Last Name : \r\n					<v><%= patient.last_name %></v>\r\n					<br />\r\n					HN :&nbsp;\r\n					<v><%=patient.hn%></v>\r\n					<br />\r\n					Age :&nbsp;\r\n					<v><%= year%> Year <%=month%> Month <%= day%> Day </v>\r\n					<br />\r\n					Gender :&nbsp;\r\n					<v><%=patient.gender%></v>\r\n					<br />\r\n					Date :&nbsp;\r\n					<v></v>\r\n					<br />\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now %></p>\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n			</div>\r\n			<div id=\"page\">\r\n			  <div class=\"clear\"></div>\r\n                \r\n                  <%\r\n        # atts = models[:attachment].find(record.images)\r\n        # atts = record.images[0..5].compact.collect{|i| models[:attachment].find(i)}\r\n   \r\n       atts_list = record.images[0..5]\r\n       if record[:selected_image] and record.selected_image and record.selected_image.size > 0\r\n          \r\n           atts_list = record.selected_image[0..5]\r\n           \r\n       end\r\n       \r\n       \r\n       atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n\r\n    %>\r\n\r\n    <div style=\"float:right;  width: 280px;  padding: 1px; text-align:center; font-size:14px;\">\r\n    <% for i in atts  %>\r\n    <img alt=\"1\" src=\"<%=i.path%>?thumb=2\" style=\"margin:2px\"/><br /><%=i.title%><br />\r\n    <% end %>\r\n    </div>\r\n				<!--      -->\r\n  <div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:600px;margin:0px;min-height:50px; float:left\" >\r\n					<div id=\"622-F1252719607\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background-color:#dff0d8;\r\n						padding:5px;\">\r\n						<b>Information</b>\r\n					</div>\r\n					<div id=\"date\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n						<span class=\"\"><label>Date : </label></span>	\r\n						<v><%=render_value \'date\'%></v>\r\n					</div>\r\n<div id=\"tracheotomy\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n						<span class=\"\"><label>Tracheotomy : </label></span>	\r\n						<v><%=render_value \'tracheotomy\'%>\r\n                       <% if record[\'tube_feeding\']==\'true\'%>Tube feeding :<v><%=render_value \'tube_feeding\'%> <%=render_value \'tube_side\'%></v><% end%>\r\n                       \r\n                        \r\n	  </div>\r\n					<div id=\"peg\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n						<span class=\"\"><label>PEG : </label></span>	\r\n						<v><%=render_value \'peg\'%></v>\r\n					</div>\r\n					<div id=\"consciousness\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n						<span class=\"\"><label>Consciousness : </label></span>	\r\n						<v><%=render_value \'consciousness\'%></v>\r\n					</div>\r\n					<div id=\"spo2\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n						<span class=\"\"><label>SpO2 : </label></span>	\r\n						<v><%=render_value \'spo2\'%></v>\r\n					</div>\r\n					<div id=\"surgeon_1\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n						<span class=\"\"><label>Operator : </label></span>	\r\n						<%=endoscopist_1%>\r\n					</div>\r\n					<div id=\"note\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px\">\r\n						<span class=\"\"><label>Note : </label></span>	\r\n						<v><%=render_value \'note\'%></v>\r\n					</div>\r\n					<div id=\"622-F1982932315\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n						<b>Evaluation of Structure/function</b>\r\n					</div>\r\n<div id=\"oral_cavity_hygiene\" class=\"  portlet \" style=\"border:0px solid blue;width:600px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n					<b style=\"width:90px; float:left\">Oral cavity : </b>\r\n		<div style=\"width:140px; float:left\"><label>Hygiene : </label><v><%=render_value \'oral_cavity_hygiene\'%></v></div>\r\n                         <div style=\"width:180px; float:left\"><label>Motion :</label><v><%=render_value \'oral_cavity_motion\'%></v></div>\r\n                         <div style=\"width:180px; float:left\"><label>Laterality :</label><v><%=render_value \'oral_cavity_laterality\'%></v></div>\r\n                         <div style=\"width:180px; float:left\"><label>Side of palsy :</label><v><%=render_value \'oral_cavity_side\'%></v></div>\r\n	  </div>\r\n                  \r\n	  <div id=\"tongue_type\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px\">\r\n						\r\n                        <div style=\"width:270px; float:left\"><span class=\"\"><b>Tongue : </b></span>	\r\n						<v><%=render_value \'tongue_type\'%></v></div>\r\n                        <div style=\"width:180px; float:left\"><span class=\"\"><label>Motion : </label></span>	\r\n						<v><%=render_value \'tongue_motion\'%></v></div>\r\n                        <div style=\"wi