r\n						<span class=\"\"><label>Next evaluation: after :</label></span>	\r\n\r\n                        <v><%=render_value \'next_evaluation_after\'%></v>\r\n                      \r\n					</div>\r\n                    <div id=\"remark\" class=\"  portlet \" style=\"border:0px solid blue;width:600px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n						<span class=\"\"><label>Remark : </label></span>	\r\n\r\n                        <v><%=render_value \'remark\'%></v>\r\n                      \r\n					</div>\r\n					\r\n					<div class=\"clear\">	</div>\r\n                    \r\n		  \r\n				<!--    -->\r\n                </div>\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n         \r\n			\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n	</body>\r\n</html>',NULL,NULL,NULL,'2016-11-23 07:25:24','2016-11-23 07:25:24','print',''),(2752,'document_name',1117,1,'\'medi_vital\'',NULL,NULL,NULL,'2016-11-24 06:18:19','2016-11-24 06:18:19',NULL,NULL),(2755,'create',1045,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n\r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n        @appointment.update_attributes :status=>\'Recovery\'\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n    	$(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2016-11-25 05:04:32','2016-11-25 05:04:32','create',''),(2756,'display',1045,3,'<style>\r\n.red{color:red}\r\n</style>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  models = get_model\r\n  \r\n  @patient_module = @module_model.find(params[:id])\r\n  record = (models[this.table_name.to_sym]).find(@patient_module.module_id)\r\n  @show=true\r\n  \r\n%>\r\n<%  @appointment_module = @module_model.find(@patient_module.parent_id)\r\n\r\n  if @appointment_module\r\n   module_name = @current_project.name+\'#\'+ \'pre_scope\' \r\n   @pre_scope_module = @module_model.first(:parent_id=>@patient_module.parent_id,:module_name=>module_name)\r\n   \r\n   if @pre_scope_module\r\n   \r\n   @pre_scope = (models[:pre_scope]).find(@pre_scope_module.module_id)\r\n\r\n%><% end %>\r\n<% end %>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<% if @pre_scope %>\r\n<div style=\"border:1px solid gray;color:gray;padding:10px\">\r\n    Pre scope : \r\n    BP = <span class=\"red\"><%=@pre_scope.bp%>/<%=@pre_scope.di%></span> mmHg,\r\n    PR = <span class=\"red\"><%=@pre_scope.pr%></span>,\r\n    RR = <span class=\"red\"><%=@pre_scope.rr%></span>,\r\n    O2sat = <span class=\"red\"><%=@pre_scope.o2sat%></span>\r\n    \r\n    <span class=\"right\"><%= @pre_scope.created_at %></span>\r\n</div>\r\n<% end %>\r\n\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<% if @pre_scope and (@pre_scope.bp==nil or @pre_scope.bp==nil or  @pre_scope.di==nil or  @pre_scope.pr==nil or  @pre_scope.rr==nil ) %>\r\n<div style=\"border:1px solid red;color:red;margin:10px\">No vital sign for prescope !! </div>\r\n<% end %>\r\n\r\n\r\n<script>\r\n\r\nfunction getScore(name){\r\n    v = $(\"#data-\"+name);\r\n    if(v.val()){\r\n        return parseInt(v.val());\r\n    }\r\n    return 0;\r\n}\r\n\r\nfunction refresh_point(){\r\n           \r\n    score = 0 ;\r\n    \r\n    bp_std = 100;\r\n    di_std = 100;\r\n    hr_std = 100;\r\n    rr_std = 100;\r\n    \r\n    <% if @pre_scope %>\r\n    \r\n    bp_std = <%=@pre_scope.bp%>;\r\n    di_std = <%=@pre_scope.di%>;\r\n    hr_std = <%=@pre_scope.pr%>;\r\n    rr_std = <%=@pre_scope.rr%>;\r\n    \r\n    <% end %>\r\n    \r\n    ts = 2;\r\n    \r\n    v = Math.abs((1.0*bp_std-getScore(\"bp\"))/bp_std);\r\n  \r\n    \r\n    if(v<.2)s=2;\r\n    else\r\n        if(v<.4)s=1;\r\n          else s=0;\r\n    if(s<ts)ts = s;    \r\n        \r\n    v = Math.abs((1.0*di_std-getScore(\"diastolic\"))/di_std);\r\n    \r\n    \r\n    if(v<.2)s=2;\r\n    else\r\n        if(v<.4)s=1;\r\n          else s=0;\r\n    if(s<ts)ts = s; \r\n    \r\n    v = Math.abs((1.0*hr_std-getScore(\"pr\"))/hr_std);\r\n   \r\n    \r\n    if(v<.2)s=2;\r\n    else\r\n        if(v<.4)s=1;\r\n          else s=0;\r\n    if(s<ts)ts = s; \r\n\r\n    v = Math.abs((1.0*rr_std-getScore(\"rr\"))/rr_std);\r\n    \r\n    \r\n    if(v<.2)s=2;\r\n    else\r\n        if(v<.4)s=1;\r\n          else s=0;\r\n    if(s<ts)ts = s; \r\n    \r\n    $(\"#data-vital_sign\").val(ts);    \r\n    \r\n    score = ts;\r\n    \r\n    v = getScore(\"o2sat\");\r\n    if(v>95)score+=2;\r\n    else\r\n        if(v>92)score+=1;\r\n        \r\n        \r\n    \r\n    score += getScore(\"conscious\");       \r\n    score += getScore(\"respiration\"); \r\n    score += getScore(\"nausea_vomiting\"); \r\n    score += getScore(\"pain\"); \r\n    score += getScore(\"ambulation\"); \r\n    score += getScore(\"bleeding\"); \r\n            \r\n    $(\"#data-point\").val(score);       \r\n}\r\n\r\nfunction post_scope_setup(){\r\n$(\"#data-point\").change(refresh_point);\r\n$(\"#data-bp\").change(refresh_point); \r\n$(\"#data-diastolic\").change(refresh_point);\r\n$(\"#data-pr\").change(refresh_point);\r\n$(\"#data-rr\").change(refresh_point);\r\n$(\"#data-o2sat\").change(refresh_point);\r\n$(\"#data-o2sat_on_o2\").change(refresh_point);\r\n$(\"#data-conscious\").change(refresh_point);\r\n$(\"#data-respiration\").change(refresh_point);\r\n$(\"#data-nausea_vomiting\").change(refresh_point);\r\n$(\"#data-pain\").change(refresh_point);\r\n$(\"#data-ambulation\").change(refresh_point);\r\n$(\"#data-bleeding\").change(refresh_point);\r\n\r\n}\r\n</script>',NULL,NULL,NULL,'2016-11-25 05:10:20','2016-11-25 05:10:20','display',''),(2757,'index',1119,2,'<h1>Hello world</h1><br>\r\n<i>This is generated by system.</i>\r\n\r\n<form id=\"form1\" name=\"form1\" method=\"post\" action=\"\">\r\n <table>\r\n <tr><td> <label for=\"Date\"></label>\r\n  Date :<select name=\"Date\" id=\"Date\">\r\n  </select></td><td> HN :\r\n  <input type=\"text\" name=\"HN\" id=\"HN\" />