-11-26 00:35:10',NULL,NULL),(2759,'record',1119,2,'\r\n<div class=\"row-fluid\">\r\n  <div class=\"span12\">\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\" style=\"height: auto;    line-height: 20px;    font-size: 14px;\">\r\n<table>\r\n    <tbody><tr>\r\n    <td><img src=\"/gebo/img/gCons/agent.png\" alt=\"\" width=\"50\"></td>\r\n    <td align=\"left\">\r\n    HN : 110293/59<br>\r\n    Name : Supasit Demo<br>\r\n    </tr>\r\n    </tbody></table>\r\n</div>  \r\n<div class=\"w-box-content cnt_a\">\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\nComplication :<br />\r\n<div class=\"btn\">Polyp</div><div class=\"btn\">Notore</div><div class=\"btn\">Cancer</div><div class=\"btn\">Supprto</div>\r\n<div class=\"clear\"></div>\r\nFinding :<br />\r\n<div class=\"btn\">Polyp</div><div class=\"btn\">Notore</div><div class=\"btn\">Cancer</div><div class=\"btn\">Supprto</div>\r\n<div class=\"clear\"></div>\r\nIntervention :<br />\r\n<div class=\"btn\">EMR</div><div class=\"btn\">Bioscy</div><div class=\"btn\">fffff</div><div class=\"btn\">Supprto</div>\r\n<div class=\"clear\"></div>\r\nNote : <br />\r\n\r\n\r\n  \r\n  <textarea name=\"Note\" id=\"Note\" cols=\"45\" rows=\"5\"></textarea>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n',NULL,NULL,NULL,'2016-11-26 00:59:18','2016-11-26 00:59:18','record',''),(2760,'status_list',1061,1,'%w{Appointed Waiting Pre-op Ready Processing Recovery ICU Post-op Discharged}',NULL,NULL,NULL,'2016-11-27 07:20:10','2016-11-27 07:20:10','status_list',''),(2761,'service_map',1061,1,'{\r\n    :pre_operative=>\'PreOperative\',\r\n    :intra_operative=>\'IntraOperative\',\r\n    :post_operative=>\'PostOperative\'\r\n}',NULL,NULL,NULL,'2016-11-27 07:21:24','2016-11-27 07:21:24','service_map',''),(2762,'update_status',1061,2,'<%\r\n    date = \"\"\r\n    txt_msg = \"\"\r\n    ap = get_model[:appointment].find(params[:id])\r\n    if ap\r\n        if params[:status]\r\n            ap.update_attributes :status=>params[:status]\r\n            txt_msg = \"\\\\#{txt_msg} Status updated.\"\r\n        end\r\n        if params[:room]\r\n            rm = get_model[:room].where(:name=>params[:room]).first\r\n            ap.update_attributes :room=>rm.id\r\n            txt_msg = \"\\\\#{txt_msg} Room updated.\"\r\n        end\r\n%>\r\n<%= txt_msg %>\r\n<br/><br/>\r\nContent Loading... Please wait.\r\n\r\n\r\n    <META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=index<%=date%>\">\r\n\r\n\r\n<%\r\n    end \r\n%>\r\n',NULL,NULL,NULL,'2016-11-27 08:10:04','2016-11-27 08:10:04','update_status',''),(2763,'print_appointment',1061,3,'<%\r\n	@module_name = @current_project.name+\'#appointment\' \r\n	@ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@patient_doc = @ehr_project.get_document \'patient\'\r\n	@module_doc = @ehr_project.get_document \'patient_module\'\r\n	@ehr_model = @ehr_project.get_model()\r\n	@patient_model = @ehr_model[:patient]\r\n	@module_model = @ehr_model[:patient_module]\r\n	\r\n	@models = get_model\r\n	\r\n	if this.table_name!=\'appointment\' and params[:parent_id] \r\n	@appointment_module = @module_model.find(params[:parent_id])\r\n	if @appointment_module\r\n	@appointment = @models[:appointment].find(@appointment_module.module_id)\r\n	end\r\n	end \r\n	\r\n	if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n	   @patient = @patient_model.find(@patient_module.patient_id)\r\n	end\r\n	\r\n	if params[:print] and params[:print][:date]\r\n	\r\n	date = Date.to_mongo(params[:print][:date])\r\n	\r\n	appointments =   @models[:appointment].where(:date=>date).all\r\n	\r\n	\r\n	records = {}\r\n	patients = {}\r\n	providers = {}\r\n	indications= {}\r\n	visit_types= {}\r\n	rooms = {nil=>\'N/A\',\'\'=>\'N/A\'}\r\n	\r\n	\r\n	\r\n	@module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n	    records[i.module_id]=i\r\n	end\r\n	\r\n	@patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n	    patients[i.id]=i\r\n	end\r\n	\r\n	@models[:visit_type].all.each do |i|\r\n	    visit_types[i.id.to_s] = i\r\n	end\r\n	\r\n	@models[:provider].all.each do |i|\r\n	    providers[i.id.to_s] = i\r\n	end\r\n	@models[:indication].all.each do |i|\r\n	    indications[i.id.to_s] = i\r\n	end\r\n	\r\n	pro = {}\r\n	@models[:procedure].all.each do |i|\r\n	    pro[i.id] = i.name\r\n	end\r\n	\r\n	@models[:room].all.each do |i|\r\n	    rooms[i.id.to_s] = i[:name]\r\n	end\r\n	  \r\n	  \r\n	\r\n	  \r\n	json_data =   appointments.collect{|ap| \r\n	    i  = records[ap.id]\r\n	    if i\r\n	        p = patients[i.patient_id]  \r\n	        provider = providers[ap.provider.to_s]\r\n	        l = %w{#bcdeee}\r\n	        age = \'-\'\r\n	        if p.birth_date\r\n	            diff = Time.diff(date, p.birth_date)\r\n                year = diff[:year]\r\n                month = diff[:month]\r\n                day = diff[:day]\r\n                age = \"\\\\#{year}y. \\\\#{month}m. \\\\#{day}d.\"\r\n            end\r\n	        indication=\"-\"\r\n	        visit_type=\"-\"\r\n	        room = \'N/A\'\r\n	\r\n	        indication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n	        visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n	        room = rooms[ap[:room]]\r\n	\r\n	        d = \"-\"\r\n	        d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n	\r\n	        if true\r\n        	  {\'id\'=>ap.id,\r\n        	  \'record\'=>i.id,\r\n        	  :hn=> p.hn,\r\n        	  \'procedure\'=>pro[ap.procedure],\r\n        	  \'date\'=>d,\r\n        	  \'color\'=>l[rand(4%l.size)],\r\n        	  :provider=>provider.name,\r\n        	  :title=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n        	  :start=>\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n        	  :stop=>\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n        	  :room=>room,\r\n        	  :diagnosis=>ap[:diagnosis_1],\r\n        	  :operation=>ap[:tentative_operation],\r\n        	  :instru=>ap[:spacial_instrument],\r\n        	  :anesth_tech=>ap[:anesth_technique],\r\n        	  \'indication\'=>indication,\r\n        	  \'allDay\'=>false,\r\n        	  \'url\'=>\'edit?id=\'+i.id.to_s,\r\n        	  :age=>age,\r\n        	  \'visit_type\'=>visit_type,\r\n        # 	  \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n        	  \'public_id\'=>p.public_id\r\n        	  }  \r\n            else\r\n                nil\r\n            end \r\n        end\r\n	}.compact\r\n	\r\n# 	list = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\n    list = json_data.sort_by{|i| [i[:room], i[:start]]}\r\n	\r\n	%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>PRINT</title>\r\n	</head>\r\n	<style type=\"text/css\" media=\"print,screen\">\r\n		html { }\r\n		value {color:#06F}\r\n		imvalue { color:#F00; font-weight:bold}\r\n		imvalue value { color:#F00; font-weight:bold}\r\n		#page {border:solid 0px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n		#head { width:100%; height:60px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-size: 1.5em; margin: .83em 0 }\r\n		h3              { font-size: 1.17em; margin: 1em 0 }\r\n		p {color:#666;}\r\n		h4, p,\r\n		blockquote, ul,\r\n		form,\r\n		ol, dl          { margin: 0.5em; }\r\n		h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n		h6              { font-size: .67em; margin: 2.33em 0 }\r\n		h4 { font-size:14pt; color:#333; height:16px;}\r\n		blockquote      { margin-left: 40px; margin-right: 40px }\r\n		i, cite, em,\r\n		var, address    { font-style: italic }\r\n		pre, tt, code,\r\n		kbd, samp       {  font-size:14px; }\r\n		pre             {margin:0;margin-left:1em; color:#666}\r\n		big             { font-size: 1.17em }\r\n		v {color:#2561cD;}\r\n		small, sub, sup { font-size: .83em }\r\n		ol, ul, dd      { margin-left: 40px }\r\n		ol              { list-style-type: decimal }\r\n		ol ul, ul ol,\r\n		ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n		.clear{clear:both;}\r\n		@media print {\r\n		@page         { width:960px; margin-top:10; }\r\n		blockquote, \r\n		.wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n		table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n		tr    { page-break-inside:avoid; page-break-after:auto }\r\n		td    { page-break-inside:avoid; page-break-after:auto }\r\n		thead { display:table-header-group;     margin-top:10px;}\r\n		tfoot { display:table-footer-group }\r\n		}\r\n		#box{\r\n		width:150px;\r\n		float:left;\r\n		padding:10px;\r\n		text-align:center;\r\n		border:1px solid #ccc;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */    \r\n		margin:10px;\r\n		}\r\n		.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n		#box img{\r\n		width:150px;\r\n		}\r\n		label{\r\n		color:#666; font-weight:bold;\r\n		}\r\n		#table-3 {\r\n		border: 1px solid #DFDFDF;\r\n		background-color: #F9F9F9;\r\n		width: 100%;\r\n		-moz-border-radius: 3px;\r\n		-webkit-border-radius: 3px;\r\n		border-radius: 3px;\r\n		font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n		color: #333;\r\n		}\r\n		#table-3 td, #table-3 th {\r\n		border-top-color: white;\r\n		border-bottom: 1px solid #DFDFDF;\r\n		color: #555;\r\n		}\r\n		#table-3 th {\r\n		text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n		font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n		font-weight: normal;\r\n		padding: 7px 7px 8px;\r\n		text-align: left;\r\n		line-height: 1.3em;\r\n		font-size: 14px;\r\n		}\r\n		#table-3 td {\r\n		font-size: 12px;\r\n		padding: 4px 7px 2px;\r\n		vertical-align: top;\r\n		background:#FFF;\r\n		}\r\n		thead {\r\n		display:table-header-group;\r\n		}\r\n		tbody {\r\n		display:table-row-group;\r\n		}\r\n	</style>\r\n	<body>\r\n		<div class=\"wrapper\">\r\n			<div id=\"head\">\r\n				<div id=\"logoleft\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' height=\"70\" style=\"float:left\" />\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now.strftime(\'%d/%m/%Y\') %></p>\r\n				</div>\r\n			</div>\r\n			<br/>\r\n			<div id=\"page\">\r\n				<div class=\"row-fluid\">\r\n					<div class=\"span12\">\r\n						<div class=\"w-box\">\r\n							<br />\r\n							<b>ตารางแสดงรายการผู้ป่วย\r\n							<span style=\"float:right\">ประจำวันที่ \r\n							<%= date.strftime(\"%d %B %Y\")%></b>\r\n							</span>\r\n							<br /><br />\r\n							<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n								<thead>\r\n									<tr>\r\n										<th>No.</th>\r\n										<th>Room</th>\r\n										<th>Time</th>\r\n										<th>HN</th>\r\n										<th style=\"width:150px\">Name</th>\r\n										<th>Age</th>\r\n										<th>Diagnosis</th>\r\n										<th>Operation</th>\r\n										<th>Spec.Instru.</th>\r\n										<th>Anesth.Tech.</th>\r\n										<th>Surgeon</th>\r\n									</tr>\r\n								</thead>\r\n								<tbody>\r\n									<% list.each_with_index do |i,index|  %>\r\n									<tr style=\"height:110px\">\r\n										<td><%=index+1%>.</td>\r\n										<td><%=i[:room]%></td>\r\n										<td><%=i[:start]%> - <%= i[:stop] %></td>\r\n										<td><%=i[:hn]%></td>\r\n										<td style=\"width:150px\"><%=i[:title]%></td>\r\n										\r\n										<td><%=i[:age]%></td>\r\n										<td><%=i[:diagnosis]%></td>\r\n										<td><%=i[:operation]%></td>\r\n										<td><%=i[:instru]%></td>\r\n										<td><%=i[:anesth_tech]%></td>\r\n										<td><%=i[:provider]%></td>\r\n										\r\n									</tr>\r\n									<% end %>\r\n								</tbody>\r\n							</table>\r\n							<br/>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</div>\r\n		</div>\r\n		<script>\r\n		    window.print();\r\n		</script>\r\n	</body>\r\n</html>\r\n<% end %>',NULL,NULL,NULL,'2016-11-27 13:43:03','2016-11-27 13:43:03','print_appointment',''),(2764,'print_room',1061,3,'<%\r\n	@module_name = @current_project.name+\'#appointment\' \r\n	@ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@patient_doc = @ehr_project.get_document \'patient\'\r\n	@module_doc = @ehr_project.get_document \'patient_module\'\r\n	@ehr_model = @ehr_project.get_model()\r\n	@patient_model = @ehr_model[:patient]\r\n	@module_model = @ehr_model[:patient_module]\r\n	\r\n	@models = get_model\r\n	\r\n	if this.table_name!=\'appointment\' and params[:parent_id] \r\n	@appointment_module = @module_model.find(params[:parent_id])\r\n	if @appointment_module\r\n	@appointment = @models[:appointment].find(@appointment_module.module_id)\r\n	end\r\n	end \r\n	\r\n	if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n	   @patient = @patient_model.find(@patient_module.patient_id)\r\n	end\r\n	\r\n	if params[:print] and params[:print][:date]\r\n	\r\n	date = Date.to_mongo(params[:print][:date])\r\n	\r\n	appointments =   @models[:appointment].where(:date=>date).all\r\n	\r\n	\r\n	records = {}\r\n	patients = {}\r\n	providers = {}\r\n	indications= {}\r\n	visit_types= {}\r\n	rooms = {nil=>\'N/A\',\'\'=>\'N/A\'}\r\n	\r\n	\r\n	\r\n	@module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n	    records[i.module_id]=i\r\n	end\r\n	\r\n	@patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n	    patients[i.id]=i\r\n	end\r\n	\r\n	@models[:visit_type].all.each do |i|\r\n	    visit_types[i.id.to_s] = i\r\n	end\r\n	\r\n	@models[:provider].all.each do |i|\r\n	    providers[i.id.to_s] = i\r\n	end\r\n	@models[:indication].all.each do |i|\r\n	    indications[i.id.to_s] = i\r\n	end\r\n	\r\n	pro = {}\r\n	@models[:procedure].all.each do |i|\r\n	    pro[i.id] = i.name\r\n	end\r\n	\r\n	@models[:room].all.each do |i|\r\n	    rooms[i.id.to_s] = i[:name]\r\n	end\r\n	  \r\n	  \r\n	\r\n	  \r\n	json_data =   appointments.collect{|ap| \r\n	    i  = records[ap.id]\r\n	    if i\r\n	        p = patients[i.patient_id]  \r\n	        provider = providers[ap.provider.to_s]\r\n	        l = %w{#bcdeee}\r\n	        age = \'-\'\r\n	        if p.birth_date\r\n	            diff = Time.diff(date, p.birth_date)\r\n                year = diff[:year]\r\n                month = diff[:month]\r\n                day = diff[:day]\r\n                age = \"\\\\#{year}y. \\\\#{month}m. \\\\#{day}d.\"\r\n            end\r\n	        indication=\"-\"\r\n	        visit_type=\"-\"\r\n	        room = \'N/A\'\r\n	\r\n	        indication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n	        visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n	        room = rooms[ap[:room]]\r\n	\r\n	        d = \"-\"\r\n	        d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n	\r\n	        if true\r\n        	  {\'id\'=>ap.id,\r\n        	  \'record\'=>i.id,\r\n        	  :hn=> p.hn,\r\n        	  \'procedure\'=>pro[ap.procedure],\r\n        	  \'date\'=>d,\r\n        	  \'color\'=>l[rand(4%l.size)],\r\n        	  :provider=>provider.name,\r\n        	  :title=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n        	  :start=>\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n        	  :stop=>\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n        	  :room=>room,\r\n        	  :diagnosis=>ap[:diagnosis_1],\r\n        	  :operation=>ap[:tentative_operation],\r\n        	  :instru=>ap[:spacial_instrument],\r\n        	  :anesth_tech=>ap[:anesth_technique],\r\n        	  \'indication\'=>indication,\r\n        	  \'allDay\'=>false,\r\n        	  \'url\'=>\'edit?id=\'+i.id.to_s,\r\n        	  :age=>age,\r\n        	  \'visit_type\'=>visit_type,\r\n        # 	  \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n        	  \'public_id\'=>p.public_id\r\n        	  }  \r\n            else\r\n                nil\r\n            end \r\n        end\r\n	}.compact\r\n	\r\n# 	list = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\n    list = json_data.sort_by{|i| [i[:room], i[:start]]}\r\n    \r\n    obj = list.group_by{|i| i[:room]}\r\n	\r\n	%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>PRINT</title>\r\n	</head>\r\n	<style type=\"text/css\" media=\"print,screen\">\r\n		html { }\r\n		value {color:#06F}\r\n		imvalue { color:#F00; font-weight:bold}\r\n		imvalue value { color:#F00; font-weight:bold}\r\n		#page {border:solid 0px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n		#head { width:100%; height:60px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-size: 1.5em; margin: .83em 0 }\r\n		h3              { font-size: 1.17em; margin: 1em 0 }\r\n		p {color:#666;}\r\n		h4, p,\r\n		blockquote, ul,\r\n		form,\r\n		ol, dl          { margin: 0.5em; }\r\n		h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n		h6              { font-size: .67em; margin: 2.33em 0 }\r\n		h4 { font-size:14pt; color:#333; height:16px;}\r\n		blockquote      { margin-left: 40px; margin-right: 40px }\r\n		i, cite, em,\r\n		var, address    { font-style: italic }\r\n		pre, tt, code,\r\n		kbd, samp       {  font-size:14px; }\r\n		pre             {margin:0;margin-left:1em; color:#666}\r\n		big             { font-size: 1.17em }\r\n		v {color:#2561cD;}\r\n		small, sub, sup { font-size: .83em }\r\n		ol, ul, dd      { margin-left: 40px }\r\n		ol              { list-style-type: decimal }\r\n		ol ul, ul ol,\r\n		ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n		.clear{clear:both;}\r\n		@media print {\r\n    		@page { \r\n    		    /*width:960px; margin-top:10; */\r\n    		    size: landscape;\r\n    		}\r\n    		blockquote, \r\n    		.wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n    		table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n    		tr    { page-break-inside:avoid; page-break-after:auto }\r\n    		td    { page-break-inside:avoid; page-break-after:auto }\r\n    		thead { display:table-header-group;     margin-top:10px;}\r\n    		tfoot { display:table-footer-group }\r\n		}\r\n		#box{\r\n		width:150px;\r\n		float:left;\r\n		padding:10px;\r\n		text-align:center;\r\n		border:1px solid #ccc;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */    \r\n		margin:10px;\r\n		}\r\n		.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n		#box img{\r\n		width:150px;\r\n		}\r\n		label{\r\n		color:#666; font-weight:bold;\r\n		}\r\n		#table-3 {\r\n		border: 1px solid #DFDFDF;\r\n		background-color: #F9F9F9;\r\n		width: 100%;\r\n		-moz-border-radius: 3px;\r\n		-webkit-border-radius: 3px;\r\n		border-radius: 3px;\r\n		font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n		color: #333;\r\n		}\r\n		#table-3 td, #table-3 th {\r\n		border-top-color: white;\r\n		border-bottom: 1px solid #DFDFDF;\r\n		color: #555;\r\n		}\r\n		#table-3 th {\r\n		text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n		font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n		font-weight: normal;\r\n		padding: 7px 7px 8px;\r\n		text-align: left;\r\n		line-height: 1.3em;\r\n		font-size: 14px;\r\n		}\r\n		#table-3 td {\r\n		font-size: 12px;\r\n		padding: 4px 7px 2px;\r\n		vertical-align: top;\r\n		background:#FFF;\r\n		}\r\n		thead {\r\n		display:table-header-group;\r\n		}\r\n		tbody {\r\n		display:table-row-group;\r\n		}\r\n	</style>\r\n	<body>\r\n		<div class=\"wrapper\">\r\n\r\n<%\r\n    obj.each do |k, list|\r\n%>\r\n<!--\r\n			<div id=\"head\">\r\n				<div id=\"logoleft\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' height=\"70\" style=\"float:left\" />\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now.strftime(\'%d/%m/%Y\') %></p>\r\n				</div>\r\n			</div>\r\n			<br/>\r\n-->			\r\n            <div class=\'clear\' style=\'page-break-before: always;\'></div><br/>\r\n			<div style=\'font-size:2.5em\'>\r\n			    <center>Room <%= k %></center>\r\n			    <!--<center style=\'font-size:0.5em\'><%= Time.now.strftime(\'%d/%m/%Y\') %></center>-->\r\n			</div>\r\n			<div id=\"page\">\r\n				<div class=\"row-fluid\">\r\n					<div class=\"span12\">\r\n						<div class=\"w-box\">\r\n							<br />\r\n							<b>ตารางแสดงรายการผู้ป่วย\r\n							<span style=\"float:right\">ประจำวันที่ \r\n							<%= date.strftime(\"%d %B %Y\")%></b>\r\n							</span>\r\n							<br /><br />\r\n							<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n								<thead>\r\n									<tr>\r\n										<th>No.</th>\r\n										<th>Time</th>\r\n										<th>HN</th>\r\n										<th style=\"width:150px\">Name</th>\r\n										<th>Age</th>\r\n										<th>Diagnosis</th>\r\n										<th>Operation</th>\r\n										<th>Spec.Instru.</th>\r\n										<th>Anesth.Tech.</th>\r\n										<th>Surgeon</th>\r\n									</tr>\r\n								</thead>\r\n								<tbody>\r\n									<% list.each_with_index do |i,index|  %>\r\n									<tr>\r\n										<td><%=index+1%>.</td>\r\n										<td><%=i[:start]%> - <%= i[:stop] %></td>\r\n										<td><%=i[:hn]%></td>\r\n										<td style=\"width:150px\"><%=i[:title]%></td>\r\n										\r\n										<td><%=i[:age]%></td>\r\n										<td><%=i[:diagnosis]%></td>\r\n										<td><%=i[:operation]%></td>\r\n										<td><%=i[:instru]%></td>\r\n										<td><%=i[:anesth_tech]%></td>\r\n										<td><%=i[:provider]%></td>\r\n										\r\n									</tr>\r\n									<% end %>\r\n								</tbody>\r\n							</table>\r\n							<div style=\'font-size:0.6em;float:right;margin-top:10px\'><i>Printed by : <%= @current_user.login.humanize %> (<%= Time.now.strftime(\'%d/%m/%Y %H:%M\') %>)</i></div>\r\n							<br/>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</div>\r\n			\r\n<%\r\n    end\r\n%>\r\n		</div>\r\n\r\n<script>\r\n        window.print();\r\n</script>\r\n\r\n\r\n	</body>\r\n</html>\r\n<% end %>',NULL,NULL,NULL,'2016-11-27 14:29:50','2016-11-27 14:29:50','print_room',''),(2765,'document_name',1120,1,'\'genral_summary\'',NULL,NULL,NULL,'2016-11-28 02:58:47','2016-11-28 02:58:47',NULL,NULL),(2766,'common_query',1061,4,'<%\r\n    # time begin\r\n    tb = Time.now\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	@m_pat = @ehr_model[:patient]\r\n	@m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n# 	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n    status_list = @status_list\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	r_model = models[:room]\r\n	w_model = models[:ward]\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	room_list = [\'N/A\']\r\n	rooms = {nil=>\'N/A\',\'\'=>\'N/A\'}\r\n	r_model.all.each do |i|\r\n	    rooms[i.id.to_s] = i[:name]\r\n	    room_list << i[:name]\r\n	end\r\n	\r\n	wards = {nil=>\'N/A\', \'\'=>\'N/A\'}\r\n	w_model.all.each do |i|\r\n	    wards[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	\r\n	id = \'\'\r\n	a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = @m_pat_mod.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n	\r\n	# form service\r\n	f_ser = {}\r\n	# module_id from service\r\n	mid_ser = {}\r\n	mid_map = {}\r\n	# service_map\r\n	sm = @service_map\r\n	sm.each do |k, v|\r\n	    f_ser[k] = {}\r\n	    mid_map[k] = {}\r\n	    mid_ser[k] = []\r\n	    tmp = @m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>pa_id).all\r\n	    tmp.each do |i|\r\n	        f_ser[k][i[:patient_id].to_s] = i.id.to_s\r\n	        mid_map[k][i[:patient_id].to_s] = i[:module_id].to_s\r\n	        mid_ser[k] << i[:module_id].to_s\r\n	        \r\n	    end\r\n	end\r\n	\r\n	rs_pat_mod = {}\r\n	pat_id = []\r\n	@m_pat_mod.where(:module_name=>mname, :module_id=>a_id).all.each do |i|\r\n	    rs_pat_mod[i[:module_id].to_s] = i\r\n	    pat_id << i[:patient_id].to_s\r\n	end\r\n	\r\n	rs_pat = {}\r\n	@m_pat.find(pat_id).each do |i|\r\n	    rs_pat[i.id.to_s] = i\r\n	end\r\n\r\nif false	\r\n	aps.collect!{|i| \r\n        id = i.id\r\n        # if m = @m_pat_mod.first(:module_name=>mname,:module_id=>i.id)\r\n        if m = rs_pat_mod[i.id.to_s]\r\n            pat_id = m.patient_id.to_s\r\n    	   #  patient = @m_pat.find(m[:patient_id])\r\n            patient = rs_pat[m[:patient_id].to_s]\r\n    	     if patient \r\n        	     provider = @rs_prov[i[:provider].to_s]\r\n        	     visit_type = @rs_visit[i[:visit_type].to_s].nil? ? \'N/A\' : @rs_visit[i[:visit_type].to_s][:name]\r\n        	     provider_name = \'NA\'\r\n        	     provider_name = provider.name if provider\r\n        	     procedure_name = \'NA\'\r\n        	     pro = @rs_proc[i[:procedure].to_s]\r\n        	     procedure_name = pro.name if pro\r\n        	     patient = @m_pat.new unless patient \r\n        	     hn = \'-\'\r\n        	     \r\n        	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n        	     provider_name  = link_to(provider_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     procedure_name = link_to(procedure_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     public_id = \'-\'\r\n        	     \r\n        	     rm = \'N/A\'\r\n        	     if i[:room]\r\n        	         rm = rooms[i[:room]]\r\n        	     end\r\n    	    \r\n                c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id.to_s}\"),\r\n        	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        	     :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Arrived\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n        	     :visit_type=>visit_type,\r\n        	     :rm=>rm,\r\n        	     :room=>select_tag(\'room\',options_for_select(room_list,rm),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_room(this)\'),\r\n        	     :start=>i[:start].strftime(\'%H:%M\'),\r\n        	     :stop=>((i[:stop].nil? or i[:stop]==\'\') ? \'-\' : i[:stop].strftime(\'%H:%M\')),\r\n        	     :note=>i[:note]\r\n                }\r\n                \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info \', :style=>\'width:45px\')\r\n                l_list = []\r\n                sm.each do |k, v|\r\n                    lab = k.to_s.split(\'_\')[0].humanize\r\n                    v_link = link_to(\"<i class=\'splashy-add\'></i> \\\\#{lab}\".html_safe, \r\n                        \"../\\\\#{v}/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/index\", \r\n                        :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                    if f_ser[k][pat_id]\r\n                        v_link = link_to(\"<i class=\'splashy-document_a4\'></i> \\\\#{lab}\".html_safe, \r\n                            \"../\\\\#{v}/show?id=\\\\#{f_ser[k][pat_id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                    end\r\n                    l_list << v_link\r\n                end\r\n                \r\n                # v_link = link_to(\'<i class=\"splashy-add\"></i> Add\'.html_safe, \r\n                #     \"../OutPatientForm/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/index\", \r\n                #     :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                # if f_liv[pat_id]\r\n                #     v_link = link_to(\'<i class=\"splashy-document_a4\"></i> View\'.html_safe, \r\n                #         \"../OutPatientForm/show?id=\\\\#{f_liv[pat_id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                # end\r\n                c[:processing_ctrl]= \"\\\\#{l_list.join(\' \')} \\\\#{d_link}\".html_safe \r\n                \r\n                c\r\n            end\r\n        end\r\n	}.compact!\r\nend	\r\n	\r\n	\r\n	# room group\r\n# 	rg = aps.sort_by{|i| [i[:rm],i[:start]]}.group_by{|i| i[:rm]}\r\n	\r\n# 	table_model = %w{room start stop hn patient provider status_ctrl processing_ctrl note }.collect{|i| i.to_sym}\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n# 	labels = {:room=>\'Room\',:start=>\'Start\',:stop=>\'Stop\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Surgeon\',:procedure=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n# 	:note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Actions\' }\r\n	\r\n	res = {}\r\n	res[:time] = Time.now - tb\r\n	res[:aps_count] = aps.size\r\n	res[:aps] = aps\r\n	\r\n	@res = res\r\n	\r\n	@rs_app  = aps\r\n	@rs_pat  = rs_pat\r\n	@rs_pat_mod = rs_pat_mod\r\n	@rs_room = rooms\r\n	@rs_ward = wards\r\n	@rs_room_list = room_list\r\n	@rs_serv = f_ser\r\n	@mid_ser = mid_ser # result of  module id service\r\n	@mid_map = mid_map\r\n	@date = date\r\n	@p_date = date.strftime(\'%d/%m/%Y\')\r\n	\r\n	@total_time = Time.now - tb\r\n%>',NULL,NULL,NULL,'2016-11-28 04:11:40','2016-11-28 04:11:40','common_query',''),(2767,'document_name',1121,1,'\'general_summary\'',NULL,NULL,NULL,'2016-11-28 05:50:41','2016-11-28 05:50:41',NULL,NULL),(2770,'print',1026,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n	# id of operative note\r\n	\r\n	models  = @models\r\n	pm = @module_model.find(params[:id])\r\n	colono_id = pm.module_id\r\n	record = models[:ebus].find(colono_id)\r\n	@record = record\r\n	@document = get_document this.document_name\r\n	\r\n	endoscopist_1 = render_value(\'endoscopist_1\')\r\n	endoscopist_2 = render_value(\'endoscopist_2\')\r\n	\r\n	if @patient \r\n    	patient = @patient\r\n    	date = Time.now.to_datetime\r\n    	birth_date = patient.birth_date \r\n    	year = month = day = \'0\'\r\n    	if date and birth_date\r\n        	t = date-birth_date    \r\n        	year = (t/365).to_i\r\n        	t%=365\r\n        	month = (t/30).to_i\r\n        	t%=30\r\n        	day = t.to_i\r\n    	end\r\n	end\r\n	\r\n	def get_render_value(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return \"-\"\r\n        else\r\n            return render_value(f.to_s)\r\n        end\r\n    end\r\n    \r\n    def get_value(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return \'-\'\r\n        else\r\n            return @record[f]\r\n        end\r\n    end\r\n    \r\n    def is_exist(field)\r\n        f = field.to_sym\r\n        if @record[f].nil? or @record[f]==\'\'\r\n            return false\r\n        else\r\n            return true\r\n        end\r\n    end\r\n		# gender\r\n	gd = {\'0\'=>\'N/A\',\'1\'=>\'Male\',\'2\'=>\'Female\'}\r\n%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>PRINT</title>\r\n	</head>\r\n	<style type=\"text/css\" media=\"all\">\r\n		html { }\r\n		#page {border:solid 1px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n		#head { width:100%; height:140px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-size: 1.5em; margin: .83em 0 }\r\n		h3              { font-size: 1.17em; margin: 1em 0 }\r\n		p {color:#666;}\r\n		h4, p,\r\n		blockquote, ul,\r\n		form,\r\n		ol, dl          { margin: 0.5em; }\r\n		h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n		h6              { font-size: .67em; margin: 2.33em 0 }\r\n		h4 { font-size:14pt; color:#333; height:16px;}\r\n		blockquote      { margin-left: 40px; margin-right: 40px }\r\n		i, cite, em,\r\n		var, address    { font-style: italic }\r\n		pre, tt, code,\r\n		kbd, samp       {  font-size:14px; }\r\n		pre             {margin:0;margin-left:1em; color:#666}\r\n		big             { font-size: 1.17em }\r\n		v {color:#2561cD;}\r\n		small, sub, sup { font-size: .83em }\r\n		ol, ul, dd      { margin-left: 40px }\r\n		ol              { list-style-type: decimal }\r\n		ol ul, ul ol,\r\n		ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n		.clear{clear:both;}\r\n		@media print {\r\n		@page         { width:960px; margin-top:0; }\r\n		blockquote, \r\n		.wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n		}\r\n		#box{\r\n		width: 235px;\r\n		float:left;\r\n		padding:0px;\r\n		text-align:center;\r\n		border:1px solid #ccc;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */    \r\n		margin:5px;\r\n		font-size:0.8em;\r\n		height:190px;\r\n		overflow:hidden;\r\n		}\r\n		.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n		#box img{\r\n		    height: 170px;\r\n    width: 230px;\r\n		}\r\n		label{\r\n		color:#666;\r\n		}\r\n		.sidationcss\r\n		{width:160px; float:left; margin-bottom:3px;}\r\n	</style>\r\n	<body>\r\n		<div class=\"wrapper\">\r\n			<div id=\"head\" class=\"well\">\r\n				<div id=\"logoleft\" style=\"width:600px; float:left\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n					<br />\r\n					First Name : \r\n					<v><%= patient.prefix_name %> <%= patient.first_name %></v>\r\n					<br />\r\n					Last Name : \r\n					<v><%= patient.last_name %></v>\r\n					<br />\r\n					HN :&nbsp;\r\n					<v><%=patient.hn%></v>\r\n					<br />\r\n					Age :&nbsp;\r\n					<v><%= year%> Year <%=month%> Month <%= day%> Day </v>\r\n					<br />\r\n					Gender :&nbsp;\r\n					<v><%= gd[patient[:gender]] %></v>\r\n					<br />\r\n					Date :&nbsp;\r\n					\r\n					<br />\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now %></p>\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n			</div>\r\n		  <div id=\"page\">\r\n			<div class=\"clear\"></div>\r\n				<table width=\"100%\">\r\n					<tr>\r\n					  <td width=\"400\" valign=\"top\">\r\n                       \r\n                        <div style=\"width:400px;border: 0px solid blue;padding-top:0px;padding-bottom:0px\" id=\"form-data\">\r\n                          <div  style=\"margin-left:auto;margin-right:auto;padding:1px;\" class=\"form-data-content\">\r\n                            <div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:100%;margin:0px;min-height:50px\" >\r\n                              <div id=\"operative_date\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label>Operative date : </label>\r\n                                </span>\r\n                                <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n                                 <v><%=render_value \'operative_date\'%></v>\r\n                                 \r\n                                </div>\r\n                              </div>\r\n                             \r\n                              <div id=\"arrival_time\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label>Arrival time : </label>\r\n                                </span>\r\n                                <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n                                  <v><%=render_value \'arrival_time\'%></v>\r\n                                  \r\n                                </div>\r\n                              </div>\r\n                              \r\n                              <div id=\"operative_setting\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label>Operative setting : </label>\r\n                                </span>\r\n                                <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n                                  <v><%=render_value \'operative_setting\'%></v>\r\n                                </div>\r\n                              </div>\r\n                             \r\n                              <div id=\"621-F6033902013\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>Diagnosis</b> </div>\r\n                             \r\n                              <div id=\"provisional_diagnosis\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px\"> <span class=\"\">\r\n                                <label>Provisional Diagnosis : </label>\r\n                                </span>\r\n                                <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n                                 \r\n                                <v><%=render_value \'provisional_diagnosis\'%></v>\r\n                                </div>\r\n                              </div>\r\n                             \r\n                              <div id=\"provisional_note\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px\"> <span class=\"\">\r\n                                <label>Note : </label>\r\n                                </span>\r\n                              <v><%=render_value \'provisional_note\'%></v>\r\n                              </div>\r\n                             \r\n                              <div id=\"621-F6752296052\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>Pathology</b> </div>\r\n                              <div id=\"histopathology\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label>Histopathology : </label>\r\n                                </span>\r\n                              <v><%=render_value \'histopathology\'%></v>\r\n                              </div>\r\n                              \r\n                              <div id=\"cytology\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label>Cytology : </label>\r\n                                </span>\r\n                               <v><%=render_value \'cytology\'%></v>\r\n                              </div>\r\n                             \r\n                              <div id=\"621-F1065965030\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>Microbiology</b> </div>\r\n                             \r\n                              <div id=\"culture\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px\"> <span class=\"\">\r\n                                <label>Culture : </label>\r\n                                </span>\r\n                             <v><%=render_value \'culture\'%></v>\r\n                              </div>\r\n                            \r\n                              <div id=\"microbiology_other\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:690px\"> <span class=\"\">\r\n                                <label>Oher : </label>\r\n                                </span>\r\n                            <v><%=render_value \'microbiology_other\'%></v>\r\n                              </div>\r\n                             \r\n                              <div id=\"621-F5346427130\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>Operator</b> </div>\r\n                             \r\n                              <div id=\"endoscopist\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label>Staff : </label>\r\n                                </span>\r\n                               <v><%=endoscopist_1%></v>\r\n                              </div>\r\n                              \r\n                              <div id=\"endoscopist_1\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label>Fellow : </label>\r\n                                </span>\r\n                               <%=endoscopist_2%>\r\n                              </div>\r\n                             \r\n                              <div id=\"621-F7043506196\" class=\"   field\" style=\"clear:both;text-align:right\"></div>\r\n                             \r\n                              <div id=\"operative_time_start_at\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label>Operative time start at : </label>\r\n                                </span>\r\n                                <v><%=render_value \'operative_time_start_at\'%></v>\r\n                              </div>\r\n                             \r\n                              <div id=\"operative_time_stop_at\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label> stop at : </label>\r\n                                </span>\r\n                              <v><%=render_value \'operative_time_stop_at\'%></v>\r\n                              </div>\r\n                             \r\n                              <div id=\"total_operative\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label>Total operative : </label>\r\n                                </span>\r\n                               <v><%=render_value \'total_operative\'%></v>\r\n                              </div>\r\n                              \r\n                              <div id=\"621-F4603315804\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>Sedation</b> </div>\r\n                             \r\n                              <% if record[\'midazolam\']==\'true\'%>\r\n                             \r\n                              <div id=\"midazolam_mg\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px\">\r\n                               Midazolam :<v><%=render_value \'midazolam_mg\'%></v> </div><% end %>\r\n                             \r\n                              <div id=\"621-F2393984515\" class=\"   field\" style=\"clear:both;text-align:right\"></div>\r\n                           <% if record[\'fentanyl\']==\'true\'%>\r\n                              \r\n                             \r\n                              <div id=\"fentanyl_mg\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px\">\r\n                               Fentanyl :<v><%=render_value \'fentanyl_mg\'%></v> </div>\r\n                             \r\n                              <div id=\"fentanyl_routh\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px\">\r\n                               <v><%=render_value \'fentanyl_routh\'%></v>\r\n                              </div>\r\n                              <% end %>\r\n                              <div id=\"621-F8721857576\" class=\"   field\" style=\"clear:both;text-align:right\"></div>\r\n                              <% if record[\'propofol\']==\'true\'%>\r\n                             \r\n                            \r\n                              <div id=\"propofol_mg\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px\">\r\n                              Propofol :  <v><%=render_value \'propofol_mg\'%></v> </div>\r\n                              <% end %>\r\n                              <div id=\"621-F0602746188\" class=\"   field\" style=\"clear:both;text-align:right\"></div>\r\n                              <% if record[\'other_sedative\']==\'true\'%>\r\n                             \r\n                              <div id=\"sedative_other\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n                                <label> Other </label>\r\n                                <v><%=render_value \'sedative_other\'%></v>\r\n                              </div><% end %>\r\n                            \r\n                              <div id=\"621-F8577463855\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>LN Station</b> </div>\r\n<%\r\n    if is_exist(:ln_station)\r\n        # field map\r\n        fm = {}\r\n        @document.fields.each do |i|\r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].strip\r\n                    tmp[:list] << x[1].strip\r\n                end\r\n                fm[i[:column_name].to_sym] = tmp\r\n            end\r\n        end\r\n        \r\n        # field temp\r\n        ft = {\r\n            \'1\'=>:upper_ebus_with_tbna,\r\n            \'2\'=>:lower_ebus_with_tbna,\r\n            \'3\'=>:subcarinal_ebus_with_tbna,\r\n            \'4\'=>:hilar_ebus_with_tbna,\r\n            \'5\'=>:interlobar_ebus_with_tbna\r\n        }\r\n        \r\n        rs = @record[:ln_station].split(\'|\')\r\n        \r\n        ft.keys.each do |i|\r\n            txt = \'N/A\'\r\n            if rs.include? i\r\n                txt = get_render_value(ft[i])\r\n            end\r\n%>\r\n                              <div id=\"<%= ft[i] %>\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\"> \r\n                                <span class=\"\">\r\n                                    <label>\r\n                                        <%= fm[:ln_station][:pair][i] %><br/>\r\n                                        &nbsp;&nbsp;&nbsp;&nbsp;- EBUS with TBNA : \r\n                                    \r\n                                    </label>\r\n                                </span>\r\n                                <v><%= txt %> </v>\r\n                              </div>\r\n<%\r\n        end\r\n    else \r\n%>\r\n                            <div id=\"interlobar_ebus_with_tbna\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\"> \r\n                                <span class=\"\">\r\n                                    <label>- None - </label>\r\n                                </span>\r\n                            </div>\r\n<%\r\n    end\r\n%>\r\n                              <div id=\"621-F1033442287\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>Complication</b> </div>\r\n                            \r\n                              <div id=\"intraoperative_complication\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px\"> <span class=\"\">\r\n                                <label>Intraoperative complication : </label>\r\n                                </span>\r\n                              <v><%=render_value \'intraoperative_complication\'%></v>\r\n                              </div>\r\n                              \r\n                              <div id=\"intraoperative_complication_detail\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px\"> <span class=\"\">\r\n                                <label>Detail : </label>\r\n                                </span>\r\n                                 <v><%=render_value \'intraoperative_complication_detail\'%></v>\r\n                              </div>\r\n                              \r\n                              <div id=\"621-F5650172760\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\"> <b>Comment</b> </div>\r\n                              \r\n                              <div id=\"comment\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;\"> <span class=\"\">\r\n                                <label>Comment : </label>\r\n                                </span>\r\n                                <v><%=render_value \'comment\'%></v>\r\n                              </div>\r\n                              \r\n                              <div class=\"clear\"></div>\r\n                            </div>\r\n                          </div>\r\n                      </div></td><td valign=\"top\"><img src=\"/esm/cusys/bronchoscopy/map.jpg\" alt=\"\" width=\"400px\"/>\r\n                      <h4>Picture :</h4>\r\n				<%\r\n					list = record.images\r\n					atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n					\r\n					if atts\r\n					atts.each_with_index do |i,index| \r\n					%>\r\n				<div id=\"box\">\r\n					<img alt=\"1\" src=\"<%=i.path%>\" /><br/>\r\n					<v><%=i.title%></v>\r\n				</div>\r\n				<% if index%4==3 %>\r\n				<div class=\"clear\"></div>\r\n				<% end %>\r\n				<% end %>\r\n				<% end %>\r\n                      </td>\r\n				  </tr>\r\n				</table>\r\n			</div>\r\n		  <div class=\"clear\"></div>\r\n\r\n                      \r\n			<div id=\"page\" style=\"height:80px\">\r\n			  <h4>Sign :</h4>\r\n		  </div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n		<%# @record.to_json.html_safe %>\r\n	</body>\r\n</html>',NULL,NULL,NULL,'2016-11-28 06:26:21','2016-11-28 06:26:21','print',''),(2771,'document_name',1123,1,'\'general_summary1\'',NULL,NULL,NULL,'2016-11-29 06:20:04','2016-11-29 06:20:04',NULL,NULL),(2772,'test_render',1061,3,'<%= render :inline=>this.params_config %>\r\n<%= render :inline=>this.common_query %>\r\n<%= @res.to_json.html_safe %>',NULL,NULL,NULL,'2016-11-29 06:20:45','2016-11-29 06:20:45','test_render',''),(2773,'params_config',1061,4,'<%\r\n    @service_map = {\r\n            :pre_operative_visit=>\'PreOperativeVisit\',\r\n            :pre_operative=>\'PreOperative\',\r\n            :intra_operative=>\'IntraOperative\',\r\n            :post_operative=>\'PostOperative\'\r\n        }\r\n    @status_list = %w{Appointed Pre-op Waiting Ready Processing Recovery Post-op ICU Discharged}\r\n    \r\n    def map_model(model)\r\n        # tmp = {nil=>\'N/A\',\'\'=>\'N/A\'}\r\n        tmp = {}\r\n        get_model[model].all.each do |i|\r\n            tmp[i.id.to_s] = i\r\n        end\r\n        return tmp\r\n    end\r\n    \r\n    @rs_visit = map_model :visit_type\r\n    @rs_prov  = map_model :provider\r\n    @rs_indi  = map_model :indication\r\n    @rs_proc  = map_model :procedure\r\n%>',NULL,NULL,NULL,'2016-11-29 06:23:02','2016-11-29 06:23:02','params_config',''),(2774,'document_name',1124,1,'\'obgyn\'',NULL,NULL,NULL,'2016-11-29 06:49:21','2016-11-29 06:49:21',NULL,NULL),(2776,'form',994,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n    var ts_field = \"data-arrival_time\";\r\n    var te_field = \"data-discharge_time\";\r\n    var tt_field = \"data-total_recovery_time\";\r\n    function update_time() {\r\n        var ts = $(\'#\' + ts_field).val();\r\n        var te = $(\'#\' + te_field).val();\r\n        // console.log(\'ts: \' + ts + \", te: \" + te);\r\n        \r\n        var t_s = new Date(\"<%= Time.now.strftime(\'%m/%d/%Y\') %> \" + ts);\r\n        var t_e = new Date(\"<%= Time.now.strftime(\'%m/%d/%Y\') %> \" + te);\r\n        // console.log(\'t_s: \' + t_s + \', t_e: \' + t_e);\r\n        \r\n        var t_d = (t_e - t_s)/60000;\r\n        // console.log(\'t_d: \' + t_d);\r\n        \r\n        $(\'#\' + tt_field).val(t_d);\r\n    }\r\n    \r\n    \r\n    $(\'#\' + ts_field).change(update_time)\r\n    $(\'#\' + te_field).change(update_time)\r\n    if ($(\'#\' + tt_field).val() === \'\') { \r\n        $(\'#\' + tt_field).val(0)\r\n    }\r\n</script>',NULL,NULL,NULL,'2016-12-01 16:48:15','2016-12-01 16:48:15','form',''),(2777,'patient_or',1061,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n    prov = {}\r\n    get_model[:provider].all.each do |i|\r\n        prov[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\' and i.name!=\'billing\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n    # locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name if user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n<div class=\"span4\">\r\n\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th>Time</th><th>Staff</th><th>Action</th></tr>\r\n</thead>\r\n\r\n<% \r\n    services.each_with_index do |s,index|\r\n        module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n        records = patient_module_model.first :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n        \r\n        if !records.nil?\r\n            mid = records[:module_id]\r\n            rec = get_model[s.name.to_sym].find(mid)\r\n            \r\n            if s.name == \'pre_operative\'\r\n%>\r\n\r\n<tr><td><%= rec[:done_date].strftime(\'%d/%m/%Y\') %> <%= rec[:done_time].strftime(\'%H:%M\') %> </td><td><%= prov[rec[:pre_done_by].to_s] %></td><td><%= s %></td></tr>\r\n<%\r\n            elsif s.name = \'intra_operative\'\r\n%>\r\n<tr><td><%= rec[:done_date].strftime(\'%d/%m/%Y\') %> <%= rec[:done_time].strftime(\'%H:%M\') %> </td><td><%= prov[rec[:pre_done_by].to_s] %></td><td><%= s %></td></tr>\r\n<%\r\n            end\r\n        end\r\n    end\r\n%>\r\n</table>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2016-12-02 02:38:44','2016-12-02 02:38:44','patient_or',''),(2778,'context_menu',1126,4,'<div class=\"accordion-group\">\r\n	<div class=\"accordion-heading\">\r\n		<a href=\"#collapse-0\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n		Dashboard\r\n		</a>\r\n		<div class=\"accordion-body collapse in\" id=\"collapse-0\">\r\n			<div class=\"accordion-inner\">\r\n				<ul class=\"nav nav-list\">\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"index\">Overview</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"case_report\">Case Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"intervention_report\">Intervention Report</a></li>\r\n				</ul>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n',NULL,NULL,NULL,'2016-12-02 03:21:16','2016-12-02 03:21:16','context_menu',''),(2779,'index',1126,2,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    patients =  module_model.all(:module_name=>mname)\r\n    \r\n    \r\n    list = []\r\n    \r\n    \r\n    \r\n    list = module_model.collection.group({:keyf=>\'function(doc){return {month:doc.date.getMonth(),name:doc.module_name};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}})\r\n          \r\n          \r\n        columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n   \r\n    map = {}\r\n    data = []\r\n\r\n    if list.size>0    \r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    name = i[\'name\'].split(\'#\')[1]\r\n    map[name] = {\'name\'=>name.humanize, \'data\'=>[]} unless map[name] \r\n    map[name][\'data\'][i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\n    end\r\n    map.each_pair do |k,v|\r\n    if k!=\'appointment\'\r\n        data<<v    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n   \r\n    columns = mlabels\r\n\r\n%>\r\n\r\n<h3>Summary</h3>\r\n\r\n<%\r\n\r\n%>\r\n\r\n<div id=\"chart\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n\r\n            <script>\r\n                function createChart() {\r\n                    $(\"#chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                }\r\n\r\n                $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n                });\r\n            </script>\r\n\r\n\r\n',NULL,NULL,NULL,'2016-12-02 03:22:09','2016-12-02 03:22:09','index',''),(2780,'case_report',1126,2,'<%= render :inline=>this.init %>\r\n<%\r\n    session[:case_report] = {} if session[:case_report].nil?\r\n    session[:case_report][:sdate] =  Time.now.at_beginning_of_month.strftime(\"%d/%m/%Y\") if session[:case_report][:sdate].nil? \r\n    session[:case_report][:edate] =  Time.now.at_end_of_month.strftime(\"%d/%m/%Y\") if session[:case_report][:sdate].nil? \r\n    \r\n    # service list\r\n    sl = %w{bronchoscopy pleuroscopy history post_operative thoracentesis ebus}\r\n    \r\n    res = nil\r\n    \r\n    sdate = session[:case_report][:sdate]\r\n    edate = session[:case_report][:edate]\r\n    \r\n    if q = params[:query]\r\n        res = {}\r\n        sdate = q[:sdate]\r\n        edate = q[:edate]\r\n        \r\n        session[:case_report][:sdate] = sdate\r\n        session[:case_report][:edate] = edate\r\n        \r\n    end\r\n    \r\n    app = get_appointment_by_date(sdate, edate)\r\n    app_ids = app.collect{|i| i.id.to_s}\r\n    pat_mod = get_patient_module_by_appointment_ids(app_ids)\r\n    par_ids = []\r\n    pat_ids = []\r\n    par_pat = {}\r\n    pat_mod.each do |i|\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id].to_s\r\n        par_pat[i.id.to_s] = i[:patient_id].to_s\r\n    end\r\n    \r\n    \r\n    \r\n    # form service\r\n	f_ser = {}\r\n	f_ser[:par_ids] = par_ids\r\n	# provider result\r\n	rs_prov = {}\r\n	# service list\r\n	sl.each do |k|\r\n	    k = k.to_sym\r\n	    f_ser[k] = {}\r\n	   # tmp = @m_pat_mod.collection.find({:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>{\'$in\'=>pat_mod.collect{|i| i.id}}}).to_a\r\n	    tmp = @m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>par_ids).all\r\n\r\n        f_ser[k][:par] = {}\r\n        f_ser[k][:mid] = []\r\n	        \r\n	    tmp.each do |i|\r\n	        f_ser[k][:par][i[:parent_id].to_s] = i.id.to_s\r\n	        f_ser[k][:mid] << i[:module_id]\r\n	    end\r\n	    \r\n	    mid = f_ser[k][:mid]\r\n	    if mid\r\n	        tmp_rs = get_model[k].collection.find({\'_id\'=>{\'$in\'=>mid}},{:fields=>{\'_id\'=>1,\'endoscopist_1\'=>1}}).to_a\r\n	        f_ser[k][:res] = tmp_rs\r\n	        f_ser[k][:prov] = tmp_rs.group_by{|i| i[\'endoscopist_1\']}\r\n	    else\r\n	        f_ser[k][:res] = []\r\n	        f_ser[k][:prov] = {}\r\n	    end\r\n	    \r\n	end\r\n	\r\n# 	all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n#     all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n#     m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n	\r\n	res = {}\r\n	res[:fser] = f_ser\r\n    \r\n%>\r\n\r\n<h1>Case Report</h1>\r\n\r\n\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n    \r\n    \r\n    .page {\r\n        width: 21cm;\r\n        min-height: 29.7cm;\r\n        padding: 2cm;\r\n        margin: 1cm auto;\r\n        border: 1px #D3D3D3 solid;\r\n        border-radius: 5px;\r\n        background: white;\r\n        box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);\r\n    }\r\n\r\n    @page {\r\n        size: A4;\r\n        margin: 0;\r\n    }\r\n    \r\n    @media print {\r\n        .page {\r\n            margin: 0 ;\r\n            border: initial;\r\n            border-radius: initial;\r\n            width: initial;\r\n            min-height: initial;\r\n            box-shadow: initial;\r\n            background: initial;\r\n            /*page-break-after: always;*/\r\n            font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\r\n            font-size: 10px;\r\n            /*line-height: 18px;*/\r\n            color: #333333;\r\n        }\r\n        body * {\r\n            visibility: hidden;\r\n        }\r\n        table, th, td {\r\n            border: 1px solid black;\r\n        }\r\n        tr    { page-break-inside:avoid; page-break-after:auto }\r\n        #printarea, #printarea * {\r\n            visibility: visible;\r\n        }\r\n        #printarea {\r\n            position: absolute;\r\n            left: 0;\r\n            top: 0;\r\n        }\r\n    }\r\n</style>\r\n<div class=\'row-fluid\'>\r\n    <div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Search\r\n			</div>\r\n			<div class=\"w-box-content cnt_a alert-success\" style=\"\"> \r\n				<%=form_for :query, :url=>params[:opt],:html=>{:style=>\'margin-bottom:0px\'}  do |f| %>\r\n            \r\n           \r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">Start Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :sdate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'start-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <label class=\"field-label\">End Date : </label>\r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.text_field :edate, :value=>Time.now.strftime(\"%d/%m/%Y\"),:id=>\'end-date\',:style=>\"width:100%\"%>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\"> \r\n                                    <div class=\"field-input\" >\r\n                                        <%= f.submit \'Submit\', :class=>\'btn btn-success\' %>\r\n                                    </div>\r\n                                </span>\r\n                                <span class=\"field-data\" style=\'float:right\'> \r\n                                    <div class=\"field-input\" style=\"float:right\">\r\n                                        <%= link_to \'Export\', \'javascript:void(0)\', :style=>\'float:right;margin-top:5px\', :onclick=>\'javascript:window.print()\', :class=>\'btn btn-info\' %>\r\n                                        <%= link_to \'Print\', \'javascript:void(0)\', :style=>\'float:right;margin-top:5px\', :onclick=>\'javascript:window.print()\', :class=>\'btn btn-info\' %>\r\n                                    </div>\r\n                                </span>\r\n                                \r\n<script>\r\n    $(\"#start-date\").kendoDatePicker({\r\n        value: \'<%= session[:case_report][:sdate] %>\'\r\n	});\r\n	$(\"#end-date\").kendoDatePicker({\r\n        value: \'<%= session[:case_report][:edate] %>\'\r\n	});\r\n</script>\r\n<% end %>\r\n                <p><br/><br/></p>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<div class=\'clear\' style=\'margin-top:10px\'></div>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\'>\r\n        <div class=\"w-box-header\">\r\n				Result\r\n			</div>\r\n        <div class=\"w-box-content cnt_a \" style=\"\"> \r\n            <div class=\"row-fluid\" style=\"padding:5px\">\r\n                <div >\r\n                    <div id=\'printarea\' class=\'page\'>\r\n                        <h1>Provider Report from <%= session[:case_report][:sdate] %> to <%= session[:case_report][:edate] %></h1>\r\n                            <br/>\r\n                                \r\n<style type=\"text/css\">\r\n.tg  {border-collapse:collapse;border-spacing:0;}\r\n.tg td{font-family:Arial, sans-serif;padding:10px 5px;border-style:solid;border-width:1px;overflow:hidden;word-break:normal;}\r\n.tg th{font-family:Arial, sans-serif;font-weight:normal;padding:10px 5px;border-style:solid;border-width:1px;overflow:hidden;word-break:normal;}\r\n.tg .tg-yzt1{background-color:#efefef;vertical-align:top}\r\n.tg .tg-yw4l{vertical-align:top}\r\n</style>\r\n<table class=\"tg\" style=\"undefined;table-layout: fixed; width: 100%\">\r\n<!--<colgroup>-->\r\n<!--<col style=\"width: 166px\">-->\r\n<!--<col style=\"width: 200px\">-->\r\n<!--<col style=\"width: 142px\">-->\r\n<!--</colgroup>-->\r\n  <tr>\r\n    <th class=\"tg-yzt1\">Name</th>\r\n<% sl.each do |i| %>\r\n    <th class=\"tg-yzt1\"><%= i.humanize %></th>\r\n<% end %>\r\n    <th class=\"tg-yzt1\">Total Cases</th>\r\n  </tr>\r\n<%\r\n    t_ser = {}\r\n    get_model[:provider].where(:provider_type=>\'1\').all.each do |i|\r\n%>\r\n  <tr>\r\n    <td class=\"tg-yw4l\"><%= i[:name] %></td>\r\n<% \r\n        sum = 0\r\n        sl.each do |j| \r\n            k = j.to_sym\r\n            if !t_ser.has_key? k\r\n                t_ser[k] = 0\r\n            end\r\n            \r\n            x = f_ser[k][:prov][i.id]\r\n            if !x.nil?\r\n                sum += x.size\r\n                t_ser[k] += x.size\r\n            end\r\n%>\r\n    <td class=\"tg-yw4l\"><center><%= x.nil? ? \'0\' : x.size %></center></th>\r\n<% end %>\r\n    <td class=\"tg-yw4l\"><center><%= sum %></center></td>\r\n  </tr>\r\n<%\r\n    end\r\n%>\r\n  <tr>\r\n    <td class=\"tg-yw4l\">Total</td>\r\n<% \r\n        sum = 0\r\n        sl.each do |j| \r\n            k = j.to_sym\r\n%>\r\n    <th class=\"tg-yw4l\"><center><%= t_ser[k] %></center></th>\r\n<% end %>\r\n    <td class=\"tg-yw4l\"><center>-</center></td>\r\n  </tr>\r\n</table>\r\n                                \r\n                                \r\n                    </div>\r\n                        \r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n',NULL,NULL,NULL,'2016-12-02 03:45:50','2016-12-02 03:45:50','case_report',''),(2781,'init',1126,4,'<%\r\n    def get_map(arr)\r\n        rs = {}\r\n        arr.each do |i|\r\n            rs[i.id.to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @m_ehr = ehr.load_model\r\n    @m_pat = @m_ehr[:patient]\r\n    @m_pat_mod = @m_ehr[:patient_module]\r\n\r\n    @models = get_model\r\n    \r\n    def get_appointment_by_date(sdate = Time.now.strftime(\'%d/%m/%Y\'), edate = Time.now.strftime(\'%d/%m/%Y\'))\r\n        sdate = Time.strptime(sdate, \"%d/%m/%Y\")\r\n        edate = Time.strptime(edate, \"%d/%m/%Y\")\r\n        cond = {}\r\n        cond[:date] = {\'$gte\'=>sdate.beginning_of_day,\'$lt\'=>edate.end_of_day}\r\n        rs = @models[:appointment].where(cond).all\r\n        return rs\r\n    end\r\n    \r\n    def get_patient_module_by_appointment_ids(app_ids = [])\r\n        return @m_pat_mod.where(:module_id=>app_ids).all\r\n    end\r\n    \r\n    def get_patient_module_document_by_patient_module_appointment(par_ids = [], mod_name = \'\')\r\n        return @m_pat_mod.where(:parent_id=>par_ids, :module_name=>mod_name).all\r\n    end\r\n    \r\n    def get_patient_module_by_document_ids(mod_name, mod_ids)\r\n        return @m_pat_mod.where(:module_name=>mod_name, :module_id=>mod_ids).all\r\n    end\r\n    \r\n    def get_module_id_array(patient_module_array = [])\r\n        return patient_module_array.collect{|i| i[:module_id].to_s}\r\n    end\r\n    \r\n    def get_module_id_map(pat_mod_arr = [])\r\n        rs = {}\r\n        pat_mod_arr.each do |i|\r\n            rs[i[:module_id].to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n    \r\n    @map_login = {\'\'=>\'Unknown\', nil=>\'Unknown\'}\r\n    @provider = {\'\'=>\'N/A\', nil=>\'N/A\'}\r\n    @prov_type = {\'\'=>\'N/A\', nil=>\'N/A\'}\r\n    \r\n    a_prov = @models[:provider].all\r\n    a_prov.each do |i|\r\n        @provider[i.id.to_s] = i[:name]\r\n        @map_login[i[:login]] = i[:name]\r\n    end\r\n%>',NULL,NULL,NULL,'2016-12-02 03:50:05','2016-12-02 03:50:05','init',''),(2782,'document_name',1127,1,'\'doctor_time\'',NULL,NULL,NULL,'2016-12-05 01:50:05','2016-12-05 01:50:05',NULL,NULL),(2783,'document_name',1128,1,'\'log_timee\'',NULL,NULL,NULL,'2016-12-05 01:53:43','2016-12-05 01:53:43',NULL,NULL),(2784,'document_name',1129,1,'\'log_time\'',NULL,NULL,NULL,'2016-12-05 01:54:42','2016-12-05 01:54:42',NULL,NULL),(2785,'room_index',1061,2,'<%\r\n    if session[:status].nil?\r\n        session[:status] = \'\'\r\n    end\r\n    if session[:room].nil?\r\n        session[:room] = \'All\'\r\n    end\r\n	\r\n	if params[:room]\r\n	    session[:room] = params[:room]\r\n	end\r\n	if params[:status]\r\n	    session[:status] = params[:status]\r\n	end\r\n	\r\n	if l_id = params[:reset_lock]\r\n        m_lock = get_model[:locker]\r\n        lock = m_lock.find(l_id)\r\n        lock.destroy if lock\r\n    end\r\n    \r\n    if params[:status] and params[:aid]\r\n        app = get_model[:appointment].find(params[:aid])\r\n        app[:status] = params[:status]\r\n        app.save\r\n    end\r\n	\r\n    partial = \'room_index_partial\'\r\n    recheck_time = 10000\r\n\r\n	cur_status = session[:status]\r\n	cur_room   = session[:room]\r\n  \r\n    date = Time.now.strftime(\"%d/%m/%Y\")\r\n    if params[:date]\r\n        date = params[:date]\r\n    end\r\n    qdate = Date.to_mongo(params[:date])\r\n    \r\n    \r\n    a_app = get_model[:appointment].where(:date=>qdate).all\r\n    \r\n%>\r\n<!--\r\n<style>\r\n    @media screen and (max-width: 600px) {\r\n\r\n        table {\r\n          border: 0;\r\n        }\r\n    \r\n        table thead {\r\n          display: none;\r\n        }\r\n    \r\n        table tr {\r\n          margin-bottom: 10px;\r\n          display: block;\r\n          border-bottom: 2px solid #ddd;\r\n        }\r\n    \r\n        table td {\r\n          display: block;\r\n          text-align: right;\r\n          font-size: 13px;\r\n          border-bottom: 1px dotted #ccc;\r\n        }\r\n    \r\n        table td:last-child {\r\n          border-bottom: 0;\r\n        }\r\n    \r\n        table td:before {\r\n          content: attr(data-label);\r\n          float: left;\r\n          text-transform: uppercase;\r\n          font-weight: bold;\r\n        }\r\n        \r\n    }\r\n</style>\r\n-->\r\n\r\n<div id=\'cnt_nurse\'>\r\n\r\n<br/><br/><center>... Loading ...</center>\r\n\r\n</div>\r\n<div id=\'msg\'></div>\r\n\r\n<script>\r\n    \r\n    var to_obj;\r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_status_json?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    clearTimeout(to_obj);\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'<%= partial %>?date=<%=date%>&room=<%=session[:room]%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(\'#cnt_nurse\').fadeOut(fade, function(){\r\n                        $(\'#cnt_nurse\').html(data);\r\n                    })\r\n                    $(\'#cnt_nurse\').fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n    var li = 0;\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        li++;\r\n        $.getJSON( \"../Home/last_updated?date=<%=date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            console.log(\'Found updated! Loading... [\' + li + \']\');\r\n            // executeQuery();\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        tt = <%= recheck_time %>;\r\n        console.log(\'Recheck in \' + tt + \' ms. [\' + li + \']\');\r\n        clearTimeout(to_obj);\r\n        setTimeout(loadPartial, tt);\r\n        \r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        setTimeout(feed_page(100), 0);\r\n        loadPartial();\r\n    });\r\n    \r\n    refresh_remote();\r\n</script>\r\n',NULL,NULL,NULL,'2016-12-05 02:54:37','2016-12-05 02:54:37','room_index',''),(2786,'room_index_partial',1061,3,'<%= render :inline=>this.params_config %>\r\n<%= render :inline=>this.common_query %>\r\n<%\r\n    date = @date\r\n    \r\n    main_service = \'room_index\'\r\n    \r\n    all_ser = {}\r\n    @rs_serv.keys.each do |i|\r\n        k = i.to_sym\r\n        all_ser[k] = {}\r\n        get_model[k].find(@mid_ser[i]).each do |j|\r\n            all_ser[k][j.id.to_s] = j\r\n        end\r\n    end\r\n    \r\n    def val rec, field\r\n        f = field.to_sym\r\n        return (rec[f].nil? or rec[f]==\'\') ? \'-\' : rec[f]\r\n    end\r\n    \r\n    today = Time.now\r\n    \r\n    s_list = @status_list\r\n    \r\n    res = []\r\n    @rs_app.each do |i|\r\n        m = @rs_pat_mod[i.id.to_s]\r\n        pat = @rs_pat[m[:patient_id].to_s]\r\n        pat_id = pat.id.to_s\r\n        \r\n            age = \'-\'\r\n            if pat[:birth_date]\r\n                diff = Time.diff(today, pat[:birth_date])\r\n                year = diff[:year]\r\n                month = diff[:month]\r\n                day = diff[:day]\r\n                age = \"\\\\#{year}y.\\\\#{month}m.\"\r\n            end\r\n            \r\n        prov = \'N/A\'\r\n        if i[:provider]\r\n            tmp = @rs_prov[i[:provider].to_s][:name]\r\n            prov = tmp\r\n        end\r\n        \r\n        ward = \'N/A\'\r\n        if i[:visit_base] == \'OPD\'\r\n            ward = i[:visit_base]\r\n        elsif i[:visit_base] == \'IPD\'\r\n            ward = i[:ward]\r\n        end\r\n        \r\n        room = @rs_room[i[:room].to_s]\r\n        \r\n        # if session[:room] == \'N/A\'\r\n        #     if room != \'N/A\'\r\n        #         next\r\n        #     end\r\n        # end\r\n            \r\n        if session[:room] != room and session[:room] != \'All\'\r\n            next\r\n        end\r\n        \r\n        \r\n        r = {}\r\n        r[:id]   = i.id.to_s\r\n        r[:room] = room\r\n        r[:start] = (i[:start].nil? or i[:start] == \'\') ? \'-\' : i[:start].strftime(\'%H:%M\')\r\n        r[:stop]  = (i[:stop].nil? or i[:stop] == \'\') ? \'-\' : i[:stop].strftime(\'%H:%M\')\r\n        r[:time]  = r[:start]\r\n        r[:surgeon] = prov\r\n        r[:anesth] = val(i, :anesth_technique)\r\n        r[:dx] = i[:diagnosis_1]\r\n        r[:op] = i[:tentative_operation]\r\n        r[:ward] = ward\r\n        r[:hn]  = pat[:hn]\r\n        r[:age] = age\r\n        r[:pat_id]   = pat_id\r\n        r[:pat_name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]} \\\\#{pat[:last_name]}\"\r\n        r[:status] = i[:status]\r\n        r[:link] = {}\r\n        \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-mini btn-info \', :style=>\'width:45px\')\r\n                l_list = []\r\n                @service_map.each do |k, v|\r\n                    lab = k.to_s.split(\'_\')[0].humanize\r\n                    v_link = link_to(\"+ \\\\#{lab}\".html_safe, \r\n                        \"../\\\\#{v}/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{pat[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/\\\\#{main_service}?date=\\\\#{@p_date}\", \r\n                        :class=>\'btn btn-mini \', :style=>\'width:45px\' )\r\n                    if x = @rs_serv[k][pat_id]\r\n                        v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            \"../\\\\#{v}/show?id=\\\\#{x}&return=../Home/\\\\#{main_service}?date=\\\\#{@p_date}\", :class=>\'btn btn-mini btn-success\', :style=>\'width:45px\')\r\n                    end\r\n                    r[:link][k] = v_link\r\n                    l_list << v_link\r\n                end\r\n        r[:d_link] = d_link\r\n        r[:l_link] = l_list\r\n        # r[:pat] = pat\r\n        res << r\r\n    end\r\n    \r\n    res = res.compact\r\n    \r\n    # group by status\r\n    sg = res.group_by{|i| i[:status]}\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				<b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b>\r\n               \r\n                <div style=\"float:right\">\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %>\r\n					<%= Time.now.strftime(\'%H:%M\') %>\r\n					<%=link_to \"Today\", \"../Home/\\\\#{main_service}?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/<%= main_service %>?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center>\r\n				    \r\n                </center>\r\n				<br/>\r\n				<center>\r\n				\r\n<%\r\n    tmp = {}\r\n    if sg[\'Processing\']\r\n        tmp = sg[\'Processing\'].sort_by{|i| [i[:room],i[:start]]}.group_by{|i| i[:room]}\r\n    end\r\n    \r\n    @rs_room_list = [\'All\'] + @rs_room_list\r\n    @rs_room_list.each do |i|\r\n        txt = \"\"\r\n        icon = \'<i class=\"splashy-information\"></i>\'.html_safe\r\n        if tmp[i]\r\n            r = tmp[i][0]\r\n            hn = r[:hn]\r\n            pat = r[:pat_name].split(\' \')[0]\r\n            icon = \'<i class=\"splashy-warning\"></i>\'.html_safe\r\n            txt = \"<br/>HN: <b>\\\\#{hn}</b><br/>\\\\#{pat}\".html_safe\r\n        end\r\n%> \r\n                    <a href=\"<%= main_service %>?date=<%=@p_date%>&room=<%= i.html_safe %>\">\r\n                        <button class=\"btn\">\r\n                            <%= icon %>\r\n                            <br />Room <b><%= i %></b>\r\n                            <%= txt %>\r\n                        </button>\r\n                    </a>\r\n<%\r\n    end\r\n%>\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n\r\n\r\n<!-- Status : Processing -->\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span-12\'>\r\n        <div class=\'w-box\'>\r\n            <div class=\'w-box-header\'  style=\'font-size:1.5em\'>\r\n                Processing\r\n            </div>\r\n            <div class=\'w-box-content cnt_a \' style=\'background:#FCF8F0\'>\r\n<%\r\n    s_idx = s_list.index(\'Processing\')\r\n    tmp.each do |k, v|\r\n        r = v[0]\r\n%>\r\n                <div class=\'row-fluid\'>\r\n                    <div id=\'header-room-<%= k %>\'>\r\n                        <div class=\'span2 alert alert-info\'>\r\n                            <span style=\'font-size:1.5em\'><b>Room :</b> <%= k %></span>\r\n                        </div>\r\n                        <div class=\'span4 alert alert-info\'>\r\n                            <span style=\'font-size:1.5em\'><b>Surgeon :</b> <%= r[:surgeon] %></span>\r\n                        </div>\r\n                        <div class=\'span3 alert alert-info\'>\r\n                            <span style=\'font-size:1.5em\'><b>Time :</b> <%= r[:start] %> - <%= r[:stop] %></span>\r\n                        </div>\r\n                        <div class=\'span3 alert alert-info\'>\r\n                            <span style=\'font-size:1.5em\'><b>Action :</b> <%= r[:link][:intra_operative] %> <%= r[:d_link] %></span>\r\n                        </div>\r\n                    </div>\r\n                                        <table class=\"table table-striped table-bordered table-condensed\">\r\n    										<thead>\r\n    											<tr>\r\n    												<th>&nbsp;</th>\r\n    												<th>Ward</th>\r\n    												<th>HN</th>\r\n    												<th>Name</th>\r\n    												<th>Age</th>\r\n    												<th>Anesth</th>\r\n    												<th>Diagnosis</th>\r\n    												<th>Operation</th>\r\n    												<th>&nbsp;</th>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n    											<tr>\r\n    												<td><center><%= link_to \'<i class=\"splashy-arrow_state_blue_left\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{r[:id]}\',\'\\\\#{s_list[s_idx-1]}\',\'\')\", :class=>\'\' %></center></td>\r\n    												<td><%= r[:ward] %></td>\r\n    												<td><%= r[:hn] %></td>\r\n    												<td><%= r[:pat_name] %></td>\r\n    												<td><%= r[:age] %></td>\r\n    												<td><%= r[:anesth] %></td>\r\n    												<td><%= r[:dx] %></td>\r\n    												<td><%= r[:op] %></td>\r\n    												<td><center><%= link_to \'<i class=\"splashy-arrow_state_blue_right\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{r[:id]}\',\'\\\\#{s_list[s_idx+1]}\',\'\')\", :class=>\'\' %></center></td>\r\n    											</tr>\r\n    										</tbody>\r\n    									</table>\r\n                        <br/>\r\n                    \r\n                    <div class=\'clear\'></div>\r\n                </div>\r\n<%\r\n    end\r\n    \r\n    if tmp.size == 0\r\n%>\r\n\r\n                <div class=\'row-fluid\'>\r\n                    <br/><br/>\r\n                    <center><h3>No Processing Patient.</h3></center>\r\n                    <br/><br/>\r\n                </div>\r\n\r\n<%\r\n    end\r\n%>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<!-- Status : Ready / Waiting / Pre-op -->\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span-12\'>\r\n        <div class=\'w-box\'>\r\n            <div class=\'w-box-header\'  style=\'font-size:1.5em\'>\r\n                Ready / Waiting / Pre-op / Appointed\r\n            </div>\r\n            <div class=\'w-box-content cnt_a \'>\r\n<%\r\n    # temp status\r\n    ts = %w{Appointed Pre-op Waiting Ready}\r\n    (ts.size - 1).downto(0) do |i|\r\n        s_idx = s_list.index(ts[i])\r\n        tmp = {}\r\n        if sg[ts[i]]\r\n            # tmp = sg[ts[i]].sort_by{|i| [i[:room],i[:start]]}.group_by{|i| i[:room]}\r\n            tmp = sg[ts[i]].sort_by{|i| [i[:room],i[:start]]}\r\n        end\r\n        # tmp.each do |k, v|\r\n            s = :pre_operative\r\n        if tmp.size == 0\r\n%>\r\n                <div class=\'row-fluid\'>\r\n                    <!--<div id=\'header-status-<%= ts[i] %>\'>-->\r\n                        <div class=\'span2 alert\'>\r\n                            <span style=\'font-size:1.5em\'><b>Status :</b> <%= ts[i] %></span>\r\n                        </div>\r\n                    <!--</div>-->\r\n                    <div class=\'alert\'>\r\n                        <br/><br/>\r\n                        <center><h3>No <%= ts[i] %> Patient.</h3></center>\r\n                        <br/><br/>\r\n                    </div>\r\n                </div>\r\n\r\n<%\r\n        else\r\n%>\r\n                <div class=\'row-fluid\'>\r\n                    <div id=\'header-status-<%= ts[i] %>\'>\r\n                        <div class=\'span2 alert alert-success\'>\r\n                            <span style=\'font-size:1.5em\'><b>Status :</b> <%= ts[i] %></span>\r\n                        </div>\r\n                        <div class=\'span2 alert alert-success\'>\r\n                            <span style=\'font-size:1.5em\'><b>Patient(s) :</b> <%= tmp.size %> </span>\r\n                        </div>\r\n                    </div>\r\n                    <table class=\"table table-striped table-bordered table-condensed\">\r\n    										<thead>\r\n    											<tr>\r\n    												<th>&nbsp;</th>\r\n    												<th width=\'5%\'>Room</th>\r\n    												<th>Time</th>\r\n    												<th>Ward</th>\r\n    												<th  width=\'20%\'>Patient Info.</th>\r\n    												<th>Anesth</th>\r\n    												<th  width=\'20%\'>Dx. / Op.</th>\r\n    												<th  width=\'3%\'>T</th>\r\n    												<th  width=\'3%\'>BP</th>\r\n    												<th  width=\'3%\'>HR</th>\r\n    												<th  width=\'3%\'>RR</th>\r\n    												<th  width=\'3%\'>SpO<sub>2</sub></th>\r\n    												<th>Action</th>\r\n    												<th>&nbsp;</th>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n            tmp.each do |r|\r\n            # v.each do |r|\r\n                rid = @mid_map[s][r[:pat_id]]\r\n                rec = {}\r\n                if rid\r\n                    rec = all_ser[s][rid]\r\n                end\r\n                f = %w{t bp hr rr spo}\r\n                c = \'<i class=\"splashy-remove_minus_sign_small\"></i>\'.html_safe\r\n                \r\n                \r\n%>\r\n    											<tr>\r\n    												<td style=\'vertical-align:middle\'><center><%= link_to \'<i class=\"splashy-arrow_state_blue_left\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{r[:id]}\',\'\\\\#{s_list[s_idx-1]}\',\'\')\", :class=>\'\' %></center></td>\r\n    												<td style=\'vertical-align:middle\'><%= r[:room] %></td>\r\n    												<td style=\'vertical-align:middle\'><%= r[:start] %> - <%= r[:stop] %></td>\r\n    												<td style=\'vertical-align:middle\'><%= r[:ward] %></td>\r\n    												<td style=\'vertical-align:middle\'><b>HN: </b><%= r[:hn] %>, <b>Name: </b><%= r[:pat_name] %><br/><b>Age: </b><%= r[:age] %> </td>\r\n    												<td style=\'vertical-align:middle\'><%= r[:anesth] %></td>\r\n    												<td style=\'vertical-align:middle\'><b>Dx: </b><%= r[:dx] %><br/><b>Op: </b><%= r[:op] %></td>\r\n    												<% \r\n    												    f.each do |x| \r\n    												        x = x.to_sym\r\n    												        if !rec[x].nil? and rec[x] != \'\'\r\n    												            c = \"<i class=\'splashy-check\' title=\'\\\\#{x.to_s.upcase}: \\\\#{rec[x]}\'></i>\".html_safe\r\n        												    end\r\n    												%>\r\n    												<td style=\'vertical-align:middle\'><center><%= c %></center></td>\r\n    												<% end %>\r\n    												<td style=\'vertical-align:middle\'><%= r[:link][s] %>&nbsp;&nbsp;<%= r[:link][:intra_operative] %>&nbsp;&nbsp;<%= r[:d_link] %></td>\r\n    												<td style=\'vertical-align:middle\'><center><%= link_to \'<i class=\"splashy-arrow_state_blue_right\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{r[:id]}\',\'\\\\#{s_list[s_idx+1]}\',\'\')\", :class=>\'\' %></center></td>\r\n    											</tr>\r\n<%\r\n                end\r\n%>\r\n    										</tbody>\r\n    									</table>\r\n                        <br/>\r\n                    \r\n                    <div class=\'clear\'></div>\r\n                </div>\r\n<%\r\n        end\r\n    \r\n        if tmp.size == 0\r\n%>\r\n\r\n\r\n<%\r\n        end\r\n    end\r\n%>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<!-- Status : Recovery -->\r\n<!-- Status : Post-op -->\r\n<!-- Status : ICU -->\r\n<!-- Status : Discharged -->\r\n<%\r\n    # temp status\r\n    ts = %w{Recovery Post-op ICU Discharged}\r\n    0.upto(ts.size - 1) do |i|\r\n        s_idx = s_list.index(ts[i])\r\n        tmp = {}\r\n        if sg[ts[i]]\r\n            tmp = sg[ts[i]].sort_by{|i| [i[:room],i[:start]]}\r\n        end\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span-12\'>\r\n        <div class=\'w-box\'>\r\n            <div class=\'w-box-header\'  style=\'font-size:1.5em\'>\r\n                <%= ts[i] %>\r\n            </div>\r\n            <div class=\'w-box-content cnt_a \'>\r\n<%\r\n        if tmp.size == 0\r\n%>\r\n                    <div class=\'alert\'>\r\n                        <br/><br/>\r\n                        <center><h3>No <%= ts[i] %> Patient.</h3></center>\r\n                        <br/><br/>\r\n                    </div>\r\n<%\r\n        else\r\n%>\r\n                <table class=\"table table-striped table-bordered table-condensed\">\r\n    										<thead>\r\n    											<tr>\r\n    												<th>&nbsp;</th>\r\n    												<th width=\'5%\'>Room</th>\r\n    												<th>Time</th>\r\n    												<th>Ward</th>\r\n    												<th  width=\'20%\'>Patient Info.</th>\r\n    												<th>Anesth</th>\r\n    												<th  width=\'20%\'>Dx. / Op.</th>\r\n    												<th>Action</th>\r\n    												<th>&nbsp;</th>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n\r\n<%\r\n            tmp.each do |r|\r\n%>\r\n                                                <tr>\r\n    												<td><center><%= link_to \'<i class=\"splashy-arrow_state_blue_left\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{r[:id]}\',\'\\\\#{s_list[s_idx-1]}\',\'\')\", :class=>\'\' %></center></td>\r\n    												<td style=\'vertical-align:middle\'><%= r[:room] %></td>\r\n    												<td style=\'vertical-align:middle\'><%= r[:start] %> - <%= r[:stop] %></td>\r\n    												<td style=\'vertical-align:middle\'><%= r[:ward] %></td>\r\n    												<td style=\'vertical-align:middle\'><b>HN: </b><%= r[:hn] %>, <b>Name: </b><%= r[:pat_name] %><br/><b>Age: </b><%= r[:age] %> </td>\r\n    												<td style=\'vertical-align:middle\'><%= r[:anesth] %></td>\r\n    												<td style=\'vertical-align:middle\'><b>Dx: </b><%= r[:dx] %><br/><b>Op: </b><%= r[:op] %></td>\r\n    												<td style=\'vertical-align:middle\'>\r\n    												\r\n    												    <%= r[:l_link].join(\' \').html_safe %>&nbsp;&nbsp;<%= r[:d_link] %>\r\n    												    \r\n    												</td>\r\n    												\r\n    												<td><center><%= link_to \'<i class=\"splashy-arrow_state_blue_right\"></i>\'.html_safe, \"javascript:update_status(\'\\\\#{r[:id]}\',\'\\\\#{s_list[s_idx+1]}\',\'\')\", :class=>\'\' %></center></td>\r\n    											</tr>\r\n<%\r\n            end\r\n        end\r\n%>\r\n    											\r\n    										</tbody>\r\n    									</table>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2016-12-05 02:55:30','2016-12-05 02:55:30','room_index_partial',''),(2787,'status_feed',1061,3,'<%\r\n    date = Time.now.strftime(\"%d/%m/%Y\")\r\n    if !params[:date].nil?\r\n        date = params[:date]\r\n    end\r\n    qdate = Date.to_mongo(date)\r\n\r\n    a_app = get_model[:appointment].where(:date=>qdate).all\r\n    \r\n    partial = \'status_feed_partial\'\r\n    recheck_time = 10000\r\n%>\r\n    <%= javascript_include_tag \"application\"  %>\r\n    <%= stylesheet_link_tag    \"application\"  %>\r\n\r\n<style type=\"text/css\">\r\nbody {\r\n    background: black;\r\n    font-family:Arial, sans-serif;\r\n    font-size:1.5em;\r\n    color:#efefef;\r\n    /*overflow:hidden;*/\r\n}\r\n.head {height:55px;line-height: 55px;font-family:Arial, sans-serif;font-size:1.2em;font-weight:normal;padding:10px 5px;border-style:solid;border-width:1px;overflow:hidden;word-break:normal;}\r\n.cont {height:55px;line-height: 30px;font-family:Arial, sans-serif;font-size:1.2em;padding:10px;border-style:solid;border-width:1px;overflow:hidden;word-break:normal;}\r\n.head-col_0 {font-weight:bold;font-size:1.2em;background-color:#680100;color:#efefef;text-align:center;vertical-align:middle;}\r\n.head-col_1 {font-weight:bold;font-size:1.2em;background-color:#643403;color:#efefef;text-align:center;vertical-align:middle;}\r\n.head-col_2 {font-weight:bold;font-size:1.2em;background-color:#013300;color:#efefef;text-align:center;vertical-align:middle;}\r\n.head-col_3 {font-weight:bold;font-size:1.2em;background-color:#010066;color:#efefef;text-align:center;vertical-align:middle;}\r\n.head-col_4 {font-weight:bold;font-size:1.2em;background-color:#1a001a;color:#efefef;text-align:center;vertical-align:middle;}\r\n.col_0 {background-color:#9a0000;color:#efefef;text-align:center;vertical-align:middle;}\r\n.col_1 {background-color:#963400;color:#efefef;text-align:center;vertical-align:middle;}\r\n.col_2 {background-color:#036400;color:#efefef;text-align:center;vertical-align:middle;}\r\n.col_3 {background-color:#00009b;color:#efefef;text-align:center;vertical-align:middle;}\r\n.col_4 {background-color:#330033;color:#efefef;text-align:center;vertical-align:middle;}\r\n\r\n.status-waiting{background-color:black;}\r\n.status-arrived {background-color:gray;}\r\n.status-preparing {background-color:#343434;}\r\n.status-processing {background-color:#cb0000;}\r\n.status-recovery {background-color:#013300;}\r\n.status-completed {background-color:#010066;color:#efefef;}\r\n\r\n\r\n.resize {font-size:1em;text-align:left;width:60%;float:left;}\r\n\r\n.tg  {border-collapse:collapse;border-spacing:0;}\r\n.tg td{font-family:Arial, sans-serif;font-size:1.2em;padding:10px 5px;border-style:solid;border-width:1px;overflow:hidden;word-break:normal;}\r\n.tg th{font-family:Arial, sans-serif;font-size:1.2em;font-weight:normal;padding:10px 5px;border-style:solid;border-width:1px;overflow:hidden;word-break:normal;}\r\n.tg .tg-7z4u{/*font-size:3em;font-family:\"Courier New\", Courier, monospace !important;;*/background-color:#036400;color:#efefef;text-align:center;vertical-align:middle;line-height:3em;}\r\n.tg .tg-cqae{/*font-size:3em;font-family:\"Courier New\", Courier, monospace !important;;*/background-color:#00009b;color:#efefef;text-align:center;vertical-align:middle;}\r\n.tg .tg-tr29{/*font-size:3em;font-family:\"Courier New\", Courier, monospace !important;;*/background-color:#963400;color:#efefef;text-align:center;vertical-align:middle;}\r\n.tg .tg-avgk{/*font-size:3em;font-family:\"Courier New\", Courier, monospace !important;;*/background-color:#1a001a;color:#efefef;text-align:center;vertical-align:middle;}\r\n/* preparing */\r\n.tg .tg-1s26{font-weight:bold;font-size:1.5em;background-color:#000000;color:#efefef;text-align:center;vertical-align:middle;}\r\n/* processing */\r\n.tg .tg-xne5{font-weight:bold;font-size:1.5em;background-color:#643403;color:#efefef;text-align:center;vertical-align:middle;}\r\n/* recovery */\r\n.tg .tg-jfbk{font-weight:bold;font-size:1.5em;background-color:#013300;color:#efefef;text-align:center;vertical-align:middle;line-height:2.5em;}\r\n/* completed */\r\n.tg .tg-eo60{font-weight:bold;font-size:1.5em;background-color:#330033;color:#efefef;text-align:center;vertical-align:middle;}\r\n::-webkit-scrollbar { \r\n    display: none; \r\n}\r\n\r\n/*Appointed Pre-op Waiting Ready Processing Recovery Post-op ICU Discharged*/\r\n.st-appointed{background:url(\'/esm/cusys/or_management/content/icon/grey-icon.png\');\r\n    width:20px;\r\n    height:20px;\r\n    margin:-5 0 0 -15;\r\n    background-size:cover;\r\n    position:absolute;}\r\n.st-pre-op{background:url(\'/esm/cusys/or_management/content/icon/yellow-icon.png\');\r\n    width:20px;\r\n    height:20px;\r\n    margin:-5 0 0 -15;\r\n    background-size:cover;\r\n    position:absolute;}\r\n.st-waiting{background:url(\'/esm/cusys/or_management/content/icon/seagreen-icon.png\');\r\n    width:20px;\r\n    height:20px;\r\n    margin:-5 0 0 -15;\r\n    background-size:cover;\r\n    position:absolute;}\r\n.st-ready{background:url(\'/esm/cusys/or_management/content/icon/green-icon.png\');\r\n    width:20px;\r\n    height:20px;\r\n    margin:-5 0 0 -15;\r\n    background-size:cover;\r\n    position:absolute;}\r\n.st-processing{background:url(\'/esm/cusys/or_management/content/icon/orange-icon.png\');\r\n    width:20px;\r\n    height:20px;\r\n    margin:-5 0 0 -15;\r\n    background-size:cover;\r\n    position:absolute;}\r\n.st-recovery{background:url(\'/esm/cusys/or_management/content/icon/sky-icon.png\');\r\n    width:20px;\r\n    height:20px;\r\n    margin:-5 0 0 -15;\r\n    background-size:cover;\r\n    position:absolute;}\r\n.st-icu{background:url(\'/esm/cusys/or_management/content/icon/red-icon.png\');\r\n    width:20px;\r\n    height:20px;\r\n    margin:-5 0 0 -15;\r\n    background-size:cover;\r\n    position:absolute;}\r\n.st-discharge{background:url(\'/esm/cusys/or_management/content/icon/blue-icon.png\');\r\n    width:20px;\r\n    height:20px;\r\n    margin:-5 0 0 -15;\r\n    background-size:cover;\r\n    position:absolute;}\r\n.st-post-op{background:url(\'/esm/cusys/or_management/content/icon/purple-icon.png\');\r\n    width:20px;\r\n    height:20px;\r\n    margin:-5 0 0 -15;\r\n    background-size:cover;\r\n    position:absolute;}\r\n    \r\n.name {display:block;width:100px;float:left;text-align:left;}\r\n.prov {display:block;width:100px;float:left;text-align:left;}\r\n.ward {display:block;width:80px;float:left;text-align:left;}\r\n.room {display:block;width:40px;float:left;text-align:left;}\r\n.stat {display:block;width:80px;float:left;text-align:left;}\r\n.note {display:block;width:100px;float:left;text-align:left;}\r\n\r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	position: fixed;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	/*background: url(http://smallenvelop.com/wp-content/uploads/2014/08/Preloader_11.gif) center no-repeat #fff;*/\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat;\r\n}\r\n</style>\r\n<body style=\'background:black;max-width:100%\'>\r\n\r\n    <div class=\'se-pre-con\'></div>\r\n\r\n    <div id=\'header\' style=\'height:80px;margin-top:30px;vertical-align:middle\'>\r\n        <span style=\'float:left;margin-left:80px;background-color:#000000;font-size:1.5em\'>\r\n            <%=@current_project.get_setting(\"report_title_1\")%>\r\n            <br/>\r\n        </span>\r\n        <span style=\'float:right;margin-right:80px\' id=\'date\'><%= qdate.strftime(\"%d %B %Y\") %></span>\r\n        <br/>\r\n        \r\n        <span style=\'font-size:1em;float:left;margin-top:30px;margin-left:80px\'>Operative Schedule</span>\r\n        <span style=\'float:right;margin-right:80px;margin-top:30px\' id=\'clock\'>xx:xx:xx</span>\r\n    </div>\r\n    \r\n    <div style=\"margin-top:20px;align:center;margin-left:1%;margin-left:1%\" id=\"table\">\r\n        <div id=\"board\"></div>\r\n    </div>\r\n    \r\n    <a href=\'index\' style=\'color:black;font-size:20px\'>Home</a>\r\n\r\n\r\n\r\n<script>\r\n    function executeQuery() {\r\n      $.ajax({\r\n        url: \'<%= partial %>?date=<%=date%>\',\r\n        success: function(data) {\r\n          //  alert(\"update\");\r\n          // do something with the return value here if you like\r\n          $(\'#board\').fadeOut(500, function(){\r\n            $(\'#board\').html(data);\r\n          })\r\n          $(\'#board\').fadeIn(500)\r\n        }\r\n      });\r\n    //   setTimeout(executeQuery, 10000); // you could choose not to continue on failure...\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n    var li = 0;\r\n    var to_obj;\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        li++;\r\n        $.getJSON( \"../Home/last_updated?date=<%=date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            console.log(\'Found updated! Loading... [\' + li + \']\');\r\n            executeQuery();\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        tt = <%= recheck_time %>;\r\n        console.log(\'Recheck in \' + tt + \' ms. [\' + li + \']\');\r\n        clearTimeout(to_obj);\r\n        setTimeout(loadPartial, tt);\r\n        \r\n    }\r\n    \r\n    var par_obj;\r\n    var interval_obj;\r\n    function toggle() {\r\n        if(shown) {\r\n            // element.hide();\r\n            element.fadeOut(\"slow\");\r\n            shown = false;\r\n        } else {\r\n            element.show();\r\n            shown = true;\r\n        }\r\n    }\r\n    \r\n    function startTime() {\r\n        var today = new Date();\r\n        var h = today.getHours();\r\n        var m = today.getMinutes();\r\n        var s = today.getSeconds();\r\n        m = checkTime(m);\r\n        s = checkTime(s);\r\n        // document.getElementById(\'txt\').innerHTML =\r\n        txt = h + \":\" + m + \":\" + s;\r\n        $(\'#clock\').html(txt);\r\n        var t = setTimeout(startTime, 500);\r\n    }\r\n    function checkTime(i) {\r\n        if (i < 10) {i = \"0\" + i};  // add zero in front of numbers < 10\r\n        return i;\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // run the first time; all subsequent calls will take care of themselves\r\n        setTimeout(executeQuery, 0);\r\n        loadPartial();\r\n        \r\n        startTime();\r\n    });\r\n\r\n    refresh_remote();\r\n</script>\r\n\r\n</body>',NULL,NULL,NULL,'2016-12-05 10:08:41','2016-12-05 10:08:41','status_feed','*'),(2788,'status_feed_partial',1061,3,'<%= render :inline=>this.params_config %>\r\n<%= render :inline=>this.common_query %>\r\n<%\r\n    # max row\r\n    mr = 8\r\n    # number of record\r\n    nr = @rs_app.size\r\n    # number of page\r\n    np = (nr / mr.to_f).ceil\r\n    # set javascript change time between page\r\n    change_time = 10000\r\n    \r\n    def val rec, field\r\n        f = field.to_sym\r\n        return (rec[f].nil? or rec[f]==\'\') ? \'-\' : rec[f]\r\n    end\r\n    \r\n    today = Time.now\r\n    \r\n    res = []\r\n    @rs_app.each do |i|\r\n        m = @rs_pat_mod[i.id.to_s]\r\n        pat = @rs_pat[m[:patient_id].to_s]\r\n        \r\n            age = \'-\'\r\n            if pat[:birth_date]\r\n                diff = Time.diff(today, pat[:birth_date])\r\n                year = diff[:year]\r\n                month = diff[:month]\r\n                day = diff[:day]\r\n                age = \"\\\\#{year}y.\\\\#{month}m.\"\r\n            end\r\n            \r\n        prov = \'N/A\'\r\n        if i[:provider]\r\n            tmp = @rs_prov[i[:provider].to_s][:name]\r\n            prov = tmp.split(\' \')[0]\r\n        end\r\n        \r\n        ward = \'N/A\'\r\n        if i[:visit_base] == \'OPD\'\r\n            ward = i[:visit_base]\r\n        elsif i[:visit_base] == \'IPD\'\r\n            ward = @rs_ward[i[:ward]]\r\n        end\r\n        \r\n        r = {}\r\n        \r\n        r[:room] = @rs_room[i[:room].to_s]\r\n        r[:start] = (i[:start].nil? or i[:start] == \'\') ? \'-\' : i[:start].strftime(\'%H:%M\')\r\n        r[:stop]  = (i[:stop].nil? or i[:stop] == \'\') ? \'-\' : i[:stop].strftime(\'%H:%M\')\r\n        r[:time]  = r[:start]\r\n        r[:surgeon] = prov\r\n        r[:anesth] = val(i, :anesth_technique)\r\n        r[:dx] = i[:diagnosis_1]\r\n        r[:op] = i[:tentative_operation]\r\n        r[:ward] = ward\r\n        r[:hn]  = pat[:hn]\r\n        r[:age] = age\r\n        r[:pat_name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]} \\\\#{pat[:last_name]}\"\r\n        r[:status] = i[:status]\r\n        # r[:pat] = pat\r\n        res << r\r\n    end\r\n    \r\n    # res += res\r\n    \r\n    res = res.sort_by{|i| [i[:room], i[:start]]}\r\n    \r\n    # number of page\r\n    # np = (res.size / mr.to_f).ceil\r\n    \r\n%>\r\n<%\r\n    1.upto(np) do |page|\r\n%>\r\n<div id=\'page-<%= page %>\'>\r\n    <div style=\'float:right;margin-right:80px;padding-bottom:10px\'><%= page %> / <%= np %></div>\r\n    <table class=\"tg\" style=\"undefined;table-layout: fixed; width: 99%\">\r\n    \r\n    <colgroup>\r\n        <col style=\"width: 5%\">\r\n        <col style=\"width: 5%\">\r\n        <col style=\"width: 5%\">\r\n        <col style=\"width: 10%\">\r\n        <col style=\"width: 15%\">\r\n        <col style=\"width: 5%\">\r\n        <col style=\"width: 10%\">\r\n        <col style=\"width: 20%\">\r\n        <col style=\"width: 20%\">\r\n        <col style=\"width: 15%\">\r\n    </colgroup>\r\n    \r\n    <tr>\r\n        <td class=\"tg-jfbk\">Room</td>\r\n        <td class=\"tg-jfbk\">Start</td>\r\n        <td class=\"tg-jfbk\">Ward</td>\r\n        <td class=\"tg-jfbk\">HN</td>\r\n        <td class=\"tg-jfbk\">Name</td>\r\n        <td class=\"tg-jfbk\">Age</td>\r\n        <td class=\"tg-jfbk\">Anesth</td>\r\n        <td class=\"tg-jfbk\">Diagnosis</td>\r\n        <td class=\"tg-jfbk\">Operation</td>\r\n        <td class=\"tg-jfbk\">Surgeon</td>\r\n    </tr>\r\n<% \r\n        # recored start\r\n        rs = ((page - 1) * mr)\r\n        # record end\r\n        re = ((page - 1) * mr) + mr\r\n        # n = 1\r\n        rs.upto(re - 1) do |n|\r\n            i = res[n]\r\n            \r\n            room = \'&nbsp;\'.html_safe\r\n            time = \'\'\r\n            ward = \'\'\r\n            hn   = \'\'\r\n            age  = \'\'\r\n            dx   = \'\'\r\n            op   = \'\'\r\n            pat_name = \'\'\r\n            anesth   = \'\'\r\n            surgeon  = \'\'\r\n            status   = \'\'\r\n            blink    = \'\'\r\n            if !i.nil?\r\n                room = i[:room]\r\n                time = i[:time]\r\n                ward = i[:ward]\r\n                hn   = i[:hn]\r\n                age  = i[:age]\r\n                dx   = i[:dx]\r\n                op   = i[:op]\r\n                pat_name = i[:pat_name]\r\n                anesth   = i[:anesth]\r\n                surgeon  = i[:surgeon]\r\n                status   = i[:status]\r\n                \r\n                if status.downcase == \'processing\' or status.downcase == \'waiting\' or status.downcase == \'ready\'\r\n                    blink = \'blink\'\r\n                end\r\n            end\r\n    # res.each do |i|\r\n%>\r\n    <tr class=\"<%# blink %>\">\r\n        <td class=\'tg-7z4u status-<%= status %> \'>\r\n            <i class=\'st-<%=status.downcase%> <%= blink %>\'></i>\r\n            <%= room %>\r\n        \r\n        </td>\r\n        <td class=\'tg-7z4u\'><%= time %> </td>\r\n        <td class=\'tg-7z4u\'><%= ward %> </td>\r\n        <td class=\'tg-7z4u\'><%= hn %> </td>\r\n        <td class=\'tg-7z4u\'><%= pat_name %> </td>\r\n        <td class=\'tg-7z4u\'><%= age %> </td>\r\n        <td class=\'tg-7z4u\'><%= anesth %> </td>\r\n        <td class=\'tg-7z4u\'><%= dx %> </td>\r\n        <td class=\'tg-7z4u\'><%= op %> </td>\r\n        <td class=\'tg-7z4u\'><%= surgeon %> </td>\r\n    </tr>\r\n<%\r\n    end\r\n%>\r\n    </table>\r\n    \r\n</div>\r\n<%\r\n    end\r\n%>\r\n\r\n<script>\r\n    function hidden_page() {\r\n<%\r\n        # number of page (np)\r\n        1.upto(np) do |i|\r\n            if i > 1\r\n%>\r\n        $(\'#page-<%=i%>\').hide();\r\n        console.log(\'### hidden page-<%=i%>\')\r\n<%\r\n            end\r\n        end\r\n%>\r\n    }\r\n    \r\n    var cur_page = 0;\r\n    var all_page = <%= np %>;\r\n    var t_out = <%= change_time %>;\r\n    var page_obj;\r\n    function change_page(from_page, to_page) {\r\n        // $(from_page).fadeOut(500);\r\n        $(from_page).hide();\r\n        $(to_page).fadeIn(500);\r\n        console.log(\'... \'+from_page+\' - \' + to_page)\r\n    }\r\n    function execute_change_page() {\r\n        nex_page = cur_page + 1\r\n        f_page = \"#page-\" + cur_page;\r\n        t_page = \"#page-\" + nex_page;\r\n        if (nex_page > all_page) {\r\n            nex_page = 1;\r\n            t_page = \"#page-\" + nex_page;\r\n        } \r\n        \r\n        change_page(f_page, t_page);\r\n        \r\n        cur_page = nex_page;\r\n        console.log(\'### cur_page (\' + f_page + \") - nex_page (\" + t_page + \") : ALL = \" + all_page);\r\n        clearTimeout(page_obj);\r\n        page_obj = setTimeout(execute_change_page, t_out);\r\n    }\r\n    \r\n    var element = $(\".blink\");\r\n    var shown = true;\r\n    clearInterval(interval_obj);\r\n    interval_obj = setInterval(toggle, 1000);\r\n    \r\n    $(document).ready(function() {\r\n        hidden_page();\r\n\r\n<% \r\n        # if number of page (np) > 1\r\n        if np > 1\r\n%>\r\n        execute_change_page();\r\n<%\r\n        end\r\n%>\r\n\r\n        $(\".se-pre-con\").fadeOut(\"slow\");\r\n    });\r\n    \r\n</script>',NULL,NULL,NULL,'2016-12-05 10:10:07','2016-12-05 10:10:07','status_feed_partial','*'),(2789,'update_status_json',1061,3,'<%\r\n    res = {}\r\n    tmp = {}\r\n    ap = get_model[:appointment].find(params[:id])\r\n    \r\n    params.keys.each do |i|\r\n        if i.to_s == \'id\'\r\n            next\r\n        end\r\n        tmp[i.to_sym] = params[i]\r\n    end\r\n    \r\n    if ap\r\n        ap.update_attributes tmp\r\n        \r\n        res[:status] = \"OK\"\r\n        res[:params] = params\r\n    else\r\n        res[:status] = \"Fail\"\r\n        res[:params] = params\r\n    end \r\n%>\r\n<%= res.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2016-12-05 17:08:06','2016-12-05 17:08:06','update_status_json',''),(2790,'create',1054,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n\r\n    if @appointment[:status] == \'Appointed\'\r\n        @appointment.update_attributes :status=>\'Pre-op\' \r\n    end\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n     