rm_submit);\r\n        btn_form.append(\'&nbsp;&nbsp;|&nbsp;&nbsp;\');\r\n        btn_form.append(frm_cancel);\r\n        \r\n        // $(\'#record-submit\').click(function() {\r\n        //     if ($(\'#data-stop_at\').val() == \"\") {\r\n        //         d = new Date();\r\n        //         $(\'#data-stop_at\').val(d.getHours() + \":\" + d.getMinutes());\r\n        //     }\r\n        // });\r\n\r\n<%\r\n        end\r\n%>\r\n        snap = $( \"a:contains(\'Snap\')\" ).clone();\r\n        snap = snap.addClass(\'btn btn-small btn-info\');\r\n        btn_snap = $(\'#btn-snap\');\r\n        btn_snap.append(snap);\r\n        \r\n        $(\'input\').prop(\'required\', null);\r\n        $(\'select\').prop(\'required\', null);\r\n<%\r\n    end\r\n%>\r\n    })\r\n\r\n\r\n    function update_time() {\r\n        var ts = $(\'#data-operative_time_start_at\').val();\r\n        var te = $(\'#data-operative_time_stop_at\').val();\r\n        console.log(\'ts: \' + ts + \", te: \" + te);\r\n        \r\n        var t_s = new Date(\"<%= Time.now.strftime(\'%m/%d/%Y\') %> \" + ts);\r\n        var t_e = new Date(\"<%= Time.now.strftime(\'%m/%d/%Y\') %> \" + te);\r\n        console.log(\'t_s: \' + t_s + \', t_e: \' + t_e);\r\n        \r\n        var t_d = (t_e - t_s)/60000;\r\n        console.log(\'t_d: \' + t_d);\r\n        \r\n        $(\'#data-total_operative\').val(t_d);\r\n    }\r\n    \r\n    \r\n    $(\'#data-operative_time_start_at\').change(update_time)\r\n    $(\'#data-operative_time_stop_at\').change(update_time)\r\n    if ($(\'#data-total_operative\').val() === \'\') {\r\n        $(\'#data-total_operative\').val(0)\r\n    }\r\n</script>',NULL,NULL,NULL,'2016-12-07 03:15:32','2016-12-07 03:15:32','form',''),(2794,'fields',235,3,'<%\r\n\r\n    def get_fields doc\r\n        doc = get_document(doc.downcase)\r\n        rs = []\r\n        if doc\r\n            a_doc = doc.fields\r\n            rs = []\r\n            \r\n            a_doc.each do |i|\r\n                name = i[:name]\r\n                col  = i[:column_name]\r\n                type = i[:field_type]\r\n                para = i[:params].nil? ? \'-\' : i[:params]\r\n                lov_type = i[:lov_type].nil? ? \'-\' : i[:lov_type]\r\n                lov = \'-\'\r\n                if i[:lov]\r\n                    lov = i[:lov].to_s.split(\'\\r\\n\').join(\', \')\r\n                end\r\n                txt = \"\\\\#{name}, \\\\#{col}, \\\\#{type}, \\\\#{para}, \\\\#{lov_type}, \\\\#{lov}\"\r\n                rs << txt\r\n            end\r\n        end\r\n        return rs\r\n    end\r\n    \r\n    res = []\r\n    if d = params[:doc]\r\n        res = get_fields d\r\n    else\r\n        res = get_fields this.document_name\r\n    end\r\n    \r\n    if res.empty?\r\n%>\r\nNo document found (doc)\r\n<%\r\n    else\r\n        res.each do |i|\r\n%>\r\n<%= i.html_safe %><br/>\r\n<%\r\n        end\r\n    end\r\n%>\r\n\r\n',NULL,NULL,NULL,'2016-12-07 04:17:25','2016-12-07 04:17:25','fields',''),(2795,'test',960,3,'<%\r\n    obj = get_model[:colposcopy].where(:follow_up=>\'2 wk\').all\r\n    res = {}\r\n    \r\n    res[:obj] = obj\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2016-12-07 04:28:13','2016-12-07 04:28:13','test',''),(2796,'exportx',876,3,'<% \r\n    tb = Time.now \r\n    \r\n    params[:date] = \'all\'\r\n    \r\n    doc = get_document \'colposcopy\'\r\n    # field map\r\n    fm = {}\r\n    # field list\r\n    fl = []\r\n    # document field\r\n    df = {}\r\n    doc.fields.each do |i|\r\n        ft = i[:field_type]\r\n        if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n            next\r\n        end\r\n        \r\n        cn = i[:column_name].to_sym\r\n        fl << cn\r\n        fm[cn] = i.to_h\r\n        \r\n        if i[:lov_type] == \'pair\'\r\n            tmp = {}\r\n            tmp[:name] = i[:name]\r\n            tmp[:list] = []\r\n            tmp[:pair] = {}\r\n            lov = i[:lov].to_s.split(\'\\r\\n\')\r\n            lov.each do |j|\r\n                x = j.split(\'|\')\r\n                tmp[:pair][x[0].strip] = x[1].strip\r\n                tmp[:list] << x[1].strip\r\n            end\r\n            \r\n            fm[cn][:list] = tmp[:list]\r\n            fm[cn][:pair] = tmp[:pair]\r\n        end\r\n    end\r\n    \r\n    l_doc = get_document \'lesion\'\r\n    lm = {}\r\n    ll = []\r\n    lf = {}\r\n    l_doc.fields.each do |i|\r\n        ft = i[:field_type]\r\n        if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n            next\r\n        end\r\n        \r\n        cn = i[:column_name].to_sym\r\n        ll << cn\r\n        lm[cn] = i.to_h\r\n        \r\n        if i[:lov_type] == \'pair\'\r\n            tmp = {}\r\n            tmp[:name] = i[:name]\r\n            tmp[:list] = []\r\n            tmp[:pair] = {}\r\n            lov = i[:lov].to_s.split(\'\\r\\n\')\r\n            lov.each do |j|\r\n                x = j.split(\'|\')\r\n                tmp[:pair][x[0].strip] = x[1].strip\r\n                tmp[:list] << x[1].strip\r\n            end\r\n            \r\n            lm[cn][:list] = tmp[:list]\r\n            lm[cn][:pair] = tmp[:pair]\r\n        end\r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	m_pat = @ehr_model[:patient]\r\n	m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	# map prov_id <-> provider_name\r\n	prov = {}\r\n	a_prov = get_model[:provider].all\r\n	a_prov.each do |i|\r\n	    prov[i.id.to_s] = i[:name]\r\n	end\r\n    \r\n    # map colpo_id <-> colpo\r\n    colpo = {}\r\n    ids   = []\r\n    # a_col = get_model[this.document_name.to_sym].all\r\n    e_date = Date.strptime(\'07/12/2016\',\"%d/%m/%Y\")\r\n    a_col = get_model[this.document_name.to_sym].where({:created_at.lt=>e_date.end_of_day}).all\r\n    a_col.each do |i|\r\n        ids << i.id\r\n        colpo[i.id.to_s] = i\r\n    end\r\n    \r\n    # colpo\'s module_model\r\n    mm_col = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#colposcopy\", :module_id=>ids).all\r\n    \r\n    # map patient_id <-> patient\r\n    pat = {}\r\n    rs_pat = m_pat.find(mm_col.collect{|i| i[:patient_id]})\r\n    rs_pat.each do |i|\r\n        pat[i.id.to_s] = i\r\n    end\r\n\r\n    # patient fields\r\n    pf = [:hn, :name, :age]\r\n    # colposcopy fields\r\n    colf = pf + fl\r\n    # lesion fields\r\n    lesf = pf + ll\r\n    \r\n    # data bin range\r\n    # {:bin=>0,:lmp=>{},:pap=>{}}\r\n    bin = {\r\n        :a=>{:bin=>0,:lmp=>{},:pap=>{}},\r\n        :b=>{:bin=>0,:lmp=>{},:pap=>{}},\r\n        :c=>{:bin=>0,:lmp=>{},:pap=>{}},\r\n        :d=>{:bin=>0,:lmp=>{},:pap=>{}},\r\n        :e=>{:bin=>0,:lmp=>{},:pap=>{}},\r\n        :f=>{:bin=>0,:lmp=>{},:pap=>{}}\r\n    }\r\n\r\n    rs_col = []\r\n    rs_les = []\r\n    mm_col.each do |i|\r\n        # patient\r\n        pt = pat[i[:patient_id].to_s]\r\n        # colpo\r\n        cp = colpo[i[:module_id].to_s]\r\n        \r\n        today = cp[:created_at]\r\n        d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  pt[:birth_date].day) : today\r\n        age = !pt[:birth_date].nil? ? d.year - pt[:birth_date].year - (d > today ? 1 : 0) : 0\r\n        \r\n        if age <= 20\r\n            x = bin[:a]\r\n            x[:bin] += 1\r\n            \r\n            m = cp[:lmp].nil? ? \'Menopause\' : cp[:lmp].strftime(\'%b\')\r\n            if !x[:lmp].has_key? m\r\n                x[:lmp][m] = 1\r\n            else\r\n                x[:lmp][m] += 1\r\n            end\r\n            if !x[:pap].has_key? i[:pap]\r\n                x[:pap][cp[:pap]] = 1\r\n            else\r\n                x[:pap][cp[:pap]] += 1\r\n            end\r\n            \r\n            \r\n        elsif age > 20 and age < 30\r\n            # bin[:b][:bin] += 1\r\n            \r\n            x = bin[:b]\r\n            x[:bin] += 1\r\n            \r\n            m = cp[:lmp].nil? ? \'Menopause\' : cp[:lmp].strftime(\'%b\')\r\n            if !x[:lmp].has_key? m\r\n                x[:lmp][m] = 1\r\n            else\r\n                x[:lmp][m] += 1\r\n            end\r\n            if !x[:pap].has_key? i[:pap]\r\n                x[:pap][cp[:pap]] = 1\r\n            else\r\n                x[:pap][cp[:pap]] += 1\r\n            end\r\n        elsif age > 30 and age < 40\r\n            # bin[:c][:bin] += 1\r\n            x = bin[:c]\r\n            x[:bin] += 1\r\n            \r\n            m = cp[:lmp].nil? ? \'Menopause\' : cp[:lmp].strftime(\'%b\')\r\n            if !x[:lmp].has_key? m\r\n                x[:lmp][m] = 1\r\n            else\r\n                x[:lmp][m] += 1\r\n            end\r\n            if !x[:pap].has_key? i[:pap]\r\n                x[:pap][cp[:pap]] = 1\r\n            else\r\n                x[:pap][cp[:pap]] += 1\r\n            end\r\n        elsif age > 40 and age < 50\r\n            # bin[:d][:bin] += 1\r\n            x = bin[:d]\r\n            x[:bin] += 1\r\n            \r\n            m = cp[:lmp].nil? ? \'Menopause\' : cp[:lmp].strftime(\'%b\')\r\n            if !x[:lmp].has_key? m\r\n                x[:lmp][m] = 1\r\n            else\r\n                x[:lmp][m] += 1\r\n            end\r\n            if !x[:pap].has_key? i[:pap]\r\n                x[:pap][cp[:pap]] = 1\r\n            else\r\n                x[:pap][cp[:pap]] += 1\r\n            end\r\n        elsif age > 50 and age < 60\r\n            # bin[:e][:bin] += 1\r\n            x = bin[:e]\r\n            x[:bin] += 1\r\n            \r\n            m = cp[:lmp].nil? ? \'Menopause\' : cp[:lmp].strftime(\'%b\')\r\n            if !x[:lmp].has_key? m\r\n                x[:lmp][m] = 1\r\n            else\r\n                x[:lmp][m] += 1\r\n            end\r\n            if !x[:pap].has_key? i[:pap]\r\n                x[:pap][cp[:pap]] = 1\r\n            else\r\n                x[:pap][cp[:pap]] += 1\r\n            end\r\n        else\r\n            # bin[:f][:bin] += 1\r\n            x = bin[:f]\r\n            x[:bin] += 1\r\n            \r\n            m = cp[:lmp].nil? ? \'Menopause\' : cp[:lmp].strftime(\'%b\')\r\n            if !x[:lmp].has_key? m\r\n                x[:lmp][m] = 1\r\n            else\r\n                x[:lmp][m] += 1\r\n            end\r\n            if !x[:pap].has_key? i[:pap]\r\n                x[:pap][cp[:pap]] = 1\r\n            else\r\n                x[:pap][cp[:pap]] += 1\r\n            end\r\n        end\r\n        \r\n        tmp = {}\r\n        tmp[:hn]  = pt[:hn]\r\n        tmp[:name]= \"\\\\#{pt[:first_name]} \\\\#{pt[:last_name]}\"\r\n        tmp[:age] = age\r\n        \r\n        les = []\r\n        \r\n        fl.each do |j|\r\n            x = fm[j]\r\n            # x = {}\r\n            v = cp[j]\r\n            if x.to_h.has_key? :pair\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                \r\n                tmp[j] = a.join(\',\')\r\n            elsif x[:column_name] == \'lesion\'\r\n                tmp[j] = v.size\r\n                les = v\r\n            elsif x[:column_name] == \'images\'\r\n                tmp[j] = v.size\r\n            elsif x[:column_name] == \'colposcopist_1\' or x[:column_name] == \'fellow\'\r\n                name = prov[v.to_s]\r\n                if name\r\n                    tmp[j] = name\r\n                else\r\n                    tmp[j] = v\r\n                end\r\n            else\r\n                tmp[j] = v\r\n            end\r\n        end\r\n        \r\n        if false\r\n        xxx = []\r\n        a_les = get_model[:lesion].find(les)\r\n        \r\n        a_les.each do |m|\r\n            lll = {}\r\n            lll[:hn] = tmp[:hn]\r\n            lll[:name] = tmp[:name]\r\n            lll[:age]  = tmp[:age]\r\n            ll.each do |n|\r\n                x = lm[n]\r\n                v = m[n]\r\n                if x.to_h.has_key? :pair\r\n                    a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                    lll[n] = a.join(\',\')\r\n                else\r\n                    lll[n] = v\r\n                end\r\n            end\r\n            xxx << lll\r\n        end\r\n        \r\n        rs_les += xxx\r\n        end\r\n        \r\n        rs_col << tmp\r\n    end\r\n    \r\n    \r\n    bin_lmp = {}\r\n    lmp = rs_col.group_by{|i| i[:lmp].strftime(\'%b\') if (!i[:lmp].nil?)}\r\n    lmp.each do |k,v|\r\n        if v\r\n            bin_lmp[k] = v.size\r\n        end\r\n    end\r\n    \r\n    bin_pap = {}\r\n    pap = rs_col.group_by{|i| i[:pap]}\r\n    pap.each do |k,v|\r\n        if v\r\n            bin_pap[k] = v.size\r\n        end\r\n    end\r\n    \r\n    bin_imp = {}\r\n    imp = rs_col.group_by{|i| i[:colposcopic_impression]}\r\n    imp.each do |k,v|\r\n        if v and k != \'Other\'\r\n            bin_imp[k] = v.size\r\n        elsif k == \'Other\'\r\n            tmp = {}\r\n            tmp[:total] = v.size\r\n            \r\n            v.each do |j|\r\n                a = j[:colposcopic_impression_other]\r\n                if !tmp.has_key? a\r\n                    tmp[a] = 0\r\n                end\r\n                tmp[a] += 1\r\n            end\r\n            \r\n            bin_imp[k] = tmp\r\n        end\r\n    end\r\n    \r\n    bin_hpv = {:asc=>{}}\r\n    hpv = rs_col.group_by{|i| i[:hpv]}\r\n    hpv.each do |k,v|\r\n        if v and k != \'Positive\'\r\n            bin_hpv[k] = v.size\r\n            \r\n            v.each do |j|\r\n                x = j[:pap]\r\n                if x == \'ASC-US\'\r\n                    if !bin_hpv[:asc].has_key? k\r\n                        bin_hpv[:asc][k] = 0\r\n                    end\r\n                    bin_hpv[:asc][k] += 1\r\n                end\r\n            end\r\n        elsif k == \'Positive\'\r\n            tmp = {}\r\n            tmp[:total] = v.size\r\n            \r\n            hr = {}\r\n            v.each do |j|\r\n                a = j[:hpv_positive]\r\n                if !tmp.has_key? a\r\n                    tmp[a] = 0\r\n                end\r\n                tmp[a] += 1\r\n                \r\n                if a == \'Other high risk\'\r\n                    b = j[:hpv_other_high_risk]\r\n                    if !hr.has_key? b\r\n                        hr[b] = 0\r\n                    end\r\n                    hr[b] += 1\r\n                end\r\n                \r\n                x = j[:pap]\r\n                if x == \'ASC-US\'\r\n                    if !bin_hpv[:asc].has_key? k\r\n                        bin_hpv[:asc][k] = 0\r\n                    end\r\n                    bin_hpv[:asc][k] += 1\r\n                end\r\n            end\r\n            \r\n            tmp[:high_risk] = hr\r\n            bin_hpv[k] = tmp\r\n        end\r\n    end\r\n    \r\n    xxx = rs_col.group_by{|i| [i[:pap], i[:hpv], i[:hpv_positive]]}\r\n    aaa = {}\r\n    xxx.each do |k,v|\r\n        if v\r\n            aaa[k] = v.size\r\n        end\r\n    end\r\n\r\n    res = {}\r\n    # res[:bin] = bin\r\n    res[:lmp] = bin_lmp\r\n    res[:pap] = bin_pap\r\n    # res[:af]   = af\r\n    res[:imp] = bin_imp\r\n    res[:hpv] = bin_hpv\r\n    res[:aaa] = aaa\r\n    res[:time] = Time.now - tb\r\n     \r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\nif false\r\n%>\r\n    <%= colf.join(\'!\') %>\r\n    <br/>\r\n    <%\r\n        rs_col.each do |i|\r\n            colf.each do |j|\r\n    %>\r\n    <%= i[j] %>!\r\n    <%\r\n            end\r\n    %>\r\n    <br/>\r\n    <%\r\n        end\r\n    %>\r\n    \r\n    <br/>\r\n    <br/>\r\n    <hr/>\r\n    <br/>\r\n    <%= lesf.join(\'!\') %>\r\n    <br/>\r\n    <%\r\n        rs_les.each do |i|\r\n            lesf.each do |j|\r\n    %>\r\n    <%= i[j] %>!\r\n    <%\r\n            end\r\n    %>\r\n    <br/>\r\n    <%\r\n        end\r\n    %>\r\n\r\n<hr/>\r\nProcessing Time : <%= Time.now - tb %>\r\n<%\r\nend\r\n%>',NULL,NULL,NULL,'2016-12-07 05:24:31','2016-12-07 05:24:31','exportx',''),(2797,'initx',876,4,'<%\r\n    def get_map(arr)\r\n        rs = {}\r\n        arr.each do |i|\r\n            rs[i.id.to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n    \r\n    @ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @m_ehr = @ehr.load_model\r\n    @m_pat = @m_ehr[:patient]\r\n    @m_pat_mod = @m_ehr[:patient_module]\r\n\r\n    @models = get_model\r\n    \r\n    def get_appointment_by_date(sdate = Time.now.strftime(\'%d/%m/%Y\'), edate = Time.now.strftime(\'%d/%m/%Y\'))\r\n        sdate = Time.strptime(sdate, \"%d/%m/%Y\")\r\n        edate = Time.strptime(edate, \"%d/%m/%Y\")\r\n        cond = {}\r\n        cond[:date] = {\'$gte\'=>sdate.beginning_of_day,\'$lt\'=>edate.end_of_day}\r\n        rs = @models[:appointment].where(cond).all\r\n        return rs\r\n    end\r\n    \r\n    def get_all_appointment()\r\n        return @models[:appointment].all\r\n    end\r\n    \r\n    def get_all_appointment_by_ids(ids=[])\r\n        return @models[:appointment].find(ids)\r\n    end\r\n    \r\n    def get_all_patient_by_ids(ids=[])\r\n        return @m_pat.find(ids)\r\n    end\r\n    \r\n    def get_patient_module_by_module_name(mod_name=\'\')\r\n        return @m_pat_mod.where(:module_name=>mod_name).all\r\n    end\r\n    \r\n    def get_patient_module_by_appointment_ids(app_ids = [])\r\n        return @m_pat_mod.where(:module_id=>app_ids).all\r\n    end\r\n    \r\n    def get_patient_module_document_by_patient_module_appointment(par_ids = [], mod_name = \'\')\r\n        return @m_pat_mod.where(:parent_id=>par_ids, :module_name=>mod_name).all\r\n    end\r\n    \r\n    def get_patient_module_by_document_ids(mod_name, mod_ids)\r\n        return @m_pat_mod.where(:module_name=>mod_name, :module_id=>mod_ids).all\r\n    end\r\n    \r\n    def get_module_id_array(patient_module_array = [])\r\n        return patient_module_array.collect{|i| i[:module_id].to_s}\r\n    end\r\n    \r\n    def get_module_id_map(pat_mod_arr = [])\r\n        rs = {}\r\n        pat_mod_arr.each do |i|\r\n            rs[i[:module_id].to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n    \r\n%>',NULL,NULL,NULL,'2016-12-07 05:24:48','2016-12-07 05:24:48','initx',''),(2798,'initx_query',876,4,'<%\r\n    # time begin\r\n    tb = Time.now\r\n    \r\n    def map_model(model)\r\n        # tmp = {nil=>\'N/A\',\'\'=>\'N/A\'}\r\n        tmp = {}\r\n        get_model[model].all.each do |i|\r\n            tmp[i.id.to_s] = i\r\n        end\r\n        return tmp\r\n    end\r\n    \r\n    @rs_visit = map_model :visit_type\r\n    @rs_prov  = map_model :provider\r\n    @rs_indi  = map_model :indication\r\n    @rs_proc  = map_model :procedure\r\n    \r\n    date = Time.now\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	@m_pat = @ehr_model[:patient]\r\n	@m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	r_model = models[:room]\r\n	\r\n	\r\n	visits = {}\r\n	get_model[:visit_type].all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	\r\n	indications = {}\r\n	get_model[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = []\r\n	if params[:date] == \'all\'\r\n	   aps = ap_model.all\r\n	elsif params[:sdate] and params[:edate]\r\n	    sdate = Date.strptime(params[:sdate], \'%d/%m/%Y\')\r\n	    edate = Date.strptime(params[:edate], \'%d/%m/%Y\')\r\n	    aps = ap_model.all(:date.gte=>sdate.at_beginning_of_day,:date.lt=>edate.end_of_day) \r\n	elsif params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\')\r\n	    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	end\r\n	\r\n# 	for a in aps\r\n# 	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n# 	end\r\n	\r\n	id = \'\'\r\n	a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = @m_pat_mod.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n	\r\n	# form service\r\n	f_ser = {}\r\n	# module_id from service\r\n	mid_ser = {}\r\n	mid_map = {}\r\n	# service_map\r\n	sm = {:colposcopy=>\'Colposcopy\'}\r\n	sm.each do |k, v|\r\n	    f_ser[k] = {}\r\n	    mid_map[k] = {}\r\n	    mid_ser[k] = []\r\n	    tmp = @m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>pa_id).all\r\n	    tmp.each do |i|\r\n	        f_ser[k][i[:patient_id].to_s] = i.id.to_s\r\n	        mid_map[k][i[:patient_id].to_s] = i[:module_id].to_s\r\n	        mid_ser[k] << i[:module_id].to_s\r\n	        \r\n	    end\r\n	end\r\n	\r\n	rs_pat_mod = {}\r\n	pat_id = []\r\n	@m_pat_mod.where(:module_name=>mname, :module_id=>a_id).all.each do |i|\r\n	    rs_pat_mod[i[:module_id].to_s] = i\r\n	    pat_id << i[:patient_id].to_s\r\n	end\r\n	\r\n	rs_pat = {}\r\n	@m_pat.find(pat_id).each do |i|\r\n	    rs_pat[i.id.to_s] = i\r\n	end\r\n\r\n# if false	\r\n# 	aps.collect!{|i| \r\n#         id = i.id\r\n#         # if m = @m_pat_mod.first(:module_name=>mname,:module_id=>i.id)\r\n#         if m = rs_pat_mod[i.id.to_s]\r\n#             pat_id = m.patient_id.to_s\r\n#     	   #  patient = @m_pat.find(m[:patient_id])\r\n#             patient = rs_pat[m[:patient_id].to_s]\r\n#     	     if patient \r\n#         	     provider = @rs_prov[i[:provider].to_s]\r\n#         	     visit_type = @rs_visit[i[:visit_type].to_s].nil? ? \'N/A\' : @rs_visit[i[:visit_type].to_s][:name]\r\n#         	     provider_name = \'NA\'\r\n#         	     provider_name = provider.name if provider\r\n#         	     procedure_name = \'NA\'\r\n#         	     pro = @rs_proc[i[:procedure].to_s]\r\n#         	     procedure_name = pro.name if pro\r\n#         	     patient = @m_pat.new unless patient \r\n#         	     hn = \'-\'\r\n        	     \r\n#         	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n#        