=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n# 	:note=>\'Note\',:visit_type=>\'Group\',:processing_ctrl=>\'Actions\' }\r\n	\r\n	res = {}\r\n	res[:time] = Time.now - tb\r\n	res[:aps_count] = aps.size\r\n	res[:aps] = aps\r\n	\r\n	@res = res\r\n	\r\n	@rs_app  = aps\r\n	@rs_pat  = rs_pat\r\n	@rs_pat_mod = rs_pat_mod\r\n	@rs_serv = f_ser\r\n	@mid_ser = mid_ser # result of  module id service\r\n	@mid_map = mid_map\r\n	@date = date\r\n	@p_date = date.strftime(\'%d/%m/%Y\')\r\n	\r\n	@total_time = Time.now - tb\r\n%>',NULL,NULL,NULL,'2016-12-07 08:56:53','2016-12-07 08:56:53','initx_query',''),(2799,'test',876,3,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	@m_pat = @ehr_model[:patient]\r\n	@m_pat_mod = @ehr_model[:patient_module]\r\n%>\r\n<%= @m_pat.all.size %>',NULL,NULL,NULL,'2016-12-07 15:13:25','2016-12-07 15:13:25','test',''),(2800,'form',899,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   \r\n   ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @m_ehr = ehr.load_model\r\n    @m_pat = @m_ehr[:patient]\r\n    @m_pat_mod = @m_ehr[:patient_module]\r\n    \r\n    pat = nil\r\n    if pat_id = params[:patient_id]\r\n        pat = @m_pat.find(pat_id)\r\n    end\r\n\r\n    res = {}\r\n    res[:pat] = pat\r\n%>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<%\r\n    if pat\r\n        # underlying disease field\r\n        uf = %w{ht dm cad cerebrovascular_disease malignancy ckd esrd}.collect{|i| i.to_sym}\r\n        # underlying disease result\r\n        ur = []\r\n        uf.each do |i|\r\n            if pat[i].downcase == \'yes\'\r\n                ur << i.to_s.upcase\r\n            end\r\n        end\r\n%>\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\'#data-diagnosis\').val(\'<%= pat[:diagnosis] %>\');\r\n        $(\'#data-underlying_disease\').val(\'<%= ur.join(\", \") %>\');\r\n<%\r\n        if pat[:esrd].downcase == \'yes\'\r\n%>\r\n        $(\"input[name=update_esrd][value=\'Yes\']\").attr(\'checked\', \'checked\');\r\n<%\r\n        else\r\n%>\r\n        $(\"input[name=update_esrd][value=\'No\']\").attr(\'checked\', \'checked\');\r\n<%\r\n        end\r\n%>\r\n    });\r\n</script>\r\n\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2016-12-08 06:34:33','2016-12-08 06:34:33','form',''),(2801,'form',1024,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n    \r\n    $(document).ready(function() {\r\n        $(\'#data-smokes\').change(function() {\r\n            v = $(this).val();\r\n            v = parseFloat(v) || \'0\'\r\n            t = \'---\'\r\n            if (v != \'0\') {\r\n                t = v * 365;\r\n            } \r\n            // console.log(v + \'-\' + t + \'...\' + $(this).val())\r\n            $(\'#data-pack_year\').val(t + \'\');\r\n        })\r\n    })\r\n    \r\n</script>',NULL,NULL,NULL,'2016-12-09 04:07:43','2016-12-09 04:07:43','form',''),(2803,'diag_reports',789,2,'<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n		width:100px\r\n    }\r\n</style>\r\n<%\r\n    act = \'diag_reports_partial\'\r\n    \r\n    report = [\r\n            [\'EGD\', \'gastro\'],\r\n            [\'Colono\', \'colono\'],\r\n            [\'EUS\', \'eus\'],\r\n            [\'ERCP\', \'ercp\'],\r\n            [\'DBE\', \'dbe\'],\r\n            [\'Sigmoid\', \'sigmoid\'],\r\n            [\'Push Entero\', \'push_enteroscopy\']\r\n        ]\r\n%>\r\n<%= form_for :adv_search,:url=>\"\\\\#{act}?update=result-panel\",:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n	    <span class=\"field-data\"> \r\n			<label class=\"field-label\">Start Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :sdate, :value=>\'\',:id=>\'sdate\',:style=>\"width:100%\"%></div>\r\n		</span> \r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">End Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :edate, :value=>\'\',:id=>\'edate\',:style=>\"width:100%\"%></div>\r\n		</span>\r\n		<span class=\'field-data\' style=\'width:450px\'>\r\n		    <label class=\'field-label\'style=\'width:100px\'>Report Output : </label>\r\n		    <div class=\'field-input\' style=\'width:250px\'><%= f.select :report, report, include_blank: false %></div>\r\n		</span>\r\n		<span class=\"field-data\">\r\n		    <div class=\"field-input\"><%=f.submit \'Submit\', :class=>\'btn btn-success\'%> </div>\r\n		</span>\r\n<script>\r\n    $(\"#sdate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n    $(\"#edate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n</script>\r\n<% end %>\r\n<div class=\'clear\'></div>\r\n<br/>\r\n<div id=\'result-panel\'></div>\r\n',NULL,NULL,NULL,'2016-12-12 04:41:32','2016-12-12 04:41:32','diag_reports',''),(2804,'diag_reports_partial',789,3,'<%\r\n    tb = Time.now\r\n    rs = {}\r\n    cond = {}\r\n    \r\n    serv = [\r\n            {:name=>\'EGD\', :service=>\'gastro\'},\r\n            {:name=>\'Colono\', :service=>\'colono\'},\r\n            {:name=>\'EUS\', :service=>\'eus\'},\r\n            {:name=>\'ERCP\', :service=>\'ercp\'},\r\n            {:name=>\'Sigmoid\', :service=>\'sigmoid\'},\r\n            {:name=>\'DBE\', :service=>\'dbe\'},\r\n            {:name=>\'Push Enteroscopy\', :service=>\'push_enteroscopy\'}\r\n        ]\r\n        \r\n    q_serv = \'\'\r\n    if q = params[:adv_search]\r\n        q[:sdate] = Time.strptime(q[:sdate], \"%d/%m/%Y\")\r\n        q[:edate] = Time.strptime(q[:edate], \"%d/%m/%Y\")\r\n        \r\n        q_serv = q[:report]\r\n        \r\n        cond[:start_procedural_date] = {\'$gte\'=>q[:sdate].beginning_of_day,\'$lt\'=>q[:edate].end_of_day}\r\n        \r\n        # serv.each do |m|\r\n            doc = get_document q_serv\r\n            # field map\r\n            fm = {}\r\n            # field list\r\n            fl = []\r\n            # document field\r\n            df = {}\r\n            doc.fields.each do |i|\r\n                ft = i[:field_type]\r\n                if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                    next\r\n                end\r\n                \r\n                cn = i[:column_name].to_sym\r\n                fl << cn\r\n                fm[cn] = i.to_h\r\n                \r\n                if i[:lov_type] == \'pair\'\r\n                    tmp = {}\r\n                    tmp[:name] = i[:name]\r\n                    tmp[:list] = []\r\n                    tmp[:pair] = {}\r\n                    lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                    lov.each do |j|\r\n                        x = j.split(\'|\')\r\n                        tmp[:pair][x[0].strip] = x[1].strip\r\n                        tmp[:list] << x[1].strip\r\n                    end\r\n                    \r\n                    fm[cn][:list] = tmp[:list]\r\n                    fm[cn][:pair] = tmp[:pair]\r\n                end\r\n            end\r\n            \r\n            res = {}\r\n            # get_model[k].collection.find({\'_id\'=>{\'$in\'=>mid}},{:fields=>{\'_id\'=>1,\'endoscopist_1\'=>1}}).to_a\r\n            # rs_serv = get_model[i[:service].to_sym].where(cond).all.group_by{|i| i[:start_procedural_date].strftime(\'%m/%y\')}\r\n            rs_serv = get_model[q_serv.to_sym].collection.find(cond, {:fields=>{\'start_procedural_date\'=>1, \'diagnosis_group\'=>1}}).to_a\r\n            # res[:rs_serv] = rs_serv\r\n            # res[:fm] = fm\r\n            # res[:dx_group] = fm[:diagnosis_group]\r\n            \r\n            rs_serv.each do |n|\r\n                # dx group\r\n                if !n[\'diagnosis_group\'].nil?\r\n                    dx = n[\'diagnosis_group\'].split(\'|\')\r\n                    # tmp = {}\r\n                    dx.each do |o|\r\n                        # dx name\r\n                        dn = fm[:diagnosis_group][:pair][o]\r\n                        # dx key\r\n                        dk = \"\\\\#{dn} [\\\\#{o}]\"\r\n                        \r\n                        if !res.has_key? dk\r\n                            res[dk] = 0\r\n                        end\r\n                        \r\n                        res[dk] += 1\r\n                    end\r\n                end\r\n            end\r\n            \r\n            rs = {:dx=>res, :total=>rs_serv.size}\r\n        # end\r\n        \r\n        \r\n    end\r\n    # bowel_preperation_finding\r\n    \r\n    \r\n%>\r\n<br/>\r\n<%# rs.to_json.html_safe %>\r\n<%\r\n    if rs.count != 0\r\n        # serv.each do |i|\r\n            dx_list = rs[:dx].to_a.sort_by{|i| i[1]}.reverse\r\n            pat_total = rs[:total]\r\n%>\r\n\r\n<h3><%= q_serv.humanize %> diagnosis group report</h3>\r\n<br/>\r\n<table class=\"table table-bordered\" style=\'width:50%\'>\r\n<thead>\r\n    <tr>\r\n        <th width=\'40%\'>Diagnosis</th>\r\n        <th width=\'10%\'>Amount</th>\r\n    </tr>\r\n</thead>\r\n<tbody>\r\n<%\r\n        dx_list.each do |i|\r\n%>\r\n    <tr>\r\n        <td><%= i[0] %></td>\r\n        <td><%= i[1] %></td>\r\n    </tr>\r\n<%\r\n        end\r\n%>\r\n    <tr>\r\n        <td>Total Patient</td>\r\n        <td><%= pat_total %></td>\r\n    </tr>\r\n</tbody>\r\n</table>\r\n<%\r\n    else\r\n%>\r\n<b>No Result Found.</b>\r\n<%\r\n    end\r\n%>\r\n<br/>\r\nProcessing time : <%= Time.now - tb %>\r\n<hr/>',NULL,NULL,NULL,'2016-12-12 04:43:59','2016-12-12 04:43:59','diag_reports_partial',''),(2805,'instrument_report',522,3,'\r\n<html>\r\n    <head>\r\n        <%=include_header%>\r\n    </head>\r\n<style media=\"print\">\r\n    table,th,td{\r\n        border: 0.5px solid black;\r\n        font-size:10px;\r\n    }\r\n    .event{\r\n        background-color:#eee;\r\n    }\r\n    .alt{\r\n        background-color:#eaa;\r\n    }\r\n</style>\r\n<style>\r\n    table,th,td{\r\n        border: 0.5px solid black;\r\n        font-size:10px;\r\n    }\r\n    \r\n    .event{\r\n        background-color:#eee;\r\n    }\r\n    .alt{\r\n        background-color:#eaa;\r\n    }\r\n@media print {\r\n    .page {page-break-after: always;}\r\n}\r\nselect{width:100px;\r\n    \r\n</style>\r\n<body style=\"font-size:0.6em;padding-left:50px\">\r\n<% unless request.post? %>\r\n\r\n<%\r\n \r\n%>\r\n<%=form_for \'month\', :url=>\'instrument_report\' do |f| %>\r\n<h1>รายงานค่าบำรุงอุปกรณ์ทางการแพทย์ \r\n    \r\n</h1>\r\nSelect Month : <%=f.date_select :query ,:order=>[:month,:year] %><br/>\r\nSelect Case type : <%=f.select :type, [[\'IPD\',\'IPD\'],[\'OPD\',\'OPD\']] %>\r\n\r\n<%= f.submit \'Submit\' %>\r\n\r\n<% end %>\r\n\r\n<% else %>\r\n<%# params.inspect %>\r\n<% \r\n\r\n    models = get_model \r\n\r\n    provider_map = {}\r\n    \r\n    date = Date.parse(\"\\\\#{params[:month][\'query(1i)\']}-\\\\#{params[:month][\'query(2i)\']}-1\").to_mongo\r\n    \r\n    products =  models[:product].all\r\n    product_map = {}\r\n    for i in products\r\n        product_map[i.id] = i\r\n    end\r\n    \r\n    product_struct_map = {}\r\n    for i in models[:payroll_structure].all\r\n        product_struct_map[i.product_id] = i.instrument\r\n    end\r\n    \r\n    \r\n    # key product-date\r\n    \r\n    map = {}\r\n    \r\n    # for all billing in month\r\n    \r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    m_apps = {}\r\n    apps = models[:appointment].where(:date=>{\'$gte\'=>date.beginning_of_month,\'$lt\'=>date.end_of_month}).all\r\n    for i in apps\r\n        m_apps[i.id] = i.date \r\n    end\r\n    \r\n    \r\n    mapps = module_model.where(:module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>apps.collect{|i| i.id }).all\r\n    for i in mapps\r\n        m_apps[i.id] = m_apps[i.module_id]\r\n    end\r\n   \r\n   \r\n\r\n    m_billings = {}\r\n    rm_billings = {}\r\n    mbillings = module_model.where(:module_name=>\"\\\\#{@current_project.name}#billing\", :parent_id=>mapps.collect{|i| i.id }).all\r\n    for i in mbillings\r\n        m_billings[i.module_id] = m_apps[i.parent_id]\r\n        rm_billings[i.module_id] = i.patient_id\r\n    end\r\n    \r\n    patients = {}\r\n    patient_model.find(mbillings.collect{|i| i.patient_id }).each do |i|\r\n        patients[i.id] = [i.hn, \"\\\\#{i.prefix_name}\\\\#{i.first_name} \\\\#{i.last_name}\", i.birth_date] \r\n    end\r\n    \r\n    type = params[:month][:type]\r\n    \r\n    \r\n    \r\n    \r\n    billings = models[:billing].find(mbillings.collect{|i| i.module_id})\r\n    billings = billings.collect{|b| b if b.billing_type==\'2\' and b.type_of_patient==type }\r\n    billings.compact!\r\n \r\n    bi = []\r\n    \r\n    for i in billings\r\n        bi += i.items    \r\n    end\r\n    \r\n    mbi = {}\r\n    billing_items = models[:billing_item].find(bi)\r\n    for i in billing_items\r\n        mbi[i.id] = i\r\n    end\r\n    \r\n    items = {}\r\n    for i in billings\r\n    \r\n        items[i.id] = [] unless items[i.id]\r\n        for j in i.items\r\n            k = mbi[j] \r\n            items[i.id] << k.product_id if product_struct_map[k.product_id]\r\n        end\r\n    end\r\n    \r\n\r\n    # billing_patient = {}\r\n    # for  i  in billing_m\r\n    #     billing_patient[i.module_id] = patients[i.patient_id]\r\n    # end\r\n    \r\n    \r\n\r\n\r\n    for i in billings \r\n        \r\n        d = m_billings[i.id]\r\n  \r\n        \r\n        for j in items[i.id]\r\n        \r\n            key = d.day\r\n            \r\n            map[j] = {} unless map[j] \r\n            map[j][key] = 0 unless map[j][key]\r\n            map[j][key] += 1\r\n            \r\n            \r\n        end\r\n        \r\n    \r\n    end\r\n    \r\n    \r\n    if true\r\n\r\n    start_date = date.beginning_of_month    \r\n    end_date = date.end_of_month\r\n    days = end_date.day\r\n    \r\n    shows = []\r\n    for i in product_struct_map.keys\r\n        shows << product_map[i]\r\n    end\r\n    \r\n    time = \'IPD\'\r\n    \r\n    time = \'OPD\' if params[:month][:type]==\'OPD\'\r\n    \r\n %>\r\n <h1>\r\n     \r\n     รายงานค่าบำรุงอุปกรณ์ทางการแพทย์ ผู้ป่วยคลินิคพิเศษ \r\n     <%=time%>\r\n     ห้องส่องกล้อง Surgical Endoscopy  \r\n     ประจำวันที่ \r\n     <%= start_date.day %> - <%= end_date.day %> <%=thmonth date.month%> <%=date.year+543%>\r\n     \r\n </h1>\r\n <table class=\"table\" style=\"border-collapse: collapse; width:100%\">\r\n     <thead>\r\n     <tr>\r\n         <th rowspan=\"2\">ชื่อหัตถการ</th>\r\n         <th rowspan=\"2\">รหัส</th>\r\n         <th rowspan=\"2\">ราคาต่อหน่วย</th>\r\n         <th colspan=\"<%=end_date.day%>\">\r\n        <center>\r\n             จำนวนหัตถการต่อวันในแต่ละวันทำการ\r\n             </center>\r\n         </th>\r\n          <th rowspan=\"2\">รวม</th>\r\n         \r\n     </tr>\r\n     <tr>\r\n          <% days.times do |d| %>\r\n          <th><%=d+1%></th>\r\n          <% end %>\r\n     </tr>\r\n         \r\n     </thead>\r\n     <tbody>\r\n     <% \r\n     tsum= 0 \r\n     \r\n     for p in shows \r\n     \r\n     price = product_struct_map[p.id].to_i\r\n     sum = 0 \r\n     %>\r\n     <tr>\r\n        <td><%=p.name%></td> <td><%=p.code %></td>  <td><%=fn price%></td>\r\n        <% days.times do |d| \r\n            \r\n            day = Date.new date.year, date.month, d+1\r\n            \r\n            sum+= map[p.id][d+1] * price if map[p.id]  and map[p.id][d+1]\r\n            \r\n            cls = \'alt\' if day.wday==6 or day.wday==0\r\n            \r\n        %>\r\n        <td class=\"<%=cls%>\"><%=map[p.id][d+1] if map[p.id] and map[p.id][d+1] %> \r\n        </td>\r\n        <% end %>\r\n        <td><%=fn sum%></td>\r\n        <%\r\n            tsum += sum\r\n        %>\r\n     </tr>\r\n     <% end %>\r\n     <tr>\r\n         <td colspan=\"<%=3+end_date.day%>\">&nbsp;</td>\r\n         <td><%=fn tsum%></td>\r\n     </tr>\r\n     </tbody>\r\n </table>\r\n\r\n\r\n<%\r\n  index = 0 \r\n%>\r\n <table class=\"table\" style=\"border-collapse: collapse; width:100%;page-break-before: always;\">\r\n      <thead>\r\n     <tr><th>No.</th>\r\n         <th>วันที่</th> <th>HN</th>\r\n           <th>Type</th>\r\n         <th>ชื่อ-สกุล</th>\r\n         <th>อายุ (ปี)</th>\r\n         <th>รายการหัตถการ</th>\r\n     </tr>        \r\n         </thead>\r\n        \r\n         <tbody>\r\n         \r\n         <%\r\n            billings.each do |i| \r\n            d = m_billings[i.id]\r\n            p = patients[rm_billings[i.id]]\r\n            it = items[i.id].collect{|i| product_map[i].name+\" (\\\\#{product_map[i].code})\"}.join(\", \")\r\n            \r\n            \r\n         %>\r\n         \r\n         \r\n    <% if index%35==0 and index!=0  %>     \r\n     </tbody>\r\n     </table>\r\n     \r\n     <table class=\"table\" style=\"border-collapse: collapse; width:100%;page-break-before: always;\">\r\n      <thead>\r\n     <tr><th>No.</th>\r\n         <th>วันที่</th> <th>HN</th>\r\n         <th>Type</th>\r\n         <th>ชื่อ-สกุล</th>\r\n         <th>อายุ (ปี)</th>\r\n         <th>รายการหัตถการ</th>\r\n     </tr>        \r\n         </thead>\r\n        \r\n         <tbody>\r\n         \r\n    <% end %>\r\n         \r\n         \r\n     <tr>\r\n        <td><%=index+1%></td>\r\n        <td><%=d.strftime(\"%d/%m/%Y\") %></td>\r\n          <td><%=p[0] %></td>\r\n         <td><%=type%></td>\r\n         <td><%=p[1] %></td>\r\n         \r\n         <td><%=((Time.now - p[2].to_datetime)/3600/24/365).to_i if p[2]%>\r\n             \r\n             <%=\"No Birth Date\" unless p[2] %>\r\n             \r\n         </td>\r\n       \r\n         <td><%=it%>\r\n             \r\n             \r\n         </td>\r\n         \r\n     </tr>\r\n     <% \r\n     index += 1\r\n     \r\n     end %>\r\n     \r\n         </tbody>\r\n     \r\n </table>\r\n\r\n\r\n<%  else %>\r\n<div class=\"alert\" ><h1>There is no records</h1></div>\r\n<%=link_to \'Back\', \'print_report\'%>\r\n<%  end %>\r\n\r\n<script>\r\n    window.print()\r\n</script>\r\n\r\n<% end %>\r\n \r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2016-12-12 15:37:32','2016-12-12 15:37:32','instrument_report',''),(2807,'document_name',1130,1,'\'waiting\'',NULL,NULL,NULL,'2016-12-13 03:30:28','2016-12-13 03:30:28',NULL,NULL),(2808,'document_name',1131,1,'\'ward\'',NULL,NULL,NULL,'2016-12-13 04:17:59','2016-12-13 04:17:59',NULL,NULL),(2810,'document_name',1132,1,'\'pre_operative_visit\'',NULL,NULL,NULL,'2016-12-13 06:51:16','2016-12-13 06:51:16',NULL,NULL),(2811,'document_name',1134,1,'\'vital_sign\'',NULL,NULL,NULL,'2016-12-13 07:25:41','2016-12-13 07:25:41',NULL,NULL),(2812,'main',1061,2,'<style>\r\n                .dataTables_wrapper{position:relative;overflow:hidden}\r\n                .dataTables_wrapper table.table {clear:both;margin-bottom:6px!important;max-width:inherit}\r\n                .dataTables_wrapper table.table thead .sorting,table.table thead .sorting_asc,table.table thead .sorting_desc,table.table thead .sorting_asc_disabled,table.table thead .sorting_desc_disabled{cursor:hand;cursor:pointer}\r\n                .dataTables_wrapper table.table thead .sorting{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_both.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc_disabled.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc_disabled.png) no-repeat center right}\r\n</style>\r\n<!-- datatable -->\r\n            <script src=\"/gebo/lib/datatables/jquery.dataTables.min.js\"></script>\r\n            <script src=\"/gebo/lib/datatables/extras/Scroller/media/js/Scroller.min.js\"></script>\r\n            <!-- datatable functions -->\r\n            <script src=\"/gebo/js/gebo_datatables.js\"></script>\r\n<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\n	end\r\n	if session[module_name]\r\n	  params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n	%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n    if l_id = params[:reset_lock]\r\n        m_lock = get_model[:locker]\r\n        lock = m_lock.find(l_id)\r\n        lock.destroy if lock\r\n    end\r\n    \r\n    if params[:status] and params[:aid]\r\n        app = get_model[:appointment].find(params[:aid])\r\n        app[:status] = params[:status]\r\n        app.save\r\n    end\r\n\r\n	if request.post?\r\n	    r_app = get_model[:appointment].find(params[:app_id])\r\n	    status = \'Waiting\'\r\n	    if params[:app_status]\r\n	        status = params[:app_status]\r\n	    end\r\n	    r_app.update_attributes :status=>params[:app_status], :qn=>params[:qn]\r\n	end\r\n	\r\n	\r\n	\r\n	\r\n	if params[:obj_id]\r\n	    now = Time.now \r\n	\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n\r\n            \r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n					<a href=\"../Appointment/create?return=../Home/main\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Appointment</button></a>\r\n					<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n						-->\r\n					<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Calendar</button></a>\r\n					<a href=\"../Home/report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n					<a href=\"room_index?date=<%= params[:date] %>\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-folder_modernist_opened\"></i><br />Room</button></a>\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\" >\r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n					<h1 id=\'clock\'><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Do you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n	 function change_room(obj) {\r\n	     if (confirm(\"Do you want to update Room to \'\" + obj.value + \"\' ?\")) {\r\n	         window.location = \"update_status?id=\"+obj.id+\"&room=\"+obj.value;\r\n	     }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n%>\r\n\r\n\r\n<% if false %>\r\n<%\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed waiting arrived preparing processing recovery completed discharge cancelled no_show}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	list = aps.clone\r\n	id = \'\'\r\n	aps.collect!{|i| \r\n	id = i.id\r\n	  if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n	     patient = patient_model.find(m.patient_id)\r\n	     if patient \r\n	     provider = p_model.find(i.provider)\r\n	     visit_type = visits[i.visit_type]\r\n	     provider_name = \'-\'\r\n	     provider_name = provider.name if provider\r\n	     procedure_name = \'-\'\r\n	     pro = models[:procedure].find(i.procedure) \r\n	     procedure_name = pro.name if pro\r\n	     patient = patient_model.new unless patient \r\n	     hn = \'-\'\r\n	     hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n	     public_id = \'-\'\r\n	    # public_id = patient.public_id if patient\r\n	    # change to use update queue number\r\n	    #  c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n	    #  :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	    #  :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	    #  :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n	    #  :visit_type=>visit_type\r\n	    #  }\r\n	    n_txt = []\r\n	    if !i[:qn].nil?\r\n	        n_txt << \"Q:\\\\#{i[:qn]}\"\r\n	    end\r\n	    if i.note != \'\'\r\n	        n_txt << i.note\r\n	    end\r\n	    d_qn = \"...\"\r\n	    d_qn = \"..\\\\#{patient[:hn].tr(\'/\',\'\')[-5..-3]}/\\\\#{patient[:hn].tr(\'/\',\'\')[-2..-1]}\" if patient and  patient[:hn]\r\n	    \r\n	    c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n	     :pending_ctrl=>link_to(\'Arrived\',\"javascript:patient_q(\'\\\\#{i.id}\',\'\\\\#{d_qn}\');\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n	     :visit_type=>visit_type,\r\n	     :note=>n_txt.join(\' / \')\r\n	    }\r\n	     \r\n	    if i.status==\'Waiting\' or i.status==\'Arrived\' or i.status==\'Preparing\'\r\n	        c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    \r\n	\r\n	    #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n	    else\r\n	        status = \'btn-info\'\r\n	        status = \'\' if i.status ==\'Completed\' or \'Discharge\'\r\n	        c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n	    end\r\n	     c\r\n	    end\r\n	  end\r\n	}.compact!\r\n	\r\n	waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\' or i[:status]==\'Arrived\' or i[:status]==\'Preparing\'}.compact\r\n	\r\n	processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n	\r\n	completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' or i[:status]==\'Discharge\' }.compact\r\n	\r\n	cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n	\r\n	table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n	:note=>\'Note\',:visit_type=>\'Group\' }\r\n	\r\n	%>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">adfdf\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n                	\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in processing\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Processing \r\n				<div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in completed\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Completed \r\n				<div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<% providers.each_pair do |k,v| %>\r\n				<%= k %><br/>\r\n				<%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n	<%\r\n		providers = {}\r\n		\r\n		for i in cancelling\r\n		    p = i[:provider]\r\n		    providers[p]=[] unless providers[p]\r\n		    providers[p] << i\r\n		end\r\n		\r\n		\r\n		%>\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Cancelled &amp; No show \r\n				<div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<p>\r\n				  <% providers.each_pair do |k,v| %>\r\n				  <%= k %><br/>\r\n				  <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n				  <% end %>\r\n			  </p>\r\n			\r\n            </div>\r\n		</div>\r\n	</div>\r\n	<!--\r\n		<div class=\"left\" style=\"width:50%\">\r\n		   <div class=\"w-box\" id=\"w_sort05\">    \r\n		        <div class=\"w-box-header\">\r\n		            Today Patients\r\n			    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n			    </div>\r\n			    <div class=\"w-box-content cnt_a\">\r\n			        content\r\n		        </div>\r\n		    </div>\r\n		</div>\r\n		-->\r\n</div>\r\n<% end %>\r\n<br/>\r\n<br/>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:320px;left:50%;margin-left:-360px\">\r\n	<div class=\"modal-header\">\r\n		<a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n		<h3>Patient Queue</h3>\r\n	</div>\r\n	<div class=\"modal-body\">\r\n		<form name=\'q\' method=\'post\'>\r\n			<span style=\'width:80px\'>Queue Number : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"qn\" id=\'qn\' style=\"width:50px\"/>\r\n			</span>\r\n			<input type=\"hidden\" name=\"app_id\" id=\"app_id\" value=\"\">\r\n			<input type=\"hidden\" name=\"app_status\" id=\"app_status\" value=\"Arrived\">\r\n			<div class=\"clear\"></div>\r\n			<input type=\"submit\" name=\"Submit\" value=\"Submit\" class=\"btn btn-success\"/>\r\n		</form>\r\n	</div>\r\n</div>\r\n<script>\r\n	function patient_q(app_id) {\r\n	    console.log(\"appointment id : \" + app_id);\r\n	    $(\'#app_id\').val(app_id);\r\n	    $(\'#modal\').modal({\r\n	        show: true, \r\n	        backdrop: \'static\',\r\n	        keyboard: true\r\n	    });\r\n	}\r\n	function patient_q(app_id, qn) {\r\n	    console.log(\"appointment id : \" + app_id);\r\n	    $(\'#qn\').val(qn);\r\n	    $(\'#app_id\').val(app_id);\r\n	    $(\'#modal\').modal({\r\n	        show: true, \r\n	        backdrop: \'static\',\r\n	        keyboard: true\r\n	    });\r\n	}\r\n</script>\r\n\r\n<script>\r\n    $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'main_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n    \r\n    function startTime() {\r\n        var today = new Date();\r\n        var h = today.getHours();\r\n        var m = today.getMinutes();\r\n        var s = today.getSeconds();\r\n        m = checkTime(m);\r\n        s = checkTime(s);\r\n        // document.getElementById(\'txt\').innerHTML =\r\n        txt = h + \":\" + m + \":\" + s;\r\n        $(\'#clock\').html(txt);\r\n        var t = setTimeout(startTime, 500);\r\n    }\r\n    function checkTime(i) {\r\n        if (i < 10) {i = \"0\" + i};  // add zero in front of numbers < 10\r\n        return i;\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        setTimeout(feed_page(100), 0);\r\n        loadPartial();\r\n        \r\n        startTime();\r\n    });\r\n    \r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Room\',\'print_room?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Nurse Index\',\'nurse_index?date=\'+params[:date] %> |\r\n<!--<%= link_to \'Case Index\',\'case_index?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Patient Status\',\'patient_status?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Patient Board\',\'../Feed/nurse_board?date=\'+params[:date] %> |-->\r\n<%= link_to \'Status Feed\',\'status_feed?date=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n',NULL,NULL,NULL,'2016-12-14 05:40:52','2016-12-14 05:40:52','main',''),(2813,'exportx',599,3,'<% \r\n    tb = Time.now \r\n    \r\n    params[:date] = \'all\'\r\n    \r\n    doc = get_document this.document_name\r\n    # field map\r\n    fm = {}\r\n    # field list\r\n    fl = []\r\n    # document field\r\n    df = {}\r\n    doc.fields.each do |i|\r\n        ft = i[:field_type]\r\n        if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n            next\r\n        end\r\n        \r\n        cn = i[:column_name].to_sym\r\n        fl << cn\r\n        fm[cn] = i.to_h\r\n        \r\n        if i[:lov_type] == \'pair\'\r\n            tmp = {}\r\n            tmp[:name] = i[:name]\r\n            tmp[:list] = []\r\n            tmp[:pair] = {}\r\n            lov = i[:lov].to_s.split(\'\\r\\n\')\r\n            lov.each do |j|\r\n                x = j.split(\'|\')\r\n                tmp[:pair][x[0].strip] = x[1].strip\r\n                tmp[:list] << x[1].strip\r\n            end\r\n            \r\n            fm[cn][:list] = tmp[:list]\r\n            fm[cn][:pair] = tmp[:pair]\r\n        end\r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	m_pat = @ehr_model[:patient]\r\n	m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	# map prov_id <-> provider_name\r\n	prov = {}\r\n	a_prov = get_model[:provider].all\r\n	a_prov.each do |i|\r\n	    prov[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map company_id <-> company_name\r\n	comp = {}\r\n	a_comp = get_model[:company].all\r\n	a_comp.each do |i|\r\n	    comp[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map knee_component <--> component_name\r\n	kcom = {}\r\n	a_temp = get_model[:knee_component].all\r\n	a_temp.each do |i|\r\n	    kcom[i.id.to_s] = i[:name]\r\n	end\r\n	# map hip component <-> component_name\r\n# 	hcom = {}\r\n# 	a_temp = get_model[:hip_component].all\r\n# 	a_temp.each do |i|\r\n# 	    hcom[i.id.to_s] = i[:name]\r\n# 	end\r\n    \r\n    # map colpo_id <-> colpo\r\n    colpo = {}\r\n    ids   = []\r\n    a_col = get_model[this.document_name.to_sym].all\r\n    a_col.each do |i|\r\n        ids << i.id\r\n        colpo[i.id.to_s] = i\r\n    end\r\n    \r\n    # colpo\'s module_model\r\n    mm_col = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{this.document_name}\", :module_id=>ids).all\r\n    \r\n    # map patient_id <-> patient\r\n    pat = {}\r\n    rs_pat = m_pat.find(mm_col.collect{|i| i[:patient_id]})\r\n    rs_pat.each do |i|\r\n        pat[i.id.to_s] = i\r\n    end\r\n\r\n    # patient fields\r\n    pf = [:hn, :name, :age, :hospital]\r\n    # colposcopy fields\r\n    colf = pf + fl\r\n    \r\n    rs_col = []\r\n    rs_les = []\r\n    mm_col.each do |i|\r\n        # patient\r\n        pt = pat[i[:patient_id].to_s]\r\n        # colpo\r\n        cp = colpo[i[:module_id].to_s]\r\n        \r\n        today = cp[:created_at]\r\n        d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  pt[:birth_date].day) : today\r\n        age = !pt[:birth_date].nil? ? d.year - pt[:birth_date].year - (d > today ? 1 : 0) : 0\r\n        \r\n        \r\n        tmp = {}\r\n        tmp[:hn]  = pt[:hn]\r\n        tmp[:name]= \"\\\\#{pt[:first_name]} \\\\#{pt[:last_name]}\"\r\n        tmp[:age] = age\r\n        tmp[:hospital] = pt[:hospital]\r\n        \r\n        les = []\r\n        \r\n        fl.each do |j|\r\n            x = fm[j]\r\n            # x = {}\r\n            v = cp[j]\r\n            if x.to_h.has_key? :pair and !v.nil?\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                \r\n                tmp[j] = a.join(\',\')\r\n            elsif x[:column_name] == \'implant_profile\'\r\n                tmp[j] = v.size\r\n                les = v\r\n            elsif x[:column_name] == \'image\'\r\n                tmp[j] = v.size\r\n            elsif x[:column_name].include? \'provider_\' or x[:column_name] == \'recorder_by\'\r\n                name = prov[v.to_s]\r\n                if name\r\n                    tmp[j] = name\r\n                else\r\n                    tmp[j] = v\r\n                end\r\n            elsif x[:column_name].include? \'component_\'\r\n                if x[:column_name].include? \'company\'\r\n                    tmp[j] = comp[v.to_s]\r\n                else\r\n                    tmp[j] = kcom[v.to_s]\r\n                end\r\n            else\r\n                tmp[j] = v\r\n            end\r\n        end\r\n        \r\n        rs_col << tmp\r\n    end\r\n    \r\n    res = {}\r\n    # res[:af]   = af\r\n    res[:res]  = rs_col\r\n    res[:time] = Time.now - tb\r\n     \r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\nif false\r\n%>\r\n    <%= colf.join(\'!\') %>\r\n    <br/>\r\n    <%\r\n        rs_col.each do |i|\r\n            colf.each do |j|\r\n    %>\r\n    <%= i[j] %>!\r\n    <%\r\n            end\r\n    %>\r\n    <br/>\r\n    <%\r\n        end\r\n    %>\r\n    \r\n    <br/>\r\n    <br/>\r\n    <hr/>\r\n    <br/>\r\n    <%= lesf.join(\'!\') %>\r\n    <br/>\r\n    <%\r\n        rs_les.each do |i|\r\n         