e000004	57ad8186790f9b55ee00000e	57ad82f1790f9b66b8000001	57b2a657790f9b0d18000001	57b7bf98790f9b30a900000c	57b7fc4d790f9b0deb000001	57bd4561790f9b5a0700000f	57c3dee8790f9b755400000b	57e155c0790f9b44ab000021	57e163ce790f9b4bd1000003	57ac2990790f9b79f000003b	57ac2d1a790f9b63c4000085	57ac300e790f9b196e000008	57ac3016790f9b19de000005	57aeb227790f9b5f5b000009	57c653c3790f9b2ddd000006	583fb46b790f9b422c00000b	57ac302c790f9b196e00000c	57ac3040790f9b194c000006	57ad82bf790f9b6615000001	57ad82f0790f9b6422000003	57ad8ef3790f9b717f00000e	57ad82f5790f9b66b8000003	57ad82f7790f9b6422000005	57ad82f7790f9b6615000003	57ad8318790f9b6615000005	57ad831c790f9b6615000007	57ed3b70790f9b2264000001	57ed3bca790f9b2264000007	57ae846d790f9b2516000001	57ae8ef0790f9b397c000003	57aea21a790f9b457d000001	57aea8fe790f9b5603000001	57ff023c790f9b7a1000000e}\r\n    pat_ids = mm_proc.collect{|i| i[:patient_id].to_s}\r\n    pat_ids = pat_ids - ig_pat\r\n    pat = {}\r\n    rs_pat = m_pat.find(pat_ids)\r\n    rs_pat.each do |i|\r\n        pat[i.id.to_s] = i\r\n    end\r\n\r\n    # main fields\r\n    mf = get_doc_field doc_name\r\n    @fm = mf\r\n\r\n    # patient fields\r\n    pf = [:id, :hn, :name, :hospital, :age, :gender]\r\n    # colposcopy fields\r\n    colf = pf + mf.keys + [:follow_up]\r\n    colf = colf - [:image_pre_op, :image_intra_op, :image_implant_barcode, :operative_note, :recorder_by, :hn, :name, :hospital]\r\n    \r\n    rs_col = []\r\n    rs_les = []\r\n    \r\n    # patient-follow_up\r\n    pat_foll = {}\r\n    # patient-implant_profile\r\n    pat_imp  = {}\r\n    # all_follow_up\r\n    fol_list = []\r\n    # all_implant_profile\r\n    imp_list = []\r\n    mm_proc.each do |i|\r\n        pat_id = i[:patient_id].to_s\r\n        par_id = i[:parent_id].to_s\r\n        # patient\r\n        pt = pat[i[:patient_id].to_s]\r\n        # colpo\r\n        cp = colpo[i[:module_id].to_s]\r\n        \r\n        if pt.nil?\r\n            next\r\n        end\r\n        \r\n        today = cp[:created_at]\r\n        # d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  pt[:birth_date].day) : today\r\n        d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  1) : today\r\n        age = !pt[:birth_date].nil? ? d.year - pt[:birth_date].year - (d > today ? 1 : 0) : 0\r\n        \r\n        \r\n        tmp = {}\r\n        tmp[:id]  = pt.id.to_s[5..14]\r\n        tmp[:hn]  = pt[:hn]\r\n        tmp[:name]= \"\\\\#{pt[:first_name]} \\\\#{pt[:last_name]}\"\r\n        tmp[:age] = age\r\n        tmp[:hospital] = pt[:hospital]\r\n        tmp[:gender] = pt[:gender]\r\n        \r\n        mf.keys.each do |j|\r\n            x = mf[j]\r\n            # x = {}\r\n            v = cp[j]\r\n            if x.to_h.has_key? :pair and !v.nil?\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                \r\n                tmp[j] = a.join(\',\')\r\n            elsif x[:column_name].include? \'implant_profile\' \r\n                tmp[j] = v\r\n                \r\n                if v.size != 0\r\n                    imp_list += v\r\n                    if !pat_imp.has_key? pat_id\r\n                        pat_imp[pat_id] = {}\r\n                    end\r\n                    pat_imp[pat_id][j] = v\r\n                end\r\n                \r\n            elsif x[:column_name] == \'image\'\r\n                tmp[j] = v.size\r\n            elsif x[:column_name].to_s.include? \'provider_\' or x[:column_name] == \'recorder_by\'\r\n                name = prov[v.to_s]\r\n                if name\r\n                    # tmp[j] = name\r\n                    tmp[j] = v.to_s[0..9]\r\n                else\r\n                    tmp[j] = v\r\n                end\r\n            elsif x[:column_name].include? \'component_\' or x[:column_name].include? \'company\'\r\n                if x[:column_name].include? \'company\'\r\n                    tmp[j] = comp[v.to_s]\r\n                else\r\n                    tmp[j] = kcom[v.to_s]\r\n                end\r\n            else\r\n                tmp[j] = v\r\n            end\r\n        end\r\n        \r\n        tmp[:follow_up] = gr_foll[par_id].nil? ? 0 : gr_foll[par_id].size\r\n        \r\n        if tmp[:follow_up] != 0\r\n            pat_foll[pat_id] = gr_foll[par_id]\r\n            fol_list += gr_foll[par_id].collect{|i| i[:module_id]}\r\n        end\r\n        \r\n        rs_col << tmp\r\n    end\r\n    \r\n    res = {}\r\n    # res[:af]   = af\r\n    res[:res]  = rs_col.size\r\n    res[:mm_foll] = mm_foll.size\r\n    res[:imp_size] = imp_list.size\r\n    res[:fol_size] = fol_list.uniq.size\r\n    res[:pat_foll] = pat_foll\r\n    res[:pat_imp]  = pat_imp\r\n    res[:time] = Time.now - tb\r\n     \r\n%>\r\n<!-- Main Procedure -->\r\n<h3><%= doc_name.humanize %> total <%= rs_col.size %> records</h3>\r\n<%= colf.join(\'|\') %><br/>\r\n<%\r\n    \r\n    rs_col.each do |i|\r\n        colf.each do |j|\r\n%>\r\n<%= i[j] %>|\r\n<%\r\n        end\r\n%>\r\n<br/>\r\n<%\r\n    end\r\n    if fol_list.size != 0\r\n        # field map\r\n        fm = get_doc_field fol_doc\r\n        @fm = fm\r\n%>\r\n<br/>\r\n\r\n<!-- Follow up -->\r\n<h3><%= fol_doc.humanize %> total <%= fol_list.size %> records</h3>\r\n<%\r\n    res_fol = get_model[fol_doc.to_sym].find(fol_list)\r\n    \r\n    # gr_fol = res_fol.group_by{|i| i.id}\r\n    gr_fol = res_fol.group_by{|i| i[:_id]}\r\n    \r\n    colf = [:id] + fm.keys - [:image, :recorder_by]\r\n%>\r\n<%= colf.join(\'|\') %><br/>\r\n<%\r\n    pat_foll.each do |k,v|\r\n        id = k[5..14]\r\n\r\n        v.each do |i|\r\n            mid = i[:module_id]\r\n            obj = gr_fol[mid][0] if gr_fol[mid]\r\n            if obj.nil?\r\n                next\r\n            end\r\n            obj[:id] = id\r\n            \r\n            colf.each do |j|\r\n%>\r\n<%= get_value j, obj[j] %>|\r\n<%\r\n            end\r\n%>\r\n<br/>\r\n<%\r\n        end\r\n%>\r\n<%\r\n    end\r\n    end # end fol_list.size // check for follow up\r\n    \r\n    if imp_list.size != 0\r\n%>\r\n<!-- Implant Profile -->\r\n<h3>Implant Profile total <%= imp_list.size %> records</h3>\r\n<%\r\n        m_company = get_model[:implant_company].all\r\n        m_component = get_model[:implant_component].all\r\n        m_type   = get_model[:implant_type].all\r\n        m_material  = get_model[:implant_material].all\r\n        \r\n        g_company = m_company.group_by{|i| i.id}\r\n        g_component = m_component.group_by{|i| i.id}\r\n        g_type    = m_type.group_by{|i| i.id}\r\n        g_material= m_material.group_by{|i| i.id}\r\n        \r\n        res_rec  = get_model[:implant_record].find(imp_list)\r\n        imp_ids  = res_rec.collect{|i| i[:component_description]}\r\n        res_imp  = get_model[:implant_profile].find(imp_ids)\r\n        \r\n        gr_rec   = res_rec.group_by{|i| i[:_id]}\r\n        gr_imp   = res_imp.group_by{|i| i[:_id].to_s}\r\n        \r\n        fm = get_doc_field \'implant_record\'\r\n        @fm = fm\r\n        \r\n        colf = [:id, :status] + fm.keys + [:product_id, :barcode]\r\n        \r\n        xxx = {}\r\n        xxx[:rec] = gr_rec\r\n        xxx[:imp] = gr_imp\r\n%>\r\n<%= colf.join(\'|\') %><br/>\r\n<% x = 0\r\n        pat_imp.each do |key, val|\r\n            id = key[5..14]\r\n            \r\n            val.each do |k,v|\r\n                st = k\r\n                v.each do |i|\r\n                    tmp = gr_rec[i]\r\n                    \r\n                    if tmp.nil?\r\n                        next\r\n                    end\r\n                    obj = tmp[0]\r\n                    obj[:id] = id\r\n                    obj[:status] = st\r\n                    \r\n                        x += 1\r\n                    colf.each do |j|\r\n                        v = obj[j]\r\n                        if v.nil? or v == \'\'\r\n                            v = \'\'\r\n                        elsif j == :company_ref_id\r\n                            v = g_company[v][0][:company_name]\r\n                        elsif j == :component_ref_id\r\n                            v = g_component[v][0][:component_name]\r\n                        elsif j == :type_ref_id\r\n                            v = g_type[v][0][:type_name]\r\n                        elsif j == :component_description\r\n                            a = v.to_s\r\n                            v = gr_imp[v.to_s][0][:component_description]\r\n                            if v\r\n                                obj[:product_id] = gr_imp[a][0][:product_id]\r\n                                obj[:barcode]    = gr_imp[a][0][:barcode]\r\n                            end\r\n                        end\r\n%>\r\n<%= v %>|\r\n<%\r\n                    end\r\n%>\r\n<br/>\r\n<%\r\n                end\r\n            end\r\n            \r\n            \r\n            if false # for implant profile display\r\n            val.each do |k, v|\r\n                st = k\r\n                v.each do |i|\r\n                    \r\n                    imp_id = gr_rec[i][0][:component_description] if gr_rec[i]\r\n                    \r\n                    if imp_id.nil?\r\n                        next\r\n                    end\r\n                    \r\n                    obj = gr_imp[imp_id.to_s][0] if gr_imp[imp_id.to_s]\r\n                    if obj.nil?\r\n                        # next\r\n                        obj = {}\r\n                        obj[:company_id] = imp_id\r\n                    end\r\n                    \r\n                    obj[:id] = id\r\n                    obj[:status] = k\r\n                    \r\n                    colf.each do |j|\r\n                        v = obj[j]\r\n                        \r\n                        if v.nil? or v == \'\'\r\n                            v = \'\'\r\n                        elsif j == :company_ref_id\r\n                            v = g_company[v][0][:company_name]\r\n                        elsif j == :component_ref_id\r\n                            v = g_component[v][0][:component_name]\r\n                        elsif j == :type_ref_id\r\n                            v = g_type[v][0][:type_name]\r\n                        elsif j == :material_ref_id\r\n                            v = g_material[v][0][:material_name]\r\n                        end\r\n                    \r\n%>\r\n<%= v %>|\r\n<%\r\n                    end\r\n%>\r\n<br/>\r\n<%\r\n                end\r\n            end\r\n            end # if false\r\n%>\r\n<% end %>\r\n<%\r\n    end # end imp_list.size // check for implant\r\n%>\r\n<%= x %>\r\n<hr/>\r\nProcessing Time : <%= Time.now - tb %>\r\n',NULL,NULL,NULL,'2016-12-15 15:04:35','2016-12-15 15:04:35','exportx',''),(2819,'print_appointment',1064,2,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n provider = providers[ap.provider.to_s]\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year} ปี \\\\#{month} เดือน \\\\#{day} วัน\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>pro[ap.procedure],\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>provider.name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'age\'=>age,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\nlist = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm/cusys/obgyn/logo.jpg\" width=\"140\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงรายการผู้ป่วย\r\n<span style=\"float:right\">ประจำวันที่ \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th>Type</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>HN</th>\r\n    <th >อายุ</th>\r\n    <th>เลขประชาชน</th>\r\n    <th>Indication</th>\r\n    <th>Procedure</th>\r\n    <th>Provider</th>\r\n    <th>Tel.</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n  <% list.each_with_index do |i,index|  %>\r\n    <tr style=\"height:110px\">\r\n    <td><%=index+1%>.</td>\r\n    <td><%=i[\'visit_type\']%></td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%></td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'age\']%></td>\r\n    <td><%=i[\'public_id\']%></td>\r\n    <td><%=i[\'indication\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    <td><%=i[\'provider\']%></td>\r\n    <td><%=i[\'tel\']%></td>\r\n    </tr>\r\n    <% end %>\r\n</tbody>\r\n  </table><br/>\r\n  </div>\r\n  </div></div></div></div></div>\r\n</body>\r\n</html>\r\n<% end %>\r\n',NULL,NULL,NULL,'2016-12-16 01:40:59','2016-12-16 01:40:59','print_appointment',''),(2820,'index_dev',721,2,'<%\r\n    @tb = Time.now\r\n    \r\n    module_name = @current_project.name\r\n    if params[:date]\r\n    	session[module_name]={:date=>params[:date]}\r\n    end\r\n    if session[module_name]\r\n    	params[:date] = session[module_name][:date]\r\n    end\r\n    unless params[:date]\r\n    	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n    end\r\n    \r\n    if session[:owner].nil?\r\n        session[:owner] = false\r\n    end\r\n    \r\n    if @current_role==\'developer\'\r\n        session[:owner] = true\r\n        session[:pin] = \'\'\r\n    end\r\n\r\n%>\r\n\r\n<style>\r\n\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n</style>\r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n    # status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n    \r\n    if session[:pin].nil?\r\n        r_user = model[:user].where(:login=>@current_user.login.to_s).first\r\n        if r_user[:pin]\r\n            session[:pin] = r_user[:pin].to_s\r\n        else\r\n            session[:pin] = \'\'\r\n        end\r\n    end\r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n\r\n    \r\n    provider = models[:provider].where(:login=>@current_user.login).first\r\n    if provider\r\n      s_provider = provider.id.to_s\r\n    end\r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %>\r\n    <%= error%>\r\n    <%\r\n        session.delete :s_date\r\n    end # end begin\r\n    %>\r\n    \r\n    <%\r\n    search_patient = false\r\n    \r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n        end\r\n        session[:s_status] = s_status\r\n        session[:s_provider] = s_provider \r\n        \r\n    end\r\n    \r\n    add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n    # PIN Section\r\n    in_pin = nil\r\n    if p = params[:record]\r\n        in_pin = p[:pin]\r\n        if p[:patient_id] != \'\' and in_pin == session[:pin] and p[:mode] == \'delete\'\r\n            destroy_url = \"destroy?mode=patient&id=\\\\#{p[:patient_id]}\".html_safe\r\n            return_url  = \"&return=\\\\#{request.fullpath}\".html_safe\r\n%>\r\n<script>\r\n                url = \"<%= destroy_url %><%= return_url %>\";\r\n                window.location = url;\r\n</script>\r\n<%\r\n        elsif p[:mode] == \'unlock\' and in_pin == session[:pin]\r\n            session[:owner] = true\r\n        elsif p[:mode] == \'lock\'\r\n            session[:owner] = false\r\n        end\r\n    end\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       My Patients\r\n       <span style=\'float:right\'>\r\n       <% if session[:owner] %>\r\n                <%= link_to \'<i class=\"splashy-document_a4\"></i> Reports\'.html_safe,\"../Home/report\", :class=>\'btn btn-mini\' %> | \r\n                <%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \"\\\\#{params[:opt]}?record[mode]=lock\", :class=>\'btn btn-mini btn-warning\' %>\r\n                <!--<%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \'javascript:lock_unlock(\"lock\")\', :class=>\'btn btn-mini btn-warning\' %>-->\r\n                <% else %>\r\n                <%=link_to \'<i class=\"splashy-lock_large_unlocked\"></i> Unlock\'.html_safe, \'javascript:lock_unlock(\"unlock\");\', :class=>\'btn btn-mini btn-warning\' %>\r\n        <% end %>\r\n        <!--\r\n        <a href=\'/esm/cusys/thks/Consignment-TH.pdf\' class=\'btn btn-mini\' target=\'_blank\'>\r\n            <i class=\"splashy-document_a4_marked\"></i>\r\n            Consignment (TH)\r\n        </a>\r\n        -->\r\n    </span>\r\n    </div>  \r\n    \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n         <!--comment-->\r\n         <%# params.inspect %><br/>\r\n         <%# s_provider.inspect %>\r\n         <!--end comment-->\r\n<div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>\"../Home/\\\\#{params[:opt]}\",:html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n\r\n<!--           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Date :     \r\n            </label>\r\n            <div class=\"field-input\" >\r\n            <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n           \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Provider :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n            </div>\r\n            </span>\r\n-->            \r\n           \r\n             <%#link_to \'[Calendar]\',\'../Appointment/index\' %>\r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Status :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :status, options_for_select(status_list.collect{|i| [i.humanize,i] }, s_status),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"row-fluid\"></div>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            HN :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Name :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :first_name, :value=>s_first_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n            \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surname :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <%= f.text_field :last_name, :value=>s_last_name,:style=>\"width:100%\"%>\r\n            </div>\r\n            </span>\r\n        <% if @current_role==\'developer\' %>    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n            Surgeon :     \r\n            </label>\r\n            <div class=\"field-input\">\r\n            <% provider = models[:provider].where(:login=>@current_user.login).first\r\n            if provider\r\n            %>\r\n            <%= provider.name %>\r\n            <%= f.hidden_field :provider, :value=>provider.id %>\r\n            <%= f.hidden_field :s_provider, :value=>provider.id %>\r\n            <% else %>\r\n            <%= f.select :provider, options_for_select(providers.collect{|i| [i.name,i.id] }, s_provider),{:include_blank=>true},:style=>\"width:100%\"%>\r\n            <% end %>\r\n            </div>\r\n            </span>\r\n        <% end %>    \r\n            <!--<span class=\"field-data\"> -->\r\n            <!--<label class=\"field-label\">-->\r\n            <!--Operatives :     -->\r\n            <!--</label>-->\r\n            <!--<div class=\"field-input\">-->\r\n            <% # f.select :operative, options_for_select([]),{},:style=>\"width:100%\"%>\r\n            <!--</div>-->\r\n            <!--</span>-->\r\n            \r\n            \r\n            <div class=\"clear\"></div>\r\n            \r\n            <span class=\"field-data\" style=\'width:300px\'> \r\n                <label class=\"field-label\">\r\n                   &nbsp;\r\n                </label> \r\n                \r\n                \r\n                <div class=\"field-input\" style=\'width:200px\'>\r\n                     <%=f.submit \'Search\', :class=>\'btn btn-success\'%> \r\n                     <% if !session[:owner] %>\r\n                     <%= link_to \'Show All\', \"javascript:show_all()\", :class=>\'btn btn-warning\', :style=>\'margin-top:5px\' %>\r\n                     <% end %>\r\n                     <!--<%=f.submit \'Clear\', :type => \"reset\", :class=>\'btn\'%>-->\r\n                </div>\r\n            </span>\r\n    \r\n    \r\n            <span class=\"field-data\"> \r\n            <label class=\"field-label\">\r\n               &nbsp;\r\n            </label> \r\n            <div class=\"field-input\">\r\n            <%\r\n            # Home/patient_record?id=5533e537790f9b01c2000006\r\n                # add_patient = \"../Patient/create?return=../Home/patient_record\" + \"?id=5533e537790f9b01c2000006\".html_safe + \"&data[date]=\\\\#{date_text}\"\r\n                if s_provider \r\n                    # add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                    add_patient += \"&data[provider]=\\\\#{s_provider}\" \r\n                end\r\n                \r\n            %>\r\n              \r\n                 <!--<%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>-->\r\n            </div>\r\n            </span>\r\n    \r\n            <div class=\"clear\"></div>\r\n            \r\n            \r\n<% \r\n	end # end search form\r\n%>\r\n        </div>\r\n        </div>\r\n        <div class=\"row-fluid\"></div>\r\n \r\n<strong>\r\n<%\r\n    rs = []\r\n    if !search_patient and params[:select].nil?\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n    	    if (session[:pin] == in_pin) or session[:owner]\r\n                rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n            else\r\n                \r\n            end\r\n        else\r\n            rs = module_model.where(:module_name=>\"\\\\#{@current_project.name}#provider\").all\r\n    	end\r\n    %>\r\n    <!--ALL : <%= rs.size %>-->\r\n    <%\r\n	elsif search_patient and params[:date]\r\n\r\n		fields = {:hn=>s_hn, :first_name=>s_first_name, :last_name=>s_last_name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        # 	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n            keys << {k.to_sym=>v}\r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n        patients = patient_model.where(criteria).all\r\n        # patients = patient_model.where(criteria).limit(20).all\r\n	    # maps = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}\r\n        # aps = ap_model.find(maps.collect{|i| i.module_id})\r\n    	\r\n    	# filter provider\r\n    	if s_provider and s_provider != \'\'\r\n     	    rs = module_model.where(:patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\", :module_id=>s_provider).all\r\n        else\r\n            rs = module_model.all :patient_id=>{\'$in\'=>patients.collect{|i| i.id}}, :module_name=>\"\\\\#{@current_project.name}#provider\"\r\n    	end\r\n    %>\r\n    <!--SEARCH PATIENT : <%= rs.size %>-->\r\n    <%\r\n    elsif params[:date]\r\n        require \'date\'\r\n        dddd = Date.parse(params[:date])\r\n	    conds = {:date.gte=>dddd.at_beginning_of_day,:date.lt=>dddd.end_of_day, :module_name=>\"\\\\#{@current_project.name}#provider\"}\r\n\r\n	    if s_provider and s_provider !=\'\'\r\n            conds.merge! :module_id=>s_provider \r\n            # conds[:module_id] = s_provider\r\n            # conds[:module_name] = @current_project.name + \"#provider\"\r\n	    end\r\n\r\n    	#if s_status != \"\"\r\n		#    conds.merge! :status=>s_status \r\n	    #end\r\n        rs = module_model.where(conds).all\r\n        # aps = ap_model.all(conds)\r\n    	# filter provider\r\n    # 	if s_provider and s_provider != \'\'\r\n     	  #  conds[:module_id] = s_provider\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    #  	else\r\n     	  #  conds[:module_name] = @current_project.name + \"#provider\"\r\n    # 	end\r\n    	\r\n    # 	rs = module_model.all(conds)\r\n        # rs = module_model.all\r\n\r\n    %>\r\n    <!--DATE : <%=rs.size%> | <%= conds %>-->\r\n    <%\r\n    end # end if\r\n%>\r\n</strong>\r\n<!--<br/>-->\r\n<!--<br/>-->\r\n<%\r\nm_procedure = models[:procedure].all\r\nmap_proc = {}\r\nfor m in m_procedure do\r\n    map_proc[m.id] = m\r\nend\r\n\r\nm_provider  = models[:provider].all\r\nmap_prov = {}\r\nfor m in m_provider do \r\n    map_prov[m.id.to_s] = m[:name]\r\nend\r\n\r\n    pat_ids = rs.collect{|i| i[:patient_id]}\r\n    res_pat = patient_model.find(pat_ids)\r\n    gr_pat  = res_pat.group_by{|i| i.id.to_s}\r\n\r\nresult = rs.collect do |i|\r\n    pat_id = i[:patient_id].to_s\r\n    # m_patient = patient_model.find(i[:patient_id].to_s)\r\n    m_patient = gr_pat[pat_id][0] if gr_pat[pat_id]\r\n    \r\n    # patient_name = m_patient[:prefix_name] + m_patient[:first_name] + \" \" + m_patient[:last_name]\r\n    patient_name = \"\\\\#{m_patient[:prefix_name]}\\\\#{m_patient[:first_name]}   \\\\#{m_patient[:last_name]}\"\r\n    \r\n    # prov = map_prov[i[:id]]\r\n    m_id = i[:module_id].to_s\r\n    prov = map_prov[m_id]\r\n    \r\n    # prov = nil\r\n    proc_rs = []\r\n    # OLD\r\n    # m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    # for m in m_ap do\r\n    #     ap = models[:appointment].find(m[:module_id])\r\n    #     if ap\r\n    #         proc_rs.push(map_proc[ap[:procedure]])\r\n    #     end\r\n    # end\r\n    # NEW\r\n    m_ap = module_model.where(:patient_id=>i[:patient_id].to_s, :module_name=>\"\\\\#{@current_project.name}#appointment\")\r\n    for m in m_ap do\r\n        ap = models[:appointment].find(m[:module_id])\r\n        if ap\r\n            # proc_rs.push(map_proc[ap[:procedure]])\r\n            procedure = map_proc[ap[:procedure]]\r\n            if procedure.nil?\r\n                next\r\n            end\r\n            code = procedure[:code]\r\n            name = procedure[:name]\r\n            m_code = \"\\\\#{@current_project.name}#\\\\#{code}\"\r\n            m_tmp = module_model.where(:module_name=>m_code, :parent_id=>m.id).first\r\n            side = \'-\'\r\n            if m_tmp\r\n                rec = models[code.to_sym].find(m_tmp[:module_id])\r\n                if rec[:side] == \'1\'\r\n                    side = \'L\'\r\n                elsif rec[:side] == \'2\'\r\n                    side = \'R\'\r\n                end\r\n            end\r\n            # txt = name + \" (\" + side + \") \"\r\n            op_txt = \"op : \\\\#{rec[:operation_date]}\" if rec\r\n            txt = \"\\\\#{name} (\\\\#{side}) <span style=\'float:right\'>\\\\#{op_txt}</span>\".html_safe\r\n            \r\n            if @current_role == \'developer\'\r\n                m_tmp = module_model.where(:parent_id=>m.id).collect{|i| i if i[:module_name].include? \'follow\'}\r\n                txt += \"[\" + m_tmp.count.to_s + \"]\"\r\n            end\r\n            \r\n            proc_rs.push(txt)\r\n        end\r\n    end\r\n    \r\n    proc_txt = \'<center><font color=\"red\">-- Create New --</font></center>\'\r\n    if !proc_rs.empty?\r\n        proc_txt = \'\'\r\n        for x in proc_rs do \r\n            if proc_rs.last == x\r\n                proc_txt += \"<div class=\'row-fluid\' style=\'float:left;padding: 0.5em 0 0.5em 0;\'>\\\\#{x.to_s}</div>\"\r\n            else\r\n                proc_txt += \"<div class=\'row-fluid\' style=\'float:left;padding: 0.5em 0 0.5em 0;border-bottom: 1px solid gray;\'>\\\\#{x.to_s}</div>\"\r\n            end\r\n            # proc_txt += \"<div class=\'row-fluid\' style=\'float:left;padding: 0.5em 0 0.5em 0;\'>\\\\#{x.to_s}</div>\"\r\n        end\r\n    end\r\n    action = \' \'\r\n    action += link_to(\'Detail\',\"patient_record?id=\\\\#{i[:patient_id]}\",:class=>\'btn btn-info\')\r\n    action += \" \"\r\n    action += link_to(\'\', \"../../www/Patient/edit?id=\\\\#{m_patient.id}&return=\\\\#{request.fullpath}\", :class=>\'splashy-contact_blue_edit\').html_safe\r\n    action += \" \"\r\n    if session[:owner]\r\n        action += link_to(\'\', \"\", :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{m_patient.id}\'); return false;\")\r\n    else\r\n        action += link_to(\'\', \"\", :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_pin(\'\\\\#{m_patient.id}\'); return false;\")\r\n    end\r\n    action += \" \"\r\n    \r\n    {:date=>i[:date], :hn=>m_patient[:hn], :name=>patient_name, :pid=>i[:patient_id], :procedure=>proc_txt, :action=>action, :provider=>prov}\r\nend\r\ncount = 1\r\nlabels = {:no=>\'No.\', :date=>\'Added Date\', :hn=>\'HN\', :name=>\'Patient Name\', :procedure=>\'Previous Procedure\', :action=>\'Action\'}\r\nfield_select = [:no, :date, :hn, :name, :procedure, :action]\r\n\r\nif @current_role == \'developer\'\r\n    labels[:provider] = \'Provider\'\r\n    field_select.insert(4, :provider)\r\nend\r\nresult = result.sort_by{|i| i[:date]}.reverse\r\n%>\r\n        \r\n        <!--<div class=\"row-fluid\">-->\r\n        <!--    <div style=\"padding-left:10px;display:block;vertical-align:middle\">-->\r\n        <!--        All Patient(s) : <v><%= result.count if result %></v> <%=link_to \'Add Patient\', add_patient, :class=>\'btn btn-info\', :style=>\'margin-top:10px\'%>-->\r\n        <!--    </div>-->\r\n        <!--</div>-->\r\n        <!--<br/>-->\r\n        <div class=\"row-fluid\">\r\n            <br/>\r\n            <div class=\"\" style=\"float:left;margin-left:10px\">\r\n                All Patient(s) : <span style=\"color:blue\"><%= result.count if result %></span>\r\n                <%=link_to \'<i class=\"splashy-contact_blue_add\"></i> Add Patient\'.html_safe, add_patient, :class=>\'btn btn-info btn-mini\', :style=>\'margin-left:10px\'%>\r\n            </div>\r\n            <% if false %>\r\n            <div class=\"\" style=\"float:right;margin-right:10px\">\r\n                <%=link_to \'<i class=\"splashy-sprocket_light\"></i> Setting\'.html_safe, \'../Setting/index\', :class=>\'btn btn-mini\' %> | \r\n                <% if session[:owner] %>\r\n                <%= link_to \'<i class=\"splashy-document_a4\"></i> Reports\'.html_safe,\"../Home/report\", :class=>\'btn btn-mini\' %> | \r\n                <%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \"\\\\#{params[:opt]}?record[mode]=lock\", :class=>\'btn btn-mini btn-warning\' %>\r\n                <!--<%=link_to \'<i class=\"splashy-lock_large_locked\"></i> Lock\'.html_safe, \'javascript:lock_unlock(\"lock\")\', :class=>\'btn btn-mini btn-warning\' %>-->\r\n                <% else %>\r\n                <%=link_to \'<i class=\"splashy-lock_large_unlocked\"></i> Unlock\'.html_safe, \'javascript:lock_unlock(\"unlock\");\', :class=>\'btn btn-mini btn-warning\' %>\r\n                <% end %>\r\n            </div>\r\n            <% end %>\r\n            <br/>\r\n        </div>\r\n        \r\n        <div id=\"result-panel\" style=\"padding:10px\">\r\n<% if result.count > 1 or session[:owner] %>\r\n            <%# tabular :data=>result, :model=>field_select, :labels=>labels, :col_width=>{:no=>50} do |row,out| %>\r\n            <%= tabular :data=>result, :model=>field_select, :labels=>labels, :col_width=>{:no=>80, :procedure=>300} do |row,out|\r\n                    out[0] = \"<center>\" + count.to_s+\".</center>\"\r\n                    out[0] = out[0].html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n            %>\r\n<% elsif result.count == 1  and search_patient %>\r\n<script>\r\n    window.location = \"patient_record?id=<%= result[0][:pid] %>\";\r\n</script>\r\n<% \r\n    else \r\n        if request.post? and !session[:owner]\r\n%>\r\n                        <div style=\'margin: auto;width:60%;\'>\r\n                            <div class=\"alert\">\r\n								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n								<strong>Invalid Private Password.</strong> Please try again or contact administrator for setting your private password.\r\n							</div>\r\n							<div class=\'clear\'></div>\r\n						</div>\r\n<%\r\n        end\r\n%>\r\n            <center><font size=\'2.5em\'><strong>Search Patient to continue.</strong></font></center>\r\n<% \r\n    end\r\n%>\r\n        </div>\r\n        \r\n    </div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function confirm_pin(id) {\r\n        \r\n    }\r\n\r\n    function confirm_delete(id) {\r\n        // destroy?id=\\\\#{m_patient.id}&mode=patient&return=\\\\#{request.fullpath}\r\n<%\r\n    destroy_url = \"destroy?mode=patient&id=\".html_safe\r\n    return_url  = \"&return=\\\\#{request.fullpath}\".html_safe\r\n%>\r\n        if (confirm(\"Do you want to delete patient data ?\") == true) {\r\n            if (confirm(\"All of patient data will be lost\") == true) {\r\n                url = \"<%= destroy_url %>\" + id + \"<%= return_url %>\";\r\n                window.location = url;\r\n            }\r\n        }\r\n    }\r\n    function change_status(obj){\r\n        if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n            window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n        }\r\n    }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\') + \"&select=date&s_provider=<%= s_provider %>\"\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<!--\r\n<div class=\"alert \">\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date] %> |\r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date] %>\r\n</div>\r\n-->\r\n<script>\r\n\r\n    <%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    user = model[:user].where(:login=>@current_user.login).first\r\n    \r\n    %>\r\n    \r\n    function access(target){\r\n        \r\n        var pin = prompt(\"Please enter PIN\", \"\");\r\n        if( \'<%= user ? user.pin : \'-\'%>\'==pin){\r\n            window.location = target\r\n        }\r\n        \r\n        \r\n    }\r\n    \r\n</script>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n\r\n<!--\r\n\r\n    Modal\r\n\r\n-->\r\n\r\n<div class=\"modal hide fade\" id=\"modal-pin\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n        <h3>Private Access</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"pin\" class=\"  portlet \" style=\"border:0px solid blue;width:250px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Please input your private password : </label></span>	\r\n                    <input type=\"password\" name=\"record[pin]\" id=\"data-pin\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n            <%= f.hidden_field :mode, :id=>\'data-mode\', :value=>\'\' %>\r\n            <%= f.hidden_field :patient_id, :id=>\'data-patient_id\', :value=>\'\' %>\r\n            <%= f.submit \'Submit\', :class=>\'btn btn-info\' %>\r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n    function pin() {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function show_all() {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(\'show\');\r\n    }\r\n    function lock_unlock(mode) {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(mode);\r\n    }\r\n    function confirm_pin(id) {\r\n        $(\'#modal-pin\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-mode\').val(\'delete\');\r\n        $(\'#data-patient_id\').val(id);\r\n    }\r\n    <% if false %>\r\n    function check_pin() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    <% end %>\r\n    $(document).ready(function(){\r\n        $(\'#btn-pin\').click(pin);\r\n    });\r\n</script>\r\n<% if @current_role==\'developer\' or @current_user.login==\'ehr@esm-solution.com\' %>\r\n<hr/>\r\nProcessing Time : <%= Time.now - @tb %>\r\n<% end %>',NULL,NULL,NULL,'2016-12-16 03:18:30','2016-12-16 03:18:30','index_dev',''),(2821,'document_name',1138,1,'\'icd_complication\'',NULL,NULL,NULL,'2016-12-17 03:17:55','2016-12-17 03:17:55',NULL,NULL),(2822,'document_name',1139,1,'\'icd_external_cause\'',NULL,NULL,NULL,'2016-12-17 03:18:11','2016-12-17 03:18:11',NULL,NULL),(2823,'document_name',1140,1,'\'icd_operation\'',NULL,NULL,NULL,'2016-12-17 03:18:28','2016-12-17 03:18:28',NULL,NULL),(2824,'document_name',1141,1,'\'icd_comorbidity\'',NULL,NULL,NULL,'2016-12-17 03:18:49','2016-12-17 03:18:49',NULL,NULL),(2825,'exportp',624,3,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	m_pat = @ehr_model[:patient]\r\n	m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	a_prov = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#provider\").all\r\n	pro_ids = a_prov.collect{|i| i[:module_id]}\r\n	pat_ids = a_prov.collect{|i| i[:patient_id]}\r\n\r\n    all_pat = m_pat.find(pat_ids)\r\n    map_pat = all_pat.group_by{|i| i[:_id]}\r\n    \r\n    all_pro = get_model[:provider].find(pro_ids)\r\n    map_pro = all_pro.group_by{|i| i[:_id]}\r\n\r\n    all_hos = get_model[:hospital].all\r\n\r\n    g_prov = a_prov.group_by{|i| i[:module_id]}\r\n    g_hosp = all_hos.group_by{|i| i.id}\r\n    g_hstr = all_hos.group_by{|i| i.id.to_s}\r\n%>\r\npro_id,hn,prov_name,pat_id,pat_name,prov_hos,pat_hos,date<br/>\r\n<%\r\n    g_prov.each do |k,v|	\r\n        prov     = map_pro[k][0]\r\n        pro_name = map_pro[k][0][:name]\r\n        pro_id   = k\r\n        \r\n        pro_hosp = prov[:main_hospital]\r\n        hos_name = \'N/A\'\r\n        if pro_hosp\r\n            hos_name = g_hosp[pro_hosp][0][:hospital_name_thai]\r\n        end\r\n        \r\n        v.each do |i|\r\n            pat      = map_pat[i[:patient_id]][0]\r\n            pat_id   = pat[:_id]\r\n            pat_hn   = pat[:hn]\r\n            key      = pat[:hospital_name]\r\n            hos      = g_hstr[key]\r\n            pat_hos  = \'N/A\'\r\n            pat_hos = pat[:hospital_name]\r\n            if hos\r\n                pat_hos = hos[0][:hospital_name_thai]\r\n                # pat_hos = \'xxx\'\r\n            else\r\n                # pat[:hospital_name] = hos\r\n                # pat.update_attributes :hospital_name=>pro_hosp.to_s\r\n                # pat.save\r\n                \r\n                pat_hos = hos_name\r\n            end\r\n            gd = pat[:gender]\r\n            if pat[:prefix_name] != \'\' and pat[:gender].nil?\r\n                if pat[:prefix_name] == \'นาย\'\r\n                    gd = \'1\'\r\n                else\r\n                    gd = \'2\'\r\n                end\r\n            end\r\n                \r\n            \r\n            bd = pat[:birth_date].nil? ? \'N/A\' : pat[:birth_date].strftime(\'%d#%m#%Y\')\r\n            \r\n            # pat[:hn] = pat[:hn].upcase\r\n            # pat.save\r\n            pat_name = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]} \\\\#{pat[:last_name]}\"\r\n%>\r\n<%= pro_id%>,<%= pat_hn %>,<%= pro_name %>,<%= pat_id %>,<%= pat_name %>,<%= gd %>,<%= bd %>,<%= pat[:bmi] %>,<%= hos_name %>,<%= pat_hos %>,<%= pat[:created_at].strftime(\'%Y#%m#%d\') %><br/>\r\n<%      end %>\r\n<%\r\n    end\r\n%>\r\n<hr/>\r\npro_id,pro_name,pro_hosp,pat_count<br/>\r\n<%\r\n    g_prov.each do |k,v|\r\n        prov     = map_pro[k][0]\r\n        pro_name = map_pro[k][0][:name]\r\n        pro_id   = k\r\n        pro_hosp = prov[:main_hospital]\r\n        hos_name = \'N/A\'\r\n        if pro_hosp\r\n            hos_name = g_hosp[pro_hosp][0][:hospital_name_thai]\r\n        end\r\n%>\r\n<%= pro_id %>,<%= pro_name %>,<%= hos_name %>,<%= v.count %><br/>\r\n<%\r\n    end\r\n%>\r\n<hr/>\r\n<%= all_pat[0].to_json.html_safe %>',NULL,NULL,NULL,'2016-12-17 10:22:40','2016-12-17 10:22:40','exportp',''),(2827,'form',1066,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n\r\n<script>\r\n    \r\n    \r\n    \r\n  \r\n    \r\n     function icd_com(id){\r\n    \r\n        \r\n        // sid = id.split(\"-\")\r\n        \r\n        // item_id = \"update_\"+sid[0]+\"_\"+sid[1]+\"_\"+sid[2]+\"_thalassemia\"\r\n        // $(\"#\"+item_id).parent().parent().hide()\r\n    \r\n    \r\n        $(\'#data-\'+id+\'comorbidity\').keyup(function(){\r\n            obj = $(this)\r\n            id = obj.attr(\"id\")\r\n            val = obj.val()\r\n            \r\n            sid = id.split(\"-\")\r\n            \r\n\r\n            if(val==\'O990\'){\r\n                item_id = \"\"+sid[1]+\"-\"+sid[2]+\"-\"+sid[3]+\"-thalassemia\"\r\n                $(\'#\'+item_id).show();\r\n\r\n            }else{\r\n                  item_id = \"\"+sid[1]+\"-\"+sid[2]+\"-\"+sid[3]+\"-thalassemia\"\r\n                $(\'#\'+item_id).hide();\r\n\r\n\r\n            }\r\n            \r\n        })\r\n        \r\n        \r\n    }\r\n    \r\n    \r\n      function icd_complication(id){\r\n    \r\n        \r\n        // sid = id.split(\"-\")\r\n        \r\n        // item_id = \"update_\"+sid[0]+\"_\"+sid[1]+\"_\"+sid[2]+\"_thalassemia\"\r\n        // $(\"#\"+item_id).parent().parent().hide()\r\n    \r\n    \r\n        $(\'#data-\'+id+\'complication\').keyup(function(){\r\n            obj = $(this)\r\n            id = obj.attr(\"id\")\r\n            val = obj.val()\r\n            \r\n            sid = id.split(\"-\")\r\n            \r\n\r\n            if(val==\'O721\'||val==\'O722\'){\r\n                item_id = \"\"+sid[1]+\"-\"+sid[2]+\"-\"+sid[3]+\"-estimated_blood_loss\"\r\n                $(\'#\'+item_id).show();\r\n\r\n            }else{\r\n                  item_id = \"\"+sid[1]+\"-\"+sid[2]+\"-\"+sid[3]+\"-estimated_blood_loss\"\r\n                $(\'#\'+item_id).hide();\r\n\r\n\r\n            }\r\n            \r\n        })\r\n        \r\n        \r\n    }\r\n    \r\n    \r\n    \r\n    \r\n    $(document).ready(function(){\r\n        \r\n            function stay_calculation(){\r\n               \r\n               \r\n               var  adm = $(\"#data-admission_date\").val().split(\"/\")\r\n               adm_d = Date.parse(adm[2]+\"-\"+adm[1]+\"-\"+adm[0])\r\n        	   \r\n        	   var  adm = $(\"#data-discharge_date\").val().split(\"/\")\r\n               dis_d = Date.parse(adm[2]+\"-\"+adm[1]+\"-\"+adm[0])\r\n        	   \r\n        	   days = parseInt(1.0*(dis_d - adm_d)/86400000)\r\n        	    $(\'#data-hospital_stay\').val(days)\r\n        	    \r\n            }\r\n            \r\n            \r\n            function check_child(){\r\n               obj =$(\'#data-number_of_fetuses\')\r\n               v = parseInt(obj.val())\r\n               f = $(\'#fetuses_detail\').children(\':last\').children(\':first\')\r\n                s=f.children().size()\r\n                if(v>s){\r\n                    for(i=0;i<v-s;i++){\r\n                        $(\'#obstetrics-fetuses_detail-add-action\').click();\r\n                    }\r\n                }\r\n                if(s>v){\r\n                    for(i=0;i<s-v;i++){\r\n                        $(\'#fetuses_detail\').children(\':last\').children(\':first\').children(\':last\').remove();\r\n                    }\r\n                          \r\n                }\r\n            }\r\n            \r\n            \r\n    \r\n            $(\'#data-number_of_fetuses\').change(check_child);\r\n        \r\n        	$(\"#admission_date\").change(stay_calculation);\r\n            $(\"#discharge_date\").change(stay_calculation);\r\n\r\n           \r\n           $(\'.btn\').addClass(\'btn-info\')\r\n    });\r\n    \r\n\r\n    \r\n    \r\n    \r\n</script>\r\n\r\n<%=render :inline=>this.script %>',NULL,NULL,NULL,'2016-12-19 04:12:38','2016-12-19 04:12:38','form',''),(2828,'document_name',1142,1,'\'provider_module\'',NULL,NULL,NULL,'2016-12-19 04:12:57','2016-12-19 04:12:57',NULL,NULL),(2829,'summary_report',1064,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n							<h3 class=\"heading\">รางงานสถิติ</h3>\r\n							<div class=\"tabbable\">\r\n								<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#tab1\" data-toggle=\"tab\">Gynaecology</a></li>\r\n									<li class=\"\"><a href=\"#tab2\" data-toggle=\"tab\">Obstetrics </a></li>\r\n									\r\n								</ul>\r\n								<div class=\"tab-content\">\r\n									<div class=\"tab-pane active\" id=\"tab1\">\r\n										<p><strong><u>รายงานสถิติ</u></strong> (สถิติรวมทั้งหมดและที่แยกคนไข้ปกติและคนไข้คลินิกนอกเวลาออกจากกัน  โดยคนไข้คลินิกนอกเวลาสามารถระบุตัวได้จาก ward ที่ admit  คือที่ นม 8 และอาคาร 14 ชั้นเท่านั้น)<br />\r\n      1. จำนวนการ Admission…..ครั้งและจำนวนผู้ป่วย……ราย (เนื่องจากผู้ป่วยหนึ่งคนอาจมา  admit มากกว่าหนึ่งครั้ง </p>\r\n      <ul>\r\n        <ul>\r\n          <li><a href=\"#\">ผู้ป่วยทั้งหมด (เดือน)</a></li>\r\n          <li><a href=\"#\">ผู้ป่วยแยกว่าเป็นผู้ป่วยทั่วไปหรือผู้ป่วยพิเศษ </a></li>\r\n          <li><a href=\"#\">ผู้ป่วยแยกแต่ละสาย (5สาย) </a></li>\r\n        </ul>\r\n      </ul>\r\n      <p>2. แยกสถิติของโรคตาม Principal  diagnosis <u>+</u> comorbidity</p>\r\n      <ul>\r\n        <li><a href=\"#\">Benign gynecologic diseases</a> (หาจาก code ทั้งหมดที่ไม่ใช่มะเร็ง)<br />\r\n        <a href=\"#\">Malignant  gynecologic diseases</a></li>\r\n        <li>ในกลุ่ม Benign gynecologic disease แยกรายละเอียดว่าเป็นโรคอะไรบ้าง  (รวมทั้งที่อยู่ใน Principle  diagnosis and comorbidity)</li>\r\n        <ul>\r\n          <li><a href=\"#\">Inflammatory  diseases: N70…, N71…</a></li>\r\n          <li><a href=\"#\">Endometriosis:  N80..</a></li>\r\n          <li><a href=\"#\">Benign  ovarian tumor: D27</a></li>\r\n          <li><a href=\"#\">Leiomyoma:  D25…</a></li>\r\n          <li><a href=\"#\">Endometrial  hyperplasia: N85..</a></li>\r\n          <li><a href=\"#\">Endometrial  polyp: N840</a></li>\r\n          <li><a href=\"#\">Cervical  intraepithelial neoplasia: N87.., D06…</a></li>\r\n          <li><a href=\"#\">Vaginal  intraepithelial neoplasia: N89…, D072</a></li>\r\n          <li><a href=\"#\">Vulvar  intraepithelial neoplasia: N90.., D071</a></li>\r\n          <li><a href=\"#\">Pelvic  organ  prolapse urinary incontinence:  N81…, N993, N884, </a></li>\r\n          <li><a href=\"#\">Urinary  incontinenceN393, N394, N328</a></li>\r\n          <li><a href=\"#\">Other   รวม code ที่เหลือทั้งหมด</a></li>\r\n        </ul>\r\n        <li>ในกลุ่ม Malignant gynecologic disease<br />\r\n          แยกว่าเป็นมะเร็งอะไรบ้างเอาเป็นจำนวนคนไม่เอาจำนวนครั้ง admission  เนื่องจากบางคนมา admit  มากกว่าหนึ่งครั้งเช่นให้ยาเคมีบำบัดหรือเกิดภาวะแทรกซ้อน<br />\r\n        </li>\r\n        <ul>\r\n          <li>แยกตามชนิดของมะเร็ง </li>\r\n          <ul>\r\n            <li><a href=\"#\">แยกเป็น primary หรือ recurrent case </a></li>\r\n            <li><a href=\"#\">แยกตาม stage ที่ได้ลงไว้เพิ่มเติม </a></li>\r\n          </ul>\r\n        </ul>\r\n      </ul>\r\n      <p>3. แยกสถิติตาม Complications </p>\r\n      <ul>\r\n        <li><a href=\"#\">intraoperative  complicationsตาม code ในเอกสาร </a></li>\r\n        <li>p<a href=\"#\">ostoperative  complicationsตาม code</a> ในเอกสารและอื่นๆที่อาจมีนอกเหนือในเอกสาร</li>\r\n        <li><a href=\"#\">แยกสถิติ เฉพาะ 3 ภาวะ</a> injury to internal organs (T812), Hemorrhage (T810) และ wound  complications (T813,T814)</li>\r\n      </ul>\r\n      <p>4. Operations</p>\r\n      <ul>\r\n        <li><a href=\"#\">แยกว่าเป็น Abdominal  surgery, laparoscopic surgery</a>(ตามเอกสาร ที่ตัดรหัสของ hysteroscopic  surgery ออกไป), hysteroscopic surgery(6812, 6816, 6823), vaginal surgery(704,7033,7062,  7064,708,7092,595,5979,6922,7077,6859, 7050), Other คือที่เหลือทั้งหมด </li>\r\n      </ul>\r\n      <p>ในกรณีที่รายหนึ่งมีการหัตถการมากกว่าหนึ่งอย่างให้ยึดว่าทำทางไหนจาก  code ที่ใส่อันแรก </p>\r\n      <ul>\r\n        <li>Focus บางหัตถการได้แก่ (ยึด code หัตถการที่ลงอันดับแรก)</li>\r\n        <ul>\r\n          <li><a href=\"#\">Abdominal  hysterectomy 6839, 6849</a></li>\r\n          <li><a href=\"#\">Laparoscopic  hysterectomy 6831,6841, 6851</a></li>\r\n          <li><a href=\"#\">Vaginal  hysterectomy 6859</a></li>\r\n          <li><a href=\"#\">Abdominal  radical hysterectomy 6869</a></li>\r\n          <li><a href=\"#\">Laparoscopic  radical hysterectomy 6861</a></li>\r\n          <li><a href=\"#\">Abdominal  salpingo-oophorectomy/oophorectomy</a> 6549,6562,6539,6552</li>\r\n          <li><a href=\"#\">Laparoscopic  salpingo-oophorectomy/oophorectomy</a> 6541,6564, 6531,6554</li>\r\n          <li><a href=\"#\">Myomectomy  6829</a> แยกว่าเป็น abdominal หรือ laparoscopic หรือ hysteroscopic ตามข้อมูลที่เติมขึ้นมาใหม่เอง </li>\r\n          <li><a href=\"#\">Staging  procedures</a> (รหัสอย่างใดอย่างหนึ่งต่อไปนี้ 4052,4053,4011,5423,  544)</li>\r\n          <li><a href=\"#\">Laparoscopic  enucleation of ovarian cyst 6525 </a></li>\r\n          <li><a href=\"#\">Abdominal  enucleation of ovarian cyst 6529</a></li>\r\n          <li><a href=\"#\">Hysteroscopic  procedure 6812,6821,6822, 6816 </a></li>\r\n        </ul>\r\n    </ul>\r\n    \r\n    </p>\r\n								  </div>\r\n												<div class=\"tab-pane\" id=\"tab2\">\r\n													<p><strong><u>รายงานสถิติ</u></strong> (สถิติรวมทั้งหมดและที่แยกคนไข้ปกติและคนไข้คลินิกนอกเวลาออกจากกัน  โดยคนไข้คลินิกนอกเวลาสามารถระบุตัวได้จาก ward ที่ admit  คือที่ นม 8 และอาคาร 14 ชั้นเท่านั้น)<br>\r\n1. จำนวนการ Admission…..ครั้งและจำนวนผู้ป่วย……ราย (เนื่องจากผู้ป่วยหนึ่งคนอาจมา  admit มากกว่าหนึ่งครั้ง </p>\r\n													<ul>\r\n                                                      <ul>\r\n                                                        <li><a href=\"#\">ผู้ป่วยทั้งหมด </a></li>\r\n                                                        <li><a href=\"#\">ผู้ป่วยแยกว่าเป็นผู้ป่วยทั่วไปหรือผู้ป่วยพิเศษ </a></li>\r\n                                                        <li>ผู้ป่วยแยกแต่ละสาย (5สาย) </li>\r\n                                                      </ul>\r\n                                                    </ul>\r\n                                                    <p>2. <a href=\"#\">จำนวนการคลอด</a> (ต้องมีรหัสอย่างใดอย่างหนึ่งในรหัสของ mode of delivery ตามเอกสาร) โดยแยกเป็นรายเดือนและรายปี  โดยแบ่งต่อว่าแยกเป็นผู้ป่วยทั่วไปผู้ป่วยแยกว่าเป็นผู้ป่วยทั่วไปหรือผู้ป่วยพิเศษ  ผู้ป่วยแยกแต่ละสาย (5สาย) <br>\r\n                                                      จำนวนการตั้งครรภ์ผิดปกติ ประกอบด้วยการแท้งAbortion  (O020,O021,O03-, O04-, O05-) การตั้งครรภ์นอกมดลูก Ectopic  pregnancy(<strong>0</strong>001, O00-)และการตั้งครรภ์ไข่ปลาอุกHydatidiform  mole (O010,O011) <br>\r\n                                                  3. จำนวนการคลอดตามชนิดของการคลอด  และแบ่งเป็นผู้ป่วยทั่วไปหรือผู้ป่วยพิเศษ </p>\r\n                                                    <ul>\r\n                                                      <li><a href=\"#\">Spontaneous  vertex delivery&nbsp;</a></li>\r\n                                                      <li><a href=\"#\">Spontaneous breech delivery&nbsp;</a></li>\r\n                                                      <li><a href=\"#\">Breech assisting</a> &nbsp;</li>\r\n                                                      <li><a href=\"#\">Forceps extraction &nbsp;</a> &nbsp; &nbsp; </li>\r\n                                                      <li><a href=\"#\">Vacuum extraction &nbsp;</a> &nbsp; &nbsp;</li>\r\n                                                      <li><a href=\"#\">Elective cesarean section &nbsp;</a> &nbsp; &nbsp;</li>\r\n                                                      <li><a href=\"#\">Emergency  cesarean section </a>&nbsp; &nbsp; </li>\r\n                                                    </ul>\r\n                                                    <p>4. Indication ของการผ่าตัดคลอดแยกเป็น elective  และ emergency  cesarean section โดยดูจาก principal diagnosis ในรายที่มีรหัสการทำ  cesarean section 740,741  นอกจากนี้ให้แบ่งเป็นผู้ป่วยทั่วไปและผู้ป่วยพิเศษ</p>\r\n                                                    <ul>\r\n                                                      <li><a href=\"#\">CPD</a> (ตามเอกสารทั้งในหัวข้อ fetal complications และ  intrapartum) </li>\r\n                                                      <li><a href=\"#\">Abnormal presentation(</a>ตามเอกสารทั้งในหัวข้อ  fetal complications และ intrapartum)</li>\r\n                                                      <li><a href=\"#\">Previous C/S or myomectomy </a>(O342,O655)</li>\r\n                                                      <li><a href=\"#\">Placenta previa </a>(O440,O441)</li>\r\n                                                      <li><a href=\"#\">Fetal distress/Non-reassuring FHR</a> (O682,O688)</li>\r\n                                                      <li><a href=\"#\">Others</a></li>\r\n                                                    </ul>\r\n                                                    <p>5.<a href=\"#\">จำนวนผู้ป่วยคลอดก่อนกำหนด (O601, O603) </a>และคลอดครบกำหนด (ดูจากมีหัตถการการคลอดแต่ไม่มี  principle diagnosis เป็น O601หรือ O603<br>\r\n                                                  6. จำนวนผู้ป่วยในแต่ละโรคที่สนใจได้แก่</p>\r\n                                                    <ul>\r\n                                                      <li><a href=\"#\">Teenage  pregnancy (Z356)</a></li>\r\n                                                      <li><a href=\"#\">Multiple pregnancy(O300, O301, O325, O430)</a></li>\r\n                                                      <li><a href=\"#\">Fetal anomalies (O350, O358)</a></li>\r\n                                                      <li><a href=\"#\">Preterm labor (O600-3)</a></li>\r\n                                                      <li><a href=\"#\">Preelampsia (O140-O142,O11)</a></li>\r\n                                                      <li><a href=\"#\">Eclampsia (O150-O152)</a></li>\r\n                                                      <li><a href=\"#\">Placenta previa (O440,O441)</a></li>\r\n                                                      <li>Postpartum hemorrhage-    Immediate O721  แยกเป็น 3 สาเหตุ \r\n                                                        <ul>\r\n                                                          <li><a href=\"#\">Uterine  atony (O622)</a><br>\r\n                                                            <a href=\"#\">Tear  genital tract (O713,O714)</a><br>\r\n                                                            <a href=\"#\">Retained  placenta (O720) </a>      <br>\r\n                                                            <a href=\"#\">Ruptured  uterus (O711)</a><br>\r\n                                                            <a href=\"#\">Other</a></li>\r\n                                                        </ul>\r\n                                                      </li>\r\n                                                      <ul>\r\n                                                        <ul>\r\n                                                          <ul>\r\n                                                            <li><a href=\"#\">Delayed O722</a></li>\r\n                                                          </ul>\r\n                                                        </ul>\r\n                                                      </ul>\r\n                                                      <li><a href=\"#\">Stillbirth</a> (ดูได้จาก outcome of delivery  ว่ามีรหัส Z371, Z373, Z374, Z376, Z377)</li>\r\n                                                      <li><a href=\"#\">Maternal  death </a>(ดูจาก discharge status ว่า death)</li>\r\n                                                    </ul>\r\n                                                    <p>7.จำนวนหัตถการที่สนใจได้แก่</p>\r\n                                                    <ul>\r\n                                                      <li><a href=\"#\">Tamponade  of uterus</a> (758) แยกเป็น B-lynch หรือ Balloon tamponade</li>\r\n                                                      <li><a href=\"#\">Cesarean hysterectomy</a> (740/1 + 6849,6839)</li>\r\n                                                      <li><a href=\"#\">Re-operation  after delivery</a> (7591,7592,7569, 5412, 7552) </li>\r\n                                                    </ul>\r\n                                    </div>\r\n									\r\n								</div>\r\n							</div>\r\n						</div>\r\n\r\n\r\n\r\n</div>',NULL,NULL,NULL,'2016-12-19 04:27:44','2016-12-19 04:27:44','summary_report',''),(2830,'main_partial',1061,3,'<%= render :inline=>this.params_config %>\r\n<%= render :inline=>this.common_query %>\r\n<%\r\n    date = @date\r\n    \r\n    main_service = \'main\'\r\n    \r\n    all_ser = {}\r\n    @rs_serv.keys.each do |i|\r\n        k = i.to_sym\r\n        all_ser[k] = {}\r\n        get_model[k].find(@mid_ser[i]).each do |j|\r\n            all_ser[k][j.id.to_s] = j\r\n        end\r\n    end\r\n    \r\n    def val rec, field\r\n        f = field.to_sym\r\n        return (rec[f].nil? or rec[f]==\'\') ? \'-\' : rec[f]\r\n    end\r\n    \r\n    today = Time.now\r\n    \r\n    s_list = @status_list\r\n    \r\n    res = []\r\n    @rs_app.each do |i|\r\n        m = @rs_pat_mod[i.id.to_s]\r\n        pat = @rs_pat[m[:patient_id].to_s]\r\n        pat_id = pat.id.to_s\r\n        \r\n            age = \'-\'\r\n            if pat[:birth_date]\r\n                diff = Time.diff(today, pat[:birth_date])\r\n                year = diff[:year]\r\n                month = diff[:month]\r\n                day = diff[:day]\r\n                age = \"\\\\#{year}y.\\\\#{month}m.\"\r\n            end\r\n            \r\n        prov = \'N/A\'\r\n        if i[:provider]\r\n            tmp = @rs_prov[i[:provider].to_s][:name]\r\n            prov = tmp\r\n        end\r\n        \r\n        ward = \'N/A\'\r\n        if i[:visit_base] == \'OPD\'\r\n            ward = i[:visit_base]\r\n        elsif i[:visit_base] == \'IPD\'\r\n            ward = i[:ward]\r\n        end\r\n        \r\n        room = @rs_room[i[:room].to_s]\r\n        ward = @rs_ward[i[:ward].to_s]\r\n        \r\n        \r\n        r = {}\r\n        r[:id]   = i.id.to_s\r\n        r[:room] = room\r\n        r[:start] = (i[:start].nil? or i[:start] == \'\') ? \'-\' : i[:start].strftime(\'%H:%M\')\r\n        r[:stop]  = (i[:stop].nil? or i[:stop] == \'\') ? \'-\' : i[:stop].strftime(\'%H:%M\')\r\n        r[:time]  = r[:start]\r\n        r[:surgeon] = prov\r\n        r[:anesth] = val(i, :anesth_technique)\r\n        r[:dx] = i[:diagnosis_1]\r\n        r[:op] = i[:tentative_operation]\r\n        r[:ward] = ward\r\n        r[:hn]  = pat[:hn]\r\n        r[:age] = age\r\n        r[:ward] = ward\r\n        r[:pat_id]   = pat_id\r\n        r[:pat_name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]} \\\\#{pat[:last_name]}\"\r\n        r[:status] = i[:status]\r\n        r[:link] = {}\r\n        \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-mini btn-info \', :style=>\'width:45px\')\r\n                l_list = []\r\n                @service_map.each do |k, v|\r\n                    lab = k.to_s.split(\'_\')[0].humanize\r\n                    v_link = link_to(\"+ \\\\#{lab}\".html_safe, \r\n                        \"../\\\\#{v}/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{pat[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/\\\\#{main_service}?date=\\\\#{@p_date}\", \r\n                        :class=>\'btn btn-mini \', :style=>\'width:45px\' )\r\n                    if x = @rs_serv[k][pat_id]\r\n                        v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            \"../\\\\#{v}/show?id=\\\\#{x}&return=../Home/\\\\#{main_service}?date=\\\\#{@p_date}\", :class=>\'btn btn-mini btn-success\', :style=>\'width:45px\')\r\n                    end\r\n                    r[:link][k] = v_link\r\n                    l_list << v_link\r\n                end\r\n        \r\n        \r\n        r[:d_link] = d_link\r\n        r[:l_link] = l_list\r\n        \r\n        \r\n        r[:s_link] = link_to(\" show\".html_safe, \"../Appointment/show?id=\\\\#{m.id.to_s}&return=../Home/main\", :class=>\'btn btn-mini btn-info\', :style=>\'width:45px\')\r\n        r[:a_link] = r[:link][:case_preparing].html_safe + \"&nbsp;&nbsp;\".html_safe + r[:s_link].html_safe\r\n        # r[:pat] = pat\r\n        res << r\r\n    end\r\n    \r\n    res = res.compact\r\n    \r\n    # group by status\r\n    sg = res.group_by{|i| i[:status]}\r\n%>\r\n<!-- Status : Processing -->\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span-12\'>\r\n        <div class=\'w-box\'>\r\n            <div class=\'w-box-header\'  style=\'font-size:1.5em\'>\r\n                Appointed Patient\r\n            </div>\r\n            <div class=\'w-box-content cnt_a \' style=\'background:#FCF8F0\'>\r\n<%\r\n    s_idx = 0\r\n    s_list = []\r\n    r = {}\r\n%>\r\n                <div class=\'row-fluid\'>\r\n                                        <table id=\'appointed-patient\' class=\"table table-striped table-bordered dTableR\">\r\n    										<thead>\r\n    											<tr>\r\n    												<th>Room</th>\r\n    												<th>Ward</th>\r\n    												<th>HN</th>\r\n    												<th>Name</th>\r\n    												<th>Age</th>\r\n    												<th>Anesth</th>\r\n    												<th>Diagnosis</th>\r\n    												<th>Operation</th>\r\n    												<th>Status</th>\r\n    												<th>Action</th>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n    res.sort_by{|i| i[:room]}.each do |i|\r\n        r = i\r\n%>\r\n    											<tr>\r\n    											    <td><%= r[:room] %> </td>\r\n    												<td><%= r[:ward] %></td>\r\n    											