y:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n    # locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name if user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2016-12-19 07:43:48','2016-12-19 07:43:48','patient_record',''),(2832,'config',1061,1,'[\r\n    {:name=>\'Preparing Records\',:open=>true,:actions=>[\r\n        {:name=>\'Pre-Op Visit\',:service=>\'pre_operative_visit\',:link=>\'../PreOperativeVisit/index\',:remote=>false}\r\n        ]\r\n    },\r\n    {:name=>\'Operating Records\',:open=>true,:actions=>[\r\n        {:name=>\'Pre Operative\',:service=>\'pre_operative\',:dashboard=>true,:link=>\'../PreOperative/index\',:remote=>false},\r\n        {:name=>\'Intra Operative\',:service=>\'intra_operative\',:dashboard=>true,:link=>\'../IntraOperative/index\',:remote=>false},\r\n        {:name=>\'Post Operative\',:service=>\'post_operative\',:dashboard=>true,:link=>\'../PostOperative/index\',:remote=>false}\r\n        ]\r\n    },\r\n    {:name=>\'ETC\',:open=>true,:actions=>[\r\n        {:name=>\'Billing\',:service=>\'billing\',:link=>\'../Billing/index\',:remote=>false}\r\n        ]\r\n    }\r\n]\r\n',NULL,NULL,NULL,'2016-12-19 07:45:22','2016-12-19 07:45:22','config',''),(2833,'document_name',1143,1,'\'attendance\'',NULL,NULL,NULL,'2016-12-19 14:22:54','2016-12-19 14:22:54',NULL,NULL),(2834,'batch_import',262,2,'<%\r\n    res = []\r\n    # pat_fields = [\'hn\', \'public_id\', \'prefix_name\', \'first_name\', \'last_name\', \'gender\', \'birth_date\', \'note\']\r\n    # app_fields = [\'date\', \'start\', \'end\']\r\n    \r\n    m_prov = get_model[:provider]\r\n    \r\n    # batch field\r\n    bf = %w{prefix first_name last_name ref_number license_number}\r\n    if request.post?\r\n        if b = params[:batch]\r\n            f = b[:file]\r\n            \r\n            require \'csv\'\r\n            \r\n            csv = CSV.parse(f.read, :headers => true, :encoding=> \"iso-8859-1:utf-8\")\r\n            \r\n            csv.each do |i|\r\n                tmp = {}\r\n                \r\n                bf.each do |j|\r\n                    j = j.to_s\r\n                    tmp[j.to_sym] = i[j]\r\n                end\r\n                tmp[:name] = \"\\\\#{tmp[:prefix]}\\\\#{tmp[:first_name]} \\\\#{tmp[:last_name]}\"\r\n                m_prov.create tmp\r\n            end # end csv\r\n            res << \'xxx \'\r\n        end # end batch\r\n    end # end post\r\n%>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting > Batch Provider</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n\r\n\r\n<%= form_for :batch, :url=>params[:opt], :html=>{:multipart=>true}  do |f| %>\r\n                <%= f.file_field :file, :accept => \"text/csv\" %> \r\n                <div class=\'row-fluid\'></div>\r\n                <%=f.submit \'Submit\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %> \r\n<% end %>\r\n\r\n<div class=\'alert alert-info\'>\r\n<% if res.empty? %>\r\n<b>Header</b> : <%= bf.join(\',\') %><br/>\r\nprovider_type (1:Doctor)\r\n<% else %>\r\n    <!--<%= res.join(\'<br/>\').html_safe %>-->\r\n    <%# res.to_json.html_safe %> \r\n    Import success <%= res.size %> records\r\n<% end %>\r\n        \r\n</div>\r\n\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>',NULL,NULL,NULL,'2016-12-19 14:47:25','2016-12-19 14:47:25','batch_import',''),(2835,'document_name',1144,1,'\'attendance_provider\'',NULL,NULL,NULL,'2016-12-21 15:07:33','2016-12-21 15:07:33',NULL,NULL),(2836,'document_name',1145,1,'\'case_preparing\'',NULL,NULL,NULL,'2016-12-22 00:19:10','2016-12-22 00:19:10',NULL,NULL),(2837,'document_name',1146,1,'\'preparing_item\'',NULL,NULL,NULL,'2016-12-22 00:20:07','2016-12-22 00:20:07',NULL,NULL),(2838,'nurse_index',1061,2,'<%\r\n    m_att = get_model[:attendance]\r\n    m_att_prov = get_model[:attendance_provider]\r\n    \r\n    if params[:date]\r\n        session[:att_date] = params[:date]\r\n    else\r\n        if session[:att_date].nil?\r\n            session[:att_date] = Time.now.strftime(\'%d/%m/%Y\')\r\n        end\r\n    end\r\n    \r\n    prov = get_model[:provider].all.group_by{|i| i[:_id].to_s}\r\n    \r\n    room = get_model[:room].all.sort_by{|i| i[:name]}\r\n    \r\n    td = session[:att_date]\r\n    dd = Date.strptime(td, \'%d/%m/%Y\')\r\n    \r\n    rs = m_att.where(:date.gte=>dd.at_beginning_of_day,:date.lt=>dd.end_of_day).all\r\n    \r\n    # attendance provider list\r\n    ap_list = []\r\n    # attendance provider field\r\n    ap_field = []\r\n    \r\n    g_vis = rs.group_by{|i| i[:visit_type]}\r\n    \r\n    su = []\r\n    n1 = []\r\n    n2 = []\r\n    n3 = []\r\n    \r\n    rs.each do |i|\r\n        ap_list += i[:surgeon]\r\n        ap_list += i[:nurse_1]\r\n        ap_list += i[:nurse_2]\r\n        ap_list += i[:nurse_3]\r\n        \r\n        su += m_att_prov.find(i[:surgeon])\r\n        n1 += m_att_prov.find(i[:nurse_1])\r\n        n2 += m_att_prov.find(i[:nurse_2])\r\n        n3 += m_att_prov.find(i[:nurse_3])\r\n    end\r\n    \r\n    # all attendance provider\r\n    a_ap = m_att_prov.find(ap_list)\r\n    \r\n    g_su = su.group_by{|i| i[:room].to_s}\r\n    g_n1 = n1.group_by{|i| i[:room].to_s}\r\n    g_n2 = n2.group_by{|i| i[:room].to_s}\r\n    g_n3 = n3.group_by{|i| i[:room].to_s}\r\n    \r\n    g_ap = a_ap.group_by{|i| i[:room].to_s}\r\n%>\r\n\r\n\r\n    <center>\r\n\r\n    <h2 class=\"well\"><img src=\"<%=@current_project.get_setting \'logo_report_path\' %>\" width=\"200\"><br />OR MANAGMENT CENTER</h2>\r\n    \r\n    </center>\r\n\r\n<%\r\n    \r\n%>\r\n<table class=\"table table-striped table-bordered table-condensed\">\r\n    										<thead>\r\n    											<tr>\r\n    												<th>Room</th>\r\n    												<th>Surgeon</th>\r\n    												<th>RN FT</th>\r\n    												<th>RN PT</th>\r\n    												<th>NA</th>\r\n    												<th>ช่าง/ธุรการ</th>\r\n    												<th>รับเวร</th>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n    room.each do |i|\r\n        rn = i[:name]\r\n        rid = i[:_id].to_s\r\n        ap = g_ap[rid].to_json.html_safe\r\n        rsu = !g_su[rid].nil? ? g_su[rid] : []\r\n        rn1 = !g_n1[rid].nil? ? g_n1[rid] : []\r\n        rn2 = !g_n2[rid].nil? ? g_n2[rid] : []\r\n        rn3 = !g_n3[rid].nil? ? g_n3[rid] : []\r\n        \r\n        su_name = \"\"\r\n        n1_name = \"\"\r\n        n2_name = \"\"\r\n        n3_name = \"\"\r\n        \r\n        rsu.each do |i|\r\n                pn = prov[i[:name].to_s][0][:name]\r\n                su_name += link_to(pn, \"#\", :class=>\'btn\')\r\n        end\r\n        rn1.each do |i|\r\n                pn = prov[i[:name].to_s][0][:name]\r\n                n1_name += link_to(pn, \"#\", :class=>\'btn\')\r\n        end\r\n        rn2.each do |i|\r\n                pn = prov[i[:name].to_s][0][:name]\r\n                n2_name += link_to(pn, \"#\", :class=>\'btn\')\r\n        end\r\n        rn3.each do |i|\r\n                pn = prov[i[:name].to_s][0][:name]\r\n                n3_name += link_to(pn, \"#\", :class=>\'btn\')\r\n        end\r\n%>\r\n    				                            <tr>\r\n    				                                <td>\r\n    				                                    <%= rn %>\r\n    				                                </td>\r\n    				                                <td>\r\n    				                                    <%= su_name.html_safe %>\r\n    				                                    <%= link_to \'+\', \"#\", :class=>\'btn\' %>\r\n    				                                </td>\r\n    				                                <td>\r\n    				                                    <%= n1_name.html_safe %>\r\n    				                                    <%= link_to \'+\', \"#\", :class=>\'btn\' %>\r\n    				                                </td>\r\n    				                                <td>\r\n    				                                    <%= n2_name.html_safe %>\r\n    				                                    <%= link_to \'+\', \"#\", :class=>\'btn\' %>\r\n    				                                </td>\r\n    				                                <td>\r\n    				                                    <%= n3_name.html_safe %>\r\n    				                                    <%= link_to \'+\', \"#\", :class=>\'btn\' %>\r\n    				                                </td>\r\n    				                                <td>\r\n    				                                    <%= link_to \'+\', \"#\", :class=>\'btn\' %>\r\n    				                                </td>\r\n    				                                <td>\r\n    				                                    <%= link_to \'+\', \"#\", :class=>\'btn\' %>\r\n    				                                </td>\r\n    				                            </tr>\r\n<%\r\n    end\r\n%>\r\n                                            </tbody>\r\n                                        </table>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n    })\r\n    \r\n</script>',NULL,NULL,NULL,'2016-12-22 01:52:23','2016-12-22 01:52:23','nurse_index',''),(2839,'layout',1147,4,'<!DOCTYPE html>\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n    <meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1\" />\r\n    <meta name=\"description\" content=\"\" />\r\n    <meta name=\"author\" content=\"\" />\r\n      <!--[if IE]>\r\n        <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\">\r\n        <![endif]-->\r\n\r\n     <title>THKJR</title>\r\n     <%= include_header %>\r\n    \r\n    <!-- BOOTSTRAP CORE STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/bootstrap.css\" rel=\"stylesheet\" />\r\n      <!-- VEGAS SLIDESHOW STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/vegas/jquery.vegas.min.css\" rel=\"stylesheet\" />\r\n     <!-- FONTAWESOME STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/font-awesome.min.css\" rel=\"stylesheet\" />\r\n    <!-- CUSTOM STYLE CSS -->\r\n    <link href=\"/esm/thks_web/www/assets/style.css\" rel=\"stylesheet\" />    \r\n    <!-- GOOGLE FONT -->\r\n    \r\n     <!-- HTML5 shim and Respond.js IE8 support of HTML5 elements and media queries -->\r\n    <!--[if lt IE 9]>\r\n      <script src=\"https://oss.maxcdn.com/libs/html5shiv/3.7.0/html5shiv.js\"></script>\r\n      <script src=\"https://oss.maxcdn.com/libs/respond.js/1.3.0/respond.min.js\"></script>\r\n    <![endif]-->\r\n<style>\r\n.bbox{ width:150px; float:left; padding:10px; margin-right:20px}\r\n.ss{padding:0px;;margin-right:5px; width:180px; font-size:1em}\r\n.sm {font-size:0.8em}\r\ninput, button, select, textarea {color:#000;}\r\nlabel {    font-weight: normal;}\r\n.navbar-inverse {\r\n    background-color: rgb(255, 255, 255);}\r\n.navbar-inverse .navbar-nav > li > a {\r\n    color: #8c8c8c;}\r\n    .navbar-inverse .navbar-toggle .icon-bar {\r\n    background-color: #8c8c8c;}\r\n