ULL,'2016-12-27 03:39:23','2016-12-27 03:39:23',NULL,NULL),(2842,'show',1150,2,'\r\n\r\n<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n\r\n\r\n<%= this.display.html_safe %>\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2016-12-27 03:55:17','2016-12-27 03:55:17','show',''),(2843,'display',1150,3,'<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n\r\n<h1>General Test summary </h1>\r\n<hr/>\r\n<%=Time.now %>\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n\r\n <div style=\"padding:5px;width:720px; margin-left:auto; margin-right:auto\" >\r\n\r\nRef : <%= @patient_module.ref_number %> \r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n<p style=\"width:720px; margin-left:auto; margin-right:auto; font-weight:bold\">HN : <%= @patient.hn %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Name : <%= @patient.first_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Surname : <%= @patient.last_name %></p>\r\n<hr /><br />\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>',NULL,NULL,NULL,'2016-12-27 03:56:32','2016-12-27 03:56:32','display',''),(2844,'index_dev',1143,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i>เพิ่มคลีนิกพิเศษ(เคสนอก)\'.html_safe, \r\n\"create?record[special_clinic]=true\",:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'.\' do |f| %>\r\n<div class=\"hide\">\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%\r\n        models = get_model \r\n        date = Time.now \r\n        if params[:date]\r\n           date = Date.parse params[:date] \r\n        end\r\n        attendance = models[:attendance].where(:date=>{\'$gte\'=>date.beginning_of_day(),\'$lte\'=>date.end_of_day()}).first\r\n        \r\n        providers = {}\r\n        for i in models[:provider].all\r\n            providers[i.id] = i.name\r\n        end\r\n        \r\n        if attendance \r\n        \r\n        @show = true        \r\n        @record = attendance\r\n        \r\n        \r\n%>\r\n<div class=\"alert alert-success \">\r\n    <%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n        <div style=\"margin-left:auto;margin-right:auto;padding:1px;width:700px\">\r\n<br/>\r\n    <%= link_to \'Calculate Payroll\', \"payroll?id=\\#{@record.id}\" , :class=>\'btn btn-info\' if @record.payroll_check!=\'true\'%>\r\n    <%= link_to \'Show\', \"payroll?id=\\#{@record.id}\" , :class=>\'btn\' if @record.payroll_check==\'true\'%>\r\n    <br/>\r\n    </div>\r\n</div>\r\n\r\n\r\n<% else %>\r\n     \r\n    <%= form_for :record, :url=>\'../Attendance/create\' do |f|  %> \r\n    <%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n   \r\n    <div style=\"margin-left:auto;margin-right:auto;padding:1px;width:730px;border:0px solid\">\r\n    <%=f.submit \"Save Today Attendance\", :class=>\'btn btn-success\' %>\r\n    </div>\r\n    <% end %>\r\n<% end%>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<%= this.list.html_safe  if @current_role==\'admin\' or @current_role==\'developer\'%>\r\n\r\n<br/>\r\n<p>\r\n<%# link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%# link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2016-12-27 03:56:53','2016-12-27 03:56:53','index_dev',''),(2845,'index',1143,2,'<%\r\n    m_att = get_model[:attendance]\r\n    m_att_prov = get_model[:attendance_provider]\r\n    \r\n    if params[:date]\r\n        session[:att_date] = params[:date]\r\n    else\r\n        if session[:att_date].nil?\r\n            session[:att_date] = Time.now.strftime(\'%d/%m/%Y\')\r\n        end\r\n    end\r\n    \r\n    def get_doc_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].strip\r\n                    tmp[:list] << x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    # @fm = fm\r\n    def get_value f, val\r\n        x = @fm[f.to_sym]\r\n        v = val\r\n        if x.to_h.has_key? :pair and !v.nil? and v != \'\'\r\n            # if f.to_sym == :if_rrt or f.to_sym == :vasopressor\r\n            #     v = x[:pair][v]\r\n            # else\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n                # v = \"<span title=\'\\\\#{v}\'>\\\\#{val} <i class=\'splashy-help\'></i></span>\".html_safe\r\n            # end\r\n        end\r\n            # if f.to_sym == :delivered_lose and !v.nil? and v != \'\'\r\n            #         v = v.to_f.round(4) if Float(v) rescue v\r\n            # end\r\n        # if v.nil? or v == \'\'\r\n        #     v = \'-\'\r\n        # end\r\n        return v\r\n    end\r\n    \r\n    if request.post?\r\n        td = session[:att_date]\r\n        dd = Date.strptime(td, \'%d/%m/%Y\')\r\n        \r\n        pp = params[:record]\r\n        \r\n        rs = m_att.where( :date => { \'$gt\' => dd.at_beginning_of_day, \'$lt\' => dd.end_of_day }, :visit_type=>params[:visit] ).first\r\n        if !rs\r\n            rs = m_att.create :date=>dd, :visit_type=>params[:visit]\r\n        end\r\n        \r\n        # add new record to attendance_provider\r\n        nr = m_att_prov.create pp\r\n        \r\n        # field symbol\r\n        fs = params[:field].to_sym\r\n        \r\n        xx = rs[fs]\r\n        if xx.nil?\r\n            xx = []\r\n        end\r\n        xx << nr.id\r\n        \r\n        # rs.update_attributes fs=>xx\r\n        rs[fs] = xx\r\n        rs.save\r\n    end\r\n    \r\n    prov = get_model[:provider].all.group_by{|i| i[:_id].to_s}\r\n    @prov = prov\r\n    room = get_model[:room].all.sort_by{|i| i[:name]}\r\n    \r\n    td = session[:att_date]\r\n    dd = Date.strptime(td, \'%d/%m/%Y\')\r\n    \r\n    # rs = m_att.where(:date.gte=>dd.at_beginning_of_day,:date.lt=>dd.end_of_day).all\r\n    rs = m_att.where( :date => { \'$gt\' => dd.at_beginning_of_day, \'$lt\' => dd.end_of_day } ).all\r\n    \r\n    # attendance provider list\r\n    ap_list = []\r\n    # attendance provider field\r\n    ap_field = []\r\n    \r\n    g_vis = rs.group_by{|i| i[:visit_type]}\r\n    \r\n    su = []\r\n    n1 = []\r\n    n2 = []\r\n    n3 = []\r\n    \r\n    rs.each do |i|\r\n        ap_list += i[:surgeon]\r\n        ap_list += i[:nurse_1]\r\n        ap_list += i[:nurse_2]\r\n        ap_list += i[:nurse_3]\r\n        \r\n        # su += m_att_prov.find(i[:surgeon])\r\n        # n1 += m_att_prov.find(i[:nurse_1])\r\n        # n2 += m_att_prov.find(i[:nurse_2])\r\n        # n3 += m_att_prov.find(i[:nurse_3])\r\n    end\r\n    \r\n    # all attendance provider\r\n    # a_ap = m_att_prov.find(ap_list)\r\n    \r\n    # g_su = su.group_by{|i| i[:room].to_s}\r\n    # g_n1 = n1.group_by{|i| i[:room].to_s}\r\n    # g_n2 = n2.group_by{|i| i[:room].to_s}\r\n    # g_n3 = n3.group_by{|i| i[:room].to_s}\r\n    \r\n    # g_ap = a_ap.group_by{|i| i[:room].to_s}\r\n    \r\n%>\r\n<%# params.to_json.html_safe %>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n				\r\n<%\r\n    # field attendance\r\n    f_att = get_doc_field \'attendance\'\r\n    # visit \r\n    v_list = f_att[:visit_type][:lov].split(/[\\r\\n]+/) \r\n    v_list.each do |i|\r\n        \r\n%>\r\n                    <a href=\"javascript:add_prov(\'<%= i %>\')\">\r\n                        <button class=\"btn\" style=\"width:140px;height:100px;margin:5px\">\r\n                            <i class=\"splashy-add\"></i>\r\n                            <br>\r\n                            <%= i.strip %>\r\n                        </button>\r\n                    </a>\r\n<% end %>\r\n					<!--<a href=\"../Appointment/create?return=../Home/main\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Appointment</button></a>-->\r\n					<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n						-->\r\n					<!--<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Calendar</button></a>-->\r\n					<!--<a href=\"../Home/report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>-->\r\n					<!--<a href=\"room_index?date=<%= params[:date] %>\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-folder_modernist_opened\"></i><br />Room</button></a>-->\r\n				\r\n				    \r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\" >\r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n					<h1 id=\'clock\'><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"\\\\#{params[:opt]}?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"<%= params[:opt] %>?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<!--<div class=\"clear\" style=\'margin-top:10px\'></div>-->\r\n\r\n<%\r\n    def link_prov ap, field, visit\r\n        pname = @prov[ap[:name].to_s][0][:name]\r\n            ts   = \'\'\r\n            te   = \'\'\r\n            if !ap[:in].nil? and ap[:in] != \'\'\r\n                ts = ap[:in].strftime(\'%H:%M\')\r\n            end\r\n            if !ap[:out].nil? and ap[:out] != \'\'\r\n                te = ap[:out].strftime(\'%H:%M\')\r\n            end\r\n        \r\n        tm = \" (\\\\#{ts}-\\\\#{te})\"\r\n        \r\n        if ts == \'\' and te == \'\'\r\n            tm = \" \"\r\n        end\r\n        \r\n        status = \'\'\r\n        if ap[:status] == \'ป่วย\'\r\n            status = \' btn-danger\'\r\n        end\r\n        \r\n        # return link_to(\"\\\\#{pname}\\\\#{tm}\", \"javascript:edit(\'\\\\#{ap.id.to_s}\',\'\\\\#{field}\', \'\\\\#{visit}\')\", :class=>\'btn\')\r\n        return link_to(\"\\\\#{pname}\\\\#{tm}\", \"../AttendanceProvider/edit?id=\\\\#{ap.id.to_s}&return=\\\\#{request.fullpath}\", :class=>\"btn\\\\#{status}\")\r\n    end\r\n\r\n    # ap_list : appointment_provider_list\r\n    # field : surgeon, nurse_1, nurse_2, nurse_3\r\n    # visit : elective, emergency, on call, add on (v_list)\r\n    @m_att_prov = m_att_prov\r\n    def get_prov_link_map ap_list, field, visit\r\n        tmp = {}\r\n        att_prov = @m_att_prov.find(ap_list)\r\n        g_room   = att_prov.group_by{|i| i[:room].to_s}\r\n        \r\n        g_room.each do |k,v|\r\n            x = []\r\n            v.each do |i|\r\n                x << link_prov(i, field, visit)\r\n            end\r\n            tmp[k] = x\r\n        end\r\n        \r\n        \r\n        return tmp\r\n    end\r\n\r\n    g_vis.each do |k,v|\r\n        surgeon_list = v[0][:surgeon]\r\n        n1_list = v[0][:nurse_1]\r\n        n2_list = v[0][:nurse_2]\r\n        n3_list = v[0][:nurse_3]\r\n        \r\n        rsur = get_prov_link_map(surgeon_list, \'surgeon\', k)\r\n        rnu1 = get_prov_link_map(n1_list, \'nurse_1\',k)\r\n        rnu2 = get_prov_link_map(n2_list, \'nurse_2\',k)\r\n        rnu3 = get_prov_link_map(n3_list, \'nurse_3\',k)\r\n        \r\n        tmp  = {}\r\n        tmp[:sur] = rsur\r\n        tmp[:n1]  = rnu1\r\n        tmp[:n2]  = rnu2\r\n        tmp[:n3]  = rnu3\r\n        \r\n        # surgeon in all room\r\n        asu = rsur[\'\'].nil? ? [] : rsur[\'\']\r\n        # nurse_1 in all room\r\n        an1 = rnu1[\'\'].nil? ? [] : rnu1[\'\']\r\n        # nurse_2 in all room\r\n        an2 = rnu2[\'\'].nil? ? [] : rnu2[\'\']\r\n        # nurse_3 in all room\r\n        an3 = rnu3[\'\'].nil? ? [] : rnu3[\'\']\r\n%>\r\n<div class=\"row-fluid\" style=\'margin-top:10px\'>\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				<h3><%= k %></h3>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n			\r\n                                        <table class=\"table table-striped table-bordered table-condensed\">\r\n    										<thead>\r\n    											<tr>\r\n    												<th width=\'10%\'>Room</th>\r\n    												<th width=\'25%\'>Surgeon</th>\r\n    												<th width=\'25%\'>RN FT</th>\r\n    												<th width=\'20%\'>RN PT</th>\r\n    												<th width=\'20%\'>NA</th>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n    room.each do |i|\r\n        rid = i.id.to_s\r\n        \r\n        rsu = rsur[rid].nil? ? [] : rsur[rid]\r\n        rn1 = rnu1[rid].nil? ? [] : rnu1[rid]\r\n        rn2 = rnu2[rid].nil? ? [] : rnu2[rid]\r\n        rn3 = rnu3[rid].nil? ? [] : rnu3[rid]\r\n%>\r\n    				                            <tr>\r\n    				                                <td style=\'vertical-align:middle\'>\r\n    				                                    <%= i[:name] %>\r\n    				                                </td>\r\n    				                                <td style=\'vertical-align:middle\'>\r\n                                                        <%= asu.join(\'&nbsp;&nbsp;\').html_safe %>\r\n                                                        <%= \'&nbsp;&nbsp;\'.html_safe if (asu.size > 0 and rsu.size > 0) %>\r\n                                                        <%= rsu.join(\'&nbsp;&nbsp;\').html_safe %>\r\n    				                                </td>\r\n    				                                <td style=\'vertical-align:middle\'>\r\n    				                                    <%= an1.join(\'&nbsp;&nbsp;\').html_safe %>\r\n    				                                    <%= \'&nbsp;&nbsp;\'.html_safe if (an1.size > 0 and rn1.size > 0) %>\r\n                                                        <%= rn1.join(\'&nbsp;&nbsp;\').html_safe %>\r\n    				                                </td>\r\n    				                                <td style=\'vertical-align:middle\'>\r\n    				                                    <%= an2.join(\'&nbsp;&nbsp;\').html_safe %>\r\n    				                                    <%= \'&nbsp;&nbsp;\'.html_safe if (an2.size > 0 and rn2.size > 0) %>\r\n                                                        <%= rn2.join(\'&nbsp;&nbsp;\').html_safe %>\r\n    				                                </td>\r\n    				                                <td style=\'vertical-align:middle\'>\r\n    				                                    <%= an3.join(\'&nbsp;&nbsp;\').html_safe %>\r\n    				                                    <%= \'&nbsp;&nbsp;\'.html_safe if (an3.size > 0 and rn3.size > 0) %>\r\n                                                        <%= rn3.join(\'&nbsp;&nbsp;\').html_safe %>\r\n    				                                </td>\r\n    				                            </tr>\r\n<%\r\n    end\r\n%>\r\n                                            </tbody>\r\n                                        </table>\r\n                                        \r\n                                        <div class=\'clear\'></div>\r\n                                        <div style=\'margin-top:10px\'>\r\n                                            <b>Officer : </b> <%= @prov[:officer_1].nil? ? \'N/A\' : @prov[:officer_1] %>\r\n                                            <br/>\r\n                                            <b>Employee : </b> <%= @prov[:employee1].nil? ? \'N/A\' : @prov[:employee1] %>\r\n                                        </div>\r\n                \r\n            </div>\r\n    \r\n        </div>\r\n    </div>\r\n</div>\r\n<%\r\n    end # end g_vis\r\n%>\r\n\r\n<%= render :inline=>this.att_prov_modal %>\r\n<script>\r\n\r\n    function add_prov(visit) {\r\n        att_prov_modal();\r\n        $(\'#att_prov-visit\').val(visit);\r\n    }\r\n\r\n    function edit (id, field, visit) {\r\n        \r\n    }\r\n\r\n    $(document).ready(function() {\r\n        $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        $(\'#add-surgeon\').click(function() {\r\n            att_prov_modal();\r\n        })\r\n    })\r\n    \r\n</script>',NULL,NULL,NULL,'2016-12-27 03:57:26','2016-12-27 03:57:26','index',''),(2846,'att_prov_modal',1143,4,'<!--\r\n\r\n\r\n    Attendance_Provider FORM RECORD\r\n\r\n\r\n-->\r\n<!--\r\n\r\n\r\n  Attendance_Provider FORM MODAL SECTION\r\n  \r\n\r\n-->\r\n<%\r\n    # prefix\r\n    pf = \'att_prov\'\r\n    # form data url\r\n    fd = \'../AttendanceProvider/create #form-data\'\r\n%>\r\n<div class=\"modal hide fade\" id=\"<%= pf %>-modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"close\" style=\"float:right;\"  data-dismiss=\"modal\">X</a>\r\n        <h3>Attendance Provider Record</h3>\r\n    </div>\r\n    <div class=\"modal-body\" style=\"height:800px\">\r\n<%= form_for :rec, :url=>\"index\", :html=>{\'id\'=>\"form-\\\\#{pf}-modal\"} do |f| %>\r\n        <%# hidden_field_tag :id,  @patient_module.module_id %>\r\n        <input type=\'hidden\' id=\'<%= pf %>-visit\' value=\'\' name=\'visit\'/>\r\n        \r\n        <select name=\'field\' id=\'<%=pf%>-field\'>\r\n            <option value=\'surgeon\'>Surgeon</option>\r\n            <option value=\'nurse_1\'>RN FT</option>\r\n            <option value=\'nurse_2\'>RN PT</option>\r\n            <option value=\'nurse_3\'>NA</option>\r\n        </select>\r\n        <br/>\r\n        <div class=\"clear\"></div>\r\n        <div id=\'form-<%=pf%>_record\'></div>\r\n        <div style=\'float:right\'>\r\n            <%= link_to \'Cancel\', \'#\', :class=>\'btn\', \'data-dismiss\'=>\'modal\' %>\r\n            <%= f.submit \'Add\', :class=>\'btn btn-success\', :id=>\"\\\\#{pf}-add-btn\" %>\r\n        </div>\r\n<% end %>\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n    \r\n    function <%= pf %>_modal(){\r\n        <%= pf %>_init();\r\n        $(\'#<%= pf %>-modal\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n        $(\"#<%= pf %>-modal\").show(\'fade\');\r\n        $(\".modal-backdrop\").show();\r\n    }\r\n    function <%= pf %>_modal_close() {\r\n        \r\n        console.log(\'Modal Close\');\r\n    }\r\n    function <%= pf %>_init() {\r\n        // this.form.reset();\r\n    }\r\n    function <%= pf %>_edit() {\r\n        \r\n    }\r\n    $(document).ready(function(){\r\n        \r\n        $(\'#form-<%= pf %>_record\').load(\'<%= fd %>\', function() {\r\n            $(\"#data-in\").kendoTimePicker({\r\n                value: \'8:00\',\r\n                interval: 15,\r\n                parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                change: function(event){\r\n                    var v = $(\'#data-time\').val()\r\n                    if(v.length==3){\r\n                        $(\'#data-time\').val(v[0]+\":\"+v[1]+v[2])\r\n                    }\r\n                }\r\n            });\r\n            $(\"#data-out\").kendoTimePicker({\r\n                value: \'16:00\',\r\n                interval: 15,\r\n                parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                change: function(event){\r\n                    var v = $(\'#data-time\').val()\r\n                    if(v.length==3){\r\n                        $(\'#data-time\').val(v[0]+\":\"+v[1]+v[2])\r\n                    }\r\n                }\r\n            });\r\n        });\r\n        \r\n    });\r\n\r\n      \r\n</script>\r\n<!--\r\n\r\n    END Modal Section\r\n\r\n-->',NULL,NULL,NULL,'2016-12-27 04:11:08','2016-12-27 04:11:08','att_prov_modal',''),(2847,'index',1151,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2016-12-27 05:43:23','2016-12-27 05:43:23',NULL,NULL),(2848,'layout',1151,4,'<%=default_layout%>',NULL,NULL,NULL,'2016-12-27 05:43:23','2016-12-27 05:43:23',NULL,NULL),(2849,'index',1152,2,'<style>\r\n                .dataTables_wrapper{position:relative;overflow:hidden}\r\n                .dataTables_wrapper table.table {clear:both;margin-bottom:6px!important;max-width:inherit}\r\n                .dataTables_wrapper table.table thead .sorting,table.table thead .sorting_asc,table.table thead .sorting_desc,table.table thead .sorting_asc_disabled,table.table thead .sorting_desc_disabled{cursor:hand;cursor:pointer}\r\n                .dataTables_wrapper table.table thead .sorting{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_both.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc_disabled.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc_disabled.png) no-repeat center right}\r\n</style>\r\n<!-- datatable -->\r\n            <script src=\"/gebo/lib/datatables/jquery.dataTables.min.js\"></script>\r\n            <script src=\"/gebo/lib/datatables/extras/Scroller/media/js/Scroller.min.js\"></script>\r\n            <!-- datatable functions -->\r\n            <script src=\"/gebo/js/gebo_datatables.js\"></script>\r\n<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n	session[module_name]={:date=>params[:date],:stamp=>Time.now.strftime(\'%d/%m/%Y\')}\r\n	end\r\n	if session[module_name] and session[module_name][:stamp] == Time.now.strftime(\'%d/%m/%Y\')\r\n	  params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n	his = session[:his]\r\n%>\r\n	\r\n<%#session[module_name].inspect %>\r\n<%\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    if params[:reset_lock]\r\n	    l = get_model[:locker].find(params[:reset_lock])\r\n        l.destroy if l\r\n	end\r\n	if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Patient Record\"\r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n    // window.location = \"../OutPatientForm/create?patient_id=<%=patient.id.to_s%>&record_name=<%=patient[:hn]%>&parent_id=<%=rec_pm_app.id.to_s%>&return=../Home/index\";\r\n</script>\r\n<%\r\n        end\r\n    end\r\n	\r\n	\r\n	\r\n	if params[:obj_id]\r\n	    now = Time.now \r\n	\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n					<!--<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Add Visit</button></a>-->\r\n					<a href=\"javascript:add_patient()\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-contact_blue_add\"></i><br />Add Patient</button></a>\r\n					<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Calendar</button></a>\r\n					<a href=\"../Report/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\" >\r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n					<h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n    \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"close\" style=\"float:right;\"  data-dismiss=\"modal\">X</a>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                    <a href=\"#\" id=\"get-hn\" class=\"btn\">GET</a>\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>เลขที่บัตรประชาชน : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n<%\r\n    if this.his_show\r\n%>\r\n<span id=\'span-his_btn\' style=\'margin-left:20px\'>\r\n\r\n  \r\n  \r\n<% if session[:his]%>\r\n<span id=\'his-status\'>\r\nWelcome <%= session[:his] %>\r\n\r\n  </span>\r\n    <a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient</a>\r\n<% else %>\r\n<span id=\'his-status\'>\r\nPlease login to get HN from HIS\r\n\r\n  </span>\r\n  <span id=\'temp-get-his\'>&nbsp;</span>\r\n            <span class=\'login-block\'>\r\n                <!--<div class=\'clear\'></div>-->\r\n                <div id=\"his-user\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px\">\r\n                    <span class=\"\"><label>Username : </label></span>	\r\n                    <input autofocus=\"\" type=\"text\" name=\"username\" id=\"input-username\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\">\r\n                </div>\r\n                <div id=\"his-pass\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Password  : </label></span>	\r\n                    <input type=\"password\" name=\"password\" id=\"input-password\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\">\r\n                </div>\r\n                <!--<div class=\'clear\'></div>-->\r\n            </span>\r\n<% end %>\r\n</span>\r\n\r\n<span id=\'span-btn\'>\r\n<% if session[:his] %>\r\n  <a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\r\n<% else %>\r\n  <span id=\'temp-his-logout\'>&nbsp;</span>\r\n  <a href=\'javascript:void(0)\' id=\'his-login\' class=\'btn btn-info\'>HIS Login</a>\r\n<% end %>\r\n</span>\r\n\r\n<% end %>\r\n            \r\n\r\n                <br/>\r\n                <div class=\'login-block btn btn-mini\' id=\'login-cancel\'  >x</div>\r\n                <span style=\'color:blue\' id=\'patient-msg\'></span>\r\n                <div class=\'clear\'></div>\r\n            \r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\" selected><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <div id=\'temporary\' style=\'\'></div>\r\n                <input type=\"hidden\" name=\"record[status]\" id=\"data-status\" value=\"Appointed\"/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Patient Record\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n\r\n    function init_fields(b) {\r\n        $(\'#data-public_id\').prop(\'readonly\', b);\r\n        $(\'#data-first_name\').prop(\'readonly\',b);\r\n        $(\'#data-last_name\').prop(\'readonly\',b);\r\n        $(\'#data-prefix_name\').prop(\'readonly\',b);\r\n        $(\'#input-prefix_name\').prop(\'readonly\',b);\r\n        $(\'#data-gender\').prop(\'readonly\',b);\r\n        $(\'#data-birth_date\').prop(\'readonly\',b);\r\n        \r\n        if (!b) {\r\n            $(\'#data-public_id\').val(\"\");\r\n            $(\'#data-first_name\').val(\"\");\r\n            $(\'#data-last_name\').val(\"\");\r\n            $(\'#data-prefix_name\').val(\"\");\r\n            $(\'#input-prefix_name\').val(\"\");\r\n            $(\'#data-gender\').val(\"\");\r\n            $(\'#data-birth_date\').val(\"<%= Time.now.strftime(\'%d/%m/%Y\') %>\");\r\n        }\r\n    }\r\n\r\n    function get_patient_info(us, ps, hn){\r\n        console.log(\'US:\' + us + \', PS:\' + ps + \',HN:\' + hn)\r\n        $(\'#his-status\').html(\'connecting...\');\r\n	    \r\n<% if his %>\r\n	\r\n	    var username = \'<%=his%>\'\r\n	    var password = \'-\'\r\n	\r\n<% end %>\r\n\r\n        // var hn=prompt(\"Please enter HN\",\"\");    \r\n        // var hn = hn\r\n        username = us;\r\n        password = ps;\r\n        if (hn==\'\') { \r\n            // alert(\"Not enough information!!\"); \r\n            $(\'#his-status\').html(\'No HN information, Please fill Patient HN\')\r\n        }else{     \r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading...</span>\');    \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            $.ajax({\r\n                url: \"get_patient_info?un=\"+username+\"&ps=\"+password+\"&hn=\"+hn,\r\n                context: document.body,\r\n                crossDomain: true\r\n            }).done(function(data) {\r\n                $(\'#his-status\').html(\'retriving...\');\r\n                // eval(data);\r\n                $(\'#temporary\').html(data);\r\n                $(\'#his-status\').html(\'completed\');\r\n                \r\n                if ($(\'#data-first_name\').val() != \'\') {\r\n                    init_fields(true);\r\n                } else {\r\n                    init_fields(false);\r\n                    $(\'#his-status\').html(\'Patient not found\')\r\n                }\r\n            }).fail(function(jqXHR, textStatus) {\r\n                // alert(\"error\");\r\n                $(\'#his-status\').html(\'Error loading, Please fill Patient information\')\r\n            });\r\n        }\r\n    }\r\n    \r\n    $(\'#get-his\').click(function() {\r\n        get_patient_info(\'<%= his %>\', \'-\', $(\'#data-hn\').val());\r\n    });\r\n	        \r\n	$(\'#his-logout\').click(function() {\r\n        $(\'#his-logout\').html(\'Loading ...\');\r\n        console.log(\'logout...\')\r\n        get_patient_info(\'-\', \'-\', \'-\');\r\n        // window.location = \'../Home/index\';\r\n    });\r\n    \r\n    $(document).ready(function(){\r\n        $(\'.login-block\').hide();\r\n        $(\'#his-login\').click(function() {\r\n            if ($(\'.login-block\').is(\":visible\")) {\r\n                $(\'#his-status\').show();\r\n                $(\'.login-block\').hide();\r\n                // console.log(\'get_patient_info\')\r\n                \r\n                \r\n    us = $(\'#input-username\').val();\r\n                ps = $(\'#input-password\').val();\r\n                hn = $(\'#data-hn\').val();\r\n                // $(\'#data-hn\').val(hn);\r\n                // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n                console.log(us + \'...\' + ps + \'...\' + hn);\r\n                $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n                get_patient_info(us, ps, hn);\r\n                \r\n                setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n                \r\n                // console.log(\'xxxx\');\r\n                // $(\'#his-status\').html(\'Logged as \' + us);\r\n                \r\n                $(\'#his-login\').hide();\r\n                $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n                $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient</a>\");\r\n                \r\n                // $(\'#modal\').modal(\'hide\')\r\n                // $(\'#modal\').attr(\'aria-hidden: false\');\r\n                // $(\'.modal-backdrop\').modal(\'hide\')\r\n                \r\n                // $(\'#commit\').click(function() {\r\n                //     console.log(\'login ...\')\r\n                //     us = $(\'#input-username\').val();\r\n                //     ps = $(\'#input-password\').val();\r\n                //     hn = $(\'#input-hn\').val();\r\n                //     get_patient_info(us, ps, hn);\r\n                //     console.log(\'... pass ...\')\r\n                // });\r\n                \r\n                $(\'#his-logout\').click(function() {\r\n            	    $(\'#his-logout\').html(\'Loading ...\');\r\n            	    console.log(\'logout...\')\r\n                    get_patient_info(\'-\', \'-\', \'-\');\r\n                    // window.location = \'../Home/index\';\r\n            	});\r\n                \r\n            } else {\r\n                $(\'#his-status\').hide();\r\n                $(\'.login-block\').show();\r\n                $(\'#his-login\').text(\'Get Patient\');\r\n                console.log(\'hide\')\r\n            }\r\n        })\r\n        $(\'#login-cancel\').click(function() {\r\n            $(\'#his-status\').show();\r\n            $(\'.login-block\').hide();\r\n            $(\'#his-login\').text(\'HIS Login\');\r\n        });\r\n        $(\'#commit\').click(function() {\r\n            us = $(\'#input-username\').val();\r\n            ps = $(\'#input-password\').val();\r\n            hn = $(\'#data-hn\').val();\r\n            // $(\'#data-hn\').val(hn);\r\n            // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n            // console.log(us + \'...\' + ps + \'...\' + hn);\r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n            get_patient_info(us, ps, hn);\r\n            \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            \r\n            // console.log(\'xxxx\');\r\n            // $(\'#his-status\').html(\'Logged as \' + us);\r\n            \r\n            $(\'#his-login\').hide();\r\n            $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n            $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient from HIS</a>\");\r\n            \r\n            // $(\'#modal\').modal(\'hide\')\r\n            // $(\'#modal\').attr(\'aria-hidden: false\');\r\n            // $(\'.modal-backdrop\').modal(\'hide\')\r\n            \r\n            // $(\'#commit\').click(function() {\r\n            //     console.log(\'login ...\')\r\n            //     us = $(\'#input-username\').val();\r\n            //     ps = $(\'#input-password\').val();\r\n            //     hn = $(\'#input-hn\').val();\r\n            //     get_patient_info(us, ps, hn);\r\n            //     console.log(\'... pass ...\')\r\n            // });\r\n            \r\n            $(\'#his-logout\').click(function() {\r\n        	    $(\'#his-logout\').html(\'Loading ...\');\r\n        	    console.log(\'logout...\')\r\n                get_patient_info(\'-\', \'-\', \'-\');\r\n                // window.location = \'../Home/index\';\r\n        	});\r\n        });\r\n    });\r\n</script>\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    \r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n	\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-hn\').val(\'\');\r\n        $(\'#patient-msg\').text(\'\');\r\n        init_fields(false);\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(\'#data-hn\').val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(\"[\" + data.hn + \"] \" + data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#data-hn\').val(data.hn);\r\n                $(\'#data-prefix_name\').val(data.prefix_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.toString().indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                // console.log(\'xxx \' + dd);\r\n                $(\'#data-birth_date\').val(dd);\r\n                $(\'#patient-msg\').text(\'Patient found in DB\');\r\n                init_fields(true);\r\n                // console.log(\'init field = true\')\r\n            } else {\r\n                $(\'#patient-msg\').text(\'Patient not found in DB. Please fill patient info.\');\r\n                init_fields(false);\r\n                // console.log(\'init field = false\')\r\n            }\r\n            \r\n            console.log(\"... \" + $(this).val())\r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#get-hn\').click(update_patient);\r\n    });\r\n</script>\r\n\r\n<script>\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n    var tt = <%= this.update_time_ms.to_i %>; // time to refresh\r\n    \r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        // tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'index_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        setTimeout(feed_page(100), 0);\r\n<%\r\n    if this.update_time_ms != 0\r\n%>        \r\n        loadPartial();\r\n<%\r\n    end\r\n%>\r\n        console.log(\'<%= this.update_time %>...\')\r\n    });\r\n\r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2016-12-27 05:46:37','2016-12-27 05:46:37','index',''),(2850,'index_partial',1152,3,'<%\r\n    main = \'../Home/index\'\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	id = \'\'\r\n	a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = module_model.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n	\r\n	sm = {}\r\n	# form service\r\n	f_ser = {}\r\n	# service_map\r\n	sv =  @current_project.get_services_by_abstract(\'ehr.emr.Document\')\r\n	sv.each do |i|\r\n	    nm = i[:name]\r\n	    if nm == \'appointment\' or nm == \'billing\' or nm == \'live_document\'\r\n	        next\r\n	    end\r\n	    \r\n	   # sm[nm.to_sym] = i[:title]\r\n	   sm[nm.to_sym] = i[:package].split(\'.\')[-1]\r\n	end\r\n	sm.each do |k, v|\r\n	    f_ser[k] = {}\r\n	    tmp = module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>pa_id).all\r\n	    tmp.each do |i|\r\n	        f_ser[k][i[:patient_id].to_s] = i.id.to_s\r\n	    end\r\n	end\r\n	\r\n	aps.collect!{|i| \r\n        id = i.id\r\n        if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n            pat_id = m.patient_id.to_s\r\n    	     patient = patient_model.find(m.patient_id)\r\n    	     if patient \r\n        	     provider = p_model.find(i.provider)\r\n        	     visit_type = visits[i.visit_type]\r\n        	     provider_name = \'NA\'\r\n        	     provider_name = provider.name if provider\r\n        	     procedure_name = \'NA\'\r\n        	     pro = models[:procedure].find(i.procedure) \r\n        	     procedure_name = pro.name if pro\r\n        	     patient = patient_model.new unless patient \r\n        	     hn = \'-\'\r\n        	     \r\n        	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n        	     provider_name  = link_to(provider_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     procedure_name = link_to(procedure_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     public_id = \'-\'\r\n    	    \r\n                c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id.to_s}\"),\r\n        	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        	     :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Arrived\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n        	     :visit_type=>visit_type,\r\n        	     :note=>i[:note]\r\n                }\r\n                \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info \', :style=>\'width:45px\')\r\n                # v_link = link_to(\'<i class=\"splashy-add\"></i> Add\'.html_safe, \r\n                #     \"../OutPatientForm/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/index\", \r\n                #     :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                # c_link = \'&nbsp;&nbsp;&nbsp;&nbsp;<i class=\"splashy-remove\"></i>\'\r\n                # if f_liv[pat_id]\r\n                #     c_link = \'&nbsp;&nbsp;&nbsp;&nbsp;<i class=\"splashy-check\"></i>\'\r\n                #     v_link = link_to(\'<i class=\"splashy-document_a4\"></i> View\'.html_safe, \r\n                #         \"../OutPatientForm/show?id=\\\\#{f_liv[pat_id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                # end\r\n                # c[:processing_ctrl]= \"\\\\#{v_link} \\\\#{d_link}\".html_safe \r\n                \r\n        l_list = []\r\n        sm.each do |k, v|\r\n                    lab = k.to_s.split(\'_\')[0].humanize\r\n                    v = v.delete(\' \')\r\n                    v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                        \"../\\\\#{v}/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=\\\\#{main}\", \r\n                        :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                    if f_ser[k][pat_id]\r\n                        v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            \"../\\\\#{v}/show?id=\\\\#{f_ser[k][pat_id]}&return=\\\\#{main}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                        # v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            # \"../\\\\#{v}/print?id=\\\\#{f_ser[k][pat_id]}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\', :target=>\'_blank\')\r\n                    end\r\n                    l_list << v_link\r\n        end\\\\#{request.fullpath}\r\n        \r\n                c[:processing_ctrl]= \"\\\\#{d_link}\".html_safe \r\n                c[:processing_ctrl] = \"\\\\#{l_list.join(\' \')} \\\\#{c[:processing_ctrl]}\".html_safe\r\n                \r\n                c\r\n            end\r\n        end\r\n	}.compact!\r\n	\r\n	table_model = %w{ hn patient provider visit_type processing_ctrl   note }.collect{|i| i.to_sym}\r\n	\r\n	\r\n	aps.collect!{|i| \r\n	\r\n	    i if i[:status]!=\'Cancelled\'\r\n	    \r\n	}.compact!\r\n	\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:procedure=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n	:note=>\'Note\',:visit_type=>\'Visit\',:processing_ctrl=>\'Actions\', :out_pat=>\'Out Patient Form\' }\r\n	\r\n	%>\r\n	<%# aps.to_json.html_safe %>\r\n	<% if @current_role==\'developer\' and false%>\r\n	<%= sm.to_json.html_safe %> <hr/>\r\n	<%= sv.to_json.html_safe %>\r\n	<% end %>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=aps.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\'background:#FCF8F0\'>\r\n			                        <div class=\'row-fluid\'>\r\n			                            <table id=\'appointed-patient\' class=\"table table-striped table-bordered dTableR\">\r\n    										<thead>\r\n    											<tr>\r\n    											\r\n<%  table_model.each do |i| %>\r\n    												<th><%= labels[i.to_sym] %></th>\r\n<%  end %>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n    if aps.size > 0\r\n        aps.each do |i|\r\n%>\r\n                                                <tr>\r\n<%\r\n            table_model.each do |j|\r\n                \r\n%>\r\n                                                    <td style=\'vertical-align:middle\'><%= (i[j].nil? or i[j]==\'\') ? \'-\' : i[j] %></td>\r\n<%\r\n            end\r\n%>\r\n                                                </tr>\r\n<%\r\n        end\r\n%>\r\n<% end %>\r\n                                            </tbody>\r\n                                        </table>\r\n                                    </div>\r\n\r\n\r\n<!--\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = aps.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model,:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = aps.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model,:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n-->\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n</div>\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        gebo_datatbles = {\r\n    		dt_a: function() {\r\n    			$(\'#appointed-patient\').dataTable({\r\n    			    stateSave : true,\r\n                    \"sDom\": \"<\'row\'<\'span6\'<\'dt_actions\'>l><\'span6\'f>r>t<\'row\'<\'span6\'i><\'span6\'p>>\",\r\n                    \"sPaginationType\": \"bootstrap_alt\",\r\n                    \"oLanguage\": {\r\n                        \"sLengthMenu\": \"_MENU_ records per page\",\r\n                        \"sEmptyTable\": \"No patient available in table. Please \'<a href=\'javascript:add_patient()\'>Add</a>\' the patient.\"\r\n                    }\r\n                });\r\n    		}\r\n        }\r\n        \r\n        gebo_datatbles.dt_a();\r\n        // gebo_datatbles.state.save();\r\n        \r\n     