e : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n<%\r\n    if return_url.include? \'?\'\r\n        return_url += \"&reset_lock=\\#{locker.id}\"\r\n    else\r\n        return_url += \"?reset_lock=\\#{locker.id}\"\r\n    end\r\n%>\r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2017-01-04 14:25:03','2017-01-04 14:25:03','create',''),(2871,'form',1043,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n    function cal_bmi() {\r\n        w = $(\'#data-weight\').val();\r\n        h = $(\'#data-height\').val();\r\n        \r\n        if (w == \'\' || h == \'\') {\r\n            $(\'#data-bmi\').val(\'\');\r\n        } else if (w != \'\' && h != \'\') {\r\n            ww = parseFloat(w);\r\n            hh = parseFloat(h);\r\n            \r\n            rs = (ww * 10000) / (hh * hh);\r\n            \r\n            $(\'#data-bmi\').val(rs.toFixed(2));\r\n            \r\n            if (rs < 18.5 || rs >= 25) {\r\n                $(\'#update_nutrition_3_item_0\').attr(\'checked\', true)\r\n                $(\'#data-nutrition_3\').val(\'0\');\r\n            } else {\r\n                $(\'#update_nutrition_3_item_1\').attr(\'checked\', true)\r\n                $(\'#data-nutrition_3\').val(\'1\');\r\n            }\r\n            \r\n            $(\'#nutrition_3\').effect(\"highlight\", {}, 1000);\r\n        }\r\n    }\r\n    \r\n    $(\'#data-weight\').change(cal_bmi);\r\n    $(\'#data-height\').change(cal_bmi);\r\n</script>\r\n',NULL,NULL,NULL,'2017-01-05 16:48:57','2017-01-05 16:48:57','form',''),(2872,'index',1160,2,'<%\r\n	return_url = url(\'index\')\r\n	return_url = params[:return] if params[:return]\r\n	\r\n	date = Time.now.strftime(\"%d/%m/%Y\")\r\n	time = Time.now.strftime(\"%H:%M\")\r\n	\r\n    # date = params[:date] if params[:date]\r\n    # time = params[:time] if params[:time]\r\n    \r\n    models = get_model\r\n    \r\n    p_model = models[:project].all\r\n    project = {}\r\n    p_model.each do |i|\r\n        project[i.id] = i\r\n    end\r\n    customer = {}\r\n    models[:customer].all.each do |i|\r\n        customer[i.id] = i\r\n    end\r\n    provider = {}\r\n    pv_name = {}\r\n    models[:provider].all.each do |i|\r\n        provider[i.id] = i\r\n        pv_name[i.name] = i.id\r\n    end\r\n    \r\n    p_select = p_model.collect{|i| [\"\\\\#{i.name} \\\\#{customer[i.customer_id].short}\",i.id]}    \r\n    \r\n    if request.post?\r\n        task={}\r\n        if params[:id]==\'\'\r\n            task = models[:task].create \r\n        else\r\n            task = models[:task].where(:id=>params[:id]).first\r\n        end\r\n        \r\n        task[:name] = params[:name] if params[:name]\r\n        task[:status] = params[:status] if params[:status]\r\n        task[:project_id] = params[:project_id]\r\n        task[:project_id] = params[:project_id].first if params[:project_id] \r\n        task[:date] = params[:date] if params[:date]\r\n        task[:start] = params[:start] if params[:start]\r\n        if params[:provider]\r\n            pv_save = params[:provider].split(\",\")\r\n            pv_save.collect!{|i| pv_name[i]}.compact!\r\n            task[:provider_id] = pv_save\r\n            \r\n        end\r\n        if params[:list]\r\n            ls = JSON.parse(params[:list])\r\n            list_add = []\r\n            ls.each do |l|\r\n                get_list = {}\r\n                if l[\"id\"]==\'\'\r\n                    get_list = models[:list].create :detail=>l[\"detail\"],:status=>l[\"status\"]\r\n                else\r\n                    get_list = models[:list].where(:id=>l[\"id\"]).first\r\n                    get_list[:detail] = l[\"detail\"]\r\n                    get_list[:status] = l[\"status\"]\r\n                    get_list.save\r\n                end\r\n                list_add << get_list.id if !list_add.include?(get_list.id)\r\n            end\r\n            %><%#=\"id=\"+task[:lists].size.inspect %><br><%\r\n            if task[:lists].size>0\r\n                for ol in task[:lists]\r\n                    if !list_add.include?(ol)\r\n                         models[:list].find(ol).destroy\r\n                    end\r\n                end\r\n            end\r\n            task[:lists] = list_add\r\n            \r\n            \r\n        end\r\n        \r\n        task.save\r\n%>\r\n<script>\r\nwindow.location.href=\"../Home/index\";\r\n</script>\r\n<%        \r\n        \r\n    end\r\n\r\n    list = {}\r\n    models[:list].all.each do |i|\r\n        list[i.id] = i\r\n    end\r\n\r\n    t_model = models[:task].all\r\n    # apps = models[:appointment].where(:date.gte=>project.start_date.at_beginning_of_day,:date.lt=>project.end_date.end_of_day).all\r\n\r\n    first = (Time.now - (Time.now.strftime(\"%u\").to_i-1).days).at_beginning_of_day\r\n    last = (first + 6.days).at_end_of_day\r\n    tmp_date = first\r\n    last_date = first + 5.days\r\n    tmp_month = \"\"\r\n\r\n    t_weekly = t_model.collect{|i| i if i.date}.compact\r\n    t_weekly = t_weekly.collect{|i| i if i.date>=first and i.date<last}.compact.sort{|a,b| a.date<=>b.date}\r\n    w_all = t_weekly.size\r\n    w_finish = t_weekly.collect{|i| i.status if i.status==\'Finish\'}.compact.size\r\n    w_per = 0\r\n    w_per = w_finish*100/w_all if w_all>0\r\n    \r\n    t_next = t_model.collect{|i| i if i.date}.compact\r\n    t_next = t_next.collect{|i| i if i.status!=\"Finish\" and i.date<first}.compact+t_next.collect{|i| i if i.date>=last}.compact\r\n    t_next.sort!{|a,b| a.date<=>b.date}\r\n    next_prepare = t_next.collect{|i| i.status if i.status==\'Prepare\'}.compact.size\r\n    next_follow = t_next.collect{|i| i.status if i.status==\'Follow\'}.compact.size\r\n    next_ready = t_next.collect{|i| i.status if i.status==\'Ready\'}.compact.size\r\n    \r\n    t_wait = t_model.collect{|i| i if !i.date}.compact\r\n\r\n    \r\n    s_class = {}\r\n    s_class[\"Ready\"] = \"btn-info\"\r\n    s_class[\"Prepare\"] = \"btn-warning\"\r\n    s_class[\"Follow\"] = \"btn-warning\"\r\n    s_class[\"Finish\"] = \"btn-success\"\r\n    \r\n%>\r\n<%#=t_weekly.inspect%>\r\n<link rel=\"stylesheet\" href=\"../../gebo/lib/tag_handler/css/jquery.taghandler.css\" />\r\n<script src=\"../../gebo/lib/tag_handler/jquery.taghandler.min.js\"></script>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-plus-sign\" style=\"margin-left:10px;\"></i> New task\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <%#=t_weekly.inspect%>\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            # date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n            Date : <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\',:style=>\'width:120px\' %> \r\n            Time : <%= text_field_tag \'time\',time,:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n        </div>\r\n\r\n        <script>\r\n        $(\"#today-date\").kendoDatePicker({\r\n            value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n            \r\n    	});\r\n    	$(\"#record-time\").kendoTimePicker({\r\n    		value: \'<%= time %>\',\r\n    		interval: 30,\r\n    		min: new Date(2019, 0, 1, 8, 0, 0) ,\r\n    		max: new Date(2019, 0, 1, 17, 0, 0) \r\n    	});\r\n        </script>\r\n        <% rescue %>\r\n          error\r\n        <% end %>    \r\n    \r\n        <!--<div class=\"span6\">\r\n    		<ul id=\"array_tag_handler\"></ul>\r\n    		<script>\r\n    		$(document).ready(function() {\r\n        // 		gebo_tag_handler = {\r\n        //     		init: function() {\r\n        //     			$(\"#array_tag_handler\").tagHandler({\r\n        //     				assignedTags: [ \'C\', \'Perl\', \'PHP\' ],\r\n        //     				availableTags: [ \'C\', \'C++\', \'C#\', \'Java\', \'Perl\', \'PHP\', \'Python\' ],\r\n        //     				autocomplete: true\r\n        //     			});\r\n        //     		}\r\n        //     	};\r\n    		});\r\n    		</script>\r\n    	</div>-->\r\n    	\r\n    	<button class=\"btn btn-primary btn-large\" id=\"btncreate\"><i class=\"icon-pencil icon-white\"></i> Create</button><br><br>\r\n	</div>\r\n</div> \r\n</div>\r\n\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-briefcase\" style=\"margin-left:10px;\"></i> Module\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n    <a href=\"../Project/index?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-folder_modernist\"></i><br />Project</button></a>\r\n    <a href=\"../Inventory/index?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-box\"></i><br />Inventory</button></a>\r\n    <a href=\"../Product/main?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-star_boxed_full\"></i><br />Product</button></a>\r\n    <a href=\"../Preventive/index?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-application_windows_edit\"></i><br />MA</button></a>\r\n\r\n\r\n    </div>\r\n</div> \r\n</div>\r\n</div>\r\n\r\n<style>\r\n.task{padding-bottom:20px;border-bottom:1px #FEFEFE solid;}\r\n.tproject_id{width:350px;}\r\n.intime{color:green;font-weight:bold;}\r\n.late{color:red;font-weight:bold;}\r\n.hdaydiv{padding-top:0px;padding-bottom:10px;font-weight:bolder;font-size:1.4em;font-style:none;}\r\n.hmonthdiv{padding-top:0px;padding-bottom:10px;font-weight:bolder;font-size:1.4em;font-style:none;background-color:#DEDEDE}\r\n.hmonth{float:right;}\r\n.ood{background-color:#FFFFFF;}\r\n.pair{background-color:#EFEFEF;}\r\n.hday{float:right;}\r\n.hMon{color:#EDEF85;}\r\n.hTue{color:#F4D2F4;}\r\n.hWed{color:#BDF4CB;}\r\n.hThu{color:#FFC48E;}\r\n.hFri{color:#BBDAFF;}\r\n.hSat{color:#E1CAF9;}\r\n.hSun{color:#FFCECE;}\r\n.Mon{background-color:#FFFFE3;}\r\n.Tue{background-color:#FFF9FF;}\r\n.Wed{background-color:#F5FFF2;}\r\n.Thu{background-color:#FFF1E6;}\r\n.Fri{background-color:#ECF4FF;}\r\n.Sat{background-color:#F5EEFD;}\r\n.Sun{background-color:#FFF9FC;}\r\n</style>\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-calendar\" style=\"margin-left:10px;\"></i> Weekly task\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"row-fluid\">\r\n            <h4><center>\r\n            Weekly progress <%=first.strftime(\"%d/%m/%Y\")+\" - \"+last.strftime(\"%d/%m/%Y\")%> \r\n            : Finished <%=w_per%>% [ <%=w_finish%>/<%=w_all%> ]\r\n            </center></h4>\r\n            <div class=\"progress progress-success progress-striped active\">\r\n              <div class=\"bar\" style=\"width: <%=w_per%>%;\"><%=w_per%>% </div>\r\n            </div>\r\n        </div><!--row-fluid-->\r\n        <div class=\"row-fluid\">\r\n        <%for t in t_weekly%>\r\n            <%\r\n            while tmp_date<t.date do\r\n                %>\r\n                <div class=\"<%=tmp_date.strftime(\'%a\')%> hdaydiv\">&nbsp;\r\n                <%if tmp_date.strftime(\"%d/%m/%Y\")==Time.now.strftime(\"%d/%m/%Y\")%><i class=\"splashy-star_full\" style=\"margin-top:5px\"></i> Today<%end%>\r\n                <span class=\"h<%=tmp_date.strftime(\'%a\')%> hday\"> + <%=tmp_date.strftime(\"%a %d %b %Y\")%></span>\r\n                </div>\r\n                <%\r\n                tmp_date+=1.day\r\n            end\r\n            %>\r\n            <div class=\"<%=t.date.strftime(\'%a\') if t.date%> task\" >\r\n            <input class=\"tid\" type=\"hidden\" value=\"<%=t.id%>\"> \r\n            <table width=\"100%\"><tr><td width=\"80px\" style=\"vertical-align:top;\">\r\n            <button class=\"btn btn-task <%=s_class[t.status] if s_class[t.status]%>\" style=\"width:80px\"><%=t.status%></button>\r\n            </td><td>\r\n            <div class=\"row-fluid\">\r\n            <div class=\"span12\">\r\n            <%=t.date.strftime(\'%d/%m\') if t.date%> <%=t.start.strftime(\'%H:%M\') if t.start%> \r\n            <%\r\n            if t.date and t.status!=\'Ready\' and t.status!=\'Finish\'\r\n                timepass = distance_of_time_in_words_to_now(t.date)\r\n                timeclass = \"intime\"\r\n                timeclass = \"late\" if t.date<date\r\n                %><i class=\"icon-time\"></i> <span class=\"<%=timeclass%>\"><%=timepass%></span><%\r\n            end\r\n            %>\r\n            <i class=\"splashy-pencil_small\"></i> <%=t.name%>\r\n            </div><!-- span12 -->\r\n            <div class=\"span12\">\r\n            <!--provider-->\r\n            <%\r\n            pv = \'\'\r\n            if t.provider_id\r\n                %><i class=\"splashy-contact_grey\"></i> <%\r\n                for pv_id in t.provider_id\r\n                    # pv+=\",\" if pv!=\'\' \r\n                    pv+=\' <span class=\"label label-info\">\'+provider[pv_id].name+\'</span>\'\r\n                end\r\n                %><%=pv.html_safe%><%\r\n            end\r\n            %>\r\n            <!--project-->\r\n            <%\r\n            if t.project_id\r\n                pj = project[t.project_id]\r\n                c = customer[pj.customer_id]\r\n                pj_content = \'\'\r\n                pj_content += pj.fullname if pj.fullname\r\n                pj_content += \" \"+pj.location if pj.location\r\n            %>\r\n                <i class=\"splashy-folder_modernist\"></i> \r\n                <a href=\"#\" class=\"pop_over\" data-content=\"<%=pj_content%>\" data-original-title=\"<%=c.name%>\" data-placement=\"bottom\" data-trigger=\"hover\">\r\n                <%=pj.name+\" \"+c.short%>\r\n                </a>\r\n            <%end%>\r\n            </div><!-- span12 -->\r\n            <div class=\"span12\">\r\n            <%\r\n            if t.lists.size>0\r\n            %>\r\n            <i class=\"splashy-view_list_with_thumbnail\"></i>\r\n                <%for l in t.lists do%>\r\n                <%=\'<i class=\"splashy-okay_small\"></i>\'.html_safe if list[l].status==\"true\"%>\r\n                <%=\'<i class=\"splashy-error_small\"></i>\'.html_safe if list[l].status==\"false\"%>\r\n                <%=list[l].detail%>\r\n                <%end%>\r\n            <%end%>\r\n            </div><!-- span12 -->\r\n            </div>\r\n            </td></tr></table>\r\n            </div><!-- task -->\r\n        <%end%>\r\n            <%\r\n            while tmp_date<last_date do\r\n                %>\r\n                <div class=\"<%=tmp_date.strftime(\'%a\')%> hdaydiv\">&nbsp;\r\n                <!--<i class=\"splashy-star_full\" style=\"margin-top:5px\"></i> Today-->\r\n                <span class=\"h<%=tmp_date.strftime(\'%a\')%> hday\"> + <%=tmp_date.strftime(\"%a %d %b %Y\")%></span>\r\n                </div>\r\n                <%\r\n                tmp_date+=1.day\r\n            end\r\n            %>        \r\n            <!--<div class=\"Mon task\" >-->\r\n            <!--Mon 07/01 -->\r\n            <!--<button class=\"btn btn-warning\">Follow</button>-->\r\n            <!--<i class=\"icon-time\"></i> <font color=red><b>-5d</b></font>-->\r\n            <!--target : 10/01/19-->\r\n            <!--<i class=\"splashy-document_a4\"></i> meeting ent-->\r\n            <!--<i class=\"splashy-folder_modernist\"></i> ENT-->\r\n            <!--<i class=\"splashy-contact_grey\"></i> Jubb, Mit, Mos-->\r\n            <!--</div>-->\r\n        </div><!--row-fluid-->\r\n    </div><!-- w-box content--->\r\n</div> \r\n\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-forward\" style=\"margin-left:10px;\"></i> Next\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"row-fluid\">\r\n            <div id=\"example\" class=\"span4\">\r\n            <div class=\" demo-section k-content wide\">\r\n                <div id=\"chart\" ></div>\r\n            </div>\r\n            <script>\r\n                function createChart() {\r\n                    $(\"#chart\").kendoChart({\r\n                        series: [{\r\n                            type: \"pie\",\r\n                            startAngle: 150,\r\n                            data: [{\r\n                                category: \"Follow\",\r\n                                value: <%=next_follow%>,\r\n                                color: \"#FFBF48\"\r\n                            },{\r\n                                category: \"Prepare\",\r\n                                value: <%=next_prepare%>,\r\n                                color: \"#90cc38\"\r\n                            },{\r\n                                category: \"Ready\",\r\n                                value: <%=next_ready%>,\r\n                                color: \"#75D6FF\"\r\n                            }]\r\n                        }],\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                }\r\n        \r\n                $(document).ready(createChart);\r\n                // $(document).bind(\"kendo:skinChange\", createChart);\r\n            </script>\r\n            </div>  \r\n            <div class=\"span8\">\r\n                <div class=\"row-fluid\">\r\n                <%for i in (0..t_next.length-1)%>\r\n                <%\r\n                    t=t_next[i]\r\n                    if tmp_month != t.date.strftime(\"%B\")\r\n                        tmp_month = t.date.strftime(\"%B\") \r\n                        %><div class=\"hmonthdiv\">&nbsp;<span class=\"hmonth\"><%=tmp_month%></span></div><%\r\n                    end\r\n                %>\r\n                 \r\n                    <div class=\"<%=i%2==0?\"ood\":\"pair\"%> task\" >\r\n                    <input class=\"tid\" type=\"hidden\" value=\"<%=t.id%>\"> \r\n                    <table width=\"100%\"><tr><td width=\"80px\" style=\"vertical-align:top;\">\r\n                    <button class=\"btn btn-task <%=s_class[t.status] if s_class[t.status]%>\" style=\"width:80px\"><%=t.status%></button>\r\n                    </td><td>\r\n                    <div class=\"row-fluid\">\r\n                    <div class=\"span12\">\r\n                    <%=t.date.strftime(\'%d/%m\') if t.date%> <%=t.start.strftime(\'%H:%M\') if t.start%> \r\n                    <%\r\n                    if t.date and t.status!=\'Ready\' and t.status!=\'Finish\'\r\n                        timepass = distance_of_time_in_words_to_now(t.date)\r\n                        timeclass = \"intime\"\r\n                        timeclass = \"late\" if t.date<date\r\n                        %><i class=\"icon-time\"></i> <span class=\"<%=timeclass%>\"><%=timepass%></span><%\r\n                    end\r\n                    %>\r\n                    <i class=\"splashy-document_a4\"></i> <%=t.name%>\r\n                    </div>\r\n                    <div class=\"span12\">\r\n                    <!--provider-->\r\n                    <%\r\n                    pv = \'\'\r\n                    if t.provider_id\r\n                        %><i class=\"splashy-contact_grey\"></i> <%\r\n                        for pv_id in t.provider_id\r\n                            # pv+=\",\" if pv!=\'\' \r\n                            pv+=\' <span class=\"label label-info\">\'+provider[pv_id].name+\'</span>\'\r\n                        end\r\n                        %><%=pv.html_safe%><%\r\n                    end\r\n                    %>\r\n                    <!--project-->\r\n                    <%\r\n                    if t.project_id\r\n                        pj = project[t.project_id]\r\n                        c = customer[pj.customer_id]\r\n                        pj_content = \'\'\r\n                        pj_content += pj.fullname if pj.fullname\r\n                        pj_content += \" \"+pj.location if pj.location\r\n                    %>\r\n                        <i class=\"splashy-folder_modernist\"></i> \r\n                        <a href=\"#\" class=\"pop_over\" data-content=\"<%=pj_content%>\" data-original-title=\"<%=c.name%>\" data-placement=\"bottom\" data-trigger=\"hover\">\r\n                        <%=pj.name+\" \"+c.short%>\r\n                        </a>\r\n                    <%end%>\r\n                    </div><!-- span12 -->\r\n                    <div class=\"span12\">\r\n                    <%\r\n                    if t.lists.size>0\r\n                    %>\r\n                    <i class=\"splashy-view_list_with_thumbnail\"></i>\r\n                        <%for l in t.lists do%>\r\n                        <%=\'<i class=\"splashy-okay_small\"></i>\'.html_safe if list[l].status==\"true\"%>\r\n                        <%=\'<i class=\"splashy-error_small\"></i>\'.html_safe if list[l].status==\"false\"%>\r\n                        <%=list[l].detail%>\r\n                        <%end%>\r\n                    <%end%>\r\n                    </div><!-- span12 -->\r\n                    </div>\r\n                    </td></tr></table>\r\n                    </div><!-- task -->\r\n                <%end%>\r\n                    <%\r\n                    while tmp_date<last_date do\r\n                        %>\r\n                        <div class=\"<%=tmp_date.strftime(\'%a\')%> hdaydiv\">&nbsp;\r\n                        <!--<i class=\"splashy-star_full\" style=\"margin-top:5px\"></i> Today-->\r\n                        <span class=\"h<%=tmp_date.strftime(\'%a\')%> hday\"> + <%=tmp_date.strftime(\"%a %d %b %Y\")%></span>\r\n                        </div>\r\n                        <%\r\n                        tmp_date+=1.day\r\n                    end\r\n                    %>        \r\n                </div><!--row-fluid-->\r\n            </div><!--span8-->\r\n        </div>\r\n    \r\n    </div><!-- w-box content -->\r\n</div> \r\n\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-star-empty\" style=\"margin-left:10px;\"></i> Waiting\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"row-fluid\">\r\n        <%for i in (0..t_wait.length-1)%>\r\n            <%\r\n                t=t_wait[i]\r\n            %>\r\n            <div class=\"<%=i%2==0?\"ood\":\"pair\"%> task\" >\r\n            <input class=\"tid\" type=\"hidden\" value=\"<%=t.id%>\"> \r\n            <button class=\"btn btn-task <%=s_class[t.status] if s_class[t.status]%>\" style=\"width:80px\"><%=t.status%></button>\r\n            <%=t.date.strftime(\'%d/%m\') if t.date%> <%=t.start.strftime(\'%H:%M\') if t.start%> \r\n            <%\r\n            if t.date and t.status!=\'Ready\' and t.status!=\'Finish\'\r\n                timepass = distance_of_time_in_words_to_now(t.date)\r\n                timeclass = \"intime\"\r\n                timeclass = \"late\" if t.date<date\r\n                %><i class=\"icon-time\"></i> <span class=\"<%=timeclass%>\"><%=timepass%></span><%\r\n            end\r\n            %>\r\n            <i class=\"splashy-document_a4\"></i> <%=t.name%>\r\n            <%\r\n            if t.project_id\r\n                pj = project[t.project_id]\r\n                c = customer[pj.customer_id]\r\n                pj_content = \'\'\r\n                pj_content += pj.fullname if pj.fullname\r\n                pj_content += \" \"+pj.location if pj.location\r\n            %>\r\n                <i class=\"splashy-folder_modernist\"></i> \r\n                <a href=\"#\" class=\"pop_over\" data-content=\"<%=pj_content%>\" data-original-title=\"<%=c.name%>\" data-placement=\"bottom\" data-trigger=\"hover\">\r\n                <%=pj.name+\" \"+c.short%>\r\n                </a>\r\n            <%end%>\r\n            <%\r\n            pv = \'\'\r\n            if t.provider_id\r\n                %><i class=\"splashy-contact_grey\"></i> <%\r\n                for pv_id in t.provider_id\r\n                    # pv+=\",\" if pv!=\'\' \r\n                    pv+=\' <span class=\"label label-info\">\'+provider[pv_id].name+\'</span>\'\r\n                end\r\n                %><%=pv.html_safe%><%\r\n            end\r\n            %>\r\n            </div>\r\n        <%end%>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<!-- modal -->\r\n<script>\r\n$(\".task\").click(function(){\r\n    tid = $(this).find(\".tid\").val();\r\n    // alert(tid);\r\n    path_task = \'../Task/json\';\r\n    $.ajax({\r\n        dataType: \"json\",\r\n        url: path_task,\r\n        data: {\r\n            id: tid\r\n        },\r\n        success: function(doc) {\r\n            // alert(doc);\r\n            loadTask(doc);\r\n            $(\"#taskModal\").modal(\"toggle\");\r\n        }\r\n    });\r\n    // $(\"#taskModal\").modal(\"toggle\");\r\n});\r\n$(\"#btncreate\").click(function(){\r\n    j = \'{\"id\":\"\",\"status\":\"Ready\",\"project_id\":\"\",\"name\":\"\",\"provider_id\":\"\",\"lists\":\"\"}\';\r\n    obj = $.parseJSON(j);\r\n    loadTask(obj);\r\n    $(\"#taskModal\").modal(\"toggle\");\r\n});\r\nfunction loadTask(t){\r\n    $(\"#tid\").val(t.id);\r\n    updateStatus(t.status);\r\n    if(t.date) $(\"#tdate\").kendoDatePicker({value:t.date});\r\n    else {$(\"#tdate\").kendoDatePicker().val(\"\");}\r\n    if(t.start) $(\"#tstart\").kendoTimePicker({value:t.start});\r\n    else $(\"#tstart\").kendoTimePicker().val(\"\");\r\n    $(\"#tname\").val(t.name);\r\n    $(\"#tproject_id\").val(t.project_id).trigger(\"liszt:updated\");\r\n    // alert($(\"#tstatus\").text());\r\n    updateProvider(t.provider_id);\r\n    updateLists(t.lists);\r\n\r\n}\r\nfunction updateStatus(s){\r\n    // alert(s);\r\n    $(\"#tstatus\").val(s);\r\n    $(\"#btnstatus\").text(s);\r\n    c = \"btn span4 bstatus \";\r\n    if(s==\'Ready\') c+=\"btn-info\";\r\n    if(s==\'Prepare\'||s==\"Follow\") c+=\"btn-warning\";\r\n    if(s==\'Finish\') c+=\"btn-success\";\r\n    $(\"#btnstatus\").attr(\"class\",c);\r\n}\r\nfunction updateLists(ls){\r\n    $(\".ldata\").remove();\r\n    $.each(ls,function(i,d){\r\n        ischeck=(d.status==\'true\')?\'checked\':\'\';\r\n        row = \'<tr class=\"ldata\" id=\"\'+d.id+\'\"><td><input type=\"checkbox\" class=\"lcheck\" \'+ischeck+\'></td><td class=\"ltext\">\'+d.detail+\'</td><td><span><i class=\"icon-trash delete\"></i></span></td></tr>\'\r\n        $(\"#tablelist\").append(row);\r\n    });\r\n}\r\nfunction updateProvider(pv){\r\n    if(pv){\r\n        $(\"#tprovider\").val(pv);\r\n        $(\".prov\").removeClass(\"btn-info\").addClass(\"disabled\");\r\n        $.each(pv,function(i,d){\r\n            $(\".prov\").each(function(){\r\n                if($(this).text()==d) $(this).addClass(\"btn-info\").removeClass(\"disabled\");\r\n            });\r\n        });\r\n    }else{\r\n        $(\".prov\").removeClass(\"btn-info\").addClass(\"disabled\");\r\n    }\r\n}\r\n$(document).ready(function(){\r\n    $(\".pop_over\").popover();\r\n    // $(\"#sidebar_bt\").click();\r\n});\r\n\r\n\r\n</script>\r\n\r\n<div id=\"taskModal\" class=\"modal hide fade\" tabindex=\"-1\" role=\"dialog\" aria-labelledby=\"myModalLabel\" aria-hidden=\"true\">\r\n<script src=\"../../gebo/lib/chosen/chosen.jquery.min.js\"></script>\r\n<link rel=\"stylesheet\" href=\"../../gebo/lib/chosen/chosen.css\" />\r\n<form id=\"task_form\" method=\"post\">\r\n<input type=\"hidden\" name=\"id\" id=\"tid\">\r\n<input type=\"hidden\" name=\"status\" id=\"tstatus\">\r\n<input type=\"hidden\" name=\"provider\" id=\"tprovider\">\r\n<input type=\"hidden\" name=\"list\" id=\"tlist\">\r\n\r\n<div class=\"modal-hearder\">\r\n    <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-hidden=\"true\">×</button>\r\n    <h3> <i class=\"splashy-document_a4\" style=\"vertical-align:middle;margin-left:10px;\"></i> Task</h3>   \r\n    <hr>\r\n</div>\r\n<div class=\"modal-body\">\r\n    <div class=\"row-fluid\">\r\n        <div class=\"row-fluid\">\r\n            <div class=\"span8\">\r\n            <label><i class=\"splashy-calendar_month\"></i> Date </label>\r\n            <input type=\"text\" class=\"span12\" id=\"tdate\" name=\"date\">\r\n            </div>\r\n            <div class=\"span4\">\r\n            <label><i class=\"icon-time\"></i> Time </label>\r\n            <input type=\"text\" class=\"span12\" id=\"tstart\" name=\"start\">\r\n            </div>\r\n        </div>\r\n        <div class=\"row-fluid\">\r\n            <label><i class=\"splashy-document_a4\"></i> Name</label>\r\n            <input type=\"text\" class=\"span12\" id=\"tname\" name=\"name\">\r\n        </div>\r\n        <div class=\"row-fluid\">\r\n            <div class=\"span12\">\r\n            <label><i class=\"splashy-folder_modernist\"></i> Project</label>\r\n			<%=select_tag :project_id, options_for_select(p_select),{:id=>\'tproject_id\',:class=>\'tproject_id\',:multiple=>true,\'data-placeholder\'=>\'Choose Project...\'}%>\r\n			</div>\r\n        </div>\r\n        <div class=\"row-fluid\">\r\n            <div class=\"row-fluid\">\r\n            <div class=\"span2\"><i class=\"splashy-comment_alert\"></i> Status </div><span class=\"btn span4 bstatus btn-info\" id=\"btnstatus\">Ready</span>\r\n            </div>\r\n            <div class=\"row-fluid collapse\">\r\n            <div class=\"alert span12\">\r\n            <span class=\"btn span2 btn-info bstatus\" id=\"b_Ready\">Ready</span>\r\n            <span class=\"btn span2 btn-warning bstatus\" id=\"b_Prepare\">Prepare</span>\r\n            <span class=\"btn span2 btn-warning bstatus\" id=\"b_Follow\">Follow</span>\r\n            <span class=\"btn span2 btn-success bstatus\" id=\"b_Finish\">Finish</span>\r\n            <span class=\"btn span2 bstatus\" id=\"b_Postpone\"> Postpone </span>\r\n            <span class=\"btn span2 bstatus\" id=\"b_Waiting\"> Waiting </span>\r\n            </div>\r\n            </div>\r\n        </div>\r\n        <div class=\"row-fluid\">\r\n            <label><i class=\"splashy-contact_grey\"></i> Provider<label>\r\n            <span class=\"btn span2 disabled prov\">Mos</span>\r\n            <span class=\"btn span2 disabled prov\">Ong</span>\r\n            <span class=\"btn span2 disabled prov\">Mit</span>\r\n            <span class=\"btn span2 disabled prov\">Jubb</span>\r\n            <span class=\"btn span2 disabled prov\">Soup</span>\r\n        </div>\r\n        <div class=\"row-fluid\">\r\n            <div class=\"span12\">\r\n                <table class=\"table table-striped\" id=\"tablelist\">\r\n                <thead><th colspan=\"2\"><i class=\"splashy-view_list_with_thumbnail\"></i> List <th></thead>\r\n                <tr><td><input type=\"checkbox\" id=\"acheck\"></td><td><textarea id=\"textlist\" class=\"span12\" rows=\"3\"></textarea><span class=\"help-block\">Add more than one item by new line</span></td><td><span class=\"btn btn-primary addlist\" id=\"addlist\">Add</span></td></thead>\r\n                </table>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"modal-footer\">\r\n    <button class=\"btn\" data-dismiss=\"modal\" aria-hidden=\"true\">Close</button>\r\n    <button class=\"btn btn-success\" id=\"btn_confirm\" type=\"submit\"><i class=\"icon-ok icon-white\"></i> Update</button>\r\n</div>\r\n</form>\r\n<script>\r\n$(\"#tdate\").kendoDatePicker({\r\n    // value: \'\',\r\n    // change: function(){\r\n    //     window.location = \"./setcase?date=\"+kendo.toString(this.value(), \'d\')\r\n    // }\r\n});\r\n$(\"#ttime\").kendoTimePicker({\r\n// 	value: \'\',\r\n	interval: 30,\r\n	min: new Date(2019, 0, 1, 8, 0, 0) ,\r\n	max: new Date(2019, 0, 1, 17, 0, 0) \r\n});\r\n$(\".tproject_id\").chosen();\r\n\r\n\r\n$(\".prov\").click(function(){\r\n    if($(this).hasClass(\"disabled\")){\r\n        $(this).removeClass(\"disabled\");\r\n        $(this).addClass(\"btn-info\");\r\n    }else{\r\n        $(this).removeClass(\"btn-info\");\r\n        $(this).addClass(\"disabled\");\r\n    }\r\n    var pv_list = \'\';\r\n    $(\".prov\").each(function(){\r\n        if($(this).hasClass(\"btn-info\")){\r\n            if(pv_list!=\'\') pv_list+=\',\';\r\n            pv_list += $(this).text();\r\n        }\r\n    });\r\n    $(\"#tprovider\").val(pv_list);\r\n    // alert($(\"#tprovider\").val());\r\n});\r\n$(\".bstatus\").click(function(){\r\n    //alert(\'collapse\');\r\n    $(\"#tstatus\").val($(this).text());\r\n    $(\"#btnstatus\").attr(\"class\",$(this).attr(\"class\"));\r\n    $(\"#btnstatus\").text($(this).text());\r\n    $(\"#btnstatus\").removeClass(\"span2\").addClass(\"span4\");\r\n    $(\".collapse\").collapse(\'toggle\');\r\n});\r\n$(\".delete\").live(\'click\', function(event) {\r\n    $(this).parents(\'tr\').remove();\r\n});\r\n$(\"#acheck\").change(function(){\r\n    $(\".lcheck\").attr(\"checked\",$(this).attr(\"checked\")?true:false);\r\n});\r\n$(\".addlist\").click(function(){\r\n    // alert($(\"#textlist\").val().split(\"\\\\n\"));\r\n    var newpost=$(\"#textlist\").val().split(\"\\\\n\");\r\n    var row=\'\';\r\n    $.each(newpost,function(i,d){\r\n        row = \'<tr class=\"ldata\" id=\"\"><td><input type=\"checkbox\" class=\"lcheck\"></td><td class=\"ltext\">\'+d+\'</td><td><span><i class=\"icon-trash delete\"></i></span></td></tr>\'\r\n        $(\"#tablelist\").append(row);\r\n    });\r\n    $(\"#textlist\").val(\"\");\r\n});\r\n$(\"#btn_confirm\").click(function(){\r\n    updateList();\r\n});\r\nfunction updateList(){\r\n    list=[];\r\n    $(\"#tablelist > tbody > tr\").each(function(){\r\n        if($(this).hasClass(\"ldata\")){\r\n            // alert($(this).find(\".lcheck\").attr(\"checked\"));\r\n            ischeck=$(this).find(\".lcheck\").attr(\"checked\")?true:false;\r\n            text=$(this).find(\".ltext\").text();\r\n            id=$(this).attr(\"id\");\r\n            list.push(\'{\"detail\":\"\'+text+\'\",\"status\":\"\'+ischeck+\'\",\"id\":\"\'+id+\'\"}\');\r\n        }\r\n    });\r\n    $(\"#tlist\").val(\'[\'+list+\']\');\r\n}\r\n</script>\r\n</div>    \r\n<!-- end modal-->    \r\n\r\n\r\n',NULL,NULL,NULL,'2017-01-08 05:55:21','2017-01-08 05:55:21','',''),(2873,'layout',1160,4,'<%=default_layout%>',NULL,NULL,NULL,'2017-01-08 05:55:21','2017-01-08 05:55:21',NULL,NULL),(2874,'document_name',1161,1,'\'product\'',NULL,NULL,NULL,'2017-01-08 05:55:42','2017-01-08 05:55:42',NULL,NULL),(2875,'document_name',1162,1,'\'product_category\'',NULL,NULL,NULL,'2017-01-08 05:55:54','2017-01-08 05:55:54',NULL,NULL),(2876,'document_name',1163,1,'\'order\'',NULL,NULL,NULL,'2017-01-08 05:56:24','2017-01-08 05:56:24',NULL,NULL),(2877,'document_name',1164,1,'\'order_item\'',NULL,NULL,NULL,'2017-01-08 05:56:29','2017-01-08 05:56:29',NULL,NULL),(2878,'document_name',1165,1,'\'store\'',NULL,NULL,NULL,'2017-01-08 05:56:38','2017-01-08 05:56:38',NULL,NULL),(2879,'document_name',1166,1,'\'store_item\'',NULL,NULL,NULL,'2017-01-08 05:56:45','2017-01-08 05:56:45',NULL,NULL),(2880,'document_name',1167,1,'\'stock_card\'',NULL,NULL,NULL,'2017-01-08 05:56:55','2017-01-08 05:56:55',NULL,NULL),(2881,'index',1168,2,'<%=render :inline=>this.init%>\r\n<%\r\n\r\n    \r\n\r\n%>\r\n<div class=\"\">\r\n    \r\n    <div class=\"row-fluid\">\r\n        \r\n\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"xw-box-header\">\r\n      <b>Welcome to <span style=\"color:#F3790D\">Inventory System</span></b><br/>\r\n    </div>  \r\n    <div class=\"xw-box-content cnt_a\">\r\n   \r\n    \r\n<div class=\"row-fluid\">\r\n\r\n\r\n\r\n<div class=\"span12\">\r\n\r\n\r\n<ul class=\"dshb_icoNav tac \">\r\n\r\n<% \r\n@stores = @models[:store].all\r\n\r\nfor i in @stores\r\n\r\n cls = \'\'\r\n cls = \'btn-success\' if @current_store and  i.id == @current_store.id\r\n%>		\r\n\r\n<a href=\"change_store?id=<%=i.id%>\"><button class=\"btn <%=cls%>\" style=\"width:120px;height:50px;margin:5px\">\r\n <%= i%>\r\n</button></a>\r\n\r\n\r\n<% end  %>\r\n\r\n   \r\n</ul></div>\r\n\r\n</div>\r\n</div>\r\n</div>  \r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n    items = []\r\n    \r\n    if @current_store\r\n    \r\n    items = @models[:store_item].where(:store_id=>@current_store.id).all\r\n    \r\n    end\r\n\r\n    products = @models[:product].find(items.collect{|i| i.product_id})\r\n    product_map = {}\r\n    for i in products\r\n        product_map[i.id] = i\r\n    end\r\n    \r\n    # order \r\n    orders = []\r\n    \r\n    if @current_store\r\n    \r\n    orders = @models[:order].where(:store_id=>@current_store.id).sort(\'created_at desc\').limit(100).all\r\n\r\n\r\n    end\r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      \r\n      \r\n      <%= @current_store %> Inventory\r\n      <%\r\n      \r\n      quick_order = nil\r\n      \r\n      %>\r\n      \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n         <%= form_for :order, :url=>\"quick_order\" do |f|  %>\r\n            \r\n        <div class=\"row-fluid\">\r\n        <div class=\"span8\">\r\n        <b>Transaction : </b> \r\n        \r\n        <%=link_to \'Usage\', \'create_order?type=usage\',:class=>\'btn\' %> &nbsp;\r\n        \r\n        <%=link_to \'Check In\', \'create_order?type=check_in\',:class=>\'btn\' %> &nbsp;\r\n        \r\n        <%=link_to \'Check Out\', \'create_order?type=check_out\',:class=>\'btn\' %> &nbsp;\r\n\r\n\r\n        <%=link_to \'Transfer\', \'create_order?type=transfer\',:class=>\'btn\' %> &nbsp;\r\n        </div>\r\n        <div class=\"span4 right\">\r\n            <%\r\n                \r\n                \r\n                if @current_store and quick_order = @models[:order].where(:status=>\'Pending\',:order_type=>[\'usage\',\'amend\'],:store_id=>@current_store.id).first\r\n                 \r\n                if request.post?\r\n                   \r\n                 \r\n                   \r\n                   if params[:balances]\r\n                       \r\n                       qitems =  @models[:order_item].find(quick_order.items)\r\n                        \r\n                       for i in qitems\r\n                            i.destroy\r\n                       end\r\n                       \r\n                       for i in items\r\n                        \r\n                        p = params[:balances][i.product_id.to_s]\r\n                        product = product_map[i.product_id]\r\n                        \r\n                        diff = 0\r\n                        diff = i.balance - p.to_i  if i.balance and p\r\n                        \r\n                        if diff != 0 \r\n                           \r\n                          new_item =  @models[:order_item].create :product_id=>i.product_id, :quantity=>-diff, :price=>product.price, :title=>product.name\r\n                            \r\n                           quick_order.items << new_item.id   \r\n                            \r\n                        end\r\n                        \r\n                        \r\n                       end\r\n                       \r\n                       quick_order.save\r\n                       \r\n                       \r\n                   end\r\n                   %>\r\n                   <meta http-equiv=\"refresh\" content=\"0; url=../Home/index\" />\r\n\r\n\r\n                   <%\r\n                    \r\n                end\r\n                \r\n            %>\r\n           \r\n            Check Out ( <%=quick_order.items.size %> items ) : \r\n            <%= hidden_field_tag \'id\', quick_order.id %>\r\n            <%= f.text_field \'search\', :id=>\'search_field\',:style=>\"width:100px\" %>\r\n            <%= f.submit \'Go\', :class=>\'btn\' %>\r\n            <% if quick_order.order_type ==\'amend\' %>\r\n            <%= link_to \'Amend Summary\', \"../Order/show?id=\\\\#{quick_order.id}\" ,:class=>\'btn btn-info\'%>\r\n            <% else %>\r\n            <%= link_to \'Checkout Summary\', \"../Order/show?id=\\\\#{quick_order.id}\" ,:class=>\'btn btn-success\'%>\r\n            <% end %>\r\n            <% else %>\r\n            <% \r\n            \r\n            %>\r\n            <%# link_to \'Start Checkout\', \'create_order?type=usage&session=quick_order\', :class=>\'btn btn-success\' %>\r\n            <%= link_to \'Start Balance Check\', \'create_order?type=amend&session=quick_order\', :class=>\'btn btn-info\' %>\r\n            <%= link_to \'Print\', \'print\', :class=>\'btn\', :target=>\'_blank\' %>\r\n\r\n\r\n\r\n            <% end %>\r\n            \r\n            \r\n        </div>\r\n        </div>\r\n        \r\n        <script>\r\n         $(document).ready(function(){\r\n                 $(\'#search_field\').focus();\r\n         });\r\n        </script>\r\n        \r\n        <% if params[:show_item]\r\n        \r\n            item = @models[:order_item].find params[:show_item]\r\n            \r\n            if item\r\n                \r\n            product = @models[:product].find item.product_id    \r\n        \r\n        %>\r\n        <div class=\"alert alert-info\">\r\n            <%\r\n                if product.image and product.image.size>0\r\n                img = @models[:attachment].find product.image[0]\r\n            %>\r\n            <%=image_tag img.path, height:100%>\r\n            <% end %>\r\n            <%= product.title %> <%= item.quantity %> <%=product.unit %> has been added.\r\n            \r\n            <%= link_to \'Cancel\', \"quick_order?id=\\\\#{quick_order.id}&order_item=\\\\#{item.id}\" ,:class=>\'btn btn-danger \'%>\r\n            \r\n        </div>\r\n        \r\n        <% end %>\r\n\r\n        <% end %>\r\n          <%\r\n    \r\n        products = @models[:product].all\r\n    \r\n    %>\r\n    \r\n    <script>\r\n        var products = <%= products.to_json.html_safe %>\r\n        var p_map = {}\r\n        \r\n        function init_product(){\r\n            for(i=0;i<products.length;i++){\r\n                ix = products[i];\r\n                p_map[ix[\'id\']] = ix;\r\n            }\r\n        }\r\n        \r\n        \r\n        \r\n        function searchProduct(){\r\n            v = $(\'#search_field\').val()\r\n            alert(v);\r\n      \r\n    \r\n        }\r\n        init_product();\r\n        </script>\r\n        \r\n        \r\n        \r\n        \r\n        \r\n        <style>\r\n            vt{\r\n                color:black;\r\n            }\r\n            v{\r\n                color:blue;\r\n            }\r\n        </style>\r\n        <br/>\r\n        \r\n        <div class=\"tabbable\">\r\n								<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#tab1\" data-toggle=\"tab\">Inventory</a></li>\r\n									<li><a href=\"#tab2\" data-toggle=\"tab\">Order / Transaction</a></li>\r\n									<li><a href=\"#tab3\" data-toggle=\"tab\">.</a></li>\r\n								</ul>\r\n								<div class=\"tab-content\">\r\n									<div class=\"tab-pane active\" id=\"tab1\">\r\n										<p>\r\n	\r\n    	  \r\n   <table class=\"table\">\r\n            <thead>\r\n                <tr>\r\n                    <th>\r\n                        Name\r\n                    </th>\r\n                    \r\n                    <th>\r\n                        Code\r\n                    </th>\r\n                    \r\n                    <th>\r\n                        Manufacture\r\n                    </th>\r\n                  \r\n                    <th>\r\n                        Barcode\r\n                    </th>\r\n                    \r\n                      <th>\r\n                        Balance\r\n                    </th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n            <%\r\n            \r\n            \r\n                 qickmap = {}\r\n                \r\n                if quick_order\r\n                    for q in quick_order.items\r\n                        iq = @models[:order_item].find(q)\r\n                       \r\n                        if iq\r\n                           qickmap[iq.product_id] = [] unless qickmap[iq.product_id]\r\n                           qickmap[iq.product_id] << iq\r\n                        end\r\n                    end\r\n                end\r\n            \r\n            \r\n                for i in items \r\n            \r\n            \r\n                p = product_map[i.product_id]\r\n                \r\n                if p \r\n                \r\n                \r\n                path = \"../Product/show?id=\\\\#{p.id}&store=\\\\#{@current_store.id}\"\r\n                \r\n                balance = 0\r\n               \r\n                if quick_order\r\n                  \r\n                  iq = qickmap[i.product_id]\r\n                  if iq \r\n                     for q in iq \r\n                        balance += q.quantity\r\n                     end\r\n                  end\r\n                    \r\n                    \r\n                end\r\n               \r\n            %>\r\n                <tr>\r\n                    <td> \r\n                       \r\n                        \r\n                        <%= link_to \'Check Out\',\"quick_order?id=\\\\#{quick_order.id}&product_id=\\\\#{p.id}\",:class=>\'btn \' if quick_order and quick_order.order_type==\'usage\'  %> <%=link_to p.name, path %> \r\n                        <div style=\"float:right\"><%=link_to \'-\' , \"remove_item?id=\\\\#{i.id}\", :data=>{:confirm=>\'Are you sure?\'},:class=>\'btn btn-mini btn-danger\' if i.balance==0 %></div>\r\n                        \r\n                    </td>\r\n                    <td>\r\n                        <%= p.code %>\r\n                    </td>\r\n                    <td>\r\n                        <%= p.manufacture %>\r\n                    </td>\r\n                  \r\n                    <td>\r\n                        <%= p.barcode %>\r\n                    </td>\r\n                    \r\n                    \r\n                    <td style=\"font-size:1.2em;<%=\'color:red\' if i.balance-balance<=0 %>\">\r\n                        \r\n                        <%  if quick_order and quick_order.order_type==\'amend\' \r\n                        \r\n                            sign = \'+\'\r\n                            sign = \'-\' if balance < 0\r\n                        \r\n                        %>\r\n                        <%= text_field_tag \"balances[\\\\#{i.product_id}]\", i.balance+balance ,:style=>\"width:50px;text-align:center\" %>\r\n                        \r\n                        <vt><%= i.balance %></vt> <%= \"<v>\\\\#{sign} \\\\#{balance.abs}</v>\".html_safe if balance!=0 %>\r\n                        \r\n                        \r\n                        <% else %>\r\n                        \r\n                        <%= i.balance-balance %> <v><%= \"+ \\\\#{balance}\" if balance>0 %></v>\r\n                        \r\n                        <% end %>\r\n                    </td>\r\n                    \r\n                </tr>\r\n                \r\n            <% end %>\r\n            <% end %>    \r\n            </tbody>\r\n        </table>\r\n        \r\n        \r\n        <%= f.submit \'Submit\', :data=>{:confirm=>\'Are you sure?\'} %>\r\n        \r\n      \r\n	\r\n	\r\n										</p>\r\n									</div>\r\n									<div class=\"tab-pane\" id=\"tab2\">\r\n										<p>\r\n										\r\n										    \r\n\r\n        \r\n        \r\n          <table class=\"table\">\r\n            <thead>\r\n                <tr>\r\n                    <th>\r\n                        Type\r\n                    </th>\r\n                    <th>\r\n                        Status\r\n                    </th>\r\n                    <th>\r\n                        Code\r\n                    </th>\r\n                       \r\n                    <th>\r\n                        Reference\r\n                    </th>\r\n                    \r\n                    \r\n                    <th>\r\n                        DateTime\r\n                    </th>\r\n                    <th>\r\n                        Action\r\n                    </th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n            <%  for i in orders \r\n              \r\n            %>\r\n                <tr>\r\n                    <td>\r\n                        <%= i.order_type %>\r\n                    </td>\r\n                    <td>\r\n                        <%= i.status %>\r\n                    </td>\r\n                    <td>\r\n                        <%= i.code %>\r\n                    </td>\r\n                     <td>\r\n                        <%= i.ref2_id%>\r\n                    </td>\r\n                    <td>\r\n                        <%= i.created_at %>\r\n                    </td>\r\n                    <td>\r\n                        <%=link_to \'Commit\', \"../Order/commit?id=\\\\#{i.id}&return=../Home/index\",:class=>\'btn btn-mini btn-success\' if i.status==\'Pending\' or i.status==\'Draft\' %>\r\n                        <%=link_to \'Detail\', \"../Order/show?id=\\\\#{i.id}\",:class=>\'btn btn-mini\' %>\r\n                    </td>\r\n                    \r\n                    \r\n                </tr>\r\n                \r\n            <% end %>    \r\n            </tbody>\r\n        </table>\r\n										    \r\n										    \r\n										</p>\r\n									</div>\r\n									<div class=\"tab-pane\" id=\"tab3\">\r\n										<p>\r\n									    .\r\n										</p>\r\n									</div>\r\n								</div>\r\n							</div>\r\n        \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        \r\n      \r\n    \r\n        \r\n    \r\n    \r\n    \r\n  <% end %>\r\n    </div>\r\n</div>  \r\n</div>\r\n</div>\r\n\r\n</div>',NULL,NULL,NULL,'2017-01-08 06:33:57','2017-01-08 06:33:57','index',''),(2882,'init',1168,4,'<%\r\n    @models=get_model\r\n    \r\n    @current_store = nil\r\n    \r\n    \r\n    \r\n    @current_store = @models[:store].find(session[:current_store]) if session[:current_store]\r\n    \r\n    unless @current_store\r\n    \r\n        @current_store = @models[:store].first\r\n        if @current_store\r\n            \r\n            session[:current_store] = @current_store.id\r\n        end\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n%>',NULL,NULL,NULL,'2017-01-08 08:46:59','2017-01-08 08:46:59','init',''),(2883,'change_store',1168,3,'<%\r\n    @models = get_model\r\n    \r\n    store = @models[:store].find(params[:id])\r\n    if store\r\n    session[:current_store] = store.id\r\n    \r\n%>\r\nChange current store to \r\n<%=  store %><meta http-equiv=\"refresh\" content=\"0; url=index\" />\r\n<% else %>\r\nCould not find store..\r\n<%=  store %><meta http-equiv=\"refresh\" content=\"0; url=index\" />\r\n<% end %>',NULL,NULL,NULL,'2017-01-08 08:54:48','2017-01-08 08:54:48','change_store',''),(2884,'create_order',1168,2,'<%= render :inline=>this.init %>\r\n\r\n<%= render :inline=>this.top_menu %>\r\n\r\n<% if request.post? and params[:items]\r\n    \r\n    \r\n    orders = []\r\n    \r\n    if params[:order][:order_type]==\'transfer\'\r\n        orders << [params[:order][:store_id], \'check_out\']\r\n        orders << [params[:to_store], \'check_in\']\r\n    else\r\n        orders << [params[:order][:store_id], params[:order][:order_type]]\r\n    end    \r\n    \r\n    \r\n    for o in orders\r\n    \r\n    items = []\r\n    \r\n    p = params[:items]\r\n    \r\n    params[:items][\'product_id\'].each_with_index do |i,index|\r\n        \r\n        expired_date = nil\r\n        if exp = p[\'exp\'][index] and exp!=\'\'\r\n        exp = exp.split(\"-\")\r\n        expired_date = Date.new(exp[2].to_i, exp[1].to_i-1, exp[0].to_i).to_mongo\r\n        end\r\n    \r\n        it = @models[:order_item].create :product_id=>p[\'product_id\'][index], :quantity=>p[\'quantity\'][index], :lot=>p[\'lot\'][index], :expried_date=>expired_date\r\n        \r\n        items << it\r\n        \r\n    \r\n    end\r\n    \r\n    \r\n    params[:order][:items] = items.collect{|i| i.id} \r\n    \r\n    params[:order][:store_id] = o[0]\r\n    params[:order][:order_type] = o[1]\r\n    \r\n    \r\n    order = @models[:order].create params[:order]\r\n    o << order\r\n    \r\n    end\r\n    \r\n    \r\n    order = orders[0][-1]\r\n\r\n%>\r\n\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Order/show?id=<%=order.id%>\" />\r\n\r\n\r\n<% elsif params[:type]==\'amend\'\r\n\r\n    \r\n        order = @models[:order].create :order_type=>params[:type], :store_id=>  @current_store.id,:status=>\'Pending\'\r\n        if order\r\n        session[params[:session].to_sym] = order.id\r\n        end\r\n    \r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Home/index\" />\r\n\r\n\r\n<% else %>\r\n<%= form_for :order, :url=>\'create_order\' do |f| %>\r\n<%= hidden_field_tag \"type\", params[:type] %>\r\n <div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Order\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <%\r\n        title = params[:type].humanize if params[:type]\r\n    %>\r\n    \r\n    <strong>\r\n    Inventory &gt; \r\n    <%= @current_store %> Store\r\n    </strong>\r\n    <br/>  <br/>\r\n    \r\n    <div class=\"row-fluid\">\r\n        <div class=\"span8\">\r\n            \r\n            <table class=\"table\">\r\n                \r\n                <thead>\r\n                    <tr>\r\n                        <th>\r\n                            No.\r\n                        </th>\r\n                        <th>\r\n                            Product Name\r\n                        </th>\r\n                         <th>\r\n                            Manufacture\r\n                        </th>\r\n                        <th>\r\n                            Code\r\n                        </th>\r\n                        <th>\r\n                            Quantity\r\n                        </th>\r\n                        <th>\r\n                            LOT\r\n                        </th>\r\n                        <th>\r\n                            Expired\r\n                        </th>\r\n                         <th>\r\n                            \r\n                        </th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody id = \"list\">\r\n                    \r\n                    \r\n                </tbody>\r\n            </table><br/>\r\n            \r\n                <% if params[:type]==\'transfer\' \r\n                \r\n                    stores = @models[:store].all\r\n                \r\n                %>\r\n                <div class=\"alert\">\r\n                From : <b><%=@current_store%></b>\r\n                To : <%= select_tag \'to_store\', options_for_select(stores.collect{|i| [i.name,i.id] }),:style=>\'width:100px\' %>\r\n                </div>\r\n                <% end %>        \r\n                <br/>\r\n                <%=f.submit \'Create \'+title, :class=>\'btn btn-success\',:confirm=>\'Are you sure?\'%> | <%=link_to \'Cancel\', \"index\" %>\r\n\r\n            \r\n            \r\n        </div>\r\n        \r\n        <div class=\"span4\">\r\n\r\n            \r\n													<div class=\"formSep control-group input-append\">\r\n														<input type=\"text\" style=\"width:80%\" id=\"search_field\" name=\"Input\"><button type=\"button\" class=\"btn\" name=\"clear\" value=\"c\" onclick=\"Calc.Input.value = \'\'\">\r\n														<i class=\"icon-remove\"></i></button>\r\n													</div>\r\n				<table class=\"table\" style=\"width:100%\">\r\n                \r\n                <thead>\r\n                    <tr>\r\n                       <th>\r\n                            Action\r\n                        </th>\r\n                        <th>\r\n                            Balance\r\n                        </th>\r\n                       \r\n                        <th>\r\n                            Description\r\n                        </th>\r\n                         <th>\r\n                            Code\r\n                        </th>\r\n                        \r\n                        <th>\r\n                            Manuf\r\n                        </th>\r\n                        \r\n                        \r\n                        \r\n                    \r\n                    </tr>\r\n                </thead>\r\n                <tbody id = \"search_list\">\r\n                    \r\n                    \r\n                </tbody>\r\n            </table>\r\n            \r\n            <hr/>\r\n            \r\n													\r\n													<div class=\"control-group\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"seven\" value=\"7\" onclick=\"Calc.Input.value += \'7\'\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"eight\" value=\"8\" onclick=\"Calc.Input.value += \'8\'\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"nine\" value=\"9\" onclick=\"Calc.Input.value += \'9\'\">\r\n													</div>\r\n													<div class=\"control-group\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"four\" value=\"4\" onclick=\"Calc.Input.value += \'4\'\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"five\" value=\"5\" onclick=\"Calc.Input.value += \'5\'\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"six\" value=\"6\" onclick=\"Calc.Input.value += \'6\'\">\r\n													</div>\r\n													<div class=\"control-group\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"one\" value=\"1\" onclick=\"Calc.Input.value += \'1\'\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"two\" value=\"2\" onclick=\"Calc.Input.value += \'2\'\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"three\" value=\"3\" onclick=\"Calc.Input.value += \'3\'\">\r\n													</div>\r\n													<div class=\"formSep control-group\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"dot\" value=\".\" onclick=\"Calc.Input.value += \'.\'\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"zero\" value=\"0\" onclick=\"Calc.Input.value += \'0\'\">\r\n														<input type=\"button\" class=\"btn btn-large\" name=\"DoIt\" value=\"Q\" onclick=\"Calc.Input.value = Math.round( eval(Calc.Input.value) * 1000)/1000\">\r\n													</div>\r\n													\r\n										\r\n            \r\n          \r\n            \r\n        </div>\r\n    </div>\r\n    <%\r\n    \r\n        products = @models[:product].all\r\n        \r\n     \r\n        \r\n        \r\n        balance_map = {}\r\n        if @current_store \r\n                \r\n            sitems = @models[:store_item].collection.find({:store_id=>@current_store.id})\r\n            \r\n            for i in sitems\r\n                \r\n                balance_map[i[\'product_id\']] = 0 unless balance_map[i[\'product_id\']]\r\n                \r\n                balance_map[i[\'product_id\']] += i[\'balance\'].to_i\r\n            \r\n            end\r\n                    \r\n            \r\n        end     \r\n        \r\n      \r\n         if params[:type]==\'transfer\' or params[:type]==\'check_out\' or params[:type]==\'usage\'\r\n            \r\n            products = products.collect{|i| i if balance_map[i.id] and balance_map[i.id] > 0 }.compact\r\n            \r\n        end\r\n      \r\n        \r\n    %>\r\n    \r\n    \r\n    <script>\r\n        var products = <%= products.to_json.html_safe %>\r\n        var p_map = {}\r\n        var b_map = <%= balance_map.to_json.html_safe %>\r\n        \r\n        function init(){\r\n            for(i=0;i<products.length;i++){\r\n                ix = products[i];\r\n                if(ix[\'barcode\']==null)ix[\'barcode\']=\'-\';\r\n                if(ix[\'name\']==null)ix[\'name\']=\'-\';\r\n                if(ix[\'title\']==null)ix[\'title\']=\'-\';\r\n                if(ix[\'manufacture\']==null)ix[\'manufacture\']=\'-\';\r\n                \r\n                ix[\'balance\'] = 0\r\n                if(b_map[ix[\'id\']]!=null)\r\n                ix[\'balance\'] = b_map[ix[\'id\']]\r\n                \r\n                \r\n                \r\n                // ix[\'name\'] = ix[\'name\'].toLowerCase();\r\n                \r\n                p_map[ix[\'id\']] = ix;\r\n            }\r\n            searchProduct();\r\n        }\r\n        \r\n        \r\n        \r\n        function searchProduct(){\r\n            v = $(\'#search_field\').val()\r\n            if(v==\'-\')return;\r\n            \r\n            var res = []\r\n            count = 0 ;\r\n            \r\n            for(i=0;i<products.length;i++){\r\n                p = products[i];\r\n                if(v!=\'\'&&p[\'barcode\']==v){\r\n                    addRow(p[\'id\'])\r\n                }else\r\n                if((p[\'code\']!=null&&p[\'code\'].indexOf(v)>=0)||(p[\'barcode\']!=null&&p[\'barcode\'].indexOf(v)>=0)||p[\'name\'].toLowerCase().indexOf(v.toLowerCase())>=0||p[\'title\'].indexOf(v)>=0||p[\'manufacture\'].toLowerCase().indexOf(v.toLowerCase())>=0){\r\n                  \r\n                    res.push(p)\r\n                    \r\n                    count+=1;\r\n                    if(v.length>0&&count>20)break;\r\n                }    \r\n            }\r\n            \r\n            $(\'#search_list\').html(\'\');\r\n            for(i=0;i<res.length;i++){\r\n            p = res[i];\r\n            \r\n            t =  $(\'#search_template\')\r\n       \r\n            // t.each(\'.pname\').html(p[\'name\'])\r\n            // t.each(\'.pbarcode\').html(p[\'barcode\'])\r\n            \r\n            // console.log(t)\r\n            \r\n            tr = $(\'<tr/>\');\r\n            td = $(\'<td />\');\r\n            ta = $(\'<a class=\"btn\">Add</a>\').attr({\'href\':\"javascript:addRow(\'\"+p[\'id\']+\"\')\"})\r\n            tr.append(td.clone().append(ta.clone()))\r\n            tr.append(td.clone().html(p[\'balance\']))\r\n\r\n\r\n            tr.append(td.clone().html(p[\'name\']))\r\n            tr.append(td.clone().html(p[\'manufacture\']))\r\n            tr.append(td.clone().html(p[\'code\']))\r\n\r\n\r\n            // tr.append(td.clone().html(p[\'barcode\']))\r\n            \r\n            \r\n            $(\'#search_list\').append(tr)\r\n            \r\n            \r\n            \r\n            }\r\n           \r\n        }\r\n        \r\n        function addRow(pid){\r\n            \r\n            p = p_map[pid]\r\n            if(p!=null){\r\n            \r\n            tr = $(\'<tr/>\');\r\n            td = $(\'<td />\');\r\n            ta = $(\'<a class=\"btn btn-mini\">Remove</a>\').attr({\'href\':\"#\"})\r\n           \r\n            tq = $(\'<%=text_field_tag(\"items[quantity][]\", 1 ,:style=>\'width:40px;text-align:left\',:size=>5) %>\');\r\n            tlot = $(\'<%=text_field_tag(\"items[lot][]\", 1 ,:style=>\'width:80px\') %>\');\r\n\r\n            texp = $(\'<%=text_field_tag(\"items[exp][]\", \'\' ,:style=>\'width:80px\') %>\');\r\n\r\n\r\n            th = $(\'<%=hidden_field_tag(\"items[product_id][]\", \'\' ,:style=>\'width:40px\',:size=>5) %>\');\r\n            \r\n            tl = td.clone().html(p[\'name\'])\r\n            \r\n            tl.append(th.clone().attr({\'name\':\"items[product_id][]\",\'value\': p[\'id\']}))\r\n    \r\n\r\n            tr.append(td.clone().html(\'-\'))\r\n            \r\n            tr.append(tl)\r\n            tr.append(td.clone().html(p[\'manufacture\']))\r\n\r\n\r\n            tr.append(td.clone().html(p[\'barcode\']))\r\n\r\n\r\n            tqx = tq.clone()\r\n            tr.append(td.clone().append(tqx))\r\n            tlx = tlot.clone().attr({\'name\':\"items[lot][]\",\'value\': \'\'})\r\n            tr.append(td.clone().append(tlx))\r\n            \r\n            tr.append(td.clone().append(texp.clone()))\r\n            \r\n            tr.append(td.clone().append(ta.clone().click(function(){\r\n                $(this).parent().parent().remove();\r\n            })))\r\n            \r\n            \r\n            $(\'#list\').append(tr)\r\n            \r\n            s = $(\'#search_field\')\r\n            s.val(\'\')\r\n            s.focus();\r\n            \r\n            //  $(\'#search_list\').html(\'\');\r\n        \r\n            }\r\n            \r\n        }\r\n        init();\r\n        $(\'#search_field\').keyup(searchProduct)\r\n        $(\'#search_field\').keydown(function(e){\r\n    if (e.keyCode == 13) { // barcode scanned!\r\n        $(\'#b2\').focus();\r\n        return false; // block form from being submitted yet\r\n    }\r\n});\r\n        \r\n    </script>\r\n    \r\n    \r\n    \r\n    \r\n    </div>\r\n    \r\n</div>\r\n</div>\r\n\r\n    </div>\r\n    \r\n<%= f.hidden_field :order_type, :value=> params[:type] %>\r\n<%= f.hidden_field :status, :value=> \'Draft\' %>\r\n<%= f.hidden_field :store_id, :value=> @current_store.id %>\r\n\r\n\r\n<% end %>\r\n<% end %>',NULL,NULL,NULL,'2017-01-08 09:09:38','2017-01-08 09:09:38','create_order',''),(2885,'top_menu',1168,4,'',NULL,NULL,NULL,'2017-01-08 14:53:25','2017-01-08 14:53:25','top_menu',''),(2886,'commit_order',1168,3,'<%= render :inline=>this.init %>\r\n<%\r\n\r\n        \r\n    \r\n    \r\n%>',NULL,NULL,NULL,'2017-01-08 15:27:35','2017-01-08 15:27:35','commit_order',''),(2887,'commit',1163,3,'<%\r\n\r\n    @models = get_model\r\n    \r\n    order = @models[:order].find params[:id]\r\n    \r\n    \r\n    if order \r\n\r\n\r\n    items = @models[:order_item].find order.items\r\n    \r\n    store = @models[:store].find order.store_id\r\n    \r\n    ms = {}\r\n    \r\n    \r\n    store_items = @models[:store_item].where(:store_id=> store.id).all\r\n    for i in store_items\r\n    \r\n        ms[i.product_id] = i\r\n        \r\n    end\r\n    \r\n    \r\n    if order.status == \'Pending\' or order.status==\'Draft\'\r\n      \r\n      completed = false\r\n        \r\n      case order.order_type \r\n      \r\n      when \'check_in\', \'amend\'\r\n      \r\n            si_map = {}\r\n            \r\n            for i in items\r\n                \r\n                si_map[i.product_id] = {:items=>[]} unless si_map[i.product_id]\r\n                si_map[i.product_id][:items] << i\r\n      \r\n            end\r\n            \r\n            si_map.each_pair do |k,v|\r\n                \r\n                ix = ms[k]\r\n                ix = @models[:store_item].create :product_id=>k, :store_id=>store.id, :balance=>0 unless ix\r\n                si_map[k][:ix] = ix\r\n                \r\n            end\r\n            \r\n            \r\n            \r\n            \r\n            for i in items\r\n            \r\n                ix = si_map[i.product_id][:ix]\r\n                \r\n                # ix = @models[:store_item].create :product_id=>i.product_id, :store_id=>store.id, :balance=>0 unless ix\r\n                \r\n                sc = @models[:stock_card].create :order_id=>order.id, :store_item_id=>ix.id, :type=>\'in\', :quantity=>i.quantity, :lot=>i.lot, :expired_date=>i.expired_date\r\n                \r\n                ix.balance = 0 unless ix.balance \r\n                ix.balance += i.quantity\r\n                \r\n                ix.save\r\n                \r\n                \r\n            end\r\n            \r\n            completed = true\r\n            \r\n\r\n      when \'check_out\',\'sale\',\'usage\'\r\n      \r\n      \r\n         msg = \'\'\r\n          check = true\r\n          \r\n          si_map = {}\r\n          \r\n          for i in items\r\n          \r\n            ix = ms[i.product_id]\r\n            if ix\r\n            si_map[i.product_id] = ix.balance\r\n            else\r\n            check = false\r\n            msg = \"No item in the store.\"\r\n            end\r\n            \r\n            \r\n          end\r\n        \r\n        \r\n          \r\n          \r\n          if check\r\n      \r\n        \r\n          for i in items\r\n         \r\n            ix = si_map[i.product_id]\r\n            \r\n            if ix - i.quantity < 0 \r\n                check = false\r\n                msg = \"Not enough item in the store.\"\r\n            end\r\n              \r\n          \r\n          end\r\n          \r\n          if check\r\n      \r\n          for i in items\r\n            \r\n                ix = ms[i.product_id]\r\n                ix = @models[:store_item].create :product_id=>i.product_id, :store_id=>store.id, :balance=>0 unless ix\r\n                \r\n                sc = @models[:stock_card].create :order_id=>order.id, :store_item_id=>ix.id, :type=>\'out\', :quantity=>i.quantity, :lot=>i.lot, :expired_date=>i.expired_date\r\n                \r\n                ix.balance -= i.quantity\r\n                ix.save\r\n                \r\n                \r\n            end\r\n            \r\n            end\r\n  \r\n            end\r\n      \r\n            completed = check\r\n            \r\n            unless check\r\n                 flash[:warning] =  msg\r\n            end\r\n      else\r\n          \r\n      end\r\n        \r\n      if completed \r\n        order.status = \'Completed\'\r\n        order.save\r\n      else\r\n      \r\n      end\r\n       \r\n       \r\n    end\r\n    \r\n    \r\n    if params[:return]\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=<%=params[:return]%>\" />\r\n<% else %>\r\n<meta http-equiv=\"refresh\" content=\"0; url=show?id=<%=order.id%>\" />\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n',NULL,NULL,NULL,'2017-01-08 15:28:34','2017-01-08 15:28:34','commit',''),(2888,'display',1161,3,'\r\n<%\r\n   model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  @show=true\r\n  @models = get_model\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n<%\r\n    if params[:store] \r\n        \r\n        store = @models[:store].find(params[:store])\r\n        if store\r\n     \r\n        store_item = @models[:store_item].where(:store_id=>store.id,:product_id=>record.id).first    \r\n       \r\n        if store_item\r\n       \r\n        cards = @models[:stock_card].where(:store_item_id=>store_item.id).all\r\n    \r\n%>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n            <th>Timestamp</th>\r\n            <th>LOT</th>\r\n            <th>Exp</th>\r\n            <th>In</th>\r\n            <th>Out</th>\r\n            <th>Balance</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <% \r\n            balance = 0 \r\n        \r\n        for i in cards \r\n        \r\n            qin = \'\'\r\n            qout = \'\'\r\n            \r\n            if i.type==\'in\'\r\n                qin = fn i.quantity\r\n                balance += i.quantity\r\n            else\r\n                qout = fn i.quantity\r\n                balance -= i.quantity\r\n            end\r\n        %>\r\n        <tr>\r\n            <td>\r\n                <%=i.created_at%>\r\n            </td>\r\n             <td>\r\n                <%=i.lot%>\r\n            </td>\r\n             <td>\r\n                <%=i.expired_date.strftime(\"%d-%m-%Y\") if i.expired_date%>\r\n            </td>\r\n            <td>\r\n                <%=qin%>\r\n            </td>\r\n            <td>\r\n                <%=qout%>\r\n            </td>\r\n            <td>\r\n                <%=fn balance%>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n    </tbody>\r\n</table>\r\n\r\n<% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2017-01-08 17:29:04','2017-01-08 17:29:04','display',''),(2889,'commit',1033,2,'<%\r\n    \r\n    \r\n    \r\n    inventory = @context.get_project(params[:inventory])\r\n    \r\n    # inventory = @context.get_projects_by_abstract(\'erp.inventory\')[0]\r\n    \r\n    imodels = inventory.load_model\r\n  \r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    m = module_model.find(params[:id])\r\n    \r\n    patient = patient_model.find m.patient_id\r\n    models = get_model\r\n    \r\n    billing = models[:billing].find(m.module_id)\r\n    \r\n    items = models[:billing_item].find(billing.items)\r\n    \r\n    bproducts = models[:product].find(items.collect{|i| i.product_id})\r\n    \r\n    \r\n    \r\n    bp_map = {}\r\n    for i in bproducts\r\n        bp_map[i.id] = i\r\n    end\r\n    \r\n    list = []\r\n    \r\n    for i in items\r\n        p = bp_map[i.product_id]\r\n        if p and p.code !=\'\' \r\n           \r\n          ip = imodels[:product].where(:code=>p.code).first\r\n           \r\n          if ip\r\n              list << [i.quantity, ip.id]\r\n          end\r\n            \r\n        end\r\n    \r\n    end\r\n    \r\n    \r\nif request.post?\r\n    \r\n    if list.size > 0 \r\n    \r\n        items = []\r\n        \r\n        for i in list\r\n        \r\n        items << imodels[:order_item].create(:quantity=>i[0], :product_id=>i[1])\r\n        \r\n        end\r\n        \r\n        store_id = nil\r\n        \r\n        unless store_id\r\n        store = imodels[:store].first\r\n        store_id = store.id\r\n        end\r\n    \r\n        order  = imodels[:order].create :store_id=>store_id, :items=>items.collect{|i| i.id}, :order_type=>\'sale\', :status=>\'Pending\', :ref_id=>params[:id] ,:ref2_id=>\"\\\\#{patient.hn}:\\\\#{m.ref_number}\"\r\n    \r\n    end\r\n    %>\r\n    <meta http-equiv=\"refresh\" content=\"0; url=show?id=<%=params[:id]%>\" />\r\n    <%\r\n    \r\nelse\r\n    \r\n    stores = imodels[:store].all\r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n    \r\n    <%= form_for \'order\', :url=>\'commit\' do |f| %>\r\n    \r\n    <h1>Check out records</h1>\r\n    <label>From inventory : </label>\r\n    <%= f.select \'store_id\',options_for_select(stores.collect{|i| [i.name,i.id] }) %>\r\n    <div class=\"clear\"></div>\r\n    \r\n    <%=hidden_field_tag \'id\', params[:id] %>\r\n    <%=hidden_field_tag \'inventory\', params[:inventory] %>\r\n    \r\n    <br/>\r\n    <%= f.submit \'Submit\', :class=>\'btn btn-success\' %>\r\n    <% end %>\r\n</div>\r\n</div>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2017-01-09 03:18:58','2017-01-09 03:18:58','commit',''),(2895,'display',1163,3,'\r\n<%\r\n  \r\n  models = get_model\r\n  model = models[this.table_name.to_sym]\r\n   \r\n  record = model.find(params[:id])\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   \r\n   items_list = record.items\r\n   \r\n   items = models[:order_item].find items_list\r\n   \r\n   products = models[:product].find items.collect{|i| i.product_id}\r\n   pm = {}\r\n   for i in products\r\n    pm[i.id] = i\r\n   end\r\n   \r\n   \r\n%>\r\n</p>\r\n\r\n<style>\r\n    #page {border:solid 1px; margin-left:-50px;width:810px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nv{color:blue;}\r\n</style>\r\n\r\n\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /><b style=\"margin-top:20px;font-size:1.5em\">Inventory System</b></div>\r\n\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%=thdate Time.now %> <%=Time.now.strftime(\"%H:%M\") %></p>\r\n</div>\r\n</div>\r\n\r\n<%\r\n    color = \'red\'\r\n    color = \'blue\' if record.status==\'Completed\'\r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n        <div class=\"span3\">\r\n                Order Type : <v><%=render_value \'order_type\' %></v>\r\n        </div>\r\n        <div class=\"span3\">\r\n                Status : <v style=\"color:<%=color%>\"><%=render_value \'status\' %></v>\r\n        </div>\r\n        <div class=\"span3\">\r\n                Store : <v><%=render_value \'store_id\' %></v>\r\n        </div>\r\n        <div class=\"span3\">\r\n                Ref ID : <v><%=render_value \'ref_id\' %></v>\r\n        </div>\r\n        \r\n    </div><br/>\r\n    \r\n<div id=\"page\">\r\n<br/>\r\n\r\n    <table class=\"table\">\r\n        <thead>\r\n            <tr>\r\n                <th>No.</th><th>Description</th><th>Code</th><th>Manufacture</th><th>Lot</th><th>Price</th><th>Qty</th><th>Amount</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n        <% \r\n            total = 0 \r\n        \r\n            items.each_with_index do |i,index| \r\n                \r\n            p = pm[i.product_id]\r\n            line_amount = 0 \r\n            line_amount = p.price.to_f * i.quantity if p.price and i.quantity \r\n            \r\n            total += line_amount\r\n        %>\r\n            <tr><td><%=index+1%>.</td>\r\n                <td><%=p.name %></td>\r\n                <td><%=p.code %></td>\r\n                 <td><%=p.manufacture %></td>\r\n                <td><%=i.lot %></td>\r\n                <td><%=fm p.price %></td>\r\n                <td><%=i.quantity %></td>\r\n                <td><%=fm line_amount %></td>\r\n            </tr>\r\n        <% end %>\r\n            <tr>\r\n                <td colspan=\"6\">&nbsp;</td>\r\n                <td >Sub total</td>\r\n                <td ><%= fm total %></td>\r\n            </tr>\r\n\r\n        </tbody>\r\n    </table>\r\n</div>\r\n\r\n\r\n',NULL,NULL,NULL,'2017-01-11 12:10:18','2017-01-11 12:10:18','display',''),(2896,'print',1029,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n	# id of operative note\r\n	\r\n	models  = @models\r\n	pm = @module_model.find(params[:id])\r\n	colono_id = pm.module_id\r\n	record = models[:vf_record].find(colono_id)\r\n	@record = record\r\n	@document = get_document this.document_name\r\n	\r\n	\r\n	def get_render_value(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return \'-\'\r\n	    else\r\n	        return render_value(f.to_s)\r\n	    end\r\n	end\r\n	\r\n	def get_value(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return \'-\'\r\n	    else\r\n	        return @record[f]\r\n	    end\r\n	end\r\n	\r\n	def is_exist(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return false\r\n	    else\r\n	        return true\r\n	    end\r\n	end\r\n	\r\n	\r\n	endoscopist_1 = render_value(\'surgeon_1\')\r\n	endoscopist_2 = render_value(\'endoscopist_2\')\r\n	\r\n	if @patient \r\n	    patient = @patient\r\n	    date = pm.created_at.to_datetime\r\n	    birth_date = patient.birth_date \r\n	    year = month = day = \'0\'\r\n	    if date and birth_date\r\n	        t = date-birth_date    \r\n	        year = (t/365).to_i\r\n	        t%=365\r\n	        month = (t/30).to_i\r\n	        t%=30\r\n	        day = t.to_i\r\n	    end\r\n	end \r\n%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>PRINT</title>\r\n	</head>\r\n	<style type=\"text/css\" media=\"all\">\r\n		html { }\r\n		#page {border:solid 1px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n		#head { width:100%; height:140px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-size: 1.5em; margin: .83em 0 }\r\n		h3              { font-size: 1.17em; margin: 1em 0 }\r\n		p {color:#666;}\r\n		h4, p,\r\n		blockquote, ul,\r\n		form,\r\n		ol, dl          { margin: 0.5em; }\r\n		h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n		h6              { font-size: .67em; margin: 2.33em 0 }\r\n		h4 { font-size:14pt; color:#333; height:16px;}\r\n		blockquote      { margin-left: 40px; margin-right: 40px }\r\n		i, cite, em,\r\n		var, address    { font-style: italic }\r\n		pre, tt, code,\r\n		kbd, samp       {  font-size:14px; }\r\n		pre             {margin:0;margin-left:1em; color:#666}\r\n		big             { font-size: 1.17em }\r\n		v {color:#2561cD;}\r\n		small, sub, sup { font-size: .83em }\r\n		ol, ul, dd      { margin-left: 40px }\r\n		ol              { list-style-type: decimal }\r\n		ol ul, ul ol,\r\n		ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n		.clear{clear:both;}\r\n		@media print {\r\n		@page         { wi