(\'locker\')\r\n	\r\n	\r\n	\r\n	date = Time.now.strftime(\"%d/%m/%Y\")\r\n	time = Time.now.strftime(\"%H:%M\")\r\n	\r\n	# date = params[:date] if params[:date]\r\n	# time = params[:time] if params[:time]\r\n	\r\n	%> \r\n<%# params[:date] %>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n				<div style=\"border:0px solid\">\r\n					<div class=\"document-border\" style=\"border:0px solid\">\r\n						<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n						<%\r\n							model = get_model(this.table_name)\r\n							\r\n							\r\n							if request.post? \r\n							    m = nil\r\n							        p_date = params[:record][:date]\r\n							        \r\n							        m_date = Date.to_mongo(p_date)\r\n							        \r\n							        a_ids   = @models[:appointment].where(:date=>m_date).all.collect{|i| i.id.to_s}\r\n							     #   m_mod = @module_model.where(:module_id=>a_ids, :patient_id=>params[:patient_id]).first\r\n							        m_mod = nil\r\n							        \r\n							        if m_mod\r\n							            flash[:notice]=\"Appointment exist.\"\r\n							            m = m_mod\r\n							        else\r\n							            flash[:notice]=\"New record has been created\"\r\n							            doc = get_document this.document_name\r\n    							        record = doc.record_create(model,params)\r\n    							        m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n							        end\r\n\r\n%>\r\n<br/>\r\n<h3><%= flash[:notice] %></h3>\r\n<br/>\r\n\r\n						<script type=\"text/javascript\">\r\n							<% if  @appointment %>\r\n							//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\n							window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n							\r\n							<% else %>\r\n							//window.location = \"../Home/index\"\r\n							<% end %>\r\n							\r\n							window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n							\r\n							\r\n						</script>\r\n						<%\r\n							else  \r\n							\r\n							  if params[:data]\r\n							  record = model.new params[:data] \r\n							  else\r\n							  record = model.new \r\n							  end\r\n							\r\n							  \r\n							%>\r\n						<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n						<%= hidden_field_tag :return, return_url if params[:return] %>\r\n						<%\r\n							fid = 0\r\n							name = \'patient_id\'\r\n							value = params[:patient_id]\r\n							value = params[:id] if params[:id]\r\n							ref_number = @next_id\r\n							ref_number = params[:ref_number] if params[:ref_number]\r\n							\r\n							%>\r\n						<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n							<div class=\"modal-header\">\r\n								<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n								<h3>Select Patient</h3>\r\n							</div>\r\n							<div class=\"modal-body\">\r\n								<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n									<table id=\"search-panel\" style=\"width:100%\" >\r\n										<tr>\r\n											<td align=\'center\' style=\"border:0px solid\">\r\n												Patient : <%= text_field_tag \'\',\'\',:id=>\"search-\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n												<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n												<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %>\r\n											</td>\r\n										</tr>\r\n									</table>\r\n								</div>\r\n								<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n									<br/>\r\n									Loading..\r\n								</div>\r\n							</div>\r\n						</div>\r\n						<div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n							Ref : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n							<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\n							Patient : \r\n							<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n							<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n							Date : <%= text_field_tag \'date\',date  ,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\n							Time : <%= text_field_tag \'time\',time,:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n						</div>\r\n						<div id=\'patient\'></div>\r\n						<script>\r\n							$(\"#record-time\").kendoTimePicker({\r\n							value: \'<%= time %>\',\r\n							interval: 10\r\n							});\r\n							$(\"#record-date\").kendoDatePicker({\r\n							  value: \'<%= date %>\',\r\n							});\r\n							\r\n							$(\"#ref-record\").kendoAutoComplete();\r\n							$(\"#<%=\"search-\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n							\r\n							function doSearch(){\r\n							$(\'#search-result\').css(\"display\", \"block\");\r\n							url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n							   url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n							   url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n							$.ajax({\r\n							url: url,\r\n							success: function(data){\r\n							$(\'#search-result\').html(data);  \r\n							}\r\n							});\r\n							   \r\n							}\r\n							function doClose(){\r\n							  \r\n							$(\'#SelectPatient\').hide();\r\n							$(\".modal-backdrop\").hide(\'fade\');\r\n							\r\n							}\r\n							\r\n							\r\n							\r\n							function doSelect(value){\r\n							$(\'#<%=fid%>\').val(value);\r\n							   \r\n							   url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n							url += \'&id=\'+value\r\n							   url += \"&return=\\#{CGI::escape(request.fullpath)}\"\r\n							   \r\n							$.ajax({\r\n							url: url,\r\n							success: function(data){\r\n							     $(\'#patient\').html(data);  \r\n							     $(\'#SelectPatient\').hide();\r\n							     $(\".modal-backdrop\").hide(\'fade\');\r\n							}\r\n							});\r\n							   \r\n							}\r\n							\r\n							\r\n							\r\n							\r\n							\r\n							$(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n							if(event.keyCode == 13) {\r\n							doSearch();\r\n							 event.preventDefault();\r\n							 return false;\r\n							}else{\r\n							\r\n							$(\'#search-result\').html(\'Loading..\')\r\n							}\r\n							});\r\n							\r\n							<% if params[:patient_id] %>\r\n							$(\'#search-result\').css(\"display\", \"block\");\r\n							doSelect(\'<%=params[:patient_id]%>\')    \r\n							<% else %>\r\n							\r\n							$(\'#SelectPatient\').modal({\r\n							           show: true, \r\n							           backdrop: \'static\',\r\n							           keyboard: true\r\n							})\r\n							\r\n							     \r\n							<% end %>\r\n							\r\n							\r\n						</script>\r\n						<%\r\n							params[:form] = {}\r\n							params[:form][:model] = model\r\n							params[:form][:form] = f\r\n							params[:form][:record] = record\r\n							\r\n							\r\n							\r\n							%>\r\n						<p>\r\n							<%= this.form.html_safe %>\r\n						</p>\r\n						<br/>\r\n						<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n						<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n						<% end %>\r\n						<span style=\"color:green\"><%=flash[:notice]%></span>\r\n						<% end %>\r\n					</div>\r\n				</div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<script>\r\n	var validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n	$(\"#record-submit\").click(function() {\r\n	\r\n	if (!validator.validate()||$(\'#0\').val()==\"\") {\r\n	alert(\'Please fill all information\');\r\n	if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\n	return false;\r\n	\r\n	}else{\r\n	    return true;\r\n	    if(confirm(\'Are you sure?\')==true){\r\n	        return true;\r\n	    }\r\n	    return false;\r\n	}\r\n	});\r\n</script>',NULL,NULL,NULL,'2017-01-24 08:05:14','2017-01-24 08:05:14','create',''),(2901,'dev',851,3,'<%\r\n    if params[:dev] or request.post?\r\n        res = {}\r\n        cur_year = Time.now.strftime(\"%y\").to_i + 43\r\n        r = params[:record]\r\n        \r\n        pat = get_model[:patient].where(:public_id=>r[:public_id]).first\r\n        if pat.nil?\r\n        \r\n            pat = get_model[:patient].last\r\n            pat_hn = pat[:hn]\r\n            new_hn = \"000001/\\\\#{cur_year}\"\r\n            tmp_hn = \"\"\r\n            \r\n            if pat_hn.index(\'/\')\r\n                tmp_hn = pat_hn.split(\'/\')[0].to_i + 1\r\n            else\r\n                tmp_hn = pat_hn.to_i + 1\r\n            end\r\n            new_hn = \"\\\\#{tmp_hn}/\\\\#{cur_year}\"\r\n            r[:hn] = new_hn\r\n            \r\n            new_pat = get_model[:patient].create r\r\n            \r\n            res[:YY] = cur_year\r\n            res[:pat] = new_pat\r\n            res[:new_hn] = new_hn\r\n            res[:params] = params\r\n            res[:message] = \"New Patient Created.\"\r\n        else\r\n            res[:pat] = pat\r\n            res[:message] = \"Existing Patient HN:\\\\#{pat[:hn]}\"\r\n        end\r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2017-01-24 08:12:59','2017-01-24 08:12:59','dev','*'),(2902,'index',851,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>params[:opt] do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2017-01-24 08:29:09','2017-01-24 08:29:09','index',''),(2903,'print_appointment',1152,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n provider = providers[ap.provider.to_s] if providers\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year} ปี \\\\#{month} เดือน \\\\#{day} วัน\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>pro[ap.procedure],\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>(provider.nil? or provider==\'\') ? \'-\' : provider.name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'age\'=>age,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\nlist = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงรายการผู้ป่วย\r\n<span style=\"float:right\">ประจำวันที่ \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th>Type</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>HN</th>\r\n    <th >อายุ</th>\r\n    <th>เลขประชาชน</th>\r\n    <th>Indication</th>\r\n    <th>Procedure</th>\r\n    <th>Provider</th>\r\n    <th>Tel.</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n  <% list.each_with_index do |i,index|  %>\r\n    <tr style=\"height:110px\">\r\n    <td><%=index+1%>.</td>\r\n    <td><%=i[\'visit_type\']%></td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%></td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'age\']%></td>\r\n    <td><%=i[\'public_id\']%></td>\r\n    <td><%=i[\'indication\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    <td><%=i[\'provider\']%></td>\r\n    <td><%=i[\'tel\']%></td>\r\n    </tr>\r\n    <% end %>\r\n</tbody>\r\n  </table><br/>\r\n  </div>\r\n  </div></div></div></div></div>\r\n</body>\r\n</html>\r\n<% end %>\r\n',NULL,NULL,NULL,'2017-01-25 01:47:06','2017-01-25 01:47:06','print_appointment',''),(2904,'patient_record',878,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\n	body { min-width:0px; }\r\n	.gebo-fixed { background-color:#f5f5f5; }\r\n	#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Patient Records\r\n				<div class=\"pull-right\">\r\n					<%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n				</div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<%\r\n					ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n					ehr_models = ehr.get_model\r\n					patient_model = ehr_models[:patient]\r\n					patient_module_model = ehr_models[:patient_module]\r\n					\r\n					emr_models = get_model\r\n					ap = emr_models[:appointment].find(params[:id])\r\n					pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n					locker_model = emr_models[:locker]\r\n					if params[:reset_lock]\r\n					    l = locker_model.find(params[:reset_lock])\r\n					    l.destroy if l\r\n					end\r\n					#locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n					#i.destroy if i\r\n					#end\r\n					 \r\n					\r\n					\r\n					if pm\r\n					\r\n					if  params[:schema_patient_module]\r\n					   pm.update_attributes params[:schema_patient_module]\r\n					end\r\n					\r\n					if params[:provider_id]\r\n					  ap.update_attributes :provider=>params[:provider_id]\r\n					   ap = emr_models[:appointment].find(params[:id])\r\n					 end\r\n					\r\n					# find provider\r\n					provider = emr_models[:provider].find(ap.provider.to_s)\r\n					\r\n					# find patient\r\n					patient = patient_model.find(pm.patient_id)\r\n					\r\n					params[:patient]=patient\r\n					params[:patient_module]=pm\r\n					\r\n					# s = Service.get(\'ehr.emr.EmrHelper\')\r\n					#    obj = s.load context\r\n					\r\n					providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n					\r\n					%>\r\n				<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\' and i.name!=\'billing\'}.compact %>\r\n				<div style=\"border:0px solid\">\r\n					<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n						<%# render :inline=>obj.show_patient %>\r\n						<div id=\"patient\">\r\n							...\r\n						</div>\r\n						<script>\r\n							<%\r\n								url = \'../../www/Patient/search_result?\'\r\n								url += \'&id=\'+patient.id.to_s\r\n								%>      \r\n							        $.ajax({\r\n							    	  url: \'<%=url.html_safe%>\',\r\n									 success: function(data){\r\n							          $(\'#patient\').html(data);  \r\n									  }\r\n									});\r\n						</script>\r\n						<br/>\r\n						<%\r\n							previous = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\n							history = []\r\n							x = previous[0..7]\r\n							last = []\r\n							last = x.compact if x\r\n							history = []\r\n							y = previous[8..-1]\r\n							history = y.compact if y and  previous.size>5\r\n							                                     \r\n							current = time_ago_in_words(ap.date)\r\n							current_date = ap.date.strftime(\"%d-%m-%y\")\r\n							current = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n							\r\n							%>\r\n						<div class=\"clear\"></div>\r\n						<div class=\"tabbable\">\r\n							<ul class=\"nav nav-tabs\">\r\n								<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n								<%\r\n									for i in last \r\n									%>\r\n								<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n								<% end %>\r\n								<% if history.size>5 %>\r\n								<li class=\"dropdown\">\r\n									<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n									<ul class=\"dropdown-menu\">\r\n										<% for j in history %>\r\n										<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n										<% end %>\r\n										<li class=\"divider\"></li>\r\n									</ul>\r\n								</li>\r\n								<% end %>\r\n							</ul>\r\n							<div class=\"tab-content\">\r\n								<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n									<h4><%= @current_project.title %> Records</h4>\r\n									<hr/>\r\n									<table class=\"table table-striped table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th></th>\r\n												<th>Forms</th>\r\n												<th>Records</th>\r\n												<th></th>\r\n											</tr>\r\n										</thead>\r\n										<%\r\n											groups = this.config\r\n											if true\r\n											for g in groups \r\n											   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n											%>\r\n										<tr>\r\n											<td colspan=\"4\"><%=g[:name]%></td>\r\n										</tr>\r\n										<% services.each_with_index do |s,index|\r\n											module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n											records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n											%>\r\n										<tr>\r\n											<td><%= index+1 %>. </td>\r\n											<td> <%= s.title %></td>\r\n											<td align=\"center\"><% for i in records %>\r\n												<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n												<%\r\n													if i[:created_at].strftime(\'%d%m%Y\') == Time.now.strftime(\'%d%m%Y\') or session[:admin]\r\n													%>\r\n												<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-info btn-mini\', :style=>\'margin-top:-5px\' %>\r\n												<%= link_to \"x\", \"../\\\\#{s.name.camelize}/destroy?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-danger btn-mini\', :style=>\'margin-top:-5px\', :data=>{:confirm=>\'Are you sure ?\'} %>\r\n												<%\r\n													end\r\n													%>\r\n												<% end %>\r\n											</td>\r\n											<td>\r\n												<%  if records.size==0 %>\r\n												<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n												<% else %>\r\n												<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n												<% end %>\r\n												<% \r\n													# locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n													\r\n													\r\n													locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n													if locker\r\n													text = \'\'\r\n													case locker.status\r\n													when \'create\'\r\n													    text=\'Creating..\'\r\n													when \'edit\'\r\n													    text=\'Editing..\'\r\n													end\r\n													user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n													\r\n													\r\n													%>\r\n												<%\r\n													user_name = user.login.split(\"@\")[0]\r\n													user_name =  solution_user.name  if solution_user\r\n													\r\n													text += \" by \" + user_name if user_name\r\n													#   text += locker.session\r\n													%>\r\n												<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n												<% end %>\r\n											</td>\r\n											<% end %>\r\n										</tr>\r\n										<% end %>\r\n										<% end %>\r\n									</table>\r\n								</div>\r\n								<% for i in previous \r\n									pm = i\r\n									%>\r\n								<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n									<h4><%= @current_project.title %> Recrods</h4>\r\n									<hr/>\r\n									<table class=\"table table-striped table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th></th>\r\n												<th>Forms</th>\r\n												<th>Records</th>\r\n												<th></th>\r\n											</tr>\r\n										</thead>\r\n										<%\r\n											groups = this.config\r\n											if true\r\n											for g in groups \r\n											   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n											%>\r\n										<tr>\r\n											<td colspan=\"4\"><%=g[:name]%></td>\r\n										</tr>\r\n										<% services.each_with_index do |s,index|\r\n											module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n											records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n											%>\r\n										<tr>\r\n											<td><%= index+1 %>. </td>\r\n											<td> <%= s.title %></td>\r\n											<td align=\"center\"><% for i in records %>\r\n												<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n											    <%\r\n													if i[:created_at].strftime(\'%d%m%Y\') == Time.now.strftime(\'%d%m%Y\') or session[:admin]\r\n													%>\r\n												<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-info btn-mini\', :style=>\'margin-top:-5px\' %>\r\n												<%= link_to \"x\", \"../\\\\#{s.name.camelize}/destroy?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-danger btn-mini\', :style=>\'margin-top:-5px\', :data=>{:confirm=>\'Are you sure ?\'} %>\r\n												<%\r\n													end\r\n													%>\r\n												<% end %>\r\n											</td>\r\n											<td>\r\n												<%  if records.size==0 %>\r\n												<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n												<% else %>\r\n<%\r\n												# if !f_pre and s.title.to_s.downcase.include? \'pre\'\r\n												if false\r\n%>\r\n<%= link_to \'Copy\', \"\\\\#{request.fullpath}&val=\\\\#{i[:module_id]}&parent_id=\\\\#{m_par}&patient_id=\\\\#{patient.id}\".html_safe, :class=>\'btn btn-warning\' %>\r\n<%\r\n        end\r\n%>\r\n												<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n												<% end %>\r\n												<br/>\r\n											</td>\r\n											<% end %>\r\n										</tr>\r\n										<% end %>\r\n										<% end %>\r\n									</table>\r\n								</div>\r\n								<% end %>\r\n							</div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n				<% else %>\r\n				Data missing\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<script>\r\n	$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>',NULL,NULL,NULL,'2017-01-30 06:56:13','2017-01-30 06:56:13','patient_record',''),(2905,'print_partial',1133,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm_core/banner.png\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize if @current_user %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3><%=this.table_name.to_s.humanize%></h3>\r\n<%= this.display.html_safe %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div class=\"hideprint\">\r\n<%= link_to \'Back\', url(\'index\') %>\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2017-01-31 07:31:35','2017-01-31 07:31:35','print_partial','*'),(2906,'print',1133,3,'<%\r\n    if params[:service] == \'PreOperative\' or params[:service] == \'PostOperative\' or params[:service] == \'IntraOperative\' or params[:service] == \'PreOperativeVisit\'\r\n%>\r\n<%= this.print_dev.html_safe %>\r\n<%  else %>\r\n<%= this.print_partial.html_safe %>\r\n<%  end %>\r\n<% if @current_role!=\'developer\' %>\r\n<script>\r\n    var millisecondsToWait = 2000;\r\n    setTimeout(function() {\r\n        window.print();\r\n    }, millisecondsToWait);\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2017-01-31 07:31:46','2017-01-31 07:31:46','print',''),(2907,'print_dev',1133,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    sample = false\r\n    if params[:sample]\r\n        sample = true\r\n    end\r\n    \r\n    return_url = \'../Home/index\'\r\n    if params[:return]\r\n        return_url = params[:return]\r\n    end\r\n    \r\n    \r\n    def get_doc_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].nil? ? \'\' : x[1].strip\r\n                    tmp[:list] << x[1].nil? ? \'\' : x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    def get_value f, fdoc, val\r\n        x = fdoc[f.to_sym]\r\n        v = val\r\n        h = x.to_h\r\n        if h.has_key? :pair and !v.nil? and v != \'\'\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n        elsif h[:field_type] == \'select_time\' and !v.nil? and v != \'\'\r\n            v = val.strftime(\'%H:%M\')\r\n        elsif h[:field_type] == \'relation_one\'\r\n            pr = eval(\"{\\\\#{h[:params]}}\")\r\n            dd = pr[:relation][:document]\r\n            v = get_model[dd].find(v)\r\n            v = v[:name] if v\r\n        end\r\n        return v\r\n    end\r\n    \r\n    @obj = {}\r\n    def val f, doc, default = \'N/A\'\r\n        doc = doc.to_sym\r\n        f = f.to_sym\r\n        if @obj.has_key? doc\r\n            # get_value(:premed, obj[:pre_operative_visit][:df], obj[:pre_operative_visit][:rec][:premed])\r\n            rt = get_value(f, @obj[doc][:df], @obj[doc][:rec][f])\r\n            return (rt.nil? or rt==\'\') ? default : rt\r\n        else\r\n            return default\r\n        end\r\n    end\r\n    \r\n    def lab f, doc\r\n        doc = doc.to_sym\r\n        f = f.to_sym\r\n        if @obj.has_key? doc\r\n            \r\n        end\r\n    end\r\n    \r\n    \r\n    \r\n    # query model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_model = ehr.load_model\r\n    \r\n    m_pat = ehr_model[:patient]\r\n    m_pat_mod = ehr_model[:patient_module]\r\n    \r\n    r_pat_mod = m_pat_mod.find(params[:id])\r\n    r_pat = m_pat.find(r_pat_mod[:patient_id])\r\n    \r\n    r_par = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id]).all\r\n    # pre-op visit\r\n    pov = {}\r\n    # pre-op\r\n    pop = {}\r\n    # intra-op\r\n    iop = {}\r\n    # post-op\r\n    pos = {}\r\n    # assign to each object\r\n    obj = {}\r\n    r_par.each do |i|\r\n        d  = i[:module_name].split(\'#\')[1].to_sym\r\n        id = i[:module_id].to_s \r\n        obj[d] = {}\r\n        obj[d][:df]  = get_doc_field(d.to_s)\r\n        obj[d][:rec] = get_model[d].find(id)\r\n    end\r\n    @obj = obj\r\n    \r\n    gender = \'NA\'\r\n    if r_pat.gender == \'1\'\r\n        gender = \'Male\'\r\n    elsif r_pat.gender == \'2\'\r\n        gender = \'Female\'\r\n    end\r\n    \r\n    today = Date.today\r\n    d = !r_pat[:birth_date].nil? ? Date.new(today.year, r_pat[:birth_date].month,  1) : today\r\n    age = !r_pat[:birth_date].nil? ? d.year - r_pat[:birth_date].year - (d > today ? 1 : 0) : \'N/A\'\r\n    pat_name = \"\\\\#{r_pat[:prefix_name]}\\\\#{r_pat[:first_name]}&nbsp;&nbsp;&nbsp;\\\\#{r_pat[:last_name]}\".html_safe\r\n\r\n    # This model\r\n    model = get_model\r\n    this_mod = get_model(this.table_name)\r\n    this_rec = this_mod.find(r_pat_mod[:module_id])\r\n    this_doc = get_document(this.document_name)\r\n    \r\n    # check pre-op exist ?\r\n    x_pre_op = m_pat_mod.where(:parent_id=>r_pat_mod[:parent_id], :module_name=>\"\\\\#{@current_project.name}#pre_op\").first\r\n    r_pre_op = nil\r\n    if x_pre_op\r\n        r_pre_op = get_model[:pre_op].find(x_pre_op[:module_id])\r\n    end\r\n    \r\n    # map\r\n    # map value\r\n    map_provider = {}\r\n    map_provider[\'\']  = \'N/A\'\r\n    map_provider[\'0\'] = \'N/A\'\r\n    map_provider[nil] = \'N/A\'\r\n\r\n    for i in model[:provider].all do\r\n        map_provider[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    map_ind = {}\r\n    map_ind[\'\']  = \'N/A\'\r\n    map_ind[nil] = \'N/A\'\r\n    model[:indication].all.each do |i|\r\n        map_ind[i.id.to_s] = i[:name]\r\n    end\r\n    \r\n    room = get_model[:room].all.group_by{|i| i[:_id].to_s}\r\n    \r\n    @record = this_rec\r\n    @document = this_doc\r\n    \r\n    \r\n    r_parent = m_pat_mod.find(r_pat_mod[:parent_id])\r\n    r_app = model[:appointment].find(r_parent[:module_id])\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n\r\n    if sample\r\n        res = {}\r\n        res[:id] = params[:id]\r\n        res[:pat_mod] = r_pat_mod\r\n        res[:pat] = r_pat\r\n        \r\n%>\r\n<%= res.to_json.html_safe %>\r\n<%\r\n    else\r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px; line-height:20px;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {\r\n    /*color:#666;*/\r\n    line-height:12px;\r\n}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; margin-left:70px; margin-right:10px; }\r\n /* blockquote, */\r\n /*.wrapper{ width:960px;margin-left:auto;margin-right:auto;} */\r\n    body {-webkit-print-color-adjust: exact;}\r\n    .next-page {page-break-after:always;}\r\n}\r\n\r\n#box{\r\n    width:300px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:250px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    height:225px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n    .tab { margin-left: 20px; }\r\n    .intro {\r\n        font-weight:bold;\r\n        width : 170px;\r\n        /*display: inline-block;*/\r\n    }\r\n    v {color:#2561cD};\r\n    cen {\r\n        text-align: center;\r\n    }\r\n\r\n</style>\r\n<%# stylesheet_link_tag    \"application\"  %>\r\n<script>\r\n    document.title = \"<%= r_pat.hn %> - <%= r_pat.prefix_name %> <%= r_pat.first_name %> <%= r_pat.last_name %> - PRINT\"\r\n</script>\r\n<body>\r\n	<div class=\"wrapper\" >\r\n		<div id=\"head\">\r\n<%\r\n    app_logo = @current_project.get_setting(\'logo_report_path\')\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n			<div style=\'float:left\'>\r\n			    <span style=\"margin-top: 30px;display: block;font-size: 2em;font-weight: bold;margin-left: 20px;\">PERIOPERATIVE NURSING RECORD</span>\r\n			</div>\r\n			<div id=\"logoright\" ><a href=\"../Home/index\"><img src=\'<%=app_logo%>\' height=\"55px\" style=\"float:right;margin-top:15px;margin-right:20px\" /></a></div>\r\n		</div>\r\n		<br />\r\n		<div id=\"page\" style=\'min-height:960px\'>\r\n		<!-- Title Section -->\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n				<tr>\r\n					<td > \r\n						<table width=\"70%\">\r\n							<tr>\r\n							    <td width=\'40%\' style=\'vertical-align:top\'>\r\n							        <span class=\"intro\">Operation Date : </span> <v><%= r_app[:date].strftime(\'%d-%m-%Y\') if r_app[:date] %></v> <br/> \r\n							        <span class=\"intro\">OR Room. : </span> <v><%= room[r_app[:room]].nil? ? \'-\' : room[r_app[:room]][0][:name] %></v> <br/>\r\n							        \r\n							        <%\r\n							            if r_app[:visit_base]==\'OPD\'\r\n							        %>\r\n							        <span class=\"intro\">Clinic : </span> <v><%= r_app[:clinic] %></v><br/>\r\n							        <%  elsif r_app[:visit_base]==\'IPD\' %>\r\n							        <span class=\"intro\">Ward : </span> <v><%= (r_app[:ward].nil? or r_app[:ward]==\'\') ? \'-\' : get_model[:ward].find(r_app[:ward])[:name] %></v><br/>\r\n							        <%  end %>\r\n							        <span class=\"intro\">Case type : </span> <v><%= r_app[:visit_type] %></v><br/>\r\n							        \r\n								</td>\r\n								<td style=\'vertical-align:top\'>\r\n									<span class=\'intro\'>HN : </span> <v><%=r_pat.hn%></v> <br/>\r\n									<span class=\' intro\'>Name : </span> <v><%= pat_name %></v><br/>\r\n									<span class=\' intro\'> Age : </span> <v><%= age %> </v>yr  \r\n									<span class=\'tab intro\'>Gender : </span> <v><%= gender %></v>\r\n								</td>\r\n							</tr>\r\n							<!--<tr>-->\r\n							<!--    <td colspan=\'2\'>&nbsp;</td>-->\r\n							<!--</tr>-->\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n            <hr/>\r\n			<div style=\"display:block;\">\r\n			<!-- Main Content -->\r\n			<%\r\n			    fm = :pre_operative_visit\r\n			%>\r\n			   <!-- Pre-op Visit -->\r\n				<table width=\"100%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left;\">\r\n				    <tr>\r\n				        <td colspan=2 style=\'background:#ccc\'><%# get_value(:premed, obj[:pre_operative_visit][:df], obj[:pre_operative_visit][:rec][:premed]) %>\r\n			                <h3>Pre-Op Visit</h3>\r\n				        </td>\r\n				    </tr>\r\n				    <tr style=\'vertical-align:top\'>\r\n				        <td width=\'40%\'>\r\n				            <b>Pre-Op Visit : </b> <v><%= val(:pre_op_visit, fm) %></v><br/>\r\n				            <span class=\'tab intro\'>Op. History : </span> <v><%= val(:op_history, fm) %></v><br/>\r\n				            <span class=\'tab intro\'>Illnesses History : </span> <v><%= val(:illnesses_history, fm) %></v><br/>\r\n				            <span class=\'tab intro\'>Limitation : </span> <v><%= val(:limitation, fm) %></v><br/>\r\n				            <span class=\'tab intro\'>Anxiety : </span> <v><%= val(:anxiety, fm) %></v><br/>\r\n				        </td>\r\n				        <td><%# get_value(:premed, obj[:pre_operative_visit][:df], obj[:pre_operative_visit][:rec][:premed]) %>\r\n			                <b>Time Pt. Arrived to OR : </b> <v><%= val(:time_pt_arrived_to_or, fm) %></v><br/>\r\n			                <span class=\'tab intro\'>NPO : </span> <v><%= val(:npo, fm) %></v> / since : <v><%= val(:npo_yes, fm, \'-\') %></v><br/>\r\n			                <span class=\'tab intro\'>Premed : </span> <v><%= val(:premed, fm) %></v> / detail : <v><%= val(:premed_yes, fm, \'-\') %></v><br/>\r\n			                <span class=\'tab intro\'>Antibiotic prehylaxis : </span> <v><%= val(:antibiotic_prehylaxis, fm) %></v> / detail : <v><%= val(:anitbiotic_prophylaxis_yes, fm, \'-\') %></v><br/>\r\n			                <span class=\'tab intro\'>Lab : </span> HIV : <v><%= val(:lab_hiv, fm) %></v> , HBsAg : <v><%= val(:hbsag, fm) %></v> <br/>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td colspan=2 style=\'border:#ccc\'><%# get_value(:premed, obj[:pre_operative_visit][:df], obj[:pre_operative_visit][:rec][:premed]) %>\r\n			                <b class=\'tab\'>> Done by : </b> <v><%= val(:done_by, fm) %> / <%= val(:date, fm) %> / <%= val(:time, fm) %></v> <v></v>\r\n				        </td>\r\n				    </tr>\r\n				</table>\r\n				\r\n				<%\r\n				    fm = :pre_operative\r\n				%>\r\n				<!-- Pre-op -->\r\n				<table width=\"100%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left;\">\r\n				    <tr>\r\n    				    \r\n    				        <td colspan=\'2\' style=\'background:#ccc\'>\r\n				                <h3>1. PERIOPERATIVE NURSING RECORD </h3>\r\n				                <b>Goal : </b> SIGN IN (Identification) / Nursing Assessments\r\n    				        </td>\r\n    				    </tr>\r\n    				<tr  style=\'vertical-align:top\'>\r\n				        <td width=\'50%\'>\r\n				            \r\n				            \r\n				            <span class=\'tab intro\'>Pt. ID by : </span> <v><%= val(:pt_id_by, fm) %></v><br/>\r\n				            <span class=\'tab intro\'>Site verified : </span> <v><%= val(:site_verified, fm) %></v> / other : <%= val(:site_verified_other, fm, \'-\') %><br/>\r\n				            <span class=\'tab intro\'>Consent Signed : </span> <v><%= val(:consent_signed, fm) %></v><br/>\r\n				            <span class=\'tab intro\'>Allergy : </span> <v><%= val(:allergy, fm) %></v> / detail : <v><%= val(:allergy_detail, fm) %></v><br/>\r\n				            \r\n				            <b class=\'tab\'>> Done by : </b> <v><%= val(:pre_done_by, fm) %> / <%= val(:pre_done_date, fm) %> / <%= val(:pre_done_time, fm) %></v> <v></v>\r\n				            <br/>\r\n				            <% if val(:other_oximeter, fm, \'\') != \'\' and val(:other_difficult_airway, fm, \'\') != \'\' and val(:other_risk, fm, \'\') != \'\' %>\r\n				            <b>Other</b><br/>\r\n				            <span class=\'tab intro\'>Is pulse oximeter on Pt. and functioning? : </span> <v><%= val(:other_oximeter, fm, \'-\') %></v><br/>\r\n				            <span class=\'tab intro\'>Difficult airway or aspiration risk? : </span> <v><%= val(:other_difficult_airway, fm, \'-\') %></v><br/>\r\n				            <span class=\'tab intro\'>Risk of > 500 ml. blood loss(7ml/kg in child) : </span> <v><%= val(:other_risk, fm, \'-\') %></v><br/>\r\n				            <b class=\'tab\'>> Done by : </b> <v><%= val(:other_done_by, fm) %> / <%= val(:other_done_date, fm) %> / <%= val(:other_done_time, fm) %></v> \r\n				            <% end %>\r\n				        </td>\r\n				        <td>\r\n				            <table border=\'1px\'>\r\n				                <tr>\r\n				                    <th>Time</th>\r\n				                    <th>T ( °C)</th>\r\n				                    <th>BP (mm/Hg)</th>\r\n				                    <th>HR (min)</th>\r\n				                    <th>RR (min)</th>\r\n				                    <th>SpO2 (%)</th>\r\n				                </tr>\r\n<%\r\n    obj = get_model[:vital_sign].find(val(:vital_sign, fm, nil))\r\n    if obj\r\n        obj.each do |i|\r\n%>\r\n                                <tr>\r\n                                    <td class=\'cen\'><%= i[:time].nil? ? \'-\' : i[:time].strftime(\'%H:%M\') %></td>\r\n                                    <td class=\'cen\'><%= i[:temp] %></td>\r\n                                    <td class=\'cen\'><%= i[:bp] %></td>\r\n                                    <td class=\'cen\'><%= i[:hr] %></td>\r\n                                    <td class=\'cen\'><%= i[:rr] %></td>\r\n                                    <td class=\'cen\'><%= i[:spo2] %></td>\r\n                                </tr>\r\n<%\r\n        end\r\n    else\r\n%>\r\n                                <tr>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                </tr>\r\n<%\r\n    end\r\n%>\r\n				            </table>\r\n				            \r\n				            <span class=\' intro\'>Consciousness : </span> <v><%= val(:consciousness , fm) %></v><br/>\r\n				            <span class=\' intro\'>Respiratory Status : </span> <v><%= val(:respiratory_status , fm) %> \r\n				                <%= \"/ \\\\#{val(:o2_lmin, fm)} L/min \" if (val(:o2_lmin, fm, \'\') != \'\') %>\r\n				                <%= \"/ \\\\#{val(:respiratory_other, fm)}\" if (val(:respiratory_other, fm, \'\') != \'\') %>\r\n				                </v><br/>\r\n				            <span class=\' intro\'>Limitation : </span> <v><%= val(:pre_limitation, fm) %> \r\n				                <%= \"/ \\\\#{val(:pre_limitation_other, fm)} \" if (val(:pre_limitation_other, fm, \'\') != \'\') %>\r\n				            </v><br/>\r\n				            <% if val(:pre_note, fm, \'\') != \'\' %>\r\n				            <span class=\' intro\'>Note : </span> <v><%= val(:pre_note , fm) %></v><br/>\r\n				            <% end %>\r\n				        </td>\r\n				    </tr>\r\n<%\r\n    int = :intra_operative\r\n%>\r\n				    <tr>\r\n    				    \r\n    				        <td colspan=\'2\' style=\'background:#ccc\'>\r\n				                <h3>2. INTRAOPERATIVE NURSING RECORD </h3>\r\n				                <b>Goal : </b> TIME OUT (All Team verbally confirms and reviews patient-specific concerns)\r\n    				        </td>\r\n    				    </tr>\r\n    				<tr  style=\'vertical-align:top\'>\r\n				        <td width=\'50%\'>\r\n				            <div style=\'width:50px;float:left\' class=\'intro\'>Time : </div> \r\n				            <div style=\'width:150px;float:left\'><b>Patient In : </b><v><%= val(:patient_in, int) %> </v></div> \r\n				            <div style=\'float:left\'><b>Incision :</b> <v><%= val(:incision, int) %> </v></div> \r\n				            <br/>\r\n				            <div style=\'width:50px;float:left\' class=\'intro\'> &nbsp;</div> \r\n				            <div style=\'width:150px;float:left\'><b>Closure : </b><v><%= val(:closure, int) %> </v></div> \r\n				            <div style=\'float:left\'><b>Patient Out :</b> <v><%= val(:patient_out, int) %> </v></div> \r\n				            <br/>\r\n				            <span class=\'tab intro\'>Anesthesia type : </span> <v><%= val(:anesthesia_type , int) %> <%= \"/ \\\\#{val(:anesthesia_other, int)} \" if (val(:anesthesia_other, int, \'\') != \'\') %> </v><br/>\r\n				            <span class=\'tab intro\'>ASA score : </span> <v><%= val(:asa_score , int) %></v><br/>\r\n				            <span class=\'tab intro\'>Preoperative diag : </span> <v><%= val(:preoperative_diag , int) %></v><br/>\r\n				            <span class=\'tab intro\'>Postoperative diag : </span> <v><%= val(:postoperative_diag , int) %></v><br/>\r\n				            \r\n				            <span class=\' intro\'>Antibiotic Prophylaxis within the last 60 min : </span> <v><%= val(:antibiotic_prophylaxis_within_the_last_60_min , int) %> \r\n				                <%= \"/ \\\\#{val(:under_60, int)} \" if (val(:under_60, int, \'\') != \'\') %> \r\n				                <%= \"/ \\\\#{val(:over_60, int)} \" if (val(:over_60, int, \'\') != \'\') %>    \r\n				                </v><br/>\r\n				            <span class=\' intro\'>Mark site : </span> <v><%= val(:mark_site , int) %></v><br/>\r\n				            <span class=\' intro\'>Anticipated Critical Events to Surgeon : </span><br/>\r\n				                <% \r\n				                    chk = 0\r\n				                    if val(:what_are_the_critical_or_non_routine_step, int, \'\') != \'\' \r\n				                        chk += 1\r\n				                %>\r\n				                <span class=\'tab intro\'>- What are the critical or non routine step? : </span> <v><%= val(:what_are_the_critical_or_non_routine_step , int) %></v><br/>\r\n				                <% \r\n				                    end \r\n				                    if val(:how_long_will_the_case_take, int, \'\') != \'\'\r\n				                        chk += 1\r\n				                %>\r\n				                <span class=\'tab intro\'>- How long will the case take? : </span> <v><%= val(:how_long_will_the_case_take , int) %></v><br/>\r\n				                <%\r\n				                    end\r\n				                    if val(:what_is_anticioated_blood_loss, int, \'\') != \'\'\r\n				                        chk += 1\r\n				                %>\r\n				                <span class=\'tab intro\'>- What is anticioated blood loss? : </span> <v><%= val(:what_is_anticioated_blood_loss , int) %></v><br/>\r\n				                <%\r\n				                    end\r\n				                    if chk == 0\r\n				                %>\r\n				                <v>- N/A -</v>   <br/>\r\n				                <%  end %>\r\n				            <span class=\' intro\'>Anticipated Critical Events:To Anesthetist : </span><br/>\r\n				                <% \r\n				                    chk = 0\r\n				                    if val(:any_patient_specific_concerns, int, \'\') != \'\' \r\n				                        chk += 1\r\n				                %>\r\n				                <span class=\'tab intro\'>- Any patient-Specific Concerns? : </span> <v><%= val(:any_patient_specific_concerns , int) %></v><br/>\r\n				                <%\r\n				                    end\r\n				                    if chk == 0\r\n				                %>\r\n				                <v>- N/A -</v>   <br/>\r\n				                <%  end %>\r\n				            <span class=\' intro\'>Anticipated Critical Events:To Nurse Teams : </span><br/>\r\n				            <v class=\"tab\"><%= val(:anticipated_critical_nurse_type, int ) %></v><br/>\r\n				            <span class=\'tab intro\'>List : </span> <v><%= val(:nurse_teams_list, int, \'-\') %></v><br/>\r\n				            <span class=\'tab intro\'>Essnetial image displayed : </span> <v><%= val(:essnetial_image_displayed, int) %></v><br/>\r\n				            <span class=\'tab intro\'>DVT/PE Risk : </span> <v><%= val(:dvtpe_risk, int) %></v><br/>\r\n				            <span class=\'tab intro\'>Pneumatic compression : </span> <v><%= val(:pneumatic_compression, int) %></v><br/>\r\n				            <b class=\'tab\'>> Done by : </b> <v><%= val(:g_done_by, int) %> / <%= val(:g_rn_date, int) %> / <%= val(:g_rn_time, int) %></v> \r\n				        </td>\r\n				        <td>\r\n				            <b>Scrub Nurse</b>\r\n				            <table border=\'1px\' width=\'100%\'>\r\n				                <tr>\r\n				                    <th>No.</th>\r\n				                    <th>Name</th>\r\n				                    <th>In</th>\r\n				                    <th>Out</th>\r\n				                </tr>\r\n<%\r\n    \r\n    obj = get_model[:nurse_time].find(val(:scrub_nurse, int, nil))\r\n    if obj\r\n        @obj[:nurse_time] = {}\r\n        @obj[:nurse_time][:df] = get_doc_field(\'nurse_time\')\r\n        tob = :nurse_time\r\n        obj.each_with_index do |i, idx|\r\n            @obj[:nurse_time][:rec] = i\r\n%>\r\n                                <tr>\r\n                                    <td class=\'cen\'><%= idx + 1 %>.</td>\r\n                                    <td class=\'cen\'><%= val(:nurse, tob) %></td>\r\n                                    <td class=\'cen\'><%= val(:in, tob) %></td>\r\n                                    <td class=\'cen\'><%= val(:in, tob) %></td>\r\n                                </tr>\r\n<%\r\n        end\r\n    else\r\n%>\r\n                                <tr>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                </tr>\r\n<%\r\n    end\r\n%>				            \r\n                            </table>\r\n                            <!-- END Scrub nurse -->\r\n                            \r\n                            <!-- Circular nurse -->\r\n                            <br/>\r\n                            <b>Circular Nurse</b>\r\n				            <table border=\'1px\' width=\'100%\'>\r\n				                <tr>\r\n				                    <th>No.</th>\r\n				                    <th>Name</th>\r\n				                    <th>In</th>\r\n				                    <th>Out</th>\r\n				                </tr>\r\n<%\r\n    \r\n    obj = get_model[:nurse_time].find(val(:circular_nurse, int, nil))\r\n    if obj\r\n        @obj[:nurse_time] = {}\r\n        @obj[:nurse_time][:df] = get_doc_field(\'nurse_time\')\r\n        tob = :nurse_time\r\n        obj.each_with_index do |i, idx|\r\n            @obj[:nurse_time][:rec] = i\r\n%>\r\n                                <tr>\r\n                                    <td class=\'cen\'><%= idx + 1 %>.</td>\r\n                                    <td class=\'cen\'><%= val(:nurse, tob) %></td>\r\n                                    <td class=\'cen\'><%= val(:in, tob) %></td>\r\n                                    <td class=\'cen\'><%= val(:in, tob) %></td>\r\n                                </tr>\r\n<%\r\n        end\r\n    else\r\n%>\r\n                                <tr>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                    <td>-</td>\r\n                                </tr>\r\n<%\r\n    end\r\n%>				            \r\n                            </table>\r\n                            <!-- END Circular nurse -->\r\n                            <span class=\'tab intro\'>> Surgeon : </span> <v><%= val(:surgeon , int) %></v> / <span class=\' intro\'>> Assistant : </span> <v><%= val(:assistants , int) %></v><br/>\r\n                            <span class=\'tab intro\'>> Anestheologist : </span> <v><%= val(:anestheologist , int) %></v> / <span class=\' intro\'>> Anesth Nurse : </span> <v><%= val(:anesth_nurse , int) %></v><br/>\r\n				        </td>\r\n				    </tr>\r\n				</table>\r\n				\r\n            </div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n		\r\n        <div class=\"next-page\" style=\'page-break-after:always;\'></div>		\r\n\r\n        <div id=\"head\">\r\n<%\r\n    app_logo = @current_project.get_setting(\'logo_report_path\')\r\n    if app_logo.empty?\r\n        app_logo = \'/esm/anes/www/content/logo-emr-life.png\'\r\n    end\r\n%>\r\n			<div style=\'float:left\'>\r\n			    <span style=\"margin-top: 30px;display: block;font-size: 2em;font-weight: bold;margin-left: 20px;\">PERIOPERATIVE NURSING RECORD</span>\r\n			</div>\r\n			<div id=\"logoright\" ><a href=\"../Home/index\"><img src=\'<%=app_logo%>\' height=\"55px\" style=\"float:right;margin-top:15px;margin-right:20px\" /></a></div>\r\n		</div>\r\n		<br />\r\n        <div id=\"page\" style=\'min-height:960px\'>\r\n		<!-- Title Section -->\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n				<tr>\r\n					<td > \r\n						<table width=\"70%\">\r\n							<tr>\r\n							    <td width=\'40%\' style=\'vertical-align:top\'>\r\n							        <span class=\"intro\">Operation Date : </span> <v><%= r_app[:date].strftime(\'%d-%m-%Y\') if r_app[:date] %></v> <br/> \r\n							        <span class=\"intro\">OR Room. : </span> <v><%= room[r_app[:room]].nil? ? \'-\' : room[r_app[:room]][0][:name] %></v> <br/>\r\n							        \r\n							        <%\r\n							            if r_app[:visit_base]==\'OPD\'\r\n							        %>\r\n							        <span class=\"intro\">Clinic : </span> <v><%= r_app[:clinic] %></v><br/>\r\n							        <%  elsif r_app[:visit_base]==\'IPD\' %>\r\n							        <span class=\"intro\">Ward : </span> <v><%= (r_app[:ward].nil? or r_app[:ward]==\'\') ? \'-\' : get_model[:ward].find(r_app[:ward])[:name] %></v><br/>\r\n							        <%  end %>\r\n							        <span class=\"intro\">Case type : </span> <v><%= r_app[:visit_type] %></v><br/>\r\n							        \r\n								</td>\r\n								<td style=\'vertical-align:top\'>\r\n									<span class=\'intro\'>HN : </span> <v><%=r_pat.hn%></v> <br/>\r\n									<span class=\' intro\'>Name : </span> <v><%= pat_name %></v><br/>\r\n									<span class=\' intro\'> Age : </span> <v><%= age %> </v>yr  \r\n									<span class=\'tab intro\'>Gender : </span> <v><%= gender %></v>\r\n								</td>\r\n							</tr>\r\n							<!--<tr>-->\r\n							<!--    <td colspan=\'2\'>&nbsp;</td>-->\r\n							<!--</tr>-->\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n            <hr/>\r\n			<div style=\"display:block;\">\r\n			<!-- Main Content -->\r\n			   <!-- Pre-op Visit -->\r\n				<table width=\"100%\" cellpadding=\"5\" cellspacing=\"5\" style=\"float:left;\">\r\n				    <tr style=\'vertical-align:top\'>\r\n				        <td ><%# get_value(:premed, obj[:pre_operative_visit][:df], obj[:pre_operative_visit][:rec][:premed]) %>\r\n			                <div style=\'background:#ccc;padding:2px\'>\r\n			                    <b>Goal : </b>Asepsis maintenance \r\n			                </div>\r\n			                \r\n			                <span class=\'tab intro\'>Evaluation : </span> <v><%= val(:evaluation, int) %> <%= \"/ \\\\#{val(:evaluation_risk, int)} \" if (val(:evaluation_risk, int, \'\') != \'\') %> </v><br/>\r\n			                <span class=\'tab intro\'>Hair Clipping In OR : </span> <v><%= val(:hair_clipping_in_or, int) %> </v><br/>\r\n			                <span class=\'tab intro\'>Prep Site Skin Condition : </span> <v><%= val(:prep_site_skin_condition, int) %> <%= \"/ \\\\#{val(:prep_site_skin_other, int)} \" if (val(:prep_site_skin_other, int, \'\') != \'\') %> </v><br/>\r\n			                <span class=\'tab intro\'>Prep Solution : </span> <v><%= val(:prep_solution, int) %> </v><br/>\r\n			                <span class=\'tab intro\'>Urinary cather : </span> <v><%= val(:urinary_cather, int) %> <%= \"/ Retained Type \\\\#{val(:retained_type, int)} \" if (val(:retained_type, int, \'\') != \'\') %>  <%= \"/ Size \\\\#{val(:retained_size, int)} \" if (val(:retained_size, int, \'\') != \'\') %>  </v><br/>\r\n			                <span class=\'tab intro\'>Urine a start : </span> <v><%= val(:urine_a_start, int) %> <%= \"/ \\\\#{val(:urine_other, int)} \" if (val(:urine_other, int, \'\') != \'\') %> </v><br/>\r\n			                <b>> Inserted by : </b> <v><%= val(:asepsis_inserted_by, int) %></v>\r\n				        </td>\r\n				        <td>\r\n				            <div style=\'background:#ccc;padding:2px\'>\r\n			                    <b>Goal : </b>Patient of Position Related Injuny\r\n			                </div>\r\n				            \r\n				            <span class=\'tab intro\'>Evaluation : </span> <v><%= val(:position_relate_evaluation, int) %> <%= \"/ \\\\#{val(:position_relate_evaluation_risk, int)} \" if (val(:position_relate_evaluation_risk, int, \'\') != \'\') %> </v><br/>\r\n				            <span class=\'tab intro\'>Surgical Position : </span> <v><%= val(:injury_surgical_position, int) %> </v><br/>\r\n				            <span class=\'tab intro\'>Positioning Divices : </span> <v><%= val(:injury_surgical_position, int) %> </v><br/>\r\n				            \r\n				        </td>\r\n				    </tr>\r\n<%\r\n    pos = :post_operative\r\n%>\r\n				    <tr>\r\n				        <td colspan=\'2\' style=\'background:#ccc\'>\r\n				            <h3>3. IMMEDIATE POST-OPERATIVE EVALUATION AND NURSING DISCHARGE SUMMARY </h3>\r\n    				    </td>\r\n				    </tr>\r\n				    <tr style=\'vertical-align:top\'>\r\n				        <td width=\'50%\'>\r\n				            <span class=\'intro\'>ESU Pad Site : Skin Burn : </span> <v><%= val(:esu_pad_site_skin_burn, pos) %> </v><br/>\r\n				            <span class=\'intro\'>Remark : </span> <v><%= val(:remark, pos, \'-\') %> </v><br/>\r\n				            <% if val(:blood_loss, pos, \'\') != \'\' %>\r\n				            <span class=\'tab intro\'>Blood loss : </span> <v><%= val(:remark, pos, \'-\') %> </v> ml.<br/>\r\n				            <% end %>\r\n				            <span class=\'intro\'>Respiratory status : </span> <v><%= val(:respiratory_status, pos) %> </v><br/>\r\n				            <% if val(:o2, pos, \'\') != \'\' %>\r\n				            <span class=\'tab intro\'>O<sub>2</sub> : </span> <v><%= val(:o2, pos, \'-\') %> </v> L/min.<br/>\r\n				            <% end %>\r\n				            <span class=\'intro\'>Pt transfered to : </span> <v><%= val(:pt_transferred_to, pos) %> <%= \"/ \\\\#{val(:pt_transferred_other, pos)} \" if (val(:pt_transferred_other, pos, \'\') != \'\') %></v><br/>\r\n				        </td>\r\n				        <td>\r\n				            <span class=\'intro\'>Nurse Note : </span> <br/> <v><%= val(:nurse_note, pos).html_safe %> </v><br/>\r\n				            \r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td colspan=\'2\'>\r\n				            <span class=\'intro\'>> Cir Nurse : </span> <v><%= val(:cir_nurse, pos) %></v>\r\n				            <span class=\'intro\'>Anesth Nurse : </span> <v><%= val(:anesth_nurse, pos) %></v>/ <v><%= val(:nurse_record_date, pos) %></v> / <v><%= val(:nurse_record_time, pos) %></v>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td colspan=\'2\' style=\'background:#ccc\'>\r\n				            <b>Post operative of visit</b>\r\n				        </td>\r\n				    </tr>\r\n				    <tr>\r\n				        <td colspan=\'2\'>\r\n				            <span class=\'intro\'>Pain score : </span> <v><%= val(:pain_score, pos) %></v><br/>\r\n				            <span class=\'intro\'>Location : </span> <v><%= val(:post_op_location, pos) %></v><br/>\r\n				            <span class=\'intro\'>N & V : </span> <v><%= val(:nv, pos) %><%= \"/ \\\\#{val(:nv_yes, pos)} \" if (val(:nv_yes, pos, \'\') != \'\') %></v><br/>\r\n				            <span class=\'intro\'>Any complication : </span> <v><%= val(:any_complication, pos) %><%= \"/ \\\\#{val(:complication_detail, pos)} \" if (val(:complication_detail, pos, \'\') != \'\') %></v><br/>\r\n				            \r\n				            <span class=\'intro\'>> Done by : </span> <v><%= val(:post_op_done_by, pos) %> / <%= val(:post_op_date, pos) %> / <%= val(:post_op_time, pos) %></v>\r\n				        </td>\r\n				    </tr>\r\n				</table>\r\n				     \r\n			</div>\r\n		</div>\r\n\r\n		<!-- Footer -->\r\n		<div id=\"page\" style=\"height:60px;padding-top: 5px;\">\r\n			<strong>Name : </strong> ........................................................\r\n			<br/>\r\n			<br/>\r\n			<strong>Signature : </strong> ........................................................\r\n			<br />\r\n		</div>\r\n		<div class=\"clear\"></div>\r\n	</div>\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2017-01-31 07:45:33','2017-01-31 07:45:33','print_dev',''),(2908,'status_feed',1063,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n    <%= javascript_include_tag \"application\"  %>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>STATUS</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml {}\r\n\r\nvalue {font-size:0.9em;padding:0px;border:0px solid;}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px;  border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding:33px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#fff;font-size:25px; \r\nbackground:#000;\r\n\r\n}\r\n.wrapper{ width:95%;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:90%; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:100%;margin-left:auto;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#000;font-weight:bold;\r\n    font-size: 1em;\r\n}\r\n\r\ntable.table {\r\n    \r\n    color: #666;\r\n    font-size: 1.5em;\r\n    -moz-border-radius: 3px;\r\n    -moz-box-shadow: 0 1px 2px #d1d1d1;\r\n    -webkit-border-radius: 3px;\r\n    -webkit-box-shadow: 0 1px 2px #d1d1d1;\r\n    background: #eaebec;\r\n    border: #ccc 1px solid;\r\n    border-radius: 3px;\r\n    box-shadow: 0 1px 2px #d1d1d1;\r\n    font-family: Arial, Helvetica, sans-serif;\r\n    text-shadow: 1px 1px 0px #fff;\r\n}\r\n\r\ntable.table tr.even td {\r\n    background: #f6f6f6;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#f8f8f8), to(#f6f6f6));\r\n    background: -moz-linear-gradient(top, #f8f8f8, #f6f6f6);\r\n}\r\n\r\ntable.table th {\r\n    padding: 5px ;\r\n    font-size:0.9em;\r\n    border-bottom: 1px solid #e0e0e0; border-top: 1px solid #fafafa;\r\n    background: #ededed;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#ededed), to(#ebebeb));\r\n    background: -moz-linear-gradient(top, #ededed, #ebebeb);\r\n}\r\n\r\ntable.table th:first-child {\r\n    //padding-left: 20px;\r\n    text-align: center\r\n}\r\n\r\ntable.table a:visited {\r\n    color: #999999;\r\n    font-weight: bold;\r\n    text-decoration: none\r\n}\r\n\r\ntable.table a:active,\r\ntable.table a:hover {\r\n    color: #bd5a35;\r\n    text-decoration: underline\r\n}\r\n\r\ntable.table a:link {\r\n    color: #666;\r\n    font-weight: bold;\r\n    text-decoration: none\r\n}\r\n\r\ntable.table tr {\r\n    padding-left: 20px;\r\n    text-align: center\r\n}\r\n\r\ntable.table tr:first-child th:first-child {\r\n    -moz-border-radius-topleft: 3px;\r\n    -webkit-border-top-left-radius: 3px;\r\n    border-top-left-radius: 3px;\r\n}\r\n\r\ntable.table tr:first-child th:last-child {\r\n    -moz-border-radius-topright: 3px;\r\n    -webkit-border-top-right-radius: 3px;\r\n    border-top-right-radius: 3px;\r\n}\r\n\r\ntable.table tr:last-child td {    border-bottom: 0 }\r\n\r\ntable.table tr:last-child td:first-child {\r\n    -moz-border-radius-bottomleft: 3px;\r\n    -webkit-border-bottom-left-radius: 3px;\r\n    border-bottom-left-radius: 3px;\r\n}\r\n\r\ntable.table tr:last-child td:last-child {\r\n    -moz-border-radius-bottomright: 3px;\r\n    -webkit-border-bottom-right-radius: 3px;\r\n    border-bottom-right-radius: 3px;\r\n}\r\n\r\ntable.table tr:hover td {\r\n    \r\n    background: #f2f2f2;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#f2f2f2), to(#f0f0f0));\r\n    background: -moz-linear-gradient(top, #f2f2f2, #f0f0f0);\r\n}\r\n\r\ntable.table tr td {\r\n    \r\n    padding: 0px;\r\n    border-bottom: 1px solid #e0e0e0; border-left: 1px solid #e0e0e0; border-top: 1px solid #ffffff;\r\n    background: #fafafa;\r\n    background: -webkit-gradient(linear, left top, left bottom, from(#fbfbfb), to(#fafafa));\r\n    background: -moz-linear-gradient(top, #fbfbfb, #fafafa);\r\n    border:1px solid;\r\n}\r\n\r\ntable.table tr td:first-child {\r\n    padding-left: 20px;\r\n    border-left: 0;\r\n}\r\n\r\n\r\n.Waiting{color:#ccc}\r\n.Preparing{color:#6cc}\r\n.Processing{color:#6c6}\r\n.Recovering{color:#cc6}\r\n.Completed{color:blue}\r\n\r\n    \r\n    \r\n</style>\r\n<body >\r\n\r\n<div class=\"wrapper\">\r\n\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\" style=\"width:100%\">\r\n<div class=\"span12\" style=\"width:100%\">\r\n\r\n\r\n\r\n<div id=\"endoscopy_nurse\" class=\"  portlet \" >\r\n\r\n<img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' width=\"400\" style=\"float:right;margin:5px; -moz-border-radius: 5px;\r\nborder-radius: 5px; background:#fff;\"/>\r\n<span>\r\n<b><%= @current_project.get_setting \'report_title_1\' %></b>\r\n\r\n<div style=\"margin-top:10px\" id=\"table\">\r\n<div id=\"board\">\r\n</div>\r\n</div></div></div></div></div>\r\n<script>\r\nnumpage = 1;\r\npage = 0;\r\n\r\nfunction update(data){\r\n    \r\n}\r\n\r\nfunction executeQuery() {\r\n  $.ajax({\r\n    url: \'status_feed_partial?page=\'+page,\r\n    success: function(data) {\r\n      //  alert(\"update\");\r\n      // do something with the return value here if you like\r\n      $(\'#board\').fadeOut(500, function(){\r\n      $(\'#board\').html(data);\r\n      })\r\n      $(\'#board\').fadeIn(500)\r\n    }\r\n  });\r\n  setTimeout(executeQuery, 30000); // you could choose not to continue on failure...\r\n}\r\n\r\nfunction setPage(i){\r\n    page = i;\r\n   // alert(\"set to \"+i);\r\n}\r\n\r\n$(document).ready(function() {\r\n  // run the first time; all subsequent calls will take care of themselves\r\n  setTimeout(executeQuery, 0);\r\n});\r\n</script>\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2017-02-01 04:11:56','2017-02-01 04:11:56','status_feed',''),(2909,'document_name',1173,1,'\'report\'',NULL,NULL,NULL,'2017-02-02 03:38:12','2017-02-02 03:38:12',NULL,NULL),(2910,'index_dev',1173,2,'<%\r\n    if !session[:owner]\r\n%>\r\n<script>\r\n    window.location = \'../Home/index\'\r\n</script>\r\n<%\r\n    end\r\n%>\r\n\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'.\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2017-02-02 03:38:42','2017-02-02 03:38:42','index_dev',''),(2911,'demographic',1173,2,'<%\r\n    if !session[:owner]\r\n%>\r\n<script>\r\n    window.location = \'../Home/index\'\r\n</script>\r\n<%\r\n    end\r\n%>\r\n<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n    