\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                }\r\n\r\n                $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n                });\r\n            </script>\r\n<%\r\n    end\r\n%>\r\n\r\n\r\n<%\r\n    \r\n        ehr_model = model\r\n        model = get_model\r\n        \r\n        m_pat_mod = module_model\r\n        # a_pat_mod = m_pat_mod.where([\'module_name LIKE ?\', \"%\\\\#{@current_preoject.name}%\"]).all.group_by{|i| i[:module_name]}\r\n        fields = {:module_name=>@current_project.name}\r\n    	\r\n	    keys = []\r\n\r\n    	fields.each_pair do |k,v| \r\n        	keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n	    end\r\n\r\n    	if keys.size>0\r\n		    criteria = {\'$or\'=>keys}\r\n	    else\r\n    		criteria ={}\r\n	    end\r\n\r\n        # patients = patient_model.where(criteria).limit(20).all\r\n        a_pat_mod = m_pat_mod.where({\"$or\"=>[{:module_name=>/taig/}]}).all.group_by{|i| i[:module_name]}\r\n        \r\n        # provider\r\n        # chinp : 554e5628790f9b0289000015\r\n        # viroj : 55ac60ea790f9b0b31000011\r\n        # chaiwat : 554ef571790f9b439c000002\r\n        # 1. get patient_id from provider\r\n        # 2. each patient get form from module_name, module_id\r\n        # 3. manipulate each module_name, module_id\r\n        \r\n        # get provider id from ... search in provider.where(:login=>@current_user.login)\r\n        \r\n        ehr_model = ehr.load_model\r\n        m_user = ehr_model[:user]\r\n        m_pat_mod = ehr_model[:patient_module]\r\n        \r\n        this_model = get_model\r\n        m_provider = this_model[:provider]\r\n        \r\n        r_user = m_user.all\r\n        r_provider = this_model[:provider].all\r\n        \r\n        prov_id = \'554ef571790f9b439c000002\' # Aj.Chaiwat\r\n        # prov_id = \'55ac60ea790f9b0b31000011\' # Aj.Viroj\r\n        # prov_id = \'554e5628790f9b0289000015\' # Aj.Chinp\r\n        l_hk  = [\'knee1\', \'knee2\', \'hip1\', \'hip2\']\r\n        m_hk = [:knee1, :knee2, :hip1, :hip2]\r\n        a_pat = m_pat_mod.where(:module_id=>prov_id).all.collect{|i| i[:patient_id].to_s}.uniq\r\n        a_dat = m_pat_mod.where(:patient_id=>a_pat).all.collect{|i| {:module_name=>i[:module_name], :module_id=>i[:module_id]}}.group_by{|i| i[:module_name]}\r\n        \r\n        res = {}\r\n        a_dat.each do |k,v|\r\n            mname = k.split(\'#\')[1]\r\n            if m_hk.include? mname.to_sym\r\n                ids = v.collect{|i| i[:module_id]}\r\n                all = model[mname.to_sym].where(:id=>ids).all.collect{|i| {:side=>i[:side], :operation_date=>i[:operation_date]}}\r\n                tmp = all.group_by{|i| i[:side]}\r\n                \r\n                res[mname.to_sym] = tmp\r\n            end\r\n        end\r\n        \r\n\r\n    map_s = {\'1\'=>\'(L)\', \'2\'=>\'(R)\'}\r\n    map_hk = {:hip1=>\'Primary Hip \', :hip2=>\'Revision Hip \', :knee1=>\'Primary Knee \', :knee2=>\'Revision Knee \'}\r\n    dat = []\r\n    xxx = {}\r\n    sum = 0\r\n    res.each do |k,v|\r\n        label = map_hk[k.to_sym]\r\n        tmp = {}\r\n        x = {:label=>label+map_s[\'1\']+\" [\\\\#{v[\'1\'].count}]\",:data=>v[\'1\'].count} if v.has_key?\'1\';\r\n        dat.push(x) if x\r\n        sum += x[:data] if x\r\n        \r\n        x = {:label=>label+map_s[\'2\']+\" [\\\\#{v[\'2\'].count}]\",:data=>v[\'2\'].count} if v.has_key?\'2\';\r\n        sum += x[:data] if x\r\n        dat.push(x) if x\r\n        \r\n        if v.has_key?\'1\'\r\n            xxx[k] = v[\'1\'].group_by { |t| [t[:operation_date].month,t[:operation_date].year] }\r\n        end\r\n    end\r\n    \r\n    # xxx = {}\r\n        # a_dat.each do |k,v|\r\n        #     mname = k.split(\'#\')[1]\r\n        #     if m_hk.include? mname.to_sym\r\n        #         ids = v.collect{|i| i[:module_id]}\r\n        #         all = model[mname.to_sym].where(:id=>ids).all.collect{|i| {:side=>i[:side], :operation_date=>i[:operation_date]}}\r\n        #         tmp = all.group_by{|i| [i[:operation_date].month,i[:operation_date].year]}\r\n                \r\n        #         xxx[mname.to_sym] = tmp\r\n        #     end\r\n        # end\r\nif @current_role == \'developer\'    \r\n    \r\n        \r\n%>\r\n<pre>\r\n    <!--<%= keys %> | <%= criteria %>-->\r\n    <%# a_pat.to_json.html_safe %>\r\n    <%# a_dat.to_json.html_safe %>\r\n    <%= xxx.to_json.html_safe %>\r\n    <%# res.to_json.html_safe %>\r\n    \r\n    <%# dat.to_json.html_safe %>\r\n    \r\n    <%# a_dat.group_by{|i| i[:module_name]}.to_json.html_safe %>\r\n    <%# a_pat_mod.to_json.html_safe %>\r\n    <%# r_provider.to_json.html_safe %>\r\n</pre>\r\n<%\r\n    end\r\n    \r\n    \r\n%>\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n		z_charts.z_all();\r\n		\r\n		$(\'#data-all_operation\').html(\"<%= sum %>\");\r\n	});\r\n    z_charts = {\r\n        z_all : function() {\r\n			// Setup the placeholder reference\r\n            var elem = $(\'#z_all\');\r\n\r\n\r\n			var data = <%= dat.to_json.html_safe %>;\r\n			\r\n            var colors = [ \"#b4dbeb\", \"#8cc7e0\", \"#64b4d5\", \"#3ca0ca\", \"#2d83a6\", \"#22637e\", \"#174356\", \"#0c242e\" ];\r\n            \r\n			// Setup the flot chart using our data\r\n            function a_plotWithColors() {\r\n                fl_a_plot = $.plot(elem, data,         \r\n                    {\r\n                        label: \"Visitors by Location\",\r\n                        series: {\r\n                            pie: {\r\n                                show: true,\r\n                                innerRadius: 0.5,\r\n                                highlight: {\r\n                                    opacity: 0.2\r\n                                }\r\n                            }\r\n                        },\r\n                        grid: {\r\n                            hoverable: true,\r\n                            clickable: true\r\n                        },\r\n                        colors: colors\r\n                    }\r\n                );\r\n            }\r\n        \r\n            a_plotWithColors();\r\n            \r\n            \r\n            // Create a tooltip on our chart\r\n            elem.qtip({\r\n                prerender: true,\r\n                content: \'Loading...\', // Use a loading message primarily\r\n                position: {\r\n                    viewport: $(window), // Keep it visible within the window if possible\r\n                    target: \'mouse\', // Position it in relation to the mouse\r\n                    adjust: { x: 7 } // ...but adjust it a bit so it doesn\'t overlap it.\r\n                },\r\n                show: false, // We\'ll show it programatically, so no show event is needed\r\n                style: {\r\n                    classes: \'ui-tooltip-shadow ui-tooltip-tipsy\',\r\n                    tip: false // Remove the default tip.\r\n                }\r\n            });\r\n         \r\n            // Bind the plot hover\r\n            elem.on(\'plothover\', function(event, pos, obj) {\r\n                \r\n                // Grab the API reference\r\n                var self = $(this),\r\n                    api = $(this).qtip(),\r\n                    previousPoint, content,\r\n         \r\n                // Setup a visually pleasing rounding function\r\n                round = function(x) { return Math.round(x * 1000) / 1000; };\r\n         \r\n                // If we weren\'t passed the item object, hide the tooltip and remove cached point data\r\n                if(!obj) {\r\n                    api.cache.point = false;\r\n                    return api.hide(event);\r\n                }\r\n         \r\n                // Proceed only if the data point has changed\r\n                previousPoint = api.cache.point;\r\n                if(previousPoint !== obj.seriesIndex)\r\n                {\r\n                    percent = parseFloat(obj.series.percent).toFixed(2);\r\n                    // Update the cached point data\r\n                    api.cache.point = obj.seriesIndex;\r\n                    // Setup new content\r\n                    content = obj.series.label + \' ( \' + percent + \'% )\';\r\n                    // Update the tooltip content\r\n                    api.set(\'content.text\', content);\r\n                    // Make sure we don\'t get problems with animations\r\n                    //api.elements.tooltip.stop(1, 1);\r\n                    // Show the tooltip, passing the coordinates\r\n                    api.show(pos);\r\n                }\r\n            });\r\n		}\r\n    };\r\n    <% if false %>\r\n    charts = {\r\n        barz = function() {\r\n            var elem = $(\'#barz\');\r\n        }\r\n    };\r\n<% end %>\r\n</script>',NULL,NULL,NULL,'2017-02-02 03:40:10','2017-02-02 03:40:10','user_overview',''),(2913,'provider',1173,3,'<%\r\n    prov = get_model[:provider].all\r\n    r_prov = {}\r\n    g_prov = prov.group_by{|i| i[:created_at].strftime(\'%m/%Y\')}\r\n    g_prov.each do |k,v|\r\n        r_prov[k] = v.count\r\n    end\r\n    \r\n    # first year\r\n    fy = prov.first[:created_at].strftime(\'%Y\').to_i\r\n    # last year\r\n    # ly = prov.last[:created_at].strftime(\'%Y\').to_i\r\n    ly = Time.now.strftime(\'%Y\').to_i\r\n    \r\n    m = %w{01	02	03	04	05	06	07	08	09	10	11	12}\r\n    \r\n    res = {}\r\n    res[:prov] = r_prov\r\n    fy.upto(ly) do |i|\r\n%>\r\n<%= i %>,\r\n<%\r\n    end\r\n%>\r\n<br/>\r\n<%\r\n    m.each do |i|\r\n%>\r\n<%= i %>,\r\n<%\r\n        fy.upto(ly) do |j|\r\n            k = \"\\\\#{i}/\\\\#{j}\"\r\n            v = r_prov[k].nil? ? 0 : r_prov[k]\r\n%>\r\n<%= v %>,\r\n<%\r\n        end\r\n%>\r\n<br/>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2017-02-02 03:46:52','2017-02-02 03:46:52','provider',''),(2914,'month_num',1173,1,'%w{01	02	03	04	05	06	07	08	09	10	11	12}',NULL,NULL,NULL,'2017-02-02 04:39:27','2017-02-02 04:39:27','month_num',''),(2915,'patient',1173,3,'<%= render :inline=>this.common_function %>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    e_model = ehr.load_model\r\n    m_pat = e_model[:patient]\r\n    m_mod = e_model[:patient_module]\r\n    \r\n    # pat = m_pat.all\r\n    pat = m_pat.find(get_patient_filtered)\r\n    fy  = pat.first[:created_at].strftime(\'%Y\').to_i\r\n    ly  = pat.last[:created_at].strftime(\'%Y\').to_i\r\n    m   = this.month_num\r\n    r_pat = {}\r\n    g_pat = pat.group_by{|i| i[:created_at].strftime(\'%m/%Y\')}\r\n\r\n    fy.upto(ly) do |j|\r\n        m.each do |i|\r\n            k = \"\\\\#{i}/\\\\#{j}\"\r\n            v = g_pat[k].nil? ? 0 : g_pat[k].count\r\n%>\r\n<%= k %>,<%= v %><br/>\r\n<%\r\n        end\r\n    end\r\n%>\r\n<br/>\r\n<%= g_pat.keys.sort %>',NULL,NULL,NULL,'2017-02-02 04:41:37','2017-02-02 04:41:37','patient',''),(2916,'operation',1173,3,'<%= render :inline=>this.common_function %>\r\n<% \r\n    tb = Time.now \r\n    \r\n    params[:date] = \'all\'\r\n    doc_name = \'knee1\'\r\n    if params[:proc]\r\n        doc_name = params[:proc]\r\n    end\r\n    \r\n    fol_doc = \'follow_up_knee\'\r\n    if doc_name.include? \'hip\'\r\n        fol_doc = \'follow_up_hip\'\r\n    end\r\n    \r\n    def get_doc_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].strip\r\n                    tmp[:list] << x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    # @fm = fm\r\n    def get_value f, val\r\n        x = @fm[f.to_sym]\r\n        v = val\r\n        if x.to_h.has_key? :pair and !v.nil? and v != \'\'\r\n            # if f.to_sym == :if_rrt or f.to_sym == :vasopressor\r\n            #     v = x[:pair][v]\r\n            # else\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n                # v = \"<span title=\'\\\\#{v}\'>\\\\#{val} <i class=\'splashy-help\'></i></span>\".html_safe\r\n            # end\r\n        end\r\n            # if f.to_sym == :delivered_lose and !v.nil? and v != \'\'\r\n            #         v = v.to_f.round(4) if Float(v) rescue v\r\n            # end\r\n        # if v.nil? or v == \'\'\r\n        #     v = \'-\'\r\n        # end\r\n        return v\r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	m_pat = @ehr_model[:patient]\r\n	m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	# map prov_id <-> provider_name\r\n	prov = {}\r\n	a_prov = get_model[:provider].all\r\n	a_prov.each do |i|\r\n	    prov[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map company_id <-> company_name\r\n	comp = {}\r\n	a_comp = get_model[:company].all\r\n	a_comp.each do |i|\r\n	    comp[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map knee_component <--> component_name\r\n	kcom = {}\r\n	a_temp = get_model[:knee_component].all\r\n	a_temp.each do |i|\r\n	    kcom[i.id.to_s] = i[:name]\r\n	end\r\n	# map hip component <-> component_name\r\n# 	hcom = {}\r\n# 	a_temp = get_model[:hip_component].all\r\n# 	a_temp.each do |i|\r\n# 	    hcom[i.id.to_s] = i[:name]\r\n# 	end\r\n    \r\n    # map colpo_id <-> colpo\r\n    colpo = {}\r\n    ids   = []\r\n    a_col = get_model[doc_name.to_sym].all\r\n    a_col.each do |i|\r\n        ids << i.id\r\n        colpo[i.id.to_s] = i\r\n    end\r\n    \r\n    \r\n    \r\n    # map patient_id <-> patient\r\n    # ig_pat = %w{55af2feb790f9b6127000003	55c21a68790f9b30e8000003	55af3548790f9b6e5f000003	55affd22790f9b19c600001a	55afff02790f9b08ee00001a	55c254ab790f9b0ddc000016	569fa3d9790f9b0c14000007	57a7514c790f9b6f5f000031	57ea9a2e790f9b475d000002	55c21dbf790f9b4041000001	55c7d26d790f9b62e8000014	55ee3b4f790f9b7114000010	5783159a790f9b3887000012	56b0811b790f9b31ac000025	56b88898790f9b07e2000013	56b98fb6790f9b4348000005	56df9a87790f9b45db0000a7	5785a75d790f9b676d00003d	57906b43790f9b296200001f	57938c9d790f9b6988000004	5793a234790f9b053f000001	57944abd790f9b2411000001	57958eba790f9b534e000034	579592ed790f9b6975000005	57a083d4790f9b2af3000011	57a083f9790f9b2af3000013	57a09623790f9b5a24000002	57a1653f790f9b3b76000005	57abe367790f9b2ca3000001	57abe9e6790f9b232a000010	57abeb90790f9b232a000015	57abfc52790f9b452c00001c	57ac1945790f9b63c4000011	57ac1e16790f9b79f0000014	57ac1e16790f9b7577000047	57ac2adb790f9b7a5a00004b	57ac2f6c790f9b19de000003	57ac3014790f9b196e00000a	57ac3019790f9b196300000f	57ac3025790f9b1963000011	57ac3083790f9b196300001a	57ad6b56790f9b458d000013	57ad7318790f9b53e3000001	57ad7318790f9b4f0f00000a	57ad7b72790f9b55ee000004	57ad8186790f9b55ee00000e	57ad82f1790f9b66b8000001	57b2a657790f9b0d18000001	57b7bf98790f9b30a900000c	57b7fc4d790f9b0deb000001	57bd4561790f9b5a0700000f	57c3dee8790f9b755400000b	57e155c0790f9b44ab000021	57e163ce790f9b4bd1000003	57ac2990790f9b79f000003b	57ad82bf790f9b6615000001	57ad82f0790f9b6422000003	57ad8ef3790f9b717f00000e	57ad82f5790f9b66b8000003	57ad82f7790f9b6422000005	57ad82f7790f9b6615000003	57ad8318790f9b6615000005	57ad831c790f9b6615000007	57ed3b70790f9b2264000001	57ed3bca790f9b2264000007	57ae846d790f9b2516000001	57ae8ef0790f9b397c000003	57aea21a790f9b457d000001	57aea8fe790f9b5603000001	57ff023c790f9b7a1000000e	55f8c301790f9b42b1000003	55fc4a9d790f9b6636000001	5604e196790f9b585d000016	561da4d6790f9b7d63000001	56d66206790f9b360d000014}\r\n    # ig_pat = %w{55af2feb790f9b6127000003	55c21a68790f9b30e8000003	55af3548790f9b6e5f000003	55affd22790f9b19c600001a	55afff02790f9b08ee00001a	55eb1062790f9b4d1c000002	5781f86e790f9b57b900002c	57ecd459790f9b151700001a	55c254ab790f9b0ddc000016	569fa3d9790f9b0c14000007	57a7514c790f9b6f5f000031	57ea9a2e790f9b475d000002	55f8c301790f9b42b1000003	55fc4a9d790f9b6636000001	5604e196790f9b585d000016	561da4d6790f9b7d63000001	56d66206790f9b360d000014	55c21dbf790f9b4041000001	55c7d26d790f9b62e8000014	55ee3b4f790f9b7114000010	5783159a790f9b3887000012	56b0811b790f9b31ac000025	56b88898790f9b07e2000013	56b98fb6790f9b4348000005	56df9a87790f9b45db0000a7	5785a75d790f9b676d00003d	57906b43790f9b296200001f	57938c9d790f9b6988000004	5793a234790f9b053f000001	57944abd790f9b2411000001	57958eba790f9b534e000034	579592ed790f9b6975000005	57a083d4790f9b2af3000011	57a083f9790f9b2af3000013	57a09623790f9b5a24000002	57a1653f790f9b3b76000005	57abe367790f9b2ca3000001	57abe9e6790f9b232a000010	57abeb90790f9b232a000015	57abfc52790f9b452c00001c	57ac1945790f9b63c4000011	57ac1e16790f9b79f0000014	57ac1e16790f9b7577000047	57ac2adb790f9b7a5a00004b	57ac2f6c790f9b19de000003	57ac3014790f9b196e00000a	57ac3019790f9b196300000f	57ac3025790f9b1963000011	57ac3083790f9b196300001a	57ad6b56790f9b458d000013	57ad7318790f9b53e3000001	57ad7318790f9b4f0f00000a	57ad7b72790f9b55ee000004	57ad8186790f9b55ee00000e	57ad82f1790f9b66b8000001	57b2a657790f9b0d18000001	57b7bf98790f9b30a900000c	57b7fc4d790f9b0deb000001	57bd4561790f9b5a0700000f	57c3dee8790f9b755400000b	57e155c0790f9b44ab000021	57e163ce790f9b4bd1000003	57ac2990790f9b79f000003b	57ac2d1a790f9b63c4000085	57ac300e790f9b196e000008	57ac3016790f9b19de000005	57aeb227790f9b5f5b000009	57c653c3790f9b2ddd000006	583fb46b790f9b422c00000b	57ac302c790f9b196e00000c	57ac3040790f9b194c000006	57ad82bf790f9b6615000001	57ad82f0790f9b6422000003	57ad8ef3790f9b717f00000e	57ad82f5790f9b66b8000003	57ad82f7790f9b6422000005	57ad82f7790f9b6615000003	57ad8318790f9b6615000005	57ad831c790f9b6615000007	57ed3b70790f9b2264000001	57ed3bca790f9b2264000007	57ae846d790f9b2516000001	57ae8ef0790f9b397c000003	57aea21a790f9b457d000001	57aea8fe790f9b5603000001	57ff023c790f9b7a1000000e}\r\n    # ig_pat = []\r\n    # pat_ids = mm_proc.collect{|i| i[:patient_id].to_s}\r\n    # pat_ids = pat_ids - ig_pat\r\n    pat_ids = get_patient_filtered\r\n    pat = {}\r\n    rs_pat = m_pat.find(pat_ids)\r\n    rs_pat.each do |i|\r\n        pat[i.id.to_s] = i\r\n    end\r\n    \r\n    # procedure\'s module_model\r\n    mm_proc = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{doc_name}\", :module_id=>ids, :patient_id=>pat_ids).all\r\n    # parent ids \r\n    par_ids = mm_proc.collect{|i| i[:parent_id]}\r\n    # follow up\r\n    mm_foll = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{fol_doc}\", :parent_id=>par_ids).all\r\n    gr_foll = mm_foll.group_by{|i| i[:parent_id].to_s}\r\n\r\n    # main fields\r\n    mf = get_doc_field doc_name\r\n    @fm = mf\r\n\r\n    # patient fields\r\n    pf = [:id, :hn, :name, :hospital, :age, :gender]\r\n    # column fields\r\n    colf = pf + mf.keys + [:follow_up]\r\n    colf = colf - [:image_pre_op, :image_intra_op, :image_implant_barcode, :operative_note, :recorder_by, :hn, :name, :hospital]\r\n    \r\n    rs_col = []\r\n    rs_les = []\r\n    \r\n    # patient-follow_up\r\n    pat_foll = {}\r\n    # patient-implant_profile\r\n    pat_imp  = {}\r\n    # all_follow_up\r\n    fol_list = []\r\n    # all_implant_profile\r\n    imp_list = []\r\n    mm_proc.each do |i|\r\n        pat_id = i[:patient_id].to_s\r\n        par_id = i[:parent_id].to_s\r\n        # patient\r\n        pt = pat[i[:patient_id].to_s]\r\n        # colpo\r\n        cp = colpo[i[:module_id].to_s]\r\n        \r\n        if pt.nil?\r\n            next\r\n        end\r\n        \r\n        today = cp[:created_at]\r\n        # age = 0\r\n        # begin\r\n        d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  1) : today\r\n        age = !pt[:birth_date].nil? ? d.year - pt[:birth_date].year - (d > today ? 1 : 0) : 0\r\n        # age = (pt[:birth_date].nil? or pt[:birth_date]==\'\') ? \"xx-\\\\#{pt[:birth_date]}-xx\" : \"yy-\\\\#{pt[:birth_date].instance_of?(Date)}-yy\"\r\n        # rescue\r\n        #     age = \"xx-\\\\#{pt[:birth_date]}-xx\"\r\n        # end\r\n        \r\n        \r\n        tmp = {}\r\n        tmp[:id]  = pt.id.to_s[5..14]\r\n        tmp[:hn]  = pt[:hn]\r\n        tmp[:name]= \"\\\\#{pt[:first_name]} \\\\#{pt[:last_name]}\"\r\n        tmp[:age] = age\r\n        tmp[:hospital] = pt[:hospital]\r\n        tmp[:gender] = pt[:gender]\r\n        \r\n        mf.keys.each do |j|\r\n            x = mf[j]\r\n            # x = {}\r\n            v = cp[j]\r\n            if x.to_h.has_key? :pair and !v.nil?\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                \r\n                tmp[j] = a.join(\',\')\r\n            elsif x[:column_name].include? \'implant_profile\' \r\n                tmp[j] = v\r\n                \r\n                if v.size != 0\r\n                    imp_list += v\r\n                    if !pat_imp.has_key? pat_id\r\n                        pat_imp[pat_id] = {}\r\n                    end\r\n                    pat_imp[pat_id][j] = v\r\n                end\r\n                \r\n            elsif x[:column_name] == \'image\'\r\n                tmp[j] = v.size\r\n            elsif x[:column_name].to_s.include? \'provider_\' or x[:column_name] == \'recorder_by\'\r\n                name = prov[v.to_s]\r\n                if name\r\n                    # tmp[j] = name\r\n                    tmp[j] = v.to_s[0..9]\r\n                else\r\n                    tmp[j] = v\r\n                end\r\n            elsif x[:column_name].include? \'component_\' or x[:column_name].include? \'company\'\r\n                if x[:column_name].include? \'company\'\r\n                    tmp[j] = comp[v.to_s]\r\n                else\r\n                    tmp[j] = kcom[v.to_s]\r\n                end\r\n            else\r\n                tmp[j] = v\r\n            end\r\n        end\r\n        \r\n        tmp[:follow_up] = gr_foll[par_id].nil? ? 0 : gr_foll[par_id].size\r\n        \r\n        if tmp[:follow_up] != 0\r\n            pat_foll[pat_id] = gr_foll[par_id]\r\n            fol_list += gr_foll[par_id].collect{|i| i[:module_id]}\r\n        end\r\n        \r\n        rs_col << tmp\r\n    end\r\n    \r\n    res = {}\r\n    # res[:af]   = af\r\n    res[:res]  = rs_col.size\r\n    res[:mm_foll] = mm_foll.size\r\n    res[:imp_size] = imp_list.size\r\n    res[:fol_size] = fol_list.uniq.size\r\n    res[:pat_foll] = pat_foll\r\n    res[:pat_imp]  = pat_imp\r\n    res[:time] = Time.now - tb\r\n    \r\n    # this month\r\n    tm = \"\\\\#{tb.strftime(\'%d\')}/\\\\#{tb.strftime(\'%Y\')}\"\r\n    \r\n    m   = this.month_num\r\n    obj = mm_proc\r\n    g_obj = mm_proc.group_by{|i| i[:created_at].strftime(\'%m/%Y\')}\r\n    # fy  = obj.first[:created_at].strftime(\'%Y\').to_i\r\n    fy = 2015\r\n    ly  = obj.last[:created_at].strftime(\'%Y\').to_i\r\n    fy.upto(ly) do |j|\r\n        m.each do |i|\r\n            k = \"\\\\#{i}/\\\\#{j}\"\r\n            v = g_obj[k].nil? ? 0 : g_obj[k].count\r\n            if k == tm\r\n                k = \"<u>\\\\#{k}</u>\".html_safe\r\n            end\r\n%>\r\n<%= k %>,<%= v %><br/>\r\n<%\r\n        end\r\n    end\r\n    \r\n    if false\r\n%>\r\n<!-- Main Procedure -->\r\n<h3><%= doc_name.humanize %> total <%= rs_col.size %> records</h3>\r\n<%= colf.join(\'|\') %><br/>\r\n<%\r\n    \r\n    rs_col.each do |i|\r\n        colf.each do |j|\r\n%>\r\n<%= i[j] %>|\r\n<%\r\n        end\r\n%>\r\n<br/>\r\n<%\r\n    end\r\n\r\n    if fol_list.size != 0\r\n        # field map\r\n        fm = get_doc_field fol_doc\r\n        @fm = fm\r\n%>\r\n<br/>\r\n\r\n<!-- Follow up -->\r\n<h3><%= fol_doc.humanize %> total <%= fol_list.size %> records</h3>\r\n<%\r\n    res_fol = get_model[fol_doc.to_sym].find(fol_list)\r\n    \r\n    # gr_fol = res_fol.group_by{|i| i.id}\r\n    gr_fol = res_fol.group_by{|i| i[:_id]}\r\n    \r\n    colf = [:id] + fm.keys - [:image, :recorder_by]\r\n%>\r\n<%= colf.join(\'|\') %><br/>\r\n<%\r\n    pat_foll.each do |k,v|\r\n        id = k[5..14]\r\n\r\n        v.each do |i|\r\n            mid = i[:module_id]\r\n            obj = gr_fol[mid][0] if gr_fol[mid]\r\n            if obj.nil?\r\n                next\r\n            end\r\n            obj[:id] = id\r\n            \r\n            colf.each do |j|\r\n%>\r\n<%= get_value j, obj[j] %>|\r\n<%\r\n            end\r\n%>\r\n<br/>\r\n<%\r\n        end\r\n%>\r\n<%\r\n    end\r\n    end # end fol_list.size // check for follow up\r\n\r\n    if imp_list.size != 0\r\n%>\r\n<!-- Implant Profile -->\r\n<h3>Implant Profile total <%= imp_list.size %> records</h3>\r\n<%\r\n        m_company = get_model[:implant_company].all\r\n        m_component = get_model[:implant_component].all\r\n        m_type   = get_model[:implant_type].all\r\n        m_material  = get_model[:implant_material].all\r\n        \r\n        g_company = m_company.group_by{|i| i.id}\r\n        g_component = m_component.group_by{|i| i.id}\r\n        g_type    = m_type.group_by{|i| i.id}\r\n        g_material= m_material.group_by{|i| i.id}\r\n        \r\n        res_rec  = get_model[:implant_record].find(imp_list)\r\n        imp_ids  = res_rec.collect{|i| i[:component_description]}\r\n        res_imp  = get_model[:implant_profile].find(imp_ids)\r\n        \r\n        gr_rec   = res_rec.group_by{|i| i[:_id]}\r\n        gr_imp   = res_imp.group_by{|i| i[:_id].to_s}\r\n        \r\n        fm = get_doc_field \'implant_record\'\r\n        @fm = fm\r\n        \r\n        colf = [:id, :status] + fm.keys + [:product_id, :barcode]\r\n        \r\n        xxx = {}\r\n        xxx[:rec] = gr_rec\r\n        xxx[:imp] = gr_imp\r\n%>\r\n<%= colf.join(\'|\') %><br/>\r\n<% x = 0\r\n        pat_imp.each do |key, val|\r\n            id = key[5..14]\r\n            \r\n            val.each do |k,v|\r\n                st = k\r\n                v.each do |i|\r\n                    tmp = gr_rec[i]\r\n                    \r\n                    if tmp.nil?\r\n                        next\r\n                    end\r\n                    obj = tmp[0]\r\n                    obj[:id] = id\r\n                    obj[:status] = st\r\n                    \r\n                        x += 1\r\n                    colf.each do |j|\r\n                        v = obj[j]\r\n                        if v.nil? or v == \'\'\r\n                            v = \'\'\r\n                        elsif j == :company_ref_id\r\n                            v = g_company[v][0][:company_name]\r\n                        elsif j == :component_ref_id\r\n                            v = g_component[v][0][:component_name]\r\n                        elsif j == :type_ref_id\r\n                            v = g_type[v][0][:type_name]\r\n                        elsif j == :component_description\r\n                            a = v.to_s\r\n                            v = gr_imp[v.to_s][0][:component_description]\r\n                            if v\r\n                                obj[:product_id] = gr_imp[a][0][:product_id]\r\n                                obj[:barcode]    = gr_imp[a][0][:barcode]\r\n                            end\r\n                        end\r\n%>\r\n<%= v %>|\r\n<%\r\n                    end\r\n%>\r\n<br/>\r\n<%\r\n                end\r\n            end\r\n            \r\n            \r\n            if false # for implant profile display\r\n            val.each do |k, v|\r\n                st = k\r\n                v.each do |i|\r\n                    \r\n                    imp_id = gr_rec[i][0][:component_description] if gr_rec[i]\r\n                    \r\n                    if imp_id.nil?\r\n                        next\r\n                    end\r\n                    \r\n                    obj = gr_imp[imp_id.to_s][0] if gr_imp[imp_id.to_s]\r\n                    if obj.nil?\r\n                        # next\r\n                        obj = {}\r\n                        obj[:company_id] = imp_id\r\n                    end\r\n                    \r\n                    obj[:id] = id\r\n                    obj[:status] = k\r\n                    \r\n                    colf.each do |j|\r\n                        v = obj[j]\r\n                        \r\n                        if v.nil? or v == \'\'\r\n                            v = \'\'\r\n                        elsif j == :company_ref_id\r\n                            v = g_company[v][0][:company_name]\r\n                        elsif j == :component_ref_id\r\n                            v = g_component[v][0][:component_name]\r\n                        elsif j == :type_ref_id\r\n                            v = g_type[v][0][:type_name]\r\n                        elsif j == :material_ref_id\r\n                            v = g_material[v][0][:material_name]\r\n                        end\r\n                    \r\n%>\r\n<%= v %>|\r\n<%\r\n                    end\r\n%>\r\n<br/>\r\n<%\r\n                end\r\n            end\r\n            end # if false\r\n%>\r\n<% end %>\r\n<%\r\n    end # end imp_list.size // check for implant\r\n%>\r\n<%= x %>\r\n<% end %>\r\n<hr/>\r\nUsage : Report/operation?proc=\'document_name[<u>knee1</u>|knee2|hip1|hip2]\'<br/>\r\nProcessing Time : <%= Time.now - tb %>\r\n',NULL,NULL,NULL,'2017-02-02 05:07:27','2017-02-02 05:07:27','operation',''),(2917,'context_menu',1168,4,'<div id=\"context-menu\" class=\"accordion\">\r\n             <div class=\"accordion-group\">\r\n	<div class=\"accordion-heading\">\r\n		<a href=\"#collapse-0\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n		Inventory System\r\n		</a>\r\n		<div class=\"accordion-body collapse in\" id=\"collapse-0\">\r\n			<div class=\"accordion-inner\">\r\n				<ul class=\"nav nav-list\">\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"../Product/index\">Products</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"../ProductCategory/index\">Categories</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"../Order/index\">Orders</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"../Store/index\">Stores</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"../Report/index\">Reports</a></li>\r\n\r\n\r\n				</ul>\r\n			</div>\r\n	</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n		\r\n			</div>\r\n		</div>',NULL,NULL,NULL,'2017-02-02 05:31:40','2017-02-02 05:31:40','context_menu',''),(2918,'quick_order',1168,3,'<%= render :inline=>this.init %>\r\n\r\n<%\r\n    \r\n    order = @models[:order].find(params[:id]) \r\n     items = @models[:store_item].where(:store_id=>@current_store.id).all\r\n      products = @models[:product].find(items.collect{|i| i.product_id})\r\n    product_map = {}\r\n    for i in products\r\n        product_map[i.id] = i\r\n    end\r\n    \r\n    if params[:balances]\r\n                       \r\n                       qitems =  @models[:order_item].find(order.items)\r\n                        \r\n                       for i in qitems\r\n                            i.destroy\r\n                       end\r\n                       \r\n                       for i in items\r\n                        \r\n                        p = params[:balances][i.product_id.to_s]\r\n                        product = product_map[i.product_id]\r\n                        \r\n                        diff = 0\r\n                        diff = i.balance - p.to_i  if i.balance and p\r\n                        \r\n                        if diff != 0 \r\n                           \r\n                          new_item =  @models[:order_item].create :product_id=>i.product_id, :quantity=>-diff, :price=>product.price, :title=>product.name\r\n                            \r\n                           order.items << new_item.id   \r\n                            \r\n                        end\r\n                        \r\n                        \r\n                       end\r\n                       \r\n                       order.save\r\n                       \r\n                       \r\n    end\r\n                   \r\n                   \r\n                   \r\n    \r\n    \r\n    \r\n   \r\n    if order and ( params[:product_id] or (params[:order] and params[:order][:search]) ) \r\n           %>\r\n        .\r\n        <%\r\n        if params[:product_id]\r\n            product = @models[:product].find(params[:product_id])\r\n        else\r\n            product = @models[:product].where(:barcode=>params[:order][:search]).first\r\n        end\r\n        %>\r\n        .\r\n        <%\r\n        if product \r\n            \r\n            store_item = @models[:store_item].where(:product_id=>product.id , :store_id=>@current_store.id).first\r\n            balance = 0 \r\n            \r\n            if  store_item == nil  \r\n                \r\n                store_item = @models[:store_item].create :product_id=>product.id , :store_id=>@current_store.id, :balance=>0\r\n            %>\r\n            created\r\n            <%\r\n            end\r\n            \r\n            \r\n            for i in @models[:order_item].find(order.items)\r\n                if i.product_id == product.id\r\n                    balance += i.quantity\r\n                end\r\n            end\r\n            \r\n            \r\n            if store_item and store_item.balance - balance > 0\r\n            \r\n            \r\n            \r\n            item = @models[:order_item].create :quantity=>1, :price=>product.price, :title=>product.title, :product_id=>product.id \r\n            \r\n            order.items << item.id\r\n            \r\n            order.save\r\n            \r\n            # elsif store_item == nil and order.order_type==\'amend\'\r\n            \r\n           \r\n            end\r\n            \r\n            \r\n        end\r\n        \r\n        \r\n    elsif order and params[:order_item]\r\n    \r\n        item = @models[:order_item].find params[:order_item]\r\n        \r\n        order.items.delete item.id\r\n        \r\n        order.save\r\n        item.destroy\r\n        \r\n    end\r\n\r\n%>\r\n \r\n\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Home/index?show_item=<%=item.id if item%>\" />\r\n\r\n\r\n',NULL,NULL,NULL,'2017-02-02 12:59:37','2017-02-02 12:59:37','quick_order',''),(2919,'show',1163,2,'<%\r\n    return_url = url(\'../Home/index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%\r\n    models = get_model\r\n    order = models[:order].find(params[:id])\r\n    \r\n%>\r\n<%= link_to \'Commit\', \"commit?id=\\\\#{params[:id]}\",:class=>\'btn btn-success\',:data=>{:confirm=>\'Are you sure?\' } if order.status==\'Pending\' or order.status==\'Draft\' %> \r\n<% if order.status==\'Completed\' %>\r\n<%= link_to \'Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-info\' %> | \r\n<% end %>\r\n\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:class=>\'btn\' %> | \r\n<%= link_to \'Back\', return_url %> \r\n<% if flash[:warning] %><br/><br/>\r\n<div class=\"alert alert-danger\"><%= flash[:warning] %></div>\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-02-02 15:41:10','2017-02-02 15:41:10','show',''),(2920,'print_partial',1163,4,'\r\n\r\n<%=@record.inspect %>',NULL,NULL,NULL,'2017-02-04 04:38:29','2017-02-04 04:38:29','print_partial',''),(2921,'document_name',1174,1,'\'nurse_note\'',NULL,NULL,NULL,'2017-02-06 02:12:31','2017-02-06 02:12:31',NULL,NULL),(2922,'emr_report',522,2,'<h1>EMR Reports</h1>\r\n<ul>\r\n<%\r\n\r\nservices =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\'}.compact \r\nfor i in services\r\n\r\n%>\r\n<li>\r\n    <%=link_to i.name.humanize, \"../\\\\#{i.name.camelize}/analysis\",:target=>\'_blank\' %> \r\n    </li>\r\n<% end %>\r\n    \r\n    \r\n</ul>',NULL,NULL,NULL,'2017-02-06 17:23:45','2017-02-06 17:23:45','emr_report',''),(2923,'form',1174,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n<script>\r\n    function cal_bmi() {\r\n        w = $(\'#data-bw\').val();\r\n        h = $(\'#data-ht\').val();\r\n        bmi = \'-\';\r\n        \r\n        if (w != \'\' && h != \'\') {\r\n            w = parseFloat(w);\r\n            h = parseFloat(h) / 100;\r\n            bmi = (w / (h * h)).toFixed(2);\r\n        }\r\n        \r\n        \r\n        $(\'#data-bmi\').val(bmi);\r\n    }\r\n    \r\n    function cal_sos_score() {\r\n        s1 = $(\'#data-sos_consciousness\').val();\r\n        s2 = $(\'#data-sos_sbp_mmhg\').val();\r\n        s3 = $(\'#data-sos_hr_min\').val();\r\n        s4 = $(\'#data-sos_rr_min\').val();\r\n        s5 = $(\'#data-sos_bt\').val();\r\n        \r\n        ss1 = (s1 == \"\" ? 0 : Math.abs(parseInt(s1)));\r\n        ss2 = (s2 == \"\" ? 0 : Math.abs(parseInt(s2)));\r\n        ss3 = (s3 == \"\" ? 0 : Math.abs(parseInt(s3)));\r\n        ss4 = (s4 == \"\" ? 0 : Math.abs(parseInt(s4)));\r\n        ss5 = (s5 == \"\" ? 0 : Math.abs(parseInt(s5)));\r\n        \r\n        sum = ss1 + ss2 + ss3 + ss4 + ss5;\r\n        \r\n        $(\'#data-sos_total_score\').val(sum);\r\n    }\r\n    \r\n    $(document).ready(function() {\r\n        $(\'#data-bw\').change(cal_bmi);\r\n        $(\'#data-ht\').change(cal_bmi);\r\n        \r\n        if ($(\'#data-sos_total_score\').val()==\"\") {\r\n            $(\'#data-sos_total_score\').val(\"0\");\r\n        }\r\n        \r\n        $(\'#data-sos_consciousness\').change(cal_sos_score);\r\n        $(\'#data-sos_sbp_mmhg\').change(cal_sos_score);\r\n        $(\'#data-sos_hr_min\').change(cal_sos_score);\r\n        $(\'#data-sos_rr_min\').change(cal_sos_score);\r\n        $(\'#data-sos_bt\').change(cal_sos_score);\r\n        \r\n    });\r\n\r\n    var ts_field = \"data-arrival_time\";\r\n    var te_field = \"data-discharge_time\";\r\n    var tt_field = \"data-total_recovery_time\";\r\n    function update_time() {\r\n        var ts = $(\'#\' + ts_field).val();\r\n        var te = $(\'#\' + te_field).val();\r\n        // console.log(\'ts: \' + ts + \", te: \" + te);\r\n        \r\n        var t_s = new Date(\"<%= Time.now.strftime(\'%m/%d/%Y\') %> \" + ts);\r\n        var t_e = new Date(\"<%= Time.now.strftime(\'%m/%d/%Y\') %> \" + te);\r\n        // console.log(\'t_s: \' + t_s + \', t_e: \' + t_e);\r\n        \r\n        var t_d = (t_e - t_s)/60000;\r\n        // console.log(\'t_d: \' + t_d);\r\n        \r\n        $(\'#\' + tt_field).val(t_d);\r\n    }\r\n    \r\n    \r\n    $(\'#\' + ts_field).change(update_time)\r\n    $(\'#\' + te_field).change(update_time)\r\n    if ($(\'#\' + tt_field).val() === \'\') { \r\n        $(\'#\' + tt_field).val(0)\r\n    }\r\n</script>',NULL,NULL,NULL,'2017-02-07 01:16:44','2017-02-07 01:16:44','form',''),(2924,'his_show',1152,1,'false',NULL,NULL,NULL,'2017-02-08 15:23:57','2017-02-08 15:23:57','his_show',''),(2925,'document_name',1175,1,'\'sedation_time\'',NULL,NULL,NULL,'2017-02-10 04:03:22','2017-02-10 04:03:22',NULL,NULL),(2926,'document_name',1176,1,'\'post_scope_record\'',NULL,NULL,NULL,'2017-02-10 04:05:23','2017-02-10 04:05:23',NULL,NULL),(2927,'print',1163,3,'<html>\r\n<head>\r\n			<%= javascript_include_tag \"application\"  %>\r\n			<%= stylesheet_link_tag    \"application\", media: \"all\" %>\r\n			<%= csrf_meta_tag %>\r\n\r\n    \r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n    \r\n</head>\r\n\r\n\r\n<body>\r\n<%= this.display.html_safe %>\r\n<style type=\"text/css\" media=\"all\">\r\n    #page {border:solid 1px; width:910px;margin-left:0px ; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\n</style>\r\n<script>\r\n    $(document).ready(function(){\r\n        // alert(\'dijfdf\')\r\n        window.print();\r\n        window.onfocus=function(){ window.close();}\r\n    })\r\n</script>    \r\n</body>\r\n</html>',NULL,NULL,NULL,'2017-02-13 09:29:44','2017-02-13 09:29:44','print',''),(2928,'index',1161,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'index\' do |f| %>\r\n<div>\r\n\r\n<div class=\'left\'>\r\n    \r\n    <%=link_to \'Edit Items\', \'index_edit\',:class=>\'btn\'%>\r\n    \r\n</div>\r\n<div class=\"hide\">\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n</div>\r\n\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%# link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2017-02-13 11:11:51','2017-02-13 11:11:51','index',''),(2929,'index_edit',1161,2,'<%\r\n\r\n models = get_model\r\n \r\n category_map = {}\r\n categories =  models[:product_category].all\r\n cat_map = {}\r\n categories.each do |i|\r\n     category_map[i.id] = []\r\n     cat_map[i.id] = i\r\n end\r\n category_map[nil] = []\r\n \r\n pmap = {}\r\n products = models[:product].all :order=>\'manufacture, name \'\r\n for i in products\r\n    pmap[i.id.to_s] = i\r\n end\r\n \r\n if request.post?\r\n    \r\n    \r\n    params[:ids].each_with_index do |i,index| \r\n        \r\n        p = pmap[i]\r\n        \r\n        p.update_attributes :name=>params[:name][index], :code=>params[:code][index],  :barcode=>params[:barcode][index], \r\n        :category_id=>params[:category_id][index], :cost=>params[:cost][index], :price=>params[:price][index], :manufacture=>params[:manufacture][index]\r\n        \r\n    end\r\n     \r\n     %>\r\n     <script>\r\n         window.location= \"index\";\r\n     </script>\r\n     <%\r\n     \r\n else\r\n \r\n \r\n \r\n\r\n \r\n for i in products\r\n  \r\n    category_map[i.category_id] << i     if  category_map[i.category_id] \r\n    \r\n end\r\n \r\n%>\r\n<%= form_for :product, :url=>\'index_edit\' do |f| %>\r\n<table class=\"table\">\r\n<thead>\r\n    <tr>\r\n        <th>Description</th>\r\n        <th>Category</th> \r\n        <th>Code</th>\r\n        <th>Barcode</th>\r\n        <th>Manufacture</th>\r\n        <th>Cost</th>\r\n        <th>Price</th>\r\n    \r\n\r\n    </tr>\r\n</thead>\r\n    <tbody>\r\n    <% \r\n        \r\n        cats = categories.collect{|i| i.id} + [nil]\r\n        \r\n        #for i in cats\r\n        \r\n        #cat = cat_map[i]\r\n        \r\n        \r\n    %>\r\n    \r\n    <% for p in products  #category_map[i].sort{|a,b| a.name<=>b.name} %>\r\n    <tr>\r\n    \r\n     <td>\r\n        <%=text_field_tag \"name[]\",p.name, :style=>\'width:270px\' %>\r\n    </td>    \r\n\r\n\r\n    \r\n    <td><%=hidden_field_tag \"ids[]\", p.id %>\r\n        <%=select_tag \"category_id[]\", options_for_select(categories.collect{|i| [i.name,i.id]}, p.category_id),:include_blank=>true,:style=>\"width:120px\" %>\r\n        \r\n    </td>\r\n     <td>\r\n        <%=text_field_tag \"code[]\",p.code, :style=>\'width:70px\' %>\r\n    </td>   \r\n   \r\n    \r\n    \r\n    <td>\r\n        <%=text_field_tag \"barcode[]\",p.barcode,:onkeypress=>\'javascript:key()\',:style=>\'width:100px\',:id=>\"barcode_\\\\#{p.id}\" %>\r\n        <script>\r\n            $(\"#barcode_<%=p.id%>\").keydown(function(e){\r\n                if (e.keyCode == 13) { // barcode scanned!\r\n                    return false; // block form from being submitted yet\r\n                }\r\n            });\r\n        </script>\r\n    </td>    \r\n    \r\n    <td>\r\n        \r\n        <%=text_field_tag \"manufacture[]\",p.manufacture, :style=>\'width:70px\' %>\r\n    </td>   \r\n   \r\n      <td>\r\n     \r\n        <%=text_field_tag \"cost[]\",p.cost, :style=>\'width:60px\' %>\r\n     \r\n    </td> \r\n    <td>\r\n     \r\n        <%=text_field_tag \"price[]\",p.price, :style=>\'width:60px\' %>\r\n     \r\n    </td> \r\n    \r\n  \r\n    <td align=\"center\">\r\n    \r\n       <%=link_to \'Edit\', \"../Product/edit?id=\\\\#{p.id}&return=../Product/index\", :class=>\'btn btn-info\'%>\r\n\r\n     \r\n    </td>\r\n\r\n    \r\n    \r\n        \r\n    </tr>\r\n    <% end %>\r\n    </tbody>\r\n</table>\r\n<%= f.submit \'Update\',:class=>\'btn\' %> | <%= link_to \'Cancel\', \'index\' %> | \r\n\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n\r\n\r\n<% end %>\r\n<% end %>\r\n\r\n<script>\r\n    function key(){\r\n     \r\n    }\r\n</script>',NULL,NULL,NULL,'2017-02-13 11:12:10','2017-02-13 11:12:10','index_edit',''),(2930,'list',1161,3,'<%\r\n   model = get_model(this.table_name)\r\n   records = []\r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   \r\n    if params[:search]\r\n        records = model.all(params[:search][:criteria])\r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n    #   records = model.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n       records = model.all :order=>\'manufacture, name \'\r\n\r\n\r\n    end\r\n    \r\n    mcategory = {}\r\n    models = get_model\r\n    \r\n    models[:product_category].all.each do |i|\r\n       mcategory[i.id] = i  \r\n    end\r\n    \r\n    if params[:category_id]\r\n       \r\n       records = records.collect{|i| i if params[:category_id]==i.category_id.to_s }.compact\r\n       \r\n        \r\n    end\r\n    \r\n   \r\n%>\r\n\r\n<% if records.size==1 \r\n    \r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=show?id=<%=records[0].id%>\" />\r\n<% end %>\r\n<%# tabular :model=>labels, :data=>records do |i,out|\r\n\r\nfields.each_with_index do |f,index|\r\n\r\nout[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n\r\nend\r\nout << link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nout << link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\')\r\nout << link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:confirm=>\'Are you sure?\')\r\nout\r\nend\r\n%>\r\n<div>\r\n<table class=\"table\">\r\n    \r\n    <thead>\r\n        <tr>\r\n            <th>No.</th><th>Description</th><th>Category</th><th>Code</th><th>Barcode</th><th>Manufacture</th><th>Cost</th><th>Price</th><th>Image</th>\r\n            <th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n    <% records.each_with_index do |p,index|  \r\n        \r\n        category = mcategory[p.category_id]\r\n    %>\r\n        <tr>\r\n            <td><%=index+1%>.</td>\r\n            <td><%=link_to p.name, \"show?id=\\\\#{p.id}\" %></td>\r\n            <td><%=category.name if category%></td><td><%=p.code%></td><td><%=p.barcode%></td><td><%=p.manufacture%></td>\r\n            <td><%=p.cost%></td>\r\n            <td><%=p.price%></td><td><%=\'OK\' if p.image and p.image.size>0%></td>\r\n        \r\n            <td>\r\n                <%=link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>p.id),:class=>\'btn btn-info btn-mini\' )%>\r\n                <%=link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>p.id),:class=>\'btn btn-warning btn-mini\')%>\r\n                <%=link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>p.id),:class=>\'btn btn-danger btn-mini\',:data=>{:confirm=>\'Are you sure?\'})%>\r\n            </td>\r\n        </tr>\r\n    <% end %>\r\n    </tbody>\r\n</table>\r\n</div>\r\n\r\n<% if false and page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2017-02-13 15:55:54','2017-02-13 15:55:54','list',''),(2931,'index',1178,2,'<style>\r\n                .dataTables_wrapper{position:relative;overflow:hidden}\r\n                .dataTables_wrapper table.table {clear:both;margin-bottom:6px!important;max-width:inherit}\r\n                .dataTables_wrapper table.table thead .sorting,table.table thead .sorting_asc,table.table thead .sorting_desc,table.table thead .sorting_asc_disabled,table.table thead .sorting_desc_disabled{cursor:hand;cursor:pointer}\r\n                .dataTables_wrapper table.table thead .sorting{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_both.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc_disabled.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc_disabled.png) no-repeat center right}\r\n</style>\r\n<!-- datatable -->\r\n            <script src=\"/gebo/lib/datatables/jquery.dataTables.min.js\"></script>\r\n            <script src=\"/gebo/lib/datatables/extras/Scroller/media/js/Scroller.min.js\"></script>\r\n            <!-- datatable functions -->\r\n            <script src=\"/gebo/js/gebo_datatables.js\"></script>\r\n<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\n	end\r\n	if session[module_name]\r\n	  params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n	his = session[:his]\r\n%>\r\n	\r\n<%#session[module_name].inspect %>\r\n<%\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    if params[:reset_lock]\r\n	    l = get_model[:locker].find(params[:reset_lock])\r\n        l.destroy if l\r\n	end\r\n	if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Patient Record\"\r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n    // window.location = \"../OutPatientForm/create?patient_id=<%=patient.id.to_s%>&record_name=<%=patient[:hn]%>&parent_id=<%=rec_pm_app.id.to_s%>&return=../Home/index\";\r\n</script>\r\n<%\r\n        end\r\n    end\r\n	\r\n	\r\n	\r\n	if params[:obj_id]\r\n	    now = Time.now \r\n	\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n                \r\n                	Status \r\n                \r\n                \r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> \r\n					\r\n				\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n                \r\n                \r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n					<!--<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Add Visit</button></a>-->\r\n					\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n\r\n\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n    \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"close\" style=\"float:right;\"  data-dismiss=\"modal\">X</a>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>เลขที่บัตรประชาชน : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n<%\r\n    if this.his_show\r\n%>\r\n<span id=\'span-his_btn\' style=\'margin-left:20px\'>\r\n\r\n  \r\n  \r\n<% if session[:his]%>\r\n<span id=\'his-status\'>\r\nWelcome <%= session[:his] %>\r\n\r\n  </span>\r\n    <a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient</a>\r\n<% else %>\r\n<span id=\'his-status\'>\r\nPlease login to get HN from HIS\r\n\r\n  </span>\r\n  <span id=\'temp-get-his\'>&nbsp;</span>\r\n            <span class=\'login-block\'>\r\n                <!--<div class=\'clear\'></div>-->\r\n                <div id=\"his-user\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px\">\r\n                    <span class=\"\"><label>Username : </label></span>	\r\n                    <input autofocus=\"\" type=\"text\" name=\"username\" id=\"input-username\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\">\r\n                </div>\r\n                <div id=\"his-pass\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Password  : </label></span>	\r\n                    <input type=\"password\" name=\"password\" id=\"input-password\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\">\r\n                </div>\r\n                <!--<div class=\'clear\'></div>-->\r\n            </span>\r\n<% end %>\r\n</span>\r\n\r\n<span id=\'span-btn\'>\r\n<% if session[:his] %>\r\n  <a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\r\n<% else %>\r\n  <span id=\'temp-his-logout\'>&nbsp;</span>\r\n  <a href=\'javascript:void(0)\' id=\'his-login\' class=\'btn btn-info\'>HIS Login</a>\r\n<% end %>\r\n</span>\r\n\r\n<% end %>\r\n            \r\n\r\n                <br/>\r\n                <div class=\'login-block btn btn-mini\' id=\'login-cancel\'  >x</div>\r\n                <span style=\'color:blue\' id=\'patient-msg\'></span>\r\n                <div class=\'clear\'></div>\r\n            \r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\" selected><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <div id=\'temporary\' style=\'\'></div>\r\n                <input type=\"hidden\" name=\"record[status]\" id=\"data-status\" value=\"Appointed\"/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Patient Record\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n\r\n    function init_fields(b) {\r\n        $(\'#data-public_id\').prop(\'readonly\', b);\r\n        $(\'#data-first_name\').prop(\'readonly\',b);\r\n        $(\'#data-last_name\').prop(\'readonly\',b);\r\n        $(\'#data-prefix_name\').prop(\'readonly\',b);\r\n        $(\'#input-prefix_name\').prop(\'readonly\',b);\r\n        $(\'#data-gender\').prop(\'readonly\',b);\r\n        $(\'#data-birth_date\').prop(\'readonly\',b);\r\n        \r\n        if (!b) {\r\n            $(\'#data-public_id\').val(\"\");\r\n            $(\'#data-first_name\').val(\"\");\r\n            $(\'#data-last_name\').val(\"\");\r\n            $(\'#data-prefix_name\').val(\"\");\r\n            $(\'#input-prefix_name\').val(\"\");\r\n            $(\'#data-gender\').val(\"\");\r\n            $(\'#data-birth_date\').val(\"<%= Time.now.strftime(\'%d/%m/%Y\') %>\");\r\n        }\r\n    }\r\n\r\n    function get_patient_info(us, ps, hn){\r\n        console.log(\'US:\' + us + \', PS:\' + ps + \',HN:\' + hn)\r\n        $(\'#his-status\').html(\'connecting...\');\r\n	    \r\n<% if his %>\r\n	\r\n	    var username = \'<%=his%>\'\r\n	    var password = \'-\'\r\n	\r\n<% end %>\r\n\r\n        // var hn=prompt(\"Please enter HN\",\"\");    \r\n        // var hn = hn\r\n        username = us;\r\n        password = ps;\r\n        if (hn==\'\') { \r\n            // alert(\"Not enough information!!\"); \r\n            $(\'#his-status\').html(\'No HN information, Please fill Patient HN\')\r\n        }else{     \r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading...</span>\');    \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            $.ajax({\r\n                url: \"get_patient_info?un=\"+username+\"&ps=\"+password+\"&hn=\"+hn,\r\n                context: document.body,\r\n                crossDomain: true\r\n            }).done(function(data) {\r\n                $(\'#his-status\').html(\'retriving...\');\r\n                // eval(data);\r\n                $(\'#temporary\').html(data);\r\n                $(\'#his-status\').html(\'completed\');\r\n                \r\n                if ($(\'#data-first_name\').val() != \'\') {\r\n                    init_fields(true);\r\n                } else {\r\n                    init_fields(false);\r\n                    $(\'#his-status\').html(\'Patient not found\')\r\n                }\r\n            }).fail(function(jqXHR, textStatus) {\r\n                // alert(\"error\");\r\n                $(\'#his-status\').html(\'Error loading, Please fill Patient information\')\r\n            });\r\n        }\r\n    }\r\n    \r\n    $(\'#get-his\').click(function() {\r\n        get_patient_info(\'<%= his %>\', \'-\', $(\'#data-hn\').val());\r\n    });\r\n	        \r\n	$(\'#his-logout\').click(function() {\r\n        $(\'#his-logout\').html(\'Loading ...\');\r\n        console.log(\'logout...\')\r\n        get_patient_info(\'-\', \'-\', \'-\');\r\n        // window.location = \'../Home/index\';\r\n    });\r\n    \r\n    $(document).ready(function(){\r\n        $(\'.login-block\').hide();\r\n        $(\'#his-login\').click(function() {\r\n            if ($(\'.login-block\').is(\":visible\")) {\r\n                $(\'#his-status\').show();\r\n                $(\'.login-block\').hide();\r\n                // console.log(\'get_patient_info\')\r\n                \r\n                \r\n    us = $(\'#input-username\').val();\r\n                ps = $(\'#input-password\').val();\r\n                hn = $(\'#data-hn\').val();\r\n                // $(\'#data-hn\').val(hn);\r\n                // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n                console.log(us + \'...\' + ps + \'...\' + hn);\r\n                $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n                get_patient_info(us, ps, hn);\r\n                \r\n                setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n                \r\n                // console.log(\'xxxx\');\r\n                // $(\'#his-status\').html(\'Logged as \' + us);\r\n                \r\n                $(\'#his-login\').hide();\r\n                $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n                $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient</a>\");\r\n                \r\n                // $(\'#modal\').modal(\'hide\')\r\n                // $(\'#modal\').attr(\'aria-hidden: false\');\r\n                // $(\'.modal-backdrop\').modal(\'hide\')\r\n                \r\n                // $(\'#commit\').click(function() {\r\n                //     console.log(\'login ...\')\r\n                //     us = $(\'#input-username\').val();\r\n                //     ps = $(\'#input-password\').val();\r\n                //     hn = $(\'#input-hn\').val();\r\n                //     get_patient_info(us, ps, hn);\r\n                //     console.log(\'... pass ...\')\r\n                // });\r\n                \r\n                $(\'#his-logout\').click(function() {\r\n            	    $(\'#his-logout\').html(\'Loading ...\');\r\n            	    console.log(\'logout...\')\r\n                    get_patient_info(\'-\', \'-\', \'-\');\r\n                    // window.location = \'../Home/index\';\r\n            	});\r\n                \r\n            } else {\r\n                $(\'#his-status\').hide();\r\n                $(\'.login-block\').show();\r\n                $(\'#his-login\').text(\'Get Patient\');\r\n                console.log(\'hide\')\r\n            }\r\n        })\r\n        $(\'#login-cancel\').click(function() {\r\n            $(\'#his-status\').show();\r\n            $(\'.login-block\').hide();\r\n            $(\'#his-login\').text(\'HIS Login\');\r\n        });\r\n        $(\'#commit\').click(function() {\r\n            us = $(\'#input-username\').val();\r\n            ps = $(\'#input-password\').val();\r\n            hn = $(\'#data-hn\').val();\r\n            // $(\'#data-hn\').val(hn);\r\n            // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n            // console.log(us + \'...\' + ps + \'...\' + hn);\r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n            get_patient_info(us, ps, hn);\r\n            \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            \r\n            // console.log(\'xxxx\');\r\n            // $(\'#his-status\').html(\'Logged as \' + us);\r\n            \r\n            $(\'#his-login\').hide();\r\n            $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n            $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient from HIS</a>\");\r\n            \r\n            // $(\'#modal\').modal(\'hide\')\r\n            // $(\'#modal\').attr(\'aria-hidden: false\');\r\n            // $(\'.modal-backdrop\').modal(\'hide\')\r\n            \r\n            // $(\'#commit\').click(function() {\r\n            //     console.log(\'login ...\')\r\n            //     us = $(\'#input-username\').val();\r\n            //     ps = $(\'#input-password\').val();\r\n            //     hn = $(\'#input-hn\').val();\r\n            //     get_patient_info(us, ps, hn);\r\n            //     console.log(\'... pass ...\')\r\n            // });\r\n            \r\n            $(\'#his-logout\').click(function() {\r\n        	    $(\'#his-logout\').html(\'Loading ...\');\r\n        	    console.log(\'logout...\')\r\n                get_patient_info(\'-\', \'-\', \'-\');\r\n                // window.location = \'../Home/index\';\r\n        	});\r\n        });\r\n    });\r\n</script>\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    \r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n	\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-hn\').val(\'\');\r\n        $(\'#patient-msg\').text(\'\');\r\n        init_fields(false);\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(\"[\" + data.hn + \"] \" + data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#data-hn\').val(data.hn);\r\n                $(\'#data-prefix_name\').val(data.prefix_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.toString().indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                // console.log(\'xxx \' + dd);\r\n                $(\'#data-birth_date\').val(dd);\r\n                $(\'#patient-msg\').text(\'Patient found in DB\');\r\n                init_fields(true);\r\n                // console.log(\'init field = true\')\r\n            } else {\r\n                $(\'#patient-msg\').text(\'Patient not found in DB. Please fill patient info.\');\r\n                init_fields(false);\r\n                // console.log(\'init field = false\')\r\n            }\r\n            \r\n            console.log(\"... \" + $(this).val())\r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#data-hn\').keyup(update_patient);\r\n    });\r\n</script>\r\n\r\n<script>\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'index_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        setTimeout(feed_page(100), 0);\r\n        loadPartial();\r\n    });\r\n    \r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2017-02-14 08:08:55','2017-02-14 08:08:55','index',''),(2932,'pdf',872,3,'<%= render :inline=>this.print_partial %>\r\n\r\n<%\r\n    # url = params[:url]\r\n    \r\n    # pdf_file = \"/tmp/demo.pdf\"\r\n\r\n    # kit = PDFKit.new(url,:margin_top => \'0.2in\',:margin_right => \'0.2in\',:margin_bottom => \'0.2in\',:javascript_delay => 1000)\r\n    # file = kit.to_file(pdf_file)\r\n%>\r\n<%# file %>\r\n<%# send_file(file, :filename => \"your_document.pdf\", :type => \"application/pdf\") %>',NULL,NULL,NULL,'2017-02-15 04:23:20','2017-02-15 04:23:20','pdf','*'),(2933,'show_pdf',872,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   atts = @ehr_project.get_model :attachment\r\n   att =  atts.find(@patient_module.report)\r\n   if att\r\n%>\r\n<%# att.inspect  %>\r\n<embed src=\"<%= att.path%>\" width=\"100%\" height=\"100%\"/>\r\n<% else %>\r\n<%= this.print_partial.html_safe %>\r\n<% end %>',NULL,NULL,NULL,'2017-02-15 04:48:03','2017-02-15 04:48:03','show_pdf','*'),(2934,'attach_pdf',872,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    if params[:path]\r\n        \r\n        field = @module_doc .find_by_column_name \'report\'\r\n        att = @module_doc .attach_field_file field.id, params[:path].split(\'/\')[-1] , \'\', File.open(params[:path])\r\n        @patient_module.update_attributes :report=>att.id\r\n    \r\n%>\r\nOK\r\n<%\r\n    else\r\n%>\r\n    Error\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2017-02-15 07:06:55','2017-02-15 07:06:55','attach_pdf','*'),(2935,'pdf',873,3,'<%= render :inline=>this.print_partial %>\r\n',NULL,NULL,NULL,'2017-02-15 07:38:39','2017-02-15 07:38:39','pdf','*'),(2936,'pdf',882,3,'<%= render :inline=>this.print_partial %>\r\n',NULL,NULL,NULL,'2017-02-15 07:47:55','2017-02-15 07:47:55','pdf','*'),(2937,'edit',881,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  return_url = \"../Pacu/edit?id=\\\\#{params[:pm]}&return=../Home/patient_record?id=\\\\#{params[:ap]}\".html_safe\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    # return_url = \"show?id=\\\\#{record.id}\"\r\n    return_url = \"../Pacu/edit?id=\\\\#{params[:pm]}&return=../Home/patient_record?id=\\\\#{params[:ap]}\".html_safe\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n<%# params.to_json.html_safe %>\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%= hidden_field_tag :pm,  params[:pm] %>\r\n<%= hidden_field_tag :ap,  params[:ap] %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    function painscore_update() {\r\n        tmp = parseInt($(this).val());\r\n        obj = $(\'#data-pain\');\r\n        if (tmp <= 4) {\r\n            obj.val(\'2\');\r\n        } else if (tmp == 5 || tmp == 6) {\r\n            obj.val(\'1\');\r\n        } else {\r\n            obj.val(\'0\');\r\n        }\r\n        // console.log(\'SCORE : \' + tmp);\r\n    }\r\n    \r\n    $(\'#data-pain_score\').change(painscore_update);\r\n    $(\'#pacu_ref_id\').hide();\r\n</script>',NULL,NULL,NULL,'2017-02-15 08:05:51','2017-02-15 08:05:51','edit',''),(2938,'destroy',881,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  @record.destroy \r\n  \r\n  return_url = \"../Pacu/edit?id=\\#{params[:pm]}&return=../Home/patient_record?id=\\#{params[:ap]}\".html_safe\r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=<%= return_url %>\">',NULL,NULL,NULL,'2017-02-15 14:41:28','2017-02-15 14:41:28','destroy',''),(2939,'edit',875,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n    return_url = \"../Pacu/edit?id=\\\\#{params[:pm]}&return=../Home/patient_record?id=\\\\#{params[:ap]}\".html_safe\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    return_url = \"../Pacu/edit?id=\\\\#{params[:pm]}&return=../Home/patient_record?id=\\\\#{params[:ap]}\".html_safe\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<%= hidden_field_tag :pm,  params[:pm] %>\r\n<%= hidden_field_tag :ap,  params[:ap] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n    $(\'#dx_pacu_ref_id\').hide();\r\n</script>',NULL,NULL,NULL,'2017-02-15 15:12:04','2017-02-15 15:12:04','edit',''),(2940,'destroy',875,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  @record.destroy \r\n  \r\n  return_url = \"../Pacu/edit?id=\\#{params[:pm]}&return=../Home/patient_record?id=\\#{params[:ap]}\".html_safe\r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=<%= return_url %>\">',NULL,NULL,NULL,'2017-02-15 15:12:49','2017-02-15 15:12:49','destroy',''),(2941,'his_show',878,1,'false',NULL,NULL,NULL,'2017-02-15 15:40:25','2017-02-15 15:40:25','his_show',''),(2942,'document_name',1179,1,'\'ve_record\'',NULL,NULL,NULL,'2017-02-16 15:05:23','2017-02-16 15:05:23',NULL,NULL),(2943,'document_name',1180,1,'\'ve_test\'',NULL,NULL,NULL,'2017-02-16 15:29:49','2017-02-16 15:29:49',NULL,NULL),(2944,'print',1179,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n	# id of operative note\r\n	\r\n	models  = @models\r\n	pm = @module_model.find(params[:id])\r\n	colono_id = pm.module_id\r\n	record = models[:ve_record].find(colono_id)\r\n	@record = record\r\n	@document = get_document this.document_name\r\n	\r\n	\r\n	def get_render_value(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return \'-\'\r\n	    else\r\n	        return render_value(f.to_s)\r\n	    end\r\n	end\r\n	\r\n	def get_value(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return \'-\'\r\n	    else\r\n	        return @record[f]\r\n	    end\r\n	end\r\n	\r\n	def is_exist(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return false\r\n	    else\r\n	        return true\r\n	    end\r\n	end\r\n	\r\n	\r\n	endoscopist_1 = render_value(\'surgeon_1\')\r\n	endoscopist_2 = render_value(\'endoscopist_2\')\r\n	\r\n	if @patient \r\n	    patient = @patient\r\n	    date = pm.created_at.to_datetime\r\n	    birth_date = patient.birth_date \r\n	    year = month = day = \'0\'\r\n	    if date and birth_date\r\n	        t = date-birth_date    \r\n	        year = (t/365).to_i\r\n	        t%=365\r\n	        month = (t/30).to_i\r\n	        t%=30\r\n	        day = t.to_i\r\n	    end\r\n	end \r\n%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>PRINT</title>\r\n	</head>\r\n	<style type=\"text/css\" media=\"all\">\r\n		html { }\r\n		#page {border:solid 0px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n		#head { width:100%; height:140px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-size: 1.5em; margin: .83em 0 }\r\n		h3              { font-size: 1.17em; margin: 1em 0 }\r\n		p {color:#666;}\r\n		h4, p,\r\n		blockquote, ul,\r\n		form,\r\n		ol, dl          { margin: 0.5em; }\r\n		h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n		h6              { font-size: .67em; margin: 2.33em 0 }\r\n		h4 { font-size:14pt; color:#333; height:16px;}\r\n		blockquote      { margin-left: 40px; margin-right: 40px }\r\n		i, cite, em,\r\n		var, address    { font-style: italic }\r\n		pre, tt, code,\r\n		kbd, samp       {  font-size:14px; }\r\n		pre             {margin:0;margin-left:1em; color:#666}\r\n		big             { font-size: 1.17em }\r\n		v {color:#2561cD;}\r\n		small, sub, sup { font-size: .83em }\r\n		ol, ul, dd      { margin-left: 40px }\r\n		ol              { list-style-type: decimal }\r\n		ol ul, ul ol,\r\n		ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n		.clear{clear:both;}\r\n		@media print {\r\n		@page         { width:960px; margin-top:0; }\r\n		blockquote, \r\n		.wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n		}\r\n		#box{\r\n		width:215px;\r\n		float:left;\r\n		padding:0px;\r\n		text-align:center;\r\n		border:0px solid #ccc;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */    \r\n		margin:5px;\r\n		font-size:0.8em;\r\n		height:190px;\r\n		overflow:hidden;\r\n		}\r\n		.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n		#box img{\r\n		height:170px; margin-left:-50px;\r\n		}\r\n		label{\r\n		color:#666;\r\n		}\r\n		.sidationcss\r\n		{width:160px; float:left; margin-bottom:3px;}\r\n	</style>\r\n	<body>\r\n		<div class=\"wrapper\">\r\n			<div id=\"head\" class=\"well\">\r\n				<div id=\"logoleft\" style=\"width:600px; float:left;\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n					<br />\r\n					First Name : \r\n					<v><%= patient.prefix_name %> <%= patient.first_name %></v>\r\n					<br />\r\n					Last Name : \r\n					<v><%= patient.last_name %></v>\r\n					<br />\r\n					HN :&nbsp;\r\n					<v><%=patient.hn%></v>\r\n					<br />\r\n					Age :&nbsp;\r\n					<v><%= year%> Year <%=month%> Month <%= day%> Day </v>\r\n					<br />\r\n					Gender :&nbsp;\r\n					<v><%=patient.gender==\'1\'?\'Male\':\'Female\'%></v>\r\n					<br />\r\n					Date :&nbsp;\r\n					<v><%=render_value \'date\'%></v>\r\n					<br />\r\n				</div>\r\n				<div id=\"logoright\">\r\n				\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n			</div>\r\n			<div id=\"page\">\r\n				<div class=\"clear\"></div>\r\n               \r\n                \r\n    <%\r\n        # atts = models[:attachment].find(record.images)\r\n        # atts = record.images[0..4].compact.collect{|i| models[:attachment].find(i)}\r\n   \r\n       atts_list = record.images[0..4]\r\n       if record[:selected_image] and record.selected_image and record.selected_image.size > 0\r\n          \r\n           atts_list = record.selected_image[0..4]\r\n           \r\n       end\r\n       \r\n       \r\n       atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n\r\n    %>\r\n\r\n    <div style=\"float:right;  width: 280px;  padding: 1px; text-align:center; font-size:14px;\">\r\n    <% for i in atts  %>\r\n    <img src=\"<%=i.path%>\" width=\"270\" height=\"200\" style=\"margin:5px\"/><br /><%=i.title%><br />\r\n    <% end %>\r\n    </div>\r\n				<!--      -->\r\n				<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:600px;margin:0px;min-height:50px; float:left\" >\r\n					<div id=\"622-F1252719607\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background-color:#dff0d8;\r\n						padding:5px;\">\r\n						<b>Information</b>\r\n					</div>\r\n				\r\n\r\n						<div style=\"width:200px; float:left\"><span class=\"\" ><label>Date :</label></span>	<v><%=render_value \'date\'%></v></div>\r\n                        <div id=\"tracheotomy\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n                       <% if record[\'tube\']!=\'\' %><span class=\"\"><label>Tube :</label></span>	<v><%=render_value \'tube\'%></v><% end%>\r\