LL,NULL,NULL,'2017-02-20 01:58:13','2017-02-20 01:58:13','test2',''),(2950,'document_name',1181,1,'\'test_form\'',NULL,NULL,NULL,'2017-02-20 03:28:49','2017-02-20 03:28:49',NULL,NULL),(2951,'document_name',1182,1,'\'basic_exam\'',NULL,NULL,NULL,'2017-02-20 04:37:37','2017-02-20 04:37:37',NULL,NULL),(2952,'show',1182,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<%= Time.now %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n\r\n\r\n<%= this.display.html_safe %>\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-02-20 04:42:08','2017-02-20 04:42:08','show',''),(2953,'form',1182,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n\r\n<script>\r\n\r\n    function cal(){\r\n         w = parseInt($(\'#data-weight\').val())\r\n         h = parseInt($(\'#data-height\').val())\r\n         $(\'#data-bmi\').val(w+h)\r\n         \r\n    }\r\n    $(\'#data-weight\').change(cal);\r\n    $(\'#data-height\').change(cal);\r\n    \r\n</script>',NULL,NULL,NULL,'2017-02-20 04:43:31','2017-02-20 04:43:31','form',''),(2954,'document_name',1183,1,'\'op\'',NULL,NULL,NULL,'2017-02-21 00:40:41','2017-02-21 00:40:41',NULL,NULL),(2955,'show',1161,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn\' %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-02-25 15:03:23','2017-02-25 15:03:23','show',''),(2956,'footer',608,4,'<h3>Created by Soup</h3>',NULL,NULL,NULL,'2017-02-27 03:31:40','2017-02-27 03:31:40','footer',''),(2957,'get_time',608,1,'\r\n\r\nreturn Time.now ',NULL,NULL,NULL,'2017-02-27 03:32:49','2017-02-27 03:32:49','get_time',''),(2958,'redefine',608,5,'\r\n\r\ndef get_time\r\n    return Time.now.strftime(\"%H:%M\")\r\nend',NULL,NULL,NULL,'2017-02-27 03:35:17','2017-02-27 03:35:17','redefine',''),(2959,'index',1184,2,'<h1>Inventory Reports</h1>\r\n\r\n\r\n<%\r\n\r\n  @from_date = Time.now.beginning_of_year\r\n  @to_date = Time.now\r\n\r\n  if params[:query] \r\n  a =   (%w(1 2 3).collect { |e| params[:query][\"from_date(\\\\#{e}i)\"].to_i }) \r\n  @from_date = Date.to_mongo(a.join(\"-\")) \r\n  a =   (%w(1 2 3).collect { |e| params[:query][\"to_date(\\\\#{e}i)\"].to_i }) \r\n  @to_date = Date.to_mongo(a.join(\"-\")).end_of_day\r\n  end\r\n    \r\n    models = get_model\r\n\r\n\r\n    products = models[:product].all :order=>\'manufacture, name\'\r\n    \r\n    \r\n    orders =  models[:order].collection.find({:created_at=>{\'$gte\'=>@from_date,\'$lte\'=>@to_date},:order_type=>\'usage\',:status=>\'Completed\'},{:fields=>{\'items\'=>1,\'_id\'=>1,\'created_at\'=>1,\'order_type\'=>1,\'status\'=>1}}).to_a\r\n\r\n    items = []\r\n    \r\n    order_items = {}\r\n    \r\n    for i in orders\r\n        items += i[\'items\']\r\n    end\r\n    \r\n    its = models[:order_item].collection.find({:_id=>{\'$in\'=>items}}).to_a\r\n    \r\n    for i in its\r\n    \r\n        order_items[i[\'_id\']] = i \r\n    end\r\n    \r\n    now = Time.now\r\n    \r\n    pm = {}\r\n    \r\n    max = 0 \r\n    psum = {}\r\n    \r\n    for i in orders\r\n    \r\n        time = (( now - i[\'created_at\'])/3600/24/7).round+1\r\n    \r\n        max = time if max < time\r\n        \r\n        for j in i[\'items\']\r\n        \r\n            item = order_items[j]\r\n           \r\n            if item\r\n                pm[item[\'product_id\']] = {} unless pm[item[\'product_id\']]\r\n                pm[item[\'product_id\']][time] = 0 unless pm[item[\'product_id\']][time]\r\n                pm[item[\'product_id\']][time] += item[\'quantity\']\r\n                psum[item[\'product_id\']] = 0 unless   psum[item[\'product_id\']]\r\n                psum[item[\'product_id\']] += item[\'quantity\']\r\n                \r\n            end\r\n        \r\n        end\r\n    \r\n    end\r\n    \r\n    \r\n    ssum = {}\r\n    \r\n    stores = models[:store].all\r\n    \r\n    for s in stores\r\n        \r\n        ssum[s.id] = {} unless ssum[s.id] \r\n        items = models[:store_item].collection.find({:store_id=>s.id}).to_a\r\n        for si in items\r\n             ssum[s.id][si[\'product_id\']] = si[\'balance\'] unless  ssum[s.id][si[\'product_id\']]\r\n             \r\n        end\r\n    \r\n        \r\n    end\r\n    \r\n    \r\n    \r\n      \r\n%>\r\n<style>\r\n    select{\r\n        width:100px\r\n        \r\n    }\r\n    .balance{\r\n        background:#eee;\r\n    }\r\n</style>\r\n<%=form_for :query, :url=>\"index\" do |f|  %>\r\nFrom <%= f.date_select \'from_date\' ,:default=>@from_date , :order=>[:day, :month,:year] %> to <%= f.date_select \'to_date\', :default=>@to_date, :order=>[:day,:month,:year] %> \r\n<%= f.submit \'Submit\' %>\r\n<% end %>\r\n\r\n<% if request.post? %>\r\nPeriod : <%= @from_date.strftime(\"%d/%m/%Y\")%> - <%= @to_date.strftime(\"%d/%m/%Y\")%>\r\n<%# m_all_pm_colo.inspect %><br/>\r\n<%#labels.inspect   %> \r\n\r\n<% end %>\r\n\r\n<table class=\"table\" style=\"\" >\r\n<thead>\r\n    <tr>\r\n        <th>Name</th>\r\n        <th>Manufacture</th>\r\n        <th>Code</th>\r\n        <th>Barcode</th>\r\n        \r\n    \r\n        <% max.times do |j| \r\n%>\r\n<th>\r\n<%=j+1%>w\r\n</th>\r\n<% end %>\r\n\r\n\r\n<% stores.each do |s| %>\r\n    <th><%=s.name%></th>\r\n    <% end %>\r\n    <th>Total</th>\r\n    \r\n    \r\n    </tr>\r\n    \r\n    \r\n</thead>\r\n<tbody>\r\n<% \r\n\r\n    for i in products#.sort{|a,b| psum[a.id]<=>psum[b.id] } \r\n    sum = 0 \r\n    \r\n%>\r\n\r\n<tr>\r\n<td><%= i.name %> </td>\r\n<td><%= i.manufacture %></td>\r\n<td><%= i.code %></td>\r\n<td><%= i.barcode %></td>\r\n\r\n<% max.times do |j| \r\n%>\r\n<td>\r\n<% \r\n   p = nil\r\n   p = pm[i.id][j+1] if pm[i.id]\r\n\r\n  if p \r\n      sum+=p\r\n%>\r\n<% end %>\r\n\r\n<%= sum>0?sum:\'-\'%>\r\n</td>\r\n<% end %>\r\n<% \r\n    stotal = 0 \r\n    stores.each do |s|\r\n    \r\n    si = 0 \r\n    \r\n    si = ssum[s.id][i.id] if ssum[s.id][i.id]\r\n    \r\n    stotal += si\r\n    \r\n    %>\r\n    <td class=\"balance\"><%=si!=0?si:\'-\'%></td>\r\n    <% end %>\r\n    <td><%=stotal%></td>\r\n</tr>\r\n<% end %>\r\n</tbody>\r\n    \r\n</table>\r\n\r\n',NULL,NULL,NULL,'2017-02-28 07:35:31','2017-02-28 07:35:31','index',''),(2960,'print',1174,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%= render :inline=>this.common_function %>\r\n<%\r\n	# id of operative note\r\n	\r\n	models  = @models\r\n	pm = @module_model.find(params[:id])\r\n	c_id = pm.module_id\r\n	record = models[:nurse_note].find(c_id)\r\n	@record = record\r\n	@document = get_document this.document_name\r\n	\r\n	@doc_name = this.document_name\r\n	set_document_object(@doc_name, @record)\r\n	df = get_document_field(\'nurse_note\')\r\n	   	\r\n	def get_render_value(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return \'-\'\r\n	    else\r\n	        return render_value(f.to_s)\r\n	    end\r\n	end\r\n	\r\n	def get_value(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return \'-\'\r\n	    else\r\n	        return @record[f]\r\n	    end\r\n	end\r\n	\r\n	def is_exist(field)\r\n	    f = field.to_sym\r\n	    if @record[f].nil? or @record[f]==\'\'\r\n	        return false\r\n	    else\r\n	        return true\r\n	    end\r\n	end\r\n	\r\n	\r\n	endoscopist_1 = render_value(\'surgeon_1\')\r\n	endoscopist_2 = render_value(\'endoscopist_2\')\r\n	\r\n	if @patient \r\n	    patient = @patient\r\n	    date = pm.created_at.to_datetime\r\n	    birth_date = patient.birth_date \r\n	    year = month = day = \'0\'\r\n	    if date and birth_date\r\n	        t = date-birth_date    \r\n	        year = (t/365).to_i\r\n	        t%=365\r\n	        month = (t/30).to_i\r\n	        t%=30\r\n	        day = t.to_i\r\n	    end\r\n	end \r\n	%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>PRINT</title>\r\n	</head>\r\n	<style type=\"text/css\" media=\"all\">\r\n		html { }\r\n		#page {border:solid 1px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n		#head { width:100%; height:140px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-size: 1.5em; margin: .83em 0 }\r\n		h3              { font-size: 1.17em; margin: 1em 0 }\r\n		p {color:#666;}\r\n		h4, p,\r\n		blockquote, ul,\r\n		form,\r\n		ol, dl          { margin: 0.5em; }\r\n		h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n		h6              { font-size: .67em; margin: 2.33em 0 }\r\n		h4 { font-size:14pt; color:#333; height:16px;}\r\n		blockquote      { margin-left: 40px; margin-right: 40px }\r\n		i, cite, em,\r\n		var, address    { font-style: italic }\r\n		pre, tt, code,\r\n		kbd, samp       {  font-size:14px; }\r\n		pre             {margin:0;margin-left:1em; color:#666}\r\n		big             { font-size: 1.17em }\r\n		v {color:#2561cD;}\r\n		small, sub, sup { font-size: .83em }\r\n		ol, ul, dd      { margin-left: 40px }\r\n		ol              { list-style-type: decimal }\r\n		ol ul, ul ol,\r\n		ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n		.clear{clear:both;}\r\n		@media print {\r\n		@page         { width:960px; margin-top:0; }\r\n		blockquote, \r\n		.wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n		}\r\n		#box{\r\n		width:215px;\r\n		float:left;\r\n		padding:0px;\r\n		text-align:center;\r\n		border:1px solid #ccc;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */    \r\n		margin:5px;\r\n		font-size:0.8em;\r\n		height:170px;\r\n		overflow:hidden;\r\n		}\r\n		.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n		#box img{\r\n		height:170px; margin-left:-50px;\r\n		}\r\n		label{\r\n		color:#666;\r\n		}\r\n		.sidationcss\r\n		{width:160px; float:left; margin-bottom:3px;}\r\n		.tb {\r\n						border-collapse: collapse;\r\n						}\r\n						.tc {\r\n						border: 1px solid #ddd;\r\n						padding: 5px;\r\n						text-align: center;\r\n						}\r\n	</style>\r\n	<body>\r\n		<div class=\"wrapper\">\r\n			<div id=\"head\" class=\"well\">\r\n				<div id=\"logoleft\" style=\"width:600px; float:left\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n					<br />\r\n					First Name : \r\n					<v><%= patient.prefix_name %> <%= patient.first_name %></v>\r\n					<br />\r\n					Last Name : \r\n					<v><%= patient.last_name %></v>\r\n					<br />\r\n					HN :&nbsp;\r\n					<v><%=patient.hn%></v>\r\n					<br />\r\n					Age :&nbsp;\r\n					<v><%= year%> Year <%=month%> Month <%= day%> Day </v>\r\n					<br />\r\n					Gender :&nbsp;\r\n					<v><%=patient.gender%></v>\r\n					<br />\r\n					Date :&nbsp;\r\n					<v></v>\r\n					<br />\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now %></p>\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n			</div>\r\n			<div id=\"page\">\r\n				<div class=\"clear\"></div>\r\n				<!--      -->\r\n				<div id=\"622-F1252719607\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;background-color:#dff0d8;\r\n					padding:5px;\">\r\n					<b>Nurse Note</b>\r\n				</div>\r\n				<div id=\"onset_year\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<label> Onset&nbsp;Year: </label>\r\n					<v><%=render_value \'onset_year\'%></v>\r\n				</div>\r\n				<div id=\"onset_month\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<label> Onset&nbsp;Month: </label>\r\n					<v><%=render_value \'onset_month\'%></v>\r\n				</div>\r\n				<div id=\"onset_day\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<label> Onset&nbsp;day: </label>\r\n					<v><%=render_value \'onset_day\'%></v>\r\n				</div>\r\n				<div id=\"726-F5766562186\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n				</div>\r\n				<div id=\"chief_complaints\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;border:1px solid #eee;;\">\r\n					<span class=\"\"><label>Chief complaints : </label></span>\r\n					<v><%=render_value \'chief_complaints\'%></v>\r\n				</div>\r\n				<div id=\"comorbid_disease\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:360px;border:1px solid #eee; ;\">\r\n					<span class=\"\"><label>Co-morbid disease : </label></span>\r\n					<v><%=render_value \'comorbid_disease\'%></v>\r\n				</div>\r\n				<div id=\"past_history_of_cancer\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;border:1px solid #eee; ;\">\r\n					<span class=\"\"><label>Past History of Cancer : </label></span>\r\n					<v><%=render_value \'past_history_of_cancer\'%></v>\r\n					<% if is_exist(\'past_history_of_cancer_note\') %>\r\n					<br/>\r\n					Note: <v><%= val \'past_history_of_cancer_note\' %></v>\r\n					<% end %>\r\n				</div>\r\n				<div id=\"726-F7369355452\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n				</div>\r\n				<div style=\'float:left;width:48%\'>\r\n    				<div id=\"anticoagulant_usage\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;border:1px solid #eee;;\">\r\n    					<span class=\"\"><label>Anticoagulant usage : </label></span>\r\n    					<v><%= val(\'anticoagulant_usage\')%></v> \r\n    					<br/>\r\n    					<label>Note : </label> <v><%= val \'anticoagulant_usage_note\' %></v>\r\n    				</div>\r\n    				<div id=\"others\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left\">\r\n    					<span class=\"\"><label>Others : </label></span>\r\n    					<v><%=render_value \'others\'%></v>\r\n    				</div>\r\n    				<div class=\'clear\'></div>\r\n    				<div id=\"smoking\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n    					<span class=\"\"><label>Smoking : </label></span>\r\n    					<v><%=render_value \'smoking\'%></v>\r\n    				</div>\r\n    				<div id=\"smoking_pack\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n    					<span class=\"\"><label>Smoking pack : </label></span>\r\n    					<v><%=render_value \'smoking_pack\'%></v>\r\n    				</div>\r\n    				\r\n    				<div id=\"bw\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n    					<label> BW&nbsp;: </label>\r\n    					<v><%=render_value \'bw\'%></v>\r\n    				</div>\r\n    				<div id=\"ht\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n    					<label> HT&nbsp;: </label>\r\n    					<v><%=render_value \'ht\'%></v>\r\n    				</div>\r\n    				<div id=\"bmi\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n    					<label> BMI&nbsp;: </label>\r\n    					<v><%=render_value \'bmi\'%></v>\r\n    				</div>\r\n    				\r\n				</div>\r\n\r\n				<div id=\"drug_usage\" class=\"  portlet \" style=\"float:right;border:0px solid blue;width:49%;margin: 0 0.5em 0.5em 0;float:left;border:1px solid #eee;padding:5px;\">\r\n                    <span class=\"\"><b>Drug usage : </b></span><br/>\r\n<%\r\n    # drug_usage\r\n    if @record[:drug_usage].nil? or @record[:drug_usage]==\'\'\r\n%>\r\n                    <v>N/A</v>\r\n<%  \r\n    else \r\n%>\r\n                    <table bordercolor=\"#999999\" class=\'tb tc\' width=\'100%\'>\r\n										<tr>\r\n											<th class=\'tc\' width=\'10%\'>No.</th>\r\n											<th class=\'tc\' width=\'60%\'>Drug</th>\r\n											<th class=\'tc\' width=\'30%\'>Stop date</th>\r\n										</tr>\r\n<%\r\n        du = get_model[:drug_usage].find(@record[:drug_usage])\r\n        du.each_with_index do |i, idx|\r\n%>\r\n                        <tr>\r\n                            <td class=\'tc\'><%= idx + 1 %>.</td>\r\n                            <td class=\'tc\'><v><%= i[:drug] %></v></td>\r\n                            <td class=\'tc\'><%= i[:stop_date].nil? ? \'N/A\' : i[:stop_date].strftime(\'%d/%m/%Y\') %></td>\r\n                        </tr>\r\n<%  \r\n        end \r\n%>\r\n                    </table>\r\n<%\r\n    end\r\n%>					\r\n				</div>\r\n				\r\n				<div class=\'clear\'></div>\r\n				<!--\r\n				<div id=\"anticoagulant_stop_date\" class=\"  portlet \" style=\"border:0px solid blue;width:250px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>Anticoagulant stop date : </label></span>\r\n					<v><%=render_value \'anticoagulant_stop_date\'%></v>\r\n				</div>\r\n				<div id=\"aspirin_stop_date\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>Aspirin stop date : </label></span>\r\n					<v><%=render_value \'aspirin_stop_date\'%></v>\r\n				</div>\r\n				<div id=\"clopidogrel_stop_date\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>Clopidogrel stop date : </label></span>\r\n					<v><%=render_value \'clopidogrel_stop_date\'%></v>\r\n				</div>\r\n				-->\r\n				\r\n				<div id=\"726-F2172137553\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n				</div>\r\n				\r\n				<div class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n					<b>Patient\'s status on Arrival at Pulmonary Intervention Suite</b>\r\n				</div>\r\n				\r\n				<div class=\"  portlet \" style=\"border:0px solid blue;width:700px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\">Arrival time : </span>\r\n					<v><%=render_value \'d1_arrival_time\'%></v>\r\n				</div>\r\n				<br/>\r\n				<!-- vital d1_xxx -->\r\n				<table bordercolor=\"#999999\" class=\'tb tc\' width=\'100%\'>\r\n										<tr>\r\n										    <td class=\'tc\' style=\'text-align:left\'><b>BP</b> <v><%= val \'d1_bp\' %></v> mmHg</td>\r\n										    <td class=\'tc\' style=\'text-align:left\'><b>HR</b> <v><%= val \'d1_hr\' %></v> /min</td>\r\n										    <td class=\'tc\' style=\'text-align:left\'><b>RR</b> <v><%= val \'d1_rr\' %></v> /min</td>\r\n										    <td class=\'tc\' style=\'text-align:left\'><b>O<sub>2</sub>sat</b> <v><%= val \'d1_o2\' %></v> %</td>\r\n										</tr>\r\n										<tr>\r\n										    <td class=\'tc\' colspan=\'4\' style=\'text-align:left\'>\r\n<%\r\n    d1_f = @obj[:nurse_note][:df][:d1_environment][:pair]\r\n    d1_r = @obj[:nurse_note][:rec][:d1_environment]\r\n    d1_r = (d1_r.nil? or d1_r==\'\') ? [] : d1_r.split(\'|\')\r\n    \r\n    d1_f.each do |k,v|\r\n        i = false\r\n        c = \"[&nbsp;&nbsp;&nbsp;]\"\r\n        if d1_r.include? k\r\n            i = true\r\n            c = \"[&nbsp;/&nbsp;]\"\r\n        end\r\n        \r\n        x = \'\'\r\n        if i\r\n            if k == \'2\'\r\n                x = \"<v><u>&nbsp;&nbsp;\\\\#{val(\'d1_cannular\')}&nbsp;&nbsp;</u></v> LPM\"\r\n            elsif k == \'3\'\r\n                x = \"<v><u>&nbsp;&nbsp;\\\\#{val(\'d1_oxygen\')}&nbsp;&nbsp;</u></v> LPM\"\r\n            elsif k == \'4\'\r\n                x = \"<v><u>&nbsp;&nbsp;\\\\#{val(\'d1_tpiece\')},&nbsp;\\\\#{val(\'d1_fio2\')}&nbsp;&nbsp;</u></v> LPM\"\r\n            elsif k == \'5\'\r\n                x = \", setting <v><u>&nbsp;&nbsp;\\\\#{val(\'d1_setting\')}&nbsp;&nbsp;</u></v> LPM\"\r\n            end\r\n        else\r\n            x = \'<u>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</u>\'\r\n        end\r\n%>\r\n<div style=\'width:30%;float:left;line-height:18px\'><%= c.html_safe %> <%= v %> <%= x.html_safe %></div>\r\n<%  end %>\r\n										    </td>\r\n										</tr>\r\n				</table>\r\n				<br/>\r\n				<!-- end vital -->\r\n				\r\n				<div id=\"comment\" class=\"  portlet \" style=\"border:0px solid blue;width:700px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>Comment : </label></span>\r\n					<v><%=render_value \'comment\'%></v>\r\n				</div>\r\n				<div id=\"ve_test\" class=\"  portlet \" style=\"border:0px solid blue;width:100%;margin: 0 0.5em 0.5em 0;float:left;\">\r\n				    <div class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n    					<b><b>Medication &amp; Vital signs</b></b>\r\n    				</div>\r\n					<%\r\n						tmp_rec = @record\r\n						tmp_doc = @document\r\n						\r\n						@document = get_document \'medi_vital\'\r\n						\r\n						# ve many\r\n						vm = @record[:mv_records]\r\n						# medi_vital list\r\n						vl = get_model[:medi_vital].find(vm)\r\n						\r\n						\r\n						%>\r\n					<style>\r\n						\r\n					</style>\r\n					<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n						<div id=\"F0887825841\">\r\n							<div id=\"583530fc790f9b351e000030\" >\r\n								<div id=\"ve_record-ve_test-583530fc790f9b351e000030-623-F5742127698\" class=\"   field\" style=\"clear:both;text-align:left\">\r\n									<table bordercolor=\"#999999\" class=\'tb tc\' width=\'100%\'>\r\n										<tr>\r\n											<th class=\'tc\' width=\'5%\'>No.</th>\r\n											<th class=\'tc\' width=\'10%\'>Time</th>\r\n											<th class=\'tc\' width=\'10%\'>BP</th>\r\n											<th class=\'tc\' width=\'10%\'>HR</th>\r\n											<th class=\'tc\' width=\'10%\'>RR</th>\r\n											<th class=\'tc\' width=\'10%\'>O<sub>2</sub>sat</th>\r\n											<th class=\'tc\'>IV/Medication</th>\r\n										</tr>\r\n										<%\r\n											idx = 0\r\n											vl.each do |i|\r\n											    idx += 1\r\n											    @record = i\r\n											%>\r\n										<tr>\r\n											<td class=\'tc\'>\r\n												<v><%= idx %>.</v>\r\n											</td>\r\n											<td class=\'tc\'>\r\n												<v><%= get_render_value(:time) %></v>\r\n											</td>\r\n											<td class=\'tc\'>\r\n												<v><%= get_render_value(:bp) %></v>\r\n											</td>\r\n											<td class=\'tc\'>\r\n												<v><%= get_render_value(:hr) %></v>\r\n											</td>\r\n											<td class=\'tc\'>\r\n												<v><%= get_render_value(:rr) %></v>\r\n											</td>\r\n											<td class=\'tc\'>\r\n												<v><%= get_render_value(:osat) %></v>\r\n											</td>\r\n											<td class=\'tc\' style=\'text-align:left\'>\r\n												<%\r\n													med = []\r\n													med << \"Midazolam : <v>\\\\#{i[:midazolam_mg]}</v> mg\".html_safe unless i[:midazolam_mg].nil? or i[:midazolam_mg] == \'\' \r\n													med << \"Fentanyl : <v>\\\\#{i[:fentanyl_mcg]}</v> mcg\".html_safe unless i[:fentanyl_mcg].nil? or i[:fentanyl_mcg] == \'\' \r\n													med << \"Propofol : <v>\\\\#{i[:propofol_mg]}</v> mg\".html_safe unless i[:propofol_mg].nil? or i[:propofol_mg] == \'\' \r\n													med << \"Other : <v>\\\\#{i[:other_note]}</v> \".html_safe unless i[:other_note].nil? or i[:other_note] == \'\' \r\n													\r\n													%>\r\n												<%= med.join(\',&nbsp;&nbsp;\').html_safe %>\r\n											</td>\r\n										</tr>\r\n										<%\r\n											end\r\n											%>\r\n									</table>\r\n								</div>\r\n							</div>\r\n						</div>\r\n					</div>\r\n					<div class=\"clear\"></div>\r\n					<%\r\n						@record   = tmp_rec\r\n						@document = tmp_doc\r\n						%>\r\n				</div>\r\n				<div id=\"726-F6118707286\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n					<b>Pre-Operative Note</b>\r\n				</div>\r\n				<div id=\"labs_note\" class=\"  portlet \" style=\"border:0px solid blue; width:350px; margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>Labs note : </label></span>\r\n					<v><%=render_value \'labs_note\'%></v>\r\n				</div>\r\n				<div id=\"medicine_note\" class=\"  portlet \" style=\"border:0px solid blue;width:350px; margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>Medicine note : </label></span>\r\n					<v><%=render_value \'medicine_note\'%></v>\r\n				</div>\r\n				<div class=\"clear\"></div>\r\n				<div id=\"726-F6118707286\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n					<b>Post-Operative Note</b>\r\n				</div>\r\n				<div id=\"arrival_time\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>Arrival time : </label></span>\r\n					<v><%=render_value \'arrival_time\'%></v>\r\n				</div>\r\n				<div id=\"discharge_time\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 