class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>O2 saturation (%) : </label></span>\r\n					<v><%=render_value \'before_o2_saturation\'%></v>\r\n				</div>\r\n				-->\r\n				<div id=\"before_level_of_consciousness\" class=\"  portlet \" style=\"border:0px solid blue;width:250px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>Level of consciousness : </label></span>\r\n					<v><%=render_value \'before_level_of_consciousness\'%></v>\r\n				</div>\r\n				<div id=\"transfer_to\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;\">\r\n					<span class=\"\"><label>Transfer to : </label></span>\r\n					<v><%=render_value \'transfer_to\'%></v>\r\n				</div>\r\n				<% if @record[:transfer_to] == \'2\' %>\r\n				<div id=\"word_note\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					Ward \r\n					<v><%=render_value \'word_note\'%></v>\r\n				</div>\r\n				<% end %>\r\n				<div class=\'clear\'></div>\r\n				<div id=\"specimens\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>Specimens : </label></span>\r\n					<v><%=render_value \'specimens\'%></v>\r\n				</div>\r\n				<% if @record[:specimens] != \'0\' %>\r\n				<div id=\"fluid_bottle\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n					fluid : \r\n					<v><%=render_value \'fluid_bottle\'%></v>\r\n				</div>\r\n				<div id=\"hssne_bottle\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n					tissue : \r\n					<v><%=render_value \'hssne_bottle\'%></v>\r\n				</div>\r\n				<div id=\"slide_paper\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n					slide : \r\n					<v><%= get_value \'slide_paper\' %> แผ่น</v>\r\n				</div>\r\n				<% end %>\r\n				<div id=\"726-F5667615889\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n					<b>การประเมินผู้ป่วยก่อนจำหน่ายออกจากห้องพักฟื้น</b>\r\n				</div>\r\n				<div id=\"sos_consciousness\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>Consciousness : </label></span>\r\n					<v><%=render_value \'sos_consciousness\'%></v>\r\n				</div>\r\n				<div id=\"sos_sbp_mmhg\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<span class=\"\"><label>SBP(mmHg) : </label></span>\r\n					<v><%=render_value \'sos_sbp_mmhg\'%></v>\r\n				</div>\r\n				<div id=\"sos_hr_min\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n					<span class=\"\"><label>HR(/min) : </label></span>\r\n					<v><%=render_value \'sos_hr_min\'%></v>\r\n				</div>\r\n				<div id=\"sos_rr_min\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n					<span class=\"\"><label>RR(/min) : </label></span>\r\n					<v><%=render_value \'sos_rr_min\'%></v>\r\n				</div>\r\n				<div id=\"sos_bt\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:120px;\">\r\n					<span class=\"\"><label>BT(c) : </label></span>\r\n					<v><%=render_value \'sos_bt\'%></v>\r\n				</div>\r\n				<div id=\"sos_total_score\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n					<b><span class=\"\"><label>คะแนนรวม : </label></span></b>\r\n					<v><%=render_value \'sos_total_score\'%></v>\r\n				</div>\r\n				<div id=\"726-F4662588185\" class=\"  field\" style=\"clear:both;\">\r\n					: 0-1 คะแนน - ส่งกลับหอผู้ป้วย, วัดv/s ตามปกติ<br />\r\n					: 2-3 คะแนน - ส่งกลับหอผู้ป่วยโดยแพทย์ติดตามไปประเมินซ้ำที่หอผู้ป่วย<br />\r\n					: ≥ 4 คะแนน - พิจารณาเข้าสังเกตการต่อที่หอผู้ป้วยวิกฤต\r\n				</div>\r\n			</div>\r\n			<div class=\"clear\">	</div>\r\n			<div id=\"page\" style=\"height:80px\">\r\n				<h4>Sign :</h4>\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n		</div>\r\n	</body>\r\n</html>\r\n<% if @current_role != \'developer\' %>\r\n<script>\r\n	window.print()\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2017-03-02 03:06:25','2017-03-02 03:06:25','print',''),(2961,'report',1064,2,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    patients =  module_model.all(:module_name=>mname)\r\n    \r\n    \r\n    list = []\r\n    \r\n    \r\n    \r\n    list = module_model.collection.group({:keyf=>\'function(doc){return {month:doc.date.getMonth(),name:doc.module_name};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}})\r\n          \r\n          \r\n        columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n   \r\n    map = {}\r\n    data = []\r\n         \r\n    if list.size>0    \r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    name = i[\'name\'].split(\'#\')[1]\r\n    map[name] = {\'name\'=>name.humanize, \'data\'=>[]} unless map[name] \r\n    map[name][\'data\'][i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\n    end\r\n    map.each_pair do |k,v|\r\n    if k!=\'appointment\'\r\n        data << v    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n   \r\n    columns = mlabels\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box-header\">\r\n										<h3>Summary</h3>\r\n									\r\n									</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%\r\n\r\n%>\r\n\r\n<div id=\"chart\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n<br/>\r\n<table  class=\"table table-bordered\" style=\'width:100%\'>\r\n    <thead>\r\n        <tr>\r\n            <th>Month</th>\r\n<% mlabels.each do |i| %>\r\n            <th><%= i %></th>\r\n<% end %>\r\n            <th>Total</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n<%\r\n    total = {}\r\n    data.each do |i|\r\n        v = i[\'data\']\r\n%>\r\n        <tr>\r\n            <td><%= i[\'name\'] %></td>\r\n<%\r\n    mlabels.each_with_index do |i, n|\r\n        if !total.has_key? i\r\n            total[i] = []\r\n        end\r\n        x = (v[n].nil?) ? 0 : v[n]\r\n        total[i] << x\r\n%>\r\n            <td><%= v[n].nil? ? \'-\' : v[n] %></td>\r\n<%  end %>\r\n            <td><%= v.sum %></td>\r\n        </tr>\r\n<%  end %>\r\n        <tr>\r\n            <td>Total</td>\r\n<%  \r\n    sum = 0\r\n    mlabels.each_with_index do |i, n| \r\n        v = total[i].sum\r\n        sum += v\r\n%>\r\n            <td><%= total[i].sum %></td>\r\n<%  end %>\r\n            <td><%= sum %></td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n\r\n            <script>\r\n                function createChart() {\r\n                    $(\"#chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                }\r\n\r\n                $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n                });\r\n            </script>\r\n\r\n\r\n',NULL,NULL,NULL,'2017-03-03 08:26:02','2017-03-03 08:26:02','report',''),(2962,'index',1185,2,'<%\r\n   \r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    patients =  module_model.all(:module_name=>mname)\r\n    \r\n    \r\n    list = []\r\n    \r\n    \r\n    \r\n    \r\n    list = module_model.collection.group({:keyf=>\'function(doc){return {month:doc.date.getMonth(),name:doc.module_name};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}\r\n        }\r\n    )\r\n          \r\n          \r\n        columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n   \r\n    map = {}\r\n    data = []\r\n         \r\n    if list.size>0    \r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    name = i[\'name\'].split(\'#\')[1]\r\n    map[name] = {\'name\'=>name.humanize, \'data\'=>[]} unless map[name] \r\n    map[name][\'data\'][i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\n    end\r\n    map.each_pair do |k,v|\r\n    if k!=\'appointment\'\r\n        data << v    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n   \r\n    columns = mlabels\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box-header\">\r\n										<h3>Summary</h3>\r\n									\r\n									</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%\r\n\r\n%>\r\n\r\n<div id=\"chart\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n<br/>\r\n<table  class=\"table table-bordered\" style=\'width:100%\'>\r\n    <thead>\r\n        <tr>\r\n            <th>Month</th>\r\n<% mlabels.each do |i| %>\r\n            <th><%= i %></th>\r\n<% end %>\r\n            <th>Total</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n<%\r\n\r\n    total = {}\r\n    data.each do |i|\r\n        v = i[\'data\']\r\n%>\r\n\r\n        <tr>\r\n            <td><%= i[\'name\'] %></td>\r\n<%\r\n    mlabels.each_with_index do |i, n|\r\n        if !total.has_key? i\r\n            total[i] = []\r\n        end\r\n        x = (v[n].nil?) ? 0 : v[n]\r\n        total[i] << x\r\n%>\r\n\r\n\r\n            <td><%= v[n].nil? ? \'-\' : v[n] %></td>\r\n<%  end %>\r\n\r\n\r\n            <td><%= v.compact.sum if v%></td>\r\n            \r\n            \r\n        </tr>\r\n        \r\n<%  end %>\r\n        <tr>\r\n            <td>Total</td>\r\n<%  \r\n\r\n    sum = 0\r\n    mlabels.each_with_index do |i, n| \r\n        v = total[i].sum\r\n        \r\n        \r\n        sum += v if v\r\n%>\r\n            <td><%= total[i].sum %></td>\r\n<%  end %>\r\n            <td><%= sum %></td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<br/>\r\n\r\n\r\n\r\n\r\n\r\n            <script>\r\n                function createChart() {\r\n                    $(\"#chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                }\r\n\r\n                $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n                });\r\n            </script>\r\n\r\n\r\n',NULL,NULL,NULL,'2017-03-06 14:48:43','2017-03-06 14:48:43','index',''),(2963,'context_menu',1185,4,'\r\n<% \r\n   obj = [\r\n        {:name=>\'Reports\',:open=>true,:actions=>[\r\n                {:name=>\'Overview\',:service=>\'\',:link=>\'index\',:remote=>false},\r\n                {:name=>\'ICD Search\',:service=>\'\',:link=>\'icd_search\',:remote=>false},\r\n                {:name=>\'Admission Search\',:service=>\'\',:link=>\'admit_search\',:remote=>false},\r\n                {:name=>\'Gynecology Report\',:service=>\'\',:link=>\'gynecology_report\',:remote=>false},\r\n                {:name=>\'Obstetrics Report\',:service=>\'\',:link=>\'obstetrics_report\',:remote=>false},\r\n\r\n\r\n            ]\r\n        },\r\n        {:name=>\'Links\',:open=>true,:actions=>[\r\n                {:name=>\'Back to Home\',:service=>\'\',:link=>\'../Home/index\',:remote=>false}\r\n            ]\r\n        }\r\n    ]\r\n\r\n#   obj << {:name=>\'Links\', :actions=>[{:name=>\'Back to EHR\',:link=>\"../../www/Home/index\",:remote=>false}]}\r\n%>\r\n<%= show_menu obj%>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<!--</div></div></div>-->',NULL,NULL,NULL,'2017-03-07 05:47:36','2017-03-07 05:47:36','context_menu',''),(2964,'icd_search',1185,2,'<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n		width:100px\r\n    }\r\n    \r\n<%\r\n    malignant_list = %w{C541 C542 C548 C530 C531 C538 C56 C796 C570 C52 C510 C511 C512 C518 C482 C786 D392 C58 C578 C80 C509 C189}\r\n    malignant_list.each do |i|\r\n%>\r\n.<%= i %> { background:lightsalmon; }\r\n<% end %>\r\n</style>\r\n<%\r\n    report = [\r\n            [\'Bowel Report\', \'bowel\'],\r\n            [\'Screening CRC - Poylp Report\', \'spolyp\'],\r\n            [\'Iron deficiency anemia (colono)\', \'iron-colo\'],\r\n            [\'Iron deficiency anemia (gastro)\', \'iron-gast\']\r\n        ]\r\n%>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box-header\">\r\n			<h3>Search</h3>\r\n		</div>\r\n        <div class=\"w-box-content cnt_a\">\r\n<%= form_for :search,:url=>\'icd_search_partial?update=result-panel\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n	    <span class=\"field-data\"> \r\n			<label class=\"field-label\">Start Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :sdate, :value=>\'\',:id=>\'sdate\',:style=>\"width:100%\"%></div>\r\n		</span> \r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">End Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :edate, :value=>\'\',:id=>\'edate\',:style=>\"width:100%\"%></div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">ICD Code :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :code, :value=>\'\',:id=>\'code\',:style=>\"width:100%\"%></div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n<!--		\r\n		<span class=\'field-data\' style=\'width:450px\'>\r\n		    <label class=\'field-label\'style=\'width:100px\'>Report Output : </label>\r\n		    <div class=\'field-input\' style=\'width:250px\'><%= f.select :report, report, include_blank: false %></div>\r\n		</span>\r\n-->		\r\n		<span class=\"field-data\">\r\n		    <div class=\"field-input\"><%=f.submit \'Submit\', :class=>\'btn btn-success\'%> </div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n<script>\r\n    $(\"#sdate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n    $(\"#edate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n</script>\r\n<% end %>\r\n\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class=\'clear\'></div>\r\n<br/>\r\n<div id=\'result-panel\'></div>\r\n',NULL,NULL,NULL,'2017-03-07 05:59:57','2017-03-07 05:59:57','icd_search',''),(2965,'icd_search_partial',1185,3,'<%\r\n    tb = Time.now\r\n    rs = {}\r\n    obj  = {}\r\n    cond = {}\r\n    \r\n    services = [:obstetrics, :gynecology]\r\n    \r\n    report = \'\'\r\n    if q = params[:search]\r\n        q[:sdate] = Time.strptime(q[:sdate], \"%d/%m/%Y\")\r\n        q[:edate] = Time.strptime(q[:edate], \"%d/%m/%Y\")\r\n        \r\n        code = q[:code].upcase\r\n        qq   = Regexp.new(Regexp.escape(q[:code]), \"i\")\r\n        \r\n        report = q[:report]\r\n        code_list = code.split(/[\\s,]/)\r\n        \r\n        cond[:created_at] = {\'$gte\'=>q[:sdate].beginning_of_day,\'$lt\'=>q[:edate].end_of_day}\r\n        res = []\r\n        \r\n            #\r\n            # Obstetrics \r\n            #\r\n            rs_obs= []\r\n            id_obs= {}\r\n            f_map = {\r\n                \'comorbidity\'=>{:n=>:icd_comorbidity,:f=>:comorbidity}, \r\n                \'complication\'=>{:n=>:icd_complication,:f=>:complication}, \r\n                \'external_cause\'=>{:n=>:icd_external_cause,:f=>:external_cause}, \r\n                \'other_diagnosis\'=>{:n=>:icd_other_diagnosis,:f=>:other_diagnosis}, \r\n                \'operation\'=>{:n=>:icd_operation,:f=>:operation}\r\n            }\r\n            f_obs = {:icd_comorbidity=>[], :icd_complication=>[], :icd_external_cause=>[], :icd_other_diagnosis=>[], :icd_operation=>[]}\r\n            obs = get_model[:obstetrics].collection.find(cond, {:fields=>{\'_id\'=>1, \'principle_diagnosis\'=>1, \'comorbidity\'=>1, \'complication\'=>1, \'external_cause\'=>1, \'other_diagnosis\'=>1, \'operation\'=>1}}).to_a\r\n            \r\n            obs.each do |i|\r\n                id = i[\'_id\']\r\n                icd = (!i[\'principle_diagnosis\'].nil? and i[\'principle_diagnosis\'] != \'\') ? i[\'principle_diagnosis\'].upcase : \'---\'\r\n                if !code_list.empty?\r\n                    rs_obs << {:form_id=>id, :icd=>icd, :group=>\'principle_diagnosis\'} if code_list.include? icd\r\n                else\r\n                    rs_obs << {:form_id=>id, :icd=>icd, :group=>\'principle_diagnosis\'}\r\n                end\r\n                # rs_obs << {:form_id=>id, :icd=>icd, :group=>\'principle_diagnosis\'}\r\n                f_map.each do |k, v|\r\n                    ls = i[k]\r\n                    if ls != \'\' and !ls.nil?\r\n                        if !ls.empty?\r\n                            f_obs[v[:n]] += ls \r\n                            ls.each do |j|\r\n                                id_obs[j] = id\r\n                            end\r\n                        end\r\n                    end\r\n                end\r\n            end\r\n            # obj = id_obs\r\n            tmp = []\r\n            f_map.each do |k,v|\r\n                # model name\r\n                mn = v[:n]\r\n                # field name\r\n                fn = v[:f].to_s\r\n                # list value\r\n                lv = f_obs[mn]\r\n                # group name\r\n                gn = fn\r\n                \r\n                tmp = get_model[mn].collection.find({\'_id\'=>{\'$in\'=>lv}}, {:fields=>{\'_id\'=>1, fn=>1}})\r\n                tmp.each do |i|\r\n                    f_id = id_obs[i[\'_id\']]\r\n                    # code list\r\n                    # cl   = i[fn].split(\',\')\r\n                    cl   = i[fn].split(/[\\s,.]/)\r\n                    if cl.count == 1\r\n                        if !code_list.empty?\r\n                            rs_obs << {:form_id=>f_id, :icd=>cl[0].strip, :group=>gn} if code_list.include? cl[0].strip\r\n                        else\r\n                            rs_obs << {:form_id=>f_id, :icd=>cl[0].strip, :group=>gn}\r\n                        end\r\n                        # rs_obs << {:form_id=>f_id, :icd=>cl[0].strip, :group=>gn}\r\n                    else\r\n                        cl.each do |j|\r\n                            if !code_list.empty?\r\n                                rs_obs << {:form_id=>f_id, :icd=>j.strip, :group=>gn} if code_list.include? j.strip\r\n                            else\r\n                                rs_obs << {:form_id=>f_id, :icd=>j.strip, :group=>gn}\r\n                            end\r\n                            # rs_obs << {:form_id=>f_id, :icd=>j.strip, :group=>gn}\r\n                        end\r\n                    end\r\n                end\r\n            end\r\n            \r\n            #\r\n            # Gynecology\r\n            # \r\n            rs_gyn= []\r\n            id_gyn= {}\r\n            f_gyn = {:icd_comorbidity=>[], :icd_complication=>[], :icd_external_cause=>[], :icd_other_diagnosis=>[], :icd_operation=>[]}\r\n            gyn = get_model[:gynecology].collection.find(cond, {:fields=>{\'_id\'=>1, \'principle_diagnosis\'=>1, \'comorbidity\'=>1, \'complication\'=>1, \'external_cause\'=>1, \'other_diagnosis\'=>1, \'operation\'=>1}}).to_a\r\n            \r\n            gyn.each do |i|\r\n                id = i[\'_id\']\r\n                icd = (!i[\'principle_diagnosis\'].nil? and i[\'principle_diagnosis\'] != \'\') ? i[\'principle_diagnosis\'].upcase : \'XXXX\'\r\n                if !code_list.empty?\r\n                    rs_gyn << {:form_id=>id, :icd=>icd, :group=>\'principle_diagnosis\'} if code_list.include? icd\r\n                else\r\n                    rs_gyn << {:form_id=>id, :icd=>icd, :group=>\'principle_diagnosis\'}\r\n                end\r\n                # rs_gyn << {:form_id=>id, :icd=>icd, :group=>\'principle_diagnosis\'}\r\n                f_map.each do |k, v|\r\n                    ls = i[k]\r\n                    if ls != \'\' and !ls.nil?\r\n                        if !ls.empty?\r\n                            f_gyn[v[:n]] += ls \r\n                            ls.each do |j|\r\n                                id_gyn[j] = id\r\n                            end\r\n                        end\r\n                    end\r\n                end\r\n            end\r\n            \r\n            tmp = []\r\n            f_map.each do |k,v|\r\n                # model name\r\n                mn = v[:n]\r\n                # field name\r\n                fn = v[:f].to_s\r\n                # list value\r\n                lv = f_gyn[mn]\r\n                # group name\r\n                gn = fn\r\n                \r\n                tmp = get_model[mn].collection.find({\'_id\'=>{\'$in\'=>lv}}, {:fields=>{\'_id\'=>1, fn=>1}})\r\n                tmp.each do |i|\r\n                    f_id = id_gyn[i[\'_id\']]\r\n                    # code list\r\n                    cl   = i[fn].split(/[\\s,.]/)\r\n                    if cl.count == 1\r\n                        if !code_list.empty?\r\n                            rs_gyn << {:form_id=>f_id, :icd=>cl[0].strip, :group=>gn} if code_list.include? cl[0].strip\r\n                        else\r\n                            rs_gyn << {:form_id=>f_id, :icd=>cl[0].strip, :group=>gn}\r\n                        end\r\n                        # rs_gyn << {:form_id=>f_id, :icd=>cl[0].strip, :group=>gn}\r\n                    else\r\n                        cl.each do |j|\r\n                            if !code_list.empty?\r\n                                rs_gyn << {:form_id=>f_id, :icd=>j.strip, :group=>gn} if code_list.include? j.strip\r\n                            else\r\n                                rs_gyn << {:form_id=>f_id, :icd=>j.strip, :group=>gn}\r\n                            end\r\n                            # rs_gyn << {:form_id=>f_id, :icd=>j.strip, :group=>gn}\r\n                        end\r\n                    end\r\n                end\r\n            end\r\n            \r\n            \r\n            res = {}\r\n            res[:obstetrics] = rs_obs\r\n            res[:gynecology] = rs_gyn\r\n        \r\n        \r\n        \r\n        rs = res\r\n    else\r\n        \r\n    end\r\n    # bowel_preperation_finding\r\n    \r\n    \r\n%>\r\n<style>\r\n    .XXXX {\r\n        color:red;\r\n        \r\n    }\r\n</style>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\'>\r\n        \r\n    \r\n<div class=\'span4\'>\r\n<%\r\n    services.each do |ser|\r\n        x = rs[ser]\r\n%>\r\n                            <div id=\"group_<%= ser %>\" class=\"accordion\">\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#service_<%= ser %>\" data-parent=\"#group_<%= ser %>\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											<h3><%= ser.to_s.humanize %> </h3>\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"service_<%= ser %>\">\r\n										<div class=\"accordion-inner\">\r\n										\r\n						\r\n    <table class=\"table table-bordered\" style=\'width:100%\'>\r\n        <thead>\r\n            <tr>\r\n                <th>No.</th>\r\n                <th>ICD Code</th>\r\n                <th>Total</th>\r\n                <th>Action</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n<%\r\n    res  = x.group_by{|i| i[:group]}\r\n    res.each do |k,v|\r\n        n = v.count\r\n%>\r\n            <tr>\r\n                <th colspan=\'2\' style=\'background:#eee\'><%= k.humanize %></th>\r\n                <th style=\'background:#eee\'><center><%= n %></center></th>\r\n                <th style=\'background:#eee\'><center><%= link_to \'Hide\', \"javascript:show(\'\\\\#{ser}_\\\\#{k}\')\", :class=>\'btn btn-mini btn-info\', :id=>\"btn-\\\\#{ser}_\\\\#{k}\" %></center></th>\r\n            </tr>\r\n<%\r\n        no = 0\r\n        g = v.group_by{|i| i[:icd]}\r\n        gk = g.keys.sort_by{|i| i}\r\n        gk.each do |i|\r\n            x = i\r\n            y = g[i]\r\n            no += 1\r\n%>\r\n            <tr class=\'<%= ser %>_<%= k %> <%= x %>\'>\r\n                <td><center><%= no %>.</center></td>\r\n                <td><center><%= x %></center></td>\r\n                <td><center><%= y.count %></center></td>\r\n                <td><center><%= link_to \'Detail\', \"javascript:detail(\'\\\\#{ser}_\\\\#{x}_\\\\#{k}\')\", :class=>\'btn btn-mini\' %></center></td>\r\n            </tr>\r\n<%  end %>\r\n<%  end %>\r\n        </tbody>\r\n    </table>\r\n    \r\n    \r\n    </div></div></div></div>\r\n<% end %>\r\n    \r\n</div>\r\n\r\n<div id=\'patient-result\' class=\'span8\'>\r\n\r\n    <table class=\"table table-bordered\" style=\'width:100%\' id=\'pat-result\'>\r\n        <thead>\r\n            <tr>\r\n                <th>HN</th>\r\n                <th>Name</th>\r\n                <th>Date</th>\r\n                <th>Detail</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n\r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    m_pat = model[:patient]\r\n    m_pat_mod = model[:patient_module]\r\n    services.each do |ser|\r\n        x = rs[ser]\r\n        \r\n        g_form = x.group_by{|i| i[:form_id]}\r\n        \r\n        fid = g_form.keys\r\n        # tmp = m_pat_mod.where(:module_id=>fid).all\r\n        tmp = m_pat_mod.collection.find({\'module_id\'=>{\'$in\'=>fid}}, {:fields=>{\'patient_id\'=>1, \'module_id\'=>1, \'created_at\'=>1, \'module_name\'=>1}}).to_a\r\n        g_tmp = tmp.group_by{|i| i[\'module_id\']}\r\n        \r\n        pid = tmp.collect{|i| i[\'patient_id\']}\r\n        pat = m_pat.collection.find({\'_id\'=>{\'$in\'=>pid}},{:fields=>{\'hn\'=>1, \'prefix_name\'=>1,\'first_name\'=>1,\'last_name\'=>1}}).to_a\r\n        \r\n        g_pat = pat.group_by{|i| i[\'_id\']}\r\n        n = 0\r\n        tmp.each do |i|\r\n            n += 1\r\n            form_id = i[\'module_id\']\r\n            pp = {}\r\n            pp = g_pat[i[\'patient_id\']] if !i[\'patient_id\'].nil?\r\n            if pp.nil?\r\n                pp = {\'hn\' => \'------\', \'prefix_name\'=>\'--\', \'first_name\'=>\'--\', \'last_name\'=>\'--\'}\r\n            else\r\n                pp = pp[0]\r\n            end\r\n            \r\n            pn = \"\\\\#{pp[\'prefix_name\']}\\\\#{pp[\'first_name\']} \\\\#{pp[\'last_name\']}\"\r\n            \r\n            md = i[\'module_name\'].split(\'#\')[1].humanize\r\n            \r\n            list = g_form[form_id]\r\n            icd_list = []\r\n            icd_css  = []\r\n            list.each do |a| \r\n                icd_list << a[:icd]\r\n                icd_css  << \"D_\\\\#{ser}_\\\\#{a[:icd]}_\\\\#{a[:group]}\"\r\n            end\r\n%>\r\n\r\n            <tr class=\"pat_<%= ser.downcase %> <%= icd_css.join(\' \') %>\" style=\'display:none\'>\r\n                <td style=\'display:none\' class=\'pat_<%= ser.downcase %>\'><%= n %></td>\r\n                <td><%= pp[\'hn\'] %></td>\r\n                <td><%= pn %><br/><%= icd_list.join(\', \') %></td>\r\n                <td><%= i[\'created_at\'].strftime(\'%d/%m/%Y\') %></td>\r\n                <td><%= link_to \'Detail\', \"../\\\\#{md}/show?id=\\\\#{i[\'_id\']}&return=../Home/index\", :target=>\'_blank\', :class=>\'btn btn-mini btn-gebo\' %></td>\r\n            </tr>\r\n            \r\n<%\r\n        end\r\n    end\r\n%>\r\n        </tbody>\r\n    </table>\r\n</div>\r\n\r\n<script>\r\n    function show(x) {\r\n        a = $(\'.\' + x).css(\'display\');\r\n        if (a != \'none\') {\r\n            $(\'.\' + x).hide();\r\n            $(\'#btn-\' + x).text(\"Show\");\r\n        } else {\r\n            $(\'.\' + x).show();\r\n            $(\'#btn-\' + x).text(\"Hide\");\r\n        }\r\n        console.log(a);\r\n    }\r\n\r\n    function detail(x) {\r\n        n = \"D_\" + x;\r\n        a = $(\'.\' + n).css(\'display\');\r\n        if (a != \'none\') {\r\n            $(\'.\' + n).hide();\r\n            // $(\'#btn-\' + x).text(\"Show\");\r\n        } else {\r\n            $(\'.\' + n).show();\r\n            // $(\'#btn-\' + x).text(\"Hide\");\r\n        }\r\n        console.log(a);\r\n    }\r\n</script>\r\n\r\n<div class=\'clear\'></div>\r\n\r\n<br/>\r\n<% if @current_role==\'developer\' %>\r\n<%# params.to_json.html_safe %><br/><br/>\r\n<%# qq %>\r\n<% end %>\r\n<hr/>\r\nProcessing time : <%= Time.now - tb %>. <%= Time.now %>\r\n\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-03-07 06:11:48','2017-03-07 06:11:48','icd_search_partial',''),(2966,'index',622,2,'<%\r\n    if @current_role != \'admin\' or @current_role != \'developer\' or @current_user.login != \'ehr@esm-solution.com\' or @current_user.login != \'ls@esm-solution.com\'\r\n        session[:admin] = false\r\n    else\r\n        session[:admin] = true\r\n    end\r\n    \r\n    module_name = @current_project.name\r\n    if params[:date]\r\n        session[module_name]={:date=>params[:date]}\r\n    end\r\n    if session[module_name]\r\n        params[:date] = session[module_name][:date]\r\n    end\r\n    unless params[:date]\r\n        params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n    end\r\n \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n\r\n    # checking existing provider\r\n    prov = get_model[:provider].where(:provider_type=>\'1\').all\r\n    if prov.empty?\r\n%>\r\n                            <div class=\"modal hide fade\" id=\"modal-provider\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>ข้อแนะนำ</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n								    ไม่พบรายชื่อแพทย์ในระบบ กรุณาคลิกที่ปุ่ม\r\n								    \r\n									<ul class=\"dshb_icoNav tac\" style=\'display:inline\'>\r\n									    <li><a style=\"background-image: url(/gebo/img/gCons/configuration02.png)\" href=\"javascript:void(0);\">\r\n										    Settings</a></li>\r\n									</ul>\r\n									\r\n									เพื่อตั้งค่ารายชื่อแพทย์\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">รับทราบ</a>\r\n								</div>\r\n							</div>\r\n<script>\r\n    $(document).ready(function() {\r\n        $(\'#modal-provider\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n        \r\n        // $(\'#btn-add_patient\').off(\'click\');\r\n    });\r\n</script>\r\n<%\r\n    end\r\n%>\r\n\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n    width:100px\r\n    }\r\n    \r\n    .table td {\r\n        vertical-align: middle;\r\n    }\r\n\r\n\r\n/* Paste this css to your style sheet file or under head tag */\r\n/* This only works with JavaScript, \r\nif it\'s not present, don\'t show loader */\r\n.no-js #loader { display: none;  }\r\n.js #loader { display: block; position: absolute; left: 100px; top: 0; }\r\n.se-pre-con {\r\n	/*position: fixed;*/\r\n	position: absolute;\r\n	left: 0px;\r\n	top: 0px;\r\n	width: 100%;\r\n	height: 100%;\r\n	z-index: 9999;\r\n	background: url(/gebo/img/ajax_loader.gif) center no-repeat #144884;\r\n}\r\n\r\n                .dataTables_wrapper{position:relative;overflow:hidden}\r\n                .dataTables_wrapper table.table {clear:both;margin-bottom:6px!important;max-width:inherit}\r\n                .dataTables_wrapper table.table thead .sorting,table.table thead .sorting_asc,table.table thead .sorting_desc,table.table thead .sorting_asc_disabled,table.table thead .sorting_desc_disabled{cursor:hand;cursor:pointer}\r\n                .dataTables_wrapper table.table thead .sorting{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_both.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc_disabled.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc_disabled.png) no-repeat center right}\r\n</style>\r\n<!-- datatable -->\r\n            <script src=\"/gebo/lib/datatables/jquery.dataTables.min.js\"></script>\r\n            <script src=\"/gebo/lib/datatables/extras/Scroller/media/js/Scroller.min.js\"></script>\r\n            <!-- datatable functions -->\r\n            <script src=\"/gebo/js/gebo_datatables.js\"></script>\r\n            \r\n<%\r\n    date = Time.now \r\n\r\n    date_text = date.strftime(\"%d/%m/%Y\")\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n   \r\n    # manage\r\n    if pp = params[:manage] and request.post?\r\n        if pp[:doc] == \'patient\' and pp[:mode] == \'remove\'\r\n            all_pm = module_model.where(:patient_id=>pp[:pid]).all\r\n            \r\n            all_pm.each do |i|\r\n                mn = i[:module_name].split(\'#\')\r\n                if mn[0] == @current_project.name\r\n                    tmp = get_model[mn[1].to_sym]\r\n                    xxx = tmp.find(i[:module_id])\r\n                    xxx.destroy\r\n                end\r\n                \r\n                i.destroy\r\n            end\r\n            \r\n            xxx = patient_model.find(pp[:pid])\r\n            xxx.destroy\r\n        end\r\n    end\r\n    \r\n    models = get_model\r\n    provider_model = models[:provider]\r\n    \r\n    s_status = nil\r\n    s_provider = nil\r\n    s_date = Time.now\r\n    s_first_name=nil\r\n    s_last_name=nil\r\n    hn=nil\r\n    \r\n    \r\n    s_provider = session[:s_provider] if session[:s_provider]\r\n    s_status = session[:s_status] if session[:s_status]\r\n    \r\n    begin\r\n    \r\n    s_date = Date.strptime(session[:s_date].to_s,\"%d/%m/%Y\") if session[:s_date]\r\n    s_date = Date.strptime(params[:date].to_s,\"%d/%m/%Y\") if params[:date]\r\n    date_text = s_date.strftime(\"%d/%m/%Y\")\r\n    session[:s_date] = date_text\r\n    rescue Exception=>e\r\n    \r\n    %><%= error%>\r\n    <%\r\n    session.delete :s_date\r\n    end\r\n     %>\r\n        <%\r\n    search_patient = false\r\n    if p = params[:search]\r\n       \r\n        \r\n        s_provider = p[:provider] if p[:provider] \r\n        s_status = p[:status] if p[:status]\r\n        \r\n      \r\n        s_first_name = p[:first_name] if p[:first_name] and p[:first_name] != \"\"\r\n        s_last_name = p[:last_name] if p[:last_name] and p[:last_name] != \"\"\r\n        s_hn= p[:hn] if p[:hn] \r\n        \r\n        if s_first_name or s_last_name or s_hn\r\n              search_patient = true\r\n          end\r\n        session[:s_status] = s_status\r\n         session[:s_provider] = s_provider \r\n        \r\n    end\r\n    if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        p_app[:end] = p_app[:start]\r\n        p_app[:status] = \'Appointed\'\r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Add & Continue\"\r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n</script>\r\n<%\r\n        end\r\n    end\r\n    \r\n    \r\n    providers = provider_model.all.to_a.sort{|a,b| a.name.split(\'.\')[-1]<=>b.name.split(\'.\')[-1] }\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       <b>Home : <%= date.strftime(\'%d/%m/%Y\') %></b>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n            <div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n<%=form_for :search,:url=>params[:opt], :html=>{:style=>\'margin-bottom:0px\'} do |f| %>\r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\">Date : </label>\r\n                    <div class=\"field-input\" >\r\n                        <%= f.text_field :date, :value=>date_text,:id=>\'today-date\',:style=>\"width:100%\"%>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\">HN : </label>\r\n                    <div class=\"field-input\">\r\n                        <%= f.text_field :hn, :value=>s_hn,:style=>\"width:100%;background:#eeeecc\"%>\r\n                    </div>\r\n                </span>\r\n            \r\n                <span class=\"field-data\" style=\"margin-top:5px;width:300px\"> \r\n                        <%=f.submit \'Search\', :class=>\'btn btn-success\'%>\r\n                        <%=link_to \'Advanced Search\', \'javascript:void(0)\', :id=>\'btn-advanced_search\', :class=>\'btn\' %>\r\n                        <%=link_to \'Show Filter\', \'javascript:void(0)\', :id=>\'btn-show_filter\', :class=>\'btn\' %>\r\n                </span>\r\n                \r\n                <div class=\"clear\"></div>\r\n\r\n                <span class=\"field-data\">\r\n                    <label class=\"field-label\">&nbsp;</label>\r\n                    <div class=\"field-input\">\r\n                        <%=link_to \'Add Patient\', \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\',:style=>\'margin-top:10px\'%>\r\n                    </div>\r\n                </span>\r\n\r\n            <div class=\"clear\"></div>\r\n            \r\n            <script>\r\n                $(\'#search_hn\').focus();\r\n            </script>\r\n<% end %>\r\n            \r\n        </div>\r\n        \r\n    </div>\r\n\r\n    <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" id=\'block-filter\'>\r\n        <a class=\"close\" href=\"javascript:void(0);\" id=\'btn-hide_filter\' style=\'float:left\'>x</a>\r\n        <div class=\"row-fluid\">\r\n                <span class=\"field-data\"> \r\n                    <label class=\"field-label\"> </label>\r\n                    <div class=\"field-input\" style=\'float:right\'>&nbsp;<b>Filter by</b></div>\r\n                </span>\r\n                <!-- filter -->\r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Provider : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-provider\" id=\"fil-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"prov_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"prov_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Procedure : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-procedure\" id=\"fil-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"proc_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"proc_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Visit : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-visit\" id=\"fil-visit\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"visit_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"visit_<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n                \r\n                <span class=\"field-data\" > \r\n                    <label class=\"field-label\" > Status : </label>\r\n                    <div class=\"field-input\">\r\n                        <select name=\"fil-status\" id=\"fil-status\" style=\"width:100%;height:2.0em;border:1px solid #bbb\">\r\n                            <option value=\"status_all\">-- ทั้งหมด --</option>\r\n            <%\r\n                for l in status_list do\r\n            %>\r\n                            <option value=\"status_<%= l %>\"><%= l %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </span>\r\n        </div>\r\n    </div>\r\n\r\n        <!--DATE : <%# date %>-->\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n\r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    indication_model = models[:indication]    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    indication_model.all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    date = s_date\r\n     %>\r\n    <%#params.inspect %><%#search_patient.inspect%>\r\n    <%\r\n# SEARCH SECTION    \r\n    if search_patient\r\n        \r\n        fields = {:hn=>s_hn, :first_name=>s_hn, :last_name=>s_hn}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n    \r\n        if keys.size>0\r\n            conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n            criteria = {\'$or\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n    \r\n        patients = patient_model.where(criteria).limit(20).all  \r\n        maps = module_model.all     :patient_id=>{\'$in\'=>patients.collect{|i|i.id} }   \r\n        aps = ap_model.find(maps.collect{|i| i.module_id})\r\n%>\r\n<!--<%= params[:search].to_json.html_safe %>-->\r\n<%\r\n        if aps.count == 1 # and @current_role==\'developer\' \r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= aps.first.id.to_s %>\';\r\n</script>\r\n<%\r\n        end\r\n\r\n    elsif pad = params[:adv_pat]\r\n        adv = params[:advanced]\r\n        fields = {:provider=>adv[:provider], :visit_type=>adv[:visit_type], :indication=>adv[:indication], :procedure=>adv[:procedure]}\r\n        keys = []\r\n        \r\n        fields.each_pair do |k,v| \r\n            keys <<{k.to_sym=>v} if v and v!=\'\' \r\n        end\r\n        \r\n        if keys.size>0\r\n            criteria = {\'$and\'=>keys}\r\n        else\r\n            criteria ={}\r\n        end\r\n        \r\n        # patient criteria\r\n        fs = {:first_name=>pad[:fname], :last_name=>pad[:lname]}\r\n        ks = []\r\n        fs.each_pair do |k, v|\r\n            ks <<{k.to_sym=>Regexp.new(v)} if v and v!=\'\' \r\n        end\r\n        if ks.size>0\r\n            cr = {\'$or\'=>ks}\r\n        else\r\n            cr ={}\r\n        end\r\n        \r\n        a_app = []\r\n        if !criteria.empty?\r\n            a_app = ap_model.where(criteria).all\r\n        end\r\n        \r\n        a_pat = []\r\n        if !cr.empty?\r\n            a_pat = patient_model.where(cr).all\r\n        end\r\n        \r\n        if !a_app.empty? and cr.empty?\r\n            aps = a_app\r\n        elsif a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(maps.collect{|i| i.module_id})\r\n        elsif !a_app.empty? and !cr.empty?\r\n            maps = module_model.where(:patient_id=>a_pat.collect{|i|i.id})  \r\n            aps = ap_model.find(a_app.collect{|i|i.id} & maps.collect{|i| i.module_id})\r\n        else\r\n            aps = ap_model.limit(20).all\r\n        end\r\n    else\r\n    \r\n        conds = {:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day}\r\n\r\n        if s_provider and s_provider !=\'\'\r\n            conds.merge! :provider=>s_provider \r\n        end\r\n\r\n        if s_status and s_status != \"\"\r\n            conds.merge! :status=>s_status \r\n        end\r\n    \r\n        aps = ap_model.all(conds)\r\n\r\n    end\r\n    \r\n    a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = module_model.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n    # form service\r\n	f_ser = {}\r\n	# service_map\r\n	sm = {\r\n        :gastro=>\'Gastro\',\r\n        :colono=>\'Colono\'\r\n        # :push_enteroscopy=>\'Push Ent\',\r\n        # :dbe=>\'DBE\',\r\n        # :sigmoid=>\'Sigmoid\',\r\n        # :ercp=>\'ERCP\',\r\n        # :eus=>\'EUS\'\r\n	}\r\n	sm.each do |k, v|\r\n	    f_ser[k] = {}\r\n	    tmp = module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>pa_id).all\r\n	    tmp.each do |i|\r\n	        f_ser[k][i[:patient_id].to_s] = i.id.to_s\r\n	    end\r\n	end\r\n         \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n    if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n        pat_id = m.patient_id.to_s\r\n        \r\n        if i[:status].nil? or i[:status]==\'\'\r\n            i.update_attributes :status=>\'Appointed\'\r\n        end\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}&return=\\\\#{request.fullpath}\") if patient\r\n         public_id = \'-\'\r\n         bdate = i.date.strftime(\'%d/%m/\').to_s + (i.date.strftime(\'%Y\').to_i + 543).to_s\r\n         col_patient = link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id}\")\r\n        #  if i[:note] != \'\' and !i[:note].nil?\r\n        #      col_patient += \"<br/><i>Note: \\\\#{i[:note]}</i>\".html_safe\r\n        #  end\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>col_patient,\r\n         :provider=>provider_name,:date=>i.date.strftime(\'%d/%m/%Y\'),:note=>\"\\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\',:style=>\'margin:0px\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type, :patient_id=>patient.id, :prov_id=>i.provider, :proc_id=>i.procedure, :visit_id=>i.visit_type,\r\n         :pat_id=>pat_id\r\n         }\r\n         \r\n        #  if i.status==\'Waiting\'\r\n        #      c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        #      #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        #  else\r\n        #      status = \'btn-info\'\r\n        #      status = \'\' if i.status ==\'Completed\'\r\n             c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info\', :style=>\'width:45px\',)\r\n        #  end\r\n        \r\n        if (date_text == Time.now.strftime(\'%d/%m/%Y\') and @current_role==\'admin\') or @current_role==\'developer\'\r\n            c[:processing_ctrl] += link_to(\'\', \"../../www/Patient/edit?id=\\\\#{m.patient_id}&return=\\\\#{request.fullpath}\", :class=>\'splashy-contact_blue_edit\', :style=>\'margin-left:5px;margin-top:2px\').html_safe\r\n            c[:processing_ctrl] += link_to(\'\', \"javascript:confirm_delete(\'\\\\#{m.patient_id}\')\", :class=>\'splashy-contact_blue_remove\', :style=>\'margin-left:5px;margin-top:2px\').html_safe\r\n        end\r\n        \r\n        l_list = []\r\n        sm.each do |k, v|\r\n                    lab = k.to_s.split(\'_\')[0].humanize\r\n                    v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                        \"../\\\\#{v}/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=\\\\#{request.fullpath}\", \r\n                        :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                    if f_ser[k][pat_id]\r\n                        v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            \"../\\\\#{v}/show?id=\\\\#{f_ser[k][pat_id]}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\', :target=>\'_blank\')\r\n                        # v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            # \"../\\\\#{v}/print?id=\\\\#{f_ser[k][pat_id]}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\', :target=>\'_blank\')\r\n                    end\r\n                    l_list << v_link\r\n        end\\\\#{request.fullpath}\r\n        \r\n        c[:processing_ctrl] = \"\\\\#{l_list.join(\' \')} \\\\#{c[:processing_ctrl]}\".html_safe\r\n        \r\n        c\r\n         \r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{hn patient provider procedure visit_type status_ctrl processing_ctrl note}.collect{|i| i.to_sym}\r\n    \r\n    \r\n        labels = {:no=>\'No.\', :date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Visit\',:processing_ctrl=>\'Action\', :procedure=>\'Procedure\' }\r\n    \r\n    %>\r\n<div class=\"se-pre-con\"></div>\r\n\r\n<%\r\n    if aps.empty?\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\' style=\'padding:20px\'>\r\n        <center><h3>ไม่มีรายการนัดหมายสำหรับวันนี้ คลิกปุ่ม \r\n        <%=link_to \'Add Patient\', \'javascript:void(0)\', :id=>\'btn-add_patient\', :class=>\'btn btn-info\',:style=>\'\',:disabled=>true%>\r\n        เพื่อเพิ่มรายการนัดหมาย</h3></center>\r\n    </div>\r\n</div>\r\n<%\r\n    else\r\n        # table fields\r\n        # tf = [:no]+table_model+[:processing_ctrl,:note]\r\n        tf = table_model - [:note]\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\' style=\'padding:20px\'>\r\n        <div id=\'filter-count\'></div>\r\n        <!--<table class=\"table table-bordered\">-->\r\n        <table id=\'patient-table\' class=\"table table-striped table-bordered dTableR\">\r\n            <thead>\r\n                <tr>\r\n<%\r\n    if @current_role==\'developer\'\r\n%>\r\n                    <th><input type=\'checkbox\' name=\'check_all\' id=\'check_all\' value=\'check_all\'/></th>\r\n<%\r\n    end # checkbox if\r\n%>\r\n                    <th>No.</th>\r\n<%\r\n            tf.each do |i|\r\n%>\r\n                    <th><%= labels[i] %></th>\r\n<%\r\n            end\r\n%>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n<%\r\n            no = 1;\r\n            aps.each do |i|\r\n                i[:no] = link_to(no, \"../../www/Patient/edit?id=\\\\#{i[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n%>\r\n                <tr class=\'filterable\'>\r\n<%\r\n    if @current_role==\'developer\'\r\n%>\r\n                    <td><input type=\'checkbox\' value=\'<%= i[:pat_id] %>_<%= Time.now.to_i %>\' id=\'<%= i[:pat_id] %>\'/></td>\r\n<%\r\n    end # checkbox if\r\n%>\r\n                    <td><%= i[:no] %></td>\r\n<%\r\n                tf.each do |j|\r\n                    cs = \'\'\r\n                    if j.to_s == \'provider\'\r\n                        cs = \"class=\'filter prov_\\\\#{i[:prov_id]}\'\"\r\n                    elsif j.to_s == \'procedure\'\r\n                        cs = \"class=\'filter proc_\\\\#{i[:proc_id]}\'\"\r\n                    elsif j.to_s == \'note\'\r\n                        cs = \"class=\'filter visit_\\\\#{i[:visit_id]}\'\"\r\n                    elsif j.to_s == \'status_ctrl\'\r\n                        cs = \"class=\'filter status_\\\\#{i[:status]}\'\"\r\n                    end\r\n%>\r\n                    <td <%= cs.html_safe %>><%= i[j] %></td>\r\n<%\r\n                end\r\n%>\r\n                </tr>\r\n<%\r\n                no += 1\r\n            end # end aps\r\n%>\r\n            </tbody>\r\n        </table>\r\n    </div>\r\n</div>\r\n<%\r\n    end\r\n%>\r\n\r\n\r\n<% if false %>\r\n<%\r\n        app_a = []\r\n        app_c = []\r\n        aps.each do |i|\r\n            if i[:status] == \'Completed\'\r\n                app_c << i\r\n            else\r\n                app_a << i\r\n            end\r\n        end\r\n%>\r\n<div id=\'default-panel\' style=\'padding:5px\'>\r\n    <div class=\"tabbable\">\r\n        <ul class=\"nav nav-tabs\">\r\n            <li class=\"active\"><a href=\"#appointed\" data-toggle=\"tab\">Appointed (<%= app_a.count %>)</a></li>\r\n            <li><a href=\"#completed\" data-toggle=\"tab\">Completed (<%= app_c.count %>)</a></li>\r\n        </ul>\r\n        <div class=\"tab-content\">\r\n            <div class=\"tab-pane active\" id=\"appointed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_a,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n            <div class=\"tab-pane\" id=\"completed\">\r\n<% n = 1 %>\r\n<%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>app_c,:labels=>labels do |row,out| \r\n                out[0] = link_to(n.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{row[:patient_id]}&return=\\\\#{request.fullpath}\").html_safe\r\n                n+=1\r\n                out\r\n            end\r\n%>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<% end %>\r\n\r\n<% if false %>\r\n        <div id=\"result-panel\"  style=\"padding:5px\">\r\n                <% count = 1 %>\r\n                <%= tabular :model=>[:no]+table_model+[:processing_ctrl,:note],:data=>aps,:labels=>labels do |row,out| \r\n                    # out[0] = count.to_s+\".\"\r\n                    out[0] = link_to(count.to_s+\".\", \"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\").html_safe\r\n                    count+=1\r\n                 out\r\n             end\r\n                %>\r\n        </div>\r\n<% end %>        \r\n        \r\n        \r\n        \r\n    </div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n\r\n <script>\r\n function change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= s_date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"<%=params[:opt]%>?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<br/>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<%#session[module_name].inspect %>\r\n\r\n<div class=\"alert \">\r\n<%# link_to \'Total Status\',\'total_status?print[date]=\'+params[:date], :target=>\'_blank\' %>\r\nUseful Links : \r\n<!--<%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | -->\r\n<%= link_to \'Today Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\',class: \'btn btn-mini\' %> | \r\n<!--<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date],class: \'btn btn-mini\' %> |-->\r\n<%= link_to \'Total Status\',\'total_status?print[date]=\'+params[:date],class: \'btn btn-mini\', :target=>\'_blank\' %> |\r\n<%= link_to \'Reports\',\'report?date=\'+params[:date],class: \'btn btn-mini\' %> | \r\n<%= link_to \'Appointment\',\'../Appointment/index?date=\'+params[:date],class: \'btn btn-mini\' %> |\r\n<%\r\n    if @current_role==\'admin\' or @current_role==\'developer\'\r\n%>\r\n<%= link_to \'Reset Lock\',\'../Locker/reset\',class: \'btn btn-mini\' %> \r\n<% \r\n    end\r\n%>\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n<%\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n%>\r\n	\r\n<div class=\"modal hide fade\" id=\"modal2\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Advanced Search</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n        \r\n<%= form_for :advanced , :url=>params[:opt] do |f| %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name  : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[first_name]\" id=\"data-fname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name : </label></span>	\r\n                    <input type=\"text\" name=\"adv_pat[last_name]\" id=\"data-lname\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"advanced[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <%= f.submit \'Search\', :class=>\'btn btn-success\' %>\r\n                <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a> \r\n            </div>\r\n        </div>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n							\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <button class=\"close\" data-dismiss=\"modal\">×</button>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal well\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                </div>\r\n                <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                <br/>\r\n                <div id=\"patient_msg\"></div>\r\n                <div class=\"clear\"></div>\r\n                <hr/>\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Birthdate or Age<br/>(dd/mm/yyyy or xx) : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Appointed Date <br/>(dd/mm/yyyy): </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Time <br/>(HH.MM) : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 80px;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'08:00\',\r\n                    	interval: 10,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:220px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication <br/>(Select one) : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            	<div class=\"clear\"></div>\r\n            	\r\n                <div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Visit Type : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Add & Continue\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n</script>\r\n\r\n<script src=\"http://cdn.jsdelivr.net/jquery.cookie/1.4.0/jquery.cookie.min.js\"></script>\r\n\r\n<div id=\'zjs\'>\r\n    <script>\r\n        function confirm_delete(pid) {\r\n            if(confirm(\"Do you want to remove all patient\'s data ?\")){\r\n                \r\n            \r\n                var form = $(\'<form name=\"manage\"></form>\');\r\n    \r\n                form.attr(\"method\", \"post\");\r\n                form.attr(\"action\", \"index_admin\");\r\n                \r\n                params = {pid:pid, doc:\'patient\', mode:\'remove\'};\r\n                $.each(params, function(key, value) {\r\n                    var field = $(\'<input></input>\');\r\n                    \r\n                    k = \"manage[\" + key + \"]\"\r\n            \r\n                    field.attr(\"type\", \"hidden\");\r\n                    field.attr(\"name\", k);\r\n                    field.attr(\"value\", value);\r\n            \r\n                    form.append(field);\r\n                    \r\n                    // alert(k + \'-\' + value)\r\n                });\r\n                \r\n                // The form needs to be a part of the document in\r\n                // order for us to be able to submit it.\r\n                $(document.body).append(form);\r\n                form.submit();\r\n            \r\n            }\r\n        }\r\n        \r\n        $(\'#zjs\').remove();\r\n    </script>\r\n</div>\r\n\r\n<script>\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(this).val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                $(\'#data-birth_date\').val(dd);\r\n            } \r\n        });\r\n    }\r\n    \r\n    function filter() {\r\n        var prov = $(\"#fil-provider\").val();\r\n        var proc = $(\"#fil-procedure\").val();\r\n        var visit = $(\"#fil-visit\").val();\r\n        var status = $(\"#fil-status\").val();\r\n        var count = 0;\r\n        if (prov.indexOf(\'all\') != -1 && proc.indexOf(\'all\') != -1 && visit.indexOf(\'all\') != -1 && status.indexOf(\'all\') != -1) {\r\n            $(\'tr\').show();\r\n        } else {\r\n            $(\'.filterable\').hide();\r\n            console.log(\'all hide ...\');\r\n            $(\"td.filter\").each(function (i, col) {\r\n                \r\n                    if ($(col).hasClass(prov) || $(col).hasClass(proc) || $(col).hasClass(visit) || $(col).hasClass(status)) {\r\n                        $(col).parent(\'tr\').show();\r\n                        count++;\r\n                    } else {\r\n                        // if (!$(col).parent(\'tr\').is(\':visible\')) {\r\n                            // $(col).parent(\'tr\').hide();\r\n                        // }\r\n                    }\r\n                    // console.log(\'i : \' + i + \", col : \" + col)\r\n                    \r\n            });\r\n        }\r\n        $(\'#filter-count\').html(\'<b>Total filtered : <v>\' + count + \'</v></b>\');\r\n    }\r\n    \r\n    \r\n    $(document).ready(function(){\r\n        <% if !prov.empty? %>\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        <% end %>\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#data-hn\').change(update_patient);\r\n        // show filter section\r\n        $(\'#block-filter\').hide();\r\n        $(\'#btn-show_filter\').click(function() {\r\n            // $(\'#block-filter\').show();\r\n            $(\'#block-filter\').fadeIn(\'slow\');\r\n        });\r\n        $(\'#btn-hide_filter\').click(function() {\r\n            $(\'#block-filter\').fadeOut(\'slow\');\r\n        })\r\n        \r\n        $(\"#fil-provider\").change(filter);\r\n        $(\"#fil-procedure\").change(filter);\r\n        $(\"#fil-visit\").change(filter);\r\n        $(\"#fil-status\").change(filter);\r\n        \r\n        // remove splash loading\r\n        $(\".se-pre-con\").fadeOut(\"slow\");\r\n        \r\n        // data-table\r\n        gebo_datatbles = {\r\n    		dt_a: function() {\r\n    			$(\'#patient-table\').dataTable({\r\n    			    stateSave : true,\r\n                    \"sDom\": \"<\'row\'<\'span6\'<\'dt_actions\'>l><\'span6\'f>r>t<\'row\'<\'span6\'i><\'span6\'p>>\",\r\n                    \"sPaginationType\": \"bootstrap_alt\",\r\n                    \"oLanguage\": {\r\n                        \"sLengthMenu\": \"_MENU_ records per page\",\r\n                        \"sEmptyTable\": \"No patient available in table. Please \'<a href=\'javascript:add_patient()\'>Add</a>\' the patient.\"\r\n                    }\r\n                });\r\n    		}\r\n        }\r\n        \r\n        gebo_datatbles.dt_a();\r\n        \r\n        $(\"#check_all\").on(\"change\", function() {\r\n            $(\':checkbox\').not(this).prop(\'checked\', this.checked);\r\n        });\r\n\r\n        $(\":checkbox\").on(\"change\", function(){\r\n            var checkboxValues = {};\r\n            $(\":checkbox\").each(function(){\r\n                checkboxValues[this.id] = this.checked;\r\n            });\r\n            $.cookie(\'checkboxValues\', checkboxValues, { expires: 7, path: \'/\' })\r\n        });\r\n\r\n        function repopulateCheckboxes(){\r\n            var checkboxValues = $.cookie(\'checkboxValues\');\r\n            if(checkboxValues){\r\n                Object.keys(checkboxValues).forEach(function(element) {\r\n                    var checked = checkboxValues[element];\r\n                    $(\"#\" + element).prop(\'checked\', checked);\r\n                });\r\n            }\r\n        }\r\n\r\n        $.cookie.json = true;\r\n        repopulateCheckboxes();\r\n    });\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2017-03-10 15:40:12','2017-03-10 15:40:12','index',''),(2967,'import_items',1168,3,'<%= render :inline=>this.init %>\r\n<%\r\n    models = get_model\r\n    \r\n    store = @current_store\r\n    \r\n    products = models[:product].all\r\n    \r\n    items = []\r\n    for i in products \r\n    \r\n        \r\n        store_item = models[:store_item].where(:store_id=>store.id, :product_id=>i.id).first\r\n        \r\n        unless store_item\r\n        \r\n            store_item = models[:store_item].create :store_id=>store.id, :product_id=>i.id, :balance=>0\r\n            \r\n        end\r\n        \r\n        items << store_item \r\n        \r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n\r\n<%= items.inspect %>',NULL,NULL,NULL,'2017-03-11 04:51:36','2017-03-11 04:51:36','import_items',''),(2968,'index',1061,2,'<style>\r\n                .dataTables_wrapper{position:relative;overflow:hidden}\r\n                .dataTables_wrapper table.table {clear:both;margin-bottom:6px!important;max-width:inherit}\r\n                .dataTables_wrapper table.table thead .sorting,table.table thead .sorting_asc,table.table thead .sorting_desc,table.table thead .sorting_asc_disabled,table.table thead .sorting_desc_disabled{cursor:hand;cursor:pointer}\r\n                .dataTables_wrapper table.table thead .sorting{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_both.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc_disabled.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc_disabled.png) no-repeat center right}\r\n</style>\r\n<!-- javascript datatable -->\r\n<script src=\"/gebo/lib/datatables/jquery.dataTables.min.js\"></script>\r\n<script src=\"/gebo/lib/datatables/extras/Scroller/media/js/Scroller.min.js\"></script>\r\n<!-- datatable functions -->\r\n<script src=\"/gebo/js/gebo_datatables.js\"></script>\r\n\r\n<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n	session[module_name]={:date=>params[:date]}\r\n	end\r\n	if session[module_name]\r\n	  params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n	\r\n	if request.post?\r\n	    r_app = get_model[:appointment].find(params[:app_id])\r\n	    status = \'Waiting\'\r\n	    if params[:app_status]\r\n	        status = params[:app_status]\r\n	    end\r\n	    r_app.update_attributes :status=>params[:app_status], :qn=>params[:qn]\r\n	end\r\n	\r\n	if params[:obj_id]\r\n	    now = Time.now \r\n	\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n					<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Add Visit</button></a>\r\n					<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n						-->\r\n					<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Calendar</button></a>\r\n					<a href=\"../Report/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n					<!--<a href=\"nurse_index?date=<%= params[:date] %>\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-heart\"></i><br />Nurse Index</button></a>-->\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\" >\r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n					<h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/\\\\#{params[:opt]}?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/<%= params[:opt] %>?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n%>\r\n\r\n\r\n\r\n<br/>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:320px;left:50%;margin-left:-360px\">\r\n	<div class=\"modal-header\">\r\n		<a href=\"#\" class=\"btn btn-mini\" style=\"float:right;\"  data-dismiss=\"modal\">X Close</a>\r\n		<h3>Patient Queue</h3>\r\n	</div>\r\n	<div class=\"modal-body\">\r\n		<form name=\'q\' method=\'post\'>\r\n			<span style=\'width:80px\'>Queue Number : </span><span class=\"field-input\" >\r\n			<input type=\"text\" name=\"qn\" id=\'qn\' style=\"width:50px\"/>\r\n			</span>\r\n			<input type=\"hidden\" name=\"app_id\" id=\"app_id\" value=\"\">\r\n			<input type=\"hidden\" name=\"app_status\" id=\"app_status\" value=\"Arrived\">\r\n			<div class=\"clear\"></div>\r\n			<input type=\"submit\" name=\"Submit\" value=\"Submit\" class=\"btn btn-success\"/>\r\n		</form>\r\n	</div>\r\n</div>\r\n<script>\r\n	function patient_q(app_id) {\r\n	    console.log(\"appointment id : \" + app_id);\r\n	    $(\'#app_id\').val(app_id);\r\n	    $(\'#modal\').modal({\r\n	        show: true, \r\n	        backdrop: \'static\',\r\n	        keyboard: true\r\n	    });\r\n	}\r\n	function patient_q(app_id, qn) {\r\n	    console.log(\"appointment id : \" + app_id);\r\n	    $(\'#qn\').val(qn);\r\n	    $(\'#app_id\').val(app_id);\r\n	    $(\'#modal\').modal({\r\n	        show: true, \r\n	        backdrop: \'static\',\r\n	        keyboard: true\r\n	    });\r\n	}\r\n</script>\r\n\r\n<script>\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n\r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'index_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        \r\n        setTimeout(feed_page(100), 0);\r\n        loadPartial();\r\n    });\r\n    \r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Room\',\'print_room?date=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Room Summary\',\'room_summay?date=\'+params[:date] %> |\r\n<!--<%= link_to \'Case Index\',\'case_index?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Patient Status\',\'patient_status?date=\'+params[:date] %> |-->\r\n<!--<%= link_to \'Patient Board\',\'../Feed/nurse_board?date=\'+params[:date] %> |-->\r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %> | \r\n\r\n<span class=\"right\">\r\n<%= link_to \'Inventory\',\'../../or_inventory/Home/index\' , :class=>\'btn btn-mini\' if @current_role==\'admin\' or @current_role==\'inventory\' or @current_role==\'developer\' %>\r\n</span>\r\n\r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2017-03-13 03:11:56','2017-03-13 03:11:56','index',''),(2969,'index_partial',1061,3,'<%= render :inline=>this.params_config %>\r\n<%= render :inline=>this.common_query %>\r\n<%\r\n    date = @date\r\n    \r\n    main_service = \'index\'\r\n    \r\n    all_ser = {}\r\n    @rs_serv.keys.each do |i|\r\n        k = i.to_sym\r\n        all_ser[k] = {}\r\n        get_model[k].find(@mid_ser[i]).each do |j|\r\n            all_ser[k][j.id.to_s] = j\r\n        end\r\n    end\r\n    \r\n    def val rec, field\r\n        f = field.to_sym\r\n        return (rec[f].nil? or rec[f]==\'\') ? \'-\' : rec[f]\r\n    end\r\n    \r\n    today = Time.now\r\n    \r\n    s_list = @status_list\r\n    \r\n    res = []\r\n    @rs_app.each do |i|\r\n        m = @rs_pat_mod[i.id.to_s]\r\n        pat = @rs_pat[m[:patient_id].to_s]\r\n        pat_id = pat.id.to_s\r\n        \r\n            age = \'-\'\r\n            if pat[:birth_date]\r\n                diff = Time.diff(today, pat[:birth_date])\r\n                year = diff[:year]\r\n                month = diff[:month]\r\n                day = diff[:day]\r\n                age = \"\\\\#{year}y.\\\\#{month}m.\"\r\n            end\r\n            \r\n        prov = \'N/A\'\r\n        if i[:provider]\r\n            tmp = @rs_prov[i[:provider].to_s][:name]\r\n            prov = tmp\r\n        end\r\n        \r\n        ward = \'N/A\'\r\n        if i[:visit_base] == \'OPD\'\r\n            ward = i[:visit_base]\r\n        elsif i[:visit_base] == \'IPD\'\r\n            ward = i[:ward]\r\n        end\r\n        \r\n        room = @rs_room[i[:room].to_s]\r\n        ward = @rs_ward[i[:ward].to_s]\r\n        \r\n        \r\n        r = {}\r\n        r[:id]   = i.id.to_s\r\n        r[:room] = room\r\n        r[:start] = (i[:start].nil? or i[:start] == \'\') ? \'-\' : i[:start].strftime(\'%H:%M\')\r\n        r[:stop]  = (i[:stop].nil? or i[:stop] == \'\') ? \'-\' : i[:stop].strftime(\'%H:%M\')\r\n        r[:time]  = r[:start]\r\n        r[:surgeon] = prov\r\n        r[:anesth] = val(i, :anesth_technique)\r\n        r[:dx] = i[:diagnosis_1]\r\n        r[:op] = i[:tentative_operation]\r\n        r[:ward] = ward\r\n        r[:hn]  = pat[:hn]\r\n        r[:age] = age\r\n        r[:ward] = ward\r\n        r[:pat_id]   = pat_id\r\n        r[:pat_name] = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]} \\\\#{pat[:last_name]}\"\r\n        r[:status] = i[:status]\r\n        r[:link] = {}\r\n        \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-mini btn-info \', :style=>\'width:45px\')\r\n                l_list = []\r\n                @service_map.each do |k, v|\r\n                    lab = k.to_s.split(\'_\')[0].humanize\r\n                    if k.to_s == \'pre_operative_visit\'\r\n                        lab = \'Visit\'\r\n                    end\r\n                    v_link = link_to(\"+ \\\\#{lab}\".html_safe, \r\n                        \"../\\\\#{v}/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{pat[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/\\\\#{main_service}?date=\\\\#{@p_date}\", \r\n                        :class=>\'btn btn-mini \', :style=>\'width:45px\' )\r\n                    if x = @rs_serv[k][pat_id]\r\n                        v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            \"../\\\\#{v}/show?id=\\\\#{x}&return=../Home/\\\\#{main_service}?date=\\\\#{@p_date}\", :class=>\'btn btn-mini btn-success\', :style=>\'width:45px\')\r\n                    end\r\n                    r[:link][k] = v_link\r\n                    l_list << v_link\r\n                end\r\n        \r\n        \r\n        r[:d_link] = d_link\r\n        r[:l_link] = l_list\r\n        \r\n        \r\n        r[:s_link] = link_to(\" show\".html_safe, \"../Appointment/show?id=\\\\#{m.id.to_s}&return=../Home/main\", :class=>\'btn btn-mini btn-info\', :style=>\'width:45px\')\r\n        r[:a_link] = r[:s_link].html_safe\r\n        # r[:a_link] = r[:link][:case_preparing].html_safe + \"&nbsp;&nbsp;\".html_safe + r[:s_link].html_safe\r\n        # r[:pat] = pat\r\n        res << r\r\n    end\r\n    \r\n    res = res.compact\r\n    \r\n    # group by status\r\n    sg = res.group_by{|i| i[:status]}\r\n%>\r\n<%# @rs_serv %>\r\n<!-- Status : Processing -->\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span-12\'>\r\n        <div class=\'w-box\'>\r\n            <div class=\'w-box-header\'  style=\'font-size:1.5em\'>\r\n                Appointed Patient\r\n            </div>\r\n            <div class=\'w-box-content cnt_a \' style=\'background:#FCF8F0\'>\r\n<%\r\n    s_idx = 0\r\n    s_list = []\r\n    r = {}\r\n%>\r\n                <div class=\'row-fluid\'>\r\n                                        <table id=\'appointed-patient\' class=\"table table-striped table-bordered dTableR\">\r\n    										<thead>\r\n    											<tr>\r\n    											    <th>No.</th>\r\n    												<th>Room</th>\r\n    												<th>Time</th>\r\n    												<th>Ward</th>\r\n    												<th>HN</th>\r\n    												<th>Name</th>\r\n    												<th>Age</th>\r\n    												<th>Anesth</th>\r\n    												<th>Diagnosis</th>\r\n    												<th>Operation</th>\r\n    												<th>Status</th>\r\n    												<th>Action</th>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n    res.sort_by{|i| [i[:room], i[:start]]}.each_with_index do |i, n|\r\n        r = i\r\n%>\r\n    											<tr>\r\n    											    <td><%= n + 1 %></td>\r\n    											    <td><%= r[:room] %> </td>\r\n    											    <td><%= r[:start] %></td>\r\n    												<td><%= r[:ward] %></td>\r\n    												<td><%= r[:hn] %></td>\r\n    												<td><%= r[:pat_name] %></td>\r\n    												<td><%= r[:age] %></td>\r\n    												<td><%= r[:anesth] %></td>\r\n    												<td><%= r[:dx] %></td>\r\n    												<td><%= r[:op] %></td>\r\n    												<td><%= r[:status] %> </td>\r\n    												<td><%= r[:l_link].join(\'&nbsp;\').html_safe %>&nbsp;<%= r[:d_link].html_safe %></td>\r\n    											</tr>\r\n<%  end %>\r\n    										</tbody>\r\n    									</table>\r\n                        <br/>\r\n                    <div class=\'clear\'></div>\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        gebo_datatbles = {\r\n    		dt_a: function() {\r\n    			$(\'#appointed-patient\').dataTable({\r\n    			    stateSave : true,\r\n                    \"sDom\": \"<\'row\'<\'span6\'<\'dt_actions\'>l><\'span6\'f>r>t<\'row\'<\'span6\'i><\'span6\'p>>\",\r\n                    \"sPaginationType\": \"bootstrap_alt\",\r\n                    \"oLanguage\": {\r\n                        \"sLengthMenu\": \"_MENU_ records per page\"\r\n                    }\r\n                });\r\n    		}\r\n        }\r\n        \r\n        gebo_datatbles.dt_a();\r\n    })\r\n</script>',NULL,NULL,NULL,'2017-03-13 03:12:27','2017-03-13 03:12:27','index_partial',''),(2970,'print',1168,3,'<%= render :inline=>this.init %>\r\n\r\n<%\r\n  \r\n  models = get_model\r\n  \r\n  \r\n  \r\n   items = models[:store_item].where(:store_id=>@current_store.id).all\r\n   \r\n   products = models[:product].find items.collect{|i| i.product_id}\r\n   pm = {}\r\n   for i in products\r\n    pm[i.id] = i\r\n   end\r\n  \r\n#   store = models[:store].find @current_store\r\n   \r\n#   record = model.find(params[:id])\r\n#   @show=true\r\n%>\r\n<html>\r\n<head>\r\n			<%= javascript_include_tag \"application\"  %>\r\n			<%= stylesheet_link_tag    \"application\", media: \"all\" %>\r\n			<%= csrf_meta_tag %>\r\n\r\n    \r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n    \r\n</head>\r\n    <body>\r\n        \r\n<% if true %>\r\n\r\n<style>\r\n    #page {border:solid 1px; margin-left:-50px;width:810px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nv{color:blue;}\r\n</style>\r\n\r\n\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><b style=\"margin-top:20px;font-size:1.5em\">Inventory System</b></div>\r\n\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%=thdate Time.now %> <%=Time.now.strftime(\"%H:%M\") %></p>\r\n</div>\r\n</div>\r\n\r\n<%\r\n   \r\n%>\r\n<div class=\"row-fluid\">\r\n        <div class=\"span3\">\r\n                Store ID : <v><%=@current_store.name %></v>\r\n        </div>\r\n      \r\n    </div><br/>\r\n    \r\n<%\r\n\r\n    page = 0 \r\n    npage = 32\r\n    \r\n       total = 0 \r\n           \r\n            items.each_with_index do |i,index| \r\n                \r\n                \r\n%>                \r\n   \r\n <% if index==0  || index%npage==npage-1 %>  \r\n    \r\n<div id=\"page\" style=\"page-break-after: always;\">\r\n<br/>\r\n\r\n    <table class=\"table\">\r\n        <thead>\r\n            <tr>\r\n                <th>No.</th><th>Description</th><th>Manufacture</th><th>Lot</th><th>Cost</th><th>Price</th><th>Balance</th><th>Amount</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n        \r\n<% end %>\r\n       \r\n        <% \r\n    \r\n                \r\n            p = pm[i.product_id]\r\n            if p \r\n            a = 0 \r\n            a = p.price.to_i * i.balance.to_i if p.price and i.balance\r\n            total += a\r\n        %>\r\n            <tr><td><%=index+1%>.</td>\r\n                <td><%=p.name %></td>\r\n                 <td><%=p.manufacture %></td>\r\n                 <td></td>\r\n                <td><%=fm p.cost %></td>\r\n                <td><%=fm p.price %></td>\r\n                <td><%=fn i.balance %></td>\r\n                <td><%=fm a %></td>\r\n            </tr>\r\n      \r\n           \r\n\r\n\r\n<% if index%npage==npage%>\r\n <tr>\r\n                <td colspan=\"5\">&nbsp;</td>\r\n                <td >Sub total</td>\r\n                <td ><%= fm total %></td>\r\n            </tr>\r\n        </tbody>\r\n    </table>\r\n</div>\r\n\r\n<% end %>\r\n<% end %>\r\n  <% end %>\r\n\r\n<% end %>\r\n\r\n<style type=\"text/css\" media=\"all\">\r\n    #page {border:solid 1px; width:910px;margin-left:0px ; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\n</style>\r\n<script>\r\n    $(document).ready(function(){\r\n        // alert(\'dijfdf\')\r\n        window.print();\r\n        window.onfocus=function(){ window.close();}\r\n    })\r\n</script>   \r\n    </body>\r\n</html>',NULL,NULL,NULL,'2017-03-15 07:19:38','2017-03-15 07:19:38','print',''),(2971,'document_name',1186,1,'\'head_neck_registry\'',NULL,NULL,NULL,'2017-03-16 01:52:21','2017-03-16 01:52:21',NULL,NULL);
INSERT INTO `esm_operations` VALUES (2974,'index',407,2,'<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Appointment</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\',:style=>\'width:120px\' %> <%=link_to \"( Today Click )\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n       <%= date.strftime(\'%A %d %B %Y\')%><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}\r\n    map_status = {\'appointed\'=>\'นัดตรวจ\',\'waiting\'=>\'รอตรวจ\',\'processing\'=>\'เข้าห้องตรวจ\',\'recovery\'=>\'รอผลตรวจ\',\'completed\'=>\'เสร็จสิ้น\',\'cancelled\'=>\'ยกเลิกนัด\'}\r\n    \r\n    status_list.collect!{|i| \r\n    k = map_status[i] ; \r\n    \r\n    k = i.humanize unless k\r\n    \r\n    [ k, i.humanize ] \r\n    }\r\n    \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n </div><br/>\r\n \r\n',NULL,NULL,NULL,'2017-03-16 06:58:35','2017-03-16 06:58:35','',''),(2975,'index',1188,2,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    patients =  module_model.all(:module_name=>mname)\r\n    \r\n    \r\n    list = []\r\n    \r\n    \r\n    \r\n    list = module_model.collection.group({:keyf=>\'function(doc){return {month:doc.date.getMonth(),name:doc.module_name};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}})\r\n          \r\n          \r\n        columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n   \r\n    map = {}\r\n    data = []\r\n         \r\n    if list.size>0    \r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    name = i[\'name\'].split(\'#\')[1]\r\n    map[name] = {\'name\'=>name.humanize, \'data\'=>[]} unless map[name] \r\n    map[name][\'data\'][i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\n    end\r\n    map.each_pair do |k,v|\r\n    if k!=\'appointment\'\r\n        data << v    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n   \r\n    columns = mlabels\r\n\r\n%>\r\n\r\n<%#list.inspect%>\r\n<div class=\'span12\' style=\'background:#FFF;padding:10px\'>\r\n<h3>Summary</h3>\r\n\r\n<%\r\n\r\n%>\r\n\r\n<div id=\"chart\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n\r\n<br/>\r\n</div>\r\n\r\n\r\n\r\n\r\n            <script>\r\n                function createChart() {\r\n                    $(\"#chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                }\r\n\r\n                $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n                });\r\n            </script>\r\n\r\n\r\n',NULL,NULL,NULL,'2017-03-20 04:07:03','2017-03-20 04:07:03','index',''),(2976,'context_menu',1188,4,'\r\n<% \r\n   obj = [\r\n        {:name=>\'Reports\',:open=>true,:actions=>[\r\n                {:name=>\'Room Usage\',:service=>\'\',:link=>\'room_usage\',:remote=>false}\r\n            ]\r\n        },\r\n        {:name=>\'Links\',:open=>true,:actions=>[\r\n                {:name=>\'Back to Home\',:service=>\'\',:link=>\'../Home/index\',:remote=>false}\r\n            ]\r\n        }\r\n    ]\r\n\r\n#   obj << {:name=>\'Links\', :actions=>[{:name=>\'Back to EHR\',:link=>\"../../www/Home/index\",:remote=>false}]}\r\n%>\r\n<%= show_menu obj%>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<!--</div></div></div>-->',NULL,NULL,NULL,'2017-03-20 04:10:08','2017-03-20 04:10:08','context_menu',''),(2977,'room_usage',1188,2,'<style>\r\n    .field-label{\r\n        width:100px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:240px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    .weekend {\r\n        background: #ccc;\r\n    }\r\n    .status_cls{\r\n		width:100px\r\n    }\r\n</style>\r\n\r\n<%\r\n    today = Time.now\r\n    \r\n    mon_list = []\r\n    year_list = []\r\n    \r\n    f_int = get_model[:intra_operative].first\r\n    l_int = get_model[:intra_operative].last\r\n    \r\n    fir_year = f_int[:created_at].strftime(\'%Y\').to_i\r\n    cur_year = today.strftime(\'%Y\').to_i\r\n    \r\n    cur_month = today.strftime(\'%m\').to_i\r\n    \r\n    1.upto(12) do |i|\r\n        d = Date.new(cur_year, i, 1)\r\n        mon_list << [d.strftime(\'%B\'), i]\r\n    end\r\n    \r\n    fir_year.upto(cur_year) do |i|\r\n        year_list << i\r\n    end\r\n    \r\n    if request.post?\r\n        if s = params[:search]\r\n            cur_month = s[:month].to_i\r\n            cur_year  = s[:year].to_i\r\n        end\r\n    end\r\n    \r\n    params[:sdate] = \"1/\\\\#{cur_month}/\\\\#{cur_year}\"\r\n    params[:edate] = \"\\\\#{Date.civil(cur_year, cur_month, -1).strftime(\'%d/%m/%Y\')}\"\r\n    \r\n    sd = Date.strptime(params[:sdate], \'%d/%m/%Y\') \r\n	ed = Date.strptime(params[:edate], \'%d/%m/%Y\') \r\n    \r\n    # ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n%>\r\n<%= render :inline=>this.params_config %>\r\n<%= render :inline=>this.common_query %>\r\n<%\r\n    par_ids = []\r\n    @rs_pat_mod.each do |k,v|\r\n        par_ids << v.id\r\n    end\r\n    \r\n    int_ids = @m_pat_mod.where(:parent_id=>par_ids, :module_name=>\"\\\\#{@current_project.name}#intra_operative\").all\r\n    \r\n    rs_int  = get_model[:intra_operative].find(int_ids.collect{|i| i[:module_id]})\r\n%>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box-header\">\r\n			<h3>Search</h3>\r\n		</div>\r\n        <div class=\"w-box-content cnt_a\">\r\n<%= form_for :search,:url=>params[:opt], :html=>{:style=>\'margin-bottom:0px\'}, :remote=>false do |f| %>\r\n	    <span class=\"field-data\"> \r\n			<label class=\"field-label\" >Select Month :  </label>\r\n			<div class=\"field-input\" style= ><%= f.select :month, mon_list, {:include_blank=>false, :selected=>cur_month}, :id=>\'month\', :style=>\'width:120px\' %></div>\r\n		</span> \r\n		<!--select(method, choices = nil, options = {}, html_options = {}, &block) public-->\r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">Select Year :  </label>\r\n			<div class=\"field-input\" ><%= f.select :year, year_list, {:include_blank=>false}, :id=>\'year\', :style=>\'width:100px\' %></div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n		<span class=\"field-data\">\r\n		    <div class=\"field-input\"><%=f.submit \'Submit\', :class=>\'btn btn-success\'%> </div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n<% end %>\r\n\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class=\'clear\'></div>\r\n<br/>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span6\">\r\n        <div class=\"w-box-header\">\r\n			<h3>Result</h3>\r\n		</div>\r\n        <div class=\"w-box-content cnt_a\">\r\n            \r\n            <table class=\'table table-striped table-bordered dTableR dataTable\'>\r\n                <thead>\r\n                    <th>Date / Room</th>\r\n<%\r\n    @rs_room_list.each do |i|\r\n%>\r\n                    <th><%= i %></th>\r\n<%  end %>\r\n                </thead>\r\n                <tbody>\r\n<%\r\n    last_date = ed.strftime(\'%d\').to_i\r\n    1.upto(last_date) do |i|\r\n        d = Date.new(cur_year, cur_month, i)\r\n        x = d.strftime(\'%a\')\r\n        c = \'\'\r\n        if x == \'Sun\' or x == \'Sat\'\r\n            c = \'weekend\'\r\n        end\r\n%>\r\n                    <tr class=\'<%= c %>\'>\r\n                        <td><%= d.strftime(\'%d/%m/%Y\') %></td>\r\n<%\r\n\r\n%>\r\n                    </tr>\r\n<%\r\n    end\r\n%>\r\n                </tbody>\r\n            </table>\r\n            \r\n        </div>\r\n    </div>\r\n</div>\r\n',NULL,NULL,NULL,'2017-03-20 04:10:43','2017-03-20 04:10:43','room_usage',''),(2978,'common_query',1188,4,'<%\r\n    # time begin\r\n    tb = Time.now\r\n    date = Time.now\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	@m_pat = @ehr_model[:patient]\r\n	@m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n# 	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n    status_list = @status_list\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	r_model = models[:room]\r\n	w_model = models[:ward]\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	room_list = [\'N/A\']\r\n	rooms = {nil=>\'N/A\',\'\'=>\'N/A\'}\r\n	r_model.all.each do |i|\r\n	    rooms[i.id.to_s] = i[:name]\r\n	    room_list << i[:name]\r\n	end\r\n	\r\n	wards = {nil=>\'N/A\', \'\'=>\'N/A\'}\r\n	w_model.all.each do |i|\r\n	    wards[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	if params[:date]\r\n	    date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n	    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	elsif params[:sdate] and params[:edate]\r\n	    sd  = Date.strptime(params[:sdate], \'%d/%m/%Y\') \r\n	    ed  = Date.strptime(params[:edate], \'%d/%m/%Y\') \r\n	    aps = ap_model.all(:date.gte=>sd.at_beginning_of_day,:date.lt=>ed.end_of_day) \r\n	end\r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	\r\n	id = \'\'\r\n	a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = @m_pat_mod.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n	\r\n	# form service\r\n	f_ser = {}\r\n	# module_id from service\r\n	mid_ser = {}\r\n	mid_map = {}\r\n	# service_map\r\n	sm = @service_map\r\n	sm.each do |k, v|\r\n	    f_ser[k] = {}\r\n	    mid_map[k] = {}\r\n	    mid_ser[k] = []\r\n	    tmp = @m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>pa_id).all\r\n	    tmp.each do |i|\r\n	        f_ser[k][i[:patient_id].to_s] = i.id.to_s\r\n	        mid_map[k][i[:patient_id].to_s] = i[:module_id].to_s\r\n	        mid_ser[k] << i[:module_id].to_s\r\n	        \r\n	    end\r\n	end\r\n	\r\n	rs_pat_mod = {}\r\n	pat_id = []\r\n	@m_pat_mod.where(:module_name=>mname, :module_id=>a_id).all.each do |i|\r\n	    rs_pat_mod[i[:module_id].to_s] = i\r\n	    pat_id << i[:patient_id].to_s\r\n	end\r\n	\r\n	rs_pat = {}\r\n	@m_pat.find(pat_id).each do |i|\r\n	    rs_pat[i.id.to_s] = i\r\n	end\r\n\r\n	res = {}\r\n	res[:time] = Time.now - tb\r\n	res[:aps_count] = aps.size\r\n	res[:aps] = aps\r\n	\r\n	@res = res\r\n	\r\n	@rs_app  = aps\r\n	@rs_pat  = rs_pat\r\n	@rs_pat_mod = rs_pat_mod\r\n	@rs_room = rooms\r\n	@rs_ward = wards\r\n	@rs_room_list = room_list\r\n	@rs_serv = f_ser\r\n	@mid_ser = mid_ser # result of  module id service\r\n	@mid_map = mid_map\r\n	@date = date\r\n	@p_date = date.strftime(\'%d/%m/%Y\')\r\n	\r\n	@total_time = Time.now - tb\r\n%>',NULL,NULL,NULL,'2017-03-20 04:11:59','2017-03-20 04:11:59','common_query',''),(2979,'print',899,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n<%= javascript_include_tag \"application\"  %>\r\n<%= csrf_meta_tag %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm_core/banner.png\" width=\"300\"/></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h3><%=this.table_name.to_s.humanize%></h3>\r\n<%= this.display.html_safe %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div class=\"hideprint\">\r\n<%= link_to \'Back\', url(\'index\') %>\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n<script>\r\n    function load_content() {\r\n      $.ajax({\r\n        url: \'rec_partial?pm_id=<%=params[:id]%>\',\r\n        success: function(data) {\r\n          //  alert(\"update\");\r\n          // do something with the return value here if you like\r\n          $(\'#rrt-result\').fadeOut(500, function(){\r\n            $(\'#rrt-result\').html(data);\r\n          })\r\n          $(\'#rrt-result\').fadeIn(500)\r\n        }\r\n      });\r\n    }\r\n    $(document).ready(function() {\r\n        load_content();\r\n    });\r\n</script>\r\n\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2017-03-20 06:01:37','2017-03-20 06:01:37','print',''),(2980,'params_config',1188,4,'<%\r\n    @service_map = {\r\n            :case_preparing=>\'CasePreparing\',\r\n            :pre_operative_visit=>\'PreOperativeVisit\',\r\n            :pre_operative=>\'PreOperative\',\r\n            :intra_operative=>\'IntraOperative\',\r\n            :post_operative=>\'PostOperative\'\r\n        }\r\n    @status_list = %w{Appointed Pre-op Waiting Ready Processing Recovery Post-op ICU Discharged}\r\n    \r\n    def map_model(model)\r\n        # tmp = {nil=>\'N/A\',\'\'=>\'N/A\'}\r\n        tmp = {}\r\n        get_model[model].all.each do |i|\r\n            tmp[i.id.to_s] = i\r\n        end\r\n        return tmp\r\n    end\r\n    \r\n    @rs_visit = map_model :visit_type\r\n    @rs_prov  = map_model :provider\r\n    @rs_indi  = map_model :indication\r\n    @rs_proc  = map_model :procedure\r\n%>',NULL,NULL,NULL,'2017-03-21 03:32:46','2017-03-21 03:32:46','params_config',''),(2981,'common_function',1185,4,'<%\r\n    def document_query(cond = {}, sel_fields = {}, doc = \'obstetrics\') \r\n        res = []\r\n        \r\n        if cond.empty?\r\n            today = Time.now\r\n            sdate = today.at_beginning_of_month\r\n            edate = today.end_of_month\r\n            cond[:created_at] = {\'$gte\'=>sdate.beginning_of_day,\'$lt\'=>edate.end_of_day}\r\n        end\r\n        \r\n        fields = {}\r\n        fields[:fields] = sel_fields\r\n        \r\n        obj = get_model[doc.to_sym].collection.find(cond, fields).to_a\r\n        if obj\r\n            res = obj\r\n        end\r\n        \r\n        return res\r\n    end\r\n    \r\n    def get_patient_by_document_result(res = [])\r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        m_pat = model[:patient]\r\n        m_pat_mod = model[:patient_module]\r\n        \r\n        g_form = res.group_by{|i| i[\'_id\']}\r\n        \r\n        fid = g_form.keys\r\n        # tmp = m_pat_mod.where(:module_id=>fid).all\r\n        tmp = m_pat_mod.collection.find({\'module_id\'=>{\'$in\'=>fid}}, {:fields=>{\'patient_id\'=>1, \'module_id\'=>1, \'created_at\'=>1, \'module_name\'=>1}}).to_a\r\n        g_tmp = tmp.group_by{|i| i[\'module_id\']}\r\n        \r\n        pid = tmp.collect{|i| i[\'patient_id\']}\r\n        pat = m_pat.collection.find({\'_id\'=>{\'$in\'=>pid}},{:fields=>{\'hn\'=>1, \'prefix_name\'=>1,\'first_name\'=>1,\'last_name\'=>1}}).to_a\r\n        \r\n        g_pat = pat.group_by{|i| i[\'_id\']}\r\n        \r\n        # res = {}\r\n        # res[:patient] = g_pat\r\n        # res[:module_link] = g_tmp\r\n        \r\n        # return res\r\n        return g_pat\r\n    end\r\n    \r\n    def get_patient_module_by_document_result(res = [])\r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        m_pat = model[:patient]\r\n        m_pat_mod = model[:patient_module]\r\n        \r\n        g_form = res.group_by{|i| i[\'_id\']}\r\n        \r\n        fid = g_form.keys\r\n        # tmp = m_pat_mod.where(:module_id=>fid).all\r\n        res = m_pat_mod.collection.find({\'module_id\'=>{\'$in\'=>fid}}, {:fields=>{\'patient_id\'=>1, \'module_id\'=>1, \'created_at\'=>1, \'module_name\'=>1, \'parent_id\'=>1}}).to_a\r\n        return res\r\n    end\r\n\r\n    # def get_pat_with_document_result(res = [])\r\n    #     ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    #     model = ehr.load_model\r\n    #     m_pat = model[:patient]\r\n    #     m_pat_mod = model[:patient_module]\r\n        \r\n    #     g_form = res.group_by{|i| i[\'_id\']}\r\n        \r\n    #     fid = g_form.keys\r\n    #     # tmp = m_pat_mod.where(:module_id=>fid).all\r\n    #     tmp = m_pat_mod.collection.find({\'module_id\'=>{\'$in\'=>fid}}, {:fields=>{\'patient_id\'=>1, \'module_id\'=>1, \'created_at\'=>1, \'module_name\'=>1}}).to_a\r\n    #     g_tmp = tmp.group_by{|i| i[\'module_id\']}\r\n        \r\n    #     pid = tmp.collect{|i| i[\'patient_id\']}\r\n    #     pat = m_pat.collection.find({\'_id\'=>{\'$in\'=>pid}},{:fields=>{\'hn\'=>1, \'prefix_name\'=>1,\'first_name\'=>1,\'last_name\'=>1}}).to_a\r\n        \r\n    #     g_pat = pat.group_by{|i| i[\'_id\']}\r\n        \r\n    #     # res = {}\r\n    #     # res[:patient] = g_pat\r\n    #     # res[:module_link] = g_tmp\r\n        \r\n    #     # return res\r\n    #     return g_pat\r\n    # end\r\n\r\n    def get_icd_code(cond = {}, code_list = [], service = \'obstetrics\')\r\n            \r\n            if cond.empty?\r\n                today = Time.now\r\n                sdate = today.at_beginning_of_month\r\n                edate = today.end_of_month\r\n                cond[:created_at] = {\'$gte\'=>sdate.beginning_of_day,\'$lt\'=>edate.end_of_day}\r\n            end\r\n            \r\n            #\r\n            # Obstetrics \r\n            #\r\n            rs_obs= []\r\n            id_obs= {}\r\n            f_map = {\r\n                \'comorbidity\'=>{:n=>:icd_comorbidity,:f=>:comorbidity}, \r\n                \'complication\'=>{:n=>:icd_complication,:f=>:complication}, \r\n                \'external_cause\'=>{:n=>:icd_external_cause,:f=>:external_cause}, \r\n                \'other_diagnosis\'=>{:n=>:icd_other_diagnosis,:f=>:other_diagnosis}, \r\n                \'operation\'=>{:n=>:icd_operation,:f=>:operation}\r\n            }\r\n            f_obs = {:icd_comorbidity=>[], :icd_complication=>[], :icd_external_cause=>[], :icd_other_diagnosis=>[], :icd_operation=>[]}\r\n            obs = get_model[service.to_sym].collection.find(cond, {:fields=>{\'_id\'=>1, \'principle_diagnosis\'=>1, \'comorbidity\'=>1, \'complication\'=>1, \'external_cause\'=>1, \'other_diagnosis\'=>1, \'operation\'=>1}}).to_a\r\n            \r\n            obs.each do |i|\r\n                id = i[\'_id\']\r\n                icd = (!i[\'principle_diagnosis\'].nil? and i[\'principle_diagnosis\'] != \'\') ? i[\'principle_diagnosis\'].upcase : \'---\'\r\n                if !code_list.empty?\r\n                    rs_obs << {:form_id=>id, :icd=>icd, :group=>\'principle_diagnosis\'} if code_list.include? icd\r\n                else\r\n                    rs_obs << {:form_id=>id, :icd=>icd, :group=>\'principle_diagnosis\'}\r\n                end\r\n                # rs_obs << {:form_id=>id, :icd=>icd, :group=>\'principle_diagnosis\'}\r\n                f_map.each do |k, v|\r\n                    ls = i[k]\r\n                    if ls != \'\' and !ls.nil?\r\n                        if !ls.empty?\r\n                            f_obs[v[:n]] += ls \r\n                            ls.each do |j|\r\n                                id_obs[j] = id\r\n                            end\r\n                        end\r\n                    end\r\n                end\r\n            end\r\n            # obj = id_obs\r\n            tmp = []\r\n            f_map.each do |k,v|\r\n                # model name\r\n                mn = v[:n]\r\n                # field name\r\n                fn = v[:f].to_s\r\n                # list value\r\n                lv = f_obs[mn]\r\n                # group name\r\n                gn = fn\r\n                \r\n                tmp = get_model[mn].collection.find({\'_id\'=>{\'$in\'=>lv}}, {:fields=>{\'_id\'=>1, fn=>1}})\r\n                tmp.each do |i|\r\n                    f_id = id_obs[i[\'_id\']]\r\n                    # code list\r\n                    # cl   = i[fn].split(\',\')\r\n                    cl   = i[fn].split(/[\\s,.]/)\r\n                    if cl.count == 1\r\n                        if !code_list.empty?\r\n                            rs_obs << {:form_id=>f_id, :icd=>cl[0].strip, :group=>gn} if code_list.include? cl[0].strip\r\n                        else\r\n                            rs_obs << {:form_id=>f_id, :icd=>cl[0].strip, :group=>gn}\r\n                        end\r\n                        # rs_obs << {:form_id=>f_id, :icd=>cl[0].strip, :group=>gn}\r\n                    else\r\n                        cl.each do |j|\r\n                            if !code_list.empty?\r\n                                rs_obs << {:form_id=>f_id, :icd=>j.strip, :group=>gn} if code_list.include? j.strip\r\n                            else\r\n                                rs_obs << {:form_id=>f_id, :icd=>j.strip, :group=>gn}\r\n                            end\r\n                            # rs_obs << {:form_id=>f_id, :icd=>j.strip, :group=>gn}\r\n                        end\r\n                    end\r\n                end\r\n            end\r\n        return rs_obs\r\n    end\r\n    \r\n    def get_patient_by_icd_result(result_list = []) \r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        m_pat = model[:patient]\r\n        m_pat_mod = model[:patient_module]\r\n        \r\n        x = result_list\r\n        \r\n        g_form = x.group_by{|i| i[:form_id]}\r\n        \r\n        fid = g_form.keys\r\n        # tmp = m_pat_mod.where(:module_id=>fid).all\r\n        tmp = m_pat_mod.collection.find({\'module_id\'=>{\'$in\'=>fid}}, {:fields=>{\'patient_id\'=>1, \'module_id\'=>1, \'created_at\'=>1, \'module_name\'=>1}}).to_a\r\n        g_tmp = tmp.group_by{|i| i[\'module_id\']}\r\n        \r\n        pid = tmp.collect{|i| i[\'patient_id\']}\r\n        pat = m_pat.collection.find({\'_id\'=>{\'$in\'=>pid}},{:fields=>{\'hn\'=>1, \'prefix_name\'=>1,\'first_name\'=>1,\'last_name\'=>1}}).to_a\r\n        \r\n        g_pat = pat.group_by{|i| i[\'_id\']}\r\n        \r\n        return g_pat\r\n    end\r\n    \r\n    def get_document_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].nil? ? \'\' : x[1].strip\r\n                    tmp[:list] << x[1].nil? ? \'\' : x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    def get_value f, fdoc, val\r\n        x = fdoc[f.to_sym]\r\n        v = val\r\n        h = x.to_h\r\n        if h.has_key? :pair and !v.nil? and v != \'\'\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n        elsif h[:field_type] == \'select_time\' and !v.nil? and v != \'\'\r\n            v = val.strftime(\'%H:%M\')\r\n        elsif h[:field_type] == \'relation_one\'\r\n            pr = eval(\"{\\\\#{h[:params]}}\")\r\n            dd = pr[:relation][:document]\r\n            v = get_model[dd].find(v)\r\n            v = v[:name] if v\r\n        end\r\n        return v\r\n    end\r\n    \r\n    @obj = {}\r\n    def val f, doc, default = \'N/A\'\r\n        doc = doc.to_sym\r\n        f = f.to_sym\r\n        if @obj.has_key? doc\r\n            # get_value(:premed, obj[:pre_operative_visit][:df], obj[:pre_operative_visit][:rec][:premed])\r\n            rt = get_value(f, @obj[doc][:df], @obj[doc][:rec][f])\r\n            return (rt.nil? or rt==\'\') ? default : rt\r\n        else\r\n            return default\r\n        end\r\n    end\r\n%>',NULL,NULL,NULL,'2017-03-23 06:33:58','2017-03-23 06:33:58','common_function',''),(2982,'admission_ob',1185,2,'<%\r\n    tb = Time.now\r\n%>\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n		width:100px\r\n    }\r\n    \r\n    .tbth {\r\n        vertical-align: middle;\r\n        text-align: center;\r\n    }\r\n\r\n</style>\r\n\r\n<%\r\n    year = []\r\n    cur_year = tb.strftime(\'%Y\').to_i\r\n    2016.upto(cur_year) do |i|\r\n        year << i\r\n    end\r\n%>\r\n<% if false %>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box-header\">\r\n			<h3>Search</h3>\r\n		</div>\r\n        <div class=\"w-box-content cnt_a\">\r\n<%= form_for :search,:url=>params[:opt],:html=>{:style=>\'margin-bottom:0px\'}, :remote=>false do |f| %>\r\n        <span class=\'field-data\' >\r\n		    <label class=\'field-label\' >Start Year : </label>\r\n		    <div class=\'field-input\' ><%= f.select :syear, year, {:include_blank=>false, :selected=>cur_year}, :id=>\'start_year\', :style=>\'width:120px\' %></div>\r\n		</span>\r\n	    <span class=\'field-data\' >\r\n		    <label class=\'field-label\' >End Year : </label>\r\n		    <div class=\'field-input\' ><%= f.select :eyear, year, {:include_blank=>false, :selected=>cur_year}, :id=>\'end_year\', :style=>\'width:120px\' %></div>\r\n		</span>\r\n		\r\n		<div class=\'clear\'></div>\r\n		<span class=\"field-data\">\r\n		    <div class=\"field-input\"><%=f.submit \'Submit\', :class=>\'btn btn-success\'%> </div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n\r\n<% end %>\r\n    </div>\r\n</div>\r\n<% end %>\r\n\r\n<%= render :inline=>this.common_function %>\r\n<%\r\n    style = \"style=\'vertical-align: middle;text-align: center;\'\".html_safe\r\n    \r\n    sdate = Time.strptime(\"1/01/2017\", \"%d/%m/%Y\")\r\n    edate = Time.strptime(\"31/12/2017\", \"%d/%m/%Y\")\r\n    cond = {}\r\n    cond[:admission_date] = {\'$gte\'=>sdate.beginning_of_day,\'$lt\'=>edate.end_of_day}\r\n    \r\n    sf = {:admission_date=>1, :ward=>1, :color=>1}\r\n    res = document_query(cond, sf, \'obstetrics\')\r\n    # z = get_pat_by_document_result(y)\r\n    \r\n    c = %w{เขียว เหลือง ฟ้า แดง ชมพู}\r\n    \r\n    grs = res.group_by{|i| i[\'admission_date\'].nil? ? \"00/\\\\#{cur_year}\" : i[\'admission_date\'].strftime(\'%m/%Y\')}\r\n    \r\n%>\r\n<%# grs.to_json.html_safe %>\r\n\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\'>\r\n        <div class=\'w-box-header\'>\r\n            <h3>Result on <%= cur_year %></h3>\r\n        </div>\r\n        <div class=\'w-box-content cnt_a\'>\r\n            \r\n            <table class=\"table table-bordered\" style=\'width:100%\'>\r\n                <thead>\r\n                    <tr>\r\n                        <th rowspan=2 <%= style %>>Month</th>\r\n                        <th rowspan=2 <%= style %>>No.Admission</th>\r\n                        <th colspan=2 <%= style %>>No.Patient</th>\r\n                        <th colspan=5 <%= style %>>สาย</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <th <%= style %>>ทั่วไป</th>\r\n                        <th <%= style %>>พิเศษ</th>\r\n<%\r\n    c.each do |i|\r\n%>\r\n                        <th <%= style %>><%= i %></th>\r\n<% end %>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n<%\r\n    1.upto(12) do |i|\r\n        m = format(\'%02d\', i)\r\n        k = \"\\\\#{m}/\\\\#{cur_year}\"\r\n        \r\n        r = grs[k]\r\n        if !r.nil?\r\n            wg = r.group_by{|x| x[\'ward\']}\r\n            cg = r.group_by{|x| x[\'color\']}\r\n            \r\n            np = 0\r\n            sp = 0\r\n            n_list = []\r\n            s_list = []\r\n            wg.each do |x,y|\r\n                if x.include? \'นม.8\' or x.include? \'14\'\r\n                    sp += y.count\r\n                    s_list += y\r\n                else\r\n                    np += y.count\r\n                    n_list += y\r\n                end\r\n            end\r\n            \r\n            spat = get_patient_by_document_result(s_list)\r\n            npat = get_patient_by_document_result(n_list)\r\n            \r\n            ap = get_patient_by_document_result(r)\r\n%>\r\n                    <tr>\r\n                        <td <%= style %>><%= k %></td>\r\n                        <td <%= style %>><%= r.count %></td>\r\n                        <td <%= style %>><%= npat.count %></td>\r\n                        <td <%= style %>><%= spat.count %></td>\r\n<%\r\n        c.each do |j|\r\n            idx = c.index(j) + 1\r\n            n   = 0\r\n            tmp = cg[idx.to_s]\r\n            if !tmp.nil?\r\n                n = tmp.count\r\n            end\r\n%>\r\n                        <td <%= style %>> <%= n %> </td>\r\n<%      end %>\r\n                    </tr>\r\n<%  \r\n        else\r\n%>\r\n                    <tr>\r\n                        <td <%= style %>><%= k %></td>\r\n                        <td <%= style %>>-</td>\r\n                        <td <%= style %>>-</td>\r\n                        <td <%= style %>>-</td>\r\n                        <td <%= style %>>-</td>\r\n                        <td <%= style %>>-</td>\r\n                        <td <%= style %>>-</td>\r\n                        <td <%= style %>>-</td>\r\n                        <td <%= style %>>-</td>\r\n                    </tr>\r\n<%\r\n        end\r\n    end # end month\r\n    \r\n%>\r\n                </tbody>\r\n            </table>\r\n            \r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<hr/>\r\nProcessing time : <%= Time.now - tb %> ms.',NULL,NULL,NULL,'2017-03-23 06:36:01','2017-03-23 06:36:01','admission_ob',''),(2983,'pat_search',214,3,'<% \r\n    @document = get_document(this.document_name)\r\n    fields = @document.list_fields\r\n    labels = fields.collect{|i| i.column_name }\r\n    model = get_model(this.table_name)\r\n    res = {}\r\n    user = get_model[:user].where(:login=>params[:user]).first\r\n    if user\r\n        res = model.where(:hn=>params[:hn]).first\r\n        if res.nil?\r\n            res = {}\r\n        else\r\n            res[:application] = @current_solution.name\r\n        end\r\n        \r\n    end\r\n#   query = params[:q]\r\n#   keys = []\r\n#   @document.list_fields.each_with_index do |f,index| \r\n#     keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n#   end\r\n\r\n#   records = model.all({\'$or\'=>keys}.merge!({:limit=>20}))\r\n    # res[:params] = params\r\n%>\r\n<%= res.to_json.html_safe %>\r\n',NULL,NULL,NULL,'2017-03-25 09:43:13','2017-03-25 09:43:13','pat_search','*'),(2984,'document_name',1189,1,'\'enteroscopy\'',NULL,NULL,NULL,'2017-03-25 14:16:56','2017-03-25 14:16:56',NULL,NULL),(2985,'print_partial',1189,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    gas_id = pm.module_id\r\n    record = models[:enteroscopy].find(gas_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px;padding-left:20px;padding-right:20px }\r\n#head { width:100%; height:80px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n \r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n.thumbnail {\r\n  position: relative;\r\n  width: 300x;\r\n  height: 300px;\r\n  overflow: hidden;\r\n}\r\n.thumbnail img {\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 50%;\r\n  height: 100%;\r\n  width: auto;\r\n  -webkit-transform: translate(-50%,-50%);\r\n      -ms-transform: translate(-50%,-50%);\r\n          transform: translate(-50%,-50%);\r\n}\r\n.thumbnail img.portrait {\r\n  width: 100%;\r\n  height: auto;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\'  %>\' height=\'70px\' /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Enteroscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=record.date_note%></v>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n<hr />\r\n    \r\n		<table width=\"100%\"><tr><td width=\"60%\" valign=\"top\">\r\n		\r\n		\r\n     <h4 style=\"padding:0px; margin:0px; margin-left:10px;margin-bottom:5px \">Status : <%=record[\'status\']%> </h4>\r\n						<table width=\"100%\">\r\n				<tr>\r\n					<td><label>Previous opreation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n					<td><label>NPO time (Hours) :</label> <v><%=render_value \'npotime\' %></v></td>\r\n					<td></td>\r\n				</tr>\r\n				<tr>\r\n					<td><label>Quality of Preparate :</label><v> <%=record[\'quality_of_preparate\']%></v></td>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \')%></v></td>\r\n				\r\n				</tr>		\r\n				\r\n			</table>	\r\n		\r\n		<div class=\"clear\"></div>\r\n		\r\n		\r\n</td>\r\n		    <td valign=\"top\" width=\"40%\"><h4 style=\"padding:0px; margin:0px; margin-left:10px; margin-bottom:5px\">Sedation</h4>\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% if record[\'dormicum\']==\'true\'%>\r\n<tr><td>Dormicum : <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'%>\r\n<tr><td>Pethidine : <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'%>\r\n<tr><td>Buscopan : <v><%=record[\'buscopan_mg\']%> mg <%=record[\'route_buscopan\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'%>\r\n<tr><td>Fentanyl : <v><%=record[\'mg_fentanyl\']%> mg <%=record[\'fentanyl_route\']%> </v> </td></tr>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'%>\r\n<tr><td>Diprivan : <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v></td></tr>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'%>\r\n<tr><td>Valium : <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v> </td></tr>\r\n<% end%>\r\n\r\n<% if record[\'plasil\']==\'true\'%>\r\n<tr><td>Plasil : <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v> </td></tr>\r\n<% end%>\r\n\r\n<% if record[\'other\']==\'true\'%>\r\n<tr><td>Other Note : <v><%=record[\'other_note\']%> </v> </td></tr>\r\n<% end%>\r\n</table></td>\r\n		</tr>\r\n\r\n</table>\r\n\r\n<hr />\r\n<h4>Scope finding</h4>\r\n&nbsp;&nbsp;<label>Scope pass through : </label><v><%=render_value \'scope\'%> <i></i></v>&nbsp;\r\n&nbsp;&nbsp;<label>Esophagitis LA Class : </label><v><%=render_value \'esophagitis_la_class\'%> <i></i></v>&nbsp;\r\n<label>Pocedure : </label><v><%=render_value \'procedure\'%> <i></i></v><br />\r\n<p>Start at : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<div class=\"clear\"></div>\r\n\r\n<table width=\"850\"><tr>\r\n<td><span class=\"\"><label>Z line at (cm.) : </label></span>	\r\n<v><%=render_value \'z_line\'%></v></td>\r\n<td><span class=\"\"><label>EGJ at (cm.) : </label></span>	\r\n<v><%=render_value \'egj_at\'%></v></td>\r\n<td><span class=\"\"><label>Sliding Hernia : </label></span>	\r\n<v><%=render_value \'sliding_hernia\'%></v></td>\r\n<td><span class=\"\"><label>Ampulla of Vater : </label></span>	\r\n<v><%=render_value \'ampulla_of_vater\'%></v></td>\r\n</tr>\r\n\r\n</table>\r\n\r\n<%\r\n    scopes_labels = {\'egj_scope\'=>\'EGJ\'}\r\n\r\n    scopes = %w{pharynx_scope esophagus_scope egj_scope fundus_scope cardia_scope body_scope antrum_scope first_duodenum_scope sphincter_of_oddi_scope second_duodenum_scope third_duodenum_scope forth_duodenum_scope proximal_jejunum_scope distal_jejunum_scope terminal_ileum_scope }\r\n\r\n    scopes.each_with_index do |j,index|\r\n    if index<record.scope.to_i \r\n    tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    \r\n    \r\n    \r\n    text = \"Normal\"\r\n    tag_cls = \'\'\r\n    if record[tag] == \'1\'\r\n    	text =  \"Abnormal\"\r\n    	 tag_cls = \'color:red\'\r\n    end\r\n    label = tag.humanize\r\n    label = scopes_labels[j] if scopes_labels[j]\r\n    \r\n%>\r\n<p><%= label %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Abnormal Type :</td><td>Endoscopy Dx :</td><td>Morphology Type :</td><td>Size (cm.) :</td><td>Treatment :</td><td>By :</td><td>Clip :</td><td>Patho No. :</td><td>Abnormal Note :</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n      size= \'-\'\r\n      size = i[\'size\'] if i[\'size\']!=0\r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'endoscopy_dx\']%></v></td><td><v><%=i[\'morphology_type\']%></v></td><td><v><%=size%></v></td><td><v><%=i[\'treatment\']%></v></td><td> <v><%=i[\'treatment_by\']%></v> </td><td><v><%=i[\'clip\']%></v></td><td><v><%=i[\'patho_number\']%></v></td><td><v><%=i[\'abnormal_note\']%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<hr />\r\n\r\n<h4>Note :</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \')%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n    <p>Note: <v><%=record[\'scope_note\']%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.image\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\" class=\"\">\r\n		<%= image_tag i.path+\"?thumb=2\",:style=>\'width:100%; display: block; margin: auto;\' %><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2017-03-25 14:27:20','2017-03-25 14:27:20','print_partial',''),(2986,'print_image',1189,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div style=\"page-break-after: always\">\r\n<%= render :inline=>this.print_partial, :locals=>{:this=>this} %>\r\n</div>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    gas_id = pm.module_id\r\n    record = models[:gastroscopy].find(gas_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px;padding-left:20px;padding-right:20px }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:200px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n\r\n.thumbnail {\r\n  position: relative;\r\n  width: 300x;\r\n  height: 300px;\r\n  overflow: hidden;\r\n}\r\n.thumbnail img {\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 50%;\r\n  height: 100%;\r\n  width: auto;\r\n  -webkit-transform: translate(-50%,-50%);\r\n      -ms-transform: translate(-50%,-50%);\r\n          transform: translate(-50%,-50%);\r\n}\r\n.thumbnail img.portrait {\r\n  width: 100%;\r\n  height: auto;\r\n}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<!--<div id=\"logoleft\"><img src=\'/esm/cusys/colorectal/login-logo2.png\' width=\"300\" /></div>-->\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' height=\'70px\' /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Enteroscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=record.date_note%></v>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n<hr />\r\n\r\n<table width=\"100%\" border=\"0\">\r\n  <tr>\r\n    <td valign=\"top\" width=\"50%\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p></td>\r\n    <td width=\"50%\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \')%></v></p>\r\n</td>\r\n  </tr>\r\n</table>\r\n\r\n\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n    <p>Note: <v><%=record[\'scope_note\']%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    <p>Remark : <v><%=record[\'remark\']%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n\r\n    <%\r\n        list = record.image\r\n        atts = []\r\n        if list[8...36]\r\n            atts = list[8...36].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        end\r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\" class=\"thumbnail\">\r\n		<%= image_tag i.path+\"?thumb=2\" %><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\" style=\"height:40px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<script>\r\nwindow.print()\r\n</script>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2017-03-25 14:27:44','2017-03-25 14:27:44','print_image',''),(2987,'document_name',1190,1,'\'patient\'',NULL,NULL,NULL,'2017-03-27 03:54:31','2017-03-27 03:54:31',NULL,NULL),(2988,'document_name',1191,1,'\'bronchoscopy\'',NULL,NULL,NULL,'2017-03-27 07:04:14','2017-03-27 07:04:14',NULL,NULL),(2989,'document_name',1192,1,'\'bronchoscopy_scope\'',NULL,NULL,NULL,'2017-03-27 07:04:48','2017-03-27 07:04:48',NULL,NULL),(2990,'get_patient_info',1190,3,'<%\r\n\r\n\r\n\r\ndef get_hn i\r\n\r\n  n = \'\'\r\n  y = \'\'\r\n  \r\n  return i if i.size<5 or i.size>9\r\n  if i.index \'/\'  \r\n    t = i.split(\"/\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.index \'-\'  \r\n    t = i.split(\"-\")\r\n    y = t[-1]\r\n    n = t[0]\r\n  elsif i.size==8\r\n    y = i[0..1].to_i\r\n    y2 = i[-2..-1].to_i\r\n    n = i[3..-1].to_i  \r\n    if y2 > y\r\n      y = y2\r\n      n = i[0..-3].to_i    \r\n    end\r\n  else\r\n    y = i[-2..-1]\r\n    n = i[0..-3]\r\n  end\r\n  \r\n  hn = \"\\\\#{n.to_i.to_s}/\\\\#{y}\"\r\n\r\n  return hn    \r\n\r\nend\r\n\r\n\r\nrequire \'uri\'\r\nrequire \'base64\'\r\n\r\nhis_ip = \"http://170.100.50.240:9292\"\r\nhis_ip = \"http://localhost:9292\"\r\nhis_ip =  get_setting \'his_host\'\r\n\r\nusername = \'jane\'\r\npassword = \'jane\'\r\nhn = 47700094.to_s\r\nusername = params[:un] if params[:un]\r\npassword = params[:ps] if params[:ps]\r\nhn = params[:hn] if params[:hn]\r\n\r\nif hn == \'-\'\r\n  session[:his]=nil\r\n  session[:last_his]=nil\r\n  session.delete \'his\'\r\n  msg=\'logout HIS\'\r\n%>\r\n<!--alert(\"<%=msg%>\");-->\r\nwindow.location.reload();\r\n<%\r\n  \r\nelse # reset login\r\n\r\nunless session[:his]  # if not login then login\r\n\r\n    login_url = his_ip+\'/his/login?username=\'+username+\'&password=\'+password+\'&hn=\'+hn\r\n    uri = URI.parse(login_url)\r\n    http = Net::HTTP.new(uri.host, uri.port); \r\n    http.open_timeout = 5; \r\n    http.read_timeout = 20;\r\n    result= http.get(uri.path+\"?\"+uri.query).body\r\n    if result != \'\'\r\n        object = ActiveSupport::JSON.decode result\r\n        session[:his] = \"\\\\#{username}\" \r\n        session[:last_his] = Time.now\r\n%>\r\n        <!--alert(\'<%=object[\'status\'] %>\')-->\r\n        $(\'#his-status\').text(\'Status <%= object[\'status\'] %>\');\r\n<%\r\n    end\r\n\r\nend  # end login\r\n\r\n# get patient info\r\n\r\ninfo_url = his_ip+\'/his/get_patient_info?username=\'+session[:his]+\'&hn=\'+hn\r\n\r\nuri = URI.parse(info_url)\r\nhttp = Net::HTTP.new(uri.host, uri.port); \r\nhttp.open_timeout = 3; \r\nhttp.read_timeout = 15;\r\n\r\nbegin\r\n\r\n    result= http.get(uri.path+\"?\"+uri.query).body\r\n\r\n    if result != \'\'\r\n        object = ActiveSupport::JSON.decode result\r\n        object[\'hn\']=params[:hn];\r\n        if object[\'picture\'] and object[\'s_hn\']\r\n            doc = Document.find(params[:doc_id])\r\n            ssid = Time.now.to_i.to_s+rand(100).to_s\r\n            @document = @current_project.get_document doc.name\r\n            atts =  @document.attach_field_image \'F6478524829\',\"\\\\#{object[\'hn\']}.png\",ssid,StringIO.new(Base64.decode64(object[\'picture\']))\r\n            if atts\r\n%>\r\n    $.ajax({\r\n            url: \'/esm_image/<%=params[:doc_id]%>/attach_to_gallery?p_id=<%=@current_project.id%>&field_id=F6478524829&ssid=<%=ssid%>&upload=true\',\r\n            data: [],\r\n        	dataType: \'script\',\r\n			type: \'GET\',\r\n			error: function (xhr, status, error) {\r\n			alert(error);\r\n			}\r\n	}).done(function(data){\r\n        alert(\"Picture Inserted\");\r\n    });\r\n<%\r\n            end\r\n        end\r\n    \r\n%>\r\nobject = <%=object.to_json.html_safe%>\r\n$(\"#data-hn\").val(object[\'hn\']);\r\n$(\"#data-public_id\").val(object[\'public_id\']);\r\n//alert(object[\'birth_date\']);\r\n$(\"#data-prefix_name\").val(object[\'prefix\']);\r\n$(\"#input-prefix_name\").val(object[\'prefix\']);\r\n$(\"#data-first_name\").val(object[\'first_name\']);\r\n$(\"#data-last_name\").val(object[\'last_name\']);\r\n$(\"#data-first_name_eng\").val(object[\'first_name\']);\r\n$(\"#data-last_name_eng\").val(object[\'last_name\']);\r\n$(\"#data-nationality\").val(object[\'nationality\']);\r\n\r\n$(\"#data-born_address\").val(object[\'born_address\']);\r\n$(\"#data-born_tambon\").val(object[\'born_tambon\']);\r\n$(\"#data-born_amphur\").val(object[\'born_amphur\']);\r\n$(\"#data-born_province\").val(object[\'born_province\']);\r\n$(\"#data-born_zipcode\").val(object[\'born_zipcode\']);\r\n$(\"#data-born_country\").val(object[\'born_country\']);\r\n\r\n$(\"#data-contact_address\").val(object[\'contact_address\']);\r\n$(\"#data-contact_tambon\").val(object[\'contact_tambon\']);\r\n$(\"#data-contact_amphur\").val(object[\'contact_amphur\']);\r\n$(\"#data-contact_province\").val(object[\'contact_province\']);\r\n$(\"#data-contact_zipcode\").val(object[\'contact_zipcode\']);\r\n$(\"#data-contact_country\").val(object[\'contact_country\']);\r\n\r\n$(\"#data-occupation\").val(object[\'occupation\']);\r\n$(\"#data-gender\").val(object[\'gender\']);\r\n$(\"#data-marital_status\").val(object[\'marital\']);\r\n\r\n$(\"#data-tel_home\").val(object[\'tel_home\']);\r\n//$(\"#data-tel_office\").val(object[\'lice_tel\']);\r\n$(\"#data-mobile\").val(object[\'mobile\']);\r\n$(\"#data-email\").val(object[\'email\']);\r\n\r\nvar bd = object[\'birth_date\'];\r\nbb = bd.split(\'/\');\r\nif (bb[0] == \"00\") {\r\n    bd = \"01/01/\" + bb[2];\r\n}\r\n\r\n$(\"#data-birth_date\").val(bd);\r\n$(\"#data-contact_name\").val(object[\'contact_name\']);\r\n$(\"#data-contact_tel\").val(object[\'contact_tel\']);\r\n$(\"#data-contact_desc\").val(object[\'contact_desc\']);\r\n\r\n\r\n    <% else %>\r\n        alert(\"Agent Error\");\r\n    <% end %>\r\n<% rescue  Exception=>e %>\r\nalert(\"Cannot connect Agent <%=e.message%>\");\r\n<% end %>\r\n<% end %>',NULL,NULL,NULL,'2017-03-29 03:26:50','2017-03-29 03:26:50','get_patient_info',''),(2991,'test',1185,3,'<%\r\n    cond = {}\r\n    today = Time.now\r\n            sdate = today.at_beginning_of_month\r\n            edate = today.end_of_month\r\n            cond[:admission_date] = {\'$gte\'=>sdate.beginning_of_year,\'$lt\'=>edate.end_of_day}\r\n            \r\n            sf = {:admission_date=>1, :ward=>1, :color=>1, :case_type=>1}\r\n            \r\n    # x = get_model[:gynecology].collection.find(cond, {:fields=>sf}).to_a\r\n    x = get_model[:gynecology].collection.find(cond, {:fields=>sf}).sort({:admission_date=>-1}).limit(1).to_a\r\n    \r\n%>\r\n<%= x.to_json.html_safe %>',NULL,NULL,NULL,'2017-04-04 04:42:56','2017-04-04 04:42:56','test',''),(2992,'export_rrt',909,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    is_oneline = false\r\n    if params[:cs] == \'one\'\r\n        is_oneline = true\r\n    end\r\n    \r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n\r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = [] # all parent_id\r\n    pat_ids = [] # all patient_id\r\n    app_par = {}\r\n    pat_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n        pat_par[i[:patient_id]] = i.id.to_s\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    # begin\r\n    # a_pat = a_pat.sort_by{|i| i[:patient_order] if i[:patient_order]}\r\n    a_pat = a_pat.sort{|a,b| a[:patient_order] && b[:patient_order] ? a[:patient_order] <=> b[:patient_order] : a[:patient_order] ? -1 : 1 }\r\n    \r\n    # query patient_module <-> aki\r\n    mod_aki = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#aki\")\r\n    i_aki = []\r\n    p_aki = {}\r\n    mod_aki.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_aki << mid\r\n        if !p_aki.has_key? pid\r\n            p_aki[pid] = []\r\n        end\r\n        p_aki[pid] << mid\r\n    end\r\n    m_aki = {}\r\n    a_aki = get_model[:aki].find(i_aki)\r\n    a_aki.each do |i|\r\n        m_aki[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> summary_form\r\n    mod_out = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#summary_form\")\r\n    i_out = []\r\n    p_out = {}\r\n    mod_out.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_out << mid\r\n        if !p_out.has_key? pid\r\n            p_out[pid] = []\r\n        end\r\n        p_out[pid] << mid\r\n    end\r\n    m_out = {}\r\n    a_out = get_model[:summary_form].find(i_out)\r\n    a_out.each do |i|\r\n        m_out[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> case_record\r\n    mod_case = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#case_record\")\r\n    i_case = []\r\n    p_case = {}\r\n    mod_case.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_case << mid\r\n        if !p_case.has_key? pid\r\n            p_case[pid] = []\r\n        end\r\n        p_case[pid] << mid\r\n    end\r\n    m_case = {}\r\n    a_case = get_model[:case_record].find(i_case)\r\n    a_case.each do |i|\r\n        m_case[i.id] = i\r\n    end\r\n    \r\n    \r\n    # processing\r\n    res = []\r\n    # pf = %w{patient_number	patient_order	recheck	reference	birth_date	gender	weight	height	ideal_body_weight	date_of_admission	date_of_icu_admission	time_of_icu_admission	reimbursement	diagnosis	ht	dm	cad	cerebrovascular_disease	malignancy	ckd	esrd	baseline_serum_creainine_by_mdrd	available_baseline	baseline_serum_cr	date_of_baseline_serum_cr	first_available_cr	first_available_cr_date	icu	glasgow_coma_score	temperature	mean_arterial	heart_rate	respiratory_rate	oxygenation	arterial_ph	serum_sodium	serum_potassium	serum_creatinine	hematocrit	white_blood_count	age	chronic_health_points	apache_ii}\r\n    pf = %w{patient_number	patient_order gender apache_ii glasgow_coma_score diagnosis	ht	dm	cad	cerebrovascular_disease	malignancy	ckd	esrd age baseline_serum_creainine_by_mdrd available_baseline baseline_serum_cr date_of_baseline_serum_cr first_available_cr_date date_of_admission	date_of_icu_admission}\r\n\r\n    dd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    # cf = %w{case_status bun  creatinine mechanical_ventilation vasopressor vasopressor_type dose_of_vasopressor rs coagulation cns liver renal cvs diuretic lactate sofa if_rrt}\r\n    cf = %w{record_day case_status move_out_time bun creatinine urine_output24hr intake output net_balance urine_output_cal mechanical_ventilation vasopressor vasopressor_type rate_of_vasopressor dose_of_vasopressor ml_of_vasopressor patient_weight cal_dose_vasopressor rs coagulation cns liver renal cvs diuretic lactate sofa if_rrt indication mode_of_rrt type_of_vascular_access site_of_vascular_access internal_jugular_lr bfr dfr dialyzer anticoagulant_ihd complication_ihd type_of_vascular_access_sled site_of_vascular_access_sled internal_jugular_lr_sled duration_sled bfr_sled dfr_sled dialyzer_sled anticoagulant_sled complication_sled type_of_vascular_access_crrt site_of_vascular_access_crrt internal_jugular_lr_crrt  crrt_bfr crrt_ufr rfr_crrt dfr_crrt effrent_fluid total_time_crrt delivered_lose machine_type mode anticoagulant_crrt crrt_complication type_of_catheter type_solution cycle fill_volume dwell_time pd_complication}\r\n\r\n    # of = %w{stop_rrt_date rrt_day  icu_discharge_status date_of_icu_discharge los_in_icu  hospital_discharge_status date_of_hospital_discharge los_in_hospital  death_date total_ventilator_day  crbsi vap}\r\n    of = %w{stop_rrt_date rrt_day  icu_discharge_status los_in_icu  hospital_discharge_status los_in_hospital  death_date total_ventilator_day  crbsi vap date_of_hospital_discharge}\r\n    af = %w{aki_max_staging aki_max_staging_from auto_max_staging cr_diagnosis cr_diagnosis_from_day cr_staging cr_staging_from_day urine_output_diagnosis urine_output_from_day urine_output_staging urine_output_staging_from_day cause_of_aki cause_other admin_cause_of_aki cause_other2 aki_type a_on_c}\r\n\r\n    dx_group = {}\r\n\r\n    # for each patient\r\n    a_pat.each do |pat|\r\n        tmp = {}\r\n        msg = []\r\n        # filter age < 18\r\n        if pat.nil? or pat[:age].to_i < 18\r\n            next\r\n        end\r\n        \r\n        pp = {}\r\n        pp[:site] = @current_solution.name\r\n        pf.each do |i|\r\n            pp[i.to_sym] = pat[i.to_sym]\r\n        end\r\n        \r\n        dx_str = pp[:diagnosis].clone.downcase\r\n        if dx_str.include? \' and \'\r\n            dx_str.gsub!(\' and \', \',\')\r\n        end\r\n        dx_str.split(\',\').collect do |i|\r\n            k = i.strip\r\n            v = pp[:patient_number]\r\n            if !dx_group.has_key? k\r\n                dx_group[k] = []\r\n            end\r\n            dx_group[k] << v\r\n        end\r\n        \r\n        \r\n        pp[:time_of_icu_admission] = pp[:time_of_icu_admission].nil? ? \'\' : pp[:time_of_icu_admission].strftime(\'%H:%M\')\r\n        \r\n        # recheck urine output from case_record\r\n        cid_list = []\r\n        if xx = p_case[pat.id]\r\n            xx.each do |i|\r\n                cid_list << m_case[i]\r\n            end\r\n        else\r\n            msg << \"xx found\"\r\n        end\r\n        \r\n        # mapping day <--> case_record\r\n        mc = {}\r\n        cid_list.each do |i|\r\n            rd = i[:record_day]\r\n            if rd==\'\'\r\n                msg << \'empty rd\'\r\n            end\r\n            if !mc.has_key? rd\r\n                mc[rd] = i\r\n            else\r\n                msg << \"dup rd[\\\\#{rd}]\"\r\n            end\r\n        end\r\n        \r\n        # checking aki is created ?\r\n        is_aki = false\r\n        aid_list = []\r\n        if xx = p_aki[pat.id]\r\n            xx.each do |i|\r\n                aid_list << m_aki[i]\r\n            end\r\n            is_aki = true\r\n        else\r\n            msg << \"NO AKI\"\r\n        end\r\n        \r\n        # assign aki\r\n        pp[:aki_auto_max_staging] = \'0\'\r\n        pp[:aki_auto_max_from] = \'-\'\r\n        r_aki = nil\r\n        if is_aki\r\n            r_aki = aid_list[0]\r\n            \r\n            # sum = 0\r\n            af.each do |i|\r\n                pp[i.to_sym] = r_aki[i.to_sym].nil? ? \'\' : r_aki[i.to_sym]\r\n                # sum += r_aki[i.to_sym].nil? ? 0 : r_aki[i.to_sym].to_i\r\n                # pp[i.to_sym] = r_aki\r\n            end\r\n            # if sum > 0\r\n            if pp[:auto_max_staging].to_i > 0\r\n                pp[:aki] = \'Yes\'\r\n                if pp[:cr_staging].to_i > pp[:urine_output_staging].to_i\r\n                    pp[:aki_auto_max_staging] = pp[:cr_staging]\r\n                    pp[:aki_auto_max_from] = \'Cr\'\r\n                elsif pp[:cr_staging].to_i < pp[:urine_output_staging].to_i\r\n                    pp[:aki_auto_max_staging] = pp[:urine_output_staging]\r\n                    pp[:aki_auto_max_from] = \'Urine\'\r\n                else\r\n                    pp[:aki_auto_max_staging] = pp[:urine_output_staging]\r\n                    pp[:aki_auto_max_from] = \'Both\'\r\n                end\r\n            else\r\n                pp[:aki] = \'No\'\r\n            end\r\n            \r\n            \r\n        else\r\n            pp[:aki] = \'None\'\r\n        end\r\n        \r\n        # checking summary_form is created ?\r\n        is_out = false\r\n        oid_list = []\r\n        if xx = p_out[pat.id]\r\n            xx.each do |i|\r\n                oid_list << m_out[i]\r\n            end\r\n            is_out = true\r\n            # pp[:outcome] = \'Yes\'\r\n        else\r\n            msg << \"NO OUTCOME\"\r\n            # pp[:outcome] = \'No\'\r\n        end\r\n        \r\n        # assign summary_form (outcome)\r\n        r_out = nil\r\n        if is_out\r\n            r_out = oid_list[0]\r\n            \r\n            of.each do |i|\r\n                pp[i.to_sym] = r_out[i.to_sym].nil? ? \'\' : r_out[i.to_sym]\r\n                # pp[i.to_sym] = m_out.to_json.html_safe \r\n            end\r\n            pp[:outcome] = \'Yes\'\r\n        else\r\n            pp[:outcome] = \'No\'\r\n        end\r\n        \r\n        \r\n        # number of record_day\r\n        nrd = cid_list.count\r\n        \r\n        pp[:has_rrt] = \'No\'\r\n        pp[:rrt_start_day] = \'\'\r\n        pp[:rrt_stop_day]  = \'\'\r\n        pp[:num_of_record_day] = nrd\r\n        if !mc.empty?\r\n            dd.each do |i|\r\n                if !mc[i].nil?\r\n                    tmp = {}\r\n                    cf.each do |j|\r\n                        if j.to_s == \'move_out_time\'\r\n                            if mc[i][:case_status].to_i != 0\r\n                                \r\n                                if is_oneline\r\n                                    # pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                    pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym].nil? ? \'xx:xx\' : mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                else\r\n                                    # pp[j.to_sym] = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                    pp[j.to_sym] = mc[i][j.to_sym].nil? ? \'xx:xx\' : mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                end\r\n                            end\r\n                        else\r\n                            \r\n                            if is_oneline\r\n                                pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym]\r\n                            else\r\n                                pp[j.to_sym] = mc[i][j.to_sym]\r\n                            end\r\n                            \r\n                            if mc[i][j.to_sym] == \'0\' and j.to_s == \'if_rrt\'\r\n                                pp[:has_rrt] = \'Yes\'\r\n                                if pp[:rrt_start_day] == \'\'\r\n                                    pp[:rrt_start_day] = i\r\n                                    pp[:rrt_stop_day] = i\r\n                                else\r\n                                    pp[:rrt_stop_day] = i\r\n                                end\r\n                            end\r\n                        end\r\n                    end\r\n                    if !is_oneline\r\n                        tmp = pp.clone\r\n                        res << tmp\r\n                    end\r\n                end\r\n            end # end dd\r\n            \r\n            \r\n        end\r\n        \r\n        \r\n        # pm_id = pat_par[pat.id]\r\n        # x_id = app_par[pm_id]\r\n        # pp[:detail] = link_to(\'detail\', \"../Home/patient_record?id=\\\\#{x_id}\", :target=>\'_blank\')\r\n        \r\n        if is_oneline\r\n            res << pp\r\n        end\r\n    end\r\n    \r\n    lbl = []\r\n    lbl << \'site\'\r\n    lbl = lbl + pf\r\n    lbl << \"num_of_record_day\"\r\n    lbl << \"has_rrt\"\r\n    lbl << \"rrt_start_day\"\r\n    lbl << \"rrt_stop_day\"\r\n    lbl << \'aki\'\r\n    lbl << \"aki_auto_max_staging\"\r\n    lbl << \"aki_auto_max_from\"\r\n    if params[:cs] == \'one\'\r\n        fx = cf\r\n        fx.each do |i|\r\n            dd.each do |j|\r\n                lbl << \"\\\\#{i}_\\\\#{j}\"\r\n            end\r\n        end\r\n    elsif params[:cs] == \'multi\'\r\n        lbl = lbl + cf\r\n    end\r\n    lbl = lbl + af\r\n    lbl << \'outcome\'\r\n    lbl = lbl + of\r\n        \r\n    \r\n    # result assign\r\n    display = \'table\'\r\n    if params[:type] == \'csv\'\r\n        display = \'csv\'\r\n    elsif params[:type] == \'xls\'\r\n        display = \'xls\'\r\n    elsif params[:type] == \'json\'\r\n        display = \'json\'\r\n    end\r\n    \r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    # rs[:app_par] = app_par\r\n    # rs[:mod_par] = mod_par\r\n\r\n    if display == \'json\'\r\n        rs[:all_patient] = a_pat.count\r\n        rs[:all_aki] = a_aki.count\r\n        rs[:all_result] = res.count\r\n        rs[:label] = lbl\r\n        rs[:result] = res\r\n        rs[:time] = Time.now - tb\r\n%>\r\n\r\n<%= rs.to_json.html_safe %>\r\n\r\n<%\r\n    elsif display == \'table\'\r\n        # ff = res[0].keys\r\n        ff = lbl.collect{|i| i.to_sym}\r\n%>\r\n\r\n<%= stylesheet_link_tag    \"application\"  %>\r\n<h3>Total Patient = <%= a_pat.count %></h3>\r\nquery time = <%= Time.now - tb %>\r\n\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n<% ff.each do |i| %>\r\n        <th><%= i %></th>\r\n<% end %>        \r\n    </tr>\r\n<% \r\n        res.each do |i| \r\n%>\r\n    <tr>\r\n<% \r\n            ff.each do |j| \r\n                val = i[j]\r\n%>\r\n       <td><%= val %></td>\r\n<% end %>\r\n    </tr>\r\n<% end %>\r\n</table>\r\n\r\n<br/>\r\nProcessing time = <%= Time.now - tb %><br/>\r\n\r\n<%\r\n    elsif display == \'csv\'\r\n        require \'csv\'\r\n        fname = \'Export\'\r\n        header = true\r\n        if params[:fname]\r\n            fname = params[:fname]\r\n        end\r\n        if params[:header]==\'false\'\r\n            header = false\r\n        end\r\n    \r\n        response.headers[\"Content-Type\"] = \"text/csv\"\r\n        response.headers[\"Content-disposition\"] = \"attachment; filename=\\\\#{params[:solution_name]}-\\\\#{fname}-\\\\#{Time.now.strftime(\'%y%m%d%H%M%S\')}.csv\"\r\n        \r\n        # ff = res[0].keys\r\n        ff = lbl.collect{|i| i.to_sym}\r\n        \r\n        xxx = CSV.generate do |csv|\r\n            if header\r\n                csv << ff # header\r\n            end\r\n            res.each do |i|\r\n                tmp = []\r\n                ff.each do |j|\r\n                    tmp << \"\\\\#{i[j].to_s}\"\r\n                end\r\n                \r\n                csv << tmp\r\n            end\r\n        end\r\n%>\r\n<%= xxx.html_safe %>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2017-04-05 02:58:55','2017-04-05 02:58:55','export_rrt','*'),(2993,'link_export_rrt',909,3,'<%\r\n    # README here to clean data\r\n    # 1. make \'reference\' field by run service \'patient\'\r\n    #\r\n    # 2. run service \'aki\' to update aki document\r\n    #\r\n    # 3. run this service for  export all data\r\n    # \r\n    # rid = %w{1	2	3	4	5	6	7	9	11	12	13	14	15	16	17	19	21	23}\r\n    # THAI\r\n    rid = %w{1	2	3	4	5	6	7	9	11	12	13	14	15	16	17	21	23}\r\n    # LAOS + PHILIPPINS\r\n    # rid = %w{8 19 24 25 26 27}\r\n    idx = 1\r\n    rid.each do |i|\r\n        type = \'csv\'\r\n        if params[:type]\r\n            type = params[:type]\r\n        end\r\n        \r\n%>\r\n<h3><%= idx %>. RRTS_<%= i %></h3>\r\n<ul>\r\n    <!--<li><a href=\'https://emr-life.com/rrts_<%=i%>/www/Patient/reorder\' target=\'_blank\'>Reorder Patient</a><br/></li>-->\r\n    <li><a href=\'https://emr-life.com/rrts_<%=i%>/rrts/Zam/export_rrt?type=<%= type %>&cs=one&fname=rrt_data\' target=\'_blank\'>All Data with all Case_Record in one line</a><br/></li>\r\n    <!--<li><a href=\'https://emr-life.com/rrts_<%=i%>/rrts/Zam/export?type=<%= type %>&cs=multi&fname=all_data_2\' target=\'_blank\'>All Data with all Case_Record in multi line</a><br/></li>-->\r\n    <!--<li><a href=\'https://emr-life.com/rrts_<%=i%>/rrts/Zam/export_cs?type=csv&fname=all_case_record_per_line\' target=\'_blank\'>All Case_Record on record per line</a><br/></li>-->\r\n    <!--<li><a href=\'https://emr-life.com/rrts_<%=i%>/rrts/Zam/export_cs?type=csv&cs=all&fname=one_case_record_per_line\' target=\'_blank\'>All Case_Record in one line per record</a><br/></li>-->\r\n</ul>\r\n<%\r\n        idx += 1\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2017-04-06 11:41:23','2017-04-06 11:41:23','link_export_rrt',''),(2994,'batch_user_provider',262,2,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @ehr_models = ehr.get_model\r\n    \r\n    role_map = {}\r\n    m_role = @ehr_models[:role].all\r\n    m_role.each do |i|\r\n        rn = i[:name].downcase\r\n        role_map[rn] = i\r\n    end\r\n    \r\n    m_prov = get_model[:provider]\r\n    \r\n    res = []\r\n    fields = %w{prefix	first_name	last_name	login	password	provider_type	role    email}\r\n    if request.post?\r\n        if b = params[:batch]\r\n            f = b[:file]\r\n            \r\n            require \'csv\'\r\n            \r\n            csv = CSV.parse(f.read, :headers => true, :encoding=> \"iso-8859-1:utf-8\", :col_sep=>\'\\t\')\r\n            \r\n            csv.each do |i|\r\n                \r\n                pn = i[\'prefix\']\r\n                fn = i[\'first_name\']\r\n                ln = i[\'last_name\']\r\n                pt = i[\'provider_type\']\r\n                login  = i[\'login\']\r\n                passwd = i[\'password\']\r\n                email  = i[\'email\']\r\n                \r\n                fname  = \"\\\\#{pn}\\\\#{fn} \\\\#{ln}\"\r\n                \r\n                role   = i[\'role\'].nil? ? \'user\' : i[\'role\'].downcase\r\n                rid    = role_map[role]\r\n                if rid.nil?\r\n                    n_role = @ehr_models[:role].create(:name=>role)\r\n                    role_map[role] = n_role\r\n                    rid = n_role.id\r\n                else\r\n                    rid = rid.id\r\n                end\r\n                \r\n                usr = @ehr_models[:user].where(:login=>login).first\r\n                prv = get_model[:provider].where(:name=>fname).first\r\n                \r\n                if usr.nil? and prv.nil?\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(passwd, salt)\r\n                    tmp = salt + \'...\' + hashed_password\r\n                    n_user = @ehr_models[:user].create :role=>rid, :login=>login, :salt=>salt, :hashed_password=>hashed_password, :email=>email, :name=>fname, :activate=>\"true\"\r\n                    \r\n                    n_prov = get_model[:provider].create :name=>fname, :login=>login, :prefix=>pn, :first_name=>fn, :last_name=>ln, :provider_type=>pt\r\n                    res << {:msg=>login, :res=>\'success\'}\r\n                else\r\n                    res << {:msg=>login, :res=>\"ERR USER:\\\\#{usr}, PROV:\\\\#{prv}\"}\r\n                end\r\n                \r\n            end # end csv\r\n            # res << \'xxx \'\r\n        end # end batch\r\n    end # end post\r\n%>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting > Batch User - Provider</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n\r\n\r\n<%= form_for :batch, :url=>params[:opt], :html=>{:multipart=>true}  do |f| %>\r\n                <%= f.file_field :file, :accept => \"text/csv\" %> \r\n                <div class=\'row-fluid\'></div>\r\n                <%=f.submit \'Submit\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %> \r\n<% end %>\r\n\r\n<div class=\'alert alert-info\'>\r\n<% if res.empty? %>\r\n<b>Header</b> : <%= fields.to_json.html_safe %><br/>\r\n<% else %>\r\n    <%= res.to_json.html_safe %> | <%= res.size %>\r\n<% end %>\r\n<%= role_map.to_json.html_safe %>        \r\n</div>\r\n\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>',NULL,NULL,NULL,'2017-04-07 03:03:12','2017-04-07 03:03:12','batch_user_provider',''),(2995,'diag_group',477,2,'<%\r\n    if request.post?\r\n        if dx = params[:dx]\r\n            pat = get_model[:patient].find(dx[:pat])\r\n            if !pat.nil?\r\n                pat.each do |pp|\r\n                    dxg = dx[:diagnosis_group]\r\n                    if !pp[:diagnosis_group].nil? and pp[:diagnosis_group] != \'\'\r\n                        dxg = \"\\\\#{pp[:diagnosis_group]}, \\\\#{dxg}\"\r\n                    end\r\n                    if params[:commit] == \'Clear\'\r\n                        dxg = \'\'\r\n                    end\r\n                    pp.update_attributes :diagnosis_group=>dxg\r\n                end\r\n            end\r\n        end\r\n    end\r\n    \r\n    res = get_model[:patient].all.sort_by{|i| [i[:diagnosis].strip.downcase, i[:diagnosis_group].nil? ? \'\' : i[:diagnosis_group]]}\r\n    \r\n    mod = %w{check patient_order patient_number diagnosis diagnosis_group action}\r\n%>\r\n<%= form_for :dx do |f| %>\r\n\r\nDiagnosis group : <%= f.text_field :diagnosis_group, :style=>\'margin-top:10px\' %>\r\n                <%= f.submit \'Submit\', :class=>\'btn btn-success\' %> <%= f.submit \'Clear\', :class=>\'btn btn-danger\' %>\r\n                \r\n                <%= link_to \'Export\', \'export?type=csv\', :class=>\'btn btn-info\', :style=>\'float:right;margin-top: 10px;margin-right: 15px;\' %>\r\n\r\n<hr/>\r\n\r\n<style>\r\n .divWithScroll{\r\n    height:600px;\r\n    overflow:scroll;\r\n    overflow-x:hidden;\r\n}\r\n</style>     \r\nTotal Patients : <%= res.count %>\r\n<br/><br/>\r\n<div class=\'divWithScroll\'>\r\n<table class=\'table table-striped table-bordered table-condensed\' >\r\n    <thead>\r\n        <tr>\r\n        <th>&nbsp;</th>\r\n        <th>Patient order</th>\r\n        <th>Patient number</th>\r\n        <th>Diagnosis (at ICU)</th>\r\n        <th>Diagnosis group</th>\r\n        <th>Action</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n<%\r\n    res.each do |i|\r\n%>\r\n        <tr>\r\n            <td><%= f.check_box :pat, {:multiple=>true}, \"\\\\#{i.id.to_s}\", nil %></td>\r\n            <td><%= i[:patient_order] %></td>\r\n            <td><%= i[:patient_number] %></td>\r\n            <td><%= i[:diagnosis] %></td>\r\n            <td><%= i[:diagnosis_group] %></td>\r\n            <td><%= link_to \'Detail\', \"edit?id=\\\\#{i.id}&return=diag_group\", :class=>\'btn btn-info\' %></td>\r\n        </tr>\r\n<% end %>\r\n    </tbody>\r\n</table>\r\n<% end %>\r\n</div>\r\n\r\n<hr/>\r\n\r\n\r\n\r\n<% if false %>\r\n<%= tabular :model=>mod,:data=>res do |row,out|\r\n    \r\n              \r\n       out[0] = \"\\\\#{\'<u>\' if row[:recheck] and row[:recheck]!=\'\' and row[:recheck]!=\'false\' }\\\\#{row[:patient_order]} \\\\#{\'</u>\' if row[:recheck] and row[:recheck]!=\'\' and row[:recheck]!=\'false\'} \"\r\n\r\n       out\r\n       \r\n       end%>\r\n<% end %>',NULL,NULL,NULL,'2017-04-16 08:23:59','2017-04-16 08:23:59','diag_group',''),(2998,'document_name',1194,1,'\'operation\'',NULL,NULL,NULL,'2017-04-17 06:27:34','2017-04-17 06:27:34',NULL,NULL),(2999,'admit_search',1185,2,'<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n		width:100px\r\n    }\r\n    \r\n<%\r\n    malignant_list = %w{C541 C542 C548 C530 C531 C538 C56 C796 C570 C52 C510 C511 C512 C518 C482 C786 D392 C58 C578 C80 C509 C189}\r\n    malignant_list.each do |i|\r\n%>\r\n.<%= i %> { background:lightsalmon; }\r\n<% end %>\r\n</style>\r\n<%\r\n    report = [\r\n            [\'Admission\', \'admission\'],\r\n            [\'Ward\', \'ward\'],\r\n            [\'Line / Color\', \'color\'],\r\n            [\'Case type (Ward/Private)\', \'case_type\']\r\n        ]\r\n    service = [\r\n            [\'Gynecology\', \'gynecology\'],\r\n            [\'Obstetrics\', \'obstetrics\']\r\n        ]\r\n%>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box-header\">\r\n			<h3>Search</h3>\r\n		</div>\r\n        <div class=\"w-box-content cnt_a\">\r\n<%= form_for :search,:url=>\'admit_search_partial?update=result-panel\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n	    <span class=\"span4\"> \r\n			<label class=\"field-label\">Start Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :sdate, :value=>\'\',:id=>\'sdate\',:style=>\"width:100%\"%></div>\r\n		</span> \r\n		<span class=\"span4\"> \r\n			<label class=\"field-label\">End Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :edate, :value=>\'\',:id=>\'edate\',:style=>\"width:100%\"%></div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n		<span class=\'span4\' style=\'width:400px\'>\r\n		    <label class=\'field-label\'style=\'width:100px\'>Report Output : </label>\r\n		    <div class=\'field-input\' style=\'width:250px\'><%= f.select :report, report, include_blank: false, :style=>\'margin-top:10px\' %></div>\r\n		</span>\r\n		<span class=\'span4\' style=\'width:300px\'>\r\n		    <label class=\'field-label\'style=\'width:100px\'>Select Form : </label>\r\n		    <div class=\'field-input\' style=\'width:150px\'><%= f.select :service, service, include_blank: false, :style=>\'margin-top:10px\' %></div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n		<span class=\"field-data\">\r\n		    <div class=\"field-input\"><%=f.submit \'Submit\', :class=>\'btn btn-success\'%> </div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n<script>\r\n    $(\"#sdate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n    $(\"#edate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n</script>\r\n<% end %>\r\n\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class=\'clear\'></div>\r\n<br/>\r\n<div id=\'result-panel\'></div>\r\n',NULL,NULL,NULL,'2017-04-17 07:21:48','2017-04-17 07:21:48','admit_search',''),(3000,'admit_search_partial',1185,3,'<%= render :inline=>this.common_function %>\r\n<%\r\n    tb = Time.now\r\n    res  = {}\r\n    obj  = {}\r\n    cond = {}\r\n    \r\n    sv = \'obstetrics\'\r\n    \r\n    \r\n    \r\n    report = \'\'\r\n    if q = params[:search]\r\n        q[:sdate] = Time.strptime(q[:sdate], \"%d/%m/%Y\")\r\n        q[:edate] = Time.strptime(q[:edate], \"%d/%m/%Y\")\r\n        \r\n        # code = q[:code].upcase\r\n        # qq   = Regexp.new(Regexp.escape(q[:code]), \"i\")\r\n        # code_list = code.split(/[\\s,]/)\r\n        \r\n        report = q[:report]\r\n        \r\n        # cond[:created_at] = {\'$gte\'=>q[:sdate].beginning_of_day,\'$lt\'=>q[:edate].end_of_day}\r\n        cond[:admission_date] = {\'$gte\'=>q[:sdate].beginning_of_day,\'$lt\'=>q[:edate].end_of_day}\r\n        sf = {:admission_date=>1, :discharge_date=>1}\r\n        sv = q[:service]\r\n        rm = {}\r\n        rg = {}\r\n        km = {}\r\n        lb = []\r\n        fg = \'admission_date\'\r\n        \r\n        df = get_document_field(sv)\r\n        \r\n        if report == \'admission\'\r\n            ra = document_query(cond, sf, sv)\r\n            \r\n            rs = ra.group_by{|i| i[\'admission_date\'].nil? ? \'00/0000\' : i[\'admission_date\'].strftime(\'%m/%Y\')}\r\n            \r\n            km = {\'admission_date\'=>\'Admission\'}\r\n            lb = [\'admission_date\']\r\n        elsif report == \'ward\'\r\n            fg = report\r\n            sf[fg] = 1\r\n            ra = document_query(cond, sf, sv)\r\n            rs = ra.group_by{|i| i[\'admission_date\'].nil? ? \'00/0000\' : i[\'admission_date\'].strftime(\'%m/%Y\')}\r\n            rg = ra.group_by{|i| i[fg]}\r\n            \r\n            lb = rg.keys.sort\r\n            lb.each do |i|\r\n                km[i] = i\r\n            end\r\n        elsif report == \'color\'\r\n            fg = report\r\n            if sv == \'gynecology\'\r\n                fg = \'line\'\r\n            end\r\n            \r\n            sf[fg] = 1\r\n            \r\n            ra = document_query(cond, sf, sv)\r\n            rs = ra.group_by{|i| i[\'admission_date\'].nil? ? \'00/0000\' : i[\'admission_date\'].strftime(\'%m/%Y\')}\r\n            rg = ra.group_by{|i| i[fg]}\r\n            \r\n            lb = rg.keys.sort\r\n            lb.each do |i|\r\n                km[i] = get_value(fg, df, i)\r\n            end\r\n        elsif report == \'case_type\'\r\n            fg = report\r\n            \r\n            sf[fg] = 1\r\n            \r\n            ra = document_query(cond, sf, sv)\r\n            rs = ra.group_by{|i| i[\'admission_date\'].nil? ? \'00/0000\' : i[\'admission_date\'].strftime(\'%m/%Y\')}\r\n            rg = ra.group_by{|i| i[fg]}\r\n            \r\n            lb = rg.keys.sort\r\n            lb.each do |i|\r\n                km[i] = get_value(fg, df, i)\r\n            end\r\n        end\r\n        \r\n        res[:res] = rs\r\n        res[:lbl] = lb\r\n        res[:km]  = km\r\n        res[:fg]  = fg\r\n    end\r\n    # bowel_preperation_finding\r\n    \r\n    lbl = []\r\n    \r\n%>\r\n<style>\r\n    .XXXX {\r\n        color:red;\r\n        \r\n    }\r\n</style>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\'>\r\n        \r\n    \r\n<div class=\'span8\'>						\r\n						\r\n    <table id=\'search-result\' class=\"table table-bordered\" style=\'width:100%\'>\r\n        <thead>\r\n            <tr>\r\n                <th>Month/Year</th>\r\n<%\r\n    res[:lbl].each do |i|\r\n        h = res[:km][i]\r\n        if h.nil? or h == \'\'\r\n            h = \'-\'\r\n        end\r\n%>\r\n                <th><%= h %></th>\r\n<% end %>\r\n                <th>Total</th>\r\n                <!--<th>Action</th>-->\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n<%\r\n    sum = {}\r\n    res[:res].each do |k, v|\r\n        if res[:lbl].count == 1\r\n            z = v.count\r\n            if !sum.has_key? res[:lbl][0]\r\n                sum[res[:lbl][0]] = 0\r\n            end\r\n            sum[res[:lbl][0]] += z\r\n%>\r\n            <tr>\r\n                <td><%= k %></td>\r\n                <td><%= v.count %></td>\r\n                <td><%= z %></td>\r\n                <!--<td><%= link_to \'Detail\', \'#\', :class=>\'btn btn-mini btn-gebo\' %></td>-->\r\n            </tr>\r\n<%\r\n        else \r\n            x = v.group_by{|i| i[res[:fg]]}\r\n%>\r\n            <tr>\r\n                <td><%= k %></td>\r\n<%\r\n            s = 0\r\n            res[:lbl].each do |i|\r\n                z = 0\r\n                a = x[i]\r\n                if !a.nil?\r\n                    z = a.count\r\n                end\r\n                if !sum.has_key? i\r\n                    sum[i] = 0\r\n                end\r\n                sum[i] += z\r\n                s += z\r\n%>\r\n                <td><%= z %></td>\r\n<% \r\n            end \r\n%>\r\n                <td><%= s %></td>\r\n                <!--<td><%= link_to \'Detail\', \'#\', :class=>\'btn btn-mini btn-gebo\' %></td>-->\r\n            </tr>\r\n<% \r\n        end \r\n    end\r\n%>\r\n            <tr>\r\n                <th>Sum</th>\r\n<%\r\n    s = 0\r\n    res[:lbl].each do |i|\r\n        s += sum[i]\r\n%>\r\n                <th><%= sum[i] %></th>\r\n<%  end %>\r\n                <th><%= s %></th>\r\n                <!--<th> </th>-->\r\n            </tr>\r\n        </tbody>\r\n    </table>\r\n\r\n    <div class=\'alert alert-info\'>\r\n        <b>Total patients </b>= <span id=\'total-pat\'></span>\r\n    </div>\r\n    \r\n</div>\r\n\r\n<div id=\'patient-result\' class=\'span4\'>\r\n\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    m_pat = model[:patient]\r\n    m_pat_mod = model[:patient_module]\r\n\r\n    sum_pat = 0\r\n    pat_list  = []\r\n    pat_group = {}\r\n    res[:res].each do |k,v|\r\n        grp = k.split(\'/\').join(\'-\')\r\n        x = 0\r\n        \r\n        vid   = v.collect{|i| i[\'_id\']}\r\n        g_res = v.group_by{|i| i[\'_id\']}\r\n        \r\n        tmp = m_pat_mod.where(:module_id=>vid).all\r\n        g_tmp = tmp.group_by{|i| i[:patient_id]}\r\n        \r\n        pid = tmp.collect{|i| i[:patient_id]}\r\n        pat = m_pat.collection.find({\'_id\'=>{\'$in\'=>pid}},{:fields=>{\'hn\'=>1, \'prefix_name\'=>1,\'first_name\'=>1,\'last_name\'=>1}}).to_a\r\n        sum_pat += pat.count\r\n        pat_list += pid\r\n        \r\n        g_pat = pat.group_by{|i| i[\'_id\']}\r\n%>\r\n    <div id=\"group_<%= grp %>\" class=\"accordion\">\r\n		<div class=\"accordion-group\">\r\n			<div class=\"accordion-heading\">\r\n				<a href=\"#result_<%= grp %>\" data-parent=\"#group_<%= grp %>\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n					<b><%= k.to_s.humanize %> - Total : <%= pat.count %> patients</b>\r\n				</a>\r\n			</div>\r\n			<div class=\"accordion-body collapse \" id=\"result_<%= grp %>\">\r\n				<div class=\"accordion-inner\">\r\n				    <%# v.to_json.html_safe %>\r\n                    <table class=\"table table-bordered\" style=\'width:100%\' id=\'pat-result\'>\r\n                        <thead>\r\n                            <tr>\r\n                                <th>No.</th>\r\n                                <th>HN</th>\r\n                                <th>Name</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n<%\r\n        if res[:lbl].count == 1\r\n            n = 0\r\n            \r\n            pat.each do |i|\r\n                pp = g_pat[i[:patient_id]].nil? ? {} : g_pat[i[:patient_id]][0]\r\n                pn = \"\\\\#{i[\'prefix_name\']}\\\\#{i[\'first_name\']} \\\\#{i[\'last_name\']}\"\r\n                \r\n                pid = i[\'_id\']\r\n                # md = i[:module_name].split(\'#\')[1].humanize\r\n                n += 1\r\n                ln = []\r\n                \r\n                g_tmp[pid].each do |j|\r\n                    pm = j\r\n                    fm = pm[:module_id]\r\n                    md = pm[:module_name].split(\'#\')[1].humanize\r\n                    rf = g_res[fm][0]\r\n                    \r\n                            ad = rf[\'admission_date\'].strftime(\'1%d%m\').to_i\r\n                            cc = pm[:created_at].strftime(\'1%d%m\').to_i\r\n                            cs = \'btn btn-mini btn-gebo\'\r\n                            if cc <= ad\r\n                                cs = \'btn btn-mini btn-warning\'\r\n                            end\r\n                            if rf[\'admission_date\'] > rf[\'discharge_date\']\r\n                                cs = \'btn btn-mini btn-danger\'\r\n                            end\r\n                            \r\n                    ln << link_to(rf[\'admission_date\'].strftime(\'%d/%m/%Y\'), \"../\\\\#{md}/show?id=\\\\#{pm.id}&return=../Home/index\", :target=>\'_blank\', :class=>cs)\r\n                end\r\n                \r\n                link = ln.join(\'&nbsp;\').html_safe\r\n%>\r\n                            <tr>\r\n                                <td><%= n %>.</td>\r\n                                <td>\r\n                                    <%= i[\'hn\'] %><br/>\r\n                                    <%= link_to \'Details\', \"../Home/index?search[hn]=\\\\#{i[\'hn\']}\", :class=>\'btn btn-mini btn-info\', :target=>\'_blank\' %>    \r\n                                </td>\r\n                                <td>\r\n                                    <%= pn %><br/>\r\n                                    <%= link %>        \r\n                                </td>\r\n                            </tr>\r\n<%  \r\n            end\r\n        else\r\n            # pat_list = []\r\n            g_frm = tmp.group_by{|i| i[:module_id]}\r\n            \r\n            x = v.group_by{|i| i[res[:fg]]}\r\n            lbl = res[:lbl]\r\n            lbl.each do |lb|\r\n                if !pat_group.has_key? lb\r\n                    pat_group[lb] = []\r\n                end\r\n                \r\n                z = 0\r\n                a = x[lb]\r\n                c = \"D_\\\\#{lb.hash}_\\\\#{grp}\"\r\n                # t = \"P_\\\\#{lb.hash}_\\\\#{grp}\"\r\n                if !a.nil?\r\n                    z = a.count\r\n                    n = 0\r\n                    pat = get_patient_by_document_result(a)\r\n%>\r\n                            <tr>\r\n                                <td colspan=\'2\' class=\'alert\' style=\'text-align:center\'><b><%= res[:km][lb] %> : <%= pat.count %> patients</b></td>\r\n                                <td class=\'alert\' style=\'vertical-align:middle;text-align:center\' ><%= link_to \'detail\', \"javascript:detail(\'\\\\#{c}\')\", :class=>\'btn btn-mini btn-info\' %></td>\r\n                            </tr>\r\n<% \r\n                    pat.each do |k,v|\r\n                        i = v[0]\r\n                        pat_list << i[\'_id\']\r\n                        pat_group[lb] << i[\'_id\']\r\n                        # pm = g_frm[i[\'_id\']][0]\r\n                        \r\n                        pn = \"\\\\#{i[\'prefix_name\']}\\\\#{i[\'first_name\']} \\\\#{i[\'last_name\']}\"\r\n                        \r\n                        pid = i[\'_id\']\r\n                        # md = i[:module_name].split(\'#\')[1].humanize\r\n                        n += 1\r\n                        ln = []\r\n                        \r\n                        g_tmp[pid].each do |j|\r\n                            pm = j\r\n                            fm = pm[:module_id]\r\n                            md = pm[:module_name].split(\'#\')[1].humanize\r\n                            rf = g_res[fm][0]\r\n                            \r\n                            ad = rf[\'admission_date\'].strftime(\'1%d%m\').to_i\r\n                            cc = pm[:created_at].strftime(\'1%d%m\').to_i\r\n                            cs = \'btn btn-mini btn-gebo\'\r\n                            if cc <= ad\r\n                                cs = \'btn btn-mini btn-warning\'\r\n                            end\r\n                            if rf[\'admission_date\'] > rf[\'discharge_date\']\r\n                                cs = \'btn btn-mini btn-danger\'\r\n                            end\r\n\r\n                            \r\n                            ln << link_to(\"\\\\#{rf[\'admission_date\'].strftime(\'%d/%m/%Y\')}\".html_safe, \"../\\\\#{md}/show?id=\\\\#{pm.id}&return=../Home/index\", :target=>\'_blank\', :class=>cs)\r\n                        end\r\n                        \r\n                        link = ln.join(\'&nbsp;\').html_safe\r\n                        \r\n%>\r\n                            <tr class=\'<%= c %>\' style=\'display:none\'>\r\n                                <td><%= n %>.</td>\r\n                                <td>\r\n                                    <%= i[\'hn\'] %>\r\n                                    <br/>\r\n                                    <%= link_to \'Details\', \"../Home/index?search[hn]=\\\\#{i[\'hn\']}\", :class=>\'btn btn-mini btn-info\', :target=>\'_blank\' %>\r\n                                </td>\r\n                                <td><%= pn %><br/><%= link %></td>\r\n                            </tr>\r\n<%\r\n                    end\r\n                end\r\n            end\r\n        end\r\n%>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    \r\n<% end %>\r\n\r\n    <div class=\'clear\'/>\r\n    <div class=\'alert\'>\r\n        <b>Count Patients </b>= <%= pat_list.uniq.count %> / <%= sum_pat %>\r\n    </div>\r\n</div>\r\n\r\n\r\n<%\r\n    txt_result = pat_list.uniq.count\r\n    if !pat_group.empty?\r\n        tmp = []\r\n        pat_group.each do |k, v|\r\n            h = res[:km][k]\r\n            if h.nil? or h == \'\'\r\n                h = \'-\'\r\n            end\r\n            txt = \"\\\\#{h} (\\\\#{v.uniq.count})\"\r\n            tmp << txt\r\n        end\r\n        \r\n        txt_result = \"\\\\#{tmp.join(\' / \')} / Total (\\\\#{txt_result})\"\r\n    end\r\n%>\r\n<script>\r\n    $(\'#total-pat\').text(\'<%= txt_result %>\');\r\n\r\n    function show(x) {\r\n        a = $(\'.\' + x).css(\'display\');\r\n        if (a != \'none\') {\r\n            $(\'.\' + x).hide();\r\n            $(\'#btn-\' + x).text(\"Show\");\r\n        } else {\r\n            $(\'.\' + x).show();\r\n            $(\'#btn-\' + x).text(\"Hide\");\r\n        }\r\n        console.log(a);\r\n    }\r\n\r\n    function detail(x) {\r\n        n = x;\r\n        a = $(\'.\' + n).css(\'display\');\r\n        if (a != \'none\') {\r\n            $(\'.\' + n).hide();\r\n            // $(\'#btn-\' + x).text(\"Show\");\r\n        } else {\r\n            $(\'.\' + n).show();\r\n            // $(\'#btn-\' + x).text(\"Hide\");\r\n        }\r\n        console.log(a);\r\n    }\r\n</script>\r\n\r\n<div class=\'clear\'></div>\r\n\r\n<br/>\r\n<% if @current_role==\'developer\' %>\r\n<%# params.to_json.html_safe %><br/><br/>\r\n<%# qq %>\r\n<% end %>\r\n<hr/>\r\n\r\nProcessing time : <%= Time.now - tb %>. <%= Time.now %>\r\n\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-04-17 07:24:40','2017-04-17 07:24:40','admit_search_partial',''),(3001,'patient_record',1064,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\n	body { min-width:0px; }\r\n	.gebo-fixed { background-color:#f5f5f5; }\r\n	#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Patient Records\r\n				<div class=\"pull-right\">\r\n					<%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n				</div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<%\r\n					ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n					ehr_models = ehr.get_model\r\n					patient_model = ehr_models[:patient]\r\n					patient_module_model = ehr_models[:patient_module]\r\n					\r\n					emr_models = get_model\r\n					ap = emr_models[:appointment].find(params[:id])\r\n					pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n					locker_model = emr_models[:locker]\r\n					if params[:reset_lock]\r\n					    l = locker_model.find(params[:reset_lock])\r\n					    l.destroy if l\r\n					end\r\n					#locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n					#i.destroy if i\r\n					#end\r\n					 \r\n					\r\n					\r\n					if pm\r\n					\r\n					if  params[:schema_patient_module]\r\n					   pm.update_attributes params[:schema_patient_module]\r\n					end\r\n					\r\n					if params[:provider_id]\r\n					  ap.update_attributes :provider=>params[:provider_id]\r\n					   ap = emr_models[:appointment].find(params[:id])\r\n					 end\r\n					\r\n					# find provider\r\n					provider = emr_models[:provider].find(ap.provider.to_s)\r\n					\r\n					# find patient\r\n					patient = patient_model.find(pm.patient_id)\r\n					\r\n					params[:patient]=patient\r\n					params[:patient_module]=pm\r\n					\r\n					# s = Service.get(\'ehr.emr.EmrHelper\')\r\n					#    obj = s.load context\r\n					\r\n					providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n					\r\n					%>\r\n				<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\'}.compact %>\r\n				<div style=\"border:0px solid\">\r\n					<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n						<%# render :inline=>obj.show_patient %>\r\n						<div id=\"patient\">\r\n							...\r\n						</div>\r\n						<script>\r\n							<%\r\n								url = \'../../www/Patient/search_result?\'\r\n								url += \'&id=\'+patient.id.to_s\r\n								%>      \r\n							        $.ajax({\r\n							    	  url: \'<%=url.html_safe%>\',\r\n									 success: function(data){\r\n							          $(\'#patient\').html(data);  \r\n									  }\r\n									});\r\n						</script>\r\n						<% \r\n							test = false\r\n							if @current_role == \'developer\' and test \r\n							%>\r\n						<pre>\r\n    Appointment : <%= ap.to_json.html_safe %><br/>\r\n</pre>\r\n						<pre>\r\n    PatientModule : <%= pm.to_json.html_safe %>\r\n</pre>\r\n						<% if params[:remove] == \'true\'\r\n							ap.destroy\r\n							pm.destroy\r\n							%>\r\n						<script>\r\n							window.location = \"index\"\r\n						</script>\r\n						<% end %>\r\n						<% \r\n							if params[:update] == \'true\' \r\n							    sname = @current_project.name + \"#\" + params[:sname]\r\n							    app_id = params[:app_id]\r\n							    \r\n							    t_ap = emr_models[:appointment].find(app_id)\r\n							    t_pm = patient_module_model.first(:module_id=>t_ap.id.to_s)\r\n							    f_pm = patient_module_model.where(:module_name=>sname, :parent_id=>pm.id).first\r\n							\r\n							    # Move unnessesary record to another appointment_id and patient_id\r\n							    # open record page that you need to move (f_pm), \r\n							    # use parameter update=true&sname={your_service_name}&app_id={another_appointment}\r\n							    \r\n							    # if t_pm\r\n							    #     f_pm.update_attributes :parent_id=>t_pm.id, :patient_id=>t_pm[:patient_id]\r\n							    #     ap = t_ap\r\n							    #     pm = t_pm\r\n							    # end\r\n							%>\r\n						<pre>\r\n    AppointmentID : <%= t_pm.to_json.html_safe %><br/>\r\n    <!--ParentID : <%=  %><br/>-->\r\n    Service  : <%= sname %><br/>\r\n    TEST : <%= f_pm.to_json.html_safe %>\r\n</pre>\r\n						<%\r\n							end\r\n							%>\r\n						<% end %>\r\n						<br/>\r\n						<%\r\n							previous = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\n							history = []\r\n							x = previous[0..7]\r\n							last = []\r\n							last = x.compact if x\r\n							history = []\r\n							y = previous[8..-1]\r\n							history = y.compact if y and  previous.size>5\r\n							                                     \r\n							current = time_ago_in_words(ap.date)\r\n							current_date = ap.date.strftime(\"%d-%m-%y\")\r\n							current = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n							\r\n							a_map = {}\r\n							a_ids = last.collect{|i| i[:module_id]}\r\n							a_list = get_model[:appointment].find(a_ids)\r\n							a_list.each do |i|\r\n							    a_map[i.id.to_s] = i\r\n							end\r\n						%>	\r\n						<div class=\"clear\"></div>\r\n						\r\n						<div class=\"tabbable\">\r\n						    \r\n							<ul class=\"nav nav-tabs\">\r\n								<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%><br/><%= ap[:status] %></a></li>\r\n								<%\r\n									for i in last \r\n									    m_ap_id = i[:module_id].to_s\r\n									    m_ap = a_map[m_ap_id]\r\n									    ap_status = \'NA\'\r\n									    ap_date = i.date.strftime(\"%d-%m-%y\") if i.date\r\n									    if m_ap\r\n									        ap_status = m_ap[:status].nil? ? \'N/A\' : m_ap[:status]\r\n									        ap_date = m_ap[:date].strftime(\"%d-%m-%y\")\r\n									    end\r\n								%>\r\n								<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date) if i.date%><br/><%=ap_date%><br/><%= m_ap[:status] %></a></li>\r\n								<% end %>\r\n								<% if history.size>5 %>\r\n								<li class=\"dropdown\">\r\n									<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n									<ul class=\"dropdown-menu\">\r\n										<% for j in history %>\r\n										<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n										<% end %>\r\n										<li class=\"divider\"></li>\r\n									</ul>\r\n								</li>\r\n								<% end %>\r\n								<span style=\'float:right;margin-top:20px;margin-right:10px\'>\r\n        						    <%= link_to \'Add Visit\', \"../Appointment/create?obj_id=\\\\#{patient.id.to_s}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-mini btn-success\' %>\r\n        						</span>\r\n							</ul>\r\n							<div class=\"tab-content\">\r\n								<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n									<h4><%= @current_project.title %> Records</h4>\r\n									<% if current == \'Today\' %>\r\n									<div style=\'float:right\'><%= link_to \'Edit Visit\', \"../Appointment/show?id=\\\\#{pm.id.to_s}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-mini btn-info\', :style=>\'margin-top:-30px\' %></div>\r\n									<% end %>\r\n									<hr/>\r\n									<table class=\"table table-striped table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th></th>\r\n												<th>Forms</th>\r\n												<th>Records</th>\r\n												<th></th>\r\n											</tr>\r\n										</thead>\r\n										\r\n										<%\r\n											groups = this.config\r\n											if true\r\n											for g in groups \r\n											   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n											%>\r\n										<tr>\r\n											<td colspan=\"4\"><%=g[:name]%></td>\r\n										</tr>\r\n										<% services.each_with_index do |s,index|\r\n											module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n											records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n											%>\r\n										<tr>\r\n											<td><%= index+1 %>. </td>\r\n											<td> <%= s.title %></td>\r\n											<td align=\"center\">\r\n										    <% for i in records %>\r\n												<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number[0..9] if !i.ref_number.nil?}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n												<%= link_to \"Edit\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=