end %>\r\n										<% end %>\r\n									</table>\r\n								</div>\r\n								\r\n								\r\n								<% for i in previous \r\n									pm = i\r\n									%>\r\n								<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n									<h4><%= @current_project.title %> Records</h4>\r\n									<% \r\n								\r\n									    \r\n									    x = a_map[i[:module_id].to_s]\r\n									    \r\n									    \r\n									    \r\n									    \r\n									   # if x and  Time.now.to_i < x[:date].to_time.to_i\r\n									        \r\n								    %> \r\n									<div style=\'float:right\'><%= link_to \'Edit Visit\', \"../Appointment/show?id=\\\\#{i.id.to_s}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-mini btn-info\', :style=>\'margin-top:-30px\' %></div>\r\n									<% \r\n									   # end \r\n									%>\r\n							\r\n									\r\n									<hr/>\r\n									<table class=\"table table-striped table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th></th>\r\n												<th>Forms</th>\r\n												<th>Records</th>\r\n												<th></th>\r\n											</tr>\r\n										</thead>\r\n										\r\n										<%\r\n											groups = this.config\r\n											if true\r\n											for g in groups \r\n											   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n											%>\r\n										<tr>\r\n											<td colspan=\"4\"><%=g[:name]%></td>\r\n										</tr>\r\n										\r\n										<% services.each_with_index do |s,index|\r\n											module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n											records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n											%>\r\n										<tr>\r\n											<td><%= index+1 %>. </td>\r\n											<td> <%= s.title %></td>\r\n											<td align=\"center\">\r\n											<% for i in records %>\r\n												<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n												<%= link_to \"Edit\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-mini btn-info\' %>\r\n												<% if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n                                                <%= link_to \" Delete \", \"javascript:confirm_delete(\'\\\\#{s.name.camelize}\',\'\\\\#{i.id}\')\", :class=>\'btn btn-danger btn-mini\' %> \r\n                                                <% end %>\r\n											<% end %>\r\n											</td>\r\n											<td>\r\n												<%  if records.size==0 %>\r\n												<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n												<% else %>\r\n												<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n												<% end %>\r\n												<br/>\r\n											</td>\r\n											<% end %>\r\n										</tr>\r\n										<% end %>\r\n										<% end %>\r\n									</table>\r\n								</div>\r\n								<% end %>\r\n							</div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n				<% else %>\r\n				Data missing\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<script>\r\n	$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n	\r\n	function confirm_delete(ser, id) {\r\n        if (confirm(\'Do you want to continue?\')) {\r\n            url = \"../\" + ser + \"/destroy?id=\" + id + \"&return=<%=request.fullpath%>\"\r\n            window.location = url;\r\n        }\r\n    }\r\n</script>',NULL,NULL,NULL,'2017-04-19 14:00:40','2017-04-19 14:00:40','patient_record',''),(3003,'document_name',1195,1,'\'nurse