                 <input id=\"confirm\" name=\"confirm\" type=\"text\" class=\"form-control required\" aria-required=\"true\">\r\n                                            </div>\r\n                                        </div>\r\n                                        <div class=\"col-lg-4\">\r\n                                            <div class=\"text-center\">\r\n                                                <div style=\"margin-top: 20px\">\r\n                                                    <i class=\"fa fa-sign-in\" style=\"font-size: 180px;color: #e5e5e5 \"></i>\r\n                                                </div>\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n\r\n                                </fieldset>\r\n                                <h1 id=\"form-h-1\" tabindex=\"-1\" class=\"title\">Profile</h1>\r\n                                <fieldset id=\"form-p-1\" role=\"tabpanel\" aria-labelledby=\"form-h-1\" class=\"body\" aria-hidden=\"true\" style=\"display: none;\">\r\n                                    <h2>Profile Information</h2>\r\n                                    <div class=\"row\">\r\n                                        <div class=\"col-lg-6\">\r\n                                            <div class=\"form-group\">\r\n                                                <label>First name *</label>\r\n                                                <input id=\"name\" name=\"name\" type=\"text\" class=\"form-control required\" aria-required=\"true\">\r\n                                            </div>\r\n                                            <div class=\"form-group\">\r\n                                                <label>Last name *</label>\r\n                                                <input id=\"surname\" name=\"surname\" type=\"text\" class=\"form-control required\" aria-required=\"true\">\r\n                                            </div>\r\n                                        </div>\r\n                                        <div class=\"col-lg-6\">\r\n                                            <div class=\"form-group\">\r\n                                                <label>Email *</label>\r\n                                                <input id=\"email\" name=\"email\" type=\"text\" class=\"form-control required email\" aria-required=\"true\">\r\n                                            </div>\r\n                                            <div class=\"form-group\">\r\n                                                <label>Address *</label>\r\n                                                <input id=\"address\" name=\"address\" type=\"text\" class=\"form-control\">\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                </fieldset>\r\n\r\n                                <h1 id=\"form-h-2\" tabindex=\"-1\" class=\"title\">Warning</h1>\r\n                                <fieldset id=\"form-p-2\" role=\"tabpanel\" aria-labelledby=\"form-h-2\" class=\"body\" aria-hidden=\"true\" style=\"display: none;\">\r\n                                    <div class=\"text-center\" style=\"margin-top: 120px\">\r\n                                        <h2>You did it Man :-)</h2>\r\n                                    </div>\r\n                                </fieldset>\r\n\r\n                                <h1 id=\"form-h-3\" tabindex=\"-1\" class=\"title\">Finish</h1>\r\n                                <fieldset id=\"form-p-3\" role=\"tabpanel\" aria-labelledby=\"form-h-3\" class=\"body\" aria-hidden=\"true\" style=\"display: none;\">\r\n                                    <h2>Terms and Conditions</h2>\r\n                                    <input id=\"acceptTerms\" name=\"acceptTerms\" type=\"checkbox\" class=\"required\" aria-required=\"true\"> <label for=\"acceptTerms\">I agree with the Terms and Conditions.</label>\r\n                                </fieldset>\r\n                            </div><div class=\"actions clearfix\"><ul role=\"menu\" aria-label=\"Pagination\"><li class=\"disabled\" aria-disabled=\"true\"><a href=\"#previous\" role=\"menuitem\">Previous</a></li><li aria-hidden=\"false\" aria-disabled=\"false\"><a href=\"#next\" role=\"menuitem\">Next</a></li><li aria-hidden=\"true\" style=\"display: none;\"><a href=\"#finish\" role=\"menuitem\">Finish</a></li></ul></div></form>\r\n                        </div>\r\n                    </div>\r\n                    </div>\r\n\r\n                </div>',NULL,NULL,NULL,'2017-05-22 08:29:43','2017-05-22 08:29:43','form1',''),(3025,'register',1207,2,'<div class=\"row\">\r\n            <div class=\"col-lg-7\">\r\n                <div class=\"ibox float-e-margins\">\r\n                    <div class=\"ibox-title\">\r\n                        <h5>Basic form <small>Simple login form example</small></h5>\r\n                        <div class=\"ibox-tools\">\r\n                            <a class=\"collapse-link\">\r\n                                <i class=\"fa fa-chevron-up\"></i>\r\n                            </a>\r\n                            <a class=\"dropdown-toggle\" data-toggle=\"dropdown\" href=\"#\">\r\n                                <i class=\"fa fa-wrench\"></i>\r\n                            </a>\r\n                            <ul class=\"dropdown-menu dropdown-user\">\r\n                                <li><a href=\"#\">Config option 1</a>\r\n                                </li>\r\n                                <li><a href=\"#\">Config option 2</a>\r\n                                </li>\r\n                            </ul>\r\n                            <a class=\"close-link\">\r\n                                <i class=\"fa fa-times\"></i>\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"ibox-content\">\r\n                        <div class=\"row\">\r\n                            <div class=\"col-sm-6 b-r\"><h3 class=\"m-t-none m-b\">Sign in</h3>\r\n                                <p>Sign in today for more expirience.</p>\r\n                                <form role=\"form\">\r\n                                    <div class=\"form-group\"><label>Email</label> <input type=\"email\" placeholder=\"Enter email\" class=\"form-control\"></div>\r\n                                    <div class=\"form-group\"><label>Password</label> <input type=\"password\" placeholder=\"Password\" class=\"form-control\"></div>\r\n                                    <div>\r\n                                        <button class=\"btn btn-sm btn-primary pull-right m-t-n-xs\" type=\"submit\"><strong>Log in</strong></button>\r\n                                        <label class=\"\"> <div class=\"icheckbox_square-green\" style=\"position: relative;\"><input type=\"checkbox\" class=\"i-checks\" style=\"position: absolute; opacity: 0;\"><ins class=\"iCheck-helper\" style=\"position: absolute; top: 0%; left: 0%; display: block; width: 100%; height: 100%; margin: 0px; padding: 0px; background: rgb(255, 255, 255); border: 0px; opacity: 0;\"></ins></div> Remember me </label>\r\n                                    </div>\r\n                                </form>\r\n                            </div>\r\n                            <div class=\"col-sm-6\"><h4>Not a member?</h4>\r\n                                <p>You can create an account:</p>\r\n                                <p class=\"text-center\">\r\n                                    <a href=\"\"><i class=\"fa fa-sign-in big-icon\"></i></a>\r\n                                </p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n                <div class=\"col-lg-5\">\r\n                    <div class=\"ibox float-e-margins\">\r\n                        <div class=\"ibox-title\">\r\n                            <h5>Horizontal form</h5>\r\n                            <div class=\"ibox-tools\">\r\n                                <a class=\"collapse-link\">\r\n                                    <i class=\"fa fa-chevron-up\"></i>\r\n                                </a>\r\n                                <a class=\"dropdown-toggle\" data-toggle=\"dropdown\" href=\"#\">\r\n                                    <i class=\"fa fa-wrench\"></i>\r\n                                </a>\r\n                                <ul class=\"dropdown-menu dropdown-user\">\r\n                                    <li><a href=\"#\">Config option 1</a>\r\n                                    </li>\r\n                                    <li><a href=\"#\">Config option 2</a>\r\n                                    </li>\r\n                                </ul>\r\n                                <a class=\"close-link\">\r\n                                    <i class=\"fa fa-times\"></i>\r\n                                </a>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"ibox-content\">\r\n                            <form class=\"form-horizontal\">\r\n                                <p>Sign in today for more expirience.</p>\r\n                                <div class=\"form-group\"><label class=\"col-lg-2 control-label\">Email</label>\r\n\r\n                                    <div class=\"col-lg-10\"><input type=\"email\" placeholder=\"Email\" class=\"form-control\"> <span class=\"help-block m-b-none\">Example block-level help text here.</span>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"form-group\"><label class=\"col-lg-2 control-label\">Password</label>\r\n\r\n                                    <div class=\"col-lg-10\"><input type=\"password\" placeholder=\"Password\" class=\"form-control\"></div>\r\n                                </div>\r\n                                <div class=\"form-group\">\r\n                                    <div class=\"col-lg-offset-2 col-lg-10\">\r\n                                        <div class=\"i-checks\"><label> <div class=\"icheckbox_square-green\" style=\"position: relative;\"><input type=\"checkbox\" style=\"position: absolute; opacity: 0;\"><ins class=\"iCheck-helper\" style=\"position: absolute; top: 0%; left: 0%; display: block; width: 100%; height: 100%; margin: 0px; padding: 0px; background: rgb(255, 255, 255); border: 0px; opacity: 0;\"></ins></div><i></i> Remember me </label></div>\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"form-group\">\r\n                                    <div class=\"col-lg-offset-2 col-lg-10\">\r\n                                        <button class=\"btn btn-sm btn-white\" type=\"submit\">Sign in</button>\r\n                                    </div>\r\n                                </div>\r\n                            </form>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>',NULL,NULL,NULL,'2017-05-22 08:38:04','2017-05-22 08:38:04','register',''),(3026,'index',1207,2,'<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    if params[:reset_lock]\r\n	    l = get_model[:locker].find(params[:reset_lock])\r\n        l.destroy if l\r\n	end\r\n	\r\n	begin\r\n	    date = Time.now\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    rescue\r\n    \r\n    end\r\n \r\n    if request.post? \r\n        \r\n        app = params[:record]\r\n        # pat = params[:pat]\r\n        pat = {\r\n                :hn=>app[:hn],\r\n                :first_name=>app[:first_name]\r\n            }\r\n        \r\n        if app and pat\r\n            p_app = app\r\n        \r\n            m_appointment = get_model[:appointment]\r\n            \r\n            if false\r\n            if pat[:birth_date].length <= 2\r\n                cur_year = Time.now.year\r\n                dif_year = cur_year - pat[:birth_date].to_i\r\n                pat[:birth_date] = \"01/01/\" + dif_year.to_s\r\n            elsif !pat[:birth_date].empty?\r\n                date = Date.parse(pat[:birth_date])\r\n                year = date.strftime(\"%Y\").to_i\r\n                if year > 2400\r\n                    year = year - 543\r\n                    new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                    pat[:birth_date] = new_date\r\n                end \r\n            end\r\n            end\r\n            \r\n            if !p_app[:date].empty?\r\n                date = Date.parse(p_app[:date])\r\n                year = date.strftime(\"%Y\").to_i\r\n                if year > 2400\r\n                    year = year - 543\r\n                    new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                    p_app[:date] = new_date\r\n                end \r\n            end\r\n            \r\n            patient = patient_model.where(:hn=>pat[:hn]).first\r\n            if  patient\r\n                msg = \"Appointment added.\"\r\n                err = false\r\n            else\r\n                patient = patient_model.create pat\r\n                msg = \"Patient created. Appointment added.\"\r\n            end\r\n            p_app[:end] = p_app[:start]\r\n            \r\n            rec_app = m_appointment.create p_app\r\n            rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>pat[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n\r\n        end\r\n     \r\n    end\r\n\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    r_model = models[:region]\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    regions = {}\r\n    models[:region].all.each do |i|\r\n        regions[i.id] = i[:name]\r\n    end\r\n    provs = {}\r\n    models[:provider].all.each do |i|\r\n        provs[i.id] = i[:name]\r\n    end\r\n    \r\n    is_admin = false\r\n    if (@current_role == \'developer\') or (@current_role == \'admin\')\r\n        is_admin = true\r\n    end\r\n    \r\n    aps = []\r\n    if is_admin\r\n        aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    else\r\n        aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day,:created_by=>\"\\\\#{@current_user.login}\") \r\n    end\r\n    \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n        id = i.id\r\n        if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n            \r\n             patient = patient_model.find(m.patient_id)\r\n             visit_type = visits[i.visit_type]\r\n             provider_name = provs[i.provider].nil? ? \'-\' : provs[i.provider]\r\n             procedure_name = \'-\'\r\n             patient = patient_model.new unless patient \r\n             l_hn = \'-\'\r\n             l_hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n             public_id = \'-\'\r\n            # public_id = patient.public_id if patient\r\n             c = {:m=>m,:ap=>i,:p=>patient,:ref_number=>m.ref_number,:public_id=>public_id,:hn=>patient[:hn],:link_hn=>l_hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n             :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \",:status=>i.status,:procedure=>procedure_name,\r\n             :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\', :style=>\'margin-top:10px;width:100%;max-width:200px\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n             :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n             :visit_type=>visit_type,:time=>i[:start].strftime(\'%H:%M\'),:mid=>m.id,:region=>regions[i[:region]],:police=>(provs[i[:provider_2]]),\r\n             :contact=>i[:contact], :tel_contact=>i[:tel_contact], :tel_police=>i[:tel_provider_2], :first_dead_note=>i[:first_dead_note], :police_station=>i[:police_station]\r\n             }\r\n             \r\n             if i.status==\'Waiting\'\r\n             c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n            \r\n    \r\n             #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n             else\r\n             status = \'btn-info\'\r\n             status = \'\' if i.status ==\'Completed\'\r\n             c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n             end\r\n             c\r\n        end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{ hn patient  status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard <b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b> <b><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<!--<a href=\"/cusys/www/Patient/create?return=%2Fcusys%2Fforensic%2FAppointment%2Fcreate%3Freturn%3D..%2FHome%2Findex\"><button class=\"btn\" ><i class=\"splashy-add\"></i>New Case</button></a>-->\r\n<%= link_to \"+ New case\", \"patient\", :class=>\'btn btn-info\' %>\r\n\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\',:style=>\'width:120px\' %> <%=link_to \"Today\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\", :class=>\"btn\" %><br/>\r\n\r\n<script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<hr />\r\n<%\r\n    # app_mod = module_model.where\r\n%>\r\n<%# module_model.limit(2).to_json.html_safe %>\r\n\r\n<%# params.to_json.html_safe %>\r\n                                    <table class=\"table table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th>Information</th>\r\n												<th>Action</th>\r\n											</tr>\r\n										</thead>\r\n										<tbody>\r\n<%\r\n    aps.reverse.each do |i|\r\n%>\r\n											<tr>\r\n												<td><div class=\"infomation\">\r\n                                                 <div class=\"itemm\">เลขที่</div>\r\n												  <div class=\"itemm\">\r\n												    <v>: <%= i[:hn] %></v> \r\n												    </v>\r\n											      </div>\r\n                                                   \r\n												  <div class=\"itemm\">วันที่แจ้ง</div>\r\n												  <div class=\"itemm\">\r\n												    <v>: <%= i[:date].strftime(\'%d/%m/%Y\') %> <%= i[:time] %></v>\r\n												    </v>\r\n											      </div>\r\n												  <div class=\"clear\"></div>\r\n												  <div class=\"itemm\">สาเหตุการตายเบื้องต้น</div>\r\n												  <div class=\"itemm\">\r\n												    <v>: <%= i[:first_dead_note] %></v>\r\n											      </div>\r\n												  \r\n												  <div class=\"itemm\">พื้นที่รับผิดชอบ</div>\r\n												  <div class=\"itemm\">\r\n												    <v>: <%= i[:police_station] %></v>\r\n											      </div>\r\n												  <div class=\"clear\"></div>\r\n												  <div class=\"itemm\">พนักงานสอบสวน</div>\r\n												  <div class=\"itemm\">\r\n												    <v>: <%= i[:police] %></v>\r\n											      </div>\r\n												 \r\n												  <div class=\"itemm\">เบอร์โทรสอบสวน</div>\r\n												  <div class=\"itemm\">\r\n												    <v>: <%= i[:tel_police] %></v>\r\n											      </div>\r\n												  <div class=\"clear\"></div>\r\n												  <div class=\"itemm\">ญาติ</div>\r\n												  <div class=\"itemm\">\r\n												    <v>: <%= i[:contact] %></v>\r\n											      </div>\r\n												 \r\n												  <div class=\"itemm\">เบอร์โทร</div>\r\n												  <div class=\"itemm\">\r\n												    <v>: <%= i[:tel_contact] %></v>\r\n											      </div>\r\n											    </div>												  <br></td>\r\n												<td class=\" \">\r\n        											<a href=\"../Appointment/edit?id=<%= i[:mid] %>&return=../Home/index\" class=\"btn\" title=\"Edit\" style=\"width:80px\"><i class=\"icon-pencil\"></i><br />Edit</a>\r\n        											\r\n                                                    <%\r\n                                                        # ../CrimeScene/create?patient_id=593b80d3790f9b1d67000006&record_name=123&parent_id=5a09086fe401f20c18000075&return=/forensic/Home/patient_record?id=5a09086fe401f20c18000074\r\n                                                        \r\n                                                        pm1 = module_model.where(:module_name=>\"\\\\#{@current_project.name}#crime_scene\",:parent_id=>i[:m].id).first\r\n                                            \r\n                                                        if pm1\r\n                                                            \r\n                                                         url = \"../CrimeScene/show?id=\\\\#{pm1.id}&return=../Home/index\"    \r\n                                                    %>\r\n                                                    <a class=\"btn btn-success\" style=\"width:80px\" href=\"<%=url%>\"><i class=\"icon-eye-open\"></i><br />Crime Scene</a>\r\n        										    <% else \r\n        										    \r\n        										        url = \"../CrimeScene/create?patient_id=\\\\#{i[:p].id}&record_name=\\\\#{i[:hn]}&parent_id=\\\\#{i[:m].id}&return=../Home/index\"\r\n        										    %>\r\n        										    <a class=\"btn\" style=\"width:80px\" href=\"<%=url%>\"><i class=\"icon-eye-open\"></i><br />Crime Scene</a>\r\n        										    <% end %>\r\n        											\r\n        											<a href=\"#\" class=\"btn\" title=\"Delete\" style=\"width:80px\"><i class=\"icon-trash\"></i><br />Trash</a>\r\n        											<br/>\r\n        											<div class=\'clear\'></div>\r\n        											<br/>\r\n        											<% i[:status_ctrl] %> <%= i[:processing_ctrl] %> \r\n        										</td>\r\n											</tr>\r\n<%  end %>\r\n										</tbody>\r\n									</table>\r\n\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n\r\n\r\n<% if false %>\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        New Case Today\r\n     \r\n	          <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            On Process\r\n	          <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<% end %>\r\n </div><br/>\r\n \r\n',NULL,NULL,NULL,'2017-05-27 06:48:03','2017-05-27 06:48:03','',''),(3027,'index_partial',1207,3,'<%\r\n    main = \'../Home/index\'\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	id = \'\'\r\n	a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = module_model.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n	\r\n	sm = {}\r\n	# form service\r\n	f_ser = {}\r\n	# service_map\r\n	sv =  @current_project.get_services_by_abstract(\'ehr.emr.Document\')\r\n	sv.each do |i|\r\n	    nm = i[:name]\r\n	    if nm == \'appointment\' or nm == \'billing\' or nm == \'live_document\'\r\n	        next\r\n	    end\r\n	    \r\n	   # sm[nm.to_sym] = i[:title]\r\n	   sm[nm.to_sym] = i[:package].split(\'.\')[-1]\r\n	end\r\n	sm.each do |k, v|\r\n	    f_ser[k] = {}\r\n	    tmp = module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>pa_id).all\r\n	    tmp.each do |i|\r\n	        f_ser[k][i[:patient_id].to_s] = i.id.to_s\r\n	    end\r\n	end\r\n	\r\n	aps.collect!{|i| \r\n        id = i.id\r\n        if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n            pat_id = m.patient_id.to_s\r\n    	     patient = patient_model.find(m.patient_id)\r\n    	     if patient \r\n        	     provider = p_model.find(i.provider)\r\n        	     visit_type = visits[i.visit_type]\r\n        	     provider_name = \'NA\'\r\n        	     provider_name = provider.name if provider\r\n        	     procedure_name = \'NA\'\r\n        	     pro = models[:procedure].find(i.procedure) \r\n        	     procedure_name = pro.name if pro\r\n        	     patient = patient_model.new unless patient \r\n        	     hn = \'-\'\r\n        	     \r\n        	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n        	     provider_name  = link_to(provider_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     procedure_name = link_to(procedure_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     public_id = \'-\'\r\n    	    \r\n                c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id.to_s}\"),\r\n        	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        	     :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Arrived\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n        	     :visit_type=>visit_type,\r\n        	     :note=>i[:note]\r\n                }\r\n                \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info \', :style=>\'width:45px\')\r\n                # v_link = link_to(\'<i class=\"splashy-add\"></i> Add\'.html_safe, \r\n                #     \"../OutPatientForm/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/index\", \r\n                #     :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                # c_link = \'&nbsp;&nbsp;&nbsp;&nbsp;<i class=\"splashy-remove\"></i>\'\r\n                # if f_liv[pat_id]\r\n                #     c_link = \'&nbsp;&nbsp;&nbsp;&nbsp;<i class=\"splashy-check\"></i>\'\r\n                #     v_link = link_to(\'<i class=\"splashy-document_a4\"></i> View\'.html_safe, \r\n                #         \"../OutPatientForm/show?id=\\\\#{f_liv[pat_id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                # end\r\n                # c[:processing_ctrl]= \"\\\\#{v_link} \\\\#{d_link}\".html_safe \r\n                \r\n        l_list = []\r\n        sm.each do |k, v|\r\n                    lab = k.to_s.split(\'_\')[0].humanize\r\n                    v = v.delete(\' \')\r\n                    v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                        \"../\\\\#{v}/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=\\\\#{main}\", \r\n                        :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                    if f_ser[k][pat_id]\r\n                        v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            \"../\\\\#{v}/show?id=\\\\#{f_ser[k][pat_id]}&return=\\\\#{main}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                        # v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            # \"../\\\\#{v}/print?id=\\\\#{f_ser[k][pat_id]}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\', :target=>\'_blank\')\r\n                    end\r\n                    l_list << v_link\r\n        end\\\\#{request.fullpath}\r\n        \r\n                c[:processing_ctrl]= \"\\\\#{d_link}\".html_safe \r\n                c[:processing_ctrl] = \"\\\\#{l_list.join(\' \')} \\\\#{c[:processing_ctrl]}\".html_safe\r\n                \r\n                c\r\n            end\r\n        end\r\n	}.compact!\r\n	\r\n	table_model = %w{ hn patient provider visit_type processing_ctrl note }.collect{|i| i.to_sym}\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:procedure=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n	:note=>\'Note\',:visit_type=>\'Visit\',:processing_ctrl=>\'Actions\', :out_pat=>\'Out Patient Form\' }\r\n	\r\n	%>\r\n	<%# aps.to_json.html_safe %>\r\n	<% if @current_role==\'developer\' and false%>\r\n	<%= sm.to_json.html_safe %> <hr/>\r\n	<%= sv.to_json.html_safe %>\r\n	<% end %>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=aps.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\'background:#FCF8F0\'>\r\n			                        <div class=\'row-fluid\'>\r\n			                            <table id=\'appointed-patient\' class=\"table table-striped table-bordered dTableR\">\r\n    										<thead>\r\n    											<tr>\r\n<%  table_model.each do |i| %>\r\n    												<th><%= labels[i.to_sym] %></th>\r\n<%  end %>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n    if aps.size > 0\r\n        aps.each do |i|\r\n%>\r\n                                                <tr>\r\n<%\r\n            table_model.each do |j|\r\n                \r\n%>\r\n                                                    <td style=\'vertical-align:middle\'><%= (i[j].nil? or i[j]==\'\') ? \'-\' : i[j] %></td>\r\n<%\r\n            end\r\n%>\r\n                                                </tr>\r\n<%\r\n        end\r\n%>\r\n<% end %>\r\n                                            </tbody>\r\n                                        </table>\r\n                                    </div>\r\n\r\n\r\n<!--\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = aps.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model,:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = aps.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model,:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n-->\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n</div>\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        gebo_datatbles = {\r\n    		dt_a: function() {\r\n    			$(\'#appointed-patient\').dataTable({\r\n    			    stateSave : true,\r\n                    \"sDom\": \"<\'row\'<\'span6\'<\'dt_actions\'>l><\'span6\'f>r>t<\'row\'<\'span6\'i><\'span6\'p>>\",\r\n                    \"sPaginationType\": \"bootstrap_alt\",\r\n                    \"oLanguage\": {\r\n                        \"sLengthMenu\": \"_MENU_ records/page\",\r\n                        \"sEmptyTable\": \"No patient available in table. Please \'<a href=\'javascript:add_patient()\'>Add</a>\' the patient.\"\r\n                    }\r\n                });\r\n    		}\r\n        }\r\n        \r\n        gebo_datatbles.dt_a();\r\n        // gebo_datatbles.state.save();\r\n        \r\n        // $(\'#appointed-patient\').DataTable( {\r\n        //     stateSave: true,\r\n        //     columnDefs: [ {\r\n        //         targets: [ 0 ],\r\n        //         orderData: [ 0, 1 ]\r\n        //     }, {\r\n        //         targets: [ 1 ],\r\n        //         orderData: [ 1, 0 ]\r\n        //     }, {\r\n        //         targets: [ 4 ],\r\n        //         orderData: [ 4, 0 ]\r\n        //     } ]\r\n        // } );\r\n    })\r\n</script>',NULL,NULL,NULL,'2017-05-27 07:45:02','2017-05-27 07:45:02','index_partial',''),(3028,'patient_record',1207,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if i.name!=\'live_document\' and i.name!=\'billing\'}.compact %>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and previous and  previous.size>5 \r\n                                     \r\ncurrent = time_ago_in_words(ap.date) if  ap.date\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date) if i.date%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history and history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date) if i.date%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n    # locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name if user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<span><%=text.html_safe  %></span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2017-05-27 08:17:02','2017-05-27 08:17:02','patient_record',''),(3029,'update_time_ms',1152,1,'0',NULL,NULL,NULL,'2017-05-29 14:02:59','2017-05-29 14:02:59','update_time_ms',''),(3030,'index',1173,2,'<%= render :inline=>this.common_function %>\r\n<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% 12px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n</style>\r\n\r\n<script src=\"/kendoui/js/kendo.web.min.js\"></script>\r\n<link href=\"/kendoui/styles/kendo.common.min.css\" rel=\"stylesheet\"/>\r\n<script src=\"/kendoui/js/kendo.all.min.js\"></script>\r\n\r\n<script src=\"/kendoui/source/js/kendo.numerictextbox.js\"></script>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Available Reports</h3>\r\n                <% if @current_role==\'developer\' %>\r\n                    <div class=\'row-fluid\'>\r\n                        <div style=\'float:right\'><%= link_to \'Manage\', \'index_dev\', :class=>\'btn btn-info btn-mini\', :style=>\'margin-top:-60px\' %></div>\r\n                    </div>\r\n                <% end %>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n            \r\n<% \r\n    if session[:owner] or (@current_role == \'developer\') \r\n        rep = get_model[:report].all\r\n        g_rep = rep.group_by{|i| i[:category]}\r\n        \r\n        df  = get_document_field \'report\'\r\n        cat = df[:category][:lov].split(\' \')\r\n        \r\n%>\r\n            <div class=\'row-fluid\'>\r\n                <div class=\'span12\'>\r\n                \r\n<%\r\n        cat.each do |i|\r\n%>\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px\">\r\n                            <div id=\"accordion-<%= i.downcase %>\" class=\"accordion\">\r\n                            \r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapse-<%= i.downcase %>\" data-parent=\"#accordion-<%= i.downcase %>\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											<%= i %>\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapse-<%= i.downcase %>\">\r\n										<div class=\"accordion-inner\">\r\n										\r\n										\r\n										<div class=\'row-fluid\'>\r\n										    <div id=\"result-<%= i.downcase %>\"></div>\r\n										</div>\r\n\r\n										\r\n<%\r\n            v = g_rep[i]\r\n            if !v.nil?\r\n                v.each do |j|\r\n                    ln = j[:service]\r\n                    if ln.include? \'?\'\r\n                        ln += \"&update=result-\\\\#{i.downcase}\"\r\n                    else\r\n                        ln += \"?update=result-\\\\#{i.downcase}\"\r\n                    end\r\n%>\r\n    <div class=\'row-fluid\'>\r\n            <%= link_to j[:name].html_safe, ln, :class=>\'span12 btn\',  :remote=>true  %>\r\n    </div>\r\n    <br/>\r\n<% \r\n                end\r\n            end\r\n%>\r\n										</div>\r\n									</div>\r\n								</div>\r\n							</div>\r\n					</div>\r\n				</div>\r\n\r\n<%\r\n        end \r\n%>\r\n\r\n                </div> \r\n            </div>\r\n\r\n\r\n\r\n\r\n<% else %>\r\n                <center><h1>Access Denied</h1></center>\r\n<script>\r\n    window.location = \'../Home/index\';\r\n</script>\r\n<% end %>\r\n            \r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<script>\r\n    refresh_remote();\r\n</script>',NULL,NULL,NULL,'2017-06-01 07:48:08','2017-06-01 07:48:08','index',''),(3031,'provider_hosp',1173,3,'<%\r\n    prov = get_model[:provider].all\r\n    hosp = get_model[:hospital].all\r\n    \r\n    g_hosp = hosp.group_by{|i| i.id.to_s}\r\n    \r\n    res = {}\r\n    res[:prov] = prov\r\n    res[:hosp] = hosp\r\n    \r\n    prov_no_hosp = []\r\n    prov_hosp = []\r\n    hosp_list = []\r\n    prov.each do |i|\r\n        if i[:main_hospital].nil?\r\n            prov_no_hosp << i\r\n        else\r\n            h = i[:main_hospital]\r\n            tmp = {}\r\n            tmp[:prov] = i\r\n            tmp[:hosp] = g_hosp[h.to_s]\r\n            prov_hosp << tmp\r\n            hosp_list << h\r\n        end\r\n    end\r\n    \r\n    res = {}\r\n    res[:no_hosp_count] = prov_no_hosp.count\r\n    res[:no_hosp] = prov_no_hosp\r\n    res[:in_hosp_count] = prov_hosp.count\r\n    res[:in_hosp] = prov_hosp\r\n    res[:hosp] = hosp_list.uniq\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2017-06-01 07:51:59','2017-06-01 07:51:59','provider_hosp',''),(3032,'show',628,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px\">\r\n\r\n\r\n\r\n<%= this.display.html_safe %>\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\#{params[:id]}&return=\\#{return_url}\",:class=>bt_class %> | \r\n<%# link_to \'Back\', return_url %>\r\n<%= link_to \'Back\', \"../Home/index\" %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-06-01 08:07:33','2017-06-01 08:07:33','show',''),(3033,'list',628,3,'<style>\r\n/*!\r\n * FullCalendar v1.6.0 Stylesheet\r\n * Docs & License: http://arshaw.com/fullcalendar/\r\n * (c) 2013 Adam Shaw\r\n */\r\n\r\n\r\n.fc {\r\n    direction: ltr;\r\n	text-align: left;\r\n	}\r\n	\r\n.fc table {\r\n	border-collapse: collapse;\r\n	border-spacing: 0;\r\n	}\r\n	\r\nhtml .fc,\r\n.fc table {\r\n	font-size: 1em;\r\n	}\r\n	\r\n.fc td,\r\n.fc th {\r\n	padding: 0;\r\n	vertical-align: top;\r\n	}\r\n\r\n\r\n\r\n/* Header\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-header td {\r\n	white-space: nowrap;\r\n	}\r\n\r\n.fc-header-left {\r\n	width: 25%;\r\n	text-align: left;\r\n	}\r\n	\r\n.fc-header-center {\r\n	text-align: center;\r\n	}\r\n	\r\n.fc-header-right {\r\n	width: 25%;\r\n	text-align: right;\r\n	}\r\n	\r\n.fc-header-title {\r\n	display: inline-block;\r\n	vertical-align: top;\r\n	}\r\n	\r\n.fc-header-title h2 {\r\n	margin-top: 0;\r\n	white-space: nowrap;\r\n	}\r\n	\r\n.fc .fc-header-space {\r\n	padding-left: 10px;\r\n	}\r\n	\r\n.fc-header .fc-button {\r\n	margin-bottom: 1em;\r\n	vertical-align: top;\r\n	}\r\n	\r\n/* buttons edges butting together */\r\n\r\n.fc-header .fc-button {\r\n	margin-right: -1px;\r\n	}\r\n	\r\n.fc-header .fc-corner-right,  /* non-theme */\r\n.fc-header .ui-corner-right { /* theme */\r\n	margin-right: 0; /* back to normal */\r\n	}\r\n	\r\n/* button layering (for border precedence) */\r\n	\r\n.fc-header .fc-state-hover,\r\n.fc-header .ui-state-hover {\r\n	z-index: 2;\r\n	}\r\n	\r\n.fc-header .fc-state-down {\r\n	z-index: 3;\r\n	}\r\n\r\n.fc-header .fc-state-active,\r\n.fc-header .ui-state-active {\r\n	z-index: 4;\r\n	}\r\n	\r\n	\r\n	\r\n/* Content\r\n------------------------------------------------------------------------*/\r\n	\r\n.fc-content {\r\n	clear: both;\r\n	}\r\n	\r\n.fc-view {\r\n	width: 100%; /* needed for view switching (when view is absolute) */\r\n	overflow: hidden;\r\n	}\r\n	\r\n	\r\n\r\n/* Cell Styles\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-widget-header,    /* <th>, usually */\r\n.fc-widget-content {  /* <td>, usually */\r\n	border: 1px solid #ddd;\r\n	}\r\n	\r\n.fc-state-highlight { /* <td> today cell */ /* TODO: add .fc-today to <th> */\r\n	background: #fcf8e3;\r\n	}\r\n	\r\n.fc-cell-overlay { /* semi-transparent rectangle while dragging */\r\n	background: #bce8f1;\r\n	opacity: .3;\r\n	filter: alpha(opacity=30); /* for IE */\r\n	}\r\n	\r\n\r\n\r\n/* Buttons\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-button {\r\n	position: relative;\r\n	display: inline-block;\r\n	padding: 0 .6em;\r\n	overflow: hidden;\r\n	height: 1.9em;\r\n	line-height: 1.9em;\r\n	white-space: nowrap;\r\n	cursor: pointer;\r\n	}\r\n	\r\n.fc-state-default { /* non-theme */\r\n	border: 1px solid;\r\n	}\r\n\r\n.fc-state-default.fc-corner-left { /* non-theme */\r\n	border-top-left-radius: 4px;\r\n	border-bottom-left-radius: 4px;\r\n	}\r\n\r\n.fc-state-default.fc-corner-right { /* non-theme */\r\n	border-top-right-radius: 4px;\r\n	border-bottom-right-radius: 4px;\r\n	}\r\n\r\n/*\r\n	Our default prev/next buttons use HTML entities like &lsaquo; &rsaquo; &laquo; &raquo;\r\n	and we\'ll try to make them look good cross-browser.\r\n*/\r\n\r\n.fc-text-arrow {\r\n	margin: 0 .1em;\r\n	font-size: 2em;\r\n	font-family: \"Courier New\", Courier, monospace;\r\n	vertical-align: baseline; /* for IE7 */\r\n	}\r\n\r\n.fc-button-prev .fc-text-arrow,\r\n.fc-button-next .fc-text-arrow { /* for &lsaquo; &rsaquo; */\r\n	font-weight: bold;\r\n	}\r\n	\r\n/* icon (for jquery ui) */\r\n	\r\n.fc-button .fc-icon-wrap {\r\n	position: relative;\r\n	float: left;\r\n	top: 50%;\r\n	}\r\n	\r\n.fc-button .ui-icon {\r\n	position: relative;\r\n	float: left;\r\n	margin-top: -50%;\r\n	*margin-top: 0;\r\n	*top: -50%;\r\n	}\r\n	\r\n/*\r\n  button states\r\n  borrowed from twitter bootstrap (http://twitter.github.com/bootstrap/)\r\n*/\r\n\r\n.fc-state-default {\r\n	background-color: #f5f5f5;\r\n	background-image: -moz-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: -webkit-gradient(linear, 0 0, 0 100%, from(#ffffff), to(#e6e6e6));\r\n	background-image: -webkit-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: -o-linear-gradient(top, #ffffff, #e6e6e6);\r\n	background-image: linear-gradient(to bottom, #ffffff, #e6e6e6);\r\n	background-repeat: repeat-x;\r\n	border-color: #e6e6e6 #e6e6e6 #bfbfbf;\r\n	border-color: rgba(0, 0, 0, 0.1) rgba(0, 0, 0, 0.1) rgba(0, 0, 0, 0.25);\r\n	color: #333;\r\n	text-shadow: 0 1px 1px rgba(255, 255, 255, 0.75);\r\n	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2), 0 1px 2px rgba(0, 0, 0, 0.05);\r\n	}\r\n\r\n.fc-state-hover,\r\n.fc-state-down,\r\n.fc-state-active,\r\n.fc-state-disabled {\r\n	color: #333333;\r\n	background-color: #e6e6e6;\r\n	}\r\n\r\n.fc-state-hover {\r\n	color: #333333;\r\n	text-decoration: none;\r\n	background-position: 0 -15px;\r\n	-webkit-transition: background-position 0.1s linear;\r\n	   -moz-transition: background-position 0.1s linear;\r\n	     -o-transition: background-position 0.1s linear;\r\n	        transition: background-position 0.1s linear;\r\n	}\r\n\r\n.fc-state-down,\r\n.fc-state-active {\r\n	background-color: #cccccc;\r\n	background-image: none;\r\n	outline: 0;\r\n	box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.15), 0 1px 2px rgba(0, 0, 0, 0.05);\r\n	}\r\n\r\n.fc-state-disabled {\r\n	cursor: default;\r\n	background-image: none;\r\n	opacity: 0.65;\r\n	filter: alpha(opacity=65);\r\n	box-shadow: none;\r\n	}\r\n\r\n	\r\n\r\n/* Global Event Styles\r\n------------------------------------------------------------------------*/\r\n	 \r\n.fc-event {\r\n	border: 1px solid #3a87ad; /* default BORDER color */\r\n	background-color: #3a87ad; /* default BACKGROUND color */\r\n	color: #fff;               /* default TEXT color */\r\n	text-shadow: 0 -1px 0 rgba(0, 0, 0, 0.25);\r\n	font-size: .85em;\r\n	cursor: default;\r\n	}\r\n\r\na.fc-event {\r\n	text-decoration: none;\r\n	}\r\n	\r\na.fc-event,\r\n.fc-event-draggable {\r\n	cursor: pointer;\r\n	}\r\n	\r\n.fc-rtl .fc-event {\r\n	text-align: right;\r\n	}\r\n\r\n.fc-event-inner {\r\n	width: 100%;\r\n	overflow: hidden;\r\n	}\r\n	\r\n.fc-event-time,\r\n.fc-event-title {\r\n	padding: 0 1px;\r\n	}\r\n	\r\n.fc .ui-resizable-handle {\r\n	display: block;\r\n	position: absolute;\r\n	z-index: 99999;\r\n	overflow: hidden; /* hacky spaces (IE6/7) */\r\n	font-size: 300%;  /* */\r\n	line-height: 50%; /* */\r\n	}\r\n	\r\n	\r\n	\r\n/* Horizontal Events\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-event-hori {\r\n	border-width: 1px 0;\r\n	margin-bottom: 1px;\r\n	}\r\n\r\n.fc-ltr .fc-event-hori.fc-event-start,\r\n.fc-rtl .fc-event-hori.fc-event-end {\r\n	border-left-width: 1px;\r\n	border-top-left-radius: 3px;\r\n	border-bottom-left-radius: 3px;\r\n	}\r\n\r\n.fc-ltr .fc-event-hori.fc-event-end,\r\n.fc-rtl .fc-event-hori.fc-event-start {\r\n	border-right-width: 1px;\r\n	border-top-right-radius: 3px;\r\n	border-bottom-right-radius: 3px;\r\n	}\r\n	\r\n/* resizable */\r\n	\r\n.fc-event-hori .ui-resizable-e {\r\n	top: 0           !important; /* importants override pre jquery ui 1.7 styles */\r\n	right: -3px      !important;\r\n	width: 7px       !important;\r\n	height: 100%     !important;\r\n	cursor: e-resize;\r\n	}\r\n	\r\n.fc-event-hori .ui-resizable-w {\r\n	top: 0           !important;\r\n	left: -3px       !important;\r\n	width: 7px       !important;\r\n	height: 100%     !important;\r\n	cursor: w-resize;\r\n	}\r\n	\r\n.fc-event-hori .ui-resizable-handle {\r\n	_padding-bottom: 14px; /* IE6 had 0 height */\r\n	}\r\n	\r\n	\r\n	\r\n/* Reusable Separate-border Table\r\n------------------------------------------------------------*/\r\n\r\ntable.fc-border-separate {\r\n	border-collapse: separate;\r\n	}\r\n	\r\n.fc-border-separate th,\r\n.fc-border-separate td {\r\n	border-width: 1px 0 0 1px;\r\n	}\r\n	\r\n.fc-border-separate th.fc-last,\r\n.fc-border-separate td.fc-last {\r\n	border-right-width: 1px;\r\n	}\r\n	\r\n.fc-border-separate tr.fc-last th,\r\n.fc-border-separate tr.fc-last td {\r\n	border-bottom-width: 1px;\r\n	}\r\n	\r\n.fc-border-separate tbody tr.fc-first td,\r\n.fc-border-separate tbody tr.fc-first th {\r\n	border-top-width: 0;\r\n	}\r\n	\r\n	\r\n\r\n/* Month View, Basic Week View, Basic Day View\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-grid th {\r\n	text-align: center;\r\n	}\r\n\r\n.fc .fc-week-number {\r\n	width: 22px;\r\n	text-align: center;\r\n	}\r\n\r\n.fc .fc-week-number div {\r\n	padding: 0 2px;\r\n	}\r\n	\r\n.fc-grid .fc-day-number {\r\n	float: right;\r\n	padding: 0 2px;\r\n	}\r\n	\r\n.fc-grid .fc-other-month .fc-day-number {\r\n	opacity: 0.3;\r\n	filter: alpha(opacity=30); /* for IE */\r\n	/* opacity with small font can sometimes look too faded\r\n	   might want to set the \'color\' property instead\r\n	   making day-numbers bold also fixes the problem */\r\n	}\r\n	\r\n.fc-grid .fc-day-content {\r\n	clear: both;\r\n	padding: 2px 2px 1px; /* distance between events and day edges */\r\n	}\r\n	\r\n/* event styles */\r\n	\r\n.fc-grid .fc-event-time {\r\n	font-weight: bold;\r\n	}\r\n	\r\n/* right-to-left */\r\n	\r\n.fc-rtl .fc-grid .fc-day-number {\r\n	float: left;\r\n	}\r\n	\r\n.fc-rtl .fc-grid .fc-event-time {\r\n	float: right;\r\n	}\r\n	\r\n	\r\n\r\n/* Agenda Week View, Agenda Day View\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-agenda table {\r\n	border-collapse: separate;\r\n	}\r\n	\r\n.fc-agenda-days th {\r\n	text-align: center;\r\n	}\r\n	\r\n.fc-agenda .fc-agenda-axis {\r\n	width: 50px;\r\n	padding: 0 4px;\r\n	vertical-align: middle;\r\n	text-align: right;\r\n	white-space: nowrap;\r\n	font-weight: normal;\r\n	}\r\n\r\n.fc-agenda .fc-week-number {\r\n	font-weight: bold;\r\n	}\r\n	\r\n.fc-agenda .fc-day-content {\r\n	padding: 2px 2px 1px;\r\n	}\r\n	\r\n/* make axis border take precedence */\r\n	\r\n.fc-agenda-days .fc-agenda-axis {\r\n	border-right-width: 1px;\r\n	}\r\n	\r\n.fc-agenda-days .fc-col0 {\r\n	border-left-width: 0;\r\n	}\r\n	\r\n/* all-day area */\r\n	\r\n.fc-agenda-allday th {\r\n	border-width: 0 1px;\r\n	}\r\n	\r\n.fc-agenda-allday .fc-day-content {\r\n	min-height: 34px; /* TODO: doesnt work well in quirksmode */\r\n	_height: 34px;\r\n	}\r\n	\r\n/* divider (between all-day and slots) */\r\n	\r\n.fc-agenda-divider-inner {\r\n	height: 2px;\r\n	overflow: hidden;\r\n	}\r\n	\r\n.fc-widget-header .fc-agenda-divider-inner {\r\n	background: #eee;\r\n	}\r\n	\r\n/* slot rows */\r\n	\r\n.fc-agenda-slots th {\r\n	border-width: 1px 1px 0;\r\n	}\r\n	\r\n.fc-agenda-slots td {\r\n	border-width: 1px 0 0;\r\n	background: none;\r\n	}\r\n	\r\n.fc-agenda-slots td div {\r\n	height: 20px;\r\n	}\r\n	\r\n.fc-agenda-slots tr.fc-slot0 th,\r\n.fc-agenda-slots tr.fc-slot0 td {\r\n	border-top-width: 0;\r\n	}\r\n\r\n.fc-agenda-slots tr.fc-minor th,\r\n.fc-agenda-slots tr.fc-minor td {\r\n	border-top-style: dotted;\r\n	}\r\n	\r\n.fc-agenda-slots tr.fc-minor th.ui-widget-header {\r\n	*border-top-style: solid; /* doesn\'t work with background in IE6/7 */\r\n	}\r\n	\r\n\r\n\r\n/* Vertical Events\r\n------------------------------------------------------------------------*/\r\n\r\n.fc-event-vert {\r\n	border-width: 0 1px;\r\n	}\r\n\r\n.fc-event-vert.fc-event-start {\r\n	border-top-width: 1px;\r\n	border-top-left-radius: 3px;\r\n	border-top-right-radius: 3px;\r\n	}\r\n\r\n.fc-event-vert.fc-event-end {\r\n	border-bottom-width: 1px;\r\n	border-bottom-left-radius: 3px;\r\n	border-bottom-right-radius: 3px;\r\n	}\r\n	\r\n.fc-event-vert .fc-event-time {\r\n	white-space: nowrap;\r\n	font-size: 10px;\r\n	}\r\n\r\n.fc-event-vert .fc-event-inner {\r\n	position: relative;\r\n	z-index: 2;\r\n	}\r\n	\r\n.fc-event-vert .fc-event-bg { /* makes the event lighter w/ a semi-transparent overlay  */\r\n	position: absolute;\r\n	z-index: 1;\r\n	top: 0;\r\n	left: 0;\r\n	width: 100%;\r\n	height: 100%;\r\n	background: #fff;\r\n	opacity: .3;\r\n	filter: alpha(opacity=30);\r\n	}\r\n	\r\n.fc .ui-draggable-dragging .fc-event-bg, /* TODO: something nicer like .fc-opacity */\r\n.fc-select-helper .fc-event-bg {\r\n	display: none\\9; /* for IE6/7/8. nested opacity filters while dragging don\'t work */\r\n	}\r\n	\r\n/* resizable */\r\n	\r\n.fc-event-vert .ui-resizable-s {\r\n	bottom: 0        !important; /* importants override pre jquery ui 1.7 styles */\r\n	width: 100%      !important;\r\n	height: 8px      !important;\r\n	overflow: hidden !important;\r\n	line-height: 8px !important;\r\n	font-size: 11px  !important;\r\n	font-family: monospace;\r\n	text-align: center;\r\n	cursor: s-resize;\r\n	}\r\n	\r\n.fc-agenda .ui-resizable-resizing { /* TODO: better selector */\r\n	_overflow: hidden;\r\n	}\r\n	\r\n	\r\n</style>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n   records = []\r\n   n = 10 \r\n%>\r\n<%\r\n   \r\n   values = {}\r\n   query=\'\'\r\n   if params[:search]\r\n\r\n        \r\n        query = params[:search][:query]\r\n          keys = []\r\n    \r\n        @patient_doc.list_fields.each_with_index do |f,index| \r\n		    keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        \r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n\r\n                \r\n        ps = @patient_model.all({\'$or\'=>keys}.merge!(dates))\r\n   \r\n        records = []\r\n        for i in ps\r\n            records+= @module_model.where(:patient_id=>i.id,:module_name=>@module_name).all\r\n        end\r\n        count = records.size\r\n        \r\n        \r\n    else\r\n        from_date = nil\r\n        to_date = nil  \r\n          n = @module_model.where(:module_name=>@module_name).count\r\n        rows,offset,page = params[:paginate]\r\n        records = @module_model.where(:module_name=>@module_name).all(:order=>\'created_at desc\',:limit=>20)\r\n    end\r\n\r\n\r\n patients = {}\r\n @patient_model.find(records.collect{|i| i.patient_id}).each do |i|\r\n patients[i.id]=i\r\n end\r\n appointments = {}\r\n @models[:appointment].find(records.collect{|i| i.module_id}).each do |i|\r\n appointments[i.id]=i\r\n end\r\n \r\n title = \'Calendar\'\r\n \r\n if params[:provider_id]\r\n    provider = @models[:provider].find(params[:provider_id])\r\n    title = \"\\#{provider.name}\'s Calendar\"\r\n end\r\n%>\r\n\r\n  <link rel=\"stylesheet\" href=\"/gebo/lib/fullcalendar/fullcalendar_gebo.css\" />\r\n  <div class=\"row-fluid\">\r\n            			<div class=\"span12\">\r\n							<h2 class=\"heading\"><%= title %></h2>\r\n							<div id=\"calendar\"></div>\r\n						</div>\r\n					</div>\r\n\r\n\r\n    	<script src=\"/gebo/lib/fullcalendar/fullcalendar.min.js\"></script>\r\n			<!-- calendar functions -->\r\n			<script src=\"/gebo/lib/fullcalendar/gcal.js\"></script>\r\n<%\r\n   pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\njson_data =   records.collect{|i| \r\nl = %w{#bcdeee}\r\nap = appointments[i.module_id] \r\np = patients[i.patient_id]\r\nif (ap and params[:provider_id]==nil) or (params[:provider_id] and ap.provider.to_s==params[:provider_id].to_s)\r\n     date_d = \'-\'\r\n     date_d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n     date_s = \'-\'\r\n     date_s = ap.date.strftime(\"%Y-%m-%d\")+ap.start.strftime(\" %H:%M\") if ap.date and ap.start\r\n     date_e = \'-\'\r\n     date_e = ap.date.strftime(\"%Y-%m-%d\")+ap.stop.strftime(\" %H:%M\") if ap.date  and ap.stop\r\n     \r\n     \r\n    {\'procedure\'=>pro[ap.procedure],\'date\'=>date_d,\'color\'=>l[rand(4%l.size)],\'title\'=>\"\\#{p.first_name if p } \\#{p.hn if p}\",\'start\'=>date_s,\'end\'=>date_e,\'allDay\'=>false,\'url\'=>\'edit?id=\'+i.id.to_s}  \r\nelse\r\n    nil\r\nend \r\n}.compact\r\n\r\n    \r\n    df =   @models[:day_off].all\r\n \r\n    \r\n    df_list = df.collect{|i|\r\n        pname = \'\'\r\n        p = @models[:provider].find(i.provider)\r\n        pname = p.name if p\r\n        date =  \'-\'\r\n        date = i.date.strftime(\"%Y-%m-%d\") if i.date\r\n        {\'color\'=>\'#ccc\',\'title\'=>\"\\#{i.title} \\#{pname}\",\'start\'=>date,\'allDay\'=>true}\r\n    }\r\n    \r\n    map = {}\r\n    \r\n    for i in json_data\r\n    \r\n    date = i[\'date\']\r\n    p = i[\'procedure\']\r\n    \r\n    map[date] = {} unless map[date]\r\n    map[date][p] = 0  unless map[date][p]\r\n    map[date][p] += 1\r\n    \r\n    end\r\n    \r\n    c_list = []\r\n    map.each_pair do |k,v|\r\n         txt = \'\'\r\n         v.each_pair { |key, value| txt+=\"\\#{key}=\\#{value}   \".html_safe }\r\n         c_list<<{\'color\'=>\'#fcc\',\'title\'=>\"\\#{txt}\",\'start\'=>k,\'allDay\'=>true,\'url\'=>\'/\'}\r\n    end\r\n    \r\n    detail = json_data\r\n    \r\n    json_data = df_list\r\n    \r\n    json_data+= c_list\r\n    \r\n    json_data+= detail if params[:detail]    \r\n%>\r\n<%#df.inspect %>\r\n\r\n<script>\r\n\r\n var refresh_loading = false;\r\n\r\n function refresh_date(start,end,detail,provider_id){\r\n    \r\n        if(refresh_loading==false){\r\n        refresh_loading = true\r\n    \r\n        path = \'data\'\r\n        detail_path = \'data_detail\'\r\n      \r\n        $.ajax({\r\n            url: path ,\r\n            dataType: \'json\',\r\n            data: {\r\n                start: start,\r\n                end: end,\r\n                detail: detail,\r\n                provider_id: provider_id\r\n            },\r\n            success: function(doc) {\r\n             data = eval(doc);\r\n            $(\'#calendar\').fullCalendar(\'removeEvents\');\r\n           \r\n            $.each(data, function(index, event){\r\n            $(\'#calendar\').fullCalendar(\'renderEvent\', event);\r\n            });\r\n            }\r\n            });\r\n            \r\n         $.ajax({\r\n            url: detail_path,\r\n            data: {\r\n                start: start,\r\n                end: end,\r\n                detail: detail,\r\n                provider_id: provider_id\r\n            },\r\n            success: function(doc) {\r\n                $(\'#event-details\').html(doc);\r\n            }\r\n         });\r\n\r\n    refresh_loading=false;\r\n     $(\'#loading\').hide();\r\n        }\r\n    \r\n}\r\n    $(document).ready(function() {\r\n\r\n\r\n\r\n\r\n\r\n        gebo_calendar.regular();\r\n\r\n		//* resize elements on window resize\r\n		var lastWindowHeight = $(window).height();\r\n		var lastWindowWidth = $(window).width();\r\n		$(window).on(\"debouncedresize\",function() {\r\n      \r\n			if($(window).height()!=lastWindowHeight || $(window).width()!=lastWindowWidth){\r\n				lastWindowHeight = $(window).height();\r\n				lastWindowWidth = $(window).width();\r\n				//* rebuild calendar\r\n			}\r\n		});\r\n	});\r\n	\r\n	//* calendar\r\n	gebo_calendar = {\r\n		regular: function() {\r\n			var date = new Date();\r\n			var d = date.getDate();\r\n			var m = date.getMonth();\r\n			var y = date.getFullYear();\r\n			var calendar = $(\'#calendar\').fullCalendar({\r\n				header: {\r\n					left: \'prev,next today\',\r\n					center: \'title\',\r\n					right: \'month,agendaWeek,agendaDay\'\r\n				},\r\n		\r\n				aspectRatio: 2,\r\n				selectable: true,\r\n				selectHelper: true,\r\n                \r\n      dayClick: function(date, allDay, jsEvent, view) {\r\n      if($(\'#calendar\').fullCalendar( \'getView\').name!=\'month\')\r\n            window.location=\"../DayOff/create?data[date]=\"+date.getFullYear()+\'-\'+(date.getMonth()+1)+\'-\'+date.getDate() +\"&return=../Appointment/index\"\r\n      $(\'#calendar\').fullCalendar( \'changeView\', \'agendaDay\' );\r\n      $(\'#calendar\').fullCalendar( \'gotoDate\', date.getFullYear() ,date.getMonth(), date.getDate()  );\r\n      \r\n       provider_id = \"<%=params[:provider_id]%>\";\r\n      \r\n       refresh_date(date.getTime()/1000,date.getTime()/1000+3600*24-1,true,provider_id);\r\n      \r\n     \r\n      \r\n      },\r\n      viewDisplay: function(view) {\r\n          \r\n\r\n        if(view.name == \'month\')\r\n        { \r\n            $(\'#calendar\').fullCalendar(\'refetchEvents\');\r\n        }\r\n        if(view.name==\'agendaWeek\'){\r\n             $(\'#calendar\').fullCalendar(\'refetchEvents\');\r\n        }\r\n      },\r\n	  select: function(start, end, allDay) {\r\n               \r\n      if(allDay==false){\r\n	        calendar.fullCalendar(\'unselect\');\r\n            window.location=\"create?data[date]=\"+start.getFullYear()+\'-\'+(start.getMonth()+1)+\'-\'+start.getDate()+\"&data[start]=\"+\r\n            start.getHours()+\":\"+start.getMinutes()+\"&data[stop]=\"+end.getHours()+\":\"+end.getMinutes()\r\n      }\r\n               \r\n	  }\r\n      ,\r\n	  editable: false,\r\n	  theme: false,\r\n	  events: function(start, end, callback) {\r\n   \r\n    \r\n      provider_id = \"<%=params[:provider_id]%>\";\r\n    \r\n  \r\n      refresh_date(Math.round(start.getTime() / 1000),Math.round(end.getTime() / 1000),<%=params[:detail]==\'true\'%>,provider_id);\r\n         \r\n\r\n     },\r\n	  loading: function(bool) {\r\n	  if (bool) $(\'#loading\').show();\r\n	  else $(\'#loading\').hide();\r\n	  }\r\n	});\r\n	}\r\n	};\r\n</script>\r\n<div id=\'loading\' style=\'display:none\'>Loading...</div>\r\n\r\n<div id=\"event-details\">\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2017-06-01 08:07:47','2017-06-01 08:07:47','list',''),(3034,'testz',628,3,'<%\r\n    res = {}\r\n    \r\n    # initial code\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	m_pat = @ehr_model[:patient]\r\n	m_pat_mod = @ehr_model[:patient_module]\r\n    \r\n    if params[:id]\r\n        res = get_model[this.table_name.to_sym].find(params[:id])\r\n    end\r\n    \r\n    if params[:pat]\r\n        res = m_pat_mod.where(:patient_id=>params[:pat]).all\r\n    end\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2017-06-01 08:08:05','2017-06-01 08:08:05','testz',''),(3035,'create_ole',627,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Create Patient</h3>\r\n<!--<strong>Create Patient</strong>-->\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n<div >\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\" >\r\n\r\n<%= render :inline=>this.init %>\r\n<% # params.inspect %>\r\n<%\r\n\r\n    msg = nil\r\n    err = false\r\n\r\n    if request.post?\r\n      \r\n        p = params[:record]\r\n        return_url = params[:return]\r\n        date = Time.now\r\n        if !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        \r\n        # next_service = \"../Patient/create_test?return=\\#{return_url}&\".html_safe\r\n        next_service = \"../Home/index\"\r\n        patient = false\r\n        # patient = @patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Duplicate HN in database\"\r\n            # next_service += URI.escape(params.collect{|k,v| \"\\#{k}=\\#{v}\"}.join(\'&\')).html_safe\r\n            err = true\r\n        else\r\n            # msg = \"Success\"\r\n            # next_service = \"../Setting/index\"\r\n            patient = @patient_model.create p\r\n            # if params[:record][:height] != \"\" and params[:record][:weight] != \"\"\r\n                # patient.update_attributes :height=>params[:record][:height], :weight=>params[:record][:weight], :bmi=>params[:record][:bmi]\r\n            # end\r\n            next_service = \'../Home/patient_record?id=\' + patient.id\r\n          \r\n            if params[:record][:provider]\r\n                m_pm_record = @module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>params[:record][:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\#{@current_project.name}#provider\", :module_id=>params[:record][:provider]\r\n            end\r\n            \r\n            msg = \"Patient created\"\r\n        end\r\n      \r\n    #   return_url += \'&obj_id=\'+patient.id.to_s\r\n      %>\r\n      <%#params.inspect %>\r\n      <div class=\"alert <%= err ? \"alert-error\" : \"alert-success\" %>\"><%= msg %></div>\r\n      <% if false %>\r\n      <pre><%# patient.inspect %></pre>\r\n      <pre><%# params.inspect %></pre>\r\n      <pre><%#  params[:record][:height].empty? %></pre>\r\n      <% end %>\r\n      <meta http-equiv=\"refresh\" content=\"0; url=<%=next_service%>\" />\r\n      <%\r\n    else\r\n%>\r\n<%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%= f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n<%= f.hidden_field :date, :value=>params[:data][:date] %>\r\n<div class=\"w-box\">\r\n<!--<div id=\"132-F1376173358\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">-->\r\n<div class=\"form-horizontal well\">\r\n<!--<b>Personal Information</b>-->\r\n<p class=\"f_legend\">Patient Information</p>\r\n<!--</div>-->\r\n\r\n<div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;margin: 0 0.5em 0.5em 0;float:left;width:140px;min-height:30px;\">\r\n<!--<span class=\"\"><label>Hospital Number <span class=\"f_req\">*</span>  : </label></span>	-->\r\n<!--<input type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"><span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[hn]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n    <span class=\"\"><label>Hospital Number (HN) : </label></span>\r\n    <input type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:140px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n<%\r\n    model = get_model\r\n    \r\n    r_prov = model[:provider].find(params[:data][:provider])\r\n    main_hospital = r_prov[:main_hospital] if r_prov[:main_hospital]\r\n    part_time_hospital = r_prov[:part_time_hospital].split(\'|\') if r_prov[:part_time_hospital]\r\n    \r\n    main_hospital = \'\' unless main_hospital\r\n    part_time_hospital = [] unless part_time_hospital\r\n    \r\n    list_hospital = []\r\n    if main_hospital != \'\' and !main_hospital.nil?\r\n        list_hospital.push(main_hospital)\r\n    end\r\n    if !part_time_hospital.empty?\r\n        list_hospital += part_time_hospital\r\n    end\r\n%>\r\n<div id=\"hospital_name\" class=\"  portlet \" style=\"border:0px solid blue;width:260px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Hospital Name : </label></span>	\r\n    <select name=\"record[hospital_name]\" id=\"data-hospital_name\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n<%\r\n    @map_hospital.each do |k,v|\r\n        sel = \"\"\r\n        if k == main_hospital\r\n            sel = \' selected=\"selected\"\'\r\n        end\r\n        if list_hospital.include? k or list_hospital.empty?\r\n%>\r\n        <option value=\"<%=k%>\"<%=sel.html_safe%>><%=v%></option>\r\n<%\r\n        end\r\n    end\r\n%>\r\n    </select>\r\n</div>\r\n\r\n<div class=\"row-fluid\"></div>\r\n\r\n<div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;margin: 0 0.5em 0.5em 0;float:left;width:240px;min-height:30px;\">\r\n    <span class=\"\"><label>Public ID (เลขที่บัตรประชาชน) : </label></span>	\r\n    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Prefix name : </label></span>	\r\n    <select name=\"record[prefix_name]\" id=\"data-prefix_name\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n        <option value=\"นาย\">นาย</option>\r\n        <option value=\"นาง\">นาง</option>\r\n        <option value=\"นางสาว\">นางสาว</option>\r\n    </select>\r\n</div>\r\n\r\n<div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\">\r\n    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n</div>\r\n\r\n<div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\">\r\n    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<div id=\"height\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Height (cm.) : </label></span>	\r\n    <input type=\"text\" name=\"record[height]\" id=\"data-height\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div id=\"weight\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>Weight (kg.) : </label></span>	\r\n    <input type=\"text\" name=\"record[weight]\" id=\"data-weight\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div id=\"bmi\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n    <span class=\"\"><label>BMI : </label></span>	\r\n    <input type=\"text\" name=\"record[bmi]\" id=\"data-bmi\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Birth date (dd/mm/yyyy) : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n\r\n<span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\"><input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"2015-03-08 20:44:27 +0700\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n<script>\r\n	$(\"#data-birth_date\").kendoDatePicker({\r\n		value: \'<%= Time.now.strftime(\'%d/%m/%Y\')%>\',\r\n	});\r\n</script>\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n<span class=\"\"><label>Gender : </label></span>	\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n\r\n<select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;background:#eee;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\"><option value=\"\">&nbsp;</option>\r\n<option value=\"1\">Male</option>\r\n<option value=\"2\">Female</option>\r\n<option value=\"0\">NA</option>\r\n</select>\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<%= hidden_field_tag :return, params[:return] %>\r\n<%= f.submit \'Submit\', :class=>\'btn\' %>\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n<script>\r\n    function bmi_update() {\r\n        // txt = $(this).val();\r\n        // num = isNaN(parseInt(txt)) ? 0 : parseInt(txt);\r\n        \r\n        h = isNaN(parseFloat($(\'#data-height\').val())) ? 0 : parseFloat($(\'#data-height\').val());\r\n        w = isNaN(parseFloat($(\'#data-weight\').val())) ? 0 : parseFloat($(\'#data-weight\').val());\r\n        \r\n        h = h/100;\r\n        bmi = 0\r\n        if (h != 0) {\r\n            bmi = w / (h * h)\r\n            $(\'#data-bmi\').val(bmi.toFixed(2));\r\n            // console.log(\'BMI = \' + bmi)\r\n        }\r\n        // console.log(\'bmi_update h(\' + h + \'), w(\' + w + \')\');\r\n    }\r\n\r\n    $(document).ready(function(){\r\n        // console.log(\'ready\');\r\n        \r\n        $(\'#data-bmi\').val(\'0.00\');\r\n        \r\n        $(\'#data-height\').change(bmi_update);\r\n        $(\'#data-weight\').change(bmi_update);\r\n        // console.log(\'finish\');\r\n    });\r\n</script>',NULL,NULL,NULL,'2017-06-01 08:09:12','2017-06-01 08:09:12','create_ole',''),(3036,'auto_logout',1208,2,'<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% 12px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n</style>\r\n\r\n<%= render :inline=>this.init %>\r\n<%\r\n    msg = []\r\n    tmp = nil\r\n    suc_msg = nil\r\n    \r\n    if request.post?\r\n        if !params[:account].nil?\r\n            if params[:account][:login_name].empty?\r\n                msg.push(\'Invalid login name\')\r\n            end\r\n            if params[:account][:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if params[:account][:password].empty?\r\n                msg.push(\'No password found\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>params[:account][:login_name]).first\r\n                if m_user\r\n                    msg.push(\'Existing login name\')\r\n                else\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(params[:account][:password], salt)\r\n                    tmp = salt + \'...\' + hashed_password\r\n                    m_user = @ehr_models[:user].create :role=>params[:account][:role], :login=>params[:account][:login_name], :salt=>salt, :hashed_password=>hashed_password, :email=>params[:account][:email], :name=>params[:account][:full_name], :activate=>\"true\"\r\n                    tmp = m_user.id.to_s\r\n                    \r\n                    m_provider = @models[:provider].create :group=>\'default\', :name=>params[:account][:full_name], :login=>params[:account][:login_name], :provider_type=>\'1\'\r\n                    tmp += \'...\' + m_provider.id.to_s\r\n                end\r\n            end\r\n        elsif !params[:profile].nil?\r\n            px = params[:profile]\r\n            if px[:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if px[:cur_password].empty?\r\n                msg.push(\'No password to confirm your change\')\r\n            else\r\n                if px[:new_password] != px[:con_password]\r\n                    msg.push(\"Your confirm password not match the new password. Try again.\")\r\n                end\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>px[:login_name]).first\r\n                salt = m_user[:salt]\r\n                hashed_password = User.encrypt(px[:cur_password], salt)\r\n                if m_user[:hashed_password] == hashed_password\r\n                    if px[:con_password] == px[:new_password] and px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        suc_msg= \"<strong>Success</strong> Your profile has been change\".html_safe\r\n                    elsif px[:con_password] == px[:new_password] and !px[:new_password].empty?\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        salt = User.random_string(10) \r\n                        hashed_password = User.encrypt(px[:new_password], salt)\r\n                        m_user[:hashed_password] = hashed_password\r\n                        m_user[:salt] = salt\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your profile and password has been change\".html_safe\r\n                    else\r\n                        msg.push(\'Your new and confirm password does not match\')\r\n                    end\r\n                    \r\n                else\r\n                    msg.push(\'Your current password does not match\')\r\n                end\r\n                # msg.push(px[:login_name])\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n<%#list.inspect%>\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                Setting\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                            <div id=\"accordion1\" class=\"accordion\">\r\n<%\r\n    # check admin or developer role\r\n    if @current_role == \'admin\' or @current_role == \'developer\'\r\n        usr = @ehr_models[:user].all.collect do |i|\r\n            role = @ehr_models[:role].find(i.role)\r\n            role_name = \'undefined\'\r\n            if role\r\n                role_name = role[:name]\r\n            end\r\n            provider = @models[:provider].where(:login=>i.login).first\r\n            \r\n            if provider\r\n                {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :i=>i}\r\n            end\r\n        end\r\n%>\r\n<%\r\n    if !msg.empty?\r\n        for m in msg do\r\n%>\r\n                                <div class=\"alert alert-error\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= m %>\r\n    							</div>\r\n<%\r\n        end\r\n    elsif suc_msg\r\n%>\r\n                                <div class=\"alert alert-success\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= suc_msg %>\r\n    							</div>\r\n<%\r\n    end\r\n%>\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											Manage Account\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse\" id=\"collapseOne1\">\r\n										<div class=\"accordion-inner\">\r\n										    <!--<div id=\"form-panel\" class=\"row-fluid\"><%= link_to \'Add New\', \'add_new?update=form-panel\', :remote=>true, :class=>\'btn\', :style=>\'float:right\' %>-->\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :account, :url=>\"index\", :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Add New Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">no space, special characters</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'member\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:class=>\'btn\', :style=>\'vertical-align: top;\' %></span>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n											<!--<hr/>-->\r\n                                            <div id=\"account\">\r\n											<table class=\"table\">\r\n        										<thead>\r\n        											<tr>\r\n        												<th>No.</th>\r\n        												<th>Login Name</th>\r\n        												<th>Name</th>\r\n        												<th>Role</th>\r\n        												<th>Actions</th>\r\n        											</tr>\r\n        										</thead>\r\n        										<tbody>\r\n        										<% \r\n        										    no = 1\r\n        										    for i in usr.compact do\r\n        										\r\n        										%>\r\n        										    <tr>\r\n        										        <td><%= no %>.</td>\r\n        										        <td><%= i[:login] %></td>\r\n        										        <td><%= i[:provider_name] %></td>\r\n        										        <td><%= i[:role_name] %></td>\r\n        										        <td>\r\n        										            <%= link_to \'\', \'#\', :title=>\'Delete Account\', :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\#{i[:id]}\', \'\\#{i[:provider_id]}\')\" %>&nbsp;&nbsp;&nbsp;\r\n        										            <%= link_to \'\', \'#\', :title=>\'Edit Account\', :class=>\'splashy-contact_blue_edit\', :onclick=>\"javascript:confirm_edit(\'\\#{i[:id]}\', \'\\#{i[:provider_id]}\')\" %>\r\n        										        </td>\r\n        										    </tr>\r\n        										<%\r\n        										    no += 1\r\n        										    end\r\n        										%>\r\n        										</tbody>\r\n        									</table>\r\n										</div>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n<%\r\n    end\r\n%>\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n											User Profile\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse in\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :profile, :class=>\'\', :url=>\"index\" ,:method=>\'POST\' do |f| %>\r\n											<%\r\n											    cur_user = @ehr_models[:user].where(:login=>@current_user.to_s).first\r\n											%>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your information</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\', :value=>@current_user, :disabled=>\'disabled\' %>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\', :value=>cur_user[:name] if cur_user %> \r\n        													<span class=\"help-block\">your account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Password\" class=\"span10\" name=\"[profile]cur_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your information</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Password\" class=\"span10\" name=\"[profile]new_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Password\" class=\"span10\" name=\"[profile]con_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n										</div>\r\n									</div>\r\n								</div>\r\n							</div>\r\n                        \r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<br/>\r\n\r\n<script>\r\n    refresh();\r\n    \r\n    function confirm_delete(uid, pid) {\r\n        if (confirm(\'Are you sure?\') == true) {\r\n<%\r\n            destroy_url = \'destroy?id=\'\r\n%>\r\n            \r\n            url = \"destroy?uid=\" + uid + \"&pid=\" + pid;\r\n            window.location = url;\r\n        }\r\n    }\r\n    \r\n    function confirm_edit(uid, pid) {\r\n        // if (alert(\'Are you sure?\') == true) {\r\n            \r\n        // }\r\n        \r\n    }\r\n\r\n\r\n// // idle.js (c) Alexios Chouchoulas 2009\r\n// // Released under the terms of the GNU Public License version 2.0 (or later).\r\n\r\n// var _API_JQUERY = 1;\r\n// var _API_PROTOTYPE = 2;\r\n// var _api;\r\n\r\n// // var _idleTimeout = 30000;       // 30 seconds\r\n// // var _awayTimeout = 600000;      // 10 minutes\r\n// var _idleTimeout = 10000;   // 10 seconds\r\n// var _awayTimeout = 20000;   // 20s\r\n\r\n// var _idleNow = false;\r\n// var _idleTimestamp = null;\r\n// var _idleTimer = null;\r\n// var _awayNow = false;\r\n// var _awayTimestamp = null;\r\n// var _awayTimer = null;\r\n\r\n// function setIdleTimeout(ms)\r\n// {\r\n//     _idleTimeout = ms;\r\n//     _idleTimestamp = new Date().getTime() + ms;\r\n//     if (_idleTimer != null) {\r\n//         clearTimeout (_idleTimer);\r\n//     }\r\n//     _idleTimer = setTimeout(_makeIdle, ms + 50);\r\n//     //console.log(\'idle in \' + ms + \', tid = \' + _idleTimer);\r\n// }\r\n\r\n// function setAwayTimeo