.create :role=>role, :login=>user, :salt=>salt, :hashed_password=>hashed_password, :email=>email, :name=>i[\'name\'], :activate=>\"true\"\r\n                m_provider = @models[:provider].create :group=>\'default\', :name=>i[\'name\'], :login=>user, :provider_type=>i[\'provider_type\'], :prefix=>i[\'prefix\'].strip, :first_name=>i[\'first_name\'].strip, :last_name=>i[\'last_name\'].strip, :license_number=>i[\'license\']\r\n                \r\n                res << [user, pass]\r\n                \r\n                # ad = i[\'date\'].split(\'/\')\r\n                # ad[2] = (ad[2].to_i - 543).to_s\r\n                # # i[\'date\'] = \'xxx\'\r\n                # i[\'date\'] = Time.strptime(ad.join(\'/\'), \'%d/%m/%Y\')\r\n                # # i[\'date\'] = ad[2] + \'-\' + ad[1] + \'-\' + ad[0]\r\n                # i[\'start\'] = Time.parse(i[\'start\'], i[\'date\'])\r\n                # i[\'end\'] = Time.parse(i[\'end\'], i[\'date\'])\r\n                \r\n                # note = nil\r\n                # if i[\'birth_date\'].nil?\r\n                #     i[\'birth_date\'] = 55\r\n                #     note = \'uncorrect-age\'\r\n                # end\r\n                \r\n                #     if i[\'birth_date\'].length <= 2\r\n                #         cur_year = Time.now.year\r\n                #         dif_year = cur_year - i[\'birth_date\'].to_i\r\n                #         i[\'birth_date\'] = \"01/01/\" + dif_year.to_s\r\n                #     elsif i[\'birth_date\'].split(\'/\')[2].to_i > Time.now.year\r\n                #         dob = i[\'birth_date\'].split(\'/\')\r\n                #         yyyy = dob[2].to_i - 543\r\n                #         i[\'birth_date\'] = dob.join(\'/\')\r\n                #     end\r\n                \r\n                # pat = {}\r\n                # pat_fields.each do |j|\r\n                #     pat[j] = i[j]\r\n                # end\r\n                \r\n                # app = {}\r\n                # app_fields.each do |j|\r\n                #     app[j] = i[j]\r\n                # end\r\n                # app[\'provider\'] = b[:provider]\r\n                # app[\'procedure\'] = b[:procedure]\r\n                # app[\'visit_type\'] = b[:visit_type]\r\n                # app[\'indication\'] = b[:indication]\r\n                # app[\'status\'] = \'Appointed\'\r\n                # app[\'note\'] = i[\'note\']\r\n                # if note\r\n                #     app[\'note\'] += \"/\\#{note}\"\r\n                # end\r\n                \r\n                # r_app = @m_app.create app\r\n                # r_pat = @m_pat.create pat\r\n                # r_pat_mod = @m_pat_mod.create :ref_number=>\'0000\', :patient_id=>r_pat.id, :module_name=>\"\\#{@current_project.name}#appointment\", :module_id=>r_app.id, :date=>i[\'date\'], :time=>i[\'start\']\r\n                \r\n                # res << [r_pat,r_app,r_pat_mod]\r\n                # res << [i[\'hn\'], i[\'start\']]\r\n                # res << i\r\n            end\r\n            # res << \'xxx\'\r\n        end\r\n    end\r\n%>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting > Batch Registration</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n\r\n\r\n<%= form_for :batch, :url=>params[:opt], :html=>{:multipart=>true}  do |f| %>\r\n                <%= f.file_field :file, :accept => \"text/csv\" %>  \r\n                <div class=\'row-fluid\'></div>\r\n                <%=f.submit \'Submit\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %> \r\n<% end %>\r\n\r\n<div class=\'alert alert-info\'>\r\n<% if res.empty? %>\r\n<b>Header</b> : <%= ff.join(\',\') %>\r\n<% else %>\r\n    <%= res.join(\'<br/>\').html_safe %>\r\n<% end %>\r\n        \r\n</div>\r\n\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>',NULL,NULL,NULL,'2017-06-01 08:10:21','2017-06-01 08:10:21','batch_register',''),(3038,'index',1208,2,'<style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    v{color:#00f}\r\n\r\n    .accordion-toggle:hover {\r\n      background-color: #e5e5e5;\r\n      text-decoration: none;\r\n    }\r\n    .accordion-toggle {\r\n      background-color: #f5f5f5;\r\n      color: #222;\r\n      text-decoration: none;\r\n      background-image: url(/gebo/img/acc_icons.png);\r\n      background-position: 98% -34px;\r\n      background-repeat: no-repeat;\r\n    }\r\n    .collapsed {\r\n        background-position: 98% 12px;\r\n    }\r\n    .well {\r\n      min-height: 20px;\r\n      padding: 19px;\r\n      margin-bottom: 20px;\r\n      background-color: #f5f5f5;\r\n      border: 1px solid #eee;\r\n      border: 1px solid rgba(0,0,0,0.05);\r\n      border-radius: 4px;\r\n      box-shadow: inset 0 1px 1px rgba(0,0,0,0.05);\r\n    }\r\n</style>\r\n    <!-- nice form elements -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/uniform/Aristo/uniform.aristo.css\" />\r\n	<!-- 2col multiselect -->\r\n    <link rel=\"stylesheet\" href=\"/gebo/lib/multiselect/css/multi-select.css\" />\r\n\r\n<%= render :inline=>this.init %>\r\n\r\n<%\r\n    msg = []\r\n    tmp = nil\r\n    suc_msg = nil\r\n    \r\n    if request.post?\r\n        if !params[:account].nil? and !params[:add_new].nil?\r\n            pa = params[:account]\r\n            fname = \"\\\\#{pa[:prefix]}\\\\#{pa[:first_name]} \\\\#{pa[:last_name]}\"\r\n            \r\n            if params[:account][:login_name].nil?\r\n                msg.push(\'Invalid login name\')\r\n            end\r\n            if fname.strip == \'\'\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if params[:account][:password].nil?\r\n                msg.push(\'No password found\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>params[:account][:login_name]).first\r\n                if m_user\r\n                    msg.push(\'Existing login name\')\r\n                else\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(params[:account][:password], salt)\r\n                    tmp = salt + \'...\' + hashed_password\r\n                    m_user = @ehr_models[:user].create :role=>params[:account][:role], :login=>params[:account][:login_name], :salt=>salt, :hashed_password=>hashed_password, :email=>params[:account][:email], :name=>params[:account][:full_name], :activate=>\"true\"\r\n                    tmp = m_user.id.to_s\r\n                    \r\n                    m_provider = @models[:provider].create :group=>\'default\', :name=>fname, :login=>pa[:login_name], :provider_type=>pa[:provider_type], :prefix=>pa[:prefix], :first_name=>pa[:first_name], :last_name=>pa[:last_name], :license_number=>pa[:license_number], :main_hospital=>pa[:main_hospital]\r\n                    tmp += \'...\' + m_provider.id.to_s\r\n                end\r\n            end\r\n        elsif !params[:account].nil? and !params[:update].nil?\r\n            acc = params[:account]\r\n            \r\n            full_name = acc[:prefix].strip + acc[:first_name].strip + \" \" + acc[:last_name].strip\r\n            full_name = full_name.strip\r\n            if full_name == \'\'\r\n                msg.push(\'Invalid name, Please fill the doctor name.\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>acc[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>acc[:login_name]).first\r\n                \r\n                m_prov[:name] = full_name\r\n                m_prov[:prefix] = acc[:prefix]\r\n                m_prov[:first_name] = acc[:first_name]\r\n                m_prov[:last_name] = acc[:last_name]\r\n                m_prov[:provider_type] = acc[:provider_type]\r\n                m_prov[:license_number] = acc[:license_number]\r\n                m_prov[:main_hospital]  = acc[:main_hospital]\r\n                m_prov.save\r\n                \r\n                suc_msg= \"<b>Success</b> Account <b>\\\\#{acc[:login_name]}</b> has been updated\".html_safe\r\n                \r\n                if acc[:password].strip != \'\'\r\n                    salt = User.random_string(10) \r\n                    hashed_password = User.encrypt(acc[:password], salt)\r\n                    m_user[:hashed_password] = hashed_password\r\n                    m_user[:salt] = salt\r\n                    # m_user.save\r\n                    suc_msg= \"<strong>Success</strong> Account <b>\\\\#{acc[:login_name]}</b> profile and password has been updated\".html_safe\r\n                end\r\n                \r\n                m_user[:name] = full_name\r\n                m_user[:email] = acc[:email]\r\n                m_user[:role] = acc[:role]\r\n                m_user.save\r\n            end\r\n        elsif px = params[:public_pass]\r\n            m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n\r\n            pri = px[:pri_password]\r\n            if pri == m_user[:pin]\r\n                pub = px[:pub_password]\r\n                \r\n                salt = User.random_string(10) \r\n                hashed_password = User.encrypt(px[:pub_password], salt)\r\n                m_user[:hashed_password] = hashed_password\r\n                m_user[:salt] = salt\r\n                m_user.save\r\n                suc_msg= \"<strong>Success</strong> Your public password has been change\".html_safe\r\n            else\r\n                msg.push(\'Invalid private password\')\r\n            end\r\n            \r\n        elsif px = params[:private_pass]\r\n            new_pri = px[:new_private]\r\n            con_pri = px[:con_private]\r\n            \r\n            cur_pri = px[:cur_private]\r\n            \r\n            if new_pri != con_pri\r\n                msg.push(\'Your new and confirm password does not match\')\r\n            end\r\n        \r\n            m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n            \r\n            if msg.empty?\r\n                if !m_user[:pin].nil?\r\n                    if cur_pri == m_user[:pin] and new_pri == con_pri\r\n                        m_user[:pin] = new_pri\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your private password has been change\".html_safe\r\n                        \r\n                        session[:pin] = new_pri\r\n                    else\r\n                        msg.push(\'Invalid current private password\')\r\n                    end\r\n                else\r\n                    if new_pri == con_pri\r\n                        m_user[:pin] = new_pri\r\n                        m_user.save\r\n                        suc_msg= \"<strong>Success</strong> Your private password has been update\".html_safe\r\n                        \r\n                        session[:pin] = new_pri\r\n                    end\r\n                end\r\n            end\r\n        elsif !params[:profile].nil?\r\n            px = params[:profile]\r\n            if px[:full_name].empty?\r\n                msg.push(\'Invalid full name\')\r\n            end\r\n            if px[:confirm_private].empty?\r\n                msg.push(\'No password to confirm your change\')\r\n            end\r\n            \r\n            if msg.empty?\r\n                m_user = @ehr_models[:user].where(:login=>px[:login_name]).first\r\n                m_prov = @models[:provider].where(:login=>px[:login_name]).first\r\n                # salt = m_user[:salt]\r\n                # hashed_password = User.encrypt(px[:cur_password], salt)\r\n                \r\n                pin = px[:confirm_private]\r\n                \r\n                # if m_user[:hashed_password] == hashed_password\r\n                if m_user[:pin] == pin\r\n                        if m_prov[:name] != px[:full_name]\r\n                            m_prov[:name] = px[:full_name]\r\n                            m_prov[:main_hospital] = px[:main_hospital]\r\n                            m_prov[:part_time_hospital] = px[:part_time_hospital].join(\'|\') if !px[:part_time_hospital].nil?\r\n                            # m_prov.update_attributes(:main_hospital=>px[:main_hospital],:name=>px[:full_name],:part_time_hospital=>px[:part_time_hospital])\r\n                            m_prov.save\r\n                            m_user[:name] = px[:full_name]\r\n                            m_user.save\r\n                        end\r\n                        if m_prov[:main_hospital] != px[:main_hospital]\r\n                            m_prov[:main_hospital] = px[:main_hospital]\r\n                            m_prov.save\r\n                        end\r\n                        suc_msg= \"<strong>Success</strong> Your profile has been change\".html_safe\r\n                        \r\n                    # if px[:con_password] == px[:new_password] and px[:new_password].empty?\r\n                    #     if m_prov[:name] != px[:full_name]\r\n                    #         m_prov[:name] = px[:full_name]\r\n                    #         m_prov[:main_hospital] = px[:main_hospital]\r\n                    #         m_prov[:part_time_hospital] = px[:part_time_hospital].join(\'|\') if !px[:part_time_hospital].nil?\r\n                    #         # m_prov.update_attributes(:main_hospital=>px[:main_hospital],:name=>px[:full_name],:part_time_hospital=>px[:part_time_hospital])\r\n                    #         m_prov.save\r\n                    #         m_user[:name] = px[:full_name]\r\n                    #         m_user.save\r\n                    #     end\r\n                    #     suc_msg= \"<strong>Success</strong> Your profile has been change\".html_safe\r\n                    # elsif px[:con_password] == px[:new_password] and !px[:new_password].empty?\r\n                    #     if m_prov[:name] != px[:full_name]\r\n                    #         m_prov[:name] = px[:full_name]\r\n                    #         m_prov[:main_hospital] = px[:main_hospital]\r\n                    #         m_prov[:part_time_hospital] = px[:part_time_hospital].join(\'|\') if !px[:part_time_hospital].nil?\r\n                    #         # m_prov.update_attributes(:main_hospital=>px[:main_hospital],:name=>px[:full_name],:part_time_hospital=>px[:part_time_hospital])\r\n                    #         m_prov.save\r\n                    #         m_user[:name] = px[:full_name]\r\n                    #         m_user.save\r\n                    #     end\r\n                    #     salt = User.random_string(10) \r\n                    #     hashed_password = User.encrypt(px[:new_password], salt)\r\n                    #     m_user[:hashed_password] = hashed_password\r\n                    #     m_user[:salt] = salt\r\n                    #     m_user.save\r\n                    #     suc_msg= \"<strong>Success</strong> Your profile and password has been change\".html_safe\r\n                    # else\r\n                    #     msg.push(\'Your new and confirm password does not match\')\r\n                    # end\r\n                    \r\n                else\r\n                    msg.push(\'Your current password does not match\')\r\n                end\r\n                # msg.push(px[:login_name])\r\n            end\r\n        end\r\n    end\r\n%>\r\n\r\n<%#list.inspect%>\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>Setting</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n<%\r\nif @current_role==\'developer\'\r\n%>\r\n<%= link_to \'Batch User\', \'batch_register\', :target=>\'_blank\' %>\r\n<%\r\nend\r\n%>\r\n                <div style=\"border:0px solid\">\r\n                    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:800px\">\r\n                            <div id=\"accordion1\" class=\"accordion\">\r\n\r\n<%\r\n    if !msg.empty?\r\n        for m in msg do\r\n%>\r\n                                <div class=\"alert alert-error\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= m %>\r\n    							</div>\r\n<%\r\n        end\r\n    elsif suc_msg\r\n%>\r\n                                <div class=\"alert alert-success\">\r\n    								<a class=\"close\" data-dismiss=\"alert\">×</a>\r\n    								<%= suc_msg %>\r\n    							</div>\r\n<%\r\n    end\r\n%>\r\n\r\n<%\r\n    # check admin or developer role\r\n    if (@current_role == \'admin\' and session[:owner]) or @current_role == \'developer\'\r\n        usr = @ehr_models[:user].all.collect do |i|\r\n            role = @ehr_models[:role].find(i.role)\r\n            role_name = \'undefined\'\r\n            if role\r\n                role_name = role[:name]\r\n            end\r\n            provider = @models[:provider].where(:login=>i.login).first\r\n            \r\n            if provider\r\n                {:id=>i.id, :login=>i.login, :email=>i.email, :role_id=>i.role, :role_name=>role_name, :provider_id=>provider.id, :provider_name=>provider.name, :license=>provider[:license_number], :i=>i}\r\n            end\r\n        end\r\n%>\r\n\r\n<% \r\n        m_hos = @models[:hospital]\r\n        m_com = @models[:implant_company]\r\n        m_imp = @models[:implant_profile]\r\n        \r\n        c_hos = m_hos.all.count\r\n        c_com = m_com.all.count\r\n        c_imp = m_imp.all.count\r\n%>\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#admin-control\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Admin Control\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse\" id=\"admin-control\">\r\n										<div class=\"accordion-inner\">\r\n										    <ul class=\"dshb_icoNav tac\">\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/first-aid.png)\" href=\"../Hospital/index\">\r\n										                <span class=\"label label-success\"><%= c_hos > 100 ? \"+100\" : c_hos.to_s %></span> Hospital</a></li>\r\n										        <li><a style=\"background-image: url(/gebo/img/gCons/home.png)\" href=\"../ImplantCompany/index\">\r\n										                <span class=\"label label-important\"><%= c_com > 100 ? \"+100\" : c_com.to_s %></span> Company</a></li>\r\n										        <li><a style=\"font-size:0.8em;background-image: url(/gebo/img/gCons/home.png)\" href=\"../ImplantCompany/index\">\r\n										                <span class=\"label label-info\"><%= @models[:implant_company].all.count.to_s %></span> Implant Company</a></li>\r\n										                <br/>\r\n										        <li><a href=\"../ImplantProfile/index\">Implant Profile</a></li>\r\n										        <li><a style=\'font-size:0.7em;\' href=\"../ImplantComponent/index\">Implant Component</a></li>\r\n										        <li><a href=\"../ImplantType/index\">Implant Type</a></li>\r\n										        <li><a href=\"../ImplantMaterial/index\">Implant Material</a></li>\r\n										    </ul>\r\n										    <!--\r\n										    <ul class=\"dshb_icoNav tac\">\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/multi-agents.png)\" href=\"javascript:void(0)\"><span class=\"label label-info\">+10</span> Users</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/world.png)\" href=\"javascript:void(0)\">Map</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/configuration.png)\" href=\"javascript:void(0)\">Settings</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/lab.png)\" href=\"javascript:void(0)\">Lab</a>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/van.png)\" href=\"javascript:void(0)\"><span class=\"label label-success\">$2851</span> Delivery</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/pie-chart.png)\" href=\"javascript:void(0)\">Charts</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/edit.png)\" href=\"javascript:void(0)\">Add New Article</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/add-item.png)\" href=\"javascript:void(0)\"> Add New Page</a></li>\r\n                								<li><a style=\"background-image: url(/gebo/img/gCons/chat-.png)\" href=\"javascript:void(0)\"><span class=\"label label-important\">26</span> Comments</a></li>\r\n                							</ul>\r\n                							-->\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n\r\n                                <div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseOne1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											Manage Account\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseOne1\">-->\r\n									<div class=\"accordion-body collapse\" id=\"collapseOne1\">\r\n										<div class=\"accordion-inner\">\r\n										    <!--<div id=\"form-panel\" class=\"row-fluid\"><%= link_to \'Add New\', \'add_new?update=form-panel\', :remote=>true, :class=>\'btn\', :style=>\'float:right\' %>-->\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :account, :url=>params[:opt], :method=>\'POST\' do |f| %>\r\n											    <fieldset>\r\n        											<p class=\"f_legend\">Add New Account</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Name</label>\r\n        												<div class=\"controls\">\r\n        												    <div class=\"row-fluid\">\r\n        												    <%= f.text_field :prefix, :class=>\'span2\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    <%= f.text_field :first_name, :class=>\'span4\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    <%= f.text_field :last_name, :class=>\'span4\', :style=>\'float:left;margin-right:15px\' %>\r\n        												    </div>\r\n        													<!--<input type=\"text\" name=\"name\" class=\"span10\">-->\r\n        													<span class=\"help-block span2\">prefix name</span>\r\n        													<span class=\"help-block span4\">first name</span>\r\n        													<span class=\"help-block span4\">last name</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">License Number</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :license_number, :class=>\'span2\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">doctor license number</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">no space, special characters</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Public Password</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.password_field :password, :class=>\'span10\' %>\r\n        													<!--<input type=\"password\" name=\"password\" class=\"span10\">-->\r\n        													<span class=\"help-block\">account password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Main Hospital</label>\r\n        												<div class=\"controls\">\r\n        												\r\n        												    <input type=\"text\" name=\"account[main_hospital]\" id=\"data-main_hospital\" size=\"29\" style=\"margin-top:-2px;vertical-align:text-top;display:blockwidth:140px;width:250px\" class=\"k-textbox k-textbox-txt span10\">\r\n<script>\r\n<%\r\n    a_hosp = get_model[:hospital].all.collect{|i| {:text=>i[:hospital_name_thai], :value=>i.id.to_s}}    \r\n%>\r\n    var ds_hosp = <%= a_hosp.to_json.html_safe %>\r\n    $(document).ready(function() {\r\n            $(\"#data-main_hospital\").kendoComboBox({\r\n                dataTextField: \"text\",\r\n                dataValueField: \"value\",\r\n                filter: \"contains\",\r\n                dataSource: ds_hosp,\r\n                change: function(e) {\r\n                    var widget = e.sender;\r\n        \r\n                    if (widget.value() && widget.select() === -1) {\r\n                      //custom has been selected\r\n                      widget.value(\"\"); //reset widget\r\n                    }\r\n                }\r\n            });\r\n            $(\'input[name=\"account[main_hospital]_input\"]\').css(\'height\', \'\');\r\n<%\r\n    # if main_hospital\r\n    if false\r\n%>\r\n            var cb = $(\"#data-main_hospital\").data(\"kendoComboBox\");\r\n            cb.value(\'<%= main_hospital %>\');\r\n<%\r\n    end\r\n%>\r\n    });\r\n</script> \r\n        												\r\n        												<% if false %>\r\n        													<select name=\"account[main_hospital]\" id=\"account_main_hospital\">\r\n        													    <option value=\"\" selected disable>--- Please select hospital ---</option>\r\n        											    <% \r\n        											        for i in get_model[:hospital] do \r\n        											            s = nil\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i[:hospital_name_thai]%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        											    <% end %>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">E-Mail</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :email, :class=>\'span10\' %>\r\n        													<!--<input type=\"text\" name=\"login_name\" class=\"span10\">-->\r\n        													<span class=\"help-block\">email account</span>\r\n        												</div>\r\n        											</div>\r\n        											<!--\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%# f.text_field :full_name, :class=>\'span10\' %>\r\n        													<span class=\"help-block\">account name</span>\r\n        												</div>\r\n        											</div>\r\n        											-->\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Account Role</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[role]\" id=\"account_role\">\r\n        											    <% \r\n        											        for i in @ehr_models[:role].all do \r\n        											            s = nil\r\n        											            if i.name == \'user\'\r\n        											                s = \'selected\'\r\n        											            end\r\n        											    %>\r\n                                                                <option value=\"<%=i.id%>\" <%= s if s %>><%=i.name%></option>\r\n                                                        <%\r\n        											        end \r\n        											    %>\r\n        											        </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Account Type</label>\r\n        												<div class=\"controls\">\r\n        												    <select name=\"account[provider_type]\" id=\"provider_type\">\r\n                                                                <option value=\"\"></option>\r\n                                                                <option value=\"1\">Doctor\r\n                                                                </option>\r\n                                                                <option value=\"4\">Fellow Doctor\r\n                                                                </option>\r\n                                                                <option value=\"2\">Nurse\r\n                                                                </option>\r\n                                                                <option value=\"3\">Assistant\r\n                                                                </option>\r\n                                                            </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<%=f.submit \'Add New\',:id=>\'data-add_new\', :name=>\'add_new\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;\' %> \r\n        													<%=f.submit \'Update\',:id=>\'data-update\', :name=>\'update\', :class=>\'btn btn-success\', :style=>\'vertical-align: top;display:none\' %> \r\n        													<%=link_to \'Cancel\', \'#\', :id=>\'data-cancel\', :class=>\'btn\', :style=>\'display:none\', :onclick=>\"javascript:cancel()\" %>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n											<!--<hr/>-->\r\n                                            <div id=\"account\">\r\n											<table class=\"table\">\r\n        										<thead>\r\n        											<tr>\r\n        												<th>No.</th>\r\n        												<th>Login Name</th>\r\n        												<th>Name</th>\r\n        												<th>License</th>\r\n        												<th>Role</th>\r\n        												<th>Actions</th>\r\n        											</tr>\r\n        										</thead>\r\n        										<tbody>\r\n        										<% \r\n        										    no = 1\r\n        										    for i in usr.compact do\r\n        										\r\n        										%>\r\n        										    <tr>\r\n        										        <td><%= no %>.</td>\r\n        										        <td><%= i[:login] %></td>\r\n        										        <td><%= i[:provider_name] %></td>\r\n        										        <td><%= (i[:license].nil? or i[:license]==\'\') ? \'-\' : i[:license] %></td>\r\n        										        <td><%= i[:role_name] %></td>\r\n        										        <td>\r\n        										            <%= link_to \'\', \'#\', :title=>\'Delete Account\', :class=>\'splashy-contact_blue_remove\', :onclick=>\"javascript:confirm_delete(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>&nbsp;&nbsp;&nbsp;\r\n        										            <%= link_to \'\', \'#\', :title=>\'Edit Account\', :class=>\'splashy-contact_blue_edit\', :onclick=>\"javascript:confirm_edit(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>&nbsp;&nbsp;&nbsp;\r\n\r\n<%= link_to \'\', \'#\', :title=>\'Reset Password\', :class=>\'splashy-contact_blue\', :onclick=>\"javascript:confirm_reset(\'\\\\#{i[:id]}\', \'\\\\#{i[:provider_id]}\')\" %>\r\n\r\n        										        </td>\r\n        										    </tr>\r\n        										<%\r\n        										    no += 1\r\n        										    end\r\n        										%>\r\n        										</tbody>\r\n        									</table>\r\n										</div>\r\n                                        </div>\r\n									</div>\r\n                                </div>\r\n<%\r\n    end\r\n%>\r\n\r\n											<%\r\n											    cur_user = @ehr_models[:user].where(:login=>@current_user.to_s).first\r\n											    cur_prov = @models[:provider].where(:login=>@current_user.to_s).first\r\n											%>\r\n											\r\n								<div class=\"accordion-group\">\r\n									<div class=\"accordion-heading\">\r\n									    <!--<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle \">-->\r\n										<a href=\"#collapseTwo1\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											User Profile\r\n										</a>\r\n									</div>\r\n									<!--<div class=\"accordion-body collapse in\" id=\"collapseTwo1\">-->\r\n									<div class=\"accordion-body collapse\" id=\"collapseTwo1\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :profile, :class=>\'\', :url=>params[:opt] ,:method=>\'POST\' do |f| %>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your information</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Login Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :login_name, :class=>\'span10\', :value=>@current_user, :disabled=>\'disabled\' %>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Full Name</label>\r\n        												<div class=\"controls\">\r\n        												    <%= f.text_field :full_name, :class=>\'span10\', :value=>cur_user[:name] if cur_user %> \r\n        													<span class=\"help-block\">your account name</span>\r\n        												</div>\r\n        											</div>\r\n        											<hr/>\r\n<%\r\n    main_hospital = cur_prov[:main_hospital] if cur_prov\r\n    part_time_hospital = cur_prov[:part_time_hospital] if cur_prov\r\n    part_time_hospital = [] unless part_time_hospital\r\n\r\n    m_hosp = get_model[:hospital]\r\n    \r\n    map_hospital = {}\r\n    map_hospital[\"\"] = \"Please select hospital\"\r\n    \r\n    map_region = {\r\n        \'1\'=>\'กรุงเทพ\',\r\n        \'2\'=>\'ปริมณฑล\',\r\n        \'3\'=>\'ภาคกลาง\',\r\n        \'4\'=>\'ภาคเหนือ\',\r\n        \'5\'=>\'ภาคใต้\',\r\n        \'6\'=>\'ภาคอิสาน\',\r\n        \'7\'=>\'ภาคตะวันออก\',\r\n        \'8\'=>\'ภาคตะวันตก\'}\r\n    map_reg_hosp = {}\r\n    \r\n    sel_txt = \"\"\r\n    a_hosp = m_hosp.all\r\n    for i in a_hosp do\r\n        map_hospital[i.id.to_s] = i[:hospital_name_thai]\r\n        if !map_reg_hosp.has_key? i[:region]\r\n            map_reg_hosp[i[:region]] = {}\r\n        end\r\n        # if i.id.to_s == main_hospital\r\n        #     next\r\n        # end\r\n        map_reg_hosp[i[:region]][i.id.to_s] = i[:hospital_name_thai]\r\n    end \r\n%>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Main Hospital</label>\r\n        												<div class=\"controls\">\r\n        												\r\n        												    <%# f.select :main_hospital, map_hospital, :selected => a_hosp.last[:hospital_name_thai], :class=>\'span10\' %>\r\n        												    <select name=\"profile[main_hospital]\" id=\"profile_main_hospital\" class=\"span10\">\r\n<%\r\n    map_hospital.each do |k,v|\r\n        sel = \'\'\r\n        if main_hospital.to_s == k.to_s\r\n            sel = \' selected=\"selected\"\'\r\n        end\r\n%>\r\n                                                                <option value=\"<%=k%>\"<%= sel %>><%=v%></option>\r\n<% \r\n    end\r\n%>\r\n        												    </select>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Part Time Hospital</label>\r\n        												<div class=\"controls\">\r\n        												    <%# f.select :main_hospital, map_hospital, :selected => a_hosp.last[:hospital_name_thai], :class=>\'span10\' %>\r\n        												    <select name=\"profile[part_time_hospital][]\" multiple=\"multiple\" class=\"multiselect\" >\r\n<%\r\n    opt_txt = \"\"\r\n    sel_txt = \"\"\r\n    list_part_time = part_time_hospital.split(\'|\')\r\n    # list_part_time = [\'55c5ba20790f9b1672000004\',\'55c4e3ed790f9b223e000002\']\r\n    map_reg_hosp.each do |k,v|\r\n        opt_txt += \"<optgroup label=\'\\\\#{map_region[k]}\'>\"\r\n        v.each do |x,y|\r\n            if list_part_time.include? x\r\n                # sel_txt += \"<li class=\'ms-elem-selected\' ms-value=\'\\\\#{x}\'>\\\\#{y}</li>\"\r\n                opt_txt += \"<option value=\'\\\\#{x}\' selected>\\\\#{y}</option>\"\r\n            else\r\n                opt_txt += \"<option value=\'\\\\#{x}\'>\\\\#{y}</option>\"\r\n            end\r\n        end\r\n        opt_txt += \"</optgroup>\"\r\n    end\r\n%>\r\n                                                                <%= opt_txt.html_safe %>\r\n        												    </select>\r\n        												    <a id=\"select_all\" href=\"javascript:void(0)\">Select All</a> / <a id=\"deselect_all\" href=\"javascript:void(0)\">Deselect All</a>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm Private</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Information using Private Password\" class=\"span10\" name=\"[profile]confirm_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your information</span>\r\n        												</div>\r\n        											</div>\r\n        											<!--\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Public Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Public Password\" class=\"span10\" name=\"[profile]pub_password\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">make change your public password</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Private Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Private Password\" class=\"span10\" name=\"[profile]pri_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm to change your public password</span>\r\n        												</div>\r\n        											</div>\r\n        											<hr/>\r\n        											<div class=\"control-group\">\r\n        											<%\r\n        											    ctrl = \'\'\r\n        											    if @current_role==\'developer\'\r\n        											        ctrl = \'disable\'\r\n        											    elsif cur_user[:pin].nil? or cur_user[:pin] == \'\'\r\n        											        ctrl = \'readonly\'\r\n        									            end\r\n        											%>\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Private Password\" class=\"span10\" name=\"[profile]cur_private\" <%= ctrl %>>\r\n        													<span class=\"help-block\">your private password</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Private Password\" class=\"span10\" name=\"[profile]new_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your private password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Private Password\" class=\"span10\" name=\"[profile]con_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new private password</span>\r\n        												</div>\r\n        											</div>\r\n        											-->\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n											<% end %>\r\n											</div>\r\n										</div>\r\n									</div>\r\n								</div>\r\n								\r\n								<div class=\"accordion-group\">	\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo3\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n										Public Password\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"collapseTwo3\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :public_pass, :class=>\'\', :url=>params[:opt] ,:method=>\'POST\' do |f| %>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n											\r\n        											<%\r\n        											    ctrl = \'\'\r\n        											    if @current_role==\'developer\'\r\n        											        ctrl = \'disable\'\r\n        											    elsif cur_user[:pin].nil? or cur_user[:pin] == \'\'\r\n        											        ctrl = \'readonly\'\r\n        									            end\r\n        											%>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your public password</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Public Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Public Password\" class=\"span10\" name=\"public_pass[pub_password]\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">make change your public password</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Private Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Private Password\" class=\"span10\" name=\"public_pass[pri_password]\" <%= ctrl %>>\r\n        													<span class=\"help-block\">confirm to change your public password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n        										\r\n        										<% end %>\r\n        									</div>\r\n        								</div>\r\n        							</div>\r\n								</div>\r\n								\r\n								<div class=\"accordion-group\">	\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapseTwo4\" data-parent=\"#accordion1\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n										Private Password\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"collapseTwo4\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"form-horizontal well\">\r\n											<%= form_for :private_pass, :class=>\'\', :url=>params[:opt] ,:method=>\'POST\' do |f| %>\r\n											<%= f.hidden_field :login_name, :value=>@current_user %>\r\n											<%\r\n        											    ctrl = \'\'\r\n        											    if @current_role==\'developer\'\r\n        											        ctrl = \'disable\'\r\n        											    elsif cur_user[:pin].nil? or cur_user[:pin] == \'\'\r\n        											        ctrl = \'readonly\'\r\n        									            end\r\n        											%>\r\n    											<fieldset>\r\n        											<p class=\"f_legend\">Update your private password</p>\r\n        											<div class=\"control-group\">\r\n        												<label class=\"control-label\">Current Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Current Private Password\" class=\"span10\" name=\"[private_pass]cur_private\" <%= ctrl %>>\r\n        													<span class=\"help-block\">your private password</span>\r\n        												</div>\r\n        												<label class=\"control-label\">New Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"New Private Password\" class=\"span10\" name=\"[private_pass]new_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">if you want to change your private password, input new one here</span>\r\n        												</div>\r\n        												<label class=\"control-label\">Confirm Password</label>\r\n        												<div class=\"controls\">\r\n        													<input type=\"password\" placeholder=\"Confirm Private Password\" class=\"span10\" name=\"[private_pass]con_private\" <%= \'disabled\' if @current_role == \'developer\' %>>\r\n        													<span class=\"help-block\">confirm your new private password</span>\r\n        												</div>\r\n        											</div>\r\n        											<div class=\"control-group\">\r\n        												<div class=\"controls\">\r\n        													<button class=\"btn\" type=\"submit\" <%= \'disabled\' if @current_role == \'developer\' %>>Save</button>\r\n        												</div>\r\n        											</div>\r\n        										</fieldset>\r\n        										\r\n        										<% end %>\r\n        									</div>\r\n        								</div>\r\n        							</div>\r\n								</div>\r\n							</div>\r\n                        \r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<br/>\r\n\r\n<script>\r\n    refresh();\r\n    \r\n    function confirm_delete(uid, pid) {\r\n        if (confirm(\'Are you sure?\') == true) {\r\n<%\r\n            destroy_url = \'destroy?id=\'\r\n%>\r\n            \r\n            url = \"destroy?uid=\" + uid + \"&pid=\" + pid;\r\n            window.location = url;\r\n        }\r\n    }\r\n    \r\n    function confirm_edit(uid, pid) {\r\n        // if (alert(\'Are you sure?\') == true) {\r\n            \r\n        // }\r\n        // console.log(\'UID = \' + uid);\r\n        // console.log(\'PID = \' + pid);\r\n        url = \"get_user?uid=\" + uid + \"&pid=\" + pid;\r\n        console.log(\"URL = \" + url);\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(data.prov.prefix + \" | \" + data.user.login + \"...\" + data.user.role);\r\n                $(\'#account_prefix\').val(data.prov.prefix);\r\n                $(\'#account_first_name\').val(data.prov.first_name);\r\n                $(\'#account_last_name\').val(data.prov.last_name);\r\n                $(\'#account_license_number\').val(data.prov.license_number);\r\n                $(\'#account_login_name\').val(data.user.login);\r\n                $(\'#account_password\').val(\'\');\r\n                $(\'#account_email\').val(data.user.email);\r\n                \r\n                $(\'#account_role option[value=\"\' + data.user.role + \'\"]\').prop(\'selected\', true);\r\n                $(\'#provider_type option[value=\"\' + data.prov.provider_type + \'\"]\').prop(\'selected\', true);\r\n                \r\n                var cb = $(\"#data-main_hospital\").data(\"kendoComboBox\");\r\n                cb.value(data.prov.main_hospital);\r\n                console.log(\'hosp : \' + data.prov.main_hospital);\r\n                // $(\'#account_role value:eq(\' + data.user.role + \')\').prop(\'selected\', true);\r\n                // $(\'#provider_type value:eq(\' + data.prov.provider_type + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n            } \r\n        });\r\n        \r\n        $(\'#data-add_new\').hide();\r\n        $(\'#data-update\').show();\r\n        $(\'#data-cancel\').show();\r\n        $(\'#account_login_name\').prop(\'readonly\', true);\r\n    }\r\n    \r\n    function confirm_reset(uid, pid) {\r\n        if (confirm(\'Are you sure?\') == true) {\r\n            url = \"reset_password?uid=\" + uid + \"&pid=\" + pid;\r\n            window.location = url;\r\n        }\r\n    }\r\n    \r\n    function cancel() {\r\n                $(\'#account_prefix\').val(\'\');\r\n                $(\'#account_first_name\').val(\'\');\r\n                $(\'#account_last_name\').val(\'\');\r\n                $(\'#account_license_number\').val(\'\');\r\n                $(\'#account_login_name\').val(\'\');\r\n                $(\'#account_password\').val(\'\');\r\n                $(\'#account_email\').val(\'\');\r\n        // $(\'#account\').trigger(\"reset\");\r\n        $(\'#data-add_new\').show();\r\n        $(\'#data-update\').hide();\r\n        $(\'#data-cancel\').hide();\r\n        $(\'#account_login_name\').prop(\'readonly\', false);\r\n    }\r\n</script>\r\n            <!-- styled form elements -->\r\n            <script src=\"/gebo/lib/uniform/jquery.uniform.min.js\"></script>\r\n            <!-- multiselect -->\r\n            <script src=\"/gebo/lib/multiselect/js/jquery.multi-select.min.js\"></script>\r\n            <!-- enhanced select (chosen) -->\r\n            <script src=\"/gebo/lib/chosen/chosen.jquery.min.js\"></script>\r\n<script>\r\n    $(document).ready(function() {\r\n		//* 2col multiselect\r\n		multiz.init();\r\n		\r\n	});\r\n    //* multiselect\r\n	multiz = {\r\n		init: function(){\r\n			\r\n			$(\'.multiselect\').multiSelect({\r\n				selectableHeader	: \'<h4>Selectable Hospitals</h4>\',\r\n				selectedHeader		: \'<h4>Selected Hospitals</h4>\'\r\n			});\r\n			$(\'.ms-elem-selectable\').hide();\r\n			$(\'.ms-elem-selectable\').click(function(){\r\n			   console.log($(this).attr(\'ms-value\')); \r\n			});\r\n// 			$(\'.ms-selection\').find(\'ul.ms-list\').html(\'<li class=\"ms-elem-selected\" ms-value=\"55c4e3ed790f9b223e000002\">โรงพยาบาลตำรวจ</li><li class=\"ms-elem-selected\" ms-value=\"55c5ba20790f9b1672000004\">โรงพยาบาลจุฬาลงกรณ์</li>\');\r\n// 			$(\'#ms-optgroup .ms-selectable, #ms-outsideCountries .ms-selectable\').find(\'li.ms-elem-selectable\').hide();\r\n			$(\'.ms-optgroup-label\').click(function(){\r\n				if ($(this).hasClass(\'ms-collapse\')){\r\n					$(this).nextAll(\'li\').hide();\r\n					$(this).removeClass(\'ms-collapse\'); \r\n				} else {\r\n					$(this).nextAll(\'li:not(.ms-selected)\').show();\r\n					$(this).addClass(\'ms-collapse\');\r\n				}\r\n			});\r\n		  \r\n// 			$(\'#searchable-form\').multiSelect({\r\n// 				selectableHeader : \'<input type=\"text\" id=\"multi_search\" autocomplete=\"off\" placeholder=\"search\" />\',\r\n// 				selectedHeader	 : \'<a href=\"javascript:void(0)\" id=\"sForm_deselect\" class=\"btn\">Deselect All</a>\'\r\n// 			});\r\n		\r\n// 			$(\'input#multi_search\').quicksearch(\'#ms-searchable-form .ms-selectable li\');\r\n// 			$(\'#searchable-form\').multiSelect();\r\n			\r\n			$(\'#select_all\').on(\'click\', function(){\r\n				$(\'.multiselect\').multiSelect(\'select_all\');\r\n				return false;\r\n			});\r\n			\r\n			$(\'#deselect_all\').on(\'click\', function(){\r\n				$(\'.multiselect\').multiSelect(\'deselect_all\');\r\n				return false;\r\n			});\r\n			\r\n			$(\'#sForm_deselect\').on(\'click\', function(){\r\n				$(\'#searchable-form\').multiSelect(\'deselect_all\');\r\n				return false;\r\n			});\r\n\r\n		}\r\n	};\r\n</script>',NULL,NULL,NULL,'2017-06-01 08:10:46','2017-06-01 08:10:46','index',''),(3039,'init',1208,4,'<%\r\n    @models = get_model\r\n        \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @ehr_models = ehr.get_model\r\n%>',NULL,NULL,NULL,'2017-06-01 08:12:33','2017-06-01 08:12:33','init',''),(3040,'create',729,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n    if request.post?\r\n      \r\n        hos_name = params[:record][:hospital_name_thai]\r\n        params[:record][:hospital_name_thai] = hos_name.strip\r\n      \r\n        obj = get_model(this.table_name).where(:hospital_name_thai=>hos_name).first\r\n        if obj\r\n            flash[:notice] = \'Record exist\'\r\n        else\r\n            doc = get_document this.document_name\r\n            record = doc.record_create(model,params)\r\n            flash[:notice]=\'New record has been created\'\r\n        end\r\n        \r\n        if return_url.index(\'?\')\r\n            return_url+=\'&\'\r\n         else\r\n            return_url+=\'?\'\r\n        end\r\n\r\n        return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-06-02 04:01:31','2017-06-02 04:01:31','create',''),(3041,'clean_login',1157,3,'<%\r\n    prov = get_model(this.table_name).all\r\n    \r\n    e_prov = []\r\n    prov.each do |i|\r\n        if i[:login] != i[:login].strip\r\n            e_prov << i\r\n        end\r\n    end\r\n    \r\n    res = {}\r\n    res[:err] = e_prov\r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2017-06-02 07:11:24','2017-06-02 07:11:24','clean_login',''),(3042,'search',1207,2,'<h1> Search Result </h1>\r\n<% \r\n	models = get_model\r\n	\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	\r\n	fields = %w{hn public_id first_name last_name}\r\n	query = \'\'\r\n	if params[:query]\r\n	    query = params[:query].strip\r\n	end\r\n	\r\n	keys = []\r\n	\r\n	keys << {:hn=>Regexp.new(query)}\r\n	keys << {:first_name=>Regexp.new(query)}\r\n	keys << {:last_name=>Regexp.new(query)}\r\n	keys << {:public_id=>query} if query.size==13\r\n	\r\n	criteria = {\'$or\'=>keys}\r\n	\r\n	patients = patient_model.where(criteria).limit(20).all  \r\n	\r\n	app_name = \"\\#{@current_project.name}#appointment\"\r\n	app_model = models[:appointment]\r\n	\r\n\r\n	\r\n	fields.insert(0, \'no\')\r\n	r = 0\r\n%>\r\nResult for \'<%= query %>\' = <%= patients.count %>\r\n<hr/>\r\n<%\r\nif patients.count != 0\r\n%>\r\n<%= tabular :model=>fields,:data=>patients,:n=>10 do |row,out|\r\n	am = module_model.where(:module_name=>\"\\#{app_name}\",:patient_id=>row.id).order(\'date\').last\r\n	r += 1\r\n	if am\r\n        app = app_model.where(:id=>am.module_id).first\r\n	\r\n        if @current_role!=\'pathologist\'\r\n            url = \"../Home/patient_record?id=\\#{am.module_id}\"\r\n        else\r\n            url = \"../Home/patho_patient_record?id=\\#{am.module_id}\"\r\n        end\r\n	\r\n        out[0] = link_to(\"\\#{r}.\", url)\r\n        out[1] = link_to(row.hn,url)\r\n        out[2] = link_to(row.public_id,url)\r\n        out[3] = link_to(row.first_name,url)\r\n        out[4] = link_to(row.last_name,url)\r\n        n = module_model.where(:module_name=>\"\\#{app_name}\",:patient_id=>row.id).count\r\n        	\r\n        extra = link_to(\'Add Visit\', \"../Appointment/create?obj_id=\\#{row.id}&return=../Home/index\", :class=>\'btn btn-mini btn-success\') + \' \' + link_to(\"Detail (\\#{n})\", url, :class=>\'btn btn-mini btn-info\')\r\n        	\r\n        	\r\n        out << extra.html_safe\r\n        \r\n	else\r\n	    out[0] = \"\\#{r}.\"\r\n        out << link_to(\'Add Visit\', \"../Appointment/create?obj_id=\\#{row.id}&return=../Home/index\", :class=>\'btn btn-mini btn-success\')\r\n	end\r\n	\r\n        out\r\nend\r\n	\r\n%>\r\n<%\r\nelse\r\n%>\r\n<h3>No patient found</h3>\r\n<%= link_to \'New patient\', \"../../www/Patient/create?hn=\\#{params[:query]}&return=/\\#{@current_project.name}/Appointment/create?return=../Home/index\", :class=>\'btn btn-info\' %>\r\n<%\r\nend\r\n%>\r\n<hr/>',NULL,NULL,NULL,'2017-06-05 05:38:48','2017-06-05 05:38:48','search',''),(3045,'document_name',1209,1,'\'appointment\'',NULL,NULL,NULL,'2017-06-07 05:06:12','2017-06-07 05:06:12',NULL,NULL),(3046,'new_case',1207,2,'<%\r\n    td = Time.now # today\r\n    td_str = td.strftime(\'%d/%m/%Y\')\r\n    tm_str = td.strftime(\'%H:%M\')\r\n    \r\n    ra = get_model[:region].all.sort_by{|i| i[:name]}\r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				<b> <i class=\"splashy-contact_grey_add\"></i>New Case</b>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding:10px\">\r\n				<form action=\"index\" accept-charset=\"UTF-8\" method=\"post\">\r\n					<div class=\"w-box\">\r\n						<div class=\"form-horizontal well\">\r\n							<div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label style=\'margin-top:22px\'>เลขที่ศพ <span class=\"f_req\">*</span>  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"pat[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\">\r\n							</div>\r\n							<div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\"><label>วันที่รับแจ้ง <br>(dd/mm/yyyy): </label></span>	\r\n								<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n									<span class=\"k-widget k-datepicker k-header k-input\" style=\"width: 100px;\"><span class=\"k-picker-wrap k-state-default\">\r\n									<input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= td_str %>\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 7 มิถุนายน 2017\">\r\n									<span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n									<script>\r\n										$(\"#data-date\").kendoDatePicker({\r\n											value: \'<%= td_str %>\',\r\n										});\r\n									</script>\r\n								</div>\r\n							</div>\r\n							<div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\"><label>เวลา <br>(HH.MM) : </label></span>\r\n								<span class=\"k-widget k-timepicker k-header k-input\" style=\"width: 80px;\">\r\n								<span class=\"k-picker-wrap k-state-default\">\r\n								<input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 100%;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\">\r\n								<span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n								<span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n								</span>\r\n								</span>\r\n								</span>\r\n								<script>\r\n									$(\"#data-start\").kendoTimePicker({\r\n										value: \'08:00\',\r\n										interval: 10,\r\n										parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n										change: function(event){\r\n											var v = $(\'#data-start\').val()\r\n											if(v.length==3){\r\n												$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n											}\r\n											 \r\n										}\r\n									});\r\n								</script>\r\n							</div>\r\n							<!--\r\n							<div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>เลขที่บัตรประชาชน : </label></span>	\r\n								<input type=\"text\" name=\"pat[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n							</div>\r\n							-->\r\n							<div class=\"clear\"></div>\r\n							<hr/>\r\n							<div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\"><label>Prefix name : </label></span>	\r\n								<span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n								<span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n								<input name=\"pat[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" autocomplete=\"off\" tabindex=\"0\" maxlength=\"32\" style=\"vertical-align: text-top; width: 100%;\" aria-disabled=\"false\" role=\"combobox\" aria-