>\',\r\n										});\r\n									</script>\r\n								</div>\r\n							</div>\r\n							<div class=\"clear\"></div>\r\n							<div id=\"provider_2\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label >พนักงานสอบสวน : </label></span>	\r\n								<!--<input type=\"text\" name=\"app[region]\" id=\"data-region\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >-->\r\n							    \r\n							    <select name=\"app[provider_2]\" id=\"data-provider_2\" style=\'width:100%;height:2.0em\'>\r\n							        <option value=\"\"></option>\r\n							    <%\r\n							        pol = get_model[:provider].where(:provider_type=>\'8\').all\r\n							        pol.each do |i|    \r\n							    %>\r\n							        <option value=\"<%= i.id.to_s %>\"><%= i[:name] %></option>\r\n							    <%  end %>\r\n							    </select>\r\n							    \r\n							</div>\r\n							<div id=\"tel_provider_2\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label >หมายเลขโทรศัพท์ : </label></span>	\r\n								<input type=\"text\" name=\"app[tel_provider_2]\" id=\"data-tel_provider_2\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"region\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label >เขตที่รับผิดชอบ : </label></span>	\r\n								<!--<input type=\"text\" name=\"app[region]\" id=\"data-region\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >-->\r\n							    \r\n							    <select name=\"app[region]\" id=\"data-region\" style=\'width:100%;height:2.0em\'>\r\n							        <option value=\"\"></option>\r\n							    <%\r\n							        ra.each do |i|    \r\n							    %>\r\n							        <option value=\"<%= i.id.to_s %>\"><%= i[:name] %></option>\r\n							    <%  end %>\r\n							    </select>\r\n							    \r\n							</div>\r\n							<!--<div class=\'clear\'></div>-->\r\n							\r\n							<div id=\"note\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label >สาเหตุการตายเบื้องต้น : </label></span>	\r\n								<input type=\"text\" name=\"app[note]\" id=\"data-note\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div class=\"clear\"></div>\r\n							\r\n							<div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label>แพทย์ที่ปฎิบัติงาน : </label></span>	\r\n								<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n									<select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n										<option value=\"\"></option>\r\n<%\r\n    prov = get_model[:provider].where(:provider_type=>\'1\').all.sort_by{|i| i[:name]}\r\n    prov.each do |i|\r\n%>\r\n                                        <option value=\"<%= i.id.to_s %>\"><%= i[:name] %></option>\r\n<% end %>\r\n									</select>\r\n								</div>\r\n							</div>\r\n							<div class=\'clear\'></div>\r\n							<h3>สถานที่พบศพ</h3>\r\n							<div id=\"address-no\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>บ้านเลขที่  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_no]\" id=\"data-address_no\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-name\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>หมู่บ้าน/อาคาร/คอนโด  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_name]\" id=\"data-address_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-soi\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>ซอย  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_soi]\" id=\"data-address_soi\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-moo\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>หมู่  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_moo]\" id=\"data-address_moo\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-road\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>ถนน  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_road]\" id=\"data-address_road\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-tambol\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>ตำบล  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_tambol]\" id=\"data-address_tambol\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-amphur\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>อำเภอ  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_amphur]\" id=\"data-address_amphur\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-province\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>จังหวัด  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_province]\" id=\"data-address_province\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<br>\r\n							<div class=\'clear\'></div>\r\n							<div id=\"contact\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label>ผู้พบศพ  : </label></span>	\r\n								<input type=\"text\" name=\"app[contact]\" id=\"data-contact\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"tel_contact\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label>หมายเลขโทรศัพท์  : </label></span>	\r\n								<input type=\"text\" name=\"app[tel_contact]\" id=\"data-tel_contact\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div class=\'clear\'></div>\r\n							<div id=\"temporary\" style=\"\"></div>\r\n							<input type=\"hidden\" name=\"app[status]\" id=\"data-status\" value=\"Appointed\">\r\n							<input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user[:login] %>\">\r\n							<input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user[:login] %>\">\r\n							<input type=\"submit\" name=\"commit\" value=\"+Add New Case\" class=\"btn btn-success\">\r\n							<a href=\"index\" class=\"btn \" >Cancel</a>  \r\n							<div class=\"clear\"></div>\r\n						</div>\r\n					</div>\r\n				</form>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    \r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    \r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n</script>',NULL,NULL,NULL,'2017-06-07 05:08:44','2017-06-07 05:08:44','new_case',''),(3047,'document_name',1210,1,'\'finding\'',NULL,NULL,NULL,'2017-06-07 05:13:17','2017-06-07 05:13:17',NULL,NULL),(3048,'document_name',1211,1,'\'symptom\'',NULL,NULL,NULL,'2017-06-07 05:16:44','2017-06-07 05:16:44',NULL,NULL),(3049,'document_name',1212,1,'\'symptom_group\'',NULL,NULL,NULL,'2017-06-07 05:17:00','2017-06-07 05:17:00',NULL,NULL),(3050,'document_name',1213,1,'\'anatomy\'',NULL,NULL,NULL,'2017-06-07 05:21:38','2017-06-07 05:21:38',NULL,NULL),(3051,'gynecology_report',1185,2,'<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n		width:100px\r\n    }\r\n    \r\n<%\r\n    malignant_list = %w{C541 C542 C548 C530 C531 C538 C56 C796 C570 C52 C510 C511 C512 C518 C482 C786 D392 C58 C578 C80 C509 C189}\r\n    malignant_list.each do |i|\r\n%>\r\n.<%= i %> { background:lightsalmon; }\r\n<% end %>\r\n</style>\r\n<%\r\n\r\n    models = get_model\r\n\r\n    c = models[:gynecology].count\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box-header\">\r\n			<h3>Search</h3>\r\n		</div>\r\n        <div class=\"w-box-content cnt_a\">\r\n<%= form_for :search,:url=>\'gynecology_report_partial?update=result-panel\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n	    <span class=\"field-data\"> \r\n			<label class=\"field-label\">Start Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :sdate, :value=>\'\',:id=>\'sdate\',:style=>\"width:100%\"%></div>\r\n		</span> \r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">End Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :edate, :value=>\'\',:id=>\'edate\',:style=>\"width:100%\"%></div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n\r\n		<div class=\'clear\'></div>\r\n\r\n		<span class=\"field-data\">\r\n		    <div class=\"field-input\"><%=f.submit \'Submit\', :class=>\'btn btn-success\'%> </div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n<script>\r\n    $(\"#sdate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n    $(\"#edate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n</script>\r\n<% end %>\r\n\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class=\'clear\'></div>\r\n<br/>\r\n<div id=\'result-panel\'></div>\r\n',NULL,NULL,NULL,'2017-06-08 13:09:42','2017-06-08 13:09:42','gynecology_report',''),(3052,'gynecology_report_partial',1185,3,'<%\r\n\r\n    models = get_model\r\n\r\n    \r\n     if q = params[:search]\r\n         \r\n           cond = {}\r\n         \r\n        q[:sdate] = Time.strptime(q[:sdate], \"%d/%m/%Y\")\r\n        q[:edate] = Time.strptime(q[:edate], \"%d/%m/%Y\")\r\n        cond[:admission_date] = {\'$gte\'=>q[:sdate].beginning_of_day,\'$lte\'=>q[:edate].end_of_day}\r\n        \r\n        records = models[:gynecology].collection.find(cond, {:fields=>{\'discharge_date\'=>1,\'admission_date\'=>1,\'discharge_status\'=>1, \'mcode\'=>1,\'_id\'=>1,\'case_type\'=>1,\'line\'=>1,\'stage\'=>1,\'malignancy_case_type\'=>1, \'principle_diagnosis\'=>1, \'comorbidity\'=>1, \'complication\'=>1, \'external_cause\'=>1, \'other_diagnosis\'=>1, \'operation\'=>1}}).to_a\r\n        \r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n		ehr_models = ehr.get_model\r\n		patient_model = ehr_models[:patient]\r\n		patient_module_model = ehr_models[:patient_module]\r\n        \r\n        mpa = {}\r\n        mpatients = {}\r\n        \r\n        patient_module_model.collection.find(\'module_id\'=>{\'$in\'=>records.collect{|i| i[\'_id\']}}).to_a.each do |i|\r\n           \r\n            mpa[i[\'module_id\']] = i[\'patient_id\']\r\n            mpatients[i[\'patient_id\']] = true\r\n            \r\n        end\r\n        \r\n        records.collect!{|i|\r\n        \r\n            i[\'patient_id\'] = mpa[i[\'_id\']]\r\n           \r\n            i \r\n        }\r\n        total_cases = mpatients.keys.size\r\n        \r\n        \r\n        \r\n        def query_map ms, rs, table, key, ukey=nil\r\n    \r\n        rx = []\r\n        mrx = {}\r\n        rs.collect{|i| i[key] }.compact.each{|i|\r\n            rx+= i\r\n        }\r\n        \r\n        rs.each do |i|\r\n           \r\n           i[key].each do |j|\r\n            \r\n            mrx[j] = i[\'patient_id\']   \r\n            \r\n           end\r\n            \r\n        end\r\n        \r\n        \r\n        ris = ms[table].collection.find({\'_id\'=>{\'$in\'=>rx}}).to_a\r\n        rm = {}\r\n        ux = {}\r\n        for i in ris\r\n            rm[i[\'_id\']] = i \r\n            x = i[ukey]\r\n            xs = x.gsub(\'.\',\',\').split(\',\')\r\n            for xi in xs\r\n            ux[xi] = [] unless ux[xi]\r\n            i[\'patient_id\'] = mrx[i[\'_id\']]\r\n            ux[xi] << i\r\n            end\r\n        end\r\n            \r\n        [rm, rx, ux]\r\n            \r\n        end    \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        # comorbidity = []\r\n        # records.collect{|i| i[\'comorbidity\'] }.compact.each{|i| comorbidity+= i}\r\n        \r\n        # complication = []\r\n        # records.collect{|i| i[\'complication\'] }.compact.each{|i| complication+= i}\r\n        \r\n        # external_cause = []\r\n        # records.collect{|i| i[\'external_cause\'] }.compact.each{|i| external_cause+= i}\r\n        \r\n        # other_diagnosis = []\r\n        # records.collect{|i| i[\'other_diagnosis\'] }.compact.each{|i| other_diagnosis+= i}\r\n        \r\n        # operation = []\r\n        # records.collect{|i| i[\'operation\'] }.compact.each{|i| operation+=i}\r\n        \r\n         k_principle_diagnosis = {}\r\n         k_mcode= {}\r\n         k_discharge={}\r\n         for i in records\r\n         \r\n            k_principle_diagnosis[i[\'principle_diagnosis\']] = [] unless  k_principle_diagnosis[i[\'principle_diagnosis\']] \r\n            k_principle_diagnosis[i[\'principle_diagnosis\']]  << i \r\n            \r\n            mcode = i[\'mcode\']\r\n            if mcode\r\n            mcode = mcode.gsub(\"/\",\"\")\r\n            k_mcode[mcode] = [] unless    k_mcode[mcode]\r\n            k_mcode[mcode] << i \r\n            end\r\n            k_discharge[i[\'discharge_status\']] = [] unless k_discharge[i[\'discharge_status\']] \r\n            k_discharge[i[\'discharge_status\']] << i\r\n            \r\n            \r\n         end\r\n        \r\n        \r\n         m_comorbidity, comorbidity, k_comorbidity  = query_map(models, records, :icd_comorbidity, \'comorbidity\', \'comorbidity\')\r\n        \r\n         m_complication, complication, k_complication  = query_map(models, records, :icd_complication, \'complication\', \'complication\')\r\n        \r\n         m_external_cause, external_cause, k_external_cause  = query_map(models, records, :icd_external_cause, \'external_cause\', \'external_cause\')\r\n        \r\n         m_other_diagnosis, other_diagnosis, k_other_diagnosis  = query_map(models, records, :icd_other_diagnosis, \'other_diagnosis\', \'other_diagnosis\')\r\n        \r\n         m_operation, operation, k_operation  = query_map(models, records, :icd_operation, \'operation\', \'operation\')\r\n        \r\n        \r\n        \r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        m_patient = model[:patient]\r\n        m_patient_module = model[:patient_module]\r\n        \r\n        pm_records = m_patient_module.collection.find({\'module_id\'=>{\'$in\'=>records.collect{|i| i[\'_id\']}}}).to_a\r\n        \r\n        pm_map = {}\r\n        pm_records.each{|i| pm_map[i[\'module_id\']] = i}\r\n        \r\n        p_records = m_patient.collection.find({\'_id\'=>{\'$in\'=>pm_records.collect{|i| i[\'patient_id\']}}}).to_a\r\n        \r\n        p_map = {}\r\n        p_records.each{|i| p_map[i[\'_id\']]=i }\r\n        \r\n        \r\n        \r\n        patients = {}\r\n        \r\n        for i in records\r\n        \r\n            pm = pm_map[i[\'_id\']]\r\n            \r\n            p = p_map[pm[\'patient_id\']]\r\n            \r\n            if p\r\n                patients[p[\'_id\']] = [p,i,[]] unless patients[p[\'_id\']] \r\n                patients[p[\'_id\']][2] << i\r\n            end\r\n            \r\n        \r\n        end\r\n        \r\n        \r\n        \r\n        \r\n        \r\ndef formulate l\r\n\r\n   l =  l.split(\"\\n\").compact\r\n    \r\n    l.collect!{|j|\r\n    \r\n    t = j.split(\":\")\r\n    \r\n    name = t[0]\r\n    codes = t[1].split(\',\').collect{|i| i.strip}.compact if t[1]\r\n    \r\n    {:name=>name,:codes=>codes}\r\n    }\r\n    \r\n    l\r\n    \r\nend\r\n\r\n\r\n    #   m_comorbidity  = models[:icd_comorbidity].collection.find({\'_id\'=>{\'$in\'=>comorbidity}}).to_a\r\n    #   m_comorbidity  = models[:icd_comorbidity].collection.find(\'_id\'=>{\'$in\'=>[BSON::ObjectId(\'592f9079790f9b6a69000033\')]}).to_a\r\n       \r\n%>    \r\n<%=q[:sdate].beginning_of_day %> - <%= q[:edate].end_of_day %>\r\n<%# params.inspect %><hr/>\r\n\r\n<style>\r\n    .strong{\r\n         font-weight: bold;\r\n    }\r\n    .header{\r\n        font-weight: bold;\r\n        background-color:#ccc;\r\n    }\r\n</style>\r\n<h1>\r\nTotal patients and total admission cases\r\n</h1>\r\nTotal Patients : <%=fn p_records.size %> Patients \r\n<br/>\r\nTotal Admission :  <%=fn records.size %> Cases \r\n<br/>\r\n\r\n<%\r\n    months = {}\r\n    \r\n    for i in records \r\n        key = \"\\\\#{i[\'admission_date\'].month}-\\\\#{i[\'admission_date\'].year}\"\r\n        months[key] = [] unless months[key]\r\n        months[key] << i\r\n    end\r\n    \r\n    months_key = months.keys.sort{|a,b| \"1-\\\\#{a}\".to_datetime <=>\"1-\\\\#{b}\".to_datetime } \r\n\r\n\r\ncounter = {}\r\nlist2 = <<LISTEOF2\r\nCervical cancer:C530,C531,C538\r\nOvarian cancer:C56\r\nUterine cancer:C541,C542,C543,C544,C545,C546,C547,C548\r\nFallopian tube caner:C570\r\nPeritoneal cancer:C482\r\nVulvar cancer:C510,C511,C512,C513,C514,C515,C516,C517,C518\r\nGestational trophoblastic disease:D392,C58\r\nTwo primary cancer:C578\r\nLISTEOF2\r\n\r\nlist2 = formulate(list2)  \r\nfor i in list2\r\n\r\n    c = 0 \r\n    for code in i[:codes]\r\n     counter[code] = true\r\n    \r\n    end\r\n    \r\nend\r\n\r\n\r\n\r\n\r\n%>\r\n<%\r\n    \r\n    mc = {}\r\n\r\n    counter.keys.each do |code|\r\n    \r\n    if k_principle_diagnosis[code]  \r\n    k_principle_diagnosis[code].each do |i|\r\n     key = \"\\\\#{i[\'discharge_date\'].month}-\\\\#{i[\'discharge_date\'].year}\"\r\n    \r\n    mc[key] = {} unless mc[key]\r\n    \r\n      pm = pm_map[i[\'_id\']]\r\n            \r\n    p = p_map[pm[\'patient_id\']]\r\n            \r\n    if p\r\n    \r\n    mc[key][p[\'_id\']] = 1\r\n    \r\n    end\r\n        \r\n    end\r\n    end\r\n    \r\n    end\r\n\r\n    \r\n    \r\n    sum = [0,0,0]\r\n\r\n%>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n            <th>Month</th>\r\n            <th>Total admission</th>\r\n            <th>Unique Patients</th>\r\n            <th>Unique Patients with Cancer code</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <% for i in months_key \r\n            m  = months[i]\r\n            up = {}\r\n            for j in m\r\n            \r\n                pm = pm_map[j[\'_id\']]\r\n            \r\n                p = p_map[pm[\'patient_id\']]\r\n                \r\n                if p\r\n                   up[p[\'_id\']] = 1 \r\n                end\r\n                #   c+= k_principle_diagnosis[code].size\r\n                \r\n            end\r\n            sum[0]+=m.size\r\n            sum[1]+=up.keys.size\r\n            sum[2]+=mc[i].keys.size if mc[i]\r\n        %>\r\n        <tr>\r\n            <td><%= i %></td><td><%=m.size%></td><td><%=up.keys.size%></td><td><%=mc[i].keys.size if mc[i]%></td>\r\n        </tr>\r\n        <% end %>\r\n        <tr>\r\n        <td></td>\r\n            <td><%=sum[0]%></td>  <td><%#sum[1]%></td>  <td><%#sum[2]%></td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n\r\n\r\n<h1>\r\n    Total patients by yype\r\n</h1>\r\n<%\r\n\r\n    case_type = {}\r\n    line = {}\r\n    patients.values.each do |i|\r\n        case_type[i[1][\'case_type\']] = 0 unless  case_type[i[1][\'case_type\']] \r\n        case_type[i[1][\'case_type\']] += 1\r\n        line[i[1][\'line\']] = 0 unless  line[i[1][\'line\']] \r\n        line[i[1][\'line\']] += 1\r\n        \r\n    end\r\n\r\n\r\n%>\r\n<b>ประเภท</b>\r\n<% case_type.each_pair do |i,j|\r\n    \r\n    title = i.humanize\r\n    title = \"ไม่ระบุ\"  if title ==\"\"\r\n    %>\r\n<li><%=title%> : <%=fn j%></li>\r\n<% end %>\r\n<%\r\n\r\n%>\r\n<b>สาย</b>\r\n<li>เขียว  \r\n: <%=fn line[\'1\']%></li>\r\n<li>เหลือง \r\n: <%=fn line[\'2\']%></li>\r\n<li>ฟ้า \r\n: <%=fn line[\'3\']%></li>\r\n<li>แดง  \r\n: <%=fn line[\'4\']%></li>\r\n<li>ชมพู  \r\n: <%=fn line[\'5\']%></li>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<%\r\n\r\n\r\n\r\n\r\n\r\ndef display list, sum, tag = \'data\'\r\n%>\r\n<%= \"<table class=\'table\' style=\'\' id=\'\\\\#{tag.to_s}\'\".html_safe %>\r\n<%\r\nfor i in list \r\n\r\nname = i[:name]\r\ns = 0 \r\n if name.index \'*\'\r\n    s = 3\r\n    name = name[1..-1]     \r\n end\r\ncodes = i[:codes].join(\",\")\r\nx = false\r\nif codes ==\'-\'\r\nx = \'-\' \r\nend\r\nif codes ==\'--\'\r\nx = \'+\'\r\nend\r\n\r\n\r\n%>\r\n<tr style=\"<%=\'background:#eee\' if x ==\'+\'%>\">\r\n\r\n<td class=\"<%=\'strong\' if x ==\'-\'%>\">\r\n    <%=(\'&nbsp;\'*s).html_safe%><%=name%>\r\n</td>    \r\n<td>\r\n    <%=codes unless x %>\r\n</td>    \r\n\r\n<td>\r\n\r\n\r\n<% if codes !=\'\' %>\r\n\r\n<%\r\n    \r\n    count = i[:count]\r\n    \r\n    count = i[:ucount] if name==\'Staging procedures\' or  name==\'Vaginal reconstruction\' or name==\'Bowel surgery / repair\' or name==\'Urinary tract surgery/ repair\'\r\n\r\n%>\r\n    <%= count %>  (<%=(format(\'%.2f\',i[:count].to_f*100/sum))%>%)\r\n    <% end %>\r\n</td>    \r\n\r\n</tr>\r\n<%\r\n    if name==\'Myomectomy\' and x !=\'-\'\r\n    \r\n    op_count = {}\r\n    \r\n    for j in i[:items]\r\n    \r\n        id = j[\'detail_operation\']\r\n        op_count[id] = 0 unless op_count[id]\r\n        op_count[id] += 1 \r\n    \r\n    end\r\n# 1|Abdominal\r\n# 2|Laparoscopic\r\n# 3|Hysteroscopic\r\n# 4|B-Lynch\r\n# 5|Balloon tamponade\r\n    op_count.keys.sort.each do |j|\r\n    count = op_count[j]\r\n    label = {\'1\'=>\'Abdominal\',\'2\'=>\'Laparoscopic\',\'3\'=>\'Hysteroscopic\',\'4\'=>\'B-Lynch\',\'5\'=>\'Balloon tamponade\',\'\'=>\'NA\'}[j]\r\n%>\r\n<tr>\r\n    \r\n    <td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n        <%=label %>\r\n    </td>\r\n    <td>\r\n        \r\n    </td>\r\n    <td>\r\n        <%=count %>\r\n    </td>\r\n</tr>\r\n\r\n\r\n<% end %>\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n \r\n  <%\r\n\r\n \r\nend\r\n\r\n\r\n%>\r\n\r\n<div class=\"\" style=\"display:block\">\r\n<h1>\r\n    Benign gynecologic diseases\r\n</h1>\r\n\r\n<%\r\n\r\ncounter = {}\r\nlist2 = <<LISTEOF2\r\nCervical cancer:C530,C531,C538\r\nOvarian cancer:C56\r\nUterine cancer:C541,C542,C543,C544,C545,C546,C547,C548\r\nFallopian tube caner:C570\r\nPeritoneal cancer:C482\r\nVulvar cancer:C510,C511,C512,C513,C514,C515,C516,C517,C518\r\nGestational trophoblastic disease:D392,C58\r\nTwo primary cancer:C578\r\nLISTEOF2\r\n\r\nlist2 = formulate(list2)  \r\nfor i in list2\r\n\r\n    c = 0 \r\n    for code in i[:codes]\r\n     counter[code] = true\r\n    \r\n    end\r\n    \r\nend\r\n\r\n%>\r\n\r\n\r\n<%\r\n\r\nlist = <<LISTEOF\r\nPelvic inflammatory diseases: N700,N701,N702\r\nEndometriosis: N801,N802,N803,N804,N805,N806,N807\r\nBenign ovarian tumor: D27\r\nLeiomyoma: D250,D251,D252,D253,D254,D255,D256,D257\r\nAdenomyosis:N800\r\nEndometrial hyperplasia: N850,N851,N852,N853,N854,N855,N856,N857\r\nEndometrial polyp: N840\r\nCervical intraepithelial neoplasia: N870,N871,D060,D061\r\nVaginal intraepithelial neoplasia: N890,N891,D072\r\nVulvar intraepithelial neoplasia: N900,N901,D071\r\nPelvic organ  prolapse urinary incontinence: N811,N812,N813,N814,N815,N816,N817,N993,N884\r\nUrinary incontinence: N393,N394,N328\r\nCongenital malformation : Q505, Q510,Q511,Q512,Q513,Q514,Q515,Q520,Q521,Q522,Q523,Q524,Q525,Q526,Q527,Q528\r\nEctopic pregnancy: O000,O001,O002,O008\r\nPhysiologic ovarian cyst: N830, N831, N832\r\nInfertility: N970,N971,N972,N973,N974,N975,N312,Z312\r\nBrest cancer:C509,Z853\r\nLISTEOF\r\n\r\n\r\n%>\r\n\r\n<%\r\nlist = formulate(list)  \r\nsum = 0 \r\n\r\nfound = false\r\nfor i in list\r\n\r\n    c = 0 \r\n    for code in i[:codes]\r\n        # principle diangosis\r\n        if k_principle_diagnosis[code]\r\n            c+= k_principle_diagnosis[code].size\r\n            found = true\r\n        end\r\n        if  k_comorbidity[code]\r\n            c+= k_comorbidity[code].size \r\n            found = true\r\n        end   \r\n        counter[code] = true\r\n    end\r\n    \r\n    i[:count] = c\r\n    sum += c\r\nend\r\n\r\n\r\nfor i in k_principle_diagnosis.keys.sort\r\n\r\n    list <<{:name=>i, :count=> k_principle_diagnosis[i].size, :codes=>[i]} unless counter[i]\r\n\r\n%>\r\n<% end %>\r\n\r\n<div id=\"data_1_p\"></div>\r\n<script>\r\n    $(\'#data_1\').appendTo($(\'#data_1_p\'))\r\n</script>\r\n\r\n<%= display list, sum, :data_1 %>\r\n\r\n\r\n<h1>\r\n  Malignant gynecologic diseases\r\n</h1>\r\n\r\n\r\n<%\r\n\r\nlist = <<LISTEOF\r\nCervical cancer:C530,C531,C538\r\nOvarian cancer:C56\r\nUterine cancer:C541,C542,C543,C544,C545,C546,C547,C548\r\nFallopian tube caner:C570\r\nPeritoneal cancer:C482\r\nVulvar cancer:C510,C511,C512,C513,C514,C515,C516,C517,C518\r\nGestational trophoblastic disease:D392,C58\r\nTwo primary cancer:C578\r\nLISTEOF\r\n\r\n\r\n%>\r\n\r\n<%\r\nlist = formulate(list)  \r\nsum = 0 \r\nfor i in list\r\n    \r\n    c = 0 \r\n    stage = {:primary=>0, :recurrent=>0, :detail=>{}}\r\n    for code in i[:codes]\r\n        # principle diangosis\r\n        if k_principle_diagnosis[code]\r\n            c+= k_principle_diagnosis[code].size\r\n            for k in k_principle_diagnosis[code]\r\n    \r\n                if k[\'malignancy_case_type\']==\'1\'\r\n                    stage[:primary]+=1 \r\n                end\r\n                if k[\'malignancy_case_type\']==\'2\'\r\n                    stage[:recurrent]+=1\r\n                    st = k[\'stage\']\r\n                    if st\r\n                       stage[:detail][st] = 0 unless   stage[:detail][st] \r\n                       stage[:detail][st]  +=1\r\n                    end\r\n                    \r\n                end\r\n            end\r\n            \r\n        end\r\n        \r\n        if  k_comorbidity[code]\r\n        c+= k_comorbidity[code].size\r\n        \r\n             for k in k_comorbidity[code]\r\n    \r\n                if k[\'malignancy_case_type\']==\'1\'\r\n                    stage[:primary]+=1 \r\n                end\r\n                if k[\'malignancy_case_type\']==\'2\'\r\n                    stage[:recurrent]+=1\r\n                    st = k[\'stage\']\r\n                    if st\r\n                       stage[:detail][st] = 0 unless   stage[:detail][st] \r\n                       stage[:detail][st]  +=1\r\n                    end\r\n                    \r\n                end\r\n            end\r\n        \r\n        \r\n        \r\n        end\r\n        \r\n        \r\n        \r\n    end\r\n    i[:count] = c\r\n    i[:stage] = stage\r\n    sum += c\r\nend\r\n%>\r\n<div id=\"data_2_p\"></div>\r\n<script>\r\n    $(\'#data_2\').appendTo($(\'#data_2_p\'))\r\n</script>\r\n<%= display list, sum, :data_2 %>\r\n<%\r\n    \r\n\r\n%>\r\n\r\n<% for i in list \r\nif i[:codes][0]!=\'C578\' \r\n%>\r\n<%#i.inspect %>\r\n<table class=\"table\" style=\"display:table\"> \r\n    <tr>\r\n        <tr>\r\n            <th><%=i[:name]%> : <%=i[:codes].join(\", \")%>  : </th><th><%=i[:count] %></th>\r\n        </tr>\r\n        <% if i[:name]!=\'Gestational trophoblastic disease\' %>\r\n        <tr>\r\n            <td>Primary</td><td><%=i[:stage][:primary]%></td>\r\n            \r\n        </tr>\r\n        <tr>\r\n            <td>Recurrent</td><td><%=i[:stage][:recurrent]%></td>\r\n            \r\n        </tr>\r\n        <% end %>\r\n        <% if false\r\n        \r\n        for j in %w{IA IA1 IA2 IB IB1 IB2 IC IC1 IC2 IC3 IIA IIA1 IIA2 IIB IIIA IIIA1 IIIA2 IIIB IIIC IIIC1 IIIC2 IVA IVB} %>\r\n        <tr>\r\n            <td>Stage <%=j%></td> <td><%= i[:stage][:detail][j] %></td>\r\n        </tr>\r\n        <% end %>\r\n        <tr></tr>\r\n        <% end %>\r\n    </tr>\r\n    \r\n</table>\r\n\r\n\r\n<br/>\r\n\r\n<% else %>\r\n<%#m_comorbidity.inspect %>\r\n<%#i.inspect %>\r\n<% \r\n\r\n    commap = {}\r\nif k_principle_diagnosis[\'C578\'] \r\nfor j in k_principle_diagnosis[\'C578\'] \r\n\r\n  for k in  j[\"comorbidity\"]\r\n    com = m_comorbidity[k]\r\n    commap[com[\'comorbidity\']] = 0 unless  commap[com[\'comorbidity\']] \r\n    commap[com[\'comorbidity\']]  += 1\r\n  end\r\n  \r\n  \r\n%>\r\n<% end %>\r\n<% end %>\r\n\r\n\r\n<%# commap.inspect %>\r\n\r\n\r\n\r\n<table class=\"table\"> \r\n    <tr>\r\n        <tr>\r\n            <th><%=i[:name]%> : <%=i[:codes].join(\", \")%> : <%=i[:count] %> Case(s)</th><th>No. (%)</th>\r\n        </tr>\r\n        <tr>\r\n            <td>Primary</td><td><%=i[:stage][:primary]%></td>\r\n            \r\n        </tr>\r\n        <% for c in commap.keys.sort %>\r\n        <tr>\r\n            <td><%=c%></td><td><%=commap[c]%></td>\r\n        </tr>\r\n        <% end %>\r\n    </tr>\r\n    \r\n</table>\r\n\r\n<% end %>\r\n<% end %>\r\n<%#records.inspect %>\r\n\r\n    \r\n</div>\r\n<!-- ====================================================== -->\r\n<%# k_comorbidity.inspect %>\r\n<h1>\r\n     Histology of malignant gynecologic diseases\r\n\r\n</h1>\r\n\r\n\r\n\r\n<%\r\n\r\nlist = <<LISTEOF\r\nOvarian cancer:-\r\nSerous cystadenocarcinoma:M84413\r\nBorderline serous cystadenoma: M84423\r\nMucinous cystadenocarcinoma: M84703, M84803\r\nBorderline mucinous cystadenoma :M84723\r\nEndometrioid carcinoma: M83803\r\nClear cell carcinoma: M83103\r\nMixed cell carcinoma: M83233\r\nAdenocarcinoma: M81403\r\nDysgerminoma: M90603\r\nEndodermal sinus tumor: M90713\r\nImmature teratoma: M90803\r\nMixed germ cell tumor: M90853\r\nGranulosa cell tumor: M86203\r\nUterine cancer:-\r\nEndometrioid carcinoma: M81403\r\nPapillary serous carcinoma: M80503\r\nEndometrial stromal sarcoma: M89303\r\nLeiomyosarcom: M88903\r\nMMMT - carcinosarcoma: M89503, M89803\r\nCervical carcinoma:-\r\nSquamous cell carcinoma: M80703\r\nKeratinizing squamous cell carcinoma: M80713\r\nNonkeratinizing squamous cell carcinoma: M80723, M80733\r\nAdenocarcinoma: M81403\r\nSmall cell carcinoma: M80413\r\nLISTEOF\r\n\r\n%>\r\n\r\n<%\r\nlist = formulate(list)  \r\n%>\r\n<%#list.inspect %>\r\n<%#k_principle_diagnosis.keys.inspect %>\r\n<%#k_comorbidity.keys.inspect %>\r\n\r\n\r\n<%\r\nsum = 0 \r\nfor i in list\r\n    \r\n    c = 0 \r\n    for code in i[:codes]\r\n        # principle diangosis\r\n        c+= k_principle_diagnosis[code].size if k_principle_diagnosis[code]\r\n        c+= k_comorbidity[code].size if  k_comorbidity[code]\r\n        c+= k_mcode[code].size if k_mcode[code]\r\n        \r\n    end\r\n    i[:count] = c\r\n    sum += c\r\nend\r\n%>\r\n<div id=\"data_3_p\"></div>\r\n<script>\r\n    $(\'#data_3\').appendTo($(\'#data_3_p\'))\r\n</script>\r\n<%= display list, sum, :data_3 %>\r\n\r\n\r\n\r\n\r\n<h1>\r\n\r\n    4. Complications\r\n\r\n</h1>\r\n\r\n\r\n<%\r\n\r\nlist = <<LISTEOF\r\nIntraoperative complications:-\r\nInjury to internal organs:T812\r\nBladder: S3721\r\nUreter: S371\r\nBowel:S364,S364S366\r\nIntraabdominal vessels: S350, S351, S355, S357\r\nMultipel intraabdominal organs: S367, S377\r\nHemorrhage complicating procedure: T810\r\nPostoperative complications:-\r\nWound infection: T814\r\nWound disruption/dehiscence: T813\r\nUrinary tract infection : N10, N300, N390\r\nThromboembolism: I801, I802\r\nUrinary retention: T818,R33\r\nFistula:-\r\nVesicovaginal fistula: N820\r\nUreterovaginal fistula: N821\r\nRectovaginal fistula: N823\r\nEnterovaginal fistula: K632\r\nLISTEOF\r\n\r\n%>\r\n\r\n<%\r\nlist = formulate(list)  \r\nsum = 0 \r\nfor i in list\r\n    \r\n    c = 0 \r\n    for code in i[:codes]\r\n        # principle diangosis\r\n        # c+= k_principle_diagnosis[code].size if k_principle_diagnosis[code]\r\n        # c+= k_comorbidity[code].size if  k_comorbidity[code]\r\n        c+= k_complication[code].size if  k_complication[code]\r\n        \r\n    end\r\n    i[:count] = c\r\n    sum += c\r\nend\r\n%>\r\n<div id=\"data_4_p\"></div>\r\n<script>\r\n    $(\'#data_4\').appendTo($(\'#data_4_p\'))\r\n</script>\r\n<%= display list, sum, :data_4%>\r\n\r\n\r\n\r\n\r\n<h1>\r\n\r\n5. Operations\r\n\r\n</h1>\r\n<%#k_operation.keys.inspect %>\r\n\r\n<%\r\n\r\nlist = <<LISTEOF\r\nType of surgery:-\r\nAbdominal surgery:6839, 6849, 6869, 6529, 6539, 6552, 6512, 6599, 6592, 6549, 6562,6571, 6522, 5459, 6589, 544, 688\r\nLaparoscopic surgery:5421, 6841, 6851, 6831, 6861, 6525, 5451, 6581, 6629, 6531, 6554, 6513, 6541, 6564, 6574, 6524\r\nHysteroscopic surgery:6812, 6816, 6823, 6829\r\nVaginal surgery:6859, 7050, 7051, 7052, 7092, 704, 708, 7033,7062,7064,7092, 595,5979,6922,7077\r\nRobotic surgery: 1742\r\nProcedures:-\r\nHysterectomy:-\r\nAbdominal hysterectomy: 6839, 6849\r\nLaparoscopic hysterectomy:6831, 6841\r\nVaginal hysterectomy:6859\r\nAbdominal radical hysterectomy:6869\r\nLaparoscopic radical hysterectomy:6861\r\nMyomectomy:-\r\nMyomectomy:6829\r\nEnucleation of ovarian cyst:-\r\nAbdominal:6529\r\nLaparoscopic:6525\r\nAbdominal salpingo-oophorectomy/oophorectomy:6549,6562,6539,6552\r\nLaparoscopic salpingo-oophorectomy/oophorectomy:6541,6564, 6531,6554\r\nSalingectomy:-\r\nUnilateral:664,6669\r\nBilateral:6652,6663\r\nSalpingectomy with remove of tubal pregnancy:6662\r\nStaging procedures:4052,4053,4011,5423, 5425, 544\r\nFractional curettage or dilatation curettage:6909\r\nConization:672\r\nLEEP:6732\r\nColpocleisis/colpectomy: 708\r\nIncontinence surgery:595,5979\r\nVaginal reconstruction:7050,7051,7052,7092,7062,7064\r\nVulvectomy:715,7161,7162\r\nChemotherapy: 9925\r\nRadiotherapy: 9223,9927\r\nBlood transfusion: 9904, 9905, 9906, 9907\r\nBowel surgery / repair: 4869,4594,4562,4591, 4673,4675,4871, 4620, 4610\r\nUrinary tract surgery/ repair: 5781, 5682, 5674\r\nLISTEOF\r\n\r\n%>\r\n\r\n<%\r\n\r\nlist = formulate(list)  \r\n\r\nsum = 0 \r\n\r\nlist.each_with_index do |i,index|\r\n    \r\n    \r\n    \r\n    \r\n    c = 0 \r\n    items = []\r\n    uitems = {}\r\n    for code in i[:codes]\r\n        # principle diangosis\r\n        \r\n        if k_operation[code]\r\n            \r\n            items += k_operation[code]\r\n            c+= k_operation[code].size \r\n            \r\n            for j in k_operation[code]\r\n                uitems[j[\'patient_id\']] = true\r\n            end\r\n            \r\n        end\r\n        \r\n    end\r\n    i[:count] = c\r\n    i[:ucount] = uitems.keys.size\r\n    i[:items] = items\r\n    sum += c\r\nend\r\n\r\n    surgery_code = \"1742, 6859, 7050, 7051, 7052, 7092, 704, 708, 7033,7062,7064,7092, 595,5979,6922,7077, 6812, 6816, 6823, 6829, 6839, 6849, 6869, 6529, 6539, 6552, 6512, 6599, 6592, 6549, 6562,6571, 6522, 5459, 6589, 544, 688,5421, 6841, 6851, 6831, 6861, 6525, 5451, 6581, 6629, 6531, 6554, 6513, 6541, 6564, 6574, 6524,  \"\r\n    surgery_code = surgery_code.split(\",\").collect{|i| i.strip} \r\n    \r\n    uitems = {}\r\n    for code in surgery_code\r\n        # principle diangosis\r\n        \r\n        if k_operation[code]\r\n            \r\n            for j in k_operation[code]\r\n                uitems[j[\'patient_id\']] = true\r\n            end\r\n            \r\n        end\r\n        \r\n    end\r\n    \r\n    total_surgery = uitems.keys.size\r\n\r\n\r\n\r\n%>\r\n\r\n<div id=\"data_5_p\"></div>\r\n<script>\r\n    $(\'#data_5\').appendTo($(\'#data_5_p\'))\r\n</script>\r\n<%= display list, sum, :data_5%>\r\n\r\n\r\n\r\n\r\n<h1>\r\n\r\n6. Gyneocologic death\r\n<%\r\n    total = 0\r\n    k_discharge.each_pair do |i,ix|\r\n       total+=ix.size \r\n    end\r\n\r\n%>\r\n</h1>\r\n\r\n<%#k_discharge.keys.inspect %>\r\n<%\r\n\r\n    k_discharge[\'1\'] = [] unless k_discharge[\'1\']\r\n    k_discharge[\'2\'] = [] unless k_discharge[\'2\']\r\n    k_discharge[\'3\'] = [] unless k_discharge[\'3\']\r\n    k_discharge[\'9\'] = [] unless k_discharge[\'9\']\r\n    \r\n    \r\n%>\r\n\r\n\r\n<table class=\"table\">\r\n    <tr>\r\n        <th>Complete recovered</th><td><%=k_discharge[\'1\'].size%> (<%=format(\"%.2f\",k_discharge[\'1\'].size.to_f/total*100)%>%)</td>\r\n    </tr>\r\n    \r\n <tr>\r\n        <th>Improved</th><td><%=k_discharge[\'2\'].size%> (<%=format(\"%.2f\",k_discharge[\'2\'].size.to_f/total*100)%>%)</td>\r\n    </tr>\r\n <tr>\r\n \r\n        <th>Not Improved</th><td><%=k_discharge[\'3\'].size%> (<%=format(\"%.2f\",k_discharge[\'3\'].size.to_f/total*100)%>%)</td>\r\n    </tr>    \r\n <tr>\r\n        <th>Death</th><td><%=k_discharge[\'9\'].size%> (<%=format(\"%.2f\",k_discharge[\'9\'].size.to_f/total*100)%>%)</td>\r\n    </tr>   \r\n<tr>\r\n        <th>Total admission</th><th><%=total%></th>\r\n</tr>\r\n<tr>\r\n        <th>Total cases</th><th><%=total_cases%></th>\r\n</tr>\r\n<tr>\r\n        <th>Total surgery</th><th><%=total_surgery%></th>\r\n</tr>\r\n\r\n\r\n    \r\n    \r\n    \r\n</table>\r\n<h1>Death Detail</h1>\r\n<u>\r\n<% for  i in k_discharge[\'9\']\r\n\r\n  pm = pm_map[i[\'_id\']]\r\n            \r\n            p = p_map[pm[\'patient_id\']]\r\n            \r\nif p\r\n        \r\n    \r\n    id = pm[\'_id\']        \r\n            \r\n            \r\n%>\r\n<li>\r\n<%=link_to \"\\\\#{p[\'hn\']}\",\"../Gynecology/show?id=\\\\#{id}\" %>\r\n</li>\r\n<% end %>\r\n<% end %>\r\n</u>\r\n\r\n\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2017-06-08 13:12:50','2017-06-08 13:12:50','gynecology_report_partial',''),(3053,'login',1207,4,'<html>\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n\r\n <!-- Bootstrap framework -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap.min.css\" />\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap-responsive.min.css\" />\r\n        <!-- theme color-->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n        <!-- tooltip -->    \r\n			<link rel=\"stylesheet\" href=\"/gebo/lib/qtip2/jquery.qtip.min.css\" />\r\n        <!-- main styles -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/style.css\" />\r\n<style>\r\ninput, textarea, select, .uneditable-input { height:28px;}\r\n.login_page .cnt_b { padding:15px 0}\r\n</style>            \r\n</head>\r\n<body class=\"login_page\" style=\"background:url(/esm/cusys/forensic/bgContent.jpg) center no-repeat;\r\nbackground-size: cover;\">\r\n<script src=\"/gebo/js/jquery.min.js\"></script>\r\n<script src=\"/gebo/js/jquery.actual.min.js\"></script>\r\n<script src=\"/gebo/lib/validation/jquery.validate.min.js\"></script>\r\n<script src=\"/gebo/bootstrap/js/bootstrap.min.js\"></script>\r\n<%\r\n	p = {}\r\n	if @current_project \r\n	tp = @current_project.get_params if @current_project \r\n	p = tp if tp\r\n	end\r\n	title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"ESM:Innovation as a Service\"\r\n	bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#eee\"\r\n	logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n%>\r\n\r\n<%\r\n    user = \'\'\r\n	user = params[:user][:login] if params[:user]\r\n%>\r\n<%= form_for :user, :action=>\'login\' do|form|%>\r\n\r\n	<div class=\"login_box\" style=\"height:350px;top:0;bottom: 0;left: 0;right: 0;margin: auto;\">\r\n		\r\n		<form action=\"dashboard.html\" method=\"post\" id=\"login_form\">\r\n			<div class=\"formSep\" style=\"text-align:center;padding-top:5px\"><a href=\"/\">\r\n            <img src=\"/esm/cusys/forensic/logo_chula.png\" width=\"300\">\r\n            </a>\r\n			</div>    \r\n			<% if flash[:error] %>\r\n			<div class=\"alert alert alert-login\">\r\n				<%= flash[:error] %>\r\n			</div>\r\n			<% else %>\r\n			<div class=\"alert alert alert-login\">\r\n				Please login to continue \r\n			</div>\r\n			<% end %>\r\n			\r\n			\r\n	   	\r\n\r\n			\r\n			<div class=\"cnt_b\">\r\n			\r\n					\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-user\"></i></span>\r\n						<%= form.text_field \"login\", :size => 20,:id=>\'user_login\',:placeholder=>\"Email or Login ID\",\'data-icon\'=>\"user\",:value=>user%>\r\n					   \r\n					</div>\r\n				</div>\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-lock\"></i></span>\r\n						<%= form.password_field \"password\", :size => 20,:id=>\'user_password\',:placeholder=>\"Password\",\'data-icon\'=>\"closed-lock\"%>\r\n						\r\n					</div>\r\n				</div>\r\n					<%  unless @current_solution %>\r\n				<span id=\"solution_id_toggle\"><center><a href=\"javascript:$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\">...</a></center></span>	\r\n				<div class=\"formRow\" id=\"solution_id\" style=\"display:none\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-book\"></i></span>\r\n						<%= text_field_tag \"user[esm]\",cookies[:esm], :size => 20,:id=>\'esm\',:placeholder=>\"Solution ID\",\'data-icon\'=>\"settings\"%>\r\n					</div>\r\n				</div>\r\n				<script>\r\n				    $(document).ready(function(){\r\n				<% if cookies[:esm] %>\r\n					$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\r\n				<%  end %>\r\n			  });\r\n				</script>\r\n				\r\n					<% else %>\r\n						<%= form.hidden_field \"esm\", :value=> @current_solution.name %>\r\n						<%= form.hidden_field \"project_id\", :value=> @current_project.id if @current_project%>\r\n					<% end %>\r\n					\r\n					\r\n				<div class=\"formRow clearfix\">\r\n					<label class=\"checkbox\"><input id=\"ck\" name=\'remember\' type=\"checkbox\" /> Remember me</label>\r\n				</div>\r\n			</div>\r\n			<div class=\"btm_b clearfix\" >\r\n			<button class=\"btn pull-right\" type=\"submit\">Sign In</button>\r\n				\r\n			\r\n				\r\n			</div>  \r\n		</form>\r\n		\r\n		\r\n		\r\n	\r\n	</div>\r\n	\r\n	<div class=\"links_b links_btm clearfix\" >\r\n	\r\n	\r\n	</div>\r\n		\r\n	</div>  \r\n   <% end %>\r\n\r\n    <script>\r\n        $(document).ready(function(){\r\n            \r\n			//* boxes animation\r\n			form_wrapper = $(\'.login_box\');\r\n            $(\'.linkform a,.link_reg a\').on(\'click\',function(e){\r\n				var target	= $(this).attr(\'href\'),\r\n					target_height = $(target).actual(\'height\');\r\n				$(form_wrapper).css({\r\n					\'height\'		: form_wrapper.height()\r\n				});	\r\n				$(form_wrapper.find(\'form:visible\')).fadeOut(400,function(){\r\n					form_wrapper.stop().animate({\r\n                        height	: target_height\r\n                    },500,function(){\r\n                        $(target).fadeIn(400);\r\n                        $(\'.links_btm .linkform\').toggle();\r\n						$(form_wrapper).css({\r\n							\'height\'		: \'\'\r\n						});	\r\n                    });\r\n				});\r\n				e.preventDefault();\r\n			});\r\n			\r\n			//* validation\r\n			$(\'#login_form\').validate({\r\n				onkeyup: false,\r\n				errorClass: \'error\',\r\n				validClass: \'valid\',\r\n				rules: {\r\n					username: { required: true, minlength: 3 },\r\n					password: { required: true, minlength: 3 }\r\n				},\r\n				highlight: function(element) {\r\n					$(element).closest(\'div\').addClass(\"f_error\");\r\n				},\r\n				unhighlight: function(element) {\r\n					$(element).closest(\'div\').removeClass(\"f_error\");\r\n				},\r\n				errorPlacement: function(error, element) {\r\n					$(element).closest(\'div\').append(error);\r\n				}\r\n			});\r\n        });\r\n    </script>\r\n\r\n\r\n		<script type=\"text/javascript\">\r\n		try{document.getElementById(\'user_login\').focus();}catch(e){}\r\n		</script>\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n\r\n    \r\n\r\n',NULL,NULL,NULL,'2017-06-09 00:39:00','2017-06-09 00:39:00','login',''),(3056,'document_name',1215,1,'\'patient\'',NULL,NULL,NULL,'2017-06-09 03:34:52','2017-06-09 03:34:52',NULL,NULL),(3057,'document_name',1216,1,'\'region\'',NULL,NULL,NULL,'2017-06-09 04:19:43','2017-06-09 04:19:43',NULL,NULL),(3058,'document_name',1217,1,'\'filter\'',NULL,NULL,NULL,'2017-06-09 06:30:16','2017-06-09 06:30:16',NULL,NULL),(3059,'manage',628,2,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n%>\r\n<%= patient_model.count %> | <%= module_model.count %>',NULL,NULL,NULL,'2017-06-09 06:32:29','2017-06-09 06:32:29','manage',''),(3060,'config',1207,1,'services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| \r\ni if  i.name!=\'appointment\' and i.name!=\'live_document\' and i.name!=\'document\' and i.name!=\'billing\'}.compact\r\n[\r\n{:name=>\'Form\',:open=>true,:actions=>services.collect{|i| {:name=>i.name.camelize,:service=>i.name,:link=>\"../\\\\#{i.name.camelize}/index\"}} }]\r\n\r\n',NULL,NULL,NULL,'2017-06-10 04:11:16','2017-06-10 04:11:16','config',''),(3061,'document_name',1219,1,'\'anatomy_group\'',NULL,NULL,NULL,'2017-06-10 05:06:47','2017-06-10 05:06:47',NULL,NULL),(3062,'form',1218,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   models = get_model\r\n   symptom_list =  models[:symptom].collection.find().to_a\r\n   symptom_group_list =  models[:symptom_group].collection.find().to_a\r\n   \r\n   anatomy_list =  models[:anatomy].collection.find().to_a\r\n   anatomy_group_list =  models[:anatomy_group].collection.find().to_a\r\n   sg_map = {}\r\n   \r\n   for i in symptom_list\r\n    sg_map[i[\'group\']] = [] unless sg_map[i[\'group\']]\r\n    sg_map[i[\'group\']] << i\r\n    \r\n   end\r\n\r\n   \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n\r\n<div id=\"current\" class=\"finding alert alert-info hide\" >\r\n        <%=hidden_field_tag \'symptom_id\', \'\', :id=>\"symptom_id\" %>\r\n        <%=hidden_field_tag \'anatomy_list\', \'\', :id=>\"anatomy_list\" %> \r\n        <%=hidden_field_tag \'summary\', \'\',  :id=>\"summary\" %>\r\n        <center><span style=\"font-size:1.3em\" id=\'text\'></span></center>\r\n</div>\r\n\r\n<div class=\"row-fluid hide\" style=\"border:0px solid\" id=\"symptom-view\" >\r\n    <div class=\"span12\">\r\n        <%#sympton_list.inspect %>\r\n    \r\n						\r\n							<div id=\"accordion-1\" class=\"accordion\">\r\n							\r\n							\r\n								\r\n								    <% for g in symptom_group_list \r\n								        symptoms = sg_map[g[\'_id\']]\r\n								        if symptoms\r\n								    %>\r\n								<div class=\"accordion-group s_group s_group_<%=g[\'type\']%>\">\r\n									<div class=\"accordion-heading\">\r\n										<a href=\"#collapse-<%=g[\'_id\']%>\" data-parent=\"#accordion-<%=g[\'type\']%>\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n											<%=g[\'name\']%>\r\n										</a>\r\n									</div>\r\n									<div class=\"accordion-body collapse\" id=\"collapse-<%=g[\'_id\']%>\" style=\"height: 0\">\r\n										<div class=\"accordion-inner\">\r\n										    <div class=\"row-fluid\">\r\n                                            <% symptoms.each_with_index do |i,index|  %>\r\n                                            <%=link_to i[\'name\'], \"javascript:select_symptom(\'\\\\#{i[\'_id\']}\')\" , :class=>\'btn span6\',:style=>\"font-size:1.2em\"%>\r\n                                          \r\n                                            <% if index%2==1 and index!=0%>\r\n                                            </div>\r\n                                            <div class=\"row-fluid\">\r\n                                           \r\n                                            <% end %>\r\n                                            <% end %>\r\n                                            </div>\r\n                                            \r\n										</div>\r\n									</div>\r\n									<% end %>\r\n							\r\n								</div>\r\n							<% end %>\r\n							\r\n					\r\n						\r\n    </div>\r\n</div>\r\n<div class=\"row-fluid hide\"  style=\"border:0px solid\" id=\"anatomy-view\">\r\n    <div class=\"span12\">\r\n        \r\n        <%#anatomy_list.inspect %>\r\n        <% for i in anatomy_group_list %>\r\n        <div id=\"<%=i[\'_id\']%>\" class=\"anatomy-group\">\r\n        <%=link_to \'Home\', \'javascript:anatomy_home()\',:class=>\'btn btn-info\' unless i[\'name\'].index(\'overview\') %>\r\n        <%=link_to \'Back\', \'javascript:anatomy_back()\',:class=>\'btn btn-info\' unless i[\'name\'].index(\'overview\') %>  <br/>  \r\n        <center><%= image_tag i[\'path\'], :usemap=>\"#map-\\\\#{i[\'_id\']}\" %></center>\r\n <map name=\"map-<%=i[\'_id\']%>\">\r\n<%= i[\'script\'].html_safe %>\r\n</map>\r\n            \r\n        </div>\r\n        \r\n        <% end %>\r\n        \r\n        \r\n    </div>\r\n</div>\r\n<div class=\"row-fluid\"  style=\"border:0x solid\">\r\n    <div class=\"span12\">\r\n        \r\n    </div>\r\n</div>\r\n\r\n\r\n<div id=\"finding-template\" class=\"hide\">\r\n\r\n    <%=hidden_field_tag \"x[]\", \'[]\', :id=>\'tt_record\' %>\r\n\r\n\r\n   <div id=\"list\" class=\"alert\">\r\n       List<br>\r\n   </div>\r\n   \r\n   <div class=\"\">\r\n   <%=link_to \'Add\', \"#\" ,:id=>\"tt_add_button\" ,:class=>\'btn\'%>\r\n   </div>\r\n   \r\n   \r\n</div>\r\n\r\n\r\n<div id=\"finding-item-template\" class=\"hide\">\r\n        <%=hidden_field_tag \'symptom_id\', \'\', :id=>\"symptom_id\" %>\r\n        <%=hidden_field_tag \'anatomy_list\', \'\', :id=>\"anatomy_list\" %> \r\n    \r\n        <%=link_to \'Del\' , \'javascript:delete_finding()\',:id=>\"del_finding\",:data=>{:confirm=>\'Are you sure?\'},:class=>\'btn btn-danger  \' %>\r\n    \r\n        <%=text_field_tag \'summary\', \'\',  :id=>\"summary\",:class=>\'span10\',:style=>\"vertical-align:top;font-size:1.2em;\" %>\r\n        <%=link_to \'+\' , \'javascript:select_more_anatomy()\',:id=>\"more_anatomy\", :class=>\'btn \' %>\r\n        <%#link_to \'Edit\' , \'\',:id=>\"edit_finding\", :class=>\'btn \' %>\r\n            \r\n\r\n</div>\r\n\r\n\r\n<script>\r\n        \r\n    var symptom_list = <%= symptom_list.to_json.html_safe %>    \r\n    var anatomy_list = <%= anatomy_list.to_json.html_safe %>\r\n    var symptom_group_list = <%= symptom_group_list.to_json.html_safe %>    \r\n    var anatomy_group_list = <%= anatomy_group_list.to_json.html_safe %>    \r\n    \r\n    var symptom_map = {}\r\n    var anatomy_map = {}\r\n    var symptom_group_map = {}\r\n    var anatomy_group_map = {}\r\n    var a_name_map = {}\r\n    var ag_name_map = {}\r\n    \r\n    var anatomy_stack = []\r\n    \r\n    \r\n    var current_mode = null;\r\n    var current_group = null;\r\n    var current_anatomy = null;\r\n    var current_symptom = null;\r\n    var current_finding = null;\r\n    var current_home = \'overview\';\r\n    \r\n    var run_id = 0;\r\n    var current_id = 0;\r\n    \r\n    for(var id in symptom_list){\r\n        i = symptom_list[id];\r\n        symptom_map[i[\'_id\']] = i;\r\n    }\r\n    \r\n    for(var id in anatomy_list){\r\n        i = anatomy_list[id];\r\n        anatomy_map[i[\'_id\']] = i;\r\n        a_name_map[i[\'name\']] = i;\r\n    }\r\n    \r\n    for(var id in symptom_group_list){\r\n        i = symptom_group_list[id];\r\n        symptom_group_map[i[\'_id\']] = i;\r\n    }\r\n    \r\n    for(var id in anatomy_group_list){\r\n        i = anatomy_group_list[id];\r\n        anatomy_group_list[i[\'_id\']] = i;\r\n        ag_name_map[i[\'name\']] = i;\r\n    }\r\n    \r\n    \r\n        \r\n   \r\n    \r\n    function setup(id, s_group,home){\r\n        \r\n        obj =  $(\'#\'+id)\r\n       \r\n        obj.css(\"width\",\"100%\")\r\n        var template = $(\'#finding-template\').clone();\r\n       template.removeClass(\"hide\");\r\n       record = template.find(\"#tt_record\")\r\n       record.attr(\"name\",\"record[\"+id+\"]\")\r\n       record.val($(\'#data-\'+id).val())\r\n      \r\n        list = template.find(\'#list\')\r\n        \r\n\r\n       ids =  JSON.parse($(\'#data-\'+id).val())\r\n       for(ix=0;ix<ids.length;ix++){\r\n           i = ids[ix]\r\n        doc_id = \"<%=this.document_name%>[\"+id+\"][\"+i+\"]\"   \r\n        data_id = \'#data-<%=this.document_name%>-\'+id+\'-\'+i+\'-\'\r\n        var templatei = $(\'#finding-item-template\').clone();     \r\n           \r\n        templatei.attr(\"id\",\"<%=this.document_name%>-\"+i)\r\n        \r\n        symptom_id = templatei.find(\'#symptom_id\')\r\n        symptom_id.attr(\'name\',doc_id+\'[symptom_id]\')\r\n        symptom_id.val($(data_id+\'symptom_id\').val())\r\n        \r\n        anatomy_list = templatei.find(\'#anatomy_list\')\r\n        anatomy_list.attr(\'name\',doc_id+\'[anatomy_list]\')\r\n        anatomy_list.val($(data_id+\'anatomy_list\').val())\r\n        \r\n        summary = templatei.find(\'#summary\')\r\n        summary.attr(\'name\',doc_id+\'[summary]\')\r\n        summary.val($(data_id+\'summary\').val())\r\n        \r\n        \r\n                \r\n        more = templatei.find(\'#more_anatomy\')\r\n        more.attr(\"href\",\"javascript:select_more_anatomy(\'\"+i+\"\')\")\r\n        more.attr(\"s_group\",current_group)\r\n        more.attr(\"home\",current_home)\r\n        \r\n        edit = templatei.find(\'#edit_finding\')\r\n        edit.attr(\"href\",\"javascript:edit_finding(\'\"+i+\"\')\")\r\n        \r\n        del = templatei.find(\'#del_finding\')\r\n        del.attr(\"href\",\"javascript:delete_finding(\'\"+i+\"\')\")\r\n       \r\n        templatei.show()   \r\n        list.append(templatei);\r\n        // list.append(i)\r\n            //  list = $(\'#\'+id).find(\'#list\')\r\n       \r\n       }\r\n\r\n        // alert(list)\r\n       \r\n       obj.empty()\r\n      \r\n       template.attr(\"id\", id)\r\n       template.attr(\"s_group\",s_group)\r\n       add_btn = template.find(\"#tt_add_button\")\r\n       add_btn.attr(\"value\",id)\r\n       add_btn.attr(\"s_group\",s_group)\r\n       add_btn.attr(\"home\",home)\r\n       \r\n       \r\n       add_btn.click(create_finding);\r\n       \r\n       \r\n       \r\n       list = template.find(\"#list\")\r\n       \r\n       \r\n       \r\n       obj.append(template);\r\n       \r\n     \r\n      \r\n   \r\n        // template.appendTo(obj)\r\n    }\r\n    \r\n    \r\n    \r\n    \r\n    setup(\'rot_list\',\'2\',\'overview\')\r\n    setup(\'wound_list\',\'1\',\'overview\')\r\n    setup(\'bone_list\',\'3\',\'bone-overview\')\r\n    setup(\'rigor_list\',\'4\',\'overview\')\r\n    setup(\'liver_list\',\'5\',\'overview\')\r\n    function create_finding(){\r\n        // alert()\r\n        run_id += 1;\r\n        current_id = run_id;\r\n        // setup list \r\n        // filter group\r\n        // show symptom\r\n        current_group = $(this).attr(\"s_group\")\r\n        current_home = $(this).attr(\"home\")\r\n        // alert(current_group)\r\n        current_mode = $(this).attr(\"value\");\r\n         $(\'#current\').find(\'#anatomy_list\').val(\'[]\')\r\n         $(\'#current\').find(\'#text\').html(\'...\')\r\n        \r\n        $(\'.s_group\').hide()\r\n        $(\'.s_group_\'+current_group).show()\r\n        anatomy_home();\r\n        show_finding();\r\n        show_symptom();\r\n    }\r\n\r\n    function edit_finding(finding){\r\n        // show editor\r\n        alert(\'edit\')\r\n    }\r\n    \r\n    function delete_finding(finding){\r\n        // remove that finding\r\n     \r\n        item = $(\'#<%=this.document_name%>-\'+finding)\r\n        item.remove();\r\n    }\r\n    \r\n    function add_anatomy(finding){\r\n        // setup finding\r\n        // show anatomy\r\n    }\r\n    \r\n    function select_symptom(symptom){\r\n        // hide_symtom\r\n        // show_anatomy\r\n    \r\n        symptom = symptom_map[symptom]\r\n         $(\'#current\').find(\'#symptom_id\').val(symptom[\'_id\'])\r\n         $(\'#current\').find(\'#text\').html(\'\'+symptom[\'name\']+\'ที่...\')\r\n        // alert(symptom[\'name\'])\r\n        hide_symptom();\r\n        show_anatomy();\r\n    }\r\n    \r\n    function a(anatomy){\r\n        select_anatomy(anatomy)\r\n    }\r\n    function g(anatomy){\r\n        select_anatomy_group(anatomy)\r\n    }\r\n    \r\n    function select_more_anatomy(id){\r\n        current_id = id;\r\n        \r\n        current = $(\'#current\');\r\n        \r\n        item = $(\'#<%=this.document_name%>-\'+id)\r\n\r\n        symptom_id = item.find(\'#symptom_id\')\r\n        current.find(\'#symptom_id\').val(symptom_id.val())\r\n          \r\n        anatomy_list = item.find(\'#anatomy_list\')\r\n        current.find(\'#anatomy_list\').val(anatomy_list.val())\r\n\r\n        summary = item.find(\'#summary\')\r\n        current.find(\'#summary\').val(summary.val())\r\n        show_finding();\r\n        show_anatomy();\r\n        \r\n        \r\n\r\n    }\r\n    \r\n    function select_anatomy(anatomy){\r\n        // hide_anatomy\r\n        // add_finding\r\n        // if finding is exist then add more anatomy to list\r\n        //\r\n        // alert(anatomy);\r\n        current = $(\'#current\');\r\n\r\n\r\n        anatomy = a_name_map[anatomy]\r\n        ids =  JSON.parse(current.find(\'#anatomy_list\').val())\r\n        if(anatomy[\'_id\']){\r\n        ids.push(anatomy[\'_id\'])\r\n        }else{\r\n            alert(\'Not found \'+anatomy)\r\n        }\r\n        //   alert(JSON.stringify(ids))\r\n        current.find(\'#anatomy_list\').val( JSON.stringify(ids))\r\n        // alert(anatomy[\'_id\'])\r\n        \r\n        \r\n        add_new_finding();\r\n        \r\n        hide_anatomy();\r\n        hide_finding();\r\n        \r\n    }\r\n    \r\n    \r\n    \r\n    // autopsy-wound_list-593c1ed7790f9b6126000001-symptom_id\r\n    \r\n    // autopsy[wound_list][593c1ed7790f9b6126000001][symptom_id]\r\n    \r\n    function add_new_finding(){\r\n        current = $(\'#current\');\r\n        // final generate text \r\n        // add tag to list \r\n        symptom = symptom_map[current.find(\'#symptom_id\').val()]\r\n        ids =  JSON.parse(current.find(\'#anatomy_list\').val())\r\n        anatomy_list = []\r\n        locations = \'\'\r\n        ls = []\r\n        for(var id in ids){\r\n            i = ids[id];\r\n            anatomy = anatomy_map[i]\r\n            anatomy_list.push(anatomy)\r\n            // console.log(anatomy_map)\r\n            ls.push(anatomy[\'text_th\'])\r\n        }\r\n        \r\n        doc_id = \"<%=this.document_name%>[\"+current_mode+\"][\"+current_id+\"]\"\r\n        \r\n        locations = ls.join(\",\")\r\n        \r\n        text = \"\"\r\n        symptom_text = symptom[\'text_th\']\r\n        if(symptom_text==\'\') symptom_text = symptom[\'name\']\r\n        text = \"\"+symptom_text+\"ที่\"+locations\r\n        \r\n        \r\n        current.find(\"#summary\").val(text)\r\n        \r\n        var template = $(\'#finding-item-template\').clone();\r\n        \r\n        record = $(\'#<%=this.document_name%>-\'+current_id)\r\n        console.log(record)\r\n        if (record.length>0){\r\n            template = record\r\n        }else{\r\n            template.show();\r\n            list = $(\'#\'+current_mode).find(\'#list\')\r\n            list.append(template);\r\n            \r\n        }\r\n        \r\n        \r\n        template.attr(\"id\",\"<%=this.document_name%>-\"+run_id)\r\n        \r\n        symptom_id = template.find(\'#symptom_id\')\r\n        symptom_id.attr(\'name\',doc_id+\'[symptom_id]\')\r\n        symptom_id.val(symptom[\'_id\'])\r\n        \r\n        anatomy_list = template.find(\'#anatomy_list\')\r\n        anatomy_list.attr(\'name\',doc_id+\'[anatomy_list]\')\r\n        anatomy_list.val(current.find(\'#anatomy_list\').val())\r\n        \r\n        summary = template.find(\'#summary\')\r\n        summary.attr(\'name\',doc_id+\'[summary]\')\r\n        summary.val(current.find(\"#summary\").val())\r\n        \r\n        \r\n        more = template.find(\'#more_anatomy\')\r\n        more.attr(\"href\",\"javascript:select_more_anatomy(\'\"+current_id+\"\')\")\r\n        more.attr(\"s_group\",current_group)\r\n        more.attr(\"home\",current_home)\r\n        \r\n        edit = template.find(\'#edit_finding\')\r\n        edit.attr(\"href\",\"javascript:edit_finding(\'\"+current_id+\"\')\")\r\n        \r\n        del = template.find(\'#del_finding\')\r\n        del.attr(\"href\",\"javascript:delete_finding(\'\"+current_id+\"\')\")\r\n        \r\n       \r\n    }\r\n\r\n    function show_anatomy(){\r\n        $(\'#anatomy-view\').show()\r\n    }\r\n    \r\n    function hide_anatomy(){\r\n        $(\'#anatomy-view\').hide()\r\n    }\r\n    \r\n    \r\n    function show_symptom(){\r\n        \r\n        $(\'#symptom-view\').show()\r\n    }\r\n    \r\n    function hide_symptom(){\r\n        $(\'#symptom-view\').hide()\r\n\r\n    }\r\n    \r\n    function show_finding(){\r\n        obj = $(\'#\'+current_mode)\r\n        obj.find(\'.non-finding\').hide();\r\n        $(\'.finding\').show();\r\n    }\r\n    \r\n    function hide_finding(){\r\n        obj = $(\'#\'+current_mode)\r\n        obj.find(\'.non-finding\').show();\r\n        $(\'.finding\').hide();\r\n    }\r\n    \r\n    function select_anatomy_group(anatomy_group){\r\n        // hide current_group\r\n        // show next_group\r\n        \r\n        $(\'.anatomy-group\').each(function(){\r\n             $( this ).hide();\r\n        })\r\n        \r\n        anatomy_group = ag_name_map[anatomy_group]\r\n        anatomy_stack.push(current_anatomy)\r\n        current_anatomy = anatomy_group\r\n        \r\n        // alert(\"show group \"+ anatomy_group[\'_id\'])\r\n        \r\n        $(\'#\'+anatomy_group[\"_id\"]).show();\r\n        \r\n    }\r\n    function anatomy_home(){\r\n        anatomy_stack = [];\r\n        select_anatomy_group(current_home)\r\n    }\r\n    function anatomy_back(){\r\n        anatomy_group = anatomy_stack.slice(-1)[0]\r\n        anatomy_stack.pop()\r\n        select_anatomy_group(anatomy_group[\'name\'])\r\n    }\r\n    \r\n    anatomy_home()\r\n    $(document).ready(function(){\r\n        $(\'.tabbable\').css(\"width\",\"100%\")\r\n    })\r\n    \r\n    $(\'.nav-tabs a\').click(function(){\r\n        // alert(\'difjdf\')\r\n        hide_finding();\r\n        hide_anatomy();\r\n        hide_symptom();\r\n    })\r\n    \r\n    $(\'#tab-F2680283681-tab\').find(\'a\').html(\'<img src=\"/esm/cusys/forensic/1dinfo.jpg\" width=\"70\">\')\r\n    $(\'#tab-F1115545538-tab\').find(\'a\').html(\'<img src=\"/esm/cusys/forensic/2minfo.jpg\" width=\"70\">\')\r\n    $(\'#tab-F1636318776-tab\').find(\'a\').html(\'<img src=\"/esm/cusys/forensic/3pinfo.jpg\" width=\"70\">\')\r\n    $(\'#tab-F2350094887-tab\').find(\'a\').html(\'<img src=\"/esm/cusys/forensic/4binfo.jpg\" width=\"70\">\')\r\n    $(\'#tab-F1599195989-tab\').find(\'a\').html(\'<img src=\"/esm/cusys/forensic/5riginfo.jpg\" width=\"70\">\')\r\n    $(\'#tab-F6106470445-tab\').find(\'a\').html(\'<img src=\"/esm/cusys/forensic/6livinfo.jpg\" width=\"70\">\')\r\n    $(\'#tab-F6930399623-tab\').find(\'a\').html(\'<img src=\"/esm/cusys/forensic/7vinfo.jpg\" width=\"70\">\')\r\n    \r\n    <% \r\n        \r\n        l = %w{age_group body_group skin_group eye_color hair_color upper lower death_in death_at}\r\n        \r\n    %>\r\n    var status_list = <%=l.to_json.html_safe%>\r\n    \r\n    function update_status(){\r\n \r\n       editor =  $(\'#data-autopsy_summary\').data(\"kendoEditor\");\r\n       command =\"ศพ เพศ\"\r\n       \r\n       command += \'ชาย\'\r\n       \r\n       command += \' สัญญชาติ\'\r\n       command += \'ไทย\'\r\n        \r\n       if($(\'#data-age_group\').val()){    \r\n       command += \' วัย\'           \r\n       command += $(\'#data-age_group option:selected\').text();\r\n       }\r\n       \r\n       if($(\'#data-body_group\').val()){    \r\n       command += \' รูปร่าง\'           \r\n       command += $(\'#data-body_group option:selected\').text();\r\n       }\r\n       \r\n       if($(\'#data-skin_group\').val()){    \r\n       command += \' ผิวสี\'           \r\n       command += $(\'#data-skin_group option:selected\').text();\r\n       }\r\n       \r\n       if($(\'#data-eye_color\').val()){    \r\n       command += \' ตาสี\'           \r\n       command += $(\'#data-eye_color option:selected\').text();\r\n       }\r\n       \r\n       if($(\'#data-hair_color\').val()){    \r\n       command += \' ผมสี\'           \r\n       command += $(\'#data-hair_color option:selected\').text();\r\n       }\r\n       \r\n       if($(\'#data-upper\').val()){    \r\n       command += \' ท่อนบนสวม\'           \r\n       command += $(\'#data-upper option:selected\').text();\r\n       }\r\n       \r\n       if($(\'#data-lower\').val()){    \r\n       command += \' ท่อนล่างสวม\'           \r\n       command += $(\'#data-lower option:selected\').text();\r\n       }\r\n      \r\n       if($(\'#data-death_in\').val()){    \r\n       command += \' สภาพศพพบเสียชีวิตในท่า\'           \r\n       command += $(\'#data-death_in option:selected\').text();\r\n       }\r\n       \r\n       if($(\'#data-death_at\').val()){    \r\n       command += \' บน\'           \r\n       command += $(\'#data-death_at option:selected\').text();\r\n       }\r\n    //   ศพ เพศ ชาย สัญชาติ ไทย กลางคน รูปร่างสมส่วน ผิวสีดำแดง ผใสีดำ ท่อนบนสวมเสื้อยืดแขนสั้น<br />\r\n//   สภาพศพพบเสียชีวิตในท่านอนหงาย บนพ\r\n       \r\n       \r\n       \r\n        editor.value(command)\r\n     \r\n    }\r\n    for(ix=0;ix<status_list.length;ix++){\r\n        i = status_list[ix];\r\n        $(\'#data-\'+i).change(update_status);\r\n        \r\n        \r\n    }\r\n\r\n    \r\n</script>\r\n\r\n\r\n   \r\n\r\n\r\n',NULL,NULL,NULL,'2017-06-10 05:48:38','2017-06-10 05:48:38','form',''),(3063,'export_dialyzer',378,3,'<%\r\n    def get_document_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].strip\r\n                    tmp[:list] << x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    fm = get_document_field \'dialyzer\'\r\n    \r\n	@module_name = @current_project.name+\'#\'+ this.table_name \r\n	@ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@patient_doc = @ehr_project.get_document \'patient\'\r\n	@module_doc = @ehr_project.get_document \'patient_module\'\r\n	@ehr_model = @ehr_project.get_model()\r\n	@patient_model = @ehr_model[:patient]\r\n	@module_model = @ehr_model[:patient_module]\r\n	\r\n	\r\n	@document = get_document(this.document_name)\r\n	\r\n	doc = @document\r\n	\r\n# 	data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n# 	data = get_model(this.document_name).limit(200) \r\n    data = get_model(this.document_name).sort(\'created_at desc\').limit(100)\r\n	\r\n	fields = @document.fields\r\n	fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n	fields << \'created_at\'\r\n	fields << \'updated_at\'\r\n%>\r\n<table >\r\n	<tr>\r\n	    <td>No.</td>\r\n		<td>HN</td>\r\n		<td>Name</td>\r\n		<td>Gender</td>\r\n		<td>Birth Date</td>\r\n		<td>Age</td>\r\n		<td>Record date</td>\r\n<%\r\n			for i in fields \r\n			    if i[0] != \'dialyzermm\'\r\n%>\r\n		<td><%= i[1] %></td>\r\n<%\r\n                else \r\n%>\r\n        <td>Dialyzer count</td>\r\n<%\r\n                    fm.each do |k,v|\r\n%>\r\n        <td><%= v[:name] %></td>\r\n<%                  end\r\n                end\r\n            end \r\n%>\r\n	</tr>\r\n<% \r\n    n = 0\r\n    a_dia = get_model[:dialyzer].all\r\n    g_dia = a_dia.group_by{|i| i.id}\r\n    for i in data \r\n		@record = i\r\n		\r\n		age = 0\r\n		hn = nil\r\n		\r\n		p = @patient_model.new\r\n		m = @module_model.collection.find(:module_id=>i.id).first\r\n		if m \r\n		\r\n		    patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n		    if patient\r\n		        bdate = 0\r\n		        bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n		        age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n		\r\n		        p = patient\r\n		        p[\'record_date\'] = m[\'date\']\r\n		\r\n		    end\r\n		end\r\n		\r\n		y = 1\r\n		dc = i[\'dialyzermm\'].count\r\n		if dc != 0\r\n		    y = dc\r\n		end\r\n		\r\n		n += 1\r\n		\r\n		1.upto(y) do |x|\r\n%>\r\n	<tr>\r\n	    <td><%= n %>.</td>\r\n		<td><%=p[\'hn\'] %></td>\r\n		<td><%=p[\'first_name\']%> <%=p[\'last_name\']%></td>\r\n		<td><%=p[\'gender\']%></td>\r\n		<td><%=p[\'birth_date\'].strftime(\'%d/%m/%Y\') if p[\'birth_date\'] %></td>\r\n		<td><%=age%></td>\r\n		<td><%=p[\'record_date\'].strftime(\'%d/%m/%Y\') if p[\'record_date\']%></td>\r\n<%\r\n			@document = doc\r\n			@fields = @document.fields\r\n			\r\n			for j in fields \r\n			    if j[0] != \'dialyzermm\'\r\n			\r\n			        if i[j[0]]\r\n%>\r\n		<td><%= render_value j[0] %></td>\r\n                    <% else %>\r\n		<td>.</td>\r\n                    <% end %>\r\n                <% else %>\r\n        <td><%= dc %></td>\r\n        <% if dc == 0 %>\r\n        <td>.</td>\r\n        <td>.</td>\r\n        <td>.</td>\r\n        <% \r\n            else \r\n                obj = i[j[0]][x - 1]\r\n                # a.each do |z|\r\n                    q = !g_dia[obj].nil? ? g_dia[obj][0] : {}\r\n        %>\r\n        <td><%= q[:dialyzer_number] %></td>\r\n        <td><%= q[:filtration_life_time] %></td>\r\n        <td><%= q[:dialyzer_note] %></td>\r\n                <%# end %>\r\n        <%  end %>\r\n                <% end %>\r\n            <% end %>\r\n	</tr>\r\n	    <% end %>\r\n<% end %>\r\n</table>',NULL,NULL,NULL,'2017-06-13 15:59:20','2017-06-13 15:59:20','export_dialyzer',''),(3064,'patient',1217,2,'<%\r\n    mode = \'new\'\r\n    if request.post?\r\n        if params[:commit].include? \'Removed\'\r\n            obj = params[:rec][:pat]\r\n            fil = get_model[:filter]\r\n            obj.each do |i|\r\n                fil.create :link_object_id=>i, :module_name=>\'www#patient\', :status=>\'removed\'\r\n            end\r\n        elsif params[:commit].include? \'Select\'\r\n            obj = params[:rec][:pat]\r\n            sel_pat = get_model[:filter].where(:link_object_id=>obj, :status=>\'selected\').all\r\n            sel_ids = sel_pat.collect{|i| i[:link_object_id].to_s} if sel_pat\r\n            obj = obj - sel_ids\r\n            fil = get_model[:filter]\r\n            obj.each do |i|\r\n                fil.create :link_object_id=>i, :module_name=>\'www#patient\', :status=>\'selected\'\r\n            end\r\n        elsif params[:commit].include? \'New\'\r\n            mode = \'new\'\r\n        elsif params[:commit].include? \'All\'\r\n            mode = \'all\'\r\n        elsif params[:commit].include? \'Filtered\'\r\n            mode = \'filter\'\r\n        elsif params[:commit].include? \'Reject\'\r\n            mode = \'removed\'\r\n        end\r\n    end\r\n    \r\n    # initial code\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	m_pat = @ehr_model[:patient]\r\n	m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	a_prov = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#provider\").all\r\n	pro_ids = a_prov.collect{|i| i[:module_id]}\r\n	pat_ids = a_prov.collect{|i| i[:patient_id]}\r\n	\r\n\r\n	\r\n	a_filter = get_model[:filter].where(:module_name=>\'www#patient\', :status=>\'removed\').all\r\n# 	fil_pat = a_filter.collect{|i| BSON::ObjectId.from_string(i[:link_object_id])}\r\n		fil_pat = a_filter.collect{|i| i[:link_object_id]}\r\n\r\n\r\n    # fil_pat = []\r\n	\r\n	if mode == \'filter\'\r\n	    s_pat = get_model[:filter].where(:module_name=>\'www#patient\', :status=>\'selected\').all\r\n        sel_pat = s_pat.collect{|i| i[:link_object_id] }.compact.collect{|i| BSON::ObjectId.from_string(i) }\r\n\r\n	   # pat_ids = pat_ids - fil_pat\r\n	elsif mode == \'removed\'\r\n	    pat_ids = fil_pat\r\n    elsif mode == \'new\'\r\n    \r\n   \r\n        s_pat = get_model[:filter].where(:module_name=>\'www#patient\', :status=>\'selected\').all\r\n        sel_pat = s_pat.collect{|i| i[:link_object_id] }.compact.collect{|i| BSON::ObjectId.from_string(i) }\r\n        \r\n        	%>\r\n    <div class=\"alert\">\r\n	Total Selected <%=sel_pat.size%>\r\n    Total Patient <%=pat_ids.size%>\r\n	</div>\r\n	<%\r\n        pat_ids = pat_ids - fil_pat\r\n        pat_ids = pat_ids - sel_pat\r\n	end\r\n\r\n	\r\n    all_pat = m_pat.find(pat_ids)\r\n    map_pat = all_pat.group_by{|i| i[:_id]}\r\n    \r\n    all_pro = get_model[:provider].find(pro_ids)\r\n    map_pro = all_pro.group_by{|i| i[:_id]}\r\n\r\n    all_hos = get_model[:hospital].all\r\n\r\n    g_prov = a_prov.group_by{|i| i[:module_id]}\r\n    g_hosp = all_hos.group_by{|i| i.id}\r\n    g_hstr = all_hos.group_by{|i| i.id.to_s}\r\n    \r\n    \r\n%>\r\n\r\n<style>\r\n .divWithScroll{\r\n    height:500px;\r\n    overflow:scroll;\r\n    overflow-x:hidden;\r\n}\r\n</style>  \r\n<%= mode %> | <%= pat_ids.count %>\r\n<%= form_for :rec do |f| %>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box\">\r\n            <div class=\"w-box-header\">\r\n                <h3>List of Patient</h3>\r\n            </div>  \r\n            <div class=\"w-box-content cnt_a\">\r\n            \r\n\r\n\r\n<%= f.submit \'Show New\', :class=>\'btn btn-info\' %> \r\n<%= f.submit \'Show Filtered\', :class=>\'btn btn-info\' %> \r\n<%= f.submit \'Show All\', :class=>\'btn btn-warning\' %> \r\n<%= f.submit \'Show Rejected\', :class=>\'btn btn-warning\' %> |\r\n<span style=\'width:200px\'>&nbsp;|&nbsp;</span>\r\n<%= f.submit \'Selected\', :class=>\'btn btn-success\' %> \r\n<%= f.submit \'Removed\', :class=>\'btn btn-danger\' %> \r\n\r\n<br/>\r\n\r\n\r\n<hr/>\r\n\r\nTotal Patient : <%= pat_ids.count %> <% if mode == \'filter\' %> / <%= pat_ids.count + fil_pat.count %> <% end %> | All Surgeon : <%= g_prov.count %>\r\n\r\n<br/>\r\n\r\n<div class=\'divWithScroll\'>\r\n<table class=\'table table-striped table-bordered table-condensed\' >\r\n    <thead>\r\n        <tr>\r\n            <th><input type=\"checkbox\" id=\"checkAll\" ></th>\r\n            <th>Provider ID</th>\r\n            <th>Provider Name</th>\r\n            <th>Provider Hospital</th>\r\n            <th>Patient Hospital</th>\r\n            <th>Patient ID</th>\r\n            <th>Patient HN</th>\r\n            <th>Patient Name</th>\r\n            <th>Gender</th>\r\n            <th>Birthdate</th>\r\n            <th>Date</th>\r\n            <th>Action</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n<%\r\n    # cur_year \r\n    cy = Time.now.strftime(\'%Y\').to_i\r\n    hs = []\r\n    g_prov.each do |k,v|	\r\n        prov     = map_pro[k][0]\r\n        pro_name = map_pro[k][0][:name]\r\n        pro_id   = k\r\n        \r\n        pro_hosp = prov[:main_hospital]\r\n        hos_name = \'N/A\'\r\n        if pro_hosp\r\n            hos_name = g_hosp[pro_hosp][0][:hospital_name_thai]\r\n        end\r\n        \r\n        v = v.sort_by{|i| i[:created_at]}\r\n        v.each do |i|\r\n            pat      = map_pat[i[:patient_id]]\r\n            if pat.nil?\r\n                next\r\n            else\r\n                pat  = pat[0]\r\n            end\r\n            \r\n            pat_id   = pat[:_id]\r\n            pat_hn   = pat[:hn]\r\n            key      = pat[:hospital_name]\r\n            hos      = g_hstr[key]\r\n            pat_hos  = \'N/A\'\r\n            pat_hos = pat[:hospital_name]\r\n            if hos\r\n                pat_hos = hos[0][:hospital_name_thai]\r\n                # pat_hos = \'xxx\'\r\n            else\r\n                # pat[:hospital_name] = hos\r\n                # pat.update_attributes :hospital_name=>pro_hosp.to_s\r\n                # pat.save\r\n                \r\n                pat_hos = hos_name\r\n            end\r\n            gd = pat[:gender]\r\n            if pat[:prefix_name] != \'\' and pat[:gender].nil?\r\n                if pat[:prefix_name] == \'นาย\'\r\n                    gd = \'1\'\r\n                else\r\n                    gd = \'2\'\r\n                end\r\n            end\r\n                \r\n            \r\n            bd = pat[:birth_date].nil? ? \'N/A\' : pat[:birth_date].strftime(\'%d#%m#%Y\')\r\n            \r\n            # patient birth year\r\n            py = (bd == \'N/A\') ? cy : pat[:birth_date].strftime(\'%Y\').to_i\r\n            bg = \"\"\r\n            if (cy - py) < 20\r\n                bg = \"style=background:yellow\"\r\n                hs << [pat_hn, pat_hos, \"\\\\#{py}\", \"\\\\#{cy-py}\",pat.id]\r\n            elsif (cy - py) > 90\r\n                bg = \"style=background:red\"\r\n                hs << [pat_hn, pat_hos, \"\\\\#{py}\", \"\\\\#{cy-py}\", pat.id]\r\n            end\r\n            \r\n            # pat[:hn] = pat[:hn].upcase\r\n            # pat.save\r\n            pat_name = \"\\\\#{pat[:prefix_name]}\\\\#{pat[:first_name]} \\\\#{pat[:last_name]}\"\r\n            \r\n%>\r\n        <tr>\r\n            <td><%= f.check_box :pat, {:multiple=>true}, \"\\\\#{pat.id.to_s}\", nil %></td>\r\n            <td><%= pro_id %></td>\r\n            <td><%= pro_name %></td>\r\n            <td><%= hos_name %></td>\r\n            <td><%= pat_hos %></td>\r\n            <td><%= pat_id %></td>\r\n            <td><%= pat_hn %></td>\r\n            <td><%= pat_name %></td>\r\n            <td <%= (gd.nil? or gd == \'\') ?  \'style=background:black\' : \'\' %>><%= gd %></td>\r\n            <td <%= bg %>><%= bd %></td>\r\n            <td><%= pat[:created_at].strftime(\'%Y#%m#%d\') %></td>\r\n            <td>\r\n                <%= link_to \'Patient\', \"../../www/Patient/edit?id=\\\\#{pat_id}\",:target=>\'_blank\', :class=>\'btn btn-warning btn-mini\' %>\r\n\r\n                <%= link_to \'Details\', \"../Home/patient_record?id=\\\\#{pat_id}\", :target=>\'_blank\', :class=>\'btn btn-info btn-mini\' %>\r\n            </td>\r\n        </tr>\r\n        <% if false %>\r\n<%= pro_id%>,<%= pat_hn %>,<%= pro_name %>,<%= pat_id %>,<%= pat_name %>,<%= gd %>,<%= bd %>,<%= pat[:bmi] %>,<%= hos_name %>,<%= pat_hos %>,<%= pat[:created_at].strftime(\'%Y#%m#%d\') %><br/>\r\n        <% end %>\r\n<%      end %>\r\n<%\r\n    end\r\n%>\r\n    </tbody>\r\n</table>\r\n<% if true %>\r\nAll under 40 years = <%= hs.count %><br/>\r\nList : <br/>\r\n<% hs.each do |i| %>\r\n<%= i[0] %>;<%= i[1] %>|<%= i.join(\'-\') %><br/>\r\n<% end %>\r\n<% end %>\r\n</div>\r\n<% if false %>\r\n<hr/>\r\npro_id,pro_name,pro_hosp,pat_count<br/>\r\n<%\r\n    g_prov.each do |k,v|\r\n        prov     = map_pro[k][0]\r\n        pro_name = map_pro[k][0][:name]\r\n        pro_id   = k\r\n        pro_hosp = prov[:main_hospital]\r\n        hos_name = \'N/A\'\r\n        if pro_hosp\r\n            hos_name = g_hosp[pro_hosp][0][:hospital_name_thai]\r\n        end\r\n%>\r\n<%= pro_id %>,<%= pro_name %>,<%= hos_name %>,<%= v.count %><br/>\r\n<%\r\n    end\r\n%>\r\n<hr/>\r\n<% end %>\r\n\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<% end %>\r\n\r\n\r\n<script>\r\n    $(\"#checkAll\").click(function(){\r\n        $(\'input:checkbox\').not(this).prop(\'checked\', this.checked);\r\n    });\r\n</script>',NULL,NULL,NULL,'2017-06-14 03:10:57','2017-06-14 03:10:57','patient',''),(3065,'document_name',1220,1,'\'age_group\'',NULL,NULL,NULL,'2017-06-14 06:43:00','2017-06-14 06:43:00',NULL,NULL),(3066,'document_name',1221,1,'\'body_group\'',NULL,NULL,NULL,'2017-06-14 06:43:30','2017-06-14 06:43:30',NULL,NULL),(3067,'document_name',1222,1,'\'eye_color\'',NULL,NULL,NULL,'2017-06-14 06:43:41','2017-06-14 06:43:41',NULL,NULL),(3068,'document_name',1223,1,'\'list_item\'',NULL,NULL,NULL,'2017-06-14 06:44:17','2017-06-14 06:44:17',NULL,NULL),(3069,'index',1217,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'index\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2017-06-14 07:27:25','2017-06-14 07:27:25','index',''),(3070,'create',1173,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index_dev\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-06-15 02:29:04','2017-06-15 02:29:04','create',''),(3071,'common_function',1173,4,'<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    @model = ehr.load_model\r\n    @m_pat = @model[:patient]\r\n    @m_pat_mod = @model[:patient_module]\r\n        \r\n    def proc_list\r\n        return [\"hip1\", \"hip2\", \"knee1\", \"knee2\"]\r\n    end\r\n    \r\n    def document_query(cond = {}, sel_fields = {}, doc = this.table_name) \r\n        res = []\r\n        \r\n        if cond.empty? and false\r\n            today = Time.now\r\n            sdate = today.at_beginning_of_month\r\n            edate = today.end_of_month\r\n            cond[:created_at] = {\'$gte\'=>sdate.beginning_of_day,\'$lt\'=>edate.end_of_day}\r\n        end\r\n        \r\n        fields = {}\r\n        fields[:fields] = sel_fields\r\n        \r\n        obj = get_model[doc.to_sym].collection.find(cond, fields).to_a\r\n        if obj\r\n            res = obj\r\n        end\r\n        \r\n        return res\r\n    end\r\n    \r\n    def get_patient_filtered(hos_code = nil)\r\n        res = []\r\n        \r\n        if !hos_code.nil?\r\n            hos = get_model[:hospital].where(:hospital_code=>hos_code.upcase).first\r\n            \r\n            if hos.nil?\r\n                hos_code = nil\r\n            else\r\n                hos_code = hos.id.to_s\r\n            end\r\n        end\r\n        \r\n        if hos_code.nil?\r\n            a_prov = @m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#provider\").all\r\n        else\r\n            prov = get_model[:provider].where(:main_hospital=>hos_code).all\r\n            pid = prov.collect{|i| i.id}\r\n            a_prov = @m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#provider\",:module_id=>pid).all\r\n        end\r\n     \r\n    	pat_ids = a_prov.collect{|i| i[:patient_id]}.compact\r\n        # Use for realtime data	\r\n    # 	a_filter = get_model[:filter].where(:module_name=>\'www#patient\', :status=>\'removed\').all\r\n	   # fil_pat = a_filter.collect{|i| BSON::ObjectId.from_string(i[:object_id])}\r\n	    \r\n	   # return pat_ids - fil_pat\r\n	   \r\n	   \r\n	   # Use for selected data\r\n	    a_filter = get_model[:filter].where(:module_name=>\'www#patient\', :status=>\'selected\').all\r\n	   # fil_pat  = a_filter.collect{|i| i.id }\r\n        \r\n          \r\n        \r\n	   # fil_pat  = a_filter.compact.collect{|i| BSON::ObjectId.from_string(i[:link_object_id])}\r\n	   fil_pat  = a_filter.collect{|i| i[:link_object_id]}.compact.collect{|i| BSON::ObjectId.from_string(i) }\r\n\r\n       \r\n	   # return fil_pat\r\n	    if hos_code.nil?\r\n            return fil_pat\r\n        else\r\n            return fil_pat & pat_ids\r\n        end\r\n        \r\n        \r\n	   \r\n    end\r\n    \r\n    def get_patient_by_document_result(res = [])\r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        m_pat = model[:patient]\r\n        m_pat_mod = model[:patient_module]\r\n        \r\n        g_form = res.group_by{|i| i[\'_id\']}\r\n        \r\n        fid = g_form.keys\r\n        # tmp = m_pat_mod.where(:module_id=>fid).all\r\n        tmp = m_pat_mod.collection.find({\'module_id\'=>{\'$in\'=>fid}}, {:fields=>{\'patient_id\'=>1, \'module_id\'=>1, \'created_at\'=>1, \'module_name\'=>1}}).to_a\r\n        g_tmp = tmp.group_by{|i| i[\'module_id\']}\r\n        \r\n        pid = tmp.collect{|i| i[\'patient_id\']}\r\n        pat = m_pat.collection.find({\'_id\'=>{\'$in\'=>pid}},{:fields=>{\'hn\'=>1, \'prefix_name\'=>1,\'first_name\'=>1,\'last_name\'=>1}}).to_a\r\n        \r\n        g_pat = pat.group_by{|i| i[\'_id\']}\r\n        \r\n        # res = {}\r\n        # res[:patient] = g_pat\r\n        # res[:module_link] = g_tmp\r\n        \r\n        # return res\r\n        return g_pat\r\n    end\r\n    \r\n    def get_patient_module_by_document_result(res = [])\r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        m_pat = model[:patient]\r\n        m_pat_mod = model[:patient_module]\r\n        \r\n        g_form = res.group_by{|i| i[\'_id\']}\r\n        \r\n        fid = g_form.keys\r\n        # tmp = m_pat_mod.where(:module_id=>fid).all\r\n        res = m_pat_mod.collection.find({\'module_id\'=>{\'$in\'=>fid}}, {:fields=>{\'patient_id\'=>1, \'module_id\'=>1, \'created_at\'=>1, \'module_name\'=>1, \'parent_id\'=>1}}).to_a\r\n        return res\r\n    end\r\n    \r\n    def get_document_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].nil? ? \'\' : x[1].strip\r\n                    tmp[:list] << x[1].nil? ? \'\' : x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    def get_value f, fdoc, val\r\n        x = fdoc[f.to_sym]\r\n        v = val\r\n        h = x.to_h\r\n        if h.has_key? :pair and !v.nil? and v != \'\'\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n        elsif h[:field_type] == \'select_time\' and !v.nil? and v != \'\'\r\n            v = val.strftime(\'%H:%M\')\r\n        elsif h[:field_type] == \'relation_one\'\r\n            pr = eval(\"{\\\\#{h[:params]}}\")\r\n            dd = pr[:relation][:document]\r\n            v = get_model[dd].find(v)\r\n            v = v[:name] if v\r\n        end\r\n        return v\r\n    end\r\n    \r\n    @obj = {}\r\n    def val f, doc, default = \'N/A\'\r\n        doc = doc.to_sym\r\n        f = f.to_sym\r\n        if @obj.has_key? doc\r\n            # get_value(:premed, obj[:pre_operative_visit][:df], obj[:pre_operative_visit][:rec][:premed])\r\n            rt = get_value(f, @obj[doc][:df], @obj[doc][:rec][f])\r\n            return (rt.nil? or rt==\'\') ? default : rt\r\n        else\r\n            return default\r\n        end\r\n    end\r\n%>',NULL,NULL,NULL,'2017-06-15 02:38:30','2017-06-15 02:38:30','com',''),(3072,'hip_report',1173,3,'<%= render :inline=>this.common_function %>\r\n<%\r\n    \r\n%>\r\n<%= params.to_json.html_safe %>',NULL,NULL,NULL,'2017-06-15 03:37:18','2017-06-15 03:37:18','hip_report',''),(3073,'overview',1173,3,'<%= render :inline=>this.common_function %>\r\n<%\r\n    tb  = Time.now\r\n    \r\n    type = params[:type]\r\n    \r\n    def percent(v, sum)\r\n        return \'%.2f\' % (v * 100.0/sum)\r\n    end\r\n    \r\n    if type == \'num_proc\'\r\n        # filtered patient\r\n        fp  = get_patient_filtered\r\n        ff = get_model[:filter].all\r\n        \r\n        # all provider\r\n        pv = get_model[:provider].all\r\n        g_pro = pv.group_by{|i| i.id}\r\n        pro_mod = @m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#provider\", :patient_id=>fp).all\r\n        pro_ids = pro_mod.collect{|i| i[:module_id]}.uniq\r\n        g_pat_pro = pro_mod.group_by{|i| i[:patient_id]}\r\n        \r\n        \r\n        # procedure list\r\n        pl  = proc_list\r\n        \r\n        pat_pro = {}\r\n        pat_pro[:sum] = {:pro=>0, :all=>0}\r\n        pl.each do |i|\r\n            mn = \"\\\\#{@current_project.name}#\\\\#{i}\"\r\n            rs = @m_pat_mod.where(:module_name=>mn, :patient_id=>fp).all\r\n            al = @m_pat_mod.where(:module_name=>mn).all\r\n            ids = rs.collect{|i| i[:module_id]}\r\n            pat_pro[i] = {:pro=>ids, :all=>al}\r\n            pat_pro[:sum][:pro] += ids.count\r\n            pat_pro[:sum][:all] += al.count\r\n        end\r\n        res = pat_pro\r\n        \r\n        pro_count = pat_pro[:sum][:pro]\r\n%>\r\n<center>\r\n    <table id=\'search-result\' class=\"table table-bordered\" style=\'width:40%\'>\r\n        <tbody>\r\n            <tr>\r\n                <th colspan=\'2\' style=\'background:lightgrey\'><center>Procedures</center></th>\r\n            </tr>\r\n            <tr>\r\n                <td style=\'vertical-align:middle\'><center><h1><%= pat_pro[:sum][:all] %></h1></center></td>\r\n                <td><center><h2><%= pat_pro[:sum][:all] - pat_pro[:sum][:pro] %></h2><hr style=\'margin:0px\'/><span style=\'font-size:0.8em\'>no patient identifiers</span></center></td>\r\n            </tr>\r\n            <tr>\r\n                <th colspan=\'2\' style=\'background:lightgrey\'><center>Linkable procedures</center></th>\r\n            </tr>\r\n            <tr>\r\n                <td colspan=\'2\'>\r\n                    <center><h1><%= pat_pro[:sum][:pro] %></h1><hr style=\'margin:0px\'/><h3><%= fp.count %></h3><span style=\'font-size:0.8em\'>patient identifiers</span></center>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <th style=\'background:lightgrey\'><center>HIPS</center></th>\r\n                <th style=\'background:lightgrey\'><center>KNEES</center></th>\r\n            </tr>\r\n            <tr>\r\n                <td>\r\n                    <center><span style=\'font-size:0.8em\'>primaries</span><br/><%= pat_pro[\'hip1\'][:pro].count %> (<%= (pat_pro[\'hip1\'][:pro].count * 100.0 / pro_count).round(2) %> %)</center>\r\n                    <hr style=\'margin:5px\'/>\r\n                    <center><span style=\'font-size:0.8em\'>revisions</span><br/><%= pat_pro[\'hip2\'][:pro].count %> (<%= (pat_pro[\'hip2\'][:pro].count * 100.0 / pro_count).round(2) %> %)</center>\r\n                </td>\r\n                <td>\r\n                    <center><span style=\'font-size:0.8em\'>primaries</span><br/><%= pat_pro[\'knee1\'][:pro].count %> (<%= (pat_pro[\'knee1\'][:pro].count * 100.0 / pro_count).round(2) %> %)</center>\r\n                    <hr style=\'margin:5px\'/>\r\n                    <center><span style=\'font-size:0.8em\'>revisions</span><br/><%= pat_pro[\'knee2\'][:pro].count %> (<%= (pat_pro[\'knee2\'][:pro].count * 100.0 / pro_count).round(2) %> %)</center>\r\n                </td>\r\n            </tr>\r\n        </tbody>\r\n    </table>\r\n</center>\r\n<% if false %>\r\nAll providers = <%= pv.count %><br/>\r\nFiltered provider = <%= pro_ids.count %><br/>\r\nAll patients = <%= fp.count + ff.count %><br/>\r\nFiltered patient = <%= fp.count %> <br/>\r\n<%\r\n    s = 0\r\n    res.each do |k,v|\r\n        if k.to_s == \'sum\'\r\n            next\r\n        end\r\n        s += v[:pro].count\r\n%>\r\n<%= k %> = <%= v[:pro].count %><br/>\r\n<%  end %>\r\nAll procedures = <%= s %>\r\n<% end # if false %>\r\n<% \r\n    elsif type == \'num_record\'\r\n        # filtered patient\r\n        fil_pat = get_patient_filtered\r\n        \r\n        all_pat = @m_pat.find(fil_pat)\r\n        g_pat   = all_pat.group_by{|i| i[:created_at].strftime(\'%m/%Y\')}\r\n        \r\n        # procedure list\r\n        rl  = [] # record list\r\n        pl  = proc_list\r\n        pp  = []\r\n        pl.each do |i|\r\n            mn = \"\\\\#{@current_project.name}#\\\\#{i}\"\r\n            pp << mn\r\n        end\r\n        \r\n        rl = @m_pat_mod.where(:module_name=>{\'$regex\' => pp.join(\'|\'), \'$options\' => \'i\'}).all\r\n        \r\n        g_rec   = rl.group_by{|i| i[:created_at].strftime(\'%m/%Y\')}\r\n        \r\n        f_mon   = g_pat.keys[0].split(\'/\')[0].to_i\r\n        f_year  = g_pat.keys[0].split(\'/\')[1].to_i\r\n        \r\n        cur_mon = tb.strftime(\'%m\').to_i\r\n        cur_year = tb.strftime(\'%Y\').to_i\r\n        \r\n        lbn = []\r\n        \r\n        f_year.upto(cur_year) do |i|\r\n            f_mon.upto(12) do |j|\r\n                tmp = \"\\\\#{\'%02d\' % j}/\\\\#{\'%02d\' % i}\"\r\n                lbn << tmp\r\n                if tmp == tb.strftime(\'%m/%Y\')\r\n                    break\r\n                end\r\n            end\r\n            f_mon = 1\r\n        end\r\n        \r\n        ser_pat = {:name=>\"Patient\", :data=>[]}\r\n        ser_rec = {:name=>\"Record\", :data=>[]}\r\n        s = 0\r\n        x = 0\r\n        lbn.each do |i|\r\n            v = 0\r\n            if t = g_pat[i]\r\n                v = t.count\r\n                s += v\r\n            end\r\n            ser_pat[:data] << s\r\n            \r\n            if t = g_rec[i]\r\n                v = t.count\r\n                x += v\r\n            end\r\n            ser_rec[:data] << x\r\n        end\r\n%>\r\n    <!--<%= ser_pat.to_json.html_safe %> <%= ser_pat[:data].sum %><br/><%= ser_rec.to_json.html_safe %> <%= ser_rec[:data].sum %><br/><%= g_rec.count %>-->\r\n    <div class=\"span12 k-content wide\">\r\n        <center>\r\n            <div id=\"chart\" style=\"border:0px solid;min-height:400px\" class=\'span12\'></div>\r\n            \r\n            <table id=\'procedures-result\' class=\"table table-bordered\" width=\'90%\'>\r\n                <thead>\r\n                    <tr>\r\n                        <th>Serie</th>\r\n                        <% lbn.each do |i| %>\r\n                        <th><%= i %></th>\r\n                        <% end %>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                <%\r\n                    dt = [ser_pat, ser_rec]\r\n                    dt.each do |i|\r\n                        name = i[:name]\r\n                        data = i[:data]\r\n                %>\r\n                    <tr>\r\n                        <td><%= name %></td>\r\n                        <% \r\n                            x = 0\r\n                            data.each_with_index do |j, idx| \r\n                                n = j\r\n                                if idx > 0\r\n                                    n = j - data[idx - 1]\r\n                                end\r\n                        %>\r\n                        <td><center><%= n %> <!--(<%= j %>)--></center></td>\r\n                        <% end %>\r\n                    </tr>\r\n                <%  end %>\r\n                </tbody>\r\n            </table>\r\n            \r\n        </center>\r\n    </div>\r\n    <script>\r\n        function createChart() {\r\n            \r\n            $(\"#chart\").kendoChart({\r\n                title: {\r\n                    text: \"Number of data records and procedures per month\"\r\n                },\r\n                legend: {\r\n                    position: \"bottom\"\r\n                },\r\n                chartArea: {\r\n                    background: \"\"\r\n                },\r\n                seriesDefaults: {\r\n                    type: \"line\",\r\n                    style: \"smooth\"\r\n                },\r\n                // seriesColors: [\"red\", \"green\"],\r\n                series: [<%= ser_pat.to_json.html_safe %>, <%= ser_rec.to_json.html_safe %>],\r\n                valueAxis: {\r\n                    labels: {\r\n                        format: \"{0}\"\r\n                    },\r\n                    line: {\r\n                        visible: false\r\n                    },\r\n                    axisCrossingValue: -10\r\n                },\r\n                categoryAxis: {\r\n                    categories: <%= lbn.to_json.html_safe %>,\r\n                    majorGridLines: {\r\n                        visible: false\r\n                    },\r\n                    labels: {\r\n                        rotation: \"auto\"\r\n                    }\r\n                },\r\n                tooltip: {\r\n                    visible: true,\r\n                    format: \"{0}%\",\r\n                    template: \"#= series.name #: #= value #\"\r\n                }\r\n            });\r\n        }\r\n\r\n        $(document).ready(createChart);\r\n        $(document).bind(\"kendo:skinChange\", createChart);\r\n        // $(document).ready(function() {\r\n        //     setTimeout(function() {\r\n        //                 createChart();\r\n        //             }, 400);\r\n        // })\r\n    </script>\r\n    <div class=\'clear\'></div>\r\n<%  \r\n    elsif type==\'lateral\' \r\n    # filtered patient\r\n        fp  = get_patient_filtered\r\n        \r\n        # procedure list\r\n        pl  = proc_list\r\n        \r\n        pat_pro = {}\r\n        pl.each do |i|\r\n            mn = \"\\\\#{@current_project.name}#\\\\#{i}\"\r\n            rs = @m_pat_mod.where(:module_name=>mn, :patient_id=>fp).all\r\n            ids = rs.collect{|i| i[:module_id]}\r\n            pat_pro[i.to_sym] = {:id=>ids, :rs=>rs}\r\n        end\r\n        res = pat_pro\r\n        \r\n        pat_h1 = pat_pro[:hip1][:rs].group_by{|i| i[:patient_id]}.count\r\n        pat_h2 = pat_pro[:hip2][:rs].group_by{|i| i[:patient_id]}.count\r\n        \r\n        pat_k1 = pat_pro[:knee1][:rs].group_by{|i| i[:patient_id]}.count\r\n        pat_k2 = pat_pro[:knee2][:rs].group_by{|i| i[:patient_id]}.count\r\n        \r\n        pro_h1_id = pat_pro[:hip1][:id]\r\n        pro_h2_id = pat_pro[:hip2][:id]\r\n        \r\n        pro_k1_id = pat_pro[:knee1][:id]\r\n        pro_k2_id = pat_pro[:knee2][:id]\r\n        \r\n        rs_h1 = document_query({\'_id\'=>{\'$in\'=>pro_h1_id}}, {\'side\'=>1, \'bilateral\'=>1}, \'hip1\')\r\n        rs_h2 = document_query({\'_id\'=>{\'$in\'=>pro_h2_id}}, {\'side\'=>1, \'bilateral\'=>1}, \'hip2\')\r\n        \r\n        rs_k1 = document_query({\'_id\'=>{\'$in\'=>pro_k1_id}}, {\'side\'=>1, \'bilateral\'=>1}, \'knee1\')\r\n        rs_k2 = document_query({\'_id\'=>{\'$in\'=>pro_k2_id}}, {\'side\'=>1, \'bilateral\'=>1}, \'knee2\')\r\n        \r\n        \r\n%>\r\n<center>\r\n    <!--<div class=\'span6\'>-->\r\n    <table id=\'procedures-result\' class=\"table table-bordered \" style=\'width:70%\'>\r\n        <thead>\r\n            <tr>\r\n                <th rowspan=\'2\'>&nbsp;</th>\r\n                <th colspan=\'2\'><center>Joint</center></th>\r\n                <th rowspan=\'2\'><center>Total</center></th>\r\n            </tr>\r\n            <tr>\r\n                <th><center>HIPS</center></th>\r\n                <th><center>KNEES</center></th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n            <tr>\r\n                <td style=\'vertical-align:middle\'>Number of patients</td>\r\n                <td>\r\n                <%\r\n                    # sum hip\r\n                    sh = pat_h1 + pat_h2\r\n                %>\r\n                    <div style=\'font-size:0.8em\'>primaries</div>\r\n                    <h3><%= pat_h1 %> <span style=\'font-size:0.8em\'>(<%= \'%.2f\' % (pat_h1 * 100.0/sh) %>%)</span></h3>\r\n                    <hr style=\'margin:2px\'/>\r\n                    <div style=\'font-size:0.8em\'>revisions</div>\r\n                    <h3><%= pat_h2 %> <span style=\'font-size:0.8em\'>(<%= \'%.2f\' % (pat_h2 * 100.0/sh) %>%)</span></h3>\r\n                    <hr style=\'margin:2px\'/><div style=\'font-size:0.8em\'>total</div>\r\n                    <h1><%= pat_h1 + pat_h2 %></h1>\r\n                </td>\r\n                <td >\r\n                <%\r\n                    # sum knee\r\n                    sk = pat_k1 + pat_k2\r\n                %>\r\n                    <div style=\'font-size:0.8em\'>primaries</div>\r\n                    <h3><%= pat_k1 %> <span style=\'font-size:0.8em\'>(<%= percent(pat_k1, sk) %>%)</span></h3>\r\n                    <hr style=\'margin:2px\'/>\r\n                    <div style=\'font-size:0.8em\'>revisions</div>\r\n                    <h3><%= pat_k2 %> <span style=\'font-size:0.8em\'>(<%= percent(pat_k2, sk) %>%)</span></h3>\r\n                    <hr style=\'margin:2px\'/><div style=\'font-size:0.8em\'>total</div>\r\n                    <h1><%= pat_k1 + pat_k2 %></h1>\r\n                </td>\r\n                <td style=\'vertical-align:middle\'>\r\n                    <center><h1 style=\'font-size:3em\'><%= fp.count %></h1></center>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n            <%\r\n                # sum hip (sh) sum knee (sk)\r\n                sh = pro_h1_id.count + pro_h2_id.count\r\n                sk = pro_k1_id.count + pro_k2_id.count\r\n                sum = sh + sk\r\n            %>\r\n                <td style=\'vertical-align:middle\'>Number of procedures</td>\r\n                <td>\r\n                    <div style=\'font-size:0.8em\'>primaries</div>\r\n                    <h3><%= pro_h1_id.count %> <span style=\'font-size:0.8em\'>(<%= percent(pro_h1_id.count, sum) %>%)</span></h3>\r\n                    <hr style=\'margin:2px\'/>\r\n                    <div style=\'font-size:0.8em\'>revisions</div>\r\n                    <h3><%= pro_h2_id.count %> <span style=\'font-size:0.8em\'>(<%= percent(pro_h2_id.count, sum) %>%)</span></h3>\r\n                    <hr style=\'margin:2px\'/><div style=\'font-size:0.8em\'>total</div>\r\n                    <h1><%= sh %> <span style=\'font-size:0.8em\'>(<%= percent(sh, sum) %>%)</span></h1>\r\n                </td>\r\n                <td>\r\n                    <div style=\'font-size:0.8em\'>primaries</div>\r\n                    <h3><%= pro_k1_id.count %>  <span style=\'font-size:0.8em\'>(<%= percent(pro_k1_id.count, sum) %>%)</span></h3>\r\n                    <hr style=\'margin:2px\'/>\r\n                    <div style=\'font-size:0.8em\'>revisions</div>\r\n                    <h3><%= pro_k2_id.count %>  <span style=\'font-size:0.8em\'>(<%= percent(pro_k2_id.count, sum) %>%)</span></h3>\r\n                    <hr style=\'margin:2px\'/><div style=\'font-size:0.8em\'>total</div>\r\n                    <h1><%= sk %> <span style=\'font-size:0.8em\'>(<%= percent(sk, sum) %>%)</span></h1>\r\n                </td>\r\n                <td style=\'vertical-align:middle\'>\r\n                    <center><h1 style=\'font-size:3em\'><%= sh + sk %></h1></center>\r\n                </td>\r\n            </tr>\r\n            <tr>\r\n                <td style=\'vertical-align:middle\'>Number of left-unilateral (%)</td>\r\n                <td></td>\r\n                <td></td>\r\n                <td style=\'vertical-align:middle\'></td>\r\n            </tr>\r\n            <tr>\r\n                <td style=\'vertical-align:middle\'>Number of right-unilateral (%)</td>\r\n                <td></td>\r\n                <td></td>\r\n                <td style=\'vertical-align:middle\'></td>\r\n            </tr>\r\n            <!--\r\n            <tr>\r\n                <td style=\'vertical-align:middle\'>Number of unilateral (left or right) (%)</td>\r\n                <td></td>\r\n                <td></td>\r\n                <td style=\'vertical-align:middle\'></td>\r\n            </tr>\r\n            -->\r\n            <tr>\r\n                <td style=\'vertical-align:middle\'>Number (%) of bilateral (both left and right)</td>\r\n                <td></td>\r\n                <td></td>\r\n                <td style=\'vertical-align:middle\'></td>\r\n            </tr>\r\n        </tbody>\r\n    </table>\r\n    <%# pat_pro.to_json.html_safe %>\r\n    <!--</div>-->\r\n    <%= rs_h1.group_by{|i| i[\'side\']}.keys %> | <%= rs_h2.count %>, <%= rs_k1.count %> | <%= rs_k2.count %>\r\n</center>\r\n<%\r\n    else\r\n%>\r\n<h3>No type selected</h3>\r\n<%  end %>\r\n    <div class=\'clear\'></div>\r\n<hr/>\r\n<i style=\'font-size:0.5em;color:grey\'>Processing Time : <%= Time.now - tb %></i>\r\n<br/>',NULL,NULL,NULL,'2017-06-15 03:45:56','2017-06-15 03:45:56','overview',''),(3074,'create',1218,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s  and params[:override]==nil\r\n    %>\r\n    <script>\r\n        res = confirm(\"Someone is editing this document. Would you like to override the record?\");\r\n        if(res==true){\r\n             $(document).ready(function(){\r\n              $(\'#ref_number\').parent().append(\"<input type=\'hidden\' name=\'override\' value=\'override\' />\");\r\n               \r\n           })\r\n        }else\r\n            window.location = \"<%=return_url%>\";\r\n\r\n\r\n        </script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; max-width: 1000px; width: 95%;\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\nRef : <%=ref_number%>\r\n <div class=\"<%=\'hide\' if params[:parent_id]%>\" style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc;\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n<%\r\n    if return_url.include? \'?\'\r\n        return_url += \"&reset_lock=\\\\#{locker.id}\"\r\n    else\r\n        return_url += \"?reset_lock=\\\\#{locker.id}\"\r\n    end\r\n%>\r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2017-06-15 04:12:58','2017-06-15 04:12:58','create',''),(3075,'test',1173,3,'<%= render :inline=>this.common_function %>\r\n<%\r\n    res = {}\r\n    pat = get_patient_filtered\r\n    \r\n    a_hosp = get_model[:hospital].all\r\n    hosp = a_hosp.group_by{|i| i.id.to_s}\r\n    \r\n    g_pat = @m_pat.find(pat).group_by{|i| i[:hospital_name].to_s}\r\n    \r\n    rs = {}\r\n    sm = 0\r\n    g_pat.each do |k, v|\r\n        hos = hosp[k.to_s][0][:hospital_name_thai]\r\n        rs[hos] = v.count\r\n        sm += v.count\r\n    end\r\n    res[:rs] = rs\r\n    res[:sm] = sm\r\n    if false\r\n    a_hosp = get_model[:provider].all\r\n    g_hosp = a_hosp.group_by{|i| i[:created_at].strftime(\'%Y\')}\r\n    g_hosp.each do |k,v|\r\n%>\r\n<%= k %>|<%=v.count %><br/>\r\n<% \r\n    end \r\n    end\r\n%>\r\n<%\r\n    a_hosp.each do |i|\r\n%>\r\n<%= i[:hospital_name_thai] %><br/>\r\n<% end %>\r\n<%# res.to_json.html_safe %>',NULL,NULL,NULL,'2017-06-16 03:36:37','2017-06-16 03:36:37','test',''),(3076,'export_all',1173,3,'<%= render :inline=>this.common_function %>\r\n<% \r\n    tb = Time.now \r\n    \r\n    params[:date] = \'all\'\r\n    doc_name = \'knee1\'\r\n    if params[:proc]\r\n        doc_name = params[:proc]\r\n    end\r\n    hos_code = nil\r\n    if params[:hosp]\r\n        hos_code = params[:hosp]\r\n    end\r\n    \r\n    fol_doc = \'follow_up_knee\'\r\n    if doc_name.include? \'hip\'\r\n        fol_doc = \'follow_up_hip\'\r\n    end\r\n    \r\n    def get_doc_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].strip\r\n                    tmp[:list] << x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    # @fm = fm\r\n    def get_value f, val\r\n        x = @fm[f.to_sym]\r\n        v = val\r\n        if x.to_h.has_key? :pair and !v.nil? and v != \'\'\r\n            # if f.to_sym == :if_rrt or f.to_sym == :vasopressor\r\n            #     v = x[:pair][v]\r\n            # else\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n                # v = \"<span title=\'\\\\#{v}\'>\\\\#{val} <i class=\'splashy-help\'></i></span>\".html_safe\r\n            # end\r\n        end\r\n            # if f.to_sym == :delivered_lose and !v.nil? and v != \'\'\r\n            #         v = v.to_f.round(4) if Float(v) rescue v\r\n            # end\r\n        # if v.nil? or v == \'\'\r\n        #     v = \'-\'\r\n        # end\r\n        return v\r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	m_pat = @ehr_model[:patient]\r\n	m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	# map prov_id <-> provider_name\r\n	prov = {}\r\n	a_prov = get_model[:provider].all\r\n	a_prov.each do |i|\r\n	    prov[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map company_id <-> company_name\r\n	comp = {}\r\n	a_comp = get_model[:company].all\r\n	a_comp.each do |i|\r\n	    comp[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map hospital_id <-> hospital_name\r\n	hosp = {}\r\n	a_hosp = get_model[:hospital].all\r\n	a_hosp.each do |i|\r\n	    hosp[i.id.to_s] = i[:hospital_name_thai]\r\n	end\r\n	\r\n	# map knee_component <--> component_name\r\n	kcom = {}\r\n	a_temp = get_model[:knee_component].all\r\n	a_temp.each do |i|\r\n	    kcom[i.id.to_s] = i[:name]\r\n	end\r\n	# map hip component <-> component_name\r\n# 	hcom = {}\r\n# 	a_temp = get_model[:hip_component].all\r\n# 	a_temp.each do |i|\r\n# 	    hcom[i.id.to_s] = i[:name]\r\n# 	end\r\n    \r\n    # map colpo_id <-> colpo\r\n    colpo = {}\r\n    ids   = []\r\n    a_col = get_model[doc_name.to_sym].all\r\n    a_col.each do |i|\r\n        ids << i.id\r\n        colpo[i.id.to_s] = i\r\n    end\r\n    \r\n    # procedure\'s module_model\r\n    mm_proc = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{doc_name}\", :module_id=>ids).all\r\n    # parent ids \r\n    par_ids = mm_proc.collect{|i| i[:parent_id]}\r\n    # follow up\r\n    mm_foll = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{fol_doc}\", :parent_id=>par_ids).all\r\n    gr_foll = mm_foll.group_by{|i| i[:parent_id].to_s}\r\n    \r\n    # map patient_id <-> patient\r\n    # ig_pat = %w{55af2feb790f9b6127000003	55c21a68790f9b30e8000003	55af3548790f9b6e5f000003	55affd22790f9b19c600001a	55afff02790f9b08ee00001a	55c254ab790f9b0ddc000016	569fa3d9790f9b0c14000007	57a7514c790f9b6f5f000031	57ea9a2e790f9b475d000002	55c21dbf790f9b4041000001	55c7d26d790f9b62e8000014	55ee3b4f790f9b7114000010	5783159a790f9b3887000012	56b0811b790f9b31ac000025	56b88898790f9b07e2000013	56b98fb6790f9b4348000005	56df9a87790f9b45db0000a7	5785a75d790f9b676d00003d	57906b43790f9b296200001f	57938c9d790f9b6988000004	5793a234790f9b053f000001	57944abd790f9b2411000001	57958eba790f9b534e000034	579592ed790f9b6975000005	57a083d4790f9b2af3000011	57a083f9790f9b2af3000013	57a09623790f9b5a24000002	57a1653f790f9b3b76000005	57abe367790f9b2ca3000001	57abe9e6790f9b232a000010	57abeb90790f9b232a000015	57abfc52790f9b452c00001c	57ac1945790f9b63c4000011	57ac1e16790f9b79f0000014	57ac1e16790f9b7577000047