abfc52790f9b452c00001c	57ac1945790f9b63c4000011	57ac1e16790f9b79f0000014	57ac1e16790f9b7577000047	57ac2adb790f9b7a5a00004b	57ac2f6c790f9b19de000003	57ac3014790f9b196e00000a	57ac3019790f9b196300000f	57ac3025790f9b1963000011	57ac3083790f9b196300001a	57ad6b56790f9b458d000013	57ad7318790f9b53e3000001	57ad7318790f9b4f0f00000a	57ad7b72790f9b55ee000004	57ad8186790f9b55ee00000e	57ad82f1790f9b66b8000001	57b2a657790f9b0d18000001	57b7bf98790f9b30a900000c	57b7fc4d790f9b0deb000001	57bd4561790f9b5a0700000f	57c3dee8790f9b755400000b	57e155c0790f9b44ab000021	57e163ce790f9b4bd1000003	57ac2990790f9b79f000003b	57ac2d1a790f9b63c4000085	57ac300e790f9b196e000008	57ac3016790f9b19de000005	57aeb227790f9b5f5b000009	57c653c3790f9b2ddd000006	583fb46b790f9b422c00000b	57ac302c790f9b196e00000c	57ac3040790f9b194c000006	57ad82bf790f9b6615000001	57ad82f0790f9b6422000003	57ad8ef3790f9b717f00000e	57ad82f5790f9b66b8000003	57ad82f7790f9b6422000005	57ad82f7790f9b6615000003	57ad8318790f9b6615000005	57ad831c790f9b6615000007	57ed3b70790f9b2264000001	57ed3bca790f9b2264000007	57ae846d790f9b2516000001	57ae8ef0790f9b397c000003	57aea21a790f9b457d000001	57aea8fe790f9b5603000001	57ff023c790f9b7a1000000e}\r\n    # pat_ids = mm_proc.collect{|i| i[:patient_id].to_s}\r\n    # pat_ids = pat_ids - ig_pat\r\n    pat_ids = get_patient_filtered(hos_code)\r\n    pat = {}\r\n    rs_pat = m_pat.find(pat_ids)\r\n    rs_pat.each do |i|\r\n        pat[i.id.to_s] = i\r\n    end\r\n\r\n    # main fields\r\n    mf = get_doc_field doc_name\r\n    @fm = mf\r\n\r\n    # patient fields\r\n    pf = [:id, :hn, :name, :hospital_name, :age, :gender]\r\n    # colposcopy fields\r\n    colf = pf + mf.keys + [:follow_up]\r\n    colf = colf - [:image_pre_op, :image_intra_op, :image_implant_barcode, :operative_note, :recorder_by, :hn, :name]\r\n    \r\n    rs_col = []\r\n    rs_les = []\r\n    \r\n    # patient-follow_up\r\n    pat_foll = {}\r\n    # patient-implant_profile\r\n    pat_imp  = {}\r\n    # all_follow_up\r\n    fol_list = []\r\n    # all_implant_profile\r\n    imp_list = []\r\n    zz = []\r\n    mm_proc.each do |i|\r\n        pat_id = i[:patient_id].to_s\r\n        par_id = i[:parent_id].to_s\r\n        # patient\r\n        pt = pat[i[:patient_id].to_s]\r\n        # colpo\r\n        cp = colpo[i[:module_id].to_s]\r\n        \r\n        if pt.nil?\r\n            next\r\n        end\r\n        \r\n        today = cp[:created_at]\r\n        if (!cp[:operation_date].nil? and cp[:operation_date] != \'\')\r\n            today = cp[:operation_date]\r\n        end\r\n        # d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  pt[:birth_date].day) : today\r\n        d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  1) : today\r\n        age = !pt[:birth_date].nil? ? d.year - pt[:birth_date].year - (d > today ? 1 : 0) : 0\r\n        \r\n        \r\n        tmp = {}\r\n        tmp[:id]  = pt.id # pt.id.to_s[5..14]\r\n        tmp[:hn]  = pt[:hn]\r\n        tmp[:name]= \"\\\\#{pt[:first_name]} \\\\#{pt[:last_name]}\"\r\n        tmp[:age] = age\r\n        tmp[:hospital_name] = hosp[pt[:hospital_name].to_s]\r\n        tmp[:gender] = pt[:gender]\r\n        # tmp[:created_at] = today\r\n        # tmp[:operation_date] = cp[:operation_date]\r\n        # zz << pt[:hospital_name]\r\n        mf.keys.each do |j|\r\n            x = mf[j]\r\n            \r\n            # x = {}\r\n            v = cp[j]\r\n            if x.to_h.has_key? :pair and !v.nil?\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                \r\n                tmp[j] = a.join(\',\')\r\n            elsif x[:column_name].include? \'implant_profile\' \r\n                tmp[j] = v\r\n                \r\n                if v.size != 0\r\n                    imp_list += v\r\n                    if !pat_imp.has_key? pat_id\r\n                        pat_imp[pat_id] = {}\r\n                    end\r\n                    pat_imp[pat_id][j] = v\r\n                end\r\n                \r\n            elsif x[:column_name] == \'image\'\r\n                tmp[j] = v.size\r\n            elsif x[:column_name].to_s.include? \'provider_\' or x[:column_name] == \'recorder_by\'\r\n                name = prov[v.to_s]\r\n                if name\r\n                    # tmp[j] = name\r\n                    tmp[j] = v.to_s[0..9]\r\n                else\r\n                    tmp[j] = v\r\n                end\r\n            elsif x[:column_name].include? \'component_\' or x[:column_name].include? \'company\'\r\n                if x[:column_name].include? \'company\'\r\n                    tmp[j] = comp[v.to_s]\r\n                else\r\n                    tmp[j] = kcom[v.to_s]\r\n                end\r\n            else\r\n                tmp[j] = v\r\n            end\r\n        end\r\n        \r\n        tmp[:follow_up] = gr_foll[par_id].nil? ? 0 : gr_foll[par_id].size\r\n        \r\n        if tmp[:follow_up] != 0\r\n            pat_foll[pat_id] = gr_foll[par_id]\r\n            pat_foll[pat_id] << tmp\r\n            fol_list += gr_foll[par_id].collect{|i| i[:module_id]}\r\n        end\r\n        \r\n        rs_col << tmp\r\n    end\r\n    \r\n    res = {}\r\n    # res[:af]   = af\r\n    res[:res]  = rs_col.size\r\n    res[:mm_foll] = mm_foll.size\r\n    res[:imp_size] = imp_list.size\r\n    res[:fol_size] = fol_list.uniq.size\r\n    res[:pat_foll] = pat_foll\r\n    res[:pat_imp]  = pat_imp\r\n    res[:time] = Time.now - tb\r\n     \r\n%>\r\n<!-- Main Procedure -->\r\n<h3><%= doc_name.humanize %> total <%= rs_col.size %> records</h3>\r\n<%= colf.join(\'|\') %><br/>\r\n<%\r\nif false    \r\n    rs_col.each do |i|\r\n        colf.each do |j|\r\n%>\r\n<%= i[j] %>|\r\n<%\r\n        end\r\n%>\r\n<br/>\r\n<%\r\n    end\r\nend\r\n    if fol_list.size != 0\r\n        # field map\r\n        fm = get_doc_field fol_doc\r\n        @fm = fm\r\n%>\r\n<br/>\r\n\r\n<!-- Follow up -->\r\n<h3><%= fol_doc.humanize %> total <%= fol_list.size %> records</h3>\r\n<%\r\n    res_fol = get_model[fol_doc.to_sym].find(fol_list)\r\n    \r\n    # gr_fol = res_fol.group_by{|i| i.id}\r\n    gr_fol = res_fol.group_by{|i| i[:_id]}\r\n    \r\n    colf = [:id] + fm.keys - [:image, :recorder_by]\r\n%>\r\n<%= colf.join(\'|\') %><br/>\r\n<%\r\n    pat_foll.each do |k,v|\r\n        # id = k[5..14]\r\n        id = \"\\\\#{k}-\\\\#{v.count}\"\r\n\r\n        v.each do |i|\r\n            mid = i[:module_id]\r\n            obj = gr_fol[mid][0] if gr_fol[mid]\r\n            if obj.nil?\r\n                if !i[:hn].nil?\r\n                    i[:period] = \"0\"\r\n                    obj = i\r\n                else\r\n                    next\r\n                end\r\n            end\r\n            obj[:id] = id\r\n            \r\n            colf.each do |j|\r\n                if j == :period\r\n%>\r\n<%= obj[j] %>|\r\n<%\r\n                else\r\n%>\r\n<%= get_value j, obj[j] %>|\r\n<%\r\n                end\r\n            end\r\n%>\r\n<br/>\r\n<%\r\n        end\r\n%>\r\n<%\r\n    end\r\n    end # end fol_list.size // check for follow up\r\n    \r\n    if imp_list.size != 0\r\n%>\r\n<!-- Implant Profile -->\r\n<h3>Implant Profile total <%= imp_list.size %> records</h3>\r\n<%\r\n        m_company = get_model[:implant_company].all\r\n        m_component = get_model[:implant_component].all\r\n        m_type   = get_model[:implant_type].all\r\n        m_material  = get_model[:implant_material].all\r\n        \r\n        g_company = m_company.group_by{|i| i.id}\r\n        g_component = m_component.group_by{|i| i.id}\r\n        g_type    = m_type.group_by{|i| i.id}\r\n        g_material= m_material.group_by{|i| i.id}\r\n        \r\n        res_rec  = get_model[:implant_record].find(imp_list)\r\n        imp_ids  = res_rec.collect{|i| i[:component_description]}\r\n        res_imp  = get_model[:implant_profile].find(imp_ids)\r\n        \r\n        gr_rec   = res_rec.group_by{|i| i[:_id]}\r\n        gr_imp   = res_imp.group_by{|i| i[:_id].to_s}\r\n        \r\n        fm = get_doc_field \'implant_record\'\r\n        @fm = fm\r\n        \r\n        colf = [:id, :status] + fm.keys + [:product_id, :barcode]\r\n        \r\n        xxx = {}\r\n        xxx[:rec] = gr_rec\r\n        xxx[:imp] = gr_imp\r\n%>\r\n<%= colf.join(\'|\') %><br/>\r\n<% x = 0\r\n        pat_imp.each do |key, val|\r\n            id = key[5..14]\r\n            \r\n            val.each do |k,v|\r\n                st = k\r\n                v.each do |i|\r\n                    tmp = gr_rec[i]\r\n                    \r\n                    if tmp.nil?\r\n                        next\r\n                    end\r\n                    obj = tmp[0]\r\n                    obj[:id] = id\r\n                    obj[:status] = st\r\n                    \r\n                        x += 1\r\n                    colf.each do |j|\r\n                        v = obj[j]\r\n                        if v.nil? or v == \'\'\r\n                            v = \'\'\r\n                        elsif j == :company_ref_id\r\n                            v = g_company[v][0][:company_name]\r\n                        elsif j == :component_ref_id\r\n                            v = g_component[v][0][:component_name]\r\n                        elsif j == :type_ref_id\r\n                            v = g_type[v][0][:type_name]\r\n                        elsif j == :component_description\r\n                            a = v.to_s\r\n                            v = gr_imp[v.to_s][0][:component_description]\r\n                            if v\r\n                                obj[:product_id] = gr_imp[a][0][:product_id]\r\n                                obj[:barcode]    = gr_imp[a][0][:barcode]\r\n                            end\r\n                        end\r\n%>\r\n<%= v %>|\r\n<%\r\n                    end\r\n%>\r\n<br/>\r\n<%\r\n                end\r\n            end\r\n            \r\n            \r\n            if false # for implant profile display\r\n            val.each do |k, v|\r\n                st = k\r\n                v.each do |i|\r\n                    \r\n                    imp_id = gr_rec[i][0][:component_description] if gr_rec[i]\r\n                    \r\n                    if imp_id.nil?\r\n                        next\r\n                    end\r\n                    \r\n                    obj = gr_imp[imp_id.to_s][0] if gr_imp[imp_id.to_s]\r\n                    if obj.nil?\r\n                        # next\r\n                        obj = {}\r\n                        obj[:company_id] = imp_id\r\n                    end\r\n                    \r\n                    obj[:id] = id\r\n                    obj[:status] = k\r\n                    \r\n                    colf.each do |j|\r\n                        v = obj[j]\r\n                        \r\n                        if v.nil? or v == \'\'\r\n                            v = \'\'\r\n                        elsif j == :company_ref_id\r\n                            v = g_company[v][0][:company_name]\r\n                        elsif j == :component_ref_id\r\n                            v = g_component[v][0][:component_name]\r\n                        elsif j == :type_ref_id\r\n                            v = g_type[v][0][:type_name]\r\n                        elsif j == :material_ref_id\r\n                            v = g_material[v][0][:material_name]\r\n                        end\r\n                    \r\n%>\r\n<%= v %>|\r\n<%\r\n                    end\r\n%>\r\n<br/>\r\n<%\r\n                end\r\n            end\r\n            end # if false\r\n%>\r\n<% end %>\r\n<%\r\n    end # end imp_list.size // check for implant\r\n%>\r\n<%= x %>\r\n<hr/>\r\nProcessing Time : <%= Time.now - tb %>\r\n',NULL,NULL,NULL,'2017-06-17 07:57:59','2017-06-17 07:57:59','export_all',''),(3077,'show',1209,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;max-width:750px\">\r\n\r\n<%\r\n\r\n   @document =  get_document this.document_name \r\n   \r\n   model = get_model(this.table_name)\r\n   @patient_module = @module_model.find(params[:id])\r\n   record = model.find(@patient_module.module_id)\r\n   @record = record    \r\n  if request.post?\r\n    \r\n   \r\n    if p = params[\'cancel_\']\r\n        \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            old_app.destroy\r\n            mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>nil\r\n   \r\n    elsif p = params[\'postpone_\']\r\n    \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            # old_app.destroy\r\n            # mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        \r\n        \r\n        new_app = record.clone\r\n        new_app.update_attributes :date=>p[0][\'postpone_to\'],:status=>\'Appointed\'\r\n        \r\n        mm = @patient_module.clone\r\n        mm.module_id = new_app.id \r\n        mm.save    \r\n        \r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>p[0][\'postpone_to\'], :postpone_id=>new_app.id\r\n       \r\n        \r\n        \r\n    end\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Home/index\" />\r\n<% end %>\r\n<%= this.display.html_safe %>\r\n\r\n<div id=\"cancel\" style=\"display:none\"  class=\"alert alert-warning\">\r\n   <p>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'cancel_\'\r\n        field = @document.find_by_column_name \'cancel_reason\'\r\n        begin\r\n        %>\r\n        \r\n        <%#field%>\r\n        <div>\r\n        \r\n        <h3>Cancel</h3><br/>\r\n        <%# render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Cancelled\' %>\r\n        </div>\r\n        <script>\r\n        <%= yield :script %>\r\n        \r\n      \r\n        </script>\r\n        <% rescue Exception=>e %>\r\n        <%=e.message%>\r\n        <% end%>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n</div>\r\n\r\n<div id=\"postpone\" style=\"display:none;padding:10px\" class=\"alert alert-warning\">\r\n   \r\n      <p>\r\n        <h3>Postpone</h3><br/>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'postpone_\'\r\n        %>\r\n        <div>\r\n        \r\n       <% field = @document.find_by_column_name \'cancel_reason\' %>\r\n       <%# render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n       <% field = @document.find_by_column_name \'postpone_to\' %>\r\n       <%# render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Postpone\' %>\r\n        </div>\r\n       \r\n       \r\n        <script>\r\n        <%= yield :script %>\r\n        </script>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n   \r\n   \r\n</div>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<!--<%= link_to \'Cancel\'.html_safe, \"javascript:cancel()\",:class=>bt_class %> | -->\r\n<!--<%= link_to \'Postpone\'.html_safe, \"javascript:postpone()\",:class=>bt_class %> | -->\r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    \r\n    function cancel(){\r\n        $(\'#postpone\').hide()\r\n        $(\'#cancel\').slideDown()\r\n        $(\'#cancel_cancel_reason\').show()\r\n        \r\n    }\r\n    \r\n    function postpone(){\r\n        $(\'#cancel\').hide()\r\n        $(\'#postpone\').slideDown()\r\n        $(\'#postpone_postpone_to\').show()\r\n\r\n    }\r\n    \r\n    function cancel_ctrl(){\r\n        $(\'#postpone\').slideUp()\r\n        $(\'#cancel\').slideUp()\r\n    }\r\n    $(\'.ctrl\').hide();\r\n</script>',NULL,NULL,NULL,'2017-06-17 16:11:16','2017-06-17 16:11:16','show',''),(3078,'endoscopist_report',789,2,'<%\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    \r\n    forms = %w{colono gastro dbe sigmoid push_enteroscopy ercp eus liver_biopsy percutaneous_drainage liver_ultrasound_and_fibroscan }\r\n    pmap = {}\r\n    map = {}\r\n    names = []\r\n    providers = @models[:provider].collection.find({},{:fields=>{:_id=>1,:name=>1}}).to_a\r\n    \r\n    for i in providers\r\n        pmap[i[\'_id\']] = {:p=>i[\'name\'],:f=>{}}\r\n        names << [i[\'name\'],i[\'_id\']]\r\n    end\r\n    \r\n    names.sort!{ |a,b| a[0]<=>b[0] }\r\n    \r\n      for i in forms\r\n        records = @models[i.to_sym].collection.find({},{:fields=>{:_id=>1,:endoscopist=>1}}).to_a\r\n        \r\n        for  r in  records \r\n        \r\n        if pmap[r[\'endoscopist\']] \r\n        pmap[r[\'endoscopist\']][:f][i] = 0  unless  pmap[r[\'endoscopist\']][:f][i]\r\n        pmap[r[\'endoscopist\']][:f][i] += 1\r\n    end\r\n        end\r\n    \r\n    end\r\n    \r\n%>\r\n<table class=\"table\">\r\n<thead>\r\n<tr><th>&nbsp;</th>\r\n<%\r\n  for i in forms\r\n%>\r\n<th><%=i%></th>\r\n<% end %>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<% for i in names %>\r\n<tr>\r\n    <th><%=i[0]%></th>\r\n    <% for f in forms \r\n        v = 0 \r\n        v = pmap[i[1]][:f][f] if pmap[i[1]][:f][f]\r\n    %>\r\n    <td><%= v %></td>\r\n    <% end %>\r\n</tr>\r\n<% end %>\r\n</tbody>\r\n</table>\r\n\r\n',NULL,NULL,NULL,'2017-06-20 04:04:22','2017-06-20 04:04:22','endoscopist_report',''),(3079,'index',729,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'index\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2017-06-22 03:12:41','20