{order.order_id} (\\\\#{order.order_date})\r\n\r\n\r\nYou order form Treesci innovation. \\\\#{order.order_id} (\\\\#{order.order_date})\r\nplease check status form http://order.treesci.com\r\nStatus - \\\\#{order.status }\r\nCustomer - \\\\#{order.customer.name }\r\n\r\nOrder by - \\\\#{@current_user}\r\nTotal price - \\\\#{order.total_amount } Baht\r\nMESSAGE_END\r\nNet::SMTP.start(\'smtp.treesci.com\', 25, \'mail.treesci.com\',\'info@treesci.com\', \'minadadmin\', :plain) do |smtp|\r\n  smtp.send_message message, \'info@treesci.com\', email , customeremail\r\nend\r\n\r\n\r\n%>\r\n            ',NULL,NULL,NULL,'2017-06-22 04:43:07','2017-06-22 04:43:07','send_mail',''),(3081,'search_result',1215,3,'<% \r\n\r\nrequire \'time_diff\'\r\n\r\n    models = get_model  \r\n\r\n    @document = get_document(this.document_name)\r\n    model = models[:patient]\r\n    att_model = models[:attachment]\r\n    patient = model.find(params[:id])\r\n    date = Time.now.to_datetime\r\n    if patient \r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    diff = Time.diff(date, birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    \r\n    #year = (t/365).to_i\r\n    #t%=365\r\n    #month = (t/30).to_i\r\n	#t%=30\r\n	#day = t.to_i\r\n    end\r\n%>\r\n<style>\r\nv {color:#00f}\r\n.patientname {padding:20px;float:left}\r\n</style>\r\n<div class=\"alert alert-block alert-success\">\r\n<div class=\"btn left imginfo\" style=\"height:100px;width:100px\">\r\n<%\r\nif patient.picture and patient.picture.size>0 \r\n pic = att_model.find(patient.picture[-1])\r\n if pic \r\n%>\r\n<%=image_tag \"\\\\#{pic.path}?thumb=1\",:height=>100 %>\r\n<% end \r\nend %>\r\n</div>\r\n\r\n<div class=\"left patientname\" >\r\n<p class=\"nameinfo\">\r\n<b> ชื่อ-สกุล : </b><v><%= patient.prefix_name %>  <%= patient.first_name %> <%= patient.last_name %></v>\r\n</p>\r\n<p class=\"ageinfo\">\r\n<b > Age : </b><v><%= year%> Years <%=month%> Months <%= day%> Days</v>\r\n</p>\r\n</div>\r\n\r\n<div class=\"left patientname\" >\r\n\r\n<p class=\"hninfo\">\r\n<b > เลขที่ศพ : </b><v> <%= patient.hn %></v>\r\n</p>\r\n<p class=\"idinfo\">\r\n<b > เลขบัตรประจำตัวประชาชน : </b><v><%=patient.public_id%> </v>\r\n</p>\r\n</div>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\npatient = <%= patient.to_json.html_safe %>;\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2017-06-22 05:02:59','2017-06-22 05:02:59','search_result',''),(3082,'print_partial',1201,3,'<%\r\n\r\n    \r\n    record = params[:record]\r\n    patient = params[:patient]\r\n    app = params[:appointment]\r\n    \r\n    models = get_model\r\n    \r\n    \r\n    @record = record\r\n    @document = params[:document]\r\n    \r\n    \r\ndage = Time.new.year.to_i-app.birth_date.year.to_i\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"wrapper\">\r\n<table width=\"100%\">\r\n<tr><td width=\"17%\"><img src=\"/esm/cusys/forensic/Logo_of_the_Faculty_of_Medicine,_Chulalongkorn_University.jpg\" width=\"100\"/></td><td width=\"65%\"><center>ศูนย์อำนวยการชันสูตรพลิกศพ คณะแพทย์ศาสตร์ จุฬาลงกรณ์หมาวิทยาลัย<br />\r\nถนนพระราม 4 แขวงปทุมวัน เขตประทุมวัน กรุงเทพ 10330<br />\r\nโทรศัทพ์ 022-564-436, 022-564-269 ต่อ 104,106</center></td><td width=\"18%\" align=\"right\"><img src=\"/esm/cusys/forensic/logo FMCU.jpg\" width=\"150\"/></td></tr>\r\n</table>\r\n<div id=\"page\">\r\n<div class=\"detail\">\r\n<center>\r\n  <strong>รายงานการตรวจชันสูตรพลิกศพ ณ สถานที่เกิดเหตุ</strong>\r\n</center>\r\n<p><strong><br />\r\n  เลขที่ศพ\r\n      \r\n  </strong> <%=patient.hn%> </p>\r\n<p>ชื่อผู้เสียชัวิต \r\n&nbsp;&nbsp;&nbsp;<%=patient.prefix_name %> <%=patient.first_name %> <%=patient.last_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;สัญชาติื <%=app.national %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; เพศ <%=app.sex %> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;อายุ :&nbsp;<%=dage %> ปี <p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ศาสนา <%=app.religion %></p>\r\n<p>รับแจ้งวันที่ &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;28&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; เดือน &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;มกราคม&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; พ.ศ. &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2560 &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;เวลา&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; start13.40 น. &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;เขตพื้นที่รับผิดชอบ <%=app.police_station %></p>\r\n<p>ตรวจศพวันที่ &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;28 &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;เดือน&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; มกราคม &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;พ.ศ. &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2560&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; เวาาชันสูตรพลิกศพ &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;15.29 น.</p>\r\n<p>สถานที่พบศพ <%=app.addr_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;บ้านเลขที่ <%=app.addr_no %> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ถนน <%=app.addr_road %>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;แขวง <%=app.addr_tambol %>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;เขต <%=app.addr_amphur %> &nbsp;&nbsp;&nbsp;&nbsp;จังหวัด <%=app.addr_province %> <br />\r\n\r\n    \r\n    \r\n</p>\r\n<p><br />\r\n  <br />\r\n</p>\r\n<div class=\"p1\">\r\n<p><strong>1. สภาพศพภายนอก / สภาพแวดล้อใ ณ สถานที่เกิดเหตุ</strong></p>\r\n<p>\r\n- <%=record.autopsy_summary.html_safe if record.autopsy_summary %>\r\n</p>\r\n\r\n<%\r\n    if record.rot_list \r\n    findings = models[:finding].find(record.rot_list)\r\n    for i in findings\r\n%>\r\n<p>- <%= i.summary %></p>\r\n<% end %>\r\n<% end %>\r\n\r\n<%\r\n    if record.wound_list \r\n    findings = models[:finding].find(record.wound_list)\r\n    for i in findings\r\n%>\r\n<p>- <%= i.summary %></p>\r\n<% end %>\r\n<% end %>\r\n\r\n<%\r\n    if record.bone_list \r\n    findings = models[:finding].find(record.bone_list)\r\n    for i in findings\r\n%>\r\n<p>- <%= i.summary %></p>\r\n<% end %>\r\n<% end %>\r\n\r\n<%\r\n    if record.rigor_list \r\n    findings = models[:finding].find(record.rigor_list)\r\n    for i in findings\r\n%>\r\n<p>- <%= i.summary %></p>\r\n<% end %>\r\n<% end %>\r\n\r\n<%\r\n    if record.liver_list \r\n    findings = models[:finding].find(record.liver_list)\r\n    for i in findings\r\n%>\r\n<p>- <%= i.summary %></p>\r\n<% end %>\r\n<% end %>\r\n\r\n\r\n</div><br/>\r\n<p><strong>ประวัติผู้ตาย :</strong> <%=render_value \'dead_history\'%></p>\r\n<p><strong>โรคประจำตัว :</strong> <%=render_value \'congenital_disease\'%></p>\r\n<p><strong>ยา :</strong> <%=render_value \'medicine_note\'%><br />\r\n  <br />\r\n</p>\r\n<p><strong>2. ความเห็นของแพทย์</strong></p>\r\n<p>- สาเหตุการตายเบื้องตัน <%=render_value \'dead_cause\'%><br />\r\n- ประมาณระยะเวลาที่เสียชีวิต : <%=render_value \'dead_hour\'%><%=render_value \'dead_day\'%><%=render_value \'dead_month\'%>  <br />\r\n  <br />\r\n</p>\r\n<p><strong>3. ดำเนินการโดย</strong></p>\r\n- <%=render_value \'dead_plan\'%><br />\r\n\r\n</div>\r\n<table width=\"100%\">\r\n<tr>\r\n<%\r\n    @record = app\r\n    @document = get_document \'appointment\'\r\n\r\n%>\r\n    <td width=\"50%\" align=\"center\">ลงชื่อ.....................................<br />\r\n    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<%=render_value \'provider_2\' %>)<br />\r\n    &nbsp;&nbsp;พนักงานสอบสวน</td>\r\n    <td width=\"50%\" align=\"center\">ลงชื่อ.....................................<br />\r\n    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<%=render_value \'provider\' %>)<br />\r\n    &nbsp;&nbsp;&nbsp;&nbsp;แพทย์ชันสูตรพลิกศพ</td>\r\n</tr>\r\n</table>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n',NULL,NULL,NULL,'2017-06-22 05:53:25','2017-06-22 05:53:25','print_partial',''),(3083,'display',1218,3,'<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inl