lor:#000;background:none;font-size:16px;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.detail { height:1100px}\r\n.p1 {height:500px}\r\n\r\n@media print {\r\n    .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  @app_module = @module_model.find(@patient_module.parent_id)\r\n  \r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @appointment =  get_model(\'appointment\').find(@app_module.module_id)\r\n   @record = record\r\n   params[:patient]=@patient \r\n   params[:appointment] = @appointment\r\n   params[:record] = @record\r\n   params[:document] = @document\r\n%>\r\n<%=this.print_partial%>\r\n<%# params.inspect  %>\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2017-06-22 06:31:26','2017-06-22 06:31:26','print',''),(3087,'patient',1207,2,'<%\r\n    td = Time.now # today\r\n    td_str = td.strftime(\'%d/%m/%Y\')\r\n    tm_str = td.strftime(\'%H:%M\')\r\n    \r\n    ra = get_model[:region].all.sort_by{|i| i[:name]}\r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				<b> <i class=\"splashy-contact_grey_add\"></i>New Case</b>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding:10px\">\r\n				<form action=\"index\" accept-charset=\"UTF-8\" method=\"post\">\r\n					<div class=\"w-box\">\r\n					    <div class=\"form-horizontal well\">\r\n					        <div id=\"form-appointment\">\r\n					            <br/><br/>\r\n					            <center><span style=\'font-size:1.2em\'>... Loading Please Wait ...</span></center>\r\n					            <br/><br/>\r\n					        </div>\r\n					    </div>\r\n					    <div class=\'clear\'></div>\r\n					    <center>\r\n							<div id=\"temporary\" style=\"\"></div>\r\n							<input type=\"hidden\" name=\"record[status]\" id=\"data-status\" value=\"Appointed\">\r\n							<input type=\"hidden\" name=\"record[created_by]\" id=\"data-created_by\" value=\"<%= @current_user[:login] %>\">\r\n							<input type=\"hidden\" name=\"record[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user[:login] %>\">\r\n							<input type=\"submit\" name=\"commit\" value=\"+Add New Case\" class=\"btn btn-success\">\r\n							<a href=\"index\" class=\"btn \" >Cancel</a>  \r\n						</center>\r\n						<div class=\"clear\"></div>\r\n					    <% if false %>\r\n						<div class=\"form-horizontal well\">\r\n							<div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label style=\'margin-top:22px\'>เลขที่ศพ <span class=\"f_req\">*</span>  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"pat[hn]\" id=\"data-hn\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\">\r\n							</div>\r\n							<div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\"><label>วันที่รับแจ้ง <br>(dd/mm/yyyy): </label></span>	\r\n								<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n									<span class=\"k-widget k-datepicker k-header k-input\" style=\"width: 100px;\"><span class=\"k-picker-wrap k-state-default\">\r\n									<input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= td_str %>\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 7 มิถุนายน 2017\">\r\n									<span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n									<script>\r\n										$(\"#data-date\").kendoDatePicker({\r\n											value: \'<%= td_str %>\',\r\n										});\r\n									</script>\r\n								</div>\r\n							</div>\r\n							<div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\"><label>เวลา <br>(HH.MM) : </label></span>\r\n								<span class=\"k-widget k-timepicker k-header k-input\" style=\"width: 80px;\">\r\n								<span class=\"k-picker-wrap k-state-default\">\r\n								<input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"2015-06-03 08:00:00 +0700\" style=\"width: 100%;\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\">\r\n								<span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n								<span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n								</span>\r\n								</span>\r\n								</span>\r\n								<script>\r\n									$(\"#data-start\").kendoTimePicker({\r\n										value: \'08:00\',\r\n										interval: 10,\r\n										parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n										change: function(event){\r\n											var v = $(\'#data-start\').val()\r\n											if(v.length==3){\r\n												$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n											}\r\n											 \r\n										}\r\n									});\r\n								</script>\r\n							</div>\r\n							<!--\r\n							<div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>เลขที่บัตรประชาชน : </label></span>	\r\n								<input type=\"text\" name=\"pat[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n							</div>\r\n							-->\r\n							<div class=\"clear\"></div>\r\n							<hr/>\r\n							<div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\"><label>Prefix name : </label></span>	\r\n								<span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n								<span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n								<input name=\"pat[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" autocomplete=\"off\" tabindex=\"0\" maxlength=\"32\" style=\"vertical-align: text-top; width: 100%;\" aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" aria-owns=\"data-prefix_name_listbox\" aria-busy=\"false\" id=\"input-prefix_name\" aria-activedescendant=\"data-prefix_name_option_selected\">\r\n								<span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n								<span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-prefix_name_listbox\">select</span>\r\n								</span>\r\n								</span>\r\n								<input type=\"text\" name=\"pat[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n								</span>\r\n							</div>\r\n							<div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label>First name<span class=\"f_req\">*</span>  : </label></span>	\r\n								<input type=\"text\" name=\"pat[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\">\r\n							</div>\r\n							<div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label>Last name : </label></span>	\r\n								<input type=\"text\" name=\"pat[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<!--<div class=\"clear\"></div>-->\r\n							<div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\"><label>Gender : </label></span>	\r\n								<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n									<select name=\"pat[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n										<option value=\"0\">ไม่ระบุ</option>\r\n										<option value=\"1\">ชาย</option>\r\n										<option value=\"2\">หญิง</option>\r\n									</select>\r\n								</div>\r\n							</div>\r\n							<div id=\"religion\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label>Religion  : </label></span>	\r\n								<input type=\"text\" name=\"pat[religion]\" id=\"data-religion\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\"><label>Birthdate or Age </label></span>	\r\n								<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n									<span class=\"k-widget k-datepicker k-header k-input\" style=\"width: 120px;\"><span class=\"k-picker-wrap k-state-default\">\r\n									<input type=\"text\" name=\"pat[birth_date]\" id=\"data-birth_date\" value=\"<%= td_str %>\" style=\"width: 100%;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 7 มิถุนายน 2017\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n									<script>\r\n										$(\"#data-birth_date\").kendoDatePicker({\r\n											value: \'<%= td_str %>\',\r\n										});\r\n									</script>\r\n								</div>\r\n							</div>\r\n							<div class=\"clear\"></div>\r\n							<div id=\"provider_2\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label >พนักงานสอบสวน : </label></span>	\r\n								<!--<input type=\"text\" name=\"app[region]\" id=\"data-region\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >-->\r\n							    \r\n							    <select name=\"app[provider_2]\" id=\"data-provider_2\" style=\'width:100%;height:2.0em\'>\r\n							        <option value=\"\"></option>\r\n							    <%\r\n							        pol = get_model[:provider].where(:provider_type=>\'8\').all\r\n							        pol.each do |i|    \r\n							    %>\r\n							        <option value=\"<%= i.id.to_s %>\"><%= i[:name] %></option>\r\n							    <%  end %>\r\n							    </select>\r\n							    \r\n							</div>\r\n							<div id=\"tel_provider_2\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label >หมายเลขโทรศัพท์ : </label></span>	\r\n								<input type=\"text\" name=\"app[tel_provider_2]\" id=\"data-tel_provider_2\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"region\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label >เขตที่รับผิดชอบ : </label></span>	\r\n								<!--<input type=\"text\" name=\"app[region]\" id=\"data-region\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >-->\r\n							    \r\n							    <select name=\"app[region]\" id=\"data-region\" style=\'width:100%;height:2.0em\'>\r\n							        <option value=\"\"></option>\r\n							    <%\r\n							        ra.each do |i|    \r\n							    %>\r\n							        <option value=\"<%= i.id.to_s %>\"><%= i[:name] %></option>\r\n							    <%  end %>\r\n							    </select>\r\n							    \r\n							</div>\r\n							<!--<div class=\'clear\'></div>-->\r\n							\r\n							<div id=\"note\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label >สาเหตุการตายเบื้องต้น : </label></span>	\r\n								<input type=\"text\" name=\"app[note]\" id=\"data-note\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div class=\"clear\"></div>\r\n							\r\n							<div id=\"provider\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label>แพทย์ที่ปฎิบัติงาน : </label></span>	\r\n								<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n									<select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n										<option value=\"\"></option>\r\n<%\r\n    prov = get_model[:provider].where(:provider_type=>\'1\').all.sort_by{|i| i[:name]}\r\n    prov.each do |i|\r\n%>\r\n                                        <option value=\"<%= i.id.to_s %>\"><%= i[:name] %></option>\r\n<% end %>\r\n									</select>\r\n								</div>\r\n							</div>\r\n							<div class=\'clear\'></div>\r\n							<h3>สถานที่พบศพ</h3>\r\n							<div id=\"address-no\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>บ้านเลขที่  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_no]\" id=\"data-address_no\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-name\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>หมู่บ้าน/อาคาร/คอนโด  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_name]\" id=\"data-address_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-soi\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>ซอย  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_soi]\" id=\"data-address_soi\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-moo\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>หมู่  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_moo]\" id=\"data-address_moo\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-road\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>ถนน  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_road]\" id=\"data-address_road\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-tambol\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>ตำบล  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_tambol]\" id=\"data-address_tambol\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-amphur\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>อำเภอ  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_amphur]\" id=\"data-address_amphur\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"address-province\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n								<span class=\"\"><label>จังหวัด  : </label></span>	\r\n								<input autofocus=\"\" type=\"text\" name=\"app[addr_province]\" id=\"data-address_province\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<br>\r\n							<div class=\'clear\'></div>\r\n							<div id=\"contact\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label>ผู้พบศพ  : </label></span>	\r\n								<input type=\"text\" name=\"app[contact]\" id=\"data-contact\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div id=\"tel_contact\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n								<span class=\"\">\r\n								<label>หมายเลขโทรศัพท์  : </label></span>	\r\n								<input type=\"text\" name=\"app[tel_contact]\" id=\"data-tel_contact\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" >\r\n							</div>\r\n							<div class=\'clear\'></div>\r\n							<div id=\"temporary\" style=\"\"></div>\r\n							<input type=\"hidden\" name=\"app[status]\" id=\"data-status\" value=\"Appointed\">\r\n							<input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user[:login] %>\">\r\n							<input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user[:login] %>\">\r\n							<input type=\"submit\" name=\"commit\" value=\"+Add New Case\" class=\"btn btn-success\">\r\n							<a href=\"index\" class=\"btn \" >Cancel</a>  \r\n							<div class=\"clear\"></div>\r\n						</div>\r\n						<% end %>\r\n					</div>\r\n				</form>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<script >\r\n    $(document).ready(function(){\r\n        $(\'#form-appointment\').load(\'../Appointment/create #form-data\', function() {\r\n            $(\"#data-date\").kendoDatePicker({\r\n				value: \'<%= td_str %>\',\r\n			});\r\n			$(\"#data-operation_date\").kendoDatePicker({\r\n				value: \'<%= td_str %>\',\r\n			});\r\n            $(\"#data-start\").kendoTimePicker({\r\n              value: \'<%= tm_str %>\',\r\n              interval: 10,\r\n              parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n              change: function(event){\r\n                var v = $(\'#data-start\').val()\r\n                if(v.length==3){\r\n                  $(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                }\r\n                 \r\n              }\r\n            });\r\n            $(\"#data-operation_time\").kendoTimePicker({\r\n              value: \'<%= tm_str %>\',\r\n              interval: 10,\r\n              parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n              change: function(event){\r\n                var v = $(\'#data-operation_time\').val()\r\n                if(v.length==3){\r\n                  $(\'#data-operation_time\').val(v[0]+\":\"+v[1]+v[2])\r\n                }\r\n                 \r\n              }\r\n            });\r\n        });\r\n        \r\n    });\r\n</script>\r\n\r\n<% if false %>\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"}\r\n        ]\r\n	\r\n    });\r\n    \r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    \r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2017-06-22 06:39:13','2017-06-22 06:39:13','patient',''),(3088,'edit',1209,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  pat   = @patient_model.find(@patient_module[:patient_id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n   \r\n  \r\n  \r\n  \r\n  if request.post?\r\n  \r\n    \r\n    doc = get_document this.document_name\r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:ti