tor.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   ',NULL,NULL,NULL,'2017-06-22 08:24:14','2017-06-22 08:24:14','edit',''),(3090,'display',1201,3,'<% return_url=\'\' %>\r\n<style>\r\n    .document-border { width:100%;}\r\n    \r\n</style>\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  @app_module = @module_model.find(@patient_module.parent_id)\r\n  \r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @appointment =  get_model(\'appointment\').find(@app_module.module_id)\r\n   @record = record\r\n   params[:patient]=@patient \r\n   params[:appointment] = @appointment\r\n   params[:record] = @record\r\n   params[:document] = @document\r\n%>\r\n<div class=\"span12\" style=\"overflow:scroll\">\r\n<div class=\"\" style=\"width:100%;max-width:720px;padding:20px\">\r\n<%=this.print_partial%>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-06-22 09:12:20','2017-06-22 09:12:20','display',''),(3091,'login',1224,4,'<html>\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n\r\n <!-- Bootstrap framework -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap.min.css\" />\r\n            <link rel=\"stylesheet\" href=\"/gebo/bootstrap/css/bootstrap-responsive.min.css\" />\r\n        <!-- theme color-->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/dark.css\" />\r\n        <!-- tooltip -->    \r\n			<link rel=\"stylesheet\" href=\"/gebo/lib/qtip2/jquery.qtip.min.css\" />\r\n        <!-- main styles -->\r\n            <link rel=\"stylesheet\" href=\"/gebo/css/style.css\" />\r\n<style>\r\ninput, textarea, select, .uneditable-input { height:28px;}\r\n.login_page .cnt_b {\r\n    width: 80%;}\r\n.login_page .cnt_b { padding:15px 0}\r\n.login_page .login_box {\r\n    width: 310px;\r\n    background: none;\r\n    border: 0px solid #ccc;}\r\n@media (max-width: 767px)\r\n{\r\n.input-prepend input, .input-append input, .input-prepend input[class*=\"span\"], .input-append input[class*=\"span\"] {\r\n    width: 210px;\r\n}\r\n}\r\n</style>            \r\n</head>\r\n<body class=\"login_page\" style=\"background:url(/esm/cuforensic/www/bgContentlogin.jpg) center no-repeat;\r\nbackground-size: cover;\">\r\n<script src=\"/gebo/js/jquery.min.js\"></script>\r\n<script src=\"/gebo/js/jquery.actual.min.js\"></script>\r\n<script src=\"/gebo/lib/validation/jquery.validate.min.js\"></script>\r\n<script src=\"/gebo/bootstrap/js/bootstrap.min.js\"></script>\r\n<%\r\n	p = {}\r\n	if @current_project \r\n	tp = @current_project.get_params if @current_project \r\n	p = tp if tp\r\n	end\r\n	title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"ESM:Innovation as a Service\"\r\n	bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#eee\"\r\n	logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n%>\r\n\r\n<%\r\n    user = \'\'\r\n	user = params[:user][:login] if params[:user]\r\n%>\r\n<%= form_for :user, :action=>\'login\' do|form|%>\r\n\r\n	<div class=\"login_box\" style=\"height:320px;top:0;bottom: 0;left: 0;right: 0;margin: auto;\">\r\n		\r\n		<form action=\"/forensic/Home/index\" method=\"post\" id=\"login_form\">\r\n			<div class=\"formSep\" style=\"text-align:center;padding-top:5px\"><a href=\"/\">\r\n            <img src=\"/esm/cuforensic/www/logo_chula.png\" width=\"200\">\r\n            </a>\r\n			</div>    \r\n			\r\n			\r\n			\r\n	  \r\n\r\n			\r\n			<div class=\"cnt_b\">\r\n			\r\n					\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-user\"></i></span>\r\n						<%= form.text_field \"login\", :size => 20,:id=>\'user_login\',:placeholder=>\"Email or Login ID\",\'data-icon\'=>\"user\",:value=>user%>\r\n					   \r\n					</div>\r\n				</div>\r\n				<div class=\"formRow\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-lock\"></i></span>\r\n						<%= form.password_field \"password\", :size => 20,:id=>\'user_password\',:placeholder=>\"Password\",\'data-icon\'=>\"closed-lock\"%>\r\n						\r\n					</div>\r\n				</div>\r\n					<%  unless @current_solution %>\r\n				<span id=\"solution_id_toggle\"><center><a href=\"javascript:$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\">...</a></center></span>	\r\n				<div class=\"formRow\" id=\"solution_id\" style=\"display:none\">\r\n					<div class=\"input-prepend\">\r\n						<span class=\"add-on\"><i class=\"icon-book\"></i></span>\r\n						<%= text_field_tag \"user[esm]\",cookies[:esm], :size => 20,:id=>\'esm\',:placeholder=>\"Solution ID\",\'data-icon\'=>\"settings\"%>\r\n					</div>\r\n				</div>\r\n				<script>\r\n				    $(document).ready(function(){\r\n				<% if cookies[:esm] %>\r\n					$(\'#solution_id\').show();$(\'#solution_id_toggle\').hide();\r\n				<%  end %>\r\n			  });\r\n				</script>\r\n				\r\n					<% else %>\r\n						<%= form.hidden_field \"esm\", :value=> @current_solution.name %>\r\n						<%= form.hidden_field \"project_id\", :value=> @current_project.id if @current_project%>\r\n					<% end %>\r\n					\r\n					\r\n				<div class=\"formRow clearfix\"><br />\r\n					<button class=\"btn\" style=\"width:97%\" type=\"submit\">Sign In</button><br />\r\n                    <label class=\"checkbox\" style=\"color:#FFF\"><input id=\"ck\" name=\'remember\' type=\"checkbox\" /> Remember me</label>\r\n                    \r\n				</div>\r\n			</div>\r\n			<div class=\"clearfix\" >\r\n				\r\n				<% if flash[:error] %>\r\n			<div class=\"alert\" style=\"color:#903\">\r\n				<%= flash[:error] %>\r\n			</div>\r\n			<% else %>\r\n			\r\n			<% end %>\r\n				\r\n			</div>  \r\n		</form>\r\n		\r\n		\r\n		\r\n	\r\n		\r\n	</div>\r\n	\r\n\r\n		\r\n	</div>  \r\n   <% end %>\r\n\r\n    <script>\r\n        $(document).ready(function(){\r\n            \r\n			//* boxes animation\r\n			form_wrapper = $(\'.login_box\');\r\n            $(\'.linkform a,.link_reg a\').on(\'click\',function(e){\r\n				var target	= $(this).attr(\'href\'),\r\n					target_height = $(target).actual(\'height\');\r\n				$(form_wrapper).css({\r\n					\'height\'		: form_wrapper.height()\r\n				});	\r\n				$(form_wrapper.find(\'form:visible\')).fadeOut(400,function(){\r\n					form_wrapper.stop().animate({\r\n                        height	: target_height\r\n                    },500,function(){\r\n                        $(target).fadeIn(400);\r\n                        $(\'.links_btm .linkform\').toggle();\r\n						$(form_wrapper).css({\r\n							\'height\'		: \'\'\r\n						});	\r\n                    });\r\n				});\r\n				e.preventDefault();\r\n			});\r\n			\r\n			//* validation\r\n			$(\'#login_form\').validate({\r\n				onkeyup: false,\r\n				errorClass: \'error\',\r\n				validClass: \'valid\',\r\n				rules: {\r\n					username: { required: true, minlength: 3 },\r\n					password: { required: true, minlength: 3 }\r\n				},\r\n				highlight: function(element) {\r\n					$(element).closest(\'div\').addClass(\"f_error\");\r\n				},\r\n				unhighlight: function(element) {\r\n					$(element).closest(\'div\').removeClass(\"f_error\");\r\n				},\r\n				errorPlacement: function(error, element) {\r\n					$(element).closest(\'div\').append(error);\r\n				}\r\n			});\r\n        });\r\n    </script>\r\n\r\n\r\n		<script type=\"text/javascript\">\r\n		try{document.getElementById(\'user_login\').focus();}catch(e){}\r\n		</script>\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n\r\n    \r\n\r\n',NULL,NULL,NULL,'2017-06-23 01:21:38','2017-06-23 01:21:38','login',''),(3092,'export_field',1173,3,'<%= render :inline=>this.common_function %>\r\n<% \r\n    tb = Time.now \r\n    \r\n    params[:date] = \'all\'\r\n    doc_name = \'knee1\'\r\n    if params[:proc]\r\n        doc_name = params[:proc]\r\n    end\r\n    hos_code = nil\r\n    if params[:hosp]\r\n        hos_code = params[:hosp]\r\n    end\r\n    \r\n    fol_doc = \'follow_up_knee\'\r\n    if doc_name.include? \'hip\'\r\n        fol_doc = \'follow_up_hip\'\r\n    end\r\n    \r\n    def get_doc_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].strip\r\n                    tmp[:list] << x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    # @fm = fm\r\n    def get_value f, val\r\n        x = @fm[f.to_sym]\r\n        v = val\r\n        if x.to_h.has_key? :pair and !v.nil? and v != \'\'\r\n            # if f.to_sym == :if_rrt or f.to_sym == :vasopressor\r\n            #     v = x[:pair][v]\r\n            # else\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n                # v = \"<span title=\'\\\\#{v}\'>\\\\#{val} <i class=\'splashy-help\'></i></span>\".html_safe\r\n            # end\r\n        end\r\n            # if f.to_sym == :delivered_lose and !v.nil? and v != \'\'\r\n            #         v = v.to_f.round(4) if Float(v) rescue v\r\n            # end\r\n        # if v.nil? or v == \'\'\r\n        #     v = \'-\'\r\n        # end\r\n        return v\r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	m_pat = @ehr_model[:patient]\r\n	m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	# map prov_id <-> provider_name\r\n	prov = {}\r\n	a_prov = get_model[:provider].all\r\n	a_prov.each do |i|\r\n	    prov[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map company_id <-> company_name\r\n	comp = {}\r\n	a_comp = get_model[:company].all\r\n	a_comp.each do |i|\r\n	    comp[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map hospital_id <-> hospital_name\r\n	hosp = {}\r\n	a_hosp = get_model[:hospital].all\r\n	a_hosp.each do |i|\r\n	    hosp[i.id.to_s] = i[:hospital_name_thai]\r\n	end\r\n	\r\n	# map knee_component <--> component_name\r\n	kcom = {}\r\n	a_temp = get_model[:knee_component].all\r\n	a_temp.each do |i|\r\n	    kcom[i.id.to_s] = i[:name]\r\n	end\r\n	# map hip component <-> component_name\r\n# 	hcom = {}\r\n# 	a_temp = get_model[:hip_component].all\r\n# 	a_temp.each do |i|\r\n# 	    hcom[i.id.to_s] = i[:name]\r\n# 	end\r\n    \r\n# -------------------------------------------    \r\npf = [:id, :proc, :hospital_name, :age, :gender]\r\ncolf = pf + [:patient_asa_grade, :side, :bilateral, :anesthetic_types, :indication_for_surgery, :chemical, :mechanical, :procedure, :approach, :computer_assist]\r\n%>\r\n<%= colf.join(\'|\') %><br/>\r\n<%\r\n\r\ndoc_list = [doc_name]\r\n\r\nif doc_name == \'all\'\r\n    doc_list = %w{hip1 hip2 knee1 knee2}\r\nend\r\n\r\ndoc_list.each do |doc_name|\r\n    # follow up\r\n    # mm_foll = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{fol_doc}\", :parent_id=>par_ids).all\r\n    # gr_foll = mm_foll.group_by{|i| i[:parent_id].to_s}\r\n    \r\n    # map patient_id <-> patient\r\n    # ig_pat = %w{55af2feb790f9b6127000003	55c21a68790f9b30e8000003	55af3548790f9b6e5f000003	55affd22790f9b19c600001a	55afff02790f9b08ee00001a	55c254ab790f9b0ddc000016	569fa3d9790f9b0c14000007	57a7514c790f9b6f5f000031	57ea9a2e790f9b475d000002	55c21dbf790f9b4041000001	55c7d26d790f9b62e8000014	55ee3b4f790f9b7114000010	5783159a790f9b3887000012	56b0811b790f9b31ac000025	56b88898790f9b07e2000013	56b98fb6790f9b4348000005	56df9a87790f9b45db0000a7	5785a75d790f9b676d00003d	57906b43790f9b296200001f	57938c9d790f9b6988000004	5793a234790f9b053f000001	57944abd790f9b2411000001	57958eba790f9b534e000034	579592ed790f9b6975000005	57a083d4790f9b2af3000011	57a083f9790f9b2af3000013	57a09623790f9b5a24000002	57a1653f790f9b3b76000005	57abe367790f9b2ca3000001	57abe9e6790f9b232a000010	57abeb90790f9b232a000015	57abfc52790f9b452c00001c	57ac1945790f9b63c4000011	57ac1e16790f9b79f0000014	57ac1e16790f9b7577000047	57ac2adb790f9b7a5a00004b	57ac2f6c790f9b19de000003	57ac3014790f9b196e00000a	57ac3019790f9b196300000f	57ac3025790f9b1963000011	57ac3083790f9b196300001a	57ad6b56790f9b458d000013	57ad7318790f9b53e3000001	57ad7318790f9b4f0f00000a	57ad7b72790f9b55ee000004	57ad8186790f9b55ee00000e	57ad82f1790f9b66b8000001	57b2a657790f9b0d18000001	57b7bf98790f9b30a900000c	57b7fc4d790f9b0deb000001	57bd4561790f9b5a0700000f	57c3dee8790f9b755400000b	57e155c0790f9b44ab000021	57e163ce790f9b4bd1000003	57ac2990790f9b79f000003b	57ad82bf790f9b6615000001	57ad82f0790f9b6422000003	57ad8ef3790f9b717f00000e	57ad82f5790f9b66b8000003	57ad82f7790f9b6422000005	57ad82f7790f9b6615000003	57ad8318790f9b6615000005	57ad831c790f9b6615000007	57ed3b70790f9b2264000001	57ed3bca790f9b2264000007	57ae846d790f9b2516000001	57ae8ef0790f9b397c000003	57aea21a790f9b457d000001	57aea8fe790f9b5603000001	57ff023c790f9b7a1000000e	55f8c301790f9b42b1000003	55fc4a9d790f9b6636000001	5604e196790f9b585d000016	561da4d6790f9b7d63000001	56d66206790f9b360d000014}\r\n    # ig_pat = %w{55af2feb790f9b6127000003	55c21a68790f9b30e8000003	55af3548790f9b6e5f000003	55affd22790f9b19c600001a	55afff02790f9b08ee00001a	55eb1062790f9b4d1c000002	5781f86e790f9b57b900002c	57ecd459790f9b151700001a	55c254ab790f9b0ddc000016	569fa3d9790f9b0c14000007	57a7514c790f9b6f5f000031	57ea9a2e790f9b475d000002	55f8c301790f9b42b1000003	55fc4a9d790f9b6636000001	5604e196790f9b585d000016	561da4d6790f9b7d63000001	56d66206790f9b360d000014	55c21dbf790f9b4041000001	55c7d26d790f9b62e8000014	55ee3b4f790f9b7114000010	5783159a790f9b3887000012	56b0811b790f9b31ac000025	56b88898790f9b07e2000013	56b98fb6790f9b4348000005	56df9a87790f9b45db0000a7	5785a75d790f9b676d00003d	57906b43790f9b296200001f	57938c9d790f9b6988000004	5793a234790f9b053f000001	57944abd790f9b2411000001	57958eba790f9b534e000034	579592ed790f9b6975000005	57a083d4790f9b2af3000011	57a083f9790f9b2af3000013	57a09623790f9b5a24000002	57a1653f790f9b3b76000005	57abe367790f9b2ca3000001	57abe9e6790f9b232a000010	57abeb90790f9b232a000015	57abfc52790f9b452c00001c	57ac1945790f9b63c4000011	57ac1e16790f9b79f0000014	57ac1e16790f9b7577000047	57ac2adb790f9b7a5a00004b	57ac2f6c790f9b19de000003	57ac3014790f9b196e00000a	57ac3019790f9b196300000f	57ac3025790f9b1963000011	57ac3083790f9b196300001a	57ad6b56790f9b458d000013	57ad7318790f9b53e3000001	57ad7318790f9b4f0f00000a	57ad7b72790f9b55ee000004	57ad8186790f9b55ee00000e	57ad82f1790f9b66b8000001	57b2a657790f9b0d18000001	57b7bf98790f9b30a900000c	57b7fc4d790f9b0deb000001	57bd4561790f9b5a0700000f	57c3dee8790f9b755400000b	57e155c0790f9b44ab000021	57e163ce790f9b4bd1000003	57ac2990790f9b79f000003b	57ac2d1a790f9b63c4000085	57ac300e790f9b196e000008	57ac3016790f9b19de000005	57aeb227790f9b5f5b000009	57c653c3790f9b2ddd000006	583fb46b790f9b422c00000b	57ac302c790f9b196e00000c	57ac3040790f9b194c000006	57ad82bf790f9b6615000001	57ad82f0790f9b6422000003	57ad8ef3790f9b717f00000e	57ad82f5790f9b66b8000003	57ad82f7790f9b6422000005	57ad82f7790f9b6615000003	57ad8318790f9b6615000005	57ad831c790f9b6615000007	57ed3b70790f9b2264000001	57ed3bca790f9b2264000007	57ae846d790f9b2516000001	57ae8ef0790f9b397c000003	57aea21a790f9b457d000001	57aea8fe790f9b5603000001	57ff023c790f9b7a1000000e}\r\n    # pat_ids = mm_proc.collect{|i| i[:patient_id].to_s}\r\n    # pat_ids = pat_ids - ig_pat\r\n    pat_ids = get_patient_filtered(hos_code)\r\n    pat = {}\r\n    rs_pat = m_pat.find(pat_ids)\r\n    rs_pat.each do |i|\r\n        pat[i.id.to_s] = i\r\n    end\r\n    \r\n    # map colpo_id <-> colpo\r\n    colpo = {}\r\n    ids   = []\r\n    a_col = get_model[doc_name.to_sym].all\r\n    a_col.each do |i|\r\n        ids << i.id\r\n        colpo[i.id.to_s] = i\r\n    end\r\n    \r\n    # procedure\'s module_model\r\n    mm_proc = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{doc_name}\", :module_id=>ids, :patient_id=>pat_ids).all\r\n    # parent ids \r\n    par_ids = mm_proc.collect{|i| i[:parent_id]}\r\n\r\n    # main fields\r\n    mf = get_doc_field doc_name\r\n    @fm = mf\r\n\r\n    # patient fields\r\n    # pf = [:id, :hn, :name, :hospital_name, :age, :gender]\r\n    # pf = [:id, :hospital_name, :age, :gender]\r\n    # display field\r\n    # cc = []\r\n    # if doc_name == \'hip1\'\r\n    #     x = %w{age	gender	operation_date	patient_asa_grade	side	bilateral	anesthetic_types	regional_type	regional_never_block_type	regional_never_block_other	indication_for_surgery	indication_for_surgery_other	chemical	mechanical	peri_operative_injection	procedure	approach	computer_assist	cement	screws	antibiotic	augmentation	augmentation_type	fe_cement	fe_antibiotic	fe_augmentation	fe_augmentation_type	bearing_surface_type	cup_size	head_diameter	intra_operative_type	intra_operative_other	hoos_interval_score}\r\n    # elsif doc_name == \'hip2\'\r\n    #     x = %w{age	gender	operation_date	patient_asa_grade	side	bilateral	anesthetic_types	regional_type	regional_never_block_type	regional_never_block_other	indication_for_surgery	other_indication	chemical	mechanical	periarticular_injection	procedure	approach	computer_assist	cement	screw	antibiotic	augmentation	augmentation_other	femoral_cement	femoral_antibiotic	femoral_stem	femoral_augmentation	bearing_surface	cup_size	head_diameter	intra_operative_type	intra_operative_other	hoos_interval_score}\r\n        \r\n    # end\r\n    # cc = x.collect{|i| i.to_sym}\r\n    # colf = pf + mf.keys + [:follow_up]\r\n    # colf = colf - [:image_pre_op, :image_intra_op, :image_implant_barcode, :operative_note, :recorder_by, :hn, :name]\r\n    # colf = pf + [:patient_asa_grade, :side, :bilateral, :anesthetic_types, :indication_for_surgery, :chemical, :mechanical, :procedure, :approach, :computer_assist]\r\n    \r\n    rs_col = []\r\n    rs_les = []\r\n    \r\n    # patient-follow_up\r\n    pat_foll = {}\r\n    # patient-implant_profile\r\n    pat_imp  = {}\r\n    # all_follow_up\r\n    fol_list = []\r\n    # all_implant_profile\r\n    imp_list = []\r\n    zz = []\r\n    mm_proc.each do |i|\r\n        pat_id = i[:patient_id].to_s\r\n        par_id = i[:parent_id].to_s\r\n        # patient\r\n        pt = pat[i[:patient_id].to_s]\r\n        # colpo\r\n        cp = colpo[i[:module_id].to_s]\r\n        \r\n        if pt.nil?\r\n            next\r\n        end\r\n        \r\n        today = cp[:created_at]\r\n        if !cp[:operation_date].nil?\r\n            today = cp[:operation_date]\r\n        end\r\n        # d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  pt[:birth_date].day) : today\r\n        d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  1) : today\r\n        age = !pt[:birth_date].nil? ? d.year - pt[:birth_date].year - (d > today ? 1 : 0) : 0\r\n        \r\n        \r\n        tmp = {}\r\n        # tmp[:id]  = pt.id.to_s[5..14]\r\n        tmp[:id]  = pt.id.to_s\r\n        tmp[:hn]  = pt[:hn]\r\n        tmp[:proc]= doc_name\r\n        tmp[:name]= \"\\\\#{pt[:first_name]} \\\\#{pt[:last_name]}\"\r\n        tmp[:age] = age\r\n        tmp[:hospital_name] = hosp[pt[:hospital_name].to_s]\r\n        tmp[:gender] = pt[:gender]\r\n        # zz << pt[:hospital_name]\r\n        mf.keys.each do |j|\r\n            x = mf[j]\r\n            # x = {}\r\n            v = cp[j]\r\n            if x.to_h.has_key? :pair and !v.nil?\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                \r\n                tmp[j] = a.join(\',\')\r\n            elsif x[:column_name].include? \'implant_profile\' \r\n                tmp[j] = v\r\n                \r\n                if v.size != 0\r\n                    imp_list += v\r\n                    if !pat_imp.has_key? pat_id\r\n                        pat_imp[pat_id] = {}\r\n                    end\r\n                    pat_imp[pat_id][j] = v\r\n                end\r\n                \r\n            elsif x[:column_name] == \'image\'\r\n                tmp[j] = v.size\r\n            elsif x[:column_name].to_s.include? \'provider_\' or x[:column_name] == \'recorder_by\'\r\n                name = prov[v.to_s]\r\n                if name\r\n                    # tmp[j] = name\r\n                    tmp[j] = v.to_s[0..9]\r\n                else\r\n                    tmp[j] = v\r\n                end\r\n            elsif x[:column_name].include? \'component_\' or x[:column_name].include? \'company\'\r\n                if x[:column_name].include? \'company\'\r\n                    tmp[j] = comp[v.to_s]\r\n                else\r\n                    tmp[j] = kcom[v.to_s]\r\n                end\r\n            else\r\n                tmp[j] = v\r\n            end\r\n        end\r\n        \r\n        # tmp[:follow_up] = gr_foll[par_id].nil? ? 0 : gr_foll[par_id].size\r\n        \r\n        # if tmp[:follow_up] != 0\r\n        #     pat_foll[pat_id] = gr_foll[par_id]\r\n        #     fol_list += gr_foll[par_id].collect{|i| i[:module_id]}\r\n        # end\r\n        \r\n        rs_col << tmp\r\n    end\r\n    \r\n    res = {}\r\n    # res[:af]   = af\r\n    res[:res]  = rs_col.size\r\n    # res[:mm_foll] = mm_foll.size\r\n    # res[:imp_size] = imp_list.size\r\n    # res[:fol_size] = fol_list.uniq.size\r\n    # res[:pat_foll] = pat_foll\r\n    # res[:pat_imp]  = pat_imp\r\n    res[:time] = Time.now - tb\r\n    \r\n    if false\r\n%>\r\n<!-- Main Procedure -->\r\n<h3><%= doc_name.humanize %> total <%= rs_col.size %> records</h3>\r\n<%= colf.join(\'|\') %><br/>\r\n<%\r\n    end\r\n    \r\n    rs_col.each do |i|\r\n        colf.each do |j|\r\n%>\r\n<%= i[j] %>|\r\n<%\r\n        end\r\n%>\r\n<br/>\r\n<%\r\n    end\r\nend # end doc_list\r\n%>\r\n<hr/>\r\nProcessing Time : <%= Time.now - tb %>\r\n',NULL,NULL,NULL,'2017-06-23 03:58:37','2017-06-23 03:58:37','export_field',''),(3093,'view',1178,2,'<div class=\"well box\">\r\n    <div class=\"row-fluid\">\r\n<div class=\"span6\" style=\"background:#fff\">\r\n<table class=\"table table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th>id</th>\r\n												<th>Name</th>\r\n												<th>Email</th>\r\n											</tr>\r\n										</thead>\r\n										<tbody>\r\n											<tr>\r\n												<td>134</td>\r\n												<td>Summer Throssell</td>\r\n												<td>summert@example.com</td>\r\n											</tr>\r\n											<tr>\r\n												<td>135</td>\r\n												<td>Anthony Pound</td>\r\n												<td>anthonyp@example.com</td>\r\n											</tr>\r\n											<tr>\r\n												<td>136</td>\r\n												<td>Erin Church</td>\r\n												<td>erinc@example.com</td>\r\n											</tr>\r\n											<tr>\r\n												<td>137</td>\r\n												<td>Declan Pamphlett</td>\r\n												<td>declanp@example.com</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n</div>       \r\n<div class=\"span6\">ee</div>  \r\n    </div>\r\n</div>',NULL,NULL,NULL,'2017-06-26 01:43:27','2017-06-26 01:43:27','view',''),(3094,'user_logout',1224,3,'<meta http-equiv=\"refresh\" content=\"0; url=<%=url_for \'/user/logout\' %>\" />',NULL,NULL,NULL,'2017-06-26 04:37:17','2017-06-26 04:37:17','user_logout',''),(3095,'index',1224,3,'<meta http-equiv=\"refresh\" content=\"0; url=<%=url_for \'/forensic/Home/index\' %>\" />',NULL,NULL,NULL,'2017-06-26 04:38:08','2017-06-26 04:38:08','index',''),(3096,'export_data',1173,3,'<%\r\n	# export_data latest 07/07/2017\r\n%>\r\n<%= render :inline=>this.common_function %>\r\n<% \r\n    tb = Time.now \r\n    \r\n    params[:date] = \'all\'\r\n    doc_name = \'knee1\'\r\n    if params[:proc]\r\n        doc_name = params[:proc]\r\n    end\r\n    hos_code = nil\r\n    if params[:hosp]\r\n        hos_code = params[:hosp]\r\n    end\r\n    \r\n    # selected field\r\n    sf = [\'gender\']\r\n    if params[:sf]\r\n        sf = params[:sf].split(\',\')\r\n    end\r\n    # count N/A ?\r\n    na = false\r\n    if params[:na]\r\n        na = params[:na]\r\n    end\r\n    # distribution start\r\n    ds = 10\r\n    if params[:ds]\r\n        ds = params[:ds].to_i\r\n    end\r\n    # distribution end\r\n    de = 100\r\n    if params[:de]\r\n        de = params[:de].to_i\r\n    end\r\n    # step \r\n    sp = 1\r\n    if params[:sp]\r\n        sp = params[:sp].to_i\r\n    end\r\n    # data type (distribution, normal, ratio)\r\n    # dt = \'distribution\'\r\n    dt = \'normal\'\r\n    if params[:dt]\r\n        dt = params[:dt]\r\n    end\r\n    # count field number\r\n    cn = \'Yes\'\r\n    if params[:cn]\r\n        cn = params[:cn]\r\n    end\r\n    # sort by (key|value)\r\n    st = nil\r\n    if params[:st]\r\n        st = params[:st]\r\n    end\r\n    # bin of distribution\r\n    bn = 10\r\n    lw = nil # lower\r\n    lu = nil # upper \r\n    if params[:bn]\r\n        bn = params[:bn].to_i\r\n    end\r\n    if params[:lw]\r\n        lw = params[:lw].to_i\r\n    end\r\n    if params[:lu]\r\n        lu = params[:lu].to_i\r\n    end\r\n    # display (json, csv)\r\n    dp = \'json\'\r\n    if params[:dp]\r\n        dp = params[:dp]\r\n    end\r\n    \r\n    ck = false\r\n    if params[:ck]\r\n        ck = true\r\n    end\r\n    \r\n    \r\n    fol_doc = \'follow_up_knee\'\r\n    if doc_name.include? \'hip\'\r\n        fol_doc = \'follow_up_hip\'\r\n    end\r\n    \r\n    def get_doc_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].strip\r\n                    tmp[:list] << x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    # @fm = fm\r\n    def get_value f, val\r\n        x = @fm[f.to_sym]\r\n        v = val\r\n        if x.to_h.has_key? :pair and !v.nil? and v != \'\'\r\n            # if f.to_sym == :if_rrt or f.to_sym == :vasopressor\r\n            #     v = x[:pair][v]\r\n            # else\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n                # v = \"<span title=\'\\\\#{v}\'>\\\\#{val} <i class=\'splashy-help\'></i></span>\".html_safe\r\n            # end\r\n        end\r\n            # if f.to_sym == :delivered_lose and !v.nil? and v != \'\'\r\n            #         v = v.to_f.round(4) if Float(v) rescue v\r\n            # end\r\n        # if v.nil? or v == \'\'\r\n        #     v = \'-\'\r\n        # end\r\n        return v\r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	m_pat = @ehr_model[:patient]\r\n	m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	# map prov_id <-> provider_name\r\n	prov = {}\r\n	a_prov = get_model[:provider].all\r\n	a_prov.each do |i|\r\n	    prov[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map company_id <-> company_name\r\n	comp = {}\r\n	a_comp = get_model[:company].all\r\n	a_comp.each do |i|\r\n	    comp[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map hospital_id <-> hospital_name\r\n	hosp = {}\r\n	a_hosp = get_model[:hospital].all\r\n	a_hosp.each do |i|\r\n	    hosp[i.id.to_s] = i[:hospital_name_thai]\r\n	end\r\n	\r\n	# map knee_component <--> component_name\r\n	kcom = {}\r\n	a_temp = get_model[:knee_component].all\r\n	a_temp.each do |i|\r\n	    kcom[i.id.to_s] = i[:name]\r\n	end\r\n	# map hip component <-> component_name\r\n# 	hcom = {}\r\n# 	a_temp = get_model[:hip_component].all\r\n# 	a_temp.each do |i|\r\n# 	    hcom[i.id.to_s] = i[:name]\r\n# 	end\r\n    \r\n    # map colpo_id <-> colpo\r\n    colpo = {}\r\n    ids   = []\r\n    a_col = get_model[doc_name.to_sym].all\r\n    a_col.each do |i|\r\n        ids << i.id\r\n        colpo[i.id.to_s] = i\r\n    end\r\n    \r\n    # procedure\'s module_model\r\n    mm_proc = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{doc_name}\", :module_id=>ids).all\r\n    # parent ids \r\n    par_ids = mm_proc.collect{|i| i[:parent_id]}\r\n    # follow up\r\n    # mm_foll = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{fol_doc}\", :parent_id=>par_ids).all\r\n    # gr_foll = mm_foll.group_by{|i| i[:parent_id].to_s}\r\n    \r\n    # map patient_id <-> patient\r\n    pat_ids = get_patient_filtered(hos_code)\r\n    pat = {}\r\n    rs_pat = m_pat.find(pat_ids)\r\n    rs_pat.each do |i|\r\n        pat[i.id.to_s] = i\r\n    end\r\n        \r\n    # main fields\r\n    mf = get_doc_field doc_name\r\n    @fm = mf\r\n    # @fm[:gender] = {:name=>\'Gender\', :label=>\'Gender\', :column_name=>\'gender\', :lov_type=>\'pair\', :lov=>\'1|Male 2|Female\', :list=>[\'Male\', \'Female\'], :pair=>{\'1\'=>\'Male\', \'2\'=>\'Female\'}}\r\n\r\n    # patient fields\r\n    pf = [:id, :hn, :name, :hospital_name, :age, :gender]\r\n    # display field\r\n    # cc = []\r\n    # if doc_name == \'hip1\'\r\n    #     x = %w{age	gender	operation_date	patient_asa_grade	side	bilateral	anesthetic_types	regional_type	regional_never_block_type	regional_never_block_other	indication_for_surgery	indication_for_surgery_other	chemical	mechanical	peri_operative_injection	procedure	approach	computer_assist	cement	screws	antibiotic	augmentation	augmentation_type	fe_cement	fe_antibiotic	fe_augmentation	fe_augmentation_type	bearing_surface_type	cup_size	head_diameter	intra_operative_type	intra_operative_other	hoos_interval_score}\r\n    # elsif doc_name == \'hip2\'\r\n    #     x = %w{age	gender	operation_date	patient_asa_grade	side	bilateral	anesthetic_types	regional_type	regional_never_block_type	regional_never_block_other	indication_for_surgery	other_indication	chemical	mechanical	periarticular_injection	procedure	approach	computer_assist	cement	screw	antibiotic	augmentation	augmentation_other	femoral_cement	femoral_antibiotic	femoral_stem	femoral_augmentation	bearing_surface	cup_size	head_diameter	intra_operative_type	intra_operative_other	hoos_interval_score}\r\n    # end\r\n    # cc = x.collect{|i| i.to_sym}\r\n    colf = pf + mf.keys + [:follow_up, :my]\r\n    colf = colf - [:image_pre_op, :image_intra_op, :image_implant_barcode, :operative_note, :recorder_by, :hn, :name]\r\n    # colf = pf + cc\r\n    \r\n    rs_col = []\r\n    rs_les = []\r\n    \r\n    # patient-follow_up\r\n    pat_foll = {}\r\n    # patient-implant_profile\r\n    pat_imp  = {}\r\n    # all_follow_up\r\n    fol_list = []\r\n    # all_implant_profile\r\n    imp_list = []\r\n    zz = []\r\n    mm_proc.each do |i|\r\n        pat_id = i[:patient_id].to_s\r\n        par_id = i[:parent_id].to_s\r\n        # patient\r\n        pt = pat[i[:patient_id].to_s]\r\n        # colpo\r\n        cp = colpo[i[:module_id].to_s]\r\n        \r\n        if pt.nil?\r\n            next\r\n        end\r\n        \r\n        today = cp[:created_at]\r\n        if !cp[:operation_date].nil? and cp[:operation_date] != \'\'\r\n            today = cp[:operation_date]\r\n        end\r\n        # d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  pt[:birth_date].day) : today\r\n        d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  1) : today\r\n        age = !pt[:birth_date].nil? ? d.year - pt[:birth_date].year - (d > today ? 1 : 0) : 0\r\n        \r\n        \r\n        tmp = {}\r\n        # tmp[:id]  = pt.id.to_s[5..14]\r\n        tmp[:id] = pt.id.to_s\r\n        tmp[:hn]  = pt[:hn]\r\n        tmp[:name]= \"\\\\#{pt[:first_name]} \\\\#{pt[:last_name]}\"\r\n        tmp[:age] = age\r\n        tmp[:hospital_name] = hosp[pt[:hospital_name].to_s]\r\n        tmp[:gender] = pt[:gender]\r\n        # zz << pt[:hospital_name]\r\n        mf.keys.each do |j|\r\n            x = mf[j]\r\n            # x = {}\r\n            v = cp[j]\r\n            if x.to_h.has_key? :pair and !v.nil?\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                \r\n                tmp[j] = a.join(\',\')\r\n            elsif x[:column_name].include? \'implant_profile\' \r\n                tmp[j] = v\r\n                \r\n                if v.size != 0\r\n                    imp_list += v\r\n                    if !pat_imp.has_key? pat_id\r\n                        pat_imp[pat_id] = {}\r\n                    end\r\n                    pat_imp[pat_id][j] = v\r\n                end\r\n                \r\n            elsif x[:column_name] == \'image\'\r\n                tmp[j] = v.size\r\n            elsif x[:column_name].to_s.include? \'provider_\' or x[:column_name] == \'recorder_by\'\r\n                name = prov[v.to_s]\r\n                if name\r\n                    # tmp[j] = name\r\n                    tmp[j] = v.to_s[0..9]\r\n                else\r\n                    tmp[j] = v\r\n                end\r\n            elsif x[:column_name].include? \'component_\' or x[:column_name].include? \'company\'\r\n                if x[:column_name].include? \'company\'\r\n                    tmp[j] = comp[v.to_s]\r\n                else\r\n                    tmp[j] = kcom[v.to_s]\r\n                end\r\n            else\r\n                tmp[j] = v\r\n            end\r\n        end\r\n        \r\n        tmp[:my] = cp[:created_at].strftime(\'%m/%Y\')\r\n        \r\n        # tmp[:follow_up] = gr_foll[par_id].nil? ? 0 : gr_foll[par_id].size\r\n        \r\n        # if tmp[:follow_up] != 0\r\n        #     pat_foll[pat_id] = gr_foll[par_id]\r\n        #     fol_list += gr_foll[par_id].collect{|i| i[:module_id]}\r\n        # end\r\n        \r\n        rs_col << tmp\r\n    end\r\n    \r\n    xx = {}\r\n    dd = {}\r\n    sm = 0\r\n    \r\n    # labels\r\n    lbn = []\r\n    # data_series\r\n    dds = []\r\n    \r\n    # result set\r\n    res = {}\r\n    # check pat ids\r\n    chk = {}\r\n    \r\n    if dt == \'distribution\'\r\n        xx = rs_col.group_by{|i| i[sf[0].to_sym].to_i}\r\n        (ds..de).step(sp) do |i|\r\n            v = xx[i].nil? ? 0 : xx[i].count\r\n            dd[i] = v\r\n            sm += v\r\n        end\r\n        # labels\r\n        lbn = dd.keys\r\n        # data_series\r\n        dds = dd.values\r\n    elsif dt == \'bin\'\r\n        xx = rs_col.group_by{|i| i[sf[0].to_sym].to_i}\r\n        \r\n        dn = (lw.to_i - 1) < 0 ? 0 : ((lw.to_i / bn) * bn)\r\n        up = (lu.to_i == 0) ? ((xx.keys.max / bn) * bn) : lu.to_i\r\n        ix = (dn == 0) ? 0 : 0 - ((dn - 1) / bn)\r\n        \r\n        ub = (up / bn) + ix\r\n        xx.each do |k,v|\r\n            n = v.count\r\n            m = ((k / bn) + ix) <= 0 ? 0 : (k / bn) + ix\r\n            if m >= ub\r\n                m = ub\r\n            end\r\n            \r\n            if !dd.has_key? m\r\n                dd[m] = 0\r\n            end\r\n            dd[m] += n\r\n        end\r\n        # (dn..up).\r\n        \r\n        mn = dd.keys.min\r\n        mx = dd.keys.max\r\n        mn = 0 unless mn\r\n          mx = 0 unless mx\r\n        (mn).upto(mx) do |i|\r\n            \r\n            aa = ((i - 1) * bn) + dn + 1\r\n            bb = (i * bn) + dn\r\n            \r\n            if i == 0 and (lw != 0)\r\n                if aa < 0\r\n                    aa = 0\r\n                end\r\n                lbn << \"< \\\\#{bb}\"\r\n            elsif i == mx and (lu != 0)\r\n                lbn << \"> \\\\#{aa}\"\r\n            else\r\n                lbn << \"\\\\#{aa} - \\\\#{bb}\"\r\n            end\r\n            \r\n            dds << dd[i]\r\n        end\r\n        # lbn = [dn,up,ix]\r\n        \r\n        sm = dd.values.sum\r\n    elsif dt == \'bin-matrix\'\r\n        xx = rs_col.group_by{|i| i[sf[0].to_sym].to_i}\r\n        # compared field\r\n        cf = sf[1].to_sym\r\n        \r\n        dn = (lw.to_i - 1) < 0 ? 0 : ((lw.to_i / bn) * bn)\r\n        up = (lu.to_i == 0) ? ((xx.keys.max / bn) * bn) : lu.to_i\r\n        ix = (dn == 0) ? 0 : 0 - ((dn - 1) / bn)\r\n        \r\n        ub = (up / bn) + ix\r\n        tm = rs_col.group_by{|i| i[cf]}\r\n        pos_key = tm.keys.sort.reverse\r\n        res[:row] = pos_key\r\n        # res[:xxx] = tm\r\n        xx.each do |k,v|\r\n            m = ((k / bn) + ix) <= 0 ? 0 : (k / bn) + ix\r\n            if m > ub\r\n                m = ub\r\n            end\r\n            sm += v.count\r\n            g = v.group_by{|i| i[cf]}\r\n            \r\n            if !dd.has_key? m\r\n                dd[m] = {}\r\n                pos_key.each do |i|\r\n                    dd[m][i] = 0\r\n                end\r\n            end\r\n            \r\n            pos_key.each do |i|\r\n                n = g[i].nil? ? 0 : g[i].count\r\n                dd[m][i] += n\r\n            end\r\n        end\r\n        # (dn..up).\r\n        mn = dd.keys.min\r\n        mx = dd.keys.max\r\n        (mn).upto(mx) do |i|\r\n            aa = ((i - 1) * bn) + dn + 1\r\n            bb = (i * bn) + dn\r\n            \r\n            if i == 0 and (lw != 0)\r\n                if aa < 0\r\n                    aa = 0\r\n                end\r\n                lbn << \"< \\\\#{bb}\"\r\n            elsif i == mx and (lu != 0)\r\n                lbn << \"> \\\\#{aa}\"\r\n            else\r\n                lbn << \"\\\\#{aa} - \\\\#{bb}\"\r\n            end\r\n            \r\n            # dds << dd[i]\r\n        end\r\n        # lbn = [dn,up,ix]\r\n        \r\n        # sm = dd.values.sum\r\n        vv = {}\r\n        pos_key.each do |i|\r\n            vv[i] = []\r\n            dd.keys.sort.each do |j|\r\n                vv[i] << dd[j][i]\r\n            end\r\n        end\r\n        dds = vv\r\n    elsif dt == \'data-matrix\'\r\n        xx = rs_col.group_by{|i| i[sf[0].to_sym]}\r\n        # compared field\r\n        cf = sf[1].to_sym\r\n        yy = rs_col.group_by{|i| i[cf]}\r\n        row = yy.keys.sort\r\n        lbn = xx.keys.sort\r\n        \r\n        tmp = rs_col.group_by{|i| [i[sf[0].to_sym], i[cf]]}\r\n        dds = {}\r\n        rw  = []\r\n        lbn.each do |m|\r\n            # q = [m.to_s]\r\n            dd[m] = {}\r\n            row.each do |n|\r\n                q = [m, n]\r\n                v = 0\r\n                if !tmp[q].nil?\r\n                    x = tmp[q]\r\n                    \r\n                    if params[:cn].nil?\r\n                        v = x.count\r\n                    else\r\n                        w = x.group_by{|i| i[cn.to_sym]}\r\n                        w.each do |k,val|\r\n                            if k.nil? or k == \'\'\r\n                                k = \'N/A\'\r\n                            end\r\n                            if n.nil? or n == \'\'\r\n                                n = \'N/A\'\r\n                            end\r\n                            kk = \"\\\\#{n} - \\\\#{k}\"\r\n                            rw << kk\r\n                            v = val.count\r\n                            dd[m][kk] = v\r\n                            sm += v\r\n                        end\r\n                    end\r\n                end\r\n                if params[:cn].nil?\r\n                    dd[m][n] = v\r\n                    sm += v\r\n                end\r\n            end\r\n        end\r\n        vv = {}\r\n        if !params[:cn].nil?\r\n            row = rw.sort.uniq\r\n        end\r\n        row.each do |i|\r\n            vv[i] = []\r\n            dd.keys.sort.each do |j|\r\n                vv[i] << dd[j][i].to_i\r\n            end\r\n        end\r\n        dds = vv\r\n        \r\n        # if params[:cn].nil?\r\n        #     res[:row] = row\r\n        # else\r\n        #     res[:row] = rw\r\n        # end\r\n        res[:row] = row\r\n    elsif dt == \'versus-filter\'\r\n        ss = sf.collect{|i| i.to_sym}\r\n        \r\n        xx = rs_col.group_by{|i| i[ss[0]]}\r\n        yy = rs_col.group_by{|i| i[ss[1]]}\r\n        \r\n        kx = xx.keys.sort\r\n        ky = yy.keys.sort\r\n        \r\n        lbn = kx\r\n        res[:row] = ky\r\n        \r\n        tmp = rs_col.group_by{|i| [i[ss[0]], i[ss[1]]]}\r\n        # N/A set\r\n        ns = [nil, \'\', cn]\r\n        nq = [[nil,nil], [nil,\'\'], [nil,cn], [\'\',nil], [\'\',cn], [\'\',\'\'], [cn,cn], [cn,nil], [cn,\'\']]\r\n        \r\n        txt = [ss[0], ss[1], ss.join(\' + \'), ss.join(\' ~ \')]\r\n        ttt = [0,0,0,0]\r\n        xxx = [[],[],[],[]]\r\n        qq  = []\r\n        kx.each do |x|\r\n            dd[x] = {}\r\n            ky.each do |y|\r\n                q = [x, y]\r\n                n = 0\r\n                v = tmp[q]\r\n                if !v.nil?\r\n                    n = v.count\r\n                end\r\n                qq << q\r\n                dd[x][y] = n\r\n                sm += n\r\n                \r\n                if x.nil? \r\n                    x = cn\r\n                end\r\n                if y.nil?\r\n                    y = cn\r\n                end\r\n                \r\n                if nq.include? q\r\n                    ttt[3] += n\r\n                    if n != 0\r\n                        xxx[3] << q << n\r\n                    end\r\n                elsif ns.include? y\r\n                    ttt[0] += n\r\n                    if n != 0\r\n                        xxx[0] << q << n\r\n                    end\r\n                elsif ns.include? x\r\n                    ttt[1] += n\r\n                    if n != 0\r\n                        xxx[1] << q << n\r\n                    end\r\n                else\r\n                    ttt[2] += n\r\n                    if n != 0\r\n                        xxx[2] << q << n\r\n                    end\r\n                end\r\n                \r\n                # if (x != cn) and (y == cn)\r\n                #     ttt[0] += n\r\n                #     # xxx[0] << [x,y]\r\n                # elsif (x == cn) and (y != cn)\r\n                #     ttt[1] += n\r\n                #     # xxx[1] << [x,y]\r\n                # elsif (x != cn) and (y != cn)\r\n                #     ttt[2] += n\r\n                #     # xxx[2] << [x,y]\r\n                # elsif (x == cn) and (y == cn)\r\n                #     ttt[3] += n\r\n                #     # xxx[3] << [x,y]\r\n                # end\r\n            end\r\n        end\r\n        res[:vs] = {}\r\n        res[:vs][:lbn] = txt\r\n        res[:vs][:dat] = ttt\r\n        vv = {}\r\n        ky.each do |i|\r\n            vv[i] = []\r\n            dd.keys.sort.each do |j|\r\n                vv[i] << dd[j][i]\r\n            end\r\n        end\r\n        dds = vv\r\n        res[:xxx] = xxx\r\n        # res[:qq] = qq.uniq\r\n    elsif dt == \'versus\'\r\n        ss = sf.collect{|i| i.to_sym}\r\n        ss.each do |i|\r\n            s = 0\r\n            dd[i] = {}\r\n            tmp = rs_col.group_by{|j| j[i]}\r\n            tmp.each do |k,v|\r\n                if na\r\n                    if k.nil? or k == \'\'\r\n                        next\r\n                    end\r\n                end\r\n                \r\n                dd[i][k] = v.count\r\n                s += v.count\r\n            end\r\n            # dd[i][:s] = s\r\n        end\r\n        \r\n        tmp = [[],[],[],[]]\r\n        rs_col.each do |i|\r\n            \r\n            if i[ss[0]] != \'\' and i[ss[1]] == \'\'\r\n                tmp[0] << i\r\n            elsif i[ss[0]] == \'\' and i[ss[1]] != \'\'\r\n                tmp[1] << i\r\n            elsif i[ss[0]] != \'\' and i[ss[1]] != \'\'\r\n                tmp[2] << i\r\n            elsif i[ss[0]] == \'\' and i[ss[1]] == \'\'\r\n                tmp[3] << i\r\n            end\r\n            \r\n        end\r\n        ttt = []\r\n        tmp.each do |i|\r\n            ttt << i.count\r\n        end\r\n        # res[:tmp] = ttt\r\n        # res[:tmp_sum] = ttt.sum\r\n        \r\n        lbn = [ss[0], ss[1], ss.join(\' + \'), ss.join(\' ~ \')]\r\n        dds = ttt\r\n        sm = ttt.sum\r\n    elsif dt == \'multiple\'\r\n        ss = sf.collect{|i| i.to_sym}\r\n        ss.each do |i|\r\n            s = 0\r\n            dd[i] = {}\r\n            tmp = rs_col.group_by{|j| j[i]}\r\n            tmp.each do |k,v|\r\n                if na\r\n                    if k.nil? or k == \'\'\r\n                        next\r\n                    end\r\n                end\r\n                \r\n                dd[i][k] = v.count\r\n                s += v.nil? ? 0 : v.count\r\n            end\r\n            # dd[i][:s] = s\r\n        end\r\n        \r\n        # lbn = dd.keys\r\n        dd.each do |k, v|\r\n            lbn << k\r\n            dds << v[cn]\r\n        end\r\n        # sm = dds.sum\r\n    else\r\n        xx = rs_col.group_by{|i| i[sf[0].to_sym]}\r\n        xx.each do |k,v|\r\n            if na\r\n                if k.nil? or k == \'\'\r\n                    next\r\n                end\r\n            end\r\n            dd[k] = v.count\r\n            sm += v.count\r\n            \r\n            if ck\r\n                chk[k] = v.collect{|i| i[:id]}.join(\',\')\r\n            end\r\n        end\r\n        \r\n        # labels\r\n            lbn = dd.keys\r\n        # data_series\r\n            dds = dd.values\r\n            \r\n            if ck\r\n                res[:pid] = chk.values\r\n            end\r\n    end\r\n    \r\n    if st == \'key\'\r\n        lbn = []\r\n        dds = []\r\n        kk = dd.keys.sort_by{|i| i}\r\n        kk.each do |i|\r\n            lbn << i\r\n            dds << dd[i]\r\n        end\r\n    elsif st == \'value\'\r\n        lbn = []\r\n        dds = []\r\n        kk = dd.sort_by {|k,v| v}\r\n        tk = \'\'\r\n        tv = nil\r\n        kk.each do |k,v|\r\n            if k.nil? or k == \'\'\r\n                tk = k\r\n                tv = v\r\n                next\r\n            end\r\n            lbn << k\r\n            dds << v\r\n        end\r\n        \r\n        if tv\r\n            lbn.insert(0, tk)\r\n            dds.insert(0, tv)\r\n        end\r\n    elsif st == \'rvalue\'\r\n        lbn = []\r\n        dds = []\r\n        kk = dd.sort_by {|k,v| v}.reverse\r\n        tk = \'\'\r\n        tv = nil\r\n        kk.each do |k,v|\r\n            if k.nil? or k == \'\'\r\n                tk = k\r\n                tv = v\r\n                next\r\n            end\r\n            lbn << k\r\n            dds << v\r\n        end\r\n        \r\n        if tv\r\n            lbn.insert(0, tk)\r\n            dds.insert(0, tv)\r\n        end\r\n    end\r\n        \r\n    \r\n    \r\n    \r\n    # res[:af]   = af\r\n    res[:res]  = rs_col.size\r\n    res[:lbn]  = lbn\r\n    res[:dd]   = dds\r\n    res[:rw]   = dd\r\n    # res[:xx]   = xx\r\n    res[:sm]   = sm\r\n    # res[:mm_foll] = mm_foll.size\r\n    # res[:imp_size] = imp_list.size\r\n    # res[:fol_size] = fol_list.uniq.size\r\n    # res[:pat_foll] = pat_foll\r\n    # res[:pat_imp]  = pat_imp\r\n    # res[:colf] = colf\r\n    \r\n    res[:time] = Time.now - tb\r\n    # res[:fm] = @fm\r\n    \r\n    sep = \'|\'\r\n    \r\n    if false \r\n%>\r\n<!-- Main Procedure -->\r\n<h3><%= doc_name.humanize %> total <%= rs_col.size %> records</h3>\r\n<%= colf.join(\'|\') %><br/>\r\n<%\r\n    \r\n    rs_col.each do |i|\r\n        colf.each do |j|\r\n%>\r\n<%= i[j] %>|\r\n<%\r\n        end\r\n    end\r\n    \r\n    end # false \r\n%>\r\n<%\r\n    if dp == \'plain\'\r\n        response.headers[\"Content-Type\"] = \"text/plain; charset=utf-8\"\r\n        lbn = lbn.map{|i| (i.nil? or i == \'\') ? \'N/A\' : i}\r\n%>\r\n<%= sf[0] %><%=sep%><%= lbn.join(sep) %>\r\n<%\r\n        if dt == \'bin-matrix\' or dt == \'data-matrix\' or dt == \'versus-filter\'\r\n            dd = res[:dd]\r\n            dd.each do |k,v|\r\n%>\r\n<%= (k.nil? or k == \'\') ? \'N/A\' : k %><%=sep%><%= v.join(sep) %>\r\n<%\r\n            end\r\n            tt = []\r\n            rw = res[:rw]\r\n            lbn = res[:lbn]\r\n            lbn.each do |i|\r\n                m = rw[i]\r\n                v = m.nil? ? [0] : m.values\r\n                tt << v.sum\r\n            end\r\n%>\r\nTotal<%=sep%><%= tt.join(sep) %>\r\n<%\r\n            if dt == \'versus-filter\'\r\n%>\r\n\r\nlabel<%=sep%><%= res[:vs][:lbn].join(sep) %>\r\ndata<%=sep%><%= res[:vs][:dat].join(sep) %>\r\n<%\r\n            end\r\n\r\n        else \r\n%>\r\ncount<%=sep%><%= dds.join(sep) %>\r\n<%\r\n            if ck\r\n%>\r\nids<%=sep%><%= res[:pid].join(sep) %>\r\n<%          end %>\r\n<%      end %>\r\nsum<%=sep%><%= sm %>\r\ntotal<%=sep%><%= rs_col.count %>\r\n\r\n<% \r\n        if dt == \'versus\' or dt == \'multiple\'\r\n            rw = res[:rw]\r\n            rw.each do |k,v|\r\n%>\r\n<%= k %><%=sep%><%= v.keys.join(sep) %>\r\ncount<%=sep%><%= v.values.join(sep) %>\r\nsum<%=sep%><%= v.values.sum %>\r\n\r\n<%      \r\n            end\r\n\r\n        end \r\n%>\r\n<%  else %>\r\n<%= res.to_json.html_safe %>\r\n<%  end %>\r\n',NULL,NULL,NULL,'2017-06-26 06:14:24','2017-06-26 06:14:24','export_data',''),(3097,'link_all',1173,3,'<%\r\n    hs = {\r\n         \"All\"=>\"&\"\r\n        # \"PGH\"=>\"hosp=PGH&\"\r\n        #\"KKU\"=>\"hosp=KKU&\"#,\r\n        # \"LERDSIN\"=>\"hosp=LERDSIN&\",\r\n        # \"PHRAE\"=>\"hosp=PHRAE&\",\r\n        # \"PMK\"=>\"hosp=PMK&\"\r\n    }\r\n    \r\n    \r\n    \r\n%>\r\n<h1>Primary HIP</h1>\r\n<%\r\n    hs.each do |k,v|\r\n        ln = \"export_data?proc=hip1&\\\\#{v}\"\r\n%>\r\n<h3>Hip1 - <%= k %></h3>\r\n<ol>\r\n    <li><%= link_to \'Age\', \"\\\\#{ln}sf=age&bn=10&lw=40&lu=90&dp=plain&dt=bin\", :target=>\'_blank\' %></li>\r\n    <ul>\r\n        <li><%= link_to \'Age-Gender\', \"\\\\#{ln}sf=age,gender&bn=10&lw=40&lu=90&dp=plain&dt=bin-matrix\", :target=>\'_blank\' %></li>\r\n        <li><%= link_to \'Gender\', \"\\\\#{ln}sf=gender&dp=plain\", :target=>\'_blank\' %></li>\r\n    </ul>\r\n    <li><%= link_to \'Side\', \"\\\\#{ln}sf=side&dp=plain\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Bilateral\', \"\\\\#{ln}sf=bilateral&dp=plain\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Diagnosis\', \"\\\\#{ln}sf=indication_for_surgery&dp=plain&st=value\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Thromboprophylaxis\', \"\\\\#{ln}sf=chemical,mechanical&dp=plain&dt=versus-filter&cn=None\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Thromboprophylaxis Chemical\', \"\\\\