li><%= link_to \'Tibial Augmentation Type\', \"\\\\#{ln}sf=tibial_augmentation&dp=plain&st=value\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Patellar Component\', \"\\\\#{ln}sf=patellar_component,patellar_component_reason&dt=data-matrix&dp=plain\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'KOOS Interval Score\', \"\\\\#{ln}sf=koos_interval_score&dp=plain\", :target=>\'_blank\' %></li>\r\n    <hr/>\r\n    <li><%= link_to \'Hospital\', \"\\\\#{ln}sf=hospital_name&dp=plain\", :target=>\'_blank\' %></li>\r\n</ol>\r\n<% end %>\r\n<hr/>\r\n<h1>Revision KNEE</h1>\r\n<%\r\n    hs.each do |k,v|\r\n        ln = \"export_data?proc=knee2&\\\\#{v}\"\r\n%>\r\n<h3>Knee2 - <%= k %></h3>\r\n<ol>\r\n    <li><%= link_to \'Age\', \"\\\\#{ln}sf=age&bn=10&lw=40&lu=90&dp=plain&dt=bin\", :target=>\'_blank\' %></li>\r\n    <ul>\r\n        <li><%= link_to \'Age-Gender\', \"\\\\#{ln}sf=age,gender&bn=10&lw=40&lu=90&dp=plain&dt=bin-matrix\", :target=>\'_blank\' %></li>\r\n        <li><%= link_to \'Gender\', \"\\\\#{ln}sf=gender&dp=plain\", :target=>\'_blank\' %></li>\r\n    </ul>\r\n    <li><%= link_to \'Gender\', \"\\\\#{ln}sf=gender&dp=plain\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Side\', \"\\\\#{ln}sf=side&dp=plain\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Bilateral\', \"\\\\#{ln}sf=bilateral&dp=plain\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Diagnosis\', \"\\\\#{ln}sf=indication_for_surgery&dp=plain&st=value\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Coronal alignment\', \"\\\\#{ln}sf=coronal_alignment_varus_valgus&dp=plain\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Thromboprophylaxis\', \"\\\\#{ln}sf=chemical,mechanical&dp=plain&dt=versus-filter&cn=None\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Thromboprophylaxis - Chemical\', \"\\\\#{ln}sf=chemical&dp=plain&st=value\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Thromboprophylaxis - Mechanical\', \"\\\\#{ln}sf=mechanical&dp=plain&st=value\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Injection\', \"\\\\#{ln}sf=periarticular_injection&dp=plain&st=key\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Procedure\', \"\\\\#{ln}sf=procedure&dp=plain&st=value\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Approach\', \"\\\\#{ln}sf=approach&dp=plain&st=value\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Computer assist\', \"\\\\#{ln}sf=computer_assist&dp=plain&st=key\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Femoral Cement\', \"\\\\#{ln}sf=femoral_cement&dp=plain&st=key\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Femoral Stem\', \"\\\\#{ln}sf=femoral_stem&dp=plain&st=key\", :target=>\'_blank\' %></li>\r\n    <!--<li><%= link_to \'Femoral Component\', \"\\\\#{ln}sf=femoral_cement,femoral_stem,antibiotic&cn=Yes&dp=plain&dt=multiple\", :target=>\'_blank\' %></li>-->\r\n    <li><%= link_to \'Femoral Augmentation Type\', \"\\\\#{ln}sf=femoral_augmentation&dp=plain&st=value\", :target=>\'_blank\' %></li>\r\n    <!--<li><%= link_to \'Tibial Component\', \"\\\\#{ln}sf=tibial_cement,tibial_stem,tibial_antibiotic&cn=Yes&dp=plain&dt=multiple\", :target=>\'_blank\' %></li>-->\r\n    <li><%= link_to \'Tibial Cement\', \"\\\\#{ln}sf=tibial_cement&dp=plain&st=key\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Tibial Stem\', \"\\\\#{ln}sf=tibial_stem&dp=plain&st=key\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Tibial Augmentation Type\', \"\\\\#{ln}sf=tibial_augmentation&dp=plain&st=value\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'Patellar Component\', \"\\\\#{ln}sf=patellar_component,patellar_component_reason&dt=multiple&dp=plain\", :target=>\'_blank\' %></li>\r\n    <li><%= link_to \'KOOS Interval Score\', \"\\\\#{ln}sf=koos_interval_score&dp=plain\", :target=>\'_blank\' %></li>\r\n    <hr/>\r\n    <li><%= link_to \'Hospital\', \"\\\\#{ln}sf=hospital_name&dp=plain\", :target=>\'_blank\' %></li>\r\n</ol>\r\n<% end %>',NULL,NULL,NULL,'2017-06-26 14:29:43','2017-06-26 14:29:43','link_all',''),(3098,'active_provider',1173,3,'<%= render :inline=>this.common_function %>\r\n<%\r\n    pat_ids = get_patient_filtered\r\n    pro = @m_pat_mod.where(:patient_id=>pat_ids, :module_name=>\"\\#{@current_project.name}#provider\").all\r\n    pro_ids = pro.collect{|i| i[:module_id]}\r\n    prov = get_model[:provider].find(pro_ids)\r\n    hos_ids = prov.collect{|i| i[:main_hospital]}\r\n    res = {}\r\n    res[:pro_count] = pro_ids.uniq.count\r\n    res[:hos_count] = hos_ids.uniq.count\r\n    res[:pro_all] = prov\r\n    \r\n%>\r\n<%= res.to_json.html_safe %>',NULL,NULL,NULL,'2017-06-28 14:12:40','2017-06-28 14:12:40','active_provider',''),(3099,'export_ra',909,3,'<% tb = Time.now %>\r\n<%= render :inline=>this.initx %>\r\n<%\r\n    is_oneline = false\r\n    if params[:cs] == \'one\'\r\n        is_oneline = true\r\n    end\r\n    \r\n    ar = []\r\n    rs = {}\r\n    res = {}\r\n    pat_mod = {}\r\n\r\n    mod_app = get_patient_module_by_module_name(\"\\\\#{@current_project.name}#appointment\")\r\n\r\n    a_ids = []\r\n    par_ids = [] # all parent_id\r\n    pat_ids = [] # all patient_id\r\n    app_par = {}\r\n    pat_par = {}\r\n    mod_app.collect do |i| \r\n        a_ids << i[:module_id]\r\n        par_ids << i.id.to_s\r\n        pat_ids << i[:patient_id]\r\n        app_par[i.id.to_s] = i[:module_id]\r\n        pat_par[i[:patient_id]] = i.id.to_s\r\n    end\r\n    \r\n    a_app = get_all_appointment_by_ids(a_ids)\r\n    a_pat = get_all_patient_by_ids(pat_ids)\r\n    # begin\r\n    # a_pat = a_pat.sort_by{|i| i[:patient_order] if i[:patient_order]}\r\n    a_pat = a_pat.sort{|a,b| a[:patient_order] && b[:patient_order] ? a[:patient_order] <=> b[:patient_order] : a[:patient_order] ? -1 : 1 }\r\n    \r\n    # query patient_module <-> aki\r\n    mod_aki = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#aki\")\r\n    i_aki = []\r\n    p_aki = {}\r\n    mod_aki.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_aki << mid\r\n        if !p_aki.has_key? pid\r\n            p_aki[pid] = []\r\n        end\r\n        p_aki[pid] << mid\r\n    end\r\n    m_aki = {}\r\n    a_aki = get_model[:aki].find(i_aki)\r\n    a_aki.each do |i|\r\n        m_aki[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> summary_form\r\n    mod_out = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#summary_form\")\r\n    i_out = []\r\n    p_out = {}\r\n    mod_out.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_out << mid\r\n        if !p_out.has_key? pid\r\n            p_out[pid] = []\r\n        end\r\n        p_out[pid] << mid\r\n    end\r\n    m_out = {}\r\n    a_out = get_model[:summary_form].find(i_out)\r\n    a_out.each do |i|\r\n        m_out[i.id] = i\r\n    end\r\n    \r\n    # query patient_module <-> case_record\r\n    mod_case = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\\\#{@current_project.name}#case_record\")\r\n    i_case = []\r\n    p_case = {}\r\n    mod_case.each do |i|\r\n        mid = i[:module_id]\r\n        pid = i[:patient_id]\r\n        \r\n        i_case << mid\r\n        if !p_case.has_key? pid\r\n            p_case[pid] = []\r\n        end\r\n        p_case[pid] << mid\r\n    end\r\n    m_case = {}\r\n    a_case = get_model[:case_record].find(i_case)\r\n    a_case.each do |i|\r\n        m_case[i.id] = i\r\n    end\r\n    \r\n    \r\n    # processing\r\n    res = []\r\n    # pf = %w{patient_number	patient_order	recheck	reference	birth_date	gender	weight	height	ideal_body_weight	date_of_admission	date_of_icu_admission	time_of_icu_admission	reimbursement	diagnosis	ht	dm	cad	cerebrovascular_disease	malignancy	ckd	esrd	baseline_serum_creainine_by_mdrd	available_baseline	baseline_serum_cr	date_of_baseline_serum_cr	first_available_cr	first_available_cr_date	icu	glasgow_coma_score	temperature	mean_arterial	heart_rate	respiratory_rate	oxygenation	arterial_ph	serum_sodium	serum_potassium	serum_creatinine	hematocrit	white_blood_count	age	chronic_health_points	apache_ii}\r\n    pf = %w{patient_number	patient_order gender apache_ii  diagnosis dm date_of_icu_admission reference	baseline_serum_creainine_by_mdrd	baseline_serum_cr	first_available_cr	}\r\n\r\n    dd = %w{1 2 3 4 5 6 7 14 21 28}\r\n    # cf = %w{case_status bun  creatinine mechanical_ventilation vasopressor vasopressor_type dose_of_vasopressor rs coagulation cns liver renal cvs diuretic lactate sofa if_rrt}\r\n    cf = %w{record_day case_status move_out_time bun creatinine urine_output24hr  urine_output_cal mechanical_ventilation vasopressor }\r\n\r\n    # of = %w{stop_rrt_date rrt_day  icu_discharge_status date_of_icu_discharge los_in_icu  hospital_discharge_status date_of_hospital_discharge los_in_hospital  death_date total_ventilator_day  crbsi vap}\r\n    of = %w{date_of_icu_discharge	date_of_hospital_discharge	icu_discharge_status	hospital_discharge_status   stop_rrt_date rrt_day  icu_discharge_status los_in_icu  hospital_discharge_status los_in_hospital  death_date total_ventilator_day  crbsi vap}\r\n    af = %w{aki_max_staging aki_max_staging_from auto_max_staging cr_diagnosis cr_diagnosis_from_day cr_staging cr_staging_from_day urine_output_diagnosis urine_output_from_day urine_output_staging urine_output_staging_from_day cause_of_aki cause_other admin_cause_of_aki cause_other2 aki_type a_on_c}\r\n\r\n    dx_group = {}\r\n    ref = {\'1\'=>\'baseline_serum_cr\', \'2\'=>\'baseline_serum_creainine_by_mdrd\', \'3\'=>\'first_available_cr\'}\r\n    dis_status = {\'0\'=>\'Alive\', \'1\'=>\'Death\', \'2\'=>\'HAMA\'}\r\n    # for each patient\r\n    a_pat.each do |pat|\r\n        tmp = {}\r\n        msg = []\r\n        # filter age < 18\r\n        if pat.nil? or pat[:age].to_i < 18\r\n            next\r\n        end\r\n        \r\n        pp = {}\r\n        pp[:site] = @current_solution.name\r\n        pf.each do |i|\r\n            pp[i.to_sym] = pat[i.to_sym]\r\n        end\r\n        \r\n        dx_str = pp[:diagnosis].clone.downcase\r\n        if dx_str.include? \' and \'\r\n            dx_str.gsub!(\' and \', \',\')\r\n        end\r\n        dx_str.split(\',\').collect do |i|\r\n            k = i.strip\r\n            v = pp[:patient_number]\r\n            if !dx_group.has_key? k\r\n                dx_group[k] = []\r\n            end\r\n            dx_group[k] << v\r\n        end\r\n        \r\n        pp[:reference] = ref[pp[:reference]]\r\n        \r\n        \r\n        pp[:time_of_icu_admission] = pp[:time_of_icu_admission].nil? ? \'\' : pp[:time_of_icu_admission].strftime(\'%H:%M\')\r\n        \r\n        # recheck urine output from case_record\r\n        cid_list = []\r\n        if xx = p_case[pat.id]\r\n            xx.each do |i|\r\n                cid_list << m_case[i]\r\n            end\r\n        else\r\n            msg << \"xx found\"\r\n        end\r\n        \r\n        # mapping day <--> case_record\r\n        mc = {}\r\n        cid_list.each do |i|\r\n            rd = i[:record_day]\r\n            if rd==\'\'\r\n                msg << \'empty rd\'\r\n            end\r\n            if !mc.has_key? rd\r\n                mc[rd] = i\r\n            else\r\n                msg << \"dup rd[\\\\#{rd}]\"\r\n            end\r\n        end\r\n    if false\r\n        # checking aki is created ?\r\n        is_aki = false\r\n        aid_list = []\r\n        if xx = p_aki[pat.id]\r\n            xx.each do |i|\r\n                aid_list << m_aki[i]\r\n            end\r\n            is_aki = true\r\n        else\r\n            msg << \"NO AKI\"\r\n        end\r\n        \r\n        # assign aki\r\n        pp[:aki_auto_max_staging] = \'0\'\r\n        pp[:aki_auto_max_from] = \'-\'\r\n        r_aki = nil\r\n        if is_aki\r\n            r_aki = aid_list[0]\r\n            \r\n            # sum = 0\r\n            af.each do |i|\r\n                pp[i.to_sym] = r_aki[i.to_sym].nil? ? \'\' : r_aki[i.to_sym]\r\n                # sum += r_aki[i.to_sym].nil? ? 0 : r_aki[i.to_sym].to_i\r\n                # pp[i.to_sym] = r_aki\r\n            end\r\n            # if sum > 0\r\n            if pp[:auto_max_staging].to_i > 0\r\n                pp[:aki] = \'Yes\'\r\n                if pp[:cr_staging].to_i > pp[:urine_output_staging].to_i\r\n                    pp[:aki_auto_max_staging] = pp[:cr_staging]\r\n                    pp[:aki_auto_max_from] = \'Cr\'\r\n                elsif pp[:cr_staging].to_i < pp[:urine_output_staging].to_i\r\n                    pp[:aki_auto_max_staging] = pp[:urine_output_staging]\r\n                    pp[:aki_auto_max_from] = \'Urine\'\r\n                else\r\n                    pp[:aki_auto_max_staging] = pp[:urine_output_staging]\r\n                    pp[:aki_auto_max_from] = \'Both\'\r\n                end\r\n            else\r\n                pp[:aki] = \'No\'\r\n            end\r\n            \r\n            \r\n        else\r\n            pp[:aki] = \'None\'\r\n        end\r\n    end # end AKI\r\n        # checking summary_form is created ?\r\n        is_out = false\r\n        oid_list = []\r\n        if xx = p_out[pat.id]\r\n            xx.each do |i|\r\n                oid_list << m_out[i]\r\n            end\r\n            is_out = true\r\n            # pp[:outcome] = \'Yes\'\r\n        else\r\n            msg << \"NO OUTCOME\"\r\n            # pp[:outcome] = \'No\'\r\n        end\r\n        \r\n        # assign summary_form (outcome)\r\n        r_out = nil\r\n        if is_out\r\n            r_out = oid_list[0]\r\n            \r\n            of.each do |i|\r\n                pp[i.to_sym] = r_out[i.to_sym].nil? ? \'\' : r_out[i.to_sym]\r\n                # pp[i.to_sym] = m_out.to_json.html_safe \r\n            end\r\n            pp[:outcome] = \'Yes\'\r\n        else\r\n            pp[:outcome] = \'No\'\r\n        end\r\n        pp[:icu_discharge_status] = dis_status[pp[:icu_discharge_status]]\r\n        pp[:hospital_discharge_status] = dis_status[pp[:hospital_discharge_status]]\r\n        \r\n        # number of record_day\r\n        nrd = cid_list.count\r\n        \r\n        pp[:has_rrt] = \'No\'\r\n        pp[:rrt_start_day] = \'\'\r\n        pp[:rrt_stop_day]  = \'\'\r\n        pp[:num_of_record_day] = nrd\r\n        pp[:has_vasopressor] = \'No\'\r\n        pp[:has_ventilation] = \'No\'\r\n        if !mc.empty?\r\n            dd.each do |i|\r\n                if !mc[i].nil?\r\n                    tmp = {}\r\n                    cf.each do |j|\r\n                        if j.to_s == \'move_out_time\'\r\n                            if mc[i][:case_status].to_i != 0\r\n                                \r\n                                if is_oneline\r\n                                    # pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                    pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym].nil? ? \'xx:xx\' : mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                else\r\n                                    # pp[j.to_sym] = mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                    pp[j.to_sym] = mc[i][j.to_sym].nil? ? \'xx:xx\' : mc[i][j.to_sym].strftime(\'%H:%M\')\r\n                                end\r\n                            end\r\n                        else\r\n                            \r\n                            if is_oneline\r\n                                pp[\"\\\\#{j}_\\\\#{i}\".to_sym] = mc[i][j.to_sym]\r\n                            else\r\n                                pp[j.to_sym] = mc[i][j.to_sym]\r\n                            end\r\n                            \r\n                            if mc[i][j.to_sym] == \'0\' and j.to_s == \'if_rrt\'\r\n                                pp[:has_rrt] = \'Yes\'\r\n                                if pp[:rrt_start_day] == \'\'\r\n                                    pp[:rrt_start_day] = i\r\n                                    pp[:rrt_stop_day] = i\r\n                                else\r\n                                    pp[:rrt_stop_day] = i\r\n                                end\r\n                            end\r\n                            \r\n                            if mc[i][j.to_sym] == \'Yes\' and j.to_s == \'vasopressor\'\r\n                                pp[:has_vasopressor] = \'Yes\'\r\n                            end\r\n                            if mc[i][j.to_sym] == \'Yes\' and j.to_s == \'mechanical_ventilation\'\r\n                                pp[:has_ventilation] = \'Yes\'\r\n                            end\r\n                            \r\n                        end\r\n                    end\r\n                    if !is_oneline\r\n                        tmp = pp.clone\r\n                        res << tmp\r\n                    end\r\n                end\r\n            end # end dd\r\n            \r\n            \r\n        end\r\n        \r\n        \r\n        # pm_id = pat_par[pat.id]\r\n        # x_id = app_par[pm_id]\r\n        # pp[:detail] = link_to(\'detail\', \"../Home/patient_record?id=\\\\#{x_id}\", :target=>\'_blank\')\r\n        \r\n        if is_oneline\r\n            res << pp\r\n        end\r\n    end\r\n    \r\n    lbl = []\r\n    lbl << \'site\'\r\n    # lbl = lbl + pf\r\n    lbl = %w{site diagnosis date_of_icu_admission	date_of_icu_discharge	date_of_hospital_discharge	icu_discharge_status	hospital_discharge_status	dm	has_vasopressor	has_ventilation	apache_ii	reference	baseline_serum_creainine_by_mdrd	baseline_serum_cr	first_available_cr}\r\n    # lbl << \"num_of_record_day\"\r\n    lbl << \"has_rrt\"\r\n    # lbl << \"rrt_start_day\"\r\n    # lbl << \"rrt_stop_day\"\r\n    # lbl << \'aki\'\r\n    # lbl << \"aki_auto_max_staging\"\r\n    # lbl << \"aki_auto_max_from\"\r\n    if params[:cs] == \'one\'\r\n        # fx = cf\r\n        fx = %w{creatinine}\r\n        fx.each do |i|\r\n            dd.each do |j|\r\n                lbl << \"\\\\#{i}_\\\\#{j}\"\r\n            end\r\n        end\r\n    elsif params[:cs] == \'multi\'\r\n        lbl = lbl + cf\r\n    end\r\n    # lbl = lbl + af\r\n    # lbl << \'outcome\'\r\n    # lbl = lbl + of\r\n        \r\n    \r\n    # result assign\r\n    display = \'table\'\r\n    if params[:type] == \'csv\'\r\n        display = \'csv\'\r\n    elsif params[:type] == \'xls\'\r\n        display = \'xls\'\r\n    elsif params[:type] == \'json\'\r\n        display = \'json\'\r\n    end\r\n    \r\n    # rs[:appointment] = a_app\r\n    # rs[:patient] = a_pat\r\n    # rs[:app_par] = app_par\r\n    # rs[:mod_par] = mod_par\r\n\r\n    if display == \'json\'\r\n        rs[:all_patient] = a_pat.count\r\n        rs[:all_aki] = a_aki.count\r\n        rs[:all_result] = res.count\r\n        rs[:label] = lbl\r\n        rs[:result] = res\r\n        rs[:time] = Time.now - tb\r\n%>\r\n\r\n<%= rs.to_json.html_safe %>\r\n\r\n<%\r\n    elsif display == \'table\'\r\n        # ff = res[0].keys\r\n        ff = lbl.collect{|i| i.to_sym}\r\n%>\r\n\r\n<%= stylesheet_link_tag    \"application\"  %>\r\n<h3>Total Patient = <%= a_pat.count %></h3>\r\nquery time = <%= Time.now - tb %>\r\n\r\n<table border=1 class=\'table table-striped table-bordered table-condensed\'>\r\n    <tr>\r\n<% ff.each do |i| %>\r\n        <th><%= i %></th>\r\n<% end %>        \r\n    </tr>\r\n<% \r\n        res.each do |i| \r\n%>\r\n    <tr>\r\n<% \r\n            ff.each do |j| \r\n                val = i[j]\r\n%>\r\n       <td><%= val %></td>\r\n<% end %>\r\n    </tr>\r\n<% end %>\r\n</table>\r\n\r\n<br/>\r\nProcessing time = <%= Time.now - tb %><br/>\r\n\r\n<%\r\n    elsif display == \'csv\'\r\n        require \'csv\'\r\n        fname = \'Export\'\r\n        header = true\r\n        if params[:fname]\r\n            fname = params[:fname]\r\n        end\r\n        if params[:header]==\'false\'\r\n            header = false\r\n        end\r\n    \r\n        response.headers[\"Content-Type\"] = \"text/csv\"\r\n        response.headers[\"Content-disposition\"] = \"attachment; filename=\\\\#{params[:solution_name]}-\\\\#{fname}-\\\\#{Time.now.strftime(\'%y%m%d%H%M%S\')}.csv\"\r\n        \r\n        # ff = res[0].keys\r\n        ff = lbl.collect{|i| i.to_sym}\r\n        \r\n        xxx = CSV.generate do |csv|\r\n            if header\r\n                csv << ff # header\r\n            end\r\n            res.each do |i|\r\n                tmp = []\r\n                ff.each do |j|\r\n                    tmp << \"\\\\#{i[j].to_s}\"\r\n                end\r\n                \r\n                csv << tmp\r\n            end\r\n        end\r\n%>\r\n<%= xxx.html_safe %>\r\n<%\r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2017-06-29 15:53:16','2017-06-29 15:53:16','export_ra','*'),(3100,'context_menu',944,4,'<%\r\nreturn_url = \'\'\r\nreturn_url = \"&return=\\\\#{params[:return]}\" if params[:return]\r\nname = this.document_name.humanize\r\nlist = [\r\n    {:name=>\'List\',:link=>\'index\',:remote=>false},\r\n    {:name=>\'Search\',:link=>\'search\',:remote=>false},\r\n    {:name=>\'Create \'+name,:link=>\'create\',:remote=>false}\r\n]\r\nif params[:id]\r\n    list<<{:name=>\'Edit\',:link=>\"edit?id=\\\\#{params[:id]}\\\\#{return_url}\",:remote=>false}\r\n    list<<{:name=>\'Delete\',:link=>\"destroy?id=\\\\#{params[:id]}\",:remote=>false}\r\nend\r\nlist<<{:name=>\'Back to Home\',:link=>\"../Home/index\",:remote=>false}\r\n%>\r\n<%= show_menu [{:name=>this.document_name.humanize,:open=>true,:actions=>list}] \r\n%>\r\n\r\n',NULL,NULL,NULL,'2017-06-30 07:23:58','2017-06-30 07:23:58','context_menu',''),(3101,'search',944,2,'<%= render :inline=>this.common_function %>\r\n<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n		width:100px\r\n    }\r\n</style>\r\n<%\r\n    df = get_document_field this.table_name\r\n    sd = df[:study_date][:pair]\r\n    report = []\r\n    \r\n    sd.each do |k,v|\r\n        report << [v, k]\r\n    end\r\n    # report = [\r\n    #         [\'Admission\', \'admission\'],\r\n    #         [\'Ward\', \'ward\'],\r\n    #         [\'Line / Color\', \'color\'],\r\n    #         [\'Case type (Ward/Private)\', \'case_type\']\r\n    #     ]\r\n%>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box-header\">\r\n			<h3>Search</h3>\r\n		</div>\r\n        <div class=\"w-box-content cnt_a\">\r\n<%= form_for :search,:url=>\"search_partial?update=result-panel\",:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n		<div class=\'clear\'></div>\r\n		<span class=\'span4\'>\r\n		    <label class=\'field-label\'style=\'width:100px\'>Search : </label>\r\n		    <div class=\'field-input\' style=\'width:300px\'><%= f.select :report, report, include_blank: true, :style=>\'margin-top:10px\' %></div>\r\n		</span>\r\n		<span class=\'span4\'>\r\n    		<span class=\"field-data\">\r\n    		    <div class=\"field-input\"><%=f.submit \'Submit\', :class=>\'btn btn-success\'%> </div>\r\n    		</span>\r\n    	</span>\r\n		<div class=\'clear\'></div>\r\n<% end %>\r\n\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class=\'clear\'></div>\r\n<br/>\r\n<div id=\'result-panel\'></div>',NULL,NULL,NULL,'2017-06-30 07:25:14','2017-06-30 07:25:14','search',''),(3102,'search_partial',944,3,'<%= render :inline=>this.common_function %>\r\n<%\r\n    res = get_model[this.table_name.to_sym].where(:study_date=>params[:search][:report]).all\r\n    \r\n    df  = get_document_field this.table_name\r\n    \r\n    lbl = df.keys\r\n    lbl = [:no, :nameth, :nameen, :tel, :email]\r\n    lbl << :created_at\r\n    lbl << :action\r\n%>\r\n<div class=\'row-fluid\'>\r\n    <div class=\'span12\'>\r\n        \r\n        <center><h1><%= df[:study_date][:pair][params[:search][:report]] %></h1></center>\r\n        <br/>\r\n        \r\n        <h3>Total registration : <%= res.count %></h3>\r\n        \r\n        <table id=\'search-result\' class=\"table table-bordered\" style=\'width:100%\'>\r\n            <thead>\r\n                <tr>\r\n<%\r\n    lbl.each do |i|\r\n        txt = \"\"\r\n        if !df[i].nil?\r\n            txt = df[i][:label].html_safe\r\n        else\r\n            if i.to_s == \'no\'\r\n                txt = \'No.\'\r\n            elsif i.to_s == \'action\'\r\n                txt = \'Action\'\r\n            elsif i.to_s == \'created_at\'\r\n                txt = \'Register Date\'\r\n            end\r\n        end\r\n%>\r\n                    <th><%= df[i].nil? ? \'Action\' : df[i][:label].html_safe %></th>\r\n<%  end %>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n<%\r\n    n = res.count + 1\r\n    res = res.sort_by{|i| i[:created_at]}.reverse\r\n    res.each do |i|\r\n        n -= 1\r\n%>\r\n                <tr>\r\n<%\r\n        lbl.each do |j|    \r\n            txt = \'\'\r\n            if j.to_s == \'no\'\r\n                txt = n\r\n            elsif j.to_s == \'action\'\r\n                txt = link_to(\'detail\', \"show?id=\\\\#{i.id}\", :target=>\'_blank\', :class=>\'btn btn-mini btn-info\')\r\n            elsif j.to_s == \'created_at\'\r\n                txt = i[j].strftime(\'%d/%m/%Y\')\r\n            else\r\n                txt = i[j]\r\n            end\r\n            \r\n%>\r\n                    <td><%= txt %></td>\r\n<%      end %>\r\n                </tr>\r\n<%  end %>\r\n            </tbody>\r\n        </table>\r\n    </div>\r\n</div>',NULL,NULL,NULL,'2017-06-30 07:30:29','2017-06-30 07:30:29','search_partial',''),(3103,'common_function',944,4,'<%\r\n    def document_query(cond = {}, sel_fields = {}, doc = this.table_name) \r\n        res = []\r\n        \r\n        if cond.empty?\r\n            today = Time.now\r\n            sdate = today.at_beginning_of_month\r\n            edate = today.end_of_month\r\n            cond[:created_at] = {\'$gte\'=>sdate.beginning_of_day,\'$lt\'=>edate.end_of_day}\r\n        end\r\n        \r\n        fields = {}\r\n        fields[:fields] = sel_fields\r\n        \r\n        obj = get_model[doc.to_sym].collection.find(cond, fields).to_a\r\n        if obj\r\n            res = obj\r\n        end\r\n        \r\n        return res\r\n    end\r\n    \r\n    def get_patient_by_document_result(res = [])\r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        m_pat = model[:patient]\r\n        m_pat_mod = model[:patient_module]\r\n        \r\n        g_form = res.group_by{|i| i[\'_id\']}\r\n        \r\n        fid = g_form.keys\r\n        # tmp = m_pat_mod.where(:module_id=>fid).all\r\n        tmp = m_pat_mod.collection.find({\'module_id\'=>{\'$in\'=>fid}}, {:fields=>{\'patient_id\'=>1, \'module_id\'=>1, \'created_at\'=>1, \'module_name\'=>1}}).to_a\r\n        g_tmp = tmp.group_by{|i| i[\'module_id\']}\r\n        \r\n        pid = tmp.collect{|i| i[\'patient_id\']}\r\n        pat = m_pat.collection.find({\'_id\'=>{\'$in\'=>pid}},{:fields=>{\'hn\'=>1, \'prefix_name\'=>1,\'first_name\'=>1,\'last_name\'=>1}}).to_a\r\n        \r\n        g_pat = pat.group_by{|i| i[\'_id\']}\r\n        \r\n        # res = {}\r\n        # res[:patient] = g_pat\r\n        # res[:module_link] = g_tmp\r\n        \r\n        # return res\r\n        return g_pat\r\n    end\r\n    \r\n    def get_patient_module_by_document_result(res = [])\r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        m_pat = model[:patient]\r\n        m_pat_mod = model[:patient_module]\r\n        \r\n        g_form = res.group_by{|i| i[\'_id\']}\r\n        \r\n        fid = g_form.keys\r\n        # tmp = m_pat_mod.where(:module_id=>fid).all\r\n        res = m_pat_mod.collection.find({\'module_id\'=>{\'$in\'=>fid}}, {:fields=>{\'patient_id\'=>1, \'module_id\'=>1, \'created_at\'=>1, \'module_name\'=>1, \'parent_id\'=>1}}).to_a\r\n        return res\r\n    end\r\n\r\n    def get_document_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].nil? ? \'\' : x[1].strip\r\n                    tmp[:list] << x[1].nil? ? \'\' : x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    def get_value f, fdoc, val\r\n        x = fdoc[f.to_sym]\r\n        v = val\r\n        h = x.to_h\r\n        if h.has_key? :pair and !v.nil? and v != \'\'\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n        elsif h[:field_type] == \'select_time\' and !v.nil? and v != \'\'\r\n            v = val.strftime(\'%H:%M\')\r\n        elsif h[:field_type] == \'relation_one\'\r\n            pr = eval(\"{\\\\#{h[:params]}}\")\r\n            dd = pr[:relation][:document]\r\n            v = get_model[dd].find(v)\r\n            v = v[:name] if v\r\n        end\r\n        return v\r\n    end\r\n    \r\n    @obj = {}\r\n    def val f, doc, default = \'N/A\'\r\n        doc = doc.to_sym\r\n        f = f.to_sym\r\n        if @obj.has_key? doc\r\n            # get_value(:premed, obj[:pre_operative_visit][:df], obj[:pre_operative_visit][:rec][:premed])\r\n            rt = get_value(f, @obj[doc][:df], @obj[doc][:rec][f])\r\n            return (rt.nil? or rt==\'\') ? default : rt\r\n        else\r\n            return default\r\n        end\r\n    end\r\n%>',NULL,NULL,NULL,'2017-06-30 07:32:18','2017-06-30 07:32:18','common_function',''),(3104,'reset_password',1208,3,'<%= render :inline=>this.init %>\r\n<%\r\n    require \'net/smtp\'\r\n \r\n    uid = params[:uid] # user_id\r\n    pid = params[:pid] # provider_id\r\n\r\n    prov = @models[:provider].find(pid)\r\n    user = @ehr_models[:user].find(uid)\r\n    \r\n    to = user[:email]\r\n    name = prov[:name]\r\n    \r\n    # pass = rand(10**24-10)+10\r\n    pass = 8.times.map{ Random.rand(10).to_s } .join(\'\')\r\n    \r\n    salt = User.random_string(10) \r\n    hashed_password = User.encrypt(pass, salt)\r\n \r\n    user.update_attributes :salt=>salt, :hashed_password=>hashed_password, :pin=>\'\'\r\n \r\n    message =\r\n<<EOF\r\nFrom: ESM Chaiwat <chaiwat@esm-solution.com>\r\nTo: \\#{name} <\\#{to}>\r\nSubject: [THKJR.info] Reset Password\r\n\r\nเรียน \\#{name},\r\n\r\nทางระบบได้ทำการ reset password โดยท่านสามารถทำการ login ในระบบ https://thkjr.info โดยใช้\r\n\r\nUsername : \\#{user[:login]}\r\nPassword : \\#{pass}\r\n\r\nเมื่อท่าน login แล้ว ให้ทำการสร้าง private password โดยเข้าไปที่\r\n\r\nเมนูบาร์ Setting > Private Password\r\n\r\nจึงเรียนมาเพื่อทราบ\r\n\r\n--\r\nChaiwat Bootchai\r\nSystem Administrator\r\nTHKJR.info\r\n\r\nEOF\r\n     \r\n	smtp = Net::SMTP.new \'smtp.gmail.com\', 587\r\n    smtp.enable_starttls\r\n    smtp.start(\'gmail.com\', \'chaiwat@esm-solution.com\', \'zamachita\', :login)\r\n    smtp.send_message message, \'chaiwat@esm-solution.com\', \"\\#{to}\"\r\n    smtp.finish   \r\n%>\r\n<%# message %>\r\n<script>\r\n    window.location = \"index\";\r\n</script>',NULL,NULL,NULL,'2017-07-04 03:23:53','2017-07-04 03:23:53','reset_password',''),(3105,'export_patient_data',1173,3,'<%\r\n	# export_data latest 07/07/2017\r\n%>\r\n<%= render :inline=>this.common_function %>\r\n<% \r\n    tb = Time.now \r\n    \r\n    params[:date] = \'all\'\r\n    doc_name = \'knee1\'\r\n    if params[:proc]\r\n        doc_name = params[:proc]\r\n    end\r\n    hos_code = nil\r\n    if params[:hosp]\r\n        hos_code = params[:hosp]\r\n    end\r\n    \r\n    # selected field\r\n    sf = [\'gender\']\r\n    if params[:sf]\r\n        sf = params[:sf].split(\',\')\r\n    end\r\n    # count N/A ?\r\n    na = false\r\n    if params[:na]\r\n        na = params[:na]\r\n    end\r\n    # distribution start\r\n    ds = 10\r\n    if params[:ds]\r\n        ds = params[:ds].to_i\r\n    end\r\n    # distribution end\r\n    de = 100\r\n    if params[:de]\r\n        de = params[:de].to_i\r\n    end\r\n    # step \r\n    sp = 1\r\n    if params[:sp]\r\n        sp = params[:sp].to_i\r\n    end\r\n    # data type (distribution, normal, ratio)\r\n    # dt = \'distribution\'\r\n    dt = \'normal\'\r\n    if params[:dt]\r\n        dt = params[:dt]\r\n    end\r\n    # count field number\r\n    cn = \'Yes\'\r\n    if params[:cn]\r\n        cn = params[:cn]\r\n    end\r\n    # sort by (key|value)\r\n    st = nil\r\n    if params[:st]\r\n        st = params[:st]\r\n    end\r\n    # bin of distribution\r\n    bn = 10\r\n    lw = nil # lower\r\n    lu = nil # upper \r\n    if params[:bn]\r\n        bn = params[:bn].to_i\r\n    end\r\n    if params[:lw]\r\n        lw = params[:lw].to_i\r\n    end\r\n    if params[:lu]\r\n        lu = params[:lu].to_i\r\n    end\r\n    # display (json, csv)\r\n    dp = \'json\'\r\n    if params[:dp]\r\n        dp = params[:dp]\r\n    end\r\n    \r\n    \r\n    \r\n    fol_doc = \'follow_up_knee\'\r\n    if doc_name.include? \'hip\'\r\n        fol_doc = \'follow_up_hip\'\r\n    end\r\n    \r\n    def get_doc_field doc_name\r\n        doc = get_document doc_name\r\n        # field map\r\n        fm = {}\r\n        # field list\r\n        # fl = []\r\n        # document field\r\n        df = {}\r\n        doc.fields.each do |i|\r\n            ft = i[:field_type]\r\n            if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n                next\r\n            end\r\n            \r\n            cn = i[:column_name].to_sym\r\n            # fl << cn\r\n            fm[cn] = i.to_h\r\n            \r\n            if i[:lov_type] == \'pair\'\r\n                tmp = {}\r\n                tmp[:name] = i[:name]\r\n                tmp[:list] = []\r\n                tmp[:pair] = {}\r\n                lov = i[:lov].to_s.split(\'\\r\\n\')\r\n                lov.each do |j|\r\n                    x = j.split(\'|\')\r\n                    tmp[:pair][x[0].strip] = x[1].strip\r\n                    tmp[:list] << x[1].strip\r\n                end\r\n                \r\n                fm[cn][:list] = tmp[:list]\r\n                fm[cn][:pair] = tmp[:pair]\r\n            end\r\n        end\r\n        return fm\r\n    end\r\n    \r\n    # @fm = fm\r\n    def get_value f, val\r\n        x = @fm[f.to_sym]\r\n        v = val\r\n        if x.to_h.has_key? :pair and !v.nil? and v != \'\'\r\n            # if f.to_sym == :if_rrt or f.to_sym == :vasopressor\r\n            #     v = x[:pair][v]\r\n            # else\r\n                a = v.split(\'|\').collect{|b| x[:pair][b]}\r\n                v = a.join(\', \')\r\n                # v = \"<span title=\'\\\\#{v}\'>\\\\#{val} <i class=\'splashy-help\'></i></span>\".html_safe\r\n            # end\r\n        end\r\n            # if f.to_sym == :delivered_lose and !v.nil? and v != \'\'\r\n            #         v = v.to_f.round(4) if Float(v) rescue v\r\n            # end\r\n        # if v.nil? or v == \'\'\r\n        #     v = \'-\'\r\n        # end\r\n        return v\r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	@ehr_model = ehr.load_model\r\n	m_pat = @ehr_model[:patient]\r\n	m_pat_mod = @ehr_model[:patient_module]\r\n	\r\n	# map prov_id <-> provider_name\r\n	prov = {}\r\n	a_prov = get_model[:provider].all\r\n	a_prov.each do |i|\r\n	    prov[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map company_id <-> company_name\r\n	comp = {}\r\n	a_comp = get_model[:company].all\r\n	a_comp.each do |i|\r\n	    comp[i.id.to_s] = i[:name]\r\n	end\r\n	\r\n	# map hospital_id <-> hospital_name\r\n	hosp = {}\r\n	a_hosp = get_model[:hospital].all\r\n	a_hosp.each do |i|\r\n	    hosp[i.id.to_s] = i[:hospital_name_thai]\r\n	end\r\n	\r\n	# map knee_component <--> component_name\r\n	kcom = {}\r\n	a_temp = get_model[:knee_component].all\r\n	a_temp.each do |i|\r\n	    kcom[i.id.to_s] = i[:name]\r\n	end\r\n	# map hip component <-> component_name\r\n# 	hcom = {}\r\n# 	a_temp = get_model[:hip_component].all\r\n# 	a_temp.each do |i|\r\n# 	    hcom[i.id.to_s] = i[:name]\r\n# 	end\r\n    \r\n    # map colpo_id <-> colpo\r\n    colpo = {}\r\n    ids   = []\r\n    a_col = get_model[doc_name.to_sym].all\r\n    a_col.each do |i|\r\n        ids << i.id\r\n        colpo[i.id.to_s] = i\r\n    end\r\n    \r\n    # map patient_id <-> patient\r\n    pat_ids = get_patient_filtered(hos_code)\r\n    pat = {}\r\n    rs_pat = m_pat.find(pat_ids)\r\n    rs_pat.each do |i|\r\n        pat[i.id.to_s] = i\r\n    end\r\n    \r\n    a_prov = m_pat_mod.where(:module_name=>\"\\\\#{@current_project.name}#provider\", :patient_id=>pat_ids).all\r\n    pat_prov = a_prov.group_by{|i| i[:patient_id]}\r\n\r\n    # patient fields\r\n    pf = [:id, :hn, :name, :hospital_name, :age, :gender, :surgeon, :created_my, :created_year]\r\n    # display field\r\n    colf = pf\r\n    \r\n    rs_col = []\r\n    rs_les = []\r\n    \r\n    # patient-follow_up\r\n    pat_foll = {}\r\n    # patient-implant_profile\r\n    pat_imp  = {}\r\n    # all_follow_up\r\n    fol_list = []\r\n    # all_implant_profile\r\n    imp_list = []\r\n    zz = []\r\n    rs_pat.each do |i|\r\n        pat_id = i.id.to_s\r\n        # patient\r\n        pt = i\r\n        \r\n        if pt.nil?\r\n            next\r\n        end\r\n        \r\n        today = i[:created_at]\r\n        # if !cp[:operation_date].nil? and cp[:operation_date] != \'\'\r\n        #     today = cp[:operation_date]\r\n        # end\r\n        # d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  pt[:birth_date].day) : today\r\n        d = !pt[:birth_date].nil? ? Date.new(today.year, pt[:birth_date].month,  1) : today\r\n        age = !pt[:birth_date].nil? ? d.year - pt[:birth_date].year - (d > today ? 1 : 0) : 0\r\n        \r\n        \r\n        tmp = {}\r\n        tmp[:id]  = pt.id.to_s[5..14]\r\n        tmp[:hn]  = pt[:hn]\r\n        tmp[:name]= \"\\\\#{pt[:first_name]} \\\\#{pt[:last_name]}\"\r\n        tmp[:age] = age\r\n        tmp[:hospital_name] = hosp[pt[:hospital_name].to_s]\r\n        tmp[:gender] = pt[:gender]\r\n        \r\n        mod = pat_prov[i.id][0]\r\n        prov_id = mod[:module_id].to_s\r\n        tmp[:surgeon] = prov_id\r\n        \r\n        tmp[:created_my]   = pt[:created_at].strftime(\'%m/%Y\')\r\n        tmp[:created_year] = pt[:created_at].strftime(\'%Y\')\r\n        \r\n        rs_col << tmp\r\n    end\r\n    \r\n    xx = {}\r\n    dd = {}\r\n    sm = 0\r\n    \r\n    # labels\r\n    lbn = []\r\n    # data_series\r\n    dds = []\r\n    \r\n    # result set\r\n    res = {}\r\n    res[:pat_count] = rs_pat.count\r\n    \r\n    if dt == \'distribution\'\r\n        xx = rs_col.group_by{|i| i[sf[0].to_sym].to_i}\r\n        (ds..de).step(sp) do |i|\r\n            v = xx[i].nil? ? 0 : xx[i].count\r\n            dd[i] = v\r\n            sm += v\r\n        end\r\n        # labels\r\n        lbn = dd.keys\r\n        # data_series\r\n        dds = dd.values\r\n    elsif dt == \'bin\'\r\n        xx = rs_col.group_by{|i| i[sf[0].to_sym].to_i}\r\n        \r\n        dn = (lw.to_i - 1) < 0 ? 0 : ((lw.to_i / bn) * bn)\r\n        up = (lu.to_i == 0) ? ((xx.keys.max / bn) * bn) : lu.to_i\r\n        ix = (dn == 0) ? 0 : 0 - ((dn - 1) / bn)\r\n        \r\n        ub = (up / bn) + ix\r\n        xx.each do |k,v|\r\n            n = v.count\r\n            m = ((k / bn) + ix) <= 0 ? 0 : (k / bn) + ix\r\n            if m >= ub\r\n                m = ub\r\n            end\r\n            \r\n            if !dd.has_key? m\r\n                dd[m] = 0\r\n            end\r\n            dd[m] += n\r\n        end\r\n        # (dn..up).\r\n        mn = dd.keys.min\r\n        mx = dd.keys.max\r\n        (mn).upto(mx) do |i|\r\n            aa = ((i - 1) * bn) + dn + 1\r\n            bb = (i * bn) + dn\r\n            \r\n            if i == 0 and (lw != 0)\r\n                if aa < 0\r\n                    aa = 0\r\n                end\r\n                lbn << \"< \\\\#{bb}\"\r\n            elsif i == mx and (lu != 0)\r\n                lbn << \"> \\\\#{aa}\"\r\n            else\r\n                lbn << \"\\\\#{aa} - \\\\#{bb}\"\r\n            end\r\n            \r\n            dds << dd[i]\r\n        end\r\n        # lbn = [dn,up,ix]\r\n        \r\n        sm = dd.values.sum\r\n    elsif dt == \'bin-matrix\'\r\n        xx = rs_col.group_by{|i| i[sf[0].to_sym].to_i}\r\n        # compared field\r\n        cf = sf[1].to_sym\r\n        \r\n        dn = (lw.to_i - 1) < 0 ? 0 : ((lw.to_i / bn) * bn)\r\n        up = (lu.to_i == 0) ? ((xx.keys.max / bn) * bn) : lu.to_i\r\n        ix = (dn == 0) ? 0 : 0 - ((dn - 1) / bn)\r\n        \r\n        ub = (up / bn) + ix\r\n        tm = rs_col.group_by{|i| i[cf]}\r\n        pos_key = tm.keys.sort.reverse\r\n        res[:row] = pos_key\r\n        # res[:xxx] = tm\r\n        xx.each do |k,v|\r\n            m = ((k / bn) + ix) <= 0 ? 0 : (k / bn) + ix\r\n            if m > ub\r\n                m = ub\r\n            end\r\n            sm += v.count\r\n            g = v.group_by{|i| i[cf]}\r\n            \r\n            if !dd.has_key? m\r\n                dd[m] = {}\r\n                pos_key.each do |i|\r\n                    dd[m][i] = 0\r\n                end\r\n            end\r\n            \r\n            pos_key.each do |i|\r\n                n = g[i].nil? ? 0 : g[i].count\r\n                dd[m][i] += n\r\n            end\r\n        end\r\n        # (dn..up).\r\n        mn = dd.keys.min\r\n        mx = dd.keys.max\r\n        (mn).upto(mx) do |i|\r\n            aa = ((i - 1) * bn) + dn + 1\r\n            bb = (i * bn) + dn\r\n            \r\n            if i == 0 and (lw != 0)\r\n                if aa < 0\r\n                    aa = 0\r\n                end\r\n                lbn << \"< \\\\#{bb}\"\r\n            elsif i == mx and (lu != 0)\r\n                lbn << \"> \\\\#{aa}\"\r\n            else\r\n                lbn << \"\\\\#{aa} - \\\\#{bb}\"\r\n            end\r\n            \r\n            # dds << dd[i]\r\n        end\r\n        # lbn = [dn,up,ix]\r\n        \r\n        # sm = dd.values.sum\r\n        vv = {}\r\n        pos_key.each do |i|\r\n            vv[i] = []\r\n            dd.keys.sort.each do |j|\r\n                vv[i] << dd[j][i]\r\n            end\r\n        end\r\n        dds = vv\r\n    elsif dt == \'data-matrix\'\r\n        xx = rs_col.group_by{|i| i[sf[0].to_sym]}\r\n        # compared field\r\n        cf = sf[1].to_sym\r\n        yy = rs_col.group_by{|i| i[cf]}\r\n        row = yy.keys.sort\r\n        lbn = xx.keys.sort\r\n        \r\n        tmp = rs_col.group_by{|i| [i[sf[0].to_sym], i[cf]]}\r\n        dds = {}\r\n        rw  = []\r\n        lbn.each do |m|\r\n            # q = [m.to_s]\r\n            dd[m] = {}\r\n            row.each do |n|\r\n                q = [m, n]\r\n                v = 0\r\n                if !tmp[q].nil?\r\n                    x = tmp[q]\r\n                    \r\n                    if params[:cn].nil?\r\n                        v = x.count\r\n                    else\r\n                        w = x.group_by{|i| i[cn.to_sym]}\r\n                        w.each do |k,val|\r\n                            if k.nil? or k == \'\'\r\n                                k = \'N/A\'\r\n                            end\r\n                            if n.nil? or n == \'\'\r\n                                n = \'N/A\'\r\n                            end\r\n                            kk = \"\\\\#{n} - \\\\#{k}\"\r\n                            rw << kk\r\n                            v = val.count\r\n                            dd[m][kk] = v\r\n                            sm += v\r\n                        end\r\n                    end\r\n                end\r\n                if params[:cn].nil?\r\n                    dd[m][n] = v\r\n                    sm += v\r\n                end\r\n            end\r\n        end\r\n        vv = {}\r\n        if !params[:cn].nil?\r\n            row = rw.sort.uniq\r\n        end\r\n        row.each do |i|\r\n            vv[i] = []\r\n            dd.keys.sort.each do |j|\r\n                vv[i] << dd[j][i].to_i\r\n            end\r\n        end\r\n        dds = vv\r\n        \r\n        # if params[:cn].nil?\r\n        #     res[:row] = row\r\n        # else\r\n        #     res[:row] = rw\r\n        # end\r\n        res[:row] = row\r\n    elsif dt == \'versus-filter\'\r\n        ss = sf.collect{|i| i.to_sym}\r\n        \r\n        xx = rs_col.group_by{|i| i[ss[0]]}\r\n        yy = rs_col.group_by{|i| i[ss[1]]}\r\n        \r\n        kx = xx.keys.sort\r\n        ky = yy.keys.sort\r\n        \r\n        lbn = kx\r\n        res[:row] = ky\r\n        \r\n        tmp = rs_col.group_by{|i| [i[ss[0]], i[ss[1]]]}\r\n        \r\n        txt = [ss[0], ss[1], ss.join(\' + \'), ss.join(\' ~ \')]\r\n        ttt = [0,0,0,0]\r\n        xxx = [[],[],[],[]]\r\n        kx.each do |x|\r\n            dd[x] = {}\r\n            ky.each do |y|\r\n                q = [x, y]\r\n                n = 0\r\n                v = tmp[q]\r\n                if !v.nil?\r\n                    n = v.count\r\n                end\r\n                dd[x][y] = n\r\n                sm += n\r\n                \r\n                if x.nil?\r\n                    x = cn\r\n                end\r\n                if y.nil?\r\n                    y = cn\r\n                end\r\n                \r\n                if (x != cn) and (y == cn)\r\n                    ttt[0] += n\r\n                    # xxx[0] << v\r\n                elsif (x == cn) and (y != cn)\r\n                    ttt[1] += n\r\n                    # xxx[1] << v\r\n                elsif (x != cn) and (y != cn)\r\n                    ttt[2] += n\r\n                    # xxx[2] << v\r\n                elsif (x == cn) and (y == cn)\r\n                    ttt[3] += n\r\n                    # xxx[3] << v\r\n                end\r\n            end\r\n        end\r\n        res[:vs] = {}\r\n        res[:vs][:lbn] = txt\r\n        res[:vs][:dat] = ttt\r\n        vv = {}\r\n        ky.each do |i|\r\n            vv[i] = []\r\n            dd.keys.sort.each do |j|\r\n                vv[i] << dd[j][i]\r\n            end\r\n        end\r\n        dds = vv\r\n        # res[:xxx] = xxx\r\n    elsif dt == \'versus\'\r\n        ss = sf.collect{|i| i.to_sym}\r\n        ss.each do |i|\r\n            s = 0\r\n            dd[i] = {}\r\n            tmp = rs_col.group_by{|j| j[i]}\r\n            tmp.each do |k,v|\r\n                if na\r\n                    if k.nil? or k == \'\'\r\n                        next\r\n                    end\r\n                end\r\n                \r\n                dd[i][k] = v.count\r\n                s += v.count\r\n            end\r\n            # dd[i][:s] = s\r\n        end\r\n        \r\n        tmp = [[],[],[],[]]\r\n        rs_col.each do |i|\r\n            \r\n            if i[ss[0]] != \'\' and i[ss[1]] == \'\'\r\n                tmp[0] << i\r\n            elsif i[ss[0]] == \'\' and i[ss[1]] != \'\'\r\n                tmp[1] << i\r\n            elsif i[ss[0]] != \'\' and i[ss[1]] != \'\'\r\n                tmp[2] << i\r\n            elsif i[ss[0]] == \'\' and i[ss[1]] == \'\'\r\n                tmp[3] << i\r\n            end\r\n            \r\n        end\r\n        ttt = []\r\n        tmp.each do |i|\r\n            ttt << i.count\r\n        end\r\n        # res[:tmp] = ttt\r\n        # res[:tmp_sum] = ttt.sum\r\n        \r\n        lbn = [ss[0], ss[1], ss.join(\' + \'), ss.join(\' ~ \')]\r\n        dds = ttt\r\n        sm = ttt.sum\r\n    elsif dt == \'multiple\'\r\n        ss = sf.collect{|i| i.to_sym}\r\n        ss.each do |i|\r\n            s = 0\r\n            dd[i] = {}\r\n            tmp = rs_col.group_by{|j| j[i]}\r\n            tmp.each do |k,v|\r\n                if na\r\n                    if k.nil? or k == \'\'\r\n                        next\r\n                    end\r\n                end\r\n                \r\n                dd[i][k] = v.count\r\n                s += v.nil? ? 0 : v.count\r\n            end\r\n            # dd[i][:s] = s\r\n        end\r\n        \r\n        # lbn = dd.keys\r\n        dd.each do |k, v|\r\n            lbn << k\r\n            dds << v[cn]\r\n        end\r\n        # sm = dds.sum\r\n    else\r\n        xx = rs_col.group_by{|i| i[sf[0].to_sym]}\r\n        xx.each do |k,v|\r\n            if na\r\n                if k.nil? or k == \'\'\r\n                    next\r\n                end\r\n            end\r\n            dd[k] = v.count\r\n            sm += v.count\r\n        end\r\n        \r\n        # labels\r\n            lbn = dd.keys\r\n        # data_series\r\n            dds = dd.values\r\n            \r\n    end\r\n    \r\n    if st == \'key\'\r\n        lbn = []\r\n        dds = []\r\n        kk = dd.keys.sort_by{|i| i}\r\n        kk.each do |i|\r\n            lbn << i\r\n            dds << dd[i]\r\n        end\r\n    elsif st == \'value\'\r\n        lbn = []\r\n        dds = []\r\n        kk = dd.sort_by {|k,v| v}\r\n        kk.each do |k,v|\r\n            lbn << k\r\n            dds << v\r\n        end\r\n    elsif st == \'rvalue\'\r\n        lbn = []\r\n        dds = []\r\n        kk = dd.sort_by {|k,v| v}.reverse\r\n        kk.each do |k,v|\r\n            lbn << k\r\n            dds << v\r\n        end\r\n    end\r\n        \r\n    \r\n    \r\n    \r\n    # res[:af]   = af\r\n    res[:res]  = rs_col.size\r\n    res[:lbn]  = lbn\r\n    res[:dd]   = dds\r\n    res[:rw]   = dd\r\n    # res[:xx]   = xx\r\n    res[:sm]   = sm\r\n    # res[:mm_foll] = mm_foll.size\r\n    # res[:imp_size] = imp_list.size\r\n    # res[:fol_size] = fol_list.uniq.size\r\n    # res[:pat_foll] = pat_foll\r\n    # res[:pat_imp]  = pat_imp\r\n    # res[:colf] = colf\r\n    \r\n    res[:time] = Time.now - tb\r\n    # res[:fm] = @fm\r\n    \r\n    sep = \'|\'\r\n    \r\n    if false \r\n%>\r\n<!-- Main Procedure -->\r\n<h3><%= doc_name.humanize %> total <%= rs_col.size %> records</h3>\r\n<%= colf.join(\'|\') %><br/>\r\n<%\r\n    \r\n    rs_col.each do |i|\r\n        colf.each do |j|\r\n%>\r\n<%= i[j] %>|\r\n<%\r\n        end\r\n    end\r\n    \r\n    end # false \r\n%>\r\n<%\r\n    if dp == \'plain\'\r\n        response.headers[\"Content-Type\"] = \"text/plain; charset=utf-8\"\r\n        lbn = lbn.map{|i| (i.nil? or i == \'\') ? \'N/A\' : i}\r\n%>\r\n<%= sf[0] %><%=sep%><%= lbn.join(sep) %>\r\n<%\r\n        if dt == \'bin-matrix\' or dt == \'data-matrix\' or dt == \'versus-filter\'\r\n            dd = res[:dd]\r\n            dd.each do |k,v|\r\n%>\r\n<%= (k.nil? or k == \'\') ? \'N/A\' : k %><%=sep%><%= v.join(sep) %>\r\n<%\r\n            end\r\n            tt = []\r\n            rw = res[:rw]\r\n            lbn = res[:lbn]\r\n            lbn.each do |i|\r\n                m = rw[i]\r\n                v = m.nil? ? [0] : m.values\r\n                tt << v.sum\r\n            end\r\n%>\r\nTotal<%=sep%><%= tt.join(sep) %>\r\n<%\r\n            if dt == \'versus-filter\'\r\n%>\r\n\r\nlabel<%=sep%><%= res[:vs][:lbn].join(sep) %>\r\ndata<%=sep%><%= res[:vs][:dat].join(sep) %>\r\n<%\r\n            end\r\n\r\n        else \r\n%>\r\ncount<%=sep%><%= dds.join(sep) %>\r\n<%      end %>\r\nsum<%=sep%><%= sm %>\r\ntotal<%=sep%><%= rs_col.count %>\r\n\r\n<% \r\n        if dt == \'versus\' or dt == \'multiple\'\r\n            rw = res[:rw]\r\n            rw.each do |k,v|\r\n%>\r\n<%= k %><%=sep%><%= v.keys.join(sep) %>\r\ncount<%=sep%><%= v.values.join(sep) %>\r\nsum<%=sep%><%= v.values.sum %>\r\n\r\n<%      \r\n            end\r\n\r\n        end \r\n%>\r\n<%  else %>\r\n<%= res.to_json.html_safe %>\r\n<%  end %>\r\n',NULL,NULL,NULL,'2017-07-11 02:54:37','2017-07-11 02:54:37','export_patient_data',''),(3106,'live_api',1001,3,'<%\r\n\r\n\r\n    models = get_model\r\n    \r\n    model = models[params[:model].to_sym]\r\n    \r\n    result = {:params=>params.to_json}\r\n    mrecord = nil\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    emodel = ehr.load_model\r\n        \r\n    patient_model = emodel[:patient]\r\n    module_model = emodel[:patient_module]\r\n    \r\n    \r\n    if params[:record]\r\n        rx = JSON.parse(params[:record])\r\n        \r\n        \r\n        \r\n        rx[\'id\'] = rx[\'_id\'] if rx[\'_id\']\r\n        record = model.find(rx[\'id\'])\r\n    \r\n        \r\n        unless record\r\n    \r\n       \r\n        \r\n        record = model.create  rx \r\n        \r\n        p = params[:params]\r\n        \r\n        apm = module_model.find(p[:parent_id])\r\n        \r\n        \r\n     i = module_model.last :module_name=>\"\\\\#{@current_project.name}#\\\\#{params[:model]}\"\r\n      l = 111\r\n      if i and i.ref_number\r\n          l = i.ref_number[6..-1].to_i%10000\r\n      end\r\n      next_id = format(\'%04d\',(l+1)%10000)\r\n      d = Time.now\r\n      @next_id = \"\\\\#{d.strftime(\'%y%m%d\')}\\\\#{next_id}\"  \r\n          \r\n          \r\n          \r\n        mrecord = module_model.create :parent_id=>p[:parent_id], :ref_number=> @next_id ,:module_id=>record.id, :module_name=>\"\\\\#{@current_project.name}#\\\\#{params[:model]}\",:patient_id=>apm.patient_id\r\n        \r\n        \r\n        else\r\n        \r\n        mrecord = module_model.where(:module_id=>record.id).first\r\n            \r\n        record.update_attributes rx \r\n            \r\n        end\r\n        \r\n        result[:record] = record\r\n        \r\n        unless params[:finding]\r\n            result[:app_id] =  module_model.find(mrecord.parent_id).module_id\r\n            \r\n        end\r\n        \r\n        \r\n        \r\n        \r\n    end\r\n\r\n    if params[:finding]\r\n        \r\n        fx = JSON.parse(params[:finding])\r\n        \r\n        \r\n        finding_model = models[params[:finding_model]]\r\n        \r\n        finding = finding_model.find(fx[\'id\'])\r\n        unless finding\r\n            finding = finding_model.create fx\r\n        end\r\n        params[:record_field] = (params[:location]+\"_scope\").to_sym\r\n        \r\n        \r\n        list = record[params[:record_field]]\r\n        list = [] unless list\r\n        list << finding.id\r\n        \r\n        record.update_attributes params[:record_field] => list\r\n        \r\n        \r\n        if params[:finding_image]\r\n            \r\n           title = params[:disease]\r\n           \r\n           list = finding[params[:finding_image]]\r\n           attm = models[:attachment]\r\n           attm.find(list).each_with_index do |i,index| \r\n           \r\n        #   if index%2==0\r\n            \r\n        #     title = params[:disease]\r\n        #     else\r\n        #     title = params[:location]\r\n        #     end\r\n            \r\n            title = params[:location]\r\n           \r\n           i.update_attributes :title=>title.humanize\r\n           \r\n           \r\n           \r\n           end\r\n            \r\n        end\r\n        \r\n        \r\n        result[:record_field] = params[:record_field] \r\n        result[:finding] = finding.id \r\n        result[:next_finding] = finding_model.new.id\r\n        result[:record] = record\r\n    end\r\n    \r\n    if params[:status]\r\n        \r\n        \r\n            models[:appointment].find(result[:app_id]).update_attributes :status=>\'Recovery\'\r\n        \r\n    end\r\n\r\n    if params[:start]\r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        emodel = ehr.load_model\r\n        \r\n        patient_model = emodel[:patient]\r\n        module_model = emodel[:patient_module]\r\n        \r\n        patient = patient_model.where(:hn=>params[:ref]).first\r\n        \r\n        date = Date.to_mongo(params[:start])\r\n        m = module_model.where(:parent_id=>params[:parent_id], :module_name=>\"\\\\#{@current_project.name}#\\\\#{params[:model]}\",:patient_id=>patient.id).first()\r\n        result[:module_name]= \"\\\\#{@current_project.name}#\\\\#{params[:model]}\"\r\n        result[:parent_id]= params[:parent_id]\r\n        \r\n        result[:patient_id] = patient.id\r\n        result[:date] = date\r\n        result[:m] = m\r\n        r = nil\r\n        if m\r\n          ma = module_model.find(m[\'parent_id\'])\r\n          app = models[:appointment].find(ma.module_id)\r\n          app.update_attributes :status=>\'Processing\'\r\n          r = model.collection.find(\"_id\"=>m[\'module_id\']).first()\r\n          result[:record]  = r\r\n        end\r\n        if r and params[:img]\r\n          attm = models[:attachment]\r\n           \r\n          result[:images] = attm.find(r[params[:img]]).collect{|i|  i }  \r\n\r\n           \r\n        end\r\n        \r\n        \r\n        \r\n     \r\n\r\n    end\r\n    \r\n       \r\n           scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n            map = {}\r\n            findings = []\r\n            \r\n            ids = []\r\n            \r\n            r = record unless r\r\n            if r \r\n                \r\n                for i in scope_list\r\n                    ids+= r[i] if r[i]\r\n                end\r\n                \r\n                result[:ids] = ids\r\n                \r\n                models[:colonoscopy_scope].find(ids).each do |i|\r\n                    map[i.id.to_s] = i \r\n                end\r\n               \r\n             index = 0   \r\n                  \r\n            for i in scope_list\r\n                \r\n                \r\n                for j in r[i]\r\n                \r\n                index+=1\r\n                t = {:loc=>i}\r\n                t2 = i.split(\"_\")[0]\r\n                lesion = map[j.to_s]\r\n                t[:title] = \"#\\\\#{index}. \\\\#{lesion[\'abnormal_type\']} at \\\\#{t2.humanize}\"\r\n                t[:id] = j.to_s\r\n                findings << t\r\n                    \r\n                end\r\n                \r\n            end\r\n               \r\n               result[:findings] = findings\r\n            end\r\n           \r\n        \r\n        \r\n    \r\n\r\n%><%=result.to_json.html_safe%>',NULL,NULL,NULL,'2017-07-16 07:21:03','2017-07-16 07:21:03','live_api','*'),(3107,'document_name',1225,1,'\'old_opd_first_visit\'',NULL,NULL,NULL,'2017-07-23 03:55:23','2017-07-23 03:55:23',NULL,NULL),(3108,'document_name',1226,1,'\'old_opd_visit_note\'',NULL,NULL,NULL,'2017-07-23 04:21:35','2017-07-23 04:21:35',NULL,NULL),(3109,'print',880,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    # gender\r\n	gd = {\'0\'=>\'N/A\',\'1\'=>\'Male\',\'2\'=>\'Female\'}\r\n	\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    med_id = pm.module_id\r\n    record = models[:opd_first_visit].find(med_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    provider = render_value(\'provider\')\r\n    \r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<meta content=\"authenticity_token\" name=\"csrf-param\" />\r\n<meta content=\"SdEWaBNLwQSAphZHmuFRZbAnL/xn+o2QS00f4UDiS0o=\" name=\"csrf-token\" />\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:960px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto; padding-top: 10px;} \r\n 	.break { page-break-after:always; margin-top:40px; top:20px}\r\n	 .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\" class=\"well\">\r\n				<div id=\"logoleft\" style=\"width:600px; float:left\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n					<br />\r\n					First Name : \r\n					<v><%= patient.prefix_name %> <%= patient.first_name %></v>\r\n					<br />\r\n					Last Name : \r\n					<v><%= patient.last_name %></v>\r\n					<br />\r\n					HN :&nbsp;\r\n					<v><%=patient.hn%></v>\r\n					<br />\r\n					Age :&nbsp;\r\n					<v><%= year%> Year <%=month%> Month <%= day%> Day </v>\r\n					<br />\r\n					Gender :&nbsp;\r\n					<v><%= gd[patient[:gender]] %></v>\r\n					<br />\r\n					\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now %></p>\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n			</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n<%= render :inline=>this.print_partial%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<div class=\"break\"></div>\r\n</div>\r\n\r\n<script>\r\n//window.print()\r\n</script>\r\n\r\n</body>\r\n</html>\r\n\r\n 	',NULL,NULL,NULL,'2017-07-23 04:44:50','2017-07-23 04:44:50','print',''),(3110,'print_partial',880,4,'<%\r\n\r\n\r\n    # models  = @models\r\n    # pm = @module_model.find(params[:id])\r\n    # med_id = pm.module_id\r\n    # record = models[:skin_pick_test].find(med_id)\r\n    # # @record = record\r\n    # @document = get_document this.document_name\r\n\r\n   \r\n   \r\n   record = @record\r\n%>\r\n\r\n\r\n<div id=\"page\">\r\n  <h3>Opd visit</h3><hr style=\"margin-bottom: 5px;\"/>\r\n  <div>\r\n    <div>\r\n      <div id=\"form-data\">\r\n        <div>\r\n          <div id=\"sortable\">\r\n            <div id=\"525-F5602108481\"></div>\r\n            <div style=\"width:100%; float:left\" id=\"525-F1185908999\"><strong>อาการที่เจ็บป่วย</strong></div>\r\n           <div style=\"clear:both\"></div>\r\n            <div style=\"width:500px; float:left\" id=\"fam_pain_nose\"><%=render_value \'last_diagnosis\'%>\r\n              \r\n            </div>\r\n            <div style=\"width:180px; float:left\" id=\"fam_pain_nose_note\">\r\n              <label>ระบุ :</label><%=render_value \'fam_pain_nose_note\'%>\r\n            </div>\r\n            <div style=\"clear:both\"></div>\r\n            Duration : <%=render_value \'duration_days\'%> วัน <%=render_value \'duration_mouth\'%> เดือน <%=render_value \'last_diagnosis\'%> ปี\r\n            <div style=\"width:100%; float:left\" id=\"525-F7566987087\"><strong>Anterior and Posterior Rhinoscopy</strong></div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_mucosa\">\r\n              <label>nasal mucosa :</label><%=render_value \'nasal_mucosa\'%>\r\n             \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"nasal_mucosa_abnormal\">\r\n              <label> note :</label><%=render_value \'nasal_mucosa_abnormal\'%>\r\n            </div>\r\n            <div style=\"clear:both\" id=\"525-F8101366529\"></div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_discharge\">\r\n              <label>nasal discharge :</label><%=render_value \'nasal_discharge\'%>\r\n             \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"nasal_discharge_abnormal_note\">\r\n              <label>note :</label><%=render_value \'nasal_discharge_abnormal_note\'%>\r\n            </div>\r\n            <div style=\"clear:both\" id=\"525-F1411733355\"></div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_septum\">\r\n              <label>nasal septum :</label><%=render_value \'nasal_septum\'%>\r\n            \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"nasal_septum_abnormal_note\">\r\n              <label> note :</label><%=render_value \'nasal_septum_abnormal_note\'%>\r\n            </div>\r\n            <div style=\"clear:both\" id=\"525-F4482191640\"></div>\r\n            <div style=\"width:180px; float:left\" id=\"middle_turbinate\">\r\n              <label>middle turbinate :</label><%=render_value \'middle_turbinate\'%>\r\n            \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"middle_turbinate_abnormal_note\">\r\n              <label>note :</label><%=render_value \'middle_turbinate_abnormal_note\'%>\r\n            </div>\r\n            <div style=\"clear:both\" id=\"525-F7044008143\"></div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_polyp\">\r\n              <label>nasal polyp :</label><%=render_value \'nasal_polyp\'%>\r\n            \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"nasal_polyp_abnormal_note\">\r\n              <label>note :</label>\r\n              <%=render_value \'nasal_polyp_abnormal_note\'%>\r\n            </div>\r\n            <div style=\"clear:both\" id=\"525-F5001550601\"></div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_mass\">\r\n              <label>nasal mass :</label><%=render_value \'nasal_mass\'%>\r\n             \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"nasal_mass_abnormal_note\">\r\n              <label>note :</label><%=render_value \'nasal_mass_abnormal_note\'%>\r\n            </div><div style=\"clear:both\"></div>\r\n            <div style=\"width:150px; float:left\" id=\"525-F0526716157\"><strong>Nasal endoscopy</strong> :</div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_endoscopy_yn\"><%=render_value \'nasal_endoscopy_yn\'%>\r\n              \r\n            </div>\r\n            <div style=\"width:300px; float:left\" id=\"nasal_endoscopy_detail\">\r\n              <label>Detail :</label><%=render_value \'nasal_endoscopy_detail\'%>\r\n            </div>\r\n            <div id=\"525-F2909271281\" style=\"clear:both\"></div>&nbsp;<br />\r\n            Modified Lund Mackay Postoperative Endoscopy Score :<br />\r\n            <div id=\"rigid_nasal_endoscopic_score\" style=\"width: 630px;float: left; margin-right:5px\">\r\n              <% f =  @document.find_by_column_name \'rigid_nasal_endoscopic_score\'  \r\n                 \r\n                 p =  eval(\"{\\\\#{f.params}}\") \r\n              \r\n              \r\n                values = eval(@record.rigid_nasal_endoscopic_score)\r\n                total = 0 \r\n                sum = {}\r\n              %>\r\n            <table border=\"1\" cellpadding=\"0\" cellspacing=\"0\">\r\n                  <tr>\r\n                      <td>&nbsp;</td>\r\n                      <% for c in p[:grid][:col]%>\r\n                      <th align=\"center\" style=\"padding:5px\"><%= c %></th>\r\n                      <% end %>\r\n                  </tr>\r\n                  \r\n                  <% p[:grid][:row].each_with_index  do |r,ri| %>\r\n                  <tr>\r\n                      <th align=\"center\" style=\"padding:5px\"><%=r%></th>\r\n                      <% p[:grid][:col].each_with_index do |c,ci| \r\n                      \r\n                      if values[ri.to_s][ci]!=\'\'\r\n                        sum[ci] = 0 unless sum[ci]\r\n                        sum[ci] += values[ri.to_s][ci].to_i \r\n                        total +=  values[ri.to_s][ci].to_i \r\n                    end\r\n                      %>\r\n                      <td align=\"center\"><%= values[ri.to_s][ci] %></td>\r\n                      <% end%>\r\n                      \r\n                  </tr>\r\n                  <% end %>\r\n                  \r\n                  <tr>\r\n                      <th align=\"center\" style=\"padding:5px\">Sum = <%total%> </th>\r\n                        <% p[:grid][:col].each_with_index do |c,ci| %>\r\n                      <td align=\"center\"><%= sum[ci] %></td>\r\n                      <% end %>\r\n                  </tr>\r\n              </table>\r\n              \r\n              \r\n              \r\n              <div>\r\n              \r\n              </div>\r\n            </div>\r\n            <div id=\"525-F2688413838\">\r\n              <table border=\"1\" width=\"320\" cellspacing=\"0\" cellpadding=\"0\" style=\"font-size:10px\">\r\n                <tbody>\r\n                  <tr>\r\n                    <td width=\"104\" valign=\"top\"><p align=\"center\">Mucosa<br />\r\n                      (0-6)</p></td>\r\n                    <td width=\"103\" valign=\"top\"><p align=\"center\">Discharge<br />\r\n                      (0-2)</p></td>\r\n                    <td width=\"52\" valign=\"top\"><p align=\"center\">Purulence<br />\r\n                      (0-2)</p></td>\r\n                  </tr>\r\n                  <tr>\r\n                    <td width=\"104\" valign=\"top\"><p>0 = normal mucosa <br />\r\n                      1 = mild edema<br />\r\n                      2 = severe edema<br />\r\n                      3 = mild polypoid<br />\r\n                      4 = severe polypoid<br />\r\n                      5 = polyp within cavity<br />\r\n                      6 = polyp beyond cavity</p></td>\r\n                    <td width=\"103\" valign=\"top\"><p>0 = no discharge<br />\r\n                      1 = clear, thin discharge<br />\r\n                      2 = thick, purulent discharge</p></td>\r\n                    <td width=\"52\" valign=\"top\"><p>0= absent<br />\r\n                      2 = present</p></td>\r\n                  </tr>\r\n                </tbody>\r\n              </table>\r\n              <br />\r\n            </div>\r\n            <div class=\"clear\"></div>&nbsp;<br />\r\n            <div id=\"lund_mckay_score\">\r\n              <label>Lund Mckay score :</label>\r\n              <div class=\"clear\"></div>\r\n              <div style=\"width:250px; float:left\">\r\n                 <% f =  @document.find_by_column_name \'lund_mckay_score\'  \r\n                 \r\n                 p =  eval(\"{\\\\#{f.params}}\") \r\n              \r\n              \r\n                values = eval(@record.lund_mckay_score)\r\n                total = 0 \r\n                sum = {}\r\n              %>\r\n            <table border=\"1\" cellpadding=\"0\" cellspacing=\"0\">\r\n                  <tr>\r\n                      <td>&nbsp;</td>\r\n                      <% for c in p[:grid][:col]%>\r\n                      <th align=\"center\" style=\"padding:5px\"><%= c %></th>\r\n                      <% end %>\r\n                  </tr>\r\n                  \r\n                  <% p[:grid][:row].each_with_index  do |r,ri| %>\r\n                  <tr>\r\n                      <th align=\"center\" style=\"padding:5px\"><%=r%></th>\r\n                      <% p[:grid][:col].each_with_index do |c,ci| \r\n                      \r\n                      if values[ri.to_s][ci]!=\'\'\r\n                        sum[ci] = 0 unless sum[ci]\r\n                        sum[ci] += values[ri.to_s][ci].to_i \r\n                        total +=  values[ri.to_s][ci].to_i \r\n                    end\r\n                      %>\r\n                      <td align=\"center\"><%= values[ri.to_s][ci] %></td>\r\n                      <% end%>\r\n                      \r\n                  </tr>\r\n                  <% end %>\r\n                  \r\n                  <tr>\r\n                      <th align=\"center\" style=\"padding:5px\">Sum = <%total%> </th>\r\n                        <% p[:grid][:col].each_with_index do |c,ci| %>\r\n                      <td align=\"center\"><%= sum[ci] %></td>\r\n                      <% end %>\r\n                  </tr>\r\n              </table>\r\n              \r\n              </div>\r\n            </div>&nbsp;<br />\r\n            \r\n            <div style=\"width:640px; float:left; padding:10px\">\r\n            <div id=\"525-F6304495065\"><strong>Lab investigations</strong></div>\r\n            <div style=\"width:200px; float:left\" id=\"mctt\">\r\n              <label>MCTT : </label><%=render_value \'mctt\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"nasal_cytology\">\r\n              <label>Nasal Cytology : </label><%=render_value \'nasal_cytology\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"cbc\">\r\n              <label>CBC : </label><%=render_value \'cbc\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"anti_hiv\">\r\n              <label>Anti HIV : </label><%=render_value \'anti_hiv\'%>\r\n            </div>\r\n             \r\n            <div style=\"width:200px; float:left\" id=\"serum_ige\">\r\n              <label>Serum IgE : </label><%=render_value \'serum_ige\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"paranasal_sinus_xray\">\r\n              <label>Paranasal sinus X-ray : </label><%=render_value \'paranasal_sinus_xray\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"chest_xray\">\r\n              <label>Chest X-ray : </label><%=render_value \'chest_xray\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"paranasal_sinus_ct_scan\">\r\n              <label>Paranasal sinus CT scan : </label><%=render_value \'paranasal_sinus_ct_scan\'%>\r\n            </div>\r\n              \r\n            <div style=\"width:200px; float:left\" id=\"acoustic_rhinometry\">\r\n              <label>Acoustic rhinometry : </label><%=render_value \'acoustic_rhinometry\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"rhihomanometry\">\r\n              <label>Rhihomanometry : </label><%=render_value \'rhihomanometry\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"pick_test\">\r\n              <label>Pick test : </label><%=render_value \'pick_test\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"serial_end_point_titration\">\r\n              <label>Serial end point titration : </label><%=render_value \'serial_end_point_titration\'%>\r\n            </div>\r\n            </div>\r\n              <div style=\"clear:both\"></div>&nbsp;<br />\r\n            <div style=\"width:100%; float:left\" id=\"diagonsis\">\r\n              <label>Diagonsis : </label><b style=\"color:#F00\"><%=render_value \'diagonsis\'%></b>\r\n            </div><div style=\"clear:both\"></div>\r\n            <div style=\"width:500px; float:left\" id=\"plan_of_treatment\">\r\n              <label>Plan of treatment : </label><%=render_value \'plan_of_treatment\'%>\r\n            </div><br />&nbsp;<br />\r\n            <div style=\"width:100%; float:left\" id=\"525-F8694878105\"><strong>Impression</strong></div>\r\n            <div style=\"width:7000px; float:left\" id=\"impressions\">\r\n              <%=render_value \'impressions\'%>\r\n             \r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"other_impression\">\r\n             <%=render_value \'other_impression\'%>\r\n            </div>\r\n            <br />&nbsp;<br />\r\n            <div style=\"width:100%; float:left\" id=\"525-F8447400292\"><strong>Management</strong></div>\r\n            <div style=\"width:400px; float:left\" id=\"management\">\r\n              <%=render_value \'management\'%>\r\n              \r\n            </div>\r\n            <div style=\"width:100%; float:left\" id=\"description\">\r\n              <label>Description :</label><b style=\"color:#F00\"><p style=\"color:#F00\"><%=render_value \'description\'%></p></b>\r\n          \r\n            </div><div style=\"clear:both\"></div>\r\n            <div id=\"next_visit\">\r\n            \r\n                <div id=\"next_visit2\" style=\"float:right\">\r\n                  <div><%=render_value \'next_visit\'%> ( <%=render_value \'next_visit_time\'%><%=render_value \'time_type\'%> )\r\n                    \r\n                  </div>\r\n                </div>\r\n             \r\n            </div>\r\n          <div class=\"clear\"></div>\r\n          \r\n          </div>\r\n         \r\n        </div>\r\n      </div>\r\n      \r\n      <div id=\"clear\"></div>\r\n    </div>\r\n  </div>\r\n\r\n</div>\r\n\r\n\r\n',NULL,NULL,NULL,'2017-07-23 04:45:32','2017-07-23 04:45:32','print_partial',''),(3111,'print',561,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    # gender\r\n	gd = {\'0\'=>\'N/A\',\'1\'=>\'Male\',\'2\'=>\'Female\'}\r\n	\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    med_id = pm.module_id\r\n    record = models[:opd_visit_note].find(med_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    provider = render_value(\'provider\')\r\n    \r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<meta content=\"authenticity_token\" name=\"csrf-param\" />\r\n<meta content=\"SdEWaBNLwQSAphZHmuFRZbAnL/xn+o2QS00f4UDiS0o=\" name=\"csrf-token\" />\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:960px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto; padding-top: 10px;} \r\n 	.break { page-break-after:always; margin-top:40px; top:20px}\r\n	 .hideprint {\r\n		display:none;\r\n		\r\n    }\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:9px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n\r\n\r\n.document value {\r\ncolor: #0000ff;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\" class=\"well\">\r\n				<div id=\"logoleft\" style=\"width:600px; float:left\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n					<br />\r\n					First Name : \r\n					<v><%= patient.prefix_name %> <%= patient.first_name %></v>\r\n					<br />\r\n					Last Name : \r\n					<v><%= patient.last_name %></v>\r\n					<br />\r\n					HN :&nbsp;\r\n					<v><%=patient.hn%></v>\r\n					<br />\r\n					Age :&nbsp;\r\n					<v><%= year%> Year <%=month%> Month <%= day%> Day </v>\r\n					<br />\r\n					Gender :&nbsp;\r\n					<v><%= gd[patient[:gender]] %></v>\r\n					<br />\r\n					\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now %></p>\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n			</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n<%= render :inline=>this.print_partial%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<div class=\"break\"></div>\r\n</div>\r\n\r\n<script>\r\n//window.print()\r\n</script>\r\n\r\n</body>\r\n</html>\r\n\r\n 	',NULL,NULL,NULL,'2017-07-24 08:28:47','2017-07-24 08:28:47','print',''),(3112,'print_partial',561,4,'<%\r\n\r\n\r\n    # models  = @models\r\n    # pm = @module_model.find(params[:id])\r\n    # med_id = pm.module_id\r\n    # record = models[:skin_pick_test].find(med_id)\r\n    # # @record = record\r\n    # @document = get_document this.document_name\r\n\r\n   \r\n   \r\n   record = @record\r\n%>\r\n\r\n\r\n<div id=\"page\">\r\n  <h3>Opd visit</h3><hr style=\"margin-bottom: 5px;\"/>\r\n  <div>\r\n    <div>\r\n      <div id=\"form-data\">\r\n        <div>\r\n          <div id=\"sortable\">\r\n            <div id=\"525-F5602108481\"></div>\r\n            <div style=\"width:100%; float:left\" id=\"525-F1185908999\"><strong>อาการที่เจ็บป่วย</strong></div>\r\n           <div style=\"clear:both\"></div>\r\n            <div style=\"width:500px; float:left\" id=\"fam_pain_nose\"><%=render_value \'last_diagnosis\'%>\r\n              \r\n            </div>\r\n            <div style=\"width:180px; float:left\" id=\"fam_pain_nose_note\">\r\n              <label>ระบุ :</label><%=render_value \'fam_pain_nose_note\'%>\r\n            </div>\r\n            <div style=\"clear:both\"></div>\r\n            Duration : <%=render_value \'duration_days\'%> วัน <%=render_value \'duration_mouth\'%> เดือน <%=render_value \'last_diagnosis\'%> ปี\r\n            <div style=\"width:100%; float:left\" id=\"525-F7566987087\"><strong>Anterior and Posterior Rhinoscopy</strong></div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_mucosa\">\r\n              <label>nasal mucosa :</label><%=render_value \'nasal_mucosa\'%>\r\n             \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"nasal_mucosa_abnormal\">\r\n              <label> note :</label><%=render_value \'nasal_mucosa_abnormal\'%>\r\n            </div>\r\n            <div style=\"clear:both\" id=\"525-F8101366529\"></div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_discharge\">\r\n              <label>nasal discharge :</label><%=render_value \'nasal_discharge\'%>\r\n             \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"nasal_discharge_abnormal_note\">\r\n              <label>note :</label><%=render_value \'nasal_discharge_abnormal_note\'%>\r\n            </div>\r\n            <div style=\"clear:both\" id=\"525-F1411733355\"></div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_septum\">\r\n              <label>nasal septum :</label><%=render_value \'nasal_septum\'%>\r\n            \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"nasal_septum_abnormal_note\">\r\n              <label> note :</label><%=render_value \'nasal_septum_abnormal_note\'%>\r\n            </div>\r\n            <div style=\"clear:both\" id=\"525-F4482191640\"></div>\r\n            <div style=\"width:180px; float:left\" id=\"middle_turbinate\">\r\n              <label>middle turbinate :</label><%=render_value \'middle_turbinate\'%>\r\n            \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"middle_turbinate_abnormal_note\">\r\n              <label>note :</label><%=render_value \'middle_turbinate_abnormal_note\'%>\r\n            </div>\r\n            <div style=\"clear:both\" id=\"525-F7044008143\"></div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_polyp\">\r\n              <label>nasal polyp :</label><%=render_value \'nasal_polyp\'%>\r\n            \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"nasal_polyp_abnormal_note\">\r\n              <label>note :</label>\r\n              <%=render_value \'nasal_polyp_abnormal_note\'%>\r\n            </div>\r\n            <div style=\"clear:both\" id=\"525-F5001550601\"></div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_mass\">\r\n              <label>nasal mass :</label><%=render_value \'nasal_mass\'%>\r\n             \r\n            </div>\r\n            <div style=\"width:250px; float:left\" id=\"nasal_mass_abnormal_note\">\r\n              <label>note :</label><%=render_value \'nasal_mass_abnormal_note\'%>\r\n            </div><div style=\"clear:both\"></div>\r\n            <div style=\"width:150px; float:left\" id=\"525-F0526716157\"><strong>Nasal endoscopy</strong> :</div>\r\n            <div style=\"width:180px; float:left\" id=\"nasal_endoscopy_yn\"><%=render_value \'nasal_endoscopy_yn\'%>\r\n              \r\n            </div>\r\n            <div style=\"width:300px; float:left\" id=\"nasal_endoscopy_detail\">\r\n              <label>Detail :</label><%=render_value \'nasal_endoscopy_detail\'%>\r\n            </div>\r\n            <div id=\"525-F2909271281\" style=\"clear:both\"></div>&nbsp;<br />\r\n            Modified Lund Mackay Postoperative Endoscopy Score :<br />\r\n            <div id=\"rigid_nasal_endoscopic_score\" style=\"width: 630px;float: left; margin-right:5px\">\r\n              <% f =  @document.find_by_column_name \'rigid_nasal_endoscopic_score\'  \r\n                 \r\n                 p =  eval(\"{\\\\#{f.params}}\") \r\n              \r\n              \r\n                values = eval(@record.rigid_nasal_endoscopic_score)\r\n                total = 0 \r\n                sum = {}\r\n              %>\r\n            <table border=\"1\" cellpadding=\"0\" cellspacing=\"0\">\r\n                  <tr>\r\n                      <td>&nbsp;</td>\r\n                      <% for c in p[:grid][:col]%>\r\n                      <th align=\"center\" style=\"padding:5px\"><%= c %></th>\r\n                      <% end %>\r\n                  </tr>\r\n                  \r\n                  <% p[:grid][:row].each_with_index  do |r,ri| %>\r\n                  <tr>\r\n                      <th align=\"center\" style=\"padding:5px\"><%=r%></th>\r\n                      <% p[:grid][:col].each_with_index do |c,ci| \r\n                      \r\n                      if values[ri.to_s][ci]!=\'\'\r\n                        sum[ci] = 0 unless sum[ci]\r\n                        sum[ci] += values[ri.to_s][ci].to_i \r\n                        total +=  values[ri.to_s][ci].to_i \r\n                    end\r\n                      %>\r\n                      <td align=\"center\"><%= values[ri.to_s][ci] %></td>\r\n                      <% end%>\r\n                      \r\n                  </tr>\r\n                  <% end %>\r\n                  \r\n                  <tr>\r\n                      <th align=\"center\" style=\"padding:5px\">Sum = <%total%> </th>\r\n                        <% p[:grid][:col].each_with_index do |c,ci| %>\r\n                      <td align=\"center\"><%= sum[ci] %></td>\r\n                      <% end %>\r\n                  </tr>\r\n              </table>\r\n              \r\n              \r\n              \r\n              <div>\r\n              \r\n              </div>\r\n            </div>\r\n            <div id=\"525-F2688413838\">\r\n              <table border=\"1\" width=\"320\" cellspacing=\"0\" cellpadding=\"0\" style=\"font-size:10px\">\r\n                <tbody>\r\n                  <tr>\r\n                    <td width=\"104\" valign=\"top\"><p align=\"center\">Mucosa<br />\r\n                      (0-6)</p></td>\r\n                    <td width=\"103\" valign=\"top\"><p align=\"center\">Discharge<br />\r\n                      (0-2)</p></td>\r\n                    <td width=\"52\" valign=\"top\"><p align=\"center\">Purulence<br />\r\n                      (0-2)</p></td>\r\n                  </tr>\r\n                  <tr>\r\n                    <td width=\"104\" valign=\"top\"><p>0 = normal mucosa <br />\r\n                      1 = mild edema<br />\r\n                      2 = severe edema<br />\r\n                      3 = mild polypoid<br />\r\n                      4 = severe polypoid<br />\r\n                      5 = polyp within cavity<br />\r\n                      6 = polyp beyond cavity</p></td>\r\n                    <td width=\"103\" valign=\"top\"><p>0 = no discharge<br />\r\n                      1 = clear, thin discharge<br />\r\n                      2 = thick, purulent discharge</p></td>\r\n                    <td width=\"52\" valign=\"top\"><p>0= absent<br />\r\n                      2 = present</p></td>\r\n                  </tr>\r\n                </tbody>\r\n              </table>\r\n              <br />\r\n            </div>\r\n            <div class=\"clear\"></div>&nbsp;<br />\r\n            <div id=\"lund_mckay_score\">\r\n              <label>Lund Mckay score :</label>\r\n              <div class=\"clear\"></div>\r\n              <div style=\"width:250px; float:left\">\r\n                 <% f =  @document.find_by_column_name \'lund_mckay_score\'  \r\n                 \r\n                 p =  eval(\"{\\\\#{f.params}}\") \r\n              \r\n              \r\n                values = eval(@record.lund_mckay_score)\r\n                total = 0 \r\n                sum = {}\r\n              %>\r\n            <table border=\"1\" cellpadding=\"0\" cellspacing=\"0\">\r\n                  <tr>\r\n                      <td>&nbsp;</td>\r\n                      <% for c in p[:grid][:col]%>\r\n                      <th align=\"center\" style=\"padding:5px\"><%= c %></th>\r\n                      <% end %>\r\n                  </tr>\r\n                  \r\n                  <% p[:grid][:row].each_with_index  do |r,ri| %>\r\n                  <tr>\r\n                      <th align=\"center\" style=\"padding:5px\"><%=r%></th>\r\n                      <% p[:grid][:col].each_with_index do |c,ci| \r\n                      \r\n                      if values[ri.to_s][ci]!=\'\'\r\n                        sum[ci] = 0 unless sum[ci]\r\n                        sum[ci] += values[ri.to_s][ci].to_i \r\n                        total +=  values[ri.to_s][ci].to_i \r\n                    end\r\n                      %>\r\n                      <td align=\"center\"><%= values[ri.to_s][ci] %></td>\r\n                      <% end%>\r\n                      \r\n                  </tr>\r\n                  <% end %>\r\n                  \r\n                  <tr>\r\n                      <th align=\"center\" style=\"padding:5px\">Sum = <%total%> </th>\r\n                        <% p[:grid][:col].each_with_index do |c,ci| %>\r\n                      <td align=\"center\"><%= sum[ci] %></td>\r\n                      <% end %>\r\n                  </tr>\r\n              </table>\r\n              \r\n              </div>\r\n            </div>&nbsp;<br />\r\n            \r\n            <div style=\"width:640px; float:left; padding:10px\">\r\n            <div id=\"525-F6304495065\"><strong>Lab investigations</strong></div>\r\n            <div style=\"width:200px; float:left\" id=\"mctt\">\r\n              <label>MCTT : </label><%=render_value \'mctt\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"nasal_cytology\">\r\n              <label>Nasal Cytology : </label><%=render_value \'nasal_cytology\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"cbc\">\r\n              <label>CBC : </label><%=render_value \'cbc\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"anti_hiv\">\r\n              <label>Anti HIV : </label><%=render_value \'anti_hiv\'%>\r\n            </div>\r\n             \r\n            <div style=\"width:200px; float:left\" id=\"serum_ige\">\r\n              <label>Serum IgE : </label><%=render_value \'serum_ige\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"paranasal_sinus_xray\">\r\n              <label>Paranasal sinus X-ray : </label><%=render_value \'paranasal_sinus_xray\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"chest_xray\">\r\n              <label>Chest X-ray : </label><%=render_value \'chest_xray\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"paranasal_sinus_ct_scan\">\r\n              <label>Paranasal sinus CT scan : </label><%=render_value \'paranasal_sinus_ct_scan\'%>\r\n            </div>\r\n              \r\n            <div style=\"width:200px; float:left\" id=\"acoustic_rhinometry\">\r\n              <label>Acoustic rhinometry : </label><%=render_value \'acoustic_rhinometry\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"rhihomanometry\">\r\n              <label>Rhihomanometry : </label><%=render_value \'rhihomanometry\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"pick_test\">\r\n              <label>Pick test : </label><%=render_value \'pick_test\'%>\r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"serial_end_point_titration\">\r\n              <label>Serial end point titration : </label><%=render_value \'serial_end_point_titration\'%>\r\n            </div>\r\n            </div>\r\n              <div style=\"clear:both\"></div>&nbsp;<br />\r\n            <div style=\"width:100%; float:left\" id=\"diagonsis\">\r\n              <label>Diagonsis : </label><b style=\"color:#F00\"><%=render_value \'diagonsis\'%></b>\r\n            </div><div style=\"clear:both\"></div>\r\n            <div style=\"width:500px; float:left\" id=\"plan_of_treatment\">\r\n              <label>Plan of treatment : </label><%=render_value \'plan_of_treatment\'%>\r\n            </div><br />&nbsp;<br />\r\n            <div style=\"width:100%; float:left\" id=\"525-F8694878105\"><strong>Impression</strong></div>\r\n            <div style=\"width:7000px; float:left\" id=\"impressions\">\r\n              <%=render_value \'impressions\'%>\r\n             \r\n            </div>\r\n            <div style=\"width:200px; float:left\" id=\"other_impression\">\r\n             <%=render_value \'other_impression\'%>\r\n            </div>\r\n            <br />&nbsp;<br />\r\n            <div style=\"width:100%; float:left\" id=\"525-F8447400292\"><strong>Management</strong></div>\r\n            <div style=\"width:400px; float:left\" id=\"management\">\r\n              <%=render_value \'management\'%>\r\n              \r\n            </div>\r\n            <div style=\"width:100%; float:left\" id=\"description\">\r\n              <label>Description :</label><b style=\"color:#F00\"><p style=\"color:#F00\"><%=render_value \'description\'%></p></b>\r\n          \r\n            </div><div style=\"clear:both\"></div>\r\n            <div id=\"next_visit\">\r\n            \r\n                <div id=\"next_visit2\" style=\"float:right\">\r\n                  <div><%=render_value \'next_visit\'%> ( <%=render_value \'next_visit_time\'%><%=render_value \'time_type\'%> )\r\n                    \r\n                  </div>\r\n                </div>\r\n             \r\n            </div>\r\n          <div class=\"clear\"></div>\r\n          \r\n          </div>\r\n         \r\n        </div>\r\n      </div>\r\n      \r\n      <div id=\"clear\"></div>\r\n    </div>\r\n  </div>\r\n\r\n</div>\r\n\r\n\r\n',NULL,NULL,NULL,'2017-07-24 08:29:11','2017-07-24 08:29:11','print_partial',''),(3117,'index_screening',1229,2,'<%\r\n    \r\n    module_name = @current_project.name\r\n    if params[:date]\r\n        session[module_name]={:date=>params[:date]}\r\n    end\r\n    if session[module_name]\r\n        params[:date] = session[module_name][:date]\r\n    end\r\n    unless params[:date]\r\n        params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n    end\r\n \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    # map_visit = r_map(get_model[:visit_type].all)\r\n    # map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    # map_proc = r_map(get_model[:procedure].all)\r\n    # map_ind = r_map(get_model[:indication].all)\r\n    date = Time.now\r\n%>\r\n\r\n  \r\n   <%\r\n    models = get_model\r\n   \r\n    projects = models[:project].all.reverse\r\n    \r\n    current_project = nil\r\n    current_project = projects[0] if projects.size>0 \r\n    \r\n   %>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n\r\n    <div class=\"w-box-header\">\r\n       <b>Home Screening : <%= date.strftime(\'%d/%m/%Y\') %></b>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding:0px\" >\r\n        <div style=\"border:0px solid;margin:0px;\" class=\"alert alert-success\" >\r\n            <div class=\"document-border2\" style=\"border:0px solid;margin-bottom:0px\">\r\n            \r\n              <%=link_to \'New patient\',\'javascript:$(\"#new-patient\").slideDown()\',:class=>\'btn btn-success\'%> for <%= current_project.name %>\r\n                 <div id=\"new-patient\" style=\"display:none\" >\r\n    <%=form_for :data ,:url=>\'new_patient\' do |f| %>\r\n    <br/>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span4\">\r\n    <label>\r\n        เลขบัตรประจำตัวประชาชน\r\n    </label>\r\n    <%=f.text_field :public_id ,:size=>20%>\r\n    </div>\r\n    \r\n    <div class=\"span4\">\r\n    <label>\r\n        Hospital Number (ถ้ามี)\r\n    </label>\r\n    <%=f.text_field :hn ,:size=>20%>\r\n    </div>\r\n    \r\n    </div>\r\n    \r\n    <div class=\"row-fluid\">\r\n    <div class=\"span4\">\r\n    <label>\r\n        ชื่อ\r\n    </label>\r\n    <%=f.text_field :first_name ,:size=>20%>\r\n    </div>\r\n    \r\n    <div class=\"span4\">\r\n    <label>\r\n        นามสกุล\r\n    </label>\r\n    <%=f.text_field :last_name ,:size=>20%><br/>\r\n    </div>\r\n    \r\n    <div class=\"span4\">\r\n    <label>\r\n        เพศ <span class=\"f_req\">*</span>\r\n    </label>\r\n    <%=f.select :gender , options_for_select([[\'ชาย\',\'1\'],[\'หญิง\',\'2\']], :required=>\"required\", :validationmessage=>\'Cannot be empty\') %><br/>\r\n    </div>\r\n  \r\n  </div>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span4\">\r\n    <label>\r\n        วันเดือนปีเกิด <span class=\"f_req\">*</span>\r\n    </label>\r\n    <%=f.text_field :birth_date ,:size=>20, :id=>\'data-birth_date\', :required=>\"required\", :validationmessage=>\'Cannot be empty\'%><br/>\r\n    </div>\r\n    \r\n    <div class=\"span4\">\r\n    <label>\r\n        เบอร์ติดต่กลับ\r\n    </label>\r\n    <%=f.text_field :mobile ,:size=>20%><br/>\r\n    </div>\r\n    \r\n    </div>\r\n    \r\n    \r\n    <% if projects.size>0 %>\r\n    <div class=\"row-fluid\">\r\n    <label>\r\n        โครงการ\r\n    </label>\r\n    \r\n    <%=f.select :patient_type , options_for_select(projects.collect{|i| [i.name,i.code] }, current_project.code )  if projects.size>0%><br/>\r\n    <% end %>\r\n    \r\n    </div>\r\n    \r\n    <br/>\r\n     <%= f.submit \'New Patient\' ,:class=>\'btn btn-success\',:data=>{:disable_with=>\'loading\'}%> | \r\n     <%=link_to \'Cancel\',\'javascript:$(\"#new-patient\").slideUp()\'%>\r\n    <% end %>\r\n    </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n<div class=\"row-fluid \">    \r\n\r\n        <%= form_for :search ,:url=>\'../Home/index_screening\' do |f| %>\r\n\r\n<div class=\"alert\">\r\n<div class=\"span3 \">\r\n<right>\r\n  ค้นหา:  HN, PID, ชื่อ นามสกุล</right>\r\n</div>\r\n<div class=\"span3 \"><%=f.text_field :q%></div>\r\n\r\n<div class=\"span3 \">\r\n <%=f.submit \'Search\'%>\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n    <% end %>\r\n \r\n </div>\r\n    <div class=\"\">\r\n    \r\n    <div class=\"row-fluid\">\r\n    <div class=\"span4\">\r\n   \r\n    \r\n    \r\n    <h3>New Patients</h3>\r\n    <%  if current_project  %>\r\n  \r\n  \r\n\r\n    <%\r\n   \r\n        \r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        patient_model = model[:patient]\r\n        module_model = model[:patient_module]\r\n        \r\n        if params[:search] and params[:search][:q]!=\'\'\r\n            query = params[:search][:q]\r\n            keys = []\r\n            keys <<{:first_name=>Regexp.new(query)}\r\n            keys <<{:last_name=>Regexp.new(query)}\r\n            keys <<{:public_id=>Regexp.new(query)}\r\n            keys <<{:hn=>Regexp.new(query)}\r\n            \r\n            keys = {\'$or\'=>keys,:patient_type=>current_project.code}\r\n        \r\n            patients = patient_model.all(keys)\r\n\r\n\r\n        \r\n        #all patients in project  \r\n        else\r\n            \r\n        limit = 50\r\n        limit = 0 if params[:all]\r\n            \r\n        patients = patient_model.where(:patient_type=>current_project.code).limit(limit).all()\r\n        \r\n        end\r\n        \r\n        pms_map = {}\r\n        module_model.where(:patient_id=> patients.collect{|i| i.id }).all.collect{|i| pms_map[i.patient_id] = [] unless pms_map[i.patient_id] ; pms_map[i.patient_id] << i }\r\n        \r\n    \r\n        #all patients without patient_module\r\n        \r\n        new_patients = []\r\n        screening_patients = []\r\n        \r\n        for i in patients\r\n        \r\n         if pm = pms_map[i.id]\r\n            screening_patients << i\r\n        else\r\n            new_patients << i    \r\n        \r\n        end\r\n    end\r\n\r\n\r\n\r\n   index = 1\r\n    %>\r\n\r\n    <%=tabular :model=>%w{no name public_id},:col_width=>{\'no\'=>40},:data=>new_patients do |row,out| \r\n      out[0] = index      \r\n      out[1] = link_to(\"\\\\#{row.prefix_name}\\\\#{row.first_name} \\\\#{row.last_name}\", \"../../www/Patient/edit?id=\\\\#{row.id}\",:target=>\'_blank\')\r\n\r\n    index+=1\r\n\r\n    out << link_to(\"Screening\",\"../Screening/create?patient_id=\\\\#{row.id}\",:class=>\'btn btn-info\')   \r\n\r\n    \r\n    out \r\n    end\r\n    %>\r\n\r\n    \r\n    \r\n    </div>\r\n    \r\n    \r\n    <div class=\"span8\">\r\n    \r\n    <% index = 1 \r\n    \r\n        screening_patients.sort!{|a,b| pms_map[b.id].size<=>pms_map[a.id].size }\r\n    %>\r\n    \r\n    <h3>Screening Patients</h3>\r\n     <%=tabular :model=>%w{no name public_id hn birth_date actions},:col_width=>{\'public_id\'=>120,\'no\'=>55,\'actions\'=>250},:data=>screening_patients do |row,out| \r\n    \r\n    if pms = pms_map[row.id]\r\n        \r\n        screening_pm = nil\r\n        appoint_pm = nil\r\n        \r\n        for j in pms\r\n            screening_pm = j if j.module_name.index(\'screening\') \r\n            appoint_pm = j if j.module_name.index(\'appointment\')\r\n        end\r\n        \r\n        out[0] = index\r\n        index+=1\r\n        x = []\r\n        x << link_to(\"Screening\",\"../Screening/show?id=\\\\#{screening_pm.id}&return=../Home/index_screening\",:class=>\'btn\')  if screening_pm\r\n        unless appoint_pm\r\n            # x << link_to(\"+12Aug\",\"javascript:appoint(\'../Appointment/create?patient_id=\\\\#{row.id}&data[date]=12/08/2017&data[provider]=5978ac80790f9b310700000a&data[procedure]=5978aa64790f9b3630000002\',\'\\\\#{row.hn}\')\",:class=>\'btn btn-info\')\r\n            # x << link_to(\"+13Aug\",\"javascript:appoint(\'../Appointment/create?patient_id=\\\\#{row.id}&data[date]=13/08/2017&data[provider]=5978ac80790f9b310700000a&data[procedure]=5978aa64790f9b3630000002\',\'\\\\#{row.hn}\')\",:class=>\'btn btn-info\')\r\n            x << link_to(\"+8Dec\",\"javascript:appoint(\'../Home/register?patient_id=\\\\#{row.id}&data[date]=8/12/2018&data[provider]=5978ac80790f9b310700000a&data[procedure]=5978aa64790f9b3630000002\',\'\\\\#{row.hn}\')\",:class=>\'btn btn-info\')\r\n            x << link_to(\"+9Dec\",\"javascript:appoint(\'../Home/register?patient_id=\\\\#{row.id}&data[date]=9/12/2018&data[provider]=5978ac80790f9b310700000a&data[procedure]=5978aa64790f9b3630000002\',\'\\\\#{row.hn}\')\",:class=>\'btn btn-info\')\r\n\r\n            \r\n            # out << link_to(\"Appointment\",\"../Appointment/create?patient_id=\\\\#{row.id}\",:class=>\'btn btn-info\')\r\n        else\r\n            appointed = models[:appointment].find(appoint_pm.module_id)\r\n            x << link_to(\"Arrived \\\\#{appointed.date.strftime(\'%d-%m-%y\')}\",\"../Appointment/show?id=\\\\#{appoint_pm.id}&status=Arrived\",:class=>\'btn btn-success\') \r\n        end\r\n        out[5] = x.join(\"\")\r\n    end\r\n      out[1] = link_to(\"\\\\#{row.prefix_name}\\\\#{row.first_name} \\\\#{row.last_name}\", \"../../www/Patient/edit?id=\\\\#{row.id}\",:target=>\'_blank\')\r\n      birth_date = row[\'birth_date\']\r\n    if birth_date \r\n        out[4] = birth_date.strftime(\"%d-%m-\")+(birth_date.year+543).to_s     \r\n    else\r\n        out[4] = \'-\'\r\n    end\r\n\r\n    \r\n    out \r\n    end\r\n    %>\r\n\r\n    <%=link_to \'Show all\', \'index_screening?all=1\' %>\r\n   \r\n    </div>\r\n    \r\n    \r\n    <% end %>\r\n    \r\n    </div>\r\n    \r\n    </div>\r\n    \r\n<script>\r\n    function appoint(url,hn){\r\n        hn = window.prompt(\"HN?\",hn);\r\n        window.location=url+\'&hn=\'+hn;\r\n    }\r\n    $(document).ready(function(){\r\n       \r\n       $(\"#data-birth_date\").kendoDatePicker({\r\n	\r\n	});\r\n	\r\n	$(\"#data-birth_date\").change(function(){\r\n		obj = $(this)\r\n		v = obj.val()\r\n		if(v.length>0){\r\n		s = v.split(\"/\")\r\n		y = parseInt(s[2])\r\n		if(y>2200)\r\n		y = y-543\r\n		\r\n		d = new Date(y,parseInt(s[1]-1),parseInt(s[0]))\r\n		obj.val(\"\"+parseInt(s[0])+\"/\"+parseInt(s[1])+\"/\"+y)\r\n		}\r\n	});\r\n	\r\n    });\r\n     \r\n    // $(\'.dshb_icoNav\').hide()\r\n</script>    \r\n    \r\n    ',NULL,NULL,NULL,'2017-07-26 14:51:00','2017-07-26 14:51:00','index_screening',''),(3120,'register',1229,3,'<%\r\n\r\n\r\n            # x << link_to(\"+12Aug\",\"javascript:appoint(\'../Home/register?\r\n            \r\n            # patient_id=\\\\#{row.id}&\r\n            # data[date]=12/08/2017&\r\n            # data[provider]=5978ac80790f9b310700000a&\r\n            # data[procedure]=5978aa64790f9b3630000002\r\n            \r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        patient_model = model[:patient]\r\n        module_model = model[:patient_module]\r\n        models = get_model\r\n        \r\n        \r\n        \r\n        app_m = models[:appointment]\r\n        model = app_m\r\n        \r\n        p_date = params[:data][:date]\r\n							        \r\n        # m_date = Date.to_mongo(p_date)\r\n        params[:record] = params[:data]\r\n        params[:record][:status] = \'Appointed\'\r\n       \r\n        flash[:notice]=\"New record has been created\"\r\n        doc = get_document \'appointment\'\r\n	    record = doc.record_create(model,params)\r\n	    @module_name = @current_project.name+\'#appointment\' \r\n	    \r\n	    m = module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:data][:date]\r\n        \r\n\r\n        \r\n        \r\n\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=index_screening\" />',NULL,NULL,NULL,'2017-08-02 17:37:19','2017-08-02 17:37:19','register',''),(3122,'index_content',1007,4,'<%= content_for :header do  %>\r\n<%=link_to image_tag(\"/esm/cusys/mobile/colo_logo.png\", height:70, ), \"../../www/Home/index\" %> \r\n<%# image_tag \"/esm/cusys/mobile/trang_logo.png\", height:70 %> \r\n<% end %>\r\n',NULL,NULL,NULL,'2017-08-06 16:24:07','2017-08-06 16:24:07','index_content',''),(3123,'index',1230,2,'<style>\r\n    select{ width:90px;margin-top:8px;};\r\n</style>\r\n<!--<div class=\"hero-unit\" style=\"margin:10px\">-->\r\n<blockquote>\r\n<h2>Projects</h2>\r\n<hr>\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    projects = models[:project].all\r\n    projects.sort!{|a,b| b.start_date<=>a.start_date }\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    \r\n    if params[:query]\r\n        default_project_id = \"0\"\r\n        from_date = params[:query][\'from_date(1i)\']+\"-\"+params[:query][\'from_date(2i)\']+\"-\"+params[:query][\'from_date(3i)\']+\"-\" if params[:query]\r\n        # from_date = from_date.beginning_of_month\r\n        \r\n        to_date = params[:query][\'to_date(1i)\']+\"-\"+params[:query][\'to_date(2i)\']+\"-\"+params[:query][\'to_date(3i)\']+\"-\" if params[:query]\r\n        # to_date = to_date.end_of_month\r\n\r\n    else\r\n        default_project_id = projects[0].id.to_s\r\n        default_project_id = params[:project_id] if params[:project_id] \r\n    end\r\n    from_date = Date.to_mongo(from_date)\r\n    to_date = Date.to_mongo(to_date)\r\n\r\n    for i in projects \r\n        if i.id.to_s==default_project_id\r\n            btn_style = \'btn-primary\'\r\n            from_date = i.start_date\r\n            to_date = i.end_date\r\n        else\r\n            btn_style = \'\'\r\n        end\r\n%>\r\n<%=link_to i.name,\"../Report/index?project_id=\\\\#{i.id}\",:class=>\'btn btn-large \'+btn_style %>\r\n\r\n<% end %>\r\n\r\n<%=form_for :query, :url=>\"\" do |f| %>\r\n\r\nPeriod : \r\n<%=f.date_select :from_date, :order=>[:day, :month, :year],:default=>from_date%> -\r\n<%=f.date_select :to_date, :order=>[:day, :month, :year],:default=>to_date  %>\r\n<%= f.submit \"Query\", :class=>\'btn\'%>\r\n\r\n\r\n<% end %>\r\n\r\n<% \r\n    format_startdate = from_date.strftime(\"%d/%m/%Y\")\r\n    format_enddate = to_date.strftime(\"%d/%m/%Y\")\r\n    format_startend = format_startdate+\"-\"+format_enddate\r\n    format_startend = format_startdate if format_startdate==format_enddate\r\n        \r\n    if true\r\n        if default_project_id != \"0\"\r\n            project = models[:project].find(default_project_id)\r\n            format_startdate = project.start_date.strftime(\"%d/%m/%Y\")\r\n            format_enddate = project.end_date.strftime(\"%d/%m/%Y\")\r\n            format_startend = project.start_date.strftime(\"%d-\")+format_enddate\r\n        end\r\n%>\r\n\r\n<%= %>\r\n<!--</div>-->\r\n<hr>\r\n</blockquote>\r\n\r\n<blockquote>\r\n<h1>Summary Report</h1>\r\n<hr>\r\n<%=link_to \"Summary \"+format_startend,\"../Home/summary_report_2?from_date=\"+format_startdate+\"&to_date=\"+format_enddate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n<%=link_to \"Demographic Report\",\"../Report/demographic_report\",:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n\r\n</blockquote>\r\n\r\n<blockquote>\r\n<h1>Patients Report</h1>\r\n<hr>\r\n<%=link_to \"BSH Patient \"+format_startend,\"../Home/patient_report?date=\"+format_startdate+\"&stop_date=\"+format_enddate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n\r\n<% if default_project_id != \"0\"%>\r\n<%=link_to \"BSH Patient \"+format_startdate,\"../Home/patient_report?date=\"+format_startdate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n<%=link_to \"BSH Patient \"+format_enddate,\"../Home/patient_report?date=\"+format_enddate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<% end %>\r\n</blockquote>\r\n\r\n<blockquote>\r\n<h1>Pathology Report</h1>\r\n<hr>\r\n<%=link_to \"BSH Patho \"+format_startend,\"../Home/patient_patho?date=\"+format_startdate+\"&stop_date=\"+format_enddate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n\r\n<% if default_project_id != \"0\"%>\r\n<%=link_to \"BSH Patho \"+format_startdate,\"../Home/patient_patho?date=\"+format_startdate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n<%=link_to \"BSH Patho \"+format_enddate,\"../Home/patient_patho?date=\"+format_enddate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<% end %>\r\n</blockquote>\r\n\r\n<blockquote>\r\n<h1>Finding Details Report</h1>\r\n<hr>\r\n<%=link_to \"BSH Patho Details \"+format_startend,\"../Home/patient_polyp_cancer?date=\"+format_startdate+\"&stop_date=\"+format_enddate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n\r\n<% if default_project_id != \"0\"%>\r\n<%=link_to \"BSH Patho Details \"+format_startdate,\"../Home/patient_polyp_cancer?date=\"+format_startdate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n<%=link_to \"BSH Patho Details \"+format_enddate,\"../Home/patient_polyp_cancer?date=\"+format_enddate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n<% end %>\r\n\r\n<%=link_to \"BSH Abnormal Details \"+format_startend,\"../Home/patient_abnormal?date=\"+format_startdate+\"&stop_date=\"+format_enddate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n\r\n<% if default_project_id != \"0\"%>\r\n<%=link_to \"BSH Abnormal Details \"+format_startdate,\"../Home/patient_abnormal?date=\"+format_startdate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n<%=link_to \"BSH Abnormal Details \"+format_enddate,\"../Home/patient_abnormal?date=\"+format_enddate,:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n<% end %>\r\n</blockquote>\r\n\r\n<blockquote>\r\n<h1>Poor Bowel</h1>\r\n<hr>\r\n<%=link_to \"Poor Bowel \"+format_startend,\"../Home/patient_report?name=Poor Bowel Report&date=\"+format_startdate+\"&stop_date=\"+format_enddate+\"&poor=1\",:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n\r\n<% if default_project_id != \"0\"%>\r\n<%=link_to \"Poor Bowel \"+format_startdate,\"../Home/patient_report?name=Poor Bowel Report&date=\"+format_startdate+\"&poor=1\",:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n<br/>\r\n<%=link_to \"Poor Bowel \"+format_enddate,\"../Home/patient_report?name=Poor Bowel Report&date=\"+format_enddate+\"&poor=1\",:class=>\'btn\',:target=>\'_blank\' %><br/>\r\n</blockquote>\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2017-08-07 16:26:38','2017-08-07 16:26:38','index','admin'),(3124,'print_partial',1009,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id]) \r\n    colono_id = pm.module_id\r\n    record = models[:colonoscopy].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = pm.created_at.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize if@current_user %></p>\r\n<p>Printed at :&nbsp;<%=thdate Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colonoscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v><%=thdate record.date_note%></v>&nbsp;&nbsp; Colonoscope by :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n  \r\n   \r\n	  <table width=\"100%\">\r\n	    <tr>\r\n	      <td > <h4 style=\"padding:0px; margin:0px; margin-left:10px\">Status : <%=record[\'status\']%> </h4></td>\r\n	      <td><h4 style=\"padding:0px; margin:0px;margin-left:10px\">Sedation</h4></td>\r\n        </tr>\r\n	    <tr>\r\n      <td width=\"60%\"><p><span style=\"float:left; \"> </span>\r\n        <span style=\"float:left;display:block-inline;\">\r\n				<table width=\"100%\" style=\"margin-left:10px\" >\r\n				<tr>\r\n				  \r\n					<td width=\"300\"><label>Previous opreation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n				 \r\n					<td><label>Bowel Preparation :</label> <v><%=render_value \'bowel_preparation\' %> <%=record[\'bowel_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'bowel_other\'%></v></td>\r\n				</tr>\r\n				<tr>\r\n				\r\n					<td><label>Quality of Preparate :</label> <v><%=record[\'quality_of_preparate\']%></v></td>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \') if record[\'record\']%></v></td>\r\n				\r\n				<tr>\r\n					\r\n					<td width=\"220\"><label>Additional Bowel Preparation :</label> <v><%=render_value \'additional_bowel_preparation\' %> <%=record[\'add_bowel_prep_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'add_bowel_prep_other\'%></v></td>\r\n				</tr>		\r\n				\r\n			</table>	\r\n		</span>\r\n		\r\n \r\n		</p></td>\r\n\r\n<td width=\"40%\"  valign=\"top\">\r\n\r\n<p>\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% any_sedation = false %>\r\n\r\n<tr><td >\r\n<% if record[\'dormicum\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Dormicum :</label> <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Pethidine :</label> <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'drithpivan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Drithpivan :</label> <v><%=record[\'drithpivan_mg\']%> mg <%=record[\'drithpivan_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Diprivan :</label> <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v>  </div>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Valium :</label> <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Buscopan :</label> <v><%=record[\'buscopan_mg\']%> mg <%=record[\'buscopan_route\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'plasil\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Plasil :</label> <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Fentanyl :</label> <v><%=record[\'fentanyl_mg\']%> mcg <%=record[\'fentanyl_routh\']%> </v>   </div>\r\n<% end%>\r\n\r\n<% if record[\'general_anesthesia\'] and record[\'general_anesthesia\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><v>General anesthesia</v>   </div>\r\n<% end%>\r\n\r\n<% if record[\'other\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Other Note :</label> <v><%=record[\'other_note\']%> </v>   </div>\r\n\r\n<% end%>\r\n</td>\r\n  </tr>\r\n\r\n\r\n<tr>\r\n<td><% unless  any_sedation %>\r\n<v>No sedation</v>\r\n<% end %>\r\n</td>\r\n</tr>\r\n</table>\r\n</p></td>\r\n </tr></table>\r\n		\r\n<hr />\r\n\r\n<h4>Scope finding</h4>\r\n<table style=\"padding-left:15px\">\r\n<tr>\r\n    <td width=\"300\">\r\n    <label>Scope pass through : </label><v><%=render_value \'scope\'%></v>\r\n    </td>\r\n    <td width=\"240\">\r\n    <label>Pocedure : </label><v><%=render_value \'procedure\'%></v>\r\n    </td>\r\n    <td><label>Diverticulum : </label><v><%=render_value \'diverticulum\'%></v></td>\r\n</tr>\r\n\r\n</table>\r\n\r\n\r\n\r\n\r\n<% if  a = record[\'procedure_other\']  and a !=\"\" %><label>Note : </label><v><%=render_value \'procedure_other\'%> </v><% end%>\r\n<p style=\"padding-left:10px\">Start at : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<p >\r\n<%\r\n    scopes = %w{rectum_scope sigmoid_scope descending_colon_scope transvers_colon_scope ascending_colon_scope cecum_scope terminal_ileum_scope}.reverse\r\n    \r\n    scopes.each_with_index do |j,index|\r\n    if scopes.size-index-1<record.scope.to_i \r\n    tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    text = \"Normal\"\r\n    tag_cls = \'\'\r\n    if render_value(tag) == \'1\'\r\n    	text =  \"Abnormal\"\r\n    	 tag_cls = \'color:red\'\r\n    end\r\n%>\r\n<p><%= j.humanize %> : <v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></p>\r\n<%\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Type:</td><td>Dx:</td><td>Morphology:</td><td>Size:</td><td>Treatment:</td><td>By:</td><td>Clip:</td><td>Patho No:</td>\r\n<td>Chromo By:</td><td>Kudo:</td><td>Sano:</td><td>NICE:</td><td>JNET:</td><td>Note:</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n      \r\n     \r\n     note =  []  \r\n     note << i[\'abnormal_note\'] if i[\'abnormal_note\'] and i[\'abnormal_note\']!=\'\'\r\n     note << \"Tattoo was done\" if i[\'tattoo\'] and i[\'tattoo\']==\'Done\'\r\n     note << i[\'complication\'] if i[\'complication\'] and i[\'complication\']!=\'none\'\r\n     \r\n      note = note.join \", \" \r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%></v></td><td><v><%=i[\'endoscopy_dx\']%></v></td><td><v><%=i[\'morphology_type\']%></v></td><td>\r\n<% if i[\'size\']==0%>\r\n<v> -</v>\r\n<% else%>\r\n<v><%=i[\'size\']%> cm.</v>\r\n<% end%>\r\n</td>\r\n<td><v><%=i[\'treatment\']%></v></td>  <td><v><%=i[\'treatment_by\']%></v> </td> <td><v><%=i[\'clip\']%></v></td>               <td><v><%=i[\'patho_number\']%></v></td>\r\n<td><v><%=i[\'chromo\']%></v></td>     <td><v><%=i[\'kudo_type\']%></v></td>     <td><v><%=i[\'sano_type\']%></v></td>          <td><v><%=i[\'nice_classification\']%></v></td>\r\n<td><v><%=i[\'jnet_class\']%></v></td><td><v><%=note%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n<hr />\r\n\r\n\r\n<h4>Note</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<% if a= record[\'scope_note\'] and a !=\"\" %><label>Note : </label><v><%=render_value \'scope_note\'%> </v><% end%>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \') if record[\'diagnosis_group\']%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endscopist : <v><%=endoscopist_1%></v></p>\r\n	\r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\">\r\n    <p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n\r\n    <%\r\n        list = record.image\r\n        \r\n        atts = models[:attachment].find(list[0...8].compact).compact\r\n        \r\n        map = {}\r\n        for i in atts\r\n            map[i.id.to_s] = i\r\n        end\r\n        atts = []\r\n        for i in list[0...8].compact\r\n            atts << map[i]\r\n        end\r\n        \r\n        \r\n        # atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>?thumb=2\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:80px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2017-08-08 07:07:15','2017-08-08 07:07:15','print_partial','*'),(3125,'print',1009,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%= render :inline=>this.print_partial, :locals=>{:this=>this} %>\r\n<script>\r\nwindow.print()\r\n</script>',NULL,NULL,NULL,'2017-08-08 07:07:30','2017-08-08 07:07:30','print','*'),(3126,'index_content',1231,4,'<%= content_for :header do  %>\r\n<%=link_to image_tag(\"/esm/cusys/mobile/colo_logo.png\", height:70 ), \"../../www/Home/index\" %> \r\n<%= image_tag \"/esm/bsh_mobile/endo/bsh_logo.jpg\", height:60 %> \r\n<% end %>\r\n',NULL,NULL,NULL,'2017-08-08 15:21:46','2017-08-08 15:21:46','index_content',''),(3127,'search',1001,3,'<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n \r\n date = Time.now\r\n date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n%>\r\n<div class=\"span12 alert\"><%=date.strftime(\"%d/%m/%Y\")%></div>\r\n\r\n\r\n<%\r\n ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n model = ehr.load_model\r\n patient_model = model[:patient]\r\n module_model = model[:patient_module]\r\n\r\n models = get_model\r\n ap_model = models[:appointment]\r\n    \r\n aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day,:status=>{\'$ne\'=>\'Cancelled\'}) \r\n \r\n patient_filter = []\r\n \r\n if request.post? and params[:search]\r\n \r\n    q = params[:search][:q]\r\n \r\n    patient_filter = patient_model.where(:hn=>q.strip).all.collect{|i| i.id}\r\n\r\n \r\n end\r\n \r\n module_map = {}\r\n module_model.where(:module_id=>aps.collect{|i| i.id}).all.collect{|i| module_map[i.module_id] = i}\r\n \r\n patient_map = {}\r\n patient_model.where(:id=>module_map.values.collect{|i| i.patient_id}).all.collect{|i| patient_map[i.id] = i}\r\n \r\n aps.collect! do |i|\r\n     \r\n appm = module_map[i.id]\r\n \r\n res = {:app=>i}\r\n \r\n if appm \r\n      p = patient_map[appm.patient_id]\r\n      res[:p] = p \r\n      next unless p\r\n      res[:name] = \"\\\\#{p.hn } &nbsp;&nbsp;&nbsp;&nbsp;\\\\#{p.prefix_name} \\\\#{p.first_name} \\\\#{p.last_name}\" .html_safe\r\n end \r\n \r\n \r\n if patient_filter.size==0 or patient_filter.index(p.id)\r\n    res\r\n else\r\n    nil\r\n end\r\n\r\n end\r\n \r\n aps.compact!\r\n\r\n%>\r\n\r\n<% if request.post? and aps.size==1%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=patient_record?id=<%=aps[0][:app].id%>\" />\r\n<center><h1>Searching ....</h1></center>\r\n<% else %>\r\n<% if aps.size!=1 %>\r\n<meta http-equiv=\"refresh\" content=\"0; url=index\" />\r\n<center><h1>Duplicate appointment!!</h1></center>\r\n\r\n\r\n<% else %>\r\n<meta http-equiv=\"refresh\" content=\"0; url=index\" />\r\n<center><h1>Patient not found!!</h1></center>\r\n\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2017-08-09 09:07:53','2017-08-09 09:07:53','search',''),(3128,'status_board',1229,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Patient Board</title>\r\n<%=include_header%>\r\n<style>\r\n .bbody{ width:900px; margin-left:auto; margin-right:auto;}\r\n .bhead{text-align:center}\r\n</style>\r\n<script>\r\n        function update_time(){\r\n        \r\n         var d = new Date();\r\n    document.getElementById(\"demo\").innerHTML = d.toLocaleTimeString();\r\n}\r\n</script>\r\n</head>\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    date = Time.now \r\n    \r\n    \r\n    apps = models[:appointment].where(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day).all\r\n\r\n    groups = {}\r\n    total_appointed = apps.size\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    \r\n    \r\n    # colos = models[:colonoscopy].where(\r\n    \r\n    \r\n    \r\n    \r\n    for i in apps\r\n    \r\n    s = i.status\r\n    groups[s] = [] unless groups[s]\r\n    groups[s] << i\r\n    \r\n    \r\n    end\r\n    \r\n    appm = {}\r\n    \r\n    module_model.where(:module_id=>apps.collect{|i| i.id} ).all.each do |i|\r\n    \r\n    appm[i.module_id] = i\r\n    \r\n    end\r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n\r\n\r\n    \r\n    colom =  models[:colonoscopy].find(module_model.where(:parent_id=>appm.values.collect{|i| i.id}, :module_name=>\"\\\\#{@current_project.name}#colonoscopy\").all.collect{|i| i.module_id})\r\n    \r\n    scopes = []\r\n    \r\n    coloms = {}\r\n    colom.each do |i|\r\n         scope_list.each do |j|\r\n            coloms[i.id] = [] unless coloms[i.id]\r\n            coloms[i.id] += i[j] if i[j]\r\n            scopes += coloms[i.id] if coloms[i.id]\r\n         end\r\n    end\r\n    scm = {}\r\n    \r\n    models[:colonoscopy_scope].find(scopes).each do |i|\r\n    # scm[i.id.to_s] = i.finding\r\n    scm[i.id.to_s] = i.abnormal_type\r\n    \r\n    end\r\n    \r\n    l = {}\r\n    \r\n  \r\n\r\n    # models[:colonoscopy_scope].find(colom)\r\n    \r\n    \r\n    \r\n    \r\n    # abnormal_type\r\n    total_register =0\r\n    total_register += groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    total_register += groups[\'Processing\'].size if groups[\'Processing\']\r\n    total_register += groups[\'Completed\'].size if groups[\'Completed\']\r\n    \r\n    \r\n    \r\n    total_register += groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    \r\n    total_complete = 0 \r\n    total_complete += groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    total_complete += groups[\'Completed\'].size if groups[\'Completed\']\r\n    \r\n    total_cancer = 0\r\n    total_polyp  = 0 \r\n    total_waiting = 0 \r\n    total_waiting = groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    \r\n   \r\n    # coloms.each_pair do |c,l|\r\n         \r\n    # end\r\n    \r\n    data = []\r\n    \r\n     coloms.keys.each do |k|\r\n        v = coloms[k].collect{|i| scm[i.to_s] }\r\n        l[k.to_s] = v\r\n\r\n        total_cancer+=1 if v and v.index(\'Mass\') \r\n        total_polyp+=1 if v and v.index(\'Polyp\')\r\n\r\n    end\r\n\r\n    \r\n\r\n    mm = {}\r\n    mm2 = {}\r\n    module_model.where(:module_id=>coloms.keys).all.each do|i|\r\n        mm[i.module_id.to_s] = i.patient_id\r\n        mm2[i.module_id.to_s] = i.id\r\n    end\r\n    \r\n    pm = {}\r\n    patient_model.find(mm.values).each do |i|\r\n      pm[i.id] = i \r\n    end\r\n    \r\n    # total_register =1 if total_register ==0 \r\n    \r\n\r\n%>\r\n\r\n<body style=\"padding:20px\">\r\n<style>\r\n    h2{font-size:1.5em};\r\n</style>\r\n<div class=\"bbody\" style=\"font-size:12px\">\r\n\r\n<div class=\"bhead\">\r\n<span style=\"float:left;\" ><img src=\"/esm/bsh_mobile/endo/bsh_logo_only.jpeg\" style=\"width:100px\" /></span>\r\n<span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" style=\"width:100px\" /></span>\r\n  <h2>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก\r\n  โรงพยาบาลพุทธโสธร  <br />ร่วมกับ <br /> ห้องส่องกล้อง Surgical Endoscopy โรงพยาบาลจุฬาลงกรณ์\r\n  </h2><hr />\r\n<h1  style=\"color:blue\"> <i>วันที่ <%=Time.now.strftime(\"%d %B %Y\")%> \r\n    \r\n     <span id=\"demo\"></span></i>\r\n</h1>\r\n\r\n\r\n\r\n<h3>\r\n\r\n<br/></h3>\r\n<table style=\"width:700px; margin-left:auto; margin-right:auto; font-size:2em;\" cellpadding=\"20\">\r\n<tr><td align=\"left\">\r\nจำนวนผู้ป่วยที่ลงทะเบียนวันนี้</td>\r\n<td align=\"left\"><%=total_register%> คน\r\n    \r\n\r\n    \r\n</td></tr>\r\n<!--\r\n<tr><td align=\"left\">จำนวนผู้ป่วยที่ส่องกล้องอยู่\r\n</td>\r\n<td align=\"left\"><%=groups[\'Processing\'].size if groups[\'Processing\']%> คน\r\n    \r\n</td></tr>\r\n-->\r\n<%\r\n total_register = 1 if total_register==0\r\n%>\r\n<tr><td align=\"left\">จำนวนผู้ป่วยที่ส่องกล้องแล้ว</td> \r\n<td align=\"left\"><%=total_complete%> คน\r\n        <%=total_complete*100/total_register%>%\r\n</td></tr>\r\n<tr><td align=\"left\">จำนวนผู้ป่วยที่มี Cancer</td> \r\n<td align=\"left\"><%=total_cancer%> คน \r\n     <%=total_cancer*100/total_register%>%\r\n    \r\n</td></tr>\r\n<tr><td align=\"left\">จำนวนผู้ป่วยที่มี Polyp</td>\r\n  <td align=\"left\"><%=total_polyp%> คน \r\n           <%=total_polyp*100/total_register%>%\r\n\r\n\r\n  </td></tr>\r\n<tr><td align=\"left\">จำนวนผู้ป่วยที่รอส่องกล้อง</td> \r\n<td align=\"left\"><%=total_waiting%> คน\r\n       \r\n\r\n\r\n</td></tr>\r\n<tr><td align=\"left\">จำนวนผู้ป่วยที่นัดมาวันนี้</td> \r\n<td align=\"left\"><%=total_appointed%> คน\r\n              \r\n\r\n\r\n</td></tr>\r\n</table>\r\n<br/><br/><br/>\r\n<table border=\"1\" width=\"800\" style=\"margin-left:auto;margin-right:auto\">\r\n<% \r\n    index = 0 \r\n    for i in l.keys \r\n    v = l[i]\r\n    m = mm[i]\r\n    p = pm[m]\r\n    index+=1\r\n%>\r\n    <tr>\r\n    <td><%=index%></td>\r\n    <td><%=p.first_name%> <%=p.last_name%> </td>\r\n    <td><%=p.hn%></td>\r\n    \r\n    <td><%=v.join%></td>        \r\n    \r\n        <td><%=link_to \"Show\", \"../Colonoscopy/show?id=\\\\#{mm2[i]}\" %></td>\r\n    </tr>\r\n    \r\n    <% end %>\r\n</table>\r\n\r\n<script>\r\n\r\n        \r\n\r\n     var time = new Date().getTime();\r\n     $(document.body).bind(\"mousemove keypress\", function(e) {\r\n         time = new Date().getTime();\r\n     });\r\n     \r\n     setInterval(update_time,1000)\r\n\r\n     function refresh() {\r\n         if(new Date().getTime() - time >= 30000) \r\n             window.location.reload(true);\r\n         else \r\n             setTimeout(refresh, 30000);\r\n     }\r\n\r\n     setTimeout(refresh, 30000);\r\n</script>\r\n\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2017-08-10 15:57:39','2017-08-10 15:57:39','status_board',''),(3129,'print_sticker',1008,3,'<html>\r\n<head>\r\n    <%=include_header%>\r\n</head>\r\n<body>\r\n<%\r\n   \r\n   if params[:queue]\r\n   \r\n   require \'task\'\r\n   t = Task.enqueue params\r\n   \r\n%>\r\nSending ....\r\n<script>\r\n\r\n<% unless params[:return] %>\r\nsetTimeout(\"window.close();\",1000);\r\n<% else %>\r\nwindow.location = \"<%= params[:return].html_safe %>\";\r\n<% end %>\r\n</script>\r\n\r\n<% else %>\r\n<script>\r\n    function wrist_refresh(queue){\r\n        var url = window.location.href;    \r\n        url += \'&queue=\'+queue\r\n        window.location.href = url;\r\n    }\r\n</script>\r\n\r\n<div class=\"row-fluid\" style=\"border:0px solid\">\r\n<div class=\"span3\">&nbsp;</div>\r\n<div class=\"span4\" >\r\n        <h1>กรุณาเลือกเครื่องพิมพ์ wristband printer</h1>\r\n        <div style=\"font-size:1.3em\">\r\n        \r\n        <div class=\"row-fluid\">\r\n       <a href=\"javascript:wrist_refresh(\'esm-pi\')\" class=\"btn btn-success span6\"> ห้องเตรียมลำไส้  </a>\r\n  \r\n       <a href=\"javascript:wrist_refresh(\'esm-pi-2\')\" class=\"btn btn-success span6\"> ห้องส่องกล้อง </a>\r\n       </div>\r\n      </div>\r\n</div>\r\n</div>\r\n\r\n\r\n<% end%>\r\n</body>\r\n</html>',NULL,NULL,NULL,'2017-08-11 14:43:55','2017-08-11 14:43:55','print_sticker',''),(3131,'patient_report',1229,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Patient Report</title>\r\n<%=include_header%>\r\n<style>\r\n .bbody{ width:100%; margin-left:auto; margin-right:auto;}\r\n .bhead{text-align:center}\r\n  table {\r\n    border-width: thin;\r\n    border-spacing: 1px;\r\n    border-style: none;\r\n    border-color: black;\r\n    border-collapse: collapse;\r\n    font-size:0.6em;\r\n}\r\ntd {padding-left:3px;}\r\n/*.printonly{display:none;visibility:hidden;}*/\r\n@media print{\r\n    .pagebreak {page-break-before: always;}\r\n    @page {size: landscape}\r\n    /*.printonly{display:inline;visibility:visible;}*/\r\n}\r\n</style>\r\n</head>\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    params[:date]  = \"13/8/2017\" unless params[:date]\r\n    t = params[:date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    date = Date.new t[0],t[1],t[2]\r\n    \r\n    \r\n    \r\n    stop_date = date\r\n    \r\n    if params[:stop_date]\r\n    t = params[:stop_date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    stop_date = Date.new t[0],t[1],t[2]\r\n    end\r\n\r\n\r\n    apps = models[:appointment].where(:date.gte=>date.at_beginning_of_day,:date.lt=>stop_date.end_of_day).all\r\n\r\n\r\n\r\n    groups = {}\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    \r\n    \r\n    # colos = models[:colonoscopy].where(\r\n    \r\n    \r\n    \r\n    \r\n    for i in apps\r\n    \r\n    s = i.status\r\n    groups[s] = [] unless groups[s]\r\n    groups[s] << i\r\n    \r\n    \r\n    end\r\n    \r\n    appm = {}\r\n    \r\n    module_model.where(:module_id=>apps.collect{|i| i.id} ).all.each do |i|\r\n    \r\n    appm[i.module_id] = i\r\n    \r\n    end\r\n    \r\n    \r\n    screen_map = {}\r\n    screen_p = {}\r\n    screen_r = {}\r\n    screen_m = module_model.where(:patient_id=>appm.values.collect{|i| i.patient_id}, :module_name=>\"\\\\#{@current_project.name}#screening\").all\r\n    screen_m.each do |i|\r\n        screen_map[i.patient_id] = i.module_id \r\n    end\r\n    \r\n    screens = models[:screening].find(screen_m.collect{|i| i.module_id})\r\n    \r\n   \r\n    for i in screens\r\n        \r\n        screen_r[i.id] =  i\r\n        \r\n    end\r\n   \r\n \r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n\r\n    colo_m = module_model.where(:parent_id=>appm.values.collect{|i| i.id}, :module_name=>\"\\\\#{@current_project.name}#colonoscopy\").all\r\n    colo_p = {}\r\n    colo_mm = {}\r\n    colo_m.each do |i|\r\n        colo_p[i.patient_id] = i.module_id \r\n        colo_mm[i.module_id] = i.parent_id\r\n    end\r\n    \r\n    \r\n\r\n    \r\n    \r\n    colos =  models[:colonoscopy].find(colo_m.collect{|i| i.module_id})\r\n    colomap = {}\r\n    scopes = []\r\n    \r\n    coloms = {}\r\n    colos.each do |i|\r\n         \r\n         colomap[i.id] = i\r\n         scope_list.each do |j|\r\n            coloms[i.id] = [] unless coloms[i.id]\r\n            coloms[i.id] += i[j] if i[j]\r\n           \r\n            scopes += coloms[i.id] if coloms[i.id]\r\n         end\r\n    end\r\n    scm = {}\r\n    \r\n    models[:colonoscopy_scope].find(scopes).each do |i|\r\n    scm[i.id] = i\r\n    end\r\n    \r\n    l = {}\r\n    \r\n  \r\n \r\n    \r\n    # models[:colonoscopy_scope].find(colom)\r\n    \r\n    \r\n    \r\n \r\n    \r\n    \r\n    # abnormal_type\r\n    total_register =0\r\n    total_register += groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    total_register += groups[\'Processing\'].size if groups[\'Processing\']\r\n    total_register += groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    \r\n    total_complete = 0 \r\n    total_complete = groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    total_cancer = 0\r\n    total_polyp  = 0 \r\n    total_waiting = 0 \r\n    total_waiting = groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    \r\n   \r\n    # coloms.each_pair do |c,l|\r\n         \r\n    # end\r\n    \r\n    data = []\r\n    \r\n    coloms.keys.each do |k|\r\n        v = coloms[k].collect{|i| scm[i] }\r\n        l[k.to_s] = v\r\n        total_cancer+=1 if v and v.index(\'Cancer\') \r\n        total_polyp+=1 if v and v.index(\'Polyp\')\r\n\r\n    end\r\n\r\n    mm = {}\r\n    mm2 = {}\r\n    module_model.where(:module_id=>coloms.keys).all.each do|i|\r\n        mm[i.module_id.to_s] = i.patient_id\r\n        mm2[i.module_id.to_s] = i.id\r\n    end\r\n    \r\n    pm = {}\r\n    patient_model.find(mm.values).each do |i|\r\n      pm[i.id] = i \r\n    end\r\n    \r\n    providers = {}\r\n    models[:provider].all.each do |i|\r\n        providers[i.id] = i.name \r\n    end\r\n    \r\n\r\n    # scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n#     1|Rectum\r\n# 2|Sigmoid\r\n# 3|Descending colon\r\n# 4|Transvers colon\r\n# 5|Ascending colon\r\n# 6|Cecum\r\n# 7|Terminal ileum\r\n    \r\n    scope_map = {}\r\n    scope_list.each_with_index do |i,index|\r\n        scope_map[(index+1).to_s] = i.split(\"_\")[0].humanize\r\n    end\r\n    \r\n    gender_map = {\'1\'=>\'ชาย\', \'2\'=>\'หญิง\'}\r\n\r\n%>\r\n\r\n<body>\r\n\r\n<div class=\"bbody\" style=\"font-size:14px\">\r\n\r\n<div class=\"bhead\">\r\n \r\n\r\n\r\n\r\n\r\n<table id=\"table\" width=\"100%\" border=\"0\" cellpadding=\"1\" cellspacing=\"1\" style=\"margin-left:auto;margin-right:auto;font-size:0.6em\">\r\n<tr>\r\n  <th colspan=\"19\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/bsh_mobile/endo/bsh_logo_only.jpeg\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h2>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลพุทธโสธร ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์\r\n  </h2>\r\n  <h3>\r\n  <%=params[:name] if params[:name] %>\r\n  วันที่\r\n  <%=params[:date]%>\r\n  <%=\"- \"+params[:stop_date] if params[:stop_date]&&(params[:stop_date]!=params[:date])%>\r\n  ผู้ป่วยทั้งหมด\r\n  <span id=\"sum_patient\"></span>\r\n  คน \r\n  <% unless params[:name] %>\r\n  พบ Patho \r\n  <span id=\"sum_patient_patho\"></span>\r\n  คน \r\n  รวม \r\n  <span id=\"sum_patho\"></span>\r\n  ชิ้น\r\n  <% end %>\r\n  </h3>\r\n<h1>&nbsp;</h1></th>\r\n  </tr>\r\n</table>\r\n<table id=\"table\" width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\"margin-left:auto;margin-right:auto;\">\r\n<tr>\r\n    <th width=\"10px\">No.</th>\r\n    <th width=\"100px\">ชื่อ-สกุล</th>\r\n    <th width=\"20px\">HN</th>\r\n    <th width=\"40px\">เลขบัตรประชาชน</th>\r\n    <th width=\"20px\">Gender</th>\r\n    <th width=\"20px\">อายุ</th>\r\n    <th width=\"40px\">วันที่ทำ</th>\r\n    <th width=\"30px\">อำเภอ</th>\r\n    <th width=\"50px\">Tel</th>\r\n    <th width=\"20px\">Fit test</th>\r\n    <th width=\"100px\">Diagnosis</th>\r\n    <th width=\"80px\">Bowel<br/>preparation</th>\r\n    <th width=\"60px\">กล้อง</th>\r\n    <th width=\"40px\">ส่องถึง</th>\r\n    <th width=\"10px\">Patho</th>\r\n    <th width=\"100px\">แพทย์1</th>\r\n    <th width=\"100px\">แพทย์2</th>\r\n    <th width=\"100px\">พยาบาล</th>\r\n    <th width=\"10px\">Action</th>\r\n</tr>\r\n<% \r\n    index = 0 \r\n    sum_patho = 0\r\n    patient_patho = 0 \r\n    \r\n    list = []\r\n    for i in l.keys \r\n    v = l[i]\r\n    m = mm[i]\r\n    p = pm[m]\r\n    index+=1\r\n    \r\n    r = colomap[colo_p[p.id]]\r\n    lesion = coloms[r.id]\r\n    \r\n    age = 0 \r\n    \r\n    age = ((Time.now - p.birth_date.to_datetime)/3600/365/24).to_i if p.birth_date\r\n    age_class =\"black\"\r\n    age_class = \"red\" if age < 40 or age > 100\r\n    \r\n    sc = scope_map[r.scope]\r\n    \r\n    patho = 0 \r\n   \r\n    if coloms[r.id]\r\n    for x in coloms[r.id]\r\n        patho+=1 if scm[x] and scm[x].patho_number.to_i >0\r\n    end\r\n    end\r\n    \r\n    s = \'-\'\r\n    \r\n    if s = screen_r[screen_map[p.id]]\r\n        s = s.fit_test\r\n    end\r\n    \r\n    line = {:p=>p, :date=>params[:date], :r=>r,  :sc=>sc, :patho=>patho,:age=>age,:s=>s }\r\n    list << line\r\nend\r\nindex = 0\r\n\r\n    list.sort! {|b,a| \r\n        a[:patho]<=>b[:patho]\r\n    }\r\n    \r\n    if params[:poor]\r\n       list.collect!{|i| i if i[:r].quality_of_preparate ==\'Poor\' }.compact!\r\n    end\r\n    \r\n    \r\n    \r\n    for i in list.sort{|a,b| a[:p].first_name <=> b[:p].first_name } \r\n    \r\n    p = i[:p]\r\n    date = i[:date]\r\n    r = i[:r]\r\n    patho = i[:patho]\r\n    sc = i[:sc]\r\n    index+=1\r\n    age = i[:age]\r\n    \r\n    \r\n   s = i[:s]\r\n   \r\n   sum_patho += patho\r\n   patient_patho+=1 if patho.to_i>0\r\n    \r\n%>\r\n\r\n    <tr style=\"color:<%=age_class%>\">\r\n    <td><%=index%></td>\r\n    <td align=\"left\"><%=link_to \"\\\\#{p.first_name} \\\\#{p.last_name}\", \"../../www/Patient/edit?id=\\\\#{p.id}\",:target=>\"_blank\"%> </td>\r\n    <td><%=p.hn%></td>\r\n    <td><%=p.public_id%></td>\r\n    <td><%=gender_map[p.gender]%></td>\r\n    <td ><%=\"\\\\#{age} ปี \"%> \r\n    <%=p.birth_date if age_class==\'red\'%></td>  \r\n<td><%=params[:date]%></td>\r\n<td align=\"left\"><%=p.contact_amphur%></td>\r\n\r\n\r\n<td><%=p.mobile%></td>\r\n\r\n<td><%=s%></td>\r\n<td align=\"left\"><%=r.diagnosis_group%></td>\r\n<td><%=r.quality_of_preparate%></td>\r\n<td align=\"left\"><%=r.colonoscope%></td>\r\n<td align=\"left\"><%=sc%></td>\r\n<td><%=patho %><%= %></td>\r\n<td align=\"left\"><%=providers[r.endoscopist_1]%></td>\r\n<td align=\"left\"><%=providers[r.endoscopist_2]%></td>\r\n<td align=\"left\"><%=providers[r.nurse]%></td>\r\n        <td><%=link_to \"Show\", \"../Colonoscopy/show?id=\\\\#{colo_mm[r.id]}\" %></td>\r\n    </tr>\r\n<% if index==30||(index>30&&index%30==0) %>\r\n</table>\r\n<div class=\"pagebreak\"></div>\r\n<table id=\"table\" width=\"100%\"  border=\"1\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-left:auto;margin-right:auto\">\r\n<tr class=\"printonly\">\r\n    <th width=\"10px\">No.</th>\r\n    <th width=\"100px\">ชื่อ-สกุล</th>\r\n    <th width=\"20px\">HN</th>\r\n    <th width=\"40px\">เลขบัตรประชาชน</th>\r\n    <th width=\"20px\">Gender</th>\r\n    <th width=\"20px\">อายุ</th>\r\n    <th width=\"40px\">วันที่ทำ</th>\r\n    <th width=\"30px\">อำเภอ</th>\r\n    <th width=\"50px\">Tel</th>\r\n    <th width=\"20px\">Fit test</th>\r\n    <th width=\"100px\">Diagnosis</th>\r\n    <th width=\"80px\">Bowel<br/>preparation</th>\r\n    <th width=\"60px\">กล้อง</th>\r\n    <th width=\"40px\">ส่องถึง</th>\r\n    <th width=\"10px\">Patho</th>\r\n    <th width=\"100px\">แพทย์1</th>\r\n    <th width=\"100px\">แพทย์2</th>\r\n    <th width=\"100px\">พยาบาล</th>\r\n    <th width=\"10px\">Action</th>\r\n</tr>\r\n<% end %>    \r\n    <% end %>\r\n</table>\r\n\r\n<script>\r\n$(\"#sum_patient\").html(<%=index%>);\r\n$(\"#sum_patho\").html(<%=sum_patho%>);\r\n$(\"#sum_patient_patho\").html(<%=patient_patho%>);\r\n\r\n</script>\r\n\r\n<%#appm.inspect %>\r\n\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n<%= render :inline=>this.table_export %>\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2017-08-12 05:08:54','2017-08-12 05:08:54','patient_report',''),(3132,'create',1023,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n\r\n  models = get_model \r\n   \r\n  model = models[:pathology]\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    \r\n    \r\n    \r\n    \r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    \r\n    cpos = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n    gpos = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n    \r\n    \r\n    mc = @module_model.where(:parent_id=>@appointment_module.id,:module_name=>\"\\\\#{@current_project.name}#colonoscopy\").first\r\n    if mc\r\n    colonoscopy_record =  models[:colonoscopy].where(:id=>mc.module_id).first\r\n    if colonoscopy_record\r\n        list = []\r\n        cpos.each_with_index do |i,index|\r\n        for j in colonoscopy_record[i.to_sym]  \r\n            m = models[:colonoscopy_scope].find j\r\n            if m.patho_number and m.patho_number.to_i > 0 \r\n            location = nil\r\n            location = cpos[index].humanize if cpos[index] \r\n            location = location.split[0..-2].join(\" \") if location\r\n            mpc =  models[:patho_colono].create :location=>location, :patho_no=>m.patho_number, :endodx=>m.endoscopy_dx, :patho_image=>m.image\r\n            list << mpc\r\n            end\r\n        end\r\n        end\r\n        list.collect!{|i| i.id}\r\n        record.colono_pathology = list\r\n    end\r\n    end\r\n    \r\n    mc = @module_model.where(:parent_id=>@appointment_module.id,:module_name=>\"\\\\#{@current_project.name}#gastroscopy\").first\r\n    if mc\r\n    gastroscopy_record =  models[:gastroscopy].where(:id=>mc.module_id).first\r\n    if gastroscopy_record\r\n    \r\n         list = []\r\n        gpos.each_with_index do |i,index|\r\n        if gastroscopy_record[i.to_sym]\r\n        for j in gastroscopy_record[i.to_sym]  \r\n            m = models[:gastroscopy_scope].find j\r\n            if m.patho_number and m.patho_number.to_i > 0 \r\n     \r\n  \r\n            mpc =  models[:patho_gastro].create :location=>gpos[index].humanize, :patho_no=>m.patho_number, :endodx=>m.endoscopy_dx, :patho_image=>m.image\r\n            list << mpc\r\n            end\r\n        end\r\n        else\r\n        end\r\n        end\r\n        list.collect!{|i| i.id}\r\n        record.gastro_pathology = list\r\n\r\n    end\r\n    end\r\n    \r\n\r\n    end\r\n\r\n%>\r\n\r\n<% if record.save \r\n\r\n t = Time.now\r\n \r\n\r\n m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>t.strftime(\"%Y-%m-%d\"),:time=>t.strftime(\"%H:%M\"),:parent_id=>params[:parent_id],:ref_number=>\'new\'\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    locker.destroy if locker\r\n    \r\n%>\r\n<h1>Please wait...</h1>\r\n<meta http-equiv=\"refresh\" content=\"0; url=<%=return_url%>\" />\r\n<% end %>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2017-08-12 06:11:47','2017-08-12 06:11:47','create','user'),(3133,'patient_patho',1229,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Patient Report</title>\r\n<%=include_header%>\r\n<style>\r\n .bbody{ width:100%; margin-left:auto; margin-right:auto;}\r\n .bhead{text-align:center}\r\n table {\r\n    border-width: thin;\r\n    border-spacing: 0.5px;\r\n    border-style: none;\r\n    border-color: black;\r\n    border-collapse: collapse;\r\n    font-size:0.7em;\r\n    \r\n}\r\ntd {padding-left:3px;}\r\n\r\n@media print{\r\n    #printout{\r\n        visibility:visible;\r\n    }\r\n    .pagebreak {page-break-before: always;}\r\n}\r\n\r\n\r\n</style>\r\n\r\n\r\n\r\n\r\n</head>\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    params[:date]  = \"12/8/2017\" unless params[:date]\r\n    t = params[:date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    date = Date.new t[0],t[1],t[2]\r\n    \r\n    \r\n    stop_date = date\r\n    \r\n    if params[:stop_date]\r\n    t = params[:stop_date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    stop_date = Date.new t[0],t[1],t[2]\r\n    end\r\n\r\n\r\n    apps = models[:appointment].where(:date.gte=>date.at_beginning_of_day,:date.lt=>stop_date.end_of_day).all\r\n\r\n    groups = {}\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    \r\n    \r\n    # colos = models[:colonoscopy].where(\r\n    \r\n    #MIT\r\n    map_app = {}\r\n    \r\n    for i in apps\r\n    \r\n    \r\n    s = i.status\r\n    groups[s] = [] unless groups[s]\r\n    groups[s] << i\r\n    \r\n    #MIT\r\n    map_app[i.id] = i\r\n    \r\n    \r\n    end\r\n    \r\n    appm = {}\r\n    \r\n    #MIT\r\n    rev_appm = {}\r\n    \r\n    module_model.where(:module_id=>apps.collect{|i| i.id} ).all.each do |i|\r\n    \r\n    appm[i.module_id] = i\r\n    \r\n    #MIT\r\n    rev_appm[i.id] = i.module_id\r\n    \r\n    \r\n    end\r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n\r\n    colo_m = module_model.where(:parent_id=>appm.values.collect{|i| i.id}, :module_name=>\"\\\\#{@current_project.name}#colonoscopy\").all\r\n    colo_p = {}\r\n    colo_mm = {}\r\n    colo_m.each do |i|\r\n        colo_mm[i.module_id] = i\r\n        colo_p[i.patient_id] = i.module_id \r\n    end\r\n    \r\n    \r\n    colos =  models[:colonoscopy].find(colo_m.collect{|i| i.module_id})\r\n    colomap = {}\r\n    scopes = []\r\n    \r\n    coloms = {}\r\n    locmap = {}\r\n    colos.each do |i|\r\n         \r\n         colomap[i.id] = i\r\n         scope_list.each do |j|\r\n            coloms[i.id] = [] unless coloms[i.id]\r\n            coloms[i.id] += i[j] if i[j]\r\n            for x in i[j]\r\n                locmap[x.to_s] = j\r\n            end\r\n            \r\n            scopes += coloms[i.id] if coloms[i.id]\r\n         end\r\n    end\r\n\r\n    scm = {}\r\n    \r\n    models[:colonoscopy_scope].find(scopes).each do |i|\r\n    scm[i.id.to_s] = i\r\n\r\n    end\r\n    \r\n    l = {}\r\n    \r\n \r\n  \r\n \r\n    \r\n    # models[:colonoscopy_scope].find(colom)\r\n    \r\n    \r\n    \r\n \r\n    \r\n    \r\n    # abnormal_type\r\n    total_register =0\r\n    total_register += groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    total_register += groups[\'Processing\'].size if groups[\'Processing\']\r\n    total_register += groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    \r\n  total_complete = 0 \r\n    total_complete = groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    total_cancer = 0\r\n    total_polyp  = 0 \r\n    total_waiting = 0 \r\n    total_waiting = groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    \r\n   \r\n    # coloms.each_pair do |c,l|\r\n         \r\n    # end\r\n    \r\n    data = []\r\n    \r\n\r\n    \r\n     coloms.keys.each do |k|\r\n        v = coloms[k].collect{|i| scm[i] }\r\n        l[k.to_s] = v\r\n        total_cancer+=1 if v and v.index(\'Cancer\') \r\n        total_polyp+=1 if v and v.index(\'Polyp\')\r\n\r\n    end\r\n\r\n    mm = {}\r\n    mm2 = {}\r\n    module_model.where(:module_id=>coloms.keys).all.each do|i|\r\n        mm[i.module_id.to_s] = i.patient_id\r\n        mm2[i.module_id.to_s] = i.id\r\n    end\r\n    \r\n    pm = {}\r\n    patient_model.find(mm.values).each do |i|\r\n      pm[i.id] = i \r\n    end\r\n    \r\n    providers = {}\r\n    models[:provider].all.each do |i|\r\n        providers[i.id] = i.name \r\n    end\r\n    \r\n\r\n    # scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n#     1|Rectum\r\n# 2|Sigmoid\r\n# 3|Descending colon\r\n# 4|Transvers colon\r\n# 5|Ascending colon\r\n# 6|Cecum\r\n# 7|Terminal ileum\r\n    \r\n    scope_map = {}\r\n    scope_list.each_with_index do |i,index|\r\n        scope_map[(index+1).to_s] = i.split(\"_\")[0].humanize\r\n    end\r\n    \r\n    gender_map = {\'1\'=>\'ชาย\', \'2\'=>\'หญิง\'}\r\n\r\n%>\r\n\r\n<body>\r\n\r\n<table id=\"table\" width=\"100%\"  border=\"1\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-left:auto;margin-right:auto\">\r\n<tr style=\"border-top-color:white;border-left-color:white;border-right-color:white\">\r\n  <th colspan=\"16\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/bsh_mobile/endo/bsh_logo_only.jpeg\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h3>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลพุทธโสธร ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์.\r\n  </h3>\r\n  <h3>\r\n  Pathology Report\r\n  วันที่\r\n  <%=params[:date]%>\r\n  <%=\"- \"+params[:stop_date] if params[:stop_date]&&(params[:stop_date]!=params[:date])%>\r\n  ผู้ป่วย\r\n  <span id=\"sum_patient\"></span>\r\n  คน\r\n  Patho รวม\r\n  <span id=\"sum_patho\"></span>\r\n  ชิ้น\r\n  </h3>\r\n<br>\r\n<!--<h3>&nbsp;</h3>-->\r\n    \r\n</th>\r\n  </tr>\r\n<tr>\r\n    <th width=\"10px\">No.</th>\r\n    <th width=\"150px\">ชื่อ-สกุล</th>\r\n    <th width=\"50px\">HN</th>\r\n    <th width=\"80px\">เลขบัตรประชาชน</th>\r\n    <th width=\"25px\">Gender</th>\r\n    <th width=\"25px\">อายุ</th>\r\n    <th width=\"60px\">วันที่ทำ</th>\r\n    <th width=\"30px\">#Patho</th>\r\n    <th>Finding</th>  \r\n</tr>\r\n\r\n<%  \r\n    index = 0\r\n    sum_patho = 0\r\n    colos.each do |i|\r\n         \r\n#   colomap[i.id] = i\r\n\r\n    xx = colo_mm[i.id]\r\n    slist = coloms[i.id]        \r\n    p = pm[xx.patient_id]     \r\n\r\n  age = 0 \r\n    \r\n    age = ((Time.now - p.birth_date.to_datetime)/3600/365/24).to_i if p.birth_date\r\n    age_class =\"black\"\r\n    age_class = \"red\" if age < 40 or age > 100\r\n    show = false\r\n    for j in slist \r\n        s = scm[j.to_s]\r\n        \r\n        if  s and s.patho_number and s.patho_number.to_i > 0  \r\n         show =true\r\n        end\r\n        \r\n    end\r\n    if show\r\n         index+=1\r\n%>\r\n<tr>\r\n\r\n<td><%=index%></td>\r\n\r\n<td><%=p.first_name%> <%=p.last_name%></td>\r\n\r\n<td><%=p.hn%></td>\r\n\r\n<td><%=p.public_id%></td>\r\n\r\n  <td><%=gender_map[p.gender]%></td>\r\n    <td><span style=\"display:inline\"><%=\"\\\\#{age} ปี \"%></span> \r\n    <%=p.birth_date if age_class==\'red\'%></td> \r\n<td><%=map_app[rev_appm[xx.parent_id]].date.strftime(\"%d/%m/%Y\")\r\n #MIT\r\n%></td>\r\n\r\n\r\n<%\r\nsslist = []\r\n    \r\nfor j in slist \r\n    s = scm[j.to_s]\r\n    \r\n    loc = nil\r\n    \r\n    loc = locmap[s.id.to_s].split(\'_\')[0].humanize if s and locmap[s.id.to_s]\r\n    \r\n    if  s and s.patho_number and s.patho_number.to_i > 0  \r\n   \r\n\r\n    \r\n    sslist << \"\\\\#{s.patho_number}.\\\\#{s.abnormal_type}:\\\\#{loc}\"\r\n    \r\n\r\n\r\n    end  \r\n    \r\nend\r\n\r\nsum_patho+=sslist.size\r\n%>\r\n\r\n<%\r\nstext = sslist.sort.join(\", \")\r\n%>\r\n<td style=\"text-align:center;\"><%=sslist.size%></td>\r\n\r\n<td><%=stext%></td>\r\n\r\n\r\n</tr>\r\n\r\n<% if index==30||(index>35&&index%35==0) %>\r\n</table>\r\n<div class=\"pagebreak\">\r\n<table id=\"table\" width=\"100%\"  border=\"1\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-left:auto;margin-right:auto\">\r\n<tr id=\"printout\">\r\n    <th width=\"10px\">No.</th>\r\n    <th width=\"150px\">ชื่อ-สกุล</th>\r\n    <th width=\"50px\">HN</th>\r\n    <th width=\"80px\">เลขบัตรประชาชน</th>\r\n    <th width=\"25px\">Gender</th>\r\n    <th width=\"25px\">อายุ</th>\r\n    <th width=\"60px\">วันที่ทำ</th>\r\n    <th width=\"30px\">#Patho</th>\r\n    <th>Finding</th>\r\n</tr>\r\n<% end %>\r\n<% end %>\r\n\r\n\r\n         \r\n         \r\n<% end %>\r\n\r\n</table>\r\n\r\n<script>\r\n$(\"#sum_patient\").html(<%=index%>);\r\n$(\"#sum_patho\").html(<%=sum_patho%>);\r\n</script>\r\n<%= render :inline=>this.table_export %>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2017-08-12 08:12:58','2017-08-12 08:12:58','patient_patho',''),(3134,'patient_polyp_cancer',1229,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Patient Report</title>\r\n<%=include_header%>\r\n<style>\r\n .bbody{ width:100%; margin-left:auto; margin-right:auto;}\r\n .bhead{text-align:center}\r\n  table {\r\n    border-width: thin;\r\n    border-spacing: 1px;\r\n    border-style: none;\r\n    border-color: black;\r\n    border-collapse: collapse;\r\n    font-size:0.6em;\r\n}\r\n@media print{\r\n    .pagebreak {page-break-before: always;}\r\n    @page {size: landscape}\r\n}\r\n</style>\r\n</head>\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    params[:date]  = \"13/8/2016\" unless params[:date]\r\n    t = params[:date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    date = Date.new t[0],t[1],t[2]\r\n    \r\n    \r\n      \r\n    stop_date = date\r\n    \r\n    if params[:stop_date]\r\n    t = params[:stop_date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    stop_date = Date.new t[0],t[1],t[2]\r\n    end\r\n\r\n\r\n    apps = models[:appointment].where(:date.gte=>date.at_beginning_of_day,:date.lt=>stop_date.end_of_day).all\r\n\r\n\r\n\r\n    groups = {}\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    \r\n    \r\n    # colos = models[:colonoscopy].where(\r\n    \r\n    \r\n    \r\n    \r\n    for i in apps\r\n    \r\n    s = i.status\r\n    groups[s] = [] unless groups[s]\r\n    groups[s] << i\r\n    \r\n    \r\n    end\r\n    \r\n    appm = {}\r\n    \r\n    module_model.where(:module_id=>apps.collect{|i| i.id} ).all.each do |i|\r\n    \r\n    appm[i.module_id] = i\r\n    \r\n    end\r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n\r\n    colo_m = module_model.where(:parent_id=>appm.values.collect{|i| i.id}, :module_name=>\"\\\\#{@current_project.name}#colonoscopy\").all\r\n    colo_p = {}\r\n    colo_m.each do |i|\r\n        colo_p[i.patient_id] = i.module_id \r\n    end\r\n    \r\n    \r\n    \r\n    colos =  models[:colonoscopy].find(colo_m.collect{|i| i.module_id})\r\n    colomap = {}\r\n    scopes = []\r\n    \r\n    coloms = {}\r\n    locmap = {}\r\n    colos.each do |i|\r\n         \r\n         colomap[i.id.to_s] = i\r\n         scope_list.each do |j|\r\n            coloms[i.id.to_s] = [] unless coloms[i.id.to_s]\r\n            coloms[i.id.to_s] += i[j] if i[j]\r\n            for x in i[j]\r\n                locmap[x.to_s] = j\r\n            end\r\n            \r\n            scopes += coloms[i.id.to_s] if coloms[i.id.to_s]\r\n         end\r\n    end\r\n    scm = {}\r\n    \r\n    models[:colonoscopy_scope].find(scopes).each do |i|\r\n    scm[i.id.to_s] = i\r\n    end\r\n    \r\n    l = {}\r\n    \r\n  \r\n \r\n    \r\n    # models[:colonoscopy_scope].find(colom)\r\n    \r\n    \r\n    \r\n \r\n    \r\n    \r\n    # abnormal_type\r\n    total_register =0\r\n    total_register += groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    total_register += groups[\'Processing\'].size if groups[\'Processing\']\r\n    total_register += groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    \r\n  total_complete = 0 \r\n    total_complete = groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    total_cancer = 0\r\n    total_polyp  = 0 \r\n    total_waiting = 0 \r\n    total_waiting = groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    \r\n   \r\n    # coloms.each_pair do |c,l|\r\n         \r\n    # end\r\n    \r\n    data = []\r\n    \r\n     coloms.keys.each do |k|\r\n        v = coloms[k].collect{|i| scm[i] }\r\n        l[k.to_s] = v\r\n        total_cancer+=1 if v and v.index(\'Cancer\') \r\n        total_polyp+=1 if v and v.index(\'Polyp\')\r\n\r\n    end\r\n\r\n    mm = {}\r\n    mm2 = {}\r\n    module_model.where(:module_id=>coloms.keys).all.each do|i|\r\n        mm[i.module_id.to_s] = i.patient_id\r\n        mm2[i.module_id.to_s] = i.id\r\n    end\r\n    \r\n    pm = {}\r\n    patient_model.find(mm.values).each do |i|\r\n      pm[i.id] = i \r\n    end\r\n    \r\n    providers = {}\r\n    models[:provider].all.each do |i|\r\n        providers[i.id] = i.name \r\n    end\r\n    \r\n\r\n    # scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n#     1|Rectum\r\n# 2|Sigmoid\r\n# 3|Descending colon\r\n# 4|Transvers colon\r\n# 5|Ascending colon\r\n# 6|Cecum\r\n# 7|Terminal ileum\r\n    \r\n    scope_map = {}\r\n    scope_list.each_with_index do |i,index|\r\n        scope_map[(index+1).to_s] = i.split(\"_\")[0].humanize\r\n    end\r\n    \r\n    gender_map = {\'1\'=>\'ชาย\', \'2\'=>\'หญิง\'}\r\n\r\n%>\r\n\r\n<body>\r\n\r\n<div class=\"bbody\" style=\"font-size:14px\">\r\n\r\n<div class=\"bhead\">\r\n \r\n\r\n\r\n\r\n\r\n<table id=\"table\" width=\"100%\" border=\"0\" cellpadding=\"1\" cellspacing=\"1\" style=\" \">\r\n<tr>\r\n  <th colspan=\"16\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/bsh_mobile/endo/bsh_logo_only.jpeg\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h2>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลพุทธโสธร ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์\r\n <br>\r\n  Patho Details Report\r\n  วันที่\r\n  <%=params[:date]%>\r\n  <%=\"- \"+params[:stop_date] if params[:stop_date]&&(params[:stop_date]!=params[:date])%>\r\n  ผู้ป่วย\r\n  <span id=\"sum_patient\"></span>\r\n  คน\r\n  <!--Patho รวม\r\n  <span id=\"sum_patho\"></span>\r\n  ชิ้น-->\r\n  </h2>\r\n  <br>\r\n  </th>\r\n  </tr>\r\n</table>\r\n<table id=\"table\" width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\" \">\r\n<tr>\r\n    <th width=\"10px\">No.</th>\r\n    <th width=\"80px\">ชื่อ-สกุล</th>\r\n    <th width=\"20px\">HN</th>\r\n    <th width=\"40px\">เลขบัตรประชาชน</th>\r\n    <th width=\"10px\">Gender</th>\r\n    <th width=\"10px\">อายุ</th> \r\n    <th width=\"40px\">วันที่ทำ</th>\r\n    <td width=\"40px\">Tel</td>\r\n    <th width=\"80px\">Endoscopist1</th>\r\n    <th width=\"120px\">Diagnosis Group</th>\r\n    <th width=\"80px\">#Patho</th>\r\n    <th width=\"80px\">Finding</th>\r\n    <th width=\"120px\">Endoscopist Dx</th>\r\n    <th width=\"80px\">ตำแหน่ง</th>\r\n    \r\n</tr>\r\n<% \r\n    index = 0 \r\n    sum_patho =0\r\n    for i in l.keys \r\n    v = l[i]\r\n    m = mm[i]\r\n    p = pm[m]\r\n    \r\n    r = colomap[colo_p[p.id].to_s]\r\n    lesion = coloms[r.id.to_s]\r\n    \r\n    age = 0 \r\n    \r\n    age = ((Time.now - p.birth_date.to_datetime)/3600/365/24).to_i if p.birth_date\r\n    age_class =\"black\"\r\n    age_class = \"red\" if age < 40 or age > 100\r\n    \r\n    ls = scope_map[r.scope]\r\n    \r\n    patho = 0 \r\n   \r\n    if coloms[r.id.to_s]\r\n    for x in coloms[r.id.to_s]\r\n        patho+=1 if scm[x.to_s] and scm[x.to_s].patho_number.to_i >0\r\n    end\r\n    end\r\n    \r\n    coloms[r.id.to_s].collect!{|y| y if scm[y.to_s] }.compact!\r\n    \r\n    if  r.diagnosis_group and r.diagnosis_group.downcase !=nil and patho>0\r\n        \r\n    coloms[r.id.to_s].sort!{|a,b| scm[a.to_s].patho_number.to_i<=>scm[b.to_s].patho_number.to_i}  \r\n    index2 = 0 \r\n    \r\n    \r\n    index+=1\r\n\r\n\r\n    for x in coloms[r.id.to_s]\r\n   \r\n    if scm[x.to_s] and scm[x.to_s].patho_number.to_i >0\r\n    j = scm[x.to_s]\r\n    loc = locmap[x.to_s].split(\'_\')[0].humanize\r\n    index2+=1\r\n    # sum_patho+=j.patho_number.to_i if j\r\n    sum_patho+=1\r\n%>\r\n\r\n    <tr style=\"color:<%=age_class%>\">\r\n    <td><%=index%>.<%=index2%></td>\r\n    <td align=\"left\" style=\"padding-left:4px\"><%=p.first_name%> <%=p.last_name%> </td>\r\n    <td align=\"left\" style=\"padding-left:4px\"><%=p.hn%></td>\r\n    <td align=\"left\" style=\"padding-left:4px\"><%=p.public_id%></td>\r\n    <td><%=gender_map[p.gender]%></td>\r\n    <td ><%=\"\\\\#{age} ปี \"%> \r\n    <%=p.birth_date if age_class==\'red\'%></td>  \r\n    \r\n<td><%=params[:date]%></td>\r\n<td align=\"left\" style=\"padding-left:4px\"><%=p.mobile%></td>\r\n\r\n\r\n<td align=\"left\" style=\"padding-left:4px\"><%=providers[r.endoscopist_1]%></td>\r\n<td align=\"left\" style=\"padding-left:4px\"><%=r.diagnosis_group.split(\"|\").collect{|x| x if x.size>0}.compact.join(\",\")%></td>\r\n\r\n\r\n<td align=\"left\" style=\"padding-left:4px\"><%=j.patho_number if j%></td>\r\n\r\n<td align=\"left\" style=\"padding-left:4px\"><%=j.abnormal_type if j%></td>\r\n<td align=\"left\" style=\"padding-left:4px\"><%=j.endoscopy_dx if j%></td>\r\n\r\n\r\n<td align=\"left\" style=\"padding-left:4px\"><%=loc%></td>\r\n\r\n    </tr>\r\n    \r\n    <% end %>\r\n<% if sum_patho==30||(sum_patho>35&&sum_patho%35==0) %>\r\n</table>\r\n<div class=\"pagebreak\"></div>\r\n<table id=\"table\" width=\"100%\"  border=\"1\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-left:auto;margin-right:auto\">\r\n<tr>\r\n    <th width=\"10px\">No.</th>\r\n    <th width=\"80px\">ชื่อ-สกุล</th>\r\n    <th width=\"20px\">HN</th>\r\n    <th width=\"40px\">เลขบัตรประชาชน</th>\r\n    <th width=\"10px\">Gender</th>\r\n    <th width=\"10px\">อายุ</th> \r\n    <th width=\"40px\">วันที่ทำ</th>\r\n    <td width=\"40px\">Tel</td>\r\n    <th width=\"80px\">Endoscopist1</th>\r\n    <th width=\"120px\">Diagnosis Group</th>\r\n    <th width=\"80px\">#Patho</th>\r\n    <th width=\"80px\">Finding</th>\r\n    <th width=\"120px\">Endoscopist Dx</th>\r\n    <th width=\"80px\">ตำแหน่ง</th>\r\n    \r\n</tr>\r\n<% end %>       \r\n    <% end %>\r\n    <% end %>\r\n\r\n    <% end %>\r\n</table>\r\n\r\n<script>\r\n$(\"#sum_patient\").html(<%=index%>);\r\n$(\"#sum_patho\").html(<%=sum_patho%>);\r\n\r\n</script>\r\n\r\n<%#locmap.inspect %>\r\n</div>\r\n\r\n</div>\r\n\r\n<%= render :inline=>this.table_export %>\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2017-08-13 02:18:48','2017-08-13 02:18:48','patient_polyp_cancer',''),(3135,'table_export',1229,4,'\r\n	<script  src=\"/downloadify/swfobject.js\"></script>\r\n	\r\n	\r\n	<script  src=\"/downloadify/base64.min.js\"></script>\r\n	\r\n	\r\n	<!-- FileSaver.js is the library of choice for Chrome -->\r\n	<script  src=\"/downloadify/Blob.js\"></script>\r\n	<script src=\"/downloadify/FileSaver.js\"></script>\r\n	<script lang=\"javascript\" src=\"/downloadify/xlsx.full.min.js\"></script>\r\n	<script>\r\n	\r\n	\r\n	function s2ab(s) {\r\n		if(typeof ArrayBuffer !== \'undefined\') {\r\n			var buf = new ArrayBuffer(s.length);\r\n			var view = new Uint8Array(buf);\r\n			for (var i=0; i!=s.length; ++i) view[i] = s.charCodeAt(i) & 0xFF;\r\n			return buf;\r\n		} else {\r\n			var buf = new Array(s.length);\r\n			for (var i=0; i!=s.length; ++i) buf[i] = s.charCodeAt(i) & 0xFF;\r\n			return buf;\r\n		}\r\n	}\r\n\r\n	function export_table_to_excel(id, type, fn) {\r\n	var wb = XLSX.utils.table_to_book(document.getElementById(id), {sheet:\"Sheet JS\"});\r\n	var wbout = XLSX.write(wb, {bookType:type, bookSST:true, type: \'binary\'});\r\n	var fname = fn || \'export.\' + type;\r\n	// try {\r\n		saveAs(new Blob([s2ab(wbout)],{type:\"application/octet-stream\"}), fname);\r\n	// } catch(e) { if(typeof console != \'undefined\') console.log(e, wbout); }\r\n	return wbout;\r\n	}\r\n\r\n	function doit(type, fn) { return export_table_to_excel(\'table\', type || \'xlsx\', fn); }\r\n	</script>\r\n\r\n\r\n\r\n\r\n<script  src=\"/downloadify/swfobject.js\"></script>\r\n\r\n<script  src=\"/downloadify/downloadify.min.js\"></script>\r\n<style>\r\n@media print {\r\n\r\n    .non-print{\r\n        display:none;\r\n    }\r\n    \r\n}\r\n\r\n</style>\r\n\r\n\r\n<input type=\"submit\" value=\"Export to XLSX!\" onclick=\"doit(\'xlsx\');\" class=\"non-print\">\r\n<p id=\"xlsxbtn\" class=\"btn\" style=\"display:none\">Flash required for actually downloading the generated file.</p>\r\n\r\n\r\n\r\n<script type=\"text/javascript\">\r\nfunction tableau(pid, iid, fmt, ofile) {\r\n	if(true) {\r\n		if(document.getElementById(iid)) document.getElementById(iid).hidden = true; \r\n		Downloadify.create(pid,{\r\n			swf: \'media/downloadify.swf\',\r\n			downloadImage: \'download.png\',\r\n			width: 100,\r\n			height: 30,\r\n			filename: ofile, data: function() { var o = doit(fmt, ofile); return window.btoa(o); },\r\n			transparent: false,\r\n			append: false,\r\n			dataType: \'base64\',\r\n			onComplete: function(){ alert(\'Your File Has Been Saved!\'); },\r\n			onCancel: function(){ alert(\'You have cancelled the saving of this file.\'); },\r\n			onError: function(){ alert(\'You must put something in the File Contents or there will be nothing to save!\'); }\r\n		});\r\n	} else document.getElementById(pid).innerHTML = \"\";\r\n}\r\ntableau(\'xlsxbtn\',  \'xportxlsx\',  \'xlsx\',  \'export.xlsx\');\r\n\r\n</script>',NULL,NULL,NULL,'2017-08-13 04:08:26','2017-08-13 04:08:26','table_export',''),(3136,'demographic_report',1230,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Patient Report</title>\r\n<%=include_header%>\r\n<style>\r\n .bbody{ width:100%; margin-left:auto; margin-right:auto;}\r\n .bhead{text-align:center}\r\n table {\r\n    border-width: thin;\r\n    border-spacing: 1px;\r\n    border-style: none;\r\n    border-color: black;\r\n    border-collapse: collapse;\r\n}\r\ntd {padding-left:3px;}\r\n\r\n</style>\r\n\r\n\r\n\r\n\r\n</head>\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    params[:date]  = \"12/8/2017\" unless params[:date]\r\n    t = params[:date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    date = Date.new t[0],t[1],t[2]\r\n    \r\n    \r\n    projects = models[:project].all\r\n    \r\n    for project in projects \r\n    \r\n    \r\n    apps = models[:appointment].where(:date.gte=>project.start_date.at_beginning_of_day,:date.lt=>project.end_date.end_of_day).all\r\n\r\n    groups = {}\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    \r\n    \r\n    # colos = models[:colonoscopy].where(\r\n   \r\n    for i in apps\r\n    \r\n    \r\n    s = i.status\r\n    groups[s] = [] unless groups[s]\r\n    groups[s] << i\r\n    \r\n    \r\n    end\r\n    \r\n    appm = {}\r\n    \r\n    module_model.where(:module_id=>apps.collect{|i| i.id} ).all.each do |i|\r\n    \r\n    appm[i.module_id] = i\r\n    \r\n    end\r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n\r\n    colo_m = module_model.where(:parent_id=>appm.values.collect{|i| i.id}, :module_name=>\"\\\\#{@current_project.name}#colonoscopy\").all\r\n    colo_p = {}\r\n    colo_mm = {}\r\n    colo_m.each do |i|\r\n        colo_mm[i.module_id] = i\r\n        colo_p[i.patient_id] = i.module_id \r\n    end\r\n    \r\n    \r\n    colos =  models[:colonoscopy].find(colo_m.collect{|i| i.module_id})\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    colomap = {}\r\n    scopes = []\r\n    \r\n    coloms = {}\r\n    locmap = {}\r\n    colos.each do |i|\r\n         \r\n         colomap[i.id] = i\r\n         scope_list.each do |j|\r\n            coloms[i.id] = [] unless coloms[i.id]\r\n            coloms[i.id] += i[j] if i[j]\r\n            for x in i[j]\r\n                locmap[x.to_s] = j\r\n            end\r\n            \r\n            scopes += coloms[i.id] if coloms[i.id]\r\n         end\r\n    end\r\n\r\n    scm = {}\r\n    \r\n    models[:colonoscopy_scope].find(scopes).each do |i|\r\n    scm[i.id.to_s] = i\r\n\r\n    end\r\n    \r\n    l = {}\r\n    \r\n \r\n  \r\n \r\n    \r\n    # models[:colonoscopy_scope].find(colom)\r\n    \r\n    \r\n    \r\n \r\n    \r\n    \r\n    # abnormal_type\r\n    total_register =0\r\n    total_register += groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    total_register += groups[\'Processing\'].size if groups[\'Processing\']\r\n    total_register += groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    \r\n  total_complete = 0 \r\n    total_complete = groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    total_cancer = 0\r\n    total_polyp  = 0 \r\n    total_waiting = 0 \r\n    total_waiting = groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    \r\n   \r\n    # coloms.each_pair do |c,l|\r\n         \r\n    # end\r\n    \r\n    data = []\r\n    \r\n\r\n    \r\n     coloms.keys.each do |k|\r\n        v = coloms[k].collect{|i| scm[i] }\r\n        l[k.to_s] = v\r\n        total_cancer+=1 if v and v.index(\'Cancer\') \r\n        total_polyp+=1 if v and v.index(\'Polyp\')\r\n\r\n    end\r\n\r\n    mm = {}\r\n    mm2 = {}\r\n    module_model.where(:module_id=>coloms.keys).all.each do|i|\r\n        mm[i.module_id.to_s] = i.patient_id\r\n        mm2[i.module_id.to_s] = i.id\r\n    end\r\n    \r\n    pm = {}\r\n    patient_model.find(mm.values).each do |i|\r\n      pm[i.id] = i \r\n    end\r\n    \r\n    providers = {}\r\n    models[:provider].all.each do |i|\r\n        providers[i.id] = i.name \r\n    end\r\n    \r\n\r\n    # scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n#     1|Rectum\r\n# 2|Sigmoid\r\n# 3|Descending colon\r\n# 4|Transvers colon\r\n# 5|Ascending colon\r\n# 6|Cecum\r\n# 7|Terminal ileum\r\n    \r\n    scope_map = {}\r\n    scope_list.each_with_index do |i,index|\r\n        scope_map[(index+1).to_s] = i.split(\"_\")[0].humanize\r\n    end\r\n    \r\n    gender_map = {\'1\'=>\'ชาย\', \'2\'=>\'หญิง\'}\r\n    \r\n    \r\n    \r\n    amphurs = {}\r\n    \r\n    dmap = {:polyp=>{},:adenoma=>{},:cancer=>{}}\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n\r\n%>\r\n\r\n<body style=\"padding:20px\">\r\n\r\n<table id=\"table\" width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-left:auto;margin-right:auto; display:none\">\r\n<tr>\r\n  <th colspan=\"16\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/bsh_mobile/endo/bsh_logo_only.jpeg\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h2>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลพุทธโสธร ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์.\r\n  </h2>\r\n\r\n<h1>&nbsp;</h1></th>\r\n  </tr>\r\n<tr>\r\n    <th width=\"10px\">No.</th>\r\n    <th>ชื่อ-สกุล</th>\r\n    <th>HN</th>\r\n    <th>เลขบัตรประชาชน</th><th>Gender</th><th>อายุ</th><th>วันที่ทำ</th>\r\n    <th>#Patho</th><th>Finding</th>\r\n    \r\n</tr>\r\n<%  \r\n    index = 0\r\n    colos.each do |i|\r\n         \r\n#   colomap[i.id] = i\r\n\r\n    xx = colo_mm[i.id]\r\n    slist = coloms[i.id]        \r\n    p = pm[xx.patient_id]   \r\n    \r\n    \r\n    location = \"\\\\#{p.contact_province}-\\\\#{p.contact_amphur}\"\r\n    \r\n    amphurs[location] = 0  unless   amphurs[location]\r\n    \r\n    amphurs[location] += 1\r\n    \r\n    \r\n    dmap[:total_colono] = {} unless dmap[:total_colono]\r\n    dmap[:total_colono][location] = 0 unless dmap[:total_colono][location]\r\n    dmap[:total_colono][location] += 1\r\n    \r\n    is_polyp = false\r\n    is_adenoma = false\r\n    is_cancer = false\r\n    \r\n\r\n\r\n    age = 0 \r\n    \r\n    age = ((Time.now - p.birth_date.to_datetime)/3600/365/24).to_i if p.birth_date\r\n    age_class =\"black\"\r\n    age_class = \"red\" if age < 40 or age > 100\r\n    show = false\r\n    for j in slist \r\n        s = scm[j.to_s]\r\n        \r\n        if  s and s.patho_number and s.patho_number.to_i > 0  \r\n         show = true\r\n        end\r\n        if s.endoscopy_dx\r\n        if s and s.endoscopy_dx.downcase.index(\'polyp\') or s.endoscopy_dx==\"Sessile Serrated Adenoma\" or s.endoscopy_dx==\"Traditional Serrated Adenoma\"\r\n            is_polyp = true\r\n        end\r\n        if s and [\"Adenomatous polyp\",\"Sessile Serrated Adenoma\",\"Malignant non invasive polyp\",\"Traditional Serrated Adenoma\"].index(s.endoscopy_dx)\r\n            is_adenoma = true\r\n        end\r\n        if s and s.endoscopy_dx.index(\'Malignant invasive polyp\') or s.endoscopy_dx==\'Malignancy\'\r\n            is_cancer = true\r\n        end\r\n        end\r\n    end\r\n    \r\n    if is_polyp\r\n        \r\n        dmap[:polyp][location] = 0 unless dmap[:polyp][location]\r\n        dmap[:polyp][location] += 1\r\n\r\n    end\r\n\r\n    if is_adenoma\r\n        \r\n        dmap[:adenoma][location] = 0 unless dmap[:adenoma][location]\r\n        dmap[:adenoma][location] += 1\r\n\r\n    end\r\n\r\n    if is_cancer\r\n        \r\n        dmap[:cancer][location] = 0 unless dmap[:cancer][location]\r\n        dmap[:cancer][location] += 1\r\n\r\n    end\r\n\r\n\r\n    \r\n    if true\r\n         index+=1\r\n%>\r\n<tr>\r\n\r\n<td><%=index%></td>\r\n\r\n<td><%=p.first_name%> <%=p.last_name%></td>\r\n\r\n<td><%=p.contact_amphur%></td>\r\n<td><%=p.contact_province%></td>\r\n\r\n\r\n\r\n\r\n<td><%=p.hn%></td>\r\n\r\n<td><%=p.public_id%></td>\r\n\r\n  <td><%=gender_map[p.gender]%></td>\r\n    <td ><%=\"\\\\#{age} ปี \"%> \r\n    <%=p.birth_date if age_class==\'red\'%></td> \r\n<td><%=params[:date]%></td>\r\n\r\n\r\n<%\r\nsslist = []\r\n    \r\nfor j in slist \r\n    s = scm[j.to_s]\r\n    \r\n    loc = nil\r\n    \r\n    loc = locmap[s.id.to_s].split(\'_\')[0].humanize if s and locmap[s.id.to_s]\r\n    \r\n    if  s \r\n   \r\n\r\n    \r\n    sslist << \"\\\\#{s.patho_number}.\\\\#{s.abnormal_type}:\\\\#{loc}:\\\\#{s.endoscopy_dx}\"\r\n    \r\n\r\n\r\n    end  \r\n    \r\nend\r\n%>\r\n\r\n<%\r\nstext = sslist.sort.join(\", \")\r\n%>\r\n<td><%=sslist.size%></td>\r\n\r\n<td><%=stext%></td>\r\n\r\n\r\n</tr>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n         \r\n         \r\n<% end %>\r\n\r\n</table>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<%#amphurs.inspect %>\r\n<h2>ตารางสรุปแยกตามอำเภอ</h2>\r\n<hr/>\r\n<%#dmap.inspect %>\r\n<style>\r\n    .v{color:blue;}\r\n</style>\r\n<table class=\"\" border=\"1\" width=\"100%\">\r\n    <tr>\r\n        <th>&nbsp;</th>\r\n        <% for i in amphurs.keys.sort %>\r\n        <th><%=i.split(\"-\")[-1]%></th>\r\n        <% end %>\r\n    </tr>\r\n    <% for t in [:total_colono, :polyp, :adenoma, :cancer] %>\r\n    <tr>\r\n    <td><%= t %></td>\r\n    <% for i in amphurs.keys.sort %>\r\n        <th><%=dmap[t][i]%> <span class=\"v\"><%=\"(\\\\#{format(\'%.2f\',(dmap[t][i].to_f*100)/dmap[:total_colono][i])}%)\" if t!=:total_colono %></span></th>\r\n    <% end %>\r\n    </tr>\r\n    <% end %>\r\n        \r\n    \r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2017-08-13 05:53:19','2017-08-13 05:53:19','demographic_report',''),(3137,'summary_report',1229,3,'<%\r\n\r\n    dates = %w{12/8/2017 13/8/2017}\r\n    groups = {}\r\n    \r\n    models = get_model\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n  \r\n    map = {}\r\n    \r\n    l = %w{total total_polyp total_cancer total_diver total_other}.collect{|i| i.to_sym}\r\n    s = {}\r\n    for i in dates\r\n        t = i.split(\"/\").reverse.collect{|i| i.to_i}\r\n        date = Date.new t[0],t[1],t[2]\r\n        key = i\r\n        \r\n        apps = models[:appointment].where(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day).all\r\n        appm = module_model.where(:module_id=>apps.collect{|i| i.id }).all\r\n        \r\n        colom = module_model.where(:parent_id=>appm.collect{|i| i.id },:module_name=>\"\\\\#{@current_project.name}#colonoscopy\").all\r\n        \r\n        colos = models[:colonoscopy].find(colom.collect{|i| i.module_id })\r\n        \r\n        map[key] = {} unless map[key]\r\n        r = map[key]\r\n        %>\r\n        <%#colos.collect{|i| \"\\\\#{i.diagnosis_group}\"}.join(\'<br/>\').html_safe%>\r\n        <%\r\n        \r\n        r[:total] = colos.size\r\n        r[:total_polyp] = colos.collect{|i| i if  i.diagnosis_group.downcase.index(\'polyp\') }.compact.size\r\n        r[:total_cancer] = colos.collect{|i| i if  i.diagnosis_group.index(\'Cancer\') }.compact.size\r\n        r[:total_diver] = colos.collect{|i| i if  i.diagnosis_group.downcase.index(\'diverti\') }.compact.size\r\n        r[:total_other] = colos.collect{|i| i if  i.diagnosis_group.downcase.index(\'polyp\')==nil and i.diagnosis_group.downcase.index(\'cancer\')==nil and i.diagnosis_group.downcase.index(\'diverti\')==nil and i.diagnosis_group!=\'Normal\' }.compact.size\r\n        # r[:total]- r[:total_polyp]- r[:total_cancer]- r[:total_diver]- colos.collect{|i| i if  i.diagnosis_group==\'Normal\' }.compact.size\r\n        \r\n        for x in l\r\n            s[x] = 0 unless s[x]\r\n            s[x] += r[x]\r\n        end\r\n# {\"12/8/2016\"=>{:total=>81, :total_polyp=>18, :total_cancer=>1, :total_diver=>10, :total_other=>1}, \"13/8/2016\"=>{:total=>76, :total_polyp=>25, :total_cancer=>1, :total_diver=>12, :total_other=>-2}}        \r\n        \r\n    end\r\n%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Patient Report</title>\r\n<%=include_header%>\r\n<style>\r\n .bbody{ width:100%; margin-left:auto; margin-right:auto;}\r\n .bhead{text-align:center}\r\n</style>\r\n</head>\r\n    <body>\r\n\r\n<div class=\"bbody\" style=\"font-size:14px\">\r\n\r\n<div class=\"bhead\">\r\n \r\n\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\"  style=\"margin-left:auto;margin-right:auto\">\r\n<tr>\r\n  <th colspan=\"16\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/bsh_mobile/endo/bsh_logo_only.jpeg\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h2>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลพุทธโสธร ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์\r\n  </h2>\r\n\r\n<h1>&nbsp;</h1></th>\r\n  </tr>\r\n<tr>\r\n<td align=\"center\">\r\n        <table border=\"1\" cellpadding=\"20\" >\r\n            <tr><td>&nbsp;</td>\r\n                <% for d in dates %>\r\n                <th><%=d%></th>\r\n                <% end %>\r\n                <td>Sum</td>\r\n            </tr>\r\n            <% for r in l %>\r\n            <tr><td><%=r.to_s.humanize%></td>\r\n                <% for d in dates %>\r\n                <td><%=map[d][r]%></td>\r\n                <% end %>\r\n                \r\n                <td><%=s[r]%> <%=\"(\\\\#{format(\'%.2f\',(s[r]*100.to_f/s[:total]).to_f)}%)\" if r!=:total %></td>\r\n            </tr>\r\n            <% end %>\r\n            \r\n            \r\n            \r\n        </table>\r\n    </td>\r\n    </tr>\r\n    </table>\r\n    </div>\r\n    </div>\r\n        \r\n    </body>\r\n</html>',NULL,NULL,NULL,'2017-08-13 07:38:10','2017-08-13 07:38:10','summary_report',''),(3138,'patient_abnormal',1229,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Patient Report</title>\r\n<%=include_header%>\r\n<style>\r\n .bbody{ width:100%; margin-left:auto; margin-right:auto;}\r\n .bhead{text-align:center}\r\n  table {\r\n    border-width: thin;\r\n    border-spacing: 1px;\r\n    border-style: none;\r\n    border-color: black;\r\n    border-collapse: collapse;\r\n    font-size:0.6em;\r\n}\r\n@media print{\r\n    .pagebreak {page-break-before: always;}\r\n    @page {size: landscape}\r\n}\r\n</style>\r\n</head>\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    params[:date]  = \"13/8/2016\" unless params[:date]\r\n    t = params[:date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    date = Date.new t[0],t[1],t[2]\r\n    \r\n    stop_date = date\r\n    \r\n    if params[:stop_date]\r\n    t = params[:stop_date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    stop_date = Date.new t[0],t[1],t[2]\r\n    end\r\n\r\n\r\n    apps = models[:appointment].where(:date.gte=>date.at_beginning_of_day,:date.lt=>stop_date.end_of_day).all\r\n\r\n\r\n    groups = {}\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    \r\n    \r\n    # colos = models[:colonoscopy].where(\r\n    \r\n    \r\n    \r\n    \r\n    for i in apps\r\n    \r\n    s = i.status\r\n    groups[s] = [] unless groups[s]\r\n    groups[s] << i\r\n    \r\n    \r\n    end\r\n    \r\n    appm = {}\r\n    \r\n    module_model.where(:module_id=>apps.collect{|i| i.id} ).all.each do |i|\r\n    \r\n    appm[i.module_id] = i\r\n    \r\n    end\r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n\r\n    colo_m = module_model.where(:parent_id=>appm.values.collect{|i| i.id}, :module_name=>\"\\\\#{@current_project.name}#colonoscopy\").all\r\n    colo_p = {}\r\n    colo_m.each do |i|\r\n        colo_p[i.patient_id] = i.module_id \r\n    end\r\n    \r\n    \r\n    \r\n    colos =  models[:colonoscopy].find(colo_m.collect{|i| i.module_id})\r\n    colomap = {}\r\n    scopes = []\r\n    \r\n    coloms = {}\r\n    locmap = {}\r\n    colos.each do |i|\r\n         \r\n         colomap[i.id.to_s] = i\r\n         scope_list.each do |j|\r\n            coloms[i.id.to_s] = [] unless coloms[i.id.to_s]\r\n            coloms[i.id.to_s] += i[j] if i[j]\r\n            for x in i[j]\r\n                locmap[x.to_s] = j\r\n            end\r\n            \r\n            scopes += coloms[i.id.to_s] if coloms[i.id.to_s]\r\n         end\r\n    end\r\n    scm = {}\r\n    \r\n    models[:colonoscopy_scope].find(scopes).each do |i|\r\n    scm[i.id.to_s] = i\r\n    end\r\n    \r\n    l = {}\r\n    \r\n  \r\n \r\n    \r\n    # models[:colonoscopy_scope].find(colom)\r\n    \r\n    \r\n    \r\n \r\n    \r\n    \r\n    # abnormal_type\r\n    total_register =0\r\n    total_register += groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    total_register += groups[\'Processing\'].size if groups[\'Processing\']\r\n    total_register += groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    \r\n  total_complete = 0 \r\n    total_complete = groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    total_cancer = 0\r\n    total_polyp  = 0 \r\n    total_waiting = 0 \r\n    total_waiting = groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    \r\n   \r\n    # coloms.each_pair do |c,l|\r\n         \r\n    # end\r\n    \r\n    data = []\r\n    \r\n     coloms.keys.each do |k|\r\n        v = coloms[k].collect{|i| scm[i] }\r\n        l[k.to_s] = v\r\n        total_cancer+=1 if v and v.index(\'Cancer\') \r\n        total_polyp+=1 if v and v.index(\'Polyp\')\r\n\r\n    end\r\n\r\n    mm = {}\r\n    mm2 = {}\r\n    module_model.where(:module_id=>coloms.keys).all.each do|i|\r\n        mm[i.module_id.to_s] = i.patient_id\r\n        mm2[i.module_id.to_s] = i.id\r\n    end\r\n    \r\n    pm = {}\r\n    patient_model.find(mm.values).each do |i|\r\n      pm[i.id] = i \r\n    end\r\n    \r\n    providers = {}\r\n    models[:provider].all.each do |i|\r\n        providers[i.id] = i.name \r\n    end\r\n    \r\n\r\n    # scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n#     1|Rectum\r\n# 2|Sigmoid\r\n# 3|Descending colon\r\n# 4|Transvers colon\r\n# 5|Ascending colon\r\n# 6|Cecum\r\n# 7|Terminal ileum\r\n    \r\n    scope_map = {}\r\n    scope_list.each_with_index do |i,index|\r\n        scope_map[(index+1).to_s] = i.split(\"_\")[0].humanize\r\n    end\r\n    \r\n    gender_map = {\'1\'=>\'ชาย\', \'2\'=>\'หญิง\'}\r\n\r\n%>\r\n\r\n<body>\r\n\r\n<div class=\"bbody\" style=\"font-size:14px\">\r\n\r\n<div class=\"bhead\">\r\n \r\n\r\n\r\n\r\n\r\n<table id=\"table\" width=\"100%\" border=\"0\" cellpadding=\"1\" cellspacing=\"1\" style=\" \">\r\n<tr>\r\n  <th colspan=\"16\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/bsh_mobile/endo/bsh_logo_only.jpeg\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h2>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลพุทธโสธร ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์\r\n  </h2>\r\n  <h3>\r\n  Abnormal Details Report\r\n  วันที่\r\n  <%=params[:date]%>\r\n  <%=\"- \"+params[:stop_date] if params[:stop_date]&&(params[:stop_date]!=params[:date])%>\r\n  ผู้ป่วย\r\n  <span id=\"sum_patient\"></span>\r\n  คน\r\n  Abnormal Details\r\n  <span id=\"sum_patho\"></span>\r\n  records\r\n  </h3>\r\n  \r\n<br></th>\r\n  </tr>\r\n</table>  \r\n<table id=\"table\" width=\"100%\" border=\"1\" cellpadding=\"1\" cellspacing=\"1\" style=\" \">\r\n<tr>\r\n    <th width=\"25px\">No.</th>\r\n    <th width=\"100px\">ชื่อ-สกุล</th>\r\n    <th width=\"20px\">HN</th>\r\n    <th width=\"40px\">เลขบัตรประชาชน</th> \r\n    <th width=\"10px\">Gender</th> \r\n    <th width=\"10px\">อายุ</th> \r\n    <th width=\"20px\">วันที่ทำ</th>\r\n    <td width=\"20px\">Tel</td>\r\n    <th width=\"80px\">Endoscopist1</th>\r\n    <th width=\"150px\">Diagnosis Group</th>\r\n    <th width=\"80px\">#Patho</th>\r\n    <th width=\"80px\">Finding</th>\r\n    <th width=\"120px\">Endoscopist Dx</th>\r\n    <th width=\"80px\">ตำแหน่ง</th>\r\n    \r\n</tr>\r\n<% \r\n    index = 0 \r\n    sum_patho = 0\r\n    for i in l.keys \r\n    v = l[i]\r\n    m = mm[i]\r\n    p = pm[m]\r\n    \r\n    r = colomap[colo_p[p.id].to_s]\r\n    lesion = coloms[r.id.to_s]\r\n    \r\n    age = 0 \r\n    \r\n    age = ((Time.now - p.birth_date.to_datetime)/3600/365/24).to_i if p.birth_date\r\n    age_class =\"black\"\r\n    age_class = \"red\" if age < 40 or age > 100\r\n    \r\n    ls = scope_map[r.scope]\r\n    \r\n    patho = 0 \r\n   \r\n    if coloms[r.id.to_s]\r\n    for x in coloms[r.id.to_s]\r\n        patho+=1 if scm[x.to_s] and scm[x.to_s].patho_number.to_i >0\r\n    end\r\n    end\r\n    \r\n    coloms[r.id.to_s].collect!{|y| y if scm[y.to_s] }.compact!\r\n    \r\n    if  r.diagnosis_group and r.diagnosis_group.downcase !=nil #and patho>0\r\n        \r\n    coloms[r.id.to_s].sort!{|a,b| scm[a.to_s].patho_number.to_i<=>scm[b.to_s].patho_number.to_i}  \r\n    index2 = 0 \r\n    \r\n    \r\n    index+=1 if coloms[r.id.to_s].size>0\r\n\r\n\r\n    for x in coloms[r.id.to_s]\r\n   \r\n    # if scm[x.to_s] and scm[x.to_s].patho_number.to_i >0\r\n    j = scm[x.to_s]\r\n    loc = locmap[x.to_s].split(\'_\')[0].humanize\r\n    index2+=1\r\n    sum_patho+=1\r\n\r\n%>\r\n\r\n    <tr style=\"color:<%=age_class%>\">\r\n    <td><%=index%>.<%=index2%></td>\r\n    <td align=\"left\" style=\"padding-left:4px\"><%=p.first_name%> <%=p.last_name%> </td>\r\n    <td align=\"left\" style=\"padding-left:4px\"><%=p.hn%></td>\r\n    <td align=\"left\" style=\"padding-left:4px\"><%=p.public_id%></td>\r\n    <td><%=gender_map[p.gender]%></td>\r\n    <td ><%=\"\\\\#{age} ปี \"%> \r\n    <%=p.birth_date if age_class==\'red\'%></td>  \r\n    \r\n<td><%=params[:date]%></td>\r\n<td align=\"left\" style=\"padding-left:4px\"><%=p.mobile%></td>\r\n\r\n\r\n<td align=\"left\" style=\"padding-left:4px\"><%=providers[r.endoscopist_1]%></td>\r\n<td align=\"left\" style=\"padding-left:4px\"><%=r.diagnosis_group.split(\"|\").collect{|x| x if x.size>0}.compact.join(\",\")%></td>\r\n\r\n\r\n<td align=\"left\" style=\"padding-left:4px\"><%=j.patho_number if j%></td>\r\n\r\n<td align=\"left\" style=\"padding-left:4px\"><%=j.abnormal_type if j%></td>\r\n<td align=\"left\" style=\"padding-left:4px\"><%=j.endoscopy_dx if j%></td>\r\n\r\n\r\n<td align=\"left\" style=\"padding-left:4px\"><%=loc%></td>\r\n\r\n    </tr>\r\n    \r\n<% if sum_patho==30||(sum_patho>35&&sum_patho%35==0) %>\r\n</table>\r\n<div class=\"pagebreak\"></div>\r\n<table id=\"table\" width=\"100%\"  border=\"1\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-left:auto;margin-right:auto\">\r\n<tr>\r\n    <th width=\"25px\">No.</th>\r\n    <th width=\"100px\">ชื่อ-สกุล</th>\r\n    <th width=\"20px\">HN</th>\r\n    <th width=\"40px\">เลขบัตรประชาชน</th> \r\n    <th width=\"10px\">Gender</th> \r\n    <th width=\"10px\">อายุ</th> \r\n    <th width=\"20px\">วันที่ทำ</th>\r\n    <td width=\"20px\">Tel</td>\r\n    <th width=\"80px\">Endoscopist1</th>\r\n    <th width=\"150px\">Diagnosis Group</th>\r\n    <th width=\"80px\">#Patho</th>\r\n    <th width=\"80px\">Finding</th>\r\n    <th width=\"120px\">Endoscopist Dx</th>\r\n    <th width=\"80px\">ตำแหน่ง</th>\r\n    \r\n</tr>\r\n<% end %>         \r\n    <% end %>\r\n    <% #end %>\r\n\r\n    <% end %>\r\n\r\n    <% end %>\r\n</table>\r\n<script>\r\n$(\"#sum_patient\").html(<%=index%>);\r\n$(\"#sum_patho\").html(<%=sum_patho%>);\r\n\r\n</script>\r\n\r\n<%#locmap.inspect %>\r\n</div>\r\n\r\n</div>\r\n\r\n<%= render :inline=>this.table_export %>\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2017-08-13 16:48:45','2017-08-13 16:48:45','patient_abnormal',''),(3139,'summary_report_2',1229,3,'<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Patient Report</title>\r\n<%=include_header%>\r\n<style>\r\n .bbody{ width:100%; margin-left:auto; margin-right:auto;}\r\n .bhead{text-align:center}\r\n table {\r\n    border-width: thin;\r\n    border-spacing: 1px;\r\n    border-style: none;\r\n    border-color: black;\r\n    border-collapse: collapse;\r\n}\r\ntd {padding-left:3px;}\r\n\r\n@media print {\r\n    #query {\r\n        display: none;\r\n    }\r\nh3 {\r\n    font-size:0.8em;\r\n}    \r\n  \r\n\r\n}   \r\n\r\n</style>\r\n\r\n\r\n\r\n\r\n</head>\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    \r\n    \r\n    amphurs = {}\r\n    \r\n    dmap = {:appointment=>{},:cancel=>{},:polyp=>{},:adenoma=>{},:cancer=>{},:no_show=>{}}\r\n    \r\n    \r\n    \r\n    \r\n    params[:date]  = \"12/8/2017\" unless params[:date]\r\n    t = params[:date].split(\"/\").reverse.collect{|i| i.to_i}\r\n    date = Date.new t[0],t[1],t[2]\r\n    \r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    \r\n    \r\n    if true\r\n    \r\n    \r\n    \r\n    if params[:project_id]\r\n        \r\n    project = models[:project].find(params[:project_id])\r\n    \r\n    apps = models[:appointment].where(:date.gte=>project.start_date.at_beginning_of_day,:date.lt=>project.end_date.end_of_day).all\r\n        \r\n    else \r\n        apps = []\r\n        if params[:query]\r\n            from_date = params[:query][\'from_date(1i)\']+\"-\"+params[:query][\'from_date(2i)\']+\"-\"+params[:query][\'from_date(3i)\']+\"-\" if params[:query]\r\n            # from_date = from_date.beginning_of_month\r\n            \r\n            to_date = params[:query][\'to_date(1i)\']+\"-\"+params[:query][\'to_date(2i)\']+\"-\"+params[:query][\'to_date(3i)\']+\"-\" if params[:query]\r\n            # to_date = to_date.end_of_month\r\n        end\r\n        if params[:from_date]\r\n            params[:from_date]  = \"13/8/2017\" unless params[:from_date]\r\n            t = params[:from_date].split(\"/\").reverse.collect{|i| i.to_i}\r\n            from_date = Date.new t[0],t[1],t[2]\r\n            # from_date = t[0]+\"-\"+t[1]+\"-\"+t[2]+\"-\"\r\n            to_date = from_date\r\n            \r\n            if params[:to_date]\r\n            t = params[:to_date].split(\"/\").reverse.collect{|i| i.to_i}\r\n            to_date = Date.new t[0],t[1],t[2]\r\n            # to_date = t[0]+\"-\"+t[1]+\"-\"+t[2]+\"-\"\r\n            end   \r\n        end\r\n        apps = models[:appointment].where(:date.gte=>from_date.at_beginning_of_day,:date.lt=>to_date.end_of_day).all\r\n    end\r\n    \r\n    from_date = Date.to_mongo(from_date)\r\n    to_date = Date.to_mongo(to_date)\r\n\r\n\r\n\r\n    \r\n    apps.sort!{|a,b| b.date<=>a.date }.reverse \r\n    \r\n    \r\n\r\n    groups = {}\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    \r\n    \r\n    # colos = models[:colonoscopy].where(\r\n   \r\n    for i in apps\r\n    \r\n    \r\n    s = i.status\r\n    groups[s] = [] unless groups[s]\r\n    groups[s] << i\r\n    \r\n    # all appointment\r\n    \r\n    key = \"date-\"+i.date.strftime(\"%d/%m/%Y\")\r\n\r\n    dmap[:appointment][key] = 0 unless dmap[:appointment][key]\r\n    dmap[:appointment][key] += 1\r\n    \r\n    \r\n    \r\n    end\r\n    \r\n    appm = {}\r\n    \r\n    module_model.where(:module_id=>apps.collect{|i| i.id} ).all.each do |i|\r\n    \r\n    appm[i.module_id] = i\r\n    \r\n    end\r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n\r\n    colo_m = module_model.where(:parent_id=>appm.values.collect{|i| i.id}, :module_name=>\"\\\\#{@current_project.name}#colonoscopy\").all\r\n    colo_p = {}\r\n    colo_mm = {}\r\n    colo_m.each do |i|\r\n        colo_mm[i.module_id] = i\r\n        colo_p[i.patient_id] = i.module_id \r\n    end\r\n    \r\n    \r\n    colos =  models[:colonoscopy].find(colo_m.collect{|i| i.module_id})\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    colomap = {}\r\n    scopes = []\r\n    \r\n    coloms = {}\r\n    locmap = {}\r\n    colos.each do |i|\r\n         \r\n         colomap[i.id] = i\r\n         scope_list.each do |j|\r\n            coloms[i.id] = [] unless coloms[i.id]\r\n            coloms[i.id] += i[j] if i[j]\r\n            for x in i[j]\r\n                locmap[x.to_s] = j\r\n            end\r\n            \r\n            scopes += coloms[i.id] if coloms[i.id]\r\n         end\r\n    end\r\n\r\n    scm = {}\r\n    \r\n    models[:colonoscopy_scope].find(scopes).each do |i|\r\n    scm[i.id.to_s] = i\r\n    end\r\n    \r\n    l = {}\r\n    \r\n \r\n  \r\n \r\n    \r\n    # models[:colonoscopy_scope].find(colom)\r\n    \r\n    \r\n    \r\n \r\n    \r\n    \r\n    # abnormal_type\r\n    total_register =0\r\n    total_register += groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    total_register += groups[\'Processing\'].size if groups[\'Processing\']\r\n    total_register += groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    \r\n  total_complete = 0 \r\n    total_complete = groups[\'Recovery\'].size if groups[\'Recovery\']\r\n    total_cancer = 0\r\n    total_polyp  = 0 \r\n    total_waiting = 0 \r\n    total_waiting = groups[\'Arrived\'].size if groups[\'Arrived\']\r\n    \r\n   \r\n    # coloms.each_pair do |c,l|\r\n         \r\n    # end\r\n    \r\n    data = []\r\n    \r\n\r\n    \r\n     coloms.keys.each do |k|\r\n        v = coloms[k].collect{|i| scm[i] }\r\n        l[k.to_s] = v\r\n        total_cancer+=1 if v and v.index(\'Cancer\') \r\n        total_polyp+=1 if v and v.index(\'Polyp\')\r\n\r\n    end\r\n\r\n    mm = {}\r\n    mm2 = {}\r\n    module_model.where(:module_id=>coloms.keys).all.each do|i|\r\n        mm[i.module_id.to_s] = i.patient_id\r\n        mm2[i.module_id.to_s] = i.id\r\n    end\r\n    \r\n    pm = {}\r\n    patient_model.find(mm.values).each do |i|\r\n      pm[i.id] = i \r\n    end\r\n    \r\n    providers = {}\r\n    models[:provider].all.each do |i|\r\n        providers[i.id] = i.name \r\n    end\r\n    \r\n\r\n    # scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n#     1|Rectum\r\n# 2|Sigmoid\r\n# 3|Descending colon\r\n# 4|Transvers colon\r\n# 5|Ascending colon\r\n# 6|Cecum\r\n# 7|Terminal ileum\r\n    \r\n    scope_map = {}\r\n    scope_list.each_with_index do |i,index|\r\n        scope_map[(index+1).to_s] = i.split(\"_\")[0].humanize\r\n    end\r\n    \r\n    gender_map = {\'1\'=>\'ชาย\', \'2\'=>\'หญิง\'}\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n\r\n%>\r\n\r\n<body style=\"padding:20px\">\r\n<style>\r\n    select{ width:80px;margin-top:8px;};\r\n</style>\r\n<div id=\"query\">\r\n<%=form_for :query, :url=>\"\" do |f| %>\r\n<center>\r\nPeriod : \r\n<%=f.date_select :from_date, :order=>[:day, :month, :year],:default=>from_date%> -\r\n<%=f.date_select :to_date, :order=>[:day, :month, :year],:default=>to_date  %>\r\n<%= f.submit \"Query\", :class=>\'btn\'%>\r\n</center>\r\n\r\n<% end %>\r\n\r\n<hr/>\r\n</div>\r\n\r\n<table id=\"table\" width=\"100%\" border=\"1\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-left:auto;margin-right:auto; display:none\">\r\n<tr>\r\n  <th colspan=\"16\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/bsh_mobile/endo/bsh_logo_only.jpeg\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h3>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลพุทธโสธร ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์.\r\n  </h3>\r\n\r\n<h1>&nbsp;</h1></th>\r\n  </tr>\r\n<tr>\r\n    <th width=\"10px\">No.</th>\r\n    <th>ชื่อ-สกุล</th>\r\n    <th>HN</th>\r\n    <th>เลขบัตรประชาชน</th><th>Gender</th><th>อายุ</th><th>วันที่ทำ</th>\r\n    <th>#Patho</th><th>Finding</th>\r\n    \r\n</tr>\r\n<%  \r\n    index = 0\r\n    colos.each do |i|\r\n         \r\n#   colomap[i.id] = i\r\n\r\n    xx = colo_mm[i.id]\r\n    slist = coloms[i.id]        \r\n    p = pm[xx.patient_id]   \r\n    \r\n    if p\r\n\r\n    \r\n    location = \"\\\\#{p.contact_province}-\\\\#{p.contact_amphur}\"\r\n    location = \"date-\\\\#{i.created_at.strftime(\"%d/%m/%Y\")}\"\r\n    \r\n    amphurs[location] = 0  unless   amphurs[location]\r\n    \r\n    amphurs[location] += 1\r\n    \r\n    \r\n    dmap[:colonoscopy] = {} unless dmap[:colonoscopy]\r\n    dmap[:colonoscopy][location] = 0 unless dmap[:colonoscopy][location]\r\n    dmap[:colonoscopy][location] += 1\r\n    \r\n    dmap[:cancel][location] = dmap[:appointment][location] - dmap[:colonoscopy][location]\r\n    \r\n    is_polyp = false\r\n    is_adenoma = false\r\n    is_cancer = false\r\n    \r\n\r\n\r\n    age = 0 \r\n    \r\n    age = ((Time.now - p.birth_date.to_datetime)/3600/365/24).to_i if p.birth_date\r\n    age_class =\"black\"\r\n    age_class = \"red\" if age < 40 or age > 100\r\n    show = false\r\n    for j in slist \r\n        s = scm[j.to_s]\r\n        \r\n        if  s and s.patho_number and s.patho_number.to_i > 0  \r\n         show = true\r\n        end\r\n        if s.endoscopy_dx\r\n        if s and s.endoscopy_dx.downcase.index(\'polyp\') or s.endoscopy_dx==\"Sessile Serrated Adenoma\" or s.endoscopy_dx==\"Traditional Serrated Adenoma\"\r\n            is_polyp = true\r\n        end\r\n        if s and [\"Adenomatous polyp\",\"Sessile Serrated Adenoma\",\"Malignant non invasive polyp\",\"Traditional Serrated Adenoma\"].index(s.endoscopy_dx)\r\n            is_adenoma = true\r\n        end\r\n        if s and s.endoscopy_dx.index(\'Malignant invasive polyp\') or s.endoscopy_dx==\'Malignancy\'\r\n            is_cancer = true\r\n        end\r\n        end\r\n    end\r\n    \r\n    if is_polyp\r\n        \r\n        dmap[:polyp][location] = 0 unless dmap[:polyp][location]\r\n        dmap[:polyp][location] += 1\r\n\r\n    end\r\n\r\n    if is_adenoma\r\n        \r\n        dmap[:adenoma][location] = 0 unless dmap[:adenoma][location]\r\n        dmap[:adenoma][location] += 1\r\n\r\n    end\r\n\r\n    if is_cancer\r\n        \r\n        dmap[:cancer][location] = 0 unless dmap[:cancer][location]\r\n        dmap[:cancer][location] += 1\r\n\r\n    end\r\n\r\n\r\n    \r\n    if true\r\n         index+=1\r\n%>\r\n<tr>\r\n\r\n<td><%=index%></td>\r\n\r\n<td><%=p.first_name%> <%=p.last_name%></td>\r\n\r\n<td><%=p.contact_amphur%></td>\r\n<td><%=p.contact_province%></td>\r\n\r\n\r\n\r\n\r\n<td><%=p.hn%></td>\r\n\r\n<td><%=p.public_id%></td>\r\n\r\n  <td><%=gender_map[p.gender]%></td>\r\n    <td ><%=\"\\\\#{age} ปี \"%> \r\n    <%=p.birth_date if age_class==\'red\'%></td> \r\n<td><%=params[:date]%></td>\r\n\r\n\r\n<%\r\nsslist = []\r\n    \r\nfor j in slist \r\n    s = scm[j.to_s]\r\n    \r\n    loc = nil\r\n    \r\n    loc = locmap[s.id.to_s].split(\'_\')[0].humanize if s and locmap[s.id.to_s]\r\n    \r\n    if  s \r\n   \r\n\r\n    \r\n    sslist << \"\\\\#{s.patho_number}.\\\\#{s.abnormal_type}:\\\\#{loc}:\\\\#{s.endoscopy_dx}\"\r\n    \r\n\r\n\r\n    end  \r\n    \r\nend\r\n%>\r\n\r\n<%\r\nstext = sslist.sort.join(\", \")\r\n%>\r\n<td><%=sslist.size%></td>\r\n\r\n<td><%=stext%></td>\r\n\r\n\r\n</tr>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n         \r\n         \r\n<% end %>\r\n\r\n</table>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<table  border=\"0\" cellpadding=\"1\" cellspacing=\"1\"  style=\"margin-left:auto;margin-right:auto;width:100%\" >\r\n<tr>\r\n  <th colspan=\"16\"><span style=\"float:right\"><img src=\"/esm/cusys/mobile/colo_logo.png\" alt=\"a\" style=\"width:60px\" /></span><span style=\"float:left\"><img src=\"/esm/bsh_mobile/endo/bsh_logo_only.jpeg\" alt=\"a\" style=\"width:60px\" /></span> \r\n  <h3>โครงการตรวจคัดกรองมะเร็งลำไส้ใหญ่และทวารหนัก<br />\r\n  โรงพยาบาลพุทธโสธร ร่วมกับ ห้องส่องกล้อง Surgery Endoscopy โรงพยาบาลจุฬาลงกรณ์\r\n  </h3>\r\n  <h3>\r\n  วันที่\r\n  <%=params[:from_date]%>\r\n  <%=\"- \"+params[:to_date] if params[:to_date]&&(params[:to_date]!=params[:from_date])%>\r\n  ผู้ป่วย\r\n  <span id=\"sum_patient\"></span>\r\n  คน\r\n  </h3>  \r\n  </tr>\r\n</table>\r\n\r\n<%#amphurs.inspect %>\r\n\r\n<hr/>\r\n<style>\r\n    .v{color:blue;}\r\n    td{padding:20px;}\r\n    \r\n</style>\r\n\r\n<%\r\n   keys = amphurs.keys\r\n   \r\n  keys = keys.sort{|a,b| Date.strptime(a.split(\"-\")[-1], \"%d/%m/%Y\").to_datetime.to_i<=>Date.strptime(b.split(\"-\")[-1], \"%d/%m/%Y\").to_datetime.to_i }\r\n   \r\n\r\n%>\r\n<table class=\"\" border=\"1\" width=\"80%\"  style=\"margin-left:auto;margin-right:auto\">\r\n    <tr>\r\n        <th>Description</th>\r\n        <% for i in keys %>\r\n        <th><%=i.split(\"-\")[-1]%></th>\r\n        <% end %>\r\n        <th>Total</th>\r\n        \r\n    </tr>\r\n    <% \r\n    csum = {}\r\n    colo_sum=0\r\n        \r\n    for t in [:appointment,:cancel,:colonoscopy, :polyp, :adenoma, :cancer]\r\n    \r\n        lt = t.to_s.humanize\r\n        lt = \'Cancel & No show\' if t==:cancel\r\n    \r\n    \r\n    %>\r\n    <tr>\r\n    <td><%= lt %></td>\r\n    <% rsum=0\r\n        \r\n        for i in keys\r\n        rsum += dmap[t][i] if dmap[t][i]\r\n        colo_sum += dmap[t][i] if t==:colonoscopy\r\n        per_total = 0\r\n        per_total = format(\'%.2f\',(rsum.to_f*100)/colo_sum) if colo_sum > 0\r\n        \r\n        %>\r\n        <th><%=dmap[t][i]%> <span class=\"v\"><%=\"(\\\\#{format(\'%.2f\',(dmap[t][i].to_f*100)/dmap[:colonoscopy][i])}%)\" if t==:polyp or t==:adenoma or t==:cancer %></span></th>\r\n  \r\n   <% end %>\r\n   \r\n    <th>\r\n        <%=rsum%>\r\n        <span class=\"v\"> <%=\"(\\\\#{per_total}%)\" if t==:polyp or t==:adenoma or t==:cancer %></span>\r\n    </th>\r\n    </tr>\r\n    <% end %>\r\n        \r\n        \r\n    \r\n</table>\r\n\r\n<script>\r\n$(\"#sum_patient\").html(<%=colo_sum%>);\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2017-08-13 17:03:04','2017-08-13 17:03:04','summary_report_2',''),(3140,'pre_register',500,2,'<div class=\"row-fluid\" style=\"\">\r\n<right><%=link_to \'ลงทะเบียนใหม่\',\'create\', :class=>\'btn btn-success\', :style=>\'float:right\'%></right><br/>\r\n\r\n<br/>    \r\n</div>\r\n<table class=\"table\" style=\"font-size:0.8em\">\r\n<thead>\r\n<tr>\r\n<th>\r\nชื่อ\r\n</th>   \r\n<th>\r\nนามสกุล    \r\n</th>\r\n<th>\r\nสถาบัน\r\n</th>\r\n<th>\r\nเบอร์ติดต่อ\r\n</th>\r\n\r\n<th>\r\nEmail\r\n</th>\r\n\r\n<th>\r\nลงทะเบียน\r\n</th>\r\n</tr>\r\n\r\n    \r\n</thead>\r\n<%\r\n    model = get_model\r\n    members = model[:member].all.collect{|m| m if m.email == nil or m.email.size ==0 }.compact\r\n    for m in members\r\n%>\r\n<tr>\r\n    <td><%=m.first_name%></td><td><%=m.last_name%></td><td><%=m.hospital%></td><td><%=m.mobile%></td><td><%=m.email%></td><td><%=link_to \'ลงทะเบียน\', \"edit?id=\\\\#{m.id}\", :class=>\'btn\'  %></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n\r\n',NULL,NULL,NULL,'2017-08-17 17:20:33','2017-08-17 17:20:33','pre_register',''),(3141,'edit',500,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>แก้ไขข้อมูลการลงทะเบียน</h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"pre_register\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'pre_register\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-08-17 17:32:15','2017-08-17 17:32:15','edit',''),(3142,'financial_report',522,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Financial Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # params_date = select_date\r\n    # select_date = Date.to_mongo(select_date)\r\n    \r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date , :order=>[:day,:month,:year]%>\r\n\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    # start_date = select_date.beginning_of_month()\r\n    # stop_date = select_date.end_of_month()\r\n    \r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    providers = @models[:provider].collection.find({:provider_type=>\'1\'}).to_a.collect{|i| i[\'_id\']}\r\n    \r\n  \r\n    payrolls = @models[:attendance_payroll].collection.find({:provider=>{\'$in\'=>providers},:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}}).to_a\r\n    \r\n \r\n    \r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n    \r\n    \r\n    all_pm_bill = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}billing\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_bill = bmap all_pm_bill, \'parent_id\'\r\n    \r\n    \r\n    all_bill = models[:billing].collection.find({\'_id\'=>{\'$in\'=>all_pm_bill.collect{|i| i[\'module_id\']}}}).to_a\r\n    m_all_bill = bmap all_bill, \'_id\'\r\n    \r\n    items = []\r\n    for i in all_bill\r\n        items  += i[\'items\']\r\n    end\r\n    \r\n    all_bill_item = models[:billing_item].collection.find({\'_id\'=>{\'$in\'=>items}}).to_a\r\n    m_all_bill_item = bmap all_bill_item, \'_id\'\r\n    \r\n    products = models[:product].collection.find().to_a\r\n    m_products = bmap products, \'_id\'\r\n    \r\n    payroll_structures = models[:payroll_structure].collection.find().to_a\r\n    m_payroll_structures = bmap payroll_structures, \'product_id\'\r\n    \r\n    \r\n    pcat = models[:product_category].collection.find().to_a\r\n    m_pcat = bmap pcat, \'_id\'\r\n    \r\n    \r\n    m_cat = {}\r\n    m_code = {}\r\n    \r\n    for i in products\r\n    \r\n        m_cat[i[\'_id\']] = m_pcat[i[\'category_id\']][0][\'type\'] if i[\'category_id\'] and  m_pcat[i[\'category_id\']]\r\n        m_code[i[\'_id\']] = i[\'code\']\r\n        \r\n        \r\n        \r\n    end\r\n    \r\n    all_payroll_item = models[:attendance_payroll_item].collection.find({\'billing_id\'=>{\'$in\'=>all_bill.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_payroll_item = bmap all_payroll_item, \'billing_id\'\r\n    \r\n    \r\n    \r\n   \r\n   \r\n    m = {}\r\n    ym = {}\r\n    mm = {}\r\n    \r\n    for app in all_app\r\n        \r\n        pm_app = m_all_pm_app[app[\'_id\']]\r\n        if pm_app\r\n            pm_app = pm_app[0]\r\n            date = app[\'date\'].strftime(\"%Y-%m\")\r\n            \r\n            pm_billing = m_all_pm_bill[pm_app[\'_id\']]\r\n            \r\n            mm[date] = true\r\n            ym[app[\'date\'].strftime(\"%Y\")] = true\r\n          \r\n            \r\n            if pm_billing \r\n                \r\n            \r\n            \r\n            billing = m_all_bill[pm_billing[0][\'module_id\']][0]\r\n            \r\n            billing_type = billing[\'billing_type\']\r\n            \r\n            \r\n            key = \"\\\\#{date}-\\\\#{billing_type}\"\r\n            \r\n              \r\n          \r\n            for i in billing[\'items\']\r\n            \r\n            it = m_all_bill_item[i][0]\r\n            \r\n            p = m_cat[it[\'product_id\']]\r\n            \r\n            ps = m_payroll_structures[it[\'product_id\']]\r\n            \r\n            if ps and ps.size>0\r\n            \r\n            ps = ps[0]\r\n            \r\n            m[key+\"-subsidy\"] = 0 unless  m[key+\"-subsidy\"] \r\n               \r\n            m[key+\"-subsidy\"] += ps[\'instrument\'].to_i\r\n                \r\n            end\r\n            \r\n            price = it[\'price\']\r\n            \r\n            m[key+\"-\"+p] = 0 unless m[key+\"-\"+p] \r\n            m[key+\"-\"+p] += it[\'price\']\r\n            \r\n            if m_code[it[\'product_id\']] == \'SU077\'\r\n              \r\n               m[key+\"-bowelprep\"] = 0 unless  m[key+\"-bowelprep\"] \r\n               \r\n               m[key+\"-bowelprep\"] += it[\'price\']\r\n                \r\n              \r\n            end\r\n            \r\n            \r\n            end\r\n            \r\n            sum = 0 \r\n            list = m_all_payroll_item[billing[\'_id\']]\r\n            if list\r\n            for i in list\r\n            \r\n                sum+= i[\'price\']\r\n                \r\n            end\r\n            end\r\n            \r\n            m[key+\"-payback\"] = 0 unless m[key+\"-payback\"]\r\n            m[key+\"-payback\"] += sum \r\n            \r\n    \r\n        end\r\n    \r\n    \r\n        end\r\n        \r\n\r\n    end\r\n    \r\n   %>\r\n    <%#m.inspect %>\r\n    <%\r\n       \r\n    for p in payrolls\r\n        \r\n        \r\n        date = p[\'date\'].strftime(\"%Y-%m\")\r\n        \r\n        key = \"\\\\#{date}-2-doctor\"\r\n        \r\n        m[key] = 0 unless m[key]\r\n        \r\n        m[key] += p[\'amount\'].to_i if p[\'amount\']\r\n        m[key] += p[\'amount_2\'].to_i if p[\'amount_2\']\r\n        \r\n        \r\n        \r\n    \r\n    end\r\n    \r\n    \r\n    sm = {}\r\n    st = {}\r\n    \r\n    m.each_pair do |k,v|\r\n       t = k.split(\"-\")\r\n       st[k] = v\r\n       k = \"\\\\#{t[0]}-\\\\#{t[2]}\"\r\n       \r\n       if t[-1]==\'procedure\' or t[-1]==\'dispense\'\r\n       sm[k] = 0 unless sm[k]\r\n       \r\n       sm[k] += v\r\n        end\r\n        \r\n    end\r\n    \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n    \r\n\r\n\r\nmonth_text=\'\'\r\n    # month_text = month_th[select_date.month-1]+select_date.strftime(\"-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    \r\n    td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:middle; \r\n        font-weight: bold;\r\n    }\r\n    td.small{\r\n        font-size:0.8em;\r\n    }\r\n    td.date{\r\n        padding:0px;\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n        td.date{\r\n        padding:0px;\r\n        \r\n        width:125px;\r\n        \r\n    }\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n    \r\n    tr.page-break{page-break-after:always;page-break-inside:avoid; page-break-after:auto}\r\n    .force-break{ display: block;page-break-before:always;}\r\n        \r\n    }\r\n    \r\n\r\n    \r\n   table { page-break-inside:auto }\r\n   tr    { page-break-inside:avoid; page-break-after:auto }\r\n    \r\n</style>\r\n<style type=\"text/css\">\r\n\r\n</style>\r\n\r\n<div style=\"width:720px\">\r\n<h3>รายงานงบการเงิน</h3>\r\n</div>\r\n\r\n<br/>\r\n<table class=\'table\' border=\"1\">\r\n    <tr>\r\n        <thead>\r\n            <th>&nbsp;</th>\r\n            <th>&nbsp;</th>\r\n            <th>&nbsp;</th>\r\n            \r\n            <% 12.times do |i| %>\r\n            <th><%= format(\'%02d\',i+1)%></th>\r\n            <% end %>\r\n             \r\n            <th>Sum</th>\r\n            <th>Total</th>\r\n        </thead>\r\n    </tr>\r\n    <% \r\n    \r\n    \r\n    \r\n      \r\n    for y in ym.keys %>\r\n    <tr>\r\n        <td rowspan=\"12\" style=\"vertical-align: middle;\"><%= y %></td>\r\n        \r\n        <td rowspan=\"6\" style=\"vertical-align: middle;\" >Elective</td>\r\n        <td > Procedure </td>\r\n        <% \r\n        sum = 0 \r\n        12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-1-procedure\"\r\n        \r\n        if m[k]\r\n            \r\n        v = m[k]\r\n        \r\n        v -= m[y+\"-\"+format(\'%02d\',i+1)+\"-1-bowelprep\"] if m[y+\"-\"+format(\'%02d\',i+1)+\"-1-bowelprep\"]\r\n\r\n        # v -= m[y+\"-\"+format(\'%02d\',i+1)+\"-1-subsidy\"] if m[y+\"-\"+format(\'%02d\',i+1)+\"-1-subsidy\"]\r\n\r\n        # v -= m[y+\"-\"+format(\'%02d\',i+1)+\"-1-payback\"] if m[y+\"-\"+format(\'%02d\',i+1)+\"-1-payback\"]\r\n        \r\n        # v -= m[y+\"-\"+format(\'%02d\',i+1)+\"-1-doctor\"] if m[y+\"-\"+format(\'%02d\',i+1)+\"-1-doctor\"]\r\n        \r\n        sm\r\n        \r\n        t = fn(v) \r\n        sum+= v \r\n        end\r\n        \r\n        \r\n        %>\r\n        <td align=\"right\"><%=t%></td>\r\n        <% end %>\r\n        <td><%=fn(sum)%></td>\r\n        <td style=\"vertical-align: middle;\" rowspan=\"6\"><%=fn(sm[\"\\\\#{y}-1\"])%></td>\r\n    </tr>\r\n\r\n\r\n    <tr align=\"right\">\r\n       \r\n        <td >เวชภัณฑ์ </td>\r\n        <% \r\n        sum = 0 \r\n        12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-1-dispense\"\r\n        t = fn(m[k]) if m[k]\r\n         sum+= m[k] if m[k]\r\n        %>\r\n        <td ><%=t%></td>\r\n        <% end %>\r\n           <td><%=fn(sum)%></td>\r\n    </tr>\r\n    \r\n    \r\n    <tr align=\"right\">\r\n       \r\n        <td >ห้องเตรียมลำไส้ </td>\r\n        <% \r\n        sum = 0 \r\n        12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-1-bowelprep\"\r\n        t = fn(m[k]) if m[k]\r\n         sum+= m[k] if m[k]\r\n        %>\r\n        <td ><%=t%></td>\r\n        <% end %>\r\n           <td><%=fn(sum)%></td>\r\n    </tr>\r\n    \r\n    <tr align=\"right\">\r\n       \r\n        <td >OT</td>\r\n        <% \r\n         sum = 0 \r\n         12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-1-payback\"\r\n        t = fn(m[k]) if m[k]\r\n         sum+= m[k] if m[k]\r\n        \r\n        %>\r\n        <td><%=t%></td>\r\n        <% end %>\r\n         <td><%=fn(sum)%></td>\r\n    </tr>\r\n    \r\n      <tr align=\"right\">\r\n       \r\n        <td >DF</td>\r\n        <% \r\n         sum = 0 \r\n         12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-1-doctor\"\r\n        t = fn(m[k]) if m[k]\r\n         sum+= m[k] if m[k]\r\n        \r\n        %>\r\n        <td><%=t%></td>\r\n        <% end %>\r\n         <td><%=fn(sum)%></td>\r\n    </tr>\r\n    \r\n        \r\n    <tr align=\"right\">\r\n       \r\n        <td >Subsidy </td>\r\n        <% \r\n        sum = 0 \r\n        12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-1-subsidy\"\r\n        t = fn(m[k]) if false and  m[k]\r\n        \r\n         sum+= m[k] if m[k]\r\n        %>\r\n        <td ><%=t%></td>\r\n        <% end %>\r\n           <td>0<%#fn(sum)%></td>\r\n    </tr>\r\n\r\n   <tr align=\"right\">\r\n       \r\n        <td rowspan=\"6\" style=\"vertical-align: middle;\" >Extratime</td>\r\n        <td > Procedure </td>\r\n        <% \r\n        \r\n        sum=0\r\n        12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-2-procedure\"\r\n        \r\n        \r\n        if m[k]\r\n            \r\n        v = m[k]\r\n        \r\n        v -= m[y+\"-\"+format(\'%02d\',i+1)+\"-2-bowelprep\"] if m[y+\"-\"+format(\'%02d\',i+1)+\"-2-bowelprep\"]\r\n        \r\n        # v -= m[y+\"-\"+format(\'%02d\',i+1)+\"-2-subsidy\"] if m[y+\"-\"+format(\'%02d\',i+1)+\"-2-subsidy\"]\r\n\r\n        # v -= m[y+\"-\"+format(\'%02d\',i+1)+\"-2-payback\"] if m[y+\"-\"+format(\'%02d\',i+1)+\"-2-payback\"]\r\n        \r\n        # v -= m[y+\"-\"+format(\'%02d\',i+1)+\"-2-doctor\"] if m[y+\"-\"+format(\'%02d\',i+1)+\"-2-doctor\"]\r\n        \r\n        \r\n        t = fn(v) \r\n        sum+= v \r\n        end\r\n        \r\n        \r\n        \r\n        %>\r\n        <td><%=t%></td>\r\n        <% end %>\r\n         <td><%=fn(sum)%></td>\r\n        <td style=\"vertical-align: middle;\" rowspan=\"6\"><%=fn(sm[\"\\\\#{y}-2\"])%></td>\r\n\r\n\r\n    </tr>\r\n\r\n    <tr align=\"right\">\r\n      \r\n        <td >เวชภัณฑ์ </td>\r\n        <%\r\n        sum=0\r\n        12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-2-dispense\"\r\n        t = fn(m[k]) if m[k]\r\n           sum+= m[k] if m[k]\r\n        %>\r\n        <td><%=t%></td>\r\n        <% end %>\r\n         <td><%=fn(sum)%></td>\r\n    </tr>\r\n    \r\n        <tr align=\"right\">\r\n       \r\n        <td >ห้องเตรียมลำไส้ </td>\r\n        <% \r\n        sum = 0 \r\n        12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-2-bowelprep\"\r\n        t = fn(m[k]) if m[k]\r\n         sum+= m[k] if m[k]\r\n        %>\r\n        <td ><%=t%></td>\r\n        <% end %>\r\n           <td><%=fn(sum)%></td>\r\n    </tr>\r\n    <tr align=\"right\">\r\n       \r\n        <td >OT</td>\r\n        \r\n        <% \r\n        sum = 0 \r\n        12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-2-payback\"\r\n        t = fn(m[k]) if m[k]\r\n          sum+= m[k] if m[k]\r\n        \r\n        %>\r\n        <td><%=t%></td>\r\n        <% end %>\r\n         <td><%=fn(sum)%></td>\r\n    </tr>\r\n\r\n\r\n  <tr align=\"right\">\r\n       \r\n        <td >DF</td>\r\n        <% \r\n         sum = 0 \r\n         12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-2-doctor\"\r\n        t = fn(m[k]) if m[k]\r\n         sum+= m[k] if m[k]\r\n        \r\n        %>\r\n        <td><%=t%></td>\r\n        <% end %>\r\n         <td><%=fn(sum)%></td>\r\n    </tr>\r\n    \r\n      <tr align=\"right\">\r\n       \r\n        <td >Subsidy</td>\r\n        <% \r\n        sum = 0 \r\n        12.times do |i| \r\n        t = \'-\'\r\n        k = y+\"-\"+format(\'%02d\',i+1)+\"-2-subsidy\"\r\n        t = fn(m[k]) if m[k]\r\n         sum+= m[k] if m[k]\r\n        %>\r\n        <td ><%=t%></td>\r\n        <% end %>\r\n           <td><%=fn(sum)%></td>\r\n    </tr>\r\n    \r\n\r\n    <% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n\r\n<br/>\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2017-08-24 01:54:26','2017-08-24 01:54:26','financial_report',''),(3143,'document_name',1232,1,'\'intra_op\'',NULL,NULL,NULL,'2017-08-26 02:19:12','2017-08-26 02:19:12',NULL,NULL),(3144,'document_name',1233,1,'\'pre_operative\'',NULL,NULL,NULL,'2017-08-26 03:45:17','2017-08-26 03:45:17',NULL,NULL),(3146,'document_name',1235,1,'\'post_scope_record\'',NULL,NULL,NULL,'2017-08-26 03:55:39','2017-08-26 03:55:39',NULL,NULL),(3150,'document_name',1236,1,'\'pre_scope\'',NULL,NULL,NULL,'2017-08-26 04:00:27','2017-08-26 04:00:27',NULL,NULL),(3151,'gfff',695,2,'hfcsx,xx\r\nsx,slx\r\nslslxx\r\nslslxlliunhkjhhgggggdfbfggegegegegefgefg\r\nfbefhefgefgsg4gg4g4g4g4wg4g\r\negegeg4g4g4tg4g4tgwfgw4ggw4ggw4ggw4tgw44\r\ntgegherggw4tg4g4gefg4tg4tg4tgg4tg4tg4tg4tg4tg',NULL,NULL,NULL,'2017-08-26 12:09:57','2017-08-26 12:09:57','gfff',''),(3152,'print',1236,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:pre_scope].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n\r\n<meta content=\"authenticity_token\" name=\"csrf-param\" />\r\n<meta content=\"SdEWaBNLwQSAphZHmuFRZbAnL/xn+