ject[\'birth_date\'].toString();\r\ntmp = bd.split(\"/\");\r\nif (tmp[0] == \"00\") {\r\n    bd = \"01/01/\" + tmp[2]\r\n}\r\n$(\"#data-birth_date\").val(bd);\r\n$(\"#data-contact_name\").val(object[\'contact_name\']);\r\n$(\"#data-contact_tel\").val(object[\'contact_tel\']);\r\n$(\"#data-contact_desc\").val(object[\'contact_desc\']);\r\n<%\r\n    end\r\n%>\r\n<%# object.to_json.html_safe %>\r\n<% else %>\r\n    alert(\"Agent Error\");\r\n<% end %>\r\n<% rescue  Exception=>e %>\r\n    alert(\"Cannot connect Agent <%=e.message%>\");\r\n<% end %>\r\n<% end %>\r\n</script>\r\n<%# object.to_json.html_safe %>',NULL,NULL,NULL,'2017-09-19 16:03:38','2017-09-19 16:03:38','get_patient_info_tmp',''),(3174,'document_name',1245,1,'\'dyslipidemia_form\'',NULL,NULL,NULL,'2017-09-22 09:09:20','2017-09-22 09:09:20',NULL,NULL),(3175,'image_search_download',522,2,'\r\n<center>Preparing Download ....</center>\r\n<% if params[:images] \r\n\r\n     grid = Mongo::Grid.new(MongoMapper.database)\r\n     models = get_model\r\n     images = models[:attachment].find(params[:images])\r\n     id = \"image_\\\\#{Time.now.to_i}\"\r\n     tmp = File.join(\"tmp\",\"cache\",id)\r\n     `mkdir \\\\#{tmp}`\r\n      file = nil\r\n                content = nil\r\n                atts = []\r\n     for i in images\r\n                        ofile = grid.get(i.file_id)\r\n                        ext = ofile.filename.split(\".\")[-1]\r\n                        fname = \"\\\\#{tmp}/\\\\#{i.file_id}.\\\\#{ext}\"\r\n                        f = File.open(fname,\'w\')\r\n                        f.write ofile.read.force_encoding(\'utf-8\') \r\n                        f.close\r\n                        atts << fname\r\n     end\r\n\r\n     \r\n      tarfile = \"\\\\#{tmp}.zip\"\r\n      `zip \\\\#{tarfile} \\\\#{atts.join(\" \")}`\r\n      `mv \\\\#{tarfile} public` \r\n     `rm -rf \\\\#{tmp}`\r\n    \r\n%>\r\n<%# atts.inspect %>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=/<%=id%>.zip\">\r\n<script>\r\nsetTimeout(function() {\r\n  //your code to be executed after 1 second\r\n  window.close()\r\n}, 1000);\r\n\r\n\r\n    \r\n</script>\r\n\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2017-09-23 08:09:24','2017-09-23 08:09:24','image_search_download',''),(3176,'document_name',1247,1,'\'intra_scope\'',NULL,NULL,NULL,'2017-09-25 04:52:38','2017-09-25 04:52:38',NULL,NULL),(3177,'document_name',1248,1,'\'intra_scope_add\'',NULL,NULL,NULL,'2017-09-25 04:54:20','2017-09-25 04:54:20',NULL,NULL),(3178,'document_name',1249,1,'\'intra_scope_iv\'',NULL,NULL,NULL,'2017-09-25 05:09:41','2017-09-25 05:09:41',NULL,NULL),(3179,'document_name',1250,1,'\'implant_record\'',NULL,NULL,NULL,'2017-09-28 03:41:44','2017-09-28 03:41:44',NULL,NULL),(3180,'document_name',1251,1,'\'implant_item\'',NULL,NULL,NULL,'2017-09-28 03:45:42','2017-09-28 03:45:42',NULL,NULL),(3181,'obstetrics_report_partial',1185,3,'<%\r\n\r\n    models = get_model\r\n\r\n    \r\n     if q = params[:search]\r\n         \r\n           cond = {}\r\n         \r\n        q[:sdate] = Time.strptime(q[:sdate], \"%d/%m/%Y\")\r\n        q[:edate] = Time.strptime(q[:edate], \"%d/%m/%Y\")\r\n        cond[:admission_date] = {\'$gte\'=>q[:sdate].beginning_of_day,\'$lte\'=>q[:edate].end_of_day}\r\n        \r\n        # records = models[:gynecology].collection.find(cond, {:fields=>{\'discharge_status\'=>1, \'mcode\'=>1,\'_id\'=>1,\'case_type\'=>1,\'line\'=>1,\'stage\'=>1,\'malignancy_case_type\'=>1, \'principle_diagnosis\'=>1, \'comorbidity\'=>1, \'complication\'=>1, \'external_cause\'=>1, \'other_diagnosis\'=>1, \'operation\'=>1}}).to_a\r\n        records = models[:obstetrics].collection.find(cond, {:fields=>{\'admission_date\'=>1,\'fetuses_detail\'=>1,\'discharge_status\'=>1, \'mcode\'=>1,\'_id\'=>1,\'case_type\'=>1,\'line\'=>1,\'stage\'=>1,\'malignancy_case_type\'=>1, \'principle_diagnosis\'=>1, \'comorbidity\'=>1, \'complication\'=>1, \'external_cause\'=>1, \'other_diagnosis\'=>1, \'operation\'=>1}}).to_a\r\n        \r\n      \r\n        def query_map ms, rs, table, key, ukey=nil\r\n    \r\n        rx = []\r\n        map = {}\r\n        for i in rs\r\n        \r\n        for j in i[key]\r\n        \r\n        map[j] = i\r\n        \r\n        end\r\n        \r\n        end\r\n        \r\n        \r\n        rs.collect{|i| i[key] }.compact.each{|i| rx+= i}\r\n        ris = ms[table].collection.find({\'_id\'=>{\'$in\'=>rx}}).to_a\r\n        rm = {}\r\n        ux = {}\r\n        for i in ris\r\n            rm[i[\'_id\']] = i \r\n            x = i[ukey]\r\n            xs = x.gsub(\'.\',\',\').split(\',\')\r\n            for xi in xs\r\n            ux[xi] = [] unless ux[xi]\r\n            ux[xi] << i.merge(map[i[\'_id\']])\r\n            end\r\n        end\r\n            \r\n        [rm, rx, ux]\r\n            \r\n        end    \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        \r\n        # comorbidity = []\r\n        # records.collect{|i| i[\'comorbidity\'] }.compact.each{|i| comorbidity+= i}\r\n        \r\n        # complication = []\r\n        # records.collect{|i| i[\'complication\'] }.compact.each{|i| complication+= i}\r\n        \r\n        # external_cause = []\r\n        # records.collect{|i| i[\'external_cause\'] }.compact.each{|i| external_cause+= i}\r\n        \r\n        # other_diagnosis = []\r\n        # records.collect{|i| i[\'other_diagnosis\'] }.compact.each{|i| other_diagnosis+= i}\r\n        \r\n        # operation = []\r\n        # records.collect{|i| i[\'operation\'] }.compact.each{|i| operation+=i}\r\n        \r\n         k_principle_diagnosis = {}\r\n         k_mcode= {}\r\n         k_discharge={}\r\n         for i in records\r\n         \r\n            k_principle_diagnosis[i[\'principle_diagnosis\']] = [] unless  k_principle_diagnosis[i[\'principle_diagnosis\']] \r\n            k_principle_diagnosis[i[\'principle_diagnosis\']]  << i \r\n            \r\n            mcode = i[\'mcode\']\r\n            if mcode\r\n            mcode = mcode.gsub(\"/\",\"\")\r\n            k_mcode[mcode] = [] unless    k_mcode[mcode]\r\n            k_mcode[mcode] << i \r\n            end\r\n            k_discharge[i[\'discharge_status\']] = [] unless k_discharge[i[\'discharge_status\']] \r\n            k_discharge[i[\'discharge_status\']] << i\r\n            \r\n            \r\n         end\r\n        \r\n        \r\n         m_comorbidity, comorbidity, k_comorbidity  = query_map(models, records, :icd_comorbidity, \'comorbidity\', \'comorbidity\')\r\n        \r\n         m_complication, complication, k_complication  = query_map(models, records, :icd_complication, \'complication\', \'complication\')\r\n        \r\n         m_external_cause, external_cause, k_external_cause  = query_map(models, records, :icd_external_cause, \'external_cause\', \'external_cause\')\r\n        \r\n         m_other_diagnosis, other_diagnosis, k_other_diagnosis  = query_map(models, records, :icd_other_diagnosis, \'other_diagnosis\', \'other_diagnosis\')\r\n        \r\n         m_operation, operation, k_operation  = query_map(models, records, :icd_operation, \'operation\', \'operation\')\r\n        \r\n        #  babies = \r\n         m_babies, babies, k_babies =  query_map(models, records, :results_of_delivery_baby, \'fetuses_detail\', \'mode_of_delivery\')\r\n        %>\r\n  \r\n        <%\r\n        \r\n        \r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        model = ehr.load_model\r\n        m_patient = model[:patient]\r\n        m_patient_module = model[:patient_module]\r\n        \r\n        pm_records = m_patient_module.collection.find({\'module_id\'=>{\'$in\'=>records.collect{|i| i[\'_id\']}}}).to_a\r\n        \r\n        pm_map = {}\r\n        pm_records.each{|i| pm_map[i[\'module_id\']] = i}\r\n        \r\n        p_records = m_patient.collection.find({\'_id\'=>{\'$in\'=>pm_records.collect{|i| i[\'patient_id\']}}}).to_a\r\n        \r\n        p_map = {}\r\n        p_records.each{|i| p_map[i[\'_id\']]=i }\r\n        \r\n        \r\n        \r\n        patients = {}\r\n        \r\n        for i in records\r\n        \r\n            pm = pm_map[i[\'_id\']]\r\n            \r\n            p = p_map[pm[\'patient_id\']]\r\n            \r\n            if p\r\n            patients[p[\'_id\']] = [p,i,[]] unless patients[p[\'_id\']] \r\n            \r\n            \r\n            patients[p[\'_id\']][2] << i\r\n        end\r\n            \r\n        \r\n        end\r\n        \r\n        \r\n        \r\n    case_type = {}\r\n    line = {}\r\n    patients.values.each do |i|\r\n        case_type[i[1][\'case_type\']] = 0 unless  case_type[i[1][\'case_type\']] \r\n        case_type[i[1][\'case_type\']] += 1\r\n        line[i[1][\'line\']] = 0 unless  line[i[1][\'line\']] \r\n        line[i[1][\'line\']] += 1\r\n        \r\n    end\r\n\r\n\r\n\r\n        \r\n        \r\n\r\n    #   m_comorbidity  = models[:icd_comorbidity].collection.find({\'_id\'=>{\'$in\'=>comorbidity}}).to_a\r\n    #   m_comorbidity  = models[:icd_comorbidity].collection.find(\'_id\'=>{\'$in\'=>[BSON::ObjectId(\'592f9079790f9b6a69000033\')]}).to_a\r\n     def formulate l\r\n\r\n   l =  l.split(\"\\n\").compact\r\n    \r\n    l.collect!{|j|\r\n    \r\n    t = j.split(\":\")\r\n    \r\n    name = t[0]\r\n    codes = t[1].split(\',\').collect{|i| i.strip}.compact if t[1]\r\n    \r\n    {:name=>name,:codes=>codes}\r\n    }\r\n    \r\n    l\r\n    \r\nend\r\n\r\n\r\n\r\n\r\ndef display list, sum, tag = \'data\'\r\n%>\r\n<%= \"<table class=\'table\' style=\'\' id=\'\\\\#{tag.to_s}\'\".html_safe %>\r\n<%\r\nfor i in list \r\n\r\nname = i[:name]\r\ns = 0 \r\n if name.index \'*\'\r\n    s = 3\r\n    name = name[1..-1]     \r\n end\r\ncodes = i[:codes].join(\",\")\r\nx = false\r\nif codes ==\'-\'\r\nx = \'-\' \r\nend\r\nif codes ==\'--\'\r\nx = \'+\'\r\nend\r\n\r\n\r\n%>\r\n<tr style=\"<%=\'background:#eee\' if x ==\'+\'%>\">\r\n<td class=\"<%=\'strong\' if x ==\'-\'%>\">\r\n    <%=(\'&nbsp;\'*s).html_safe%><%=name%>\r\n</td>    \r\n<td>\r\n    <%=codes unless x %>\r\n</td>    \r\n\r\n<td><% if codes !=\'\' %>\r\n    <%=i[:count]%> (<%=(format(\'%.2f\',i[:count].to_f*100/sum))%>%)\r\n    <% end %>\r\n</td>    \r\n\r\n<td><% if codes !=\'\' %>\r\n    <%=i[:ward]%> (<%=(format(\'%.2f\',i[:ward].to_f*100/sum))%>%)\r\n    <% end %>\r\n</td>  \r\n\r\n<td><% if codes !=\'\' %>\r\n    <%=i[:private]%> (<%=(format(\'%.2f\',i[:private].to_f*100/sum))%>%)\r\n    <% end %>\r\n</td>  \r\n\r\n\r\n</tr>\r\n<% end %>\r\n\r\n\r\n \r\n  <%\r\n\r\n \r\nend\r\n\r\n\r\n\r\n%> \r\n\r\n\r\n\r\n<h1>1. Total admission and total cases \r\n</h1>\r\n\r\n(เนื่องจากผู้ป่วยหนึ่งคนอาจมา admit มากกว่าหนึ่งครั้ง • แยกเป็นรายเดือน และรวมยอดรายปี\r\n<%\r\n \r\n  months = {}\r\n  \r\n  for i in records\r\n  \r\n  date = i[\'admission_date\']\r\n  \r\n  k = \"\\\\#{date.strftime(\"%Y-%m\")}\"\r\n  \r\n  months[k] = [] unless months[k] \r\n  months[k] << i\r\n \r\n  end\r\n  pt = {}\r\n  cases = {}\r\n  \r\n  for i in records\r\n  \r\n    pm = pm_map[i[\'_id\']]\r\n    \r\n    date = i[\'admission_date\']\r\n    k = \"\\\\#{date.strftime(\"%Y-%m\")}\"\r\n    unless pt[pm[\'patient_id\']]\r\n        pt[pm[\'patient_id\']] = true\r\n        cases[k] = [] unless cases[k] \r\n        cases[k] << i\r\n    end\r\n  \r\n  \r\n  end\r\n%>\r\n<table class=\"table\">\r\n    <thead>\r\n    <tr>\r\n        <th>Month</th> <th>Admit No.</th> <th>Case No.</th>\r\n    </tr>\r\n    </thead>\r\n    <% for i in months.keys.sort %>\r\n    <tr>\r\n        <td>\r\n            <%=i%>\r\n        </td>\r\n        <td>\r\n            <%=fn months[i].size%>\r\n        </td>\r\n        <td>\r\n            <%=fn cases[i].size%>\r\n        </td>\r\n    </tr>\r\n    \r\n    <% end %>\r\n    <tr>\r\n        <th>Total</th><td><%=fn records.size%></td><td><%=fn pt.size%></td>\r\n    </tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<h1>2. Total deliveries\r\n</h1>\r\n\r\n• แยกเป็นรายเดือนและรวมยอดรายปี\r\n<%\r\n\r\n    case1 = []\r\n    kcase1 = {}\r\n    %w{O03* O04* O05* O001 O002 O008 O010 O011}.each do |i|\r\n       \r\n       if i.index(\'*\')\r\n       k = []\r\n       for j in k_principle_diagnosis.keys\r\n            k << j if j.index(i[0..-2])\r\n       end\r\n       \r\n       for j in k\r\n       kcase1[j]=true\r\n       case1+= k_principle_diagnosis[j].collect{|z| [z[\'admission_date\']] } if k_principle_diagnosis[j]\r\n       end\r\n       \r\n       else\r\n           \r\n       kcase1[i]=true\r\n       case1+= k_principle_diagnosis[i].collect{|z| [z[\'admission_date\']] } if k_principle_diagnosis[i]\r\n       \r\n       end\r\n       \r\n        \r\n    end\r\n    \r\n    case2 = []\r\n    \r\n    %w{Z370 Z372 Z375}.each_with_index do |i,index|\r\n    \r\n       if k_comorbidity[i]\r\n  \r\n       for j in k_comorbidity[i]\r\n  \r\n       case2 << [j[\'admission_date\'],j[\'principle_diagnosis\'],i,index+1] \r\n       \r\n       end\r\n       end\r\n        \r\n    end\r\n    \r\n    \r\n    case3 = []\r\n    mcase3 = {\'Z371\'=>1,\'Z374\'=>2,\'Z377\'=>3, \'Z373\'=>1}\r\n    \r\n    %w{Z371 Z374 Z377 Z373}.each_with_index do |i,index|\r\n    \r\n       if k_comorbidity[i]\r\n   \r\n       for j in k_comorbidity[i]\r\n  \r\n       case3 << [j[\'admission_date\'],j[\'principle_diagnosis\'],i,mcase3[i]] \r\n       \r\n       end\r\n       end\r\n        \r\n    end \r\n    \r\n    \r\n    mcase1 = {}\r\n    \r\n    for i in case1 \r\n        \r\n        k = i[0].strftime(\"%Y-%m\")\r\n        mcase1[k] = 0 unless mcase1[k]\r\n        mcase1[k] +=1\r\n    \r\n    end\r\n    \r\n    mcase2 = {}\r\n    \r\n    for i in case2 \r\n        \r\n        k = i[0].strftime(\"%Y-%m\")\r\n        mcase2[k] = 0 unless mcase2[k]\r\n        mcase2[k] +=1\r\n    \r\n    end\r\n    \r\n    mcase3 = {}\r\n    \r\n    for i in case3 \r\n        \r\n        k = i[0].strftime(\"%Y-%m\")\r\n        mcase3[k] = 0 unless mcase3[k]\r\n        mcase3[k] +=1\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n%>\r\n<%=mcase1.inspect %>\r\n<%=mcase2.inspect %>\r\n<%=mcase3.inspect %>\r\n\r\n\r\n\r\n<table class=\"table\">\r\n<thead>\r\n    <tr>\r\n        <th>&nbsp;</th> <th>Total deliveries</th> <th>Total live births</th> <th>Total stillbirths</th> <th>Total birth</th>\r\n    \r\n    </tr>\r\n    </thead>\r\n    \r\n    <% for i in mcase2.keys.sort \r\n    sum = 0\r\n    # sum+= mcase1[i] if mcase1[i]\r\n    sum+= mcase2[i] if mcase2[i]\r\n    sum+= mcase3[i] if mcase3[i]\r\n    \r\n    %>\r\n    \r\n    <tr>\r\n    <td><%=i%></td>\r\n    <td><%=mcase1[i]%></td>\r\n    <td><%=mcase2[i]%></td>\r\n    <td><%=mcase3[i]%></td>\r\n    <td><%=sum%></td>    \r\n    </tr>\r\n    \r\n    <% end %>\r\n    \r\n    \r\n</table>\r\n\r\n \r\n<h1>3. Abnormal pregnancy\r\n</h1>\r\n\r\n+ Abortion\r\n    Spontaneous abortion (O03-)\r\n    Medical abortion (O04-) Criminal abortion (O05-)\r\n\r\n+ Ectopic pregnancy (O001, O000, O002, O008)\r\nต้องดึงข้อมูลจากสถิติของ Gyn ร่วมด้วย\r\n \r\n+ Hydatidiform mole (O010,O011)\r\n \r\n\r\n<h1>4. Gestational age at birth ไม่รวมคนไข้ที่ได้รับวินิจฉัยว่าแท้ง (อายุครรภ์น้อยกว่า 22 สัปดาห์) หรือมีรหัสการแท้ง (O03-,O04-, O05-)\r\n</h1>\r\nGestational age (weeks)\r\nNo.(%)\r\n22-24\r\n25-28\r\n \r\n29-32\r\n33-36\r\n \r\n37-42\r\n>42\r\n\r\nTotal\r\nMean + SD\r\n\r\n\r\n\r\n\r\n\r\n\r\n<hr/>\r\n<%\r\n  \r\n    \r\ntemplates = <<LISTEOF\r\n1000:Less than 1,000\r\n1499:1,000-1,499\r\n1999:1,500-1,999\r\n2499:2,000-2,499\r\n2999:2,500-2,999\r\n3499:3,000-3,499\r\n3999:3,500-3,999\r\n10000:More than 4,000\r\nLISTEOF\r\n\r\n\r\n%>\r\n<% \r\n\r\ntt = templates.split(\"\\n\")\r\n\r\n\r\n\r\n    list = []\r\n    \r\n    for i in tt\r\n    t = i.split(\":\")\r\n    list<< {:title=>t[1].strip,:check=>t[0].to_i}\r\n    \r\n    end\r\n\r\n%>\r\n\r\n<h1>5. Weight distribution of singleton infants เอาเฉพาะที่มีทารกคนเดียว หรือดูจาก outcome of delivery เป็น Z370\r\n</h1>\r\n<%\r\n\r\n  sum_total = 0 \r\n\r\n  k_comorbidity[\'Z370\'].each do |i| \r\n      \r\n    baby = m_babies[i[\'fetuses_detail\'][0]]\r\n    if baby \r\n        weight=baby[\'weight\'].to_i\r\n         \r\n        for j in list\r\n            \r\n            \r\n            if weight<j[:check]\r\n               \r\n               \r\n               j[:total] = 0 unless j[:total]\r\n               j[:total] += 1\r\n               \r\n               \r\n                if i[\'principle_diagnosis\'] == \'O601\'\r\n                    j[:lt_total] = [] unless j[:lt_total]\r\n                    j[:lt_total] << weight\r\n                else\r\n                    \r\n                    j[:gt_total] = [] unless j[:gt_total]\r\n                    j[:gt_total] << weight\r\n                    \r\n                end\r\n                \r\n                \r\n                sum_total+=1\r\n                \r\n                break\r\n                \r\n            end\r\n             \r\n         \r\n        end\r\n        \r\n        \r\n         \r\n       \r\n     end\r\n      \r\n  end\r\n  \r\n  sum_lt = 0 \r\n  sum_gt = 0 \r\n  sum_ltw = 0 \r\n  sum_gtw = 0 \r\n  sum_lt2 = 0 \r\n  sum_gt2 = 0\r\n  \r\n  \r\n  for j in list\r\n    \r\n        \r\n        j[:total_percent] = \"(\\\\#{format(\'%.2f\',j[:total]*100.0/sum_total)})%\"\r\n        j[:lt_total_percent] = \"(\\\\#{format(\'%.2f\',j[:lt_total].size*100.0/j[:total])})%\" if j[:lt_total]\r\n        j[:gt_total_percent] = \"(\\\\#{format(\'%.2f\',j[:gt_total].size*100.0/j[:total])})%\" if j[:gt_total]\r\n\r\n        sum_lt += j[:lt_total].size if j[:lt_total]\r\n        sum_gt += j[:gt_total].size if j[:gt_total]\r\n        \r\n        if j[:lt_total]\r\n            for k in j[:lt_total]\r\n            \r\n            sum_ltw += k\r\n            \r\n        end\r\n        end\r\n        \r\n        if j[:gt_total]\r\n        for k in j[:gt_total]\r\n            \r\n            sum_gtw += k\r\n            \r\n        end\r\n        end\r\n        \r\n  end\r\n  \r\n  avg_lt = sum_ltw*1.0/sum_lt\r\n  avg_gt = sum_gtw*1.0/sum_gt\r\n  max_lt = 0\r\n  min_lt = 9999 \r\n  max_gt = 0\r\n  min_gt = 9999\r\n  \r\n  for j in list\r\n    \r\n        if j[:lt_total]\r\n            for k in j[:lt_total]\r\n                max_lt = k if k > max_lt\r\n                min_lt = k if k < min_lt\r\n                sum_lt2 += (k-avg_lt)**2\r\n            \r\n            end\r\n        end\r\n        \r\n        if j[:gt_total]\r\n            for k in j[:gt_total]\r\n                max_gt = k if k > max_gt\r\n                min_gt = k if k < min_gt\r\n                sum_gt2 += (k-avg_gt)**2\r\n            \r\n            end\r\n        end\r\n      \r\n        \r\n  end\r\n  \r\n  sd_lt = Math.sqrt(sum_lt2/(sum_lt-1))\r\n  sd_gt = Math.sqrt(sum_gt2/(sum_gt-1))\r\n%>\r\n\r\n\r\n\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n            <th>&nbsp;</th><th>Total</th><th>&lt;37 weeks</th><th>&gt;37 weeks</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        \r\n        <% for i in list %>\r\n        <tr>\r\n            <td>\r\n                <%=i[:title]%>\r\n            </td>\r\n            <td>\r\n                <%=i[:total]%>\r\n                <%=i[:total_percent]%>\r\n            </td>\r\n            \r\n            <td> \r\n                <%=i[:lt_total].size if i[:lt_total]%>\r\n                <%=i[:lt_total_percent]%>\r\n            </td>\r\n            <td> \r\n                <%=i[:gt_total].size if i[:gt_total]%>\r\n                <%=i[:gt_total_percent]%>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n    <tr>\r\n    <td>Total</td>  <td><%= sum_total %></td><td><%= sum_lt %> (<%=format(\"%.2f\",sum_lt*100.0/sum_total)%>%)</td><td><%= sum_gt %> (<%=format(\"%.2f\",sum_gt*100.0/sum_total)%>%)</td>\r\n    </tr>\r\n    \r\n    <tr>\r\n        <td>Mean &plusmn; SD</td> <td>&nbsp;</td>  <td><%=fm avg_lt%> &plusmn; <%=format(\'%.2f\',sd_lt)%> </td> <td><%=fm avg_gt%> &plusmn; <%=format(\'%.2f\',sd_gt)%> </td> \r\n    </tr>\r\n    <tr>\r\n        <td>Range</td><td>&nbsp;</td><td><%=fn max_lt-min_lt%></td><td><%=fn max_gt-min_gt%></td>\r\n    </tr>\r\n    </tbody>\r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n<h1>6. Weight distribution of multiple pregnancy (O300,O301)</h1>\r\n<%\r\n   list = []\r\n    \r\n    for i in tt\r\n    t = i.split(\":\")\r\n    list<< {:title=>t[1].strip,:check=>t[0].to_i,:total=>0}\r\n    \r\n    end\r\n  sum_total = 0 \r\n  \r\n  all =  []\r\n  all += k_comorbidity[\'O300\'] if k_comorbidity[\'O300\']\r\n  all += k_comorbidity[\'O301\'] if k_comorbidity[\'O301\']\r\n\r\n  all.each do |i| \r\n      \r\n    baby = m_babies[i[\'fetuses_detail\'][0]]\r\n    if baby \r\n        weight=baby[\'weight\'].to_i\r\n         \r\n        for j in list\r\n            \r\n            \r\n            if weight<j[:check]\r\n               \r\n               \r\n               j[:total] = 0 unless j[:total]\r\n               j[:total] += 1\r\n               \r\n               \r\n                if i[\'principle_diagnosis\'] == \'O601\'\r\n                    j[:lt_total] = [] unless j[:lt_total]\r\n                    j[:lt_total] << weight\r\n                else\r\n                    \r\n                    j[:gt_total] = [] unless j[:gt_total]\r\n                    j[:gt_total] << weight\r\n                    \r\n                end\r\n                \r\n                \r\n                \r\n                sum_total+=1\r\n                \r\n                break\r\n                \r\n            end\r\n             \r\n         \r\n        end\r\n        \r\n        \r\n         \r\n       \r\n     end\r\n      \r\n  end\r\n  \r\n  sum_lt = 0 \r\n  sum_gt = 0 \r\n  sum_ltw = 0 \r\n  sum_gtw = 0 \r\n  sum_lt2 = 0 \r\n  sum_gt2 = 0\r\n  \r\n  \r\n  \r\n  \r\n  for j in list\r\n    \r\n    \r\n    \r\n        \r\n        j[:total_percent] = \"(\\\\#{format(\'%.2f\',j[:total]*100.0/sum_total)})%\"\r\n        j[:lt_total_percent] = \"(\\\\#{format(\'%.2f\',j[:lt_total].size*100.0/j[:total])})%\" if j[:lt_total]\r\n        j[:gt_total_percent] = \"(\\\\#{format(\'%.2f\',j[:gt_total].size*100.0/j[:total])})%\" if j[:gt_total]\r\n\r\n\r\n\r\n\r\n        sum_lt += j[:lt_total].size if j[:lt_total]\r\n        sum_gt += j[:gt_total].size if j[:gt_total]\r\n        \r\n        \r\n        if j[:lt_total]\r\n            for k in j[:lt_total]\r\n            \r\n            \r\n            sum_ltw += k\r\n            \r\n        end\r\n        end\r\n        \r\n        \r\n        if j[:gt_total]\r\n        for k in j[:gt_total]\r\n            \r\n            sum_gtw += k\r\n            \r\n        end\r\n        end\r\n        \r\n  end\r\n  \r\n  avg_lt = sum_ltw*1.0/sum_lt\r\n  avg_gt = sum_gtw*1.0/sum_gt\r\n  max_lt = 0\r\n  min_lt = 9999 \r\n  max_gt = 0\r\n  min_gt = 9999\r\n  \r\n  \r\n  for j in list\r\n    \r\n        if j[:lt_total]\r\n            for k in j[:lt_total]\r\n                max_lt = k if k > max_lt\r\n                min_lt = k if k < min_lt\r\n                sum_lt2 += (k-avg_lt)**2\r\n            \r\n            end\r\n        end\r\n        \r\n        if j[:gt_total]\r\n            for k in j[:gt_total]\r\n                max_gt = k if k > max_gt\r\n                min_gt = k if k < min_gt\r\n                sum_gt2 += (k-avg_gt)**2\r\n            \r\n            end\r\n        end\r\n      \r\n        \r\n  end\r\n  \r\n  \r\n  sd_lt = Math.sqrt(sum_lt2/(sum_lt-1))\r\n  sd_gt = Math.sqrt(sum_gt2/(sum_gt-1))\r\n%>\r\n\r\n\r\n\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n            <th>&nbsp;</th><th>Total</th><th>&lt;37 weeks</th><th>&gt;37 weeks</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        \r\n        <% for i in list %>\r\n        <tr>\r\n            <td>\r\n                <%=i[:title]%>\r\n            </td>\r\n            <td>\r\n                <%=i[:total]%>\r\n                <%=i[:total_percent]%>\r\n            </td>\r\n            \r\n            <td> \r\n                <%=i[:lt_total].size if i[:lt_total]%>\r\n                <%=i[:lt_total_percent]%>\r\n            </td>\r\n            <td> \r\n                <%=i[:gt_total].size if i[:gt_total]%>\r\n                <%=i[:gt_total_percent]%>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n    <tr>\r\n    <td>Total</td>  <td><%= sum_total %></td><td><%= sum_lt %> (<%=format(\"%.2f\",sum_lt*100.0/sum_total)%>%)</td><td><%= sum_gt %> (<%=format(\"%.2f\",sum_gt*100.0/sum_total)%>%)</td>\r\n    </tr>\r\n    \r\n    <tr>\r\n        <td>Mean &plusmn; SD</td> <td>&nbsp;</td>  <td><%=fm avg_lt%> &plusmn; <%=format(\'%.2f\',sd_lt)%> </td> <td><%=fm avg_gt%> &plusmn; <%=format(\'%.2f\',sd_gt)%> </td> \r\n    </tr>\r\n    <tr>\r\n        <td>Range</td><td>&nbsp;</td><td><%=fn max_lt-min_lt%></td><td><%=fn max_gt-min_gt%></td>\r\n    </tr>\r\n    </tbody>\r\n</table>\r\n\r\n\r\n<%\r\nlist = <<LISTEOF\r\nSpontaneous vertex delivery:O800\r\nSpontaneous breech delivery:O801\r\nBreech assisting:O831\r\nForceps extraction:O810\r\nVacuum extraction:O814\r\nElective cesarean section:O820\r\nEmergency cesarean section:O821\r\nLISTEOF\r\n\r\n\r\n\r\n\r\n%>\r\n<%\r\n\r\nlist = formulate(list)  \r\n\r\nsum = 0 \r\np = 0 \r\nw = 0 \r\n\r\nfor i in list\r\np = 0 \r\nw = 0 \r\n\r\n\r\n    c = 0 \r\n    for code in i[:codes]\r\n        # principle diangosis\r\n        c+= k_principle_diagnosis[code].size if  k_principle_diagnosis[code]\r\n        c+= k_comorbidity[code].size if  k_comorbidity[code]\r\n        \r\n     \r\n        \r\n        if  k_principle_diagnosis[code]\r\n        p +=  k_principle_diagnosis[code].collect{|j| j if  j[\'case_type\']==\'private\'}.compact.size\r\n        w +=  k_principle_diagnosis[code].collect{|j| j if j[\'case_type\']==\'ward\'}.compact.size\r\n        end\r\n        if  k_comorbidity[code]\r\n        p +=  k_comorbidity[code].collect{|j| j if  j[\'case_type\']==\'private\'}.compact.size\r\n        w +=  k_comorbidity[code].collect{|j| j if  j[\'case_type\']==\'ward\'}.compact.size\r\n        end\r\n        \r\n    end\r\n    i[:count] = c\r\n    i[:ward] = w\r\n    i[:private] = p \r\n    sum += c\r\nend\r\n%>\r\n<h1>\r\n\r\n7. Mode of delivery of singleton infants จํานวนการคลอดตามชนิดของการคลอด และแบ่งเป็นผู้ป่วยทั่วไปหร    \r\n    \r\n</h1>\r\n<div id=\"data_7_p\"></div>\r\n<script>\r\n    $(\'#data_7\').appendTo($(\'#data_7_p\'))\r\n</script>\r\n<%= display list, sum, :data_7%>\r\n\r\n\r\n\r\n\r\n\r\n<%\r\nlist = <<LISTEOF\r\nAll by spontaneous vertex/breech delivery:O840\r\nAll by forceps or vacuum extraction:O841\r\nAll by cesarean section:O842\r\nCombination methods:O848\r\nLISTEOF\r\n\r\n%>\r\n\r\n\r\n<%\r\n\r\nlist = formulate(list)  \r\n\r\nsum = 0 \r\n\r\nfor i in list\r\n\r\n    c = 0 \r\n    p = 0\r\n    w = 0 \r\n    for code in i[:codes]\r\n        # principle diangosis\r\n        c+= k_principle_diagnosis[code].size if  k_principle_diagnosis[code]\r\n        c+= k_comorbidity[code].size if  k_comorbidity[code]\r\n        \r\n     \r\n        \r\n        if  k_principle_diagnosis[code]\r\n        p +=  k_principle_diagnosis[code].collect{|j| j if  j[\'case_type\']==\'private\'}.compact.size\r\n        w +=  k_principle_diagnosis[code].collect{|j| j if j[\'case_type\']==\'ward\'}.compact.size\r\n        end\r\n        if  k_comorbidity[code]\r\n        p +=  k_comorbidity[code].collect{|j| j if  j[\'case_type\']==\'private\'}.compact.size\r\n        w +=  k_comorbidity[code].collect{|j| j if  j[\'case_type\']==\'ward\'}.compact.size\r\n        end\r\n        \r\n    end\r\n    i[:count] = c\r\n    i[:ward] = w\r\n    i[:private] = p \r\n    sum += c\r\nend\r\n%>\r\n<h1>\r\n\r\n8. Mode of delivery of multiple pregnancy (O300,O301) จํานวนการคลอดตามชนิดของการคลอด และแบ่งเป็นผู้ป่วยทั่วไปหรืทั่วไปหร    \r\n    \r\n</h1>\r\n<div id=\"data_8_p\"></div>\r\n<script>\r\n    $(\'#data_8\').appendTo($(\'#data_8_p\'))\r\n</script>\r\n<%= display list, sum, :data_8%>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nk_principle_diagnosis \r\n<br/>\r\n\r\n<%=k_principle_diagnosis.keys.sort.collect{|i|[i,k_principle_diagnosis[i].size] } %>\r\n\r\n<hr/>\r\n\r\nk_comorbidity<br/>\r\n<%=k_comorbidity.keys.sort.collect{|i|[i,k_comorbidity[i].size] }.inspect %>\r\n<hr/>\r\n\r\nk_complication<br/>\r\n<%=k_complication.keys.sort.inspect %>\r\n<hr/>\r\n\r\nk_external_cause<br/>\r\n<%=k_external_cause.keys.sort.inspect %>\r\n<hr/>\r\n\r\nk_other_diagnosis<br/>\r\n<%=k_other_diagnosis.keys.sort.inspect %>\r\n\r\nk_operation<br/>\r\n<%=k_operation.keys.sort.inspect %>\r\n\r\nk_babies<br/>\r\n  \r\n        <%=k_babies.keys.sort.collect{|i|[i,k_babies[i].size] } %>\r\n    <hr/>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<pre>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n1. Total admission and total cases \r\n\r\n\r\n(เนื่องจากผู้ป่วยหนึ่งคนอาจมา admit มากกว่าหนึ่งครั้ง • แยกเป็นรายเดือน และรวมยอดรายปี\r\n\r\n\r\n2. Total deliveries\r\n\r\n\r\n• แยกเป็นรายเดือนและรวมยอดรายปี\r\n\r\n\r\n \r\nTable : \r\n\r\nTotal deliveries     มีรหัสอย่างใดอย่างหนึ่งในรหัสของ mode of delivery ดังข้อ 3\r\n\r\nTotal live births    นับเป็นจํานวนคน (เนื่องจากในบางรายเป็นแฝด)  \r\nZ370 (1 คน), Z 372 (2 คน), Z375 (3 คน)\r\n\r\nTotal stillbirths    นับเป็นจํานวนคน (เนื่องจากในบางรายเป็นแฝด)\r\nZ371 (ตาย 1 คน), Z374 (ตายทั้ง 2 คน) , Z377 (ตายทั้ง 3 คน) Z373 (รอด 1 คน แต่ตาย 1 คน), Z376 (บางคนตายบางคนรอด อันนี้นับจํานวนไม่ได้ อาจต้องมาดูเอง)\r\n \r\nTotal birth         Live births + Stillbirth\r\n\r\n\r\n3. Abnormal pregnancy\r\n\r\n+ Abortion\r\n    Spontaneous abortion (O03-)\r\n    Medical abortion (O04-) Criminal abortion (O05-)\r\n\r\n+ Ectopic pregnancy (O001, O000, O002, O008)\r\nต้องดึงข้อมูลจากสถิติของ Gyn ร่วมด้วย\r\n \r\n+ Hydatidiform mole (O010,O011)\r\n \r\n\r\n4. Gestational age at birth ไม่รวมคนไข้ที่ได้รับวินิจฉัยว่าแท้ง (อายุครรภ์น้อยกว่า 22 สัปดาห์) หรือมีรหัสการแท้ง (O03-,O04-, O05-)\r\n\r\nGestational age (weeks)\r\nNo.(%)\r\n22-24\r\n25-28\r\n \r\n29-32\r\n33-36\r\n \r\n37-42\r\n>42\r\n\r\nTotal\r\nMean + SD\r\n\r\n\r\n\r\n\r\n5. Weight distribution of singleton infants เอาเฉพาะที่มีทารกคนเดียว หรือดูจาก outcome of delivery เป็น Z370, Z371\r\n\r\n\r\n                                    Total               < 37 weeks  เลือกจากอายุครรภ์หรือมีรหัส O601 ร่วมด้วย               >37 weeks\r\nBirth weight (grams)                No. (%)             No.(%)                                                      No.(%)\r\n\r\nLess than 1,000\r\n1,000-1,499\r\n1,500-1,999\r\n2,000-2,499\r\n2,500-2,999\r\n3,000-3,499\r\n3,500-3,999\r\nMore than 4,000\r\nTotal\r\nMean + SD\r\nRange\r\n                \r\n6. Weight distribution of multiple pregnancy (O300,O301)\r\n\r\n                                    Total               < 37 weeks    เลือกจากอายุครรภ์หรือมีรหัส O601 ร่วมด้วย             >37 weeks\r\nBirth weight (grams)                No.(%               No.(%)                                                      No.(%)\r\nLess than 1,000\r\n1,000-1,499\r\n1,500-1,999\r\n2,000-2,499\r\n2,500-2,999\r\n3,000-3,499\r\n3,500-3,999\r\nTotal\r\nMean + SD\r\nRange\r\n\r\n7. Mode of delivery of singleton infants จํานวนการคลอดตามชนิดของการคลอด และแบ่งเป็นผู้ป่วยทั่วไปหรือผู้ป่วยพิเศษ\r\nSpontaneous vertex delivery O800\r\nSpontaneous breech delivery O801\r\nBreech assisting O831\r\nForceps extraction O810\r\nVacuum extraction O814\r\nElective cesarean section O820\r\nEmergency cesarean section O821\r\nTotal\r\n\r\n8. Mode of delivery of multiple pregnancy (O300,O301) จํานวนการคลอดตามชนิดของการคลอด และแบ่งเป็นผู้ป่วยทั่วไปหรือผู้ป่วยพิเศษ\r\nAll by spontaneous vertex/breech delivery O840\r\nAll by forceps or vacuum extraction O841\r\nAll by cesarean section O842\r\nCombination methods O848\r\nTotal\r\n\r\n9. Indication of elective cesarean section (O820)\r\nCPD: O331,O335, O339\r\nAbnormal presentation\r\nBreech presentation O321 Shoulder presentation O322\r\nOther ที่เหลือทั้งหมด O320, O323-O326\r\nrevious C/S or myomectomy O342\r\nMultiple pregnancy O300,O301, O325\r\nPlacenta previa O440,O441\r\nOthers ที่เหลือทั้งหมด\r\nTotal\r\n\r\n10. Indication of emergency cesarean section (O821)\r\nCPD O648, O651-654, O662, O663\r\nAbnormal presentation\r\nBreech presentation O641 Shoulder presentation O644 Other ที่เหลือทั้งหมด O642,O643,O645\r\nPrevious C/S or myomectomy O655\r\nMultiple pregnancy O300,O301, O325\r\nFetal distress/Non-reassuring FHR O682,O688\r\nPlacenta previa O440,O441\r\nOthers ที่เหลือทั้งหมด\r\nTotal\r\n\r\n11. Obstetrics complications\r\nMultiple pregnancy(O300, O301, O325, O430)\r\nFetal anomalies (O350, O358)\r\nPreterm delivery (O601, O603)\r\nPreterm labor without delivery (O600)\r\nPROM (O420, O421, O422, O429)\r\nIUGR (O365)\r\nOligohydraminos (O410)\r\nPolyhydraminos (O40)\r\nGestational DM (O244)\r\nPreeclampsia (O140-O142)\r\nPreeclampsia without severe features (O140) Preeclampsia with severe features (O141, O142) Superimposed preeclampsia (O11)\r\nEclampsia (O150,O151) Postpartum eclampsia (O152)\r\nPlacenta previa (O440, O441)\r\nPlacenta previa without hemorrhage (O440) Placenta previa with hemorrhage (O441)\r\nAbruptio placenta (O450, O458)\r\nAbruptio placenta without coagulation defect (O458)\r\nAbruptio placenta with coagulation defect (O450)\r\nRupture uterus (O710,O711)\r\nProlapse cord (O690)\r\nShoulder dystocia (O660)\r\nLow Apgar score (at 5 minutes < 7)\r\n\r\n12. Maternal complications\r\nTeenage pregnancy (Z356)\r\nAdvanced maternal age (Z355, Z358)\r\nAnemia O990\r\nThalassemia (D560,D561,D563,D582,D569) Iron deficiency anemia (D500, D509)\r\nUnspecified (D649)\r\nHypertension (O100)\r\nDM (O240,O241)\r\nHeart disease (O994)\r\nCongenital heart disease (Q20- -Q28-)\r\nObesity (E660-E669)\r\nThyroid disease (E04-, E05-, E06-)\r\nGynecologic conditions\r\nMyoma uteri (O341)\r\nBenign ovarian cyst (O348 +D27) Malignant ovarian tumor (C56) Uterine anomalies (O345) Cervical incompetence (O343)\r\nSyphilis (O981)\r\nHIV infection (Z21, B20-B24)\r\nUrinary tract infection (O230, O231)\r\nDrug dependence or smoking (F10- - F19-)\r\nMaternal death (ดูจาก discharge status ว่า death) ระบุสาเหตุการเสียชีวิต\r\n\r\n\r\n13. Complications of the puerperium\r\nPerineal tear\r\nFirst degree perineal tear O700 Second degree perineal tear O701 Third degree perineal tear O702 Fourth degree perineal tear O703\r\nWound complication\r\nDisruption of episiotomy wound O901\r\nDisruption of cesarean section wound O900\r\nWound infection (episiotomy or cesarean section wound) O860\r\nHematoma of episiotomy wound O902\r\nImmediate postpartum hemorrhage (O721) และแยกสาเหตุ Uterine atony (O622)\r\nTear genital tract (O713,O714)\r\nRetained placenta (O720)\r\nRuptured uterus (O711) Other\r\nDelayed postpartum hemorrhage (O722)\r\nPuerpural infection (O85)\r\nUrinary tract infection (O862)\r\nRetained placenta (O720, O730, O731)\r\nIntraabdominal injury during delivery (O715, T812) Urinary tract injury during delivery (O715) Other organ injury (T812)\r\nAmniotic fluid embolism (O881)\r\n\r\n\r\n14. Obstetrics procedures\r\nSpontaneous delivery (vertex/breech) 7359\r\nForceps extraction 721,7221,7231,724\r\nVacuum extraction 7271\r\nCesarean section 740,741\r\nCesarean hysterectomy (740/1 + 6849,6839)\r\nHysterotomy (7491)\r\nManual removal of placenta (754)\r\nTamponade of uterus (758) แยกเป็น B-lynch หรือ Balloon tamponade ตามที่ลงเพิ่มไว้\r\nB-Lynch\r\nBallon tamponade\r\nHypogastric artery ligation (3886)\r\nRe-operation after delivery (7591,7592,7569, 5412, 7552)\r\nEvacuation of hematom (7591, 7592)\r\nCervical cerclage (6759)\r\nD&C following abortion of delivery (6902)\r\nSuction curettage or MVA (6951)\r\nResuture episiotomy wound (7569)\r\nTR (6632)\r\n\r\n15. Summary (สรุปเฉพาะรายป)ี\r\nTotal deliveries (ครั้ง)\r\nTotal births (คน)\r\nTotal live births (คน)\r\nCesarean section rate (%)\r\nจํานวนคนที่ทํา CS (740,741) หารจํานวนการคลอดทั้งหมด (total delivery)\r\nStillbirth rate (/1,000 total births)\r\nจํานวนทารกที่คลอดเสียชีวิตหารจํานวนทารกคลอดทั้งหมด (Total birth) คูณ 1,000\r\nMaternal death rate (/100,000 livebirths)\r\nจํานวนมารดาที่เสียชีวิตหารจํานวนการคลอดทารกมีชีพ (Total live births) คูณ 100,000\r\n</pre>\r\n\r\n\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2017-10-02 03:07:16','2017-10-02 03:07:16','obstetrics_report_partial',''),(3182,'obstetrics_report',1185,2,'<style>\r\n    .field-label{\r\n        width:80px;\r\n        text-align:right;\r\n        border:0px solid;\r\n        line-height: 3em;\r\n        vertical-align: middle;\r\n        float:left;\r\n    }\r\n    .field-input{\r\n        width:120px;\r\n        float:left;\r\n        margin-left:5px;\r\n        vertical-align: middle;\r\n        line-height: 3em;\r\n        border:0px solid;\r\n    }\r\n    .field-input input,select{\r\n        margin-top:5px;\r\n    }\r\n    \r\n    .field-data{\r\n        display: table-cell;\r\n        border:0px solid;\r\n        width:220px;\r\n        height:3em;\r\n        float:left;\r\n    }\r\n    \r\n    .status_cls{\r\n		width:100px\r\n    }\r\n    \r\n<%\r\n    malignant_list = %w{C541 C542 C548 C530 C531 C538 C56 C796 C570 C52 C510 C511 C512 C518 C482 C786 D392 C58 C578 C80 C509 C189}\r\n    malignant_list.each do |i|\r\n%>\r\n.<%= i %> { background:lightsalmon; }\r\n<% end %>\r\n</style>\r\n<%\r\n\r\n    models = get_model\r\n\r\n    c = models[:gynecology].count\r\n\r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n        <div class=\"w-box-header\">\r\n			<h3>Search</h3>\r\n		</div>\r\n        <div class=\"w-box-content cnt_a\">\r\n<%= form_for :search,:url=>\'obstetrics_report_partial?update=result-panel\',:html=>{:style=>\'margin-bottom:0px\'}, :remote=>true do |f| %>\r\n	    <span class=\"field-data\"> \r\n			<label class=\"field-label\">Start Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :sdate, :value=>\'\',:id=>\'sdate\',:style=>\"width:100%\"%></div>\r\n		</span> \r\n		<span class=\"field-data\"> \r\n			<label class=\"field-label\">End Date :  </label>\r\n			<div class=\"field-input\" ><%= f.text_field :edate, :value=>\'\',:id=>\'edate\',:style=>\"width:100%\"%></div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n\r\n		<div class=\'clear\'></div>\r\n\r\n		<span class=\"field-data\">\r\n		    <div class=\"field-input\"><%=f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:disable_with=>\'Loading...\'}%> </div>\r\n		</span>\r\n		<div class=\'clear\'></div>\r\n<script>\r\n    $(\"#sdate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.beginning_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n    $(\"#edate\").kendoDatePicker({\r\n    	value: \'<%= Time.now.end_of_month.strftime(\"%d/%m/%Y\") %>\'\r\n    });\r\n</script>\r\n<% end %>\r\n\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class=\'clear\'></div>\r\n<br/>\r\n<div id=\'result-panel\'></div>\r\n\r\n',NULL,NULL,NULL,'2017-10-02 03:07:40','2017-10-02 03:07:40','obstetrics_report',''),(3183,'document_name',1252,1,'\'otology_register_pattern\'',NULL,NULL,NULL,'2017-10-05 01:25:08','2017-10-05 01:25:08',NULL,NULL),(3184,'get_emr_report',574,3,'<%= render :inline=>this.init%><%  \r\n    date = Time.now\r\n   \r\n   \r\n   \r\n   \r\n    if params[:date] \r\n        date = Time.parse(params[:date])\r\n    end\r\n   \r\n    start_date = date.beginning_of_month \r\n    end_date = date.end_of_month\r\n    \r\n    document_name = \'colonoscopy\'\r\n    document_name = params[:report] if params[:report]\r\n   \r\n    provider_field = \'endoscopist_1\'\r\n    provider_field = params[:provider] if params[:provider]\r\n    \r\n   \r\n    models = get_model\r\n    \r\n    m_patients = {}\r\n    ms = nil\r\n    records = nil\r\n    mapps = nil\r\n    apps = nil\r\n    patients = nil\r\n    providers = nil\r\n    m_providers = nil\r\n    \r\n    clinic_id = {}\r\n    clinic_id = eval params[:clinic_id] if params[:clinic_id]\r\n    \r\n    report_type = {}\r\n    report_type = eval params[:report_type] if params[:report_type]\r\n    \r\n    #   Parameters: {\"clinic_id\"=>\"{\'field\'=>\'status\',\'map\'=>{\'Elective\'=>660301,\'Emergency\'=>660301,\'Extratime\'=>660302}}\", \"report_type\"=>\"{\'document\'=>\'pre_scope\',\'field\'=>\'type_of_patient\'}\", \"report\"=>\"colonoscopy\", \"provider\"=>\"endoscopist_1\", \"date\"=>\"2018-08-14\", \"id\"=>\"5b725db6e138234d80000262\", \"solution_name\"=>\"colo\", \"project_name\"=>\"colo\", \"service\"=>\"Api\", \"opt\"=>\"get_emr_report\"}\r\n\r\n    \r\n    if params[:id]\r\n    \r\n    \r\n        ms = @patient_module_model.collection.find(:_id=>BSON::ObjectId(params[:id])).to_a\r\n        mapps = @patient_module_model.collection.find(:_id=>ms[0][\'parent_id\']).to_a\r\n        \r\n        apps = models[:appointment].collection.find(:_id=>mapps[0][\'module_id\']).to_a\r\n     \r\n        patients = @patient_model.collection.find({:_id=>mapps[0][\'patient_id\']},:fields=>{\'hn\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'prefix_name\'=>1}).to_a\r\n        \r\n        m_patients[patients[0][\'_id\']] = patients[0]\r\n        \r\n        \r\n       \r\n        # providers = models[:provider].collection.find({:provider_type=>\'1\',:_id=>{\'$in\'=>[records[0][provider_field],apps[0][\'provider_id\'] ]}}, :fields=>{:name=>1, :ref_number=>1})\r\n    \r\n        providers = models[:provider].collection.find({}, :fields=>{:name=>1, :ref_number=>1})\r\n\r\n\r\n        \r\n        \r\n        fields = {provider_field=>1,:updated_at=>1}\r\n        \r\n        \r\n        if clinic_id \r\n               \r\n               \r\n               \r\n               \r\n           if clinic_id[\'field\']\r\n                \r\n                \r\n                \r\n                fields[clinic_id[\'field\']] = 1\r\n               \r\n           end\r\n                \r\n        end\r\n        \r\n        \r\n        #  records = models[document_name.to_sym].collection.find({:_id=>{\'$in\'=>ms.collect{|i| i[\'module_id\']}}},:fields=>{provider_field=>1,:updated_at=>1}).to_a\r\n         records = models[document_name.to_sym].collection.find({:_id=>{\'$in\'=>ms.collect{|i| i[\'module_id\']}}},:fields=>fields).to_a\r\n\r\n\r\n        \r\n        \r\n    else\r\n    # mtoday = @patient_module_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day,:module_name=>\"\\\\#{@current_project.name}#appointment\") \r\n        apps = models[:appointment].collection.find(\'date\'=>{\'$gte\'=>start_date,\'$lte\'=>end_date}).to_a \r\n        mapps = @patient_module_model.collection.find(:module_id=>{\'$in\'=>apps.collect{|i| i[\'_id\']}} ).to_a\r\n        \r\n        patients = @patient_model.collection.find({:_id=>{\'$in\'=>mapps.collect{|i| i[\'patient_id\']}}},:fields=>{\'hn\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'prefix_name\'=>1}).to_a\r\n    \r\n        for i in patients\r\n            m_patients[i[\'_id\']] = i \r\n        end\r\n        \r\n        ms = @patient_module_model.collection.find(:parent_id=>{\'$in\'=>mapps.collect{|i| i[\'_id\']}},:module_name=>\"\\\\#{@current_project.name}#\\\\#{document_name}\").to_a \r\n\r\n        providers = models[:provider].collection.find({}, :fields=>{:name=>1, :ref_number=>1})\r\n        \r\n        \r\n        \r\n        fields = {provider_field=>1,:updated_at=>1}\r\n        \r\n        \r\n        \r\n        if clinic_id \r\n               \r\n               \r\n           if clinic_id[\'field\']\r\n                \r\n                \r\n                fields[clinic_id[\'field\']] = 1\r\n               \r\n           end\r\n                \r\n        end\r\n    \r\n    \r\n        records = models[document_name.to_sym].collection.find({:_id=>{\'$in\'=>ms.collect{|i| i[\'module_id\']}}},:fields=>fields).to_a\r\n        \r\n        \r\n    end\r\n \r\n    \r\n    \r\n    \r\n    m_apps = {}\r\n    \r\n    for i in apps\r\n        m_apps[i[\'_id\']] = i\r\n    end\r\n    \r\n    m_mapps = {}\r\n    \r\n    for i in mapps\r\n        m_mapps[i[\'_id\']] = i\r\n    end\r\n    \r\n    \r\n    m_providers = {}\r\n    for i in providers\r\n        m_providers[i[\'_id\']] = i\r\n    end\r\n\r\n    m_records = {}\r\n    \r\n    for i in records\r\n        m_records[i[\'_id\']] = i \r\n    end\r\n    \r\n    list = []\r\n    \r\n    \r\n            \r\n    if report_type \r\n        \r\n        if d = report_type[\'document\']\r\n        \r\n        model = models[d.to_sym]\r\n        \r\n        docs = @patient_module_model.collection.find(:parent_id=>{\'$in\'=>mapps.collect{|i| i[\'_id\']}},:module_name=>\"\\\\#{@current_project.name}#\\\\#{d}\").to_a \r\n        m_docs = {}\r\n        for i in docs\r\n            m_docs[i[\'parent_id\']] = i \r\n        end\r\n        \r\n        drecords = model.collection.find({:_id=>{\'$in\'=>docs.collect{|i| i[\'module_id\']}}}, :fields=>{report_type[\'field\']=>1}).to_a\r\n        \r\n        m_drecords = {}\r\n        for i in drecords\r\n            m_drecords[i[\'_id\']] = i[report_type[\'field\']]\r\n        end\r\n        # params[:drecord] = m_docs.inspect \r\n        \r\n        for i in ms \r\n        \r\n            record = m_records[i[\'module_id\']]\r\n        \r\n            drecord = \"\"\r\n            drecord = m_drecords[m_docs[i[\'parent_id\']][\'module_id\']] if m_docs[i[\'parent_id\']]\r\n            \r\n            if drecord\r\n                record[report_type[\'field\']] = drecord #drecord[report_type[\'field\']]         \r\n            end\r\n        \r\n        end\r\n        \r\n        elsif report_type[\'default\']\r\n            for i in ms\r\n                record = m_records[i[\'module_id\']]\r\n                record[report_type[\'field\']] = report_type[\'default\']\r\n            end\r\n        end\r\n            \r\n    end\r\n\r\n\r\n    \r\n    \r\n \r\n    for i in ms \r\n        record = m_records[i[\'module_id\']]\r\n        if record\r\n            m_app = m_mapps[i[\'parent_id\']]\r\n            app = m_apps[m_app[\'module_id\']]\r\n            p_id = record[provider_field]\r\n            provider = m_providers[p_id]\r\n            provider = m_providers[app[\'provider_id\']] unless provider \r\n            \r\n            date = app[\'date\']\r\n            patient = m_patients[m_app[\'patient_id\']]\r\n            \r\n            \r\n            hn = patient[\'hn\']\r\n            \r\n            if t = hn.split(\"/\")\r\n               \r\n               hn = \"\\\\#{t[-1]}\\\\#{format(\'%06d\',t[0].to_i)}\"\r\n                \r\n            end\r\n          \r\n            \r\n            provider= {} unless provider\r\n    \r\n            \r\n            # \r\n            o = {:id=>i[\'_id\'],:date=>app[\'date\'],:hn=>hn, \r\n            \r\n            :patient=>\"\\\\#{patient[\'prefix_name\']}\\\\#{patient[\'first_name\']} \\\\#{patient[\'last_name\']}\", \r\n            \r\n            :provider=>\"\\\\#{provider[\'name\']}\",\r\n            \r\n            :pro_code=>provider[\'ref_number\'], \r\n            \r\n            :updated_at=>record[\'updated_at\'],\r\n            \r\n            :report_type=>\'OPD\',\r\n            \r\n            :clinic_id=>\'\'\r\n            \r\n            }\r\n            \r\n            \r\n        \r\n        \r\n        \r\n            \r\n            if clinic_id\r\n               \r\n               \r\n               \r\n               unless clinic_id[\'document\']\r\n                \r\n                \r\n                if clinic_id[\'default\']\r\n                    \r\n                     o[:clinic_id] = clinic_id[\'default\']\r\n                    \r\n                end\r\n                \r\n                if v = record[clinic_id[\'field\']] and clinic_id[\'map\']\r\n                    \r\n                    \r\n                    o[:clinic_id] = v\r\n                    \r\n                    o[:clinic_id] = clinic_id[\'map\'][v] if  clinic_id[\'map\']\r\n                    \r\n                    \r\n                end\r\n               \r\n               end\r\n                \r\n            end\r\n            \r\n            if report_type\r\n               \r\n               o[:report_type] = record[report_type[\'field\']]\r\n                \r\n            end\r\n            \r\n            \r\n            \r\n            url = \"http://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{document_name.humanize}/pdf?id=\\\\#{o[:id]}\"\r\n            \r\n            \r\n            list << [o[:id],o[:date],o[:updated_at],o[:hn],o[:patient],o[:provider],o[:pro_code],url,o[:clinic_id], o[:report_type]] \r\n            \r\n        end\r\n    \r\n    end\r\n    \r\n    msg = {:return=>200,:msg=>params.inspect ,:data=>list}\r\n    \r\n %><%=msg.to_json.html_safe %>\r\n ',NULL,NULL,NULL,'2017-10-05 05:04:14','2017-10-05 05:04:14','get_emr_report','*'),(3185,'document_name',1254,1,'\'site\'',NULL,NULL,NULL,'2017-10-05 17:06:41','2017-10-05 17:06:41',NULL,NULL),(3186,'document_name',1255,1,'\'patient\'',NULL,NULL,NULL,'2017-10-05 17:08:03','2017-10-05 17:08:03',NULL,NULL),(3187,'document_name',1256,1,'\'provider\'',NULL,NULL,NULL,'2017-10-05 17:08:34','2017-10-05 17:08:34',NULL,NULL),(3188,'document_name',1257,1,'\'site_report\'',NULL,NULL,NULL,'2017-10-05 17:09:45','2017-10-05 17:09:45',NULL,NULL),(3189,'document_name',1258,1,'\'record\'',NULL,NULL,NULL,'2017-10-05 17:11:48','2017-10-05 17:11:48',NULL,NULL),(3190,'index',1253,2,'<%= view :fitscreen %>\r\n<h1>Hello World</h1><br>\r\n<i>This is generated by system.</i>\r\n\r\n\r\n<table class=\"table\">\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    sites = models[:site].all\r\n    \r\n    for site in sites\r\n    \r\n    reports = models[:site_report].where(:site_id=>site.id).all\r\n    \r\n    for i in reports\r\n    \r\n  \r\n  \r\n%>\r\n<% %w{ 2017 2018}.each do |x|  %>\r\n\r\n\r\n<tr>\r\n<td><%=link_to \"\\\\#{site.domain} \\\\#{site.solution} \\\\#{site.application} \\\\#{i.name} ... update \\\\#{x}\", \"update?site_id=\\\\#{site.id}&report_id=\\\\#{i.id}\", :target=>\'_blank\'  %>\r\n</td>\r\n<% 12.times do |j| \r\n  start = Date.parse(format(\"\\\\#{x}-%02d-01\",j+1)).to_mongo\r\n  stop = start.end_of_month\r\n  count = models[:record].where(:report_id=>i.id,:date=>{\'$lte\'=>stop,\'$gte\'=>start}).count\r\n#   f = models[:record].where(:report_id=>i.id).last\r\n%>\r\n<td><%=count%> \r\n<%=link_to \"\\\\#{x}-\\\\#{j+1}\", \"update?site_id=\\\\#{site.id}&report_id=\\\\#{i.id}&date=\\\\#{format(\'%s-%02d-01\',x,j+1)}\", :target=>\'_blank\'  %>\r\n\r\n</td>\r\n<% end %>    \r\n    \r\n \r\n</tr>\r\n   <% end %>  \r\n<% end %><% end %>\r\n</table>',NULL,NULL,NULL,'2017-10-05 17:15:26','2017-10-05 17:15:26','',''),(3191,'update',1253,3,'\r\n<%\r\n\r\n   \r\n\r\n\r\n    models = get_model\r\n    \r\n    site = models[:site].find params[:site_id]\r\n    \r\n    report = models[:site_report].find params[:report_id]\r\n    \r\n    date = Time.now.strftime(\"%Y-%m-%d\")\r\n    date = params[:date] if params[:date]\r\n    query=\"\"\r\n    # query = {:clinic_id=>eval(\"{\\\\#{report.clinic_id_data}}\")}\r\n    query =  \"{\\\\#{report.clinic_id_data}}\"\r\n    query2 =   \"{\\\\#{report.report_type_data}}\"\r\n    data = \"clinic_id=\\\\#{URI.escape(query)}&report_type=\\\\#{URI.escape(query2)}\"\r\n    \r\n    url = \"\'http://\\\\#{site.domain}/\\\\#{site.solution}/\\\\#{site.application}/Api/get_emr_report?report=\\\\#{report.name}&provider=\\\\#{report.provider_field}&date=\\\\#{date}\'\"\r\n    if params[:from_time] and params[:to_time] \r\n        from_time = params[:from_time]\r\n        to_time = params[:to_time]\r\n        url = \"\'http://\\\\#{site.domain}/\\\\#{site.solution}/\\\\#{site.application}/Api/get_emr_report?report=\\\\#{report.name}&provider=\\\\#{report.provider_field}&from_time=\\\\#{from_time}&to_time=\\\\#{to_time}\'\"\r\n    %>\r\n    <%=URI.escape(url).inspect%>\r\n    <%\r\n\r\nelse\r\n    \r\n    \r\n%> \r\n<%= data.inspect  %>\r\n<%= url %><br/>\r\n<%= date %><br/>\r\n<%\r\n\r\n    msg =  JSON.parse `curl --data \"\\\\#{data}\" \\\\#{url}`\r\n    \r\n    %>\r\n    <%= msg[\'msg\'] %><br/>\r\n    <%\r\n    \r\n    data = msg[\'data\']\r\n    \r\n    providers = models[:provider].where(:site_id=>site.id).all\r\n    \r\n    mp = {}\r\n    \r\n    for i in providers\r\n        mp[i.name] = i\r\n    end\r\n    \r\n    records = models[:record].collection.find(:site_id=>site.id, :report_id=>report.id).to_a\r\n    m = {}\r\n    \r\n    for i in records\r\n        m[i[\'record_id\']] = i\r\n    end\r\n    \r\n    \r\n    count = 3\r\n    \r\n    for i in data\r\n    \r\n        # r = models[:record].where(:record_id=>BSON::ObjectId(i[0])).first\r\n        r = m[BSON::ObjectId(i[0])]\r\n        \r\n        \r\n        unless r\r\n            \r\n            provider = mp[i[5]]\r\n            \r\n            unless provider \r\n                provider = models[:provider].create :name=>i[5], :code=>i[6], :site_id=>site.id\r\n                mp[provider.name] = provider\r\n            end\r\n            \r\n            patient = models[:patient].where(:hn=>i[3]).first\r\n            unless patient \r\n                patient = models[:patient].create :hn=>i[3], :name=>i[4]\r\n            end\r\n            \r\n            r = models[:record].create :record_id=>BSON::ObjectId(i[0]), :site_id=>site.id, :provider_id=>provider.id, :report_id=>report.id, :patient_id=>patient.id, :url=>i[7],:date=>i[1],:clinic_id=>i[8], :report_type=>i[9], :updated=>i[2]\r\n        \r\n          url = \"\\\\#{r.url}\"\r\n          attach_pdf = \"http://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/pacs/Home/attach_pdf?id=\\\\#{r.id}\"\r\n \r\n    path = \"pacs\"\r\n    require_relative \'app/models/workers/pdf_generator\'\r\n    if true || count > 0 \r\n    PdfGenerator.enqueue :url=>url,:id=>r.id,:path=>path,:return=>attach_pdf\r\n    count-=1\r\n    end\r\n        \r\n        \r\n        end\r\n        \r\n    \r\n    end\r\n\r\n%>\r\n\r\n<%= data.inspect %>\r\n<% end %>',NULL,NULL,NULL,'2017-10-05 17:37:23','2017-10-05 17:37:23','update',''),(3192,'attach_pdf',1253,3,'<%\r\n   if params[:path]\r\n       \r\n    document = get_document \'record\'\r\n    field = document.find_by_column_name \'report\'\r\n    models = get_model\r\n    record = models[:record].find params[:id]\r\n    \r\n    if record\r\n        att = document.attach_field_file field.id, params[:path].split(\'/\')[-1] , \'\', File.open(params[:path])\r\n        `rm params[:path]`\r\n        record.update_attributes :report=>att.id\r\n    end\r\n    \r\nend\r\n%>\r\nOK\r\n<%',NULL,NULL,NULL,'2017-10-08 09:36:43','2017-10-08 09:36:43','attach_pdf','*'),(3193,'show',1258,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n\r\n<%= link_to \'Export\'.html_safe, \"export?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2017-10-08 10:03:44','2017-10-08 10:03:44','show',''),(3194,'export',1258,3,'<%\r\n    \r\n    models = get_model \r\n    \r\n    record = models[:record].find params[:id]\r\n    \r\n    path = @current_project.get_setting \'export_path\'\r\n  \r\n    \r\n    if record\r\n        \r\n        att =  @current_project.attachment_model.find record.report\r\n        grid = Mongo::Grid.new(MongoMapper.database)\r\n        ofile = grid.get(att.file_id)\r\n        \r\n        patient = models[:patient].find record.patient_id\r\n        provider = models[:provider].find record.provider_id\r\n        report = models[:site_report].find record.report_id\r\n        site = models[:site].find record.site_id\r\n        provider_code = \'0000000\'\r\n        provider_code = provider.code if provider and provider.code!=\"\"\r\n        report_type = \'OPD\'\r\n        report_type = record.report_type if record.report_type and record.report_type!=\'\'\r\n        \r\n        \r\n        fname = \"\\\\#{patient.hn}_\\\\#{0}_\\\\#{record.date.strftime(\"%d-%m-%Y\")}_\\\\#{provider_code}_\\\\#{record.clinic_id}_\\\\#{report_type}_\\\\#{report.name.humanize}_1.pdf\"\r\n        fpath = File.join(path,site.write_path,fname)\r\n        f = File.open(fpath,\'w\')\r\n        data =  ofile.read.force_encoding(\'utf-8\') \r\n        record.update_attributes :exported=>\'true\'\r\n        f.write data\r\n        f.close\r\n       %>\r\n       \r\n       <%=fpath    %>\r\n       <%\r\n    #   http://emr-life.com/content/esm/ehr/pacs/content/record/report/59d9f89f790f9b1e3d0002d5.pdf\r\n        \r\n    end\r\n    \r\n\r\n%>',NULL,NULL,NULL,'2017-10-08 10:17:32','2017-10-08 10:17:32','export',''),(3195,'document_name',1259,1,'\'otology_register_pattern\'',NULL,NULL,NULL,'2017-10-11 03:32:27','2017-10-11 03:32:27',NULL,NULL),(3196,'print',1259,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:otology_register_pattern].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto;  margin-top: 5px;} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color: #0028ff;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto; margin-top: 5px;} \r\n}\r\n\r\n#box{\r\n    width:300px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:0px;\r\n    font-size:0.8em;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n\r\n    width:100%;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<center><img src=\"/esm/cusys/ent2/cuent2.jpg\" /></center>\r\n<center> <div id=\"logoleft\" style=\"margin-left:0px\"><h2>Otology register pattern</h2>\r\n</div>\r\n\r\n\r\n</center>\r\n\r\n\r\n\r\n</div><br /><br /><br />\r\n<div id=\"page\">\r\n\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n\r\n\r\n\r\n\r\n\r\n\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> ชื่อ-สกุล : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'ไม่ระบุ\'\r\n    if patient.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>เพศ : </strong><%= gender %> &nbsp; <strong>อายุ :&nbsp;</strong>\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D-->\r\n      </td>\r\n          <td>\r\n         \r\n              <% if record[\'operative_date\']!=nil %>\r\n\r\n<label>Operative date : </label><v><%=render_value \'operative_date\'%>\r\n\r\n\r\n<% end%>\r\n          </td>\r\n          \r\n      </tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n \r\n	<hr style=\"margin-top: 5px;\"/>\r\n    \r\n\r\n\r\n<div style=\"float:left;width: 100%; font-size:13px\">\r\n  \r\n<% if record[\'xxx\']!=\"\" %>\r\n\r\n<% end%>\r\n\r\n\r\n\r\n<div id=\"otology_diagnosis\" class=\"  portlet \" style=\"border:0px solid blue;width:700px;margin: 0 0.5em 0.5em 0;float:left;; margin-top:10px\">\r\n\r\n\r\n<span class=\"\"><label>Diagnosis : </label></span>\r\n\r\n<v><%=render_value \'otology_diagnosis\'%></v>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div id=\"diagnosis_group\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n\r\n\r\n<span class=\"\"><label>Diagnosis group : </label></span>\r\n\r\n<v><%=render_value \'diagnosis_group\'%></v>  \r\n<% if record[\'malignancy_detail\']!=\"\" %>\r\n( <v><%=render_value \'malignancy_detail\'%></v> )\r\n<% end%>\r\n</div>\r\n\r\n<% if record[\'benign_type\']!=\"\" %>\r\n<div id=\"benign_type\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n\r\n\r\n\r\n<span class=\"\"><label>Type : </label></span>\r\n<v><%=render_value \'benign_type\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"operation\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:500px;\">\r\n\r\n\r\n<span class=\"\"><label>Operation : </label></span>\r\n\r\n<v><%=render_value \'operation\'%></v>\r\n</div>\r\n\r\n\r\n\r\n<% if record[\'ex_stapes\']!=\"\" %>\r\n<div id=\"ex_stapes\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<span class=\"\"><label>Stapes : </label></span>\r\n<v><%=render_value \'ex_stapes\'%></v>\r\n</div>\r\n<% end%>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<% if record[\'ex_ossicular_chain_reconstruction\']!=\"\" %>\r\n<div id=\"ex_ossicular_chain_reconstruction\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;min-height:30px;\">\r\n<span class=\"\"><label>Ossicular chain reconstruction : </label></span>\r\n<v><%=render_value \'ex_ossicular_chain_reconstruction\'%></v>\r\n</div>\r\n\r\n<% end%>\r\n\r\n<% if record[\'operation_other\']!=\"\" %>\r\n<div id=\"operation_other\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;min-height:30px;\">\r\n<span class=\"\"><label>Other: </label></span>\r\n<v><%=render_value \'operation_other\'%></v>\r\n</div>\r\n\r\n<% end%>\r\n\r\n\r\n\r\n	<div id=\"785-F3480667038\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Finding - External ear</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"external_ear_canal\" class=\"  portlet \" style=\"border:0px solid blue;width:800px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>External ear canal : </label></span>\r\n<br />\r\n<v><%=render_value \'external_ear_canal\'%> <%=render_value \'external_ear_abnormal\'%></v> \r\n</div>\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"tympanic_membrane\" class=\"  portlet \" style=\"border:0px solid blue;width:800px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Tympanic membrane : </label></span>\r\n<br />\r\n<v><%=render_value \'tympanic_membrane\'%> <%=render_value \'tympanic_membrane_abnormal\'%></v>\r\n</div>\r\n\r\n\r\n<div id=\"middle_ear\" class=\"  portlet \" style=\"border:0px solid blue;width:800px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Middle Ear : </label></span>\r\n<br />\r\n<v><%=render_value \'middle_ear\'%> <%=render_value \'middle_ear_abnormal\'%></v>\r\n</div>\r\n\r\n\r\n\r\n<div id=\"ossicle\" class=\"  portlet \" style=\"border:0px solid blue;width:800px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Ossicle : </label></span>\r\n<br />\r\n<v><%=render_value \'ossicle\'%> <%=render_value \'ossicle_abnormal\'%></v>\r\n</div>\r\n\r\n\r\n\r\n<div id=\"malleus\" class=\"  portlet \" style=\"border:0px solid blue;width:800px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Malleus : </label></span>\r\n<br />\r\n<v><%=render_value \'malleus\'%></v>\r\n</div>\r\n\r\n<div id=\"incus\" class=\"  portlet \" style=\"border:0px solid blue;width:800px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Incus : </label></span>\r\n<br />\r\n<v><%=render_value \'incus\'%></v>\r\n</div>\r\n\r\n\r\n\r\n<div id=\"stapes\" class=\"  portlet \" style=\"border:0px solid blue;width:800px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Stapes : </label></span>\r\n<br />\r\n<v><%=render_value \'stapes\'%></v>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div id=\"facial_nerve\" class=\"  portlet \" style=\"border:0px solid blue;width:800px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Facial nerve : </label></span>\r\n<br />\r\n<v><%=render_value \'facial_nerve\'%></v>\r\n</div>\r\n\r\n<div id=\"mastoid\" class=\"  portlet \" style=\"border:0px solid blue;width:800px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Mastoid : </label></span>\r\n<br />\r\n<v><%=render_value \'mastoid\'%> <%=render_value \'mastoid_abnormal\'%></v>\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n  \r\n  \r\n  \r\n  \r\n  \r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n    <%\r\n        list = record.picture_tags\r\n        atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>?thumb=2\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%3==2 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n\r\n</div>\r\n\r\n<div style=\"width:400px; margin-left:auto; margin-right:auto\">\r\n				\r\n				\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        \r\n        \r\n<%\r\n    if @current_role != \'developer\'\r\n%>\r\n        setTimeout(function() {\r\n            print();\r\n        }, 3000);\r\n<%\r\n    end\r\n%>\r\n    });\r\n</script>\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2017-10-11 03:48:37','2017-10-11 03:48:37','print',''),(3199,'index',1261,2,'<h1>\r\n    API for implant profile database\r\n</h1>\r\n<table>\r\n    <tr>\r\n        <td>\r\n            <%=link_to \'update_data\', \'update_data\' %>\r\n        </td>\r\n    </tr>\r\n</table>\r\n',NULL,NULL,NULL,'2017-10-26 07:31:48','2017-10-26 07:31:48','index',''),(3200,'update_data',1261,3,'<%\r\n    path = \'tmp/cache/dump_thkjr\'\r\n\r\n    collections = %w{ taig.hospital  taig.implant_company taig.implant_component taig.implant_material taig.implant_profile taig.implant_type}\r\n    for i in collections    \r\n    \r\n    cmd = \"mongodump --db esm_emr-taig --collection \\\\#{i} --out \\\\#{path}\"\r\n\r\n    out = `\\\\#{cmd}`\r\n    \r\n    end\r\n    \r\n    database = \'esm_emr-thkjr\'\r\n    \r\n    cmd = \"mongorestore --db \\\\#{database} --dir \\\\#{path}/esm_emr-taig\"\r\n    \r\n    out = `\\\\#{cmd}`\r\n\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=index\" />\r\n ',NULL,NULL,NULL,'2017-10-26 07:32:05','2017-10-26 07:32:05','update_data',''),(3201,'login',1261,3,'<%\r\n     ehr = @current_solution.get_project \'www\'\r\n    user_m = ehr.get_model[:user]\r\n    msg = {}\r\n    \r\n    if params[:login] and params[:pw]\r\n        \r\n    login = params[:login]    \r\n    password = params[:pw]\r\n    user = user_m.where(:login=>login).first    \r\n\r\n    if user = user_m.where(:login=>login).first    \r\n        salt = user.salt\r\n        hashed_password = User.encrypt(password,salt)\r\n        if hashed_password != user.hashed_password\r\n            \r\n            msg[:return] = [403,\"User Not Found or Wrong password\"]\r\n        \r\n        else\r\n        \r\n           user.update_attributes :last_actived => Time.now, :current_session=>session[:session_id]\r\n        \r\n           msg[:return] = [200,\"OK\"]\r\n           msg[:data] = user\r\n        \r\n        end\r\n    \r\n    else\r\n        \r\n        msg[:return] = [403,\"User Not Found\"]\r\n        \r\n    end\r\n    else\r\n        msg[:return] = [303,\"Not Engough Info\"]\r\n    \r\n    end\r\n  response.headers[\'Access-Control-Allow-Origin\'] =  \'*\' \r\n  response.headers[\'Access-Control-Allow-Credentials\'] = \'true\'\r\n  response.headers[\'Access-Control-Allow-Methods\'] = \'POST, GET, PUT, DELETE, OPTIONS\'\r\n  response.headers[\'Access-Control-Allow-Headers\'] = \'origin, accept, content-type, accept\'\r\n  \r\n%><%=msg.to_json.html_safe%>',NULL,NULL,NULL,'2017-10-26 07:51:08','2017-10-26 07:51:08','login','*'),(3202,'signup',1261,3,'<%\r\n  response.headers[\'Access-Control-Allow-Origin\'] = request.headers[\'Origin\'] || \'*\' # the domain you\'re making the request from\r\n  response.headers[\'Access-Control-Allow-Credentials\'] = \'true\'\r\n  response.headers[\'Access-Control-Allow-Headers\'] = \'accept, content-type\'\r\n    \r\n    msg = {}\r\n    \r\n    if request.get?\r\n        \r\n    ehr = @current_solution.get_project \'www\'\r\n    user_m = ehr.get_model[:user]\r\n    login = params[:login]    \r\n    \r\n    unless user_m.where(:login=>login).first    \r\n        \r\n   \r\n    email = params[:email]\r\n    salt = params[:salt]\r\n    salt = User.random_string(10) unless params[:salt]\r\n    password = params[:pw]\r\n    #  Digest::SHA1.hexdigest(passsalt)\r\n    hashed_password = User.encrypt(password,salt)\r\n    \r\n    user = user_m.create :login=>login, :salt=>salt, :hashed_password=>hashed_password, :email=>email\r\n    \r\n    msg[:return] = [200,\"OK\"]\r\n    msg[:data] = {:user=>user}\r\n        \r\n        \r\n        \r\n    else\r\n        \r\n        msg[:return] = [403,\"User Existed\"]\r\n        \r\n        \r\n    end\r\n        \r\n    \r\n    else\r\n    \r\n    msg[:return] = [200,\"OK\"]\r\n    msg[:data] = {:salt=>User.random_string(10)}\r\n    \r\n    end\r\n    \r\n    \r\n%><%=msg.to_json.html_safe%>',NULL,NULL,NULL,'2017-10-26 07:51:26','2017-10-26 07:51:26','signup','*'),(3203,'get_database',1261,3,'<%\r\n response.headers[\'Access-Control-Allow-Origin\'] = request.headers[\'Origin\'] || \'*\' # the domain you\'re making the request from\r\n  response.headers[\'Access-Control-Allow-Credentials\'] = \'true\'\r\n  response.headers[\'Access-Control-Allow-Headers\'] = \'accept, content-type\'\r\n    msg = {}\r\n    models = get_model\r\n    \r\n    msg[:hospital]=models[:hospital].all\r\n    msg[:implant_company]=models[:implant_company].all\r\n    msg[:implant_component]=models[:implant_component].all\r\n    msg[:implant_material]=models[:implant_material].all\r\n    msg[:implant_profile]=models[:implant_profile].all\r\n    msg[:implant_type]=models[:implant_type].all\r\n\r\n\r\n\r\n    \r\n    \r\n    \r\n%><%=msg.to_json.html_safe%>',NULL,NULL,NULL,'2017-10-26 07:52:48','2017-10-26 07:52:48','get_database','*'),(3204,'get_profile',1261,3,'<%= render :inline=>this.init %><%\r\n    \r\n    query = params[:q].strip\r\n    models = get_model\r\n    \r\n    \r\n    ehr = @current_solution.get_project \'www\'\r\n    user_m = ehr.get_model[:user]\r\n    msg = {}\r\n    login = params[:login]\r\n    if user = user_m.where(:login=>login).first and session[:session_id] == user.current_session   \r\n  \r\n    # if params[:return] == 200 \r\n        \r\n        \r\n    profiles = models[:implant_profile].collection.find().to_a\r\n    p = []\r\n    \r\n    for i in profiles\r\n    \r\n    barcode = \'\'\r\n    barcode = i[\'barcode\'].gsub(\'+\',\'\') if i[\'barcode\']\r\n        if barcode == query or i[\'product_id\'] == query\r\n            p << i       \r\n            break\r\n        end\r\n    end\r\n    msg = {:return=>[200,\'OK\'], :data=>p}\r\n    msg[:user] = user\r\n    msg = {:return=>[404,\'NOT FOUND\'], :data=>nil} if p.size==0\r\n    \r\n    \r\n    else \r\n    \r\n    msg[:return] = [303, \'NOT Allowed\']\r\n    \r\n    end\r\n    \r\n\r\n    \r\n    \r\n    \r\n%><%=msg.to_json.html_safe%>',NULL,NULL,NULL,'2017-10-26 08:03:25','2017-10-26 08:03:25','get_profile','*'),(3205,'init',1261,4,'<%\r\n    ehr = @current_solution.get_project \'www\'\r\n    user_m = ehr.get_model[:user]\r\n    msg = {}\r\n    login = params[:login]\r\n    if user = user_m.where(:login=>login).first and session[:session_id] == user.current_session   \r\n         msg[:return] = [200,\'OK\']\r\n    end  \r\n    \r\n  response.headers[\'Access-Control-Allow-Origin\'] = request.headers[\'Origin\'] || \'*\' # the domain you\'re making the request from\r\n  response.headers[\'Access-Control-Allow-Credentials\'] = \'true\'\r\n  response.headers[\'Access-Control-Allow-Headers\'] = \'accept, content-type\'\r\n%>\r\n',NULL,NULL,NULL,'2017-10-26 08:48:33','2017-10-26 08:48:33','init',''),(3206,'submit_case',1261,3,'<%= render :inline=>this.init %><%\r\n       \r\n  response.headers[\'Access-Control-Allow-Origin\'] =  \'*\' \r\n  response.headers[\'Access-Control-Allow-Credentials\'] = \'true\'\r\n  response.headers[\'Access-Control-Allow-Methods\'] = \'POST, GET, PUT, DELETE, OPTIONS\'\r\n  response.headers[\'Access-Control-Allow-Headers\'] = \'origin, accept, content-type, accept\'\r\n    \r\n    # query by date\r\n    # query by hn\r\n    # query by hospital\r\n    # query by hospital + date\r\n    # query by hospital + hn\r\n    \r\n    # patient : name, hn, hospital_id, gender 1:2 , age as number\r\n    # case type\r\n    \r\n    # Hip1\r\n    # Hip2\r\n    # Knee1\r\n    # Knee2\r\n    \r\n    # implant_profiles => implant records\r\n    # implate record ; code company_ref_id component_ref_id type_ref_id component_description=>profile note\r\n    \r\n    msg = {}\r\n    \r\n    if request.post?\r\n        \r\n         begin\r\n        \r\n          ehr = @current_solution.get_project \'www\'\r\n          ehr_models = ehr.get_model\r\n          patient_m = ehr_models[:patient]\r\n          patient_module_m = ehr_models[:patient_module]\r\n          \r\n          name = params[:name]\r\n          t = name.split\r\n          \r\n          prefix_name = \'\'\r\n          last_name = \'\'\r\n          \r\n          first_name = name if t.size==1\r\n          first_name, last_name = name.split if t.size==2\r\n          prefix_name, first_name, last_name = name.split if t.size==3\r\n          age = 0 \r\n          age= params[:age].to_i if params[:age] \r\n          dob = Date.parse \"\\\\#{2017-age}-01-01\"\r\n          gender = \'0\'\r\n          gender =  \'1\' if params[:gender] == \'M\'\r\n          gender =  \'2\' if params[:gender] == \'F\'\r\n          date = params[:date]\r\n          \r\n          patient = patient_m.create :first_name=>first_name, :last_name=>last_name, :prefix_name=>prefix_name, :birth_date=>dob, :gender=>gender, :hn=>params[:hn]\r\n          \r\n\r\n          \r\n          models = get_model\r\n          \r\n          \r\n          \r\n          \r\n          record_type = params[:case_type] #primary_hip => Hip1 \r\n          map = {\'primary_hip\'=>:hip1, \'revision_hip\'=>:hip2, \'primary_knee\'=>:knee1, \'revission_knee\'=>:knee2 }\r\n          \r\n          msg[:data] = {:patient=>patient}\r\n          \r\n          if record_type = map[params[:case_type]]\r\n             \r\n            model_m  = models[record_type] \r\n            \r\n            profiles = []\r\n            \r\n            params[:codes].each_with_index do |i,index|\r\n                \r\n              if i.size>0 \r\n              profile = models[:implant_record].create :code=>i, :company_ref_id=>params[:company_ref_id][index],:component_ref_id=>params[:component_ref_id][index],:type_ref_id=>params[:type_ref_id][index], :component_description=>params[:component_description][index] \r\n               \r\n              profiles << profile    \r\n              \r\n              end\r\n              \r\n              \r\n            end\r\n                \r\n            \r\n            \r\n            hospital_id = nil \r\n            hospital = models[:hospital].find(params[:hospital])\r\n            hospital_id = hospital.id if hospital \r\n            \r\n            \r\n            \r\n            procedure = models[:procedure].where(:code=>record_type.to_s).first\r\n             \r\n            appointment = models[:appointment].create :date=>date, :visit_type=>hospital_id,:procedure=>procedure.id\r\n          \r\n          \r\n          \r\n            apm = patient_module_m.create :patient_id=>patient.id, :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>appointment.id\r\n          \r\n             \r\n            record = model_m.create  :implant_profiles=>profiles.collect{|i| i.id} \r\n            \r\n            rm = patient_module_m.create  :module_name=>\"\\\\#{@current_project.name}#\\\\#{record_type.to_s}\", :module_id=>record.id, :parent_id=> apm.id, :patient_id=>patient.id\r\n    \r\n            msg[:data][:appointment] = appointment\r\n            msg[:data][:appointment_module] = apm\r\n            \r\n\r\n            msg[:data][:record] = record\r\n            msg[:data][:record_module] = rm\r\n            \r\n          \r\n            \r\n          end\r\n            \r\n            \r\n          \r\n          \r\n          msg[:return] = [200,\'OK\']\r\n          rescue Exception=>e\r\n            msg[:data] = params\r\n            msg[:return] = [505,\'Error\']\r\n          \r\n          end\r\n        \r\n    \r\n    else    \r\n        msg[:return] = [505,\'Error\']\r\n    end\r\n%><%=msg.to_json.html_safe%><%=params.inspect %>\r\n',NULL,NULL,NULL,'2017-10-29 14:20:46','2017-10-29 14:20:46','submit_case','*'),(3207,'get_case',1261,3,'',NULL,NULL,NULL,'2017-10-29 14:20:59','2017-10-29 14:20:59','get_case',''),(3208,'query',1261,3,'<%= render :inline=>this.init %><%\r\n       \r\n  response.headers[\'Access-Control-Allow-Origin\'] = request.headers[\'Origin\'] || \'*\' # the domain you\'re making the request from\r\n  response.headers[\'Access-Control-Allow-Credentials\'] = \'true\'\r\n  response.headers[\'Access-Control-Allow-Headers\'] = \'accept, content-type\'\r\n    \r\n    # query by date\r\n    # query by hn\r\n    # query by hospital\r\n    # query by hospital + date\r\n    # query by hospital + hn\r\n\r\n    msg = {}\r\n \r\n    found = false \r\n    \r\n    \r\n    ehr = @current_solution.get_project \'www\'\r\n    ehr_models = ehr.get_model\r\n    patient_m = ehr_models[:patient]\r\n    patient_module_m = ehr_models[:patient_module]\r\n    \r\n    models = get_model\r\n    \r\n    patients = []\r\n    \r\n    apps = nil\r\n    pm_apps = nil\r\n    m_apps = {}\r\n    \r\n    if params[:date]\r\n        \r\n        \r\n        date = params[:date].to_mongo\r\n        myDate =  Date.parse(date);\r\n\r\n        \r\n        apps = models[:appointment].where(:date=>{\'$lte\'=>myDate.end_of_day, \'$gte\'=>myDate.beginning_of_day}).all\r\n        \r\n        pm_apps = patient_module_m.collection.find({:module_id=>{\'$in\'=>apps.collect{|i| i.id}}}).to_a\r\n\r\n    end\r\n    \r\n \r\n    \r\n \r\n    unless apps\r\n       \r\n       if params[:hospital]\r\n          \r\n        apps = models[:appointment].where(:visit_type=>params[:hospital]).all\r\n        \r\n        pm_apps = patient_module_m.collection.find({:module_id=>{\'$in\'=>apps.collect{|i| i.id}}}).to_a\r\n         \r\n       end\r\n       \r\n    else\r\n      \r\n        apps.collect!{|i| i if i.visit_type.to_s == params[:hospital] }.compact!   if params[:hospital]  \r\n        \r\n    end\r\n     \r\n  \r\n    \r\n    for i in apps\r\n        \r\n        m_apps[i.id] = i\r\n        \r\n    end\r\n        \r\n    res = []\r\n  \r\n        \r\n        \r\n    for i in pm_apps\r\n        \r\n        patient = patient_m.find i[\'patient_id\']\r\n        \r\n        app = m_apps[i[\'module_id\']]\r\n        \r\n        if app\r\n            \r\n            \r\n            procedure = models[:procedure].find  app.procedure\r\n            \r\n            if procedure \r\n            \r\n                #m = models[procedure.code.to_sym]\r\n                \r\n                gender = \'NA\'\r\n                \r\n                gender = \'M\' if patient.gender ==\'1\'\r\n                gender = \'F\' if patient.gender ==\'2\'\r\n                date = \'-\'\r\n                \r\n                date =app.date.strftime(\'%d/%m/%Y\') if app.date\r\n                pm = patient_module_m.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{procedure.code}\", :parent_id=>i[\'_id\']).first\r\n                  \r\n                res << {:text=>\"\\\\#{patient.prefix_name}\\\\#{patient.first_name} \\\\#{patient.last_name}\\t\\\\#{gender}\\t\\\\#{date}\\t\\\\#{procedure.name}\",:hn=>patient.hn,:id=>pm,:data=>{:patient=>patient, :appointment=>app, :procedure=>procedure} }\r\n            \r\n            end\r\n                \r\n        end\r\n        \r\n    \r\n    end\r\n  \r\n    \r\n    \r\n    if params[:hn]\r\n    \r\n    res.collect!{|i| i if i[:hn] == params[:hn] }\r\n    res.compact!\r\n    \r\n    end\r\n    \r\n    found = true if res.size>0\r\n    \r\n    msg[:return] = [200,\'OK\'] \r\n    msg[:data] = res\r\n    \r\n    \r\n    unless found\r\n        \r\n    msg[:return] = [404,\'Not Found\'] \r\n    msg[:data] = []\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n%><%=msg.to_json.html_safe%>',NULL,NULL,NULL,'2017-10-29 14:21:19','2017-10-29 14:21:19','query','*'),(3209,'test',1261,2,'<%\r\n\r\n    models = get_model\r\n    hospitals = models[:hospital].all\r\n    \r\n    components = models[:implant_component].all\r\n    types = models[:implant_type].all.collect{|i| [\"\\\\#{i.type_id} \\\\#{i.type_name}\" ,i.id] }\r\n    profiles = models[:implant_profile].collection.find({},{:fields=>{\'_id\'=>1,\'component_description\'=>1,\'side\'=>1,\'size\'=>1}}).to_a.collect{|i| [\"\\\\#{i[\'component_description\']} \\\\#{i[\'side\']} \\\\#{i[\'size\']}\" ,i[\'_id\']] }\r\n\r\n%>\r\n\r\n    <%=form_for :case, :url=>\"submit_case?update=result\", :data=>{:remote=>true} do |f|  %>\r\n    <h1>Case Submission</h1>\r\n    \r\n    Date : <%=text_field_tag \'date\', Time.now.strftime(\'%Y-%m-%d\') %><br/>\r\n    Name : <%=text_field_tag \'name\' %><br/>\r\n    HN : <%=text_field_tag \'hn\' %><br/>\r\n    Age : <%=text_field_tag \'age\' %><br/>\r\n    Gender : <%=select_tag \'gender\', options_for_select([\'M\',\'F\']) %><br/>\r\n    Hospital : <%=select_tag \'hospital\', options_for_select(hospitals.collect{|i| [i.hospital_name_thai,i.id]}) %><br/>\r\n    <hr/>\r\n    Case type : <%=select_tag \'case_type\', options_for_select(%w{primary_hip revision_hip primary_knee revision_knee}.collect{|i| [i.humanize, i]} ) %>    \r\n    <ul>\r\n    <% 3.times do |i| \r\n    \r\n                # implate record ; code company_ref_id component_ref_id type_ref_id component_description=>profile note\r\n\r\n   %>\r\n        <li>\r\n        \r\n            <%=text_field_tag \'codes[]\' %><br/>\r\n            <%=select_tag \'company_ref_id[]\', options_for_select(models[:implant_company].all.collect{|i| [i.company_name,i.id] } ) %>   \r\n            <%=select_tag \'component_ref_id[]\', options_for_select(components.collect{|i| [i.component_name,i.id] } ) %>   \r\n            <%=select_tag \'type_ref_id[]\', options_for_select(types ) %>   \r\n            <%=select_tag \'component_description[]\', options_for_select(profiles ) %>   \r\n\r\n\r\n\r\n\r\n            \r\n        </li>\r\n    <% end %>\r\n    </ul>\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    <%= f.submit \'Submit\'%>\r\n    <% end %>\r\n    \r\n    <div id=\"result\">..</div>',NULL,NULL,NULL,'2017-10-29 14:21:51','2017-10-29 14:21:51','test','*'),(3210,'index',1262,2,'\r\n<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Record</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"search\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-zoom\"></i><br />Search Patient</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n        <%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n    });\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:hospital]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.hospital_name_thai\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n   # aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n     aps = ap_model.all(:limit=>10,:order=>\'created_at desc\') \r\n\r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n         \r\n         \r\n         \r\n         #public_id = patient.public_id if patient\r\n         c = {\r\n         \r\n         :ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",\r\n         :hospital=>visit_type,\r\n         :status=>i.status,:date=>\"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date}\",:procedure=>procedure_name,\r\n         :visit_type=>visit_type,\r\n         :processing_ctrl=>link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info\')\r\n         }\r\n         \r\n        \r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if true}.compact\r\n    \r\n    \r\n    table_model = %w{date hn patient hospital procedure }.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:date=>\'Date\',:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n    \r\n    \r\n%>\r\n\r\n\r\n<%\r\n\r\n     tmp = waiting\r\n\r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Recently Patients \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n       <%= tabular :model=>table_model+[:processing_ctrl],:data=>tmp,:labels=>labels %>\r\n\r\n        \r\n        </div>\r\n    </div>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<br/>\r\n<%  t = Time.new date.year, date.month,date.day\r\n%>\r\n\r\n<%\r\n   start = t.beginning_of_day\r\n   stop = t.end_of_day\r\n\r\n   modules = module_model.where(:module_name=>/\\\\#{@current_project.name}/i,:date=>{\"$gte\"=> start, \"$lt\"=> stop}).all\r\n   \r\n   modules.collect! do |i|\r\n   %>\r\n\r\n   <%\r\n   if i.module_name!=\"\\\\#{@current_project.name}#appointment\"\r\n         patient = patient_model.find(i.patient_id)\r\n        \r\n         hn = \'-\'\r\n         hn = patient.hn #link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         \r\n        ap =  module_model.find(i.parent_id)\r\n      if ap \r\n      ap = ap.module_id \r\n     {:public_id=>public_id, :hn=>hn, :patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\"),\r\n        :show=>link_to(\'Show\',\"../\\\\#{i.module_name.split(\'#\')[-1].camelize}/show?id=\\\\#{i.id}&record_name=\\\\#{hn}&return=../Home/patient_record?id=\\\\#{ap}\",:class=>\'btn btn-small\'), \r\n      :module_name=>i.module_name.split(\"#\")[-1].humanize,\r\n      :updated_at=>i.updated_at.strftime(\"%d-%m-%y\"),\r\n      :date=>i.date.strftime(\"%d-%m-%y\"),\r\n      \r\n     }\r\n     end\r\n     end\r\n   end\r\n   modules.compact!\r\n%>\r\n<%#\"\\\\#{@current_project.name}#appointment\"%>\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Recently Chart Reports \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n	     <%= tabular :model=>[:date, :updated_at,:hn, :patient, :module_name,:show],:data=>modules do |row,out|\r\n             \r\n            out\r\n         end\r\n         %>\r\n    \r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n\r\n </div><br/>\r\n \r\n <script>\r\n $(\"#query\").focus();\r\n </script>',NULL,NULL,NULL,'2017-10-29 15:26:11','2017-10-29 15:26:11','',''),(3213,'print_appointment',502,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i[:name]\r\n    end\r\n    \r\n    \r\n\r\n    \r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i\r\n p = patients[i.patient_id]  \r\n provider = providers[ap.provider.to_s]\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year} ปี \\\\#{month} เดือน \\\\#{day} วัน\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s][:name] if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s][:name] if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'procedure\'=>pro[ap.procedure],\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>(provider.nil? or provider==\'\') ? \'-\' : provider[:name],\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>d+\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'age\'=>age,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\nlist = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: normal;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 14px;\r\n\r\n}\r\n#table-3 td {\r\n	font-size: 12px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting(\"logo_report_path\")%>\' width=\"250\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n\r\n<div id=\"page\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<br />\r\n<b>ตารางแสดงรายการผู้ป่วย\r\n<span style=\"float:right\">ประจำวันที่ \r\n<%= date.strftime(\"%d %B %Y\")%></b>\r\n</span>\r\n<br /><br />\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th>No.</th>\r\n    <th>Type</th>\r\n    <th style=\"width:150px\">ชื่อ - สกุล</th>\r\n    <th>HN</th>\r\n    <th >อายุ</th>\r\n    <th>เลขประชาชน</th>\r\n    <th>Indication</th>\r\n    <th>Procedure</th>\r\n    <th>Provider</th>\r\n    <th>Tel.</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n  <% list.each_with_index do |i,index|  %>\r\n    <tr style=\"height:110px\">\r\n    <td><%=index+1%>.</td>\r\n    <td><%=i[\'visit_type\']%></td>\r\n    <td style=\"width:150px\"><%=i[\'title\']%></td>\r\n    <td><%=i[\'hn\']%></td>\r\n    <td><%=i[\'age\']%></td>\r\n    <td><%=i[\'public_id\']%></td>\r\n    <td><%=i[\'indication\']%></td>\r\n    <td><%=i[\'procedure\']%></td>\r\n    <td><%=i[\'provider\']%></td>\r\n    <td><%=i[\'tel\']%></td>\r\n    </tr>\r\n    <% end %>\r\n</tbody>\r\n  </table><br/>\r\n  </div>\r\n  </div></div></div></div></div>\r\n</body>\r\n</html>\r\n<% end %>\r\n',NULL,NULL,NULL,'2017-10-31 02:23:35','2017-10-31 02:23:35','print_appointment',''),(3214,'update_status',146,2,'Status updated\r\n<%\r\n  date = \"\"\r\n  ap = get_model[:appointment].find(params[:id])\r\n  change = true\r\n  \r\n  change = false if ap.status ==\'Processing\' and params[:status]==\'Preparing\'\r\n  \r\n  if ap and change\r\n  ap.update_attributes :status=>params[:status]\r\n  \r\n%>\r\n<%\r\nend \r\n%>\r\n<META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=index<%=date%>\">\r\n\r\n',NULL,NULL,NULL,'2017-11-07 07:21:01','2017-11-07 07:21:01','update_status',''),(3215,'download_image',235,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %><%\r\n\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    @patient_module = @module_model.find(params[:id])\r\n    # record = model.find(@patient_module.module_id)\r\n    @document =  get_document(this.document_name)\r\n    \r\n    fields = @document.fields\r\n  \r\n    \r\n    img_field = nil\r\n    for i in fields\r\n        \r\n        if i.field_type == \'image_camera\'\r\n           img_field = i\r\n           break;\r\n        end\r\n    \r\n    end\r\n    \r\n    if img_field \r\n    \r\n\r\n        url = \"/esm_image/\\\\#{@document.id}/download?record_id=\\\\#{@patient_module .module_id}&field_id=\\\\#{img_field.id}&p_id=\\\\#{@current_project.id}\"\r\n    \r\n    \r\n    else\r\n        url = \"../Home/index\"\r\n    end\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=<%=url%>\" />\r\n<script></script>\r\n',NULL,NULL,NULL,'2017-11-17 04:47:41','2017-11-17 04:47:41','download_image',''),(3216,'patient_record',1063,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\n	body { min-width:0px; }\r\n	.gebo-fixed { background-color:#f5f5f5; }\r\n	#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Patient Records\r\n				<div class=\"pull-right\">\r\n					<%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n				</div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<%\r\n					ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n					ehr_models = ehr.get_model\r\n					patient_model = ehr_models[:patient]\r\n					patient_module_model = ehr_models[:patient_module]\r\n					\r\n					emr_models = get_model\r\n					ap = emr_models[:appointment].find(params[:id])\r\n					pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n					locker_model = emr_models[:locker]\r\n					if params[:reset_lock]\r\n					    l = locker_model.find(params[:reset_lock])\r\n					    l.destroy if l\r\n					end\r\n					#locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n					#i.destroy if i\r\n					#end\r\n					 \r\n					\r\n					\r\n					if pm\r\n					\r\n					if  params[:schema_patient_module]\r\n					   pm.update_attributes params[:schema_patient_module]\r\n					end\r\n					\r\n					if params[:provider_id]\r\n					  ap.update_attributes :provider=>params[:provider_id]\r\n					   ap = emr_models[:appointment].find(params[:id])\r\n					 end\r\n					\r\n					# find provider\r\n					provider = emr_models[:provider].find(ap.provider.to_s)\r\n					\r\n					# find patient\r\n					patient = patient_model.find(pm.patient_id)\r\n					\r\n					params[:patient]=patient\r\n					params[:patient_module]=pm\r\n					\r\n					# s = Service.get(\'ehr.emr.EmrHelper\')\r\n					#    obj = s.load context\r\n					\r\n					providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n					\r\n					%>\r\n				<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\'}.compact %>\r\n				<div style=\"border:0px solid\">\r\n					<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n						<%# render :inline=>obj.show_patient %>\r\n						<div id=\"patient\">\r\n							...\r\n						</div>\r\n						<script>\r\n							<%\r\n								url = \'../../www/Patient/search_result?\'\r\n								url += \'&id=\'+patient.id.to_s\r\n								%>      \r\n							        $.ajax({\r\n							    	  url: \'<%=url.html_safe%>\',\r\n									 success: function(data){\r\n							          $(\'#patient\').html(data);  \r\n									  }\r\n									});\r\n						</script>\r\n						<% \r\n							test = false\r\n							if @current_role == \'developer\' and test \r\n							%>\r\n						<pre>\r\n    Appointment : <%= ap.to_json.html_safe %><br/>\r\n</pre>\r\n						<pre>\r\n    PatientModule : <%= pm.to_json.html_safe %>\r\n</pre>\r\n						<% if params[:remove] == \'true\'\r\n							ap.destroy\r\n							pm.destroy\r\n							%>\r\n						<script>\r\n							window.location = \"index\"\r\n						</script>\r\n						<% end %>\r\n						<% \r\n							if params[:update] == \'true\' \r\n							    sname = @current_project.name + \"#\" + params[:sname]\r\n							    app_id = params[:app_id]\r\n							    \r\n							    t_ap = emr_models[:appointment].find(app_id)\r\n							    t_pm = patient_module_model.first(:module_id=>t_ap.id.to_s)\r\n							    f_pm = patient_module_model.where(:module_name=>sname, :parent_id=>pm.id).first\r\n							\r\n							    # Move unnessesary record to another appointment_id and patient_id\r\n							    # open record page that you need to move (f_pm), \r\n							    # use parameter update=true&sname={your_service_name}&app_id={another_appointment}\r\n							    \r\n							    # if t_pm\r\n							    #     f_pm.update_attributes :parent_id=>t_pm.id, :patient_id=>t_pm[:patient_id]\r\n							    #     ap = t_ap\r\n							    #     pm = t_pm\r\n							    # end\r\n							%>\r\n						<pre>\r\n    AppointmentID : <%= t_pm.to_json.html_safe %><br/>\r\n    <!--ParentID : <%=  %><br/>-->\r\n    Service  : <%= sname %><br/>\r\n    TEST : <%= f_pm.to_json.html_safe %>\r\n</pre>\r\n						<%\r\n							end\r\n							%>\r\n						<% end %>\r\n						<br/>\r\n						<%\r\n							previous = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\n							history = []\r\n							x = previous[0..7]\r\n							last = []\r\n							last = x.compact if x\r\n							history = []\r\n							y = previous[8..-1]\r\n							history = y.compact if y and  previous.size>5\r\n							                                     \r\n							current = time_ago_in_words(ap.date)\r\n							current_date = ap.date.strftime(\"%d-%m-%y\")\r\n							current = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n							\r\n							a_map = {}\r\n							a_ids = last.collect{|i| i[:module_id]}\r\n							a_list = get_model[:appointment].find(a_ids)\r\n							a_list.each do |i|\r\n							    a_map[i.id.to_s] = i\r\n							end\r\n						%>	\r\n						<div class=\"clear\"></div>\r\n						\r\n						<div class=\"tabbable\">\r\n						    \r\n							<ul class=\"nav nav-tabs\">\r\n								<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%><br/><%= ap[:status] %></a></li>\r\n								<%\r\n									for i in last \r\n									    m_ap_id = i[:module_id].to_s\r\n									    m_ap = a_map[m_ap_id]\r\n									    ap_status = \'NA\'\r\n									    ap_date = i.date.strftime(\"%d-%m-%y\") if i.date\r\n									    if m_ap\r\n									        ap_status = m_ap[:status].nil? ? \'N/A\' : m_ap[:status]\r\n									        ap_date = m_ap[:date].strftime(\"%d-%m-%y\")\r\n									    end\r\n								%>\r\n								<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date) if i.date%><br/><%=ap_date%><br/><%= m_ap[:status] %></a></li>\r\n								<% end %>\r\n								<% if history.size>5 %>\r\n								<li class=\"dropdown\">\r\n									<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n									<ul class=\"dropdown-menu\">\r\n										<% for j in history %>\r\n										<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n										<% end %>\r\n										<li class=\"divider\"></li>\r\n									</ul>\r\n								</li>\r\n								<% end %>\r\n								<span style=\'float:right;margin-top:20px;margin-right:10px\'>\r\n        						    <%= link_to \'Add Visit\', \"../Appointment/create?obj_id=\\\\#{patient.id.to_s}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-mini btn-success\' %>\r\n        						</span>\r\n							</ul>\r\n							<div class=\"tab-content\">\r\n								<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n									<h4><%= @current_project.title %> Records</h4>\r\n									<% if current == \'Today\' %>\r\n									<div style=\'float:right\'><%= link_to \'Edit Visit\', \"../Appointment/show?id=\\\\#{pm.id.to_s}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-mini btn-info\', :style=>\'margin-top:-30px\' %></div>\r\n									<% end %>\r\n									<hr/>\r\n									<table class=\"table table-striped table-bordered\">\r\n										<thead>\r\n											<tr>\r\n												<th></th>\r\n												<th>Forms</th>\r\n												<th>Records</th>\r\n												<th></th>\r\n											</tr>\r\n										</thead>\r\n										\r\n										<%\r\n											groups = this.config\r\n											if true\r\n											for g in groups \r\n											   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n											%>\r\n										<tr>\r\n											<td colspan=\"4\"><%=g[:name]%></td>\r\n										</tr>\r\n										<% services.each_with_index do |s,index|\r\n											module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n											records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n											%>\r\n										<tr>\r\n											<td><%= index+1 %>. </td>\r\n											<td> <%= s.title %></td>\r\n											<td align=\"center\"><% for i in records %>\r\n												<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number[0..9] if !i.ref_number.nil?}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\" %>&nbsp;\r\n												<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\" %>\r\n												<% end %>\r\n											</td>\r\n											<td>\r\n												<%  if records.size==0 %>\r\n												<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class%>\r\n												<% else %>\r\n												<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n												<%=link_to \'Image\',\"../\\\\#{s.name.camelize}/download_image?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n												\r\n												<% end %>\r\n												<% \r\n													locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n													if