st][11..-1].each do |i|\r\n										    # key symbol\r\n										    ks = i.downcase.strip.gsub(\' \', \'_\').to_sym\r\n										    # has sub element ?\r\n										    hs = fm.has_key? ks\r\n										    # selected item ?\r\n										    si = af.include? ks.to_s\r\n										    \r\n										    rs = \"N/A\"\r\n										    if si and !hs\r\n										        @record = get_model[:bronchoscopy_scope].find(tmp_rec[ks])\r\n										        dx_val = \'N/A\'\r\n										        in_val = \'N/A\'\r\n										        sc_val = \'\'\r\n										        \r\n										        if !@record.nil?\r\n										            dx_val = get_render_value(:diagnosis)\r\n										            in_val = get_render_value(:intervention)\r\n										            \r\n										            if is_exist(:scope_note)\r\n										                sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										            end\r\n										        end\r\n										        rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										        i = \"<b>\\\\#{i}</b>\".html_safe\r\n										    \r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %> \r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										elsif si and hs\r\n										    i = \"<b>\\\\#{i}</b>\".html_safe\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										rs = \'\'\r\n										kk = fm[ks]\r\n										\r\n										ls = tmp_rec[ks].split(\'|\')\r\n										ls.each do |j|\r\n										    # sub element name\r\n										    em = kk[:pair][j]\r\n										    sn = \"<i><b>\\\\#{em}</b></i>\".html_safe\r\n										    # element symbol\r\n										    es = em.downcase.strip.gsub(\' \', \'_\')\r\n										    if es == \'apicoposterior_segment\'\r\n										        es = \'apoposterior_segment\'\r\n										    elsif es == \'anterior_segment\'\r\n										        es = \'posterior_segment\'\r\n										    end\r\n										    \r\n										    @record = get_model[:bronchoscopy_scope].find(tmp_rec[\"\\\\#{ks}_\\\\#{es}\".to_sym])\r\n										    dx_val = \'N/A\'\r\n										    in_val = \'N/A\'\r\n										    sc_val = \'\'\r\n										    \r\n										    if !@record.nil?\r\n										        dx_val = get_render_value(:diagnosis)\r\n										        in_val = get_render_value(:intervention)\r\n										        \r\n										        if is_exist(:scope_note)\r\n										            sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										        end\r\n										    end\r\n										    rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											&nbsp;&nbsp;<%= sn %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<% \r\n										end\r\n										else\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										end\r\n										end \r\n										# end section\r\n										%>\r\n								</table>\r\n							</td>\r\n							<td valign=\'top\'>\r\n								<table width=\'100%\' border=\'0\' cellpadding=\'0\' cellspacing=\'2\' style=\'-moz-border-radius:5px;border-radius:5px;border-color:#999\'>\r\n									<%\r\n										# section to render report\r\n										fm[:anatomy][:list][6..10].each do |i|\r\n										    # key symbol\r\n										    ks = i.downcase.strip.gsub(\' \', \'_\').to_sym\r\n										    # has sub element ?\r\n										    hs = fm.has_key? ks\r\n										    # selected item ?\r\n										    si = af.include? ks.to_s\r\n										    \r\n										    rs = \"N/A\"\r\n										    if si and !hs\r\n										        @record = get_model[:bronchoscopy_scope].find(tmp_rec[ks])\r\n										        dx_val = \'N/A\'\r\n										        in_val = \'N/A\'\r\n										        sc_val = \'\'\r\n										        \r\n										        if !@record.nil?\r\n										            dx_val = get_render_value(:diagnosis)\r\n										            in_val = get_render_value(:intervention)\r\n										            \r\n										            if is_exist(:scope_note)\r\n										                sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										            end\r\n										        end\r\n										        rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										        i = \"<b>\\\\#{i}</b>\".html_safe\r\n										    \r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										elsif si and hs\r\n										    i = \"<b>\\\\#{i}</b>\".html_safe\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										rs = \'\'\r\n										kk = fm[ks]\r\n										\r\n										ls = tmp_rec[ks].split(\'|\')\r\n										ls.each do |j|\r\n										    # sub element name\r\n										    em = kk[:pair][j]\r\n										    sn = \"<i><b>\\\\#{em}</b></i>\".html_safe\r\n										    # element symbol\r\n										    es = em.downcase.strip.gsub(\' \', \'_\')\r\n										    \r\n										    @record = get_model[:bronchoscopy_scope].find(tmp_rec[\"\\\\#{ks}_\\\\#{es}\".to_sym])\r\n										    dx_val = \'N/A\'\r\n										    in_val = \'N/A\'\r\n										    sc_val = \'\'\r\n										    \r\n										    if !@record.nil?\r\n										        dx_val = get_render_value(:diagnosis)\r\n										        in_val = get_render_value(:intervention)\r\n										        \r\n										        if is_exist(:scope_note)\r\n										            sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										        end\r\n										    end\r\n										    rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											&nbsp;&nbsp;<%= sn %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<% \r\n										end\r\n										else\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										end\r\n										end \r\n										# end section\r\n										%>\r\n								</table>\r\n							</td>\r\n						</tr>\r\n					</table>\r\n				</div>\r\n			</div>\r\n			<div class=\"clear\"></div>\r\n			<div id=\"page\">\r\n				<h4>Comment :</h4>\r\n				<%= record.comments.html_safe %>\r\n			</div>\r\n		\r\n			<div class=\"clear\"></div>\r\n			\r\n<%\r\n    @record = tmp_rec\r\n    @document = tmp_doc\r\n    if !rs_att.empty?\r\n%>\r\n            <footer></footer>\r\n            <br/><br/>\r\n            <div id=\"head\" class=\"well\">\r\n				<div id=\"logoleft\" style=\"width:600px; float:left\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n					<br />\r\n					First Name : \r\n					<v><%= patient.prefix_name %> <%= patient.first_name %></v>\r\n					<br />\r\n					Last Name : \r\n					<v><%= patient.last_name %></v>\r\n					<br />\r\n					HN :&nbsp;\r\n					<v><%=patient.hn%></v>\r\n					<br />\r\n					Age :&nbsp;\r\n					<v><%= year%> Year <%=month%> Month <%= day%> Day </v>\r\n					<br />\r\n					Gender :&nbsp;\r\n					<v><%= gd[patient[:gender]] %></v>\r\n					<br />\r\n					Date :&nbsp;\r\n					<v><%=record.date_note%></v>\r\n					<br />\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now %></p>\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n			</div>\r\n			<div id=\"page\" style=\'min-height:1000px\'>\r\n				<h4>Picture :</h4>\r\n				<%\r\n					if !rs_att.empty?\r\n					 rs_att[0..19].each_with_index do |i,index| \r\n					%>\r\n				<div id=\"box\">\r\n					<img alt=\"<%= i[:title] %>\" src=\"<%=i[:path]%>\" /><br/>\r\n					<v><%=i[:title]%></v>\r\n				</div>\r\n				<% if index%4==3 %>\r\n				<div class=\"clear\"></div>\r\n				<% end %>\r\n				<% end %>\r\n				<% end %>\r\n				<div class=\"clear\"></div>\r\n			</div>\r\n				\r\n				\r\n			<div id=\"page\" style=\"padding-top: 5px;min-height:1.5cm\">\r\n			    <div id=\'sign-2\' style=\'float:left\'>\r\n    			    <h4>Sign : </h4>\r\n    			    <br/>\r\n    			    <br/>&nbsp;\r\n			    </div>\r\n				<div id=\'provider-name-2\' style=\'margin-top:10px;float:right;color:#666\'>\r\n					<%= render_value(\'endoscopist_1\') %> / <%= render_value(\'endoscopist_2\') %>\r\n					<br/>\r\n					Printed at : <%= Time.now %>\r\n					<br/>\r\n				</div>\r\n			</div>\r\n<%\r\n    end\r\n%>\r\n			\r\n		</div>\r\n	</body>\r\n</html>\r\n<script>\r\nwindow.print()\r\n</script>',NULL,NULL,NULL,'2018-01-10 01:28:04','2018-01-10 01:28:04','print',''),(3258,'document_name',1288,1,'\'m_opioids\'',NULL,NULL,NULL,'2018-01-10 09:34:05','2018-01-10 09:34:05',NULL,NULL),(3259,'document_name',1289,1,'\'m_adjuvants\'',NULL,NULL,NULL,'2018-01-10 09:34:20','2018-01-10 09:34:20',NULL,NULL),(3260,'document_name',129