   $(\'#personal_id\').removeClass(\'alert alert-danger\')\r\n                    $(\'#personal_id\').addClass(\'alert alert-success\')\r\n\r\n\r\n                }else{\r\n                    // alert(\'inCorrect\')\r\n                    $(\'#personal_id\').removeClass(\'alert alert-success\')\r\n                    $(\'#personal_id\').addClass(\'alert alert-danger\')\r\n                }\r\n            }else{\r\n                 alert(\'Too short\')\r\n            }\r\n           \r\n            \r\n            \r\n            \r\n            \r\n        })\r\n        \r\n           var options = null;\r\n        if(options == null){\r\n                options = {};\r\n                options[\'implant_model\'] = $(\'#data-implant_model\').find(\'option\').clone()\r\n                options[\'implant_model_stem\'] = $(\'#data-implant_model_stem\').find(\'option\').clone()\r\n                options[\'implant_model_cup\'] = $(\'#data-implant_model_cup\').find(\'option\').clone()\r\n                options[\'diagnosis\'] = $(\'#data-diagnosis\').find(\'option\').clone()\r\n                \r\n\r\n          }\r\n        function check(){\r\n            \r\n            obj =  $(\'#data-operation\')\r\n            op = operations[obj.val()]\r\n            // alert(op);\r\n            if(op==\'Hip\'){\r\n               $(\'.implant\').hide()\r\n               $(\'.hip\').show()\r\n           }else{\r\n               $(\'.implant\').hide()\r\n               $(\'.knee\').show()\r\n           }\r\n            if(obj.val()){\r\n            op_dx = operations_dx[obj.val()]\r\n            alert(op_dx)\r\n           \r\n           \r\n           \r\n           \r\n           key = op_dx\r\n           values = dx_mask[key]\r\n           mask = {}\r\n           for(var id in values){\r\n              ix = values[id];\r\n              mask[ix] = true;\r\n           }\r\n           \r\n           $(\'#data-diagnosis\').find(\'option\').remove()\r\n           \r\n           options[\'diagnosis\'].each(function(){\r\n               opx = $(this)\r\n               if(mask[opx.attr(\'value\')]==true){\r\n                   opx.clone().appendTo($(\'#data-diagnosis\'))\r\n               }\r\n           })\r\n           \r\n           \r\n            }\r\n           \r\n           \r\n        }\r\n        \r\n        $(\'#data-operation\').change(function(){\r\n           check()\r\n        });\r\n        check()\r\n        \r\n     \r\n     \r\n     $(\'#data-implant_brand\').change(function(){\r\n           \r\n           obj = $(this)\r\n           brandv = brands[obj.val()]\r\n           op = $(\'#data-operation\').val()\r\n           opv = operations[op]\r\n          \r\n        //   alert(key)\r\n        \r\n          \r\n           \r\n           if(opv==\'Knee\'){\r\n          \r\n           key = \"\"+opv+\"-\"+brandv\r\n           values = implants[key]\r\n           mask = {}\r\n           for(var id in values){\r\n              ix = values[id];\r\n              mask[ix] = true;\r\n           }\r\n           \r\n           $(\'#data-implant_model\').find(\'option\').remove()\r\n           \r\n           options[\'implant_model\'].each(function(){\r\n               opx = $(this)\r\n               if(mask[opx.attr(\'value\')]==true){\r\n                   opx.clone().appendTo($(\'#data-implant_model\'))\r\n               }\r\n           })\r\n           \r\n           }else\r\n           if(opv==\'Hip\'){\r\n               \r\n               alert(brandv)\r\n               key = \"\"+opv+\"-Stem\"+\"-\"+brandv\r\n               values = implants[key]\r\n               mask = {}\r\n               for(var id in values){\r\n                    ix = values[id];\r\n                    mask[ix] = true;\r\n               }\r\n               \r\n               $(\'#data-implant_model_stem\').find(\'option\').remove()\r\n               options[\'implant_model_stem\'].each(function(){\r\n               opx = $(this)\r\n                    if(mask[opx.attr(\'value\')]==true){\r\n                        opx.clone().appendTo($(\'#data-implant_model_stem\'))\r\n                    }\r\n               })\r\n               alert(brandv)\r\n               \r\n               $(\'#data-implant_brand_cup option[value=\"\'+brandv+\'\"]\').attr(\"selected\",true);\r\n\r\n               \r\n               \r\n               key = \"\"+opv+\"-Cup\"+\"-\"+brandv\r\n               values = implants[key]\r\n               mask = {}\r\n               for(var id in values){\r\n                    ix = values[id];\r\n                    mask[ix] = true;\r\n               }\r\n               $(\'#data-implant_model_cup\').find(\'option\').remove()\r\n               options[\'implant_model_cup\'].each(function(){\r\n               opx = $(this)\r\n                    if(mask[opx.attr(\'value\')]==true){\r\n                        opx.clone().appendTo($(\'#data-implant_model_cup\'))\r\n                    }\r\n               })\r\n               \r\n               \r\n               \r\n           }\r\n           \r\n           \r\n           \r\n           \r\n           \r\n            \r\n        });\r\n     \r\n\r\n        $(\'#data-implant_brand_cup\').change(function(){\r\n           \r\n           obj = $(this)\r\n           brandv = brands[obj.val()]\r\n           op = $(\'#data-operation\').val()\r\n           opv = operations[op]\r\n          \r\n        //   alert(key)\r\n        \r\n   \r\n           if(opv==\'Hip\'){\r\n               \r\n               key = \"\"+opv+\"-Stem\"+\"-\"+brandv\r\n               values = implants[key]\r\n               mask = {}\r\n               for(var id in values){\r\n                    ix = values[id];\r\n                    mask[ix] = true;\r\n               }\r\n               $(\'#data-implant_model_stem\').find(\'option\').remove()\r\n               options[\'implant_model_stem\'].each(function(){\r\n               opx = $(this)\r\n                    if(mask[opx.attr(\'value\')]==true){\r\n                        opx.clone().appendTo($(\'#data-implant_model_stem\'))\r\n                    }\r\n               })\r\n               \r\n               key = \"\"+opv+\"-Cup\"+\"-\"+brandv\r\n               values = implants[key]\r\n               mask = {}\r\n               for(var id in values){\r\n                    ix = values[id];\r\n                    mask[ix] = true;\r\n               }\r\n               $(\'#data-implant_model_cup\').find(\'option\').remove()\r\n               options[\'implant_model_cup\'].each(function(){\r\n               opx = $(this)\r\n                    if(mask[opx.attr(\'value\')]==true){\r\n                        opx.clone().appendTo($(\'#data-implant_model_cup\'))\r\n                    }\r\n               })\r\n               \r\n               \r\n               \r\n           }\r\n           \r\n     \r\n           \r\n           \r\n           \r\n           \r\n            \r\n        });\r\n        \r\n      \r\n             \r\n        \r\n    })\r\n    \r\n    \r\n            \r\n           fx = update_koos_choice_1_func;\r\n           \r\n           function update_koos_choice_1_func(){\r\n            //   alert(\'idofj\')\r\n               fx();\r\n               v = $(\'#data-koos_choice_1\').val();\r\n               alert(v)\r\n              \r\n           }\r\n// alert(\'dijf\')    \r\n</script>\r\n',NULL,NULL,NULL,'2018-02-08 16:01:56','2018-02-08 16:01:56','',''),(3302,'show',1321,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2018-02-08 16:23:07','2018-02-08 16:23:07','show',''),(3303,'display',1321,3,'\r\n<%\r\n   model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   \r\n   operation = get_model(\'operation\').find(@record.operation)\r\n   \r\n    \r\n    \r\n    # operations = models[:operation].all.collect{|i| [i.id,i.type]}.to_h\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n\r\n<script>\r\n    $(document).ready(function(){\r\n        \r\n        function check(){\r\n            \r\n          \r\n            op = \"<%=operation.type%>\"\r\n            // alert(op);\r\n            if(op==\'Hip\'){\r\n               $(\'.implant\').hide()\r\n               $(\'.hip\').show()\r\n           }else{\r\n               $(\'.implant\').hide()\r\n               $(\'.knee\').show()\r\n           }\r\n        }\r\n        \r\n     \r\n        check()\r\n        \r\n        \r\n    })\r\n</script>',NULL,NULL,NULL,'2018-02-08 16:25:23','2018-02-08 16:25:23','display',''),(3304,'list',1036,3,'<%\r\n   model = get_model(this.table_name)\r\n   records = []\r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   \r\n    if params[:search]\r\n        records = model.all(params[:search][:criteria])\r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n       records = model.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n    end\r\n   now = Time.now\r\n\r\n\r\n%>\r\n\r\n<%= tabular :model=>labels, :data=>records do |i,out|\r\n\r\nfields.each_with_index do |f,index|\r\n\r\nout[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n\r\nend\r\nout << link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nif (now - i.created_at)/86400 < 30\r\nout << link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\')\r\nout << link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:data=>{:confirm=>\'Are you sure?\'})\r\nend\r\nout\r\nend\r\n%>\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2018-02-09 03:41:06','2018-02-09 03:41:06','list',''),(3307,'layout',1292,4,'<html>\r\n    \r\n    <head>\r\n        <%= include_header %>\r\n\r\n    </head>\r\n    <style>\r\n        .main_content{\r\n            padding-top:10px;\r\n        }\r\n        input{\r\n            padding:10px;\r\n            width:150px;\r\n            \r\n        }\r\n        select{\r\n            width:150px;\r\n        }\r\n        \r\n        .document-border {\r\n    width: 300px; \r\n                 margin-left: 1px;\r\n    margin-right: 1px;\r\n        }\r\n    .form-data-content {\r\n    width: 300px;\r\n \r\n}\r\n    @media (max-width: 979px)\r\n{\r\n.main_content {\r\n    padding: 10px 0px 20px;\r\n}\r\n}\r\n    </style>\r\n    \r\n<body>\r\n    \r\n\r\n    <header style=\"min-height:40px\">\r\n        \r\n    \r\n        <div class=\"navbar navbar-fixed-top\" >\r\n                    <div class=\"navbar-inner\">\r\n                        <div class=\"container-fluid\" >\r\n                        \r\n                        \r\n                            <a class=\"brand\" href=\"/\" style=\"text-align:center; vertical-align: middle;border:0px solid;margin:0px;padding:5px;width:100px\">\r\n                            <img height=\"30\"  src=\"/esm/taig/registry/logolong2.png\" alt=\"111984\"></a>\r\n                            \r\n                         <ul class=\"nav\" style=\"border:0px solid\">\r\n	                       <li><a href=\"../Home/index\"><i class=\"icon-home icon-white\"></i> <b>Home</b></a></li>\r\n	                       \r\n	                       </ul>\r\n                            \r\n                           <span id=\"search-pos-partial\" class=\"left\"></span>\r\n						 \r\n						 <ul class=\"nav user_menu pull-right\">\r\n	                         <li class=\"divider-vertical hidden-phone hidden-tablet\"></li>\r\n						     <li class=\"dropdown\">\r\n							    <a href=\"#\" class=\"dropdown-toggle\" data-toggle=\"dropdown\"><%=@current_user.login %><b class=\"caret\"></b></a>\r\n						        <ul class=\"dropdown-menu\">\r\n						            <li style=\"\"><a href=\"../Home/setting\">Account Settings</a></li>\r\n									<li><a href=\"/user/logout\">Logout</a></li>\r\n						        </ul>\r\n							 </li>\r\n						\r\n						 </ul>\r\n						\r\n                        </div>\r\n                    </div>\r\n        </div>\r\n                \r\n    \r\n    </header>\r\n    \r\n <div class=\"main_content\">\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12\" style=\"\">\r\n        <%= yield :content %>\r\n        </div>\r\n        </div>\r\n        \r\n          </div>    \r\n          </div>    \r\n<script>\r\n    refresh_remote();\r\n  \r\n</script>    \r\n<%=view :fitwidth %>\r\n    </body>\r\n</html>',NULL,NULL,NULL,'2018-02-10 09:26:16','2018-02-10 09:26:16','',''),(3308,'setting',1292,2,'<h1>Settings</h1>',NULL,NULL,NULL,'2018-02-10 09:36:44','2018-02-10 09:36:44','setting',''),(3309,'create',1292,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New Case Record</h3>\r\n<div class=\"pull-right\">\r\n<%# link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid;\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%  \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    user = model[:user].where(:login=>@current_user.login).first\r\n    user_id = nil\r\n    user_id = user.id if user\r\n%>\r\n\r\n<%= form.hidden_field :user_id, :value=>user_id%>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n    \r\n    \r\n    last = get_model[:thk_record].where(:user_id=>user_id, :created_at=>{\'$gte\'=>Time.now.beginning_of_day}).last\r\n    if last \r\n    \r\n        # record.hospital = last.hospital if last\r\n        record = last\r\n        record.id = nil\r\n        record.date = nil\r\n        record.personal_id = \'\'\r\n    \r\n    \r\n    else\r\n        \r\n      thkjr = @context.get_projects_by_abstract(\'thks.thks\')\r\n      if thkjr and thkjr[0]\r\n          \r\n      model = thkjr[0].load_model\r\n      login = @current_user.login\r\n      login = \'demo\' if @current_role ==\'developer\'\r\n          \r\n      \r\n      providers =  model[:provider].all\r\n      provider = model[:provider].where(:login=>login).first\r\n      \r\n      hospital = model[:hospital].find(provider.main_hospital)\r\n      if hospital \r\n         record.hospital = hospital.hospital_name_thai \r\n      end\r\n    \r\nend\r\n    end\r\n    params[:form][:record] = record\r\n    \r\n    \r\n    \r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-02-10 10:03:15','2018-02-10 10:03:15','create',''),(3310,'form',1292,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<%\r\n    models = get_model\r\n  \r\n    diagnosis =  models[:diagnosis].all.collect{|i| [i.id,i.name]}.to_h\r\n    \r\n    operations = models[:operation].all.collect{|i| [i.id,i.type]}.to_h\r\n    operations_dx = models[:operation].all.collect{|i| [i.id,i.dx_type]}.to_h\r\n    \r\n    complications = models[:complication].all.collect{|i| [i.id,i.name]}.to_h\r\n    \r\n    brands = models[:brand].all.collect{|i| [i.id, i.name]}.to_h\r\n    \r\n    implants = {}\r\n    \r\n    models[:implant].all.each do |i|\r\n       \r\n       key = \"\\\\#{i.type}-\\\\#{i.brand}\"\r\n       \r\n       implants[key] = [] unless implants[key]\r\n       implants[key] << i.id\r\n        \r\n    end\r\n    \r\n    diagnosis_mask = {}\r\n    models[:diagnosis].all.each do |i|\r\n        \r\n       key = \"\\\\#{i.type}\"\r\n       \r\n       diagnosis_mask[key] = [] unless diagnosis_mask[key]\r\n       diagnosis_mask[key] << i.id\r\n       \r\n    end\r\n    \r\n    complication_mask = {}\r\n    \r\n    models[:complication].all.each do |i|\r\n        \r\n       key = \"\\\\#{i.type}\"\r\n       \r\n       complication_mask[key] = [] unless complication_mask[key]\r\n       complication_mask[key] << i.id\r\n       \r\n    end\r\n    \r\n    \r\n%>\r\n<style>\r\n    option:disabled {\r\ncolor:red;\r\n}\r\n</style>\r\n<script>\r\n    \r\n    $(document).ready(function(){\r\n    var operations = <%=operations.to_json.html_safe %>\r\n    var operations_dx = <%=operations_dx.to_json.html_safe %>\r\n    var complications = <%=complications.to_json.html_safe %>\r\n\r\n    var brands = <%=brands.to_json.html_safe %>\r\n    var implants = <%=implants.to_json.html_safe %>\r\n    var diagnosis = <%=diagnosis.to_json.html_safe %>\r\n    var dx_mask = <%= diagnosis_mask.to_json.html_safe %>\r\n    \r\n    var complication_mask = <%= complication_mask.to_json.html_safe %>\r\n    \r\n    \r\n    \r\n    $(\"#data-personal_id\").keydown(function (e) {\r\n        // Allow: backspace, delete, tab, escape, enter and .\r\n        if ($.inArray(e.keyCode, [46, 8, 9, 27, 13, 110, 190]) !== -1 ||\r\n             // Allow: Ctrl/cmd+A\r\n            (e.keyCode == 65 && (e.ctrlKey === true || e.metaKey === true)) ||\r\n             // Allow: Ctrl/cmd+C\r\n            (e.keyCode == 67 && (e.ctrlKey === true || e.metaKey === true)) ||\r\n             // Allow: Ctrl/cmd+X\r\n            (e.keyCode == 88 && (e.ctrlKey === true || e.metaKey === true)) ||\r\n             // Allow: home, end, left, right\r\n            (e.keyCode >= 35 && e.keyCode <= 39)) {\r\n                 // let it happen, don\'t do anything\r\n                 return;\r\n        }\r\n        // Ensure that it is a number and stop the keypress\r\n        if ((e.shiftKey || (e.keyCode < 48 || e.keyCode > 57)) && (e.keyCode < 96 || e.keyCode > 105)) {\r\n            e.preventDefault();\r\n        }\r\n    });\r\n        $(\'#data-birth_date\').change(function(){\r\n             v = $(this).val()\r\n             if(v.indexOf(\'NaN\')!=-1){\r\n                 t = v.split(\"/\")\r\n                 i = parseInt(t);\r\n                 y = (new Date()).getFullYear() - i\r\n                 $(this).val(\"1/1/\"+y)\r\n             }\r\n        })\r\n    \r\n        $(\'#data-personal_id\').change(function(){\r\n            v = $(this).val()\r\n            \r\n            if(v.length==13){\r\n                sum = 0\r\n                for (var i = 0; i < 12; i++) {\r\n                    j = parseInt(v.charAt(i));\r\n                    sum+= (13-i)*j;\r\n                } \r\n                tail = (11-sum%11)%10;\r\n                \r\n                if(tail==parseInt(v.charAt(12))){\r\n                    // alert(\'Correct\')\r\n                    $(\'#personal_id\').removeClass(\'alert alert-danger\')\r\n                    $(\'#personal_id\').addClass(\'alert alert-success\')\r\n\r\n\r\n                }else{\r\n                    // alert(\'inCorrect\')\r\n                    $(\'#personal_id\').removeClass(\'alert alert-success\')\r\n                    $(\'#personal_id\').addClass(\'alert alert-danger\')\r\n                }\r\n            }else{\r\n                 alert(\'Too short\')\r\n            }\r\n           \r\n            \r\n            \r\n            \r\n            \r\n        })\r\n        \r\n             var options = null;\r\n        if(options == null){\r\n                options = {};\r\n                options[\'implant_model\'] = $(\'#data-implant_model\').find(\'option\').clone()\r\n                options[\'implant_model_stem\'] = $(\'#data-implant_model_stem\').find(\'option\').clone()\r\n                options[\'implant_model_cup\'] = $(\'#data-implant_model_cup\').find(\'option\').clone()\r\n                options[\'diagnosis\'] = $(\'#data-diagnosis\').find(\'option\').clone()\r\n                options[\'complication\'] = $(\'#data-complication\').find(\'option\').clone()\r\n\r\n\r\n\r\n          }\r\n        function check(){\r\n            \r\n            obj =  $(\'#data-operation\')\r\n            op = operations[obj.val()]\r\n            // alert(op);\r\n            if(op==\'Hip\'){\r\n               $(\'.implant\').hide()\r\n               $(\'.hip\').show()\r\n           }else{\r\n               $(\'.implant\').hide()\r\n               $(\'.knee\').show()\r\n           }\r\n            if(obj.val()){\r\n            op_dx = operations_dx[obj.val()]\r\n            // alert(op_dx)\r\n           \r\n           \r\n           \r\n           \r\n           key = op_dx\r\n           values = dx_mask[key]\r\n           mask = {}\r\n           for(var id in values){\r\n              ix = values[id];\r\n              mask[ix] = true;\r\n           }\r\n           \r\n           $(\'#data-diagnosis\').find(\'option\').remove()\r\n           \r\n           options[\'diagnosis\'].each(function(){\r\n               opx = $(this)\r\n               if(mask[opx.attr(\'value\')]==true){\r\n                   opx.clone().appendTo($(\'#data-diagnosis\'))\r\n               }\r\n           })\r\n           \r\n           \r\n            }\r\n            \r\n            \