'#diagnosis_other\').hide()\r\n           \r\n        });\r\n        \r\n           $(\'#data-complication\').change(function(){\r\n             \r\n           if(complications[$(\'#data-complication\').val()]!=null){\r\n               \r\n            dx = complications[$(\'#data-complication\').val()]\r\n            \r\n            if(dx.trim()===\'Other\'){\r\n                \r\n                $(\'#complication_other\').show()\r\n            }else\r\n            $(\'#complication_other\').hide()\r\n           \r\n           }else\r\n             $(\'#complication_other\').hide()\r\n           \r\n        });\r\n\r\n        $(\'#data-implant_brand\').change(function(){\r\n           \r\n           obj = $(this)\r\n           brandv = brands[obj.val()]\r\n           op = $(\'#data-operation\').val()\r\n           opv = operations[op]\r\n          \r\n        //   alert(key)\r\n        \r\n          \r\n           \r\n           if(opv==\'Knee\'){\r\n          \r\n           key = \"\"+opv+\"-\"+brandv\r\n           values = implants[key]\r\n           mask = {}\r\n           for(var id in values){\r\n              ix = values[id];\r\n              mask[ix] = true;\r\n           }\r\n           \r\n           $(\'#data-implant_model\').find(\'option\').remove()\r\n           \r\n           options[\'implant_model\'].each(function(){\r\n               opx = $(this)\r\n               if(mask[opx.attr(\'value\')]==true){\r\n                   opx.clone().appendTo($(\'#data-implant_model\'))\r\n               }\r\n           })\r\n           \r\n           }else\r\n           if(opv==\'Hip\'){\r\n               \r\n               key = \"\"+opv+\"-Stem\"+\"-\"+brandv\r\n               values = implants[key]\r\n               mask = {}\r\n               for(var id in values){\r\n                    ix = values[id];\r\n                    mask[ix] = true;\r\n               }\r\n               $(\'#data-implant_model_stem\').find(\'option\').remove()\r\n               opt