 \r\n       if t[:personal_id]!=\'\'\r\n          cond.merge! :personal_id=>t[:personal_id] \r\n       end\r\n        if t[:hn]!=\'\'\r\n          cond.merge! :hn=>t[:hn] \r\n       end\r\n       \r\n       if t[:gender]!=\'\'\r\n          cond.merge! :gender=>t[:gender] \r\n       end\r\n       \r\n       \r\n       if t[:operation]!=\'\'\r\n          cond.merge! :operation=>t[:operation] \r\n       end\r\n       \r\n       if t[:diagnosis]!=\'\'\r\n          cond.merge! :diagnosis=>t[:diagnosis] \r\n       end\r\n       \r\n           \r\n       if t[:implat_brand]!=\'\'\r\n          cond.merge! :implat_brand=>t[:implat_brand] \r\n       end\r\n        \r\n    end\r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    user = model[:user].where(:login=>@current_user.login).first\r\n    user_id = nil\r\n    \r\n    if user\r\n          cond.merge! :user_id=>user.id \r\n    end\r\n    if @current_role==\'developer\'\r\n        \r\n    end\r\n    \r\n    \r\n    records = models[:thk_record].where(cond).all\r\n    \r\n    \r\n    operations = models[:operation].all.collect{|i|[i.id,i.name]}.to_h\r\n    diagnosis = models[:diagnosis].all.collect{|i|[i.id,i.name]}.to_h\r\n\r\n\r\n\r\n%>\r\n<%\r\nif @current_role==\'developer\' or true\r\n    if user\r\n        no_id = models[:thk_record].where(:personal_id=>\'\', :user_id=>user.id).count\r\n    else\r\n        no_id = models[:thk_record].where(:personal_id=>\'\').count\r\n    end\r\n    \r\n    if no_id > 0\r\n%>\r\n\r\n<div class=\'row-fluid\'>\r\n    <p></p>\r\n    <div class=\'alert alert-danger\'>\r\n        Please fill the missing personal id for <a href=\'javascript:void(0)\' id=\'missing_id\'><%= no_id %></a> patient\r\n    </div>\r\n</div>\r\n<%\r\n    end\r\nend\r\n%>\r\n<h3>Records : <i><%=\"last \\\\#{params[:day]} day(s)\" if params[:day]%></i> </h3>\r\n<table class=\"table table-bordered\" style=\"font-size:0.9em\" >\r\n	<thead>\r\n		<tr>\r\n			<th width=\"\" align=\"center\" valign=\"middle\">Date</th>\r\n			<th width=\"\" align=\"center\" valign=\"middle\">PID</th>\r\n	\r\n			<th width=\"\" align=\"center\" valign=\"middle\">Op.</th>\r\n			<th width=\"\" align=\"center\" valign=\"middle\">Dx.</th>\r\n			\r\n			<th></th>\r\n      </tr>\r\n	</thead>\r\n	<tbody>\r\n	   <% for i in records \r\n	    idb = i.personal_id\r\n	    \r\n	    idb = idb[0..2]+\"..\"+idb[-4..-1] if idb[0..2] and idb[-4..-1]\r\n	    gender = \'-\'\r\n	    gender = \'M\' if i.gender==\'1\'\r\n	    gender = \'F\' if i.gender==\'2\'\r\n	    \r\n	    \r\n	    pid = i.hn\r\n	    count = 0 \r\n	    \r\n	    if i.personal_id and i.personal_id!=\"\"\r\n	        pid = idb \r\n	        count = models[:thk_record].where(:personal_id=>i.personal_id).count\r\n	    else\r\n	        count = models[:thk_record].where(:hn=>i.hn).count\r\n	    end\r\n	    \r\n	   %>\r\n		<tr>\r\n			<td><%=i.date.strftime(\"%d/%m/%y\") if i.date%></td>\r\n			<td><%=pid %> (<%=gender%>) <i style=\"color:#999\"><%=count%> records</i></td>\r\n		\r\n			<td><%=operations[i.operation]%></td>\r\n	        <td><%=diagnosis[i.diagnosis]%></td>\r\n	        \r\n			<td>\r\n			<% if i.personal_id and i.personal_id!=\"\" %>\r\n			 <a href=\"detail?id=<%=i.personal_id%>\" class=\"btn btn-info btn-small\">Detail</a>\r\n			 <% elsif i.hn and i.hn!=\"\" %>\r\n			 <a href=\"detail?id=<%=i.hn%>\" class=\"btn btn-info btn-small\">Detail</a>\r\n             <% else %>\r\n			 <a href=\"edit?id=<%=i.id%>\" class=\"btn btn-danger btn-small\">Edit require PID</a>\r\n			 <% end %>\r\n			</td>\r\n		</tr>\r\n	<% end %>\r\n\r\n	</tbody>\r\n</table>\r\n\r\n<script>\r\n\r\n    $(\'#missing_id\').click(function() {\r\n        $( \'#result\' ).html(\"<center>loading....</center>\");\r\n        $.ajax({\r\n            url: \"missing_partial\",\r\n            context: document.body\r\n        }).done(function(data) {\r\n            $( \'#result\' ).html( data);\r\n        });\r\n    })\r\n    \r\n</script>\r\n\r\n<%\