   \r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n       records = model.limit(rows).skip(offset).all :order=>\'code\'\r\n    end\r\n   \r\n   products = records\r\n   \r\n#   products = products.sort{|a,b| t = 1 if a.category_id==nil; t = -1 if b.category_id==nil ; t=a.allocation<=>b.allocation if t==0 ; t = a.name<=>b.name if t==0; t   } \r\n   \r\n   \r\n   \r\n%>\r\n\r\n\r\n<table class=\"table\">\r\n   <thead>\r\n    <tr>\r\n        <th>No.</th>\r\n        <th>Description</th>\r\n        <th>Code</th>\r\n        \r\n        <th>Group Code</th>\r\n        \r\n        <th>Vendor Code</th>\r\n         <th>Vendor Group</th>\r\n        <th>Cost</th>\r\n        <th>Price</th>\r\n  \r\n        <th>Allocation</th>\r\n        <th>Category</th>\r\n        <th>BOM</th>\r\n        \r\n        <th>&nbsp;</th>\r\n    </tr>\r\n    </thead>\r\n    <tbody>\r\n    <% products.each_with_index do |p,pi| \r\n        \r\n    \r\n       name = p.name\r\n       \r\n       name = name[0..50]+\" . . . \" if name.size> 50\r\n    %>\r\n    \r\n    <tr>\r\n          <td>\r\n            <%= pi+1+offset %>\r\n        </td>\r\n        <td>\r\n            <%= name %>\r\n        </td>\r\n        <td>\r\n            <%=p.code %>\r\n        </td>\r\n        \r\n         <td>\r\n            <%=p.group_code %>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=p.vendor_code %>\r\n        </td>\r\n    \r\n          <td>\r\n            <%=p.vendor_group %>\r\n        </td>\r\n        <td>\r\n            <%=p.cost %>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=p.price %>\r\n        </td>\r\n       \r\n         <td>\r\n            <%=p.allocation %>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=  models[:pl_category].find(p.category_id).name if p.category_id%>\r\n        </td>\r\n        \r\n        <td>\r\n            <% items =  models[:pl_product_bom].where(:product_id=>p.id).count %>\r\n            <%=link_to  \'BOM\', \"show?id=\\\\#{p.id}\", :class=>\'btn btn-info\' if items > 0%> \r\n        </td>\r\n        \r\n        <td>\r\n        <%\r\n            i = p\r\n        %>\r\n        \r\n            <%=link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' ) %>\r\n<%=link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\') %>\r\n<%=link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:data=>{:confirm=>\'Are you sure?\'}) %>\r\n        </td>\r\n        \r\n    </tr>\r\n    \r\n    \r\n    <% end %>\r\n    </tbody>\r\n    \r\n</table>\r\n\r\n\r\n\r\n\r\n<%# tabular :model=>labels, :data=>records do |i,out|\r\n\r\nfields.each_with_index do |f,index|\r\n\r\nout[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n\r\nend\r\n\r\nout<<link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nout<<link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\')\r\nout<<link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:data=>{:confirm=>\'Are you sure?\'})\r\nout\r\nend\r\n%>\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        \r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2018-02-11 07:13:20','2018-02-11 07:13:20','list',''),(3323,'index',1325,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query, Regexp::IGNORECASE)}\r\n        end\r\n        dates = {}\r\n        if false and params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 50\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'index\' do |f| %>\r\n<div>\r\n<!--\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n-->\r\n\r\n\r\n<% %w{ PI LAB ADM DRUG HOS NRC OH PH SU VOL}.each do |i| %>\r\n<%=link_to i, \"index?group=\\\\#{i}\", :class=>\"btn \\\\#{\'btn-info\' if params[:group]==i}\" %>\r\n<% end %>\r\n<%=link_to \'Show All\', \"index\", :class=>\"btn btn-warning\" if params[:group] %>\r\n\r\n\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-small\' %>\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2018-02-11 07:17:03','2018-02-11 07:17:03','index',''),(3324,'customer_index',1272,2,'',NULL,NULL,NULL,'2018-02-11 13:11:48','2018-02-11 13:11:48','customer_index',''),(3325,'message',1272,2,'<h3 class=\"heading\" style=\"color:red\">Project : HER kinase inhibition in patients with HER2- and HER3-mutant cancers</h3>\r\n<div class=\"chat_box\">\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12 chat_content\">\r\n										<div class=\"chat_heading clearfix\">\r\n											<div class=\"pull-right\"><i class=\"icon-remove chat_close\"></i></div>\r\n											Active users: <span class=\"act_users\">2</span>\r\n										</div>\r\n										\r\n										<div class=\"msg_window\">\r\n											<div class=\"chat_msg clearfix msg_clone\" style=\"display:none\">\r\n												<div class=\"chat_msg_hea