ckground-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><%=project.protocol_no%></span>\r\n           </li>\r\n     \r\n        </ul></div></div>\r\n    </div>\r\n</nav>\r\n\r\n\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%> </h3>\r\n<div class=\"pull-right\">\r\n\r\n<%# link_to \'<i class=\"splashy-printer\"></i> Show Detail\'.html_safe, \"javascript:$(\'#project-detail\').toggle()\",:class=>\'btn btn-mini\' %>\r\n\r\n\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" id=\"project-detail\">\r\n<%\r\n\r\n    active = \'overview\'\r\n    active = params[:active] if params[:active] \r\n\r\n%>\r\n\r\n\r\n<div class=\"tabbable tabbable-bordered\">\r\n	<ul class=\"nav nav-tabs\">\r\n		<li class=\"<%=\'active\' if active==\'overview\' %>\"><a href=\"#tab_br1\" data-toggle=\"tab\" class=\"tab_btn\">Overview</a></li>\r\n		<li class=\"<%=\'active\' if active==\'schedule\' %>\"><a href=\"#tab_br2s\" data-toggle=\"tab\" class=\"tab_btn\">Patient Schedule</a></li>\r\n		<li class=\"<%=\'active\' if active==\'patient\' %>\"><a href=\"#tab_br2\" data-toggle=\"tab\" class=\"tab_btn\">Patient List</a></li>\r\n		\r\n		<li class=\"<%=\'active\' if active==\'protocol\' or active==\'protocol2\' %>\"><a href=\"#tab_br3\" data-toggle=\"tab\" class=\"tab_btn\">Protocol & Budget</a></li>\r\n		<li><a href=\"#tab_br4\" data-toggle=\"tab\" class=\"tab_btn\">Screening &amp; Payment</a></li>\r\n		<li><a href=\"#tab_br5\" data-toggle=\"tab\" class=\"tab_btn\">Documents</a></li>\r\n		<li><a href=\"#tab_br6\" data-toggle=\"tab\" class=\"tab_btn\">Members</a></li>\r\n		<li><a href=\"#tab_br8\" data-toggle=\"tab\" class=\"tab_btn\">Reports</a></li>\r\n\r\n	</ul>\r\n	<div class=\"tab-content\">\r\n		<div class=\"tab-pane <%=\'active\' if active==\'overview\' %>\" id=\"