ms[:id]).all\r\n        \r\n\r\n       \r\n        events = list.clone\r\n    \r\n    \r\n             events.collect!{|e|  \r\n    \r\n                  \r\n            \r\n                    # period = models[:pl_period].find e.period_id\r\n                    # project = mprojects[e.project_id]\r\n                    # patient = models[:patient].find e.patient_id\r\n                    # title = \"\\\\#{project.protocol_no} : \\\\#{period.visit if period} : \\\\#{patient.subject_id} : \\\\#{patient.first_name} \\\\#{patient.last_name} \\\\#{\'#\'+e.note if e.note}\"\r\n                    p = mp[e.patient_id]\r\n                    title = \"\\\\#{e.name}\" \r\n                    traveling = \"*T: \\\\#{e.traveling_note} \\\\#{e.traveling_status}\" if e.traveling_note and e.traveling_note!=\"\"\r\n                    title = \"\\\\#{e.name} : \\\\#{p.subject_id} : \\\\#{p.first_name} \\\\#{p.last_name} \\\\#{traveling}\" if p\r\n                    \r\n                        color = \"#f5eeef\"\r\n                    \r\n                    color = \"#eff5ef\" if e.status==\'Completed\'\r\n                    \r\n                    date = e.date \r\n                    if date \r\n                        \r\n                        date = DateTime.parse(e.date.strftime(\"%Y-%m-%d\")+\"T\"+e.date.strftime(\"%H:%M\") )    \r\n                    \r\n                else\r\n                    %>\r\n                   <%=link_to \'Error\', \"../Visit/show?id=\\\\#{e.id}\"%> \r\n                <%\r\n                end\r\n                    \r\n    \r\n    			{\r\n    			        :title=>title.html_safe,\r\n						:start=> date,\r\n						:end=>  date,\r\n						:allDay=> true,\r\n                        :color=> color,\r\n                        :textColor=>\"#111\",\r\n                        :url=>\"../Visit/show?id=\\\\#{e.id}\"\r\n                }\r\n    \r\n    }\r\n        \r\n        \r\n        \r\n    \r\n        app_list = models[:patient_schedule].where(:patient_id=>{\'$in\'=>patients.collect{|i| i.id }}).all\r\n\r\n        app_events = app_list.collect{ |e|\r\n        \r\n        \r\n                p = mp[e.patient_id]\r\n                title = \"\\\\#{e.name}\" \r\n                title = \"\\\\#{e.name} : \\\\#{p.subject_id} : \\\\#{p.first_name} \\\\#{p.last_name}\" if p\r\n          \r\n    \r\n    			{\r\n    			        :title=>title,\r\n						:start=> DateTime.parse(e.start_date.strftime(\"%Y-%m-%d\")+\"T\"+e.start_time.strftime(\"%H:%M\") ),\r\n						:end=>  DateTime.parse(e.end_date.strftime(\"%Y-%m-%d\")+\"T\"+e.end_time.strftime(\"%H:%M\")),\r\n						:allDay=> true,\r\n                        :color=> \"#eeeeee\",\r\n                        :textColor=>\"#111\",\r\n                        :url=>\"../PatientSchedule/show?id=\\\\#{e.id}\"\r\n                }\r\n        \r\n       \r\n        \r\n        \r\n    }\r\n        \r\n        events+=app_events\r\n\r\n    \r\n    \r\n%>\r\n\r\n   <div class=\"row-fluid\">\r\n    <div id=\"calendar-schedulex\" class=\"span12\" style=\"\"></div>\r\n  </div>  \r\n        <script>\r\n        \r\n        \r\n$(document).ready(function() {\r\n		gebo_calendar_schedulex.regular();\r\n// 		gebo_calendar.google();\r\n		//* resize elements on window resize\r\n		var lastWindowHeight = $(window).height();\r\n		var lastWindowWidth = $(window).width();\r\n		$(window).on(\"debouncedresize\",function() {\r\n			if($(window).height()!=lastWindowHeight || $(window).width()!=lastWindowWidth){\r\n				lastWindowHeight = $(window).height();\r\n				lastWindowWidth = $(window).width();\r\n				//* rebuild calendar\r\n				$(\'#calendar-schedulex\').fullCalendar(\'render\');\r\n				// $(\'#calendar_google\').fullCalendar(\'render\');\r\n			}\r\n		});\r\n		\r\n		$(\'.fc-button-content\').click();\r\n		\r\n	});\r\n	\r\n	//* calendar\r\n	gebo_calendar_schedulex = {\r\n		regular: function() {\r\n			var date = new Date();\r\n			var d = date.getDate();\r\n			var m = date.getMonth();\r\n			var