here(:document_id=>params[:id]).first\r\n    history = []\r\n    \r\n    if docx \r\n        \r\n        history = get_model(\'document_history\').where(:project_document_id=>docx.id).all\r\n        #return_url = \"../Project/show?id=\\\\#{docx.project_id}\"\r\n        project_id = docx.project_id\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    if params[:pid]\r\n      \r\n      project_id = params[:pid]  \r\n    end\r\n    \r\n  \r\n  if project_id\r\n%>\r\n<div id=\"context_menu\">\r\nLoading...\r\n</div>\r\n<script>\r\n    $.ajax({\r\n  url: \"../Project/context_menu_partial?id=<%=project_id%>\",\r\n  context: document.body\r\n}).done(function(data) {\r\n  $(\'#context_menu\' ).html( data );\r\n});\r\n</script>\r\n\r\n<% end %>',NULL,NULL,NULL,'2018-02-11 16:17:16','2018-02-11 16:17:16','context_menu_tmp',''),(3329,'create',1332,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<% link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n    www = @context.get_projects_by_abstract(\'www.www\')[0]\r\n    user_model = www.load_model[:user] \r\n    user = user_model.where(:login=>@current_user.login).first\r\n    unless user\r\n    user = user_model.where(:login=>\'admin\').first\r\n    end\r\n    user_id = nil\r\n    user_id = user.id if user\r\n    \r\n    \r\n  \r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    \r\n    \r\n    if params[:pid]\r\n       \r\n       mproject = get_model \'project\' \r\n       \r\n       project = mproject.find(params[:pid])\r\n       \r\n       if project\r\n          \r\n            mproject_doc = get_model \'project_document\'\r\n            \r\n          \r\n            \r\n            docx = mproject_doc.create :last_updated_by=>user_id, :date=>Time.now, :document_name=>\"\\\\#{this.document_name}\", :project_id=>project.id, :document_id=> record.id \r\n            \r\n            mdocument_history =  get_model \'document_history\'\r\n            \r\n            mdocument_history.create :login=>\"\\\\#{@current_user}/\\\\#{@current_role}\", :user_id=>user_id, :project_document_id=>docx.id, :document_id=>record.id, :type=>\'CREATE\'\r\n            \r\n                \r\n            \r\n            \r\n            \r\n           \r\n       end\r\n       \r\n       \r\n        \r\n        \r\n    end\r\n    \r\n    \r\n    \r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n    return_url = \"show?id=\\\\#{record.id}\"\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n\r\n<%= hidden_field_tag \'pid\', params[:pid] %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</di