 <% end %>\r\n    	       \r\n\r\n    	    </td>\r\n    	    <td>\r\n    	         <%=link_to \"Del\", \"remove_attachment?id=\\\\#{j.id}&tab=\\\\#{index}\", :data=>{:confirm=>\'Are you sure?\'},:class=>\'btn btn-danger btn-mini\'%>\r\n\r\n\r\n    	    </td>\r\n    	</tr>\r\n    	<% end %>\r\n    	</tbody>\r\n    </table>\r\n    								\r\n    <hr/>\r\n    \r\n    \r\n    <%= form_for :record, :url=>\"../DocumentAttachment/create\", :html=>{:multipart=>true} do |f| %>	\r\n    <label>\r\n    <h4><%=i[:title]%> Upload (.jpeg, .png, .pdf, .xlsx, .docx):</h4>\r\n    </label>\r\n    <%= f.hidden_field :name,:value=>i[:name] %>\r\n    <%= f.hidden_field :project_document_id,:value=>docx.id %>		\r\n    <%= hidden_field_tag :return,request.url+\"&tab=\\\\#{index}\" %>		\r\n    <div id=\"file-<%=i[:name]%>\" class=\"  portlet \" style=\"border:0px solid blue;width:530px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n        <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n            <div style=\"border:0px dotted;\">\r\n                <div style=\"width:100%\">\r\n                    <table border=\"0\">\r\n                        <tr>\r\n                            <td>\r\n                                1. Name : \r\n                            </td>\r\n                            <td>\r\n                                <%= f.text_field :note, :value=>\"\" %> \r\n                            </td>\r\n                            \r\n                        </tr>\r\n                        <tr>\r\n                             <td>\r\n                                2. Comment : \r\n                            </td>\r\n                            <td>\r\n                                <%= f.text_field :comment, :value=>\"\" %> \r\n                            </td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td>    \r\n                            3. File : \r\n                            </td>\r\n                            <td>\r\n                                <a id=\"a_data-file-<%=i[:name]%>\" target=\"_blank\" href=\"\" onclick=\"return false;\">\r\n                            <img width=\"160\" id=\"img_data-file-<%=i[:name]%>\" class=\"\" alt=\"\" style=\"border:0px solid blue\" src=\"\">\r\n                            </a>\r\n                            \r\n                                <div class=\"k-widget k-upload\">\r\n                                    <div class=\"k-dropzone\">\r\n                                        <div class=\"btn k-upload-button\">\r\n                                            <input name=\"upload[file]\" id=\"_data-file-<%=i[:name]%>\" type=\"file\" data-role=\"upload\"  autocomplete=\"off\" ><span>Select...</span>\r\n                                        </div>\r\n                                        <em>drop files here to upload</em>\r\n                                    </div>\r\n                                </div>\r\n                            \r\n                            </td>\r\n                        </tr>\r\n                    </table>\r\n                    <%= f.submit \'Upload\', :id=>\"upload-\\\\#{i[:name]}\", :class=>\'btn\', :disabled=>true%>\r\n                    <input type=\"hidden\" name=\"record[file]\" id=\"data-file-<%=i[:name]%>\">\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <div class=\"clear\"></div>\r\n        <script type=\"text/javascript\" charset=\"utf-8\">\r\n            //$(\"#data-name\").kendoAutoComplete();\r\n            //$(\"#data-note\").kendoAutoComplete();\r\n            function onSuccess(e) {\r\n            }\r\n            \r\n             $(document).ready(function() {\r\n            \r\n                 $(\"#_data-file-<%=i[:name]%>\").kendoUpload({\r\n                     async: {\r\n                         saveUrl: \"/esm_attachments/851/upload.json?p_id=486&field_id=F1505628217\",\r\n                         autoUpload: true\r\n                     },\r\n            		success: function(e){\r\n            			$.map(e.files, function(file) {\r\n            			        var info = file.name;\r\n            			});\r\n            			$(\"#data-file-<%=i[:name]%>\").val(e.response.id)\r\n            			$(\"#img_data-file-<%=i[:name]%>\").attr(\'src\',e.response.path)\r\n            			$(\"#a_data-file-<%=i[:name]%>\").attr(\'href\',e.response.path)\r\n            			$(\".k-upload-files\").empty();\r\n            			 $(\".k-upload-files\").hide();   \r\n            	\r\n            			$(\"#upload-<%=i[:name]%>\").addClass(\"btn-success\")\r\n            			$(\"#upload-<%=i[:name]%>\").prop(\"disabled\", false);\r\n            		}\r\n            });\r\n            });\r\n        </script>\r\n    <% end %>						\r\n    										\r\n    \r\n    <hr/>\r\n</div>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n<% end %>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n  \r\n\r\n    \r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"alert\"><label>\r\n\r\n    \r\n</label>\r\n   \r\n\r\n    <% \r\n     action_count =0 \r\n    if config[:actions] \r\n   \r\n    \r\n    for i in config[:actions]\r\n    \r\n     if i[:action_by] ==nil or ( i[:action_by] and i[:action_by].index(@current_role))\r\n         action_count+=1\r\n    %>\r\n    \r\n    <%= link_to i[:name], \"\\\\#{i[:action]}?id=\\\\#{params[:id]}\", :class=>i[:class]  %>\r\n      <% end %><% end %>\r\n    <% end %>\r\n    \r\n   <%=\'|\' if action_count>0 %>\r\n\r\n    <% if config[:submit_by] and config[:submit_by].index(@current_role) %>\r\n    <% if docx.status == nil or docx.status==\'draft\' or docx.status==\'reply\'    %>\r\n    <%\r\n        text = \'Submit\'\r\n    %>\r\n    <%= link_to \'Submit\', \"process_doc?id=\\\\#{params[:id]}&status=pending\", :class=>\'btn btn-success\',:data=>{:confirm=>\"Are you sure?\"} %>\r\n    <% end  %>\r\n    <% end %>\r\n    \r\n    <% if config[:approve_by] and config[:approve_by].index(@current_role)%>\r\n    \r\n    \r\n    \r\n    <% if docx.status==\'pending\' %>\r\n    <%= link_to \'Review\', \"process_doc?id=\\\\#{params[:id]}&status=review\", :class=>\'btn btn-info\' ,:data=>{:confirm=>\"Are you sure?\"}%>\r\n    <% end %>\r\n\r\n    <% if docx.status==\'review\'%>\r\n    <%= link_to \'Reply\', \"process_doc?id=\\\\#{params[:id]}&status=reply\", :class=>\'btn btn-info\',:data=>{:confirm=>\"Are you sure?\"} %>\r\n    <% end %>\r\n\r\n    \r\n    <% if docx.status==\'pending\' or docx.status==\'review\' or docx.status==\'reply\' %>\r\n    <%= link_to \'Finished\', \"process_doc?id=\\\\#{params[:id]}&status=finished\", :class=>\'btn btn-danger\',:data=>{:confirm=>\"Are you sure?\"} %>\r\n    <% end %>\r\n    \r\n    \r\n    <% if true %>\r\n    <%= link_to \'Back to Draft\', \"process_doc?id=\\\\#{params[:id]}&status=draft\", :class=>\' \' %>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n\r\n  <right><%=docx.status%></right> \r\n    \r\n    \r\n    \r\n    </div>\r\n \r\n    \r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<br/>\r\n\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n   History\r\n</div>    \r\n<div class=\"w-box-content cnt_a\">\r\n     <table class=\"table\">\r\n         \r\n         <%\r\n         \r\n         for i in history.reverse\r\n         \r\n         %>\r\n         <tr>\r\n         <td>\r\n            <%=i.login%>\r\n         </td>\r\n         \r\n            \r\n         <td>\r\n            <%=i.type%>\r\n         </td>\r\n         \r\n        \r\n         <td>\r\n            <%=i.created_at%>\r\n         </td>\r\n        \r\n     \r\n        </tr>\r\n         <% end %>\r\n         \r\n         \r\n         \r\n     </table>\r\n    \r\n</div>\r\n\r\n</div>\r\n\r\n<% rescue Exception =>e %>\r\n<%=e%>\r\n\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2018-02-11 17:15:34','2018-02-11 17:15:34','show',''),(3337,'index_partial',1294,3,'<%\r\n    main = \'../Home/index\'\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	%>\r\n<%# aps.inspect %>\r\n<%\r\n	id = \'\'\r\n	a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = module_model.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n	\r\n	sm = {}\r\n	# form service\r\n	f_ser = {}\r\n	# service_map\r\n	sv =  @current_project.get_services_by_abstract(\'ehr.emr.Document\')\r\n	sv.each do |i|\r\n	    nm = i[:name]\r\n	    if nm == \'appointment\' or nm == \'billing\' or nm == \'live_document\'\r\n	        next\r\n	    end\r\n	    \r\n	   # sm[nm.to_sym] = i[:title]\r\n	   sm[nm.to_sym] = i[:package].split(\'.\')[-1]\r\n	   \r\n	end\r\n	\r\n	sm.each do |k, v|\r\n	    f_ser[k] = {}\r\n	    tmp = module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>pa_id).all\r\n	    tmp.each do |i|\r\n	        f_ser[k][i[:patient_id].to_s] = i.id.to_s\r\n	    end\r\n	end\r\n	\r\n	aps.collect!{|i| \r\n        id = i.id\r\n        if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n            pat_id = m.patient_id.to_s\r\n    	     patient = patient_model.find(m.patient_id)\r\n    	     if patient \r\n        	     provider = p_model.find(i.provider)\r\n        	     visit_type = visits[i.visit_type]\r\n        	     provider_name = \'NA\'\r\n        	     provider_name = provider.name if provider\r\n        	     procedure_name = \'NA\'\r\n        	     pro = models[:procedure].find(i.procedure) \r\n        	     procedure_name = pro.name if pro\r\n        	     patient = patient_model.new unless patient \r\n        	     hn = \'-\'\r\n        	     \r\n        	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n        	     provider_name  = link_to(provider_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     procedure_name = link_to(procedure_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     public_id = \'-\'\r\n    	    \r\n                c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id.to_s}\"),\r\n        	     :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        	     :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Arrived\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n        	     :visit_type=>visit_type,\r\n        	     :note=>i[:note]\r\n                }\r\n                \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info \',