    # v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            # \"../\\\\#{v}/print?id=\\\\#{f_ser[k][pat_id]}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\', :target=>\'_blank\')\r\n                    end\r\n                    l_list << v_link\r\n        end\\\\#{request.fullpath}\r\n        \r\n                c[:processing_ctrl]= \"\\\\#{d_link}\".html_safe \r\n                c[:processing_ctrl] = \"\\\\#{l_list.join(\' \')} \\\\#{c[:processing_ctrl]}\".html_safe\r\n                \r\n                c\r\n            end\r\n        end\r\n	}.compact!\r\n	\r\n	table_model = %w{ hn patient provider visit_type processing_ctrl   note }.collect{|i| i.to_sym}\r\n	\r\n	\r\n	aps.collect!{|i| \r\n	\r\n	    i if i[:status]!=\'Cancelled\'\r\n	    \r\n	}.compact!\r\n	\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:procedure=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n	:note=>\'Note\',:visit_type=>\'Visit\',:processing_ctrl=>\'Actions\', :out_pat=>\'Out Patient Form\' }\r\n	\r\n	%>\r\n	<%# aps.to_json.html_safe %>\r\n	<% if @current_role==\'developer\' and false%>\r\n	<%= sm.to_json.html_safe %> <hr/>\r\n	<%= sv.to_json.html_safe %>\r\n	<% end %>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=aps.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\'background:#FCF8F0\'>\r\n			                        <div class=\'row-fluid\'>\r\n			                            <table id=\'appointed-patient\' class=\"table table-striped table-bordered dTableR\">\r\n    										<thead>\r\n    											<tr>\r\n    											\r\n<%  table_model.each do |i| %>\r\n    												<th><%= labels[i.to_sym] %></th>\r\n<%  end %>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n    if aps.size > 0\r\n        aps.each do |i|\r\n%>\r\n                                                <tr>\r\n<%\r\n            table_model.each do |j|\r\n                \r\n%>\r\n                                                    <td style=\'vertical-align:middle\'><%= (i[j].nil? or i[j]==\'\') ? \'-\' : i[j] %></td>\r\n<%\r\n            end\r\n%>\r\n                                                </tr>\r\n<%\r\n        end\r\n%>\r\n<% end %>\r\n                                            </tbody>\r\n                                        </table>\r\n                                    </div>\r\n\r\n\r\n<!--\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = aps.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model,:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = aps.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model,:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n-->\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n</div>\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        gebo_datatbles = {\r\n    		dt_a: function() {\r\n    			$(\'#appointed-patient\').dataTable({\r\n    			    stateSave : true,\r\n                    \"sDom\": \"<\'row\'<\'span6\'<\'dt_actions\'>l><\'span6\'f>r>t<\'row\'<\'span6\'i><\'span6\'p>>\",\r\n                    \"sPaginationType\": \"bootstrap_alt\",\r\n                    \"oLanguage\": {\r\n                        \"sLengthMenu\": \"_MENU_ records per page\",\r\n                        \"sEmptyTable\": \"No patient available in table. Please \'<a href=\'javascript:add_patient()\'>Add</a>\' the patient.\"\r\n                    }\r\n                });\r\n    		}\r\n        }\r\n        \r\n        gebo_datatbles.dt_a();\r\n        // gebo_datatbles.state.save();\r\n        \r\n        // $(\'#appointed-patient\').DataTable( {\r\n        //     stateSave: true,\r\n        //     columnDefs: [ {\r\n        //         targets: [ 0 ],\r\n        //         orderData: [ 0, 1 ]\r\n        //     }, {\r\n        //         targets: [ 1 ],\r\n        //         orderData: [ 1, 0 ]\r\n        //     }, {\r\n        //         targets: [ 4 ],\r\n        //         orderData: [ 4, 0 ]\r\n        //     } ]\r\n        // } );\r\n    })\r\n</script>',NULL,NULL,NULL,'2018-02-12 03:09:41','2018-02-12 03:09:41','index_partial',''),(3338,'config',1294,1,'[\r\n{:name=>\'Records\',:open=>true,:actions=>[\r\n{:name=>\'Pain assessment tools\',:service=>\'pain_assessment_tools\',:link=>\'../PainAassessmentTools/index\',:remote=>false},\r\n{:name=>\'Assessment form\',:service=>\'assessment_form\',:link=>\'../AssessmentForm/index\',:remote=>false},\r\n{:name=>\'Set OR for pain intervention\',:service=>\'set_or_for_pain_intervention\',:link=>\'../SetOrForPainIntervention/index\',:remote=>false},\r\n{:name=>\'Pain intervention record\',:service=>\'pain_intervention_record\',:link=>\'../PainInterventionRecord/index\',:remote=>false}]}]',NULL,NULL,NULL,'2018-02-12 04:42:26','2018-02-12 04:42:26','config',''),(3339,'document_name',1336,1,'\'assessment_form\'',NULL,NULL,NULL,'2018-02-12 04:51:44','2018-02-12 04:51:44',NULL,NULL),(3340,'document_name',1337,1,'\'user_project\'',NULL,NULL,NULL,'2018-02-12 14:22:44','2018-02-12 14:22:44',NULL,NULL),(3341,'index_tmp',1272,2,'<style>\r\n    .table thead th {\r\n    background-color: #b405a0 !important;\r\n}\r\n</style>\r\n\r\n\r\n<h3 class=\"heading\">Research Project Management</h3>\r\n<a href=\"#\" class=\"btn btn-success\">+ New project</a> admin mode------></admin> <a href=\"report\" class=\"btn\"> Summary Report</a> | <a href=\"admin\" class=\"btn\"> Administration </a> <hr>\r\n\r\n\r\n<table class=\"table table-bordered\" width=\"100%\">\r\n										<thead>\r\n											<tr>\r\n												<th width=\"2%\" height=\"36\" align=\"center\" valign=\"middle\">Peoject id</th>\r\n												<th width=\"28%\" align=\"center\" valign=\"middle\">Project Name</th>\r\n												<th width=\"65%\" align=\"center\" valign=\"middle\">Detail</th>\r\n												<th width=\"5%\" align=\"center\" valign=\"middle\">Status</th>\r\n												<th width=\"5%\" align=\"center\" valign=\"middle\">Action</th>\r\n								          </tr>\r\n										</thead>\r\n										<tbody>\r\n											<tr>\r\n												<td>PJ0001-60</td>\r\n												<td>HER kinase inhibition in patients with HER2- and HER3-mutant cancers</td>\r\n												<td>In a basket trial design, the efficacy of the pan-HER kinase inhibitor neratinib is tested in patients with 21 different tumour types, and responses are determined by mutation and tissue type, and are restricted to HER2-mutant cancers.</td>\r\n												<td>Bugget</td>\r\n												<td><a href=\"project\" class=\"btn btn-info\">Detail</a></td>\r\n											</tr>\r\n											<tr>\r\n												<td>PJ0002-60</td>\r\n												<td>High performance plasma amyloid-β biomarkers for Alzheimer\'s disease</td>\r\n												<td>Measurement of human plasma amyloid-β biomarkers using immunoprecipitation coupled with mass spectrometry reliably predicts individual brain amyloid-β status and has potential clinical utility.</td>\r\n												<td>On process</td>\r\n												<td><a href=\"project\" class=\"btn btn-info\">Detail</a></td>\r\n											</tr>\r\n											<tr>\r\n												<td>PJ0003-60</td>\r\n												<td>Characterizing steroid hormone receptor chromatin binding landscapes in male and female breast cancer</td>\r\n												<td>Male breast cancer (MBC) is rare and largely hormonally driven. Here, the authors examine the action of steroid hormone receptors in male and female breast cancers and find gender selective hormone receptor action that associates with the survival of MBC patients.</td>\r\n												<td>On process</td>\r\n												<td><a href=\"project\" class=\"btn btn-info\">Detail</a></td>\r\n											</tr>\r\n											<tr>\r\n												<td>PJ0001-61</td>\r\n												<td>Differential regulation of hepcidin in cancer and non-cancer tissues and its clinical implications</td>\r\n												<td><ul>\r\n												  <li itemprop=\"creator\" itemscope=\"\" itemtype=\"http://schema.org/Person\"><span itemprop=\"name\">Driton Vela</span></li>\r\n												  <li itemprop=\"creator\" itemscope=\"\" itemtype=\"http://schema.org/Person\"> &amp; <span itemprop=\"name\">Zana Vela-Gaxha</span></li>\r\n											    </ul></td>\r\n												<td>Finish</td>\r\n												<td><a href=\"project\" class=\"btn btn-info\">Detail</a></td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-02-12 14:40:32','2018-02-12 14:40:32','index_tmp',''),(3342,'layout',1272,4,'\r\n<%= default_layout %>\r\n<style>\r\n    .accordion-inner li{\r\n        margin:5px;\r\n  \r\n    }\r\n    .sidebar .accordion-group .accordion-heading .accordion-toggle{\r\n        background-color:#e0e0e0;\r\n        color:#222;\r\n        transition: background-color 0.2s ease-in-out;\r\n    }\r\n    .sidebar .accordion-group a{\r\n        border:0px solid;\r\n    }\r\n    \r\n    .w-box-content .nav-tabs li a{\r\n        font-size:15px;\r\n    }\r\n</style>\r\n\r\n\r\n\r\n<div id=\"msg-link\">\r\n<li class=\"hidden-phone hidden-tablet \">\r\n  <div class=\"nb_boxes clearfix hide\">\r\n  <a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#myMail\" class=\"label ttip_b\" oldtitle=\"New messages\" aria-describedby=\"ui-tooltip-0\">25 <i class=\"splashy-mail_light\"></i></a>\r\n  <a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#myTasks\" class=\"label ttip_b\" oldtitle=\"New t