ง project. ใหม่\r\nมีมากมายหลายอย่าง\r\n</pre>\r\n \r\n\r\n<center >\r\n<%= link_to \'Create Project\', \"../Project/create\", :class=>\'btn btn-success\' %>\r\n</center>\r\n\r\n</div>\r\n</div>\r\n\r\n<% else %>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<br/>\r\n<span \"right\"><%= link_to \'Create More Project\', \"../Project/create\", :class=>\'\' %>\r\n<% end %>',NULL,NULL,NULL,'2018-02-12 15:19:41','2018-02-12 15:19:41','index_customer',''),(3345,'index_admin',1272,3,'<div class=\"heading\">\r\n    <h1>Welcome Admin</h1>\r\n</div>    \r\n<%\r\n    \r\n    models = get_model\r\n    \r\n    today_schedule = 0\r\n\r\n%>\r\n\r\n<%# image_tag \"/esm/cusys/cucrc/ic1.png\"%>\r\n\r\n<ul class=\"dshb_icoNav tac\">\r\n<li><a href=\"../Home/dashboard\" style=\"background-image: url(/gebo/img/gCons/computer.png)\">Dashboard</a></li>\r\n<li><a href=\"../Project/index\" style=\"background-image: url(/gebo/img/gCons/globe.png)\"><span class=\"label label-info\"><%=models[:project].count %></span> Projects</a></li>\r\n<li><a href=\"../Member/index\" style=\"background-image: url(/gebo/img/gCons/female-user.png)\"><span class=\"label label-success\"><%=models[:member].count%></span>Members</a></li>\r\n<li><a href=\"../User/index\" style=\"background-image: url(/gebo/img/gCons/agent.png)\"><span class=\"label label-success\"><%=models[:user].count%></span>Users / Roles</a></li>\r\n<li><a href=\"../Home/schedule\" style=\"background-image: url(/gebo/img/gCons/calendar.png)\"><span class=\"label label-important\"><%=today_schedule%></span>Schedule</a></li>\r\n<li><a href=\"../Patient/index\" style=\"background-image: url(/gebo/img/gCons/happy-face.png)\"><span class=\"label label-success\"><%=models[:patient].count%></span>Patients</a></li>\r\n<li><a href=\"../Report/index\" style=\"background-image: url(/gebo/img/gCons/bar-chart.png)\">Reports</a></li>\r\n<li><a href=\"../Accounting/index\" style=\"background-image: url(/gebo/img/gCons/dollar.png)\">Accounting</a></li>\r\n</ul>\