  user = user_model.where(:login=>\'admin\').first\r\n    end\r\n    user_id = nil\r\n    user_id = user.id if user\r\n    \r\n  \r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    m_user_project = get_model \'user_project\'\r\n    \r\n    m_user_project.create :project_id => record.id, :user_id=>user_id, :role=>\'admin\'\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n    return_url = \"show?id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', \"../Home/index\" %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-02-12 15:37:07','2018-02-12 15:37:07','create',''),(3347,'contact_us',1272,2,'',NULL,NULL,NULL,'2018-02-12 15:55:50','2018-02-12 15:55:50','contact_us','*'),(3348,'manual',1272,2,'<h1>User manual</h1>',NULL,NULL,NULL,'2018-02-12 15:56:09','2018-02-12 15:56:09','manual',''),(3349,'download',1272,2,'<h1>Downloads</h1>',NULL,NULL,NULL,'2018-02-12 15:56:27','2018-02-12 15:56:27','download',''),(3350,'activities',1272,2,'<h1>Activities</h1>',NULL,NULL,NULL,'2018-02-12 15:56:49','201