der = \'หญิง\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>เพศ : </strong><%= gender %> &nbsp; <strong>อายุ :&nbsp;</strong>\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D-->\r\n      </td>\r\n          <td>\r\n         \r\n              <% if record[\'operative_date\']!=nil %>\r\n\r\n<label>Operative date : </label><%=render_value \'operative_date\'%>\r\n\r\n\r\n<% end%>\r\n          </td>\r\n          \r\n      </tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n \r\n	<hr style=\"margin-top: 5px; border-top: 2px solid #868686;\"/>\r\n    \r\n    <br />\r\n\r\n  \r\n    <div style=\"float:left;width: 800px; font-size:13px\">\r\n   <!--   -->\r\n   \r\n   \r\n   \r\n   \r\n   <div style=\"width:100%;border: 0px solid blue;padding-top:0px;padding-bottom:0px\" id=\"form-data\">\r\n	\r\n<div  style=\"margin-left:auto;margin-right:auto;padding:1px;\" class=\"form-data-content\">\r\n\r\n\r\n\r\n<div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:100%;margin:0px;min-height:50px\" >\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"vas\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;\">\r\n\r\n<% if record[\'vas\']!=\"\" %>\r\n<span class=\"\"><label>1.VAS (Visual Analog Scale) : </label><%=render_value \'vas\'%></span>\r\n<% end%>\r\n</div>\r\n\r\n\r\n<div id=\"nrs\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;\">\r\n\r\n\r\n<% if record[\'nrs\']!=\"\" %>\r\n<span class=\"\"><label>2.NRS (Numeric Rating Scale) : </label><%=render_value \'nrs\'%></span>\r\n<% end%>\r\n</div>\r\n<div id=\"vrs\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;\">\r\n\r\n\r\n<% if record[\'vrs\']!=\"\" %>\r\n<span class=\"\"><label>3.VRS (Verbal Rating Scale) : </label><%=render_value \'vrs\'%></span>\r\n<% end%>\r\n</div>\r\n<div id=\"revised_faces_pain_scale\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;\">\r\n\r\n\r\n<% if record[\'revised_faces_pain_scale\']!=\"\" %>\r\n<span class=\"\"><label>4.Revised faces pain scale : </label><%=render_value \'revised_faces_pain_scale\'%></span>\r\n<% end%>\r\n</div>\r\n	<div id=\"791-F6256529643\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>5. FLACC pain scale (สำหรับเด็กอายุตั้งแต่ 2 เดือน ถึง 7 ปี)</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n<div id=\"face\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:350px;\">\r\n\r\n\r\n<% if record[\'face\']!=\"\" %>\r\n<span class=\"\"><label>Face : </label><%=render_value \'face\'%></span>\r\n<% end%>\r\n</div>\r\n\r\n<div id=\"legs\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:350px;\">\r\n\r\n\r\n<% if record[\'legs\']!=\"\" %>\r\n<span class=\"\"><label>Legs : </label><%=render_value \'legs\'%></span>\r\n<% end%>\r\n</div>\r\n\r\n<div id=\"activity\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:350px;\">\r\n\r\n\r\n<% if record[\'activity\']!=\"\" %>\r\n<span class=\"\"><label>Activity : </label><%=render_value \'activity\'%></span>\r\n<% end%>\r\n\r\n</div>\r\n\r\n<div id=\"cry\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:350px;\">\r\n\r\n\r\n<% if record[\'cry\']!=\"\" %>\r\n<span class=\"\"><label>Cry : </label><%=render_value \'cry\'%></span>\r\n<% end%>\r\n</div>\r\n<div id=\"consolability\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;\">\r\n\r\n\r\n<% if record[\'consolability\']!=\"\" %>\r\n<span class=\"\"><label>Consolability : </label><%=ren