, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\nv {color:#009}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n <div id=\"logoleft\" style=\"margin-left:0px\">\r\n<table>\r\n<tr>\r\n<td><img src=\"/esm/cusys/pain_clinic/logo.jpg\" width=\"200\" /></td><td><b>Pain Research Unit, <br />Faculty of medicine chulalongkorn university</b>\r\n<br />&nbsp;<br />\r\n</td>\r\n</tr>\r\n</table> \r\n\r\n\r\n </div>\r\n\r\n<div id=\"logoright\"><br />\r\n<h4>Assessment Form Report</h4>\r\n\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br />\r\n<div id=\"page\">\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n\r\n\r\n\r\n\r\n\r\n      <%=patient.hn%> &nbsp;&nbsp;&