:30px;\">\r\n\r\n<% if record[\'chronic_cancer_pain\']!=\"\" %> <%=render_value \'chronic_cancer_pain\'%><br /> <% end%>\r\n<% if record[\'chronic_msk_pain\']!=\"\" %> <%=render_value \'chronic_msk_pain\'%><br /> <% end%>\r\n<% if record[\'cervical_spine_type\']!=\"\" %> <%=render_value \'cervical_spine_type\'%><br /> <% end%>\r\n<% if record[\'thoracic_spine_type\']!=\"\" %> <%=render_value \'thoracic_spine_type\'%><br /> <% end%>\r\n<% if record[\'lumbosacral_spine_type\']!=\"\" %> <%=render_value \'lumbosacral_spine_type\'%><br /> <% end%>\r\n<% if record[\'joints_and_others_type\']!=\"\" %> <%=render_value \'joints_and_others_type\'%><br /> <% end%>\r\n<% if record[\'chronic_neuropathic_pain_type\']!=\"\" %> <%=render_value \'chronic_neuropathic_pain_type\'%><br /> <% end%>\r\n<% if record[\'chronic_neuropathic_pain_type\']!=\"\" %> <%=render_value \'chronic_neuropathic_pain_type\'%><br /> <% end%>\r\n<% if record[\'chronic_headache_type\']!=\"\" %> <%=render_value \'chronic_headache_type\'%><br /> <% end%>\r\n<% if record[\'chronic_postsurgical_type\']!=\"\" %> <%=render_value \'chronic_postsurgical_type\'%><br /> <% end%>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n	<div id=\"848-F5574272985\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n<div id=\"previous_treatments\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Previous treatments : </label></span>\r\n<%=render_value \'previous_treatments\'%>\r\n	\r\n</div>\r\n\r\n\r\n\r\n<div id=\"ongoing_treatments\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Ongoing treatments : </label></span>\r\n<%=render_value \'ongoing_treatments\'%>\r\n</div>\r\n\r\n\r\n<div id=\"underlying__disease\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Underlying  disease : </label></span>\r\n<%=render_value \'underlying__disease\'%>\r\n	\r\n\r\n</div>\r\n\r\n<div id=\"antiplatelet_anticoagulant\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Antiplatelet/anticoagulant : </label></span>\r\n<%=render_value \'antiplatelet_anticoagulant\'%>\r\n	\r\n</div>\r\n\r\n<div id=\"antiplatelet_yes\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>detail : </label></span>\r\n<%=render_value \'antiplatelet_yes\'%>\r\n	\r\n</div>\r\n\r\n\r\n<div id=\"drug_allergy\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Drug allergy : </label></span>\r\n<%=render_value \'drug_allergy\'%>\r\n\r\n</div>\r\n	<div id=\"848-F1193731833\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Vital  sign</b>\r\n		\r\n	</div>\r\n\r\n	\r\n\r\n<table width=\"95%\" border=\"1\" cellpadding=\"1\" cellspacing=\"0\">\r\n<tr>\r\n<th height=\"25\">BP</th><th>PR</th><th>RR</th><th>BW</th><th>Hb/Hct</th><th>WBC</th><th>Plt</th><th>Cr</th><th>SGOT/SGPT</th><th>Albumin</th><th>INR</th>\r\n</tr>\r\n<tr>\r\n<td height=\"29\" align=\"center\"><%=render_value \'bp\'%></td><td align=\"center\"><%=render_value \'pr\'%></td><td align=\"center\"><%=render_value \'rr\'%></td><td align=\"center\"><%=render_value \'bw\'%></td><td align=\"center\"><%=render_value \'hbhct\'%></td><td align=\"center\"><%=render_value \'wbc\'%></td><td align=\"center\"><%=render_value \'plt\'%></td>\r\n<td align=\"center\"><%=render_value \'cr\'%></td><td align=\"center\"><%=render_value \'sgotsgpt\'%></td><td align=\"center\"><%=render_value \'albumin\'%></td><td align=\"center\"><%=render_value \'inr\'%></td>\r\n</tr>\r\n\r\n</table>\r\n\r\n\r\n<br />\r\n<div id=\"current__pain_medications\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:650px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Current  pain medications : </label></span>\r\n<%=render_value \'current__pain_medications\'%>\r\n	\r\n\r\n</div>\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"pain_location1\" class=\"  portlet \" style=\"border:0px solid blue;width:100%;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n  <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n\r\n\r\n			\r\n			\r\n			<div id=\"F1473960159\">\r\n			\r\n			  <div id=\"5a82e91e790f9bec94000025\" style=\"border:0px solid #ccc;margin-bottom:5px;\">\r\n	<div style=\"background:#eee\">&nbsp;Pain location\r\n	\r\n	</div>\r\n	<div style=\"padding-left:5px;\">\r\n		\r\n\r\n<!--   -->\r\n\r\n\r\n\r\n<%\r\n    tmp_rec = @record\r\n    tmp_doc = @document\r\n    \r\n    @document = get_document \'pain_location\'\r\n    \r\n    # ve many\r\n    vm = @record[:pain_location]\r\n    # ve_test list\r\n    vl = get_model[:pain_location].find(vm)\r\n    \r\n    idx = 0\r\n    vl.each do |i|\r\n        idx += 1\r\n        @record = i\r\n%>\r\n\r\n\r\n						\r\n						<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n							\r\n                        \r\n	                      <p>Location : <v><%= render_value \'location\' %></v><br />\r\n	                        Left or Right : <v><%= render_value \'locationlr\' %></v><br />\r\n	                        Pain characteristics : <v><%= render_value \'pain_characteristics\' %></v><br />\r\n	                        Types of pain : <v><%= render_value \'types_of_pain\' %></v><br />\r\n	                        Pain pattern : <v><%= render_value \'pain_pattern\' %></v><br />\r\n	                        At rest average (<v><%= render_value \'at_rest_average\' %></v>) most severe (<v><%= render_value \'at_rest_most_severe\' %></v>)  Movement average (<v><%= render_value \'movement_average\' %></v>)  most severe (<v><%= render_value \'movement_most_severe\' %></v>)<br />\r\n	                        Aggravating factors : <v><%= render_value \'aggravating_factors\' %></v> <v><%= render_value \'aggravating_factors_other\' %></v><br />\r\n                          Relieving  factors : <v><%= render_value \'relieving_factors\' %></v><v><%= render_value \'relieving_factors_other\' %></v></p>\r\n						</div><hr />\r\n<%\r\n    end\r\n    @record   = tmp_rec\r\n    @document = tmp_doc\r\n%>\r\n					</div>\r\n\r\n\r\n<!-- -->\r\n<div class=\"clear\"></div>\r\n\r\n		\r\n	</div>\r\n</div>\r\n				\r\n		</div>\r\n					\r\n		\r\n		\r\n		\r\n		\r\n	\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n	<div id=\"848-F9222817470\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Psychosocial  aspects</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n<div id=\"occupation\" class=\"  portlet \" style=\"border:0px solid blue;width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n\r\n\r\n<span class=\"\"><label>Occupation : </label></span>\r\n<%=render_value \'occupation\'%>\r\n</div>	\r\n\r\n\r\n\r\n<div id=\"care_giver\" class=\"  portlet \" style=\"border:0px solid blue;width:350px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n\r\n\r\n<span class=\"\"><label>Care giver : </label></span>\r\n<%=render_value \'care_giver\'%>\r\n	\r\n\r\n</div>\r\n\r\n\r\n<div id=\"ecog_score\" class=\"  portlet \" style=\"border:0px solid blue;margin: 0 0.5em 0.5em 0;float:left;width:800px\">\r\n\r\n\r\n<span class=\"\"><label>ECOG score : </label></span>\r\n<%=render_value \'ecog_score\'%>\r\n\r\n</div>\r\n	\r\n\r\n\r\n	<div id=\"848-F6864044932\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"co_symptoms\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px\">\r\n\r\n\r\n<span class=\"\"><label>Co-symptoms : </label></span>\r\n<%=render_value \'co_symptoms\'%>\r\n</div>\r\n\r\n\r\n<div id=\"insomnia\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\">\r\n<span class=\"\"><label>insomnia : </label></span>\r\n<%=render_value \'insomnia\'%>\r\n</div>\r\n\r\n<div id=\"fatigue\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\">\r\n<span class=\"\"><label>fatigue : </label></span>\r\n<%=render_value \'fatigue\'%>\r\n</div>\r\n\r\n<div id=\"loss_of_appetite\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\">\r\n<span class=\"\"><label>loss of appetite : </label></span>\r\n<v><%=render_value \'loss_of_appetite\'%></v>\r\n</div>\r\n\r\n<div id=\"anxiety\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\">\r\n<span class=\"\"><label>anxiety : </label></span>\r\n<%=render_value \'anxiety\'%>\r\n</div>\r\n\r\n<div id=\"depression\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\">\r\n<span class=\"\"><label>depression : </label></span>\r\n<%=render_value \'depression\'%>\r\n</div>\r\n\r\n<div id=\"lymphedema\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\">\r\n<span class=\"\"><label>lymphedema : </label></span>\r\n<%=render_value \'lymphedema\'%>\r\n</div>\r\n\r\n<div id=\"dyspnea\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:250px\">\r\n<span class=\"\"><label>dyspnea : </label></span>\r\n<%=render_value \'dyspnea\'%>\r\n</div>\r\n\r\n\r\n\r\n<div id=\"adverse_effects_from_medications\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px\">\r\n\r\n\r\n<span class=\"\"><label>Adverse effects from medications  : </label></span>\r\n<%=render_value \'adverse_effects_from_medications\'%>\r\n	\r\n</div>\r\n\r\n\r\n\r\n<div id=\"adverse_effects_yes\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px\">\r\n\r\n\r\n<span class=\"\"><label>please indicate  : </label></span>\r\n<%=render_value \'adverse_effects_yes\'%>\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n<div id=\"expectation_concern\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:350px\">\r\n\r\n\r\n<span class=\"\"><label>Expectation/Concern : </label></span>\r\n<%=render_value \'expectation_concern\'%>\r\n	\r\n\r\n</div>\r\n\r\n\r\n<div id=\"perception_knowledge\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:350px\">\r\n\r\n\r\n<span class=\"\"><label>Perception/Knowledge : </label></span>\r\n<%=render_value \'perception_knowledge\'%>\r\n\r\n</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"current_pain_problems\" class=\"  portlet \" style=\"border:0px solid blue;width:700px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n\r\n\r\n<span class=\"\"><label>Current pain problems : </label></span>\r\n<%=render_value \'current_pain_problems\'%>\r\n	\r\n</div>\r\n\r\n\r\n\r\n\r\n<div id=\"physical_exam\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:650px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Physical exam : </label></span>\r\n<%=render_value \'physical_exam\'%>\r\n	\r\n\r\n</div>\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"assessment_and_plans\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:650px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Assessment and plans : </label></span>\r\n<%=render_value \'assessment_and_plans\'%>\r\n	\r\n\r\n</div>\r\n\r\n\r\n	<div id=\"848-F7927308405\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Medication</b>\r\n		\r\n	</div>\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"m_opioids\" class=\"  portlet \" style=\"border:0px solid blue;width:100%;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n<!--   -->\r\n\r\n\r\n\r\n<%\r\n    tmp_rec = @record\r\n    tmp_doc = @document\r\n    \r\n    @document = get_document \'m_opioids\'\r\n    \r\n    # ve many\r\n    vm = @record[:m_opioids]\r\n    # ve_test list\r\n    vl = get_model[:m_opioids].find(vm)\r\n    \r\n    idx = 0\r\n    vl.each do |i|\r\n        idx += 1\r\n        @record = i\r\n%>\r\n\r\n\r\n						\r\n						<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >\r\n						\r\n                    \r\n                        	\r\n                        \r\n<div style=\"width:200px; float:left\">Opioids : </div><div style=\"width:300px;float:left;\"><v><%= render_value \'opioids\' %></v></div> <v><%= render_value \'units\' %></v>\r\n  Units  \r\n  <v><%= render_value \'note\' %></v>  \r\n  <br />\r\n						</div>\r\n<%\r\n    end\r\n    @record   = tmp_rec\r\n    @document = tmp_doc\r\n%>\r\n	  </div>\r\n\r\n\r\n<!-- -->\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n\r\n<div id=\"m_adjuvants\" class=\"  portlet \" style=\"border:0px solid blue;width:100%;margin: 0 0.5em 0.5em 0;float:left;\">\r\n<div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\" >	\r\n<!--   -->\r\n\r\n\r\n\r\n<%\r\n    tmp_rec = @record\r\n    tmp_doc = @document\r\n    \r\n    @document = get_document \'m_adjuvants\'\r\n    \r\n    # ve many\r\n    vm = @record[:m_adjuvants]\r\n    # ve_test list\r\n    vl = get_model[:m_adjuvants].find(vm)\r\n    \r\n    idx = 0\r\n