llspacing=\"0\">\r\n<tr>\r\n<th height=\"27\">BP</th><th>PR</th><th>SpO2</th><th>RR</th>\r\n</tr>\r\n<tr>\r\n<td height=\"27\" align=\"center\"><%=render_value \'post_bp\'%></td><td align=\"center\"><%=render_value \'post_pr\'%></td><td align=\"center\"><%=render_value \'post_spo2\'%></td><td align=\"center\"><%=render_value \'post_rr\'%></td>\r\n</tr>\r\n</table>\r\n<br />\r\n<div id=\"technique\" class=\"  portlet \" style=\"border:0px solid blue;width:800px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n\r\n\r\n<span class=\"\"><label>Technique : </label></span>\r\n<%=render_value \'technique\'%>\r\n\r\n</div>\r\n\r\n\r\n<div id=\"procedure_time\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:350px;\">\r\n\r\n\r\n\r\n	\r\n<label> Procedure&nbsp;time  </label>\r\n <%=render_value \'procedure_time\'%>\r\n</div>\r\n\r\n<div id=\"estimated_blood_loss\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:350px\">\r\n\r\n\r\n\r\n	\r\n<label> Estimated&nbsp;blood&nbsp;loss  </label>\r\n<%=render_value \'estimated_blood_loss\'%>\r\n</div>\r\n\r\n\r\n<div id=\"complications\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:800px;\">\r\n\r\n\r\n<span class=\"\"><label>Complications : </label></span>\r\n<%=render_value \'complications\'%>\r\n\r\n</div>\r\n\r\n	<div id=\"792-F0026145654\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Pre-procedure pain score</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"pre_pain_score_at_rest\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\nat rest : <%=render_value \'pre_pain_score_at_rest\'%>\r\n\r\n\r\n	\r\n</div>\r\n\r\n\r\n\r\n<div id=\"pre_pain_score_movement\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\nmovement : <%=render_value \'pre_pain_score_movement\'%>\r\n\r\n\r\n	\r\n</div>\r\n	\r\n\r\n\r\n	<div id=\"792-F8099954296\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Post-procedure pain score</b>\r\n		\r\n	</div>\r\n\r\n\r\n\r\n<div id=\"post_pain_score_at_rest\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\nat rest : <%=render_value \'post_pain_score_at_rest\'%>\r\n\r\n</div>\r\n\r\n<div id=\"post_pain_score_movement\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\nmovement : <%=render_value \'post_pain_score_movement\'%>\r\n</div>\r\n\r\n<div id=\"note\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:800px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Note : </label></span>\r\n<%=render_value \'note\'%>\r\n</div>\r\n\r\n<div id=\"endoscopist_1\" class=\"  portlet \" style=\"border:0px solid blue;width:350px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Physician sign : </label></span>\r\n<%=render_value \'endoscopist_1\'%>\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"clear\"></div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong></strong> \r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        \r\n        \r\n<%\r\n    if @current_role != \'developer\'\r\n%>\r\n        setTimeout(function() {\r\n            print();\r\n        }, 2000);\r\n<%\r\n    end\r\n%>\r\n    });\r\n</script>\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2018-02-13 15:07:46','2018-02-13 15:07:46','print',''),(3363,'print',1271,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:set_or_for_pain_intervention].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.w