loat:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n <div id=\"logoleft\" style=\"margin-left:0px\">\r\n<table>\r\n<tr>\r\n<td><img src=\"/esm/cusys/pain_clinic/logo.jpg\" width=\"200\" /></td><td><b>Pain Research Unit, <br />Faculty of medicine chulalongkorn university</b>\r\n<br />&nbsp;<br />\r\n</td>\r\n</tr>\r\n</table> \r\n\r\n\r\n </div>\r\n\r\n<div id=\"logoright\"><br />\r\n<h4>Set or for pain intervention Report</h4>\r\n\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br />\r\n<div id=\"page\">\r\n\r\n\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n\r\n\r\n\r\n\r\n\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> ชื่อ-สกุล : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'ไม่ระบุ\'\r\n    if patient.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>เพศ : </strong><%= gender %> &nbsp; <strong>อายุ :&nbsp;</strong>\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D-->\r\n      </td>\r\n          <td>\r\n         \r\n              <% if record[\'operative_date\']!=nil %>\r\n\r\n<label>Operative date : </label><%=render_value \'operative_date\'%>\r\n\r\n\r\n<% end%>\r\n          </td>\r\n          \r\n      </tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n \r\n	<hr style=\"margin-top: 5px; border-top: 2px solid #868686;\"/>\r\n    \r\n    <br />\r\n    <div id=\"sortable\" class=\" connectedSortable document  \" style=\"font-size:14px; border: 0px solid orange;padding:0px;width:100%;margin:0px;min-height:50px\" >\r\n	\r\n\r\n\r\n\r\n\r\n	<div id=\"793-F8172551752\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Diagnosis</b>\r\n		\r\n	</div>\r\n<div id=\"diagnosis\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:800px;min-height:30px;\"><b style=\"color:#F00\"><%=render_value \'diagnosis\'%></b>\r\n\r\n</div>\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"interventions_1\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:800px;\">\r\n\r\n\r\n<span class=\"\"><label>Interventions 1 : </label></span>\r\n<%=render_value \'interventions_1\'%> - <span class=\"\"><label>Level : </label></span> <%=render_value \'interventions_1_level\'%> ( <span class=\"\"><label>Side : </label></span> <%=render_value \'interventions_1_side\'%> )\r\n</div>\r\n<div id=\"793-F7214000970\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n  \r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"intervention_2\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:800px;\">\r\n\r\n\r\n<span class=\"\"><label>Intervention 2 : </label></span>\r\n<%=render_value \'intervention_2\'%> - <span class=\"\"><label>Level : </label>\r\n</span> <%=render_value \'intervention_2_level\'%> ( <span class=\"\">\r\n<label>Side : </label></span> <%=render_value \'intervention_2_side\'%> )\r\n\r\n</div>\r\n<div id=\"793-F8455145940\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n  \r\n</div>\r\n\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"date_for_intervention\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Date for intervention : </label></span>\r\n\r\n	<br /><%=render_value \'date_for_intervention\'%>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div id=\"time_for_intervention\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Time : </label></span><br />\r\n<%=render_value \'time_for_intervention\'%>\r\n\r\n</div>\r\n\r\n\r\n<div id=\"estimated_injection_time\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:300px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Estimated injection time  : </label></span>\r\n<br /><%=render_value \'estimated_injection_time\'%> (minutes)\r\n\r\n</div>\r\n\r\n	<div id=\"793-F8172551752\" class=\"  field\" style=\"clear:both;font-size:1.2em;border-bottom:1px solid #ccc;margin-bottom:10px;\">\r\n		<b>Equipment</b>\r\n		\r\n	</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"machine\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:200px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Machine : </label></span>\r\n<%=render_value \'machine\'%>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div id=\"contrast\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:600px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Contrast (ราคาประมาณ 350 บาท, ไม่สามารถเบิกได้ทุกสิทธิ์การรักษา) : </label></span>\r\n<%=render_value \'contrast\'%>\r\n	\r\n</div>\r\n\r\n\r\n	<div id=\"793-F8053554883\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n	\r\n\r\n\r\n\r\n\r\n<div id=\"needle\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Needle : </label></span><br />\r\n<%=render_value \'needle\'%>\r\n	\r\n</div>\r\n\r\n\r\n<div id=\"medication_injectate\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:400px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Medication injectate : </label></span><br />\r\n<%=render_value \'medication_injectate\'%>\r\n	\r\n</div>\r\n<div id=\"underlying_and_concern\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:800px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Underlying and concern : </label></span><br />\r\n<%=render_value \'underlying_and_concern\'%>\r\n	\r\n\r\n</div>\r\n<div id=\"antiplatelet_anticoagulant\" class=\"  portlet \" style=\"border:0px solid blue;width:500px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Antiplatelet  / anticoagulant : </label></span><br />\r\n<%=render_value \'antiplatelet_anticoagulant\'%> <%=render_value \'antiplatelet__yes\'%>\r\n\r\n</div>\r\n\r\n\r\n\r\n</div>\r\n\r\n<div id=\"stop_for\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Stop for : </label></span><br />\r\n<%=render_value \'stop_for\'%>\r\n\r\n</div>\r\n<div id=\"since_date\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>since date : </label></span><br />\r\n<%=render_value \'since_date\'%>\r\n	\r\n</div>\r\n\r\n	<div id=\"793-F2622265654\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"allergy\" class=\"  portlet \" style=\"border:0px solid blue;width:350px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>Allergy : </label></span><br />\r\n<b style=\"color:#F00\"><%=render_value \'allergy\'%></b>\r\n\r\n</div>\r\n\r\n\r\n<div id=\"npo\" class=\"  portlet \" style=\"border:0px solid blue;width:350px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>NPO : </label></span><br />\r\n<%=render_value \'npo\'%>\r\n</div>\r\n\r\n\r\n	<div id=\"793-F3919024007\" class=\"  field\" style=\"clear:both;\">\r\n		\r\n		except concurrent medications **Suggest to hold DM med**\r\n	</div>\r\n\r\n\r\n\r\n	<div id=\"793-F5440684736\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n<div id=\"pain_medications_continuation\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:500px;\">\r\n\r\n\r\n<span class=\"\"><label>Pain medications continuation : </label></span> \r\n<%=render_value \'pain_medications_continuation\'%>\r\n</div>\r\n\r\n\r\n\r\n<div id=\"consent_form\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n\r\n\r\nConsent form : \r\n<b style=\"color:#F00\"><%=render_value \'consent_form\'%></b>\r\n</div>\r\n	\r\n\r\n\r\n	<div id=\"793-F6975287204\" class=\"   field\" style=\"clear:both;text-align:right\">\r\n		\r\n	</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"reimbursement\" class=\"  portlet \" style=\"border:0px solid blue;width:500px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>สิทธิ์การรักษา : </label></span><br />\r\n<b style=\"color:#F00\"><%=render_value \'reimbursement\'%></b>\r\n</div>\r\n\r\n\r\n	<div id=\"793-F6926909172\" class=\"  field\" style=\"clear:both;\">\r\n		\r\n		[หากผู้ป่วยใช้สิทธิ 302, ปกส หรือพระภิกษุ ให้แจ้งผู้ป่วยและญาติเพิ่มเติมว่า จำเป็นต้องมาขึ้นสิทธิการรักษาที่ ตึก ภปร ชั้นล่าง ก่อนเสมอในตอนเช้าก่อนการชำระเงิน โดยผู้ป่วยสามารถมาที่ห้องผ่าตัดได้เลยเพื่อรับการรักษา และญาติเป็นผู้ขึ้นสิทธิและชำระเงิน)] \r\n\r\n	</div>\r\n	\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"other_contact\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:700px;min-height:30px;\">\r\n\r\n\r\n<span class=\"\">บอร์โทรศัพท์ผู้ป่วยหรือญาติที่ติดต่อได้ (ระบุ) : </span>\r\n<%=render_value \'other_contact\'%>\r\n\r\n</div>\r\n	<div id=\"793-F9122207326\" class=\"  field\" style=\"clear:both;\">\r\n		\r\n		**ให้เอกสารและใบนัดกับผู้ป่วย พร้อมแจ้งว่า วันที่ได้รับการฉีดยาต้องมีญาติมาด้วยเสมอ เวลา 8.30 น. และนำยามาด้วย**<br />\r\n**กรณีพิเศษ หากผู้ป่วยไม่มีญาติมาด้วย (เฉพาะเคส facet block เท่านั้น) ต้องทำการขึ้นสิทธิเอง และชำระเงินให้เรียบร้อยก่อนการฉีดยา และอาจต้องอยู่ห้องพักฟื้นนานกว่าเคสปกติ รวมทั้งให้แพทย์ประเมินอาการก่อนให้กลับบ้านเสมอ**\r\n\r\n	</div>\r\n\r\n\r\n	\r\n\r\n\r\n<br />&nbsp;\r\n<br />\r\n<div id=\"endoscopist_1\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n\r\n\r\n<span class=\"\"><label>แพทย์ผู้สั่งการรักษา : </label></span><br />\r\n<%=render_value \'endoscopist_1\'%>\r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n</div>\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong></strong> \r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n<script>\r\n    $(document).ready(function() {\r\n        \r\n        \r\n<%\r\n    if @current_role != \'developer\'\r\n%>\r\n        setTimeout(function() {\r\n            print();\r\n        }, 2000);\r\n<%\r\n    end\r\n%>\r\n    });\r\n</script>\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2018-02-13 15:38:55','2018-02-13 15:38:55','print',''),(3364,'document_name',1340,1,'\'pain_location\'',NULL,NULL,NULL,'2018-02-19 05:00:56','2018-02-19 05:00:56',NULL,NULL),(3367,'document_name',1342,1,'\'hpb_collecting_form\'',NULL,NULL,NULL,'2018-02-22 06:46:59','2018-02-22 06:46:59',NULL,NULL),(3368,'total_report',522,2,'<br/>\r\n<div><span style=\"font-size:2em\" >ESD reports</span>\r\n<span style=\"float:right\"><%=link_to \"Export\", \"./total_esd_report_excel\",:class=>\"btn btn-success\"%></span>\r\n</div>\r\n<br/>\r\n<%= render :inline=>this.init%>\r\n<%\r\n  month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n  \r\n  \r\n  \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-25\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-25\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    \r\n\r\n    m = @models[:colonoscopy_scope].collection.find({},{:fields=>{\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1,\'treatment_by\'=>1 }}).to_a\r\n   \r\n   \r\n   %>\r\n   <%=form_for \'report\' do |f| %>\r\nFrom : <%= f.date_select :from_date, :default=>from_date ,:discard_day=>true , :order=>[:month,:year],:start_year=>2008%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date ,:discard_day=>true , :order=>[:month,:year],:start_year=>2008%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n   <%\r\n#   colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 }}).to_a\r\n# diagnosis_note scope_note project procedure\r\n\r\n   def bmap objs, id=\'_id\'\r\n        map = {}\r\n        \r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n\r\n    \r\n    list = []\r\n    res = []\r\n    \r\n    \r\n    for i in m\r\n    \r\n        if i[\'endoscopy_dx\']==\'ESD\'\r\n            list << i \r\n        elsif i[\'abnormal_note\'] and i[\'abnormal_note\'].downcase.index(\'esd\')\r\n            list << i\r\n        elsif i[\'treatment_by\'] and i[\'treatment_by\'].downcase.index(\'esd\')\r\n            list << i \r\n        end\r\n    end\r\n    \r\n    \r\n    if request.post?\r\n    \r\n    # m = @models[:colonoscopy_scope].collection.find({},{:fields=>{\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1 }}).to_a\r\n   \r\n    list = @models[:colonoscopy_scope].collection.find({:_id=>{\'$in\'=>list.collect{|i|i[\'_id\']}}}).to_a\r\n    \r\n    # { $where: \"this.name.length > 1\" }\r\n    \r\n    \r\n    scope_list = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\'];\r\n    map = {\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1, \'procedure\'=>1,\'scope_note\'=>1, \'diagnosis_note\'=>1,\'project\'=>1}\r\n    qmap = {:diagnosis_group=>{\'$ne\'=>\'Normal\'}}\r\n    where = []\r\n    for i in scope_list\r\n        map[i]=1\r\n    end\r\n    \r\n    \r\n    qmap[\'$where\']= \'this.rectum_scope.length > 1 || this.sigmoid_scope.length > 1 || this.transvers_colon_scope.length>1 || this.ascending_colon_scope.length>1 || this.cecum_scope.length>1 || this.terminal_ileum_scope.length>1\'\r\n    \r\n    ml = @models[:colonoscopy].collection.find({},{:fields=>map}).to_a\r\n    \r\n    lim = {}\r\n    for i in list\r\n    \r\n        lim[i[\'_id\']] = i\r\n    \r\n    end\r\n    \r\n    \r\n    plist = {}\r\n    \r\n    \r\n    for i in ml\r\n    \r\n        f = false\r\n        \r\n        for j in scope_list\r\n        \r\n            \r\n            if i[j]!=\"\"\r\n                \r\n                \r\n            for k in i[j]\r\n            \r\n            \r\n            if lim[k]\r\n       \r\n                plist[i[\'_id\']] = {:c=>i,:l=>{}} unless plist[i[\'_id\']]\r\n                \r\n                plist[i[\'_id\']][:l][j] = [] unless plist[i[\'_id\']][:l][j]\r\n                plist[i[\'_id\']][:l][j] << lim[k]\r\n                \r\n            end\r\n            \r\n            end\r\n            end \r\n        end\r\n        \r\n            # map = {\'_id\'=>1,\'endoscopy_dx\'=>1,\'abnormal_note\'=>1, \'procedure\'=>1,\'scope_note\'=>1, \'diagnosis_note\'=>1}\r\n\r\n        \r\n        if (i[\'project\'] and i[\'project\'].downcase.index(\'esd\')) or (i[\'procedure\'] and i[\'procedure\'].downcase.index(\'esd\')) or (i[\'scope_note\'] and i[\'scope_note\'].downcase.index(\'esd\')) or (i[\'diagnosis_note\'] and i[\'diagnosis_note\'].downcase.index(\'esd\')) \r\n            \r\n            plist[i[\'_id\']] = {:c=>i,:l=>{}} unless plist[i[\'_id\']]\r\n            \r\n        end\r\n        \r\n        \r\n        \r\n    end\r\n#   {:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}}\r\n     # all pm colono of those appointments\r\n     \r\n     \r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    \r\n    all_pm_colo = @m_patient_module.collection.find({:module_id=>{\'$in\'=>plist.keys},:module_name=>\"\\\\#{pname}colonoscopy\"}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'module_id\'\r\n    \r\n          # all pm colono of those appointments\r\n    all_patient = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'patient_id\'] }}}).to_a\r\n    m_all_patient = bmap all_patient, \'_id\'\r\n    \r\n    cols = %w{abnormal_type  endoscopy_dx morphology_type size treatment treatment_by clip patho_number pit_pattern pit_pattern pitt_by kudo_type vascular_pattern \r\n    vascular_by sano_type nice_classification niceby abnormal_note tattoo jnet_class jnetby chromo complication } \r\n    count = 0 \r\n%>\r\n<table border=\"1\" style=\"border-collapse: collapse;font-size:0.6em\" ><th>No.</th>\r\n<th style=\"width:100px\">Date</th><th>HN</th><th style=\"width:100px\">First name</th><th style=\"width:100px\">Last name</th><th>Procedure</th><th>Note</th><th>Project</th>\r\n<th>Location</th>\r\n<% for x in cols %>\r\n<th><%= x.humanize %></th>\r\n<% end %>\r\n<% 5.times.each do |i| %>\r\n<th  style=\"width:100px\"><%=i+1%>.</th>\r\n<% end %>\r\n<%\r\n   for i in plist.keys\r\n    colo = plist[i]\r\n    c = colo[:c]\r\n    l = colo[:l]\r\n    p_m = m_all_pm_colo[i][0]\r\n    p = m_all_patient[p_m[\'patient_id\']][0] \r\n    \r\nif l.size == 0 \r\n%>\r\n<tr><td><%=count+1%><% count+=1 %>.</td><td style=\"width:100px\"><%=p_m[\'date\'].strftime(\"%d-%m-%Y\")%></td><td><%=p[\'hn\']%></td>\r\n<td><%=p[\'first_name\']%></td><td><%=p[\'last_name\']%></td>\r\n<td><%=c[\'procedure\']%></td>    \r\n<td><%=c[\'scope_note\']%></td>      \r\n<td><%=c[\'project\']%></td>      \r\n    \r\n</tr>\r\n<%\r\nelse\r\n    l.each_pair do |location,list|\r\n        \r\n        for li in list\r\n\r\n%>\r\n<tr><td><%=count+1%><% count+=1 %>.</td><td  style=\"width:100px\"><%=p_m[\'date\'].strftime(\"%d-%m-%Y\")%></td><td><%=p[\'hn\']%></td>\r\n<td><%=p[\'first_name\']%></td><td><%=p[\'last_name\']%></td>\r\n<td><%=c[\'procedure\']%></td>    \r\n<td><%=c[\'scope_note\']%></td>      \r\n<td><%=c[\'project\']%></td>  \r\n<td><%=location.split(\"_\")[0..-2].join(\" \")%></td>\r\n<% for x in cols \r\n  style = \'\'\r\n  style = \'style=\"width:150px\"\' if x==\'endoscopy_dx\'\r\n%>\r\n<td <%=style.html_safe %>><%= li[x] %></td>\r\n<% end %>\r\n<% \r\n  \r\n\r\n    atts = @models[:attachment].find(li[\'image\']).to_a\r\n    \r\n    %>\r\n    <%=%>\r\n<%\r\nl = atts[0..4].compact\r\nfor ai in l\r\n%>\r\n<td style=\"width:100px\">\r\n<a href=\"<%=ai.path%>\" class=\"highslide \" rel=\"highslide\" onclick=\"return hs.expand(this)\"><center>\r\n<img  src=\"<%=ai.path%>&thumb=1\" width=\"100\" />\r\n</a>\r\n</td>\r\n<% end %>\r\n\r\n<% (5-l.size).times do |img| %>\r\n<td >&nbsp;</td>\r\n<% end %>\r\n</tr>\r\n<% end %>\r\n <% \r\n        end\r\n    end\r\n end %>    \r\n</table>\r\n<%\r\n end %> \r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-02-25 11:32:56','2018-02-25 11:32:56','total_report',''),(3369,'index',1343,2,'<h1>Report</h1>\r\n<%=link_to \"Operative Schedule\", \"operative_schedule\",:class=>\'btn btn-info\'%>',NULL,NULL,NULL,'2018-02-26 01:02:16','2018-02-26 01:02:16','index',''),(3370,'operative_schedule',1343,2,'<%\r\n\r\n month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n  \r\n  \r\n  \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-\"+params[:report][\'from_date(3i)\'] if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_day\r\n    \r\n    to_date = from_date.end_of_day\r\n    \r\n  \r\n    \r\n%>\r\n<%=form_for \'report\' do |f| %>\r\n\r\nDate : <%= f.date_select :from_date, :default=>from_date , :order=>[:day,:month,:year],:start_year=>2008%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n<% if request.post? \r\n\r\n    models = get_model\r\n    \r\n    records = models[:set_or_for_pain_intervention].where(:date_for_intervention=>{\"$gte\"=>from_date,\"$lte\"=>to_date}).all\r\n    \r\n    \r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    \r\n    @m_patient = model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    \r\n    mrecords = @m_patient_module.where(:module_id=>{\"$in\"=>records.collect{|i| i.id} }).all\r\n    \r\n    hrecords = mrecords.collect{|i| [i.module_id,i.patient_id] }.to_h\r\n    \r\n    patients = @m_patient.where(:id=>{\"$in\"=>hrecords.values}).all\r\n    \r\n    hpatients = patients.collect{|i| [i.id, i] }.to_h\r\n    \r\n    \r\n    \r\n    \r\n# time_for_intervention\r\n%>\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n<div id=\"printableArea\">\r\n<style>\r\n    td{\r\n        padding:20px;\r\n    }\r\n</style>\r\n<h3>ตารางรายชื่อผู้ป่วย set case pain intervention ประจำวันที่ \r\n<%= from_date.strftime(\"%d/%m/%Y\") %></h3>\r\n<hr/>\r\n<table class=\"table\">\r\n    <thead>\r\n        <th>No.</th><th>HN</th><th>Name-Surname</th><th>Date/Time</th> <th>Diagnosis</th><th>Interventions</th><th>Equiptment</th><th>แพทย์</th>\r\n    </thead>\r\n    <tbody>\r\n        <% records.each_with_index do|i,index| \r\n           \r\n           patient = hpatients[hrecords[i.id]]\r\n           @record = i\r\n           @document =  get_document \'set_or_for_pain_intervention\'\r\n\r\n\r\n        %>\r\n        <tr> \r\n            <td>\r\n                <%=index+1%>.\r\n            </td>\r\n           <td>\r\n                <%=patient.hn%>\r\n            </td>\r\n            <td>\r\n                <%=patient.first_name%>  <%=patient.last_name%>\r\n            </td>\r\n            <td>\r\n                <%=i.date_for_intervention%> <%=i.time_for_intervention.strftime(\"%H:%M\")%>\r\n            </td>\r\n            <td>\r\n             <%=i.diagnosis%>\r\n            </td>\r\n            <td>\r\n             <%=i.intervention_1%>    <%=i.intervention_2%>\r\n            </td>\r\n            <td>\r\n                <%=i.machine.split(\"|\").join(\", \")%>\r\n            </td>\r\n            <td>\r\n                <%= render_value \'endoscopist_1\' %>\r\n            </td>\r\n        \r\n        </tr>\r\n        <% end %>\r\n    </tbody>\r\n</table>\r\n</div>\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" />\r\n\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2018-02-26 01:02:49','2018-02-26 01:02:49','operative_schedule',''),(3371,'document_name',1344,1,'\'complication\'',NULL,NULL,NULL,'2018-02-27 07:01:32','2018-02-27 07:01:32',NULL,NULL),(3373,'document_name',1345,1,'\'clinical_symptoms_add\'',NULL,NULL,NULL,'2018-02-27 12:43:21','2018-02-27 12:43:21',NULL,NULL),(3374,'document_name',1346,1,'\'laboratory_evaluations_add\'',NULL,NULL,NULL,'2018-02-27 13:03:55','2018-02-27 13:03:55',NULL,NULL),(3375,'document_name',1347,1,'\'liver_evaluations_add\'',NULL,NULL,NULL,'2018-02-27 13:20:49','2018-02-27 13:20:49',NULL,NULL),(3376,'document_name',1348,1,'\'radiological_evaluations_add\'',NULL,NULL,NULL,'2018-02-27 13:28:11','2018-02-27 13:28:11',NULL,NULL),(3377,'document_name',1349,1,'\'pathological_evaluations_add\'',NULL,NULL,NULL,'2018-02-27 13:35:46','2018-02-27 13:35:46',NULL,NULL),(3380,'document_name',1351,1,'\'post_operative_add\'',NULL,NULL,NULL,'2018-03-01 07:30:18','2018-03-01 07:30:18',NULL,NULL),(3381,'document_name',1352,1,'\'treatments_add\'',NULL,NULL,NULL,'2018-03-01 09:04:55','2018-03-01 09:04:55',NULL,NULL),(3382,'signup',1353,2,'<div class=\"heading\">\r\n<h1>Sign-Up</h1></div>\r\n\r\n<style>\r\n    .bbox{\r\n        float:left;\r\n        padding-right:10px;\r\n    }\r\n    \r\n</style>\r\n<h3>1. Customer Registration</h3>\r\n\r\n\r\n<%= form_for :customer,:url=>\'signup_action\' do |f| %>\r\n\r\n<div class=\"field bbox\">\r\n    <label>Customer Name</label>\r\n    <%=f.text_field :name %> \r\n\r\n</div>\r\n\r\n\r\n<div class=\"field bbox\">\r\n    <label>Address</label>\r\n    <%=f.text_field :address , :style => \"width:500px;\"%> \r\n</div>\r\n<div class=\"clear\"></div>\r\n<div class=\"field bbox\">\r\n    <label>Contact Name</label>\r\n    <%=f.text_field :contact_name %> \r\n\r\n</div>\r\n<div class=\"field bbox\">\r\n    <label>Contact Email</label>\r\n    <%=f.text_field :email %> \r\n\r\n</div>\r\n<div class=\"field bbox\">\r\n    <label>Contact Telephone</label>\r\n    <%=f.text_field :tel %> \r\n\r\n</div>\r\n<div class=\"field bbox\">\r\n    <label>Fax</label>\r\n    <%=f.text_field :fax %> \r\n\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<hr />\r\n\r\n<h3>2. Customer\'s Admin User & Password</h3>\r\n<i> * CRO representative</i>\r\n\r\n<div class=\"field\">\r\n    <label>Username</label>\r\n    <%=f.text_field :admin_user %>\r\n</div>\r\n\r\n\r\n\r\n<div class=\"field\">\r\n    <label>Password</label>\r\n    <%=f.password_field :password %>\r\n</div>\r\n\r\n<div class=\"field\">\r\n    <label>Password Confirmation</label>\r\n    <%=f.password_field :password_confirmation %>\r\n</div>\r\n<div class=\"field\">\r\n    <label>Email</label>\r\n    <%=f.text_field :admin_email %>\r\n</div>\r\n\r\n<%= f.submit \'Submit\', :class=>\'btn btn-info\' %> | <%=link_to \'Cancel\', \"../Home/index\" %>\r\n\r\n<% end %>\r\n\r\n<script>\r\n\r\n        $(\'#customer_name\').change(function(){\r\n           // alert(this.value)\r\n        });\r\n    \r\n        function readURL(input) {\r\n        if (input.files && input.files[0]) {\r\n            var reader = new FileReader();\r\n            \r\n            reader.onload = function (e) {\r\n                $(\'#blah\').attr(\'src\', e.target.result);\r\n            }\r\n            \r\n            reader.readAsDataURL(input.files[0]);\r\n        }\r\n    }\r\n    \r\n    $(\"#logo\").change(function(){\r\n        readURL(this);\r\n    });\r\n</script>',NULL,NULL,NULL,'2018-03-03 12:56:46','2018-03-03 12:56:46','signup','*'),(3383,'signup_action',1353,2,'<%=render :inline=>this.init%>\r\n<% if request.post? \r\n\r\n  cparams = params[:customer]\r\n\r\n  if params[:customer] and @models[:customer].where(:name=>cparams[:name]).first == nil and cparams[:password]==cparams[:password_confirmation]\r\n      \r\n      \r\n      \r\n    login = cparams[:admin_user]\r\n    password = cparams[:password]\r\n    \r\n    salt = User.random_string(10) \r\n    hashed_password = User.encrypt(password, salt)\r\n    \r\n    role_model = @models[:role]\r\n    role = role_model.where(:name=>\'customer\').first\r\n        \r\n    role = role_model.create :name=>\'customer\' unless role\r\n    \r\n    unless @models[:user].where(:login=>params[:customer][:admin_user]).first\r\n    \r\n    admin_user = @models[:user].create :login=>params[:customer][:admin_user],\'salt\'=>salt,\'hashed_password\'=>hashed_password,:role=>role.id, :email=>params[:customer][:admin_email]\r\n      \r\n    cu