ield :login %>\r\n</div>\r\n\r\n\r\n\r\n<div class=\"field\">\r\n    <label>Password</label>\r\n    <%=f.password_field :password %>\r\n</div>\r\n\r\n<div class=\"field\">\r\n    <label>Password Confirmation</label>\r\n    <%=f.password_field :password_confirmation %>\r\n</div>\r\n<div class=\"field\">\r\n    <label>Email</label>\r\n    <%=f.text_field :email %>\r\n</div>\r\n\r\n<%= f.submit \'Submit\', :class=>\'btn btn-info\' %>\r\n\r\n<% end %>\r\n\r\n<script>\r\n\r\n        $(\'#customer_name\').change(function(){\r\n           // alert(this.value)\r\n        });\r\n    \r\n        function readURL(input) {\r\n        if (input.files && input.files[0]) {\r\n            var reader = new FileReader();\r\n            \r\n            reader.onload = function (e) {\r\n                $(\'#blah\').attr(\'src\', e.target.result);\r\n            }\r\n            \r\n            reader.readAsDataURL(input.files[0]);\r\n        }\r\n    }\r\n    \r\n    $(\"#logo\").change(function(){\r\n        readURL(this);\r\n    });\r\n</script>\r\n\r\n<% end %>',NULL,NULL,NULL,'2018-03-03 16:39:28','2018-03-03 16:39:28','user_signup',''),(3397,'document_name',1357,1,'\'user_customer\'',NULL,NULL,NULL,'2018-03-03 16:51:54','2018-03-03 16:51:54',NULL,NULL),(3398,'add',1337,3,'<%\r\n    \r\n    user = get_model(\'user_project\').create :user_id=>params[:user_id], :project_id=>params[:project_id]\r\n    \r\n%><meta http-equiv=\"refresh\" content=\"0; url=../Project/members?id=<%=params[:project_id]%>\" />',NULL,NULL,NULL,'2018-03-03 17:22:08','2018-03-03 17:22:08','add',''),(3399,'destroy',1337,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  project_id = @record.project_id\r\n  @record.destroy \r\n  \r\n%><meta http-equiv=\"refresh\" content=\"0; url=../Project/members?id=<%=project_id%>\" />',NULL,NULL,NULL,'2018-03-03 17:24:56','2018-03-03 17:24:56','destroy',''),(3400,'config',1295,1,'config = {}\r\n\r\nconfig[:version] = \'1.1\'\r\n\r\nconfi