n    \r\n    current_user_project = models[:user_project].where(:user_id=>current_user.id, :project_id=>project.id).first\r\n    \r\n    \r\n    is_admin = false\r\n    \r\n    if current_user_project\r\n        is_admin = true if current_user_project.role==\'admin\'\r\n    end\r\n\r\n\r\n    if project \r\n        \r\n        member_projects = models[:member_project].where(:project_id=>project.id).all\r\n        \r\n        \r\n%>\r\n\r\n<div class=\"heading\">\r\n    <h1>CRC PI</h1>\r\n</div>\r\n<%  members  = member_projects.collect{|i| i if i.role==\'pi\'}.compact %>\r\n<div class=\"row-fluid\">\r\n<%  for i in members %>\r\n\r\n<div class=\"span4\">\r\n    <div>\r\n       <center>\r\n    <%\r\n        member = models[:member].find i.member_id\r\n        att = nil\r\n        if member\r\n        if member.picture\r\n            att = models[:attachment].find member.picture\r\n        end\r\n        path_img = \'/esm/cusys/cucrc/person.png\'\r\n        path_img = att.path if att\r\n    %>\r\n    <%=image_tag path_img ,:height=>150 %>\r\n    <br/>\r\n \r\n    <%=member.name if member %>\r\n    <% else \r\n    \r\n    i.destroy\r\n    %>\r\n    Member not found\r\n    <% end %>    \r\n    </center>\r\n    \r\n    </div>\r\n</div>\r\n<% end %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<div class=\"heading\">\r\n    <h1>CRC StartUp</h1>\r\n</div>\r\n<%  members  = member_projects.collect{|i| i if i.role==\'startup\'}.compact %>\r\n<div class=\"row-fluid\">\r\n<%  for i in members %>\r\n\r\n<div class=\"span4\">\r\n    <div>\r\n       <center>\r\n    <%\r\n        member = models[:member].find i.member_id\r\n        att = nil\r\n        if member\r\n        if member.picture\r\n            att = models[:attachment].find member.picture\r\n        end\r\n       path_img = \'/esm/cusys/cucrc/person.png\'\r\n        path_img = att.path if att\r\n    %>\r\n    <%=image_tag path_img ,:height=>150 %>\r\n    <br/>\r\n \r\n    <%=member.name if member%>\r\n          <% else \r\n          i.destroy\r\n          %>\r\n    Member not found \r\n    <% end %>   \r\n        \r\n    </center>\r\n    </div>\r\n</div>\r\n<% end %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<div class=\"heading\">\r\n    <h1>CRC SN/SC</h1>\r\n</div>\r\n<%  members  = member_projects.collect{|i| i if i.role==\'sn\' or i.role==\'sc\'}.compact %>\r\n<div class=\"row-fluid\">\r\n<%  for i in members %>\r\n\r\n<div class=\"span4\">\r\n    <div>\r\n       <center>\r\n    <%\r\n        member = models[:member].find i.member_id\r\n        att = nil\r\n        if member\r\n        if member.picture\r\n            att = models[:attachment].find member.picture\r\n        end\r\n      path_img = \'/esm/cusys/cucrc/person.png\'\r\n        path_img = att.path if att\r\n    %>\r\n    <%=image_tag path_img,:height=>150  %>\r\n    <br/>\r\n \r\n    <%=member.name if member%>\r\n    <% else \r\n        i.destroy\r\n    %>\r\n    Member not found\r\n    <% end %>   \r\n        \r\n    </center>\r\n\r\n    </div>\r\n</div>\r\n<% end %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<% if @current_role ==\'admin\' or @current_role ==\'startup\' or @current_role ==\'developer\'  %>\r\n<div class=\"heading\">\r\n    <h1>CRC Project Members</h1>\r\n</div>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr><th>Name</th><th>Role</th><th>Email</th><th></th></tr>\r\n    </thead>\r\n    <tbody>\r\n    <% for i in member_projects \r\n       member = models[:member].find i.member_id\r\n        user = models[:user].find i.user_id\r\n        if member\r\n    %>\r\n            <tr>\r\n            <td>\r\n                <%=member.name%>\r\n            </td>\r\n            <td>\r\n                <%=i.role%>\r\n            </td>\r\n            <td>\r\n                <%=member.email%>\r\n            </td>\r\n        \r\n         \r\n          \r\n                <td><%=link_to \'Remove\', \"../MemberProject/destroy?id=\\\\#{i.id}\", :class=>\'btn btn-mini btn-danger\', :data=>{:confirm=>\'Are you sure?\'} %></td>\r\n                \r\n            </tr>\r\n              <% \r\n\r\n    end %>\r\n    <% \r\n\r\n    end %>\r\n    </tbody>\r\n</table>\r\n\r\n\r\n<%\r\n\r\n\r\n    user_customer =   models[:user_customer].where(:user_id=>current_user.id).first       \r\n\r\n\r\n    \r\n    members = models[:member].all     \r\n    \r\n%>\r\n\r\n<div class=\"heading\">\r\n    <h1>CRC All Members</h1>\r\n</div>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr><th>Name</th><th>Position</th><th>Email</th><th></th></tr>\r\n    </thead>\r\n    <tbody>\r\n    <% for i in members \r\n        # user = models[:user].find i.user_id\r\n    %>\r\n            <tr><td>\r\n                <%=i.name%>\r\n            </td>\r\n            <td>\r\n                <%=i.position%>\r\n            </td>\r\n                <td>\r\n                <%=i.email%>\r\n            </td>\r\n            \r\n            \r\n                <td><%=link_to \'Add to project\', \"../MemberProject/add?member_id=\\\\#{i.id}&project_id=\\\\#{project.id}\", :class=>\'btn btn-mini\',:data=>{:confirm=>\'Are you sure?\'} %> \r\n                <%#link_to \'Delete\', \"../User/destroy?id=\\\\#{user.id}\", :class=>\'btn btn-mini btn-danger\', :data=>{:confirm=>\'Are you sure?\'} %></td> \r\n                \r\n            </tr>\r\n    <% end %>\r\n    </tbody>\r\n</table>\r\n<% end %><% end %>\r\n<%#link_to \"Register CRO User\", \"../Registration/user_signup?customer_id=\\\\#{customer.id}&project_id=\\\\#{project.id}\", :class=>\'btn\'  %>\r\n',NULL,NULL,NULL,'2018-03-04 16:18:59','2018-03-04 16:18:59','crc_members',''),(3407,'document_name',1359,1,'\'member_project\'',NULL,NULL,NULL,'2018-03-04 16:21:09','2018-03-04 16:21:09',NULL,NULL),(3408,'add',1359,3,'<%\r\n    member = get_model(\'member\').find params[:member_id]\r\n    \r\n    \r\n    \r\n    user = get_model(\'member_project\').create :member_id=>params[:member_id], :project_id=>params[:project_id], :role=>member.position\r\n    \r\n%><meta http-equiv=\"refresh\" content=\"0; url=../Project/show?id=<%=params[:project_id]%>\" />',NULL,NULL,NULL,'2018-03-04 16:27:07','2018-03-04 16:27:07','add',''),(3409,'destroy',1359,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  project_id = @record.project_id\r\n  @record.destroy \r\n  \r\n%><meta http-equiv=\"refresh\" content=\"0; url=../Project/show?id=<%=project_id%>\" />',NULL,NULL,NULL,'2018-03-04 16:32:28','2018-03-04 16:32:28','destroy',''),(3410,'process_project',1278,3,'<% \r\n\r\n    www = @context.get_projects_by_abstract(\'www.www\')[0]\r\n    user_model = www.load_model[:user] \r\n    user = user_model.where(:login=>@current_user.login).first\r\n    unless user\r\n    user = user_model.where(:login=>\'admin\').first\r\n    end\r\n    user_id = nil\r\n    user_id = user.id if user\r\n    \r\n\r\n    mproject = get_model \'project\'\r\n    \r\n    project =  mproject.find(params[:id])\r\n    \r\n    if project\r\n    \r\n        project.update_attributes :status=>params[:status]\r\n        \r\n    end\r\n    \r\n    \r\n    \r\n    if false and docx \r\n         mdocument_history =  get_model \'document_history\'\r\n        docx.update_attributes :status=>params[:status]\r\n        mdocument_history.create :login=>\"\\\\#{@current_user}/\\\\#{@current_role}\", :user_id=>user_id, :project_document_id=>docx.id, :document_id=>docx.document_id, :type=>params[:status].upcase\r\n\r\n    end\r\n    \r\n    return_url = \"../Home/index\"\r\n    \r\n    \r\n   \r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=<%=return_url%>\" />',NULL,NULL,NULL,'2018-03-04 16:53:47','2018-03-04 16:53:47','process_project',''),(3411,'submit',1253,3,'\r\n<%\r\n\r\n    models = get_model\r\n    \r\n    \r\n    # http://emr-life.com/esm/ehr/pacs/Home/submit?domain=emrlife.com&solution=colo&id=5a20b8b9e138233dc30007c1&report=colono\r\n    \r\n    \r\n    site = models[:site].where(:domain=>params[:domain], :solution=>params[:solution], :application=>params[:application]).first\r\n    \r\n    if site \r\n    \r\n    report = models[:site_report].where(:name=> params[:report]).first\r\n    \r\n    if report\r\n        \r\n        %>\r\n    <%=site.inspect %><br/>\r\n    <%=report.inspect %>\r\n    <%\r\n    if true\r\n    id = params[:id]\r\n    \r\n    date = Time.now.strftime(\"%Y-%m-%d\")\r\n    date = params[:date] if params[:date]\r\n    query=\"\"\r\n    # query = {:clinic_id=>eval(\"{\\\\#{report.clinic_id_data}}\")}\r\n    query =  \"{\\\\#{report.clinic_id_data}}\"\r\n    query2 =   \"{\\\\#{report.report_type_data}}\"\r\n    data = \"clinic_id=\\\\#{URI.escape(query)}&report_type=\\\\#{URI.escape(query2)}\"\r\n    \r\n    url = \"\'http://\\\\#{site.domain}/\\\\#{site.solution}/\\\\#{site.application}/Api/get_emr_report?report=\\\\#{report.name}&provider=\\\\#{report.provider_field}&date=\\\\#{date}&id=\\\\#{id}\'\"\r\n%> \r\n<%= data.inspect  %>\r\n<%= url %><br/>\r\n<%= date %><br/>\r\n<%\r\n   \r\n    msg =  JSON.parse `curl --data \"\\\\#{data}\" \\\\#{url}`\r\n         \r\n    data = msg[\'data\']\r\n    \r\n    puts \"------\"\r\n    \r\n    puts data.inspect \r\n    \r\n    \r\n    %>\r\n    <%= msg[\'msg\'] %><br/>\r\n\r\n     \r\n \r\n        <%\r\n    if true \r\n    \r\n    providers = models[:provider].where(:site_id=>site.id).all\r\n    \r\n    mp = {}\r\n    \r\n    for i in providers\r\n        mp[i.name] = i\r\n    end\r\n    \r\n    records = models[:record].collection.find(:site_id=>site.id, :report_id=>report.id).to_a\r\n    m = {}\r\n    \r\n    for i in records\r\n        m[i[\'record_id\']] = i\r\n    end\r\n    \r\n    # puts m.inspect\r\n    \r\n    count = 3\r\n    \r\n    for i in data\r\n        \r\n        puts i.inspect \r\n        \r\n        # r = models[:record].where(:record_id=>BSON::ObjectId(i[0])).first\r\n        r = m[BSON::ObjectId(i[0])]\r\n        \r\n         provider = mp[i[5]]\r\n            \r\n            unless provider \r\n                provider = models[:provider].create :name=>i[5], :code=>i[6], :site_id=>site.id\r\n                mp[provider.name] = provider\r\n            end\r\n            \r\n            patient = models[:patient].where(:hn=>i[3]).first\r\n            unless patient \r\n                patient = models[:patient].create :hn=>i[3], :name=>i[4]\r\n            end\r\n        \r\n        \r\n   \r\n        \r\n        \r\n        unless r   \r\n            puts \'no report\'\r\n            \r\n            r = models[:record].create :record_id=>BSON::ObjectId(i[0]), :site_id=>site.id, :provider_id=>provider.id, :report_id=>report.id, :patient_id=>patient.id, :url=>i[7],:date=>i[1],:clinic_id=>i[8], :report_type=>i[9], :updated=>i[2]\r\n        \r\n        else\r\n             puts \'exist report\'\r\n            r = models[:record].find(r[\'_id\'])\r\n        \r\n            r.update_attributes :record_id=>BSON::ObjectId(i[0]), :exported=>nil,:site_id=>site.id, :provider_id=>provider.id, :report_id=>report.id, :patient_id=>patient.id, :url=>i[7],:date=>i[1],:clinic_id=>i[8], :report_type=>i[9], :updated=>i[2]\r\n        \r\n        end\r\n        \r\n          url = \"\\\\#{r.url}\"\r\n          attach_pdf = \"http://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/pacs/Home/attach_pdf?id=\\\\#{r.id}\"\r\n \r\n    path = \"pacs\"\r\n    require_relative \'app/models/workers/pdf_generator\'\r\n    if true || count > 0 \r\n    PdfGenerator.enqueue :url=>url,:id=>r.id,:path=>path,:return=>attach_pdf\r\n    count-=1\r\n    end\r\n        \r\n        \r\n        \r\n    \r\n    end\r\n   end\r\n%>\r\n\r\n<%= data.inspect %>\r\n<%end%>\r\n<%else%>\r\nReport not found <%=params.inspect%>\r\n<%end%>\r\n<%else%>\r\nSolution not found <%=params.inspect.html_safe%>\r\n<%end%>',NULL,NULL,NULL,'2018-03-06 17:34:42','2018-03-06 17:34:42','submit','*'),(3412,'test_export',146,2,'<%\r\n    \r\n%>\r\n\r\n<% url = \"\\\\#{@current_project.get_setting \'report_server\'}?domain=\\\\#{DOMAIN}&solution=\\\\#{@current_solution.name}&application=\\\\#{@current_project.name}\"%>\r\n\r\n<%= url%>',NULL,NULL,NULL,'2018-03-06 18:06:05','2018-03-06 18:06:05','test_export',''),(3413,'document_name',1360,1,'\'endo_form\'',NULL,NULL,NULL,'2018-03-11 07:19:10','2018-03-11 07:19:10',NULL,NULL),(3414,'query_template',522,4,'<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n</style>\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # params_date = select_date\r\n    # select_date = Date.to_mongo(select_date)\r\n    \r\n    now = Time.now \r\n    \r\n    from_date = now.beginning_of_month.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-\"+params[:report][\'from_date(3i)\'] if params[:report]\r\n    @from_date = Date.to_mongo(from_date)\r\n    # from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = now.end_of_month.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-\"+params[:report][\'to_date(3i)\'] if params[:report]\r\n    @to_date = Date.to_mongo(to_date)\r\n    # to_date = to_date.end_of_month\r\n   \r\n%>\r\n\r\n\r\nFrom : <%= f.date_select :from_date, :default=>@from_date  , :order=>[:day,:month,:year],:start_year=>2008,:end_year=>Time.now.year%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>@to_date , :order=>[:day,:month,:year]%>\r\n\r\n<%\r\n   if request.post? \r\n       \r\n       \r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    other_status = {\'Cancelled\'=>0,\'Postpone\'=>0}\r\n    ipd_opd = {}\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>@from_date,\'$lt\'=>@to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n              # all pm colono of those appointments\r\n    all_patient = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\'] }}}).to_a\r\n    m_all_patient = bmap all_patient, \'_id\'\r\n    \r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_colo = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}colonoscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_colo = bmap all_pm_colo, \'parent_id\'\r\n    \r\n      # all pm colono of those appointments\r\n    all_pm_gastro = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}gastroscopy\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_gastro = bmap all_pm_gastro, \'parent_id\'\r\n    \r\n         # all pm colono of those appointments\r\n    all_pm_prescope = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}pre_scope\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_prescope = bmap all_pm_prescope, \'parent_id\'\r\n    \r\n    \r\n           # all pm colono of those appointments\r\n    all_pm_patho = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}pathology\",:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_patho = bmap all_pm_patho, \'parent_id\'\r\n    \r\n    \r\n    cs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1,\'diagnosis_note\'=>1,\'diagnosis_group\'=>1,\'endoscopist_1\'=>1}\r\n    gs = {\'_id\'=>1,\'status\'=>1,\'procedure\'=>1 ,\'diagnosis_note\'=>1,\'diagnosis_group\'=>1,\'endoscopist_1\'=>1}\r\n    \r\n    \r\n    # colo_scope = [\'rectum_scope\',\'sigmoid_scope\',\'descending_colon_scope\',\'transvers_colon_scope\',\'ascending_colon_scope\',\'cecum_scope\',\'terminal_ileum_scope\']\r\n    # for i in colo_scope\r\n    #     cs[i] = 1\r\n    # end\r\n    \r\n    # gastro_scope = [\'pharynx_scope\',\'esophagus_scope\',\'egj_scope\',\'fundus_scope\',\'cardia_scope\',\'body_scope\',\'antrum_scope\',\'first_duodenum_scope\',\'sphincter_of_oddi_scope\',\'second_duodenum_scope\',\'third_duodenum_scope\',\'forth_duodenum_scope\',\'proximal_jejunum_scope\',\'distal_jejunum_scope\']\r\n    # for i in gastro_scope\r\n    #     gs[i] = 1\r\n    # end     \r\n    \r\n    \r\n    colo = @models[:colonoscopy].collection.find({:_id=>{\'$in\'=>all_pm_colo.collect{|i| i[\'module_id\']}}},{:fields=>cs}).to_a\r\n    m_colo = bmap colo, \'_id\'\r\n    \r\n    gastro = @models[:gastroscopy].collection.find({:_id=>{\'$in\'=>all_pm_gastro.collect{|i| i[\'module_id\']}}},{:fields=>gs}).to_a\r\n    m_gastro = bmap gastro, \'_id\'\r\n \r\n \r\n    prescope = @models[:pre_scope].collection.find({:_id=>{\'$in\'=>all_pm_prescope.collect{|i| i[\'module_id\']}}},{:fields=>{\'_id\'=>1,\'type_of_patient\'=>1 }}).to_a\r\n    m_prescope = bmap prescope, \'_id\'\r\n    \r\n    patho = @models[:pathology].collection.find({:_id=>{\'$in\'=>all_pm_patho.collect{|i| i[\'module_id\']}}}).to_a\r\n    m_patho = bmap patho, \'_id\'\r\n    \r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    ###### mapping phase\r\n    \r\n    \r\n    map = {}\r\n    date_map = {}\r\n    \r\n    \r\n    for app in all_app\r\n    \r\n    \r\n       \r\n       \r\n       \r\n       #parent = m_all_pm_app[app[\'_id\']][0]\r\n       \r\n       \r\n       if  m_all_pm_app[app[\'_id\']] and parent = m_all_pm_app[app[\'_id\']][0] and m_all_patient[parent[\'patient_id\']]\r\n       pid = parent[\'_id\']\r\n       \r\n       \r\n       \r\n       \r\n       \r\n       \r\n       patient =  m_all_patient[parent[\'patient_id\']][0]\r\n       \r\n       \r\n       prescope = m_all_pm_prescope[pid]\r\n       \r\n       \r\n       \r\n       \r\n       \r\n       if prescope and prescope[0] and  m_prescope[prescope[0][\'module_id\']] and app[\'visit_type\']\r\n           \r\n           \r\n           \r\n           \r\n           prescope = m_prescope[prescope[0][\'module_id\']][0]\r\n           \r\n           \r\n           date = app[\'date\']\r\n           \r\n           visit = \'-\'\r\n           \r\n           \r\n           visit = m_visit[app[\'visit_type\']][0][\'name\'] if m_visit[app[\'visit_type\']]\r\n           \r\n           \r\n           case_type = prescope[\'type_of_patient\']\r\n           d = date.strftime(\"%Y-%m-%d\")\r\n           date_map[d] = true\r\n           key = \"\\\\#{d}-\\\\#{case_type}-\\\\#{visit}\"\r\n           \r\n           \r\n           \r\n           \r\n           \r\n           \r\n           colo =  m_all_pm_colo[pid]\r\n           if colo\r\n              colo = m_colo[colo[0][\'module_id\']][0]\r\n           end\r\n           \r\n           gastro =  m_all_pm_gastro[pid]\r\n           if gastro\r\n              gastro = m_gastro[gastro[0][\'module_id\']][0]\r\n           end\r\n           \r\n           patho =  m_all_pm_patho[pid]\r\n           if patho\r\n              patho = m_patho[patho[0][\'module_id\']][0]\r\n           end\r\n                \r\n           i = {:patient=>patient, :visit=>visit,:date=>date,:case_type=>case_type,:colo=>colo, :gastro=>gastro, :patho=>patho}\r\n           map[key] = [] unless  map[key]\r\n           map[key] << i\r\n           \r\n    end\r\n    end\r\n    end\r\n    @date_map = date_map\r\n    @map = map\r\n%>\r\n<% end %>\r\n<script>\r\n    \r\n    \r\nfunction downloadCSV(csv, filename) {\r\n    var csvFile;\r\n    var downloadLink;\r\n\r\n    // CSV file\r\n    csvFile = new Blob([csv], {type: \"text/csv\"});\r\n\r\n    // Download link\r\n    downloadLink = document.createElement(\"a\");\r\n\r\n    // File name\r\n    downloadLink.download = filename;\r\n\r\n    // Create a link to the file\r\n    downloadLink.href = window.URL.createObjectURL(csvFile);\r\n\r\n    // Hide download link\r\n    downloadLink.style.display = \"none\";\r\n\r\n    // Add the link to DOM\r\n    document.body.appendChild(downloadLink);\r\n\r\n    // Click download link\r\n    downloadLink.click();\r\n}\r\n\r\n\r\nfunction exportTableToCSV(filename) {\r\n    var csv = [];\r\n    var rows = document.querySelectorAll(\"table tr\");\r\n    \r\n    for (var i = 0; i < rows.length; i++) {\r\n        var row = [], cols = rows[i].querySelectorAll(\"td, th\");\r\n        \r\n        for (var j = 0; j < cols.length; j++) \r\n            row.push(cols[j].innerText);\r\n        \r\n        csv.push(row.join(\",\"));        \r\n    }\r\n\r\n    // Download CSV file\r\n    downloadCSV(csv.join(\"\\\\n\"), filename);\r\n}\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2018-03-11 16:52:13','2018-03-11 16:52:13','query_template',''),(3415,'pathology_report',522,2,'<h1>Pathology Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n\r\n<%=form_for \'report\' do |f| %>\r\n<%=render :inline=>this.query_template, :locals=>{:f=>f} %>\r\n<br/>\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n<% if request.post? %>\r\n\r\n<%= @from_date.inspect %> - \r\n<%= @to_date.inspect %>\r\n\r\n<%\r\n    date_map = @date_map\r\n    map = @map\r\n    \r\n    #### collate data\r\n    \r\n    res = {}\r\n    \r\n    map.each_pair do |k,l|\r\n       \r\n       \r\n       sum = 0 \r\n       for i in l\r\n        \r\n       sum += i[:patho][\'colono_pathology\'].size if i[:patho]\r\n       sum += i[:patho][\'gastro_pathology\'].size if i[:patho]\r\n       \r\n       end\r\n       \r\n       res[k] = sum\r\n        \r\n    end\r\n    \r\n    csum = {}\r\n%>\r\n\r\n<table class=\"table\" style=\"border:1px solid\">\r\n    \r\n    <thead>\r\n    \r\n        <tr>\r\n            <th rowspan=\"2\">Date</th>\r\n            <th colspan=\"3\">Elective</th>\r\n            <th colspan=\"3\">Emergency</th>\r\n\r\n\r\n            <th colspan=\"3\">Extratime</th>\r\n            \r\n            <th rowspan=\"2\">Total</th>\r\n        </tr>\r\n        <tr>\r\n            \r\n            <% for visit in %w{Elective Emergency Extratime}%> \r\n            \r\n            <% for case_type in %w{IPD OPD} %>\r\n            <th><%=case_type%></th>\r\n              <% end %>\r\n            <th>Sum</th>\r\n            <% end %> \r\n           \r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <% for d in date_map.keys.sort\r\n            \r\n        %>\r\n        <tr>\r\n        <th><%=d%></th>\r\n        <% \r\n            total = 0 \r\n        \r\n        for visit in %w{Elective Emergency Extratime} \r\n   sum = 0 \r\n\r\n        for case_type in %w{IPD OPD} %>\r\n            <% \r\n         \r\n                \r\n            \r\n                k = \"\\\\#{d}-\\\\#{case_type}-\\\\#{visit}\"\r\n                k2 = \"\\\\#{visit}-\\\\#{case_type}\"\r\n                csum[k2] = 0 unless csum[k2]\r\n                \r\n                \r\n                \r\n                i = \'\'\r\n                i = res[k] if res[k]\r\n                if i.to_i>0 \r\n                    sum+=i \r\n                    csum[k2]+=i\r\n                end\r\n                \r\n            %>\r\n            <td>\r\n                <%= i if i!=0%>\r\n            </td>\r\n            <% end %>\r\n            <th><%=sum%></th>\r\n            <%\r\n                total += sum\r\n            %>\r\n            <% end %>\r\n            <th><%=total%></th>\r\n        </tr>\r\n        <% end %>\r\n        <th>Total</th>\r\n        <% \r\n            tsum= 0 \r\n            for visit in %w{Elective Emergency Extratime}\r\n        \r\n        %>\r\n            <% \r\n                sum = 0 \r\n        for case_type in %w{IPD OPD} \r\n                k2 = \"\\\\#{visit}-\\\\#{case_type}\"\r\n                sum+= csum[k2] if csum[k2]\r\n                tsum+= csum[k2] if csum[k2]\r\n            %> \r\n            <th><%=csum[k2] if csum[k2]%></th>\r\n              <% end %>\r\n            <th><%=sum%></th>\r\n            <% end %>\r\n            <th><%=tsum%></th>\r\n        \r\n    </tbody>\r\n</table>\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<button onclick=\"exportTableToCSV(\'pathology.csv\')\">Export to CSV File</button>\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-03-11 16:52:43','2018-03-11 16:52:43','pathology_report',''),(3416,'diagnosis_report',522,2,'<h1>Diagnosis Report</h1>\r\n<%= render :inline=>this.init %>\r\n<%\r\n    query = \'\'\r\n    query = params[:report][:diagnosis] if params[:report]\r\n%>\r\n<%=form_for \'report\' do |f| %>\r\n<%\r\nlist = <<EOF\r\nNeoplastic polyp\r\nHyperplastic polyp\r\nSerrated polyp\r\nInflammatory polyp\r\nOther polyp\r\nPolyposis\r\nParasite\r\nUlcerative colitis\r\nCrohn\'s\r\nCancer\r\nDiverticulum\r\nInflammation\r\nRadiation\r\nForeign body\r\nSubmucosal\r\nExtraluminal\r\nAnastomosis complication\r\nHaemorrhoid\r\nMelanosis coli\r\nSRUS\r\nBleeding\r\nAbnormal vessel\r\nUlcer\r\nLipoma\r\nInfection\r\nBenign Stricture\r\nEndoscopic complication\r\nEOF\r\n%>\r\n<%\r\n\r\nlist = list.split(\"\\n\").collect{|i| i.strip}\r\n\r\n%>\r\n\r\n\r\n\r\n<%=render :inline=>this.query_template, :locals=>{:f=>f} %>\r\n<br/>\r\n<% list.each_with_index do |i,index|  %>\r\n<%=link_to (index+1).to_s+\". \"+i, \"#\", :id=>\"d\\\\#{index}\",:value=>i,:style=>\"width:200px;display:inline-block;border:0px solid;padding:5px\" %>\r\n<% if index%6==5 and index!=0 %>\r\n<div class=\"clear\"></div>\r\n<% end %><% end %>\r\n\r\n\r\n<script>\r\n<% list.each_with_index do |i,index|  %>\r\n$(\'#d<%=index%>\').click(function(){\r\n    v = $(this).attr(\'value\')\r\n    $(\'#dx\').val(v);\r\n})\r\n<% end %>\r\n</script>\r\n\r\n<label>Diagnosis contain : </label><%=f.text_field :diagnosis, :value=>query,:id=>\'dx\'%>\r\n<br/>\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n<% if request.post? %>\r\n\r\n<%= @from_date.inspect %> - \r\n<%= @to_date.inspect %>\r\n\r\n<%\r\n    date_map = @date_map\r\n    map = @map\r\n    \r\n    #### collate data\r\n    \r\n    query = params[:report][:diagnosis].downcase \r\n    \r\n    res = []\r\n    \r\n    map.each_pair do |k,l|\r\n     \r\n    for i in l \r\n    \r\n    \r\n    if i[:colo] \r\n        \r\n        colo = i[:colo]\r\n        if colo[\'diagnosis_note\'].downcase.index query or  colo[\'diagnosis_group\'].downcase.index query\r\n        res << i\r\n        end\r\n    end\r\n    \r\n    end\r\n       \r\n    end\r\n\r\n%>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n            <th>\r\n                Date \r\n            </th>\r\n             <th>\r\n                HN \r\n            </th>\r\n             <th>\r\n                Name \r\n            </th>\r\n             <th>\r\n                Gender \r\n            </th>\r\n             <th>\r\n                Age \r\n            </th>\r\n            \r\n             <th>\r\n                Dx Note \r\n            </th>\r\n            <th>\r\n                Dx Group\r\n            </th>\r\n            \r\n            <th>\r\n                Procedure\r\n            </th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n    <% \r\n    now = Time.now\r\n    %>\r\n        \r\n    <% for i in res.sort{|a,b| a[:date]<=>b[:date]} %>\r\n    <tr>\r\n        <td>\r\n            <%=i[:date].strftime(\"%d/%m/%Y\")%>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=i[:patient][\'hn\'] %>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=i[:patient][\'first_name\'] %> <%=i[:patient][\'last_name\'] %>\r\n        </td>\r\n        \r\n          <td>\r\n          <%\r\n          gender = \"NA\"\r\n          gender = \"M\" if i[:patient][\'gender\'] == \'1\'\r\n          gender = \"F\" if i[:patient][\'gender\'] == \'2\'\r\n          \r\n          %>\r\n            <%=gender %>\r\n        </td> \r\n        \r\n        <td>\r\n            <%=((i[:date]- i[:patient][\'birth_date\'])/365/24/3600).to_i %>\r\n        </td>\r\n        \r\n        \r\n       \r\n        <td>\r\n            <%=i[:colo][\'diagnosis_note\'] %>\r\n        </td>\r\n        <td>\r\n            <%=i[:colo][\'diagnosis_group\'].split(\"|\").join(\", \") %>\r\n        </td>\r\n          <td>\r\n            <%=i[:colo][\'procedure\'].split(\"|\").collect{|j| j if j!=\"\"}.compact.join(\", \") %>\r\n        </td>\r\n    </tr>\r\n    <% end %>\r\n    \r\n    \r\n    </tbody>\r\n</table>\r\n\r\n\r\n<button onclick=\"exportTableToCSV(\'diagnosis-<%=query%>.csv\')\">Export to CSV File</button>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-03-11 18:18:57','2018-03-11 18:18:57','diagnosis_report',''),(3417,'config',1324,1,'config = {}\r\n\r\nconfig[:version] = \'1.1\'\r\n\r\nconfig[:attachment] = []\r\n\r\nconfig[:attachment] << {:name=>\'protocol\', :title=>\'Protocol\'}\r\n\r\nconfig[:actions] = []\r\n\r\nconfig[:actions] << {:name=>\'Edit Protocol & Budget\', :action=>\'manage\', :class=>\'btn btn-info\'}\r\n\r\n\r\n\r\n\r\n\r\nconfig',NULL,NULL,NULL,'2018-03-17 11:54:28','2018-03-17 11:54:28','config',''),(3418,'manage',1324,2,'\r\n<%\r\n   mproject_doc = get_model \'project_document\'\r\n    \r\n    docx =  mproject_doc.where(:document_id=>params[:id]).first\r\n    history = []\r\n    \r\n    if docx \r\n        \r\n        history = get_model(\'document_history\').where(:project_document_id=>docx.id).all\r\