& Fee\',\"edit_quotation?id=\\\\#{docx.document_id}&update=panel\", :class=>\'btn\', :data=>{:disable_with=>\'Loading..\',:remote=>true} %> \r\n<%#link_to \'Income & Expense\',\"edit_income_expense?id=\\\\#{docx.document_id}&update=panel\", :class=>\'btn\', :data=>{:disable_with=>\'Loading..\',:remote=>true} %> \r\n<%#link_to \'Income\',\"edit_income?id=\\\\#{docx.document_id}&update=panel\", :class=>\'btn\', :data=>{:disable_with=>\'Loading..\',:remote=>true} %> \r\n\r\n<%#link_to \'Labor Expense\',\"edit_labor_expense?id=\\\\#{docx.document_id}&update=panel\", :class=>\'btn\', :data=>{:disable_with=>\'Loading..\',:remote=>true} %> \r\n<%#link_to \'Other Expense\',\"edit_other_expense?id=\\\\#{docx.document_id}&update=panel\", :class=>\'btn\', :data=>{:disable_with=>\'Loading..\',:remote=>true} %>\r\n<div id=\"panel\">\r\n<center>Loading...</center>\r\n</div>\r\n<% end %>\r\n<script>\r\n    $(document).ready(function(){\r\n         $(\'#protocol_btn\').click();\r\n\r\n\r\n    })\r\n    \r\n</script>',NULL,NULL,NULL,'2018-03-17 12:17:29','2018-03-17 12:17:29','manage',''),(3419,'edit_protocol',1324,3,'<h1>Protocol Editing</h1> \r\n<%\r\n sheet = get_model(\"pl_sheet\").find params[:id]\r\n models = get_model\r\n%>\r\n\r\n\r\n<%=form_for :protocol, :url=>\"protocol?id=\\\\#{params[:id]}&update=protocol-panel\", :data=>{:remote=>true} do |f|  %>\r\n\r\n<div id=\"protocol-panel\" style=\"overflow:scroll\">\r\n<%= render :inline=>this.protocol_form%>\r\n</div>\r\n\r\n<%= f.submit \'Update\' ,:data=>{:disable_with=>\'Updating..\'},:id=>\'update-btn\',:class=>\"btn btn-info\"%>\r\n<%= link_to \'Sort \',\"sort_protocol?id=\\\\#{params[:id]}&update=panel\" , :data=>{:remote=>true, :disable_with=>\'Loading..\'},:class=>\'btn btn-info\' %>\r\n<a data-toggle=\"modal\" class=\"btn\" id=\"add_period_btn\" data-backdrop=\"static\" href=\"#add_period\">Add Period</a>\r\n\r\n<a data-toggle=\"modal\" class=\"btn\" id=\"add_product_btn\" data-backdrop=\"static\" href=\"#add_product\"></a>\r\n\r\n<%= link_to \'Select Products\', \"javascript:$(\'#product-list\').modal(\'show\')\" %>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"modal hide fade\" id=\"add_period\" aria-hidden=\"false\" style=\"display: block;\">\r\n<%=form_for :record, :url=>\"period_add?id=\\\\#{params[:id]}&update=protocol-panel\", :data=>{:remote=>true} do |f|  %>\r\n\r\n\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Add Period</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n\r\n\r\n<h2>Period:</h2>\r\n<%= f.hidden_field :sheet_id, :value=>params[:id] %>\r\n<label>Visit</label>\r\n<%= f.text_field :visit ,:placeholder=>\"Text or Number\"%>\r\n\r\n<label>Day</label>\r\n<%= f.text_field :day ,:placeholder=>\"Number\"%>\r\n\r\n<label>Week</label>\r\n<%= f.text_field :week %>\r\n\r\n<label>Window</label>\r\n<%= f.text_field :window,:placeholder=>\"Number : +/-\"  %> \r\n\r\n<label>Est Subject</label>\r\n<%= f.text_field :est_subject, :value=>sheet.subject %>\r\n<br/>\r\n\r\n\r\n\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n								<%= f.submit \'Add Product\' ,:data=>{:disable_with=>\'Updating..\'},:id=>\"add_period_submit\", :class=>\'btn btn-info\'%> | \r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\" id=\"add_period_close\">Close</a>\r\n								</div>\r\n								<% end %>\r\n							</div>\r\n\r\n<div class=\"modal hide fade\" id=\"add_product\" aria-hidden=\"false\" style=\"display: block;\">\r\n<%=form_for :record, :url=>\"product_add?id=\\\\#{params[:id]}&update=protocol-panel\", :data=>{:remote=>true} do |f|  %>\r\n\r\n\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Add Period</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n\r\n\r\n<h2>Product:</h2>\r\n\r\n<%=hidden_field_tag :sheet_id, params[:id] %>\r\n\r\n<%=select_tag :product_id, options_for_select(get_model(\'pl_product\').all.collect{|i| [i.name,i.id]}) ,:include_blank=>true%>\r\n\r\n\r\n<label>Name</label>\r\n<%= f.text_field :name %>\r\n\r\n<label>Code</label>\r\n<%= f.text_field :code %>\r\n\r\n<label>Category</label>\r\n<%= f.select :category_id, options_for_select(get_model(\'pl_category\').all.collect{|i| [i.name,i.id]}) %>\r\n\r\n<label>Cost</label>\r\n<%= f.text_field :cost %>\r\n\r\n<label>Price</label>\r\n<%= f.text_field :price %>\r\n\r\n<label>PI mh</label>\r\n<%= f.text_field :pi_mh %>\r\n<br/>\r\n<label>SN mh</label>\r\n<%= f.text_field :sn_mh %>\r\n<br/>\r\n<label>SC mh</label>\r\n<%= f.text_field :sc_mh %>\r\n<br/>\r\n<label>PH mh</label>\r\n<%= f.text_field :ph_mh %>\r\n<br/>\r\n\r\n\r\n\r\n\r\n			</div>\r\n								<div class=\"modal-footer\"><%= f.submit \'Add Product\' ,:data=>{:disable_with=>\'Updating..\'}, :class=>\'btn btn-info\'%>\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n								\r\n<% end %>								\r\n</div>\r\n\r\n\r\n</div>\r\n<div class=\"modal hide fade modal-lg\" id=\"product-list\">\r\n\r\n<%=form_for :record, :url=>\"product_add?id=\\\\#{params[:id]}&update=protocol-panel\", :data=>{:remote=>true} do |f|  %>\r\n\r\n\r\n<div class=\"modal-header\">\r\n	<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n	<h3>Select Products</h3><%=text_field_tag \"search\", \"\", :id=>\'search_product\' %>\r\n\r\n\r\n</div>\r\n<div class=\"modal-body\">\r\n\r\n\r\n<%=hidden_field_tag :sheet_id, params[:id] %>\r\n<table class=\"table\">\r\n<thead>\r\n    <tr>\r\n        <th></th><th>Name</th><th>Code</th><th>Cost</th><th>Price</th><th>Group Code</th><th>Vendor Code</th>\r\n    </tr>\r\n</thead>\r\n<% \r\nproducts = get_model(\'pl_product\').all\r\nfor i in products %>\r\n\r\n<tr id=\"s<%=i.id%>\">\r\n<td>\r\n    <%=check_box_tag \"p[\\\\#{i.id}]\",\"1\" ,false%>\r\n</td>\r\n<td>\r\n <%=i.name%>\r\n</td>\r\n\r\n<td><%=i.code%></td>\r\n<td><%=i.cost%></td>\r\n<td><%=i.price%></td>\r\n<td><%=i.group_code%></td>\r\n<td><%=i.vendor_code%></td>\r\n\r\n</tr>\r\n\r\n\r\n\r\n<% end %>\r\n</table>\r\n\r\n<script>\r\n   $(document).ready(function(){\r\n       products = <%=products.to_json.html_safe%>\r\n    \r\n       $(\'#search_product\').keyup(function(){\r\n           v = $(this).val()\r\n           if(v.length>0){\r\n               count = 0 ;\r\n               v = v.toLowerCase();\r\n           for(var id in products){\r\n               if(v==\"\"){\r\n                   $(\'#s\'+p[\'id\']).show();\r\n               }else{\r\n               p = products[id];\r\n               if(p[\'name\'].toLowerCase().indexOf(v)>=0||p[\'code\'].toLowerCase().indexOf(v)>=0){\r\n                   $(\'#s\'+p[\'id\']).show();\r\n                      count +=1;\r\n               }else{\r\n                    $(\'#s\'+p[\'id\']).hide();\r\n               }\r\n               if(count>20)\r\n               break;\r\n                }\r\n           }}\r\n       })\r\n       \r\n       $(\'#select-product\').click(function(){\r\n           \r\n           $(\'#update-btn\').click();\r\n           \r\n           javascript:$(\'#product-list\').modal(\'hide\')\r\n           \r\n           return true;\r\n           \r\n       })\r\n           \r\n       \r\n       \r\n    //   $(\'#product-list\').toggle();\r\n       \r\n   })\r\n\r\n</script>\r\n\r\n			</div>\r\n<div class=\"modal-footer\"><%= f.submit \'Select\' ,:data=>{:disable_with=>\'Updating..\'},:id=>\'select-product\', :class=>\'btn btn-info\'%>\r\n	<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n	</div>\r\n								\r\n<% end %>								\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"modal hide fade\" id=\"config_chem\" aria-hidden=\"false\" style=\"display: block;\">\r\n<div class=\"modal-dialog modal-lg\" id=\"config_chem_content\">\r\n...	\r\n				\r\n</div>\r\n</div>\r\n\r\n',NULL,NULL,NULL,'2018-03-17 12:30:40','2018-03-17 12:30:40','edit_protocol',''),(3420,'protocol',1324,3,'\r\n<% if request.post? \r\n\r\n   models = get_model\r\n   \r\n   cp_map = {}\r\n   \r\n   if params[:product_price]\r\n      \r\n       params[:product_price].each_pair do |k,v|\r\n          detail = params[:product_detail][k] \r\n          i = models[:pl_period_product].find(k)\r\n          if v.to_f != i.price\r\n            cp_map[k] = true\r\n          end      \r\n          i.update_attributes :price=>v.to_f, :detail=>detail\r\n          \r\n       end\r\n       \r\n   end\r\n   \r\n   \r\n   if params[:p]\r\n   \r\n   imap = {}\r\n   items = models[:pl_period_item].where(:sheet_id=>params[:id]).all\r\n   for j in items\r\n    k = \"\\\\#{j.period_id}-\\\\#{j.period_product_id}\"\r\n    imap[k] = j\r\n   end\r\n   \r\n   mark = {}\r\n   \r\n    \r\n    \r\n    periods = get_model(\"pl_period\").where(:sheet_id=>params[:id]).sort(:sort_order).all\r\n\r\n\r\n   \r\n\r\n   for i in params[:p].keys\r\n     \r\n\r\n   k = i.split(\"|\")\r\n   \r\n   period_product = models[:pl_period_product].find(k[0])\r\n   \r\n   \r\n   \r\n   #period = models[:pl_period].where(:sheet_id=>params[:id], :day=>k[1]).first\r\n     period = periods[k[1].to_i]#models[:pl_period].where(:sheet_id=>params[:id], :day=>k[1]).first\r\n\r\n\r\n   \r\n   if period_product and period\r\n      \r\n      \r\n      k2 = \"\\\\#{period.id}-\\\\#{period_product.id}\"\r\n      \r\n      if x = imap[k2]\r\n        #existing\r\n        mark[k2] = true\r\n        if cp_map[x.period_product_id.to_s]\r\n            x.update_attributes :price=>period_product.price\r\n        end\r\n        \r\n      else\r\n      \r\n        # doesn\'t exist\r\n        x =  models[:pl_period_item].create :sheet_id=>params[:id], :period_id=>period.id, :period_product_id=>period_product.id, :product_id=>period_product.product_id, :price=>period_product.price\r\n   \r\n      \r\n      end\r\n        \r\n     \r\n      \r\n     \r\n   end\r\n   \r\n   \r\n   \r\n   \r\n   end\r\n   \r\n  # out of entry\r\n  \r\n   imap.keys.each do |im| \r\n      \r\n      unless mark[im]\r\n      \r\n        imap[im].destroy\r\n      \r\n      end\r\n       \r\n   end\r\n   \r\n   \r\n   end\r\n\r\n%>\r\nUpdated .. <%=Time.now%>\r\n<% end %>\r\n<%= render :inline=>this.protocol_form%>',NULL,NULL,NULL,'2018-03-17 12:30:56','2018-03-17 12:30:56','protocol',''),(3421,'protocol_form',1324,4,'<%\r\n\r\n    models = get_model\r\n    \r\n    sheet = get_model(\"pl_sheet\").find params[:id]\r\n    \r\n    periods = get_model(\"pl_period\").where(:sheet_id=>sheet.id).sort(:sort_order).all\r\n    \r\n    period_products = get_model(\"pl_period_product\").where(:sheet_id=>sheet.id).sort(:sort_order).all\r\n    \r\n    m_product = get_model(\"pl_product\")\r\n    \r\n    \r\n    items = models[:pl_period_item].where(:sheet_id=>sheet.id).all\r\n    map = {}\r\n    \r\n    for i in items\r\n    \r\n    k = \"\\\\#{i.period_product_id}|\\\\#{i.period_id}\"\r\n    \r\n    map[k] = i \r\n    \r\n    \r\n    end\r\n  \r\n    \r\n%>\r\n<script>\r\n    var i = 0 \r\n</script>\r\n\r\n\r\n<div style=\"float:right\">\r\nVisit (Column) : <%=link_to \'All\', \"javascript:scroll(-999,1000);\", :class=>\'btn\' %>\r\n<span class=\"col-display\"></span>\r\n<%=link_to \'<<\', \"javascript:scroll(-1000,10);\", :class=>\'btn\' %>\r\n<%=link_to \'<\', \"javascript:scroll(-1,10);\", :class=>\'btn\' %>\r\n<%=link_to \'>\', \"javascript:scroll(1,10);\", :class=>\'btn\' %>\r\n<%=link_to \'>>\', \"javascript:scroll(1000,10);\", :class=>\'btn\' %>\r\n&nbsp;&nbsp;&nbsp;\r\nItem (Row) :\r\n<%=link_to \'All\', \"javascript:rscroll(-999,100);\", :class=>\'btn\' %>\r\n<span class=\"row-display\"></span>\r\n<%=link_to \'^\', \"javascript:rscroll(-1,5);\", :class=>\'btn\' %>\r\n<%=link_to \'v\', \"javascript:rscroll(1,5);\", :class=>\'btn\' %>\r\n</div>\r\n\r\n<br/>\r\n<br/>\r\n\r\n\r\n\r\n<style>\r\n    .small{width:40px;margin:0px;};\r\n\r\n</style>\r\n\r\n<script>\r\n    function add_period(){\r\n     $(\'#record_visit\').val($(\'#visit\').val())\r\n     $(\'#record_day\').val($(\'#day\').val())\r\n     $(\'#record_week\').val($(\'#week\').val())\r\n     $(\'#record_window\').val($(\'#window\').val())\r\n     $(\'#add_period_btn\').click();\r\n     $(\'#add_period_submit\').click();\r\n     $(\'#add_period_close\').click();\r\n    }\r\n</script>\r\n\r\n\r\n\r\n<table class=\"table table-bordered table-striped\" style=\"\">\r\n  \r\n  <thead>\r\n\r\n\r\n  <tr>\r\n  \r\n  <td>\r\n  Protocol version : <%=sheet.version%>\r\n  </td>  <td></td>\r\n   <td ></td>\r\n  <td ></td>\r\n\r\n<% count = -1  %>\r\n\r\n  <% for i in periods %>\r\n  <td class=\"vcol\" cid=\"<%=count+=1%>\" ><%=link_to \"x \\\\#{count+1}\", \"period_remove?id=\\\\#{params[:id]}&period_id=\\\\#{i.id}&update=protocol-panel\",:data=>{:remote=>true,:confirm=>\'Are you sure?\'}, :class=>\"btn btn-danger btn-mini\" %></td>\r\n  <% end %>\r\n  <td><%=link_to \"+\", \"javascript:add_period()\",:class=>\'btn btn-success btn-mini\' %></td>\r\n\r\n  </tr>\r\n  <tr>\r\n  <th>\r\n  Visit\r\n  </th>\r\n  <th></th>\r\n  <th ></th>\r\n  <th ></th>\r\n\r\n\r\n  <% \r\n    next_visit = 1\r\n \r\n \r\n  periods.each_with_index do |i,index|\r\n  relative = 1\r\n  relative = periods[index].day.to_i - periods[index-1].day.to_i if periods.size>2 \r\n  next_visit = i.day.to_i + relative\r\n  name = \'NA\'\r\n  name = \"<u>\\\\#{i.day}</u>\".html_safe if i.day and i.day!=\"\"\r\n  name = i.visit if i.visit and i.visit.size>0\r\n  \r\n  \r\n  %>\r\n \r\n  <th  class=\"vcol\" cid=\"<%=index%>\"><%=link_to name, \"../PlPeriod/edit?id=\\\\#{i.id}\", :target=>\'_blank\' %></th>\r\n  <%\r\n     \r\n    #  next_visit = i.visit.to_i + 1  \r\n  %>\r\n  <% end %>\r\n  <th>\r\n  <%=text_field_tag \"visit\", next_visit,:class=>\'small\' %>\r\n  </tr>\r\n  \r\n  <tr>\r\n  <th>\r\n  Day\r\n  </th>   <th></th> <th ></th>\r\n  <th ></th>\r\n  <% next_day = 1\r\n  \r\n  \r\n  periods.each_with_index do |i,index|\r\n    relative = 1\r\n    relative = periods[index].day.to_i - periods[index-1].day.to_i if periods.size>2 \r\n    next_day = i.day.to_i + relative\r\n    name = i.day\r\n    name = \"NA\" if i.day==nil or i.day ==\"\"\r\n  %>\r\n  <th class=\"vcol\" cid=\"<%=index%>\"><%=name%> </th>\r\n  <% end %>\r\n   <th>\r\n         <%=text_field_tag \"day\", next_day ,:class=>\'small\' %> <%#periods[periods.size-1].day%>\r\n   </th>\r\n  </tr>\r\n      \r\n  <tr>\r\n  <th>\r\n  Week\r\n  </th>  <th></th>\r\n    <th ></th>\r\n  <th ></th>\r\n <% \r\n   \r\n \r\n \r\n  periods.each_with_index do |i,index|\r\n   week = \"NA\"\r\n    week = (i.day.to_i/7).to_s if i.day.to_i>0 if i.day and i.day!=\"\"\r\n    week = i.week if i.week and i.week.size>0\r\n    \r\n    \r\n  \r\n  %>\r\n  <th class=\"vcol\" cid=\"<%=index%>\" ><%=week%></th>\r\n  <% end %>\r\n   <th>\r\n   <%\r\n     week = next_day/7\r\n   %>\r\n   <%=text_field_tag \"week\", week ,:class=>\'small\' %>\r\n\r\n   </th>\r\n  </tr>\r\n  \r\n  \r\n  <tr>\r\n  <th>\r\n  Time window for visit (Days)\r\n  </th> <th >Vendor</th>\r\n    <th >Cost</th>\r\n  <th >Price</th>\r\n  <% \r\n    window = 0 \r\n  periods.each_with_index do |i,index| %>\r\n  <th class=\"vcol\" cid=\"<%=index%>\">+/-<%=i.window%></th>\r\n   <%\r\n     window = i.window\r\n   %>\r\n  \r\n  <% end %>\r\n   <th>\r\n    <%=text_field_tag \"window\", window ,:class=>\'small\' %>\r\n   </th>\r\n  </tr>\r\n         \r\n         \r\n  </thead>\r\n  <tbody>\r\n      <% period_products.each_with_index do |i,rindex| \r\n        p  = m_product.find i.product_id\r\n        \r\n        if p\r\n            \r\n        detail = i.detail\r\n        detail = p.name if i.detail == nil or i.detail ==\"\"\r\n        cp = p\r\n        cpp = i\r\n     \r\n      %>\r\n      <tr class=\"vrow\" rid=\"<%=rindex%>\" >\r\n      <td style=\" width:450px\" >\r\n          <div style=\";border:0px solid;float:left;width:100%\">\r\n          <%=rindex+1%>. \r\n        \r\n        \r\n       <b>  <%=p.code %></b> <a href=\"#\" data-toggle=\"tooltip\" title=\"\" data-original-title=\"<%=p.name%>\"><i class=\"splashy-help\"></i></a> \r\n :  <%=p.group_code %> \r\n \r\n          \r\n             <span style=\"float:right\">\r\n              <%=link_to \"Select\", \"#\", :onclick=>\"javascript:checkSelect(\'\\\\#{i.id}\')\", :class=>\"btn btn-info btn-mini\" %>\r\n            <%=link_to \"x\", \"product_remove?id=\\\\#{params[:id]}&period_product_id=\\\\#{i.id}&update=protocol-panel\",:data=>{:remote=>true,:confirm=>\'Are you sure?\'}, :class=>\"btn btn-danger btn-mini\" %>\r\n          </span>\r\n        \r\n        </div>\r\n        <%=text_field_tag \"product_detail[\\\\#{i.id}]\", detail,:class=>\'small\', :style=>\"width:250px\"%> \r\n\r\n     \r\n          \r\n          \r\n      </td>\r\n      <td >\r\n          <%=p.vendor_code%>\r\n      </td>\r\n      <td id=\"<%=i.id%>-cost\">\r\n       <%   cost = p.cost\r\n        if p.price and p.price !=\"\" and  p.cost == p.price \r\n            cost = i.price\r\n        end %>  \r\n        <%= cost %>\r\n      </td>\r\n      \r\n      <td>\r\n          <%=text_field_tag \"product_price[\\\\#{i.id}]\", i.price,:class=>\'small\',:id=>\"\\\\#{i.id}-price\"%>\r\n          <% if p.price and p.price !=\"\" and  p.cost == p.price %>\r\n          <script>\r\n              $(\"#<%=i.id%>-price\").change(function(){\r\n                  $(\"#<%=i.id%>-cost\").html($(this).val())\r\n              })\r\n              $(\"#<%=i.id%>-price\").css(\"background-color\",\"yellow\")\r\n          </script>\r\n          <% end %>\r\n      </td>\r\n       <% periods.each_with_index do |j,index|\r\n       \r\n            k = \"\\\\#{i.id}|\\\\#{j.id}\"\r\n            k2 = \"\\\\#{i.id}|\\\\#{index}\"\r\n            vindex = \"vcol\"\r\n            \r\n       %>\r\n        <td class=\"<%=vindex%>\" cid=\"<%=index%>\">\r\n       \r\n            <%=check_box_tag \"p[\\\\#{k2}]\",\"1\", map[k], :class=>\'s_select \'+i.id %>\r\n            <%# map[k].id if map[k]%>\r\n        </td>\r\n      <% end %>\r\n      <td>\r\n         \r\n      </td>\r\n      </tr>\r\n      <% else \r\n      \r\n      i.destroy\r\n        \r\n      %>\r\n      <tr>\r\n          <td>\r\n              No product found\r\n          </td>\r\n      </tr>\r\n      <% end %>\r\n      \r\n      \r\n     <%\r\n        if cp\r\n        \r\n        \r\n        sub_items = models[:pl_product_bom].where(:product_id=>cp.id).all\r\n        \r\n     \r\n        for i in sub_items\r\n        p = models[:pl_product].find(i.sub_product_id)\r\n        \r\n        detail = p.name\r\n        detail = i.detail if i.detail and i.detail !=\'\'\r\n        \r\n        \r\n        cost = p.cost\r\n        price = p.price\r\n        \r\n        cost = i.cost if i.cost\r\n        price = i.price if i.price\r\n        \r\n        \r\n     %>\r\n     <tr class=\"vrow\" rid=\"<%=rindex%>\">\r\n         <td>&nbsp;&nbsp; - <b><%=p.code%></b> : <%=detail%> <%=\"x \\\\#{i.quantity}\" if i.quantity and  i.quantity>0%> <%=\'<b>(Option)</b>\'.html_safe if i.quantity==nil%></td>\r\n         <td><%=p.vendor_code%></td>\r\n         <td><%=cost%></td>   <td><%=price%></td>\r\n         <td colspan=\"<%=periods.size+1%>\">\r\n         </td>\r\n         \r\n         \r\n     </tr>\r\n       <% end %>\r\n       \r\n     <% end %>\r\n        \r\n    <%\r\n        if cpp\r\n        \r\n        sub_items = models[:pl_period_product_bom].where(:period_product_id=>cpp.id).all\r\n     \r\n     \r\n        for i in sub_items\r\n        p = models[:pl_product].find(i.sub_product_id)\r\n     %>\r\n     <tr class=\"vrow\" rid=\"<%=rindex%>\">\r\n         <td>&nbsp;&nbsp; - <b><%=p.code%></b> : <%=p.name%> </td>\r\n         <td><%=p.vendor_code%></td>\r\n         <td><%=i.cost%></td>   <td><%=p.price%></td>\r\n         <td colspan=\"<%=periods.size+1%>\">\r\n         </td>\r\n         \r\n         \r\n     </tr>\r\n       <% end %>\r\n       <% end %>\r\n       \r\n             <% if cp and cp.code==\'SET-CHEM\' %>\r\n       <tr class=\"vrow\" rid=\"<%=rindex%>\">\r\n           <td>\r\n               <!--<a data-toggle=\"modal\" class=\"btn\" id=\"config_chem_btn\" data-backdrop=\"static\" href=\"#config_chem\">Configure</a>-->\r\n                \r\n                <%= link_to \'Configure\', \"javascript:config_chem(\'\\\\#{cpp.id}\')\"%>\r\n\r\n           </td>\r\n             <td colspan=\"<%=periods.size+4%>\">\r\n       </tr>\r\n       \r\n         <% end %>\r\n       \r\n       \r\n      <% end %>\r\n      \r\n  </tbody>\r\n</table>\r\n\r\n<div style=\"float:right\">\r\nVisit (Column) : <%=link_to \'All\', \"javascript:scroll(-999,1000);\", :class=>\'btn\' %>\r\n<span class=\"col-display\"></span>\r\n<%=link_to \'<<\', \"javascript:scroll(-1000,10);\", :class=>\'btn\' %>\r\n<%=link_to \'<\', \"javascript:scroll(-1,10);\", :class=>\'btn\' %>\r\n<%=link_to \'>\', \"javascript:scroll(1,10);\", :class=>\'btn\' %>\r\n<%=link_to \'>>\', \"javascript:scroll(1000,10);\", :class=>\'btn\' %>\r\n&nbsp;&nbsp;&nbsp; Item (Row) : \r\n<%=link_to \'All\', \"javascript:rscroll(-999,50);\", :class=>\'btn\' %>\r\n<span class=\"row-display\"></span>\r\n<%=link_to \'^\', \"javascript:rscroll(-1,5);\", :class=>\'btn\' %>\r\n<%=link_to \'v\', \"javascript:rscroll(1,5);\", :class=>\'btn\' %>\r\n</div>\r\n\r\n\r\n\r\n\r\n<script>\r\n    function checkSelect(id){\r\n        post = $(document).scrollTop();\r\n        \r\n        all_check = true\r\n        $(\'.\'+id).each(function(){\r\n            obj = $(this)\r\n            if(obj.prop(\'checked\')==false){\r\n                all_check = false;\r\n            }\r\n            \r\n        }) \r\n        \r\n        if(all_check){\r\n            $(\'.\'+id).prop(\'checked\', false)\r\n        }else{\r\n            $(\'.\'+id).prop(\'checked\', true)\r\n        }\r\n\r\n        \r\n        \r\n        setTimeout(function(){\r\n          $(\'body\').scrollTop(post);\r\n        }, 10);\r\n    }\r\n    \r\n    function config_chem(rindex){\r\n        \r\n$.ajax({\r\n  url: \"chem_config?id=<%=params[:id]%>&idx=\"+rindex,\r\n  context: document.body\r\n}).done(function(data) {\r\n\r\n  $(\'#config_chem_content\' ).html(data);\r\n   $(\'#config_chem\').modal(\'show\')\r\n});\r\n           \r\n   \r\n           \r\n           \r\n    }\r\n    \r\n    \r\n    \r\n  function rscroll(n,p){\r\n        \r\n    cur = 1000\r\n    max = 0  \r\n        \r\n        \r\n    $(\'.vrow:visible\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'rid\'))\r\n    if(i<cur)cur=i;   \r\n  });\r\n  \r\n  $(\'.vrow\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'rid\'))\r\n    if(i>max)max=i;\r\n\r\n  });\r\n\r\n   max+=1\r\n\r\n    \r\n        \r\n    nc = cur+n;\r\n\r\n\r\n    \r\n   \r\n    if(nc+p>max)nc=max-p;\r\n     if(nc<0)nc=0;\r\n    \r\n    console.log(\"\"+i+\" \" +nc+\" \"+(cur+n)+\" \"+max)\r\n   \r\n  $(\'.vrow\').each(function(){\r\n     \r\n     v = $(this)\r\n     i = parseInt(v.attr(\'rid\'))\r\n    \r\n     \r\n     \r\n     if(nc<=i&&i<nc+p){\r\n         v.show();  \r\n     }else{\r\n         v.hide();\r\n     }\r\n     \r\n        if(nc+p<max)max=nc+p;\r\n     $(\'.row-display\').html(\"\"+(nc+1)+\" - \"+(max))\r\n  }); \r\n  \r\n         if(n==-999)nc=-1;\r\n         $.cookie(\"ui-scroll-row\",nc,{ expires : 1 });\r\n  }\r\n    \r\n    \r\n  function scroll(n,p){\r\n\r\n  cur = 1000\r\n  max = 0 \r\n  \r\n  $(\'.vcol:visible\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'cid\'))\r\n    if(i<cur)cur=i;   \r\n  });\r\n  \r\n  $(\'.vcol\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'cid\'))\r\n    if(i>max)max=i;\r\n\r\n  });\r\n\r\n    max+=1;\r\n\r\n   \r\n    nc = cur+n;\r\n\r\n\r\n\r\n \r\n    if(nc+p>max)nc=max-p;\r\n       if(nc<0)nc=0;\r\n          \r\n  $(\'.vcol\').each(function(){\r\n     \r\n     v = $(this)\r\n     i = parseInt(v.attr(\'cid\'))\r\n    \r\n\r\n     \r\n     \r\n     if(nc<=i&&i<nc+p){\r\n         v.show();  \r\n     }else{\r\n         v.hide();\r\n     }\r\n     \r\n     if(nc+p<max)max=nc+p;\r\n      if(n==-999)nc=-1;\r\n     $(\'.col-display\').html(\"\"+(nc+1)+\" - \"+(max))\r\n      \r\n  });\r\n    \r\n       $.cookie(\"ui-scroll-col\",nc,{ expires : 1 });\r\n    \r\n  }\r\n  \r\n  col = 1000\r\n  cols= 12\r\n  row = 0\r\n  rows = 10\r\n  \r\n  value = $.cookie(\"ui-scroll-col\");\r\n  if(value!=null) col =  parseInt(value);\r\n  value = $.cookie(\"ui-scroll-row\");\r\n  if(value!=null) row =  parseInt(value);\r\n  \r\n  \r\n  if(col==-1){\r\n      col = 0;\r\n      cols = 10000;\r\n  }\r\n  \r\n  if(row==-1){\r\n      row = 0;\r\n      rows = 10000;\r\n  }\r\n  \r\n  \r\n  scroll(col,cols)\r\n  rscroll(row,rows)\r\n\r\n         \r\n               $(\'[data-toggle=\"tooltip\"]\').each(function(){\r\n              \r\n                  $(this).tooltip()\r\n              \r\n               });\r\n\r\n\r\n\r\n\r\n</script>',NULL,NULL,NULL,'2018-03-17 12:40:43','2018-03-17 12:40:43','protocol_form',''),(3422,'period_add',1324,3,'<%\r\n    m_pl_period = get_model(\"pl_period\")\r\n    params[:record][:sort_order] = params[:record][:day]\r\n    m_pl_period.create params[:record]\r\n    \r\n%>\r\n<script>\r\n     $.cookie(\"ui-scroll-col\",999,{ expires : 1 });\r\n</script>\r\n<%= render :inline=>this.protocol_form%>',NULL,NULL,NULL,'2018-03-17 12:48:55','2018-03-17 12:48:55','period_add',''),(3423,'product_add',1324,3,'<%\r\n    models = get_model \r\n    m_pl_product = models[:pl_product]\r\n    \r\n    \r\n    if params[:p]\r\n        \r\n    m_pl_period_product = get_model(\"pl_period_product\")\r\n    \r\n    sort_order = 0 \r\n    \r\n    last = m_pl_period_product.where(:sheet_id=>params[:sheet_id]).sort(:sort_order).last\r\n    \r\n    sort_order = last.sort_order+1 if last\r\n    \r\n    for i in params[:p].keys\r\n    \r\n    p =  m_pl_product.find i\r\n    \r\n    m_pl_period_product.create :price=>p.price, :sheet_id=>params[:sheet_id], :product_id=>p.id,:sort_order=>sort_order\r\n        \r\n    end\r\n        \r\n%>\r\n<script>\r\n    <% for i in params[:p].keys %>\r\n    $(\'#p_<%=i%>\').prop(\'checked\', false);\r\n    <% end %>\r\n         $.cookie(\"ui-scroll-row\",999,{ expires : 1 });\r\n\r\n\r\n    \r\n    \r\n</script>\r\n\r\n        <%= render :inline=>this.protocol_form%>\r\n\r\n\r\n<%\r\n\r\n\r\n    elsif  params[:record]\r\n    \r\n    if params[:product_id]!=\"\"\r\n        product = m_pl_product.find params[:product_id]\r\n    \r\n    else\r\n        product = m_pl_product.create params[:record]\r\n    end\r\n    \r\n    if params[:template] and params[:template] == \'income\'\r\n    \r\n           \r\n    m_pl_item = get_model(\"pl_item\")\r\n    q = 1\r\n    q = params[:quantity].to_i if params[:quantity]\r\n    m_pl_item.create :price=>params[:record][:price], :sheet_id=>params[:sheet_id], :product_id=>product.id, :quantity=>q\r\n    \r\n    \r\n    \r\n    %>\r\n    <%= render :inline=>this.income_form%>\r\n    <%\r\n        \r\n    else\r\n    \r\n    m_pl_period_product = get_model(\"pl_period_product\")\r\n    m_pl_period_product.create :price=>params[:record][:price], :sheet_id=>params[:sheet_id], :product_id=>product.id\r\n    %>\r\n    <%= render :inline=>this.protocol_form%>\r\n    <%\r\n    end\r\n    else\r\n        %>\r\n    <%= render :inline=>this.protocol_form%>\r\n    <%    \r\n    end\r\n%>\r\n',NULL,NULL,NULL,'2018-03-17 13:18:12','2018-03-17 13:18:12','product_add',''),(3424,'period_remove',1324,3,'<%\r\n    m_pl_period = get_model(\"pl_period\")\r\n    m_pl_period.find( params[:period_id]).destroy\r\n    \r\n    \r\n%>\r\n<%= render :inline=>this.protocol_form%>',NULL,NULL,NULL,'2018-03-17 17:07:27','2018-03-17 17:07:27','period_remove',''),(3425,'edit_quotation',1324,3,'<h1>Quotation Editing</h1>\r\n\r\n\r\n<%=form_for :quotation, :url=>\"quotation?id=\\\\#{params[:id]}&update=quotation-panel\", :data=>{:remote=>true} do |f|  %>\r\n\r\n<div id=\"quotation-panel\" style=\"overflow:scroll\">\r\n<%= render :inline=>this.quotation_form%>\r\n</div>\r\n\r\n<%= f.submit \'Update\' ,:data=>{:disable_with=>\'Updating..\'},:class=>\"btn btn-info\"%>\r\n<%= link_to  \'Print\' ,\"#\" ,:class=>\"btn\"%>\r\n<%= link_to  \'Download\' ,\"#\" ,:class=>\"btn\"%>\r\n\r\n\r\n\r\n<% end %>',NULL,NULL,NULL,'2018-03-18 07:41:59','2018-03-18 07:41:59','edit_quotation',''),(3426,'quotation_form',1324,4,'<%\r\n    \r\n\r\n    models = get_model\r\n    \r\n    sheet = get_model(\"pl_sheet\").find params[:id]\r\n    \r\n    periods = get_model(\"pl_period\").where(:sheet_id=>sheet.id).sort(:sort_order).all\r\n    \r\n    period_products = get_model(\"pl_period_product\").where(:sheet_id=>sheet.id).sort(:sort_order).all\r\n    \r\n    m_product = get_model(\"pl_product\")\r\n    \r\n    \r\n    items = models[:pl_period_item].where(:sheet_id=>sheet.id).all\r\n    map = {}\r\n    \r\n    for i in items\r\n    \r\n    k = \"\\\\#{i.period_product_id}|\\\\#{i.period_id}\"\r\n    \r\n    map[k] = i \r\n    \r\n    \r\n    end\r\n    \r\n%>\r\n\r\n<div style=\"float:right\">\r\nVisit (Column) : <%=link_to \'All\', \"javascript:scroll(-999,1000);\", :class=>\'btn\' %>\r\n<span id=\"col-display\"></span>\r\n<%=link_to \'<<\', \"javascript:scroll(-1000,10);\", :class=>\'btn\' %>\r\n<%=link_to \'<\', \"javascript:scroll(-1,10);\", :class=>\'btn\' %>\r\n<%=link_to \'>\', \"javascript:scroll(1,10);\", :class=>\'btn\' %>\r\n<%=link_to \'>>\', \"javascript:scroll(1000,10);\", :class=>\'btn\' %>\r\n&nbsp;&nbsp;&nbsp;\r\nItem (Row)\r\n<%=link_to \'All\', \"javascript:rscroll(-999,50);\", :class=>\'btn\' %>\r\n<span id=\"row-display\"></span>\r\n<%=link_to \'^\', \"javascript:rscroll(-1,10);\", :class=>\'btn\' %>\r\n<%=link_to \'v\', \"javascript:rscroll(1,10);\", :class=>\'btn\' %>\r\n</div>\r\n\r\n<br/>\r\n<br/>\r\n\r\n\r\n\r\n<style>\r\n    .small{width:40px;margin:0px;padding:0px;};\r\n</style>\r\n\r\n<div style=\"width:100%; overflow:scroll\">\r\n<table class=\"table table-bordered table-striped\" width=\"100%\">\r\n  \r\n  <thead>\r\n\r\n\r\n  \r\n  <tr>\r\n  <th style=\"width:200px\">\r\n  Visit\r\n  </th>\r\n\r\n  <th rowspan=\"4\">Allocation</th>\r\n\r\n\r\n  <% periods.each_with_index do |i,index| %>\r\n  <th  class=\"vcol\" cid=\"<%=index%>\"><%=i.visit%></th>\r\n  <% end %>\r\n  <th>\r\n  </tr>\r\n  \r\n  <tr>\r\n  <th>\r\n  Day\r\n  </th>\r\n  <% periods.each_with_index do |i,index| %>\r\n  <th class=\"vcol\" cid=\"<%=index%>\"><%=i.day%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n      \r\n  <tr>\r\n  <th>\r\n  Week\r\n  </th>\r\n  <% periods.each_with_index do |i,index| %>\r\n  <th class=\"vcol\" cid=\"<%=index%>\"><%=i.week%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n  \r\n  \r\n  <tr>\r\n  <th>\r\n  Time window for visit (Days)\r\n  </th>\r\n  <% periods.each_with_index do |i,index| %>\r\n  <th  class=\"vcol\" cid=\"<%=index%>\">+/-<%=i.window%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n         \r\n  </thead>\r\n  <tbody>\r\n      <%\r\n        \r\n        sum_price  = {}\r\n      \r\n      \r\n      period_products.each_with_index do |i,index| \r\n        p  = m_product.find i.product_id\r\n        \r\n      %>\r\n      <tr class=\"vrow\" rid=\"<%=index%>\">\r\n      <td>\r\n        <div style=\"width:250px\">\r\n          <%=index+1%>.\r\n    \r\n         <b><%=i.detail%></b> <a href=\"#\" data-toggle=\"tooltip\" title=\"\" data-original-title=\"<%=p.name%>\"><i class=\"splashy-help\"></i></a> \r\n             \r\n         </div>\r\n      </td>\r\n      \r\n      <td align=\"center\" >\r\n          <%=p.allocation%>\r\n      </td>\r\n      \r\n     \r\n       <% periods.each_with_index do |j,index|\r\n       \r\n            k = \"\\\\#{i.id}|\\\\#{j.id}\"\r\n            k2 = \"\\\\#{i.id}|\\\\#{j.visit}\"\r\n            \r\n            \r\n       %>\r\n        <td class=\"vcol\" cid=\"<%=index%>\" >\r\n        <%\r\n        if map[k]\r\n            \r\n            sum_price[j.id] = 0 unless sum_price[j.id]\r\n            sum_price[j.id] += map[k].price\r\n            \r\n        %>\r\n             <%=text_field_tag \"item_price[\\\\#{map[k].id}]\", map[k].price, :class=>\'small\' %>\r\n             \r\n        <% end %>     \r\n        </td>\r\n      <% end %>\r\n      <td></td>\r\n      </tr>\r\n      <% end %>\r\n      <tr>\r\n          <th>\r\n             Total cost per visit \r\n          </th>\r\n          <th></th>\r\n           <% \r\n              total_per_subject = 0 \r\n            periods.each_with_index do |j,jindex|\r\n            \r\n                total_per_subject +=  sum_price[j.id] if sum_price[j.id]\r\n            %>\r\n            <td class=\"vcol\" cid=\"\\\\#{jindex}\">\r\n                <%= sum_price[j.id] if sum_price[j.id]%>\r\n            </td>\r\n            <% end %>\r\n            <td>\r\n                <%=fm total_per_subject %>\r\n            </td>\r\n      </tr>\r\n            <tr>\r\n          <th>\r\n             EC overhead cost 20%\r\n          </th>\r\n          <th></th>\r\n           <% \r\n           \r\n              total_oh = total_per_subject*0.2\r\n         \r\n            %>\r\n            <td colspan=\"<%=periods.size%>\">\r\n                <%=fm total_oh%>\r\n            </td>\r\n          \r\n            <td>\r\n                <%=fm total_per_subject+total_oh %>\r\n            </td>\r\n      </tr>\r\n          <tr>\r\n          <th>\r\n            Total Cost\r\n          </th>\r\n          <th></th>\r\n           <% \r\n           \r\n           \r\n              total_oh = total_per_subject*0.2\r\n         \r\n            %>\r\n            <td colspan=\"<%=periods.size%>\">\r\n                <%=fn sheet.subject%> subjects\r\n            </td>\r\n          \r\n            <th class=\"alert\">\r\n            \r\n                <%=fm sheet.subject*(total_per_subject+total_oh) if sheet.subject%>\r\n                \r\n            </th>\r\n      </tr>\r\n  </tbody>\r\n</table>\r\n</div>\r\n<script>\r\n     \r\n    \r\n  function rscroll(n,p){\r\n        \r\n    cur = 1000\r\n    max = 0  \r\n        \r\n        \r\n    $(\'.vrow:visible\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'rid\'))\r\n    if(i<cur)cur=i;   \r\n  });\r\n  \r\n  $(\'.vrow\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'rid\'))\r\n    if(i>max)max=i;\r\n\r\n  });\r\n\r\n\r\n\r\n    max+=1;\r\n        \r\n    nc = cur+n;\r\n\r\n\r\n    \r\n   \r\n    if(nc+p>max)nc=max-p;\r\n     if(nc<0)nc=0;\r\n    \r\n    console.log(\"\"+i+\" \" +nc+\" \"+(cur+n)+\" \"+max)\r\n   \r\n  $(\'.vrow\').each(function(){\r\n     \r\n     v = $(this)\r\n     i = parseInt(v.attr(\'rid\'))\r\n    \r\n     \r\n     \r\n     if(nc<=i&&i<nc+p){\r\n         v.show();  \r\n     }else{\r\n         v.hide();\r\n     }\r\n     \r\n        if(nc+p<max)max=nc+p;\r\n     $(\'#row-display\').html(\"\"+(nc+1)+\" - \"+(max))\r\n  }); \r\n         if(n==-999)nc=-1;\r\n         $.cookie(\"ui-scroll-row\",nc,{ expires : 1 });\r\n  }\r\n    \r\n    \r\n  function scroll(n,p){\r\n\r\n  cur = 1000\r\n  max = 0 \r\n  \r\n  $(\'.vcol:visible\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'cid\'))\r\n    if(i<cur)cur=i;   \r\n  });\r\n  \r\n  $(\'.vcol\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'cid\'))\r\n    if(i>max)max=i;\r\n\r\n  });\r\n   \r\n   \r\n   max+=1;\r\n\r\n   \r\n    nc = cur+n;\r\n\r\n\r\n\r\n \r\n    if(nc+p>max)nc=max-p;\r\n       if(nc<0)nc=0;\r\n          \r\n  $(\'.vcol\').each(function(){\r\n     \r\n     v = $(this)\r\n     i = parseInt(v.attr(\'cid\'))\r\n    \r\n\r\n     \r\n     \r\n     if(nc<=i&&i<nc+p){\r\n         v.show();  \r\n     }else{\r\n         v.hide();\r\n     }\r\n     \r\n     if(nc+p<max)max=nc+p;\r\n     \r\n     $(\'#col-display\').html(\"\"+(nc+1)+\" - \"+(max))\r\n      \r\n  });\r\n  \r\n       if(n==-999)nc=-1;\r\n       $.cookie(\"ui-scroll-col\",nc,{ expires : 1 });\r\n  }\r\n  \r\n  \r\n  col = 1000\r\n  cols= 12\r\n  row = 0\r\n  rows = 10\r\n  \r\n  value = $.cookie(\"ui-scroll-col\");\r\n  if(value!=null) col =  parseInt(value);\r\n  value = $.cookie(\"ui-scroll-row\");\r\n  if(value!=null) row =  parseInt(value);\r\n  \r\n  \r\n  if(col==-1){\r\n      col = 0;\r\n      cols = 10000;\r\n  }\r\n  \r\n  if(row==-1){\r\n      row = 0;\r\n      rows = 10000;\r\n  }\r\n  \r\n  \r\n  scroll(col,cols)\r\n  rscroll(row,rows)\r\n\r\n\r\n\r\n         $(\'[data-toggle=\"tooltip\"]\').each(function(){\r\n                   $(this).tooltip()\r\n              \r\n               });\r\n</script>',NULL,NULL,NULL,'2018-03-18 07:50:48','2018-03-18 07:50:48','quotation_form',''),(3427,'edit_income_expense',1324,3,'<h1>Income Expense Estimation</h1>\r\n\r\n\r\n<%=form_for :protocol, :url=>\"income_expense?id=\\\\#{params[:id]}&update=income-panel\", :data=>{:remote=>true} do |f|  %>\r\n\r\n<div id=\"income-panel\" style=\"overflow:scroll\">\r\n<%= render :inline=>this.income_expense_form%>\r\n</div>\r\n\r\n<%= f.submit \'Update\' ,:data=>{:disable_with=>\'Updating..\'},:class=>\"btn btn-info\"%>\r\n<%= link_to  \'Print\' ,\"#\" ,:class=>\"btn\"%>\r\n<%= link_to  \'Download\' ,\"#\" ,:class=>\"btn\"%>\r\n\r\n\r\n\r\n<% end %>',NULL,NULL,NULL,'2018-03-18 08:23:44','2018-03-18 08:23:44','edit_income_expense',''),(3428,'income_expense_form',1324,4,'<%\r\n    income_variable = 0 \r\n    cost_expense = 0 \r\n\r\n    models = get_model\r\n    \r\n    sheet = get_model(\"pl_sheet\").find params[:id]\r\n    \r\n    periods = get_model(\"pl_period\").where(:sheet_id=>sheet.id).all\r\n    \r\n    period_products = get_model(\"pl_period_product\").where(:sheet_id=>sheet.id).all\r\n    \r\n    m_product = get_model(\"pl_product\")\r\n    \r\n    \r\n    items = models[:pl_period_item].where(:sheet_id=>sheet.id).all\r\n    map = {}\r\n    \r\n    for i in items\r\n    \r\n    k = \"\\\\#{i.period_product_id}|\\\\#{i.period_id}\"\r\n    \r\n    map[k] = i \r\n    \r\n    \r\n    end\r\n    \r\n%>\r\n<style>\r\n    .small{width:40px;margin:0px;};\r\n</style>\r\n\r\n<table class=\"table table-bordered table-striped\" style=\"\">\r\n  \r\n  <thead>\r\n\r\n\r\n  <tr>\r\n  <td>\r\n  Protocol vertion : <%=sheet.version%> (variable income)\r\n  </td>\r\n  <td rowspan=\"0\"></td>\r\n\r\n\r\n\r\n  <% for i in periods %>\r\n  <td></td>\r\n<% end %>\r\n <td>THB</td>\r\n  </tr>\r\n  <tr>\r\n  <th>\r\n  Visit\r\n  </th>\r\n  <th rowspan=\"4\"></th>\r\n\r\n\r\n  <% for i in periods %>\r\n  <th><%=i.visit%></th>\r\n  <% end %>\r\n  <th>\r\n  </tr>\r\n  \r\n  <tr>\r\n  <th>\r\n  Day\r\n  </th>\r\n  <% for i in periods %>\r\n  <th><%=i.day%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n      \r\n  <tr>\r\n  <th>\r\n  Week\r\n  </th>\r\n  <% for i in periods %>\r\n  <th><%=i.week%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n  \r\n  \r\n  <tr>\r\n  <th>\r\n  Time window for visit (Days)\r\n  </th>\r\n  <% for i in periods %>\r\n  <th>+/-<%=i.window%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n         \r\n  </thead>\r\n  <tbody>\r\n      <%\r\n        \r\n        sum_price  = {}\r\n      \r\n      \r\n      \r\n      for i in period_products\r\n        p  = m_product.find i.product_id\r\n              for j in periods \r\n       \r\n            k = \"\\\\#{i.id}|\\\\#{j.id}\"\r\n            k2 = \"\\\\#{i.id}|\\\\#{j.visit}\"\r\n        \r\n        \r\n       \r\n       \r\n        if map[k]\r\n            \r\n            \r\n            sum_price[j.id] = 0 unless sum_price[j.id]\r\n            sum_price[j.id] += map[k].price\r\n        end  \r\n        end  \r\n        \r\n      end \r\n      \r\n      %>\r\n \r\n      <tr>\r\n          <th>\r\n            Total per subjects\r\n          </th>\r\n          <th></th>\r\n           <% \r\n              total_per_subject = 0 \r\n            for j in periods \r\n            \r\n                total_per_subject +=  sum_price[j.id] if sum_price[j.id]\r\n            %>\r\n            <td>\r\n                <%= sum_price[j.id] if sum_price[j.id]%>\r\n            </td>\r\n            <% end %>\r\n            <td>\r\n                <%=fm total_per_subject %>\r\n            </td>\r\n      </tr>\r\n          <tr>\r\n          <th>\r\n           Number of subjects\r\n          </th>\r\n          <th></th>\r\n           <% \r\n            \r\n            for j in periods \r\n            \r\n               \r\n            %>\r\n            <td >\r\n                <%=text_field_tag \"period_subject[\\\\#{j.id}]\" , j.est_subject ,:class=>\'small\'%>\r\n            </td>\r\n            <% end %>\r\n            <td>\r\n            \r\n            </td>\r\n          </tr>\r\n      \r\n             <tr>\r\n          <th>\r\n            Total variable income\r\n        </th>\r\n          <th></th>\r\n           <% \r\n            total_per_visit = {}\r\n            sum_total = 0 \r\n            for j in periods \r\n                price = 0 \r\n                price = sum_price[j.id] if sum_price[j.id]\r\n                subject = sheet.subject\r\n                subject = j.est_subject if j.est_subject and j.est_subject!=0\r\n                total = subject *price\r\n                total_per_visit[j.id] = 0 unless total_per_visit[j.id]\r\n                total_per_visit[j.id] += total\r\n                sum_total += total\r\n            %>\r\n            <th >\r\n                <%=fm subject *price %>\r\n            </th>\r\n            <% end %>\r\n            <th>\r\n             <%=fm sum_total%>\r\n            </th>\r\n          </tr>\r\n        \r\n        \r\n            <tr>\r\n          <th>\r\n             EC overhead cost 20%\r\n          </th>\r\n          <th></th>\r\n           <% \r\n           oh_per_visit = {}\r\n           sum_oh =0\r\n              for j in periods \r\n                oh = total_per_visit[j.id] *0.2\r\n                oh_per_visit[j.id] = 0 unless oh_per_visit[j.id]\r\n                oh_per_visit[j.id] +=  oh\r\n                sum_oh += oh    \r\n            %>\r\n            <th >\r\n                <%=fm oh%>\r\n            </th>\r\n             <% end %>\r\n            <th>\r\n                <%=fm sum_oh %>\r\n            </th>\r\n      </tr>\r\n          <tr>\r\n          <th>\r\n            Total Income (20% OH incl.)\r\n          </th>\r\n          <th></th>\r\n             <% \r\n      \r\n           sum_total = 0\r\n              for j in periods \r\n                sum = 0 \r\n                if total_per_visit[j.id] and oh_per_visit[j.id]\r\n                sum = total_per_visit[j.id] + oh_per_visit[j.id]\r\n                end\r\n                sum_total += sum    \r\n            %>\r\n            <th >\r\n                <%=fm sum%>\r\n            </th>\r\n             <% end %>\r\n            <th class=\"alert-success\">\r\n            <%\r\n            income_variable = sum_total\r\n            %>\r\n                <%=fm sum_total %>\r\n            </th>\r\n      </tr>\r\n  </tbody>\r\n  \r\n   \r\n  <thead>\r\n\r\n\r\n  <tr>\r\n  <td>\r\n  Protocol vertion : <%=sheet.version%> (variable expense)\r\n  </td>\r\n  <td rowspan=\"0\"></td>\r\n\r\n\r\n\r\n  <% for i in periods %>\r\n  <td></td>\r\n<% end %>\r\n <td>THB</td>\r\n  </tr>\r\n  <tr>\r\n  <th>\r\n  Visit\r\n  </th>\r\n  <th rowspan=\"4\">Cost</th>\r\n\r\n\r\n  <% for i in periods %>\r\n  <th><%=i.visit%></th>\r\n  <% end %>\r\n  <th>\r\n  </tr>\r\n  \r\n  <tr class=\"hide\">\r\n  <th>\r\n  Day\r\n  </th>\r\n  <% for i in periods %>\r\n  <th><%=i.day%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n      \r\n  <tr class=\"hide\">\r\n  <th>\r\n  Week\r\n  </th>\r\n  <% for i in periods %>\r\n  <th><%=i.week%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n  \r\n  \r\n  <tr class=\"hide\">\r\n  <th>\r\n  Time window for visit (Days)\r\n  </th>\r\n  <% for i in periods %>\r\n  <th>+/-<%=i.window%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n         \r\n  </thead>\r\n   <tbody>\r\n      <%\r\n        \r\n        sum_price  = {}\r\n      \r\n      \r\n      for i in period_products\r\n        p  = m_product.find i.product_id\r\n      %>\r\n      <tr>\r\n      <th>\r\n          <%=p.name%>\r\n      </th>\r\n      \r\n      <td align=\"center\" >\r\n          <%=p.cost %>\r\n      </td>\r\n      \r\n     \r\n       <% for j in periods \r\n       \r\n            k = \"\\\\#{i.id}|\\\\#{j.id}\"\r\n            k2 = \"\\\\#{i.id}|\\\\#{j.visit}\"\r\n            \r\n            \r\n       %>\r\n        <td>\r\n        <%\r\n        if map[k]\r\n            \r\n            sum_price[j.id] = 0 unless sum_price[j.id]\r\n            sum_price[j.id] += p.cost\r\n            \r\n        %>\r\n             <%= p.cost %>\r\n             \r\n        <% end %>     \r\n        </td>\r\n      <% end %>\r\n      <td></td>\r\n      </tr>\r\n      <% end %>\r\n      <tr>\r\n          <th>\r\n             Laboratory cost per subject\r\n          </th>\r\n          <th></th>\r\n           <% \r\n              total_per_subject = 0 \r\n            for j in periods \r\n            \r\n                total_per_subject +=  sum_price[j.id] if sum_price[j.id]\r\n            %>\r\n            <th>\r\n                <%=fm sum_price[j.id] if sum_price[j.id]%>\r\n            </th>\r\n            <% end %>\r\n            <th>\r\n               <%=fm total_per_subject %>\r\n            </th>\r\n      </tr>\r\n         <tr>\r\n          <th>\r\n             Laboratory cost for all subject\r\n          </th>\r\n          <th></th>\r\n           <% \r\n              total_per_subject = 0 \r\n            for j in periods \r\n            \r\n                subject = sheet.subject\r\n                subject = j.est_subject if j.est_subject\r\n            \r\n                total_per_subject +=  sum_price[j.id]*subject if sum_price[j.id]\r\n            %>\r\n            <th>\r\n                <%=fm sum_price[j.id]*subject  if sum_price[j.id] %>\r\n            </th>\r\n            <% end %>\r\n            <th class=\"alert-danger\">\r\n                <%=fm total_per_subject %>\r\n            </th>\r\n      </tr>\r\n  <%\r\n    cost_expense = total_per_subject\r\n  %>\r\n         \r\n  </tbody>\r\n  \r\n  <%\r\n  \r\n    sheet.update_attributes :income_variable=>income_variable, :cost_expense=>cost_expense \r\n  \r\n  %>\r\n  \r\n  \r\n</table>\r\n<%#sheet.inspect %>',NULL,NULL,NULL,'2018-03-18 08:24:14','2018-03-18 08:24:14','income_expense_form',''),(3429,'income_expense',1324,3,'\r\n<% if request.post? \r\n\r\n   models = get_model\r\n   \r\n   if params[:period_subject]\r\n      \r\n       params[:period_subject].each_pair do |k,v|\r\n          models[:pl_period].find(k).update_attributes :est_subject=>v\r\n       end\r\n\r\n   \r\n   end\r\n\r\n%>\r\nUpdated .. <%=Time.now%>\r\n<% end %>\r\n<%= render :inline=>this.income_expense_form%>\r\n\r\n',NULL,NULL,NULL,'2018-03-18 09:33:03','2018-03-18 09:33:03','income_expense',''),(3430,'quotation',1324,3,'\r\n<% if request.post? \r\n\r\n   models = get_model\r\n   \r\n   if params[:item_price]\r\n      \r\n       params[:item_price].each_pair do |k,v|\r\n          models[:pl_period_item].find(k).update_attributes :price=>v.to_f \r\n       end\r\n       \r\n   end\r\n\r\n%>\r\nUpdated .. <%=Time.now%>\r\n<% end %>\r\n<%= render :inline=>this.quotation_form%>',NULL,NULL,NULL,'2018-03-18 09:55:06','2018-03-18 09:55:06','quotation',''),(3431,'labor_expense_form',1324,4,'<%\r\n    \r\n\r\n    models = get_model\r\n    \r\n    sheet = get_model(\"pl_sheet\").find params[:id]\r\n    \r\n    periods = get_model(\"pl_period\").where(:sheet_id=>sheet.id).all\r\n    \r\n    period_products = get_model(\"pl_period_product\").where(:sheet_id=>sheet.id).all\r\n    \r\n    m_product = get_model(\"pl_product\")\r\n    \r\n    \r\n    items = models[:pl_period_item].where(:sheet_id=>sheet.id).all\r\n    map = {}\r\n    \r\n    for i in items\r\n  