d align=\"center\" >\r\n          <%=w%>\r\n          \r\n      </td>\r\n      \r\n     \r\n       <% for j in periods \r\n       \r\n            k = \"\\\\#{i.id}|\\\\#{j.id}\"\r\n            k2 = \"\\\\#{i.id}|\\\\#{j.visit}\"\r\n            \r\n            \r\n       %>\r\n        <td>\r\n        <%\r\n        if map[k]\r\n            \r\n            sum_price[j.id] = 0 unless sum_price[j.id]\r\n            sum_price[j.id] += w if w\r\n            \r\n        %>\r\n             <%=w %>\r\n             \r\n        <% end %>     \r\n        </td>\r\n      <% end %>\r\n      <td></td>\r\n      </tr>\r\n      <% end %>\r\n      <tr>\r\n          <th>\r\n            Total hours per visit per subject\r\n          </th>\r\n          <th></th>\r\n           <% \r\n              total_per_subject = 0 \r\n            for j in periods \r\n            \r\n                total_per_subject +=  sum_price[j.id] if sum_price[j.id]\r\n            %>\r\n            <th>\r\n                <%= sum_price[j.id] if sum_price[j.id]%>\r\n            </th>\r\n            <% end %>\r\n            <th class=\"alert-success\">\r\n                <%=fm total_per_subject %>\r\n            </th>\r\n      </tr>\r\n      \r\n       <tr>\r\n          <th>\r\n            Total cost per visit per subject\r\n          </th>\r\n          <th></th>\r\n           <% \r\n              total_per_subject = 0 \r\n            for j in periods \r\n            \r\n                total_per_subject +=  sum_price[j.id]*mh if sum_price[j.id]\r\n            %>\r\n            <th>\r\n                <%= sum_price[j.id]*mh if sum_price[j.id]%>\r\n            </th>\r\n            <% end %>\r\n            <th class=\"alert-success\">\r\n                <%=fm total_per_subject %>\r\n            </th>\r\n      </tr>\r\n      \r\n       <tr>\r\n          <th>\r\n             Total cost per visit per all subject\r\n          </th>\r\n          <th></th>\r\n           <% \r\n              total_per_subject = 0 \r\n            for j in periods \r\n            \r\n                total_per_subject +=  sum_price[j.id]*mh*j.est_subject if sum_price[j.id]\r\n            %>\r\n            <th>\r\n                <%= sum_price[j.id]*mh*j.est_subject if sum_price[j.id]%>\r\n            </th>\r\n            <% end %>\r\n            <th class=\"alert-success\">\r\n                <%=fm total_per_subject %>\r\n            </th>\r\n      </tr>\r\n      \r\n      <%\r\n      cost_study_team += total_per_subject\r\n      %>\r\n      \r\n       \r\n  </tbody>\r\n\r\n  \r\n  <% end %>\r\n  <%\r\n    sheet.update_attributes :cost_study_team=>cost_study_team\r\n  %>\r\n</table>',NULL,NULL,NULL,'2018-03-18 14:21:31','2018-03-18 14:21:31','labor_expense_form',''),(3432,'edit_labor_expense',1324,3,'<h1>Labor Expense</h1>\r\n\r\n\r\n<%=form_for :labor, :url=>\"labor_expense?id=\\\\#{params[:id]}&update=labor-panel\", :data=>{:remote=>true} do |f|  %>\r\n\r\n\r\n<div id=\"labor-panel\" style=\"overflow:scroll\">\r\n<%= render :inline=>this.labor_expense_form%>\r\n</div>\r\n\r\n<%= f.submit \'Update\' ,:data=>{:disable_with=>\'Updating..\'},:class=>\"btn btn-info\"%>\r\n<%= link_to  \'Print\' ,\"#\" ,:class=>\"btn\"%>\r\n<%= link_to  \'Download\' ,\"#\" ,:class=>\"btn\"%>\r\n\r\n\r\n\r\n<% end %>',NULL,NULL,NULL,'2018-03-18 14:23:25','2018-03-18 14:23:25','edit_labor_expense',''),(3433,'attendance_report',522,2,'<h1>Attendance Report</h1>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n</style>\r\n<script>\r\n    \r\n    \r\nfunction downloadCSV(csv, filename) {\r\n    var csvFile;\r\n    var downloadLink;\r\n\r\n    // CSV file\r\n    csvFile = new Blob([csv], {type: \"text/csv\"});\r\n\r\n    // Download link\r\n    downloadLink = document.createElement(\"a\");\r\n\r\n    // File name\r\n    downloadLink.download = filename;\r\n\r\n    // Create a link to the file\r\n    downloadLink.href = window.URL.createObjectURL(csvFile);\r\n\r\n    // Hide download link\r\n    downloadLink.style.display = \"none\";\r\n\r\n    // Add the link to DOM\r\n    document.body.appendChild(downloadLink);\r\n\r\n    // Click download link\r\n    downloadLink.click();\r\n}\r\n\r\n\r\nfunction exportTableToCSV(filename) {\r\n    var csv = [];\r\n    var rows = document.querySelectorAll(\"table tr\");\r\n    \r\n    for (var i = 0; i < rows.length; i++) {\r\n        var row = [], cols = rows[i].querySelectorAll(\"td, th\");\r\n        \r\n        for (var j = 0; j < cols.length; j++) \r\n            row.push(cols[j].innerText);\r\n        \r\n        csv.push(row.join(\",\"));        \r\n    }\r\n\r\n    // Download CSV file\r\n    downloadCSV(csv.join(\"\\\\n\"), filename);\r\n}\r\n</script>\r\n<%=form_for \'report\' do |f| %>\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # params_date = select_date\r\n    # select_date = Date.to_mongo(select_date)\r\n    \r\n    now = Time.now \r\n    \r\n    from_date = now.beginning_of_month.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-\"+params[:report][\'from_date(3i)\'] if params[:report]\r\n    @from_date = Date.to_mongo(from_date)\r\n    # from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = now.end_of_month.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-\"+params[:report][\'to_date(3i)\'] if params[:report]\r\n    @to_date = Date.to_mongo(to_date)\r\n    # to_date = to_date.end_of_month\r\n    \r\n    \r\n    list = models[:attendance].where(:date=>{\'$gte\'=>@from_date,\'$lt\'=>@to_date}).all\r\n    providers = models[:provider].all\r\n    provider_map = {}\r\n    for i in providers\r\n        provider_map[i.id] = i\r\n    end\r\n    \r\n    l = %w{n1 n2 n3 pn1 pn2 employee1 officer1}\r\n\r\n   \r\n%>\r\n\r\n\r\n\r\nFrom : <%= f.date_select :from_date, :default=>@from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>@to_date , :order=>[:day,:month,:year]%>\r\n\r\n<%=f.submit \'Search\'%>\r\n<%\r\n   if request.post? \r\n       \r\n    map = {}\r\n    \r\n    for i in list\r\n    \r\n    for j in l\r\n    \r\n        id = i[j]\r\n        map[id] = {} unless map[id]\r\n        map[id][i.date] = 1\r\n    \r\n    end\r\n    \r\n    end\r\n       \r\n       \r\n%>\r\n<table class=\"table  table-bordered table-striped\">\r\n    <thead>\r\n        <th>ชื่อ</th>\r\n        <% for i in list %>\r\n        <th><%=i.date.strftime(\"%d/%m\")%></th>    \r\n        <% end %>  \r\n        <th></th>\r\n        \r\n    </thead>\r\n  \r\n        <% \r\n        \r\n        providers = map.keys.collect{|i| provider_map[i]}.compact\r\n        \r\n        group = {}\r\n        labels = {\'2\'=>\'Nurse\',\'3\'=>\'PN\',\'8\'=>\'แม่บ้าน\',\'10\'=>\'Employ\'}\r\n        \r\n        for i in providers\r\n        \r\n            group[i.provider_type] = [] unless group[i.provider_type]\r\n            group[i.provider_type] << i\r\n        \r\n        end\r\n        \r\n        for g in %w{2 3 8 10}\r\n        %>\r\n        <thead>\r\n        <tr>\r\n            <th><%=labels[g]%></th>\r\n            <th colspan=\"<%=list.size+1%>\"></th>\r\n        \r\n        </tr>\r\n        \r\n        \r\n        </thead>\r\n        <tbody>\r\n        <%\r\n        for j in group[g]\r\n        sum = 0 \r\n        %>\r\n        <tr>\r\n        <th><%=j.name%></th>\r\n      \r\n        <% for i in list \r\n            \r\n            sum += 1 if map[j.id][i.date]\r\n        \r\n        %>\r\n        <td><%=map[j.id][i.date]%></td>    \r\n        <% end %>\r\n        <th><%=sum%></th>\r\n        </tr>\r\n        <% end %>\r\n        </tbody>\r\n         <% end %>\r\n   \r\n</table>\r\n \r\n<%\r\nend\r\n%>\r\n    <button onclick=\"exportTableToCSV(\'attendance.csv\')\">Export to CSV File</button>\r\n\r\n\r\n<%\r\nend\r\n%>\r\n\r\n\r\n\r\n   ',NULL,NULL,NULL,'2018-03-19 16:34:14','2018-03-19 16:34:14','attendance_report',''),(3434,'income_form',1324,4,'<%\r\n    income_variable = 0 \r\n    cost_expense = 0 \r\n\r\n    models = get_model\r\n    \r\n    sheet = get_model(\"pl_sheet\").find params[:id]\r\n    \r\n    periods = get_model(\"pl_period\").where(:sheet_id=>sheet.id).all\r\n    \r\n    period_products = get_model(\"pl_period_product\").where(:sheet_id=>sheet.id).all\r\n    \r\n    m_product = get_model(\"pl_product\")\r\n    \r\n    \r\n    items = models[:pl_period_item].where(:sheet_id=>sheet.id).all\r\n    map = {}\r\n    \r\n    for i in items\r\n    \r\n    k = \"\\\\#{i.period_product_id}|\\\\#{i.period_id}\"\r\n    \r\n    map[k] = i \r\n    \r\n    \r\n    end\r\n    \r\n%>\r\n\r\n<style>\r\n    .small{width:40px;margin:0px;};\r\n</style>\r\n\r\n<table class=\"table table-bordered table-striped\" style=\"\">\r\n  \r\n  <thead>\r\n\r\n\r\n  <tr>\r\n  <td>\r\n  Protocol vertion : <%=sheet.version%> (variable income)\r\n  </td>\r\n  <td rowspan=\"0\"></td>\r\n\r\n\r\n\r\n  <% for i in periods %>\r\n  <td></td>\r\n<% end %>\r\n <td>THB</td>\r\n  </tr>\r\n  <tr>\r\n  <th>\r\n  Visit\r\n  </th>\r\n  <th rowspan=\"4\"></th>\r\n\r\n\r\n  <% for i in periods %>\r\n  <th><%=i.visit%></th>\r\n  <% end %>\r\n  <th>\r\n  </tr>\r\n  \r\n  <tr>\r\n  <th>\r\n  Day\r\n  </th>\r\n  <% for i in periods %>\r\n  <th><%=i.day%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n      \r\n  <tr>\r\n  <th>\r\n  Week\r\n  </th>\r\n  <% for i in periods %>\r\n  <th><%=i.week%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n  \r\n  \r\n  \r\n  <tr>\r\n  <th>\r\n  Time window for visit (Days)\r\n  </th>\r\n  <% for i in periods %>\r\n  <th>+/-<%=i.window%></th>\r\n  <% end %>\r\n   <th>\r\n   </th>\r\n  </tr>\r\n         \r\n  </thead>\r\n  <tbody>\r\n      <%\r\n        \r\n        sum_price  = {}\r\n      \r\n      \r\n      \r\n      for i in period_products\r\n        p  = m_product.find i.product_id\r\n              for j in periods \r\n       \r\n            k = \"\\\\#{i.id}|\\\\#{j.id}\"\r\n            k2 = \"\\\\#{i.id}|\\\\#{j.visit}\"\r\n        \r\n        \r\n       \r\n       \r\n        if map[k]\r\n            \r\n            \r\n            sum_price[j.id] = 0 unless sum_price[j.id]\r\n            sum_price[j.id] += map[k].price\r\n        end  \r\n        end  \r\n        \r\n      end \r\n      \r\n      %>\r\n \r\n      <tr>\r\n          <th>\r\n            Total per subjects\r\n          </th>\r\n          <th></th>\r\n           <% \r\n              total_per_subject = 0 \r\n            for j in periods \r\n            \r\n                total_per_subject +=  sum_price[j.id] if sum_price[j.id]\r\n            %>\r\n            <td>\r\n                <%= sum_price[j.id] if sum_price[j.id]%>\r\n            </td>\r\n            <% end %>\r\n            <td>\r\n                <%=fm total_per_subject %>\r\n            </td>\r\n      </tr>\r\n          <tr>\r\n          <th>\r\n           Number of subjects\r\n          </th>\r\n          <th></th>\r\n           <% \r\n            \r\n            for j in periods \r\n            \r\n               \r\n            %>\r\n            <td >\r\n                <%=text_field_tag \"period_subject[\\\\#{j.id}]\" , j.est_subject ,:class=>\'small\'%>\r\n            </td>\r\n            <% end %>\r\n            <td>\r\n            \r\n            </td>\r\n          </tr>\r\n      \r\n             <tr>\r\n          <th>\r\n            Total variable income\r\n        </th>\r\n          <th></th>\r\n           <% \r\n            total_per_visit = {}\r\n            sum_total = 0 \r\n            for j in periods \r\n                price = 0 \r\n                price = sum_price[j.id] if sum_price[j.id]\r\n                subject = sheet.subject\r\n                subject = j.est_subject if j.est_subject and j.est_subject!=0\r\n                total = subject * price\r\n                \r\n                total_per_visit[j.id] = 0 unless total_per_visit[j.id]\r\n                total_per_visit[j.id] += total\r\n                sum_total += total\r\n            %>\r\n            <th >\r\n                <%=fm subject *price %>\r\n            </th>\r\n            <% end %>\r\n            <th>\r\n             <%=fm sum_total%>\r\n            </th>\r\n          </tr>\r\n        \r\n        \r\n            <tr>\r\n          <th>\r\n             EC overhead cost 20%\r\n          </th>\r\n          <th></th>\r\n           <% \r\n           oh_per_visit = {}\r\n           sum_oh =0\r\n              for j in periods \r\n              \r\n                oh = total_per_visit[j.id] *0.2\r\n                oh_per_visit[j.id] = 0 unless oh_per_visit[j.id]\r\n                oh_per_visit[j.id] +=  oh\r\n                sum_oh += oh    \r\n            %>\r\n            <th >\r\n                <%=fm oh%>\r\n            </th>\r\n             <% end %>\r\n            <th>\r\n                <%=fm sum_oh %>\r\n            </th>\r\n      </tr>\r\n          <tr>\r\n          <th>\r\n            Total Income (20% OH incl.)\r\n          </th>\r\n          <th></th>\r\n             <% \r\n      \r\n           sum_total = 0\r\n              for j in periods \r\n                sum = 0 \r\n                if total_per_visit[j.id] and oh_per_visit[j.id]\r\n                sum = total_per_visit[j.id] + oh_per_visit[j.id]\r\n                end\r\n                sum_total += sum    \r\n            %>\r\n            <th >\r\n                <%=fm sum%>\r\n            </th>\r\n             <% end %>\r\n            <th class=\"alert-success\">\r\n            <%\r\n            income_variable = sum_total\r\n            %>\r\n                <%=fm sum_total %>\r\n            </th>\r\n      </tr>\r\n  </tbody>\r\n  \r\n</table>\r\n  <%\r\n  \r\n  \r\n \r\n           fixed_charge  =  get_model[:pl_category].where(:name=>\'fixed_charge\').first\r\n\r\n\r\n      if fixed_charge \r\n          \r\n       items = models[:pl_item].where(:sheet_id=>sheet.id).all\r\n    \r\n  %>\r\n  <h1>Fixed Charge </h1>\r\n  <table class=\"table table-bordered table-striped\">\r\n      <thead>\r\n          <tr>\r\n              <th>Description</th>\r\n              <th>Quantity</th>\r\n              <th>Price</th>\r\n              <th>Amount</th>\r\n              \r\n          </tr>\r\n          \r\n      </thead>\r\n      <tbody>\r\n        \r\n              <%\r\n                sum = 0 \r\n              items.each_with_index do |i,index| \r\n                  \r\n                p = models[:pl_product].find i.product_id\r\n                \r\n                sum += (i.quantity * i.price) if  i.price\r\n              %>\r\n              <tr>\r\n              <td><%=%>\r\n                  <%= p.name %><%=hidden_field_tag \"p[\\\\#{i.product_id}]\",index %>\r\n              </td>\r\n              <td>\r\n                  <%=text_field_tag \"iq[\\\\#{index}]\", i.quantity,:class=>\'small\' %>\r\n              </td>\r\n               <td>\r\n                  <%=text_field_tag \"ip[\\\\#{index}]\", i.price ,:class=>\'\'%>\r\n              </td>\r\n              <td>\r\n              \r\n                  <%=text_field_tag \"ia[\\\\#{index}]\", i.quantity * i.price, :readonly=>true,:class=>\'\' if i.price and i.quantity%>\r\n                  \r\n              </td>\r\n              \r\n              </tr>\r\n              <% end %>\r\n    \r\n      </tbody>\r\n      <thead>\r\n          <tr>\r\n              <th colspan=\"3\"></th>\r\n              <th><%=fm sum%></th>\r\n          </tr>\r\n      </thead>\r\n  </table>\r\n   <%\r\n   end\r\n   %>\r\n \r\n   <%\r\n   \r\n        \r\n        oh = sum*0.2 + sheet.income_variable * 0.2 if sheet.income_variable\r\n        \r\n        \r\n       sheet.update_attributes :income_fixed=>sum, :income_oh=>oh\r\n\r\n\r\n   %>\r\n 								\r\n</div>\r\n\r\n\r\n  ',NULL,NULL,NULL,'2018-03-22 01:42:28','2018-03-22 01:42:28','income_form',''),(3435,'edit_income',1324,3,'<h1>Income</h1>\r\n\r\n\r\n<%=form_for :protocol, :url=>\"income?id=\\\\#{params[:id]}&update=income-panel\", :data=>{:remote=>true} do |f|  %>\r\n\r\n<div id=\"income-panel\" style=\"overflow:scroll\">\r\n<%= render :inline=>this.income_form%>\r\n</div>\r\n\r\n<%= f.submit \'Update\' ,:data=>{:disable_with=>\'Updating..\'},:class=>\"btn btn-info\"%>\r\n<%= link_to  \'Print\' ,\"#\" ,:class=>\"btn\"%>\r\n<%# link_to  \'Download\' ,\"#\" ,:class=>\"btn\"%>\r\n\r\n\r\n\r\n<% end %>\r\n\r\n  <a data-toggle=\"modal\" class=\"btn\" id=\"add_product_btn\" data-backdrop=\"static\" href=\"#add_product\">Add Fixed Charged Item </a>\r\n\r\n\r\n<div class=\"modal hide fade\" id=\"add_product\" aria-hidden=\"false\" style=\"display: block;\">\r\n<%=form_for :record, :url=>\"product_add?id=\\\\#{params[:id]}&update=income-panel&template=income\", :data=>{:remote=>true} do |f|  %>\r\n\r\n\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Add Fixed Charged Item</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n\r\n\r\n<h2>Product:</h2>\r\n\r\n<%=hidden_field_tag :sheet_id, params[:id] %>\r\n\r\n<%=select_tag :product_id, options_for_select(get_model(\'pl_product\').all.collect{|i| [i.name,i.id]}) ,:include_blank=>true%>\r\n\r\n\r\n<label>Name</label>\r\n<%= f.text_field :name %>\r\n\r\n<label>Code</label>\r\n<%= f.text_field :code %>\r\n<%\r\n     fixed_charge  =  get_model[:pl_category].where(:name=>\'fixed_charge\').first\r\n%>\r\n<%= f.hidden_field :category_id, :value=>fixed_charge.id %>\r\n\r\n<label>Price</label>\r\n<%= f.text_field :price %>\r\n\r\n<label>Quantity</label>\r\n<%= text_field_tag :quantity, 1 %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n</div>\r\n<div class=\"modal-footer\"><%= f.submit \'Add Product\' ,:data=>{:disable_with=>\'Updating..\'}, :class=>\'btn btn-info\'%>\r\n<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n</div>\r\n								\r\n<% end %>',NULL,NULL,NULL,'2018-03-22 01:44:01','2018-03-22 01:44:01','edit_income',''),(3436,'income',1324,3,'\r\n<% if request.post? \r\n\r\n   models = get_model\r\n   \r\n   if params[:period_subject]\r\n      \r\n       params[:period_subject].each_pair do |k,v|\r\n          models[:pl_period].find(k).update_attributes :est_subject=>v\r\n       end\r\n    end\r\n   \r\n   if params[:p]\r\n       uniq = {}\r\n       \r\n    items = models[:pl_item].where(:sheet_id=>params[:id]).all\r\n  for j in items\r\n    j.destroy\r\n  end\r\n       \r\n       params[:p].each_pair do|k,index|\r\n       unless uniq[k]\r\n            uniq[k] =true\r\n       \r\n            p = models[:pl_product].find k\r\n            \r\n            q = params[:iq][index]\r\n            price = params[:ip][index]\r\n            \r\n            models[:pl_item].create :product_id=>p.id, :sheet_id=>params[:id], :quantity=>q, :price=>price if p\r\n       end\r\n   end\r\n   end\r\n       \r\n   \r\n   \r\n   \r\n\r\n%>\r\nUpdated .. <%=Time.now%>\r\n<% end %>\r\n<%= render :inline=>this.income_form%>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-03-22 01:45:47','2018-03-22 01:45:47','income',''),(3437,'document_name',1361,1,'\'pl_item\'',NULL,NULL,NULL,'2018-03-22 01:53:28','2018-03-22 01:53:28',NULL,NULL),(3438,'context_menu',1098,4,'<div class=\"accordion-group\">\r\n	<div class=\"accordion-heading\">\r\n		<a href=\"#collapse-0\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n		Dashboard\r\n		</a>\r\n		<div class=\"accordion-body collapse in\" id=\"collapse-0\">\r\n			<div class=\"accordion-inner\">\r\n				<ul class=\"nav nav-list\">\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"index\">Overview</a></li>\r\n					\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"procedure_sum_report\">Procedure Summary Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"month_sum_report\">Month Summary Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"weekly_report\">Weekly Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"case_report\">Monthly Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"yearly_report\">Yearly Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"annual_report\">Annual Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"endoscopist_report\">Endoscopist Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"procedure_report\">Procedure Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"total_ssa_report\">SSA Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"total_esd_report\">ESD Report</a></li>\r\n                	<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"bowel_report\">Bowel Prep Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"nbi_report\">NBI Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"emr_report\">EMR Summary Report</a></li>\r\n    				<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"pathology_report\">Pathology Report</a></li>\r\n\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"diagnosis_report\">Diagnosis Report</a></li>\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"attendance_report\">Attendance Report</a></li>\r\n\r\n                    <li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"case_data_report\">Case Data Report</a></li>\r\n\r\n    				<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"image_search\">Image Search</a></li>\r\n            \r\n\r\n\r\n				</ul>\r\n			</div>\r\n	</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</div></div></div>',NULL,NULL,NULL,'2018-03-27 16:13:29','2018-03-27 16:13:29','context_menu',''),(3439,'case_data_report',1098,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Case Data Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # params_date = select_date\r\n    # select_date = Date.to_mongo(select_date)\r\n    \r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n   \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date , :order=>[:day,:month,:year]%>\r\n\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    # start_date = select_date.beginning_of_month()\r\n    # stop_date = select_date.end_of_month()\r\n    \r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'visit_time\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n    \r\n    \r\n    all_m_app = @m_patient_module.collection.find({:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_m_app = bmap all_m_app, \'parent_id\'\r\n    \r\n    map = {}\r\n    mtotal = {}\r\n    dtotal = {}\r\n    \r\n    modules = %w{colonoscopy gastroscopy ercp eus bronchoscopy} \r\n    mlabels = %w{Colo EGD ERCP EUS Bronchoscopy} \r\n    \r\n\r\n\r\n    for i in all_app\r\n    \r\n        k = i[\'date\'].strftime(\"%d-%m-%Y\")\r\n        \r\n        pm = m_all_pm_app[i[\'_id\']]\r\n        if pm \r\n            pm = pm[0]\r\n            \r\n            list = m_all_m_app[pm[\'_id\']]\r\n            \r\n            map[k] = {} unless map[k]\r\n            dtotal[k] ={} unless dtotal[k]\r\n            if list\r\n            \r\n            for j in list\r\n            \r\n                mname = i[\'visit_time\']+\"_\"+j[\'module_name\'].split(\"#\")[1]\r\n                if modules.index(j[\'module_name\'].split(\"#\")[1])!=nil\r\n                map[k][mname] = 0 unless  map[k][mname]\r\n                map[k][mname]+=1 \r\n                \r\n                mtotal[mname] = 0 unless mtotal[mname]\r\n                mtotal[mname] +=1\r\n                mtotal[i[\'visit_time\']] = 0 unless mtotal[i[\'visit_time\']]\r\n                 mtotal[i[\'visit_time\']]+=1\r\n                dtotal[k][i[\'visit_time\']] = 0 unless  dtotal[k][i[\'visit_time\']]\r\n                dtotal[k][i[\'visit_time\']] += 1\r\n                \r\n                \r\n                end\r\n            end\r\n            \r\n            end\r\n                \r\n        end\r\n        \r\n    \r\n    end\r\n    \r\n  \r\n    n = modules.size+1\r\n   %>\r\n<table class=\"table table-striped\"> \r\n    <thead>\r\n        <tr>\r\n            <th></th>\r\n            <th colspan=\"<%=n%>\">Elective</th>\r\n            <th colspan=\"<%=n%>\">Extratime</th>\r\n            <th colspan=\"<%=n%>\">Ext Weekend</th>\r\n        </tr>\r\n        \r\n        <tr>\r\n            <th>Date</th>\r\n              <% for j in %w{1 2 3} %>\r\n              <% for x in mlabels %>\r\n              <th><%=x%></th>\r\n              <% end %>\r\n              <th>Sum</th>\r\n              <% end %>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n    \r\n    <%\r\n        for k in map.keys.sort \r\n        i = map[k]\r\n    %>\r\n    <tr>\r\n        <td>\r\n            <%=k%>\r\n        </td>\r\n        \r\n        <% for j in %w{1 2 3} %>\r\n        <% for x in modules\r\n            y = \"\\\\#{j}_\\\\#{x}\"\r\n        %>\r\n        <td>\r\n            <%=map[k][y]%>\r\n        </td>\r\n        <% end %>\r\n        <td>\r\n            <%=dtotal[k][j]%>\r\n        </td>\r\n        <% end %>\r\n    </tr>\r\n    <% end %>\r\n    <tr>\r\n        <th>\r\n            \r\n        </th>\r\n         <% for j in %w{1 2 3} %>\r\n        <% for x in modules\r\n            y = \"\\\\#{j}_\\\\#{x}\"\r\n        %>\r\n        <td>\r\n            <%=mtotal[y]%>\r\n        </td>\r\n        <% end %>\r\n         <td>\r\n            <%=mtotal[j]%>\r\n        </td>\r\n        <% end %>\r\n    </tr>\r\n        \r\n    </tbody>\r\n    \r\n    \r\n    \r\n</table>   \r\n<%# map.inspect %>   \r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n<%# link_to \'Print\', \"print_monthly_report_partial?report[date]=\\\\#{params_date}\",:class=>\'btn \' ,:target=>\'_blank\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-03-27 16:14:44','2018-03-27 16:14:44','case_data_report',''),(3440,'index',1362,2,'<%\r\n    models = get_model\r\n    @document = get_document \'thk_record\'\r\n    records = models[:thk_record].all\r\n%>\r\n<table class=\"table\">\r\n<thead>\r\n    <tr>\r\n        <th>Personal ID</th>\r\n        <th>DOB</th>\r\n        <th>Gender</th>\r\n        <th>Surgery Date</th>\r\n        <th>Hospital</th>\r\n        <th>Site</th>\r\n        <th>Diagnosis</th>\r\n        <th>Brand</th>\r\n        <th>Model</th>\r\n        <th>Stem</th>\r\n        <th>Cup</th>\r\n        <th>Complication</th>\r\n    </tr>\r\n</thead>\r\n   <tbody>\r\n  <% for i in records \r\n    @record = i\r\n  %>\r\n  <tr>\r\n\r\n  <td>\r\n    <%=i.personal_id%>\r\n  </td>\r\n   <td>\r\n      <%=i.birth_date%>\r\n  </td>\r\n        <td>\r\n      <%=i.gender%>\r\n  </td>\r\n    <td>\r\n      <%=i.date%>\r\n  </td>\r\n    <td>\r\n      <%=i.hospital%>\r\n  </td> \r\n\r\n  <td>\r\n      <%=i.site%>\r\n  </td>\r\n \r\n  \r\n  <td>\r\n      <%=render_value \'diagnosis\'%>\r\n  </td>  \r\n  <td>\r\n      <%=render_value \'implant_brand\'%>\r\n  </td>\r\n  <td>\r\n       <%=render_value \'implant_model\'%>\r\n  </td>\r\n  \r\n  \r\n  <td>\r\n       <%=render_value \'implant_model_stem\'%>\r\n  </td>\r\n  <td>\r\n       <%=render_value \'implant_model_cup\'%>\r\n  </td>\r\n  <td>\r\n      <%=render_value \'complication\'%>\r\n  </td>\r\n  </tr>\r\n  <% end %>\r\n  </tbody>\r\n</table>',NULL,NULL,NULL,'2018-04-03 13:11:04','2018-04-03 13:11:04','index',''),(3441,'form',1342,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n\r\n        function updateTMN(f){\r\n            t = $(f+\"t\").val()\r\n            n = $(f+\"n\").val()\r\n            m = $(f+\"m\").val()\r\n            // alert(\"T=\"+t+\" N=\"+n+\" M=\"+m);\r\n            \r\n            s = \"\"\r\n            \r\n            if(t==\'Tis\')s =  \'0\';\r\n            if(t==\'T1\')s =  \'I\';\r\n            if(t==\'T2\')s =  \'II\';\r\n            if(t==\'T3a\')s = \'IIIA\';\r\n            if(t==\'T3b\')s = \'IIIB\';\r\n            if(t==\'T4\')s =  \'IIIC\';\r\n            \r\n            \r\n            if(n==\'N1\')s= \'IVA\';\r\n            if(m==\'M1\')s= \'IVB\';\r\n          \r\n            if(n==\'\'||m==\'\')s = \'Unknown\'\r\n            \r\n            $(f+\"stage\").val(s)\r\n            \r\n      \r\n            \r\n        }\r\n    <%\r\n        list1=%w{clinical_staging_hcc_ pathological_staging_hcc_}\r\n        list2=%w{clinical_staging_cholangiocarcinoma_ pathological_staging_cholangiocarcinoma_}\r\n\r\n\r\n        \r\n        for i in list1\r\n    %>\r\n        $(\"#data-<%=i%>t\").change(function(){\r\n            updateTMN(\"#data-<%=i%>\")\r\n        })  \r\n        $(\"#data-<%=i%>n\").change(function(){\r\n            updateTMN(\"#data-<%=i%>\")\r\n        }) \r\n        $(\"#data-<%=i%>m\").change(function(){\r\n            updateTMN(\"#data-<%=i%>\")\r\n        }) \r\n    <% end %>\r\n    <%      for i in list2\r\n    %>\r\n        $(\"#data-<%=i%>t\").change(function(){\r\n            updateTMN(\"#data-<%=i%>\")\r\n        })  \r\n        $(\"#data-<%=i%>n\").change(function(){\r\n            updateTMN(\"#data-<%=i%>\")\r\n        }) \r\n        $(\"#data-<%=i%>m\").change(function(){\r\n            updateTMN(\"#data-<%=i%>\")\r\n        }) \r\n    <% end %>\r\n    \r\n    function modal_link(){\r\n    //  \r\n      id = $(this).attr(\"id\")\r\n     html = $(\"#\"+id+\"-detail\").html()\r\n     $(\"#modal-body\").html(html)\r\n      $(\'#modal_link\').click();\r\n      return false;\r\n    }\r\n    \r\n    <%\r\n    \r\n        list = %w{clinical_staging_hcc_stage pathological_staging_hcc_stage intrahepatic_bile_duct_tumor_stage distal_bile_duct_tumor_stage perihilar_bile_duct_tumor_stage gallbladder_carcinoma_stage pancreatic_carcinoma_stage}\r\n        for i in list\r\n    %>\r\n    $(\'#<%=i%> label\').append(\'<a id=\"info-<%=i%>\"><img src=\"/assets/info-ae97b3535a95d4390605ca44a249b117.gif\" alt=\"Info\"></a>\')\r\n    $(\'#info-<%=i%>\').click(modal_link);\r\n    <% end %>\r\n        \r\n</script>\r\n\r\n<a id=\"modal_link\" data-toggle=\"modal\" data-backdrop=\"static\" href=\"#modal\" style=\"display: none;\"></a>\r\n\r\n<div id=\"info-clinical_staging_hcc_stage-detail\" class=\"hide\">\r\n   <center><img src=\"/esm/nci/liver/3.jpg\" width=\"800\" ></center>\r\n</div>\r\n\r\n<div id=\"info-pathological_staging_hcc_stage-detail\"  class=\"hide\">\r\n   <center><img src=\"/esm/nci/liver/3.jpg\" ></center>\r\n</div>\r\n\r\n<div id=\"info-intrahepatic_bile_duct_tumor_stage-detail\"  class=\"hide\">\r\n   <center><img src=\"/esm/nci/liver/6.jpg\" ></center>\r\n</div>\r\n\r\n<div id=\"info-distal_bile_duct_tumor_stage-detail\"  class=\"hide\">\r\n   <center><img src=\"/esm/nci/liver/5.jpg\" ></center>\r\n</div>\r\n\r\n<div id=\"info-perihilar_bile_duct_tumor_stage-detail\"  class=\"hide\">\r\n   <center><img src=\"/esm/nci/liver/4.jpg\" ></center>\r\n</div>\r\n\r\n<div id=\"info-gallbladder_carcinoma_stage-detail\"  class=\"hide\">\r\n   <center><img src=\"/esm/nci/liver/2.jpg\" ></center>\r\n</div>\r\n\r\n<div id=\"info-pancreatic_carcinoma_stage-detail\"  class=\"hide\">\r\n   <center><img src=\"/esm/nci/liver/1.jpg\" ></center>\r\n</div>\r\n\r\n<div class=\"modal hide\" id=\"modal\" aria-hidden=\"true\" style=\"display: none;\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Modal header</h3>\r\n								</div>\r\n								<div class=\"modal-body\" id=\"modal-body\">\r\n								</div>\r\n								<div class=\"modal-footer\">\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n</div>\r\n<script>\r\n    function refresh_form(){\r\n v1 = $(\"#data-start_time\").val().split(\':\');\r\n intake = new Date(1,1,1,v1[0],v1[1]);\r\n v2 = $(\"#data-end_time\").val().split(\':\');\r\n output = new Date(1,1,1,v2[0],v2[1]);\r\n\r\n//  alert(output-intake);\r\n $(\"#data-operative_total_time\").val((output-intake)/60000);\r\n //alert(intake+output)\r\n}\r\n\r\n$(\"#data-start_time\").change(function(){\r\nrefresh_form();\r\n});\r\n$(\"#data-end_time\").change(function(){\r\nrefresh_form();\r\n});\r\n    \r\n</script>\r\n\r\n',NULL,NULL,NULL,'2018-04-04 01:57:58','2018-04-04 01:57:58','form',''),(3442,'video',226,2,'<h1>Video</h1>\r\nMov<br/>\r\n<video width=\"500\" controls>\r\n  <source src=\"/video.mov\" type=\"video/mp4\">\r\n  <source src=\"movie.ogg\" type=\"video/ogg\">\r\nYour browser does not support the video tag.\r\n</video>\r\n<br/>\r\n\r\n\r\nMp4<br/>\r\n<video width=\"500\" controls>\r\n  <source src=\"/video.mp4\" type=\"video/mp4\">\r\n  <source src=\"movie.ogg\" type=\"video/ogg\">\r\nYour browser does not support the video tag.\r\n</video>\r\n<br/>\r\n\r\nH265<br/>\r\n<video width=\"500\" controls>\r\n  <source src=\"/video.h265.mp4\" type=\"video/mp4;  codecs=hevc\">\r\n  <source src=\"movie.ogg\" type=\"video/ogg\">\r\nYour browser does not support the video tag.\r\n</video>\r\n\r\n\r\nHEVC m3u8\r\n\r\n <div id=\'player\'>\r\n            <video width=\"800\"  src=\"/video.h264.m3u8\" controls autoplay>\r\n            </video>\r\n        </div>',NULL,NULL,NULL,'2018-04-15 17:37:32','2018-04-15 17:37:32','video',''),(3443,'index_partial',1363,3,'\r\n<%\r\n\r\n\r\n    main = \'../Home/index?\'\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n\r\n\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n	model = ehr.load_model\r\n	patient_model = model[:patient]\r\n	module_model = model[:patient_module]\r\n	patients = [] \r\n	mname = \"\\\\#{@current_project.name}#appointment\"\r\n	# patients =  module_model.all(:module_name=>mname)\r\n	status_list=%w{appointed arrived preparing processing recovery completed discharge cancelled}.collect{|i| i.humanize}\r\n	\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n	p_model = models[:provider]\r\n	v_model = models[:visit_type]\r\n	\r\n	\r\n	\r\n	visits = {}\r\n	v_model.all.each do |i|\r\n	    visits[i.id]=i.name\r\n	end\r\n	indications = {}\r\n	models[:indication].all.each do |i|\r\n	    indications[i.id]=i.name\r\n	end\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	user = @current_user\r\n	%>\r\n	<% if user.login == \'opd\'%>\r\n<iframe src=\"/svh/endo/Home/print_appointment?print[date]=<%= date.strftime(\'%d/%m/%Y\') %>\" height=\"500\" width=\"100%\"></iframe>\r\n<% else %>\r\n<%# aps.inspect %>\r\n<%\r\n	id = \'\'\r\n	a_id = aps.collect{|i| i.id.to_s}\r\n	pa_id = module_model.where(:module_id=>a_id).all.collect{|i| i.id.to_s}\r\n	\r\n	sm = {}\r\n	# form service\r\n	f_ser = {}\r\n	# service_map\r\n	sv =  @current_project.get_services_by_abstract(\'ehr.emr.Document\')\r\n	sv.each do |i|\r\n	    nm = i[:name]\r\n	    if nm == \'appointment\' or nm == \'billing\' or nm == \'live_document\'\r\n	        next\r\n	    end\r\n	    \r\n	   # sm[nm.to_sym] = i[:title]\r\n	   sm[nm.to_sym] = i[:package].split(\'.\')[-1]\r\n	end\r\n	sm.each do |k, v|\r\n	    f_ser[k] = {}\r\n	    tmp = module_model.where(:module_name=>\"\\\\#{@current_project.name}#\\\\#{k}\", :parent_id=>pa_id).all\r\n	    tmp.each do |i|\r\n	       # f_ser[k][i[:patient_id].to_s] = i.id.to_s\r\n	        f_ser[k][i.parent_id] = i.id.to_s\r\n\r\n\r\n	    end\r\n	end\r\n	\r\n\r\n	\r\n	aps.collect!{|i| \r\n        id = i.id\r\n        if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n            pat_id = m.patient_id.to_s\r\n    	     patient = patient_model.find(m.patient_id)\r\n    	     if patient \r\n        	     provider = p_model.find(i.provider)\r\n        	     visit_type = visits[i.visit_type]\r\n    \r\n        	     provider_name = \'NA\'\r\n        	     provider_name = provider.name if provider\r\n        	     procedure_name = \'NA\'\r\n        	     pro = models[:procedure].find(i.procedure) \r\n        	     procedure_name = pro.name if pro\r\n        	     patient = patient_model.new unless patient \r\n        	     hn = \'-\'\r\n        	     \r\n        	     stime = i.start.strftime(\"%H:%M\")\r\n        	     now = Time.now\r\n        	     age = \'-\'\r\n        	      \r\n        	     age = ( (Time.now - patient.birth_date.to_datetime) / (3600*24*365)).to_i.to_s+\" Yr\" if patient.birth_date\r\n        	     \r\n        	     \r\n        	     hn = link_to(patient.hn, \"../../www/Patient/edit?id=\\\\#{patient.id.to_s}&return=../../\\\\#{@current_project.name}/Home/index\") if patient\r\n        	     provider_name  = link_to(provider_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n        	     public_id = \'-\'\r\n        	     \r\n        	     procedure_name = i.procedure_list if i.procedure_list and i.procedure_list!=\"\"\r\n                 procedure_name = link_to(procedure_name, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\")\r\n\r\n\r\n                c = {:ref_number=>m.ref_number,:age=>age, :public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"patient_record?id=\\\\#{i.id.to_s}\"),\r\n        	     :provider=>provider_name,:time=>stime,:date=>i.date,:room=>i.room, :note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n        	     :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n        	     :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Arrived\", :id=>\'arr_btn\', :class=>\'btn btn-small btn-success\'),\r\n        	     :anes=>i[:anes],\r\n        	     :note=>i[:note],:ward=>i[:ward]\r\n                }\r\n                \r\n                d_link = link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-info \', :style=>\'width:45px\')\r\n                # v_link = link_to(\'<i class=\"splashy-add\"></i> Add\'.html_safe, \r\n                #     \"../OutPatientForm/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=../Home/index\", \r\n                #     :class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                # c_link = \'&nbsp;&nbsp;&nbsp;&nbsp;<i class=\"splashy-remove\"></i>\'\r\n                # if f_liv[pat_id]\r\n                #     c_link = \'&nbsp;&nbsp;&nbsp;&nbsp;<i class=\"splashy-check\"></i>\'\r\n                #     v_link = link_to(\'<i class=\"splashy-document_a4\"></i> View\'.html_safe, \r\n                #         \"../OutPatientForm/show?id=\\\\#{f_liv[pat_id]}&return=../Home/index\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\')\r\n                # end\r\n                # c[:processing_ctrl]= \"\\\\#{v_link} \\\\#{d_link}\".html_safe \r\n                \r\n        l_list = []\r\n  \r\n        sm.each do |k, v|\r\n                    lab = k.to_s.split(\'_\')[0]\r\n                    \r\n                    service = @current_project.services.where(:name=>lab).first\r\n                    # lab = service.title\r\n                    if service\r\n                       lab = service.title \r\n                    else\r\n                        lab = lab.humanize\r\n                    end\r\n                \r\n                    \r\n                    v = v.delete(\' \')\r\n                    v_link = \"\" #link_to(\" \\\\#{lab}\".html_safe, \r\n                        #\"../\\\\#{v}/create?patient_id=\\\\#{pat_id}&record_name=\\\\#{patient[:hn]}&parent_id=\\\\#{m.id.to_s}&return=\\\\#{main}\", \r\n                        #:class=>\'btn btn-small \', :style=>\'width:45px\' )\r\n                    if f_ser[k][m.id]\r\n                        v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            \"../\\\\#{v}/edit?id=\\\\#{f_ser[k][m.id]}&record_name=\\\\#{patient.hn}-\\\\#{patient.first_name}-\\\\#{patient.last_name}&ref_2=\\\\#{lab}&return=\\\\#{main}\", :class=>\'btn btn-small btn-success\', :style=>\'width:65px\')\r\n                        # v_link = link_to(\" \\\\#{lab}\".html_safe, \r\n                            # \"../\\\\#{v}/print?id=\\\\#{f_ser[k][pat_id]}&return=\\\\#{request.fullpath}\", :class=>\'btn btn-small btn-success\', :style=>\'width:45px\', :target=>\'_blank\')\r\n                    end\r\n                    l_list << v_link\r\n        end\\\\#{request.fullpath}\r\n        \r\n                c[:processing_ctrl]= \"\\\\#{d_link}\".html_safe \r\n                c[:processing_ctrl] = \"\\\\#{l_list.join(\' \')} \\\\#{c[:processing_ctrl]}\".html_safe\r\n                \r\n                c\r\n            end\r\n        end\r\n	}.compact!\r\n	\r\n	table_model = %w{time procedure  hn patient age provider anes processing_ctrl   note room ward }.collect{|i| i.to_sym}\r\n	\r\n	\r\n	aps.collect!{|i| \r\n	\r\n	    i if i[:status]!=\'Cancelled\'\r\n	    \r\n	}.compact!\r\n	\r\n	\r\n	#[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n	\r\n	labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:age=>\'Age\' ,:provider=>\'Appointed Doctor\',:procedure=>\'Procedure\', :status_ctrl=>\'Status\',:pending_ctrl=>\'Actions\',\r\n	:note=>\'SR/Note\',:anes=>\'Anes\',:processing_ctrl=>\'Actions\', :out_pat=>\'Out Patient Form\',:room=>\'Room\',:ward=>\'ward\' }\r\n	\r\n	%>\r\n	<%# aps.to_json.html_safe %>\r\n	<% if @current_role==\'developer\' and false%>\r\n	<%= sm.to_json.html_safe %> <hr/>\r\n	<%= sv.to_json.html_safe %>\r\n	<% end %>\r\n	\r\n<%\r\nall_apps = aps\r\n\r\n\r\nmroom = {}\r\n\r\n    \r\n    for i in all_apps\r\n    \r\n        room = i[:room]\r\n        time = i[:time]\r\n        \r\n        mroom[room] = {} unless mroom[room]\r\n        mroom[room][time] = [] unless mroom[room][time]\r\n        mroom[room][time] << i\r\n        \r\n        # mroom[room] = [] unless mroom[room]\r\n        # mroom[room] << i\r\n        \r\n        \r\n    end\r\n	\r\n   \r\n\r\n\r\n\r\n\r\n   mroom.keys.sort.each do |room|\r\n       \r\n       tabs = mroom[room]\r\n       \r\n       \r\n%>	\r\n\r\n<h3><%=room%></h3>\r\n<div style=\"width:100%;border:0px solid\">\r\n	<div class=\"left\" style=\"width:100%;\">\r\n		<div class=\"w-box\" id=\"w_sort05\">\r\n			<div class=\"w-box-header\">\r\n				Today Patients \r\n				<div class=\"pull-right\"><i class=\"\"><%=aps.size%> Patients</i></div>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\'background:#FCF8F0\'>\r\n			                        <div class=\'row-fluid\'>\r\n			                            <table id=\'appointed-patient\' class=\"table table-striped table-bordered dTableR\">\r\n    										<thead>\r\n    											<tr>\r\n    											\r\n<%  table_model.each do |i| %>\r\n    												<th><%= labels[i.to_sym] %></th>\r\n<%  end %>\r\n    											</tr>\r\n    										</thead>\r\n    										<tbody>\r\n<%\r\n    outgroup = []\r\n\r\n    if tabs.keys.size > 0\r\n        \r\n        # %w{07:00 07:30 08:00 08:30 09:00 09:30 10:00 10:30 11:00 11:30 12:00 12:30 13:00 13:30 14:00 14:30 15:00 15:30 16:00 16:30 17:00 17:30 18:00 18:30 19:00}.each do |t| \r\n        tabs.keys.sort{|a,b| a<=>b}.each do |t| \r\n            \r\n     \r\n        \r\n        if tabs[t]\r\n        \r\n        aps = tabs[t] \r\n        \r\n        \r\n        aps.each do |i|\r\n%>\r\n                                                <tr>\r\n<%\r\n            table_model.each do |j|\r\n                \r\n%>\r\n                                                    <td style=\'vertical-align:middle\'><%= (i[j].nil? or i[j]==\'\') ? \'-\' : i[j] %></td>\r\n<%\r\n            end\r\n%>\r\n                                                </tr>\r\n<%\r\n     end\r\n%>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n                                            </tbody>\r\n                                        </table>\r\n                                    </div>\r\n\r\n\r\n<!--\r\n				<% \r\n					for visit in visits.values\r\n					 tmp = aps.collect{|w| w if  w[:visit_type]==visit }.compact\r\n					%>\r\n				<% if tmp.size>0 %>\r\n				<%=visit%>\r\n				<%= tabular :model=>table_model,:data=>tmp,:labels=>labels %>\r\n				<% end %>  <% end %>\r\n				<% if tmp = aps.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n				<%= tabular :model=>table_model,:data=>tmp ,:labels=>labels %>\r\n				<% end %>\r\n-->\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"clear\"></div>\r\n	<br/>\r\n</div>\r\n<% end %>\r\n<script>\r\n    $(document).ready(function() {\r\n        gebo_datatbles = {\r\n    		dt_a: function() {\r\n    			$(\'#appointed-patient\').dataTable({\r\n    			    stateSave : true,\r\n                    \"sDom\": \"<\'row\'<\'span6\'<\'dt_actions\'>l><\'span6\'f>r>t<\'row\'<\'span6\'i><\'span6\'p>>\",\r\n                    \"sPaginationType\": \"bootstrap_alt\",\r\n                    \"oLanguage\": {\r\n                        \"sLengthMenu\": \"_MENU_ records per page\",\r\n                        \"sEmptyTable\": \"No patient available in table. Please \'<a href=\'javascript:add_patient()\'>Add</a>\' the patient.\"\r\n                    }\r\n                });\r\n    		}\r\n        }\r\n        \r\n        gebo_datatbles.dt_a();\r\n        // gebo_datatbles.state.save();\r\n        \r\n        // $(\'#appointed-patient\').DataTable( {\r\n        //     stateSave: true,\r\n        //     columnDefs: [ {\r\n        //         targets: [ 0 ],\r\n      