 \r\n    {   \r\n        :value=>\'varices\',\r\n        :dx_id=>\'51\',\r\n        :group=>3\r\n        \r\n    }, \r\n    {   \r\n        :value=>\'phg\',\r\n        :title=>\'PHG\',\r\n        :dx_id=>\'52\',\r\n        :group=>3\r\n        \r\n    },\r\n    { \r\n        :value=>\'ulcer\',\r\n        :dx_id=>\'3\',\r\n    },\r\n    {   \r\n        :value=>\'polyp\',\r\n        :dx_id=>\'6\',\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'coustic_ingestion\',\r\n        :dx_id=>\'7\',\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'mallory_weiss\',\r\n        :dx_id=>\'8\',\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'ampulla\',\r\n        :dx_id=>\'9\',\r\n        :group=>0\r\n    },\r\n    {   \r\n        :value=>\'stricture\',\r\n        :dx_id=>\'10\',\r\n        :group=>0\r\n    },\r\n    {\r\n        :value=>\'dieulafoys_lesion\',\r\n        :dx_id=>\'15\',\r\n        :group=>0\r\n    }\r\n]\r\n}',NULL,NULL,NULL,'2018-04-18 06:14:38','2018-04-18 06:14:38','finding_config',''),(3446,'display_script',1365,4,'<style>\r\n    v {color:#000;}\r\n</style>\r\n\r\n\r\n\r\n\r\n<script>\r\n    function inspect_finding(){\r\n        \r\n        \r\n        \r\n        console.log(\"call inspect finding \")\r\n\r\n            \r\n\r\n                \r\n        \r\n        \r\n    }\r\n    \r\n\r\n</script>\r\n    \r\n<div id=\"finding-div\" style=\"width:500px\"></div>\r\n\r\n<script>\r\n\r\nvar define_inspector = null;\r\n\r\n\r\n$( document ).ready(function() {\r\n\r\nif(define_inspector==null){\r\nconsole.log(\'display script\')\r\ndefine_inspector = true    \r\n\r\ntree.regMonitor(inspect_finding);\r\n\r\nvalues = $(\'#data-findings\').val()\r\nvalues = eval(values).join(\"|\")\r\n            \r\n        \r\n$.ajax({\r\n  url: \"finding_ajax\",\r\n  method: \"POST\",\r\n  data: { values : values, init:true },\r\n  cache: false\r\n})\r\n.done(function( html ) {\r\n\r\n    $( \"#findings\" ).html( html );\r\n});\r\n