act\r\n    \r\n      \r\n       second_atts = atts[0..-1].compact\r\n       \r\n       \r\n\r\n    %>\r\n<style>\r\n@media print {\r\n    footer {page-break-after: always;}\r\n}\r\n\r\n<% \r\n\r\nif true\r\nif true %>\r\n.crop {\r\n    width: 300px;\r\n    overflow: hidden;\r\n    margin-bottom:10px;\r\n}\r\n\r\n.crop img {\r\n    width: 240px;\r\n    height: 190px;\r\n    margin: 0px 0px 0px 0px;\r\n}\r\n<% else %>\r\n.crop {\r\n    width: 240px;\r\n    height: 165px;\r\n    margin:5px;\r\n}\r\n\r\n.crop img {\r\n    width: 240px;\r\n    height: 165px;\r\n}\r\n<% end %>\r\n    \r\n<% end %>\r\n</style>\r\n    <div style=\"float:right;  width: 280px;  padding: 5px; text-align:center; font-size:14px;\">\r\n    <% for i in first_atts  %>\r\n    <div class=\"crop\">\r\n    <img src=\"<%=i.path%>\" /><br /><span><%=i.title%></span><br />\r\n    </div>\r\n    <% end %>\r\n\r\n   \r\n    \r\n    </div>\r\n\r\n<div style=\"float:left\">\r\n\r\n\r\n\r\n\r\n<%= render :inline=>this.display_script %>\r\n\r\n\r\n</div>\r\n<!--<div>  <% if record[\'report_head\']==\'Colonoscopy Diagnosis Report\' %><img src=\"/esm/svh/endo/gast.jpg\" width=\"120px\" style=\"Float:right,top:5px\"><% end%>\r\n  <% if record[\'report_head\']==\'Gastroscopy Diagnosis Report\' %><img src=\"/esm/svh/endo/colo.jpg\" width=\"120px\" style=\"Float:right,top:5px\"><% end%>\r\n  </div>\r\n-->\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong>Approved By :</strong> \r\n<%=render_value \'endoscopist\'%> \r\n \r\n</div>\r\n<div class=\"clear\"></div><br />\r\n <center style=\" color:#026889; font-size:14px\"><b>Samitivej Sukumvit Hospital</b> 133 Sukumvit 49 Klong tan nua, Vadana, Bangkok 10110 Tel 02-7118822-24 , 02-7118000 Fax 02-7118833<br />\r\n <b>โรงพยาบาลสมิติเวช</b> สุขุมวิท 133 สุขุมวิท49 คลองตันเหนือ เขตวัฒนา กรุงเทพ 10110 โทร 02-7118822-24 , 02-7118000 แฟกซ์ 02-7118833\r\n     \r\n </center>\r\n\r\n</div>\r\n\r\n\r\n\r\n<%\r\n    \r\n    n =  second_atts.size/15\r\n    \r\n    (n+1).times do |j| \r\n        \r\n    atts = second_atts[j*15..j*15+15-1].compact    \r\n%>\r\n\r\n<% if atts.size>0 %>\r\n<div class=\"footer\">\r\n   &nbsp; \r\n</div>\r\n<div class=\"wrapper\" style=\"page-break-before: always;\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'<%=@current_project.get_setting(\'logo_report_path\')%>\' height=\'70px\' style=\"Float:left,top:5px\" /></div><h3> <strong><%=@record.report_head %> <br />\r\n<%=@current_project.get_setting(\"report_title_1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%>\r\n  </strong></h3>\r\n</center>\r\n\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n<br />&nbsp;\r\n<br />\r\n<table width=\"100%\" style=\"font-size:16px\">\r\n<tr><td>    <strong>Ref HN :&nbsp;\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</strong>\r\n      <strong> Name-Surname : \r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    </strong>\r\n      <%\r\n    gender = \'-\'\r\n    if patient.gender == \'1\'\r\n        gender = \'Male\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'Female\'\r\n    end\r\n \r\n\r\n%>\r\n      &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Sex : </strong><%= gender %> &nbsp; <strong>Age :&nbsp;</strong>\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D-->\r\n      <br /><strong>Date :  </strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <%=render_value \'date\'%> <strong>Project : </strong> <%=render_value \'project\'%>\r\n    <br /><strong>Endoscopist : </strong><%=render_value \'endoscopist\'%>  \r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n   <div style