1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%></b>\r\n</td>\r\n  <td width=\"67%\"><strong>      Ref HN :&nbsp;</strong>\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> Name : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'ไม่ระบุ\'\r\n    if patient.gender == \'1\'\r\n        gender = \'ชาย(Male)\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'หญิง(Female)\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>Gender : </strong><%= gender %> &nbsp; <strong>Age</strong> :&nbsp;\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D-->\r\n      <br /><strong>Date :  </strong> <%=render_value \'date\'%> ( <%=render_value \'operation_time\'%> )<br />\r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n\r\n	<hr style=\"margin-top: 5px;\"/>\r\n    <% atts_list = record.images[0..5]\r\n       if record[:selected_image] and record.selected_image and record.selected_image.size > 0\r\n          \r\n           atts_list = record.selected_image[0..5]\r\n           \r\n       end\r\n       \r\n       \r\n       atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n\r\n    %>\r\n\r\n\r\n<style>\r\n\r\n.crop img {\r\n    width: 230px;\r\n\r\n}\r\n\r\n    \r\n</style>\r\n    <div style=\"float:right;  width: 220px;  padding: 5px; text-align:left; font-size:14px;\">\r\n    <% for i in atts  %>\r\n    <div class=\"crop\">\r\n    <img src=\"<%=i.path%>\" /><br /><center><span style=\"\"> <%=i.title%></span></center><br />\r\n    </div>\r\n    <% end %>\r\n\r\n   \r\n    \r\n    </div>\r\n\r\n<div style=\"float:left; width:650px;\">\r\n  \r\n<table width=\"100%\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n  <td width=\"26%\" valign=\"top\" class=\"sidationcss\"><strong>Endoscopist : </strong></td>\r\n  <td width=\"74%\"><%=render_value \'endoscopist\'%> <%=render_value \'other_endoscopist\'%></td>\r\n  <td width=\"74%\" rowspan=\"6\" valign=\"top\">\r\n  <% if record[\'report_head\']==\'Colonoscopy\' %><img src=\"/esm/svh/endo/colo.jpg\" width=\"200px\" style=\"Float:right,top:5px\"><% end%>\r\n  <% if record[\'report_head\']==\'Gastroscopy\' %><img src=\"/esm/svh/endo/gast.jpg\" width=\"200px\" style=\"Float:right,top:5px\"><% end%>\r\n  \r\n  </td>\r\n  </tr>\r\n<tr>\r\n  <td valign=\"top\" class=\"sidationcss\"><strong>Instrument</strong></td>\r\n  <td><%=render_value \'instrument\'%></td>\r\n  </tr>\r\n\r\n<tr>\r\n  <td valign=\"top\" class=\"sidationcss\"><strong>Anesthesiologist</strong></td>\r\n  <td><%=render_value \'anesthesiologist\'%></td>\r\n  </tr>\r\n<tr>\r\n  <td valign=\"top\" class=\"sidationcss\"><strong style=\"font-size:14px\">Type of Anesthesia</strong></td>\r\n  <td><%=render_value \'type_of_anesthesia\'%></td>\r\n  </tr>\r\n<tr>\r\n  <td valign=\"top\" class=\"sidationcss\"><strong>Medication</strong></td>\r\n  <td>\r\n  <div >\r\n  <% if record[\'propofol_mg\']!=\'\' %>Propofol <%=render_value \'propofol_mg\'%> IV,<% end%>\r\n  <% if record[\'dormicum_mg\']!=\'\' %>Dormicum <%=render_value \'dormicum_mg\'%> IV,<% end%>\r\n  <% if record[\'fentanyl_mg\']!=\'\' %>Fentanyl <%=render_value \'fentanyl_mg\'%> IV,<% end%>\r\n  <% if record[\'pethdine_mg\']!=\'\' %>Pethdine <%=render_value \'pethdine_mg\'%> IV,<% end%>\r\n  <% if record[\'hyoscine_mg\']!=\'\' %>Hyoscine <%=render_value \'hyoscine_mg\'%> IV,<% end%>\r\n  <% if record[\'etomidate_mg\']!=\'\' %>Etomidate <%=render_value \'etomidate_mg\'%> IV<% end%>\r\n  \r\n  </div>\r\n\r\n  \r\n  </td>\r\n  </tr>\r\n<tr>\r\n  <td valign=\"top\" class=\"sidationcss\"><strong>Indication</strong></td>\r\n  <td><%=render_value \'indication\'%></td>\r\n  </tr>\r\n<tr><td valign=\"top\" class=\"sidationcss\"><strong>Consent</strong></td><td colspan=\"2\"><%=render_value \'consent\'%></td>\r\n  </tr>\r\n<tr><td valign=\"top\" class=\"sidationcss\"><strong>Procedure</strong></td>\r\n  <td colspan=\"2\"><%=render_value \'procedure\'%></td>\r\n  </tr>\r\n</table>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n<div id=\"875-F8300752119\" class=\"  field\" style=\"clear:both;\">\r\n		<b class=\"sidationcss\">Findings</b>\r\n\r\n\r\n<%\r\n\r\n    templates = {}\r\n    \r\n    templates[\'Colonoscopy\'] = %w{ anal_canal rectum sigmoid_colon  descending_colon splenic_fixure transverse_colon hepatic_flexure ascending_colon cecum ileo_cecae_valve terminal_ileum colo_other}\r\n    \r\n    templates[\'Gastroscopy\'] = %w{ oropharynx esophagus eg_junction stomach_fundus cardia cardia_body antrum pylorus duodenum_buld two_part three_part gastro_other}\r\n\r\n    temp = templates[record[\'report_head\']]\r\n    temp = [] unless temp\r\n\r\n%>\r\n<table>\r\n    <% for i in temp \r\n        iv = record[i]\r\n        \r\n        iv = \'Normal\' if iv==\'\'\r\n    %>\r\n    <tr>\r\n    <th><div style=\"width:150px; float:left; margin-left:20px; color:#3C0; font-weight:bold\"><%=i.humanize%></div></th>\r\n        <td>\r\n            <%= iv%>\r\n        </td>\r\n    </tr>\r\n    <% end %>\r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n	\r\n    \r\n    	\r\n	</div>\r\n\r\n				\r\n\r\n\r\n\r\n<div id=\"diagnosis\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:650px;\">\r\n\r\n\r\n  <span class=\"sidationcss\"><strong>Diagnosis</strong></span><span class=\"\"><strong> :</strong>\r\n  </span>\r\n\r\n	<%=render_value \'colono_diagnosis_group\'%> <%=render_value \'diagnosis\'%>\r\n</div>\r\n\r\n						\r\n\r\n\r\n\r\n\r\n<div id=\"biopsy_for_pathology\" class=\"  portlet \" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n\r\n\r\n  <span class=\"sidationcss\"><strong>Biopsy for Pathology</strong></span><span class=\"\"><strong> :</strong>\r\n  </span>\r\n<%=render_value \'biopsy_for_pathology\'%>\r\n	\r\n</div>\r\n\r\n\r\n<div id=\"site_of_biopsy\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;\">\r\n\r\n\r\n<span class=\"\">\r\n<strong>At :</strong>\r\n</span>\r\n<%=render_value \'site_of_biopsy\'%>\r\n</div>\r\n\r\n\r\n<div id=\"therapeutic_procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:650px;\">\r\n\r\n\r\n  <span class=\"sidationcss\"><strong>Therapeutic Procedure</strong></span><span class=\"\"><strong> :</strong>\r\n  </span>\r\n<%=render_value \'therapeutic_procedure\'%>\r\n\r\n</div>\r\n\r\n\r\n						\r\n\r\n\r\n\r\n\r\n<div id=\"suggestion\" class=\"  portlet \" style=\"border:0px solid blue;width:600px;margin: 0 0.5em 0.5em 0;float:left;;\">\r\n\r\n\r\n<span class=\"sidationcss\"><strong>Suggestion</strong></span><strong> :</strong>\r\n<%=render_value \'suggestion\'%>\r\n	</div>\r\n\r\n	</div>\r\n				\r\n		\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<!-- <span style=\"float:right\">\r\n<strong>Reported by :</strong>&nbsp;<%=render_value \'recorder\'%><br />\r\n<strong>Printed Date Time :</strong>&nbsp;<%=render_value \'date_approve\' %> <%=render_value \'time_approve\'%>\r\n</span> -->&nbsp;<br />\r\n<span class=\"sidationcss\"><strong>Signature</strong> ...........................................................................\r\n</span><br />\r\n<!--\r\n<strong><% if record[\'approve\']!=\"\" %>Approved<% end %> By :</strong> \r\n<%=render_value \'endoscopist_approve\'%> (Gastroenterologist)\r\n -->\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n<div class=\"clear\">\r\n</div><br />\r\n <center>Samitivej Sukumvit Hospital 133 Sukumvit 49 Klong tan nua, Vadana, Bangkok 10110 Tel 02-7118822-24 , 02-7118000 Fax 02-7118833<br />\r\n โรงพยาบาลสมิติเวช สุขุมวิท 133 สุขุมวิท49 คลองตันเหนือ เขตวัฒนา กรุงเทพ 10110 โทร 02-7118822-24 , 02-7118000 แฟกซ์ 02-7118833\r\n     \r\n </center>\r\n\r\n\r\n</div>\r\n<script>\r\n\r\n<%\r\n        require \'csv\'\r\n        icd10_list = {}\r\n        CSV.foreach(File.join(Dir.pwd,\'public\',\'/esm/cusys/med/icd-10.csv\')) do |row|\r\n           icd10_list[row[0]]=row[1] \r\n        end\r\n        \r\n%>\r\n    \r\n    var icd10_list = <%=icd10_list.to_json.html_safe%>\r\n    icd = $(\'#data-icd10\').val()\r\n    licd = icd.split(\'|\')\r\n    div = $(\'#diagnosis-div\')\r\n    tr = div.parent().parent()\r\n    icd = $(\"<tr>\").append(\"<td><strong>ICD</strong></td>\")\r\n    for(var id in licd){\r\n        i = licd[id]\r\n        icd.append($(\'<p>\').append(\"<v>\"+i+\"</v> : \"+icd10_list[i]))\r\n        \r\n    }\r\n    tr.after(icd)\r\n    \r\n    \r\n    \r\n    \r\n</script>\r\n<script>\r\n   \r\n    $(document).ready(function() {\r\n        setTimeout(function(){\r\n        window.print()\r\n        },3000);\r\n    })\r\n    \r\n</script>\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2018-04-22 06:12:43','2018-04-22 06:12:43','print',''),(3461,'display',1370,3,'<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n<style>\r\n    .refinfo {padding:5px;width:720px; margin-left:auto; margin-right:auto}\r\n</style>\r\n <div class=\"refinfo\" >\r\n\r\nRef : <%= @patient_module.ref_number[0..9] if @patient_module.ref_number %> \r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<