</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-05-13 15:47:54','2018-05-13 15:47:54','edit',''),(3482,'document_name',1377,1,'\'post\'',NULL,NULL,NULL,'2018-05-16 08:18:42','2018-05-16 08:18:42',NULL,NULL),(3483,'document_name',1378,1,'\'member\'',NULL,NULL,NULL,'2018-05-16 09:04:50','2018-05-16 09:04:50',NULL,NULL),(3484,'detail',1292,2,'<style>\r\n\r\n</style>\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n    <h3 style=\"display:inline-block\">THKJR short version</h3>\r\n    \r\n    \r\n<div class=\"pull-right\" style=\"padding-top: 5px;\">\r\n<a class=\"btn btn-mini\" href=\"index\" id=\"search-btn\"> Back </a>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%\r\n    models = get_model\r\n    \r\n        operations = models[:operation].all.collect{|i|[i.id,i.name]}.to_h\r\n    diagnosis = models[:diagnosis].all.collect{|i|[i.id,i.name]}.to_h\r\n\r\n\r\n    records = models[:thk_record].where(:personal_id=>params[:id]).all\r\n    \r\n    records += models[:thk_record].where(:hn=>params[:id]).all\r\n    \r\n    if records.size>0 \r\n        last = records[0]\r\n%>\r\n<div class=\"alert alert-success\">\r\n    Personal ID : <%=last.personal_id%>\r\n    \r\n</div>\r\n\r\n<h3>Records : <i><%=\"last \\\\#{params[:day]} day(s)\" if params[:day]%></i> </h3>\r\n<table class=\"table table-bordered\" style=\"font-size:0.9em\" >\r\n	<thead>\r\n		<tr>\r\n			<th width=\"\" align=\"center\" valign=\"middle\">Date</th>\r\n	