ues = \"\"    \r\n        \r\n$.ajax({\r\n  url: \"finding_ajax\",\r\n  method: \"POST\",\r\n  data: { values : values, init:true },\r\n  cache: false\r\n})\r\n.done(function( html ) {\r\n\r\n    $( \"#findings\" ).html( html );\r\n});\r\n\r\n\r\nfunction change_scope(){\r\n   obj = $(\'#data-scope_pass_through\')\r\n   v = obj.val()\r\n   scopes = [\'colon_terminal_ileum\',\'colon_ileocecal_value\',\'colon_cecum\',\'colon_ascending_colon\',\'colon_transverse_colon\',\'colon_descending_colon\',\'colon_sigmoid_colon\',\'colon_rectum\',\'colon_anus\']\r\n   select_ix = scopes.indexOf(v)\r\n   \r\n\r\n   for(var ix in scopes){\r\n       i = scopes[ix]\r\n       id =parseInt(ix) +1\r\n    //   alert(\"\"+ix+\" \"+select_ix+\" \"+\'#p\'+id)\r\n       p = $(\'#p\'+id)\r\n       if(ix<select_ix){\r\n           p.parent().parent().hide()\r\n       }else{\r\n           p.parent().parent().show()\r\n       }\r\n   }\r\n}\r\n\r\n\r\n$(\'#data-scope_pass_through\').change(change_scope)\r\n\r\nchange_scope();\r\n\r\n\r\n}\r\n\r\n\r\n\r\n\r\n});\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<table width=\"600\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n  <td style=\"width:250px\" valign=\"top\"><strong>Type of sedation</strong></td>\r\n  <td width=\"365\" valign=\"top\">\r\n  <span id=\'type_of_sedation-div\' name=\'type_of_sedation\' class=\"report-field\" >...</span>\r\n  </td>\r\n  </tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Type of Drug</strong></td>\r\n  <td valign=\"top\">\r\n  <span id=\'anesthetic_drug_type-div\' name=\'anesthetic_drug_type\' class=\"report-field\" template=\"subtree\" >...</span>\r\n  </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Bowel preperation</strong></td>\r\n  <td valign=\"top\">\r\n  <!--<span id=\'bowel_preperation_finding-div\' name=\'bowel_preperation_finding\' class=\"report-field\"  >...</span>\r\n  LC:<span id=\'lc-div\' name=\'lc\' class=\"report-field\">-</span> \r\n  TC:<span id=\'tc-div\' name=\'tc\' class