d colon</strong></td>\r\n  <td valign=\"top\"><span id=\"p7\" ><v>Normal</v></span><br/>\r\n  </td>\r\n</tr>\r\n\r\n<tr>\r\n  <td valign=\"top\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Rectum</strong></td>\r\n  <td valign=\"top\"><span id=\"p8\"><v>Normal</v></span><br/>\r\n  </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Anus</strong></td>\r\n  <td valign=\"top\"><span id=\"p9\"><v>Normal</v></span><br/>\r\n  </td>\r\n</tr>\r\n\r\n<tr id=\"other-finding-panel\" style=\"display:none\">\r\n  <td valign=\"top\" class=\"digaw\"><strong>&nbsp;&nbsp;&nbsp;&nbsp;Other</strong></td>\r\n  <td valign=\"top\"><v><span id=\"other-finding-div\"></span></v><br/>\r\n  </td>\r\n</tr>\r\n\r\n\r\n<tr>\r\n  <td valign=\"top\"><strong>Diagnosis</strong></td>\r\n  <td valign=\"top\"><span id=\"diagnosis-div\">[Diagnosis]</span>\r\n  </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Intervention</strong></td>\r\n  <td valign=\"top\">\r\n  \r\n    <span id=\'operative_procedure-div\' name=\'operative_procedure\' class=\"report-field\" ></span>\r\n    <span id=\'intervention-div\'  >...</span>\r\n     \r\n  </td>\r\n</tr>\r\n\r\n<tr>\r\n  <td valign=\"top\"><strong>Complications</strong></td>\r\n  <td valign=\"top\">\r\n       <span id=\'complications-div\' name=\'complications\' class=\"report-field\" >No</span>\r\n\r\n       <span id=\'complication-div\' name=\'complication_type\' class=\"report-field\" template=\"subtree\"></span>\r\n         \r\n </td>\r\n</tr>\r\n<tr>\r\n  <td valign=\"top\"><strong>Comment</strong></td>\r\n  <td valign=\"top\">\r\n  \r\n       <span id=\'comment-div\' name=\'comment\' class=\"report-field-x\" >Loading..</span>\r\n\r\n </td>\r\n</tr>\r\n</table>\r\n\r\n<script>\r\n\r\n    \r\n       if (typeof(def_calculate) == \"undefined\"){\r\n         var def_calculate = 1 \r\n     \r\n    $(document).ready(function(){\r\n\r\n       function calculate(){\r\n            lc =  $(\'#data-lc\').val()\r\n            tc =  $(\'#data-tc\').val()\r\n            rc =  $(\'#data-rc\').val()\r\n            \r\n            if(lc==\'\')lc=\'0\'\r\n            if(tc==\'\')tc=\'0\'\r\n            if(rc==\'\')rc=\'0\'\r\n            \r\n            lc =  parseInt(lc);\r\n            tc =  parseInt(tc);\r\n            rc =  parseInt(rc);\r\n            s = lc+tc+rc;\r\n            \r\n            $(\'#data-bbps\').val(s);\r\n             cupdate();\r\n             $(\'#data-bowel_preperation_finding\').val(\'1\');\r\n             \r\n            v = {0:\'3\',1:\'3\',2:\'3\',3:\'2\',4:\'2\',5:\'2\',6:\'2\',7:\'1\',8:\'1\',9:\'0\'}\r\n            va = v[s];\r\n            $(\'#update_bowel_preperation_finding_item_\'+va).attr(\'checked\', \'checked\');\r\n            \r\n            update_bowel_preperation_finding_func();\r\n             \r\n            \r\n            \r\n       }\r\n       \r\n       $(\'#data-lc\').change(calculate);\r\n        \r\n        $(\'#data-tc\').change(calculate);\r\n        \r\n        $(\'#data-rc\').change(calculate);\r\n        \r\n        function cupdate(){\r\n            $(\'#bbps-div\').html($(\'#data-bbps\').val())\r\n        }\r\n        \r\n        $(\'#data-bbps\').change(cupdate);    \r\n        $(document).ready(function(){\r\n      $(\'#bbps-div\').html($(\'#data-bbps\').val())\r\n      });\r\n    \r\n      \r\n    });\r\n    \r\n    $(\'#bowel_preperation_finding\').hide();\r\n    \r\n       }\r\n</script>\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-05-21 03:05:26','2018-05-21 03:05:26','display_script',''),(3489,'finding_config',1379,1,'{\r\n:name=>\'EUS\',\r\n:order=>[:location,:disease,:procedure],\r\n:models=>{:location=>[\'location\',\'location_tag\',\'single\'],:disease=>[\'disease\',\'disease_tag\',\'single\'],:procedure=>[\'procedure\',\'procedure_tag\',\'multitple\']},\r\n:first_level=>[:location,:disease],\r\n:selectors=>{:location=>%w{esophagus stomach duodenum}},\r\n:view_organized_by=>:location,\r\n:view=>[\r\n    {   :title=>\'Esophagus\',\r\n        :valu