e)\r\n    });\r\n    \r\n    \r\n    $(\'#data-endoscopist\').change(function(){\r\n        \r\n        var value = $(this).val()\r\n    \r\n        $(\'#data-recorder\').val(value)\r\n        $(\'#data-endoscopist_approve\').val(value)\r\n            \r\n    });\r\n    \r\n \r\n  $(\'#findings\').css(\'display\',\'none\')\r\n    \r\n    // alert(icd10_list)\r\n    \r\n    \r\n</script>\r\n\r\n',NULL,NULL,NULL,'2018-05-21 03:08:05','2018-05-21 03:08:05','finding_ajax','*'),(3491,'context_menu',1356,4,'<%\r\nreturn_url = \'\'\r\nreturn_url = \"&return=\\\\#{params[:return]}\" if params[:return]\r\nname = this.document_name.humanize\r\nlist = [{:name=>\'List\',:link=>\'index\',:remote=>false},{:name=>\'Create \'+name,:link=>\'create\',:remote=>false}]\r\nif params[:id]\r\nlist<<{:name=>\'Edit\',:link=>\"edit?id=\\\\#{params[:id]}\\\\#{return_url}\",:remote=>false}\r\nlist<<{:name=>\'Delete\',:link=>\"destroy?id=\\\\#{params[:id]}\",:remote=>false}\r\nend\r\nlist<<{:name=>\'Back to Home\',:link=>\"../Home/index\",:remote=>false}\r\nmenus = [{:name=>this.document_name.humanize,:open=>true,:actions=>list}] \r\n\r\n\r\nmenus << {:name=>\'Departments\', :open=>true, :actions=> get_model(\'department\').all.collect{|i| {:name=>i.name ,:link=>\"index?department=\\\\#{i.id}\",:remote=>false} } }\r\n\r\n\r\n\r\n\r\n%>\r\n<%= show_menu menus\r\n%>\r\n',NULL,NULL,NULL,'2018-05-21 04:15:59','2018-05-21 04:15:59','context_menu',''),(3492,'index',1356,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n     