   \r\n       \r\n    end\r\n%>\r\n<div class=\"alert\">Upldated..</div>\r\n<%# params.inspect %>\r\n<% end %>\r\n\r\n\r\n<%\r\n    \r\n    items = models[:pl_period_product].where(:sheet_id=>sheet.id).sort(:sort_order).all\r\n    \r\n    m_products = Hash[models[:pl_product].find(items.collect{|i| i.product_id}).map{|i| [i.id,i] }]\r\n    \r\n    periods = models[:pl_period].where(:sheet_id=>sheet.id).sort(:sort_order).all\r\n    \r\n    %>\r\n    \r\n<%=form_for :protocol, :url=>\"sort_protocol?id=\\\\#{params[:id]}&update=panel\", :data=>{:remote=>true} do |f|  %>\r\n\r\n\r\n  <script>\r\n  $( function() {\r\n    $( \"#sortable-1\" ).sortable();\r\n    $( \"#sortable-1\" ).disableSelection();\r\n    $( \"#sortable-2\" ).sortable();\r\n    $( \"#sortable-2\" ).disableSelection();\r\n  } );\r\n  </script>\r\n\r\n<h3>Products</h3>\r\n<ul id=\"sortable-1\">\r\n  <% for i in items \r\n    p = m_products[i.product_id] \r\n  %>\r\n  <li class=\"ui-state-default\"> <%=i.sort_order%> : <span class=\"ui-icon ui-icon-arrowthick-2-n-s\"></span><%= p.name %>  (<%=p.code%>) - <%= i.detail %> <%=hidden_field_tag \"products[]\", i.id %> </li>\r\n  <% end %>\r\n</ul>\r\n \r\n <h3>Periods</h3>\r\n <ul id=\"sortable-2\">\r\n  <% for i in periods \r\n   \r\n  %>\r\n  <li class=\"ui-state-default\"><%=hidden_field_tag \"visits[]\", i.id %><%=i.sort_order%> : Visit <span class=\"ui-icon ui-icon-arrowthick-2-n-s\"></span><%=text_field_tag \"visits_name[]\",  i.visit ,:style=>\'width:50px\' %>  Day : <%=text_field_tag \"visits_day[]\",  i.day ,:style=>\'width:50px\' %>  </li>\r\n  <% end %>\r\n</ul>\r\n\r\n\r\n<%= f.submit \"Submit\", :class=>\"btn btn-success\"%> | <%=link_to \'Back\',\"edit_protocol?id=\\\\#{params[:id]}&update=panel\", :class=>\'btn\', :data=>{:disable_with=>\'Loading..\',:remote=>true} %> \r\n\r\n\r\n\r\n\r\n <% end %>',NULL,NULL,NULL,'2018-06-06 06:34:17','2018-06-06 06:34:17','sort_protocol',''),(3505,'document_name',1383,1,'\'patient\'',NULL,NULL,NULL,'2018-06-06