rams[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n<script>\r\n    $(\'.admin\').hide();\r\n</script>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-06-06 16:19:04','2018-06-06 16:19:04','create',''),(3511,'patient',1278,3,'<%\r\n    models = get_model\r\n\r\n    project = models[:project].find params[:id]\r\n    \r\n    patients = models[:patient].where(:project_id=>project.id).all\r\n    \r\n    \r\n%>\r\n \r\n \r\n\r\n\r\n<div class=\"row-fluid\">\r\n    \r\n<div class=\"span12 tac\">\r\n							<ul class=\"ov_boxes\">\r\n							\r\n									<li>\r\n									<div class=\"p_bar_up p_canvas\" style=\"font-size:1.8em;padding-top:15px\"><%=patients.size%><br/>\r\n									  <span style=\"font-size:0.5em\">Subjects</span>\r\n									  </div>\r\n									<div class=\"ov_text\">\r\n										<strong style=\"\"></strong>\r\n										Total Number of Subjects \r\n									</div>\r\n								</li>\r\n							<%\r\n							\r\n							\r\n							    cta_doc = models[:project_document].where(:document_name=>\'clinical_trial_agreement\',:project_id=>project.id).first\r\n							    \r\n							    if cta_doc and cta = models[:clinical_trial_agreement].find(cta_doc.document_id)\r\n							    \r\n							    number_of_failure  =  patients.collect{|i| i if i.status and  i.status==\'SCF\'}.compact.size\r\n							    ratio = \'-\'\r\n							    \r\n							    ratio = \"\\\\#{format(\'%.2f\',number_of_failure.to_f/patients.size*100)}%\" if patients.size>0\r\n							    \r\n							    \r\n							    \r\n							    \r\n							%>\r\n								<li>\r\n									<div class=\"p_bar_up p_canvas\" style=\"font-size:1.8em;padding-top:15px\"><%=number_of_failure%><br/>\r\n									  <span style=\"font-size:0.5em\">Patients</span>\r\n									  </div>\r\n									<div class=\"ov_text\">\r\n										<strong style=\"color:red\"><%=ratio%> ( <%= cta.screening_failure_ratio %> ) </strong>\r\n										<%= cta.screening_failure_note %>\r\n									</div>\r\n								</li>\r\n						   <% end %>\r\n						   \r\n						   \r\n						   <% if project.recruitment_end %>\r\n								<li>\r\n									<div class=\"p_bar_down p_canvas\" style=\"font-size:1.8em;padding-top:15px\"> <%= (project.recruitment_end.to_datetime.to_i - Time.now.to_i)/3600/24%><br/>\r\n									    <span style=\"font-size:0.5em\">Days</span>\r\n									</div>\r\n									<div class=\"ov_text\">\r\n										<strong style=\"color:blue\"><%=project.recruitment_end.strftime(\'%d/%m/%Y\')%></strong>\r\n										End of Recruitment Date\r\n									</div>\r\n								</li>\r\n						   <% end %>\r\n\r\n\r\n						   <% if project.end_of_study %>\r\n\r\n\r\n								<li>\r\n								    <div class=\"p_bar_down p_canvas\" style=\"font-size:1.8em;padding-top:15px\"> <%= (project.end_of_study.to_datetime.to_i - Time.now.to_i)/3600/24%><br/>\r\n									    <span style=\"font-size:0.5em\">Days</span>\r\n									</div>\r\n									<div class=\"ov_text\">\r\n										<strong style=\"color:blue\"><%=project.end_of_study.strftime(\'%d/%m/%Y\')%></strong>\r\n										End of Study Date\r\n\r\n									</div>\r\n								</li>\r\n							 <% end %>\r\n\r\n\r\n							</ul>\r\n						</div>\r\n    \r\n</div>\r\n\r\n<%\r\n\r\n    fpatients = patients.collect{|i| i if i.status==\'SCF\' }.compact\r\n    patients = patients.collect{|i| i if i.status!=\'SCF\' }.compact\r\n    \r\n\r\n%>\r\n\r\n\r\n<h3>Today Schedule</h3>\r\n\r\n\r\n\r\n\r\n<table class=\"table \">\r\n<thead>\r\n    <tr><th>No.</th>\r\n        <th>Sub #</th>\r\n        <th>HN</th>\r\n        <th>Name</th>\r\n        <th>Initial</th>\r\n        <th>Gender</th>\r\n        <th>Age</th>\r\n        <th>Status</th>\r\n        <th>Protocol Version</th>\r\n        <th>Today Visit</th>\r\n        <th>Schedule</th>\r\n    </tr>\r\n</thead>\r\n<tbody>\r\n    \r\n  <% \r\n    visit_count = 0 \r\n    patients.each_with_index do |i,index| \r\n \r\n     visit = models[:visit].where(:patient_id=>i.id, :date=>{\'$gte\'=>Time.now.beginning_of_day,\'$lte\'=>Time.now.end_of_day}).sort(:date.desc).first  \r\n  \r\n     \r\n     if visit\r\n         visit_count+=1\r\n         period = models[:pl_period].find visit.period_id\r\n         \r\n         s = models[:pl_sheet].find visit.sheet_id\r\n         \r\n         status = \'btn-success\'\r\n         status = \'\' if visit.status==\'Completed\'\r\n        \r\n  %>\r\n\r\n    <tr>\r\n        <td>\r\n            <%=index+1%>.\r\n        </td>\r\n            <td><%=link_to i.subject_id, \"../Patient/show?id=\\\\#{i.id}\" %></td>\r\n\r\n\r\n            <td>\r\n            <%=link_to i.hn, \"../Patient/show?id=\\\\#{i.id}\" %>\r\n\r\n\r\n        </td>\r\n           <td>\r\n            <%=link_to \"\\\\#{i.prefix_name}\\\\#{i.first_name} \\\\#{i.last_name} \" , \"../Patient/show?id=\\\\#{i.id}\" %>\r\n\r\n\r\n\r\n        </td>\r\n           <td>\r\n            <%=link_to \" \\\\#{i.subject_initial}\" , \"../Patient/show?id=\\\\#{i.id}\" %>\r\n\r\n\r\n\r\n        </td>\r\n        <td>\r\n            <%= i.gender%>\r\n        </td>\r\n        <td>\r\n           <%= ((Time.now - i.birth_date.to_datetime)/(3600*24*365)).to_i if i.birth_date%>\r\n        </td>\r\n        <td><%= i.status %></td>\r\n        <td><%= s.version if s%></td>\r\n        \r\n        <td><%= link_to  \"\\\\#{visit.name} : \\\\#{visit.date.strftime(\'%d/%m/%y\')}\", \"../Visit/show?id=\\\\#{visit.id}\",:class=>\'btn \'+status  %></td>\r\n        \r\n        <%\r\n            \r\n        %>\r\n        <td></td>\r\n    </tr>\r\n    <% end %>\r\n    \r\n    <% end %>\r\n   \r\n    <% if visit_count==0 %>\r\n     <tr><td colspan=\"10\" class=\"alert alert-success\"><center>No Today Patient</center></td></tr>\r\n    <% end %>\r\n    \r\n    \r\n</tbody>\r\n    \r\n</table>\r\n<br/>\r\n\r\n\r\n <% \r\n \r\n    groups = {}\r\n    gmap = {}\r\n    \r\n    eos_list = []\r\n    eot_list = []\r\n    \r\n    unschedule = []\r\n    \r\n    \r\n    # patient arm by last or first visit for arm detection\r\n    # next visit\r\n    \r\n \r\n patients.each_with_index do |i,index|  \r\n    \r\n        period = nil\r\n        \r\n        \r\n        \r\n        # last visit \r\n        \r\n        visit = models[:visit].where(:patient_id=>i.id).sort(:date.desc).first  \r\n        \r\n        last_visit = models[:visit].where(:patient_id=>i.id,:date=>{\'$lte\'=>Time.now.end_of_day}).sort(:date.desc).first   \r\n        \r\n        next_visit = models[:visit].where(:patient_id=>i.id,:date=>{\'$gte\'=>Time.now.end_of_day}).sort(:date).first  \r\n        \r\n        visit = last_visit if last_visit\r\n        \r\n        \r\n        \r\n        if visit \r\n        \r\n            period = models[:pl_period].find visit.period_id\r\n            patient = models[:patient].find visit.patient_id\r\n            s = models[:pl_sheet].find visit.sheet_id\r\n            s = models[:pl_sheet].find patient.sheet_id unless s\r\n            \r\n            \r\n            unless s \r\n            \r\n            if patient\r\n            v = models[:visit].where(:patient_id=>patient.id, :sheet_id=>{\'$ne\'=>nil}).first\r\n            s = models[:pl_sheet].find v.sheet_id\r\n            end\r\n            \r\n        \r\n            end\r\n            \r\n            if s\r\n\r\n            \r\n            groups[s.id] = [] unless groups[s.id]\r\n            \r\n            groups[s.id] << [s, i, visit, period, next_visit]\r\n            \r\n            gmap[s.id] = s\r\n            \r\n        else\r\n            %>\r\n            <%= link_to \'Patient unschedule\',\"../Patient/show?id=\\\\#{patient.id}\" %>\r\n            <%\r\n            visit.destroy\r\n            # patient.update_attributes :status=>\'ACT\'\r\n        end\r\n        \r\n        elsif i.status==\'EOS\'\r\n        \r\n            eos_list << i \r\n        elsif i.status==\'EOT\'\r\n            eot_list << i \r\n        else\r\n            unschedule << i \r\n        end    \r\n        \r\n\r\nend\r\n    \r\n%>\r\n\r\n<% \r\n\r\n\r\ngroups.each_pair do |g,list|\r\n\r\n if cookies[:sort]\r\n    \r\n    list = list.sort_by do |i|\r\n       \r\n       case cookies[:sort]\r\n       when \'name\'\r\n        i[1].first_name \r\n        when \'subject_id\'\r\n        i[1].subject_id\r\n        when \'hn\'\r\n        i[1].hn\r\n        when \'gender\'\r\n        i[1].gender\r\n        when \'age\'\r\n        i[1].birth_date\r\n    end\r\n        \r\n    end\r\n     \r\n     \r\n end\r\n\r\n\r\n%>\r\n\r\n\r\n<%=cookies[:sort]  %>\r\n\r\n<h3>Patient List in Protocol Version : <%=gmap[g].version%></h3>\r\n\r\n\r\n<table class=\"table table-striped table-bordered \">\r\n<thead>\r\n    <tr><th>No.</th>\r\n        <th sort=\'subject_id\'>Sub # <i class=\"splashy-arrow_state_grey_expanded\"></i></th>\r\n        <th sort=\'hn\' >HN <i class=\"splashy-arrow_state_grey_expanded\"></i></th>\r\n        <th sort=\'name\'>Name <i class=\"splashy-arrow_state_grey_expanded\"></i></th>\r\n        <th sort=\'initial\'>Initial <i class=\"splashy-arrow_state_grey_expanded\"></i></th>\r\n        <th sort=\'gender\'>Gender <i class=\"splashy-arrow_state_grey_expanded\"></i></th>\r\n        <th sort=\'age\'>Age <i class=\"splashy-arrow_state_grey_expanded\"></i></th>\r\n        <th>Status</th>\r\n\r\n\r\n        <th>Protocol Version</th>\r\n        <th>Last Visit</th>\r\n        <th>Next Visit</th>\r\n        \r\n    </tr>\r\n</thead>\r\n<tbody>\r\n    \r\n<% list.each_with_index do |x,index| \r\n    \r\n    s = x[0]\r\n    i = x[1]\r\n    visit= x[2]\r\n    period = x[3]\r\n    next_visit = x[4]\r\n    \r\n    status = \'btn-success\'\r\n    status = \'\' if visit and visit.status==\'Completed\' \r\n        \r\n%>\r\n   \r\n\r\n    <tr>\r\n        <td>\r\n            <%=index+1%>.\r\n        </td>\r\n        <td>\r\n            <%=link_to i.subject_id, \"../Patient/show?id=\\\\#{i.id}\" %>\r\n        </td>\r\n        <td>\r\n            <%=link_to i.hn, \"../Patient/show?id=\\\\#{i.id}\" %>\r\n\r\n\r\n        </td>\r\n           <td>\r\n            <%=link_to \"\\\\#{i.prefix_name}\\\\#{i.first_name} \\\\#{i.last_name} \\\\#{i.subject_initial}\" , \"../Patient/show?id=\\\\#{i.id}\" %>\r\n\r\n\r\n        </td>\r\n        \r\n              <td>\r\n            <%=link_to \"\\\\#{i.subject_initial}\" , \"../Patient/show?id=\\\\#{i.id}\" %>\r\n\r\n\r\n        </td>\r\n            <td>\r\n            <%= i.gender%>\r\n        </td>\r\n        <td>\r\n           <%= ((Time.now - i.birth_date.to_datetime)/(3600*24*365)).to_i if i.birth_date%>\r\n        </td>\r\n        \r\n          <td>\r\n            <%=select_tag  :status, options_for_select(%w{ACT EOT EOS SCF},i.status ) ,:style=>\'width:60px\',:class=>\'patient_status\', :pid=>i.id, :include_blank=>true%>\r\n\r\n        </td>\r\n        <td>\r\n            <%= s.version %>\r\n        </td>\r\n        <td>\r\n        <% if visit %>\r\n            <%= link_to  \"\\\\#{visit.name} : \\\\#{visit.date.strftime(\'%d/%m/%y\')}\", \"../Visit/show?id=\\\\#{visit.id}&return=../Project/show?id=\\\\#{params[:id]}\",:class=>\'btn btn-mini \'+status if visit %>\r\n            - <%= distance_of_time_in_words visit.date, Time.now %>\r\n\r\n\r\n        <% else %>\r\n            <%# link_to  \"Screening\", \"../Visit/create?project_id=\\\\#{project.id}&patient_id=\\\\#{i.id}\",:class=>\'btn\' %>\r\n        <% end %>\r\n        </td>\r\n        \r\n        <td>\r\n            <%\r\n            if next_visit\r\n                period = models[:pl_period].find next_visit.period_id\r\n                s = models[:pl_sheet].find period.sheet_id if period\r\n            %>\r\n            <%= link_to  \"\\\\#{period.visit if period} : \\\\#{next_visit.date.strftime(\'%d/%m/%y\')}\", \"../Visit/show?id=\\\\#{next_visit.id}&return=../Project/show?id=\\\\#{params[:id]}\",:class=>\'btn btn-mini \' if next_visit %>\r\n            + <%= distance_of_time_in_words next_visit.date, Time.now %>\r\n            <% else %>\r\n            \r\n            <%# link_to  \"+Visit\", \"../Patient/show?id=\\\\#{i.id}&schedule=1\" ,:class=>\'btn btn-mini btn-info\' %>\r\n            \r\n            <% end %>\r\n        </td>\r\n        \r\n      \r\n        \r\n        \r\n    </tr>\r\n    \r\n    <% end %>\r\n</tbody>\r\n    \r\n</table>\r\n    <% end %>\r\n    <hr/>\r\n<%\r\n    \r\n  if unschedule.size>0  or eos_list.size>0 or fpatients.size>0 or eot_list.size > 0 \r\n      \r\n      \r\n      \r\n      m = {\'unschedule\'=>\'New Patient List (Screening)\',\'eot\'=>\'End of Treatment Patient List (EOT)\',\'eos\'=>\'End of Study Patient List (EOS)\', \'scf\'=>\'Screen Failure Patient List (SCF)\'}\r\n      \r\n      \r\n    m.each_pair do |k,label|\r\n        \r\n        list = []\r\n        list = unschedule if k==\'unschedule\'\r\n        list = eot_list if k==\'eot\'\r\n        list = eos_list if k==\'eos\'\r\n        list = fpatients if k==\'scf\'\r\n    \r\n%>\r\n    \r\n<h4><%=label%></h4>\r\n\r\n\r\n<table class=\" itable table table-striped table-bordered table-condensed\">\r\n<thead>\r\n    <tr><th>No.</th>\r\n        <th>Sub #</th>\r\n        <th>HN</th>\r\n        <th>Name</th>\r\n        <th>Initial</th>\r\n        \r\n        <th>Gender</th>\r\n        <th>Age</th>\r\n        <th>Status</th>\r\n        <th></th>\r\n\r\n\r\n       \r\n    </tr>\r\n</thead>\r\n<tbody>\r\n    \r\n  <% list.each_with_index do |i,index| \r\n  \r\n        \r\n  %>\r\n\r\n       <tr>\r\n        <td>\r\n            <%=index+1%>.\r\n        </td>\r\n            <td>\r\n            <%=link_to i.subject_id, \"../Patient/show?id=\\\\#{i.id}\" %>\r\n\r\n\r\n        </td>\r\n          <td>\r\n            <%=link_to i.hn, \"../Patient/show?id=\\\\#{i.id}\" %>\r\n\r\n\r\n        </td>\r\n           <td>\r\n            <%=link_to \"\\\\#{i.prefix_name}\\\\#{i.first_name} \\\\#{i.last_name}\" , \"../Patient/show?id=\\\\#{i.id}\" %>\r\n\r\n\r\n        </td>\r\n           <td>\r\n            <%=link_to \"\\\\#{i.subject_initial}\" , \"../Patient/show?id=\\\\#{i.id}\" %>\r\n\r\n\r\n        </td>\r\n        <td>\r\n            <%= i.gender%>\r\n        </td>\r\n        <td>\r\n           <%= ((Time.now - i.birth_date.to_datetime)/(3600*24*365)).to_i if i.birth_date%>\r\n        </td>\r\n        <td>\r\n            <%=select_tag  :status, options_for_select(%w{ACT EOT EOS SCF},i.status ) ,:style=>\'width:80px\',:class=>\'patient_status\', :pid=>i.id %>\r\n        </td>\r\n       \r\n       <td>\r\n            <% if k==\'unschedule\' %>\r\n            <%= link_to \'+Visit\', \"#\", :class=>\'btn btn-info randomize_btn\', :patient_id=>i.id,:patient_name=>\"\\\\#{i.prefix_name}\\\\#{i.first_name} \\\\#{i.last_name} \\\\#{i.subject_initial}\"%>\r\n            <% end %>\r\n            \r\n           \r\n       </td>\r\n        \r\n      \r\n   \r\n    </tr>\r\n    \r\n    <% end %>\r\n</tbody>\r\n    \r\n</table>\r\n<br/><br/>\r\n   <% end %>\r\n   \r\n     <% end %>\r\n   \r\n\r\n   \r\n<!-- Randomize -->\r\n\r\n<div class=\"modal hide \" id=\"modal-randomize\" aria-hidden=\"false\" style=\"display: none;\">\r\n	<div class=\"modal-header\">\r\n		<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n		<h3>Randomize</h3>\r\n	</div>\r\n	<%= form_for :randomize, :url=>\"process_patient?id=\\\\#{params[:id]}\" do |f| %>\r\n	<div class=\"modal-body\">\r\n        \r\n        <%=f.hidden_field :project_id, :value=>project.id %>\r\n        \r\n	    <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Patient :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	            <span id=\"randomize_patient_name\" ></span>\r\n	            <%=f.hidden_field :patient_id,:value=>nil %>\r\n	        </div>\r\n	    </div>\r\n	    \r\n	   <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Screening No :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	      \r\n	        <%=text_field_tag  :patient_screening_no %><i> # N/A leave blank</i>\r\n	        </div>\r\n	    </div>\r\n	    <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Subject ID :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	      \r\n	        <%=text_field_tag  :patient_subject_id %><i> # N/A leave blank</i>\r\n	        </div>\r\n	    </div>\r\n	    \r\n           <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Visit Type :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	        Schedule\r\n        <%=f.hidden_field :visit_type, :value=>\'1\' %>\r\n\r\n	        </div>\r\n	    </div>\r\n	    \r\n	    \r\n	         <%\r\n	            \r\n	            docs = models[:project_document].where(:document_name=>\'pl_sheet\',:project_id=>project.id).all\r\n	            sheets = models[:pl_sheet].find(docs.collect{|i| i.document_id })\r\n	        %>\r\n	        \r\n	        \r\n      \r\n       \r\n        <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Visit :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	        \r\n	        <%\r\n	            msheets = Hash[sheets.collect{|i| [i.id,i]}]\r\n	            \r\n	            periods = models[:pl_period].where(:sheet_id=>{\'$in\'=>sheets.collect{|i| i.id}}).all.collect{|i| \r\n	                 \r\n	                 s = msheets[i.sheet_id]\r\n	               \r\n	                 [i.visit, i.id, s.id, i.day, \"\\\\#{s.version} : \\\\#{i.visit} : \\\\#{i.day}D \" ]\r\n	            \r\n	            }\r\n	            \r\n	           \r\n	        %>\r\n	       \r\n	        <%=f.select :period_id, options_for_select(periods.collect{|i| [i[-1],i[1]] }),:include_blank=>true  %>\r\n	        \r\n	       \r\n	        </div>\r\n	    </div>\r\n	    \r\n	      <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Protocol Version :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	   \r\n	        <%=f.select :sheet_id, options_for_select(sheets.collect{|i| [i.version,i.id]}),:include_blank=>true %>\r\n	        </div>\r\n	    </div>\r\n       \r\n        <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Visit Name :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	      \r\n	        <%=f.text_field  :name %>\r\n	        </div>\r\n	    </div>\r\n       \r\n           <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Date :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	      \r\n	        <%=f.text_field  :date %>\r\n	        </div>\r\n	        \r\n	        \r\n	        \r\n	    </div>\r\n       \r\n       <script>\r\n    \r\n    \r\n    \r\n    $(\"#randomize_date\").kendoDatePicker({\r\n		value: \'<%=Time.now.strftime(\"%d/%m/%Y\")%>\',\r\n	});\r\n	\r\n	$(\"#randomize_date\").change(function(){\r\n		obj = $(this)\r\n		v = obj.val()\r\n		if(v.length>0){\r\n		s = v.split(\"/\")\r\n		y = parseInt(s[2])\r\n		if(y>2200)\r\n		y = y-543\r\n		\r\n		d = new Date(y,parseInt(s[1]-1),parseInt(s[0]))\r\n		obj.val(\"\"+parseInt(s[0])+\"/\"+parseInt(s[1])+\"/\"+y)\r\n		}\r\n	});\r\n           var periods = <%=periods.to_json.html_safe%>\r\n           \r\n           $(\'#randomize_period_id\').change(function(){\r\n               \r\n               v = $(this).val();\r\n             \r\n               for(var ix in periods){\r\n                   i = periods[ix];\r\n                   if(i[1]==v){\r\n                       $(\'#randomize_sheet_id\').val(i[2]);\r\n                       $(\'#randomize_name\').val(i[0]);\r\n                       \r\n                       day = parseInt(i[3]);\r\n                       s =  $(\'#randomize_date\').val().split(\"/\")\r\n                       d = new Date(parseInt(s[2]),parseInt(s[1]),parseInt(s[0]))\r\n                       \r\n                       d.setDate(d.getDate() + day)\r\n                       t = \"\"+d.getDate()+\"/\"+d.getMonth()+\"/\"+d.getFullYear()\r\n                      \r\n                       $(\'#randomize_date\').val(t);\r\n                   }\r\n                   \r\n               }\r\n               \r\n           })\r\n           \r\n           \r\n           $(\'.randomize_btn\').click(function(){\r\n               \r\n               v = $(this).attr(\'patient_id\')\r\n               name = $(this).attr(\'patient_name\')\r\n               $(\'#randomize_patient_id\').val(v)\r\n               $(\'#randomize_patient_name\').html(name)\r\n               $(\'#modal-randomize\').modal();\r\n               \r\n           })\r\n           \r\n       </script>\r\n       \r\n      	</div> \r\n        		<div class=\"modal-footer\">\r\n		<%=f.submit \'Submit\', :class=>\'btn btn-success\'%>\r\n		<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n	</div>\r\n	<% end %>\r\n</div>\r\n   \r\n<!-- Change Status -->\r\n\r\n<div class=\"modal hide \" id=\"modal-randomize\" aria-hidden=\"false\" style=\"display: none;\">\r\n	<div class=\"modal-header\">\r\n		<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n		<h3>Change Status</h3>\r\n	</div>\r\n	<div class=\"modal-body\">\r\n    \r\n    Change Status\r\n\r\n	</div>\r\n	<div class=\"modal-footer\">\r\n		<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n	</div>\r\n</div>\r\n<style>\r\n    .itable td{\r\n        \r\n        width:100px;\r\n        \r\n    }\r\n</style>\r\n<script>\r\n    $(\'th\').each(function(){\r\n        t = $(this)\r\n        if(t.attr(\'sort\')){\r\n            t.click(function(){\r\n                $.cookie(\"sort\",$(this).attr(\'sort\'),{ expires : 1 });\r\n                location.reload()\r\n            })\r\n           \r\n        }\r\n    })\r\n    $(\'.patient_status\').change(function(){\r\n        pid = $(this).attr(\'pid\')\r\n        status = $(this).val()\r\n        window.location.replace(\"patient_status?id=<%=params[:id]%>&patient_id=\"+pid+\"&status=\"+status);\r\n    })\r\n</script>\r\n   ',NULL,NULL,NULL,'2018-06-06 16:49:27','2018-06-06 16:49:27','patient',''),(3512,'show',1385,2,'<%\r\n\r\n    record = get_model(\'visit\').find params[:id]\r\n\r\n    return_url = \"../Patient/show?id=\\\\#{record.patient_id}\"\r\n    \r\n\r\n\r\n    models = get_model\r\n    \r\n    project = models[:project].find record.project_id\r\n    visit = record\r\n    patient = models[:patient].find record.patient_id\r\n    \r\n    protocol_version = \'-\'\r\n    sheet = models[:pl_sheet].find patient.sheet_id\r\n    if sheet\r\n        protocol_version = sheet.version    \r\n    end\r\n    \r\n\r\n   \r\n%>\r\n    <div id=\"jCrumbs\" class=\"breadCrumb module\">\r\n        <div style=\"overflow:hidden; position:relative; width: 1316px;\"><div><ul style=\"width: 500px;\">\r\n            <li class=\"first\">\r\n                <a href=\"../Home/index\"><i class=\"icon-home\"></i></a>\r\n            </li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Project/index\" style=\"width: 84px;\">Projects</a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Project/show?id=<%=project.id%>\" style=\"width: 94px;\"><%=project.protocol_no%></a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Project/show?id=<%=project.id if sheet%>\" style=\"width: 134px;\"><%=protocol_version%></a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Patient/show?id=<%=patient.id%>\" style=\"width: 134px;\"><%=patient.subject_id%> <%=patient.first_name%> <%=patient.last_name%></a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li class=\"last\" style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n               <%=visit.name%>\r\n            </li>\r\n        </ul></div></div>\r\n    </div>\r\n</nav>\r\n\r\n\r\n<style>\r\nv{\r\n      color:blue;\r\n  }\r\n</style>\r\n<table class=\"table table-striped table-bordered table-condensed\">\r\n<tr>\r\n\r\n    <td>\r\n        <b>Subject ID : </b><v><%=patient.subject_id%></v>\r\n    </td>\r\n\r\n\r\n    <td>\r\n        <b>HN : </b><v><%=patient.hn%></v>\r\n    </td>\r\n\r\n    <td>\r\n        <b>Patient Name : </b><v><%=patient.prefix_name%><%=patient.first_name%> <%=patient.last_name%></v>\r\n    </td>\r\n    <td>\r\n        <b>Gender : </b><v><%=patient.gender%></v>\r\n    </td>\r\n    <td>\r\n        <b>Age : </b><v><%=((record.date - patient.birth_date.to_datetime)/(3600*24*365)).to_i if record.date and patient and patient.birth_date%> ปี</v>\r\n    </td>\r\n    \r\n    \r\n</tr>    \r\n</table>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%# link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Work List\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Laboratory Order\'.html_safe, \"print_lab?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n\r\n\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"\" style=\"border:0px solid\">\r\n\r\n<%= this.display.html_safe %><br/>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-06-06 17:12:19','2018-06-06 17:12:19','show',''),(3513,'display',1385,3,'\r\n<%\r\n  models = get_model\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  \r\n  project = models[:project].find(record.project_id)\r\n  sheet = models[:pl_sheet].find(record.sheet_id)\r\n  \r\n  patient = models[:patient].find(record.patient_id)\r\n\r\n\r\n  \r\n   sheet = models[:pl_sheet].find patient.sheet_id unless sheet\r\n            \r\n    unless sheet \r\n        \r\n     visit = models[:visit].where(:patient_id=>patient.id, :sheet_id=>{\'$ne\'=>nil}).first\r\n     sheet = models[:pl_sheet].find visit.sheet_id\r\n     visit = nil\r\n    \r\n    end\r\n  \r\n  \r\n  period = models[:pl_period].find(record.period_id)\r\n  \r\n  period_items = []\r\n  period_items  = models[:pl_period_product].where(:sheet_id=>sheet.id).order(:sort_order).all if sheet\r\n  \r\n  m_products = Hash[models[:pl_product].find(period_items.compact.collect{|i| i.product_id}).map{|i| [i.id, i]}]\r\n  items = []\r\n  items  = models[:pl_period_item].where(:sheet_id=>sheet.id, :period_id=>period.id).all if sheet and period\r\n\r\n  \r\n  \r\n\r\n  pimap = {}\r\n  \r\n  for i in items\r\n    pimap[i.period_product_id] = i \r\n  end\r\n  \r\n  \r\n  \r\n  \r\n  @show=true\r\n%>\r\n<style>\r\n    @media print {\r\n  body {\r\n  color: #000;\r\n  }\r\n  table{\r\n      padding:10px;\r\n  }\r\n  td,th{\r\n      padding:10px;\r\n  }\r\n  v{\r\n      color:blue;\r\n  }\r\n\r\n}\r\n\r\n  .price{\r\n      width:50px;\r\n  }\r\n  \r\n  .edited_by{\r\n      font-size:0.8em;\r\n  }\r\n</style>\r\n\r\n\r\n\r\n<p>\r\n\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   m_visit = {}\r\n   u_visit = []\r\n   \r\n   models[:visit_item].where(:visit_id=>record.id).each do |i|\r\n       if i.item_id\r\n           m_visit[i.item_id] = i \r\n       else\r\n           u_visit << i\r\n       end\r\n   end\r\n   \r\n   \r\n   tissue_list = models[:visit_tissue].where(:visit_id=>record.id).all\r\n   periods = []\r\n   periods = models[:pl_period].where(:sheet_id=>sheet.id).order(:sort_order).all  if sheet\r\n   \r\n   now = 0 \r\n   periods.each_with_index do |i,index|\r\n       if period==i\r\n          now = index \r\n       end\r\n   end\r\n   now += 1\r\n   \r\n   now = periods.size-1 if now == periods.size\r\n   next_visit = nil\r\n   next_visit = periods[now].id if periods[now]\r\n   \r\n   snsc_only = true\r\n   \r\n   snsc_only = false if %w{sn sc admin developer}.index @current_role\r\n   \r\n   show_cost = false\r\n   show_cost = true if %w{ admin developer}.index @current_role\r\n   \r\n%>\r\n<%# %w{sn sc admin developer}.index(@current_role).inspect %>\r\n\r\n<%# render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n<script>\r\n    $(\'.admin\').hide()\r\n</script>\r\n<%# link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n<%# link_to \'Back\', \"../Patient/show?id=\\\\#{patient.id}\"  %>\r\n\r\n\r\n\r\n\r\n<%= form_for :visit, :url=>\"process?id=\\\\#{params[:id]}\" do |f| \r\n    \r\n%><%\r\n\r\n    visit_name = \'\'\r\n    \r\n    visit_name = period.visit if period\r\n        \r\n    visit_name = record.name if record.name and record.name.size>0\r\n    \r\n     visit_date = record.date.strftime(\"%d/%m/%Y\") if record.date\r\n    \r\n%>\r\n\r\n<h3>Protocol : <v><%= project.protocol_no %></v> Version : <v> <%=sheet.version %></v>\r\nVisit : <v><%=text_field_tag \'visit_name\', visit_name,:style=>\'width:80px;color:blue;font-size:1.1em\' %> </v> at <v><%=text_field_tag \'visit_date\', visit_date, :style=>\'width:120px;color:blue;font-size:1.1em\'%></v>\r\nStatus : <v><%=record.status%></v>\r\n  <%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n\r\n\r\n</h3><br/>\r\n\r\n\r\n<%=hidden_field_tag :return, params[:return] %>\r\n\r\n\r\n\r\n\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span7\" >\r\n\r\n<% if  record.status==\'Completed\' %>\r\n<%# f.submit \'Update\',:class=>\'btn\',:data=>{:confirm=>\'Are you sure?\'}%>\r\n<%= link_to \'Show Transaction\',\"transaction?id=\\\\#{params[:id]}\", :class=>\'btn btn-info\' if record.status==\'Completed\' %>\r\n\r\n<%= link_to \'Next Visit\',\"../Patient/show?id=\\\\#{patient.id}\", :class=>\'btn btn-success\' if record.status==\'Completed\' %>\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n<div class=\"span5 right\" >\r\n    <b>Status </b>\r\n    \r\n    SN / SC : \r\n    <%= select_tag :status, options_for_select(%w{draft completed cancelled no_show postpone}.collect{|i| [i.humanize,i.humanize]}, record.status),:include_blank=>true,:id=>\'change-status\', :style=>\"width:100px\" %>\r\n   \r\n    Pharmacist : \r\n    <%= select_tag :pharmacist_status, options_for_select(%w{draft completed}.collect{|i| [i.humanize,i.humanize]}, record.pharmacist_status),:include_blank=>true,:id=>\'change-pharmacist-status\', :style=>\"width:100px\" %>\r\n    \r\n    \r\n    Transaction : <span style=\"color:red\"><%=\'Created\' if record.transaction==\'true\' %></span>\r\n    <script>\r\n        $(\'#change-status\').change(function(){\r\n            v = $(this).val()\r\n            window.location=\"update_status?id=<%=params[:id]%>&status=\"+v;\r\n            \r\n        })\r\n           $(\'#change-pharmacist-status\').change(function(){\r\n            v = $(this).val()\r\n            window.location=\"update_status?id=<%=params[:id]%>&pharmacist_status=\"+v;\r\n            \r\n        })\r\n    </script>\r\n</div>\r\n\r\n\r\n<%# link_to \'Back to Patient\',\"../Patient/show?id=\\\\#{patient.id}\" %>\r\n\r\n\r\n</div>\r\n\r\n<div class=\"tabbable tabbable-bordered\">\r\n<ul class=\"nav nav-tabs\">\r\n\r\n	<li class=\"active\"><a href=\"#tab1\" data-toggle=\"tab\">Schedule List</a></li>\r\n	<li class=\"\"><a href=\"#tab5\" data-toggle=\"tab\">Traveling <span style=\"color:green\"><%=\"(\\\\#{record.traveling_status})\" if record.traveling_status and record.traveling_status!=\"\" %></span></a></li>\r\n	<li class=\"\"><a href=\"#tab2\" data-toggle=\"tab\">Additional List</a></li>\r\n\r\n<% if %w{admin developer pharmacist }.index @current_role %>\r\n<li class=\"\"><a href=\"#tab4\" data-toggle=\"tab\">Pharmacy</a></li>\r\n<% end %>    \r\n\r\n	\r\n	<!--<li class=\"\"><a href=\"#tab3\" data-toggle=\"tab\">Pathology</a></li>-->\r\n\r\n\r\n\r\n</ul>\r\n<div class=\"tab-content\">\r\n\r\n<div class=\"tab-pane\" id=\"tab5\">\r\n<h3>Traveling</h3>\r\n\r\n\r\n<table class=\"table\" style=\"width:300px\">\r\n<tr>\r\n    <td>\r\n        Remark \r\n    </td>\r\n    <td>\r\n         <%=text_field_tag \'visit_traveling_note\', record.traveling_note,:style=>\';color:blue;font-size:1.1em\' %> \r\n    </td>\r\n</tr>\r\n<tr>\r\n    <td>\r\n        Traveling Amount \r\n    </td>\r\n    <td>\r\n         <%=text_field_tag \'visit_traveling_amount\', record.traveling_amount,:style=>\';color:blue;font-size:1.1em\' %> \r\n    </td>\r\n</tr> \r\n\r\n<tr>\r\n    <td>\r\n        Traveling Extra\r\n    </td>\r\n    <td>\r\n         <%=text_field_tag \'visit_traveling_extra\', record.traveling_extra,:style=>\';color:blue;font-size:1.1em\' %> \r\n    </td>\r\n</tr> \r\n<tr>\r\n    <td>\r\n        Status \r\n    </td>\r\n    <td>\r\n         <%=select_tag \'visit_traveling_status\', options_for_select(%w{Pending Completed},record.traveling_status),:include_blank=>true,:style=>\'\' %> \r\n    </td>\r\n</tr>    \r\n\r\n\r\n</table>\r\n\r\n</div>\r\n\r\n<div class=\"tab-pane active\" id=\"tab1\">\r\n\r\n<p>\r\n\r\n\r\n<h3>Schedule List</h3>\r\n\r\n\r\n<table class=\"table  table-striped table-bordered table-condensed\"  >\r\n    <thead>\r\n        <th>No.</th> <th>Code</th> <th>Detail</th><th>Group</th><th>Vendor</th> \r\n        \r\n        <%if show_cost %><th>Cost</th><% end %>\r\n        \r\n        <th>Price</th>\r\n        <th>Done</th> <th style=\"width:200px\">Note</th> \r\n    </thead>\r\n    <tbody>\r\n        <%  \r\n            items = []\r\n             \r\n            period_items.each_with_index do |pi,index| \r\n                \r\n            items <<  pimap[pi.id] if pimap[pi.id]\r\n                \r\n            end\r\n            \r\n            its = []\r\n            \r\n            items.each_with_index do |i,index| \r\n            \r\n                cpp = i\r\n                pp = models[:pl_period_product].find(cpp.period_product_id)\r\n\r\n                its << [i, cpp, pp]\r\n            \r\n            end\r\n            \r\n            its.sort! do |a,b|\r\n                \r\n               a[2].sort_order <=> b[2].sort_order\r\n                \r\n            end\r\n            \r\n            its.each_with_index do |ix,index| \r\n            \r\n            i = ix[0]\r\n            \r\n            cpp = ix[1]\r\n            \r\n            \r\n           \r\n            item = nil\r\n            \r\n            p = m_products[i.product_id]\r\n            \r\n            pp = ix[2] #models[:pl_period_product].find(cpp.period_product_id)\r\n            \r\n            item = m_visit[i.id]\r\n            item = models[:visit_item].new unless item\r\n            \r\n            note = \"\"\r\n            note = item.note  if item\r\n            check = true\r\n            check = false if item and item.done==false\r\n            #check = false if item and item.done==false\r\n            #check = true if record.status == nil or record.status ==\"\"\r\n            \r\n            \r\n             cp = p\r\n                  \r\n                  \r\n        item.vendor_code = p.vendor_code unless item.vendor_code      \r\n        \r\n        sub_items = models[:pl_product_bom].where(:product_id=>cp.id).all\r\n    \r\n        options = false\r\n        \r\n        if sub_items.size > 0 \r\n        \r\n        options = true\r\n        opt_items = [] \r\n              \r\n        for c in sub_items\r\n            \r\n            options = false if c.quantity and c.quantity > 0 \r\n            \r\n        end\r\n        \r\n        \r\n        \r\n            \r\n        if sub_items.size > 0  and options\r\n        \r\n            for c in sub_items\r\n                 po = models[:pl_product].find(c.sub_product_id)\r\n                opt_items << po\r\n            end\r\n            \r\n        end\r\n        \r\n        end\r\n            \r\n            \r\n        %>\r\n        <tr>\r\n         <th><%= index+1%>.</th>\r\n         <td><%= p.code%></td>\r\n         <td><%= pp.detail%></td>\r\n         <td><%= p.group_code%>\r\n             \r\n         </td>\r\n         \r\n         <% unless options %>\r\n         \r\n         <td>\r\n            <% if p.vendor_code and p.vendor_code.size>0 %>\r\n            <%=p.vendor_code%>\r\n            <%= hidden_field_tag \"vendor[\\\\#{i.id}]\", p.vendor_code  %>\r\n            <% else \r\n            \r\n                pi_options = []\r\n                \r\n                if p.vendor_group == \'PI\'\r\n                    \r\n                    pi_options = models[:member].where(:position=>\'pi\',:vendor_code=>{\'$ne\'=>nil}).all.collect{|x| [\"\\\\#{x.name} (\\\\#{x.vendor_code})\", x.vendor_code] } \r\n                \r\n            %>\r\n            <%= select_tag \"vendor[\\\\#{i.id}]\", options_for_select(pi_options, item.vendor_code), :style=>\'width:100px\'  %>\r\n            <% end %>\r\n            <% end %>\r\n         </td>\r\n         \r\n         <%\r\n            pass = false\r\n            \r\n            cost = p.cost\r\n            price = p.price\r\n            \r\n            price =  cpp.price\r\n            \r\n            if  p.cost and p.price and (p.cost == p.price )\r\n                # cost = cpp.price unless item.cost\r\n                pass = true\r\n            end\r\n            \r\n            \r\n            # price = cpp.price\r\n            cost = price if pass\r\n            \r\n            \r\n            item.cost = cost unless item.cost\r\n            item.price = price unless item.price\r\n          \r\n         %>\r\n         \r\n         <td style=\"<%=\'display:none\' if show_cost == false %>\" id=\"cost-<%=item.id%>-td\">\r\n         <%= text_field_tag \"cost[\\\\#{i.id}]\", item.cost,:id=>\"cost-\\\\#{item.id}\",:class=>\'price\' ,:readonly=>snsc_only, :style=>\"\\\\#{\'background:yellow\' if pass}\"%></td>\r\n         <td id=\"price-<%=item.id%>-td\">\r\n         <%= text_field_tag \"price[\\\\#{i.id}]\", item.price,:id=>\"price-\\\\#{item.id}\",:class=>\'price\' ,:readonly=>snsc_only, :style=>\"\\\\#{\'background:yellow\' if pass}\"%>\r\n            \r\n             <% if  p.cost  and p.price and p.cost == p.price%>\r\n             <script>\r\n                 $(\'#price-<%=item.id%>\').change(function(){\r\n                      \r\n                      \r\n                      $(\'#cost-<%=item.id%>\').val( $(this).val())\r\n                     \r\n                     \r\n                 });\r\n                 \r\n                 \r\n                 \r\n             </script>\r\n             <% end %>\r\n             \r\n         </td>\r\n         \r\n         \r\n         <% else %>\r\n           <%\r\n                s = opt_items[0]\r\n                sm = {}\r\n                for x in opt_items\r\n                    sm[x.vendor_code] = {:cost=>x.cost, :price=>x.price}\r\n                end\r\n                vendor = s.vendor_code\r\n                vendor = item.vendor_code if item.vendor_code\r\n                item.price = cpp.price\r\n                \r\n             %>\r\n         <td>\r\n         <%=select_tag \"vendor[\\\\#{i.id}]\",options_for_select(opt_items.collect{|c| [c.vendor_code,c.vendor_code]}, vendor ),:readonly=>snsc_only, :style=>\"width:80px\",:id=>\"select-\\\\#{item.id}\" %>\r\n           \r\n             <script>\r\n                 var data_<%=item.id%> = <%=sm.to_json.html_safe%>\r\n                 \r\n                 $(\'#select-<%=item.id%>\').change(function(){\r\n                     \r\n                     v = $(this).val()\r\n                     c = data_<%=item.id%>[v]\r\n                     \r\n                     $(\'#cost-<%=item.id%>\').val(c[\'cost\'])\r\n                    // $(\'#price-<%=item.id%>\').val(c[\'price\'])\r\n                     \r\n                 })\r\n                 \r\n             </script>\r\n             \r\n         </td>\r\n         <td style=\"<%=\'display:none\' if show_cost == false %>\" id=\"cost-<%=item.id%>-td\"><%= text_field_tag \"cost[\\\\#{i.id}]\", s.cost,:id=>\"cost-\\\\#{item.id}\",:class=>\'price\',:readonly=>snsc_only%></td>\r\n         <td style=\"<%=\'display:none\' if show_cost == false %>\" id=\"price-<%=item.id%>-td\"><%= text_field_tag \"price[\\\\#{i.id}]\", item.price,:id=>\"price-\\\\#{item.id}\",:class=>\'price\' ,:readonly=>snsc_only %></td>\r\n         \r\n         <% end %>\r\n         \r\n         <td><%= hidden_field_tag \"check[\\\\#{i.id}]\", \'false\'%>\r\n             <%= check_box_tag \"check[\\\\#{i.id}]\", true, check ,:readonly=>snsc_only, :class=>\'check-item\' %><br/>\r\n             <span class=\"edited_by\" id=\"edited_by_t_<%=i.id%>\"><%=item.edited_by%></span>\r\n             <%= hidden_field_tag \"edited_by[\\\\#{i.id}]\", item.edited_by, :style=>\'width:100px\'%>\r\n                 \r\n             </td>\r\n         <td><%= text_field_tag \"note[\\\\#{i.id}]\", note, :style=>\'width:100px\'%></td>\r\n\r\n\r\n         </tr>\r\n      \r\n          <%\r\n          \r\n    \r\n        if sub_items.size > 0 \r\n      \r\n        # if true\r\n        unless options\r\n       \r\n        \r\n        for i in sub_items\r\n        p = models[:pl_product].find(i.sub_product_id)\r\n        \r\n        detail = p.name\r\n        detail = i.detail if i.detail and i.detail !=\'\'\r\n     %>\r\n     <tr><td></td><td>- <%=p.code%></td>\r\n         <td><%=detail%> x <%=i.quantity%></td>\r\n         <td><%=p.group_code%></td>\r\n         <td><%=p.vendor_code%><%=p.vendor_group%></td>\r\n         <td><%=p.cost%> x <%=i.quantity %></td> <td><%=p.price if p.price and p.price!=0 %></td>\r\n        <td></td> <td></td>\r\n     </tr>\r\n       <% end %>\r\n     \r\n     \r\n        \r\n        <% end %>\r\n         \r\n             <% end %>\r\n       <% if cp.code==\'SET-CHEM\' %>\r\n        <%\r\n        \r\n        \r\n        sub_items = models[:pl_period_product_bom].where(:period_product_id=>cpp.period_product_id).all\r\n     \r\n       \r\n     \r\n        for ib in sub_items\r\n        \r\n        p = models[:pl_product].find(ib.sub_product_id)\r\n        \r\n        \r\n        \r\n     %>\r\n     <tr>\r\n         <td></td>\r\n         <td>- <%=p.code%></td><td><%=p.name%> </td>\r\n         <td><%=p.group_code%></td>\r\n         <td>\r\n         <% if  p.vendor_code==\"\" or p.vendor_code==nil\r\n            opt_items =  models[:pl_product].find(models[:pl_product_bom].where(:product_id=>p.id).all.collect{|ia| ia.sub_product_id})\r\n            \r\n              sm = {}\r\n            \r\n            for ix in opt_items\r\n            \r\n                sm[ix.id] = ix.cost\r\n            \r\n            end\r\n            \r\n            selected_option = models[:visit_item_bom].where(:visit_id=>record.id,:item_id=>i.id,:bom_id=>ib.id).first\r\n            product_id = nil\r\n            product_id = selected_option.product_id if selected_option\r\n            default_cost = opt_items[0].cost\r\n            selected_options = models[:visit_item_bom].where(:visit_id=>record.id, :item_id=>i.id,:bom_id=>ib.id).all\r\n         %>\r\n         <%=select_tag \"sub_vendor[\\\\#{i.id}][\\\\#{ib.id}]\",options_for_select(opt_items.collect{|ia| [ia.vendor_code,ia.id]}, product_id),:readonly=>snsc_only, :style=>\"width:100px\", :id=>\"select-\\\\#{i.id}-\\\\#{ib.id}\"%>\r\n         \r\n         <script>\r\n             \r\n             var data_<%=ib.id%> = <%=sm.to_json.html_safe %>\r\n             \r\n             $(\'#select-<%=i.id%>-<%=ib.id%>\').change(function(){\r\n                    v = $(this).val()\r\n                 \r\n                    $(\'#cost-<%=ib.id%>\').html(data_<%=ib.id%>[v])\r\n                 \r\n             })\r\n             \r\n             \r\n         </script>\r\n         \r\n         <% else %> \r\n         <%=p.vendor_code%>\r\n         <% end %>     \r\n         </td>\r\n         <td id=\"cost-<%=ib.id%>\"><%=default_cost%> </td>   <td  id=\"price-<%=ib.id%>\"><%=p.price%></td>\r\n         <td>\r\n             \r\n             \r\n             \r\n         </td> <td></td>\r\n     </tr>\r\n       <% end %>\r\n   \r\n \r\n       \r\n         <% end %>\r\n       \r\n         \r\n         \r\n         \r\n           <% end %>\r\n    </tbody>\r\n</table>\r\n\r\n<script>\r\n    \r\n    $(\'.check-item\').change(function(){\r\n        id = $(this).attr(\'id\').split(\'_\')[1]\r\n        $(\"#edited_by_\"+id).val(\'<%=@current_user.login%> <%=Time.now.strftime(\"%d/%m/%Y %H:%M\")%>\')\r\n        $(\"#edited_by_t_\"+id).html(\'<%=@current_user.login%> <%=Time.now.strftime(\"%d/%m/%Y %H:%M\")%>\')\r\n        \r\n        \r\n    })\r\n    \r\n</script>\r\n\r\n\r\n\r\n\r\n			</p>\r\n		</div>\r\n		<div class=\"tab-pane\" id=\"tab2\">\r\n			<p>\r\n\r\n<h3>Pass Through List</h3>\r\n\r\n<table class=\"table table-striped\">\r\n    <thead>\r\n        <tr>\r\n            <th>Code</th>\r\n            <th>Detail</th>\r\n            <th>Group</th>\r\n            <th>Vendor</th>\r\n            <th>Cost</th>\r\n            <th>Price</th>\r\n            <th>Quantity</th>\r\n            <th>Note</th>\r\n            <th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody id=\"pass-through-list\">\r\n        <%\r\n            for i in u_visit.collect{|i| i if i.item_type==\'1\'}.compact\r\n            \r\n            item = models[:project_item].find(i.project_item_id)\r\n            \r\n             p = models[:pl_product].find(i.product_id) \r\n             \r\n             if p \r\n                 \r\n             price = p.price\r\n             cost = p.cost\r\n             detail = p.name\r\n             \r\n            #  item = models[:pl_period_product].where(:sheet_id=>sheet.id, :product_id=>i.product_id).first\r\n             \r\n            #  item = models[:project_item].where(:project_id=>record.project_id,:product_id=>i.product_id).first\r\n             \r\n             \r\n             if item\r\n             price = item.price\r\n             detail = item.detail\r\n            end\r\n            # detail = p.name\r\n            # detail = i.detail if i.detail\r\n            #  cost = item.price if item\r\n           opt = false\r\n           sub_items = models[:pl_product_bom].where(:product_id=>p.id).all      \r\n           opt = true if sub_items.size > 0 and sub_items[0].item_type==\'OPT\'\r\n        %>\r\n        <tr id=\"r<%=i.id%>\">\r\n            <td>\r\n                <b><%=p.code%></b><%=hidden_field_tag \"item_id[]\", i.product_id %><%=hidden_field_tag \"item_item_type[]\", \'1\'  %>\r\n                <%=hidden_field_tag \"item_item[]\", i.project_item_id %>\r\n            </td>\r\n             <td>\r\n                <%=detail%>\r\n            </td>\r\n             <td>\r\n                <%=p.group_code%>\r\n            </td>\r\n            <td>\r\n                <% if opt==true %>\r\n                <%=select_tag \"item_vendor[]\",options_for_select(sub_items.collect{|y| models[:pl_product].find(y.sub_product_id).vendor_code}, i.vendor_code) , :style=>\'width:100px\'%>\r\n                <% else %>\r\n                <%=p.vendor_code%>\r\n                <% end %>\r\n            </td>\r\n            <td>\r\n                <%=fn cost %><%=hidden_field_tag \"item_cost[]\", cost %>\r\n            </td>\r\n            <td>\r\n                <%=fn price %><%=hidden_field_tag \"item_price[]\", price %>\r\n            </td>\r\n            <td>\r\n                <%=text_field_tag \"item_quantity[]\", i.quantity , :style=>\'width:50px\'%>\r\n            </td>\r\n            \r\n             <td>\r\n                <%=text_field_tag \"item_note[]\", i.note %>\r\n            </td>\r\n            <td>\r\n                <%=link_to \"Delete\", \"#\", :id=>i.id, :class=>\'un-visit\' %>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n        \r\n        \r\n        <%\r\n        \r\n        \r\n        \r\n        if sub_items.size>0\r\n            \r\n            if sub_items[0].item_type==\'OPT\'\r\n                \r\n                \r\n                \r\n            else    \r\n        \r\n        for x in sub_items\r\n                   p = models[:pl_product].find(x.sub_product_id)\r\n        %>\r\n        <tr>\r\n            <td>&nbsp;&nbsp;- <%=p.code%></td><td><%=x.detail%></td><td><%=p.vendor_group%></td><td><%=p.vendor_code%></td><td><%=x.cost%></td><td></td><td><%=x.quantity%></td>\r\n        </tr>\r\n         <% end %>\r\n        \r\n          <% end %>\r\n           <% end %>\r\n           \r\n           <!-- set chem -->\r\n           <%\r\n           \r\n        \r\n        \r\n        sub_items = models[:pl_additional_product_bom].where(:project_item_id=>item.id).all      \r\n\r\n\r\n           \r\n        if sub_items.size>0\r\n        \r\n        for x in sub_items\r\n                \r\n                p = models[:pl_product].find(x.sub_product_id)\r\n                bom = models[:pl_product_bom].where(:product_id=>p.id).all\r\n                sp = models[:visit_additional_item_bom].where(:visit_id=>record.id,:item_id=>i.id,:bom_id=>x.id.to_s).first\r\n                \r\n        %>\r\n        <tr>\r\n            <td>&nbsp;&nbsp;- <%=p.code%></td><td><%=p.name%></td><td><%=p.vendor_group%></td>\r\n            <td>\r\n            \r\n            <%=select_tag \"sub_vendor_item[\\\\#{item.id}][\\\\#{x.id}]\",  options_for_select(bom.collect{|x| y= models[:pl_product].find(x.sub_product_id); [y.vendor_code,x.sub_product_id] },sp.product_id ), :style=>\'width:100px\' %> \r\n                \r\n                \r\n            </td>\r\n            \r\n            \r\n            <td><%=sp.cost%></td><td></td><td><%=x.quantity%></td><td><%=%></td><td><%=%></td>\r\n        </tr>\r\n        \r\n          <% end %>\r\n           <% end %>\r\n           \r\n           \r\n        \r\n         <% end %>\r\n    </tbody>\r\n</table>\r\n<br/>\r\n<% if snsc_only==false %>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#addProductPassThrough\" id=\"pass-through\" class=\"btn\" >+Item</a>\r\n<% end %>\r\n\r\n<script>\r\n    $(\'.un-visit\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n</script>\r\n<br/><br/><br/>\r\n<h3>Reimbursement List</h3>\r\n\r\n<table class=\"table table-striped\">\r\n    <thead>\r\n        <tr>\r\n            <th>Code</th>\r\n            <th>Detail</th>\r\n            \r\n            <th>Group</th>\r\n            <th>Vendor</th>\r\n            <th>Cost</th>\r\n            <th>Price</th>\r\n            <th>Quantity</th>\r\n            <th>Note</th>\r\n            <th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody id=\"reimburse-list\">\r\n        <% \r\n        \r\n            for i in u_visit.collect{|i| i if i.item_type==\'2\'}.compact\r\n            \r\n             p = models[:pl_product].find(i.product_id) \r\n             if p \r\n                 \r\n             price = p.price\r\n             cost = p.cost\r\n             item = models[:project_item].where(:product_id=>i.product_id).first\r\n             \r\n             price = item.price if item\r\n             cost = item.price if item\r\n                 \r\n        %>\r\n        <tr id=\"r<%=i.id%>\">\r\n            <td>\r\n                <%=p.code%><%=hidden_field_tag \"item2_id[]\", i.product_id %><%=hidden_field_tag \"item2_item_type[]\", \'2\'  %>\r\n                <%=hidden_field_tag \"item2_item[]\", i.project_item_id %>\r\n\r\n\r\n            </td>\r\n             <td>\r\n                <%=p.name%>\r\n            </td>\r\n             <td>\r\n                <%=p.group_code%>\r\n            </td>\r\n            <td>\r\n                <%=p.vendor_code%>\r\n            </td>\r\n            <td>\r\n                <%=text_field_tag \"item2_cost[]\", i.cost, :style=>\'width:50px\' %>\r\n            </td>\r\n            <td>\r\n                <%=text_field_tag \"item2_price[]\", i.price, :style=>\'width:50px\' %>\r\n            </td>\r\n              <td>\r\n                <%=text_field_tag \"item2_quantity[]\", i.quantity, :style=>\'width:50px\' %>\r\n            </td>\r\n             <td>\r\n                <%=text_field_tag \"item2_note[]\", i.note %>\r\n            </td>\r\n            <td>\r\n                <%=link_to \"Delete\", \"#\", :id=>i.id, :class=>\'un-visit\' %>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n         <% end %>\r\n    </tbody>\r\n</table>\r\n<br/>\r\n\r\n<% if snsc_only==false %>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#addProductReimburse\" id=\"reimburse\" class=\"btn\">+Item</a>\r\n<% end %>\r\n<script>\r\n    $(\'.un-visit\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n</script>\r\n\r\n\r\n\r\n			</p>\r\n		</div>\r\n		<div class=\"tab-pane\" id=\"tab3\">\r\n			<p>\r\n\r\n<h3>Pathology</h3>\r\n\r\n<table class=\"table table-striped\">\r\n    <thead>\r\n        <tr>\r\n            <th>Detail</th>\r\n            <th>Type</th>\r\n            <th>Note</th>\r\n            <th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody id=\"tissue-list\">\r\n        <%\r\n            for i in tissue_list \r\n        %>\r\n        <tr id=\"t<%=i.id%>\">\r\n            <td>\r\n                 <%=text_field_tag \"tissue[]\", i.name %>\r\n            </td>\r\n            <td>\r\n                 <%=text_field_tag \"tissue-note[]\", i.note %>\r\n    </td>\r\n            <td>\r\n                <%=text_field_tag \"tissue-note[]\", i.note %>\r\n            </td>\r\n            <td>\r\n                <%=link_to \"Delete\", \"#\", :id=>i.id, :class=>\'tissue-del\' %>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n        \r\n    </tbody>\r\n</table><br/>\r\n<%=link_to \"+Tissue\", \"javascript:addTissue()\", :class=>\'btn\'%>\r\n\r\n<script>\r\n    function addTissue(){\r\n        template = []\r\n        \r\n        template.push(\"<td><input type=\'text\' name=\'tissue[]\' value=\'\'></td>\")\r\n        template.push(\"<td><input type=\'text\' name=\'tissue-type[]\' value=\'\'></td>\")\r\n        template.push(\"<td><input type=\'text\' name=\'tissue-note[]\' value=\'\'></td>\")\r\n        template.push(\"<td><a class=\'tissue-del\' href=\'#\'>Delete</a></td>\")\r\n\r\n\r\n        $(\'#tissue-list\').append(\"<tr  >\"+template.join()+\"</tr>\");\r\n        $(\'.tissue-del\').click(function(){\r\n            $(this).parent().parent().remove()\r\n            return false\r\n        })\r\n        \r\n        // $(\'#search_result\').html(\'\')\r\n    }\r\n    $(\'.un-visit\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n    $(\'.tissue\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#t\'+id).remove()\r\n            return false\r\n    })\r\n        \r\n        \r\n</script>\r\n\r\n\r\n\r\n			</p>\r\n		</div>\r\n		\r\n				<div class=\"tab-pane\" id=\"tab4\">\r\n			<p>\r\n\r\n      <h3>IP Drug List</h3>\r\n<%\r\n\r\n    ip_items = models[:ip_item].where(:project_id=>project.id).all\r\n\r\n%>\r\n           \r\n<%= hidden_field_tag \"ip_visit\", record.id %> <%= hidden_field_tag \"ip_patient\", patient.id %>\r\n\r\n\r\n\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n            <th>IP Name</th>\r\n            <th>Lot / Expired / Balance</th>\r\n            <th>Usage</th>\r\n            <th>Note</th>\r\n            <th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody id=\"pharma-list-ip\">\r\n    <% \r\n    for ip in ip_items \r\n    \r\n      \r\n    \r\n        current_card = models[:ip_card].where(:item_id=>ip.id, :visit_id=>record.id).first\r\n\r\n\r\n        options = models[:ip_card].where(:item_id=>ip.id,:visit_id=>{\'$ne\'=>record.id}).all\r\n        \r\n        opt_map = {}\r\n        balance = 0 \r\n        for j in options\r\n            k = \"\\\\#{j.lot}|\\\\#{j.expired_date}\"\r\n            \r\n            opt_map[k] = {:balance=>0, :j=>j} unless opt_map[k]\r\n            \r\n            balance = opt_map[k][:balance]\r\n            \r\n            balance+=j.quantity if j.status==\'in\'\r\n            balance-=j.quantity if j.status==\'out\'\r\n            \r\n            opt_map[k][:balance] = balance\r\n            opt_map[k][:select] = \"Lot: \\\\#{j.lot} Exp: \\\\#{j.expired_date} = \\\\#{balance}\"\r\n            \r\n            \r\n        end\r\n        \r\n        options = []\r\n        \r\n        opt_map.each_pair do |k,v|\r\n           \r\n           options << [v[:select], k] \r\n           \r\n        end\r\n        \r\n        quantity = 0 \r\n        note = \'\'\r\n        \r\n        if current_card\r\n           \r\n           quantity = current_card.quantity\r\n           note = current_card.note\r\n            \r\n        end\r\n    \r\n    %>\r\n    <tr>\r\n        <td>\r\n            <%= ip.name  %>\r\n            <%= hidden_field_tag \"ip_item[]\", ip.id %>\r\n        </td>\r\n        \r\n        <td>\r\n            <%= select_tag \"ip_lot[]\",options_for_select(options),:style=>\"width:250px\"   %>\r\n        </td>\r\n        \r\n        <td>\r\n            <%= text_field_tag \"ip_quantity[]\", quantity %>\r\n        </td>\r\n          <td>\r\n            <%= text_field_tag \"ip_note[]\", note %>\r\n        </td>\r\n    </tr>\r\n    \r\n    <% end %>\r\n    </tbody>\r\n    \r\n</table>\r\n\r\n\r\n\r\n      <h3>Pharmacist List</h3>\r\n\r\n<% if @current_role==\'pharmacist\' or @current_role==\'admin\' or @current_role==\'developer\'%>\r\n\r\n\r\n\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n            <th>Code</th>\r\n            <th>Detail</th>\r\n            <th>Group</th>\r\n            <th>Vendor</th>\r\n            <th>Cost</th>\r\n            <th>Price</th>\r\n            <th>Quantity</th>\r\n            <th>Note</th>\r\n            <th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody id=\"pharma-list\">\r\n        <%\r\n            for i in u_visit.collect{|i| i if i.item_type==\'3\'}.compact\r\n            \r\n            \r\n             p = models[:pl_product].find(i.product_id) \r\n             \r\n             if p \r\n                 \r\n             price = p.price\r\n             cost = p.cost\r\n             item = models[:project_item].where(:product_id=>i.product_id).first\r\n             \r\n             price = item.price if item\r\n            #  cost = item.price if item\r\n                 \r\n        %>\r\n        <tr id=\"r<%=i.id%>\">\r\n            <td>\r\n                <%=p.code%><%=hidden_field_tag \"item3_id[]\", i.product_id %><%=hidden_field_tag \"item3_item_type[]\", \'3\'  %>\r\n            </td>\r\n             <td>\r\n                <%=p.name%>\r\n            </td>\r\n             <td>\r\n                <%=p.group_code%>\r\n            </td>\r\n            <td>\r\n                <%=p.vendor_code%>\r\n            </td>\r\n            <td>\r\n                <%=fn cost %><%=hidden_field_tag \"item3_cost[]\", cost %>\r\n            </td>\r\n            <td>\r\n                <%=fn price %><%=hidden_field_tag \"item3_price[]\", price %>\r\n            </td>\r\n            <td>\r\n                <%=text_field_tag \"item3_quantity[]\", i.quantity , :style=>\'width:50px\'%>\r\n            </td>\r\n            \r\n             <td>\r\n                <%=text_field_tag \"item3_note[]\", i.note %>\r\n            </td>\r\n            <td>\r\n                <%=link_to \"Delete\", \"#\", :id=>i.id, :class=>\'un-visit\' %>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n         <% end %>\r\n    </tbody>\r\n</table>\r\n<br/>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#addProductPharma\" class=\"btn\">+Item</a>\r\n\r\n<script>\r\n    $(\'.un-visit\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n</script>\r\n\r\n<% else %>\r\n<br/>\r\n<div class=\"alert alert-danger\">\r\n    PHARMACIST ONLY\r\n</div>\r\n\r\n<% end %>\r\n\r\n<br/><br/><br/>\r\n\r\n			</p>\r\n		</div>\r\n		\r\n				<div class=\"tab-pane\" id=\"tab5\">\r\n			<p>\r\n<h3>Reimbursement</h3>\r\n\r\n\r\n            Reimbursement \r\n            \r\n            \r\n			</p>\r\n		</div>\r\n	</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n</div>\r\n<%\r\n    if record.transaction != \'true\' \r\n%>\r\n\r\n<% if project.budget_approved==\'true\' %>\r\n\r\n<% if %w{sn sc admin developer}.index @current_role %>\r\n<%= hidden_field_tag \"snsc_submit\",\"\",:id=>\"snsc_submit\" %>\r\n<b>SN/SC : </b>\r\n<% if record.status==\'Completed\' %>\r\n<%= f.submit \'Update\',:class=>\'btn snsc_btn\',:data=>{:confirm=>\'Are you sure?\'}%>\r\n<% else %>\r\n<%= f.submit \'Save Draft\',:class=>\"btn \\\\#{\'btn-info\' if record.status==\'Draft\'} snsc_btn\",:data=>{:confirm=>\'Are you sure?\'}%> \r\n<%= f.submit \'Submit\',:class=>\'btn btn-success snsc_btn\',:data=>{:confirm=>\'Are you sure?\'}%>\r\n<% end %>\r\n<script>\r\n    $(\'.snsc_btn\').click(function(){\r\n        $(\'#snsc_submit\').val(\"true\")\r\n    })\r\n</script>\r\n<% end %>\r\n\r\n<% else %>\r\n\r\n<div class=\'alert alert-danger\'>\r\nNot approved budget!!\r\n</div>\r\n\r\n<% end %>\r\n\r\n<% if %w{pharmacist admin developer}.index @current_role %>\r\n<%= hidden_field_tag \"pharmacist_submit\",\"\",:id=>\"pharmacist_submit\" %>\r\n<b>Pharmacist : </b>\r\n<% if  record.pharmacist_status==\'Completed\' %>\r\n<%= f.submit \'Update\',:class=>\'btn pharmacist_btn\',:data=>{:confirm=>\'Are you sure?\'}%>\r\n<%= record.pharmacist_status %>\r\n<% else %>\r\n<%= f.submit \'Save Draft\',:class=>\"btn \\\\#{\'btn-info\' if record.pharmacist_status==\'Draft\'} pharmacist_btn\",:data=>{:confirm=>\'Are you sure?\'}%> \r\n<%= f.submit \'Submit\',:class=>\'btn btn-success pharmacist_btn\',:data=>{:confirm=>\'Are you sure?\'}%>\r\n<% end %>\r\n<script>\r\n    $(\'.pharmacist_btn\').click(function(){\r\n        $(\'#pharmacist_submit\').val(\"true\")\r\n    })\r\n</script>\r\n\r\n<% end %>\r\n\r\n<% else %>\r\n<div class=\"alert alert-info\">Already create invoice.. please contact accounting</div>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n<div id=\"template-pass-through-tmp\" style=\"display:none\">\r\n <table>\r\n        <tbody>\r\n    <tr>\r\n    <td class=\"code\">\r\n        code\r\n    </td>\r\n    <td >\r\n    \r\n        <%=hidden_field_tag \"item\", \'\', :class=>\'field-x item\' %>\r\n        <%=hidden_field_tag \"id\", \'\', :class=>\'field-x record\' %>\r\n        <%=hidden_field_tag \"item_type\