 <%=text_field_tag \"quantity\", \'1\', :class=>\'field-x quantity\' , :style=>\'width:50px\'%>\r\n    </td>\r\n    <td >\r\n        <%=text_field_tag \"note\", \'\', :class=>\'field-x note\' %>\r\n    </td>\r\n    <td class=\"delete\">\r\n        <%=link_to \"Delete\", \"#\", :class=>\'del-x\' %>\r\n    </td>\r\n\r\n\r\n    \r\n    </tr>\r\n    </tbody>\r\n        \r\n    </table>\r\n    \r\n</div>\r\n\r\n\r\n\r\n<div id=\"template-pharma\" style=\"display:none\">\r\n <table>\r\n        <tbody>\r\n    <tr>\r\n    <td class=\"code\">\r\n        code\r\n    </td>\r\n    <td >\r\n        <%=hidden_field_tag \"id\", \'\', :class=>\'field-x record\' %>\r\n        <%=hidden_field_tag \"item_type\", \'3\', :class=>\'field-x item_type\' %>\r\n        \r\n        <span class=\"detail\">-</span>\r\n    </td>\r\n    <td class=\"group_code\">\r\n        -\r\n    </td>\r\n    <td class=\"vendor_code\">\r\n        -\r\n    </td>\r\n    <td class=\"cost\">\r\n        -\r\n    </td>\r\n    <td class=\"price\">\r\n        -\r\n    </td>\r\n   <td >\r\n        <%=text_field_tag \"quantity\", \'1\', :class=>\'field-x quantity\', :style=>\'width:50px\' %>\r\n    </td>\r\n    <td >\r\n        <%=text_field_tag \"note\", \'\', :class=>\'field-x note\' %>\r\n    </td>\r\n    <td class=\"delete\">\r\n        <%=link_to \"Delete\", \"#\", :class=>\'del-x\' %>\r\n    </td>\r\n\r\n\r\n    \r\n    </tr>\r\n    </tbody>\r\n        \r\n    </table>\r\n    \r\n</div>\r\n\r\n\r\n\r\n\r\n<script>\r\n\r\n    function selectPassThrough(product_id){\r\n      \r\n        $.ajax({\r\n            url: \"add_item?item_id=\"+product_id+\"&project_id=<%=params[:id]%>\",\r\n            context: document.body\r\n        }).done(function(data) {\r\n            \r\n            template = $(data)\r\n            $(\'#close-pass_through_list\').click();\r\n            \r\n            \r\n             template.find(\'.del-x\').click(function(){\r\n                   $(\'.r\'+$(this).attr(\'id\')).remove()\r\n     