.del-x\').click(function(){\r\n    //         id = $(this).attr(\'id\')\r\n    //         $(\'#r\'+id).remove()\r\n    //         return false\r\n    //     })\r\n        \r\n        \r\n        \r\n\r\n        \r\n    //     template.find(\'tr\').each(function(){\r\n    //         $(this).attr(\"id\", \"r\"+p[\'id\'])\r\n    //         $(\'#pass-through-list\').append($(this))\r\n    //     })\r\n        \r\n//   $(\'#close-pass_through_list\').click();\r\n\r\n\r\n// })\r\n    \r\n    // }\r\n \r\n \r\n    function selectReimburse(product_id){\r\n             $.ajax({\r\n            url: \"../PlProduct/data?item_id=\"+product_id+\"&project_id=<%=params[:id]%>\",\r\n            context: document.body\r\n        }).done(function(data) {\r\n        \r\n        data = JSON.parse(data);\r\n  \r\n        p = data\r\n        \r\n        pre = \'item2\'\r\n      \r\n        template = $(\'#template-reimburse\').clone()\r\n        \r\n        template.find(\'.code\').html(p[\'code\'])\r\n        template.find(\'.item\').attr(\"value\",product_id)\r\n\r\n\r\n        template.find(\'.gl_code\').html(p[\'gl_code\'])\r\n        template.find(\'.group_code\').html(p[\'group_code\'])\r\n        template.find(\'.vendor_code\').html(p[\'vendor_code\'])\r\n        template.find(\'.field-x\').each(function(){\r\n            \r\n            $(this).attr(\"name\",  \"item2_\"+$(this).attr(\"name\")+\"[]\" ) \r\n            \r\n        })\r\n       \r\n        template.find(\'.record\').attr(\"value\",p[\'id\'])\r\n\r\n\r\n        template.find(\'.detail\').html(p[\'name\'])\r\n        \r\n        // template.find(\'.cost\').attr(\"value\",p[\'cost\'])\r\n        // template.find(\'.price\').attr(\"value\",p[\'price\'])\r\n        \r\n        template.find(\'.del-x\').attr(\"id\",p[\'id\'])\r\n        template.find(\'.del-x\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n        \r\n        \r\n        \r\n\r\n        \r\n        template.find(\'tr\').each(function(){\r\n            $(this).attr(\"id\", \"r\"+p[\'id\'])\r\n            $(\'#reimburse-list\').append($(this))\r\n        })\r\n        \r\n   $(\'#close-reimburse_list\').click();\r\n\r\n\r\n})\r\n    }\r\n\r\n    \r\n    function selectPharma(product_id){\r\n       $.ajax({\r\n            url: \"../PlProduct/data?id=\"+product_id+\"&project_id=<%=params[:id]%>\",\r\n            context: document.body\r\n        }).done(function(data) {\r\n      \r\n        data = JSON.parse(data);\r\n  \r\n        p = data\r\n        \r\n        pre = \'item3\'\r\n      \r\n        template = $(\'#template-pharma\').clone()\r\n\r\n\r\n        template.find(\'.code\').html(p[\'code\'])\r\n        template.find(\'.gl_code\').html(p[\'gl_code\'])\r\n        template.find(\'.group_code\').html(p[\'group_code\'])\r\n        template.find(\'.vendor_code\').html(p[\'vendor_code\'])\r\n        \r\n        template.find(\'.field-x\').each(function(){\r\n            \r\n            $(this).attr(\"name\",  \"item3_\"+$(this).attr(\"name\")+\"[]\" ) \r\n            \r\n        })\r\n       \r\n        template.find(\'.record\').attr(\"value\",p[\'id\'])\r\n\r\n\r\n        template.find(\'.detail\').html(p[\'name\'])\r\n        \r\n        \r\n        template.find(\'.cost\').html(p[\'cost\'])\r\n\r\n        template.find(\'.price\').html(p[\'price\'])\r\n\r\n\r\n\r\n        template.find(\'.del-x\').attr(\"id\",p[\'id\'])\r\n        template.find(\'.del-x\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n        \r\n        \r\n        \r\n\r\n        \r\n        template.find(\'tr\').each(function(){\r\n            $(this).attr(\"id\", \"r\"+p[\'id\'])\r\n            $(\'#pharma-list\').append($(this))\r\n        })\r\n        \r\n   $(\'#close-pharma\').click();\r\n\r\n\r\n})\r\n    \r\n    }\r\n    \r\n    \r\n    \r\n    $(\'#pass-through\').click(function(){\r\n            $(\'#pass-through-form\').click();\r\n    })\r\n    $(\'#reimburse\').click(function(){\r\n            $(\'#reimburse-form\').click();\r\n    })\r\n\r\n    \r\n \r\n</script>\r\n\r\n\r\n\r\n<div class=\"modal hide\" id=\"addProductPassThrough\" aria-hidden=\"true\" style=\"display: none;\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Pass Through Item</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n\r\n<%= form_for :query, :url=>\"../PlProduct/product_wl_search?id=\\\\#{project.id}&update=search_result_1&callback=selectPassThrough&sheet_id=\\\\#{sheet.id}\", :data=>{:remote=>true} do |f| %>\r\nSearch <%= f.text_field :q%>\r\n<%= f.submit \'Search\',:id=>\'pass-through-form\' %>\r\n<% end %>\r\n\r\n								\r\n<div id=\"search_result_1\">\r\n    \r\n</div>\r\n\r\n\r\n	</div>\r\n	<div class=\"modal-footer\">\r\n		<a href=\"#\" class=\"btn\" data-dismiss=\"modal\" id=\"close-pass_through_list\">Close</a>\r\n	</div>\r\n</div>\r\n\r\n\r\n<div class=\"modal hide\" id=\"addProductReimburse\" aria-hidden=\"true\" style=\"display: none;\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Reimburse Item</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n\r\n<%= form_for :query, :url=>\"../PlProduct/product_wl_search?id=\\\\#{project.id}&update=search_result_2&callback=selectReimburse&sheet_id=\\\\#{sheet.id}\", :data=>{:remote=>true} do |f| %>\r\nSearch <%= f.text_field :q%>\r\n<%= f.submit \'Search\',:id=>\'reimburse-form\'%>\r\n<% end %>\r\n\r\n								\r\n<div id=\"search_result_2\">\r\n    \r\n</div>\r\n\r\n\r\n	</div>\r\n	<div class=\"modal-footer\">\r\n		<a href=\"#\" class=\"btn\" data-dismiss=\"modal\" id=\"close-reimburse_list\">Close</a>\r\n	</div>\r\n</div>\r\n\r\n\r\n<div class=\"modal hide\" id=\"addProductPharma\" aria-hidden=\"true\" style=\"display: none;\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Pharmacist Item</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n\r\n<%= form_for :query, :url=>\"../PlProduct/product_search?id=\\\\#{project.id}&update=search_result_3&callback=selectPharma&sheet_id=\\\\#{sheet.id}\", :data=>{:remote=>true} do |f| %>\r\nSearch <%= f.text_field :q%>\r\n<%= f.submit \'Search\' %>\r\n<% end %>\r\n\r\n								\r\n<div id=\"search_result_3\">\r\n    \r\n</div>\r\n\r\n\r\n	</div>\r\n	<div class=\"modal-footer\">\r\n		<a href=\"#\" class=\"btn\" data-dismiss=\"modal\" id=\"close-pharma\">Close</a>\r\n	</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<br/>\r\n<br/>\r\n* last updated at <%= record.updated_at %>',NULL,NULL,NULL,'2018-06-06 17:12:46','2018-06-06 17:12:46','display',''),(3514,'print',1385,3,'<html>\r\n<head>\r\n			<%= javascript_include_tag \"application\"  %>\r\n			<%= stylesheet_link_tag    \"application\" ,\"elfinder\",\"elfinder-theme\"%>\r\n			<%= csrf_meta_tag %>\r\n</head>\r\n<body>\r\n<style>\r\n    table{border:1px};\r\n</style>\r\n\r\n\r\n\r\n<%\r\n  models = get_model\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  \r\n  project = models[:project].find(record.project_id)\r\n  sheet = models[:pl_sheet].find(record.sheet_id)\r\n  period = models[:pl_period].find(record.period_id)\r\n  patient = models[:patient].find(record.patient_id)\r\n  \r\n  period_items  = models[:pl_period_product].where(:sheet_id=>sheet.id).order(:sort_order).all\r\n  \r\n  m_products = Hash[models[:pl_product].find(period_items.compact.collect{|i| i.product_id}).map{|i| [i.id, i]}]\r\n  \r\n  items  = models[:pl_period_item].where(:sheet_id=>sheet.id, :period_id=>period.id).all\r\n\r\n  \r\n\r\n  pimap = {}\r\n  \r\n  for i in items\r\n    pimap[i.period_product_id] = i \r\n  end\r\n  \r\n  \r\n  \r\n  \r\n  @show=true\r\n%>\r\n<style>\r\n    @media print {\r\n  body {\r\n  color: #000;\r\n  }\r\n  table{\r\n      border-collapse: collapse;\r\n      padding:5px;\r\n      font-size:0.8em;\r\n  }\r\n  td,th{\r\n      padding:5px;\r\n  }\r\n  v{\r\n      color:blue;\r\n  }\r\n}\r\nv{\r\n      color:blue;\r\n  }\r\n</style>\r\n<table class=\"table\">\r\n<tr>\r\n\r\n    <td>\r\n        <b>Subject ID : </b><v><%=patient.subject_id%></v>\r\n    </td>\r\n\r\n\r\n    <td>\r\n        <b>HN : </b><v><%=patient.hn%></v>\r\n    </td>\r\n\r\n    <td>\r\n        <b>Patient Name : </b><v><%=patient.prefix_name%><%=patient.first_name%> <%=patient.last_name%></v>\r\n    </td>\r\n    <td>\r\n        <b>Gender : </b><v><%=patient.gender%></v>\r\n    </td>\r\n    <td>\r\n        <b>Age : </b><v><%=((record.date - patient.birth_date.to_datetime)/(3600*24*365)).to_i if patient and patient.birth_date%> ปี</v>\r\n    </td>\r\n    \r\n    \r\n</tr>    \r\n</table>\r\n\r\n\r\n\r\n<p>\r\n\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   m_visit = {}\r\n   models[:visit_item].where(:visit_id=>record.id).each do |i|\r\n       m_visit[i.item_id] = i \r\n   end\r\n   \r\n   \r\n   periods = models[:pl_period].where(:sheet_id=>sheet.id).order(:sort_order).all\r\n   \r\n   now = 0 \r\n   periods.each_with_index do |i,index|\r\n       if period==i\r\n          now = index \r\n       end\r\n   end\r\n   now += 1\r\n   \r\n   now = periods.size-1 if now == periods.size\r\n   \r\n   next_visit = periods[now].id\r\n   \r\n   \r\n   \r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n<script>\r\n    $(\'.admin\').hide()\r\n</script>\r\n\r\n<br/>\r\n<hr/>\r\n<%= form_for :visit, :url=>\"process?id=\\\\#{params[:id]}\" do |f| \r\n    \r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n    <h3>Protocol : <v><%= sheet.name%></v> Version : <v> <%=sheet.version%></v> Visit : <v><%=period.visit%></v> at <v><%=record.date.strftime(\"%d/%m/%Y\")%></v></h3><br/>\r\n</div>\r\n<%=hidden_field_tag :return, params[:return] %>\r\n\r\n<table class=\"table span12\"  >\r\n    <thead>\r\n        <th>No.</th> <th>Detail</th> <th>Code</th> <th>Group</th> <th>Check List</th> <th style=\"width:200px\">Note</th> \r\n    </thead>\r\n    <tbody>\r\n        <%  \r\n            items = []\r\n             \r\n            period_items.each_with_index do |pi,index| \r\n                \r\n            items <<  pimap[pi.id] if pimap[pi.id]\r\n                \r\n            end\r\n        \r\n            items.each_with_index do |i,index| \r\n            \r\n           \r\n            item = nil\r\n            \r\n            p = m_products[i.product_id]\r\n            \r\n            item = m_visit[i.id]\r\n            \r\n            note = \"\"\r\n            note = item.note  if item\r\n            check = true\r\n            check = false unless item\r\n            check = true if record.status ==nil or record.status ==\"\"\r\n        %>\r\n        <tr>\r\n         <th><%= index+1%>.</th>\r\n         <td><%= p.code%></td>\r\n         <td><%= p.name%></td>\r\n         <td><%= p.group_code%></td>\r\n         <td><%= check_box_tag \"check[\\\\#{i.id}]\", true, false %></td>\r\n         <td><%= text_field_tag \"note[\\\\#{i.id}]\", note%></td>\r\n\r\n\r\n         </tr>\r\n           <% end %>\r\n    </tbody>\r\n</table>\r\n<br/>\r\n</div>\r\n<br/>\r\n\r\n<% end %>\r\n\r\n\r\n<script>\r\n    window.print()\r\n    window.close()\r\n</script>\r\n</body>\r\n</html>',NULL,NULL,NULL,'2018-06-06 17:31:52','2018-06-06 17:31:52','print',''),(3515,'create',1385,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<% link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</di