      \r\n  end\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"../Project/show?id=<%=record.project_id%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', \"show?id=\\\\#{params[:id]}\" %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n<script>\r\n    // $(\'.admin\').hide()\r\n    <% if sheet %>\r\n        $(\'#data-patient_id option\').each(function(){\r\n            option = $(this).attr(\"value\")\r\n            if(option!=\"<%=record.patient_id%>\"){\r\n                $(this).remove()\r\n            }\r\n        })\r\n    \r\n        $(\'#data-project_id option\').each(function(){\r\n            option = $(this).attr(\"value\")\r\n            if(option!=\"<%=project.id%>\"){\r\n                $(this).remove()\r\n            }\r\n        })\r\n    \r\n        // $(\'#data-sheet_id option\').each(function(){\r\n        //     option = $(this).attr(\"value\")\r\n        //     if(option!=\"<%=sheet.id%>\"){\r\n        //         $(this).remove()\r\n        //     }\r\n        // })\r\n        \r\n        var sheets = <%=sheets.collect{|i| i.id}.to_json.html_safe %>\r\n        $(\'#data-sheet_id option\').each(function(){\r\n            option = $(this).attr(\"value\")\r\n            if(sheets.indexOf(option)==-1){\r\n                $(this).remove()\r\n            }\r\n        })\r\n        \r\n        var periods = <%=periods.collect{|i| i.id}.to_json.html_safe %>\r\n        $(\'#data-period_id option\').each(function(){\r\n            option = $(this).attr(\"value\")\r\n            if(periods.indexOf(option)==-1&&option!=\'\'){\r\n                $(this).remove()\r\n            }\r\n        })\r\n        \r\n    <% end %>\r\n</script>',NULL,NULL,NULL,'2018-06-07 01:50:22','2018-06-07 01:50:22','edit',''),(3517,'index',1387,2,'<h1>Hello world</h1><br>\n<i>This is generated by system.</i>',NULL,NULL,NULL,'2018-06-08 04:11:17','2018-06-08 04:11:17',NULL,NULL),(3518,'layout',1387,4,'<%=default_layout%>',NULL,NULL,NULL,'2018-06-08 04:11:17','2018-06-08 04:11:17',NULL,NULL),(3519,'document_name',1388,1,'\'member\'',NULL,NULL,NULL,'2018-06-08 04:13:32','2018-06-08 04:13:32',NULL,NULL),(3520,'create',1388,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<% link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n      \r\n    next_number = 0\r\n    last = model.last\r\n    if last\r\n        next_number = last.member_no.to_i+1\r\n    else\r\n        next_number =1\r\n    end   \r\n    \r\n    params[:record][:member_no] = format(\"%06d\" ,next_number)\r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-06-08 05:25:52','2018-06-08 05:25:52','create',''),(3521,'document_name',1389,1,'\'account\'',NULL,NULL,NULL,'2018-06-08 06:28:04','2018-06-08 06:28:04',NULL,NULL);
INSERT INTO `esm_operations` VALUES (3522,'certify_report',522,2,'<h1> Certify Report </h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n</style>\r\n\r\n<%\r\n\r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    \r\n    \r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    \r\n    \r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-25\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-25\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    providers = models[:provider].where(:provider_type=>\'1\').sort(:name).all\r\n    \r\n    provider_id = nil \r\n    provider_id = params[:report][:provider] if params[:report]\r\n    \r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nFrom : <%= f.date_select :from_date, :default=>from_date ,:discard_day=>true , :order=>[:month,:year],:start_year=>2008%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date ,:discard_day=>true , :order=>[:month,:year],:start_year=>2008%>\r\n<br/>\r\nEndoscopist : <%= f.select :provider, options_for_select(providers.collect{|i| [i.name, i.id] }, provider_id ), :class=>\'provider\'%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n<hr/>\r\n\r\n<% if request.post?  \r\n\r\n\r\n    provider = models[:provider].find(params[:report][:provider])\r\n  \r\n\r\n    colono_reports = models[:colonoscopy].where(:endoscopist_1=>provider.id, :date_note=>{\'$gte\'=>from_date, \'$lte\'=>to_date }).all\r\n    gastro_reports = models[:gastroscopy].where(:endoscopist_1=>provider.id, :date_note=>{\'$gte\'=>from_date, \'$lte\'=>to_date }).all\r\n\r\n\r\n\r\n\r\n%>\r\n<div class=\"wbox\" id=\"certificate\" style=\"border:0px solid\">\r\n\r\n    <div class=\"hide\" style=\"border:1px solid ;width:800px;height:400px;font-size:1.5em;font-family: \'Times New Roman\', Times, serif;padding:20px;\">\r\n    <br/>  <br/>\r\n    <center>\r\n        <h2>Certificate of Endoscopist Training Fellowship Program</h2><br/><br/>\r\n        \r\n        This is to certify that <br/><br/><br/><br/>\r\n        \r\n        <span style=\"font-size:1.2em\"><%=provider.name %></span> <br/><br/><br/><br/>\r\n        \r\n        Has successfull completed<br/><br/><br/><br/><br/>\r\n        \r\n    </center>\r\n    \r\n    <div class=\"row-fluid\" style=\"font-size:0.8em\">\r\n        <div class=\"span4\" style=\"border-top:1px solid\">\r\n            <center>Signature</center>\r\n        </div>\r\n        <div class=\"span4\">\r\n            <center><%=Time.now.strftime(\"%d %B %Y\")%></center>\r\n        </div>\r\n        <div class=\"span4\" style=\"border-top:1px solid\">\r\n            <center>Signature</center>\r\n        </div>\r\n        \r\n    </div>\r\n    \r\n    </div>\r\n    \r\n    <div style=\"border:1px solid ;width:800px;font-family: \'Times New Roman\', Times, serif;padding:20px;margin-top:20px\">\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span4\">\r\n            <h3>Colonoscopy</h3>\r\n    </div>\r\n    <div class=\"span3\">\r\n         \r\n    </div>\r\n    <div class=\"span5\">\r\n            <right>Report from : <%=from_date.strftime(\"%d %B %Y\")%> - :<%= to_date.strftime(\"%d %B %Y\")%></right>\r\n    </div>\r\n    </div>\r\n       <hr/>\r\n       \r\n      <%\r\n    \r\n        normal = 0 \r\n        detect = 0\r\n        other  = 0 \r\n        proc_map = {}\r\n        \r\n        #  if dg and (dg.downcase.index(\'polyp\') or dg.index(\'Cancer\') or dg.index(\'Polyposis\') or dg.index(\'Submucosal\'))\r\n        #             endos[endoscopist][\'adr\'] = 0 unless endos[endoscopist][\'adr\']\r\n        #             endos[endoscopist][\'adr\'] += 1\r\n        #         end\r\n        \r\n        \r\n        colono_reports.each do |i|\r\n            \r\n        dg = i.diagnosis_group\r\n        \r\n        if dg and (dg.downcase.index(\'polyp\') or dg.index(\'Cancer\') or dg.index(\'Polyposis\') or dg.index(\'Submucosal\'))\r\n            detect+=1\r\n        elsif i.diagnosis_group==\'Normal\'    \r\n            normal+=1\r\n        else\r\n            other+=1    \r\n        end\r\n        \r\n        i.procedure.split(\"|\").each do |j|\r\n        \r\n        if j.strip.size>0\r\n        proc_map[j] = [] unless proc_map[j]\r\n        proc_map[j] << i\r\n        end\r\n        \r\n        end\r\n        \r\n        \r\n        \r\n        end\r\n    \r\n        total = colono_reports.size\r\n        rate = (detect).to_f/total*100\r\n    \r\n    %>\r\n     <%\r\n        \r\n        evaluation=\'Failed\'\r\n        eval_class=\'failed\'\r\n        \r\n        if rate > 0.3 && total > 400\r\n            evaluation=\'Pass\'\r\n            eval_class=\'pass\'     \r\n        end\r\n        \r\n        if(to_date - from_date)/3600/24< 350\r\n            \r\n            evaluation=\'Not available\'\r\n            eval_class=\'na\'   \r\n        end\r\n    \r\n    %>\r\n   <style>\r\n       .failed{\r\n           color:red;\r\n       }\r\n       .pass{\r\n           color:green;\r\n       }\r\n       .na{\r\n           color:orange;\r\n       }\r\n       tr{\r\n           padding:20px;\r\n       }\r\n   </style>\r\n    <div class=\"row-fluid\">\r\n        <div class=\"span12\" style=\"font-size:1.5em\">\r\n            <table class=\"row-fluid\" cellpadding=\"10\">\r\n                <tr>\r\n                    <td  align=\"right\" style=\"width:200px\">\r\n                        Total case : \r\n                    </td>\r\n                    <td align=\"center\"  style=\"width:200px\" >\r\n                        <%= total %> cases\r\n                    </td>\r\n                    <td style=\"width:200px\"  align=\"right\">\r\n                        Evalutation : \r\n                    </td>\r\n                    <td class=\"<%=eval_class%>\"  align=\"center\">\r\n                        <%= evaluation %>\r\n                        \r\n                        <%\r\n                            id = nil\r\n                            \r\n                            cert = models[:certificate].where(:provider_id=>provider_id).first\r\n                            if cert\r\n                            id = cert.id\r\n                        %>\r\n                        <%= link_to \'Print\', \"../Certificate/issue?id=\\\\#{id}\", :class=>\"btn\", :target=>\'_blank\' %>\r\n                        \r\n                        <% end %>\r\n                    </td>\r\n                </tr>\r\n                \r\n                <tr>\r\n                    <td align=\"right\">\r\n                        Polyp detection rate : \r\n                    </td>\r\n                    <td  align=\"center\">\r\n                        <%= format(\"%.2f\",rate) %> %\r\n                    </td>\r\n                </tr>\r\n                \r\n                <tr>\r\n                    <td align=\"right\" valign=\"top\">\r\n                        Procedure detail : \r\n                    </td>\r\n                    <td  align=\"left\" colspan=\"3\" >\r\n                       <table cellpadding=\"10\">\r\n                        <tr>\r\n                        <% \r\n                        count =0  \r\n                        proc_map.each_pair do |k,v| %>\r\n                        \r\n                        <td><%=k %> : <%= v.size %> cases</td>\r\n                        <% if count%2==1 %>\r\n                        </tr>\r\n                        <tr>\r\n                        <% end %>\r\n                        <%\r\n                        count+=1\r\n                        %>\r\n                        <% end %>\r\n                        </tr>   \r\n                       </table>\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </div>\r\n    </div>\r\n\r\n   \r\n    \r\n    \r\n    </div>\r\n    <div style=\"border:1px solid ;width:800px;font-family: \'Times New Roman\', Times, serif;padding:20px;margin-top:20px\">\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span4\">\r\n            <h3>Gastroscopy</h3>\r\n    </div>\r\n    <div class=\"span3\">\r\n         \r\n    </div>\r\n    <div class=\"span5\">\r\n            <right>Report from : <%=from_date.strftime(\"%d %B %Y\")%> - :<%= to_date.strftime(\"%d %B %Y\")%></right>\r\n    </div>\r\n    </div>\r\n       <hr/>\r\n     <div class=\"row-fluid\">\r\n     <div class=\"span12\" style=\"font-size:1.5em\">\r\n            <table class=\"row-fluid\" cellpadding=\"10\">\r\n                <tr>\r\n                    <td  align=\"right\" style=\"width:200px\">\r\n                        Total case : \r\n                    </td>\r\n                    <td align=\"center\"  style=\"width:200px\" >\r\n                        <%= gastro_reports.size %> cases\r\n                    </td>\r\n                    <td style=\"width:200px\"  align=\"right\">\r\n                      \r\n                    </td>\r\n                    <td class=\"<%=eval_class%>\"  align=\"center\">\r\n                        \r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        \r\n    </div>\r\n    </div>\r\n    \r\n</div>\r\n\r\n\r\n\r\n<% end %>\r\n\r\n<style>\r\n    .provider{\r\n        width:400px;\r\n    }\r\n</style>\r\n\r\n\r\n<%=link_to \'Manage Certificate\',\"../Certificate/index\" if @current_role==\'admin\' or@current_role==\'developer\'%>\r\n\r\n\r\n',NULL,NULL,NULL,'2018-06-08 07:12:10','2018-06-08 07:12:10','certify_report',''),(3527,'print_partial',490,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[this.document_name.to_sym].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:70px;min-height:7-;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'<%=@current_project.get_setting(\'logo_report_path\')%>\' height=\'70px\' style=\"Float:left,top:5px\" /></div><h3> <strong><%=@current_service.title %> Diagnosis Report<br />\r\n<%=@current_project.get_setting(\"report_title_1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%>\r\n  </strong></h3>\r\n</center>\r\n\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> ชื่อ-สกุล : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'ไม่ระบุ\'\r\n    if patient.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>เพศ : </strong><%= gender %> &nbsp; <strong>อายุ :&nbsp;</strong>\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D-->\r\n      <br /><strong>Date :  </strong> <%=render_value \'start_procedural_date\'%> <strong>Produral Time :  </strong> <%=render_value \'start_procedural_time\'%> - <%=render_value \'stop_procedural_time\'%> Total Time :  <%=render_value \'procedural_time\'%>  <strong>Project : </strong> <%=render_value \'study_project\'%>\r\n    <br /><strong>Endoscopist : </strong><%=render_value \'endoscopist\'%>  , <strong>Endoscopist assist : </strong><%=render_value \'assist1endoscopist\'%> <%=render_value \'assist2endoscopist\'%> \r\n    <br /><strong>Nurse : </strong><%=render_value \'nurse\'%> , <strong>Nurse assist : </strong><%=render_value \'assist_1_nurse\'%><%=render_value \'assist_2_nurse\'%>\r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n &nbsp;&nbsp;&nbsp;<strong>Indication : </strong><%=render_value \'clinical_indication\'%><%=render_value \'indication_other_note\'%>\r\n	<hr style=\"margin-top: 5px;\"/>\r\n    <%\r\n        # atts = models[:attachment].limit(5).find(record.image)\r\n       \r\n       atts_list = record.image[0..4]\r\n       if record.selected_image and record.selected_image.size > 0\r\n          \r\n           atts_list = record.selected_image[0..4]\r\n           \r\n       end\r\n       \r\n       \r\n       atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n       \r\n       \r\n\r\n\r\n    %>\r\n\r\n\r\n<style>\r\n<% if @current_solution.name!=\'gi\' %>\r\n.crop {\r\n    width: 300px;\r\n    overflow: hidden;\r\n    margin-bottom:10px;\r\n}\r\n\r\n.crop img {\r\n    width: 100%;\r\n max-width: 270px;\r\n    margin: 0px;\r\n min-height: 170px;\r\n}\r\n<% else %>\r\n.crop {\r\n    width: 240px;\r\n    /*height: 165px;*/\r\n    margin:5px;\r\n}\r\n\r\n.crop img {\r\n    // width: 240px;\r\n    height: 165px;\r\n}\r\n<% end %>\r\n    \r\n</style>\r\n    <div style=\"float:right;  width: 280px;  padding: 5px; text-align:center; font-size:14px;\">\r\n    <% for i in atts  %>\r\n    <div class=\"crop\">\r\n    <img src=\"<%=i.path%>\" /><br /><span style=\"margin-left:0px;border:0px solid;width:100%;display:block\"><%=i.title%></span><br />\r\n    </div>\r\n    <% end %>\r\n\r\n\r\n   \r\n    \r\n    </div>\r\n\r\n<div style=\"float:left\">\r\n\r\n\r\n<table width=\"550\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr><td valign=\"top\"><strong>Consent</strong></td><td>The procedure of the examination, including possible complications were clearly and discussed with the patient and family, then a consent form was signed by the patient and/or family</td></tr>\r\n<tr><td valign=\"top\"><strong>Procedure</strong></td>\r\n  <td>The patient\'s blood pressure, pulse and oxygen saturation were montiored ontinuously throghout the procedure. the scope was passed under direct  vision through the mouth and advanced to the duodenum. The endoscopy was accomplished without difficulty. The findings were described below. The patient tolerated the procedure well.</td></tr>\r\n</table>\r\n<div class=\"clear\"></div>\r\n\r\n<%= render :inline=>this.display %>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n<strong>Reported by :</strong>&nbsp;<%=render_value \'recorder\'%><br />\r\n<strong>Printed Date Time :</strong>&nbsp;<%=render_value \'date_approve\' %> <%=render_value \'time_approve\'%>\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong><% if record[\'approve\']!=\"\" %>Approved<% end %> By :</strong> \r\n<%=render_value \'endoscopist_approve\'%> (Gastroenterologist)\r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<script>\r\n\r\n<%\r\n        require \'csv\'\r\n        icd10_list = {}\r\n        CSV.foreach(File.join(Dir.pwd,\'public\',\'/esm/cusys/med/icd-10.csv\')) do |row|\r\n           icd10_list[row[0]]=row[1] \r\n        end\r\n        \r\n%>\r\n    \r\n    var icd10_list = <%=icd10_list.to_json.html_safe%>\r\n    icd = $(\'#data-icd10\').val()\r\n    licd = icd.split(\'|\')\r\n    div = $(\'#diagnosis-div\')\r\n    tr = div.parent().parent()\r\n    icd = $(\"<tr>\").append(\"<td><strong>ICD</strong></td>\")\r\n    for(var id in licd){\r\n        i = licd[id]\r\n        icd.append($(\'<p>\').append(\"<v>\"+i+\"</v> : \"+icd10_list[i]))\r\n        \r\n    }\r\n    tr.after(icd)\r\n    \r\n    \r\n    \r\n    \r\n</script>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2018-06-19 04:28:55','2018-06-19 04:28:55','print_partial',''),(3528,'export',1321,3,'<table>\r\n<%\r\n @document = get_document(this.document_name)\r\n\r\n model = get_model[this.document_name]\r\n \r\n list = model.all \r\n fields = @document.list_fields\r\n \r\n %>\r\n<tr>\r\n<% for i in fields %>\r\n<td><%= i.column_name %></td>\r\n<% end %>\r\n    \r\n</tr>\r\n<%\r\n for i in list\r\n @record = i \r\n%>\r\n<tr>\r\n<% for f in fields %>\r\n<td>\r\n<%= render_value f.column_name  %>\r\n</td><% end %>\r\n</tr>\r\n<% end %>\r\n</table>',NULL,NULL,NULL,'2018-06-20 06:14:20','2018-06-20 06:14:20','export',''),(3530,'process',1385,2,'<%\r\n\r\n\r\n  models = get_model\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  \r\n  project = models[:project].find(record.project_id)\r\n  sheet = models[:pl_sheet].find(record.sheet_id)\r\n  \r\n  period = models[:pl_period].find(record.period_id)\r\n  patient = models[:patient].find(record.patient_id)\r\n  \r\n  period_items  = models[:pl_period_product].where(:sheet_id=>sheet.id).all\r\n  \r\n  m_products = Hash[models[:pl_product].find(period_items.collect{|i| i.product_id}).map{|i| [i.id, i]}]\r\n  items = []\r\n  items  = models[:pl_period_item].where(:sheet_id=>sheet.id, :period_id=>period.id).all if period\r\n \r\n  status = record.status\r\n  pharmacist_status = record.pharmacist_status\r\n  \r\n  if params[:snsc_submit] == \'true\'\r\n      \r\n      if params[:commit]==\'Save Draft\'\r\n            status=\"Draft\"\r\n      else\r\n            status=\"Completed\"\r\n            models[:entry_log].log @current_user.login, \'Visit\', \'complete\', \"../Visit/show?id=\\\\#{record.id}\"\r\n\r\n\r\n            \r\n      end\r\n  end\r\n  \r\n  if params[:pharmacist_submit] == \'true\'\r\n      \r\n      \r\n      if params[:commit]==\'Save Draft\'\r\n            pharmacist_status=\"Draft\"\r\n      else\r\n          models[:entry_log].log @current_user.login, \'Pharmacist\', \'complete\', \"../Visit/show?id=\\\\#{record.id}\"\r\n           pharmacist_status=\"Completed\"\r\n       end\r\n  end\r\n  \r\n  \r\n  date = record.date\r\n  \r\n  if params[:visit_date]\r\n     t = params[:visit_date].split(\"/\").reverse.collect{|i| i.to_i}\r\n     date = Date.new t[0],t[1],t[2]\r\n      \r\n  end\r\n  \r\n  record.update_attributes :status=>status, :pharmacist_status=>pharmacist_status\r\n  record.update_attributes  :name=>params[:visit_name], :date=>date, :traveling_note=>params[:visit_traveling_note], :traveling_status=>params[:visit_traveling_status], :traveling_amount=>params[:visit_traveling_amount], :traveling_extra=>params[:visit_traveling_extra]\r\n  \r\n  \r\n  \r\n\r\n  \r\n  \r\n  \r\n  \r\n  models[:visit_item].where(:visit_id=>record.id).each do |i|\r\n     i.destroy \r\n  end\r\n\r\n   models[:visit_item_bom].where(:visit_id=>record.id).each do |i|\r\n     i.destroy \r\n  end\r\n  \r\n   models[:visit_tissue].where(:visit_id=>record.id).each do |i|\r\n     i.destroy \r\n  end\r\n  \r\n  if params[:check]\r\n     \r\n    for i in items\r\n        \r\n        done = false\r\n    \r\n        status = \'Not Done\'    \r\n        \r\n        if  params[:check][i.id.to_s] == \'true\'\r\n            status = \'Done\' \r\n            done = true\r\n        end\r\n        \r\n        note = params[:note][i.id.to_s] if params[:note]\r\n        \r\n        cost = params[:cost][i.id.to_s] if params[:cost]\r\n        price = params[:price][i.id.to_s] if params[:price]\r\n        vendor = params[:vendor][i.id.to_s] if params[:vendor]\r\n        \r\n        \r\n        \r\n        \r\n        models[:visit_item].create :visit_id=>record.id, :edited_by=> params[:edited_by][i.id.to_s], :product_id=>i.product_id, :item_id=>i.id, :done=>done, :status=>status, :note=>note, :cost=>cost, :price=>price, :vendor_code=>vendor\r\n        \r\n        if params[:sub_vendor] and params[:sub_vendor][i.id.to_s]\r\n           \r\n           params[:sub_vendor][i.id.to_s].each_pair do |k,v|\r\n              \r\n            p = models[:pl_product].find v\r\n            \r\n            if p\r\n                \r\n                 models[:visit_item_bom].create :visit_id=>record.id, :cost=> p.cost, :price=>p.price, :vendor_code=>p.vendor_code, :bom_id=> k, :item_id=>i.id, :product_id=>p.id\r\n                \r\n            end\r\n               \r\n           end\r\n            \r\n            \r\n        end\r\n        \r\n        \r\n            \r\n        # if params[:check][i.id.to_s]\r\n            \r\n        #     note = params[:note][i.id.to_s] if params[:note]\r\n        #     models[:visit_item].create :visit_id=>record.id, :product_id=>i.product_id, :item_id=>i.id, :done=>true, :status=>\'Done\', :note=>note\r\n            \r\n            \r\n        # else\r\n        \r\n        #     note = params[:note][i.id.to_s] if params[:note]\r\n        #     models[:visit_item].create :visit_id=>record.id, :product_id=>i.product_id, :item_id=>i.id, :done=>false, :status=>\'Not Done\', :note=>note\r\n        \r\n        \r\n        # end\r\n        \r\n        \r\n        \r\n    \r\n    \r\n    end\r\n      \r\n      \r\n  end\r\n  if params[\'item_id\'] and params[\'item_item\'] and params[\'item_price\'] and params[\'item_vendor\'] and params[\'item_quantity\']\r\n\r\n     params[\'item_id\'].each_with_index do |i,index| \r\n        \r\n         item =  models[:visit_item].create  :visit_id=>record.id,:project_item_id=>params[\'item_item\'][index], :price=>params[\'item_price\'][index],:vendor_code=>params[\'item_vendor\'][index], :product_id=>i, :done=>true, :status=>\'Done\', :note=>params[\'item_note\'][index],\r\n          :quantity=>params[\'item_quantity\'][index],:item_type=>params[\'item_item_type\'][index]\r\n         \r\n         \r\n         \r\n         \r\n          if params[:sub_vendor_item] and params[:sub_vendor_item][item.project_item_id.to_s]\r\n           \r\n           params[:sub_vendor_item][item.project_item_id.to_s].each_pair do |k,v|\r\n              \r\n            p = models[:pl_product].find v\r\n            \r\n            if p\r\n                \r\n                 models[:visit_additional_item_bom].create :visit_id=>record.id, :cost=> p.cost, :price=>p.price, :vendor_code=>p.vendor_code, :bom_id=> k, :item_id=>item.id, :product_id=>p.id\r\n                \r\n            end\r\n               \r\n           end\r\n            \r\n            \r\n        end\r\n         \r\n         \r\n     end\r\n     \r\n  end\r\n  \r\n  \r\n    if params[\'item2_id\']\r\n     \r\n     params[\'item2_id\'].each_with_index do |i,index| \r\n        \r\n          models[:visit_item].create  :visit_id=>record.id,:project_item_id=>params[\'item_item\'][index], :product_id=>i, :done=>true, :status=>\'Done\', :note=>params[\'item2_note\'][index],\r\n          :item_type=>params[\'item2_item_type\'][index], :price=>params[\'item2_price\'][index], :cost=>params[\'item2_cost\'][index],:quantity=>params[\'item_quantity\'][index]\r\n         \r\n     end\r\n     \r\n  end\r\n  \r\n  \r\n    if params[\'item3_id\']\r\n\r\n     params[\'item3_id\'].each_with_index do |i,index| \r\n        \r\n          models[:visit_item].create  :visit_id=>record.id, :product_id=>i, :done=>true, :status=>\'Done\', :note=>params[\'item3_note\'][index],\r\n          :quantity=>params[\'item3_quantity\'][index],:item_type=>params[\'item3_item_type\'][index]\r\n         \r\n     end\r\n     \r\n  end\r\n  \r\n#   \"un-visit\"=>[\"5b0275a3790f9b466d0001be\", \"5b0275a3790f9b466d0001bc\", \"5b0275a3790f9b466d0001ba\"], \"un-visit-note\"=>[\"df\", \"wfw\", \"were\"]\r\n \r\n#   \"tissue\"=>[\"fadsf\", \"ads\"], \"tissue-type\"=>[\"a\", \"dsfa\"], \"tissue-note\"=>[\"sdf\", \"asdfadsf\"], \r\n\r\n    if params[\'tissue\']\r\n        \r\n        params[\'tissue\'].each_with_index do |i,index| \r\n            \r\n            type = nil \r\n            type = params[\'tissue-type\'][index] if params[\'tissue-type\'] and params[\'tissue-type\'][index]\r\n            note = nil \r\n            note = params[\'tissue-note\'][index] if params[\'tissue-note\'] and params[\'tissue-note\'][index]\r\n           \r\n            models[:visit_tissue].create  :visit_id=>record.id, :name=>i, :type=>type, :note=>note\r\n            \r\n            \r\n        end\r\n    \r\n    end\r\n    \r\n    if params[:ip_visit] and params[:ip_patient] and params[:ip_item]\r\n       \r\n        params[:ip_item].each_with_index do |i,index|\r\n           \r\n           item_id = i\r\n           lot,exp = params[:ip_lot][index].split(\"|\")\r\n           quantity = params[:ip_quantity][index].to_i\r\n           current_card = models[:ip_card].where(:visit_id=>params[:ip_visit], :item_id=>item_id).first\r\n           note = params[:ip_note][index]\r\n          \r\n           if quantity > 0 \r\n               \r\n                current_card= models[:ip_card].create :item_id=>item_id, :lot=>lot,:expired_date=>exp, :visit_id=>params[:ip_visit], :patient_id=>params[:ip_patient], :status=>\'out\' unless current_card \r\n                \r\n                current_card.update_attributes :quantity=>quantity, :note=>note\r\n          \r\n           else\r\n                current_card.destroy if current_card\r\n               \r\n           end\r\n            \r\n        end\r\n        \r\n        \r\n    end\r\n    \r\n    \r\n \r\n \r\n%>\r\n<h1>Processing..</h1>\r\n\r\n<% if true %>\r\n<meta http-equiv=\"refresh\" content=\"0; url=<%=\"show?id=\\\\#{params[:id]}\" %>\" />\r\n<% else %>\r\n<%= params.inspect %>\r\n<% end %>',NULL,NULL,NULL,'2018-06-30 17:39:14','2018-06-30 17:39:14','process',''),(3531,'display',1383,3,'\r\n<%\r\n    models = get_model\r\n   model = models[:patient]\r\n  record = model.find(params[:id])\r\n  @show=true\r\n  \r\n  visit = models[:visit].where(:patient_id=>record.id, :date=>{\'$gte\'=>Time.now.beginning_of_day,\'$lte\'=>Time.now.end_of_day}).first\r\n  visits = models[:visit].where(:patient_id=>record.id).all\r\n  \r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n\r\n\r\n<script>\r\n    $(\"#image\").hide();\r\n</script>',NULL,NULL,NULL,'2018-07-01 04:44:00','2018-07-01 04:44:00','display',''),(3532,'show',1383,2,'       <link rel=\"stylesheet\" href=\"/gebo/lib/fullcalendar/fullcalendar_gebo.css\" />	\r\n			<script src=\"/gebo/lib/fullcalendar/fullcalendar.min.js\"></script>\r\n			<script src=\"/gebo/lib/fullcalendar/gcal.js\"></script>\r\n\r\n\r\n<%\r\n    begin \r\n\r\n    models = get_model\r\n\r\n    record = models[:patient].find params[:id]\r\n\r\n    return_url = \"../Project/show?id=\\\\#{record.project_id}\"\r\n     return_url = params[:return] if params[:return]\r\n     \r\n     \r\n    visit = models[:visit].where(:patient_id=>record.id, :date=>{\'$gte\'=>Time.now.beginning_of_day,\'$lte\'=>Time.now.end_of_day}).first\r\n    \r\n    \r\n    has_next = models[:visit].where(:patient_id=>record.id, :date=>{\'$gt\'=>Time.now.end_of_day}).all\r\n\r\n    \r\n   visits = models[:visit].where(:patient_id=>record.id).all\r\n   \r\n   last = nil\r\n   unless visit\r\n   visit = visits[-1] \r\n   last = true\r\n   end\r\n   \r\n    \r\n    project = models[:project].find record.project_id\r\n    \r\n \r\n   \r\n%>\r\n\r\n\r\n<%\r\n    patient = record\r\n    \r\n    protocol_version = \'-\'\r\n    \r\n    sheet = models[:pl_sheet].find patient.sheet_id\r\n    if sheet\r\n        protocol_version = sheet.version    \r\n    end\r\n    \r\n\r\n   \r\n%>\r\n    <div id=\"jCrumbs\" class=\"breadCrumb module\">\r\n        <div style=\"overflow:hidden; position:relative; width: 1316px;\"><div><ul style=\"width: 500px;\">\r\n            <li class=\"first\">\r\n                <a href=\"../Home/index\"><i class=\"icon-home\"></i></a>\r\n            </li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Project/index\" style=\"width: 84px;\">Projects</a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Project/show?id=<%=project.id%>\" style=\"width: 94px;\"><%=project.protocol_no%></a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Project/show?id=<%=project.id if sheet%>\" style=\"width: 134px;\"><%=protocol_version%></a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li class=\"last\" style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><%=patient.subject_id%> <%=patient.first_name%> <%=patient.last_name%></span>\r\n           </li>\r\n           \r\n        </ul></div></div>\r\n    </div>\r\n</nav>\r\n\r\n\r\n<style>\r\nv{\r\n      color:blue;\r\n  }\r\n</style>\r\n\r\n\r\n<table class=\"table table-striped table-bordered table-condensed\">\r\n<tr>\r\n\r\n    <td>\r\n        <b>Subject ID : </b><v><%=patient.subject_id%></v>\r\n    </td>\r\n\r\n\r\n    <td>\r\n        <b>HN : </b><v><%=patient.hn%></v>\r\n    </td>\r\n\r\n    <td>\r\n        <b>Patient Name : </b><v><%=patient.prefix_name%><%=patient.first_name%> <%=patient.last_name%></v>\r\n    </td>\r\n    <td>\r\n        <b>Gender : </b><v><%=patient.gender%></v>\r\n    </td>\r\n    <td>\r\n        <b>Age : </b><v><%=((Time.now - patient.birth_date.to_datetime)/(3600*24*365)).to_i if patient and patient.birth_date%> ปี</v>\r\n    </td>\r\n    \r\n    \r\n</tr>    \r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n\r\n\r\n\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n\r\n<div class=\"tabbable tabbable-bordered\">\r\n<ul class=\"nav nav-tabs\">\r\n\r\n\r\n	<li class=\"active\" ><a href=\"#tab_br1\" data-toggle=\"tab\" class=\"tab_btn\">General Information</a></li>\r\n	<li ><a href=\"#tab_br2\" data-toggle=\"tab\" class=\"tab_btn\">Schedule</a></li>\r\n    <li ><a href=\"#tab_br3\" data-toggle=\"tab\" class=\"tab_btn\">History</a></li>\r\n		<!--<li ><a href=\"#tab_br4\" data-toggle=\"tab\" class=\"tab_btn\" >Other Schedule</a></li>-->\r\n\r\n\r\n</ul>\r\n<div class=\"tab-content\">\r\n\r\n<div class=\"tab-pane active\" id=\"tab_br1\">\r\n<p>\r\n    <div class=\"\" style=\"border:0px solid\">\r\n    <%= this.display.html_safe %><br/>\r\n    <%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-info\' %> |\r\n    \r\n    <%= link_to \'Destory\'.html_safe, \"destroy?id=\\\\#{params[:id]}\",:class=>\'btn btn-danger\' ,:data=>{:confirm=>\'Are you sure?\'} %> \r\n    </div>				\r\n</p>\r\n</div>\r\n\r\n<div class=\"tab-pane\" id=\"tab_br2\">\r\n<h3>Schedule & Appointment</h3>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span4\">\r\n<%\r\n\r\n\r\n    events = []\r\n\r\n      \r\n      \r\n        list = models[:visit].where(:patient_id=>params[:id]).all\r\n        \r\n\r\n       \r\n        events = list.clone\r\n    \r\n    \r\n             events.collect!{|e|  \r\n    \r\n               \r\n                \r\n            \r\n                    # period = models[:pl_period].find e.period_id\r\n                    # project = mprojects[e.project_id]\r\n                    # patient = models[:patient].find e.patient_id\r\n                    # title = \"\\\\#{project.protocol_no} : \\\\#{period.visit if period} : \\\\#{patient.subject_id} : \\\\#{patient.first_name} \\\\#{patient.last_name} \\\\#{\'#\'+e.note if e.note}\"\r\n                    title = \"\\\\#{e.name}\"     \r\n                    \r\n                    date = e.date\r\n                    if date\r\n                       date =  DateTime.parse(e.date.strftime(\"%Y-%m-%d\")+\"T\"+e.date.strftime(\"%H:%M\") )\r\n                    end\r\n    \r\n    			{\r\n    			        :title=>title,\r\n						:start=> date,\r\n						:end=>  date,\r\n						:allDay=> true,\r\n                        :color=> \"#f5eeef\",\r\n                        :textColor=>\"#111\",\r\n                        :url=>\"../Visit/show?id=\\\\#{e.id}\"\r\n                }\r\n    \r\n    }\r\n    \r\n    \r\n        app_list = models[:patient_schedule].where(:patient_id=>params[:id]).all\r\n\r\n        app_events = app_list.collect{ |e|\r\n        \r\n        \r\n                title = \"\\\\#{e.name}\"          \r\n    \r\n    			{\r\n    			        :title=>title,\r\n						:start=> DateTime.parse(e.start_date.strftime(\"%Y-%m-%d\")+\"T\"+e.start_time.strftime(\"%H:%M\") ),\r\n						:end=>  DateTime.parse(e.end_date.strftime(\"%Y-%m-%d\")+\"T\"+e.end_time.strftime(\"%H:%M\")),\r\n						:allDay=> true,\r\n                        :color=> \"#eeeeee\",\r\n                        :textColor=>\"#111\",\r\n                        :url=>\"../PatientSchedule/show?id=\\\\#{e.id}\"\r\n                }\r\n        \r\n       \r\n        \r\n        \r\n    }\r\n        \r\n        events+=app_events\r\n\r\n    \r\n    \r\n%>\r\n\r\n   \r\n    <div id=\"calendar-schedule\" class=\"span12\" style=\"\"></div>\r\n</div>\r\n<div class=\"span8\">\r\n<h3>Schedule Visit  <span style=\"background-color:#f4ebed;width:30px;height:1em;display:inline-block;border:1px solid #cccccc\"></span></h3><br/>\r\n <table class=\"table  table-striped table-bordered table-condensed\">\r\n        <thead>\r\n            <tr>\r\n                <th>No.</th><th>Name</th><th>Visit Type</th><th>Date</th><th>Status</th><th></th><th></th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n        <% list.each_with_index do |i,index| %>\r\n            <tr>\r\n                <td><%=index+1%>.</td>\r\n                <td><%=link_to i.name, \"../Visit/show?id=\\\\#{i.id}\" %></td>\r\n                <td><%=i.visit_type%></td>\r\n                <td><%=i.date.strftime(\"%d/%m/%Y\") if i.date %></td>\r\n                <td><%=i.status%></td>\r\n                \r\n                <td><%=link_to \'Edit\', \"../Visit/edit?id=\\\\#{i.id}&return=\\\\#{request.url}\",:class=>\"\" %></td>\r\n                <td><%=link_to \'Delete\', \"../Visit/destroy?id=\\\\#{i.id}&return=\\\\#{request.url}\",:class=>\"\",:data=>{:confirm=>\'Are you sure?\'} %></td>\r\n\r\n\r\n                \r\n            </tr>\r\n        <% end %>\r\n        </tbody>\r\n        \r\n    </table>\r\n    \r\n    <%\r\n        \r\n        i = record\r\n    \r\n    %>\r\n    <br/>\r\n    <a  class=\'btn btn-info randomize_btn\' visit_type=\'schedule\' patient_name=\"<%=\"\\\\#{i.prefix_name}\\\\#{i.first_name} \\\\#{i.last_name}\" %>\"  patient_id=\"<%=i.id%>\" data-backdrop=\"static\" href=\"#modal-randomize\">Add Schedule Visit</a>\r\n\r\n    <a  class=\'btn btn-default randomize_btn\' visit_type=\'unschedule\' patient_name=\"<%=\"\\\\#{i.prefix_name}\\\\#{i.first_name} \\\\#{i.last_name}\" %>\"  patient_id=\"<%=i.id%>\" data-backdrop=\"static\" href=\"#modal-randomize\">Add UnSchedule Visit</a>\r\n\r\n\r\n    \r\n    <br/><br/>\r\n<h3>Schedule Other <span style=\"background-color:#eeeeee;width:30px;height:1em;display:inline-block;border:1px solid #cccccc\"></span></h3><br/>\r\n    \r\n    <table class=\"table  table-striped table-bordered table-condensed\">\r\n        <thead >\r\n            <tr >\r\n                <th >No.</th><th>Name</th><th>Note</th><th>Date</th><th></th><th></th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n        <% app_list.each_with_index do |i,index| %>\r\n            <tr>\r\n                <td><%=index+1%>.</td>\r\n                <td><%=i.name%></td>\r\n                <td><%=i.note%></td>\r\n                <td><%=i.start_date.strftime(\"%d/%m/%Y\") if i.start_date %> <%=\' - \'+ i.end_date.strftime(\"%d/%m/%Y\") if i.end_date and i.start_date!=i.end_date %></td>\r\n          \r\n                <td><%=link_to \'Edit\', \"../PatientSchedule/edit?id=\\\\#{i.id}&return=\\\\#{request.url}\",:class=>\"\" %></td>\r\n                <td><%=link_to \'Delete\', \"../PatientSchedule/destroy?id=\\\\#{i.id}&return=\\\\#{request.url}\",:class=>\"\",:data=>{:confirm=>\'Are you sure?\'} %></td>\r\n\r\n\r\n                \r\n            </tr>\r\n        <% end %>\r\n        </tbody>\r\n        \r\n    </table>\r\n</div>\r\n</div>\r\n    <script>\r\n        \r\n        \r\n$(document).ready(function() {\r\n		gebo_calendar_schedule.regular();\r\n// 		gebo_calendar.google();\r\n		//* resize elements on window resize\r\n		var lastWindowHeight = $(window).height();\r\n		var lastWindowWidth = $(window).width();\r\n		$(window).on(\"debouncedresize\",function() {\r\n			if($(window).height()!=lastWindowHeight || $(window).width()!=lastWindowWidth){\r\n				lastWindowHeight = $(window).height();\r\n				lastWindowWidth = $(window).width();\r\n				//* rebuild calendar\r\n				$(\'#calendar-schedule\').fullCalendar(\'render\');\r\n				// $(\'#calendar_google\').fullCalendar(\'render\');\r\n			}\r\n		});\r\n		\r\n		$(\'.fc-button-content\').click();\r\n		\r\n	});\r\n	\r\n	//* calendar\r\n	gebo_calendar_schedule = {\r\n		regular: function() {\r\n			var date = new Date();\r\n			var d = date.getDate();\r\n			var m = date.getMonth();\r\n			var y = date.getFullYear();\r\n			var calendar = $(\'#calendar-schedule\').fullCalendar({\r\n				header: {\r\n					left: \'prev next\',\r\n					center: \'title,today\',\r\n					right: \'\'\r\n				},\r\n				buttonText: {\r\n					prev: \'<i class=\"icon-chevron-left cal_prev\" />\',\r\n					next: \'<i class=\"icon-chevron-right cal_next\" />\'\r\n				},\r\n				aspectRatio: 1.5,\r\n				selectable: true,\r\n				selectHelper: true,\r\n				select: function(start, end, allDay) {\r\n				    console.log(start)\r\n				    window.location=\"../PatientSchedule/create?patient_id=<%=params[:id]%>&date=\"+(start);\r\n				    \r\n				// 	var title = prompt(\'Event Title:\');\r\n				// 	if (title) {\r\n				// 		calendar.fullCalendar(\'renderEvent\',\r\n				// 			{\r\n				// 				title: title,\r\n				// 				start: start,\r\n				// 				end: end,\r\n				// 				allDay: allDay\r\n				// 			},\r\n				// 			true // make the event \"stick\"\r\n				// 		);\r\n				// 	}\r\n				// 	calendar.fullCalendar(\'unselect\');\r\n				},\r\n				editable: true,\r\n				theme: false,\r\n				events: <%=events.to_json.html_safe%>,\r\n				eventColor: \'#bcdeee\'\r\n			})\r\n		}\r\n	};\r\n        \r\n        \r\n        \r\n    </script>\r\n    \r\n    \r\n</p>\r\n</div>\r\n\r\n<div class=\"tab-pane\" id=\"tab_br2x\">\r\n<p>\r\n										\r\n<!-- ################################################################################################### --->\r\n\r\n\r\n<%\r\n   if visit  \r\n   \r\n   \r\n   sheet = models[:pl_sheet].find(visit.sheet_id)\r\n   \r\n\r\n   patient = record\r\n   \r\n   \r\n   sheet = models[:pl_sheet].find patient.sheet_id unless sheet\r\n            \r\n    unless sheet \r\n        \r\n     v = models[:visit].where(:patient_id=>patient.id, :sheet_id=>{\'$ne\'=>nil}).first\r\n     sheet = models[:pl_sheet].find v.sheet_id\r\n   \r\n    \r\n    end\r\n  \r\n   \r\n   \r\n   \r\n   period = models[:pl_period].find(visit.period_id)\r\n   periods = []\r\n   periods = models[:pl_period].where(:sheet_id=>sheet.id).order(:sort_order).all if sheet\r\n   \r\n   now = 0 \r\n   periods.each_with_index do |i,index|\r\n       if period==i\r\n          now = index \r\n       end\r\n   end\r\n   now += 1\r\n   \r\n   now = periods.size-1 if now == periods.size\r\n   \r\n   next_visit = periods[now].id if periods[now]\r\n   \r\n   \r\n\r\n now_day = 0\r\n now_day = period.day.to_i if period\r\n \r\n ext_class = \"alert alert-info\"\r\n ext_class = \"\" if has_next.size>0\r\n \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"alert\">\r\n<h3>Last Visit : </h3><br/>\r\n    <div class=\"row-fluid\">\r\n     <div class=\"span6\">Visit Schedule : <b><%=period.visit if period%></b> </div><div class=\"span6\">Visit Type : <b><%=visit.visit_type%></b></div>\r\n     </div>\r\n       <div class=\"row-fluid\">\r\n    <div class=\"span6\">\r\n    Date : <b><%=visit.date.strftime(\"%d/%m/%Y\")%></b>\r\n    </div>\r\n    <div class=\"span6\">\r\n    Status : <b><%=visit.status%></b>\r\n    </div>\r\n    </div>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span6\">\r\n    <%=link_to \'Show Detail\',\"../Visit/show?id=\\\\#{visit.id}\", :class=>\'btn\'%>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<% if has_next.size> 0 %>\r\n\r\n<div class=\"alert\">\r\n    # Already create next visit at <%=has_next[0].date.strftime(\"%d/%m/%Y\") %>\r\n</div>\r\n<% end %>\r\n<% if has_next.size== 0 and visit.status!=\'Completed\' and last==nil  %>\r\n<div class=\"alert\">\r\n    # Please complete today visit.\r\n</div>\r\n<% end %>\r\n\r\n\r\n\r\n<% if visit.status==\'Completed\'  and has_next.size==0\r\n\r\n%>\r\n\r\n<div class=\"row-fluid \" id=\"next_visit\">\r\n<div class=\"span12\">\r\n<div class=\"<%= ext_class %>\">\r\n<%= form_for :visit, :url=>\"create_visit\" do |f| %>\r\n<%= hidden_field_tag :patient_id,  params[:id] %>\r\n\r\n<h3>Next Visit : </h3>\r\n    <%\r\n    \r\n    \r\n        options = [[\"\",\"\\\\#{sheet.id if sheet}:\"]] + periods.collect{|i|   [\"\\\\#{i.visit} +\\\\#{i.day.to_i - now_day} days \\\\#{\'->Current\' if period and i.id==period.id}\" , \"\\\\#{sheet.id if sheet}:\\\\#{i.id}\"] }\r\n        \r\n        if sheet\r\n        \r\n        sheet_doc = models[:project_document].where(:document_id=>sheet.id).first\r\n        m_sheets = models[:project_document].where(:project_id=>sheet_doc.project_id, :document_name=>\'pl_sheet\').all\r\n        sheets = models[:pl_sheet].where(:id=>{\'$ne\'=>sheet.id, \'$in\'=>m_sheets.collect{|i|i.document_id}}).all\r\n        \r\n        for s in sheets\r\n        \r\n            speriods =  models[:pl_period].where(:sheet_id=>s.id).all\r\n         \r\n            options+= speriods.collect{|i|   [\"version \\\\#{s.version if s} / \\\\#{i.visit} +\\\\#{i.day.to_i - now_day} days \\\\#{\'->Current\' if  period and i.id==period.id}\" ,\"\\\\#{s.id}:\\\\#{i.id}\"] }\r\n            \r\n        \r\n        end\r\n            \r\n    %>\r\n \r\n    Visit Schedule : <%=select_tag \"next_visit\", options_for_select(options.compact,\"\\\\#{sheet.id if sheet}:\\\\#{next_visit}\") %>\r\n\r\n    Visit Type : \r\n<select name=\"next_visit_type\" id=\"data-visit_type\" >\r\n<option selected=\"selected\" value=\"SCHEDULE\">SCHEDULE</option>\r\n<option value=\"UNSCHEDULE\">UNSCHEDULE</option></select>\r\n<br/>\r\n    Date : <%= text_field_tag \"next_date\", \"\" %>\r\n<br/><br/>\r\n<%=f.submit \'Create Next Visit\', :class=>\'btn btn-success\'%>\r\n</div>\r\n</div>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n<% end %>\r\n<%\r\ndefault_date_shift = 0 \r\ndefault_date_shift= periods[now].day.to_i - period.day.to_i if period %>\r\n<script>\r\n	$(\"#next_date\").kendoDatePicker({\r\n		value: \'<%=(visit.date+default_date_shift).strftime(\"%d/%m/%Y\")%>\',\r\n	});\r\n	\r\n	$(\"#data-date\").change(function(){\r\n		obj = $(this)\r\n		v = obj.val()\r\n		if(v.length>0){\r\n		s = v.split(\"/\")\r\n		y = parseInt(s[2])\r\n		if(y>2200)\r\n		y = y-543\r\n		\r\n		d = new Date(y,parseInt(s[1]-1),parseInt(s[0]))\r\n		obj.val(\"\"+parseInt(s[0])+\"/\"+parseInt(s[1])+\"/\"+y)\r\n		}\r\n	});\r\n</script>\r\n\r\n<% end %>\r\n\r\n\r\n<!-- ################################################################################################### --->\r\n\r\n<!-- ################################################################################################### --->\r\n\r\n<!-- ################################################################################################### --->\r\n\r\n\r\n\r\n</div>\r\n\r\n</p>\r\n</div>\r\n									\r\n<div class=\"tab-pane\" id=\"tab_br3\">\r\n										<p>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<h3>Visit History</h3>\r\n<table class=\"table\" > \r\n    <thead>\r\n        <tr><th>No.</th>\r\n            <th>Date</th><th>Protocol Version</th><th>Visit</th><th>Visit Type</th><th>Result</th><th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <% visits.each_with_index do |i,index| \r\n            sheet = models[:pl_sheet].find(i.sheet_id)\r\n            period = models[:pl_period].find(i.period_id)\r\n        %>\r\n        <tr><td><%=index+1%>.</td>\r\n            <td><%=link_to i.date,\"../Visit/show?id=\\\\#{i.id}\"  %></td>\r\n            <td><%=sheet.version if sheet%></td>\r\n            <td><%=period.visit if period%></td><td><%=i.visit_type%></td>\r\n            <td style=\"color:green\"><%=i.status%></td>\r\n            <td><%=link_to \'Del\', \"../Visit/destroy?id=\\\\#{i.id}\",:class=>\'btn btn-mini btn-danger\', :data=>{:confirm=>\'Are you sure?\'} %></td>\r\n        </tr>\r\n        <% end %>\r\n    </tbody>\r\n    \r\n</table>\r\n<%=link_to \'Summary\' , \"summary?id=\\\\#{params[:id]}\", :class=>\'btn\' %>\r\n</div>\r\n</div>\r\n										</p>\r\n										\r\n										\r\n									</div>\r\n\r\n									\r\n<div class=\"tab-pane\" id=\"tab_br4\">\r\n										<p>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span4\">\r\n	<div id=\"calendar\" class=\"span12\" style=\"width:300px;height:300px\"></div>\r\n</div>\r\n\r\n<div class=\"span8\">\r\n    <h3>Schedule List</h3>\r\n    <%\r\n        list = models[:patient_schedule].where(:patient_id=>params[:id]).all\r\n    \r\n    %>\r\n    \r\n    <table class=\"table\">\r\n        <thead>\r\n            <tr>\r\n                <th>No.</th><th>Name</th><th>Note</th><th>Date</th><th></th><th></th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n        <% list.each_with_index do |i,index| %>\r\n            <tr>\r\n                <td><%=index+1%>.</td>\r\n                <td><%=i.name%></td>\r\n                <td><%=i.note%></td>\r\n                <td><%=i.start_date%> - <%=i.end_date%></td>\r\n                <td><%=link_to \'Edit\', \"../PatientSchedule/edit?id=\\\\#{i.id}&return=\\\\#{request.url}\",:class=>\"\" %></td>\r\n                <td><%=link_to \'Delete\', \"../PatientSchedule/destroy?id=\\\\#{i.id}&return=\\\\#{request.url}\",:class=>\"\" %></td>\r\n\r\n\r\n                \r\n            </tr>\r\n        <% end %>\r\n        </tbody>\r\n        \r\n    </table>\r\n    \r\n     \r\n</div>\r\n\r\n    \r\n    \r\n</div>\r\n\r\n\r\n<script>\r\n<%\r\n\r\n    events = []\r\n\r\n\r\n       \r\n        events = list\r\n    \r\n    \r\n             events.collect!{|e|  \r\n    \r\n               \r\n                \r\n            \r\n                    # period = models[:pl_period].find e.period_id\r\n                    # project = mprojects[e.project_id]\r\n                    # patient = models[:patient].find e.patient_id\r\n                    # title = \"\\\\#{project.protocol_no} : \\\\#{period.visit if period} : \\\\#{patient.subject_id} : \\\\#{patient.first_name} \\\\#{patient.last_name} \\\\#{\'#\'+e.note if e.note}\"\r\n                    title = \"\\\\#{e.name}\"          \r\n    \r\n    			{\r\n    			        :title=>title,\r\n						:start=> DateTime.parse(e.start_date.strftime(\"%Y-%m-%d\")+\"T\"+e.start_time.strftime(\"%H:%M\") ),\r\n						:end=>  DateTime.parse(e.end_date.strftime(\"%Y-%m-%d\")+\"T\"+e.end_time.strftime(\"%H:%M\")),\r\n						:allDay=> true,\r\n                        :color=> \"#f5eeef\",\r\n                        :textColor=>\"#111\",\r\n                        :url=>\"../PatientSchedule/show?id=\\\\#{e.id}\"\r\n                }\r\n    \r\n    }\r\n\r\n%>\r\n    \r\n    /* [ ---- Gebo Admin Panel - calendar ---- ] */\r\n\r\n	$(document).ready(function() {\r\n		gebo_calendar.regular();\r\n// 		gebo_calendar.google();\r\n		//* resize elements on window resize\r\n		var lastWindowHeight = $(window).height();\r\n		var lastWindowWidth = $(window).width();\r\n		$(window).on(\"debouncedresize\",function() {\r\n			if($(window).height()!=lastWindowHeight || $(window).width()!=lastWindowWidth){\r\n				lastWindowHeight = $(window).height();\r\n				lastWindowWidth = $(window).width();\r\n				//* rebuild calendar\r\n				$(\'#calendar\').fullCalendar(\'render\');\r\n				// $(\'#calendar_google\').fullCalendar(\'render\');\r\n			}\r\n		});\r\n	});\r\n	\r\n	//* calendar\r\n	gebo_calendar = {\r\n		regular: function() {\r\n			var date = new Date();\r\n			var d = date.getDate();\r\n			var m = date.getMonth();\r\n			var y = date.getFullYear();\r\n			var calendar = $(\'#calendar\').fullCalendar({\r\n				header: {\r\n					left: \'prev next\',\r\n					center: \'title,today\',\r\n					right: \'\'\r\n				},\r\n				buttonText: {\r\n					prev: \'<i class=\"icon-chevron-left cal_prev\" />\',\r\n					next: \'<i class=\"icon-chevron-right cal_next\" />\'\r\n				},\r\n				aspectRatio: 1.5,\r\n				selectable: true,\r\n				selectHelper: true,\r\n				select: function(start, end, allDay) {\r\n				    console.log(start)\r\n				    window.location=\"../PatientSchedule/create?patient_id=<%=params[:id]%>&date=\"+(start);\r\n				    \r\n				// 	var title = prompt(\'Event Title:\');\r\n				// 	if (title) {\r\n				// 		calendar.fullCalendar(\'renderEvent\',\r\n				// 			{\r\n				// 				title: title,\r\n				// 				start: start,\r\n				// 				end: end,\r\n				// 				allDay: allDay\r\n				// 			},\r\n				// 			true // make the event \"stick\"\r\n				// 		);\r\n				// 	}\r\n				// 	calendar.fullCalendar(\'unselect\');\r\n				},\r\n				editable: true,\r\n				theme: false,\r\n				events: <%=events.to_json.html_safe%>,\r\n				eventColor: \'#bcdeee\'\r\n			})\r\n		}\r\n	};\r\n	$(\'#other_schedule_btn\').click(function(){\r\n\r\n \r\n    // $.cookie(\"patient-tab\",\'tab_br4\',{ expires : 1 });\r\n	   \r\n	});\r\n	\r\n	$(\'.tab_btn\').click(function(){\r\n\r\n             $.cookie(\"patient-tab\",$(this).attr(\'href\'),{ expires : 1 });\r\n	   	      setTimeout(function() {$(\'.fc-button-content\').click();}, 50);\r\n\r\n\r\n	});\r\n	\r\n	\r\n	\r\n	\r\n	$(document).ready(function(){\r\n	     \r\n	     tab = $.cookie(\"patient-tab\");\r\n	     \r\n	     	$(\'.tab_btn\').each(function(){\r\n	     	    o = $(this)\r\n	     	    if(tab==o.attr(\'href\')){\r\n	     	        o.click();\r\n	     	    }\r\n	     	    \r\n	     	})\r\n	     \r\n	      setTimeout(function() {$(\'.fc-button-content\').click();}, 50);\r\n\r\n\r\n\r\n	})\r\n	\r\n</script>\r\n\r\n\r\n</div>\r\n</div>\r\n\r\n</p>\r\n</div>\r\n\r\n\r\n\r\n									\r\n									\r\n								\r\n								</div>\r\n								\r\n								\r\n							\r\n							</div>\r\n\r\n<div style=\"border:0px solid\">\r\n\r\n<div>\r\n\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n<div class=\"modal hide \" id=\"modal-randomize\" aria-hidden=\"false\" style=\"display: none;\">\r\n	<div class=\"modal-header\">\r\n		<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n		<h3>Schdule Visit</h3>\r\n	</div>\r\n	<%= form_for :randomize, :url=>\"process?id=\\\\#{params[:id]}\" do |f| %>\r\n	<div class=\"modal-body\">\r\n        \r\n        <%=f.hidden_field :project_id, :value=>project.id %>\r\n        \r\n	    <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Patient :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	            <span id=\"randomize_patient_name\" ></span>\r\n	            <%=f.hidden_field :patient_id,:value=>nil %>\r\n	        </div>\r\n	    </div>\r\n	    \r\n	\r\n	    <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Subject ID :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	         <%=record.subject_id%>\r\n	      \r\n	        </div>\r\n	    </div>\r\n	    \r\n           <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Visit Type :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	        <span id=\"visit_type_text\">Schedule</span>\r\n            <%=f.hidden_field :visit_type, :value=>\'SCHEDULE\' %>\r\n\r\n	        </div>\r\n	    </div>\r\n	    \r\n	    \r\n	         <%\r\n	            \r\n	            docs = models[:project_document].where(:document_name=>\'pl_sheet\',:project_id=>project.id).all\r\n	            sheets = models[:pl_sheet].find(docs.collect{|i| i.document_id })\r\n	        %>\r\n	        \r\n	        \r\n      <div class=\"row-fluid visit_tag\" >\r\n	        <div class=\"span4\">\r\n	            <label>From Visit :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	        \r\n	        <%\r\n	            msheets = Hash[sheets.collect{|i| [i.id,i]}]\r\n	            \r\n	            periods = models[:pl_period].where(:sheet_id=>{\'$in\'=>sheets.collect{|i| i.id}}).all.collect{|i| \r\n	                 \r\n	                 s = msheets[i.sheet_id]\r\n	               \r\n	                 [i.visit, i.id, s.id, i.day, \"\\\\#{s.version} : \\\\#{i.visit} : \\\\#{i.day}D \" ]\r\n	            \r\n	            }\r\n	            \r\n	            visits = models[:visit].where(:patient_id=>record.id).all.collect{|v|\r\n	                \r\n	                \r\n	                i = models[:pl_period].find(v.period_id)\r\n	                if i \r\n	                s = msheets[i.sheet_id]\r\n	                [i.visit, i.id, s.id, i.day, \"\\\\#{s.version} : \\\\#{i.visit} : \\\\#{i.day}D = \\\\#{v.name}\" ]\r\n	                else\r\n	                \r\n	                [v.name, nil,nil, 0, \"\\\\#{v.name}\" ]\r\n	                \r\n	                end \r\n	            \r\n	            }\r\n	            \r\n	            periods = visits\r\n	               \r\n	            last_date = Time.now.strftime(\"%d/%m/%Y\");\r\n	               \r\n	            last_visit = models[:visit].where(:patient_id=>record.id).last \r\n	            last_period = 0\r\n	            if last_visit\r\n	                \r\n	               lv =   models[:pl_period].find(last_visit.period_id)\r\n	               if lv\r\n	               last_period = lv.day.to_i \r\n	               end\r\n	               last_date = last_visit.date.strftime(\"%d/%m/%Y\")\r\n	               \r\n	            end\r\n	            \r\n	           \r\n	        %>\r\n	       \r\n	        <%=select_tag :last_period_id, options_for_select(periods.collect{|i| [i[-1],i[3]] },last_period),:include_blank=>true   %>\r\n	        \r\n	       \r\n	        </div>\r\n	    </div>\r\n	    \r\n	         <div class=\"row-fluid \">\r\n	        <div class=\"span4\">\r\n	            <label>From Date :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	      <%\r\n	         \r\n	      %>\r\n	        <%=text_field_tag  :from_date, last_date  %>\r\n	        </div>\r\n	      \r\n            </div>\r\n       \r\n        <div class=\"row-fluid visit_tag\">\r\n	        <div class=\"span4\">\r\n	            <label>Visit :</label>\r\n	        </div>\r\n	        <div class=\"span8 alert\">\r\n	        \r\n	        <%\r\n	            msheets = Hash[sheets.collect{|i| [i.id,i]}]\r\n	            \r\n	            periods = models[:pl_period].where(:sheet_id=>{\'$in\'=>sheets.collect{|i| i.id}}).all.collect{|i| \r\n	                 \r\n	                 s = msheets[i.sheet_id]\r\n	               \r\n	                 [i.visit, i.id, s.id, i.day, \"\\\\#{s.version} : \\\\#{i.visit} : \\\\#{i.day}D \" ]\r\n	            \r\n	            }\r\n	            \r\n	           \r\n	        %>\r\n	       \r\n	        <%=f.select :period_id, options_for_select(periods.collect{|i| [i[-1],i[1]] }),:include_blank=>true  ,:style=>\"width:120px\"%>\r\n	        <%\r\n	            days = []\r\n	             days << [\'7 days\',7]\r\n	             days << [\'14 days\',14]\r\n	             days << [\'21 days\',21]\r\n	             days << [\'28 days\',28]\r\n	             days << [\'3 months\',90]\r\n	             days << [\'6 months\',180]\r\n	             days << [\'9 months\',270]\r\n	             \r\n	        %>\r\n	         \r\n	        <!---->\r\n	        \r\n	        \r\n	        \r\n	        \r\n	       \r\n	        </div>\r\n	    </div>\r\n	    \r\n	      \r\n          \r\n           <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Visit Date :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	      \r\n	        <%=f.text_field  :date %> <span id=\"shift_date\"></span> \r\n	       <%=text_field_tag  :days,\"\",:class=>\'days\' ,:style=>\"width:30px;margin:0px\",:placeholder=>\'Day\'  %> \r\n	        <%=select_tag :days, options_for_select(days),:class=>\'days\', :include_blank=>true ,:style=>\"width:80px;margin:0px\" %>\r\n\r\n	        </div>\r\n	        \r\n	        \r\n	        \r\n	    </div>\r\n	    \r\n	       <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Visit Name :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	      \r\n	        <%=f.text_field  :name %>\r\n	        </div>\r\n	    </div>\r\n          \r\n	    \r\n	      <div class=\"row-fluid\">\r\n	        <div class=\"span4\">\r\n	            <label>Protocol Version :</label>\r\n	        </div>\r\n	        <div class=\"span8\">\r\n	   \r\n	        <%=f.select :sheet_id, options_for_select(sheets.collect{|i| [i.version,i.id]}),:include_blank=>true ,:readonly=>true%>\r\n	        </div>\r\n	    </div>\r\n       \r\n     \r\n          \r\n    \r\n       \r\n       <script>\r\n    \r\n    \r\n    \r\n    $(\"#from_date\").kendoDatePicker({\r\n		value: \'<%=last_date%>\',\r\n	});\r\n	\r\n	 $(\"#randomize_date\").kendoDatePicker({\r\n		value: \'<%=last_date%>\',\r\n	});\r\n	\r\n	\r\n	$(\"#randomize_date\").change(function(){\r\n		obj = $(this)\r\n		v = obj.val()\r\n		if(v.length>0){\r\n		s = v.split(\"/\")\r\n		y = parseInt(s[2])\r\n		if(y>2200)\r\n		y = y-543\r\n		\r\n		d = new Date(y,parseInt(s[1]-1),parseInt(s[0]))\r\n		obj.val(\"\"+parseInt(s[0])+\"/\"+parseInt(s[1])+\"/\"+y)\r\n		}\r\n	});\r\n           var periods = <%=periods.to_json.html_safe%>\r\n           var s_date = [];\r\n           \r\n           \r\n           \r\n           $(\'.days\').change(function(){\r\n               \r\n               v = $(this).val();\r\n               \r\n               day = parseInt(v)\r\n               if(day>0){\r\n                           $(\'#shift_date\').html(\"+\"+day)\r\n                       }else{\r\n                           $(\'#shift_date\').html(\"\"+day)\r\n                       }\r\n               s =  $(\'#from_date\').val().split(\"/\")\r\n                      \r\n               d = new Date(parseInt(s[2]),parseInt(s[1]),parseInt(s[0]))\r\n               d.setDate(d.getDate() + day +1)\r\n               \r\n               t = \"\"+d.getDate()+\"/\"+d.getMonth()+\"/\"+d.getFullYear()\r\n                      \r\n               $(\'#randomize_date\').val(t);\r\n             \r\n             \r\n           })\r\n           \r\n           \r\n           $(\'#randomize_period_id\').change(function(){\r\n               \r\n               v = $(this).val();\r\n             \r\n               for(var ix in periods){\r\n                   i = periods[ix];\r\n                   if(i[1]==v){\r\n                       $(\'#randomize_sheet_id\').val(i[2]);\r\n                       $(\'#randomize_name\').val(i[0]);\r\n                       oday = parseInt($(\'#last_period_id\').val())\r\n                       day = parseInt(i[3])-oday;\r\n                       \r\n                       if(day>0){\r\n                           $(\'#shift_date\').html(\"+\"+day)\r\n                       }else{\r\n                           $(\'#shift_date\').html(\"\"+day)\r\n                       }\r\n                       \r\n                       s =  $(\'#from_date\').val().split(\"/\")\r\n                      \r\n                       d = new Date(parseInt(s[2]),parseInt(s[1]),parseInt(s[0]))\r\n                       \r\n                       d.setDate(d.getDate() + day+1)\r\n                       t = \"\"+d.getDate()+\"/\"+d.getMonth()+\"/\"+d.getFullYear()\r\n                      \r\n                       $(\'#randomize_date\').val(t);\r\n                   }\r\n                   \r\n               }\r\n               \r\n           })\r\n           \r\n           \r\n           $(\'.randomize_btn\').click(function(){\r\n               \r\n               v = $(this).attr(\'patient_id\')\r\n               name = $(this).attr(\'patient_name\')\r\n               $(\'#randomize_patient_id\').val(v)\r\n               $(\'#randomize_patient_name\').html(name)\r\n               \r\n               visit_type = $(this).attr(\'visit_type\')\r\n               \r\n               if(visit_type==\'unschedule\'){\r\n                   \r\n                   $(\'#visit_type_text\').html(\'UnSchedule\')\r\n                   $(\'#randomize_visit_type\').val(\'UNSCHEDULE\')\r\n                   \r\n                   $(\'.visit_tag\').remove();\r\n                   \r\n               }\r\n               \r\n               \r\n               $(\'#modal-randomize\').modal();\r\n               s_date = $(\'#randomize_date\').val()\r\n\r\n\r\n           })\r\n           \r\n       </script>\r\n       \r\n      	</div> \r\n        		<div class=\"modal-footer\">\r\n		<%=f.submit \'Submit\', :class=>\'btn btn-success\'%>\r\n		<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n	</div>\r\n	<% end %>\r\n</div>\r\n   <%\r\n     rescue Exception =>e\r\n   %>\r\n   <%=e.inpsect %>\r\n\r\n\r\n<% end %>',NULL,NULL,NULL,'2018-07-01 04:44:08','2018-07-01 04:44:08','show',''),(3533,'edit',1383,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n    models = get_model\r\n    model = models[:patient]  \r\n    record = model.find params[:id]\r\n    \r\n    return_url = \"../Project/show?id=\\\\#{record.project_id}\"\r\n    \r\n    \r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=record.id%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-07-01 05:13:29','2018-07-01 05:13:29','edit',''),(3534,'create_visit',1383,3,'<%\r\n\r\n    models = get_model\r\n    \r\n    next_visit = params[:next_visit].split(\":\")\r\n    \r\n    sheet_id = next_visit[0]\r\n    period_id = next_visit[1]\r\n    patient_id = params[:patient_id]\r\n    visit_type = params[:next_visit_type]\r\n    \r\n    patient = models[:patient].find patient_id\r\n    \r\n    \r\n    models[:visit].create :date=>params[:next_date], :patient_id=>patient_id, :sheet_id=>sheet_id, :period_id=>period_id, :visit_type=>visit_type, :project_id=>patient.project_id\r\n    patient.update_attributes :sheet_id=>sheet_id\r\n    \r\n    \r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Patient/show?id=<%=patient_id%>\" />\r\n',NULL,NULL,NULL,'2018-07-01 05:26:34','2018-07-01 05:26:34','create_visit',''),(3535,'summary',1383,2,'<%\r\n\r\n    models = get_model\r\n    \r\n    record = models[:patient].find params[:id]\r\n\r\n    return_url = \"../Project/show?id=\\\\#{record.project_id}\"\r\n    return_url = params[:return] if params[:return]\r\n     \r\n     \r\n    visit = models[:visit].where(:patient_id=>record.id, :date=>{\'$gte\'=>Time.now.beginning_of_day,\'$lte\'=>Time.now.end_of_day}).first\r\n    has_next = models[:visit].where(:patient_id=>record.id, :date=>{\'$gt\'=>Time.now.end_of_day}).all\r\n    visits = models[:visit].where(:patient_id=>record.id).order(:date).all\r\n   \r\n    \r\n    smap = {}\r\n    \r\n    for  i in visits\r\n    \r\n    smap[i.sheet_id] = [] unless smap[i.sheet_id]\r\n    \r\n    smap[i.sheet_id] << i\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n%>\r\n\r\n<% smap.each_pair do |sid,list| \r\n\r\n    s = models[:pl_sheet].find sid\r\n    \r\n    px = models[:pl_period_product].where(:sheet_id=>s.id).order(:sort_order).all\r\n    \r\n    pmap = {}\r\n    \r\n    models[:pl_product].find(px.collect{|i| i.product_id}).each do |i|\r\n        pmap[i.id] = i\r\n    end\r\n    \r\n    imap = {}\r\n    \r\n    models[:pl_period_item].where(:sheet_id=>s.id).all.each do |i|\r\n        k = \"\\\\#{i.period_id}:\\\\#{i.period_product_id}\"\r\n        imap[k] = i\r\n    end\r\n    \r\n    \r\n    vlist = {}\r\n    list.each do |it| \r\n        \r\n    vlist[it.id] = {}\r\n    \r\n    vis = models[:visit_item].where(:visit_id=>it.id).all.each do |i|\r\n        \r\n        vlist[it.id][i.item_id] = i\r\n        \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n    \r\n    <div class=\"span12\">\r\n        <h3><%=s.name %> version <%=s.version%></h3>\r\n        <table class=\"table\">\r\n            <thead>\r\n                <tr>\r\n                <th>\r\n                    No.\r\n                </th>\r\n                <th>\r\n                    Code\r\n                </th>\r\n                <th>\r\n                    Description\r\n                </th>\r\n                <th>\r\n                    Group\r\n                </th>\r\n                <% list.each do |it| \r\n                   period = models[:pl_period].find it.period_id \r\n                %>\r\n                <th style=\"width:50px\"> \r\n                    <center>\r\n                    <a href=\"../Visit/show?id=<%=it.id%>\"><%= period.visit%><br/>\r\n                    <span style=\"font-size:0.8em\">\r\n                    <%= it.date.strftime(\"%d/%m/%Y\") %><br/>\r\n                    <%= it.visit_type %>    </span>\r\n                    </a></center>\r\n                </th>\r\n                <% end %>\r\n                <th>\r\n                    \r\n                </th>\r\n                \r\n                </tr>\r\n                \r\n            </thead>\r\n            <tbody>\r\n            <% px.each_with_index do |pi, index| \r\n                p = pmap[pi.product_id]\r\n            %>\r\n            <tr>\r\n                <td  style=\"width:50px\">\r\n                    <%=index+1%>.\r\n                </td>\r\n                <td style=\"width:100px\">\r\n                    <%= p.code %>\r\n                </td>\r\n                <td  style=\"width:200px\" >\r\n                    <%= pi.detail %>\r\n                </td>\r\n                 <td style=\"width:100px\">\r\n                    <%= p.group_code %>\r\n                </td>\r\n                <% list.each do |it| \r\n                    \r\n                    \r\n                    k = \"\\\\#{it.period_id}:\\\\#{pi.id}\"\r\n                    ix = imap[k]\r\n                    visit_item = nil\r\n                    visit_item = vlist[it.id][ix.id] if ix\r\n                    \r\n                %>\r\n                <td align=\"center\">\r\n                <%\r\n                    if visit_item and visit_item.status==\'Done\'\r\n                %>\r\n                    <%=image_tag \"/esm/cusys/cucrc/done.png\", :height=>30 %>\r\n                \r\n                <% elsif ix %>\r\n                    <% if it.status!=\'Completed\' %>\r\n                        <%=image_tag \"/esm/cusys/cucrc/maybe.png\" , :height=>30%>\r\n                    <% else %>\r\n                        <%=image_tag \"/esm/cusys/cucrc/not-done.png\" , :height=>30%>\r\n                    <% end %>\r\n                <% else %>\r\n                <% end %>\r\n                 </td>\r\n                 \r\n                <% end %>\r\n                    \r\n                    <td></td>\r\n                \r\n                \r\n            </tr>\r\n            <% end %>    \r\n            </tbody>\r\n        </table>\r\n        \r\n        \r\n        \r\n    </div>\r\n    \r\n</div>\r\n<% end %>\r\n\r\n<%= link_to \"Back to Patient\", \"show?id=\\\\#{params[:id]}\"%> ',NULL,NULL,NULL,'2018-07-01 09:33:34','2018-07-01 09:33:34','summary',''),(3536,'document_name',1392,1,'\'certificate\'',NULL,NULL,NULL,'2018-07-02 05:49:23','2018-07-02 05:49:23',NULL,NULL),(3537,'issue',1392,2,'<%\r\n    path = File.join(\"out.jpg\");\r\n    thumb = File.join(\"out-thumb.jpg\");\r\n    template = File.join(\"/esm/colo/colo/SxEndoCertificateNoname.jpg\");\r\n    font = File.join(\"/esm/colo/colo/BOOKOS.TTF\");\r\n    \r\n    \r\n    record = get_model(\'certificate\').find params[:id]\r\n    \r\n    cmd = `convert -fill \"srgb(255,255,100)\" -font \"\\\\#{File.join(\"public\",font)}\" -pointsize 100 -