s=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to \'Issue Document\'.html_safe, \"issue?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-07-02 05:52:49','2018-07-02 05:52:49','show',''),(3539,'document_name',1393,1,'\'transaction\'',NULL,NULL,NULL,'2018-07-02 12:08:10','2018-07-02 12:08:10',NULL,NULL),(3540,'document_name',1394,1,'\'transaction_item\'',NULL,NULL,NULL,'2018-07-02 12:08:33','2018-07-02 12:08:33',NULL,NULL),(3541,'transaction_tmp',1385,2,'<%\r\n    models = get_model\r\n    visit = models[:visit].find params[:id] \r\n  \r\n    \r\n    \r\n    transactions = models[:transaction].where(:visit_id=>visit.id).all\r\n    \r\n%>\r\n<h1>Transaction for Visit ID : </h1>\r\n\r\n<%= form_for \'record\', :url=>\'create_transaction?id=\'+params[:id] do |f| %>\r\n<%=%>\r\n<div class=\"row-fluid\">\r\n\r\n<div class=\"span12\">\r\n<h3>1. Sale Order for CRA <%= check_box_tag \"transaction[]\",\"SO\",true  %> (click to select)</h3>    \r\n\r\n<!--\r\n<p>\r\n    <label>1.1 Select item by </label>\r\n    <%=radio_button_tag \'so_select\', \'1\' %> By Visit quote\r\n    <br/>\r\n    <%=radio_button_tag \'so_select\', \'2\' %> By Actual activities\r\n\r\n</p>\r\n<p>\r\n    <label>1.2 Group item by</label>\r\n    <%=radio_button_tag \'so_group\', \'1\' %> By Group Code using category\r\n    <br/>\r\n    <%=radio_button_tag \'so_group\', \'2\' %> By Item Code for each item\r\n\r\n</p>\r\n-->\r\n\r\n\r\n\r\n</div>    \r\n</div>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<h3>2. Purchase Order to Provider/Hospital/CRC <%= check_box_tag \"transaction[]\",\"BV\",true  %> (click to select)</h3>    \r\n\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n<%= f.submit \'Create Transaction\', :class=>\'btn btn-success\' %>\r\n<% end %>\r\n<hr/>\r\n\r\n<br/>\r\n<%= link_to \'Back to Visit\', \"show?id=\\\\#{params[:id]}\"%>\r\n\r\n',NULL,NULL,NULL,'2018-07-03 00:40:17','2018-07-03 00:40:17','transaction_tmp',''),(3542,'create_transaction',1385,2,'<%\r\n    models = get_model\r\n    visit = models[:visit].find params[:id] \r\n    project = models[:project].find visit.project_id\r\n    sheet = models[:pl_sheet].find visit.sheet_id\r\n    period = models[:pl_period].find visit.period_id\r\n    patient = models[:patient].find visit.patient_id\r\n    \r\n    transactions = models[:transaction].where(:visit_id=>visit.id).all\r\n    params[:so_select]=\'2\'\r\n    params[:so_group]=\'2\'\r\n    \r\n    \r\n    if params[:transaction].index(\"SO\")>=0 \r\n        items = []\r\n    if params[:so_select]==\"1\"\r\n        \r\n        items = models[:pl_period_item].where(:sheet_id=>sheet.id, :period_id=>period.id).all\r\n        \r\n    else\r\n        its = models[:visit_item].where(:visit_id=>visit.id).all\r\n        \r\n        items = models[:pl_period_item].find(its.collect{|i| i.item_id })\r\n    end\r\n    \r\n    \r\n\r\n    list = items.collect{|i|\r\n        \r\n        p = models[:pl_product].find i.product_id\r\n        pp = models[:pl_period_product].find i.period_product_id\r\n        c = models[:pl_category].where(:group_code=> p.group_code).first\r\n        if c\r\n        gl_code = c.gl_code\r\n        c_gl_code = c.gl_code\r\n        end\r\n        gl_code = p.gl_code if p.gl_code and p.gl_code!=\"\" \r\n       \r\n        {:item=>i, :product=>p, :period_product=>pp, :category=>c, :price=>i.price, :cost=>p.cost, :p_gl_code=>gl_code, :c_gl_code=>c_gl_code }\r\n    \r\n    }\r\n\r\n\r\n    ilist = []\r\n    \r\n    if params[:so_group]==\'1\'\r\n    \r\n    cmap = {}\r\n    map = {}\r\n    \r\n    list.each do |i|\r\n      \r\n    if i[:category] \r\n        cmap[i[:category].id] = i[:category]\r\n        map[i[:category].id] = [] unless  map[i[:category].id] \r\n        map[i[:category].id] << i \r\n    end\r\n\r\n    end\r\n    \r\n    map.each_pair do |c,l|\r\n        sum = 0\r\n        category = cmap[c] \r\n        for i in l\r\n            sum+= i[:price]\r\n        end\r\n        ilist << {:price=>sum, :quantity=>1, :amt=>sum, :name=>category.name, :gl_code=>category.gl_code}    \r\n        \r\n    end\r\n    \r\n    \r\n    else\r\n        list.each do |i|\r\n        \r\n        ilist << {:price=>i[:price], :quantity=>1, :amt=>i[:price], :name=>i[:period_product].detail , :gl_code=>i[:p_gl_code]}  \r\n        \r\n        end\r\n    end\r\n    \r\n    \r\n    \r\n    sum = 0\r\n    \r\n    \r\n    for i in ilist\r\n        \r\n        sum+= i[:amt]\r\n    \r\n    end\r\n    \r\n    \r\n    oh = sum*0.2\r\n    oh_c = models[:pl_category].where(:group_code=>\'OH\').first \r\n    oh = format(\"%.2f\",oh).to_f\r\n    ilist << {:price=>oh, :quantity=>1, :amt=>oh, :name=>oh_c.name , :gl_code=>oh_c.gl_code}    \r\n\r\n    px = {:reftype=>\'SO\', :qccorp=>\'00000\', :qcbranch=>\'00000\', :qcsect=>\'00000\',:qcjob=>\'00000\'}\r\n    book = \'0001\'\r\n    code = \'0000001\'\r\n    refno = \"SO\\\\#{book}/\\\\#{code}\"\r\n    \r\n    px.merge! :date=>visit.date.strftime(\"%d%m%y\"), :recdate=>Time.now.strftime(\"%d%m%y\"),:duedate=>\"\",:qcbook=>book,:code=>code, :refno=>refno\r\n    \r\n    amt = sum \r\n    \r\n    px.merge! :date=>visit.date.strftime(\"%d%m%y\"), :amt=>amt, :vatisout=>\'Y\', :vattype=>\'4\',:vatamt=>\'\'\r\n    \r\n    if project.customer_id and customer = models[:customer].find(project.customer_id)\r\n    \r\n    px.merge! :qccoor=>customer.acc_code\r\n    \r\n    end\r\n    \r\n    px.merge! :qcempl=>\'0001\',:credterm=>30, :qcwhouse=>\'0001\', :remarkh1=>patient.subject_id, :remarkh2=>patient.hn ,:remarkh3=>visit.visit_type \r\n    \r\n    \r\n    transaction = models[:transaction].create px.merge(:visit_id=>visit.id)\r\n    \r\n    \r\n    # {:item=>i, :product=>p, :period_product=>pp, :category=>c, :price=>i.price, :cost=>p.cost, :p_gl_code=>gl_code, :c_gl_code=>c_gl_code }\r\n\r\n\r\n    \r\n    for i in list \r\n    product = i[:product]\r\n    itransaction = models[:transaction_item].create px.merge(:transaction_id=>transaction.id, :qcprod=>product.code, :qty=>1, :price=>i[:price],:discstr=>\'\',:qcum=>\'ครั้ง\',:umqty=>1)\r\n    end\r\n    \r\n    \r\n    \r\n\r\n\r\n\r\n%>\r\n<h1> SaleOrder : <%=sheet.name %> version <%=sheet.version %></h1>\r\n<h3> Visit : <%=period.visit %></h3>\r\n<%= tabular :data=>ilist, :model=>[:name, :price, :quantity, :amt, :gl_code]  %>\r\n<%\r\n \r\n    end\r\n    \r\n%>\r\n<%= link_to \"Back to Transaction\", \"transaction?id=\\\\#{params[:id]}\"%>\r\n\r\n',NULL,NULL,NULL,'2018-07-03 00:57:28','2018-07-03 00:57:28','create_transaction',''),(3543,'edit',398,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model()[this.table_name.to_sym]\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s and params[:override]==nil\r\n    %>\r\n    <script>\r\n            \r\n         res = confirm(\"Someone is editing this document. Would you like to override the record?\");\r\n        if(res==true){\r\n            \r\n            \r\n            // $(\'#ref_number\').parent().append(\"<input type=\'text\' name=\'override\' value=\'override\' />\");\r\n            // $(\'#ref_number\').remove();\r\n           $(document).ready(function(){\r\n              $(\'#ref_number\').parent().append(\"<input type=\'hidden\' name=\'override\' value=\'override\' />\");\r\n               \r\n           })\r\n            // $(\'<input>\').attr(\'type\',\'text\').attr(\'name\',\'override\').attr(\'value\',\'override\').appendTo(\'form\');\r\n            \r\n            \r\n        }else\r\n            window.location = \"<%=return_url%>\";\r\n\r\n\r\n\r\n        \r\n    </script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n     \r\n    t = Time.now - record.updated_at \r\n \r\n \r\n    if  false and  @current_role!=\'superuser\' and @current_role!=\'developer\' and @current_role!=\'admin\' # and t.to_i > 3600 * 24 \r\n     locker.destroy if locker\r\n  %>\r\n   <script>alert(\"Not allowed to edit this document!!\");window.location = \"<%=return_url%>\";</script>\r\n  <%\r\n  end\r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n<style>\r\n    .refinfo{background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc}\r\n</style>\r\n <div class=\"refinfo\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right refdate\" >\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%\r\n    if return_url.include? \'?\'\r\n        return_url += \"&reset_lock=\\\\#{locker.id}\"\r\n    else\r\n        return_url += \"?reset_lock=\\\\#{locker.id}\"\r\n    end\r\n%>\r\n<%= f.submit \"Update\".html_safe, :class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n<%= link_to \'Cancel\', return_url,:data=>{:confirm=>\'Are you sure?\'} %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"span4 well\">test</div>\r\n\r\n\r\n\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   ',NULL,NULL,NULL,'2018-07-05 03:28:10','2018-07-05 03:28:10','edit',''),(3544,'index',1363,2,'<%# view :fullwidth %>\r\n<style>\r\n                .dataTables_wrapper{position:relative;overflow:hidden}\r\n                .dataTables_wrapper table.table {clear:both;margin-bottom:6px!important;max-width:inherit}\r\n                .dataTables_wrapper table.table thead .sorting,table.table thead .sorting_asc,table.table thead .sorting_desc,table.table thead .sorting_asc_disabled,table.table thead .sorting_desc_disabled{cursor:hand;cursor:pointer}\r\n                .dataTables_wrapper table.table thead .sorting{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_both.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_asc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_asc_disabled.png) no-repeat center right}\r\n                .dataTables_wrapper table.table thead .sorting_desc_disabled{background: #e9f3f8 url(/gebo/lib/datatables/images/sort_desc_disabled.png) no-repeat center right}\r\n</style>\r\n<!-- datatable -->\r\n            <script src=\"/gebo/lib/datatables/jquery.dataTables.min.js\"></script>\r\n            <script src=\"/gebo/lib/datatables/extras/Scroller/media/js/Scroller.min.js\"></script>\r\n            <!-- datatable functions -->\r\n            <script src=\"/gebo/js/gebo_datatables.js\"></script>\r\n<%\r\n	module_name = @current_project.name\r\n	if params[:date]\r\n	session[module_name]={:date=>params[:date],:stamp=>Time.now.strftime(\'%d/%m/%Y\')}\r\n	end\r\n	if session[module_name] and session[module_name][:stamp] == Time.now.strftime(\'%d/%m/%Y\')\r\n	  params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n	his = session[:his]\r\n	user = @current_user\r\n%>\r\n	\r\n<%#session[module_name].inspect %>\r\n<%\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    if params[:reset_lock]\r\n	    l = get_model[:locker].find(params[:reset_lock])\r\n        l.destroy if l\r\n	end\r\n	if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        \r\n        p_app[:stop] = p_app[:start]\r\n        \r\n        p_app[:stop] =  (Time.parse(p_app[:start])+params[:duration].to_i*60).to_mongo\r\n        \r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Patient Record\"\r\n            \r\n            \r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n    // window.location = \"../OutPatientForm/create?patient_id=<%=patient.id.to_s%>&record_name=<%=patient[:hn]%>&parent_id=<%=rec_pm_app.id.to_s%>&return=../Home/index\";\r\n</script>\r\n<%\r\n    else\r\n %>\r\n<script>\r\n    window.location = \'index\';\r\n    // window.location = \"../OutPatientForm/create?patient_id=<%=patient.id.to_s%>&record_name=<%=patient[:hn]%>&parent_id=<%=rec_pm_app.id.to_s%>&return=../Home/index\";\r\n</script>\r\n<%      \r\n    end\r\n    end\r\n	\r\n	\r\n	\r\n	if params[:obj_id]\r\n	    now = Time.now \r\n	\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n					<!--<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Add Visit</button></a>-->\r\n					<a href=\"javascript:add_patient()\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-contact_blue_add\"></i><br />Add Patient</button></a>\r\n					<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Calendar</button></a>\r\n					<a href=\"../Report/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\" >\r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n					<h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n    \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"close\" style=\"float:right;\"  data-dismiss=\"modal\">X</a>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\"  style=\"background: #f5f5f5;\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"float:left;vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                    \r\n                    \r\n                    \r\n                </div>\r\n                <div class=\"portlet\" style=\"margin: 0 0.5em 0.5em 0\">\r\n                <span class=\"\"><label>&nbsp;</label></span>	\r\n                    <a href=\"#\" id=\"get-hn\" class=\"btn\" style=\"float:left;height:15px\">GET</a>\r\n                    \r\n                </div>\r\n               \r\n                \r\n                \r\n                 <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;margin-top:-5px;\">\r\n                    <span class=\"\"><label>Appointed Date : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;margin-top:-5px;\">\r\n                    <span class=\"\"><label>Time <span class=\"f_req\">*</span>  : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"\" style=\"width: 80px;\" required=\"required\" validationmessage=\"Cannot be empty\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'07:00\',\r\n                    	interval: 30,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	\r\n                <div id=\"duration\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;margin-top:-5px;\">\r\n                    <span class=\"\"><label>Duration<span class=\"f_req\">*</span> : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"duration\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-duration\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"duration\" id=\"data-duration\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\" value=\"\" required=\"required\" validationmessage=\"Cannot be empty\">\r\n                    </span>\r\n                </div>\r\n            	\r\n            	\r\n            	  <div id=\"appointed_room\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Room <span class=\"f_req\">*</span>: </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                    <%=select_tag \"app[room]\", options_for_select(%w{Room1 Room2 Room3 Room4 Room5 Room6}),:include_blank=>true , :required => true,:style=>\"width:80px\" %>    \r\n                  \r\n\r\n                    </div>\r\n                </div><div class=\"clear\"></div>\r\n<hr/>\r\n\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;margin-top:-5px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                 <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;margin-top:-5px;\">\r\n                    <span class=\"\"><label>Birthdate : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <!--  <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>เลขที่บัตรประชาชน :</label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div> -->\r\n                  \r\n        <!--   <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">>\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\" selected><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n        -->      \r\n                \r\n               \r\n               \r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n<div id=\"ward\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;margin-top:-5px;\">\r\n\r\n\r\n<span class=\"\"><label>Ward <span class=\"f_req\">*</span>: </label></span>\r\n\r\n	\r\n\r\n<input type=\"text\" name=\"app[ward]\" id=\"data-ward\" value=\"\" size=\"29\" style=\"vertical-align: text-top; width: 100%; \" required=\"required\" validationmessage=\"Cannot be empty\" onkeypress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" >\r\n    \r\n</div>                \r\n<div class=\"clear\"></div>                \r\n\r\n<div id=\"procedure_list\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px;min-height:30px;margin-top:-5px;\">\r\n\r\n\r\n<span class=\"\"><label>Procedure <span class=\"f_req\">*</span>: </label></span>\r\n\r\n	\r\n\r\n<input type=\"text\" name=\"app[procedure_list]\" id=\"data-procedure_list\" value=\"\" size=\"29\" style=\"vertical-align: text-top; width: 100%; \" class=\"k-textbox k-textbox-txt k-invalid\"  data-role=\"combobox\" validationmessage=\"Please select one\"  required=\"required\" validationmessage=\"Cannot be empty\" >\r\n    \r\n</div>\r\n\r\n\r\n <div id=\"provider\" class=\"  portlet \r\nRoom\r\n\r\n |  | Cancel | Delete\" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider <span class=\"f_req\">*</span>: </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\" required=\"required\" validationmessage=\"Cannot be empty\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n   <div id=\"record_by\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>ชื่อคนทำนัด<span class=\"f_req\">*</span> : </label></span>	\r\n                    <input type=\"text\" name=\"app[record_by]\" id=\"data-record_by\" size=\"10\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                </div>\r\n\r\n                \r\n                \r\n<%\r\n    if this.his_show\r\n%>\r\n\r\n<span id=\'span-his_btn\' style=\'margin-left:20px\'>\r\n\r\n  \r\n  \r\n<% if session[:his]%>\r\n<span id=\'his-status\'>\r\nWelcome <%= session[:his] %>\r\n\r\n  </span>\r\n    <a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient</a>\r\n<% else %>\r\n<span id=\'his-status\'>\r\nPlease login to get HN from HIS\r\n\r\n  </span>\r\n  <span id=\'temp-get-his\'>&nbsp;</span>\r\n            <span class=\'login-block\'>\r\n                <!--<div class=\'clear\'></div>-->\r\n                <div id=\"his-user\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px\">\r\n                    <span class=\"\"><label>Username : </label></span>	\r\n                    <input autofocus=\"\" type=\"text\" name=\"username\" id=\"input-username\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\">\r\n                </div>\r\n                <div id=\"his-pass\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Password  : </label></span>	\r\n                    <input type=\"password\" name=\"password\" id=\"input-password\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\">\r\n                </div>\r\n                <!--<div class=\'clear\'></div>-->\r\n            </span>\r\n<% end %>\r\n</span>\r\n\r\n<span id=\'span-btn\'>\r\n<% if session[:his] %>\r\n  <a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\r\n<% else %>\r\n  <span id=\'temp-his-logout\'>&nbsp;</span>\r\n  <a href=\'javascript:void(0)\' id=\'his-login\' class=\'btn btn-info\'>HIS Login</a>\r\n<% end %>\r\n</span>\r\n\r\n<% end %>\r\n            \r\n\r\n                <br/>\r\n                <div class=\'login-block btn btn-mini\' id=\'login-cancel\'  >x</div>\r\n                <span style=\'color:blue\' id=\'patient-msg\'></span>\r\n             \r\n               \r\n            	<div class=\"clear\"></div>\r\n            	\r\n               \r\n<div id=\"anes\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:180px;min-height:30px;margin-top:-5px;\">\r\n\r\n\r\n<span class=\"\"><label>Anes <span class=\"f_req\">*</span>: </label></span>\r\n\r\n	\r\n\r\n<input type=\"text\" name=\"app[anes]\" id=\"data-anes\" value=\"\" size=\"40\" style=\"vertical-align: text-top; width: 100%; \" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" default=\"default\" data-role=\"combobox\" aria-disabled=\"true\">\r\n    \r\n</div> \r\n\r\n                \r\n                      <div id=\"note\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Note : </label></span>	\r\n                    <input type=\"text\" name=\"app[note]\" id=\"data-note\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n                \r\n               \r\n               \r\n               \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <div id=\'temporary\' style=\'\'></div>\r\n                <input type=\"hidden\" name=\"record[status]\" id=\"data-status\" value=\"Appointed\"/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" id=\"room-app\" value=\"\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Patient Record\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n\r\n    function init_fields(b) {\r\n        $(\'#data-public_id\').prop(\'readonly\', b);\r\n        $(\'#data-first_name\').prop(\'readonly\',b);\r\n        $(\'#data-last_name\').prop(\'readonly\',b);\r\n        $(\'#data-prefix_name\').prop(\'\',b);\r\n        $(\'#input-prefix_name\').prop(\'\',b);\r\n        $(\'#data-gender\').prop(\'\',b);\r\n        $(\'#data-birth_date\').prop(\'\',b);\r\n        \r\n        if (!b) {\r\n            $(\'#data-public_id\').val(\"\");\r\n            $(\'#data-first_name\').val(\"\");\r\n            $(\'#data-last_name\').val(\"\");\r\n            $(\'#data-prefix_name\').val(\"\");\r\n            $(\'#input-prefix_name\').val(\"\");\r\n            $(\'#data-gender\').val(\"\");\r\n            $(\'#data-birth_date\').val(\"<%= Time.now.strftime(\'%d/%m/%Y\') %>\");\r\n        }\r\n    }\r\n\r\n    function get_patient_info(us, ps, hn){\r\n        console.log(\'US:\' + us + \', PS:\' + ps + \',HN:\' + hn)\r\n        $(\'#his-status\').html(\'connecting...\');\r\n	    \r\n<% if his %>\r\n	\r\n	    var username = \'<%=his%>\'\r\n	    var password = \'-\'\r\n	\r\n<% end %>\r\n\r\n        // var hn=prompt(\"Please enter HN\",\"\");    \r\n        // var hn = hn\r\n        username = us;\r\n        password = ps;\r\n        if (hn==\'\') { \r\n            // alert(\"Not enough information!!\"); \r\n            $(\'#his-status\').html(\'No HN information, Please fill Patient HN\')\r\n        }else{     \r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading...</span>\');    \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            $.ajax({\r\n                url: \"get_patient_info?un=\"+username+\"&ps=\"+password+\"&hn=\"+hn,\r\n                context: document.body,\r\n                crossDomain: true\r\n            }).done(function(data) {\r\n                $(\'#his-status\').html(\'retriving...\');\r\n                // eval(data);\r\n                $(\'#temporary\').html(data);\r\n                $(\'#his-status\').html(\'completed\');\r\n                \r\n                if ($(\'#data-first_name\').val() != \'\') {\r\n                    init_fields(true);\r\n                } else {\r\n                    init_fields(false);\r\n                    $(\'#his-status\').html(\'Patient not found\')\r\n                }\r\n            }).fail(function(jqXHR, textStatus) {\r\n                // alert(\"error\");\r\n                $(\'#his-status\').html(\'Error loading, Please fill Patient information\')\r\n            });\r\n        }\r\n    }\r\n    \r\n    $(\'#get-his\').click(function() {\r\n        get_patient_info(\'<%= his %>\', \'-\', $(\'#data-hn\').val());\r\n    });\r\n	        \r\n	$(\'#his-logout\').click(function() {\r\n        $(\'#his-logout\').html(\'Loading ...\');\r\n        console.log(\'logout...\')\r\n        get_patient_info(\'-\', \'-\', \'-\');\r\n        // window.location = \'../Home/index\';\r\n    });\r\n    \r\n    $(document).ready(function(){\r\n        $(\'.login-block\').hide();\r\n        $(\'#his-login\').click(function() {\r\n            if ($(\'.login-block\').is(\":visible\")) {\r\n                $(\'#his-status\').show();\r\n                $(\'.login-block\').hide();\r\n                // console.log(\'get_patient_info\')\r\n                \r\n                \r\n    us = $(\'#input-username\').val();\r\n                ps = $(\'#input-password\').val();\r\n                hn = $(\'#data-hn\').val();\r\n                // $(\'#data-hn\').val(hn);\r\n                // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n                console.log(us + \'...\' + ps + \'...\' + hn);\r\n                $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n                get_patient_info(us, ps, hn);\r\n                \r\n                setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n                \r\n                // console.log(\'xxxx\');\r\n                // $(\'#his-status\').html(\'Logged as \' + us);\r\n                \r\n                $(\'#his-login\').hide();\r\n                $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n                $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient</a>\");\r\n                \r\n                // $(\'#modal\').modal(\'hide\')\r\n                // $(\'#modal\').attr(\'aria-hidden: false\');\r\n                // $(\'.modal-backdrop\').modal(\'hide\')\r\n                \r\n                // $(\'#commit\').click(function() {\r\n                //     console.log(\'login ...\')\r\n                //     us = $(\'#input-username\').val();\r\n                //     ps = $(\'#input-password\').val();\r\n                //     hn = $(\'#input-hn\').val();\r\n                //     get_patient_info(us, ps, hn);\r\n                //     console.log(\'... pass ...\')\r\n                // });\r\n                \r\n                $(\'#his-logout\').click(function() {\r\n            	    $(\'#his-logout\').html(\'Loading ...\');\r\n            	    console.log(\'logout...\')\r\n                    get_patient_info(\'-\', \'-\', \'-\');\r\n                    // window.location = \'../Home/index\';\r\n            	});\r\n                \r\n            } else {\r\n                $(\'#his-status\').hide();\r\n                $(\'.login-block\').show();\r\n                $(\'#his-login\').text(\'Get Patient\');\r\n                console.log(\'hide\')\r\n            }\r\n        })\r\n        $(\'#login-cancel\').click(function() {\r\n            $(\'#his-status\').show();\r\n            $(\'.login-block\').hide();\r\n            $(\'#his-login\').text(\'HIS Login\');\r\n        });\r\n        $(\'#commit\').click(function() {\r\n            us = $(\'#input-username\').val();\r\n            ps = $(\'#input-password\').val();\r\n            hn = $(\'#data-hn\').val();\r\n            // $(\'#data-hn\').val(hn);\r\n            // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n            // console.log(us + \'...\' + ps + \'...\' + hn);\r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n            get_patient_info(us, ps, hn);\r\n            \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            \r\n            // console.log(\'xxxx\');\r\n            // $(\'#his-status\').html(\'Logged as \' + us);\r\n            \r\n            $(\'#his-login\').hide();\r\n            $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n            $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient from HIS</a>\");\r\n            \r\n            // $(\'#modal\').modal(\'hide\')\r\n            // $(\'#modal\').attr(\'aria-hidden: false\');\r\n            // $(\'.modal-backdrop\').modal(\'hide\')\r\n            \r\n            // $(\'#commit\').click(function() {\r\n            //     console.log(\'login ...\')\r\n            //     us = $(\'#input-username\').val();\r\n            //     ps = $(\'#input-password\').val();\r\n            //     hn = $(\'#input-hn\').val();\r\n            //     get_patient_info(us, ps, hn);\r\n            //     console.log(\'... pass ...\')\r\n            // });\r\n            \r\n            $(\'#his-logout\').click(function() {\r\n        	    $(\'#his-logout\').html(\'Loading ...\');\r\n        	    console.log(\'logout...\')\r\n                get_patient_info(\'-\', \'-\', \'-\');\r\n                // window.location = \'../Home/index\';\r\n        	});\r\n        });\r\n    });\r\n</script>\r\n\r\n<!-- mit add-->\r\n<script> \r\nfunction get_room_appoint(date){\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: \'./get_appoint\',\r\n        data: {\r\n            date: date\r\n        },\r\n        success: function(doc) {\r\n            $(\"#room-app\").val(doc);\r\n            check_room();\r\n            //  alert(doc);\r\n        }\r\n    });\r\n}\r\n\r\nfunction check_room(){\r\n    var r=$(\"#app_room\").val();\r\n    var s=$(\"#data-start\").val();\r\n    var j=$(\"#room-app\").val();\r\n    var oj = JSON.parse(j);\r\n    if(r!=\'\'&&s!=\'\'&&oj.length>0){\r\n        //alert(r+\' \'+s+\' \'+oj.length);\r\n        var isAvailable=true;\r\n        var message=\'\';\r\n        var roomUsed=0;\r\n        $.each(oj,function(i,v){\r\n            num_s = parseInt(s.replace(\':\',\'\'));\r\n            if(num_s>=parseInt(v.start.replace(\':\',\'\'))&&num_s<=parseInt(v.stop.replace(\':\',\'\'))){\r\n                roomUsed++;\r\n                if(r==v.room){\r\n                    $(\"#app_room\").val(\"\");\r\n                    isAvailable=false;\r\n                    message = r+\' is not available at \'+v.start+\'-\'+v.stop;\r\n                    return false;\r\n                }\r\n            }\r\n            \r\n        });\r\n        if(!isAvailable) alert(message);\r\n        else if(roomUsed>2){\r\n            $(\"#app_room\").val(\"\");\r\n            alert(\"Can not make more than 3 appointments in \"+s);\r\n        }\r\n        \r\n    }\r\n}\r\n\r\n$(document).ready(function(){\r\n    $(\"#data-date\").change(function(){\r\n       get_room_appoint($(this).kendoDatePicker().val()); \r\n    });\r\n    $(\"#data-start\").change(function(){check_room();});\r\n    $(\"#app_room\").change(function(){check_room();});\r\n    get_room_appoint($(\"#data-date\").kendoDatePicker().val()); \r\n});\r\n</script>\r\n<!--end mit add -->\r\n\r\n<script>\r\n    $(\"#data-procedure_list\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [{\"text\":\"EGD\",\"value\":\"EGD\"},\r\n        {\"text\":\"Colono\",\"value\":\"Colono\"},\r\n        {\"text\":\"EGD + Colono\",\"value\":\"EGD + Colono\"},\r\n        {\"text\":\"EGD (jmc)\",\"value\":\"EGD (jmc)\"},\r\n        {\"text\":\"Colono (jmc)\",\"value\":\"Colono (jmc)\"},\r\n        {\"text\":\"EGD + Colono (jmc)\",\"value\":\"EGD + Colono (jmc)\"},\r\n        {\"text\":\"Sigmoid\",\"value\":\"Sigmoid\"},\r\n        {\"text\":\"EUS\",\"value\":\"EUS\"},\r\n        {\"text\":\"ERCP\",\"value\":\"ERCP\"},\r\n        {\"text\":\"PEG\",\"value\":\"PEG\"},\r\n        {\"text\":\"PEG-J\",\"value\":\"PEG-J\"},\r\n        {\"text\":\"SSE\",\"value\":\"SSE\"},\r\n        {\"text\":\"NJ\",\"value\":\"NJ\"},\r\n        {\"text\":\"Liver Bx.\",\"value\":\"Liver Bx.\"},\r\n        {\"text\":\"BLUE RIBBON Gastroscopy (Non Sedation)\",\"value\":\"BLUE RIBBON Gastroscopy (Non Sedation)\"},\r\n        {\"text\":\"BLUE RIBBON Gastroscopy (Sedation)\",\"value\":\"BLUE RIBBON Gastroscopy (Sedation)\"},\r\n        {\"text\":\"BLUE RIBBON Colonoscopy (Non Sedation)\",\"value\":\"BLUE RIBBON Colonoscopy (Non Sedation)\"},\r\n        {\"text\":\"BLUE RIBBON Colonoscopy (Sedation)\",\"value\":\"BLUE RIBBON Colonoscopy (Sedation)\"},\r\n        {\"text\":\"BLUE RIBBON Gastro-Colonscopy (Sedation)\",\"value\":\"BLUE RIBBON Gastro-Colonscopy (Sedation)\"}\r\n        \r\n        \r\n        \r\n        \r\n        ]\r\n	\r\n    });\r\n    \r\n     $(\"#data-ward\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [{\"text\":\"OPD\",\"value\":\"OPD\"},{\"text\":\"IPD\",\"value\":\"IPD\"},{\"text\":\"OR\",\"value\":\"OR\"},{\"text\":\"ICU\",\"value\":\"ICU\"}]\r\n	\r\n    });\r\n    \r\n \r\n         $(\"#data-anes\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n        {\"text\":\"Non\",\"value\":\"Non\"},\r\n        {\"text\":\"Mod\",\"value\":\"Mod\"},\r\n        {\"text\":\"Consult GI anesth\",\"value\":\"Consult GI anesth\"},\r\n        {\"text\":\"Consult team anesth\",\"value\":\"Consult team anesth\"},\r\n        {\"text\":\"Consult SR\",\"value\":\"Consult SR\"}]\r\n	\r\n    });\r\n\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"},\r\n            {\"text\":\"MR.\",\"value\":\"MR.\"},\r\n            {\"text\":\"MS.\",\"value\":\"MS.\"},\r\n            {\"text\":\"MRS.\",\"value\":\"MRS.\"},\r\n            {\"text\":\"MISS.\",\"value\":\"MISS.\"}\r\n\r\n        ]\r\n	\r\n    });\r\n    \r\n    \r\n        $(\"#data-duration\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n         \r\n            {\"text\":\"30 นาที\",\"value\":\"30\"},\r\n            {\"text\":\"1 ชั่วโมง\",\"value\":\"60\"},\r\n            {\"text\":\"1 ชั่วโมงครึ่ง\",\"value\":\"90\"},\r\n            {\"text\":\"2 ชั่วโมง\",\"value\":\"120\"}\r\n        ]\r\n	\r\n    });\r\n    \r\n    \r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\' || val == \'MR.\'|| val == \'Mr.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n	\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-hn\').val(\'\');\r\n        $(\'#patient-msg\').text(\'\');\r\n        init_fields(false);\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        \r\n        v =  $(\'#data-hn\').val();\r\n        nv = v.replace(/-/g, \'\');\r\n        $(\'#data-hn\').val(nv);\r\n        \r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(\'#data-hn\').val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                if(data.prefix)\r\n                data.prefix_name = data.prefix\r\n                \r\n                console.log(data)\r\n                \r\n                console.log(\"[\" + data.hn + \"] \" + data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#data-hn\').val(data.hn);\r\n                $(\'#data-prefix_name\').val(data.prefix_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                // $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n\r\n\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.toString().indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                // console.log(\'xxx \' + dd);\r\n                $(\'#data-birth_date\').val(dd);\r\n                $(\'#patient-msg\').text(\'Patient found in DB\');\r\n                init_fields(true);\r\n                // console.log(\'init field = true\')\r\n            } else {\r\n                $(\'#patient-msg\').text(\'Patient not found in DB. Please fill patient info.\');\r\n                init_fields(false);\r\n                // console.log(\'init field = false\')\r\n            }\r\n            \r\n            console.log(\"... \" + $(this).val())\r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#get-hn\').click(update_patient);\r\n    });\r\n</script>\r\n\r\n<script>\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n    var tt = <%= this.update_time_ms.to_i %>; // time to refresh\r\n    \r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        // tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'../Home/index_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        setTimeout(feed_page(100), 0);\r\n<%\r\n    if this.update_time_ms != 0\r\n%>        \r\n        loadPartial();\r\n<%\r\n    end\r\n%>\r\n        console.log(\'<%= this.update_time %>...\')\r\n    });\r\n\r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print 1 page\',\'print_appointment2?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<% link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> \r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n</div><br/>\r\n\r\n',NULL,NULL,NULL,'2018-07-09 06:13:32','2018-07-09 06:13:32','index',''),(3545,'index_snsc',1272,3,'\r\n\r\n            <link rel=\"stylesheet\" href=\"/gebo/lib/fullcalendar/fullcalendar_gebo.css\" />	\r\n			<script src=\"/gebo/lib/fullcalendar/fullcalendar.min.js\"></script>\r\n			<script src=\"/gebo/lib/fullcalendar/gcal.js\"></script>\r\n\r\n<div class=\"heading\">\r\n    <h1>Study Nurse / Study Co</h1>\r\n</div>    \r\n\r\n<%\r\n\r\n    status_list = %w{ Open Final Closed Archived }\r\n    \r\n    projects = []\r\n\r\n    \r\n    models = get_model\r\n    \r\n    \r\n    if @current_role == \'admin\' or @current_role==\'developer\'\r\n        \r\n        \r\n        projects = get_model(\"project\").all\r\n    \r\n    else\r\n    \r\n    user = models[:user].where(:login=> @current_user.login).first\r\n    \r\n    member =  models[:member].where(:user_id=>user.id).first\r\n    \r\n    if member\r\n    \r\n    member_projects = models[:member_project].where(:member_id=>member.id).all\r\n    \r\n  \r\n    \r\n    \r\n    projects = get_model(\"project\").find member_projects.collect{|i| i.project_id}\r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    end\r\n    \r\n    mprojects = {}\r\n    \r\n    for i in projects\r\n        mprojects[i.id] = i \r\n    end\r\n    \r\n    \r\n    %>\r\n    \r\n    <div class=\"tabbable\">\r\n	<ul class=\"nav nav-tabs\">\r\n		<li class=\"active\"><a href=\"#tab1\" data-toggle=\"tab\">My Schedule</a></li>\r\n		<li class=\"\"><a href=\"#tab2\" data-toggle=\"tab\">My Projects</a></li>\r\n		<li><a href=\"#tab3\" data-toggle=\"tab\">My Performance</a></li>\r\n	</ul>\r\n	<div class=\"tab-content\">\r\n		<div class=\"tab-pane active\" id=\"tab1\">\r\n			<p>\r\n\r\n<%\r\n\r\n    date = Time.now\r\n    date = Date.parse params[:date] if params[:date] \r\n\r\n    visits = []\r\n    pvisits = []\r\n\r\n    for p in projects\r\n    \r\n        list = models[:visit].where(:project_id=>p.id, :date=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}).sort(:date.desc).all     \r\n        plist = models[:visit].where(:project_id=>p.id,:status=>{\'$ne\'=>\'Completed\'}, :date=>{\'$lte\'=>date.beginning_of_day}).sort(:date.desc).all     \r\n        \r\n      \r\n\r\n\r\n        for i in list\r\n        \r\n            patient = models[:patient].find i.patient_id\r\n            \r\n            sheet = models[:pl_sheet].find patient.sheet_id\r\n            \r\n            unless sheet \r\n                \r\n             visit = models[:visit].where(:patient_id=>patient.id, :sheet_id=>{\'$ne\'=>nil}).first\r\n             sheet = models[:pl_sheet].find visit.sheet_id\r\n             visit = nil\r\n\r\n            end\r\n            \r\n            period = models[:pl_period].find i.period_id\r\n            period_visit = \'\'\r\n            if period\r\n                period_visit = period.visit\r\n            end\r\n            \r\n            visits << {:status=> i.status, :project=>p,:protocol_no=>p.protocol_no, :patient=>patient, :name=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\", :hn=>patient.hn,:subject_no=>patient.subject_id,\r\n                :visit=>i, :visit_type=>i.visit_type, :date=>\"\\\\#{i.date.strftime(\"%d/%m/%Y\") if i.date}\", :sheet=>sheet, :period=>period, :period_name=> period_visit\r\n            }\r\n        \r\n        end\r\n        \r\n         for i in plist\r\n        \r\n            patient = models[:patient].find i.patient_id\r\n            if patient\r\n            sheet = models[:pl_sheet].find patient.sheet_id\r\n            \r\n            unless sheet \r\n                \r\n             visit = models[:visit].where(:patient_id=>patient.id, :sheet_id=>{\'$ne\'=>nil}).first\r\n             sheet = models[:pl_sheet].find visit.sheet_id\r\n             visit = nil\r\n\r\n            end\r\n            \r\n            period = models[:pl_period].find i.period_id\r\n            period_visit = \'\'\r\n            if period\r\n                period_visit = period.visit\r\n            end\r\n            period_visit = i.name if i.name and i.name.size>0\r\n            \r\n            pvisits << {:status=> i.status, :project=>p,:protocol_no=>p.protocol_no, :patient=>patient, :name=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\", :hn=>patient.hn,:subject_no=>patient.subject_id,\r\n                :visit=>i, :visit_type=>i.visit_type, :date=>\"\\\\#{i.date.strftime(\"%d/%m/%Y\") if i.date}\", :sheet=>sheet, :period=>period, :period_name=> period_visit\r\n            }\r\n           else\r\n              i.destroy  \r\n        end\r\n        \r\n     \r\n        \r\n        end\r\n        \r\n        \r\n    end\r\n\r\n    %>\r\n    \r\n<div><span class=\"font-size:1.5em\"><b>My Schedule</b></span>\r\n\r\n<div class=\"pull-right\">Date : <%=text_field_tag \"date\", date.strftime(\"%d/%m/%Y\"), :id=>\'select_date\' %>\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n<hr/>\r\n<script>\r\n	$(\"#select_date\").kendoDatePicker({\r\n		value: \'<%= date.strftime(\"%d/%m/%Y\") if date %>\'\r\n	});\r\n	\r\n	$(\"#select_date\").change(function(){\r\n	  	obj = $(this)\r\n		v = obj.val()\r\n        window.location=\"index?date=\"+v;\r\n	});\r\n</script>\r\n\r\n\r\n<div class=\"row\">\r\n\r\n    <%\r\n    \r\n      list = visits.collect{|i| i if i[:status]==\'\' or i[:status]==nil}.compact\r\n        \r\n      complete_list = visits.collect{|i| i if i[:status]==\'Completed\' }.compact\r\n      \r\n      cancel_list = visits.collect{|i| i if i[:status]==\'Cancelled\' }.compact\r\n      \r\n      {:schedule=>list, :complete=>complete_list, :pending=>pvisits}.each_pair do |status, list|\r\n\r\n        if status!=:pending or list.size>0\r\n\r\n    %>\r\n    <div class=\"span7\" style=\"border:0px solid\">    \r\n    \r\n    <h3><%=status.to_s.humanize%> Visit </h3>\r\n    <div class=\"pull-right\"><%#link_to \'Print All\', \"print_all?date=\\\\#{date}\",:class=>\'btn btn-mini\' %></div>\r\n    <table class=\"table\">\r\n        <thead>\r\n            <tr>\r\n                <th>\r\n                    Protocol No\r\n                </th>\r\n                <th>\r\n                    Date\r\n                </th>\r\n                <th>\r\n                    Subject No\r\n                </th>\r\n                <th>\r\n                    Patient Name\r\n                </th>\r\n            \r\n                <th>\r\n                    Visit\r\n                </th>\r\n                <th>\r\n                    Visit Type\r\n                </th>\r\n                \r\n                <th>\r\n                    Actions\r\n                </th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n        \r\n    <%\r\n        if list.size > 0 \r\n        for i in list\r\n    %>\r\n    <tr>\r\n        <td>\r\n            <%=link_to i[:protocol_no], \"../Project/show?id=\\\\#{i[:project].id}\" %>\r\n        </td>\r\n        \r\n          \r\n        <td>\r\n            <%=link_to i[:date], \"../Visit/show?id=\\\\#{i[:visit].id}\" %>\r\n        </td>\r\n        \r\n        \r\n        <td>\r\n            <%=link_to i[:subject_no], \"../Patient/show?id=\\\\#{i[:patient].id}\" %>        </td>\r\n        <td>\r\n            <%=link_to i[:name], \"../Patient/show?id=\\\\#{i[:patient].id}\" %>\r\n        </td>\r\n        \r\n        \r\n     \r\n        <td>\r\n            <%=\"\\\\#{i[:period_name]}\"%>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=\"\\\\#{i[:visit_type]}\"%>\r\n        </td>\r\n        \r\n        \r\n        <td>\r\n            <%=link_to \"Detail\", \"../Visit/show?id=\\\\#{i[:visit].id}\", :class=>\'btn btn-success btn-mini\' %>\r\n            <%#link_to \"Work List\", \"../Visit/print?id=\\\\#{i[:visit].id}\", :class=>\'btn btn-mini\', :target=>\'_blank\' if i[:visit_type]!=\'UNSCHEDULE\' %>\r\n            <%= i[:status] %>\r\n        </td>\r\n        \r\n      \r\n        \r\n    </tr>\r\n\r\n    <% end %>\r\n         <% else %>\r\n       <tr>\r\n           <td colspan=\"5\">No Records </td>\r\n       </tr>\r\n      <% end %>\r\n      \r\n        </tbody>\r\n    </table>\r\n  </div>  \r\n   <% end %>\r\n       <% end %>\r\n</div>\r\n<!---------------- -->\r\n\r\n<%  \r\n        \r\n        events = models[:visit].where(:date=>{\'$ne\'=>nil},:project_id=>{\'$in\'=>projects.collect{|i| i.id}}).sort(\'status,project_id, visit_id\').all\r\n    \r\n    \r\n             events.collect!{|e|  \r\n    \r\n               \r\n                \r\n            \r\n                    period = models[:pl_period].find e.period_id\r\n                    project = mprojects[e.project_id]\r\n                    patient = models[:patient].find e.patient_id\r\n                    patient_name = \'DELETED\'\r\n                    patient_name = \"\\\\#{patient.subject_id} : \\\\#{patient.first_name} \\\\#{patient.last_name} \" if patient\r\n                    \r\n                    traveling = \"*T: \\\\#{e.traveling_note} \\\\#{e.traveling_status}\" if e.traveling_note and e.traveling_note!=\"\"\r\n\r\n\r\n                    title = \"\\\\#{project.protocol_no} : \\\\#{period.visit if period} : \\\\#{patient_name} \\\\#{\'#\'+e.note if e.note} \\\\#{traveling}\"\r\n                    color = \"#f5eeef\"\r\n                    \r\n                    \r\n                    color = \"#eff5ef\" if e.status==\'Completed\'\r\n                 \r\n    \r\n    			{\r\n    			        :title=>title,\r\n						:start=> DateTime.parse(e.date.strftime(\"%Y-%m-%d\")+\"T\"+e.date.strftime(\"%H:%M\") ),\r\n						:end=>  DateTime.parse(e.date.strftime(\"%Y-%m-%d\")+\"T\"+e.date.strftime(\"%H:%M\")),\r\n						:allDay=> true,\r\n                        :color=> color,\r\n                        :textColor=>\"#111\",\r\n                        :url=>\"../Visit/show?id=\\\\#{e.id}\"\r\n                }\r\n    \r\n    }\r\n\r\n  er = models[:visit].where(:date=>nil,:project_id=>{\'$in\'=>projects.collect{|i| i.id}}).sort(\'status,project_id, visit_id\').all\r\n%>\r\n<% if er.size>0 %><br/>\r\n<div class=\"aler alert-danger\"><br/>\r\n<%=er.collect{|i| link_to \'ERROR no date\', \"../Visit/edit?id=\\\\#{i.id}\"  }.join(\'<br/>\').html_safe %><br/><br/>\r\n</div>\r\n<% end %>\r\n    \r\n\r\n<style>\r\n.fc-button-content{\r\n    padding:8px;\r\n}\r\n    \r\n</style>\r\n<br/><br/>\r\n<div class=\"row-fluid\">\r\n	<div id=\"calendar\" class=\"span12\"></div>\r\n</div>\r\n\r\n<script>\r\n\r\n    \r\n    /* [ ---- Gebo Admin Panel - calendar ---- ] */\r\n\r\n	$(document).ready(function() {\r\n		gebo_calendar.regular();\r\n// 		gebo_calendar.google();\r\n		//* resize elements on window resize\r\n		var lastWindowHeight = $(window).height();\r\n		var lastWindowWidth = $(window).width();\r\n		$(window).on(\"debouncedresize\",function() {\r\n			if($(window).height()!=lastWindowHeight || $(window).width()!=lastWindowWidth){\r\n				lastWindowHeight = $(window).height();\r\n				lastWindowWidth = $(window).width();\r\n				//* rebuild calendar\r\n				$(\'#calendar\').fullCalendar(\'render\');\r\n				// $(\'#calendar_google\').fullCalendar(\'render\');\r\n			}\r\n		});\r\n	});\r\n	\r\n	//* calendar\r\n	gebo_calendar = {\r\n		regular: function() {\r\n			var date = new Date();\r\n			var d = date.getDate();\r\n			var m = date.getMonth();\r\n			var y = date.getFullYear();\r\n			var calendar = $(\'#calendar\').fullCalendar({\r\n				header: {\r\n					left: \'prev next\',\r\n					center: \'title,today\',\r\n					right: \'\'\r\n				},\r\n				buttonText: {\r\n					prev: \'<i class=\"icon-chevron-left cal_prev\" />\',\r\n					next: \'<i class=\"icon-chevron-right cal_next\" />\'\r\n				},\r\n				aspectRatio: 1.5,\r\n				selectable: true,\r\n				selectHelper: true,\r\n				select: function(start, end, allDay) {\r\n				    console.log(start)\r\n				    window.location=\"../Home/index?date=\"+(start);\r\n				    \r\n				// 	var title = prompt(\'Event Title:\');\r\n				// 	if (title) {\r\n				// 		calendar.fullCalendar(\'renderEvent\',\r\n				// 			{\r\n				// 				title: title,\r\n				// 				start: start,\r\n				// 				end: end,\r\n				// 				allDay: allDay\r\n				// 			},\r\n				// 			true // make the event \"stick\"\r\n				// 		);\r\n				// 	}\r\n				// 	calendar.fullCalendar(\'unselect\');\r\n				},\r\n				editable: true,\r\n				theme: false,\r\n				events: <%=events.to_json.html_safe%>,\r\n				eventColor: \'#bcdeee\'\r\n			})\r\n		}\r\n	};\r\n	\r\n</script>\r\n\r\n<%\r\nstatus = \'cancel\'\r\nlist = cancel_list\r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n       <div class=\"span6\" style=\"border:0px solid\">    \r\n    <h3><%=status.to_s.humanize%> Visit </h3>\r\n    \r\n    <table class=\"table\">\r\n        <thead>\r\n            <tr>\r\n                <th>\r\n                    Protocol No\r\n                </th>\r\n                <th>\r\n                    Date\r\n                </th>\r\n                <th>\r\n                    HN\r\n                </th>\r\n                <th>\r\n                    Patient Name\r\n                </th>\r\n            \r\n                <th>\r\n                    Visit\r\n                </th>\r\n                <th>\r\n                    Visit Type\r\n                </th>\r\n                \r\n                <th>\r\n                    Actions\r\n                </th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n    <%\r\n        for i in list\r\n    %>\r\n    <tr>\r\n        <td>\r\n            <%=link_to i[:protocol_no], \"../Project/show?id=\\\\#{i[:project].id}\" %>\r\n        </td>\r\n        \r\n          \r\n        <td>\r\n            <%=link_to i[:date], \"../Visit/show?id=\\\\#{i[:visit].id}\" %>\r\n        </td>\r\n        \r\n        \r\n        <td>\r\n            <%=link_to i[:hn], \"../Patient/show?id=\\\\#{i[:patient].id}\" %>        </td>\r\n        <td>\r\n            <%=link_to i[:name], \"../Patient/show?id=\\\\#{i[:patient].id}\" %>\r\n        </td>\r\n        \r\n        \r\n     \r\n        <td>\r\n            <%=\"\\\\#{i[:sheet].version} : \\\\#{i[:period_name]}\"%>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=\"\\\\#{i[:visit_type]}\"%>\r\n        </td>\r\n        \r\n        \r\n        <td>\r\n            <%=link_to \"Detail\", \"../Visit/show?id=\\\\#{i[:visit].id}\", :class=>\'btn info \' %>\r\n            <%#link_to \"Work List\", \"../Visit/print?id=\\\\#{i[:visit].id}\", :class=>\'btn\', :target=>\'_blank\' if i[:visit_type]!=\'UNSCHEDULE\' %>\r\n            <%=i[:status]%>\r\n            \r\n        </td>\r\n        \r\n      \r\n        \r\n    </tr>\r\n    <% end %>\r\n        </tbody>\r\n    </table>\r\n    \r\n</div>\r\n</div>\r\n\r\n			</p>\r\n		</div>\r\n		<div class=\"tab-pane\" id=\"tab2\">\r\n			<p>\r\n<h3> My Projects </h3>\r\n<hr/>    <%\r\n    \r\n    for s in status_list\r\n    \r\n    list = projects.collect{|i| i if i.status==s }.compact\r\n    \r\n    \r\n    \r\n    %>\r\n<div class=\"heading\">\r\n    <h3><%=s%> <%=link_to \"Create\",\"../Project/create?status=\\\\#{s}\", :class=>\'btn btn-mini\' %></h3>\r\n</div>    \r\n<table class=\"table\">\r\n<thead>\r\n    <tr>\r\n        <th>No.</th>\r\n        <th>Protocol No.</th>\r\n        <th>Title</th> \r\n        <th>Phase</th>\r\n        <th>Sponsor</th>\r\n        <th>CRO</th>\r\n        <th>CRA</th>\r\n        <th>#Patient</th>\r\n        <th>Duration</th>\r\n    </tr>\r\n</thead>\r\n<tbody>\r\n<%\r\nlist.each_with_index do |i,index|\r\n%>\r\n<tr>\r\n    <td><%=index+1%>.</td>\r\n\r\n    <td><%=link_to i.protocol_no, \"../Project/show?id=\\\\#{i.id}\" %></td>\r\n    <td><%=link_to i.project_title[0..30], \"../Project/show?id=\\\\#{i.id}\" %></td>\r\n    <td><%=i.phase%></td>\r\n    <td><%=i.sponsor%></td>\r\n    <td><%=i.cro%></td>\r\n    <td><%=i.cra_contact%></td>\r\n    <td><%=i.no_of_patient%></td>\r\n    <td><%=i.duration%></td>\r\n</tr>\r\n<% end %>\r\n</tbody>\r\n</table>\r\n\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n			</p>\r\n		</div>\r\n		<div class=\"tab-pane\" id=\"tab3\">\r\n			<p>\r\n<%\r\n    patients = []\r\n    visits = []\r\n    \r\n    for i in projects \r\n        \r\n        ps = models[:patient].where(:project_id=>i.id).all\r\n        patients += ps\r\n    \r\n        vs = models[:visit].where(:project_id=>i.id).all\r\n        visits += vs\r\n        \r\n    end\r\n\r\n\r\n%>\r\n\r\n\r\n<h3> My Performance </h3>\r\n<hr/>\r\n<b>Project view</b>\r\n<ul>\r\n    <li> Number of Projects : <%=projects.size %> / <%=models[:project].size%></li>\r\n    <li> Number of Open Projects : <%=projects.collect{|i| i if i.status==\'Open\' }.size %></li>\r\n    <li> Number of Close Projects :<%=projects.collect{|i| i if i.status==\'Open\' }.size %></li>\r\n</ul>\r\n<b>Patient view</b>\r\n<ul>\r\n    <li> Number of Patients : <%=patients.size %></li>\r\n    <li> Number of Visits : <%=visits.size %></li>\r\n</ul>\r\n\r\n\r\n\r\n\r\n\r\n			</p>\r\n		</div>\r\n	</div>\r\n</div>\r\n    \r\n    \r\n    \r\n\r\n\r\n',NULL,NULL,NULL,'2018-07-10 02:46:21','2018-07-10 02:46:21','index_snsc',''),(3546,'my_project',1272,2,'<div class=\"heading\">\r\n    <h1>My Project</h1>\r\n</div>    \r\n\r\n<%\r\n    models = get_model\r\n\r\n    status_list = %w{ Open Final Closed Archived }\r\n    projects = []\r\n    \r\n    if @current_role == \'admin\' or @current_role==\'developer\' or  @current_role==\'pharmacist\' or  @current_role==\'accounting\'\r\n        \r\n    projects = get_model(\"project\").all\r\n    \r\n    \r\n    else\r\n    \r\n    user = models[:user].where(:login=> @current_user.login).first\r\n    \r\n    member =  models[:member].where(:user_id=>user.id).first\r\n    \r\n    if member\r\n    \r\n    member_projects = models[:member_project].where(:member_id=>member.id).all\r\n    \r\n    \r\n    projects = get_model(\"project\").find member_projects.collect{|i| i.project_id}\r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    \r\n    for s in status_list\r\n    \r\n    list = projects.collect{|i| i if i.status==s }.compact\r\n    %>\r\n<div class=\"heading\">\r\n    <h3><%=s%> <%=link_to \"Create\",\"../Project/create?status=\\\\#{s}\", :class=>\'btn btn-mini\' if  @current_role == \'admin\' or @current_role==\'developer\'  and  @current_role == \'startup\' %></h3>\r\n</div>    \r\n<table class=\"table\">\r\n<thead>\r\n    <tr>\r\n        <th>No.</th>\r\n        <th>Protocol No.</th>\r\n        <th>Title</th> \r\n        <th>Phase</th>\r\n        <th>Sponsor</th>\r\n        <th>CRO</th>\r\n        <th>CRA</th>\r\n        <th>#Patient</th>\r\n        <th>Duration</th>\r\n    </tr>\r\n</thead>\r\n<tbody>\r\n<%\r\nlist.each_with_index do |i,index|\r\n%>\r\n<tr>\r\n    <td><%=index+1%>.</td>\r\n    <td><%=link_to i.protocol_no, \"../Project/show?id=\\\\#{i.id}\" %></td>\r\n    <td><%=link_to i.project_title[0..30], \"../Project/show?id=\\\\#{i.id}\" %></td>\r\n    <td><%=i.phase%></td>\r\n    <td><%=i.sponsor%></td>\r\n    <td><%=i.cro%></td>\r\n    <td><%=i.cra_contact%></td>\r\n    <td><%=i.no_of_patient%></td>\r\n    <td><%=i.duration%></td>\r\n</tr>\r\n<% end %>\r\n</tbody>\r\n</table>\r\n\r\n\r\n<%\r\nif false\r\nfor i in list\r\n%>\r\n\r\n    <%=button_tag \"\\\\#{i.project_title}<br/>\\\\#{i.cro}<br/><span style=\'color:blue\'>\\\\#{i.status}</span>\".html_safe, :class=>\'btn\', :style=>\"width:180px;height:100px;margin:20px\", :onclick=>\"javascript:window.location=\'../Project/show?id=\\\\#{i.id}\'\" %>\r\n\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n',NULL,NULL,NULL,'2018-07-10 02:51:36','2018-07-10 02:51:36','my_project',''),(3547,'config',1363,1,'[\r\n{:name=>\'Endoscopist Records\',:open=>true,:actions=>[\r\n{:name=>\'Gastroscopy\',:service=>\'gastroscopy\',:dashboard=>true,:link=>\'../Gastroscopy/index\',:remote=>false},\r\n{:name=>\'Colonosopy\',:service=>\'colonoscopy\',:dashboard=>true,:link=>\'../Colonoscopy/index\',:remote=>false},\r\n{:name=>\'EUS\',:service=>\'eus\',:dashboard=>true,:link=>\'../eus/index\',:remote=>false},\r\n{:name=>\'ERCP\',:service=>\'ercp\',:dashboard=>true,:link=>\'../ercp/index\',:remote=>false},\r\n{:name=>\'Sigmoid\',:service=>\'sigmoid\',:dashboard=>true,:link=>\'../Sigmoid/index\',:remote=>false},\r\n{:name=>\'ESD\',:service=>\'esd\',:dashboard=>true,:link=>\'../esd/index\',:remote=>false},\r\n{:name=>\'EFTR\',:service=>\'eftr\',:dashboard=>true,:link=>\'../Eftr/index\',:remote=>false},\r\n{:name=>\'PEG\',:service=>\'peg\',:dashboard=>true,:link=>\'../Peg/index\',:remote=>false},\r\n{:name=>\'PED-J\',:service=>\'ped_j\',:dashboard=>true,:link=>\'../PedJ/index\',:remote=>false},\r\n{:name=>\'NJ\',:service=>\'nj\',:dashboard=>true,:link=>\'../Nj/index\',:remote=>false},\r\n{:name=>\'DBE\',:service=>\'dbe\',:dashboard=>true,:link=>\'../dbe/index\',:remote=>false},\r\n{:name=>\'GI KPI\',:service=>\'gi_kpi\',:dashboard=>true,:link=>\'../gi_kpi/index\',:remote=>false},\r\n{:name=>\'gi_pre_procedure_assessment\',:service=>\'gi_pre_procedure_assessment\',:dashboard=>true,:link=>\'../GiPreProcedureAssessment/index\',:remote=>false},\r\n{:name=>\'Bowel Preparation Record\',:service=>\'bowel_preparation_record\',:dashboard=>true,:link=>\'../BowelPreparationRecord/index\',:remote=>false}]}]\r\n',NULL,NULL,NULL,'2018-07-10 12:51:54','2018-07-10 12:51:54','config',''),(3548,'document_name',1395,1,'\'eus\'',NULL,NULL,NULL,'2018-07-10 14:12:22','2018-07-10 14:12:22',NULL,NULL),(3551,'display_script',1395,4,'\r\n<style>\r\n    .heads { width:250px; float:left; text-transform: uppercase; font-weight: bold;padding:5px;}\r\n    .headss {width:170px;}\r\n    .red {color: #A30D0D;}\r\n    .green {color: #1EA30D; float:left; padding-left:10px; width:200px; padding:5px; font-weight: bold;}\r\n    .detail { width:350px;padding:5px;float:left;}\r\n    .detail p{font-size:16px}\r\n    .consent { width:120px; float:left; text-transform: uppercase; font-weight: bold;padding:5px;}\r\n    .procedure {width:120px; float:left; text-transform: uppercase; font-weight: bold;padding:5px;}\r\n    .madication {width:100px};\r\n</style>\r\n         <div class=\"heads red headss\"> instrument  </div> <div class=\"detail\">  <%= render_value \'instrument\' %></div><br/>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"heads red headss\">Endoscopist </div> <div class=\"detail\"><%=render_value \'endoscopist\'%>  </div><br/>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"heads red headss\">anesthesiologist  </div> <div class=\"detail\">   <%= render_value \'anesthesiologist\' if @record.anesthesiologist %>  <%= render_value \'other_anesthesiologist\' %></div><br/>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"heads red headss\"> Type of Anesthesia   </div> <div class=\"detail\">  <%= render_value \'type_of_anesthesia\' %></div><br/>\r\n<div class=\"clear\"></div>\r\n         <div class=\"heads red headss\"> madication  </div> <div class=\"detail\"> \r\n         \r\n                 <% if @record.propofol_mg !=\'\' %>Propofol <%=render_value \'propofol_mg\'%> ,<% end%>\r\n                 <% if @record.dormicum_mg !=\'\' %>Dormicum <%=render_value \'dormicum_mg\'%> ,<% end%>\r\n                 <% if @record.fentanyl_mg !=\'\' %>Fentanyl <%=render_value \'fentanyl_mg\'%> ,<% end%>\r\n                 <% if @record.pethdine_mg !=\'\' %>Pethdine <%=render_value \'pethdine_mg\'%> ,<% end%>\r\n                 <% if @record.hyoscine_mg !=\'\' %>Hyoscine <%=render_value \'hyoscine_mg\'%> ,<% end%>\r\n                 <% if @record.etomidate_mg !=\'\' %>Etomidate <%=render_value \'etomidate_mg\'%> ,<% end%></div><br/>\r\n       <div class=\"clear\"></div>\r\n         <div class=\"consent red\"> consent </div> <div class=\"detail\" style=\"float: inherit;\">  <%= render_value \'consent\' %></div><br/>\r\n        <div class=\"clear\"></div>\r\n        <div class=\"procedure red\"> procedure </div> <div class=\"detail\" style=\"float: inherit;\">  <%= render_value \'procedure\' %></div><br/>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"heads red\"><text>FINDINGS</text></div><div class=\"clear\"></div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Endoscopic finding </div> <div class=\"detail\"><% if @record.endoscopic_finding ==\"\" %>Normal<%else%><%= render_value \'endoscopic_finding\' %> <% end%>  </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Echoscopic finding </div> <div class=\"detail\"><% if @record.echoscopic_finding ==\"\" %>Normal<%else%><%= render_value \'echoscopic_finding\' %> <% end%>  </div>\r\n         <div class=\"clear\"></div>\r\n\r\n         <div class=\"heads red\"> Final diagnosis : </div> <div class=\"detail\">  <%= render_value \'diagnosis\' %></div><br/>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"heads red\"> Fine needle aspiration : </div> <div class=\"detail\">  <%= render_value \'fine_needle_aspiration\' %> <b class=\"red\" style=\"padding: 0 20px 0 20px\"> </b><%= render_value \'x_passes\' %>\r\n         <b class=\"red\" style=\"padding: 0 20px 0 20px\">Needle no :</b><%= render_value \'needle_no\' %>\r\n         </div><br/>\r\n        <div class=\"clear\"></div>\r\n         <div class=\"heads red\"> therapeutic procedure : </div> <div class=\"detail\">  <%= render_value \'therapeutic_procedure\' %></div><br/><br/>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"heads red\"> suggestion : </div> <div class=\"detail\">  <%= render_value \'suggestion\' %></div><br/>\r\n\r\n         \r\n\r\n  \r\n\r\n',NULL,NULL,NULL,'2018-07-10 14:13:47','2018-07-10 14:13:47','display_script','*'),(3552,'export_with_image',235,3,'<%\r\n\r\n ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    models = get_model\r\n    \r\n    ap_model = models[:appointment]\r\n    \r\n    p_model = models[:provider]\r\n     \r\n    \r\n    from_date = \"01/05/2016\".to_datetime.to_mongo\r\n    to_date = Time.now\r\n     \r\n    aps = ap_model.all(:date.gte=>from_date.at_beginning_of_day,:date.lt=>to_date.end_of_day) \r\n    \r\n    # for a in aps\r\n    #     a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    # end\r\n    \r\n    pms  = module_model.where(:module_id=>aps.collect{|i| i.id}).all\r\n    map_pms = pms.map{|i| [i.module_id, i] }.to_h\r\n    \r\n    \r\n    patients = patient_model.find pms.collect{|i| i.patient_id}\r\n    map_patients = patients.map{|i| [i.id, i]}.to_h\r\n    \r\n    \r\n    cpms = module_model.where(:parent_id=>pms.collect{|i| i.id}).all\r\n    map_cpms = cpms.map{|i| [i.parent_id,i]}.to_h\r\n    \r\n    colpos = models[:colposcopy].find cpms.collect{|i| i.module_id }\r\n    map_colpos = colpos.map{|i| [i.id, i]}.to_h\r\n    \r\n    @document = @current_project.get_document \'colposcopy\'\r\n    \r\n    list  = []\r\n    aps[0..-1].each do |app|\r\n    \r\n    if pm = map_pms[app.id] and cpm = map_cpms[pm.id] and colpo = map_colpos[cpm.module_id] and patient = map_patients[pm.patient_id]\r\n        \r\n    bdate = 0\r\n    bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n    age = (pm[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n    @record = colpo\r\n    \r\n    data = @document.list_fields.map{|i| \r\n        \r\n        [i.column_name, render_value(i.column_name).strip]\r\n    \r\n    }.to_h\r\n    \r\n    images = data[\'images\']\r\n    \r\n    \r\n    atts = models[:attachment].find eval(images)\r\n    \r\n    atts.collect!{|i| i.path} if atts\r\n    \r\n    \r\n    data.merge! \'date\'=>app.date.strftime(\"%d-%m-%Y\"),\'age\'=>age, \'hn\'=>patient.hn,\'gender\'=>patient.gender, \'name\'=>\"\\\\#{patient.prefix_name}\\\\#{patient.first_name} \\\\#{patient.last_name}\", \'images\'=>atts.join(\"|\")  \r\n    \r\n    list << data\r\n    \r\n    end    \r\n        \r\n    end    \r\n    \r\n    \r\n    cols = %w{date hn name age gender}+ @document.list_fields.collect{|i| i.column_name}\r\n    if false\r\n%><table class=\"table\">\r\n    <thead>\r\n        <% for i in cols %>\r\n        <th><%=i%></th>\r\n        <% end %>\r\n    </thead>\r\n    <tbody>\r\n        <% list.each_with_index do |r,ridx | %>\r\n        <tr>\r\n        <% for i in cols \r\n            v = r[i]\r\n            v = r[i].html_safe if v.instance_of? String\r\n        %>\r\n        <td><%=v%></td>\r\n        <% end %>\r\n        </tr>\r\n        <% end %>\r\n    </tbody>\r\n</table>\r\n<%else%><%= cols.join(\"\\t\") %>\r\n<% list.each_with_index do |r,ridx | %>\r\n<%= cols.collect{|i|  \r\n    v = r[i]\r\n    v = r[i].html_safe if v.instance_of? String\r\n    v\r\n}.join(\"\\t\")  %>\r\n<% end %>\r\n\r\n<% end %>\r\n',NULL,NULL,NULL,'2018-07-15 04:05:50','2018-07-15 04:05:50','export_with_image','*'),(3553,'index',1396,2,'<h1>Reports</h1>\r\n<h3><center class=\"alert\">Under Construction!!!</center></h3>',NULL,NULL,NULL,'2018-07-17 15:58:43','2018-07-17 15:58:43','index',''),(3554,'index',1397,2,'<h1>Reports</h1>\r\n<h3><center class=\"alert\">Under Construction!!!</center></h3>',NULL,NULL,NULL,'2018-07-17 15:59:46','2018-07-17 15:59:46','index',''),(3555,'document_name',1398,1,'\'ticket\'',NULL,NULL,NULL,'2018-07-17 16:00:39','2018-07-17 16:00:39',NULL,NULL),(3556,'index',1278,2,'<div class=\"heading\">\r\n    <h1>Projects\r\n    <div class=\"right\">\r\n        Search : <%= text_field_tag \'search\', \'\', :id=>\'search_field\' %>\r\n    </div>\r\n    \r\n</h1>  \r\n  \r\n</div>    \r\n\r\n<%\r\n    \r\n    models = get_model\r\n    \r\n    today_schedule = 0\r\n\r\n%>\r\n\r\n<%# image_tag \"/esm/cusys/cucrc/ic1.png\"%>\r\n\r\n<style>\r\n    td{width:80px}\r\n</style>\r\n<%\r\n\r\n    status_list = %w{New  Pre-Startup Startup Open Final Closed Archived }\r\n      if @current_role == \'admin\' or @current_role==\'developer\'\r\n        \r\n        \r\n        projects = get_model(\"project\").all\r\n    \r\n    else\r\n    \r\n    user = models[:user].where(:login=> @current_user.login).first\r\n    \r\n    member =  models[:member].where(:user_id=>user.id).first\r\n    \r\n    if member\r\n    \r\n    member_projects = models[:member_project].where(:member_id=>member.id).all\r\n    \r\n    projects = get_model(\"project\").find member_projects.collect{|i| i.project_id}\r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    end\r\n    for s in status_list\r\n    \r\n    list = projects.collect{|i| i if i.status==s }.compact\r\n    %>\r\n<div class=\"heading\">\r\n    <h3><%=s%> <%=link_to \"Create\",\"../Project/create?status=\\\\#{s}\", :class=>\'btn btn-mini\' %></h3>\r\n</div>    \r\n<table class=\"table\">\r\n<thead>\r\n    <tr>\r\n        <th>No.</th>\r\n        <th>Protocol No.</th>\r\n        <th style=\"width:200px\">Title</th> \r\n        <th>Short Name</th>\r\n        <th>Phase</th>\r\n        <th>Sponsor</th>\r\n        <th>CRO</th>\r\n        <th>CRA</th>\r\n        \r\n        <th>Budget/OH</th>\r\n        <th>#Patient</th>\r\n        <th>Duration</th>\r\n        <th>Action</th>\r\n    </tr>\r\n</thead>\r\n<tbody>\r\n<%\r\nlist.sort{|a,b| a.protocol_no<=>b.protocol_no}.each_with_index do |i,index|\r\n%>\r\n<tr id=\"<%=i.id%>\" class=\"project\" >\r\n    <td><%=index+1%>.</td>\r\n    <td><%=i.protocol_no%></td>\r\n    <td><%=link_to i.project_title[0..50], \"../Project/show?id=\\\\#{i.id}\" %></td>\r\n     <td><%=i.short_name%></td>\r\n\r\n\r\n    <td><%=i.phase%></td>\r\n    <td><%=i.sponsor%></td>\r\n    <td><%=i.cro%></td>\r\n    <td><%=i.cra_contact%></td>\r\n    <td><%=\'<i class=\"splashy-check\"></i>\'.html_safe if i.budget_approved %> / <%=\'<i class=\"splashy-check\"></i>\'.html_safe if i.oh != \'false\' %></td>\r\n    <td><%=i.no_of_patient%></td>\r\n    <td><%=i.duration%></td>\r\n    <td><%=link_to \'Delete\',\"destroy?id=\\\\#{i.id}\",:class=>\'btn btn-small btn-danger\', :data=>{:confirm=>\'Are you sure?\'} if %w{admin developer startup}.index(@current_role)%></td>\r\n</tr>\r\n<% end %>\r\n</tbody>\r\n</table>\r\n\r\n\r\n<%\r\nif false\r\nfor i in list\r\n%>\r\n\r\n    <%=button_tag \"\\\\#{i.project_title}<br/>\\\\#{i.cro}<br/><span style=\'color:blue\'>\\\\#{i.status}</span>\".html_safe, :class=>\'btn\', :style=>\"width:180px;height:100px;margin:20px\", :onclick=>\"javascript:window.location=\'../Project/show?id=\\\\#{i.id}\'\" %>\r\n\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n<% end %>\r\n\r\n<script>\r\n   var  list = <%=projects.collect{|i| [i.protocol_no,i.short_name,i.id] }.to_json.html_safe %>;\r\n    $(\'#search_field\').keyup(function(){\r\n       \r\n       \r\n        \r\n        q = $(this).val()\r\n        \r\n        var re = new RegExp(q, \'i\');\r\n        \r\n        if(q.length>0){\r\n            \r\n             $(\'.project\').hide();\r\n            \r\n            for(var id in list){\r\n                v = list[id];\r\n                \r\n                var myArray = re.exec(v[0]);\r\n                var myArray2 = re.exec(v[1]);\r\n                \r\n                if(myArray!=null||myArray2!=null){\r\n                    $(\'#\'+v[2]).show();\r\n                }\r\n                \r\n                \r\n            }\r\n            \r\n                \r\n        }else{\r\n             $(\'.project\').show();\r\n        }\r\n        \r\n        \r\n    })\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2018-07-17 16:11:02','2018-07-17 16:11:02','index',''),(3557,'search',1272,2,'<h1>Search Result</h1>\r\n<%\r\n    models = get_model\r\n    \r\n    q = params[:query] \r\n    exp = /\\\\#{q}/i\r\n    projects = models[:project].where(\'$or\'=>[{:protocol_no=>exp},{:project_title=>exp},{:project_title_th=>exp},{:sponsor=>exp}]).all\r\n    patients = models[:patient].where(\'$or\'=>[{:first_name=>exp},{:last_name=>exp}, {:subject_id=>exp}]).all\r\n\r\n\r\n%>\r\n\r\n<%=exp.inspect %>\r\n\r\n<hr/>\r\n<%=tabular :data=>projects, :model =>%w{protocol_no project_title project_title_th sponsor} do |row,out| \r\n    out << link_to(\"Show\", \"../Project/show?id=\\\\#{row.id}\",:class=>\'btn\')\r\nout\r\nend\r\n%>\r\n\r\n<hr/>\r\n<%=tabular :data=>patients, :model =>%w{subject_id first_name last_name } do |row,out| \r\n    out << link_to(\"Show\", \"../Patient/show?id=\\\\#{row.id}\",:class=>\'btn\')\r\nout\r\nend\r\n%>',NULL,NULL,NULL,'2018-07-17 16:38:45','2018-07-17 16:38:45','search',''),(3558,'config',1308,1,'config = {}\r\n\r\nconfig[:version] = \'1.1\'\r\n\r\n\r\nconfig',NULL,NULL,NULL,'2018-07-17 16:59:05','2018-07-17 16:59:05','config',''),(3559,'print_lab',1385,3,'<html>\r\n<head>\r\n			<%= javascript_include_tag \"application\"  %>\r\n			<%= stylesheet_link_tag    \"application\" ,\"elfinder\",\"elfinder-theme\"%>\r\n			<%= csrf_meta_tag %>\r\n</head>\r\n<body>\r\n<style>\r\n    table{border:1px};\r\n</style>\r\n\r\n<h1> Laboratory Order Sheet </h1>\r\n... Need template ....\r\n<%\r\n  models = get_model\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  \r\n  project = models[:project].find(record.project_id)\r\n  sheet = models[:pl_sheet].find(record.sheet_id)\r\n  period = models[:pl_period].find(record.period_id)\r\n  patient = models[:patient].find(record.patient_id)\r\n  \r\n  period_items  = models[:pl_period_product].where(:sheet_id=>sheet.id).order(:sort_order).all\r\n  \r\n  m_products = Hash[models[:pl_product].find(period_items.compact.collect{|i| i.product_id}).map{|i| [i.id, i]}]\r\n  \r\n  items  = models[:pl_period_item].where(:sheet_id=>sheet.id, :period_id=>period.id).all\r\n\r\n  \r\n\r\n  pimap = {}\r\n  \r\n  for i in items\r\n    pimap[i.period_product_id] = i \r\n  end\r\n  \r\n  \r\n  \r\n  \r\n  @show=true\r\n%>\r\n<style>\r\n    @media print {\r\n  body {\r\n  color: #000;\r\n  }\r\n  table{\r\n      border-collapse: collapse;\r\n      padding:5px;\r\n      font-size:0.8em;\r\n  }\r\n  td,th{\r\n      padding:5px;\r\n  }\r\n  v{\r\n      color:blue;\r\n  }\r\n}\r\nv{\r\n      color:blue;\r\n  }\r\n</style>\r\n<table class=\"table\">\r\n<tr>\r\n\r\n    <td>\r\n        <b>Subject ID : </b><v><%=patient.subject_id%></v>\r\n    </td>\r\n\r\n\r\n    <td>\r\n        <b>HN : </b><v><%=patient.hn%></v>\r\n    </td>\r\n\r\n    <td>\r\n        <b>Patient Name : </b><v><%=patient.prefix_name%><%=patient.first_name%> <%=patient.last_name%></v>\r\n    </td>\r\n    <td>\r\n        <b>Gender : </b><v><%=patient.gender%></v>\r\n    </td>\r\n    <td>\r\n        <b>Age : </b><v><%=((record.date - patient.birth_date.to_datetime)/(3600*24*365)).to_i if patient and patient.birth_date%> ปี</v>\r\n    </td>\r\n    \r\n    \r\n</tr>    \r\n</table>\r\n\r\n\r\n\r\n<p>\r\n\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   m_visit = {}\r\n   models[:visit_item].where(:visit_id=>record.id).each do |i|\r\n       m_visit[i.item_id] = i \r\n   end\r\n   \r\n   \r\n   periods = models[:pl_period].where(:sheet_id=>sheet.id).order(:sort_order).all\r\n   \r\n   now = 0 \r\n   periods.each_with_index do |i,index|\r\n       if period==i\r\n          now = index \r\n       end\r\n   end\r\n   now += 1\r\n   \r\n   now = periods.size-1 if now == periods.size\r\n   \r\n   next_visit = periods[now].id\r\n   \r\n   \r\n   \r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n<script>\r\n    $(\'.admin\').hide()\r\n</script>\r\n\r\n<br/>\r\n<hr/>\r\n<%= form_for :visit, :url=>\"process?id=\\\\#{params[:id]}\" do |f| \r\n    \r\n%>\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n    <h3>Protocol : <v><%= sheet.name%></v> Version : <v> <%=sheet.version%></v> Visit : <v><%=period.visit%></v> at <v><%=record.date.strftime(\"%d/%m/%Y\")%></v></h3><br/>\r\n</div>\r\n<%=hidden_field_tag :return, params[:return] %>\r\n\r\n<table class=\"table span12\"  >\r\n    <thead>\r\n        <th>No.</th> <th>Detail</th> <th>Code</th> <th>Group</th> <th>Check List</th> <th style=\"width:200px\">Note</th> \r\n    </thead>\r\n    <tbody>\r\n        <%  \r\n            items = []\r\n             \r\n            period_items.each_with_index do |pi,index| \r\n                \r\n            items <<  pimap[pi.id] if pimap[pi.id]\r\n                \r\n            end\r\n        \r\n            items.each_with_index do |i,index| \r\n            \r\n           \r\n            item = nil\r\n            \r\n            p = m_products[i.product_id]\r\n            \r\n            if p.group_code==\'LAB\'\r\n            \r\n            item = m_visit[i.id]\r\n            \r\n            note = \"\"\r\n            note = item.note  if item\r\n            check = true\r\n            check = false unless item\r\n            check = true if record.status ==nil or record.status ==\"\"\r\n        %>\r\n        <tr>\r\n         <th><%= index+1%>.</th>\r\n         <td><%= p.code%></td>\r\n         <td><%= p.name%></td>\r\n         <td><%= p.group_code%></td>\r\n         <td><%= check_box_tag \"check[\\\\#{i.id}]\", true, false %></td>\r\n         <td><%= text_field_tag \"note[\\\\#{i.id}]\", note%></td>\r\n\r\n\r\n         </tr>\r\n           <% end %> <% end %>\r\n    </tbody>\r\n</table>\r\n<br/>\r\n</div>\r\n<br/>\r\n\r\n<% end %>\r\n\r\n\r\n<script>\r\n    window.print()\r\n</script>\r\n</body>\r\n</html>',NULL,NULL,NULL,'2018-07-17 18:37:55','2018-07-17 18:37:55','print_lab',''),(3560,'document_name',1399,1,'\'intra_scope_event\'',NULL,NULL,NULL,'2018-07-25 03:58:03','2018-07-25 03:58:03',NULL,NULL),(3565,'document_name',1401,1,'\'colonoscopy\'',NULL,NULL,NULL,'2018-07-25 14:29:10','2018-07-25 14:29:10',NULL,NULL),(3566,'document_name',1402,1,'\'colonoscopy_scope\'',NULL,NULL,NULL,'2018-07-25 14:38:10','2018-07-25 14:38:10',NULL,NULL),(3568,'form',1403,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n <%=render :inline=>this.finding_config%>\r\n<script>\r\n\r\n  \r\n    var content_select = {};\r\n    \r\n       $(\'.pop_over\').each(function(){\r\n            $(this).attr(\"href\",\"#info-img\")\r\n            $(this).attr(\"data-toggle\",\"modal\")\r\n            $(this).attr(\"data-backdrop\",\"static\")\r\n            $(this).click(function(){\r\n                \r\n                $(\'#info-img-src\').attr(\"src\", $(this).attr(\'data-content\') )\r\n                \r\n            })\r\n             \r\n        })\r\n        \r\n    \r\n    function inject(path){\r\n    \r\n        // colonoscopy-terminal_ileum_scope-5b58a818790f9bd471000012-\r\n        // colonoscopy-cecum_scope-5b58a854790f9b0d45000004-\r\n        // data-colonoscopy-cecum_scope-5b58a854790f9b0d45000004-abnormal_type\r\n        //data-colonoscopy-descending_colon_scope-5b58a93e790f9b0d45000007-abnormal_type\r\n//   data-colonoscopy-terminal_ileum_scope-5b75a878790f9b76b10000c0-\r\n//         colonoscopy-terminal_ileum_scope-5b75aaa6790f9b76b10000da-\r\n        t = path.split(\"-\")\r\n        id= t[2];\r\n        \r\n        $(\'#\'+id).find(\".finding\").hide();\r\n        \r\n        $(\'.pop_over\').each(function(){\r\n            $(this).attr(\"href\",\"#info-img\")\r\n            $(this).attr(\"data-toggle\",\"modal\")\r\n            $(this).attr(\"data-backdrop\",\"static\")\r\n            $(this).click(function(){\r\n                \r\n                $(\'#info-img-src\').attr(\"src\", $(this).attr(\'data-content\') )\r\n                \r\n            })\r\n             \r\n        })\r\n        \r\n        $(\'#data-\'+path+\"abnormal_type\").change(function(){\r\n            $(\'#\'+id).find(\".finding\").hide();\r\n              \r\n            v = $(this).val()\r\n            cf = null;\r\n            cf = config[v];\r\n            if(cf!=null && typeof(cf)!=\'undefined\'){\r\n            for(var ix in cf[\'display_class\']){\r\n                i = cf[\'display_class\'][ix];\r\n                 $(\'#\'+id).find(\'.\'+i).show();\r\n            }\r\n            \r\n            for(var ix in cf[\'display_id\']){\r\n                i = cf[\'display_id\'][ix];\r\n                 $(\'#\'+path+i).show();\r\n            }\r\n            \r\n            Object.keys(cf[\'filter\']).forEach(function (key) { \r\n              var value = cf[\'filter\'][key]\r\n             \r\n            //   data-colonoscopy-terminal_ileum_scope-5b58b428790f9b268500000a-morphology_type\r\n                if( content_select[key]==null)\r\n                content_select[key] = $(\'#data-\'+path+key).html();\r\n                \r\n                $(\'#data-\'+path+key).html(content_select[key]);\r\n                \r\n                $(\'#data-\'+path+key).find(\'option\').each(function(){\r\n                    //  alert(key)\r\n                console.log(\" v \"+value.indexOf($(this).attr(\'value\')))\r\n                \r\n                if(value.indexOf($(this).attr(\'value\'))<0){    \r\n                    $(this).remove();\r\n                }\r\n                console.log(content_select[key])\r\n                  \r\n                  \r\n                   \r\n                })\r\n              \r\n              \r\n              \r\n                // iteration code\r\n            })\r\n            \r\n            \r\n            \r\n            }else{\r\n                $(\'#\'+id).find(\".finding\").hide();\r\n            }\r\n          \r\n        })\r\n        \r\n    }\r\n    \r\n</script>\r\n\r\n\r\n\r\n\r\n<div class=\"modal hide\" id=\"info-img\" aria-hidden=\"false\" style=\"display: none;\">\r\n<div class=\"modal-header\">\r\n<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n<h3>Modal header</h3>\r\n</div>\r\n<div class=\"modal-body\" id=\"modal-body\">\r\n<img src=\"\" id=\"info-img-src\"/>\r\n</div>\r\n<div class=\"modal-footer\">\r\n<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n</div>\r\n</div>\r\n<%= render :partial=>\'/esm_documents/tree_helper.html\' %>\r\n\r\n\r\n',NULL,NULL,NULL,'2018-07-25 14:50:20','2018-07-25 14:50:20','form',''),(3569,'document_name',1404,1,'\'instrument\'',NULL,NULL,NULL,'2018-07-25 15:06:29','2018-07-25 15:06:29',NULL,NULL),(3570,'patient_record',1405,2,'<% Time.zone =  get_setting \'time_zone\' %>\r\n<style>\r\nbody { min-width:0px; }\r\n.gebo-fixed { background-color:#f5f5f5; }\r\n#sidebar_bt {display:none }\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Patient Records\r\n        <div class=\"pull-right\">\r\n        <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n        </div> \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<%\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    ehr_models = ehr.get_model\r\n    patient_model = ehr_models[:patient]\r\n    patient_module_model = ehr_models[:patient_module]\r\n    \r\n    emr_models = get_model\r\n    ap = emr_models[:appointment].find(params[:id])\r\n    pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n    locker_model = emr_models[:locker]\r\n    if params[:reset_lock]\r\n        l = locker_model.find(params[:reset_lock])\r\n        l.destroy if l\r\n    end\r\n    #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n    #i.destroy if i\r\n    #end\r\n     \r\n    \r\n    \r\n    if pm\r\n    \r\n    if  params[:schema_patient_module]\r\n       pm.update_attributes params[:schema_patient_module]\r\n    end\r\n    \r\n    if params[:provider_id]\r\n      ap.update_attributes :provider=>params[:provider_id]\r\n       ap = emr_models[:appointment].find(params[:id])\r\n     end\r\n    \r\n    # find provider\r\n    provider = emr_models[:provider].find(ap.provider.to_s)\r\n    \r\n    # find patient\r\n    patient = patient_model.find(pm.patient_id)\r\n    \r\n    params[:patient]=patient\r\n    params[:patient_module]=pm\r\n    \r\n   # s = Service.get(\'ehr.emr.EmrHelper\')\r\n#    obj = s.load context\r\n    \r\n    providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n    \r\n%>\r\n\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'finding_document\' and i.name!=\'billing\'}.compact %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid; width:100%; padding:0px;max-width:688px\">\r\n<%# render :inline=>obj.show_patient %>\r\n<div id=\"patient\">\r\n...\r\n</div>\r\n<script>\r\n<%\r\n        url = \'../../www/Patient/search_result?\'\r\n        url += \'&id=\'+patient.id.to_s\r\n  %>      \r\n        $.ajax({\r\n    	  url: \'<%=url.html_safe%>\',\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n		  }\r\n		});\r\n</script>\r\n<br/>\r\n<%\r\n\r\n\r\nprevious = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\nhistory = []\r\nx = previous[0..7]\r\nlast = []\r\nlast = x.compact if x\r\nhistory = []\r\ny = previous[8..-1]\r\nhistory = y.compact if y and  previous.size>5\r\n                                     \r\ncurrent = time_ago_in_words(ap.date)\r\ncurrent_date = ap.date.strftime(\"%d-%m-%y\")\r\ncurrent = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n\r\n%>\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<div class=\"tabbable\">\r\n    							<ul class=\"nav nav-tabs\">\r\n									<li class=\"active\"><a href=\"#a<%=pm.id%>\" data-toggle=\"tab\"><%=current%><br/><%=current_date%></a></li>\r\n                                    <%\r\n                                    \r\n                                    \r\n                                     for i in last \r\n                                    %>\r\n                                	<li><a href=\"#a<%=i.id%>\" data-toggle=\"tab\"><%=time_ago_in_words(i.date)%><br/><%=i.date.strftime(\"%d-%m-%y\") if i.date%></a></li>\r\n									<% end %>\r\n                                    <% if history.size>5 %>\r\n                                    <li class=\"dropdown\">\r\n										<a href=\"#\" data-toggle=\"dropdown\" class=\"dropdown-toggle\">History<b class=\"caret\"></b></a>\r\n										<ul class=\"dropdown-menu\">\r\n                                            <% for j in history %>\r\n											<li><a href=\"#a<%=j.id%>\" data-toggle=\"tab\"><%=j.date.strftime(\"%d-%m-%y\") if j.date%> : <%=time_ago_in_words(j.date)%></a></li>\r\n                                            <% end %>\r\n											<li class=\"divider\"></li>\r\n										</ul>\r\n									</li>\r\n                                    <% end %>\r\n								\r\n                                </ul>\r\n\r\n\r\n\r\n<div class=\"tab-content\">\r\n<div class=\"tab-pane active\" id=\"a<%=pm.id%>\">\r\n\r\n\r\n<h4><%= @current_project.title %> Records</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n\r\n<% \r\n\r\n    # locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n\r\n\r\n    locker = locker_model.where(:module_id=>pm.id.to_s,:module_name=>s.name,:created_at=>{\'$lt\'=>1.hours.ago}).first\r\n    if locker\r\n    text = \'\'\r\n    case locker.status\r\n    when \'create\'\r\n        text=\'Creating..\'\r\n    when \'edit\'\r\n        text=\'Editing..\'\r\n    end\r\n   user,role,solution_user = @current_solution.get_user_by_id locker.session\r\n   \r\n   \r\n   %>\r\n\r\n\r\n<%\r\n   user_name = user.login.split(\"@\")[0]\r\n   user_name =  solution_user.name  if solution_user\r\n\r\n   text += \" by \" + user_name if user_name\r\n#   text += locker.session\r\n%>\r\n\r\n<%=image_tag \'/gebo/img/ajax_loader.gif\',:width=>30,:height=>30,:style=>\'vertical-align:middle\'%>&nbsp;<span><%=text.html_safe  %><span>\r\n    <% end %>\r\n\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n</div>\r\n\r\n<% for i in previous \r\n pm = i\r\n%>\r\n<div class=\"tab-pane\" id=\"a<%=i.id%>\">\r\n<h4><%= @current_project.title %> Recrods</h4>\r\n<hr/>\r\n<table class=\"table table-striped table-bordered\">\r\n<thead>\r\n<tr><th></th><th>Forms</th><th>Records</th><th></th></tr>\r\n</thead>\r\n\r\n<%\r\ngroups = this.config\r\nif true\r\nfor g in groups \r\n   services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n%>\r\n<tr><td colspan=\"4\"><%=g[:name]%></td></tr>\r\n<% services.each_with_index do |s,index|\r\n    module_name = \"\\\\#{@current_project.name}#\\\\#{s.name}\"\r\n    records = patient_module_model.all :module_name=>module_name, :parent_id=>pm.id,:patient_id=>pm.patient_id\r\n%>\r\n<tr><td><%= index+1 %>. </td><td> <%= s.title %></td>\r\n\r\n<td align=\"center\"><% for i in records %>\r\n<%= link_to \"\\\\#{i.date.strftime(\"%d-%m-%Y\") if i.date} \\\\#{i.time.strftime(\"%H:%M\") if i.time } - \\\\#{i.ref_number}\", \"../\\\\#{s.name.camelize}/show?id=\\\\#{i.id}\" %>&nbsp;\r\n<%= link_to \"[ Edit ]\", \"../\\\\#{s.name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}\" %>\r\n<% end %>\r\n</td>\r\n<td>\r\n<%  if records.size==0 %>\r\n<%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}\" ,:class=>bt_class%>\r\n<% else %>\r\n<%=link_to \'Print\',\"../\\\\#{s.name.camelize}/print?id=\\\\#{i.id}\",:target=>\'_blank\' ,:class=>bt_class%>\r\n<% end %>\r\n\r\n<br/>\r\n\r\n</td>\r\n<% end %>\r\n</tr>\r\n\r\n<% end %>\r\n<% end %>\r\n</table>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n<% else %>\r\nData missing\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n$(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n</script>\r\n\r\n\r\n ',NULL,NULL,NULL,'2018-07-25 15:38:03','2018-07-25 15:38:03','patient_record',''),(3571,'config',1405,1,'services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'finding_document\' and i.name!=\'live_document\'  and i.name!=\'billing\'}.compact\r\n[{:name=>\'Form\',:open=>true,:actions=>services.collect{|i| {:name=>i.name.camelize,:service=>i.name,:link=>\"../\\\\#{i.name.camelize}/index\"}} }]\r\n\r\n',NULL,NULL,NULL,'2018-07-25 15:41:12','2018-07-25 15:41:12','config',''),(3573,'finding_config',1401,4,'<script>\r\n<%\r\nconfig = {}\r\n\r\n\r\n########### Polyp\r\n\r\n\r\nfilter = {}\r\n\r\nlist = <<EOX\r\nPedunculated\r\nSessile\r\nSlightly elevated \r\nFlat\r\nSlightly depressed\r\nExcavated \r\nEOX\r\nfilter[\'morphology_type\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\n\r\nlist = <<EOX\r\nCold biopsy\r\nHot biopsy\r\nCold snare polypectomy \r\nHot snare polypectomy \r\nEMR\r\nESD\r\nSampling\r\nOther\r\nEOX\r\nfilter[\'intervention\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\n\r\nconfig[\'Polyp\'] = {\'display_class\'=>[\'polyp\'],\'display_id\'=>[\'number_of_lesion\',\'morphology_type\',\'size\'], \'filter\'=>filter }\r\n\r\n\r\n\r\n########### Mass\r\n\r\n\r\nfilter = {}\r\n\r\nlist = <<EOX\r\nCircumferential \r\nHemicircumferential \r\nRound \r\nUlcerative \r\nUlceroproliferative \r\nSubmucosal \r\nSubmucosal with central ulceration \r\nEOX\r\nfilter[\'morphology_type\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\n\r\nlist = <<EOX\r\nSampling \r\nEMR\r\nESD\r\nOther \r\nEOX\r\nfilter[\'intervention\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\n\r\nconfig[\'Mass\'] = {\'display_class\'=>[],\'display_id\'=>[\'morphology_type\',\'size\'], \'filter\'=>filter }\r\n\r\n\r\n\r\n\r\n\r\n########### Ulcer\r\n\r\n\r\nfilter = {}\r\n\r\nlist = <<EOX\r\nRound \r\nOval \r\nLinear\r\nGeographic \r\nSerpiginous \r\nRodent-bite-like\r\nAphthous\r\nEOX\r\nfilter[\'morphology_type\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\n\r\nlist = <<EOX\r\nCold biopsy\r\nHot biopsy\r\nCold snare polypectomy \r\nHot snare polypectomy \r\nEMR\r\nESD\r\nSampling\r\nOther\r\nEOX\r\nfilter[\'intervention\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\n\r\nconfig[\'Ulcer\'] = {\'display_class\'=>[\'ulcer\',\'location\'],\'display_id\'=>[\'number_of_lesion\',\'morphology_type\',\'size\'], \'filter\'=>filter }\r\n\r\n\r\n\r\n########### Mucosa\r\n\r\n\r\nfilter = {}\r\n\r\nlist = <<EOX\r\nErythematous \r\nEdematous\r\nDecreased vascular pattern \r\nGranularity \r\nNodularity\r\nFriable \r\nContact bleeding \r\nSpontaneous bleeding \r\nPseudopolyps\r\nEOX\r\nfilter[\'morphology_type\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\nconfig[\'Mucosa\'] = {\'display_class\'=>[\'location\'],\'display_id\'=>[\'morphology_type\'], \'filter\'=>filter }\r\n\r\n\r\n\r\n########### Stricture\r\n\r\nlist = <<EOX\r\nSampling 	\r\nStent placement 	\r\nBalloon stricturoplasty 	\r\nSten removal 	\r\nOther 	\r\nEOX\r\nfilter[\'intervention\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\nconfig[\'Stricture\'] = {\'display_class\'=>[\'stricture\'],\'display_id\'=>[\'size\'], \'filter\'=>filter }\r\n\r\n\r\n\r\n########### Diverticulum\r\n\r\nlist = <<EOX\r\nClipping \r\nInjection therapy \r\nOther 	\r\nEOX\r\nfilter[\'intervention\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\nconfig[\'Diverticulum\'] = {\'display_class\'=>[\'location\'],\'display_id\'=>[\'number_of_lesion\', \'bleeding_stigmata\',\'size\'], \'filter\'=>filter }\r\n\r\n\r\n\r\n\r\n\r\n########### Angiodysplasia\r\n\r\nlist = <<EOX\r\nClipping \r\nBipolar coaptation \r\nAPC \r\nOther 	\r\nEOX\r\nfilter[\'intervention\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\nconfig[\'Angiodysplasia\'] = {\'display_class\'=>[\'location\'],\'display_id\'=>[\'number_of_lesion\', \'bleeding_stigmata\',\'size\'], \'filter\'=>filter }\r\n\r\n\r\n########### Dieulafoy\'s lesion \r\n\r\nlist = <<EOX\r\nClipping \r\nBipolar coaptation \r\nAPC \r\nOther 	\r\nEOX\r\nfilter[\'intervention\']=list.split(\"\\n\").collect{|i| i.strip}\r\n\r\nconfig[\"Dieulafoy\'s lesion\"] = {\'display_class\'=>[],\'display_id\'=>[ \'bleeding_stigmata\'], \'filter\'=>filter }\r\n\r\n\r\n\r\n\r\n\r\n%>\r\nconfig = <%=config.to_json.html_safe%>\r\n\r\nfunction updateBBPS(){\r\n\r\n    sum = 0;\r\n  \r\n    if($(\'#data-bowel_preparation_lc\').val())sum += parseInt($(\'#data-bowel_preparation_lc\').val());\r\n    \r\n    if($(\'#data-bowel_preparation_tc\').val())sum += parseInt($(\'#data-bowel_preparation_tc\').val());\r\n    \r\n    if($(\'#data-bowel_preparation_rc\').val()) sum += parseInt($(\'#data-bowel_preparation_rc\').val());\r\n    \r\n    \r\n    $(\'#data-bowel_preparation_bbps\').val(sum);\r\n}\r\n\r\n\r\n$(\'#data-bowel_preparation_lc\').change(updateBBPS);\r\n$(\'#data-bowel_preparation_tc\').change(updateBBPS);\r\n$(\'#data-bowel_preparation_rc\').change(updateBBPS);\r\n$(\'#data-diagnosis_group\').change(function(){\r\n  \r\n    if($(this).val()!=\"Normal\"){\r\n    \r\n          v = $(this).val().split(\"|\")\r\n          out = [];\r\n          for(var i=0;i<v.length;i++){\r\n            k = v[i];\r\n            if(k!=\"Normal\"){\r\n                out.push(k);\r\n            }\r\n          }\r\n          \r\n          $(this).val(out.join(\"|\"))\r\n          $(\'#update_diagnosis_group_item_0\').prop(\'checked\', false); \r\n    }\r\n});\r\n\r\n\r\n<%\r\n    if params[:id]\r\n%>\r\n $(document).ready(function(){\r\n            \r\n<%        \r\n        @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        @ehr_model = @ehr_project.get_model()\r\n        @module_model = @ehr_model[:patient_module]\r\n\r\n\r\n  \r\n      model = get_model(\'colonoscopy\')\r\n      \r\n      @patient_module = @module_model.find(params[:id])\r\n      \r\n      \r\n      record = model.find(@patient_module.module_id)\r\n      scopes = %w{rectum_scope sigmoid_scope descending_colon_scope transvers_colon_scope ascending_colon_scope cecum_scope terminal_ileum_scope}.reverse\r\n\r\n\r\n      for s in scopes\r\n        for i in record[s]\r\n            %>\r\n            inject(\"colonoscopy-<%=s%>-<%=i%>-\");\r\n            $(\'#data-colonoscopy-<%=s%>-<%=i%>-abnormal_type\').change();\r\n            \r\n            <%\r\n        end\r\n      end\r\n      \r\n%>\r\n \r\n });\r\n<% end %>\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2018-07-25 16:59:26','2018-07-25 16:59:26','finding_config',''),(3574,'print',1401,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%= render :inline=>this.print_partial, :locals=>{:this=>this} %>\r\n<script>\r\nwindow.print()\r\n</script>\r\n<%\r\n    if @current_project.get_setting \'report_server\'\r\n    report_server_path = \"\\#{@current_project.get_setting \'report_server\'}?domain=\\#{DOMAIN}&solution=\\#{@current_solution.name}&application=\\#{@current_project.name}&report=\\#{this.document_name}&id=\\#{params[:id]}\"\r\n    `curl \'\\#{report_server_path.html_safe}\'`\r\n    end \r\n%>\r\n<%#report_server_path%>',NULL,NULL,NULL,'2018-07-31 02:14:14','2018-07-31 02:14:14','print',''),(3575,'print_image',1401,3,'\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div style=\"page-break-after: always\">\r\n<%= render :inline=>this.print_partial, :locals=>{:this=>this} %>\r\n</div>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:colonoscopy].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed :&nbsp;<%= Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colonoscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n	<p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n	<p>Date :&nbsp;<v><%=record.date_note%></v>&nbsp;&nbsp; Colonoscope :&nbsp;<v><%=record[\'colonoscope\']%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n	<p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n\r\n\r\n\r\n<table width=\"100%\" >\r\n<tr>\r\n  <td valign=\"top\" border=\"1\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<p><label>Note : </label><v><% if a= record[\'scope_note\'] and a !=\"\" %><%=render_value \'scope_note\'%> </v><% end%></p></td>\r\n  <td valign=\"top\"><p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \') if record[\'diagnosis_group\']%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p></td>\r\n</tr>\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>1.Endoscopist : <v><%=endoscopist_1%></v></p>\r\n	<p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>2.Endoscopist : <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<b>Picture :</b><br/>\r\n    <%\r\n        list = record.image\r\n        atts = []\r\n        if list[8...36]\r\n        atts = list[8...36].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        end\r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>?thumb=2\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n<div id=\"page\" style=\"height:40px\">\r\n<h4>Sign :</h4>\r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n<script>\r\nwindow.print()\r\n</script>\r\n\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,'2018-07-31 02:14:34','2018-07-31 02:14:34','print_image',''),(3576,'print_partial',1401,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:colonoscopy].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n    endoscopist_1 = render_value(\'endoscopist_1\')\r\n    endoscopist_2 = render_value(\'endoscopist_2\')\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = pm.created_at.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n<%=include_header%>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:90px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:10px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<div id=\"logoleft\"><img src=\"/esm/endo_siriraj/endo/logoendo.jpg\" width=\"200\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize if @current_user %></p>\r\n<p>Printed :&nbsp;<%=thdate Time.now %></p>\r\n</div>\r\n</div>\r\n<div id=\"page\">\r\n<h4>Colonoscopy</h4>\r\n<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" >\r\n<tr>\r\n<td width=\"50%\"> \r\n\r\n    <p>Hospital No :&nbsp;<v><%=patient.hn%></v> Name : <v><%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %></v></p>\r\n    <p>Date :&nbsp;<v><%=thdate record.date_note%></v>&nbsp;&nbsp; Colonoscope :&nbsp;<v><%=endoscopist_1%></v>  </p>\r\n\r\n\r\n</td>\r\n<td width=\"50%\" valign=\"top\"> \r\n\r\n    <p>Age :&nbsp;<v><%= year%> Year <%=month%> Month <%= day%> Day </v></p>\r\n\r\n	</td>\r\n</tr>\r\n</table>\r\n	<hr />\r\n  \r\n   \r\n	  <table width=\"100%\">\r\n	    <tr>\r\n	      <td > <h4 style=\"padding:0px; margin:0px; margin-left:10px\">Status : <%=record[\'status\']%> </h4></td>\r\n	      <td><h4 style=\"padding:0px; margin:0px;margin-left:10px\">Sedation</h4></td>\r\n        </tr>\r\n	    <tr>\r\n      <td width=\"60%\"><p><span style=\"float:left; \"> </span>\r\n        <span style=\"float:left;display:block-inline;\">\r\n				<table width=\"100%\" style=\"margin-left:10px\" >\r\n				<tr>\r\n				  \r\n					<td width=\"300\"><label>Previous Operation :</label> <v><%=render_value(\'previous_opreation\')%><i></i></v></td>\r\n					<td><label>Indication :</label> <v><%=render_value \'indication\'%> <i></i></v></td>\r\n				</tr>\r\n				<tr>\r\n				 \r\n					<td><label>Bowel Preparation :</label> <v><%=render_value \'bowel_preparation\' %> <%=record[\'bowel_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'bowel_other\'%></v></td>\r\n				</tr>\r\n				<tr>\r\n				\r\n					<td><label>Quality of Preparation :</label> <v><%=record[\'quality_of_preparate\']%></v></td>\r\n					<td><label>Record :</label> <v><%=record[\'record\'].split(\'|\').join(\' , \') if record[\'record\']%></v></td>\r\n				\r\n				<tr>\r\n					\r\n					<td width=\"220\"><label>Additional Bowel Preparation :</label> <v><%=render_value \'additional_bowel_preparation\' %> <%=record[\'add_bowel_prep_cc\']%> cc.</v></td>\r\n					<td><label>Other :</label> <v><%=render_value \'add_bowel_prep_other\'%></v></td>\r\n				</tr>		\r\n				\r\n			</table>	\r\n		</span>\r\n		\r\n \r\n		</p></td>\r\n\r\n<td width=\"40%\"  valign=\"top\">\r\n\r\n<p>\r\n<table width=\"98%\" style=\"margin-left:10px\">\r\n<% any_sedation = false %>\r\n\r\n<tr><td >\r\n<% if record[\'dormicum\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Dormicum :</label> <v><%=record[\'dormicum_mg\']%> mg <%=record[\'dormicum_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'pethidine\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Pethidine :</label> <v><%=record[\'pethidine_mg\']%> mg <%=record[\'pethidine_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'drithpivan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Drithpivan :</label> <v><%=record[\'drithpivan_mg\']%> mg <%=record[\'drithpivan_num\']%> </v></div>\r\n<% end%>\r\n<% if record[\'diprivan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Diprivan :</label> <v><%=record[\'diprivan_mg\']%> mg <%=record[\'diprivan_num\']%> </v>  </div>\r\n<% end%>\r\n<% if record[\'valium\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Valium :</label> <v><%=record[\'valium_mg\']%> mg <%=record[\'valium_num\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'buscopan\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Buscopan :</label> <v><%=record[\'buscopan_mg\']%> mg <%=record[\'buscopan_route\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'plasil\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Plasil :</label> <v><%=record[\'plasil_mg\']%> mg <%=record[\'plasil_route\']%> </v>   </div>\r\n<% end%>\r\n<% if record[\'fentanyl\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Fentanyl :</label> <v><%=record[\'fentanyl_mg\']%> mcg <%=record[\'fentanyl_routh\']%> </v>   </div>\r\n<% end%>\r\n\r\n<% if record[\'general_anesthesia\'] and record[\'general_anesthesia\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><v>General anesthesia</v>   </div>\r\n<% end%>\r\n\r\n<% if record[\'other\']==\'true\'\r\n any_sedation = true\r\n%>\r\n<div class=\"sidationcss\"><label>Other Note :</label> <v><%=record[\'other_note\']%> </v>   </div>\r\n\r\n<% end%>\r\n</td>\r\n  </tr>\r\n\r\n\r\n<tr>\r\n<td><% unless  any_sedation %>\r\n<v>No sedation</v>\r\n<% end %>\r\n</td>\r\n</tr>\r\n</table>\r\n</p></td>\r\n </tr></table>\r\n		\r\n<hr />\r\n\r\n<h4>Scope finding</h4>\r\n<table width=\"872\" style=\"padding-left:15px\">\r\n<tr>\r\n    <td width=\"341\">\r\n    <label>Scope pass through : </label><v><%=render_value \'scope\'%></v>\r\n    </td>\r\n    <td width=\"519\">\r\n    <label>Procedure : </label><v><%=render_value \'procedure\'%></v>\r\n    </td>\r\n   \r\n</tr>\r\n\r\n</table>\r\n\r\n\r\n\r\n<% if  a = record[\'procedure_other\']  and a !=\"\" %><label>Note : </label><v><%=render_value \'procedure_other\'%> </v><% end%>\r\n<p style=\"padding-left:10px\">Start : <v><%=record[\'start_at\'].strftime(\'%H:%M\') if record.start_at %></v> To : <v><%=record[\'stop_at\'].strftime(\'%H:%M\') if record.stop_at%></v> Total time : <v><%= (record.stop_at - record.start_at)/60.0%> mins</v></p>\r\n<p >\r\n<%\r\n    scopes = %w{rectum_scope sigmoid_scope descending_colon_scope transvers_colon_scope ascending_colon_scope cecum_scope terminal_ileum_scope}.reverse\r\n    \r\n    scopes.each_with_index do |j,index|\r\n    if scopes.size-index-1<record.scope.to_i \r\n    tag = j.split(\"_\")[0..-2].join(\'_\')\r\n    text = \"Normal\"\r\n    tag_cls = \'\'\r\n    t =  record[tag].strip\r\n    if  t== \'1\' or t==\'Abnormal\'\r\n    	text =  \"Abnormal\"\r\n    	 tag_cls = \'color:red\'\r\n    end\r\n    label = tag\r\n    label = \'transverse_colon\' if tag == \'transvers_colon\'\r\n    \r\n%>\r\n<p><%= label.humanize %> : <span id=\"<%=j%>\"><v style=\"<%=tag_cls%>\"><%= text%>&nbsp;&nbsp;<%= record[\"\\\\#{tag}_note\"] %></v></span></p>\r\n<%\r\nif record[j]  and record[j]!=\'\' and record[j].size>0\r\n    \r\n    list,doc = get_has_many_value(j) \r\n%>\r\n<table width=\"100%\" class=\"smm\">\r\n<tr>\r\n<td>No.</td><td>Type:</td><td>Dx:</td><td>Morphology:</td><td>Size:</td><td>Treatment:</td><td>By:</td><td>Clip:</td><td>Patho No:</td>\r\n<td>Chromo By:</td><td>Kudo:</td><td>Sano:</td><td>NICE:</td><td>JNET:</td><td>Note:</td>\r\n</tr>\r\n<%\r\n#for i in list \r\n  list.each_with_index do |i,index| \r\n      \r\n     \r\n     note =  []  \r\n     note << i[\'abnormal_note\'] if i[\'abnormal_note\'] and i[\'abnormal_note\']!=\'\'\r\n     note << \"Tattoo was done\" if i[\'tattoo\'] and i[\'tattoo\']==\'Done\'\r\n     note << i[\'complication\'] if i[\'complication\'] and i[\'complication\']!=\'none\'\r\n     \r\n    \r\n     \r\n     \r\n      note = note.join \", \" \r\n%>\r\n<%# list.inspect %>\r\n<tr>\r\n<td><%= index+1 %>. </td><td><v><%=i[\'abnormal_type\']%>\r\n    <%\r\n     if i[\'location\']\r\n        \r\n        %>\r\n        <script>\r\n          $(document).ready(function(){\r\n            <% for l in i[\'location\'].split(\'|\') %>\r\n                $(\'#<%=l%>_scope\').html(\"<v><%=i[\'abnormal_type\']%></v>\")\r\n            <% end %>\r\n          })\r\n        </script>\r\n        <%\r\n         \r\n     end\r\n    %>\r\n    \r\n</v></td><td><v><%=i[\'endoscopy_dx\']%></v></td><td><v><%=i[\'morphology_type\']%></v></td><td>\r\n<% if i[\'size\']==0%>\r\n<v> -</v>\r\n<% else%>\r\n<v><%=i[\'size\']%> cm.</v>\r\n<% end%>\r\n</td>\r\n<td><v><%=i[\'treatment\']%></v></td>  <td><v><%=i[\'treatment_by\']%></v> </td> <td><v><%=i[\'clip\']%></v></td>               <td><v><%=i[\'patho_number\']%></v></td>\r\n<td><v><%=i[\'chromo\']%></v></td>     <td><v><%=i[\'kudo_type\']%></v></td>     <td><v><%=i[\'sano_type\']%></v></td>          <td><v><%=i[\'nice_classification\']%></v></td>\r\n<td><v><%=i[\'jnet_class\']%></v></td><td><v><%=note%></v></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n\r\n<%\r\n    break if record.scope==tag.humanize\r\n%>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n<hr />\r\n\r\n\r\n<h4>Note</h4>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_note\']%></v></p>\r\n<% if a= record[\'scope_note\'] and a !=\"\" %><label>Note : </label><v><%=render_value \'scope_note\'%> </v><% end%>\r\n<p style=\"font-size:16px;font-weight:bold\">Diagnosis groups : <v style=\"color:red; font-weight:bold\"><%=record[\'diagnosis_group\'].split(\'|\').join(\' , \') if record[\'diagnosis_group\']%></v></p>\r\n<p>Remark : <v><%=record[\'remark\']%></v></p>\r\n<table width=\"100%\" >\r\n<tr>\r\n<td width=\"50%\" valign=\"top\" border=\"1\">\r\n	<p>.........................................<br />\r\n	Endoscopist 1: \r\n	  <v><%=endoscopist_1%></v></p>\r\n\r\n</td>\r\n<% if endoscopist_2.strip!=\'N/A\' %>\r\n<td width=\"50%\" valign=\"top\">\r\n	<p>.........................................<br />\r\n	  Endoscopist 2: \r\n	  <v><%=endoscopist_2%></v></p>\r\n    \r\n</td>\r\n<% end %>\r\n</tr>\r\n<tr>\r\n<td colspan=\"2\">\r\n    <p>Plan for Treatment : <v><%=record[\'plan_for_treatment\']%></v></p>\r\n    \r\n</td>\r\n</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n<div id=\"page\">\r\n<h4>Picture :</h4>\r\n\r\n    <%\r\n        list = record.image\r\n        \r\n        atts = models[:attachment].find(list[0...8].compact).compact\r\n        \r\n        map = {}\r\n        for i in atts\r\n            map[i.id.to_s] = i\r\n        end\r\n        atts = []\r\n        for i in list[0...8].compact\r\n            atts << map[i]\r\n        end\r\n        \r\n        \r\n        # atts = list[0...8].compact.collect{|i| models[:attachment].find(i)}.compact\r\n        \r\n    if atts\r\n        atts.each_with_index do |i,index| \r\n    %>\r\n	<div id=\"box\">\r\n		<img alt=\"1\" src=\"<%=i.path%>?thumb=2\" /><br/>\r\n		<v><%=i.title%></v>\r\n	</div>\r\n    <% if index%4==3 %>\r\n    <div class=\"clear\"></div>\r\n    <% end %>\r\n<% end %>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n\r\n',NULL,NULL,NULL,'2018-07-31 02:15:00','2018-07-31 02:15:00','print_partial','*'),(3577,'display',1401,3,'<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n<div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n\r\n<div id=\'prescope\' >Loading..PreScope information</div>\r\n<script>\r\n\r\n<%\r\n\r\n url = \"../PreScope/pre_scope_detail?id=\\\\#{params[:id]}\"\r\n url = \"../PreScope/pre_scope_detail?parent_id=\\\\#{params[:parent_id]}\" if params[:parent_id]\r\n \r\n%>\r\n\r\n$.ajax({\r\n  url: \"<%=url%>\",\r\n  context: document.body\r\n}).done(function(data) { \r\n  $(\'#prescope\').html(data);\r\n \r\n});\r\n</script>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>',NULL,NULL,NULL,'2018-07-31 02:16:42','2018-07-31 02:16:42','display',''),(3578,'context_menu',1396,4,'<%\r\nreturn_url = \'\'\r\nreturn_url = \"&return=\\\\#{params[:return]}\" if params[:return]\r\nname = this.document_name.humanize\r\nlist = []\r\nif true\r\nlist<<{:name=>\'Project\',:link=>\"../Report/project_summary\",:remote=>false}\r\nend\r\n\r\n%>\r\n<%= show_menu [{:name=>\'Reports\',:open=>true,:actions=>list}] \r\n%>\r\n\r\n\r\n',NULL,NULL,NULL,'2018-07-31 07:24:38','2018-07-31 07:24:38','context_menu',''),(3579,'project_summary',1396,2,'<%=render :inline=>this.report_helper%>\r\n<%\r\n       \r\n    column_fields = %w{phase project_type sponsor customer_id cro disease status siv_date} \r\n    \r\n    row_fields = %w{number_of_records no_of_patient duration no_of_active_patients total_grant}\r\n    \r\n    build_form row_fields, column_fields\r\n    \r\n%>\r\nProject : <%=@models[:project].count %>\r\n\r\n<%=yield :form %>',NULL,NULL,NULL,'2018-07-31 07:27:16','2018-07-31 07:27:16','project_summary',''),(3580,'report_helper',1396,4,'<%\r\n    @models = get_model\r\n    \r\n\r\ndef build_form row, col_a, col_b=nil\r\n    \r\n    column_fields = %w{phase project_type sponsor customer_id cro disease status siv_date} \r\n    \r\n    row_fields = %w{number_of_records no_of_patient duration no_of_active_patients total_grant}\r\n    \r\n    column_fields = col_a if col_a\r\n    row_fields = row if row\r\n    cols_a = column_fields \r\n    cols_b = column_fields\r\n    cols_b  = col_b if col_b\r\n    \r\n%>\r\n\r\n<%=content_for :form do %> \r\n<script src=\"https://d3js.org/d3.v4.min.js\"></script>\r\n\r\n\r\n<%= form_for :query, :url=>\"project_summary_partial?update=result\", :data=>{:remote=>true} do |f| %>\r\n\r\nColumn A : <%=f.select :col_a, options_for_select(cols_a) , include_blank: true%>\r\n\r\nColumn B : <%=f.select :col_b, options_for_select(cols_b) , include_blank: true %>\r\n\r\nRow : <%=f.select :row, options_for_select(row_fields) %>\r\n\r\n<%= f.submit \'Query\' %>\r\n\r\n<% end %>\r\n    \r\n<div id=\"result\">\r\n    \r\n</div>    \r\n\r\n<% end %>\r\n<% end %>\r\n\r\n\r\n<% def build_result model, select_col={\'protocol_no\':1} %>\r\n<%=content_for :result do %>\r\n<h3>Result : </h3>\r\n\r\n<% \r\n    m = @models[model]\r\n    criteria = {}\r\n    select_colums = select_col\r\n    \r\n    params[:query][:col_b]=nil if params[:query][:col_b] == params[:query][:col_a]\r\n    \r\n    col_a = params[:query][:col_a]\r\n    col_b = params[:query][:col_b]\r\n    \r\n    \r\n    select_colums[params[:query][:col_a]]=1\r\n    select_colums[params[:query][:col_b]]=1 if params[:query][:col_b] and params[:query][:col_b]!=\'\'\r\n    select_colums[params[:query][:row]]=1 if params[:query][:row]!=\'number_of_records\'\r\n    \r\n    records = m.collection.find(criteria, :fields=>select_colums).to_a\r\n    \r\n    map = {}\r\n    map_a = {}\r\n    map_b = {}\r\n    \r\n    values = []\r\n    \r\n    for i in records\r\n    \r\n    a = i[col_a].to_s\r\n    b = i[col_b].to_s\r\n    \r\n    map_a[a] = [] unless map_a[a]\r\n    map_a[a] << i \r\n    \r\n    map_b[b] = [] unless map_b[b]\r\n    map_b[b] << i \r\n    \r\n    k = \"\\\\#{a}-\\\\#{b}\"\r\n    map[k] = [] unless map[k]\r\n    map[k] << i\r\n    \r\n    end\r\n    \r\n    max = 0 \r\n    for a in map_a.keys.sort\r\n    \r\n    obj = {\'a\'=>a}\r\n    \r\n    for b in map_b.keys.sort\r\n    \r\n    k = \"\\\\#{a}-\\\\#{b}\"\r\n    if map[k]\r\n    \r\n\r\n    size = 0\r\n    if params[:query][:row]==\'number_of_records\'\r\n        obj[b] = map[k].size\r\n        size = map[k].size\r\n    else\r\n        obj[b] = 0 unless obj[b]\r\n        sum= 0 \r\n        for i in map[k]\r\n            sum += i[params[:query][:row]].to_i\r\n        end\r\n         obj[b]+= sum\r\n         size = sum\r\n        \r\n    end\r\n    max = size if size > max\r\n    else\r\n    obj[b] = 0 \r\n    end\r\n\r\n    end\r\n    \r\n    values << obj\r\n    \r\n    end\r\n    \r\n    \r\n\r\n%>\r\n\r\n \r\n<style>\r\n\r\n.bar {\r\n  fill: steelblue;\r\n}\r\n\r\n.bar:hover {\r\n  fill: brown;\r\n}\r\n\r\n.axis--x path {\r\n  /*display: none;*/\r\n}\r\n\r\n</style>\r\n<div class=\"row-fluid\">\r\n<svg width=\"1280\" height=\"400\"></svg></div>\r\n<script>\r\n$(document).ready(function(){\r\n   \r\n \r\nvar svg = d3.select(\"svg\"),\r\n    margin = {top: 20, right: 20, bottom: 100, left: 40},\r\n    width = +svg.attr(\"width\") - margin.left - margin.right,\r\n    height = +svg.attr(\"height\") - margin.top - margin.bottom;\r\n\r\nvar x = d3.scaleBand().rangeRound([0, width]).padding(0.4),\r\n    y = d3.scaleLinear().rangeRound([height, 0]);\r\n\r\nvar x1 = d3.scaleBand()\r\n    .padding(0.05);\r\nvar z = d3.scaleOrdinal()\r\n    .range([\"#98abc5\", \"#8a89a6\", \"#7b6888\", \"#6b486b\", \"#a05d56\", \"#d0743c\", \"#ff8c00\"]);    \r\n\r\n    \r\nvar g = svg.append(\"g\")\r\n    .attr(\"transform\", \"translate(\" + margin.left + \",\" + margin.top + \")\");\r\n\r\n  \r\n  data = <%=values.to_json.html_safe%>;\r\n//   data.push({a:\'A\',b:\'I\',r:12});\r\n//   data.push({a:\'B\',b:\'I\',r:42});\r\n//   data.push({a:\'C\',b:\'II\',r:31});\r\n//   data.push({a:\'D\',b:\'V\',r:51});\r\n//   data.push({a:\'A\',\'I\':12,\'II\':30});\r\n//   data.push({a:\'B\',\'I\':22,\'II\':13});\r\n   \r\n   \r\n   \r\n  \r\n//   keys = jQuery.unique(data.map(function(d) { return d.b; }));\r\n  \r\n  keys = <%=map_b.keys.sort.to_json.html_safe%>;\r\n  \r\n\r\n  x.domain(data.map(function(d) { return d.a; }));\r\n  x1.domain(keys).rangeRound([0, x.bandwidth()]);\r\n   max = <%= max %>\r\n\r\n  y.domain([0, max]);\r\n  g.append(\"g\")\r\n      .attr(\"class\", \"axis axis--x\")\r\n      .attr(\"transform\", \"translate(0,\" + height + \")\")\r\n      .call(d3.axisBottom(x)).selectAll(\"text\")\r\n    .attr(\"y\", 0)\r\n    .attr(\"x\", 9)\r\n    .attr(\"dy\", \".35em\")\r\n    .attr(\"transform\", \"rotate(90)\")\r\n    .style(\"text-anchor\", \"start\");\r\n\r\n  g.append(\"g\")\r\n      .attr(\"class\", \"axis axis--y\")\r\n      .call(d3.axisLeft(y).ticks(10, \"\"))\r\n    .append(\"text\")\r\n      .attr(\"transform\", \"rotate(-90)\")\r\n      .attr(\"y\", 6)\r\n      .attr(\"dy\", \"0.71em\")\r\n      .attr(\"text-anchor\", \"end\")\r\n      .text(\"Projects\");\r\n\r\n//   g.selectAll(\".bar\")\r\n//     .data(data)\r\n//     .enter().append(\"rect\")\r\n//       .attr(\"class\", \"bar\")\r\n//       .attr(\"x\", function(d) { return x(d.a); })\r\n//       .attr(\"y\", function(d) { return y(d.r); })\r\n//       .attr(\"width\", x.bandwidth())\r\n//       .attr(\"height\", function(d) { return height - y(d.r); });\r\n      console.log(keys)\r\n   g.append(\"g\")\r\n    .selectAll(\"g\")\r\n    .data(data)\r\n    .enter().append(\"g\")\r\n      .attr(\"transform\", function(d) { return \"translate(\" + x(d.a) + \",0)\"; })\r\n    .selectAll(\"rect\")\r\n    .data(function(d) { return keys.map(function(key) { \r\n        return {key: key, value: d[key]}; }); })\r\n    // .data(function(d) { return [{key:\'I\',value:d.r},{key:\'II\',value:d.r},{key:\'V\',value:d.r}] })\r\n    .enter().append(\"rect\")\r\n      .attr(\"x\", function(d) { return x1(d.key); })\r\n      .attr(\"y\", function(d) { return y(d.value); })\r\n      .attr(\"width\", x1.bandwidth())\r\n      .attr(\"height\", function(d) { return height - y(d.value); })\r\n      .attr(\"fill\", function(d) { return z(d.key); })\r\n      \r\n      \r\n      \r\n      \r\n});\r\n\r\n</script>\r\n\r\n\r\n<table class=\"table\">\r\n    <thead>\r\n    <tr>\r\n        <th>A</th>\r\n        <th>B</th>\r\n        <th>Projects </th>\r\n        <th>Count</th>\r\n    </tr>\r\n    </thead>\r\n    <tbody>\r\n        <% for a in map_a.keys.sort %>\r\n        <% for b in map_b.keys.sort %>\r\n        <% \r\n            k = \"\\\\#{a}-\\\\#{b}\"\r\n            v = map[k] \r\n            v = [] unless v\r\n            if v.size > 0 \r\n        %>  \r\n        <tr>\r\n            <td><%=a%></td><td><%=b%></td><td><%=v.collect{|i| link_to(i[\'protocol_no\'],\"../Project/show?id=\\\\#{i[\'_id\']}\",:target=>\'_blank\')}.join(\", \").html_safe%></td>\r\n            <td>\r\n                <%\r\n                if params[:query][:row]==\'number_of_records\'\r\n       \r\n        size = v.size\r\n    else\r\n     \r\n        sum= 0 \r\n        for i in v\r\n            sum += i[params[:query][:row]].to_i\r\n        end\r\n         size = sum\r\n        \r\n    end\r\n                %>\r\n                <%=size%>\r\n            </td>\r\n        </tr>\r\n        \r\n        <% end %>\r\n        <% end %>\r\n        <% end %>\r\n    </tbody>\r\n</table>\r\n\r\n\r\n\r\n<% end %>\r\n<% end %>',NULL,NULL,NULL,'2018-07-31 07:29:13','2018-07-31 07:29:13','report_helper',''),(3581,'project_summary_partial',1396,3,'<%=render :inline=>this.report_helper%>\r\n<%\r\n    build_result :project \r\n%>\r\n<%= yield :result %>',NULL,NULL,NULL,'2018-07-31 08:00:00','2018-07-31 08:00:00','project_summary_partial',''),(3582,'product_search',1385,3,'<%\r\n    models = get_model\r\n    if params[:query]\r\n    \r\n    if params[:query][:q] !=\"\"\r\n    query = /\\\\#{params[:query][:q]}/\r\n    products = models[:pl_product].where(\'$or\'=>[{:name=>query},{:code=>query}]).all :limit=>20\r\n    else\r\n    \r\n    sheet = models[:pl_sheet].find params[:sheet_id]\r\n    \r\n    product_items = models[:pl_period_product].where(:sheet_id=>sheet.id).all\r\n    \r\n    products = models[:pl_product].find product_items.collect{|i| i.product_id }\r\n        \r\n    end\r\n    \r\n    pmap ={}\r\n    for i in products\r\n        pmap[i.id] = i\r\n    end\r\n%>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n           <th>Code</th>\r\n            <th>Detail</th>\r\n         \r\n            <th>Group</th>\r\n            <th>Cost</th>\r\n            <th>Price</th>\r\n            <th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <% for i in products %>\r\n        <tr><td><%=i.code %><td>\r\n            <%=i.name %>\r\n        </td>\r\n            <td><%=i.group_code %></td><td><%=i.cost %></td><td><%=i.price %></td>\r\n            <td><%=link_to \'Select\', \"javascript:selectProduct(\'\\\\#{i.id}\')\" %></td></td>\r\n        </tr>\r\n        <% end %>\r\n    </tbody>\r\n</table>\r\n\r\n\r\n\r\n<script>\r\n    \r\n    var list = <%=pmap.to_json.html_safe%>;\r\n    \r\n    function selectProduct(pid){\r\n        p = list[pid];\r\n      \r\n        template = []\r\n        template.push(\"<td>\"+p[\'code\']+\"<input type=\'hidden\' name=\'un-visit[]\' value=\'\"+p[\'id\']+\"\'>\"+\"</td>\")\r\n        template.push(\"<td>\"+p[\'name\']+\"</td>\")\r\n        template.push(\"<td>\"+p[\'group_code\']+\"</td>\")\r\n        template.push(\"<td><input type=\'text\' name=\'un-visit-note[]\' value=\'\'>\"+\"</td>\")\r\n        template.push(\"<td><a href=\'#\' id=\'\"+p[\'id\']+\"\'>Delete</a</td>\")\r\n        $(\'#unschedule-list\').append(\"<tr id=\'r\"+p[\'id\']+\"\'>\"+template.join()+\"</tr>\");\r\n        $(\'#\'+p[\'id\']).click(function(){\r\n            $(\'#r\'+p[\'id\']).remove()\r\n            return false\r\n        })\r\n        $(\'#close\').click();\r\n        // $(\'#search_result\').html(\'\')\r\n    }\r\n    \r\n    \r\n</script>\r\n<% end %>',NULL,NULL,NULL,'2018-07-31 16:28:19','2018-07-31 16:28:19','product_search',''),(3583,'document_name',1406,1,'\'visit_tissue\'',NULL,NULL,NULL,'2018-07-31 17:20:25','2018-07-31 17:20:25',NULL,NULL),(3584,'assignment',1278,2,'<%\r\n    models = get_model\r\n    \r\n    \r\n    projects = models[:project].all.sort{|a,b| a.protocol_no<=>b.protocol_no }\r\n    mmap = {}\r\n    models[:member].all.each do |i|\r\n    mmap[i.id.to_s] = i     \r\n    end\r\n    \r\n#     pi|PI\r\n# admin|Admin\r\n# startup|Start up\r\n# sn|Study Nurse\r\n# sc|Study Coordinator\r\n# pharmacist|Pharmacist\r\n# labco|Lab Coordinator\r\n# finance|Finance\r\n# radiologist|Radiologist\r\n# pathologist|Pathologist\r\n# ophthalmologist|Ophthalmologist\r\n# cadiologist|Cadiologist\r\n# other|Other\r\n\r\n   pi_list  = models[:member].where(:position=>\'pi\').all.collect{|i| [i.name,i.id]}\r\n   sn_list  = models[:member].where(:position=>\'sn\').all.collect{|i| [i.name,i.id]}\r\n   sc_list  = models[:member].where(:position=>\'sc\').all.collect{|i| [i.name,i.id]}\r\n   si_list  = models[:member].where(:position=>\'pi\').all.collect{|i| [i.name,i.id]}\r\n   \r\n   \r\n   startup_list =  models[:member].where(:position=>\'startup\').all.collect{|i| [i.name,i.id]}\r\n   pharmacist_list = models[:member].where(:position=>\'pharmacist\').all.collect{|i| [i.name,i.id]}\r\n   pm = models[:member_project].all\r\n   \r\n   \r\n   sponsors = models[:sponsor].all.collect{|i| [i.name, i.id]}\r\n   customers = models[:customer].all.collect{|i| [\"\\\\#{i.name} : \\\\#{i.acc_code}\", i.id]}\r\n   \r\n   map = {}\r\n   \r\n   \r\n   for i in pm\r\n   \r\n   pid = i.project_id\r\n   role = i.role\r\n   \r\n   map[pid] = {} unless map[pid]\r\n   map[pid][role] = [] unless map[pid][role]\r\n   map[pid][role] << i.member_id\r\n   \r\n   \r\n   end\r\n\r\n   if request.post?\r\n     models[:member_project].destroy_all\r\n    if params[:pi]\r\n        params[:pi].each_pair do |k,v| \r\n            for i in v\r\n              m = mmap[i]\r\n              models[:member_project].create :member_id=>i, :project_id=>k, :role=>m.position if m\r\n            end\r\n        end\r\n    end\r\n    \r\n    ulist = {}\r\n    \r\n    if params[:spo]\r\n        params[:spo].each_pair do |k,v| \r\n            for i in v\r\n             \r\n              \r\n              ulist[k] = {} unless ulist[k]\r\n              \r\n              ulist[k][:sponsor_id]=i\r\n              \r\n            end\r\n        end\r\n    end\r\n    if params[:cus]\r\n        params[:cus].each_pair do |k,v| \r\n            for i in v\r\n              ulist[k] = {} unless ulist[k]\r\n              \r\n              ulist[k][:customer_id]=i\r\n              \r\n            end\r\n        end\r\n    end\r\n    \r\n    \r\n    ulist.each_pair do|p,v|\r\n\r\n        models[:project].find(p).update_attributes v\r\n        \r\n    end\r\n    \r\n    \r\n    \r\n    \r\n    \r\n      if params[:startup]\r\n        params[:startup].each_pair do |k,v| \r\n            for i in v\r\n              m = mmap[i]\r\n              models[:member_project].create :member_id=>i, :project_id=>k, :role=>m.position if m\r\n            end\r\n        end\r\n    end\r\n    if params[:sn]\r\n        params[:sn].each_pair do |k,v| \r\n            for i in v\r\n              m = mmap[i]\r\n              models[:member_project].create :member_id=>i, :project_id=>k, :role=>m.position if m\r\n            end\r\n        end\r\n    end\r\n    if params[:sc]\r\n        params[:sc].each_pair do |k,v| \r\n            for i in v\r\n              m = mmap[i]\r\n              models[:member_project].create :member_id=>i, :project_id=>k, :role=>m.position if m\r\n            end\r\n        end\r\n    end\r\n      if params[:si]\r\n        params[:si].each_pair do |k,v| \r\n            for i in v\r\n              m = mmap[i]\r\n              models[:member_project].create :member_id=>i, :project_id=>k, :role=>\'si\' if m\r\n            end\r\n        end\r\n    end\r\n      if params[:pharma]\r\n        params[:pharma].each_pair do |k,v| \r\n            for i in v\r\n              m = mmap[i]\r\n              models[:member_project].create :member_id=>i, :project_id=>k, :role=>m.position if m\r\n            end\r\n        end\r\n    end\r\n    \r\n    %>\r\n    <meta http-equiv=\"refresh\" content=\"0; url=assignment\" />\r\n    \r\n    <%\r\n   else \r\n%>\r\n<style>\r\n    select{font-size:0.9em;width:150px;padding:0px}\r\n</style>\r\n<%= form_for :record, :url=>\"\" do|f| %>\r\n<h1>Project Assignment (<%=pm.size %> projects) </h1>  \r\n   \r\n\r\n\r\n<div style=\"float:right\">\r\nColumn : <%=link_to \'All\', \"javascript:scroll(0,1000);\", :class=>\'btn\' %>\r\n<span id=\"col-display\"></span>\r\n<%=link_to \'<<\', \"javascript:scroll(-1000,5);\", :class=>\'btn\' %>\r\n<%=link_to \'<\', \"javascript:scroll(-1,5);\", :class=>\'btn\' %>\r\n<%=link_to \'>\', \"javascript:scroll(1,5);\", :class=>\'btn\' %>\r\n<%=link_to \'>>\', \"javascript:scroll(1000,5);\", :class=>\'btn\' %>\r\n&nbsp;&nbsp;&nbsp;\r\n<%=link_to \'All\', \"javascript:rscroll(0,500);\", :class=>\'btn\' %>\r\n<span id=\"row-display\"></span>\r\n<%=link_to \'^\', \"javascript:rscroll(-5,15);\", :class=>\'btn\' %>\r\n<%=link_to \'v\', \"javascript:rscroll(5,15);\", :class=>\'btn\' %>\r\n</div>\r\n\r\n<br/>\r\n<br/>\r\n\r\n\r\n\r\n<div style=\"overflow:scroll\">\r\n<table class=\"table scroll-table\" style=\"font-size:1em\">\r\n<thead>\r\n    <tr>\r\n        <th>Protocol No</th>\r\n        <th>Title</th>\r\n        \r\n    \r\n        <th>Phase</th>\r\n        \r\n        \r\n        <th class=\"vcol\" cid=\"0\">1.Sponsor</th>\r\n            \r\n        <th class=\"vcol\" cid=\"1\">2.Customer</th>\r\n        <th class=\"vcol\" cid=\"2\">3.PI</th>\r\n        <th class=\"vcol\" cid=\"3\">4.Startup</th>\r\n        <th class=\"vcol\" cid=\"4\">5.Study Nurse 1</th>\r\n        <th class=\"vcol\" cid=\"5\">6.Study Nurse 2</th>\r\n        <th class=\"vcol\" cid=\"6\">7.Study Nurse 3</th>\r\n\r\n        <th class=\"vcol\" cid=\"7\">8.Study Co 1</th>\r\n        <th class=\"vcol\" cid=\"8\">9.Study Co 2</th>\r\n        <th class=\"vcol\" cid=\"9\">10.Study Co 3</th>\r\n    \r\n        <th class=\"vcol\" cid=\"10\">11.Pharmacist 1</th>\r\n        <th class=\"vcol\" cid=\"11\">12.Pharmacist 2</th>\r\n        \r\n        \r\n        <th class=\"vcol\" cid=\"10\">13.Sub-I 1</th>\r\n        <th class=\"vcol\" cid=\"11\">14.Sub-I 2</th>\r\n        <th class=\"vcol\" cid=\"10\">15.Sub-I 3</th>\r\n        <th class=\"vcol\" cid=\"11\">16.Sub-I 4</th>\r\n    </tr>\r\n</thead>\r\n<tbody>\r\n<% projects.each_with_index do |i,pindex| \r\n\r\n   pi = []\r\n   sn = []\r\n   sc = []\r\n   startup = []\r\n   pharmacist = []\r\n   si = []\r\n   \r\n   \r\n   if map[i.id]\r\n       \r\n   startup =  map[i.id][\'startup\'] if map[i.id][\'startup\']\r\n   pi = map[i.id][\'pi\'] if map[i.id][\'pi\']\r\n   sn = map[i.id][\'sn\'] if map[i.id][\'sn\']\r\n   sc = map[i.id][\'sc\'] if map[i.id][\'sc\']\r\n   pharmacist = map[i.id][\'pharmacist\'] if map[i.id][\'pharmacist\']\r\n   \r\n   si = map[i.id][\'si\'] if map[i.id][\'si\']\r\n   \r\n   end\r\n\r\n%>\r\n<tr class=\"vrow\" rid=\"<%=pindex%>\">\r\n    <th class=\"vfixed\"><%=pindex+1%>. \r\n        <%=link_to i.protocol_no, \"../Project/show?id=\\\\#{i.id}\"%> \r\n        <%=link_to \"NA\", \"../Project/show?id=\\\\#{i.id}\" if i.protocol_no ==\'\' or i.protocol_no==nil %>\r\n    </th>\r\n    <td class=\"vfixed\">\r\n        <%=i.project_title[0..30]%>\r\n        \r\n    </td>\r\n    <td class=\"vfixed\">\r\n        <%=i.phase%>\r\n    </td >\r\n\r\n    <td class=\"vcol\" cid=\"0\">\r\n      \r\n        <%=select_tag \"spo[\\\\#{i.id}][]\", options_for_select(sponsors,i.sponsor_id), :include_blank=>true %>  <br/><%=i.sponsor%>\r\n      \r\n    </td>\r\n    \r\n    <td class=\"vcol\" cid=\"1\">\r\n     \r\n        <%=select_tag \"cus[\\\\#{i.id}][]\", options_for_select(customers,i.customer_id), :include_blank=>true %><br/>   <%=i.cro%>\r\n    </td>\r\n\r\n    <td class=\"vcol\" cid=\"2\">\r\n        <%=select_tag \"pi[\\\\#{i.id}][]\", options_for_select(pi_list,pi[0]), :include_blank=>true %>\r\n    </td>\r\n    \r\n     <td class=\"vcol\" cid=\"3\">\r\n        <%=select_tag \"startup[\\\\#{i.id}][]\", options_for_select(startup_list,startup[0]), :include_blank=>true %>\r\n    </td>\r\n  \r\n    <td class=\"vcol\" cid=\"4\">\r\n        <%=select_tag \"sn[\\\\#{i.id}][]\", options_for_select(sn_list,sn[0]), :include_blank=>true %>\r\n    </td>\r\n    \r\n    <td class=\"vcol\" cid=\"5\">\r\n        <%=select_tag \"sn[\\\\#{i.id}][]\", options_for_select(sn_list,sn[1]), :include_blank=>true %>\r\n    </td>\r\n    \r\n    <td class=\"vcol\" cid=\"6\">\r\n        <%=select_tag \"sn[\\\\#{i.id}][]\", options_for_select(sn_list,sn[2]), :include_blank=>true %>\r\n    </td>\r\n    <td class=\"vcol\" cid=\"7\">\r\n        <%=select_tag \"sc[\\\\#{i.id}][]\", options_for_select(sc_list,sc[0]), :include_blank=>true %>\r\n    </td>\r\n    <td class=\"vcol\" cid=\"8\">\r\n        <%=select_tag \"sc[\\\\#{i.id}][]\", options_for_select(sc_list,sc[1]), :include_blank=>true %>\r\n    </td>\r\n    \r\n    <td class=\"vcol\" cid=\"9\">\r\n        <%=select_tag \"sc[\\\\#{i.id}][]\", options_for_select(sc_list,sc[2]), :include_blank=>true %>\r\n    </td>\r\n    \r\n    \r\n    \r\n    \r\n    <td class=\"vcol\" cid=\"10\">\r\n        <%=select_tag \"pharma[\\\\#{i.id}][]\", options_for_select(pharmacist_list,pharmacist[0]), :include_blank=>true %>\r\n    </td>\r\n    <td class=\"vcol\" cid=\"11\">\r\n        <%=select_tag \"pharma[\\\\#{i.id}][]\", options_for_select(pharmacist_list,pharmacist[1]), :include_blank=>true %>\r\n    </td>\r\n    \r\n    \r\n    <td class=\"vcol\" cid=\"12\">\r\n        <%=select_tag \"si[\\\\#{i.id}][]\", options_for_select(pi_list,si[0]), :include_blank=>true %>\r\n    </td>\r\n    <td class=\"vcol\" cid=\"13\">\r\n        <%=select_tag \"si[\\\\#{i.id}][]\", options_for_select(pi_list,si[1]), :include_blank=>true %>\r\n    </td>\r\n    <td class=\"vcol\" cid=\"14\">\r\n        <%=select_tag \"si[\\\\#{i.id}][]\", options_for_select(pi_list,si[2]), :include_blank=>true %>\r\n    </td>\r\n    <td class=\"vcol\" cid=\"15\">\r\n        <%=select_tag \"si[\\\\#{i.id}][]\", options_for_select(pi_list,si[3]), :include_blank=>true %>\r\n    </td>\r\n    \r\n    \r\n \r\n    \r\n    \r\n  \r\n</tr>\r\n<% end %>\r\n</tbody>\r\n</table>\r\n</div>\r\n<%= f.submit \'Submit\', :class=>\'btn btn-success\'%>\r\n\r\n<% end %>\r\n<% end %>\r\n\r\n\r\n\r\n<script>\r\n  \r\n    \r\n    \r\n  function rscroll(n,p){\r\n        \r\n    cur = 1000\r\n    max = 0  \r\n        \r\n        \r\n    $(\'.vrow:visible\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'rid\'))\r\n    if(i<cur)cur=i;   \r\n  });\r\n  \r\n  $(\'.vrow\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'rid\'))\r\n    if(i>max)max=i;\r\n\r\n  });\r\n   \r\n   max+=1;\r\n    \r\n        \r\n    nc = cur+n;\r\n\r\n\r\n    \r\n   \r\n    if(nc+p>max)nc=max-p;\r\n    \r\n    \r\n    if(nc<0)nc=0;\r\n    \r\n    console.log(\"\"+i+\" \" +nc+\" \"+(cur+n)+\" \"+max)\r\n   \r\n  $(\'.vrow\').each(function(){\r\n     \r\n     v = $(this)\r\n     i = parseInt(v.attr(\'rid\'))\r\n    \r\n     \r\n     \r\n     if(nc<=i&&i<nc+p){\r\n         v.show();  \r\n     }else{\r\n         v.hide();\r\n     }\r\n     \r\n     if(nc+p<max)max=nc+p;\r\n     $(\'#row-display\').html(\"\"+(nc+1)+\" - \"+(max))\r\n  }); \r\n  \r\n     $.cookie(\"ui-scroll-row\",nc,{ expires : 1 });\r\n\r\n\r\n      \r\n  }\r\n    \r\n    \r\n  function scroll(n,p){\r\n\r\n  cur = 1000\r\n  max = 0 \r\n  \r\n  $(\'.vcol:visible\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'cid\'))\r\n    if(i<cur)cur=i;   \r\n  });\r\n  \r\n  $(\'.vcol\').each(function(){\r\n     \r\n    v = $(this)\r\n    i = parseInt(v.attr(\'cid\'))\r\n    if(i>max)max=i;\r\n\r\n  });\r\n\r\n    max+=1;\r\n   \r\n    nc = cur+n;\r\n\r\n\r\n\r\n \r\n    if(nc+p>max)nc=max-p;\r\n       if(nc<0)nc=0;\r\n          \r\n     $(\'.vcol\').each(function(){\r\n     \r\n     v = $(this)\r\n     i = parseInt(v.attr(\'cid\'))\r\n    \r\n\r\n     \r\n     \r\n     if(nc<=i&&i<nc+p){\r\n         v.show();  \r\n     }else{\r\n         v.hide();\r\n     }\r\n     \r\n     if(nc+p<max)max=nc+p;\r\n     \r\n     $(\'#col-display\').html(\"\"+(nc+1)+\" - \"+(max))\r\n      \r\n  });\r\n    \r\n    \r\n//   document.cookie = \"ui-scroll=\"+nc+\";\"\r\n\r\n   $.cookie(\"ui-scroll-col\",nc,{ expires : 1 });\r\n\r\n    \r\n  }\r\n  \r\n\r\n  col = 0\r\n  value = $.cookie(\"ui-scroll-col\");\r\n  if(value!=null) col =  parseInt(value);\r\n  row = 0\r\n  value = $.cookie(\"ui-scroll-row\");\r\n  if(value!=null) row =  parseInt(value);\r\n  \r\n  \r\n  scroll(col,5)\r\n  rscroll(row,15)\r\n\r\n\r\n    \r\n</script>',NULL,NULL,NULL,'2018-07-31 18:00:40','2018-07-31 18:00:40','assignment',''),(3585,'workload',1278,2,'',NULL,NULL,NULL,'2018-07-31 18:47:37','2018-07-31 18:47:37','workload',''),(3586,'create',1013,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=@current_service.title %></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border-x\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    @patient_module = m\r\n    \r\n    # change status to \'Completed\' when created document\r\n    @appointment.update_attributes :status=>\'Recovery\'\r\n   \r\n    # require \'pdfkit\'\r\n    # url = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/pdf?id=\\#{@patient_module.id}\"\r\n    # kit = PDFKit.new(url,:margin_top => \'0.2in\',:margin_right => \'0.2in\',:margin_bottom => \'0.2in\')\r\n    # report = \"tmp/cache/\\#{@patient_module.id.to_s}.pdf\"\r\n    # file = kit.to_file(report)\r\n    # field = @module_doc .find_by_column_name \'report\'\r\n    # att = @module_doc .attach_field_file field.id, report, \'\', File.open(report)\r\n    # @patient_module.update_attributes :report=>att.id\r\n \r\n    url = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/pdf?id=\\#{@patient_module.id}\"\r\n    attach_pdf = \"https://\\#{DOMAIN}/\\#{@current_solution.name}/\\#{@current_project.name}/\\#{@current_service.name}/attach_pdf?id=\\#{@patient_module.id}\"\r\n    \r\n    id = @patient_module.id.to_s\r\n    path = \"test\"\r\n    require_relative \'app/models/workers/pdf_generator\'\r\n    PdfGenerator.enqueue :url=>url,:id=>id,:path=>path,:return=>attach_pdf\r\n    \r\n\r\n \r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') ,:html=>{:id=>\'form-id\'} do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:100%;border:1px solid #ccc\" >\r\n<center>\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</center>\r\n    \r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%# f.submit \"Save & Exit\".html_safe,:class=>\'btn btn-small btn-success\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%# link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n\r\n<div id=\"button-submit\" style=\"width:100%;padding-left:20px;position:fixed;height:40px;background:#eee;padding:5px;bottom:0px;border-top:1px solid #ccc\">\r\n\r\n<div id=\"validation-error\" style=\"display:inline-block;margin-bottom:5px;\" class=\"alert alert-info\">Loading...</div>\r\n<%= f.submit \"Finish\".html_safe, :class=>\'btn btn-small btn-info\',:id=>\'record-submit\',:data=>{:disable_with=>\'Updating..\'} %> |\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\ncustom_validation();\r\n// alert(\'Please fill all information\');\r\n// if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n<%\r\nif @appointment.visit_type and @appointment.visit_type!=\'\'\r\n    \r\nvisit = get_model(\'visit_type\').find(@appointment.visit_type)\r\n if visit   \r\n%>\r\n//$(\'#data-schedule\').val(\'<%=visit.ref_id%>\')\r\n\r\n<% end %>\r\n<% end %>\r\n\r\n</script>   \r\n<script>jQuery(\"body\").addClass(\"sidebar_hidden_force\");jQuery(\"#sidebar_bt\").hide();</script>',NULL,NULL,NULL,'2018-08-02 10:22:38','2018-08-02 10:22:38','create',''),(3587,'edit',1013,2,'\r\n<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<script>\r\nfunction custom_validation(){\r\n    alert(\'Please fill all information\');\r\n}\r\n</script>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=@current_service.title %></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border-x\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n    locker = locker_model.where(:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n\r\n\r\n    url = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{@current_service.name}/pdf?id=\\\\#{@patient_module.id}\"\r\n    attach_pdf = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{@current_service.name}/attach_pdf?id=\\\\#{@patient_module.id}\"\r\n    \r\n    id = @patient_module.id.to_s\r\n    path = \"test\"\r\n    require_relative \'app/models/workers/pdf_generator\'\r\n    PdfGenerator.enqueue :url=>url,:id=>id,:path=>path,:return=>attach_pdf\r\n    \r\n    @patient_module.update_attributes :report=>nil\r\n    \r\n    \r\n\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) ,:html=>{:id=>\'form-id\'} do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n\r\n<div id=\"button-submit\" style=\"width:100%;padding-left:20px;position:fixed;height:40px;background:#eee;padding:5px;bottom:0px;border-top:1px solid #ccc\">\r\n<%= f.submit \"Finish\".html_safe, :class=>\'btn btn-small btn-info\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n<div id=\"validation-error\" style=\"display:inline-block;margin-bottom:5px;\" class=\"alert alert-info\">Loading...</div>\r\n\r\n\r\n</div>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n    \r\n    var t = $(\'#data-approve\').val()\r\n    if(t!=\'Yes\'){\r\n        var date = new Date();\r\n        var hour = date.getHours()\r\n        var min = date.getMinutes()\r\n        if(hour>=15){\r\n            //  $(\'#data-schedule\').val(\'2\');  \r\n            // $.sticky(\"Set to special clinic\", {autoclose : 5000, position: \"top-right\" });\r\n             \r\n        }\r\n            \r\n    }\r\n    \r\n    \r\n</script>\r\n\r\n<script>\r\n\r\n\r\n\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n    \r\nif (custom_validation()&&!validator.validate()) {\r\n// alert(\'Please fill all information\');\r\n\r\nreturn false;\r\n}else{\r\n      return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n\r\n$(document).ready(function(){\r\n    v = $(\'#data-approve\')\r\n    \r\n    $(\'.splashy-warning_triangle\').each(function(){\r\n        $(this).addClass(\'splashy-check\')\r\n        $(this).removeClass(\'splashy-warning_triangle\')\r\n    })\r\n<%\r\n    mapp = @module_model.find(@patient_module.parent_id)\r\n    @appointment = get_model(\'appointment\').find(mapp.module_id)\r\n%>\r\n<%\r\nif @appointment.visit_type and @appointment.visit_type!=\'\'\r\n\r\n\r\nvisit = get_model(\'visit_type\').find(@appointment.visit_type)\r\nif visit    \r\n%>\r\n// $(\'#data-schedule\').val(\'<%=visit.ref_id%>\')\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n})\r\n\r\n</script>   \r\n\r\n<script>jQuery(\"body\").addClass(\"sidebar_hidden_force\");jQuery(\"#sidebar_bt\").hide();</script>\r\n\r\n',NULL,NULL,NULL,'2018-08-02 10:23:14','2018-08-02 10:23:14','edit',''),(3588,'finding_template',1379,1,'{\r\n:name=>\'NA\',\r\n:order=>[:location,:disease,:intervention],\r\n:validate=>[],\r\n:models=>{:location=>[\'location\',\'location_tag\',\'single\'],:disease=>[\'disease\',\'disease_tag\',\'single\'],:intervention=>[\'intervention\',\'intervention_tag\',\'multitple\']},\r\n:view_organized_by=>:location,\r\n:data_organized_by=>:disease,\r\n:intervention_by=>:intervention,\r\n:view=>[\r\n    {   :title=>\'Esophagus\',\r\n        :value=>\'esophagus\',\r\n        :adj=>\'esophageal\',\r\n        :view_text=> \':esophagus_distance -cm from incisor in the :esophagus of esophagus\',\r\n        :filter_dependencies=>{:disease=>{\'reflux\'=>[\'esophagus_distance\',\'esophagus\'],\'hiatal_hernia\'=>[\'esophagus_distance\',\'esophagus\'],\'mallory_weiss\'=>[\'esophagus_distance\',\'esophagus\']}}\r\n    },\r\n    {\r\n        :title=>\'Stomach\',\r\n        :value=>\'stomach\',\r\n        :view_text=> \':stomach of stomach\',\r\n     