float:left\">\r\n\r\n\r\n\r\n<%= render :inline=>this.display %>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong>Approved By :</strong> \r\n<%=render_value \'endoscopist\'%> \r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<script>\r\n\r\n<%\r\n        require \'csv\'\r\n        icd10_list = {}\r\n        CSV.foreach(File.join(Dir.pwd,\'public\',\'/esm/cusys/med/icd-10.csv\')) do |row|\r\n           icd10_list[row[0]]=row[1] \r\n        end\r\n        \r\n%>\r\n    \r\n    var icd10_list = <%=icd10_list.to_json.html_safe%>\r\n    icd = $(\'#data-icd10\').val()\r\n    licd = icd.split(\'|\')\r\n    div = $(\'#diagnosis-div\')\r\n    tr = div.parent().parent()\r\n    icd = $(\"<tr>\").append(\"<td><strong>ICD</strong></td>\")\r\n    for(var id in licd){\r\n        i = licd[id]\r\n        icd.append($(\'<p>\').append(\"<v>\"+i+\"</v> : \"+icd10_list[i]))\r\n        \r\n    }\r\n    tr.after(icd)\r\n    \r\n    \r\n    \r\n    \r\n</script>\r\n\r\n<% if second_atts.size>0 %>\r\n\r\n<div class=\"footer\">\r\n   &nbsp; \r\n</div>\r\n<div class=\"wrapper\" style=\"page-break-before: always;\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'<%=@current_project.get_setting(\'logo_report_path\')%>\' height=\'70px\' style=\"Float:left,top:5px\" /></div><h3> <strong><%=@current_service.title %> Diagnosis Report<br />\r\n<%=@current_project.get_setting(\"report_title_1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%>\r\n  </strong></h3>\r\n</center>\r\n\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> Name-Surname : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'-\'\r\n    if patient.gender == \'1\'\r\n        gender = \'Male\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'Female\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>Sex : </strong><%= gender %> &nbsp; <strong>Age :&nbsp;</strong>\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D-->\r\n      <br /><strong>Date :  </strong> <%=render_value \'start_procedural_date\'%> <strong>Produral Time :  </strong> <%=render_value \'start_procedural_time\'%> - <%=render_value \'stop_procedural_time\'%> Total Time :  <%=render_value \'procedural_time\'%>  <strong>Project : </strong> <%=render_value \'study_project\'%>\r\n    <br /><strong>Endoscopist : </strong><%=render_value \'endoscopist\'%>  \r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n<div style=\"border:0px solid\">\r\n   <div style=\"  padding: 5px; text-align:center; font-size:14px;\">\r\n    <% for i in second_atts  %>\r\n    <div class=\"crop\" style=\"float:left;display:inline-block;border:0px solid red;width:280px\">\r\n    <img src=\"<%=i.path%>\" style=\"width:260px;height:200px\" /><br /><span><%=i.title%></span><br />\r\n    </div>\r\n    <% end %>\r\n   <div class=\"clear\"></div>\r\n</div>\r\n\r\n\r\n    \r\n\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div>\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong>Approved By :</strong> \r\n<%=render_value \'endoscopist\'%> \r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n<% end %>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2018-08-11 02:16:22','2018-08-11 02:16:22','print_partial',''),(3597,'create',1379,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n   return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s\r\n    %>\r\n    <script>alert(\"Someone is editing this documen!!t\");window.location = \"<%=return_url%>\";</script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=@current_service.title %></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border-x\" style=\"border:0px solid\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    @patient_module = m\r\n    \r\n    # change status to \'Completed\' when created document\r\n    @appointment.update_attributes :status=>\'Recovery\'\r\n   \r\n    # require \'pdfkit\'\r\n    # url = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{@current_service.name}/pdf?id=\\\\#{@patient_module.id}\"\r\n    # kit = PDFKit.new(url,:margin_top => \'0.2in\',:margin_right => \'0.2in\',:margin_bottom => \'0.2in\')\r\n    # report = \"tmp/cache/\\\\#{@patient_module.id.to_s}.pdf\"\r\n    # file = kit.to_file(report)\r\n    # field = @module_doc .find_by_column_name \'report\'\r\n    # att = @module_doc .attach_field_file field.id, report, \'\', File.open(report)\r\n    # @patient_module.update_attributes :report=>att.id\r\n \r\n    url = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{@current_service.name}/pdf?id=\\\\#{@patient_module.id}\"\r\n    attach_pdf = \"https://\\\\#{DOMAIN}/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/\\\\#{@current_service.name}/attach_pdf?id=\\\\#{@patient_module.id}\"\r\n    \r\n    id = @patient_module.id.to_s\r\n    path = \"test\"\r\n    require_relative \'app/models/workers/pdf_generator\'\r\n    PdfGenerator.enqueue :url=>url,:id=>id,:path=>path,:return=>attach_pdf\r\n    \r\n\r\n \r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n    \r\n    record.endoscopist = @appointment.provider\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') ,:html=>{:id=>\'form-id\'} do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\n <div style=\"background:#eeeeff;padding:5px;width:100%;border:1px solid #ccc\" >\r\n<center>\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</center>\r\n    \r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n                 \r\n<%# f.submit \"Save & Exit\".html_safe,:class=>\'btn btn-small btn-success\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n\r\n<%# link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n\r\n<div id=\"button-submit\" style=\"width:100%;padding-left:20px;position:fixed;height:40px;background:#eee;padding:5px;bottom:0px;border-top:1px solid #ccc\">\r\n\r\n<div id=\"validation-error\" style=\"display:inline-block;margin-bottom:5px;\" class=\"alert alert-info\"></div>\r\n<%= f.submit \"Finish\".html_safe, :class=>\'btn btn-small btn-info\',:id=>\'record-submit\',:data=>{:disable_with=>\'Updating..\'} %> |\r\n<%= link_to \'Cancel\', return_url+\"&reset_lock=\\\\#{locker.id}\",:confirm=>\'Are you sure?\' %>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\ncustom_validation();\r\n// alert(\'Please fill all information\');\r\n// if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n<%\r\nif @appointment.visit_type and @appointment.visit_type!=\'\'\r\n    \r\nvisit = get_model(\'visit_type\').find(@appointment.visit_type)\r\n if visit   \r\n%>\r\n$(\'#data-schedule\').val(\'<%=visit.ref_id%>\')\r\n\r\n<% end %>\r\n<% end %>\r\n\r\n</script>   \r\n<script>jQuery(\"body\").addClass(\"sidebar_hidden_force\");jQuery(\"#sidebar_bt\").hide();</script>',NULL,NULL,NULL,'2018-08-15 06:52:30','2018-08-15 06:52:30','create',''),(3598,'print_appointment',1363,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  begining = Time.now.beginning_of_day\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date,:status=>{\'$ne\'=>\'Cancelled\'}).all\r\n \r\n \r\n  records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n  visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i  and patients[i.patient_id]  \r\n p = patients[i.patient_id]  \r\n provider = providers[ap.provider.to_s] if providers\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p and  p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year}y. \"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'room\'=>ap.room,\r\n    \'procedure_list\'=>ap.procedure_list,\r\n    \'note\'=>ap.note,\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>(provider.nil? or provider==\'\') ? \'-\' : provider.name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'age\'=>age,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id,\r\n    \'ward\'=>ap.ward,\r\n    \'record_by\'=>ap.record_by,\r\n    \'anes\'=>ap.anes\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\nlist = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\n\r\nrooms = {}\r\n\r\nfor i in list\r\n\r\n    room_id = i[\'room\']\r\n    rooms[room_id] = [] unless rooms[room_id]\r\n    rooms[room_id] << i\r\n    \r\n    \r\nend\r\n\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:1200px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n.wrapper{ width:1200px;margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:1200px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:100%;margin-left:0px;margin-right:0px} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: bold;\r\n	padding: 7px 7px 8px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 12px;\r\nbackground: #e8e8e8;\r\n}\r\n#table-3 td {\r\n	font-size: 10px;\r\n	padding: 4px 7px 2px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n.boxx {width:100%; float:left; padding:5px }\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\" >\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<% \r\nrooms.keys.sort.each do |room_id|\r\n\r\nrl = rooms[room_id]\r\n\r\nlist = rl\r\n    \r\n%>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"boxx\">\r\n<br /><br /><div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"200\" style=\"float:left\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;</p>\r\n<p>Printed at :&nbsp;<%= Time.now.strftime(\'%d/%m/%Y %H:%M\') %></p>\r\n</div>\r\n</div>\r\n<b>\r\n<%= room_id %></b>\r\n<span style=\"float:right\"> \r\n<b>Date : <%= date.strftime(\"%d/%m/%y\")%> , Total Patient : <%= appointments.size %></b>\r\n\r\n<%\r\n\r\n    day_offs = @models[:day_off].where(:date=>{\'$lte\'=>date},:to_date=>{\'$gte\'=>date}).all.collect{|i| \r\n        \r\n        provider = @models[:provider].find i.provider\r\n        \r\n        period = \"\\\\#{i.date.strftime(\'%d/%m/%Y\')} - \\\\#{i.to_date.strftime(\'%d/%m/%Y\')}\"\r\n        period = \"\\\\#{i.date.strftime(\'%d/%m/%Y\')}\" if i.date==i.to_date\r\n        \r\n        {:name=> provider.name, :title=>i.title, :period=>period }\r\n        \r\n    }\r\n    \r\n   if day_offs.size > 0 \r\n       %>\r\n<span style=\"color:#aa3333\"><i> Note : \r\n       <%\r\n    for i in day_offs\r\n%>\r\n<%= \"\\\\#{i[:name]} \\\\#{i[:title]} \\\\#{i[:period]}\" %>\r\n<% end %>\r\n</i></span>\r\n<% end %>\r\n\r\n</span>\r\n\r\n<br />\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th style=\"width:40px\">Time</th>\r\n    <th style=\"width:100px\">Pro</th>\r\n    <th style=\"width:200px\">ชื่อ - สกุล</th>\r\n    <th style=\"width:100px\">HN</th>\r\n    <th style=\"width:40px\">อายุ</th>\r\n    \r\n\r\n\r\n    <th style=\"width:200px\">Provider</th>\r\n    <th>Ans</th>\r\n    <th>ward</th>\r\n    <th>Note</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n  <%\r\n    list.sort!{|a,b| a[\'start\']<=>b[\'start\'] }\r\n    \r\n    tmap = {}\r\n    \r\n    for i in list\r\n        t = ((i[\'start\'].to_datetime.to_i )/60/30)%48\r\n  \r\n        tmap[t] = [] unless tmap[t]\r\n        \r\n        tmap[t] << i\r\n        \r\n     \r\n        \r\n    end\r\n  %>\r\n  \r\n  <% #\r\n    \r\n    px = {}\r\n    \r\n    48.times do |t|\r\n        \r\n    \r\n        \r\n        \r\n    b = (begining+t*30*60).strftime(\"%H:%M\")\r\n        \r\n    if t>13 and t <= 36 or (tmap[t]!=nil and tmap[t].size>0) and px[b]==nil\r\n        \r\n        list = tmap[t]\r\n    \r\n        if list\r\n        \r\n        list.each_with_index do |i,index|  \r\n        \r\n        te = 0 \r\n        start =  i[\'start\'].to_datetime\r\n        te = (i[\'end\'].to_datetime.strftime(\"%H:%M\").to_datetime.to_i - i[\'start\'].to_datetime.to_i)/1800 if i[\'end\']\r\n        \r\n        \r\n        style_txt = \'\'\r\n        \r\n    \r\n        if i[\'anes\'] and  i[\'anes\'].index(\'Consult\') #or  i[\'anes\'] ==  \'Consult team anesth\' or  i[\'anes\'] ==  \'Consult GI anesth\' \r\n         style_txt = \'background:#DFDFDF\'\r\n        end\r\n        \r\n        start = start - (start.to_i.to_f%1800)/24/3600\r\n        \r\n        \r\n        te.times do |j|\r\n            \r\n            \r\n        px[(start+j*(1.0/48)).strftime(\"%H:%M\")] = true\r\n  \r\n    %>\r\n    <tr>\r\n    <td style=\"<%=style_txt%>\" >\r\n    <%=(start+j*(1.0/48)).strftime(\"%H:%M\")%><% index+1%></td>\r\n    <% if j==0 %>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'procedure_list\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'title\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'hn\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'age\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'provider\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'anes\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'ward\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'note\']%></td> \r\n    \r\n    <% end %>\r\n    </tr>\r\n    <% end %>\r\n    \r\n    <% end %>\r\n    \r\n       <%else %>\r\n       \r\n    <tr>\r\n    <td><%=(begining+t*30*60).strftime(\"%H:%M\")%> </td>\r\n     <td>&nbsp;</td> <td>&nbsp;</td> <td>&nbsp;</td> <td>&nbsp;</td> <td>&nbsp;</td> <td>&nbsp;</td> <td>&nbsp;</td> <td>&nbsp;</td> \r\n    </tr>\r\n    \r\n      <%end %> \r\n    \r\n    <% end %>\r\n    <% end %>\r\n    \r\n    \r\n</tbody>\r\n  </table>\r\n</div>  \r\n\r\n  <hr style=\"page-break-after: always;\">\r\n\r\n  \r\n<% end %>\r\n</div>\r\n  </div></div></div></div></div>\r\n</body>\r\n</html>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2018-08-16 04:02:01','2018-08-16 04:02:01','print_appointment','*'),(3600,'document_name',1409,1,'\'gasmotin\'',NULL,NULL,NULL,'2018-08-18 08:42:20','2018-08-18 08:42:20',NULL,NULL),(3601,'research_index',146,3,'<meta http-equiv=\"refresh\" content=\"0; url=../Research/index\" />\r\n',NULL,NULL,NULL,'2018-08-18 09:13:49','2018-08-18 09:13:49','research_index',''),(3602,'index',1411,2,'<center>\r\n<h1>\r\n    \r\n    Surgical Endoscopy Research Center\r\n    \r\n</h1>\r\n</center>\r\n<br/>\r\n\r\n<hr/>\r\n<br/>\r\n<div class=\"row-fluid\">\r\n    \r\n    <div class=\"span6\">\r\n        \r\n        <%= link_to \'Gasmotin Project\', \'../Gasmotin/index\', :class=>\'btn\', :style=>\'padding:3em\' %>\r\n\r\n\r\n    </div>\r\n    \r\n</div>\r\n    \r\n',NULL,NULL,NULL,'2018-08-18 09:26:39','2018-08-18 09:26:39','index',''),(3603,'gasmotin',1411,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<center><h1>Gasmotin Project</h1>\r\n<br/>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n     \r\n        <%= form_for :search, :url=>\'gasmotin_partial?update=search\', :data=>{:remote=>true} do |f| %>\r\n        \r\n        HN : <%= f.text_field :query, :value=>\'\' %>\r\n        \r\n        <%= f.submit \'Search\' %>\r\n        \r\n        <% end %>\r\n                \r\n    </div>\r\n</div>\r\n</center>\r\n<div id=\"search\"></div>\r\n<%\r\n    \r\n    date = Time.now\r\n    date = Date.parse(params[:date]) if params[:date]\r\n    \r\n    \r\n%>\r\n\r\n\r\n<h3>Gasmotin Records for <%=text_field_tag \"date\", date.strftime(\"%d/%m/%Y\"), :id=>\'select_date\' %>\r\n\r\n : </h3>\r\n<script>\r\n	$(\"#select_date\").kendoDatePicker({\r\n		value: \'<%= date.strftime(\"%d/%m/%Y\") if date %>\',\r\n	});\r\n	\r\n	$(\"#select_date\").change(function(){\r\n	  	obj = $(this)\r\n		v = obj.val()\r\n        window.location=\"gasmotin?date=\"+v;\r\n	});\r\n</script>\r\n<%\r\n    \r\n    name_gasmotin = @current_project.name+\'#gasmotin\' \r\n\r\n\r\n    m_records = @module_model.where(:module_name=>name_gasmotin, :created_at=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}).all\r\n    list = []\r\n    \r\n    for i in m_records\r\n    \r\n    age = 0\r\n    \r\n    r = @models[:gasmotin].find i.module_id\r\n    endoscopist_1 = nil\r\n    date_note = nil\r\n    if r \r\n    patient = @patient_model.find i.patient_id\r\n    \r\n       age = r.age\r\n       date_note = r.date_note\r\n       \r\n       endoscopist_1 = @models[:provider].find r.endoscopist_1\r\n       \r\n       if endoscopist_1\r\n           \r\n          endoscopist_1 = endoscopist_1.name\r\n   else\r\n       \r\n       endoscopist_1 = \'-\'\r\n       end\r\n   \r\n    # date = Time.now\r\n    # if r\r\n    #     quality_of_preparate = r.quality_of_preparate\r\n    #     date = r.date_note\r\n    #     endoscopist = r.endoscopist_1\r\n    # end\r\n    \r\n    # age = ((date - patient.birth_date.to_datetime)/365.0).to_i if patient.birth_date\r\n    # # age = patient.birth_date\r\n\r\n    list << {:id=>i.id, :hn=>patient.hn,:gender=> patient.gender,:parent_id=> i.parent_id,:age=>age, :name=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\", :date=>date_note, :endoscopist_1=>endoscopist_1}\r\n end\r\n    end\r\n\r\n%>\r\n<%= tabular :data=>list, :model=>%w{hn name gender age  endoscopist_1 date }.collect{|i| i.to_sym } do |row,out| \r\n      \r\n        out << link_to(\"Edit\", \"../Gasmotin/edit?id=\\\\#{row[:id]}\", :class=>\'btn btn-info\')\r\n\r\n\r\nout \r\nend\r\n%>\r\n<i><%=list.size%> records</i>\r\n',NULL,NULL,NULL,'2018-08-18 09:33:52','2018-08-18 09:33:52','gasmotin',''),(3604,'gasmotin_partial',1411,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n\r\n    \r\n    # patient search\r\n    \r\n    # search for all colono records for a patient\r\n    \r\n    # sort by date\r\n    if request.post?\r\n        \r\n    q = params[:search][:query] \r\n    \r\n    patient = @patient_model.where(:hn=>q).first\r\n  \r\n  \r\n   if patient \r\n   \r\n    # 45678/77\r\n    name = @current_project.name+\'#colonoscopy\' \r\n    list = []\r\n    records = @module_model.where(:module_name=>name, :patient_id=>patient.id).all\r\n    \r\n    for i in records\r\n    age = 0 \r\n    r = @models[:colonoscopy].find i.module_id\r\n    quality_of_preparate = \'\'\r\n    endoscopist = nil\r\n    date = Time.now\r\n    if r\r\n        quality_of_preparate = r.quality_of_preparate\r\n        date = r.date_note\r\n   \r\n        endoscopist = r.endoscopist_1\r\n    end\r\n    \r\n    age = ((date - patient.birth_date.to_datetime)/365.0).to_i if patient.birth_date and date\r\n    # age = patient.birth_date\r\n\r\n    list << {:colo_id=>r.id, :start_at=>r.start_at,:hn=>patient.hn,:gender=> patient.gender,:start_to_scope_at=>r.start_scope_at,:parent_id=> i.parent_id,  :name=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\", :age=>age, :date=>date, :quality_of_preparate=>quality_of_preparate, :endoscopist=>endoscopist}\r\n    \r\n    end\r\n%>\r\n<h3>\r\n    Search Result : \r\n</h3>\r\n<%= tabular :data=>list, :model=>%w{hn name gender age quality_of_preparate endoscopist date }.collect{|i| i.to_sym } do |row,out| \r\n\r\n    name_gasmotin = @current_project.name+\'#gasmotin\' \r\n\r\n\r\n    m_gasmotin = @module_model.where(:module_name=>name_gasmotin, :parent_id=>row[:parent_id]).first\r\n    \r\n    if m_gasmotin\r\n    \r\n        out << link_to(\"Edit\", \"../Gasmotin/edit?id=\\\\#{m_gasmotin.id}\", :class=>\'btn btn-info\')\r\n\r\n    else    \r\n        out << link_to(\"Create\", \"../Gasmotin/create?colo_id=\\\\#{row[:colo_id]}&patient_id=\\\\#{patient.id}&parent_id=\\\\#{row[:parent_id]}&data[age]=\\\\#{row[:age]}\", :class=>\'btn btn-success\')\r\n    \r\n    end\r\n\r\nout\r\nend\r\n%>\r\n\r\n<% else %>\r\n<div class=\"alert\">\r\n    Patient not found \r\n</div>\r\n<% end %>\r\n<% end %>\r\n',NULL,NULL,NULL,'2018-08-18 09:38:41','2018-08-18 09:38:41','gasmotin_partial',''),(3605,'init',1411,4,'<%\r\n @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n%>',NULL,NULL,NULL,'2018-08-18 10:08:40','2018-08-18 10:08:40','init',''),(3606,'create',1409,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s  and params[:override]==nil\r\n    %>\r\n    <script>\r\n        res = confirm(\"Someone is editing this document. Would you like to override the record?\");\r\n        if(res==true){\r\n             $(document).ready(function(){\r\n              $(\'#ref_number\').parent().append(\"<input type=\'hidden\' name=\'override\' value=\'override\' />\");\r\n               \r\n           })\r\n        }else\r\n            window.location = \"<%=return_url%>\";\r\n\r\n\r\n        </script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n<style>\r\n    .document-border { border:0px solid;}\r\n</style>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n    \r\n    \r\n    if params[:colo_id]\r\n       \r\n       colo = get_model(\'colonoscopy\').find params[:colo_id]\r\n       \r\n       if colo\r\n           \r\n           record.date_note = colo.date_note\r\n           record.start_scope_at = colo.start_at\r\n           record.start_scope_at = Time.now\r\n           record.quality_of_preparate = colo.quality_of_preparate\r\n           record.endoscopist_1 = colo.endoscopist_1\r\n           \r\n       end\r\n       \r\n        \r\n    end\r\n\r\n    \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\nRef : <%=ref_number%>\r\n <div class=\"<%=\'hide\' if params[:parent_id]%>\" style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc;\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n<%\r\n    if return_url.include? \'?\'\r\n        return_url += \"&reset_lock=\\\\#{locker.id}\"\r\n    else\r\n        return_url += \"?reset_lock=\\\\#{locker.id}\"\r\n    end\r\n%>\r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2018-08-18 15:29:21','2018-08-18 15:29:21','create',''),(3607,'context_menu',1409,4,'<br/><br/>\r\n<center><%=link_to \'Gasmotin Home\', \"index\",:class=>\'btn\'%></center><br/>\r\n<center><%=link_to \'Research\', \"../Research/index\",:class=>\'btn\'%></center>',NULL,NULL,NULL,'2018-08-18 15:32:19','2018-08-18 15:32:19','context_menu',''),(3608,'document_name',1412,1,'\'sponsor\'',NULL,NULL,NULL,'2018-08-19 08:40:27','2018-08-19 08:40:27',NULL,NULL),(3609,'update_status',1385,3,'<%\r\n\r\n    visit = get_model(\'visit\').find params[:id]\r\n    unless params[:pharmacist_status]\r\n    visit.update_attributes :status=>params[:status].humanize\r\n    else\r\n    visit.update_attributes :pharmacist_status=>params[:pharmacist_status].humanize\r\n    \r\n    end\r\n    \r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=show?id=<%=params[:id] %>\" />',NULL,NULL,NULL,'2018-08-19 17:13:19','2018-08-19 17:13:19','update_status',''),(3610,'document_name',1413,1,'\'resource\'',NULL,NULL,NULL,'2018-08-19 17:31:34','2018-08-19 17:31:34',NULL,NULL),(3611,'index',1414,2,'\r\n<style>\r\n.fc-button-content{\r\n    padding:8px;\r\n}\r\n    \r\n</style>\r\n\r\n\r\n						<div class=\"span12\">\r\n							<h2 class=\"heading\">Monitor Room Booking</h2>\r\n							<div id=\"calendar\"></div>\r\n						</div>\r\n				\r\n					\r\n		\r\n\r\n\r\n\r\n\r\n            <link rel=\"stylesheet\" href=\"/gebo/lib/fullcalendar/fullcalendar_gebo.css\" />	\r\n			<script src=\"/gebo/lib/fullcalendar/fullcalendar.min.js\"></script>\r\n			<script src=\"/gebo/lib/fullcalendar/gcal.js\"></script>\r\n\r\n<%\r\n    \r\n    models = get_model\r\n    \r\n    events = models[:booking_item].all\r\n    \r\n    \r\n    events.collect!{|e|  \r\n    \r\n                e.start_time_at = Time.now unless e.start_time_at\r\n                e.stop_time_at = Time.now unless e.stop_time_at\r\n                \r\n         \r\n    \r\n    			{\r\n    			        :title=>e.name,\r\n						:start=> DateTime.parse(e.start_at.strftime(\"%Y-%m-%d\")+\"T\"+e.start_time_at.strftime(\"%H:%M\") ),\r\n						:end=>  DateTime.parse(e.stop_at.strftime(\"%Y-%m-%d\")+\"T\"+e.stop_time_at.strftime(\"%H:%M\")),\r\n						:allDay=> e.all_day==\'true\',\r\n                        :color=> e.color,\r\n                        :textColor=>e.text_color,\r\n                        :url=>\"../BookingItem/show?id=\\\\#{e.id}\"\r\n                }\r\n    \r\n    }\r\n\r\n%>\r\n<script>\r\n\r\n\r\n    \r\n    /* [ ---- Gebo Admin Panel - calendar ---- ] */\r\n\r\n	$(document).ready(function() {\r\n		gebo_calendar.regular();\r\n// 		gebo_calendar.google();\r\n		//* resize elements on window resize\r\n		var lastWindowHeight = $(window).height();\r\n		var lastWindowWidth = $(window).width();\r\n		$(window).on(\"debouncedresize\",function() {\r\n			if($(window).height()!=lastWindowHeight || $(window).width()!=lastWindowWidth){\r\n				lastWindowHeight = $(window).height();\r\n				lastWindowWidth = $(window).width();\r\n				//* rebuild calendar\r\n				$(\'#calendar\').fullCalendar(\'render\');\r\n				// $(\'#calendar_google\').fullCalendar(\'render\');\r\n			}\r\n		});\r\n	});\r\n	\r\n	//* calendar\r\n	gebo_calendar = {\r\n		regular: function() {\r\n			var date = new Date();\r\n			var d = date.getDate();\r\n			var m = date.getMonth();\r\n			var y = date.getFullYear();\r\n			var calendar = $(\'#calendar\').fullCalendar({\r\n				header: {\r\n					left: \'prev next\',\r\n					center: \'title,today\',\r\n					right: \'month,agendaWeek,agendaDay\'\r\n				},\r\n				buttonText: {\r\n					prev: \'<i class=\"icon-chevron-left cal_prev\" />\',\r\n					next: \'<i class=\"icon-chevron-right cal_next\" />\'\r\n				},\r\n				aspectRatio: 2,\r\n				selectable: true,\r\n				selectHelper: true,\r\n				select: function(start, end, allDay) {\r\n				    \r\n				    window.location=\"../BookingItem/create?data[start_time_at]=\"+start.toJSON()+\"&data[stop_time_at]=\"+end.toJSON()+\"&data[all_day]=\"+allDay;\r\n				    \r\n				// 	var title = prompt(\'Event Title:\');\r\n				// 	if (title) {\r\n				// 		calendar.fullCalendar(\'renderEvent\',\r\n				// 			{\r\n				// 				title: title,\r\n				// 				start: start,\r\n				// 				end: end,\r\n				// 				allDay: allDay\r\n				// 			},\r\n				// 			true // make the event \"stick\"\r\n				// 		);\r\n				// 	}\r\n				// 	calendar.fullCalendar(\'unselect\');\r\n				},\r\n				editable: true,\r\n				theme: false,\r\n				events: <%=events.to_json.html_safe%>,\r\n				eventColor: \'#bcdeee\'\r\n			})\r\n		}\r\n	};\r\n	\r\n// 	[\r\n// 					{\r\n// 						title: \'All Day Event\',\r\n// 						start: new Date(y, m, 1),\r\n//                         color: \'#aedb97\',\r\n//                         textColor: \'#3d641b\'\r\n// 					},\r\n// 					{\r\n// 						title: \'Long Event\',\r\n// 						start: new Date(y, m, d-5),\r\n// 						end: new Date(y, m, d-2)\r\n// 					},\r\n// 					{\r\n// 						id: 999,\r\n// 						title: \'Repeating Event\',\r\n// 						start: new Date(y, m, d+8, 16, 0),\r\n// 						allDay: false\r\n// 					},\r\n// 					{\r\n// 						id: 999,\r\n// 						title: \'Repeating Event\',\r\n// 						start: new Date(y, m, d+15, 16, 0),\r\n// 						allDay: false\r\n// 					},\r\n// 					{\r\n// 						title: \'Meeting\',\r\n// 						start: new Date(y, m, d+12, 15, 0),\r\n// 						allDay: false,\r\n//                         color: \'#aedb97\',\r\n//                         textColor: \'#3d641b\'\r\n// 					},\r\n// 					{\r\n// 						title: \'Lunch\',\r\n// 						start: new Date(y, m, d, 12, 0),\r\n// 						end: new Date(y, m, d, 14, 0),\r\n// 						allDay: false\r\n// 					},\r\n// 					{\r\n// 						title: \'Birthday Party\',\r\n// 						start: new Date(y, m, d+1, 19, 0),\r\n// 						end: new Date(y, m, d+1, 22, 30),\r\n// 						allDay: false,\r\n//                         color: \'#cea97e\',\r\n//                         textColor: \'#5e4223\'\r\n// 					},\r\n// 					{\r\n// 						title: \'Click for Google\',\r\n// 						start: new Date(y, m, 28),\r\n// 						end: new Date(y, m, 29),\r\n// 						url: \'http://google.com/\'\r\n// 					}\r\n// 				]\r\n    \r\n</script>\r\n\r\n',NULL,NULL,NULL,'2018-08-19 17:35:20','2018-08-19 17:35:20','index',''),(3613,'context_menu',1379,4,'<%\r\nreturn_url = \'\'\r\nreturn_url = \"&return=\\\\#{params[:return]}\" if params[:return]\r\nname = @current_service.title\r\nplist = []\r\nlist = [{:name=>\'List\',:link=>\'index\',:remote=>false},{:name=>name+ \' Creation\' ,:link=>\'create\',:remote=>false},{:name=>name+\" Analysis\",:link=>\'analysis\',:remote=>false}]\r\n\r\nplist<<{:name=>\'Back to Detail\',:link=>\"../Home/index\",:remote=>false} if params[:return]\r\n\r\n\r\nif params[:id]\r\nplist<<{:name=>\'Edit \'+name,:link=>\"edit?id=\\\\#{params[:id]}\\\\#{return_url}\",:remote=>false}\r\n\r\n\r\n#list<<{:name=>\'Delete\',:link=>\"destroy?id=\\\\#{params[:id]}\",:remote=>false}\r\nend\r\nlist<<{:name=>\'Back to Home\',:link=>\"../Home/index\",:remote=>false}\r\n%>\r\n<%= show_menu [{:name=>this.document_name.humanize,:open=>true,:actions=>list},\r\n{:name=>\'Patient Detail\',:open=>true,:actions=>plist}\r\n] \r\n\r\n%>\r\n\r\n<%\r\n\r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n\r\n     p_id = @current_project.id\r\n     doc = @current_project.get_document @current_service.name\r\n     img = nil\r\n     mrecord =  @module_model.find(params[:id])\r\n     if mrecord\r\n     record = doc.get_model.find(mrecord.module_id)\r\n     for i in doc.fields\r\n        if i.field_type==\'image_camera\'\r\n            img = i\r\n        break\r\n        end\r\n     end\r\n     \r\n     \r\n%>\r\n<div class=\"accordion-body collapse in\" id=\"collapse-1\">\r\n			<div class=\"accordion-inner\">\r\n				<ul class=\"nav nav-list\">\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\">\r\n					   <%=link_to \'Download Library\',\"/esm_image/\\\\#{doc.id}/download?record_id=\\\\#{record.id}&field_id=\\\\#{img.id}&p_id=\\\\#{p_id}\" ,:class=>\'k-button\',:target=>\'_blank\'%>\r\n					</li>\r\n				</ul>\r\n			</div>\r\n</div>\r\n<% end %>',NULL,NULL,NULL,'2018-08-20 01:11:14','2018-08-20 01:11:14','context_menu',''),(3614,'print_partial',1370,3,'<%=render :inline=>@current_service.operations.where(:name=>\'print\').first.command.gsub(\'\\#{\',\'\\\\#{\'),:locals=>{:this=>this,:context=>context}%>',NULL,NULL,NULL,'2018-08-20 01:28:27','2018-08-20 01:28:27','print_partial',''),(3615,'document_name',1415,1,'\'booking_item\'',NULL,NULL,NULL,'2018-08-20 04:34:26','2018-08-20 04:34:26',NULL,NULL),(3616,'create',1415,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<% link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  \r\n  record = model.new\r\n  \r\n  record = model.new params[:data] if params[:data]\r\n      \r\n  if params[:data] and params[:data][:all_day]==\'true\'\r\n     \r\n     record.start_time_at += 1\r\n     record.stop_time_at += 1\r\n      \r\n  end\r\n \r\n     record.start_at = record.start_time_at\r\n     record.stop_at = record.stop_time_at\r\n  \r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"../Booking/index\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-08-20 05:15:06','2018-08-20 05:15:06','create',''),(3617,'form',1415,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = f