'context_menu_partial',1363,3,'<style>\r\n    .list-x{width:100px;border:0px solid;display:inline-block;}\r\n</style>\r\n<% \r\nif @current_role != \'pathologist\'\r\nmodules = @context.get_projects_by_abstract \'ehr.emr\' \r\nmodel = get_model\r\nehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\nehr_models = ehr.load_model\r\npatient_model = ehr_models[:patient]\r\nm = modules.collect{|i| {:name=>i.title,:link=>\"../../\\\\#{i.name}/Home/index\",:remote=>false} }\r\nm <<  {:name=>\'Back to EHR\',:link=>\"../../www/Home/index\",:remote=>false}\r\n%>\r\n<%# show_menu m %>\r\n\r\n<%\r\n\r\nif params[:id]\r\n\r\npm_model = ehr_models[:patient_module]\r\n\r\nlpm = pm_model.find(params[:id])\r\n    \r\nif params[:mode]==\'module\' and lpm\r\n    \r\n    \r\n    apm = pm_model.find(lpm.parent_id)\r\n    if lpm and apm\r\n    ap = model[:appointment].find(apm.module_id)\r\n    else\r\n    apm = pm_model.find(params[:id])\r\n    ap = model[:appointment].find(apm.module_id)\r\n\r\n    end\r\n    \r\nelse\r\n    ap = model[:appointment].find(params[:id]) \r\n    if ap\r\n    apm = pm_model.where(:module_id=>ap.id).first\r\n    end\r\n    \r\nend\r\npatient = nil\r\nif apm\r\n   patient = patient_model.find(apm.patient_id) \r\nend\r\n\r\n# if params[:id] or params[:parent_id]\r\n    \r\nobj = this.config\r\n\r\nlist = []\r\n\r\nfor i in obj\r\nfor j in i[:actions]\r\n  if j[:dashboard]==true\r\n    list << j\r\n  end\r\nend\r\nend\r\n\r\n\r\n# \r\n\r\n\r\n# if params[:parent_id]\r\n# elsif params[:service]==\'Home\'\r\n#     ap = model[:appointment].find(params[:id]) \r\n# else\r\n#     lpm = pm_model.find(params[:id])\r\n#     apm = pm_model.find(lpm.parent_id)\r\n#     ap = model[:appointment].find(apm.module_id)\r\n# end\r\n\r\n# obj = [\r\n# {:name=>\'Endoscopy\',:open=>true,:actions=>[\r\n# {:name=>\'Consignment\',:service=>\'consignment\',:link=>\'../Consignment/index\',:remote=>false},\r\n# {:name=>\'Pre Scope\',:service=>\'pre_scope\',:link=>\'../PreScope/index\',:remote=>false},\r\n# {:name=>\'Intra Scope\',:service=>\'intra_scope\',:link=>\'../IntraScope/index\',:remote=>false},\r\n# {:name=>\'Post Scope\',:service=>\'post_scope\',:link=>\'../PostScope/index\',:remote=>false}]},\r\n# {:name=>\'Endoscopist Records\',:open=>true,:actions=>[\r\n# {:name=>\'Colonosopy\',:service=>\'colonoscopy\',:link=>\'../Colonoscopy/index\',:remote=>false},\r\n# {:name=>\'Gastroscopy\',:service=>\'gastroscopy\',:link=>\'../Gastroscopy/index\',:remote=>false}]},\r\n# {:name=>\'ETC\',:open=>true,:actions=>[\r\n# {:name=>\'Pathology\',:service=>\'pathology\',:link=>\'../Pathology/index\',:remote=>false},\r\n# {:name=>\'Analyses\',:service=>\'report\',:link=>\'../Report/index\',:remote=>false}]}]\r\n\r\nif patient\r\n%>\r\n<%# params[:id] %>\r\n<%#list.inspect  %>\r\n\r\n\r\n<div class=\"accordion-group\" style=\"\">\r\n	<div class=\"accordion-heading\">\r\n		<a href=\"#collapse-0\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n		Visit Detail\r\n		</a>\r\n		</div>\r\n		<div class=\"accordion-body collapse in\" id=\"collapse-0\">\r\n			<div class=\"accordion-inner\">\r\n			<div class=\"alert alert-info\">\r\n			\r\n<b>Name : </b><%= patient.first_name %> <%= patient.last_name %> <br/>\r\n<b>HN : </b><%= patient.hn %> <br/>\r\n\r\n			\r\n<b>Visit Type : </b><%=t = model[:visit_type].find(ap.visit_type); t.name if t %> <br/>\r\n<b>Visit Date : </b><%= ap.date  if ap%><br/>\r\n</div>\r\n<% for i in list %>\r\n<div style=\"padding-bottom:5px;padding-top:5px;border-bottom:1px solid #ccc\">\r\n<span class=\"list-x\"><%=i[:name]%> : </span>\r\n<%\r\n   ilist = []\r\n#   apm\r\n   pm = pm_model.where(:parent_id=>apm.id,:module_name=>\"\\\\#{@current_project.name}#\\\\#{i[:service]}\").first\r\n   return_url = \"../Home/patient_record?id=\\\\#{ap.id}\"\r\n   if pm\r\n      ilist << link_to(\"Edit\",\"\\\\#{i[:link].split(\'/\')[0..-2].join(\'/\')}/edit?record_name=\\\\#{patient.hn}-\\\\#{patient.first_name}-\\\\#{patient.last_name}&ref_2=\\\\#{i[:name]}&id=\\\\#{pm.id}&return=\\\\#{return_url}\",:class=>\'btn\')\r\n      ilist << link_to(\"Print\",\"\\\\#{i[:link].split(\'/\')[0..-2].join(\'/\')}/print?id=\\\\#{pm.id}\",:class=>\'btn \',:target=>\'_blank\')\r\n   else\r\n      patient_id = apm.patient_id\r\n      patient_hn = patient.hn\r\n      \r\n      \r\n      ilist << link_to(\"Create\",\"\\\\#{i[:link].split(\'/\')[0..-2].join(\'/\')}/create?patient_id=\\\\#{patient_id}&ref_2=\\\\#{i[:name]}&record_name=\\\\#{patient_hn}-\\\\#{patient.first_name}-\\\\#{patient.last_name}&parent_id=\\\\#{apm.id}&return=\\\\#{return_url}\",:class=>\'btn\')\r\n   end\r\n\r\n\r\n\r\n for j in ilist \r\n%>\r\n<%=j.html_safe%>\r\n<% end %>\r\n</div>\r\n\r\n<% end %>\r\n<div><br/>\r\n    <center><%=link_to \'Back to Record\', params[:return], :class=>\'btn\' %></center>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n\r\n</div>\r\n\r\n<% else %>\r\n\r\n<%=show_menu this.config %>\r\n<% end %>\r\n\r\n<%    \r\n\r\n# obj << {:name=>\'Links\',:open=>true,:actions=>m}\r\n%>\r\n<% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\') %>\r\n\r\n<% else %>\r\n<center style=\"margin-top:20px\"><%= link_to \'Pathology Records\',\'../Pathology/index\',:class=>\'btn\' %></center>\r\n<% end %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-09-03 04:19:53','2018-09-03 04:19:53','context_menu',''),(3652,'context_menu',1385,4,'<div id=\"context_menu\">\r\n    \r\n</div>\r\n<script>\r\n$.ajax({\r\n  url: \"../Home/global_menu\",\r\n  context: document.body\r\n}).done(function(data) {\r\n  $( \'#context_menu\' ).html(data);\r\n});\r\n</script>\r\n',NULL,NULL,NULL,'2018-09-04 04:30:20','2018-09-04 04:30:20','context_menu',''),(3653,'global_menu',1272,3,'<% if @current_user %>\r\n<div id=\"context-menu\" class=\"accordion\">\r\n	<div class=\"accordion-group\">\r\n		<div class=\"accordion-heading sdb_h_active\">\r\n			<a href=\"../Home/index\" class=\"accordion-toggle\">\r\n			<i class=\"icon-th\"></i> Dashboard\r\n			</a>\r\n		</div>\r\n	</div>\r\n	<div class=\"accordion-group\">\r\n		<div class=\"accordion-heading sdb_h_active\">\r\n			<a href=\"../Home/my_project\" class=\"accordion-toggle\">\r\n			<i class=\"icon-folder-open\"></i>	My Projects\r\n			</a>\r\n		</div>\r\n	</div>\r\n	\r\n	<div class=\"accordion-group\">\r\n		<div class=\"accordion-heading sdb_h_active\">\r\n			<a href=\"../Member/index\" class=\"accordion-toggle\">\r\n					<i class=\"icon-user\"></i> Members\r\n			</a>\r\n		</div>\r\n	</div>\r\n	<div class=\"accordion-group\">\r\n		<div class=\"accordion-heading sdb_h_active\">\r\n			<a href=\"../Report/index\" class=\"accordion-toggle\">\r\n			<i class=\"icon-folder-close\"></i>	Reports\r\n			</a>\r\n		</div>\r\n	</div>\r\n<% if @current_role==\'admin\' or  @current_role==\'developer\' or  @current_role==\'pharmacist\' %>\r\n\r\n	<div class=\"accordion-group\">\r\n		<div class=\"accordion-heading sdb_h_active\">\r\n			<a href=\"../IpItem/index\" class=\"accordion-toggle\">\r\n			<i class=\"icon-leaf\"></i>	IP Inventory\r\n			</a>\r\n		</div>\r\n	</div>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n<%\r\n    days = [7,30]\r\n    \r\n    for d in days\r\n\r\n    entry_logs = get_model(\'entry_log\').where(:created_at=>{\'$gte\'=>(Time.now-d*24*3600)})\r\n    \r\n    logins = {}\r\n    actions = {}\r\n    \r\n    map = {}\r\n    \r\n    for i in entry_logs\r\n    \r\n        login = i.login\r\n        \r\n        logins[login] = 0 unless  logins[login]\r\n        logins[login] +=  1\r\n        \r\n        action = \"\\\\#{i.action.humanize} \\\\#{i.type}\"\r\n        \r\n        actions[action] = 0 unless  actions[action]\r\n        actions[action] +=  1\r\n        \r\n        \r\n        \r\n    end\r\n    \r\n    sort_logins = []\r\n    \r\n    logins.each_pair do |k,v| \r\n        sort_logins << [k,v]\r\n    end\r\n    \r\n    sort_events = []\r\n    \r\n    actions.each_pair do |k,v| \r\n        sort_events << [k,v]\r\n    end\r\n    \r\n    sort_logins.sort!{|a,b| b[1]<=>a[1]}\r\n    \r\n    sort_events.sort!{|a,b| b[1]<=>a[1]}\r\n%>\r\n\r\n<div class=\"accordion-group\">\r\n		<div class=\"accordion-heading\">\r\n			<a href=\"#collapseLogL<%=d%>\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n				<i class=\"icon-user\"></i> 	Most Active Users : <%=d%> days\r\n			</a>\r\n		</div>\r\n		<div class=\"accordion-body collapse\" id=\"collapseLogL<%=d%>\" style=\"height: 0px;\">\r\n			<div class=\"accordion-inner\">\r\n				<ul class=\"nav nav-list\">\r\n				<% for i in sort_logins %>\r\n					<li><a href=\"javascript:void(0)\"><%=i[0]%> : <%=i[1]%> </a></li>\r\n			    <% end %>\r\n				</ul>\r\n				\r\n			</div>\r\n		</div>\r\n	</div>\r\n\r\n\r\n<div class=\"accordion-group\">\r\n		<div class=\"accordion-heading\">\r\n			<a href=\"#collapseLogE<%=d%>\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle collapsed\">\r\n				<i class=\"icon-th\"></i> 	Most Active Events : <%=d%> days\r\n			</a>\r\n		</div>\r\n		<div class=\"accordion-body collapse\" id=\"collapseLogE<%=d%>\" style=\"height: 0px;\">\r\n			<div class=\"accordion-inner\">\r\n				<ul class=\"nav nav-list\">\r\n			    <% for i in sort_events %>\r\n					<li><a href=\"javascript:void(0)\"><%=i[0]%> : <%=i[1]%></a></li>\r\n			    <% end %>\r\n				</ul>\r\n				\r\n			</div>\r\n		</div>\r\n	</div>\r\n\r\n\r\n\r\n<% end %>\r\n</div>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2018-09-04 04:35:03','2018-09-04 04:35:03','global_menu','*'),(3654,'context_menu',1383,4,'<div id=\"context_menu\">\r\n    \r\n</div>\r\n<script>\r\n$.ajax({\r\n  url: \"../Home/global_menu\",\r\n  context: document.body\r\n}).done(function(data) {\r\n  $( \'#context_menu\' ).html(data);\r\n});\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2018-09-04 04:44:34','2018-09-04 04:44:34','context_menu',''),(3655,'export',464,3,'\r\n<%\r\n\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n\r\n  @document = get_document(this.document_name)\r\n\r\n  doc = @document\r\n\r\n  data = get_model(this.document_name).all :sort=>\'created_at desc\'\r\n  \r\n   fields = @document.fields\r\n   fields = fields.collect{|i| [i.column_name,i.name] unless Document.visual_types.index(i.field_type) }.compact!\r\n   fields << \'created_at\'\r\n   fields << \'updated_at\'\r\n    @document = doc\r\n    @fields = @document.fields\r\n   \r\n   data.collect! do |i|\r\n    \r\n    @record = i\r\n    p = nil\r\n    age = nil\r\n    age = 0\r\n    hn = nil\r\n    \r\n    p = @patient_model.new\r\n    m = @module_model.collection.find(:module_id=>i.id).first\r\n    if m \r\n    \r\n    patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n    if patient\r\n    bdate = 0\r\n    bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n    age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n   \r\n    p = patient\r\n    \r\n\r\n    end\r\n   end\r\n    if p\r\n    r = {:patient=>p,:age=>age,:record=>i}\r\n    else\r\n    r = nil\r\n    end\r\n    \r\n    r\r\n   \r\n   end\r\n   \r\n   data.compact!\r\n   data = data.sort{|a,b| a[:patient][\'patient_order\'].to_i<=>b[:patient][\'patient_order\'].to_i }\r\n   \r\n   \r\n   \r\n   unless params[:type]\r\n   \r\n%>\r\n<table>\r\n<tr><td>Order</td><td>Patient number</td><td>Gender</td><td>Birth Date</td><td>Age</td><td>Date of ICU Admission</td>\r\n\r\n<%\r\nfor i in fields \r\n%><td><%= i[1] %></td>\r\n<% end %>\r\n</tr>\r\n<% for i in data \r\n\r\n   p = i[:patient]\r\n   age = i[:age]\r\n   @record = i[:record] \r\n  \r\n    bd = p[\'birth_date\'].strftime(\'%d-%m-%Y\') if !p[\'birth_date\'].nil?\r\n%>\r\n<tr>\r\n<td><%=p[\'patient_order\'] %></td><td><%=p[\'patient_number\']%></td><td><%=p[\'gender\']%></td><td><%=bd%></td><td><%=age%></td>\r\n<td><%=p[\'date_of_icu_admission\']%></td>\r\n<%\r\n    \r\n    for j in fields \r\n    \r\n    if @record[j[0]]\r\n%>\r\n<td><%= render_value j[0] %></td>\r\n<% else %>\r\n<td>.</td>\r\n<% end %>\r\n<% end %>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% else \r\nif params[:type]==\'csv\'\r\n    require \'csv\'\r\n    \r\n    response.headers[\"Content-Type\"] = \"text/csv\"\r\n    response.headers[\"Content-disposition\"] = \"attachment; filename=\\\\#{this.document_name}-\\\\#{params[:solution_name]}-\\\\#{Time.now.to_i}.xls\"\r\n    \r\nres = CSV.generate do |csv|\r\n  csv << [\"hos\",\"patient_order\", \"patient_number\", \"gender\", \"birth_date\",\"age\",\"date_of_icu_admission\"]+fields.collect{|i| i[0]}\r\n  for i in data \r\n  p = i[:patient]\r\n  age = i[:age]\r\n  @record = i[:record]\r\n  lines = []\r\n  lines = fields.collect{|j| \r\n  if @record[j[0]]\r\n    res = render_value(j[0]).strip\r\n  else\r\n    res = \'\'\r\n  end\r\n  res\r\n  }\r\n  \r\n  csv << [params[:hos],p[\'patient_order\'], p[\'patient_number\'],p[\'gender\'],p[\'birth_date\'],age,p[\'date_of_icu_admission\']]+lines \r\n  end\r\n  # ...\r\nend\r\n%><%=res.html_safe%><%\r\nend\r\nend%>\r\n  \r\n  \r\n   \r\n   \r\n   ',NULL,NULL,NULL,'2018-09-06 02:00:00','2018-09-06 02:00:00','export','*'),(3656,'project_document',1278,4,'<%\r\n    project = @project\r\n\r\n%>\r\n\r\n\r\n<%\r\n\r\n    if project.status!=\'New\'  and project.status!=\'Pending\'\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n\r\n\r\n<%\r\n    \r\n    \r\n    \r\n    models = get_model\r\n\r\n   docs = [\'feasibility\',\'site_selection_visit\', \'investigator_meeting\']\r\n   \r\n   if project.status!=\'Pre-Startup\' \r\n \r\n        \r\n    docs += %w{ budget_negotiation  ec_submission crc_registration letter_of_authority certificate_request clinical_trial_agreement material_transfer_agreement draft_announcement}\r\n  \r\n    docs.delete \'pl_sheet\' if @current_role==\'customer\'\r\n \r\n   end\r\n   \r\n   \r\n   permission = {}\r\n   \r\n   if @current_role==\'customer\'\r\n        permission[:budget_negotiation]=false\r\n   end\r\n   \r\n   labels = {}\r\n   \r\n#   labels[\'pl_sheet\'] = \'Cost-Effective Evaluation\'\r\n%>\r\n\r\n<table class=\"table table-bordered\">\r\n<thead>\r\n    <tr>\r\n        <th>Document</th>\r\n        <th>Created at</th>\r\n        <th>Last updated at</th>\r\n        <th>Plan to finished at</th>\r\n        <th>Finished at</th>\r\n        <th>Note</th>\r\n        <th></th>\r\n        \r\n    </tr>\r\n</thead>\r\n<tbody>\r\n\r\n<%\r\n   \r\n   docs.each_with_index do |d,index|\r\n   \r\n   dname = d.camelize\r\n   dname = labels[d] if labels[d]\r\n   \r\n   docxs = models[:project_document].where(:document_name=>d,:project_id=>params[:id]).all\r\n   \r\n   \r\n   %>\r\n\r\n<tr>\r\n<th colspan=\"8\">\r\n<h4 style=\"display:inline-block\"><%=dname%>\r\n    <a  class=\"btn btn-mini\" href=\"<%=url_for(\"../\\\\#{dname}/create?pid=\\\\#{params[:id]}\")%>\"  ><i class=\"splashy-add_small\"></i> Create</a>\r\n</h4>\r\n</th>\r\n</tr>\r\n\r\n<div class=\"\">\r\n\r\n    \r\n<%\r\n   for i in docxs\r\n   \r\n    alert=\'\'\r\n    alert=\'alert-success\' if i.status==\'finished\'\r\n    alert=\'alert-danger\' if i.status==\'reply\'\r\n    alert=\'alert-info\' if i.status==\'review\'\r\n%>\r\n<tr>\r\n    <td>\r\n    - <%=link_to i.summary.humanize+ \" \", \"../\\\\#{dname}/show?id=\\\\#{i.document_id}\", :class=>\"\" %>\r\n    </td>\r\n    \r\n    <td>\r\n       <%= i.created_at.strftime(\"%d/%m/%Y %H:%M\") %>\r\n    </td>   \r\n    \r\n    <td>\r\n       <%= i.updated_at.strftime(\"%d/%m/%Y %H:%M\") %>\r\n    </td>    \r\n    \r\n    <td>\r\n       <%= i.plan_to_finish_date.strftime(\"%d/%m/%Y %H:%M\") if i.plan_to_finish_date %>\r\n    </td>   \r\n    <td>\r\n       <%= i.finished_date.strftime(\"%d/%m/%Y %H:%M\")if i.finished_date %>\r\n    </td>  \r\n    <td>\r\n         <%=text_field_tag \"document[\\\\#{i.id}][note]\",i.note,:style=>\'width:120px;margin:0px\'  %> <%= i.status.humanize if i.status %>\r\n    </td>  \r\n    \r\n    <td>\r\n    <%= link_to \'Edit\', \"../\\\\#{dname}/edit?id=\\\\#{i.document_id}\", :class=>\'btn btn-mini\' %>\r\n    <%= link_to \'Delete\', \"../\\\\#{dname}/destroy?id=\\\\#{i.document_id}\", :class=>\'btn btn-danger btn-mini\',:data=>{:confirm=>\'Are you sure?\'} %>\r\n    </td>    \r\n        \r\n    </tr> \r\n<% end %>\r\n<%#link_to \"Create \\\\#{dname}\", \"../\\\\#{dname}/create?pid=\\\\#{params[:id]}\", :class=>\"btn\" %>\r\n<% end %>\r\n\r\n</tbody>\r\n</table>\r\n\r\n<% end %>\r\n\r\n\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<h3> Other Documents</h3>\r\n<tabel class=\"table\">\r\n    <thead>\r\n        \r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            \r\n        </tr>\r\n    </tbody>\r\n</tabel>\r\n\r\n',NULL,NULL,NULL,'2018-09-06 09:49:00','2018-09-06 09:49:00','project_document',''),(3657,'project_member',1278,4,'\r\n<div class=\"heading\">\r\n<h1>CRC Members</h1>\r\n</div>\r\n<%\r\n    models = get_model\r\n  \r\n    current_user = models[:user].where(:login=>@current_user.login).first \r\n    admin_role = models[:role].where(:name=>\'admin\').first\r\n    current_user = models[:user].where(:role=>admin_role.id).first if @current_role==\'developer\'\r\n    \r\n    project = models[:project].find(params[:id])\r\n    \r\n    \r\n    \r\n    current_user_project = models[:user_project].where(:user_id=>current_user.id, :project_id=>project.id).first\r\n    \r\n    \r\n    is_admin = false\r\n    \r\n    if current_user_project\r\n        is_admin = true if current_user_project.role==\'admin\'\r\n    end\r\n\r\n\r\n    if project \r\n        \r\n        member_projects = models[:member_project].where(:project_id=>project.id).all\r\n        \r\n        \r\n%>\r\n\r\n<h3>CRC PI : </h3>\r\n<%  members  = member_projects.collect{|i| i if i.role==\'pi\'}.compact %>\r\n<div class=\"row-fluid\">\r\n<%  for i in members %>\r\n\r\n<div class=\"span4\">\r\n    <div>\r\n       <center>\r\n    <%\r\n        member = models[:member].find i.member_id\r\n        att = nil\r\n        if member\r\n        if member.picture\r\n            att = models[:attachment].find member.picture\r\n        end\r\n        path_img = \'/esm/cusys/cucrc/person.png\'\r\n        path_img = att.path if att\r\n    %>\r\n    <%=image_tag path_img ,:height=>150 %>\r\n    <br/>\r\n \r\n    <%=link_to member.name,\"../Member/show?id=\\\\#{member.id}\" if member%>\r\n\r\n    <% else \r\n    \r\n    i.destroy\r\n    %>\r\n    Member not found\r\n    <% end %>    \r\n    </center>\r\n    \r\n    </div>\r\n</div>\r\n<% end %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n    <h3>CRC StartUp :</h3>\r\n<%  members  = member_projects.collect{|i| i if i.role==\'startup\'}.compact %>\r\n<div class=\"row-fluid\">\r\n<%  for i in members %>\r\n\r\n<div class=\"span4\">\r\n    <div>\r\n       <center>\r\n    <%\r\n        member = models[:member].find i.member_id\r\n        att = nil\r\n        if member\r\n        if member.picture\r\n            att = models[:attachment].find member.picture\r\n        end\r\n       path_img = \'/esm/cusys/cucrc/person.png\'\r\n        path_img = att.path if att\r\n    %>\r\n    <%=image_tag path_img ,:height=>150 %>\r\n    <br/>\r\n \r\n    <%=link_to member.name,\"../Member/show?id=\\\\#{member.id}\" if member%>\r\n\r\n          <% else \r\n          i.destroy\r\n          %>\r\n    Member not found \r\n    <% end %>   \r\n        \r\n    </center>\r\n    </div>\r\n</div>\r\n<% end %>\r\n\r\n<div class=\"clear\"></div>\r\n\r\n<h3>CRC SN/SC : </h3>\r\n\r\n<%  members  = member_projects.collect{|i| i if i.role==\'sn\' or i.role==\'sc\'}.compact %>\r\n<div class=\"row-fluid\">\r\n<%  for i in members %>\r\n\r\n<div class=\"span4\">\r\n    <div>\r\n       <center>\r\n    <%\r\n        member = models[:member].find i.member_id\r\n        att = nil\r\n        if member\r\n        if member.picture\r\n            att = models[:attachment].find member.picture\r\n        end\r\n      path_img = \'/esm/cusys/cucrc/person.png\'\r\n        path_img = att.path if att\r\n    %>\r\n    <%=image_tag path_img,:height=>150  %>\r\n    <br/>\r\n \r\n    <%=link_to member.name,\"../Member/show?id=\\\\#{member.id}\" if member%>\r\n    <% else \r\n        i.destroy\r\n    %>\r\n    Member not found\r\n    <% end %>   \r\n        \r\n    </center>\r\n\r\n    </div>\r\n</div>\r\n<% end %>\r\n</div>\r\n<div class=\"clear\"></div>\r\n\r\n<% if @current_role ==\'admin\' or @current_role ==\'startup\' or @current_role ==\'developer\'  %>\r\n<a href=\"javascript:$(\'#manage\').toggle()\">Manage</a>\r\n\r\n\r\n<div id=\"manage\" style=\"display:none\">\r\n\r\n<div class=\"heading\">\r\n    <h1>CRC Project Members  </h1>\r\n</div>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr><th>Name</th><th>Role</th><th>Email</th><th></th></tr>\r\n    </thead>\r\n    <tbody>\r\n    <% for i in member_projects \r\n       member = models[:member].find i.member_id\r\n        user = models[:user].find i.user_id\r\n        if member\r\n    %>\r\n            <tr>\r\n            <td>\r\n                <%=member.name%>\r\n            </td>\r\n            <td>\r\n                <%=i.role%>\r\n            </td>\r\n            <td>\r\n                <%=member.email%>\r\n            </td>\r\n        \r\n         \r\n          \r\n                <td><%=link_to \'Remove\', \"../MemberProject/destroy?id=\\\\#{i.id}\", :class=>\'btn btn-mini btn-danger\', :data=>{:confirm=>\'Are you sure?\'} %></td>\r\n                \r\n            </tr>\r\n              <% \r\n\r\n    end %>\r\n    <% \r\n\r\n    end %>\r\n    </tbody>\r\n</table>\r\n\r\n\r\n<%\r\n\r\n\r\n    user_customer =   models[:user_customer].where(:user_id=>current_user.id).first       \r\n\r\n\r\n    \r\n    members = models[:member].all     \r\n    \r\n%>\r\n\r\n<div class=\"heading\">\r\n    <h1>CRC All Members</h1>\r\n</div>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr><th>Name</th><th>Position</th><th>Email</th><th></th></tr>\r\n    </thead>\r\n    <tbody>\r\n    <% for i in members \r\n        # user = models[:user].find i.user_id\r\n    %>\r\n            <tr><td>\r\n                <%=i.name%>\r\n            </td>\r\n            <td>\r\n                <%=i.position%>\r\n            </td>\r\n                <td>\r\n                <%=i.email%>\r\n            </td>\r\n            \r\n            \r\n                <td><%=link_to \'Add to project\', \"../MemberProject/add?member_id=\\\\#{i.id}&project_id=\\\\#{project.id}\", :class=>\'btn btn-mini\',:data=>{:confirm=>\'Are you sure?\'} %> \r\n                <%#link_to \'Delete\', \"../User/destroy?id=\\\\#{user.id}\", :class=>\'btn btn-mini btn-danger\', :data=>{:confirm=>\'Are you sure?\'} %></td> \r\n                \r\n            </tr>\r\n    <% end %>\r\n    </tbody>\r\n</table>\r\n<% end %><% end %>\r\n</div>\r\n\r\n\r\n<%\r\n    models = get_model\r\n  \r\n    current_user = models[:user].where(:login=>@current_user.login).first \r\n     admin_role = models[:role].where(:name=>\'admin\').first\r\n    current_user = models[:user].where(:role=>admin_role.id).first if @current_role==\'developer\'\r\n    \r\n    project = models[:project].find(params[:id])\r\n    \r\n    \r\n    current_user_project = models[:user_project].where(:user_id=>current_user.id, :project_id=>project.id).first\r\n    \r\n    is_admin = false\r\n    \r\n    if current_user_project\r\n        is_admin = true if current_user_project.role==\'admin\'\r\n    end\r\n\r\n\r\n    if project \r\n        \r\n        user_projects = models[:user_project].where(:project_id=>project.id).all\r\n        \r\n        \r\n%>\r\n<div class=\"heading\">\r\n    <h1>CRA Members </h1>\r\n</div>\r\n<% end %>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr><th>Login</th><th>Role</th><th>Email</th><th></th></tr>\r\n    </thead>\r\n    <tbody>\r\n    <% for i in user_projects \r\n        user = models[:user].find i.user_id\r\n        if user\r\n    %>\r\n            <tr><td>\r\n                <%=user.login%>\r\n            </td>\r\n            <td>\r\n                <%=i.role%>\r\n            </td>\r\n                <td>\r\n                <%=user.email%>\r\n            </td>\r\n                <td> <%=link_to \'Remove\', \"../UserProject/destroy?id=\\\\#{i.id}\", :class=>\'btn btn-mini btn-danger\', :data=>{:confirm=>\'Are you sure?\'}  if is_admin and user and user.login!=@current_user.login %></td>\r\n                \r\n            </tr>\r\n    <% \r\nend\r\n    end %>\r\n    </tbody>\r\n</table>\r\n\r\n\r\n<%\r\n\r\n\r\n    user_customer =   models[:user_customer].where(:user_id=>current_user.id).first       \r\n\r\n\r\n    \r\n    if user_customer\r\n    customer = models[:customer].find user_customer.customer_id\r\n    if customer\r\n        \r\n    user_customers =   models[:user_customer].where(:customer_id=>customer.id).all       \r\n    \r\n%>\r\n\r\n<div class=\"heading\">\r\n    <h1>Customer : <%=customer.name %></h1>\r\n</div>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr><th>Login</th><th>Email</th><th></th></tr>\r\n    </thead>\r\n    <tbody>\r\n    <% for i in user_customers \r\n        user = models[:user].find i.user_id\r\n    %>\r\n            <tr><td>\r\n                <%=user.login%>\r\n            </td>\r\n                <td>\r\n                <%=user.email%>\r\n            </td>\r\n            \r\n            \r\n                <td><%=link_to \'Add to project\', \"../UserProject/add?user_id=\\\\#{user.id}&project_id=\\\\#{project.id}\", :class=>\'btn btn-mini\',:data=>{:confirm=>\'Are you sure?\'}   if is_admin %> \r\n                <%#link_to \'Delete\', \"../User/destroy?id=\\\\#{user.id}\", :class=>\'btn btn-mini btn-danger\', :data=>{:confirm=>\'Are you sure?\'} %></td> \r\n                \r\n            </tr>\r\n    <% end %>\r\n    </tbody>\r\n</table>\r\n<%=link_to \"Register CRO User\", \"../Registration/user_signup?customer_id=\\\\#{customer.id}&project_id=\\\\#{project.id}\", :class=>\'btn\'  %>\r\n<% end %>\r\n<% end %>\r\n<%#link_to \"Register CRO User\", \"../Registration/user_signup?customer_id=\\\\#{customer.id}&project_id=\\\\#{project.id}\", :class=>\'btn\'  %>\r\n\r\n',NULL,NULL,NULL,'2018-09-06 09:54:08','2018-09-06 09:54:08','project_member',''),(3658,'project_protocol',1278,4,'\r\n      <h1>Protocol & Budget</h1>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"tabbable tabbable-bordered\">\r\n								<ul class=\"nav nav-tabs\">\r\n									<li class=\'\'><a href=\"#tab_br1_p\" data-toggle=\"tab\">Overview</a></li>\r\n									<li class=\"<%=\'active\' if params[:active]!=\'protocol2\'%>\"><a href=\"#tab_br2_p\" data-toggle=\"tab\">Protocols</a></li>\r\n									<li class=\"<%=\'active\' if params[:active]==\'protocol2\'%>\"><a href=\"#tab_br3_p\" data-toggle=\"tab\">Additional Costs</a></li>\r\n									<li ><a href=\"#tab_br4_p\" data-toggle=\"tab\">Fixed Costs</a></li>\r\n									<li ><a href=\"#tab_br5_p\" data-toggle=\"tab\">Remarks</a></li>\r\n						    	</ul>\r\n						    	\r\n								<div class=\"tab-content\">\r\n									<div class=\"tab-pane  \" id=\"tab_br1_p\">\r\n										<p>\r\n<h3>Overview</h3>\r\n\r\n\r\n\r\n<%\r\n    models = get_model\r\n\r\n    sheet_docs = models[:project_document].where(:document_name=>\'pl_sheet\',:project_id=>params[:id]).first\r\n    if sheet_docs\r\n    sheet = get_model(\'pl_sheet\').find sheet_docs.document_id\r\n\r\n%>\r\n<div id=\"panel\">\r\n<br/>\r\n    <table class=\"table table-bordered\" style=\"width:600px\">\r\n        <thead>\r\n        <tr>\r\n            <th colspan=\"2\" >Project profit & loss study\r\n                \r\n                <span style=\"float:right\"><%=link_to \'Edit\', \"edit?id=\\\\#{params[:id]}\", :class=>\'btn\'  %></span>\r\n                \r\n            </th>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr>\r\n            <th style=\"width:200px\">Version :</th> <td><%=sheet.version%></td>\r\n        </tr>\r\n        <tr>\r\n            <th>Project Name :</th> <td><%=sheet.name%></td>\r\n        </tr>\r\n        <tr>\r\n            <th>Project Period :</th> <td><%=sheet.period%></td>\r\n        </tr>\r\n        <tr>\r\n            <th>Number of subjects :</th> <td><%=sheet.subject%></td>\r\n        </tr>\r\n        </tbody> \r\n         <thead>\r\n        <tr>\r\n            <th colspan=\"2\" >Income</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n            <tr>\r\n            <th>Variable charged (Study/Visit) :</th> <td><%=fm sheet.income_variable%></td> \r\n            </tr>\r\n            \r\n            <tr>\r\n            <th>Fixed charged :</th> <td><%=fm sheet.income_fixed%></td> \r\n            </tr>\r\n            \r\n            <tr>\r\n            <th>Overhead :</th> <td><%=fm sheet.income_oh%></td> \r\n            </tr>\r\n        </tbody>\r\n         <thead>\r\n        <tr>\r\n            <th colspan=\"2\" >Cost of project</th>\r\n        </tr>\r\n        </thead>\r\n              <tbody>\r\n            <tr>\r\n            <th>Start up costs :</th> <td><%=fm sheet.cost_startup%></td> \r\n            </tr>\r\n            \r\n            <tr>\r\n            <th>Direct cost (Expense) :</th> <td><%=fm sheet.cost_expense%></td> \r\n            </tr>\r\n            \r\n            <tr>\r\n            <th>Direct study team costs :</th> <td><%=fm sheet.cost_study_team%></td> \r\n            </tr>\r\n            \r\n            <tr>\r\n            <th>Administrative costs :</th> <td><%=fm sheet.cost_admin%></td> \r\n            </tr>\r\n            \r\n            <tr>\r\n            <th>Facilities costs :</th> <td><%=sheet.cost_facilities%></td> \r\n            </tr>\r\n            \r\n            \r\n        </tbody>\r\n        \r\n        <thead>\r\n        <tr>\r\n            <th colspan=\"2\" >Profit (Loss) Summary</th>\r\n        </tr>\r\n        </thead>\r\n            <tbody>\r\n       \r\n            \r\n            <tr>\r\n            <th>Profit (Loos)/project 3yr:</th> <td><%=sheet.total_cost%></td> \r\n            </tr>\r\n            \r\n            <tr>\r\n            <th>Profit (Loos) (%) :</th> <td><%=0%></td> \r\n            </tr>\r\n           \r\n            <tr>\r\n            <th>Avg. per year :</th> <td><%=0%></td> \r\n            </tr>\r\n            \r\n            <tr>\r\n            <th>Return on Investment (%)/year :</th> <td><%=0%></td> \r\n            </tr>\r\n        </tbody>\r\n    </table>\r\n    \r\n</div>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n										</p>\r\n									</div>\r\n									<div class=\"tab-pane <%=\'active\' if params[:active]!=\'protocol2\'%> \" id=\"tab_br2_p\">\r\n\r\n<p>\r\n<h3>Protocols</h3>\r\n<br/>\r\n<%\r\n\r\n\r\n    \r\n    doc_sheets = models[:project_document].where(:document_name=>\'pl_sheet\',:project_id=>params[:id]).all\r\n    \r\n%>\r\n<% if true %>\r\n<ul>\r\n<table class=\"table\"> \r\n<thead>\r\n    <tr>\r\n        <th>No.</th>\r\n        <th>Version.</th>\r\n        \r\n        <th>Est Subject</th>\r\n        <th>Last updated</th>\r\n        <th>Active</th>\r\n        <th></th>\r\n    </tr>\r\n</thead>\r\n<% doc_sheets.each_with_index do |i,index| \r\n    sheet = models[:pl_sheet].find(i.document_id)\r\n    if sheet\r\n%>\r\n\r\n<tr>\r\n\r\n<td>\r\n    <%=index+1%>.\r\n</td>\r\n\r\n\r\n<td>\r\n<%=link_to \"\\\\#{sheet.version}\", \"../PlSheet/manage?id=\\\\#{sheet.id}\" %>\r\n\r\n</td>\r\n<td>\r\n    <%=sheet.subject %>\r\n</td>\r\n\r\n\r\n<td>\r\n    <%=sheet.updated_at%>\r\n</td>\r\n\r\n<%  \r\n    active = \"In Active\"\r\n    active = \'Active\' if sheet.in_active==\'true\'\r\n%>\r\n\r\n<td>\r\n    <%=\'In Active\' if sheet.in_active==\'true\'%>\r\n    <%=\'Active\' if sheet.in_active!=\'true\'%>\r\n    \r\n</td>\r\n\r\n<td>\r\n\r\n<%=link_to \"Modify\", \"../PlSheet/manage?id=\\\\#{sheet.id}\", :class=>\'btn btn-info\', :target=>\'_blank\' %>\r\n<%=link_to \"Edit\", \"../PlSheet/edit?id=\\\\#{sheet.id}\", :class=>\'btn \' %>\r\n<%=link_to  active , \"../PlSheet/activate?id=\\\\#{sheet.id}\", :class=>\'btn\', :target=>\'_blank\' %>\r\n<%=link_to \"Clone\", \"../PlSheet/clone?id=\\\\#{sheet.id}\", :class=>\'btn btn-warning\',:data=>{:confirm=>\'Are you sure?\'} %>\r\n\r\n\r\n&nbsp;&nbsp;<%=link_to \"Delete\", \"../PlSheet/destroy?id=\\\\#{sheet.id}\", :class=>\'btn btn-danger\',:data=>{:confirm=>\'Are you sure?\'} %>\r\n\r\n\r\n\r\n\r\n</td>\r\n</tr>\r\n<% end %>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n</ul>\r\n<%=link_to \"Create Protocol\",\"../PlSheet/create?pid=\\\\#{params[:id]}\", :class=>\'btn  btn-success\' %>\r\n\r\n\r\n\r\n</p>\r\n									</div>\r\n									<div class=\"tab-pane <%=\'active\' if params[:active]==\'protocol2\'%>\" id=\"tab_br3_p\">\r\n										<p>\r\n\r\n<%= form_for :protocol, :url=>\"protocol_update?project_id=\\\\#{params[:id]}\" do |f| %>\r\n\r\n<%=hidden_field_tag \"pass_through_list_id[]\", \"\" %>\r\n<%=hidden_field_tag \"reimburse_list_id[]\", \"\" %>\r\n\r\n\r\n<h3>Pass Through</h3>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n            <th>Code</th>\r\n            <th>Detail</th>\r\n            <th>Group</th>\r\n            <th>Vendor</th>\r\n            <th>Cost</th>\r\n            <th>Price</th>\r\n            <th>Note</th>\r\n            <th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody id=\"pass-through-list\">\r\n        <%\r\n      \r\n       items = models[:project_item].where(:project_id=>params[:id], :item_type=>\'1\').sort(:sort_order).all\r\n       \r\n       \r\n    \r\n    %>\r\n        <%\r\n            items.each_with_index do |i,rindex|  \r\n            \r\n             p = models[:pl_product].find(i.product_id) \r\n             if p \r\n        %>\r\n        <tr id=\"r<%=i.id%>\" class=\"c<%=i.id%>\">\r\n            <td>\r\n                <b><%=p.code%></b>\r\n                <a href=\"#\" data-toggle=\"tooltip\" title=\"\" data-original-title=\"<%=p.name%>\"><i class=\"splashy-help\"></i></a>\r\n                \r\n                <%=hidden_field_tag \"pass_through_list_itm[\\\\#{rindex}]\", i.id %>\r\n                <%=hidden_field_tag \"pass_through_list_idx[\\\\#{rindex}]\", i.product_id %>\r\n                \r\n                <%#hidden_field_tag \"pass_through_list_id[]\", i.product_id %>\r\n            </td>\r\n             <td>\r\n                <%=text_field_tag \"pass_through_e_detail[\\\\#{rindex}]\", i.detail %>\r\n            </td>\r\n             <td>\r\n                <%=p.group_code%>\r\n            </td>\r\n              <td>\r\n                <%=p.vendor_code%>\r\n            </td>\r\n             <td>\r\n                <%=p.cost%>\r\n            </td>\r\n             <td>\r\n                <%=text_field_tag \"pass_through_e_price[\\\\#{rindex}]\", i.price ,:style=>\"width:100px\"%>\r\n            </td>\r\n       \r\n                   <td>\r\n                <%=text_field_tag \"pass_through_e_note[\\\\#{rindex}]\", i.note %>\r\n            </td>\r\n            <td>\r\n                <%=link_to \"Delete\", \"#\", :id=>i.id, :class=>\'un-visit\' %>\r\n            </td>\r\n        </tr>\r\n        \r\n        <% if p.code==\'SET-CHEM\' %>\r\n             \r\n    <%\r\n        \r\n        sub_items = models[:pl_additional_product_bom].where(:project_item_id=>i.id).all\r\n     \r\n        for ix in sub_items\r\n        px = models[:pl_product].find(ix.sub_product_id)\r\n     %>\r\n     <tr class=\"vrow c<%=i.id%>\" rid=\"<%=rindex%>\">\r\n         <td>&nbsp;&nbsp; - <%=px.code%> : <%=px.name%> </td>\r\n         <td><%=px.vendor_code%></td>\r\n         <td><%=px.cost%></td>   <td><%=px.price%></td>\r\n         <td colspan=\"<%=4%>\">\r\n         </td>\r\n     </tr>\r\n    \r\n     <% end %>\r\n    \r\n       <tr class=\"vrow c<%=i.id%>\" rid=\"<%=rindex%>\">\r\n           <td>\r\n               <!--<a data-toggle=\"modal\" class=\"btn\" id=\"config_chem_btn\" data-backdrop=\"static\" href=\"#config_chem\">Configure</a>-->\r\n                \r\n                <%= link_to \'Configure\', \"javascript:config_chem(\'\\\\#{i.id}\')\"%>\r\n\r\n           </td>\r\n             <td colspan=\"6\"></td>\r\n       </tr>\r\n       \r\n         <% end %>\r\n    \r\n        <% end %>\r\n        \r\n        <%\r\n            items = models[:pl_product_bom].where(:product_id=>p.id).all\r\n            type = \'\'\r\n            for x in items\r\n            \r\n            px = models[:pl_product].find(x.sub_product_id)\r\n            if px\r\n        %>\r\n         <tr>\r\n            <td>&nbsp;&nbsp; - <%=px.code %> <%=\"(Optional)\" if x.item_type==\'OPT\' %></td><td><%=px.name %></td><td><%=px.group_code %></td><td><%=px.vendor_code %></td><td><%=px.cost %></td><td><%=px.price %></td>\r\n        </tr>\r\n        \r\n     <% end %>\r\n       \r\n     <% end %>\r\n    \r\n     <% end %>\r\n    </tbody>\r\n</table>\r\n<br/>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#addProductPassThrough\" class=\"btn\">+Item</a>\r\n<br/><br/>\r\n<hr/><br/>\r\n<script>\r\n    $(\'.un-visit\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n</script>\r\n\r\n\r\n\r\n\r\n<h3>Reimbursement</h3>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n            <th>Code</th>\r\n            <th>Detail</th>\r\n            <th>Group</th>\r\n            <th>Vendor</th>\r\n            <th>Cost</th>\r\n            <th>Price</th>\r\n            <th>Note</th>\r\n            <th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody id=\"reimburse-list\">\r\n        <%\r\n      \r\n       items = models[:project_item].where(:project_id=>params[:id], :item_type=>\'2\').sort(:sort_order).all\r\n       \r\n       \r\n    \r\n    %>\r\n        <%\r\n            for i in items \r\n            \r\n             p = models[:pl_product].find(i.product_id) \r\n             if p \r\n        %>\r\n        <tr id=\"r<%=i.id%>\">\r\n            <td>\r\n                <b><%=p.code%></b>\r\n                <%=hidden_field_tag \"reimburse_list_id[]\", i.product_id %>\r\n            </td>\r\n             <td>\r\n                <%=text_field_tag \"reimburse_list_detail[]\", i.detail %>\r\n            </td>\r\n             <td>\r\n                <%=p.group_code%>\r\n            </td>\r\n              <td>\r\n                <%=p.vendor_code%>\r\n            </td>\r\n            \r\n                       <td>\r\n                <%=p.cost%>\r\n            </td>\r\n             <td>\r\n                <%=text_field_tag \"reimburse_list_price[]\", i.price ,:style=>\"width:100px\"%>\r\n            </td>\r\n    \r\n               <td>\r\n                <%=text_field_tag \"reimburse_list_note[]\", i.note %>\r\n            </td>\r\n            <td>\r\n                <%=link_to \"Delete\", \"#\", :id=>i.id, :class=>\'un-visit\' %>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n        \r\n        \r\n        \r\n        \r\n         <%\r\n            items = models[:pl_product_bom].where(:product_id=>p.id).all\r\n            type = \'\'\r\n            for x in items\r\n            \r\n            px = models[:pl_product].find(x.sub_product_id)\r\n            if px\r\n        %>\r\n         <tr>\r\n            <td>&nbsp;&nbsp; - <%=px.code %> <%=\"(Optional)\" if x.item_type==\'OPT\' %></td><td><%=px.name %></td><td><%=px.group_code %></td><td><%=px.vendor_code %></td><td><%=px.cost %></td><td><%=px.price %></td>\r\n        </tr>\r\n        \r\n     <% end %>\r\n      <% end %>\r\n     \r\n        \r\n              <% end %>\r\n    </tbody>\r\n</table>\r\n<br/>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#addProductReimburse\" class=\"btn\">+Item</a>\r\n<br/>\r\n<br/>\r\n<script>\r\n    $(\'.un-visit\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n</script>\r\n<br/>\r\n<hr/>\r\n\r\n\r\n<%=f.submit \'Update\', :class=>\'btn btn-info\' %> | <%= link_to \'Sort\', \"project_sort_item?id=\\\\#{params[:id]}&update=additional-cost\", :data=>{:remote=>true},:class=>\'btn btn-info\' %>\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n										</p>\r\n									</div>\r\n									\r\n									<div class=\"tab-pane\" id=\"tab_br4_p\">\r\n										<p>\r\n\r\n<h3>Fixed Cost</h3>\r\n<%= form_for :protocol, :url=>\"protocol_update?project_id=\\\\#{params[:id]}\" do |f| %>\r\n<%=hidden_field_tag \"fixed_list_id[]\", \"\" %>\r\n\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr>\r\n            <th>Code</th>\r\n            <th>Detail</th>\r\n            <th>Group</th>\r\n            <th>Vendor</th>\r\n             <th>Cost</th>\r\n            <th>Price</th>\r\n    \r\n             <th>Quantity</th>\r\n            <th>Note</th>\r\n            \r\n            <th></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody id=\"fixed-list\">\r\n        <%\r\n      \r\n       items = models[:project_item].where(:project_id=>params[:id], :item_type=>\'3\').sort(:sort_order).all\r\n       \r\n       \r\n    \r\n    %>\r\n        <%\r\n            for i in items \r\n            \r\n             p = models[:pl_product].find(i.product_id) \r\n             if p \r\n        %>\r\n         <tr id=\"r<%=i.id%>\">\r\n            <td>\r\n                <b><%=p.code%></b>\r\n                <a href=\"#\" data-toggle=\"tooltip\" title=\"\" data-original-title=\"<%=p.name%>\"><i class=\"splashy-help\"></i></a>\r\n                <%=hidden_field_tag \"fixed_list_id[]\", i.product_id %>\r\n            </td>\r\n             <td>\r\n                <%=text_field_tag \"fixed_list_detail[]\", i.detail %>\r\n            </td>\r\n             <td>\r\n                <%=p.group_code%>\r\n            </td>\r\n              <td>\r\n                <%=p.gl_code%>\r\n            </td>\r\n            <td id=\"cost-<%=p.id%>\">\r\n                <%=i.price%>\r\n            </td>\r\n         \r\n             <td>\r\n                <%=text_field_tag \"fixed_list_price[]\", i.price,:style=>\"width:100px\", :pid=>p.id, :class=>\'fixed-price\' %>\r\n              \r\n            </td>\r\n          \r\n            <td>\r\n                <%=text_field_tag \"fixed_list_quantity[]\", i.quantity ,:style=>\"width:100px\"%>\r\n            </td>\r\n             <td>\r\n                <%=text_field_tag \"fixed_list_note[]\", i.note %>\r\n            </td>\r\n            \r\n            <td>\r\n                <%=link_to \"Delete\", \"#\", :id=>i.id, :class=>\'un-visit\' %>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n        \r\n              <% end %>\r\n    </tbody>\r\n</table>\r\n  <script>\r\n  $(\'.fixed-price\').keyup(function(){\r\n      \r\n      v = $(this).val();\r\n      $(\'#cost-\'+$(this).attr(\'pid\')).html(v)\r\n\r\n\r\n      \r\n      \r\n  })\r\n  </script>\r\n<br/>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#addProductFixed\" id=\"fixed_cost_btn\" class=\"btn\">+Item</a>\r\n\r\n<script>\r\n    $(\'.un-visit\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n        \r\n    $(\'#fixed_cost_btn\').click(function(){\r\n        $(\'#fixed-search-btn\').click();\r\n    })    \r\n</script>\r\n<br/>\r\n<hr/>\r\n\r\n\r\n<%=f.submit \'Update\', :class=>\'btn btn-info\' %>  | <%= link_to \'Sort\', \"project_sort_item?id=\\\\#{params[:id]}&update=additional-cost\", :data=>{:remote=>true},:class=>\'btn btn-info\' %>\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n										</p>\r\n									</div>									\r\n\r\n<div class=\"tab-pane\" id=\"tab_br5_p\">\r\n    <p>\r\n	<%\r\n	    project = models[:project].find(params[:id])\r\n	%>\r\n	<h1>Remark</h1>\r\n	<%# project.id %>\r\n<pre class=\"remark-panel\" id=\"remark-panel\" style=\"width:100%;overflow:auto\">\r\n<%=project.remark1.html_safe if project.remark1%>	  \r\n</pre>\r\n<%=link_to \"Edit\",\"#\", :id=>\'remark-editor-open\',:class=>\'remark-panel\' %>\r\n\r\n\r\n\r\n<div id=\"remark-editor\" style=\"display:none\">\r\n	<%=form_for :remark, :url=>\"remark?id=\\\\#{params[:id]}&update=remark-panel\",:data=>{:remote=>true} do |f| %>\r\n	<%= text_field_tag :remark1_editor, project.remark1 %><br/>\r\n	<%=f.submit \'Update\',:class=>\'btn btn-info\' %> | <%=link_to \'Cancel\', \"#\",:id=>\'remark-editor-close\' %>\r\n	<% end %>\r\n	\r\n</div>	\r\n	\r\n<script>\r\n	    \r\n$(\'#remark-editor-open\').click(function(){\r\n    \r\n      $(\'#remark-editor\').show();\r\n      $(\'.remark-panel\').hide();\r\n      \r\n})\r\n$(\'#remark-editor-close\').click(function(){\r\n    \r\n      $(\'#remark-editor\').hide();\r\n      $(\'.remark-panel\').show();\r\n      \r\n})\r\n\r\n$(document).ready(function(){\r\n \r\n  $(\"#remark1_editor\").kendoEditor({\r\n			encoded:false,\r\n			change: function(){\r\n	\r\n			},	resizable: {\r\n				    min: 100,\r\n				    toolbar:true\r\n				    \r\n				  },\r\n            tools: [\r\n                 \"fontName\",\r\n			 	 \"bold\",\r\n			     \"italic\",\r\n			     \"underline\",\r\n			     \"strikethrough\",\r\n			     \"fontSize\",\r\n			     \"foreColor\",\r\n			     \"insertImage\",\r\n			     {\r\n                   name: \"viewHtml\",\r\n                	tooltip: \"View HTML\",\r\n                	exec: function(e) {\r\n	\r\n                    var editor = $(this).data(\"kendoEditor\");\r\n                    var dialog = $($(\"#viewHtml-template\").html())\r\n                        .find(\"textarea\").val(editor.value()).end()\r\n                        .find(\".viewHtml-update\")\r\n                            .click(function() {\r\n                                editor.value(dialog.element.find(\"textarea\").val());\r\n                                dialog.close();\r\n                            })\r\n                        .end()\r\n                        .find(\".viewHtml-cancel\")\r\n                            .click(function() {\r\n                                dialog.close();\r\n                            })\r\n                        .end()\r\n                        .kendoWindow({\r\n                            modal: true,\r\n                            title: \"View HTML\",\r\n                            deactivate: function() {\r\n                                dialog.destroy();\r\n                            }\r\n                        }).data(\"kendoWindow\");\r\n\r\n                    dialog.center().open();\r\n                }\r\n            }\r\n            ]\r\n        });\r\n	  // $(\"#data-project_description\").show();	\r\n\r\n});\r\n	    \r\n	    \r\n	    \r\n	</script>\r\n	</p>\r\n</div>\r\n								\r\n								</div>\r\n								\r\n\r\n								\r\n								\r\n								\r\n							</div>\r\n							\r\n							\r\n\r\n\r\n\r\n\r\n<div class=\"modal hide\" id=\"addProductPassThrough\" aria-hidden=\"true\" style=\"display: none;\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Pass Through Item</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n\r\n<%= form_for :query, :url=>\"../PlProduct/product_search?update=search_result_1&list=pass-through-list\", :data=>{:remote=>true},:id=>\'pass-form\' do |f| %>\r\nSearch <%= f.text_field :q, :id=>\'pass-search\'%>\r\n<%= f.submit \'Search\', :id=>\'pass-search-btn\' %>\r\n<% end %>\r\n\r\n<script>\r\n    \r\n    $(\'#pass-search\').keyup(function(){\r\n        v = $(this).val()\r\n        if(v.length>0){\r\n            $(\'#pass-search-btn\').click();\r\n        }\r\n    })\r\n    \r\n</script>\r\n								\r\n<div id=\"search_result_1\">\r\n    \r\n</div>\r\n\r\n\r\n	</div>\r\n	<div class=\"modal-footer\">\r\n		<a href=\"#\" class=\"btn btn-info select-btn\" data-dismiss=\"modal\"  >Select</a>\r\n		<a href=\"#\" class=\"btn\" data-dismiss=\"modal\" id=\"close-pass_through_list\">Close</a>\r\n	</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"modal hide\" id=\"addProductReimburse\" aria-hidden=\"true\" style=\"display: none;\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Reimbursement Item</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n\r\n<%= form_for :query, :url=>\"../PlProduct/product_search?update=search_result_2&list=reimburse-list\", :data=>{:remote=>true} do |f| %>\r\nSearch <%= f.text_field :q, :id=>\'reim-search\'%>\r\n<%= f.submit \'Search\',:id=>\'reim-search-btn\' %>\r\n<% end %>\r\n\r\n<script>\r\n    \r\n    $(\'#reim-search\').keyup(function(){\r\n        v = $(this).val()\r\n        if(v.length>0){\r\n            $(\'#reim-search-btn\').click();\r\n        }\r\n    })\r\n    \r\n</script>								\r\n<div id=\"search_result_2\">\r\n    \r\n</div>\r\n\r\n\r\n	</div>\r\n	<div class=\"modal-footer\">\r\n			<a href=\"#\" class=\"btn btn-info select-btn\" data-dismiss=\"modal\"  >Select</a>\r\n\r\n\r\n		<a href=\"#\" class=\"btn\" data-dismiss=\"modal\" id=\"close-reimburse_list\">Close</a>\r\n	</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"modal hide\" id=\"addProductFixed\" aria-hidden=\"true\" style=\"display: none;\">\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Fixed Cost Item</h3>\r\n								</div>\r\n								<div class=\"modal-body\">\r\n<%= form_for :query, :url=>\"../PlProduct/product_search?update=search_result_3&list=fixed-list\", :data=>{:remote=>true} do |f| %>\r\nSearch <%= f.text_field :q , :id=>\'fixed-search\'%>\r\n<%= f.submit \'Search\',:id=>\'fixed-search-btn\' %>\r\n<% end %>\r\n\r\n<script>\r\n    \r\n    $(\'#fixed-search\').keyup(function(){\r\n        v = $(this).val()\r\n        if(v.length>0){\r\n            $(\'#fixed-search-btn\').click();\r\n        }\r\n    })\r\n    \r\n</script>									\r\n<div id=\"search_result_3\">\r\n    \r\n</div>\r\n\r\n\r\n	</div>\r\n	<div class=\"modal-footer\">\r\n		<a href=\"#\" class=\"btn btn-info select-btn\" data-dismiss=\"modal\"  >Select</a>\r\n        <a href=\"#\" class=\"btn\" data-dismiss=\"modal\" id=\"close-fixed_list\">Close</a>\r\n	</div>\r\n</div>\r\n\r\n<div class=\"modal hide fade\" id=\"config_chem\" aria-hidden=\"false\" style=\"display: block;\">\r\n<div class=\"modal-dialog modal-lg\" id=\"config_chem_content\">\r\n...	\r\n				\r\n</div>\r\n</div>\r\n\r\n<script>\r\n\r\n\r\n     function config_chem(rindex){\r\n$.ajax({\r\n  url: \"chem_config?id=<%=params[:id]%>&idx=\"+rindex,\r\n  context: document.body\r\n}).done(function(data) {\r\n\r\n  $(\'#config_chem_content\' ).html(data);\r\n   $(\'#config_chem\').modal(\'show\')\r\n});\r\n           \r\n   \r\n           \r\n           \r\n    }\r\n    \r\n    $(\'.select-btn\').click(function(){\r\n                $(\'.item:checked\').each(function(){\r\n                \r\n                ids = $(this).attr(\'id\').split(\"_\");\r\n                func = ids[0];\r\n                id = ids[1];\r\n                \r\n                eval(\'selectProduct\'+func+\'(\"\'+id+\'\")\');\r\n                \r\n                \r\n            })    \r\n                \r\n                \r\n    })\r\n$(\'[data-toggle=\"tooltip\"]\').tooltip()\r\n</script>',NULL,NULL,NULL,'2018-09-06 10:12:56','2018-09-06 10:12:56','project_protocol',''),(3659,'project_term',1278,4,'<h1>Screening &amp; Payment</h1>',NULL,NULL,NULL,'2018-09-06 10:13:29','2018-09-06 10:13:29','project_term',''),(3660,'context_menu',1332,4,'<div id=\"context_menu\">\r\n    \r\n</div>\r\n<script>\r\n$.ajax({\r\n  url: \"../Home/global_menu\",\r\n  context: document.body\r\n}).done(function(data) {\r\n  $( \'#context_menu\' ).html(data);\r\