inate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">List of <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-quantity_capsule_4\"></i> Summary\'.html_safe,\"../IpItem/summary\",:class=>\'btn btn-mini\' %>\r\n\r\n\r\n<%= link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe,\"../IpLog/create\",:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'index\' do |f| %>\r\n<div>\r\nFrom : \r\n<%= f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\nTo : \r\n<%= f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.list.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%= link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, \"../IpLog/create\",:class=>\'btn btn-small\' %>\r\n<%= link_to \'History\'.html_safe, \"../IpLog/index\",:class=>\'btn btn-small\' %>\r\n\r\n\r\n<%= link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2018-09-06 17:22:23','2018-09-06 17:22:23','index',''),(3666,'form',1433,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n   @record.user = @current_user.login\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n',NULL,NULL,NULL,'2018-09-06 17:23:25','2018-09-06 17:23:25','',''),(3667,'create',1433,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<% link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    models = get_model \r\n    \r\n    # exist_item = models[:ip_item].where(:project_id=>record.project_id, :barcode=>record.barcode).first\r\n    \r\n    il_item = get_model(\'ip_item\').create :project_id=>record.project_id, :name=>record.name, :barcode=> record.barcode,:comment=>record.comment\r\n    \r\n    \r\n    il_item_card = get_model(\'ip_card\').create :status=>\'in\', :item_id=>il_item.id, :lot=>record.lot, :expired_date=>record.exp, :quantity=>record.quantity\r\n    \r\n    \r\n    record.update_attributes :ip_item_id=>il_item.id\r\n\r\n\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n    \r\n    return_url = \"../IpItem/index\"\r\n    \r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"<%= return_url.html_safe %>\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-09-06 17:24:24','2018-09-06 17:24:24','create',''),(3668,'context_menu',1433,4,'<div id=\"context_menu\">\r\n    \r\n</div>\r\n<script>\r\n$.ajax({\r\n  url: \"../Home/global_menu\",\r\n  context: document.body\r\n}).done(function(data) {\r\n  $( \'#context_menu\' ).html(data);\r\n});\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-09-06 17:35:05','2018-09-06 17:35:05','context_menu',''),(3669,'list',1432,3,'<%\r\n   model = get_model(this.table_name)\r\n   records = []\r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   \r\n    if params[:search]\r\n        records = model.all(params[:search][:criteria])\r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n       records = model.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n    end\r\n    \r\n    models = get_model\r\n    \r\n    pmap = {}\r\n    \r\n    unprojects = records.collect{|i| i if i.project_id == nil}.compact \r\n    \r\n    moved_out =  records.collect{|i| i if i.status == \'99\'}.compact \r\n    \r\n    projects = models[:project].find records.collect{|i| i.project_id}\r\n    \r\n    for i in records\r\n        if i.status!=\'99\'\r\n        pmap[i.project_id] = [] unless pmap[i.project_id]\r\n        pmap[i.project_id] << i\r\n        end\r\n    end\r\n    \r\n    \r\n     moved_pmap = {}\r\n    \r\n    for i in moved_out\r\n    \r\n        moved_pmap[i.project_id] = [] unless moved_pmap[i.project_id]\r\n        moved_pmap[i.project_id] << i\r\n    \r\n    end\r\n%>\r\n<div class=\"tabbable\">\r\n	<ul class=\"nav nav-tabs\">\r\n		<li class=\"active\"><a href=\"#tab0\" data-toggle=\"tab\">Active</a></li>\r\n		<li class=\"\"><a href=\"#tab1\" data-toggle=\"tab\">Moved Out</a></li>\r\n		<li><a href=\"#tab3\" data-toggle=\"tab\">Un Mapped</a></li>\r\n	</ul>\r\n		<div class=\"tab-content\">\r\n	\r\n	\r\n<%\r\n    [pmap, moved_pmap].each_with_index do |x,xindex|\r\n    \r\n    projects = models[:project].find x.keys\r\n\r\n\r\n    pmap = x\r\n\r\n%>\r\n	\r\n		<div class=\"tab-pane <%=\'active\' if xindex==0 %>\" id=\"tab<%=xindex%>\">\r\n			<p>\r\n\r\n<table class=\"table\">\r\n    \r\n    <% for i in projects %>\r\n    <thead>\r\n    <tr>\r\n        \r\n    <th>\r\n        <%= i.protocol_no %>\r\n    </th>  \r\n\r\n    <th>\r\n        Lot\r\n    </th>\r\n    <th>\r\n        Expired\r\n    </th>\r\n    <th>\r\n        Day until exp\r\n    </th>\r\n    <th>\r\n        รวม\r\n    </th>\r\n      <th>\r\n        จำนวนที่ใช้ไป\r\n    </th>\r\n    <th>\r\n        คงเหลือ\r\n    </th>\r\n    <th>\r\n       จำนวนที่ใช้ได้(หักexpออก)\r\n    </th>\r\n    <th>\r\n        จำนวนรวมที่ใช้ได้\r\n    </th>\r\n    <th>\r\n        จำนวนรวมที่ใช้ไป\r\n    </th>\r\n    \r\n    <th>\r\n        Min\r\n    </th>\r\n\r\n    <th>\r\n        Status\r\n    </th>\r\n      <th>\r\n        Comment \r\n    </th>\r\n    <th>\r\n        \r\n    </th>    \r\n    </tr>\r\n    </thead>\r\n    <tbody>\r\n    <%\r\n    \r\n    \r\n    \r\n        now = Time.now \r\n        \r\n    if pmap[i.id]\r\n        \r\n        for j in pmap[i.id]\r\n        \r\n        \r\n        list = models[:ip_card].where(:item_id=>j.id).all\r\n        map = {}\r\n        \r\n        for k in list\r\n        \r\n            map[k.lot] = [] unless map[k.lot]\r\n            \r\n            map[k.lot] << k\r\n        \r\n        end\r\n      \r\n      \r\n      \r\n        storage=\"\"\r\n#         1|2-8C\r\n# 2|15-25C\r\n# 3|-20C\r\n# 4|-60C\r\nif j.storage_condition\r\n        storage =  {\'1\'=>\'2-8C&#176;\',\'2\'=>\'15-25C&#176;\',\'3\'=>\'-20C&#176;\',\'4\'=>\'-60C&#176;\'}[j.storage_condition] \r\n        storage = \"<span style=\'color:green\'>\\\\#{storage}<span>\".html_safe\r\n    end\r\n      \r\n      %>\r\n        <tr>\r\n        <td style=\"vertical-align:middle\" >\r\n            <%=link_to j.name, \"show?id=\\\\#{j.id}\" %> <%=storage%>    \r\n        </td>\r\n        \r\n        <td> \r\n        \r\n        <%=link_to \'+ Lot\', \"../IpCard/create?record[item_id]=\\\\#{j.id}\", :class=>\'btn btn-mini btn-success\' if j.status!=\'99\'%>  \r\n        Date Out : <span style=\"color:red\"><%=j.date_out.strftime(\"%d/%m/%Y\") if j.status==\'99\'%>  </span>\r\n\r\n\r\n        </td>\r\n        <td colspan=\"11\">\r\n            \r\n        </td>\r\n        <td>\r\n             <%=link_to \'Edit\', \"../IpItem/edit?id=\\\\#{j.id}\", :class=>\'btn btn-mini\'%>  \r\n            <%=link_to \'Del\', \"../IpItem/destroy?id=\\\\#{j.id}\", :class=>\'btn btn-danger btn-mini\', :data=>{:confirm=>\'Are you sure?\'} %>     \r\n        </td>\r\n        </tr>  \r\n    <%\r\n    \r\n    \r\n        total_usable = 0 \r\n        total_usage = 0 \r\n        adj_one_month = 0 \r\n    \r\n        map.each_pair do |k,v| \r\n            \r\n        balance = 0 \r\n        total = 0 \r\n        usage = 0 \r\n        usable = 0 \r\n        expired = nil\r\n        \r\n        for x in v\r\n        \r\n            if x.status==\'in\'\r\n                total += x.quantity if x.quantity\r\n                balance+= x.quantity if x.quantity\r\n            end\r\n            \r\n            if x.status==\'out\'\r\n                usage += x.quantity if x.quantity\r\n                balance-= x.quantity if x.quantity\r\n            end\r\n            \r\n            expired = x.expired_date if x.expired_date    \r\n        \r\n            \r\n        \r\n        end\r\n        \r\n        \r\n        usable = balance\r\n        \r\n         if expired\r\n        \r\n        if   now > expired \r\n           \r\n           usable = 0 \r\n            \r\n        end\r\n        \r\n        if now > expired.to_datetime-30\r\n        \r\n            adj_one_month += usable\r\n        \r\n        end\r\n    end\r\n  \r\n        \r\n        total_usable += usable if usable\r\n        total_usage += usage if usage\r\n        \r\n        end\r\n        \r\n        status = \'\'\r\n        \r\n        \r\n        if j.minimum and  total_usable-adj_one_month < j.minimum\r\n            status = \'NEAR EXP\'\r\n        end\r\n        \r\n        \r\n        if j.minimum and  total_usable < j.minimum\r\n            status = \'ALERT\'\r\n        end\r\n        \r\n        \r\n        \r\n        \r\n        \r\n        tag = nil\r\n        map = {} if j.status==\'99\'\r\n        map.each_pair do |k,v| \r\n            \r\n        balance = 0 \r\n        total = 0 \r\n        usage = 0 \r\n        usable = 0 \r\n        expired = nil\r\n        \r\n        for x in v\r\n        \r\n            if x.status==\'in\'\r\n                total += x.quantity if x.quantity\r\n                balance+= x.quantity if x.quantity\r\n            end\r\n            \r\n            if x.status==\'out\'\r\n                usage += x.quantity if x.quantity\r\n                balance-= x.quantity if x.quantity\r\n            end\r\n            \r\n            expired = x.expired_date if x.expired_date    \r\n        \r\n        end\r\n        \r\n        usable = balance\r\n            \r\n    %>\r\n    <tr> \r\n             <% unless tag %>\r\n        <th rowspan=\"<%=map.keys.size %>\" style=\"vertical-align:middle;\">\r\n            \r\n           <!--<%=j.name%>  <%=link_to \'Edit\', \"../IpItem/edit?id=\\\\#{j.id}\", :class=>\'btn btn-mini\'%>    <%=link_to \'Del\', \"../IpItem/destroy?id=\\\\#{j.id}\", :class=>\'btn btn-danger btn-mini\', :data=>{:confirm=>\'Are you sure?\'} %> -->\r\n        </th>\r\n             <% end %>\r\n    \r\n        <td>\r\n            <%=k%>     \r\n        </td>\r\n        \r\n            <% if expired %>\r\n            <% if expired > Time.now %>\r\n            <td><%=expired.strftime(\"%d-%b-%y\")%></td><td><%= distance_of_time_in_words now, expired.to_datetime if expired%> </td>\r\n            <% else\r\n            \r\n                usable = 0 \r\n                \r\n            %>\r\n            <td><span class=\" alert-danger\"><%=expired.strftime(\"%d-%b-%y\")%></span></td><td><span class=\" alert-danger\">Expired</span></td>\r\n            <% end %>\r\n            <% else %>\r\n            <span class=\"alert alert-warning\">No Date</span>\r\n            <% end %>\r\n        </td>\r\n           <td>\r\n           <%= total %>\r\n        </td>\r\n       \r\n        <td>\r\n           <%= usage %> <%=link_to \'+\', \"../IpCard/create?record[item_id]=\\\\#{j.id}&record[lot]=\\\\#{k}&record[status]=out\", :class=>\'btn btn-mini btn-info\' if j.status!=\'99\'%>  \r\n\r\n\r\n        </td>\r\n         <td>\r\n           <%= balance %>\r\n        </td>\r\n        <td>\r\n           <%= usable %>\r\n        </td>\r\n        \r\n        <% unless tag %>\r\n        \r\n        <td rowspan=\"<%=map.keys.size%>\" style=\"vertical-align:middle;\">\r\n            <span class=\" alert-info\" style=\"padding:5px\"><b><%=total_usable%></b></span>\r\n        </td>\r\n        \r\n        <td rowspan=\"<%=map.keys.size%>\" style=\"vertical-align:middle;\">\r\n            <%=total_usage%>\r\n        </td>\r\n        \r\n        <td rowspan=\"<%=map.keys.size%>\" style=\"vertical-align:middle;\">\r\n            <%=j.minimum%>\r\n        </td>\r\n        \r\n  \r\n        \r\n        \r\n     \r\n        <%\r\n        \r\n         sclass=\"\"\r\n         sclass=\"alert alert-warning\" if status==\'NEAR EXP\'\r\n\r\n\r\n         sclass=\"alert alert-danger\" if status==\'ALERT\'\r\n         \r\n        %>\r\n          \r\n        <td  colspan=\"2\" rowspan=\"<%=map.keys.size%>\"  style=\"vertical-align:middle;\">\r\n            <span class=\"<%=sclass%>\"><%=status%></span>\r\n        </td>\r\n        \r\n          \r\n        <td rowspan=\"<%=map.keys.size%>\" style=\"vertical-align:middle;\">\r\n            <%=j.comment %>\r\n        </td>\r\n        \r\n        \r\n        <% \r\n        \r\n              tag = true\r\n        end %>\r\n        \r\n        \r\n    </tr>\r\n    		<% end %>\r\n     <% \r\n     \r\n\r\n      \r\n     end %>\r\n    <% end %>\r\n</tbody>\r\n    \r\n    <% end %>\r\n    \r\n</table>\r\n	</p>\r\n		</div>\r\n		\r\n		<% end %>\r\n\r\n\r\n\r\n		<div class=\"tab-pane\" id=\"tab3\">\r\n			<p>\r\n\r\n\r\n\r\n<% if unprojects.size > 0  %>\r\n<h3>Un Project </h3>\r\n<table class=\"table\">\r\n<% for i in  unprojects %>\r\n<tr>\r\n    <td><%=i.project_name if i%></td>   <td><%=i.name %></td>   <td><%=link_to \'Edit\', \"edit?id=\\\\#{i.id}\" %></td>\r\n</tr>\r\n<% end %>\r\n</table>\r\n<% end %>\r\n\r\n\r\n			</p>\r\n		</div>\r\n	</div>\r\n</div>\r\n\r\n\r\n',NULL,NULL,NULL,'2018-09-06 17:43:52','2018-09-06 17:43:52','list',''),(3670,'destroy',1434,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  @record.update_attributes :status=>\'0\', :provider_type=>\'-1\'\r\n  @record.destroy \r\n\r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=index\">',NULL,NULL,NULL,'2018-09-10 01:17:01','2018-09-10 01:17:01','destroy',''),(3671,'document_name',1435,1,'\'sigmoid\'',NULL,NULL,NULL,'2018-09-14 06:25:44','2018-09-14 06:25:44',NULL,NULL),(3672,'document_name',1436,1,'\'appointment\'',NULL,NULL,NULL,'2018-09-17 04:37:42','2018-09-17 04:37:42',NULL,NULL),(3674,'document_name',1437,1,'\'project_item\'',NULL,NULL,NULL,'2018-09-18 14:22:08','2018-09-18 14:22:08',NULL,NULL),(3675,'product_search',1325,3,'<%\r\n    models = get_model\r\n    if params[:query]\r\n    \r\n    products = []    \r\n    \r\n    if params[:query][:q] !=\"\"\r\n    query = /\\\\#{params[:query][:q]}/i\r\n    products = models[:pl_product].where(\'$or\'=>[{:name=>query},{:code=>query}]).all :limit=>100\r\n    \r\n    else\r\n    \r\n    \r\n    if params[:id]\r\n    \r\n    project = models[:project].find params[:id]\r\n    \r\n    product_items = models[:project_item].where(:project_id=>project.id).all\r\n    \r\n    products = models[:pl_product].find product_items.collect{|i| i.product_id }\r\n    \r\n    else\r\n    \r\n    products = models[:pl_product].where(\'$or\'=>[{:code=>/STU-/i},{:code=>/FIX-/i}]).all  \r\n\r\n\r\n    \r\n    end\r\n    \r\n       \r\n    # products = []    \r\n        \r\n    end\r\n    \r\n    pmap ={}\r\n    for i in products\r\n        pmap[i.id] = i\r\n    end\r\n    \r\n    pre = \'\'\r\n    func = \'\'\r\n    callback= \'\'\r\n    if params[:list]\r\n    \r\n    pre = params[:list].split(\"-\").join(\"_\")\r\n    func = pre.camelize\r\n    \r\n    end\r\n    \r\n    if params[:sheet_id] \r\n        sheet = models[:pl_sheet].find(params[:sheet_id])\r\n        doc = models[:project_document].where(:document_id=>sheet.id).first\r\n    end\r\n    \r\n%>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr><th>#</th>\r\n           <th>Code</th>\r\n            <th>Detail</th>\r\n            <th>Group</th>\r\n             <th>Vendor</th>\r\n            <th>Cost</th>\r\n            <th>Price</th>\r\n           \r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <% for i in products \r\n        \r\n            detail = i.name\r\n            price = i.price\r\n            cost = i.cost\r\n            \r\n       \r\n            if sheet      \r\n                \r\n            # schedule item    \r\n            # item = models[:pl_period_product].where(:sheet_id=>sheet.id, :product_id=>i.id).first   \r\n            \r\n            # only item\r\n            item = models[:project_item].where(:project_id=>doc.project_id,:product_id=>i.id).first unless item\r\n             \r\n             \r\n             \r\n            if item\r\n                \r\n                detail = item.detail\r\n                price = item.price\r\n                # cost = item.cost \r\n                \r\n            end\r\n            \r\n         end\r\n        %>\r\n        \r\n        <%\r\n        unless params[:callback]\r\n            callback = \"selectProduct\\\\#{func}(\'\\\\#{i.id}\')\"\r\n        end\r\n            callback = \"\\\\#{params[:callback]}(\'\\\\#{i.id}\')\" if params[:callback]\r\n        \r\n        cls = \"\"\r\n        if item \r\n            cls = \'alert-success\' \r\n            cls = \'alert-info\' if item.class.to_s.index(\"Schema::ProjectItem\") and item.item_type==\'1\'  #blue addtional\r\n            cls = \'alert-danger\' if item.class.to_s.index(\"Schema::ProjectItem\") and item.item_type==\'2\' #reimburse\r\n            \r\n            \r\n        end\r\n        \r\n        \r\n        \r\n        %>\r\n        <tr class=\"<%=cls if item%>\">\r\n        <td><%=check_box_tag  \"\\\\#{func}_\\\\#{i.id}\",\'true\',false, :class=>\'item\' %></td>\r\n        <td><%=i.code %><td>\r\n            <%=link_to detail, \"javascript:\\\\#{callback}\" %>\r\n        </td>\r\n            \r\n            <td><%=i.group_code %></td> <td><%=i.vendor_code %></td><td><%=cost %></td><td><%= price %></td>\r\n            \r\n        </tr>\r\n        <% end %>\r\n    </tbody>\r\n</table>\r\n<% unless params[:callback] %>\r\n<div id=\"template-x\" style=\"display:none\">\r\n <table>\r\n        <tbody>\r\n    <tr>\r\n    <td class=\"code\" style=\"font-weight: bold;\">\r\n        code\r\n    </td>\r\n    <td >\r\n        <%=hidden_field_tag \"id\", \'\', :class=>\'field-x record\' %>\r\n\r\n        <%=text_field_tag \"detail\", \'\', :class=>\'field-x detail\' %>\r\n    </td>\r\n    <td class=\"group_code\">\r\n        group_code\r\n    </td>\r\n    <td class=\"vendor_code\">\r\n        -\r\n    </td>\r\n    <td class=\"cost\">\r\n        cost\r\n    </td>\r\n    <td >\r\n        <%=text_field_tag \"price\",\'\',  :class=>\'field-x price\' ,:style=>\"width:100px\" %>\r\n    </td>\r\n\r\n    <%\r\n    if pre==\'fixed_list\'\r\n    %>\r\n    \r\n    <td >\r\n        <%=text_field_tag \"quantity\",\'\',  :class=>\'field-x quantity\',:style=>\"width:100px\" %>\r\n    </td>\r\n    \r\n    <% end %>\r\n    <td >\r\n        <%=text_field_tag \"note\", \'\', :class=>\'field-x note\' %>\r\n    </td>\r\n    <td class=\"delete\">\r\n        <%=link_to \"Delete\", \"#\", :class=>\'del-x\' %>\r\n    </td>\r\n\r\n\r\n    \r\n    </tr>\r\n    </tbody>\r\n        \r\n    </table>\r\n    \r\n</div>\r\n\r\n\r\n<script>\r\n    \r\n    var list_<%=pre%> = <%=pmap.to_json.html_safe%>;\r\n    \r\n    function selectProduct<%=func%>(pid){\r\n        p = list_<%=pre%>[pid];\r\n        pre = \'<%=pre%>\'\r\n        console.log(p)\r\n        template = $(\'#template-x\').clone()\r\n        \r\n        template.find(\'.code\').html(p[\'code\'])\r\n        template.find(\'.vendor_code\').html(p[\'vendor_code\'])\r\n\r\n        template.find(\'.group_code\').html(p[\'group_code\'])\r\n\r\n\r\n                \r\n        template.find(\'.field-x\').each(function(){\r\n            \r\n            $(this).attr(\"name\",  pre+\"_\"+$(this).attr(\"name\")+\"[]\" ) \r\n            \r\n        })\r\n       \r\n        template.find(\'.record\').attr(\"value\",p[\'id\'])\r\n\r\n\r\n        template.find(\'.detail\').attr(\"value\",p[\'name\'])\r\n       \r\n        template.find(\'.price\').attr(\"value\",p[\'price\'])\r\n        template.find(\'.cost\').html(p[\'cost\'])\r\n        \r\n        <% if params[:list] ==\'fixed-list\' %>\r\n        template.find(\'.price\').attr(\'pid\', p[\'id\'])\r\n        template.find(\'.cost\').attr(\'id\', \"cost-\"+p[\'id\'])\r\n        \r\n        template.find(\'.price\').keyup(function(){\r\n              \r\n             v =  $(this).val();\r\n             $(\'#cost-\'+$(this).attr(\'pid\')).html(v)\r\n             \r\n              \r\n          })\r\n        \r\n        <% end %>\r\n        \r\n        template.find(\'.del-x\').attr(\"id\",p[\'id\'])\r\n        template.find(\'.del-x\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n        \r\n        \r\n        \r\n\r\n        \r\n        template.find(\'tr\').each(function(){\r\n            $(this).attr(\"id\", \"r\"+p[\'id\'])\r\n            $(\'#<%=params[:list]%>\').append($(this))\r\n        })\r\n        \r\n        // template = []\r\n        // template.push(\"<td>\"+p[\'code\']+\"<input type=\'hidden\' name=\'\"+pre+\"_product_id[]\' value=\'\"+p[\'id\']+\"\'>\"+\"</td>\")\r\n        // template.push(\"<td>\"+p[\'name\']+\"</td>\")\r\n        // template.push(\"<td>\"+p[\'group_code\']+\"</td>\")\r\n        // template.push(\"<td><input type=\'text\' name=\'un-visit-note[]\' value=\'\'>\"+\"</td>\")\r\n        // template.push(\"<td><a href=\'#\' id=\'\"+p[\'id\']+\"\'>Delete</a</td>\")\r\n        \r\n        \r\n        // $(\'#<%=params[:list]%>\').append(\"<tr id=\'r\"+p[\'id\']+\"\'>\"+template.join()+\"</tr>\");\r\n        \r\n        // $(\'#\'+p[\'id\']).click(function(){\r\n        //     id = $(this).attr(\'id\')\r\n        //     $(\'#r\'+id).remove()\r\n        //     return false\r\n        // })\r\n        // $(\'#close-\'+pre).click();\r\n        \r\n        \r\n        // $(\'#search_result\').html(\'\')\r\n    }\r\n    \r\n    \r\n</script>\r\n<% end %>\r\n\r\n<% end %>',NULL,NULL,NULL,'2018-09-18 15:01:19','2018-09-18 15:01:19','product_search',''),(3676,'protocol_update',1278,3,'<%\r\n\r\n    models = get_model\r\n    project = models[:project].find params[:project_id] \r\n\r\n   if request.post?\r\n       \r\n       \r\n   if params[:pass_through_list_id ]\r\n \r\n     \r\n      if params[:pass_through_list_itm]\r\n     \r\n      items = models[:project_item].where(:project_id=>project.id, :item_type=>\'1\').all\r\n       mark = {}   \r\n      \r\n     \r\n       params[:pass_through_list_itm].each_pair do |k,it|\r\n          \r\n          mark[it] = k\r\n          \r\n       end\r\n       \r\n        items.each do |i| \r\n        \r\n            if j = mark[i.id.to_s]\r\n                \r\n                obj = {}\r\n                obj[\'detail\'] = params[:pass_through_e_detail][j]\r\n                obj[\'price\'] = params[:pass_through_e_price][j]\r\n                obj[\'note\'] = params[:pass_through_e_note][j]\r\n\r\n                i.update_attributes obj\r\n            \r\n            else\r\n                i.destroy\r\n                \r\n            end\r\n            \r\n        end\r\n       \r\n    end\r\n          \r\n          \r\n       params[:pass_through_list_id].each_with_index do |i,index|\r\n           idx = index-1\r\n          if i.size>0\r\n           obj = { :item_type=>\'1\', :project_id=>project.id, :product_id=>i}\r\n           \r\n           obj[\'detail\'] = params[:pass_through_list_detail][idx]\r\n           obj[\'price\'] = params[:pass_through_list_price][idx]\r\n           obj[\'note\'] = params[:pass_through_list_note][idx]\r\n           \r\n           record = models[:project_item].create obj\r\n        end\r\n           \r\n       end\r\n   \r\n   end\r\n   \r\n   \r\n    if params[:reimburse_list_id ]\r\n    \r\n     \r\n      items = models[:project_item].where(:project_id=>project.id, :item_type=>\'2\').all\r\n      items.each do |i| i.destroy\r\n      end            \r\n          \r\n       params[:reimburse_list_id].each_with_index do |i,index|\r\n           idx = index -1 \r\n           if i.size>0\r\n           obj = { :item_type=>\'2\', :project_id=>project.id , :product_id=>i}\r\n           \r\n           obj[\'detail\'] = params[:reimburse_list_detail][idx]\r\n           obj[\'price\'] = params[:reimburse_list_price][idx]\r\n           obj[\'note\'] = params[:reimburse_list_note][idx]\r\n           \r\n           record = models[:project_item].create obj\r\n      end\r\n           \r\n       end\r\n   \r\n   end\r\n   \r\n      if params[:fixed_list_id ]\r\n    \r\n     \r\n      items = models[:project_item].where(:project_id=>project.id, :item_type=>\'3\').all\r\n      items.each do |i| i.destroy\r\n      end            \r\n          \r\n       params[:fixed_list_id].each_with_index do |i,index|\r\n           idx = index -1 \r\n           if i.size>0\r\n           obj = { :item_type=>\'3\', :project_id=>project.id, :product_id=>i }\r\n           \r\n           obj[\'detail\'] = params[:fixed_list_detail][idx]\r\n           obj[\'price\'] = params[:fixed_list_price][idx]\r\n           obj[\'note\'] = params[:fixed_list_note][idx]\r\n           obj[\'quantity\'] = params[:fixed_list_quantity][idx]\r\n           \r\n           \r\n\r\n           record = models[:project_item].create obj\r\n            end\r\n           \r\n       end\r\n   \r\n   end\r\n   \r\n   \r\n   end\r\n   \r\n%>\r\n<h3>Record updated .. </h3>\r\n<% if true %>\r\n<meta http-equiv=\"refresh\" content=\"0; url=show?id=<%=project.id%>&active=protocol2\" />\r\n<% end %>',NULL,NULL,NULL,'2018-09-18 15:31:47','2018-09-18 15:31:47','protocol_update',''),(3677,'case_reports',1438,2,'\r\n<h1>Case Report Summary </h1>\r\n<%\r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n	tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n \r\n\r\n\r\n	def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    @m_patient= model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    type = \'All\'\r\n    type = params[:report][:type] if params[:report]\r\n    \r\n    procedure = \'all\'\r\n    procedure = params[:report][:procedure] if params[:report]\r\n    \r\n    procedures = %w{all gastro colono push_enteroscopy sigmoid ercp eus dbe liver_biopsy}\r\n    cmap = {}\r\n    for i in procedures\r\n        cmap[i] = i.humanize\r\n    end\r\n    \r\n%>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    v{\r\n        color:blue;\r\n    }\r\n</style>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date  , :order=>[:day,:month,:year]%>\r\n\r\n<br/>\r\n\r\n\r\nSchedule : <%=f.select :type, options_for_select(%w{all elective special_clinic emergency}.collect{|i| i.humanize }, type) %>\r\n\r\nProcedure : <%=f.select :procedure, options_for_select(procedures.collect{|i| [i.humanize,i] }, procedure) %>\r\n\r\n\r\n\r\n\r\n<br/>\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n  <%#params.inspect %>\r\n\r\n\r\n<% \r\n\r\n	findings_id = []\r\n    \r\n\r\n\r\n\r\n	if request.post? \r\n  \r\n  \r\n		# select appointment by date\r\n  \r\n		all_app = @models[:appointment].collection.find({:date=>{\'$gte\'=>from_date,\'$lt\'=>to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n  \r\n  \r\n  \r\n		# select pm by module_id of appointment\r\n  \r\n		all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n		\r\n		m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n  \r\n		# select patients by patient_id of pm \r\n		all_patients = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'hn\'=>1}}).to_a\r\n		m_patients = bmap all_patients\r\n  \r\n  \r\n  \r\n		map = {}\r\n  \r\n  \r\n		# for each forms prepare list of module_id \r\n		all_pm = @m_patient_module.collection.find({:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n		m_all_pm = bmap all_pm, \'module_id\'\r\n  \r\n		for i in all_pm\r\n  \r\n			m = i[\'module_name\'].split(\'#\')[-1]\r\n  \r\n			if procedure==\'all\'\r\n  \r\n				map[m] = [] unless map[m]\r\n				map[m] << i[\'module_id\']\r\n  \r\n			else\r\n  \r\n				if m == procedure\r\n  \r\n					map[m] = [] unless map[m]\r\n					map[m] << i[\'module_id\']\r\n  \r\n				end\r\n  \r\n      \r\n			end\r\n  \r\n		end\r\n  \r\n  \r\n		# for each form\'s records \r\n		case_map = {}\r\n		provider_map = {}\r\n  \r\n    for k in map.keys\r\n    \r\n		rs = map[k]\r\n		case_map[k] = [] unless case_map[k]\r\n		if @models[k.to_sym]\r\n    \r\n			conds = {:_id=>{\'$in\'=>rs}}\r\n    \r\n			# 0|Elective\r\n			# 1|Emergency\r\n			# 2|Special clinic\r\n			# 3|Live demo\r\n    \r\n    \r\n			if type !=\'All\'\r\n    \r\n				ctype = \'\'\r\n				case type\r\n					when \'Elective\'\r\n						ctype = \'0\'\r\n					when \'Emergency\'\r\n						ctype = \'1\'\r\n					when \'Special clinic\'\r\n						ctype = \'2\'\r\n				end\r\n        \r\n				conds.merge! :schedule=> ctype\r\n       \r\n			end\r\n			\r\n        \r\n			records = @models[k.to_sym].collection.find(conds, {:fields=>{\'findings\'=>1,\'_id\'=>1,\'schedule\'=>1,\'endoscopist\'=>1,\'created_at\'=>1,\'diagnosis_text\'=>1,\'diagnosis_group\'=>1,\'intervention_text\'=>1,\'procedure\'=>1,\'intervention\'=>1,\'intervention_group\'=>1,\'intervention_summary\'=>1}}).to_a\r\n\r\n   \r\n		\r\n			for i in records\r\n				provider_map[i[\'endoscopist\']] = true \r\n        \r\n				findings_id += i[\'findings\'] if i[\'findings\']\r\n        \r\n				if true\r\n					case_map[k] << i \r\n				end\r\n        \r\n			end\r\n\r\n		end\r\n  \r\n	end\r\n  \r\n  \r\n  \r\n	providers = @models[:provider].collection.find({:_id=>{\'$in\'=>provider_map.keys}})\r\n	m_providers = bmap providers\r\n  \r\n  \r\n  #  collect error\r\n  \r\n	findings = @models[:finding].collection.find({:_id=>{\'$in\'=>findings_id.collect{|x| BSON::ObjectId(x)}}}).to_a\r\n	\r\n	findings_map = bmap findings\r\n  \r\n  \r\n  \r\n	intervention_ids = findings.collect{|x| x[\'intervention\'] }\r\n  \r\n  \r\n  \r\n	interventions = @models[:intervention].collection.find({:_id=>{\'$in\'=>intervention_ids},:intervention_tag=>{\'$ne\'=>\"\"}},{:fields=>{\'intervention_tag\'=>1,\'op_clipping_type\'=>1}}).to_a\r\n  \r\n	interventions_map = bmap interventions\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  if records\r\n  \r\n		for i in records\r\n  \r\n			if i[\'findings\']\r\n            \r\n            \r\n			fs = i[\'findings\'].collect{|x| findings_map[BSON::ObjectId(x)][0] }\r\n			\r\n			fs = fs.collect{|x| {:f=>x,:i=>interventions_map[x[\'intervention\']]} } \r\n            inv = []\r\n            inv = i[\'intervention_group\'].split(\"|\") if i[\'intervention_group\']\r\n            if fs\r\n            for f in fs\r\n                if f[:i]\r\n                    fi = f[:i][0]\r\n                    inv << fi[\'intervention_tag\']\r\n                end\r\n            end\r\n            end\r\n            \r\n            i[\'intervention_group\'] = inv.uniq.join(\'|\')\r\n            \r\n            end\r\n    \r\n            \r\n		end\r\n  \r\n  end\r\n %>\r\n  <%#interventions_map.inspect %>\r\n  \r\n  \r\nFor <i><%=from_date.strftime(\"%d-%m-%Y\")%> to <%=to_date.strftime(\"%d-%m-%Y\")%> </i>\r\n \r\n<br/><br/>\r\n \r\n \r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Procedure</th> <!-- <th>Elective</th><th>Emergency</th><th>Special Clinic</th><th>Undefined</th> --><th>Total</th>\r\n	</tr>\r\n<%  \r\n    tsum = {\'0\'=>0,\'1\'=>0,\'2\'=>0,nil=>0}\r\n\r\n	for k in case_map.keys \r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n		s = i[\'schedule\']\r\n     \r\n		tmap[s] = [] unless tmap[s]\r\n		tmap[s] << i \r\n     \r\n		tsum[s] = 0 unless tsum[s]\r\n		tsum[s] += 1\r\n      \r\n	end\r\n  \r\n%>\r\n    <tr><td><%=k.humanize%></td>\r\n    <!--  \r\n		<td align=\'center\'><%=tmap[\'0\'].size if tmap[\'0\']%></td>\r\n		<td align=\'center\'><%=tmap[\'1\'].size if tmap[\'1\']%></td>\r\n		<td align=\'center\'><%=tmap[\'2\'].size if tmap[\'2\']%></td>\r\n		<td align=\'center\'><%=tmap[\'\'].size if tmap[\'\']%></td>\r\n     --> \r\n    <th><%=case_map[k].size%></th></tr>\r\n	\r\n<% end %>      \r\n <!--\r\n	<tr>\r\n		<td>&nbsp;</td>\r\n		<th><%=tsum[\'0\']%></td>\r\n		<th><%=tsum[\'1\']%></td>\r\n		<th><%=tsum[\'2\']%></td>\r\n		<th><%=tsum[\'\']%></td>\r\n<%\r\n			total_sum = 0 \r\n			total_sum += tsum[\'0\'] if tsum[\'0\']\r\n			total_sum += tsum[\'1\'] if tsum[\'1\']\r\n			total_sum += tsum[\'2\'] if tsum[\'2\']\r\n			total_sum += tsum[\'\'] if tsum[\'\']\r\n\r\n%>\r\n		<th><%=total_sum%></th>\r\n	</tr>\r\n	 -->\r\n</table>\r\n\r\n<br>\r\n  \r\n<% if procedure!=\'all\'%>\r\n<%\r\n    int_map = {}\r\n    for i in records\r\n		int = i[\'intervention_group\']\r\n		if int\r\n			ints = int.split(\'|\') \r\n     \r\n			for j in ints\r\n				int_map[j] = 0 unless int_map[j]\r\n				int_map[j] += 1\r\n			end\r\n		end\r\n    end\r\n  \r\n%>\r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Intervention</th><th>Count</th>\r\n	</tr>\r\n<% for i in int_map.keys %>\r\n	<tr>\r\n		<th><%=i.humanize%></th>\r\n		<td align=\'center\'><%=int_map[i]%></td>\r\n	</tr>\r\n<% end %>\r\n</table>\r\n  \r\n<br/>\r\n  \r\n<%\r\n    dx_map = {}\r\n    for i in records\r\n     \r\n		int = i[\'diagnosis_group\']\r\n		if int\r\n			dxs = int.split(\'|\') \r\n     \r\n			for j in dxs\r\n     \r\n				dx_map[j] = 0 unless dx_map[j]\r\n				dx_map[j] += 1\r\n     \r\n			end\r\n     \r\n		end\r\n      \r\n    end\r\n  \r\n%>\r\n\r\n<%\r\n  \r\n    options = get_document(procedure ).find_by_column_name(\'diagnosis_group\').get_lov_options   \r\n    \r\n    dx_name = {}\r\n    \r\n    for i in options\r\n        \r\n        dx_name[i[0]] = i[1].strip\r\n    \r\n    end\r\n  \r\n  \r\n%>\r\n  \r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Diagnosis Group</th><th>Count</th>\r\n	</tr>\r\n<% \r\n	for i in dx_map.keys \r\n  \r\n		name = \"Undefined(\\\\#{i})\"\r\n		name = dx_name[i] if dx_name[i]\r\n  \r\n%>\r\n	<tr>\r\n		<th><%=name%></th>\r\n		<td align=\'center\'><%=dx_map[i]%></td>\r\n	</tr>\r\n  \r\n<% end %>\r\n</table>\r\n  \r\n<br/>\r\n  \r\n<% end %>\r\n<div class=\'row-fluid\'>\r\n<div style=\'float:right;margin:20px\'>\r\n<%= link_to \'Export EXCEL\', \"case_reports_excel?from_date=\\\\#{from_date.strftime(\'%Y-%m-%d\')}&to_date=\\\\#{to_date.strftime(\'%Y-%m-%d\')}&type=\\\\#{params[:report][:type]}&procedure=\\\\#{params[:report][:procedure]}\", :target=>\'_blank\', :class=>\'btn btn-info\' %>\r\n</div></div>\r\n\r\n<table border=\"1\">\r\n	<tr>\r\n		<th>#</th>\r\n		<th>Procedure</th>\r\n		<th>Date</th>\r\n		<th>HN</th>\r\n		<th>Patient\'s name</th>\r\n		<th>Ans</th>\r\n		<th>Endosocpist</th>\r\n		<th>Diagnosis</th>\r\n		<th>Intervention</th>\r\n		<th>InterventionGroup</th>\r\n	</tr>\r\n\r\n<%\r\n	# zam\r\n	# prepare excel result\r\n	res = {}\r\n	\r\n	# select provider of those records\r\n	for k in case_map.keys\r\n		\r\n		# zam\r\n		# set operation name\r\n		op_name = k.humanize\r\n%>\r\n	<tr style=\"background-color:#ccffcc\">\r\n		<td colspan=\"10\"><h1><%=k.humanize%></h1></td>\r\n	</tr>\r\n<%\r\n  \r\n		tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n			s = i[\'schedule\']\r\n     \r\n			tmap[s] = [] unless tmap[s]\r\n			tmap[s] << i \r\n      \r\n		end\r\n  \r\n		tmap.each_pair do |ks, list| \r\n			index = 0 \r\n			\r\n			# zam\r\n			# set visit_type\r\n			vt = tschedule[ks]\r\n			kk = \"\\\\#{op_name}-\\\\#{vt}\"\r\n			res[kk] = []\r\n%>\r\n    <tr style=\"background-color:#cccccc\">\r\n		<td colspan=\"10\"><%=tschedule[ks]%></td>\r\n	</tr>\r\n<%\r\n	list.each do |i|\r\n	\r\n		# zam\r\n		# temporary for each records\r\n		tmp = {}\r\n    \r\n		pm = m_all_pm[i[\'_id\']][0]\r\n		if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n			patient = m_patients[pm[\'patient_id\']][0]\r\n			provider = nil\r\n			provider = m_providers[i[\'endoscopist\']][0]  if m_providers[i[\'endoscopist\']]\r\n			\r\n			if pm and patient  and provider\r\n        \r\n				schedule = \'-\'\r\n        \r\n				schedule = tschedule[ i[\'schedule\']]\r\n				\r\n				# collect text into tmp\r\n				op_date = i[\'created_at\'].strftime(\"%d/%m/%Y\") \r\n				pat_hn  = patient[\'hn\'] \r\n				pat_name= \"\\\\#{patient[\'first_name\']} \\\\#{patient[\'last_name\']}\"\r\n				\r\n				tmp[:op_date] = op_date\r\n				tmp[:hn] = pat_hn\r\n				tmp[:name] = pat_name\r\n				tmp[:endo] = provider[\'name\']\r\n				tmp[:instrument] = i[\'instrument\']\r\n				tmp[:diag] = i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'diagnosis_text\']\r\n				tmp[:inv_txt] = i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'intervention_text\'] \r\n				tmp[:inv_sum] = i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'intervention_summary\']\r\n				tmp[:inv_group] = i[\'intervention_group\']\r\n				\r\n				\r\n				res[kk] << tmp\r\n        \r\n%>\r\n	<tr>\r\n		<td><%=index+1%></td>\r\n        <td><%=k.humanize%></td>\r\n		<td><%=i[\'created_at\'].strftime(\"%d-%m-%Y\") %></td>\r\n		<td><%=patient[\'hn\'] %></td>\r\n		<td><%=patient[\'first_name\'] %> <%=patient[\'last_name\']%></td>\r\n		<td><%= schedule %></td><td><%= provider[\'name\'] %></td>\r\n        <td >\r\n        <%# i.inspect %>\r\n        <%= i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').html_safe if i[\'diagnosis_text\'] %></td>\r\n        <td ><%= i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').html_safe if i[\'intervention_text\'] %><%= i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').html_safe if i[\'intervention_summary\'] %></td>\r\n<%\r\n           ig = \'background-color:#ffcccc\'\r\n%>\r\n        <td style=\'<%=ig if  i[\'intervention_text\']!=\"\" and i[\'intervention_group\'] and  i[\'intervention_group\'].strip==\'\' %>\'>\r\n<%\r\n            intv = \'-\'\r\n          \r\n%>\r\n			<%=i[\'intervention_group\']%><%#i[\'intervention_text\']%>\r\n			</td>\r\n        </tr>\r\n<%\r\n        \r\n				index+=1\r\n        \r\n			end # if pm and patient  and provider\r\n    \r\n		end #if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n  \r\n        \r\n	end # list.each do |i|\r\n  \r\n	end # tmap.each_pair do |ks, list| \r\n  \r\n	end # for k in case_map.keys\r\n	\r\n# 	session[:case_report_excel] = res\r\n# 	session[:case_report_from] = from_date.strftime(\"%d/%m/%Y\")\r\n# 	session[:case_report_to] = to_date.strftime(\"%d/%m/%Y\")\r\n  \r\n%>\r\n</table>\r\n<%# res.to_json.html_safe %>\r\n<%\r\n  \r\n  # for each recoreds to reprrt\r\n  \r\n%>\r\n  \r\n  \r\n  \r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2018-09-24 03:40:46','2018-09-24 03:40:46','case_reports',''),(3678,'endoscopist_report',1438,2,'<%\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    \r\n    forms = %w{colono gastro dbe sigmoid push_enteroscopy ercp eus liver_biopsy percutaneous_drainage}\r\n    pmap = {}\r\n    map = {}\r\n    names = []\r\n    providers = @models[:provider].collection.find({},{:fields=>{:_id=>1,:name=>1}}).to_a\r\n    \r\n    for i in providers\r\n        pmap[i[\'_id\']] = {:p=>i[\'name\'],:f=>{}}\r\n        names << [i[\'name\'],i[\'_id\']]\r\n    end\r\n    \r\n    names.sort!{ |a,b| a[0]<=>b[0] }\r\n    \r\n      for i in forms\r\n        records = @models[i.to_sym].collection.find({},{:fields=>{:_id=>1,:endoscopist=>1}}).to_a\r\n        \r\n        for  r in  records \r\n        \r\n        if pmap[r[\'endoscopist\']] \r\n        pmap[r[\'endoscopist\']][:f][i] = 0  unless  pmap[r[\'endoscopist\']][:f][i]\r\n        pmap[r[\'endoscopist\']][:f][i] += 1\r\n    end\r\n        end\r\n    \r\n    end\r\n    \r\n%>\r\n<table class=\"table\">\r\n<thead>\r\n<tr><th>&nbsp;</th>\r\n<%\r\n  for i in forms\r\n%>\r\n<th><%=i%></th>\r\n<% end %>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<% for i in names %>\r\n<tr>\r\n    <th><%=i[0]%></th>\r\n    <% for f in forms \r\n        v = 0 \r\n        v = pmap[i[1]][:f][f] if pmap[i[1]][:f][f]\r\n    %>\r\n    <td><%= v %></td>\r\n    <% end %>\r\n</tr>\r\n<% end %>\r\n</tbody>\r\n</table>\r\n\r\n',NULL,NULL,NULL,'2018-09-24 03:41:50','2018-09-24 03:41:50','endoscopist_report',''),(3679,'context_menu',1438,4,'\r\n<% \r\n   obj = [\r\n        {:name=>\'Reports\',:open=>true,:actions=>[\r\n            {:name=>\'Case report\',:service=>\'gastro\',:link=>\'../Report/case_reports\',:remote=>false},\r\n            {:name=>\'Colono report\',:service=>\'colono\',:link=>\'../Report/colono_reports\',:remote=>false},\r\n            {:name=>\'Diagnosis report\',:service=>\'colono\',:link=>\'../Report/diag_reports\',:remote=>false},\r\n            {:name=>\'Extra report\',:service=>\'colono\',:link=>\'colono_bowel\',:remote=>false},\r\n            {:name=>\'Endoscopist report\',:service=>\'report\',:link=>\'../Report/endoscopist_report\',:remote=>false}\r\n\r\n\r\n            ]\r\n        }\r\n    ]\r\n\r\n#   obj << {:name=>\'Links\', :actions=>[{:name=>\'Back to EHR\',:link=>\"../../www/Home/index\",:remote=>false}]}\r\n%>\r\n<%= show_menu obj%>\r\n\r\n\r\n<div class=\"accordion-group\">\r\n	<div class=\"accordion-heading\">\r\n		<a href=\"#collapse-0\" data-parent=\"#side_accordion\" data-toggle=\"collapse\" class=\"accordion-toggle\">\r\n		Dashboard\r\n		</a>\r\n		\r\n		<div class=\"accordion-body collapse in\" id=\"collapse-0\" style=\"display:none\">\r\n			<div class=\"accordion-inner\">\r\n				<ul class=\"nav nav-list\">\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"index\">Overview</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"weekly_report\">Weekly Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"case_report\">Monthly Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"endoscopist_report\">Endoscopist Report</a></li>\r\n					<li style=\"height:2em;border:0px solid red;margin:0.5em\"><a class=\"k-button\" href=\"procedure_report\