 \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Back\', return_url %>\r\n\r\n<br/>\r\n<%\r\n    models = get_model\r\n\r\n    if request.post?\r\n        \r\n    \r\n    items = models[:pl_product_bom].where(:product_id=>params[:id]).all\r\n    for i in items\r\n        i.destroy\r\n    end\r\n    if params[:bom_id]\r\n    params[:bom_id].each_with_index do |i,ix|\r\n       \r\n       item = models[:pl_product_bom].create :product_id=>params[:id], :sub_product_id=>i, :detail=>params[:bom_detail][ix], :quantity=>params[:bom_quantity][ix],:note=>params[:bom_note][ix],:cost=>params[:bom_cost][ix],:price=>params[:bom_price][ix]\r\n        \r\n    end\r\n    end\r\n    \r\n    \r\n    \r\n    %>\r\n    <meta http-equiv=\"refresh\" content=\"0; url=show?id=<%=params[:id]%>\" />\r\n\r\n<%\r\nelse\r\n%>\r\n<%=form_for :bom, :url=>\"\" do |f| %>\r\n<%\r\n    \r\n    items = models[:pl_product_bom].where(:product_id=>params[:id]).all\r\n\r\n%>\r\n<h3>Bill Of Material (BOM) </h3>\r\n<br/>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#addProductPassThrough\" class=\"btn btn-mini\">+ Product Item</a>\r\n<br/><br/>\r\n\r\n\r\n<table class=\"table\">\r\n<thead>\r\n <tr>\r\n            <th>Code</th>\r\n            <th>Detail</th>\r\n            <th>Group</th>\r\n            <th>Vendor</th>\r\n         \r\n            <th>Cost</th>\r\n            <th>Price</th>\r\n             <th>Quantity</th>\r\n            <th>Note</th>\r\n            \r\n            <th></th>\r\n        </tr>\r\n</thead>\r\n<tbody id=\"list\">\r\n      <%\r\n            for i in items \r\n            \r\n             p = models[:pl_product].find(i.sub_product_id) \r\n             \r\n             \r\n             if p\r\n                 \r\n             i.cost = p.cost unless i.cost\r\n             i.price = p.price unless i.price\r\n                 \r\n        %>\r\n         <tr id=\"r<%=i.id%>\">\r\n            <td>\r\n                <%=p.code%>\r\n                <%=hidden_field_tag \"bom_id[]\", i.sub_product_id %>\r\n            </td>\r\n             <td>\r\n                <%=text_field_tag \"bom_detail[]\", i.detail %>\r\n            </td>\r\n             <td>\r\n                <%=p.group_code%>\r\n            </td>\r\n              <td>\r\n                <%=p.vendor_code%>\r\n            </td>\r\n            \r\n            <td>\r\n                <%=text_field_tag \"bom_cost[]\", i.cost ,:style=>\"width:50px\"%>\r\n\r\n\r\n            </td>\r\n           \r\n            <td>\r\n                <%=text_field_tag \"bom_price[]\", i.price ,:style=>\"width:50px\"%>\r\n\r\n\r\n            </td>\r\n            \r\n            \r\n            <td>\r\n                <%=text_field_tag \"bom_quantity[]\", i.quantity ,:style=>\"width:50px\"%>\r\n            </td>\r\n             <td>\r\n                <%=text_field_tag \"bom_note[]\", i.note %>\r\n            </td>\r\n            \r\n            <td>\r\n                <%=link_to \"Delete\", \"#\", :id=>i.id, :class=>\'un-visit\' %>\r\n            </td>\r\n        </tr>\r\n        <% end %>\r\n        \r\n              <% end %>\r\n</tbody>\r\n    \r\n</table>\r\n<br/>\r\n<br/>\r\n<script>\r\n    $(\'.un-visit\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n</script>\r\n\r\n\r\n<br/>\r\n<%= f.submit \'Save\', :class=>\'btn btn-info\' %>\r\n\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<% end %>\r\n\r\n<div id=\"template-x\" style=\"display:none\">\r\n <table>\r\n        <tbody>\r\n    <tr>\r\n    <td class=\"code\">\r\n        code\r\n    </td>\r\n    <td >\r\n        <%=hidden_field_tag \"id\", \'\', :class=>\'field-x record\' %>\r\n\r\n        <%=text_field_tag \"detail\", \'\', :class=>\'field-x detail\' %>\r\n    </td>\r\n    <td class=\"group_code\">\r\n        -\r\n    </td>\r\n    <td class=\"vendor_code\">\r\n        -\r\n    </td>\r\n    <td >\r\n        <%=text_field_tag \"cost\", \'1\', :class=>\'field-x  cost\' %>\r\n    </td>\r\n    <td >\r\n        <%=text_field_tag \"price\", \'1\', :class=>\'field-x  price\' %>\r\n    </td>\r\n   <td >\r\n        <%=text_field_tag \"quantity\", \'1\', :class=>\'field-x quantity\' %>\r\n    </td>\r\n    <td >\r\n        <%=text_field_tag \"note\", \'\', :class=>\'field-x note\' %>\r\n    </td>\r\n    <td class=\"delete\">\r\n        <%=link_to \"Delete\", \"#\", :class=>\'del-x\' %>\r\n    </td>\r\n\r\n\r\n    \r\n    </tr>\r\n    </tbody>\r\n        \r\n    </table>\r\n    \r\n</div>\r\n\r\n<script>\r\n\r\n    function selectProductBom(product_id){\r\n\r\n$.ajax({\r\n  url: \"../PlProduct/data?id=\"+product_id,\r\n  context: document.body\r\n}).done(function(data) {\r\n  data = JSON.parse(data);\r\n  \r\n  \r\n  \r\n        p = data\r\n        \r\n        pre = \'bom\'\r\n      \r\n        template = $(\'#template-x\').clone()\r\n        \r\n        template.find(\'.code\').html(p[\'code\'])\r\n        template.find(\'.gl_code\').html(p[\'gl_code\'])\r\n\r\n        template.find(\'.group_code\').html(p[\'group_code\'])\r\n\r\n        template.find(\'.vendor_code\').html(p[\'vendor_code\'])\r\n\r\n        // template.find(\'.cost\').html(p[\'cost\'])\r\n        \r\n        // template.find(\'.price\').html(p[\'price\'])\r\n                 \r\n        template.find(\'.field-x\').each(function(){\r\n            \r\n            $(this).attr(\"name\",  pre+\"_\"+$(this).attr(\"name\")+\"[]\" ) \r\n            \r\n        })\r\n       \r\n        template.find(\'.record\').attr(\"value\",p[\'id\'])\r\n\r\n\r\n        template.find(\'.detail\').attr(\"value\",p[\'name\'])\r\n        template.find(\'.cost\').attr(\"value\",p[\'cost\'])\r\n        template.find(\'.price\').attr(\"value\",p[\'price\'])\r\n        \r\n        template.find(\'.price\').attr(\"value\",p[\'price\'])\r\n        template.find(\'.del-x\').attr(\"id\",p[\'id\'])\r\n        template.find(\'.del-x\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n        \r\n        \r\n        \r\n\r\n        \r\n        template.find(\'tr\').each(function(){\r\n            $(this).attr(\"id\", \"r\"+p[\'id\'])\r\n            $(\'#list\').append($(this))\r\n        })\r\n  \r\n  \r\n     $(\'#close\').click();\r\n  \r\n  \r\n}); \r\n\r\n    }\r\n    \r\n</script>\r\n\r\n\r\n<div class=\"modal hide\" id=\"addProductPassThrough\" aria-hidden=\"true\" style=\"display: none;\">\r\n	<div class=\"modal-header\">\r\n		<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n		<h3>Product Item</h3>\r\n	</div>\r\n	<div class=\"modal-body\">\r\n\r\n<%= form_for :query, :url=>\"../PlProduct/product_search?update=search_result_1&callback=selectProductBom\", :data=>{:remote=>true} do |f| %>\r\nSearch <%= f.text_field :q%>\r\n<%= f.submit \'Search\' %>\r\n<% end %>\r\n\r\n								\r\n<div id=\"search_result_1\">\r\n    \r\n</div>\r\n\r\n\r\n	</div>\r\n	<div class=\"modal-footer\">\r\n		<a href=\"#\" class=\"btn\" data-dismiss=\"modal\" id=\"close\">Close</a>\r\n	</div>\r\n</div>\r\n\r\n<style>\r\n    input{\r\n        width:120px;\r\n    }\r\n</style>\r\n',NULL,NULL,NULL,'2018-09-26 14:33:22','2018-09-26 14:33:22','show',''),(3687,'data',1325,3,'<%  \r\n    if params[:project_id]\r\n        \r\n      item = nil\r\n      obj = nil\r\n      \r\n      if params[:id]  \r\n      obj = get_model(\'pl_product\').find(params[:id]) \r\n      item = get_model(\'project_item\').where(:product_id=>obj.id).first \r\n     else\r\n       item = get_model(\'project_item\').find(params[:item_id])\r\n      obj = get_model(\'pl_product\').find(item.product_id) \r\n       \r\n      end\r\n       \r\n       if item\r\n          obj.name = item.detail\r\n        #   obj.cost = item.price\r\n          obj.price = item.price\r\n       end\r\n                \r\n\r\n\r\n    end\r\n    \r\n\r\n%><%=obj.to_json.html_safe if obj%>',NULL,NULL,NULL,'2018-09-26 14:57:14','2018-09-26 14:57:14','data',''),(3688,'document_name',1443,1,'\'research_form\'',NULL,NULL,NULL,'2018-09-27 06:24:29','2018-09-27 06:24:29',NULL,NULL),(3689,'transaction',1385,2,'\r\n<%\r\n\r\n    record = get_model(\'visit\').find params[:id]\r\n\r\n    return_url = \"../Patient/show?id=\\\\#{record.patient_id}\"\r\n    \r\n\r\n\r\n    models = get_model\r\n    \r\n    project = models[:project].find record.project_id\r\n    visit = record\r\n    patient = models[:patient].find record.patient_id\r\n    \r\n    protocol_version = \'-\'\r\n    sheet = models[:pl_sheet].find patient.sheet_id\r\n    if sheet\r\n        protocol_version = sheet.version    \r\n    end\r\n    \r\n\r\n   \r\n%>\r\n    <div id=\"jCrumbs\" class=\"breadCrumb module\">\r\n        <div style=\"overflow:hidden; position:relative; width: 1316px;\"><div><ul style=\"width: 500px;\">\r\n            <li class=\"first\">\r\n                <a href=\"../Home/index\"><i class=\"icon-home\"></i></a>\r\n            </li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Project/index\" style=\"width: 84px;\">Projects</a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Project/show?id=<%=project.id%>\" style=\"width: 94px;\"><%=project.protocol_no%></a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Project/show?id=<%=project.id if sheet%>\" style=\"width: 134px;\"><%=protocol_version%></a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n                <span style=\"\"><a href=\"../Patient/show?id=<%=patient.id%>\" style=\"width: 134px;\"><%=patient.subject_id%> <%=patient.first_name%> <%=patient.last_name%></a></span>\r\n            <div class=\"chevronOverlay\" style=\"display: block;\"></div></li>\r\n            <li class=\"last\" style=\"background-image: none; background-position: initial initial; background-repeat: initial initial;\">\r\n               <%=visit.name%>\r\n            </li>\r\n        </ul></div></div>\r\n    </div>\r\n</nav>\r\n\r\n\r\n<style>\r\nv{\r\n      color:blue;\r\n  }\r\n</style>\r\n<table class=\"table table-striped table-bordered table-condensed\">\r\n<tr>\r\n\r\n    <td>\r\n        <b>Subject ID : </b><v><%=patient.subject_id%></v>\r\n    </td>\r\n\r\n\r\n    <td>\r\n        <b>HN : </b><v><%=patient.hn%></v>\r\n    </td>\r\n\r\n    <td>\r\n        <b>Patient Name : </b><v><%=patient.prefix_name%><%=patient.first_name%> <%=patient.last_name%></v>\r\n    </td>\r\n    <td>\r\n        <b>Gender : </b><v><%=patient.gender%></v>\r\n    </td>\r\n    <td>\r\n        <b>Age : </b><v><%=((record.date - patient.birth_date.to_datetime)/(3600*24*365)).to_i if patient and patient.birth_date%> ปี</v>\r\n    </td>\r\n    \r\n    \r\n</tr>    \r\n</table>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%# link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n\r\n\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"\" style=\"border:0px solid\">\r\n\r\n\r\n\r\n<%\r\n    models = get_model\r\n    visit = models[:visit].find params[:id] \r\n    \r\n    period = models[:pl_period].find visit.period_id\r\n  \r\n    project = models[:project].find visit.project_id\r\n\r\n    patient = models[:patient].find visit.patient_id\r\n    \r\n  \r\n    out = visit.process models%>\r\n\r\n<table class=\"table table-striped\">\r\n\r\n    <%\r\n    \r\n    \r\n\r\n    for i in  out[:sale_items] \r\n    \r\n    id = i[:id]\r\n    items = i[:items]\r\n    total = i[:total]\r\n    oh = i[:oh]\r\n    \r\n%>\r\n\r\n\r\n<tr>\r\n<td colspan=\"7\">\r\n<h3> SO : <u><%= id %></u></h3>\r\n</td>\r\n</tr>\r\n\r\n\r\n    <thead>\r\n        <tr>\r\n            <th>No.</th>\r\n            <th>Code</th>\r\n            <th>Detail</th>\r\n            <th>Price</th>\r\n            <th>Quantity</th>\r\n            <th>Amount</th>\r\n            <th>Acc Code</th>\r\n            \r\n        </tr>\r\n        \r\n    </thead>\r\n    <tbody>\r\n        <% items.each_with_index do |i,ix|  %>\r\n        <tr>\r\n            <td>\r\n                <%=ix+1%>.\r\n            </td>\r\n            <td><%=i[:code]%></td>\r\n            <td><%=i[:detail]%></td>\r\n            <td><%=fm i[:price]%></td>\r\n            <td><%=fn i[:quantity]%></td>\r\n            <td><%=fm i[:amount]%></td>\r\n            <td><%=i[:acc_code]%></td>\r\n\r\n\r\n        </tr>\r\n        <% end %>\r\n        \r\n         <tr>\r\n            <td>\r\n               \r\n            </td>\r\n            <td>-</td>\r\n            <td>Sum Total</td>\r\n            \r\n            \r\n            <td></td>\r\n            <td></td>\r\n            <td><u><b><%=fm total%></b></u></td>\r\n            \r\n            <td></td>\r\n\r\n\r\n        </tr>\r\n        \r\n    </tbody>\r\n\r\n\r\n<% end %>\r\n</table>\r\n\r\n<h3> BV & PO </h3>\r\n\r\n\r\n\r\n<table class=\"table table-striped\">\r\n<%\r\n\r\n     out[:buy_items].each do |b| \r\n     id = b[:id]\r\n     items = b[:items]\r\n     \r\n%>\r\n\r\n    <thead>\r\n        <tr>\r\n            <td colspan=\"7\"><br/>\r\n                <h4>Vendor Code : <%=id%></h4>\r\n            </td>\r\n        </tr>\r\n        <tr>\r\n            <th>No.</th>\r\n            <th>Code</th>\r\n            <th>Detail</th>\r\n            <th>Cost</th>\r\n            <th>Quantity</th>\r\n            <th>Amount</th>\r\n            <th>Vendor Code</th>\r\n            \r\n        </tr>\r\n        \r\n    </thead>\r\n    <tbody>\r\n        <% items.each_with_index do |i,ix|  %>\r\n        <tr>\r\n            <td>\r\n                <%=ix+1%>.\r\n            </td>\r\n            <td><%=i[:code]%></td>\r\n            <td><%=i[:detail]%></td>\r\n            <td><%=i[:cost]%></td>\r\n            <td><%=i[:quantity]%></td>\r\n            <td><%=fm i[:amount]%></td>\r\n            <td><%=i[:vendor_code]%></td>\r\n\r\n\r\n        </tr>\r\n        <% end %>\r\n        <tr>\r\n            <td>\r\n                \r\n            </td>\r\n            <td>\r\n                -\r\n            </td>\r\n            <td>\r\n                Sum Total\r\n            </td>\r\n            <td>\r\n                \r\n            </td>\r\n            <td>\r\n                \r\n            </td>\r\n            <td>\r\n                <u><b><%=fm b[:total]%></b></u>\r\n            </td>\r\n        </tr>\r\n    </tbody>\r\n\r\n <% end %>\r\n</table>\r\n\r\n\r\n\r\n<%= link_to \'Back to Visit\', \"show?id=\\\\#{params[:id]}\"%>\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n',NULL,NULL,NULL,'2018-09-28 00:58:21','2018-09-28 00:58:21','transaction',''),(3690,'search',1363,2,'\r\n<h1> Search Result </h1>\r\n<hr/>\r\n<% \r\n    models = get_model\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    fields = %w{hn public_id first_name last_name}\r\n    query = params[:query].strip\r\n    \r\n    \r\n    \r\n    hn_mode=false\r\n    \r\n    \r\n    # if i = query.index(\'/\')\r\n    #     t = query.split(\'/\')\r\n    #     query = \"\\\\#{t[0].to_i}/\\\\#{t[1].to_i}\"\r\n    #     hn_mode = true  \r\n    # elsif query[0..-3].size>=4 and query.to_i !=0\r\n    #     query = \"\\\\#{query[0..-3].to_i}/\\\\#{query[-2..-1].to_i}\"\r\n    #     hn_mode = true  \r\n    # end\r\n    \r\n    \r\n    \r\n    # if query.size == 8 and query.index(\'/\')==nil\r\n    #   query = \"\\\\#{query[0..-3].to_i}/\\\\#{query[-2..-1].to_i}\" \r\n    # elsif query.index(\'/\')\r\n    \r\n    # end\r\n    \r\n    \r\n    keys = []\r\n    # fields.each do |f| \r\n    #     keys <<{f.to_sym=>Regexp.new(query)}\r\n    # end\r\n    keys << {:hn=>query}\r\n\r\n    \r\n    unless hn_mode\r\n    \r\n    keys << {:first_name=>Regexp.new(query)}\r\n    keys << {:last_name=>Regexp.new(query)}\r\n    keys << {:public_id=>query} if query.size==13\r\n    \r\n    end\r\n    \r\n    criteria = {\'$or\'=>keys}\r\n    \r\n    patients = patient_model.where(criteria).all  \r\n    \r\n    app_name = \"\\\\#{@current_project.name}#appointment\"\r\n    app_model = models[:appointment]\r\n\r\n    if patients.size==1\r\n        row = patients[0]\r\n        ams = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).all.collect{|i| i.module_id }\r\n        app = app_model.where(:id=>{\'$in\'=>ams},:status=>{\'$nin\'=>[\'Cancelled\',\'No show\']}).all :sort=>\'date desc\'\r\n    end\r\n\r\n    \r\n%>\r\n<table class=\"table  table-striped table-bordered\">\r\n    <thead>\r\n        <tr>\r\n            <th>HN</th> <th>Patient\'s Name</th> <th>Record</th> <th>Date</th> <th>Endoscopist</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n    <%  for i in patients \r\n    \r\n        ams = module_model.where(:patient_id=>i.id, :module_name=>{\'$ne\'=>\"\\\\#{@current_project.name}#appointment\"}).all\r\n        \r\n        for j in ams\r\n            \r\n            mname = j.module_name.split(\'#\')[1]\r\n            \r\n            pams = module_model.find(j.parent_id)\r\n            \r\n            app = app_model.find(pams.module_id)\r\n            \r\n            if app\r\n                \r\n        endoscopist = models[:provider].find(app.provider)\r\n\r\n        \r\n    %>\r\n        <tr>\r\n            <td>\r\n                <%= i.hn %>\r\n            </td>\r\n            \r\n            <td>\r\n                <%= i.prefix_name %><%= i.first_name %> <%=i.last_name %>\r\n            </td>\r\n            <td>\r\n                <%=link_to mname.humanize, \"../\\\\#{mname.classify}/show?id=\\\\#{j.id}\",:target=>\'_blank\' %>\r\n            </td>\r\n            \r\n             <td>\r\n                <%=app.date.strftime(\"%d-%m-%Y\") %>\r\n            </td>\r\n            \r\n            <td>\r\n                <%=endoscopist.name if endoscopist %>\r\n            </td>\r\n            \r\n        </tr>\r\n    <% end %>  \r\n    <% end %>    \r\n    \r\n    <% end %>    \r\n    </tbody>\r\n</table>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-09-30 02:33:48','2018-09-30 02:33:48','search',''),(3691,'display_script',1435,4,'\r\n<style>\r\n    .heads { width:220px; float:left; text-transform: uppercase; font-weight: bold;padding:5px; font-size:14px;}\r\n    .headss {width:170px;  }\r\n    .red {color: <%=@current_project.get_setting \'theme_color\' %>;}\r\n    .green {color: #1EA30D; float:left; padding-left:10px; width:200px;font-weight: bold;}\r\n    .detail { width:300px; padding:5px; float:left;}\r\n    .detail_consent { width:500px; padding-left:10px; padding:5px;}\r\n    .consent { width:100px; float:left; text-transform: uppercase; font-weight: bold;padding:5px;}\r\n    .detail_procedure { width:500px; padding-left:10px; padding:5px;}\r\n    .procedure { width:100px; float:left; text-transform: uppercase; font-weight: bold;padding:5px;}\r\n    .clear {clear:both}   \r\n    .diagnosis {width:120px; float:left; text-transform: uppercase; font-weight: bold;padding:5px;}\r\n    .suggestion {width:120px; float:left; text-transform: uppercase; font-weight: bold;padding:5px;}\r\n</style>\r\n\r\n<table border=\"0px\" width=\"640px\">\r\n<tr>\r\n    <td><div class=\"heads red headss\"> instrument  </div> <div class=\"\" style=\"padding:5px;float:left;\">  <%= render_value \'instrument\' %></div>\r\n    <div class=\"clear\"></div>\r\n         <div class=\"heads red headss\">Endoscopist </div> <div class=\"\" style=\"padding:5px;float:left;font-size:14px\"><%=render_value \'endoscopist\'%>  </div><br/>\r\n     <div class=\"clear\"></div>\r\n         <div class=\"heads red headss\">anesthesiologist  </div> <div class=\"\" style=\"padding:5px;float:left;\">  <%= render_value \'anesthesiologist\' if @record.anesthesiologist %>  <%= render_value \'other_anesthesiologist\' %></div><br/>\r\n    <div class=\"clear\"></div>\r\n         <div class=\"heads red headss\"> Type of Anesthesia   </div> <div class=\"\" style=\"padding:5px;float:left;\">  <%= render_value \'type_of_anesthesia\' %></div><br/>\r\n <div class=\"clear\"></div>\r\n         <div class=\"heads red headss\"> medication  </div> <div class=\"\" style=\"wpadding:5px;float:left;\"> \r\n         \r\n                 <% if @record.propofol_mg !=\'\' %>Propofol <%=render_value \'propofol_mg\'%> ,<% end%>\r\n                 <% if @record.dormicum_mg !=\'\' %>Dormicum <%=render_value \'dormicum_mg\'%> ,<% end%>\r\n                 <% if @record.fentanyl_mg !=\'\' %>Fentanyl <%=render_value \'fentanyl_mg\'%> ,<% end%>\r\n                 <% if @record.pethdine_mg !=\'\' %>Pethdine <%=render_value \'pethdine_mg\'%> ,<% end%>\r\n                 <% if @record.hyoscine_mg !=\'\' %>Hyoscine <%=render_value \'hyoscine_mg\'%> ,<% end%>\r\n                 <% if @record.etomidate_mg !=\'\' %>Etomidate <%=render_value \'etomidate_mg\'%> ,<% end%></div><br/></td>\r\n    <td align=\"right\">\r\n     \r\n  <img src=\"/esm/svh/endo/gast.jpg\" width=\"160px\">\r\n  \r\n \r\n        \r\n    </td>\r\n</tr>\r\n         <div class=\"clear\"></div>\r\n</table>    \r\n<div class=\"clear\"  style=\"margin-bottom: 10px;\"></div>\r\n         <div class=\"consent red\"> consent </div> <div class=\"detail_consent\" style=\"float: inherit;\">  <%= render_value \'consent\' %></div><br/>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"procedure red\"> procedure </div> <div class=\"detail_procedure\" style=\"float: inherit;\">  <%= render_value \'procedure\' %></div><br/>\r\n         \r\n         <div class=\"clear\"></div>\r\n         <div class=\"heads red\"><text>FINDINGS</text></div><div class=\"clear\"></div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Anal canal </div><div class=\"detail\"><% if @record.anal_canal ==\"\" %>Normal<%else%><%= render_value \'anal_canal\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Rectum  </div><div class=\"detail\"><% if @record.rectum ==\"\" %>Normal<%else%><%= render_value \'rectum\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Sigmoid colon </div><div class=\"detail\"><% if @record.sigmoid_colon ==\"\" %>Normal<%else%><%= render_value \'sigmoid_colon\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Descending colon </div><div class=\"detail\"><% if @record.descending_colon ==\"\" %>Normal<%else%><%= render_value \'descending_colon\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Splenic fixure </div><div class=\"detail\"><% if @record.splenic_fixure ==\"\" %>Normal<%else%><%= render_value \'splenic_fixure\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Transverse colon </div><div class=\"detail\"><% if @record.transverse_colon ==\"\" %>Normal<%else%><%= render_value \'transverse_colon\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Hepatic fixure </div><div class=\"detail\"><% if @record.hepatic_flexure ==\"\" %>Normal<%else%><%= render_value \'hepatic_flexure\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Ascending colon </div><div class=\"detail\"><% if @record.ascending_colon ==\"\" %>Normal<%else%><%= render_value \'ascending_colon\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Cecum  </div><div class=\"detail\"><% if @record.cecum ==\"\" %>Normal<%else%><%= render_value \'cecum\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Ileo cecae valve </div><div class=\"detail\"><% if @record.ileo_cecae_valve ==\"\" %>Normal<%else%><%= render_value \'ileo_cecae_valve\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Terminal ileum </div><div class=\"detail\"><% if @record.terminal_ileum ==\"\" %>Normal<%else%><%= render_value \'terminal_ileum\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"green\"> Colo other </div><div class=\"detail\"><% if @record.colo_other ==\"\" %>Normal<%else%><%= render_value \'colo_other\'%> <% end%> </div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"diagnosis red\"> diagnosis </div>  <div class=\"detail\" style=\"float: inherit;width:500px\">  <%= render_value \'diagnosis\' %></div>\r\n   <div class=\"clear\"></div>\r\n     \r\n         <div class=\"diagnosis red\"> Biopsy  </div> <div class=\"detail\"> <%= render_value \'biopsy_for_pathology\' %><b class=\"red\" style=\"padding-left:20px;padding-right:20px\">AT </b> <%= render_value \'site_of_biopsy\' %></div>\r\n         <div class=\"clear\"></div>\r\n         <div class=\"heads red\"> Therapeutic procedure  </div> <div class=\"detail\">  <%= render_value \'therapeutic_procedure\' %></div>\r\n <div class=\"clear\"></div>\r\n         <div class=\"suggestion red\"> suggestion </div> \r\n   <div class=\"detail\" style=\"float: inherit;width:500px\">  <%= render_value \'suggestion\' %></div>\r\n <div style=\"clear:both\"></div>\r\n         \r\n\r\n  \r\n\r\n',NULL,NULL,NULL,'2018-10-03 21:23:43','2018-10-03 21:23:43','display_script',''),(3692,'pimport',1325,2,'<h1>\r\n    Product Import \r\n</h1>\r\n\r\n<%\r\n    require \'csv\'\r\n    \r\n    pheader = nil\r\n    pmap = {}\r\n\r\n# [\"﻿note\", \"bom\", \"code\", \"ref_code\", \"name\", \"quantity\", \"cost\", \"price\", \"unit\", \"vendor_code\", \"vendor_group\", \"vendor\", nil, nil, nil, nil]\r\n# [\"Fix cost\", nil, \"STU-001\", \"SU-011\", \"Start up fee (per time)\", nil, \"35,000.00\", \"35,000.00\", \"Time\", \"CRC\", nil, \"CRC\", nil, nil, nil, nil]\r\n   \r\n#     ADM\r\n# LAB\r\n# DRUG\r\n# HOS\r\n# PI\r\n# NRC\r\n# OH\r\n# PH\r\n# SU\r\n# VOL\r\n\r\n    def unify tag, v\r\n       if v\r\n       case tag\r\n       when :price\r\n       v = (v.split(\",\").join).to_f\r\n       when :cost\r\n       v = (v.split(\",\").join).to_f\r\n       when :cost_hiv_nat, :cost_hos\r\n        v = (v.split(\",\").join).to_f if v\r\n       when :quantity\r\n        v = v.to_i if v\r\n       \r\n       else \r\n       v\r\n       end\r\n         end\r\n       return v\r\n    end\r\n  \r\n  \r\n   if true\r\n\r\n    CSV.foreach(\'public/esm/cusys/cucrc/item.csv\') do |row|\r\n       unless pheader\r\n        pheader = {}\r\n        # row.each_with_index do |i,ix|\r\n        #     if i\r\n        #      pheader[i.to_sym] = ix\r\n        #     end\r\n        # end\r\n        \r\n         pheader = {:group_code=>0, :bom=>1,:code=>2, :ref_code=>3, :name=>4, :quantity=>5,:cost=>6, :price=>7 , :unit=>8, :vendor_code=>9, :vendor_group=>10, :vendor=>11}\r\n\r\n\r\n    \r\n       else\r\n        \r\n            obj = {}\r\n            pheader.each_pair do |k,v|\r\n                obj[k] = unify(k,row[v])\r\n            end\r\n    \r\n        \r\n            if obj[:bom] and obj[:bom]!=obj[:code]\r\n                \r\n                root = pmap[obj[:bom]]\r\n                if root\r\n                   \r\n                   root[:bom_list] = [] unless root[:bom_list]\r\n                   quantity = 1\r\n                   quantity = obj[:quantity].to_i if obj[:quantity]\r\n                   root[:bom_list] << {:code=> obj[:code], :quantity=> quantity}\r\n                    \r\n                end\r\n               \r\n            \r\n            end\r\n            \r\n            obj[:group_code] = obj[:note]\r\n            \r\n            unless pmap[obj[:code]]\r\n            \r\n            pmap[obj[:code]] = obj\r\n            \r\n            end\r\n            \r\n            \r\n       \r\n       end\r\n     \r\n        \r\n    end\r\n    \r\nend \r\n    \r\n# ===============================================================================================\r\n\r\n   pheader = nil\r\n    \r\n    # map = [\"﻿\", \"BOM\"=>:bom, \"New code\"=>, \"Ref code\", \"Name\", \"Quantity\", \"Price\", \"HIV/NAT\", \"HOS\", \"หน่วยนับ\"]\r\n    \r\nif true\r\n\r\n       CSV.foreach(\'public/esm/cusys/cucrc/lab.csv\') do |row|\r\n           \r\n        \r\n       unless pheader\r\n        pheader = {:code=>2, :ref_code=>3, :name=>4, :quantity=>5, :price=>6 , :cost_hiv_nat=>7, :cost_hos=>8, :unit=>9}\r\n       else\r\n           \r\n        obj = {:group_code=>\'LAB\' }\r\n            pheader.each_pair do |k,v|\r\n                obj[k] = unify(k,row[v])\r\n            end\r\n        \r\n        \r\n        \r\n        unless pmap[obj[:code]]\r\n        \r\n        code = obj[:code]\r\n        \r\n        \r\n        opt = []\r\n        \r\n        \r\n        if obj[:cost_hos]\r\n            o = obj.clone\r\n            o[:code] = \"\\\\#{code}-HOS\"\r\n            o[:cost] = o[:cost_hos]\r\n            o[:vendor_code] = \'HOS\'\r\n            pmap[o[:code]] = o\r\n            opt << {:code=>o[:code]}\r\n        end\r\n        \r\n        \r\n        if obj[:cost_hiv_nat]\r\n             o = obj.clone\r\n            o[:code] = \"\\\\#{code}-HIVNAT\"\r\n            o[:cost] = o[:cost_hiv_nat]\r\n            o[:vendor_code] = \'CRL01\'\r\n            pmap[o[:code]] = o\r\n             opt << {:code=>o[:code]}\r\n        end\r\n        \r\n        obj[:code] = code\r\n        obj[:cost] = nil\r\n        obj[:opt_list] = opt \r\n        pmap[obj[:code]] = obj\r\n        \r\n        \r\n        \r\n        \r\n        end\r\n        \r\n        \r\n        end\r\n        \r\n        \r\n           \r\n    end \r\n    \r\nend\r\n\r\npheader = nil\r\n\r\n   \r\n   if true\r\n\r\n       CSV.foreach(\'public/esm/cusys/cucrc/drug.csv\') do |row|\r\n\r\n        # ,BOM,New code,Ref code,Name,Quantity,Cost,Price,หน่วยนับ,Vendor code,Vendor group,Vendor\r\n\r\n       unless pheader\r\n        pheader = {:code=>2, :ref_code=>3, :name=>4, :quantity=>5, :cost=>6 ,:price=>7 , :unit=>8, :vendor_code=>9, :vendor_group=>10, :ventor=>11}\r\n       else\r\n           \r\n        obj = {:group_code=>\'DRUG\' }\r\n            pheader.each_pair do |k,v|\r\n                obj[k] = unify(k,row[v])\r\n            end\r\n        \r\n        \r\n        \r\n        unless pmap[obj[:code]]\r\n        \r\n        code = obj[:code]\r\n        \r\n        pmap[obj[:code]] = obj\r\n        \r\n        end\r\n        \r\n    end\r\n    \r\nend\r\n\r\nend\r\n        \r\n   pmap.delete nil     \r\n%>\r\n\r\n\r\n<table class=\"table\">\r\n    <% pmap.keys.sort.each do |k| \r\n        v = pmap[k]\r\n    %>\r\n    <tr>\r\n        <td><%=k%></td><td><%=v[:ref_code]%></td><td><%=v[:name]%></td><td><%=v[:cost]%></td><td><%=v[:price]%></td><td><%=v[:vendor_code]%></td><td><%=v[:vendor_group]%></td><td><%=v[:vendor]%></td>\r\n        <td><%=v[:bom_list] if v[:bom_list]%></td><td><%=v[:opt_list] if v[:opt_list]%></td>\r\n    </tr>\r\n    \r\n    <%end%>\r\n    \r\n</table>\r\n<%\r\n\r\n    models = get_model\r\n\r\n    if params[:reset]\r\n    \r\n   \r\n    \r\n    list = %w{pl_product pl_product_bom pl_period_product pl_period_item visit_item }\r\n    for i in list\r\n        if models[i.to_sym]\r\n        models[i.to_sym].destroy_all \r\n        else\r\n        %>\r\n        <%=i.to_sym%>\r\n        <%\r\n        end\r\n    end\r\n    \r\n    \r\n    end\r\n\r\n\r\n    if params[:reset]\r\n    \r\n    m_product = models[:pl_product]\r\n    \r\n    pmap.keys.sort.each do |k| \r\n    \r\n        v = pmap[k]\r\n        \r\n        record = m_product.where(:code=>v[:code]).first\r\n        \r\n        unless record\r\n            record = m_product.create :code=>v[:code], :name=>v[:name], :vendor_code=>v[:vendor_code], :vendor_group=>v[:vendor_group], :cost=>v[:cost], :price=>v[:price], :group_code=>v[:group_code]\r\n        else\r\n            record.update_attributes :code=>v[:code], :name=>v[:name], :vendor_code=>v[:vendor_code], :vendor_group=>v[:vendor_group], :cost=>v[:cost], :price=>v[:price], :group_code=>v[:group_code]\r\n        end\r\n        \r\n      \r\n        \r\n        \r\n    end\r\n    \r\n    \r\n    \r\n     pmap.keys.sort.each do |k| \r\n    \r\n        v = pmap[k]\r\n        \r\n        record = m_product.where(:code=>v[:code]).first\r\n        \r\n        if v[:bom_list]\r\n           for j in v[:bom_list] \r\n                sub_product = m_product.where(:code=>j[:code]).first\r\n                if sub_product\r\n                    models[:pl_product_bom].create :product_id=>record.id, :sub_product_id=>sub_product.id, :quantity=>j[:quantity], :item_type=>\'BOM\'     \r\n                end\r\n                \r\n            end\r\n            \r\n            \r\n        end\r\n        \r\n        if v[:opt_list]\r\n           for j in v[:opt_list] \r\n                sub_product = m_product.where(:code=>j[:code]).first\r\n                if sub_product\r\n                    models[:pl_product_bom].create :product_id=>record.id, :sub_product_id=>sub_product.id, :quantity=>j[:quantity], :item_type=>\'OPT\'     \r\n                end\r\n                \r\n            end\r\n            \r\n            \r\n        end\r\n        \r\n        \r\n        \r\n    end\r\n    \r\nend\r\n    \r\n    \r\n%>\r\n\r\n\r\n<% %>',NULL,NULL,NULL,'2018-10-08 04:18:07','2018-10-08 04:18:07','pimport',''),(3693,'protocol_chem',1324,3,'<%\r\n    models = get_model \r\n    \r\n    \r\n    if request.post?\r\n        \r\n        sheet = models[:pl_sheet].find params[:sheet_id]\r\n        \r\n        if sheet \r\n            p = models[:pl_product].where(:code=>\'SET-CHEM\').first\r\n            if p \r\n                # period_product =  models[:pl_period_product].where(:product_id=>p.id, :sheet_id=>sheet.id).first\r\n                period_product =  models[:pl_period_product].find(params[:idx])\r\n                \r\n                if period_product\r\n                   \r\n                   records = models[:pl_period_product_bom].where(:period_product_id=>period_product.id).all\r\n                   for i in records\r\n                    i.destroy\r\n                    end\r\n                    \r\n                    \r\n                    for i in params[:p]\r\n                 \r\n                        records = models[:pl_period_product_bom].create(:period_product_id=>period_product.id, :sub_product_id=>i)\r\n\r\n                    end\r\n                    \r\n                \r\n                    \r\n                    \r\n                   \r\n                    \r\n                end\r\n            end\r\n        end\r\n        \r\n    end\r\n    \r\n%>\r\n<%= render :inline=>this.protocol_form%>\r\n\r\n<script>\r\n\r\n    $(\'#config_chem\').modal(\'hide\')\r\n</script>',NULL,NULL,NULL,'2018-10-09 03:57:29','2018-10-09 03:57:29','protocol_chem',''),(3694,'chem_config',1324,3,'<%\r\n    models=get_model\r\n    \r\n    map = {}\r\n    \r\n    labs = models[:pl_product].where(:group_code=>\'LAB\',:vendor_code=>{\'$ne\'=>nil} ).all\r\n    \r\n    for i in labs\r\n    \r\n        map[i.id] = i\r\n    \r\n    end\r\n\r\n    labs = models[:pl_product].where(:vendor_code=>{\'$in\'=>[nil,\'\']},:group_code=>\'LAB\',:code=>{\'$ne\'=>\'SET-CHEM\'}).sort(:code).all\r\n\r\n    boms = models[:pl_product_bom].where(:product_id=>labs.collect{|i| i.id}).all\r\n    \r\n    bmap = {}\r\n    \r\n    \r\n    \r\n    for i in boms\r\n    \r\n    \r\n       bmap[i.product_id] = {} unless bmap[i.product_id]\r\n       p = map[i.sub_product_id]\r\n        if p \r\n            bmap[i.product_id][p.vendor_code] = p\r\n        end\r\n    end\r\n    \r\n    \r\n    \r\n    iselect = {} \r\n    \r\n    sheet = models[:pl_sheet].find params[:id]\r\n        \r\n    if sheet \r\n        p = models[:pl_product].where(:code=>\'SET-CHEM\').first\r\n        if p \r\n            period_product =  models[:pl_period_product].where(:product_id=>p.id, :sheet_id=>sheet.id).first\r\n            \r\n            period_product =  models[:pl_period_product].find(params[:idx])\r\n            \r\n            \r\n            if period_product\r\n                \r\n                records = models[:pl_period_product_bom].where(:period_product_id=>period_product.id).all\r\n                for i in records\r\n                \r\n                    iselect[i.sub_product_id] = true\r\n                \r\n                end\r\n\r\n            end\r\n        end\r\n    \r\n    end\r\n    \r\n%>\r\n\r\n<%=form_for :record, :url=>\"protocol_chem?id=\\\\#{params[:id]}&update=protocol-panel&idx=\\\\#{params[:idx]}\", :data=>{:remote=>true} do |f|  %>\r\n\r\n\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Chem Configure</h3>\r\n								</div>\r\n<div class=\"modal-body\">\r\n\r\n\r\n<%=hidden_field_tag :sheet_id, params[:id] %>\r\n<%\r\n   \r\n%>\r\n<%= text_field_tag :search_item,\"\" %>\r\n\r\n<table class=\"table table-sm\" >\r\n<thead>\r\n    <tr>\r\n        <th>\r\n            Code\r\n        </th>\r\n        <th>\r\n            Description\r\n        </th>\r\n        \r\n        <th>\r\n            Price\r\n        </th>\r\n        \r\n        <th>\r\n            Select    \r\n        </th>\r\n        \r\n        <th>\r\n            Hos\r\n        </th>\r\n        \r\n        <th>\r\n            HIV/NAT\r\n        </th>\r\n\r\n    </tr>\r\n</thead>\r\n<% for i in labs %>\r\n<tr id=\"<%=i.id%>\" class=\"rowx\">\r\n    <td>\r\n        <%=i.code%>\r\n    </td>\r\n    \r\n    <td>\r\n        <%=i.name%>\r\n    </td>\r\n    \r\n    <td>\r\n        <%= i.price %>\r\n    </td>\r\n    <td>\r\n        <%= check_box_tag \"p[]\", i.id , iselect[i.id]  %>\r\n    </td>\r\n    <td>\r\n    <%\r\n    \r\n    \r\n        if bmap[i.id] and  b = bmap[i.id][\'HOS\'] and b \r\n    %>\r\n        <%= b.cost %>\r\n        \r\n    <% else %>\r\n        - \r\n    <% end %>\r\n    </td>\r\n    \r\n    \r\n    <td>\r\n      <%\r\n      \r\n        if bmap[i.id] and  b = bmap[i.id][\'CRL01\'] and b\r\n    %>\r\n        <%= b.cost %>\r\n        \r\n    <% else %>\r\n        - \r\n    <% end %>\r\n    </td>\r\n    \r\n    \r\n    \r\n    \r\n</tr>\r\n<% end %>    \r\n</table>\r\n\r\n</div>\r\n\r\n<script>\r\n    $(\'#search_item\').keyup(function(){\r\n        list = <%= labs.to_json.html_safe %>\r\n        v = $(this).val()\r\n        if(v.length>0){\r\n            reg =  new RegExp(v,\'i\');\r\n            $(\'.rowx\').hide();\r\n            for(var ix in list){\r\n                i = list[ix];\r\n                \r\n                var res = i[\'name\'].match(reg);\r\n                if(res!=null){\r\n                    $(\'#\'+i[\'id\']).show();\r\n                }\r\n                \r\n            }\r\n            \r\n        }else{\r\n              $(\'.rowx\').show();\r\n        }\r\n    })\r\n</script>\r\n								<div class=\"modal-footer\"><%= f.submit \'Update\' ,:data=>{:disable_with=>\'Updating..\'}, :class=>\'btn btn-info\'%>\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n								\r\n<% end %>		\r\n\r\n<script>\r\n    refresh_remote()\r\n</script>\r\n',NULL,NULL,NULL,'2018-10-09 04:19:44','2018-10-09 04:19:44','chem_config',''),(3695,'document_name',1444,1,'\'ip_card\'',NULL,NULL,NULL,'2018-10-09 14:40:19','2018-10-09 14:40:19',NULL,NULL),(3696,'create',1444,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<% link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.new params[:record]\r\n  \r\n  return_url = url(\'index\')\r\n  return_url = params[:return] if params[:return]\r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    flash[:notice]=\'New record has been created\'\r\n    \r\n    if return_url.index(\'?\')\r\n        return_url+=\'&\'\r\n     else\r\n        return_url+=\'?\'\r\n    end\r\n\r\n    return_url += \"obj_id=\\\\#{record.id}\"\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"../IpItem/index\"\r\n//-->\r\n</script>\r\n<%\r\n  else  \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |form| %>\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = form\r\n    params[:form][:record] = record\r\n%>\r\n<%= hidden_field_tag \'return\', params[:return] if params[:return] %>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-add\"></i> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<style>\r\n    .admin{\r\n        display:none;\r\n    }\r\n</style>\r\n',NULL,NULL,NULL,'2018-10-09 16:02:15','2018-10-09 16:02:15','create',''),(3699,'document_name',1446,1,'\'demographic_data\'',NULL,NULL,NULL,'2018-10-10 07:35:36','2018-10-10 07:35:36',NULL,NULL),(3700,'document_name',1448,1,'\'ajcc8th_edition\'',NULL,NULL,NULL,'2018-10-10 08:03:25','2018-10-10 08:03:25',NULL,NULL),(3701,'document_name',1449,1,'\'diagnosis_and_pathology\'',NULL,NULL,NULL,'2018-10-10 08:03:55','2018-10-10 08:03:55',NULL,NULL),(3702,'document_name',1450,1,'\'treatment_ebc\'',NULL,NULL,NULL,'2018-10-10 08:04:19','2018-10-10 08:04:19',NULL,NULL),(3703,'document_name',1451,1,'\'treatment_mbc\'',NULL,NULL,NULL,'2018-10-10 08:05:09','2018-10-10 08:05:09',NULL,NULL),(3704,'document_name',1452,1,'\'cmtinebc\'',NULL,NULL,NULL,'2018-10-10 08:06:25','2018-10-10 08:06:25',NULL,NULL),(3705,'document_name',1453,1,'\'cmtin_abc\'',NULL,NULL,NULL,'2018-10-10 08:06:41','2018-10-10 08:06:41',NULL,NULL),(3707,'document_name',1455,1,'\'ajcc8th_edition\'',NULL,NULL,NULL,'2018-10-10 08:20:03','2018-10-10 08:20:03',NULL,NULL),(3708,'index',1456,2,'<%= @current_project.get_setting \'cms_host\'\r\n\r\n%>',NULL,NULL,NULL,'2018-10-15 06:22:31','2018-10-15 06:22:31','index',''),(3709,'get_stations',1456,3,'<%= render :inline=>this.init%>\r\n<%\r\n    uri = URI(\"\\\\#{@api}/get_stations\")\r\n    params = { :zone => \'default\' }\r\n    uri.query = URI.encode_www_form(params)\r