ata[\'bp\'].split(\'/\')\r\n            sys = bps[0];\r\n            dia = bps[1];\r\n            console.log(id)\r\n            $(\'#data-intra_scope-vital_sign-\'+id+\'-bp\').val(sys);\r\n            $(\'#data-intra_scope-vital_sign-\'+id+\'-diastolic\').val(dia);\r\n            $(\'#data-intra_scope-vital_sign-\'+id+\'-pr\').val(last_data[\'pr\']);\r\n            $(\'#data-intra_scope-vital_sign-\'+id+\'-o2sat\').val(last_data[\'spo2\']);\r\n            // $(\'#data-intra_scope-vital_sign-\'+id+\'-rr\').val(last_data[\'rr\']);\r\n\r\n\r\n\r\n     \r\n         }\r\n         \r\n    \r\n}\r\nfunction refresh_monitor() {\r\n  $.ajax({\r\n   url: \"../Monitor/get_data?zone=default&id=<%=params[:id]%>\",\r\n    success: function(content) {\r\n      data = JSON.parse(content)    \r\n      new_bp_stamp = data[\'bp_stamp\']\r\n      new_bp = data[\'bp\']\r\n      \r\n    //   console.log(data)\r\n         console.log(new_bp_stamp+\" \"+bp_stamp+\" old = \"+old_bp+\" new = \"+new_bp)\r\n         \r\n      if(new_bp!=old_bp&&data[\'bp\']!=\'-/-\'){\r\n          \r\n         console.log(new_bp_stamp)\r\n         console.log(data)\r\n         bp_stamp = new_bp_stamp\r\n         old_bp = new_bp\r\n         last_data = data\r\n\r\n         // check last record is empty\r\n         \r\n         s = $(\'#F7646639377\').children().last();\r\n         last = s\r\n         add = true\r\n         if(last){\r\n            id = last.attr(\'id\')\r\n            sys = $(\'#data-intra_scope-vital_sign-\'+id+\'-bp\').val()\r\n            if(sys==\"\")\r\n                add = false;\r\n         }\r\n         \r\n         if(add)\r\n         $(\'#intra_scope-vital_sign-add-action\').click();\r\n         \r\n         setTimeout(fill_data, 1500);\r\n          \r\n        // \r\n\r\n      }\r\n      \r\n      $(\'#update\').html(data);\r\n    },\r\n    complete: function() {\r\n      // schedule the next request *only* when the current one is complete:\r\n      setTimeout(refresh_monitor, 1000);\r\n    }\r\n  });\r\n}\r\n\r\n// schedule the first invocation:\r\nsetTimeout(refresh_monitor, 1000);\r\n\r\n\r\n</script>\r\n<% else %>\r\n<div id=\"monitor_result\">\r\n    \r\n</div>\r\n<div class=\"modal hide\" id=\"monitor_panel\">\r\n\r\n<div class=\"row-fluid\">\r\n    <%# form_for \'select_monitor\', :url=>\'../Monitor/select_station?update=monitor_result\', :data=>{:remote=>true} do |f| %>\r\n    <div class=\"col-sm-12\">\r\n   <center><br/>\r\n   <p><h3>Select Monitor</h3>\r\n   </p>\r\n    <%= select_tag :monitor, options_for_select(data.collect{|i| [i[\'title\'],i[\'id\']] } ), :id=>\'monitor_id\' %>\r\n    <br/>\r\n    <%= submit_tag \'Submit\', :class=>\'btn btn-info\',:id=>\'monitor_submit\' %>     <%= submit_tag \'Cancel\', :class=>\'btn btn-default\',:id=>\'monitor_cancel\' %> \r\n\r\n\r\n    <br/>    <br/>\r\n</center>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n\r\n  $(\'#monitor_panel\').modal(\'show\'); \r\n  $(\'#monitor_cancel\').click(function(){\r\n    \r\n        $(\'#monitor_panel\').modal(\'hide\'); \r\n        return false;\r\n      \r\n  });\r\n  \r\n  $(\'#monitor_submit\').click(function(){\r\n  \r\n        val = $(\'#monitor_id\').val();\r\n\r\n $.ajax({\r\n        url: \"../Monitor/select_station?id=\"+val,\r\n        context: document.body,\r\n        type: \"POST\"\r\n    }).done(function(content) {\r\n        $(\'#update\').append(content);\r\n    });\r\n \r\n      return false;\r\n  })\r\n</script>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-10-15 15:05:34','2018-10-15 15:05:34','select_station',''),(3713,'show',1436,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;max-width:750px\">\r\n\r\n<%\r\n\r\n   @document =  get_document this.document_name \r\n   \r\n   model = get_model(this.table_name)\r\n   @patient_module = @module_model.find(params[:id])\r\n   record = model.find(@patient_module.module_id)\r\n   @record = record    \r\n  if request.post?\r\n    \r\n   \r\n    if p = params[\'cancel_\']\r\n        \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            old_app.destroy\r\n            mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>nil\r\n   \r\n    elsif p = params[\'postpone_\']\r\n    \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            # old_app.destroy\r\n            # mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        \r\n        \r\n        new_app = record.clone\r\n        new_app.update_attributes :date=>p[0][\'postpone_to\'],:status=>\'Appointed\'\r\n        \r\n        mm = @patient_module.clone\r\n        mm.module_id = new_app.id \r\n        mm.save    \r\n        \r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>p[0][\'postpone_to\'], :postpone_id=>new_app.id\r\n       \r\n        \r\n        \r\n    end\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Home/index\" />\r\n<% end %>\r\n<%= this.display.html_safe %>\r\n\r\n<div id=\"cancel\" style=\"display:none\"  class=\"alert alert-warning\">\r\n   <p>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'cancel_\'\r\n        field = @document.find_by_column_name \'cancel_reason\'\r\n        begin\r\n        %>\r\n        \r\n        <%#field%>\r\n        <div>\r\n        \r\n        <h3>Cancel</h3><br/>\r\n        <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Cancelled\' %>\r\n        </div>\r\n        <script>\r\n        <%= yield :script %>\r\n        \r\n      \r\n        </script>\r\n        <% rescue Exception=>e %>\r\n        <%=e.message%>\r\n        <% end%>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n</div>\r\n\r\n<div id=\"postpone\" style=\"display:none;padding:10px\" class=\"alert alert-warning\">\r\n   \r\n      <p>\r\n        <h3>Postpone</h3><br/>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'postpone_\'\r\n        %>\r\n        <div>\r\n        \r\n       <% field = @document.find_by_column_name \'cancel_reason\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n       <% field = @document.find_by_column_name \'postpone_to\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Postpone\' %>\r\n        </div>\r\n       \r\n       \r\n        <script>\r\n        <%= yield :script %>\r\n        </script>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n   \r\n   \r\n</div>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Cancel\'.html_safe, \"javascript:cancel()\",:class=>bt_class %> | \r\n<%= link_to \'Postpone\'.html_safe, \"javascript:postpone()\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    \r\n    function cancel(){\r\n        $(\'#postpone\').hide()\r\n        $(\'#cancel\').slideDown()\r\n        $(\'#cancel_cancel_reason\').show()\r\n        \r\n    }\r\n    \r\n    function postpone(){\r\n        $(\'#cancel\').hide()\r\n        $(\'#postpone\').slideDown()\r\n        $(\'#postpone_postpone_to\').show()\r\n\r\n    }\r\n    \r\n    function cancel_ctrl(){\r\n        $(\'#postpone\').slideUp()\r\n        $(\'#cancel\').slideUp()\r\n    }\r\n    $(\'.ctrl\').hide();\r\n</script>',NULL,NULL,NULL,'2018-10-17 15:33:38','2018-10-17 15:33:38','show',''),(3714,'index',1457,3,'<html>\r\n<head>\r\n    <%=include_header%>\r\n</head>\r\n<body>\r\n<% \r\n    models = get_model\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    fields = %w{hn public_id first_name last_name}\r\n\r\n    query = \"\"\r\n    \r\n        params[:hn] = params[\'HN\'] if params[\'HN\']\r\n\r\n    \r\n    if params[:hn] or params[:query]\r\n\r\n    params[:query] = params[:hn] if params[:hn]\r\n     \r\n    query = params[:query].strip\r\n    \r\n    end\r\n\r\n    hn_mode=true\r\n    \r\n    \r\n    # if i = query.index(\'/\')\r\n    #     t = query.split(\'/\')\r\n    #     query = \"\\\\#{t[0].to_i}/\\\\#{t[1].to_i}\"\r\n    #     hn_mode = true  \r\n    # elsif query[0..-3].size>=4 and query.to_i !=0\r\n    #     query = \"\\\\#{query[0..-3].to_i}/\\\\#{query[-2..-1].to_i}\"\r\n    #     hn_mode = true  \r\n    # end\r\n    \r\n    \r\n    \r\n    # if query.size == 8 and query.index(\'/\')==nil\r\n    #   query = \"\\\\#{query[0..-3].to_i}/\\\\#{query[-2..-1].to_i}\" \r\n    # elsif query.index(\'/\')\r\n    \r\n    # end\r\n    \r\n    \r\n    keys = []\r\n    # fields.each do |f| \r\n    #     keys <<{f.to_sym=>Regexp.new(query)}\r\n    # end\r\n    keys << {:hn=>query}\r\n\r\n    \r\n    unless hn_mode\r\n    \r\n    keys << {:first_name=>Regexp.new(query)}\r\n    keys << {:last_name=>Regexp.new(query)}\r\n    keys << {:public_id=>query} if query.size==13\r\n    \r\n    end\r\n    \r\n    criteria = {\'$or\'=>keys}\r\n    \r\n    patients = patient_model.where(criteria).all  \r\n    \r\n    app_name = \"\\\\#{@current_project.name}#appointment\"\r\n    app_model = models[:appointment]\r\n\r\n    if patients.size==1\r\n        row = patients[0]\r\n        ams = module_model.where(:module_name=>\"\\\\#{app_name}\",:patient_id=>row.id).all.collect{|i| i.module_id }\r\n        app = app_model.where(:id=>{\'$in\'=>ams},:status=>{\'$nin\'=>[\'Cancelled\',\'No show\']}).all :sort=>\'date desc\'\r\n    end\r\n\r\n    \r\n%>\r\n<table class=\"table  table-striped table-bordered\">\r\n    <thead>\r\n        <tr>\r\n            <th>HN</th> <th>Patient\'s Name</th> <th>Record</th> <th>Date</th> <th>Endoscopist</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n    <%  for i in patients \r\n    \r\n        ams = module_model.where(:patient_id=>i.id, :module_name=>{\'$ne\'=>\"\\\\#{@current_project.name}#appointment\"}).all\r\n        \r\n        for j in ams\r\n            \r\n            mname = j.module_name.split(\'#\')[1]\r\n            \r\n            pams = module_model.find(j.parent_id)\r\n            \r\n            app = app_model.find(pams.module_id) if pams\r\n            \r\n            if app\r\n                \r\n        endoscopist = models[:provider].find(app.provider)\r\n\r\n        \r\n    %>\r\n        <tr>\r\n            <td>\r\n                <%= i.hn %>\r\n            </td>\r\n            \r\n            <td>\r\n                <%= i.prefix_name %><%= i.first_name %> <%=i.last_name %>\r\n            </td>\r\n            <td>\r\n                <%=link_to mname.humanize, \"../\\\\#{mname.classify}/print_partial?id=\\\\#{j.id}\",:target=>\'_blank\' %>\r\n            </td>\r\n            \r\n             <td>\r\n                <%=app.date.strftime(\"%d-%m-%Y\") %>\r\n            </td>\r\n            \r\n            <td>\r\n                <%=endoscopist.name if endoscopist %>\r\n            </td>\r\n            \r\n        </tr>\r\n    <% end %>  \r\n    <% end %>    \r\n    \r\n    <% end %>    \r\n    </tbody>\r\n</table>\r\n</body>\r\n\r\n</html>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-10-17 16:01:48','2018-10-17 16:01:48','index','*'),(3716,'document_name',1460,1,'\'liver_ultrasound_and_fibroscan\'',NULL,NULL,NULL,'2018-10-19 02:05:12','2018-10-19 02:05:12',NULL,NULL),(3717,'document_name',1461,1,'\'rdu_form_18\'',NULL,NULL,NULL,'2018-10-19 02:39:53','2018-10-19 02:39:53',NULL,NULL),(3718,'create',1461,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">New <%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<% link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe, url(\"create\"),:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<