       \r\n        end\r\n        \r\n        \r\n        list << obj\r\n        \r\n        \r\n    end\r\n    \r\n  \r\n    \r\n  # use row here...\r\nend\r\n\r\n  for j in list\r\n        \r\n        record = model.where(:user_id=>j[:user_id]).first\r\n        unless record\r\n            \r\n            record = model.create j\r\n            \r\n            user_id = format(\'%04d\',record.user_id.to_i) if record.user_id and record.user_id!=\'\' and record.user_id.to_i!=0\r\n  \r\n            record.member_id = \"2018-01-\\\\#{user_id}\"\r\n            \r\n            record.save\r\n        \r\n        end\r\n        \r\n    end\r\n\r\n\r\n%>\r\n\r\n<%= headers.inspect %>\r\n<hr/>\r\n<%= list.inspect %>\r\n\r\n',NULL,NULL,NULL,'2018-10-23 09:40:47','2018-10-23 09:40:47','import_csv',''),(3727,'index',1467,2,'<style>\r\n    .bb {\r\n    padding: 6px 12px;\r\n        font-size:14px;\r\n    }\r\n</style>\r\n<div class=\"row-fluid\" style=\"font-size:1.2em\">\r\n    <div class=\"col-lg-12\">\r\n        <center><br /><p></p>\r\n            <%= form_for :search, :url=>\"search?update=panel\", :data=>{:remote=>true} do |f| %>\r\n            ค้นหาหมายเลขลงทะเบียน เลขที่ใบประกอบ อีเมลล์ หรือ หมายเลขโทรศัพท์ <br/>\r\n            <br/><%= f.text_field :query ,:style=>\"padding:10px;height:40px;font-size:1.2em\"%><br/>\r\n            <br/>\r\n\r\n            <%= f.submit \'Search\', :class=>\'btn-success bb\',:data=>{ :disable_with=>\'Loading..\'}%> \r\n            <% end %>\r\n        </center>\r\n        \r\n        <div class=\"row-fluid\">\r\n           <div id=\"panel\" class=\"span12\" style=\"overflow:hidden\">\r\n               <center><a href=\"../Member/index\">...</a></center>\r\n           </div>\r\n        </div>\r\n        <% if @current_role==\'developer\' %>\r\n        <%= get_model(\'member\').where(:arrived=>\'true\').count%> / <%= get_model(\'member\').count%>\r\n        <% end %>\r\n    </div>\r\n</div>',NULL,NULL,NULL,'2018-10-23 09:49:15','2018-10-23 0