=>\'\'}, \'$or\'=>[{:first_name=>rq},{:last_name=>rq},{:license_id=>rq},{:user_id=>q},{:email=>rq},{:mobile=>rq},{:workplace=>rq}] ).sort(:first_name).all\r\n    \r\n    \r\n\r\n%>\r\n<table class=\"table\" style=\"font-size:0.7em;border:0px solid;width:100%\" >\r\n    <thead>\r\n        <tr>\r\n            <% for j in fields %>\r\n           \r\n            <th>\r\n                <%=j.to_s.humanize %>\r\n            </th>\r\n            <% end %>\r\n             <th>\r\n                Action\r\n            </th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n    <% for i in records %>\r\n        <tr>\r\n        <% for j in fields %>\r\n            <td>\r\n                <%=link_to i[j], \"../Member/show?id=\\\\#{i.id}\" if i[j] %>\r\n            </td>\r\n            \r\n            <% end %>\r\n             <td>\r\n                <%=link_to \"Select\", \"../Member/edit?id=\\\\#{i.id}\",:class=>\"btn btn-info\" %>\r\n            </td>\r\n        </tr>\r\n    <% end %>\r\n    </tbody>\r\n</table>',NULL,NULL,NULL,'2018-10-23 11:17:05','2018-10-23 11:17:05','search',''),(3730,'clone',1324,2,'<%\r\n\r\n    models = get_model\r\n    \r\n    sheet = models[:pl_sheet].find(params[:id])\r\n    \r\n    pdoc = models[:project_document].where(:document_id=>sheet.id).first\r\n    \r\n    periods = models[:pl_period].where(:sheet_id=>sheet.id).all\r\n    \r\n    period_products = models[:pl_period_product].where(:sheet_id=>sheet.id).all\r\n    \r\n    period_items = models[:pl_period_item].where(:sheet_id=>sheet.id).all\r\n    \r\n    \r\n    new_sheet = sheet.dup \r\n    \r\n    new_pdoc = pdoc.dup\r\n    \r\n    new_sheet.version =  \"\\\\#{ new_sheet.version} copy\"\r\n    \r\n    new_sheet.save\r\n    \r\n    new_pdoc.update_attributes :document_id=>new_sheet.id\r\n    \r\n    period_map = {}\r\n    product_map = {}\r\n    \r\n    \r\n    \r\n    for i in periods\r\n    \r\n        p = i.dup\r\n   \r\n        p.update_attributes :sheet_id=>new_sheet.id\r\n        period_map[i.id] = p.id\r\n    \r\n    end\r\n    \r\n    for i in period_products\r\n    \r\n        p = i.dup\r\n        p.update_attributes :sheet_id=>new_sheet.id\r\n        product_map[i.id] = p.id\r\n        \r\n        list = models[:pl_period_product_bom].where(:period_product_id=>i.id).all\r\n        for j in list\r\n            g = j.dup\r\n            \r\n            g.update_attributes :period_product_id=>p.id\r\n            \r\n        end\r\n        \r\n    \r\n    end\r\n    l = []\r\n    for i in period_items\r\n        p = i.dup\r\n        new_period = period_map[i.period_id]\r\n        new_product = product_map[i.period_product_id] \r\n        if new_period and new_product\r\n            \r\n         p.update_attributes :sheet_id=>new_sheet.id, :period_id=>new_period, :period_product_id=>new_product\r\n          l <<  p   \r\n            \r\n        end\r\n        \r\n    end\r\n    \r\n    \r\n\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"../Project/show?id=<%=pdoc.project_id if new_sheet%>&active=protocol\"\r\n//-->\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2018-10-23 15:17:26','2018-10-23 15:17:26','clone',''),(3731,'destroy',1324,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  docx =  get_model(\'project_document\').where(:document_id=>params[:id]).first\r\n  project_id = docx.project_id\r\n  docx.destroy\r\n  @record.destroy \r\n  \r\n  models = get_model\r\n  id = @record.id\r\n  \r\n  for i in models[:pl_period].where(:sheet_id=>id).all\r\n    i.destroy\r\n  end\r\n  \r\n  for i in models[:pl_period_product].where(:sheet_id=>id).all\r\n    i.destroy\r\n  end\r\n  \r\n  for i in models[:pl_period_item].where(:sheet_id=>id).all\r\n    i.destroy\r\n  end\r\n  \r\n  \r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=../Project/show?id=<%=project_id%>\">',NULL,NULL,NULL,'2018-10-23 15:56:09','2018-10-23 15:56:09','destroy',''),(3732,'destroy',1385,3,'<%\r\n  model = get_model(thi