ition: absolute;\r\n            top: 200px;\r\n            left: 5px;\r\n            font-size: 25px;\r\n            width: 360px;\r\n            border: 0px solid;\r\n        }\r\n    .barcode {\r\n            position: absolute;\r\n            top: 290px;\r\n            left: 0px;\r\n            font-size: 14px;\r\n            width: 380px;\r\n            border: 0px solid;\r\n    }\r\n    </style>\r\n</head>\r\n<!--<body style=\"padding-top:40px;padding-left:38px;padding-right:0px;border:0px solid\">\r\n-->\r\n<%\r\nleft = 45\r\nleft = 10 if params[:ipad]\r\nw = 760\r\nw = 780 if params[:ipad]\r\n\r\n%>\r\n<body style=\"padding-top:40px;padding-left:<%=left%>px;padding-right:0px;border:0px solid\">\r\n<% \r\n3.times do |t| \r\np = true\r\np = false if params[:p] and params[:p].to_i!=t\r\n\r\n%>\r\n<div class=\"box\" style=\"top:<%=0%>px;border:0px solid;padding-right:15px;overflow:hidden;<%=\'height:345px\' if t==2%>\">\r\n<div class=\"\" style=\"; border:0px solid; position: relative; width:767px; height:360px;overflow:hidden;\">\r\n<% if p %>\r\n<div style=\"text-align:left\">\r\n<img src=\"/esm/sxendo/www/card-new-small.jpg\"  style=\"width:<%=w%>px;height:365px;margin:0px;margin-left:0px;margin-top:-15px;border:0px solid\" >    \r\n</div>\r\n   <div class=\"content\">\r\n<%= @record.first_name %>\r\n<%= @record.last_name %>\r\n<%\r\n    second = @record.country \r\n    second = @record.workplace if second==\'Thailand\'\r\n%>\r\n<p style=\"margin-top: 7px;font-size:0.9em\"><% if @record.country == \"\" %>Thailand <% end %><%= second %></p>\r\n    </div> \r\n\r\n<div class=\"barcode\">\r\n    <center></center>\r\n    <%= image_tag \"/barcode?code=\\\\#{@record.member_id}\",:style=>\"width:200px;vertical-align:middle;height:38px\" %><br/>\r\n    \r\n    <%=@record.member_id%>\r\n    \r\n</div>\r\n<% end %>\r\n</div>\r\n</div>\r\n<% end %>    \r\n<script>\r\n    window.print();\r\n</script>    \r\n</body>\r\n</html>',NULL,NULL,NULL,'2018-10-27 03:47:25','2018-10-27 03:47:25','print',''),(3738,'context_menu',1461,4,'',NULL,NULL,NULL,'2018-10-29 02:47:29','2018-10-29 02:47:29','context_menu',''),(3739,'records',1279,2,'<%\r\n\r\n    models = get_model\r\n    user = models[:user].where(:login=>@current_user.login).first\r\n    \r\n    \r\n    # list = models[:rdu_form].where(:user_id=>user.id).all\r\n    \r\n    periods = models[:period].all\r\n\r\n%>\r\n\r\n\r\n\r\n<h3>รายการแบบประเมิน <%= user.name if user  %></h3><br>\r\n\r\n\r\n\r\n<% if user %>\r\n<table class=\"table\">\r\n    <% for i in periods \r\n    \r\n       record  = models[:rdu_form].where(:user_id=>user.id, :period_id=> i.id).first\r\n\r\n    %>\r\n    <tr>\r\n        <td>\r\n            ผลการประเมิน\r\n        </td>\r\n          <td>\r\n            <%=i.name %>\r\n        </td>\r\n        <td>\r\n            <% if record %>\r\n            <%=link_to \'Show\', \"../RduForm/show?id=\\\\#{record.id}\", :class=>\'btn btn-info btn-small\' %>\r\n            <%=link_to \'Delete\', \"../RduForm/destroy?id=\\\\#{record.id}\", :class=>\'btn btn-danger btn-small\' %>\r\n            <% else %>\r\n            <%=link_to \'Create\', \"../RduForm/create?record[period_id]=\\\\#{i.id}\", :class=>\'btn btn-success btn-small\' %>\r\n            <% end %>\r\n            \r\n        </td>\r\n    </tr>\r\n    <% end %>\r\n    \r\n</table>\r\n<% end %>\r\n\r\n\r\n',NULL,NULL,NULL,'2018-10-29 02:53:52','2018-10-29 02:53:52','records',''),(3741,'',1461,1,'<html>\r\n\r\n<%\r\n   model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n%>\r\n\r\n</p>\r\n<head>\r\n    <title>Print</title>\r\n    <style>\r\n    body { margin: 0px;\r\n    padding: 0px;\r\n        \r\n    }\r\n    .box { padding 0px; margin:0px; border:1px solid;\r\n        width:1000px;\r\n            position: relative;\r\n    text-align: center;\r\n        }\r\n    .content {      position: absolute;\r\n    top: 230px;\r\n    left: 0px;\r\n    font-size: 25px;\r\n    width: 500px;\r\n    border: 0px solid;\r\n        }\r\n    </style>\r\n</head>\r\n\r\n<body>\r\n<div class=\"box\">\r\n\r\n\r\ndata\r\n</div>\r\n\r\n</body>\r\n</html>',NULL,NULL,NULL,'2018-10-29 05:46:38','2018-10-29 05:46:38','',''),(3745,'form',1461,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n  \r\n    models = get_model\r\n    user = models[:user].where(:login=>@current_user.login).first\r\n    \r\n    if params[:period_id]\r\n        period = models[:period].find params[:period_id]\r\n    else\r\n        period = models[:period].find @record.period_id\r\n    end\r\n  \r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<%= text_field_tag \"record[user_id]\",user.id  if user %>\r\n<%= text_field_tag \"record[period_id]\",period.id  if period %>\r\n\r\n<%= text_field_tag \"return_url\", \"../Home/index\"  %>',NULL,NULL,NULL,'2018-10-29 05:54:32','2018-10-29 05:54:32','',''),(3747,'export_data',1279,3,'<script type=\"text/javascript\">\r\nconsole.log(\"ok\")\r\nfunction download_csv(csv, filename) {\r\n    var csvFile;\r\n    var downloadLink;\r\n\r\n    // CSV FILE\r\n    csvFile = new Blob([csv], {type: \"text/csv\"});\r\n\r\n    // Download link\r\n    downloadLink = document.createElement(\"a\");\r\n\r\n    // File name\r\n    downloadLink.download = filename;\r\n\r\n    // We have to create a link to the file\r\n    downloadLink.href = window.URL.createObjectURL(csvFile);\r\n\r\n    // Make sure that the link is not displayed\r\n    downloadLink.style.display = \"none\";\r\n\r\n    // Add the link to your DOM\r\n    document.body.appendChild(downloadLink);\r\n\r\n    // Lanzamos\r\n    downloadLink.click();\r\n}\r\n\r\nfunction export_table_to_csv(html, filename) {\r\n var csv = [];\r\n var rows = document.querySelectorAll(\"table tr\");\r\n\r\n    for (var i = 0; i < rows.length; i++) {\r\n  var row = [], cols = rows[i].querySelectorAll(\"td, th\");\r\n\r\n        for (var j = 0; j < cols.length; j++) \r\n            row.push(cols[j].innerText);\r\n\r\n  csv.push(row.join(\",\"));  \r\n }\r\n\r\n    // Download CSV\r\n    download_csv(csv.join(\"\\n\"), filename);\r\n}\r\n\r\ndocument.querySelector(\"button\").addEventListener(\"click\", function () {\r\n    var html = document.querySelector(\"table\").outerHTML;\r\n export_table_to_csv(html, \"table.csv\");\r\n});\r\n</script>\r\n\r\n\r\n<style>\r\n    table { font-size:12px }\r\n    table tr { font-size:12px }\r\n    \r\n</style>\r\n\r\n<button> CSV download</button>\r\nรายงานตัวชี้วัดโครงการโรงพยาบาลส่งเสริมการใช้ยาอย่างสมเหตุผล RDU Hospital Project <br />\r\n\r\nชื่อโรงพยาบาล<br />\r\n\r\nชื่อผู้รับผิดชอบในการรายงานตัวชี้วัด<br />\r\n\r\nโทรศัพท์<br />\r\n\r\nหมายหตุ: ดูรายละเอียดวิธีการคำนวณตัวชี้วัดจากคู่มือตัวชี้วัดโครงการโรงพยาบาลส่งเสริมการใช้ยาอย่างสมเหตุผล<br /><br />\r\n\r\n<div style=\"font-size:14px\" id=\"dvData\">\r\n\r\n<table id=\"testTable\" summary=\"Code page support in different versions of MS Windows.\" rules=\"groups\" frame=\"hsides\" border=\"2\">\r\n  <col width=\"101\" />\r\n  <col width=\"263\" />\r\n  <col width=\"387\" />\r\n  <col width=\"70\" />\r\n  <col width=\"65\" />\r\n  <col width=\"70\" span=\"4\" />\r\n  <col width=\"72\" />\r\n  <tr>\r\n    <td width=\"101\">รหัสตัวชี้วัด</td>\r\n    <td width=\"263\">ชื่อตัวชี้วัด</td>\r\n    <td width=\"387\">เป้าหมาย</td>\r\n    <td width=\"70\">ข้อมูล    Baseline  ต.ค.57-มี.ค.58</td>\r\n    <td width=\"65\">ข้อมูล Baseline    เม.ย.-ก.ย.58</td>\r\n    <td width=\"70\">ผลการดำเนินงาน    ต.ค.58-มี.ค.59</td>\r\n    <td width=\"70\">ผลการดำเนินงาน    เม.ย.-ก.ย.59</td>\r\n    <td width=\"70\">ผลการดำเนินงาน    ต.ค.59-มี.ค.60</td>\r\n    <td width=\"70\">ผลการดำเนินงาน    เม.ย.-ก.ย.60</td>\r\n    <td width=\"72\">ผลการดำเนินงาน    ต.ค.60-มี.ค.61</td>\r\n  </tr>\r\n  <tr>\r\n    <td colspan=\"2\" width=\"364\">ตัวชี้วัดหลัก</td>\r\n    <td width=\"387\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">C-I-01</td>\r\n    <td align=\"left\" width=\"263\">จำนวนรายการยาเฉลี่ยต่อผู้ป่วยที่มารับบริการที่แผนกผู้ป่วยนอก</td>\r\n    <td width=\"387\">น้อยกว่าหรือเท่ากับ    3.0 รายการ</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">C-I-02</td>\r\n    <td align=\"left\" width=\"263\">ร้อยละการสั่งยาในบัญชียาหลักในผู้ป่วยนอก</td>\r\n    <td width=\"387\">มากกว่าหรือเท่ากับ    85%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">C-I-03</td>\r\n    <td align=\"left\" width=\"263\">จำนวนยาปฏิชีวนะชนิดรับประทานที่สั่งใช้ต่อ 1000 ประชากรต่อวัน    (หน่วยเป็นจำนวน Defined Daily Dose ต่อ 1000 ประชากรต่อวัน)</td>\r\n    <td width=\"387\">ลดลง    20% เมื่อเปรียบเทียบกับจำนวนก่อนเริ่มโครงการ (baseline)</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">ตัวชี้วัดรอง</td>\r\n    <td width=\"263\">&nbsp;</td>\r\n    <td width=\"387\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"101\">Es</td>\r\n    <td align=\"left\" width=\"263\">เลือกรายงาน    6 จาก 14  ตัวชี้วัด</td>\r\n    <td colspan=\"2\" width=\"457\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">E-HT-I-01</td>\r\n    <td align=\"left\" width=\"263\">ร้อยละของผู้ป่วยความดันเลือดสูงที่ใช้    RAS blockage (ACEIs/ARBs/Renin inhibitor) 2    ชนิดร่วมกันในการรักษาโรคความดันเลือดสูง</td>\r\n    <td width=\"387\">0%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">E-DM-I-01</td>\r\n    <td align=\"left\" width=\"263\">ร้อยละของผู้ป่วยที่ใช้ glibenclamide ในผู้ป่วยที่มีอายุมากกว่า    65 ปีหรือมี eGFR &lt; 60 มล./นาที/1.73 ตารางเมตร</td>\r\n    <td width=\"387\">น้อยกว่าหรือเท่ากับ    5%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"2\" width=\"101\">E-DM-I-02</td>\r\n    <td rowspan=\"2\" width=\"263\">ร้อยละของผู้ป่วยเบาหวานที่ใช้ยา    metformin เป็นยาชนิดเดียวหรือร่วมกับยาอื่นเพื่อควบคุมระดับน้ำตาล    โดยไม่มีข้อห้ามใช้ ตามข้อแนะนำ E-DM-R-01</td>\r\n    <td rowspan=\"2\" width=\"387\">มากกว่าหรือเท่ากับ    80%</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"65\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr> </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">E-DLP-I-01</td>\r\n    <td align=\"left\" width=\"263\">ร้อยละของผู้ป่วยที่มีภาวะไขมันในเลือดสูง/ผิดปกติที่ได้รับ statin    ซึ่งเป็น moderate หรือ high intensity statin ตามบัญชียาหลักแห่งชาติ    (simvastatin 20-40 มก. หรือ atorvastatin 40 มก.)</td>\r\n    <td width=\"387\">มากกว่าหรือเท่ากับ    80%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">E-OA-I-01</td>\r\n    <td align=\"left\" width=\"263\">ร้อยละของผู้ป่วยโรคข้อเสื่อมที่มีการใช้ยากลุ่ม NSAIDs ซ้ำซ้อน</td>\r\n    <td width=\"387\">น้อยกว่าหรือเท่ากับ    5%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"101\">E-GOUT-I-01</td>\r\n    <td width=\"263\">ผู้ป่วยโรคข้ออักเสบเกาต์ที่มีข้อบ่งชี้ในการรักษาด้วยยาลดกรดยูริก    ที่ได้รับยาลดกรดยูริกในเลือด และปรับขนาดยาจนระดับกรดยูริกในเลือดน้อยกว่า 6    มก./ดล. ภายใน 1 ปี    หลังจากเริ่มรักษา</td>\r\n    <td width=\"387\">มากกว่าหรือเท่ากับ    60%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"2\" width=\"101\">E-CKD-I-01</td>\r\n    <td rowspan=\"2\" width=\"263\">ร้อยละผู้ป่วยโรคไตเรื้อรังระดับ    3 ขึ้นไปที่ได้รับ NSAIDs </td>\r\n    <td rowspan=\"2\" width=\"387\">น้อยกว่าหรือเท่ากับ    10%</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"65\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr> </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">E-ASTH-I-01</td>\r\n    <td align=\"left\" width=\"263\">ร้อยละผู้ป่วยโรคหืดที่ได้รับยา inhaled corticosteroid</td>\r\n    <td width=\"387\">มากกว่าหรือเท่ากับ    80%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">E-COPD-I-01</td>\r\n    <td align=\"left\" width=\"263\">โรงพยาบาลมีระบบการบริหารจัดการ    และการประเมินการรักษาโรคปอดอุดกั้นเรื้อรัง ที่ครบวงจร เพื่อให้ผู้ป่วยนอก    และผู้ป่วยในได้รับยาอย่างสมเหตุผล</td>\r\n    <td width=\"387\">มากกว่าหรือเท่ากับ    80%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">E-RI-I-01</td>\r\n    <td width=\"263\">ร้อยละการใช้ยาปฏิชีวนะในโรคติดเชื้อที่ระบบการหายใจช่วงบนและหลอดลมอักเสบเฉียบพลันในผู้ป่วยนอก</td>\r\n    <td width=\"387\">น้อยกว่าหรือเท่ากับ    20%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">E-AD-I-01</td>\r\n    <td width=\"263\">ร้อยละการใช้ยาปฏิชีวนะในโรคอุจจาระร่วงเฉียบพลัน</td>\r\n    <td width=\"387\">น้อยกว่าหรือเท่ากับ    20%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">E-STW-I-01</td>\r\n    <td width=\"263\">ร้อยละการใช้ยาปฏิชีวนะในบาดแผลสดจากอุบัติเหตุ</td>\r\n    <td width=\"387\">น้อยกว่าหรือเท่ากับ    40%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">E-APL-I-01</td>\r\n    <td width=\"263\">ร้อยละการใช้ยาปฏิชีวนะในหญิงคลอดปกติครบกำหนดทางช่องคลอด</td>\r\n    <td width=\"387\">น้อยกว่าหรือเท่ากับ    10%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"101\">E-FOR-I-01</td>\r\n    <td width=\"263\">รายการยาที่ควรพิจารณาตัดออก 8 รายการ    ที่ยังคงมีเหลืออยู่ในบัญชียาโรงพยาบาล</td>\r\n    <td width=\"387\">ไม่เกิน    1 รายการ</td>\r\n    <td>&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"101\">S</td>\r\n    <td colspan=\"3\" align=\"left\" width=\"720\">เลือกรายงาน 6 จาก 10 ตัวชี้วัด</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">S-GER-I-01</td>\r\n    <td align=\"left\" width=\"263\">ร้อยละผู้ป่วยนอกสูงอายุที่ใช้ยากลุ่ม    long-acting benzodiazepine ได้แก่ chlordiazepoxide, diazepam, dipotassium    chlorazepate </td>\r\n    <td width=\"387\">น้อยกว่าหรือเท่ากับ    5%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">S-GER-I-02</td>\r\n    <td align=\"left\" width=\"263\">ร้อยละของผู้ป่วยในสูงอายุที่ได้รับยามากกว่า 5    รายการและได้รับการประสานรายการยา (medication reconciliation)</td>\r\n    <td width=\"387\">มากกว่าหรือเท่ากับ    50%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"101\">S-PRG-I-01</td>\r\n    <td width=\"263\">จำนวนสตรีตั้งครรภ์ที่ได้รับยาที่ห้ามใช้    ได้แก่ยา Warfarin,Statins หรือ Ergots เมื่อรู้ว่าตั้งครรภ์แล้ว *ยกเว้นกรณีใส่    mechanical heart valve</td>\r\n    <td width=\"387\">0    คน</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"2\" width=\"101\">S-LAC-I-01</td>\r\n    <td rowspan=\"2\" width=\"263\">ร้อยละของสตรีให้นมบุตรที่ได้รับการสั่งจ่ายยากระตุ้นการหลั่งน้ำนม    ได้แก่ metoclopramide หรือ domperidone ภายใน 10 วันหลังคลอด</td>\r\n    <td rowspan=\"2\" width=\"387\">0%</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"65\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr> </tr>\r\n  <tr>\r\n    <td width=\"101\">S-PED-I-01</td>\r\n    <td align=\"left\" width=\"263\">ร้อยละการได้รับยาต้านฮิสตามีนชนิด non-sedating     ในเด็กที่ได้รับการวินิจฉัยเป็นโรคติดเชื้อของทางเดินหายใจ    (ครอบคลุมโรคตามรหัส ICD-10 ของโครงการ Antibiotic Smart Use, ASU) </td>\r\n    <td width=\"387\">น้อยกว่าหรือเท่ากับ    20%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"2\" width=\"101\">S-CKD-I-02</td>\r\n    <td rowspan=\"2\" width=\"263\">ร้อยละของผู้ป่วยเบาหวานร่วมกับโรคไตเรื้อรังระยะ    3 ขึ้นไป ที่เกิดภาวะ metformin associated lactic acidosis </td>\r\n    <td rowspan=\"2\" width=\"387\">น้อยกว่าหรือเท่ากับ    10%</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"65\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"70\">&nbsp;</td>\r\n    <td rowspan=\"2\" width=\"72\">&nbsp;</td>\r\n  </tr>\r\n  <tr> </tr>\r\n  <tr>\r\n    <td align=\"left\" width=\"101\">S-CKD-I-03</td>\r\n    <td align=\"left\" width=\"263\">ร้อยละของผู้ป่วยโรคไตเรื้อรังที่ได้รับรายการยา/กลุ่มยาที่ควรหลีกเลี่ยงในผู้ป่วยโรคไต</td>\r\n    <td width=\"387\">น้อยกว่าหรือเท่ากับ    20%</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"65\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"70\">&nbsp;</td>\r\n    <td width=\"72\">&nbsp;</td>\r\n  </tr>\r\n</table>\r\n\r\n</div>',NULL,NULL,NULL,'2018-10-29 06:41:51','2018-10-29 06:41:51','export_data',''),(3748,'destroy',1280,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  @record.destroy \r\n%>\r\n<meta http-equiv=\"refresh\" content=\"3;url=http://rdu.emr-life.com/www/Home/records\">',NULL,NULL,NULL,'2018-10-29 08:32:47','2018-10-29 08:32:47','destroy',''),(3749,'show',1280,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Back\', \'../Home/records\' %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-10-29 08:36:59','2018-10-29 08:36:59','show',''),(3750,'index',1471,2,'\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Solution\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE</b></center><br/>\r\n    <%= render :inline=>this.module %>\r\n</div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n<% \r\n\r\n    model = get_model\r\n    patient_model = model[:patient]\r\n    patient_module_model = model[:patient_module]\r\n    modules = @context.get_projects_by_abstract \'ehr.emr\' \r\n   \r\n\r\n    \r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n\r\n<%\r\ndb = patient_model.collection.db\r\n%>\r\n<%#db.class%>\r\n<%#db.collection_names.sort%>\r\n<%#db.collection(\'colo.appointment\').count%>\r\n\r\n<%\r\nfor m in modules\r\n  \r\n    list = db.collection(\"\\\\#{m.name}.appointment\").group({:keyf=>\'function(doc){return {month:doc.date.getMonth()};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:status=>{\'$in\'=>[\'Completed\',\'Recovery\',\'Processing\']},:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}})\r\n        columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n        \r\n    if list.size>0    \r\n    data = []\r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    data[i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\n    \r\n\r\n%>\r\n<%#list.inspect%>\r\n<div id=\"chart-<%=m.id%>\" style=\"border:0px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n<%#columns.to_json%>\r\n            <script>\r\n                    $(\"#chart-<%=m.id%>\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"<%=m.title%> Patients by Month\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: [{\r\n                            name: \"Patients\",\r\n                            data: <%=data.to_json.html_safe %>\r\n                        }],\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                \r\n\r\n             \r\n            </script>                 \r\n\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        System Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    \r\n<table class=\"table table-striped table-bordered table-condensed\">\r\n<thead>\r\n<tr>\r\n<th>Title</th>\r\n<th>Value</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Disk Space</td>\r\n<%\r\n   size = patient_model.collection.db.stats[\'storageSize\']\r\n   unit = \'B\'\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'KB\'\r\n   size /= 1000\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'MB\'\r\n   size /= 1000\r\n   \r\n   if size/1000 > 1 \r\n   unit = \'GB\'\r\n   size /= 1000\r\n   \r\n   end\r\n   end\r\n   end\r\n   \r\n   \r\n\r\n%>\r\n\r\n<td><%=format(\'%.2f\',size)%> <%=unit%></td>\r\n</tr>\r\n<tr>\r\n<td>Total Patient</td>\r\n<td><%= (model[:patient]).count %></td>\r\n</tr>\r\n<tr>\r\n<td>Total Module</td>\r\n<td><%= modules.size %></td>\r\n</tr>\r\n<tr>\r\n\r\n</tr>\r\n<tr>\r\n<td>Total Record</td>\r\n<td><%= (model[:patient_module]).count %></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Support\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <%= link_to \'Inventory System\', \'../../inventory/Home/index\',:class=>\'btn\' %>\r\n   \r\n</div>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-10-30 10:50:19','2018-10-30 10:50:19','',''),(3751,'context_menu',1471,4,'',NULL,NULL,NULL,'2018-10-30 10:50:56','2018-10-30 10:50:56','context_menu',''),(3752,'opd',1363,2,'<%# view :fullwidth %>\r\n<style>\r\n.navbar .nav {\r\ndisplay:none; \r\n}\r\n.sidebar_inner {\r\n   display:none;  \r\n}             \r\n                  \r\n</style>\r\n<!-- datatable -->\r\n            <script src=\"/gebo/lib/datatables/jquery.dataTables.min.js\"></script>\r\n            <script src=\"/gebo/lib/datatables/extras/Scroller/media/js/Scroller.min.js\"></script>\r\n            <!-- datatable functions -->\r\n            <script src=\"/gebo/js/gebo_datatables.js\"></script>\r\n<%\r\n	module_name = @current_project.name if @current_project\r\n	if params[:date]\r\n	session[module_name]={:date=>params[:date],:stamp=>Time.now.strftime(\'%d/%m/%Y\')}\r\n	end\r\n	if session[module_name] and session[module_name][:stamp] == Time.now.strftime(\'%d/%m/%Y\')\r\n	  params[:date] = session[module_name][:date]\r\n	end\r\n	unless params[:date]\r\n	params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n	end\r\n	his = session[:his]\r\n	user = @current_user\r\n%>\r\n	\r\n<%#session[module_name].inspect %>\r\n<%\r\n	ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    \r\n    if params[:reset_lock]\r\n	    l = get_model[:locker].find(params[:reset_lock])\r\n        l.destroy if l\r\n	end\r\n	if p = params[:record]\r\n        p_app = params[:app]\r\n        \r\n        m_appointment = get_model[:appointment]\r\n        \r\n        if p[:birth_date].length <= 2\r\n            cur_year = Time.now.year\r\n            dif_year = cur_year - p[:birth_date].to_i\r\n            p[:birth_date] = \"01/01/\" + dif_year.to_s\r\n        elsif !p[:birth_date].empty?\r\n            date = Date.parse(p[:birth_date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p[:birth_date] = new_date\r\n            end \r\n        end\r\n        if !p_app[:date].empty?\r\n            date = Date.parse(p_app[:date])\r\n            year = date.strftime(\"%Y\").to_i\r\n            if year > 2400\r\n                year = year - 543\r\n                new_date = year.to_s + \"-\" + date.strftime(\"%m-%d\")\r\n                p_app[:date] = new_date\r\n            end \r\n        end\r\n        \r\n        patient = patient_model.where(:hn=>p[:hn]).first\r\n        if  patient\r\n            msg = \"Appointment added.\"\r\n            err = false\r\n        else\r\n            patient = patient_model.create p\r\n            msg = \"Patient created. Appointment added.\"\r\n        end\r\n        \r\n        p_app[:stop] = p_app[:start]\r\n        \r\n        p_app[:stop] =  (Time.parse(p_app[:start])+params[:duration].to_i*60).to_mongo\r\n        \r\n        \r\n        rec_app = m_appointment.create p_app\r\n        rec_pm_app = module_model.create :ref_number=>\'0000\', :patient_id=>patient.id, :date=>p[:date], :time=>Time.now.strftime(\"%H:%M\"), :module_name=>\"\\\\#{@current_project.name}#appointment\", :module_id=>rec_app.id, :created_by=>p_app[:created_by], :updated_by=>p_app[:updated_by]\r\n    \r\n        cmd = params[:commit]\r\n        if cmd == \"Patient Record\"\r\n            \r\n            \r\n%>\r\n<script>\r\n    window.location = \'patient_record?id=<%= rec_app.id %>\';\r\n    // window.location = \"../OutPatientForm/create?patient_id=<%=patient.id.to_s%>&record_name=<%=patient[:hn]%>&parent_id=<%=rec_pm_app.id.to_s%>&return=../Home/opd\";\r\n</script>\r\n<%\r\n    else\r\n %>\r\n<script>\r\n    window.location = \'index\';\r\n    // window.location = \"../OutPatientForm/create?patient_id=<%=patient.id.to_s%>&record_name=<%=patient[:hn]%>&parent_id=<%=rec_pm_app.id.to_s%>&return=../Home/opd\";\r\n</script>\r\n<%      \r\n    end\r\n    end\r\n	\r\n	\r\n	\r\n	if params[:obj_id]\r\n	    now = Time.now \r\n	\r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n	end\r\n%>\r\n<% user.inspect %>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span8\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Dashboard\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\">\r\n				<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center>\r\n				<br/>\r\n				<center>\r\n					<!--<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Add Visit</button></a>-->\r\n					<a href=\"/user/logout\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Logout</button></a>\r\n				</center>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	<div class=\"span4\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				Status\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n				<div class=\"alert alert-block alert-info\" >\r\n					<%\r\n						begin        \r\n						     date = Time.now\r\n						     date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n						 %>\r\n					Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\' %> <br/>\r\n					<h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n					<%=link_to \"\\\\#{ date.strftime(\'%A %d %B %Y\') }\", \"../Home/opd?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n				</div>\r\n				<script>\r\n					$(\"#today-date\").kendoDatePicker({\r\n					    value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n					    change: function(){\r\n					        window.location = \"../Home/opd?date=\"+kendo.toString(this.value(), \'d\')\r\n					    }\r\n					});\r\n				</script>\r\n				<% rescue %>\r\n				error\r\n				<% end %>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<style>\r\n	.status_cls{\r\n	width:100px\r\n	}\r\n</style>\r\n<script>\r\n	function change_status(obj){\r\n	  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n	   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n	  }\r\n	 }\r\n</script>\r\n\r\n<div id=\'patient_content\'>\r\n    <center>... Loading ...</center>\r\n</div>\r\n\r\n<%\r\n    s_date = date.strftime(\'%d/%m/%Y\')\r\n    a_app = get_model[:appointment].all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n\r\n    pdate = date.strftime(\"%d/%m/%Y\")\r\n    \r\n    def r_map(rs)\r\n        return rs.collect{|i| [i.id.to_s, i[:name]]}\r\n    end\r\n    \r\n    map_visit = r_map(get_model[:visit_type].all)\r\n    map_prov = r_map(get_model[:provider].where(:provider_type=>{\'$in\'=>[\'1\',\'4\']}).all)\r\n    map_proc = r_map(get_model[:procedure].all)\r\n    map_ind = r_map(get_model[:indication].all)\r\n%>\r\n<div class=\"modal hide fade\" id=\"modal\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n    <div class=\"modal-header\">\r\n        <a href=\"#\" class=\"close\" style=\"float:right;\"  data-dismiss=\"modal\">X</a>\r\n        <h3>Add Patient</h3>\r\n    </div>\r\n    <div class=\"modal-body\"  style=\"background: #f5f5f5;\">\r\n    <%= form_for :record , :url=>params[:opt] do |f| %>\r\n<%# f.hidden_field :provider, :value=>params[:data][:provider] %>\r\n        <%= f.hidden_field :date, :value=>pdate %>\r\n        <div class=\"w-box\">\r\n            <div class=\"form-horizontal\">\r\n                <div id=\"hn\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>HN <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input autofocus type=\"text\" name=\"record[hn]\" id=\"data-hn\" size=\"29\" style=\"float:left;vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\" />\r\n                    \r\n                    \r\n                    \r\n                </div>\r\n                <div class=\"portlet\" style=\"margin: 0 0.5em 0.5em 0\">\r\n                <span class=\"\"><label>&nbsp;</label></span>	\r\n                    <a href=\"#\" id=\"get-hn\" class=\"btn\" style=\"float:left;height:15px\">GET</a>\r\n                    \r\n                </div>\r\n               \r\n                \r\n                \r\n                 <div id=\"appointed_date\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;margin-top:-5px;\">\r\n                    <span class=\"\"><label>Appointed Date : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 150px;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[date]\" id=\"data-date\" value=\"<%= pdate %>\" style=\"width: 100px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\">\r\n                        <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-date\").kendoDatePicker({\r\n                        		value: \'<%= pdate %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <div id=\"start\" class=\" portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;margin-top:-5px;\">\r\n                    <span class=\"\"><label>Time <span class=\"f_req\">*</span>  : </label></span>\r\n                    <span class=\"k-widget k-timepicker k-header\" style=\"width: 150px;\">\r\n                        <span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"app[start]\" id=\"data-start\" value=\"\" style=\"width: 80px;\" required=\"required\" validationmessage=\"Cannot be empty\" onKeyPress=\" if ((event.keyCode == 13))  {event.preventDefault();} \" data-role=\"timepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-start_timeview\"/>\r\n                            <span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-start_timeview\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-clock\">select</span>\r\n                            </span>\r\n                        </span>\r\n                    </span>\r\n                    <script>\r\n                    $(\"#data-start\").kendoTimePicker({\r\n                    	value: \'<% Time.now.strftime(\"%H:%M\")%>\',\r\n                    	interval: 30,\r\n                    	parseFormats: [\"HH.mm\",\"HHmm\",\"HH;mm\",\"HH mm\",\"HH,mm\"],\r\n                    	change: function(event){\r\n                    		var v = $(\'#data-start\').val()\r\n                    		if(v.length==3){\r\n                    			$(\'#data-start\').val(v[0]+\":\"+v[1]+v[2])\r\n                    		}\r\n                    		 \r\n                    	}\r\n                    });\r\n                    </script>\r\n            	</div>\r\n            	\r\n                <div id=\"duration\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;margin-top:-5px;\">\r\n                    <span class=\"\"><label>Duration<span class=\"f_req\">*</span> : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"duration\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-duration\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"duration\" id=\"data-duration\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\" value=\"\" required=\"required\" validationmessage=\"Cannot be empty\">\r\n                    </span>\r\n                </div>\r\n            	\r\n            	\r\n            	  <div id=\"appointed_room\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Room <span class=\"f_req\">*</span>: </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                    <%=select_tag \"app[room]\", options_for_select(%w{Room1 Room2 Room3 Room4 Room5 Room6}),:include_blank=>true , :required => true,:style=>\"width:80px\" %>    \r\n                  \r\n\r\n                    </div>\r\n                </div><div class=\"clear\"></div>\r\n<hr/>\r\n\r\n                <div id=\"prefix_name\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;margin-top:-5px;\">\r\n                    <span class=\"\"><label>Prefix name : </label></span>	\r\n                    <span class=\"k-widget k-combobox k-header k-textbox k-textbox-txt\" style=\"vertical-align: text-top; width: 100%;\">\r\n                        <span tabindex=\"-1\" unselectable=\"on\" class=\"k-dropdown-wrap k-state-default\">\r\n                            <input name=\"record[prefix_name]_input\" class=\"k-input k-textbox k-textbox-txt\" type=\"text\" \r\n                                autocomplete=\"off\" tabindex=\"0\" maxlength=\"524288\" style=\"vertical-align: text-top; width: 100%;margin-top:-3px\" \r\n                                aria-disabled=\"false\" role=\"combobox\" aria-expanded=\"false\" aria-autocomplete=\"list\" \r\n                                aria-owns=\"data-demo_listbox\" aria-busy=\"false\" aria-activedescendant=\"data-demo_option_selected\" id=\"input-prefix_name\">\r\n                            <span tabindex=\"-1\" unselectable=\"on\" class=\"k-select\">\r\n                                <span unselectable=\"on\" class=\"k-icon k-i-arrow-s\" role=\"button\" tabindex=\"-1\" aria-controls=\"data-demo_listbox\">select</span>\r\n                            </span>\r\n                        </span>\r\n                        <input type=\"text\" name=\"record[prefix_name]\" id=\"data-prefix_name\" size=\"29\" style=\"vertical-align: text-top; width: 100%; display: none;\" \r\n                            class=\"k-textbox k-textbox-txt\" data-role=\"combobox\" aria-disabled=\"false\">\r\n                    </span>\r\n                </div>\r\n                <div id=\"first_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>First name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[first_name]\" id=\"data-first_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[first_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"last_name\" class=\"  portlet \" style=\"border:0px solid blue;width:200px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Last name <span class=\"f_req\">*</span>  : </label></span>	\r\n                    <input type=\"text\" name=\"record[last_name]\" id=\"data-last_name\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" aria-invalid=\"true\"/>\r\n                    <!--<span class=\"k-widget k-tooltip k-tooltip-validation k-invalid-msg\" data-for=\"record[last_name]\" role=\"alert\"><span class=\"k-icon k-warning\"> </span> Cannot be empty</span>-->\r\n                </div>\r\n                <div id=\"gender\" class=\"  portlet \" style=\"border:0px solid blue;width:80px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Gender : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"record[gender]\" id=\"data-gender\" style=\"width:100%;height:2.0em;border:1px solid #bbb;margin-top:-2px\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"0\">ไม่ระบุ</option>\r\n                            <option value=\"1\">ชาย</option>\r\n                            <option value=\"2\">หญิง</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                <div class=\"clear\"></div>\r\n                 <div id=\"birth_date\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;margin-top:-5px;\">\r\n                    <span class=\"\"><label>Birthdate : </label></span>	\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <span class=\"k-widget k-datepicker k-header\" style=\"width: 100%;\"><span class=\"k-picker-wrap k-state-default\">\r\n                            <input type=\"text\" name=\"record[birth_date]\" id=\"data-birth_date\" value=\"<%= Time.now.strftime(\"%d/%m/%Y\") %>\" style=\"width: 120px;\" data-role=\"datepicker\" class=\"k-input\" role=\"textbox\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-owns=\"data-birth_date_dateview\" aria-disabled=\"false\" aria-label=\"Current focused date is 8 มีนาคม 2015\"><span unselectable=\"on\" class=\"k-select\" role=\"button\" aria-controls=\"data-birth_date_dateview\"><span unselectable=\"on\" class=\"k-icon k-i-calendar\">select</span></span></span></span>\r\n                        <script>\r\n                        	$(\"#data-birth_date\").kendoDatePicker({\r\n                        		value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n                        	});\r\n                        </script>\r\n                    </div>\r\n                </div>\r\n                <!--  <div id=\"public_id\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>เลขที่บัตรประชาชน :</label></span>	\r\n                    <input type=\"text\" name=\"record[public_id]\" id=\"data-public_id\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div> -->\r\n                  \r\n        <!--   <div id=\"procedure\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Procedure : </label></span>	\r\n                    <<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">>\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[procedure]\" id=\"data-procedure\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_proc do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\" selected><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n        -->      \r\n                \r\n               \r\n               \r\n            	<div id=\"indication\" class=\"  portlet \" style=\"border:0px solid blue;width:120px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Indication : </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[indication]\" id=\"data-indication\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_ind do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n<div id=\"ward\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:80px;min-height:30px;margin-top:-5px;\">\r\n\r\n\r\n<span class=\"\"><label>Ward <span class=\"f_req\">*</span>: </label></span>\r\n\r\n	\r\n\r\n<input type=\"text\" name=\"app[ward]\" id=\"data-ward\" value=\"\" size=\"29\" style=\"vertical-align: text-top; width: 100%; \" class=\"k-textbox k-textbox-txt k-invalid\" required=\"required\" validationmessage=\"Cannot be empty\" default=\"default\" data-role=\"combobox\" aria-disabled=\"true\">\r\n    \r\n</div>                \r\n<div class=\"clear\"></div>                \r\n\r\n<div id=\"procedure_list\" class=\"  portlet \" style=\"border:0px solid blue;width:165px;margin: 0 0.5em 0.5em 0;float:left;width:150px;min-height:30px;margin-top:-5px;\">\r\n\r\n\r\n<span class=\"\"><label>Procedure <span class=\"f_req\">*</span>: </label></span>\r\n\r\n	\r\n\r\n<input type=\"text\" name=\"app[procedure_list]\" id=\"data-procedure_list\" value=\"\" size=\"29\" style=\"vertical-align: text-top; width: 100%; \" class=\"k-textbox k-textbox-txt k-invalid\"  data-role=\"combobox\" validationmessage=\"Please select one\"  required=\"required\" validationmessage=\"Cannot be empty\" >\r\n    \r\n</div>\r\n\r\n\r\n <div id=\"provider\" class=\"  portlet \r\nRoom\r\n\r\n |  | Cancel | Delete\" style=\"border:0px solid blue;width:300px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Provider <span class=\"f_req\">*</span>: </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[provider]\" id=\"data-provider\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" class=\"\" validationmessage=\"Please select one\" required=\"required\" validationmessage=\"Cannot be empty\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_prov do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n\r\n<script>\r\n    $(\"#data-procedure_list\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [{\"text\":\"EGD\",\"value\":\"EGD\"},{\"text\":\"Colono\",\"value\":\"Colono\"},{\"text\":\"EGD + Colono\",\"value\":\"EGD + Colono\"},{\"text\":\"Sigmoid\",\"value\":\"Sigmoid\"},{\"text\":\"EUS\",\"value\":\"EUS\"},{\"text\":\"ERCP\",\"value\":\"ERCP\"},{\"text\":\"PEG\",\"value\":\"PEG\"},{\"text\":\"PEG-J\",\"value\":\"PEG-J\"},{\"text\":\"SSE\",\"value\":\"SSE\"},{\"text\":\"NJ\",\"value\":\"NJ\"},{\"text\":\"Liver Bx.\",\"value\":\"Liver Bx.\"}]\r\n	\r\n    });\r\n    \r\n     $(\"#data-ward\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [{\"text\":\"OPD\",\"value\":\"OPD\"},{\"text\":\"IPD\",\"value\":\"IPD\"},{\"text\":\"OR\",\"value\":\"OR\"},{\"text\":\"ICU\",\"value\":\"ICU\"}]\r\n	\r\n    });\r\n</script>\r\n                \r\n                \r\n<%\r\n    if this.his_show\r\n%>\r\n<span id=\'span-his_btn\' style=\'margin-left:20px\'>\r\n\r\n  \r\n  \r\n<% if session[:his]%>\r\n<span id=\'his-status\'>\r\nWelcome <%= session[:his] %>\r\n\r\n  </span>\r\n    <a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient</a>\r\n<% else %>\r\n<span id=\'his-status\'>\r\nPlease login to get HN from HIS\r\n\r\n  </span>\r\n  <span id=\'temp-get-his\'>&nbsp;</span>\r\n            <span class=\'login-block\'>\r\n                <!--<div class=\'clear\'></div>-->\r\n                <div id=\"his-user\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px\">\r\n                    <span class=\"\"><label>Username : </label></span>	\r\n                    <input autofocus=\"\" type=\"text\" name=\"username\" id=\"input-username\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\">\r\n                </div>\r\n                <div id=\"his-pass\" class=\"  portlet \" style=\"border:0px solid blue;width:100px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Password  : </label></span>	\r\n                    <input type=\"password\" name=\"password\" id=\"input-password\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt k-invalid\">\r\n                </div>\r\n                <!--<div class=\'clear\'></div>-->\r\n            </span>\r\n<% end %>\r\n</span>\r\n\r\n<span id=\'span-btn\'>\r\n<% if session[:his] %>\r\n  <a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\r\n<% else %>\r\n  <span id=\'temp-his-logout\'>&nbsp;</span>\r\n  <a href=\'javascript:void(0)\' id=\'his-login\' class=\'btn btn-info\'>HIS Login</a>\r\n<% end %>\r\n</span>\r\n\r\n<% end %>\r\n            \r\n\r\n                <br/>\r\n                <div class=\'login-block btn btn-mini\' id=\'login-cancel\'  >x</div>\r\n                <span style=\'color:blue\' id=\'patient-msg\'></span>\r\n                <div class=\'clear\'></div>\r\n            \r\n                \r\n            	<div class=\"clear\"></div>\r\n            	\r\n               \r\n                <div id=\"visit_type\" class=\"  portlet \" style=\"border:0px solid blue;width:150px;margin: 0 0.5em 0.5em 0;float:left;;min-height:30px;\">\r\n                    <span class=\"\"><label>Anes <span class=\"f_req\">*</span>: </label></span>	\r\n                    <!--<input type=\"text\" name=\"bed\" id=\"data-bed\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:block\" class=\"k-textbox k-textbox-txt\">-->\r\n                    <div style=\"dispaly:inline-block;vertical-align:middle;border:0px solid red\">\r\n                        <select name=\"app[visit_type]\" id=\"data-visit_type\" style=\"width:100%;height:2.0em;border:1px solid #bbb\" validationmessage=\"Please select one\" required=\"required\" validationmessage=\"Cannot be empty\">\r\n                            <option value=\"\"></option>\r\n            <%\r\n                for l in map_visit do\r\n            %>\r\n                            <option value=\"<%= l[0]%>\"><%= l[1] %></option>\r\n            <%\r\n                end\r\n            %>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n                \r\n                      <div id=\"note\" class=\"  portlet \" style=\"border:0px solid blue;width:400px;margin: 0 0.5em 0.5em 0;float:left;min-height:30px;\">\r\n                    <span class=\"\"><label>Note : </label></span>	\r\n                    <input type=\"text\" name=\"app[note]\" id=\"data-note\" size=\"29\" style=\"vertical-align:text-top;width:100%;display:blockwidth:300px\" class=\"k-textbox k-textbox-txt\">\r\n                </div>\r\n               \r\n                <div class=\"clear\"></div>\r\n                <br/>\r\n                <div id=\'temporary\' style=\'\'></div>\r\n                <input type=\"hidden\" name=\"record[status]\" id=\"data-status\" value=\"Appointed\"/>\r\n                <input type=\"hidden\" name=\"app[created_by]\" id=\"data-created_by\" value=\"<%= @current_user.login %>\"/>\r\n                <input type=\"hidden\" name=\"app[updated_by]\" id=\"data-updated_by\" value=\"<%= @current_user.login %>\"/>\r\n\r\n            \r\n            <%= f.submit \'Add Patient\', :class=>\'btn btn-info\' %>\r\n            <a href=\"javascript:void(0)\" class=\"btn \"  data-dismiss=\"modal\">Cancel</a>  \r\n            \r\n            <span style=\"float:right\">\r\n                <%= f.submit \'Patient Record\', :class=>\'btn btn-info\' %>\r\n            </span>\r\n<% end %>\r\n        <div class=\"clear\"></div>\r\n    </div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n\r\n    function init_fields(b) {\r\n        $(\'#data-public_id\').prop(\'readonly\', b);\r\n        $(\'#data-first_name\').prop(\'readonly\',b);\r\n        $(\'#data-last_name\').prop(\'readonly\',b);\r\n        $(\'#data-prefix_name\').prop(\'\',b);\r\n        $(\'#input-prefix_name\').prop(\'\',b);\r\n        $(\'#data-gender\').prop(\'\',b);\r\n        $(\'#data-birth_date\').prop(\'\',b);\r\n        \r\n        if (!b) {\r\n            $(\'#data-public_id\').val(\"\");\r\n            $(\'#data-first_name\').val(\"\");\r\n            $(\'#data-last_name\').val(\"\");\r\n            $(\'#data-prefix_name\').val(\"\");\r\n            $(\'#input-prefix_name\').val(\"\");\r\n            $(\'#data-gender\').val(\"\");\r\n            $(\'#data-birth_date\').val(\"<%= Time.now.strftime(\'%d/%m/%Y\') %>\");\r\n        }\r\n    }\r\n\r\n    function get_patient_info(us, ps, hn){\r\n        console.log(\'US:\' + us + \', PS:\' + ps + \',HN:\' + hn)\r\n        $(\'#his-status\').html(\'connecting...\');\r\n	    \r\n<% if his %>\r\n	\r\n	    var username = \'<%=his%>\'\r\n	    var password = \'-\'\r\n	\r\n<% end %>\r\n\r\n        // var hn=prompt(\"Please enter HN\",\"\");    \r\n        // var hn = hn\r\n        username = us;\r\n        password = ps;\r\n        if (hn==\'\') { \r\n            // alert(\"Not enough information!!\"); \r\n            $(\'#his-status\').html(\'No HN information, Please fill Patient HN\')\r\n        }else{     \r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading...</span>\');    \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            $.ajax({\r\n                url: \"get_patient_info?un=\"+username+\"&ps=\"+password+\"&hn=\"+hn,\r\n                context: document.body,\r\n                crossDomain: true\r\n            }).done(function(data) {\r\n                $(\'#his-status\').html(\'retriving...\');\r\n                // eval(data);\r\n                $(\'#temporary\').html(data);\r\n                $(\'#his-status\').html(\'completed\');\r\n                \r\n                if ($(\'#data-first_name\').val() != \'\') {\r\n                    init_fields(true);\r\n                } else {\r\n                    init_fields(false);\r\n                    $(\'#his-status\').html(\'Patient not found\')\r\n                }\r\n            }).fail(function(jqXHR, textStatus) {\r\n                // alert(\"error\");\r\n                $(\'#his-status\').html(\'Error loading, Please fill Patient information\')\r\n            });\r\n        }\r\n    }\r\n    \r\n    $(\'#get-his\').click(function() {\r\n        get_patient_info(\'<%= his %>\', \'-\', $(\'#data-hn\').val());\r\n    });\r\n	        \r\n	$(\'#his-logout\').click(function() {\r\n        $(\'#his-logout\').html(\'Loading ...\');\r\n        console.log(\'logout...\')\r\n        get_patient_info(\'-\', \'-\', \'-\');\r\n        // window.location = \'../Home/index\';\r\n    });\r\n    \r\n    $(document).ready(function(){\r\n        $(\'.login-block\').hide();\r\n        $(\'#his-login\').click(function() {\r\n            if ($(\'.login-block\').is(\":visible\")) {\r\n                $(\'#his-status\').show();\r\n                $(\'.login-block\').hide();\r\n                // console.log(\'get_patient_info\')\r\n                \r\n                \r\n    us = $(\'#input-username\').val();\r\n                ps = $(\'#input-password\').val();\r\n                hn = $(\'#data-hn\').val();\r\n                // $(\'#data-hn\').val(hn);\r\n                // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n                console.log(us + \'...\' + ps + \'...\' + hn);\r\n                $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n                get_patient_info(us, ps, hn);\r\n                \r\n                setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n                \r\n                // console.log(\'xxxx\');\r\n                // $(\'#his-status\').html(\'Logged as \' + us);\r\n                \r\n                $(\'#his-login\').hide();\r\n                $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n                $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient</a>\");\r\n                \r\n                // $(\'#modal\').modal(\'hide\')\r\n                // $(\'#modal\').attr(\'aria-hidden: false\');\r\n                // $(\'.modal-backdrop\').modal(\'hide\')\r\n                \r\n                // $(\'#commit\').click(function() {\r\n                //     console.log(\'login ...\')\r\n                //     us = $(\'#input-username\').val();\r\n                //     ps = $(\'#input-password\').val();\r\n                //     hn = $(\'#input-hn\').val();\r\n                //     get_patient_info(us, ps, hn);\r\n                //     console.log(\'... pass ...\')\r\n                // });\r\n                \r\n                $(\'#his-logout\').click(function() {\r\n            	    $(\'#his-logout\').html(\'Loading ...\');\r\n            	    console.log(\'logout...\')\r\n                    get_patient_info(\'-\', \'-\', \'-\');\r\n                    // window.location = \'../Home/index\';\r\n            	});\r\n                \r\n            } else {\r\n                $(\'#his-status\').hide();\r\n                $(\'.login-block\').show();\r\n                $(\'#his-login\').text(\'Get Patient\');\r\n                console.log(\'hide\')\r\n            }\r\n        })\r\n        $(\'#login-cancel\').click(function() {\r\n            $(\'#his-status\').show();\r\n            $(\'.login-block\').hide();\r\n            $(\'#his-login\').text(\'HIS Login\');\r\n        });\r\n        $(\'#commit\').click(function() {\r\n            us = $(\'#input-username\').val();\r\n            ps = $(\'#input-password\').val();\r\n            hn = $(\'#data-hn\').val();\r\n            // $(\'#data-hn\').val(hn);\r\n            // $(\'#data-hn\').val(\'...\' + us + \'...\' + ps + \'...\' + hn);\r\n            // console.log(us + \'...\' + ps + \'...\' + hn);\r\n            $(\'#his-status\').html(\'<span class=\"blink\">Loading ...</span>\');\r\n            get_patient_info(us, ps, hn);\r\n            \r\n            setInterval(function() {$(\'.blink\').fadeOut(500).fadeIn(500)}, 1000)\r\n            \r\n            // console.log(\'xxxx\');\r\n            // $(\'#his-status\').html(\'Logged as \' + us);\r\n            \r\n            $(\'#his-login\').hide();\r\n            $(\'#temp-his-logout\').html(\"<a href=\'javascript:void(0)\' id=\'his-logout\' class=\'btn btn-warning\'>HIS Logout</a>\");\r\n            $(\'#temp-get-his\').html(\"<a  href=\'javascript:void(0)\' id=\'get-his\' class=\'btn btn-info\'>Get Patient from HIS</a>\");\r\n            \r\n            // $(\'#modal\').modal(\'hide\')\r\n            // $(\'#modal\').attr(\'aria-hidden: false\');\r\n            // $(\'.modal-backdrop\').modal(\'hide\')\r\n            \r\n            // $(\'#commit\').click(function() {\r\n            //     console.log(\'login ...\')\r\n            //     us = $(\'#input-username\').val();\r\n            //     ps = $(\'#input-password\').val();\r\n            //     hn = $(\'#input-hn\').val();\r\n            //     get_patient_info(us, ps, hn);\r\n            //     console.log(\'... pass ...\')\r\n            // });\r\n            \r\n            $(\'#his-logout\').click(function() {\r\n        	    $(\'#his-logout\').html(\'Loading ...\');\r\n        	    console.log(\'logout...\')\r\n                get_patient_info(\'-\', \'-\', \'-\');\r\n                // window.location = \'../Home/index\';\r\n        	});\r\n        });\r\n    });\r\n</script>\r\n\r\n<script>\r\n    $(\"#data-prefix_name\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n            // {\"text\":\"xxx\",\"value\":\"xxx\"},\r\n            {\"text\":\"นาย\",\"value\":\"นาย\"},\r\n            {\"text\":\"นาง\",\"value\":\"นาง\"},\r\n            {\"text\":\"นางสาว\",\"value\":\"นางสาว\"},\r\n            {\"text\":\"ด.ช.\",\"value\":\"ด.ช.\"},\r\n            {\"text\":\"ด.ญ.\",\"value\":\"ด.ญ.\"},\r\n            {\"text\":\"Mr.\",\"value\":\"Mr.\"},\r\n            {\"text\":\"Miss.\",\"value\":\"Miss.\"}\r\n        ]\r\n	\r\n    });\r\n    \r\n    \r\n        $(\"#data-duration\").kendoComboBox({\r\n        dataTextField: \"text\",\r\n        dataValueField: \"value\",\r\n        dataSource: [\r\n         \r\n            {\"text\":\"30 นาที\",\"value\":\"30\"},\r\n            {\"text\":\"1 ชั่วโมง\",\"value\":\"60\"},\r\n            {\"text\":\"1 ชั่วโมงครึ่ง\",\"value\":\"90\"},\r\n            {\"text\":\"2 ชั่วโมง\",\"value\":\"120\"}\r\n        ]\r\n	\r\n    });\r\n    \r\n    \r\n    function update_gender() {\r\n        val = $(this).val();\r\n        if (val == \'0\') {\r\n            $(\'#data-gender option:eq(0)\').prop(\'selected\', true);\r\n        } else if (val == \'นาย\' || val == \'ด.ช.\') {\r\n            $(\'#data-gender option:eq(1)\').prop(\'selected\', true);\r\n        } else {\r\n            $(\'#data-gender option:eq(2)\').prop(\'selected\', true);\r\n        }\r\n        \r\n        // checked select option\r\n        data_demo_update();\r\n    }\r\n    function data_demo_update(){\r\n		t = $(\'#data-prefix_name\');\r\n		val = t.val();\r\n		if(val==\'true\'){\r\n			val = t.attr(\'checked\');\r\n			if(val==\'checked\'){\r\n				val = \'TRUE\';\r\n			}else{\r\n				val = \'\';\r\n			}\r\n						\r\n		}\r\n		text = val;\r\n	}\r\n	$(document).ready(function(){\r\n	    // prefix_name\r\n        $(\'#data-prefix_name\').change(update_gender);\r\n	});\r\n	\r\n    function add_patient() {\r\n        $(\'#modal\').modal({\r\n            show: true, \r\n            // backdrop: \'static\',\r\n            backdrop: \'fade\',\r\n            keyboard: true\r\n        });\r\n        $(\'#data-hn\').val(\'\');\r\n        $(\'#patient-msg\').text(\'\');\r\n        init_fields(false);\r\n        // $(\'#data-hn\').focus();\r\n    }\r\n    function advanced_search() {\r\n        $(\'#modal2\').modal({\r\n            show: true, \r\n            backdrop: \'static\',\r\n            keyboard: true\r\n        });\r\n    }\r\n    function update_patient() {\r\n        url = \"../../www/Patient/get_patient_by_hn?hn=\" + $(\'#data-hn\').val();\r\n        $.getJSON( url , function( data ) {\r\n            if (!jQuery.isEmptyObject(data)) {\r\n                console.log(\"[\" + data.hn + \"] \" + data.prefix_name + \" | \" + data.first_name + \"-\" + data.last_name);\r\n                $(\'#data-public_id\').val(data.public_id);\r\n                $(\'#data-first_name\').val(data.first_name);\r\n                $(\'#data-last_name\').val(data.last_name);\r\n                $(\'#data-hn\').val(data.hn);\r\n                $(\'#data-prefix_name\').val(data.prefix_name);\r\n                $(\'#input-prefix_name\').val(data.prefix_name);\r\n                $(\'#data-gender option:eq(\' + data.gender + \')\').prop(\'selected\', true);\r\n                // $(\'#data-prefix_name option:contains(\"\' + data.prefix_name.trim() + \'\")\').prop(\'selected\', true);\r\n                \r\n                dd = data.birth_date\r\n                if (dd.toString().indexOf(\'-\') != -1) {\r\n                    tmp = dd.split(\'-\');\r\n                    dd = tmp[2] + \"/\" + tmp[1] + \"/\" + tmp[0];\r\n                }\r\n                // console.log(\'xxx \' + dd);\r\n                $(\'#data-birth_date\').val(dd);\r\n                $(\'#patient-msg\').text(\'Patient found in DB\');\r\n                init_fields(true);\r\n                // console.log(\'init field = true\')\r\n            } else {\r\n                $(\'#patient-msg\').text(\'Patient not found in DB. Please fill patient info.\');\r\n                init_fields(false);\r\n                // console.log(\'init field = false\')\r\n            }\r\n            \r\n            console.log(\"... \" + $(this).val())\r\n        });\r\n    }\r\n    $(document).ready(function(){\r\n        $(\'#btn-add_patient\').click(add_patient);\r\n        $(\'#btn-advanced_search\').click(advanced_search);\r\n        // hn\r\n        $(\'#get-hn\').click(update_patient);\r\n    });\r\n</script>\r\n\r\n<script>\r\n    var update_id = \"#patient_content\";\r\n\r\n    function app_update(aid, hn, name, room, status) {\r\n        console.log(\'appointment=\' + aid);\r\n        $(\".modal-backdrop\").show(\'fade\');\r\n        $(\'#modal\').show();\r\n        $(\'#modal\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n        });\r\n        $(\'#frm_status\').val(status);\r\n        $(\'#frm_room\').val(room);\r\n        $(\'#patient-hn\').text(hn);\r\n        $(\'#patient-name\').text(name);\r\n        $(\'#aid\').val(aid);\r\n    }\r\n\r\n    var ls = <%= a_app.empty? ? \'\"\"\'.html_safe : a_app.sort_by{|i| i[\"updated_at\"]}.last[\'updated_at\'].to_json.html_safe%>;\r\n    var ub = true; // update boolean\r\n    var tt = <%= this.update_time_ms.to_i %>; // time to refresh\r\n    \r\n    function loadPartial() {\r\n        console.log(\"LAST UPDATE = \" + ls);\r\n        \r\n        $.getJSON( \"last_updated?date=<%=s_date%>\", function( data ) {\r\n            var tmp = data.last_updated;\r\n            \r\n            if (tmp == ls) {\r\n                ub = true;\r\n                // console.log(\'XXX\' + ls);\r\n            } else {\r\n                // console.log(\'CCC\' + ls + \"...\" + tmp);\r\n                ub = false;\r\n                ls = tmp;\r\n            }\r\n            \r\n            // console.log(\"ub : \" + ub);\r\n            // console.log(tmp + \"....\" + ls);\r\n        });\r\n        \r\n        if (!ub) {\r\n            feed_page(500);\r\n        }\r\n        \r\n        // console.log(\"ubx: \" + ub);\r\n        // tt = Math.random() * 100000;\r\n        // tt = 10000;\r\n        console.log(\'Reload in > \' + tt + \' ms.\')\r\n        setTimeout(loadPartial, tt);\r\n    }\r\n    \r\n    function feed_page(fade) {\r\n            $.ajax({\r\n                url: \'../Home/index_partial?date=<%=s_date%>\',\r\n                success: function(data) {\r\n                    //  alert(\"update\");\r\n                    // do something with the return value here if you like\r\n                    $(update_id).fadeOut(fade, function(){\r\n                        $(update_id).html(data);\r\n                    })\r\n                    $(update_id).fadeIn(fade)\r\n                }\r\n            });\r\n    }\r\n    \r\n    function update_status(app_id, status, room) {\r\n        var u = \'update_queue_status?id=\' + app_id + \'&status=\' + status;\r\n        if (room != \'\') {\r\n            u += \'&room=\' + room;\r\n        }\r\n        // var ub = false;\r\n            $.ajax({\r\n                url: u,\r\n                success: function(data) {\r\n                    // location.reload();\r\n                    feed_page(100);\r\n                }\r\n            });\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // $(\'body\').addClass(\'sidebar_hidden\');\r\n        // $(\"body\").attr(\"class\", \"sidebar_hidden\");\r\n        setTimeout(feed_page(100), 0);\r\n<%\r\n    if this.update_time_ms != 0\r\n%>        \r\n        loadPartial();\r\n<%\r\n    end\r\n%>\r\n        console.log(\'<%= this.update_time %>...\')\r\n    });\r\n\r\n    refresh_remote();\r\n</script>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print 1 page\',\'print_appointment2?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<div class=\"clear\"></div>\r\n</div><br/>',NULL,NULL,NULL,'2018-10-30 11:01:02','2018-10-30 11:01:02','opd',''),(3753,'layout',1471,4,'<% user = @current_user %>\r\n<% if user.login == \'opd\'%>\r\n<meta http-equiv=\"refresh\" content=\"0;url=/svh/endo/Home/opd\">\r\n<% else %>\r\n<%=default_layout%>\r\n<% end%>',NULL,NULL,NULL,'2018-10-30 11:03:49','2018-10-30 11:03:49','',''),(3754,'create',1419,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    \r\n    locker_model = get_model(\'locker\')\r\n    if locker_model\r\n\r\n    \r\n    locker = locker_model.where(:module_id=>params[:parent_id],:module_name=>this.table_name,:created_at=>{\'$gt\'=>1.hours.ago}).first\r\n    \r\n    if locker \r\n        if locker.session!= session[:user].to_s  and params[:override]==nil\r\n    %>\r\n    <script>\r\n        res = confirm(\"Someone is editing this document. Would you like to override the record?\");\r\n        if(res==true){\r\n             $(document).ready(function(){\r\n              $(\'#ref_number\').parent().append(\"<input type=\'hidden\' name=\'override\' value=\'override\' />\");\r\n               \r\n           })\r\n        }else\r\n            window.location = \"<%=return_url%>\";\r\n\r\n\r\n        </script>\r\n    <%\r\n        end\r\n    elsif session[:user] and session[:user]!=\'\' \r\n    \r\n    locker = locker_model.create({:session=>session[:user],:module_id=>params[:parent_id],:reference_id=>params[:return],:module_name=>this.table_name,:status=>\'create\'})\r\n    \r\n    end\r\n    \r\n    end\r\n    \r\n    \r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n<style>\r\n    .document-border { border:0px solid;}\r\n</style>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\">\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n\r\n  return_url = \"../Home/patient_record?id=\\\\#{@appointment.id}\"\r\n\r\n  model = get_model(this.table_name)\r\n\r\n\r\n  if request.post? \r\n  \r\n    locker.destroy if locker\r\n    \r\n    \r\n    doc = get_document this.document_name\r\n    record = doc.record_create(model,params)\r\n    m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n    flash[:notice]=\'New record has been created\'\r\n \r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<% if  @appointment %>\r\n//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n<% else %>\r\n//window.location = \"../Home/index\"\r\n<% end %>\r\n\r\nwindow.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n\r\n</script>\r\n\r\n\r\n\r\n<%\r\n  else  \r\n  \r\n    if params[:data]\r\n    record = model.new params[:data] \r\n    else\r\n    record = model.new \r\n    end\r\n    \r\n    \r\n    \r\n    record.endoscopist = @appointment.provider\r\n\r\n\r\n    \r\n%>\r\n<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n\r\n<%= hidden_field_tag :return, return_url if params[:return] %>\r\n\r\n<%\r\n   fid = 0\r\n   name = \'patient_id\'\r\n   value = params[:patient_id]\r\n   value = params[:id] if params[:id]\r\n   ref_number = @next_id\r\n   ref_number = params[:ref_number] if params[:ref_number]\r\n   \r\n%>\r\n<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n<div class=\"modal-header\">\r\n\r\n<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n<h3>Select Patient</h3>\r\n</div>\r\n<div class=\"modal-body\">\r\n<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n<table id=\"search-panel\" style=\"width:100%\" >\r\n<tr><td align=\'center\' style=\"border:0px solid\">\r\nPatient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n\r\n<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %></td>\r\n\r\n</tr></table>\r\n</div>\r\n<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n<br/>\r\n    Loading..\r\n</div>\r\n</div>\r\n </div>\r\nRef : <%=ref_number%>\r\n <div class=\"<%=\'hide\' if params[:parent_id]%>\" style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc;\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\nPatient : \r\n<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</div>\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= Time.now.strftime(\"%H:%M\") %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= Time.now.strftime(\"%d/%m/%Y\") %>\',\r\n    });\r\n    \r\n    $(\"#ref-record\").kendoAutoComplete();\r\n    $(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n\r\nfunction doSearch(){\r\n        $(\'#search-result\').css(\"display\", \"block\");\r\n		url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n        url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n        url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n		  $(\'#search-result\').html(data);  \r\n		  }\r\n		});\r\n        \r\n}\r\n   function doClose(){\r\n       \r\n     $(\'#SelectPatient\').hide();\r\n     $(\".modal-backdrop\").hide(\'fade\');\r\n    \r\n   }\r\n\r\n\r\n\r\n    function doSelect(value){\r\n    	$(\'#<%=fid%>\').val(value);\r\n        \r\n        url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n		url += \'&id=\'+value\r\n        url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n        \r\n		$.ajax({\r\n		  url: url,\r\n		 success: function(data){\r\n          $(\'#patient\').html(data);  \r\n          $(\'#SelectPatient\').hide();\r\n          $(\".modal-backdrop\").hide(\'fade\');\r\n		  }\r\n		});\r\n        \r\n	}\r\n\r\n\r\n\r\n\r\n\r\n    $(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n    if(event.keyCode == 13) {\r\n	  doSearch();\r\n      event.preventDefault();\r\n      return false;\r\n    }else{\r\n	\r\n	$(\'#search-result\').html(\'Loading..\')\r\n}\r\n  });\r\n  \r\n    <% if params[:patient_id] %>\r\n    $(\'#search-result\').css(\"display\", \"block\");\r\n    doSelect(\'<%=params[:patient_id]%>\')    \r\n    <% else %>\r\n    \r\n     $(\'#SelectPatient\').modal({\r\n                show: true, \r\n                backdrop: \'static\',\r\n                keyboard: true\r\n    })\r\n    \r\n          \r\n    <% end %>\r\n\r\n	\r\n</script>\r\n\r\n\r\n<%\r\n    params[:form] = {}\r\n    params[:form][:model] = model\r\n    params[:form][:form] = f\r\n    params[:form][:record] = record\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n\r\n<%\r\n    if return_url.include? \'?\'\r\n        return_url += \"&reset_lock=\\\\#{locker.id}\"\r\n    else\r\n        return_url += \"?reset_lock=\\\\#{locker.id}\"\r\n    end\r\n%>\r\n<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\n\r\nif (!validator.validate()||$(\'#0\').val()==\"\") {\r\nalert(\'Please fill all information\');\r\nif($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\nreturn false;\r\n\r\n}else{\r\n    return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   \r\n',NULL,NULL,NULL,'2018-10-31 04:23:31','2018-10-31 04:23:31','create',''),(3755,'print_appointment2',1363,3,'<%\r\n  @module_name = @current_project.name+\'#appointment\' \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  begining = Time.now.beginning_of_day\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n\r\n  if params[:print] and params[:print][:date]\r\n  \r\n  date = Date.to_mongo(params[:print][:date])\r\n \r\n  appointments =   @models[:appointment].where(:date=>date,:status=>{\'$ne\'=>\'Cancelled\'}).all\r\n \r\n \r\n records = {}\r\n patients = {}\r\n providers = {}\r\n indications= {}\r\n visit_types= {}\r\n\r\n\r\n @module_model.where(:module_name=>@module_name, :module_id=>{\'$in\'=>appointments.collect{|i| i.id }}).all.each do |i|\r\n\r\n  records[i.module_id]=i\r\n end\r\n \r\n @patient_model.find(records.values.collect{|i| i.patient_id if i }).each do |i|\r\n patients[i.id]=i\r\n end\r\n\r\n @models[:visit_type].all.each do |i|\r\n visit_types[i.id.to_s] = i\r\n end\r\n \r\n @models[:provider].all.each do |i|\r\n providers[i.id.to_s] = i\r\n end\r\n @models[:indication].all.each do |i|\r\n indications[i.id.to_s] = i\r\n end\r\n \r\n     pro = {}\r\n    @models[:procedure].all.each do |i|\r\n    pro[i.id] = i.name\r\n    end\r\n    \r\n    \r\n\r\n    \r\njson_data =   appointments.collect{|ap| \r\n i  = records[ap.id]\r\n if i and patients[i.patient_id] \r\n p = patients[i.patient_id]  \r\n provider = providers[ap.provider.to_s] if providers\r\n l = %w{#bcdeee}\r\n age = \'-\'\r\n if p and p.birth_date\r\n     diff = Time.diff(date, p.birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    age = \"\\\\#{year}\"\r\n end\r\n indication=\"-\"\r\n visit_type=\"-\"\r\n \r\nindication = indications[ap.indication.to_s].name if indications[ap.indication.to_s]\r\n visit_type = visit_types[ap.visit_type.to_s].name if visit_types[ap.visit_type.to_s]\r\n \r\n d = \"-\"\r\n d = ap.date.strftime(\"%Y-%m-%d\") if ap.date\r\n \r\nif true\r\n    {\'id\'=>ap.id,\r\n    \'record\'=>i.id,\r\n    \'hn\'=> p.hn,\r\n    \'room\'=>ap.room,\r\n    \'procedure_list\'=>ap.procedure_list,\r\n    \'note\'=>ap.note,\r\n    \'date\'=>d,\r\n    \'color\'=>l[rand(4%l.size)],\r\n    \'provider\'=>(provider.nil? or provider==\'\') ? \'-\' : provider.first_name,\r\n    \'title\'=>\"\\\\#{p.prefix_name if p } \\\\#{p.first_name if p } \\\\#{p.last_name if p }\",\r\n    \'start\'=>\"\\\\#{ap.start.strftime(\" %H:%M\") if ap.start}\",\r\n    \'end\'=>d+\"\\\\#{ap.stop.strftime(\" %H:%M\") if ap.stop}\",\r\n    \'indication\'=>indication,\r\n    \'allDay\'=>false,\r\n    \'url\'=>\'edit?id=\'+i.id.to_s,\r\n    \'age\'=>age,\r\n    \'visit_type\'=>visit_type,\r\n    \'tel\'=>[p.tel_home,p.tel_office,p.mobile].collect{|i| i if i!=\"\"}.compact.join(\", \"),\r\n    \'public_id\'=>p.public_id,\r\n    \'ward\'=>ap.ward,\r\n    \'anes\'=>ap.anes\r\n    }  \r\nelse\r\n    nil\r\nend \r\nend\r\n}.compact\r\n\r\nlist = json_data.sort{|a,b| a[\'visit_type\']<=>b[\'visit_type\']}\r\n\r\nrooms = {}\r\n\r\nfor i in list\r\n\r\n    room_id = i[\'room\']\r\n    rooms[room_id] = [] unless rooms[room_id]\r\n    rooms[room_id] << i\r\n    \r\n    \r\nend\r\n\r\n \r\n%>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n</head>\r\n<style type=\"text/css\" media=\"print,screen\">\r\nhtml { }\r\nvalue {color:#06F}\r\nimvalue { color:#F00; font-weight:bold}\r\nimvalue value { color:#F00; font-weight:bold}\r\n#page {border:solid 1px; width:1200px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px; }\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:9pt;}\r\n.wrapper{ margin-left:auto;margin-right:auto} \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 1px;line-height: 0;overflow: visible; width:98%;}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 0.5em; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#2561cD;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:1200px; margin-top:0; }\r\n  blockquote, \r\n .wrapper{ width:100%;margin-left:0px;margin-right:0px} \r\n  table { page-break-after:auto; -fs-table-paginate: paginate; }\r\n  tr    { page-break-inside:avoid; page-break-after:auto }\r\n  td    { page-break-inside:avoid; page-break-after:auto }\r\n  thead { display:table-header-group;     margin-top:10px;}\r\n  tfoot { display:table-footer-group }\r\n\r\n}\r\n\r\n#box{\r\n    width:150px;\r\n    float:left;\r\n    padding:10px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:10px;\r\n}\r\n.smm { font-size:0.5em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n        width:150px;\r\n}\r\nlabel{\r\n    color:#666; font-weight:bold;\r\n}\r\n\r\n#table-3 {\r\n    border: 1px solid #DFDFDF;\r\n    background-color: #F9F9F9;\r\n    width: 100%;\r\n    -moz-border-radius: 3px;\r\n    -webkit-border-radius: 3px;\r\n    border-radius: 3px;\r\n	font-family: Arial,\"Bitstream Vera Sans\",Helvetica,Verdana,sans-serif;\r\n	color: #333;\r\n}\r\n#table-3 td, #table-3 th {\r\n	border-top-color: white;\r\n	border-bottom: 1px solid #DFDFDF;\r\n	color: #555;\r\n}\r\n#table-3 th {\r\n	text-shadow: rgba(255, 255, 255, 0.796875) 0px 1px 0px;\r\n	font-family: Georgia,\"Times New Roman\",\"Bitstream Charter\",Times,serif;\r\n	font-weight: bold;\r\n	padding: 4px 4px 4px;\r\n	text-align: left;\r\n	line-height: 1.3em;\r\n	font-size: 9px;\r\nbackground: #e8e8e8;\r\n}\r\n#table-3 td {\r\n	font-size: 10px;\r\n	padding: 4px 4px 4px;\r\n	vertical-align: top;\r\n	background:#FFF;\r\n}\r\nthead {\r\n    display:table-header-group;\r\n\r\n}\r\ntbody {\r\n    display:table-row-group;\r\n}\r\n.boxx {width:500px; float:left; padding:5px }\r\n</style>\r\n<body>\r\n\r\n<div class=\"wrapper\" >\r\n\r\n\r\n<br /><br /><div id=\"head\">\r\n<div id=\"logoleft\"><img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"200\" style=\"float:left\" /></div>\r\n<div id=\"logoright\">\r\n<p>Reported by :&nbsp;<%= @current_user.login.humanize %></p>\r\n<p>Printed at :&nbsp;<%= Time.now.strftime(\'%d/%m/%Y %H:%M\') %></p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<table>\r\n    <tr valign=\"top\">\r\n    \r\n<% \r\nrooms.keys.sort.each do |room_id|\r\n\r\nrl = rooms[room_id]\r\n\r\nlist = rl\r\n    \r\n%>\r\n\r\n\r\n<td>\r\n\r\n\r\n\r\n\r\n\r\n\r\n        \r\n        \r\n\r\n<div class=\"boxx\">\r\n\r\n<b>\r\n<%= room_id %></b>\r\n<span style=\"float:right\"> \r\n<b>Date : <%= date.strftime(\"%d/%m/%y\")%> , Total Patient : <%= appointments.size %></b>\r\n\r\n<%\r\n\r\n    day_offs = @models[:day_off].where(:date=>{\'$lte\'=>date},:to_date=>{\'$gte\'=>date}).all.collect{|i| \r\n        \r\n        provider = @models[:provider].find i.provider\r\n        \r\n        period = \"\\\\#{i.date.strftime(\'%d/%m/%Y\')} - \\\\#{i.to_date.strftime(\'%d/%m/%Y\')}\"\r\n        period = \"\\\\#{i.date.strftime(\'%d/%m/%Y\')}\" if i.date==i.to_date\r\n        \r\n        {:name=> provider.name, :title=>i.title, :period=>period }\r\n        \r\n    }\r\n    \r\n   if day_offs.size > 0 \r\n       %>\r\n<span style=\"color:#aa3333\"><i> Note : \r\n       <%\r\n    for i in day_offs\r\n%>\r\n<%= \"\\\\#{i[:name]} \\\\#{i[:title]} \\\\#{i[:period]}\" %>\r\n<% end %>\r\n</i></span>\r\n<% end %>\r\n\r\n</span>\r\n\r\n<br />\r\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" id=\"table-3\">\r\n  <thead>\r\n  <tr>\r\n    <th style=\"width:30px\">Time</th>\r\n    <th style=\"width:60px\">Procedure</th>\r\n    <th style=\"width:250px\">Patient Name</th>\r\n    <th style=\"width:60px\">HN</th>\r\n    <th style=\"width:20px\">Age</th>\r\n    <th style=\"width:70px\">Provider</th>\r\n    <th style=\"width:50px\">Ans</th>\r\n    <th style=\"width:30px\">ward</th>\r\n  </tr>\r\n  </thead>\r\n  <tbody>\r\n  <%\r\n    list.sort!{|a,b| a[\'start\']<=>b[\'start\'] }\r\n    \r\n    tmap = {}\r\n    \r\n    for i in list\r\n        t = ((i[\'start\'].to_datetime.to_i )/60/30)%48\r\n  \r\n        tmap[t] = [] unless tmap[t]\r\n        \r\n        tmap[t] << i\r\n        \r\n     \r\n        \r\n    end\r\n  %>\r\n  \r\n  <% #\r\n    \r\n    px = {}\r\n    \r\n    48.times do |t|\r\n        \r\n    \r\n        \r\n        \r\n    b = (begining+t*30*60).strftime(\"%H:%M\")\r\n        \r\n    if t>13 and t <= 36 or (tmap[t]!=nil and tmap[t].size>0) and px[b]==nil\r\n        \r\n        list = tmap[t]\r\n    \r\n        if list\r\n        \r\n        list.each_with_index do |i,index|  \r\n        \r\n        te = 0 \r\n        start =  i[\'start\'].to_datetime\r\n        te = (i[\'end\'].to_datetime.strftime(\"%H:%M\").to_datetime.to_i - i[\'start\'].to_datetime.to_i)/1800 if i[\'end\']\r\n        \r\n        \r\n        style_txt = \'\'\r\n        \r\n         if i[\'anes\'] and  i[\'anes\'].index(\'Consult\') #or  i[\'anes\'] ==  \'Consult team anesth\' or  i[\'anes\'] ==  \'Consult GI anesth\' \r\n         style_txt = \'background:#DFDFDF\'\r\n        end\r\n        \r\n        start = start - (start.to_i.to_f%1800)/24/3600\r\n        \r\n        \r\n        te.times do |j|\r\n            \r\n            \r\n        px[(start+j*(1.0/48)).strftime(\"%H:%M\")] = true\r\n  \r\n    %>\r\n    <tr>\r\n    <td style=\"<%=style_txt%>\" >\r\n    <%=(start+j*(1.0/48)).strftime(\"%H:%M\")%><% index+1%></td>\r\n    <% if j==0 %>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'procedure_list\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'title\']%> <br /><%=i[\'note\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'hn\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'age\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'provider\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'anes\']%></td>\r\n    <td rowspan=\"<%=te%>\" style=\"<%=style_txt%>\" ><%=i[\'ward\']%></td>\r\n\r\n    \r\n    <% end %>\r\n    </tr>\r\n    <% end %>\r\n    \r\n    <% end %>\r\n    \r\n       <%else %>\r\n       \r\n    <tr>\r\n    <td><%=(begining+t*30*60).strftime(\"%H:%M\")%> </td>\r\n     <td>&nbsp;</td>  <td>&nbsp;</td> <td>&nbsp;</td> <td>&nbsp;</td> <td>&nbsp;</td> <td>&nbsp;</td> <td>&nbsp;</td> \r\n    </tr>\r\n    \r\n      <%end %> \r\n    \r\n    <% end %>\r\n    <% end %>\r\n    \r\n    \r\n</tbody>\r\n  </table>\r\n</div>  \r\n\r\n</td>\r\n  \r\n<% end %>\r\n</div>\r\n  </div></div></div></div></div>\r\n  \r\n      </tr>\r\n    \r\n</table>\r\n</body>\r\n</html>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2018-11-01 04:32:26','2018-11-01 04:32:26','print_appointment2',''),(3756,'edit',1465,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3><%=this.table_name.to_s.humanize%> Update</h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  record.country = \'Thailand\' unless record.country\r\n  user_id = \'NA\'\r\n  \r\n  user_id = format(\'%04d\',record.user_id.to_i) if record.user_id and record.user_id!=\'\' and record.user_id.to_i!=0\r\n  \r\n  record.member_id = \"2018-01-\\\\#{user_id}\" \r\n  \r\n  \r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=record.id%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>