document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   \r\n    if params[:search]\r\n        records = model.all(params[:search][:criteria])\r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n       records = model.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n    end\r\n   \r\n%>\r\n\r\n<%= tabular :model=>labels, :data=>records do |i,out|\r\n\r\nfields.each_with_index do |f,index|\r\n\r\nout[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n\r\nend\r\nout<<link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nout<<link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\')\r\n#out<<link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:data=>{:confirm=>\'Are you sure?\'})\r\nout\r\nend\r\n%>\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2018-11-07 08:29:38','2018-11-07 08:29:38','list',''),(3766,'document_name',1474,1,'\'short_record\'',NULL,NULL,NULL,'2018-11-10 10:22:48','2018-11-10 10:22:48',NULL,NULL),(3767,'document_name',1475,1,'\'operation\'',NULL,NULL,NULL,'2018-11-10 10:31:59','2018-11-10 10:31:59',NULL,NULL),(3768,'document_name',1476,1,'\'brand\'',NULL,NULL,NULL,'2018-11-10 10:32:46','2018-11-10 10:32:46',NULL,NULL),(3769,'document_name',1477,1,'\'implant\'',NULL,NULL,NULL,'2018-11-10 10:33:27','2018-11-10 10:33:27',NULL,NULL),(3770,'document_name',1478,1,'\'diagnosis\'',NULL,NULL,NULL,'2018-11-10 10:34:50','2018-11-10 10:34:50',NULL,NULL),(3771,'document_name',1479,1,'\'complication\'',NULL,NULL,NULL,'2018-11-10 10:35:23','2018-11-10 10:35:23',NULL,NULL),(3772,'document_name',1480,1,'\'koos\'',NULL,NULL,NULL,'2018-11-10 10:46:57','2018-11-10 10:46:57',NULL,NULL),(3773,'document_name',1481,1,'\'hoos\'',NULL,NULL,NULL,'2018-11-10 10:47:42','2018-11-10 10:47:42',NULL,NULL),(3774,'list_import',1432,3,'<%\r\nrequire \'csv\'\r\n\r\npath = \"public/esm/cusys/cucrc/ip_list.csv\"\r\n\r\nheader = true\r\nmodels = get_model\r\nprojects = models[:project].all.collect{|i| [i.protocol_no.downcase,i] }\r\n\r\ndef find_project name, projects\r\n    name = name.downcase\r\n    for i in projects\r\n        tag = i[0]\r\n        project = i[1]\r\n        \r\n        return project if name.index(tag)\r\n        \r\n        \r\n    end\r\n    \r\n    return nil\r\n\r\nend\r\n\r\n\r\nCSV.foreach(path) do |row|\r\n\r\n    if header\r\n       header=false \r\n    else\r\n    \r\n        name= row[0] \r\n        ip_name= row[1] \r\n        lot = row[2]\r\n        expired =  Date.parse(row[3])\r\n        \r\n        project = find_project name, projects\r\n        project_id = nil\r\n        project_id = project.id if project\r\n        \r\n        item = models[:ip_item].where(:name=>ip_name, :project_name=> name).first\r\n        \r\n        unless item\r\n            \r\n            item = models[:ip_item].create(:name=>ip_name, :project_name=> name, :project_id=>project_id)\r\n             \r\n        end\r\n        \r\n        card = models[:ip_card].where(:item_id=>item.id, :lot=> lot).first\r\n        \r\n        unless card\r\n            \r\n            card = models[:ip_card].create(:item_id=>item.id, :lot=> lot, :expired_date=>expired, :status=>\'in\', :quantity=>0)\r\n             \r\n        end\r\n        \r\n      \r\n        %>\r\n        \r\n        <%=row.inspect %><br/>\r\n        \r\n        <%\r\n    \r\n\r\n    end\r\n\r\n\r\nend\r\n\r\n%>',NULL,NULL,NULL,'2018-11-11 16:06:18','2018-11-11 16:06:18','list_import',''),(3777,'document_name',1483,1,'\'or_appointment\'',NULL,NULL,NULL,'2018-11-12 07:53:58','2018-11-12 07:53:58',NULL,NULL),(3778,'index_pharmacy',1272,3,'\r\n\r\n            <link rel=\"stylesheet\" href=\"/gebo/lib/fullcalendar/fullcalendar_gebo.css\" />	\r\n			<script src=\"/gebo/lib/fullcalendar/fullcalendar.min.js\"></script>\r\n			<script src=\"/gebo/lib/fullcalendar/gcal.js\"></script>\r\n\r\n<div class=\"heading\">\r\n    <h1>Pharmacist</h1>\r\n</div>    \r\n\r\n<%\r\n\r\n    status_list = %w{ Open Final Closed Archived }\r\n    \r\n    projects = []\r\n\r\n    \r\n    models = get_model\r\n    \r\n    \r\n    if true or @current_role == \'admin\' or @current_role==\'developer\'\r\n        \r\n    projects = get_model(\"project\").where(:status=>\'Open\').all\r\n    \r\n    else\r\n    \r\n    user = models[:user].where(:login=> @current_user.login).first\r\n    \r\n    member =  models[:member].where(:user_id=>user.id).first\r\n    \r\n    if false and member\r\n    \r\n    member_projects = models[:member_project].where(:member_id=>member.id).all\r\n    \r\n    projects = get_model(\"project\").find member_projects.collect{|i| i.project_id}\r\n    \r\n    \r\n    end\r\n    \r\n    \r\n    end\r\n    \r\n    mprojects = {}\r\n    \r\n    for i in projects\r\n        mprojects[i.id] = i \r\n    end\r\n    \r\n    \r\n    %>\r\n    \r\n    <div class=\"tabbable\">\r\n	<ul class=\"nav nav-tabs\">\r\n		<li class=\"active\"><a href=\"#tab1\" data-toggle=\"tab\">My Schedule</a></li>\r\n		<li class=\"\"><a href=\"#tab2\" data-toggle=\"tab\">My Projects</a></li>\r\n		<li><a href=\"#tab3\" data-toggle=\"tab\">My Performance</a></li>\r\n	</ul>\r\n	<div class=\"tab-content\">\r\n		<div class=\"tab-pane active\" id=\"tab1\">\r\n			<p>\r\n\r\n<%\r\n\r\n    date = Time.now\r\n    date = Date.parse params[:date] if params[:date] \r\n\r\n    visits = []\r\n    pvisits = []\r\n\r\n    for p in projects\r\n    \r\n        list = models[:visit].where(:project_id=>p.id, :date=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}).sort(:date.desc).all     \r\n        plist = models[:visit].where(:project_id=>p.id,:pharmacist_status=>{\'$ne\'=>\'Completed\'}, :date=>{\'$lte\'=>date.beginning_of_day}).sort(:date.desc).limit(5).all     \r\n        \r\n      \r\n\r\n\r\n        for i in list\r\n        \r\n            patient = models[:patient].find i.patient_id\r\n            \r\n            sheet = models[:pl_sheet].find patient.sheet_id\r\n            \r\n            unless sheet \r\n                \r\n             visit = models[:visit].where(:patient_id=>patient.id, :sheet_id=>{\'$ne\'=>nil}).first\r\n             sheet = models[:pl_sheet].find visit.sheet_id\r\n             visit = nil\r\n\r\n            end\r\n            \r\n            period = models[:pl_period].find i.period_id\r\n            period_visit = \'\'\r\n            if period\r\n                period_visit = period.visit\r\n            end\r\n            \r\n            visits << {:status=> i.status, :project=>p,:protocol_no=>p.protocol_no, :patient=>patient, :name=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\", :hn=>patient.hn,:subject_no=>patient.subject_id,\r\n                :visit=>i, :visit_type=>i.visit_type, :date=>\"\\\\#{i.date.strftime(\"%d/%m/%Y\") if i.date}\", :sheet=>sheet, :period=>period, :period_name=> period_visit,\r\n                :pharmacist_status=>i.pharmacist_status\r\n            }\r\n        \r\n        end\r\n        \r\n         for i in plist\r\n        \r\n            patient = models[:patient].find i.patient_id\r\n            if patient\r\n            sheet = models[:pl_sheet].find patient.sheet_id\r\n            \r\n            unless sheet \r\n                \r\n             visit = models[:visit].where(:patient_id=>patient.id, :sheet_id=>{\'$ne\'=>nil}).first\r\n             sheet = models[:pl_sheet].find visit.sheet_id\r\n             visit = nil\r\n\r\n            end\r\n            \r\n            period = models[:pl_period].find i.period_id\r\n            period_visit = \'\'\r\n            if period\r\n                period_visit = period.visit\r\n            end\r\n            period_visit = i.name if i.name and i.name.size>0\r\n            \r\n            pvisits << {:status=> i.status, :project=>p,:protocol_no=>p.protocol_no, :patient=>patient, :name=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\", :hn=>patient.hn,:subject_no=>patient.subject_id,\r\n                :visit=>i, :visit_type=>i.visit_type, :date=>\"\\\\#{i.date.strftime(\"%d/%m/%Y\") if i.date}\", :sheet=>sheet, :period=>period, :period_name=> period_visit,\r\n                :pharmacist_status=>i.pharmacist_status\r\n            }\r\n           else\r\n              i.destroy  \r\n        end\r\n        \r\n     \r\n        \r\n        end\r\n        \r\n        \r\n    end\r\n\r\n    %>\r\n    \r\n<div><span class=\"font-size:1.5em\"><b>My Schedule</b></span>\r\n\r\n<div class=\"pull-right\">Date : <%=text_field_tag \"date\", date.strftime(\"%d/%m/%Y\"), :id=>\'select_date\' %>\r\n</div>\r\n\r\n</div>\r\n\r\n\r\n<hr/>\r\n<script>\r\n	$(\"#select_date\").kendoDatePicker({\r\n		value: \'<%= date.strftime(\"%d/%m/%Y\") if date %>\'\r\n	});\r\n	\r\n	$(\"#select_date\").change(function(){\r\n	  	obj = $(this)\r\n		v = obj.val()\r\n        window.location=\"index?date=\"+v;\r\n	});\r\n</script>\r\n\r\n\r\n<div class=\"row\">\r\n\r\n    <%\r\n    \r\n      list = visits.collect{|i| i if i[:status]==\'\' or i[:status]==nil}.compact\r\n        \r\n      complete_list = visits.collect{|i| i if i[:status]==\'Completed\' }.compact\r\n      \r\n      cancel_list = visits.collect{|i| i if i[:status]==\'Cancelled\' }.compact\r\n      \r\n      {:schedule=>list, :complete=>complete_list, :pending=>pvisits}.each_pair do |status, list|\r\n\r\n        if status!=:pending or list.size>0\r\n\r\n    %>\r\n    <div class=\"span7\" style=\"border:0px solid\">    \r\n    \r\n    <h3><%=status.to_s.humanize%> Visit </h3>\r\n    <div class=\"pull-right\"><%#link_to \'Print All\', \"print_all?date=\\\\#{date}\",:class=>\'btn btn-mini\' %></div>\r\n    <table class=\"table\">\r\n        <thead>\r\n            <tr>\r\n                <th>\r\n                    Protocol No\r\n                </th>\r\n                <th>\r\n                    Date\r\n                </th>\r\n                <th>\r\n                    Subject No\r\n                </th>\r\n                <th>\r\n                    Patient Name\r\n                </th>\r\n            \r\n                <th>\r\n                    Visit\r\n                </th>\r\n                <th>\r\n                    Visit Type\r\n                </th>\r\n                <th>\r\n                    SN\r\n                </th>\r\n                <th>\r\n                    Px\r\n                </th>\r\n                <th>\r\n                    Actions\r\n                </th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n        \r\n    <%\r\n        if list.size > 0 \r\n        for i in list\r\n    %>\r\n    <tr>\r\n        <td>\r\n            <%=link_to i[:protocol_no], \"../Project/show?id=\\\\#{i[:project].id}\" %>\r\n        </td>\r\n        \r\n          \r\n        <td>\r\n            <%=link_to i[:date], \"../Visit/show?id=\\\\#{i[:visit].id}\" %>\r\n        </td>\r\n        \r\n        \r\n        <td>\r\n            <%=link_to i[:subject_no], \"../Patient/show?id=\\\\#{i[:patient].id}\" %>        </td>\r\n        <td>\r\n            <%=link_to i[:name], \"../Patient/show?id=\\\\#{i[:patient].id}\" %>\r\n        </td>\r\n        \r\n        \r\n     \r\n        <td>\r\n            <%=\"\\\\#{i[:period_name]}\"%>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=\"\\\\#{i[:visit_type]}\"%>\r\n        </td>\r\n        <td>\r\n              <%=\'<i class=\"splashy-check\"></i>\'.html_safe if i[:status]==\'Completed\' %>\r\n              <%=\'-\' if i[:status]!=\'Completed\' %>\r\n\r\n\r\n        </td>\r\n        <td>\r\n              <%= i[:pharmacist_status] %>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=link_to \"Detail\", \"../Visit/show?id=\\\\#{i[:visit].id}\", :class=>\'btn btn-success btn-mini\' %>\r\n            <%#link_to \"Work List\", \"../Visit/print?id=\\\\#{i[:visit].id}\", :class=>\'btn btn-mini\', :target=>\'_blank\' if i[:visit_type]!=\'UNSCHEDULE\' %>\r\n          \r\n        </td>\r\n        \r\n      \r\n        \r\n    </tr>\r\n\r\n    <% end %>\r\n         <% else %>\r\n       <tr>\r\n           <td colspan=\"5\">No Records </td>\r\n       </tr>\r\n      <% end %>\r\n      \r\n        </tbody>\r\n    </table>\r\n  </div>  \r\n   <% end %>\r\n       <% end %>\r\n</div>\r\n<!---------------- -->\r\n\r\n<%  \r\n        \r\n        events = models[:visit].where(:date=>{\'$ne\'=>nil},:project_id=>{\'$in\'=>projects.collect{|i| i.id}}).sort(\'status,project_id, visit_id\').all\r\n    \r\n    \r\n             events.collect!{|e|  \r\n    \r\n               \r\n                \r\n            \r\n                    period = models[:pl_period].find e.period_id\r\n                    project = mprojects[e.project_id]\r\n                    patient = models[:patient].find e.patient_id\r\n                    patient_name = \'DELETED\'\r\n                    patient_name = \"\\\\#{patient.subject_id} : \\\\#{patient.first_name} \\\\#{patient.last_name} \" if patient\r\n                    \r\n                    title = \"\\\\#{project.protocol_no} : \\\\#{period.visit if period} : \\\\#{patient_name} \\\\#{\'#\'+e.note if e.note}\"\r\n                    color = \"#f5eeef\"\r\n                    \r\n                    \r\n                    color = \"#eff5ef\" if e.status==\'Completed\'\r\n                 \r\n    \r\n    			{\r\n    			        :title=>title,\r\n						:start=> DateTime.parse(e.date.strftime(\"%Y-%m-%d\")+\"T\"+e.date.strftime(\"%H:%M\") ),\r\n						:end=>  DateTime.parse(e.date.strftime(\"%Y-%m-%d\")+\"T\"+e.date.strftime(\"%H:%M\")),\r\n						:allDay=> true,\r\n                        :color=> color,\r\n                        :textColor=>\"#111\",\r\n                        :url=>\"../Visit/show?id=\\\\#{e.id}\"\r\n                }\r\n    \r\n    }\r\n\r\n  er = models[:visit].where(:date=>nil,:project_id=>{\'$in\'=>projects.collect{|i| i.id}}).sort(\'status,project_id, visit_id\').all\r\n%>\r\n<% if er.size>0 %><br/>\r\n<div class=\"aler alert-danger\"><br/>\r\n<%=er.collect{|i| link_to \'ERROR no date\', \"../Visit/edit?id=\\\\#{i.id}\"  }.join(\'<br/>\').html_safe %><br/><br/>\r\n</div>\r\n<% end %>\r\n    \r\n\r\n<style>\r\n.fc-button-content{\r\n    padding:8px;\r\n}\r\n    \r\n</style>\r\n<br/><br/>\r\n<div class=\"row-fluid\">\r\n	<div id=\"calendar\" class=\"span12\"></div>\r\n</div>\r\n\r\n<script>\r\n\r\n    \r\n    /* [ ---- Gebo Admin Panel - calendar ---- ] */\r\n\r\n	$(document).ready(function() {\r\n		gebo_calendar.regular();\r\n// 		gebo_calendar.google();\r\n		//* resize elements on window resize\r\n		var lastWindowHeight = $(window).height();\r\n		var lastWindowWidth = $(window).width();\r\n		$(window).on(\"debouncedresize\",function() {\r\n			if($(window).height()!=lastWindowHeight || $(window).width()!=lastWindowWidth){\r\n				lastWindowHeight = $(window).height();\r\n				lastWindowWidth = $(window).width();\r\n				//* rebuild calendar\r\n				$(\'#calendar\').fullCalendar(\'render\');\r\n				// $(\'#calendar_google\').fullCalendar(\'render\');\r\n			}\r\n		});\r\n	});\r\n	\r\n	//* calendar\r\n	gebo_calendar = {\r\n		regular: function() {\r\n			var date = new Date();\r\n			var d = date.getDate();\r\n			var m = date.getMonth();\r\n			var y = date.getFullYear();\r\n			var calendar = $(\'#calendar\').fullCalendar({\r\n				header: {\r\n					left: \'prev next\',\r\n					center: \'title,today\',\r\n					right: \'\'\r\n				},\r\n				buttonText: {\r\n					prev: \'<i class=\"icon-chevron-left cal_prev\" />\',\r\n					next: \'<i class=\"icon-chevron-right cal_next\" />\'\r\n				},\r\n				aspectRatio: 1.5,\r\n				selectable: true,\r\n				selectHelper: true,\r\n				select: function(start, end, allDay) {\r\n				    console.log(start)\r\n				    window.location=\"../Home/index?date=\"+(start);\r\n				    \r\n				// 	var title = prompt(\'Event Title:\');\r\n				// 	if (title) {\r\n				// 		calendar.fullCalendar(\'renderEvent\',\r\n				// 			{\r\n				// 				title: title,\r\n				// 				start: start,\r\n				// 				end: end,\r\n				// 				allDay: allDay\r\n				// 			},\r\n				// 			true // make the event \"stick\"\r\n				// 		);\r\n				// 	}\r\n				// 	calendar.fullCalendar(\'unselect\');\r\n				},\r\n				editable: true,\r\n				theme: false,\r\n				events: <%=events.to_json.html_safe%>,\r\n				eventColor: \'#bcdeee\'\r\n			})\r\n		}\r\n	};\r\n	\r\n</script>\r\n\r\n<%\r\nstatus = \'cancel\'\r\nlist = cancel_list\r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n       <div class=\"span6\" style=\"border:0px solid\">    \r\n    <h3><%=status.to_s.humanize%> Visit </h3>\r\n    \r\n    <table class=\"table\">\r\n        <thead>\r\n            <tr>\r\n                <th>\r\n                    Protocol No\r\n                </th>\r\n                <th>\r\n                    Date\r\n                </th>\r\n                <th>\r\n                    HN\r\n                </th>\r\n                <th>\r\n                    Patient Name\r\n                </th>\r\n            \r\n                <th>\r\n                    Visit\r\n                </th>\r\n                <th>\r\n                    Visit Type\r\n                </th>\r\n                \r\n                <th>\r\n                    Actions\r\n                </th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n    <%\r\n        for i in list\r\n    %>\r\n    <tr>\r\n        <td>\r\n            <%=link_to i[:protocol_no], \"../Project/show?id=\\\\#{i[:project].id}\" %>\r\n        </td>\r\n        \r\n          \r\n        <td>\r\n            <%=link_to i[:date], \"../Visit/show?id=\\\\#{i[:visit].id}\" %>\r\n        </td>\r\n        \r\n        \r\n        <td>\r\n            <%=link_to i[:hn], \"../Patient/show?id=\\\\#{i[:patient].id}\" %>        </td>\r\n        <td>\r\n            <%=link_to i[:name], \"../Patient/show?id=\\\\#{i[:patient].id}\" %>\r\n        </td>\r\n        \r\n        \r\n     \r\n        <td>\r\n            <%=\"\\\\#{i[:sheet].version} : \\\\#{i[:period_name]}\"%>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=\"\\\\#{i[:visit_type]}\"%>\r\n        </td>\r\n        \r\n        \r\n        <td>\r\n            <%=link_to \"Detail\", \"../Visit/show?id=\\\\#{i[:visit].id}\", :class=>\'btn info \' %>\r\n            <%#link_to \"Work List\", \"../Visit/print?id=\\\\#{i[:visit].id}\", :class=>\'btn\', :target=>\'_blank\' if i[:visit_type]!=\'UNSCHEDULE\' %>\r\n            <%=i[:status]%>\r\n            \r\n        </td>\r\n        \r\n      \r\n        \r\n    </tr>\r\n    <% end %>\r\n        </tbody>\r\n    </table>\r\n    \r\n</div>\r\n</div>\r\n\r\n			</p>\r\n		</div>\r\n		<div class=\"tab-pane\" id=\"tab2\">\r\n			<p>\r\n<h3> My Projects </h3>\r\n\r\n  <div class=\"right\">\r\n        Search : <%= text_field_tag \'search\', \'\', :id=>\'search_field\' %>\r\n    </div>\r\n    \r\n<hr/>    \r\n\r\n<%\r\n    \r\n    for s in status_list\r\n    \r\n    list = projects.collect{|i| i if i.status==s }.compact\r\n    \r\n    \r\n    \r\n    %>\r\n<div class=\"heading\">\r\n    <h3><%=s%> <%=link_to \"Create\",\"../Project/create?status=\\\\#{s}\", :class=>\'btn btn-mini\' %></h3>\r\n</div>    \r\n<table class=\"table\">\r\n<thead>\r\n    <tr>\r\n        <th>No.</th>\r\n        <th>Protocol No.</th>\r\n        <th>Title</th> \r\n        <th>Phase</th>\r\n        <th>Sponsor</th>\r\n        <th>CRO</th>\r\n        <th>CRA</th>\r\n        <th>#Patient</th>\r\n        <th>Duration</th>\r\n    </tr>\r\n</thead>\r\n<tbody>\r\n<%\r\nlist.each_with_index do |i,index|\r\n%>\r\n<tr id=\"<%=i.id%>\" class=\"project\">\r\n    <td><%=index+1%>.</td>\r\n\r\n    <td><%=link_to i.protocol_no, \"../Project/show?id=\\\\#{i.id}\" %></td>\r\n    <td><%=link_to i.project_title[0..30], \"../Project/show?id=\\\\#{i.id}\" %></td>\r\n    <td><%=i.phase%></td>\r\n    <td><%=i.sponsor%></td>\r\n    <td><%=i.cro%></td>\r\n    <td><%=i.cra_contact%></td>\r\n    <td><%=i.no_of_patient%></td>\r\n    <td><%=i.duration%></td>\r\n</tr>\r\n<% end %>\r\n</tbody>\r\n</table>\r\n\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n\r\n\r\n			</p>\r\n		</div>\r\n		<div class=\"tab-pane\" id=\"tab3\">\r\n			<p>\r\n<%\r\n    patients = []\r\n    visits = []\r\n    \r\n    for i in projects \r\n        \r\n        ps = models[:patient].where(:project_id=>i.id).all\r\n        patients += ps\r\n    \r\n        vs = models[:visit].where(:project_id=>i.id).all\r\n        visits += vs\r\n        \r\n    end\r\n\r\n\r\n%>\r\n\r\n\r\n<h3> My Performance </h3>\r\n<hr/>\r\n<b>Project view</b>\r\n<ul>\r\n    <li> Number of Projects : <%=projects.size %> / <%=models[:project].size%></li>\r\n    <li> Number of Open Projects : <%=projects.collect{|i| i if i.status==\'Open\' }.size %></li>\r\n    <li> Number of Close Projects :<%=projects.collect{|i| i if i.status==\'Open\' }.size %></li>\r\n</ul>\r\n<b>Patient view</b>\r\n<ul>\r\n    <li> Number of Patients : <%=patients.size %></li>\r\n    <li> Number of Visits : <%=visits.size %></li>\r\n</ul>\r\n\r\n\r\n\r\n\r\n\r\n			</p>\r\n		</div>\r\n	</div>\r\n</div>\r\n    \r\n    \r\n    \r\n<script>\r\n   var  list = <%=projects.collect{|i| [i.protocol_no,i.short_name,i.id] }.to_json.html_safe %>;\r\n    $(\'#search_field\').keyup(function(){\r\n       \r\n       \r\n        \r\n        q = $(this).val()\r\n        \r\n        var re = new RegExp(q, \'i\');\r\n        \r\n        if(q.length>0){\r\n            \r\n             $(\'.project\').hide();\r\n            \r\n            for(var id in list){\r\n                v = list[id];\r\n                \r\n                var myArray = re.exec(v[0]);\r\n                var myArray2 = re.exec(v[1]);\r\n                \r\n                if(myArray!=null||myArray2!=null){\r\n                    $(\'#\'+v[2]).show();\r\n                }\r\n                \r\n                \r\n            }\r\n            \r\n                \r\n        }else{\r\n             $(\'.project\').show();\r\n        }\r\n        \r\n        \r\n    })\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2018-11-14 17:18:50','2018-11-14 17:18:50','index_pharmacy',''),(3781,'delete_visits',1485,3,'<%\r\n    models = get_model\r\n    project = models[:project].find params[:id]\r\n    visits = models[:visit].where(:project_id=>project.id).all\r\n    for i in visits\r\n    \r\n    i.destroy\r\n        \r\n    end\r\n\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Project/show?id=<%=project.id%>\" />',NULL,NULL,NULL,'2018-11-14 18:37:05','2018-11-14 18:37:05','delete_visits',''),(3782,'document_name',1486,1,'\'diagnosis\'',NULL,NULL,NULL,'2018-11-15 06:26:51','2018-11-15 06:26:51',NULL,NULL),(3785,'document_name',1488,1,'\'demographic\'',NULL,NULL,NULL,'2018-11-15 07:16:48','2018-11-15 07:16:48',NULL,NULL),(3786,'document_name',1489,1,'\'treatment_mbc\'',NULL,NULL,NULL,'2018-11-15 08:01:27','2018-11-15 08:01:27',NULL,NULL),(3787,'document_name',1490,1,'\'cmtin_ebc\'',NULL,NULL,NULL,'2018-11-15 08:43:24','2018-11-15 08:43:24',NULL,NULL),(3788,'missing_partial',1292,3,'<%\r\n    models = get_model\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    user = model[:user].where(:login=>@current_user.login).first\r\n    \r\n    operations = models[:operation].all.collect{|i|[i.id,i.name]}.to_h\r\n    diagnosis = models[:diagnosis].all.collect{|i|[i.id,i.name]}.to_h\r\n    \r\n    if user\r\n        res = models[:thk_record].where(:personal_id=>\'\', :user_id=>user.id)\r\n    else\r\n        res = models[:thk_record].where(:personal_id=>\'\')\r\n    end\r\n    \r\n    g = {\'1\'=>\'M\', \'2\'=>\'F\'}\r\n%>\r\n<table class=\"table table-bordered\" style=\"font-size:0.9em\" >\r\n	<thead>\r\n		<tr>\r\n		    <th width=\"\" align=\"center\" valign=\"middle\">Date</th>\r\n			<th width=\"\" align=\"center\" valign=\"middle\">Hospital</th>\r\n			<th width=\"\" align=\"center\" valign=\"middle\">HN</th>\r\n	\r\n			<th width=\"\" align=\"center\" valign=\"middle\">Op.</th>\r\n			<th width=\"\" align=\"center\" valign=\"middle\">Dx.</th>\r\n			<th>Action</th>\r\n			\r\n			<th></th>\r\n      </tr>\r\n	</thead>\r\n	<tbody>\r\n<%\r\n    res.each do |i|\r\n%>\r\n		<tr>\r\n			<td><%=i.date.strftime(\"%d/%m/%y\") if i.date%></td>\r\n			<td><%= i.hospital %></td>\r\n			<td><%=i.hn %> (<%=g[i.gender]%>) </td>\r\n		\r\n			<td><%=operations[i.operation]%></td>\r\n	        <td><%=diagnosis[i.diagnosis]%></td>\r\n	        \r\n			<td>\r\n			<% if i.personal_id and i.personal_id!=\"\" %>\r\n			 <a href=\"detail?id=<%=i.personal_id%>\" class=\"btn btn-info btn-small\">Detail</a>\r\n			 <% elsif i.hn and i.hn!=\"\" %>\r\n			 <a href=\"detail?id=<%=i.hn%>\" class=\"btn btn-info btn-small\">Detail</a>\r\n			 <% end %>\r\n			 \r\n			 <% if i.personal_id == \"\" %>\r\n			 <a href=\"edit?id=<%=i.id%>\" class=\"btn btn-danger btn-small\">Edit require PID</a>\r\n			 <% end %>\r\n			 \r\n			 <% if i.hn == \"\" %>\r\n			    <a href=\"edit?id=<%=i.id%>\" class=\"btn btn-danger btn-small\">Edit require HN</a>\r\n			 <% end %>\r\n			</td>\r\n		</tr>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2018-11-15 08:47:02','2018-11-15 08:47:02','missing_partial',''),(3789,'document_name',1491,1,'\'outcome\'',NULL,NULL,NULL,'2018-11-16 02:20:44','2018-11-16 02:20:44',NULL,NULL),(3790,'case_report2',1438,2,'\r\n<h1>Case Report Summary </h1>\r\n<%\r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n	tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n \r\n\r\n\r\n	def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    @m_patient= model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    type = \'All\'\r\n    type = params[:report][:type] if params[:report]\r\n    \r\n    procedure = \'all\'\r\n    procedure = params[:report][:procedure] if params[:report]\r\n    \r\n    procedures = %w{all gastro colono push_enteroscopy sigmoid ercp eus dbe liver_biopsy}\r\n    cmap = {}\r\n    for i in procedures\r\n        cmap[i] = i.humanize\r\n    end\r\n    \r\n%>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    v{\r\n        color:blue;\r\n    }\r\n</style>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date  , :order=>[:day,:month,:year]%>\r\n\r\n<br/>\r\n\r\n\r\nSchedule : <%=f.select :type, options_for_select(%w{all elective special_clinic emergency}.collect{|i| i.humanize }, type) %>\r\n\r\nProcedure : <%=f.select :procedure, options_for_select(procedures.collect{|i| [i.humanize,i] }, procedure) %>\r\n\r\n\r\n\r\n\r\n<br/>\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n\r\n\r\n\r\n<% end %>\r\n\r\n\r\n  <%#params.inspect %>\r\n\r\n\r\n<% \r\n\r\n	findings_id = []\r\n    \r\n\r\n\r\n\r\n	if request.post? \r\n  \r\n  \r\n		# select appointment by date\r\n  \r\n		all_app = @models[:appointment].collection.find({:date=>{\'$gte\'=>from_date,\'$lt\'=>to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n  \r\n  \r\n  \r\n		# select pm by module_id of appointment\r\n  \r\n		all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n		\r\n		m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n  \r\n		# select patients by patient_id of pm \r\n		all_patients = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'hn\'=>1}}).to_a\r\n		m_patients = bmap all_patients\r\n  \r\n  \r\n  \r\n		map = {}\r\n  \r\n  \r\n		# for each forms prepare list of module_id \r\n		all_pm = @m_patient_module.collection.find({:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n		m_all_pm = bmap all_pm, \'module_id\'\r\n  \r\n		for i in all_pm\r\n  \r\n			m = i[\'module_name\'].split(\'#\')[-1]\r\n  \r\n			if procedure==\'all\'\r\n  \r\n				map[m] = [] unless map[m]\r\n				map[m] << i[\'module_id\']\r\n  \r\n			else\r\n  \r\n				if m == procedure\r\n  \r\n					map[m] = [] unless map[m]\r\n					map[m] << i[\'module_id\']\r\n  \r\n				end\r\n  \r\n      \r\n			end\r\n  \r\n		end\r\n  \r\n  \r\n		# for each form\'s records \r\n		case_map = {}\r\n		provider_map = {}\r\n  \r\n    for k in map.keys\r\n    \r\n		rs = map[k]\r\n		case_map[k] = [] unless case_map[k]\r\n		if @models[k.to_sym]\r\n    \r\n			conds = {:_id=>{\'$in\'=>rs}}\r\n    \r\n			# 0|Elective\r\n			# 1|Emergency\r\n			# 2|Special clinic\r\n			# 3|Live demo\r\n    \r\n    \r\n			if type !=\'All\'\r\n    \r\n				ctype = \'\'\r\n				case type\r\n					when \'Elective\'\r\n						ctype = \'0\'\r\n					when \'Emergency\'\r\n						ctype = \'1\'\r\n					when \'Special clinic\'\r\n						ctype = \'2\'\r\n				end\r\n        \r\n				conds.merge! :schedule=> ctype\r\n       \r\n			end\r\n			\r\n        \r\n			records = @models[k.to_sym].collection.find(conds, {:fields=>{\'findings\'=>1,\'_id\'=>1,\'schedule\'=>1,\'endoscopist\'=>1,\'created_at\'=>1,\'diagnosis_text\'=>1,\'diagnosis_group\'=>1,\'intervention_text\'=>1,\'procedure\'=>1,\'intervention\'=>1,\'intervention_group\'=>1,\'intervention_summary\'=>1}}).to_a\r\n\r\n   \r\n		\r\n			for i in records\r\n				provider_map[i[\'endoscopist\']] = true \r\n        \r\n				findings_id += i[\'findings\'] if i[\'findings\']\r\n        \r\n				if true\r\n					case_map[k] << i \r\n				end\r\n        \r\n			end\r\n\r\n		end\r\n  \r\n	end\r\n  \r\n  \r\n  \r\n	providers = @models[:provider].collection.find({:_id=>{\'$in\'=>provider_map.keys}})\r\n	m_providers = bmap providers\r\n  \r\n  \r\n  #  collect error\r\n  \r\n	findings = @models[:finding].collection.find({:_id=>{\'$in\'=>findings_id.collect{|x| BSON::ObjectId(x)}}}).to_a\r\n	\r\n	findings_map = bmap findings\r\n  \r\n  \r\n  \r\n	intervention_ids = findings.collect{|x| x[\'intervention\'] }\r\n  \r\n  \r\n  \r\n	interventions = @models[:intervention].collection.find({:_id=>{\'$in\'=>intervention_ids},:intervention_tag=>{\'$ne\'=>\"\"}},{:fields=>{\'intervention_tag\'=>1,\'op_clipping_type\'=>1}}).to_a\r\n  \r\n	interventions_map = bmap interventions\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  if records\r\n  \r\n		for i in records\r\n  \r\n			if i[\'findings\']\r\n            \r\n            \r\n			fs = i[\'findings\'].collect{|x| findings_map[BSON::ObjectId(x)][0] }\r\n			\r\n			fs = fs.collect{|x| {:f=>x,:i=>interventions_map[x[\'intervention\']]} } \r\n            inv = []\r\n            inv = i[\'intervention_group\'].split(\"|\") if i[\'intervention_group\']\r\n            if fs\r\n            for f in fs\r\n                if f[:i]\r\n                    fi = f[:i][0]\r\n                    inv << fi[\'intervention_tag\']\r\n                end\r\n            end\r\n            end\r\n            \r\n            i[\'intervention_group\'] = inv.uniq.join(\'|\')\r\n            \r\n            end\r\n    \r\n            \r\n		end\r\n  \r\n  end\r\n %>\r\n  <%#interventions_map.inspect %>\r\n  \r\n  \r\nFor <i><%=from_date.strftime(\"%d-%m-%Y\")%> to <%=to_date.strftime(\"%d-%m-%Y\")%> </i>\r\n \r\n<br/><br/>\r\n \r\n \r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Procedure</th> <!-- <th>Elective</th><th>Emergency</th><th>Special Clinic</th><th>Undefined</th> --><th>Total</th>\r\n	</tr>\r\n<%  \r\n    tsum = {\'0\'=>0,\'1\'=>0,\'2\'=>0,nil=>0}\r\n\r\n	for k in case_map.keys \r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n		s = i[\'schedule\']\r\n     \r\n		tmap[s] = [] unless tmap[s]\r\n		tmap[s] << i \r\n     \r\n		tsum[s] = 0 unless tsum[s]\r\n		tsum[s] += 1\r\n      \r\n	end\r\n  \r\n%>\r\n    <tr><td><%=k.humanize%></td>\r\n    <!--  \r\n		<td align=\'center\'><%=tmap[\'0\'].size if tmap[\'0\']%></td>\r\n		<td align=\'center\'><%=tmap[\'1\'].size if tmap[\'1\']%></td>\r\n		<td align=\'center\'><%=tmap[\'2\'].size if tmap[\'2\']%></td>\r\n		<td align=\'center\'><%=tmap[\'\'].size if tmap[\'\']%></td>\r\n     --> \r\n    <th><%=case_map[k].size%></th></tr>\r\n	\r\n<% end %>      \r\n <!--\r\n	<tr>\r\n		<td>&nbsp;</td>\r\n		<th><%=tsum[\'0\']%></td>\r\n		<th><%=tsum[\'1\']%></td>\r\n		<th><%=tsum[\'2\']%></td>\r\n		<th><%=tsum[\'\']%></td>\r\n<%\r\n			total_sum = 0 \r\n			total_sum += tsum[\'0\'] if tsum[\'0\']\r\n			total_sum += tsum[\'1\'] if tsum[\'1\']\r\n			total_sum += tsum[\'2\'] if tsum[\'2\']\r\n			total_sum += tsum[\'\'] if tsum[\'\']\r\n\r\n%>\r\n		<th><%=total_sum%></th>\r\n	</tr>\r\n	 -->\r\n</table>\r\n\r\n<br>\r\n  \r\n<% if procedure!=\'all\'%>\r\n<%\r\n    int_map = {}\r\n    for i in records\r\n		int = i[\'intervention_group\']\r\n		if int\r\n			ints = int.split(\'|\') \r\n     \r\n			for j in ints\r\n				int_map[j] = 0 unless int_map[j]\r\n				int_map[j] += 1\r\n			end\r\n		end\r\n    end\r\n  \r\n%>\r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Intervention</th><th>Count</th>\r\n	</tr>\r\n<% for i in int_map.keys %>\r\n	<tr>\r\n		<th><%=i.humanize%></th>\r\n		<td align=\'center\'><%=int_map[i]%></td>\r\n	</tr>\r\n<% end %>\r\n</table>\r\n  \r\n<br/>\r\n  \r\n<%\r\n    dx_map = {}\r\n    for i in records\r\n     \r\n		int = i[\'diagnosis_group\']\r\n		if int\r\n			dxs = int.split(\'|\') \r\n     \r\n			for j in dxs\r\n     \r\n				dx_map[j] = 0 unless dx_map[j]\r\n				dx_map[j] += 1\r\n     \r\n			end\r\n     \r\n		end\r\n      \r\n    end\r\n  \r\n%>\r\n\r\n<%\r\n  \r\n    options = get_document(procedure ).find_by_column_name(\'diagnosis_group\').get_lov_options   \r\n    \r\n    dx_name = {}\r\n    \r\n    for i in options\r\n        \r\n        dx_name[i[0]] = i[1].strip\r\n    \r\n    end\r\n  \r\n  \r\n%>\r\n  \r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Diagnosis Group</th><th>Count</th>\r\n	</tr>\r\n<% \r\n	for i in dx_map.keys \r\n  \r\n		name = \"Undefined(\\\\#{i})\"\r\n		name = dx_name[i] if dx_name[i]\r\n  \r\n%>\r\n	<tr>\r\n		<th><%=name%></th>\r\n		<td align=\'center\'><%=dx_map[i]%></td>\r\n	</tr>\r\n  \r\n<% end %>\r\n</table>\r\n  \r\n<br/>\r\n  \r\n<% end %>\r\n<div class=\'row-fluid\'>\r\n<div style=\'float:right;margin:20px\'>\r\n<%= link_to \'Export EXCEL\', \"case_reports_excel?from_date=\\\\#{from_date.strftime(\'%Y-%m-%d\')}&to_date=\\\\#{to_date.strftime(\'%Y-%m-%d\')}&type=\\\\#{params[:report][:type]}&procedure=\\\\#{params[:report][:procedure]}\", :target=>\'_blank\', :class=>\'btn btn-info\' %>\r\n</div></div>\r\n\r\n<table border=\"1\">\r\n	<tr>\r\n		<th>#</th>\r\n		<th>Procedure</th>\r\n		<th>Date</th>\r\n		<th>HN</th>\r\n		<th>Patient\'s name</th>\r\n		<th>Ans</th>\r\n		<th>Endosocpist</th>\r\n		<th>Diagnosis</th>\r\n		<th>Intervention</th>\r\n		<th>InterventionGroup</th>\r\n	</tr>\r\n\r\n<%\r\n	# zam\r\n	# prepare excel result\r\n	res = {}\r\n	\r\n	# select provider of those records\r\n	for k in case_map.keys\r\n		\r\n		# zam\r\n		# set operation name\r\n		op_name = k.humanize\r\n%>\r\n	<tr style=\"background-color:#ccffcc\">\r\n		<td colspan=\"10\"><h1><%=k.humanize%></h1></td>\r\n	</tr>\r\n<%\r\n  \r\n		tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n			s = i[\'schedule\']\r\n     \r\n			tmap[s] = [] unless tmap[s]\r\n			tmap[s] << i \r\n      \r\n		end\r\n  \r\n		tmap.each_pair do |ks, list| \r\n			index = 0 \r\n			\r\n			# zam\r\n			# set visit_type\r\n			vt = tschedule[ks]\r\n			kk = \"\\\\#{op_name}-\\\\#{vt}\"\r\n			res[kk] = []\r\n%>\r\n    <tr style=\"background-color:#cccccc\">\r\n		<td colspan=\"10\"><%=tschedule[ks]%></td>\r\n	</tr>\r\n<%\r\n	list.each do |i|\r\n	\r\n		# zam\r\n		# temporary for each records\r\n		tmp = {}\r\n    \r\n		pm = m_all_pm[i[\'_id\']][0]\r\n		if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n			patient = m_patients[pm[\'patient_id\']][0]\r\n			provider = nil\r\n			provider = m_providers[i[\'endoscopist\']][0]  if m_providers[i[\'endoscopist\']]\r\n			\r\n			if pm and patient  and provider\r\n        \r\n				schedule = \'-\'\r\n        \r\n				schedule = tschedule[ i[\'schedule\']]\r\n				\r\n				# collect text into tmp\r\n				op_date = i[\'created_at\'].strftime(\"%d/%m/%Y\") \r\n				pat_hn  = patient[\'hn\'] \r\n				pat_name= \"\\\\#{patient[\'first_name\']} \\\\#{patient[\'last_name\']}\"\r\n				\r\n				tmp[:op_date] = op_date\r\n				tmp[:hn] = pat_hn\r\n				tmp[:name] = pat_name\r\n				tmp[:endo] = provider[\'name\']\r\n				tmp[:instrument] = i[\'instrument\']\r\n				tmp[:diag] = i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'diagnosis_text\']\r\n				tmp[:inv_txt] = i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'intervention_text\'] \r\n				tmp[:inv_sum] = i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'intervention_summary\']\r\n				tmp[:inv_group] = i[\'intervention_group\']\r\n				\r\n				\r\n				res[kk] << tmp\r\n        \r\n%>\r\n	<tr>\r\n		<td><%=index+1%></td>\r\n        <td><%=k.humanize%></td>\r\n		<td><%=i[\'created_at\'].strftime(\"%d-%m-%Y\") %></td>\r\n		<td><%=patient[\'hn\'] %></td>\r\n		<td><%=patient[\'first_name\'] %> <%=patient[\'last_name\']%></td>\r\n		<td><%= schedule %></td><td><%= provider[\'name\'] %></td>\r\n        <td >\r\n        <%# i.inspect %>\r\n        <%= i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').html_safe if i[\'diagnosis_text\'] %></td>\r\n        <td ><%= i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').html_safe if i[\'intervention_text\'] %><%= i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').html_safe if i[\'intervention_summary\'] %></td>\r\n<%\r\n           ig = \'background-color:#ffcccc\'\r\n%>\r\n        <td style=\'<%=ig if  i[\'intervention_text\']!=\"\" and i[\'intervention_group\'] and  i[\'intervention_group\'].strip==\'\' %>\'>\r\n<%\r\n            intv = \'-\'\r\n          \r\n%>\r\n			<%=i[\'intervention_group\']%><%#i[\'intervention_text\']%>\r\n			</td>\r\n        </tr>\r\n<%\r\n        \r\n				index+=1\r\n        \r\n			end # if pm and patient  and provider\r\n    \r\n		end #if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n  \r\n        \r\n	end # list.each do |i|\r\n  \r\n	end # tmap.each_pair do |ks, list| \r\n  \r\n	end # for k in case_map.keys\r\n	\r\n# 	session[:case_report_excel] = res\r\n# 	session[:case_report_from] = from_date.strftime(\"%d/%m/%Y\")\r\n# 	session[:case_report_to] = to_date.strftime(\"%d/%m/%Y\")\r\n  \r\n%>\r\n</table>\r\n<%# res.to_json.html_safe %>\r\n<%\r\n  \r\n  # for each recoreds to reprrt\r\n  \r\n%>\r\n  \r\n  \r\n  \r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2018-11-23 02:45:59','2018-11-23 02:45:59','case_report2',''),(3791,'mit_report',1438,2,'<h1>Endoscopist Report </h1>\r\n<%\r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n	tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n \r\n\r\n\r\n	def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    @m_patient= model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    type = \'All\'\r\n    type = params[:report][:type] if params[:report]\r\n    \r\n    procedure = \'all\'\r\n    procedure = params[:report][:procedure] if params[:report]\r\n    \r\n    # procedures = %w{all gastro colono push_enteroscopy sigmoid ercp eus dbe liver_biopsy}\r\n    procedures = %w{all gastroscopy colonoscopy eus ercp sigmoid esd eftr peg ped_j nj dbe}\r\n\r\n    cmap = {}\r\n    for i in procedures\r\n        cmap[i] = i.humanize\r\n    end\r\n    \r\n%>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    v{\r\n        color:blue;\r\n    }\r\n    table th.text-center, table td.text-center { \r\n        text-align: center;\r\n    }\r\n    .table thead th{\r\n        background-color:white;\r\n        \r\n    }\r\n    \r\n</style>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date  , :order=>[:day,:month,:year]%>\r\n\r\n<br/>\r\n\r\n\r\n<!--Schedule : <%=f.select :type, options_for_select(%w{all elective special_clinic emergency}.collect{|i| i.humanize }, type) %>-->\r\n\r\nProcedure : <%=f.select :procedure, options_for_select(procedures.collect{|i| [i.humanize,i] }, procedure), {},{multiple:true, class:\"chzn-select\"} %>\r\n\r\n\r\n\r\n\r\n<br/>\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<%  if request.post? %> \r\n<button id=\"print_btn\" type=\"button\" class=\"btn\">Print</button>\r\n<script>\r\n   \r\n    $(\"#print_btn\").click(function() {\r\n        var content = $(\"#print_table\").html();\r\n        var mywindow = window.open(\'\', \'Print\', \'height=600,width=800\');\r\n    \r\n        mywindow.document.write(\'<html><head><title>รายงานประจำเดือน</title>\');\r\n        var htmlToPrint = \'\' +\r\n        \'<style type=\"text/css\">\' +\r\n        \'table th, table td {\' +\r\n        \'border:0.5px solid #000;\' +\r\n        \'font-size:0.8em;\'+\r\n        \'padding:5px;\'+\r\n        \'}\' +\r\n        \'table{\'+\r\n        // \'padding:30px;\' +\r\n        \'border-spacing:0px;\' +\r\n        \'border-collapse: collapse;\'+\r\n        \'}\' +\r\n        \'table th.endoname{\'+\r\n        \'text-align: left;\'+\r\n        \'font-size:0.5em;\'+\r\n        \'}\'+\r\n        \'table th.text-center, table td.text-center { \'+\r\n        \'text-align: center;\'+\r\n        \'}\'+\r\n        \'</style>\';\r\n        mywindow.document.write(htmlToPrint);\r\n        mywindow.document.write(\'</head><body >\');\r\n        mywindow.document.write(content);\r\n        mywindow.document.write(\'</body></html>\');\r\n    \r\n        mywindow.document.close();\r\n        mywindow.focus()\r\n        mywindow.print();\r\n        mywindow.close();\r\n        return true;\r\n        // setTimeout(function(){\r\n        // window.print()\r\n        // },3000);\r\n    })\r\n    \r\n</script>\r\n<%  end %>\r\n<% end %>\r\n\r\n<% if request.post?  %>\r\n<%\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    \r\n    # forms = %w{colonoscopy gastro dbe sigmoid push_enteroscopy ercp eus liver_biopsy percutaneous_drainage}\r\n    procedure.delete(\"\")\r\n    if procedure.include?(\'all\')\r\n        forms = %w{gastroscopy colonoscopy eus ercp sigmoid esd eftr peg ped_j nj dbe } \r\n    else\r\n        forms =  procedure\r\n    end\r\n    pmap = {}\r\n    map = {}\r\n    names = []\r\n    providers = @models[:provider].collection.find({},{:fields=>{:_id=>1,:name=>1}}).to_a\r\n    \r\n    for i in providers\r\n        pmap[i[\'_id\']] = {:p=>i[\'name\'],:f=>{}}\r\n        names << [i[\'name\'],i[\'_id\']]\r\n    end\r\n    \r\n    names.sort!{ |a,b| a[0]<=>b[0] }\r\n    \r\n    for i in forms\r\n        records = @models[i.to_sym].collection.find({:date=>{\'$gte\'=>from_date,\'$lt\'=>to_date}},{:fields=>{:_id=>1,:endoscopist=>1}}).to_a\r\n        for  r in  records \r\n            if pmap[r[\'endoscopist\']] \r\n            pmap[r[\'endoscopist\']][:f][i] = 0  unless  pmap[r[\'endoscopist\']][:f][i]\r\n            pmap[r[\'endoscopist\']][:f][i] += 1\r\n            end\r\n        end\r\n    end\r\n    \r\n%>\r\n<div id=\"print_table\">\r\n<center>\r\nรายงานประจำเดือน</br>\r\n<%=from_date.strftime(\"%-d \")+month_th[from_date.strftime(\"%m\").to_i-1]+\" \"+(from_date.strftime(\"%Y\").to_i+543).to_s%> \r\n- \r\n<%=to_date.strftime(\"%-d \")+month_th[to_date.strftime(\"%m\").to_i-1]+\" \"+(to_date.strftime(\"%Y\").to_i+543).to_s%> \r\n</center>\r\n<table class=\"table table-bordered\">\r\n<!--<thead>-->\r\n<tr><th>&nbsp;</th>\r\n<%\r\n  for i in forms\r\n%>\r\n<th class=\'text-center\'><%=i%></th>\r\n<% end %>\r\n</tr>\r\n<!--</thead>-->\r\n<tbody>\r\n<% for i in names %>\r\n<%  row = \"<tr><th class=\'endoname\'>\".html_safe+i[0]+\"</th>\".html_safe\r\n    num_form = 0\r\n    for f in forms\r\n        v = 0\r\n        num_form = v = pmap[i[1]][:f][f] if pmap[i[1]][:f][f]\r\n        row+=\"<td class=\'text-center\'>\".html_safe+v.to_s+\"</td>\".html_safe\r\n    end\r\n    row+=\"</tr>\".html_safe\r\n    if num_form>0 \r\n        %><%= row %><%\r\n    end\r\n%>\r\n<% end %>\r\n</tbody>\r\n</table>\r\n</div>\r\n\r\n<% end #if request.post? %>\r\n',NULL,NULL,NULL,'2018-11-29 02:36:34','2018-11-29 02:36:34','mit_report',''),(3792,'tmp_staff_report_result',805,3,'\r\n<%\r\n    tb = Time.now \r\n    \r\n    def map_parent_object(m_arr = [])\r\n        rs = {}\r\n        m_arr.each do |i|\r\n            rs[i[:parent_id].to_s] = i\r\n        end\r\n        return rs\r\n    end\r\n%>\r\n<%= render :inline=>this.init %>\r\n<%#params.inspect %><br/>\r\n<%\r\n\r\n        \r\n\r\n   if true\r\n    rs = {}\r\n    res = {}\r\n    ars = []\r\n    pat_mod = {}\r\n    app_date = Time.now\r\n    if q = params[:query]\r\n        sdate = q[:sdate]\r\n        edate = q[:edate]\r\n        app_date = sdate\r\n        \r\n        \r\n        \r\n        rs = get_appointment_by_date(sdate, edate).compact.sort_by{|i|  (i[:start] == \'\' or i[:start] == nil) ? \'00:00\' : i[:start].strftime(\'%H:%M\')}\r\n        app_ids = rs.collect{|i| i.id.to_s}\r\n        pat_mod = get_patient_module_by_appointment_ids(app_ids)\r\n        par_ids = pat_mod.collect{|i| i.id.to_s}\r\n        pat_ids = pat_mod.collect{|i| i[:patient_id].to_s}\r\n        mod_pre = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\#{@current_project.name}#pre_anesthetic\")\r\n        mod_pos = get_patient_module_document_by_patient_module_appointment(par_ids, \"\\#{@current_project.name}#post_anesthetic\")\r\n        ids_pre = get_module_id_array(mod_pre)\r\n        ids_pos = get_module_id_array(mod_pos)\r\n        a_pre = @models[:pre_anesthetic].find(ids_pre)\r\n        a_pos = @models[:post_anesthetic].find(ids_pos)\r\n        \r\n        a_pat = @m_pat.find(pat_ids)\r\n        \r\n        par_app = get_module_id_map(pat_mod)\r\n        par_pre = map_parent_object(mod_pre)\r\n        par_pos = map_parent_object(mod_pos)\r\n        map_pre = get_map(a_pre)\r\n        map_pos = get_map(a_pos)\r\n        \r\n        map_pat = get_map(a_pat)\r\n        map_ward = get_map(@models[:ward].all)\r\n        # map_room = get_map(@models[:or_room].all)\r\n        \r\n        map_anes_tech = {\'\'=>\'Undefined\',\'1\'=>\'General anesthesia (balanced technique)\', \'2\'=>\'General anesthesia (Inhalation technique)\',\'3\'=>\'General anesthesia (TIVA)\',\'4\'=>\'Monitor anesthetic care\',\'5\'=>\'Regional anesthesia\',\'6\'=>\'Nerve Block\',\'7\'=>\'Combined general anesthesia and nerve block\',\'8\'=>\'Combined general anesthesia and regional anesthesia\',\'9\'=>\'GA due to RA/Nerve block fail\'}\r\n        map_pacu = {nil=>\'Undefined\', \'\'=>\'Undefined\',\'1\'=>\'OR\',\'2\'=>\'RR\',\'3\'=>\'WARD\',\'4\'=>\'ICU\'}\r\n        \r\n        res = par_pre\r\n        oti = [] # intra-operative\r\n        otp = [] # pacu-operative\r\n        rs.each do |i|\r\n            tmp = {}\r\n            pm_app = par_app[i.id.to_s]\r\n            # tmp[:par_id] = par_id.id\r\n            pm_pre = par_pre[pm_app.id.to_s]\r\n            pm_pos = par_pos[pm_app.id.to_s]\r\n            \r\n            if  pm_pos.nil?\r\n                next\r\n            end\r\n            \r\n            # patient info\r\n            pat_id = pm_app[:patient_id].to_s\r\n            pat = map_pat[pat_id]\r\n            \r\n            tmp[:hn] = pat[:hn]\r\n            tmp[:name] = \"\\#{pat[:prefix_name]}\\#{pat[:first_name]}  \\#{pat[:last_name]}\"\r\n            \r\n            today = i[:date]\r\n            if pat[:birth_date]\r\n                d = Date.new(today.year, pat[:birth_date].month,  pat[:birth_date].day)\r\n                age = d.year - pat[:birth_date].year - (d > today ? 1 : 0)\r\n                tmp[:age] = age\r\n            else\r\n                tmp[:age] = \'-\'\r\n            end\r\n            \r\n            # appointment\r\n            tmp[:diag] = i[:diagnosis]\r\n            tmp[:operation] = i[:operation]\r\n            tmp[:ward] = (i[:ward]==\'\' or i[:ward].nil?) ? \'N/A\' : map_ward[i[:ward]][:name]\r\n            tmp[:surgeon] = (i[:surgeon]==\'\' or i[:surgeon].nil?) ? \'N/A\' : @provider[i[:surgeon]]\r\n            tmp[:ast_surgeon] = (i[:assist]==\'\' or i[:assist].nil?) ? \'N/A\' : @provider[i[:assist]]\r\n            tmp[:app_date] = i[:date]\r\n            \r\n            # anesth team\r\n            pre = !pm_pre.nil? ? map_pre[pm_pre[:module_id].to_s] : nil\r\n            pos = map_pos[pm_pos[:module_id].to_s]\r\n            # tmp[:debug] = \"PRE : \\#{pre.to_json.html_safe}<br/>POS : \\#{pos.to_json.html_safe}\"\r\n            \r\n            if pre\r\n                tmp[:team_pre_1] = (pre[:anesthesiologist]==\'\' or pre[:anesthesiologist].nil?) ? \'N/A\' : @provider[pre[:anesthesiologist].to_s]\r\n                tmp[:team_pre_2] = (pre[:nurse]==\'\' or pre[:nurse].nil?) ? \'N/A\' : @provider[pre[:nurse].to_s]\r\n            else\r\n                tmp[:team_pre_1] = \'N/A\'\r\n                tmp[:team_pre_2] = \'N/A\'\r\n            end\r\n            \r\n            tmp[:team_pos_1] = (pos[:anesthesiologist]==\'\' or pos[:anesthesiologist].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist].to_s]\r\n            tmp[:team_pos_2] = (pos[:nurse_anesthetist]==\'\' or pos[:nurse_anesthetist].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetist].to_s]\r\n            \r\n            # intra-op\r\n            tmp[:xproc] = \"Neuroanesthesia with Special monitor\"\r\n            tmp[:dur_time] = \'N/A\'\r\n            tmp[:dur_anesthesiologist] = \'N/A\'\r\n            tmp[:dur_anesthetist] = \'N/A\'\r\n            dur_off = (pos[:anesthetic_official_duration]==\'\' or pos[:anesthetic_official_duration].nil?) ? 0 : pos[:anesthetic_official_duration].to_i\r\n            dur_non = (pos[:anesthetic_non_official_duration]==\'\' or pos[:anesthetic_non_official_duration].nil?) ? 0 : pos[:anesthetic_non_official_duration].to_i\r\n            if dur_non==0 and dur_off > 0\r\n                ds = pos[:anesthetic_official_date_start].strftime(\'%d/%m/%Y\') if pos[:anesthetic_official_date_start]\r\n                de = pos[:anesthetic_official_date_end].strftime(\'%d/%m/%Y\') if pos[:anesthetic_official_date_end]\r\n                ts = pos[:anesthetic_official_time_start].strftime(\'%H:%M\') if pos[:anesthetic_official_time_start]\r\n                te = pos[:anesthetic_official_time_end].strftime(\'%H:%M\') if pos[:anesthetic_official_time_end]\r\n                \r\n                tmp[:dur_time] = \"\\#{ds} \\#{ts} - \\#{de} \\#{te} (\\#{dur_off} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                tmp[:dur_anesthetist] = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n            elsif dur_non > 0 and dur_off==0\r\n                ds = pos[:anesthetic_nonofficial_date_start].strftime(\'%d/%m/%Y\') if pos[:anesthetic_nonofficial_date_start]\r\n                de = pos[:anesthetic_nonofficial_date_end].strftime(\'%d/%m/%Y\') if pos[:anesthetic_nonofficial_date_end]\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\') if pos[:anesthetic_nonofficial_time_start]\r\n                te = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\') if pos[:anesthetic_nonofficial_time_end]\r\n                \r\n                tmp[:dur_time] = \"\\#{ds} \\#{ts} - \\#{de} \\#{te} (\\#{dur_non} mins)\"\r\n                tmp[:dur_anesthesiologist] = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                tmp[:dur_anesthetist] = \"\\#{a1}, \\#{a2}\"\r\n                \r\n                # OT Report\r\n                tmp[:xtime] = \"\\#{ts}-\\#{te}\"\r\n                tmp[:xanes] = tmp[:dur_anesthesiologist]\r\n                tmp[:xnur1] = a1\r\n                tmp[:xnur2] = a2\r\n            elsif dur_non > 0 and dur_off > 0\r\n                ds_off = pos[:anesthetic_official_date_start]\r\n                de_off = pos[:anesthetic_official_date_end]\r\n                ds_non = pos[:anesthetic_nonofficial_date_start]\r\n                de_non = pos[:anesthetic_nonofficial_date_end]\r\n                \r\n                ts_off = pos[:anesthetic_official_time_start].strftime(\'%H:%M\') if  pos[:anesthetic_official_time_start]\r\n                te_off = pos[:anesthetic_official_time_end].strftime(\'%H:%M\') if  pos[:anesthetic_official_time_end]\r\n                ts_non = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\') if  pos[:anesthetic_nonofficial_time_start]\r\n                te_non = pos[:anesthetic_nonofficial_time_end].strftime(\'%H:%M\') if  pos[:anesthetic_nonofficial_time_end]\r\n                \r\n                ds = ds_off\r\n                de = de_non\r\n                ts = ts_off\r\n                te = te_non\r\n                if ds_off == ds_non and de_off == de_non\r\n                    if ts_non < ts_off\r\n                        ts = ts_non\r\n                        te = te_off\r\n                    end\r\n                    tmp[:dur_time] = \"\\#{ds.strftime(\'%d/%m/%Y\')} \\#{ts} - \\#{de.strftime(\'%d/%m/%Y\')} \\#{te} (\\#{dur_off + dur_non} mins)\" \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\#{ts}-\\#{te}\"\r\n                elsif de_non > ds_off\r\n                    tmp[:dur_time] = \"\\#{ds.strftime(\'%d/%m/%Y\')} \\#{ts} - \\#{de.strftime(\'%d/%m/%Y\')} \\#{te} (\\#{dur_off + dur_non} mins)\"  \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\#{ts}-\\#{te}\"\r\n                elsif ds_non < de_off\r\n                    ds = ds_non\r\n                    de = de_off\r\n                    ts = ts_non\r\n                    te = te_off\r\n                    tmp[:dur_time] = \"\\#{ds.strftime(\'%d/%m/%Y\')} \\#{ts} - \\#{de.strftime(\'%d/%m/%Y\')} \\#{te} (\\#{dur_off + dur_non} mins)\"    \r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\#{ts}-\\#{te}\"\r\n                else\r\n                    tmp[:dur_time] = \"official time : (\\#{ds_off} \\#{ts_off} - \\#{de_off} \\#{te_off}) / non-official time : (\\#{ds_non} \\#{ts_non} - \\#{de_non} \\#{te_non}) [\\#{dur_off + dur_non} mins] \"\r\n                    \r\n                    # OT Report\r\n                    tmp[:xtime] = \"\\#{ts_non}-\\#{te_non}\"\r\n                end\r\n\r\n\r\n                off_a0 = (pos[:anesthesiologist_official]==\'\' or pos[:anesthesiologist_official].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_official].to_s]\r\n                off_a1 = (pos[:nurse_anesthetic_official]==\'\' or pos[:nurse_anesthetic_official].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_official].to_s]\r\n                non_a0 = (pos[:anesthesiologist_nonofficial]==\'\' or pos[:anesthesiologist_nonofficial].nil?) ? \'N/A\' : @provider[pos[:anesthesiologist_nonofficial].to_s]\r\n                non_a1 = (pos[:nurse_anesthetic_nonofficial_]==\'\' or pos[:nurse_anesthetic_nonofficial_].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_].to_s]\r\n                non_a2 = (pos[:nurse_anesthetic_nonofficial_2]==\'\' or pos[:nurse_anesthetic_nonofficial_2].nil?) ? \'N/A\' : @provider[pos[:nurse_anesthetic_nonofficial_2].to_s]\r\n                \r\n                \r\n                tmp[:dur_anesthesiologist] = \"\\#{off_a0} (official time) / \\#{non_a0} (non-official time)\"\r\n                tmp[:dur_anesthetist] = \"\\#{off_a1} (official time) / \\#{non_a1}, \\#{non_a2} (non-official time)\"\r\n                \r\n                # OT Report\r\n                tmp[:xanes] = non_a0\r\n                tmp[:xnur1] = non_a1\r\n                \r\n                tmp[:xnur2] = non_a2\r\n            else\r\n                ts = pos[:anesthetic_nonofficial_time_start].strftime(\'%H:%M\') if  pos[:anesthetic_nonofficial_time_start]\r\n   