me].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Booking</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\',:style=>\'width:120px\' %> <%=link_to \"( Today Click )\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n       <%= date.strftime(\'%A %d %B %Y\')%><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' }.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n </div><br/>\r\n \r\n',NULL,NULL,NULL,'2018-12-04 04:46:39','2018-12-04 04:46:39','',''),(3795,'create',1494,2,'<%\r\n	params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n	return_url = url(\'index\')\r\n	return_url = params[:return] if params[:return]\r\n	\r\n	\r\n	locker_model = get_model(\'locker\')\r\n	\r\n	\r\n	\r\n	date = Time.now.strftime(\"%d/%m/%Y\")\r\n	time = Time.now.strftime(\"%H:%M\")\r\n	\r\n	# date = params[:date] if params[:date]\r\n	# time = params[:time] if params[:time]\r\n	\r\n	%> \r\n<%# params[:date] %>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				<h3>New <%=this.table_name.to_s.humanize%></h3>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n				<div style=\"border:0px solid\">\r\n					<div class=\"document-border\" style=\"border:0px solid\">\r\n						<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n						<%\r\n							model = get_model(this.table_name)\r\n							\r\n							\r\n							if request.post? \r\n							    m = nil\r\n							        p_date = params[:record][:date]\r\n							        \r\n							        m_date = Date.to_mongo(p_date)\r\n							        \r\n							        a_ids   = @models[:appointment].where(:date=>m_date).all.collect{|i| i.id.to_s}\r\n							        m_mod = @module_model.where(:module_id=>a_ids, :patient_id=>params[:patient_id]).first\r\n							        \r\n							        if m_mod\r\n							            flash[:notice]=\"Appointment exist.\"\r\n							            m = m_mod\r\n							        else\r\n							            flash[:notice]=\"New record has been created\"\r\n							            doc = get_document this.document_name\r\n    							        record = doc.record_create(model,params)\r\n    							        record.update_attributes :status=>\"Waiting\"\r\n    							        m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n							        end\r\n\r\n%>\r\n<br/>\r\n<h3><%= flash[:notice] %></h3>\r\n<br/>\r\n\r\n						<script type=\"text/javascript\">\r\n							<% if  @appointment %>\r\n							//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\n							window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n							\r\n							<% else %>\r\n							//window.location = \"../Home/index\"\r\n							<% end %>\r\n							\r\n							window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n							\r\n							\r\n						</script>\r\n						<%\r\n							else  \r\n							\r\n							  if params[:data]\r\n							  record = model.new params[:data] \r\n							  else\r\n							  record = model.new \r\n							  end\r\n							\r\n							  \r\n							%>\r\n						<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n						<%= hidden_field_tag :return, return_url if params[:return] %>\r\n						<%\r\n							fid = 0\r\n							name = \'patient_id\'\r\n							value = params[:patient_id]\r\n							value = params[:id] if params[:id]\r\n							ref_number = @next_id\r\n							ref_number = params[:ref_number] if params[:ref_number]\r\n							\r\n							%>\r\n						<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n							<div class=\"modal-header\">\r\n								<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n								<h3>Select Patient</h3>\r\n							</div>\r\n							<div class=\"modal-body\">\r\n								<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n									<table id=\"search-panel\" style=\"width:100%\" >\r\n										<tr>\r\n											<td align=\'center\' style=\"border:0px solid\">\r\n												Patient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n												<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n												<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %>\r\n											</td>\r\n										</tr>\r\n									</table>\r\n								</div>\r\n								<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n									<br/>\r\n									Loading..\r\n								</div>\r\n							</div>\r\n						</div>\r\n						<div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n							Ref : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n							<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\n							Patient : \r\n							<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n							<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n							Date : <%= text_field_tag \'date\',date  ,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\n							Time : <%= text_field_tag \'time\',time,:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n						</div>\r\n						<div id=\'patient\'></div>\r\n						<script>\r\n						    function search_appointment(objs){\r\n						        \r\n						        list = [];\r\n						        for(var id in objs){\r\n						            i = objs[id];\r\n						            list.push(i[\'id\']);\r\n						            \r\n						        }\r\n						        \r\n						         url = \'search_appointment?plist=\'+list.join(\',\')\r\n						        	$.ajax({\r\n							        url: url,\r\n							success: function(data){\r\n							    eval(data);\r\n							}\r\n							});\r\n						    }\r\n						\r\n							$(\"#record-time\").kendoTimePicker({\r\n							value: \'<%= time %>\',\r\n							interval: 10\r\n							});\r\n							$(\"#record-date\").kendoDatePicker({\r\n							  value: \'<%= date %>\',\r\n							});\r\n							\r\n							$(\"#ref-record\").kendoAutoComplete();\r\n							$(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n							\r\n							function doSearch(){\r\n							$(\'#search-result\').css(\"display\", \"block\");\r\n							url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n							   url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n							   url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n							$.ajax({\r\n							url: url,\r\n							success: function(data){\r\n							$(\'#search-result\').html(data);  \r\n							}\r\n							});\r\n							   \r\n							}\r\n							function doClose(){\r\n							  \r\n							$(\'#SelectPatient\').hide();\r\n							$(\".modal-backdrop\").hide(\'fade\');\r\n							\r\n							}\r\n							\r\n							\r\n							\r\n							function doSelect(value){\r\n							$(\'#<%=fid%>\').val(value);\r\n							   \r\n							   url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n							url += \'&id=\'+value\r\n							   url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n							   \r\n							$.ajax({\r\n							url: url,\r\n							success: function(data){\r\n							     $(\'#patient\').html(data);  \r\n							     $(\'#SelectPatient\').hide();\r\n							     $(\".modal-backdrop\").hide(\'fade\');\r\n							}\r\n							});\r\n							   \r\n							}\r\n							\r\n							\r\n							\r\n							\r\n							\r\n							$(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n							if(event.keyCode == 13) {\r\n							doSearch();\r\n							 event.preventDefault();\r\n							 return false;\r\n							}else{\r\n							\r\n							$(\'#search-result\').html(\'Loading..\')\r\n							}\r\n							});\r\n							\r\n							<% if params[:patient_id] %>\r\n							$(\'#search-result\').css(\"display\", \"block\");\r\n							doSelect(\'<%=params[:patient_id]%>\')    \r\n							<% else %>\r\n							\r\n							$(\'#SelectPatient\').modal({\r\n							           show: true, \r\n							           backdrop: \'static\',\r\n							           keyboard: true\r\n							})\r\n							\r\n							     \r\n							<% end %>\r\n							\r\n							\r\n						</script>\r\n						<%\r\n							params[:form] = {}\r\n							params[:form][:model] = model\r\n							params[:form][:form] = f\r\n							params[:form][:record] = record\r\n							\r\n							\r\n							\r\n							%>\r\n						<p>\r\n							<%= this.form.html_safe %>\r\n						</p>\r\n						<br/>\r\n						<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n						<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n						<% end %>\r\n						<span style=\"color:green\"><%=flash[:notice]%></span>\r\n						<% end %>\r\n					</div>\r\n				</div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<script>\r\n	var validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n	$(\"#record-submit\").click(function() {\r\n	\r\n	if (!validator.validate()||$(\'#0\').val()==\"\") {\r\n	alert(\'Please fill all information\');\r\n	if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\n	return false;\r\n	\r\n	}else{\r\n	    return true;\r\n	    if(confirm(\'Are you sure?\')==true){\r\n	        return true;\r\n	    }\r\n	    return false;\r\n	}\r\n	});\r\n	\r\n	$(\"#start\").hide()\r\n</script>',NULL,NULL,NULL,'2018-12-04 04:51:33','2018-12-04 04:51:33','create',''),(3796,'index',1495,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n	return_url = url(\'index\')\r\n	return_url = params[:return] if params[:return]\r\n	\r\n	locker_model = get_model(\'locker\')\r\n	\r\n	date = Time.now.strftime(\"%d/%m/%Y\")\r\n	time = Time.now.strftime(\"%H:%M\")\r\n	\r\n    date = params[:date] if params[:date]\r\n    time = params[:time] if params[:time]\r\n    \r\n    s_models = get_model(\'schedule\').all\r\n    \r\n    model = get_model(\'appointment\')\r\n    if request.post?\r\n        if params[:id]\r\n            @patient_module = @module_model.find(params[:id])\r\n            record = model.find(@patient_module.module_id)\r\n            %><%#=record.inspect%><%\r\n            # @patient_module.update_attributes :date=>params[:date],:time=>params[:time]\r\n            record.update_attributes :status=>\"Appointed\",:date=>params[:date],:start=>params[:time],:stop=>params[:time]\r\n%>\r\n<script>\r\n$.sticky(\"<i class=\'icon-ok icon-white\'></i> Save appointment success\", {autoclose : 3000, position: \"top-center\" , type: \"st-success\"});\r\n</script>\r\n<%            \r\n            # @patient_module.update_attributes :status=>\"Appointed\",:date=>params[:date],:time=>params[:time]\r\n        end\r\n        if params[:remove_id]\r\n            @patient_module = @module_model.find(params[:remove_id])\r\n            record = model.find(@patient_module.module_id)\r\n            record.update_attributes :status=>\"Waiting\"\r\n%>\r\n<script>\r\n$.sticky(\"<i class=\'icon-remove\'></i> Removed appointment success\", {autoclose : 3000, position: \"top-center\" , type: \"st-error\"});\r\n</script>\r\n<%            \r\n        end\r\n    end\r\n	\r\n%> \r\n\r\n<div class=\"span11\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-calendar\" style=\"margin-left:10px;\"></i> Date appointment\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n            firstday = Date.strptime(\"1\"+date.strftime(\"/%m/%Y\"), \'%d/%m/%Y\')\r\n            d = date.strftime(\"%u\")\r\n            # %U if start Sun,%W if start Mon\r\n            thisweek = date.strftime(\"%W\").to_i - firstday.strftime(\"%W\").to_i \r\n            thisweek +=1\r\n            day_provider = s_models.collect{|i| i if i.day==d}.compact\r\n        %>\r\n            Date : <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\',:style=>\'width:120px\' %> \r\n            Time : <%= text_field_tag \'time\',time,:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n            <%=link_to \"( Today Click )\", \"./index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %>\r\n            <br><%=date.strftime(\"%A\")%> Week: <%=thisweek%>\r\n            <%for p in day_provider%>\r\n                <%if p.week.include? thisweek.to_s %>\r\n                <%=\" GA : \" if p.type==\"1\"%>\r\n                <%=\" LA : \" if p.type==\"2\"%>\r\n                <%=p.doctor%> \r\n                <%end%>\r\n            <%end%>\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"./index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n	$(\"#record-time\").kendoTimePicker({\r\n		value: \'<%= time %>\',\r\n		interval: 10\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n</div><!--w-box Date appointment-->\r\n<br>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n    # status_list=%w{waiting }.collect{|i| i.humanize}\r\n\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    table_model = %w{ hn patient procedure operation pre_operation }.collect{|i| i.to_sym}\r\n\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\',:procedure=>\'Diagnosis\',:start=>\'Start\',:tel=>\'Tel\',:date_add=>\'Date added\',:operation=>\'Operation\',:pre_operation=>\'Pre operation\' }\r\n\r\n\r\n\r\n%>\r\n\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-list\" style=\"margin-left:10px;\"></i> Appointment list\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n<%\r\n    apl = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day,:order=>\"start\")\r\n    apl.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id) and i.status!=\"Waiting\"\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\") if patient\r\n         public_id = \'-\'\r\n         app_date = i.date.strftime(\"%d/%m/%Y\")+i.start.strftime(\" %H:%M\")\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type,:start=>app_date,:operation=>i.operation,:pre_operation=>i.pre_operation\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Appoint\',\"javascript:confirm_app(\'\\\\#{m.id}\',\'\\\\#{provider_name}\',\'\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\',\'\\\\#{procedure_name}\',\'\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\')\",:class=>\'btn btn-small btn-success\') +\" \"+link_to(\'Detail\',\"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\",:class=>\'btn btn-small \')\r\n        #  c[:pending_ctrl]=link_to(\'Detail\',\"../Appointment/show?id=\\\\#{m.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Appoint\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n\r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"../Home/patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)+\' \'+link_to(\'Remove\',\"javascript:remove_app(\'\\\\#{m.id}\',\'\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\',\'\\\\#{app_date}\')\",:class=>\'btn btn-small btn-danger\')\r\n        #  c[:processing_ctrl]=link_to(\'Detail\',\"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\",:class=>\'btn btn-small \')\r\n\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n \r\n\r\n%>    \r\n    <%= tabular :model=>[:start,:provider]+table_model+[:note,:processing_ctrl],:data=>apl,:labels=>labels %>\r\n    </div>\r\n</div><!--w-box Appointment list-->\r\n\r\n\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-book\" style=\"margin-left:10px;\"></i> Booking list\r\n        <span style=\"float:right\"><a href=\"../Appointment/create?return=../Home/index\" class=\"btn\"><i class=\"splashy-add\"></i> New booking</a></span>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n<%\r\n    \r\n    aps = ap_model.all(:status=>\'Waiting\') \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    # list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         visit_type = \'<font color=red>\'.html_safe+visit_type+\'</font>\'.html_safe if visit_type and visit_type.upcase==\'EMERGENCY\'\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\") if patient\r\n         public_id = \'-\'\r\n         tel = \'\'\r\n         tel += \',\'+patient.tel_home if patient.tel_home and patient.tel_home!=\'\'\r\n         tel += \',\'+patient.tel_office if patient.tel_office and patient.tel_office!=\'\'\r\n         tel += \',\'+patient.mobile if patient.mobile and patient.mobile!=\'\'\r\n         tel += \',\'+patient.contact_tel if patient.contact_tel and patient.contact_tel!=\'\'\r\n         tel = tel[1..-1] if tel[0]==\',\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type,:tel=>tel,:date_add=>m.date.strftime(\"%d/%m/%Y\"),:operation=>i.operation,:pre_operation=>i.pre_operation\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Appoint\',\"javascript:confirm_app(\'\\\\#{m.id}\',\'\\\\#{provider_name}\',\'\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\',\'\\\\#{procedure_name}\',\'\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\')\",:class=>\'btn btn-small btn-success\') +\" \"+link_to(\'Detail\',\"../Appointment/show?id=\\\\#{m.id}&return=../Home/index\",:class=>\'btn btn-small \')\r\n        #  c[:pending_ctrl]=link_to(\'Detail\',\"../Appointment/show?id=\\\\#{m.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Appoint\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n\r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    # waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    waiting = aps.collect{|i| i if i[:status]==\'Waiting\' }.compact\r\n \r\n    # table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    providers = {}\r\n    \r\n    for i in waiting\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end    \r\n\r\n%>   \r\n        <div class=\"row-fluid\"><div class=\"span12\">\r\n        <div class=\"tabbable tabbable-bordered\">\r\n            <ul class=\"nav nav-tabs\">\r\n            <%  index=0\r\n                providers.each_pair do |k,v| \r\n                index+=1\r\n                active = \"\"\r\n                active = \"class=active\" if index==1\r\n            %>\r\n                <li <%=active%>><a href=\"#tab_l<%=index%>\" data-toggle=\"tab\"><%= k %></a></li>\r\n            <% end %>    \r\n            </ul>\r\n            <div class=\"tab-content\">\r\n            <%  index=0\r\n                providers.each_pair do |k,v| \r\n                index+=1\r\n                active = \"\"\r\n                active = \"active\" if index==1\r\n                ga=[]\r\n                la=[]\r\n                non=[]\r\n                ga = providers[k].collect{|i| i if i[:operation]==\'GA\'}.compact\r\n                la = providers[k].collect{|i| i if i[:operation]==\'LA\'}.compact\r\n                non = providers[k].collect{|i| i if i[:operation]!=\'LA\' and i[:operation]!=\'GA\'}.compact\r\n\r\n            %>\r\n                <div class=\"tab-pane <%=active%>\" id=\"tab_l<%=index%>\">\r\n                    <%=\"GA\" if ga.size>0%>\r\n                    <%= tabular :model=>[:date_add]+table_model+[:tel,:pending_ctrl,:note],:data=>ga,:labels=>labels if ga.size>0%>\r\n                    <%=\"LA\" if la.size>0%>\r\n                    <%= tabular :model=>[:date_add]+table_model+[:tel,:pending_ctrl,:note],:data=>la,:labels=>labels if la.size>0%>\r\n                    <%= tabular :model=>[:date_add]+table_model+[:tel,:pending_ctrl,:note],:data=>non,:labels=>labels if non.size>0%>\r\n                </div>\r\n            <% end %>    \r\n            </div>\r\n        </div>\r\n        </div></div>\r\n        <br>\r\n    </div>\r\n</div><!--w-box Booking list-->\r\n\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-user\" style=\"margin-left:10px;\"></i> OR schedule\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <table class=\"table table-bordered\">\r\n        <thead><th>Day</th><th>GA</th><th>LA</th></thead>\r\n<%\r\n        days = []\r\n        days << [\'1\',\'#FFD133\',\'วันจันทร์\']\r\n        days << [\'2\',\'#EA67DE\',\'วันอังคาร\']\r\n        days << [\'3\',\'#41BD22\',\'วันพุธ\']\r\n        days << [\'4\',\'#EB7528\',\'วันพฤหัสบดี\']\r\n        days << [\'5\',\'#28BCEB\',\'วันศุกร์\']\r\n        for d in days\r\n            s = s_models.collect{|i| i if i.day==d[0]}.compact\r\n            s_ga = s.collect{|i| i if i.type==\'1\' }.compact\r\n            s_la = s.collect{|i| i if i.type==\'2\' }.compact\r\n        %>\r\n        <tr >\r\n        <td><%=d[2]%></td>\r\n        <td>\r\n        <% for ga in s_ga %> \r\n        <%=ga.doctor%> <b>Week :</b> <%=ga.week%></br>\r\n        <% end %>\r\n        </td>\r\n        <td>\r\n        <% for la in s_la %> \r\n        <%=la.doctor%> <b>Week :</b> <%=la.week%><br>\r\n        <% end %>\r\n        </td>\r\n        </tr>\r\n        <% \r\n        end\r\n%>        \r\n        \r\n        </table>\r\n        <%#=s_models.inspect%>\r\n    </div>\r\n</div><!--w-box OR schedule-->\r\n\r\n</div><!--span11-->\r\n\r\n<!--modal-->\r\n<script>\r\n	function confirm_app(id,provider,patient,procedure,note){\r\n	    //alert(\"confirm\");\r\n	   // $(\"#app_date\").html(kendo.toString($(\"#today-date\").val(), \'d\'));\r\n	    $(\"#app_id\").val(id);\r\n	    $(\"#app_date\").kendoDatePicker({\r\n            value: kendo.toString($(\"#today-date\").val(), \'d\')\r\n            \r\n	    });\r\n    	$(\"#app_time\").kendoTimePicker({\r\n    		value: $(\"#record-time\").val(),\r\n    		interval: 10\r\n    	});\r\n    	$(\"#app_date\").parent().css(\'width\',\"120px\");\r\n    	$(\"#app_time\").parent().css(\'width\',\"50px\");\r\n	    $(\"#app_provider\").html(provider)\r\n	    $(\"#app_patient\").html(patient);\r\n	    $(\"#app_procedure\").html(procedure);\r\n	    $(\"#app_note\").html(note);\r\n	    $(\"#myModal\").modal(\"toggle\");\r\n	}\r\n	\r\n	function remove_app(id,patient,date){\r\n	    $(\"#remove_id\").val(id);\r\n	    $(\"#remove_text\").html(\"ยืนยันลบการนัดหมาย \"+patient+\" \"+date);\r\n	    $(\"#removeModal\").modal(\"toggle\");\r\n	}\r\n</script>\r\n<div id=\"myModal\" class=\"modal hide fade\" tabindex=\"-1\" role=\"dialog\" aria-labelledby=\"myModalLabel\" aria-hidden=\"true\">\r\n<form id=\"app_form\" method=\"post\">\r\n<input type=\"hidden\" name=\"id\" id=\"app_id\">\r\n<div class=\"modal-hearder\">\r\n    <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-hidden=\"true\">×</button>\r\n    <h3> <i class=\"icon-calendar\" style=\"vertical-align:middle;margin-left:10px;\"></i> Confirm appointment</h3>   \r\n    <hr>\r\n</div>\r\n<div class=\"modal-body\">\r\n    <table border=\"0\" style=\"width:100%\">\r\n    <tr>\r\n        <td>Date <span style=\"float:right\">:</span></td>\r\n        <td> <input id=\"app_date\" name=\"date\" /></span></td>\r\n        <td> <span style=\"float:right\"> Time :</span></td>\r\n        <td> <input id=\"app_time\" name=\"time\" /></span></td>\r\n        <td></td>\r\n    </tr>\r\n    <tr><td>Provider <span style=\"float:right\">:</span></td><td> <span id=\"app_provider\"></span></td></tr>\r\n    <tr><td>Patient <span style=\"float:right\">:</span></td><td> <span id=\"app_patient\"></span></td></tr>\r\n    <tr><td>Procedure <span style=\"float:right\">:</span></td><td> <span id=\"app_procedure\"></td></div></tr>\r\n    <tr><td>Note <span style=\"float:right\">:</span></td><td> <span id=\"app_note\"></span></td></tr>\r\n    </table>\r\n</div>\r\n<div class=\"modal-footer\">\r\n    <button class=\"btn\" data-dismiss=\"modal\" aria-hidden=\"true\">Close</button>\r\n    <button class=\"btn btn-success\" id=\"btn_confirm\" type=\"submit\"><i class=\"icon-ok icon-white\"></i> Confirm</button>\r\n</div>\r\n</form>\r\n<script>\r\n	$(\"#btn_confirm\").click(function(){\r\n	   // $.sticky(\"<i class=\'icon-ok icon-white\'></i> Save appointment success\", {autoclose : 3000, position: \"top-center\" , type: \"st-success\"});\r\n	   // $(\"#myModal\").modal(\"hide\");\r\n	});\r\n</script>\r\n</div>\r\n\r\n<div id=\"removeModal\" class=\"modal hide fade\" tabindex=\"-1\" role=\"dialog\" aria-labelledby=\"myModalLabel\" aria-hidden=\"true\">\r\n<form id=\"remove_form\" method=\"post\">\r\n<input type=\"hidden\" name=\"remove_id\" id=\"remove_id\">\r\n<div class=\"modal-hearder\">\r\n    <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-hidden=\"true\">×</button>\r\n    <h3> <i class=\"icon-calendar\" style=\"vertical-align:middle;margin-left:10px;\"></i> Confirm Remove</h3>   \r\n    <hr>\r\n</div>\r\n<div class=\"modal-body\">\r\n    <span id=\"remove_text\"></span>\r\n</div>\r\n<div class=\"modal-footer\">\r\n    <button class=\"btn\" data-dismiss=\"modal\" aria-hidden=\"true\">Close</button>\r\n    <button class=\"btn btn-danger\" id=\"btn_confirm\" type=\"submit\"><i class=\"icon-remove icon-white\"></i> Remove</button>\r\n</div>\r\n</form>\r\n</div>\r\n<!--end modal-->\r\n\r\n\r\n',NULL,NULL,NULL,'2018-12-08 00:02:24','2018-12-08 00:02:24','',''),(3797,'create',1496,2,'<%\r\n	params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n	return_url = url(\'index\')\r\n	return_url = params[:return] if params[:return]\r\n	\r\n	\r\n	locker_model = get_model(\'locker\')\r\n	\r\n	\r\n	\r\n	date = Time.now.strftime(\"%d/%m/%Y\")\r\n	time = Time.now.strftime(\"%H:%M\")\r\n	\r\n	# date = params[:date] if params[:date]\r\n	# time = params[:time] if params[:time]\r\n	\r\n	%> \r\n<%# params[:date] %>\r\n<div class=\"row-fluid\">\r\n	<div class=\"span12\">\r\n		<div class=\"w-box\">\r\n			<div class=\"w-box-header\">\r\n				<h3>New Booking<!--<%=this.table_name.to_s.humanize%>--></h3>\r\n			</div>\r\n			<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n				<div style=\"border:0px solid\">\r\n					<div class=\"document-border\" style=\"border:0px solid\">\r\n						<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n						<%\r\n							model = get_model(this.table_name)\r\n							\r\n							\r\n							if request.post? \r\n							    m = nil\r\n							        p_date = params[:record][:date]\r\n							        \r\n							        m_date = Date.to_mongo(p_date)\r\n							        \r\n							        a_ids   = @models[:appointment].where(:date=>m_date).all.collect{|i| i.id.to_s}\r\n							        m_mod = @module_model.where(:module_id=>a_ids, :patient_id=>params[:patient_id]).first\r\n							        \r\n							        if m_mod\r\n							            flash[:notice]=\"Appointment exist.\"\r\n							            m = m_mod\r\n							        else\r\n							            flash[:notice]=\"New record has been created\"\r\n							            doc = get_document this.document_name\r\n    							        record = doc.record_create(model,params)\r\n    							        record.update_attributes :status=>\"Waiting\"\r\n    							        m = @module_model.create :patient_id=>params[:patient_id],:module_id=>record.id,:module_name=>@module_name,:date=>params[:date],:time=>params[:time],:parent_id=>params[:parent_id],:ref_number=>params[:ref_number]\r\n							        end\r\n\r\n%>\r\n<br/>\r\n<h3><%= flash[:notice] %></h3>\r\n<br/>\r\n\r\n						<script type=\"text/javascript\">\r\n							<% if  @appointment %>\r\n							//window.location = \"../Home/patient_record?id=<%=@appointment.id%>\"\r\n							window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n							\r\n							<% else %>\r\n							//window.location = \"../Home/index\"\r\n							<% end %>\r\n							\r\n							window.location = \"show?id=<%=m.id%>&return=<%=return_url%>\"\r\n							\r\n							\r\n						</script>\r\n						<%\r\n							else  \r\n							\r\n							  if params[:data]\r\n							  record = model.new params[:data] \r\n							  else\r\n							  record = model.new \r\n							  end\r\n							\r\n							  \r\n							%>\r\n						<%= form_for :record,:url=>url(\'create\') do |f| %>\r\n						<%= hidden_field_tag :return, return_url if params[:return] %>\r\n						<%\r\n							fid = 0\r\n							name = \'patient_id\'\r\n							value = params[:patient_id]\r\n							value = params[:id] if params[:id]\r\n							ref_number = @next_id\r\n							ref_number = params[:ref_number] if params[:ref_number]\r\n							\r\n							%>\r\n						<div class=\"modal hide fade\" id=\"SelectPatient\" style=\"width:720px;left:50%;margin-left:-360px\">\r\n							<div class=\"modal-header\">\r\n								<%=link_to \'Exit\',\'javascript:doClose()\', :class=>\'right\'%>\r\n								<h3>Select Patient</h3>\r\n							</div>\r\n							<div class=\"modal-body\">\r\n								<div style=\"background:#eeeeff;padding:5px;width:680px;border:1px solid #ccc\" >\r\n									<table id=\"search-panel\" style=\"width:100%\" >\r\n										<tr>\r\n											<td align=\'center\' style=\"border:0px solid\">\r\n												Patient : <%= text_field_tag \'\',\'\',:id=>\"search-\\\\#{fid}-inline\",:size=>30,:class=>tb_class ,:placeholder=>\'Search.. + Enter\',:style=>\'width:400px\' %>\r\n												<%= submit_tag \'Search\', :onclick=>\'doSearch();return false;\',:class=>bt_class %>\r\n												<%= hidden_field_tag name, value, :id=>fid ,:class=>tb_class,:placeholder=>\"Patient ID\" %>\r\n											</td>\r\n										</tr>\r\n									</table>\r\n								</div>\r\n								<div id=\"search-result\" style=\"padding:0px;display:none;width:100%\">\r\n									<br/>\r\n									Loading..\r\n								</div>\r\n							</div>\r\n						</div>\r\n						<div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n							Ref : <%= text_field_tag \'ref_number\',ref_number,:id=>\'ref-record\',:class=>tb_class,:style=>\"width:80px\" %> \r\n							<%= hidden_field_tag \'parent_id\',params[:parent_id] ,:id=>\'record-patient_id\'%> \r\n							Patient : \r\n							<a href=\"../../www/Patient/create?return=<%=CGI::escape(request.fullpath)%>\" class=\"<%=bt_class%>\">New Patient</a>\r\n							<a data-toggle=\"modal\" data-backdrop=\"static\" href=\"#SelectPatient\" class=\"btn btn-danger\" style=\"width:150px\" title=\"Select Patient\">Search Patient</a>\r\n							Date : <%= text_field_tag \'date\',date  ,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\n							Time : <%= text_field_tag \'time\',time,:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n						</div>\r\n						<div id=\'patient\'></div>\r\n						<script>\r\n						    function search_appointment(objs){\r\n						        \r\n						        list = [];\r\n						        for(var id in objs){\r\n						            i = objs[id];\r\n						            list.push(i[\'id\']);\r\n						            \r\n						        }\r\n						        \r\n						         url = \'search_appointment?plist=\'+list.join(\',\')\r\n						        	$.ajax({\r\n							        url: url,\r\n							success: function(data){\r\n							    eval(data);\r\n							}\r\n							});\r\n						    }\r\n						\r\n							$(\"#record-time\").kendoTimePicker({\r\n							value: \'<%= time %>\',\r\n							interval: 10\r\n							});\r\n							$(\"#record-date\").kendoDatePicker({\r\n							  value: \'<%= date %>\',\r\n							});\r\n							\r\n							$(\"#ref-record\").kendoAutoComplete();\r\n							$(\"#<%=\"search-\\\\#{fid}-inline\"%>\").kendoAutoComplete();\r\n							\r\n							function doSearch(){\r\n							$(\'#search-result\').css(\"display\", \"block\");\r\n							url = \'../../<%= @ehr_project.name %>/Patient/search?\'\r\n							   url += \"return=<%=CGI::escape(request.fullpath)%>\"\r\n							   url += \'&q=\'+$(\'#search-<%=fid%>-inline\').val();\r\n							$.ajax({\r\n							url: url,\r\n							success: function(data){\r\n							$(\'#search-result\').html(data);  \r\n							}\r\n							});\r\n							   \r\n							}\r\n							function doClose(){\r\n							  \r\n							$(\'#SelectPatient\').hide();\r\n							$(\".modal-backdrop\").hide(\'fade\');\r\n							\r\n							}\r\n							\r\n							\r\n							\r\n							function doSelect(value){\r\n							$(\'#<%=fid%>\').val(value);\r\n							   \r\n							   url = \'../../<%= @ehr_project.name %>/Patient/search_result?\'\r\n							url += \'&id=\'+value\r\n							   url += \"&return=\\\\#{CGI::escape(request.fullpath)}\"\r\n							   \r\n							$.ajax({\r\n							url: url,\r\n							success: function(data){\r\n							     $(\'#patient\').html(data);  \r\n							     $(\'#SelectPatient\').hide();\r\n							     $(\".modal-backdrop\").hide(\'fade\');\r\n							}\r\n							});\r\n							   \r\n							}\r\n							\r\n							\r\n							\r\n							\r\n							\r\n							$(\"#search-<%=fid%>-inline\").keydown(function(event){\r\n							if(event.keyCode == 13) {\r\n							doSearch();\r\n							 event.preventDefault();\r\n							 return false;\r\n							}else{\r\n							\r\n							$(\'#search-result\').html(\'Loading..\')\r\n							}\r\n							});\r\n							\r\n							<% if params[:patient_id] %>\r\n							$(\'#search-result\').css(\"display\", \"block\");\r\n							doSelect(\'<%=params[:patient_id]%>\')    \r\n							<% else %>\r\n							\r\n							$(\'#SelectPatient\').modal({\r\n							           show: true, \r\n							           backdrop: \'static\',\r\n							           keyboard: true\r\n							})\r\n							\r\n							     \r\n							<% end %>\r\n							\r\n							\r\n						</script>\r\n						<%\r\n							params[:form] = {}\r\n							params[:form][:model] = model\r\n							params[:form][:form] = f\r\n							params[:form][:record] = record\r\n							\r\n							\r\n							\r\n							%>\r\n						<p>\r\n							<%= this.form.html_safe %>\r\n						</p>\r\n						<br/>\r\n						<%= f.submit \"Create\".html_safe,:class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Creating..\' %> |\r\n						<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n						<% end %>\r\n						<span style=\"color:green\"><%=flash[:notice]%></span>\r\n						<% end %>\r\n					</div>\r\n				</div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>\r\n<script>\r\n	var validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n	$(\"#record-submit\").click(function() {\r\n	\r\n	if (!validator.validate()||$(\'#0\').val()==\"\") {\r\n	alert(\'Please fill all information\');\r\n	if($(\'#0\').val()==\"\")alert(\'Please select a patient\');\r\n	return false;\r\n	\r\n	}else{\r\n	    return true;\r\n	    if(confirm(\'Are you sure?\')==true){\r\n	        return true;\r\n	    }\r\n	    return false;\r\n	}\r\n	});\r\n	\r\n	$(\"#date,#start,#stop,#room\").hide();\r\n</script>',NULL,NULL,NULL,'2018-12-08 14:29:19','2018-12-08 14:29:19','create',''),(3798,'project_sort_item',1278,3,'<h2>Additional Cost sorting function</h2>\r\n\r\n<%\r\n    models = get_model\r\n    \r\n    project = models[:project].find params[:id] \r\n    \r\n    \r\n%>\r\n\r\n<%\r\n    if request.post? \r\n\r\n    3.times do |t|\r\n    s =  \"item_\\\\#{t}\".to_sym   \r\n    if params[s]\r\n      \r\n       params[s].each_with_index do |i,index| \r\n           \r\n         models[:project_item].find(i).update_attributes :sort_order=>index + 1  \r\n         \r\n       end \r\n       \r\n       \r\n    end\r\n\r\n    end\r\n\r\n%>\r\n<div class=\"alert\">Upldated..</div>\r\n<%# params.inspect %>\r\n<% end %>\r\n\r\n<%\r\n    if project\r\n    \r\n    %>\r\n    \r\n<%=form_for :protocol, :url=>\"project_sort_item?id=\\\\#{params[:id]}&update=additional-cost\", :data=>{:remote=>true} do |f|  %>\r\n<%\r\n\r\n    3.times do |t|\r\n    \r\n    label = %w{pass_through reimbursement fix_cost}[t].humanize\r\n    items = models[:project_item].where(:project_id=>project.id, :item_type=>(t+1).to_s).sort(:sort_order).all\r\n    m_products = Hash[models[:pl_product].find(items.collect{|i| i.product_id}).map{|i| [i.id,i] }]\r\n\r\n\r\n\r\n%>\r\n\r\n  <script>\r\n  $( function() {\r\n    $( \"#sortable-<%=t%>\" ).sortable();\r\n    $( \"#sortable-<%=t%>\" ).disableSelection();\r\n  } );\r\n  </script>\r\n\r\n<h3><%=label%></h3>\r\n<ul id=\"sortable-<%=t%>\">\r\n  <% for i in items \r\n    p = m_products[i.product_id] \r\n  %>\r\n  <li class=\"ui-state-default\"> <%=i.sort_order%> : <span class=\"ui-icon ui-icon-arrowthick-2-n-s\"></span><%= p.name %>  (<%=p.code%>) - <%= i.detail %> <%=hidden_field_tag \"item_\\\\#{t}[]\", i.id %> </li>\r\n  <% end %>\r\n</ul>\r\n \r\n \r\n \r\n   <% end %>\r\n\r\n<%= f.submit \"Submit\", :class=>\"btn btn-success\"%> | <%=link_to \'Back\',\"project_protocol_proxy?id=\\\\#{params[:id]}&update=panel\", :class=>\'btn\', :data=>{:disable_with=>\'Loading..\',:remote=>true} %> \r\n\r\n <% end %>\r\n\r\n\r\n <% end %>',NULL,NULL,NULL,'2018-12-10 17:33:36','2018-12-10 17:33:36','project_sort_item',''),(3799,'project_protocol_proxy',1278,3,'<%=render :inline=>this.project_protocol %>',NULL,NULL,NULL,'2018-12-10 17:57:05','2018-12-10 17:57:05','project_protocol_proxy',''),(3800,'document_name',1497,1,'\'patient_schedule\'',NULL,NULL,NULL,'20