> Create</button> |\r\n\r\n<%= link_to \'Back\', return_url %>\r\n<% end %>\r\n<span style=\"color:green\"><%=flash[:notice]%></span>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\'.admin\').hide()\r\n</script>',NULL,NULL,NULL,'2018-12-11 01:52:36','2018-12-11 01:52:36','create',''),(3802,'edit',1497,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"../Patient/show?id=<%=record.patient_id%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\'.admin\').hide();\r\n</script>',NULL,NULL,NULL,'2018-12-11 03:39:22','2018-12-11 03:39:22','edit',''),(3803,'show',1497,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    \r\n    record = get_model(\'patient_schedule\').find(params[:id])\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Back\', \"../Patient/show?id=\\\\#{record.patient_id}\" %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2018-12-11 03:44:30','2018-12-11 03:44:30','show',''),(3804,'destroy',1497,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  patient_id = @record.patient_id\r\n  @record.destroy \r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=../Patient/show?id=<%=patient_id%>\">',NULL,NULL,NULL,'2018-12-11 03:51:36','2018-12-11 03:51:36','destroy',''),(3805,'print_partial',902,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n	# id of operative note\r\n	\r\n	models  = @models\r\n	pm = @module_model.find(params[:id])\r\n	colono_id = pm.module_id\r\n	md = this.table_name.to_sym\r\n	record = models[md].find(colono_id)\r\n	@record = record\r\n	@document = get_document this.document_name\r\n	\r\n	endoscopist_1 = render_value(\'endoscopist_1\')\r\n	endoscopist_2 = render_value(\'endoscopist_2\')\r\n	\r\n	# gender\r\n	gd = {\'0\'=>\'N/A\',\'1\'=>\'Male\',\'2\'=>\'Female\'}\r\n	\r\n	if @patient \r\n	patient = @patient\r\n	date = Time.now.to_datetime\r\n	birth_date = patient.birth_date \r\n	year = month = day = \'0\'\r\n	if date and birth_date\r\n	t = date-birth_date    \r\n	year = (t/365).to_i\r\n	t%=365\r\n	month = (t/30).to_i\r\n	t%=30\r\n	day = t.to_i\r\n	end\r\n	end\r\n	\r\n	 # many lesion\r\n	a_lesion = models[:bronchoscopy_scope].find(record[:apex])\r\n	d_lesion = get_document \'bronchoscopy_scope\'\r\n	f_lesion = d_lesion.fields\r\n	fl = {}\r\n	fm = {}\r\n	\r\n	f_lesion.each do |i|\r\n	    # lab = i[:label]\r\n	    lov = i[:lov]\r\n	    name = i[:column_name]\r\n	    if lov\r\n	        fm[name] = {}\r\n	        ll = lov.split(/[\\r\\n]+/)\r\n	        ll.each do |j|\r\n	            if j.include? \'|\'\r\n	                xx = j.split(\'|\')\r\n	                fm[name][xx[0].strip.to_s] = xx[1].strip\r\n	            else\r\n	                fm[name][j.strip] = j.strip\r\n	            end\r\n	        end\r\n	    end\r\n	end\r\n	\r\n					# atts = models[:attachment].limit(5).find(record.image)\r\n					\r\n	atts = models[:attachment].where(:_id=>record[:images], :selected=>1).all\r\n	if atts.nil?\r\n	    atts = []\r\n	end				\r\n	if atts.empty?\r\n	   atts_list = record[:images][0..8]\r\n	   atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n	end\r\n	\r\n	\r\n	a_page = 1\r\n	if atts.size > 5\r\n	    a_page = 2\r\n	end\r\n	\r\n	g_att = atts.group_by{|i| i.id.to_s}\r\n	rs_att = []\r\n	record[:images].each do |i|\r\n	    if g_att.has_key? i.to_s\r\n	        rs_att << g_att[i.to_s][0]\r\n	    end\r\n	end\r\n	\r\n	%>\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n	<head>\r\n		<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n		<title>PRINT</title>\r\n	</head>\r\n	<style type=\"text/css\" media=\"all\">\r\n		html { }\r\n		#page {border:solid 1px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n		.page {border:solid 1px; width:910px; border-color:#666;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */\r\n		margin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n		#head { width:100%; height:140px;}\r\n		#logoleft { margin-left:20px; float:left;}\r\n		#logoright{ margin-right:20px; float:right;}\r\n		th              { font-weight: bolder; text-align: center }\r\n		caption         { text-align: center }\r\n		body            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size:11pt;}\r\n		.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\n		hr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\n		h1              { font-size: 2em; margin: .67em 0 }\r\n		h2              { font-size: 1.5em; margin: .83em 0 }\r\n		h3              { font-size: 1.17em; margin: 1em 0 }\r\n		p {color:#666;}\r\n		h4, p,\r\n		blockquote, ul,\r\n		form,\r\n		ol, dl          { margin: 0.5em; }\r\n		h5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\n		h6              { font-size: .67em; margin: 2.33em 0 }\r\n		h4 { font-size:14pt; color:#333; height:16px;}\r\n		blockquote      { margin-left: 40px; margin-right: 40px }\r\n		i, cite, em,\r\n		var, address    { font-style: italic }\r\n		pre, tt, code,\r\n		kbd, samp       {  font-size:14px; }\r\n		pre             {margin:0;margin-left:1em; color:#666}\r\n		big             { font-size: 1.17em }\r\n		v {color:#2561cD;}\r\n		small, sub, sup { font-size: .83em }\r\n		ol, ul, dd      { margin-left: 40px }\r\n		ol              { list-style-type: decimal }\r\n		ol ul, ul ol,\r\n		ul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n		.clear{clear:both;}\r\n		@media print {\r\n		@page         { width:960px; margin-top:0; }\r\n		blockquote, \r\n		.wrapper{ width:960px;margin-left:55px;margin-right:auto;} \r\n		footer {\r\n		/*page-break-after: always;*/\r\n		}\r\n		}\r\n		#box{\r\n\r\n		float:left;\r\n		padding:0px;\r\n		text-align:center;\r\n		border:1px solid #ccc;\r\n		-webkit-border-radius: 5px; /* Safari prototype */\r\n		-moz-border-radius: 5px; /* Gecko browsers */\r\n		border-radius: 5px; /* Everything else - limited support at the moment */    \r\n		margin:0px;\r\n		font-size:0.8em;\r\n		height:200px;\r\n		overflow:hidden;\r\n		}\r\n		.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n		#box img{\r\n		height:168px;\r\n		margin-left: 0px;\r\n		}\r\n		label{\r\n		color:#666;\r\n		}\r\n		#paper {height:1400px;}\r\n		.sidationcss\r\n		{width:160px; float:left; margin-bottom:3px;}\r\n	</style>\r\n	<body>\r\n		<div class=\"wrapper\">\r\n		<div id=\"paper\">\r\n			<div id=\"head\" class=\"well\">\r\n				<div id=\"logoleft\" style=\"width:600px; float:left\">\r\n					<img src=\'<%=@current_project.get_setting \'logo_report_path\' %>\' width=\"300\" style=\"float:left\" />\r\n					<br />\r\n					First Name : \r\n					<v><%= patient.prefix_name %> <%= patient.first_name %></v>\r\n					<br />\r\n					Last Name : \r\n					<v><%= patient.last_name %></v>\r\n					<br />\r\n					HN :&nbsp;\r\n					<v><%=patient.hn%></v>\r\n					<br />\r\n					Age :&nbsp;\r\n					<v><%= year%> Year <%=month%> Month <%= day%> Day </v>\r\n					<br />\r\n					Gender :&nbsp;\r\n					<v><%= gd[patient[:gender]] %></v>\r\n					<br />\r\n					Date :&nbsp;\r\n					<v><%=record.date_note%></v>\r\n					<br />\r\n				</div>\r\n				<div id=\"logoright\">\r\n					<p>Reported by :&nbsp;<%= @current_user.login.humanize  if @current_user %></p>\r\n					<p>Printed at :&nbsp;<%= Time.now %></p>\r\n					<p>\r\n					<center><%=image_tag \"/barcode?code=\\\\#{patient.hn}\" %></center>\r\n					</p>\r\n					<p>\r\n					<center>HN : <%=patient.hn%></center>\r\n					</p>\r\n				</div>\r\n			</div>\r\n			<div id=\"page\">\r\n				<div class=\"clear\"></div>\r\n				<table width=\"100%\">\r\n					<tr>\r\n						<td width=\'48%\'>\r\n						</td>\r\n						<td>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td valign=\'top\' cellspacing=\'10\'>\r\n							<h4 style=\"padding:0px; margin:0px; margin-left:10px\">Status : <%=render_value \'status\'%> </h4>\r\n							<br/><br/>\r\n							<p>\r\n								<span style=\"float:left; \"> </span>\r\n								<span style=\"float:left;display:block-inline;\">\r\n							<table width=\"100%\" style=\"margin-left:10px\" >\r\n							<tr>\r\n							<td width=\"122\">Procedure</td>\r\n							<td width=\"271\"><v>Bronchoscopy</v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>\r\n							Endoscopist</td>\r\n							<td><v><%=endoscopist_1%></v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>Fellow</td>\r\n							<td><v><%=endoscopist_2%></v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>Diagnosis\r\n							</td>\r\n							<td><v><%=render_value \'provisional_diagnosis\'%></v>\r\n							</td>\r\n							</tr>\r\n							<tr>\r\n							<td>Definite Diagnosis </td>\r\n							<td><v><%=render_value \'definite_diagnosis\'%></v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>Pathology</td>\r\n							<td><v>Histopathology :<%=render_value \'histopathology1\'%></v><br /><v>Cytology :<%=render_value \'cytology\'%></v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>Microbiology</td>\r\n							<td><v><%=render_value \'culture\'%> / <%=render_value \'culture_other\'%></v></td>\r\n							</tr>\r\n							<tr>\r\n							<td>Operation</td>\r\n							<td><v><%=render_value \'operative_time_start_at\'%> - <%=render_value \'operative_time_stop_at\'%></v> </td>\r\n							</tr>\r\n							<tr>\r\n							<td>Sedation</td>\r\n							<td> <% if record[\'midazolam\']==\'true\'%><v>Midazolam : <%=render_value \'midazolam_mg\'%></v><br /><% end%>\r\n							<% if record[\'fentanyl\']==\'true\'%><v>Fentanyl :<%=render_value \'fentanyl_mcg\'%></v><br /><% end%>\r\n							<% if record[\'propofol\']==\'true\'%><v>Propofol :<%=render_value \'propofol_mg\'%></v><br /><% end%>\r\n							<% if record[\'other\']==\'true\'%><v>Ohter :<%=render_value \'other_note\'%></v><% end%></td>\r\n							</tr>		\r\n							</table>	\r\n							</span>\r\n							</p>\r\n							<div class=\'clear\'></div>\r\n						</td>\r\n						<td valign=\"top\">\r\n							<div id=\'sign\' style=\'height:10px\'>\r\n								<h4>Sign : </h4>\r\n								<div id=\'provider-name\' style=\'margin-top:10px;float:right\'>\r\n									<%= render_value(\'endoscopist_1\') %> / <%= render_value(\'endoscopist_2\') %>\r\n								</div>\r\n							</div>\r\n							<hr/>\r\n							<br/>\r\n							<h4 style=\"padding:0px; margin:0px;margin-left:10px\">Findings</h4>\r\n							<br />\r\n							<div id=\'finding\'>\r\n								<br/>\r\n								<%\r\n									def get_render_value(field)\r\n									    f = field.to_sym\r\n									    if @record[f].nil? or @record[f]==\'\'\r\n									        return \"-\"\r\n									    else\r\n									        return render_value(f.to_s)\r\n									    end\r\n									end\r\n									\r\n									def get_value(field)\r\n									    f = field.to_sym\r\n									    if @record[f].nil? or @record[f]==\'\'\r\n									        return \'-\'\r\n									    else\r\n									        return @record[f]\r\n									    end\r\n									end\r\n									\r\n									def is_exist(field)\r\n									    f = field.to_sym\r\n									    if @record[f].nil? or @record[f]==\'\'\r\n									        return false\r\n									    else\r\n									        return true\r\n									    end\r\n									end\r\n									\r\n									# anatomy fields\r\n									af = get_render_value(:anatomy).split(\',\').collect{|i| i.downcase.strip.gsub \' \', \'_\'} \r\n									# field map\r\n									fm = {}\r\n									@document.fields.each do |i|\r\n									    if i[:lov_type] == \'pair\'\r\n									        tmp = {}\r\n									        tmp[:name] = i[:name]\r\n									        tmp[:list] = []\r\n									        tmp[:pair] = {}\r\n									        lov = i[:lov].to_s.split(\'\\r\\n\')\r\n									        lov.each do |j|\r\n									            x = j.split(\'|\')\r\n									            tmp[:pair][x[0].strip] = x[1].strip\r\n									            tmp[:list] << x[1].strip\r\n									        end\r\n									        fm[i[:column_name].to_sym] = tmp\r\n									    end\r\n									end\r\n									\r\n									tmp_rec = @record\r\n									tmp_doc = @document\r\n									\r\n									@document = get_document \'bronchoscopy_scope\'\r\n									%>\r\n								<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"2\" style=\"-moz-border-radius: 5px;\r\n									border-radius: 5px; border-color:#999\">\r\n									<%\r\n										# section to render report\r\n										fm[:anatomy][:list][0..5].each do |i|\r\n										    # key symbol\r\n										    ks = i.downcase.strip.gsub(\' \', \'_\').to_sym\r\n										    # has sub element ?\r\n										    hs = fm.has_key? ks\r\n										    # selected item ?\r\n										    si = af.include? ks.to_s\r\n										    \r\n										    rs = \"N/A\"\r\n										    if si and !hs\r\n										        @record = get_model[:bronchoscopy_scope].find(tmp_rec[ks])\r\n										        dx_val = \'N/A\'\r\n										        in_val = \'N/A\'\r\n										        sc_val = \'\'\r\n										        \r\n										        if !@record.nil?\r\n										            dx_val = get_render_value(:diagnosis)\r\n										            in_val = get_render_value(:intervention)\r\n										            \r\n										            if is_exist(:scope_note)\r\n										                sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										            end\r\n										        end\r\n										        rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										        \r\n										        i = \"<b>\\\\#{i}</b>\".html_safe\r\n										    \r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										elsif si and hs\r\n										    i = \"<b>\\\\#{i}</b>\".html_safe\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										rs = \'\'\r\n										kk = fm[ks]\r\n										\r\n										ls = tmp_rec[ks].split(\'|\')\r\n										ls.each do |j|\r\n										    # sub element name\r\n										    em = kk[:pair][j]\r\n										    sn = \"<i><b>\\\\#{em}</b></i>\".html_safe\r\n										    # element symbol\r\n										    es = em.downcase.strip.gsub(\' \', \'_\')\r\n										    \r\n										    @record = get_model[:bronchoscopy_scope].find(tmp_rec[\"\\\\#{ks}_\\\\#{es}\".to_sym])\r\n										    dx_val = \'N/A\'\r\n										    in_val = \'N/A\'\r\n										    sc_val = \'\'\r\n										    \r\n										    if !@record.nil?\r\n										        dx_val = get_render_value(:diagnosis)\r\n										        in_val = get_render_value(:intervention)\r\n										        \r\n										        if is_exist(:scope_note)\r\n										            sc_val = \"<br/>Note : <v>\\\\#{get_value(:scope_note)}</v>\"\r\n										        end\r\n										    end\r\n										    rs = \"Diagnosis : <v>\\\\#{dx_val}</v><br/>Intervention : <v>\\\\#{in_val}</v>\\\\#{sc_val}\".html_safe\r\n										    \r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											&nbsp;&nbsp;<%= sn %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<% \r\n										end\r\n										else\r\n										%>\r\n									<tr>\r\n										<td width=\'35%\' valign=\'top\'>\r\n											<%= i %>\r\n										</td>\r\n										<td>\r\n											<%= rs %>\r\n										</td>\r\n									</tr>\r\n									<%\r\n										end\r\n										end \r\n										#