==\'rrts#aki\'\r\n            created_at  = j.created_at\r\n        end\r\n        \r\n        if j.module_name==\'rrts#appointment\'\r\n        \r\n            appoint = true\r\n        end\r\n        \r\n        end\r\n        \r\n        \r\n        # unless appoint\r\n            \r\n        #     app = models[:appointment].create :created_at=>created_at, :updated_at=>created_at,:date=>created_at\r\n            \r\n        #     pm =  module_model.create :module_name=>\'rrts#appointment\', :patient_id=>p.id, :module_id=>app.id\r\n        \r\n        #     for j in lm\r\n            \r\n        #         j.update_attributes :parent_id=>pm.id\r\n                \r\n        #     end\r\n        \r\n        # end\r\n        \r\n        \r\n    if p \r\n%><%= i%> :  \r\n<%=p.patient_order%><br/>\r\n<%# pm.inspect %><br/>\r\n<%= lm.collect{|j| \"\\\\#{j.module_name} \\\\#{j.id} \\\\#{j.parent_id}\" }.join(\"<br/>\").html_safe %>\r\n<hr/>\r\n\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n<%= models[:appointment].first.inspect %>',NULL,NULL,NULL,'2018-12-16 14:46:06','2018-12-16 14:46:06','recovery_patient',''),(3807,'usage_report',522,2,'<%\r\n\r\n    # I18n.locale = \'th\'\r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n%>\r\n\r\n<h1>Product Usage Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # params_date = select_date\r\n    # select_date = Date.to_mongo(select_date)\r\n    \r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    \r\n    \r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n    categories = models[:product_category].all\r\n    category = nil\r\n    \r\n    \r\n    category = params[:report][:product_category] if params[:report] and params[:report][:product_category]\r\n    \r\n    \r\n    \r\n    products = models[:product].all\r\n    \r\n    \r\n    product = nil\r\n    product =  params[:report][:product] if params[:report] and params[:report][:product]\r\n    \r\n   \r\n   \r\n%>\r\n\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date , :order=>[:day,:month,:year]%> <br/>\r\n\r\nProduct type : <%= f.select :product_category, options_for_select(categories.collect{|i| [i.name,i.id] }, category) %><br/>\r\n\r\nProduct : <%= f.select :product, options_for_select(products.collect{|i| [i.name,i.id] }, product), :include_blank=>true %>\r\n\r\n\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    billings = models[:billing].collection.find({:created_at=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}}).to_a\r\n    products = models[:product].collection.find().to_a\r\n    \r\n    mproducts = Hash[products.collect { |i| [i[\'_id\'], i] } ]\r\n    \r\n    items = []\r\n    for i in billings\r\n        items += i[\'items\']\r\n    end\r\n    \r\n    items = models[:billing_item].collection.find({\'_id\'=>{\'$in\'=>items}}).to_a\r\n    mitems = Hash[items.collect {|i| [i[\'_id\'],i]}]\r\n    mk1 = {}\r\n    mk2 = {}\r\n    pk1 = {}\r\n    psum = {}\r\n    \r\n    \r\n    \r\n    for i in billings\r\n    \r\n        date = i[\'created_at\']\r\n        k2 = date.strftime(\"%Y-%m-%d\")\r\n        k1 = date.strftime(\"%Y-%m\")\r\n        \r\n        for j in i[\'items\']\r\n        \r\n            k = mitems[j]\r\n            p = mproducts[k[\'product_id\']]\r\n            pid = p[\'_id\']\r\n            \r\n            if (p and p[\'category_id\'].to_s == category and product==nil) or (product and pid.to_s==product.to_s)\r\n              \r\n              mk1[k1] = {} unless mk1[k1] \r\n              mk1[k1][p[\'_id\']] = 0 unless mk1[k1][p[\'_id\']]\r\n              mk1[k1][p[\'_id\']] += 1\r\n              \r\n              mk2[k2] = {} unless mk2[k2] \r\n              mk2[k2][p[\'_id\']] = 0 unless mk2[k2][p[\'_id\']]\r\n              mk2[k2][p[\'_id\']] += 1\r\n              \r\n              pk1[pid] = {} unless pk1[pid]\r\n              pk1[pid][k1] = 0 unless pk1[pid][k1] \r\n              pk1[pid][k1] += 1\r\n              \r\n              psum[pid] = 0 unless psum[pid] \r\n              psum[pid] += 1\r\n              \r\n              \r\n              \r\n            end\r\n            \r\n\r\n        end\r\n    \r\n    end\r\n    \r\n    k1s = mk1.keys.sort\r\n \r\n %>\r\nResult from <%= start_date.strftime(\"%d-%m-%Y\") %> to <%= stop_date.strftime(\"%d-%m-%Y\") %><br/>\r\n\r\n<i><%= billings.size %> Records </i><br/>\r\n \r\n\r\n \r\n <h3>MK1</h3>\r\n \r\n <table class=\"table\">\r\n     \r\n     <thead>\r\n         <tr>\r\n             <th>Products</th>\r\n             <% for k1 in k1s %>\r\n            <th>\r\n                <%= k1 %>\r\n            </th>\r\n            <% end %>\r\n            <th>Total</th>\r\n         </tr>\r\n     </thead>\r\n     <tbody>\r\n        <% \r\n        \r\n            psort = pk1.keys.sort{|a,b| mproducts[a][\'name\']<=>mproducts[b][\'name\'] } \r\n            \r\n            psort = pk1.keys.sort{|a,b| psum[b]<=>psum[a] } \r\n\r\n        \r\n            for pid in psort\r\n            p  =   mproducts[pid]\r\n        %>\r\n         <tr>\r\n            <th>\r\n                <%=p[\'name\']%>\r\n            </th> \r\n            <% \r\n                sum = 0 \r\n            for k1 in k1s\r\n                \r\n                sum+=pk1[pid][k1] if pk1[pid][k1] \r\n                \r\n            %>\r\n            <td>\r\n                <%= pk1[pid][k1] %>\r\n            </td>\r\n            \r\n            <% end %>\r\n            \r\n            <td>\r\n                <%= sum %>\r\n            </td>\r\n         </tr>\r\n         <% end %>\r\n     \r\n         \r\n     </tbody>\r\n     \r\n </table>\r\n \r\n \r\n \r\n \r\n \r\n \r\n \r\n <% end %>',NULL,NULL,NULL,'2018-12-16 16:50:01','2018-12-16 16:50:01','usage_report',''),(3808,'index',522,2,'<center><h1>Please Select Report</h1></center>',NULL,NULL,NULL,'2018-12-16 16:58:47','2018-12-16 16:58:47','index',''),(3809,'remark',1278,3,'<%\r\n    models = get_model\r\n    project = models[:project].find(params[:id])\r\n    \r\n    project.update_attributes :remark1=>params[:remark1_editor]\r\n    \r\n%>\r\n<%= project.remark1.html_safe%>\r\n<script>\r\n    $(\'#remark-editor\').hide();\r\n    $(\'.remark-panel\').show();\r\n    \r\n</script>',NULL,NULL,NULL,'2018-12-18 04:22:44','2018-12-18 04:22:44','remark',''),(3810,'adv_export',378,2,'\r\n<%\r\n\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n\r\n from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n   \r\n%>\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n\r\n<%=form_for \'report\' do |f| %>\r\n<h1> Dialyzer Report </h1>\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date , :order=>[:day,:month,:year]%>\r\n\r\n\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n<%\r\n\r\n    if request.post? \r\n    \r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n  @document = get_document(this.document_name)\r\n\r\n  doc = @document\r\n   %>\r\n   <%= link_to \'Download\', \"#\", :id=>\'btnExport\', :class=>\'btn\' %>\r\n   <%\r\n   \r\n  #data = get_model(this.document_name).all :sort=>\'created_at desc\', :limit=>2000, :offset=>0\r\n  \r\n  data = get_model(this.document_name).where(:crrt_date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}).all\r\n  \r\n   lfields = @document.fields\r\n   fields = lfields.collect{|i| [i.column_name,i.name,i] unless Document.visual_types.index(i.field_type) }.compact!\r\n   fields << \'created_at\'\r\n   fields << \'updated_at\'\r\n   \r\n   models = get_model\r\n   many_list = {}\r\n   \r\n   dxmax = 0 \r\n   \r\n   for f in fields\r\n    field = f[2]\r\n       \r\n    if f.size ==3 and field.field_type==\'relation_many\'\r\n       p = eval(\"{\\\\#{field.params}}\")[:relation][:document]\r\n       many_list[field.column_name] =  {:name=>field.column_name,:doc=>p, :model=>models[p.to_sym],:records=>[] }\r\n        \r\n    end\r\n   \r\n   \r\n   end\r\n   mm = @module_model.where(:module_id=>{\'$in\'=>data.collect{|i| i.id }}).all\r\n   \r\n   mmodule = Hash[mm.collect{|i|  [i.module_id,i] }]\r\n   mapp = Hash[@module_model.where(:id=>{\'$in\'=>mm.collect{|i| i.parent_id }}).all.collect{|i|  [i.id,i.module_id] }]\r\n  \r\n   pmap = {}\r\n   map = {}\r\n   results = {}\r\n   dlist = []\r\n   pids = []\r\n   data.each do |i|\r\n       m = mmodule[i.id]\r\n       app_id = mapp[m.parent_id]\r\n       pid = \"\\\\#{m.patient_id}-\\\\#{app_id}\"\r\n       pids << m.patient_id\r\n       map[pid] = [] unless map[pid]\r\n       map[pid] << {:date=>i.crrt_date,:module_id=>m.id,:items=>i.dialyzermm,:dialyzer=>i.dialyzer}\r\n       \r\n       dlist += i.dialyzermm\r\n   end\r\n       \r\n    mpatient = Hash[@patient_model.find(pids).collect{|i| [i.id.to_s,i]}]\r\n\r\n       \r\n    mdilist = Hash[models[:dialyzer].find(dlist).collect{|i| [i.id,i]}]\r\n    \r\n    map.each_pair do |k,v|\r\n  \r\n      \r\n       if v.size > 0 \r\n       for i in v\r\n            l = []\r\n            for j in i[:items]\r\n                d = mdilist[j]\r\n                l << d\r\n            end\r\n            i[:list] = [] unless i[:list]\r\n            i[:list] += l\r\n       end\r\n   else\r\n\r\n   end\r\n    end\r\n    \r\n    \r\n    map.each_pair do |k,v|\r\n       \r\n       \r\n       l = []\r\n       x = []  # continuous crrt \r\n       \r\n       last_date = nil\r\n       \r\n       for i in v.sort{|a,b| a[:date]<=>b[:date]}  # by date\r\n     \r\n        date = i[:date]\r\n       \r\n        last_date = date unless last_date\r\n        \r\n        if last_date\r\n            period = (date.to_datetime - last_date.to_datetime).to_i\r\n      \r\n      \r\n        \r\n        if period>1\r\n           \r\n            if x.size>0\r\n                    \r\n                l << x \r\n                x = [] \r\n            end\r\n           \r\n          \r\n            \r\n        end\r\n        \r\n        \r\n        \r\n        last_date = date\r\n        end\r\n        \r\n        no = 1\r\n       \r\n        for j in i[:list]  # by record\r\n            \r\n            \r\n            #dialyzer_number\r\n            #filtration_life_time\r\n            #dialyzer_note\r\n            \r\n          \r\n            \r\n            if no != j.dialyzer_number\r\n                \r\n                if x.size>0\r\n                    \r\n                    l << x \r\n                    x = []\r\n                \r\n                end\r\n                no = j.dialyzer_number\r\n                \r\n            else\r\n            \r\n                x << {:date=>i[:date], :dialyzer=>i[:dialyzer], :module_id=>i[:module_id], :item=>j}\r\n             \r\n            end\r\n\r\n        end\r\n          \r\n          \r\n               \r\n        end\r\n          if x.size>0\r\n                    \r\n                    l << x \r\n                \r\n                end\r\n                \r\n         idx=1\r\n        rx=[]\r\n        note = nil    \r\n        for i in l \r\n            hour = 0   \r\n        dx = []\r\n        \r\n        \r\n        for zi in i    \r\n            z = zi[:item]\r\n            hour += z.filtration_life_time.to_i\r\n           \r\n            note = z.dialyzer_note\r\n            \r\n        end\r\n         dxmax = i.size if i.size > dxmax\r\n\r\n\r\n        rx << {:items=>i,:dialyzer=> i[0][:dialyzer],  :hour=>hour,:idx=>idx, :final=>note, :date=>i[0][:date] }\r\n        idx+=1\r\n      \r\n        end\r\n        \r\n        \r\n        \r\n        \r\n        results[k] = rx\r\n        \r\n    end\r\n    \r\n       idx=0\r\n   \r\n%>\r\n<div id=\"data\">\r\n<table class=\"table\">\r\n<thead>\r\n    <th>No.</th>\r\n    <th>Patient</th>\r\n    <th>Gender</th>\r\n    <th>Age(ปี)</th>\r\n    <th>Dialyzer</th>\r\n    <th>Dialyzer Idx</th>\r\n    <th>Hour</th>\r\n    <th>Reason</th>\r\n    <% dxmax.times do |t| %>\r\n    <th>CRRT</th>\r\n    <% end %>\r\n</thead>\r\n\r\n\r\n\r\n    <tbody>\r\n    <% map.each_pair do |k,v| \r\n        rx = results[k]\r\n        \r\n        \r\n        for i in rx \r\n        \r\n        \r\n        pid,app_id = k.split(\"-\")\r\n    \r\n        p = mpatient[pid.to_s]\r\n    %>\r\n\r\n<tr>\r\n    <td>\r\n        <%= idx+1 %>.\r\n    </td>\r\n\r\n    <td>\r\n        <%= link_to \"\\\\#{p.prefix_name} \\\\#{p.first_name} \\\\#{p.last_name}\", \"../Home/patient_record?id=\\\\#{app_id}\" if p%>\r\n    </td>\r\n    \r\n    \r\n    <td>\r\n    <% \r\n\r\n    gender = \'-\'\r\n    gender = \'M\' if p.gender==\'1\'\r\n    gender = \'F\' if p.gender==\'0\'\r\n\r\n        \r\n    %>\r\n        <%= link_to \"\\\\#{gender}\" , \"../Home/patient_record?id=\\\\#{app_id}\" if p%>\r\n    </td>\r\n    \r\n        \r\n    <td>\r\n    <% \r\n    age = \'-\'\r\n    age = ((i[:date] - p.birth_date)/365).to_i\r\n        \r\n    %>\r\n        <%= link_to \"\\\\#{age}\" , \"../Home/patient_record?id=\\\\#{app_id}\" if p%>\r\n    </td>\r\n    \r\n    <td>\r\n        <%=i[:dialyzer]%>\r\n    </td>\r\n\r\n    \r\n    <td>\r\n        <%= i[:idx]%>\r\n    </td>\r\n        \r\n    <td>\r\n        <%=i[:hour] %>\r\n    </td>\r\n    \r\n    <td>\r\n        <%= i[:final]%>\r\n    </td>\r\n    \r\n    <% for z in i[:items] %>\r\n    <td>\r\n    <%# i[:items].collect{|z| link_to(\"\\\\#{z[:date]} \",\"show?id=\\\\#{z[:module_id]}\")+\"(\\\\#{z[:item].filtration_life_time}\\\\#{\' : \'+z[:item].dialyzer_note if z[:item].dialyzer_note and z[:item].dialyzer_note.size>0})\" }.join(\", \").html_safe  %>\r\n    <%=  link_to(\"\\\\#{z[:date]}\",\"show?id=\\\\#{z[:module_id]}\")  + \" (\\\\#{z[:item].filtration_life_time}\\\\#{\' : \'+z[:item].dialyzer_note if z[:item].dialyzer_note and z[:item].dialyzer_note.size>0})\".html_safe  %>\r\n    </td>\r\n    <% end %>\r\n    \r\n</tr>  <%\r\n\r\n    idx+=1\r\nend %>\r\n  <% end %>\r\n    \r\n    </tbody>\r\n</table>\r\n<!--\r\n<table class=\"table\">\r\n    <tbody>\r\n    <% map.each_pair do |k,v| %>\r\n        <tr>\r\n        <th><%=link_to k, \"#\" %></th>\r\n            \r\n            <%\r\n            for i in v.sort{|a,b| a[:date]<=>b[:date]}\r\n                if i[:list]\r\n            for j in i[:list]\r\n            %>\r\n            \r\n            <td>\r\n                <%=link_to i[:date].strftime(\"%d-%m-%Y\"),\"show?id=\\\\#{i[:module_id]}\" %><br/> <%= j.dialyzer_number %>,   <%= j.filtration_life_time %>, <%=j.dialyzer_note%>\r\n            </td>\r\n              <% end %>\r\n             <% end %>\r\n             <td>|</td>\r\n            <% end %>\r\n            \r\n        </tr>\r\n    \r\n    <% end %>\r\n    \r\n    </tbody>\r\n</table>\r\n-->\r\n</div>\r\n<script>\r\n    $(\"#btnExport\").click(function(e) {\r\n    window.open(\'data:application/vnd.ms-excel,\' + $(\'#data\').html());\r\n    e.preventDefault();\r\n});\r\n</script>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2018-12-19 16:36:10','2018-12-19 16:36:10','adv_export',''),(3811,'document_name',1498,1,'\'hip1\'',NULL,NULL,NULL,'2018-12-22 16:21:58','2018-12-22 16:21:58',NULL,NULL),(3812,'document_name',1499,1,'\'provider\'',NULL,NULL,NULL,'2018-12-22 16:24:05','2018-12-22 16:24:05',NULL,NULL),(3813,'document_name',1500,1,'\'hospital\'',NULL,NULL,NULL,'2018-12-22 16:24:39','2018-12-22 16:24:39',NULL,NULL),(3814,'document_name',1501,1,'\'record_template\'',NULL,NULL,NULL,'2018-12-22 16:29:17','2018-12-22 16:29:17',NULL,NULL),(3815,'document_name',1502,1,'\'implant_company\'',NULL,NULL,NULL,'2018-12-22 16:39:26','2018-12-22 16:39:26',NULL,NULL),(3816,'document_name',1503,1,'\'implant_component\'',NULL,NULL,NULL,'2018-12-22 16:40:12','2018-12-22 16:40:12',NULL,NULL),(