s_adduction\', \'hhs_external_rotation\', \'hhs_internal_rotation\'];\r\nfunction hhs_score_update() {\r\n    txt = $(this).val();\r\n    num = isNaN(parseInt(txt)) ? 0 : parseInt(txt);\r\n    console.log(\"hip = \" + $(this).val());\r\n    \r\n    sum = 0;\r\n    // simple sum\r\n    for (var i in hhs_select) {\r\n        f = \"#data-\" + hhs_select[i];\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n    for (var i in hhs_radio) {\r\n        f = \"input[id^=\'update_\" + hhs_radio[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n    // Absence of Deformity (All yes = 4; Less than 4 =0)\r\n    abs = 0;\r\n    for (var i in hhs_absence_group) {\r\n        f = \"input[id^=\'update_\" + hhs_absence_group[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        abs += n;\r\n    }\r\n    if (abs == 4) {\r\n        sum += abs;\r\n    }\r\n    // Range of Motion (*indicate normal)\r\n    // Range of Motion Scale \r\n    // 211-300 (5)\r\n    // 161-210 (4)\r\n    // 101-160 (3)\r\n    // 61-100 (2)\r\n    // 31-60 (1)\r\n    // 0-30 (0)\r\n    mot = 0;\r\n    sum_m = 0;\r\n    for (var i in hhs_motion_group) {\r\n        f = \"#data-\" + hhs_motion_group[i];\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        if (f.indexOf(\'flexion\') != -1) {\r\n            if (n > 140) {\r\n                n = 140;\r\n            }\r\n        } else {\r\n            if (n > 40) {\r\n                n = 40;\r\n            }\r\n        }\r\n        sum_m += n;\r\n    } \r\n		if (sum_m >= 211 && sum_m <= 300) {\r\n            mot = 5;\r\n        } else if (sum_m >= 161 && sum_m <= 210) {\r\n            mot = 4;\r\n        } else if (sum_m >= 101 && sum_m <= 160) {\r\n            mot = 3;\r\n        } else if (sum_m >= 61 && sum_m <= 100) {\r\n            mot = 2;\r\n        } else if (sum_m >= 31 && sum_m <= 60) {\r\n            mot = 1;\r\n        } else {\r\n            mot = 0;\r\n        }\r\n    \r\n    sum += mot;\r\n    \r\n    console.log(\"[HHS] SUMATION = \" + sum);\r\n    \r\n    $(\"#data-hhs_total_range_of_motion\").val(sum_m);\r\n    $(\"#data-hhs_hip_score\").val(sum);\r\n}\r\n\r\n$(document).ready(function(){\r\n    // ----\r\n    // harris_hip_score\r\n    // ----\r\n    kn_score = 0;\r\n    tmp_score = $(\"#data-hhs_hip_score\").val();\r\n    if (tmp_score != \'\') {\r\n        kn_score = tmp_score;\r\n    } else {\r\n        $(\"#data-hhs_hip_score\").val(\"0\");\r\n    }\r\n    tmp_score = $(\"#data-hhs_total_range_of_motion\").val();\r\n    if (tmp_score != \'\') {\r\n        kn_score = tmp_score;\r\n    } else {\r\n        $(\"#data-hhs_total_range_of_motion\").val(\"0\");\r\n    }\r\n    \r\n    for (var i in hhs_select) {\r\n        f = \"#data-\" + hhs_select[i];\r\n        $(f).change(hhs_score_update);\r\n    }\r\n    for (var i in hhs_radio) {\r\n        f = \"input[id^=\'update_\" + hhs_radio[i] + \"\']\";\r\n        $(f).change(hhs_score_update);\r\n    }\r\n    for (var i in hhs_absence_group) {\r\n        f = \"input[id^=\'update_\" + hhs_absence_group[i] + \"\']\";\r\n        $(f).change(hhs_score_update);\r\n    }\r\n    for (var i in hhs_motion_group) {\r\n        f = \"#data-\" + hhs_motion_group[i];\r\n        $(f).change(hhs_score_update);\r\n    }\r\n});\r\n</script>',NULL,NULL,NULL,'2018-12-22 17:31:55','2018-12-22 17:31:55','',''),(3830,'form',1481,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<!-- HIP Generate Script -->\r\n<script>\r\n// generate script\r\n<%\r\nsumgroup = this.sumgroup\r\nif sumgroup != \'No service\'\r\n\r\n    doc_ready = \'\\n\'\r\n    sumgroup.each do |k, v|\r\n        ks = \'\' # select\r\n        kr = \'\' # radio\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \"// \" + k.to_s + \"\\n\"\r\n        doc_ready += \"// ---\\n\"\r\n        doc_ready += \'tmp_score = $(\"#data-\' + v[:total].to_s + \'\").val();\\n\'\r\n        doc_ready += \"if (tmp_score == \'\') { \\n  $(\'#data-\\\\#{v[:total].to_s}\').val(\'0\');\\n}\\n\"\r\n%>\r\n\r\n// ---\r\n// Generate for function <%= k %>\r\n// --- zam ---\r\n<%\r\n        if v[:select]\r\n            ks = k.to_s + \"_select\"\r\n            doc_ready += \"for (var i in \\\\#{ks}) {\\n\"\r\n            doc_ready += \"  f = \'#data-\' + \\\\#{ks}[i];\\n\"\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n%>\r\nvar <%= ks %> = [\"<%= v[:select].join(\'\",\"\').html_safe %>\"];\r\n<%\r\n        end\r\n        if v[:radio]\r\n            kr = k.to_s + \"_radio\"\r\n            doc_ready += \"for (var i in \\\\#{kr}) {\\n\"\r\n            doc_ready += \'  f = \"input[id^=\' + \"\'update_\" + \'\" + \' + \"\\\\#{kr}[i] + \" + \'\"\' + \"\']\" + \'\";\\n\'\r\n            doc_ready += \"  $(f).change(\\\\#{k.to_s});\\n}\\n\"\r\n            \r\n%>\r\nvar <%= kr %> = [\"<%= v[:radio].join(\'\",\"\').html_safe %>\"];\r\n<%\r\n        end\r\n%>\r\nfunction <%= k %>() {\r\n    sum = 0;\r\n<% if v[:select] %>\r\n    for (var i in <%= ks %>) {\r\n        f = \"#data-\" + <%= ks %>[i];\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n<% if v[:radio] %>\r\n    for (var i in <%= kr %>) {\r\n        f = \"input[id^=\'update_\" + <%= kr %>[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n<% end %>\r\n\r\n    console.log(\"<%= k %> := \" + sum);\r\n\r\n    $(\"#data-<%= v[:total] %>\").val(sum);\r\n    $(\"#data-<%= v[:total] %>\").trigger(\'change\');\r\n}\r\n<%\r\nend\r\nend # end generate script\r\n%>\r\n$(document).ready(function() {\r\n    <%= doc_ready.html_safe %> \r\n})\r\n</script>\r\n\r\n<%\r\n    hoos = {\"0\"=>\"100.000\",\r\n\"1\"=>\"92.340\",\r\n\"2\"=>\"85.257\",\r\n\"3\"=>\"80.550\",\r\n\"4\"=>\"76.776\",\r\n\"5\"=>\"73.472\",\r\n\"6\"=>\"70.426\",\r\n\"7\"=>\"67.516\",\r\n\"8\"=>\"64.664\",\r\n\"9\"=>\"61.815\",\r\n\"10\"=>\"58.930\",\r\n\"11\"=>\"55.985\",\r\n\"12\"=>\"52.965\",\r\n\"13\"=>\"49.858\",\r\n\"14\"=>\"46.652\",\r\n\"15\"=>\"43.335\",\r\n\"16\"=>\"39.902\",\r\n\"17\"=>\"36.363\",\r\n\"18\"=>\"32.735\",\r\n\"19\"=>\"29.009\",\r\n\"20\"=>\"25.103\",\r\n\"21\"=>\"20.805\",\r\n\"22\"=>\"15.633\",\r\n\"23\"=>\"8.104\",\r\n\"24\"=>\"0.000\"}\r\n%>\r\n<script>\r\n    var hoos = <%= hoos.to_json.html_safe %>;\r\n    \r\n    function interval_score_update() {\r\n        v = $(this).val();\r\n        $(\'#data-hoos_interval_score\').val(hoos[v]);\r\n    }\r\n    \r\n    $(document).ready(function() {\r\n        $(\'#data-hoos_total_hoos_score\').change(interval_score_update);\r\n    })\r\n</script>',NULL,NULL,NULL,'2018-12-22 17:36:00','2018-12-22 17:36:00','',''),(3831,'sumgroup',1481,1,'{\r\n	:hoos_update => {\r\n	    :radio => [:hoos_choice_1, :hoos_choice_2, :hoos_choice_3, :hoos_choice_4, :hoos_choice_5, :hoos_choice_6],\r\n	    :total => :hoos_total_hoos_score\r\n	}\r\n}',NULL,NULL,NULL,'2018-12-22 17:42:41','2018-12-22 17:42:41','sumgroup',''),(3832,'sumgroup',1480,1,'{\r\n	:koos_update => {\r\n	    :radio => [:koos_choice_1, :koos_choice_2, :koos_choice_3, :koos_choice_4, :koos_choice_5, :koos_choice_6, :koos_choice_7],\r\n	    :total => :koos_total_koos_score\r\n	}\r\n}',NULL,NULL,NULL,'2018-12-22 17:44:33','2018-12-22 17:44:33','sumgroup',''),(3833,'form',1480,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= 