r\n<% end %>\r\n\r\n    console.log(\"<%= k %> := \" + sum);\r\n\r\n    $(\"#data-<%= v[:total] %>\").val(sum);\r\n    $(\"#data-<%= v[:total] %>\").trigger(\'change\');\r\n}\r\n<%\r\nend\r\nend # end generate script\r\n%>\r\n$(document).ready(function() {\r\n    <%= doc_ready.html_safe %> \r\n})\r\n</script>\r\n\r\n<!-- koos -->\r\n<%\r\n    koos = {\"0\"=>\"100.000\",\r\n\"1\"=>\"91.975\",\r\n\"2\"=>\"84.600\",\r\n\"3\"=>\"79.914\",\r\n\"4\"=>\"76.332\",\r\n\"5\"=>\"73.342\",\r\n\"6\"=>\"70.704\",\r\n\"7\"=>\"68.284\",\r\n\"8\"=>\"65.994\",\r\n\"9\"=>\"63.776\",\r\n\"10\"=>\"61.583\",\r\n\"11\"=>\"59.381\",\r\n\"12\"=>\"57.140\",\r\n\"13\"=>\"54.840\",\r\n\"14\"=>\"52.465\",\r\n\"15\"=>\"50.012\",\r\n\"16\"=>\"47.487\",\r\n\"17\"=>\"44.905\",\r\n\"18\"=>\"42.281\",\r\n\"19\"=>\"39.625\",\r\n\"20\"=>\"36.931\",\r\n\"21\"=>\"34.174\",\r\n\"22\"=>\"31.307\",\r\n\"23\"=>\"28.251\",\r\n\"24\"=>\"24.875\",\r\n\"25\"=>\"20.941\",\r\n\"26\"=>\"15.939\",\r\n\"27\"=>\"8.291\",\r\n\"28\"=>\"0.000\"}\r\n%>\r\n<script>\r\n    var koos = <%= koos.to_json.html_safe %>; \r\n    \r\n    function interval_score_update() {\r\n        v = $(this).val();\r\n        $(\'#data-koos_interval_score\').val(koos[v]);\r\n    }\r\n\r\n    $(document).ready(function() {\r\n        // iamzam\r\n        $(\'#data-koos_total_koos_score\').change(interval_score_update);\r\n    });\r\n</script>\r\n',NULL,NULL,NULL,'2018-12-22 17:46:22','2018-12-22 17:46:22','',''),(3834,'form',1514,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n// womac_score\r\nvar w_radio = [\'womac_walk_on_flat\',\'womac_going_up_down_stair\',\'womac_night_pain\',\'womac_sitting_or_lying\',\'womac_standing_upright\',\'womac_knee_joint_stiffness_morning\',\'womac_knee_joint_stiffness_later_day\',\'womac_ascending_stairs\',\'womac_descending_stairs\',\'womac_rising_from_sitting\',\'womac_standing\',\'womac_bending_to_floor_pick_up_object\',\'womac_walking_on_flat\',\'womac_getting_in_out_of_car\',\'womac_going_shopping\',\'womac_putting_on_socks\',\'womac_raising_from_bed\',\'womac_taking_off_socks\',\'womac_lying_in_bed\',\'womac_getting_in_out_of_restroom\',\'womac_sitting\',\'womac_getting_on_off_toilet\',\'womac_heavy_domestic_duties\',\'womac_light_domestic_duties\'];\r\nfunction womac_score_update() {\r\n    txt = $(this).val();\r\n    num = isNaN(parseInt(txt)) ? 0 : parseInt(txt);\r\n    console.log(\"womac = \" + $(this).val());\r\n    \r\n    sum = 0;\r\n    for (var i in w_radio) {\r\n        f = \"input[id^=\'update_\" + w_radio[i] + \"\']:checked\";\r\n        v = $(f).val();\r\n        n = isNaN(parseInt(v)) ? 0 : parseInt(v);\r\n        sum += n;\r\n    }\r\n    $(\"#data-womac_total_womac_score\").val(sum);\r\n}\r\n\r\n$(document).ready(function(){\r\n    // ----\r\n    // womac_score\r\n    // ----\r\n    kn_score = 0;\r\n    tmp_score = $(\"#data-womac_total_womac_score\").val();\r\n    if (tmp_score != \'\') {\r\n        kn_score = tmp_score;\r\n    } else {\r\n        $(\"#data-womac_total_womac_score\").val(\"0\");\r\n    }\r\n    for (var i in w_radio) {\r\n        f = \"input[id^=\'update_\" + w_radio[i] + \"\']\";\r\n        $(f).change(womac_score_update);\r\n    }\r\n});\r\n    \r\n</script>',NULL,NULL,NULL,'2018-12-22 17:49:14','2018-12-22 17:49:14','',''),(3835,'setcase',1496,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n	return_url = url(\'index\')\r\n	return_url = params[:return] if params[:return]\r\n	\r\n	locker_model = get_model(\'locker\')\r\n	\r\n	date = Time.now.strftime(\"%d/%m/%Y\")\r\n	time = Time.now.strftime(\"%H:%M\")\r\n	\r\n    date = params[:date] if params[:date]\r\n    time = params[:time] if params[:time]\r\n    \r\n    s_models = get_model(\'schedule\').all\r\n    \r\n    model = get_model(this.table_name)\r\n    if request.post?\r\n        if params[:id]\r\n            @patient_module = @module_model.find(params[:id])\r\n            record = model.find(@patient_module.module_id)\r\n            %><%#=record.inspect%><%\r\n            @patient_module.update_attributes :date=>params[:date],:time=>params[:time]\r\n            record.update_attributes :status=>\"Appointed\",:date=>params[:date],:start=>params[:time],:stop=>params[:time]\r\n%>\r\n<script>\r\n$.sticky(\"<i class=\'icon-ok icon-white\'></i> Save appointment success\", {autoclose : 3000, position: \"top-center\" , type: \"st-success\"});\r\n</script>\r\n<%            \r\n            # @patient_module.update_attributes :status=>\"Appointed\",:date=>params[:date],:time=>params[:time]\r\n        end\r\n        if params[:remove_id]\r\n            @patient_module = @module_model.find(params[:remove_id])\r\n            record = model.find(@patient_module.module_id)\r\n            record.update_attributes :status=>\"Waiting\"\r\n%>\r\n<script>\r\n$.sticky(\"<i class=\'icon-remove\'></i> Removed appointment success\", {autoclose : 3000, position: \"top-center\" , type: \"st-error\"});\r\n</script>\r\n<%            \r\n        end\r\n    end\r\n	\r\n%> \r\n\r\n<div class=\"span11\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-calendar\" style=\"margin-left:10px;\"></i> Date appointment\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n            firstday = Date.strptime(\"1\"+date.strftime(\"/%m/%Y\"), \'%d/%m/%Y\')\r\n            d = date.strftime(\"%u\")\r\n            # %U if start Sun,%W if start Mon\r\n            thisweek = date.strftime(\"%W\").to_i - firstday.strftime(\"%W\").to_i \r\n            thisweek +=1\r\n            day_provider = s_models.collect{|i| i if i.day==d}.compact\r\n        %>\r\n            Date : <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\',:style=>\'width:120px\' %> \r\n            Time : <%= text_field_tag \'time\',time,:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n            <%=link_to \"( Today Click )\", \"./setcase?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %>\r\n            <br><%=date.strftime(\"%A\")%> Week: <%=thisweek%>\r\n            <%for p in day_provider%>\r\n                <%if p.week.include? thisweek.to_s %>\r\n                <%=\" GA : \" if p.type==\"1\"%>\r\n                <%=\" LA : \" if p.type==\"2\"%>\r\n                <%=p.doctor%> \r\n                <%end%>\r\n            <%end%>\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"./setcase?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n	$(\"#record-time\").kendoTimePicker({\r\n		value: \'<%= time %>\',\r\n		interval: 10\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n</div><!--w-box Date appointment-->\r\n<br>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n    # status_list=%w{waiting }.collect{|i| i.humanize}\r\n\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    table_model = %w{ hn patient procedure }.collect{|i| i.to_sym}\r\n\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\',:procedure=>\'Procedure\',:start=>\'Start\',:tel=>\'Tel\',:date_add=>\'Date added\' }\r\n\r\n\r\n\r\n%>\r\n\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-list\" style=\"margin-left:10px;\"></i> Appointment list\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n<%\r\n    apl = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day,:order=>\"start\")\r\n    apl.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id) and i.status!=\"Waiting\"\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}&return=../Appointment/setcase\") if patient\r\n         public_id = \'-\'\r\n         app_date = i.date.strftime(\"%d/%m/%Y\")+i.start.strftime(\" %H:%M\")\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type,:start=>app_date\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Appoint\',\"javascript:confirm_app(\'\\\\#{m.id}\',\'\\\\#{provider_name}\',\'\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\',\'\\\\#{procedure_name}\',\'\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\')\",:class=>\'btn btn-small btn-success\') +\" \"+link_to(\'Detail\',\"../Appointment/show?id=\\\\#{m.id}&return=../Appointment/setcase\",:class=>\'btn btn-small \')\r\n        #  c[:pending_ctrl]=link_to(\'Detail\',\"../Appointment/show?id=\\\\#{m.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Appoint\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n\r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"../Home/patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)+\' \'+link_to(\'Remove\',\"javascript:remove_app(\'\\\\#{m.id}\',\'\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\',\'\\\\#{app_date}\')\",:class=>\'btn btn-small btn-danger\')\r\n        #  c[:processing_ctrl]=link_to(\'Detail\',\"../Appointment/show?id=\\\\#{m.id}&return=../Appointment/setcase\",:class=>\'btn btn-small \')\r\n\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n \r\n\r\n%>    \r\n    <%= tabular :model=>[:start,:provider]+table_model+[:note,:processing_ctrl],:data=>apl,:labels=>labels %>\r\n    </div>\r\n</div><!--w-box Appointment list-->\r\n\r\n\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-book\" style=\"margin-left:10px;\"></i> Booking list\r\n        <span style=\"float:right\"><a href=\"../Appointment/create?return=../Appointment/setcase\" class=\"btn\"><i class=\"splashy-add\"></i> New booking</a></span>\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n<%\r\n    \r\n    aps = ap_model.all(:status=>\'Waiting\') \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    # list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}&return=../Appointment/setcase\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type,:tel=>patient.mobile,:date_add=>i.created_at.strftime(\"%d/%m/%Y\")\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Appoint\',\"javascript:confirm_app(\'\\\\#{m.id}\',\'\\\\#{provider_name}\',\'\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\',\'\\\\#{procedure_name}\',\'\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\')\",:class=>\'btn btn-small btn-success\') +\" \"+link_to(\'Detail\',\"../Appointment/show?id=\\\\#{m.id}&return=../Appointment/setcase\",:class=>\'btn btn-small \')\r\n        #  c[:pending_ctrl]=link_to(\'Detail\',\"../Appointment/show?id=\\\\#{m.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Appoint\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n\r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    # waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    waiting = aps.collect{|i| i if i[:status]==\'Waiting\' }.compact\r\n \r\n    # table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    providers = {}\r\n    \r\n    for i in waiting\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end    \r\n\r\n%>   \r\n        <div class=\"row-fluid\"><div class=\"span12\">\r\n        <div class=\"tabbable tabbable-bordered\">\r\n            <ul class=\"nav nav-tabs\">\r\n            <%  index=0\r\n                providers.each_pair do |k,v| \r\n                index+=1\r\n                active = \"\"\r\n                active = \"class=active\" if index==1\r\n            %>\r\n                <li <%=active%>><a href=\"#tab_l<%=index%>\" data-toggle=\"tab\"><%= k %></a></li>\r\n            <% end %>    \r\n            </ul>\r\n            <div class=\"tab-content\">\r\n            <%  index=0\r\n                providers.each_pair do |k,v| \r\n                index+=1\r\n                active = \"\"\r\n                active = \"active\" if index==1\r\n            %>\r\n                <div class=\"tab-pane <%=active%>\" id=\"tab_l<%=index%>\">\r\n                    <%= tabular :model=>[:date_add]+table_model+[:tel,:pending_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n                </div>\r\n            <% end %>    \r\n            </div>\r\n        </div>\r\n        </div></div>\r\n        <br>\r\n    </div>\r\n</div><!--w-box Booking list-->\r\n\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        <i class=\"icon-user\" style=\"margin-left:10px;\"></i> OR schedule\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <table class=\"table table-bordered\">\r\n        <thead><th>Day</th><th>GA</th><th>LA</th></thead>\r\n<%\r\n        days = []\r\n        days << [\'1\',\'#FFD133\',\'วันจันทร์\']\r\n        days << [\'2\',\'#EA67DE\',\'วันอังคาร\']\r\n        days << [\'3\',\'#41BD22\',\'วันพุธ\']\r\n        days << [\'4\',\'#EB7528\',\'วันพฤหัสบดี\']\r\n        days << [\'5\',\'#28BCEB\',\'วันศุกร์\']\r\n        for d in days\r\n            s = s_models.collect{|i| i if i.day==d[0]}.compact\r\n            s_ga = s.collect{|i| i if i.type==\'1\' }.compact\r\n            s_la = s.collect{|i| i if i.type==\'2\' }.compact\r\n        %>\r\n        <tr >\r\n        <td><%=d[2]%></td>\r\n        <td>\r\n        <% for ga in s_ga %> \r\n        <%=ga.doctor%> <b>Week :</b> <%=ga.week%></br>\r\n        <% end %>\r\n        </td>\r\n        <td>\r\n        <% for la in s_la %> \r\n        <%=la.doctor%> <b>Week :</b> <%=la.week%><br>\r\n        <% end %>\r\n        </td>\r\n        </tr>\r\n        <% \r\n        end\r\n%>        \r\n        \r\n        </table>\r\n        <%#=s_models.inspect%>\r\n    </div>\r\n</div><!--w-box OR schedule-->\r\n\r\n</div><!--span11-->\r\n\r\n<!--modal-->\r\n<script>\r\n	function confirm_app(id,provider,patient,procedure,note){\r\n	    //alert(\"confirm\");\r\n	   // $(\"#app_date\").html(kendo.toString($(\"#today-date\").val(), \'d\'));\r\n	    $(\"#app_id\").val(id);\r\n	    $(\"#app_date\").kendoDatePicker({\r\n            value: kendo.toString($(\"#today-date\").val(), \'d\')\r\n            \r\n	    });\r\n    	$(\"#app_time\").kendoTimePicker({\r\n    		value: $(\"#record-time\").val(),\r\n    		interval: 10\r\n    	});\r\n    	$(\"#app_date\").parent().css(\'width\',\"120px\");\r\n    	$(\"#app_time\").parent().css(\'width\',\"50px\");\r\n	    $(\"#app_provider\").html(provider)\r\n	    $(\"#app_patient\").html(patient);\r\n	    $(\"#app_procedure\").html(procedure);\r\n	    $(\"#app_note\").html(note);\r\n	    $(\"#myModal\").modal(\"toggle\");\r\n	}\r\n	\r\n	function remove_app(id,patient,date){\r\n	    $(\"#remove_id\").val(id);\r\n	    $(\"#remove_text\").html(\"ยืนยันลบการนัดหมาย \"+patient+\" \"+date);\r\n	    $(\"#removeModal\").modal(\"toggle\");\r\n	}\r\n</script>\r\n<div id=\"myModal\" class=\"modal hide fade\" tabindex=\"-1\" role=\"dialog\" aria-labelledby=\"myModalLabel\" aria-hidden=\"true\">\r\n<form id=\"app_form\" method=\"post\">\r\n<input type=\"hidden\" name=\"id\" id=\"app_id\">\r\n<div class=\"modal-hearder\">\r\n    <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-hidden=\"true\">×</button>\r\n    <h3> <i class=\"icon-calendar\" style=\"vertical-align:middle;margin-left:10px;\"></i> Confirm appointment</h3>   \r\n    <hr>\r\n</div>\r\n<div class=\"modal-body\">\r\n    <table border=\"0\" style=\"width:100%\">\r\n    <tr>\r\n        <td>Date <span style=\"float:right\">:</span></td>\r\n        <td> <input id=\"app_date\" name=\"date\" /></span></td>\r\n        <td> <span style=\"float:right\"> Time :</span></td>\r\n        <td> <input id=\"app_time\" name=\"time\" /></span></td>\r\n        <td></td>\r\n    </tr>\r\n    <tr><td>Provider <span style=\"float:right\">:</span></td><td> <span id=\"app_provider\"></span></td></tr>\r\n    <tr><td>Patient <span style=\"float:right\">:</span></td><td> <span id=\"app_patient\"></span></td></tr>\r\n    <tr><td>Procedure <span style=\"float:right\">:</span></td><td> <span id=\"app_procedure\"></td></div></tr>\r\n    <tr><td>Note <span style=\"float:right\">:</span></td><td> <span id=\"app_note\"></span></td></tr>\r\n    </table>\r\n</div>\r\n<div class=\"modal-footer\">\r\n    <button class=\"btn\" data-dismiss=\"modal\" aria-hidden=\"true\">Close</button>\r\n    <button class=\"btn btn-success\" id=\"btn_confirm\" type=\"submit\"><i class=\"icon-ok icon-white\"></i> Confirm</button>\r\n</div>\r\n</form>\r\n<script>\r\n	$(\"#btn_confirm\").click(function(){\r\n	   // $.sticky(\"<i class=\'icon-ok icon-white\'></i> Save appointment success\", {autoclose : 3000, position: \"top-center\" , type: \"st-success\"});\r\n	   // $(\"#myModal\").modal(\"hide\");\r\n	});\r\n</script>\r\n</div>\r\n\r\n<div id=\"removeModal\" class=\"modal hide fade\" tabindex=\"-1\" role=\"dialog\" aria-labelledby=\"myModalLabel\" aria-hidden=\"true\">\r\n<form id=\"remove_form\" method=\"post\">\r\n<input type=\"hidden\" name=\"remove_id\" id=\"remove_id\">\r\n<div class=\"modal-hearder\">\r\n    <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-hidden=\"true\">×</button>\r\n    <h3> <i class=\"icon-calendar\" style=\"vertical-align:middle;margin-left:10px;\"></i> Confirm Remove</h3>   \r\n    <hr>\r\n</div>\r\n<div class=\"modal-body\">\r\n    <span id=\"remove_text\"></span>\r\n</div>\r\n<div class=\"modal-footer\">\r\n    <button class=\"btn\" data-dismiss=\"modal\" aria-hidden=\"true\">Close</button>\r\n    <button class=\"btn btn-danger\" id=\"btn_confirm\" type=\"submit\"><i class=\"icon-remove icon-white\"></i> Remove</button>\r\n</div>\r\n</form>\r\n</div>\r\n<!--end modal-->\r\n\r\n',NULL,NULL,NULL,'2018-12-24 06:39:50','2018-12-24 06:39:50','setcase',''),(3836,'get_emr_image',574,3,'<%= render :inline=>this.init%><%  \r\n    date = Time.now\r\n   \r\n   \r\n    \r\n   \r\n    if params[:date] \r\n        date = Time.parse(params[:date])\r\n    end\r\n   \r\n    start_date = date.beginning_of_month \r\n    end_date = date.end_of_month\r\n    \r\n    start_date = date.beginning_of_day\r\n    end_date = date.end_of_day\r\n    \r\n    \r\n    document_name = \'colonoscopy\'\r\n    document_name = params[:report] if params[:report]\r\n   \r\n\r\n    models = get_model\r\n    \r\n    \r\n    \r\n    apps = models[:appointment].where(:date=>{\'$gte\'=>start_date,\'$lte\'=>end_date}).all\r\n    \r\n    \r\n    mapps = @patient_module_model.collection.find(:module_id=>{\'$in\'=>apps.collect{|i| i.id}}).to_a\r\n        \r\n    # apps = models[:appointment].collection.find(:_id=>mapps[0][\'module_id\']).to_a\r\n     \r\n    mpatients = Hash[@patient_model.collection.find({:_id=>{\'$in\'=>mapps.collect{|i| i[\'patient_id\']}}},:fields=>{\'hn\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'prefix_name\'=>1}).to_a.collect{|i| [i[\'_id\'],i] }]\r\n    \r\n    allforms =  @patient_module_model.collection.find(:parent_id=>{\'$in\'=>mapps.collect{|i| i[\'_id\']}}).to_a\r\n    \r\n    forms = {}\r\n\r\n    for i in allforms\r\n    \r\n        form = i[\'module_name\'].split(\'#\')[-1]\r\n        unless forms[form]\r\n         \r\n            document =  @current_project.get_document form\r\n            for j in document.fields\r\n                if j.field_type == \'image_camera\'\r\n                    \r\n                      forms[form] = {:field=>j.column_name, :records=>[]}\r\n                \r\n                end\r\n            end\r\n            \r\n        end\r\n        \r\n        if  forms[form]\r\n            patient = mpatients[i[\'patient_id\']]\r\n        \r\n            forms[form][:records] << {:module_id=>i[\'module_id\'],:hn=>patient[\'hn\'],:created_at=>i[\'created_at\'] } \r\n    \r\n        end\r\n    \r\n    end\r\n    \r\n    list = []\r\n    \r\n    \r\n    forms.each_pair do |k,v|\r\n       \r\n       \r\n       mrecords = Hash[models[k.to_sym].collection.find({:_id=>{\'$in\'=>v[:records].collect{|i| i[:module_id]} }}, :fields=>{v[:field]=>1} ).collect{|i| i if i[v[:field]].size>0}.compact.collect{|i| [i[\'_id\'],i]}]\r\n       \r\n       mimgs = {}\r\n    #   atts =v[:records].collect{|i|  models[:attachment].collection.find({:_id=>{\'$in\'=>mrecords[i[:module_id]][v[:field]]}})  if mrecords[i[:module_id]];} \r\n       atts =v[:records].collect{|i|  models[:attachment].find(mrecords[i[:module_id]][v[:field]])  if mrecords[i[:module_id]];}\r\n       \r\n      \r\n      \r\n       for x in atts\r\n       if x\r\n       for y in x \r\n            \r\n            mimgs[y.id.to_s] = y.created_at\r\n            \r\n       end\r\n       end\r\n   \r\n       end\r\n  \r\n       \r\n       records = v[:records].collect{|i|  i[:ae]=k;\r\n    \r\n       i[:imgs] = []\r\n       \r\n       if mrecords[i[:module_id]]; \r\n       \r\n       mrecords[i[:module_id]][v[:field]].each_with_index do |j, jdx| \r\n                \r\n                stamp = mimgs[j]\r\n                stamp = i[:created_at] + jdx*5 unless stamp\r\n       \r\n       \r\n                i[:imgs] << {:id=>j,:path=>\"/content/esm/\\\\#{@current_solution.name}/\\\\#{@current_project.name}/content/\\\\#{k}/\\\\#{v[:field]}/\\\\#{j}.jpg\",:created_at=>stamp,:idx=>jdx  }\r\n                \r\n                \r\n       end \r\n       index = 0 \r\n       \r\n       i[:imgs].sort!{|a,b| a[:created_at]<=>b[:created_at]} .collect{|j|\r\n        \r\n        j[:idx] = index\r\n        index+=1\r\n       \r\n       } \r\n       \r\n       \r\n       end\r\n                \r\n       \r\n       i if mrecords[i[:module_id]]; \r\n                \r\n      }.compact\r\n       \r\n       list+=records\r\n       \r\n        # /content/esm/colo/colo/content/colonoscopy/image/5c2043c8e13823027700005d.jpg\r\n    end\r\n    \r\n    #  hn form images\r\n    \r\n    \r\n    # list = []\r\n    # for i in allforms\r\n    \r\n    #     form = i[\'module_name\'].split(\'#\')[-1]\r\n    #     if img = forms[form]\r\n                \r\n    #         record = models[form.to_sym].collection.find({:_id=>i[\'module_id\']}, :fields=>{img=>1} ) \r\n                \r\n    #         list << record  \r\n            \r\n    #     end\r\n       \r\n        \r\n    # end\r\n    \r\n    \r\n    # list = forms\r\n    \r\n \r\n    msg = {:return=>200,:msg=>params.inspect ,:data=>list}\r\n    \r\n %><%=msg.to_json.html_safe %>\r\n ',NULL,NULL,NULL,'2018-12-25 15:34:10','2018-12-25 15:34:10','get_emr_image','*'),(3837,'print_partial',491,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n    # id of operative note\r\n    \r\n    models  = @models\r\n    pm = @module_model.find(params[:id])\r\n    colono_id = pm.module_id\r\n    record = models[:colono].find(colono_id)\r\n    @record = record\r\n    @document = get_document this.document_name\r\n    \r\n\r\n  \r\n    if @patient \r\n    patient = @patient\r\n    date = Time.now.to_datetime\r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    year = (t/365).to_i\r\n    t%=365\r\n    month = (t/30).to_i\r\n    t%=30\r\n    day = t.to_i\r\n    end\r\nend %>\r\n\r\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>PRINT</title>\r\n	<%= javascript_include_tag \"application\"  %>\r\n	<%# stylesheet_link_tag    \"application\"  %>\r\n</head>\r\n<style type=\"text/css\" media=\"all\">\r\nhtml { }\r\n#page {border:solid 1px; width:910px; border-color:#666;\r\n-webkit-border-radius: 5px; /* Safari prototype */\r\n-moz-border-radius: 5px; /* Gecko browsers */\r\nborder-radius: 5px; /* Everything else - limited support at the moment */\r\nmargin-bottom:5px; padding-bottom:5px; padding-left:20px;padding-right:20px}\r\n#head { width:100%; height:60px;}\r\n#logoleft { margin-left:20px; float:left;}\r\n#logoright{ margin-right:20px; float:right;}\r\nth              { font-weight: bolder; text-align: center }\r\ncaption         { text-align: center }\r\nbody            {   font-family: Arial, Helvetica, sans-serif; color:#000;background:none;font-size: 15px}\r\n.wrapper{ width:960px;margin-left:auto;margin-right:auto; } \r\nhr    {clear: both;border: none;border-top: 1px solid #AAA;border-bottom: 1px solid #FFF; font-size: 0px;line-height: 0;overflow: visible; width:98%; border-bottom:0px}\r\nh1              { font-size: 2em; margin: .67em 0 }\r\nh2              { font-size: 1.5em; margin: .83em 0 }\r\nh3              { font-size: 1.17em; margin: 1em 0 }\r\np {color:#666;}\r\nh4, p,\r\nblockquote, ul,\r\nform,\r\nol, dl          { margin: 5px; }\r\nh5              { font-size: .83em; line-height: 1.17em; margin: 1.67em 0 }\r\nh6              { font-size: .67em; margin: 2.33em 0 }\r\n\r\nh4 { font-size:14pt; color:#333; height:16px;}\r\nblockquote      { margin-left: 40px; margin-right: 40px }\r\ni, cite, em,\r\nvar, address    { font-style: italic }\r\npre, tt, code,\r\nkbd, samp       {  font-size:14px; }\r\npre             {margin:0;margin-left:1em; color:#666}\r\nbig             { font-size: 1.17em }\r\nv {color:#000;}\r\nsmall, sub, sup { font-size: .83em }\r\nol, ul, dd      { margin-left: 40px }\r\nol              { list-style-type: decimal }\r\nol ul, ul ol,\r\nul ul, ol ol    { margin-top: 0; margin-bottom: 0 }\r\n.clear{clear:both;}\r\n@media print {\r\n  @page         { width:960px; margin-top:5px; }\r\n  blockquote, \r\n .wrapper{ width:960px;margin-left:auto;margin-right:auto;} \r\n}\r\n\r\n#box{\r\n    width:215px;\r\n    float:left;\r\n    padding:0px;\r\n    text-align:center;\r\n    border:1px solid #ccc;\r\n    -webkit-border-radius: 5px; /* Safari prototype */\r\n    -moz-border-radius: 5px; /* Gecko browsers */\r\n    border-radius: 5px; /* Everything else - limited support at the moment */    \r\n    margin:5px;\r\n    font-size:0.8em;\r\n    height:135px;\r\n    overflow:hidden;\r\n}\r\n.smm { font-size:0.7em; border:1px solid;border-color:#ccc;}\r\n#box img{\r\n    \r\n    \r\n    height:120px;\r\n}\r\nlabel{\r\n    color:#666;\r\n}\r\n.digaw {height:100px;min-height:100px;}\r\n.sidationcss\r\n{width:160px; float:left; margin-bottom:3px;}\r\n</style>\r\n<body>\r\n<div class=\"wrapper\">\r\n\r\n<div id=\"head\">\r\n<center>\r\n <div id=\"logoleft\" style=\"margin-left:0px\"><img src=\'<%=@current_project.get_setting(\"logo_report_path\")%>\' height=\"70px\" style=\"Float:left,top:5px\" /></div><h3> <strong><%=@current_service.title %> Diagnosis Report<br />\r\n<%=@current_project.get_setting(\"report_title_1\")%><br />\r\n<%=@current_project.get_setting(\"report_title_2\")%>\r\n  </strong></h3>\r\n</center>\r\n\r\n\r\n\r\n</div><br />\r\n<div id=\"page\">\r\n\r\n<table width=\"100%\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr>\r\n<td > \r\n<table width=\"100%\">\r\n<tr><td>    <strong>Ref HN :&nbsp;</strong>\r\n      <%=patient.hn%> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n      <strong> ชื่อ-สกุล : </strong>\r\n      <%= patient.prefix_name %> <%= patient.first_name %> <%= patient.last_name %>\r\n    \r\n      <%\r\n    gender = \'ไม่ระบุ\'\r\n    if patient.gender == \'1\'\r\n        gender = \'ชาย\'\r\n    elsif patient.gender == \'2\'\r\n        gender = \'หญิง\'\r\n    end\r\n \r\n\r\n%>\r\n      <strong>เพศ : </strong><%= gender %> &nbsp; \r\n      <strong>เกิด ว/ด/ป :</strong>\r\n      <%=patient.birth_date.strftime(\'%d/%m/%Y\') if patient.birth_date%> &nbsp;\r\n      <strong>อายุ :&nbsp;</strong>\r\n      <%= year%> Y \r\n      <!--<%=month%> M <%= day%> D--> \r\n      <br /><strong>Date :  </strong> <%=render_value \'start_procedural_date\'%> <strong>Produral Time :  </strong> <%=render_value \'start_procedural_time\'%> - <%=render_value \'stop_procedural_time\'%> Total Time :  <%=render_value \'procedural_time\'%>  <strong>Project : </strong> <%=render_value \'study_project\'%>\r\n    <br /><strong>Endoscopist : </strong><%=render_value \'endoscopist\'%>  , <strong>Endoscopist assist : </strong><%=render_value \'assist1endoscopist\'%> <%=render_value \'assist2endoscopist\'%> \r\n    <br /><strong>Nurse : </strong><%=render_value \'nurse\'%> , <strong>Nurse assist : </strong><%=render_value \'assist_1_nurse\'%><%=render_value \'assist_2_nurse\'%>\r\n    </td></tr>\r\n</table>\r\n\r\n   \r\n   \r\n\r\n\r\n</td>\r\n\r\n</tr>\r\n</table>\r\n &nbsp;&nbsp;&nbsp;<strong>Indication : </strong><%=render_value \'clinical_indication\'%><% if record[\'other_indication_note\']!=\'\' %> : <%=render_value \'other_indication_note\'%><% end %>\r\n\r\n &nbsp;&nbsp;&nbsp;<%=render_value \'cecal_intubation_time\'%> &nbsp;\r\n \r\n <%=render_value \'withdrawal_time\'%>\r\n	\r\n	\r\n	\r\n	<hr />\r\n    \r\n    <%\r\n        # atts = models[:attachment].find(record.image)\r\n        # atts = record.image[0..4].compact.collect{|i| models[:attachment].find(i)}\r\n   \r\n       atts_list = record.image[0..4]\r\n       if record[:selected_image] and record.selected_image and record.selected_image.size > 0\r\n          \r\n           atts_list = record.selected_image[0..4]\r\n           \r\n       end\r\n       \r\n       \r\n       atts = atts_list.compact.collect{|i| models[:attachment].find(i)}\r\n\r\n    %>\r\n\r\n\r\n<style>\r\n<% if @current_solution.name!=\'gi\' %>\r\n.crop {\r\n    width: 300px;\r\n    overflow: hidden;\r\n\r\n}\r\n\r\n.crop img {\r\n    width: 100%;\r\n max-width: 270px;\r\n    margin: 0px;\r\n min-height: 170px;\r\n}\r\n<% else %>\r\n.crop {\r\n    width: 240px;\r\n    /*height: 165px;*/\r\n    margin:5px;\r\n}\r\n\r\n.crop img {\r\n    // width: 240px;\r\n    height: 165px;\r\n}\r\n<% end %>\r\n    \r\n</style>\r\n    <div style=\"float:right;  width: 280px;  padding: 5px; text-align:center; font-size:14px;\">\r\n    <% for i in atts  %>\r\n    <div class=\"crop\">\r\n    <img src=\"<%=i.path%>\" /><br /><span style=\"margin-left:0px;border:0px solid;width:100%;display:block\"><%=i.title%></span><br />\r\n    </div>\r\n    <% end %>\r\n\r\n\r\n   \r\n    \r\n    </div>\r\n<div style=\"float:left\">\r\n\r\n\r\n<table width=\"550\" cellpadding=\"5\" cellspacing=\"5\">\r\n<tr><td valign=\"top\"><strong>Consent</strong></td><td>The procedure of the examination, including possible complications were clearly and discussed with the patient and family, then a consent form was signed by the patient and/or family</td></tr>\r\n<tr><td valign=\"top\"><strong>Procedure</strong></td>\r\n  <td>The patient\'s blood pressure, pulse and oxygen saturation were montiored ontinuously throghout the procedure. the scope was passed under direct vision through the anus and advanced to the colon. The endoscopy was accomplished without difficulty. The findings were described below. The patient tolerated the procedure well.</td></tr>\r\n</table>\r\n<div class=\"clear\"></div>\r\n\r\n<%= render :inline=>this.display %>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n<div id=\"page\" style=\"height:40px;padding-top: 5px;\">\r\n<span style=\"float:right\">\r\n<strong>Reported by :</strong>&nbsp;<%= @current_user.login.humanize if @current_user %><br />\r\n<strong>Printed Date Time :</strong>&nbsp;<%=render_value \'date_approve\' %> <%=render_value \'time_approve\'%>\r\n</span>\r\n<strong>Signature</strong> ...........................................................................\r\n<br />\r\n<strong><% if record[\'approve\']!=\"\" %>Approved<% end %> By :</strong> \r\n<%=render_value \'endoscopist_approve\'%> (Gastroenterologist)\r\n \r\n</div>\r\n<div class=\"clear\">\r\n</div>\r\n\r\n\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>\r\n\r\n',NULL,NULL,NULL,'2018-12-27 04:08:04','2018-12-27 04:08:04','print_partial',''),(3840,'document_name',1517,1,'\'demographic\'',NULL,NULL,NULL,'2019-01-02 00:52:07','2019-01-02 00:52:07',NULL,NULL),(3841,'document_name',1518,1,'\'diagnosis\'',NULL,NULL,NULL,'2019-01-02 00:53:26','2019-01-02 00:53:26',NULL,NULL),(3842,'document_name',1519,1,'\'treatment_ebc\'',NULL,NULL,NULL,'2019-01-02 00:54:20','2019-01-02 00:54:20',NULL,NULL),(3843,'document_name',1520,1,'\'treatment_mbc\'',NULL,NULL,NULL,'2019-01-02 00:55:00','2019-01-02 00:55:00',NULL,NULL),(3844,'document_name',1521,1,'\'outcome\'',NULL,NULL,NULL,'2019-01-02 00:56:00','2019-01-02 00:56:00',NULL,NULL),(3845,'patient_record',1522,2,'    \r\n    <% Time.zone =  get_setting \'time_zone\' %>\r\n    <style>\r\n    body { min-width:0px; }\r\n    .gebo-fixed { background-color:#f5f5f5; }\r\n    #sidebar_bt {display:none }\r\n    </style>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n    <div class=\"w-box\">\r\n        <div class=\"w-box-header\">\r\n            Patient Medical Records\r\n            <div class=\"pull-right\">\r\n            <%=link_to(\'<< Back\',\'index\',:class=>\'btn btn-mini\')%>\r\n            </div> \r\n        </div>  \r\n        <div class=\"w-box-content cnt_a\">\r\n        \r\n    <%\r\n    \r\n        ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n        ehr_models = ehr.get_model\r\n        patient_model = ehr_models[:patient]\r\n        patient_module_model = ehr_models[:patient_module]\r\n        groups = this.config\r\n        emr_models = get_model\r\n        ap = emr_models[:appointment].find(params[:id])\r\n        pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n        \r\n        locker_model = emr_models[:locker]\r\n        if params[:reset_lock]\r\n            l = locker_model.find(params[:reset_lock])\r\n            l.destroy if l\r\n        end\r\n        #locker_model.where(:session=>session[:session_id]).all.each do |i|\r\n        #i.destroy if i\r\n        #end\r\n         \r\n        \r\n        \r\n        if pm\r\n        \r\n        if  params[:schema_patient_module]\r\n           pm.update_attributes params[:schema_patient_module]\r\n        end\r\n        \r\n        if params[:provider_id]\r\n          ap.update_attributes :provider=>params[:provider_id]\r\n           ap = emr_models[:appointment].find(params[:id])\r\n         end\r\n        \r\n        # find provider\r\n        provider = emr_models[:provider].find(ap.provider.to_s)\r\n        \r\n        # find patient\r\n        patient = patient_model.find(pm.patient_id)\r\n        \r\n        params[:patient]=patient\r\n        params[:patient_module]=pm\r\n        \r\n       # s = Service.get(\'ehr.emr.EmrHelper\')\r\n    #    obj = s.load context\r\n        \r\n        providers = emr_models[:provider].where(:provider_type=>\'1\').all\r\n        \r\n    %>\r\n    \r\n    <% services =  @current_project.get_services_by_abstract(\'ehr.emr.Document\').collect{|i| i if  i.name!=\'appointment\' and i.name!=\'live_document\'}.compact %>\r\n    <div style=\"border:0px solid\">\r\n    <div class=\"document-border\" style=\"border:0px solid;width:100%; padding:0px;max-width:688px\">\r\n    <%# render :inline=>obj.show_patient %>\r\n    <div id=\"patient\">\r\n    ...\r\n    </div>\r\n    <script>\r\n    <%\r\n            url = \'../../www/Patient/search_result?\'\r\n            url += \'&id=\'+patient.id.to_s\r\n      %>      \r\n            $.ajax({\r\n              url: \'<%=url.html_safe%>\',\r\n             success: function(data){\r\n              $(\'#patient\').html(data);  \r\n              }\r\n            });\r\n    </script>\r\n    \r\n    <%\r\n    \r\n    \r\n    previous = patient_module_model.all(:patient_id=>patient.id,:id=>{\"$ne\" => pm.id},:module_name=>pm.module_name,:order=>\'date desc\')\r\n    history = []\r\n    x = previous[0..7]\r\n    last = []\r\n    last = x.compact if x\r\n    history = []\r\n    y = previous[8..-1]\r\n    history = y.compact if y and  previous.size>5\r\n                                         \r\n    current = time_ago_in_words(ap.date)\r\n    current_date = ap.date.strftime(\"%d-%m-%y\")\r\n    current = \'Today\' if current_date == Time.now.strftime(\"%d-%m-%y\")\r\n    \r\n    %>\r\n    \r\n    \r\n    \r\n    <div class=\"clear\"></div>\r\n    \r\n    <h4><%= @current_project.title %> Recrods</h4>\r\n    \r\n    \r\n    \r\n    <% else %>\r\n    Data missing\r\n    <% end %>\r\n    <br/><br/>\r\n    <div class=\"clear\"></div>\r\n    <%\r\n        pm = patient_module_model.first(:module_id=>ap.id.to_s)\r\n        modules = patient_module_model.all(:parent_id=>pm.id,:patient_id=>pm.patient_id).collect do |i|\r\n            name = i.module_name.split(\"#\")[-1]\r\n            hn = patient.hn\r\n            \r\n            rr = link_to(\"\\\\#{i.date.strftime(\"%d-%m-%Y\")} \\\\#{i.time.strftime(\"%H:%M\") if i.time } \", \"../\\\\#{name.camelize}/show?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\")\r\n            rr += \' \'\r\n            #rr += link_to(\"[ Edit ]\", \"../\\\\#{name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\")\r\n            date = i.date.strftime(\"%d-%m-%y\")\r\n            \r\n            #show = link_to(\'Show\',\"../\\\\#{name.camelize}/show?id=\\\\#{i.id}&record_name=\\\\#{hn}&return=../Home/patient_record?id=\\\\#{ap}\",:class=>\'btn btn-small\')\r\n            show = link_to(\"Edit \", \"../\\\\#{name.camelize}/edit?id=\\\\#{i.id}&record_name=\\\\#{patient.hn}&return=\\\\#{request.fullpath}\",:class=>\'btn btn-small\')\r\n            show += \' \'\r\n            show += link_to(\'Print\',\"../\\\\#{name.camelize}/print?id=\\\\#{i.id}&return=\\\\#{request.fullpath}\",:target=>\'_blank\' ,:class=>\'btn btn-small\')\r\n    \r\n            {:name=>name,:records=>rr.html_safe,:date=>date,:show=>show,:module_name=>name}\r\n        end\r\n    \r\n    %>\r\n    <div class=\"tabbable tabs-left\" style=\"border:1px solid #ccc; -moz-border-radius: 5px;\r\n    border-radius: 5px;\">\r\n    <ul class=\"nav nav-tabs\" style=\"background:#F4F4F4; -moz-border-radius: 5px;border-radius: 5px;\">\r\n    <li class=\"active\" ><a href=\"#tab_dashboard\" data-toggle=\"tab\" style=\"font-size:14px; padding:10px\" >Dashboard</a></li>\r\n    <%\r\n    for g in groups \r\n       services = g[:actions].collect{|i| [@current_project.get_service(i[:service]), i[:name]]}.compact\r\n       %> \r\n    <li class=\"\" ><span style=\"font-size:14px;padding:10px\"><%=g[:name]%></span></li>\r\n       <%\r\n       for st in services\r\n       s = st[0]\r\n       name = st[1]\r\n       n = modules.collect{|i| i if i[:module_name]==s.name }.compact.size\r\n    %>\r\n    <li class=\"<%#\'active\' if s == services[0]%>\" style=\"border:0px solid;width:150px;overflow:hidden\"><a href=\"#tab_<%=s.id%>\" data-toggle=\"tab\" style=\"font-size:12px; padding:10px\">- <%=name%>\r\n    <%= \"(\\\\#{n})\" if n>0 %>\r\n    </a></li>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n    </ul>\r\n    \r\n    \r\n    <div class=\"tab-content span8\" style=\"border:0px solid;float:left; clear:none;\">\r\n    <div class=\"tab-pane  <%= \'active\' if true %>\" style=\"border:0px solid;   \" id=\"tab_dashboard\">\r\n    <br/><h3>Dashboard</h3>\r\n    \r\n    <div style=\'float:right;margin-top:-30px\'>\r\n    <%\r\n      title_map = {}\r\n      services.each {|i| \r\n      \r\n      title_map[i[0].name] = i[1]\r\n      \r\n      }  \r\n      \r\n      \r\n    %>\r\n    <%# link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class %>\r\n    </div>\r\n    \r\n    <%= tabular :data=> modules,:model=>[:name,:records,:show] do |row,out|\r\n    out[0] = title_map[row[:name]]\r\n    out\r\n    end%>\r\n    \r\n    </div>\r\n    <%# title_map%>\r\n    \r\n    <%\r\n    for g in groups \r\n       services = g[:actions].collect{|i| @current_project.get_service i[:service]}.compact\r\n       for s in services\r\n    %>\r\n    <div class=\"tab-pane  <%# \'active\' if s==services[0] %>\" id=\"tab_<%=s.id%>\"  style=\"border:0px solid;\">\r\n    <br/><h3><%=s.title%></h3>\r\n    \r\n    <%=link_to \'Create\',\"../\\\\#{s.name.camelize}/create?patient_id=\\\\#{patient.id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.id}&return=\\\\#{request.fullpath}\" ,:class=>bt_class ,:style=>\'float:right;margin-top:-30px\'%>\r\n    \r\n    <%= tabular :data=> modules.collect{|i| i if i[:module_name]==s.name }.compact ,:model=>[:title,:records,:show] do |row,out|\r\n    out[0] = s.title\r\n    out\r\n    end%>\r\n    \r\n    </div>\r\n    <% end %>\r\n    <% end %>\r\n    \r\n   </div>\r\n   </div>\r\n    \r\n    \r\n    \r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n    <br/><br/>\r\n    \r\n    \r\n    <script>\r\n    $(\'title\').html(\'<%=patient.hn%> <%=patient.first_name%> <%=patient.last_name%>\')\r\n    </script>\r\n    \r\n     \r\n',NULL,NULL,NULL,'2019-01-02 01:03:35','2019-01-02 01:03:35','patient_record',''),(3846,'document_name',1523,1,'\'add_chemotherapy\'',NULL,NULL,NULL,'2019-01-02 01:20:05','2019-01-02 01:20:05',NULL,NULL),(3847,'document_name',1524,1,'\'add_endocrinerx\'',NULL,NULL,NULL,'2019-01-02 01:30:24','2019-01-02 01:30:24',NULL,NULL),(3848,'document_name',1525,1,'\'add_antiher2\'',NULL,NULL,NULL,'2019-01-02 01:44:57','2019-01-02 01:44:57',NULL,NULL),(3849,'index',1526,2,'\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Solution \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n    <center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE</b></center><br/>\r\n    <%= render :inline=>this.module %>\r\n</div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n<% \r\n\r\n    model = get_model\r\n    patient_model = model[:patient]\r\n    patient_module_model = model[:patient_module]\r\n    modules = @context.get_projects_by_abstract \'ehr.emr\' \r\n%>\r\n\r\n\r\n\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n      Information \r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center>  News and Update\r\n  \r\n  <hr />\r\n\r\nปัจจุบันระบบ เปิดให้ทดสอบใช้งานแล้วครับ สามารถทดสอบลงข้อมูลได้แล้ว และเมื่อระบบเรียบร้อย จะทำการ reset data ทั้งหมด จึงแจ้งมาเพื่อทราบ\r\n<br /><br />E.S.M. Developer Team<br /><br />\r\n\r\n<a href=\"/esm/tsco_bc/breast_cancer/manual tsco-bc.pdf\" target=\"_blank\">  สามารถ Download คู่มือการใช้งานระบบ</a>\r\n  </center>\r\n</div>\r\n</div>  \r\n</div>  \r\n</div>  \r\n\r\n',NULL,NULL,NULL,'2019-01-02 02:21:35','2019-01-02 02:21:35','',''),(3850,'export_csv',729,3,'<%\r\n    require \'csv\'\r\n    \r\n    doc = get_document this.document_name\r\n    # field map\r\n    fm = {}\r\n    # field list\r\n    fl = []\r\n    # document field\r\n    df = {}\r\n    doc.fields.each do |i|\r\n        ft = i[:field_type]\r\n        if ft == \'clear\' or ft == \'section\' or ft == \'html\' or ft == \'chapter\' or ft == \'tab\'\r\n            next\r\n        end\r\n        \r\n        cn = i[:column_name].to_sym\r\n        fl << cn\r\n        fm[cn] = i.to_h\r\n        \r\n        if i[:lov_type] == \'pair\'\r\n            tmp = {}\r\n            tmp[:name] = i[:name]\r\n            tmp[:list] = []\r\n            tmp[:pair] = {}\r\n            lov = i[:lov].to_s.split(\'\\r\\n\')\r\n            lov.each do |j|\r\n                x = j.split(\'|\')\r\n                tmp[:pair][x[0].strip] = x[1].strip\r\n                tmp[:list] << x[1].strip\r\n            end\r\n            \r\n            fm[cn][:list] = tmp[:list]\r\n            fm[cn][:pair] = tmp[:pair]\r\n        end\r\n    end\r\n    # field keys\r\n    fk = [:_id]\r\n    fk = fk + fm.keys\r\n    \r\n    dat = get_model[this.document_name.to_sym].all\r\n    \r\n    dat.each do |i|\r\n        fk.each do |j|\r\n%>\r\n<%= i[j] %>|<% end %>\r\n\r\n<br>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2019-01-02 06:22:36','2019-01-02 06:22:36','export_csv',''),(3851,'layout',1473,4,'<!DOCTYPE html>\r\n<html lang=\"en\">\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n  \r\n\r\n			<!-- Content -->\r\n			<%\r\n				p = {}\r\n				project_params = @current_project.get_params if @current_project \r\n				p = project_params if project_params\r\n				title = (p[\'app_title\']and p[\'app_title\']!=\'\')?p[\'app_title\']:\"EMR-LIFE : Medical Records Service Provider\"\r\n				bg = (p[\'app_bg_style\']and p[\'app_bg_style\']!=\'\')?p[\'app_bg_style\']:\"#fff\"\r\n				logo = (p[\'app_logo_url\']and p[\'app_logo_url\']!=\'\')?p[\'app_logo_url\']:\'/esm_core/banner1.png\'\r\n				theme = (p[\'app_theme\']and p[\'app_theme\']!=\'\')?p[\'app_theme\']:\