=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\">\r\n\r\n\r\n\r\n<%= this.display.html_safe %>\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<script>\r\n\r\nfunction getScore(name){\r\n    v = $(\"#data-\"+name);\r\n    if(v.val()){\r\n        return parseInt(v.val());\r\n    }\r\n    return 0;\r\n}\r\n\r\nfunction refresh_point(){\r\n           \r\n        \r\n        \r\n    \r\n    score = getScore(\"motor\")+getScore(\"respiration\") + getScore(\"conscious\") + getScore(\"sbp\") + getScore(\"o2sat\"); \r\n            \r\n            $(\"#data-point\").val(score);       \r\n}\r\n\r\nfunction post_scope_setup(){\r\n$(\"#data-point\").change(refresh_point);\r\n$(\"#data-motor\").change(refresh_point); \r\n$(\"#data-respiration\").change(refresh_point);\r\n$(\"#data-conscious\").change(refresh_point);\r\n$(\"#data-sbp\").change(refresh_point);\r\n$(\"#data-o2sat\").change(refresh_point);\r\n\r\n\r\n}\r\n</script>',NULL,NULL,NULL,'2019-01-14 09:06:44','2019-01-14 09:06:44','show',''),(3896,'document_name',1544,1,'\'customer\'',NULL,NULL,NULL,'2019-01-15 04:13:22','2019-01-15 04:13:22',NULL,NULL),(3897,'document_name',1545,1,'\'site\'',NULL,NULL,NULL,'2019-01-15 05:00:39','2019-01-15 05:00:39',NULL,NULL),(3898,'document_name',1546,1,'\'item\'',NULL,NULL,NULL,'2019-01-15 06:38:05','2019-01-15 06:38:05',NULL,NULL),(3899,'document_name',1547,1,'\'item_link\'',NULL,NULL,NULL,'2019-01-15 0