),name:doc.module_name};}\',\r\n          :reduce=>\'function(curr,result){result.count++;}\',\r\n          :initial=>{:count=>0},\r\n          :finalize=>\'function(result){result.month=result.month}\',\r\n          :cond=>{:date=>{\'$gte\'=>Time.now.at_beginning_of_year()}}})\r\n          \r\n          \r\n        columns=[]\r\n        \r\n    mlabels = %w{Jan Feb Mar Apr May Jun July Aug Sep Oct Nov Dec}    \r\n   \r\n    map = {}\r\n    data = []\r\n         \r\n    if list.size>0    \r\n    for i in list\r\n    columns[i[\'month\'].to_i]= mlabels[i[\'month\'].to_i]\r\n    name = i[\'name\'].split(\'#\')[1]\r\n    map[name] = {\'name\'=>name.humanize, \'data\'=>[]} unless map[name] \r\n    map[name][\'data\'][i[\'month\'].to_i] = i[\'count\'].to_i\r\n    end\r\n    end\r\n    map.each_pair do |k,v|\r\n    if k!=\'appointment\'\r\n        data<<v end %><%\r\n    \r\n    end\r\n    \r\n    \r\n    \r\n   \r\n    columns = mlabels\r\n\r\n%>\r\n\r\n<%#list.inspect%>\r\n<div class=\'span12\' style=\'background:#FFF;padding:10px\'>\r\n<h3>Summary</h3>\r\n\r\n<%\r\n\r\n%>\r\n\r\n<div id=\"chart\" style=\"border:1px solid;width:100%;min-height:300px\">\r\n</div>\r\n\r\n\r\n<br/>\r\n<a href=\"../Colposcopy/export_select\" class=\"btn\">Export data</a>\r\n</div>\r\n\r\n\r\n\r\n\r\n            <script>\r\n                function createChart() {\r\n                    $(\"#chart\").kendoChart({\r\n                        theme: $(document).data(\"kendoSkin\") || \"default\",\r\n                        title: {\r\n                            text: \"Records by Months\"\r\n                        },\r\n                        legend: {\r\n                            position: \"bottom\"\r\n                        },\r\n                        chartArea: {\r\n                            background: \"\"\r\n                        },\r\n                        seriesDefaults: {\r\n                            type: \"column\"\r\n                        },\r\n                        series: <%=data.to_json.html_safe %>\r\n                        ,\r\n                        valueAxis: {\r\n                            labels: {\r\n                                format: \"{0}\"\r\n                            }\r\n                        },\r\n                        categoryAxis: {\r\n                            categories: <%=columns.to_json.html_safe%>\r\n                        },\r\n                        tooltip: {\r\n                            visible: true,\r\n                            format: \"{0}\"\r\n                        }\r\n                    });\r\n                }\r\n\r\n                $(document).ready(function() {\r\n                    setTimeout(function() {\r\n                        createChart();\r\n                    }, 400);\r\n                });\r\n            </script>\r\n\r\n\r\n',NULL,NULL,NULL,'2019-01-24 03:41:02','2019-01-24 03:41:02','report',''),(3906,'export_select',876,3,'\r\n<%\r\n\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n\r\n  @document = get_document(this.document_name)\r\n\r\n  doc = @document\r\n  \r\n  fromdate=\"\"\r\n  todate=\"\"\r\n  fd = Time.now\r\n  td = Time.now\r\n  if params[:fromdate]\r\n      fromdate = params[:fromdate] \r\n      t = fromdate.split(\"/\").reverse.collect{|i| i.to_i}\r\n      fd = Date.new t[0],t[1],t[2]\r\n      fd = Date.to_mongo(fd)\r\n  end\r\n  if params[:todate]\r\n      todate = params[:todate] \r\n      t = todate.split(\"/\").reverse.collect{|i| i.to_i}\r\n      td = Date.new t[0],t[1],t[2]\r\n      td = Date.to_mongo(td)\r\n\r\n  end\r\n\r\n  data = get_model(this.document_name).where(:created_at.gte=>fd.at_beginning_of_day,:created_at.lt=>td.end_of_day).all :sort=>\'created_at desc\', :limit=>4310, :offset=>0\r\n#   data = get_model(this.document_name).where(:lmp.gte=>fd.at_beginning_of_day,:lmp.lt=>td.end_of_day).all :sort=>\'created_at desc\', :limit=>4310, :offset=>0\r\n#   data = get_model(this.document_name).all :sort=>\'created_at desc\', :limit=>1, :offset=>0\r\n\r\n  \r\n   lfields = @document.fields\r\n   fields = lfields.collect{|i| [i.column_name,i.name,i] unless Document.visual_types.index(i.field_type) }.compact!\r\n   fields << \'created_at\'\r\n   fields << \'updated_at\'\r\n   \r\n   models = get_model\r\n   many_list = {}\r\n   \r\n   for f in fields\r\n    field = f[2]\r\n       \r\n    if f.size ==3 and field.field_type==\'relation_many\'\r\n       p = eval(\"{\\\\#{field.params}}\")[:relation][:document]\r\n       many_list[field.column_name] =  {:name=>field.column_name,:doc=>p, :model=>models[p.to_sym],:records=>[] }\r\n        \r\n    end\r\n   \r\n   \r\n   end\r\n   \r\n   \r\n   for i in data\r\n   begin\r\n        for j in many_list.keys\r\n        \r\n            if i[j] and i[j].size > 0 \r\n               \r\n               many_list[j][:records]+=i[j]\r\n                \r\n            end\r\n        \r\n        end\r\n        \r\n        rescue\r\n        \r\n    end\r\n    \r\n   end\r\n   \r\n   many_list.each_pair do |k,v|\r\n \r\n      many_document = get_document(many_list[k][:doc])\r\n      mfields = []\r\n      mfields = many_document.fields.collect{|i| [i.column_name,i.name]  } # if many_document\r\n\r\n      \r\n\r\n      records = v[:model].find v[:records]\r\n      m = {}\r\n      for i in records\r\n        \r\n        m[i.id] = i \r\n      end\r\n       \r\n      many_list[k][:map]=m\r\n      many_list[k][:fields]=mfields\r\n      \r\n \r\n   end\r\n   \r\n   \r\n%><%=include_header%>\r\n\r\n\r\n<h2><%= this.table_name  %></h2>\r\n<form method=\"post\">\r\n<%#=data.inspect%>\r\nfrom <%= text_field_tag \'fromdate\',fromdate,:id=>\'fromdate\',:onchange=>\'alert\',:style=>\'width:120px\' %>\r\nto <%= text_field_tag \'todate\',todate,:id=>\'todate\',:onchange=>\'alert\',:style=>\'width:120px\' %>\r\n<button class=\"btn\" id=\"btn_confirm\" type=\"submit\"> Query</button>\r\n</form>\r\n<script>\r\n$(\"#fromdate\").kendoDatePicker().val(\"<%=fromdate%>\");\r\n$(\"#todate\").kendoDatePicker().val(\"<%=todate%>\");\r\n</script>\r\n<%if request.post?%>\r\n<%= link_to \'Download\', \"#\", :id=>\'btnExport\', :class=>\'btn\' %>\r\n<%end%>\r\n<hr />\r\n<br />\r\n<%if request.post?%>\r\n<div id=\"data\">\r\n<table border=\"1\">\r\n<tr><th>HN</th><th>Name</th><th>Gender</th><th>Birth Date</th><th>Age</th><th>Record date</th>\r\n\r\n<%\r\nfor i in fields \r\n%><th><%= i[1] %></th>\r\n<% end %>\r\n</tr>\r\n\r\n<% for i in data \r\n begin\r\n     @record = i\r\n\r\n    age = 0\r\n    hn = nil\r\n    \r\n    p = @patient_model.new\r\n    m = @module_model.collection.find(:module_id=>i.id).first\r\n    if m \r\n    \r\n    patient = @patient_model.collection.find(\'_id\'=>m[\'patient_id\']).first\r\n    if patient\r\n    bdate = 0\r\n    bdate = patient[\'birth_date\'].to_datetime.to_i if patient[\'birth_date\']\r\n    age = (m[\'created_at\'].to_datetime.to_i - bdate )/3600/24/365\r\n   \r\n    p = patient\r\n    p[\'record_date\'] = m[\'date\']\r\n    \r\n    end\r\n   end\r\n    \r\n    \r\n%>\r\n<tr>\r\n<td><%=p[\'hn\'] %></td><td><%=p[\'first_name\']%> <%=p[\'last_name\']%></td><td><%=p[\'gender\']%></td><td><%=p[\'birth_date\'].strftime(\'%d/%m/%Y\') if p[\'birth_date\'] %></td><td><%=age%></td><td><%=p[\'record_date\'].strftime(\'%d/%m/%Y\') if p[\'record_date\']%></td>\r\n\r\n<%\r\n    @document = doc\r\n    @fields = @document.fields\r\n    \r\n    for j in fields \r\n    \r\n    if i[j[0]]\r\n        \r\n    if j[2].field_type!=\'relation_many\'\r\n%>\r\n<td><%= render_value j[0] %></td>\r\n<% else \r\n\r\n m = many_list[j[0]]\r\n \r\n %>\r\n<td><table>\r\n        <!-- <tr>\r\n            <% for x in m[:fields] %>\r\n            <td>\r\n            <%= x[1]%>\r\n            </td>\r\n            <% end %>\r\n        </tr>-->\r\n            \r\n    <% for k in i[j[0]]\r\n       \r\n        r = m[:map][k]\r\n        %>\r\n        <tr>\r\n            <% for x in m[:fields] %>\r\n            <td>\r\n                <%=x[1]%>=<%=r[x[0].to_s]%>\r\n            </td>\r\n            <% end %>\r\n        </tr>\r\n    <% end %>\r\n    </table>\r\n</td>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n<% else %>\r\n<td>.</td>\r\n<% end %>\r\n<% end %>\r\n\r\n\r\n\r\n</tr>\r\n<% \r\nrescue\r\n\r\nend\r\n\r\nend %>\r\n\r\n</table>\r\n  \r\n</div>\r\n<%end #request.post%>\r\n<script>\r\n    $(\"#btnExport\").click(function(e) {\r\n    window.open(\'data:application/vnd.ms-excel,\' + $(\'#data\').html());\r\n    e.preventDefault();\r\n});\r\n</script>\r\n   \r\n\r\n',NULL,NULL,NULL,'2019-01-24 03:56:09','2019-01-24 03:56:09','export_select',''),(3907,'document_name',1552,1,'\'pathological_staging\'',NULL,NULL,NULL,'2019-01-29 05:09:05','2019-01-29 05:09:05',NULL,NULL),(3908,'document_name',1553,1,'\'add_endocrinerx_ebc\'',NULL,NULL,NULL,'2019-01-29 05:34:28','2019-01-29 05:34:28',NULL,NULL),(3909,'document_name',1554,1,'\'patient\'',NULL,NULL,NULL,'2019-01-29 08:28:33','2019-01-29 08:28:33',NULL,NULL),(3910,'search_result',1554,3,'<% \r\n\r\nrequire \'time_diff\'\r\n\r\n    models = get_model  \r\n\r\n    @document = get_document(this.document_name)\r\n    model = models[:patient]\r\n    att_model = models[:attachment]\r\n    patient = model.find(params[:id])\r\n    date = Time.now.to_datetime\r\n    if patient \r\n    birth_date = patient.birth_date \r\n    year = month = day = \'0\'\r\n    if date and birth_date\r\n    t = date-birth_date    \r\n    diff = Time.diff(date, birth_date)\r\n    year = diff[:year]\r\n    month = diff[:month]\r\n    day = diff[:day]\r\n    \r\n    #year = (t/365).to_i\r\n    #t%=365\r\n    #month = (t/30).to_i\r\n	#t%=30\r\n	#day = t.to_i\r\n    