ords = model.all(params[:search][:criteria])\r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n       records = model.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n    end\r\n   \r\n%>\r\n\r\n<%= tabular :model=>labels, :data=>records do |i,out|\r\n\r\nfields.each_with_index do |f,index|\r\n\r\nout[index] = render(:partial=>\'/esm_documents/show_value.html\',:locals=>{:field=>f,:record=>i})\r\n\r\nend\r\n#out<<link_to(\'<i class=\"splashy-zoom\"></i>Show\'.html_safe, url(\"show\",:id=>i.id),:class=>\'btn btn-info btn-mini\' )\r\nout<<link_to(\'<i class=\"splashy-pencil_small\"></i>Edit\'.html_safe, url(\"user_edit\",:id=>i.id),:class=>\'btn btn-warning btn-mini\')\r\nout<<link_to(\'<i class=\"splashy-error_x\"></i>Delete\'.html_safe, url(\"user_destroy\",:id=>i.id),:class=>\'btn btn-danger btn-mini\',:data=>{:confirm=>\'Are you sure?\'})\r\nout\r\nend\r\n%>\r\n<% if page %>\r\n    Pages <%= link_to \'<<\', \"index?page=0\"   %> |\r\n    <% (n.to_f/rows).ceil.times do |i| \r\n    if i > page -5 and i<page+5\r\n        if i!=page\r\n    %><%= link_to i+1, \"index?page=\\\\#{i}\" %> |\r\n        <% else %>\r\n            <%= i+1 %> |\r\n        <% end %>\r\n    <% end %>\r\n<% end %>\r\n<%= link_to \'>>\', \"index?page=\\\\#{(n.to_f/rows).ceil-1}\" %>\r\n<%\r\n    last = offset+rows\r\n    last = n if last > n\r\n%>\r\n<span style=\"float:right\"><%=offset+1%>-<%=last%> of <%=n%></span>\r\n<div class=\"clear\"></div>\r\n<% end %>',NULL,NULL,NULL,'2019-01-31 08:25:22','2019-01-31 08:25:22','user_list',''),(3915,'user_edit',1555,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>User Management</h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%\r\n  r_select = get_model(\'role\').all.collect{|i| [i.name,i.id]}\r\n  h_select = get_model(\'member\').all.collect{|i| [i.hospital,i.id]}\r\n  model = get_model(\'user\')\r\n  record = {}\r\n  record[:_id] = \'\'\r\n  record = model.find(params[:id]) if params[:id] and params[:id]!=\'\'\r\n  %><%#=record.inspect%><%\r\n  m_model = get_model(\'member\').where(:users=>params[:id]).first \r\n  hos = \"\"\r\n  hos = m_model.id if m_model\r\n  if request.post?\r\n    if params[:id]==\'\'\r\n        record = model.create \r\n    else\r\n        record = model.find(params[:id])\r\n    end\r\n    #doc = get_document \'user\'\r\n    # record = doc.record_update(model,params,record)\r\n    record[:login] = params[:record][:login_name] if params[:record][:login_name]\r\n    record[:email] = params[:record][:email] if params[:record][:email]\r\n    record[:name] = params[:record][:name] if params[:record][:name]\r\n    if params[:record][:password] and params[:record][:password]!=\'\'\r\n        salt = User.random_string(10) \r\n        hashed_password = User.encrypt(params[:record][:password], salt)\r\n        record[:hashed_password] = hashed_password\r\n        record[:salt] = salt\r\n    end\r\n    record[:role] = BSON::ObjectId.from_string(params[:role]) if params[:role]\r\n    record.save\r\n    flash[:notice]=\'New record has been created\'\r\n    m_model = get_model(\'member\').where(:users=>params[:id]).first\r\n    if m_model \r\n        u = []\r\n        u = m_model.users if m_model.users \r\n        u.delete(record.id)\r\n        m_model[:users]=u\r\n        m_model.save\r\n        %><%#=\'test=\'+m_model.users.to_s%><br><%\r\n    end\r\n    m_model = get_model(\'member\').find(params[:member])\r\n    if m_model \r\n        u = []\r\n        u = m_model.users if m_model.users\r\n        u << record.id\r\n        m_model[:users]=u\r\n        m_model.save\r\n        %><%#=\'new \'+m_model.users.to_s%><br><%\r\n    end\r\n\r\n%>\r\n<h3>Save sucessful!</h3>\r\n<%#=record.inspect%><br>\r\n<%#=params.inspect%><br>\r\n<%#=m_model.inspect%><br>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"user_edit?id=<%=record.id%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n<%#=r_select.inspect%>\r\n\r\n<div class=\"accordion-body collapse in\" id=\"collapseOne1\">\r\n	<div class=\"accordion-inner\">\r\n	    <div class=\"form-horizontal well\">\r\n<%= form_for :record,:url=>url(\'user_edit\',:id=>record[:_id]) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<div class=\"control-group\">\r\n	<label class=\"control-label\">Login Name</label>\r\n	<div class=\"controls\">\r\n	    <%= f.text_field :login_name, :class=>\'span10\', :value=>record[:login] %>\r\n		<span class=\"help-block\">no space, special characters</span>\r\n	</div>\r\n</div>\r\n<div class=\"control-group\">\r\n	<label class=\"control-label\">Password</label>\r\n	<div class=\"controls\">\r\n	    <%#= f.password_field :password, :class=>\'span10\' %>\r\n	    <%= f.password_field :password, :class=>\'span10\' %>\r\n		<span class=\"help-block\">account password</span>\r\n	</div>\r\n</div>\r\n<div class=\"control-group\">\r\n	<label class=\"control-label\">Full Name</label>\r\n	<div class=\"controls\">\r\n	    <%= f.text_field :name, :class=>\'span10\', :value=>record[:name] %>\r\n		<span class=\"help-block\">no space, special characters</span>\r\n	</div>\r\n</div>\r\n<div class=\"control-group\">\r\n	<label class=\"control-label\">E-Mail</label>\r\n	<div class=\"controls\">\r\n	    <%= f.text_field :email, :class=>\'span10\', :value=>record[:email] %>\r\n		<span class=\"help-block\">email account</span>\r\n	</div>\r\n</div>\r\n<div class=\"control-group\">\r\n	<label class=\"control-label\">Hospital</label>\r\n	<div class=\"controls\">\r\n	    <%=select_tag :member, options_for_select(h_select,hos)%>\r\n		<span class=\"help-block\">user group</span>\r\n	</div>\r\n</div>\r\n<div class=\"control-group\">\r\n	<label class=\"control-label\">Role</label>\r\n	<div class=\"controls\">\r\n	    <%=select_tag :role, options_for_select(r_select,record[:role])%>\r\n		<span class=\"help-block\">user authentication</span>\r\n	</div>\r\n</div>\r\n<%#= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> <%=record[:_id]==\'\'?\'Create\':\'Update\'%></button> |\r\n<%= link_to \'Back\', url(\'user\') %>\r\n<% end %>\r\n</div></div></div>\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2019-01-31 08:49:08','2019-01-31 08:49:08','user_edit',''),(3916,'destroy',1383,3,'<%\r\n\r\n\r\n  model = get_model(this.table_name)\r\n  \r\n  \r\n  @record = model.find(params[:id])\r\n  project_id = @record.project_id\r\n  @record.destroy \r\n  \r\n  \r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=../Project/show?id=<%=project_id%>\">',NULL,NULL,NULL,'2019-02-01 07:52:33','2019-02-01 07:52:33','destroy',''),(3917,'chem_config',1278,3,'<%\r\n    models=get_model\r\n    \r\n    map = {}\r\n    \r\n    labs = models[:pl_product].where(:group_code=>\'LAB\',:vendor_code=>{\'$ne\'=>nil} ).all\r\n    \r\n    for i in labs\r\n    \r\n        map[i.id] = i\r\n    \r\n    end\r\n\r\n    labs = models[:pl_product].where(:vendor_code=>{\'$in\'=>[nil,\'\']},:group_code=>\'LAB\',:code=>{\'$ne\'=>\'SET-CHEM\'}).sort(:code).all\r\n\r\n    boms = models[:pl_product_bom].where(:product_id=>labs.collect{|i| i.id}).all\r\n    \r\n    bmap = {}\r\n    \r\n    \r\n    \r\n    for i in boms\r\n    \r\n    \r\n       bmap[i.product_id] = {} unless bmap[i.product_id]\r\n       p = map[i.sub_product_id]\r\n        if p \r\n            bmap[i.product_id][p.vendor_code] = p\r\n        end\r\n    end\r\n    \r\n    \r\n    \r\n    iselect = {} \r\n    \r\n    #sheet = models[:pl_sheet].find params[:id]\r\n    \r\n    project = models[:project].find params[:id]\r\n        \r\n    if project \r\n        # p = models[:pl_product].where(:code=>\'SET-CHEM\').first\r\n        # if p \r\n        #     period_product =  models[:pl_period_product].where(:product_id=>p.id, :sheet_id=>sheet.id).first\r\n            \r\n        #     period_product =  models[:pl_period_product].find(params[:idx])\r\n            \r\n            \r\n        #     if period_product\r\n                \r\n        #         records = models[:pl_period_product_bom].where(:period_product_id=>period_product.id).all\r\n        #         for i in records\r\n                \r\n        #             iselect[i.sub_product_id] = true\r\n                \r\n        #         end\r\n\r\n        #     end\r\n        # end\r\n        project_item = models[:project_item].find(params[:idx])\r\n        if project_item\r\n        records = models[:pl_additional_product_bom].where(:project_item_id=>project_item.id).all\r\n        for i in records\r\n                \r\n                    iselect[i.sub_product_id] = true\r\n                \r\n        end\r\n    end\r\n         \r\n    end\r\n    \r\n%>\r\n\r\n<%=form_for :record, :url=>\"protocol_chem?id=\\\\#{params[:id]}&update=config_chem_content&idx=\\\\#{params[:idx]}\", :data=>{:remote=>true} do |f|  %>\r\n\r\n\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" data-dismiss=\"modal\">×</button>\r\n									<h3>Chem Configure</h3>\r\n								</div>\r\n<div class=\"modal-body\">\r\n\r\n\r\n<%=hidden_field_tag :project_id, params[:id] %>\r\n<%\r\n   \r\n%>\r\n<%= text_field_tag :search_item,\"\" %>\r\n\r\n<table class=\"table table-sm\" >\r\n<thead>\r\n    <tr>\r\n        <th>\r\n            Code\r\n        </th>\r\n        <th>\r\n            Description\r\n        </th>\r\n        \r\n        <th>\r\n            Price\r\n        </th>\r\n        \r\n        <th>\r\n            Select    \r\n        </th>\r\n        \r\n        <th>\r\n            HOS\r\n        </th>\r\n        \r\n        <th>\r\n            HIV/NAT\r\n        </th>\r\n\r\n    </tr>\r\n</thead>\r\n<% for i in labs %>\r\n<tr id=\"<%=i.id%>\" class=\"rowx\">\r\n    <td>\r\n        <%=i.code%>\r\n    </td>\r\n    \r\n    <td>\r\n        <%=i.name%>\r\n    </td>\r\n    \r\n    <td>\r\n        <%= i.price %>\r\n    </td>\r\n    <td>\r\n        <%= check_box_tag \"p[]\", i.id , iselect[i.id]  %>\r\n    </td>\r\n    <td>\r\n    <%\r\n    \r\n    \r\n        if bmap[i.id] and  b = bmap[i.id][\'HOS\'] and b \r\n    %>\r\n        <%= b.cost %>\r\n        \r\n    <% else %>\r\n        - \r\n    <% end %>\r\n    </td>\r\n    \r\n    \r\n    <td>\r\n      <%\r\n      \r\n        if bmap[i.id] and  b = bmap[i.id][\'CRL01\'] and b\r\n    %>\r\n        <%= b.cost %>\r\n        \r\n    <% else %>\r\n        - \r\n    <% end %>\r\n    </td>\r\n    \r\n    \r\n    \r\n    \r\n</tr>\r\n<% end %>    \r\n</table>\r\n\r\n</div>\r\n\r\n<script>\r\n    $(\'#search_item\').keyup(function(){\r\n        list = <%= labs.to_json.html_safe %>\r\n        v = $(this).val()\r\n        if(v.length>0){\r\n            reg =  new RegExp(v,\'i\');\r\n            $(\'.rowx\').hide();\r\n            for(var ix in list){\r\n                i = list[ix];\r\n                \r\n                var res = i[\'name\'].match(reg);\r\n                if(res!=null){\r\n                    $(\'#\'+i[\'id\']).show();\r\n                }\r\n                \r\n            }\r\n            \r\n        }else{\r\n              $(\'.rowx\').show();\r\n        }\r\n    })\r\n</script>\r\n								<div class=\"modal-footer\"><%= f.submit \'Update\' ,:data=>{:disable_with=>\'Updating..\'}, :class=>\'btn btn-info\'%>\r\n									<a href=\"#\" class=\"btn\" data-dismiss=\"modal\">Close</a>\r\n								</div>\r\n								\r\n<% end %>		\r\n\r\n<script>\r\n    refresh_remote()\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2019-02-01 16:49:07','2019-02-01 16:49:07','chem_config',''),(3918,'protocol_chem',1278,3,'<%\r\n    models = get_model \r\n    \r\n    \r\n    if request.post?\r\n        \r\n        project = models[:project].find params[:project_id]\r\n        \r\n        if project \r\n          \r\n                # period_product =  models[:pl_period_product].where(:product_id=>p.id, :sheet_id=>sheet.id).first\r\n                # period_product =  models[:pl_period_product].find(params[:idx])\r\n                \r\n                   project_item = models[:project_item].find(params[:idx])\r\n               \r\n                  if project_item\r\n                    \r\n                   records = models[:pl_additional_product_bom].where(:project_item_id=>project_item.id).all\r\n       \r\n         \r\n                #   records = models[:pl_period_product_bom].where(:period_product_id=>period_product.id).all\r\n                   for i in records\r\n                    i.destroy\r\n                    end\r\n                    \r\n                    \r\n                    for i in params[:p]\r\n                 \r\n                        records = models[:pl_additional_product_bom].create(:project_item_id=>project_item.id, :sub_product_id=>i)\r\n\r\n                    end\r\n                    \r\n                \r\n                    \r\n                    \r\n                   \r\n                   \r\n            end\r\n        end\r\n        \r\n    end\r\n    \r\n%>\r\n\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Project/show?id=<%=project.id%>&active=protocol2\" />\r\n\r\n<script>\r\n\r\n    $(\'#config_chem\').modal(\'hide\')\r\n</script>',NULL,NULL,NULL,'2019-02-01 16:50:22','2019-02-01 16:50:22','protocol_chem',''),(3919,'document_name',1556,1,'\'pl_additional_product_bom\'',NULL,NULL,NULL,'2019-02-01 17:10:02','2019-02-01 17:10:02',NULL,NULL),(3920,'form',1552,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    \r\n    $(document).ready(function(){\r\n       \r\n      var nlist = null;\r\n      var mlist = null;\r\n       \r\n      function resolve(){\r\n          \r\n          v = $(\'#data-staging_type\').val();\r\n          \r\n          nl = [];\r\n          \r\n           $(\'#data-patho_n\').html(\"\");\r\n           $(\'#data-patho_m\').html(\"\");\r\n           \r\n           \r\n           \r\n           \r\n        //   console.log(nlist.length)\r\n        //   for(var  id=0 ; inlist.length ){\r\n        //       i = id\r\n        //       console.log(id[0]);\r\n        //     //   alert(i)\r\n              \r\n        //   }\r\n          \r\n          nlist.each(function(){\r\n            vo = $(this)\r\n            if(vo.val().charAt(0)==v||vo.val().charAt(0)==\'M\'){\r\n                $(\'#data-patho_n\').append(vo)\r\n            }\r\n          })\r\n          \r\n          mlist.each(function(){\r\n            vo = $(this)\r\n            if(vo.val().charAt(0)==v||vo.val().charAt(0)==\'M\'){\r\n                $(\'#data-patho_m\').append(vo)\r\n            }\r\n          })\r\n          \r\n        //   $(\'#data-patho_n\').html(nl);  \r\n          \r\n          \r\n          //$(\'#data-patho_n\').html(mlist);  \r\n          \r\n            \r\n          \r\n      }\r\n      \r\n      function cal(){\r\n          t = $(\'#data-patho_t\').val();\r\n          n = $(\'#data-patho_n\').val();\r\n          m = $(\'#data-patho_m\').val();\r\n          \r\n          k = \"\"+t+\"-\"+n.substring(1);\r\n          \r\n          stages = []\r\n          stages.push([\'Tis-cN0\',\'0\'])\r\n          stages.push([\'T1-cN0\',\'IA\'])\r\n          stages.push([\'T0-cN1mi\',\'IB\'])\r\n          stages.push([\'T1-cN1mi\',\'IB\'])\r\n          \r\n          stages.push([\'T0-cN1\',\'IIA\']) \r\n          stages.push([\'T1-cN1\',\'IIA\']) \r\n          stages.push([\'T2-cN0\',\'IIA\']) \r\n          \r\n          stages.push([\'T2-cN1\',\'IIB\']) \r\n          stages.push([\'T3-cN0\',\'IIB\'])     \r\n          \r\n          stages.push([\'T0-N1\',\'IIIA\']) \r\n          stages.push([\'T1-N2\',\'IIIA\']) \r\n          stages.push([\'T2-N3\',\'IIIA\'])          \r\n\r\n          stages.push([\'T4b-N0\',\'IIIB\']) \r\n          stages.push([\'T4b-N1\',\'IIIB\']) \r\n          stages.push([\'T4a-N2\',\'IIIB\'])  \r\n          stages.push([\'T3-N3\',\'IIIB\'])   \r\n\r\n          stages.push([\'T4b-N2\',\'IIIC\']) \r\n          stages.push([\'T4b-N3\',\'IIIC\'])  \r\n          stages.push([\'T4a-N3\',\'IIIC\'])           \r\n\r\n\r\n\r\n          \r\n          stage = \"\"\r\n          \r\n          for(var id in stages){\r\n              i = stages[id]\r\n              if(i[0]==k){\r\n                stage=i[1]\r\n              }\r\n          }\r\n          \r\n        \r\n          \r\n          if(m.substring(1)==\'M1\'){\r\n              stage=\'IV\'\r\n          }\r\n          \r\n          $(\'#data-ajcc_staging\').val(stage);\r\n          \r\n      }\r\n      \r\n      $(\'#data-staging_type\').change(function(){\r\n          resolve();\r\n      })\r\n      $(\'#data-patho_t\').change(function(){\r\n          cal();\r\n      })\r\n      $(\'#data-patho_n\').change(function(){\r\n          cal();\r\n      })\r\n         $(\'#data-patho_m\').change(function(){\r\n          cal();\r\n      })\r\n          \r\n          \r\n          \r\n          \r\n          \r\n          nlist = $(\'#data-patho_n option\').clone();\r\n          mlist = $(\'#data-patho_m option\').clone();\r\n          \r\n          console.log(nlist);\r\n         \r\n          \r\n          \r\n          \r\n        resolve();\r\n        cal();\r\n        \r\n    });\r\n    \r\n</script>',NULL,NULL,NULL,'2019-02-04 07:27:19','2019-02-04 07:27:19','form',''),(3921,'procedure_sum_report',1098,2,'<h1>Procedure Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n\r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy ercp eus}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nFrom : <%= f.date_select :from_date, :default=>from_date ,:discard_day=>true , :order=>[:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date ,:discard_day=>true , :order=>[:month,:year]%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    # all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}}).to_a\r\n\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n \r\n    visit_time = [\"1\",\"2\",\"3\"]\r\n    time_name = {}\r\n    time_name[\"1\"] = \"ในเวลาปกติ\"\r\n    time_name[\"2\"] = \"นอกเวลาเย็น\"\r\n    time_name[\"3\"] = \"นอกเวลาเสาร์/อาทิตย์\"\r\n    \r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    providers = @models[:provider].collection.find().to_a\r\n    m_providers = bmap providers, \'_id\'\r\n\r\n    procedures = @models[:procedure].collection.find().to_a\r\n    m_procedures = bmap procedures, \'_id\'\r\n\r\n    l_procedures = procedures.collect{|i| i[\'name\']}.compact\r\n    l_procedures << \"Total\"\r\n    \r\n   \r\n    \r\n    \r\n    %>\r\n\r\n<%\r\n  \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n%>\r\n\r\n<%#= all_app.inspect %>\r\n<%#= pd_count.inspect %>\r\n\r\n\r\n<% \r\n\r\n    # month_text = select_date.strftime(\"%B-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n           td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:center; \r\n        font-weight: bold;\r\n    }\r\n    td.date{\r\n        padding:5px 10px 5px 10px;\r\n        \r\n        \r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n        \r\n    }\r\n\r\n    \r\n</style>\r\n\r\n\r\n<%\r\n\r\nfrom_text =  month_th[from_date.month-1]+from_date.strftime(\"-%Y\")\r\n\r\nto_text =  month_th[to_date.month-1]+to_date.strftime(\"-%Y\")\r\n \r\n%>\r\n<center><h3>\r\nรายงานจำนวนผู้เข้ารับบริการ \r\n<%=@current_project.get_setting \'report_title_1\' %>\r\n<br/>\r\n<%=@current_project.get_setting \'report_title_2\' %></h3>\r\n<br/>\r\n<h4>แยกตามประเภทการรักษา ระหว่างวันที่ \r\n    <%=from_text %> - <%= to_text %>\r\n</h4></center>\r\n\r\n<br/>\r\n<%\r\nfor v in visit_time\r\n    l_pv = []\r\n    pd_count = {}\r\n    time_app = []\r\n    time_app = all_app.collect{|i| i if i[\'visit_time\']==v}.compact\r\n    if time_app.size>0\r\n    for app in time_app\r\n        l_pv << app[\'provider\'] if !l_pv.include?(app[\'provider\'])\r\n        pd_count[app[\'provider\']] = {} unless pd_count[app[\'provider\']]\r\n        pd_count[app[\'provider\']][m_procedures[app[\'procedure\']][0][\'name\']] = 0 unless  pd_count[app[\'provider\']][m_procedures[app[\'procedure\']][0][\'name\']]\r\n        pd_count[app[\'provider\']][m_procedures[app[\'procedure\']][0][\'name\']] += 1\r\n    end\r\n    for j in l_pv\r\n        pd_count[j][\'Total\'] = time_app.collect{|i| i[\'_id\'] if i[\'provider\']==j}.compact.size\r\n    end\r\n \r\n%>\r\n<h3><%=time_name[v]%></h3>\r\n\r\n<table border=\"1\" class=\"content\">\r\n\r\n<tr style=\"background-color:#dedeff\"><th>Endoscopist</th>\r\n    <% for j in l_procedures %>\r\n    <th><%=j%></th>\r\n    <% end %>\r\n</tr>\r\n\r\n<% \r\n    sum = {}\r\n    l_pv.each do |i| \r\n        provider = \'deleted\'\r\n        provider = m_providers[i][0][\'name\'] if m_providers[i]\r\n%>\r\n<tr>\r\n    <td><%=provider%></td>\r\n    <% \r\n        for j in l_procedures \r\n            sum[j] = 0 unless sum[j]\r\n            sum[j] += pd_count[i][j] if pd_count[i][j]\r\n    %>\r\n    <td class=\"<%=(j==\'Total\')?\'total\':\'tx\'%>\"><%=pd_count[i][j] if pd_count[i][j]%></td>\r\n    <%  end %>\r\n</tr>\r\n<% end %>\r\n\r\n<tr>\r\n    <td>Total</td>\r\n    <% for j in l_procedures %>\r\n    <td class=\"total2\"><%=sum[j] if sum[j]>0%></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n\r\n<hr/>\r\n<br/>\r\n<% end end #for v %>\r\n\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n\r\n\r\n<% end %>\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2019-02-05 03:00:41','2019-02-05 03:00:41','procedure_sum_report',''),(3922,'form',1519,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n# treatment_ebc-add_chemotherapy-5c7f472b790f9be52a0001ec-c1\r\n# treatment_ebc-add_chemotherapy-5c7f472b790f9be52a0001ec-c2\r\n%>\r\n<script>\r\n    \r\n    function updatechange(prefix,v){\r\n        \r\n          $(\'#\'+prefix+\'c5\').hide()\r\n                $(\'#\'+prefix+\'c6\').hide()                \r\n                $(\'#\'+prefix+\'c7\').hide()\r\n                $(\'#\'+prefix+\'c8\').hide()\r\n                $(\'#\'+prefix+\'c9\').hide()\r\n                $(\'#\'+prefix+\'c10\').hide()\r\n                $(\'#\'+prefix+\'c11\').hide()\r\n                $(\'#\'+prefix+\'c12\').hide()\r\n                \r\n             \r\n            if(v==\'FAC\'||v==\'FEC\'||v==\'CMF\'||v==\'Tcarbo\'||v==\'Capecitabine\'){\r\n                $(\'#\'+prefix+\'c5\').show()\r\n                $(\'#\'+prefix+\'c6\').show()\r\n            }\r\n            \r\n            if(v==\'Paclitaxel q  weeks\'||v==\'Oral CMF\'){\r\n     \r\n                $(\'#\'+prefix+\'c5\').show()\r\n                $(\'#\'+prefix+\'c6\').show()\r\n                $(\'#\'+prefix+\'c7\').show()\r\n                $(\'#\'+prefix+\'c8\').show()\r\n                $(\'#\'+prefix+\'c9\').show()\r\n                $(\'#\'+prefix+\'c10\').show()\r\n                $(\'#\'+prefix+\'c11\').show()\r\n                $(\'#\'+prefix+\'c12\').show()\r\n           \r\n            }\r\n            \r\n            if(v==\'iv CMF\'){\r\n     \r\n                $(\'#\'+prefix+\'c5\').show()\r\n                $(\'#\'+prefix+\'c6\').show()\r\n                $(\'#\'+prefix+\'c7\').show()\r\n                $(\'#\'+prefix+\'c8\').show()\r\n            }       \r\n            \r\n    }\r\n    \r\n    \r\n    function register(id,prefix,value){\r\n    \r\n        \r\n        for(var i=4;i<12;i++){\r\n    \r\n            $(\'#\'+prefix+\'c\'+(i+1)).hide()\r\n        }\r\n        \r\n        $(\'#data-\'+prefix+\'add_regimen\').change(function(){\r\n            \r\n            v = $(this).val()\r\n            \r\n            \r\n            updatechange(prefix,v)\r\n            \r\n        })\r\n        \r\n             v =$(\'#data-\'+prefix+\'add_regimen\').val()\r\n            \r\n            updatechange(prefix,v)\r\n        \r\n        \r\n        \r\n    }\r\n    //alert($(\'input[name=update_surgery_site]\').size())\r\n    function site_select(){\r\n        s=$(\'input[name=update_surgery_site]:checked\').val()\r\n        $(\'#methodsx_l\').show();\r\n        $(\'#lnsx_l\').show();\r\n        $(\'#methodsx_other_L\').show();\r\n        $(\'#methodsx_r\').show();\r\n        $(\'#lnsx_r\').show();\r\n        $(\'#methodsx_other_r\').show();\r\n        if(s){\r\n            if(s==\'Left\'){\r\n                $(\'#methodsx_r\').hide();\r\n                $(\'#lnsx_r\').hide();\r\n                $(\'#methodsx_other_r\').hide();\r\n            }else if(s==\'Right\'){\r\n                $(\'#methodsx_l\').hide();\r\n                $(\'#lnsx_l\').hide();\r\n                $(\'#methodsx_other_L\').hide();\r\n            }\r\n        }\r\n    }\r\n    $(document).ready(function(){\r\n        // $(\'#update_surgery_site_item_0\').click(function(){\r\n        $(\'input[name=update_surgery_site]\').change(function(){\r\n            site_select()\r\n            \r\n        });\r\n        site_select()\r\n    });\r\n</script>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n\r\n',NULL,NULL,NULL,'2019-02-05 03:50:23','2019-02-05 03:50:23','form',''),(3923,'display',1519,3,'<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n<style>\r\n    .refinfo {padding:5px;width:720px; margin-left:auto; margin-right:auto}\r\n</style>\r\n <div class=\"refinfo\" >\r\n\r\nRef : <%= @patient_module.ref_number[0..9] if @patient_module.ref_number %> \r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n<p style=\"width:720px; margin-left:auto; margin-right:auto; font-weight:bold\">HN : <%= @patient.hn %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Name : <%= @patient.first_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Surname : <%= @patient.last_name %></p>\r\n<hr /><br />\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n<script>\r\n    \r\n    function register(id,prefix,value){\r\n        \r\n        \r\n        for(var i=4;i<12;i++){\r\n    \r\n            $(\'#\'+prefix+\'c\'+(i+1)).hide()\r\n        }\r\n            \r\n        \r\n             v =value\r\n       \r\n            if(v==\'FAC\'||v==\'FEC\'||v==\'CMF\'){\r\n                $(\'#\'+prefix+\'c5\').show()\r\n                $(\'#\'+prefix+\'c6\').show()\r\n            }else{\r\n                $(\'#\'+prefix+\'c5\').hide()\r\n                $(\'#\'+prefix+\'c6\').hide()\r\n            }\r\n            \r\n            \r\n                \r\n            if(v==\'CMF\'){\r\n                $(\'#\'+prefix+\'c7\').show()\r\n                $(\'#\'+prefix+\'c8\').show()\r\n            }else{\r\n                $(\'#\'+prefix+\'c7\').hide()\r\n                $(\'#\'+prefix+\'c8\').hide()\r\n            }\r\n        \r\n        \r\n        \r\n        \r\n    }\r\n    \r\n\r\n    \r\n</script>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>',NULL,NULL,NULL,'2019-02-05 04:31:10','2019-02-05 04:31:10','display',''),(3924,'change_password',1272,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=\'User\'%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(\'user\')\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document \'user\'\r\n    password = params[:password]\r\n    if password == params[:password_confirmation]\r\n    salt = User.random_string(10) \r\n    hashed_password = User.encrypt(password, salt)\r\n    params[\'record\'] = {\'salt\'=>salt,\'hashed_password\'=>hashed_password}\r\n    end\r\n    \r\n    \r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"index\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'change_password\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<label>Password</label><%= password_field_tag \'password\' %>\r\n<label>Password Confirmation</label><%= password_field_tag \'password_confirmation\' %>\r\n\r\n<%# this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2019-02-05 07:18:19','2019-02-05 07:18:19','change_password',''),(3925,'case_provider_report',789,2,'\r\n<h1>Case Report Summary </h1>\r\n<%\r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n	tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n \r\n\r\n\r\n	def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    @m_patient= model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    type = \'All\'\r\n    type = params[:report][:type] if params[:report]\r\n    \r\n    procedure = \'all\'\r\n    procedure = params[:report][:procedure] if params[:report]\r\n\r\n    indication = params[:report][:indication] if params[:report]\r\n    intervention = params[:report][:intervention] if params[:report]\r\n    diagnosis = params[:report][:diagnosis] if params[:report]\r\n\r\n    \r\n    procedures = %w{all gastro colono push_enteroscopy sigmoid ercp eus dbe liver_biopsy}\r\n    cmap = {}\r\n    for i in procedures\r\n        cmap[i] = i.humanize\r\n    end\r\n    \r\n    providers = @models [:provider].where().sort(:name).all\r\n    provider_select = providers.collect{|i| [i.name,i.id]}.compact\r\n\r\n\r\n%>\r\n<script src=\"../../../gebo/lib/chosen/chosen.jquery.min.js\"></script>\r\n<link rel=\"stylesheet\" href=\"../../../gebo/lib/chosen/chosen.css\" />\r\n\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    v{\r\n        color:blue;\r\n    }\r\n    .endoscopist{width:600px;}\r\n</style>\r\n\r\n<%=form_for \'report\' do |f| %>\r\n\r\nFrom : <%= f.date_select :from_date, :default=>from_date  , :order=>[:day,:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date  , :order=>[:day,:month,:year]%>\r\n\r\n<br/>\r\n\r\n\r\nSchedule : <%=f.select :type, options_for_select(%w{all elective special_clinic emergency}.collect{|i| i.humanize }, type) %>\r\n\r\nProcedure : <%=f.select :procedure, options_for_select(procedures.collect{|i| [i.humanize,i] }, procedure) %>\r\n\r\n<br/>\r\nEndoscopist : \r\n<%=f.select :endoscopist, options_for_select(provider_select),{},{:id=>\'endoscopist\',:class=>\'endoscopist\',:multiple=>true,\'data-placeholder\'=>\'Choose endoscopist...\'}%>\r\n\r\n<br/>\r\n<!--\r\nIndication : <%=f.text_field :indication ,:class=>\'span6\'%><br/>\r\n\r\nIntervention : <%=f.text_field :intervention ,:class=>\'span6\'%><br/>\r\n\r\nDiagnosis : <%=f.text_field :diagnosis ,:class=>\'span6\'%><br/>\r\n-->\r\n<%#i_map.inspect%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<script>\r\n$(\".endoscopist\").chosen();\r\n\r\n// var endos=\'<%#=endos.to_s.html_safe%>\';\r\n// var endos_arr=endos.split(\',\');\r\n// $(\"#endoscopist\").val(endos_arr).trigger(\"liszt:updated\");\r\n// alert(endos_arr+\' \'+$(\"#endoscopist\").val(\'value\'));\r\n\r\n</script>\r\n\r\n\r\n<% end %>\r\n\r\n\r\n  <%#params.inspect %>\r\n\r\n\r\n<% \r\n\r\n	findings_id = []\r\n    \r\n\r\n\r\n\r\n\r\n	if request.post? \r\n        endos = params[:report][:endoscopist] if params[:report]\r\n        endos.delete(\"\") if endos\r\n        endos.collect!{|i| BSON::ObjectId.from_string(i)} if endos\r\n        \r\n        finding_map = {}\r\n        finding_map[\'0\'] = \'Normal\'\r\n        finding_map[\'1\'] = \'Abnormal\'\r\n        \r\n        dxg_map = {}\r\n        \r\n        i_map = {}\r\n        \r\n        ext_cols = []\r\n        \r\n        if procedure!=\'all\'\r\n        \r\n            doc = @current_project.get_document procedure\r\n            fields = doc.fields.collect{|i| i if i.column_name==\'clinical_indication\' }.compact\r\n            indication_text = fields[0].lov.gsub(\'\\r\',\'\')\r\n            i_arr = indication_text.split(\'\\n\')\r\n            \r\n            for i in i_arr\r\n                i_sp = i.split(\'|\')\r\n                i_map[i_sp[0]] = i_sp[1] unless i_map[i_sp[0]]\r\n            end  \r\n            \r\n            \r\n            dxg_map = doc.fields.collect{|i| i if i.column_name==\'diagnosis_group\' }.compact[0].lov.gsub(\'\\r\',\'\').split(\"\\n\").collect{|i| i.split(\'|\') }.to_h\r\n         \r\n            service = @current_project.get_service procedure\r\n            config  = service.operations.where(:name=>\'finding_config\').first\r\n            if config\r\n                    \r\n                    obj = eval config.command\r\n                    ext_cols = obj[:view]\r\n                 \r\n            end\r\n        \r\n            \r\n        end\r\n		# select appointment by date\r\n  \r\n		all_app = @models[:appointment].collection.find({:date=>{\'$gte\'=>from_date,\'$lt\'=>to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n  \r\n  \r\n  \r\n		# select pm by module_id of appointment\r\n  \r\n		all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n		\r\n		m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n  \r\n		# select patients by patient_id of pm \r\n		all_patients = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'hn\'=>1,\'birth_date\'=>1}}).to_a\r\n		m_patients = bmap all_patients\r\n  \r\n  \r\n  \r\n		map = {}\r\n  \r\n  \r\n		# for each forms prepare list of module_id \r\n		all_pm = @m_patient_module.collection.find({:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n		m_all_pm = bmap all_pm, \'module_id\'\r\n  \r\n		for i in all_pm\r\n  \r\n			m = i[\'module_name\'].split(\'#\')[-1]\r\n  \r\n			if procedure==\'all\'\r\n  \r\n				map[m] = [] unless map[m]\r\n				map[m] << i[\'module_id\']\r\n  \r\n			else\r\n  \r\n				if m == procedure\r\n  \r\n					map[m] = [] unless map[m]\r\n					map[m] << i[\'module_id\']\r\n  \r\n				end\r\n  \r\n      \r\n			end\r\n  \r\n		end\r\n  \r\n  \r\n  \r\n		# for each form\'s records \r\n		case_map = {}\r\n		provider_map = {}\r\n  \r\n    for k in map.keys\r\n    \r\n		rs = map[k]\r\n		case_map[k] = [] unless case_map[k]\r\n		if @models[k.to_sym]\r\n    \r\n			conds = {:_id=>{\'$in\'=>rs}}\r\n    \r\n			# 0|Elective\r\n			# 1|Emergency\r\n			# 2|Special clinic\r\n			# 3|Live demo\r\n    \r\n    \r\n			if type !=\'All\'\r\n    \r\n				ctype = \'\'\r\n				case type\r\n					when \'Elective\'\r\n						ctype = \'0\'\r\n					when \'Emergency\'\r\n						ctype = \'1\'\r\n					when \'Special clinic\'\r\n						ctype = \'2\'\r\n				end\r\n        \r\n				conds.merge! :schedule=> ctype\r\n       \r\n			end\r\n# 			conds.merge! :endoscopist=> endos\r\n            px = {\'findings\'=>1,\'finding\'=>1,\'clinical_indication\'=>1,\'_id\'=>1,\'schedule\'=>1,\'endoscopist\'=>1,\'assist1endoscopist\'=>1,\'assist2endoscopist\'=>1,\'created_at\'=>1,\'diagnosis_text\'=>1,\'diagnosis_group\'=>1,\'intervention_text\'=>1,\'procedure\'=>1,\'intervention\'=>1,\'intervention_group\'=>1,\'intervention_summary\'=>1,\'diagnosis_group\'=>1,\'final_diagnosis\'=>1}\r\n            \r\n            if ext_cols.size>0\r\n               for x in ext_cols\r\n                  px[x[:editor_id]] = 1 \r\n               end\r\n            end\r\n            \r\n			records = @models[k.to_sym].collection.find(conds, {:fields=>px}).to_a\r\n# 			records = @models[k.to_sym].collection.find(conds).to_a\r\n\r\n            records.collect!{|i| i if endos.include?(i[\'endoscopist\']) or endos.include?(i[\'assist1endoscopist\']) or endos.include?(i[\'assist2endoscopist\'])}.compact! if endos and endos.size>0\r\n  %><%#=records.inspect%><% \r\n		\r\n			for i in records\r\n				provider_map[i[\'endoscopist\']] = true \r\n				\r\n				i[\'findings\'] = eval(i[\'findings\'][0]) if i[\'findings\'].size > 0 and i[\'findings\'][0].index(\']\')\r\n             \r\n                \r\n				findings_id += i[\'findings\'] if i[\'findings\']\r\n        \r\n				if true\r\n					case_map[k] << i \r\n				end\r\n        \r\n			end\r\n\r\n		end\r\n  \r\n	end\r\n  \r\n  \r\n  \r\n  \r\n	providers = @models[:provider].collection.find({:_id=>{\'$in\'=>provider_map.keys}})\r\n	m_providers = bmap providers\r\n  \r\n  \r\n  #  collect error\r\n    \r\n     \r\n	findings = @models[:finding].collection.find({:_id=>{\'$in\'=>findings_id.collect{|x| BSON::ObjectId(x)}}}).to_a\r\n# 	findings =[]\r\n	\r\n	findings_map = bmap findings\r\n  \r\n  \r\n  \r\n	intervention_ids = findings.collect{|x| x[\'intervention\'] }\r\n  \r\n  \r\n  \r\n  \r\n	interventions = @models[:intervention].collection.find({:_id=>{\'$in\'=>intervention_ids},:intervention_tag=>{\'$ne\'=>\"\"}},{:fields=>{\'intervention_tag\'=>1,\'op_clipping_type\'=>1}}).to_a\r\n  \r\n	interventions_map = bmap interventions\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  if records\r\n  \r\n		for i in records\r\n  \r\n			if i[\'findings\']\r\n            \r\n            \r\n			fs = i[\'findings\'].collect{|x| findings_map[BSON::ObjectId(x)][0] }\r\n# 			fs = []\r\n			fs = fs.collect{|x| {:f=>x,:i=>interventions_map[x[\'intervention\']]} } \r\n            inv = []\r\n            inv = i[\'intervention_group\'].split(\"|\") if i[\'intervention_group\']\r\n            if fs\r\n            for f in fs\r\n                if f[:i]\r\n                    fi = f[:i][0]\r\n                    inv << fi[\'intervention_tag\']\r\n                end\r\n            end\r\n            end\r\n            \r\n            i[\'intervention_group\'] = inv.uniq.join(\'|\')\r\n            \r\n            end\r\n    \r\n            \r\n		end\r\n  \r\n  end\r\n %>\r\n  <%#interventions_map.inspect %>\r\n  \r\n  \r\nFor <i><%=from_date.strftime(\"%d-%m-%Y\")%> to <%=to_date.strftime(\"%d-%m-%Y\")%> </i>\r\n \r\n<br/><br/>\r\n \r\n \r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Procedure</th><th>Elective</th><th>Emergency</th><th>Special Clinic</th><th>Undefined</th><th>Total</th>\r\n	</tr>\r\n<%  \r\n    tsum = {\'0\'=>0,\'1\'=>0,\'2\'=>0,nil=>0}\r\n\r\n	for k in case_map.keys \r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n		s = i[\'schedule\']\r\n     \r\n		tmap[s] = [] unless tmap[s]\r\n		tmap[s] << i \r\n     \r\n		tsum[s] = 0 unless tsum[s]\r\n		tsum[s] += 1\r\n      \r\n	end\r\n  \r\n%>\r\n    <tr><td><%=k.humanize%></td>\r\n      \r\n		<td align=\'center\'><%=tmap[\'0\'].size if tmap[\'0\']%></td>\r\n		<td align=\'center\'><%=tmap[\'1\'].size if tmap[\'1\']%></td>\r\n		<td align=\'center\'><%=tmap[\'2\'].size if tmap[\'2\']%></td>\r\n		<td align=\'center\'><%=tmap[\'\'].size if tmap[\'\']%></td>\r\n      \r\n    <th><%=case_map[k].size%></th></tr>\r\n	\r\n<% end %>      \r\n \r\n	<tr>\r\n		<td>&nbsp;</td>\r\n		<th><%=tsum[\'0\']%></td>\r\n		<th><%=tsum[\'1\']%></td>\r\n		<th><%=tsum[\'2\']%></td>\r\n		<th><%=tsum[\'\']%></td>\r\n<%\r\n			total_sum = 0 \r\n			total_sum += tsum[\'0\'] if tsum[\'0\']\r\n			total_sum += tsum[\'1\'] if tsum[\'1\']\r\n			total_sum += tsum[\'2\'] if tsum[\'2\']\r\n			total_sum += tsum[\'\'] if tsum[\'\']\r\n\r\n%>\r\n		<th><%=total_sum%></th>\r\n	</tr>\r\n</table>\r\n\r\n<br>\r\n  \r\n<% if procedure!=\'all\'%>\r\n<%\r\n    int_map = {}\r\n    for i in records\r\n		int = i[\'intervention_group\']\r\n		if int\r\n			ints = int.split(\'|\') \r\n     \r\n			for j in ints\r\n				int_map[j] = 0 unless int_map[j]\r\n				int_map[j] += 1\r\n			end\r\n		end\r\n    end\r\n  \r\n%>\r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Intervention</th><th>Count</th>\r\n	</tr>\r\n<% for i in int_map.keys %>\r\n	<tr>\r\n		<th><%=i.humanize%></th>\r\n		<td align=\'center\'><%=int_map[i]%></td>\r\n	</tr>\r\n<% end %>\r\n</table>\r\n  \r\n<br/>\r\n  \r\n<%\r\n    dx_map = {}\r\n    for i in records\r\n     \r\n		int = i[\'diagnosis_group\']\r\n		if int\r\n			dxs = int.split(\'|\') \r\n     \r\n			for j in dxs\r\n     \r\n				dx_map[j] = 0 unless dx_map[j]\r\n				dx_map[j] += 1\r\n     \r\n			end\r\n     \r\n		end\r\n      \r\n    end\r\n  \r\n%>\r\n\r\n<%\r\n  \r\n    options = get_document(procedure ).find_by_column_name(\'diagnosis_group\').get_lov_options   \r\n    \r\n    dx_name = {}\r\n    \r\n    for i in options\r\n        \r\n        dx_name[i[0]] = i[1].strip\r\n    \r\n    end\r\n  \r\n  \r\n%>\r\n  \r\n<table border=\"1\">\r\n	<tr>\r\n		<th>Diagnosis Group</th><th>Count</th>\r\n	</tr>\r\n<% \r\n	for i in dx_map.keys \r\n  \r\n		name = \"Undefined(\\\\#{i})\"\r\n		name = dx_name[i] if dx_name[i]\r\n  \r\n%>\r\n	<tr>\r\n		<th><%=name%></th>\r\n		<td align=\'center\'><%=dx_map[i]%></td>\r\n	</tr>\r\n  \r\n<% end %>\r\n</table>\r\n  \r\n<br/>\r\n  \r\n<% end %>\r\n<div class=\'row-fluid\'>\r\n<div style=\'float:right;margin:20px\'>\r\n<%#= link_to \'Export EXCEL\', \"case_provider_excel?from_date=\\\\#{from_date.strftime(\'%Y-%m-%d\')}&to_date=\\\\#{to_date.strftime(\'%Y-%m-%d\')}&type=\\\\#{params[:report][:type]}&procedure=\\\\#{params[:report][:procedure]}\", :target=>\'_blank\', :class=>\'btn btn-info\' %>\r\n<%= link_to \'Export EXCEL\', \"javascript:export_table_to_csv(encodeURIComponent($(\'#export_data\').html()), \'case_report.csv\')\", :class=>\'btn btn-info\' %>\r\n\r\n</div></div>\r\n\r\n<table border=\"1\" id=\"export_data\">\r\n	<tr>\r\n		<th>#</th>\r\n		<th>Procedure</th>\r\n		<th>Date</th>\r\n		<th>HN</th>\r\n		<th>Patient\'s name</th>\r\n		<th>Age</th>\r\n		<th>Schedule</th>\r\n		<th>Endosocpist</th>\r\n		<th>Indication</th>\r\n		<th>InterventionGroup</th>\r\n		<th>Intervention</th>\r\n		<th><!--DiagnosisGroup-->Finding</th>\r\n		<th>DiagnosisGroup</th>\r\n		\r\n		<th>Diagnosis</th>\r\n		<% for x in ext_cols %>\r\n		<th><%=x[:value].humanize%></th>\r\n		<% end %>\r\n		\r\n	</tr>\r\n\r\n<%\r\n	# zam\r\n	# prepare excel result\r\n	res = {}\r\n	\r\n	# select provider of those records\r\n	for k in case_map.keys\r\n		\r\n		# zam\r\n		# set operation name\r\n		op_name = k.humanize\r\n%>\r\n	<tr style=\"background-color:#ccffcc\">\r\n		<td colspan=\"<%=14+ext_cols.size%>\"><h1><%=k.humanize%></h1></td>\r\n	</tr>\r\n<%\r\n  \r\n		tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n			s = i[\'schedule\']\r\n     \r\n			tmap[s] = [] unless tmap[s]\r\n			tmap[s] << i \r\n      \r\n		end\r\n  \r\n		tmap.each_pair do |ks, list| \r\n			index = 0 \r\n			\r\n			# zam\r\n			# set visit_type\r\n			vt = tschedule[ks]\r\n			kk = \"\\\\#{op_name}-\\\\#{vt}\"\r\n			res[kk] = []\r\n%>\r\n    <tr style=\"background-color:#cccccc\">\r\n		<td colspan=\"<%=14+ext_cols.size%>\"><%=tschedule[ks]%></td>\r\n	</tr>\r\n<%\r\n	list.each do |i|\r\n	\r\n		# zam\r\n		# temporary for each records\r\n		tmp = {}\r\n    \r\n		pm = m_all_pm[i[\'_id\']][0]\r\n		if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n			patient = m_patients[pm[\'patient_id\']][0]\r\n			providers = []\r\n			providers << m_providers[i[\'endoscopist\']][0][\'name\']  if m_providers[i[\'endoscopist\']]\r\n			providers << m_providers[i[\'assist1endoscopist\']][0][\'name\']  if m_providers[i[\'assist1endoscopist\']]\r\n            providers << m_providers[i[\'assist2endoscopist\']][0][\'name\']  if m_providers[i[\'assist2endoscopist\']]\r\n            provider = providers.join(\", \")\r\n            \r\n            \r\n			if pm and patient  and provider\r\n        \r\n				schedule = \'-\'\r\n        \r\n				schedule = tschedule[ i[\'schedule\']]\r\n				\r\n				# collect text into tmp\r\n				op_date = i[\'created_at\'].strftime(\"%d/%m/%Y\") \r\n				pat_hn  = patient[\'hn\'] \r\n				pat_name= \"\\\\#{patient[\'first_name\']} \\\\#{patient[\'last_name\']}\"\r\n				\r\n				tmp[:op_date] = op_date\r\n				tmp[:hn] = pat_hn\r\n				tmp[:name] = pat_name\r\n				tmp[:endo] = provider\r\n				tmp[:diag] = \'\"\'+i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\')+\'\"\' if i[\'diagnosis_text\']\r\n				tmp[:inv_txt] = \'\"\'+i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\')+\'\"\' if i[\'intervention_text\'] \r\n				tmp[:inv_sum] = \'\"\'+i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\')+\'\"\' if i[\'intervention_summary\']\r\n				tmp[:inv_group] = i[\'intervention_group\']\r\n				\r\n				\r\n				res[kk] << tmp\r\n				\r\n				#finding\r\n				finding_text = finding_map[i[\'finding\']]\r\n				# finding_text = \"Normal\"\r\n				# finding_text = \"Abnormal\" if i[\'diagnosis_group\']!=\'0\' and i[\'diagnosis_group\']!=\' \' and i[\'diagnosis_group\']!=\'\'\r\n				if finding_text==\'Abnormal\'\r\n				    tmp_finding=\'Normal\'\r\n				    for x in ext_cols \r\n				        tmp_text = i[x[:editor_id]].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\').html_safe\r\n				        tmp_finding=\'Abnormal\' unless tmp_text==\'Normal\' or tmp_text==\'\' or tmp_text==\' \' or tmp_text==\'NA\' or tmp_text==\'N/A\'\r\n				    end\r\n				    finding_text = tmp_finding\r\n				end\r\n        \r\n%>\r\n	<tr>\r\n		<td><%=index+1%></td>\r\n        <td><%=k.humanize%></td>\r\n		<td><%=i[\'created_at\'].strftime(\"%d-%m-%Y\") %></td>\r\n		<td><%=patient[\'hn\'] %></td>\r\n		<td><%=patient[\'first_name\'] %> <%=patient[\'last_name\']%></td>\r\n		<td><%=((Time.now - patient[\'birth_date\'].to_datetime)/3600/365/24).to_i if patient[\'birth_date\']%></td>\r\n		<td><%= schedule %></td>\r\n		<td>\"<%= provider %>\"</td>\r\n        <td><%=\'\"\'+i[\'clinical_indication\'].split(\'|\').collect{|indi| i_map[indi]}.join(\',\')+\'\"\' if i[\'clinical_indication\']!=\'\'%></td>\r\n<%\r\n           ig = \'background-color:#ffcccc\'\r\n%>\r\n        <td style=\'<%#ig if  i[\'intervention_text\']!=\"\" and i[\'intervention_group\'] and  i[\'intervention_group\'].strip==\'\' %>\'>\r\n<%\r\n            intv = \'-\'\r\n          \r\n%>\r\n			<%=\'\"\'+i[\'intervention_group\']+\'\"\' if i[\'intervention_group\']!=\'\'%><%#i[\'intervention_text\']%>\r\n			</td>\r\n        <td style=\"width:300px\"><%= \'\"\'+i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<br />\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\').gsub(\'\"\',\'\').html_safe+\'\"\' if i[\'intervention_text\'] and i[\'intervention_text\']!=\'\' %><%= \'\"\'+i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\').gsub(\'\"\',\'\').html_safe+\'\"\' if i[\'intervention_summary\'] and i[\'intervention_summary\']!=\'\' %></td>\r\n        <td><%=finding_text%></td>\r\n        <td><%=\'\"\'+i[\'diagnosis_group\'].split(\'|\').collect{|x| dxg_map[x]}.join(\", \")+\'\"\' if i[\'diagnosis_group\'] and i[\'diagnosis_group\']!=\' \'%></td>\r\n        <td style=\"width:300px\"><%= \'\"\'+i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\').html_safe+\'\"\' if i[\'diagnosis_text\'] and i[\'diagnosis_text\']!=\'\' %></td>\r\n      \r\n      	<% for x in ext_cols %>\r\n		<td><%=\'\"\'+i[x[:editor_id]].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\').html_safe+\'\"\' if i[x[:editor_id]] and i[x[:editor_id]]!=\'\'%></td>\r\n		<% end %>\r\n		\r\n		\r\n        </tr>\r\n\r\n<%\r\n        \r\n				index+=1\r\n        \r\n			end # if pm and patient  and provider\r\n    \r\n		end #if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n  \r\n        \r\n	end # list.each do |i|\r\n  \r\n	end # tmap.each_pair do |ks, list| \r\n  \r\n	end # for k in case_map.keys\r\n	\r\n# 	session[:case_report_excel] = res\r\n# 	session[:case_report_from] = from_date.strftime(\"%d/%m/%Y\")\r\n# 	session[:case_report_to] = to_date.strftime(\"%d/%m/%Y\")\r\n  \r\n%>\r\n</table>\r\n<%# res.to_json.html_safe %>\r\n<%\r\n  \r\n  # for each recoreds to reprrt\r\n  \r\n%>\r\n<script type=\"text/javascript\">\r\nconsole.log(\"ok\")\r\nfunction download_csv(csv, filename) {\r\n    var csvFile;\r\n    var downloadLink;\r\n\r\n    // CSV FILE\r\n    csvFile = new Blob([csv], {type: \"text/csv\"});\r\n\r\n    // Download link\r\n    downloadLink = document.createElement(\"a\");\r\n\r\n    // File name\r\n    downloadLink.download = filename;\r\n\r\n    // We have to create a link to the file\r\n    downloadLink.href = window.URL.createObjectURL(csvFile);\r\n\r\n    // Make sure that the link is not displayed\r\n    downloadLink.style.display = \"none\";\r\n\r\n    // Add the link to your DOM\r\n    document.body.appendChild(downloadLink);\r\n\r\n    // Lanzamos\r\n    downloadLink.click();\r\n}\r\n\r\nfunction export_table_to_csv(html, filename) {\r\n    var csv = [];\r\n    var rows = document.querySelectorAll(\"table tr\");\r\n    for (var i = 0; i < rows.length; i++) {\r\n        var row = [], cols = rows[i].querySelectorAll(\"td, th\");\r\n        for (var j = 0; j < cols.length; j++) \r\n            row.push(cols[j].innerText.replace(\"\\\\n\",\" \"));\r\n\r\n      csv.push(row.join(\",\"));  \r\n     }\r\n\r\n    // Download CSV\r\n    download_csv(csv.join(\"\\\\n\"), filename);\r\n}\r\n\r\n// document.querySelector(\"button\").addEventListener(\"click\", function () {\r\n//     var html = document.querySelector(\"table\").outerHTML;\r\n//  export_table_to_csv(html, \"table.csv\");\r\n// });\r\n</script>  \r\n  \r\n  \r\n<% end %>\r\n\r\n\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2019-02-06 03:05:15','2019-02-06 03:05:15','case_provider_report',''),(3926,'case_provider_excel',789,3,'<%\r\n    response.headers[\"Content-Type\"] = \"application/xls\"\r\n    response.headers[\"Content-disposition\"] = \"attachment; filename=CaseReports-\\#{Time.now.to_i}.xls\"\r\n    \r\n    pname = \"\\#{@current_project.name}#\"\r\n	tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n \r\n\r\n\r\n	def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    \r\n    month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n    @models = get_model\r\n    forms = %w{colonoscopy gastroscopy}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    @m_patient= model[:patient]\r\n    @m_patient_module = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = params[:from_date]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = params[:to_date]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n    \r\n    type = \'All\'\r\n    type = params[:report][:type] if params[:report]\r\n    \r\n    procedure = \'all\'\r\n    procedure = params[:report][:procedure] if params[:report]\r\n    \r\n    procedures = %w{all gastro colono push_enteroscopy sigmoid ercp eus dbe}\r\n    cmap = {}\r\n    for i in procedures\r\n        cmap[i] = i.humanize\r\n    end\r\n	\r\n	\r\n  \r\n		# select appointment by date\r\n  \r\n		all_app = @models[:appointment].collection.find({:date=>{\'$gte\'=>from_date,\'$lt\'=>to_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n  \r\n  \r\n		# select pm by module_id of appointment\r\n  \r\n		all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n		m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n  \r\n		# select patients by patient_id of pm \r\n		all_patients = @m_patient.collection.find({:_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'patient_id\'] }}},{:fields=>{\'_id\'=>1,\'first_name\'=>1,\'last_name\'=>1,\'hn\'=>1}}).to_a\r\n		m_patients = bmap all_patients\r\n  \r\n  \r\n		map = {}\r\n  \r\n		# for each forms prepare list of module_id \r\n		all_pm = @m_patient_module.collection.find({:parent_id=>{\'$in\'=>all_pm_app.collect{|i| i[\'_id\']}}}).to_a\r\n		m_all_pm = bmap all_pm, \'module_id\'\r\n  \r\n		for i in all_pm\r\n  \r\n			m = i[\'module_name\'].split(\'#\')[-1]\r\n  \r\n			if procedure==\'all\'\r\n  \r\n				map[m] = [] unless map[m]\r\n				map[m] << i[\'module_id\']\r\n  \r\n			else\r\n  \r\n				if m == procedure\r\n  \r\n					map[m] = [] unless map[m]\r\n					map[m] << i[\'module_id\']\r\n  \r\n				end\r\n  \r\n      \r\n			end\r\n  \r\n		end\r\n  \r\n  \r\n		# for each form\'s records \r\n		case_map = {}\r\n		provider_map = {}\r\n  \r\n    for k in map.keys\r\n    \r\n		rs = map[k]\r\n		case_map[k] = [] unless case_map[k]\r\n		if @models[k.to_sym]\r\n    \r\n			conds = {:_id=>{\'$in\'=>rs}}\r\n    \r\n			# 0|Elective\r\n			# 1|Emergency\r\n			# 2|Special clinic\r\n			# 3|Live demo\r\n    \r\n    \r\n			if type !=\'All\'\r\n    \r\n				ctype = \'\'\r\n				case type\r\n					when \'Elective\'\r\n						ctype = \'0\'\r\n					when \'Emergency\'\r\n						ctype = \'1\'\r\n					when \'Special clinic\'\r\n						ctype = \'2\'\r\n				end\r\n        \r\n				conds.merge! :schedule=> ctype\r\n       \r\n			end\r\n        \r\n			records = @models[k.to_sym].collection.find(conds, {:fields=>{\'comment\'=>1,\'_id\'=>1,\'complications\'=>1,\'clinical_indication\'=>1,\'start_procedural_time\'=>1,\'findings\'=>1,\'_id\'=>1,\'schedule\'=>1,\'endoscopist\'=>1,\'created_at\'=>1,\'diagnosis_text\'=>1,\'diagnosis_group\'=>1,\'intervention_text\'=>1,\'procedure\'=>1,\'intervention\'=>1,\'intervention_group\'=>1,\'intervention_summary\'=>1}}).to_a\r\n\r\n	@document = get_document(k)\r\n   \r\n			findings_id = []\r\n         idx_name = {}\r\n		    if @document.find_by_column_name(\'clinical_indication\')\r\n		    for i in @document.find_by_column_name(\'clinical_indication\').get_lov_options   \r\n			\r\n			    idx_name[i[0]] = i[1].strip\r\n		\r\n		    end # for i in options\r\n        end\r\n\r\n			for i in records\r\n				provider_map[i[\'endoscopist\']] = true \r\n        \r\n				findings_id += i[\'findings\'] if i[\'findings\']\r\n                i[\'clinical_indication\'] =  i[\'clinical_indication\'].split(\"|\").collect{|x| idx_name[x]}.join(\", \") if i[\'clinical_indication\']  #render_value(\'clinical_indication\')\r\n                i[\'complications\'] = i[\'comment\'] if i[\'complications\']==\'0\'\r\n                i[\'complications\'] = \'Y \'+i[\'comment\'] if i[\'complications\']==\'1\'\r\n                \r\n				if true\r\n					case_map[k] << i \r\n				end\r\n        \r\n			end\r\n\r\n		end\r\n  \r\n	end\r\n  \r\n  \r\n	providers = @models[:provider].collection.find({:_id=>{\'$in\'=>provider_map.keys}})\r\n	m_providers = bmap providers\r\n  \r\n  \r\n	findings = @models[:finding].collection.find({:_id=>{\'$in\'=>findings_id.collect{|x| BSON::ObjectId(eval(x)[0])}}}).to_a\r\n	findings_map = bmap findings\r\n  \r\n	intervention_ids = findings.collect{|x| x[\'intervention\'] }\r\n  \r\n	interventions = @models[:intervention].collection.find({:_id=>{\'$in\'=>intervention_ids},:intervention_tag=>{\'$ne\'=>\"\"}},{:fields=>{\'intervention_tag\'=>1,\'op_clipping_type\'=>1}}).to_a\r\n  \r\n	interventions_map = bmap interventions\r\n  \r\n  \r\n		for i in records\r\n  \r\n			if i[\'findings\']\r\n            \r\n			fs = i[\'findings\'].collect{|x| findings_map[BSON::ObjectId(eval(x)[0])][0] }\r\n			fs = fs.collect{|x| {:f=>x,:i=>interventions_map[x[\'intervention\']]} } \r\n            inv = []\r\n            inv = i[\'intervention_group\'].split(\"|\") if i[\'intervention_group\']\r\n            for f in fs\r\n                if f[:i]\r\n                    fi = f[:i][0]\r\n                    inv << fi[\'intervention_tag\']\r\n                end\r\n            end\r\n            \r\n            i[\'intervention_group\'] = inv.uniq.join(\'|\')\r\n            \r\n            end\r\n    \r\n            \r\n		end\r\n \r\n    tsum = {\'0\'=>0,\'1\'=>0,\'2\'=>0,nil=>0}\r\n\r\n	for k in case_map.keys \r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n			s = i[\'schedule\']\r\n		 \r\n			tmap[s] = [] unless tmap[s]\r\n			tmap[s] << i \r\n		 \r\n			tsum[s] = 0 unless tsum[s]\r\n			tsum[s] += 1\r\n      \r\n		end # case_map[k].each do |i|\r\n  \r\n	end  # for k in case_map.keys      \r\n \r\n  \r\n	if procedure!=\'all\'\r\n\r\n		int_map = {}\r\n		for i in records\r\n			int = i[\'intervention_group\']\r\n			if int\r\n				ints = int.split(\'|\') \r\n		 \r\n				for j in ints\r\n					int_map[j] = 0 unless int_map[j]\r\n					int_map[j] += 1\r\n				end\r\n			end\r\n		end\r\n	  \r\n		dx_map = {}\r\n		for i in records\r\n		 \r\n			int = i[\'diagnosis_group\']\r\n			if int\r\n				dxs = int.split(\'|\') \r\n		 \r\n				for j in dxs\r\n		 \r\n					dx_map[j] = 0 unless dx_map[j]\r\n					dx_map[j] += 1\r\n		 \r\n				end # for j in dxs\r\n		 \r\n			end # if int\r\n		  \r\n		end # for i in records\r\n		options = []\r\n		options = get_document(procedure ).find_by_column_name(\'diagnosis_group\').get_lov_options    if get_document(procedure ).find_by_column_name(\'diagnosis_group\')\r\n		\r\n		dx_name = {}\r\n		\r\n		for i in options\r\n			\r\n			dx_name[i[0]] = i[1].strip\r\n		\r\n		end # for i in options\r\n	  \r\n	  \r\n		for i in dx_map.keys \r\n	  \r\n			name = \"Undefined(\\#{i})\"\r\n			name = dx_name[i] if dx_name[i]\r\n		end # for i in dx_map.keys \r\n	  \r\n	  \r\n	end # if procedure!=\'all\'\r\n\r\n	# zam\r\n	# prepare excel result\r\n	res = {}\r\n	sdate = from_date.strftime(\'%d/%m/%Y\')\r\n	edate = to_date.strftime(\'%d/%m/%Y\')\r\n	\r\n	# select provider of those records\r\n	for k in case_map.keys\r\n		\r\n		# zam\r\n		# set operation name\r\n		op_name = k.humanize\r\n\r\n		tschedule = {\'0\'=>\'Elective\', \'1\'=>\'Emergency\', \'2\'=>\'Special clinic\'}\r\n		tmap = {}\r\n		case_map[k].each do |i|\r\n     \r\n			s = i[\'schedule\']\r\n     \r\n			tmap[s] = [] unless tmap[s]\r\n			tmap[s] << i \r\n      \r\n		end\r\n  \r\n		tmap.each_pair do |ks, list| \r\n			index = 0 \r\n			\r\n			# zam\r\n			# set visit_type\r\n			vt = tschedule[ks]\r\n			kk = \"\\#{op_name}-\\#{vt}\"\r\n			res[kk] = []\r\n\r\n			list.each do |i|\r\n			\r\n				# zam\r\n				# temporary for each records\r\n				tmp = {}\r\n			\r\n				pm = m_all_pm[i[\'_id\']][0]\r\n				if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n					patient = m_patients[pm[\'patient_id\']][0]\r\n					provider = nil\r\n					provider = m_providers[i[\'endoscopist\']][0]  if m_providers[i[\'endoscopist\']]\r\n					\r\n					if pm and patient  and provider\r\n				\r\n						schedule = \'-\'\r\n				\r\n						schedule = tschedule[ i[\'schedule\']]\r\n						\r\n						# collect text into tmp\r\n						op_date = i[\'created_at\'].strftime(\"%d/%m/%Y\") \r\n						pat_hn  = patient[\'hn\'] \r\n						pat_name= \"\\#{patient[\'first_name\']} \\#{patient[\'last_name\']}\"\r\n						\r\n						tmp[:op_date] = op_date\r\n						tmp[:hn] = pat_hn\r\n						tmp[:name] = pat_name\r\n						tmp[:endo] = provider[\'name\']\r\n						tmp[:diag] = i[\'diagnosis_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'diagnosis_text\']\r\n						tmp[:inv_txt] = i[\'intervention_text\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'intervention_text\'] \r\n						tmp[:inv_sum] = i[\'intervention_summary\'].gsub(\'<p>\',\'\').gsub(\'</p>\',\'\').gsub(\'<br>\',\'\').gsub(\'<br/>\',\'\').gsub(\'<v>\',\'\').gsub(\'</v>\',\'\') if i[\'intervention_summary\']\r\n						tmp[:inv_group] = i[\'intervention_group\']\r\n						tmp[:time] = i[\'start_procedural_time\'].strftime(\"%H:%M\")\r\n						tmp[:indication]= i[\'clinical_indication\']\r\n						tmp[:complication] = i[\'complications\']\r\n						\r\n						res[kk] << tmp\r\n				\r\n						index+=1\r\n				\r\n					end # if pm and patient  and provider\r\n			\r\n				end #if pm[\'patient_id\'] and m_patients[pm[\'patient_id\']]\r\n		  \r\n				\r\n			end # list.each do |i|\r\n  \r\n		end # tmap.each_pair do |ks, list| \r\n  \r\n	end # for k in case_map.keys\r\n%>\r\n<?xml version=\"1.0\"?>\r\n<?mso-application progid=\"Excel.Sheet\"?>\r\n<Workbook xmlns=\"urn:schemas-microsoft-com:office:spreadsheet\"\r\n xmlns:o=\"urn:schemas-microsoft-com:office:office\"\r\n xmlns:x=\"urn:schemas-microsoft-com:office:excel\"\r\n xmlns:ss=\"urn:schemas-microsoft-com:office:spreadsheet\"\r\n xmlns:html=\"http://www.w3.org/TR/REC-html40\">\r\n <DocumentProperties xmlns=\"urn:schemas-microsoft-com:office:office\">\r\n  <Author>E.S.M.Solution CO.,Ltd.</Author>\r\n  <LastAuthor><%= @current_user %></LastAuthor>\r\n  <Created><%= Time.now %></Created>\r\n  <LastSaved><%= Time.now %></LastSaved>\r\n  <Version>15.00</Version>\r\n </DocumentProperties>\r\n <OfficeDocumentSettings xmlns=\"urn:schemas-microsoft-com:office:office\">\r\n  <AllowPNG/>\r\n </OfficeDocumentSettings>\r\n <ExcelWorkbook xmlns=\"urn:schemas-microsoft-com:office:excel\">\r\n  <WindowHeight>7800</WindowHeight>\r\n  <WindowWidth>20490</WindowWidth>\r\n  <WindowTopX>0</WindowTopX>\r\n  <WindowTopY>0</WindowTopY>\r\n  <ProtectStructure>False</ProtectStructure>\r\n  <ProtectWindows>False</ProtectWindows>\r\n </ExcelWorkbook>\r\n <Styles>\r\n  <Style ss:ID=\"Default\" ss:Name=\"Normal\">\r\n   <Alignment ss:Vertical=\"Bottom\"/>\r\n   <Borders/>\r\n   <Font ss:FontName=\"Calibri\" x:Family=\"Swiss\" ss:Size=\"11\" ss:Color=\"#000000\"/>\r\n   <Interior/>\r\n   <NumberFormat/>\r\n   <Protection/>\r\n  </Style>\r\n  <Style ss:ID=\"s65\">\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s68\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s69\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s70\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Bottom\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s72\">\r\n   <Alignment ss:Vertical=\"Bottom\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s74\">\r\n   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\" ss:WrapText=\"1\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n  <Style ss:ID=\"s75\">\r\n   <Alignment ss:Vertical=\"Bottom\" ss:WrapText=\"1\"/>\r\n   <NumberFormat ss:Format=\"@\"/>\r\n  </Style>\r\n </Styles>\r\n<%\r\n    res.keys.each do |i|\r\n        ws_name = i\r\n        arr = res[i]\r\n        if arr.count == 0\r\n            next\r\n        end\r\n        if i.split(\'-\').count != 1 or arr.count != 0\r\n            # arr = res[i]\r\n%>\r\n <Worksheet ss:Name=\"<%= ws_name %>\">\r\n  <Table ss:ExpandedColumnCount=\"13\" ss:ExpandedRowCount=\"<%= arr.count + 10 %>\" x:FullColumns=\"1\"\r\n   x:FullRows=\"1\" ss:DefaultRowHeight=\"15\">\r\n   <Column ss:StyleID=\"s68\" ss:AutoFitWidth=\"0\" ss:Width=\"35.25\"/>\r\n   <Column ss:StyleID=\"s70\" ss:AutoFitWidth=\"0\" ss:Width=\"68.25\"/>\r\n   <Column ss:StyleID=\"s70\" ss:Width=\"67.5\"/>\r\n   <Column ss:StyleID=\"s65\" ss:AutoFitWidth=\"0\" ss:Width=\"150\" ss:Span=\"1\"/>\r\n   <Column ss:Index=\"6\" ss:StyleID=\"s75\" ss:AutoFitWidth=\"0\" ss:Width=\"150\"\r\n    ss:Span=\"3\"/>\r\n   <Column ss:Index=\"10\" ss:StyleID=\"s65\" ss:AutoFitWidth=\"0\"/>\r\n   <Row>\r\n    <Cell ss:MergeAcross=\"8\"><Data ss:Type=\"String\"><%= ws_name %> Report</Data></Cell>\r\n    <Cell ss:StyleID=\"s72\"/>\r\n   </Row>\r\n   <Row>\r\n    <Cell ss:MergeAcross=\"8\"><Data ss:Type=\"String\"><%= sdate %> to <%= edate %></Data></Cell>\r\n    <Cell ss:StyleID=\"s72\"/>\r\n   </Row>\r\n   <Row ss:Index=\"4\" ss:StyleID=\"s69\">\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">No</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Date</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Time</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">HN</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Patient\'s name</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\">Endosocpist</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Indication</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Diagnosis</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Intervention</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Intervention Summary</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">InterventionGroup</Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\">Complication</Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"/>\r\n   </Row>\r\n<%\r\n    idx = 1\r\n    arr.each do |i|\r\n%>\r\n   <Row ss:AutoFitHeight=\"0\" ss:Height=\"52\">\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= idx.to_s %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:op_date] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:time] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:hn] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:name] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:endo] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"><Data ss:Type=\"String\"><%= i[:indication] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= i[:diag] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= i[:inv_txt] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= i[:inv_sum] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= i[:inv_group] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s74\"><Data ss:Type=\"String\"><%= i[:complication] %></Data></Cell>\r\n    <Cell ss:StyleID=\"s68\"/>\r\n   </Row>\r\n<%\r\n        idx += 1\r\n    end\r\n%>\r\n  </Table>\r\n  <WorksheetOptions xmlns=\"urn:schemas-microsoft-com:office:excel\">\r\n   <PageSetup>\r\n    <Header x:Margin=\"0.3\"/>\r\n    <Footer x:Margin=\"0.3\"/>\r\n    <PageMargins x:Bottom=\"0.75\" x:Left=\"0.7\" x:Right=\"0.7\" x:Top=\"0.75\"/>\r\n   </PageSetup>\r\n   <Selected/>\r\n   <Panes>\r\n    <Pane>\r\n     <Number>3</Number>\r\n     <ActiveRow>5</ActiveRow>\r\n     <ActiveCol>1</ActiveCol>\r\n    </Pane>\r\n   </Panes>\r\n   <ProtectObjects>False</ProtectObjects>\r\n   <ProtectScenarios>False</ProtectScenarios>\r\n  </WorksheetOptions>\r\n </Worksheet>\r\n<%\r\n        end\r\n    end\r\n%>\r\n</Workbook>\r\n\r\n\r\n',NULL,NULL,NULL,'2019-02-06 07:09:02','2019-02-06 07:09:02','case_provider_excel',''),(3927,'document_name',1557,1,'\'staging\'',NULL,NULL,NULL,'2019-02-07 02:46:45','2019-02-07 02:46:45',NULL,NULL),(3928,'document_name',1558,1,'\'add_chemotherapy_mbc\'',NULL,NULL,NULL,'2019-02-07 02:59:00','2019-02-07 02:59:00',NULL,NULL),(3929,'document_name',1559,1,'\'plan_ma\'',NULL,NULL,NULL,'2019-02-07 03:00:24','2019-02-07 03:00:24',NULL,NULL),(3930,'form',1557,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    \r\n    $(document).ready(function(){\r\n       \r\n      var nlist = null;\r\n      var mlist = null;\r\n       \r\n      function resolve(status){\r\n       \r\n          v = $(\'#data-staging_type\').val();\r\n          \r\n          nl = [];\r\n          \r\n           $(\'#data-patho_n\').html(\"\");\r\n           $(\'#data-patho_m\').html(\"\");\r\n          $(\'#data-yp_n\').html(\"\");\r\n          $(\'#data-yp_m\').html(\"\");\r\n           \r\n        //   console.log(nlist.length)\r\n        //   for(var  id=0 ; inlist.length ){\r\n        //       i = id\r\n        //       console.log(id[0]);\r\n        //     //   alert(i)\r\n              \r\n        //   }\r\n\r\n          \r\n          nlist.each(function(){\r\n            vo = $(this)\r\n            if(vo.val().charAt(0)==v||vo.val().charAt(0)==\'M\'||vo.val()==\'\'){\r\n              $(\'#data-patho_n\').append(vo);\r\n            }\r\n          })\r\n          \r\n          mlist.each(function(){\r\n            vo = $(this)\r\n            if(vo.val().charAt(0)==v||vo.val().charAt(0)==\'M\'||vo.val()==\'\'){\r\n                $(\'#data-patho_m\').append(vo);\r\n            }\r\n          })\r\n          \r\n          nlist_yp.each(function(){\r\n            vo = $(this)\r\n            if(vo.val().charAt(0)==\'p\'||vo.val().charAt(0)==\'M\'||vo.val()==\'\'){\r\n                \r\n              $(\'#data-yp_n\').append(vo);\r\n            }\r\n          })\r\n          \r\n          mlist_yp.each(function(){\r\n            vo = $(this)\r\n            if(vo.val().charAt(0)==v||vo.val().charAt(0)==\'M\'||vo.val()==\'\'){\r\n                $(\'#data-yp_m\').append(vo);\r\n            }\r\n          })\r\n          \r\n          if(status==\'change\'){\r\n              $(\'#data-patho_t\').val(\'\')\r\n              $(\'#data-yp_t\').val(\'\')\r\n              $(\'#data-patho_n\').val(\'\')\r\n              $(\'#data-patho_m\').val(\'\')\r\n              $(\'#data-yp_n\').val(\'\')\r\n              $(\'#data-yp_m\').val(\'\')\r\n          }\r\n          \r\n          \r\n\r\n          \r\n        //   $(\'#data-patho_n\').html(nl);  \r\n          \r\n          \r\n          //$(\'#data-patho_n\').html(mlist);  \r\n          \r\n            \r\n          \r\n      }\r\n      \r\n      function cal(){\r\n          t = $(\'#data-patho_t\').val();\r\n          n = $(\'#data-patho_n\').val();\r\n          m = $(\'#data-patho_m\').val();\r\n          \r\n          k = \"\"+t.substring(0,2)+\"-\"+n.substring(1,3);\r\n        //   alert (k);\r\n          stages = []\r\n          stages.push([\'Ti-N0\',\'0\'])\r\n          stages.push([\'T1-N0\',\'IA\'])\r\n          stages.push([\'T0-Nm\',\'IB\'])\r\n          stages.push([\'T1-Nm\',\'IB\'])\r\n          stages.push([\'T0-N1\',\'IIA\']) \r\n          stages.push([\'T1-N1\',\'IIA\']) \r\n          stages.push([\'T2-N0\',\'IIA\']) \r\n          \r\n          stages.push([\'T2-N1\',\'IIB\']) \r\n          stages.push([\'T3-N0\',\'IIB\'])     \r\n          \r\n          stages.push([\'T0-N2\',\'IIIA\']) \r\n          stages.push([\'T1-N2\',\'IIIA\']) \r\n          stages.push([\'T2-N2\',\'IIIA\'])   \r\n          stages.push([\'T3-N1\',\'IIIA\'])\r\n          stages.push([\'T3-N2\',\'IIIA\'])\r\n\r\n          stages.push([\'T4-N0\',\'IIIB\']) \r\n          stages.push([\'T4-N1\',\'IIIB\']) \r\n          stages.push([\'T4-N2\',\'IIIB\'])  \r\n\r\n\r\n          stages.push([\'Tx-N3\',\'IIIC\']) \r\n          stages.push([\'Tis-N3\',\'IIIC\']) \r\n          stages.push([\'T1-N3\',\'IIIC\']) \r\n          stages.push([\'T2-N3\',\'IIIC\'])           \r\n          stages.push([\'T3-N3\',\'IIIC\']) \r\n          stages.push([\'T4-N3\',\'IIIC\']) \r\n          stages.push([\'T3-N3\',\'IIIC\'])  \r\n\r\n\r\n  \r\n          stage = \"\"\r\n          \r\n          for(var id in stages){\r\n              i = stages[id]\r\n              if(i[0]==k){\r\n                stage=i[1]\r\n              }\r\n          }\r\n          \r\n        \r\n          \r\n          if(m.substring(1)==\'M1\'){\r\n              stage=\'IV\'\r\n          }\r\n          \r\n          $(\'#data-ajcc_staging\').val(stage);\r\n          \r\n      }\r\n      \r\n      $(\'#data-staging_type\').change(function(){\r\n          resolve(\'change\');\r\n      })\r\n      $(\'#data-patho_t\').change(function(){\r\n          cal();\r\n      })\r\n      $(\'#data-patho_n\').change(function(){\r\n          cal();\r\n      })\r\n         $(\'#data-patho_m\').change(function(){\r\n          cal();\r\n      })\r\n          \r\n// YP staging\r\n\r\n  function calyp(){\r\n          t = $(\'#data-yp_t\').val();\r\n          n = $(\'#data-yp_n\').val();\r\n          m = $(\'#data-yp_m\').val();\r\n          \r\n          k = \"\"+t.substring(0,2)+\"-\"+n.substring(1,3);\r\n        //   alert (k);\r\n          stages = []\r\n          stages.push([\'Ti-N0\',\'0\'])\r\n          stages.push([\'T1-N0\',\'IA\'])\r\n          stages.push([\'T0-Nm\',\'IB\'])\r\n          stages.push([\'T1-Nm\',\'IB\'])\r\n          stages.push([\'T0-N1\',\'IIA\']) \r\n          stages.push([\'T1-N1\',\'IIA\']) \r\n          stages.push([\'T2-N0\',\'IIA\']) \r\n          \r\n          stages.push([\'T2-N1\',\'IIB\']) \r\n          stages.push([\'T3-N0\',\'IIB\'])     \r\n          \r\n          stages.push([\'T0-N2\',\'IIIA\']) \r\n          stages.push([\'T1-N2\',\'IIIA\']) \r\n          stages.push([\'T2-N2\',\'IIIA\'])   \r\n          stages.push([\'T3-N1\',\'IIIA\'])\r\n          stages.push([\'T3-N2\',\'IIIA\'])\r\n\r\n          stages.push([\'T4-N0\',\'IIIB\']) \r\n          stages.push([\'T4-N1\',\'IIIB\']) \r\n          stages.push([\'T4-N2\',\'IIIB\'])  \r\n\r\n\r\n          stages.push([\'Tx-N3\',\'IIIC\']) \r\n          stages.push([\'Tis-N3\',\'IIIC\']) \r\n          stages.push([\'T1-N3\',\'IIIC\']) \r\n          stages.push([\'T2-N3\',\'IIIC\'])           \r\n          stages.push([\'T3-N3\',\'IIIC\']) \r\n          stages.push([\'T4-N3\',\'IIIC\']) \r\n          stages.push([\'T3-N3\',\'IIIC\'])  \r\n\r\n\r\n  \r\n          stage = \"\"\r\n          \r\n          for(var id in stages){\r\n              i = stages[id]\r\n              if(i[0]==k){\r\n                stage=i[1]\r\n              }\r\n          }\r\n          \r\n        \r\n          \r\n          if(m.substring(1)==\'M1\'){\r\n              stage=\'IV\'\r\n          }\r\n          \r\n          $(\'#data-ajcc_after_treatment\').val(stage);\r\n          \r\n      }\r\n      \r\n\r\n      $(\'#data-yp_t\').change(function(){\r\n          calyp();\r\n      })\r\n      $(\'#data-yp_n\').change(function(){\r\n          calyp();\r\n      })\r\n         $(\'#data-yp_m\').change(function(){\r\n          calyp();\r\n      })\r\n      \r\n// Yp staging      \r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n          \r\n          \r\n          \r\n          \r\n          nlist = $(\'#data-patho_n option\').clone();\r\n          mlist = $(\'#data-patho_m option\').clone();\r\n          nlist_yp = $(\'#data-yp_n option\').clone();\r\n          mlist_yp = $(\'#data-yp_m option\').clone();\r\n          \r\n          console.log(nlist);\r\n         \r\n          \r\n          \r\n          \r\n        reso