label\">Confirm Password <span class=\"f_req\">*</span></label>\r\n	<div class=\"controls\">\r\n	    <%#= f.password_field :password, :class=>\'span10\' %>\r\n	    <%= f.password_field :c_password, :class=>\'span10\' %>\r\n		<span id=\"cpass\" class=\"help-block\">confirm account password</span>\r\n	</div>\r\n</div>\r\n\r\n\r\n</p>\r\n<br/>\r\n<!--<span class=\'btn btn-small\' id=\"btn_update\"><i class=\"splashy-pencil\"></i> <%=record[:_id]==\'\'?\'Create\':\'Update\'%></span> -->\r\n<button class=\'btn btn-small\' id=\"btn_update\"><i class=\"splashy-pencil\"></i> <%=record[:_id]==\'\'?\'Create\':\'Update\'%></button> \r\n|\r\n<%= link_to \'Back\', url(\'../../breast_cancer/Home/index\') %>\r\n<% end %>\r\n<script src=\"../../../gebo/lib/validation/jquery.validate.min.js\"></script>\r\n<script>\r\n$(\"#btn_update\").click(function(){\r\n    alert(\"aaa\");\r\n    if($(\"#pass\").val()!=$(\"#cpass\").val()){\r\n        alert(\"miss match\");\r\n    }else{\r\n        \r\n    }\r\n})\r\n	$(document).ready(function() {\r\n		gebo_validation.reg();\r\n	});\r\n	\r\n	//* validation\r\n	gebo_validation = {\r\n        reg: function() {\r\n            reg_validator = $(\'.form_validation_reg\').validate({\r\n				onkeyup: false,\r\n				errorClass: \'error\',\r\n				validClass: \'valid\',\r\n				highlight: function(element) {\r\n					$(element).closest(\'div\').addClass(\"f_error\");\r\n				},\r\n				unhighlight: function(element) {\r\n					$(element).closest(\'div\').removeClass(\"f_error\");\r\n				},\r\n                errorPlacement: function(error, element) {\r\n                    $(element).closest(\'div\').append(error);\r\n                },\r\n                rules: {\r\n					password: { required: true, minlength: 6 },\r\n					c_password: { required: true, minlength: 6 },\r\n				},\r\n                invalidHandler: function(form, validator) {\r\n					$.sticky(\"There are some errors. Please corect them and submit again.\", {autoclose : 5000, position: \"top-right\"