cument.body\r\n}).done(function(data) {\r\n  $( \'#r<%=i.id%>\' ).html(data);\r\n});\r\n        </script>\r\n        \r\n    </td>\r\n    \r\n    <td id=\"r<%=i.id%>\">\r\n    ...\r\n    </td>\r\n    </tr>\r\n<%    \r\n \r\n    end\r\n%>  \r\n</tbody>\r\n</table>\r\n<%= link_to \'Back\', \"../Home/index\", :class=>\'btn\' %> \r\n\r\n\r\n',NULL,NULL,NULL,'2019-02-07 14:20:21','2019-02-07 14:20:21','interactive_transaction',''),(3937,'document_name',1561,1,'\'invoice\'',NULL,NULL,NULL,'2019-02-08 01:18:03','2019-02-08 01:18:03',NULL,NULL),(3938,'process',1561,2,'<%\r\n    result= {}\r\n    \r\n    models = get_model\r\n    \r\n    transactions = models[:transaction].find params[:transaction]\r\n    \r\n    \r\n    acc = {}\r\n    \r\n    for i in transactions\r\n    \r\n        acc_code = i.qccoor# QCCOOR\r\n    \r\n        unless acc[acc_code]\r\n            acc[acc_code] = {:acc_code=>acc_code, :project_id=>i.project_id, :items=>[],:amount=>0}\r\n        end\r\n          acc[acc_code][:amount]+= i.amt\r\n          acc[acc_code][:items] << i\r\n        \r\n    end\r\n    \r\n    acc.each_pair do |k,v|\r\n       project = models[:project].find v[:project_id]\r\n       invoice = models[:invoice].create :acc_code=>v[:acc_code], :amount=>v[:amount], :customer_id=>project.customer_id, :project_id=>project.id, :status=>\'Completed\', :date=>Time.now\r\n       for i in v[:items]\r\n       \r\n        i.update_attributes :invoice_id=>invoice.id\r\n       \r\n        end\r\n        \r\n    end\r\n    \r\n    \r\n%>\r\n\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Home/index\" />',NULL,NULL,NULL,'2019-02-08 02:03:46','2019-02-08 02:03:46','process',''),(3939,'show',1561,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n    models = get_model\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n<%= link_to \'Back\', return_url %>\r\n\r\n<%\r\n    \r\n    transactions = models[:transaction].where(:invoice_id=>params[:id]).all\r\n    \r\n%>\r\n<hr/>\r\n<h3>Transactions</h3>\r\n<br/>\r\n<table class=\"table\">\r\n<%\r\nfor i in transactions\r\n%>\r\n<tr>\r\n<%\r\nfor j in %w{reftype date refno amt qccoor} \r\n%>\r\n<td><%=link_to i[j], \"../Visit/show?id=\\\\#{i.visit_id}\", :target=>\'_blank\'  %></td>   \r\n<% end %>\r\n</tr>\r\n<% end %>\r\n</table>\r\n\r\n\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2019-02-08 02:26:12','2019-02-08 02:26:12','show',''),(3940,'admin_accounting',1272,3,'\r\n<%\r\n\r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n\r\n\r\n\r\n    models = get_model\r\n  \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-\"+params[:report][\'from_date(3i)\'] if params[:report]\r\n\r\n    from_date = Date.to_mongo(from_date)\r\n    # from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-\"+params[:report][\'to_date(3i)\'] if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    # to_date = to_date.end_of_month\r\n%>\r\n <% if request.post? \r\n \r\n    start_date = from_date.beginning_of_day#select_date.beginning_of_month()\r\n    stop_date = to_date.end_of_day#select_date.end_of_month()\r\n    \r\n    %>\r\n\r\n    <b>Result : </b><%=start_date %> - <%= stop_date %> , <b>RefNo : </b><%=params[:report][:refno]%><br/><br/>\r\n    <%\r\n    cond = {}\r\n    \r\n    if params[:report][:refno] and  params[:report][:refno].size>0 \r\n        \r\n        \r\n    cond = {:refno=>params[:report][:refno]}\r\n        \r\n    else\r\n \r\n    cond = {:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}}\r\n    \r\n    end\r\n    \r\n     if params[:report] and ( params[:report][:ref_type]==\'SO\' or params[:report][:ref_type]==\'BV\')\r\n       \r\n       cond.merge!  :reftype=>params[:report][:ref_type]\r\n        \r\n    end\r\n        \r\n       \r\n    transactions =  models[:transaction].where(cond).all\r\n    \r\n    map = {}\r\n    items =  models[:transaction_item].where(:transaction_id=>{\'$in\'=>transactions.collect{|i| i.id}}).all\r\n    for i in items\r\n        \r\n        map[i.transaction_id] = [] unless map[i.transaction_id]\r\n        map[i.transaction_id] << i\r\n    \r\n    end\r\n\r\n    list1 = %w{reftype date refno amt qccoor -  -  remarkh1 remarkh2 remarkh3 remarkh4 remarkh5 }\r\n\r\n\r\n    list2 = %w{reftype -    refno amt qcprod qty price remarkh1 remarkh2 remarkh3 remarkh4 remarkh5 }\r\n\r\n\r\n    \r\n %>\r\n <%=form_for :invoice, :url=>\'../Invoice/process\' do |f| %>\r\n <table class=\"table\">\r\n     <thead>\r\n         <tr><th>No.</th>\r\n             <th>RefType</th> <th>Date</th>  <th>RefNo</th>  <th>Amount</th>  <th>QCProd</th>  <th>QTY</th>  <th>Price</th>  <th>Remark H1</th><th>Remark H2</th><th>Remark H3</th><th>Remark H4</th><th>Remark H5</th><th>Invoice</th>\r\n         </tr>\r\n     </thead>\r\n     <tbody>\r\n     <% transactions.each_with_index do|i,iindex|\r\n        items = map[i.id]\r\n        amt = i[\'amt\']\r\n        %>\r\n         <tr>\r\n            <td><%=iindex+1%>.</td>\r\n            <% for k in list1 %>\r\n             <td><%=link_to i[k],\"../Visit/transaction?id=\\\\#{i.visit_id}\", :target=>\'_blank\'  if k!=\'-\' and i[k] and i[k].to_s.size>0%></td>\r\n             <% end %>\r\n             <td><% if i.invoice_id \r\n             \r\n            \r\n             %>\r\n                 <%=link_to \"Invoice\",\"../Invoice/show?id=\\\\#{i.invoice_id}\",:target=>\'_blank\',:class=>\'btn btn-info\' if i.invoice_id%>\r\n                 <% else %>\r\n                 <%= check_box_tag \'transaction[]\', i.id %>\r\n                 <% end %>\r\n             </td>\r\n         </tr>\r\n         \r\n         <%\r\n            if params[:report][:show_detail]==\'1\'\r\n         \r\n         items.each_with_index do|j,jindex| %>\r\n         <tr style=\"background:#eee\">\r\n            <td><%=jindex+1%>.</td>\r\n             <% for k in list2 %>\r\n             <td><%=j[k] if k!=\'-\'%></td>\r\n             <% end %>\r\n             <td></td>\r\n         </tr>\r\n         <% end %>\r\n         <tr>\r\n             <td>\r\n                 \r\n             </td>\r\n             <td>\r\n                 \r\n             </td>\r\n                <td>\r\n              <%=   i[\'date\']%>\r\n             </td>\r\n             <td>\r\n                <%= i[\'refno\'] %>\r\n             </td>\r\n             <td><%=fm amt%></td>\r\n             <td colspan=\"8\">\r\n                 \r\n             </td>\r\n         </tr>\r\n         \r\n      <% end %>\r\n         \r\n      <% end %>\r\n     </tbody>\r\n </table>\r\n<%= f.submit \'Create Invoice\', :class=>\'btn btn-success\' %>\r\n     <% end %>\r\n \r\n <% end %>',NULL,NULL,NULL,'2019-02-08 02:56:58','2019-02-08 02:56:58','admin_accounting',''),(3941,'show',1409,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<style>\r\n    .document-border {border:1px solid #ccc;background:#fcfcfc;padding:0px;width:750px}\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\