n    <script>\r\n            \r\n         res = confirm(\"Someone is editing this document. Would you like to override the record?\");\r\n        if(res==true){\r\n            \r\n            \r\n            // $(\'#ref_number\').parent().append(\"<input type=\'text\' name=\'override\' value=\'override\' />\");\r\n            // $(\'#ref_number\').remove();\r\n           $(document).ready(function(){\r\n              $(\'#ref_number\').parent().append(\"<input type=\'hidden\' name=\'override\' value=\'override\' />\");\r\n               \r\n           })\r\n            // $(\'<input>\').attr(\'type\',\'text\').attr(\'name\',\'override\').attr(\'value\',\'override\').appendTo(\'form\');\r\n            \r\n            \r\n        }else\r\n            window.location = \"<%=return_url%>\";\r\n\r\n\r\n\r\n        \r\n    </script>\r\n    <%\r\n        end\r\n    else\r\n    \r\n    locker = locker_model.create({:session=>session[:user].to_s,:reference_id=>params[:return],:module_id=>@patient_module.parent_id.to_s,:module_name=>this.table_name,:status=>\'edit\'})\r\n    \r\n    end\r\n  \r\n    end\r\n  \r\n     \r\n    t = Time.now - record.updated_at \r\n \r\n \r\n    if  false and  @current_role!=\'superuser\' and @current_role!=\'developer\' and @current_role!=\'admin\' # and t.to_i > 3600 * 24 \r\n     locker.destroy if locker\r\n  %>\r\n   <script>alert(\"Not allowed to edit this document!!\");window.location = \"<%=return_url%>\";</script>\r\n  <%\r\n  end\r\n  \r\n  if request.post?\r\n  \r\n    locker.destroy if locker\r\n  \r\n    doc = get_document this.document_name\r\n      \r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n<style>\r\n    .refinfo{background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc}\r\n</style>\r\n <div class=\"refinfo\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right refdate\" >\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%\r\n    if return_url.include? \'?\'\r\n        return_url += \"&reset_lock=\\#{locker.id}\"\r\n    else\r\n        return_url += \"?reset_lock=\\#{locker.id}\"\r\n    end\r\n%>\r\n<%= f.submit \"Update\".html_safe, :class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n<%= link_to \'Cancel\', return_url,:data=>{:confirm=>\'Are you sure?\'} %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    $(\"#record-time\").kendoTimePicker({  \r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n</script>   ',NULL,NULL,NULL,'2019-02-08 06:40:29','2019-02-08 06:40:29','edit',''),(3943,'index',1409,2,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<center><h1>Gasmotin Project</h1>\r\n<br/>\r\n<div class=\"row-fluid\">\r\n    <div class=\"span12\">\r\n     \r\n        <%= form_for :search, :url=>\'partial?update=search\', :data=>{:remote=>true} do |f| %>\r\n        \r\n        HN : <%= f.text_field :query, :value=>\'\' %>\r\n        \r\n        <%= f.submit \'Search\' %>\r\n        \r\n        <% end %>\r\n                \r\n    </div>\r\n</div>\r\n</center>\r\n<div id=\"search\"></div>\r\n<%\r\n    \r\n    date = Time.now\r\n    date = Date.parse(params[:date]) if params[:date]\r\n    \r\n    \r\n%>\r\n\r\n\r\n<h3>Gasmotin Records for <%=text_field_tag \"date\", date.strftime(\"%d/%m/%Y\"), :id=>\'select_date\' %>\r\n\r\n : </h3>\r\n<script>\r\n	$(\"#select_date\").kendoDatePicker({\r\n		value: \'<%= date.strftime(\"%d/%m/%Y\") if date %>\',\r\n	});\r\n	\r\n	$(\"#select_date\").change(function(){\r\n	  	obj = $(this)\r\n		v = obj.val()\r\n        window.location=\"gasmotin?date=\"+v;\r\n	});\r\n</script>\r\n<%\r\n    \r\n    name_gasmotin = @current_project.name+\'#gasmotin\' \r\n\r\n\r\n    m_records = @module_model.where(:module_name=>name_gasmotin, :created_at=>{\'$gte\'=>date.beginning_of_day,\'$lte\'=>date.end_of_day}).all\r\n    list = []\r\n    \r\n    for i in m_records\r\n    \r\n    age = 0\r\n    \r\n    r = @models[:gasmotin].find i.module_id\r\n    endoscopist_1 = nil\r\n    date_note = nil\r\n    if r \r\n    patient = @patient_model.find i.patient_id\r\n    \r\n       age = r.age\r\n       date_note = r.date_note\r\n       \r\n       endoscopist_1 = @models[:provider].find r.endoscopist_1\r\n       \r\n       if endoscopist_1\r\n           \r\n          endoscopist_1 = endoscopist_1.name\r\n   else\r\n       \r\n       endoscopist_1 = \'-\'\r\n       end\r\n   \r\n    # date = Time.now\r\n    # if r\r\n    #     quality_of_preparate = r.quality_of_preparate\r\n    #     date = r.date_note\r\n    #     endoscopist = r.endoscopist_1\r\n    # end\r\n    \r\n    # age = ((date - patient.birth_date.to_datetime)/365.0).to_i if patient.birth_date\r\n    # # age = patient.birth_date\r\n\r\n    list << {:id=>i.id, :hn=>patient.hn,:gender=> patient.gender,:parent_id=> i.parent_id,:age=>age, :name=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\", :date=>date_note, :endoscopist_1=>endoscopist_1}\r\n end\r\n    end\r\n\r\n%>\r\n<%= tabular :data=>list, :model=>%w{hn name gender age  endoscopist_1 date }.collect{|i| i.to_sym } do |row,out| \r\n      \r\n        out << link_to(\"Edit\", \"../Gasmotin/edit?id=\\\\#{row[:id]}\", :class=>\'btn btn-info\')\r\n\r\n\r\nout \r\nend\r\n%>\r\n<i><%=list.size%> records</i>\r\n\r\n',NULL,NULL,NULL,'2019-02-08 06:42:45','2019-02-08 06:42:45','index',''),(3944,'partial',1409,3,'<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n\r\n    \r\n    # patient search\r\n    \r\n    # search for all colono records for a patient\r\n    \r\n    # sort by date\r\n    if request.post?\r\n        \r\n    q = params[:search][:query] \r\n    \r\n    patient = @patient_model.where(:hn=>q).first\r\n  \r\n    \r\n   if patient \r\n   \r\n    # 45678/77\r\n    name = @current_project.name+\'#colonoscopy\' \r\n    list = []\r\n    records = @module_model.where(:module_name=>name, :patient_id=>patient.id).all\r\n    \r\n    for i in records\r\n    age = 0 \r\n    r = @models[:colonoscopy].find i.module_id\r\n    quality_of_preparate = \'\'\r\n    endoscopist = nil\r\n    date = Time.now\r\n    if r\r\n        quality_of_preparate = r.quality_of_preparate\r\n        date = r.date_note\r\n   \r\n        endoscopist = r.endoscopist_1\r\n        \r\n        endoscopist =  @models[:provider].find(endoscopist).name\r\n        \r\n    end\r\n    \r\n    age = ((date - patient.birth_date.to_datetime)/365.0).to_i if patient.birth_date and date\r\n    # age = patient.birth_date\r\n\r\n    list << {:colo_id=>r.id, :start_at=>r.start_at,:hn=>patient.hn,:gender=> patient.gender,:start_to_scope_at=>r.start_scope_at,:parent_id=> i.parent_id,  :name=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\", :age=>age, :date=>date, :quality_of_preparate=>quality_of_preparate, :endoscopist=>endoscopist}\r\n    \r\n    end\r\n%>\r\n<h3>\r\n    Search Result : \r\n</h3>\r\n<%= tabular :data=>list, :model=>%w{hn name gender age quality_of_preparate endoscopist date }.collect{|i| i.to_sym } do |row,out| \r\n\r\n    name_gasmotin = @current_project.name+\'#gasmotin\' \r\n    \r\n    # row[5] = @models[:provider].find(row[:endoscopist]).name\r\n\r\n    m_gasmotin = @module_model.where(:module_name=>name_gasmotin, :parent_id=>row[:parent_id]).first\r\n    \r\n    if m_gasmotin\r\n    \r\n        out << link_to(\"Edit\", \"../Gasmotin/edit?id=\\\\#{m_gasmotin.id}\", :class=>\'btn btn-info\')\r\n\r\n    else    \r\n        out << link_to(\"Create\", \"../Gasmotin/create?colo_id=\\\\#{row[:colo_id]}&patient_id=\\\\#{patient.id}&parent_id=\\\\#{row[:parent_id]}&data[age]=\\\\#{row[:age]}\", :class=>\'btn btn-success\')\r\n    \r\n    end\r\n\r\nout\r\nend\r\n%>\r\n\r\n<% else %>\r\n<div class=\"alert\">\r\n    Patient not found \r\n</div>\r\n<% end %>\r\n<% end %>\r\n\r\n',NULL,NULL,NULL,'2019-02-12 01:21:42','2019-02-12 01:21:42','partial',''),(3945,'month_sum_report',1098,2,'<h1>Procedure Report</h1>\r\n<%= render :inline=>this.init %>\r\n\r\n<style>\r\n    select{\r\n        width:100px;\r\n    }\r\n    \r\n  \r\n</style>\r\n\r\n<%\r\n\r\n     month_th = %w{ มกราคม กุมภาพันธ์ มีนาคม เมษายน พฤษภาคม มิถุนายน กรกฎาคม สิงหาคม กันยายน ตุลาคม พฤศจิกายน ธันวาคม}\r\n     month_short_th = %w{ ม.ค. ก.พ. มี.ค. เม.ย. พ.ค. มิ.ย. ก.ค. ส.ค. ก.ย. ต.ค. พ.ย. ธ.ค. }\r\n\r\n\r\n\r\n    models = get_model\r\n    forms = %w{colonoscopy gastroscopy ercp eus}\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] #patient_model.all :select=>[:date]\r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n    \r\n    from_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    from_date = params[:report][\'from_date(1i)\']+\"-\"+params[:report][\'from_date(2i)\']+\"-15\" if params[:report]\r\n    from_date = Date.to_mongo(from_date)\r\n    from_date = from_date.beginning_of_month\r\n    \r\n   \r\n    to_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    to_date = params[:report][\'to_date(1i)\']+\"-\"+params[:report][\'to_date(2i)\']+\"-15\" if params[:report]\r\n    to_date = Date.to_mongo(to_date)\r\n    to_date = to_date.end_of_month\r\n%>\r\n\r\n<%=form_for \'report\' do |f| %>\r\nFrom : <%= f.date_select :from_date, :default=>from_date ,:discard_day=>true , :order=>[:month,:year]%>\r\n\r\nTo : <%= f.date_select :to_date, :default=>to_date ,:discard_day=>true , :order=>[:month,:year]%>\r\n\r\n<%= f.submit \'Query\' ,:class=>\'btn\'%>\r\n<% end %>\r\n\r\n\r\n\r\n <% if request.post? \r\n \r\n \r\n    # select_date = Time.now.strftime(\"%Y-%m-%d\")\r\n    # select_date = params[:report][\'date(1i)\']+\"-\"+params[:report][\'date(2i)\']+\"-15\" if params[:report]\r\n    # select_date = Date.to_mongo(select_date)\r\n    start_date = from_date#select_date.beginning_of_month()\r\n    stop_date = to_date#select_date.end_of_month()\r\n    \r\n    \r\n\r\n    pname = \"\\\\#{@current_project.name}#\"\r\n    out = {}\r\n    \r\n    def bmap objs, id=\'_id\'\r\n        map = {}\r\n        for i in objs\r\n            map[i[id]] = [] unless map[i[id]] \r\n            map[i[id]] << i\r\n        end\r\n        return map\r\n    end\r\n    \r\n    # all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}},{:fields=>{\'_id\'=>1,\'date\'=>1,\'status\'=>1,\'visit_type\'=>1}}).to_a\r\n    all_app =  @models[:appointment].collection.find({:date=>{\'$gte\'=>start_date,\'$lt\'=>stop_date}}).to_a\r\n\r\n    \r\n    \r\n    all_pm_app = @m_patient_module.collection.find({:module_name=>\"\\\\#{pname}appointment\",:module_id=>{\'$in\'=>all_app.collect{|i| i[\'_id\']}}}).to_a\r\n    m_all_pm_app = bmap all_pm_app, \'module_id\'\r\n \r\n\r\n    visits = @models[:visit_type].collection.find().to_a\r\n    m_visit = bmap visits, \'_id\'\r\n    \r\n    providers = @models[:provider].collection.find().to_a\r\n    m_providers = bmap providers, \'_id\'\r\n\r\n    procedures = @models[:procedure].collection.find().to_a\r\n    m_procedures = bmap procedures, \'_id\'\r\n\r\n    l_procedures = procedures.collect{|i| i[\'name\'] if i[\'name\']!=\'EGD & Colonoscopy\'}.compact\r\n    \r\n    # l_procedures << \"Total\"\r\n    \r\n   \r\n    \r\n    \r\n    %>\r\n\r\n<%\r\n  \r\n    \r\n    colors = {\'Elective\'=>\'#deffde\',\'Extratime\'=>\'#dedeff\',\'Emergency\'=>\'ffdede\',\'Total\'=>\'dedede\'}         \r\n    \r\n%>\r\n\r\n<%#= all_app.inspect %>\r\n<%#= pd_count.inspect %>\r\n\r\n\r\n<% \r\n\r\n    # month_text = select_date.strftime(\"%B-%Y\")\r\n\r\n%>\r\n<div id=\"printableArea\">\r\n<style>\r\n \r\n    td.Elective{\r\n        text-align:center;\r\n        background:#deffde;\r\n        width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Extratime{\r\n        text-align:center;\r\n        background:#dedeff;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.Emergency{\r\n        text-align:center;\r\n        background:#ffdede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    td.total{\r\n        text-align:center;\r\n        background:#dedede;\r\n            width:25px;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n           td.total2{\r\n        text-align:center;\r\n        background:#efefef;\r\n        width:25px;\r\n        text-decoration: underline;\r\n        /*padding:5px 10px 5px 10px;*/\r\n    }\r\n    .tx{\r\n        text-align:center; \r\n        /*font-weight: bold;*/\r\n    }\r\n    td.date{\r\n        padding:5px 10px 5px 10px;\r\n        \r\n        \r\n        \r\n    }\r\n    \r\n    table {\r\n          border-collapse: collapse;\r\n    }\r\n    .weekend{\r\n         background:#cccccc;\r\n    }\r\n    @media print {\r\n    \r\n    .content{\r\n        font-size:0.5em;\r\n    }    \r\n        \r\n    }\r\n\r\n    \r\n</style>\r\n\r\n\r\n<%\r\n\r\nfrom_text =  month_th[from_date.month-1]+from_date.strftime(\"-%Y\")\r\n\r\nto_text =  month_th[to_date.month-1]+to_date.strftime(\"-%Y\")\r\n \r\ntmp_date =  from_date\r\nshow_month = []\r\nrange_month = []\r\nwhile tmp_date < to_date\r\n    m_text_show = \"\"\r\n    m_text_show = month_short_th[tmp_date.month-1]\r\n    m_text_show += tmp_date.strftime(\"%y\") #if params[:report][\'from_date(1i)\']!=params[:report][\'to_date(1i)\']\r\n    show_month << m_text_show\r\n    range_month << [tmp_date.beginning_of_month,tmp_date.end_of_month]\r\n    tmp_date += 1.month\r\nend\r\nshow_month << \"Total\"\r\n\r\n    l_pv = []\r\n    l_pv = all_app.uniq{|i| i[\'provider\']}.collect{|i| [m_providers[i[\'provider\']][0][\'name\'],i[\'provider\']]}.sort{|a,b| a[0]<=>b[0]}\r\n\r\n\r\n%>\r\n<%#=l_pv.inspect%><br/>\r\n<%#=all_app.first.inspect%>\r\n<center><h3>\r\nรายงานจำนวนผู้เข้ารับบริการ \r\n<%=@current_project.get_setting \'report_title_1\' %>\r\n<br/>\r\n<%=@current_project.get_setting \'report_title_2\' %></h3>\r\n<br/>\r\n<h4>แยกตามประเภทการรักษา ระหว่างวันที่ \r\n    <%=from_text %> - <%= to_text %>\r\n</h4></center>\r\n\r\n<br/>\r\n<%\r\n    pc_count = {}\r\n    for pc in l_procedures \r\n        pc_app = all_app.collect{|i| i if m_procedures[i[\'procedure\']][0][\'name\'].include?(pc)}.compact\r\n        pc_count[pc] = {} unless pc_count[pc]\r\n        show_month.each_with_index{|j,n|\r\n            tmp_count = []\r\n            if j==\'Total\'\r\n                pc_count[pc][j] = pc_app.size\r\n            else\r\n                r = range_month[n] if range_month[n]\r\n                tmp_count = pc_app.collect{|i| i if i[\'date\']>=r[0] and i[\'date\']<=r[1]}.compact\r\n                pc_count[pc][j] = tmp_count.size\r\n            end\r\n        }\r\n    end\r\n    \r\n    pv_count = {}\r\n    for pv in l_pv\r\n        pv_app = all_app.collect{|i| i if i[\'provider\']==pv[1]}.compact\r\n        pv_count[pv[0]] = {} unless pv_count[pv[0]]\r\n        show_month.each_with_index{|j,n|\r\n            tmp_count = []\r\n            if j==\'Total\'\r\n                tmp_num = 0\r\n                for i in pv_app \r\n                    if m_procedures[i[\'procedure\']][0][\'name\'].include?(\'&\')\r\n                        tmp_num += 2\r\n                    else\r\n                        tmp_num += 1\r\n                    end\r\n                end\r\n                pv_count[pv[0]][j] = tmp_num\r\n            else\r\n                r = range_month[n] if range_month[n]\r\n                tmp_count = pv_app.collect{|i| i if i[\'date\']>=r[0] and i[\'date\']<=r[1]}.compact\r\n                tmp_num = 0\r\n                for i in tmp_count \r\n                    if m_procedures[i[\'procedure\']][0][\'name\'].include?(\'&\')\r\n                        tmp_num += 2\r\n                    else\r\n                        tmp_num += 1\r\n                    end\r\n                end\r\n                pv_count[pv[0]][j] = tmp_num\r\n            end\r\n        }\r\n    end\r\n\r\n    \r\n\r\n%>\r\n<table border=\"1\" class=\"content\">\r\n\r\n<tr style=\"background-color:#dedeff\"><th>Procedures</th>\r\n    <% for j in show_month %>\r\n    <th><%=j%></th>\r\n    <% end %>\r\n</tr>\r\n<% \r\n    sum = {}\r\n    for pc in l_procedures \r\n%>\r\n<tr>\r\n    <td><%=pc%></td>\r\n    <% \r\n        for j in show_month \r\n            sum[j] = 0 unless sum[j]\r\n            sum[j] += pc_count[pc][j] if pc_count[pc][j]\r\n    %>\r\n    <td class=\"<%=(j==\'Total\')?\'total\':\'tx\'%>\"><%=pc_count[pc][j] if pc_count[pc][j] %></td>\r\n    <%  end %>\r\n</tr>\r\n<% end %>\r\n\r\n<tr>\r\n    <td>Total</td>\r\n    <% for j in show_month %>\r\n    <td class=\"total2\"><%=sum[j] %></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n\r\n<br/>\r\n<hr/>\r\n<table border=\"1\" class=\"content\">\r\n\r\n<tr style=\"background-color:#dedeff\"><th>Endoscopist</th>\r\n    <% for j in show_month %>\r\n    <th><%=j%></th>\r\n    <% end %>\r\n</tr>\r\n<% \r\n    sum = {}\r\n    for pv in l_pv \r\n%>\r\n<tr>\r\n    <td><%=pv[0]%></td>\r\n    <% \r\n        for j in show_month \r\n            sum[j] = 0 unless sum[j]\r\n            sum[j] += pv_count[pv[0]][j] if pv_count[pv[0]][j]\r\n    %>\r\n    <td class=\"<%=(j==\'Total\')?\'total\':\'tx\'%>\"><%=pv_count[pv[0]][j] if pv_count[pv[0]][j]%></td>\r\n    <%  end %>\r\n</tr>\r\n<% end %>\r\n\r\n<tr>\r\n    <td>Total</td>\r\n    <% for j in show_month %>\r\n    <td class=\"total2\"><%=sum[j] %></td>\r\n    <% end %>\r\n</tr>\r\n</table>\r\n<br/>\r\n<hr/>\r\n<input type=\"button\" onclick=\"printDiv(\'printableArea\')\" value=\"Print\" class=\"btn\" />\r\n\r\n\r\n<% end %>\r\n\r\n<script>\r\n    function printDiv(divName) {\r\n     var printContents = document.getElementById(divName).innerHTML;\r\n     var originalContents = document.body.innerHTML;\r\n\r\n     document.body.innerHTML = printContents;\r\n\r\n     window.print();\r\n\r\n     document.body.innerHTML = originalContents;\r\n}\r\n</script>\r\n\r\n',NULL,NULL,NULL,'2019-02-12 03:46:53','2019-02-12 03:46:53','month_sum_report',''),(3946,'patient_status',1278,3,'<%\r\n\r\n    models = get_model\r\n       \r\n           \r\n    patient = models[:patient].find params[:patient_id]\r\n   \r\n   if patient\r\n      \r\n      patient.update_attributes :status=>params[:status]\r\n       \r\n   end\r\n    \r\n        \r\n\r\n%>\r\n\r\n<meta http-equiv=\"refresh\" content=\"0; url=<%=\"show?id=\\\\#{params[:id]}\"%>\" />',NULL,NULL,NULL,'2019-02-12 06:22:14','2019-02-12 06:22:14','patient_status',''),(3947,'document_name',1562,1,'\'follow_up_backup\'',NULL,NULL,NULL,'2019-02-14 05:57:19','2019-02-14 05:57:19',NULL,NULL),(3948,'print_traveling',1385,3,'<%\r\n\r\n    models = get_model\r\n    payment_name = \"นางสาวธัญญ์นลิน ธนาเศรษฐ์สุข\"\r\n    \r\n    visit = models[:visit].find params[:id]\r\n    patient = models[:patient].find visit.patient_id\r\n    \r\n    patient_name = \"\\\\#{patient.prefix_name}\\\\#{patient.first_name} \\\\#{patient.last_name}\"\r\n    patient_id_card = \"-\"\r\n    patient_id_card = patient.personal_id if patient.personal_id and patient.personal_id.size > 0 \r\n    \r\n    project = models[:project].find visit.project_id\r\n    traveling_amount = 0\r\n    traveling_extra = 0\r\n    traveling_amount = visit.traveling_amount if visit.traveling_amount\r\n    traveling_extra = visit.traveling_extra if visit.traveling_extra\r\n    total_amount = traveling_amount + traveling_extra\r\n    \r\n    text = \"\"\r\n    text = \"ห้าร้อยบาทถ้วน\" if total_amount==500\r\n    text = \"หนึ่งพันบาทถ้วน\" if total_amount==1000\r\n    text = \"หนึ่งพันห้าร้อยบาทถ้วน\" if total_amount==1500\r\n    text = \"สองพันบาทถ้วน\" if total_amount==2000\r\n    text = \"สองพันห้าร้อยบาทถ้วน\" if total_amount==2500\r\n    text = \"่สามพันบาทถ้วน\" if total_amount==3000\r\n\r\n\r\n    \r\n    \r\n    \r\n%>\r\n\r\n<html>\r\n    <head>\r\n        \r\n    </head>\r\n    <body >\r\n    <html xmlns:v=\"urn:schemas-microsoft-com:vml\"\r\nxmlns:o=\"urn:schemas-microsoft-com:office:office\"\r\nxmlns:x=\"urn:schemas-microsoft-com:office:excel\"\r\nxmlns=\"http://www.w3.org/TR/REC-html40\">\r\n\r\n<head