_visit = \'\'\r\n            if period\r\n                period_visit = period.visit\r\n            end\r\n            \r\n            today_visits_x << {:status=> i.traveling_status, :project=>p,:protocol_no=>p.protocol_no, :patient=>patient, :name=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\", :hn=>patient.hn,:subject_no=>patient.subject_id,\r\n                :visit=>i, :visit_type=>i.visit_type, :date=>\"\\\\#{i.date.strftime(\"%d/%m/%Y\") if i.date}\", :sheet=>sheet, :period=>period, :period_name=> period_visit\r\n            }\r\n        \r\n        end\r\n    \r\n        for i in pending_visits\r\n        \r\n            patient = models[:patient].find i.patient_id\r\n            \r\n            sheet = models[:pl_sheet].find patient.sheet_id\r\n            p = models[:project].find i.project_id\r\n            \r\n            unless sheet \r\n                \r\n             visit = models[:visit].where(:patient_id=>patient.id, :sheet_id=>{\'$ne\'=>nil}).first\r\n             sheet = models[:pl_sheet].find visit.sheet_id\r\n             visit = nil\r\n\r\n            end\r\n            \r\n            period = models[:pl_period].find i.period_id\r\n            period_visit = \'\'\r\n            if period\r\n                period_visit = period.visit\r\n            end\r\n            \r\n            pending_visits_x << {:status=> i.traveling_status, :project=>p,:protocol_no=>p.protocol_no, :patient=>patient, :name=>\"\\\\#{patient.first_name} \\\\#{patient.last_name}\", :hn=>patient.hn,:subject_no=>patient.subject_id,\r\n                :visit=>i, :visit_type=>i.visit_type, :date=>\"\\\\#{i.date.strftime(\"%d/%m/%Y\") if i.date}\", :sheet=>sheet, :period=>period, :period_name=> period_visit\r\n            }\r\n        \r\n        end\r\n        \r\n        \r\n          for i in completed_visits\r\n        \r\n            patient = models[:patient].find i.patient_id\r\n            \r\n            sheet = models[:pl_sheet].find patient.sheet_id\r\n 