us\r\n                </th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n          <%\r\n          list = today_visits_x\r\n        if list.size > 0 \r\n        for i in list\r\n    %>\r\n    <tr>\r\n        <td>\r\n            <%=link_to i[:protocol_no], \"../Project/show?id=\\\\#{i[:project].id}\" %>\r\n        </td>\r\n        \r\n          \r\n        <td>\r\n            <%=link_to i[:date], \"../Visit/show?id=\\\\#{i[:visit].id}\" %>\r\n        </td>\r\n        \r\n        \r\n        <td>\r\n            <%=link_to i[:subject_no], \"../Patient/show?id=\\\\#{i[:patient].id}\" %>        </td>\r\n        <td>\r\n            <%=link_to i[:name], \"../Patient/show?id=\\\\#{i[:patient].id}\" %>\r\n        </td>\r\n        \r\n        \r\n     \r\n        <td>\r\n            <%=\"\\\\#{i[:period_name]}\"%>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=fn i[:visit].traveling_amount %> /   <%=fn i[:visit].traveling_extra %>\r\n        </td>\r\n        \r\n        \r\n        <td>\r\n        \r\n            <%=link_to \"Print\", \"../Visit/print_traveling?id=\\\\#{i[:visit].id}\", :class=>\'btn  btn-mini\',:target=>\'_blank\'%>\r\n            <%#link_to \"Work List\", \"../Visit/print?id=\\\\#{i[:visit].id}\", :class=>\'btn btn-mini\', :target=>\'_blank\' if i[:visit_type]!=\'UNSCHEDULE\' %>\r\n          \r\n        </td>\r\n        <td>\r\n            <%= i[:visit].traveling_status if i[:visit].traveling_status!=\'Pending\' %>\r\n            <%=link_to \"Payment\", \"#\",:vid=>i[:visit].id, :amount=>i[:visit].traveling_amount, :extra=>i[:visit].traveling_extra, :class=>\'payment_btn btn btn-success btn-mini\' if i[:visit].traveling_status==\'Pending\' %>\r\n\r\n        </td>\r\n      \r\n        \r\n    </tr>\r\n   <% end %>\r\n    <% end %>\r\n        </tbody>\r\n</table>\r\n\r\n\r\n    <h3>Complete</h3>\r\n\r\n	            \r\n	             <table class=\"table\">\r\n        <thead>\r\n            <tr>\r\n                <th>\r\n    