\n        <td>\r\n            <%=\"\\\\#{i[:period_name]}\"%>\r\n        </td>\r\n        \r\n        <td>\r\n            <%=fn i[:visit].traveling_amount %> /   <%=fn i[:visit].traveling_extra %>\r\n        </td>\r\n        \r\n        \r\n        <td>\r\n        \r\n            <%=link_to \"Print\", \"../Visit/print_traveling?id=\\\\#{i[:visit].id}\", :class=>\'btn  btn-mini\',:target=>\'_blank\'%>\r\n            <%#link_to \"Work List\", \"../Visit/print?id=\\\\#{i[:visit].id}\", :class=>\'btn btn-mini\', :target=>\'_blank\' if i[:visit_type]!=\'UNSCHEDULE\' %>\r\n          \r\n        </td>\r\n        <td>\r\n            <%=link_to \"Payment\", \"#\",:vid=>i[:visit].id, :amount=>i[:visit].traveling_amount, :extra=>i[:visit].traveling_extra, :class=>\'payment_btn btn btn-success btn-mini\'%>&nbsp;\r\n\r\n        </td>\r\n      \r\n        \r\n    </tr>\r\n   <% end %>\r\n    <% end %>\r\n        </tbody>\r\n</table>\r\n	            \r\n	            \r\n	        </div>\r\n	        \r\n	    </div>\r\n	\r\n<script>\r\n    $(\'.payment_btn\').click(function(){\r\n        id = $(this).attr(\'vid\')\r\n        amount = $(this).attr(\'amount\')\r\n        extra = $(this).attr(\'extra\')\r\n        \r\n        var amount = prompt(\"Please enter extra Traveling Amount\", amount);\r\n        var extra = prompt(\"Please enter extra Traveling Extra, 0 or \'\' for NA\", extra);\r\n        \r\n        window.location.replace(\"traveling_payment?id=\"+id+\"&amount=\"+amount+\"&extra=\"+extra);\r\n\r\n        \r\n    })\r\n</script>\r\n \r\n	\r\n	\r\n	',NULL,NULL,NULL,'2019-02-17 11:57:55','2019-02-17 11:57:55','traveling',''),(3951,'index_bk',1495,2,'<%\r\n  module_name = @current_project.name\r\n if params[:date]\r\n  session[module_name]={:date=>params[:date]}\r\n end\r\n if session[module_name]\r\n    params[:date] = session[module_name][:date]\r\n end\r\n unless params[:date]\r\n params[:date] = Time.now.strftime(\'%d/%m/%Y\')\r\n end\r\n%>\r\n<%#session[module_name].inspect %>\r\n<%\r\n\r\n if params[:obj_id]\r\n now = Time.now \r\n\r\n \r\n\r\n \r\n \r\n%>\r\n<meta http-equiv=\"Refresh\" content=\"0; url=../Appointment/create?patient_id=<%=params[:obj_id]%>&data[date]=<%=now.strftime(\'%Y-%m-%d\')%>&data[start]=<%=now.strftime(\'H:M\')%>&data[stop]=<%=now.strftime(\'H:M\')%>\">\r\n<%\r\n end\r\n%>\r\n<script>\r\n//window.location=\"../Appointment/setcase\";\r\n</script>\r\n<div class=\"row-fluid\">\r\n<div class=\"span8\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n       Dashboard\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\">\r\n<center><b>Welcome to <span style=\"color:#F3790D\">EMR</span>-LIFE, <%= @current_project.title %> Module</b></center><br/>\r\n\r\n<center>\r\n\r\n<!-- <a href=\"../Appointment/create?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br />Booking</button></a>\r\n --><a href=\"../Appointment/setcase?return=../Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month_edit\"></i><br />Set Case</button></a>\r\n\r\n<!--<a href=\"../../www/Patient/create?return=../../<%=@current_project.name%>/Home/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-add\"></i><br /> New Patient</button></a>\r\n-->\r\n<a href=\"../Appointment/index\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-calendar_month\"></i><br />Appointment</button></a>\r\n<a href=\"report\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Reports</button></a>\r\n<!--<a href=\"status_feed\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Status</button></a>\r\n-->\r\n<%\r\nif false\r\n%><a href=\"attachment\"><button class=\"btn\" style=\"width:120px;height:80px;margin:5px\"><i class=\"splashy-view_outline_detail\"></i><br />Attachments</button></a>\r\n<% end %>\r\n</center>\r\n    </div>\r\n    </div>\r\n</div>\r\n<div class=\"span4\">\r\n<div class=\"w-box\">\r\n    <div class=\"w-box-header\">\r\n        Status\r\n    </div>  \r\n    <div class=\"w-box-content cnt_a\" style=\"padding-bottom:0px\">\r\n        <div class=\"alert alert-block alert-info\" >\r\n                \r\n        <%\r\n       begin        \r\n            date = Time.now\r\n            date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n        %>\r\n                Date <%= text_field_tag \'date\',date,:id=>\'today-date\',:onchange=>\'alert\',:style=>\'width:120px\' %> <%=link_to \"( Today Click )\", \"../Home/index?date=\\\\#{Time.now.strftime(\'%d/%m/%Y\')}\" %><br/>\r\n\r\n        <h1><%= Time.now.strftime(\"%H : %M\") %></h1>\r\n        \r\n       <%= date.strftime(\'%A %d %B %Y\')%><br/>\r\n\r\n        </div>\r\n\r\n    <script>\r\n    $(\"#today-date\").kendoDatePicker({\r\n        value: \'<%= date.strftime(\"%d/%m/%Y\") %>\',\r\n        change: function(){\r\n            window.location = \"../Home/index?date=\"+kendo.toString(this.value(), \'d\')\r\n        }\r\n	});\r\n</script>\r\n<% rescue %>\r\n  error\r\n<% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<style>\r\n.status_cls{\r\nwidth:100px\r\n}\r\n</style>\r\n<script>\r\nfunction change_status(obj){\r\n  if(confirm(\"Are you sure to update status to \"+obj.value + \" ?\")){\r\n   window.location=\"update_status?id=\"+obj.id+\"&status=\"+obj.value;\r\n  }\r\n }\r\n</script>\r\n<%\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n    patients = [] \r\n    mname = \"\\\\#{@current_project.name}#appointment\"\r\n   # patients =  module_model.all(:module_name=>mname)\r\n    status_list=%w{appointed waiting processing recovery completed cancelled no_show}.collect{|i| i.humanize}\r\n   \r\n    \r\n    models = get_model\r\n    ap_model = models[:appointment]\r\n    p_model = models[:provider]\r\n    v_model = models[:visit_type]\r\n    \r\n\r\n    \r\n    visits = {}\r\n    v_model.all.each do |i|\r\n        visits[i.id]=i.name\r\n    end\r\n    indications = {}\r\n    models[:indication].all.each do |i|\r\n        indications[i.id]=i.name\r\n    end\r\n    \r\n    aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n    for a in aps\r\n        a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n    end\r\n    %>\r\n    <%# aps.inspect %>\r\n    <%\r\n    \r\n    \r\n    list = aps.clone\r\n    id = \'\'\r\n    aps.collect!{|i| \r\n    id = i.id\r\n      if m = module_model.first(:module_name=>mname,:module_id=>i.id)\r\n         patient = patient_model.find(m.patient_id)\r\n         provider = p_model.find(i.provider)\r\n         visit_type = visits[i.visit_type]\r\n         provider_name = \'-\'\r\n         provider_name = provider.name if provider\r\n         procedure_name = \'-\'\r\n         pro = models[:procedure].find(i.procedure) \r\n         procedure_name = pro.name if pro\r\n         patient = patient_model.new unless patient \r\n         hn = \'-\'\r\n         hn = link_to(patient.hn, \"../Appointment/show?id=\\\\#{m.id}\") if patient\r\n         public_id = \'-\'\r\n        # public_id = patient.public_id if patient\r\n         c = {:ref_number=>m.ref_number,:public_id=>public_id,:hn=>hn,:patient=>link_to(\"\\\\#{patient.prefix_name} \\\\#{patient.first_name} \\\\#{patient.last_name}\",\"../../www/Patient/edit?id=\\\\#{patient.id}&return=\\\\#{request.fullpath}\"),\r\n         :provider=>provider_name,:date=>i.date,:note=>\"\\\\#{visit_type} \\\\#{indications[i.indication]} \\\\#{i.note}\",:status=>i.status,:procedure=>procedure_name,\r\n         :status_ctrl=>select_tag(\'name\',options_for_select(status_list,i.status),:class=>\'status_cls\',:id=>i.id,:onchange=>\'change_status(this)\'),\r\n         :pending_ctrl=>link_to(\'Arrived\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\'),\r\n         :visit_type=>visit_type\r\n         }\r\n         \r\n         if i.status==\'Waiting\'\r\n         c[:pending_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \')+\" \"+link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n        \r\n\r\n         #c[:processing_ctrl]=link_to(\'Process\',\"update_status?id=\\\\#{i.id}&status=Processing\",:class=>\'btn btn-small btn-success\') \r\n         else\r\n         status = \'btn-info\'\r\n         status = \'\' if i.status ==\'Completed\'\r\n         c[:processing_ctrl]=link_to(\'Detail\',\"patient_record?id=\\\\#{i.id}\",:class=>\'btn btn-small \'+status)\r\n         end\r\n         c\r\n      end\r\n    }.compact!\r\n    \r\n    # waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' or i[:status]==\'Waiting\'}.compact\r\n    waiting = aps.collect{|i| i if i[:status]==\'Appointed\' or  i[:status]==\'Pending\' }.compact\r\n    \r\n    processing = aps.collect{|i| i if i[:status]==\'Processing\' }.compact\r\n    \r\n    completed = aps.collect{|i| i if i[:status]==\'Recovery\' or i[:status]==\'Completed\' }.compact\r\n    \r\n    cancelling = aps.collect{|i| i if i[:status]==\'No show\' or i[:status]==\'Cancelled\' }.compact\r\n    \r\n    \r\n    table_model = %w{ hn patient provider procedure status_ctrl}.collect{|i| i.to_sym}\r\n    \r\n    #[:ref_number,:date,:patient,:provider,:status_ctrl,:note,:pending_ctrl]\r\n    \r\n    labels = {:hn=>\'HN\',:public=>\'Public\',:patient=>\'Patient\',:provider=>\'Appointed Doctor\',:status_ctrl=>\'Status\',:pending_ctrl=>\'Appointed ctrl\',\r\n    :note=>\'Note\',:visit_type=>\'Group\' }\r\n    \r\n%>\r\n\r\n\r\n<div style=\"width:100%;border:0px solid\">\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n	        Today Patients \r\n     \r\n	    <div class=\"pull-right\"><i class=\"\"><%=waiting.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        \r\n           <% \r\n           \r\n           for visit in visits.values\r\n            tmp = waiting.collect{|w| w if  w[:visit_type]==visit }.compact\r\n           %>\r\n           <% if tmp.size>0 %>\r\n           <%=visit%>\r\n	        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp,:labels=>labels %>\r\n            <% end %>  <% end %>\r\n            \r\n        <% if tmp = waiting.collect{|w| w if w[:visit_type]==nil }.compact and tmp.size>0 %>    \r\n        <%= tabular :model=>table_model+[:pending_ctrl,:note],:data=>tmp ,:labels=>labels %>\r\n        <% end %>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in processing\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;background:#d9edf7\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Processing \r\n	    <div class=\"pull-right\"><i class=\"\"><%=processing.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n<%\r\n    providers = {}\r\n    \r\n    for i in completed\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Completed \r\n        <div class=\"pull-right\"><i class=\"\"><%=completed.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:processing_ctrl,:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n\r\n\r\n<div class=\"clear\"></div>\r\n<br/>\r\n\r\n\r\n<%\r\n    providers = {}\r\n    \r\n    for i in cancelling\r\n        p = i[:provider]\r\n        providers[p]=[] unless providers[p]\r\n        providers[p] << i\r\n    end\r\n    \r\n\r\n%>\r\n<div class=\"left\" style=\"width:100%;\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Cancelled &amp; No show \r\n        <div class=\"pull-right\"><i class=\"\"><%=cancelling.size%> Patients</i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n        <% providers.each_pair do |k,v| %>\r\n        <%= k %><br/>\r\n            <%= tabular :model=>table_model+[:note],:data=>providers[k],:labels=>labels %>\r\n        <% end %>\r\n    </div>\r\n    </div>\r\n</div>\r\n<!--\r\n<div class=\"left\" style=\"width:50%\">\r\n   <div class=\"w-box\" id=\"w_sort05\">    \r\n        <div class=\"w-box-header\">\r\n            Today Patients\r\n	    <div class=\"pull-right\"><i class=\"\"></i></div>\r\n	    </div>\r\n	    <div class=\"w-box-content cnt_a\">\r\n	        content\r\n        </div>\r\n    </div>\r\n</div>\r\n-->\r\n\r\n\r\n</div>\r\n<br/>\r\n<br/>\r\n\r\n<hr/>\r\nLinks : <%= link_to \'Print Appointment\',\'print_appointment?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Print Report\',\'print_report?print[date]=\'+params[:date],:target=>\'_blank\' %> | \r\n<%= link_to \'Status Feed\',\'status_feed?print[date]=\'+params[:date] %> |\r\n<%= link_to \'Reset Locker\',\'../Locker/reset\' if @current_role==\'admin\' or @current_role==\'developer\' %>\r\n<div class=\"clear\"></div>\r\n </div><br/>\r\n \r\n\r\n',NULL,NULL,NULL,'2019-02-21 03:16:16','2019-02-21 03:16:16','index_bk',''),(3952,'init',1495,4,'<%\r\n  @module_name = @current_project.name+\'#\'+ this.table_name \r\n  @ehr_project = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n  @patient_doc = @ehr_project.get_document \'patient\'\r\n  @module_doc = @ehr_project.get_document \'patient_module\'\r\n  @ehr_model = @ehr_project.get_model()\r\n  @patient_model = @ehr_model[:patient]\r\n  @module_model = @ehr_model[:patient_module]\r\n  \r\n  @models = get_model\r\n  \r\n  if this.table_name!=\'appointment\' and params[:parent_id] \r\n  @appointment_module = @module_model.find(params[:parent_id])\r\n  if @appointment_module\r\n  @appointment = @models[:appointment].find(@appointment_module.module_id)\r\n  end\r\n  end \r\n  \r\n  if params[:id] and  @patient_module = @module_model.find(params[:id])\r\n     @patient = @patient_model.find(@patient_module.patient_id)\r\n  end\r\n  \r\n  @next_id= \'000000\'\r\n  \r\n  if @patient_module\r\n     \r\n     @next_id = @patient_module.ref_number\r\n      \r\n  else\r\n      \r\n      \r\n  i = @module_model.last :module_name=>@module_name \r\n  l = 111\r\n  if i and i.ref_number\r\n      l = i.ref_number[6..-1].to_i%10000\r\n  end\r\n  next_id = format(\'%04d\',(l+1)%10000)\r\n  d = Time.now\r\n  @next_id = \"\\#{d.strftime(\'%y%m%d\')}\\#{next_id}\"\r\n\r\n  end\r\n\r\n%>\r\n\r\n',NULL,NULL,NULL,'2019-02-21 05:10:06','2019-02-21 05:10:06','init',''),(3953,'edit',1496,2,'<%\r\n    params[:patient_id]=params[:obj_id] if params[:obj_id]\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n  \r\n    \r\n    \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  \r\n  \r\n    locker_model = get_model(\'locker\')\r\n   \r\n  \r\n  \r\n  \r\n  if request.post?\r\n  \r\n    \r\n    doc = get_document this.document_name\r\n    @patient_module.update_attributes :ref_number=>params[:ref_number],:date=>params[:date],:time=>params[:time]\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=@patient_module.id%>&return=<%=return_url%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n%>\r\n<%\r\n%>\r\n\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>params[:id]) do |f| %>\r\n\r\n <div style=\"background:#eeeeff;padding:5px;width:720px;border:1px solid #ccc\" >\r\n\r\nRef : <%= text_field_tag \'ref_number\',@patient_module.ref_number,:class=>tb_class,:style=>\"width:80px\" %> \r\n<%= hidden_field_tag \'return\', return_url %>\r\n\r\n<span class=\"right\">\r\nDate : <%= text_field_tag \'date\',Time.now,:id=>\"record-date\" ,:style=>\"margin-top:0px;width:120px\"%>\r\nTime : <%= text_field_tag \'time\',Time.now.strftime(\"%H:%M\"),:id=>\"record-time\" ,:style=>\"margin-top:0px;width:70px\"%>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<%= f.submit \"Update\".html_safe, :class=>\'btn btn-small\',:id=>\'record-submit\',:disable_with=>\'Updating..\' %> |\r\n\r\n<%= link_to \'Cancel\', return_url,:confirm=>\'Are you sure?\' %>\r\n<%= hidden_field_tag :id, params[:id] %>\r\n<% end %>\r\n<% end %>\r\n\r\n</div>\r\n</div>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>\r\n\r\n<script>\r\nvar validator = $(\"#form-data\").kendoValidator().data(\"kendoValidator\")\r\n$(\"#record-submit\").click(function() {\r\nif (!validator.validate()) {\r\nalert(\'Please fill all information\');\r\nreturn false;\r\n}else{\r\n       return true;\r\n    if(confirm(\'Are you sure?\')==true){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n});\r\n\r\n\r\n    $(\'#status\').remove();\r\n    $(\"#date,#start,#stop,#room\").hide();\r\n    \r\n</script>   ',NULL,NULL,NULL,'2019-02-21 06:58:11','2019-02-21 06:58:11','edit',''),(3954,'show',1496,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\" style=\"padding:0px\">\r\n<div style=\"border:0px solid;background:#eeeeee;padding:0px\">\r\n<div class=\"document-border\" style=\"border:1px solid #ccc;background:#fcfcfc;padding:0px;max-width:750px\">\r\n\r\n<%\r\n\r\n   @document =  get_document this.document_name \r\n   \r\n   model = get_model(this.table_name)\r\n   @patient_module = @module_model.find(params[:id])\r\n   record = model.find(@patient_module.module_id)\r\n   @record = record    \r\n  if request.post?\r\n    \r\n   \r\n    if p = params[\'cancel_\']\r\n        \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            old_app.destroy\r\n            mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>nil\r\n   \r\n    elsif p = params[\'postpone_\']\r\n    \r\n        if record.postpone_id\r\n        begin\r\n        old_app = model.find(record.postpone_id)\r\n        \r\n        if old_app\r\n            mm = @module_model.where(:module_id=>old_app.id)\r\n            # old_app.destroy\r\n            # mm.destroy\r\n        end\r\n        rescue Exception=>e\r\n        end\r\n        \r\n        end\r\n        \r\n        \r\n        new_app = record.clone\r\n        new_app.update_attributes :date=>p[0][\'postpone_to\'],:status=>\'Appointed\'\r\n        \r\n        mm = @patient_module.clone\r\n        mm.module_id = new_app.id \r\n        mm.save    \r\n        \r\n        record.update_attributes :status=>params[:status], :cancel_reason=>p[0][\'cancel_reason\'], :postpone_to=>p[0][\'postpone_to\'], :postpone_id=>new_app.id\r\n       \r\n        \r\n        \r\n    end\r\n%>\r\n<meta http-equiv=\"refresh\" content=\"0; url=../Home/index\" />\r\n<% end %>\r\n<%= this.display.html_safe %>\r\n\r\n<div id=\"cancel\" style=\"display:none\"  class=\"alert alert-warning\">\r\n   <p>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'cancel_\'\r\n        field = @document.find_by_column_name \'cancel_reason\'\r\n        begin\r\n        %>\r\n        \r\n        <%#field%>\r\n        <div>\r\n        \r\n        <h3>Cancel</h3><br/>\r\n        <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Cancelled\' %>\r\n        </div>\r\n        <script>\r\n        <%= yield :script %>\r\n        \r\n      \r\n        </script>\r\n        <% rescue Exception=>e %>\r\n        <%=e.message%>\r\n        <% end%>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n</div>\r\n\r\n<div id=\"postpone\" style=\"display:none;padding:10px\" class=\"alert alert-warning\">\r\n   \r\n      <p>\r\n        <h3>Postpone</h3><br/>\r\n        <%=form_for :form, :url=>\"show?id=\\\\#{params[:id]}\" do |f| %>\r\n   \r\n        \r\n        <%\r\n        @prefix = \'postpone_\'\r\n        %>\r\n        <div>\r\n        \r\n       <% field = @document.find_by_column_name \'cancel_reason\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n       <% field = @document.find_by_column_name \'postpone_to\' %>\r\n       <%= render :partial=>\'/esm_documents/render_field\',:locals=>{:field=>field}%>\r\n      \r\n      \r\n        <div class=\"clear\"></div>\r\n          <%=  hidden_field_tag \'status\', \'Postpone\' %>\r\n        </div>\r\n       \r\n       \r\n        <script>\r\n        <%= yield :script %>\r\n        </script>\r\n        \r\n          <%= f.submit \'Submit\', :class=>\'btn btn-success\', :data=>{:confirm=>\'Are you sure?\'} %> | <%=link_to \'Cancel\',\'javascript:cancel_ctrl()\' %>\r\n        <% end %>\r\n   </p>\r\n   \r\n   \r\n</div>\r\n\r\n<div style=\"padding:20px\">\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}&return=\\\\#{return_url}\",:class=>bt_class %> | \r\n<%= link_to \'Cancel\'.html_safe, \"javascript:cancel()\",:class=>bt_class %> | \r\n<%= link_to \'Postpone\'.html_safe, \"javascript:postpone()\",:class=>bt_class %> | \r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<script>\r\n    \r\n    function cancel(){\r\n        $(\'#postpone\').hide()\r\n        $(\'#cancel\').slideDown()\r\n        $(\'#cancel_cancel_reason\').show()\r\n        \r\n    }\r\n    \r\n    function postpone(){\r\n        $(\'#cancel\').hide()\r\n        $(\'#postpone\').slideDown()\r\n        $(\'#postpone_postpone_to\').show()\r\n\r\n    }\r\n    \r\n    function cancel_ctrl(){\r\n        $(\'#postpone\').slideUp()\r\n        $(\'#cancel\').slideUp()\r\n    }\r\n    $(\'.ctrl\').hide();\r\n    $(\"#date,#start,#stop,#room\").hide();\r\n</script>',NULL,NULL,NULL,'2019-02-21 06:58:22','2019-02-21 06:58:22','show',''),(3955,'show',1432,2,'<%\r\n    return_url = url(\'index\')\r\n    return_url = params[:return] if params[:return]\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\"><%=this.table_name.to_s.humanize%></h3>\r\n<div class=\"pull-right\">\r\n<%= link_to \'<i class=\"splashy-printer\"></i> Print\'.html_safe, \"print?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n<%= this.display.html_safe %><br/>\r\n\r\n<%= link_to \'Edit\'.html_safe, \"edit?id=\\\\#{params[:id]}\",:target=>\'_blank\',:class=>\'btn btn-mini\' %> | \r\n\r\n<%= link_to \'Move Out\'.html_safe, \"move_out?id=\\\\#{params[:id]}\",:class=>\'btn btn-mini btn-danger\', :data=>{:confirm=>\'Are you sure?\'}  %> | \r\n\r\n<%= link_to \'Remove\'.html_safe, \"destroy?id=\\\\#{params[:id]}\",:class=>\'btn btn-mini btn-danger\', :data=>{:confirm=>\'Are you sure?\'}  %> | \r\n\r\n<%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2019-02-21 16:04:15','2019-02-21 16:04:15','show',''),(3956,'move_out',1432,3,'<%\r\n  model = get_model(this.table_name)\r\n  @record = model.find(params[:id])\r\n  \r\n  @record.update_attributes :status=>\'99\', :date_out=>Time.now \r\n%>\r\n<meta http-equiv=\"REFRESH\" content=\"0;url=index\">',NULL,NULL,NULL,'2019-02-21 16:07:54','2019-02-21 16:07:54','move_out',''),(3957,'inspect_reprocess',1036,3,'<%\r\n\r\n\r\n    ehr = @context.get_projects_by_abstract(\'ehr.ehr\')[0]\r\n    model = ehr.load_model\r\n    patient_model = model[:patient]\r\n    module_model = model[:patient_module]\r\n\r\n    models = get_model \r\n    \r\n    list = models[:attendance].where(:date=>Date.new(2019,2,4).to_mongo).all\r\n    \r\n    billing_m = models[:billing]\r\n    billing_map = {}\r\n    billing_list = billing_m.collection.find(:created_at=>{\'$gte\'=>Date.new(2019,2,4).to_mongo,\'$lte\'=>Date.new(2019,2,5).to_mongo},).to_a\r\n    \r\n    mbilling_list = {}\r\n    \r\n    m_billings = module_model.collection.find(:module_id=>{\'$in\'=>billing_list.collect{|i| i[\'_id\']}}).to_a\r\n    for i in m_billings\r\n    \r\n    mbilling_list[i[\'module_id\'].to_s] = i\r\n    \r\n    end\r\n\r\n    \r\n    \r\n    \r\n    \r\n    for i in billing_list\r\n    \r\n        # m_billing = module_model.collection.find(:module_id=>i[\'_id\']).first\r\n    \r\n        m_billing = mbilling_list[i[\'_id\'].to_s]\r\n        \r\n        if m_billing\r\n    \r\n        m_parent = module_model.collection.find(:_id=>m_billing[\'parent_id\']).first\r\n        \r\n        app = models[:appointment].collection.find(:_id=>m_parent[\'module_id\']).first\r\n        if app\r\n        date = app[\'date\'].strftime(\"%d-%m-%Y\")\r\n        billing_map[date] = [] unless billing_map[date]\r\n        billing_map[date] << i\r\n        end\r\n        end\r\n    end\r\n    \r\n    if true\r\n    \r\n    product_m = models[:product]\r\n    product_map = {}\r\n    for i in product_m.collection.find.to_a\r\n        product_map[i[\'_id\']] = i\r\n    end\r\n    \r\n    billing_item_map = {}\r\n    billing_item_m = models[:billing_item]\r\n    for i in billing_list\r\n        billing_item_map[i[\'_id\']] = billing_item_m.collection.find(\'_id\'=>{\'$in\'=>i[\'items\']}).to_a\r\n    end\r\n\r\n    payroll_structure_map = {}\r\n    models[:payroll_structure].all.each do |i|\r\n       payroll_structure_map[i.product_id] = i\r\n    end\r\n    \r\n    provider_map = {}\r\n    \r\n    models[:provider].collection.find.to_a.each do |i|\r\n      provider_map[i[\'_id\']] = i\r\n    end\r\n    \r\n    atm_m = models[:attendance_payroll_item]\r\n    \r\n    atm_list = []\r\n    \r\n    %>\r\n<table>   \r\n<%\r\n    \r\nfor i in list\r\n    date = i.date.strftime(\"%d-%m-%Y\")\r\n    billings = billing_map[date]\r\n    \r\n    a_list = {}\r\n    \r\n    a_list[\'nurse\'] = []\r\n    a_list[\'nurse\'] << provider_map[i[\'n1\']]\r\n    a_list[\'nurse\'] << provider_map[i[\'n2\']]\r\n    a_list[\'nurse\'] << provider_map[i[\'n3\']]\r\n    \r\n    a_list[\'pn\'] = []\r\n    a_list[\'pn\'] << provider_map[i[\'pn1\']]\r\n    a_list[\'pn\'] << provider_map[i[\'pn2\']]\r\n    \r\n    a_list[\'officer\'] = []\r\n    a_list[\'officer\'] << provider_map[i[\'officer1\']]\r\n    \r\n    \r\n    a_list[\'employee\'] = []\r\n    a_list[\'employee\'] << provider_map[i[\'employee1\']]\r\n \r\n    \r\n    \r\n    sum = {}    \r\n    \r\n%>\r\n<tr>\r\n    <td>\r\n        <%=i.date%>\r\n    </td>\r\n</tr>\r\n\r\n<% \r\n\r\nif billings \r\n \r\nfor j in billings \r\n\r\nif j[\'billing_type\']==\'2\'\r\n\r\n    items =  billing_item_map[j[\'_id\']]\r\n    \r\n%>\r\n<tr>\r\n    <td>\r\n        &nbsp;\r\n    </td>\r\n    \r\n    <td>\r\n        <%=j[\'_id\']  %>  <%=j[\'type_of_patient\']  %>\r\n    </td>\r\n</tr>\r\n\r\n<% \r\n  \r\nfor k in items \r\n\r\n    product = product_map[k[\'product_id\']]\r\n    \r\n    stc = payroll_structure_map[product[\'_id\']]\r\n    if stc\r\n        \r\n        \r\n%>\r\n\r\n<tr>\r\n    <td>\r\n        &nbsp;\r\n    </td>\r\n     <td>\r\n        &nbsp;\r\n    </td>\r\n    \r\n    <td>\r\n        <%#k.inspect %>\r\n        <%=product[\'name\'] %>    <%=product[\'code\'] %>\r\n    </td>\r\n    \r\n    <% %w{nurse pn officer employee}.each do |x| \r\n    \r\n        \r\n        sum[x] = 0  unless sum[x]\r\n        sum[x] += stc[x].to_i \r\n        \r\n        txt = []\r\n        \r\n        a_list[x].each do|y|\r\n        \r\n            txt << y[\'name\']\r\n            key = \"\\\\#{i[\'_id\']}-\\\\#{y[\'_id\']}-\\\\#{j[\'_id\']}-\\\\#{product[\'_id\']}\"\r\n            \r\n            atm = atm_m.collection.find(:attendance_id=>i[\'_id\'], :provider_id=>y[\'_id\'], :billing_id=>j[\'_id\'], :product_id=>product[\'_id\']).first\r\n            \r\n            unless atm\r\n            \r\n            atm_m.create(:attendance_id=>i[\'_id\'], :provider_id=>y[\'_id\'], :billing_id=>j[\'_id\'], :product_id=>product[\'_id\'], :price=>stc[x].to_i)\r\n            atm_list << {:date=>date, :provider=>y[\'name\'],:product=>product[\'name\'] ,:attendance_id=>i[\'_id\'], :provider_id=>y[\'_id\'], :billing_id=>j[\'_id\'],:product_id=>product[\'_id\'], :price=>stc[x].to_i}\r\n            \r\n            else\r\n            atm_m.find(atm[\'_id\']).update_attributes( :price=>stc[x].to_i)\r\n\r\n\r\n            \r\n            end\r\n            \r\n            \r\n        \r\n        end\r\n    \r\n    %>\r\n    \r\n    <td>\r\n        <%= stc[x] %> (<%=txt.join(\"&nbsp;\").html_safe%>)\r\n    </td>\r\n    \r\n    \r\n    <% end%>\r\n    \r\n    \r\n</tr>\r\n<% end %>\r\n\r\n\r\n<% end %>\r\n\r\n<% end %>\r\n<%\r\n        \r\n\r\n%>\r\n\r\n\r\n\r\n<% end %>\r\n<tr>\r\n    <td>Summary</td>\r\n    <td><%=sum.inspect %></td><td><%#a_list.inspect %></td>\r\n</tr>\r\n\r\n<% end %>\r\n\r\n<% end%>\r\n\r\n</table> \r\n<table class=\"table\">\r\n<tbody>\r\n<% for i in atm_list %>\r\n<tr>\r\n<td><%= i[:date] %></td>\r\n<td><%= i[:provider] %></td>\r\n<td><%= i[:product] %></td>\r\n<td><%= i[:price] %></td>\r\n</tr>\r\n<% end %>\r\n</tbody>\r\n</table\r\n\r\n\r\n<% end %>',NULL,NULL,NULL,'2019-02-27 07:59:48','2019-02-27 07:59:48','inspect_reprocess',''),(3958,'summary',1432,2,'\r\n<%\r\n @document = get_document(this.document_name)\r\n @fields = @document.list_fields\r\n query=\'\'\r\n   \r\n if params[:search]\r\n        query = params[:search][:query]\r\n        keys = []\r\n        @fields.each_with_index do |f,index| \r\n            keys <<{f.column_name.to_sym=>Regexp.new(query)}\r\n        end\r\n        dates = {}\r\n        if params[:search][:from_date]!=\'\'\r\n            from_date = Time.parse(params[:search][:from_date])\r\n            to_date = Time.parse(params[:search][:to_date])\r\n           dates = { :created_at => { \'$gt\' =>from_date, \'$lt\' =>to_date }}\r\n        end\r\n        criteria = {\'$or\'=>keys}.merge!(dates)\r\n        params[:search][:criteria] = criteria\r\n  else\r\n     from_date = nil\r\n     to_date = nil \r\n     rows = 10000\r\n     if params[:page]\r\n        page = params[:page].to_i\r\n     else\r\n        page = 0\r\n     end\r\n     offset = page * rows;\r\n     params[:paginate] = [rows,offset,page]\r\n  end\r\n  \r\n \r\n\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3 style=\"display:inline-block\">IP Inventory</h3>\r\n<div class=\"pull-right\">\r\n<%# link_to \'<i class=\"splashy-add_small\"></i> New record\'.html_safe,\"../IpLog/create\",:class=>\'btn btn-mini\' %>\r\n</div>\r\n</div>\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<%= form_for :search, :url=>\'index\' do |f| %>\r\n<div>\r\n<%# f.text_field :from_date, :id=>\'from-date\',:style=>\'width:100px\' %>\r\n\r\n<%# f.text_field :to_date, :id=>\'to-date\',:style=>\'width:100px\' %>\r\n<span class=\"right\">\r\n<%= f.text_field :query ,:id=>\'search-field\',:class=>tb_class,:value=>query ,:style=>\'width:150px\'%>\r\n<button class=\"btn btn-small\" ><i class=\"splashy-zoom\"></i>Search</button>\r\n<%= link_to \"Show All\", url(\"index\"),:class=>\'btn btn-small btn-warning\' if params[:search] %>\r\n</span>\r\n<script>\r\n    $(\"#from-date\").kendoDatePicker({\r\n        value: \'<%= from_date.strftime(\"%d/%m/%Y\") if from_date %>\',\r\n    });\r\n    $(\"#to-date\").kendoDatePicker({\r\n        value: \'<%= to_date.strftime(\"%d/%m/%Y\") if to_date %>\',\r\n	});\r\n    $(\"#search-field\").kendoAutoComplete();\r\n</script>\r\n<div class=\"clear\"></div>\r\n</div>\r\n<% end %>\r\n\r\n<%= this.summary_partial.html_safe %>\r\n\r\n<br/>\r\n<p>\r\n<%# link_to \'<i class=\"splashy-add\"></i> New record\'.html_safe, \"../IpLog/create\",:class=>\'btn btn-small\' %>\r\n<%# link_to \'History\'.html_safe, \"../IpLog/index\",:class=>\'btn btn-small\' %>\r\n\r\n\r\n<%# link_to \"Migration tools\", url(\"migrate\") if @current_role == \'superuser\' or @current_role==\'developer\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n',NULL,NULL,NULL,'2019-02-27 17:48:07','2019-02-27 17:48:07','summary',''),(3959,'summary_partial',1432,3,'<%\r\n   model = get_model(this.table_name)\r\n   records = []\r\n   @project =  context[:project]\r\n   @document = get_document(this.document_name)\r\n   fields = @document.list_fields\r\n   labels = fields.collect{|i| i.column_name }\r\n   values = {}\r\n   \r\n    if params[:search]\r\n        records = model.all(params[:search][:criteria])\r\n    else\r\n       n = model.count\r\n       rows,offset,page = params[:paginate]\r\n       records = model.limit(rows).skip(offset).all :order=>\'created_at desc\'\r\n    end\r\n    \r\n    models = get_model\r\n    \r\n    pmap = {}\r\n    \r\n    unprojects = records.collect{|i| i if i.project_id == nil}.compact \r\n    \r\n    moved_out =  records.collect{|i| i if i.status == \'99\'}.compact \r\n    \r\n    projects = models[:project].find records.collect{|i| i.project_id}\r\n    \r\n    for i in records\r\n        if i.status!=\'99\'\r\n        pmap[i.project_id] = [] unless pmap[i.project_id]\r\n        pmap[i.project_id] << i\r\n        end\r\n    end\r\n    \r\n    \r\n     moved_pmap = {}\r\n    \r\n    for i in moved_out\r\n    \r\n        moved_pmap[i.project_id] = [] unless moved_pmap[i.project_id]\r\n        moved_pmap[i.project_id] << i\r\n    \r\n    end\r\n%>\r\n<div class=\"tabbable\">\r\n	<ul class=\"nav nav-tabs\">\r\n		<li class=\"active\"><a href=\"#tab0\" data-toggle=\"tab\">IP Inventory</a></li>\r\n		<li class=\"\"><a href=\"#tab1\" data-toggle=\"tab\">Storage</a></li>\r\n	</ul>\r\n		<div class=\"tab-content\">\r\n	\r\n	\r\n<%\r\n    [pmap].each_with_index do |x,xindex|\r\n    \r\n    projects = models[:project].find x.keys\r\n\r\n\r\n    pmap = x\r\n\r\n%>\r\n	\r\n		<div class=\"tab-pane <%=\'active\' if xindex==0 %>\" id=\"tab<%=xindex%>\">\r\n			<p>\r\n\r\n<table class=\"table\">\r\n    \r\n    <% for i in projects %>\r\n    <thead>\r\n    <tr>\r\n          <th>\r\n        Status\r\n    </th>\r\n    <th>\r\n        <%= i.protocol_no %>\r\n    </th>  \r\n  \r\n    <th>\r\n        Lot\r\n    </th>\r\n    <th>\r\n        Expired\r\n    </th>\r\n    <th>\r\n        Day until exp\r\n    </th>\r\n    <!--\r\n    <th>\r\n        รวม\r\n    </th>\r\n      <th>\r\n        จำนวนที่ใช้ไป\r\n    </th>\r\n    <th>\r\n        คงเหลือ\r\n    </th>\r\n    -->\r\n    <th>\r\n       จำนวนที่ใช้ได้(หักexpออก)\r\n    </th>\r\n    <th>\r\n        จำนวนรวมที่ใช้ได้\r\n    </th>\r\n    <!--\r\n    <th>\r\n        จำนวนรวมที่ใช้ไป\r\n    </th>\r\n  \r\n    \r\n    <th>\r\n        Min\r\n    </th>\r\n\r\n      <th>\r\n        Comment \r\n    </th>\r\n      -->\r\n    <th>\r\n        \r\n    </th>    \r\n    </tr>\r\n    </thead>\r\n    <tbody>\r\n    <%\r\n    \r\n    \r\n    \r\n        now = Time.now \r\n        \r\n    if pmap[i.id]\r\n        \r\n        for j in pmap[i.id]\r\n        \r\n        \r\n        list = models[:ip_card].where(:item_id=>j.id).all\r\n        map = {}\r\n        \r\n        for k in list\r\n        \r\n            map[k.lot] = [] unless map[k.lot]\r\n            \r\n            map[k.lot] << k\r\n        \r\n        end\r\n      \r\n      \r\n      \r\n        storage=\"\"\r\n#         1|2-8C\r\n# 2|15-25C\r\n# 3|-20C\r\n# 4|-60C\r\n    if j.storage_condition\r\n        storage =  {\'1\'=>\'2-8C&#176;\',\'2\'=>\'15-25C&#176;\',\'3\'=>\'-20C&#176;\',\'4\'=>\'-60C&#176;\'}[j.storage_condition] \r\n        storage = \"<span style=\'color:green\'>\\\\#{storage}<span>\".html_safe\r\n    end\r\n      \r\n      %>\r\n       \r\n    <%\r\n    \r\n    \r\n        total_usable = 0 \r\n        total_usage = 0 \r\n        adj_one_month = 0 \r\n    \r\n        map.each_pair do |k,v| \r\n            \r\n        balance = 0 \r\n        total = 0 \r\n        usage = 0 \r\n        usable = 0 \r\n        expired = nil\r\n        \r\n        for x in v\r\n        \r\n            if x.status==\'in\'\r\n                total += x.quantity if x.quantity\r\n                balance+= x.quantity if x.quantity\r\n            end\r\n            \r\n            if x.status==\'out\'\r\n                usage += x.quantity if x.quantity\r\n                balance-= x.quantity if x.quantity\r\n            end\r\n            \r\n            expired = x.expired_date if x.expired_date    \r\n        \r\n            \r\n        \r\n        end\r\n        \r\n        \r\n        usable = balance\r\n        \r\n         if expired\r\n        \r\n        if   now > expired \r\n           \r\n           usable = 0 \r\n            \r\n        end\r\n        \r\n        if now > expired.to_datetime-30\r\n        \r\n            adj_one_month += usable\r\n        \r\n        end\r\n    end\r\n  \r\n        \r\n        total_usable += usable if usable\r\n        total_usage += usage if usage\r\n        \r\n        end\r\n        \r\n        status = \'\'\r\n        \r\n        \r\n        if j.minimum and  total_usable-adj_one_month < j.minimum\r\n            status = \'NEAR EXP\'\r\n        end\r\n        \r\n        \r\n        if j.minimum and  total_usable < j.minimum\r\n            status = \'ALERT\'\r\n        end\r\n        \r\n        \r\n        \r\n        \r\n        \r\n        tag = nil\r\n        map = {} if j.status==\'99\'\r\n        first = true\r\n        \r\n        map.each_pair do |k,v| \r\n            \r\n        balance = 0 \r\n        total = 0 \r\n        usage = 0 \r\n        usable = 0 \r\n        expired = nil\r\n        \r\n        for x in v\r\n        \r\n            if x.status==\'in\'\r\n                total += x.quantity if x.quantity\r\n                balance+= x.quantity if x.quantity\r\n            end\r\n            \r\n            if x.status==\'out\'\r\n                usage += x.quantity if x.quantity\r\n                balance-= x.quantity if x.quantity\r\n            end\r\n            \r\n            expired = x.expired_date if x.expired_date    \r\n        \r\n        end\r\n        \r\n        usable = balance\r\n            \r\n    %>\r\n    <tr>    <%\r\n        \r\n         sclass=\"-\"\r\n         sclass=\"alert alert-warning\" if status==\'NEAR EXP\'\r\n         sclass=\"alert alert-danger\" if status==\'ALERT\'\r\n         \r\n        %>\r\n         \r\n         <% if first %>\r\n        <td  rowspan=\"<%=map.keys.size%>\"  style=\"vertical-align:middle;\">\r\n            <span class=\"<%=sclass%>\"><%=status.split(\" \").join(\"\")%></span>\r\n        </td>\r\n        \r\n        <td  rowspan=\"<%=map.keys.size%>\"  style=\"vertical-align:middle\" >\r\n            <%= j.name %> <%=storage%>    \r\n        </td>\r\n       <% end %>\r\n        \r\n        \r\n        <td>\r\n            <%=k%>     \r\n        </td>\r\n        \r\n            <% if expired %>\r\n            <% if expired > Time.now %>\r\n            <td><%=expired.strftime(\"%d-%b-%y\")%></td><td><%= distance_of_time_in_words now, expired.to_datetime if expired%> </td>\r\n            <% else\r\n            \r\n                usable = 0 \r\n                \r\n            %>\r\n            <td><span class=\" alert-danger\"><%=expired.strftime(\"%d-%b-%y\")%></span></td><td><span class=\" alert-danger\">Expired</span></td>\r\n            <% end %>\r\n            <% else %>\r\n            <span class=\"alert alert-warning\">No Date</span>\r\n            <% end %>\r\n        </td>\r\n        \r\n        <!--\r\n        <td>\r\n           <%= total %>\r\n        </td>\r\n       \r\n        <td>\r\n           <%= usage %> <%#link_to \'+\', \"../IpCard/create?record[item_id]=\\\\#{j.id}&record[lot]=\\\\#{k}&record[status]=out\", :class=>\'btn btn-mini btn-info\' if j.status!=\'99\'%>  \r\n\r\n\r\n        </td>\r\n         <td>\r\n           <%= balance %>\r\n        </td>\r\n        -->\r\n        \r\n        <td>\r\n           <%= usable %>\r\n        </td>\r\n        \r\n        <% unless tag %>\r\n        \r\n        <td rowspan=\"<%=map.keys.size%>\" style=\"vertical-align:middle;\">\r\n            <span class=\" alert-info\" style=\"padding:5px\"><b><%=total_usable%></b></span>\r\n        </td>\r\n        <!--\r\n        <td rowspan=\"<%=map.keys.size%>\" style=\"vertical-align:middle;\">\r\n            <%=total_usage%>\r\n        </td>\r\n        \r\n        <td rowspan=\"<%=map.keys.size%>\" style=\"vertical-align:middle;\">\r\n            <%=j.minimum%>\r\n        </td>\r\n      \r\n  \r\n        \r\n        \r\n     \r\n     \r\n     \r\n          \r\n        <td rowspan=\"<%=map.keys.size%>\" style=\"vertical-align:middle;\">\r\n            <%=j.comment %>\r\n        </td>\r\n          -->\r\n        \r\n        <% \r\n        \r\n              tag = true\r\n        end %>\r\n        \r\n        \r\n    </tr>\r\n    <%\r\n       first = false\r\n    %>\r\n    		<% end %>\r\n     <% \r\n     \r\n\r\n      \r\n     end %>\r\n    <% end %>\r\n</tbody>\r\n    \r\n    <% end %>\r\n    \r\n</table>\r\n	</p>\r\n		</div>\r\n		\r\n		<% end %>\r\n\r\n	<div class=\"tab-pane\" id=\"tab1\">\r\n			<p>\r\nStorage\r\n</p>\r\n</div>\r\n\r\n	</div>\r\n</div>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2019-02-27 17:50:11','2019-02-27 17:50:11','summary_partial',''),(3960,'context_menu',1526,4,'',NULL,NULL,NULL,'2019-02-28 07:34:45','2019-02-28 07:34:45','context_menu',''),(3961,'document_name',1563,1,'\'add_radiation\'',NULL,NULL,NULL,'2019-03-06 03:50:49','2019-03-06 03:50:49',NULL,NULL),(3962,'context_menu',1522,4,'',NULL,NULL,NULL,'2019-03-08 04:43:32','2019-03-08 04:43:32','context_menu',''),(3963,'document_name',1564,1,'\'bowel_preparation_record_for_colonoscopy_\'',NULL,NULL,NULL,'2019-03-11 08:30:36','2019-03-11 08:30:36',NULL,NULL),(3964,'document_name',1565,1,'\'gi_pre_procedure_assessment\'',NULL,NULL,NULL,'2019-03-11 09:10:37','2019-03-11 09:10:37',NULL,NULL),(3965,'product_wl_search',1325,3,'<%\r\n    models = get_model\r\n    if params[:query]\r\n    \r\n    products = []    \r\n    \r\n    if params[:query][:q] !=\"\"\r\n    query = /\\\\#{params[:query][:q]}/i\r\n    products = models[:pl_product].where(\'$or\'=>[{:name=>query},{:code=>query}]).all :limit=>100\r\n    \r\n    else\r\n    product_items_map = {}\r\n    \r\n    if params[:id]\r\n    \r\n    # selectPassThrough\r\n    # selectReimburse\r\n    item_type = \'1\'\r\n    item_type = \'2\' if params[:callback]==\'selectReimburse\'\r\n    \r\n    project = models[:project].find params[:id]\r\n    \r\n    product_items = models[:project_item].where(:project_id=>project.id,:item_type=>item_type).all\r\n    \r\n    products = models[:pl_product].find product_items.collect{|i| i.product_id }\r\n    \r\n    for i in product_items\r\n    \r\n    product_items_map[i.id] = i\r\n    \r\n    end\r\n    \r\n    \r\n    else\r\n    \r\n    products = models[:pl_product].where(\'$or\'=>[{:code=>/STU-/i},{:code=>/FIX-/i}]).all  \r\n\r\n\r\n    \r\n    end\r\n    \r\n       \r\n    # products = []    \r\n        \r\n    end\r\n    \r\n    pmap ={}\r\n    for i in products\r\n        pmap[i.id] = i\r\n    end\r\n    \r\n    pre = \'\'\r\n    func = \'\'\r\n    callback= \'\'\r\n    if params[:list]\r\n    \r\n    pre = params[:list].split(\"-\").join(\"_\")\r\n    func = pre.camelize\r\n    \r\n    end\r\n    \r\n    if params[:sheet_id] \r\n        sheet = models[:pl_sheet].find(params[:sheet_id])\r\n        doc = models[:project_document].where(:document_id=>sheet.id).first\r\n    end\r\n    \r\n%>\r\n<table class=\"table\">\r\n    <thead>\r\n        <tr><th>#</th>\r\n           <th>Code</th>\r\n            <th>Detail</th>\r\n            <th>Group</th>\r\n             <th>Vendor</th>\r\n            <th>Cost</th>\r\n            <th>Price</th>\r\n           \r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <% for i in product_items \r\n        \r\n           \r\n        \r\n            detail = i.detail\r\n            price = i.price\r\n            \r\n            p = pmap[i.product_id]\r\n            \r\n            cost = p.cost\r\n            \r\n       \r\n            if sheet      \r\n                \r\n            # schedule item    \r\n            # item = models[:pl_period_product].where(:sheet_id=>sheet.id, :product_id=>i.id).first   \r\n            \r\n            # only item\r\n            item = models[:project_item].where(:project_id=>doc.project_id,:product_id=>i.id).first unless item\r\n             \r\n             \r\n             \r\n            if item\r\n                \r\n                detail = item.detail\r\n                price = item.price\r\n                # cost = item.cost \r\n                \r\n            end\r\n            \r\n         end\r\n        %>\r\n        \r\n        <%\r\n        unless params[:callback]\r\n            callback = \"selectProduct\\\\#{func}(\'\\\\#{i.id}\')\"\r\n        end\r\n            callback = \"\\\\#{params[:callback]}(\'\\\\#{i.id}\')\" if params[:callback]\r\n        \r\n        cls = \"\"\r\n        if item \r\n            cls = \'alert-success\' \r\n            cls = \'alert-info\' if item.class.to_s.index(\"Schema::ProjectItem\") and item.item_type==\'1\'  #blue addtional\r\n            cls = \'alert-danger\' if item.class.to_s.index(\"Schema::ProjectItem\") and item.item_type==\'2\' #reimburse\r\n            \r\n            \r\n        end\r\n        \r\n        \r\n        \r\n        %>\r\n        <tr class=\"<%=cls if item%>\">\r\n        <td><%=check_box_tag  \"\\\\#{func}_\\\\#{i.id}\",\'true\',false, :class=>\'item\' %></td>\r\n        <td><%=p.code %><td>\r\n            <%=link_to detail, \"javascript:\\\\#{callback}\" %>\r\n        </td>\r\n            \r\n            <td><%=p.group_code %></td> <td><%=p.vendor_code %></td><td><%=cost %></td><td><%= price %></td>\r\n            \r\n        </tr>\r\n        <% end %>\r\n    </tbody>\r\n</table>\r\n<% unless params[:callback] %>\r\n<div id=\"template-x\" style=\"display:none\">\r\n <table>\r\n        <tbody>\r\n    <tr>\r\n    <td class=\"code\" style=\"font-weight: bold;\">\r\n        code\r\n    </td>\r\n    <td >\r\n        <%=hidden_field_tag \"id\", \'\', :class=>\'field-x record\' %>\r\n\r\n        <%=text_field_tag \"detail\", \'\', :class=>\'field-x detail\' %>\r\n    </td>\r\n    <td class=\"group_code\">\r\n        group_code\r\n    </td>\r\n    <td class=\"vendor_code\">\r\n        -\r\n    </td>\r\n    <td class=\"cost\">\r\n        cost\r\n    </td>\r\n    <td >fff\r\n        <%=text_field_tag \"price\",\'\',  :class=>\'field-x price\' ,:style=>\"width:100px\" %>\r\n    </td>\r\n\r\n    <%\r\n    if pre==\'fixed_list\'\r\n    %>\r\n    \r\n    <td >\r\n        <%=text_field_tag \"quantity\",\'\',  :class=>\'field-x quantity\',:style=>\"width:100px\" %>\r\n    </td>\r\n    \r\n    <% end %>\r\n    <td >\r\n        <%=text_field_tag \"note\", \'\', :class=>\'field-x note\' %>\r\n    </td>\r\n    <td class=\"delete\">\r\n        <%=link_to \"Delete\", \"#\", :class=>\'del-x\' %>\r\n    </td>\r\n\r\n\r\n    \r\n    </tr>\r\n    </tbody>\r\n        \r\n    </table>\r\n    \r\n</div>\r\n\r\n\r\n<script>\r\n    \r\n    var list_<%=pre%> = <%=pmap.to_json.html_safe%>;\r\n    var item_<%=pre%> = <%=product_items_map.to_json.html_safe%>;\r\n    \r\n    function selectProduct<%=func%>(id){\r\n        \r\n        item =  list_<%=pre%>[id];\r\n        p = list_<%=pre%>[item[\'product_id\']];\r\n        pre = \'<%=pre%>\'\r\n        console.log(p)\r\n        template = $(\'#template-x\').clone()\r\n        \r\n        template.find(\'.code\').html(p[\'code\'])\r\n        template.find(\'.vendor_code\').html(p[\'vendor_code\'])\r\n\r\n        template.find(\'.group_code\').html(p[\'group_code\'])\r\n\r\n\r\n                \r\n        template.find(\'.field-x\').each(function(){\r\n            \r\n            $(this).attr(\"name\",  pre+\"_\"+$(this).attr(\"name\")+\"[]\" ) \r\n            \r\n        })\r\n       \r\n        template.find(\'.record\').attr(\"value\",p[\'id\'])\r\n\r\n\r\n        template.find(\'.detail\').attr(\"value\",p[\'name\'])\r\n       \r\n        template.find(\'.price\').attr(\"value\",p[\'price\'])\r\n        template.find(\'.cost\').html(p[\'cost\'])\r\n        \r\n        <% if params[:list] ==\'fixed-list\' %>\r\n        template.find(\'.price\').attr(\'pid\', p[\'id\'])\r\n        template.find(\'.cost\').attr(\'id\', \"cost-\"+p[\'id\'])\r\n        \r\n        template.find(\'.price\').keyup(function(){\r\n              \r\n             v =  $(this).val();\r\n             $(\'#cost-\'+$(this).attr(\'pid\')).html(v)\r\n             \r\n              \r\n          })\r\n        \r\n        <% end %>\r\n        \r\n        template.find(\'.del-x\').attr(\"id\",p[\'id\'])\r\n        template.find(\'.del-x\').click(function(){\r\n            id = $(this).attr(\'id\')\r\n            $(\'#r\'+id).remove()\r\n            return false\r\n        })\r\n        \r\n        \r\n        \r\n\r\n        \r\n        template.find(\'tr\').each(function(){\r\n            $(this).attr(\"id\", \"r\"+p[\'id\'])\r\n            $(\'#<%=params[:list]%>\').append($(this))\r\n        })\r\n        \r\n        // template = []\r\n        // template.push(\"<td>\"+p[\'code\']+\"<input type=\'hidden\' name=\'\"+pre+\"_product_id[]\' value=\'\"+p[\'id\']+\"\'>\"+\"</td>\")\r\n        // template.push(\"<td>\"+p[\'name\']+\"</td>\")\r\n        // template.push(\"<td>\"+p[\'group_code\']+\"</td>\")\r\n        // template.push(\"<td><input type=\'text\' name=\'un-visit-note[]\' value=\'\'>\"+\"</td>\")\r\n        // template.push(\"<td><a href=\'#\' id=\'\"+p[\'id\']+\"\'>Delete</a</td>\")\r\n        \r\n        \r\n        // $(\'#<%=params[:list]%>\').append(\"<tr id=\'r\"+p[\'id\']+\"\'>\"+template.join()+\"</tr>\");\r\n        \r\n        // $(\'#\'+p[\'id\']).click(function(){\r\n        //     id = $(this).attr(\'id\')\r\n        //     $(\'#r\'+id).remove()\r\n        //     return false\r\n        // })\r\n        // $(\'#close-\'+pre).click();\r\n        \r\n        \r\n        // $(\'#search_result\').html(\'\')\r\n    }\r\n    \r\n    \r\n</script>\r\n<% end %>\r\n\r\n<% end %>',NULL,NULL,NULL,'2019-03-11 16:16:50','2019-03-11 16:16:50','product_wl_search',''),(3966,'add_item',1385,3,'<%\r\n    models = get_model\r\n    \r\n    item = models[:project_item].find params[:item_id]\r\n    \r\n    p = models[:pl_product].find item.product_id\r\n    \r\n    detail = item.detail\r\n    cost = p.cost\r\n    price = item.price\r\n    quantity = 1\r\n\r\n           opt = false\r\n           sub_items = models[:pl_product_bom].where(:product_id=>p.id).all      \r\n           opt = true if sub_items.size > 0 and sub_items[0].item_type==\'OPT\'\r\n  \r\n   \r\n%>\r\n<div id=\"template-pass-through\" style=\"display:block\">\r\n <table>\r\n        <tbody>\r\n    <tr  class=\"r<%=item.id%>\">\r\n    <td class=\"code\" style=\"font-weight: bold;\">\r\n        <%=p.code%>\r\n    </td>\r\n    <td >\r\n    \r\n        <%=hidden_field_tag \"item_item[]\", item.id , :class=>\'field-x item\' %>\r\n        <%=hidden_field_tag \"item_id[]\", p.id, :class=>\'field-x record\' %>\r\n        <%=hidden_field_tag \"item_item_type[]\", \'1\', :class=>\'field-x item_type\' %>\r\n        \r\n        <span class=\"detail\"><%=item.detail%></span>\r\n    </td>\r\n    <td class=\"group_code\">\r\n        <%=p.group_code%>\r\n    </td>\r\n    <td class=\"\">\r\n    <span class=\"vendor_txt\"></span>\r\n    \r\n          <% if opt %>\r\n            <%=select_tag \"item_vendor[]\",options_for_select(sub_items.collect{|x|  models[:pl_product].find(x.sub_product_id).vendor_code }), :class=>\'field-x vendor_code\', :style=>\'width:100px\'  %>\r\n          <% else %>\r\n         <%=hidden_field_tag \"item_vendor[]\", p.vendor_code, :class=>\'field-x vendor_code\' %>\r\n        <% end %>\r\n        \r\n    </td>\r\n    <td class=\"cost\">\r\n    <%= cost%>\r\n    </td>\r\n    <td > <span class=\"price_txt\"><%=price%></span>\r\n        <%=hidden_field_tag \"item_price[]\", price, :class=>\'field-x price\', :style=>\'width:50px\' %>\r\n    </td>\r\n   <td >\r\n        <%=text_field_tag \"item_quantity[]\", quantity, :class=>\'field-x quantity\', :style=>\'width:50px\' %>\r\n    </td>\r\n    <td >\r\n        <%=text_field_tag \"item_note[]\", \'\', :class=>\'field-x note\' %>\r\n    </td>\r\n    <td class=\"delete\">\r\n        <%=link_to \"Delete\", \"#\", :class=>\'del-x\',:id=>\"\\\\#{item.id}\" %>\r\n \r\n    </td>\r\n    </tr>\r\n    <%  if sub_items.size>0 and  opt==false\r\n    \r\n     for x in sub_items\r\n                   p = models[:pl_product].find(x.sub_product_id)\r\n        %>\r\n        <tr class=\"r<%=item.id%>\">\r\n            <td>&nbsp;&nbsp;- <%=p.code%></td><td><%=x.detail%></td><td><%=p.vendor_group%></td><td><%=p.vendor_code%></td><td><%=x.cost%></td><td></td><td><%=x.quantity%></td>\r\n            <td></td><td></td>\r\n        </tr>\r\n         <% end %>\r\n   \r\n     <% end %>\r\n       \r\n    <%\r\n       sub_items = models[:pl_additional_product_bom].where(:project_item_id=>item.id).all\r\n    %>\r\n       <%  if sub_items.size>0 \r\n    \r\n     for x in sub_items\r\n                   p = models[:pl_product].find(x.sub_product_id)\r\n                   \r\n                   bom = models[:pl_product_bom].where(:product_id=>p.id).all\r\n                   \r\n        %>\r\n        <tr class=\"r<%=item.id%>\">\r\n            <td>&nbsp;&nbsp;- <%=p.code%></td><td><%=p.name %></td><td><%=p.vendor_group%></td>\r\n            \r\n            <td><%=select_tag \"sub_vendor_item[\\\\#{item.id}][\\\\#{x.id}]\", options_for_select(bom.collect{|x| y= models[:pl_product].find(x.sub_product_id); [y.vendor_code,x.sub_product_id] }), :style=>\'width:100px\' %> </td>\r\n            \r\n            <td><%=p.cost%></td><td><%=p.price%></td><td><%=x.quantity%></td>\r\n            <td></td><td></td>\r\n        </tr>\r\n         <% end %>\r\n   \r\n     <% end %>\r\n       \r\n    \r\n    \r\n    </tbody>\r\n        \r\n    </table>\r\n    \r\n</div>',NULL,NULL,NULL,'2019-03-11 17:48:52','2019-03-11 17:48:52','add_item',''),(3967,'document_name',1566,1,'\'visit_additional_item_bom\'',NULL,NULL,NULL,'2019-03-12 16:50:25','2019-03-12 16:50:25',NULL,NULL),(3968,'document_name',1567,1,'\'bowel_preparation_record\'',NULL,NULL,NULL,'2019-03-13 08:42:49','2019-03-13 08:42:49',NULL,NULL),(3969,'form',1518,3,'<%\r\n   fparams = params[:form]\r\n   model = fparams[:model]\r\n   f = fparams[:form]\r\n   @record = fparams[:record]\r\n   @project =  context[:project]\r\n   @document =  get_document this.document_name \r\n\r\n%>\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n<script>\r\n    $(document).ready(function(){\r\n        $(\"#data-estrogen_receptor,#data-progesterone_receptor,#data-ki\").focusout(function(){\r\n            $(this).data(\"kendoComboBox\").value(checkPercent($(this).val()));\r\n        });\r\n            \r\n        function checkPercent(i){\r\n            if(!isNaN(i)&&i!=\'\'){\r\n                num = parseFloat(i);\r\n                if(num<0) num=0;\r\n                if(num>100) num=100;\r\n                return num\r\n            }else{\r\n                return i\r\n            }\r\n        }\r\n    });\r\n</script>',NULL,NULL,NULL,'2019-03-14 04:03:53','2019-03-14 04:03:53','form',''),(3970,'document_name',1568,1,'\'add_antiher2_mbc\'',NULL,NULL,NULL,'2019-03-15 02:47:30','2019-03-15 02:47:30',NULL,NULL),(3971,'document_name',1569,1,'\'add_antiher2_ebc\'',NULL,NULL,NULL,'2019-03-15 02:48:41','2019-03-15 02:48:41',NULL,NULL),(3972,'index',1570,2,'\r\n <script type=\"text/javascript\">\r\n  function openURL()\r\n  {\r\n      var shell = new ActiveXObject(\"WScript.Shell\");\r\n      shell.run(\"Firefox http://www.google.com\");\r\n  }\r\n  </script>\r\n<div class=\"row-fluid\" >\r\n<div class=\"span12\" background=\"#fff\">\r\n<center>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<form class=\"well form-inline\" style=\"width:300px\" action=\"./authen\">\r\n	<p class=\"f_legend\">RRT E-Learning System</p>\r\n	<input type=\"remail\" name=\'email\' placeholder=\"Email\" style=\"height: auto;\"><br /><br />\r\n\r\n	<button class=\"btn\" type=\"submit\">Login</button>\r\n\r\n</form>\r\n</center>\r\n									\r\n</div>\r\n\r\n\r\n\r\n\r\n    \r\n</div>\r\n',NULL,NULL,NULL,'2019-03-18 07:50:44','2019-03-18 07:50:44','','*'),(3973,'layout',1570,4,'<html>\r\n<head>\r\n<title>RRT - <%=@current_service%></title>\r\n<%=include_header%>\r\n\r\n<style>\r\n    html { \r\n  background