n<%\r\nrequire \'csv\'\r\n\r\nout = CSV.generate do |csv|\r\n  csv << fields.collect{|i| i.column_name}\r\n  for i in list\r\n  csv << fields.collect{|f| i[f.column_name] }\r\n  end\r\n  # ...\r\nend\r\n\r\n%>\r\n<%=out%>\r\n<% end %>',NULL,NULL,NULL,'2019-03-20 02:44:41','2019-03-20 02:44:41','export',''),(3982,'main',1570,2,'<%\r\n    if !session[:member_id] \r\n%>        \r\n<META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=index\">\r\n<%\r\n    else\r\n%>\r\n<style>\r\n.courseHeader{\r\nbackground: rgba(73,155,234,1);\r\nbackground: -moz-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -webkit-gradient(left top, right top, color-stop(0%, rgba(73,155,234,1)), color-stop(100%, rgba(0,4,40,1)));\r\nbackground: -webkit-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -o-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -ms-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: linear-gradient(to right, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#499bea\', endColorstr=\'#000428\', GradientType=1 );\r\ncolor:white;\r\n\r\n}\r\n.text-detail{\r\n    font-size:1.4em;\r\n    line-height: 1.4em;\r\n    font-family: \'Designil Font\', \'Helvetica\', sans-serif;\r\n    font-weight:lighter;\r\n}\r\n.text-detail2{\r\n    font-size:1.3em;\r\n    line-height: 1.3em;\r\n    font-family: \'Designil Font\', \'Helvetica\', sans-serif;\r\n    font-weight:lighter;\r\n}\r\n.circleBase {\r\n    border-radius: 50%;\r\n    behavior: url(PIE.htc); /* remove if you don\'t care about IE8 */\r\n}\r\n.type1 {\r\n    padding:10 20 10 20;\r\n    font-weight:bold;\r\n    color:white;\r\n    width: 100px;\r\n    height: 100px;\r\n    background: #499bea;\r\n}\r\n.type2{\r\n    padding:5;\r\n    font-weight:bold;\r\n    color:white;\r\n    width: 100px;\r\n    height: 100px;\r\n    background: #499bea;\r\n}\r\n.type3{\r\n    padding:5;\r\n    background: #52AC52	;\r\n    float:right;\r\n    border:solid 2px white;\r\n}\r\n.process-item{\r\n    -webkit-border-radius: 5px;\r\n    -moz-border-radius: 5px;\r\n    border-radius: 5px;\r\n    padding:10px;\r\n    margin:5px;\r\n}\r\n.process-ready{\r\n    background: #dbdbdb;\r\n    font-size:1.2em;\r\n}\r\n.process-ready:hover{\r\n    background: #b6d7f5;\r\n    font-size:1.4em;\r\n}\r\n.process-done{\r\n    background: #b6d7f5;\r\n    font-size:1.2em;\r\n}\r\n.process-done2{\r\nbackground: rgba(181,219,162,1);\r\nbackground: -moz-linear-gradient(left, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: -webkit-gradient(left top, right top, color-stop(0%, rgba(181,219,162,1)), color-stop(100%, rgba(82,172,82,1)));\r\nbackground: -webkit-linear-gradient(left, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: -o-linear-gradient(left, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: -ms-linear-gradient(left, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: linear-gradient(to right, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#b5dba2\', endColorstr=\'#52ac52\', GradientType=1 );\r\n}\r\n.warndate{\r\n    font-weight:bold;\r\n    color:red;\r\n}\r\n.btn-course{\r\n    font-size:2em;\r\n    padding:30px;\r\n}\r\n.login-name{\r\n    background: rgba(189,195,199,1);\r\n    background: -moz-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: -webkit-gradient(left top, right top, color-stop(0%, rgba(189,195,199,1)), color-stop(100%, rgba(114,159,204,1)));\r\n    background: -webkit-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: -o-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: -ms-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: linear-gradient(to right, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#bdc3c7\', endColorstr=\'#729fcc\', GradientType=1 ); \r\n    font-size:1.2em;\r\n    -webkit-border-radius: 5px;\r\n    -moz-border-radius: 5px;\r\n    border-radius: 5px;\r\n    padding:5;\r\n    opacity:0.8;\r\n}\r\n</style>\r\n<%\r\n    models = get_model\r\n    courses = models[:course].all\r\n    lessons = models[:lesson].all\r\n    processes = models[:process].all\r\n    \r\n    hls = Hash[lessons.collect{|i| [i.id,i]}]\r\n    \r\n    #init\r\n    member = models[:member].find( session[:member_id]) \r\n    member_id = member.id \r\n    \r\n    trackings = models[:tracking].where(:member_id=>member_id).all\r\n%>\r\n<%#hls.inspect %>\r\n<div class=\"row-fluid\">\r\n<div class=\"span1\">&nbsp;</div>\r\n<div class=\"span10\">\r\n<div class=\"row-fluid\">\r\n<div class=\"span12 login-name\">\r\n<div class=\"span8\"></div><div class=\"span4\" style=\"text-align: right;\"><i class=\"splashy-contact_blue\"></i> <%=member.fullname%> <%=link_to \'logout <i class=\"icon-share\"></i>\'.html_safe, \"logout\",:class=>\"btn\"%></div>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<%\r\n    for c in courses\r\n        #ls = lessons.collect{|i| i if c.lessons and c.lessons.include?(i.id)}.compact\r\n\r\n        ls = c.lessons.collect{|i| hls[i]}\r\n        \r\n        tcs = trackings.collect{|i| i if i.course_id==c.id}.compact\r\n        tc = tcs.collect{|i| i if i.type==\'course\'}.compact\r\n        c_status = \'\'\r\n        c_status = tc[0].status if tc.size>0\r\n%>\r\n    <div class=\"well courseHeader\">\r\n      <h1><%=c.name%></h1>\r\n      <p class=\"text-detail\">\r\n         <%=c.detail.html_safe%>\r\n      </p>\r\n      <div class=\"row-fluid\">\r\n<%      if c_status==\'finished\' %>\r\n        <a class=\"btn btn-success btn-large btn-course disabled span6\">\r\n          Finished\r\n        </a>\r\n<%      else %>\r\n        <a class=\"btn btn-warning btn-large btn-course btn-continue span6\" cid=\"<%=c.id%>\">\r\n          <%=(c_status==\'\')?\"Start learning\":\"Continue learning\"%>\r\n        </a>\r\n<%      end %> \r\n      </div>\r\n      <div style=\"text-align:bottom\">\r\n      <i class=\"icon-play icon-white\"></i> 6 Videos \r\n      | <i class=\"icon-list icon-white\"></i> 3 Exercises\r\n      <!--| <i class=\"icon-time icon-white\"></i> 4 hours -->\r\n      </div>\r\n    </div><!-- hero-unit -->\r\n<%\r\n        l_no = 0\r\n        for l in ls\r\n            l_no += 1\r\n            ps = processes.collect{|i| i if l.processes and l.processes.include?(i.id)}.compact\r\n            tl = tcs.collect{|i| i if i.type==\'lesson\' and i.link_id==l.id}.compact\r\n            progress = 0\r\n            lstart = \'-\'\r\n            lfinish = \'-\'\r\n            if tl.size>0\r\n                progress = tl[0].progress if tl[0].progress\r\n                lstart = tl[0].created_at.strftime(\'%d/%m/%y %H:%M\') if tl[0].created_at\r\n                lfinish = tl[0].finished_date.strftime(\'%d/%m/%y %H:%M\') if tl[0].finished_date\r\n            end\r\n%>    \r\n    <div class=\"well\">\r\n        <div class=\"row-fluid\">\r\n            <div class=\"span8\"><h3><span class=\"circleBase type1\"><%=l_no%></span> <%=l.name%>\r\n            </h3></div>\r\n            <div class=\"span4\">\r\n                <div class=\"progress progress-<%=(progress==100?\"success\":\"warning\")%>\">\r\n                  <div class=\"bar\" style=\"width: <%=progress%>%\"><%=progress%>% </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n<%\r\n            is_limit = false\r\n            has_limit = false\r\n            limit_date = Time.now\r\n            limit_date = l.limit_date if l.limit_date\r\n            if tl.size>0\r\n               limit_date = tl[0].limit_date if tl[0].limit_date\r\n               limit_date = l.limit_date if l.limit_date and tl[0].limit_date and l.limit_date<tl[0].limit_date\r\n               has_limit = true if tl[0].limit_date or l.limit_date\r\n               is_limit=(Time.now>limit_date.end_of_day) if limit_date\r\n\r\n                \r\n                for p in ps\r\n                    tp = tcs.collect{|i| i if i.type==\'process\' and i.link_id==p.id}.compact\r\n                    p_class = \"process-ready\"\r\n                    p_status = \"hide\"\r\n                    p_click = \"btn-continue\"\r\n                    if tp.size>0 and tp[0].status==\'finished\'\r\n                        p_class = \"process-done\"\r\n                        p_status = \"\"\r\n                        p_click = \"p-\"+p.type\r\n                    end\r\n                    \r\n%>        \r\n        <div class=\"process-item <%=p_class%> <%=p_click%>\" pid=\"<%=p.id%>\" lid=\"<%=l.id%>\" cid=\"<%=c.id%>\">\r\n            <span class=\"circleBase type2\"><i class=\"icon-<%=(p.type==\'Video\')?\"play\":\"list\"%> icon-white\" ></i></span> <%=p.name%>   \r\n            <span class=\"circleBase type3 <%=p_status%>\"><i class=\"icon-ok icon-white\" ></i></span>\r\n        </div>\r\n<%\r\n                end #for p\r\n%>        \r\n        <div class=\"row-fluid\">\r\n            <div class=\"span<%=(has_limit)?\"4\":\"8\"%>\">Start : <%=lstart%> </div>\r\n            <div class=\"span4\">Finish : <%=lfinish%> </div>\r\n            <% if has_limit %>\r\n            <div class=\"span4 warndate\">Limit : <%=limit_date.strftime(\"%d/%m/%y\")%> 23:59 </div>\r\n            <% end %>\r\n        </div>   \r\n<%          end #if tl.size>0 %>\r\n    </div><!-- hero-unit -->\r\n<%\r\n        end # for l\r\n    end #for c \r\n %>\r\n\r\n</div><!--span10-->\r\n</div><!--container-fluid-->\r\n<script>\r\n$(document).ready(function(){\r\n    $(\".p-Video\").click(function(){\r\n        document.location.href=\'./video?id=\'+$(this).attr(\"pid\")+\'&lid=\'+$(this).attr(\"lid\")+\'&cid=\'+$(this).attr(\"cid\");\r\n    });\r\n    $(\".p-Exam\").click(function(){\r\n        document.location.href=\'./exam?id=\'+$(this).attr(\"pid\")+\'&lid=\'+$(this).attr(\"lid\")+\'&cid=\'+$(this).attr(\"cid\");\r\n    });\r\n    $(\".btn-continue\").click(function(){conL($(this).attr(\"cid\"));});\r\n\r\n});\r\n\r\nfunction conL(id){\r\n    path = \'../Home/continue\';\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: path,\r\n        data: {\r\n            cid: id\r\n        },\r\n        success: function(doc) {\r\n            document.location.href=doc;\r\n        }\r\n    });\r\n}\r\n\r\n\r\n</script>\r\n<% end %>\r\n<div class=\"clear\"></div>',NULL,NULL,NULL,'2019-03-20 05:48:50','2019-03-20 05:48:50','main','*'),(3983,'video',1570,2,'<%\r\n    if !session[:member_id] \r\n%>        \r\n<META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=index\">\r\n<%\r\n    else\r\n%>\r\n<style>\r\nvideo {\r\n  width: 100%    !important;\r\n  height: auto   !important;\r\n}\r\n.courseHeader{\r\nbackground: rgba(73,155,234,1);\r\nbackground: -moz-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -webkit-gradient(left top, right top, color-stop(0%, rgba(73,155,234,1)), color-stop(100%, rgba(0,4,40,1)));\r\nbackground: -webkit-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -o-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -ms-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: linear-gradient(to right, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#499bea\', endColorstr=\'#000428\', GradientType=1 );\r\ncolor:white;\r\n}\r\n.circleBase {\r\n    border-radius: 50%;\r\n    behavior: url(PIE.htc); /* remove if you don\'t care about IE8 */\r\n}\r\n.type3{\r\n    padding:5;\r\n    background: #52AC52	;\r\n    float:right;\r\n    border:solid 2px white;\r\n}\r\n.login-name{\r\n    background: rgba(189,195,199,1);\r\n    background: -moz-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: -webkit-gradient(left top, right top, color-stop(0%, rgba(189,195,199,1)), color-stop(100%, rgba(114,159,204,1)));\r\n    background: -webkit-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: -o-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: -ms-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: linear-gradient(to right, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#bdc3c7\', endColorstr=\'#729fcc\', GradientType=1 ); \r\n    font-size:1.2em;\r\n    -webkit-border-radius: 5px;\r\n    -moz-border-radius: 5px;\r\n    border-radius: 5px;\r\n    padding:5;\r\n    opacity:0.8;\r\n}\r\n</style>\r\n<%\r\n    #init\r\n    models = get_model\r\n    member = models[:member].find( session[:member_id]) \r\n    member_id = member.id \r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"row-fluid\">\r\n<div class=\"span12 login-name\">\r\n<div class=\"span8\"></div><div class=\"span4\" ><i class=\"splashy-contact_blue\"></i> <%=member.fullname%> <%=link_to \'logout <i class=\"icon-share\"></i>\'.html_safe, \"logout\",:class=>\"btn\"%></div>\r\n</div>\r\n</div>\r\n<%\r\n    if params[:id]\r\n        \r\n        l = []\r\n        l = models[:lesson].find(params[:lid]) if params[:lid]\r\n        index = 0\r\n        size = 0\r\n        if l\r\n            p_list = l.processes\r\n            size = p_list.size\r\n            index = p_list.index(BSON::ObjectId.from_string(params[:id]))+1\r\n            \r\n        end\r\n        p = models[:process].find(params[:id])\r\n        if p\r\n            t = models[:tracking].where(:member_id=>member_id,:course_id=>BSON::ObjectId.from_string(params[:cid])).all\r\n            is_limit = false\r\n            has_limit = false\r\n            is_f =false\r\n            limit_date = Time.now\r\n            limit_date = l.limit_date if l.limit_date\r\n            if t\r\n               tl= t.collect{|i| i if i.link_id==l.id}.compact\r\n               if tl and tl.size>0\r\n                   limit_date = tl[0].limit_date if tl[0].limit_date\r\n                   limit_date = l.limit_date if l.limit_date and tl[0].limit_date and l.limit_date<tl[0].limit_date\r\n                   has_limit = true if tl[0].limit_date or l.limit_date\r\n                end\r\n                tps= t.collect{|i| i if i.link_id==p.id and i.finished_date}.compact\r\n                is_f = (tps.size>0)\r\n            end\r\n            is_limit=(Time.now>limit_date.end_of_day) \r\n            v = []\r\n            v = models[:video].find(p.videos) if p.videos\r\n            if v and v.name\r\n%>\r\n    <div class=\"well courseHeader\">\r\n      <p class=\"text-warning\">\r\n            <%=v.name%><%=\"<span class=\'circleBase type3\'><i class=\'icon-ok icon-white\'></i></span>\".html_safe if is_f%>\r\n<%              if has_limit %>\r\n            <span style=\"float:right\">Expire : <%=limit_date.strftime(\"%d/%m/%y\")%></span>\r\n<%              end %>\r\n      </p>\r\n<%          if !is_limit %>      \r\n        <video  controls=\"controls\" controlsList=\"nodownload\" poster=\"<%=v.poster%>\">\r\n            <source src=\"<%=v.source%>\" type=\'video/mp4\'/>\r\n        </video> \r\n<%          else %>\r\n        <video  controls=\"controls\" controlsList=\"nodownload\" poster=\"/esm/elearning/www/content/expired.jpg\">\r\n            <source src=\"\" type=\'video/mp4\'/>\r\n        </video> \r\n<%          end %>        \r\n        \r\n        <div class=\"row-fluid\">\r\n        <div class=\"span12 \"><br><br></div>\r\n        <div class=\"span12 \">\r\n            <center>\r\n            <div style=\"float:left\">\r\n            <a class=\"btn btn-warning btn-large btn-back\">\r\n              <i class=\"icon-backward icon-white\"></i> Back\r\n            </a>\r\n            </div>\r\n            <span style=\"font-size:1.8em\"><%=index%>/<%=size%></span>\r\n            <div style=\"float:right\">\r\n            <a class=\"btn btn-warning btn-large btn-next\">\r\n              Next <i class=\"icon-forward icon-white\"></i>\r\n            </a>\r\n            </div>\r\n            </center>\r\n        </div><!--span12-->\r\n        </div><!--row-fluid-->        \r\n    </div><!-- hero-unit -->\r\n<%\r\n        \r\n            end#if v\r\n        end#if p\r\n    end #if params[:id]\r\n%>    \r\n    \r\n</div><!--span10-->\r\n</div><!--container-fluid-->\r\n<script>\r\n$(document).ready(function(){\r\n    $(\".btn-next\").click(function(){next();});\r\n    $(\".btn-back\").click(function(){back();});\r\n});\r\n\r\nfunction next(){\r\n    path = \'../Home/next\';\r\n    id=\'<%=params[:id]%>\';\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: path,\r\n        data: {\r\n            pid: id\r\n        },\r\n        success: function(doc) {\r\n            document.location.href=doc;\r\n        }\r\n    });\r\n}\r\nfunction back(){\r\n    path = \'../Home/back\';\r\n    id=\'<%=params[:id]%>\';\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: path,\r\n        data: {\r\n            pid: id\r\n        },\r\n        success: function(doc) {\r\n            document.location.href=doc;\r\n        }\r\n    });\r\n}\r\n</script>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2019-03-20 09:30:45','2019-03-20 09:30:45','video','*'),(3984,'exam',1570,2,'<%\r\n    if !session[:member_id] \r\n%>        \r\n<META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=index\">\r\n<%\r\n    else\r\n%>\r\n<style>\r\n.ques{\r\n    font-size:1.4em;\r\n    line-height: 1.4em;\r\n    padding:30px;\r\n    margin:10px;\r\n    -webkit-border-radius: 10px;\r\n    -moz-border-radius: 10px;\r\n    border-radius: 10px;\r\n}\r\n.qcolor1{\r\n    background: rgba(189,195,199,1);\r\n 