ckground: linear-gradient(to right, rgba(255,210,0,1) 0%, rgba(247,151,30,1) 100%);\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#ffd200\', endColorstr=\'#f7971e\', GradientType=1 );\r\n}\r\n.courseHeader{\r\nbackground: rgba(73,155,234,1);\r\nbackground: -moz-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -webkit-gradient(left top, right top, color-stop(0%, rgba(73,155,234,1)), color-stop(100%, rgba(0,4,40,1)));\r\nbackground: -webkit-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -o-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -ms-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: linear-gradient(to right, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#499bea\', endColorstr=\'#000428\', GradientType=1 );\r\ncolor:white;\r\n}\r\n.lesson-index{\r\n    font-size:2em;\r\n    vertical-align:text-bottom;\r\n    -webkit-border-radius: 10px;\r\n    -moz-border-radius: 10px;\r\n    border-radius: 10px;\r\n    padding:20 20 40 20;\r\n    margin:20px;\r\n\r\n    background: #dbdbdb;  \r\n\r\n}\r\n.btn-course{\r\n    font-size:2em;\r\n    padding:30px;\r\n    \r\n}\r\n.text-detail{\r\n    font-size:1.4em;\r\n    line-height: 1.4em;\r\n    font-family: \'Designil Font\', \'Helvetica\', sans-serif;\r\n    font-weight:lighter;\r\n}\r\n\r\n.circleBase {\r\n    border-radius: 50%;\r\n    behavior: url(PIE.htc); /* remove if you don\'t care about IE8 */\r\n}\r\n.type3{\r\n    padding:8;\r\n    background: #52AC52	;\r\n    border:solid 2px white;\r\n}\r\n.lds-ring {\r\n  display: inline-block;\r\n  position: relative;\r\n  width: 64px;\r\n  height: 64px;\r\n}\r\n.lds-ring div {\r\n  box-sizing: border-box;\r\n  display: block;\r\n  position: absolute;\r\n  width: 51px;\r\n  height: 51px;\r\n  margin: 6px;\r\n  border: 6px solid #ffd200;\r\n  border-radius: 50%;\r\n  animation: lds-ring 1.2s cubic-bezier(0.5, 0, 0.5, 1) infinite;\r\n  border-color: #ffd200 transparent transparent transparent;\r\n}\r\n.lds-ring div:nth-child(1) {\r\n  animation-delay: -0.45s;\r\n}\r\n.lds-ring div:nth-child(2) {\r\n  animation-delay: -0.3s;\r\n}\r\n.lds-ring div:nth-child(3) {\r\n  animation-delay: -0.15s;\r\n}\r\n@keyframes lds-ring {\r\n  0% {\r\n    transform: rotate(0deg);\r\n  }\r\n  100% {\r\n    transform: rotate(360deg);\r\n  }\r\n}\r\n#congratscore{\r\n    color:#52AC52;\r\n}\r\n.login-name{\r\n    background: rgba(189,195,199,1);\r\n    background: -moz-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: -webkit-gradient(left top, right top, color-stop(0%, rgba(189,195,199,1)), color-stop(100%, rgba(114,159,204,1)));\r\n    background: -webkit-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: -o-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: -ms-linear-gradient(left, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    background: linear-gradient(to right, rgba(189,195,199,1) 0%, rgba(114,159,204,1) 100%);\r\n    filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#bdc3c7\', endColorstr=\'#729fcc\', GradientType=1 ); \r\n    font-size:1.2em;\r\n    -webkit-border-radius: 5px;\r\n    -moz-border-radius: 5px;\r\n    border-radius: 5px;\r\n    padding:5;\r\n    opacity:0.8;\r\n}\r\n</style>\r\n<%\r\n    #init\r\n    models = get_model\r\n    member = models[:member].find( session[:member_id]) \r\n    member_id = member.id \r\n    l_name = \'\'\r\n    p_name = \'\'\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12 login-name\">\r\n<div class=\"span8\"></div><div class=\"span4\" style=\"text-align:right\"><i class=\"splashy-contact_blue\"></i> <%=member.fullname%> <%=link_to \'logout <i class=\"icon-share\"></i>\'.html_safe, \"logout\",:class=>\"btn\"%></div>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n<div id=\"congrat\" class=\"modal hide fade\">\r\n<style>\r\n.cgbody{\r\n  background: url(/esm/elearning/www/content/congrat.jpg)  ; \r\n  font-size:1.6em;  \r\n  line-height: 1.6em;\r\n  height:200px;\r\n  color:#000428;\r\n}\r\n</style>\r\n  <div class=\"modal-header\">\r\n    <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-hidden=\"true\">&times;</button>\r\n    <h3><span id=\"congrathead\"></span></h3>\r\n  </div>\r\n  <div class=\"modal-body cgbody\">\r\n    <p><center><span id=\"congratbody\">\r\n    <div class=\"lds-ring\"><div></div><div></div><div></div><div></div></div>\r\n    </span>\r\n    <div id=\"congratscore\" class=\"row-fluid\">\r\n        \r\n    </div>\r\n    <br><a href=\"#\" class=\"btn btn-warning btn-large\" id=\"btnCon\">Continue <i class=\"icon-forward icon-white\"></i></a>\r\n    </center></p>\r\n  </div>\r\n  <div class=\"modal-footer\">\r\n    \r\n  </div>\r\n</div>\r\n<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n<div class=\"row-fluid\">\r\n</div>\r\n<%\r\n    if params[:id]\r\n        \r\n        l = []\r\n        l = models[:lesson].find(params[:lid]) if params[:lid]\r\n\r\n        p = models[:process].find(params[:id])\r\n        if p\r\n            p_name = p.name\r\n            l_name = l.name\r\n            t = models[:tracking].where(:member_id=>member_id,:course_id=>BSON::ObjectId.from_string(params[:cid])).all\r\n            is_limit = false\r\n            has_limit = false\r\n            is_open = true\r\n            limit_date = Time.now\r\n            limit_date = l.limit_date if l.limit_date \r\n            open_date = Time.now\r\n            open_date = l.open_date if l.open_date\r\n            is_open = (Time.now>open_date.beginning_of_day) \r\n            if t\r\n               tl= t.collect{|i| i if i.link_id==l.id}.compact\r\n               if tl and tl.size>0\r\n                   limit_date = tl[0].limit_date if tl[0].limit_date\r\n                   limit_date = l.limit_date if l.limit_date and tl[0].limit_date and l.limit_date<tl[0].limit_date\r\n                   has_limit = true if tl[0].limit_date or l.limit_date\r\n                end\r\n            end\r\n            is_limit=(Time.now>limit_date.end_of_day) \r\n            tp= t.collect{|i| i if i.link_id==p.id}.compact\r\n            if tp and tp.size>0            \r\n            if tp[0].status==\'finished\'\r\n%>\r\n<div class=\"well courseHeader\">\r\n    <h2><%=l.name%></h2>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12 cgbody\">\r\n    <center>\r\n    <br>\r\n        <%=p_name%>\r\n        สำเร็จแล้ว\r\n        <span class=\'circleBase type3\'><i class=\'icon-ok icon-white\' style=\'margin-top:4px\'></i></span>\r\n        <br>\r\n<%\r\n                if l.show_score and l.show_score==\'true\'\r\n                    tl = t.collect{|i| i if i.link_id==l.id and i.finished_date}.compact\r\n                    if tl and tl.size>0\r\n                        score = 0\r\n                        full = 0\r\n                        per = 0\r\n                        score = tl[0].score if tl[0].score\r\n                        full = l.score if l.score\r\n                        per = (score*100)/full if full>0\r\n                        if l.after\r\n                            ta = t.collect{|i| i if i.link_id==l.after and i.finished_date}.compact\r\n                            %> <%=l.name+\" [\"+score.to_s+\"/\"+full.to_s+\"] \"+per.to_s+\"%\" if ta and ta.size>0 %><%\r\n                        else\r\n                            %> <%=l.name+\" [\"+score.to_s+\"/\"+full.to_s+\"] \"+per.to_s+\"%\" %><%\r\n                        end\r\n                    end\r\n                end\r\n%>        \r\n        </center>\r\n    </div>\r\n    <div class=\"span12\"><br><br></div>\r\n    </div>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12 \">\r\n        <center>\r\n        <div style=\"float:left\">\r\n        <a class=\"btn btn-warning btn-large btn-back\">\r\n          <i class=\"icon-backward icon-white\"></i> Back\r\n        </a>\r\n        </div>\r\n        <div style=\"float:right\">\r\n        <a class=\"btn btn-warning btn-large btn-next\">\r\n          Next <i class=\"icon-forward icon-white\"></i>\r\n        </a>\r\n        </div>\r\n        </center>\r\n    </div><!--span12-->\r\n    </div><!--row-fluid-->\r\n    \r\n</div>\r\n\r\n<%\r\n            else   #if tp[0].status\r\n            if !is_open\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span1\"></div>\r\n<div class=\"span10\">\r\n<div class=\"well courseHeader\">\r\n    <h2><%=l.name%></h2>\r\n    <p class=\"text-detail\"><%=l.detail.html_safe%></p>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12\"><br><br></div>\r\n    </div>\r\n    <div class=\"row-fluid\">\r\n    <div class=\"span12 \">\r\n        <center>\r\n        <div style=\"float:left\">\r\n        <a class=\"btn btn-warning btn-large btn-back\">\r\n          <i class=\"icon-backward icon-white\"></i> Back\r\n        </a>\r\n        </div>\r\n        </center>\r\n    </div><!--span12-->\r\n    </div><!--row-fluid-->\r\n    \r\n</div>\r\n</div>\r\n</div>\r\n<%\r\n            else    \r\n                e = []\r\n                e = models[:exam].find(p.exams) if p.exams\r\n                if e and e.name\r\n%>\r\n\r\n    <div class=\"well\">\r\n        <h2><%=l.name%></h2>\r\n        <div class=\"row-fluid\">\r\n<%                         \r\n                if e.questions\r\n                    qindex = e.questions.size\r\n                    \r\n                    els = models[:examlog].where(:track_id=>tp[0].id).all\r\n                    q= models[:question].find(e.questions[0])\r\n                    if params[:qid]\r\n                        q = models[:question].find(params[:qid])\r\n                    else\r\n                        if els and els.size>0\r\n                            el_now = els.collect{|i| i if i.status==\'started\'}.compact\r\n                            q = models[:question].find(el_now[0].question_id) if el_now.size>0\r\n                        end\r\n                    end\r\n                    \r\n                    qindex = 1\r\n                    qindex = e.questions.index(q.id)+1 if q and q.id\r\n                    qnext = \'next\'\r\n                    qnext = e.questions[qindex] if  qindex<e.questions.size\r\n                    qback = \'back\'\r\n                    qback = e.questions[qindex-2] if qindex>1\r\n                    if q and q.name\r\n                        el_q = els.collect{|i| i if i.question_id==q.id}.compact\r\n                        el = {}\r\n                        if el_q.size==0 # new entry \r\n                            el = models[:examlog].create :track_id=>tp[0].id,:question_id=>q.id,:status=>\'started\'\r\n                        else\r\n                            el = el_q[0]\r\n                        end\r\n                        \r\n%>       \r\n        <div class=\"span12 ques qcolor<%=(qindex%3)+1%>\">\r\n          <%=qindex%>. <%=q.name.html_safe%>\r\n          <input type=\"hidden\" id=\"elid\" value=\"<%=el.id%>\">\r\n        </div>\r\n        <div class=\"row-fluid\">\r\n<%\r\n                        if q.answers\r\n                            as = models[:answer].find(q.answers)\r\n                            choice = \'a\'\r\n                            nchoice = 0\r\n                            istext=false\r\n                            for a in as\r\n                                istext = (a.text and a.text==\'true\')\r\n%>        \r\n        <div class=\"span<%=(istext)?\"10\":\"5\"%> ans <%=(a.id==el.answer_id)?\"ansselect\":\"\"%>\" aid=\"<%=a.id%>\">\r\n          <%=choice%>. <%=a.name.html_safe%>\r\n          <% if istext\r\n                nchoice=1\r\n          %>\r\n          <textarea class=\"span12\" rows=\"5\"><%=(a.id==el.answer_id and el.text)?\"\\\\#{el.text}\":\"\"%></textarea>\r\n          <% end %>\r\n        </div>\r\n        <%=\"</div><div class=\'row-fluid\'>\".html_safe if nchoice%2==1 %>\r\n<%                      \r\n                            choice.next!\r\n                            nchoice+=1\r\n                            end #for a\r\n                        end #if q.answers\r\n                    end #if q \r\n\r\n%>        \r\n        </div><!--row-fluid-->\r\n        </div><!--row-fluid-->\r\n        \r\n        <div class=\"row-fluid\">\r\n        <div class=\"span12 lesson-index\">\r\n            <center>\r\n            <div style=\"float:left\">\r\n            <a class=\"btn btn-warning btn-large btn-exam eback\" nid=\"<%=qback%>\">\r\n              <i class=\"icon-backward icon-white\"></i> Back\r\n            </a>\r\n            </div>\r\n            <%=qindex%>/<%=e.questions.size%>\r\n            <div style=\"float:right\">\r\n            <a class=\"btn btn-warning btn-large btn-exam\" nid=\"<%=qnext%>\">\r\n              Next <i class=\"icon-forward icon-white\"></i>\r\n            </a>\r\n            </div>\r\n            </center>\r\n        </div><!--span12-->\r\n        </div><!--row-fluid-->\r\n    </div><!-- hero-unit -->\r\n<%\r\n                            end #if e.questions \r\n                        end #if e\r\n                    end #if tp[0].status\r\n                end #if !is_open\r\n            end #if tp\r\n        end #if p\r\n    end # if params[:id]\r\n\r\n\r\n%>    \r\n    \r\n</div><!--span10-->\r\n</div><!--container-fluid-->\r\n<input type=\"hidden\" id=\"n_url\" value=\"\">\r\n<input type=\"hidden\" id=\"l_name\" value=\"<%=l_name%>\">\r\n<input type=\"hidden\" id=\"p_name\" value=\"<%=p_name%>\">\r\n<img src=\"/esm/elearning/www/content/congrat.jpg\" class=\"hide\">\r\n<script>\r\n$(document).ready(function(){\r\n    $(\".btn-next\").click(function(){next();});\r\n    $(\".btn-back\").click(function(){back();});\r\n    $(\".ans\").click(function(){\r\n        $(\".ans\").removeClass(\"ansselect\");\r\n        $(this).addClass(\"ansselect\");\r\n    });\r\n    $(\".btn-exam\").click(function(){\r\n        if(!$(this).hasClass(\"disabled\")){\r\n            $(this).addClass(\"disabled\");\r\n            save_exam($(this).attr(\"nid\"),$(this).hasClass(\"eback\"));\r\n        }\r\n    });\r\n    $(\"#congrat\").on(\'hidden\',function(){\r\n        // alert($(\"#n_url\").val());\r\n        document.location.href=$(\"#n_url\").val();\r\n    });\r\n    $(\"#btnCon\").click(function(){$(\"#congrat\").modal(\'hide\');})\r\n});\r\n\r\nfunction save_exam(nextid,canskip){\r\n    path = \'../Examlog/update\';\r\n    id=$(\"#elid\").val();\r\n    aid=$(\".ansselect\").attr(\"aid\");\r\n    texta=$(\".ansselect\").find(\"textarea\");\r\n    text=(texta.val())?texta.val():\'\';\r\n    // alert(id+\' aid=\'+aid+\' \'+nextid+\' text=\'+text);\r\n    if(!aid&&!canskip){ \r\n        alert(\'กรุณาเลือกคำตอบ\');\r\n        $(\".btn-exam\").removeClass(\"disabled\");\r\n    }else{\r\n        if(nextid==\'back\') back();\r\n        else{\r\n            $.ajax({\r\n                dataType: \"text\",\r\n                url: path,\r\n                data: {\r\n                    id: id,\r\n                    aid:aid,\r\n                    text:text,\r\n                    nextid:nextid\r\n                },\r\n                success: function(doc) {\r\n                    if(nextid==\'next\'){ next(nextid)}\r\n                    else document.location.href=doc;\r\n                }\r\n            });            \r\n        }\r\n    }\r\n\r\n}\r\n\r\nfunction updateScore(){\r\n    $(\"#btnCon\").hide();\r\n    $(\"#congrathead\").html($(\"#l_name\").val());\r\n    $(\"#congrat\").modal(\'show\');  \r\n    $(\"#congratbody\").html(\'ยินดีด้วย \'+$(\"#p_name\").val()+\' สำเร็จแล้ว!\');\r\n    $(\"#btnCon\").show();\r\n    path = \'../Tracking/get_score\';\r\n    id=\'<%=params[:id]%>\';\r\n    cid=\'<%=params[:cid]%>\';\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: path,\r\n        data: {\r\n            pid: id,\r\n            cid:cid\r\n        },\r\n        success: function(doc) {\r\n            // alert(doc)\r\n            obj = JSON.parse(doc);\r\n            txt = \'\'\r\n            $.each(obj,function(i,d){\r\n                txt+= d.name+\' [\'+d.score+\'/\'+d.full+\'] \'+d.percent+\'%<br>\'\r\n            });\r\n            $(\"#congratscore\").html(txt);\r\n        }\r\n    });   \r\n    \r\n}\r\n\r\nfunction next(nid){\r\n    path = \'../Home/next\';\r\n    id=\'<%=params[:id]%>\';\r\n    cid=\'<%=params[:cid]%>\';\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: path,\r\n        data: {\r\n            pid: id,\r\n            cid:cid\r\n        },\r\n        success: function(doc) {\r\n            if(!nid){\r\n                document.location.href=doc;\r\n            }else{\r\n                $(\"#n_url\").val(doc);\r\n                updateScore()\r\n            }\r\n        }\r\n    });\r\n}\r\nfunction back(){\r\n    path = \'../Home/back\';\r\n    id=\'<%=params[:id]%>\';\r\n    cid=\'<%=params[:cid]%>\';\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: path,\r\n        data: {\r\n            pid: id,\r\n            cid: cid\r\n        },\r\n        success: function(doc) {\r\n            document.location.href=doc;\r\n        }\r\n    });\r\n}\r\n</script>\r\n<%\r\n    end\r\n%>',NULL,NULL,NULL,'2019-03-20 13:32:49','2019-03-20 13:32:49','exam','*'),(3986,'edit',1571,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=record.id%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n<!-- Modify edit -->\r\n</div><!--document-border -->\r\n</div><!--border -->\r\n</div><!--w-box-content -->\r\n</div><!--w-box -->\r\n<% \r\n    subtable_name = \'Lesson\' \r\n    maintable = \'course\'\r\n    subtable = \'lesson\'\r\n    subfield = \'lessons\'\r\n%>\r\n<script>\r\n$(document).ready(function(){\r\n    $(\"#<%=subfield%>\").remove();\r\n    $(\"#addSub\").click(function(){\r\n       addSub();\r\n    });\r\n    loadTable();\r\n});\r\n\r\n$.urlParam = function(name){\r\n	var results = new RegExp(\'[\\?&]\' + name + \'=([^&#]*)\').exec(window.location.href);\r\n	return results[1] || 0;\r\n}\r\n\r\nfunction loadTable(){\r\n    var row=\"\";\r\n    id = $.urlParam(\'id\');\r\n    // alert(id);\r\n    row+=\'<thead><th colspan=\"5\"><%=subtable_name%> list</th></thead>\';\r\n    $.ajax({\r\n        dataType: \"json\",\r\n        url: \'../Home/get_sub\',\r\n        data: {\r\n            id: id,\r\n                main : \'<%=maintable%>\',\r\n                sub: \'<%=subtable%>\',\r\n                field: \'<%=subfield%>\'\r\n        },\r\n        success: function(doc) {\r\n            // alert(doc);\r\n            $.each(doc,function(i,d){\r\n                row+=\'<tr><td width=\"80%\">\'+d.name+\'</td>\';\r\n                row+=\'<td><span class=\"btn editS\" sid=\"\'+d.id+\'\">edit</span></td>\';\r\n                row+=\'<td><span class=\"btn upS\" sid=\"\'+d.id+\'\"><i class=\"icon-arrow-up\"></i></span></td>\';\r\n                row+=\'<td><span class=\"btn downS\" sid=\"\'+d.id+\'\"><i class=\"icon-arrow-down\"></i></span></td>\';\r\n                row+=\'<td><span class=\"btn delS\" sid=\"\'+d.id+\'\"><i class=\"icon-trash\"></i></span></td></tr>\';\r\n            });\r\n            $(\"#tableList\").empty().append(row);  \r\n            $(\".editS\").click(function(){\r\n                document.location.href=\"../<%=subtable_name%>/edit?id=\"+$(this).attr(\"sid\")+\"&return=\"+document.location.href;\r\n            });\r\n            $(\".delS\").click(function(){delSub($(this).attr(\"sid\"))});\r\n            $(\".upS\").click(function(){orderSub($(this).attr(\"sid\"),\'up\')});\r\n            $(\".downS\").click(function(){orderSub($(this).attr(\"sid\"),\'down\')});\r\n\r\n        }\r\n    });\r\n}\r\n\r\nfunction addSub(){\r\n    mainid = $.urlParam(\'id\');\r\n    name = $(\"#nameSub\").val();\r\n    if(!$(\"#addSub\").attr(\"disabled\")&&name!=\'\'){\r\n        $(\"#addSub\").attr(\"disabled\", true);\r\n        $(\"#nameSub\").val(\'\');\r\n        // alert(id);\r\n        path = \'../Home/add_sub\';\r\n        $.ajax({\r\n            dataType: \"text\",\r\n            url: path,\r\n            data: {\r\n                id: mainid,\r\n                name : name,\r\n                main : \'<%=maintable%>\',\r\n                sub: \'<%=subtable%>\',\r\n                field: \'<%=subfield%>\'\r\n            },\r\n            success: function(doc) {\r\n                //  alert(doc);\r\n                loadTable();\r\n                $(\"#addSub\").removeAttr(\"disabled\");\r\n            }\r\n        });\r\n    }\r\n}\r\n\r\nfunction delSub(id){\r\n    mainid = $.urlParam(\'id\');\r\n    path = \'../Home/del_sub\';\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: path,\r\n        data: {\r\n            id: id,\r\n            cid: mainid,\r\n            main : \'<%=maintable%>\',\r\n            field: \'<%=subfield%>\'            \r\n        },\r\n        success: function(doc) {\r\n            loadTable();\r\n        }\r\n    });\r\n}\r\n\r\nfunction orderSub(id,order){\r\n    mainid = $.urlParam(\'id\');\r\n    path = \'../Home/order_sub\';\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: path,\r\n        data: {\r\n            id: id,\r\n            cid: mainid,\r\n            order: order,\r\n            main : \'<%=maintable%>\',\r\n            field: \'<%=subfield%>\'\r\n        },\r\n        success: function(doc) {\r\n            loadTable();\r\n        }\r\n    });\r\n}\r\n\r\n\r\n</script>\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3><%=subtable_name%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n    <div class=\"row-fluid\">\r\n        <span class=\"span2\"></span>\r\n        <span class=\"span8\">\r\n            <div class=\"input-append\">\r\n                <input type=\"text\" class=\"span10\" id=\"nameSub\">\r\n                <span class=\"btn btn-success\" id=\"addSub\">Add</span>\r\n            </div>   \r\n            <table class=\"table table-striped\" id=\"tableList\">\r\n            <thead><th colspan=\"5\"><%=subtable_name%> list</th></thead>\r\n            </table>\r\n        </span>\r\n    </div><!--row-fluid-->\r\n    \r\n</div> <!--w-box-content -->\r\n</div> <!--w-box -->\r\n</div><!--span12 -->\r\n</div><!--row-fluid -->',NULL,NULL,NULL,'2019-03-21 04:35:51','2019-03-21 04:35:51','edit',''),(3991,'update_time_ms',1363,1,'300000',NULL,NULL,NULL,'2019-03-25 03:34:01','2019-03-25 03:34:01','update_time_ms',''),(3992,'get_appoint',1363,3,'<%\r\n\r\n\r\n    main = \'../Home/index?\'\r\n    date = Time.now\r\n    if params[:date]\r\n        date = Date.strptime(params[:date], \'%d/%m/%Y\') if params[:date]\r\n    end\r\n	\r\n	models = get_model\r\n	ap_model = models[:appointment]\r\n\r\n	\r\n	aps = ap_model.all(:date.gte=>date.at_beginning_of_day,:date.lt=>date.end_of_day) \r\n	for a in aps\r\n	    a.update_attributes :status=>\'Completed\' if a.status==\'\'\r\n	end\r\n	\r\n	aps.collect!{|i|\r\n	    c={:room=>i.room,:start=>i.start.strftime(\'%H:%M\'),:stop=>i.stop.strftime(\'%H:%M\')}\r\n	    c if i[:status]!=\'Cancelled\'\r\n	}.compact!\r\n	\r\n	%>\r\n	\r\n<%=aps.to_json.html_safe%>	',NULL,NULL,NULL,'2019-03-25 05:04:46','2019-03-25 05:04:46','get_appoint',''),(3993,'edit',1572,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3>Edit <%=this.table_name.to_s.humanize%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\"><%\r\n  model = get_model(this.table_name)\r\n  record = model.find(params[:id])\r\n  if request.post?\r\n    doc = get_document this.document_name\r\n    record = doc.record_update(model,params,record)\r\n    flash[:notice]=\'New record has been created\'\r\n%>\r\n<script type=\"text/javascript\">\r\n<!--\r\nwindow.location = \"show?id=<%=record.id%>\"\r\n//-->\r\n</script>\r\n<%\r\n  else\r\n  \r\n%>\r\n\r\n<%= form_for :record,:url=>url(\'edit\',:id=>record.id) do |f| %>\r\n<%\r\n    params[:form] = {:form=>f,:model=>model,:record=>record}\r\n%>\r\n<p>\r\n<%= this.form.html_safe %>\r\n</p>\r\n<br/>\r\n<button class=\'btn btn-small\'><i class=\"splashy-pencil\"></i> Update</button> |\r\n<%= link_to \'Back\', url(\'index\') %>\r\n<% end %>\r\n\r\n<% end %>\r\n<!-- Modify edit -->\r\n</div><!--document-border -->\r\n</div><!--border -->\r\n</div><!--w-box-content -->\r\n</div><!--w-box -->\r\n<% \r\n    subtable_name = \'Process\' \r\n    maintable = \'lesson\'\r\n    subtable = \'process\'\r\n    subfield = \'processes\'\r\n%>\r\n<script>\r\n$(document).ready(function(){\r\n    $(\"#<%=subfield%>\").remove();\r\n    $(\"#addSub\").click(function(){\r\n       addSub();\r\n    });\r\n    loadTable();\r\n});\r\n\r\n$.urlParam = function(name){\r\n	var results = new RegExp(\'[\