[params[:field]]\r\n            u = []\r\n            u = c[params[:field]] if c[params[:field]]\r\n            if params[:id]\r\n                i=u.index(BSON::ObjectId.from_string(params[:id])) \r\n                u.insert(i-1,u.delete_at(i)) if o==\'up\' and i>0\r\n                u.insert(i+1,u.delete_at(i)) if o==\'down\' and i<u.size-1\r\n            end\r\n             %><%=u.inspect%><br><%\r\n            c[params[:field]]=u\r\n            c.save\r\n        end\r\n    end\r\n%>',NULL,NULL,NULL,'2019-03-26 04:56:25','2019-03-26 04:56:25','order_sub',''),(3997,'del_sub',1570,3,'<%\r\n    if params[:cid] and params[:main] and params[:field]\r\n        m = get_model(params[:main]).find(params[:cid]) if params[:main]!=\'\'\r\n        if m and m[params[:field]]\r\n            u = []\r\n            u = m[params[:field]] if m[params[:field]]\r\n            u.delete(BSON::ObjectId.from_string(params[:id]))if params[:id]\r\n            m[params[:field]]=u\r\n            m.save\r\n            %><%=m[params[:field]].to_s%><br><%\r\n        end\r\n    end\r\n%>',NULL,NULL,NULL,'2019-03-26 05:15:53','2019-03-26 05:15:53','del_sub',''),(3998,'partial_sub',1570,3,'<script>\r\n$(document).ready(function(){\r\n    $(\"#<%=subfield%>\").remove();\r\n    $(\"#addSub\").click(function(){\r\n       addSub();\r\n    });\r\n    loadTable();\r\n});\r\n\r\n$.urlParam = function(name){\r\n	var results = new RegExp(\'[\\?&]\' + name + \'=([^&#]*)\').exec(window.location.href);\r\n	return results[1] || 0;\r\n}\r\n\r\nfunction loadTable(){\r\n    var row=\"\";\r\n    id = $.urlParam(\'id\');\r\n    // alert(id);\r\n    row+=\'<thead><th colspan=\"5\"><%=subtable_name%> list</th></thead>\';\r\n    $.ajax({\r\n        dataType: \"json\",\r\n        url: \'../Home/get_sub\',\r\n        data: {\r\n            id: id,\r\n                main : \'<%=maintable%>\',\r\n                sub: \'<%=subtable%>\',\r\n                field: \'<%=subfield%>\'\r\n        },\r\n        success: function(