%>\',\r\n                field: \'<%=subfield%>\'\r\n        },\r\n        success: function(doc) {\r\n            // alert(doc);\r\n            $.each(doc,function(i,d){\r\n                row+=\'<tr><td width=\"80%\">\'+d.name+\'</td>\';\r\n                row+=\'<td><span class=\"btn editS\" sid=\"\'+d.id+\'\">edit</span></td>\';\r\n                row+=\'<td><span class=\"btn upS\" sid=\"\'+d.id+\'\"><i class=\"icon-arrow-up\"></i></span></td>\';\r\n                row+=\'<td><span class=\"btn downS\" sid=\"\'+d.id+\'\"><i class=\"icon-arrow-down\"></i></span></td>\';\r\n                row+=\'<td><span class=\"btn delS\" sid=\"\'+d.id+\'\"><i class=\"icon-trash\"></i></span></td></tr>\';\r\n            });\r\n            $(\"#tableList\").empty().append(row);  \r\n            $(\".editS\").click(function(){\r\n                document.location.href=\"../<%=subtable_name%>/edit?id=\"+$(this).attr(\"sid\")+\"&return=\"+document.location.href;\r\n            });\r\n            $(\".delS\").click(function(){delSub($(this).attr(\"sid\"))});\r\n            $(\".upS\").click(function(){orderSub($(this).attr(\"sid\"),\'up\')});\r\n            $(\".downS\").click(function(){orderSub($(this).attr(\"sid\"),\'down\')});\r\n\r\n        }\r\n    });\r\n}\r\n\r\nfunction addSub(){\r\n    mainid = $.urlParam(\'id\');\r\n    name = $(\"#nameSub\").val();\r\n    if(!$(\"#addSub\").attr(\"disabled\")&&name!=\'\'){\r\n        $(\"#addSub\").attr(\"disabled\", true);\r\n        $(\"#nameSub\").val(\'\');\r\n        // alert(id);\r\n        path = \'../Home/add_sub\';\r\n        $.ajax({\r\n            dataType: \"text\",\r\n            url: path,\r\n            data: {\r\n                id: mainid,\r\n                name : name,\r\n                main : \'<%=maintable%>\',\r\n                sub: \'<%=subtable%>\',\r\n                field: \'<%=subfield%>\'\r\n            },\r\n            success: function(doc) {\r\n                //  alert(doc);\r\n                loadTable();\r\n                $(\"#addSub\").removeAttr(\"disabled\");\r\n            }\r\n        });\r\n    }\r\n}\r\n\r\nfunction delSub(id){\r\n    mainid = $.urlParam(\'id\');\r\n    path = \'../Home/del_sub\';\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: path,\r\n        data: {\r\n            id: id,\r\n            cid: mainid,\r\n            main : \'<%=maintable%>\',\r\n            field: \'<%=subfield%>\'            \r\n        },\r\n        success: function(doc) {\r\n            loadTable();\r\n        }\r\n    });\r\n}\r\n\r\nfunction orderSub(id,order){\r\n    mainid = $.urlParam(\'id\');\r\n    path = \'../Home/order_sub\';\r\n    $.ajax({\r\n        dataType: \"text\",\r\n        url: path,\r\n        data: {\r\n            id: id,\r\n            cid: mainid,\r\n            order: order,\r\n            main : \'<%=maintable%>\',\r\n            field: \'<%=subfield%>\'\r\n        },\r\n        success: function(doc) {\r\n            loadTable();\r\n        }\r\n    });\r\n}\r\n\r\n\r\n</script>\r\n<div class=\"w-box\">\r\n<div class=\"w-box-header\">\r\n<h3><%=subtable_name%></h3>\r\n</div>\r\n\r\n<div class=\"w-box-content cnt_a\">\r\n    <div class=\"row-fluid\">\r\n        <span class=\"span2\"></span>\r\n        <span class=\"span8\">\r\n            <div class=\"input-append\">\r\n                <input type=\"text\" class=\"span10\" id=\"nameSub\">\r\n                <span class=\"btn btn-success\" id=\"addSub\">Add</span>\r\n            </div>   \r\n            <table class=\"table table-striped\" id=\"tableList\">\r\n            <thead><th colspan=\"5\"><%=subtable_name%> list</th></thead>\r\n            </table>\r\n        </span>\r\n    </div><!--row-fluid-->\r\n    \r\n</div> <!--w-box-content -->\r\n</div> <!--w-box -->\r\n</div><!--span12 -->\r\n</div><!--row-fluid -->',NULL,NULL,NULL,'2019-03-26 06:28:05','2019-03-26 06:28:05','edit',''),(4001,'edit',1575,2,'<div class=\"row-fluid\">\r\n<div class=\"span12\">\r\n\r\n<div class=\