ba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: -o-linear-gradient(left, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: -ms-linear-gradient(left, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: linear-gradient(to right, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#b5dba2\', endColorstr=\'#52ac52\', GradientType=1 );\r\n}\r\n.warndate{\r\n    font-weight:bold;\r\n    color:red;\r\n}\r\n</style>\r\n<div class=\"row-fluid\">\r\n<div class=\"span1\">&nbsp;</div>\r\n<div class=\"span10\">\r\n    <div class=\"hero-unit courseHeader\">\r\n      <h1>CRRT Basic 2019</h1>\r\n      <p class=\"text-warning\">\r\n          โครงการฝึกอบรมและพัฒนาทักษะการบำบัดทดแทนไตในภาวะวิกฤตขั้นพื้นฐาน\r\n      </p>\r\n      <p>\r\n        <a class=\"btn btn-warning btn-large\">\r\n          Start Learn\r\n        </a>\r\n      </p>\r\n      <p style=\"text-align:bottom\">\r\n      <i class=\"icon-time icon-white\"></i> 4 hours \r\n      | <i class=\"icon-play icon-white\"></i> 6 Videos \r\n      | <i class=\"icon-list icon-white\"></i> 20 Exercises\r\n      </p>\r\n    </div><!-- hero-unit -->\r\n    \r\n    <div class=\"hero-unit\">\r\n        <div class=\"row-fluid\">\r\n            <div class=\"span8\"><h3><span class=\"circleBase type1\">1</span> แบบประเมินก่อนเริ่มเรียน\r\n            </h3></div>\r\n            <div class=\"span4\">\r\n                <div class=\"progress progress-success\">\r\n                  <div class=\"bar\" style=\"width: 100%\">100%  </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        \r\n        <div class=\"process-item process-done\">\r\n            <span class=\"circleBase type2\"><i class=\"icon-list icon-white\" ></i></span> แบบประเมิน   \r\n            <span class=\"circleBase type3\"><i class=\"icon-ok icon-white\" ></i></span>\r\n        </div>\r\n        \r\n        <div class=\"row-fluid\">\r\n            <div class=\"span8\">Start : 20/03/2019 13:00 </div>\r\n            <div class=\"span4\">Finish : 20/03/2019 13:00 </div>\r\n        </div>      \r\n    </div><!-- hero-unit -->\r\n    \r\n    <div class=\"hero-unit\">\r\n        <div class=\"row-fluid\">\r\n            <div class=\"span8\"><h3><span class=\"circleBase type1\">2</span> ชมวีดิทัศน์\r\n            </h3></div>\r\n            <div class=\"span4\">\r\n                <div class=\"progress progress-warning\">\r\n                  <div class=\"bar\" style=\"width: 50%\">50%  </div>\r\n                </div>\r\n            </div>\r\n        </div>      \r\n      \r\n        <div class=\"process-item process-done\">\r\n            <span class=\"circleBase type2\"><i class=\"icon-play icon-white\" ></i></span> EP1 CRRT Prismaflex  \r\n            <span class=\"circleBase type3\"><i class=\"icon-ok icon-white\" ></i></span>\r\n        </div>  \r\n        <div class=\"process-item process-ready\"><span class=\"circleBase type2\"><i class=\"icon-play icon-white\" ></i></span> EP2 CRRT Aquarius    </div>\r\n        \r\n        <div class=\"row-fluid\">\r\n            <div class=\"span4\">Start : 20/03/2019 13:00 </div>\r\n            <div class=\"span4\">Finish : - </div>\r\n            <div class=\"span4 warndate\">Limit : 20/04/2019 23:59 </div>\r\n        </div>        \r\n    </div><!-- hero-unit -->\r\n    \r\n    <div class=\"hero-unit\">\r\n        <div class=\"row-fluid\">\r\n            <div class=\"span8\"><h3><span class=\"circleBase type1\">3</span> แบบประเมินหลังเรียน\r\n            </h3></div>\r\n            <div class=\"span4\">\r\n                <div class=\"progress progress-warning\">\r\n                  <div class=\"bar\" style=\"width: 0%\">0%  </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        \r\n        <div class=\"process-item process-ready\"><span class=\"circleBase type2\"><i class=\"icon-list icon-white\" ></i></span> แบบประเมิน    </div>\r\n        \r\n        <div class=\"row-fluid\">\r\n            <div class=\"span8\">Start : - </div>\r\n            <div class=\"span4\">Finish : - </div>\r\n        </div>      \r\n    </div><!-- hero-unit -->\r\n\r\n</div><!--span10-->\r\n</div><!--container-fluid-->',NULL,NULL,NULL,'2019-03-26 07:13:08','2019-03-26 07:13:08','main_template',''),(4003,'document_name',1579,1,'\'tracking\'',NULL,NULL,NULL,'2019-03-27 03:34:05','2019-03-27 03:34:05',NULL,NULL),(4004,'next',1570,3,'<%\r\n    models = get_model\r\n    location = \'./main\'\r\n    #init\r\n    member = models[:member].find( session[:member_id]) \r\n    member_id = member.id \r\n\r\n    course = {}\r\n    if params[:cid] and params[:cid]!=\'\'\r\n        course = models[:course].find(BSON::ObjectId.from_string(params[:cid]))\r\n    else\r\n        course = models[:course].all.first\r\n    end\r\n\r\n    \r\n    t = models[:tracking].where(:member_id=>member_id,:course_id=>course.id).all\r\n    if t.size==0 # new entry \r\n        models[:tracking].create :member_id=>member_id,:course_id=>course.id,:link_id=>course.id,:type=>\'course\',:status=>\'started\',:progress=>0\r\n        if course.lessons\r\n            l = models[:lesson].find(course.lessons[0])\r\n            models[:tracking].create :member_id=>member_id,:course_id=>course.id,:link_id=>l.id,:parent_id=>course.id,:type=>\'lesson\',:status=>\'started\',:progress=>0\r\n            if l.processes\r\n                p = models[:process].find(l.processes[0])\r\n                models[:tracking].create :member_id=>member_id,:course_id=>course.id,:link_id=>p.id,:parent_id=>l.id,:type=>\'process\',:status=>\'started\',:progress=>0\r\n                location = \'./\'+p.type.downcase+\'?id=\'+p.id.to_s+\'&lid=\'+l.id.to_s+\'&cid=\'+course.id.to_s\r\n            end\r\n        end\r\n    else # alredy start\r\n        pdone =[]\r\n        if params[:pid] and params[:pid]!=\'\'\r\n            pdone = t.collect{|i| i if i.type==\'process\' and i.link_id==BSON::ObjectId.from_string(params[:pid]) and i.status!=\'finished\'}.compact\r\n        # else\r\n        #     pdone = t.collect{|i| i if i.type==\'process\' and i.status!=\'finished\'}.compact\r\n        end\r\n        if pdone.size>0\r\n            #update process\r\n            pdone[0][:status]=\'finished\'\r\n            pdone[0][:finished_date]=Time.now\r\n            pdone[0][:progress]=100\r\n            pdone[0].save\r\n            l = models[:lesson].find(pdone[0][:parent_id])\r\n            if l.processes \r\n                allpdone = t.collect{|i| i if i.type==\'process\' and i.status==\'finished\' and l.processes.include?(i.link_id)}.compact\r\n                pg = 0\r\n                pg = (allpdone.size*100)/l.processes.size if l.processes.size>0\r\n\r\n                lupdate = t.collect{|i| i if i.link_id==l.id}.compact \r\n                #update lesson\r\n                lupdate[0][:progress] = pg \r\n                if pg==100\r\n                    lupdate[0][:status] = \'finished\' \r\n                    lupdate[0][:finished_date] = Time.now \r\n                    all_tlp = t.collect{|i| i if i.parent_id==l.id}.compact \r\n                    # all_tlp = models[:tracking].where(:member_id=>member_id,:course_id=>course.id,:parent_id=>l.id).all\r\n                    sc = 0\r\n                    for tlp in all_tlp\r\n                        sc += tlp.score if tlp.score\r\n                    end\r\n                    # lupdate[0][:score] = sc\r\n                end\r\n                lupdate[0].save\r\n                if pg<100 #next process\r\n                    index = l.processes.index(pdone[0][:link_id])\r\n                    p = models[:process].find(l.processes[index+1])\r\n                    models[:tracking].create :member_id=>member_id,:course_id=>course.id,:link_id=>p.id,:parent_id=>l.id,:type=>\'process\',:status=>\'started\',:progress=>0\r\n                    location = \'./\'+p.type.downcase+\'?id=\'+p.id.to_s+\'&lid=\'+l.id.to_s+\'&cid=\'+course.id.to_s\r\n\r\n                \r\n                else #next lesson\r\n                    c = models[:course].find(lupdate[0].parent_id)\r\n                    if c.lessons\r\n                        index = c.lessons.index(l.id)\r\n                        if index < c.lessons.size-1\r\n                            l = models[:lesson].find(c.lessons[index+1])\r\n                            tl = models[:tracking].create :member_id=>member_id,:course_id=>course.id,:link_id=>l.id,:parent_id=>c.id,:type=>\'lesson\',:status=>\'started\',:progress=>0\r\n                            if l.limit_num and l.limit_num>0\r\n                                tl[:limit_date] = Time.now+l.limit_num.day\r\n                                tl.save\r\n                            end\r\n                            if l.processes\r\n                                p = models[:process].find(l.processes[0])\r\n                                models[:tracking].create :member_id=>member_id,:course_id=>course.id,:link_id=>p.id,:parent_id=>l.id,:type=>\'process\',:status=>\'started\',:progress=>0\r\n                                location = \'./\'+p.type.downcase+\'?id=\'+p.id.to_s+\'&lid=\'+l.id.to_s+\'&cid=\'+course.id.to_s\r\n                            end\r\n                        else #end course\r\n                            cupdate = t.collect{|i| i if i.link_id==c.id}.compact \r\n                            cupdate[0][:progress] = 100 \r\n                            cupdate[0][:status] = \'finished\' \r\n                            cupdate[0][:finished_date] = Time.now \r\n                            cupdate[0].save\r\n                            location = \'./main\'\r\n                        end\r\n                    end\r\n                end #if pg<100\r\n                \r\n            end\r\n        else #now process already finished\r\n            tp =[]\r\n            tp = t.collect{|i| i if i.type==\'process\' and i.link_id==BSON::ObjectId.from_string(params[:pid])}.compact if params[:pid]\r\n            if tp.size>0\r\n                l = models[:lesson].find(tp[0].parent_id)\r\n                if l.processes\r\n                    index = l.processes.index(tp[0].link_id)\r\n                    if index < l.processes.size-1\r\n                        p = models[:process].find(l.processes[index+1])\r\n                        location = \'./\'+p.type.downcase+\'?id=\'+p.id.to_s+\'&lid=\'+l.id.to_s+\'&cid=\'+course.id.to_s\r\n                    else #next lesson\r\n                        tl = t.collect{|i| i if i.type==\'lesson\' and i.link_id==l.id}.compact\r\n                        c = models[:course].find(tl[0].parent_id)\r\n                        if c.lessons\r\n                            index = c.lessons.index(l.id)\r\n                            if index < c.lessons.size-1\r\n                                nl = models[:lesson].find(c.lessons[index+1])\r\n                                if nl.processes\r\n                                    p = models[:process].find(nl.processes[0])\r\n                                    location = \'./\'+p.type.downcase+\'?id=\'+p.id.to_s+\'&lid=\'+nl.id.to_s+\'&cid=\'+course.id.to_s\r\n                                end\r\n                            else\r\n                                location=\'./main\'\r\n                            end\r\n                        end\r\n                    end\r\n                end\r\n            end #tp.size>0\r\n        end #if pdone.size>0\r\n    end\r\n%>\r\n<%=location.html_safe%>',NULL,NULL,NULL,'2019-03-27 07:19:22','2019-03-27 07:19:22','next','*'),(4006,'continue',1570,3,'<%\r\n    models = get_model\r\n    location = \'\'\r\n    #init\r\n    member = models[:member].find( session[:member_id]) \r\n    member_id = member.id \r\n\r\n    course = {}\r\n    if params[:cid] and params[:cid]!=\'\'\r\n        course = models[:course].find(BSON::ObjectId.from_string(params[:cid]))\r\n    else\r\n        course = models[:course].all.first\r\n    end\r\n    \r\n    t = models[:tracking].where(:member_id=>member_id,:course_id=>course.id).all\r\n    if t.size==0 # new entry \r\n        models[:tracking].create :member_id=>member_id,:course_id=>course.id,:link_id=>course.id,:type=>\'course\',:status=>\'started\',:progress=>0\r\n        if course.lessons\r\n            l = models[:lesson].find(course.lessons[0])\r\n            models[:tracking].create :member_id=>member_id,:course_id=>course.id,:link_id=>l.id,:parent_id=>course.id,:type=>\'lesson\',:status=>\'started\',:progress=>0\r\n            if l.processes\r\n                p = models[:process].find(l.processes[0])\r\n                models[:tracking].create :member_id=>member_id,:course_id=>course.id,:link_id=>p.id,:parent_id=>l.id,:type=>\'process\',:status=>\'started\',:progress=>0\r\n                location = \'./\'+p.type.downcase+\'?id=\'+p.id.to_s+\'&lid=\'+l.id.to_s+\'&cid=\'+course.id.to_s\r\n            end\r\n        end\r\n    else # alredy start\r\n        tp = t.collect{|i| i if i.type==\'process\' and i.status!=\'finished\'}.compact\r\n        if tp.size>0\r\n            p = models[:process].find(tp[0].link_id)\r\n            location = \'./\'+p.type.downcase+\'?id=\'+tp[0].link_id.to_s+\'&lid=\'+tp[0].parent_id.to_s+\'&cid=\'+course.id.to_s\r\n        else\r\n            location=\'./main\'\r\n        end\r\n    end #if t.size==0\r\n%>\r\n<%=location.html_safe%>',NULL,NULL,NULL,'2019-03-28 05:17:23','2019-03-28 05:17:23','continue','*'),(4007,'back',1570,3,'<%\r\n    models = get_model\r\n    location = \'./main\'\r\n    #init\r\n    member = models[:member].find( session[:member_id]) \r\n    member_id = member.id \r\n\r\n    course = {}\r\n    if params[:cid] and params[:cid]!=\'\'\r\n        course = models[:course].find(BSON::ObjectId.from_string(params[:cid]))\r\n    else\r\n        course = models[:course].all.first\r\n    end\r\n    \r\n    t = models[:tracking].where(:member_id=>member_id,:course_id=>course.id).all\r\n\r\n    tp =[]\r\n    tp = t.collect{|i| i if i.type==\'process\' and i.link_id==BSON::ObjectId.from_string(params[:pid])}.compact if params[:pid]\r\n    if tp.size>0\r\n        l = models[:lesson].find(tp[0].parent_id)\r\n        if l.processes\r\n            index = l.processes.index(tp[0].link_id)\r\n            if index > 0\r\n                p = models[:process].find(l.processes[index-1])\r\n                location = \'./\'+p.type.downcase+\'?id=\'+p.id.to_s+\'&lid=\'+l.id.to_s+\'&cid=\'+course.id.to_s\r\n            else #next lesson\r\n                tl = t.collect{|i| i if i.type==\'lesson\' and i.link_id==l.id}.compact\r\n                c = models[:course].find(tl[0].parent_id)\r\n                location=\'./main\' \r\n                if false #c.lessons\r\n                    index = c.lessons.index(l.id)\r\n                    if index > 0\r\n                        nl = models[:lesson].find(c.lessons[index-1])\r\n                        if nl.processes\r\n                            p = models[:process].find(nl.processes[-1])\r\n                            location = \'./\'+p.type.downcase+\'?id=\'+p.id.to_s+\'&lid=\'+nl.id.to_s+\'&cid=\'+course.id.to_s\r\n                        end\r\n                    else\r\n                        location=\'./main\'\r\n                    end\r\n                end\r\n            end\r\n        end\r\n    end #tp.size>0\r\n%>\r\n<%=location.html_safe%>',NULL,NULL,NULL,'2019-03-28 05:27:38','2019-03-28 05:27:38','back','*'),(4008,'authen',1570,3,'<style>\r\n.lds-ring {\r\n  display: inline-block;\r\n  position: relative;\r\n  width: 64px;\r\n  height: 64px;\r\n}\r\n.lds-ring div {\r\n  box-sizing: border-box;\r\n  display: block;\r\n  position: absolute;\r\n  width: 51px;\r\n  height: 51px;\r\n  margin: 6px;\r\n  border: 6px solid #cef;\r\n  border-radius: 50%;\r\n  animation: lds-ring 1.2s cubic-bezier(0.5, 0, 0.5, 1) infinite;\r\n  border-color: #cef transparent transparent transparent;\r\n}\r\n.lds-ring div:nth-child(1) {\r\n  animation-delay: -0.45s;\r\n}\r\n.lds-ring div:nth-child(2) {\r\n  animation-delay: -0.3s;\r\n}\r\n.lds-ring div:nth-child(3) {\r\n  animation-delay: -0.15s;\r\n}\r\n@keyframes lds-ring {\r\n  0% {\r\n    transform: rotate(0deg);\r\n  }\r\n  100% {\r\n    transform: rotate(360deg);\r\n  }\r\n}\r\n\r\n</style>\r\n<center><div class=\"lds-ring\"><div></div><div></div><div></div><div></div></div></center>\r\n<%\r\n    session.delete :member_id  \r\n    if params[:email] and params[:email]!=\'\'\r\n        \r\n        member = get_model(\'member\').where(:email=> /\\\\#{params[:email]}/i ).first\r\n        if member \r\n            session[:member_id] = member.id\r\n            \r\n%>\r\n    <META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=main\">\r\n    <% else %>\r\n    <META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=index\">\r\n    <% end %>\r\n<% else %>\r\n<META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=index\">\r\n<% end %>\r\n',NULL,NULL,NULL,'2019-03-29 03:29:54','2019-03-29 03:29:54','authen','*'),(4009,'logout',1570,3,'<META HTTP-EQUIV=\"Refresh\" CONTENT=\"0;URL=index\">\r\n<%\r\n    session.delete :member_id\r\n%>\r\n\r\n\r\n\r\n',NULL,NULL,NULL,'2019-03-29 03:36:54','2019-03-29 03:36:54','logout','*'),(4010,'document_name',1580,1,'\'examlog\'',NULL,NULL,NULL,'2019-04-02 03:36:22','2019-04-02 03:36:22',NULL,NULL),(4011,'update',1580,3,'<%\r\n    model = get_model(this.table_name)\r\n    location=\'./main\'\r\n    if params[:id]\r\n        record = model.find(params[:id])\r\n        if params[:aid] and params[:aid]!=\'\'\r\n            record[:answer_id] = BSON::ObjectId.from_string(params[:aid]) \r\n            record[:score] = get_model(\'answer\').find(BSON::ObjectId.from_string(params[:aid])).score\r\n            record[:text] = params[:text] if params[:text] and params[:text]!=\'\'\r\n            record[:status] = \'finished\'\r\n            record[:finished_date] = Time.now\r\n            record.save\r\n        end\r\n        \r\n        n = \'\'\r\n        n = params[:nextid] if params[:nextid]\r\n        if n!=\'\'\r\n            models = get_model\r\n            if n!=\'next\'\r\n                els = models[:examlog].where(:track_id=>record[:track_id],:question_id=>BSON::ObjectId.from_string(n)).all\r\n                models[:examlog].create :track_id=>record[:track_id],:question_id=>BSON::ObjectId.from_string(n),:status=>\'started\' if els.size==0\r\n                t = models[:tracking].find(record[:track_id])\r\n                location=\'exam?id=\'+t.link_id+\'&lid=\'+t.parent_id+\'&cid=\'+t.course_id+\'&qid=\'+n if t\r\n            else\r\n                els = models[:examlog].where(:track_id=>record[:track_id]).all\r\n                sc = 0\r\n                for el in els\r\n                    sc+= el.score if el.score\r\n                end\r\n                t = models[:tracking].find(record[:track_id])\r\n                t[:score] = sc\r\n                t.save\r\n                \r\n                tl = models[:tracking].where(:member_id=>t.member_id,:course_id=>t.course_id,:link_id=>t.parent_id).first\r\n                tl[:score] = sc\r\n                tl.save\r\n            end\r\n        end\r\n    end\r\n%>\r\n<%=location.html_safe%>',NULL,NULL,NULL,'2019-04-02 05:57:22','2019-04-02 05:57:22','update','*'),(4012,'admin',1570,2,'<style>\r\n.courseHeader{\r\nbackground: rgba(73,155,234,1);\r\nbackground: -moz-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -webkit-gradient(left top, right top, color-stop(0%, rgba(73,155,234,1)), color-stop(100%, rgba(0,4,40,1)));\r\nbackground: -webkit-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -o-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: -ms-linear-gradient(left, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nbackground: linear-gradient(to right, rgba(73,155,234,1) 0%, rgba(0,4,40,1) 100%);\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#499bea\', endColorstr=\'#000428\', GradientType=1 );\r\ncolor:white;\r\n}\r\n.circleBase {\r\n    border-radius: 50%;\r\n    behavior: url(PIE.htc); /* remove if you don\'t care about IE8 */\r\n}\r\n\r\n.type1 {\r\n    padding:10 20 10 20;\r\n    font-weight:bold;\r\n    color:white;\r\n    width: 100px;\r\n    height: 100px;\r\n    background: #499bea;\r\n}\r\n.type2{\r\n    padding:5;\r\n    font-weight:bold;\r\n    color:white;\r\n    width: 100px;\r\n    height: 100px;\r\n    background: #499bea;\r\n}\r\n.type3{\r\n    padding:5;\r\n    background: #52AC52	;\r\n    float:right;\r\n    border:solid 2px white;\r\n}\r\n.process-item{\r\n    -webkit-border-radius: 5px;\r\n    -moz-border-radius: 5px;\r\n    border-radius: 5px;\r\n    padding:10px;\r\n    margin:5px;\r\n}\r\n.process-ready{\r\n    background: #dbdbdb;\r\n}\r\n.process-ready:hover{\r\n    background: #b6d7f5;\r\n    font-size:1.2em;\r\n}\r\n.process-done{\r\n    background: #b6d7f5;\r\n}\r\n.process-done2{\r\nbackground: rgba(181,219,162,1);\r\nbackground: -moz-linear-gradient(left, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: -webkit-gradient(left top, right top, color-stop(0%, rgba(181,219,162,1)), color-stop(100%, rgba(82,172,82,1)));\r\nbackground: -webkit-linear-gradient(left, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: -o-linear-gradient(left, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: -ms-linear-gradient(left, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nbackground: linear-gradient(to right, rgba(181,219,162,1) 0%, rgba(82,172,82,1) 100%);\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#b5dba2\', endColorstr=\'#52ac52\', GradientType=1 );\r\n}\r\n.warndate{\r\n    font-weight:bold;\r\n    color:red;\r\n}\r\n.btn-course{\r\n    font-size:2em;\r\n    padding:30px;\r\n}\r\n.btn-module{\r\n    width:120px;\r\n    height:80px;\r\n    margin:5px;\r\n}\r\n</style>\r\n<%\r\n    models = get_model\r\n    courses = models[:course].all\r\n    lessons = models[:lesson].all\r\n    members = models[:member].all.sort{|a,b| a.fullname<=>b.fullname}\r\n    hls = Hash[lessons.collect{|i| [i.id,i]}]\r\n\r\n    trackings = models[:tracking].where(:type=>\'lesson\').all.compact\r\n    \r\n    table_model = %w{fullname email tel}.collect{|i| i.to_sym}\r\n\r\n    labels = {:fullname=>\'Name\',:email=>\'Email\',:tel=>\'Tel\' }\r\n%>\r\n<div class=\"row-fluid\">\r\n<div class=\"span1\">&nbsp;</div>\r\n<div class=\"span10\">\r\n<%\r\n    for c in courses\r\n        # ls = lessons.collect{|i| i if c.lessons.include?(i.id)}.compact\r\n        ls = c.lessons.collect{|i| hls[i]}\r\n        tcs = trackings.collect{|i| i if i.course_id==c.id}.compact\r\n        lm = {}\r\n        for m in members\r\n            l_no = 0\r\n            mtcs = tcs.collect{|i| i if i.member_id==m.id}.compact\r\n            lm[l_no] = [] if !lm[l_no]\r\n            lm[l_no] << m if mtcs and mtcs.size==0\r\n            if mtcs.size>0\r\n                for l in ls\r\n                    l_no += 1\r\n                    mtls = mtcs.collect{|i| i if i.link_id==l.id and !i.finished_date}.compact\r\n                    lm[l_no] = [] if !lm[l_no]\r\n                    lm[l_no] << m if mtls.size>0\r\n                    %><%#=mtls.inspect if mtls.size>0%><%\r\n                end\r\n                l_no += 1\r\n                mtlfs = mtcs.collect{|i| i if !i.finished_date}.compact\r\n                lm[l_no] = [] if !lm[l_no]\r\n                lm[l_no] << m if mtlfs.size==0\r\n            end #if mtcs.size>0\r\n        end #for m\r\n        \r\n%>\r\n    <div class=\"hero-unit courseHeader\">\r\n      <h1><%=c.name%></h1>\r\n      <center>\r\n        <a href=\"#\" target=\"_blank\"><button class=\"btn btn-module\">\r\n         <i class=\"splashy-application_windows_share\"></i>\r\n          <br />Analysis\r\n        </button></a> \r\n        <a href=\"../Member/index\" target=\"_blank\"><butt