nk_to \'Create Outcome\',\"../Outcome/create?patient_id=\\\\#{pm.patient_id}&record_name=\\\\#{patient.hn}&parent_id=\\\\#{pm.parent_id}&return=\\\\#{return_url}\" ,:class=>bt_class %> \r\n| <%= link_to \'Back\', return_url %>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>',NULL,NULL,NULL,'2019-04-08 23:02:25','2019-04-08 23:02:25','show',''),(4022,'display',1517,3,'<% return_url=\'\' %>\r\n\r\n<div style=\"border:0px solid\">\r\n<div class=\"document-border\" style=\"border:0px solid\">\r\n\r\n<%= render :inline=>this.init, :locals=>{:this=>this} %>\r\n\r\n<%\r\n  model = get_model(this.table_name)\r\n  @patient_module = @module_model.find(params[:id])\r\n  record = model.find(@patient_module.module_id)\r\n  @show=true\r\n%>\r\n<p>\r\n<%\r\n   @project =  context[:project]\r\n   @document =  get_document(this.document_name)\r\n   @record = record\r\n   params[:patient]=@patient \r\n%>\r\n<style>\r\n    .refinfo {padding:5px;width:720px; margin-left:auto; margin-right:auto}\r\n</style>\r\n <div class=\"refinfo\" >\r\n\r\nRef : <%= @patient_module.ref_number[0..9] if @patient_module.ref_number %> \r\n\r\n<span style=\"float:right\">\r\nDate : <%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\r\nTime : <%= @patient_module.time.strftime(\"%H:%M\") if @patient_module.time %>\r\n</span>\r\n</div>\r\n<!-- show patient -->\r\n<div id=\'patient\'>\r\n<p style=\"width:720px; margin-left:auto; margin-right:auto; font-weight:bold\">HN : <%= @patient.hn %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Name : <%= @patient.first_name %>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Surname : <%= @patient.last_name %></p>\r\n<hr /><br />\r\n</div>\r\n<script>\r\nurl = \'../../<%= @ehr_project.name %>/Patient/search_result?\';\r\nurl += \'&id=<%=@patient_module.patient_id%>\'\r\n $.ajax({\r\n url: url,\r\nsuccess: function(data){\r\n $(\'#patient\').html(data);  \r\n }\r\n});\r\n</script>\r\n\r\n<%= render :partial=>\'/esm_documents/show_layout.html\' %>\r\n</p>\r\n\r\n</div>\r\n</div>\r\n<script>\r\n     $(\"#record-time\").kendoTimePicker({\r\n    value: \'<%= @patient_module.time.strftime(\"%H:%M\")  if @patient_module.time %>\',\r\n    interval: 10\r\n    });\r\n    $(\"#record-date\").kendoDatePicker({\r\n       value: \'<%= @patient_module.date.strftime(\"%d/%m/%Y\") if @patient_module.date %>\',\r\n    });\r\n</script>',NULL,NULL,NULL,'2019-04-08 23:37:03','2019-04-08 23:37:03','display',''),(4023,'get_score',1579,3,'<%\r\n\r\n    ss = []\r\n    s = {}\r\n    if params[:cid] and params[:pid]\r\n        #init\r\n        models = get_model\r\n        member = models[:member].find( session[:member_id]) \r\n        member_id = member.id \r\n        c = models[:course].find(BSON::ObjectId.from_string(params[:cid]))\r\n        ts = models[:tracking].where(:member_id=>member_id,:course_id=>BSON::ObjectId.from_string(params[:cid])).all\r\n        tp = ts.collect{|i| i if i.link_id==BSON::ObjectId.from_string(params[:pid])}.compact\r\n        isshow = false\r\n        \r\n        \r\n        %><%#=ts.inspect%><%\r\n        if  c and c.lessons\r\n            ls = models[:lesson].find(c.lessons)\r\n            if tp and tp.size>0\r\n                lp = ls.collect{|i| i if i.id==tp[0].parent_id}.compact\r\n                isshow = true if lp and lp.size>0 and lp[0].show_score and lp[0].show_score==\'true\'\r\n            end\r\n            if isshow\r\n                for l in ls\r\n                    s = {}\r\n                    if l.show_score and l.show_score==\'true\'\r\n                        tl = ts.collect{|i| i if i.type==\'lesson\' and i.link_id==l.id and i.finished_date}.compact\r\n                        if tl and tl.size>0\r\n                            per = 0\r\n                            s[:name]=l.name\r\n                            s[:score]=tl[0].score\r\n                            s[:full]=l.score\r\n                            per = (tl[0].score*100)/l.score if l.score and l.score>0\r\n                            s[:percent]=per\r\n                            if l.after\r\n                                ta = ts.collect{|i| i if i.link_id==l.after and i.finished_date}.compact\r\n                                ss << s if ta and ta.size>0\r\n                            else\r\n                                ss << s\r\n                            end\r\n                        end\r\n                    end\r\n                end\r\n            end\r\n        end\r\n\r\n    end    \r\n%>\r\n<%=ss.to_json.html_safe%>',NULL,NULL,NULL,'2019-04-10 07:43:10','2019-04-10 07:43:10','get_score','*'),(4024,'document_name',1581,1,'\'examlog_test\'',NULL,NULL,NULL,'2019-04-11 04:18:33','2019-04-11 04:18:33',NULL,NULL),(4026,'document_name',1582,1,'\'tracking_test\'',NULL,NULL,NULL,'2019-04-11 04:52:39','2019-04-11 04:52:39',NULL,NULL),(4027,'copy',1582,3,'<%\r\n    models = get_model\r\n    ts = models[:tracking].all\r\n    for t in ts\r\n        models[:tracking_test].create :member_id=>t.member_id,:course_id=>t.course_id,:type=>t.type,:status=>t.status,:progress=>t.progress,:score=>t.score,:finished_date=>t.finished_date,:limit_date=>t.limit_date,:link_id=>t.link_id,:parent_id=>t.parent_id	\r\n    end\r\n%>\r\ndone',NULL,NULL,NULL,'2019-04-11 04:57:24','2019-04-11 04:57:24','copy',''),(4028,'copy',1581,3,'<%\r\n    models = get_model\r\n    ts = models[:examlog].all\r\n    for t in ts\r\n        models[:examlog_test].create :track_id=>t.track_id,:question_id=>t.question_id,:answer_id=>t.answer_id,:status=>t.status,:finished_date=>t.finished_date,:score=>t.score,:text=>t.text	\r\n    end\r\n%>\r\ndone',NULL,NULL,NULL,'2019-04-11 05:10:06','2019-04-11 05:10:06','copy',''),(4029,'copy',1580,3,'',NULL,NULL,NULL,'2019-04-11 06:04:56','2019-04-11 06:04:56','copy',''),(4030,'help',1160,2,'<link href=\"https://fonts.googleapis.com/css?family=Prompt\" rel=\"stylesheet\">\r\n<style>\r\n.help_body{\r\nbackground: #0575E6;  /* fallback for old browsers */\r\nbackground: -webkit-linear-gra