(\\.[^<>()\\[\\]\\\\.,;:\\s@\"]+)*)|(\".+\"))@((\\[[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\])|(([a-zA-Z\\-0-9]+\\.)+[a-zA-Z]{2,}))$/;\r\n    return re.test(String(email).toLowerCase());\r\n\r\n    \r\n    \r\n}\r\n\r\nfunction emailIsValid (email) {\r\n  return /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)\r\n}\r\n\r\n\r\n                    jQuery(document).ready(function(){\r\n                        \r\n                        jQuery(\'#submit-btn\').click(function(event){\r\n                            \r\n                            name = jQuery(\'#data_name\').val()\r\n                            email = jQuery(\'#data_email\').val()\r\n                            personal_id = jQuery(\'#data_personal_id\').val()\r\n                            phone = jQuery(\'#data_phone\').val()\r\n                            \r\n                            go = true\r\n                            if(email==\"\"){\r\n                                alert(\"Email cannot be empty\")\r\n                                go = false;\r\n                            }\r\n                            if(go && emailIsValid(email)==false){\r\n                                alert(\"Email is wrong format\")\r\n                                go = false;\r\n                            }\r\n                            if(go &&phone==\"\"){\r\n                                alert(\"Phone cannot be empty\")\r\n                                go = false;\r\n                            }\r\n                            if(go &&name==\"\"){\r\n                                alert(\"Name cannot be empty\")\r\n                                go = false;\r\n                            }\r\n                                \r\n                            if(go == false)\r\n                                event.preventDefault();\r\n                           \r\n        \r\n                         })\r\n                        \r\n                    });\r\n                \r\n\r\n    </script>\r\n\r\n\r\n\r\n\r\n\r\n</body>\r\n\r\n\r\n</html>',NULL,NULL,NULL,'2019-05-06 06:46:56','2019-05-06 06:46:56','index','*'),(4066,'process',1601,2,'<% if request.post? \r\n\r\n   model = get_model(\'member\')\r\n   last_member = model.last\r\n   member_id = 1\r\n   member_id = last_member.member_id+1 if last_member and last_member.member_id\r\n   \r\n   msg = \"\"\r\n   \r\n   member = model.where(\'$or\'=>[{:phone=>params[:data][:phone]},{:phone=>params[:data][:email]},{:personal_id=>params[:data][:personal_id]}]).first\r\n   unless member\r\n   member = model.create params[:data]\r\n   member.update_attributes :member_id=>member_id\r\n%>\r\nกำลังดำเนินการ\r\n<meta http-equiv=\"refresh\" content=\"0;url=../Register/email?name=<%=member.name%>&to=<%=member.email%>&member_id=<%=member.member_id%>\" />\r\n<%\r\n   else\r\n       msg = \"คุณได้ลงทะเบียนด้วย email หรือ หมายเลขโทรศัพท์นี้แล้ว \"\r\n       member = model.new params[:data]\r\n%>\r\n<div class=\"alert alert-danger\"><%=msg%></div>\r\n\r\n<meta http-equiv=\"refresh\" content=\"2;url=../Register/index?name=<%=member.name%>&phone=<%=member.phone%>&email=<%=member.email%>&member_id=<%=member.member_id%>\" />\r\n<% end %><% end %>',NULL,NULL,NULL,'2019-05-06 07:11:16','2019-05-06 07:11:16','process','*');
