n_key=>\'visit_id\'\r\n    # one :order_item, :class=>Schema::OrderItem, :foreign_key=>\'formula_id\'\r\n    \r\n    \r\n    \r\ndef process models\r\n   count = 0\r\n   \r\n   out = {}\r\n   \r\n   out[:obj] = self\r\n   \r\n   items = models[:visit_item].where(:visit_id=>self.id).all\r\n\r\n    patient = models[:patient].find self.patient_id\r\n\r\n   project = models[:project].find self.project_id\r\n   \r\n   period = models[:pl_period].find self.period_id\r\n   period_name = \'\'\r\n   period_name = period.visit if period\r\n\r\n\r\n\r\n   out[:item] = items\r\n   out[:ibom] = {}\r\n   out[:sale_items] = []\r\n   \r\n   \r\n    schedule_items = items.collect{|i| i if i.item_id }.compact\r\n\r\n    unschedule_items = items.collect{|i| i if i.item_type==\'1\' }.compact\r\n    \r\n    reimburse_items = items.collect{|i| i if i.item_type==\'2\' }.compact\r\n    \r\n    pharma_items = items.collect{|i| i if i.item_type==\'3\' }.compact\r\n    \r\n    \r\n    hn = patient.hn\r\n    hn = patient.subject_id if patient.subject_id\r\n   \r\n   labels = [\"#{hn}*#{period_name}\",\"#{hn}*PassT*#{period_name}\",\"#{hn}*ReImb*#{period_name}\",\"#{hn}*Pharm*#{period_name}\"   ]\r\n   list = [schedule_items, unschedule_items , reimburse_items, pharma_items]\r\n    \r\n    buy_items = []\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    list.each_with_index do |section,si|\r\n  \r\n    \r\n    \r\n    sale_items = []\r\n    \r\n        for i in section \r\n       \r\n            if i.status==\'Done\'\r\n                quantity = 1 \r\n                quantity = i.quantity.to_i if i.quantity\r\n                product = models[:pl_product].find i.product_id\r\n                # product = i.product\r\n                \r\n                detail = product.name\r\n                price = product.price \r\n            \r\n                vendor_code = product.vendor_code\r\n                \r\n                vendor_code = i.vendor_code if i.vendor_code and i.vendor_code.size>0\r\n                \r\n                cost = product.cost\r\n                \r\n                if si == 0\r\n                    \r\n                    pl_period_item = models[:pl_period_item].find i.item_id\r\n                #   pl_period_item = i.item\r\n                    \r\n                    if pl_period_item and product.id == pl_period_item.product_id\r\n                        \r\n                        \r\n                        pl_period_product = models[:pl_period_product].find pl_period_item.period_product_id\r\n                        # pl_period_product = pl_period_item.period_product\r\n                        \r\n                        \r\n                        if pl_period_product \r\n                           \r\n                          price = pl_period_product.price.to_i\r\n                          detail = pl_period_product.detail\r\n                            \r\n                        end\r\n                        \r\n                        price = pl_period_item.price.to_i if  pl_period_item.price\r\n                        \r\n                    end\r\n                     \r\n                     \r\n                     \r\n                    \r\n                elsif si == 1\r\n                \r\n                    project_item = models[:project_item].where(:product_id=>product.id).first\r\n                    # project_item =  models[:project_item].where(:product_id=>product.id).first\r\n                    \r\n                    \r\n                    if project_item \r\n                       \r\n                        price = project_item.price.to_i\r\n                        detail = project_item.detail\r\n                    \r\n                        \r\n                    end\r\n                \r\n                elsif si == 2\r\n                    \r\n                    price = i.price.to_i\r\n                    cost = i.cost.to_i\r\n                    \r\n                end\r\n             \r\n                \r\n               \r\n                \r\n               \r\n             \r\n                price = product.price unless product.price\r\n                \r\n                cost = i.cost if i.cost\r\n                price = i.price if i.price\r\n                \r\n                \r\n                \r\n                \r\n                amount = 0\r\n              \r\n                amount = quantity*price if price \r\n          \r\n                \r\n                sale_items << {:code=> product.code, :detail=>detail, :quantity=> quantity, :price=>price, :acc_code=>project.protocol_no, :amount=>amount.to_i }\r\n                \r\n                \r\n                \r\n                bom = models[:pl_product_bom].where(:product_id=>product.id).all\r\n                ibom = models[:visit_item_bom].where(:visit_id=>self.id,:item_id=> i.item_id).all\r\n\r\n        \r\n                 \r\n                \r\n                if vendor_code and vendor_code.size > 0\r\n                    \r\n                    buy_items << {:code=> product.code, :detail=>detail, :quantity=> quantity, :cost=>cost, :vendor_code=>vendor_code, :amount=>quantity*cost }\r\n                    \r\n                    \r\n                elsif bom.size>0 \r\n                \r\n                    option = true\r\n                    for j in bom\r\n                        option = false if j.quantity and j.quantity > 0 \r\n                    end\r\n                    \r\n                    \r\n                    for j in bom\r\n                        \r\n                        buy_product = models[:pl_product].find j.sub_product_id\r\n                        \r\n                        if buy_product\r\n                            \r\n                           q = 1 \r\n                           q = j.quantity  if j.quantity and j.quantity.to_i > 0 \r\n                           \r\n                           vendor_code = buy_product.vendor_code\r\n                           vendor_code = buy_product.vendor_group if vendor_code ==nil or vendor_code.size==0\r\n                           \r\n                            # if option\r\n                               \r\n                            # if i.vendor_code == buy_product.vendor_code\r\n                            cost = buy_product.cost\r\n                            cost = j.cost if j.cost and j.cost != buy_product.cost\r\n                            cost = cost.to_i\r\n                            \r\n                            buy_items << {:code=> buy_product.code, :detail=>buy_product.name, :quantity=> q, :cost=>cost, :amount=>q * cost, :vendor_code=>vendor_code }\r\n                           \r\n                        #     end\r\n                           \r\n                        #   else\r\n                       \r\n                        #     buy_items << {:code=> buy_product.code, :detail=>buy_product.name, :quantity=> q, :cost=>buy_product.cost, :amount=>q * buy_product.cost.to_i, :vendor_code=>vendor_code }\r\n                           \r\n                       \r\n                        #   end\r\n                           \r\n                        #   if option\r\n                               \r\n                        #     if i.vendor_code == buy_product.vendor_code\r\n                           \r\n                        #     buy_items << {:code=> buy_product.code, :detail=>buy_product.name, :quantity=> q, :cost=>buy_product.cost, :amount=>q * buy_product.cost.to_i, :vendor_code=>vendor_code }\r\n                           \r\n                        #     end\r\n                           \r\n                        #   else\r\n                       \r\n                        #     buy_items << {:code=> buy_product.code, :detail=>buy_product.name, :quantity=> q, :cost=>buy_product.cost, :amount=>q * buy_product.cost.to_i, :vendor_code=>vendor_code }\r\n                           \r\n                       \r\n                        #   end\r\n                           \r\n                            \r\n                        end\r\n                    \r\n                    \r\n                    end\r\n                \r\n                elsif ibom.size > 0 \r\n                    \r\n                    out[:ibom][i.id] = ibom\r\n                   \r\n                    \r\n                    for ib in ibom\r\n                    buy_product = models[:pl_product].find ib.product_id\r\n                        \r\n                    if buy_product\r\n                       q = 1  \r\n                       vendor_code = ib.vendor_code\r\n                       \r\n                       buy_items << {:code=> buy_product.code, :detail=>buy_product.name, :quantity=> q, :cost=>ib.cost, :amount=>q * ib.cost.to_i, :vendor_code=>vendor_code }\r\n                         \r\n                    end\r\n                    end\r\n                \r\n                end\r\n                \r\n            \r\n            end\r\n        \r\n        end\r\n\r\n    total = 0 \r\n    \r\n    for i in sale_items\r\n    \r\n        if true\r\n    \r\n    \r\n            total += i[:amount]\r\n            \r\n        \r\n        end\r\n    \r\n    end\r\n    \r\n    oh = 0 \r\n    if total > 0 and project.oh==\'true\'\r\n        \r\n        \r\n        oh = (total *0.2).to_i\r\n        \r\n        sale_items << {:code=> \'OH\', :detail=>\'Over Head MDCU 20%\', :quantity=> 1, :price=>oh, :acc_code=>project.protocol_no, :amount=>oh }\r\n        buy_items << {:code=> \'OH\' , :detail=>\'Over Head MDCU 20%\', :quantity=> 1, :cost=>oh, :vendor_code=>\'MDCU\', :amount=>oh }\r\n\r\n\r\n\r\n    end\r\n    \r\n    \r\n    out[:sale_items] << {:id=>labels[si], :items=>sale_items, :total=>total+oh, :oh=>oh } if sale_items.size > 0 \r\n  \r\n    \r\nend\r\n   \r\n   out[:buy_items] = []\r\n   \r\n   map = {}\r\n   \r\n   buy_items.each do |i|\r\n      \r\n      map[i[:vendor_code]] = {:id=> i[:vendor_code], :items=>[], :total=>0} unless  map[i[:vendor_code]]\r\n      map[i[:vendor_code]][:items] << i\r\n      map[i[:vendor_code]][:total] += i[:amount]\r\n       \r\n       \r\n   end\r\n   \r\n  out[:buy_items] = map.values\r\n   \r\n   \r\n   \r\n   return out\r\n    \r\n    \r\nend'),(865,NULL,443,'visit_item','\r\n	key :visit_id, ObjectId\r\n\r\n	key :product_id, ObjectId\r\n\r\n	key :item_id, ObjectId\r\n\r\n	key :detail, String\r\n\r\n	key :note, String\r\n\r\n	key :status, String\r\n\r\n	key :done, String\r\n\r\n	key :item_type, String\r\n\r\n	key :price, Float\r\n\r\n	key :cost, Float\r\n\r\n	key :vendor_code, String\r\n\n	key :quantity, Integer\n\n	key :edited_by, String\n\n	key :project_item_id, ObjectId\n','2018-06-06 14:39:48','2019-03-11 17:21:37','# one :product, :class=>Schema::PlProduct, :foreign_key=>\'product_id\'\r\n# one :item, :class=>Schema::PlPeriodItem, :foreign_key=>\'item_id\'\r\n\r\n'),(866,NULL,462,'member','\n	key :name, String\n\n	key :member_no, String\n\n	key :phone, String\n\n	key :personal_id, String\n','2018-06-08 04:13:32','2018-06-08 04:19:46',NULL),(867,NULL,462,'account','\n	key :date, Date\n\n	key :status, String\n\n	key :price, Integer\n\n	key :weight, Float\n\n	key :type, String\n','2018-06-08 06:28:04','2018-06-08 06:39:03',NULL),(868,NULL,76,'certificate','\n	key :name, String\n\n	key :period, String\n\n	key :date_of_issue, Date\n\n	key :document, ObjectId\n\n	key :number, String\n\n	key :provider_id, ObjectId\n','2018-07-02 05:49:23','2018-07-09 02:15:09',NULL),(869,NULL,443,'transaction','\n	key :reftype, String\n\n	key :qccorp, String\n\n	key :qcbranch, String\n\n	key :qcsect, String\n\n	key :qcjob, String\n\n	key :stat, String\n\n	key :date, Date\n\n	key :recdate, Date\n\n	key :duedate, Date\n\n	key :qcbook, String\n\n	key :code, String\n\n	key :refno, String\n\n	key :discamt1, Float\n\n	key :hdiscstr, Float\n\n	key :amt, Float\n\n	key :vatisout, String\n\n	key :vattype, String\n\n	key :vatamt, Float\n\n	key :qccoor, String\